//! Built-in, zero-config deterministic text embedder.
//!
//! [`local_embed`] turns arbitrary text into a fixed-dimensional, L2-normalised
//! `f32` vector using the *feature-hashing trick* (a.k.a. the "hashing
//! vectoriser"): word unigrams and intra-word character trigrams are hashed
//! into a fixed number of buckets with a signed contribution, then the whole
//! accumulator is L2-normalised so that cosine similarity is comparable across
//! documents of different lengths.
//!
//! This is **not** a neural model — it captures lexical / sub-word overlap, not
//! deep semantics. Its job is to make the `semantic_text` field type work
//! end-to-end with **zero external dependencies** (offline, no API key), giving
//! a sensible out-of-the-box experience: paraphrases that share vocabulary rank
//! above unrelated text. When a real
//! [`crate::embed::EmbeddingProxy`] is configured the engine uses that instead
//! for production-quality embeddings — the *same* embedder is always used at
//! ingest and query time so the vectors are comparable.
//!
//! Key properties:
//! * **Deterministic** — identical input always yields the identical vector,
//!   across processes and restarts (no learned weights, no RNG).
//! * **Configurable dimensionality** — `dims` (default [`DEFAULT_DIMS`]).
//! * **Comparable** — L2-normalised, so cosine similarity is well-behaved.

/// Default embedding dimensionality for the built-in embedder.
///
/// 384 mirrors the popular `all-MiniLM-L6-v2` output size, so switching from
/// the built-in embedder to a real proxy of that width needs no mapping change.
pub const DEFAULT_DIMS: usize = 384;

/// 64-bit FNV-1a hash — small, fast, stable across platforms.
#[inline]
fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in bytes {
        h ^= b as u64;
        h = h.wrapping_mul(0x00000100000001b3);
    }
    h
}

/// Accumulate one hashed feature into `acc` with a signed weight. The low bits
/// pick the bucket; one high bit picks the sign (signed hashing reduces the
/// collision bias of unsigned feature hashing).
#[inline]
fn add_feature(acc: &mut [f32], token: &[u8], weight: f32) {
    let dims = acc.len();
    if dims == 0 {
        return;
    }
    let h = fnv1a64(token);
    let idx = (h % dims as u64) as usize;
    let sign = if (h >> 63) & 1 == 0 { 1.0 } else { -1.0 };
    acc[idx] += weight * sign;
}

/// Embed `text` into a deterministic, L2-normalised vector of length `dims`.
///
/// Empty / whitespace-only text (or `dims == 0`) yields an all-zero vector;
/// cosine similarity against a zero vector is defined as 0 by
/// `compute_vector_similarity`, so this degrades gracefully rather than
/// panicking.
pub fn local_embed(text: &str, dims: usize) -> Vec<f32> {
    let mut acc = vec![0.0f32; dims];
    if dims == 0 {
        return acc;
    }

    let lower = text.to_lowercase();
    for token in lower
        .split(|c: char| !c.is_alphanumeric())
        .filter(|t| !t.is_empty())
    {
        // Whole-word unigram — the dominant lexical signal.
        add_feature(&mut acc, token.as_bytes(), 1.0);

        // Intra-word character trigrams (padded so word boundaries matter),
        // at a lower weight. These give partial credit to morphological
        // variants (e.g. "run" / "running" share the "run" shingle), which
        // nudges the embedding a little past exact-keyword matching.
        let padded: Vec<char> = std::iter::once('#')
            .chain(token.chars())
            .chain(std::iter::once('#'))
            .collect();
        if padded.len() >= 3 {
            for w in padded.windows(3) {
                let mut buf = [0u8; 12];
                let mut n = 0;
                for &ch in w {
                    let s = ch.len_utf8();
                    ch.encode_utf8(&mut buf[n..]);
                    n += s;
                }
                add_feature(&mut acc, &buf[..n], 0.35);
            }
        }
    }

    // L2-normalise so cosine similarity is length-invariant.
    let norm: f32 = acc.iter().map(|x| x * x).sum::<f32>().sqrt();
    if norm > 0.0 {
        for x in acc.iter_mut() {
            *x /= norm;
        }
    }
    acc
}

#[cfg(test)]
mod tests {
    use super::*;

    fn dot(a: &[f32], b: &[f32]) -> f32 {
        a.iter().zip(b).map(|(x, y)| x * y).sum()
    }

    #[test]
    fn dims_and_determinism() {
        let a = local_embed("the quick brown fox", 128);
        let b = local_embed("the quick brown fox", 128);
        assert_eq!(a.len(), 128);
        assert_eq!(a, b, "embedding must be deterministic");
    }

    /// Deliberately independent of [`fnv1a64`] so that changing the embedder's
    /// hash cannot silently move the checksum with it.
    fn djb2_over_bits(v: &[f32]) -> u64 {
        let mut h: u64 = 5381;
        for x in v {
            for byte in x.to_le_bytes() {
                h = h.wrapping_mul(33) ^ byte as u64;
            }
        }
        h
    }

    /// GOLDEN VECTOR — do not "fix" this by re-recording the constants.
    ///
    /// `lexical` is the default backend and the one most deployments run, and
    /// `GET /v1/embedding/identity` reports it as `resumable: true`, which
    /// tells `xerj autoindex` it may resume an existing semantic run straight
    /// across a restart. That identity is derived from the literal string
    /// `lexical-feature-hash.v1;dimensions=384`, so nothing in it is computed
    /// from this function: changing the tokenizer, the trigram padding, the
    /// feature weights, the hash seed, or the normalisation would move every
    /// vector into a new space while `identity_sha256` stayed byte-identical,
    /// and autoindex would resume across the change and mix the two spaces —
    /// exactly the failure the identity endpoint exists to prevent.
    ///
    /// If this test fails, the lexical vector space changed. The fix is to
    /// bump `lexical-feature-hash.v1` to `.v2` in
    /// `xerj-engine/src/index.rs::embedding_execution_identity` (which changes
    /// `identity_sha256` and so makes resumes across the change fail closed),
    /// and only then re-record the constants below.
    #[test]
    fn lexical_vector_space_is_frozen() {
        let v = local_embed(
            "quarterly revenue increased in the london office",
            DEFAULT_DIMS,
        );
        assert_eq!(v.len(), DEFAULT_DIMS);

        // Whole-vector fingerprint: catches any change to any bucket.
        assert_eq!(
            djb2_over_bits(&v),
            14262738046721457820,
            "the lexical vector space changed; see this test's doc comment"
        );

        // A few exact buckets, so a failure says *what* moved rather than just
        // that a checksum differs. Bit-exact: these are IEEE-754 f32 results
        // of a fixed sequence of adds and one divide, so they are reproducible
        // across platforms.
        for (index, expected) in [
            (0usize, 0.09425097f32),
            (43, 0.09425097),
            (120, -0.09425097),
            (123, 0.26928848),
        ] {
            assert_eq!(
                v[index], expected,
                "bucket {index} moved: {} != {expected}",
                v[index]
            );
        }
    }

    #[test]
    fn l2_normalised() {
        let v = local_embed("hello world of vectors", DEFAULT_DIMS);
        let norm: f32 = v.iter().map(|x| x * x).sum::<f32>().sqrt();
        assert!((norm - 1.0).abs() < 1e-4, "expected unit norm, got {norm}");
    }

    #[test]
    fn empty_text_is_zero_vector() {
        let v = local_embed("   ", 64);
        assert_eq!(v.len(), 64);
        assert!(v.iter().all(|x| *x == 0.0));
    }

    #[test]
    fn zero_dims_is_empty() {
        assert!(local_embed("anything", 0).is_empty());
    }

    #[test]
    fn paraphrase_ranks_above_unrelated() {
        // A paraphrase sharing vocabulary must be closer (higher cosine) than
        // a topically-unrelated sentence — the property `semantic_text` relies
        // on for kNN retrieval.
        let dims = DEFAULT_DIMS;
        let doc_relevant = local_embed("a hungry dog chased the ball across the green park", dims);
        let doc_unrelated = local_embed(
            "investors sold technology shares amid rising interest rates",
            dims,
        );
        let query = local_embed("a dog ran after a ball in the park", dims);

        let sim_relevant = dot(&query, &doc_relevant);
        let sim_unrelated = dot(&query, &doc_unrelated);
        assert!(
            sim_relevant > sim_unrelated,
            "relevant {sim_relevant} should beat unrelated {sim_unrelated}"
        );
    }
}

//! Built-in neural sentence embedder — pure-Rust BERT inference via `candle`.
//!
//! This is XERJ's optional *real* semantic embedder. It loads a
//! sentence-transformers BERT model (default `all-MiniLM-L6-v2`, 384-dim)
//! and produces genuine neural embeddings, in-process, with no Python and
//! no external service. It complements the two existing backends:
//!
//!   * [`crate::local::local_embed`] — zero-dependency lexical feature-hash
//!     (the honest default; fast, deterministic, but *not* semantic).
//!   * [`crate::embed::EmbeddingProxy`] — any external OpenAI-compatible
//!     `/v1/embeddings` provider (bring-your-own model).
//!
//! Model files are resolved when the embedder is loaded. The server does
//! that at startup when neural is requested (#1840): a blocked Hub or a
//! missing local directory refuses the process once, instead of failing
//! every later ingest. Air-gapped deployments point
//! [`NeuralConfig::local_dir`] at a directory holding `config.json`,
//! `tokenizer.json`, and the safetensors weights. A HuggingFace mirror is
//! `HF_ENDPOINT` (or [`NeuralConfig::hub_endpoint`]).
//!
//! Compiled only under the `neural` cargo feature.

use anyhow::{anyhow, Context, Result};
use candle_core::{DType, Device, Tensor};
use candle_nn::VarBuilder;
use candle_transformers::models::bert::{BertModel, Config, DTYPE};
use sha2::{Digest, Sha256};
use std::path::{Path, PathBuf};
use tokenizers::{Encoding, Tokenizer, TruncationParams};

use crate::microbatch::group_by_padded_cost;

/// Default sentence encoder: 6-layer MiniLM, 384-dim, ~90 MB.
pub const DEFAULT_MODEL_ID: &str = "sentence-transformers/all-MiniLM-L6-v2";

/// Cap on tokens per passage. MiniLM's positional table is 512; passages are
/// already chunked upstream, so this is a safety clamp, not the usual path.
///
/// Public because it is part of this backend's *output* contract: truncating
/// at a different length gives a different vector for a long passage, so it
/// travels in the execution identity ([`asset_identity`]'s callers).
pub const MAX_TOKENS: usize = 512;

/// Rows in one forward pass. Measured on CPU with MiniLM
/// (`examples/neural_throughput.rs`): throughput climbs steeply to 64 rows and
/// then flattens and falls back. Two runs of that sweep on this shared box
/// disagree on absolute throughput — 32/64/128/256 rows read 139/155/151/132
/// passages/s in one and 179.1/199.9/198.7/166.2 in the other (the second is
/// the run published with this change) — but agree on where the knee is. 64 is
/// also what the ONNX backend uses.
const MAX_BATCH_ROWS: usize = 64;

/// Ceiling on `rows × padded_sequence_length` for one forward pass. Bounds the
/// activation memory a single call can allocate (BERT's attention tensor grows
/// with `rows × heads × seq²`) and stops a long passage from being batched with
/// many others at its own length. 4096 leaves a full 64-row batch of ~64-token
/// passages intact; on real ingest chunks (512 *characters*, so roughly
/// 110–130 tokens of prose and up to ~400 for dense code) it is usually the
/// budget rather than the row cap that binds — about 32 rows for prose, ~9 for
/// code.
const PADDED_TOKEN_BUDGET: usize = 4_096;

/// BERT's `[PAD]` id. Padded positions carry attention-mask 0, so the id only
/// has to be a valid embedding-table index; 0 is what the tokenizer's own
/// `PaddingParams::default()` used before batches were planned here.
const PAD_TOKEN_ID: u32 = 0;

/// What one [`NeuralEmbedder::embed_blocking_stats`] call actually pushed
/// through the model. `padded_token_slots` equals `real_tokens` exactly when
/// every batch is length-homogeneous; the ratio between them is the padding
/// waste, which is what length-aware batching exists to keep near 1.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct BatchStats {
    /// Forward passes run for this call.
    pub inference_calls: usize,
    /// `rows × padded_sequence_length`, summed over those forward passes.
    pub padded_token_slots: usize,
    /// Tokens the input actually contained, after truncation.
    pub real_tokens: usize,
}

/// How to obtain the model weights.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct NeuralConfig {
    /// HuggingFace model id (e.g. `sentence-transformers/all-MiniLM-L6-v2`).
    pub model_id: String,
    /// Override the HuggingFace cache directory. `None` uses the default
    /// (`~/.cache/huggingface`).
    pub cache_dir: Option<PathBuf>,
    /// Air-gapped: load `config.json` / `tokenizer.json` / weights from this
    /// directory instead of downloading. Takes precedence over the hub.
    pub local_dir: Option<PathBuf>,
    /// Override the HuggingFace Hub base URL. `None` uses `HF_ENDPOINT` when
    /// that variable is set, otherwise `https://huggingface.co`. Tests point
    /// this at a closed local port so a blocked download never touches the
    /// network. `ApiBuilder::new()` does not read `HF_ENDPOINT` itself
    /// (hf-hub 0.4 only does that in `from_env`).
    pub hub_endpoint: Option<String>,
}

impl Default for NeuralConfig {
    fn default() -> Self {
        Self {
            model_id: DEFAULT_MODEL_ID.to_string(),
            cache_dir: None,
            local_dir: None,
            hub_endpoint: None,
        }
    }
}

/// A loaded BERT sentence embedder. Cheap to share behind an `Arc`; `embed`
/// takes `&self` and is safe to call from many threads.
pub struct NeuralEmbedder {
    model: BertModel,
    tokenizer: Tokenizer,
    device: Device,
    dims: usize,
}

impl NeuralEmbedder {
    /// Output dimensionality (hidden size of the loaded model, e.g. 384).
    pub fn dims(&self) -> usize {
        self.dims
    }

    /// Load the model, downloading from the HuggingFace Hub when it is not
    /// already cached (unless [`NeuralConfig::local_dir`] is set).
    /// **Blocking** — the server runs this at startup, off the async
    /// executor (see [`crate::Embedder::preload_neural`]).
    pub fn load(cfg: &NeuralConfig) -> Result<Self> {
        let (config_path, tokenizer_path, weights_path) = match &cfg.local_dir {
            Some(dir) => resolve_local(dir)?,
            None => resolve_from_hub(cfg)?,
        };

        let config_json = std::fs::read_to_string(&config_path)
            .with_context(|| format!("read model config {}", config_path.display()))?;
        let config: Config = serde_json::from_str(&config_json)
            .with_context(|| format!("parse model config {}", config_path.display()))?;
        let dims = config.hidden_size;

        let mut tokenizer = Tokenizer::from_file(&tokenizer_path)
            .map_err(|e| anyhow!("load tokenizer {}: {e}", tokenizer_path.display()))?;
        // Tokenize WITHOUT padding. Padding to the longest member of whatever
        // the caller handed us is exactly the cost this backend used to pay:
        // one long chunk in a window of short lines charged every short line
        // the long chunk's length. `embed_blocking` groups rows by length and
        // pads each group to its own longest row instead (see
        // [`crate::microbatch`]), so padding is applied here, per batch.
        tokenizer.with_padding(None);
        // Clamp over-long passages to the model's positional limit.
        tokenizer
            .with_truncation(Some(TruncationParams {
                max_length: MAX_TOKENS,
                ..Default::default()
            }))
            .map_err(|e| anyhow!("configure tokenizer truncation: {e}"))?;

        let device = Device::Cpu;
        // Safetensors is memory-mapped; the file must outlive the model, which
        // it does (candle copies tensors into the VarBuilder-backed model).
        let vb = unsafe {
            VarBuilder::from_mmaped_safetensors(std::slice::from_ref(&weights_path), DTYPE, &device)
                .with_context(|| format!("map weights {}", weights_path.display()))?
        };
        let model = BertModel::load(vb, &config).map_err(|e| anyhow!("load BERT model: {e}"))?;

        Ok(Self {
            model,
            tokenizer,
            device,
            dims,
        })
    }

    /// Embed a batch of passages into L2-normalized sentence vectors using
    /// attention-masked mean pooling (the sentence-transformers convention).
    /// **Blocking / CPU-bound** — call via `spawn_blocking`.
    ///
    /// Output order matches input order regardless of how the passages were
    /// grouped internally.
    pub fn embed_blocking(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        self.embed_blocking_stats(texts).map(|(vectors, _)| vectors)
    }

    /// Tokenized length of each passage, after truncation to [`MAX_TOKENS`].
    ///
    /// The cost of one forward pass is `rows × padded_sequence_length`, so
    /// these lengths are what any batching decision has to be made on; the
    /// throughput harness uses them to price a plan without running it.
    pub fn token_lengths(&self, texts: &[String]) -> Result<Vec<usize>> {
        Ok(self
            .tokenizer
            .encode_batch(texts.to_vec(), true)
            .map_err(|e| anyhow!("tokenize batch: {e}"))?
            .iter()
            .map(|enc| enc.get_ids().len().min(MAX_TOKENS))
            .collect())
    }

    /// [`Self::embed_blocking`], additionally reporting how much work the call
    /// actually pushed through the model. Used by the throughput harness and
    /// by the padding regression test; behaviour is otherwise identical.
    pub fn embed_blocking_stats(&self, texts: &[String]) -> Result<(Vec<Vec<f32>>, BatchStats)> {
        if texts.is_empty() {
            return Ok((vec![], BatchStats::default()));
        }

        let encodings = self
            .tokenizer
            .encode_batch(texts.to_vec(), true)
            .map_err(|e| anyhow!("tokenize batch: {e}"))?;
        // The tokenizer truncates at MAX_TOKENS and no longer pads, so these
        // are the real per-passage lengths.
        let lengths = encodings
            .iter()
            .map(|enc| enc.get_ids().len().min(MAX_TOKENS))
            .collect::<Vec<_>>();

        let mut stats = BatchStats {
            real_tokens: lengths.iter().sum(),
            ..BatchStats::default()
        };
        let mut ordered = vec![Vec::new(); texts.len()];
        for rows in group_by_padded_cost(&lengths, MAX_BATCH_ROWS, PADDED_TOKEN_BUDGET) {
            let seq_len = rows.iter().map(|&i| lengths[i]).max().unwrap_or(0);
            if seq_len == 0 {
                // All-empty group — zero vectors of the right width.
                for i in rows {
                    ordered[i] = vec![0.0; self.dims];
                }
                continue;
            }
            stats.inference_calls += 1;
            stats.padded_token_slots += rows.len() * seq_len;
            let vectors = self.forward_padded(&encodings, &rows, &lengths, seq_len)?;
            for (i, vector) in rows.into_iter().zip(vectors) {
                ordered[i] = vector;
            }
        }
        Ok((ordered, stats))
    }

    /// Run one rectangular forward pass over `rows`, right-padding each row to
    /// `seq_len` with [`PAD_TOKEN_ID`] and attention-mask 0. Returns vectors in
    /// `rows` order.
    fn forward_padded(
        &self,
        encodings: &[Encoding],
        rows: &[usize],
        lengths: &[usize],
        seq_len: usize,
    ) -> Result<Vec<Vec<f32>>> {
        let batch = rows.len();
        let mut ids: Vec<u32> = Vec::with_capacity(batch * seq_len);
        let mut mask: Vec<u32> = Vec::with_capacity(batch * seq_len);
        for &row in rows {
            let len = lengths[row];
            ids.extend_from_slice(&encodings[row].get_ids()[..len]);
            ids.resize(ids.len() + (seq_len - len), PAD_TOKEN_ID);
            mask.extend_from_slice(&encodings[row].get_attention_mask()[..len]);
            mask.resize(mask.len() + (seq_len - len), 0);
        }

        let input_ids = Tensor::from_vec(ids, (batch, seq_len), &self.device)
            .map_err(|e| anyhow!("build input_ids tensor: {e}"))?;
        let attention_mask = Tensor::from_vec(mask, (batch, seq_len), &self.device)
            .map_err(|e| anyhow!("build attention_mask tensor: {e}"))?;
        let token_type_ids = input_ids
            .zeros_like()
            .map_err(|e| anyhow!("build token_type_ids: {e}"))?;

        // (batch, seq_len, hidden)
        let hidden = self
            .model
            .forward(&input_ids, &token_type_ids, Some(&attention_mask))
            .map_err(|e| anyhow!("bert forward: {e}"))?;

        // Attention-masked mean pooling: sum(token * mask) / sum(mask).
        let mask_f = attention_mask
            .to_dtype(DType::F32)
            .and_then(|m| m.unsqueeze(2)) // (batch, seq_len, 1)
            .map_err(|e| anyhow!("mask to f32: {e}"))?;
        let summed = hidden
            .broadcast_mul(&mask_f)
            .and_then(|h| h.sum(1)) // (batch, hidden)
            .map_err(|e| anyhow!("masked sum: {e}"))?;
        let counts = mask_f
            .sum(1) // (batch, 1)
            .and_then(|c| c.clamp(1e-9, f32::INFINITY))
            .map_err(|e| anyhow!("mask counts: {e}"))?;
        let mean = summed
            .broadcast_div(&counts)
            .map_err(|e| anyhow!("mean pool: {e}"))?;

        // L2 normalize each row.
        let norm = mean
            .sqr()
            .and_then(|s| s.sum_keepdim(1))
            .and_then(|s| s.sqrt())
            .and_then(|n| n.clamp(1e-12, f32::INFINITY))
            .map_err(|e| anyhow!("l2 norm: {e}"))?;
        let normed = mean
            .broadcast_div(&norm)
            .map_err(|e| anyhow!("normalize: {e}"))?;

        normed
            .to_vec2::<f32>()
            .map_err(|e| anyhow!("read embeddings: {e}"))
    }
}

/// Passages in one ingest-rate probe. 32 rows of 512 ASCII characters fit one
/// length-aware forward pass under [`PADDED_TOKEN_BUDGET`] for prose-like
/// text, which is the shape `semantic_text` chunks are cut to.
pub const INGEST_PROBE_PASSAGES: usize = 32;

/// Characters (and bytes — the probe is ASCII) in each probe passage.
pub const INGEST_PROBE_CHARS: usize = 512;

/// Time one batch of ingest-shaped passages.
///
/// One untimed warmup passage runs first, so the timed call is not the
/// process's first Candle forward. Returns `None` when the call fails or the
/// clock reports 0 ms — that is "not measured", not a rate of infinity.
/// The result is not part of [`asset_identity`]: batching and wall time do
/// not change the vectors.
pub fn measure_ingest_probe(
    embedder: &NeuralEmbedder,
) -> Option<xerj_common::config::NeuralIngestProbe> {
    let passage = ingest_probe_passage();
    debug_assert_eq!(passage.len(), INGEST_PROBE_CHARS);
    let warmup = embedder
        .embed_blocking(std::slice::from_ref(&passage))
        .ok()?;
    if warmup.len() != 1 {
        return None;
    }
    let texts = vec![passage; INGEST_PROBE_PASSAGES];
    let started = std::time::Instant::now();
    let vectors = embedder.embed_blocking(&texts).ok()?;
    let millis = u64::try_from(started.elapsed().as_millis()).ok()?;
    if millis == 0 || vectors.len() != INGEST_PROBE_PASSAGES {
        return None;
    }
    Some(xerj_common::config::NeuralIngestProbe {
        bytes: (INGEST_PROBE_CHARS * INGEST_PROBE_PASSAGES) as u64,
        passages: INGEST_PROBE_PASSAGES as u32,
        millis,
    })
}

fn ingest_probe_passage() -> String {
    let unit = "fn embed_passage(text: &str) -> Vec<f32> { hash_tokens(text) } ";
    let mut passage = String::with_capacity(INGEST_PROBE_CHARS);
    while passage.len() < INGEST_PROBE_CHARS {
        passage.push_str(unit);
    }
    passage.truncate(INGEST_PROBE_CHARS);
    passage
}

/// How [`NeuralEmbedder::embed_blocking`] turns per-token hidden states into
/// one vector. Part of the identity: the same weights pooled differently are a
/// different embedder.
pub const POOLING: &str = "attention-mask-mean+l2-normalize";

/// Content address of the three files a [`NeuralEmbedder`] is built from.
///
/// A *configured model id* cannot identify an embedder: `all-MiniLM-L6-v2`
/// names a mutable hub pointer, and [`NeuralConfig::local_dir`] names a
/// directory whose contents can be swapped underneath a running server. The
/// bytes can, which is how Lucene decides whether a replicated file may be
/// reused — `ReplicaNode.fileIsIdentical` compares length + header id +
/// checksum rather than trusting the name
/// (`lucene/replicator/src/java/org/apache/lucene/replicator/nrt/ReplicaNode.java:855`),
/// on top of `CodecUtil.checkIndexHeaderID` / `retrieveChecksum`
/// (`lucene/core/src/java/org/apache/lucene/codecs/CodecUtil.java:364`, `:526`).
/// APPROACH ONLY — nothing is copied; the digest below is our own.
///
/// # What is deliberately NOT in here
///
/// Only inputs that can move a vector belong in an execution identity; an
/// identity that moves without the vectors moving is exactly the false
/// "identity changed" this replaces (#487). So these are excluded on purpose:
///
///   * **the model id and the resolved file paths** — two hosts holding the
///     same bytes under different names or directories must be able to resume
///     each other's generation, and a path would also leak into the wire
///     identity, which is documented as privacy-safe;
///   * **`MAX_BATCH_ROWS` / `PADDED_TOKEN_BUDGET`** ([`crate::microbatch`]) —
///     they decide how rows are grouped into forward passes, not what any row
///     computes. Padded positions carry attention-mask 0 and are dropped by
///     the masked mean, so regrouping the same passages returns the same
///     vectors. #366 retuned this batching with no vector change, and an
///     identity that folded it in would have failed every resume across that
///     release for nothing;
///   * **thread count, device, host CPU features** — same reason, and they are
///     not stable across the machines that must agree on one corpus.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetIdentity {
    /// sha256 of `model.safetensors` — the weights.
    pub model_sha256: String,
    /// sha256 of `tokenizer.json` — the vocabulary and pre-tokenizer.
    pub tokenizer_sha256: String,
    /// sha256 of `config.json`. Hashed whole rather than field-by-field: it
    /// parameterises the architecture candle instantiates, and enumerating the
    /// fields that matter would silently miss any new one. The cost is that a
    /// whitespace-only edit to a hand-managed `local_model_dir` copy moves the
    /// identity even though the vectors do not — over-strict (fail-closed) on
    /// a file that is byte-stable when it comes from the hub cache.
    pub config_sha256: String,
    /// `hidden_size` from the resolved `config.json` — the width of every
    /// vector this embedder produces, and the same value
    /// [`NeuralEmbedder::dims`] reports, read here without loading the model.
    pub dimensions: usize,
}

/// Why a neural model could not be content-addressed, split in two on purpose.
///
/// `EmbeddingExecutionIdentity` is documented as never carrying model paths or
/// model names across the API boundary, and a resolution failure is precisely
/// where a filesystem path would otherwise escape into
/// `non_resumable_reason` — the failure text is the one part of the identity
/// that is not a digest. So the caller reports [`Self::asset`] on the wire and
/// logs [`Self::detail`] locally.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetIdentityError {
    /// What could not be read, as a bare asset name. Contains no path, no
    /// directory and no model id, so it is safe to return to a remote client.
    pub asset: &'static str,
    /// The same failure with everything useful for an operator in it —
    /// resolved paths, the configured model id, the underlying io error. For
    /// this server's own log, never for a response body.
    pub detail: String,
}

impl AssetIdentityError {
    fn new(asset: &'static str, detail: impl std::fmt::Display) -> Self {
        Self {
            asset,
            detail: detail.to_string(),
        }
    }
}

impl std::fmt::Display for AssetIdentityError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.detail)
    }
}

impl std::error::Error for AssetIdentityError {}

/// Content-address the assets `cfg` resolves to.
///
/// Resolution takes exactly the path [`NeuralEmbedder::load`] takes (local
/// directory when set, hub cache otherwise), so a server that is able to embed
/// is always able to state what it embeds with, and one that cannot resolve its
/// assets reports *which asset* failed instead of a fabricated identity.
///
/// `ApiRepo::get` consults the local cache before the network (hf-hub 0.4
/// `api/sync.rs:709`), so a warm cache resolves offline; a cold one downloads
/// the same ~90 MB the first embed would have downloaded anyway.
///
/// Memoised per [`NeuralConfig`] for the process lifetime — the digest reads
/// ~90 MB and the caller is a request path (measured on this box: 71–77 ms on
/// the first call for MiniLM, 0 ms after). That memo is also what makes the
/// identity *stable within a process*: assets swapped under a running server
/// are not noticed until restart, which is the same bargain the ONNX arm makes
/// with its `runtime_onnx_assets` cell.
pub fn asset_identity(
    cfg: &NeuralConfig,
) -> std::result::Result<AssetIdentity, AssetIdentityError> {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};

    type Memo = HashMap<NeuralConfig, std::result::Result<AssetIdentity, AssetIdentityError>>;
    static IDENTITIES: OnceLock<Mutex<Memo>> = OnceLock::new();

    let identities = IDENTITIES.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(cached) = identities
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .get(cfg)
    {
        return cached.clone();
    }
    // Computed outside the lock: hashing is seconds of I/O on a cold cache and
    // must not serialise every other configuration behind it. Two threads
    // racing the same config compute the same answer, so the double insert is
    // harmless.
    let computed = compute_asset_identity(cfg);
    identities
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .insert(cfg.clone(), computed.clone());
    computed
}

fn compute_asset_identity(
    cfg: &NeuralConfig,
) -> std::result::Result<AssetIdentity, AssetIdentityError> {
    let (config_path, tokenizer_path, weights_path) = match &cfg.local_dir {
        Some(dir) => resolve_local_assets(dir)?,
        None => resolve_from_hub(cfg)
            // The hub error names the model id and the cache path; neither may
            // reach a client, so only the generic label travels.
            .map_err(|e| AssetIdentityError::new("the model download", format!("{e:#}")))?,
    };
    let config_json = std::fs::read(&config_path).map_err(|e| {
        AssetIdentityError::new(
            "config.json",
            format!("read model config {}: {e}", config_path.display()),
        )
    })?;
    let config: Config = serde_json::from_slice(&config_json).map_err(|e| {
        AssetIdentityError::new(
            "config.json",
            format!("parse model config {}: {e}", config_path.display()),
        )
    })?;
    Ok(AssetIdentity {
        model_sha256: file_sha256(&weights_path, "model.safetensors")?,
        tokenizer_sha256: file_sha256(&tokenizer_path, "tokenizer.json")?,
        config_sha256: format!("{:x}", Sha256::digest(&config_json)),
        dimensions: config.hidden_size,
    })
}

/// Streamed sha256 — the weights are ~90 MB and must not be held in memory
/// just to be digested.
fn file_sha256(
    path: &Path,
    asset: &'static str,
) -> std::result::Result<String, AssetIdentityError> {
    use std::io::Read;

    let fail = |e: std::io::Error| {
        AssetIdentityError::new(
            asset,
            format!("read embedding asset {}: {e}", path.display()),
        )
    };
    let mut file = std::fs::File::open(path).map_err(fail)?;
    let mut hasher = Sha256::new();
    let mut buf = vec![0u8; 1 << 20];
    loop {
        let read = file.read(&mut buf).map_err(fail)?;
        if read == 0 {
            break;
        }
        hasher.update(&buf[..read]);
    }
    Ok(format!("{:x}", hasher.finalize()))
}

/// Resolve the three model files from a local directory (air-gapped).
fn resolve_local(dir: &Path) -> Result<(PathBuf, PathBuf, PathBuf)> {
    // `load` wants the operator-facing text, paths and all; only the identity
    // endpoint has to keep the path off the wire.
    resolve_local_assets(dir).map_err(|e| anyhow!("{}", e.detail))
}

/// [`resolve_local`], keeping the failing asset separable from the path it was
/// looked for at — see [`AssetIdentityError`].
fn resolve_local_assets(
    dir: &Path,
) -> std::result::Result<(PathBuf, PathBuf, PathBuf), AssetIdentityError> {
    let config = dir.join("config.json");
    let tokenizer = dir.join("tokenizer.json");
    let weights = find_local_weights(dir)?;
    for (asset, p) in [("config.json", &config), ("tokenizer.json", &tokenizer)] {
        if !p.exists() {
            return Err(AssetIdentityError::new(
                asset,
                format!("local model dir {} is missing {asset}", dir.display()),
            ));
        }
    }
    Ok((config, tokenizer, weights))
}

/// Prefer `model.safetensors`; candle cannot read PyTorch `.bin` weights.
fn find_local_weights(dir: &Path) -> std::result::Result<PathBuf, AssetIdentityError> {
    let st = dir.join("model.safetensors");
    if st.exists() {
        return Ok(st);
    }
    Err(AssetIdentityError::new(
        "model.safetensors",
        format!(
            "local model dir {} has no model.safetensors (candle requires safetensors, \
             not pytorch_model.bin)",
            dir.display()
        ),
    ))
}

/// The single startup error for a neural model that cannot be loaded.
///
/// Callers that refuse to start (#1840) use this text so the operator sees
/// the cause once, plus the two ways out: lexical, or an offline / mirrored
/// model. Lexical is named as a different command, never as a silent swap —
/// those vectors are not comparable with neural vectors (#1189).
pub fn startup_failure_message(model_id: &str, error: &anyhow::Error) -> String {
    format!(
        "embedding.mode=neural failed to load model {model_id}: {error:#}. \
         Refusing to start. Lexical vectors are not comparable with neural vectors, \
         so this process will not switch to the lexical embedder or keep running and \
         fail every ingest. To index without a model, restart with: \
         xerj --embed-mode lexical. To keep neural offline, set \
         embedding.local_model_dir to a directory containing config.json, \
         tokenizer.json and model.safetensors. To use a HuggingFace mirror, set \
         HF_ENDPOINT to the mirror base URL and start again."
    )
}

/// Download (or read from cache) the model files from the HuggingFace Hub.
///
/// The server calls this at startup when `--embed-mode neural` is requested,
/// before it listens. The first start on a fresh machine pulls the weights
/// (~90 MB for MiniLM); every start after that is a cache hit. A progress bar
/// is shown (hf-hub writes it to stderr) so a download is not mistaken for a
/// hang.
fn resolve_from_hub(cfg: &NeuralConfig) -> Result<(PathBuf, PathBuf, PathBuf)> {
    use hf_hub::api::sync::ApiBuilder;

    let model_id = cfg.model_id.as_str();
    // `ApiBuilder::new()` does not read `HF_ENDPOINT` (hf-hub 0.4 reserved
    // that for `from_env`, which also relocates the cache via `HF_HOME`).
    // Keep the historical cache directory and apply only the mirror URL,
    // unless the caller set `model_cache_dir` / `hub_endpoint`.
    let mut builder = ApiBuilder::new().with_progress(true).with_retries(0);
    if let Some(dir) = &cfg.cache_dir {
        builder = builder.with_cache_dir(dir.clone());
    }
    if let Some(endpoint) = hub_endpoint_override(cfg) {
        builder = builder.with_endpoint(endpoint);
    }
    let api = builder
        .build()
        .with_context(|| "init HuggingFace hub client")?;
    let repo = api.model(model_id.to_string());

    // Small metadata first (fast), then the big weights file. If the weights
    // are not already cached, this is the one-time download.
    let config = repo
        .get("config.json")
        .with_context(|| format!("fetch config.json for {model_id}"))?;
    let tokenizer = repo
        .get("tokenizer.json")
        .with_context(|| format!("fetch tokenizer.json for {model_id}"))?;
    let cached = config
        .parent()
        .map(|d| d.join("model.safetensors").exists())
        .unwrap_or(false);
    if !cached {
        tracing::info!(
            model = %model_id,
            "neural embedder: downloading model weights from HuggingFace \
             (one-time, ~90 MB for MiniLM; cached for every later start)…"
        );
    }
    let weights = repo.get("model.safetensors").with_context(|| {
        format!(
            "fetch model.safetensors for {model_id} (candle requires safetensors weights). \
             If this host has no internet, pre-download the model and point \
             `embedding.local_model_dir` at the folder holding config.json / \
             tokenizer.json / model.safetensors."
        )
    })?;
    tracing::info!(model = %model_id, "neural embedder: model ready");
    Ok((config, tokenizer, weights))
}

/// Explicit [`NeuralConfig::hub_endpoint`], otherwise a non-empty `HF_ENDPOINT`.
fn hub_endpoint_override(cfg: &NeuralConfig) -> Option<String> {
    if let Some(endpoint) = cfg
        .hub_endpoint
        .as_deref()
        .map(str::trim)
        .filter(|endpoint| !endpoint.is_empty())
    {
        return Some(endpoint.to_string());
    }
    std::env::var("HF_ENDPOINT")
        .ok()
        .map(|endpoint| endpoint.trim().to_string())
        .filter(|endpoint| !endpoint.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cosine(a: &[f32], b: &[f32]) -> f32 {
        a.iter().zip(b).map(|(x, y)| x * y).sum::<f32>()
    }

    /// Live test: downloads MiniLM on first run and checks that neural
    /// embeddings capture semantic similarity (paraphrase > unrelated),
    /// which the lexical feature-hash embedder cannot do. Network + ~90 MB
    /// download, so it is `#[ignore]`d — run explicitly:
    ///   cargo test -p xerj-ai --features neural -- --ignored --nocapture
    #[test]
    #[ignore]
    fn neural_captures_semantic_similarity() {
        let emb = NeuralEmbedder::load(&NeuralConfig::default()).expect("load MiniLM");
        assert_eq!(emb.dims(), 384, "MiniLM is 384-dim");

        let texts = vec![
            "A man is playing a guitar on stage.".to_string(),
            "A musician performs with his guitar at a concert.".to_string(),
            "The quarterly financial report shows rising interest rates.".to_string(),
        ];
        let vecs = emb.embed_blocking(&texts).expect("embed");
        assert_eq!(vecs.len(), 3);
        assert_eq!(vecs[0].len(), 384);

        // Each vector is L2-normalized, so cosine == dot product.
        let norm0 = cosine(&vecs[0], &vecs[0]).sqrt();
        assert!(
            (norm0 - 1.0).abs() < 1e-3,
            "vectors should be L2-normalized"
        );

        let sim_paraphrase = cosine(&vecs[0], &vecs[1]);
        let sim_unrelated = cosine(&vecs[0], &vecs[2]);
        eprintln!("paraphrase cos = {sim_paraphrase:.4}, unrelated cos = {sim_unrelated:.4}");
        assert!(
            sim_paraphrase > sim_unrelated + 0.15,
            "neural embedder must rank the paraphrase far above the unrelated \
             sentence (got paraphrase={sim_paraphrase:.3}, unrelated={sim_unrelated:.3})"
        );
    }

    /// The ~512-character chunk `TextChunker` emits for a long field.
    fn long_passage() -> String {
        let mut s = String::new();
        while s.len() < 512 {
            s.push_str(
                "the graph builder links each new node to its diverse neighbors and prunes the \
                 candidate list before the next level is entered. ",
            );
        }
        s.truncate(512);
        s
    }

    /// ~120 characters, the document shape measured in issue #366.
    fn short_passage(i: usize) -> String {
        format!(
            "method selectAndLinkDiverse{i} in HnswGraphBuilder.java. Select neighbors and \
                 return a mask of the ones kept."
        )
    }

    /// Regression for #366. A window that mixes one long chunk with many short
    /// lines must not charge the short lines the long chunk's length.
    ///
    /// Before length-aware batching this ran as ONE rectangular forward pass of
    /// 64 rows padded to the long chunk, i.e. `padded_token_slots` ≈ 3× the
    /// tokens the input actually held; measured wall time on the same box went
    /// 40 → 146 passages/s when this bound started holding.
    ///
    /// Live test (needs the MiniLM weights), so `#[ignore]`d:
    ///   cargo test -p xerj-ai --features neural -- --ignored --nocapture
    #[test]
    #[ignore]
    fn mixed_length_window_does_not_pad_short_passages_up_to_the_long_one() {
        let emb = NeuralEmbedder::load(&NeuralConfig::default()).expect("load MiniLM");

        let mut texts = vec![long_passage()];
        texts.extend((0..63).map(short_passage));
        let (vectors, stats) = emb.embed_blocking_stats(&texts).expect("embed");

        assert_eq!(vectors.len(), texts.len());
        eprintln!(
            "forwards={} padded_slots={} real_tokens={} ratio={:.2}",
            stats.inference_calls,
            stats.padded_token_slots,
            stats.real_tokens,
            stats.padded_token_slots as f64 / stats.real_tokens as f64
        );
        assert!(
            stats.padded_token_slots * 2 <= stats.real_tokens * 3,
            "padding waste must stay under 1.5×: {} padded slots for {} real tokens \
             ({} forward passes)",
            stats.padded_token_slots,
            stats.real_tokens,
            stats.inference_calls
        );
    }

    /// Grouping reorders rows internally; the vectors that come back must still
    /// line up with the inputs, and must match what each passage gets on its
    /// own. Live test, so `#[ignore]`d.
    #[test]
    #[ignore]
    fn grouping_preserves_input_order() {
        let emb = NeuralEmbedder::load(&NeuralConfig::default()).expect("load MiniLM");

        // Deliberately interleaved lengths so the length sort has to reorder.
        let texts = vec![
            long_passage(),
            short_passage(1),
            "a".to_string(),
            long_passage(),
            short_passage(2),
        ];
        let batched = emb.embed_blocking(&texts).expect("embed batch");
        assert_eq!(batched.len(), texts.len());
        for (i, text) in texts.iter().enumerate() {
            let alone = emb
                .embed_blocking(std::slice::from_ref(text))
                .expect("embed alone");
            let sim = cosine(&batched[i], &alone[0]);
            assert!(
                sim > 0.999,
                "row {i} came back out of order or altered: cosine {sim:.4} against the \
                 same passage embedded alone"
            );
        }
    }
}

//! Experimental FP32 ONNX Runtime MiniLM backend.
//!
//! This backend is available end-to-end only in builds with the
//! `onnx-experimental` feature and must be explicitly selected with local
//! model/tokenizer paths. It is deliberately not a generic ONNX interface: the
//! graph must be an FP32 all-MiniLM-L6-v2-compatible encoder with int64 inputs
//! named `input_ids`, `attention_mask`, and `token_type_ids`, and a rank-3,
//! width-384 output named `last_hidden_state` or `token_embeddings`. The
//! tokenizer.json must come from the same model/export. XERJ attention-mask
//! mean-pools and L2-normalizes the token output.
//!
//! The safe `ort` API requires mutable session access, so one
//! session is serialized behind a mutex and aggregate throughput comes from
//! bounded, length-aware microbatches rather than unsafe concurrent `Run`.

use anyhow::{anyhow, Context, Result};
use ort::session::{builder::GraphOptimizationLevel, Session};
use ort::value::Tensor;
use std::path::Path;
use std::sync::{Arc, Condvar, Mutex};
use tokenizers::{PaddingParams, PaddingStrategy, Tokenizer, TruncationParams};

pub const MAX_TOKENS: usize = 512;
pub const DIMS: usize = 384;

/// Bounds for one offline scheduling window.
#[derive(Clone, Copy, Debug, Hash, PartialEq, Eq)]
pub struct MicrobatchConfig {
    /// Maximum inputs accepted in one call. Larger calls receive a clear
    /// backpressure error instead of allocating an unbounded queue.
    pub max_pending: usize,
    /// Maximum documents sent to one inference call.
    pub max_batch: usize,
    /// Maximum `batch_size × longest_sequence` token slots.
    pub padded_token_budget: usize,
}

impl Default for MicrobatchConfig {
    fn default() -> Self {
        Self {
            max_pending: 4_096,
            max_batch: 64,
            padded_token_budget: 4_096,
        }
    }
}

impl MicrobatchConfig {
    fn validate(self) -> Result<Self> {
        if self.max_pending == 0 || self.max_batch == 0 || self.padded_token_budget == 0 {
            return Err(anyhow!(
                "ONNX microbatch limits must be non-zero (max_pending={}, max_batch={}, padded_token_budget={})",
                self.max_pending,
                self.max_batch,
                self.padded_token_budget
            ));
        }
        Ok(self)
    }
}

pub struct OnnxEmbedder {
    session: Mutex<Session>,
    tokenizer: Tokenizer,
}

/// A fixed-width pool of independent ONNX Runtime sessions.
///
/// Construction is atomic: callers either receive the requested number of
/// sessions or an error, never a partially initialized pool.
pub(crate) struct OnnxPool {
    size: usize,
    sessions: Mutex<Vec<Arc<OnnxEmbedder>>>,
    available: Condvar,
}

struct SessionLease<'a> {
    pool: &'a OnnxPool,
    session: Option<Arc<OnnxEmbedder>>,
}

impl OnnxPool {
    pub(crate) fn load_bytes(
        model_bytes: &[u8],
        tokenizer_bytes: &[u8],
        intra_threads: usize,
        pool_size: usize,
    ) -> Result<Self> {
        if pool_size == 0 {
            return Err(anyhow!("ONNX session pool size must be non-zero"));
        }
        let sessions = build_exact_pool(pool_size, |ordinal| {
            OnnxEmbedder::load_bytes(model_bytes, tokenizer_bytes, intra_threads).with_context(
                || {
                    format!(
                        "construct ONNX session {} of {}; no partial pool was published",
                        ordinal + 1,
                        pool_size
                    )
                },
            )
        })?
        .into_iter()
        .map(Arc::new)
        .collect();
        Ok(Self {
            size: pool_size,
            sessions: Mutex::new(sessions),
            available: Condvar::new(),
        })
    }

    pub(crate) fn len(&self) -> usize {
        self.size
    }

    fn lease(&self) -> Result<SessionLease<'_>> {
        let mut sessions = self
            .sessions
            .lock()
            .map_err(|_| anyhow!("ONNX session pool mutex poisoned"))?;
        while sessions.is_empty() {
            sessions = self
                .available
                .wait(sessions)
                .map_err(|_| anyhow!("ONNX session pool mutex poisoned"))?;
        }
        let session = sessions.pop().expect("non-empty pool checked");
        Ok(SessionLease {
            pool: self,
            session: Some(session),
        })
    }

    pub(crate) fn embed_scheduled_blocking(
        &self,
        texts: &[String],
        config: MicrobatchConfig,
    ) -> Result<Vec<Vec<f32>>> {
        let lease = self.lease()?;
        lease
            .session
            .as_ref()
            .expect("leased session present")
            .embed_scheduled_blocking(texts, config)
    }
}

fn build_exact_pool<T>(
    pool_size: usize,
    mut construct: impl FnMut(usize) -> Result<T>,
) -> Result<Vec<T>> {
    let mut values = Vec::with_capacity(pool_size);
    for ordinal in 0..pool_size {
        values.push(construct(ordinal)?);
    }
    Ok(values)
}

impl Drop for SessionLease<'_> {
    fn drop(&mut self) {
        if let Some(session) = self.session.take() {
            let mut sessions = self
                .pool
                .sessions
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            sessions.push(session);
            self.pool.available.notify_one();
        }
    }
}

impl OnnxEmbedder {
    pub fn load(model_path: &Path, tokenizer_path: &Path, intra_threads: usize) -> Result<Self> {
        let model = std::fs::read(model_path)
            .with_context(|| format!("read ONNX model {}", model_path.display()))?;
        let tokenizer = std::fs::read(tokenizer_path)
            .with_context(|| format!("read tokenizer {}", tokenizer_path.display()))?;
        Self::load_bytes(&model, &tokenizer, intra_threads)
    }

    pub(crate) fn load_bytes(
        model_bytes: &[u8],
        tokenizer_bytes: &[u8],
        intra_threads: usize,
    ) -> Result<Self> {
        let mut tokenizer = Tokenizer::from_bytes(tokenizer_bytes)
            .map_err(|e| anyhow!("load tokenizer.json bytes: {e}"))?;
        tokenizer.with_padding(Some(PaddingParams {
            strategy: PaddingStrategy::BatchLongest,
            ..Default::default()
        }));
        tokenizer
            .with_truncation(Some(TruncationParams {
                max_length: MAX_TOKENS,
                ..Default::default()
            }))
            .map_err(|e| anyhow!("configure tokenizer truncation: {e}"))?;

        let ort_log_level = match std::env::var("XERJ_ONNX_LOG")
            .unwrap_or_default()
            .to_ascii_lowercase()
            .as_str()
        {
            "verbose" | "trace" => ort::logging::LogLevel::Verbose,
            "info" | "debug" => ort::logging::LogLevel::Info,
            "error" => ort::logging::LogLevel::Error,
            "fatal" => ort::logging::LogLevel::Fatal,
            _ => ort::logging::LogLevel::Warning,
        };
        let session = Session::builder()
            .map_err(|e| anyhow!("create ONNX Runtime session builder: {e}"))?
            .with_log_level(ort_log_level)
            .map_err(|e| anyhow!("configure ONNX Runtime log level: {e}"))?
            .with_optimization_level(GraphOptimizationLevel::Level3)
            .map_err(|e| anyhow!("configure ONNX graph optimizations: {e}"))?
            .with_config_entry("session.intra_op.allow_spinning", "0")
            .map_err(|e| anyhow!("disable ONNX intra-op spinning: {e}"))?
            .with_intra_threads(intra_threads.max(1))
            .map_err(|e| anyhow!("configure ONNX intra-op threads: {e}"))?
            .commit_from_memory(model_bytes)
            .context("load ONNX model bytes")?;
        Ok(Self {
            session: Mutex::new(session),
            tokenizer,
        })
    }

    /// Embed a bounded scheduling window, grouping similar lengths and
    /// restoring vectors to exact input order.
    pub fn embed_scheduled_blocking(
        &self,
        texts: &[String],
        config: MicrobatchConfig,
    ) -> Result<Vec<Vec<f32>>> {
        let config = config.validate()?;
        if texts.len() > config.max_pending {
            return Err(anyhow!(
                "ONNX embedding queue is full: received {} texts, max_pending={}; split the request or retry after draining",
                texts.len(),
                config.max_pending
            ));
        }
        let lengths = texts
            .iter()
            .map(|text| self.token_len(text))
            .collect::<Result<Vec<_>>>()?;
        let batches = plan_microbatches(&lengths, config)?;
        let mut ordered = vec![Vec::new(); texts.len()];
        for batch in batches {
            let input = batch.iter().map(|&i| texts[i].clone()).collect::<Vec<_>>();
            let vectors = self.embed_blocking(&input)?;
            for (position, vector) in batch.into_iter().zip(vectors) {
                ordered[position] = vector;
            }
        }
        Ok(ordered)
    }

    pub fn token_len(&self, text: &str) -> Result<usize> {
        self.tokenizer
            .encode(text, true)
            .map(|encoding| encoding.len())
            .map_err(|e| anyhow!("tokenize for ONNX scheduling: {e}"))
    }

    pub fn embed_blocking(&self, texts: &[String]) -> Result<Vec<Vec<f32>>> {
        if texts.is_empty() {
            return Ok(vec![]);
        }
        let encodings = self
            .tokenizer
            .encode_batch(texts.to_vec(), true)
            .map_err(|e| anyhow!("tokenize batch: {e}"))?;
        let batch = encodings.len();
        let seq_len = encodings.first().map(|e| e.get_ids().len()).unwrap_or(0);
        if seq_len == 0 {
            return Ok(vec![vec![0.0; DIMS]; batch]);
        }

        let mut ids = Vec::with_capacity(batch * seq_len);
        let mut mask = Vec::with_capacity(batch * seq_len);
        for encoding in &encodings {
            ids.extend(encoding.get_ids().iter().map(|&v| i64::from(v)));
            mask.extend(encoding.get_attention_mask().iter().map(|&v| i64::from(v)));
        }
        let token_types = vec![0_i64; ids.len()];
        let shape = [batch, seq_len];
        let input_ids = Tensor::from_array((shape, ids)).context("build input_ids")?;
        let attention_mask =
            Tensor::from_array((shape, mask.clone())).context("build attention_mask")?;
        let token_type_ids =
            Tensor::from_array((shape, token_types)).context("build token_type_ids")?;

        let mut session = self
            .session
            .lock()
            .map_err(|_| anyhow!("ONNX session mutex poisoned"))?;
        let outputs = session
            .run(ort::inputs! {
                "input_ids" => input_ids,
                "attention_mask" => attention_mask,
                "token_type_ids" => token_type_ids,
            })
            .context("ONNX MiniLM inference")?;
        let output = outputs
            .get("last_hidden_state")
            .or_else(|| outputs.get("token_embeddings"))
            .ok_or_else(|| anyhow!("ONNX model did not return token embeddings"))?;
        let (output_shape, hidden) = output
            .try_extract_tensor::<f32>()
            .context("extract ONNX token embeddings")?;
        let shape_dims = output_shape.iter().copied().collect::<Vec<_>>();
        if shape_dims != [batch as i64, seq_len as i64, DIMS as i64] {
            return Err(anyhow!(
                "unexpected ONNX output shape {shape_dims:?}, expected [{batch}, {seq_len}, {DIMS}]"
            ));
        }

        let mut vectors = Vec::with_capacity(batch);
        for row in 0..batch {
            let mut pooled = vec![0.0_f32; DIMS];
            let mut count = 0.0_f32;
            for token in 0..seq_len {
                let weight = mask[row * seq_len + token] as f32;
                count += weight;
                let base = (row * seq_len + token) * DIMS;
                for dim in 0..DIMS {
                    pooled[dim] += hidden[base + dim] * weight;
                }
            }
            for value in &mut pooled {
                *value /= count.max(1e-9);
            }
            let norm = pooled
                .iter()
                .map(|value| value * value)
                .sum::<f32>()
                .sqrt()
                .max(1e-12);
            for value in &mut pooled {
                *value /= norm;
            }
            vectors.push(pooled);
        }
        Ok(vectors)
    }
}

/// Plan length-aware microbatches. Indices are sorted for inference efficiency;
/// callers must use them to restore original order.
///
/// The grouping itself is [`crate::microbatch::group_by_padded_cost`], shared
/// with the Candle backend. What stays here is the ONNX-specific contract:
/// backpressure past `max_pending`, and refusing a single input the budget
/// cannot fit rather than silently running it alone.
pub fn plan_microbatches(
    token_lengths: &[usize],
    config: MicrobatchConfig,
) -> Result<Vec<Vec<usize>>> {
    let config = config.validate()?;
    if token_lengths.len() > config.max_pending {
        return Err(anyhow!(
            "ONNX embedding queue is full: received {} texts, max_pending={}",
            token_lengths.len(),
            config.max_pending
        ));
    }
    let clamped = token_lengths
        .iter()
        .map(|length| (*length).min(MAX_TOKENS))
        .collect::<Vec<_>>();
    if let Some(length) = clamped
        .iter()
        .copied()
        .filter(|length| *length > config.padded_token_budget)
        .min()
    {
        return Err(anyhow!(
            "padded_token_budget={} cannot fit one {}-token input",
            config.padded_token_budget,
            length
        ));
    }
    Ok(crate::microbatch::group_by_padded_cost(
        &clamped,
        config.max_batch,
        config.padded_token_budget,
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pool_initialization_discards_partial_members_on_failure() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        #[derive(Debug)]
        struct Member<'a>(&'a AtomicUsize);
        impl Drop for Member<'_> {
            fn drop(&mut self) {
                self.0.fetch_add(1, Ordering::Relaxed);
            }
        }

        let dropped = AtomicUsize::new(0);
        let error = build_exact_pool(3, |ordinal| {
            if ordinal == 1 {
                Err(anyhow!("synthetic second-session failure"))
            } else {
                Ok(Member(&dropped))
            }
        })
        .expect_err("a member failure must reject the whole pool")
        .to_string();
        assert!(error.contains("second-session failure"), "{error}");
        assert_eq!(dropped.load(Ordering::Relaxed), 1);
    }

    /// Run with explicit matching assets:
    ///
    /// `XERJ_ONNX_TEST_MODEL=/abs/model.onnx
    ///  XERJ_ONNX_TEST_TOKENIZER=/abs/tokenizer.json
    ///  cargo test -p xerj-ai --features onnx-experimental
    ///  independent_pool_sessions_are_bit_identical -- --ignored`
    #[test]
    #[ignore = "requires explicit matching ONNX model and tokenizer assets"]
    fn independent_pool_sessions_are_bit_identical() {
        let model = std::fs::read(
            std::env::var_os("XERJ_ONNX_TEST_MODEL").expect("XERJ_ONNX_TEST_MODEL is required"),
        )
        .unwrap();
        let tokenizer = std::fs::read(
            std::env::var_os("XERJ_ONNX_TEST_TOKENIZER")
                .expect("XERJ_ONNX_TEST_TOKENIZER is required"),
        )
        .unwrap();
        let texts = vec![
            "quarterly revenue increased year over year".to_string(),
            "operating margin declined in the fourth quarter".to_string(),
        ];
        let config = MicrobatchConfig::default();
        let expected = OnnxEmbedder::load_bytes(&model, &tokenizer, 2)
            .unwrap()
            .embed_scheduled_blocking(&texts, config)
            .unwrap();
        let expected_bits = expected
            .iter()
            .flatten()
            .map(|value| value.to_bits())
            .collect::<Vec<_>>();
        let pool = OnnxPool::load_bytes(&model, &tokenizer, 2, 2).unwrap();
        let sessions = pool.sessions.lock().unwrap();
        assert_eq!(sessions.len(), 2);
        for session in sessions.iter() {
            let actual = session.embed_scheduled_blocking(&texts, config).unwrap();
            assert_eq!(
                actual
                    .iter()
                    .flatten()
                    .map(|value| value.to_bits())
                    .collect::<Vec<_>>(),
                expected_bits
            );
        }
    }

    #[test]
    fn planner_bounds_every_batch_and_preserves_all_positions() {
        let lengths = [512, 14, 200, 16, 400, 15, 90, 300];
        let config = MicrobatchConfig {
            max_pending: 8,
            max_batch: 3,
            padded_token_budget: 600,
        };
        let batches = plan_microbatches(&lengths, config).unwrap();
        let mut positions = batches.iter().flatten().copied().collect::<Vec<_>>();
        positions.sort_unstable();
        assert_eq!(positions, (0..lengths.len()).collect::<Vec<_>>());
        for batch in batches {
            assert!(batch.len() <= config.max_batch);
            let longest = batch.iter().map(|&i| lengths[i]).max().unwrap();
            assert!(longest * batch.len() <= config.padded_token_budget);
        }
    }

    #[test]
    fn planner_applies_backpressure() {
        let error = plan_microbatches(
            &[10, 20, 30],
            MicrobatchConfig {
                max_pending: 2,
                ..MicrobatchConfig::default()
            },
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("queue is full"));
        assert!(error.contains("max_pending=2"));
    }

    #[test]
    fn planner_rejects_impossible_budget() {
        let error = plan_microbatches(
            &[512],
            MicrobatchConfig {
                padded_token_budget: 128,
                ..MicrobatchConfig::default()
            },
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("cannot fit"));
    }
}

