];

#[derive(Clone, Copy, PartialEq, Debug)]
enum Op {
    Gt,
    Gte,
    Lt,
    Lte,
    Eq,
}

impl Op {
    fn key(self) -> &'static str {
        match self {
            Op::Gt => "gt",
            Op::Gte => "gte",
            Op::Lt => "lt",
            Op::Lte => "lte",
            Op::Eq => "eq",
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tokens
// ─────────────────────────────────────────────────────────────────────────────

/// One prompt token, pre-normalised three ways.
#[derive(Clone, Debug)]
struct Tok {
    raw: String,
    norm: String,
    number: Option<f64>,
    /// Integral literals keep int fidelity ("4" stays 4, not 4.0).
    int_literal: Option<i64>,
    word_number: Option<f64>,
    /// concept implied by a spelled star-count word ("triple" → snum).
    concept: Option<&'static str>,
    capitalized: bool,
}

impl Tok {
    /// Numbers this planner will reason about. Non-finite literals ("1e999")
    /// are deliberately NOT numbers here: no clause may carry a bound the
    /// parser would reject, so they fall through to the leftover pass and are
    /// named in a 422 instead.
    fn is_num(&self) -> bool {
        self.number.is_some_and(|v| v.is_finite()) || self.word_number.is_some()
    }
    fn num_f64(&self) -> Option<f64> {
        self.number.or(self.word_number)
    }
    fn num_value(&self) -> Option<Value> {
        if let Some(i) = self.int_literal {
            return Some(json!(i));
        }
        self.num_f64()
            .and_then(serde_json::Number::from_f64)
            .map(Value::Number)
    }
    fn is_date(&self) -> bool {
        date_parts(&self.raw).is_some()
    }
}

fn tokenize(prompt: &str) -> Vec<Tok> {
    let mut out = Vec::new();
    for w in prompt.split_whitespace() {
        let raw = w
            .trim_matches(|c: char| ".,;:()[]{}\"'!?".contains(c))
            .to_string();
        if raw.is_empty() {
            continue;
        }
        let lower = raw.to_lowercase();
        let norm = norm_text(&raw);
        let number = lower.parse::<f64>().ok();
        let int_literal = lower.parse::<i64>().ok();
        let (word_number, concept) = word_number(&norm);
        let capitalized = raw
            .chars()
            .next()
            .map(|c| {
                c.is_uppercase()
                    && raw
                        .chars()
                        .all(|c| c.is_alphanumeric() || c == '-' || c == '_')
            })
            .unwrap_or(false);
        out.push(Tok {
            raw,
            norm,
            number,
            int_literal,
            word_number,
            concept,
            capitalized,
        });
        if out.len() == MAX_PROMPT_TOKENS {
            break;
        }
    }
    out
}

/// Normed tokens of free text (catalog descriptions, notes).
fn tokenize_normed(s: &str) -> Vec<String> {
    s.split_whitespace()
        .map(norm_text)
        .filter(|t| !t.is_empty())
        .collect()
}

/// lowercase, ascii-folded, alphanumeric only — the comparison key for
/// fields, concepts, and values.
fn norm_text(s: &str) -> String {
    s.chars()
        .filter_map(|c| {
            if c.is_ascii_alphanumeric() {
                Some(c.to_ascii_lowercase())
            } else {
                None
            }
        })
        .collect()
}

fn norm_value(v: &Value) -> String {
    match v {
        Value::String(s) => norm_text(s),
        other => norm_text(&other.to_string()),
    }
}

/// field name → comparison tokens: split on `_`, `-`, `.`, and camelCase
/// (`pl_orbper` → [pl, orbper], `lifeExp` → [life, exp]).
fn name_tokens(name: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut prev_lower = false;
    for c in name.chars() {
        if c == '_' || c == '-' || c == '.' {
            if !cur.is_empty() {
                out.push(mem::take(&mut cur));
            }
            prev_lower = false;
        } else if c.is_uppercase() {
            if prev_lower && !cur.is_empty() {
                out.push(mem::take(&mut cur));
            }
            cur.push(c.to_ascii_lowercase());
            prev_lower = false;
        } else {
            cur.push(c);
            prev_lower = c.is_lowercase() || c.is_ascii_digit();
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

/// Spelled numbers, plus the star-count words astronomy uses ("single",
/// "binary", "triple"… carry their own concept).
fn word_number(w: &str) -> (Option<f64>, Option<&'static str>) {
    // Hyphenated compounds like `triple-star`/`binary-star` norm to
    // `triplestar` and count the same way: the `-star` suffix is the unit
    // the number names.
    let stripped = w
        .strip_suffix("stars")
        .or_else(|| w.strip_suffix("star"))
        .unwrap_or(w);
    match stripped {
        "one" => (Some(1.0), None),
        "single" => (Some(1.0), Some("snum")),
        "two" => (Some(2.0), None),
        "binary" => (Some(2.0), Some("snum")),
        "three" => (Some(3.0), None),
        "triple" => (Some(3.0), Some("snum")),
        "four" => (Some(4.0), None),
        "quadruple" => (Some(4.0), Some("snum")),
        "five" => (Some(5.0), None),
        "quintuple" => (Some(5.0), Some("snum")),
        "six" => (Some(6.0), None),
        "seven" => (Some(7.0), None),
        "eight" => (Some(8.0), None),
        "nine" => (Some(9.0), None),
        "ten" => (Some(10.0), None),
        _ => (None, None),
    }
}

/// `2026-09-01` → a valid (y, m, d).
fn date_parts(word: &str) -> Option<(i32, u32, u32)> {
    let mut it = word.split('-');
    let y: i32 = it.next()?.parse().ok()?;
    let m: u32 = it.next()?.parse().ok()?;
    let d: u32 = it.next()?.parse().ok()?;
    if it.next().is_some() {
        return None;
    }
    chrono::NaiveDate::from_ymd_opt(y, m, d)?;
    Some((y, m, d))
}

fn day_start(y: i32, m: u32, d: u32) -> String {
    format!("{y:04}-{m:02}-{d:02}T00:00:00Z")
}

fn next_day(y: i32, m: u32, d: u32) -> String {
    chrono::NaiveDate::from_ymd_opt(y, m, d)
        .and_then(|date| date.succ_opt())
        .map(|next| day_start(next.year(), next.month(), next.day()))
        .unwrap_or_else(|| day_start(y, m, d))
}

fn year_start(y: i64) -> String {
    format!("{y:04}-01-01T00:00:00Z")
}

fn next_year_start(y: i64) -> String {
    format!("{:04}-01-01T00:00:00Z", y + 1)
}

/// `*` wildcard match (the only wildcard the ES-compat surface promises for
/// index names; multiple stars each match any run, possibly empty —
/// `ax-*-2026-*` is a legal pattern). Everything else is literal. Classic
/// two-pointer backtrack: pure, allocation-free, deterministic.
fn glob_match(pattern: &str, name: &str) -> bool {
    let p: Vec<char> = pattern.chars().collect();
    let s: Vec<char> = name.chars().collect();
    let (mut pi, mut si) = (0usize, 0usize);
    let (mut star, mut mark) = (usize::MAX, 0usize);
    while si < s.len() {
        if pi < p.len() && p[pi] == s[si] {
            pi += 1;
            si += 1;
        } else if pi < p.len() && p[pi] == '*' {
            star = pi;
            mark = si;
            pi += 1;
        } else if star != usize::MAX {
            mark += 1;
            si = mark;
            pi = star + 1;
        } else {
            return false;
        }
    }
    while pi < p.len() && p[pi] == '*' {
        pi += 1;
    }
    pi == p.len()
}

// ─────────────────────────────────────────────────────────────────────────────
// Field-phrase resolution
// ─────────────────────────────────────────────────────────────────────────────

/// Concept lookup over a joined normed phrase → preferred field tokens.
fn concept_for(joined: &str) -> Option<&'static [&'static str]> {
    CONCEPTS
        .iter()
        .find(|(key, _)| {
            joined == *key
                || (joined.len() >= 4 && key.ends_with(joined))
                || (key.len() >= 4 && joined.ends_with(key))
        })
        .map(|(_, targets)| *targets)
}

/// Position (name order) of the first field carrying one of these targets and
/// passing the gate. A target matches a whole name token OR the full normed
/// name — concept tables speak both spellings: `mag` is a token of `mag`, but
/// `lifeexp`/`gdppercap` are the FULL names `lifeExp`/`gdpPercap`, whose
/// comparison tokens split differently ([life, exp], [gdp, percap]).
fn field_by_tokens(
    targets: &[&str],
    fields: &[FieldView],
    gate: impl Fn(&FieldView) -> bool,
) -> Option<usize> {
    fields.iter().position(|f| {
        gate(f)
            && targets
                .iter()
                .any(|t| f.tokens.iter().any(|ft| ft == t) || &f.norm == t)
    })
}

/// Scored name match between a joined normed phrase and one field.
fn name_score(joined: &str, phrase_tokens: &[String], f: &FieldView) -> Option<u32> {
    if joined == f.norm {
        return Some(1000);
    }
    if f.norm.len() >= 3 && joined.starts_with(&f.norm) {
        // mag ⊂ magnitude, pop ⊂ population, gdppercap ⊂ gdppercapita
        return Some(800 + f.norm.len() as u32);
    }
    if joined.len() >= 3 && f.norm.starts_with(joined) {
        return Some(700 + joined.len() as u32);
    }
    let matched = phrase_tokens
        .iter()
        .filter(|p| {
            f.tokens.iter().any(|ft| {
                ft == *p
                    || (ft.len() >= 3 && p.starts_with(ft))
                    || (p.len() >= 3 && ft.starts_with(p.as_str()))
            })
        })
        .count();
    if matched > 0 && matched == phrase_tokens.len() {
        return Some(600 + matched as u32);
    }
    None
}

/// Resolve a field phrase (token indexes) under a gate: concept table first,
/// then scored name matching. Ties resolve to the first field in name order
/// (fields arrive sorted) — deterministic.
fn resolve_field(
    toks: &[Tok],
    idxs: &[usize],
    fields: &[FieldView],
    gate: impl Fn(&FieldView) -> bool + Copy,
) -> Option<usize> {
    let phrase_tokens: Vec<String> = idxs.iter().map(|&i| toks[i].norm.clone()).collect();
    let joined = phrase_tokens.concat();
    if joined.is_empty() {
        return None;
    }
    if let Some(targets) = concept_for(&joined) {
        if let Some(pos) = fields
            .iter()
            .position(|f| gate(f) && targets.iter().any(|t| f.tokens.iter().any(|ft| ft == t)))
        {
            return Some(pos);
        }
    }
    let mut best: Option<(u32, usize)> = None;
    for (pos, f) in fields.iter().enumerate() {
        if !gate(f) {
            continue;
        }
        if let Some(score) = name_score(&joined, &phrase_tokens, f) {
            if best.is_none_or(|(bs, _)| score > bs) {
                best = Some((score, pos));
            }
        }
    }
    best.map(|(_, pos)| pos)
}

/// The year-ish field: a numeric field whose name carries "year" (gapminder
/// `year`, nasa `disc_year`), else a date field (then a year becomes a
/// year-wide date range — still only prompt-supplied bounds).
fn year_field(fields: &[FieldView]) -> Option<usize> {
    fields
        .iter()
        .position(|f| f.numeric() && f.tokens.iter().any(|t| t == "year"))
        .or_else(|| fields.iter().position(|f| f.date()))
}

/// The date field: the catalog's `time_field` when present, else date-typed
/// fields by name preference (time > date > timestamp) then name order.
fn date_field(fields: &[FieldView], hint: Option<&str>) -> Option<usize> {
    if let Some(h) = hint {
        if let Some(pos) = fields.iter().position(|f| f.name == h && f.date()) {
            return Some(pos);
        }
    }
    let pref = |f: &FieldView| {
        if f.tokens.iter().any(|t| t == "time") {
            0
        } else if f.tokens.iter().any(|t| t == "date") {
            1
        } else if f.tokens.iter().any(|t| t == "timestamp" || t == "ts") {
            2
        } else {
            3
        }
    };
    fields
        .iter()
        .enumerate()
        .filter(|(_, f)| f.date())
        .min_by_key(|(pos, f)| (pref(f), *pos))
        .map(|(pos, _)| pos)
}

// ─────────────────────────────────────────────────────────────────────────────
// The passes
// ─────────────────────────────────────────────────────────────────────────────

async fn plan_prompt(
    toks: &[Tok],
    fields: &[FieldView],
    time_field_hint: Option<&str>,
    used: &mut [bool],
    ctx: &mut PlanCtx,
    idx: &Arc<Index>,
) -> Result<(Value, f64), Refusal> {
    // Pass 0: the "multi-" quantifier ("multi-planet systems", "multi-star
    // systems") — "more than one" of the concept the suffix names. The bound
    // is the word's own meaning (as with "million" → 10⁶), not generated:
    // "multi" is strictly-greater-than one, which over integer counts is the
    // same set as ≥ 2.
    multi_pass(toks, fields, used, ctx);
    // Pass B first: comparator phrases claim their tokens, so "or greater"
    // never survives as a leftover value phrase.
    numeric_pass(toks, fields, used, ctx)?;
    // Pass A: date literals and bare years.
    date_pass(toks, fields, time_field_hint, used, ctx)?;
    // Pass P: a slash-bearing token is a path prefix, not a value. Claim it
    // before the value pass so `norm_text` (which strips `/`) cannot fold it
    // into an unrelated keyword, and before leftovers so it is not reported
    // as a dropped lowercase modifier (#2120).
    path_pass(toks, fields, used, ctx);
    // Pass C: equality from the value map (field+value splits, then values).
    let mut probes = 0usize;
    let leftovers = value_pass(toks, fields, used, ctx, idx, &mut probes).await;
    let grounded = !ctx.constraints.is_empty();
    settle_leftovers(toks, &leftovers, grounded, ctx)?;

    let mut constraints = ctx.constraints.clone();
    // Gold ordering, pinned by the harness: eq clauses in prompt order
    // first, then range clauses in prompt order. Deterministic either way,
    // but matching the reference makes exact-diff tests possible.
    constraints.sort_by_key(|c| (c.is_range, c.pos));
    let clause = match constraints.len() {
        0 => json!({ "match_all": {} }),
        1 => constraints.remove(0).clause,
        _ => {
            let filters: Vec<Value> = constraints.iter().map(|c| c.clause.clone()).collect();
            let mut inner = Map::new();
            inner.insert("filter".to_string(), Value::Array(filters));
            let mut outer = Map::new();
            outer.insert("bool".to_string(), Value::Object(inner));
            Value::Object(outer)
        }
    };
    let confidence = if ctx.constraints.is_empty() { 0.5 } else { 0.9 };
    Ok((clause, confidence))
}

/// `multi-<concept>` → `> 1` on the concept's field. Fires only when the
/// remainder names a concept with a numeric field in this index; anything
/// else ("multis") is left for the ordinary passes.
fn multi_pass(toks: &[Tok], fields: &[FieldView], used: &mut [bool], ctx: &mut PlanCtx) {
    for (i, t) in toks.iter().enumerate() {
        if used[i] {
            continue;
        }
        let Some(rest) = t.norm.strip_prefix("multi") else {
            continue;
        };
        if rest.len() < 4 {
            continue;
        }
        let Some(targets) = concept_for(rest) else {
            continue;
        };
        let Some(fpos) = field_by_tokens(targets, fields, |f| f.numeric()) else {
            continue;
        };
        let f = &fields[fpos];
        ctx.constraints.push(Constraint {
            clause: range_clause_1(&f.name, "gt", json!(1)),
            phrase: t.raw.clone(),
            via: "quantifier+concept",
            is_range: true,
            pos: i,
        });
        used[i] = true;
    }
}

/// Pass B: numeric comparisons. Every bound is a prompt literal; the scale
/// lexicon ("100 million" → 10⁸) is the only arithmetic, and it is the
/// prompt's own words.
fn numeric_pass(
    toks: &[Tok],
    fields: &[FieldView],
    used: &mut [bool],
    ctx: &mut PlanCtx,
) -> Result<(), Refusal> {
    let mut i = 0;
    while i < toks.len() {
        if used[i] || !toks[i].is_num() {
            i += 1;
            continue;
        }
        // A spelled star-count word carries its own field ("triple" → snum).
        if let Some(concept) = toks[i].concept {
            if let Some(f) =
                field_by_tokens(&[concept], fields, |f| f.numeric()).map(|pos| &fields[pos])
            {
                if let Some(v) = toks[i].num_value() {
                    ctx.constraints.push(Constraint {
                        clause: term_clause(&f.name, v),
                        phrase: toks[i].raw.clone(),
                        via: "literal+concept",
                        is_range: false,
                        pos: i,
                    });
                    used[i] = true;
                    i += 1;
                    continue;
                }
            }
        }

        // (1) pair: from/between … <num> and|to|through <num>
        if let Some((second, connector)) = pair_at(toks, used, i) {
            let (lo, _lo_x) = number_span(toks, i);
            let (hi, hi_x) = number_span(toks, second);
            // "magnitude from 4" hides the phrase before `from`;
            // "between magnitude 4" hides it after `between` — try both.
            let mut bwd = backward_phrase(toks, used, i);
            if bwd.is_empty() {
                if let Some(c) = connector {
                    bwd = backward_phrase(toks, used, c);
                }
            }
            let unit = unit_after(toks, second + 1 + hi_x).map(|(u, _)| u);
            let field = resolve_comparison(toks, &bwd, unit, None, &[], fields).or_else(|| {
                if is_yearish(&toks[i]) && is_yearish(&toks[second]) {
                    year_field(fields)
                } else {
                    None
                }
            });
            let Some(fpos) = field else {
                return Err(comparison_refusal(toks, &bwd, i));
            };
            let f = &fields[fpos];
            // A year pair against a date field stays prompt-supplied: the
            // years of the prompt, as year-wide bounds.
            let clause = if f.date() {
                let y1 = toks[i].int_literal.unwrap_or_default();
                let y2 = toks[second].int_literal.unwrap_or_default();
                range_clause_2(
                    &f.name,
                    json!(year_start(y1)),
                    "gte",
                    json!(next_year_start(y2)),
                    "lt",
                )
            } else {
                range_clause_2(&f.name, lo, "gte", hi, "lte")
            };
            let phrase = format!(
                "{}… {}",
                if bwd.is_empty() {
                    String::new()
                } else {
                    format!("{} ", phrase_text(toks, &bwd))
                },
                toks[second].raw
            );
            ctx.constraints.push(Constraint {
                clause,
                phrase: phrase.trim().to_string(),
                via: "range-pair",
                is_range: true,
                pos: bwd.first().copied().unwrap_or(i),
            });
            for &b in &bwd {
                used[b] = true;
            }
            for u in &mut used[i..=second + hi_x] {
                *u = true;
            }
            i = second + 1 + hi_x;
            continue;
        }

        // (2) op-after ("2.75 or greater", "2018 or later")
        let (val, sx) = number_span(toks, i);
        if let Some((olen, op)) = op_after_at(toks, i + 1 + sx) {
            let bwd = backward_phrase(toks, used, i);
            let unit = unit_after(toks, i + 1 + sx + olen).map(|(u, _)| u);
            let fwd = forward_phrase(toks, used, i + 1 + sx + olen, 3);
            let field = resolve_comparison(toks, &bwd, unit, None, &fwd, fields)
                .or_else(|| yearish_fallback(&toks[i], fields));
            let Some(fpos) = field else {
                return Err(comparison_refusal(toks, &bwd, i));
            };
            push_comparison(ctx, &fields[fpos], op, &toks[i], val, &bwd, i, toks);
            for u in &mut used[i..i + 1 + sx + olen] {
                *u = true;
            }
            for &b in &bwd {
                used[b] = true;
            }
            i += 1 + sx + olen;
            continue;
        }

        // (3) op-before ("deeper than 50", "at least 2 known planets"),
        // including the separated form where the field phrase sits between
        // the op and the number ("stronger than magnitude 3.5").
        let mut gap_hit: Option<Vec<usize>> = None;
        let mut op_hit = op_before_at(toks, used, i);
        if op_hit.is_none() {
            if let Some((start, olen, op, gap)) = op_before_gap_at(toks, used, i) {
                op_hit = Some((start, olen, op));
                gap_hit = Some(gap);
            }
        }
        if let Some((start, olen, op)) = op_hit {
            let gap = gap_hit.clone().unwrap_or_default();
            let bwd = backward_phrase(toks, used, start);
            let unit_hit = unit_after(toks, i + 1 + sx);
            let compar = comparative_concept(toks, start, olen);
            let fwd = forward_phrase(toks, used, i + 1 + sx, 3);
            let field =
                resolve_comparison(toks, &bwd, unit_hit.map(|(u, _)| u), compar, &fwd, fields)
                    .or_else(|| resolve_field(toks, &gap, fields, |f| f.numeric()))
                    .or_else(|| yearish_fallback(&toks[i], fields));
            let Some(fpos) = field else {
                return Err(comparison_refusal(toks, &bwd, i));
            };
            push_comparison(ctx, &fields[fpos], op, &toks[i], val, &bwd, i, toks);
            for u in &mut used[start..=i + sx] {
                *u = true;
            }
            if let Some((_, uidx)) = unit_hit {
                used[uidx] = true;
            }
            for &b in &fwd {
                used[b] = true;
            }
            for &b in &bwd {
                used[b] = true;
            }
            for &b in &gap {
                used[b] = true;
            }
            i += 1 + sx;
            continue;
        }

        // (4) bare number with a forward field phrase ("2 stars", "single
        // … " handled above). No comparator, no scale.
        let fwd = forward_phrase(toks, used, i + 1, 3);
        if let Some(fpos) = resolve_field(toks, &fwd, fields, |f| f.numeric()) {
            if let Some(v) = toks[i].num_value() {
                let f = &fields[fpos];
                let phrase = format!("{} {}", toks[i].raw, phrase_text(toks, &fwd));
                ctx.constraints.push(Constraint {
                    clause: term_clause(&f.name, v),
                    phrase,
                    via: "literal+field",
                    is_range: false,
                    pos: i,
                });
                used[i] = true;
                for &k in &fwd {
                    used[k] = true;
                }
                i += 1;
                continue;
            }
        }

        // Bare years fall through to the date pass; anything else is named
        // by the leftover pass.
        i += 1;
    }
    Ok(())
}

/// Emit one comparison constraint. Every bound is the prompt's own literal;
/// a year compared against a date field becomes year-wide bounds.
#[allow(clippy::too_many_arguments)]
fn push_comparison(
    ctx: &mut PlanCtx,
    f: &FieldView,
    op: Op,
    tok: &Tok,
    val: Value,
    bwd: &[usize],
    num_i: usize,
    toks: &[Tok],
) {
    let prefix = if bwd.is_empty() {
        String::new()
    } else {
        format!("{} ", phrase_text(toks, bwd))
    };
    if op == Op::Eq {
        ctx.constraints.push(Constraint {
            clause: term_clause(&f.name, val),
            phrase: format!("{prefix}{}", tok.raw),
            via: "literal+field",
            is_range: false,
            pos: bwd.first().copied().unwrap_or(num_i),
        });
    } else if f.date() && is_yearish(tok) {
        // A year compared against a date field: year-wide bounds, still
        // only the prompt's own number.
        let y = tok
            .int_literal
            .unwrap_or_else(|| tok.num_f64().unwrap_or(0.0) as i64);
        let clause = match op {
            Op::Gt => range_clause_1(&f.name, "gt", json!(next_year_start(y))),
            Op::Gte => range_clause_1(&f.name, "gte", json!(year_start(y))),
            Op::Lt => range_clause_1(&f.name, "lt", json!(year_start(y))),
            Op::Lte => range_clause_1(&f.name, "lte", json!(next_year_start(y))),
            Op::Eq => range_clause_2(
                &f.name,
                json!(year_start(y)),
                "gte",
                json!(next_year_start(y)),
                "lt",
            ),
        };
        ctx.constraints.push(Constraint {
            clause,
            phrase: format!("{prefix}{}", tok.raw),
            via: "comparator",
            is_range: true,
            pos: bwd.first().copied().unwrap_or(num_i),
        });
    } else {
        ctx.constraints.push(Constraint {
            clause: range_clause_1(&f.name, op.key(), val),
            phrase: format!("{prefix}{}", tok.raw),
            via: "comparator",
            is_range: true,
            pos: bwd.first().copied().unwrap_or(num_i),
        });
    }
}

/// `<num> and|to|through <num>` after i, plus the from/between connector
/// governing the pair (scanned back over content tokens).
fn pair_at(toks: &[Tok], used: &[bool], i: usize) -> Option<(usize, Option<usize>)> {
    let conn = i + 1;
    if conn + 1 >= toks.len() || used[conn] {
        return None;
    }
    match toks[conn].norm.as_str() {
        "and" | "to" | "through" => {}
        _ => return None,
    }
    let second = conn + 1;
    if second >= toks.len() || used[second] || !toks[second].is_num() {
        return None;
    }
    // connector: scan back over content tokens (up to 4) for from/between
    let mut connector = None;
    let mut j = i;
    let mut steps = 0;
    while j > 0 && steps < 4 {
        j -= 1;
        steps += 1;
        if used[j] {
            break;
        }
        match toks[j].norm.as_str() {
            "between" | "from" => {
                connector = Some(j);
                break;
            }
            _ if FUNCTION_WORDS.contains(&toks[j].norm.as_str()) => continue,
            _ => continue,
        }
    }
    Some((second, connector))
}

/// Scale handling: the effective value of the number at `i` plus how many
/// extra tokens it consumed ("100 million" → (10⁸, 1)).
fn number_span(toks: &[Tok], i: usize) -> (Value, usize) {
    if i + 1 < toks.len() {
        if let Some((_, mult)) = SCALES.iter().find(|(w, _)| toks[i + 1].norm == *w) {
            if let Some(base) = toks[i].int_literal {
                let v = base.saturating_mul(*mult);
                return (json!(v), 1);
            }
            if let Some(f) = toks[i].num_f64() {
                if let Some(n) = serde_json::Number::from_f64(f * (*mult as f64)) {
                    return (Value::Number(n), 1);
                }
            }
        }
    }
    (toks[i].num_value().unwrap_or(Value::Null), 0)
}

/// op phrase starting exactly at `at`.
fn op_after_at(toks: &[Tok], at: usize) -> Option<(usize, Op)> {
    for (words, op) in OP_AFTER {
        if words.iter().enumerate().all(|(k, w)| {
            let idx = at + k;
            idx < toks.len() && toks[idx].norm == *w
        }) {
            return Some((words.len(), *op));
        }
    }
    None
}

/// op phrase ending right before the number at `i`; (start, len, op).
fn op_before_at(toks: &[Tok], used: &[bool], i: usize) -> Option<(usize, usize, Op)> {
    for (words, op) in OP_BEFORE {
        let len = words.len();
        if i < len {
            continue;
        }
        let start = i - len;
        if words
            .iter()
            .enumerate()
            .all(|(k, w)| toks[start + k].norm == *w && !used[start + k])
        {
            return Some((start, len, *op));
        }
    }
    None
}

/// The separated form: op phrase, then the FIELD PHRASE, then the number —
/// "stronger than MAGNITUDE 3.5". Scans the number back over up to 3
/// content tokens to find an op phrase ending before them; the tokens
/// between the op and the number come back as the gap, a field-phrase
/// candidate `op_before_at` alone cannot express. Purely positional, so it
/// stays deterministic.
fn op_before_gap_at(
    toks: &[Tok],
    used: &[bool],
    i: usize,
) -> Option<(usize, usize, Op, Vec<usize>)> {
    for gap_len in 1..=3 {
        // `i - gap_len` must not underflow: a number early in the prompt
        // (gapminder-052: "in 1952, countries…") has no room for a gap at
        // all. Larger gap_len only makes it worse, so stop.
        if i <= gap_len {
            break;
        }
        let number_at = i - gap_len;
        let Some((start, olen, op)) = op_before_at(toks, used, number_at) else {
            continue;
        };
        let gap: Vec<usize> = (start + olen..i).collect();
        if gap
            .iter()
            .any(|&k| used[k] || toks[k].is_num() || toks[k].is_date())
        {
            continue;
        }
        return Some((start, olen, op, gap));
    }
    None
}

/// A unit token at/after `at` (skipping one "of"): (unit key, token index).
/// "Earth radii" is two tokens.
fn unit_after(toks: &[Tok], at: usize) -> Option<(&'static str, usize)> {
    let mut k = at;
    if k < toks.len() && toks[k].norm == "of" {
        k += 1;
    }
    if k >= toks.len() {
        return None;
    }
    let norm = toks[k].norm.as_str();
    if let Some((u, _)) = UNITS.iter().find(|(u, _)| *u == norm) {
        return Some((u, k));
    }
    if norm == "earth" && k + 1 < toks.len() && toks[k + 1].norm == "radii" {
        return Some(("earthradii", k));
    }
    None
}

/// The quantity a comparative adjective names, when the op phrase carries
/// one ("deeper than" → depth).
fn comparative_concept(toks: &[Tok], start: usize, len: usize) -> Option<&'static str> {
    COMPARATIVE_CONCEPTS
        .iter()
        .find(|(w, _)| (start..start + len).any(|k| toks[k].norm == *w))
        .map(|(_, c)| *c)
}

fn is_yearish(t: &Tok) -> bool {
    matches!(t.number, Some(v) if (1500.0..=2100.0).contains(&v) && v == v.trunc())
}

/// Years with a comparator ("2018 or later") fall back to the year/date
/// field — the number is still the prompt's own.
fn yearish_fallback(tok: &Tok, fields: &[FieldView]) -> Option<usize> {
    if is_yearish(tok) {
        year_field(fields)
    } else {
        None
    }
}

/// Copulas/auxiliaries: transparent in the backward scan ("life expectancy
/// WAS below 45" still finds `life expectancy`), unlike other function words
/// which terminate the phrase.
const AUX_WORDS: &[&str] = &[
    "is", "are", "was", "were", "be", "been", "being", "do", "does", "did", "has", "have", "had",
];

/// Content tokens ending just before `stop` (up to 3): the field phrase of
/// a comparison. Function and generic words terminate the scan, auxiliaries
/// are skipped over.
fn backward_phrase(toks: &[Tok], used: &[bool], stop: usize) -> Vec<usize> {
    let mut out = Vec::new();
    let mut j = stop;
    while j > 0 && out.len() < 3 {
        j -= 1;
        if used[j] {
            break;
        }
        let t = &toks[j];
        if AUX_WORDS.contains(&t.norm.as_str()) {
            continue;
        }
        if FUNCTION_WORDS.contains(&t.norm.as_str())
            || GENERIC_WORDS.contains(&t.norm.as_str())
            || t.is_num()
            || t.is_date()
        {
            break;
        }
        out.push(j);
    }
    out.reverse();
    out
}

/// Up to `max` content tokens after `at`; generic words are skipped over —
/// EXCEPT when the generic word itself names a quantity concept ("2 known
/// planets": `planets` → pnum), in which case it joins the phrase, because
/// "at least 2 known planets" carries its field only in that word. Function
/// words end the phrase.
fn forward_phrase(toks: &[Tok], used: &[bool], at: usize, max: usize) -> Vec<usize> {
    let mut out = Vec::new();
    let mut j = at;
    while j < toks.len() && out.len() < max {
        if used[j] {
            break;
        }
        let t = &toks[j];
        if FUNCTION_WORDS.contains(&t.norm.as_str()) {
            break;
        }
        if GENERIC_WORDS.contains(&t.norm.as_str()) {
            let carries_concept = concept_for(&t.norm).is_some();
            if !carries_concept {
                j += 1;
                continue;
            }
        }
        if t.is_num() || t.is_date() {
            break;
        }
        out.push(j);
        j += 1;
    }
    out
}

/// Field resolution for a comparison, in priority order: the unit decides
/// ("6000 K" is a temperature even when the phrase says "stars"), then the
/// backward field phrase, then the comparative's own concept ("deeper"
/// without a phrase still means depth), then the forward phrase ("at least
/// 2 known planets" carries its field after the number).
fn resolve_comparison(
    toks: &[Tok],
    bwd: &[usize],
    unit: Option<&str>,
    compar: Option<&str>,
    fwd: &[usize],
    fields: &[FieldView],
) -> Option<usize> {
    if let Some(u) = unit {
        let targets = UNITS.iter().find(|(key, _)| *key == u).map(|(_, t)| *t)?;
        if let Some(pos) = field_by_tokens(targets, fields, |f| f.numeric()) {
            return Some(pos);
        }
    }
    if let Some(pos) = resolve_field(toks, bwd, fields, |f| f.numeric()) {
        return Some(pos);
    }
    if let Some(c) = compar {
        if let Some(targets) = concept_for(c) {
            if let Some(pos) = field_by_tokens(targets, fields, |f| f.numeric()) {
                return Some(pos);
            }
        }
    }
    resolve_field(toks, fwd, fields, |f| f.numeric())
}

fn comparison_refusal(toks: &[Tok], bwd: &[usize], i: usize) -> Refusal {
    let phrase = if bwd.is_empty() {
        toks[i].raw.clone()
    } else {
        format!("{} {}", phrase_text(toks, bwd), toks[i].raw)
    };
    (
        vec![phrase.clone()],
        format!(
            "comparison on `{phrase}` resolves to no numeric or date field in this index — \
             refusing rather than guessing. Name a field that exists"
        ),
    )
}

fn phrase_text(toks: &[Tok], idxs: &[usize]) -> String {
    idxs.iter()
        .map(|&k| toks[k].raw.clone())
        .collect::<Vec<_>>()
        .join(" ")
}

/// Pass A: date literals (single days and from/through pairs) and bare
/// years with a year connector. Bounds are the prompt's own days/years — a
/// year lands on the year FIELD when one exists (gapminder `year`, nasa
/// `disc_year`) and on the date field's year bounds otherwise.
fn date_pass(
    toks: &[Tok],
    fields: &[FieldView],
    time_field_hint: Option<&str>,
    used: &mut [bool],
    ctx: &mut PlanCtx,
) -> Result<(), Refusal> {
    let dpos = date_field(fields, time_field_hint);
    let ypos = fields
        .iter()
        .position(|f| f.numeric() && f.tokens.iter().any(|t| t == "year"));
    let mut i = 0;
    while i < toks.len() {
        if used[i] {
            i += 1;
            continue;
        }
        if let Some((y, m, d)) = date_parts(&toks[i].raw) {
            let Some(dfield) = dpos.map(|p| &fields[p]) else {
                // No date field: leave the literal to be named by the
                // leftover pass rather than silently dropped.
                i += 1;
                continue;
            };
            // pair: <date1> to|through <date2>
            if i + 2 < toks.len()
                && matches!(toks[i + 1].norm.as_str(), "to" | "through")
                && !used[i + 1]
                && !used[i + 2]
            {
                if let Some((y2, m2, d2)) = date_parts(&toks[i + 2].raw) {
                    ctx.constraints.push(Constraint {
                        clause: range_clause_2(
                            &dfield.name,
                            json!(day_start(y, m, d)),
                            "gte",
                            json!(next_day(y2, m2, d2)),
                            "lt",
                        ),
                        phrase: format!("{} … {}", toks[i].raw, toks[i + 2].raw),
                        via: "date-range",
                        is_range: true,
                        pos: i,
                    });
                    used[i] = true;
                    used[i + 1] = true;
                    used[i + 2] = true;
                    i += 3;
                    continue;
                }
            }
            // single day
            ctx.constraints.push(Constraint {
                clause: range_clause_2(
                    &dfield.name,
                    json!(day_start(y, m, d)),
                    "gte",
                    json!(next_day(y, m, d)),
                    "lt",
                ),
                phrase: toks[i].raw.clone(),
                via: "date-day",
                is_range: true,
                pos: i,
            });
            used[i] = true;
            i += 1;
            continue;
        }
        // bare year with a connector nearby
        if is_yearish(&toks[i]) && year_context(toks, used, i) {
            let y = toks[i].int_literal.unwrap_or_default();
            if let Some(yp) = ypos {
                let f = &fields[yp];
                ctx.constraints.push(Constraint {
                    clause: term_clause(&f.name, json!(y)),
                    phrase: toks[i].raw.clone(),
                    via: "year",
                    is_range: false,
                    pos: i,
                });
                used[i] = true;
                i += 1;
                continue;
            }
            if let Some(dp) = dpos {
                let f = &fields[dp];
                ctx.constraints.push(Constraint {
                    clause: range_clause_2(
                        &f.name,
                        json!(year_start(y)),
                        "gte",
                        json!(next_year_start(y)),
                        "lt",
                    ),
                    phrase: toks[i].raw.clone(),
                    via: "year",
                    is_range: true,
                    pos: i,
                });
                used[i] = true;
                i += 1;
                continue;
            }
        }
        i += 1;
    }
    Ok(())
}

/// Is a year connector adjacent (one token either side) to position i?
fn year_context(toks: &[Tok], used: &[bool], i: usize) -> bool {
    let check = |k: usize| !used[k] && YEAR_CONNECTORS.iter().any(|c| toks[k].norm == *c);
    (i > 0 && check(i - 1)) || (i + 1 < toks.len() && check(i + 1))
}

/// Keyword fields a path constraint may filter, most-specific first.
///
/// `ax_path` is the full root-relative path autoindex stamps on every
/// record. Code indexes also map `path`, but that value is the file name
/// (`worktree.rs`), so a directory prefix has to land on `ax_path` when
/// both exist.
const PATH_FIELDS: &[&str] = &["ax_path", "path", "filepath", "file", "ax_file"];

/// The keyword field a path prefix filters, or `None` when this index has
/// none of [`PATH_FIELDS`].
fn path_field(fields: &[FieldView]) -> Option<usize> {
    PATH_FIELDS.iter().find_map(|name| {
        fields
            .iter()
            .position(|f| f.name == *name && f.categorical())
    })
}

/// A filesystem path named by one prompt token, as the `prefix` value to
/// query, or `None` when `raw` is not a path.
///
/// Whitespace is the only token split, so `crates/herdr-gpui/src` arrives
/// whole. `norm_text` then deletes the slashes, which is why the value pass
/// cannot see it. A directory (last segment has no `.`) gets a trailing
/// slash: prefix `crates/app/src/` matches `crates/app/src/lib.rs` and not
/// `crates/app/src2/lib.rs`. A file (last segment contains `.`) is prefixed
/// as written. `and/or` is grammar, not a path. `http://…` is left for the
/// ordinary passes.
fn path_prefix(raw: &str) -> Option<String> {
    if !raw.contains('/') && !raw.contains('\\') {
        return None;
    }
    let lower = raw.to_ascii_lowercase();
    if lower.starts_with("http://") || lower.starts_with("https://") || lower.starts_with("file://")
    {
        return None;
    }
    let normalized = raw.replace('\\', "/");
    let trimmed = normalized.trim_matches('/');
    let trimmed = trimmed.strip_prefix("./").unwrap_or(trimmed);
    if trimmed.is_empty() {
        return None;
    }
    let segments: Vec<&str> = trimmed.split('/').filter(|s| !s.is_empty()).collect();
    if segments.len() < 2 || !trimmed.chars().any(|c| c.is_ascii_alphabetic()) {
        return None;
    }
    let contentful = segments.iter().any(|seg| {
        let n = norm_text(seg);
        !n.is_empty()
            && !FUNCTION_WORDS.contains(&n.as_str())
            && !GENERIC_WORDS.contains(&n.as_str())
    });
    if !contentful {
        return None;
    }
    let last = segments[segments.len() - 1];
    // Two bare words joined by a slash (`tcp/ip`, `client/server`,
    // `north/south`) are prose, not a path. Only take a token as a path when
    // it says so: three or more segments, a file extension on the last
    // segment, or a leading `./` `/` `~/` or trailing slash.
    let has_ext = last.rsplit_once('.').is_some_and(|(stem, ext)| {
        !stem.is_empty() && !ext.is_empty() && ext.chars().all(|c| c.is_ascii_alphanumeric())
    });
    let anchored = normalized.starts_with("./")
        || normalized.starts_with('/')
        || normalized.starts_with("~/")
        || normalized.ends_with('/');
    if segments.len() < 3 && !has_ext && !anchored {
        return None;
    }
    if last.contains('.') {
        Some(trimmed.to_string())
    } else {
        Some(format!("{trimmed}/"))
    }
}

/// Pass P: ground each path token as a keyword prefix. Tokens stay unused
/// when the index has no path field, so [`settle_leftovers`] can refuse
/// them by name instead of filing them as decoration.
fn path_pass(toks: &[Tok], fields: &[FieldView], used: &mut [bool], ctx: &mut PlanCtx) {
    let Some(fpos) = path_field(fields) else {
        return;
    };
    let field = fields[fpos].name.clone();
    for (i, t) in toks.iter().enumerate() {
        if used[i] {
            continue;
        }
        let Some(prefix) = path_prefix(&t.raw) else {
            continue;
        };
        ctx.constraints.push(Constraint {
            clause: prefix_clause(&field, &prefix),
            phrase: t.raw.clone(),
            via: "path-prefix",
            is_range: false,
            pos: i,
        });
        used[i] = true;
    }
}

/// Pass C: equality against the live value map. Returns the leftover runs
/// it could not ground, for the decoration/refusal decision.
async fn value_pass(
    toks: &[Tok],
    fields: &[FieldView],
    used: &mut [bool],
    ctx: &mut PlanCtx,
    idx: &Arc<Index>,
    probes: &mut usize,
) -> Vec<Vec<usize>> {
    let mut unresolved: Vec<Vec<usize>> = Vec::new();
    // Leftover runs: contiguous content tokens (function and generic words
    // break, so the value phrase inside "… for cities in Switzerland" and
    // "the ak network" survives on its own).
    let mut runs: Vec<Vec<usize>> = Vec::new();
    let mut cur: Vec<usize> = Vec::new();
    for (k, t) in toks.iter().enumerate() {
        if used[k]
            || FUNCTION_WORDS.contains(&t.norm.as_str())
            || GENERIC_WORDS.contains(&t.norm.as_str())
        {
            if !cur.is_empty() {
                runs.push(mem::take(&mut cur));
            }
        } else {
            cur.push(k);
        }
    }
    if !cur.is_empty() {
        runs.push(cur);
    }

    'runs: for run in runs {
        // (a) field + value split ("magnitude type mb" with a non-generic
        // "type", "continent Europe")
        for split in (1..run.len()).rev() {
            let (left, right) = run.split_at(split);
            let Some(fpos) = resolve_field(toks, left, fields, |f| f.categorical()) else {
                continue;
            };
            let f = &fields[fpos];
            let joined = right
                .iter()
                .map(|&k| toks[k].norm.clone())
                .collect::<String>();
            if let Some(v) = ctx.lookup_exact(&f.name, &joined) {
                ctx.constraints.push(Constraint {
                    clause: term_clause(&f.name, v),
                    phrase: phrase_text(toks, &run),
                    via: "field+value",
                    is_range: false,
                    pos: run[0],
                });
                for &k in &run {
                    used[k] = true;
                }
                continue 'runs;
            }
            // BM25 arm: the field's values did not fit the agg.
            if !ctx.complete(&f.name) && *probes < MAX_BM25_PROBES {
                let phrase = phrase_text(toks, right);
                if let Some(clause) = ctx.bm25_probe(idx, &f.name, &phrase).await {
                    *probes += 1;
                    ctx.soft += 1;
                    ctx.constraints.push(Constraint {
                        clause,
                        phrase,
                        via: "field+value-bm25",
                        is_range: false,
                        pos: run[0],
                    });
                    for &k in &run {
                        used[k] = true;
                    }
                    continue 'runs;
                }
            }
        }
        // (b) value alone, longest subrun first, fields in name order;
        // prefix matching covers adjectival forms ("European" → "Europe").
        for len in (1..=run.len()).rev() {
            for start in 0..=(run.len() - len) {
                let sub = &run[start..start + len];
                let joined = sub
                    .iter()
                    .map(|&k| toks[k].norm.clone())
                    .collect::<String>();
                let mut hit: Option<(String, Value, bool)> = None;
                for fname in ctx.values.keys() {
                    if let Some(v) = ctx.lookup_exact(fname, &joined) {
                        hit = Some((fname.clone(), v, false));
                        break;
                    }
                    if let Some(v) = ctx.lookup_prefix(fname, &joined) {
                        if hit.is_none() {
                            hit = Some((fname.clone(), v, true));
                        }
                    }
                }
                if let Some((fname, v, soft)) = hit {
                    if soft {
                        ctx.soft += 1;
                    }
                    ctx.constraints.push(Constraint {
                        clause: term_clause(&fname, v),
                        phrase: phrase_text(toks, sub),
                        via: if soft { "value-prefix" } else { "value" },
                        is_range: false,
                        pos: sub[0],
                    });
                    for &k in sub {
                        used[k] = true;
                    }
                    continue 'runs;
                }
            }
        }
        unresolved.push(run);
    }
    unresolved
}

/// The decoration/refusal decision over the runs the passes could not
/// ground. A capitalized (proper-noun) run is a 422 naming it; so is any
/// multi-token run, and any run at all when nothing else grounded the
/// prompt. A single lowercase token next to a resolved constraint is
/// decoration, reported in the plan.
fn settle_leftovers(
    toks: &[Tok],
    unresolved: &[Vec<usize>],
    grounded: bool,
    ctx: &mut PlanCtx,
) -> Result<(), Refusal> {
    if unresolved.is_empty() {
        return Ok(());
    }
    for run in unresolved {
        // A path is a constraint the caller asked for. Dropping it as a
        // lowercase modifier returns a different document set and says only
        // that a modifier was ignored (#2120).
        if let Some(path) = run
            .iter()
            .find_map(|&k| path_prefix(&toks[k].raw).map(|_| toks[k].raw.clone()))
        {
            return Err((
                vec![path.clone()],
                format!(
                    "phrase `{path}` looks like a file path, but this index has no keyword \
                     field named ax_path, path, filepath, file, or ax_file to filter on — \
                     refusing rather than dropping the path. Map one of those fields, or \
                     remove the path from the prompt"
                ),
            ));
        }
        let single = run.len() == 1;
        let capitalized = toks[run[0]].capitalized;
        if capitalized || !single || !grounded {
            let phrase = phrase_text(toks, run);
            return Err((
                vec![phrase.clone()],
                format!(
                    "phrase `{phrase}` resolves to no field and no value in this index — \
                     refusing rather than guessing. Name a field that exists, or a value \
                     the index holds"
                ),
            ));
        }
        ctx.ignored.push(phrase_text(toks, run));
    }
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests for the pure pieces (route-level tests: tests/ask_endpoint.rs)
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn glob_matches_star_and_exact() {
        assert!(glob_match("ax-*", "ax-usgs-earthquakes"));
        assert!(glob_match("ax-*", "ax-"));
        assert!(!glob_match("ax-*", "sales"));
        assert!(glob_match("ax-quakes", "ax-quakes"));
        assert!(!glob_match("ax-quakes", "ax-quakes2"));
        assert!(glob_match("*", "anything"));
        assert!(glob_match("a*b*c", "aXXbYYc"));
        assert!(!glob_match("a*b*c", "aXXbYY"));
    }

    #[test]
    fn name_tokens_splits_snake_and_camel() {
        assert_eq!(name_tokens("pl_orbper"), vec!["pl", "orbper"]);
        assert_eq!(name_tokens("lifeExp"), vec!["life", "exp"]);
        assert_eq!(name_tokens("st_teff"), vec!["st", "teff"]);
        assert_eq!(name_tokens("magType"), vec!["mag", "type"]);
        assert_eq!(name_tokens("gdpPercap"), vec!["gdp", "percap"]);
    }

    #[test]
    fn date_parts_validates() {
        assert_eq!(date_parts("2026-09-01"), Some((2026, 9, 1)));
        assert_eq!(date_parts("2026-13-01"), None);
        assert_eq!(date_parts("2026-9-1"), Some((2026, 9, 1)));
        assert_eq!(date_parts("1992"), None);
        assert_eq!(day_start(2026, 9, 1), "2026-09-01T00:00:00Z");
        assert_eq!(next_day(2026, 9, 1), "2026-09-02T00:00:00Z");
        assert_eq!(next_day(2026, 12, 31), "2027-01-01T00:00:00Z");
    }

    #[test]
    fn tokenizer_marks_numbers_years_and_dates() {
        let t = tokenize("events deeper than 50 km on 2026-09-01 (UTC)");
        let nums: Vec<&Tok> = t.iter().filter(|x| x.is_num()).collect();
        assert_eq!(nums.len(), 1);
        assert_eq!(nums[0].int_literal, Some(50));
        let dates: Vec<&Tok> = t.iter().filter(|x| x.is_date()).collect();
        assert_eq!(dates.len(), 1);
        assert_eq!(dates[0].raw, "2026-09-01");
        // parens trimmed off UTC, which is a function word
        assert!(t.iter().any(|x| x.raw == "UTC"));
    }

    #[test]
    fn number_span_applies_scale_words() {
        let t = tokenize("population above 100 million");
        let i = t.iter().position(|x| x.int_literal == Some(100)).unwrap();
        let (v, extra) = number_span(&t, i);
        assert_eq!(v, json!(100_000_000));
        assert_eq!(extra, 1);
        let t = tokenize("magnitude 4.5");
        let i = t.iter().position(|x| x.number == Some(4.5)).unwrap();
        let (v, extra) = number_span(&t, i);
        assert_eq!(v, json!(4.5));
        assert_eq!(extra, 0);
    }

    #[test]
    fn concept_table_prefers_the_longest_phrase() {
        assert_eq!(concept_for("magnitudetype"), Some(&["magtype"][..]));
        assert_eq!(concept_for("magnitude"), Some(&["mag"][..]));
        assert_eq!(concept_for("lifeexpectancy"), Some(&["lifeexp"][..]));
        assert_eq!(concept_for("orbitalperiods"), Some(&["orbper"][..]));
        assert_eq!(concept_for("population"), Some(&["pop"][..]));
        assert_eq!(concept_for("gdppercapita"), Some(&["gdppercap"][..]));
        assert_eq!(concept_for("nothingknown"), None);
    }

    #[test]
    fn path_prefix_is_a_directory_or_a_file() {
        assert_eq!(
            path_prefix("crates/herdr-gpui/src"),
            Some("crates/herdr-gpui/src/".into())
        );
        // A trailing slash is the same directory. A sibling prefix is not.
        assert_eq!(
            path_prefix("crates/herdr-gpui/src/"),
            Some("crates/herdr-gpui/src/".into())
        );
        assert_eq!(
            path_prefix(r"crates\herdr-gpui\src"),
            Some("crates/herdr-gpui/src/".into())
        );
        assert_eq!(
            path_prefix("crates/herdr-gpui/src/worktree.rs"),
            Some("crates/herdr-gpui/src/worktree.rs".into())
        );
        assert_eq!(path_prefix("./src/lib.rs"), Some("src/lib.rs".into()));
        // Grammar, dates, and URLs are not paths.
        assert_eq!(path_prefix("and/or"), None);
        assert_eq!(path_prefix("2026/09/01"), None);
        assert_eq!(path_prefix("https://example.com/a"), None);
        assert_eq!(path_prefix("rust"), None);
        // Two bare words joined by a slash are prose, not a path.
        assert_eq!(path_prefix("tcp/ip"), None);
        assert_eq!(path_prefix("client/server"), None);
        assert_eq!(path_prefix("src/lib.rs"), Some("src/lib.rs".into()));
        assert_eq!(path_prefix("app/src/"), Some("app/src/".into()));
    }

    #[test]
    fn path_field_prefers_ax_path_over_the_filename_field() {
        let fields = vec![
            FieldView::new("path".into(), "keyword"),
            FieldView::new("ax_path".into(), "keyword"),
            FieldView::new("language".into(), "keyword"),
            FieldView::new("body".into(), "text"),
        ];
        assert_eq!(fields[path_field(&fields).unwrap()].name, "ax_path");
        let filename_only = vec![FieldView::new("path".into(), "keyword")];
        assert_eq!(fields_name(&filename_only), "path");
        assert!(path_field(&[FieldView::new("language".into(), "keyword")]).is_none());
        // A text `path` is not a keyword prefix target.
        assert!(path_field(&[FieldView::new("path".into(), "text")]).is_none());
    }

    fn fields_name(fields: &[FieldView]) -> &str {
        &fields[path_field(fields).unwrap()].name
    }

    #[test]
    fn value_agg_fields_orders_by_cardinality_then_name() {
        let mut fields = vec![
            FieldView::new("continent".to_string(), "keyword"),
            FieldView::new("country".into(), "keyword"),
            FieldView::new("place".into(), "keyword"),
            FieldView::new("mag".into(), "double"),
        ];
        fields[2].cardinality_est = Some(5); // place, lowest
        fields[0].cardinality_est = Some(50);
        let got = value_agg_fields(&fields);
        assert_eq!(got, vec!["place", "continent", "country"]);
    }
}

//! Request-level write auditing — issue #329.
//!
//! ## The gap this closes
//!
//! `xerj_engine::audit` has been a real hash-chained, restart-surviving log
//! since #201, but there were exactly four `audit.append` call sites in the
//! whole API surface: `_search`, and the three `_security/api_key` operations.
//! Indexing, updates, deletes, bulk, index creation and index deletion produced
//! **nothing**. An auditor asking "did anyone change this record" got an empty
//! answer, and `audit.rs`'s own module doc had to say that an absent entry was
//! not evidence a write had not happened. That is the whole enterprise ask, and
//! it was the one thing the feature could not do.
//!
//! ## Why a middleware and not `append` at each handler
//!
//! Because the same reasoning that put authorization in [`crate::authz`]'s
//! middleware and in the engine's index funnel applies here: *a handler cannot
//! forget a check it does not make*. `es_compat.rs` alone is ~37k lines with
//! dozens of mutating handlers and several return points each; a hand-placed
//! `append` per success path is a list that is wrong the day someone adds a
//! route. `POST /v1/indices/{name}/syslog` is a write nobody would have
//! remembered.
//!
//! This is also how the reference implementation does it. Elasticsearch emits
//! its audit trail from the security filter layer, not from REST handlers:
//! `AuditTrail`'s vocabulary is request-shaped and outcome-shaped
//! (`accessGranted` / `accessDenied` / `authenticationSuccess`, one per request
//! id — `x-pack/plugin/security/…/audit/AuditTrail.java:26-60`), and
//! `LoggingAuditTrail.accessGranted` records subject + action + the indices
//! pulled off the request (`…/audit/logfile/LoggingAuditTrail.java:687-723`,
//! `AuditUtil.indices`, `…/audit/AuditUtil.java:40-44`). Read for the design
//! only — Elasticsearch is Elastic-2.0/AGPL/SSPL, no code from it is in xerj —
//! and the mechanics here are our own: axum middleware over our `Principal`,
//! writing our ring.
//!
//! ## What it records, and what it deliberately does not
//!
//! * **One entry per request, never per document.** The ring holds
//!   [`xerj_engine::audit::DEFAULT_AUDIT_CAPACITY`] entries; auditing per
//!   document would let one bulk ingest evict every other event on the node,
//!   which is the retention question issue #329 raised. A bulk is one entry
//!   whose note carries the item counts ([`AuditNote`]).
//! * **Every mutation; reads only when refused.** A successful read is not
//!   worth a slot in a shared ring — `_search` keeps its own append, which can
//!   say `took`/`hits`, and auditing every `GET /_cluster/health` from a k8s
//!   probe would flush the writes out. A read that came back `403` *is*
//!   recorded, because a credential reaching for data it does not hold is the
//!   event an auditor is looking for, and because the handler that would have
//!   logged a denied search never runs.
//! * **Authenticated requests only.** This layer sits *inside*
//!   `auth_middleware`, so a 401 leaves no entry. An unauthenticated flood
//!   would otherwise be a one-request-per-line way to evict the evidence from
//!   a bounded ring; the credential-less case is already a clean 401 and is
//!   visible in the access log.
//! * **Denials are entries too.** The layer sits *outside*
//!   [`crate::authz::authz_middleware`], so a refused write is recorded with
//!   `outcome: "denied"`. "Nothing happened" and "someone tried and was
//!   stopped" are different answers to an auditor.
//!
//! Cost is one SHA-256 over a short entry plus one `write(2)` per mutating
//! request — the tax `_search` has always paid, now paid by writes too, and
//! amortised over a whole bulk rather than charged per document.

use axum::extract::{Request, State};
use axum::http::{header, Method, StatusCode};
use axum::middleware::Next;
use axum::response::Response;

use crate::auth::authenticate;
use crate::state::AppState;

/// Extra context a handler wants on its audit entry, passed back through the
/// response extensions.
///
/// The middleware knows the request; only the handler knows how much work it
/// turned into. `process_bulk_body` uses this to report item counts, so a bulk
/// entry says `items=200 failed=0` instead of just `status=200`.
#[derive(Clone, Debug)]
pub struct AuditNote(pub String);

/// What a request is, in audit terms: the op tag and the resource it names.
struct Audited {
    op: String,
    resource: String,
    /// Record this one **only** if it was refused.
    ///
    /// True for reads. A successful read is not evidence anyone needs at the
    /// cost of a ring slot — `_search` keeps its own entry, and auditing every
    /// `GET /_cluster/health` would evict the writes. A read that came back
    /// `403` is a different thing: someone with a credential reached for data
    /// they do not hold, and that is exactly what an auditor is looking for.
    /// It is also the only way a *denied* search gets recorded at all, since
    /// the handler that would have appended never runs.
    only_if_denied: bool,
    /// The handler writes its own entries (`_security/api_key`, `_share`), so
    /// record this one **only** when the request never reached it — i.e. the
    /// response carries [`crate::authz::RefusedBeforeHandler`].
    ///
    /// These paths used to be skipped outright, on the reasoning that the
    /// handler audits them. It does — when it runs. A share-link guest's
    /// `POST /_share`, `DELETE /_share/{handle}` and `POST /_security/api_key`
    /// are refused by the authorization middleware, so neither layer wrote a
    /// line for the very requests that are attempts to widen a credential
    /// (review of PR #947: four such calls, zero entries).
    handler_audits: bool,
}

/// Path segments, empty ones dropped.
fn segments(path: &str) -> Vec<&str> {
    path.split('/').filter(|s| !s.is_empty()).collect()
}

/// Endpoints that read despite being reached with a mutating method.
///
/// ES uses POST for most reads, so this is the list that keeps a search out of
/// the write log. A name missing from it is a *noisy* entry (an op tagged after
/// the endpoint), never a missing one — the failure direction we want, since
/// the bug being fixed is silence.
fn is_read_shaped(seg: &str) -> bool {
    matches!(
        seg,
        "_search"
            | "_msearch"
            | "_search_scroll"
            | "scroll"
            | "_count"
            | "_mget"
            | "_explain"
            | "explain-plan"
            | "_analyze"
            | "_validate"
            | "_field_caps"
            | "_knn_search"
            | "_terms_enum"
            | "_rank_eval"
            | "_resolve"
            | "_sql"
            | "_render"
            | "_simulate"
            | "_disk_usage"
            | "_recovery"
            | "_stats"
            | "search"
            | "encodings"
    )
}

/// The verb suffix for an endpoint with no better name.
fn verb(method: &Method) -> &'static str {
    match *method {
        Method::PUT => "put",
        Method::POST => "post",
        Method::DELETE => "delete",
        Method::PATCH => "patch",
        _ => "write",
    }
}

/// Classify a request into an audit op + resource, or `None` to skip it.
///
/// Handles both routers, because both reach the same data: the ES-compat
/// spelling puts the index first (`/{index}/_doc/{id}`) and the native one
/// nests it (`/v1/indices/{index}/docs/{id}`).
fn classify(method: &Method, path: &str) -> Option<Audited> {
    let segs = segments(path);
    if segs.is_empty() {
        return None;
    }
    // The three `_security/api_key` operations append their own entries (with
    // a `sync_to_disk` barrier a generic layer should not impose on every
    // write); auditing them here as well would double every one. What the
    // handler cannot record is a request that never reached it.
    if segs.first() == Some(&"_security") && segs.get(1) == Some(&"api_key") {
        let op = match *method {
            Method::GET | Method::HEAD => "security.api_key.get",
            Method::DELETE => "security.api_key.invalidate",
            _ => "security.api_key.create",
        };
        return Some(Audited {
            op: op.to_string(),
            resource: "_security/api_key".to_string(),
            only_if_denied: true,
            handler_audits: true,
        });
    }
    // Share links audit themselves with the outcome detail that matters
    // (which share, wrong passcode vs exhausted vs throttled, the source
    // address of an unauthenticated claim) — see `crate::share`. Same rule:
    // only the requests the handler never saw are recorded here.
    if segs.first() == Some(&"_share") {
        return Some(classify_share(method, &segs));
    }
    // `/_xerj-console/*` is a separate application mounted at the server level
    // with its own `.xerj_audit` trail; the SPA's own traffic is not node data.
    if segs.first() == Some(&"_xerj-console") {
        return None;
    }
    let mutating = matches!(
        *method,
        Method::PUT | Method::POST | Method::DELETE | Method::PATCH
    );
    // A read — by method, or by one of the endpoints ES spells with POST. It
    // earns an entry only when it was refused; see [`Audited::only_if_denied`].
    if !mutating || segs.iter().any(|s| is_read_shaped(s)) {
        return classify_read(&segs);
    }

    // Native router: /v1/indices/{name}/…
    if segs.first() == Some(&"v1") {
        return classify_native(method, &segs);
    }

    let index = segs[0];
    // `PUT /{index}` / `DELETE /{index}` — the whole index.
    if segs.len() == 1 && !index.starts_with('_') {
        let op = match *method {
            Method::DELETE => "index.delete",
            _ => "index.create",
        };
        return Some(Audited {
            op: op.to_string(),
            resource: index.to_string(),
            only_if_denied: false,
            handler_audits: false,
        });
    }
    // The endpoint keyword is the first `_`-prefixed segment.
    let keyword = segs.iter().find(|s| s.starts_with('_')).copied()?;
    let op = match (keyword, method) {
        ("_doc", &Method::DELETE) => "delete".to_string(),
        ("_doc", _) => "index".to_string(),
        ("_create", _) => "create".to_string(),
        ("_update", _) => "update".to_string(),
        ("_bulk", _) => "bulk".to_string(),
        ("_delete_by_query", _) => "delete_by_query".to_string(),
        ("_update_by_query", _) => "update_by_query".to_string(),
        ("_reindex", _) => "reindex".to_string(),
        (k, m) => format!("{}.{}", k.trim_start_matches('_'), verb(m)),
    };
    // `segs[0]` is the index when the path is index-scoped (`/payroll/_doc/1`)
    // and the endpoint itself when it is not (`/_bulk`, `/_aliases`,
    // `/_reindex`). Both are recorded as-is: an entry that reported a *guessed*
    // index — parsed out of a bulk body that may name a dozen — would be worse
    // evidence than one that says plainly which endpoint was called. The
    // per-index truth for those requests is in the response the caller got, and
    // authorization over body-named indices is `authz`'s job, not this layer's.
    Some(Audited {
        op,
        resource: index.to_string(),
        only_if_denied: false,
        handler_audits: false,
    })
}

/// `/_share/…`, with the op tags `crate::share` uses for the same routes.
///
/// The resource is `_share`, or the share's public **handle** when the path
/// names one. Never any other path segment: `DELETE /_share/{id}` also accepts
/// the full share id, and the audit log must not be the place a share id is
/// written down.
fn classify_share(method: &Method, segs: &[&str]) -> Audited {
    let op = match (method, segs.get(1).copied()) {
        (&Method::POST, None) => "share.create",
        (&Method::GET, None) | (&Method::HEAD, None) => "share.list",
        (&Method::POST, Some("claim")) => "share.claim",
        (&Method::DELETE, Some(_)) => "share.revoke",
        _ => "share.other",
    };
    let is_handle = |s: &str| s.len() == 12 && s.bytes().all(|b| b.is_ascii_hexdigit());
    let resource = match segs.get(1).copied() {
        Some(handle) if segs.len() == 2 && is_handle(handle) => handle.to_string(),
        _ => "_share".to_string(),
    };
    Audited {
        op: op.to_string(),
        resource,
        only_if_denied: true,
        handler_audits: true,
    }
}

/// A read, described well enough to be worth an entry **if it was refused**.
///
/// The op tag matches what the successful path would have written — a denied
/// search is `op: "search", outcome: "denied"`, next to the searches that were
/// allowed — so an auditor filtering by op sees both halves of the story.
fn classify_read(segs: &[&str]) -> Option<Audited> {
    // Reaching for the audit log itself gets its own op rather than the generic
    // `search`/`verify` the keyword rule below would produce: a refused attempt
    // to read the evidence is the denied read an auditor most wants to find,
    // and it must not read like a denied data search.
    if let ["_audit", tail @ ..] = segs {
        return Some(Audited {
            op: format!(
                "audit.{}",
                tail.first().unwrap_or(&"read").trim_start_matches('_')
            ),
            resource: "_audit".to_string(),
            only_if_denied: true,
            handler_audits: false,
        });
    }
    let (op, resource) = match segs {
        // Native router: /v1/indices/{name}/search and friends.
        ["v1", "indices", name, tail @ ..] => (
            tail.last()
                .copied()
                .unwrap_or("read")
                .trim_start_matches('_'),
            (*name).to_string(),
        ),
        [first, rest @ ..] => {
            let keyword = rest
                .iter()
                .chain(std::iter::once(first))
                .find(|s| s.starts_with('_'))
                .copied()
                .unwrap_or("_read");
            (keyword.trim_start_matches('_'), (*first).to_string())
        }
        [] => return None,
    };
    Some(Audited {
        op: op.to_string(),
        resource,
        only_if_denied: true,
        handler_audits: false,
    })
}

/// `/v1/…` — the native router's spelling of the same writes.
fn classify_native(method: &Method, segs: &[&str]) -> Option<Audited> {
    match segs {
        // POST /v1/indices — create, named in the body.
        ["v1", "indices"] => Some(Audited {
            op: "index.create".to_string(),
            resource: "_indices".to_string(),
            only_if_denied: false,
            handler_audits: false,
        }),
        ["v1", "indices", name] => Some(Audited {
            op: if *method == Method::DELETE {
                "index.delete".to_string()
            } else {
                format!("index.{}", verb(method))
            },
            resource: (*name).to_string(),
            only_if_denied: false,
            handler_audits: false,
        }),
        ["v1", "indices", name, tail @ ..] => {
            let op = match tail {
                ["docs"] | ["logs"] | ["otlp"] | ["syslog"] | ["turbo-ingest"] | ["ingest"] => {
                    "index".to_string()
                }
                ["docs", "_bulk"] => "bulk".to_string(),
                ["docs", _id] if *method == Method::DELETE => "delete".to_string(),
                ["docs", _id] => "index".to_string(),
                other => format!(
                    "{}.{}",
                    other
                        .last()
                        .copied()
                        .unwrap_or("index")
                        .trim_start_matches('_'),
                    verb(method)
                ),
            };
            Some(Audited {
                op,
                resource: (*name).to_string(),
                only_if_denied: false,
                handler_audits: false,
            })
        }
        ["v1", rest @ ..] => Some(Audited {
            op: format!(
                "{}.{}",
                rest.join(".").trim_start_matches('_'),
                verb(method)
            ),
            resource: format!("/v1/{}", rest.join("/")),
            only_if_denied: false,
            handler_audits: false,
        }),
        _ => None,
    }
}

/// The `subject` an entry records: whoever the `Authorization` header resolves
/// to. A header that resolves to nothing is `"unauthenticated"` — reachable
/// only if this layer is ever mounted without `auth_middleware` above it, or if
/// the credential was invalidated between the request and the entry.
fn subject_of(state: &AppState, header: Option<&header::HeaderValue>) -> String {
    authenticate(state, header.and_then(|v| v.to_str().ok()))
        .label()
        .to_string()
}

/// `ok` / `denied` / `error`, from the status the caller actually got.
///
/// A bulk that returns 200 with per-item failures is `ok` at this layer and
/// says so in its note — the request was accepted and did write; the items
/// that did not are in the response the caller already has.
fn outcome_of(status: StatusCode) -> &'static str {
    if status.is_success() || status.is_redirection() {
        "ok"
    } else if status == StatusCode::FORBIDDEN {
        "denied"
    } else {
        "error"
    }
}

/// Record one audit entry per authenticated, mutating request.
///
/// Mounted **outside** [`crate::authz::authz_middleware`] (so refusals are
/// recorded) and **inside** `auth_middleware` (so an unauthenticated flood
/// cannot evict the log). See the module docs for the full reasoning.
pub async fn audit_middleware(State(state): State<AppState>, req: Request, next: Next) -> Response {
    let Some(audited) = classify(req.method(), req.uri().path()) else {
        return next.run(req).await;
    };
    // Resolving the caller is not free: `authenticate` hashes the presented
    // secret under the key record's salt (`auth::check_minted_key` → SHA-256).
    // A write is recorded whatever the outcome, so it resolves *before* the
    // handler — the subject has to be the credential in force when the change
    // happened, not one re-derived after a concurrent `_security/api_key`
    // invalidation. A read is recorded only when it is refused, so resolving it
    // up front would burn a hash per search and throw the answer away; the
    // header is carried instead (a `HeaderValue` clone is a refcount bump on
    // its `Bytes`, not a copy) and resolved on the 403 path only.
    //
    // Either way it is re-derived from the header rather than read from a
    // request extension, for the same reason `Principal`'s extractor is: this
    // layer must name the right subject even if it is ever mounted without the
    // authn layer above it.
    let mut subject = None;
    let mut deferred = None;
    if audited.only_if_denied {
        deferred = req.headers().get(header::AUTHORIZATION).cloned();
    } else {
        subject = Some(subject_of(&state, req.headers().get(header::AUTHORIZATION)));
    }

    let response = next.run(req).await;

    // A self-auditing route is recorded here only when its handler never ran.
    if audited.handler_audits
        && response
            .extensions()
            .get::<crate::authz::RefusedBeforeHandler>()
            .is_none()
    {
        return response;
    }
    // A read that succeeded is not recorded: the ring is small, shared, and
    // better spent on changes and refusals.
    if audited.only_if_denied && response.status() != StatusCode::FORBIDDEN {
        return response;
    }
    let subject = subject.unwrap_or_else(|| subject_of(&state, deferred.as_ref()));

    let note = response
        .extensions()
        .get::<AuditNote>()
        .map(|n| n.0.clone())
        .unwrap_or_else(|| format!("status={}", response.status().as_u16()));
    state.engine.audit.append(
        &audited.op,
        &subject,
        &audited.resource,
        outcome_of(response.status()),
        &note,
    );
    response
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A request that earns an entry whatever the outcome (i.e. a write).
    fn c(method: Method, path: &str) -> Option<(String, String)> {
        classify(&method, path)
            .filter(|a| !a.only_if_denied)
            .map(|a| (a.op, a.resource))
    }

    /// A request recorded only when it is refused (i.e. a read).
    fn denied_only(method: Method, path: &str) -> Option<(String, String)> {
        classify(&method, path)
            .filter(|a| a.only_if_denied)
            .map(|a| (a.op, a.resource))
    }

    #[test]
    fn document_writes_are_classified() {
        assert_eq!(
            c(Method::PUT, "/payroll/_doc/1"),
            Some(("index".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::POST, "/payroll/_doc"),
            Some(("index".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::DELETE, "/payroll/_doc/1"),
            Some(("delete".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::POST, "/payroll/_update/1"),
            Some(("update".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::PUT, "/payroll/_create/1"),
            Some(("create".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::POST, "/payroll/_bulk"),
            Some(("bulk".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::POST, "/_bulk"),
            Some(("bulk".into(), "_bulk".into()))
        );
        assert_eq!(
            c(Method::PUT, "/payroll"),
            Some(("index.create".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::DELETE, "/payroll"),
            Some(("index.delete".into(), "payroll".into()))
        );
        assert_eq!(
            c(Method::POST, "/payroll/_delete_by_query"),
            Some(("delete_by_query".into(), "payroll".into()))
        );
    }

    /// The `_search` entry is appended by the handler, which can report
    /// `took`/`hits`; a second one from here would double every search.
    #[test]
    fn reads_are_not_write_audited() {
        assert_eq!(c(Method::POST, "/payroll/_search"), None);
        assert_eq!(c(Method::POST, "/_msearch"), None);
        assert_eq!(c(Method::POST, "/payroll/_count"), None);
        assert_eq!(c(Method::GET, "/payroll/_doc/1"), None);
        assert_eq!(c(Method::HEAD, "/payroll"), None);
        assert_eq!(c(Method::POST, "/v1/indices/payroll/search"), None);
    }

    /// …but a refused one is recorded, under the op the allowed path uses, so
    /// an auditor filtering `op: search` sees the attempts as well as the hits.
    #[test]
    fn refused_reads_are_recorded() {
        assert_eq!(
            denied_only(Method::POST, "/payroll/_search"),
            Some(("search".into(), "payroll".into()))
        );
        assert_eq!(
            denied_only(Method::GET, "/payroll/_doc/1"),
            Some(("doc".into(), "payroll".into()))
        );
        assert_eq!(
            denied_only(Method::POST, "/v1/indices/payroll/search"),
            Some(("search".into(), "payroll".into()))
        );
        // A write is never in this bucket — it is recorded either way.
        assert_eq!(denied_only(Method::PUT, "/payroll/_doc/1"), None);
    }

    /// A refused reach for the audit log is the denied read that matters most,
    /// and it must not be filed under the same op as a denied data search.
    #[test]
    fn a_refused_audit_read_is_its_own_op() {
        assert_eq!(
            denied_only(Method::GET, "/_audit/_search"),
            Some(("audit.search".into(), "_audit".into()))
        );
        assert_eq!(
            denied_only(Method::GET, "/_audit/_verify"),
            Some(("audit.verify".into(), "_audit".into()))
        );
        // Reading the log successfully is not itself an entry — it would
        // append one row per poll to the ring it is reading.
        assert_eq!(c(Method::GET, "/_audit/_search"), None);
    }

    /// The api-key operations audit themselves, with a durability barrier this
    /// layer must not impose on every write.
    #[test]
    fn the_api_key_ops_are_not_double_audited() {
        assert_eq!(c(Method::POST, "/_security/api_key"), None);
        assert_eq!(c(Method::DELETE, "/_security/api_key"), None);
        // …but the rest of the security surface is not exempt.
        assert_eq!(
            c(Method::PUT, "/_security/role/auditor"),
            Some(("security.put".into(), "_security".into()))
        );
    }

    /// A self-auditing route: `(op, resource)` when the layer would record a
    /// request the handler never saw, `None` when it would not look at all.
    fn upstream_refusal(method: Method, path: &str) -> Option<(String, String)> {
        classify(&method, path)
            .filter(|a| a.handler_audits && a.only_if_denied)
            .map(|a| (a.op, a.resource))
    }

    /// Review of PR #947: a share-link guest's `POST /_share`, `GET /_share`,
    /// `DELETE /_share/{handle}` and `POST /_security/api_key` were refused in
    /// the authorization middleware and recorded by nobody, because this layer
    /// skipped both prefixes outright. They are classified now — as entries
    /// that are written only for a request the handler never saw.
    #[test]
    fn self_auditing_routes_are_recorded_when_the_handler_never_ran() {
        assert_eq!(
            upstream_refusal(Method::POST, "/_share"),
            Some(("share.create".into(), "_share".into()))
        );
        assert_eq!(
            upstream_refusal(Method::GET, "/_share"),
            Some(("share.list".into(), "_share".into()))
        );
        assert_eq!(
            upstream_refusal(Method::DELETE, "/_share/1a2b3c4d5e6f"),
            Some(("share.revoke".into(), "1a2b3c4d5e6f".into()))
        );
        assert_eq!(
            upstream_refusal(Method::POST, "/_share/claim"),
            Some(("share.claim".into(), "_share".into()))
        );
        assert_eq!(
            upstream_refusal(Method::POST, "/_security/api_key"),
            Some(("security.api_key.create".into(), "_security/api_key".into()))
        );
        assert_eq!(
            upstream_refusal(Method::GET, "/_security/api_key"),
            Some(("security.api_key.get".into(), "_security/api_key".into()))
        );
        assert_eq!(
            upstream_refusal(Method::DELETE, "/_security/api_key"),
            Some((
                "security.api_key.invalidate".into(),
                "_security/api_key".into()
            ))
        );
    }

    /// `DELETE /_share/{id}` accepts the full share id as well as the handle.
    /// Only the handle — 12 hex characters, public, opens nothing — may become
    /// the entry's resource; a share id must never be written to the log.
    #[test]
    fn a_share_id_in_a_path_never_becomes_an_audit_resource() {
        let id = "0123456789abcdef0123456789abcdef";
        for path in [
            format!("/_share/{id}"),
            format!("/_share/{id}/claim"),
            format!("/_share/{}", &id[..13]),
            "/_share/not-a-handle".to_string(),
        ] {
            let a = classify(&Method::DELETE, &path).expect("classified");
            assert_eq!(a.resource, "_share", "{path}");
            assert!(!a.op.contains(id), "{path}");
        }
    }

    /// Every native write path is covered without being enumerated by hand —
    /// including the ingest shapes (`logs`, `otlp`, `syslog`) that no
    /// per-handler `append` list would have remembered.
    #[test]
    fn the_native_router_is_covered_too() {
        assert_eq!(
            c(Method::POST, "/v1/indices/logs-app/docs"),
            Some(("index".into(), "logs-app".into()))
        );
        assert_eq!(
            c(Method::POST, "/v1/indices/logs-app/docs/_bulk"),
            Some(("bulk".into(), "logs-app".into()))
        );
        assert_eq!(
            c(Method::DELETE, "/v1/indices/logs-app/docs/7"),
            Some(("delete".into(), "logs-app".into()))
        );
        assert_eq!(
            c(Method::POST, "/v1/indices/logs-app/syslog"),
            Some(("index".into(), "logs-app".into()))
        );
        assert_eq!(
            c(Method::DELETE, "/v1/indices/logs-app"),
            Some(("index.delete".into(), "logs-app".into()))
        );
        assert_eq!(
            c(Method::POST, "/v1/indices"),
            Some(("index.create".into(), "_indices".into()))
        );
    }

    #[test]
    fn outcomes_map_to_the_three_words_the_entry_allows() {
        assert_eq!(outcome_of(StatusCode::OK), "ok");
        assert_eq!(outcome_of(StatusCode::CREATED), "ok");
        assert_eq!(outcome_of(StatusCode::FORBIDDEN), "denied");
        assert_eq!(outcome_of(StatusCode::NOT_FOUND), "error");
        assert_eq!(outcome_of(StatusCode::INTERNAL_SERVER_ERROR), "error");
    }
}

//! API key authentication middleware — *who* the caller is.
//!
//! Checks the `Authorization` header for any of:
//! - `Authorization: ApiKey <key>`
//! - `Authorization: Bearer <key>`
//! - `Authorization: Basic <base64(user:pass)>`
//!
//! When `config.auth.enabled` is `false` (or `--insecure` mode was set by
//! clearing the key), the check is skipped entirely.
//!
//! Authentication answers *who*; [`crate::authz`] answers *what they may
//! touch*. The bridge between them is [`Principal`], produced here by
//! [`authenticate`] and consulted there. `is_authorized` — the boolean the
//! gRPC interceptor and the HTTP middleware share — is now a thin wrapper over
//! `authenticate`, so the two surfaces cannot drift.

use axum::{
    extract::{FromRequestParts, Request, State},
    http::{request::Parts, StatusCode},
    middleware::Next,
    response::{IntoResponse, Response},
    Json,
};
use xerj_engine::rbac::{Privilege, Role};

use crate::error::{EsErrorBody, EsErrorResponse, EsRootCause};
use crate::state::AppState;

// ─────────────────────────────────────────────────────────────────────────────

/// Probe endpoints exempted from authentication.
///
/// `/health/live` and `/health/ready` are the conventional Kubernetes liveness
/// and readiness paths that container `HEALTHCHECK`s (see `engine/Dockerfile`)
/// and Helm chart probes hit **without** credentials. Gating them behind auth
/// makes every hardened deployment crashloop: the moment `auth.enabled = true`,
/// the kubelet's probe (and Docker's `curl -fsS .../health/ready`) receives a
/// 401, is marked unhealthy, and the pod is restarted forever. Both handlers
/// are dependency-free and expose no index data (they answer a bare
/// `"live"`/`"ready"` string), so leaving them open is safe.
pub const AUTH_EXEMPT_PATHS: [&str; 2] = ["/health/live", "/health/ready"];

/// Is `path` the share-claim route, `/_share/claim`?
///
/// The one unauthenticated route that hands out a credential: a guest who
/// opens a share link has, by definition, no key yet. It is exempted the way
/// `/v1/metrics` is for the scrape token — by exact path, `POST` only (the
/// method check is the caller's), never by prefix — and the handler
/// (`crate::share::claim_share`) rate-limits per source address and per share
/// and audits every outcome. Everything else under `/_share` stays behind
/// authentication and is superuser-only in its handler.
///
/// The share id is in the request **body**. The first cut matched
/// `/_share/{id}/claim`, which put the id into every access log between the
/// guest and the node; that shape is deliberately not exempt any more, so a
/// stale client gets a plain `401` instead of a second, id-leaking way in.
pub fn is_share_claim_path(path: &str) -> bool {
    let mut segs = path.split('/').filter(|s| !s.is_empty());
    matches!(
        (segs.next(), segs.next(), segs.next()),
        (Some("_share"), Some("claim"), None)
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// Principal
// ─────────────────────────────────────────────────────────────────────────────

/// The authenticated identity behind a request.
///
/// Authentication used to collapse to a bool, which is exactly why a brain was
/// not a security boundary: with no principal on the request there was nothing
/// for an authorization check to consult (issue #79). Every variant below is a
/// *capability statement*, and the ordering is deliberate — the further down
/// the list, the less a caller may reach.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Principal {
    /// Full access. Two ways to be one, and only two:
    /// - **open mode** — `auth.enabled = false` or no admin key configured.
    ///   This is `xerj --insecure` and the point-at-a-folder first run, where
    ///   there is exactly one user and no configuration; it must keep working
    ///   with zero setup, so it is deliberately unrestricted.
    /// - the configured **admin/superuser key** (`auth.admin_api_key`).
    Superuser,
    /// A key minted by `POST /_security/api_key` **with** usable
    /// `role_descriptors`. Confined: it may touch only the indices its roles
    /// name, and nothing that is not index-scoped.
    Scoped {
        /// The minted key's id (for audit/log lines, never compared).
        key_id: String,
        /// Index grants parsed from `role_descriptors`. Never empty — an
        /// empty grant list is [`Principal::Unscoped`].
        roles: Vec<Role>,
    },
    /// A key minted **without** `role_descriptors` — the shape every key had
    /// before per-brain authorization existed.
    ///
    /// It keeps its historical reach over the general ES-compat surface (so
    /// hardened Kibana/Beats deployments do not break), but it holds **no**
    /// privilege on the reserved `.xerj-memory-*` namespace. That is the
    /// fail-closed half: an unconfigured principal is denied the brain, not
    /// granted it.
    Unscoped {
        /// The minted key's id.
        key_id: String,
    },
    /// No valid credential. Normally unreachable inside a handler — the auth
    /// middleware answers 401 first — but it is what the [`Principal`]
    /// extractor yields if a handler is ever mounted without that middleware,
    /// so the default is "deny", never "allow".
    Denied,
}

impl Principal {
    /// Does this principal hold `privilege` on `index`?
    ///
    /// This is the single authorization predicate; [`crate::authz`] routes
    /// every enforcement point through it. `Unscoped` answers `true` for
    /// ordinary indices (its historical reach) and `false` for the reserved
    /// namespace, which [`crate::authz::is_reserved_index`] defines.
    pub fn allows_index(&self, index: &str, privilege: Privilege) -> bool {
        match self {
            Principal::Superuser => true,
            Principal::Scoped { roles, .. } => roles.iter().any(|r| r.allows(index, privilege)),
            Principal::Unscoped { .. } => !crate::authz::is_reserved_index(index),
            Principal::Denied => false,
        }
    }

    /// Is this the key a share-link claim minted (`crate::share::claim_share`)?
    ///
    /// Such a key carries exactly one role, named `share:<handle>`. It is
    /// recognised by that name and nothing else, which is safe in the only
    /// direction that matters: being recognised as a guest only ever *removes*
    /// reach ([`crate::authz`] intersects the guest route allow-list with the
    /// key's index grants — it never adds to them). An operator who mints an
    /// ordinary key with a role descriptor called `share:x` gets a key that is
    /// more confined than they asked for, never less.
    pub fn is_share_guest(&self) -> bool {
        match self {
            Principal::Scoped { roles, .. } => {
                !roles.is_empty()
                    && roles
                        .iter()
                        .all(|r| r.name.starts_with(crate::share::GUEST_ROLE_PREFIX))
            }
            _ => false,
        }
    }

    /// True for the one principal that is allowed to see and do everything —
    /// used to skip the authorization work entirely on the local-dev path.
    pub fn is_superuser(&self) -> bool {
        matches!(self, Principal::Superuser)
    }

    /// Short identity string for error/log lines. Never contains key material.
    pub fn label(&self) -> &str {
        match self {
            Principal::Superuser => "superuser",
            Principal::Scoped { key_id, .. } | Principal::Unscoped { key_id } => key_id.as_str(),
            Principal::Denied => "unauthenticated",
        }
    }
}

/// Extract the principal straight from the request's `Authorization` header.
///
/// Deliberately *re-derives* rather than reading a request extension planted
/// by the middleware: a handler that authorizes must be safe by construction
/// even if it is mounted on a router where the middleware was forgotten. The
/// cost is one map lookup plus a constant-time compare. When no credential
/// resolves, the result is [`Principal::Denied`] — never an error that a
/// caller could turn into a bypass.
#[axum::async_trait]
impl FromRequestParts<AppState> for Principal {
    type Rejection = std::convert::Infallible;

    async fn from_request_parts(
        parts: &mut Parts,
        state: &AppState,
    ) -> Result<Self, Self::Rejection> {
        let header = parts
            .headers
            .get(axum::http::header::AUTHORIZATION)
            .and_then(|v| v.to_str().ok());
        Ok(authenticate(state, header))
    }
}

/// Axum middleware that enforces API key authentication.
///
/// Call via `middleware::from_fn_with_state(state, auth_middleware)` in the
/// router builders.
pub async fn auth_middleware(State(state): State<AppState>, req: Request, next: Next) -> Response {
    // Kubernetes / Docker probes must stay reachable without credentials, or a
    // hardened (auth-enabled) deployment crashloops. See `AUTH_EXEMPT_PATHS`.
    if AUTH_EXEMPT_PATHS.contains(&req.uri().path()) {
        return next.run(req).await;
    }

    // RC4-W4 item 4: optional read-only metrics token. When configured, a
    // caller presenting the exact token may scrape `/v1/metrics` — and ONLY
    // that endpoint — without the admin key, so Prometheus can be handed a
    // low-privilege scrape credential that cannot read index data. The admin
    // key still works for metrics via the normal path below.
    if req.uri().path() == "/v1/metrics" && metrics_token_authorized(&state, &req) {
        return next.run(req).await;
    }

    // A guest claiming a share link has no credential yet — that is the
    // whole point of the route. See `is_share_claim_path`.
    if req.method() == axum::http::Method::POST && is_share_claim_path(req.uri().path()) {
        return next.run(req).await;
    }

    // Xerj Console lives in a peer router (mounted by `xerj-server` via
    // `Router::merge`) and runs its own session-cookie auth, so this
    // middleware never sees `/_xerj-console/*` requests — no path-prefix
    // bypass needed.

    // Extract the Authorization header.
    let auth_header = req
        .headers()
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok());

    if is_authorized(&state, auth_header) {
        next.run(req).await
    } else {
        unauthorized_response(&state.config.server.data_dir)
    }
}

/// The shared authorization decision, enforced identically by the HTTP
/// `auth_middleware` and the gRPC auth interceptor (`xerj-server::grpc`) so both
/// API surfaces require the same credentials.
///
/// Returns `true` when the request may proceed:
/// - auth is disabled, or no admin key is configured (open mode — matches the
///   `--insecure` / first-run posture); or
/// - the `Authorization` value carries the configured admin/superuser key
///   (as `ApiKey <key>`/`Bearer <key>`, or as the password half of
///   `Basic <base64(user:pass)>`); or
/// - it carries a key minted by `POST /_security/api_key`, as either
///   `ApiKey <base64(id:api_key)>` or `Basic <base64(id:api_key)>` — Kibana's
///   interactive "basic" realm login sends the latter, and a minted key's
///   `id:secret` shape is already exactly `user:pass`.
///
/// `auth_header` is the raw `Authorization` header / `authorization` metadata
/// value (e.g. `"ApiKey abc"`, `"Bearer abc"`, or `"Basic base64(...)"`), or
/// `None` when absent.
pub fn is_authorized(state: &AppState, auth_header: Option<&str>) -> bool {
    !matches!(authenticate(state, auth_header), Principal::Denied)
}

/// Resolve the request's credential to a [`Principal`].
///
/// Same acceptance rules as [`is_authorized`] (which is now defined in terms of
/// this), but it reports *which* identity authenticated so authorization has
/// something to decide against. Returns [`Principal::Denied`] when nothing
/// authenticates.
pub fn authenticate(state: &AppState, auth_header: Option<&str>) -> Principal {
    let cfg = &state.config.auth;

    // Open mode: auth disabled or no admin key configured. This is the
    // `--insecure` / point-at-a-folder posture — one user, no configuration —
    // and it stays fully unrestricted on purpose.
    if !cfg.enabled || cfg.admin_api_key.is_empty() {
        return Principal::Superuser;
    }

    let Some(header) = auth_header else {
        return Principal::Denied;
    };

    if let Some(key) = extract_key(header) {
        // The configured admin/superuser key. Compared in constant time
        // (item 7): a plain `==` short-circuits on the first mismatching byte,
        // leaking the shared-secret prefix length via response timing. The
        // created-key path already used `constant_time_eq`; the admin key —
        // the single most valuable credential in the system — must not be
        // weaker. `constant_time_eq` still returns early on a length mismatch,
        // which only reveals the key *length*, matching the created-key path.
        if constant_time_eq(key.as_bytes(), cfg.admin_api_key.as_bytes()) {
            return Principal::Superuser;
        }
        // A key minted by `POST /_security/api_key`.
        return authenticate_api_key(state, key);
    }

    basic_principal(state, header)
}

/// Validate `Authorization: Basic <base64(user:pass)>`.
///
/// xerj has no per-username credential store — same single-owner identity
/// model `security_authenticate` already uses — so this doesn't check the
/// username against anything. Two things are accepted as the *password*
/// half, both already valid credentials via the `ApiKey`/`Bearer` schemes:
/// - the admin/superuser key (any username — mirrors ES's own "elastic"
///   bootstrap superuser, where the secret is what's checked, not the name);
/// - or, treating the whole decoded `user:pass` as `id:secret`, a key minted
///   by `POST /_security/api_key` (its `id:secret` shape already matches
///   `user:pass` exactly, so no separate encoding is needed here).
fn basic_principal(state: &AppState, header: &str) -> Principal {
    let Some(prefix) = header.get(..6) else {
        return Principal::Denied;
    };
    if !prefix.eq_ignore_ascii_case("basic ") {
        return Principal::Denied;
    }
    let encoded = header[6..].trim();
    let decoded = match crate::es_compat::base64_decode(encoded) {
        Some(d) => d,
        None => return Principal::Denied,
    };
    let decoded = match std::str::from_utf8(&decoded) {
        Ok(s) => s,
        Err(_) => return Principal::Denied,
    };
    let Some((user, pass)) = decoded.split_once(':') else {
        return Principal::Denied;
    };

    let cfg = &state.config.auth;
    if constant_time_eq(pass.as_bytes(), cfg.admin_api_key.as_bytes()) {
        return Principal::Superuser;
    }
    check_minted_key(state, user, pass)
}

/// Decide whether a request to `/v1/metrics` may proceed on the strength of
/// the read-only `auth.metrics_token` alone (RC4-W4 item 4).
///
/// Returns `false` (falls through to normal auth) when the token is unset or
/// the presented credential doesn't match it. The comparison is constant-time,
/// matching the admin-key path — a scrape token is still a shared secret.
fn metrics_token_authorized(state: &AppState, req: &Request) -> bool {
    let token = &state.config.auth.metrics_token;
    if token.is_empty() {
        return false;
    }
    req.headers()
        .get(axum::http::header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok())
        .and_then(extract_key)
        .map(|k| constant_time_eq(k.as_bytes(), token.as_bytes()))
        .unwrap_or(false)
}

/// Re-authenticate a created API key credential.
///
/// The presented value is `base64("id:api_key")`. Decode it, split on the
/// first `':'`, look the id up in the engine's key store, and constant-time
/// compare the secret. The resulting principal carries the key's stored
/// grants: [`Principal::Scoped`] when it was minted with usable
/// `role_descriptors`, [`Principal::Unscoped`] otherwise.
fn authenticate_api_key(state: &AppState, presented: &str) -> Principal {
    let decoded = match crate::es_compat::base64_decode(presented) {
        Some(d) => d,
        None => return Principal::Denied,
    };
    let decoded = match std::str::from_utf8(&decoded) {
        Ok(s) => s,
        Err(_) => return Principal::Denied,
    };
    let (id, secret) = match decoded.split_once(':') {
        Some(parts) => parts,
        None => return Principal::Denied,
    };
    check_minted_key(state, id, secret)
}

/// Look up a minted `POST /_security/api_key` credential by `(id, secret)`.
/// Shared by the `ApiKey <base64(id:secret)>` and `Basic <base64(id:secret)>`
/// paths — both decode to the same `id:secret` shape.
///
/// A minted key is **never** a superuser: the strongest thing it can be is
/// `Unscoped`, which has no reach into the reserved `.xerj-memory-*`
/// namespace. That is what stops "any authenticated caller reads any brain".
fn check_minted_key(state: &AppState, id: &str, secret: &str) -> Principal {
    let record = match state.engine.api_keys.get(id) {
        Some(r) => r,
        None => return Principal::Denied,
    };
    if record.invalidated {
        return Principal::Denied;
    }
    if let Some(exp) = record.expiration_ms {
        let now_ms = chrono::Utc::now().timestamp_millis().max(0) as u64;
        if now_ms >= exp {
            return Principal::Denied;
        }
    }
    // Issue #201: the stored form is a salted SHA-256 digest, not the
    // credential. `verify_secret` hashes the presented secret under the
    // record's salt and compares digests in constant time, and answers `false`
    // for any record it cannot make sense of — an unmigrated or mangled record
    // denies rather than falling back to a plaintext compare.
    if !record.verify_secret(secret) {
        return Principal::Denied;
    }
    if record.roles.is_empty() {
        Principal::Unscoped {
            key_id: id.to_string(),
        }
    } else {
        Principal::Scoped {
            key_id: id.to_string(),
            roles: record.roles.clone(),
        }
    }
}

/// Length-independent-only constant-time byte comparison. Avoids leaking the
/// secret via early-exit timing once lengths match.
fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

