    /// The decision table, stated once. `decide` is the only thing between an
    /// authenticated caller and someone else's brain.
    #[test]
    fn decision_table() {
        let alice = scoped(
            &[".xerj-memory-alice-edges", ".xerj-memory-alice"],
            &[Privilege::ReadIndex, Privilege::WriteIndex],
        );

        // Alice reaches her own brain …
        assert!(check(&alice, Method::GET, "/_graph/alice/ego", ""));
        assert!(check(&alice, Method::GET, "/_graph/alice/overview", ""));
        assert!(check(&alice, Method::POST, "/_graph/alice/link", ""));
        assert!(check(&alice, Method::POST, "/_memory/alice/_recall", ""));
        // … and nothing of bob's, by any door.
        assert!(!check(&alice, Method::GET, "/_graph/bob/ego", ""));
        assert!(!check(&alice, Method::POST, "/_graph/bob/link", ""));
        assert!(!check(&alice, Method::DELETE, "/_graph/bob/link/e1", ""));
        assert!(!check(
            &alice,
            Method::POST,
            "/.xerj-memory-bob-edges/_search",
            ""
        ));
        assert!(!check(
            &alice,
            Method::POST,
            "/.xerj-memory-bob-edges/_doc/x",
            ""
        ));
        assert!(!check(
            &alice,
            Method::DELETE,
            "/.xerj-memory-bob-edges",
            ""
        ));
        assert!(!check(&alice, Method::POST, "/_memory/bob/_recall", ""));
        // Including the native router's spelling of the same index.
        assert!(!check(
            &alice,
            Method::POST,
            "/v1/indices/.xerj-memory-bob-edges/search",
            ""
        ));
        // A grant is a grant: alice may use her own backing index directly.
        assert!(check(
            &alice,
            Method::POST,
            "/.xerj-memory-alice-edges/_search",
            ""
        ));

        // A read-only grant does not write.
        let ro = scoped(&[".xerj-memory-alice-edges"], &[Privilege::ReadIndex]);
        assert!(check(&ro, Method::GET, "/_graph/alice/ego", ""));
        assert!(!check(&ro, Method::POST, "/_graph/alice/link", ""));
        assert!(!check(&ro, Method::DELETE, "/.xerj-memory-alice-edges", ""));

        // A legacy key with no grants: keeps ordinary indices, loses every
        // brain door. This is the fail-closed half.
        let legacy = unscoped();
        assert!(check(&legacy, Method::POST, "/logs-2026/_search", ""));
        assert!(check(&legacy, Method::GET, "/logs-*/_search", ""));
        assert!(check(&legacy, Method::GET, "/_mapping", ""));
        assert!(!check(&legacy, Method::GET, "/_graph/alice/ego", ""));
        assert!(!check(&legacy, Method::POST, "/_memory/alice/_recall", ""));
        assert!(!check(
            &legacy,
            Method::POST,
            "/.xerj-memory-alice-edges/_search",
            ""
        ));
        assert!(check(&legacy, Method::PUT, "/logs-2026", ""));

        // No credential resolves to nothing at all.
        let denied = Principal::Denied;
        assert!(!check(&denied, Method::GET, "/_graph/alice/ego", ""));
        assert!(!check(&denied, Method::GET, "/logs/_search", ""));
        assert!(!check(&denied, Method::GET, "/_mapping", ""));

        // The superuser is untouched — this is the `--insecure` path.
        let root = Principal::Superuser;
        for path in [
            "/_graph/bob/ego",
            "/_mapping",
            "/_search",
            "/.xerj-memory-bob-edges/_search",
            "/*/_search",
        ] {
            assert!(
                check(&root, Method::GET, path, ""),
                "superuser blocked on {path}"
            );
        }
    }

    /// BYPASS 1-3: the index in the body is the one that gets authorized.
    #[test]
    fn body_named_indices_are_authorized_not_the_path_one() {
        let alice = scoped(
            &[".xerj-memory-alice-edges", ".xerj-memory-alice"],
            &[Privilege::ReadIndex, Privilege::WriteIndex],
        );

        // _msearch: the header line overrides the path index.
        let msearch = "{\"index\":\".xerj-memory-bob-edges\"}\n{\"query\":{\"match_all\":{}}}\n";
        assert!(!check(
            &alice,
            Method::POST,
            "/.xerj-memory-alice-edges/_msearch",
            msearch
        ));
        assert!(!check(&alice, Method::POST, "/_msearch", msearch));
        // Her own brain through the same door still works.
        let mine = "{\"index\":\".xerj-memory-alice-edges\"}\n{\"query\":{\"match_all\":{}}}\n";
        assert!(check(&alice, Method::POST, "/_msearch", mine));

        // _bulk: the action line's `_index` overrides the path index.
        let forge =
            "{\"index\":{\"_index\":\".xerj-memory-bob-edges\",\"_id\":\"f\"}}\n{\"src\":\"x\"}\n";
        assert!(!check(
            &alice,
            Method::POST,
            "/.xerj-memory-alice-edges/_bulk",
            forge
        ));
        assert!(!check(&alice, Method::POST, "/_bulk", forge));
        let destroy = "{\"delete\":{\"_index\":\".xerj-memory-bob-edges\",\"_id\":\"e1\"}}\n";
        assert!(!check(&alice, Method::POST, "/_bulk", destroy));
        // A bulk that stays inside her grant is allowed — the global `_bulk`
        // is the default write path for every ES client and must work.
        let ok = "{\"index\":{\"_index\":\".xerj-memory-alice-edges\",\"_id\":\"a\"}}\n{\"src\":\"x\"}\n";
        assert!(check(&alice, Method::POST, "/_bulk", ok));

        // _mget: docs[]._index overrides the path index.
        let mget = "{\"docs\":[{\"_index\":\".xerj-memory-bob-edges\",\"_id\":\"1\"}]}";
        assert!(!check(
            &alice,
            Method::POST,
            "/.xerj-memory-alice-edges/_mget",
            mget
        ));
        assert!(!check(&alice, Method::POST, "/_mget", mget));
        assert!(check(
            &alice,
            Method::POST,
            "/.xerj-memory-alice-edges/_mget",
            "{\"ids\":[\"1\"]}"
        ));

        // An unscoped legacy key holds nothing in the reserved namespace by
        // any of the three doors either.
        let legacy = unscoped();
        assert!(!check(&legacy, Method::POST, "/_msearch", msearch));
        assert!(!check(&legacy, Method::POST, "/_bulk", forge));
        assert!(!check(&legacy, Method::POST, "/_mget", mget));
        // …but its ordinary-index traffic is untouched.
        let plain = "{\"index\":{\"_index\":\"logs-2026\"}}\n{\"m\":1}\n";
        assert!(check(&legacy, Method::POST, "/_bulk", plain));
    }

    /// BYPASS 4: `POST /_aliases` authorizes the indices it names, and an
    /// alias already pointing into the namespace does not launder reads.
    #[test]
    fn aliases_cannot_launder_access() {
        let legacy = unscoped();
        let add =
            "{\"actions\":[{\"add\":{\"index\":\".xerj-memory-bob-edges\",\"alias\":\"pwned\"}}]}";
        assert!(!check(&legacy, Method::POST, "/_aliases", add));
        // Also refused for a scoped key that holds a different brain.
        let alice = scoped(
            &[".xerj-memory-alice-edges"],
            &[
                Privilege::ReadIndex,
                Privilege::WriteIndex,
                Privilege::AdminIndex,
            ],
        );
        assert!(!check(&alice, Method::POST, "/_aliases", add));
        // An ordinary alias over an ordinary index still works for the legacy
        // key that has the general surface.
        let ordinary = "{\"actions\":[{\"add\":{\"index\":\"logs-2026\",\"alias\":\"logs\"}}]}";
        assert!(check(&legacy, Method::POST, "/_aliases", ordinary));
        // Squatting an alias NAME inside the reserved namespace is refused.
        let squat =
            "{\"actions\":[{\"add\":{\"index\":\"logs-2026\",\"alias\":\".xerj-memory-victim\"}}]}";
        assert!(!check(&legacy, Method::POST, "/_aliases", squat));
        // …by the path spelling too.
        assert!(!check(
            &legacy,
            Method::PUT,
            "/logs-2026/_alias/.xerj-memory-victim",
            ""
        ));

        // Reading THROUGH an alias that already points at a brain resolves to
        // the brain before the decision is made.
        let mut map = HashMap::new();
        map.insert(
            "pwned".to_string(),
            vec![".xerj-memory-bob-edges".to_string()],
        );
        let aliases = Map(map);
        assert!(!check_with(
            &legacy,
            Method::POST,
            "/pwned/_search",
            "",
            &aliases
        ));
        assert!(!check_with(
            &legacy,
            Method::POST,
            "/_mget",
            "{\"docs\":[{\"_index\":\"pwned\",\"_id\":\"1\"}]}",
            &aliases
        ));
    }

    /// The fifth shape, found by audit rather than by attack: a `terms` lookup
    /// reads a document out of an index the URL never names.
    #[test]
    fn terms_lookup_index_is_authorized() {
        let alice = scoped(&["logs-2026"], &[Privilege::ReadIndex]);
        let lookup = r#"{"query":{"bool":{"filter":[{"terms":{"user":{"index":".xerj-memory-bob-edges","id":"1","path":"dst"}}}]}}}"#;
        assert!(!check(&alice, Method::POST, "/logs-2026/_search", lookup));
        // A lookup into an index she holds is fine.
        let own = r#"{"query":{"terms":{"user":{"index":"logs-2026","id":"1","path":"u"}}}}"#;
        assert!(check(&alice, Method::POST, "/logs-2026/_search", own));
        // A plain `terms` filter (no lookup) names no index and is untouched —
        // a document field called `index` must not be read as one.
        let plain = r#"{"query":{"terms":{"index":["a","b"]}}}"#;
        assert!(check(&alice, Method::POST, "/logs-2026/_search", plain));

        // The same shape one layer over: a `lookup` runtime field joins rows
        // out of another index into the hits.
        let runtime = r#"{"runtime_mappings":{"u":{"type":"lookup","target_index":".xerj-memory-bob-edges","input_field":"src","target_field":"_id","fetch_fields":["dst"]}}}"#;
        assert!(!check(&alice, Method::POST, "/logs-2026/_search", runtime));
        let own = r#"{"runtime_mappings":{"u":{"type":"lookup","target_index":"logs-2026","input_field":"src","target_field":"_id"}}}"#;
        assert!(check(&alice, Method::POST, "/logs-2026/_search", own));
    }

    /// `_reindex` reads its source and writes its destination.
    #[test]
    fn reindex_authorizes_source_and_destination() {
        let p = scoped(
            &["logs-2026", "logs-copy"],
            &[Privilege::ReadIndex, Privilege::WriteIndex],
        );
        let ok = r#"{"source":{"index":"logs-2026"},"dest":{"index":"logs-copy"}}"#;
        assert!(check(&p, Method::POST, "/_reindex", ok));
        let steal = r#"{"source":{"index":".xerj-memory-bob-edges"},"dest":{"index":"logs-copy"}}"#;
        assert!(!check(&p, Method::POST, "/_reindex", steal));
        let overwrite =
            r#"{"source":{"index":"logs-2026"},"dest":{"index":".xerj-memory-bob-edges"}}"#;
        assert!(!check(&p, Method::POST, "/_reindex", overwrite));
        // A body that names neither is refused rather than guessed at.
        assert!(!check(&p, Method::POST, "/_reindex", "{}"));
        assert!(!check(&p, Method::POST, "/_reindex", "not json"));
    }

    /// The native router's body-named create is authorized, not blanket-refused.
    #[test]
    fn native_body_named_create_is_authorized() {
        let legacy = unscoped();
        assert!(check(
            &legacy,
            Method::POST,
            "/v1/indices",
            r#"{"name":"logs-2026","fields":[]}"#
        ));
        assert!(!check(
            &legacy,
            Method::POST,
            "/v1/indices",
            r#"{"name":".xerj-memory-victim-edges","fields":[]}"#
        ));
        assert!(!check(&legacy, Method::POST, "/v1/indices", "{}"));
    }

    /// A snapshot or restore that names no indices covers every brain on the
    /// node, so it is superuser-only.
    #[test]
    fn unbounded_snapshot_is_superuser_only() {
        let legacy = unscoped();
        assert!(!check(&legacy, Method::PUT, "/_snapshot/repo/s1", "{}"));
        assert!(!check(
            &legacy,
            Method::POST,
            "/_snapshot/repo/s1/_restore",
            "{}"
        ));
        assert!(check(
            &legacy,
            Method::PUT,
            "/_snapshot/repo/s1",
            r#"{"indices":["logs-2026"]}"#
        ));
        assert!(!check(
            &legacy,
            Method::PUT,
            "/_snapshot/repo/s1",
            r#"{"indices":[".xerj-memory-bob-edges"]}"#
        ));
        assert!(check(
            &Principal::Superuser,
            Method::PUT,
            "/_snapshot/repo/s1",
            "{}"
        ));
    }

    /// `PUT /_xerj/wal_tap` (issue #320) is a whole-node export primitive:
    /// `target_url` names any host on the network, `indices: ["*"]` names
    /// every index on this node, and the tap attaches an operator-supplied
    /// `Authorization` header to the requests it makes — exfiltration and
    /// authenticated SSRF in one call.
    ///
    /// It reached `Target::Cluster` through the `_`-prefix arm, `body_shape`
    /// returned `BodyShape::None` so `body_targets` produced no demands, and a
    /// mutating cluster verb naming nothing falls through to
    /// `Principal::Unscoped => Ok(())`. Every unscoped key on the node could
    /// therefore stream the whole node off it. Same reasoning as
    /// `unbounded_snapshot_is_superuser_only` above, same answer.
    ///
    /// The reads matter too and are covered by the same arm: `GET
    /// /_xerj/wal_tap` echoes `target_url`, and `GET /_xerj/wal_tap/_stats`
    /// enumerates the node's whole index inventory with no principal filter
    /// (`_xerj` has no `prune_sites` entry, and adding one would not help — a
    /// scoped key has no business knowing the tap's target either). Both are
    /// `cluster_is_read`, so before this arm a key scoped to a single index
    /// could read them.
    #[test]
    fn the_wal_tap_export_primitive_is_superuser_only() {
        let legacy = unscoped();
        let one_index = scoped(&["logs-2026"], &[Privilege::ReadIndex]);

        // The write: an unscoped key must not be able to point this node's
        // whole WAL at a host it chose.
        let exfiltrate = r#"{"enabled":true,"target_url":"http://attacker.example",
                             "indices":["*"],"target_auth":"ApiKey stolen"}"#;
        assert!(!check(&legacy, Method::PUT, "/_xerj/wal_tap", exfiltrate));
        assert!(!check(
            &one_index,
            Method::PUT,
            "/_xerj/wal_tap",
            exfiltrate
        ));
        assert!(!check(&legacy, Method::DELETE, "/_xerj/wal_tap", ""));

        // The reads: the target URL and the node's index inventory.
        assert!(!check(&legacy, Method::GET, "/_xerj/wal_tap", ""));
        assert!(!check(&one_index, Method::GET, "/_xerj/wal_tap", ""));
        assert!(!check(&legacy, Method::GET, "/_xerj/wal_tap/_stats", ""));
        assert!(!check(&one_index, Method::GET, "/_xerj/wal_tap/_stats", ""));

        // The namespace, not just the route: a second `_xerj` endpoint must
        // inherit this rather than have to remember it.
        assert!(!check(&legacy, Method::GET, "/_xerj/anything", ""));
        assert!(!check(&legacy, Method::POST, "/_xerj/anything/_do", ""));

        // And the operator can still drive it.
        for (method, path) in [
            (Method::GET, "/_xerj/wal_tap"),
            (Method::PUT, "/_xerj/wal_tap"),
            (Method::DELETE, "/_xerj/wal_tap"),
            (Method::GET, "/_xerj/wal_tap/_stats"),
        ] {
            assert!(
                check(&Principal::Superuser, method.clone(), path, "{}"),
                "the superuser must keep {method} {path}"
            );
        }
    }

    /// The pattern short-circuit in [`authorize_expression`] is safe because
    /// the engine expands a wildcard over the principal's visible set. Snapshot
    /// and restore are the two verbs that never reach that funnel:
    /// `Engine::create_snapshot` walks the index map itself, and
    /// `Engine::restore_snapshot` expands the pattern against the snapshot's
    /// own manifest and then removes and rewrites the index directory directly
    /// — no `get_index`, no `delete_index`. A wildcard waved through here is a
    /// wildcard executed, which made
    /// `POST /_snapshot/{repo}/{snap}/_restore {"indices":".xerj-memory-*"}`
    /// roll every tenant's brain back to the backup instant for any
    /// authenticated caller, and `{"indices":"*"}` on the create side back up
    /// every brain on the node.
    #[test]
    fn snapshot_patterns_cannot_reach_the_reserved_namespace() {
        let legacy = unscoped();
        let alice = scoped(
            &[".xerj-memory-alice-edges", ".xerj-memory-alice"],
            &[Privilege::ReadIndex, Privilege::WriteIndex],
        );
        let logs = scoped(&["logs-*"], &[Privilege::ReadIndex, Privilege::WriteIndex]);

        for body in [
            r#"{"indices":".xerj-memory-*"}"#,
            r#"{"indices":[".xerj-memory-*"]}"#,
            r#"{"indices":"*"}"#,
            r#"{"indices":["*"]}"#,
            r#"{"indices":"_all"}"#,
            r#"{"indices":"logs-*,.xerj-*"}"#,
        ] {
            for p in [&legacy, &alice, &logs] {
                assert!(
                    !check(p, Method::POST, "/_snapshot/repo/s1/_restore", body),
                    "restore {body} destroys the reserved namespace and must be refused"
                );
                assert!(
                    !check(p, Method::PUT, "/_snapshot/repo/s1", body),
                    "snapshot {body} captures the reserved namespace and must be refused"
                );
            }
        }

        // A tenant still backs up and rolls back its OWN indices, by name …
        assert!(check(
            &alice,
            Method::PUT,
            "/_snapshot/repo/s1",
            r#"{"indices":[".xerj-memory-alice"]}"#
        ));
        assert!(check(
            &alice,
            Method::POST,
            "/_snapshot/repo/s1/_restore",
            r#"{"indices":".xerj-memory-alice"}"#
        ));
        // … and through a pattern that cannot reach the namespace, in both the
        // array and the string spelling ES accepts.
        assert!(check(
            &logs,
            Method::PUT,
            "/_snapshot/repo/s1",
            r#"{"indices":"logs-*"}"#
        ));
        assert!(check(
            &logs,
            Method::POST,
            "/_snapshot/repo/s1/_restore",
            r#"{"indices":["logs-*"]}"#
        ));
        assert!(check(
            &legacy,
            Method::PUT,
            "/_snapshot/repo/s1",
            r#"{"indices":"logs-2026,logs-2027"}"#
        ));

        // The superuser is still the operator: a full backup and a full
        // restore are exactly what it is for.
        for body in [
            "{}",
            r#"{"indices":"*"}"#,
            r#"{"indices":".xerj-memory-*"}"#,
        ] {
            assert!(check(
                &Principal::Superuser,
                Method::PUT,
                "/_snapshot/repo/s1",
                body
            ));
            assert!(check(
                &Principal::Superuser,
                Method::POST,
                "/_snapshot/repo/s1/_restore",
                body
            ));
        }

        // FINDING C is unchanged here: `names:["*"]` is an operator explicitly
        // granting the whole node, so it snapshots the whole node.
        let star = scoped(&["*"], &[Privilege::ReadIndex, Privilege::WriteIndex]);
        assert!(check(
            &star,
            Method::PUT,
            "/_snapshot/repo/s1",
            r#"{"indices":"*"}"#
        ));
        assert!(check(
            &star,
            Method::POST,
            "/_snapshot/repo/s1/_restore",
            r#"{"indices":"*"}"#
        ));
    }

    /// COMPATIBILITY: the regression that made the branch unusable. Every
    /// global verb works for an ordinary credential, and a scoped key can read
    /// cluster metadata and use a wildcard it was granted.
    #[test]
    fn ordinary_credentials_keep_the_global_surface() {
        let legacy = unscoped();
        let scoped_all = scoped(
            &["*"],
            &[
                Privilege::ReadIndex,
                Privilege::WriteIndex,
                Privilege::AdminIndex,
            ],
        );
        let logs = scoped(&["logs-*"], &[Privilege::ReadIndex, Privilege::WriteIndex]);

        for p in [&legacy, &scoped_all, &logs] {
            assert!(check(p, Method::POST, "/_search", "{}"), "global _search");
            assert!(check(p, Method::POST, "/_count", "{}"), "global _count");
            assert!(
                check(p, Method::POST, "/_msearch", "{}\n{\"query\":{}}\n"),
                "global _msearch"
            );
            assert!(
                check(
                    p,
                    Method::POST,
                    "/_bulk",
                    "{\"index\":{\"_index\":\"logs-2026\"}}\n{\"m\":1}\n"
                ),
                "global _bulk"
            );
            assert!(
                check(
                    p,
                    Method::POST,
                    "/_mget",
                    "{\"docs\":[{\"_index\":\"logs-2026\",\"_id\":\"1\"}]}"
                ),
                "global _mget"
            );
            assert!(check(p, Method::GET, "/_cluster/health", ""), "health");
            assert!(check(p, Method::GET, "/_nodes", ""), "nodes");
            assert!(check(p, Method::GET, "/_mapping", ""), "mapping");
            assert!(check(p, Method::GET, "/_cat/indices", ""), "cat");
            assert!(check(p, Method::GET, "/v1/health", ""), "native health");
            assert!(
                check(p, Method::GET, "/v1/embedding/identity", ""),
                "embedding identity"
            );
            assert!(
                check(p, Method::GET, "/_resolve/index/logs-*", ""),
                "resolve"
            );
        }
        // A granted wildcard is usable, and an ungranted one resolves to
        // nothing rather than 403 (the engine expands it over the visible set).
        assert!(check(&logs, Method::GET, "/logs-*/_search", ""));
        assert!(check(&scoped_all, Method::GET, "/logs-*/_search", ""));
        assert!(check(&logs, Method::GET, "/.xerj-memory-*/_search", ""));
        // A scoped key still cannot NAME another tenant's index.
        assert!(!check(
            &logs,
            Method::GET,
            "/.xerj-memory-bob-edges/_search",
            ""
        ));
        // …nor mutate the cluster itself.
        assert!(!check(&logs, Method::PUT, "/_cluster/settings", "{}"));
        assert!(check(&legacy, Method::PUT, "/_cluster/settings", "{}"));
    }

    /// Prune the way the middleware does: pick the endpoint's sites from its
    /// path, then apply them.
    fn prune_at(path: &str, v: &mut Value, p: &Principal, known: &HashSet<String>) {
        prune_json(v, prune_sites(&segments(path)), p, known);
    }

    fn prune_rows(path: &str, table: &str, p: &Principal, known: &HashSet<String>) -> String {
        let cols = cat_index_columns(&segments(path)).unwrap_or(&[]);
        String::from_utf8(prune_text(table.as_bytes(), cols, p, known)).expect("utf8")
    }

    #[test]
    fn json_pruning_hides_unreadable_indices() {
        let p = scoped(&[".xerj-memory-alice-edges"], &[Privilege::ReadIndex]);
        let known: HashSet<String> = [
            ".xerj-memory-alice-edges",
            ".xerj-memory-bob-edges",
            "logs-2026",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let mut mapping = serde_json::json!({
            ".xerj-memory-alice-edges": {"mappings": {}},
            ".xerj-memory-bob-edges": {"mappings": {}},
            "logs-2026": {"mappings": {}}
        });
        prune_at("/_mapping", &mut mapping, &p, &known);
        assert!(mapping.get(".xerj-memory-alice-edges").is_some());
        assert!(mapping.get(".xerj-memory-bob-edges").is_none());
        // A scoped key does not see another tenant's ordinary index either …
        assert!(mapping.get("logs-2026").is_none());
        // … but structural keys are never mistaken for index names.
        assert!(mapping[".xerj-memory-alice-edges"]
            .get("mappings")
            .is_some());

        // Array shapes: `_cat/indices?format=json` and `_resolve/index`.
        let mut cat = serde_json::json!([
            {"index": ".xerj-memory-bob-edges", "docs.count": "1"},
            {"index": ".xerj-memory-alice-edges", "docs.count": "9"}
        ]);
        prune_at("/_cat/indices", &mut cat, &p, &known);
        assert_eq!(cat.as_array().unwrap().len(), 1);

        let mut caps =
            serde_json::json!({"indices": [".xerj-memory-bob-edges", ".xerj-memory-alice-edges"]});
        prune_at("/_field_caps", &mut caps, &p, &known);
        assert_eq!(
            caps["indices"],
            serde_json::json!([".xerj-memory-alice-edges"])
        );
        // …including the per-field `indices` lists buried under `fields`.
        let mut caps = serde_json::json!({
            "indices": [".xerj-memory-alice-edges", ".xerj-memory-bob-edges"],
            "fields": {"host": {"keyword": {
                "type": "keyword",
                "indices": [".xerj-memory-alice-edges", ".xerj-memory-bob-edges"]
            }}}
        });
        prune_at("/_field_caps", &mut caps, &p, &known);
        assert_eq!(
            caps["fields"]["host"]["keyword"]["indices"],
            serde_json::json!([".xerj-memory-alice-edges"])
        );
        assert_eq!(caps["fields"]["host"]["keyword"]["type"], "keyword");
    }

    /// FINDING B. An index name is an arbitrary string, so the previous
    /// "delete any key equal to a known index name, at every depth" collided
    /// with the structural keys of the responses it was protecting — and only
    /// ever for a scoped key, i.e. exactly the multi-tenant case this branch
    /// exists to enable. Each case below is one measured breakage.
    #[test]
    fn structural_keys_survive_ordinary_indices_that_share_their_name() {
        // Ordinary indices with unfortunate names, none of them readable by
        // this principal.
        let p = scoped(&["logs-2026"], &[Privilege::ReadIndex]);
        let known: HashSet<String> = ["status", "indices", "type", "nodes", "count", "logs-2026"]
            .iter()
            .map(|s| s.to_string())
            .collect();

        // `GET /_cluster/health` kept its `status` — the most-polled field in
        // the API — while still pruning the per-index breakdown.
        let mut health = serde_json::json!({
            "cluster_name": "xerj", "status": "green", "timed_out": false,
            "indices": {"logs-2026": {"status": "green"}, "status": {"status": "green"}}
        });
        prune_at("/_cluster/health", &mut health, &p, &known);
        assert_eq!(health["status"], "green");
        assert!(health["indices"].get("logs-2026").is_some());
        assert!(health["indices"].get("status").is_none());

        // `GET /_cluster/stats` kept its whole `indices` section: those are
        // aggregate counters, not a map keyed by index name.
        let mut stats = serde_json::json!({
            "status": "green",
            "indices": {"count": 5, "docs": {"count": 42}},
            "nodes": {"count": {"total": 1}}
        });
        let before = stats.clone();
        prune_at("/_cluster/stats", &mut stats, &p, &known);
        assert_eq!(stats, before, "_cluster/stats names no index anywhere");

        // Global `GET /_mapping` kept every field's `type`, which is what
        // Kibana reads to build an index pattern.
        let mut mapping = serde_json::json!({
            "logs-2026": {"mappings": {"properties": {
                "host": {"type": "keyword"},
                "count": {"type": "long"}
            }}},
            "type": {"mappings": {"properties": {}}}
        });
        prune_at("/_mapping", &mut mapping, &p, &known);
        assert_eq!(
            mapping["logs-2026"]["mappings"]["properties"]["host"]["type"],
            "keyword"
        );
        assert_eq!(
            mapping["logs-2026"]["mappings"]["properties"]["count"]["type"],
            "long"
        );
        assert!(
            mapping.get("type").is_none(),
            "the index actually named `type` is still hidden"
        );

        // `GET /_cluster/state` prunes its two index maps and leaves the node
        // map alone, even when an index shares a node's name.
        let mut state = serde_json::json!({
            "nodes": {"nodes": {"name": "nodes"}},
            "metadata": {"templates": {}, "indices": {"logs-2026": {}, "count": {}}},
            "routing_table": {"indices": {"logs-2026": {}, "count": {}}}
        });
        prune_at("/_cluster/state", &mut state, &p, &known);
        assert!(state["nodes"].get("nodes").is_some(), "node map untouched");
        assert!(state["metadata"].get("templates").is_some());
        assert!(state["metadata"]["indices"].get("logs-2026").is_some());
        assert!(state["metadata"]["indices"].get("count").is_none());
        assert!(state["routing_table"]["indices"].get("count").is_none());
    }

    /// The same collision in the `_cat` text tables: matching *any* token
    /// meant one unreadable index called `open` or `green` emptied the table.
    #[test]
    fn cat_rows_are_matched_on_the_index_column_only() {
        let p = scoped(&["logs-2026"], &[Privilege::ReadIndex]);
        let known: HashSet<String> = ["logs-2026", "open", "green", ".xerj-memory-bob-edges"]
            .iter()
            .map(|s| s.to_string())
            .collect();

        let table = "green open logs-2026 uuid 1 0 9 0 1kb 1kb\n\
                     green open .xerj-memory-bob-edges uuid 1 0 1 0 1kb 1kb\n\
                     green open open uuid 1 0 3 0 1kb 1kb\n";
        let out = prune_rows("/_cat/indices", table, &p, &known);
        assert!(out.contains("logs-2026"), "own index survives: {out}");
        assert!(
            !out.contains(".xerj-memory-bob-edges"),
            "brain hidden: {out}"
        );
        assert_eq!(
            out.lines().count(),
            1,
            "only the row whose INDEX column is hidden goes: {out}"
        );

        // `_cat/health` has no index column at all, so nothing may be dropped
        // from it however its values happen to read.
        let health = "1785000000 12:00:00 xerj green 1 1 4 4 0 0 0 0 - 100.0%\n";
        assert_eq!(prune_rows("/_cat/health", health, &p, &known), health);

        // `_cat/fielddata` carries the index in column 4.
        let fd = "n1 127.0.0.1 127.0.0.1 n1 logs-2026 0b\n\
                  n1 127.0.0.1 127.0.0.1 n1 .xerj-memory-bob-edges 0b\n";
        let out = prune_rows("/_cat/fielddata", fd, &p, &known);
        assert!(out.contains("logs-2026"));
        assert!(!out.contains(".xerj-memory-bob-edges"));
    }

    /// A `_cat/templates` row is keyed by TEMPLATE name. It must not be
    /// matched against index names — a template and an index may share one.
    #[test]
    fn cat_templates_rows_are_never_index_matched() {
        let p = scoped(&["logs-2026"], &[Privilege::ReadIndex]);
        let known: HashSet<String> = ["count"].iter().map(|s| s.to_string()).collect();
        assert!(cat_index_columns(&segments("/_cat/templates")).is_none());
        assert!(prune_sites(&segments("/_cat/templates")).is_empty());
        let rows = "count logs-* 100 -\n";
        assert_eq!(prune_rows("/_cat/templates", rows, &p, &known), rows);
    }

    /// FINDING C. Pinned, not fixed: `names: ["*"]` matches everything,
    /// including `.xerj-memory-*`. Only a superuser can mint a scoped key, so
    /// this is an operator's explicit "the whole node" rather than an
    /// escalation — but it must not change without someone meaning it.
    /// See `xerj_engine::rbac::Role::applies_to`.
    #[test]
    fn a_star_grant_reaches_the_reserved_namespace() {
        let star = scoped(&["*"], &[Privilege::ReadIndex, Privilege::WriteIndex]);
        assert!(star.allows_index(".xerj-memory-bob-edges", Privilege::ReadIndex));
        assert!(check(
            &star,
            Method::GET,
            "/.xerj-memory-bob-edges/_search",
            ""
        ));
        assert!(check(&star, Method::GET, "/_memory/bob", ""));
        // A prefix grant that stops short of the reserved namespace does not.
        let logs = scoped(&["logs-*"], &[Privilege::ReadIndex]);
        assert!(!logs.allows_index(".xerj-memory-bob-edges", Privilege::ReadIndex));
        assert!(!check(
            &logs,
            Method::GET,
            "/.xerj-memory-bob-edges/_search",
            ""
        ));
        // …and `*` is still not a licence to squat the namespace with a
        // template, which decides the mapping of brains created later.
        assert!(!check(
            &star,
            Method::PUT,
            "/_index_template/t",
            r#"{"index_patterns":[".xerj-memory-*"]}"#
        ));
    }

    /// FINDING A, config half. The ML config endpoints name an index the
    /// server will then go and read on a schedule; before this they were
    /// accepted with a 200 for a principal holding nothing on it.
    #[test]
    fn ml_config_authorizes_the_index_it_will_read() {
        let legacy = unscoped();
        let alice = scoped(&[".xerj-memory-alice-edges"], &[Privilege::ReadIndex]);

        for (path, body) in [
            (
                "/_ml/anomaly_detectors/leak2",
                r#"{"source_index":".xerj-memory-bob-edges","time_field":"created_at"}"#,
            ),
            (
                "/_ml/anomaly_detectors/leak2",
                r#"{"index":".xerj-memory-bob-edges"}"#,
            ),
            (
                "/_ml/anomaly_detectors/leak2",
                r#"{"source_index":"logs-2026","datafeed_config":{"indices":[".xerj-memory-bob-edges"]}}"#,
            ),
            (
                "/_ml/datafeeds/leak2-feed",
                r#"{"job_id":"leak2","indices":[".xerj-memory-bob-edges"]}"#,
            ),
            (
                "/_ml/datafeeds/leak2-feed",
                r#"{"job_id":"leak2","indexes":".xerj-memory-bob-edges"}"#,
            ),
        ] {
            assert!(
                !check(&legacy, Method::PUT, path, body),
                "unscoped key configured ML over a brain: PUT {path} {body}"
            );
            assert!(
                !check(&alice, Method::PUT, path, body),
                "alice configured ML over bob's brain: PUT {path} {body}"
            );
        }

        // Its own brain is fine, and so is an ordinary index for a key that
        // holds the general surface.
        assert!(check(
            &alice,
            Method::PUT,
            "/_ml/anomaly_detectors/mine",
            r#"{"source_index":".xerj-memory-alice-edges","time_field":"t"}"#
        ));
        assert!(check(
            &legacy,
            Method::PUT,
            "/_ml/anomaly_detectors/ok",
            r#"{"source_index":"logs-2026","time_field":"t"}"#
        ));
        // A datafeed that names no index inherits the (already authorized)
        // detector's source, so a scoped key is not refused for it.
        assert!(check(
            &alice,
            Method::PUT,
            "/_ml/datafeeds/mine-feed",
            r#"{"job_id":"mine"}"#
        ));
        // The sub-verbs carry no index of their own, so they are decided by
        // the pre-existing cluster rule and this change does not move them: a
        // key that holds the general surface may start a datafeed, a scoped
        // one may not (a cluster-level mutation naming nothing). Pinned so the
        // MlConfig arm cannot be read as having widened either one.
        assert_eq!(
            body_shape(&Method::POST, &segments("/_ml/datafeeds/f/_start")),
            BodyShape::None
        );
        assert!(check(
            &legacy,
            Method::POST,
            "/_ml/datafeeds/f/_start",
            "{}"
        ));
        assert!(!check(
            &alice,
            Method::POST,
            "/_ml/datafeeds/f/_start",
            "{}"
        ));
    }

    /// A template's patterns decide the mapping of indices that do not exist
    /// yet, so a pattern reaching the reserved namespace is a write to a brain
    /// by another route.
    #[test]
    fn index_template_patterns_cannot_reach_the_namespace() {
        let legacy = unscoped();
        assert!(check(
            &legacy,
            Method::PUT,
            "/_index_template/logs",
            r#"{"index_patterns":["logs-*"]}"#
        ));
        for patterns in [
            r#"{"index_patterns":[".xerj-memory-*"]}"#,
            r#"{"index_patterns":["*"]}"#,
            r#"{"index_patterns":[".xerj-memory-bob-edges"]}"#,
            r#"{"index_patterns":"logs-*,.xerj-*"}"#,
        ] {
            assert!(
                !check(&legacy, Method::PUT, "/_index_template/grab", patterns),
                "{patterns} must be refused"
            );
            assert!(
                !check(&legacy, Method::PUT, "/_template/grab", patterns),
                "legacy template {patterns} must be refused"
            );
        }
        // The superuser still registers whatever it likes.
        assert!(check(
            &Principal::Superuser,
            Method::PUT,
            "/_index_template/grab",
            r#"{"index_patterns":["*"]}"#
        ));
    }

    /// The engine-side backstop is derived from the same principal, so a name
    /// the middleware never parsed is still refused where it is resolved.
    #[test]
    fn visibility_matches_the_principal() {
        let alice = scoped(&[".xerj-memory-alice-edges"], &[Privilege::ReadIndex]);
        let v = visibility_for(&alice);
        assert!(v.visible(".xerj-memory-alice-edges"));
        assert!(!v.visible(".xerj-memory-bob-edges"));
        assert!(!v.visible("logs-2026"));

        let legacy = visibility_for(&unscoped());
        assert!(legacy.visible("logs-2026"));
        assert!(!legacy.visible(".xerj-memory-bob-edges"));

        let root = visibility_for(&Principal::Superuser);
        assert!(root.visible(".xerj-memory-bob-edges"));

        let denied = visibility_for(&Principal::Denied);
        assert!(!denied.visible("logs-2026"));
    }
}

//! Zero-overhead binary protocol for xerj.
//!
//! # Wire format
//!
//! Every message (request and response) uses a fixed 5-byte header followed by
//! a variable-length JSON payload:
//!
//! ```text
//! ┌──────────────────────┬───────────┬──────────────────────────────────┐
//! │  length  (4 bytes LE)│ op (1 byte│ payload  (length bytes, UTF-8 JSON)│
//! └──────────────────────┴───────────┴──────────────────────────────────┘
//! ```
//!
//! * **length** — `u32` little-endian: byte length of the payload that follows.
//! * **op** — one of the [`op`] constants; determines how the server interprets
//!   the payload.
//! * **payload** — JSON-encoded request or response body (no trailing newline).
//!
//! # Operation codes
//!
//! | Op | Value | Direction | Description |
//! |----|-------|-----------|-------------|
//! | SEARCH | 1 | client→server | Full-text / structured search |
//! | INDEX  | 2 | client→server | Index a single document |
//! | GET    | 3 | client→server | Retrieve a document by ID |
//! | DELETE | 4 | client→server | Delete a document by ID |
//! | BULK   | 5 | client→server | Batch-index multiple documents |
//! | HEALTH | 6 | client→server | Cluster health probe |
//! | RESP_OK  | 64 | server→client | Success response |
//! | RESP_ERR | 65 | server→client | Error response |
//!
//! # Example session
//!
//! ```text
//! client  → [0x02 0x00 0x00 0x00] [0x06] {}  (HEALTH, 2-byte payload)
//! server  → [0x31 0x00 0x00 0x00] [0x40] {"status":"green","num_indices":0,"total_docs":0}
//!                                        (RESP_OK, 49-byte payload)
//! ```

use std::sync::Arc;

use serde::{Deserialize, Serialize};
use serde_json::Value;
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{TcpListener, TcpStream},
};
use tracing::{debug, error, info, warn};
use uuid::Uuid;
use xerj_query::parse_request;

use crate::state::AppState;

// ─────────────────────────────────────────────────────────────────────────────
// Op codes
// ─────────────────────────────────────────────────────────────────────────────

/// Op-code constants for the xerj binary protocol.
pub mod op {
    pub const SEARCH: u8 = 1;
    pub const INDEX: u8 = 2;
    pub const GET: u8 = 3;
    pub const DELETE: u8 = 4;
    pub const BULK: u8 = 5;
    pub const HEALTH: u8 = 6;
    pub const RESP_OK: u8 = 64;
    pub const RESP_ERR: u8 = 65;
}

// ─────────────────────────────────────────────────────────────────────────────
// Request / response payload types
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
struct BinSearchRequest {
    index: String,
    #[serde(default)]
    query: Option<Value>,
    #[serde(default = "default_size")]
    size: usize,
    #[serde(default)]
    from: usize,
}

fn default_size() -> usize {
    10
}

#[derive(Debug, Deserialize)]
struct BinIndexRequest {
    index: String,
    #[serde(default)]
    id: Option<String>,
    source: Value,
}

#[derive(Debug, Deserialize)]
struct BinGetRequest {
    index: String,
    id: String,
}

#[derive(Debug, Deserialize)]
struct BinDeleteRequest {
    index: String,
    id: String,
}

#[derive(Debug, Deserialize)]
struct BinBulkRequest {
    index: String,
    docs: Vec<Value>,
}

// ─────────────────────────────────────────────────────────────────────────────
// Frame I/O helpers
// ─────────────────────────────────────────────────────────────────────────────

/// Read a single framed message: `[u32-LE length][u8 op][payload]`.
///
/// Returns `(op, payload_bytes)` or an I/O error.
async fn read_frame(stream: &mut TcpStream) -> std::io::Result<(u8, Vec<u8>)> {
    let mut header = [0u8; 5];
    stream.read_exact(&mut header).await?;
    let length = u32::from_le_bytes([header[0], header[1], header[2], header[3]]) as usize;
    let op = header[4];

    let mut payload = vec![0u8; length];
    if length > 0 {
        stream.read_exact(&mut payload).await?;
    }
    Ok((op, payload))
}

/// Write a framed response: `[u32-LE length][u8 op][payload]`.
async fn write_frame(stream: &mut TcpStream, op: u8, payload: &[u8]) -> std::io::Result<()> {
    let length = payload.len() as u32;
    let mut header = [0u8; 5];
    header[..4].copy_from_slice(&length.to_le_bytes());
    header[4] = op;
    stream.write_all(&header).await?;
    if !payload.is_empty() {
        stream.write_all(payload).await?;
    }
    stream.flush().await?;
    Ok(())
}

/// Serialize `value` and write it as an `RESP_OK` frame.
async fn respond_ok(stream: &mut TcpStream, value: &impl Serialize) -> std::io::Result<()> {
    let payload = serde_json::to_vec(value).unwrap_or_else(|_| b"{}".to_vec());
    write_frame(stream, op::RESP_OK, &payload).await
}

/// Write a JSON error string as a `RESP_ERR` frame.
async fn respond_err(stream: &mut TcpStream, msg: &str) -> std::io::Result<()> {
    let payload = serde_json::to_vec(&serde_json::json!({ "error": msg }))
        .unwrap_or_else(|_| b"{\"error\":\"unknown\"}".to_vec());
    write_frame(stream, op::RESP_ERR, &payload).await
}

// ─────────────────────────────────────────────────────────────────────────────
// Per-connection handler
// ─────────────────────────────────────────────────────────────────────────────

async fn handle_connection(mut stream: TcpStream, state: Arc<AppState>) {
    let peer = stream
        .peer_addr()
        .map(|a| a.to_string())
        .unwrap_or_else(|_| "unknown".to_string());
    debug!(peer = peer.as_str(), "binary protocol: new connection");

    loop {
        let (op_code, payload) = match read_frame(&mut stream).await {
            Ok(frame) => frame,
            Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
                debug!(peer = peer.as_str(), "binary protocol: client disconnected");
                break;
            }
            Err(e) => {
                warn!(peer = peer.as_str(), error = %e, "binary protocol: read error");
                break;
            }
        };

        let result = dispatch(&mut stream, op_code, &payload, &state).await;
        if let Err(e) = result {
            error!(peer = peer.as_str(), error = %e, "binary protocol: write error");
            break;
        }
    }
}

/// Dispatch a single request frame to the appropriate handler and write the
/// response frame back to the stream.
async fn dispatch(
    stream: &mut TcpStream,
    op_code: u8,
    payload: &[u8],
    state: &Arc<AppState>,
) -> std::io::Result<()> {
    match op_code {
        op::SEARCH => handle_search(stream, payload, state).await,
        op::INDEX => handle_index(stream, payload, state).await,
        op::GET => handle_get(stream, payload, state).await,
        op::DELETE => handle_delete(stream, payload, state).await,
        op::BULK => handle_bulk(stream, payload, state).await,
        op::HEALTH => handle_health(stream, state).await,
        unknown => {
            warn!(op = unknown, "binary protocol: unknown op code");
            respond_err(stream, &format!("unknown op code: {unknown}")).await
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Individual op handlers
// ─────────────────────────────────────────────────────────────────────────────

async fn handle_search(
    stream: &mut TcpStream,
    payload: &[u8],
    state: &Arc<AppState>,
) -> std::io::Result<()> {
    let req: BinSearchRequest = match serde_json::from_slice(payload) {
        Ok(r) => r,
        Err(e) => return respond_err(stream, &format!("bad search request: {e}")).await,
    };

    let idx = match state.engine.get_index(&req.index) {
        Ok(i) => i,
        Err(e) => return respond_err(stream, &e.to_string()).await,
    };

    let query_body = if let Some(q) = req.query {
        serde_json::json!({ "query": q, "from": req.from, "size": req.size })
    } else {
        serde_json::json!({ "query": { "match_all": {} }, "from": req.from, "size": req.size })
    };

    let search_req = match parse_request(&query_body) {
        Ok(r) => r,
        Err(e) => return respond_err(stream, &format!("invalid query: {e}")).await,
    };

    let started = std::time::Instant::now();
    match idx.search(&search_req).await {
        Ok(result) => {
            let took_ms = started.elapsed().as_millis() as i64;
            let hits: Vec<Value> = result
                .hits
                .iter()
                .map(|h| {
                    serde_json::json!({
                        "id": h.id,
                        "score": h.score,
                        "source": h.source,
                        "index": req.index,
                    })
                })
                .collect();
            let resp = serde_json::json!({
                "total_hits": result.total.value,
                "hits": hits,
                "took_ms": took_ms,
                "timed_out": false,
            });
            respond_ok(stream, &resp).await
        }
        Err(e) => respond_err(stream, &e.to_string()).await,
    }
}

async fn handle_index(
    stream: &mut TcpStream,
    payload: &[u8],
    state: &Arc<AppState>,
) -> std::io::Result<()> {
    let req: BinIndexRequest = match serde_json::from_slice(payload) {
        Ok(r) => r,
        Err(e) => return respond_err(stream, &format!("bad index request: {e}")).await,
    };

    let idx = match state.engine.get_index(&req.index) {
        Ok(i) => i,
        Err(e) => return respond_err(stream, &e.to_string()).await,
    };

    let id = req.id.unwrap_or_else(|| Uuid::new_v4().to_string());
    match idx.index_document(Some(id.clone()), req.source).await {
        Ok(r) => {
            state.metrics.record_doc_indexed(&req.index);
            let resp = serde_json::json!({
                "id": r.id,
                "version": r.seq_no as i64,
                "result": r.result,
            });
            respond_ok(stream, &resp).await
        }
        Err(e) => respond_err(stream, &e.to_string()).await,
    }
}

async fn handle_get(
    stream: &mut TcpStream,
    payload: &[u8],
    state: &Arc<AppState>,
) -> std::io::Result<()> {
    let req: BinGetRequest = match serde_json::from_slice(payload) {
        Ok(r) => r,
        Err(e) => return respond_err(stream, &format!("bad get request: {e}")).await,
    };

    let idx = match state.engine.get_index(&req.index) {
        Ok(i) => i,
        Err(e) => return respond_err(stream, &e.to_string()).await,
    };

    match idx.get_document(&req.id).await {
        Ok(Some(source)) => {
            let resp = serde_json::json!({
                "found": true,
                "id": req.id,
                "source_json": source.to_string(),
                "version": 1i64,
            });
            respond_ok(stream, &resp).await
        }
        Ok(None) => {
            let resp = serde_json::json!({
                "found": false,
                "id": req.id,
                "source_json": "",
                "version": 0i64,
            });
            respond_ok(stream, &resp).await
        }
        Err(e) => respond_err(stream, &e.to_string()).await,
    }
}

async fn handle_delete(
    stream: &mut TcpStream,
    payload: &[u8],
    state: &Arc<AppState>,
) -> std::io::Result<()> {
    let req: BinDeleteRequest = match serde_json::from_slice(payload) {
        Ok(r) => r,
        Err(e) => return respond_err(stream, &format!("bad delete request: {e}")).await,
    };

    let idx = match state.engine.get_index(&req.index) {
        Ok(i) => i,
        Err(e) => return respond_err(stream, &e.to_string()).await,
    };

    match idx.delete_document(&req.id).await {
        Ok(_) => {
            let resp = serde_json::json!({ "result": "deleted" });
            respond_ok(stream, &resp).await
        }
        Err(e) => respond_err(stream, &e.to_string()).await,
    }
}

async fn handle_bulk(
    stream: &mut TcpStream,
    payload: &[u8],
    state: &Arc<AppState>,
) -> std::io::Result<()> {
    let req: BinBulkRequest = match serde_json::from_slice(payload) {
        Ok(r) => r,
        Err(e) => return respond_err(stream, &format!("bad bulk request: {e}")).await,
    };

    let idx = match state.engine.get_index(&req.index) {
        Ok(i) => i,
        Err(e) => return respond_err(stream, &e.to_string()).await,
    };

    let started = std::time::Instant::now();
    let total = req.docs.len() as i32;
    let mut indexed = 0i32;
    let mut errors = false;

    // One embedding pass for the whole batch, not one per document. The
    // engine's `index_documents_batched` routes the batch through the same
    // `apply_semantic_embeddings_batch` entry the HTTP `_bulk` path uses, so
    // both bulk entry points share one batching rule; publication is still
    // per document and per-document failures stay isolated (#903).
    let docs: Vec<(Option<String>, Value)> = req
        .docs
        .into_iter()
        .map(|doc| {
            let id = doc
                .get("_id")
                .and_then(Value::as_str)
                .map(str::to_owned)
                .unwrap_or_else(|| Uuid::new_v4().to_string());
            (Some(id), doc)
        })
        .collect();

    for result in idx.index_documents_batched(docs).await {
        if result.is_ok() {
            indexed += 1;
            state.metrics.record_doc_indexed(&req.index);
        } else {
            errors = true;
        }
    }

    let took_ms = started.elapsed().as_millis() as i64;
    let resp = serde_json::json!({
        "took_ms": took_ms,
        "errors": errors,
        "indexed": indexed,
        "total": total,
    });
    respond_ok(stream, &resp).await
}

async fn handle_health(stream: &mut TcpStream, state: &Arc<AppState>) -> std::io::Result<()> {
    let health = state.engine.health().await;
    let resp = serde_json::json!({
        "status": health.status,
        "num_indices": health.index_count as i32,
        "total_docs": health.total_docs as i64,
    });
    respond_ok(stream, &resp).await
}

// ─────────────────────────────────────────────────────────────────────────────
// Server entry-point
// ─────────────────────────────────────────────────────────────────────────────

/// Start the binary protocol TCP server on `addr`.
///
/// Each connection is handled in its own Tokio task; the server runs until
/// the returned future is dropped or a fatal error occurs.
///
/// # Example
///
/// ```no_run
/// # use std::sync::Arc;
/// # use xerj_api::binary_protocol::serve_binary_protocol;
/// # use xerj_api::state::AppState;
/// # async fn run(state: Arc<AppState>) {
/// serve_binary_protocol("0.0.0.0:8081".parse().unwrap(), state).await.unwrap();
/// # }
/// ```
pub async fn serve_binary_protocol(
    addr: std::net::SocketAddr,
    state: Arc<AppState>,
) -> std::io::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!(addr = %addr, "binary protocol: listening");

    loop {
        let (stream, peer) = match listener.accept().await {
            Ok(pair) => pair,
            Err(e) => {
                error!(error = %e, "binary protocol: accept error");
                continue;
            }
        };
        debug!(peer = %peer, "binary protocol: accepted connection");
        let state = Arc::clone(&state);
        tokio::spawn(async move {
            handle_connection(stream, state).await;
        });
    }
}

#[cfg(test)]
mod tests {
    //! #903: the binary `_bulk` handler must not embed one document per
    //! inference call.
    //!
    //! The backend here is an OpenAI-compatible proxy served on an ephemeral
    //! local port, because `EmbeddingProxy::embed_batch` issues exactly one
    //! HTTP POST per call — so the request count *is* the inference-call
    //! count, with no model download and no timing noise. The default lexical
    //! embedder is deliberately not used: it is not an active backend, it runs
    //! no batched inference, and a test against it would prove nothing here.

    use std::sync::atomic::{AtomicUsize, Ordering};

    use serde_json::json;
    use xerj_common::types::{FieldConfig, FieldType, Schema};

    use super::*;

    const DIMS: usize = 8;

    /// What the embedding backend was actually asked to do.
    struct BackendCalls {
        calls: Arc<AtomicUsize>,
        widest_call: Arc<AtomicUsize>,
        texts: Arc<AtomicUsize>,
    }

    /// A mock OpenAI-compatible `/v1/embeddings` endpoint on an ephemeral port.
    async fn mock_embedding_backend() -> (String, BackendCalls) {
        mock_embedding_backend_with_width(DIMS).await
    }

    /// The same mock, answering with vectors of `width` dimensions.
    async fn mock_embedding_backend_with_width(width: usize) -> (String, BackendCalls) {
        let calls = Arc::new(AtomicUsize::new(0));
        let widest_call = Arc::new(AtomicUsize::new(0));
        let texts = Arc::new(AtomicUsize::new(0));
        let (c, w, t) = (
            Arc::clone(&calls),
            Arc::clone(&widest_call),
            Arc::clone(&texts),
        );
        let app = axum::Router::new().route(
            "/v1/embeddings",
            axum::routing::post(move |axum::Json(body): axum::Json<Value>| {
                let (c, w, t) = (Arc::clone(&c), Arc::clone(&w), Arc::clone(&t));
                async move {
                    let n = body
                        .get("input")
                        .and_then(Value::as_array)
                        .map(Vec::len)
                        .unwrap_or(0);
                    c.fetch_add(1, Ordering::SeqCst);
                    t.fetch_add(n, Ordering::SeqCst);
                    w.fetch_max(n, Ordering::SeqCst);
                    let data: Vec<Value> = (0..n)
                        .map(|i| {
                            let embedding: Vec<f64> = (0..width)
                                .map(|d| ((i + d) % 7) as f64 / 7.0 + 0.1)
                                .collect();
                            json!({ "index": i, "embedding": embedding })
                        })
                        .collect();
                    axum::Json(json!({ "data": data }))
                }
            }),
        );
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind mock backend");
        let addr = listener.local_addr().expect("mock backend addr");
        tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        (
            format!("http://{addr}/v1/embeddings"),
            BackendCalls {
                calls,
                widest_call,
                texts,
            },
        )
    }

    /// An index with one `semantic_text`-shaped field, served by the binary
    /// protocol on an ephemeral port. The temp dir must outlive the engine.
    async fn node(endpoint: String) -> (std::net::SocketAddr, tempfile::TempDir) {
        let (config, engine, dir) = semantic_engine(endpoint);
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let state = Arc::new(crate::state::AppState::new(config, engine, metrics));
        let listener = TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind binary protocol");
        let addr = listener.local_addr().expect("binary protocol addr");
        tokio::spawn(async move {
            while let Ok((stream, _)) = listener.accept().await {
                tokio::spawn(handle_connection(stream, Arc::clone(&state)));
            }
        });
        (addr, dir)
    }

    /// An engine with a `notes` index holding one `semantic_text`-shaped
    /// field of `DIMS` dimensions, embedded by the proxy at `endpoint`.
    fn semantic_engine(
        endpoint: String,
    ) -> (
        xerj_common::config::Config,
        xerj_engine::Engine,
        tempfile::TempDir,
    ) {
        let dir = tempfile::tempdir().expect("tempdir");
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        config.embedding.mode = "proxy".into();
        config.embedding.default_endpoint = endpoint;
        config.embedding.default_model = "mock-embed".into();

        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");

        let mut schema = Schema::empty();
        let mut body = FieldConfig::new("body", FieldType::Text);
        body.options.dimensions = Some(DIMS);
        body.options.similarity = Some("cosine".into());
        body.embedding = Some(xerj_common::types::EmbeddingConfig {
            endpoint: None,
            model: None,
            target_field: Some("body_vector".into()),
        });
        schema.add_field(body).expect("semantic field");
        let mut companion = FieldConfig::new("body_vector", FieldType::Vector);
        companion.options.dimensions = Some(DIMS);
        companion.options.similarity = Some("cosine".into());
        schema.add_field(companion).expect("companion field");
        engine.create_index("notes", schema).expect("create index");
        (config, engine, dir)
    }

    /// One framed request/response round trip on a fresh connection.
    async fn round_trip(addr: std::net::SocketAddr, op_code: u8, payload: Value) -> Value {
        let mut stream = TcpStream::connect(addr).await.expect("connect");
        let body = serde_json::to_vec(&payload).expect("serialize");
        let mut header = [0u8; 5];
        header[..4].copy_from_slice(&(body.len() as u32).to_le_bytes());
        header[4] = op_code;
        stream.write_all(&header).await.expect("write header");
        stream.write_all(&body).await.expect("write payload");
        stream.flush().await.expect("flush");

        let mut resp_header = [0u8; 5];
        stream
            .read_exact(&mut resp_header)
            .await
            .expect("read header");
        let length = u32::from_le_bytes([
            resp_header[0],
            resp_header[1],
            resp_header[2],
            resp_header[3],
        ]) as usize;
        let mut resp = vec![0u8; length];
        stream.read_exact(&mut resp).await.expect("read payload");
        assert_eq!(
            resp_header[4],
            op::RESP_OK,
            "response: {}",
            String::from_utf8_lossy(&resp)
        );
        serde_json::from_slice(&resp).expect("response json")
    }

    /// #903: a bulk of N single-passage documents must reach the embedding
    /// backend as ONE inference call carrying all N passages, not N calls of
    /// one passage each. Before the fix `handle_bulk` looped `index_document`
    /// per document and this assertion saw 12 calls of width 1.
    #[tokio::test]
    async fn binary_bulk_embeds_the_whole_batch_in_one_inference_call() {
        let (endpoint, backend) = mock_embedding_backend().await;
        let (addr, _dir) = node(endpoint).await;

        const DOCS: usize = 12;
        let docs: Vec<Value> = (0..DOCS)
            .map(|i| json!({ "_id": format!("d{i}"), "body": format!("passage number {i}") }))
            .collect();
        let response = round_trip(addr, op::BULK, json!({ "index": "notes", "docs": docs })).await;

        assert_eq!(
            response["errors"],
            json!(false),
            "bulk response: {response}"
        );
        assert_eq!(
            response["indexed"],
            json!(DOCS as i64),
            "bulk response: {response}"
        );
        assert_eq!(
            backend.texts.load(Ordering::SeqCst),
            DOCS,
            "every document's passage must still be embedded exactly once"
        );
        assert_eq!(
            backend.widest_call.load(Ordering::SeqCst),
            DOCS,
            "the whole batch must share one inference window"
        );
        assert_eq!(
            backend.calls.load(Ordering::SeqCst),
            1,
            "{DOCS} single-passage documents must cost 1 inference call, not one per document"
        );
    }

    /// Batching must not widen a single document's failure into the batch's:
    /// publication stays per document, and the response still counts only what
    /// was actually indexed.
    #[tokio::test]
    async fn a_rejected_document_does_not_fail_its_neighbours() {
        let (endpoint, backend) = mock_embedding_backend().await;
        let (addr, _dir) = node(endpoint).await;

        // `body_vector` is the engine-owned target of the semantic field, so
        // hand-supplied passage metadata for it is rejected per document.
        let metadata_field = format!(
            "{}body_vector",
            xerj_query::executor::PASSAGE_METADATA_PREFIX
        );
        let docs = vec![
            json!({ "_id": "ok-1", "body": "first passage" }),
            json!({
                "_id": "bad",
                "body": "second passage",
                metadata_field.clone(): { "field": "body", "chunks": [[0, 3]] }
            }),
            json!({ "_id": "ok-2", "body": "third passage" }),
        ];
        let response = round_trip(addr, op::BULK, json!({ "index": "notes", "docs": docs })).await;

        assert_eq!(response["total"], json!(3), "bulk response: {response}");
        assert_eq!(response["indexed"], json!(2), "bulk response: {response}");
        assert_eq!(response["errors"], json!(true), "bulk response: {response}");
        assert_eq!(
            backend.calls.load(Ordering::SeqCst),
            1,
            "the surviving documents still share one inference call"
        );

        let found = round_trip(addr, op::GET, json!({ "index": "notes", "id": "ok-2" })).await;
        assert_eq!(found["found"], json!(true), "get response: {found}");
        let missing = round_trip(addr, op::GET, json!({ "index": "notes", "id": "bad" })).await;
        assert_eq!(missing["found"], json!(false), "get response: {missing}");
    }

    /// #2191: a backend whose vector width contradicts the mapping fails the
    /// document with a 400 mapping error, not a retryable 500 backend error —
    /// the width is fixed, so a client retry loop could never succeed.
    #[tokio::test]
    async fn an_embedding_width_mismatch_is_a_per_item_400() {
        let (endpoint, _backend) = mock_embedding_backend_with_width(DIMS / 2).await;
        let (_config, engine, _dir) = semantic_engine(endpoint);
        let idx = engine.get_index("notes").expect("index");

        let results = idx
            .index_documents_batched(vec![(Some("d0".into()), json!({ "body": "a passage" }))])
            .await;
        assert_eq!(results.len(), 1);
        let error = results[0].as_ref().expect_err("a width mismatch must fail");
        let xerj_engine::EngineError::Common(common) = error else {
            panic!("expected a common error, got {error:?}");
        };
        assert_eq!(common.http_status(), 400, "{common}");
        let message = common.to_string();
        assert!(message.contains("mapping requires"), "{message}");
        assert!(message.contains("dimensions"), "{message}");
    }
}

//! The shared `_cat` table renderer — ES's RestTable semantics for the
//! common query parameters, implemented once (#1201).
//!
//! Every `_cat` endpoint accepts the same formatting params in ES
//! (`/_cat` common params, ES 8.13):
//!
//! - `h=a,b` — select and order the displayed columns; `*` selects all in
//!   default order. A name the endpoint does not have is dropped (ES's
//!   behaviour — a miss does not error). If nothing recognised remains the
//!   response body is empty (text) / `[]` (json).
//! - `v` — verbose: adds a header row of the (selected) column names, text
//!   format only. The header prints even when there are no rows.
//! - `bytes=b|k|kb|m|mb|g|gb|t|tb|p|pb` — re-renders byte-size columns in
//!   that unit as a plain integer: single-letter units are decimal (`k` =
//!   10³), two-letter units binary (`kb` = 2¹⁰). An unknown value is a 400
//!   naming the valid ones — the accepted-and-ignored class (#204) is what
//!   this module exists to close.
//! - `format=json` — an array of objects with string values, `h` respected.
//!
//! Text cells join with a single space; under `v` every cell (header
//! included) is additionally right-padded to its column's widest value —
//! the alignment `?v` is the documented way to get in ES.

use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde_json::{json, Value};

use crate::error::ApiError;

/// One rendered cell. `size_bytes` marks a byte-size column: `text` is the
/// default human rendering (`767b`, `4.6mb`), and a `bytes=` param re-renders
/// the cell from the raw count.
pub struct CatCell {
    pub text: String,
    pub size_bytes: Option<u64>,
}

impl CatCell {
    /// A plain (non-size) cell.
    pub fn plain(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            size_bytes: None,
        }
    }

    /// A byte-size cell; `text` should be `human_bytes(bytes)` so the
    /// default rendering matches the endpoint's pre-`bytes=` output.
    pub fn size(bytes: u64, text: String) -> Self {
        Self {
            text,
            size_bytes: Some(bytes),
        }
    }
}

/// The `bytes=` unit. Single letters are decimal powers, two letters binary
/// (ES's documented split).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ByteUnit {
    B,
    K,
    Kb,
    M,
    Mb,
    G,
    Gb,
    T,
    Tb,
    P,
    Pb,
}

impl ByteUnit {
    /// Parse a `bytes=` value; `None` when the value is not one of ES's.
    pub fn parse(raw: &str) -> Option<Self> {
        Some(match raw.trim() {
            "b" => Self::B,
            "k" => Self::K,
            "kb" => Self::Kb,
            "m" => Self::M,
            "mb" => Self::Mb,
            "g" => Self::G,
            "gb" => Self::Gb,
            "t" => Self::T,
            "tb" => Self::Tb,
            "p" => Self::P,
            "pb" => Self::Pb,
            _ => return None,
        })
    }

    /// Render `bytes` in this unit as the integer ES prints (truncated).
    pub fn render(self, bytes: u64) -> String {
        let divisor = match self {
            Self::B => 1.0,
            Self::K => 1e3,
            Self::Kb => 1024.0,
            Self::M => 1e6,
            Self::Mb => 1024.0 * 1024.0,
            Self::G => 1e9,
            Self::Gb => 1024.0 * 1024.0 * 1024.0,
            Self::T => 1e12,
            Self::Tb => 1024.0 * 1024.0 * 1024.0 * 1024.0,
            Self::P => 1e15,
            Self::Pb => 1024.0 * 1024.0 * 1024.0 * 1024.0 * 1024.0,
        };
        ((bytes as f64 / divisor) as u64).to_string()
    }
}

/// The resolved formatting params shared by every `_cat` endpoint.
#[derive(Debug, Default, Clone)]
pub struct CatParams {
    /// `v` — verbose header (any of `""`, `true`, `1`, `yes`).
    pub v: bool,
    /// `format=json`.
    pub json: bool,
    /// `h=` raw value (comma-separated column selection).
    pub h: Option<String>,
    /// `bytes=` raw value, validated.
    pub bytes: Option<ByteUnit>,
}

impl CatParams {
    /// Resolve the raw query struct. Unknown `bytes=` values are a 400
    /// naming the valid units (honoured-or-refused, never ignored);
    /// `v=` accepts the boolean spellings and refuses anything else the
    /// same way.
    pub fn resolve(
        v: Option<&str>,
        format: Option<&str>,
        h: Option<&str>,
        bytes: Option<&str>,
    ) -> Result<Self, ApiError> {
        let v = match v {
            None => false,
            Some(raw) => match raw.trim() {
                "" | "true" | "1" | "yes" => true,
                "false" | "0" | "no" => false,
                other => {
                    return Err(ApiError::new(xerj_common::XerjError::invalid_query(
                        format!("unknown v value `{other}` (expected true or false)"),
                    )))
                }
            },
        };
        let bytes = match bytes {
            None => None,
            Some(raw) => Some(ByteUnit::parse(raw).ok_or_else(|| {
                ApiError::new(xerj_common::XerjError::invalid_query(format!(
                    "unknown bytes value `{raw}` (expected one of: b, k, kb, m, mb, g, gb, t, tb, p, pb)"
                )))
            })?),
        };
        Ok(Self {
            v,
            json: format == Some("json"),
            h: h.map(str::to_string),
            bytes,
        })
    }
}

/// A `_cat` table: default column names in order, and rows of cells.
pub struct CatTable {
    pub columns: Vec<&'static str>,
    pub rows: Vec<Vec<CatCell>>,
}

impl CatTable {
    /// Column indices selected by `h`, in request order. `*` expands to the
    /// full default order; unknown names are dropped (ES drops a miss, it
    /// does not error); an empty/missing `h` selects everything.
    fn selected(&self, h: Option<&str>) -> Vec<usize> {
        let all: Vec<usize> = (0..self.columns.len()).collect();
        let Some(h) = h else {
            return all;
        };
        let mut out = Vec::new();
        for entry in h.split(',').map(str::trim).filter(|s| !s.is_empty()) {
            if entry == "*" {
                out.extend(all.iter().copied());
                continue;
            }
            if let Some(i) = self.columns.iter().position(|c| *c == entry) {
                out.push(i);
            }
        }
        out
    }

    /// The cell's rendered text under an active `bytes=` unit.
    fn cell_text(cell: &CatCell, unit: Option<ByteUnit>) -> String {
        match (unit, cell.size_bytes) {
            (Some(u), Some(b)) => u.render(b),
            _ => cell.text.clone(),
        }
    }

    /// Render text or JSON. Text pads every cell (and the header) to the
    /// column's widest value and separates with one space; with `v` the
    /// header line prints even for an empty table.
    pub fn render(&self, params: &CatParams) -> Response {
        let cols = self.selected(params.h.as_deref());
        if params.json {
            let arr: Vec<Value> = self
                .rows
                .iter()
                .map(|row| {
                    let mut obj = serde_json::Map::new();
                    for &i in &cols {
                        let text = Self::cell_text(&row[i], params.bytes);
                        obj.insert(self.columns[i].to_string(), json!(text));
                    }
                    Value::Object(obj)
                })
                .collect();
            return Json(arr).into_response();
        }

        let header: Vec<&str> = cols.iter().map(|&i| self.columns[i]).collect();
        let body_rows: Vec<Vec<String>> = self
            .rows
            .iter()
            .map(|row| {
                cols.iter()
                    .map(|&i| Self::cell_text(&row[i], params.bytes))
                    .collect()
            })
            .collect();

        // ES pads columns only under `v` — that alignment is the documented
        // reason to send it. Without `v`, cells join with a single space.
        let widths: Vec<usize> = if params.v {
            let mut widths = vec![0usize; cols.len()];
            for (i, name) in header.iter().enumerate() {
                widths[i] = widths[i].max(name.chars().count());
            }
            for row in &body_rows {
                for (i, cell) in row.iter().enumerate() {
                    widths[i] = widths[i].max(cell.chars().count());
                }
            }
            widths
        } else {
            vec![0usize; cols.len()]
        };

        let mut lines: Vec<String> = Vec::new();
        if params.v {
            lines.push(render_row(
                &header.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
                &widths,
            ));
        }
        for row in &body_rows {
            lines.push(render_row(row, &widths));
        }

        let body = if lines.is_empty() {
            String::new()
        } else {
            lines.join("\n") + "\n"
        };
        (
            StatusCode::OK,
            [(
                axum::http::header::CONTENT_TYPE,
                "text/plain; charset=utf-8",
            )],
            body,
        )
            .into_response()
    }
}

/// One text row: pad every cell but the last to its column width, join
/// with a single space.
fn render_row(cells: &[String], widths: &[usize]) -> String {
    let last = cells.len().saturating_sub(1);
    cells
        .iter()
        .enumerate()
        .map(|(i, cell)| {
            if i == last {
                cell.clone()
            } else {
                let pad = widths[i].saturating_sub(cell.chars().count());
                format!("{cell}{}", " ".repeat(pad))
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn table() -> CatTable {
        CatTable {
            columns: vec!["index", "docs.count", "store.size"],
            rows: vec![
                vec![
                    CatCell::plain("books"),
                    CatCell::plain("120"),
                    CatCell::size(767, "767b".into()),
                ],
                vec![
                    CatCell::plain("films"),
                    CatCell::plain("9"),
                    CatCell::size(4_710_400, "4.5mb".into()),
                ],
            ],
        }
    }

    fn params(h: Option<&str>, v: bool, bytes: Option<&str>, json: bool) -> CatParams {
        let mut p = CatParams::resolve(None, if json { Some("json") } else { None }, h, bytes)
            .expect("params resolve");
        p.v = v;
        p
    }

    fn text(t: &CatTable, p: &CatParams) -> String {
        let resp = t.render(p);
        let body = axum::body::to_bytes(resp.into_body(), usize::MAX);
        // tests are sync; the body is a Full<Bytes> — extract via block_on
        let rt = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();
        let bytes = rt.block_on(body).unwrap();
        String::from_utf8(bytes.to_vec()).unwrap()
    }

    fn json_out(t: &CatTable, p: &CatParams) -> Value {
        let resp = t.render(p);
        let body = axum::body::to_bytes(resp.into_body(), usize::MAX);
        let rt = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();
        let bytes = rt.block_on(body).unwrap();
        serde_json::from_slice(&bytes).unwrap()
    }

    /// #1201: `h` selects and reorders columns, in text and json.
    #[test]
    fn h_selects_and_orders_columns() {
        let t = table();
        let out = text(&t, &params(Some("docs.count,index"), false, None, false));
        assert_eq!(out, "120 books\n9 films\n");

        let j = json_out(&t, &params(Some("index,store.size"), false, None, true));
        assert_eq!(
            j,
            serde_json::json!([
                {"index": "books", "store.size": "767b"},
                {"index": "films", "store.size": "4.5mb"},
            ])
        );
    }

    /// #1201: `h=*` is the full default order; an unknown name drops.
    #[test]
    fn h_star_selects_all_and_unknown_names_drop() {
        let t = table();
        let out = text(&t, &params(Some("*"), false, None, false));
        assert_eq!(out, "books 120 767b\nfilms 9 4.5mb\n");

        let dropped = text(&t, &params(Some("index,nosuch"), false, None, false));
        assert_eq!(dropped, "books\nfilms\n");
    }

    /// #1201: `v` adds a header row, aligned to the widest cell; it prints
    /// even when the table has no rows.
    #[test]
    fn v_adds_an_aligned_header_even_with_no_rows() {
        let mut t = table();
        let out = text(&t, &params(None, true, None, false));
        assert_eq!(
            out,
            "index docs.count store.size\nbooks 120        767b\nfilms 9          4.5mb\n"
        );

        t.rows.clear();
        let empty = text(&t, &params(None, true, None, false));
        assert_eq!(empty, "index docs.count store.size\n");
    }

    /// #1201: `bytes=b` re-renders size columns as plain integers; `kb` is
    /// binary (2¹⁰) and `k` decimal (10³); non-size columns are untouched.
    #[test]
    fn bytes_re_renders_size_columns_only() {
        let t = table();
        let b = text(&t, &params(None, false, Some("b"), false));
        assert_eq!(b, "books 120 767\nfilms 9 4710400\n");
        let kb = text(&t, &params(None, false, Some("kb"), false));
        assert_eq!(kb, "books 120 0\nfilms 9 4600\n");
        let k = text(&t, &params(None, false, Some("k"), false));
        assert_eq!(k, "books 120 0\nfilms 9 4710\n");

        let j = json_out(&t, &params(None, false, Some("b"), true));
        assert_eq!(j[0]["store.size"], json!("767"));
    }

    /// #1201: an unknown `bytes=` or `v=` value is a 400 naming the valid
    /// ones — never silently ignored.
    #[test]
    fn unknown_bytes_or_v_values_are_refused() {
        let err = CatParams::resolve(None, None, None, Some("mbb")).unwrap_err();
        let rt = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();
        let resp = rt.block_on(async {
            let r = err.into_response();
            let b = axum::body::to_bytes(r.into_body(), usize::MAX)
                .await
                .unwrap();
            String::from_utf8(b.to_vec()).unwrap()
        });
        assert!(resp.contains("bytes"), "{resp}");
        assert!(resp.contains("kb"), "{resp}");

        let err = CatParams::resolve(Some("maybe"), None, None, None).unwrap_err();
        let rt = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();
        let resp = rt.block_on(async {
            let r = err.into_response();
            let b = axum::body::to_bytes(r.into_body(), usize::MAX)
                .await
                .unwrap();
            String::from_utf8(b.to_vec()).unwrap()
        });
        assert!(resp.contains("v"), "{resp}");
    }

    /// `v` accepts the flag forms ES clients send (`?v`, `?v=true`) and the
    /// negatives.
    #[test]
    fn v_parses_its_boolean_forms() {
        for raw in ["", "true", "1", "yes"] {
            let p = CatParams::resolve(Some(raw), None, None, None).unwrap();
            assert!(p.v, "v={raw} must be verbose");
        }
        for raw in ["false", "0", "no"] {
            let p = CatParams::resolve(Some(raw), None, None, None).unwrap();
            assert!(!p.v, "v={raw} must not be verbose");
        }
    }

    /// An empty table with no `v` renders an empty body — ES's empty-listing
    /// shape (not a bare newline).
    #[test]
    fn empty_table_without_v_is_an_empty_body() {
        let mut t = table();
        t.rows.clear();
        let out = text(&t, &params(None, false, None, false));
        assert_eq!(out, "");
    }
}

//! Shard routing for the ES-compat document and search handlers.
//!
//! With a cluster handle attached, a replicated index carries a primary plan
//! in the same Raft entry as the create. [`dispatch_index`] forwards a
//! document to the owner [`Engine::route_write`] names. [`dispatch_update`]
//! and [`bulk_on_primaries`] send `_update` and `_bulk` to that same owner.
//! [`update_by_query_on_primaries`] runs `_update_by_query` on every primary
//! and each primary copies the documents it changed.
//! [`delete_by_query_on_primaries`] runs `_delete_by_query` on every primary
//! and each primary copies the deletes. Native `POST /v1/indices/{name}/docs`,
//! `DELETE /v1/indices/{name}/docs/{id}`, and
//! `POST /v1/indices/{name}/docs/_bulk` use the same primary. Logs, OTLP,
//! syslog, turbo, and pipeline ingest do not.
//! The primary copies an index, delete, or the document an update stored
//! onto the in-sync replicas and acknowledges the caller when a quorum of
//! the copies has confirmed. A replica that does not
//! confirm is dropped from the in-sync set when the rest already make a
//! quorum. That replica copies the primary's live documents when it can
//! answer again, and the primary then publishes it back into the in-sync
//! set. [`fanout_search`] asks every
//! primary and merges hits. If a primary does not answer, a GET or a search
//! of that shard reads a replica copy. Single-node mode (`has_cluster`
//! false) returns before any of this.
//!
//! Replica bytes live in a hidden per-shard index, not in the user index, so
//! a primary search does not count them twice. The owner's handler does not
//! route a `replica` apply again.

use std::collections::{HashMap, HashSet};
use std::sync::Arc;
use std::time::{Duration, Instant};

use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde_json::{json, Value};
use xerj_cluster::{ApplyEffect, ClusterCommand, ShardOp, ShardResult};

use crate::es_compat::{
    aggregate_by_query_results, apply_get_doc_source_filter, apply_local_update,
    pipeline_rejected_body, search_shard_local, unrunnable_pipeline_reason, EsSearchBody,
    EsSearchJson, EsSearchQueryParams, EsUpdateBody, GetDocParams, UpdateDocParams,
};
use crate::responses::{EsDeleteDocResponse, EsDocResponse, EsGetResponse};
use crate::state::AppState;
use crate::ApiError;

/// Per-shard `from + size` cap when a search is merged across owners.
const MAX_FANOUT_WINDOW: usize = 10_000;

/// How long a forward waits for the owner to apply the index create.
const OWNER_READY_WAIT: Duration = Duration::from_secs(2);

pub(crate) enum Dispatch {
    /// This node holds the shard (or the index has no plan). The caller
    /// uses its existing local path.
    Local,
    /// The response is complete: forwarded, or refused.
    Done(Response),
}

pub(crate) fn shard_not_ready_body(index: &str) -> String {
    json!({
        "error": {
            "type": "shard_not_ready",
            "reason": format!("index [{index}] is not on this shard yet")
        },
        "status": 503
    })
    .to_string()
}

pub(crate) fn shard_not_ready_response(index: &str) -> Response {
    (
        StatusCode::SERVICE_UNAVAILABLE,
        Json(json!({
            "error": {
                "type": "shard_not_ready",
                "reason": format!("index [{index}] is not on this shard yet")
            },
            "status": 503
        })),
    )
        .into_response()
}

fn http_result(result: ShardResult) -> Response {
    let status = StatusCode::from_u16(result.status).unwrap_or(StatusCode::BAD_GATEWAY);
    let value: Value = serde_json::from_str(&result.body).unwrap_or(Value::Null);
    (status, Json(value)).into_response()
}

fn is_shard_not_ready(result: &ShardResult) -> bool {
    result.status == 503 && result.body.contains("shard_not_ready")
}

fn engine_error_response(err: xerj_engine::EngineError) -> Response {
    ApiError::new(xerj_common::XerjError::from(err)).into_response()
}

async fn forward_retrying(state: &AppState, owner: &str, op: ShardOp) -> Response {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match state.engine.forward_shard(owner, op.clone()).await {
            Ok(result) if is_shard_not_ready(&result) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            Ok(result) => return http_result(result),
            Err(err) => return engine_error_response(err),
        }
    }
}

/// Route a prepared document. `Ok`-shaped [`Dispatch::Local`] means index here.
///
/// `op` is `"index"` or `"create"`. Sequence numbers are the engine's
/// internal (1-based) values.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn dispatch_index(
    state: &AppState,
    index: &str,
    id: &str,
    doc: &Value,
    op: &str,
    if_seq_no: Option<u64>,
    if_primary_term: Option<u64>,
    version: Option<u64>,
    version_type: Option<String>,
) -> Dispatch {
    if !state.engine.has_cluster() {
        return Dispatch::Local;
    }
    if state.engine.get_index(index).is_err() {
        if let Err(err) = state.engine.ensure_replicated_index(index).await {
            return Dispatch::Done(engine_error_response(err));
        }
    }
    let source_json = doc.to_string();
    if state.engine.owns_shard(index, id) {
        let result = local_index(
            state,
            index,
            id,
            &source_json,
            op,
            if_seq_no,
            if_primary_term,
            version,
            version_type.as_deref(),
            false,
            0,
        )
        .await;
        return Dispatch::Done(http_result(result));
    }
    let Some(owner) = state.engine.route_write(index, id) else {
        return Dispatch::Local;
    };
    let shard_op = ShardOp::IndexDoc {
        index: index.to_string(),
        id: id.to_string(),
        source_json,
        op: op.to_string(),
        if_seq_no,
        if_primary_term,
        version,
        version_type,
        replica: false,
        shard: 0,
    };
    Dispatch::Done(forward_retrying(state, &owner, shard_op).await)
}

pub(crate) async fn dispatch_get(
    state: &AppState,
    index: &str,
    id: &str,
    params: &GetDocParams,
) -> Dispatch {
    if !state.engine.has_cluster() {
        return Dispatch::Local;
    }
    let Some((shard, owner)) = state.engine.primary_of(index, id) else {
        return Dispatch::Local;
    };
    if owner == state.engine.routing_node_id() {
        return Dispatch::Local;
    }
    let op = ShardOp::GetDoc {
        index: index.to_string(),
        id: id.to_string(),
        source: params.source.clone(),
        source_includes: params.source_includes.clone(),
        source_excludes: params.source_excludes.clone(),
        replica: false,
        shard: 0,
    };
    if let Some(response) = forward_primary(state, &owner, op).await {
        return Dispatch::Done(response);
    }
    for replica in state.engine.replica_nodes(index, shard) {
        let op = ShardOp::GetDoc {
            index: index.to_string(),
            id: id.to_string(),
            source: params.source.clone(),
            source_includes: params.source_includes.clone(),
            source_excludes: params.source_excludes.clone(),
            replica: true,
            shard,
        };
        match state.engine.forward_shard(&replica, op).await {
            Ok(result) if !is_shard_not_ready(&result) => {
                return Dispatch::Done(http_result(result));
            }
            _ => continue,
        }
    }
    Dispatch::Done(shard_not_ready_response(index))
}

/// `Some` when the primary answered (including a 404). `None` when the
/// primary could not be reached, so the caller may read a replica.
async fn forward_primary(state: &AppState, owner: &str, op: ShardOp) -> Option<Response> {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match state.engine.forward_shard(owner, op.clone()).await {
            Ok(result) if is_shard_not_ready(&result) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            Ok(result) => return Some(http_result(result)),
            Err(_) => return None,
        }
    }
}

pub(crate) async fn dispatch_delete(
    state: &AppState,
    index: &str,
    id: &str,
    if_seq_no: Option<u64>,
    if_primary_term: Option<u64>,
) -> Dispatch {
    if !state.engine.has_cluster() {
        return Dispatch::Local;
    }
    if state.engine.owns_shard(index, id) {
        let result = local_delete(state, index, id, if_seq_no, if_primary_term, false, 0).await;
        return Dispatch::Done(http_result(result));
    }
    let Some(owner) = state.engine.route_write(index, id) else {
        return Dispatch::Local;
    };
    let op = ShardOp::DeleteDoc {
        index: index.to_string(),
        id: id.to_string(),
        if_seq_no,
        if_primary_term,
        replica: false,
        shard: 0,
    };
    Dispatch::Done(forward_retrying(state, &owner, op).await)
}

/// Route one `_update` to the shard primary. The primary applies the partial
/// document or the script and copies the stored source onto the in-sync replicas.
///
/// [`Dispatch::Local`] is only an index with no shard plan. Single-node mode
/// does not call this.
pub(crate) async fn dispatch_update(
    state: &AppState,
    index: &str,
    id: &str,
    body: &EsUpdateBody,
    params: &UpdateDocParams,
) -> Dispatch {
    if !state.engine.has_cluster() {
        return Dispatch::Local;
    }
    let concrete = match ensure_concrete_index(state, index).await {
        Ok(name) => name,
        Err(err) => return Dispatch::Done(ensure_fail_response(index, err)),
    };
    let body_json = match serde_json::to_string(body) {
        Ok(json) => json,
        Err(err) => {
            return Dispatch::Done(
                (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "type": "parsing_exception",
                            "reason": format!("update body could not be forwarded: {err}")
                        },
                        "status": 400
                    })),
                )
                    .into_response(),
            );
        }
    };
    let params_json = serde_json::to_string(params).unwrap_or_else(|_| "{}".to_string());
    if state.engine.owns_shard(&concrete, id) {
        let result = local_update(state, index, id, &body_json, &params_json).await;
        return Dispatch::Done(http_result(result));
    }
    let Some(owner) = state.engine.route_write(&concrete, id) else {
        return Dispatch::Local;
    };
    let op = ShardOp::UpdateDoc {
        index: index.to_string(),
        id: id.to_string(),
        body_json,
        params_json,
    };
    Dispatch::Done(forward_retrying(state, &owner, op).await)
}

fn cluster_search_unsupported(feature: &str) -> Response {
    let reason = format!(
        "cluster search does not merge {feature} across shards yet; the request was not executed"
    );
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "type": "illegal_argument_exception",
                "reason": reason
            },
            "status": 400
        })),
    )
        .into_response()
}

/// `Some` when this search was answered by fan-out (including a refusal).
/// `None` when the caller should run the ordinary local search.
pub(crate) async fn fanout_search(
    state: &AppState,
    index: &str,
    params: &EsSearchQueryParams,
    principal: &crate::auth::Principal,
    body: &EsSearchJson,
) -> Option<Response> {
    if !state.engine.has_cluster() {
        return None;
    }
    if index.contains(',') || index.contains('*') || index == "_all" {
        return None;
    }
    let targets = state.engine.shard_search_targets(index);
    let me = state.engine.routing_node_id();
    if targets.is_empty() || (targets.len() == 1 && targets[0] == me) {
        return None;
    }
    let parsed = body.0.clone().unwrap_or_default();
    if parsed.aggs.is_some() || parsed.aggregations.is_some() {
        return Some(cluster_search_unsupported("aggregations"));
    }
    if parsed.suggest.is_some() {
        return Some(cluster_search_unsupported("suggest"));
    }
    if parsed.collapse.is_some() {
        return Some(cluster_search_unsupported("collapse"));
    }
    if parsed.rescore.is_some() {
        return Some(cluster_search_unsupported("rescore"));
    }
    if parsed.profile {
        return Some(cluster_search_unsupported("profile"));
    }
    if parsed.search_after.is_some() {
        return Some(cluster_search_unsupported("search_after"));
    }
    if params.scroll.is_some() {
        return Some(cluster_search_unsupported("scroll"));
    }

    let from = parsed.from;
    let size = parsed.size;
    let window = from.saturating_add(size);
    if window > MAX_FANOUT_WINDOW {
        return Some(cluster_search_unsupported("a from+size window above 10000"));
    }
    let mut shard_body = parsed;
    shard_body.from = 0;
    shard_body.size = window;
    let mut shard_params = params.clone();
    shard_params.from = Some("0".to_string());
    shard_params.size = Some(window.to_string());

    let started = Instant::now();
    let mut parts: Vec<Value> = Vec::with_capacity(targets.len());
    for target in &targets {
        let (status, value) = if target == &me {
            let response = Box::pin(search_shard_local(
                state.clone(),
                index.to_string(),
                shard_params.clone(),
                principal.clone(),
                shard_body.clone(),
            ))
            .await;
            match response_value(response).await {
                Ok(pair) => pair,
                Err(err) => {
                    return Some(shard_failure(target, &err));
                }
            }
        } else {
            let op = match (
                serde_json::to_string(&shard_body),
                serde_json::to_string(&shard_params),
            ) {
                (Ok(body_json), Ok(params_json)) => ShardOp::Search {
                    index: index.to_string(),
                    body_json,
                    params_json,
                },
                (Err(err), _) | (_, Err(err)) => {
                    return Some(shard_failure(target, &err.to_string()));
                }
            };
            match state.engine.forward_shard(target, op).await {
                Ok(result) => {
                    let value = serde_json::from_str(&result.body).unwrap_or(Value::Null);
                    (result.status, value)
                }
                Err(err) => match replica_search_for_primary(
                    state,
                    index,
                    target,
                    &shard_body,
                    &shard_params,
                    principal,
                )
                .await
                {
                    Some(value) => (200, value),
                    None => return Some(engine_error_response(err)),
                },
            }
        };
        if !(200..300).contains(&status) {
            return Some(
                (
                    StatusCode::from_u16(status).unwrap_or(StatusCode::BAD_GATEWAY),
                    Json(value),
                )
                    .into_response(),
            );
        }
        parts.push(value);
    }

    let took_ms = started.elapsed().as_millis() as u64;
    let as_int = matches!(
        params.rest_total_hits_as_int.as_deref(),
        Some("true") | Some("1")
    );
    let merged = merge_hits(&parts, from, size, as_int, took_ms);
    Some(Json(merged).into_response())
}

fn shard_failure(target: &str, err: &str) -> Response {
    (
        StatusCode::SERVICE_UNAVAILABLE,
        Json(json!({
            "error": {
                "type": "shard_not_ready",
                "reason": format!("search on shard owner [{target}] failed: {err}")
            },
            "status": 503
        })),
    )
        .into_response()
}

async fn response_value(response: Response) -> Result<(u16, Value), String> {
    let status = response.status().as_u16();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .map_err(|err| err.to_string())?;
    let value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    Ok((status, value))
}

fn merge_hits(
    parts: &[Value],
    from: usize,
    size: usize,
    total_as_int: bool,
    took_ms: u64,
) -> Value {
    let mut hits: Vec<Value> = Vec::new();
    let mut total: u64 = 0;
    let mut relation = "eq";
    let mut max_score: Option<f64> = None;
    let mut timed_out = false;
    for part in parts {
        if part.get("timed_out").and_then(Value::as_bool) == Some(true) {
            timed_out = true;
        }
        match part.pointer("/hits/total") {
            Some(Value::Number(n)) => total = total.saturating_add(n.as_u64().unwrap_or(0)),
            Some(Value::Object(_)) => {
                total = total.saturating_add(
                    part.pointer("/hits/total/value")
                        .and_then(Value::as_u64)
                        .unwrap_or(0),
                );
                if part.pointer("/hits/total/relation").and_then(Value::as_str) == Some("gte") {
                    relation = "gte";
                }
            }
            _ => {}
        }
        if let Some(score) = part.pointer("/hits/max_score").and_then(Value::as_f64) {
            max_score = Some(max_score.map(|current| current.max(score)).unwrap_or(score));
        }
        if let Some(arr) = part.pointer("/hits/hits").and_then(Value::as_array) {
            hits.extend(arr.iter().cloned());
        }
    }
    hits.sort_by(|left, right| {
        let left_score = left.get("_score").and_then(Value::as_f64).unwrap_or(0.0);
        let right_score = right.get("_score").and_then(Value::as_f64).unwrap_or(0.0);
        right_score
            .partial_cmp(&left_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| {
                left.get("_id")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .cmp(right.get("_id").and_then(Value::as_str).unwrap_or(""))
            })
    });
    if size == 0 {
        hits.clear();
    } else {
        hits = hits.into_iter().skip(from).take(size).collect();
    }
    let total_value = if total_as_int {
        json!(total)
    } else {
        json!({ "value": total, "relation": relation })
    };
    json!({
        "took": took_ms,
        "timed_out": timed_out,
        "_shards": {
            "total": parts.len(),
            "successful": parts.len(),
            "skipped": 0,
            "failed": 0
        },
        "hits": {
            "total": total_value,
            "max_score": max_score,
            "hits": hits
        }
    })
}

/// Handler installed on the cluster handle. Runs the operation locally.
pub struct ApiShardHandler {
    state: AppState,
}

impl ApiShardHandler {
    pub fn new(state: AppState) -> Self {
        ApiShardHandler { state }
    }
}

#[async_trait::async_trait]
impl xerj_cluster::ShardHandler for ApiShardHandler {
    async fn handle(&self, op: ShardOp) -> ShardResult {
        match op {
            ShardOp::IndexDoc {
                index,
                id,
                source_json,
                op,
                if_seq_no,
                if_primary_term,
                version,
                version_type,
                replica,
                shard,
            } => {
                local_index(
                    &self.state,
                    &index,
                    &id,
                    &source_json,
                    &op,
                    if_seq_no,
                    if_primary_term,
                    version,
                    version_type.as_deref(),
                    replica,
                    shard,
                )
                .await
            }
            ShardOp::GetDoc {
                index,
                id,
                source,
                source_includes,
                source_excludes,
                replica,
                shard,
            } => {
                local_get(
                    &self.state,
                    &index,
                    &id,
                    source,
                    source_includes,
                    source_excludes,
                    replica,
                    shard,
                )
                .await
            }
            ShardOp::DeleteDoc {
                index,
                id,
                if_seq_no,
                if_primary_term,
                replica,
                shard,
            } => {
                local_delete(
                    &self.state,
                    &index,
                    &id,
                    if_seq_no,
                    if_primary_term,
                    replica,
                    shard,
                )
                .await
            }
            ShardOp::UpdateDoc {
                index,
                id,
                body_json,
                params_json,
            } => {
                let concrete = concrete_index_name(&self.state.engine, &index);
                if self.state.engine.get_index(&concrete).is_err() {
                    return ShardResult::http(503, shard_not_ready_body(&index));
                }
                if !self.state.engine.owns_shard(&concrete, &id) {
                    if let Some(owner) = self.state.engine.route_write(&concrete, &id) {
                        return not_this_primary(&index, &owner);
                    }
                }
                local_update(&self.state, &index, &id, &body_json, &params_json).await
            }
            ShardOp::Bulk {
                body,
                default_index,
                require_alias,
                default_pipeline,
                default_source_req_json,
            } => {
                handle_bulk(
                    &self.state,
                    &body,
                    default_index.as_deref(),
                    require_alias,
                    default_pipeline,
                    default_source_req_json,
                )
                .await
            }
            ShardOp::UpdateByQuery {
                index,
                query_json,
                script_source,
                script_params_json,
                pipeline,
                max_docs,
                scroll_size,
                check_only,
            } => {
                handle_update_by_query(
                    &self.state,
                    &index,
                    &query_json,
                    script_source,
                    script_params_json,
                    pipeline,
                    max_docs,
                    scroll_size,
                    check_only,
                )
                .await
            }
            ShardOp::DeleteByQuery {
                index,
                query_json,
                max_docs,
                scroll_size,
                check_only,
            } => {
                handle_delete_by_query(
                    &self.state,
                    &index,
                    &query_json,
                    max_docs,
                    scroll_size,
                    check_only,
                )
                .await
            }
            ShardOp::Search {
                index,
                body_json,
                params_json,
            } => local_search(&self.state, &index, &body_json, &params_json).await,
            ShardOp::BackfillReplica {
                index,
                shard,
                replica_id,
            } => backfill_replica(&self.state, &index, shard, &replica_id).await,
            ShardOp::RetainReplicaDocs { index, shard, ids } => {
                retain_replica_docs(&self.state, &index, shard, &ids).await
            }
        }
    }
}

async fn response_to_result(response: Response) -> ShardResult {
    let status = response.status().as_u16();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap_or_default();
    let body = String::from_utf8(bytes.to_vec()).unwrap_or_else(|_| "{}".to_string());
    ShardResult::http(status, body)
}

#[allow(clippy::too_many_arguments)]
async fn local_index(
    state: &AppState,
    index: &str,
    id: &str,
    source_json: &str,
    op: &str,
    if_seq_no: Option<u64>,
    if_primary_term: Option<u64>,
    version: Option<u64>,
    version_type: Option<&str>,
    replica: bool,
    shard: u32,
) -> ShardResult {
    let store = match doc_store(index, replica, shard) {
        Ok(store) => store,
        Err(result) => return result,
    };
    if open_store(state, &store).await.is_err() {
        return ShardResult::http(503, shard_not_ready_body(index));
    }
    let doc: Value = match serde_json::from_str(source_json) {
        Ok(doc) => doc,
        Err(err) => {
            return ShardResult::http(
                400,
                json!({
                    "error": {
                        "type": "document_parsing_exception",
                        "reason": format!("forwarded document is not JSON: {err}")
                    },
                    "status": 400
                })
                .to_string(),
            );
        }
    };
    let idx = match open_store(state, &store).await {
        Ok(idx) => idx,
        Err(_) => return ShardResult::http(503, shard_not_ready_body(index)),
    };
    let result = if op == "create" {
        idx.create_document(id.to_string(), doc).await
    } else if let (Some(version), Some(version_type)) = (version, version_type) {
        if version_type == "external" || version_type == "external_gte" {
            idx.index_document_external(Some(id.to_string()), doc, version, version_type)
                .await
        } else {
            idx.index_document_with_version(Some(id.to_string()), doc, if_seq_no, if_primary_term)
                .await
        }
    } else {
        idx.index_document_with_version(Some(id.to_string()), doc, if_seq_no, if_primary_term)
            .await
    };
    match result {
        Ok(resp) => {
            state.metrics.record_doc_indexed(index);
            let wire_seq = resp.seq_no.saturating_sub(1);
            let (body, status) = if resp.result == "updated" {
                (
                    EsDocResponse::updated(index, &resp.id, resp.version, wire_seq),
                    200,
                )
            } else {
                (
                    EsDocResponse::created(index, &resp.id, resp.version, wire_seq),
                    201,
                )
            };
            let result = ShardResult::http(
                status,
                serde_json::to_string(&body).unwrap_or_else(|_| "{}".into()),
            );
            if replica {
                return result;
            }
            if let Err(nack) = replicate_write(
                state,
                index,
                id,
                ShardOp::IndexDoc {
                    index: index.to_string(),
                    id: id.to_string(),
                    source_json: source_json.to_string(),
                    op: op.to_string(),
                    if_seq_no,
                    if_primary_term,
                    version,
                    version_type: version_type.map(str::to_string),
                    replica: false,
                    shard: 0,
                },
            )
            .await
            {
                return nack;
            }
            result
        }
        Err(err) => response_to_result(engine_error_response(err)).await,
    }
}

#[allow(clippy::too_many_arguments)]
async fn local_get(
    state: &AppState,
    index: &str,
    id: &str,
    source: Option<String>,
    source_includes: Option<String>,
    source_excludes: Option<String>,
    replica: bool,
    shard: u32,
) -> ShardResult {
    if !replica && state.engine.closed_indices.contains_key(index) {
        return response_to_result(crate::es_compat::closed_index_error(index)).await;
    }
    let store = match doc_store(index, replica, shard) {
        Ok(store) => store,
        Err(result) => return result,
    };
    let idx = match open_store(state, &store).await {
        Ok(idx) => idx,
        Err(_) => return ShardResult::http(503, shard_not_ready_body(index)),
    };
    match idx.get_document(id).await {
        Ok(Some(mut doc)) => {
            xerj_query::executor::strip_internal_passage_metadata(&mut doc);
            let params = GetDocParams {
                source,
                source_includes,
                source_excludes,
            };
            let filtered = apply_get_doc_source_filter(doc, &params);
            let version = idx.lookup_version(id).unwrap_or(1);
            let seq_no = idx.lookup_seq_no(id).unwrap_or(0);
            let resp = EsGetResponse::found(index, id, version, seq_no, filtered);
            ShardResult::http(
                200,
                serde_json::to_string(&resp).unwrap_or_else(|_| "{}".into()),
            )
        }
        Ok(None) => {
            let resp = EsGetResponse::not_found(index, id);
            ShardResult::http(
                404,
                serde_json::to_string(&resp).unwrap_or_else(|_| "{}".into()),
            )
        }
        Err(err) => response_to_result(engine_error_response(err)).await,
    }
}

#[allow(clippy::too_many_arguments)]
async fn local_delete(
    state: &AppState,
    index: &str,
    id: &str,
    if_seq_no: Option<u64>,
    if_primary_term: Option<u64>,
    replica: bool,
    shard: u32,
) -> ShardResult {
    let store = match doc_store(index, replica, shard) {
        Ok(store) => store,
        Err(result) => return result,
    };
    let idx = match open_store(state, &store).await {
        Ok(idx) => idx,
        Err(_) => return ShardResult::http(503, shard_not_ready_body(index)),
    };
    match idx
        .delete_document_versioned(id, if_seq_no, if_primary_term)
        .await
    {
        Ok(outcome) if outcome.found => {
            let resp = EsDeleteDocResponse::deleted(
                index,
                id,
                outcome.version,
                outcome.seq_no.saturating_sub(1),
            );
            finish_delete(state, index, id, replica, 200, &resp).await
        }
        Ok(outcome) => {
            let resp = EsDeleteDocResponse::not_found(
                index,
                id,
                outcome.version,
                outcome.seq_no.saturating_sub(1),
            );
            finish_delete(state, index, id, replica, 404, &resp).await
        }
        Err(err) => response_to_result(engine_error_response(err)).await,
    }
}

async fn finish_delete(
    state: &AppState,
    index: &str,
    id: &str,
    replica: bool,
    status: u16,
    resp: &EsDeleteDocResponse,
) -> ShardResult {
    if !replica {
        if let Err(nack) = replicate_write(
            state,
            index,
            id,
            ShardOp::DeleteDoc {
                index: index.to_string(),
                id: id.to_string(),
                if_seq_no: None,
                if_primary_term: None,
                replica: false,
                shard: 0,
            },
        )
        .await
        {
            return nack;
        }
    }
    ShardResult::http(
        status,
        serde_json::to_string(resp).unwrap_or_else(|_| "{}".into()),
    )
}

/// Replica stores are cluster-internal. A caller's index ACL must not hide
/// them. A failover search of a replica that lives on this node runs on the
/// caller's task, and that task's visibility guard would otherwise 404 the
/// copy. The in-process shard thread has no request guard (it stands in for
/// a TCP handler); this still covers the local path.
struct OpenReplicaStore(String);

impl xerj_engine::index_guard::IndexVisibility for OpenReplicaStore {
    fn visible(&self, index: &str) -> bool {
        index == self.0
    }
}

async fn open_store(
    state: &AppState,
    name: &str,
) -> Result<Arc<xerj_engine::Index>, xerj_engine::EngineError> {
    if name.starts_with(".xerj_replica_") {
        let engine = Arc::clone(&state.engine);
        let owned = name.to_string();
        let guard = Arc::new(OpenReplicaStore(owned.clone()));
        return xerj_engine::index_guard::scoped(guard, async move { engine.get_index(&owned) })
            .await;
    }
    state.engine.get_index(name)
}

fn doc_store(index: &str, replica: bool, shard: u32) -> Result<String, ShardResult> {
    if !replica {
        return Ok(index.to_string());
    }
    xerj_cluster::replica_index_name(index, shard).ok_or_else(|| {
        ShardResult::http(
            400,
            json!({
                "error": {
                    "type": "invalid_index_name_exception",
                    "reason": format!("replica store name for [{index}] shard {shard} is not valid")
                },
                "status": 400
            })
            .to_string(),
        )
    })
}

fn quorum_nack(index: &str, needed: usize, got: usize, detail: &str) -> ShardResult {
    ShardResult::http(
        503,
        json!({
            "error": {
                "type": "replica_not_acknowledged",
                "reason": format!(
                    "primary applied the write on [{index}] but only {got} of {needed} replica acknowledgements are in sync: {detail}. The primary has the write; retry the index so an in-sync replica can take the copy"
                )
            },
            "status": 503
        })
        .to_string(),
    )
}

fn replica_nack(index: &str, replica: &str, detail: &str) -> ShardResult {
    ShardResult::http(
        503,
        json!({
            "error": {
                "type": "replica_not_acknowledged",
                "reason": format!(
                    "primary applied the write on [{index}] but replica [{replica}] did not acknowledge it: {detail}. The primary has the write; retry the index so the copy can catch up"
                )
            },
            "status": 503
        })
        .to_string(),
    )
}

/// Copy `op` onto the in-sync replicas and wait for a quorum.
///
/// The quorum is a majority of the copies placed at create (the primary,
/// which already has the write, plus [`xerj_cluster::replica_quorum_acks`]
/// replica confirmations). An empty placement returns immediately. The copy
/// is an upsert or a delete without the caller's sequence check: the
/// replica's own sequence numbers are not the primary's.
///
/// Every in-sync replica is asked. When enough confirm and some do not, the
/// ones that confirmed are published through the Raft log before the caller
/// is acknowledged, and later reads skip the rest until
/// [`backfill_replica`] copies the primary's live documents and publishes
/// the replica again. Two writes of the same shard do not publish different
/// sets; the primary holds `replica_sync_lock` across the copy and the
/// publish. Backfill takes that same lock.
async fn replicate_write(
    state: &AppState,
    index: &str,
    id: &str,
    op: ShardOp,
) -> Result<(), ShardResult> {
    let Some((shard, _)) = state.engine.primary_of(index, id) else {
        return Ok(());
    };
    let sync = state.engine.replica_sync_lock(index, shard);
    let _sync = sync.lock().await;
    let placed = state.engine.placed_replica_nodes(index, shard);
    if placed.is_empty() {
        return Ok(());
    }
    let targets = state.engine.replica_nodes(index, shard);
    let needed = xerj_cluster::replica_quorum_acks(placed.len());
    if targets.len() < needed {
        return Err(quorum_nack(
            index,
            needed,
            targets.len(),
            "fewer replicas are in sync than the quorum requires",
        ));
    }
    let op = replica_copy(op, shard);
    let mut acked: Vec<String> = Vec::new();
    let mut failed: Option<(String, String)> = None;
    for replica in &targets {
        match confirm_replica(state, replica, &op).await {
            Ok(()) => acked.push(replica.clone()),
            Err(detail) => {
                if failed.is_none() {
                    failed = Some((replica.clone(), detail));
                }
            }
        }
    }
    if acked.len() < needed {
        let (replica, detail) = failed.unwrap_or_else(|| {
            (
                "none".to_string(),
                "no in-sync replica acknowledged the write".to_string(),
            )
        });
        return Err(replica_nack(index, &replica, &detail));
    }
    if acked.len() == targets.len() {
        return Ok(());
    }
    acked.sort();
    acked.dedup();
    let Some(handle) = state.engine.cluster_handle() else {
        return Err(quorum_nack(
            index,
            needed,
            acked.len(),
            "no cluster handle to publish the in-sync set",
        ));
    };
    match handle
        .propose(ClusterCommand::SetShardInSync {
            index: index.to_string(),
            shard,
            nodes: acked.clone(),
        })
        .await
    {
        Ok(ApplyEffect::Applied) => {
            let published = state.engine.replica_nodes(index, shard);
            if acked.iter().all(|id| published.iter().any(|got| got == id)) {
                Ok(())
            } else {
                Err(quorum_nack(
                    index,
                    needed,
                    acked.len(),
                    "the in-sync set committed without the replicas that confirmed this write",
                ))
            }
        }
        Ok(other) => Err(quorum_nack(
            index,
            needed,
            acked.len(),
            &format!("in-sync update applied as {other:?}"),
        )),
        Err(err) => Err(quorum_nack(index, needed, acked.len(), &err.to_string())),
    }
}

async fn confirm_replica(state: &AppState, replica: &str, op: &ShardOp) -> Result<(), String> {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match state.engine.forward_shard(replica, op.clone()).await {
            Ok(result) if is_shard_not_ready(&result) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            Ok(result) if replica_confirmed(op, &result) => return Ok(()),
            Ok(result) => return Err(result.body),
            Err(err) => return Err(err.to_string()),
        }
    }
}

fn replica_copy(op: ShardOp, shard: u32) -> ShardOp {
    match op {
        ShardOp::IndexDoc {
            index,
            id,
            source_json,
            ..
        } => ShardOp::IndexDoc {
            index,
            id,
            source_json,
            op: "index".to_string(),
            if_seq_no: None,
            if_primary_term: None,
            version: None,
            version_type: None,
            replica: true,
            shard,
        },
        ShardOp::DeleteDoc { index, id, .. } => ShardOp::DeleteDoc {
            index,
            id,
            if_seq_no: None,
            if_primary_term: None,
            replica: true,
            shard,
        },
        other => other,
    }
}

fn replica_confirmed(op: &ShardOp, result: &ShardResult) -> bool {
    match op {
        // A delete of a copy that is already gone is still in sync.
        ShardOp::DeleteDoc { .. } => result.status == 200 || result.status == 404,
        _ => (200..300).contains(&result.status),
    }
}

fn backfill_body(status: u16, type_name: &str, reason: impl Into<String>) -> ShardResult {
    let reason = reason.into();
    ShardResult::http(
        status,
        json!({
            "error": { "type": type_name, "reason": reason },
            "status": status
        })
        .to_string(),
    )
}

fn already_in_sync() -> ShardResult {
    ShardResult::http(
        200,
        json!({ "already_in_sync": true, "copied": 0 }).to_string(),
    )
}

/// Live documents on this primary for `shard`.
///
/// The user index on the primary holds the documents it owns. Ids that
/// route elsewhere are skipped. A tombstone is not in the list. `Err` is
/// the reason the copy must not publish an in-sync set.
async fn primary_live_docs(
    state: &AppState,
    index: &str,
    shard: u32,
) -> Result<Vec<(String, Value)>, String> {
    let idx = state
        .engine
        .get_index(index)
        .map_err(|err| format!("primary index [{index}] is not open: {err}"))?;
    let mut docs = Vec::new();
    for id in idx.live_document_ids() {
        let Some((doc_shard, _)) = state.engine.primary_of(index, &id) else {
            continue;
        };
        if doc_shard != shard {
            continue;
        }
        match idx.get_document(&id).await {
            Ok(Some(source)) => docs.push((id, source)),
            Ok(None) => {}
            Err(err) => return Err(format!("reading [{index}] document [{id}]: {err}")),
        }
    }
    Ok(docs)
}

/// Copy this primary's live documents onto `replica_id` and publish it.
///
/// The replica lock is held from the snapshot through the in-sync publish.
/// A document write applies on the primary first and then waits for this
/// lock before it copies, so a write that missed the snapshot is replicated
/// to the set that includes `replica_id`. A failed copy leaves the in-sync
/// set unchanged. The replica retries.
async fn backfill_replica(
    state: &AppState,
    index: &str,
    shard: u32,
    replica_id: &str,
) -> ShardResult {
    if replica_id.is_empty() {
        return backfill_body(400, "illegal_argument_exception", "replica id is empty");
    }
    let me = state.engine.routing_node_id();
    if replica_id == me {
        return backfill_body(
            400,
            "illegal_argument_exception",
            "a primary does not backfill itself",
        );
    }
    let Some(owner) = state.engine.shard_primary(index, shard) else {
        return backfill_body(
            409,
            "shard_not_ready",
            format!("[{index}] shard {shard} has no primary on this node"),
        );
    };
    if owner != me {
        return backfill_body(
            409,
            "shard_not_primary",
            format!("[{index}] shard {shard} is owned by [{owner}], not [{me}]"),
        );
    }
    let placed = state.engine.placed_replica_nodes(index, shard);
    if !placed.iter().any(|id| id == replica_id) {
        return backfill_body(
            400,
            "illegal_argument_exception",
            format!("[{replica_id}] is not a replica of [{index}] shard {shard}"),
        );
    }
    if state
        .engine
        .replica_nodes(index, shard)
        .iter()
        .any(|id| id == replica_id)
    {
        return already_in_sync();
    }

    let sync = state.engine.replica_sync_lock(index, shard);
    let _guard = sync.lock().await;
    if state
        .engine
        .replica_nodes(index, shard)
        .iter()
        .any(|id| id == replica_id)
    {
        return already_in_sync();
    }

    let docs = match primary_live_docs(state, index, shard).await {
        Ok(docs) => docs,
        Err(reason) => return backfill_body(503, "replica_backfill_failed", reason),
    };
    for (id, source) in &docs {
        let source_json = match serde_json::to_string(source) {
            Ok(json) => json,
            Err(err) => {
                return backfill_body(
                    503,
                    "replica_backfill_failed",
                    format!("document [{id}] is not JSON: {err}"),
                );
            }
        };
        let op = ShardOp::IndexDoc {
            index: index.to_string(),
            id: id.clone(),
            source_json,
            op: "index".to_string(),
            if_seq_no: None,
            if_primary_term: None,
            version: None,
            version_type: None,
            replica: true,
            shard,
        };
        if let Err(detail) = confirm_replica(state, replica_id, &op).await {
            return backfill_body(
                503,
                "replica_backfill_failed",
                format!("replica [{replica_id}] did not take document [{id}]: {detail}"),
            );
        }
    }
    let ids: Vec<String> = docs.iter().map(|(id, _)| id.clone()).collect();
    let retain = ShardOp::RetainReplicaDocs {
        index: index.to_string(),
        shard,
        ids,
    };
    if let Err(detail) = confirm_replica(state, replica_id, &retain).await {
        return backfill_body(
            503,
            "replica_backfill_failed",
            format!(
                "replica [{replica_id}] did not drop documents the primary no longer has: {detail}"
            ),
        );
    }

    let mut nodes = state.engine.replica_nodes(index, shard);
    if !nodes.iter().any(|id| id == replica_id) {
        nodes.push(replica_id.to_string());
    }
    nodes.sort();
    nodes.dedup();
    let Some(handle) = state.engine.cluster_handle() else {
        return backfill_body(
            503,
            "replica_backfill_failed",
            "no cluster handle to publish the in-sync set",
        );
    };
    let copied = docs.len();
    match handle
        .propose(ClusterCommand::SetShardInSync {
            index: index.to_string(),
            shard,
            nodes,
        })
        .await
    {
        Ok(ApplyEffect::Applied) => {
            let published = state.engine.replica_nodes(index, shard);
            if !published.iter().any(|id| id == replica_id) {
                return backfill_body(
                    503,
                    "replica_backfill_failed",
                    "the in-sync set committed without the replica that was filled",
                );
            }
            tracing::info!(
                index = %index,
                shard,
                replica = %replica_id,
                copied,
                "copied primary documents onto a replica and published the in-sync set"
            );
            ShardResult::http(
                200,
                json!({ "already_in_sync": false, "copied": copied }).to_string(),
            )
        }
        Ok(other) => backfill_body(
            503,
            "replica_backfill_failed",
            format!("in-sync update applied as {other:?}"),
        ),
        Err(err) => backfill_body(503, "replica_backfill_failed", err.to_string()),
    }
}

/// Drop replica-store documents that are not in `ids`.
async fn retain_replica_docs(
    state: &AppState,
    index: &str,
    shard: u32,
    ids: &[String],
) -> ShardResult {
    let store = match doc_store(index, true, shard) {
        Ok(store) => store,
        Err(result) => return result,
    };
    let idx = match open_store(state, &store).await {
        Ok(idx) => idx,
        Err(_) => return ShardResult::http(503, shard_not_ready_body(index)),
    };
    let keep: HashSet<&str> = ids.iter().map(String::as_str).collect();
    for id in idx.live_document_ids() {
        if keep.contains(id.as_str()) {
            continue;
        }
        if let Err(err) = idx.delete_document(&id).await {
            return backfill_body(
                503,
                "replica_backfill_failed",
                format!("dropping [{id}] from [{store}]: {err}"),
            );
        }
    }
    ShardResult::http(200, json!({ "retained": ids.len() }).to_string())
}

/// Search the shards `primary` owns by reading one replica copy of each.
///
/// `None` when this index has no replica for that primary, or none of them
/// answered. The caller then fails the search the way it did before replicas
/// existed.
async fn replica_search_for_primary(
    state: &AppState,
    index: &str,
    primary: &str,
    body: &EsSearchBody,
    params: &EsSearchQueryParams,
    principal: &crate::auth::Principal,
) -> Option<Value> {
    let shards = state.engine.shards_owned_by(index, primary);
    if shards.is_empty() {
        return None;
    }
    let window = body.size;
    let mut parts = Vec::with_capacity(shards.len());
    for shard in shards {
        let store = xerj_cluster::replica_index_name(index, shard)?;
        let mut found = None;
        for replica in state.engine.replica_nodes(index, shard) {
            if let Some(mut value) =
                search_replica(state, &replica, &store, body, params, principal).await
            {
                rewrite_hit_index(&mut value, &store, index);
                found = Some(value);
                break;
            }
        }
        parts.push(found?);
    }
    Some(merge_hits(&parts, 0, window, false, 0))
}

async fn search_replica(
    state: &AppState,
    replica: &str,
    store: &str,
    body: &EsSearchBody,
    params: &EsSearchQueryParams,
    principal: &crate::auth::Principal,
) -> Option<Value> {
    if replica == state.engine.routing_node_id() {
        let engine_store = store.to_string();
        let guard = Arc::new(OpenReplicaStore(engine_store.clone()));
        let response = xerj_engine::index_guard::scoped(guard, async move {
            search_shard_local(
                state.clone(),
                engine_store,
                params.clone(),
                principal.clone(),
                body.clone(),
            )
            .await
        })
        .await;
        let (status, value) = response_value(response).await.ok()?;
        return (200..300).contains(&status).then_some(value);
    }
    let op = match (serde_json::to_string(body), serde_json::to_string(params)) {
        (Ok(body_json), Ok(params_json)) => ShardOp::Search {
            index: store.to_string(),
            body_json,
            params_json,
        },
        _ => return None,
    };
    match state.engine.forward_shard(replica, op).await {
        Ok(result) if (200..300).contains(&result.status) => {
            serde_json::from_str(&result.body).ok()
        }
        _ => None,
    }
}

fn rewrite_hit_index(value: &mut Value, from: &str, to: &str) {
    let Some(hits) = value
        .pointer_mut("/hits/hits")
        .and_then(Value::as_array_mut)
    else {
        return;
    };
    for hit in hits {
        if hit.get("_index").and_then(Value::as_str) == Some(from) {
            hit["_index"] = json!(to);
        }
    }
}

async fn local_search(
    state: &AppState,
    index: &str,
    body_json: &str,
    params_json: &str,
) -> ShardResult {
    let params: EsSearchQueryParams = serde_json::from_str(params_json).unwrap_or_default();
    let body: EsSearchBody = match serde_json::from_str(body_json) {
        Ok(body) => body,
        Err(err) => {
            return ShardResult::http(
                400,
                json!({
                    "error": {
                        "type": "parsing_exception",
                        "reason": format!("forwarded search body is not JSON: {err}")
                    },
                    "status": 400
                })
                .to_string(),
            );
        }
    };
    // The accepting node already passed its auth middleware. This RPC is the
    // cluster transport, not a second client. The local shard of the
    // coordinator still runs under the caller's principal.
    let response = if index.starts_with(".xerj_replica_") {
        let guard = Arc::new(OpenReplicaStore(index.to_string()));
        xerj_engine::index_guard::scoped(guard, async move {
            search_shard_local(
                state.clone(),
                index.to_string(),
                params,
                crate::auth::Principal::Superuser,
                body,
            )
            .await
        })
        .await
    } else {
        Box::pin(search_shard_local(
            state.clone(),
            index.to_string(),
            params,
            crate::auth::Principal::Superuser,
            body,
        ))
        .await
    };
    response_to_result(response).await
}

// ── `_update` and `_bulk` on the primary ────────────────────────────────────

/// Backing index when `name` is an alias, otherwise `name`.
///
/// `Engine::get_index` writes an alias through its first backing index. Routing
/// has to use that same name, or the shard plan (which lives on the concrete
/// index) is invisible and the write stays on the node that received it.
fn concrete_index_name(engine: &xerj_engine::Engine, name: &str) -> String {
    engine
        .aliases
        .get(name)
        .and_then(|names| names.first().cloned())
        .filter(|backing| !backing.is_empty())
        .unwrap_or_else(|| name.to_string())
}

enum EnsureFail {
    Engine(xerj_engine::EngineError),
    Unavailable(String),
}

fn ensure_fail_response(index: &str, err: EnsureFail) -> Response {
    match err {
        EnsureFail::Engine(err) => engine_error_response(err),
        EnsureFail::Unavailable(reason) => (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({
                "error": {
                    "type": "shard_not_ready",
                    "reason": format!("index [{index}] is not on this shard yet: {reason}")
                },
                "status": 503
            })),
        )
            .into_response(),
    }
}

fn ensure_fail_status(err: EnsureFail) -> (u16, String) {
    match err {
        EnsureFail::Engine(err) => {
            let common = xerj_common::XerjError::from(err);
            let status = common.http_status();
            (status, common.to_string())
        }
        EnsureFail::Unavailable(reason) => (503, reason),
    }
}

async fn wait_index_open(state: &AppState, name: &str) -> bool {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        if state.engine.get_index(name).is_ok() {
            return true;
        }
        if Instant::now() >= deadline {
            return false;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
}

/// Open `name`, creating it through the Raft log when it is not an alias and
/// this node does not have it yet. Does not write a document.
async fn ensure_concrete_index(state: &AppState, name: &str) -> Result<String, EnsureFail> {
    let concrete = concrete_index_name(&state.engine, name);
    if concrete != name {
        if state.engine.get_index(&concrete).is_err() {
            return Err(EnsureFail::Unavailable(format!(
                "alias [{name}] does not point at an open index"
            )));
        }
        return Ok(concrete);
    }
    if state.engine.get_index(&concrete).is_err() {
        state
            .engine
            .ensure_replicated_index(&concrete)
            .await
            .map_err(EnsureFail::Engine)?;
    }
    if !wait_index_open(state, &concrete).await {
        return Err(EnsureFail::Unavailable(format!(
            "index [{concrete}] was not open after the create committed"
        )));
    }
    Ok(concrete)
}

fn not_this_primary(index: &str, owner: &str) -> ShardResult {
    ShardResult::http(
        409,
        json!({
            "error": {
                "type": "shard_not_primary",
                "reason": format!("[{index}] is owned by [{owner}], not this node")
            },
            "status": 409
        })
        .to_string(),
    )
}

async fn local_update(
    state: &AppState,
    index: &str,
    id: &str,
    body_json: &str,
    params_json: &str,
) -> ShardResult {
    let concrete = concrete_index_name(&state.engine, index);
    if state.engine.get_index(&concrete).is_err() {
        return ShardResult::http(503, shard_not_ready_body(index));
    }
    let body: EsUpdateBody = match serde_json::from_str(body_json) {
        Ok(body) => body,
        Err(err) => {
            return ShardResult::http(
                400,
                json!({
                    "error": {
                        "type": "parsing_exception",
                        "reason": format!("forwarded update body is not JSON: {err}")
                    },
                    "status": 400
                })
                .to_string(),
            );
        }
    };
    let params: UpdateDocParams = serde_json::from_str(params_json).unwrap_or_default();
    let applied = apply_local_update(state, index, id, body, &params).await;
    if !applied.replicate {
        return response_to_result(applied.response).await;
    }
    let copy = match state.engine.get_index(&concrete) {
        Ok(idx) => match idx.get_document(id).await {
            Ok(Some(doc)) => match serde_json::to_string(&doc) {
                Ok(source_json) => ShardOp::IndexDoc {
                    index: concrete.clone(),
                    id: id.to_string(),
                    source_json,
                    op: "index".to_string(),
                    if_seq_no: None,
                    if_primary_term: None,
                    version: None,
                    version_type: None,
                    replica: false,
                    shard: 0,
                },
                Err(err) => {
                    return ShardResult::http(
                        503,
                        json!({
                            "error": {
                                "type": "replica_not_acknowledged",
                                "reason": format!(
                                    "primary applied the update on [{index}] but document [{id}] could not be copied: {err}"
                                )
                            },
                            "status": 503
                        })
                        .to_string(),
                    );
                }
            },
            Ok(None) => ShardOp::DeleteDoc {
                index: concrete.clone(),
                id: id.to_string(),
                if_seq_no: None,
                if_primary_term: None,
                replica: false,
                shard: 0,
            },
            Err(err) => {
                return ShardResult::http(
                    503,
                    json!({
                        "error": {
                            "type": "replica_not_acknowledged",
                            "reason": format!(
                                "primary applied the update on [{index}] but document [{id}] could not be read for the replica copy: {err}"
                            )
                        },
                        "status": 503
                    })
                    .to_string(),
                );
            }
        },
        Err(err) => {
            return ShardResult::http(
                503,
                json!({
                    "error": {
                        "type": "replica_not_acknowledged",
                        "reason": format!(
                            "primary applied the update on [{index}] but [{concrete}] is not open for the replica copy: {err}"
                        )
                    },
                    "status": 503
                })
                .to_string(),
            );
        }
    };
    if let Err(nack) = replicate_write(state, &concrete, id, copy).await {
        return nack;
    }
    response_to_result(applied.response).await
}

/// One parsed bulk action, in request order.
struct BulkPiece {
    action: String,
    /// Name the caller used. The bulk pipeline reports this on the item.
    index: String,
    id: String,
    action_line: String,
    source_line: Option<String>,
    /// Set when this action is already an error and must not be written.
    preset: Option<xerj_engine::bulk::BulkItemResult>,
    concrete: String,
}

fn bulk_item_error(
    action: &str,
    index: &str,
    id: &str,
    status: u16,
    error: impl Into<String>,
) -> xerj_engine::bulk::BulkItemResult {
    xerj_engine::bulk::BulkItemResult {
        action: action.to_string(),
        index: index.to_string(),
        id: id.to_string(),
        status,
        result: None,
        error: Some(error.into()),
        get_source: None,
    }
}

/// Same pairing rule as the bulk engine: a delete action has no source line.
/// The two parsers have to agree, or a delete swallows the next action.
fn bulk_action_line_is_delete(line: &str) -> bool {
    let b = line.as_bytes();
    let mut p = 0usize;
    while p < b.len() && (b[p] == b' ' || b[p] == b'\t') {
        p += 1;
    }
    if p >= b.len() || b[p] != b'{' {
        return false;
    }
    p += 1;
    while p < b.len() && (b[p] == b' ' || b[p] == b'\t') {
        p += 1;
    }
    if p >= b.len() || b[p] != b'"' {
        return false;
    }
    p += 1;
    let start = p;
    while p < b.len() && b[p] != b'"' {
        p += 1;
    }
    p < b.len() && &b[start..p] == b"delete"
}

fn json_meta_id(meta: &Value) -> Option<String> {
    match meta.get("_id")? {
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        Value::Bool(b) => Some(b.to_string()),
        _ => None,
    }
}

fn split_bulk_pieces(body: &str, default_index: Option<&str>) -> Vec<BulkPiece> {
    let lines: Vec<&str> = body
        .lines()
        .filter(|line| !line.trim().is_empty())
        .collect();
    let mut pieces = Vec::new();
    let mut i = 0usize;
    while i < lines.len() {
        let raw_action = lines[i];
        let is_delete = bulk_action_line_is_delete(raw_action);
        let source_line = if !is_delete && i + 1 < lines.len() {
            let source = lines[i + 1];
            i += 2;
            Some(source.to_string())
        } else {
            i += 1;
            None
        };
        let action_val: Value = match serde_json::from_str(raw_action) {
            Ok(value) => value,
            Err(err) => {
                pieces.push(BulkPiece {
                    action: "unknown".to_string(),
                    index: default_index.unwrap_or("_unknown").to_string(),
                    id: String::new(),
                    action_line: String::new(),
                    source_line: None,
                    preset: Some(bulk_item_error(
                        "unknown",
                        default_index.unwrap_or("_unknown"),
                        "",
                        400,
                        format!("failed to parse action line: {err}"),
                    )),
                    concrete: String::new(),
                });
                continue;
            }
        };
        let (action, meta) = if let Some(meta) = action_val.get("index") {
            ("index", meta)
        } else if let Some(meta) = action_val.get("create") {
            ("create", meta)
        } else if let Some(meta) = action_val.get("update") {
            ("update", meta)
        } else if let Some(meta) = action_val.get("delete") {
            ("delete", meta)
        } else {
            pieces.push(BulkPiece {
                action: "unknown".to_string(),
                index: default_index.unwrap_or("_unknown").to_string(),
                id: String::new(),
                action_line: String::new(),
                source_line: None,
                preset: Some(bulk_item_error(
                    "unknown",
                    default_index.unwrap_or("_unknown"),
                    "",
                    400,
                    "unknown action type",
                )),
                concrete: String::new(),
            });
            continue;
        };
        let mut meta = if meta.is_object() {
            meta.clone()
        } else {
            json!({})
        };
        let index = meta
            .get("_index")
            .and_then(Value::as_str)
            .map(str::to_string)
            .or_else(|| default_index.map(str::to_string))
            .unwrap_or_else(|| "_unknown".to_string());
        if meta.get("_index").and_then(Value::as_str).is_none() {
            meta["_index"] = json!(index);
        }
        if let Some(id) = json_meta_id(&meta) {
            if id.is_empty() {
                pieces.push(BulkPiece {
                    action: action.to_string(),
                    index: index.clone(),
                    id: String::new(),
                    action_line: String::new(),
                    source_line: None,
                    preset: Some(bulk_item_error(
                        action,
                        &index,
                        "",
                        400,
                        "if _id is specified it must not be empty",
                    )),
                    concrete: String::new(),
                });
                continue;
            }
        }
        let id = match json_meta_id(&meta) {
            Some(id) => id,
            None if action == "index" || action == "create" => {
                let id = uuid::Uuid::new_v4().to_string();
                meta["_id"] = json!(id);
                id
            }
            None => {
                let reason = if action == "update" {
                    "update action requires _id"
                } else {
                    "delete action requires _id"
                };
                pieces.push(BulkPiece {
                    action: action.to_string(),
                    index: index.clone(),
                    id: String::new(),
                    action_line: String::new(),
                    source_line: None,
                    preset: Some(bulk_item_error(action, &index, "", 400, reason)),
                    concrete: String::new(),
                });
                continue;
            }
        };
        if action != "delete" && source_line.is_none() {
            pieces.push(BulkPiece {
                action: action.to_string(),
                index: index.clone(),
                id: id.clone(),
                action_line: String::new(),
                source_line: None,
                preset: Some(bulk_item_error(
                    action,
                    &index,
                    &id,
                    400,
                    "missing document body",
                )),
                concrete: String::new(),
            });
            continue;
        }
        let mut action_obj = serde_json::Map::new();
        action_obj.insert(action.to_string(), meta);
        let action_line = serde_json::to_string(&Value::Object(action_obj))
            .unwrap_or_else(|_| raw_action.to_string());
        pieces.push(BulkPiece {
            action: action.to_string(),
            index,
            id,
            action_line,
            source_line: if action == "delete" {
                None
            } else {
                source_line
            },
            preset: None,
            concrete: String::new(),
        });
    }
    pieces
}

fn group_ndjson(pieces: &[BulkPiece], which: &[usize]) -> String {
    let mut body = String::new();
    for &at in which {
        body.push_str(&pieces[at].action_line);
        body.push('\n');
        if let Some(source) = &pieces[at].source_line {
            body.push_str(source);
            body.push('\n');
        }
    }
    body
}

#[derive(serde::Serialize, serde::Deserialize)]
struct BulkWire {
    version: u64,
    seq_no: u64,
}

#[derive(serde::Serialize, serde::Deserialize)]
struct PrimaryBulkReply {
    took_ms: u64,
    errors: bool,
    items: Vec<xerj_engine::bulk::BulkItemResult>,
    wire: Vec<Option<BulkWire>>,
}

fn nack_reason(result: &ShardResult) -> String {
    serde_json::from_str::<Value>(&result.body)
        .ok()
        .and_then(|value| {
            value
                .pointer("/error/reason")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .unwrap_or_else(|| result.body.clone())
}

fn mark_bulk_nack(item: &mut xerj_engine::bulk::BulkItemResult, nack: &ShardResult) {
    item.status = nack.status;
    item.result = None;
    item.get_source = None;
    item.error = Some(nack_reason(nack));
}

fn wire_of(engine: &xerj_engine::Engine, index: &str, id: &str) -> Option<(u64, u64)> {
    let idx = engine.get_index(index).ok()?;
    Some((
        idx.lookup_version(id).unwrap_or(1),
        idx.lookup_seq_no(id).unwrap_or(0),
    ))
}

/// Run the local bulk pipeline, then copy each success onto the in-sync replicas.
///
/// A noop update is not copied: the source did not change. A failed item is
/// not copied. A copy that misses quorum replaces that item's success with
/// the same `replica_not_acknowledged` a single-document write returns. The
/// primary already has the write.
async fn replicate_bulk_result(
    state: &AppState,
    mut result: xerj_engine::bulk::BulkResult,
) -> (xerj_engine::bulk::BulkResult, Vec<Option<(u64, u64)>>) {
    let mut wire = Vec::with_capacity(result.items.len());
    // `item` borrows `result.items`, so the flag is applied after the loop.
    let mut copy_failed = false;
    for item in &mut result.items {
        let failed = item.error.is_some() || !(200..300).contains(&item.status);
        if failed || item.id.is_empty() {
            if !failed && item.id.is_empty() {
                item.status = 503;
                item.result = None;
                item.error = Some(
                    "bulk item was acknowledged without an id, so it was not copied".to_string(),
                );
                copy_failed = true;
            }
            wire.push(None);
            continue;
        }
        let concrete = concrete_index_name(&state.engine, &item.index);
        if item.action == "delete" {
            let index = concrete.clone();
            let id = item.id.clone();
            let op = ShardOp::DeleteDoc {
                index: index.clone(),
                id: id.clone(),
                if_seq_no: None,
                if_primary_term: None,
                replica: false,
                shard: 0,
            };
            if let Err(nack) = replicate_write(state, &index, &id, op).await {
                mark_bulk_nack(item, &nack);
                copy_failed = true;
            }
            wire.push(None);
            continue;
        }
        if item.result.as_deref() == Some("noop") {
            wire.push(wire_of(&state.engine, &concrete, &item.id));
            continue;
        }
        let op = match state.engine.get_index(&concrete) {
            Ok(idx) => match idx.get_document(&item.id).await {
                Ok(Some(doc)) => match serde_json::to_string(&doc) {
                    Ok(source_json) => ShardOp::IndexDoc {
                        index: concrete.clone(),
                        id: item.id.clone(),
                        source_json,
                        op: "index".to_string(),
                        if_seq_no: None,
                        if_primary_term: None,
                        version: None,
                        version_type: None,
                        replica: false,
                        shard: 0,
                    },
                    Err(err) => {
                        mark_bulk_nack(
                            item,
                            &ShardResult::http(
                                503,
                                json!({
                                    "error": {
                                        "type": "replica_not_acknowledged",
                                        "reason": format!(
                                            "primary applied the bulk item on [{concrete}] but document [{}] is not JSON: {err}",
                                            item.id
                                        )
                                    },
                                    "status": 503
                                })
                                .to_string(),
                            ),
                        );
                        copy_failed = true;
                        wire.push(None);
                        continue;
                    }
                },
                Ok(None) => ShardOp::DeleteDoc {
                    index: concrete.clone(),
                    id: item.id.clone(),
                    if_seq_no: None,
                    if_primary_term: None,
                    replica: false,
                    shard: 0,
                },
                Err(err) => {
                    mark_bulk_nack(
                        item,
                        &ShardResult::http(
                            503,
                            json!({
                                "error": {
                                    "type": "replica_not_acknowledged",
                                    "reason": format!(
                                        "primary applied the bulk item on [{concrete}] but document [{}] could not be read: {err}",
                                        item.id
                                    )
                                },
                                "status": 503
                            })
                            .to_string(),
                        ),
                    );
                    copy_failed = true;
                    wire.push(None);
                    continue;
                }
            },
            Err(err) => {
                mark_bulk_nack(
                    item,
                    &ShardResult::http(
                        503,
                        json!({
                            "error": {
                                "type": "replica_not_acknowledged",
                                "reason": format!(
                                    "primary applied the bulk item but [{concrete}] is not open: {err}"
                                )
                            },
                            "status": 503
                        })
                        .to_string(),
                    ),
                );
                copy_failed = true;
                wire.push(None);
                continue;
            }
        };
        let index = op_index(&op).to_string();
        if let Err(nack) = replicate_write(state, &index, &item.id, op).await {
            mark_bulk_nack(item, &nack);
            copy_failed = true;
            wire.push(None);
            continue;
        }
        wire.push(wire_of(&state.engine, &concrete, &item.id));
    }
    if copy_failed {
        result.errors = true;
    }
    (result, wire)
}

fn op_index(op: &ShardOp) -> &str {
    match op {
        ShardOp::IndexDoc { index, .. }
        | ShardOp::DeleteDoc { index, .. }
        | ShardOp::UpdateDoc { index, .. } => index,
        _ => "",
    }
}

fn bulk_opts_from_parts(
    require_alias: Option<bool>,
    default_pipeline: Option<String>,
    default_source_req_json: Option<String>,
) -> xerj_engine::bulk::BulkOpts {
    xerj_engine::bulk::BulkOpts {
        require_alias,
        default_pipeline,
        default_source_req: default_source_req_json
            .and_then(|json| serde_json::from_str(&json).ok()),
    }
}

async fn run_primary_bulk(
    state: &AppState,
    body: &str,
    default_index: Option<&str>,
    opts: xerj_engine::bulk::BulkOpts,
) -> (xerj_engine::bulk::BulkResult, Vec<Option<(u64, u64)>>) {
    let result =
        xerj_engine::bulk::process_bulk_with_opts(&state.engine, default_index, body, opts).await;
    replicate_bulk_result(state, result).await
}

/// Refuse a forwarded bulk that names a shard this node does not own, and
/// wait until every named index is open. Either check happens before any
/// document is written.
fn bulk_refused_here(state: &AppState, pieces: &[BulkPiece]) -> Option<ShardResult> {
    let me = state.engine.routing_node_id();
    for piece in pieces {
        if piece.preset.is_some() {
            continue;
        }
        let concrete = concrete_index_name(&state.engine, &piece.index);
        if state.engine.get_index(&concrete).is_err() {
            return Some(ShardResult::http(503, shard_not_ready_body(&piece.index)));
        }
        if state.engine.owns_shard(&concrete, &piece.id) {
            continue;
        }
        if let Some(owner) = state.engine.route_write(&concrete, &piece.id) {
            if owner != me {
                return Some(not_this_primary(&piece.index, &owner));
            }
        }
    }
    None
}

async fn handle_bulk(
    state: &AppState,
    body: &str,
    default_index: Option<&str>,
    require_alias: Option<bool>,
    default_pipeline: Option<String>,
    default_source_req_json: Option<String>,
) -> ShardResult {
    let pieces = split_bulk_pieces(body, default_index);
    if let Some(refused) = bulk_refused_here(state, &pieces) {
        return refused;
    }
    let opts = bulk_opts_from_parts(require_alias, default_pipeline, default_source_req_json);
    let (result, wire) = run_primary_bulk(state, body, default_index, opts).await;
    let reply = PrimaryBulkReply {
        took_ms: result.took_ms,
        errors: result.errors,
        items: result.items,
        wire: wire
            .into_iter()
            .map(|item| item.map(|(version, seq_no)| BulkWire { version, seq_no }))
            .collect(),
    };
    let body = serde_json::to_string(&reply).unwrap_or_else(|_| {
        json!({
            "took_ms": 0,
            "errors": true,
            "items": [],
            "wire": []
        })
        .to_string()
    });
    ShardResult::http(200, body)
}

struct OwnerGroup {
    remote: bool,
    owner: String,
    pieces: Vec<usize>,
}

fn spread_group_failure(
    pieces: &[BulkPiece],
    which: &[usize],
    status: u16,
    error: String,
) -> (
    Vec<xerj_engine::bulk::BulkItemResult>,
    Vec<Option<(u64, u64)>>,
) {
    let items = which
        .iter()
        .map(|&at| {
            bulk_item_error(
                &pieces[at].action,
                &pieces[at].index,
                &pieces[at].id,
                status,
                error.clone(),
            )
        })
        .collect();
    (items, vec![None; which.len()])
}

async fn execute_owner_group(
    state: &AppState,
    pieces: &[BulkPiece],
    group: &OwnerGroup,
    opts: &xerj_engine::bulk::BulkOpts,
    default_index: Option<&str>,
) -> (
    Vec<xerj_engine::bulk::BulkItemResult>,
    Vec<Option<(u64, u64)>>,
) {
    let body = group_ndjson(pieces, &group.pieces);
    if !group.remote {
        let (result, wire) = run_primary_bulk(state, &body, default_index, opts.clone()).await;
        return align_group(pieces, &group.pieces, result, wire);
    }
    let op = ShardOp::Bulk {
        body,
        default_index: default_index.map(str::to_string),
        require_alias: opts.require_alias,
        default_pipeline: opts.default_pipeline.clone(),
        default_source_req_json: opts
            .default_source_req
            .as_ref()
            .and_then(|value| serde_json::to_string(value).ok()),
    };
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match state.engine.forward_shard(&group.owner, op.clone()).await {
            Ok(result) if is_shard_not_ready(&result) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            Ok(result) if (200..300).contains(&result.status) => {
                match serde_json::from_str::<PrimaryBulkReply>(&result.body) {
                    Ok(reply) => {
                        let wire = reply
                            .wire
                            .into_iter()
                            .map(|item| item.map(|wire| (wire.version, wire.seq_no)))
                            .collect();
                        let result = xerj_engine::bulk::BulkResult {
                            took_ms: reply.took_ms,
                            errors: reply.errors,
                            items: reply.items,
                        };
                        return align_group(pieces, &group.pieces, result, wire);
                    }
                    Err(err) => {
                        return spread_group_failure(
                            pieces,
                            &group.pieces,
                            503,
                            format!("primary bulk response was not usable: {err}"),
                        );
                    }
                }
            }
            Ok(result) => {
                return spread_group_failure(
                    pieces,
                    &group.pieces,
                    result.status,
                    nack_reason(&result),
                );
            }
            Err(err) => {
                return spread_group_failure(pieces, &group.pieces, 503, err.to_string());
            }
        }
    }
}

fn align_group(
    pieces: &[BulkPiece],
    which: &[usize],
    mut result: xerj_engine::bulk::BulkResult,
    mut wire: Vec<Option<(u64, u64)>>,
) -> (
    Vec<xerj_engine::bulk::BulkItemResult>,
    Vec<Option<(u64, u64)>>,
) {
    if result.items.len() == which.len() {
        if wire.len() < which.len() {
            wire.resize(which.len(), None);
        }
        wire.truncate(which.len());
        return (result.items, wire);
    }
    if result.items.len() == 1 && result.errors {
        let err = result.items.pop().expect("length checked");
        let reason = err
            .error
            .unwrap_or_else(|| "bulk request failed".to_string());
        return spread_group_failure(pieces, which, err.status, reason);
    }
    spread_group_failure(
        pieces,
        which,
        500,
        format!(
            "primary returned {} bulk items for {} actions",
            result.items.len(),
            which.len()
        ),
    )
}

/// Route a bulk body to each action's primary and copy the successes.
///
/// [`crate::es_compat`] calls this only when a cluster handle is attached.
/// The returned wire versions are the primary's. The accepting node does not
/// have the document, so a local lookup would report a fresh id.
pub(crate) async fn bulk_on_primaries(
    state: &AppState,
    default_index: Option<&str>,
    body: &str,
    opts: xerj_engine::bulk::BulkOpts,
) -> (xerj_engine::bulk::BulkResult, Vec<Option<(u64, u64)>>) {
    let started = Instant::now();
    let line_count = body.lines().filter(|line| !line.trim().is_empty()).count();
    let max_actions = state.engine.config().limits.max_actions_per_bulk;
    if line_count == 0 || (max_actions > 0 && line_count > max_actions.saturating_mul(2)) {
        let result =
            xerj_engine::bulk::process_bulk_with_opts(&state.engine, default_index, body, opts)
                .await;
        let wire = vec![None; result.items.len()];
        return (result, wire);
    }

    let mut pieces = split_bulk_pieces(body, default_index);
    let mut ensured: HashMap<String, Result<String, (u16, String)>> = HashMap::new();
    for piece in &mut pieces {
        if piece.preset.is_some() {
            continue;
        }
        let outcome = if let Some(cached) = ensured.get(&piece.index) {
            cached.clone()
        } else {
            let outcome = match ensure_concrete_index(state, &piece.index).await {
                Ok(name) => Ok(name),
                Err(err) => Err(ensure_fail_status(err)),
            };
            ensured.insert(piece.index.clone(), outcome.clone());
            outcome
        };
        match outcome {
            Ok(name) => piece.concrete = name,
            Err((status, reason)) => {
                piece.preset = Some(bulk_item_error(
                    &piece.action,
                    &piece.index,
                    &piece.id,
                    status,
                    reason,
                ));
            }
        }
    }

    let mut groups: Vec<OwnerGroup> = Vec::new();
    for (at, piece) in pieces.iter().enumerate() {
        if piece.preset.is_some() {
            continue;
        }
        let remote = if state.engine.owns_shard(&piece.concrete, &piece.id) {
            None
        } else {
            state.engine.route_write(&piece.concrete, &piece.id)
        };
        let owner = remote.clone().unwrap_or_default();
        if let Some(group) = groups
            .iter_mut()
            .find(|group| group.remote == remote.is_some() && group.owner == owner)
        {
            group.pieces.push(at);
        } else {
            groups.push(OwnerGroup {
                remote: remote.is_some(),
                owner,
                pieces: vec![at],
            });
        }
    }

    let mut items: Vec<Option<xerj_engine::bulk::BulkItemResult>> =
        pieces.iter().map(|piece| piece.preset.clone()).collect();
    let mut wire = vec![None; pieces.len()];
    for group in &groups {
        let (group_items, group_wire) =
            execute_owner_group(state, &pieces, group, &opts, default_index).await;
        for (slot, (item, item_wire)) in group
            .pieces
            .iter()
            .zip(group_items.into_iter().zip(group_wire))
        {
            items[*slot] = Some(item);
            wire[*slot] = item_wire;
        }
    }
    let items: Vec<_> = items
        .into_iter()
        .enumerate()
        .map(|(at, item)| {
            item.unwrap_or_else(|| {
                bulk_item_error(
                    pieces
                        .get(at)
                        .map(|piece| piece.action.as_str())
                        .unwrap_or("index"),
                    pieces
                        .get(at)
                        .map(|piece| piece.index.as_str())
                        .unwrap_or(""),
                    pieces.get(at).map(|piece| piece.id.as_str()).unwrap_or(""),
                    500,
                    "bulk item was not executed",
                )
            })
        })
        .collect();
    let errors = items
        .iter()
        .any(|item| item.error.is_some() || !(200..300).contains(&item.status));
    (
        xerj_engine::bulk::BulkResult {
            took_ms: started.elapsed().as_millis() as u64,
            errors,
            items,
        },
        wire,
    )
}

// ── `_update_by_query` on every primary ─────────────────────────────────────

/// One `_update_by_query` after the accepting node has validated the query.
///
/// [`update_by_query_on_primaries`] borrows this. `max_docs` is the caller's
/// cap for the whole index; the fan-out spends it across primaries.
#[derive(Clone)]
pub(crate) struct UpdateByQueryParts {
    pub query: Value,
    pub script: Option<(String, Value)>,
    pub pipeline: Option<String>,
    pub max_docs: Option<u64>,
    pub scroll_size: usize,
}

/// Box the per-index fan-out so it is not inlined into `update_by_query`.
///
/// See `begin_cluster_update_by_query` for why the future has to live on
/// the heap: a debug worker stack overflows when the handler and the runner
/// are both built on it.
pub(crate) fn pin_update_by_query_on_primaries(
    state: AppState,
    index: String,
    parts: UpdateByQueryParts,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Value> + Send>> {
    Box::pin(async move { update_by_query_on_primaries(&state, &index, &parts).await })
}

fn update_by_query_op(
    index: &str,
    parts: &UpdateByQueryParts,
    max_docs: Option<u64>,
    check_only: bool,
) -> ShardOp {
    ShardOp::UpdateByQuery {
        index: index.to_string(),
        query_json: parts.query.to_string(),
        script_source: parts.script.as_ref().map(|(source, _)| source.clone()),
        script_params_json: parts.script.as_ref().map(|(_, params)| params.to_string()),
        pipeline: parts.pipeline.clone(),
        max_docs,
        scroll_size: parts.scroll_size as u64,
        check_only,
    }
}

fn update_by_query_unavailable(index: &str, detail: &str) -> Value {
    json!({
        "error": {
            "type": "shard_not_ready",
            "reason": format!("update_by_query on [{index}] failed: {detail}")
        },
        "status": 503
    })
}

fn empty_update_by_query() -> Value {
    json!({
        "took": 0,
        "timed_out": false,
        "total": 0,
        "updated": 0,
        "deleted": 0,
        "batches": 0,
        "version_conflicts": 0,
        "noops": 0,
        "failures": [],
        "throttled_millis": 0,
        "requests_per_second": -1,
        "throttled_until_millis": 0,
    })
}

fn value_from_shard(result: &ShardResult) -> Value {
    serde_json::from_str(&result.body).unwrap_or_else(|_| {
        json!({
            "error": {
                "type": "shard_not_ready",
                "reason": result.body,
            },
            "status": result.status
        })
    })
}

fn is_not_ready_value(value: &Value) -> bool {
    value.get("status").and_then(Value::as_u64) == Some(503)
        && value.pointer("/error/type").and_then(Value::as_str) == Some("shard_not_ready")
}

fn ensure_error_status(mut value: Value) -> Value {
    if value.get("status").is_some() {
        return value;
    }
    if let Some(obj) = value.as_object_mut() {
        obj.insert("status".to_string(), json!(503));
    }
    value
}

fn has_replica_nack(body: &Value) -> bool {
    body.get("failures")
        .and_then(Value::as_array)
        .is_some_and(|items| {
            items.iter().any(|item| {
                item.pointer("/cause/type").and_then(Value::as_str)
                    == Some("replica_not_acknowledged")
            })
        })
}

fn stamp_replica_nack(mut body: Value, reason: &str) -> Value {
    if !has_replica_nack(&body) {
        return body;
    }
    if let Some(obj) = body.as_object_mut() {
        obj.insert("status".to_string(), json!(503));
        obj.insert(
            "error".to_string(),
            json!({
                "type": "replica_not_acknowledged",
                "reason": reason,
            }),
        );
    }
    body
}

/// Index open, this node is a primary (when a plan exists), pipeline runnable.
///
/// `Err` is a body the HTTP layer can return. Nothing has been written.
fn prepare_update_by_query(
    state: &AppState,
    index: &str,
    pipeline: Option<&str>,
) -> Result<(), Value> {
    if state.engine.get_index(index).is_err() {
        return Err(serde_json::from_str(&shard_not_ready_body(index))
            .unwrap_or_else(|_| update_by_query_unavailable(index, "index is not open")));
    }
    let me = state.engine.routing_node_id();
    let targets = state.engine.shard_search_targets(index);
    if !targets.is_empty() && !targets.iter().any(|id| id == &me) {
        let owner = targets.first().map(String::as_str).unwrap_or("unknown");
        let body = not_this_primary(index, owner);
        return Err(value_from_shard(&body));
    }
    if let Some(name) = pipeline {
        if let Some(reason) = unrunnable_pipeline_reason(&state.engine, name) {
            return Err(pipeline_rejected_body(&reason));
        }
    }
    Ok(())
}

async fn prepare_update_by_query_wait(
    state: &AppState,
    index: &str,
    pipeline: Option<&str>,
) -> Result<(), Value> {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match prepare_update_by_query(state, index, pipeline) {
            Err(body) if is_not_ready_value(&body) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            other => return other,
        }
    }
}

async fn forward_update_by_query(state: &AppState, index: &str, owner: &str, op: ShardOp) -> Value {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match state.engine.forward_shard(owner, op.clone()).await {
            Ok(result) if is_shard_not_ready(&result) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            Ok(result) => return value_from_shard(&result),
            Err(err) => return update_by_query_unavailable(index, &err.to_string()),
        }
    }
}

async fn copy_updated_document(state: &AppState, index: &str, id: &str) -> Result<(), String> {
    if state.engine.primary_of(index, id).is_none() {
        return Ok(());
    }
    if !state.engine.owns_shard(index, id) {
        return Err(format!(
            "primary applied the update on [{index}] but document [{id}] is not owned by this node"
        ));
    }
    let op = match state.engine.get_index(index) {
        Ok(idx) => match idx.get_document(id).await {
            Ok(Some(doc)) => match serde_json::to_string(&doc) {
                Ok(source_json) => ShardOp::IndexDoc {
                    index: index.to_string(),
                    id: id.to_string(),
                    source_json,
                    op: "index".to_string(),
                    if_seq_no: None,
                    if_primary_term: None,
                    version: None,
                    version_type: None,
                    replica: false,
                    shard: 0,
                },
                Err(err) => {
                    return Err(format!(
                        "primary applied the update on [{index}] but document [{id}] is not JSON: {err}"
                    ));
                }
            },
            Ok(None) => ShardOp::DeleteDoc {
                index: index.to_string(),
                id: id.to_string(),
                if_seq_no: None,
                if_primary_term: None,
                replica: false,
                shard: 0,
            },
            Err(err) => {
                return Err(format!(
                    "primary applied the update on [{index}] but document [{id}] could not be read: {err}"
                ));
            }
        },
        Err(err) => {
            return Err(format!(
                "primary applied the update but [{index}] is not open: {err}"
            ));
        }
    };
    replicate_write(state, index, id, op)
        .await
        .map_err(|nack| nack_reason(&nack))
}

async fn apply_update_by_query_here(
    state: &AppState,
    index: &str,
    parts: &UpdateByQueryParts,
    max_docs: Option<u64>,
) -> Value {
    let idx = match state.engine.get_index(index) {
        Ok(idx) => idx,
        Err(err) => return update_by_query_unavailable(index, &err.to_string()),
    };
    let recorded = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let pipeline = parts
        .pipeline
        .as_ref()
        .map(|name| (std::sync::Arc::clone(&state.engine), name.clone()));
    let mut body = crate::es_compat::run_update_by_query_recorded_boxed(
        idx,
        parts.query.clone(),
        max_docs,
        parts.scroll_size,
        parts.script.clone(),
        pipeline,
        Some(std::sync::Arc::clone(&recorded)),
    )
    .await;
    let ids = recorded
        .lock()
        .unwrap_or_else(|err| err.into_inner())
        .clone();
    // A failed run may already have updated some documents. Copy those before
    // returning the error so a replica does not keep the pre-update source.
    let mut nacks = Vec::new();
    for id in ids {
        if let Err(reason) = copy_updated_document(state, index, &id).await {
            nacks.push((id, reason));
        }
    }
    if body.get("status").is_some() {
        return body;
    }
    if nacks.is_empty() {
        return body;
    }
    let Some(obj) = body.as_object_mut() else {
        return body;
    };
    let failures = obj
        .entry("failures".to_string())
        .or_insert_with(|| json!([]));
    if let Some(failures) = failures.as_array_mut() {
        for (id, reason) in nacks {
            failures.push(json!({
                "id": id,
                "cause": {
                    "type": "replica_not_acknowledged",
                    "reason": reason,
                }
            }));
        }
    }
    body
}

#[allow(clippy::too_many_arguments)]
async fn handle_update_by_query(
    state: &AppState,
    index: &str,
    query_json: &str,
    script_source: Option<String>,
    script_params_json: Option<String>,
    pipeline: Option<String>,
    max_docs: Option<u64>,
    scroll_size: u64,
    check_only: bool,
) -> ShardResult {
    if let Err(body) = prepare_update_by_query_wait(state, index, pipeline.as_deref()).await {
        let status = body
            .get("status")
            .and_then(Value::as_u64)
            .and_then(|status| u16::try_from(status).ok())
            .unwrap_or(503);
        return ShardResult::http(status, body.to_string());
    }
    if check_only {
        return ShardResult::http(200, json!({ "ok": true }).to_string());
    }
    let query = match serde_json::from_str::<Value>(query_json) {
        Ok(query) => query,
        Err(err) => {
            return ShardResult::http(
                400,
                json!({
                    "error": {
                        "type": "parsing_exception",
                        "reason": format!("update_by_query query is not JSON: {err}")
                    },
                    "status": 400
                })
                .to_string(),
            );
        }
    };
    let script = script_source.map(|source| {
        let params = script_params_json
            .as_deref()
            .and_then(|raw| serde_json::from_str(raw).ok())
            .unwrap_or_else(|| json!({}));
        (source, params)
    });
    let parts = UpdateByQueryParts {
        query,
        script,
        pipeline,
        max_docs,
        scroll_size: scroll_size.max(1) as usize,
    };
    let value = apply_update_by_query_here(state, index, &parts, max_docs).await;
    let status = value
        .get("status")
        .and_then(Value::as_u64)
        .and_then(|status| u16::try_from(status).ok())
        .unwrap_or(200);
    ShardResult::http(status, value.to_string())
}

/// Run `_update_by_query` on every primary of `index` and copy the updates.
///
/// Primaries are visited in node-id order so `max_docs` is one budget for the
/// index. A primary that fails the preflight (missing pipeline, or not
/// answering) stops the call before any document is written. A later primary
/// that fails after an earlier one has already applied is returned as that
/// error; the earlier updates stay. `[cluster] enabled = false` does not call
/// this.
pub(crate) async fn update_by_query_on_primaries(
    state: &AppState,
    index: &str,
    parts: &UpdateByQueryParts,
) -> Value {
    let targets = state.engine.shard_search_targets(index);
    if targets.is_empty() {
        // No plan: this node holds the whole index. There is no primary to
        // call, so the run stays here. `replicate_write` does nothing when
        // `primary_of` is `None`.
        return apply_update_by_query_here(state, index, parts, parts.max_docs).await;
    }
    // Every primary, including this node, is a shard call. The runner builds
    // `search_inner` on the caller's stack, and that overflows a debug worker
    // (2 MiB) once the fan-out is above it. `MemoryShardRpc` already runs a
    // handler on an 8 MiB thread — the same thread a remote primary uses — so
    // this node's own shard takes that path too. A primary that is not
    // answering fails here, before any document is written.
    for target in &targets {
        let value = forward_update_by_query(
            state,
            index,
            target,
            update_by_query_op(index, parts, parts.max_docs, true),
        )
        .await;
        if value.get("ok").and_then(Value::as_bool) != Some(true) {
            return ensure_error_status(value);
        }
    }
    if parts.max_docs == Some(0) {
        return empty_update_by_query();
    }

    let mut remaining = parts.max_docs;
    let mut parts_out = Vec::with_capacity(targets.len());
    for target in &targets {
        if remaining == Some(0) {
            break;
        }
        let cap = remaining;
        let value = forward_update_by_query(
            state,
            index,
            target,
            update_by_query_op(index, parts, cap, false),
        )
        .await;
        // A shard that failed its own run (flush, script limit, or a primary
        // that stopped answering) has no `updated` count. Replica nacks keep
        // `updated` and sit in `failures` until the aggregate below.
        if value.get("updated").is_none() {
            return ensure_error_status(value);
        }
        if let Some(left) = remaining.as_mut() {
            let used = value.get("total").and_then(Value::as_u64).unwrap_or(0);
            *left = left.saturating_sub(used);
        }
        parts_out.push(value);
    }
    if parts_out.is_empty() {
        return empty_update_by_query();
    }
    stamp_replica_nack(
        aggregate_by_query_results(parts_out, "updated"),
        "primary applied the update but a replica copy missed quorum. The primary has the update; retry the update so an in-sync replica can take the copy",
    )
}

// ── `_delete_by_query` on every primary ─────────────────────────────────────

/// One `_delete_by_query` after the accepting node has validated the query.
///
/// [`delete_by_query_on_primaries`] borrows this. `max_docs` is the caller's
/// cap for the whole index; the fan-out spends it across primaries.
#[derive(Clone)]
pub(crate) struct DeleteByQueryParts {
    pub query: Value,
    pub max_docs: Option<u64>,
    pub scroll_size: usize,
}

/// Box the per-index fan-out so it is not inlined into `delete_by_query`.
///
/// Same split as [`pin_update_by_query_on_primaries`]: a debug worker stack
/// overflows when the handler and the runner are both built on it.
#[inline(never)]
pub(crate) fn pin_delete_by_query_on_primaries(
    state: AppState,
    index: String,
    parts: DeleteByQueryParts,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Value> + Send>> {
    Box::pin(async move { delete_by_query_on_primaries(&state, &index, &parts).await })
}

fn delete_by_query_op(
    index: &str,
    parts: &DeleteByQueryParts,
    max_docs: Option<u64>,
    check_only: bool,
) -> ShardOp {
    ShardOp::DeleteByQuery {
        index: index.to_string(),
        query_json: parts.query.to_string(),
        max_docs,
        scroll_size: parts.scroll_size as u64,
        check_only,
    }
}

fn delete_by_query_unavailable(index: &str, detail: &str) -> Value {
    json!({
        "error": {
            "type": "shard_not_ready",
            "reason": format!("delete_by_query on [{index}] failed: {detail}")
        },
        "status": 503
    })
}

fn empty_delete_by_query() -> Value {
    json!({
        "took": 0,
        "timed_out": false,
        "total": 0,
        "deleted": 0,
        "batches": 0,
        "version_conflicts": 0,
        "noops": 0,
        "failures": [],
        "throttled_millis": 0,
        "requests_per_second": -1,
        "throttled_until_millis": 0,
    })
}

/// Index open, and this node is a primary when a plan exists.
///
/// `Err` is a body the HTTP layer can return. Nothing has been written.
fn prepare_delete_by_query(state: &AppState, index: &str) -> Result<(), Value> {
    if state.engine.get_index(index).is_err() {
        return Err(serde_json::from_str(&shard_not_ready_body(index))
            .unwrap_or_else(|_| delete_by_query_unavailable(index, "index is not open")));
    }
    let me = state.engine.routing_node_id();
    let targets = state.engine.shard_search_targets(index);
    if !targets.is_empty() && !targets.iter().any(|id| id == &me) {
        let owner = targets.first().map(String::as_str).unwrap_or("unknown");
        let body = not_this_primary(index, owner);
        return Err(value_from_shard(&body));
    }
    Ok(())
}

async fn prepare_delete_by_query_wait(state: &AppState, index: &str) -> Result<(), Value> {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match prepare_delete_by_query(state, index) {
            Err(body) if is_not_ready_value(&body) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            other => return other,
        }
    }
}

async fn forward_delete_by_query(state: &AppState, index: &str, owner: &str, op: ShardOp) -> Value {
    let deadline = Instant::now() + OWNER_READY_WAIT;
    loop {
        match state.engine.forward_shard(owner, op.clone()).await {
            Ok(result) if is_shard_not_ready(&result) && Instant::now() < deadline => {
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
            Ok(result) => return value_from_shard(&result),
            Err(err) => return delete_by_query_unavailable(index, &err.to_string()),
        }
    }
}

async fn copy_deleted_document(state: &AppState, index: &str, id: &str) -> Result<(), String> {
    if state.engine.primary_of(index, id).is_none() {
        return Ok(());
    }
    if !state.engine.owns_shard(index, id) {
        return Err(format!(
            "primary applied the delete on [{index}] but document [{id}] is not owned by this node"
        ));
    }
    let op = ShardOp::DeleteDoc {
        index: index.to_string(),
        id: id.to_string(),
        if_seq_no: None,
        if_primary_term: None,
        replica: false,
        shard: 0,
    };
    replicate_write(state, index, id, op)
        .await
        .map_err(|nack| nack_reason(&nack))
}

async fn apply_delete_by_query_here(
    state: &AppState,
    index: &str,
    parts: &DeleteByQueryParts,
    max_docs: Option<u64>,
) -> Value {
    let idx = match state.engine.get_index(index) {
        Ok(idx) => idx,
        Err(err) => return delete_by_query_unavailable(index, &err.to_string()),
    };
    let recorded = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let mut body = crate::es_compat::run_delete_by_query_recorded_boxed(
        idx,
        parts.query.clone(),
        max_docs,
        parts.scroll_size,
        Some(std::sync::Arc::clone(&recorded)),
    )
    .await;
    let ids = recorded
        .lock()
        .unwrap_or_else(|err| err.into_inner())
        .clone();
    // A failed run may already have deleted some documents. Copy those before
    // returning the error so a replica does not keep them.
    let mut nacks = Vec::new();
    for id in ids {
        if let Err(reason) = copy_deleted_document(state, index, &id).await {
            nacks.push((id, reason));
        }
    }
    if body.get("status").is_some() {
        return body;
    }
    if nacks.is_empty() {
        return body;
    }
    let Some(obj) = body.as_object_mut() else {
        return body;
    };
    let failures = obj
        .entry("failures".to_string())
        .or_insert_with(|| json!([]));
    if let Some(failures) = failures.as_array_mut() {
        for (id, reason) in nacks {
            failures.push(json!({
                "id": id,
                "cause": {
                    "type": "replica_not_acknowledged",
                    "reason": reason,
                }
            }));
        }
    }
    body
}

async fn handle_delete_by_query(
    state: &AppState,
    index: &str,
    query_json: &str,
    max_docs: Option<u64>,
    scroll_size: u64,
    check_only: bool,
) -> ShardResult {
    if let Err(body) = prepare_delete_by_query_wait(state, index).await {
        let status = body
            .get("status")
            .and_then(Value::as_u64)
            .and_then(|status| u16::try_from(status).ok())
            .unwrap_or(503);
        return ShardResult::http(status, body.to_string());
    }
    if check_only {
        return ShardResult::http(200, json!({ "ok": true }).to_string());
    }
    let query = match serde_json::from_str::<Value>(query_json) {
        Ok(query) => query,
        Err(err) => {
            return ShardResult::http(
                400,
                json!({
                    "error": {
                        "type": "parsing_exception",
                        "reason": format!("delete_by_query query is not JSON: {err}")
                    },
                    "status": 400
                })
                .to_string(),
            );
        }
    };
    let parts = DeleteByQueryParts {
        query,
        max_docs,
        scroll_size: scroll_size.max(1) as usize,
    };
    let value = apply_delete_by_query_here(state, index, &parts, max_docs).await;
    let status = value
        .get("status")
        .and_then(Value::as_u64)
        .and_then(|status| u16::try_from(status).ok())
        .unwrap_or(200);
    ShardResult::http(status, value.to_string())
}

/// Run `_delete_by_query` on every primary of `index` and copy the deletes.
///
/// Primaries are visited in node-id order so `max_docs` is one budget for the
/// index. A primary that does not answer stops the call before any document
/// is written. A later primary that fails after an earlier one has already
/// applied is returned as that error; the earlier deletes stay.
/// `[cluster] enabled = false` does not call this.
pub(crate) async fn delete_by_query_on_primaries(
    state: &AppState,
    index: &str,
    parts: &DeleteByQueryParts,
) -> Value {
    let targets = state.engine.shard_search_targets(index);
    if targets.is_empty() {
        // No plan: this node holds the whole index. There is no primary to
        // call, so the run stays here. `replicate_write` does nothing when
        // `primary_of` is `None`.
        return apply_delete_by_query_here(state, index, parts, parts.max_docs).await;
    }
    // Every primary, including this node, is a shard call. The runner builds
    // a search on the caller's stack, and that overflows a debug worker
    // (2 MiB) once the fan-out is above it. `MemoryShardRpc` already runs a
    // handler on an 8 MiB thread, so this node's own shard takes that path
    // too. A primary that is not answering fails here, before any document
    // is written.
    for target in &targets {
        let value = forward_delete_by_query(
            state,
            index,
            target,
            delete_by_query_op(index, parts, parts.max_docs, true),
        )
        .await;
        if value.get("ok").and_then(Value::as_bool) != Some(true) {
            return ensure_error_status(value);
        }
    }
    if parts.max_docs == Some(0) {
        return empty_delete_by_query();
    }

    let mut remaining = parts.max_docs;
    let mut parts_out = Vec::with_capacity(targets.len());
    for target in &targets {
        if remaining == Some(0) {
            break;
        }
        let cap = remaining;
        let value = forward_delete_by_query(
            state,
            index,
            target,
            delete_by_query_op(index, parts, cap, false),
        )
        .await;
        // A shard that failed its own run (flush, script limit, or a primary
        // that stopped answering) has no `deleted` count. Replica nacks keep
        // `deleted` and sit in `failures` until the aggregate below.
        if value.get("deleted").is_none() {
            return ensure_error_status(value);
        }
        if let Some(left) = remaining.as_mut() {
            let used = value.get("total").and_then(Value::as_u64).unwrap_or(0);
            *left = left.saturating_sub(used);
        }
        parts_out.push(value);
    }
    if parts_out.is_empty() {
        return empty_delete_by_query();
    }
    stamp_replica_nack(
        aggregate_by_query_results(parts_out, "deleted"),
        "primary applied the delete but a replica copy missed quorum. The primary has the delete; retry the delete so an in-sync replica can take the copy",
    )
}

//! Warnings when a mapping asks for an embedder the server will not use.
//!
//! `semantic_text` accepts `inference_id`, `model_id`, and `inference_endpoint`
//! because those keys exist on the Elasticsearch wire. Ingest does not read
//! them: every document is embedded with the server's `--embed-mode`, which is
//! fixed for the index at ingest time. Saying so on the create/mapping
//! response is the warning; the hard refusal when a restarted process opens a
//! populated index under a different embedder stays in the engine.

use serde_json::{Map, Value};

/// The embedder this process will actually run. Names are compared
/// case-insensitively after trimming.
#[derive(Debug, Clone)]
pub struct ResolvedEmbedder {
    pub backend: String,
    pub neural_model: String,
    pub proxy_model: String,
    pub proxy_endpoint: String,
}

/// One warning per `semantic_text` field whose requested id or endpoint does
/// not match [`ResolvedEmbedder`]. No request is not a mismatch.
pub fn semantic_embedder_warnings(body: &Value, resolved: &ResolvedEmbedder) -> Vec<String> {
    let Some(properties) = properties_of(body) else {
        return Vec::new();
    };
    let mut fields = Vec::new();
    collect(properties, "", &mut fields);
    let mut warnings = Vec::new();
    for (name, spec) in fields {
        if let Some(warning) = field_warning(&name, spec, resolved) {
            warnings.push(warning);
            if warnings.len() == 8 {
                warnings.push(
                    "further semantic_text embedder mismatches were omitted; the mapping does not \
                     switch the embedder"
                        .to_string(),
                );
                break;
            }
        }
    }
    warnings
}

fn properties_of(body: &Value) -> Option<&Map<String, Value>> {
    body.get("mappings")
        .and_then(|mappings| mappings.get("properties"))
        .or_else(|| body.get("properties"))
        .and_then(Value::as_object)
}

fn collect<'a>(
    properties: &'a Map<String, Value>,
    prefix: &str,
    out: &mut Vec<(String, &'a Map<String, Value>)>,
) {
    for (name, spec) in properties {
        let Some(spec) = spec.as_object() else {
            continue;
        };
        let full = if prefix.is_empty() {
            name.clone()
        } else {
            format!("{prefix}.{name}")
        };
        if spec.get("type").and_then(Value::as_str) == Some("semantic_text") {
            out.push((full.clone(), spec));
        }
        if let Some(nested) = spec.get("properties").and_then(Value::as_object) {
            collect(nested, &full, out);
        }
    }
}

fn field_warning(
    field: &str,
    spec: &Map<String, Value>,
    resolved: &ResolvedEmbedder,
) -> Option<String> {
    let inference_id = spec
        .get("inference_id")
        .or_else(|| spec.get("model_id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty());
    let endpoint = spec
        .get("inference_endpoint")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|endpoint| !endpoint.is_empty());
    if inference_id.is_none() && endpoint.is_none() {
        return None;
    }
    let id_mismatch = inference_id.is_some_and(|id| !id_matches(id, resolved));
    let endpoint_mismatch = endpoint.is_some_and(|endpoint| !endpoint_matches(endpoint, resolved));
    if !id_mismatch && !endpoint_mismatch {
        return None;
    }
    let mut asked = Vec::new();
    if let Some(id) = inference_id {
        if id_mismatch {
            asked.push(format!("inference_id/model_id={id}"));
        }
    }
    if let Some(endpoint) = endpoint {
        if endpoint_mismatch {
            asked.push(format!("inference_endpoint={endpoint}"));
        }
    }
    Some(format!(
        "field [{field}] sets {}, but that does not switch the embedder. This index embeds with \
         the server's {} backend, fixed at ingest time. Changing --embed-mode or this mapping \
         does not re-embed documents already written; re-index into a new index. The faster \
         default is lexical (`xerj --embed-mode lexical`, or omit the flag).",
        asked.join(" and "),
        resolved.backend
    ))
}

fn id_matches(id: &str, resolved: &ResolvedEmbedder) -> bool {
    if id.eq_ignore_ascii_case(resolved.backend.trim()) {
        return true;
    }
    match resolved.backend.trim() {
        "neural" => {
            let model = resolved.neural_model.trim();
            !model.is_empty() && id.eq_ignore_ascii_case(model)
        }
        "proxy" => {
            let model = resolved.proxy_model.trim();
            !model.is_empty() && id.eq_ignore_ascii_case(model)
        }
        _ => false,
    }
}

fn endpoint_matches(endpoint: &str, resolved: &ResolvedEmbedder) -> bool {
    if resolved.backend.trim() != "proxy" {
        return false;
    }
    let configured = resolved.proxy_endpoint.trim();
    !configured.is_empty() && endpoint.eq_ignore_ascii_case(configured)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn lexical() -> ResolvedEmbedder {
        ResolvedEmbedder {
            backend: "lexical".into(),
            neural_model: "sentence-transformers/all-MiniLM-L6-v2".into(),
            proxy_model: String::new(),
            proxy_endpoint: String::new(),
        }
    }

    #[test]
    fn an_empty_create_response_omits_warnings() {
        let encoded =
            serde_json::to_string(&crate::responses::EsIndexResponse::ok("docs")).unwrap();
        assert!(!encoded.contains("warnings"), "{encoded}");
        assert!(encoded.contains("\"acknowledged\":true"), "{encoded}");
        assert!(encoded.contains("\"index\":\"docs\""), "{encoded}");
    }

    #[test]
    fn a_matching_or_absent_request_is_silent() {
        let body = json!({"mappings": {"properties": {
            "body": {"type": "semantic_text"},
            "title": {"type": "semantic_text", "inference_id": "lexical"}
        }}});
        assert!(semantic_embedder_warnings(&body, &lexical()).is_empty());
    }

    #[test]
    fn a_different_inference_id_warns_and_names_reindex() {
        let body = json!({"properties": {
            "body": {"type": "semantic_text", "model_id": ".elser_model_2"}
        }});
        let warnings = semantic_embedder_warnings(&body, &lexical());
        assert_eq!(warnings.len(), 1, "{warnings:?}");
        let warning = &warnings[0];
        assert!(warning.contains("body"), "{warning}");
        assert!(warning.contains(".elser_model_2"), "{warning}");
        assert!(
            warning.contains("does not switch the embedder"),
            "{warning}"
        );
        assert!(warning.contains("fixed at ingest"), "{warning}");
        assert!(warning.contains("re-index"), "{warning}");
        assert!(warning.contains("lexical"), "{warning}");
    }

    #[test]
    fn an_endpoint_on_a_non_proxy_backend_warns() {
        let body = json!({"mappings": {"properties": {
            "body": {"type": "semantic_text", "inference_endpoint": "https://example.test/v1"}
        }}});
        let warnings = semantic_embedder_warnings(&body, &lexical());
        assert_eq!(warnings.len(), 1, "{warnings:?}");
        assert!(warnings[0].contains("inference_endpoint=https://example.test/v1"));
    }

    #[test]
    fn neural_accepts_its_model_id_and_rejects_another() {
        let resolved = ResolvedEmbedder {
            backend: "neural".into(),
            neural_model: "sentence-transformers/all-MiniLM-L6-v2".into(),
            proxy_model: String::new(),
            proxy_endpoint: String::new(),
        };
        let same = json!({"mappings": {"properties": {
            "body": {"type": "semantic_text", "inference_id": "Sentence-Transformers/all-MiniLM-L6-v2"}
        }}});
        assert!(semantic_embedder_warnings(&same, &resolved).is_empty());
        let other = json!({"mappings": {"properties": {
            "body": {"type": "semantic_text", "inference_id": "lexical"}
        }}});
        assert_eq!(semantic_embedder_warnings(&other, &resolved).len(), 1);
    }

    #[test]
    fn proxy_matches_its_endpoint_and_model_only() {
        let resolved = ResolvedEmbedder {
            backend: "proxy".into(),
            neural_model: String::new(),
            proxy_model: "text-embedding-3-small".into(),
            proxy_endpoint: "https://embed.example/v1".into(),
        };
        let same = json!({"mappings": {"properties": {
            "body": {
                "type": "semantic_text",
                "inference_id": "text-embedding-3-small",
                "inference_endpoint": "https://embed.example/v1"
            }
        }}});
        assert!(semantic_embedder_warnings(&same, &resolved).is_empty());
        let other = json!({"mappings": {"properties": {
            "body": {
                "type": "semantic_text",
                "inference_id": "text-embedding-3-small",
                "inference_endpoint": "https://other.example/v1"
            }
        }}});
        let warnings = semantic_embedder_warnings(&other, &resolved);
        assert_eq!(warnings.len(), 1, "{warnings:?}");
        assert!(warnings[0].contains("other.example"));
        assert!(!warnings[0].contains("inference_id/model_id"));
    }
}

//! API error handling — converts internal [`XerjError`] values into HTTP
//! responses with the correct status code and an Elasticsearch-compatible
//! JSON body.
//!
//! # ES error format
//!
//! ```json
//! {
//!   "error": {
//!     "root_cause": [{ "type": "index_not_found_exception", "reason": "…" }],
//!     "type":   "index_not_found_exception",
//!     "reason": "no such index [my-index]"
//!   },
//!   "status": 404
//! }
//! ```

use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use serde::Serialize;
use serde_json::{json, Value};
use xerj_common::XerjError;

// ─────────────────────────────────────────────────────────────────────────────
// ES error body
// ─────────────────────────────────────────────────────────────────────────────

/// A single cause entry inside the ES `root_cause` array.
///
/// Field order matches ES byte-for-byte for `index_not_found_exception`:
/// `type, reason, resource.type, resource.id, index_uuid, index`.
#[derive(Debug, Serialize)]
pub struct EsRootCause {
    #[serde(rename = "type")]
    pub error_type: String,
    pub reason: String,
    #[serde(rename = "resource.type", skip_serializing_if = "Option::is_none")]
    pub resource_type: Option<String>,
    #[serde(rename = "resource.id", skip_serializing_if = "Option::is_none")]
    pub resource_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub index_uuid: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub index: Option<String>,
}

/// The inner `error` object in an ES error response.
#[derive(Debug, Serialize)]
pub struct EsErrorBody {
    pub root_cause: Vec<EsRootCause>,
    #[serde(rename = "type")]
    pub error_type: String,
    pub reason: String,
    #[serde(rename = "resource.type", skip_serializing_if = "Option::is_none")]
    pub resource_type: Option<String>,
    #[serde(rename = "resource.id", skip_serializing_if = "Option::is_none")]
    pub resource_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub index_uuid: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub index: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub request_id: Option<String>,
}

/// Top-level ES-compatible error response shape.
#[derive(Debug, Serialize)]
pub struct EsErrorResponse {
    pub error: EsErrorBody,
    pub status: u16,
    /// Additive, non-ES field carrying an actionable recovery hint (e.g. for
    /// `index_not_found_exception`: nearby index names, the `ax-*` wildcard
    /// an autoindex-managed cluster searches with). Same `_xerj` convention
    /// as the hint on a successful `_search` response — see
    /// `es_compat::search_response_hint`. Absent whenever no handler had
    /// anything more specific to offer than the `reason` string already
    /// says, so this never becomes noise on errors that are already
    /// self-explanatory.
    #[serde(rename = "_xerj", skip_serializing_if = "Option::is_none")]
    pub xerj_hint: Option<Value>,
}

// ─────────────────────────────────────────────────────────────────────────────
// ApiError wrapper
// ─────────────────────────────────────────────────────────────────────────────

/// An error that can be returned from any handler.
///
/// Implements [`IntoResponse`] so it can be used directly as a handler return
/// type via `Result<T, ApiError>`.
#[derive(Debug)]
pub struct ApiError {
    pub inner: XerjError,
    pub request_id: Option<String>,
    pub hint: Option<Value>,
}

impl ApiError {
    pub fn new(inner: XerjError) -> Self {
        Self {
            inner,
            request_id: None,
            hint: None,
        }
    }

    pub fn with_request_id(mut self, id: impl Into<String>) -> Self {
        self.request_id = Some(id.into());
        self
    }

    /// Attach an actionable `_xerj` recovery hint (see [`EsErrorResponse`]).
    /// Additive only — never changes `error.type` / `error.reason` / status.
    pub fn with_hint(mut self, hint: Value) -> Self {
        self.hint = Some(hint);
        self
    }
}

impl From<XerjError> for ApiError {
    fn from(e: XerjError) -> Self {
        Self::new(e)
    }
}

impl ApiError {
    /// ES-compatible error body as a plain `Value`, for contexts that never
    /// go through axum's `Response` type — e.g. storing the `response` of a
    /// completed `_tasks/{id}` entry for a detached background task.
    pub fn into_value(self) -> Value {
        let (_, body) = self.into_parts();
        serde_json::to_value(body).unwrap_or_else(|_| json!({}))
    }

    fn into_parts(self) -> (StatusCode, EsErrorResponse) {
        let mut status_code = self.inner.http_status();

        // ES parity: an explicit write/metadata block is 403
        // (`FORBIDDEN/…/cluster_block_exception`), but the disk *flood-stage*
        // block (`read_only_allow_delete`) is rejected with HTTP 429
        // (`TOO_MANY_REQUESTS/12/disk usage exceeded flood-stage watermark`).
        // Both keep the `cluster_block_exception` type; only the status differs.
        if let XerjError::IndexBlocked { block_type, .. } = &self.inner {
            if block_type.contains("read_only_allow_delete") {
                status_code = 429;
            }
        }

        let mut error_type = xerj_error_type(&self.inner);
        // ES wraps mapping/query errors with a specific phrasing in `reason`;
        // our Display impl adds a "invalid mapping:" / "invalid query:" prefix
        // that doesn't match the published shape. Strip it for compat.
        let reason = match &self.inner {
            XerjError::InvalidMapping { reason } => reason.clone(),
            XerjError::InvalidQuery { reason } => reason.clone(),
            other => other.to_string(),
        };

        // Try to extract index name for root_cause annotation.
        let index_name = extract_index_name(&self.inner);

        // ES date-resolution errors from the range parser (invalid `format`
        // pattern, value that fails an explicit format, malformed date
        // math).  The query crate's Display wraps them as
        // `parse error: <msg>`; strip that so the reason matches ES
        // byte-for-byte, and surface ES's exception types
        // (`illegal_argument_exception` for a bad format string,
        // `parse_exception` in root_cause for unparseable values/math).
        let mut reason = reason;
        let mut date_root: Option<&'static str> = None;
        {
            let stripped = reason.strip_prefix("parse error: ").unwrap_or(&reason);
            if stripped.starts_with("Invalid format: [") {
                reason = stripped.to_string();
                error_type = "illegal_argument_exception".into();
                status_code = 400;
                date_root = Some("illegal_argument_exception");
            } else if stripped.starts_with("failed to parse date field [")
                || stripped.starts_with("operator not supported for date math [")
            {
                reason = stripped.to_string();
                status_code = 400;
                date_root = Some("parse_exception");
            }
        }

        // ES specific-case: `failed to create query:` comes from shard-
        // level query builders and reports `query_shard_exception` in
        // root_cause while keeping the outer wrapper as its usual type.
        let root_type = if let Some(rt) = date_root {
            rt.to_string()
        } else if reason.starts_with("failed to create query:") {
            "query_shard_exception".to_string()
        } else if reason.starts_with("No mapping found for") {
            // #437: a sort field with no mapping is a shard-level query-
            // build failure in real ES too, wrapped the same way as
            // `failed to create query:` above — `query_shard_exception`
            // in root_cause, outer wrapper unchanged.
            "query_shard_exception".to_string()
        } else if reason.starts_with("function score query returned an invalid score:") {
            // ES validates function_score results and raises
            // `illegal_argument_exception` with a 400 status when a
            // function produces a non-finite or negative score
            // (e.g. ln1p on qty=-1 → ln(0) = -∞).
            error_type = "illegal_argument_exception".into();
            status_code = 400;
            "illegal_argument_exception".to_string()
        } else {
            error_type.clone()
        };

        // ES decorates `index_not_found_exception` with
        // `resource.type`/`resource.id`/`index_uuid` and repeats `index` +
        // `reason` at the top level, phrasing the reason as
        // `no such index [name]`. Only apply this when the name is a real
        // index name — several other 404s reuse this variant to carry a
        // sentence (e.g. "index template [x] missing"), which must keep its
        // existing shape. (RC4 Wave-3 item 4f.)
        let (res_type, res_id, res_uuid, top_index) = match &self.inner {
            XerjError::IndexNotFound { .. } => match index_name.as_deref() {
                Some(n) if is_plain_index_name(n) => {
                    reason = format!("no such index [{n}]");
                    (
                        Some("index_or_alias".to_string()),
                        Some(n.to_string()),
                        Some("_na_".to_string()),
                        Some(n.to_string()),
                    )
                }
                _ => (None, None, None, None),
            },
            // A rejected name is not a mapping problem. ES puts the attempted
            // name and `index_uuid: "_na_"` on `invalid_index_name_exception`
            // and leaves the reason as the name rule that failed.
            XerjError::InvalidIndexName { index, .. } => {
                (None, None, Some("_na_".to_string()), Some(index.clone()))
            }
            _ => (None, None, None, None),
        };

        let http_status =
            StatusCode::from_u16(status_code).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
        let root_cause = vec![EsRootCause {
            error_type: root_type,
            reason: reason.clone(),
            resource_type: res_type.clone(),
            resource_id: res_id.clone(),
            index_uuid: res_uuid.clone(),
            index: index_name,
        }];

        let body = EsErrorResponse {
            error: EsErrorBody {
                root_cause,
                error_type,
                reason,
                resource_type: res_type,
                resource_id: res_id,
                index_uuid: res_uuid,
                index: top_index,
                request_id: self.request_id,
            },
            status: status_code,
            xerj_hint: self.hint,
        };

        (http_status, body)
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let (http_status, body) = self.into_parts();
        (http_status, Json(body)).into_response()
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

/// Map a [`XerjError`] to an ES exception type string.
///
/// The returned strings match the `type` field in real ES error responses so
/// that existing ES clients, dashboards, and alerting rules can handle xerj
/// errors without modification.
///
/// Mapping table:
///
/// | `XerjError` variant | ES exception type | HTTP status |
/// |---|---|---|
/// | `IndexNotFound` | `index_not_found_exception` | 404 |
/// | `IndexAlreadyExists` | `resource_already_exists_exception` | 409 |
/// | `InvalidIndexName` | `invalid_index_name_exception` | 400 |
/// | `IndexUnavailable` | `no_shard_available_action_exception` | 503 |
/// | `DocumentNotFound` | `document_missing_exception` | 404 |
/// | `InvalidMapping` | `mapper_parsing_exception` | 400 |
/// | `InvalidQuery` | `search_phase_execution_exception` | 400 |
/// | `StorageError` / `WalError` | `store_exception` | 500 |
/// | `SerializationError` | `json_parse_exception` | 500 |
/// | `ConfigError` | `action_request_validation_exception` | 400 |
/// | `AuthError` | `security_exception` | 401 |
/// | `TlsError` | `connect_exception` | 500 |
/// | `EmbeddingError` | `circuit_breaking_exception` | 500 |
/// | `ResourceExhausted` | `es_rejected_execution_exception` | 429 |
/// | `CircuitBreaking` | `circuit_breaking_exception` | 429 |
/// | `VersionConflict` | `version_conflict_engine_exception` | 409 |
/// | `ResultWindowTooLarge` | `illegal_argument_exception` | 400 |
/// | `IndexBlocked` | `cluster_block_exception` | 403 |
/// | `ClusterUnavailable` | `master_not_discovered_exception` or `cluster_unavailable_exception` | 503 |
/// | `Internal` | `internal_server_error_exception` | 500 |
fn xerj_error_type(e: &XerjError) -> String {
    match e {
        // ── Index lifecycle ───────────────────────────────────────────────
        XerjError::IndexNotFound { .. } => "index_not_found_exception",
        XerjError::IndexAlreadyExists { .. } => "resource_already_exists_exception",
        XerjError::InvalidIndexName { .. } => "invalid_index_name_exception",
        // The index exists; its only copy cannot be opened. ES reports an
        // existing-but-unallocated index this way, so dashboards that already
        // understand a red shard understand this too.
        XerjError::IndexUnavailable { .. } => "no_shard_available_action_exception",
        // ── Document operations ───────────────────────────────────────────
        XerjError::DocumentNotFound { .. } => "document_missing_exception",
        // ── Mapping / schema ──────────────────────────────────────────────
        XerjError::InvalidMapping { .. } => "mapper_parsing_exception",
        // ── Query parsing / execution ─────────────────────────────────────
        XerjError::InvalidQuery { .. } => "search_phase_execution_exception",
        // ── Storage layer ─────────────────────────────────────────────────
        XerjError::StorageError { .. } | XerjError::WalError { .. } => "store_exception",
        // ── Serialization ─────────────────────────────────────────────────
        XerjError::SerializationError { .. } => "json_parse_exception",
        XerjError::InvalidDocumentJson { .. } => "json_parse_exception",
        // ── Configuration ─────────────────────────────────────────────────
        XerjError::ConfigError { .. } => "action_request_validation_exception",
        XerjError::ClusterStateUnavailable => "cluster_state_unavailable",
        // ── Auth ──────────────────────────────────────────────────────────
        XerjError::AuthError { .. } => "security_exception",
        // ── TLS ───────────────────────────────────────────────────────────
        XerjError::TlsError { .. } => "connect_exception",
        // ── Embedding / AI ────────────────────────────────────────────────
        XerjError::EmbeddingError { .. } => "circuit_breaking_exception",
        // ── Resource limits ───────────────────────────────────────────────
        XerjError::ResourceExhausted { .. } => "es_rejected_execution_exception",
        // ── Circuit breaker (parent memory breaker) ───────────────────────
        XerjError::CircuitBreaking { .. } => "circuit_breaking_exception",
        // ── Optimistic concurrency ────────────────────────────────────────
        XerjError::VersionConflict { .. } => "version_conflict_engine_exception",
        // ── Result window ─────────────────────────────────────────────────
        XerjError::ResultWindowTooLarge { .. } => "illegal_argument_exception",
        // ── Index blocks ──────────────────────────────────────────────────
        XerjError::IndexBlocked { .. } => "cluster_block_exception",
        // No leader is the ES "master not discovered" case. Any other reason
        // (timeout, leadership lost, shutting down) is a generic 503: the
        // write was not acknowledged and was not applied on this node.
        XerjError::ClusterUnavailable { reason } => {
            if reason.contains("no elected raft leader") {
                "master_not_discovered_exception"
            } else {
                "cluster_unavailable_exception"
            }
        }
        // ── Catch-all ─────────────────────────────────────────────────────
        XerjError::Internal { .. } => "internal_server_error_exception",
    }
    .to_string()
}

/// Extract the index name from an error, when available, for the ES
/// `root_cause[].index` field. This lets clients identify which index
/// triggered the error without parsing the human-readable reason string.
fn extract_index_name(e: &XerjError) -> Option<String> {
    match e {
        XerjError::IndexNotFound { name } | XerjError::IndexAlreadyExists { name } => {
            Some(name.clone())
        }
        XerjError::InvalidIndexName { index, .. } => Some(index.clone()),
        XerjError::DocumentNotFound { index, .. } => Some(index.clone()),
        XerjError::IndexBlocked { index, .. } | XerjError::IndexUnavailable { index, .. } => {
            Some(index.clone())
        }
        _ => None,
    }
}

/// Whether a string is a plausible concrete index/alias name rather than one
/// of the sentence-style messages some 404s smuggle through `IndexNotFound`
/// (e.g. "index template [x] missing"). ES index names cannot contain spaces
/// or brackets, so those characters reliably distinguish the two — only real
/// names receive the `resource.*` / `no such index [name]` ES treatment.
fn is_plain_index_name(name: &str) -> bool {
    !name.is_empty() && !name.contains([' ', '[', ']'])
}

