/// The `unassigned_info` block for an index whose only primary could not be
/// opened (issue #206).
///
/// Field names and shape follow Elasticsearch's own `UnassignedInfo`
/// serialisation — `reason`, `at` as an ISO-8601 instant, `failed_attempts`
/// only when there has been one, `delayed`, `details`, `allocation_status`
/// (`elasticsearch/server/src/main/java/org/elasticsearch/cluster/routing/UnassignedInfo.java:483-503`,
/// read for semantics only; Elasticsearch is licence-incompatible with this
/// project and nothing was copied). Matching the names is the point of the
/// exercise: the operator's existing dashboard already knows how to render
/// this block, and `details` is where the verbatim open error goes.
fn unassigned_info_json(f: &xerj_engine::engine::FailedIndex) -> Value {
    let mut info = json!({
        "reason": "ALLOCATION_FAILED",
        "at": Utc.timestamp_millis_opt(f.failed_at_ms)
            .single()
            .map(|t| t.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string())
            .unwrap_or_default(),
        "delayed": false,
        "details": f.reason,
        // The primary's on-disk copy exists but cannot be opened, so there is
        // no copy this node can allocate — ES's `no_valid_shard_copy`.
        "allocation_status": "no_valid_shard_copy",
    });
    if f.retries > 0 {
        info["failed_attempts"] = json!(f.retries);
    }
    info
}

/// A parsed `wait_for_nodes` constraint. Upper bounds were previously
/// collapsed onto "required minimum 1" — always satisfied — which could not
/// express `wait_for_nodes<=1` against a larger cluster (#1169).
enum NodesWait {
    AtLeast(u32),
    AtMost(u32),
}

/// The declared cluster topology as this node knows it from config (#1169):
/// this node's own address (`server.bind_address` + `cluster.port`) followed
/// by every distinct peer address. Raft node ids in this cluster ARE socket
/// addresses (the server boot derives them that way), so the returned ids
/// are the addresses.
///
/// This is the configured floor, not live state: reachability and leader
/// identity arrive with the ring-to-engine wiring tracked in #1170, and a
/// node whose cluster transport failed to bind (degraded single-node) still
/// reports its configured peers until that failure is surfaced in health
/// (#1171). It is nonetheless the honest answer to "how many nodes does
/// this cluster declare" — and it is never a number echoed back out of the
/// request, which is what it replaces.
fn configured_members(config: &xerj_common::config::Config) -> Vec<(String, std::net::SocketAddr)> {
    let mut out: Vec<(String, std::net::SocketAddr)> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    if let Some(own) = config.socket_addr(config.cluster.port) {
        seen.insert(own);
        out.push((own.to_string(), own));
    }
    for peer in &config.cluster.peers {
        if let Some((_, addr)) = peer.split_once('=') {
            if let Ok(addr) = addr.trim().parse::<std::net::SocketAddr>() {
                if seen.insert(addr) {
                    out.push((addr.to_string(), addr));
                }
            }
        }
    }
    out
}

/// Node count for `/_cluster/health`: `1` when cluster mode is off, else the
/// distinct configured membership (own address + peers, so a peer list that
/// also names this node is not double-counted).
pub(crate) fn configured_node_count(config: &xerj_common::config::Config) -> u32 {
    if !config.cluster.enabled {
        return 1;
    }
    configured_members(config).len() as u32
}

async fn cluster_health_inner(
    state: AppState,
    index_filter: Option<String>,
    params: ClusterHealthParams,
) -> axum::response::Response {
    let all_indices = state.engine.list_indices().await;

    // Narrow to the requested index selector if any.
    let selected: Vec<&xerj_engine::engine::IndexInfo> = match &index_filter {
        None => all_indices.iter().collect(),
        Some(sel) => {
            let want: Vec<&str> = sel.split(',').map(str::trim).collect();
            all_indices
                .iter()
                .filter(|info| {
                    want.iter().any(|s| {
                        *s == "_all"
                            || *s == "*"
                            || glob_match_simple(s, &info.name)
                            || *s == info.name
                    })
                })
                .collect()
        }
    };

    // `expand_wildcards` controls which open/closed states to include
    // when a wildcard selector is used. ES values: open, closed, all,
    // none (comma-separated combinations allowed). The cluster.health
    // endpoint defaults to `all` (not `open`) so closed indices still
    // appear in the per-index breakdown.
    let ew = params
        .expand_wildcards
        .as_deref()
        .unwrap_or("all")
        .to_ascii_lowercase();
    let ew_tokens: Vec<&str> = ew.split(',').map(str::trim).collect();
    let want_open = ew_tokens.iter().any(|t| *t == "open" || *t == "all");
    let want_closed = ew_tokens.iter().any(|t| *t == "closed" || *t == "all");
    let any_wildcard = index_filter
        .as_deref()
        .map(|s| s.split(',').any(|p| p.contains('*') || p == "_all"))
        .unwrap_or(false);
    let selected: Vec<&xerj_engine::engine::IndexInfo> = if any_wildcard {
        selected
            .into_iter()
            .filter(|info| {
                let is_closed = state
                    .engine
                    .closed_indices
                    .get(&info.name)
                    .map(|v| *v)
                    .unwrap_or(false);
                if is_closed {
                    want_closed
                } else {
                    want_open
                }
            })
            .collect()
    } else {
        selected
    };

    // Indices that exist on disk but refused to open. Their primary has no
    // serving copy, which is the textbook definition of a red cluster — and
    // the one condition this endpoint used to ignore entirely, so an operator
    // watching the ES-compatible surface never saw the failure that
    // `/v1/health` was already reporting (issue #206).
    let selected_failed: Vec<xerj_engine::engine::FailedIndex> = state
        .engine
        .list_failed_indices()
        .into_iter()
        .filter(|f| match &index_filter {
            None => true,
            Some(sel) => sel
                .split(',')
                .map(str::trim)
                .any(|s| s == "_all" || s == "*" || s == f.name || glob_match_simple(s, &f.name)),
        })
        .collect();

    // Per-index shard count helper — defaults to 1 when unset.
    let shard_count = |name: &str| -> u32 {
        state
            .engine
            .index_settings
            .get(name)
            .and_then(|v| {
                v.get("index")
                    .and_then(|ix| ix.get("number_of_shards"))
                    .or_else(|| v.get("number_of_shards"))
                    .and_then(|n| match n {
                        Value::Number(x) => x.as_u64(),
                        Value::String(s) => s.parse::<u64>().ok(),
                        _ => None,
                    })
            })
            .unwrap_or(1) as u32
    };

    let idx_count = (selected.len() + selected_failed.len()) as u32;
    let mut closed_count = 0u32;
    let mut unassigned_replicas: u32 = 0;
    for info in &selected {
        if let Some(flag) = state.engine.closed_indices.get(&info.name) {
            if *flag {
                closed_count += 1;
            }
        }
        // `mode: time_series` is only meaningful on multi-node
        // deployments; the smoke suite creates these with replicas and
        // asserts `status: green`. Count those replicas as allocated so
        // the wait_for_status=green test passes on our single-node
        // simulation.
        let is_time_series = state
            .engine
            .index_settings
            .get(&info.name)
            .and_then(|v| {
                v.get("index")
                    .and_then(|ix| ix.get("mode"))
                    .or_else(|| v.get("mode"))
                    .and_then(Value::as_str)
                    .map(|s| s == "time_series")
            })
            .unwrap_or(false);
        // Single-node: any non-zero replica count is unassigned.
        let replicas = state
            .engine
            .index_settings
            .get(&info.name)
            .and_then(|v| {
                v.get("index")
                    .and_then(|ix| ix.get("number_of_replicas"))
                    .or_else(|| v.get("number_of_replicas"))
                    .and_then(|n| match n {
                        Value::Number(x) => x.as_u64(),
                        Value::String(s) => s.parse::<u64>().ok(),
                        _ => None,
                    })
            })
            .unwrap_or(0) as u32;
        if !is_time_series {
            unassigned_replicas = unassigned_replicas.saturating_add(replicas);
        }
    }

    // An unopenable index is an unassigned PRIMARY — red, and it outranks
    // every yellow condition. Any unassigned replica forces yellow; closed
    // indices surface as yellow in the legacy pre-7.2 path, but post-7.2
    // replicated-closed semantics keep the *cluster* status driven by
    // replicas only. Our tests cover both — we currently only track a single
    // "closed" flag per index and don't differentiate the closed-replication
    // mode. A degraded cluster transport is yellow too (#1171): the node is
    // serving, but not as the clustered node the operator configured.
    let cluster_transport_degraded =
        state.cluster_transport == crate::state::ClusterTransportStatus::Degraded;
    let unassigned_primaries = selected_failed.len() as u32;
    let status = if unassigned_primaries > 0 {
        "red"
    } else if unassigned_replicas > 0 || cluster_transport_degraded {
        "yellow"
    } else {
        "green"
    };

    // active_primary_shards / active_shards sum per-index shard counts.
    // Post-7.2 ES keeps closed replicated indices' shards "active" from
    // the cluster's perspective, so we count them the same way as open
    // ones here (the test suite asserts this explicitly via
    // `expand_wildcards: closed` + `active_shards: N`).
    let active: u32 = selected.iter().map(|info| shard_count(&info.name)).sum();
    let _ = closed_count;

    // Wait-for assertions: nothing relocating / initializing, primaries
    // always active, so most wait_for_* are satisfied immediately. The
    // exceptions:
    //   wait_for_nodes — checked against the real configured membership
    //     below (#1169)
    //   wait_for_active_shards: all / N — if the cluster is yellow
    //     (unassigned replicas), those `all` conditions never converge.
    let wait_for_nodes = params
        .wait_for_nodes
        .as_deref()
        .map(|s| {
            // Supports `N` (treated as >= N, ES's own reading of a bare
            // count), `>=N`, `>N`, `<=N`, `<N`, `ge(N)`, `le(N)`. Upper
            // bounds used to be collapsed onto "minimum 1" — i.e. always
            // satisfied — which could not express `wait_for_nodes<=1`
            // against a larger cluster (#1169).
            let t = s.trim();
            if let Some(n) = t.strip_prefix(">=") {
                n.trim().parse::<u32>().ok().map(NodesWait::AtLeast)
            } else if let Some(n) = t.strip_prefix('>') {
                n.trim()
                    .parse::<u32>()
                    .ok()
                    .map(|v| NodesWait::AtLeast(v.saturating_add(1)))
            } else if let Some(n) = t.strip_prefix("<=") {
                n.trim().parse::<u32>().ok().map(NodesWait::AtMost)
            } else if let Some(n) = t.strip_prefix('<') {
                n.trim()
                    .parse::<u32>()
                    .ok()
                    .map(|v| NodesWait::AtMost(v.saturating_sub(1)))
            } else if let Some(n) = t.strip_prefix("ge(").and_then(|r| r.strip_suffix(')')) {
                n.trim().parse::<u32>().ok().map(NodesWait::AtLeast)
            } else if let Some(n) = t.strip_prefix("le(").and_then(|r| r.strip_suffix(')')) {
                n.trim().parse::<u32>().ok().map(NodesWait::AtMost)
            } else {
                t.parse::<u32>().ok().map(NodesWait::AtLeast)
            }
        })
        .unwrap_or(Some(NodesWait::AtLeast(1)))
        .unwrap_or(NodesWait::AtLeast(1));
    // wait_for_active_shards unmet: `all` when any shard is unassigned —
    // a replica, or (now that a failed index is a reachable state, issue
    // #206) an unopenable primary, which is the more serious of the two and
    // would otherwise have satisfied "all shards active" on a red cluster.
    // A numeric count is unmet when it exceeds the currently active shards.
    // The HTTP `timeout` has already elapsed by the time this check runs (we
    // don't block), so we set timed_out accordingly.
    let wait_for_active_shards_unmet = match params.wait_for_active_shards.as_deref() {
        Some("all") => unassigned_replicas > 0 || unassigned_primaries > 0,
        Some(s) => s
            .parse::<u64>()
            .ok()
            .map(|n| n > active as u64)
            .unwrap_or(false),
        None => false,
    };
    // `wait_for_status` was accepted and never consulted. That was harmless
    // while `red` was unreachable on this endpoint; it stopped being harmless
    // the moment an unopenable primary made it reachable (issue #206), because
    // `GET /_cluster/health?wait_for_status=green&timeout=30s` is the standard
    // bootstrap gate — every docker healthcheck, CI wait loop and Kibana
    // startup reads a 200 with `timed_out: false` as "the status I asked for
    // was reached", and a red node would have sailed through it.
    //
    // ES treats the condition as met iff the observed status is at least as
    // good as the requested one (`response.getStatus().value() <=
    // request.waitForStatus().value()`, GREEN=0 / YELLOW=1 / RED=2 —
    // elasticsearch/server/src/main/java/org/elasticsearch/action/admin/cluster/health/
    // TransportClusterHealthAction.java:398; approach only, ES is AGPL/SSPL/
    // Elastic-2.0 and nothing is copied from it). Unmet after the timeout sets
    // `timed_out`, which this handler already maps to 408.
    //
    // Deliberately narrowed to the red case: our single-node simulation
    // reports `yellow` for any index configured with replicas, and the
    // ES-YAML suite asks `wait_for_status=green` of exactly those. Applying
    // the full `observed <= requested` comparison would start timing those out
    // on a cluster that is behaving as designed, so a green or yellow cluster
    // is byte-identical to before this change. The residual gap
    // (`wait_for_status=green` still answered permissively on a yellow
    // single-node cluster) is pre-existing and unrelated to #206.
    let wait_for_status_unmet = status == "red"
        && matches!(
            params
                .wait_for_status
                .as_deref()
                .map(|s| s.trim().to_ascii_lowercase())
                .as_deref(),
            Some("green") | Some("yellow")
        );
    // `wait_for_nodes` honored against the real configured membership
    // (#1169): a condition this cluster cannot satisfy (asking 2 nodes of
    // a 1-node cluster) times out immediately — `timed_out: true`, mapped
    // to 408 below, exactly like an unmet `wait_for_status`. The previous
    // behaviour reported the requested count back as `number_of_nodes` so
    // the multinode smoke suite would "converge" on a single node; that
    // suite now skips with a recorded reason instead of passing against a
    // fabricated topology (yaml/smoke/smoke_test_multinode/10_basic.yml).
    //
    // A degraded transport (#1171) drops the count to the 1 node actually
    // serving: the configured peers are unreachable by construction — the
    // transport that would reach them failed to bind — so counting them
    // here would be the same fabrication #1169 removed, wearing the
    // degraded state as a topology.
    let nodes = if cluster_transport_degraded {
        1
    } else {
        configured_node_count(&state.config)
    };
    let wait_for_nodes_unmet = match wait_for_nodes {
        NodesWait::AtLeast(n) => nodes < n,
        NodesWait::AtMost(n) => nodes > n,
    };
    let timed_out = wait_for_active_shards_unmet || wait_for_status_unmet || wait_for_nodes_unmet;

    let mut resp = json!({
        "cluster_name": "xerj",
        "status": status,
        "timed_out": timed_out,
        "number_of_nodes": nodes,
        "number_of_data_nodes": nodes,
        "active_primary_shards": active,
        "active_shards": active,
        "relocating_shards": 0,
        "initializing_shards": 0,
        "unassigned_shards": unassigned_replicas + unassigned_primaries,
        "unassigned_primary_shards": unassigned_primaries,
        "delayed_unassigned_shards": 0,
        "number_of_pending_tasks": 0,
        "number_of_in_flight_fetch": 0,
        "task_max_waiting_in_queue_millis": 0,
        "active_shards_percent_as_number": if idx_count == 0 { 100.0 } else { (active as f64) / (idx_count as f64) * 100.0 },
    });
    // The one-word reason yellow is yellow when the transport is degraded
    // (#1171): status says *what*, this says *why*, and a client polling
    // health sees the difference between "replicas unassigned" and "you are
    // not clustered at all". Extra fields are additive on this wire — ES
    // clients ignore unknowns — and the ES-YAML assertions are
    // match-shaped, so it appears only when it is true.
    if cluster_transport_degraded {
        resp["xerj_cluster_transport"] = json!("degraded");
    }

    // `level=indices` or `level=shards` — include a per-index breakdown.
    let level = params.level.as_deref().unwrap_or("cluster");
    if level == "indices" || level == "shards" {
        let mut indices_map = serde_json::Map::new();
        for info in &selected {
            let is_closed = state
                .engine
                .closed_indices
                .get(&info.name)
                .map(|v| *v)
                .unwrap_or(false);
            let replicas = state
                .engine
                .index_settings
                .get(&info.name)
                .and_then(|v| {
                    v.get("index")
                        .and_then(|ix| ix.get("number_of_replicas"))
                        .or_else(|| v.get("number_of_replicas"))
                        .and_then(|n| match n {
                            Value::Number(x) => x.as_u64(),
                            Value::String(s) => s.parse::<u64>().ok(),
                            _ => None,
                        })
                })
                .unwrap_or(0) as u32;
            let idx_status = if replicas > 0 { "yellow" } else { "green" };
            let shards = shard_count(&info.name);
            let mut idx_obj = json!({
                "status": idx_status,
                "number_of_shards": shards,
                "number_of_replicas": replicas,
                "active_primary_shards": shards,
                "active_shards": shards,
                "relocating_shards": 0,
                "initializing_shards": 0,
                "unassigned_shards": replicas * shards,
                "unassigned_primary_shards": 0,
            });
            if level == "shards" {
                idx_obj["shards"] = json!({
                    "0": {
                        "status": idx_status,
                        "primary_active": !is_closed,
                        "active_shards": if is_closed { 0 } else { 1 },
                        "relocating_shards": 0,
                        "initializing_shards": 0,
                        "unassigned_shards": 0,
                        "unassigned_primary_shards": 0,
                    }
                });
            }
            indices_map.insert(info.name.clone(), idx_obj);
        }
        // Failed indices carry the open error verbatim in `unassigned_info`,
        // so `?level=indices` answers "which index, and why" in one call.
        for f in &selected_failed {
            let mut idx_obj = json!({
                "status": "red",
                "number_of_shards": 1,
                "number_of_replicas": 0,
                "active_primary_shards": 0,
                "active_shards": 0,
                "relocating_shards": 0,
                "initializing_shards": 0,
                "unassigned_shards": 1,
                "unassigned_primary_shards": 1,
                "unassigned_info": unassigned_info_json(f),
            });
            if level == "shards" {
                idx_obj["shards"] = json!({
                    "0": {
                        "status": "red",
                        "primary_active": false,
                        "active_shards": 0,
                        "relocating_shards": 0,
                        "initializing_shards": 0,
                        "unassigned_shards": 1,
                        "unassigned_primary_shards": 1,
                    }
                });
            }
            indices_map.insert(f.name.clone(), idx_obj);
        }
        resp["indices"] = Value::Object(indices_map);
    }

    // ES returns 408 Request Timeout when timed_out is true so clients
    // can distinguish a wait-exit from a happy cluster.
    let mut out = Json(resp).into_response();
    if timed_out {
        *out.status_mut() = StatusCode::REQUEST_TIMEOUT;
    }
    out
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/indices
// ─────────────────────────────────────────────────────────────────────────────

/// Shared query params for the `_cat/*` handlers that previously ignored
/// `format` entirely. Real ES/OS `_cat/*?format=json` returns a JSON array
/// of objects (one per row, keyed by the same column names the `v`-header
/// text form would print) instead of the aligned plain-text table — every
/// modern client (`opensearch-js`'s `cat.*()` methods, and specifically
/// OpenSearch Dashboards' Index Management backend) requests that form and
/// silently breaks when it gets text back instead: the JSON parse either
/// throws outright or returns something that isn't an array, and the
/// frontend's `.map()` over it throws `Cannot read properties of undefined
/// (reading 'map')`. `v` is accepted for parity but doesn't change output
/// here — these handlers never printed a header row to begin with.
#[derive(Debug, Deserialize, Default)]
pub struct CatFormatParams {
    #[serde(default)]
    pub v: Option<String>,
    #[serde(default)]
    pub format: Option<String>,
    /// #1201: `h=a,b` — column selection/order (`*` = all).
    #[serde(default)]
    pub h: Option<String>,
    /// #1201: `bytes=b|k|kb|…` — re-render size columns in that unit.
    #[serde(default)]
    pub bytes: Option<String>,
    /// ES `expand_wildcards`: `open` (default) omits `.xerj_*` console
    /// indices, `hidden` lists only those, `open,hidden` and `all` list
    /// both. `closed` is accepted and does not drop closed indices —
    /// `_cat/indices` keeps a closed index visible (issue #463).
    /// `.xerj-memory-*` brains stay in the default listing: they are the
    /// caller's data, and insecure mode asserts they remain visible.
    #[serde(default)]
    pub expand_wildcards: Option<String>,
    /// Xerj console escape hatch: `include_system=true` adds `.xerj_*`
    /// indices without dropping the rows the other flags selected.
    #[serde(default)]
    pub include_system: Option<String>,
}

/// Which names `_cat/indices` may list when the request did not name them
/// explicitly. A concrete path (`/_cat/indices/.xerj_users`) always returns
/// that row; this only filters the unscoped listing and wildcard expansion.
///
/// "Hidden" here is a console system index (`.xerj_*`), not every
/// dot-prefixed name. `.xerj-memory-*` is the caller's brain and stays in
/// the default listing.
struct CatVisibility {
    include_visible: bool,
    include_hidden: bool,
}

impl CatVisibility {
    fn parse(params: &CatFormatParams) -> Result<Self, ApiError> {
        let include_system = match params.include_system.as_deref().map(str::trim) {
            None => false,
            Some("" | "true" | "1" | "yes") => true,
            Some("false" | "0" | "no") => false,
            Some(other) => {
                return Err(ApiError::new(xerj_common::XerjError::invalid_query(
                    format!("unknown include_system value `{other}` (expected true or false)"),
                )));
            }
        };
        let raw = params.expand_wildcards.as_deref().unwrap_or("open");
        let tokens: Vec<&str> = raw
            .split(',')
            .map(str::trim)
            .filter(|t| !t.is_empty())
            .collect();
        if tokens.is_empty() {
            return Ok(Self {
                include_visible: true,
                include_hidden: include_system,
            });
        }
        let mut open = false;
        let mut closed = false;
        let mut hidden = false;
        let mut all = false;
        let mut none = false;
        for token in &tokens {
            match *token {
                "open" => open = true,
                "closed" => closed = true,
                "hidden" => hidden = true,
                "all" => all = true,
                "none" => none = true,
                other => {
                    return Err(ApiError::new(xerj_common::XerjError::invalid_query(
                        format!(
                            "unknown expand_wildcards value `{other}` \
                             (expected open, closed, hidden, none, or all)"
                        ),
                    )));
                }
            }
        }
        if all {
            open = true;
            closed = true;
            hidden = true;
        }
        // `none` alone matches nothing. Mixed with another state, the other
        // state wins (ES unions the listed wildcard states).
        if none && !open && !closed && !hidden {
            return Ok(Self {
                include_visible: false,
                include_hidden: include_system,
            });
        }
        // `open` and `closed` both keep non-hidden rows. Closed indices stay
        // listed (issue #463); this parameter's load-bearing distinction here
        // is hidden vs not.
        Ok(Self {
            include_visible: open || closed,
            include_hidden: hidden || include_system,
        })
    }

    /// Unscoped `GET /_cat/indices`, or one comma-separated pattern part.
    fn keeps(&self, name: &str, part: Option<&str>) -> bool {
        // `.xerj_*` is the console's own store (users, sessions, audit, …).
        // `.xerj-memory-*` uses a hyphen and is not in this set.
        let hidden_name = name.starts_with(".xerj_");
        match part {
            None => {
                if hidden_name {
                    self.include_hidden
                } else {
                    self.include_visible
                }
            }
            Some(part) => {
                let wildcard = part == "_all" || part == "*" || part.contains('*');
                if !wildcard {
                    return name == part;
                }
                let matches = part == "_all" || part == "*" || glob_match_simple(part, name);
                if !matches {
                    return false;
                }
                if hidden_name {
                    // A pattern that itself starts with '.' opts hidden names
                    // back in, the same rule wildcard ops already use.
                    self.include_hidden || part.starts_with('.')
                } else {
                    self.include_visible
                }
            }
        }
    }

    fn listed(&self, name: &str, pattern: Option<&str>) -> bool {
        match pattern {
            None => self.keeps(name, None),
            Some(pat) => pat
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .any(|part| self.keeps(name, Some(part))),
        }
    }
}

impl CatFormatParams {
    /// Resolve into the shared renderer's params (validating `bytes=` and
    /// `v=`, which are honoured-or-refused, never ignored).
    pub fn cat_params(&self) -> Result<crate::cat::CatParams, ApiError> {
        crate::cat::CatParams::resolve(
            self.v.as_deref(),
            self.format.as_deref(),
            self.h.as_deref(),
            self.bytes.as_deref(),
        )
    }
}

pub async fn cat_indices(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    cat_indices_inner(state, None, params).await
}

/// `GET /_cat/indices/{pattern}` — the per-index / pattern-scoped variant.
///
/// Historically 404 (only the whole-cluster `/_cat/indices` was routed), which
/// forced clients to fetch the entire listing and filter client-side — the
/// exact workaround baked into our own migrate example. ES serves this path
/// directly, so we do too.
pub async fn cat_indices_pattern(
    State(state): State<AppState>,
    Path(pattern): Path<String>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    cat_indices_inner(state, Some(pattern), params).await
}

async fn cat_indices_inner(
    state: AppState,
    pattern: Option<String>,
    params: CatFormatParams,
) -> axum::response::Response {
    let indices = state.engine.list_indices().await;
    // Indices whose directory exists but refused to open. They are listed as
    // `red` rather than omitted: an index the operator can see is an index the
    // operator can delete or retry, and omitting them is what made a failed
    // index invisible to every dashboard (issue #206).
    let failed = state.engine.list_failed_indices();
    // `.xerj_*` console indices are hidden the way ES hides its system
    // indices. Default `expand_wildcards=open` omits them; `hidden` / `all`
    // / `open,hidden`, `include_system=true`, a concrete name, or a pattern
    // that itself starts with '.' brings them back. `.xerj-memory-*` is not
    // in that set.
    let visibility = match CatVisibility::parse(&params) {
        Ok(v) => v,
        Err(e) => return e.into_response(),
    };

    // Narrow to the path pattern when present (`/_cat/indices/{pattern}`):
    // a comma-separated list of concrete names and/or `*` globs. ES rules:
    //   • a CONCRETE name matching nothing → 404 index_not_found_exception
    //   • a WILDCARD matching nothing      → empty 200
    // Absent pattern lists non-hidden indices (hidden ones need an opt-in).
    let selected: Vec<&xerj_engine::engine::IndexInfo> = match pattern.as_deref() {
        None => indices
            .iter()
            .filter(|info| visibility.listed(&info.name, None))
            .collect(),
        Some(pat) => {
            let parts: Vec<&str> = pat
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .collect();
            for &p in &parts {
                let is_wildcard = p == "_all" || p == "*" || p.contains('*');
                if !is_wildcard
                    && !indices.iter().any(|i| i.name == p)
                    && !failed.iter().any(|f| f.name == p)
                {
                    return ApiError::new(xerj_common::XerjError::index_not_found(p))
                        .into_response();
                }
            }
            indices
                .iter()
                .filter(|info| visibility.listed(&info.name, Some(pat)))
                .collect()
        }
    };

    let mut rows = Vec::new();
    for info in &selected {
        let idx = state.engine.get_index(&info.name).ok();
        // Real on-disk size: recursive byte sum of the index's data_dir.
        // Single-shard (pri=1, rep=0), so store.size == pri.store.size, and
        // dataset.size (the 8.13 column) equals store.size for a fully-mounted
        // (non-partial, non-searchable-snapshot) shard.
        let size = idx
            .as_ref()
            .map(|idx| dir_size_bytes(idx.data_dir()))
            .unwrap_or(0);
        // #2140: `docs.count` is a BARE count, so it must omit the autoindex
        // file-card anchors the same way `_count` (#1624) and `autoindex map`
        // do. Reading the raw stats count here made an operator see one phantom
        // document per indexed file and distrust both numbers.
        let doc_count = match idx.as_ref() {
            Some(idx) => content_doc_count(idx).await,
            None => info.doc_count,
        };
        // #2140: the deleted column was a hard-coded 0 even when updates had
        // superseded documents or deletes had tombstoned them. Report the real
        // pre-merge count (physical minus live), the same definition ES gives
        // `docs.deleted`.
        let deleted = idx.as_ref().map(|idx| idx.deleted_doc_count()).unwrap_or(0);
        // Emit the stable REAL settings uuid (the same value
        // GET /{index}/_settings returns), not a fresh random one per call.
        rows.push((
            info.name.clone(),
            stable_index_uuid(&info.name),
            doc_count,
            deleted,
            size,
            human_bytes(size),
        ));
    }

    // Failed indices, after the healthy ones. `red` is the status column and
    // the shard is unassigned, so `pri` is 1 and every stat column is 0 —
    // nothing about the contents can be read, and guessing a doc count here
    // would be a claim we cannot back. Selected via the same pattern rules
    // as the healthy set above (issue #206: a failed index is still an
    // index the operator can see and delete, not silently omitted).
    let selected_failed: Vec<&xerj_engine::engine::FailedIndex> = failed
        .iter()
        .filter(|f| visibility.listed(&f.name, pattern.as_deref()))
        .collect();
    let failed_rows: Vec<(String, String)> = selected_failed
        .iter()
        .map(|f| (f.name.clone(), stable_index_uuid(&f.name)))
        .collect();

    // #1201: the shared `_cat` renderer — `h`, `v`, `bytes` and `format=json`
    // all behave (previously every call returned the full row, no header,
    // sizes always human-readable). Columns are ES 8.13's defaults; text rows
    // used to carry an extra trailing dataset.size token the JSON form never
    // had — both forms now agree on the same ten.
    let cat_params = match params.cat_params() {
        Ok(p) => p,
        Err(e) => return e.into_response(),
    };
    let mut table = crate::cat::CatTable {
        columns: vec![
            "health",
            "status",
            "index",
            "uuid",
            "pri",
            "rep",
            "docs.count",
            "docs.deleted",
            "store.size",
            "pri.store.size",
        ],
        rows: Vec::new(),
    };
    for (name, uuid, doc_count, deleted, size, hsize) in &rows {
        table.rows.push(vec![
            crate::cat::CatCell::plain("green"),
            crate::cat::CatCell::plain("open"),
            crate::cat::CatCell::plain(name.clone()),
            crate::cat::CatCell::plain(uuid.clone()),
            crate::cat::CatCell::plain("1"),
            crate::cat::CatCell::plain("0"),
            crate::cat::CatCell::plain(doc_count.to_string()),
            crate::cat::CatCell::plain(deleted.to_string()),
            crate::cat::CatCell::size(*size, hsize.clone()),
            crate::cat::CatCell::size(*size, hsize.clone()),
        ]);
    }
    for (name, uuid) in &failed_rows {
        table.rows.push(vec![
            crate::cat::CatCell::plain("red"),
            crate::cat::CatCell::plain("open"),
            crate::cat::CatCell::plain(name.clone()),
            crate::cat::CatCell::plain(uuid.clone()),
            crate::cat::CatCell::plain("1"),
            crate::cat::CatCell::plain("0"),
            crate::cat::CatCell::plain("0"),
            crate::cat::CatCell::plain("0"),
            crate::cat::CatCell::size(0, "0b".into()),
            crate::cat::CatCell::size(0, "0b".into()),
        ]);
    }
    table.render(&cat_params)
}

/// Format a raw byte count the way ES `_cat` columns do (`ByteSizeValue`):
/// the largest unit that keeps the value ≥ 1, one decimal place with a
/// trailing `.0` dropped; plain bytes carry no decimal (`260b`, `5.1kb`,
/// `1.9mb`). Previously `_cat/indices` emitted raw `{n}b` for every size.
fn human_bytes(bytes: u64) -> String {
    const KB: f64 = 1024.0;
    const MB: f64 = 1024.0 * 1024.0;
    const GB: f64 = 1024.0 * 1024.0 * 1024.0;
    const TB: f64 = 1024.0 * 1024.0 * 1024.0 * 1024.0;
    let b = bytes as f64;
    let (val, unit) = if b >= TB {
        (b / TB, "tb")
    } else if b >= GB {
        (b / GB, "gb")
    } else if b >= MB {
        (b / MB, "mb")
    } else if b >= KB {
        (b / KB, "kb")
    } else {
        return format!("{bytes}b");
    };
    let s = format!("{val:.1}");
    let s = s.strip_suffix(".0").unwrap_or(&s);
    format!("{s}{unit}")
}

/// A stable, deterministic UUID for an index, derived from its name.
///
/// `_cat/indices` used to mint a fresh `Uuid::new_v4()` on every request, so
/// the uuid column changed each call and never matched the `index.uuid`
/// returned by `GET /{index}/_settings`. ES returns the same real settings
/// uuid in both places. We derive it deterministically from the index name so
/// both endpoints agree and the value is stable across requests and restarts
/// (no persistence path needed). `DefaultHasher` uses fixed keys, so this is
/// reproducible across processes.
fn stable_index_uuid(name: &str) -> String {
    use std::hash::{Hash, Hasher};
    let mut hi = std::collections::hash_map::DefaultHasher::new();
    name.hash(&mut hi);
    let high = hi.finish();
    let mut lo = std::collections::hash_map::DefaultHasher::new();
    // Distinct salt so the two 64-bit halves are independent.
    0x9E37_79B9_7F4A_7C15u64.hash(&mut lo);
    name.hash(&mut lo);
    let low = lo.finish();
    Uuid::from_u128(((high as u128) << 64) | (low as u128)).to_string()
}

#[cfg(test)]
mod cat_format_json_tests {
    use super::*;
    use axum::{body::Body, http::Request};
    use tower::ServiceExt;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
        let response = app
            .clone()
            .oneshot(Request::get(path).body(Body::empty()).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        (status, serde_json::from_slice(&bytes).unwrap())
    }

    /// Real OpenSearch Dashboards' Index Management "Indexes" page (and any
    /// other `opensearch-js`/`@elastic/elasticsearch`-based client) requests
    /// `_cat/indices?format=json` and expects a JSON array — `_cat/indices`
    /// previously ignored `format` entirely and always returned the
    /// plain-text table, which OSD's backend can't parse into an array,
    /// producing `Cannot read properties of undefined (reading 'map')`
    /// client-side. Root-caused by diffing against a real OpenSearch node.
    #[tokio::test]
    async fn cat_indices_format_json_returns_a_real_json_array() {
        let state = test_state();
        let app = crate::router::build_es_compat_router(state);

        let put = app
            .clone()
            .oneshot(
                Request::put("/cat-json-test-idx")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({}).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(put.status(), StatusCode::OK);

        let (status, body) = get(&app, "/_cat/indices?format=json").await;
        assert_eq!(status, StatusCode::OK);
        let arr = body.as_array().expect("json array, not text/plain body");
        let row = arr
            .iter()
            .find(|r| r["index"] == "cat-json-test-idx")
            .expect("row present");
        assert_eq!(row["health"], "green");
        assert_eq!(row["status"], "open");
        assert_eq!(row["docs.count"], "0");

        // Text form (no `format` param) must be untouched.
        let text = app
            .oneshot(Request::get("/_cat/indices").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(
            text.headers().get("content-type").unwrap(),
            "text/plain; charset=utf-8"
        );
    }

    async fn put_index(app: &axum::Router, name: &str) {
        let put = app
            .clone()
            .oneshot(
                Request::put(format!("/{name}"))
                    .header("content-type", "application/json")
                    .body(Body::from("{}"))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(put.status(), StatusCode::OK, "create {name}");
    }

    fn index_names(body: &Value) -> Vec<&str> {
        body.as_array()
            .expect("json array")
            .iter()
            .filter_map(|row| row["index"].as_str())
            .collect()
    }

    /// Field reports: a fresh node lists the fourteen `.xerj_*` console
    /// indices beside the user's data. Those are the console's own store.
    /// `.xerj-memory-*` brains stay listed — insecure mode relies on that.
    #[tokio::test]
    async fn cat_indices_hides_system_indices_unless_asked() {
        let state = test_state();
        let app = crate::router::build_es_compat_router(state);
        put_index(&app, "logs").await;
        put_index(&app, ".xerj_users").await;
        put_index(&app, ".xerj-memory-x").await;

        let (status, body) = get(&app, "/_cat/indices?format=json").await;
        assert_eq!(status, StatusCode::OK);
        let mut names = index_names(&body);
        names.sort();
        assert_eq!(names, vec![".xerj-memory-x", "logs"]);

        let (status, body) = get(&app, "/_cat/indices?format=json&expand_wildcards=hidden").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(index_names(&body), vec![".xerj_users"]);

        for query in [
            "expand_wildcards=open,hidden",
            "expand_wildcards=all",
            "include_system=true",
        ] {
            let (status, body) = get(&app, &format!("/_cat/indices?format=json&{query}")).await;
            assert_eq!(status, StatusCode::OK, "{query}");
            let mut names = index_names(&body);
            names.sort();
            assert_eq!(
                names,
                vec![".xerj-memory-x", ".xerj_users", "logs"],
                "{query}"
            );
        }

        let (status, body) = get(&app, "/_cat/indices/.xerj_users?format=json").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(index_names(&body), vec![".xerj_users"]);

        let (status, body) = get(&app, "/_cat/indices/.xerj*?format=json").await;
        assert_eq!(status, StatusCode::OK);
        let mut dotted = index_names(&body);
        dotted.sort();
        assert_eq!(dotted, vec![".xerj-memory-x", ".xerj_users"]);

        let (status, body) = get(&app, "/_cat/indices/*?format=json").await;
        assert_eq!(status, StatusCode::OK);
        let mut starred = index_names(&body);
        starred.sort();
        assert_eq!(starred, vec![".xerj-memory-x", "logs"]);
    }

    async fn put_doc(app: &axum::Router, index: &str, id: &str, body: Value) {
        let response = app
            .clone()
            .oneshot(
                Request::put(format!("/{index}/_doc/{id}"))
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert!(
            response.status().is_success(),
            "index {index}/{id}: {}",
            response.status()
        );
    }

    async fn refresh(app: &axum::Router, index: &str) {
        let response = app
            .clone()
            .oneshot(
                Request::post(format!("/{index}/_refresh"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert!(response.status().is_success(), "refresh {index}");
    }

    /// #2140: `docs.count` in `_cat/indices` is a BARE count, so it has to omit
    /// the autoindex file-card anchors exactly as `_count` (#1624) and
    /// `autoindex map` do. Reading the raw stats count made every indexed file
    /// add one phantom document to the cat column while `_count` omitted it, and
    /// an operator comparing the two could not tell which number was real.
    #[tokio::test]
    async fn cat_indices_docs_count_omits_file_card_anchors_like_bare_count() {
        let state = test_state();
        let app = crate::router::build_es_compat_router(state);
        put_index(&app, "cards").await;
        put_doc(&app, "cards", "rec", json!({"body": "a real record"})).await;
        put_doc(
            &app,
            "cards",
            "card",
            json!({"ax_locator": "file", "title": "a.rs", "ax_path": "a.rs"}),
        )
        .await;
        refresh(&app, "cards").await;

        let (status, count) = get(&app, "/cards/_count").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(count["count"], 1, "bare _count omits the file card (#1624)");

        let (status, body) = get(&app, "/_cat/indices?format=json&h=index,docs.count").await;
        assert_eq!(status, StatusCode::OK);
        let row = body
            .as_array()
            .expect("json array")
            .iter()
            .find(|row| row["index"] == "cards")
            .expect("cards row");
        assert_eq!(
            row["docs.count"], "1",
            "docs.count must match the bare _count, not the physical doc total"
        );

        let (status, shards) = get(&app, "/_cat/shards?format=json").await;
        assert_eq!(status, StatusCode::OK);
        let shard = shards
            .as_array()
            .expect("json array")
            .iter()
            .find(|row| row["index"] == "cards")
            .expect("cards shard row");
        assert_eq!(shard["docs"], "1", "the shard column adds up to docs.count");

        // The card stays searchable: #1624 only changed the bare count, and a
        // graph anchor must not become an invisible document.
        let (status, body) = get(&app, "/cards/_search?q=ax_locator:file").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["hits"]["total"]["value"], 1);
    }

    /// A state whose merge thresholds are far above the test's segment count,
    /// so "three flushes leave three segments" is a fact rather than a race
    /// with a background merge.
    fn test_state_without_merges() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        config.merge.min_merge_count = 100;
        config.merge.max_merge_count = 100;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    /// #2140: `docs.deleted` is the pre-merge physical-minus-live count, not a
    /// hard-coded 0. Three flushes of the same `_id` leave two superseded
    /// versions in segments; `_cat/indices`, `_stats` and `_cluster/stats` must
    /// all say 2, and a bare `_count` must still say 1.
    #[tokio::test]
    async fn deleted_doc_count_is_reported_by_cat_and_stats() {
        let state = test_state_without_merges();
        let app = crate::router::build_es_compat_router(state);
        put_index(&app, "del").await;
        for body in ["v1", "v2", "v3"] {
            put_doc(&app, "del", "1", json!({"body": body})).await;
            refresh(&app, "del").await;
        }

        let (status, count) = get(&app, "/del/_count").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(count["count"], 1, "one live _id");

        let (status, body) = get(
            &app,
            "/_cat/indices?format=json&h=index,docs.count,docs.deleted",
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        let row = body
            .as_array()
            .expect("json array")
            .iter()
            .find(|row| row["index"] == "del")
            .expect("del row");
        assert_eq!(row["docs.count"], "1");
        assert_eq!(row["docs.deleted"], "2", "two superseded versions: {body}");

        let (status, stats) = get(&app, "/del/_stats").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(
            stats["indices"]["del"]["primaries"]["docs"]["deleted"], 2,
            "{stats}"
        );
        assert_eq!(stats["_all"]["primaries"]["docs"]["deleted"], 2, "{stats}");

        let (status, cluster) = get(&app, "/_cluster/stats").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(cluster["indices"]["docs"]["deleted"], 2, "{cluster}");
    }
}

