#[derive(Debug, Default, Deserialize)]
pub struct EsCreateIndexBody {
    #[serde(default)]
    pub settings: Option<EsCreateIndexSettings>,
    #[serde(default)]
    pub mappings: Option<EsCreateIndexMappings>,
}

#[derive(Debug, Deserialize)]
pub struct EsCreateIndexSettings {
    #[serde(default)]
    pub number_of_shards: Option<u32>,
    #[serde(default)]
    pub number_of_replicas: Option<u32>,
}

#[derive(Debug, Default, Deserialize)]
pub struct EsCreateIndexMappings {
    #[serde(default)]
    pub properties: Option<Value>,
}

/// Display-side settings blob stored for `GET /{index}/_settings` at create.
///
/// `None` when the request carried neither settings nor an index-sort
/// decision — the single-node path then leaves `index_settings` untouched.
fn create_time_index_settings(
    body_settings: Option<&Value>,
    explicit_sort_field: &Option<String>,
    explicit_sort_order: &str,
    declared_timestamp_date: bool,
) -> Option<Value> {
    if let Some(settings) = body_settings {
        let mut s = settings.clone();
        if let Some(f) = explicit_sort_field.as_ref() {
            if let Some(o) = s.as_object_mut() {
                o.insert("__xy_index_sort_field".to_string(), json!(f));
                o.insert(
                    "__xy_index_sort_order".to_string(),
                    json!(explicit_sort_order),
                );
                o.insert("__xy_index_sort_explicit".to_string(), json!(true));
            }
        } else if declared_timestamp_date {
            if let Some(o) = s.as_object_mut() {
                o.insert("__xy_index_sort_field".to_string(), json!("@timestamp"));
                o.insert("__xy_index_sort_order".to_string(), json!("desc"));
            }
        }
        return Some(s);
    }
    if let Some(f) = explicit_sort_field.as_ref() {
        return Some(json!({
            "__xy_index_sort_field": f,
            "__xy_index_sort_order": explicit_sort_order,
            "__xy_index_sort_explicit": true,
        }));
    }
    if declared_timestamp_date {
        return Some(json!({
            "__xy_index_sort_field": "@timestamp",
            "__xy_index_sort_order": "desc",
        }));
    }
    None
}

/// Alias map with date-math names resolved. `None` when the body has no
/// `aliases` object.
fn resolved_create_aliases(body: &Value) -> Option<serde_json::Map<String, Value>> {
    let aliases = body.get("aliases")?.as_object()?;
    let mut resolved = serde_json::Map::new();
    for (alias, opts) in aliases {
        resolved.insert(resolve_date_math_index(alias), opts.clone());
    }
    Some(resolved)
}

pub async fn create_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    let body: Value = body.0.unwrap_or(Value::Null);

    // Resolve date math in index name: <log-{now/d}> → log-2026.04.11
    let index = resolve_date_math_index(&index);

    // Leading dots are allowed for system indices like .kibana, .security-*.
    if index.starts_with('_') || index.starts_with('-') || index.starts_with('+') {
        let e = xerj_common::XerjError::invalid_index_name(
            index.clone(),
            format!("Invalid index name [{index}]: must not start with '_', '-', or '+'"),
        );
        return ApiError::new(e).into_response();
    }

    // #80: make the path-traversal guarantee LOCAL at this handler boundary.
    // `Engine::create_index` also runs `IndexName::new`, but validating the name
    // here means the es_compat surface itself rejects `..`, path separators, NUL
    // and other malformed names up front — defense-in-depth, not a guarantee
    // that lives only in a distant call. Same accepted set as before (the engine
    // enforced the identical rule); the rejection is just local and obvious.
    if let Err(e) = xerj_common::IndexName::validate(&index) {
        return ApiError::new(e).into_response();
    }

    if let Some(refusal) = create_index_body_refusal(&index, &body) {
        return refusal;
    }

    // A matching index template contributes mappings and settings the request
    // did not set. The request wins on a field or setting it names. Merged
    // before validation and schema build so `semantic_text` is parsed by the
    // same mapper as an explicit mapping, and `index.default_pipeline` is
    // stored where `default_pipeline_for` and `GET /_settings` read it
    // (#2281). A schema-only pass cannot: the stored mapping was the request
    // body, so a template `semantic_text` was rendered back as `object`, and
    // the template's settings were never copied.
    let (mappings_val, merged_settings) = state.engine.merge_index_template(
        &index,
        body.get("mappings").cloned().unwrap_or(Value::Null),
        body.get("settings").cloned().unwrap_or(Value::Null),
    );
    let settings_ref = (!merged_settings.is_null()).then_some(&merged_settings);

    // Validate mapping field types before creating — ES returns
    // mapper_parsing_exception for unsupported types.
    if let Some(props) = mappings_val.get("properties").and_then(Value::as_object) {
        if let Some(refusal) = empty_field_name_refusal(props) {
            return refusal;
        }
        if let Err(reason) = validate_properties(props) {
            let e = xerj_common::XerjError::invalid_mapping(reason);
            return ApiError::new(e).into_response();
        }
        if let Err(reason) = validate_semantic_companion_targets(props) {
            let e = xerj_common::XerjError::invalid_mapping(reason);
            return ApiError::new(e).into_response();
        }
    }
    // Runtime mapping type validation too.
    if let Some(rt_obj) = mappings_val.get("runtime").and_then(Value::as_object) {
        if let Err(reason) = validate_runtime_fields(rt_obj) {
            let e = xerj_common::XerjError::invalid_mapping(reason);
            return ApiError::new(e).into_response();
        }
    }

    let schema = if let Some(props) = mappings_val.get("properties") {
        // #275: a field asked for something this build cannot deliver (an
        // unimplemented or unknown `quantization`). Refuse the create rather
        // than acknowledge it and echo the value back from `GET /_mapping`.
        match es_properties_to_schema(props) {
            Ok(schema) => schema,
            Err(reason) => {
                let e = xerj_common::XerjError::invalid_mapping(reason);
                return ApiError::new(e).into_response();
            }
        }
    } else {
        Schema::empty()
    };

    // Auto-index-sort: ES enables `index.sort.field: @timestamp DESC` when
    // the original mapping declares a `@timestamp` date field. Encode the
    // decision at create time so the search path can default-sort on it
    // even after @timestamp is later extended by dynamic mapping.
    let declared_timestamp_date = mappings_val
        .pointer("/properties/@timestamp/type")
        .and_then(Value::as_str)
        .map(|t| t == "date" || t == "date_nanos")
        .unwrap_or(false);
    // Explicit index.sort.field in settings (either nested form or flat
    // dotted key form). When present it takes precedence over the
    // @timestamp heuristic. Mirror the field + order into the
    // `__xy_index_sort_*` internal keys so the search handler's
    // default-sort hook picks them up.
    let explicit_sort_field: Option<String> = settings_ref
        .and_then(|s| {
            s.pointer("/index/sort/field")
                .or_else(|| s.pointer("/index/sort.field"))
                .or_else(|| s.get("index.sort.field"))
                .cloned()
        })
        .and_then(|v| match v {
            Value::String(s) => Some(s),
            Value::Array(mut a) => a.first_mut().and_then(|x| x.as_str().map(String::from)),
            _ => None,
        });
    let explicit_sort_order: String = settings_ref
        .and_then(|s| {
            s.pointer("/index/sort/order")
                .or_else(|| s.pointer("/index/sort.order"))
                .or_else(|| s.get("index.sort.order"))
                .cloned()
        })
        .and_then(|v| match v {
            Value::String(s) => Some(s),
            Value::Array(mut a) => a.first_mut().and_then(|x| x.as_str().map(String::from)),
            _ => None,
        })
        .unwrap_or_else(|| "asc".to_string());

    // Thread the merged `settings` into the store config at create time
    // (custom analysis config, the template's `index.default_pipeline`, and
    // the per-index `index.xerj_ingest_shards` WAL shard override that
    // `xerj autoindex` uses to keep each of its hundreds of indices at a
    // single WAL file descriptor). create_index_with_settings applies index
    // templates to the schema; the mapping blob and display settings below
    // are the merged body, so a template field is not re-derived from the
    // native type.
    let create_settings = merged_settings;
    let display_settings = create_time_index_settings(
        (!create_settings.is_null()).then_some(&create_settings),
        &explicit_sort_field,
        &explicit_sort_order,
        declared_timestamp_date,
    );
    let resolved_aliases = resolved_create_aliases(&body);

    // Cluster members replicate the create. The accepting node evaluates
    // templates and date-math aliases; peers apply that result. ILM attach
    // stays on this node either way — it is not in the log.
    if state.engine.has_cluster() {
        let spec = xerj_engine::ReplicatedIndexSpec {
            name: index.clone(),
            schema,
            settings: create_settings,
            mappings: mappings_val,
            index_settings: display_settings.unwrap_or(Value::Null),
            aliases: resolved_aliases
                .clone()
                .map(Value::Object)
                .unwrap_or(Value::Null),
        };
        return match state.engine.replicate_index_create(spec).await {
            Ok(()) => {
                if let Some(Some(policy_name)) = ilm_lifecycle_directive_from_settings(&body) {
                    let _ = crate::ism_api::attach_policy(&state, &index, &policy_name).await;
                }
                let mut resp = EsIndexResponse::ok(&index);
                resp.warnings = embedder_warnings(&state, &body);
                (StatusCode::OK, Json(resp)).into_response()
            }
            Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        };
    }

    match state
        .engine
        .create_index_with_settings(&index, schema, create_settings)
    {
        Ok(()) => {
            // Store the raw settings / mappings / aliases blob as written.
            // These are used by `GET /{index}/_settings`, `GET /{index}/_mapping`,
            // `GET /{index}`, and cluster health replica checks.
            if let Some(s) = display_settings {
                state.engine.index_settings.insert(index.clone(), s);
            }
            if !mappings_val.is_null() {
                // Persists es_mapping.json into the index dir (atomic) so
                // the create-time mapping survives a restart.
                if let Err(error) = state.engine.put_index_mapping(&index, mappings_val.clone()) {
                    return ApiError::new(xerj_common::XerjError::from(error)).into_response();
                }
            }
            if let Some(resolved_aliases) = resolved_aliases {
                // Alias keys can also contain date math
                // (`<logs_{now/d}>` → `logs_2026-04-19`). Resolve each
                // before storing / registering. The meta map keys use the
                // resolved name so GET /_alias round-trips correctly.
                for alias in resolved_aliases.keys() {
                    if let Err(error) = state.engine.add_alias(alias, &index) {
                        return ApiError::new(xerj_common::XerjError::from(error)).into_response();
                    }
                }
                state
                    .engine
                    .index_alias_metadata
                    .insert(index.clone(), Value::Object(resolved_aliases));
                state.engine.flush_alias_metadata();
            }

            // ES-shape lifecycle attach: `index.lifecycle.name` in create-time
            // settings is how ILM associates an index with a policy (there is
            // no dedicated "attach" endpoint on the ES surface, unlike ISM's
            // explicit `POST _plugins/_ism/add/{index}`). Best-effort and
            // silent on a missing/untranslatable policy — real ILM is
            // equally lenient here: it discovers the policy by name lazily
            // and simply doesn't start managing until one exists.
            if let Some(Some(policy_name)) = ilm_lifecycle_directive_from_settings(&body) {
                let _ = crate::ism_api::attach_policy(&state, &index, &policy_name).await;
            }

            let mut resp = EsIndexResponse::ok(&index);
            resp.warnings = embedder_warnings(&state, &body);
            (StatusCode::OK, Json(resp)).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

/// A 400 in Elasticsearch's error shape, for refusals whose `type` (or
/// `caused_by`) a caller matches on and that no `XerjError` variant renders.
fn es_bad_request(error_type: &str, reason: &str, caused_by: Option<(&str, &str)>) -> Response {
    let mut error = json!({
        "root_cause": [{ "type": error_type, "reason": reason }],
        "type": error_type,
        "reason": reason,
    });
    if let Some((cause_type, cause_reason)) = caused_by {
        error["caused_by"] = json!({ "type": cause_type, "reason": cause_reason });
    }
    (
        StatusCode::BAD_REQUEST,
        Json(json!({ "error": error, "status": 400 })),
    )
        .into_response()
}

/// ES refuses a mapping that declares a field with an empty name
/// (`mapper_parsing_exception` caused by `illegal_argument_exception`
/// `field name cannot be an empty string`); XERJ accepted it. Checked through
/// `properties` and multi-field `fields` at every depth.
fn empty_field_name_refusal(props: &serde_json::Map<String, Value>) -> Option<Response> {
    fn has_empty(props: &serde_json::Map<String, Value>) -> bool {
        props.iter().any(|(name, spec)| {
            name.is_empty()
                || ["properties", "fields"].iter().any(|k| {
                    spec.get(*k)
                        .and_then(Value::as_object)
                        .is_some_and(has_empty)
                })
        })
    }
    has_empty(props).then(|| {
        es_bad_request(
            "mapper_parsing_exception",
            "Failed to parse mapping: field name cannot be an empty string",
            Some((
                "illegal_argument_exception",
                "field name cannot be an empty string",
            )),
        )
    })
}

/// One index setting from a create-index `settings` object, in any of the
/// spellings ES accepts: `{"index.a.b": v}`, `{"a.b": v}`,
/// `{"index": {"a": {"b": v}}}`, `{"a": {"b": v}}` or `{"index": {"a.b": v}}`.
fn create_setting<'a>(settings: &'a Value, path: &[&str]) -> Option<&'a Value> {
    let dotted = path.join(".");
    let nested = |root: &'a Value| {
        path.iter()
            .try_fold(root, |v, key| v.get(*key))
            .or_else(|| root.get(&dotted))
    };
    settings
        .get(format!("index.{dotted}"))
        .or_else(|| settings.get("index").and_then(nested))
        .or_else(|| nested(settings))
}

/// Request-shape and setting checks ES applies to a create-index body before
/// anything is created (`indices.create/10_basic.yml`,
/// `search/550_ignore_above_invalid.yml`). Each was previously accepted with
/// a 200. Run before the index exists, so a refusal leaves nothing behind.
fn create_index_body_refusal(index: &str, body: &Value) -> Option<Response> {
    for section in ["mappings", "settings", "aliases"] {
        if let Some(v) = body.get(section) {
            if !v.is_object() && !v.is_null() {
                return Some(es_bad_request(
                    "illegal_argument_exception",
                    &format!(
                        "Malformed [{section}] section for index [{index}], should include an \
                         inner object describing the {section}"
                    ),
                    None,
                ));
            }
        }
    }
    if let Some(props) = body.pointer("/mappings/properties") {
        if !props.is_object() {
            return Some(es_bad_request(
                "mapper_parsing_exception",
                "Failed to parse mapping: [properties] must be a map type",
                None,
            ));
        }
    }
    if let Some(settings) = body.get("settings") {
        if create_setting(settings, &["soft_deletes", "enabled"])
            .is_some_and(|v| v == &json!(false) || v == &json!("false"))
        {
            return Some(es_bad_request(
                "illegal_argument_exception",
                "Creating indices with soft-deletes disabled is no longer supported. Please do \
                 not specify a value for setting [index.soft_deletes.enabled].",
                None,
            ));
        }
        if create_setting(settings, &["mode"]).and_then(Value::as_str) == Some("lookup") {
            let shards = create_setting(settings, &["number_of_shards"]).and_then(|v| {
                v.as_u64()
                    .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
            });
            if let Some(n) = shards.filter(|n| *n != 1) {
                return Some(es_bad_request(
                    "illegal_argument_exception",
                    &format!(
                        "index with [lookup] mode must have [index.number_of_shards] set to 1 \
                         or unset; provided {n}"
                    ),
                    None,
                ));
            }
        }
        let ignore_above = create_setting(settings, &["mapping", "ignore_above"]).and_then(|v| {
            v.as_i64()
                .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
        });
        if let Some(n) = ignore_above.filter(|n| *n < 0) {
            return Some(es_bad_request(
                "illegal_argument_exception",
                &format!(
                    "Failed to parse value [{n}] for setting [index.mapping.ignore_above] must be \
                     >= 0"
                ),
                None,
            ));
        }
    }
    if let Some(aliases) = body.get("aliases").and_then(Value::as_object) {
        for (alias, spec) in aliases {
            if let Some(reason) = alias_value_type_error(alias, spec) {
                return Some(es_bad_request("illegal_argument_exception", &reason, None));
            }
        }
    }
    None
}

/// The Java type name ES's alias parser reports for a JSON value.
fn alias_value_type_name(v: &Value) -> &'static str {
    match v {
        Value::String(_) => "String",
        Value::Bool(_) => "boolean",
        Value::Number(_) => "Number",
        Value::Array(_) => "Array",
        Value::Object(_) => "Object",
        Value::Null => "null",
    }
}

/// ES's `Unsupported <Type> type value [v] for field [f] in alias [a]`: the
/// flag fields take booleans, the routing fields strings or numbers.
fn alias_value_type_error(alias: &str, spec: &Value) -> Option<String> {
    let spec = spec.as_object()?;
    for (field, v) in spec {
        let ok = match field.as_str() {
            "is_write_index" | "is_hidden" => v.is_boolean() || v.is_null(),
            "routing" | "index_routing" | "search_routing" => {
                v.is_string() || v.is_number() || v.is_null()
            }
            _ => true,
        };
        if !ok {
            let shown = match v {
                Value::String(s) => s.clone(),
                other => other.to_string(),
            };
            return Some(format!(
                "Unsupported {} type value [{shown}] for field [{field}] in alias [{alias}]",
                alias_value_type_name(v)
            ));
        }
    }
    None
}

/// ES mapper_parsing_exception emits for unsupported field types. Accept
/// the set of types we actually implement and explicitly reject the few
/// that YAML tests exercise as "invalid" (`baz`, `foobar`, etc.).
fn validate_properties(props: &serde_json::Map<String, Value>) -> Result<(), String> {
    for (name, spec) in props {
        let Some(obj) = spec.as_object() else {
            continue;
        };
        if let Some(t) = obj.get("type").and_then(Value::as_str) {
            if !is_supported_field_type(t) {
                return Err(format!(
                    "Failed to parse mapping: The mapper type [{t}] declared on field [{name}] does not exist. It might have been created within a future version or requires a plugin to be installed. Check the documentation."
                ));
            }
            // #275: the same `quantization` guard `es_properties_to_fields`
            // enforces, applied on the validation walk as well. Not
            // belt-and-braces: this walk recurses into `fields` (multi-fields)
            // where the schema builder does not, so a `dense_vector` declared
            // as a multi-field would otherwise still be accepted, echoed back
            // by `GET /_mapping`, and dropped on the floor. One shared
            // resolver means one accepted set and one error message.
            if matches!(t, "keyword" | "flattened" | "wildcard") {
                if let Some(n) = obj.get("ignore_above").and_then(Value::as_i64) {
                    if n < 0 {
                        return Err(format!(
                            "Failed to parse mapping: [ignore_above] must be positive, got [{n}]"
                        ));
                    }
                }
            }
            if t == "dense_vector" {
                if let Some(opts) = obj.get("index_options") {
                    if obj.get("index").and_then(Value::as_bool) == Some(false) {
                        return Err(
                            "Failed to parse mapping: Field [index_options] requires field \
                             [index] to be configured and set to true"
                                .to_string(),
                        );
                    }
                    let element = obj
                        .get("element_type")
                        .and_then(Value::as_str)
                        .unwrap_or("float");
                    let kind = opts.get("type").and_then(Value::as_str).unwrap_or("");
                    if kind.starts_with("bbq") && matches!(element, "byte" | "bit") {
                        return Err(format!(
                            "Failed to parse mapping: [index_options] of type [{kind}] is not \
                             supported for element_type [{element}]"
                        ));
                    }
                }
                resolve_vector_quantization(name, spec)?;
            }
        }
        // Recurse into sub-properties and multi-fields.
        if let Some(sub) = obj.get("properties").and_then(Value::as_object) {
            validate_properties(sub)?;
        }
        if let Some(fields) = obj.get("fields").and_then(Value::as_object) {
            validate_properties(fields)?;
        }
    }
    Ok(())
}

fn validate_semantic_companion_targets(
    props: &serde_json::Map<String, Value>,
) -> Result<(), String> {
    fn walk(props: &serde_json::Map<String, Value>, parent: Option<&str>) -> Result<(), String> {
        let mut producer_by_target: std::collections::HashMap<String, String> =
            std::collections::HashMap::new();
        for (name, spec) in props {
            let Some(definition) = spec.as_object() else {
                continue;
            };
            if definition.get("type").and_then(Value::as_str) == Some("semantic_text") {
                if let Some(parent) = parent {
                    return Err(format!(
                        "nested semantic_text field [{parent}.{name}] is not supported; \
                         map semantic_text as a top-level field"
                    ));
                }
                let target = definition
                    .get("target_field")
                    .and_then(Value::as_str)
                    .map(str::to_string)
                    .unwrap_or_else(|| format!("{name}_vector"));
                if let Some(first) = producer_by_target.insert(target.clone(), name.clone()) {
                    return Err(format!(
                        "semantic_text fields [{first}] and [{name}] both target [{target}]; \
                     each semantic field must use a distinct target_field"
                    ));
                }
                let explicit_targets = mapping_definitions_for_logical_path(props, &target);
                if explicit_targets.len() > 1 {
                    return Err(format!(
                        "semantic_text field [{name}] target [{target}] is ambiguous because both \
                    literal and nested mapping paths resolve to that name; keep only one"
                    ));
                }
                if props.get(&target).is_none() && !explicit_targets.is_empty() {
                    return Err(format!(
                    "semantic_text field [{name}] target [{target}] resolves to a nested mapping; \
                     custom dotted target_field values must be declared as a literal top-level \
                     property key"
                ));
                }
                if let Some(explicit) = explicit_targets.first() {
                    let explicit_type = explicit
                        .get("type")
                        .and_then(Value::as_str)
                        .unwrap_or("object");
                    if explicit_type != "dense_vector" {
                        return Err(format!(
                            "semantic_text field [{name}] targets [{target}], but that field is \
                         explicitly mapped as [{explicit_type}]; map it as [dense_vector] or \
                         choose another target_field"
                        ));
                    }
                    let semantic_dims = definition
                        .get("dimensions")
                        .or_else(|| definition.get("dims"))
                        .and_then(Value::as_u64)
                        .unwrap_or(384);
                    if let Some(target_dims) = explicit.get("dims").and_then(Value::as_u64) {
                        if target_dims != semantic_dims {
                            return Err(format!(
                            "semantic_text field [{name}] produces {semantic_dims} dimensions, \
                             but target field [{target}] declares {target_dims}"
                        ));
                        }
                    }
                    let semantic_similarity = definition
                        .get("similarity")
                        .and_then(Value::as_str)
                        .unwrap_or("cosine");
                    let target_similarity = explicit
                        .get("similarity")
                        .and_then(Value::as_str)
                        .unwrap_or("cosine");
                    if semantic_similarity != target_similarity {
                        return Err(format!(
                        "semantic_text field [{name}] uses similarity [{semantic_similarity}], \
                         but target field [{target}] declares [{target_similarity}]"
                    ));
                    }
                }
            }
            if let Some(sub) = definition.get("properties").and_then(Value::as_object) {
                let path = parent
                    .map(|prefix| format!("{prefix}.{name}"))
                    .unwrap_or_else(|| name.clone());
                walk(sub, Some(&path))?;
            }
        }
        Ok(())
    }
    walk(props, None)
}

fn mapping_definitions_for_logical_path<'a>(
    props: &'a serde_json::Map<String, Value>,
    path: &str,
) -> Vec<&'a serde_json::Map<String, Value>> {
    let mut matches = Vec::new();
    if let Some(definition) = props.get(path).and_then(Value::as_object) {
        matches.push(definition);
    }
    if path.contains('.') {
        let segments: Vec<&str> = path.split('.').collect();
        let mut current = props;
        let mut found = None;
        for (position, segment) in segments.iter().enumerate() {
            let Some(definition) = current.get(*segment).and_then(Value::as_object) else {
                found = None;
                break;
            };
            if position + 1 == segments.len() {
                found = Some(definition);
                break;
            }
            let Some(children) = definition.get("properties").and_then(Value::as_object) else {
                found = None;
                break;
            };
            current = children;
        }
        if let Some(definition) = found {
            matches.push(definition);
        }
    }
    matches
}

fn validate_runtime_fields(rt: &serde_json::Map<String, Value>) -> Result<(), String> {
    for (name, spec) in rt {
        let Some(obj) = spec.as_object() else {
            continue;
        };
        if let Some(t) = obj.get("type").and_then(Value::as_str) {
            if !is_supported_runtime_field_type(t) {
                return Err(format!(
                    "Failed to parse mapping: The mapper type [{t}] declared on runtime field [{name}] does not exist. It might have been created within a future version or requires a plugin to be installed. Check the documentation."
                ));
            }
        }
    }
    Ok(())
}

/// The runtime-field type allowlist.
///
/// Runtime fields have their OWN, much smaller type registry in ES than
/// mapping properties do: `IndicesModule#getRuntimeFields` registers
/// exactly `boolean`, `composite`, `date`, `double`, `geo_point`, `ip`,
/// `keyword`, `long` and `lookup`, and `RuntimeField.parseRuntimeFields`
/// rejects anything else with the same "mapper type […] does not exist"
/// message this module emits. So a type being a perfectly valid *mapping
/// property* type says nothing about whether it is legal under
/// `mappings.runtime` — `text`, `nested`, `geo_shape`, `dense_vector`,
/// `binary`, `percolator`, `flattened`/`flat_object` and the narrower
/// numerics (`integer`, `float`, `scaled_float`, …, which collapse into
/// `long`/`double` at runtime) are all rejected by real ES.
///
/// Deliberately NOT expressed as "is_supported_field_type minus
/// exclusions": that shared list is the mapping-properties list, and
/// every future addition to it would silently widen this one. The two
/// registries are independent in ES and are kept independent here.
fn is_supported_runtime_field_type(t: &str) -> bool {
    matches!(
        t,
        "boolean"
            | "composite"
            | "date"
            | "double"
            | "geo_point"
            | "ip"
            | "keyword"
            | "long"
            // `lookup` runtime fields resolve each hit against another
            // index; the search path implements them for search-body
            // `runtime_mappings` (see the `type: lookup` branch in the
            // fields-API fetch), and `search/390_lookup_fields.yml`
            // exercises them. Neither `lookup` nor `composite` is a
            // mapping-PROPERTY type, so validating `mappings.runtime`
            // against the property list rejected both outright.
            | "lookup"
    )
}

fn is_supported_field_type(t: &str) -> bool {
    matches!(
        t,
        "text"
            | "keyword"
            | "constant_keyword"
            | "wildcard"
            | "long"
            | "integer"
            | "short"
            | "byte"
            | "double"
            | "float"
            | "half_float"
            | "scaled_float"
            | "unsigned_long"
            | "boolean"
            | "date"
            | "date_nanos"
            | "ip"
            | "binary"
            | "object"
            | "nested"
            | "flattened"
            // OpenSearch's name for the same "index without expanding
            // sub-fields" object type — every "flattened" special case
            // below also treats this as an alias.
            | "flat_object"
            | "geo_point"
            | "geo_shape"
            | "point"
            | "shape"
            | "dense_vector"
            | "sparse_vector"
            | "token_count"
            | "percolator"
            | "completion"
            | "search_as_you_type"
            | "semantic_text"
            | "match_only_text"
            | "histogram"
            | "alias"
            | "ip_range"
            | "integer_range"
            | "long_range"
            | "float_range"
            | "double_range"
            | "date_range"
            | "version"
            | "rank_feature"
            | "rank_features"
            | "annotated_text"
            | "join"
            | "icu_collation_keyword"
            | "aggregate_metric_double"
            | "passthrough"
    )
}

#[cfg(test)]
mod runtime_field_type_tests {
    //! `mappings.runtime` used to be validated against the
    //! MAPPING-PROPERTY type list with `flattened`/`flat_object` carved
    //! out by hand, so the rule was half-enforced: `flat_object` was a
    //! 400 while `text`, `nested`, `geo_shape`, `dense_vector`,
    //! `binary`, `percolator` and the narrow numerics — all of which
    //! real ES rejects just as hard — were a 200. Worse, the two types
    //! that ARE runtime-only (`composite`, `lookup`) are absent from the
    //! mapping-property list and were therefore rejected outright, so
    //! the validator was wrong in both directions.
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::Request,
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn runtime(name: &str, ty: &str) -> serde_json::Map<String, Value> {
        json!({name: {"type": ty}})
            .as_object()
            .expect("object")
            .clone()
    }

    /// Every type real ES registers as a runtime field
    /// (`IndicesModule#getRuntimeFields`) must be accepted.
    #[test]
    fn accepts_the_real_es_runtime_field_types() {
        for ty in [
            "boolean",
            "composite",
            "date",
            "double",
            "geo_point",
            "ip",
            "keyword",
            "long",
            "lookup",
        ] {
            assert!(
                validate_runtime_fields(&runtime("rf", ty)).is_ok(),
                "runtime field type [{ty}] is legal in ES and must be accepted"
            );
        }
    }

    /// `composite` and `lookup` are runtime-only — they are NOT mapping
    /// property types, so validating against the shared property list
    /// rejected them. `lookup` in particular is implemented by the
    /// search path and covered by `search/390_lookup_fields.yml`.
    #[test]
    fn accepts_runtime_only_types_absent_from_the_property_list() {
        for ty in ["composite", "lookup"] {
            assert!(
                !is_supported_field_type(ty),
                "[{ty}] is not a mapping-property type — that is the point of this test"
            );
            assert!(
                validate_runtime_fields(&runtime("rf", ty)).is_ok(),
                "runtime-only type [{ty}] must be accepted under mappings.runtime"
            );
        }
    }

    /// Valid mapping-property types that ES nonetheless refuses under
    /// `mappings.runtime`. `flat_object`/`flattened` were the only two
    /// previously rejected; the rest are the half of the rule that was
    /// missing.
    #[test]
    fn rejects_property_types_es_forbids_in_runtime_fields() {
        for ty in [
            "text",
            "match_only_text",
            "nested",
            "object",
            "geo_shape",
            "shape",
            "point",
            "dense_vector",
            "sparse_vector",
            "binary",
            "percolator",
            "completion",
            "histogram",
            "alias",
            "join",
            "version",
            "constant_keyword",
            "wildcard",
            "date_nanos",
            "integer",
            "short",
            "byte",
            "float",
            "half_float",
            "scaled_float",
            "unsigned_long",
            "ip_range",
            "date_range",
            "rank_feature",
            "token_count",
            "aggregate_metric_double",
            "flattened",
            "flat_object",
        ] {
            assert!(
                is_supported_field_type(ty),
                "[{ty}] must be a valid mapping-property type for this test to mean anything"
            );
            let err = validate_runtime_fields(&runtime("rf", ty)).expect_err(&format!(
                "runtime field type [{ty}] is forbidden by ES and must be rejected"
            ));
            assert_eq!(
                err,
                format!(
                    "Failed to parse mapping: The mapper type [{ty}] declared on runtime field [rf] does not exist. It might have been created within a future version or requires a plugin to be installed. Check the documentation."
                ),
                "rejection must carry ES's mapper-type-does-not-exist wording"
            );
        }
    }

    /// Unknown types stay rejected. A runtime field with no `type` at
    /// all keeps passing — real ES rejects that too ("No type specified
    /// for runtime field"), but that is a separate, pre-existing
    /// divergence this patch deliberately does not change, and the test
    /// pins the current behaviour so the difference stays visible.
    #[test]
    fn unknown_types_rejected_and_typeless_entries_still_pass() {
        assert!(validate_runtime_fields(&runtime("rf", "invalid")).is_err());
        let typeless = json!({"rf": {"script": {"source": "emit(1)"}}})
            .as_object()
            .expect("object")
            .clone();
        assert!(validate_runtime_fields(&typeless).is_ok());
    }

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    async fn create_index_with_runtime_type(ty: &str) -> (StatusCode, Value) {
        let router = crate::router::build_es_compat_router(test_state());
        let response = router
            .oneshot(
                Request::put(format!("/rt-type-{ty}"))
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({"mappings": {"runtime": {"rf": {"type": ty}}}}).to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("create response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        let body: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
        (status, body)
    }

    #[tokio::test]
    async fn create_index_rejects_a_text_runtime_field_over_http() {
        let (status, body) = create_index_with_runtime_type("text").await;
        assert_eq!(
            status,
            StatusCode::BAD_REQUEST,
            "ES rejects text runtime fields; got {status} {body}"
        );
        assert_eq!(body["error"]["type"], "mapper_parsing_exception", "{body}");
        assert_eq!(
            body["error"]["reason"],
            "Failed to parse mapping: The mapper type [text] declared on runtime field [rf] does not exist. It might have been created within a future version or requires a plugin to be installed. Check the documentation.",
            "{body}"
        );
    }

    #[tokio::test]
    async fn create_index_warns_when_semantic_text_asks_for_another_embedder() {
        let router = crate::router::build_es_compat_router(test_state());
        let response = router
            .oneshot(
                Request::put("/embed-warn")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({"mappings": {"properties": {
                            "body": {"type": "semantic_text", "inference_id": ".elser_model_2"}
                        }}})
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("create response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        let body: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
        assert!(status.is_success(), "{status} {body}");
        let warning = body["warnings"][0].as_str().unwrap_or("");
        assert!(warning.contains("does not switch the embedder"), "{body}");
        assert!(warning.contains("re-index"), "{body}");
        assert!(warning.contains(".elser_model_2"), "{body}");
    }

    #[tokio::test]
    async fn put_mapping_without_an_embedder_request_has_no_warnings_key() {
        let state = test_state();
        let router = crate::router::build_es_compat_router(state.clone());
        let created = router
            .clone()
            .oneshot(
                Request::put("/embed-quiet")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({"mappings": {"properties": {"body": {"type": "text"}}}}).to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("create");
        assert!(created.status().is_success());
        let created_bytes = to_bytes(created.into_body(), usize::MAX).await.unwrap();
        let created_body: Value = serde_json::from_slice(&created_bytes).unwrap();
        assert!(
            created_body.get("warnings").is_none(),
            "no mismatch must leave the create JSON unchanged: {created_body}"
        );
        let mapped = router
            .oneshot(
                Request::put("/embed-quiet/_mapping")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({"properties": {
                            "note": {"type": "semantic_text", "inference_id": "lexical"}
                        }})
                        .to_string(),
                    ))
                    .expect("request"),
            )
            .await
            .expect("mapping");
        let status = mapped.status();
        let bytes = to_bytes(mapped.into_body(), usize::MAX).await.unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
        assert!(status.is_success(), "{status} {body}");
        assert!(
            body.get("warnings").is_none(),
            "a matching inference_id must not add warnings: {body}"
        );
        assert_eq!(body["acknowledged"], true, "{body}");
    }

    #[tokio::test]
    async fn create_index_accepts_a_lookup_runtime_field_over_http() {
        let (status, body) = create_index_with_runtime_type("lookup").await;
        assert!(
            status.is_success(),
            "lookup is a legal ES runtime field type; got {status} {body}"
        );
    }

    async fn put_index(path: &str) -> (StatusCode, Value) {
        let response = crate::router::build_es_compat_router(test_state())
            .oneshot(
                Request::put(path)
                    .header("content-type", "application/json")
                    .body(Body::from("{}"))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    /// `PUT /BadName` used to come back as `mapper_parsing_exception` because
    /// every name rule was an `InvalidMapping`. ES answers a bad name with
    /// `invalid_index_name_exception` before it looks at the mapping. A real
    /// mapping error stays `mapper_parsing_exception` (the runtime-field test
    /// above).
    #[tokio::test]
    async fn create_index_rejects_a_bad_name_as_invalid_index_name_exception() {
        for (path, needle) in [
            (
                "/Bad",
                "index name must start with a lowercase letter or '.', got 'B'",
            ),
            (
                "/_secret",
                "Invalid index name [_secret]: must not start with '_', '-', or '+'",
            ),
            ("/bad!name", "index name contains invalid character '!'"),
        ] {
            let (status, body) = put_index(path).await;
            assert_eq!(status, StatusCode::BAD_REQUEST, "{path}: {body}");
            assert_eq!(
                body["error"]["type"], "invalid_index_name_exception",
                "{path}: {body}"
            );
            assert_eq!(body["status"], 400, "{path}");
            let reason = body["error"]["reason"].as_str().unwrap_or("");
            assert!(reason.contains(needle), "{path}: {reason}");
            assert_eq!(body["error"]["index_uuid"], "_na_", "{path}: {body}");
            assert_eq!(
                body["error"]["index"],
                path.trim_start_matches('/'),
                "{path}: {body}"
            );
            assert_eq!(
                body["error"]["root_cause"][0]["type"], "invalid_index_name_exception",
                "{path}"
            );
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// DELETE /{index}
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize, Default)]
pub struct DeleteIndexParams {
    #[serde(default)]
    pub ignore_unavailable: Option<String>,
    #[serde(default)]
    pub allow_no_indices: Option<String>,
}

/// ES 8 `action.destructive_requires_name`. Absent means true: a `DELETE`
/// whose selector is `*`, `_all`, or any wildcard is refused. `false` (bool
/// or the string `"false"`) is the opt-out the ES-YAML suite and the failed-
/// index recovery tests set explicitly. Transient overrides persistent.
/// Closing an index stays stricter: [`close_index`] refuses wildcards even
/// when this setting is false.
fn destructive_requires_name_enabled(settings: &Value) -> bool {
    fn as_bool(value: &Value) -> Option<bool> {
        match value {
            Value::Bool(b) => Some(*b),
            Value::String(s) => match s.trim().to_ascii_lowercase().as_str() {
                "true" => Some(true),
                "false" => Some(false),
                _ => None,
            },
            _ => None,
        }
    }
    let transient = settings
        .get("transient")
        .and_then(|s| s.get("action.destructive_requires_name"));
    let persistent = settings
        .get("persistent")
        .and_then(|s| s.get("action.destructive_requires_name"));
    transient.or(persistent).and_then(as_bool).unwrap_or(true)
}

/// True when any comma-separated selector is `_all`, `*`, or contains `*` or `?`.
fn selector_is_destructive(index: &str) -> bool {
    index
        .split(',')
        .map(str::trim)
        .filter(|part| !part.is_empty())
        .any(|part| part == "_all" || part == "*" || part.contains('*') || part.contains('?'))
}

fn destructive_delete_refused() -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{
                    "type": "illegal_argument_exception",
                    "reason": "Wildcard expressions or all indices are not allowed"
                }],
                "type": "illegal_argument_exception",
                "reason": "Wildcard expressions or all indices are not allowed"
            },
            "status": 400
        })),
    )
        .into_response()
}

pub async fn delete_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<DeleteIndexParams>,
) -> impl IntoResponse {
    // Checked before expansion. A wildcard that matches nothing must still
    // be a 400, and the settings lock is dropped before any delete.
    {
        let settings = state.engine.cluster_settings.read().await;
        if destructive_requires_name_enabled(&settings) && selector_is_destructive(&index) {
            return destructive_delete_refused();
        }
    }
    let ignore_unavailable = params.ignore_unavailable.as_deref() == Some("true");
    let allow_no_indices = params
        .allow_no_indices
        .as_deref()
        .map(|v| v == "true")
        .unwrap_or(true);

    let all = state.engine.list_indices().await;
    let mut all_names: Vec<String> = all.iter().map(|i| i.name.clone()).collect();
    // A failed index is deletable. Its name has to take part in selector
    // resolution or a literal `DELETE /broken` 404s and a wildcard silently
    // skips it — which is exactly the stuck state issue #206 describes.
    all_names.extend(
        state
            .engine
            .list_failed_indices()
            .into_iter()
            .map(|f| f.name),
    );

    let mut to_delete: Vec<String> = Vec::new();
    let parts: Vec<&str> = index
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .collect();

    // Resolve each selector part independently. ES semantics for delete:
    //   - Wildcards / `_all` / `*`: expand against *indices only* (aliases
    //     never match a pattern for delete). If a pattern resolves to
    //     nothing, honor `allow_no_indices` (default true → silently skip).
    //   - Literal alias name: 400 illegal_argument_exception — caller must
    //     use the concrete index name.
    //   - Literal concrete index name: delete it; if missing and
    //     ignore_unavailable=true, skip, else 404.
    for part in &parts {
        if *part == "_all" || *part == "*" || part.contains('*') {
            let mut matched_any = false;
            for name in &all_names {
                if *part == "_all" || *part == "*" || glob_match_simple(part, name) {
                    matched_any = true;
                    if !to_delete.contains(name) {
                        to_delete.push(name.clone());
                    }
                }
            }
            if !matched_any && !allow_no_indices {
                let e = xerj_common::XerjError::index_not_found(*part);
                return ApiError::new(e).into_response();
            }
            continue;
        }

        if state.engine.aliases.contains_key(*part) {
            if ignore_unavailable {
                // ES silently skips the alias under ignore_unavailable
                // and continues processing the rest of the comma list.
                continue;
            }
            let e = xerj_common::XerjError::invalid_query(format!(
                "The provided expression [{part}] matches an alias, specify the corresponding concrete indices instead."
            ));
            let mut resp = ApiError::new(e).into_response();
            *resp.status_mut() = StatusCode::BAD_REQUEST;
            return resp;
        }

        if !all_names.iter().any(|n| n == part) {
            if ignore_unavailable {
                continue;
            }
            let e = xerj_common::XerjError::index_not_found(*part);
            return ApiError::new(e).into_response();
        }
        if !to_delete.contains(&(*part).to_string()) {
            to_delete.push((*part).to_string());
        }
    }

    for name in &to_delete {
        // Report a delete that did not happen. The result used to be dropped
        // on the floor, so an index whose bytes could not be removed (a failed
        // index on a read-only mount, an fs error) still answered
        // `acknowledged: true` and the operator had no way to know the name
        // was still taken. A concurrent delete that already removed it is the
        // one benign outcome and stays silent.
        match state.engine.delete_index(name).await {
            Ok(()) => {}
            Err(e) => {
                let inner: xerj_common::XerjError = e.into();
                if !matches!(inner, xerj_common::XerjError::IndexNotFound { .. }) {
                    return ApiError::new(inner).into_response();
                }
            }
        }
        // RC4-W4 item 5: drop the index's per-index metric label series so it
        // doesn't linger for the process lifetime after the index is gone.
        state.metrics.prune_index_labels(name);
    }
    Json(EsDeleteIndexResponse::ok()).into_response()
}

#[cfg(test)]
mod destructive_requires_name_tests {
    use super::*;

    #[test]
    fn the_setting_defaults_to_requiring_a_name() {
        let empty = json!({"persistent": {}, "transient": {}});
        assert!(destructive_requires_name_enabled(&empty));
        let persistent_false = json!({"persistent": {"action.destructive_requires_name": false}});
        assert!(!destructive_requires_name_enabled(&persistent_false));
        let persistent_string =
            json!({"persistent": {"action.destructive_requires_name": "false"}});
        assert!(!destructive_requires_name_enabled(&persistent_string));
        let transient_wins = json!({
            "persistent": {"action.destructive_requires_name": false},
            "transient": {"action.destructive_requires_name": true}
        });
        assert!(destructive_requires_name_enabled(&transient_wins));
    }

    #[test]
    fn a_wildcard_or_all_selector_is_destructive_and_a_name_is_not() {
        for selector in ["_all", "*", "ax-*", "a?", "kept,ax-*", "foo,_all"] {
            assert!(selector_is_destructive(selector), "{selector}");
        }
        for selector in ["ax-docs", "ax-docs,ax-code", ""] {
            assert!(!selector_is_destructive(selector), "{selector}");
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize, Default)]
pub struct GetIndexParams {
    /// Expose human-readable forms of numeric/time-based settings
    /// (`creation_date_string`, `version.created_string`).
    #[serde(default)]
    pub human: Option<String>,
    #[serde(default)]
    pub features: Option<String>,
    #[serde(default)]
    pub ignore_unavailable: Option<String>,
    #[serde(default)]
    pub allow_no_indices: Option<String>,
    #[serde(default)]
    pub expand_wildcards: Option<String>,
}

pub async fn get_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<GetIndexParams>,
) -> impl IntoResponse {
    get_index_inner(state, index, params).await
}

async fn get_index_inner(
    state: AppState,
    index: String,
    params: GetIndexParams,
) -> axum::response::Response {
    // A name that starts with `_` (other than `_all`) can never be an index:
    // ES answers 400 `invalid_index_name_exception`, not a 404. (A leading
    // `-` in a list is an exclusion, so only `_` is checked.)
    if let Some(bad) = index
        .split(',')
        .map(str::trim)
        .find(|p| p.starts_with('_') && *p != "_all")
    {
        return es_bad_request(
            "invalid_index_name_exception",
            &format!("Invalid index name [{bad}], must not start with '_', '-', or '+'"),
            None,
        );
    }
    let ignore_unavailable = params.ignore_unavailable.as_deref() == Some("true");
    // ES default: wildcard / `_all` selectors default `allow_no_indices=true`
    // (a pattern that matches nothing returns `{}` rather than 404). Explicit
    // names default to false — unknown names still 404.
    let selector_has_wildcard = index
        .split(',')
        .map(str::trim)
        .any(|p| p == "_all" || p == "*" || p.contains('*'));
    let allow_no_indices = params
        .allow_no_indices
        .as_deref()
        .map(|v| v == "true")
        .unwrap_or(selector_has_wildcard);

    let expand_wildcards = params
        .expand_wildcards
        .as_deref()
        .unwrap_or("open")
        .to_string();
    let include_closed = expand_wildcards
        .split(',')
        .any(|w| w == "closed" || w == "all");
    let include_open = expand_wildcards
        .split(',')
        .any(|w| w == "open" || w == "all");

    let all = state.engine.list_indices().await;
    // An index whose directory refused to open still EXISTS — this endpoint
    // is the metadata read, not a shard read. ES resolves it out of cluster
    // metadata and never consults a shard
    // (elasticsearch/server/src/main/java/org/elasticsearch/action/admin/
    // indices/get/TransportGetIndexAction.java:107 `localClusterStateOperation`
    // → :113 `concreteIndexNames(state.metadata(), request)` then
    // `project.findMappings/findAllAliases/settings`; approach only, nothing
    // copied — ES is AGPL/SSPL/Elastic-2.0), so a red index answers 200 with
    // its metadata there. Answering 404 `index_not_found` here was the same
    // lie issue #206 is about, and it contradicted every other surface in the
    // same run: `_cat/indices` printed a red row for the name while
    // `GET /{name}` said it did not exist.
    //
    // `list_failed_indices` is visibility-filtered, so a failed brain a scoped
    // key may not read stays invisible to it here too.
    let failed_names: Vec<String> = state
        .engine
        .list_failed_indices()
        .into_iter()
        .map(|f| f.name)
        .collect();

    // Resolve the selector into concrete names.
    let mut selected: Vec<String> = Vec::new();
    let mut had_missing = false;
    for part in index.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if part == "_all" || part == "*" {
            for name in all.iter().map(|i| &i.name).chain(failed_names.iter()) {
                if !selected.contains(name) {
                    selected.push(name.clone());
                }
            }
            continue;
        }
        if part.contains('*') {
            for name in all.iter().map(|i| &i.name).chain(failed_names.iter()) {
                if glob_match_simple(part, name) && !selected.contains(name) {
                    selected.push(name.clone());
                }
            }
            continue;
        }
        // Exact name — could be a real index, or an alias pointing at one
        // (ES/OpenSearch accept both interchangeably on GET /{index}; e.g.
        // Kibana/OSD resolve `.kibana` — always an alias, never a bare
        // index — through this exact endpoint).
        if let Some(targets) = state.engine.aliases.get(part) {
            for n in targets.value() {
                if !selected.contains(n) {
                    selected.push(n.clone());
                }
            }
        } else if all.iter().any(|info| info.name == part) || failed_names.iter().any(|n| n == part)
        {
            if !selected.contains(&part.to_string()) {
                selected.push(part.to_string());
            }
        } else {
            had_missing = true;
            if !ignore_unavailable {
                // Exact missing names fail unless ignore_unavailable=true.
                let e = xerj_common::XerjError::index_not_found(part);
                return ApiError::new(e).into_response();
            }
        }
    }

    // Drop closed/open indices per expand_wildcards filter.
    selected.retain(|name| {
        let is_closed = state
            .engine
            .closed_indices
            .get(name)
            .map(|v| *v)
            .unwrap_or(false);
        if is_closed {
            include_closed
        } else {
            include_open
        }
    });

    if selected.is_empty() {
        // No match: empty object if allow_no_indices or ignore_unavailable.
        if allow_no_indices || ignore_unavailable || had_missing {
            return Json(json!({})).into_response();
        }
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }

    // `features` is a comma-separated selector of which sections to include.
    let features: Vec<String> = match &params.features {
        Some(s) if !s.is_empty() => s.split(',').map(str::trim).map(String::from).collect(),
        _ => vec!["aliases".into(), "mappings".into(), "settings".into()],
    };
    let want_aliases = features.iter().any(|f| f == "aliases");
    let want_mappings = features.iter().any(|f| f == "mappings");
    let want_settings = features.iter().any(|f| f == "settings");

    let human = params.human.as_deref() == Some("true");

    let mut body = serde_json::Map::new();
    for name in &selected {
        // `None` = the name exists but has no open handle (a failed index).
        // Its metadata is still served — the schema-derived mapping fallback
        // is the only part that needs a live index, and a failed index falls
        // back to the mapping blob persisted next to its data instead.
        let idx = match state.engine.get_index(name) {
            Ok(i) => Some(i),
            Err(_) if failed_names.iter().any(|n| n == name) => None,
            Err(_) => continue,
        };

        // Aliases: enumerate aliases pointing at this index; fold in per-alias
        // metadata (filter/routing/is_write_index) if captured at create-time.
        let mut aliases_map = serde_json::Map::new();
        for entry in state.engine.aliases.iter() {
            if entry.value().contains(name) {
                let meta = state
                    .engine
                    .index_alias_metadata
                    .get(name)
                    .and_then(|v| v.get(entry.key()).cloned())
                    .unwrap_or_else(|| json!({}));
                aliases_map.insert(entry.key().clone(), meta);
            }
        }

        // Mappings: prefer the raw blob written at create; fall back to the
        // schema-derived properties (which tracks subsequent put_mapping).
        let stored_mappings = state.engine.index_mappings.get(name).map(|v| v.clone());
        let mappings = match (stored_mappings, &idx) {
            (Some(m), _) if !m.is_null() => m,
            (_, Some(i)) => {
                let schema = i.schema().await;
                let properties = schema_to_es_properties(&schema);
                json!({ "properties": properties })
            }
            // Failed index with no persisted mapping blob: report an empty
            // mapping rather than inventing one. Nothing is known about its
            // fields until it opens.
            (_, None) => json!({ "properties": {} }),
        };

        // Settings: replay what was written (normalized to strings), merged
        // with engine defaults; `analysis` is the block in force (#1092) and
        // `creation_date` is the persisted creation time (#1573).
        let settings_inner = index_settings_response(&state, name, idx.as_ref(), human).await;

        let mut index_obj = serde_json::Map::new();
        if want_aliases {
            index_obj.insert("aliases".into(), Value::Object(aliases_map));
        }
        if want_mappings {
            index_obj.insert("mappings".into(), mappings);
        }
        if want_settings {
            index_obj.insert("settings".into(), settings_inner);
        }
        body.insert(name.clone(), Value::Object(index_obj));
    }

    Json(Value::Object(body)).into_response()
}

/// The `settings` object `GET /{index}` and `GET /{index}/_settings` serve.
///
/// Two fixes over replaying the display map alone (#1092):
///
/// * The display map (`engine.index_settings`) is rebuilt from each index's
///   `settings.json` when that index is opened (#2294). A live index whose
///   display entry is still missing falls back to the same file — what the
///   index was created with — so `GET /_settings` and `default_pipeline_for`
///   agree.
/// * `analysis` is reported from the engine, not echoed: whatever spelling the
///   caller used (`settings.analysis` beside an `index` block was dropped
///   outright), the response carries `index.analysis` = the block the index's
///   analyzer registry was actually built from, and nothing for a pre-#204
///   index whose declared block is not honoured. An agent verifying "is my
///   stemmer on?" over the wire gets the answer search would give.
///
/// A failed index (`idx == None`) keeps the display-map-only behaviour.
async fn index_settings_response(
    state: &AppState,
    name: &str,
    idx: Option<&std::sync::Arc<xerj_engine::Index>>,
    human: bool,
) -> Value {
    let mut stored = state
        .engine
        .index_settings
        .get(name)
        .map(|v| v.clone())
        .unwrap_or(Value::Null);
    if stored.is_null() {
        if let Some(i) = idx {
            stored = i.get_settings().await;
        }
    }
    // Creation timestamps: the real persisted value (#1573), not a fresh
    // `Utc::now()` per request. `index_created_at` is recorded at create and
    // loaded from `created_at.json` on boot; the fallback only covers an
    // index that has no recorded time (e.g. a failed create).
    let created_at_ms = state.engine.index_created_at.get(name).map(|v| *v);
    let mut settings = merge_settings_defaults(&stored, name, human, created_at_ms);
    if let Some(i) = idx {
        let in_force = i.analysis_in_force().await;
        if let Some(inner) = settings.get_mut("index").and_then(Value::as_object_mut) {
            inner.retain(|k, _| k != "analysis" && !k.starts_with("analysis."));
            if let Some(a) = in_force {
                inner.insert("analysis".to_string(), a);
            }
        }
    }
    settings
}

/// Normalize a raw user-provided settings blob to the ES response shape.
///
/// ES always wraps user settings under `{ "index": { ... } }` and coerces
/// all simple values to strings. Missing fields fall through to engine
/// defaults (single shard, zero replicas).
fn merge_settings_defaults(
    user_settings: &Value,
    provided_name: &str,
    human: bool,
    created_at_ms: Option<i64>,
) -> Value {
    // Pull the inner `index` block if the user used `{ "index": { ... } }`
    // syntax; otherwise treat the whole blob as the inner block.
    let raw_inner = user_settings
        .get("index")
        .cloned()
        .unwrap_or_else(|| user_settings.clone());

    let mut inner = serde_json::Map::new();

    // Default fields, overridable by the user.
    inner.insert("number_of_shards".into(), Value::String("1".into()));
    inner.insert("number_of_replicas".into(), Value::String("0".into()));

    if let Some(obj) = raw_inner.as_object() {
        for (k, v) in obj {
            // Internal bookkeeping keys (index-sort hints written at create
            // time) are not ES index settings — never surface them in the
            // settings response. They were leaking into GET /{index}/_settings
            // for any index with an @timestamp-derived or explicit index sort.
            if k.starts_with("__xy_") {
                continue;
            }
            // ES coerces numeric settings to strings in the response.
            let coerced = match v {
                Value::Number(n) => Value::String(n.to_string()),
                Value::Bool(b) => Value::String(b.to_string()),
                other => other.clone(),
            };
            inner.insert(k.clone(), coerced);
        }
    }

    // Synthesize required fields if absent. `creation_date` prefers the
    // persisted creation time: a client comparing two `GET /{index}` calls
    // must see one stable value (index age, ILM-style tooling). The `now`
    // fallback is only for an index with no recorded time.
    let created_ms = created_at_ms.unwrap_or_else(|| Utc::now().timestamp_millis());
    inner
        .entry("creation_date".to_string())
        .or_insert_with(|| Value::String(created_ms.to_string()));
    // Emit the stable, deterministic index uuid — the SAME value
    // _cat/indices reports — rather than a fresh random one per request.
    inner.insert(
        "uuid".to_string(),
        Value::String(stable_index_uuid(provided_name)),
    );
    let version = inner
        .entry("version".to_string())
        .or_insert_with(|| json!({ "created": "8130099" }));
    if human {
        if let Some(v_obj) = version.as_object_mut() {
            v_obj
                .entry("created_string".to_string())
                .or_insert_with(|| Value::String("8.13.0".into()));
        }
    }
    inner
        .entry("provided_name".to_string())
        .or_insert_with(|| Value::String(provided_name.to_string()));

    if human {
        // ES returns a pretty timestamp when `human=true`.
        if let Some(cd) = inner
            .get("creation_date")
            .and_then(Value::as_str)
            .and_then(|s| s.parse::<i64>().ok())
        {
            let ts = chrono::DateTime::<Utc>::from_timestamp_millis(cd).unwrap_or_else(Utc::now);
            inner
                .entry("creation_date_string".to_string())
                .or_insert_with(|| {
                    Value::String(ts.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
                });
        }
    }

    json!({ "index": Value::Object(inner) })
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT /{index}/_mapping
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct EsPutMappingBody {
    #[serde(default)]
    pub properties: Option<Value>,
    #[serde(default)]
    pub dynamic: Option<Value>,
}

pub async fn put_mapping(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    // Wildcard-expand index list.
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }

    // ES 8+ forbids explicit mapping types in put_mapping. Any top-level
    // key that wraps a {properties: ...} object other than `properties`
    // itself is treated as a type name (the most common is `_doc`), and
    // the call is rejected with illegal_argument_exception.
    if let Some(obj) = body.as_object() {
        for (k, v) in obj {
            if k == "properties"
                || k == "dynamic"
                || k == "_source"
                || k == "_meta"
                || k == "_routing"
                || k == "_size"
                || k == "_field_names"
                || k == "numeric_detection"
                || k == "date_detection"
                || k == "dynamic_date_formats"
                || k == "dynamic_templates"
                || k == "runtime"
                || k == "subobjects"
            {
                continue;
            }
            if v.get("properties").is_some() {
                // Emit a raw JSON body so error.type is literally
                // `illegal_argument_exception` — our InvalidMapping
                // variant maps to mapper_parsing_exception.
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "root_cause": [{
                                "type": "illegal_argument_exception",
                                "reason": "Types cannot be provided in put mapping requests"
                            }],
                            "type": "illegal_argument_exception",
                            "reason": "Types cannot be provided in put mapping requests",
                        },
                        "status": 400,
                    })),
                )
                    .into_response();
            }
        }
    }

    // Validate any `properties` field types once, up front.
    if let Some(props) = body.get("properties").and_then(Value::as_object) {
        if let Some(refusal) = empty_field_name_refusal(props) {
            return refusal;
        }
        if let Err(reason) = validate_properties(props) {
            let e = xerj_common::XerjError::invalid_mapping(reason);
            return ApiError::new(e).into_response();
        }
        if let Err(reason) = validate_semantic_companion_targets(props) {
            let e = xerj_common::XerjError::invalid_mapping(reason);
            return ApiError::new(e).into_response();
        }
    }

    // Reject type changes on existing fields. ES disallows mutating a
    // field's `type` via put_mapping (the only exception is adding a
    // `fields:{}` multi-field under the same key, which keeps the root
    // type unchanged).
    if let Some(new_props) = body.get("properties").and_then(Value::as_object) {
        for idx_name in &targets {
            let mapping = match state.engine.index_mappings.get(idx_name) {
                Some(m) => m.clone(),
                None => continue,
            };
            let old_props_map: std::collections::HashMap<String, String> =
                collect_leaf_types(&mapping);
            for (key, val) in new_props {
                // Only inspect leaves (objects with a `type` field). A
                // non-leaf `{properties: {...}}` means sub-fields are
                // added without changing any root type.
                let new_type = val.get("type").and_then(Value::as_str);
                let Some(new_type) = new_type else { continue };
                if let Some(old_type) = old_props_map.get(key) {
                    if old_type != new_type {
                        let reason = format!(
                            "mapper [{}] cannot be changed from type [{}] to [{}]",
                            key, old_type, new_type
                        );
                        return (
                            StatusCode::BAD_REQUEST,
                            Json(json!({
                                "error": {
                                    "root_cause": [{
                                        "type": "illegal_argument_exception",
                                        "reason": reason,
                                    }],
                                    "type": "illegal_argument_exception",
                                    "reason": reason,
                                },
                                "status": 400,
                            })),
                        )
                            .into_response();
                    }
                    if new_type == "semantic_text" {
                        let old_definition = mapping
                            .get("properties")
                            .and_then(Value::as_object)
                            .and_then(|properties| properties.get(key))
                            .and_then(Value::as_object);
                        let new_definition = val.as_object();
                        if let (Some(old_definition), Some(new_definition)) =
                            (old_definition, new_definition)
                        {
                            let old_contract = semantic_mapping_contract(key, old_definition);
                            let new_contract = semantic_mapping_contract(key, new_definition);
                            if old_contract != new_contract {
                                let reason = format!(
                                    "semantic_text field [{key}] embedding contract cannot be \
                                     changed in place (target_field, dimensions, and similarity \
                                     are immutable); create a new field or reindex"
                                );
                                return (
                                    StatusCode::BAD_REQUEST,
                                    Json(json!({
                                        "error": {
                                            "root_cause": [{
                                                "type": "illegal_argument_exception",
                                                "reason": reason,
                                            }],
                                            "type": "illegal_argument_exception",
                                            "reason": reason,
                                        },
                                        "status": 400,
                                    })),
                                )
                                    .into_response();
                            }
                        }
                    }
                }
            }
        }
    }

    // Build and validate every target's complete candidate state before
    // publishing any schema or raw mapping. This prevents deterministic
    // wildcard/comma-list failures (for example, a later target's field
    // collision) from leaving earlier targets changed.
    let mut plans = Vec::with_capacity(targets.len());
    for idx_name in &targets {
        let idx = match state.engine.get_index(idx_name) {
            Ok(i) => i,
            Err(_) => continue,
        };
        // Merge the new properties into the stored mappings blob so
        // round-trip GET /_mapping reflects both create-time and
        // put_mapping-time field definitions. Dotted keys in the request
        // (e.g. `subfield.text3`) are expanded into a nested
        // `subfield: { properties: { text3: ... } }` tree, matching ES.
        let mut existing = state
            .engine
            .index_mappings
            .get(idx_name)
            .map(|v| v.clone())
            .unwrap_or(json!({}));
        if let Some(obj) = existing.as_object_mut() {
            if let Some(new_props) = body.get("properties").and_then(Value::as_object) {
                let merged_props = obj
                    .get("properties")
                    .and_then(Value::as_object)
                    .cloned()
                    .unwrap_or_default();
                let mut merged = serde_json::Map::new();
                for (k, v) in merged_props {
                    merged.insert(k, v);
                }
                for (raw_key, raw_val) in new_props {
                    merge_dotted_property(&mut merged, raw_key, raw_val);
                }
                obj.insert("properties".to_string(), Value::Object(merged));
            }
            if let Some(dyn_val) = body.get("dynamic") {
                obj.insert("dynamic".into(), dyn_val.clone());
            }
            if let Some(dd) = body.get("date_detection") {
                obj.insert("date_detection".into(), dd.clone());
            }
        } else {
            existing = body.clone();
        }

        // Semantic companion validation must see the complete post-update
        // mapping, not only this request. Otherwise a target declared by an
        // earlier request can collide with a newly added semantic source.
        if let Some(merged_props) = existing.get("properties").and_then(Value::as_object) {
            if let Err(reason) = validate_semantic_companion_targets(merged_props) {
                let e = xerj_common::XerjError::invalid_mapping(reason);
                return ApiError::new(e).into_response();
            }
        }

        let mut additions = Vec::new();
        if let Some(properties) = body.get("properties") {
            let current = idx.schema().await;
            let mut candidate = current.clone();
            // #275: refuse here too, and refuse in the plan phase — this loop
            // runs per target index, so an unimplemented `quantization` in a
            // multi-index `PUT _mapping` must abort before any of it is
            // published rather than after half of it took effect.
            let parsed = match es_properties_to_fields(properties) {
                Ok(parsed) => parsed,
                Err(reason) => {
                    let e = xerj_common::XerjError::invalid_mapping(reason);
                    return ApiError::new(e).into_response();
                }
            };
            for field in parsed {
                if let Some(existing_field) = current.field(&field.name) {
                    if existing_field.field_type != field.field_type {
                        let e = xerj_common::XerjError::invalid_mapping(format!(
                            "field [{}] already exists as [{}], cannot add [{}]",
                            field.name, existing_field.field_type, field.field_type
                        ));
                        return ApiError::new(e).into_response();
                    }
                    continue;
                }
                if let Err(error) = candidate.add_field(field.clone()) {
                    return ApiError::new(error).into_response();
                }
                additions.push(field);
            }
        }
        plans.push((idx_name.clone(), idx, existing, additions));
    }

    if state.engine.has_cluster() {
        for (idx_name, _, existing, additions) in plans {
            if let Err(error) = state
                .engine
                .replicate_mapping(&idx_name, &existing, &additions)
                .await
            {
                return ApiError::new(xerj_common::XerjError::from(error)).into_response();
            }
        }
        let warnings = embedder_warnings(&state, &body);
        let mut payload = json!({ "acknowledged": true });
        if !warnings.is_empty() {
            payload["warnings"] = json!(warnings);
        }
        return Json(payload).into_response();
    }

    // Publication begins only after every deterministic candidate has passed.
    // `add_fields` repeats engine-side validation defensively. Concurrent
    // schema evolution and filesystem failures still require a broader
    // engine-level multi-index transaction primitive; see the engineering
    // report for that explicitly tracked limitation.
    for (_, idx, _, additions) in &plans {
        if !additions.is_empty() {
            if let Err(error) = idx.add_fields(additions.clone()).await {
                return ApiError::new(xerj_common::XerjError::from(error)).into_response();
            }
        }
    }
    for (idx_name, _, existing, _) in plans {
        // Persists es_mapping.json into the index dir (atomic) so the
        // merged mapping survives a restart.
        if let Err(error) = state.engine.put_index_mapping(&idx_name, existing) {
            return ApiError::new(xerj_common::XerjError::from(error)).into_response();
        }
    }

    let warnings = embedder_warnings(&state, &body);
    let mut payload = json!({ "acknowledged": true });
    if !warnings.is_empty() {
        payload["warnings"] = json!(warnings);
    }
    Json(payload).into_response()
}

/// The server embedder a mapping's `inference_id` is compared with. Identity
/// failure yields no warning rather than a failed create: the mapping still
/// does not switch the embedder, and the index-open guard remains the hard
/// check.
fn embedder_warnings(state: &AppState, body: &Value) -> Vec<String> {
    let Ok(identity) = state.engine.embedding_execution_identity() else {
        return Vec::new();
    };
    let embedding = &state.engine.config().embedding;
    let resolved = crate::embed_warning::ResolvedEmbedder {
        backend: identity.backend,
        neural_model: embedding.neural_model.clone(),
        proxy_model: embedding.default_model.clone(),
        proxy_endpoint: embedding.default_endpoint.clone(),
    };
    crate::embed_warning::semantic_embedder_warnings(body, &resolved)
}

fn semantic_mapping_contract(
    field_name: &str,
    definition: &serde_json::Map<String, Value>,
) -> (String, u64, String) {
    let target = definition
        .get("target_field")
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| format!("{field_name}_vector"));
    let dimensions = definition
        .get("dimensions")
        .or_else(|| definition.get("dims"))
        .and_then(Value::as_u64)
        .unwrap_or(384);
    let similarity = definition
        .get("similarity")
        .and_then(Value::as_str)
        .unwrap_or("cosine")
        .to_string();
    (target, dimensions, similarity)
}

/// Walk a mapping blob's `properties` tree and build a flat map of
/// dotted-path → leaf type. Both literal-dotted keys (subobjects:false
/// leaves) and nested `{properties:{...}}` children are accommodated,
/// so later put_mapping calls can compare types regardless of the
/// shape the user originally chose.
fn collect_leaf_types(mapping: &Value) -> std::collections::HashMap<String, String> {
    fn walk(
        props: &serde_json::Map<String, Value>,
        prefix: &str,
        out: &mut std::collections::HashMap<String, String>,
    ) {
        for (key, val) in props {
            // Both literal-dotted keys and nested object shapes need
            // visiting — we recurse from either one.
            let full = if prefix.is_empty() {
                key.clone()
            } else {
                format!("{}.{}", prefix, key)
            };
            if let Some(ftype) = val.get("type").and_then(Value::as_str) {
                out.insert(full.clone(), ftype.to_string());
                // Also register the literal-dotted variant the user may
                // target from a new put_mapping call.
                if !key.contains('.') && !prefix.is_empty() {
                    out.insert(key.clone(), ftype.to_string());
                }
            }
            if let Some(child) = val.get("properties").and_then(Value::as_object) {
                walk(child, &full, out);
            }
        }
    }
    let mut out = std::collections::HashMap::new();
    let props = mapping
        .get("mappings")
        .and_then(|m| m.get("properties"))
        .or_else(|| mapping.get("properties"))
        .and_then(Value::as_object);
    if let Some(p) = props {
        walk(p, "", &mut out);
    }
    out
}

/// Insert a field definition into a `properties` map, respecting the
/// dotted-path shorthand: `foo.bar.baz → {type:text}` becomes
/// `{foo: {properties: {bar: {properties: {baz: {type:text}}}}}}`.
///
/// When a segment already exists it's merged in-place; leaf-level
/// property objects (e.g. `{type:text, analyzer:whitespace}`) replace
/// any previous value for the same path.
fn merge_dotted_property(
    properties: &mut serde_json::Map<String, Value>,
    dotted_key: &str,
    leaf_value: &Value,
) {
    let segments: Vec<&str> = dotted_key.split('.').collect();
    if segments.len() == 1 {
        properties.insert(dotted_key.to_string(), leaf_value.clone());
        return;
    }
    // Recurse: find / create the first segment's property object, then
    // descend through its `.properties` to the leaf.
    let first = segments[0];
    let rest = segments[1..].join(".");
    let entry = properties
        .entry(first.to_string())
        .or_insert_with(|| json!({ "properties": {} }));
    let entry_obj = match entry.as_object_mut() {
        Some(o) => o,
        None => {
            *entry = json!({ "properties": {} });
            entry.as_object_mut().unwrap()
        }
    };
    let sub = entry_obj
        .entry("properties".to_string())
        .or_insert_with(|| Value::Object(serde_json::Map::new()));
    let sub_obj = match sub.as_object_mut() {
        Some(o) => o,
        None => {
            *sub = Value::Object(serde_json::Map::new());
            sub.as_object_mut().unwrap()
        }
    };
    merge_dotted_property(sub_obj, &rest, leaf_value);
}

/// Merge a stored (explicit, cached-at-index-creation) mapping's
/// `properties` with the live schema-derived `properties`
/// (`schema_to_es_properties`).
///
/// The stored declaration wins for any field it names -- it may carry
/// explicit settings (`ignore_above`, `analyzer`, `dense_vector` options,
/// ...) the schema's own type inference wouldn't reconstruct identically.
/// But a field the live schema knows about and the stored blob doesn't is
/// still included, instead of being permanently invisible: without this,
/// GET _mapping/_field_caps serve the ORIGINAL index-creation-time blob
/// forever, and any field discovered dynamically since -- flat or nested,
/// at any depth -- never appears in either, no matter how long the index
/// has been receiving new documents.
///
/// Recurses into whichever nested-children key each side actually uses
/// (`properties` for Object/Nested, `fields` for a leaf's multi-fields),
/// so a field explicitly declared without its own nested declaration
/// (e.g. a bare `{"type": "object"}`) still picks up children discovered
/// dynamically since, rather than only ever getting top-level treatment.
fn merge_mapping_properties(
    stored_properties: &serde_json::Map<String, Value>,
    live_properties: &serde_json::Map<String, Value>,
) -> serde_json::Map<String, Value> {
    let mut merged = stored_properties.clone();
    for (key, live_val) in live_properties {
        match merged.get_mut(key) {
            None => {
                merged.insert(key.clone(), live_val.clone());
            }
            Some(stored_val) => {
                for children_key in ["properties", "fields"] {
                    let Some(live_children) =
                        live_val.get(children_key).and_then(|v| v.as_object())
                    else {
                        continue;
                    };
                    let stored_children = stored_val
                        .get(children_key)
                        .and_then(|v| v.as_object())
                        .cloned()
                        .unwrap_or_default();
                    let merged_children = merge_mapping_properties(&stored_children, live_children);
                    if let Some(obj) = stored_val.as_object_mut() {
                        obj.insert(children_key.to_string(), Value::Object(merged_children));
                    }
                }
            }
        }
    }
    merged
}

/// Companion `dense_vector` fields the engine auto-creates for each
/// `semantic_text` field (e.g. `body` -> `body_vector`, or `target_field`
/// if the caller declared one) are an implementation detail, never meant
/// to be user-visible -- nothing in the caller's own mapping ever names
/// them. Once a document makes the live schema aware of a companion field,
/// `merge_mapping_properties` above would otherwise happily surface it in
/// `GET _mapping`/`_field_caps`, even though it was never declared under
/// that name by anyone. Scans `stored_properties` (the only place a
/// `semantic_text` field can legitimately be declared -- dynamic mapping
/// never infers that type) for each one and returns the companion name
/// `semantic_mapping_contract` computes for it, so callers can filter
/// those out of what they feed into `merge_mapping_properties`.
fn semantic_companion_field_names(
    stored_properties: &serde_json::Map<String, Value>,
) -> HashSet<String> {
    stored_properties
        .iter()
        .filter_map(|(name, def)| {
            let obj = def.as_object()?;
            (obj.get("type").and_then(Value::as_str) == Some("semantic_text")).then(|| {
                let (target, _dimensions, _similarity) = semantic_mapping_contract(name, obj);
                target
            })
        })
        .collect()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}/_mapping
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_mapping_all(State(state): State<AppState>) -> impl IntoResponse {
    get_mapping(State(state), Path("_all".to_string())).await
}

pub async fn get_settings_all(State(state): State<AppState>) -> impl IntoResponse {
    get_settings(State(state), Path("_all".to_string())).await
}

/// ES `indices.get_mapping`: a concrete name that is not an index or an
/// alias is `404 index_not_found_exception`. A wildcard (including one that
/// matches nothing) is not this case — that stays the empty-target path,
/// same split `_cat/indices` already documents.
pub(crate) fn first_missing_concrete_name(
    spec: &str,
    known: impl Fn(&str) -> bool,
) -> Option<&str> {
    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if part == "_all" || part == "*" || part.contains('*') {
            continue;
        }
        if !known(part) {
            return Some(part);
        }
    }
    None
}

pub async fn get_mapping(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let names = state.engine.index_name_list();
    let failed = state.engine.list_failed_indices();
    if let Some(missing) = first_missing_concrete_name(&index, |part| {
        names.iter().any(|n| n == part)
            || failed.iter().any(|f| f.name == part)
            || state.engine.aliases.contains_key(part)
    }) {
        let e = xerj_common::XerjError::index_not_found(missing);
        return ApiError::new(e).into_response();
    }
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }
    let mut out = serde_json::Map::new();
    for name in &targets {
        // `None` = a failed index (issue #206): no open handle, but its
        // persisted mapping blob is still readable and is exactly what an
        // operator needs while recovering it. Only the schema-derived
        // fallback below requires a live index.
        let idx = match state.engine.get_index(name) {
            Ok(i) => Some(i),
            Err(_)
                if state
                    .engine
                    .list_failed_indices()
                    .iter()
                    .any(|f| &f.name == name) =>
            {
                None
            }
            Err(_) => continue,
        };
        let stored = state
            .engine
            .index_mappings
            .get(name)
            .map(|v| v.clone())
            .unwrap_or(Value::Null);
        let mut mappings = match (&idx, stored.is_null()) {
            (Some(i), true) => {
                let schema = i.schema().await;
                let properties = schema_to_es_properties(&schema);
                json!({ "properties": properties })
            }
            // A live index with a stored (explicit-at-creation) mapping:
            // merge in anything the live schema has picked up dynamically
            // since -- otherwise a field discovered after index creation
            // (flat or nested, at any depth) is permanently invisible here,
            // forever serving the exact blob index creation started with.
            (Some(i), false) => {
                let schema = i.schema().await;
                let mut live_properties = schema_to_es_properties(&schema);
                let stored_properties = stored
                    .get("properties")
                    .and_then(|p| p.as_object())
                    .cloned()
                    .unwrap_or_default();
                // semantic_text's own companion dense_vector fields are an
                // engine-internal implementation detail, never declared by
                // the caller under that name -- exclude them from what the
                // live schema contributes, same as they were never visible
                // before this merge existed (see semantic_companion_field_names).
                let companions = semantic_companion_field_names(&stored_properties);
                live_properties.retain(|k, _| !companions.contains(k));
                let merged = merge_mapping_properties(&stored_properties, &live_properties);
                let mut m = stored.clone();
                if let Some(obj) = m.as_object_mut() {
                    obj.insert("properties".to_string(), Value::Object(merged));
                }
                m
            }
            // No live index (failed index, #206) -- nothing to merge with,
            // serve whatever's recoverable as-is.
            (None, false) => stored,
            (None, true) => json!({ "properties": {} }),
        };
        // ES injects default `rescore_vector.oversample: 3.0` on any
        // dense_vector whose `index_options.type` is BBQ-quantised
        // (bbq_disk / bbq_hnsw / bbq_flat) when the user didn't set
        // one explicitly. Mirror that here at read time so
        // `indices.get_mapping` sees the defaulted value.
        inject_bbq_rescore_defaults(&mut mappings);
        out.insert(name.clone(), json!({ "mappings": mappings }));
    }
    Json(Value::Object(out)).into_response()
}

/// Walk a mapping node, locate every dense_vector whose
/// `index_options.type` names a BBQ quantisation family, and inject
/// `rescore_vector: {oversample: 3.0}` if absent. ES applies this at
/// read time as a default; replicate it so mapping GETs match.
fn inject_bbq_rescore_defaults(node: &mut Value) {
    let is_bbq = |t: Option<&str>| -> bool {
        matches!(t, Some("bbq_disk") | Some("bbq_hnsw") | Some("bbq_flat"))
    };
    match node {
        Value::Object(obj) => {
            let has_type = obj.get("type").and_then(Value::as_str) == Some("dense_vector");
            if has_type {
                let bbq = obj
                    .get("index_options")
                    .and_then(|io| io.get("type"))
                    .and_then(Value::as_str);
                if is_bbq(bbq) {
                    let io = obj
                        .entry("index_options".to_string())
                        .or_insert_with(|| json!({}));
                    if let Some(io_obj) = io.as_object_mut() {
                        if !io_obj.contains_key("rescore_vector") {
                            io_obj
                                .insert("rescore_vector".to_string(), json!({ "oversample": 3.0 }));
                        }
                    }
                }
            }
            for (_k, v) in obj.iter_mut() {
                inject_bbq_rescore_defaults(v);
            }
        }
        Value::Array(arr) => {
            for item in arr.iter_mut() {
                inject_bbq_rescore_defaults(item);
            }
        }
        _ => {}
    }
}

#[cfg(test)]
mod get_mapping_missing_index {
    use super::*;
    use axum::body::{to_bytes, Body};
    use axum::http::Request;
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    #[test]
    fn a_concrete_missing_name_is_reported_and_a_wildcard_is_not() {
        let known = |p: &str| p == "logs" || p == "metrics";
        assert_eq!(first_missing_concrete_name("nope", known), Some("nope"));
        assert_eq!(first_missing_concrete_name("logs", known), None);
        assert_eq!(
            first_missing_concrete_name("logs,nope", known),
            Some("nope")
        );
        // A wildcard that matches nothing is not a concrete miss. The empty
        // result stays on the existing path so the YAML suite's wildcard
        // cases are unchanged.
        assert_eq!(first_missing_concrete_name("nope*", known), None);
        assert_eq!(first_missing_concrete_name("_all", known), None);
        assert_eq!(first_missing_concrete_name("*", known), None);
        assert_eq!(first_missing_concrete_name("logs*", known), None);
    }

    /// ES `indices.get_mapping`: `GET /nope/_mapping` is 404, not 200 `{}`.
    /// A name that exists still returns its mapping. A wildcard is not this
    /// check — `nope*` stays on the empty-target path.
    #[tokio::test]
    async fn get_mapping_404s_a_concrete_missing_name_and_returns_a_real_one() {
        let state = test_state();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("body", FieldType::Text));
        state.engine.create_index("logs", schema).unwrap();
        let router = crate::router::build_es_compat_router(state);

        let missing = router
            .clone()
            .oneshot(Request::get("/nope/_mapping").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(missing.status(), StatusCode::NOT_FOUND);
        let bytes = to_bytes(missing.into_body(), usize::MAX).await.unwrap();
        let json: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(json["error"]["type"], "index_not_found_exception");
        assert_eq!(json["error"]["reason"], "no such index [nope]");

        let mixed = router
            .clone()
            .oneshot(
                Request::get("/logs,nope/_mapping")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(mixed.status(), StatusCode::NOT_FOUND);

        let found = router
            .clone()
            .oneshot(Request::get("/logs/_mapping").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(found.status(), StatusCode::OK);
        let bytes = to_bytes(found.into_body(), usize::MAX).await.unwrap();
        let json: Value = serde_json::from_slice(&bytes).unwrap();
        assert!(json.get("logs").is_some(), "{json}");

        // Wildcard miss is not rewritten by the concrete check. Empty targets
        // already 404; this pins that the new branch did not turn it into 200.
        let wild = router
            .oneshot(Request::get("/nope*/_mapping").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(wild.status(), StatusCode::NOT_FOUND);
    }
}

