pub async fn get_settings(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }
    let mut out = serde_json::Map::new();
    for name in &targets {
        let idx = state.engine.get_index(name).ok();
        let settings = index_settings_response(&state, name, idx.as_ref(), false).await;
        out.insert(name.clone(), json!({ "settings": settings }));
    }
    Json(Value::Object(out)).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_doc
// ─────────────────────────────────────────────────────────────────────────────

/// Query parameters for the auto-ID index endpoint.
#[derive(Debug, Default, Deserialize)]
pub struct IndexDocAutoParams {
    /// `refresh=true|wait_for` — accepted without error; memtable is always visible.
    pub refresh: Option<String>,
    /// `pipeline=my_pipeline` — ingest pipeline to run before indexing.
    /// `_none` disables the index's `default_pipeline`; absent falls back to it.
    pub pipeline: Option<String>,
}

/// Resolve the effective ingest pipeline for a single-doc write.
///
/// Mirrors Elasticsearch `index.default_pipeline` semantics:
/// - `Some("_none")` → `None` (explicit opt-out; no pipeline runs).
/// - `Some(name)`    → that pipeline (an explicit `?pipeline=` always wins).
/// - `None`          → the index's `index.default_pipeline` setting, if any.
///
/// The default is read by [`xerj_engine::Engine::default_pipeline_for`], which
/// `_bulk` also uses — one lookup, so the two forms of the same write cannot
/// disagree about which pipeline applies.
fn resolve_effective_pipeline(
    state: &AppState,
    index: &str,
    explicit: Option<&str>,
) -> Option<String> {
    match explicit {
        Some("_none") => None,
        Some(p) => Some(p.to_string()),
        None => state.engine.default_pipeline_for(index),
    }
}

/// Parse one indexed document from raw bytes.
///
/// The size check runs before `serde_json`. `PUT /{index}/_doc/{id}` used
/// to take `Json<Value>`, which builds the DOM inside axum before the
/// handler runs. A body between the 8 MiB document ceiling and
/// `limits.max_body_bytes` (100 MiB) was parsed, then refused, and the
/// parse itself is what aborted the node under a memory cap (#1122).
/// Bytes that are not valid JSON and are also over the ceiling report the
/// size refusal, not a parse error — that is how a test can see the check
/// ran first.
pub(crate) fn parse_indexed_document_body(body: &[u8]) -> Result<Value, xerj_common::XerjError> {
    if xerj_common::document_limit::indexed_document_too_large(body.len()) {
        return Err(xerj_common::XerjError::invalid_document_json(
            xerj_common::document_limit::indexed_document_refusal(body.len()),
        ));
    }
    serde_json::from_slice(body)
        .map_err(|e| xerj_common::XerjError::invalid_query(format!("invalid JSON body: {e}")))
}

/// Serialize a document the in-process callers already hold as a [`Value`]
/// into the raw body [`index_doc`] parses. Those callers (brain edges,
/// agent memory) are small; the HTTP routes pass the request bytes through
/// unchanged.
pub(crate) fn document_body(doc: &Value) -> bytes::Bytes {
    bytes::Bytes::from(serde_json::to_vec(doc).unwrap_or_else(|_| Vec::from(&b"{}"[..])))
}

/// Fast path for `POST /{index}/_doc`: receives raw bytes to skip the axum
/// JSON extractor's extra validation pass and parse directly with simd_json /
/// serde_json.  No schema validation is performed here; the engine layer handles
/// all type coercion.  This shaves ~15–30 µs of extractor overhead per doc.
/// Resolve an alias to the concrete index a document write must land in.
/// A concrete name (or a name that will be auto-created) is returned
/// unchanged; an ambiguous alias becomes ES's 400
/// `illegal_argument_exception` instead of silently using the first backing
/// index (`GET /{index}` does resolve aliases that way, but a write may not).
fn write_target_or_refusal(
    state: &AppState,
    index: &str,
) -> std::result::Result<String, axum::response::Response> {
    match state.engine.write_target(index) {
        Ok(Some(target)) => Ok(target),
        Ok(None) => Ok(index.to_string()),
        Err(reason) => Err(es_bad_request("illegal_argument_exception", &reason, None)),
    }
}

pub async fn index_doc_auto(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<IndexDocAutoParams>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    let doc = match parse_indexed_document_body(&body) {
        Ok(v) => v,
        Err(e) => return ApiError::new(e).into_response(),
    };

    let doc = apply_ignore_malformed(&state, &index, doc);

    // Range-type + copy_to rejection. ES accepts the mapping at
    // create time but fails the first doc that actually references
    // the range field, since copy_to on a range is meaningless
    // (ES: "Copy-to currently only works for value-type fields").
    if let Some(range_field) = first_range_copy_to_field_in_mapping(&state, &index, doc.as_object())
    {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "error": {
                    "type": "document_parsing_exception",
                    "reason": format!(
                        "failed to parse field [{}]: Copy-to currently only works for value-type fields, not ranges",
                        range_field
                    )
                },
                "status": 400
            }))
        ).into_response();
    }

    // Apply dynamic-template `copy_to` at ingest (single-doc path).
    // Bulk performs this in `bulk.rs`; the _doc endpoints get the
    // same materialisation so the stored source carries the copy
    // target's value before search time.
    let doc = {
        let mut d = doc;
        if let Some(obj) = d.as_object_mut() {
            let mapping = state.engine.index_mappings.get(&index).map(|v| v.clone());
            xerj_engine::bulk::apply_dynamic_template_copy_to_public(obj, mapping.as_ref());
        }
        d
    };

    // Execute ingest pipeline if one is specified (explicit `?pipeline=`) or
    // resolved from the index's `index.default_pipeline` setting.
    let effective_pipeline = resolve_effective_pipeline(&state, &index, params.pipeline.as_deref());
    let doc = if let Some(ref pipeline) = effective_pipeline {
        match state.engine.process_through_pipeline(pipeline, vec![doc]) {
            Ok(mut results) if !results.is_empty() => {
                let (action, transformed) = results.remove(0);
                if matches!(action, xerj_wasm::pipeline::ProcessAction::Drop) {
                    return Json(json!({"result": "noop", "_id": "", "_version": 0}))
                        .into_response();
                }
                transformed
            }
            // No output for this document: refused, not passed through
            // unchanged — see `pipeline_empty_result_error`.
            Ok(_) => return pipeline_empty_result_error(pipeline).into_response(),
            // Issue #204, the purest form of the class on a user-DATA path:
            // this used to warn and then index the ORIGINAL document. A
            // pipeline whose job was to redact PII, drop a field or route the
            // document simply did not run, and the caller got `201 Created`.
            // `_bulk` already fails the item here; the single-document path now
            // agrees with it.
            Err(e) => return pipeline_execution_error(pipeline, &e).into_response(),
        }
    } else {
        doc
    };

    // Declared numeric/boolean types are enforced after the pipeline has run,
    // so a pipeline-produced value is held to the same rules as a caller's.
    let doc = match enforce_field_types(&state, &index, "", doc) {
        Ok(d) => d,
        Err(resp) => return resp,
    };

    // Cluster mode picks the id before routing so the shard owner is a
    // function of the id that will be stored. Single-node keeps the engine's
    // auto-id.
    let preset_id = if state.engine.has_cluster() {
        let id = uuid::Uuid::new_v4().to_string();
        match crate::cluster_shard::dispatch_index(
            &state, &index, &id, &doc, "index", None, None, None, None,
        )
        .await
        {
            crate::cluster_shard::Dispatch::Done(response) => return response,
            crate::cluster_shard::Dispatch::Local => Some(id),
        }
    } else {
        None
    };

    let idx = if preset_id.is_some() {
        match state.engine.get_index(&index) {
            Ok(i) => i,
            Err(_) => return crate::cluster_shard::shard_not_ready_response(&index),
        }
    } else {
        match state.engine.get_or_create_index(&index) {
            Ok(i) => i,
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    };

    match idx.index_document(preset_id, doc).await {
        Ok(resp) => {
            state.metrics.record_doc_indexed(&index);
            let er = EsDocResponse::created(
                &index,
                &resp.id,
                resp.version,
                resp.seq_no.saturating_sub(1),
            );
            (StatusCode::CREATED, Json(er)).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT /{index}/_doc/{id}
// ─────────────────────────────────────────────────────────────────────────────

/// Query parameters for the index document endpoint.
#[derive(Debug, Default, Deserialize)]
pub struct IndexDocParams {
    /// Optimistic concurrency: expected sequence number.
    pub if_seq_no: Option<u64>,
    /// Optimistic concurrency: expected primary term (must accompany if_seq_no).
    pub if_primary_term: Option<u64>,
    /// `op_type=create` — fail with 409 if the document already exists.
    pub op_type: Option<String>,
    /// `refresh=true|wait_for` — accepted without error; memtable is always visible.
    pub refresh: Option<String>,
    /// `pipeline=my_pipeline` — ingest pipeline to run before indexing.
    /// `_none` disables the index's `default_pipeline`; absent falls back to it.
    pub pipeline: Option<String>,
    /// `routing=X` — routing metadata stored on the document (surfaces
    /// as `_routing` under `fields`/`exists` queries).
    pub routing: Option<String>,
    /// External version control: `version=N` is the caller-supplied
    /// `_version` to enforce with `version_type=external[_gte]`.
    pub version: Option<u64>,
    pub version_type: Option<String>,
}

pub async fn index_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
    Query(params): Query<IndexDocParams>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    // Size check before the DOM exists. See [`parse_indexed_document_body`].
    let doc = match parse_indexed_document_body(&body) {
        Ok(v) => v,
        Err(e) => return ApiError::new(e).into_response(),
    };
    // Apply ignore_malformed validation — remove malformed values and add
    // field names to _ignored[] per the index mapping. No-op when the index
    // has no mapping yet.
    let doc = apply_ignore_malformed(&state, &index, doc);
    // Range-type + copy_to rejection — see index_doc_auto for
    // context.
    if let Some(range_field) = first_range_copy_to_field_in_mapping(&state, &index, doc.as_object())
    {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "error": {
                    "type": "document_parsing_exception",
                    "reason": format!(
                        "failed to parse field [{}]: Copy-to currently only works for value-type fields, not ranges",
                        range_field
                    )
                },
                "status": 400
            }))
        ).into_response();
    }
    // Apply dynamic-template `copy_to` at ingest — see index_doc_auto
    // for the rationale (the stored source must carry the copy's
    // value because search-time `apply_copy_to` walks the declared
    // schema only).
    let doc = {
        let mut d = doc;
        if let Some(obj) = d.as_object_mut() {
            let mapping = state.engine.index_mappings.get(&index).map(|v| v.clone());
            xerj_engine::bulk::apply_dynamic_template_copy_to_public(obj, mapping.as_ref());
        }
        d
    };
    // Persist the `?routing=X` URL parameter onto the document as
    // `_routing`. The engine treats `_routing` as queryable metadata so
    // `exists: _routing` and `fields: [_routing]` resolve correctly.
    let doc = if let Some(r) = params.routing.as_deref() {
        let mut v = doc;
        if let Some(obj) = v.as_object_mut() {
            obj.insert("_routing".to_string(), Value::String(r.to_string()));
        }
        v
    } else {
        doc
    };
    // Execute ingest pipeline if one is specified (explicit `?pipeline=`) or
    // resolved from the index's `index.default_pipeline` setting.
    let effective_pipeline = resolve_effective_pipeline(&state, &index, params.pipeline.as_deref());
    let doc = if let Some(ref pipeline) = effective_pipeline {
        match state
            .engine
            .process_through_pipeline(pipeline, vec![doc.clone()])
        {
            Ok(mut results) if !results.is_empty() => {
                let (action, transformed) = results.remove(0);
                if matches!(action, xerj_wasm::pipeline::ProcessAction::Drop) {
                    return Json(json!({"result": "noop", "_id": id, "_version": 0}))
                        .into_response();
                }
                transformed
            }
            // No output for this document: refused, not passed through
            // unchanged — see `pipeline_empty_result_error`.
            Ok(_) => return pipeline_empty_result_error(pipeline).into_response(),
            // Issue #204: this arm was folded into `_ => doc`, so a pipeline
            // that could not run left the document indexed UNTRANSFORMED under
            // a success response. Refuse instead.
            Err(e) => return pipeline_execution_error(pipeline, &e).into_response(),
        }
    } else {
        doc
    };
    // ?refresh=true|wait_for — accepted silently; memtable is immediately visible.

    // Declared numeric/boolean types are enforced after the pipeline has run,
    // so a pipeline-produced value is held to the same rules as a caller's.
    let doc = match enforce_field_types(&state, &index, &id, doc) {
        Ok(d) => d,
        Err(resp) => return resp,
    };

    // op_type=create means fail if document already exists.
    let is_create_op = params.op_type.as_deref() == Some("create");

    // The wire (ES) numbers seq_no from 0; the internal WAL counter from 1.
    // `if_seq_no` arrives in ES form → +1 before the engine CAS compare
    // (which runs on internal seqs), so a value read from GET/_search/_mget
    // or a previous write response round-trips correctly.
    let if_seq_no_internal = params.if_seq_no.map(|s| s.saturating_add(1));

    if state.engine.has_cluster() {
        match crate::cluster_shard::dispatch_index(
            &state,
            &index,
            &id,
            &doc,
            if is_create_op { "create" } else { "index" },
            if_seq_no_internal,
            params.if_primary_term,
            params.version,
            params.version_type.clone(),
        )
        .await
        {
            crate::cluster_shard::Dispatch::Done(response) => return response,
            crate::cluster_shard::Dispatch::Local => {}
        }
    }

    let idx = if state.engine.has_cluster() {
        match state.engine.get_index(&index) {
            Ok(i) => i,
            Err(_) => return crate::cluster_shard::shard_not_ready_response(&index),
        }
    } else {
        match state.engine.get_or_create_index(&index) {
            Ok(i) => i,
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    };

    if is_create_op {
        match idx.create_document(id.clone(), doc).await {
            Ok(resp) => {
                state.metrics.record_doc_indexed(&index);
                let er = EsDocResponse::created(
                    &index,
                    &resp.id,
                    resp.version,
                    resp.seq_no.saturating_sub(1),
                );
                (StatusCode::CREATED, Json(er)).into_response()
            }
            Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    } else {
        let ext_type = params.version_type.as_deref();
        let result = if let (Some(v), Some(vt)) = (params.version, ext_type) {
            if vt == "external" || vt == "external_gte" {
                idx.index_document_external(Some(id.clone()), doc, v, vt)
                    .await
            } else {
                idx.index_document_with_version(
                    Some(id.clone()),
                    doc,
                    if_seq_no_internal,
                    params.if_primary_term,
                )
                .await
            }
        } else {
            idx.index_document_with_version(
                Some(id.clone()),
                doc,
                if_seq_no_internal,
                params.if_primary_term,
            )
            .await
        };
        match result {
            Ok(resp) => {
                state.metrics.record_doc_indexed(&index);
                let is_update = resp.result == "updated";
                let wire_seq = resp.seq_no.saturating_sub(1);
                let (er, status) = if is_update {
                    (
                        EsDocResponse::updated(&index, &resp.id, resp.version, wire_seq),
                        StatusCode::OK,
                    )
                } else {
                    (
                        EsDocResponse::created(&index, &resp.id, resp.version, wire_seq),
                        StatusCode::CREATED,
                    )
                };
                (status, Json(er)).into_response()
            }
            Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT /{index}/_create/{id}
// ─────────────────────────────────────────────────────────────────────────────

/// Query parameters for the `_create` endpoint.
#[derive(Debug, Default, Deserialize)]
pub struct CreateDocParams {
    /// `refresh=true|wait_for` — accepted without error; memtable is always visible.
    pub refresh: Option<String>,
    /// `pipeline=my_pipeline` — ingest pipeline to run before indexing.
    /// `_none` disables the index's `default_pipeline`; absent falls back to it.
    pub pipeline: Option<String>,
}

/// `PUT /{index}/_create/{id}` — identical to `PUT /{index}/_doc/{id}?op_type=create`.
///
/// Returns 409 Conflict if a document with the given ID already exists.
pub async fn create_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
    Query(params): Query<CreateDocParams>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    let doc = match parse_indexed_document_body(&body) {
        Ok(v) => v,
        Err(e) => return ApiError::new(e).into_response(),
    };
    // Execute ingest pipeline if one is specified (explicit `?pipeline=`) or
    // resolved from the index's `index.default_pipeline` setting.
    let effective_pipeline = resolve_effective_pipeline(&state, &index, params.pipeline.as_deref());
    let doc = if let Some(ref pipeline) = effective_pipeline {
        match state
            .engine
            .process_through_pipeline(pipeline, vec![doc.clone()])
        {
            Ok(mut results) if !results.is_empty() => {
                let (action, transformed) = results.remove(0);
                if matches!(action, xerj_wasm::pipeline::ProcessAction::Drop) {
                    return Json(json!({"result": "noop", "_id": id, "_version": 0}))
                        .into_response();
                }
                transformed
            }
            // No output for this document: refused, not passed through
            // unchanged — see `pipeline_empty_result_error`.
            Ok(_) => return pipeline_empty_result_error(pipeline).into_response(),
            // Issue #204: this arm was folded into `_ => doc`, so a pipeline
            // that could not run left the document indexed UNTRANSFORMED under
            // a success response. Refuse instead.
            Err(e) => return pipeline_execution_error(pipeline, &e).into_response(),
        }
    } else {
        doc
    };

    // `_create` skipped every mapping-aware validation stage; the declared
    // numeric/boolean types are now enforced here too (issue #781).
    let doc = match enforce_field_types(&state, &index, &id, doc) {
        Ok(d) => d,
        Err(resp) => return resp,
    };

    if state.engine.has_cluster() {
        match crate::cluster_shard::dispatch_index(
            &state, &index, &id, &doc, "create", None, None, None, None,
        )
        .await
        {
            crate::cluster_shard::Dispatch::Done(response) => return response,
            crate::cluster_shard::Dispatch::Local => {}
        }
    }

    let idx = if state.engine.has_cluster() {
        match state.engine.get_index(&index) {
            Ok(i) => i,
            Err(_) => return crate::cluster_shard::shard_not_ready_response(&index),
        }
    } else {
        match state.engine.get_or_create_index(&index) {
            Ok(i) => i,
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    };

    match idx.create_document(id.clone(), doc).await {
        Ok(resp) => {
            state.metrics.record_doc_indexed(&index);
            let er = EsDocResponse::created(
                &index,
                &resp.id,
                resp.version,
                resp.seq_no.saturating_sub(1),
            );
            (StatusCode::CREATED, Json(er)).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

#[cfg(test)]
mod oversized_single_doc {
    use super::*;
    use axum::body::{to_bytes, Body};
    use axum::http::Request;
    use tower::ServiceExt;
    use xerj_common::config::{Config, WalSync};
    use xerj_common::document_limit::MAX_INDEXED_DOCUMENT_BYTES;
    use xerj_common::metrics::Metrics;
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    #[test]
    fn an_oversized_body_is_refused_before_it_is_parsed() {
        let body = vec![b'x'; MAX_INDEXED_DOCUMENT_BYTES + 1];
        let err = parse_indexed_document_body(&body).unwrap_err();
        let text = err.to_string();
        assert!(
            text.contains(&MAX_INDEXED_DOCUMENT_BYTES.to_string()),
            "{text}"
        );
        assert!(text.contains("not indexed"), "{text}");
        assert!(
            !text.contains("invalid JSON"),
            "the size check must run before parse: {text}"
        );
        let small = parse_indexed_document_body(br#"{"name":"ada"}"#).unwrap();
        assert_eq!(small["name"], "ada");
    }

    #[tokio::test]
    async fn put_and_create_refuse_an_oversized_body_and_a_small_put_indexes() {
        let app = crate::router::build_es_compat_router(test_state());
        let body = vec![b'x'; MAX_INDEXED_DOCUMENT_BYTES + 1];
        for path in ["/oversize/_doc/1", "/oversize/_create/1"] {
            let response = app
                .clone()
                .oneshot(
                    Request::put(path)
                        .header("content-type", "application/json")
                        .body(Body::from(body.clone()))
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::BAD_REQUEST, "{path}");
            let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
            let text = String::from_utf8(bytes.to_vec()).unwrap();
            assert!(
                text.contains(&MAX_INDEXED_DOCUMENT_BYTES.to_string()),
                "{path}: {text}"
            );
            assert!(text.contains("not indexed"), "{path}: {text}");
            assert!(
                !text.contains("invalid JSON"),
                "{path} parsed before the size check: {text}"
            );
        }

        let response = app
            .oneshot(
                Request::put("/oversize/_doc/ok")
                    .header("content-type", "application/json")
                    .body(Body::from(r#"{"name":"ada"}"#))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CREATED);
    }
}

#[cfg(test)]
mod oversized_update {
    use super::*;
    use axum::body::{to_bytes, Body};
    use axum::http::Request;
    use tower::ServiceExt;
    use xerj_common::config::{Config, WalSync};
    use xerj_common::document_limit::MAX_UPDATE_BODY_BYTES;
    use xerj_common::metrics::Metrics;
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    #[test]
    fn an_oversized_update_body_is_refused_before_it_is_parsed() {
        let body = vec![b'x'; MAX_UPDATE_BODY_BYTES + 1];
        let err = parse_update_body(&body).unwrap_err();
        let text = err.to_string();
        assert!(text.contains(&MAX_UPDATE_BODY_BYTES.to_string()), "{text}");
        assert!(text.contains("not parsed"), "{text}");
        assert!(text.contains("not changed"), "{text}");
        assert!(
            !text.contains("invalid JSON"),
            "the size check must run before parse: {text}"
        );
        let small = parse_update_body(br#"{"doc":{"name":"ada"}}"#).unwrap();
        assert_eq!(small.doc.unwrap()["name"], "ada");
    }

    #[tokio::test]
    async fn post_update_refuses_an_oversized_body_and_a_small_update_applies() {
        let app = crate::router::build_es_compat_router(test_state());
        let created = app
            .clone()
            .oneshot(
                Request::put("/upd/_doc/1")
                    .header("content-type", "application/json")
                    .body(Body::from(r#"{"name":"ada","n":1}"#))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(created.status(), StatusCode::CREATED);

        // Valid JSON, over the envelope. A parse-first path would accept
        // the syntax and answer with the document ceiling (or index it).
        // The size refusal names the update limit and does not say the
        // body was invalid JSON.
        let mut big = Vec::new();
        big.extend_from_slice(br#"{"doc":{"blob":""#);
        big.extend(std::iter::repeat_n(b'a', MAX_UPDATE_BODY_BYTES));
        big.extend_from_slice(br#""}}"#);
        let refused = app
            .clone()
            .oneshot(
                Request::post("/upd/_update/1")
                    .header("content-type", "application/json")
                    .body(Body::from(big))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(refused.status(), StatusCode::BAD_REQUEST);
        let bytes = to_bytes(refused.into_body(), usize::MAX).await.unwrap();
        let text = String::from_utf8(bytes.to_vec()).unwrap();
        assert!(text.contains(&MAX_UPDATE_BODY_BYTES.to_string()), "{text}");
        assert!(text.contains("not parsed"), "{text}");
        assert!(text.contains("not changed"), "{text}");
        assert!(
            !text.contains("invalid JSON"),
            "parsed before the size check: {text}"
        );

        let fetched = app
            .clone()
            .oneshot(Request::get("/upd/_doc/1").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(fetched.status(), StatusCode::OK);
        let bytes = to_bytes(fetched.into_body(), usize::MAX).await.unwrap();
        let doc: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(doc["_source"]["name"], json!("ada"));
        assert_eq!(doc["_source"]["n"], json!(1));

        let updated = app
            .clone()
            .oneshot(
                Request::post("/upd/_update/1")
                    .header("content-type", "application/json")
                    .body(Body::from(r#"{"doc":{"name":"ada2"}}"#))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(updated.status(), StatusCode::OK);

        let fetched = app
            .oneshot(Request::get("/upd/_doc/1").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(fetched.status(), StatusCode::OK);
        let bytes = to_bytes(fetched.into_body(), usize::MAX).await.unwrap();
        let doc: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(doc["_source"]["name"], json!("ada2"));
        assert_eq!(
            doc["_source"]["n"],
            json!(1),
            "fields the update did not name stay"
        );
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}/_doc/{id}?_source_includes=f1,f2&_source_excludes=f3
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Default, Deserialize)]
pub struct GetDocParams {
    /// Comma-separated list of fields to include in _source.
    #[serde(rename = "_source_includes")]
    pub source_includes: Option<String>,
    /// Comma-separated list of fields to exclude from _source.
    #[serde(rename = "_source_excludes")]
    pub source_excludes: Option<String>,
    /// Shorthand: `_source=false` suppresses source entirely.
    #[serde(rename = "_source")]
    pub source: Option<String>,
}

pub async fn get_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
    Query(params): Query<GetDocParams>,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    // A closed index rejects read/search ops with ES index_closed_exception.
    // Strict membership only — frozen/open indices are unaffected.
    if state.engine.closed_indices.contains_key(&index) {
        return closed_index_error(&index);
    }

    if let crate::cluster_shard::Dispatch::Done(response) =
        crate::cluster_shard::dispatch_get(&state, &index, &id, &params).await
    {
        return response;
    }

    let idx = match state.engine.get_index(&index) {
        Ok(i) => i,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    match idx.get_document(&id).await {
        Ok(Some(mut source)) => {
            xerj_query::executor::strip_internal_passage_metadata(&mut source);
            // Apply _source filtering based on query params.
            let filtered = apply_get_doc_source_filter(source, &params);
            // Real per-doc metadata (was hardcoded `_version: 1` /
            // `_seq_no: 1`, which broke read-then-CAS flows): same
            // resolvers `_mget` and `_search` hits use. `lookup_seq_no`
            // yields the ES wire form (0-based); `lookup_version` prefers
            // an external version when one was supplied.
            let version = idx.lookup_version(&id).unwrap_or(1);
            let seq_no = idx.lookup_seq_no(&id).unwrap_or(0);
            let resp = EsGetResponse::found(&index, &id, version, seq_no, filtered);
            // A blind usability run fetched a whole source file this way and
            // paid 3.17 MB for one function: `GET /_doc/{id}` is where an agent
            // lands once search has told it *which* document it wants, and it
            // had no way to learn a cheaper route existed. Same size-triggered
            // hint as `_search`, emitted before the payload so it survives
            // output truncation.
            match serde_json::to_value(&resp) {
                Ok(Value::Object(map)) => {
                    let doc_bytes = map
                        .get("_source")
                        .map(|s| serde_json::to_string(s).map(|s| s.len()).unwrap_or(0))
                        .unwrap_or(0);
                    if doc_bytes > LARGE_RESPONSE_HINT_THRESHOLD_BYTES {
                        let mut out = serde_json::Map::new();
                        out.insert("_xerj".into(), get_doc_response_hint(&index, doc_bytes));
                        out.extend(map);
                        return Json(Value::Object(out)).into_response();
                    }
                    Json(Value::Object(map)).into_response()
                }
                _ => Json(resp).into_response(),
            }
        }
        Ok(None) => {
            let resp = EsGetResponse::not_found(&index, &id);
            (StatusCode::NOT_FOUND, Json(resp)).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

/// Filter the _source of a GET _doc response based on query params.
pub(crate) fn apply_get_doc_source_filter(source: Value, params: &GetDocParams) -> Value {
    // _source=false → suppress everything.
    if params.source.as_deref() == Some("false") {
        return Value::Null;
    }

    let includes: Vec<String> = params
        .source_includes
        .as_deref()
        .map(|s| s.split(',').map(str::trim).map(String::from).collect())
        .unwrap_or_default();

    let excludes: Vec<String> = params
        .source_excludes
        .as_deref()
        .map(|s| s.split(',').map(str::trim).map(String::from).collect())
        .unwrap_or_default();

    if includes.is_empty() && excludes.is_empty() {
        return source;
    }

    // Project through the SAME faithful ES `_source` automaton the search path
    // uses (`xerj_engine::filter_object`), so dotted/nested includes+excludes
    // and `*` globs behave identically. The old local top-level-only filter
    // dropped nested includes entirely and no-oped nested excludes (#850).
    xerj_engine::filter_object(&source, &includes, &excludes)
}

#[cfg(test)]
mod get_doc_source_filter_tests {
    use super::*;
    use serde_json::json;

    // #850: GET /_doc `_source_includes`/`_source_excludes` must support
    // dotted/nested paths (and `*` globs), like search — the old top-level-only
    // filter dropped a nested include entirely and no-oped a nested exclude.
    #[test]
    fn get_doc_source_filter_handles_nested_paths() {
        let src = || json!({ "user": { "name": "x", "age": 5 }, "id": 1 });

        // Nested include keeps only the requested leaf under its parent.
        let inc = apply_get_doc_source_filter(
            src(),
            &GetDocParams {
                source_includes: Some("user.name".into()),
                ..Default::default()
            },
        );
        assert_eq!(inc, json!({ "user": { "name": "x" } }), "nested include");

        // Nested exclude removes just that leaf, keeps siblings + other keys.
        let exc = apply_get_doc_source_filter(
            src(),
            &GetDocParams {
                source_excludes: Some("user.age".into()),
                ..Default::default()
            },
        );
        assert_eq!(
            exc,
            json!({ "user": { "name": "x" }, "id": 1 }),
            "nested exclude"
        );

        // Top-level literal include is unchanged from before.
        let top = apply_get_doc_source_filter(
            src(),
            &GetDocParams {
                source_includes: Some("id".into()),
                ..Default::default()
            },
        );
        assert_eq!(top, json!({ "id": 1 }), "top-level include");
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// DELETE /{index}/_doc/{id}
// ─────────────────────────────────────────────────────────────────────────────

/// Query parameters for the delete document endpoint.
#[derive(Debug, Default, Deserialize)]
pub struct DeleteDocParams {
    /// `refresh=true|wait_for` — accepted without error; memtable is always visible.
    pub refresh: Option<String>,
    /// Optimistic concurrency: expected sequence number (ES wire form, 0-based).
    pub if_seq_no: Option<u64>,
    /// Optimistic concurrency: expected primary term (must accompany if_seq_no).
    pub if_primary_term: Option<u64>,
}

pub async fn delete_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
    Query(params): Query<DeleteDocParams>,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    // Wire → internal seq translation, same convention as the index path.
    let if_seq_no_internal = params.if_seq_no.map(|s| s.saturating_add(1));

    if let crate::cluster_shard::Dispatch::Done(response) = crate::cluster_shard::dispatch_delete(
        &state,
        &index,
        &id,
        if_seq_no_internal,
        params.if_primary_term,
    )
    .await
    {
        return response;
    }

    let idx = match state.engine.get_index(&index) {
        Ok(i) => i,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    match idx
        .delete_document_versioned(&id, if_seq_no_internal, params.if_primary_term)
        .await
    {
        // Live doc tombstoned → 200 `deleted` with the doc's REAL bumped
        // version and the tombstone's seq (ES wire form).  Was: always
        // 200 `deleted` `_version: 1` with a timestamp-garbage seq_no,
        // even for missing docs and ignored CAS params.
        Ok(outcome) if outcome.found => {
            let resp = EsDeleteDocResponse::deleted(
                &index,
                &id,
                outcome.version,
                outcome.seq_no.saturating_sub(1),
            );
            Json(resp).into_response()
        }
        // Nothing to delete → ES answers 404 with a RESULT body (not an
        // error body): `result: "not_found"`, version bookkeeping still
        // advancing (live-verified against ES 8.13.4).
        Ok(outcome) => {
            let resp = EsDeleteDocResponse::not_found(
                &index,
                &id,
                outcome.version,
                outcome.seq_no.saturating_sub(1),
            );
            (StatusCode::NOT_FOUND, Json(resp)).into_response()
        }
        // CAS mismatch surfaces as 409 version_conflict_engine_exception.
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST/{GET} /{index}/_search
// Supports comma-separated multi-index: /index1,index2/_search
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct EsSearchBody {
    #[serde(default)]
    pub query: Option<Value>,
    /// `null` / absent → default 10.  `0` means return aggregations only.
    #[serde(default = "default_size")]
    pub size: usize,
    #[serde(default, deserialize_with = "deserialize_non_negative_from")]
    pub from: usize,
    #[serde(default)]
    pub sort: Option<Value>,
    #[serde(rename = "_source", default)]
    pub source: Option<Value>,
    #[serde(default)]
    pub aggs: Option<Value>,
    #[serde(default)]
    pub aggregations: Option<Value>,
    #[serde(default)]
    pub highlight: Option<Value>,
    #[serde(default)]
    pub track_total_hits: Option<Value>,
    #[serde(default)]
    pub suggest: Option<Value>,
    #[serde(default)]
    pub explain: bool,
    /// Script fields — `{name: {script: {source, lang?, params?}}}`. Each
    /// script is evaluated per hit against the hit's source and merged into
    /// the hit's `fields` output (subject to `index.max_script_fields`).
    #[serde(default)]
    pub script_fields: Option<Value>,
    /// Stored/doc-value fields to return alongside _source.
    #[serde(default)]
    pub fields: Option<Value>,
    /// Cursor for keyset pagination: sort values from the last hit of the previous page.
    #[serde(default)]
    pub search_after: Option<Value>,
    /// Whether to include execution timing breakdown in the response.
    #[serde(default)]
    pub profile: bool,
    /// Stored fields: `["_id", "_routing"]` or `"_none_"` to suppress all stored fields.
    #[serde(default)]
    pub stored_fields: Option<Value>,
    /// Doc-value fields: return field values from doc values alongside _source.
    #[serde(default)]
    pub docvalue_fields: Option<Value>,
    /// Inner hits for nested / parent-child queries.
    #[serde(default)]
    pub inner_hits: Option<Value>,
    /// Field collapsing: deduplicate results by a field value.
    #[serde(default)]
    pub collapse: Option<Value>,
    /// KNN search spec (ES 8.x top-level knn).
    #[serde(default)]
    pub knn: Option<Value>,
    /// Runtime mappings — accepted and ignored (field types registered but scripts not executed).
    #[serde(default)]
    pub runtime_mappings: Option<Value>,
    /// Rescore specification — re-scores top hits using a secondary query.
    #[serde(default)]
    pub rescore: Option<Value>,
    /// When true, scores are tracked (and `max_score` populated) even for
    /// field-sorted queries. Default false — ES omits scores to avoid the
    /// extra scoring pass when the user asked for a sort.
    #[serde(default)]
    pub track_scores: Option<bool>,
    /// Per-index score boost. ES shape: `[{"<index>": <boost>}, ...]`.
    #[serde(default)]
    pub indices_boost: Option<Value>,
    /// Minimum score threshold — hits with `_score < min_score` are
    /// dropped before pagination, aggregations, and total counting.
    #[serde(default)]
    pub min_score: Option<f64>,
    /// When true, include `_seq_no` and `_primary_term` in each hit. ES omits
    /// these by default; they must be explicitly requested.
    #[serde(default)]
    pub seq_no_primary_term: Option<bool>,
    /// When true, include `_version` on each hit. ES omits by default.
    #[serde(default)]
    pub version: Option<bool>,
    /// Sliced-scroll parameter: `{id: 0, max: 2}` partitions docs by
    /// `hash(_id) % max == id` so parallel scroll readers get disjoint
    /// slices. We apply it post-search as a filter on the materialised
    /// hits.
    #[serde(default)]
    pub slice: Option<Value>,
    /// Point-in-time reference: `{id: "<pit_id>"}`. When set, we override
    /// `index_names` from the PIT context and filter hits to those with
    /// `_seq_no` at-or-below the snapshot taken at PIT open time.
    #[serde(default)]
    pub pit: Option<Value>,
    /// Request-level timeout in ES time-units (`"100ms"`, `"2s"`, bare
    /// number = millis). Parsed into `SearchRequest.timeout_ms` — the
    /// wall-clock deadline every cooperative check in the engine polls.
    /// RC4 blocker 12: this field did not exist, so `{"timeout": "1ms"}`
    /// was silently dropped by serde, `timeout_ms` stayed `None` (30 s
    /// engine default), and the deadline machinery was never armed
    /// (live: a 1 ms-timeout wildcard ran 3.7 s with `timed_out: false`).
    #[serde(default)]
    pub timeout: Option<String>,
    /// Second-stage relevance reranking over the top `window` hits — see
    /// [`crate::rerank_stage`]. Declared here because serde drops unknown
    /// top-level keys silently, and a `rerank` block that vanished without a
    /// word would return lexical order to a caller who asked for something else.
    #[serde(default)]
    pub rerank: Option<Value>,
    /// Opt-in local judging of the returned hits — see
    /// [`crate::judge_stage`] (issue #1060). Declared for the same reason as
    /// `rerank` one field above: a `judge` block serde dropped without a word
    /// would hand back unjudged hits under a 200.
    #[serde(default)]
    pub judge: Option<Value>,
    /// `post_filter` — accepted-and-ignored for ordinary queries (it never
    /// reaches the engine; implementing it generally is #204), but captured
    /// here because beside a `hybrid` query it must be REJECTED (#943): the
    /// fused hits came back unfiltered with a 200, the exact
    /// accepted-and-wrong class. `build_search_request` refuses that one
    /// combination with a 400 naming the supported spellings.
    #[serde(default)]
    pub post_filter: Option<Value>,
}

impl Default for EsSearchBody {
    fn default() -> Self {
        Self {
            query: None,
            size: default_size(),
            from: 0,
            sort: None,
            source: None,
            aggs: None,
            aggregations: None,
            highlight: None,
            track_total_hits: None,
            suggest: None,
            explain: false,
            script_fields: None,
            fields: None,
            search_after: None,
            profile: false,
            stored_fields: None,
            docvalue_fields: None,
            inner_hits: None,
            collapse: None,
            knn: None,
            runtime_mappings: None,
            rescore: None,
            track_scores: None,
            indices_boost: None,
            min_score: None,
            seq_no_primary_term: None,
            version: None,
            slice: None,
            pit: None,
            timeout: None,
            rerank: None,
            judge: None,
            post_filter: None,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Request-validation bundle (RC4 Wave-3 item 4) — the silent-wrong-query class.
//
// Each shape below reproduces live ES 8.13.4 status + JSON so an existing ES
// client sees the same 400 it would from a real cluster instead of a
// misleading 200 with default (match-all) semantics.
// ─────────────────────────────────────────────────────────────────────────────

/// Full set of top-level keys ES 8.13.4 accepts on the `_search` request
/// source (live-probed against the reference cluster), NOT merely the subset
/// `EsSearchBody` models. Keys ES accepts but xerj does not act on
/// (`terminate_after`, `stats`, `ext`) stay accepted-and-ignored exactly as
/// before — only genuinely-unknown keys are rejected. `post_filter` is
/// accepted-and-ignored too, EXCEPT beside a hybrid query, where it is
/// rejected (#943): the fused hits used to come back unfiltered with a 200.
const ES_SEARCH_TOP_LEVEL_KEYS: &[&str] = &[
    "query",
    "from",
    "size",
    "timeout",
    "terminate_after",
    "min_score",
    "post_filter",
    "sort",
    "track_scores",
    "track_total_hits",
    "indices_boost",
    "_source",
    "fields",
    "docvalue_fields",
    "stored_fields",
    "script_fields",
    "runtime_mappings",
    "highlight",
    "suggest",
    "rescore",
    "explain",
    "version",
    "seq_no_primary_term",
    "aggs",
    "aggregations",
    "collapse",
    "slice",
    "search_after",
    "pit",
    "knn",
    "profile",
    "stats",
    "ext",
    // The one key here that is NOT Elasticsearch's: XERJ's second-stage
    // reranking (`crate::rerank_stage`). Listed so the unknown-key gate lets it
    // through to a stage that validates its contents strictly.
    "rerank",
    // The second (`crate::judge_stage`, issue #1060), same rule.
    "judge",
];

/// A minimal position-tracking JSON scanner used solely to locate the first
/// unknown top-level key in a `_search` body and report the ES-style
/// (token-type, 1-based line, 1-based col) of its *value*. Deliberately
/// conservative: on anything it does not understand it stops and reports "no
/// unknown key", so genuinely malformed JSON falls through to the normal
/// serde parse error rather than a misleading unknown-key message.
struct SearchKeyScanner<'a> {
    b: &'a [u8],
    i: usize,
    line: usize,
    col: usize,
}

impl<'a> SearchKeyScanner<'a> {
    fn new(b: &'a [u8]) -> Self {
        Self {
            b,
            i: 0,
            line: 1,
            col: 1,
        }
    }
    #[inline]
    fn cur(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    /// Advance one byte, keeping `line`/`col` pointed at the byte now under
    /// the cursor (1-based, matching Jackson's reporting).
    #[inline]
    fn adv(&mut self) {
        if let Some(c) = self.cur() {
            if c == b'\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
            self.i += 1;
        }
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.cur() {
            if matches!(c, b' ' | b'\t' | b'\r' | b'\n') {
                self.adv();
            } else {
                break;
            }
        }
    }
    /// At an opening quote, consume a whole JSON string and return its bytes as
    /// a lossy String (escape decoding is irrelevant here — no allow-listed key
    /// contains an escape). Advances past the closing quote; `None` if
    /// unterminated.
    fn read_string(&mut self) -> Option<String> {
        if self.cur() != Some(b'"') {
            return None;
        }
        self.adv(); // opening quote
        let mut s = String::new();
        while let Some(c) = self.cur() {
            match c {
                b'"' => {
                    self.adv();
                    return Some(s);
                }
                b'\\' => {
                    self.adv();
                    if let Some(e) = self.cur() {
                        s.push(e as char);
                        self.adv();
                    }
                }
                _ => {
                    s.push(c as char);
                    self.adv();
                }
            }
        }
        None
    }
    /// Skip a complete JSON value (object/array/string/primitive). Returns
    /// false if it runs off the end.
    fn skip_value(&mut self) -> bool {
        self.skip_ws();
        match self.cur() {
            Some(b'"') => self.read_string().is_some(),
            Some(b'{') | Some(b'[') => {
                let mut depth = 0isize;
                loop {
                    match self.cur() {
                        Some(b'"') => {
                            if self.read_string().is_none() {
                                return false;
                            }
                        }
                        Some(b'{') | Some(b'[') => {
                            depth += 1;
                            self.adv();
                        }
                        Some(b'}') | Some(b']') => {
                            depth -= 1;
                            self.adv();
                            if depth == 0 {
                                return true;
                            }
                        }
                        Some(_) => self.adv(),
                        None => return false,
                    }
                }
            }
            Some(_) => {
                while let Some(c) = self.cur() {
                    if matches!(c, b',' | b'}' | b']' | b' ' | b'\t' | b'\r' | b'\n') {
                        break;
                    }
                    self.adv();
                }
                true
            }
            None => false,
        }
    }
}

/// Classify a JSON value's first byte into ES's XContent token name.
fn es_value_token(first: u8) -> &'static str {
    match first {
        b'"' => "VALUE_STRING",
        b'{' => "START_OBJECT",
        b'[' => "START_ARRAY",
        b't' | b'f' => "VALUE_BOOLEAN",
        b'n' => "VALUE_NULL",
        _ => "VALUE_NUMBER",
    }
}

/// Scan a raw `_search` body for the first top-level key ES would reject as
/// unknown. Returns `(key, token_type, line, col)` — line/col are the 1-based
/// position of the offending *value*, matching ES 8.13.4. `None` when every
/// root key is allow-listed, or when the body is not a plain object / is too
/// malformed to scan (serde then owns the error).
fn first_unknown_search_key(bytes: &[u8]) -> Option<(String, &'static str, usize, usize)> {
    let mut s = SearchKeyScanner::new(bytes);
    s.skip_ws();
    if s.cur() != Some(b'{') {
        return None;
    }
    s.adv(); // consume '{'
    loop {
        s.skip_ws();
        match s.cur() {
            Some(b'}') => return None,
            Some(b',') => {
                s.adv();
                continue;
            }
            Some(b'"') => {}
            _ => return None,
        }
        let key = s.read_string()?;
        s.skip_ws();
        if s.cur() != Some(b':') {
            return None;
        }
        s.adv(); // consume ':'
        s.skip_ws();
        let vc = s.cur()?;
        if !ES_SEARCH_TOP_LEVEL_KEYS.contains(&key.as_str()) {
            return Some((key, es_value_token(vc), s.line, s.col));
        }
        if !s.skip_value() {
            return None;
        }
    }
}

/// Build ES's `parsing_exception` body for an unknown top-level search key
/// (item 4a): `Unknown key for a VALUE_STRING in [foo].` with line/col.
fn unknown_search_key_body(key: &str, token: &str, line: usize, col: usize) -> Value {
    let reason = format!("Unknown key for a {token} in [{key}].");
    json!({
        "error": {
            "root_cause": [{ "type": "parsing_exception", "reason": reason, "line": line, "col": col }],
            "type": "parsing_exception",
            "reason": reason,
            "line": line,
            "col": col,
        },
        "status": 400,
    })
}

fn unknown_search_key_error(key: &str, token: &str, line: usize, col: usize) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(unknown_search_key_body(key, token, line, col)),
    )
        .into_response()
}

/// ES's shard-level validation envelope: a 400 `search_phase_execution_exception`
/// ("all shards failed") wrapping an `illegal_argument_exception` root cause.
/// Matches the house style xerj already uses for `_seq_no` sort rejections and
/// ES's own search_after / rescore validation errors (items 4b, 4c).
fn search_shard_validation_body(reason: &str) -> Value {
    json!({
        "error": {
            "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
            "type": "search_phase_execution_exception",
            "reason": "all shards failed",
        },
        "status": 400,
    })
}

fn search_shard_validation_error(reason: &str) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(search_shard_validation_body(reason)),
    )
        .into_response()
}

/// Count `(total, field)` sort clauses in a raw ES `sort` value the way ES does
/// for search_after: `total` counts every clause; `field` counts only clauses
/// that are not `_score` (a `_score`-only sort produces no field for the
/// FieldDoc, so search_after over it is rejected with "Sort must contain at
/// least one field.").
fn count_sort_clauses(sort: &Value) -> (usize, usize) {
    fn clause_field(v: &Value) -> Option<&str> {
        match v {
            Value::String(s) => Some(s.as_str()),
            Value::Object(o) => o.keys().next().map(String::as_str),
            _ => None,
        }
    }
    match sort {
        Value::String(_) | Value::Object(_) => {
            (1, usize::from(clause_field(sort) != Some("_score")))
        }
        Value::Array(arr) => (
            arr.len(),
            arr.iter()
                .filter(|e| clause_field(e) != Some("_score"))
                .count(),
        ),
        _ => (0, 0),
    }
}

/// True when `sort` is effectively "sort by relevance descending" — a single
/// `_score` clause with default/DESC order, or the bare string `"_score"`. ES
/// permits `rescore` alongside such a sort but rejects any other sort
/// ("Cannot use [sort] option in conjunction with [rescore].", item 4c).
fn is_pure_score_desc_sort(sort: &Value) -> bool {
    fn clause_is_score_desc(v: &Value) -> bool {
        match v {
            Value::String(s) => s == "_score",
            Value::Object(o) => {
                if o.len() != 1 {
                    return false;
                }
                let (k, ord) = o.iter().next().unwrap();
                if k != "_score" {
                    return false;
                }
                match ord {
                    // `{"_score": "desc"}` — default order is DESC.
                    Value::String(s) => s.eq_ignore_ascii_case("desc"),
                    // `{"_score": {"order": "desc"}}`; absent order → DESC.
                    Value::Object(oo) => oo
                        .get("order")
                        .and_then(Value::as_str)
                        .map(|s| s.eq_ignore_ascii_case("desc"))
                        .unwrap_or(true),
                    _ => false,
                }
            }
            _ => false,
        }
    }
    match sort {
        Value::String(s) => s == "_score",
        Value::Object(_) => clause_is_score_desc(sort),
        Value::Array(arr) => arr.len() == 1 && clause_is_score_desc(&arr[0]),
        _ => false,
    }
}

/// Reject the search-body semantic combinations ES rejects at query-build time
/// (items 4b + 4c). Returns `Some(response)` with the ES-shaped 400 when
/// invalid; `None` when the body is acceptable.
fn validate_search_after_rescore(body: &EsSearchBody) -> Option<Response> {
    // rescore is incompatible with any sort other than relevance (_score DESC).
    if body.rescore.is_some() {
        if let Some(sort) = body.sort.as_ref() {
            if !is_pure_score_desc_sort(sort) {
                return Some(search_shard_validation_error(
                    "Cannot use [sort] option in conjunction with [rescore].",
                ));
            }
        }
    }
    // search_after arity / field validation. Non-array search_after is left to
    // the engine (a documented minor gap — ES reports it as a token-level
    // parsing_exception which needs the raw byte offset we no longer hold here).
    if let Some(Value::Array(arr)) = body.search_after.as_ref() {
        let (total_sort, field_sort) = body.sort.as_ref().map(count_sort_clauses).unwrap_or((0, 0));
        if field_sort == 0 {
            return Some(search_shard_validation_error(
                "Sort must contain at least one field.",
            ));
        }
        if arr.is_empty() {
            return Some(search_shard_validation_error(
                "Values must contains at least one value.",
            ));
        }
        if arr.len() != total_sort {
            return Some(search_shard_validation_error(&format!(
                "search_after has {} value(s) but sort has {}.",
                arr.len(),
                total_sort
            )));
        }
    }
    None
}

/// Build ES's `illegal_argument_exception` for an unparseable integer URL
/// parameter (item 4d): `?size=abc` → a JSON 400 with a `number_format_exception`
/// cause, instead of axum's default `text/plain` 400.
fn int_param_parse_body(param: &str, value: &str) -> Value {
    let reason = format!("Failed to parse int parameter [{param}] with value [{value}]");
    json!({
        "error": {
            "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
            "type": "illegal_argument_exception",
            "reason": reason,
            "caused_by": {
                "type": "number_format_exception",
                "reason": format!("For input string: \"{value}\""),
            },
        },
        "status": 400,
    })
}

fn int_param_parse_error(param: &str, value: &str) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(int_param_parse_body(param, value)),
    )
        .into_response()
}

/// ES's `illegal_argument_exception` for a scroll id that cannot be decoded
/// (item 4e): `Cannot parse scroll id`, 400. Previously xerj answered 404
/// `index_not_found_exception` with the whole "No search context found for id
/// […]" sentence mis-stuffed into `root_cause[].index`.
fn cannot_parse_scroll_id_body() -> Value {
    json!({
        "error": {
            "root_cause": [{ "type": "illegal_argument_exception", "reason": "Cannot parse scroll id" }],
            "type": "illegal_argument_exception",
            "reason": "Cannot parse scroll id",
            "caused_by": { "type": "e_o_f_exception", "reason": Value::Null },
        },
        "status": 400,
    })
}

fn cannot_parse_scroll_id() -> Response {
    (StatusCode::BAD_REQUEST, Json(cannot_parse_scroll_id_body())).into_response()
}

/// ES's 404 for a well-formed scroll id whose search context is gone
/// (expired/cleared/unknown): `search_context_missing_exception` inside the
/// shard-failure envelope — NOT an `index_not_found_exception` carrying the
/// sentence as an index name.
fn search_context_missing_body(scroll_id: &str) -> Value {
    let reason = format!("No search context found for id [{scroll_id}]");
    json!({
        "error": {
            "root_cause": [{ "type": "search_context_missing_exception", "reason": reason }],
            "type": "search_phase_execution_exception",
            "reason": "all shards failed",
        },
        "status": 404,
    })
}

fn search_context_missing(scroll_id: &str) -> Response {
    (
        StatusCode::NOT_FOUND,
        Json(search_context_missing_body(scroll_id)),
    )
        .into_response()
}

/// Body extractor for `_search` that layers ES 8.13.4's deny-unknown-key
/// behaviour on top of `OptionalJson<EsSearchBody>` (item 4a): a bogus
/// top-level key is rejected with the exact ES `parsing_exception` instead of
/// being silently dropped and answered with a default match-all 200. Empty
/// body → `None` (match-all default); malformed JSON and non-JSON
/// `Content-Type` behave exactly like `OptionalJson`.
pub struct EsSearchJson(pub Option<EsSearchBody>);

impl EsSearchJson {
    #[inline]
    pub fn into_or_default(self) -> EsSearchBody {
        self.0.unwrap_or_default()
    }
}

/// Rejection for [`EsSearchJson`]: either a stock `OptionalJson` failure
/// (body-read / malformed-JSON / unsupported media type) or an unknown
/// top-level search key.
pub enum EsSearchJsonRejection {
    Optional(crate::extract::OptionalJsonRejection),
    UnknownKey {
        key: String,
        token: &'static str,
        line: usize,
        col: usize,
    },
}

impl IntoResponse for EsSearchJsonRejection {
    fn into_response(self) -> Response {
        match self {
            EsSearchJsonRejection::Optional(r) => r.into_response(),
            EsSearchJsonRejection::UnknownKey {
                key,
                token,
                line,
                col,
            } => unknown_search_key_error(&key, token, line, col),
        }
    }
}

#[async_trait]
impl<S: Send + Sync> FromRequest<S> for EsSearchJson {
    type Rejection = EsSearchJsonRejection;

    async fn from_request(req: Request, state: &S) -> Result<Self, Self::Rejection> {
        use crate::extract::OptionalJsonRejection;
        let ct = req
            .headers()
            .get(header::CONTENT_TYPE)
            .and_then(|v| v.to_str().ok())
            .map(str::to_owned);

        let bytes = Bytes::from_request(req, state)
            .await
            .map_err(|e| EsSearchJsonRejection::Optional(OptionalJsonRejection::BodyRead(e)))?;

        if bytes.is_empty() {
            return Ok(EsSearchJson(None));
        }

        if let Some(ct_str) = ct {
            let lower = ct_str.to_ascii_lowercase();
            let is_json = lower.contains("json") || lower.starts_with("text/plain");
            if !is_json {
                return Err(EsSearchJsonRejection::Optional(
                    OptionalJsonRejection::UnsupportedMediaType(ct_str),
                ));
            }
        }

        // Deny unknown top-level keys (ES parity) before the typed parse, so
        // the client sees the offending key rather than a downstream match-all
        // 200. The scanner is conservative and bails to the serde error on
        // malformed input.
        if let Some((key, token, line, col)) = first_unknown_search_key(&bytes) {
            return Err(EsSearchJsonRejection::UnknownKey {
                key,
                token,
                line,
                col,
            });
        }

        let value: EsSearchBody = serde_json::from_slice(&bytes)
            .map_err(|e| EsSearchJsonRejection::Optional(OptionalJsonRejection::JsonParse(e)))?;
        Ok(EsSearchJson(Some(value)))
    }
}

/// Format a sort value according to an ES sort `format` string. When
/// `format` is `None` (or not a recognized date format), return the raw
/// value unchanged. Handles `strict_date_optional_time_nanos` (and its
/// aliases) — the most common format used in ES YAML sort tests.
fn format_sort_value(raw: &Value, format: Option<&str>) -> Value {
    let Some(fmt) = format else {
        return raw.clone();
    };
    // Numeric sort value → treat as epoch; need to decide ms vs ns by
    // magnitude. The split is 2 * 10^15: above it the number is read as
    // nanoseconds, below it as milliseconds. That is right for every
    // NANOSECOND instant from 1970-01-24 on (2e15 ns = 2e6 s = 23.1 days) and
    // every MILLISECOND instant below 2e15 ms (~63,000 years past the epoch),
    // so only a pre-1970-01-24 nanosecond instant reads as milliseconds.
    // (The comment used to say ~2 * 10^13, which is not the constant below.)
    let n = match raw {
        Value::Number(n) => n.as_i64(),
        _ => return raw.clone(),
    };
    let Some(n) = n else { return raw.clone() };
    let is_nanos = n.abs() > 2_000_000_000_000_000;
    let s = match fmt {
        "strict_date_optional_time"
        | "strict_date_optional_time_nanos"
        | "date_optional_time"
        | "date_time"
        | "basic_date_time"
        | "epoch_millis_as_string" => {
            if is_nanos {
                let secs = n.div_euclid(1_000_000_000);
                let sub_ns = n.rem_euclid(1_000_000_000);
                let dt = chrono::DateTime::<chrono::Utc>::from_timestamp(secs, sub_ns as u32)
                    .unwrap_or_default();
                // Render up to nanosecond precision, trimming trailing zeros
                // but keeping at least ms precision.
                let rendered = dt.format("%Y-%m-%dT%H:%M:%S%.9f").to_string();
                let trimmed = rendered.trim_end_matches('0');
                let trimmed = trimmed.trim_end_matches('.');
                format!("{}Z", trimmed)
            } else {
                let dt =
                    chrono::DateTime::<chrono::Utc>::from_timestamp_millis(n).unwrap_or_default();
                dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string()
            }
        }
        "epoch_millis" => n.to_string(),
        "epoch_second" => (n / 1000).to_string(),
        _ => {
            // Java SimpleDateFormat pattern (e.g. `yyyy-MM-dd HH:mm:ss.SSS`
            // or `yyyy-MM-dd | HH:mm:ss.SSS`). Render the epoch back to
            // that pattern so clients see sort values in their requested
            // date shape.
            let pat = java_pattern_to_strftime(fmt);
            let dt = if is_nanos {
                let secs = n.div_euclid(1_000_000_000);
                let sub_ns = n.rem_euclid(1_000_000_000);
                chrono::DateTime::<chrono::Utc>::from_timestamp(secs, sub_ns as u32)
                    .unwrap_or_default()
            } else {
                chrono::DateTime::<chrono::Utc>::from_timestamp_millis(n).unwrap_or_default()
            };
            dt.format(&pat).to_string()
        }
    };
    Value::String(s)
}

/// Translate a Java SimpleDateFormat pattern to chrono strftime — the
/// tokens used by ES sort-format YAML tests. Unknown bytes are emitted
/// literally, and `'...'` quoted literals are stripped.
fn java_pattern_to_strftime(fmt: &str) -> String {
    let mut out = String::with_capacity(fmt.len() + 8);
    let bytes = fmt.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let rest = &fmt[i..];
        if rest.starts_with("yyyy") || rest.starts_with("uuuu") {
            out.push_str("%Y");
            i += 4;
        } else if rest.starts_with("yy") {
            out.push_str("%y");
            i += 2;
        } else if rest.starts_with("MM") {
            out.push_str("%m");
            i += 2;
        } else if rest.starts_with("dd") {
            out.push_str("%d");
            i += 2;
        } else if rest.starts_with("HH") {
            out.push_str("%H");
            i += 2;
        } else if rest.starts_with("mm") {
            out.push_str("%M");
            i += 2;
        } else if rest.starts_with("ss") {
            out.push_str("%S");
            i += 2;
        } else if rest.starts_with("SSSSSSSSS") {
            out.push_str("%9f");
            i += 9;
        } else if rest.starts_with("SSSSSS") {
            out.push_str("%6f");
            i += 6;
        } else if rest.starts_with("SSS") {
            out.push_str("%3f");
            i += 3;
        } else if rest.starts_with("ZZZZZ") {
            out.push_str("%:z");
            i += 5;
        } else if rest.starts_with("XXX") {
            out.push_str("%:z");
            i += 3;
        } else if rest.starts_with('Z') {
            out.push_str("%z");
            i += 1;
        } else if rest.starts_with('\'') {
            i += 1;
            while i < bytes.len() && bytes[i] != b'\'' {
                out.push(bytes[i] as char);
                i += 1;
            }
            if i < bytes.len() {
                i += 1;
            }
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    out
}

/// Walk the query tree and resolve any `terms` lookup clauses — i.e.
/// `{"terms": {"<field>": {"index": I, "id": D, "path": P}}}` — into the
/// explicit value array fetched from the target document's `path` field.
/// Called once per request at coordination time (before build_search_request).
///
/// BFS — `collect_terms_lookups` traverses mutable subtrees; once the
/// set of `(obj_ptr, field, index, id, path)` pointers is known, the
/// async fetch+replace runs as a flat sequential loop.
/// Walk an aggregation tree and substitute stored-script references
/// (`init_script: {id: "name"}`) with the inline source that was put
/// via `PUT /_scripts/{id}`. The engine-level scripted_metric runner
/// only knows inline sources, so resolution happens at the coord layer.
fn resolve_stored_scripts(v: &mut Value, state: &AppState) {
    fn is_script_key(k: &str) -> bool {
        matches!(
            k,
            "init_script" | "map_script" | "combine_script" | "reduce_script" | "script"
        )
    }
    fn walk(v: &mut Value, state: &AppState) {
        match v {
            Value::Object(obj) => {
                let keys: Vec<String> = obj.keys().cloned().collect();
                for k in keys {
                    let child = obj.get_mut(&k).unwrap();
                    if is_script_key(&k) {
                        if let Some(script_obj) = child.as_object_mut() {
                            if let Some(id) = script_obj
                                .get("id")
                                .and_then(Value::as_str)
                                .map(String::from)
                            {
                                if let Some(src) =
                                    state.engine.search_templates.get(&id).map(|v| v.clone())
                                {
                                    let src_str = src
                                        .as_str()
                                        .map(String::from)
                                        .or_else(|| {
                                            src.get("source")
                                                .and_then(Value::as_str)
                                                .map(String::from)
                                        })
                                        .unwrap_or_default();
                                    script_obj.remove("id");
                                    script_obj.insert("source".to_string(), Value::String(src_str));
                                }
                            }
                        }
                    }
                    walk(obj.get_mut(&k).unwrap(), state);
                }
            }
            Value::Array(arr) => {
                for item in arr.iter_mut() {
                    walk(item, state);
                }
            }
            _ => {}
        }
    }
    walk(v, state);
}

/// Convert a list of matched-query names into an ES `matched_queries` value.
/// When `include_scores` is true, emits a `{name: score}` map where each
/// score is the boost of the named sub-query in the raw JSON tree (default
/// 1.0). Otherwise emits a JSON array of names.
fn build_matched_queries_value(
    names: &[String],
    query_json: Option<&Value>,
    include_scores: bool,
    hit_score: Option<f64>,
) -> Value {
    if names.is_empty() {
        return Value::Null;
    }
    if !include_scores {
        return Value::Array(names.iter().cloned().map(Value::String).collect());
    }
    let mut boosts: std::collections::BTreeMap<String, f64> = std::collections::BTreeMap::new();
    let mut fs_names: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
    if let Some(q) = query_json {
        collect_named_query_scores(q, 1.0, &mut boosts);
        collect_function_score_names(q, &mut fs_names);
    }
    let mut out = serde_json::Map::new();
    for name in names {
        // A name attached to the outer function_score gets the hit's
        // actual computed _score (which function_score has already
        // applied the weight/script_score into). Other named clauses
        // use their collected boost.
        let score = if fs_names.contains(name) {
            hit_score.unwrap_or_else(|| boosts.get(name).copied().unwrap_or(1.0))
        } else {
            boosts.get(name).copied().unwrap_or(1.0)
        };
        let n = serde_json::Number::from_f64(score).unwrap_or_else(|| serde_json::Number::from(1));
        out.insert(name.clone(), Value::Number(n));
    }
    Value::Object(out)
}

/// Collect every `_name` that sits directly on a `function_score` object.
/// Used so the matched_queries score map reports the final function_score
/// output for that named clause (which already absorbs the matching
/// function weights / script_score via the engine-side FunctionScore
/// evaluation), rather than a static boost multiplier.
fn collect_function_score_names(q: &Value, out: &mut std::collections::BTreeSet<String>) {
    match q {
        Value::Object(obj) => {
            if let Some(fs) = obj.get("function_score").and_then(|v| v.as_object()) {
                if let Some(n) = fs.get("_name").and_then(Value::as_str) {
                    out.insert(n.to_string());
                }
            }
            for (_, v) in obj {
                collect_function_score_names(v, out);
            }
        }
        Value::Array(arr) => {
            for item in arr {
                collect_function_score_names(item, out);
            }
        }
        _ => {}
    }
}

fn collect_named_query_scores(
    q: &Value,
    parent_boost: f64,
    out: &mut std::collections::BTreeMap<String, f64>,
) {
    match q {
        Value::Object(obj) => {
            // Detect the ES-style `{_name: "x", boost: N, ...query params}`
            // convention at this level.
            let self_boost = obj.get("boost").and_then(Value::as_f64).unwrap_or(1.0);
            // Function-entry score at this level: weight or
            // script_score.script.source (numeric literal). Used to score
            // a `_name` that sits directly on a function_score function
            // entry.
            let fn_entry_score: Option<f64> = {
                let w = obj.get("weight").and_then(Value::as_f64);
                let ss = obj
                    .get("script_score")
                    .and_then(|s| s.get("script"))
                    .and_then(|s| s.get("source"))
                    .and_then(Value::as_str)
                    .and_then(|s| s.trim().parse::<f64>().ok());
                w.or(ss)
            };
            if let Some(name) = obj.get("_name").and_then(Value::as_str) {
                // If this object is a function entry (has weight or
                // script_score), the _name's score is the function's own
                // contribution; otherwise fall back to the boost chain.
                let score = fn_entry_score.unwrap_or(parent_boost * self_boost);
                out.insert(name.to_string(), score);
            }
            // In function_score, each entry in `functions[]` can have a
            // `filter` that carries `_name`, and a sibling `weight` (or
            // `script_score`) that determines the score for the matched
            // named query. Compute the score for this function entry, if
            // present, so we can override after the generic descent.
            let fn_weight = obj.get("weight").and_then(Value::as_f64);
            let fn_script_score = obj
                .get("script_score")
                .and_then(|s| s.get("script"))
                .and_then(|s| s.get("source"))
                .and_then(Value::as_str)
                .and_then(|s| s.trim().parse::<f64>().ok());
            let fn_score = fn_weight.or(fn_script_score);
            for (k, v) in obj {
                if k == "_name" || k == "boost" {
                    continue;
                }
                // Descend into the child, propagating the boost along the
                // way so ES's multiplicative semantics (outer_boost *
                // inner_boost) carry through for nested named queries.
                collect_named_query_scores(v, parent_boost * self_boost, out);
            }
            if let (Some(w), Some(filter)) = (fn_score, obj.get("filter")) {
                // Override the recursively-collected default boost for any
                // `_name` under this filter with the function's weight or
                // script-score result.
                let mut nested = std::collections::BTreeMap::new();
                collect_named_query_scores(filter, 1.0, &mut nested);
                for (name, _) in nested {
                    out.insert(name, w * parent_boost);
                }
            }
        }
        Value::Array(arr) => {
            for item in arr {
                collect_named_query_scores(item, parent_boost, out);
            }
        }
        _ => {}
    }
}

/// For each `{"exists": {"field": X}}` clause, check whether `X` is queryable
/// in *any* of the participating indices. A field is unqueryable if the
/// mapping declares `index: false` AND `doc_values: false` (or the field
/// type doesn't have implicit doc_values support). When unqueryable across
/// every index, the clause is rewritten to `{"match_none": {}}`.
fn rewrite_unqueryable_exists(q: &mut Value, state: &AppState, indices: &[String]) {
    fn field_is_queryable(state: &AppState, idx: &str, field: &str) -> bool {
        let Some(mapping) = state.engine.index_mappings.get(idx).map(|v| v.clone()) else {
            return true; // unknown mapping — be permissive
        };
        let props = mapping
            .get("mappings")
            .and_then(|m| m.get("properties"))
            .or_else(|| mapping.get("properties"))
            .and_then(Value::as_object);
        let Some(props) = props else { return true };
        let segs: Vec<&str> = field.split('.').collect();
        fn resolve<'a>(
            props: &'a serde_json::Map<String, Value>,
            segs: &[&str],
        ) -> Option<&'a Value> {
            let first = segs.first()?;
            let node = props.get(*first)?;
            if segs.len() == 1 {
                return Some(node);
            }
            let child = node.get("properties").and_then(Value::as_object)?;
            resolve(child, &segs[1..])
        }
        let Some(field_map) = resolve(props, &segs) else {
            return true; // field not in mapping — fall through (exists will be false anyway)
        };
        let indexed = field_map
            .get("index")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        let has_dv = field_map
            .get("doc_values")
            .and_then(Value::as_bool)
            .unwrap_or_else(|| {
                // Default doc_values per field type. Numeric/keyword/date/ip/
                // geo_point/boolean all default to true; text defaults to
                // false.
                let ftype = field_map.get("type").and_then(Value::as_str).unwrap_or("");
                !matches!(
                    ftype,
                    "text" | "annotated_text" | "match_only_text" | "binary"
                )
            });
        indexed || has_dv
    }
    fn walk(q: &mut Value, state: &AppState, indices: &[String]) {
        match q {
            Value::Object(obj) => {
                let keys: Vec<String> = obj.keys().cloned().collect();
                for k in keys {
                    if k == "exists" {
                        if let Some(field) = obj
                            .get("exists")
                            .and_then(|e| e.get("field"))
                            .and_then(Value::as_str)
                            .map(String::from)
                        {
                            let any_queryable = indices
                                .iter()
                                .any(|ix| field_is_queryable(state, ix, &field));
                            if !any_queryable {
                                obj.remove("exists");
                                obj.insert("match_none".to_string(), json!({}));
                            }
                        }
                    } else if let Some(child) = obj.get_mut(&k) {
                        walk(child, state, indices);
                    }
                }
            }
            Value::Array(arr) => {
                for item in arr.iter_mut() {
                    walk(item, state, indices);
                }
            }
            _ => {}
        }
    }
    walk(q, state, indices);
}

async fn resolve_terms_lookups(q: &mut Value, state: &AppState) {
    // First pass: collect every (index, id, path) triple keyed by the
    // (terms_obj, field) pair we'll mutate after the fetch.
    let mut pending: Vec<(String, String, String, String)> = Vec::new();
    collect_terms_lookups(q, &mut pending);
    if pending.is_empty() {
        return;
    }
    // Sequentially fetch each referenced doc and record the resolved
    // values keyed by (index, id, path) so a second walk can substitute.
    let mut resolved: std::collections::HashMap<(String, String, String), Vec<Value>> =
        std::collections::HashMap::new();
    for (_field, ix, id, path) in pending.iter() {
        let key = (ix.clone(), id.clone(), path.clone());
        if resolved.contains_key(&key) {
            continue;
        }
        let values = match state.engine.get_index(ix) {
            Ok(idx) => match idx.get_document(id).await {
                Ok(Some(doc)) => {
                    // Some engine paths return the raw source; others return
                    // a wrapper with `_source`. Accept either shape.
                    let src = doc.get("_source").cloned().unwrap_or_else(|| doc.clone());
                    extract_field_values_from_source(&src, path)
                }
                _ => vec![],
            },
            Err(_) => vec![],
        };
        resolved.insert(key, values);
    }
    apply_terms_lookups(q, &resolved);
}

fn collect_terms_lookups(q: &Value, out: &mut Vec<(String, String, String, String)>) {
    match q {
        Value::Object(obj) => {
            for (k, v) in obj.iter() {
                if k == "terms" {
                    if let Some(terms_obj) = v.as_object() {
                        for (field, spec) in terms_obj.iter() {
                            if field == "boost" {
                                continue;
                            }
                            if let Some(s) = spec.as_object() {
                                let ix = s.get("index").and_then(Value::as_str);
                                let id = s.get("id").and_then(Value::as_str);
                                let path = s.get("path").and_then(Value::as_str);
                                if let (Some(ix), Some(id), Some(path)) = (ix, id, path) {
                                    out.push((
                                        field.clone(),
                                        ix.to_string(),
                                        id.to_string(),
                                        path.to_string(),
                                    ));
                                }
                            }
                        }
                    }
                }
                collect_terms_lookups(v, out);
            }
        }
        Value::Array(arr) => {
            for item in arr.iter() {
                collect_terms_lookups(item, out);
            }
        }
        _ => {}
    }
}

fn apply_terms_lookups(
    q: &mut Value,
    resolved: &std::collections::HashMap<(String, String, String), Vec<Value>>,
) {
    match q {
        Value::Object(obj) => {
            // First substitute any direct `terms` lookup at this level.
            if let Some(terms_val) = obj.get_mut("terms") {
                if let Some(terms_obj) = terms_val.as_object_mut() {
                    let fields: Vec<String> = terms_obj.keys().cloned().collect();
                    for field in fields {
                        if field == "boost" {
                            continue;
                        }
                        let spec = terms_obj.get(&field).cloned();
                        if let Some(Value::Object(s)) = spec {
                            let ix = s.get("index").and_then(Value::as_str);
                            let id = s.get("id").and_then(Value::as_str);
                            let path = s.get("path").and_then(Value::as_str);
                            if let (Some(ix), Some(id), Some(path)) = (ix, id, path) {
                                let key = (ix.to_string(), id.to_string(), path.to_string());
                                if let Some(values) = resolved.get(&key) {
                                    terms_obj.insert(field, Value::Array(values.clone()));
                                }
                            }
                        }
                    }
                }
            }
            // Then descend into every child value — the terms clause above
            // is also still visited by the generic walk, but its
            // substitution is idempotent.
            let keys: Vec<String> = obj.keys().cloned().collect();
            for k in keys {
                if let Some(child) = obj.get_mut(&k) {
                    apply_terms_lookups(child, resolved);
                }
            }
        }
        Value::Array(arr) => {
            for item in arr.iter_mut() {
                apply_terms_lookups(item, resolved);
            }
        }
        _ => {}
    }
}

/// Extract every value reachable at `path` (dotted) from a source tree.
/// Arrays flatten; objects descend by segment.
fn extract_field_values_from_source(src: &Value, path: &str) -> Vec<Value> {
    fn walk(v: &Value, segs: &[&str], out: &mut Vec<Value>) {
        if segs.is_empty() {
            match v {
                Value::Array(arr) => {
                    for e in arr {
                        out.push(e.clone());
                    }
                }
                other => out.push(other.clone()),
            }
            return;
        }
        match v {
            Value::Object(o) => {
                if let Some(next) = o.get(segs[0]) {
                    walk(next, &segs[1..], out);
                }
            }
            Value::Array(arr) => {
                for e in arr {
                    walk(e, segs, out);
                }
            }
            _ => {}
        }
    }
    let segs: Vec<&str> = path.split('.').collect();
    let mut out = Vec::new();
    walk(src, &segs, &mut out);
    out
}

/// Merge two metric-aggregation shard responses. Returns `Some(merged)`
/// when both inputs describe the same metric kind — otherwise `None` so
/// the caller can fall back to the bucket-aware merge. xerj emits
/// internal `__xy_count__` / `__xy_sum__` tracking keys on `avg` so that
/// cross-index combination still honors the ES identity
/// `combined_avg = total_sum / total_count` (and not `(avg_a + avg_b) / 2`).
/// `sum` / `min` / `max` / `value_count` merge straightforwardly via the
/// operator appropriate to the metric.
/// Candidate rounding intervals (label, ms) — matches the per-shard list in
/// xerj-engine aggs so the coordinator picks from the same palette.
const AUTO_DATE_INTERVALS: &[(&str, i64)] = &[
    ("1ms", 1),
    ("1s", 1_000),
    ("10s", 10_000),
    ("30s", 30_000),
    ("1m", 60_000),
    ("5m", 300_000),
    ("10m", 600_000),
    ("15m", 900_000),
    ("30m", 1_800_000),
    ("1h", 3_600_000),
    ("3h", 10_800_000),
    ("12h", 43_200_000),
    ("1d", 86_400_000),
    ("7d", 604_800_000),
    ("30d", 2_592_000_000),
    ("90d", 7_776_000_000),
    ("1y", 31_536_000_000),
];

fn epoch_ms_to_iso8601_utc(ms: i64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp_millis(ms)
        .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
        .unwrap_or_default()
}

/// Walk the request `aggs` tree in lock-step with the merged results,
/// and for every `auto_date_histogram` agg re-bucket the merged output
/// using a globally-coordinated interval computed from the full set of
/// per-shard bucket keys. Recursive over sub-aggs so nested agg trees
/// (e.g. `filter { auto_date_histogram {...} }`) get fixed too.
fn rebucket_auto_date_histograms(results: &mut Value, aggs_req: &Value) {
    let Some(req_obj) = aggs_req.as_object() else {
        return;
    };
    let Some(res_obj) = results.as_object_mut() else {
        return;
    };
    for (name, req_spec) in req_obj {
        let Some(spec_obj) = req_spec.as_object() else {
            continue;
        };
        if let Some(params) = spec_obj
            .get("auto_date_histogram")
            .and_then(Value::as_object)
        {
            let target_buckets =
                params.get("buckets").and_then(Value::as_u64).unwrap_or(10) as usize;
            if let Some(res_val) = res_obj.get_mut(name) {
                recoordinate_auto_date_histogram(res_val, target_buckets);
            }
        }
        // Recurse into nested aggs — each agg spec may have an `aggs`
        // sibling. In the merged response, nested aggs live next to the
        // bucket in each bucket's sub-object OR top-level alongside
        // metric results.
        let nested_req = spec_obj
            .get("aggs")
            .or_else(|| spec_obj.get("aggregations"));
        if let (Some(nested_req), Some(res_val)) = (nested_req, res_obj.get_mut(name)) {
            // Descend into buckets (bucket sub-aggs).
            if let Some(buckets) = res_val.get_mut("buckets") {
                match buckets {
                    Value::Array(arr) => {
                        for b in arr.iter_mut() {
                            rebucket_auto_date_histograms(b, nested_req);
                        }
                    }
                    Value::Object(obj) => {
                        for (_, b) in obj.iter_mut() {
                            rebucket_auto_date_histograms(b, nested_req);
                        }
                    }
                    _ => {}
                }
            } else {
                // Pure wrapper (filter/global/etc.) — recurse in place.
                rebucket_auto_date_histograms(res_val, nested_req);
            }
        }
    }
}

fn recoordinate_auto_date_histogram(res: &mut Value, target_buckets: usize) {
    let Some(obj) = res.as_object_mut() else {
        return;
    };
    let buckets = match obj.get("buckets").and_then(|b| b.as_array()) {
        Some(b) if !b.is_empty() => b.clone(),
        _ => return,
    };
    // Collect (key_ms, doc_count, sub_aggs_map) per bucket.
    let mut entries: Vec<(i64, u64, serde_json::Map<String, Value>)> =
        Vec::with_capacity(buckets.len());
    for b in &buckets {
        let bo = match b.as_object() {
            Some(o) => o,
            None => return,
        };
        let key = match bo.get("key").and_then(Value::as_i64) {
            Some(k) => k,
            None => return,
        };
        let doc_count = bo.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        let mut subs: serde_json::Map<String, Value> = serde_json::Map::new();
        for (k, v) in bo.iter() {
            match k.as_str() {
                "key" | "key_as_string" | "doc_count" => {}
                _ => {
                    subs.insert(k.clone(), v.clone());
                }
            }
        }
        entries.push((key, doc_count, subs));
    }
    let min_ts = entries.iter().map(|(k, ..)| *k).min().unwrap_or(0);
    let max_ts = entries.iter().map(|(k, ..)| *k).max().unwrap_or(0);
    // Select interval satisfying num_buckets ≤ target; tie-break by
    // smallest interval (matches ES coordinator).
    let chosen = AUTO_DATE_INTERVALS
        .iter()
        .min_by_key(|(_, im)| {
            let mn = min_ts.div_euclid(*im) * im;
            let mx = max_ts.div_euclid(*im) * im;
            let nb = ((mx - mn) / im + 1).max(1) as usize;
            let diff = nb as i64 - target_buckets as i64;
            let overflow = if diff > 0 { 1i64 } else { 0 };
            (overflow, diff.abs())
        })
        .copied()
        .unwrap_or(("1d", 86_400_000));
    let (new_label, new_interval) = chosen;
    let current_label = obj
        .get("interval")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    // If per-shard already agreed on the coordinator's interval, no-op.
    if current_label == new_label {
        return;
    }
    // Re-bucket at the coarser grid. Sum doc_counts and merge sub-aggs.
    let mut grid: std::collections::BTreeMap<i64, (u64, serde_json::Map<String, Value>)> =
        std::collections::BTreeMap::new();
    for (key, dc, subs) in entries {
        let bucket_start = key.div_euclid(new_interval) * new_interval;
        let e = grid
            .entry(bucket_start)
            .or_insert_with(|| (0, serde_json::Map::new()));
        e.0 += dc;
        // Sub-agg merge: if existing, delegate to merge_metric_agg /
        // merge_bucket_agg when possible; otherwise keep the first.
        for (sk, sv) in subs {
            if let Some(existing) = e.1.get(&sk).cloned() {
                if let Some(m) = merge_metric_agg(&existing, &sv) {
                    e.1.insert(sk, m);
                    continue;
                }
                if let Some(m) = merge_bucket_agg(&existing, &sv) {
                    e.1.insert(sk, m);
                    continue;
                }
                // Fallback: keep existing — sub-agg is of an unknown
                // shape, don't risk corrupting it.
            } else {
                e.1.insert(sk, sv);
            }
        }
    }
    let mut new_buckets: Vec<Value> = Vec::with_capacity(grid.len());
    for (bucket_start, (dc, subs)) in grid {
        let mut bo = serde_json::Map::new();
        bo.insert(
            "key_as_string".to_string(),
            Value::String(epoch_ms_to_iso8601_utc(bucket_start)),
        );
        bo.insert("key".to_string(), json!(bucket_start));
        bo.insert("doc_count".to_string(), json!(dc));
        for (k, v) in subs {
            bo.insert(k, v);
        }
        new_buckets.push(Value::Object(bo));
    }
    obj.insert("interval".to_string(), Value::String(new_label.to_string()));
    obj.insert("buckets".to_string(), Value::Array(new_buckets));
}

/// Merge two single-bucket aggregation results across indices.
///
/// Covers `nested` / `reverse_nested` / `filter` / `global` / `sampler` —
/// agg shapes whose top-level result is `{doc_count, sub_agg_1, sub_agg_2,
/// ...}` with no `buckets` array. These slip past both `merge_metric_agg`
/// (no `value`) and `merge_bucket_agg` (no `buckets`), so absent this
/// helper one shard's empty result silently overwrote another's data
/// whenever the unmapped shard happened to land first.
fn merge_single_bucket_agg(old: &Value, new: &Value) -> Option<Value> {
    let old_obj = old.as_object()?;
    let new_obj = new.as_object()?;
    if !old_obj.contains_key("doc_count") || !new_obj.contains_key("doc_count") {
        return None;
    }
    if old_obj.contains_key("buckets") || new_obj.contains_key("buckets") {
        return None;
    }
    // A `key` field means this is a bucket inside a parent bucketed agg —
    // the bucket-aware path owns merging there. Single-bucket top-level
    // results never carry `key`.
    if old_obj.contains_key("key") || new_obj.contains_key("key") {
        return None;
    }
    let mut merged = old_obj.clone();
    let a_count = old_obj
        .get("doc_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let b_count = new_obj
        .get("doc_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    merged.insert("doc_count".to_string(), json!(a_count + b_count));
    for (k, v) in new_obj {
        if k == "doc_count" || k.starts_with("__") {
            continue;
        }
        if let Some(old_v) = merged.get(k).cloned() {
            if let Some(m) = merge_metric_agg(&old_v, v) {
                merged.insert(k.clone(), m);
            } else if let Some(m) = merge_bucket_agg(&old_v, v) {
                merged.insert(k.clone(), m);
            } else if let Some(m) = merge_single_bucket_agg(&old_v, v) {
                merged.insert(k.clone(), m);
            }
            // else keep existing
        } else {
            merged.insert(k.clone(), v.clone());
        }
    }
    Some(Value::Object(merged))
}

fn merge_metric_agg(old: &Value, new: &Value) -> Option<Value> {
    let old_obj = old.as_object()?;
    let new_obj = new.as_object()?;
    // Only merge objects that look like a metric agg response (`value` key,
    // and no `buckets` — we leave bucketed aggs to the bucket-aware path).
    if old_obj.contains_key("buckets") || new_obj.contains_key("buckets") {
        return None;
    }
    // Avg with internal tracking primitives.
    if let (Some(cnt_a), Some(sum_a), Some(cnt_b), Some(sum_b)) = (
        old_obj.get("__xy_count__").and_then(Value::as_u64),
        old_obj.get("__xy_sum__").and_then(Value::as_f64),
        new_obj.get("__xy_count__").and_then(Value::as_u64),
        new_obj.get("__xy_sum__").and_then(Value::as_f64),
    ) {
        let total_count = cnt_a + cnt_b;
        let total_sum = sum_a + sum_b;
        let value = if total_count == 0 {
            Value::Null
        } else {
            serde_json::json!(total_sum / total_count as f64)
        };
        return Some(serde_json::json!({
            "value": value,
            "__xy_count__": total_count,
            "__xy_sum__": total_sum,
        }));
    }
    // Typed metric results (`__xy_agg__` marker) — pick the correct
    // merge operator without needing to re-look-up the agg spec.
    let agg_type = old_obj
        .get("__xy_agg__")
        .and_then(Value::as_str)
        .or_else(|| new_obj.get("__xy_agg__").and_then(Value::as_str));
    if let Some(t) = agg_type {
        // Cardinality unions the distinct value sets carried as an
        // internal `__xy_values__` array so multi-index results are a
        // true union, not a sum (which would double-count values present
        // in both shards).
        if t == "cardinality" {
            use std::collections::HashSet;
            let mut set: HashSet<String> = HashSet::new();
            let collect = |arr: Option<&Value>, set: &mut HashSet<String>| {
                if let Some(Value::Array(vs)) = arr {
                    for v in vs {
                        if let Some(s) = v.as_str() {
                            set.insert(s.to_string());
                        }
                    }
                }
            };
            collect(old_obj.get("__xy_values__"), &mut set);
            collect(new_obj.get("__xy_values__"), &mut set);
            let values: Vec<Value> = set.iter().map(|s| Value::String(s.clone())).collect();
            return Some(serde_json::json!({
                "value": set.len(),
                "__xy_agg__": "cardinality",
                "__xy_values__": values,
            }));
        }
        let a = old_obj.get("value");
        let b = new_obj.get("value");
        let merged: Option<f64> = match (a.and_then(Value::as_f64), b.and_then(Value::as_f64)) {
            (Some(x), Some(y)) => Some(match t {
                "sum" | "value_count" => x + y,
                "min" => x.min(y),
                "max" => x.max(y),
                _ => return None,
            }),
            (Some(x), None) => Some(x),
            (None, Some(y)) => Some(y),
            (None, None) => None,
        };
        let value = merged
            .and_then(|f| serde_json::Number::from_f64(f).map(Value::Number))
            .unwrap_or(Value::Null);
        let mut out = serde_json::Map::new();
        out.insert("value".to_string(), value);
        out.insert("__xy_agg__".to_string(), Value::String(t.to_string()));
        // Preserve value_as_string from whichever side has it (date
        // metrics emit both and we don't want to strip the formatted
        // representation during the numeric merge).
        if let Some(vas) = new_obj
            .get("value_as_string")
            .or_else(|| old_obj.get("value_as_string"))
            .cloned()
        {
            out.insert("value_as_string".to_string(), vas);
        }
        return Some(Value::Object(out));
    }
    // Numeric `value` with no typed marker — prefer a non-null value
    // over a null one (common when one shard has the field and another
    // doesn't); otherwise leave to the bucket-aware fallback.
    match (old_obj.get("value"), new_obj.get("value")) {
        (Some(Value::Null), Some(b)) if !b.is_null() => {
            Some(serde_json::json!({ "value": b.clone() }))
        }
        _ => None,
    }
}

/// Merge two bucketed aggregation results across indices.
///
/// Handles the common shape `{"buckets": [...], ...}` where each bucket
/// has a `key` and `doc_count`. Buckets with matching keys are combined:
/// `doc_count` sums, and any sub-aggregations recursively go through
/// `merge_metric_agg`/`merge_bucket_agg`. Non-bucket fields
/// (`sum_other_doc_count`, `doc_count_error_upper_bound`) are summed.
///
/// For terms aggs the result is re-sorted by `doc_count` descending to
/// preserve ES top-N semantics. Range/histogram aggs naturally preserve
/// bucket order because same-key merges keep the first-seen ordinal.
///
/// Returns `None` if either side is not a bucketed shape this function
/// knows how to merge — the caller then falls back to replace semantics.
fn merge_bucket_agg(old: &Value, new: &Value) -> Option<Value> {
    let old_obj = old.as_object()?;
    let new_obj = new.as_object()?;
    let old_buckets_val = old_obj.get("buckets")?;
    let new_buckets_val = new_obj.get("buckets")?;

    // Keyed multi-bucket aggs — `filters` in its default named-filter form,
    // or `terms`/`range`/`date_range` with `keyed: true` — represent
    // `buckets` as a JSON OBJECT (bucket name -> bucket body), not an
    // array; the object's own key IS the bucket identity, no `key`/
    // `key_as_string` field to extract. Falling through to the array-only
    // path below made this whole function return `None` for a keyed agg
    // (`.as_array()` on an object is `None`), and the caller's fallback
    // "replace only if old was empty" check made the SAME mistake
    // (`.as_array()` on the keyed buckets object), so across N indices
    // only the first index's contribution to a keyed bucket ever survived
    // — every other index's matching documents were silently dropped from
    // a multi-index search's aggregation, even though `hits.total` summed
    // correctly across the same indices. Found live via a Kibana/OSD
    // Timelion panel's `filters` + `query_string` aggregation returning
    // doc_count 0 across `_all` despite the target index alone holding
    // thousands of matches.
    if let (Some(old_map), Some(new_map)) =
        (old_buckets_val.as_object(), new_buckets_val.as_object())
    {
        let mut merged_map = old_map.clone();
        for (key, b) in new_map {
            let Some(b_obj) = b.as_object() else { continue };
            match merged_map.get_mut(key) {
                Some(existing) => {
                    let Some(existing_obj) = existing.as_object_mut() else {
                        continue;
                    };
                    let a_count = existing_obj
                        .get("doc_count")
                        .and_then(Value::as_u64)
                        .unwrap_or(0);
                    let b_count = b_obj.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
                    existing_obj.insert("doc_count".to_string(), json!(a_count + b_count));
                    for (k, v) in b_obj {
                        if k == "doc_count" {
                            continue;
                        }
                        if let Some(old_v) = existing_obj.get(k).cloned() {
                            if let Some(m) = merge_metric_agg(&old_v, v) {
                                existing_obj.insert(k.clone(), m);
                            } else if let Some(m) = merge_bucket_agg(&old_v, v) {
                                existing_obj.insert(k.clone(), m);
                            } else if let Some(m) = merge_single_bucket_agg(&old_v, v) {
                                existing_obj.insert(k.clone(), m);
                            }
                            // else keep existing
                        } else {
                            existing_obj.insert(k.clone(), v.clone());
                        }
                    }
                }
                None => {
                    merged_map.insert(key.clone(), b.clone());
                }
            }
        }
        let summable = |k: &str| -> bool {
            matches!(
                k,
                "sum_other_doc_count" | "doc_count_error_upper_bound" | "bg_count" | "doc_count"
            )
        };
        let mut out = serde_json::Map::new();
        for (k, v) in old_obj.iter().chain(new_obj.iter()) {
            if k == "buckets" {
                continue;
            }
            match v {
                Value::Number(n) if summable(k) => {
                    let acc =
                        out.get(k).and_then(Value::as_u64).unwrap_or(0) + n.as_u64().unwrap_or(0);
                    out.insert(k.clone(), json!(acc));
                }
                _ => {
                    out.entry(k.clone()).or_insert_with(|| v.clone());
                }
            }
        }
        out.insert("buckets".to_string(), Value::Object(merged_map));
        return Some(Value::Object(out));
    }

    let old_buckets = old_buckets_val.as_array()?;
    let new_buckets = new_buckets_val.as_array()?;

    fn bucket_key(b: &Value) -> String {
        if let Some(k) = b.get("key_as_string").and_then(Value::as_str) {
            return format!("kas:{k}");
        }
        fn num_to_canonical(n: &serde_json::Number) -> String {
            // Canonicalize numbers so long 10 and double 10.0 collide.
            if let Some(f) = n.as_f64() {
                let trunc = f.trunc();
                if (f - trunc).abs() < f64::EPSILON && trunc.abs() < (1u64 << 53) as f64 {
                    return (trunc as i64).to_string();
                }
                // Round-trip through f64 to normalize "2.0" vs "2" variants.
                return format!("{f}");
            }
            n.to_string()
        }
        match b.get("key") {
            Some(Value::String(s)) => format!("s:{s}"),
            Some(Value::Number(n)) => format!("n:{}", num_to_canonical(n)),
            Some(Value::Bool(b)) => format!("b:{b}"),
            Some(Value::Object(o)) => {
                let mut pairs: Vec<(String, String)> = o
                    .iter()
                    .map(|(k, v)| {
                        let v_s = match v {
                            Value::Number(n) => num_to_canonical(n),
                            _ => v.to_string(),
                        };
                        (k.clone(), v_s)
                    })
                    .collect();
                pairs.sort();
                let joined: Vec<String> =
                    pairs.into_iter().map(|(k, v)| format!("{k}={v}")).collect();
                format!("o:{}", joined.join(","))
            }
            Some(Value::Array(a)) => format!("a:{}", serde_json::to_string(a).unwrap_or_default()),
            _ => String::new(),
        }
    }

    // Insertion-ordered merge map so we preserve first-seen order for
    // range/date_range/histogram/date_histogram (keys are naturally
    // deterministic by numeric/temporal order anyway).
    let mut merged: Vec<(String, Value)> = Vec::new();
    let mut key_idx: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    for b in old_buckets.iter().chain(new_buckets.iter()) {
        let key = bucket_key(b);
        if let Some(&idx) = key_idx.get(&key) {
            let (_, existing) = &mut merged[idx];
            let existing_obj = match existing.as_object_mut() {
                Some(o) => o,
                None => continue,
            };
            let b_obj = match b.as_object() {
                Some(o) => o,
                None => continue,
            };
            // doc_count sums.
            let a_count = existing_obj
                .get("doc_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            let b_count = b_obj.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
            existing_obj.insert("doc_count".to_string(), json!(a_count + b_count));
            // Merge any nested sub-aggregations.
            for (k, v) in b_obj {
                if k == "doc_count" || k == "key" || k == "key_as_string" {
                    continue;
                }
                if let Some(old_v) = existing_obj.get(k).cloned() {
                    if let Some(m) = merge_metric_agg(&old_v, v) {
                        existing_obj.insert(k.clone(), m);
                    } else if let Some(m) = merge_bucket_agg(&old_v, v) {
                        existing_obj.insert(k.clone(), m);
                    } else if let Some(m) = merge_single_bucket_agg(&old_v, v) {
                        existing_obj.insert(k.clone(), m);
                    }
                    // If no merger handles it, keep the existing value.
                } else {
                    existing_obj.insert(k.clone(), v.clone());
                }
            }
        } else {
            key_idx.insert(key.clone(), merged.len());
            merged.push((key, b.clone()));
        }
    }

    // Only re-sort when we can positively identify a terms agg by its
    // container-level bookkeeping (`sum_other_doc_count` /
    // `doc_count_error_upper_bound` are unique to terms). For everything
    // else (range / histogram / date_histogram / filters-keyed / composite)
    // the natural first-seen order is correct.
    let is_terms_like = old_obj.contains_key("sum_other_doc_count")
        || new_obj.contains_key("sum_other_doc_count")
        || old_obj.contains_key("doc_count_error_upper_bound")
        || new_obj.contains_key("doc_count_error_upper_bound");
    // Composite aggregations carry an `after_key` top-level entry. Their
    // buckets must preserve the per-shard ordering (each shard already
    // sorted), and we refresh `after_key` to the final bucket so cursor
    // pagination works across merged shards.
    let is_composite = old_obj.contains_key("after_key") || new_obj.contains_key("after_key");
    if is_terms_like {
        merged.sort_by(|a, b| {
            let ac = a.1.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
            let bc = b.1.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
            bc.cmp(&ac).then_with(|| a.0.cmp(&b.0))
        });
    }

    let mut out = serde_json::Map::new();
    // Preserve/sum non-bucket metadata. Counter fields are summed so
    // multi-shard/multi-index responses show the same totals as a
    // single-shard run.
    let summable = |k: &str| -> bool {
        matches!(
            k,
            "sum_other_doc_count" | "doc_count_error_upper_bound" | "bg_count" | "doc_count"
        )
    };
    for (k, v) in old_obj.iter().chain(new_obj.iter()) {
        if k == "buckets" {
            continue;
        }
        match v {
            Value::Number(n) if summable(k) => {
                let acc = out.get(k).and_then(Value::as_u64).unwrap_or(0) + n.as_u64().unwrap_or(0);
                out.insert(k.clone(), json!(acc));
            }
            _ => {
                out.entry(k.clone()).or_insert_with(|| v.clone());
            }
        }
    }
    let merged_buckets: Vec<Value> = merged.into_iter().map(|(_, v)| v).collect();
    // For composite aggregations, `after_key` should point at the LAST
    // bucket post-merge (matches ES cursor-continuation semantics).
    if is_composite {
        if let Some(last_key) = merged_buckets.last().and_then(|b| b.get("key")).cloned() {
            out.insert("after_key".to_string(), last_key);
        }
    }
    out.insert("buckets".to_string(), Value::Array(merged_buckets));
    Some(Value::Object(out))
}

#[cfg(test)]
mod merge_bucket_agg_keyed_tests {
    use super::*;

    // Regression: a keyed multi-bucket agg (`filters` in its default
    // named-filter form; also `terms`/`range`/`date_range` with
    // `keyed: true`) represents `buckets` as a JSON OBJECT, not an array.
    // `merge_bucket_agg` used to require `.as_array()`, so it silently
    // returned `None` for this shape — and the caller's array-only
    // fallback replace-check made the identical mistake — so across a
    // multi-index search only the FIRST index's contribution to a keyed
    // bucket ever survived; every other index's matching documents were
    // dropped from the merged aggregation despite `hits.total` correctly
    // summing across the same indices. Found live via a Kibana/OSD
    // Timelion panel's `filters` + `query_string` aggregation reporting
    // doc_count 0 on a multi-index (`_all`) search.
    #[test]
    fn keyed_filters_agg_sums_doc_count_across_indices() {
        let from_index_a = json!({
            "buckets": {
                "mykey": {"doc_count": 0}
            }
        });
        let from_index_b = json!({
            "buckets": {
                "mykey": {"doc_count": 3769}
            }
        });
        let merged =
            merge_bucket_agg(&from_index_a, &from_index_b).expect("keyed buckets must merge");
        assert_eq!(
            merged["buckets"]["mykey"]["doc_count"], 3769,
            "doc_count from every index must be summed, not just the first"
        );
    }

    /// The keyed merge must also recurse into nested sub-aggregations
    /// (e.g. a `date_histogram` inside a `filters` bucket, the exact shape
    /// Timelion sends) rather than dropping them or keeping only one
    /// index's contribution.
    #[test]
    fn keyed_filters_agg_merges_nested_sub_aggregation() {
        let from_index_a = json!({
            "buckets": {
                "mykey": {
                    "doc_count": 5,
                    "inner": {"value": 10.0}
                }
            }
        });
        let from_index_b = json!({
            "buckets": {
                "mykey": {
                    "doc_count": 7,
                    "inner": {"value": 20.0}
                }
            }
        });
        let merged = merge_bucket_agg(&from_index_a, &from_index_b)
            .expect("keyed buckets with nested sub-aggs must merge");
        assert_eq!(merged["buckets"]["mykey"]["doc_count"], 12);
        // `merge_metric_agg` doesn't recombine plain untracked `value`
        // pairs (no internal tracking to average correctly), so it keeps
        // the existing value rather than guessing — the important
        // regression coverage here is that doc_count summed and the
        // sub-agg key survived the merge at all (previously the whole
        // bucket from index B was dropped).
        assert!(merged["buckets"]["mykey"]["inner"].is_object());
    }

    /// A bucket key present only in the SECOND index (a filter with no
    /// matches from the first index at all) must still appear in the
    /// merged result, not be silently dropped.
    #[test]
    fn keyed_filters_agg_adds_new_key_from_second_index() {
        let from_index_a = json!({"buckets": {"a": {"doc_count": 3}}});
        let from_index_b = json!({"buckets": {"b": {"doc_count": 4}}});
        let merged = merge_bucket_agg(&from_index_a, &from_index_b).expect("must merge");
        assert_eq!(merged["buckets"]["a"]["doc_count"], 3);
        assert_eq!(merged["buckets"]["b"]["doc_count"], 4);
    }
}

fn synthetic_transform_object_ext2(
    target: &mut serde_json::Map<String, Value>,
    props: &Value,
    index_keep_arrays: bool,
    parent_dynamic_false: bool,
    inside_nested: bool,
) {
    // Step 1: collect dotted keys at this level and re-insert via
    // insert_synthetic_path (only transform when the target level has
    // a real mapping — otherwise the dotted key is "ignored source"
    // and must stay verbatim).
    let has_mapped_props = props.as_object().map(|o| !o.is_empty()).unwrap_or(false);
    if has_mapped_props {
        let keys: Vec<String> = target.keys().cloned().collect();
        for key in keys {
            if !key.contains('.') {
                continue;
            }
            let val = target.remove(&key).unwrap_or(Value::Null);
            insert_synthetic_path(target, props, &key, val);
        }
    }
    // Step 1.5: Synthetic-source column-major flatten for non-nested
    // *mapped* array-of-objects. ES reconstructs object-mapped arrays
    // via per-leaf doc_values, producing `{a:[10,100], b:[20,200]}`
    // instead of `[{a:10,b:20}, {a:100,b:200}]`. This only applies to
    // fields that are actually in the mapping (either declared or
    // dynamically created) — fields rejected as "ignored source" (e.g.
    // via `ignore_dynamic_beyond_limit`, unmapped objects under
    // `subobjects:false`, or explicit `dynamic:false`) keep source
    // order verbatim. We detect "mapped" as "props has an entry for
    // this field", since dynamic ingest already updates the mapping
    // before the doc is retrievable.
    {
        let names: Vec<String> = target.keys().cloned().collect();
        for name in names {
            let field_spec = props.as_object().and_then(|o| o.get(&name));
            // Unmapped children: ES dynamically maps them at ingest and
            // reconstructs them via doc_values column-major on read.
            // Three cases preserve source shape verbatim instead:
            //   - `dynamic: false` / `dynamic: runtime` at the parent
            //   - index-level `total_fields.ignore_dynamic_beyond_limit`
            //   - not inside a declared `nested` parent and no parent
            //     has any hint that this key is dynamically mapped
            // Only allow implicit-flatten when we know dynamic mapping
            // would apply: either we're inside a `nested` element or
            // the parent explicitly opts in (has properties AND is not
            // dynamic-false).
            if field_spec.is_none() {
                if parent_dynamic_false {
                    continue;
                }
                if !inside_nested {
                    // At a regular (non-nested) parent with no
                    // declared entry for this key, prefer the safe
                    // source-preserving behaviour unless the parent's
                    // mapping clearly declares siblings (then the
                    // field is a dynamically-added object sibling and
                    // should flatten, matching "nested object next to
                    // regular").
                    let parent_has_declared_siblings =
                        props.as_object().map(|o| !o.is_empty()).unwrap_or(false);
                    if !parent_has_declared_siblings {
                        continue;
                    }
                }
            }
            let (sub_props, sub_dynamic_false, keep_mode, is_nested, is_disabled) = match field_spec
            {
                Some(spec) => {
                    let ftype = spec.get("type").and_then(Value::as_str).unwrap_or("");
                    let disabled =
                        matches!(spec.get("enabled").and_then(Value::as_bool), Some(false));
                    let keep = spec
                        .get("synthetic_source_keep")
                        .and_then(Value::as_str)
                        .map(String::from);
                    let sub_props = spec.get("properties").cloned().unwrap_or(Value::Null);
                    let sub_df = spec
                        .get("dynamic")
                        .map(|v| match v {
                            Value::Bool(false) => true,
                            Value::String(s) => s == "false" || s == "runtime",
                            _ => false,
                        })
                        .unwrap_or(false);
                    (sub_props, sub_df, keep, ftype == "nested", disabled)
                }
                None => (Value::Null, false, None, false, false),
            };
            if is_nested {
                continue;
            }
            if is_disabled {
                continue;
            }
            // Effective synthetic_source_keep: an explicit per-field
            // `arrays|all|none` overrides the index-level default. keep:arrays|all
            // preserves the source array shape (never column-flatten); keep:none
            // forces flatten even when the index default is `arrays`; no override
            // inherits the index default. This makes the block correct under
            // `index.mapping.synthetic_source_keep: arrays` (previously the whole
            // block was skipped, so a keep:none field was never flattened).
            let effective_keep_arrays = match keep_mode.as_deref() {
                Some("arrays") | Some("all") => true,
                Some("none") => false,
                _ => index_keep_arrays,
            };
            if effective_keep_arrays {
                continue;
            }
            let should_flatten = matches!(
                target.get(&name),
                Some(Value::Array(arr)) if !arr.is_empty() && arr.iter().all(|v| v.is_object())
            );
            if !should_flatten {
                continue;
            }
            if let Some(Value::Array(arr)) = target.remove(&name) {
                target.insert(
                    name,
                    synthetic_flatten_object_array(
                        &arr,
                        &sub_props,
                        sub_dynamic_false,
                        index_keep_arrays,
                    ),
                );
            }
        }
    }

    // Step 2: recurse only into children whose parent property is
    // mapped with its own sub-`properties` block. Unmapped children
    // (or mapped-without-sub-properties like a `keyword` leaf with a
    // stray dotted string) are left alone — we don't rewrite their
    // contents. When a child's spec declares
    // `synthetic_source_keep: arrays|all`, propagate that as a
    // "keep arrays" flag to the subtree — leaf arrays under it
    // preserve source order regardless of index default.
    let names: Vec<String> = target.keys().cloned().collect();
    for name in names {
        let child_spec = props.as_object().and_then(|o| o.get(&name));
        let child_type = child_spec
            .and_then(|hp| hp.get("type"))
            .and_then(Value::as_str);
        let child_is_nested = child_type == Some("nested");
        // Flattened fields reconstruct as a single-level dotted-key map
        // (`{host:{name:x}}` -> `{"host.name":x}`), not a re-nested object.
        // Collapse here and skip the normal object recursion.
        if matches!(child_type, Some("flattened") | Some("flat_object")) {
            if let Some(cv) = target.get_mut(&name) {
                match cv {
                    Value::Object(_) => {
                        let mut flat = serde_json::Map::new();
                        flatten_synthetic_dotted("", cv, &mut flat);
                        *cv = Value::Object(flat);
                    }
                    Value::Array(arr) => {
                        for el in arr.iter_mut() {
                            if let Value::Object(_) = el {
                                let mut flat = serde_json::Map::new();
                                flatten_synthetic_dotted("", el, &mut flat);
                                *el = Value::Object(flat);
                            }
                        }
                    }
                    _ => {}
                }
            }
            continue;
        }
        let child_props_raw = child_spec.and_then(|hp| hp.get("properties")).cloned();
        // Skip recursion unless we have sub-properties OR this is a
        // nested parent (nested without declared sub-properties still
        // needs per-element synthetic reconstruction for dynamic children).
        if child_props_raw.is_none() && !child_is_nested {
            continue;
        }
        let child_props = child_props_raw.unwrap_or(Value::Null);
        let child_keep = child_spec
            .and_then(|hp| hp.get("synthetic_source_keep"))
            .and_then(Value::as_str);
        let child_keep_arrays =
            index_keep_arrays || matches!(child_keep, Some("arrays") | Some("all"));
        let child_dynamic_false = child_spec
            .and_then(|hp| hp.get("dynamic"))
            .map(|v| match v {
                Value::Bool(false) => true,
                Value::String(s) => s == "false" || s == "runtime",
                _ => false,
            })
            .unwrap_or(false);
        if let Some(child_val) = target.get_mut(&name) {
            match child_val {
                Value::Object(child_obj) => synthetic_transform_object_ext2(
                    child_obj,
                    &child_props,
                    child_keep_arrays,
                    child_dynamic_false,
                    child_is_nested,
                ),
                Value::Array(arr) => {
                    for el in arr.iter_mut() {
                        if let Value::Object(co) = el {
                            synthetic_transform_object_ext2(
                                co,
                                &child_props,
                                child_keep_arrays,
                                child_dynamic_false,
                                child_is_nested,
                            );
                        }
                    }
                }
                _ => {}
            }
        }
    }
    // Step 3: sort leaf primitive arrays ascending — ES synthetic source
    // reconstructs leaf arrays from doc_values, which enumerate values in
    // sorted order. This applies to numeric and keyword leaves (dynamic
    // or declared), NOT to text fields (which use positional postings)
    // and NOT to fields with `synthetic_source_keep: arrays|all`.
    let names: Vec<String> = target.keys().cloned().collect();
    for name in names {
        let field_spec = props.as_object().and_then(|o| o.get(&name));
        // Under `dynamic: false`, unmapped keys are ignored-source —
        // their primitive-array leaves keep the original source order
        // rather than being re-sorted via doc_values.
        if field_spec.is_none() && parent_dynamic_false {
            continue;
        }
        let is_text = field_spec
            .and_then(|hp| hp.get("type"))
            .and_then(Value::as_str)
            .map(|t| t == "text" || t == "match_only_text" || t == "annotated_text")
            .unwrap_or(false);
        if is_text {
            continue;
        }
        // Per-field synthetic_source_keep overrides index default:
        //   none   → force sort (doc_values behaviour)
        //   arrays → preserve source order of the array
        //   all    → preserve source order of both array + non-array objects
        //   (unset)→ inherit index default (arrays vs sort)
        let keep_mode = field_spec
            .and_then(|hp| hp.get("synthetic_source_keep"))
            .and_then(Value::as_str);
        match keep_mode {
            Some("arrays") | Some("all") => continue,
            Some("none") => {} // force sort below
            _ => {
                if index_keep_arrays {
                    continue;
                }
            }
        }
        if let Some(Value::Array(arr)) = target.get_mut(&name) {
            let all_primitive = arr
                .iter()
                .all(|v| matches!(v, Value::Number(_) | Value::String(_) | Value::Bool(_)));
            if !all_primitive || arr.len() < 2 {
                continue;
            }
            arr.sort_by(|a, b| match (a, b) {
                (Value::Number(x), Value::Number(y)) => {
                    let xf = x.as_f64().unwrap_or(0.0);
                    let yf = y.as_f64().unwrap_or(0.0);
                    xf.partial_cmp(&yf).unwrap_or(std::cmp::Ordering::Equal)
                }
                (Value::String(x), Value::String(y)) => x.cmp(y),
                (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
                _ => std::cmp::Ordering::Equal,
            });
        }
    }
}

/// Flatten an array of homogeneous object values into column-major form:
///   [{a:10,b:20}, {a:100,b:200}]  →  {a:[10,100], b:[20,200]}
/// Recursively handles nested objects so that `[{p:{x:1}},{p:{x:2}}]`
/// becomes `{p:{x:[1,2]}}`. Inner arrays are spliced inline (ES
/// concatenates per-doc leaf values rather than preserving array-of-
/// array structure). Primitive leaves are sorted + deduped + unwrapped
/// to a scalar if exactly one distinct value remains — matching
/// doc_values semantics — unless the leaf's spec sets
/// `synthetic_source_keep: arrays|all`, in which case source order
/// is preserved. The `props` argument is the mapping-properties node
/// for the *contents* of each array element (i.e. the parent field's
/// `.properties` map). When `parent_dynamic_false` is true, unmapped
/// keys are treated as ignored_source (source order, no sort/dedupe).
/// Collapse a (possibly nested) object into single-level dotted-key form,
/// matching ES `flattened` synthetic-source reconstruction:
/// `{"host":{"name":"x"},"region":"y"}` -> `{"host.name":"x","region":"y"}`.
fn flatten_synthetic_dotted(prefix: &str, value: &Value, out: &mut serde_json::Map<String, Value>) {
    match value {
        Value::Object(o) => {
            for (k, v) in o {
                let key = if prefix.is_empty() {
                    k.clone()
                } else {
                    format!("{prefix}.{k}")
                };
                flatten_synthetic_dotted(&key, v, out);
            }
        }
        _ => {
            out.insert(prefix.to_string(), value.clone());
        }
    }
}

fn synthetic_flatten_object_array(
    arr: &[Value],
    props: &Value,
    parent_dynamic_false: bool,
    index_keep_arrays: bool,
) -> Value {
    let mut keys_in_order: Vec<String> = Vec::new();
    let mut groups: std::collections::HashMap<String, Vec<Value>> =
        std::collections::HashMap::new();
    for el in arr {
        let Value::Object(obj) = el else { continue };
        for (k, v) in obj {
            if !groups.contains_key(k) {
                keys_in_order.push(k.clone());
            }
            let entry = groups.entry(k.clone()).or_default();
            match v {
                Value::Array(inner) => {
                    for iv in inner {
                        entry.push(iv.clone());
                    }
                }
                _ => entry.push(v.clone()),
            }
        }
    }
    let mut out = serde_json::Map::new();
    for k in keys_in_order {
        let values = groups.remove(&k).unwrap_or_default();
        let child_spec = props.as_object().and_then(|o| o.get(&k));
        let child_keep = child_spec
            .and_then(|hp| hp.get("synthetic_source_keep"))
            .and_then(Value::as_str);
        let child_props = child_spec
            .and_then(|hp| hp.get("properties"))
            .cloned()
            .unwrap_or(Value::Null);

        let child_dynamic_false = child_spec
            .and_then(|hp| hp.get("dynamic"))
            .map(|v| match v {
                Value::Bool(false) => true,
                Value::String(s) => s == "false" || s == "runtime",
                _ => false,
            })
            .unwrap_or(false);
        // Effective keep wins before the column-major flatten: keep:arrays|all
        // (explicit per-field, or inherited from the index default) preserves
        // the concatenated source-order values verbatim — objects are NOT
        // flattened and primitives are NOT sorted/deduped.
        let effective_keep_arrays = match child_keep {
            Some("arrays") | Some("all") => true,
            Some("none") => false,
            _ => index_keep_arrays,
        };
        if effective_keep_arrays {
            out.insert(k, Value::Array(values));
            continue;
        }
        let all_objects = !values.is_empty() && values.iter().all(|v| v.is_object());
        if all_objects {
            out.insert(
                k,
                synthetic_flatten_object_array(
                    &values,
                    &child_props,
                    child_dynamic_false,
                    index_keep_arrays,
                ),
            );
            continue;
        }
        // Unmapped leaves under a `dynamic: false` parent are
        // ignored-source: their values are stored verbatim and come
        // back in source order (no doc_values sort/dedupe).
        if child_spec.is_none() && parent_dynamic_false {
            out.insert(k, Value::Array(values));
            continue;
        }
        let all_primitive = !values.is_empty()
            && values
                .iter()
                .all(|v| matches!(v, Value::Number(_) | Value::String(_) | Value::Bool(_)));
        if !all_primitive {
            out.insert(k, Value::Array(values));
            continue;
        }
        let mut sorted = values;
        sorted.sort_by(|a, b| match (a, b) {
            (Value::Number(x), Value::Number(y)) => {
                let xf = x.as_f64().unwrap_or(0.0);
                let yf = y.as_f64().unwrap_or(0.0);
                xf.partial_cmp(&yf).unwrap_or(std::cmp::Ordering::Equal)
            }
            (Value::String(x), Value::String(y)) => x.cmp(y),
            (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
            _ => std::cmp::Ordering::Equal,
        });
        sorted.dedup();
        if sorted.len() == 1 {
            out.insert(k, sorted.into_iter().next().unwrap());
        } else {
            out.insert(k, Value::Array(sorted));
        }
    }
    Value::Object(out)
}

/// Insert a dotted key into a target object following ES synthetic-source
/// rules: descend through mapped properties, split at the first unmapped
/// segment. The leaf value is set at the deepest reached position, with
/// any residual dots kept as a literal sub-key.
fn insert_synthetic_path(
    target: &mut serde_json::Map<String, Value>,
    props: &Value,
    key: &str,
    val: Value,
) {
    // Walk segments and collect the "descent path" (mapped segments to
    // descend into) and the "tail" (the final key and optional value key).
    let segments: Vec<&str> = key.split('.').collect();
    if segments.is_empty() {
        return;
    }
    let mut descent: Vec<String> = Vec::new();
    let mut current_props: Value = props.clone();
    let mut cursor = 0usize;
    while cursor < segments.len() {
        let seg = segments[cursor];
        let head_prop = current_props.as_object().and_then(|o| o.get(seg)).cloned();
        if let Some(hp) = head_prop {
            descent.push(seg.to_string());
            current_props = hp.get("properties").cloned().unwrap_or(Value::Null);
            cursor += 1;
            continue;
        }
        break;
    }
    // After descent, remaining = segments[cursor..].
    // Layout rules:
    // - If cursor == segments.len(): all segments mapped. Leaf is the
    //   last segment (pop from descent) and rest is the parent path.
    //   Insert val at descent/leaf.
    // - Else: `descent` is the fully-mapped prefix. Next segment
    //   (segments[cursor]) is an object key under descent. The
    //   REMAINING segments (cursor+1..) join with '.' to form the leaf
    //   literal-key. If there's only `segments[cursor]` left and no
    //   more, that's the literal leaf key.
    let (parent_path, leaf_key): (Vec<String>, String) = if cursor == segments.len() {
        // All mapped — last segment is the leaf, rest is descent path.
        let mut dp = descent.clone();
        let leaf = dp.pop().unwrap_or_default();
        (dp, leaf)
    } else if cursor + 1 == segments.len() {
        // One unmapped leaf after mapped descent.
        (descent.clone(), segments[cursor].to_string())
    } else {
        // descent + segments[cursor] as object key; segments[cursor+1..]
        // joined with '.' as literal leaf key.
        let mut dp = descent.clone();
        dp.push(segments[cursor].to_string());
        let literal_leaf = segments[cursor + 1..].join(".");
        (dp, literal_leaf)
    };
    // Navigate to parent, creating nested objects as needed.
    let mut cur: &mut serde_json::Map<String, Value> = target;
    for p in &parent_path {
        let entry = cur
            .entry(p.clone())
            .or_insert_with(|| Value::Object(serde_json::Map::new()));
        if !entry.is_object() {
            let old = entry.take();
            let mut m = serde_json::Map::new();
            m.insert("__xy_scalar__".to_string(), old);
            *entry = Value::Object(m);
        }
        cur = entry.as_object_mut().unwrap();
    }
    cur.insert(leaf_key, val);
}

/// Remove `__xy_*` internal tracking keys from every agg result before
/// handing the aggregations object to the response. The tracking fields
/// are only needed for cross-shard/cross-index metric merge and must not
/// leak to clients (ES never emits them).
fn strip_internal_tracking(v: &mut Value) {
    match v {
        Value::Object(o) => {
            o.retain(|k, _| !k.starts_with("__xy_"));
            for (_, child) in o.iter_mut() {
                strip_internal_tracking(child);
            }
        }
        Value::Array(arr) => {
            for item in arr.iter_mut() {
                strip_internal_tracking(item);
            }
        }
        _ => {}
    }
}

/// `from` in a search body: ES refuses a negative value with
/// `[from] parameter cannot be negative but was [-1]` (30_limits.yml) instead
/// of a generic JSON type error.
fn deserialize_non_negative_from<'de, D>(deserializer: D) -> Result<usize, D::Error>
where
    D: serde::Deserializer<'de>,
{
    struct FromVisitor;
    impl serde::de::Visitor<'_> for FromVisitor {
        type Value = usize;
        fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
            f.write_str("a non-negative integer")
        }
        fn visit_i64<E: serde::de::Error>(self, n: i64) -> Result<usize, E> {
            usize::try_from(n).map_err(|_| E::custom(negative_from_reason(n)))
        }
        // A huge positive `from` (e.g. u64::MAX) must reach the result-window
        // check rather than fail as a JSON type error.
        fn visit_u64<E: serde::de::Error>(self, n: u64) -> Result<usize, E> {
            Ok(usize::try_from(n).unwrap_or(usize::MAX))
        }
    }
    deserializer.deserialize_any(FromVisitor)
}

fn negative_from_reason(n: i64) -> String {
    format!("[from] parameter cannot be negative but was [{n}]")
}

/// ES's `illegal_argument_exception` for `?from=-1`.
fn negative_from_error(n: i64) -> Response {
    let reason = negative_from_reason(n);
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                "type": "illegal_argument_exception",
                "reason": reason,
            },
            "status": 400,
        })),
    )
        .into_response()
}

fn default_size() -> usize {
    10
}

/// Walk a request JSON subtree for inline Painless script sources — values
/// under a `script` key or any `*_script` key (e.g. scripted_metric's
/// `map_script`) — and validate each against the engine's script resource
/// limits. Returns the first limit-violation message, if any.
///
/// Only genuine limit violations (oversized source, or nesting depth beyond
/// the parser's cap) are reported. Ordinary scripts — including ones outside
/// our Painless subset — return `None` so they keep degrading gracefully at
/// score time rather than turning into spurious 400s (which would break
/// otherwise-passing requests and the ES-compat gate). This is the request-time
/// guard that converts an adversarial deeply-nested `script_score` from a
/// process-aborting stack overflow into a clean 400.
fn find_script_limit_violation(v: &Value) -> Option<String> {
    match v {
        Value::Object(map) => {
            for (k, val) in map {
                if k == "script" || k.ends_with("_script") {
                    let src = match val {
                        Value::String(s) => Some(s.as_str()),
                        Value::Object(o) => o.get("source").and_then(Value::as_str),
                        _ => None,
                    };
                    if let Some(src) = src {
                        if let Err(e) = xerj_engine::painless::check_script_limits(src) {
                            return Some(e);
                        }
                    }
                }
                if let Some(hit) = find_script_limit_violation(val) {
                    return Some(hit);
                }
            }
            None
        }
        Value::Array(arr) => arr.iter().find_map(find_script_limit_violation),
        _ => None,
    }
}

/// ES-shaped `script_exception` 400 for a script that hit one of the
/// interpreter's resource limits at *run* time.
///
/// `find_script_limit_violation` catches the statically-detectable limits up
/// front. The rest — closure call depth, total invocation count — depend on
/// the data and can only trip mid-evaluation, where the caller is a scoring or
/// aggregation path with no error channel. Those paths substituted a neutral
/// value (`0.0`, `[]`) and served it as if the script had succeeded; this is
/// what they surface instead.
pub(crate) fn script_limit_response(reason: &str) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(script_limit_error_value(reason)),
    )
        .into_response()
}

/// The same body as a bare value, for the multi-search surfaces that embed a
/// per-sub-request error object inside a 200 envelope rather than failing the
/// whole HTTP call.
pub(crate) fn script_limit_error_value(reason: &str) -> Value {
    json!({
        "error": {
            "root_cause": [{ "type": "script_exception", "reason": reason }],
            "type": "script_exception",
            "reason": reason,
        },
        "status": 400,
    })
}

/// The single definition of WHICH request fields the script guard walks.
///
/// Every search entry point resolves the guard through this enum: `_search`
/// (and the scroll / async-search paths) via [`GuardedField::in_search_body`],
/// `_msearch`, `_search/template` and `_msearch/template` — which hand a raw
/// body straight to `parse_request` — via [`GuardedField::in_raw_body`]. Both
/// resolvers are exhaustive `match`es over this enum, so a field cannot be
/// guarded on one entry point and skipped on another.
///
/// The set is deliberately the fields whose values actually carry scripts to
/// an executor. Walking a WHOLE body instead (what `_msearch` did between
/// #115 and this fix) makes the multi-search API *stricter* than `_search`:
/// an over-limit `script` key under an unguarded field — `highlight`,
/// `suggest`, `docvalue_fields`, `collapse.inner_hits` — 400'd on `_msearch`
/// while the identical body returned 200 on `_search`.
///
/// Top-level `knn` is deliberately not a variant. `_search` folds the spec
/// into the guarded `query` before `build_search_request` runs, so a script
/// under `knn.filter` is guarded there; the raw-body paths never execute a
/// top-level `knn` at all — `parse_request` reads no such key — so nothing
/// parked there reaches an executor. If `_msearch` ever grows top-level knn
/// support, it needs a variant here (see
/// `script_guard_symmetry_tests::msearch_does_not_execute_top_level_knn`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum GuardedField {
    Query,
    Rescore,
    Sort,
    ScriptFields,
    RuntimeMappings,
    /// `aggs`, with ES's `aggregations` spelling as an alias. The two are ONE
    /// value, never two independently-checked keys — see [`Self::in_raw_body`].
    Aggs,
}

impl GuardedField {
    /// Every guarded field. Adding a variant forces both resolvers below to
    /// be updated (their `match`es are exhaustive); add it here too so the
    /// walk actually reaches it.
    ///
    /// REMOVING an entry is the dangerous direction and the type system does
    /// not catch it. Every test over the guarded set iterates `ALL`, so they
    /// prove the guard covers whatever `ALL` currently holds, not that it
    /// holds six specific fields. Measured: deleting `Self::Rescore` leaves
    /// the whole suite green while an 80,001-byte `rescore` script goes from
    /// 400 to 200 on every entry point, which is exactly the bypass #111
    /// closed. The width assertion below is what catches that.
    const ALL: [GuardedField; 6] = [
        Self::Query,
        Self::Rescore,
        Self::Sort,
        Self::ScriptFields,
        Self::RuntimeMappings,
        Self::Aggs,
    ];

    /// The value this field carries in a raw JSON search body.
    ///
    /// `aggs`/`aggregations` resolve exactly the way the executor resolves
    /// them — `parse_request` does `obj.get("aggs").or_else(|| obj.get(
    /// "aggregations"))` (xerj-query `parser.rs`), so **`aggs` wins whenever
    /// both keys are present**, regardless of which appears first in the
    /// document (`serde_json` preserves order workspace-wide, so document
    /// order is observable and is NOT the rule) — and
    /// `build_search_request`'s caller does the same on the typed
    /// body. Checking the two keys independently instead would 400 a body
    /// whose over-limit script sits in the spelling the executor DISCARDS: a
    /// pure false positive, and an `_msearch`-vs-`_search` split of its own.
    fn in_raw_body(self, body: &Value) -> Option<&Value> {
        match self {
            Self::Query => body.get("query"),
            Self::Rescore => body.get("rescore"),
            Self::Sort => body.get("sort"),
            Self::ScriptFields => body.get("script_fields"),
            Self::RuntimeMappings => body.get("runtime_mappings"),
            Self::Aggs => body.get("aggs").or_else(|| body.get("aggregations")),
        }
    }

    /// The value this field carries in a typed [`EsSearchBody`]. `aggs_value`
    /// is the caller's already-resolved `aggs`/`aggregations` pair (same
    /// first-spelling-wins rule as [`Self::in_raw_body`]).
    fn in_search_body<'a>(
        self,
        body: &'a EsSearchBody,
        aggs_value: Option<&'a Value>,
    ) -> Option<&'a Value> {
        match self {
            Self::Query => body.query.as_ref(),
            Self::Rescore => body.rescore.as_ref(),
            Self::Sort => body.sort.as_ref(),
            Self::ScriptFields => body.script_fields.as_ref(),
            Self::RuntimeMappings => body.runtime_mappings.as_ref(),
            Self::Aggs => aggs_value,
        }
    }
}

/// The guard covers six fields. Adding a variant is already a compile error in
/// both exhaustive `match`es; this catches the other direction — silently
/// dropping an entry from [`GuardedField::ALL`], which every test iterates and
/// therefore none of them can detect. Change the number only alongside a
/// deliberate change to what `_search` validates.
const _: () = assert!(GuardedField::ALL.len() == 6);

/// Request-time script guard for a RAW search body — the shape `_msearch`,
/// `_search/template` and `_msearch/template` hand straight to
/// `parse_request`, skipping `build_search_request` and therefore the typed
/// guard. Inspects exactly the fields `_search` inspects.
fn find_body_script_limit_violation(body: &Value) -> Option<String> {
    GuardedField::ALL
        .iter()
        .filter_map(|field| field.in_raw_body(body))
        .find_map(find_script_limit_violation)
}

/// Request-time script guard for a typed [`EsSearchBody`] (`_search`, scroll,
/// async search). Same field set as [`find_body_script_limit_violation`].
fn find_search_body_script_limit_violation(
    body: &EsSearchBody,
    aggs_value: Option<&Value>,
) -> Option<String> {
    GuardedField::ALL
        .iter()
        .filter_map(|field| field.in_search_body(body, aggs_value))
        .find_map(find_script_limit_violation)
}

/// Request-time check of every `terms` aggregation's `order` paths (#1283).
///
/// ES rejects an order key that names an aggregation the request does not
/// define with a 400 (`Invalid aggregation order path [nope]. Cannot find
/// aggregation named [nope]`, verified against ES 8.13.4). The executor has no
/// error channel for it: an unresolvable path compared every bucket as equal
/// and fell through to the key tiebreaker, so a typo produced a plausible but
/// wrongly ordered HTTP 200. Checked on the request, before execution, so the
/// answer is the same whichever executor path (fast or general) the
/// aggregation later takes.
///
/// A path is `agg1>agg2>…>aggN`, where the last element may carry a value key
/// (`p.95`, `p[95.0]`). Each element's name must be a sub-aggregation of the
/// level before it; `_count` and `_key` are the built-in keys. Value keys are
/// not validated here — that stays the executor's (lenient) business.
fn find_invalid_agg_order_path(aggs: Option<&Value>) -> Option<String> {
    fn sub_aggs(def: &Value) -> Option<&Value> {
        def.get("aggs").or_else(|| def.get("aggregations"))
    }
    fn order_keys(order: &Value) -> Vec<&str> {
        match order {
            Value::Object(o) => o.keys().map(String::as_str).collect(),
            Value::Array(arr) => arr
                .iter()
                .filter_map(Value::as_object)
                .flat_map(|o| o.keys().map(String::as_str))
                .collect(),
            _ => Vec::new(),
        }
    }
    fn check_path(path: &str, mut level: Option<&Value>) -> Option<String> {
        if path == "_count" || path == "_key" {
            return None;
        }
        for element in path.split('>') {
            let name = element
                .find(['.', '['])
                .map_or(element, |at| &element[..at]);
            match level.and_then(|defs| defs.get(name)) {
                Some(def) => level = sub_aggs(def),
                None => {
                    return Some(format!(
                        "Invalid aggregation order path [{path}]. Cannot find aggregation named [{name}]"
                    ))
                }
            }
        }
        None
    }
    let defs = aggs?.as_object()?;
    for def in defs.values() {
        let subs = sub_aggs(def);
        if let Some(order) = def.get("terms").and_then(|t| t.get("order")) {
            for path in order_keys(order) {
                if let Some(reason) = check_path(path, subs) {
                    return Some(reason);
                }
            }
        }
        if let Some(reason) = find_invalid_agg_order_path(subs) {
            return Some(reason);
        }
    }
    None
}

/// Request-time check of `composite` aggregation definitions.
///
/// Elasticsearch refuses these at parse time with a 400; XERJ's
/// `run_composite` instead answered 200 with an empty bucket list (missing or
/// empty `sources`), silently let a later source overwrite an earlier one of
/// the same name, ignored a `missing_order` that can never apply, accepted a
/// page `size` far above `search.max_buckets`, and ran under any parent.
/// Messages are ES 8.13's, as pinned by `aggregations/composite.yml`:
///
/// * `sources` absent → `Required [sources]`; empty or not a list →
///   `Composite [sources] cannot be null or empty`;
/// * two sources with one name → `Composite source names must be unique,
///   found duplicates: [..]`;
/// * `missing_order` other than `default` without `missing_bucket: true` →
///   `missingOrder can only be set if missingBucket is true`;
/// * `size` above `search.max_buckets` → ES's too-many-buckets message;
/// * a parent other than `nested`, `reverse_nested` or `filter` (through any
///   chain of those) → `[composite] aggregation cannot be used with a parent
///   aggregation of type: [..AggregatorFactory]`.
fn find_invalid_composite_agg(aggs: Option<&Value>) -> Option<String> {
    fn sub_aggs(def: &Value) -> Option<&Value> {
        def.get("aggs").or_else(|| def.get("aggregations"))
    }
    fn kind_of(def: &Value) -> Option<(&str, &Value)> {
        def.as_object()?
            .iter()
            .find(|(k, _)| !matches!(k.as_str(), "aggs" | "aggregations" | "meta"))
            .map(|(k, v)| (k.as_str(), v))
    }
    /// ES names the blocking parent by its factory class:
    /// `terms` → `TermsAggregatorFactory`, `date_histogram` →
    /// `DateHistogramAggregatorFactory`.
    fn factory_name(kind: &str) -> String {
        let camel: String = kind
            .split('_')
            .map(|part| {
                let mut chars = part.chars();
                chars
                    .next()
                    .map(|c| c.to_ascii_uppercase().to_string() + chars.as_str())
                    .unwrap_or_default()
            })
            .collect();
        format!("{camel}AggregatorFactory")
    }
    fn check(params: &Value, blocking_parent: Option<&str>) -> Option<String> {
        let sources = match params.get("sources") {
            None => return Some("Required [sources]".to_string()),
            Some(Value::Array(a)) if !a.is_empty() => a,
            Some(_) => return Some("Composite [sources] cannot be null or empty".to_string()),
        };
        let mut seen = std::collections::HashSet::new();
        let mut duplicates = Vec::new();
        for source in sources {
            let Some(obj) = source.as_object() else {
                continue;
            };
            for (name, def) in obj {
                if !seen.insert(name.as_str()) && !duplicates.contains(name) {
                    duplicates.push(name.clone());
                }
                // `{name: {terms|histogram|...: {..., missing_order}}}`
                let inner = def.as_object().and_then(|d| d.values().next());
                if let Some(inner) = inner {
                    let order = inner.get("missing_order").and_then(Value::as_str);
                    let bucket = inner
                        .get("missing_bucket")
                        .and_then(Value::as_bool)
                        .unwrap_or(false);
                    if matches!(order, Some(o) if o != "default") && !bucket {
                        return Some(
                            "missingOrder can only be set if missingBucket is true".to_string(),
                        );
                    }
                }
            }
        }
        if !duplicates.is_empty() {
            return Some(format!(
                "Composite source names must be unique, found duplicates: [{}]",
                duplicates.join(", ")
            ));
        }
        let cap = xerj_engine::aggs::max_buckets() as u64;
        if let Some(size) = params.get("size").and_then(Value::as_u64) {
            if size > cap {
                return Some(format!(
                    "Trying to create too many buckets. Must be less than or equal to: [{cap}] \
                     but was [{size}]. This limit can be set by changing the \
                     [search.max_buckets] cluster level setting."
                ));
            }
        }
        if let Some(parent) = blocking_parent {
            return Some(format!(
                "[composite] aggregation cannot be used with a parent aggregation of type: [{}]",
                factory_name(parent)
            ));
        }
        None
    }
    fn walk(
        level: &serde_json::Map<String, Value>,
        blocking_parent: Option<&str>,
    ) -> Option<String> {
        for def in level.values() {
            let Some((kind, params)) = kind_of(def) else {
                continue;
            };
            if kind == "composite" {
                if let Some(reason) = check(params, blocking_parent) {
                    return Some(reason);
                }
            }
            // ES lets a composite sit under nested / reverse_nested / filter
            // (any chain of them); any other parent blocks it.
            let below = if matches!(kind, "nested" | "reverse_nested" | "filter") {
                blocking_parent
            } else {
                Some(kind)
            };
            if let Some(subs) = sub_aggs(def).and_then(Value::as_object) {
                if let Some(reason) = walk(subs, below) {
                    return Some(reason);
                }
            }
        }
        None
    }
    walk(aggs?.as_object()?, None)
}

#[cfg(test)]
mod composite_agg_validation_tests {
    use super::find_invalid_composite_agg;
    use serde_json::json;

    fn check(aggs: serde_json::Value) -> Option<String> {
        find_invalid_composite_agg(Some(&aggs))
    }

    /// Shapes `aggregations/composite.yml` already passes with must stay
    /// valid: top level, under nested / reverse_nested / filter chains, with
    /// `missing_bucket: true` and an order, and with a sane `size`.
    #[test]
    fn valid_composites_pass() {
        for aggs in [
            json!({"c": {"composite": {"size": 10, "sources": [
                {"kw": {"terms": {"field": "keyword"}}},
                {"long": {"terms": {"field": "long", "missing_bucket": true,
                                    "missing_order": "last"}}},
                {"d": {"terms": {"field": "date", "missing_order": "default"}}}]}}}),
            json!({"n": {"nested": {"path": "nested"},
                         "aggs": {"f": {"filter": {"term": {"x": 1}},
                                        "aggs": {"r": {"reverse_nested": {},
                                                       "aggs": {"c": {"composite": {"sources": [
                                                           {"kw": {"terms": {"field": "keyword"}}}]}}}}}}}}}),
            // A composite with sub-aggregations, and an unrelated terms
            // whose child is NOT a composite.
            json!({"c": {"composite": {"sources": [{"kw": {"terms": {"field": "keyword"}}}]},
                         "aggs": {"t": {"terms": {"field": "x"}}}},
                   "t": {"terms": {"field": "y"}, "aggs": {"m": {"max": {"field": "z"}}}}}),
        ] {
            assert_eq!(check(aggs.clone()), None, "{aggs}");
        }
    }

    #[test]
    fn invalid_composites_are_refused_with_es_messages() {
        let cases = [
            (json!({"c": {"composite": {"size": 1}}}), "Required [sources]"),
            (json!({"c": {"composite": {"sources": []}}}),
             "Composite [sources] cannot be null or empty"),
            (json!({"c": {"composite": {"sources": [
                {"keyword": {"terms": {"field": "keyword"}}},
                {"keyword": {"terms": {"field": "long"}}}]}}}),
             "Composite source names must be unique, found duplicates: [keyword]"),
            (json!({"c": {"composite": {"sources": [
                {"kw": {"terms": {"field": "keyword", "missing_order": "first"}}}]}}}),
             "missingOrder can only be set if missingBucket is true"),
            (json!({"c": {"composite": {"size": 1_000_000_000u64, "sources": [
                {"kw": {"terms": {"field": "keyword"}}}]}}}),
             "Trying to create too many buckets"),
            (json!({"t": {"terms": {"field": "long"},
                          "aggs": {"c": {"composite": {"sources": [
                              {"kw": {"terms": {"field": "keyword"}}}]}}}}}),
             "[composite] aggregation cannot be used with a parent aggregation of type: [TermsAggregatorFactory]"),
        ];
        for (aggs, want) in cases {
            let got = check(aggs.clone()).unwrap_or_else(|| panic!("not refused: {aggs}"));
            assert!(got.contains(want), "{aggs}\n got: {got}\nwant: {want}");
        }
    }
}

/// Request-time check of aggregation parameters and structure that
/// Elasticsearch rejects at parse time with a 400, where XERJ answered 200
/// (ignoring the bad value, or returning an empty/defaulted result). Messages
/// are ES 8.13's, as pinned by the ES-YAML suite:
///
/// * `meta` that is not an object;
/// * `cardinality`: negative `precision_threshold`, unknown `execution_hint`;
/// * `filters` with no filters;
/// * `ip_prefix`: `prefix_length` outside `[0, 32]` (`[0, 128]` for IPv6);
/// * `median_absolute_deviation`: `compression` ≤ 0, unknown `execution_hint`;
/// * `percentiles` / `percentile_ranks`: negative `tdigest.compression`,
///   unknown `tdigest.execution_hint`, and `percentile_ranks` without usable
///   `values`;
/// * `terms` with neither `field` nor `script`;
/// * `random_sampler`: `probability` outside `(0, 0.5]` ∪ `{1.0}`, no
///   sub-aggregations, a parent, or a sampler / time_series below it;
/// * `time_series` under `global`, or in a request that also uses an
///   aggregation incompatible with time-series execution (`composite`,
///   `auto_date_histogram`, `variable_width_histogram`, `rare_terms`).
///
/// Checks that need the field's mapped type (e.g. `avg` on a keyword field)
/// are not made here.
fn find_invalid_agg_params(aggs: Option<&Value>) -> Option<String> {
    const TDIGEST_HINTS: &[&str] = &["default", "high_accuracy"];
    const CARDINALITY_HINTS: &[&str] = &[
        "global_ordinals",
        "segment_ordinals",
        "direct",
        "save_memory_heuristic",
        "save_time_heuristic",
    ];
    const TIME_SERIES_INCOMPATIBLE: &[&str] = &[
        "composite",
        "auto_date_histogram",
        "variable_width_histogram",
        "rare_terms",
    ];
    fn sub_aggs(def: &Value) -> Option<&serde_json::Map<String, Value>> {
        def.get("aggs")
            .or_else(|| def.get("aggregations"))
            .and_then(Value::as_object)
    }
    fn kind_of(def: &Value) -> Option<(&str, &Value)> {
        def.as_object()?
            .iter()
            .find(|(k, _)| !matches!(k.as_str(), "aggs" | "aggregations" | "meta"))
            .map(|(k, v)| (k.as_str(), v))
    }
    /// The parser token ES names for a JSON value.
    fn token(v: &Value) -> &'static str {
        match v {
            Value::Null => "VALUE_NULL",
            Value::Bool(_) => "VALUE_BOOLEAN",
            Value::Number(_) => "VALUE_NUMBER",
            Value::String(_) => "VALUE_STRING",
            Value::Array(_) => "START_ARRAY",
            Value::Object(_) => "START_OBJECT",
        }
    }
    fn hint_error(hint: &str) -> String {
        format!("Invalid execution_hint [{hint}], valid values are [default, high_accuracy]")
    }
    /// `tdigest` options shared by `percentiles` and `percentile_ranks`.
    fn check_tdigest(params: &Value) -> Option<String> {
        let tdigest = params.get("tdigest")?;
        if let Some(c) = tdigest.get("compression").and_then(Value::as_f64) {
            if c < 0.0 {
                return Some(format!(
                    "[compression] must be greater than or equal to 0. Found [{c:?}]"
                ));
            }
        }
        match tdigest.get("execution_hint").and_then(Value::as_str) {
            Some(h) if !TDIGEST_HINTS.contains(&h) => Some(hint_error(h)),
            _ => None,
        }
    }
    /// Every descendant definition below `def`, as `(type, name)`.
    fn descendants<'a>(def: &'a Value, out: &mut Vec<(&'a str, &'a str)>) {
        for (name, child) in sub_aggs(def).into_iter().flatten() {
            if let Some((kind, _)) = kind_of(child) {
                out.push((kind, name.as_str()));
            }
            descendants(child, out);
        }
    }
    fn has_kind(level: &serde_json::Map<String, Value>, kind: &str) -> bool {
        level.values().any(|def| {
            kind_of(def).is_some_and(|(k, _)| k == kind)
                || sub_aggs(def).is_some_and(|subs| has_kind(subs, kind))
        })
    }
    fn check_def(
        name: &str,
        def: &Value,
        kind: &str,
        params: &Value,
        ancestors: &[&str],
        time_series_request: bool,
    ) -> Option<String> {
        if let Some(meta) = def.get("meta") {
            if !meta.is_object() {
                return Some(format!(
                    "Expected [START_OBJECT] under [meta], but got a [{}] in [{name}]",
                    token(meta)
                ));
            }
        }
        match kind {
            "cardinality" => {
                if let Some(p) = params.get("precision_threshold").and_then(Value::as_i64) {
                    if p < 0 {
                        return Some(format!(
                            "[precisionThreshold] must be greater than or equal to 0. \
                             Found [{p}] in [{name}]"
                        ));
                    }
                }
                if let Some(h) = params.get("execution_hint").and_then(Value::as_str) {
                    if !CARDINALITY_HINTS.contains(&h) {
                        return Some(format!(
                            "Invalid execution mode for cardinality aggregation. Got [{h}]\
                             expected one of [{}]",
                            CARDINALITY_HINTS.join(", ")
                        ));
                    }
                }
            }
            "filters" => {
                let empty = match params.get("filters") {
                    None | Some(Value::Null) => true,
                    Some(Value::Array(a)) => a.is_empty(),
                    Some(Value::Object(o)) => o.is_empty(),
                    Some(_) => false,
                };
                if empty {
                    return Some("[filters] cannot be empty.".to_string());
                }
            }
            "ip_prefix" => {
                let max = if params.get("is_ipv6").and_then(Value::as_bool) == Some(true) {
                    128
                } else {
                    32
                };
                if let Some(len) = params.get("prefix_length").and_then(Value::as_i64) {
                    if !(0..=max).contains(&len) {
                        return Some(format!(
                            "[prefix_length] must be in range [0, {max}] while value is [{len}]"
                        ));
                    }
                }
            }
            "median_absolute_deviation" => {
                if let Some(c) = params.get("compression").and_then(Value::as_f64) {
                    if c <= 0.0 {
                        return Some(format!(
                            "[compression] must be greater than 0. Found [{c:?}] in [{name}]"
                        ));
                    }
                }
                if let Some(h) = params.get("execution_hint").and_then(Value::as_str) {
                    if !TDIGEST_HINTS.contains(&h) {
                        return Some(hint_error(h));
                    }
                }
            }
            "percentiles" => return check_tdigest(params),
            "percentile_ranks" => {
                if let Some(e) = check_tdigest(params) {
                    return Some(e);
                }
                match params.get("values") {
                    None | Some(Value::Null) => {
                        return Some(format!("[values] must not be null: [{name}]"))
                    }
                    Some(Value::Array(a)) if a.is_empty() => {
                        return Some(format!("[values] must not be an empty array: [{name}]"))
                    }
                    Some(Value::Array(a)) if !a.iter().all(Value::is_number) => {
                        return Some(format!("[values] must be numbers: [{name}]"))
                    }
                    _ => {}
                }
            }
            "terms" => {
                if params.get("field").is_none() && params.get("script").is_none() {
                    return Some(
                        "Required one of fields [field, script], but none were specified."
                            .to_string(),
                    );
                }
            }
            "random_sampler" => {
                if let Some(p) = params.get("probability").and_then(Value::as_f64) {
                    if p <= 0.0 {
                        return Some(format!(
                            "[probability] must be greater than 0.0, was [{p:?}]"
                        ));
                    }
                    if p > 0.5 && p != 1.0 {
                        return Some(format!(
                            "[probability] must be between 0.0 and 0.5 or exactly 1.0, \
                             was [{p:?}]"
                        ));
                    }
                }
                if !ancestors.is_empty() {
                    return Some(format!(
                        "[random_sampler] aggregation [{name}] cannot have a parent aggregation"
                    ));
                }
                if sub_aggs(def).is_none_or(serde_json::Map::is_empty) {
                    return Some(format!(
                        "[random_sampler] aggregation [{name}] must have sub-aggregations"
                    ));
                }
                let mut below = Vec::new();
                descendants(def, &mut below);
                if let Some((k, n)) = below.iter().find(|(k, _)| {
                    matches!(
                        *k,
                        "sampler" | "diversified_sampler" | "random_sampler" | "time_series"
                    )
                }) {
                    return Some(format!(
                        "[random_sampler] aggregation [{name}] does not support sampling \
                         [{k}] aggregation [{n}]"
                    ));
                }
            }
            "time_series" if ancestors.contains(&"global") => {
                return Some(
                    "Time series aggregations cannot be used inside global aggregation."
                        .to_string(),
                );
            }
            _ => {}
        }
        if time_series_request && TIME_SERIES_INCOMPATIBLE.contains(&kind) {
            let shown = if kind == "composite" {
                "composite"
            } else {
                name
            };
            return Some(format!(
                "[{shown}] aggregation is incompatible with time series execution mode"
            ));
        }
        None
    }
    fn walk<'a>(
        level: &'a serde_json::Map<String, Value>,
        ancestors: &mut Vec<&'a str>,
        time_series_request: bool,
    ) -> Option<String> {
        for (name, def) in level {
            let Some((kind, params)) = kind_of(def) else {
                continue;
            };
            if let Some(reason) = check_def(name, def, kind, params, ancestors, time_series_request)
            {
                return Some(reason);
            }
            if let Some(subs) = sub_aggs(def) {
                ancestors.push(kind);
                let found = walk(subs, ancestors, time_series_request);
                ancestors.pop();
                if found.is_some() {
                    return found;
                }
            }
        }
        None
    }
    let level = aggs?.as_object()?;
    let time_series_request = has_kind(level, "time_series");
    walk(level, &mut Vec::new(), time_series_request)
}

#[cfg(test)]
mod agg_param_validation_tests {
    use super::find_invalid_agg_params;
    use serde_json::json;

    fn check(aggs: serde_json::Value) -> Option<String> {
        find_invalid_agg_params(Some(&aggs))
    }

    /// Valid shapes the suite already passes with must never be refused.
    #[test]
    fn valid_aggregations_pass() {
        for aggs in [
            json!({"c": {"cardinality": {"field": "f", "precision_threshold": 0,
                                         "execution_hint": "save_memory_heuristic"}}}),
            json!({"m": {"median_absolute_deviation": {"field": "f", "compression": 500,
                                                       "execution_hint": "high_accuracy"}}}),
            json!({"p": {"percentiles": {"field": "f", "tdigest": {"compression": 200,
                                                                   "execution_hint": "default"}}}}),
            json!({"r": {"percentile_ranks": {"field": "f", "values": [50, 99],
                                              "hdr": {"number_of_significant_value_digits": 3}}}}),
            json!({"i": {"ip_prefix": {"field": "ip", "is_ipv6": true, "prefix_length": 64}}}),
            json!({"t": {"terms": {"script": {"source": "doc['f'].value"}}}}),
            json!({"f": {"meta": {"k": "v"},
                         "filters": {"filters": {"a": {"match": {"x": 1}}}}}}),
            json!({"s": {"random_sampler": {"probability": 0.1},
                         "aggs": {"m": {"avg": {"field": "v"}}}}}),
            json!({"s": {"random_sampler": {"probability": 1.0},
                         "aggs": {"m": {"avg": {"field": "v"}}}}}),
            json!({"ts": {"time_series": {"keyed": false},
                          "aggs": {"d": {"date_histogram": {"field": "@timestamp",
                                                            "fixed_interval": "1h"}}}}}),
            // An incompatible type is fine when the request has no time_series.
            json!({"c": {"composite": {"sources": [{"k": {"terms": {"field": "k"}}}]}},
                   "r": {"rare_terms": {"field": "k"}}}),
        ] {
            assert_eq!(check(aggs.clone()), None, "{aggs}");
        }
    }

    #[test]
    fn invalid_parameters_are_refused_with_es_messages() {
        let cases = [
            (json!({"distinct_int": {"cardinality": {"field": "f", "precision_threshold": -1}}}),
             "[precisionThreshold] must be greater than or equal to 0. Found [-1] in [distinct_int]"),
            (json!({"c": {"cardinality": {"field": "f", "execution_hint": "bogus"}}}),
             "Invalid execution mode for cardinality aggregation"),
            (json!({"the_filter": {"filters": {}}}), "[filters] cannot be empty"),
            (json!({"the_filter": {"meta": null, "filters": {"filters": {"a": {"match_all": {}}}}}}),
             "Expected [START_OBJECT] under [meta], but got a [VALUE_NULL] in [the_filter]"),
            (json!({"i": {"ip_prefix": {"field": "ip", "is_ipv6": false, "prefix_length": 44}}}),
             "[prefix_length] must be in range [0, 32] while value is [44]"),
            (json!({"mad": {"median_absolute_deviation": {"field": "f", "compression": 0}}}),
             "[compression] must be greater than 0. Found [0.0] in [mad]"),
            (json!({"p": {"percentiles": {"field": "f", "tdigest": {"execution_hint": "no_such_hint"}}}}),
             "Invalid execution_hint [no_such_hint], valid values are [default, high_accuracy]"),
            (json!({"r": {"percentile_ranks": {"field": "f", "values": []}}}),
             "[values] must not be an empty array: [r]"),
            (json!({"t": {"terms": {"size": 1}}}),
             "Required one of fields [field, script], but none were specified"),
            (json!({"sampled": {"random_sampler": {"probability": 1.5},
                                "aggs": {"m": {"avg": {"field": "v"}}}}}),
             "[probability] must be between 0.0 and 0.5 or exactly 1.0, was [1.5]"),
            (json!({"terms": {"terms": {"field": "p"},
                              "aggs": {"sampled": {"random_sampler": {"probability": 0.1},
                                                   "aggs": {"m": {"max": {"field": "v"}}}}}}}),
             "[random_sampler] aggregation [sampled] cannot have a parent aggregation"),
            (json!({"global": {"global": {}, "aggs": {"ts": {"time_series": {}}}}}),
             "Time series aggregations cannot be used inside global aggregation."),
            (json!({"by_time": {"auto_date_histogram": {"field": "@timestamp"},
                                "aggs": {"ts": {"time_series": {}}}}}),
             "[by_time] aggregation is incompatible with time series execution mode"),
        ];
        for (aggs, want) in cases {
            let got = check(aggs.clone()).unwrap_or_else(|| panic!("not refused: {aggs}"));
            assert!(got.contains(want), "{aggs}\n got: {got}\nwant: {want}");
        }
    }
}

/// Request-time check of pipeline-aggregation placement and `buckets_path`s.
///
/// Elasticsearch rejects these with a 400 before running the search; XERJ
/// answered 200 with a `null` (or silently skipped) pipeline value, so a
/// misplaced pipeline or a typo in its path looked like "no data". Messages
/// and rules are ES 8.13's, as pinned by the ES-YAML suite (the cases this
/// removes from `catch-lenient.txt`):
///
/// * `derivative` / `cumulative_sum` / `serial_diff` / `moving_fn` /
///   `cumulative_cardinality` / `moving_percentiles` need a `histogram`,
///   `date_histogram` or `auto_date_histogram` parent;
/// * `bucket_script` / `bucket_selector` / `bucket_sort` must be declared
///   inside another aggregation, and that parent must be multi-bucket;
/// * `bucket_sort` must have something to do (`sort`, `size` or `from`);
/// * `moving_fn`'s `window` must be positive;
/// * every `buckets_path` (and every `bucket_sort` sort key) must name
///   aggregations that exist, resolved from the level the pipeline is
///   declared at — ES's `No aggregation found for path [p]` /
///   `No aggregation [x] found for path [p]` validation failures.
///
/// Path checking is deliberately one-sided: it reports a path only when no
/// reading of it can name an existing aggregation. Value keys (`p.99`,
/// `p[99.9]`, `stats.avg`), dotted aggregation names (`v.v`) and anything
/// past a metric aggregation are left to the executor, as before.
///
/// Checked on the request, like [`find_invalid_agg_order_path`], so the
/// answer does not depend on which executor (fast or general) would run it.
fn find_invalid_pipeline_agg(aggs: Option<&Value>) -> Option<String> {
    const SEQUENTIAL: &[&str] = &[
        "derivative",
        "cumulative_sum",
        "serial_diff",
        "moving_fn",
        "cumulative_cardinality",
        "moving_percentiles",
    ];
    const SEQUENTIAL_PARENTS: &[&str] = &["histogram", "date_histogram", "auto_date_histogram"];
    const MULTI_BUCKET_PIPELINES: &[&str] = &["bucket_script", "bucket_selector", "bucket_sort"];
    const SIBLING: &[&str] = &[
        "avg_bucket",
        "max_bucket",
        "min_bucket",
        "sum_bucket",
        "stats_bucket",
        "extended_stats_bucket",
        "percentiles_bucket",
    ];
    /// Aggregations whose result has no sub-aggregations to walk into: a
    /// path that reaches one stops being checked (what follows is a value
    /// key, the executor's business).
    const LEAF: &[&str] = &[
        "avg",
        "sum",
        "min",
        "max",
        "value_count",
        "cardinality",
        "stats",
        "extended_stats",
        "percentiles",
        "percentile_ranks",
        "top_hits",
        "top_metrics",
        "weighted_avg",
        "median_absolute_deviation",
        "scripted_metric",
        "matrix_stats",
        "string_stats",
        "boxplot",
        "t_test",
        "rate",
        "geo_bounds",
        "geo_centroid",
        "geo_line",
    ];
    /// ES names a single-bucket parent by its internal result class.
    fn single_bucket_class(kind: &str) -> Option<&'static str> {
        Some(match kind {
            "filter" => "InternalFilter",
            "global" => "InternalGlobal",
            "nested" => "InternalNested",
            "reverse_nested" => "InternalReverseNested",
            "sampler" | "diversified_sampler" => "InternalSampler",
            "random_sampler" => "InternalRandomSampler",
            "missing" => "InternalMissing",
            _ => return None,
        })
    }
    fn sub_aggs(def: &Value) -> Option<&Value> {
        def.get("aggs").or_else(|| def.get("aggregations"))
    }
    /// The aggregation type key of one definition (`{"avg": {...}, "aggs": ...}`).
    fn kind_of(def: &Value) -> Option<(&str, &Value)> {
        def.as_object()?
            .iter()
            .find(|(k, _)| !matches!(k.as_str(), "aggs" | "aggregations" | "meta"))
            .map(|(k, v)| (k.as_str(), v))
    }
    fn is_pipeline(kind: &str) -> bool {
        SEQUENTIAL.contains(&kind)
            || MULTI_BUCKET_PIPELINES.contains(&kind)
            || SIBLING.contains(&kind)
    }
    /// One path element as an aggregation name at `level`: the whole element
    /// (minus a `[key]` suffix), or failing that a prefix before a `.` (a
    /// dotted value key such as `the_percentiles.99`). Returns the matched
    /// definition and whether a value key followed the name.
    fn resolve<'a>(
        level: &'a serde_json::Map<String, Value>,
        element: &str,
    ) -> Option<(&'a Value, bool)> {
        let bracketless = element.find('[').map_or(element, |at| &element[..at]);
        if let Some(def) = level.get(bracketless) {
            return Some((def, bracketless.len() != element.len()));
        }
        bracketless
            .rmatch_indices('.')
            .find_map(|(at, _)| level.get(&bracketless[..at]))
            .map(|def| (def, true))
    }
    /// ES's `No aggregation ... found for path [...]`, or `None` when some
    /// reading of `path` names existing aggregations from `level`.
    fn check_path(path: &str, level: Option<&serde_json::Map<String, Value>>) -> Option<String> {
        let elements: Vec<&str> = path.split('>').collect();
        let mut level = level;
        for (i, element) in elements.iter().enumerate() {
            let last = i + 1 == elements.len();
            if last && matches!(*element, "_count" | "_key" | "_bucket_count") {
                return None;
            }
            let found = level.and_then(|defs| resolve(defs, element));
            let Some((def, value_key)) = found else {
                return Some(if i == 0 {
                    format!("No aggregation found for path [{path}]")
                } else {
                    format!("No aggregation [{element}] found for path [{path}]")
                });
            };
            let kind = kind_of(def).map(|(k, _)| k).unwrap_or("");
            if value_key || LEAF.contains(&kind) || is_pipeline(kind) {
                return None;
            }
            level = sub_aggs(def).and_then(Value::as_object);
        }
        None
    }
    /// Every `buckets_path` string of a pipeline: a string, the values of an
    /// `{alias: path}` object, or the entries of an array.
    fn buckets_paths(params: &Value) -> Vec<&str> {
        match params.get("buckets_path") {
            Some(Value::String(s)) => vec![s.as_str()],
            Some(Value::Object(o)) => o.values().filter_map(Value::as_str).collect(),
            Some(Value::Array(a)) => a.iter().filter_map(Value::as_str).collect(),
            _ => Vec::new(),
        }
    }
    /// `bucket_sort`'s sort keys that name aggregations (not `_key`/`_count`).
    fn sort_paths(params: &Value) -> Vec<&str> {
        let keys: Vec<&str> = match params.get("sort") {
            Some(Value::String(s)) => vec![s.as_str()],
            Some(Value::Object(o)) => o.keys().map(String::as_str).collect(),
            Some(Value::Array(a)) => a
                .iter()
                .flat_map(|e| match e {
                    Value::String(s) => vec![s.as_str()],
                    Value::Object(o) => o.keys().map(String::as_str).collect(),
                    _ => Vec::new(),
                })
                .collect(),
            _ => Vec::new(),
        };
        keys.into_iter()
            .filter(|k| !matches!(*k, "_key" | "_count"))
            .collect()
    }
    fn walk(
        level: &serde_json::Map<String, Value>,
        parent: Option<&str>,
        errors: &mut Vec<String>,
    ) {
        for (name, def) in level {
            let Some((kind, params)) = kind_of(def) else {
                continue;
            };
            if SEQUENTIAL.contains(&kind) {
                match parent {
                    None => errors.push(format!(
                        "{kind} aggregation [{name}] must have a histogram, date_histogram or \
                         auto_date_histogram as parent but doesn't have a parent"
                    )),
                    Some(p) if !SEQUENTIAL_PARENTS.contains(&p) => errors.push(format!(
                        "{kind} aggregation [{name}] must have a histogram, date_histogram or \
                         auto_date_histogram as parent"
                    )),
                    Some(_) => {}
                }
            }
            if MULTI_BUCKET_PIPELINES.contains(&kind) {
                match parent.map(|p| (p, single_bucket_class(p))) {
                    None => errors.push(format!(
                        "{kind} aggregation [{name}] must be declared inside of another aggregation"
                    )),
                    Some((_, Some(class))) => errors.push(format!(
                        "Expected a multi bucket aggregation but got [{class}] for aggregation [{name}]"
                    )),
                    Some((_, None)) => {}
                }
            }
            if kind == "bucket_sort" {
                let has_sort = match params.get("sort") {
                    Some(Value::Array(a)) => !a.is_empty(),
                    Some(Value::Null) | None => false,
                    Some(_) => true,
                };
                let from = params.get("from").and_then(Value::as_u64).unwrap_or(0);
                if !has_sort && params.get("size").is_none() && from == 0 {
                    errors.push(format!(
                        "[{name}] is configured to perform nothing. Please set either of \
                         [sort, size, from] to use bucket_sort"
                    ));
                }
            }
            if kind == "moving_fn" {
                if let Some(w) = params.get("window").and_then(Value::as_i64) {
                    if w <= 0 {
                        errors.push("[window] must be a positive, non-zero integer.".to_string());
                    }
                }
            }
            if is_pipeline(kind) {
                let paths = if kind == "bucket_sort" {
                    sort_paths(params)
                } else {
                    buckets_paths(params)
                };
                for path in paths {
                    if let Some(e) = check_path(path, Some(level)) {
                        errors.push(e);
                    }
                }
            }
            if let Some(subs) = sub_aggs(def).and_then(Value::as_object) {
                walk(subs, Some(kind), errors);
            }
        }
    }
    let mut errors = Vec::new();
    walk(aggs?.as_object()?, None, &mut errors);
    if errors.is_empty() {
        return None;
    }
    let numbered: String = errors
        .iter()
        .enumerate()
        .map(|(i, e)| format!("{}: {e};", i + 1))
        .collect();
    Some(format!("Validation Failed: {numbered}"))
}

#[cfg(test)]
mod pipeline_agg_validation_tests {
    use super::find_invalid_pipeline_agg;
    use serde_json::json;

    fn check(aggs: serde_json::Value) -> Option<String> {
        find_invalid_pipeline_agg(Some(&aggs))
    }

    /// Shapes the executor already answers correctly must never be refused:
    /// a false positive here turns a working query into a 400.
    #[test]
    fn valid_pipelines_pass() {
        for aggs in [
            // derivative / cumulative_sum / moving_fn under date_histogram,
            // including a pipeline that reads another pipeline.
            json!({"h": {"date_histogram": {"field": "t", "fixed_interval": "1d"},
                         "aggs": {"v": {"avg": {"field": "x"}},
                                  "d": {"derivative": {"buckets_path": "v"}},
                                  "dd": {"derivative": {"buckets_path": "d"}},
                                  "c": {"cumulative_sum": {"buckets_path": "_count"}},
                                  "m": {"moving_fn": {"buckets_path": "v", "window": 2,
                                                      "script": "MovingFunctions.min(values)"}}}}}),
            // sibling pipelines: value keys, bracket keys, _count, a dotted
            // agg name (`v.v`), a pipeline on a terms parent.
            json!({"t": {"terms": {"field": "k"},
                         "aggs": {"p": {"percentiles": {"field": "x"}},
                                  "s": {"stats": {"field": "x"}},
                                  "v.v": {"avg": {"field": "x"}}}},
                   "a": {"avg_bucket": {"buckets_path": "t>p.99"}},
                   "b": {"max_bucket": {"buckets_path": "t>p[99.9]"}},
                   "c": {"sum_bucket": {"buckets_path": "t>_count"}},
                   "d": {"min_bucket": {"buckets_path": "t>s.avg"}},
                   "e": {"avg_bucket": {"buckets_path": "t>v.v.value"}}}),
            // bucket_script / bucket_selector / bucket_sort under a
            // multi-bucket parent, with object paths and `_key` sort.
            json!({"h": {"histogram": {"field": "x", "interval": 1},
                         "aggs": {"b": {"sum": {"field": "y"}},
                                  "s": {"bucket_script": {"buckets_path": {"x": "b", "n": "_count"},
                                                          "script": "params.x / params.n"}},
                                  "f": {"bucket_selector": {"buckets_path": {"x": "b"},
                                                            "script": "params.x > 0"}},
                                  "o": {"bucket_sort": {"sort": [{"b": {"order": "desc"}}, "_key"],
                                                        "size": 3}}}}}),
            // bucket_sort with only `size` or `from` does something.
            json!({"h": {"terms": {"field": "k"},
                         "aggs": {"o": {"bucket_sort": {"from": 2}}}}}),
        ] {
            assert_eq!(check(aggs.clone()), None, "{aggs}");
        }
    }

    #[test]
    fn misplaced_and_mispathed_pipelines_are_refused_with_es_messages() {
        let cases = [
            (json!({"h": {"date_histogram": {"field": "t", "fixed_interval": "1h"}},
                    "d": {"avg_bucket": {"buckets_path": "h>v"}}}),
             "Validation Failed: 1: No aggregation [v] found for path [h>v];"),
            (json!({"h": {"date_histogram": {"field": "t", "fixed_interval": "1h"},
                          "aggs": {"d": {"derivative": {"buckets_path": "missing"}}}}}),
             "Validation Failed: 1: No aggregation found for path [missing];"),
            (json!({"a": {"filter": {"term": {"a": 1}},
                          "aggs": {"b": {"sum": {"field": "b"}},
                                   "d": {"cumulative_sum": {"buckets_path": "b"}}}}}),
             "cumulative_sum aggregation [d] must have a histogram, date_histogram or auto_date_histogram as parent"),
            (json!({"x": {"avg": {"field": "v"}},
                    "d": {"derivative": {"buckets_path": "x"}}}),
             "derivative aggregation [d] must have a histogram, date_histogram or auto_date_histogram as parent but doesn't have a parent"),
            (json!({"a": {"filter": {"term": {"a": 1}},
                          "aggs": {"b": {"sum": {"field": "b"}},
                                   "d": {"bucket_selector": {"buckets_path": {"b": "b"},
                                                             "script": "params.b > 0"}}}}}),
             "Expected a multi bucket aggregation but got [InternalFilter] for aggregation [d]"),
            (json!({"b": {"sum": {"field": "b"}},
                    "d": {"bucket_script": {"buckets_path": {"b": "b"}, "script": "params.b"}}}),
             "bucket_script aggregation [d] must be declared inside of another aggregation"),
            (json!({"h": {"terms": {"field": "k"}, "aggs": {"bad": {"bucket_sort": {}}}}}),
             "[bad] is configured to perform nothing. Please set either of [sort, size, from] to use bucket_sort"),
            (json!({"h": {"terms": {"field": "k"},
                          "aggs": {"bad": {"bucket_sort": {"sort": ["garbage"]}}}}}),
             "No aggregation found for path [garbage]"),
            (json!({"h": {"histogram": {"field": "x", "interval": 1},
                          "aggs": {"m": {"moving_fn": {"buckets_path": "_count", "window": -1,
                                                       "script": "MovingFunctions.min(values)"}}}}}),
             "[window] must be a positive, non-zero integer."),
        ];
        for (aggs, want) in cases {
            let got = check(aggs.clone()).unwrap_or_else(|| panic!("not refused: {aggs}"));
            assert!(got.contains(want), "{aggs}\n got: {got}\nwant: {want}");
        }
    }
}

/// Parse an ES time-units string to milliseconds: `"500ms"`, `"30s"`,
/// `"2m"`, `"1h"`, `"1d"`, `"5micros"`, `"100nanos"`, bare number =
/// millis. Sub-millisecond values round up to 1 ms so `timeout=100nanos`
/// still arms a (minimal) deadline instead of none at all.
fn parse_time_to_millis(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    if let Some(n) = s.strip_suffix("nanos") {
        let v: u64 = n.parse().ok()?;
        return Some((v / 1_000_000).max(1));
    }
    if let Some(n) = s.strip_suffix("micros") {
        let v: u64 = n.parse().ok()?;
        return Some((v / 1_000).max(1));
    }
    if let Some(n) = s.strip_suffix("ms") {
        let v: u64 = n.parse().ok()?;
        return Some(v.max(1));
    }
    let (digits, mul_ms) = match s.as_bytes().last()? {
        b's' => (&s[..s.len() - 1], 1_000u64),
        b'm' => (&s[..s.len() - 1], 60_000),
        b'h' => (&s[..s.len() - 1], 3_600_000),
        b'd' => (&s[..s.len() - 1], 86_400_000),
        _ => (s, 1), // bare number → milliseconds (ES convention)
    };
    let n: u64 = digits.parse().ok()?;
    Some(n.saturating_mul(mul_ms).max(1))
}

/// Every field name this request pulls a VALUE out of the stored document for
/// by a route other than `_source` — the `fields` clause and `docvalue_fields`.
///
/// Used once per request, before the engine runs, to decide whether the default
/// `_source` projection has to be pierced (#310). It deliberately re-parses the
/// two clauses instead of the response-time lists built later in `search_impl`:
/// the decision has to be taken BEFORE the search, and the URL-param forms
/// (`?fields=`, `?docvalue_fields=`) have already been promoted into `body` by
/// then, so this sees exactly what the response layer will.
fn value_bearing_field_names(body: &EsSearchBody, fields: &[String]) -> Vec<String> {
    fn push_names(v: Option<&Value>, out: &mut Vec<String>) {
        match v {
            Some(Value::Array(arr)) => {
                for entry in arr {
                    match entry {
                        Value::String(s) => out.push(s.clone()),
                        Value::Object(o) => {
                            if let Some(name) = o.get("field").and_then(Value::as_str) {
                                out.push(name.to_string());
                            }
                        }
                        _ => {}
                    }
                }
            }
            Some(Value::String(s)) => out.push(s.clone()),
            _ => {}
        }
    }
    let mut names = Vec::new();
    match &body.fields {
        Some(v @ (Value::Array(_) | Value::String(_))) => push_names(Some(v), &mut names),
        // Same fallback the response-time `field_specs` builder takes: anything
        // else (absent, or a shape the body parser does not recognise) leaves
        // the typed request's list.
        _ => names.extend(fields.iter().cloned()),
    }
    push_names(body.docvalue_fields.as_ref(), &mut names);
    // `_passage` is computed by the engine into `hit.passage`, never read
    // out of `_source`, so it cannot be dropped by a source filter. Counting
    // it made every `fields: ["_passage"]` request with `_source` includes
    // (the `xerj search` body) re-ask the engine for the whole document
    // (#2422/#2423).
    names.retain(|name| name != xerj_query::executor::PASSAGE_RESPONSE_FIELD);
    names
}

/// #932: would an explicit `_source` includes/excludes projection DROP a name
/// the request pulls a value out of (`fields` / `docvalue_fields`)?
///
/// Answered by running the production projection (`xerj_engine::filter_object`)
/// over probe documents instead of re-deriving its wildcard/dotted semantics —
/// whatever the projection does to a document that carries ONLY the named
/// field is what it would do to the real one. Both spellings the fields
/// builder resolves (`get_source_value_by_path`: the whole dotted path as a
/// literal key, then the nested walk) are probed, and a name counts as covered
/// only when BOTH survive — a parent include (`_source: ["a"]`) keeps the
/// nested `{"a": {"b": …}}` spelling but not a literal `a.b` key, so "either"
/// would still let a stored flat key be silently dropped. A name that itself
/// carries a wildcard can select fields the includes list never names, so it
/// always counts as dropped — the safe direction: piercing re-applies the
/// caller's filter at emission, so an unnecessary pierce costs only the
/// `_savings` note, while a missed one is the silent 200 of #932.
fn source_filter_drops_a_name(
    includes: &[String],
    excludes: &[String],
    value_bearing_names: &[String],
) -> bool {
    const PROBE: &str = "__xy_source_cover_probe__";
    let survives = |doc: &Value, name: &str| -> bool {
        let filtered = xerj_engine::filter_object(doc, includes, excludes);
        // Literal spelling: the whole dotted name as one top-level key.
        if filtered.get(name).and_then(Value::as_str) == Some(PROBE) {
            return true;
        }
        // Nested spelling: walk the name's segments.
        let mut cur = &filtered;
        for seg in name.split('.') {
            match cur.get(seg) {
                Some(v) => cur = v,
                None => return false,
            }
        }
        cur.as_str() == Some(PROBE)
    };
    value_bearing_names.iter().any(|name| {
        if name.contains('*') {
            return true;
        }
        let mut flat = serde_json::Map::new();
        flat.insert(name.clone(), Value::String(PROBE.to_string()));
        let mut nested = Value::String(PROBE.to_string());
        for seg in name.rsplit('.') {
            let mut m = serde_json::Map::new();
            m.insert(seg.to_string(), nested);
            nested = Value::Object(m);
        }
        !(survives(&Value::Object(flat), name) && survives(&nested, name))
    })
}

/// Build a `SearchRequest` from the ES body, forwarding all relevant options.
fn build_search_request(
    body: &EsSearchBody,
    aggs_value: Option<Value>,
) -> Result<xerj_query::ast::SearchRequest, xerj_common::XerjError> {
    use xerj_query::ast::SourceFilter;

    // Reject scripts that exceed the engine's resource limits up front with a
    // 400, before they reach the per-document scoring path (where a deeply
    // nested script would otherwise overflow the stack and abort the server).
    // The field set lives in `GuardedField`, shared with the raw-body guard
    // the `_msearch` / `_search/template` / `_msearch/template` paths run.
    if let Some(msg) = find_search_body_script_limit_violation(body, aggs_value.as_ref()) {
        return Err(xerj_common::XerjError::invalid_query(msg));
    }
    if let Some(msg) = find_invalid_agg_order_path(aggs_value.as_ref())
        .or_else(|| find_invalid_composite_agg(aggs_value.as_ref()))
        .or_else(|| find_invalid_agg_params(aggs_value.as_ref()))
        .or_else(|| find_invalid_pipeline_agg(aggs_value.as_ref()))
    {
        return Err(xerj_common::XerjError::invalid_query(msg));
    }

    let query_val = body.query.clone().unwrap_or(json!({ "match_all": {} }));

    // Build a JSON blob for parse_request (handles the query + from/size).
    let mut query_body = json!({
        "query": query_val,
        "from": body.from,
        "size": body.size,
    });
    if let Some(ref aggs) = aggs_value {
        query_body["aggs"] = aggs.clone();
    }
    // Forward track_total_hits into the JSON blob so parse_request picks it up.
    if let Some(ref tth) = body.track_total_hits {
        query_body["track_total_hits"] = tth.clone();
    }
    // Preserve every accepted ES `fields` wire shape. The query parser
    // normalizes scalar, string-array, and `{field: ...}` entries into names
    // used by engine-owned pseudo-fields such as `_passage`.
    if let Some(ref fields) = body.fields {
        query_body["fields"] = fields.clone();
    }

    let mut req = parse_request(&query_body)
        .map_err(|e| xerj_common::XerjError::invalid_query(e.to_string()))?;

    // #943: `post_filter` never reaches the engine (accepted-and-ignored for
    // ordinary queries — implementing it generally is #204), but beside a
    // hybrid query it answered 200 with the UNFILTERED fused hits, which is
    // the accepted-and-wrong class. Reject that one combination with the
    // same 400 style the engine already uses for aggs-beside-hybrid,
    // naming the supported spellings (the filter inside each leg, or the
    // bool{must, filter} wrapper the engine now pushes into every leg).
    if body.post_filter.is_some() && req.query.contains_hybrid() {
        return Err(xerj_common::XerjError::invalid_query(
            "post_filter is not supported with hybrid/fusion queries; put the \
             filter inside each leg (hybrid.queries[].query) or beside the hybrid \
             as bool{must: [hybrid], filter: […]} so it is applied to every leg",
        ));
    }

    // Make sure size is respected exactly (parse_request uses default_size).
    req.size = body.size;
    req.from = body.from;
    req.explain = body.explain;

    // Request-level timeout (RC4 blocker 12): arm the engine's
    // cooperative wall-clock deadline. Unparsable values are ignored
    // (engine default 30 s) rather than 400 — matching our lenient
    // handling of other ES time-unit params.
    if req.timeout_ms.is_none() {
        req.timeout_ms = body.timeout.as_deref().and_then(parse_time_to_millis);
    }

    // Forward aggs.
    if req.aggs.is_none() {
        req.aggs = aggs_value;
    }

    // Parse _source filter. Supports:
    //   _source: false              → suppress entirely
    //   _source: "field1"           → include single field
    //   _source: ["f1","f2"]        → include list
    //   _source: {includes, excludes} → full filter
    if let Some(src_val) = &body.source {
        req.source = match src_val {
            Value::Bool(b) => SourceFilter::Enabled(*b),
            Value::String(s) if s == "false" => SourceFilter::Enabled(false),
            Value::String(s) if s == "true" => SourceFilter::Enabled(true),
            Value::String(s) => {
                let fields: Vec<String> = s.split(',').map(|f| f.trim().to_string()).collect();
                SourceFilter::Includes(fields)
            }
            Value::Array(arr) => {
                let fields: Vec<String> = arr
                    .iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect();
                SourceFilter::Includes(fields)
            }
            Value::Object(obj) => {
                let includes: Vec<String> = obj
                    .get("includes")
                    .or_else(|| obj.get("include"))
                    .and_then(|v| match v {
                        Value::Array(a) => Some(
                            a.iter()
                                .filter_map(|v| v.as_str().map(String::from))
                                .collect(),
                        ),
                        Value::String(s) => Some(vec![s.clone()]),
                        _ => None,
                    })
                    .unwrap_or_default();
                let excludes: Vec<String> = obj
                    .get("excludes")
                    .or_else(|| obj.get("exclude"))
                    .and_then(|v| match v {
                        Value::Array(a) => Some(
                            a.iter()
                                .filter_map(|v| v.as_str().map(String::from))
                                .collect(),
                        ),
                        Value::String(s) => Some(vec![s.clone()]),
                        _ => None,
                    })
                    .unwrap_or_default();
                SourceFilter::Fields { includes, excludes }
            }
            _ => SourceFilter::Enabled(true),
        };
    }

    // Parse sort.
    if let Some(sort_val) = &body.sort {
        let sort_fields = parse_sort(sort_val);
        req.sort = sort_fields;
        // ES treats a sort that is nothing but `_score` DESC exactly like
        // no sort at all: hits carry no `sort` arrays, `max_score` is
        // populated, and ties break by doc order (live-verified on ES
        // 8.13.4: `sort:["_score"]` / `[{"_score":"desc"}]` responses are
        // wire-identical to omitting `sort`, while `[{"_score":"asc"}]`
        // and mixed sorts DO emit sort arrays with `max_score: null`).
        if !req.sort.is_empty()
            && req
                .sort
                .iter()
                .all(|sf| sf.is_score() && sf.order == xerj_query::sort::SortOrder::Desc)
        {
            req.sort = Vec::new();
        }
    }

    // Parse highlight.
    if let Some(hl_val) = &body.highlight {
        req.highlight = parse_highlight(hl_val);
    }

    // Forward script_fields (opaque `{name: {script: {...}}}` JSON). Each
    // script is evaluated per hit against the hit's source in the search
    // handler's fields-building closure and merged into the hit's `fields`.
    req.script_fields = body.script_fields.clone();

    // track_total_hits is already forwarded via the JSON blob above.

    // Parse search_after cursor.
    if let Some(ref sa_val) = body.search_after {
        req.search_after = match sa_val {
            Value::Array(arr) => Some(arr.clone()),
            _ => None,
        };
    }

    // Forward profile flag.
    req.profile = body.profile;

    // Parse collapse field.
    if let Some(collapse_val) = &body.collapse {
        if let Some(obj) = collapse_val.as_object() {
            if let Some(field) = obj.get("field").and_then(Value::as_str) {
                req.collapse = Some(xerj_query::ast::CollapseField {
                    field: field.to_string(),
                    inner_hits: obj.get("inner_hits").cloned(),
                });
            }
        }
    }

    // Parse rescore specification.
    if let Some(rescore_val) = &body.rescore {
        req.rescore = parse_rescore(rescore_val);
    }

    // Pass min_score through to the engine so it can be applied at
    // scoring time (before total counting + aggregation).
    req.min_score = body.min_score;

    Ok(req)
}

/// Parse an ES rescore spec (single object or array of objects) into `Vec<RescoreQuery>`.
fn parse_rescore(val: &Value) -> Vec<xerj_query::ast::RescoreQuery> {
    use xerj_query::ast::{RescoreQuery, RescoreQueryInner, ScriptRescore};

    // ES allows a single rescore object or an array.
    let items: Vec<&Value> = match val {
        Value::Array(arr) => arr.iter().collect(),
        obj @ Value::Object(_) => vec![obj],
        _ => return vec![],
    };

    let mut result = Vec::new();
    for item in items {
        let window_size = item
            .get("window_size")
            .and_then(Value::as_u64)
            .map(|n| n as usize)
            .unwrap_or(100);

        let mut query_opt: Option<RescoreQueryInner> = None;
        let mut script_opt: Option<ScriptRescore> = None;

        // Query rescorer: rescore.query.rescore_query
        if let Some(q_obj) = item.get("query").and_then(Value::as_object) {
            let rescore_query_val = q_obj.get("rescore_query").cloned();
            let query_weight = q_obj
                .get("query_weight")
                .and_then(Value::as_f64)
                .unwrap_or(1.0) as f32;
            let rescore_query_weight = q_obj
                .get("rescore_query_weight")
                .and_then(Value::as_f64)
                .unwrap_or(1.0) as f32;

            if let Some(rq_val) = rescore_query_val {
                if let Ok(parsed) = xerj_query::parse_request(&json!({
                    "query": rq_val,
                    "size": 0
                })) {
                    query_opt = Some(RescoreQueryInner {
                        rescore_query: parsed.query,
                        query_weight,
                        rescore_query_weight,
                    });
                }
            }
        }

        // Script rescorer: rescore.script.script.{source, params}
        // ES wraps the actual script under TWO `script` levels — outer
        // identifies the rescorer type, inner holds source + params.
        if let Some(s_obj) = item.get("script").and_then(Value::as_object) {
            let inner = s_obj
                .get("script")
                .and_then(Value::as_object)
                .cloned()
                .unwrap_or_else(serde_json::Map::new);
            let source = inner
                .get("source")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            let params = inner.get("params").cloned().unwrap_or(json!({}));
            let q_w = s_obj
                .get("query_weight")
                .and_then(Value::as_f64)
                .unwrap_or(1.0) as f32;
            let r_w = s_obj
                .get("rescore_query_weight")
                .and_then(Value::as_f64)
                .unwrap_or(1.0) as f32;
            let mode = s_obj
                .get("score_mode")
                .and_then(Value::as_str)
                .map(String::from);
            if !source.is_empty() {
                script_opt = Some(ScriptRescore {
                    source,
                    params,
                    query_weight: q_w,
                    rescore_query_weight: r_w,
                    score_mode: mode,
                });
            }
        }

        if query_opt.is_some() || script_opt.is_some() {
            result.push(RescoreQuery {
                window_size,
                query: query_opt,
                script: script_opt,
            });
        }
    }
    result
}

/// Collect `(agg_name, field, spec)` for every `percentiles` aggregation that
/// declares `hdr`, recursing into sub-aggregations.
fn collect_hdr_percentile_aggs(aggs: &Value, out: &mut Vec<(String, String, Value)>) {
    let Some(obj) = aggs.as_object() else { return };
    for (name, body) in obj {
        let Some(body_obj) = body.as_object() else {
            continue;
        };
        for (agg_type, spec) in body_obj {
            if matches!(agg_type.as_str(), "aggs" | "aggregations" | "meta") {
                continue;
            }
            if agg_type == "percentiles" && spec.get("hdr").is_some() {
                if let Some(field) = spec.get("field").and_then(Value::as_str) {
                    out.push((name.clone(), field.to_string(), spec.clone()));
                }
            }
        }
        if let Some(subs) = body_obj
            .get("aggs")
            .or_else(|| body_obj.get("aggregations"))
        {
            collect_hdr_percentile_aggs(subs, out);
        }
    }
}

/// Extract all numeric values for `field` from a hit `_source`, flattening
/// arrays and parsing numeric-shaped strings. Supports dotted sub-field paths.
fn source_numeric_values(source: &Value, field: &str) -> Vec<f64> {
    fn push_num(v: &Value, out: &mut Vec<f64>) {
        match v {
            Value::Number(n) => {
                if let Some(f) = n.as_f64() {
                    out.push(f);
                }
            }
            Value::String(s) => {
                if let Ok(f) = s.parse::<f64>() {
                    out.push(f);
                }
            }
            Value::Array(a) => {
                for x in a {
                    push_num(x, out);
                }
            }
            _ => {}
        }
    }
    let v = source.get(field).cloned().or_else(|| {
        if field.contains('.') {
            source
                .pointer(&format!("/{}", field.replace('.', "/")))
                .cloned()
        } else {
            None
        }
    });
    let mut out = Vec::new();
    if let Some(v) = v {
        push_num(&v, &mut out);
    }
    out
}

/// Recompute the `values` payload of an `hdr` percentiles aggregation over
/// `vals`, mirroring the engine's HDR quantization exactly (see
/// `xerj_engine::aggs::run_percentiles`). Used to rebuild the result after
/// negative-valued docs are dropped (ES fails the shard holding them).
fn hdr_percentiles_values(vals: &[f64], spec: &Value) -> Value {
    let percents: Vec<f64> = spec
        .get("percents")
        .and_then(Value::as_array)
        .map(|arr| arr.iter().filter_map(Value::as_f64).collect())
        .unwrap_or_else(|| vec![1.0, 5.0, 25.0, 50.0, 75.0, 95.0, 99.0]);
    let keyed = spec.get("keyed").and_then(Value::as_bool).unwrap_or(true);
    let digits = spec
        .get("hdr")
        .and_then(|h| h.get("number_of_significant_value_digits"))
        .and_then(Value::as_u64)
        .unwrap_or(3) as u32;
    let sub_bucket_count: u64 = {
        let target = 2u64 * 10u64.pow(digits);
        let mut p = 1u64;
        while p < target {
            p <<= 1;
        }
        p
    };
    let half_sub_bucket = sub_bucket_count / 2;
    let hdr_quantize = |v: f64| -> f64 {
        if v <= 0.0 || !v.is_finite() {
            return v;
        }
        let bucket_exp = v.log2().floor() as i32;
        if bucket_exp < 5 {
            return v;
        }
        let unit_size = (1u64 << bucket_exp.min(62) as u32) as f64;
        v + (unit_size - 1.0) / (half_sub_bucket as f64)
    };
    let mut nums: Vec<f64> = vals.to_vec();
    nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let compute = |pct: f64| -> Option<f64> {
        if nums.is_empty() {
            return None;
        }
        let n = nums.len();
        let count_at = ((((pct / 100.0) * n as f64) + 0.5) as i64).max(1) as usize;
        let mut cumulative = 0usize;
        let mut pick = nums[n - 1];
        for &v in nums.iter() {
            cumulative += 1;
            if cumulative >= count_at {
                pick = v;
                break;
            }
        }
        Some(hdr_quantize(pick))
    };
    if keyed {
        let values: serde_json::Map<String, Value> = percents
            .iter()
            .map(|&pct| {
                let key = format!("{:.1}", pct);
                let val = compute(pct)
                    .and_then(serde_json::Number::from_f64)
                    .map(Value::Number)
                    .unwrap_or(Value::Null);
                (key, val)
            })
            .collect();
        Value::Object(values)
    } else {
        let arr: Vec<Value> = percents
            .iter()
            .map(|&pct| {
                let val = compute(pct)
                    .and_then(serde_json::Number::from_f64)
                    .map(Value::Number)
                    .unwrap_or(Value::Null);
                let key_num = serde_json::Number::from_f64(pct)
                    .map(Value::Number)
                    .unwrap_or(Value::Null);
                json!({ "key": key_num, "value": val })
            })
            .collect();
        Value::Array(arr)
    }
}

/// True when a sort spec is exactly a single `_doc` key in any accepted shape:
/// the bare string `"_doc"`, `["_doc"]`, or `[{"_doc": ...}]`.
fn is_lone_doc_sort(v: &Value) -> bool {
    match v {
        Value::String(s) => s == "_doc",
        Value::Array(a) if a.len() == 1 => is_lone_doc_sort(&a[0]),
        Value::Object(o) if o.len() == 1 => o.keys().next().map(|k| k == "_doc").unwrap_or(false),
        _ => false,
    }
}

/// Widen an f32 score to the f64 that prints as the SHORTEST f32 repr —
/// ES serializes scores as Java floats (`448.4`), while a raw `as f64`
/// bit-widening prints `448.3999938964844` on the wire. Order-preserving
/// (shortest round-trip is monotone), so comparisons are unaffected.
fn score_wire(v: f32) -> f64 {
    v.to_string().parse().unwrap_or(v as f64)
}

/// Parse ES sort spec into a Vec<SortField>.
///
/// ES sort can be:
/// - `"_score"` / `"_doc"` (string)
/// - `[{"field": "asc"}, {"field": {"order": "desc", "missing": "_last"}}]`
fn parse_sort(sort_val: &Value) -> Vec<xerj_query::sort::SortField> {
    use xerj_query::sort::{SortField, SortMissing, SortMode, SortOrder};
    let mut fields: Vec<SortField> = Vec::new();

    // ES accepts sort in multiple shapes:
    //   "field"                           — single field, ascending
    //   {"field": {...}}                  — single field, with opts
    //   [...]                              — array of the two above
    // Normalize to a slice of items to iterate.
    let items_owned: Vec<Value>;
    let items: &[Value] = match sort_val {
        Value::Array(arr) => arr.as_slice(),
        Value::String(_) | Value::Object(_) => {
            items_owned = vec![sort_val.clone()];
            &items_owned
        }
        _ => return fields,
    };

    for item in items {
        match item {
            Value::String(s) => {
                let sf = match s.as_str() {
                    "_score" => SortField::score_desc(),
                    "_doc" => SortField::doc_asc(),
                    other => SortField {
                        field: other.to_string(),
                        order: SortOrder::Asc,
                        mode: SortMode::default(),
                        missing: SortMissing::default(),
                        format: None,
                        unmapped_type: None,
                        numeric_type: None,
                    },
                };
                fields.push(sf);
            }
            Value::Object(obj) => {
                for (field_name, spec) in obj {
                    let (order, mode, missing, format, unmapped_type, numeric_type) = match spec {
                        Value::String(ord) => (
                            parse_sort_order(ord),
                            SortMode::default(),
                            SortMissing::default(),
                            None,
                            None,
                            None,
                        ),
                        Value::Object(opts) => {
                            let order = opts
                                .get("order")
                                .and_then(Value::as_str)
                                .map(parse_sort_order)
                                .unwrap_or(SortOrder::Asc);
                            let mode = opts
                                .get("mode")
                                .and_then(Value::as_str)
                                .map(parse_sort_mode)
                                .unwrap_or_default();
                            let missing = opts
                                .get("missing")
                                .map(|v| match v.as_str() {
                                    Some("_first") => SortMissing::First,
                                    Some("_last") => SortMissing::Last,
                                    _ => SortMissing::Value(v.clone()),
                                })
                                .unwrap_or_default();
                            let format =
                                opts.get("format").and_then(Value::as_str).map(String::from);
                            let unmapped_type = opts
                                .get("unmapped_type")
                                .and_then(Value::as_str)
                                .map(String::from);
                            // #889: `numeric_type` forces the scale the sort
                            // values are produced on, so a `date` field in one
                            // index and a `date_nanos` field in another are
                            // compared on ONE epoch scale instead of as raw
                            // longs six orders of magnitude apart.
                            let numeric_type = opts
                                .get("numeric_type")
                                .and_then(Value::as_str)
                                .map(|s| s.to_ascii_lowercase());
                            (order, mode, missing, format, unmapped_type, numeric_type)
                        }
                        _ => (
                            SortOrder::Asc,
                            SortMode::default(),
                            SortMissing::default(),
                            None,
                            None,
                            None,
                        ),
                    };
                    let sf = match field_name.as_str() {
                        "_score" => SortField {
                            field: "_score".to_string(),
                            order,
                            mode,
                            missing,
                            format,
                            unmapped_type,
                            numeric_type,
                        },
                        "_doc" => SortField {
                            field: "_doc".to_string(),
                            order,
                            mode,
                            missing,
                            format,
                            unmapped_type,
                            numeric_type,
                        },
                        other => SortField {
                            field: other.to_string(),
                            order,
                            mode,
                            missing,
                            format,
                            unmapped_type,
                            numeric_type,
                        },
                    };
                    fields.push(sf);
                }
            }
            _ => {}
        }
    }

    fields
}

fn parse_sort_order(s: &str) -> xerj_query::sort::SortOrder {
    match s {
        "asc" => xerj_query::sort::SortOrder::Asc,
        _ => xerj_query::sort::SortOrder::Desc,
    }
}

fn parse_sort_mode(s: &str) -> xerj_query::sort::SortMode {
    match s {
        "min" => xerj_query::sort::SortMode::Min,
        "max" => xerj_query::sort::SortMode::Max,
        "avg" => xerj_query::sort::SortMode::Avg,
        "sum" => xerj_query::sort::SortMode::Sum,
        "median" => xerj_query::sort::SortMode::Median,
        _ => xerj_query::sort::SortMode::default(),
    }
}

/// Parse ES highlight config into `HighlightRequest`.
///
/// ES accepts both the singular `pre_tag`/`post_tag` and the plural-array
/// shapes `pre_tags`/`post_tags` (the plural is canonical in the REST
/// spec; the singular is a convenience for our internal AST). When
/// the array form is used we take the first element.
fn parse_highlight(hl_val: &Value) -> Option<xerj_query::ast::HighlightRequest> {
    use xerj_query::ast::{HighlightFieldOptions, HighlightRequest};

    let obj = hl_val.as_object()?;
    // `fields` is an object, or ES's ordered form: an array of single-field
    // objects (`[{"title": {}}, {"body": {}}]`). The array used to fail
    // `as_object()` and drop highlighting with no error (#1946).
    let field_entries: Vec<(&String, &Value)> = match obj.get("fields")? {
        Value::Object(m) => m.iter().collect(),
        Value::Array(items) => items
            .iter()
            .filter_map(Value::as_object)
            .flat_map(|m| m.iter())
            .collect(),
        _ => return None,
    };

    fn pull_tag(
        obj: &serde_json::Map<String, Value>,
        plural: &str,
        singular: &str,
    ) -> Option<String> {
        obj.get(plural)
            .and_then(|v| v.as_array())
            .and_then(|a| a.first())
            .and_then(Value::as_str)
            .map(String::from)
            .or_else(|| obj.get(singular).and_then(Value::as_str).map(String::from))
    }

    let mut fields = std::collections::HashMap::new();
    for (field_name, field_opts) in field_entries {
        let opts = if let Some(o) = field_opts.as_object() {
            HighlightFieldOptions {
                pre_tag: pull_tag(o, "pre_tags", "pre_tag"),
                post_tag: pull_tag(o, "post_tags", "post_tag"),
                fragment_size: o
                    .get("fragment_size")
                    .and_then(Value::as_u64)
                    .map(|n| n as usize),
                number_of_fragments: o
                    .get("number_of_fragments")
                    .and_then(Value::as_u64)
                    .map(|n| n as usize),
                highlighter_type: o.get("type").and_then(Value::as_str).map(str::to_string),
                order: o.get("order").and_then(Value::as_str).map(str::to_string),
            }
        } else {
            HighlightFieldOptions::default()
        };
        fields.insert(field_name.clone(), opts);
    }

    Some(HighlightRequest {
        fields,
        pre_tag: pull_tag(obj, "pre_tags", "pre_tag"),
        post_tag: pull_tag(obj, "post_tags", "post_tag"),
        fragment_size: obj
            .get("fragment_size")
            .and_then(Value::as_u64)
            .map(|n| n as usize),
        number_of_fragments: obj
            .get("number_of_fragments")
            .and_then(Value::as_u64)
            .map(|n| n as usize),
        require_field_match: obj.get("require_field_match").and_then(Value::as_bool),
        highlighter_type: obj.get("type").and_then(Value::as_str).map(str::to_string),
        order: obj.get("order").and_then(Value::as_str).map(str::to_string),
    })
}

/// Query parameters accepted on `GET /{index}/_search`.
///
/// These are common params used by simple ES clients and curl one-liners.
/// Most are accepted and ignored (preference, routing, etc.) to avoid 400 errors.
#[derive(Debug, Clone, Default, Deserialize, Serialize)]
pub struct EsSearchQueryParams {
    /// Simple query string — `?q=title:rust`.
    pub q: Option<String>,
    /// Maximum hits to return. Kept as a raw string so `?size=abc` reaches the
    /// handler (which returns an ES-shaped 400) instead of failing at the axum
    /// `Query` layer with a `text/plain` 400 (item 4d).
    pub size: Option<String>,
    /// Start offset. Raw string for the same reason as `size`.
    pub from: Option<String>,
    /// Sort field — `price:desc` or `_score`.
    pub sort: Option<String>,
    /// Comma-separated list of source fields to include.
    #[serde(rename = "_source")]
    pub source: Option<String>,
    /// When present, prefix aggregation names with their type.
    pub typed_keys: Option<String>,
    // ── Accepted-but-ignored params (prevent 400s from ES clients) ──────────
    pub preference: Option<String>,
    pub routing: Option<String>,
    pub request_cache: Option<String>,
    pub allow_partial_search_results: Option<String>,
    pub batched_reduce_size: Option<String>,
    pub ccs_minimize_roundtrips: Option<String>,
    pub search_type: Option<String>,
    pub scroll: Option<String>,
    pub track_total_hits: Option<String>,
    /// Request-level search timeout (`?timeout=100ms`) — same semantics
    /// as the body's `timeout` (body wins when both are set). RC4
    /// blocker 12: previously this param (and the body field) were
    /// silently dropped, so the engine's cooperative deadline was never
    /// armed and `timeout` could not fire.
    pub timeout: Option<String>,
    /// ES 7+ compat: when true, return `hits.total` as a bare integer
    /// instead of `{value, relation}`. Many ES YAML tests set this.
    pub rest_total_hits_as_int: Option<String>,
    /// When true, a missing index is silently treated as empty rather than
    /// returning 404. Default false; wildcards flip to true implicitly.
    pub ignore_unavailable: Option<String>,
    /// When true, a wildcard or `_all` that matches no indices returns
    /// an empty result rather than 404. Default true.
    pub allow_no_indices: Option<String>,
    /// Accepted for compatibility; expansion happens in the selector code.
    pub expand_wildcards: Option<String>,
    /// Response filtering: `?filter_path=hits.hits._source,hits.total`
    pub filter_path: Option<String>,
    /// Comma-separated source fields to include (`?_source_includes=f1,f2`).
    #[serde(rename = "_source_includes")]
    pub source_includes: Option<String>,
    /// Comma-separated source fields to exclude (`?_source_excludes=f1,f2`).
    #[serde(rename = "_source_excludes")]
    pub source_excludes: Option<String>,
    /// Comma-separated `stored_fields` URL param.
    pub stored_fields: Option<String>,
    /// Comma-separated `docvalue_fields` URL param — overridden by body.
    pub docvalue_fields: Option<String>,
    /// Comma-separated `fields` URL param (ES 8+).
    pub fields: Option<String>,
    /// Default field for the URL `q=` query string.
    pub df: Option<String>,
    /// Default operator for the URL `q=` query string.
    pub default_operator: Option<String>,
    /// Analyzer for the URL `q=` query string.
    pub analyzer: Option<String>,
    /// Lenient for query_string — swallow parse errors.
    pub lenient: Option<String>,
    /// When true, emit `_seq_no` and `_primary_term` on each hit.
    pub seq_no_primary_term: Option<String>,
    /// When true, emit `_version` on each hit.
    pub version: Option<String>,
    /// When true, `matched_queries` is emitted as a `{name: score}` map
    /// instead of an array of names (ES 8.8+).
    pub include_named_queries_score: Option<String>,
    /// When true, dotted keys in `_source` are expanded into nested
    /// object structure (synthetic-source view of the same data).
    pub force_synthetic_source: Option<String>,
    /// URL-level `?explain=true` — ES accepts explain as either a
    /// URL parameter or a body field; whichever is set wins (body
    /// takes precedence when both are provided).
    pub explain: Option<String>,
    /// xerj extension, `?savings=`: report the `_source` payload this
    /// response did NOT have to send, relative to the response the caller
    /// would have received with no `_source` clause at all.
    ///
    /// * absent / `true` / `sampled` — **the default**: long arrays are
    ///   extrapolated from a bounded sample, everything else counted exactly,
    ///   and the block says `"measured": "sampled"`.
    /// * `exact` — serialize and count every omitted byte.
    /// * `false` / `off` / `0` — do not measure, emit nothing.
    pub savings: Option<String>,
    /// xerj extension, `?strict_unknown_fields=` (#1093): refuse lookup
    /// clauses (`term`, `match`, `range`, …) that name fields no target
    /// index maps, instead of ES's silent 0-hit 200.
    ///
    /// * `true` — enforce for this request regardless of index settings.
    /// * `false` / `off` / `0` — never enforce, regardless of index settings
    ///   (the explicit escape hatch for one request against a strict index).
    /// * absent — each target index's `index.query.strict_unknown_fields`
    ///   setting decides; a strict mark on ANY target covers the request.
    pub strict_unknown_fields: Option<String>,
}

/// Parse `?savings=` into a measurement mode. Anything unrecognised falls
/// back to the default rather than 400-ing: this is a reporting extension,
/// and a typo in it must never fail a search.
fn parse_savings_mode(param: Option<&str>) -> xerj_query::ast::SavingsMode {
    use xerj_query::ast::SavingsMode;
    match param {
        Some("false") | Some("off") | Some("0") | Some("none") => SavingsMode::Off,
        Some("exact") => SavingsMode::Exact,
        _ => SavingsMode::Sampled,
    }
}

pub async fn search_all(
    State(state): State<AppState>,
    Query(params): Query<EsSearchQueryParams>,
    principal: crate::auth::Principal,
    body: EsSearchJson,
) -> impl IntoResponse {
    search(
        State(state),
        Path("*".to_string()),
        Query(params),
        principal,
        body,
    )
    .await
}

/// Bounded top-level query-type label for the `query_latency_by_type`
/// histogram. Returns the outermost query clause name (e.g. `bool`, `term`,
/// `match`) when it is one of the known Elasticsearch query types, `match_all`
/// when the request has no `query`, and `other` for anything unrecognised — so
/// the Prometheus label set stays bounded no matter what a client sends.
pub(crate) fn top_level_query_type(body_query: &Option<serde_json::Value>) -> &'static str {
    // Bounded allow-list of ES top-level query clause names.
    const KNOWN: &[&str] = &[
        "match_all",
        "match_none",
        "match",
        "match_phrase",
        "match_phrase_prefix",
        "multi_match",
        "combined_fields",
        "term",
        "terms",
        "terms_set",
        "range",
        "exists",
        "prefix",
        "wildcard",
        "regexp",
        "fuzzy",
        "ids",
        "bool",
        "boosting",
        "constant_score",
        "dis_max",
        "function_score",
        "nested",
        "has_child",
        "has_parent",
        "parent_id",
        "geo_distance",
        "geo_bounding_box",
        "geo_shape",
        "geo_polygon",
        "shape",
        "more_like_this",
        "script",
        "script_score",
        "wrapper",
        "pinned",
        "rank_feature",
        "distance_feature",
        "intervals",
        "query_string",
        "simple_query_string",
        "percolate",
        "knn",
        "span_near",
        "span_term",
        "span_first",
        "span_or",
        "span_not",
    ];
    let Some(q) = body_query else {
        return "match_all";
    };
    match q.as_object().and_then(|o| o.keys().next()) {
        Some(first) => KNOWN
            .iter()
            .copied()
            .find(|&k| k == first.as_str())
            .unwrap_or("other"),
        None => "match_all",
    }
}

/// Request-owned child task: dropping the HTTP handler aborts its search
/// instead of leaving detached work running after a client disconnect.
struct AbortOnDrop<T>(tokio::task::JoinHandle<T>);

impl<T> Drop for AbortOnDrop<T> {
    fn drop(&mut self) {
        self.0.abort();
    }
}

#[cfg(test)]
type PendingSearchSignals = (
    tokio::sync::oneshot::Sender<()>,
    tokio::sync::oneshot::Sender<()>,
);
#[cfg(test)]
static TEST_PENDING_SEARCH_SIGNALS: std::sync::OnceLock<
    std::sync::Mutex<Vec<PendingSearchSignals>>,
> = std::sync::OnceLock::new();

#[cfg(test)]
struct SignalOnDrop(Option<tokio::sync::oneshot::Sender<()>>);
#[cfg(test)]
impl Drop for SignalOnDrop {
    fn drop(&mut self) {
        if let Some(sender) = self.0.take() {
            let _ = sender.send(());
        }
    }
}

fn search_task_panic_response(join_err: tokio::task::JoinError, index: &str) -> Response {
    tracing::error!(error = %join_err, index, "search task panicked");
    ApiError::new(xerj_common::XerjError::internal(
        "search panicked; check server logs for details",
    ))
    .into_response()
}

#[cfg(test)]
mod search_task_lifetime_tests {
    use super::{search_task_panic_response, AbortOnDrop, TEST_PENDING_SEARCH_SIGNALS};
    use axum::http::{Request, StatusCode};
    use tower::ServiceExt;

    fn test_state() -> crate::state::AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        crate::state::AppState::new(config, engine, metrics)
    }

    #[tokio::test]
    async fn executor_panic_becomes_http_500() {
        let join_err = tokio::spawn(async { panic!("injected search panic") })
            .await
            .expect_err("task must panic");
        let response = search_task_panic_response(join_err, "panic-test");
        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
    }

    #[tokio::test]
    async fn es_search_route_maps_child_panic_to_json_http_500() {
        let state = test_state();
        state
            .engine
            .create_index(
                "test-panic-search-task",
                xerj_common::types::Schema::empty(),
            )
            .unwrap();
        let app = crate::router::build_es_compat_router(state);
        let response = app
            .oneshot(
                Request::post("/test-panic-search-task/_search")
                    .header("content-type", "application/json")
                    .body(axum::body::Body::from(r#"{"query":{"match_all":{}}}"#))
                    .unwrap(),
            )
            .await
            .expect("route response");
        assert_eq!(response.status(), StatusCode::INTERNAL_SERVER_ERROR);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body["status"], 500);
        assert!(
            body["error"]["reason"]
                .as_str()
                .is_some_and(|reason| reason.contains("search panicked")),
            "unexpected error body: {body}"
        );
    }

    #[tokio::test]
    async fn dropping_es_search_route_future_aborts_owned_child() {
        let state = test_state();
        state
            .engine
            .create_index(
                "test-pending-search-task",
                xerj_common::types::Schema::empty(),
            )
            .unwrap();
        let app = crate::router::build_es_compat_router(state);
        let (started_tx, started_rx) = tokio::sync::oneshot::channel();
        let (dropped_tx, dropped_rx) = tokio::sync::oneshot::channel();
        TEST_PENDING_SEARCH_SIGNALS
            .get_or_init(|| std::sync::Mutex::new(Vec::new()))
            .lock()
            .unwrap()
            .push((started_tx, dropped_tx));

        let request = tokio::spawn(
            app.oneshot(
                Request::post("/test-pending-search-task/_search")
                    .header("content-type", "application/json")
                    .body(axum::body::Body::from(r#"{"query":{"match_all":{}}}"#))
                    .unwrap(),
            ),
        );
        tokio::time::timeout(std::time::Duration::from_secs(2), started_rx)
            .await
            .expect("route child did not start")
            .expect("start signal");
        request.abort();
        assert!(request.await.unwrap_err().is_cancelled());
        tokio::time::timeout(std::time::Duration::from_secs(2), dropped_rx)
            .await
            .expect("route-owned child did not drain after request drop")
            .expect("drop signal");
    }

    /// #875: a wildcard search over N indices must run its per-index searches
    /// CONCURRENTLY, not one at a time. Proven without timing: two indices
    /// whose injected search futures signal `started` and then pend forever.
    /// Under the old serial loop the second search never even started — the
    /// loop was parked awaiting the first — so its `started` signal never
    /// fired and this test times out. Under the two-phase fan-out both
    /// searches start while neither has completed.
    #[tokio::test]
    async fn wildcard_fanout_runs_per_index_searches_concurrently() {
        let state = test_state();
        for name in ["test-pending-search-task", "test-pending-search-task2"] {
            state
                .engine
                .create_index(name, xerj_common::types::Schema::empty())
                .unwrap();
        }
        let app = crate::router::build_es_compat_router(state);
        let (started_tx_a, started_rx_a) = tokio::sync::oneshot::channel();
        let (dropped_tx_a, dropped_rx_a) = tokio::sync::oneshot::channel();
        let (started_tx_b, started_rx_b) = tokio::sync::oneshot::channel();
        let (dropped_tx_b, dropped_rx_b) = tokio::sync::oneshot::channel();
        {
            let mut slot = TEST_PENDING_SEARCH_SIGNALS
                .get_or_init(|| std::sync::Mutex::new(Vec::new()))
                .lock()
                .unwrap();
            slot.push((started_tx_a, dropped_tx_a));
            slot.push((started_tx_b, dropped_tx_b));
        }

        let request = tokio::spawn(
            app.oneshot(
                Request::post("/test-pending-search-task*/_search")
                    .header("content-type", "application/json")
                    .body(axum::body::Body::from(r#"{"query":{"match_all":{}}}"#))
                    .unwrap(),
            ),
        );
        // BOTH per-index searches must start while NEITHER can complete —
        // exactly what a serial fan-out cannot do. The generous timeout only
        // bounds the failure mode; a passing run signals immediately.
        tokio::time::timeout(std::time::Duration::from_secs(10), async {
            started_rx_a.await.expect("first start signal");
            started_rx_b.await.expect("second start signal");
        })
        .await
        .expect("both fan-out searches must start concurrently (#875)");

        // Dropping the request aborts every spawned per-index search.
        request.abort();
        assert!(request.await.unwrap_err().is_cancelled());
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            dropped_rx_a.await.expect("first drop signal");
            dropped_rx_b.await.expect("second drop signal");
        })
        .await
        .expect("aborting the request must abort all fan-out searches");
    }

    #[tokio::test]
    async fn dropping_request_owner_aborts_and_drains_child() {
        struct Dropped(tokio::sync::oneshot::Sender<()>);
        impl Drop for Dropped {
            fn drop(&mut self) {
                let (replacement, _) = tokio::sync::oneshot::channel();
                let sender = std::mem::replace(&mut self.0, replacement);
                let _ = sender.send(());
            }
        }

        let (dropped_tx, dropped_rx) = tokio::sync::oneshot::channel();
        let task = tokio::spawn(async move {
            let _dropped = Dropped(dropped_tx);
            std::future::pending::<()>().await;
        });
        let owner = AbortOnDrop(task);
        tokio::task::yield_now().await;
        drop(owner);
        tokio::time::timeout(std::time::Duration::from_secs(1), dropped_rx)
            .await
            .expect("aborted child did not drain")
            .expect("drop signal");
    }
}

/// Shard count used only to size the `profile` response's per-shard array.
///
/// SECURITY: a stored `number_of_shards` of `-1` becomes `u64::MAX` through an
/// `as u64` cast, and `Vec::with_capacity(usize::MAX)` capacity-overflow-panics.
/// Under this crate's `panic = "abort"` that aborts the whole process, so a
/// single unauthenticated `POST /{index}/_search {"profile":true}` on an index
/// created with a negative shard count kills the node. Clamp to a sane positive
/// range, mirroring the `.max(1)` the primary shard-count reader already applies.
fn profile_shard_count(n: i64) -> u64 {
    n.clamp(1, 1024) as u64
}

// ─────────────────────────────────────────────────────────────────────────────
// Actionable response hint (`_xerj`)
// ─────────────────────────────────────────────────────────────────────────────

/// Byte threshold above which an unprojected `_search` response is "large"
/// enough to earn the `_xerj` hint (see [`search_response_hint`]). Picked
/// well above realistic small-document test fixtures — most are a few
/// hundred bytes at most — and well below the response a handful of whole
/// source files produce (measured: 5 hits returning full file bodies via
/// default `_source` = 416,630 bytes; the same query with `_source`
/// projected and `fields: ["_passage"]` = 12,122 bytes).
const LARGE_RESPONSE_HINT_THRESHOLD_BYTES: usize = 4096;

/// Whether a `fields` request — in any of the shapes ES accepts (bare
/// string, array of strings, array of `{"field": ...}` objects) — includes
/// the `_passage` pseudo-field.
fn fields_request_includes_passage(fields: &Value) -> bool {
    fn is_passage(v: &Value) -> bool {
        v.as_str() == Some("_passage")
            || v.as_object()
                .and_then(|o| o.get("field"))
                .and_then(Value::as_str)
                == Some("_passage")
    }
    match fields {
        Value::Array(arr) => arr.iter().any(is_passage),
        other => is_passage(other),
    }
}

/// Build the additive `_xerj.hints` hint for a `_search` response.
///
/// `_passage` — the field that returns just the matching snippet instead of
/// the whole document body — has no default trigger and is absent from
/// `_mapping`, so a caller has no way to discover it short of reading the
/// docs. This nudges them toward it, but only when it would actually help:
/// the caller already gets a small response as soon as they project
/// `_source` or ask for `_passage` themselves, and repeating a notice on
/// every response the caller already handled correctly is exactly the kind
/// of noise this project's review guidance rules out. Returns `None`
/// whenever the hint would not be actionable.
/// Field-keyed leaf clause types (`{"match": {"field": …}}`), shared by the
/// unknown-field hint and the #1093 refusal so the two walks cannot drift.
const FIELD_KEYED_CLAUSES: &[&str] = &[
    "match",
    "match_phrase",
    "match_phrase_prefix",
    "term",
    "terms",
    "prefix",
    "wildcard",
    "regexp",
    "fuzzy",
    "range",
];

/// A query field is "known" when any of `schemas` maps it, maps its parent
/// (`symbols.name.keyword` → `symbols`), or it is an ES metadata field
/// (`_id`, `_index`, …) a query may legitimately target.
fn field_known_in_any(name: &str, schemas: &[&xerj_common::types::Schema]) -> bool {
    if name.starts_with('_') {
        return true;
    }
    schemas.iter().any(|s| {
        s.field(name).is_some()
            || name
                .split_once('.')
                .is_some_and(|(parent, _)| s.field(parent).is_some())
    })
}

/// #1093: `(clause, field)` pairs named by lookup clauses that no schema in
/// `schemas` maps — the clauses `_search` refuses instead of answering with
/// ES's silent zero-hit 200, which a caller cannot tell from an empty corpus.
///
/// Every clause in [`FIELD_KEYED_CLAUSES`] is a lookup: zero hits there is a
/// claim about the data, and a wrong field name makes it a false claim.
/// `exists` is deliberately absent — zero IS the truthful answer to "does any
/// document have this field" — and keeps its `_xerj.hints` diagnostic instead
/// of a refusal. `multi_match` appears once, joining its field list, and only
/// when EVERY field it names is unknown (a half-real multi_match still
/// searches the fields that exist, so it gets the hint, not the 400); a
/// wildcard pattern field (`"ob*"` — legal in `multi_match.fields`) counts as
/// known when it matches at least one mapped field in any schema.
fn unknown_lookup_clause_fields(
    q: &Value,
    schemas: &[&xerj_common::types::Schema],
    out: &mut Vec<(String, String)>,
) {
    match q {
        Value::Object(o) => {
            for (k, v) in o {
                if FIELD_KEYED_CLAUSES.contains(&k.as_str()) {
                    if let Value::Object(inner) = v {
                        for f in inner.keys() {
                            if !field_known_in_any(f, schemas) {
                                let entry = (k.clone(), f.clone());
                                if !out.contains(&entry) {
                                    out.push(entry);
                                }
                            }
                        }
                    }
                } else if k == "multi_match" {
                    if let Some(Value::Array(fs)) = v.get("fields") {
                        let names: Vec<String> = fs
                            .iter()
                            .filter_map(Value::as_str)
                            // `body^3` — the boost is not part of the name.
                            .map(|f| f.split('^').next().unwrap_or(f).to_string())
                            .collect();
                        let all_unknown = !names.is_empty()
                            && names.iter().all(|f| {
                                if f.contains('*') {
                                    !schemas.iter().any(|s| {
                                        s.fields.iter().any(|sf| glob_match_simple(f, &sf.name))
                                    })
                                } else {
                                    !field_known_in_any(f, schemas)
                                }
                            });
                        if all_unknown {
                            out.push(("multi_match".to_string(), names.join(", ")));
                        }
                    }
                } else if k == "span_multi" {
                    // `{"span_multi": {"match": {"prefix": {"field": …}}}}` —
                    // the inner multi-term objects are NOT field-keyed (their
                    // keys are `field`/`value`/`boost`), so the generic walk
                    // would read "field" itself as a field name. The field is
                    // the `field` member of the wrapped multi-term spec.
                    if let Some(m) = v.get("match").and_then(Value::as_object) {
                        for (mt, spec) in m {
                            if let Some(f) = spec.get("field").and_then(Value::as_str) {
                                if !field_known_in_any(f, schemas) {
                                    let entry = (format!("span_multi {mt}"), f.to_string());
                                    if !out.contains(&entry) {
                                        out.push(entry);
                                    }
                                }
                            }
                        }
                    }
                } else if k == "intervals" {
                    // `{"intervals": {"<field>": {"match"|"prefix"|…: {…}}}}` —
                    // the field is the KEY; the spec's own `prefix`/`wildcard`/
                    // `regexp`/`fuzzy` keys are interval kinds, not fields, and
                    // must not be walked as field-keyed clauses.
                    if let Some(inner) = v.as_object() {
                        for (f, _) in inner {
                            if !field_known_in_any(f, schemas) {
                                let entry = ("intervals".to_string(), f.clone());
                                if !out.contains(&entry) {
                                    out.push(entry);
                                }
                            }
                        }
                    }
                } else {
                    unknown_lookup_clause_fields(v, schemas, out);
                }
            }
        }
        Value::Array(a) => a
            .iter()
            .for_each(|v| unknown_lookup_clause_fields(v, schemas, out)),
        _ => {}
    }
}

/// Field names a query refers to, gathered from the ordinary ES leaf shapes.
///
/// Subfield suffixes are kept (`symbols.name.keyword`) but the parent is also
/// recorded, so a query against a real field's subfield is not reported as
/// unknown.
fn referenced_query_fields(q: &Value, out: &mut Vec<String>) {
    const FIELD_KEYED: &[&str] = FIELD_KEYED_CLAUSES;
    match q {
        Value::Object(o) => {
            for (k, v) in o {
                if FIELD_KEYED.contains(&k.as_str()) {
                    if let Value::Object(inner) = v {
                        for f in inner.keys() {
                            out.push(f.clone());
                        }
                    }
                } else if k == "exists" {
                    if let Some(f) = v.get("field").and_then(Value::as_str) {
                        out.push(f.to_string());
                    }
                } else if k == "multi_match" {
                    if let Some(Value::Array(fs)) = v.get("fields") {
                        for f in fs.iter().filter_map(Value::as_str) {
                            // `body^3` — the boost is not part of the name.
                            out.push(f.split('^').next().unwrap_or(f).to_string());
                        }
                    }
                } else if k == "span_multi" {
                    // The wrapped multi-term spec is not field-keyed; its
                    // `field` member is the reference (see the matching case
                    // in `unknown_lookup_clause_fields`).
                    if let Some(m) = v.get("match").and_then(Value::as_object) {
                        for spec in m.values() {
                            if let Some(f) = spec.get("field").and_then(Value::as_str) {
                                out.push(f.to_string());
                            }
                        }
                    }
                } else if k == "intervals" {
                    // Fields are the keys of the intervals object; the spec
                    // bodies are interval kinds, not clauses.
                    if let Some(inner) = v.as_object() {
                        for f in inner.keys() {
                            out.push(f.clone());
                        }
                    }
                } else {
                    referenced_query_fields(v, out);
                }
            }
        }
        Value::Array(a) => a.iter().for_each(|v| referenced_query_fields(v, out)),
        _ => {}
    }
}

/// Hint for a query that names a field none of the matched indices map.
///
/// A prefix pattern (`proj-*`, the target `xerj search --prefix` and
/// `xerj_search` both use) resolves to every dataset under it. Code datasets
/// map `body` / `defs` / `code`; a JSON or CSV dataset often maps none of
/// them. The field is unknown only when no resolved schema maps it (#2121) —
/// the same rule as [`field_known_in_any`]. Reading the first index alone
/// reported those code fields as missing whenever a data index was first in
/// the resolved list, on a response that had already returned the code hits.
///
/// Fires regardless of hit count: a bogus field inside a `multi_match` that
/// also names a real one still returns results, so a zero-hit-only check would
/// never see the worst case.
///
/// This is the most expensive silent failure a newcomer hits. In blind
/// usability runs, two independent agents both guessed `content` (a reasonable
/// name that does not exist here), got `0 hits` with no explanation, and then
/// spent their largest payloads — 182 KB and 65 KB in one run — trial-and-
/// erroring field names before thinking to fetch `_mapping`. The engine knows
/// the schema; staying silent is a choice, and the wrong one.
fn unknown_field_hint(
    index: &str,
    body: &EsSearchBody,
    schemas: &[&xerj_common::types::Schema],
) -> Option<Value> {
    if schemas.is_empty() {
        return None;
    }
    let query = body.query.as_ref()?;
    let mut referenced = Vec::new();
    referenced_query_fields(query, &mut referenced);
    if referenced.is_empty() {
        return None;
    }

    let unknown: Vec<String> = referenced
        .iter()
        .filter(|f| !field_known_in_any(f, schemas))
        .cloned()
        .collect::<std::collections::BTreeSet<_>>()
        .into_iter()
        .collect();
    if unknown.is_empty() {
        return None;
    }

    // Text-ish fields are what a full-text query actually wants; listing every
    // keyword and numeric column would bury the answer. Union across the
    // pattern so the suggestion names a field some matched index actually maps.
    let searchable = searchable_text_fields_across(schemas);

    let primary = searchable
        .iter()
        .find(|n| n.as_str() == "body")
        .or_else(|| searchable.first())
        .cloned()
        .unwrap_or_else(|| "body".to_string());

    Some(json!({
        "hints": [{
            "code": "unknown_field",
            "reason": format!(
                "no results, and this query names {} that {} not exist in `{index}`: {}. \
                 Searchable text fields here are: {}.",
                if unknown.len() == 1 { "a field" } else { "fields" },
                if unknown.len() == 1 { "does" } else { "do" },
                unknown.join(", "),
                if searchable.is_empty() { "(none)".to_string() } else { searchable.join(", ") },
            ),
            "try": {
                "request": format!("POST /{index}/_search"),
                "body": {
                    "query": {"match": {primary.clone(): "<your text>"}},
                    "_source": ["ax_path", "title"],
                    "fields": ["_passage"],
                },
            },
        }],
    }))
}

/// Text-ish fields are what a full-text query actually wants; listing every
/// keyword and numeric column would bury the answer.
fn searchable_text_fields(schema: &xerj_common::types::Schema) -> Vec<String> {
    schema
        .fields
        .iter()
        .filter(|f| {
            matches!(
                f.field_type,
                xerj_common::types::FieldType::Text | xerj_common::types::FieldType::Keyword
            ) && !f.name.starts_with("ax_")
        })
        .map(|f| f.name.clone())
        .collect()
}

/// Searchable text fields across every matched index, first-seen order.
/// A single schema keeps [`searchable_text_fields`]'s order.
fn searchable_text_fields_across(schemas: &[&xerj_common::types::Schema]) -> Vec<String> {
    let mut out = Vec::new();
    for schema in schemas {
        for name in searchable_text_fields(schema) {
            if !out.contains(&name) {
                out.push(name);
            }
        }
    }
    out
}

/// The #1093 refusal reason for a search, or `None` when the query's lookup
/// clauses are all known, no strictness is requested, or there is nothing to
/// validate against.
///
/// Strictness: the `?strict_unknown_fields=` URL param, or the
/// `index.query.strict_unknown_fields` setting on ANY resolved index — a
/// strict mark anywhere in the target set must cover the whole request, or
/// a heterogeneous alias would answer the very 0-hit its strict member was
/// configured to refuse.
///
/// Fresh indices (schema with no fields yet — dynamic mapping has seen no
/// documents) are skipped on both sides: they cannot prove a field unknown,
/// and when every target is fresh the request is exactly the ES case where
/// the field may simply not have arrived yet.
/// Is `index.query.strict_unknown_fields` truthy in this settings tree?
/// Three spellings reach storage: nested (`{"index": {"query": …}}`, also
/// the shape a wrapper-less body lands in), a flat top-level key, and a flat
/// key merged UNDER `index` by the `_settings` handler's normalization —
/// ES clients routinely send flat dotted keys, and that handler stores them
/// verbatim.
fn strict_unknown_fields_set(settings: &Value) -> bool {
    let truthy = |v: &Value| {
        matches!(v, Value::Bool(true)) || v.as_str().is_some_and(|s| s == "true" || s == "1")
    };
    if let Some(v) = settings.pointer("/index/query/strict_unknown_fields") {
        if truthy(v) {
            return true;
        }
    }
    [Some(settings), settings.get("index")]
        .into_iter()
        .flatten()
        .any(|container| {
            container
                .get("index.query.strict_unknown_fields")
                .is_some_and(truthy)
        })
}

/// The #1093 refusal reason for a search, or `None` when the query's lookup
/// clauses are all known, no target asks for strict, or there is nothing to
/// validate against.
///
/// Strictness: the `?strict_unknown_fields=` URL param (`false`/`off`/`0`
/// forces lenient and beats any setting; `true` enforces outright; absent
/// defers to the settings), then the `index.query.strict_unknown_fields`
/// setting on ANY resolved index — a strict mark anywhere in the target set
/// covers the whole request, or a heterogeneous alias would silently answer
/// the very 0-hit its strict member was configured to refuse.
///
/// The default is ES's own lenient behaviour: a lookup on an unmapped field
/// is a 0-hit 200 (with the `_xerj.hints` diagnostic). Turning the refusal
/// on wholesale broke the ES-YAML suite (aggregation cases legitimately
/// query `missing_field` expecting 200), so strictness is opt-in — and
/// `xerj autoindex` turns it on for the indices it creates, whose explicit
/// full schemas are exactly where a wrong field name is a mistake and not
/// a dynamic-mapping probe (#1093's measured case: 5 of 30 agent intents).
async fn unknown_lookup_field_reason(
    state: &crate::state::AppState,
    index_names: &[&str],
    strict_param: Option<&str>,
    query: Option<&Value>,
) -> Option<String> {
    match strict_param {
        Some("false") | Some("off") | Some("0") => return None,
        _ => {}
    }
    let mut enforce = strict_param == Some("true");
    let query = query?;
    let mut schemas: Vec<xerj_common::types::Schema> = Vec::new();
    for name in index_names {
        // A missing index is not this check's error to report — the search
        // itself 404s (or is skipped for ignore_unavailable) further down.
        let Ok(idx) = state.engine.get_index(name) else {
            continue;
        };
        // Two stores can carry the setting: the engine's `settings.json`
        // copy (written at create) and the display map `PUT /_settings`
        // merges into — generic keys are not forwarded to the engine store,
        // so reading one of the two would silently miss the other.
        let display = state
            .engine
            .index_settings
            .get(*name)
            .map(|v| v.clone())
            .unwrap_or(Value::Null);
        if !enforce
            && (strict_unknown_fields_set(&display)
                || strict_unknown_fields_set(&idx.get_settings().await))
        {
            enforce = true;
        }
        let schema = idx.schema().await;
        if !schema.fields.is_empty() {
            schemas.push(schema);
        }
    }
    if !enforce {
        return None;
    }
    // Every target is fresh (no mapped fields anywhere): nothing can be
    // proven unknown, and this is exactly the ES case where the field may
    // simply not have arrived yet — dynamic mapping has seen no documents.
    if schemas.is_empty() {
        return None;
    }
    let refs: Vec<&xerj_common::types::Schema> = schemas.iter().collect();
    let mut unknown = Vec::new();
    unknown_lookup_clause_fields(query, &refs, &mut unknown);
    if unknown.is_empty() {
        return None;
    }

    // `QueryError::UnknownField` was written for exactly this refusal and,
    // until #1093, constructed nowhere. The per-clause reasons come from its
    // Display so the crate's error vocabulary stays the one source.
    let named = unknown
        .iter()
        .take(5)
        .map(|(clause, field)| {
            xerj_query::QueryError::UnknownField {
                field: field.clone(),
                context: format!("{clause} clause"),
            }
            .to_string()
        })
        .collect::<Vec<_>>()
        .join("; ");
    let searchable = searchable_text_fields(&schemas[0]);
    Some(format!(
        "{named}. This target enforces strict_unknown_fields because ES's answer \
         here — a silent 0-hit — is indistinguishable from an empty corpus. \
         Unset index.query.strict_unknown_fields (or send ?strict_unknown_fields=false \
         for one request) to restore that behaviour; `exists` on an unmapped field \
         stays a truthful 0-hit either way. Searchable text fields here: {}",
        if searchable.is_empty() {
            "(none)".to_string()
        } else {
            searchable.join(", ")
        },
    ))
}

/// `term`/`terms` clauses in a query, as (field, value) pairs.
///
/// Only exact-match clauses: a `match` against text is analysed and a zero
/// result there is ordinary, not a taxonomy mistake.
fn exact_term_clauses(q: &Value, out: &mut Vec<(String, String)>) {
    match q {
        Value::Object(o) => {
            for (k, v) in o {
                match k.as_str() {
                    "term" => {
                        if let Value::Object(inner) = v {
                            for (f, val) in inner {
                                let s =
                                    val.get("value").unwrap_or(val).as_str().map(str::to_string);
                                if let Some(s) = s {
                                    out.push((f.clone(), s));
                                }
                            }
                        }
                    }
                    "terms" => {
                        if let Value::Object(inner) = v {
                            for (f, val) in inner {
                                if let Value::Array(a) = val {
                                    for s in a.iter().filter_map(Value::as_str) {
                                        out.push((f.clone(), s.to_string()));
                                    }
                                }
                            }
                        }
                    }
                    _ => referenced_or_recurse(v, out),
                }
            }
        }
        Value::Array(a) => a.iter().for_each(|v| exact_term_clauses(v, out)),
        _ => {}
    }
}

fn referenced_or_recurse(v: &Value, out: &mut Vec<(String, String)>) {
    exact_term_clauses(v, out);
}

/// Build the "you filtered on a value that does not exist" hint.
///
/// `present` is a bounded sample of the values actually stored in the field.
/// A blind usability run filtered `ax_format: "markdown"` — an entirely
/// reasonable guess — and got a silent zero, because this corpus classifies
/// Markdown as `txt-prose`/`txt-lines`. Discovering that cost the agent two
/// round trips and a terms aggregation it had to think to write.
/// Whether a response qualifies for the zero-hit `unknown_value` sample
/// (#2451). Only a request that asked for hits (`size > 0`) and whose whole
/// match set is empty: an empty page with a non-zero tracked total is a page
/// past the end, not a wrong value, and a `size: 0` count/existence probe must
/// stay as cheap as its own query — the sample is a 256-row full-source read.
/// With `track_total_hits: false` the total is not authoritative, so the
/// empty page (with `size > 0`) is the only signal, as before.
fn zero_hit_value_sample_applies(
    size: usize,
    page_empty: bool,
    total_count: u64,
    track_total_disabled: bool,
) -> bool {
    size > 0 && page_empty && (track_total_disabled || total_count == 0)
}

fn unknown_value_hint(index: &str, field: &str, value: &str, present: &[String]) -> Value {
    json!({
        "hints": [{
            "code": "unknown_value",
            // "include", not "are": this comes from a bounded sample, so a rare
            // value may be missing from the list. Presenting a sample as the
            // complete set would let a caller conclude a value does not exist
            // when it simply was not sampled — a worse error than the one this
            // hint is fixing.
            "reason": format!(
                "no results: `{field}` has no value `{value}` in `{index}`. \
                 Values seen in a sample of this index include: {}. \
                 For the complete set, aggregate on the field.",
                present.join(", ")
            ),
            "try": {
                "request": format!("POST /{index}/_search"),
                "body": {
                    "query": {"term": {field: present.first().cloned().unwrap_or_default()}},
                    "_source": ["ax_path", "title"],
                },
            },
        }],
    })
}

/// Full-text clause names that score with BM25 over the analysed text and are
/// keyed by field name (`{"match": {"<field>": …}}`).
const LEXICAL_TEXT_CLAUSES: &[&str] = &[
    "match",
    "match_phrase",
    "match_phrase_prefix",
    "match_bool_prefix",
];

/// Full-text clause names that carry their own `fields` list instead of being
/// keyed by field name.
const LEXICAL_MULTI_FIELD_CLAUSES: &[&str] = &[
    "multi_match",
    "combined_fields",
    "query_string",
    "simple_query_string",
];

/// `(field, query text)` for every lexical full-text clause in a query.
///
/// Deliberately narrower than [`referenced_query_fields`]: `term`, `prefix`,
/// `range` and friends are exact-match clauses a caller reaches for on
/// purpose and which never had a semantic reading to begin with. Only the
/// clauses someone writes when they mean *"find me documents about this"*
/// can mislead them about which question was answered.
fn lexical_text_clauses(q: &Value, out: &mut Vec<(String, String)>) {
    // `{"f": "text"}` and `{"f": {"query": "text", …}}` are the same clause.
    fn clause_text(v: &Value) -> String {
        v.as_str()
            .or_else(|| v.get("query").and_then(Value::as_str))
            .unwrap_or_default()
            .to_string()
    }
    match q {
        Value::Object(o) => {
            for (k, v) in o {
                if LEXICAL_TEXT_CLAUSES.contains(&k.as_str()) {
                    if let Value::Object(inner) = v {
                        for (field, spec) in inner {
                            out.push((field.clone(), clause_text(spec)));
                        }
                    }
                } else if LEXICAL_MULTI_FIELD_CLAUSES.contains(&k.as_str()) {
                    let text = clause_text(v);
                    let mut fields: Vec<String> = v
                        .get("fields")
                        .and_then(Value::as_array)
                        .map(|arr| {
                            arr.iter()
                                .filter_map(Value::as_str)
                                // `ctx^2` — the boost is not part of the name.
                                .map(|f| f.split('^').next().unwrap_or(f).to_string())
                                .collect()
                        })
                        .unwrap_or_default();
                    if let Some(default_field) = v.get("default_field").and_then(Value::as_str) {
                        fields.push(default_field.to_string());
                    }
                    for field in fields {
                        out.push((field, text.clone()));
                    }
                } else {
                    lexical_text_clauses(v, out);
                }
            }
        }
        Value::Array(a) => a.iter().for_each(|v| lexical_text_clauses(v, out)),
        _ => {}
    }
}

/// Fields the same query already reaches through a vector clause, by whatever
/// name that clause used — `semantic` names the text field, `knn` names the
/// companion vector field.
fn vector_query_fields(q: &Value, out: &mut Vec<String>) {
    match q {
        Value::Object(o) => {
            for (k, v) in o {
                if matches!(k.as_str(), "semantic" | "knn") {
                    // `knn` accepts a single spec or an array of them.
                    let specs: Vec<&Value> = match v {
                        Value::Array(a) => a.iter().collect(),
                        single => vec![single],
                    };
                    for spec in specs {
                        if let Some(f) = spec.get("field").and_then(Value::as_str) {
                            out.push(f.to_string());
                        }
                    }
                }
                vector_query_fields(v, out);
            }
        }
        Value::Array(a) => a.iter().for_each(|v| vector_query_fields(v, out)),
        _ => {}
    }
}

/// Fields whose vector clause reaches the vector for this query, approximating
/// the engine's `peel_semantic_query` / `peel_knn_query` /
/// `compound_bool_direct_knn` dispatch (index.rs) for the shapes that can
/// co-exist with a lexical `semantic_text` clause.
///
/// A `semantic` clause consults the vector only as the whole query, as the SOLE
/// `must`/`should` candidate of a `bool` with no `must_not`, or inside a
/// `hybrid` (which fuses and runs every branch). A `semantic` clause sitting
/// BESIDE a sibling in a multi-clause `bool` falls through to the lexical path
/// and never consults the vector (#394) — so it must NOT count as "reached the
/// vector" here, or the hint gets suppressed on a query that ran BM25-only,
/// reintroducing the exact silence the hint exists to break.
///
/// A `knn` clause is no longer bound by that (#825). A `knn` that is a DIRECT
/// child of a compound bool's scoring lists is pre-executed by the engine and
/// its top-k pinned into the tree, so it dispatches whatever its siblings are —
/// and that is precisely the tree this module's `knn`-beside-`query` fold
/// emits, so the hand-rolled ES hybrid must not be nagged for running BM25
/// "only".
///
/// This is NOT a byte-exact mirror of `peel`, and does not need to be (#777):
/// where it diverges the shapes are contrived or carry no lexical clause, so none
/// can produce an observable wrong hint — a pure multi-`knn` or `nested` bool has
/// no text clause to flag; a `hybrid` nested as a bool's sole candidate is
/// collected here even though `peel`'s bool arm would not descend into it
/// (over-suppressing a contrived `bool{should:[hybrid], filter:[match]}`, exactly
/// as the prior blanket walk did — not a regression); and a query-level
/// `boost`/`_name` is an inline leaf param, not a wrapper key, so nothing
/// dispatching is missed.
///
/// The `knn` arm inherits exactly that one known divergence and no other. A
/// one-clause `bool` is erased before the engine reads the tree (#399), so
/// descending through a sole candidate into a compound bool tracks
/// `compound_bool_direct_knn` faithfully — except in the same contrived
/// `bool{should:[bool{should:[knn, match]}], filter:[…]}` shape, where the
/// wrapper is not erased, the engine does NOT pin, and this over-suppresses.
/// Same class, same contrivance, no new one.
///
/// Contrast [`vector_query_fields`], which collects every mention regardless of
/// shape and is right only for the top-level `knn` block (which always dispatches).
fn dispatching_vector_fields(q: &Value, out: &mut Vec<String>) {
    let Value::Object(o) = q else {
        return;
    };
    // A direct `semantic`/`knn` at this level dispatches.
    for key in ["semantic", "knn"] {
        if let Some(v) = o.get(key) {
            let specs: Vec<&Value> = match v {
                Value::Array(a) => a.iter().collect(),
                single => vec![single],
            };
            for spec in specs {
                if let Some(f) = spec.get("field").and_then(Value::as_str) {
                    out.push(f.to_string());
                }
            }
        }
    }
    // `hybrid` runs and fuses every branch, so each branch dispatches on its
    // own terms.
    if let Some(Value::Array(branches)) = o.get("hybrid").and_then(|h| h.get("queries")) {
        for entry in branches {
            if let Some(inner) = entry.get("query") {
                dispatching_vector_fields(inner, out);
            }
        }
    }
    // `constant_score` is a transparent wrapper (the engine peels it).
    if let Some(inner) = o.get("constant_score").and_then(|c| c.get("filter")) {
        dispatching_vector_fields(inner, out);
    }
    // `bool` reaches a `semantic` clause ONLY in the single-`must`/`should`
    // candidate, no-`must_not` shape the engine peels; every other bool falls
    // through to the lexical path and consults no vector.
    //
    // `knn` is no longer bound by that (#825): a `knn` clause sitting DIRECTLY
    // in a compound bool's SCORING lists is now pre-executed by the engine and
    // its top-k pinned into the tree (`compound_bool_direct_knn` /
    // `pin_knn_clause` in xerj-engine), so it genuinely dispatches however many
    // siblings it has — which is exactly the tree this module's own
    // `knn`-beside-`query` fold emits. Mirror the engine's gate: exactly one
    // direct `Knn` child across `must` + `should`, `must_not`/`filter`
    // irrelevant. `semantic` keeps the #394 rule, which still holds for it.
    if let Some(Value::Object(b)) = o.get("bool") {
        let mut scoring: Vec<&Value> = Vec::new();
        for key in ["must", "should"] {
            match b.get(key) {
                Some(Value::Array(a)) => scoring.extend(a.iter()),
                Some(Value::Null) | None => {}
                Some(other) => scoring.push(other),
            }
        }
        let mut direct_knn = scoring.iter().filter(|c| c.get("knn").is_some());
        if let (Some(clause), None) = (direct_knn.next(), direct_knn.next()) {
            if let Some(spec) = clause.get("knn") {
                let specs: Vec<&Value> = match spec {
                    Value::Array(a) => a.iter().collect(),
                    single => vec![single],
                };
                for spec in specs {
                    if let Some(f) = spec.get("field").and_then(Value::as_str) {
                        out.push(f.to_string());
                    }
                }
            }
        }
        let must_not_empty = match b.get("must_not") {
            None | Some(Value::Null) => true,
            Some(Value::Array(a)) => a.is_empty(),
            Some(_) => false,
        };
        if must_not_empty && scoring.len() == 1 {
            dispatching_vector_fields(scoring[0], out);
        }
    }
}

/// Hint for a lexical full-text query aimed at a `semantic_text` field (#363).
///
/// `semantic_text` maps to `FieldType::Text` plus an `EmbeddingConfig`, and the
/// scoring path never consults the embedding: `match` on such a field is
/// byte-identical to `match` on a plain `text` field — same ids, same BM25
/// scores — while the vector it was embedded into is reachable only through
/// `semantic`. Nothing in the response distinguishes the two, so a caller who
/// queried the obvious way cannot tell from the outside that they got none of
/// the semantics. That is not free: on the corpus in the issue the semantic
/// index cost ~12x the indexing time of the BM25-only one (20.7s vs 1.7s for
/// 321 documents) and `match` returned exactly the BM25 answer.
///
/// The lexical behaviour itself is deliberate and separately tested
/// (xerj-engine `test_semantic_text_match_survives_flush`, which exists
/// because BM25 over `semantic_text` used to break at flush), so rewriting
/// `match` into `semantic` would trade one silent surprise for another. This
/// follows Lucene's uniform doctrine for "you asked this field for something
/// it does not do" instead: say so, and name the remedy in the same breath.
/// Both of these throw rather than answer a neighbouring question, and both
/// spell out the fix:
///   * `lucene/core/src/java/org/apache/lucene/index/FloatVectorValues.java:53`
///   * `lucene/core/src/java/org/apache/lucene/index/DocValues.java:206`
///     — closes with "Re-index with correct docvalues type."
///
/// Lucene throws; this only hints. A `match` on `semantic_text` is a valid,
/// answerable request whose answer is BM25 — rejecting it would break callers
/// who want exactly that — so the response stays intact and the diagnosis
/// rides alongside it.
fn lexical_on_semantic_text_hint(
    index: &str,
    body: &EsSearchBody,
    schema: &xerj_common::types::Schema,
) -> Option<Value> {
    let query = body.query.as_ref()?;
    // Nearly every index has no `semantic_text` at all; a linear pass over the
    // field list is strictly cheaper than walking the query JSON, so it goes
    // first and this whole check costs those indices nothing measurable.
    if !schema.fields.iter().any(|f| f.embedding.is_some()) {
        return None;
    }
    let mut lexical = Vec::new();
    lexical_text_clauses(query, &mut lexical);
    if lexical.is_empty() {
        return None;
    }
    // Only the vector clauses that GENUINELY dispatch count as "reached the
    // vector" — a `semantic`/`knn` beside a lexical clause in a multi-clause
    // bool falls through to BM25 and consulted no embedding, so it must not
    // suppress the hint (#394). The top-level `knn` block is the exception:
    // it lives outside `query` and always dispatches.
    let mut vectorised = Vec::new();
    dispatching_vector_fields(query, &mut vectorised);
    if let Some(knn) = body.knn.as_ref() {
        vector_query_fields(&json!({ "knn": knn }), &mut vectorised);
    }

    let mut flagged: Vec<(String, String)> = Vec::new();
    for (field, text) in lexical {
        // Only an exact field name: `ctx.keyword` is a different field with
        // different semantics, and querying it lexically is the point of it.
        let Some(embedding) = schema.field(&field).and_then(|f| f.embedding.as_ref()) else {
            continue;
        };
        let companion = embedding
            .target_field
            .clone()
            .unwrap_or_else(|| format!("{field}_vector"));
        // A caller whose query actually reached the vector for this field
        // (a dispatching `semantic`/`knn`, a top-level `knn`, or a `hybrid`)
        // knows what the field is; repeating it is the noise that mutes a hint
        // channel, and a hybrid is a correct use, not a mistake. A `semantic`
        // clause that never dispatched (a multi-clause bool) is NOT in this set
        // (#394), so its lexical sibling is still flagged.
        if vectorised.iter().any(|f| *f == field || *f == companion) {
            continue;
        }
        if flagged.iter().any(|(f, _)| *f == field) {
            continue;
        }
        flagged.push((field, text));
    }
    let (first_field, first_text) = flagged.first()?.clone();
    let names = flagged
        .iter()
        .map(|(f, _)| format!("`{f}`"))
        .collect::<Vec<_>>()
        .join(", ");
    let plural = flagged.len() > 1;
    // An empty text means a clause shape we did not recognise well enough to
    // quote back; a placeholder is honest, a wrong quote is not.
    let suggested_text = if first_text.is_empty() {
        "<your text>".to_string()
    } else {
        first_text
    };

    Some(json!({
        "hints": [{
            "code": "lexical_on_semantic_text",
            "reason": format!(
                "{names} {} `semantic_text`, but this query scored {} with BM25 over the \
                 analysed text — the embedding written at ingest was NOT consulted, so these \
                 hits are lexical and a paraphrase sharing no words with the target will not \
                 find it. For meaning-based recall run the `semantic` query on `{first_field}`; \
                 to keep both signals, combine them with `hybrid`.",
                if plural { "are" } else { "is" },
                if plural { "them" } else { "it" },
            ),
            "try": {
                "request": format!("POST /{index}/_search"),
                // Query only. The other hints in this module also project
                // `_source`, but they are answering "your response is too
                // big"; this one is answering "you ran the wrong query", and
                // a projection to fields that may not exist in this index
                // would be a second, unasked-for suggestion riding along.
                "body": {
                    "query": {"semantic": {
                        "field": first_field,
                        "query": suggested_text,
                        "k": 10,
                    }},
                },
            },
        }],
    }))
}

/// Hint attached to an oversized `GET /{index}/_doc/{id}` response.
///
/// A document fetch cannot be narrowed the way a search can, so the recovery is
/// to go back through `_search` and ask for the passage instead of the document.
fn get_doc_response_hint(index: &str, doc_bytes: usize) -> Value {
    json!({
        "hints": [{
            "reason": format!(
                "this document's `_source` is {doc_bytes} bytes — for code, that is \
                 the whole file. To retrieve only the function or class you are after, \
                 search for it and request the passage instead of fetching the document."
            ),
            "try": {
                "request": format!("POST /{index}/_search"),
                "body": {
                    "query": {"bool": {"should": [
                        {"multi_match": {
                            "query": "<the symbol or phrase you want>",
                            "fields": ["body", "defs"],
                            "type": "most_fields",
                        }},
                        {"match_phrase": {"defs": {
                            "query": "<the symbol or phrase you want>",
                            "boost": 4,
                        }}},
                    ]}},
                    // Project the path rather than dropping `_source`: a blind
                    // run got the passage, could not tell which file it came
                    // from, and spent 6 MB on follow-ups recovering it. Costs
                    // ~69 bytes and makes the reply a complete answer.
                    "_source": ["ax_path", "title"],
                    "fields": ["_passage"],
                },
            },
        }],
    })
}

fn search_response_hint(index: &str, body: &EsSearchBody, hits: &[EsHit]) -> Option<Value> {
    // Trigger on the SIZE of what we are about to return, not on whether the
    // caller projected `_source`.
    //
    // An earlier version gated on "the caller did not project", which sounded
    // reasonable and was wrong: a blind usability run had an agent project
    // `_source` almost immediately — a good instinct — which silenced the hint
    // permanently. It then pulled 372 KB with `_source:["body"]` and never
    // learned `_passage` existed. Projecting to a whole-file field is exactly
    // the case that needs the hint most, so size is the only honest signal.
    //
    // `_passage` already requested is still a valid reason to stay quiet: that
    // caller has found the mechanism and is choosing its payload deliberately.
    let passage_already_requested = body
        .fields
        .as_ref()
        .is_some_and(fields_request_includes_passage);
    if passage_already_requested {
        return None;
    }

    let source_bytes: usize = hits
        .iter()
        .filter_map(|h| h.source.as_ref())
        .map(|s| serde_json::to_string(s).map(|s| s.len()).unwrap_or(0))
        .sum();
    if source_bytes <= LARGE_RESPONSE_HINT_THRESHOLD_BYTES {
        return None;
    }

    let mut hint = json!({
        "hints": [{
            "reason": format!(
                "this response carried {source_bytes} bytes of `_source` across \
                 {hit_count} hit(s) — for code, that is usually whole files. To get \
                 only the matching function or class, add `\"fields\":[\"_passage\"]` \
                 and drop `_source`.",
                hit_count = hits.len(),
            ),
            "try": {
                "request": format!("POST /{index}/_search"),
                "body": {
                    "query": body.query.clone().unwrap_or_else(|| json!({"match_all": {}})),
                    // Project the path rather than dropping `_source`: a blind
                    // run got the passage, could not tell which file it came
                    // from, and spent 6 MB on follow-ups recovering it. Costs
                    // ~69 bytes and makes the reply a complete answer.
                    "_source": ["ax_path", "title"],
                    "fields": ["_passage"],
                },
            },
        }],
    });
    // The suggestion is "ready to send", so it must still be the caller's
    // search. A request that asked for `rerank` and followed a hint without it
    // would come back in the engine's order, believing it had been reranked.
    // The suggested projection also narrows what the judge is sent — to the
    // title, the path and the matching passage — which is the same trade.
    if let Some(rerank) = &body.rerank {
        hint["hints"][0]["try"]["body"]["rerank"] = rerank.clone();
    }
    // Same rule for the judge block: a suggested request that lost the
    // caller's `judge` would come back unjudged and unpruned.
    if let Some(judge) = &body.judge {
        hint["hints"][0]["try"]["body"]["judge"] = judge.clone();
    }
    Some(hint)
}

/// A short list of existing index names to suggest when `_search` named an
/// index that doesn't exist — the same spirit as the mapping-error path
/// that already enumerates valid field names for an unknown one. Prefers
/// names that share a prefix with, or contain/are contained by, what the
/// caller typed (the common case: a half-remembered or typo'd dataset
/// slug); falls back to the user indices that exist so the hint is never
/// empty just because nothing looked textually similar.
///
/// Dot-prefixed names (`.xerj_*`, `.xerj-memory-*`) sort first and used to
/// win that fallback, so a typo suggested the console's own indices. They
/// stay out of the pool unless the missing name itself is dot-prefixed.
fn nearby_index_names(missing: &str, available: &[String], limit: usize) -> Vec<String> {
    let pool: Vec<&String> = if missing.starts_with('.') {
        available.iter().collect()
    } else {
        available
            .iter()
            .filter(|name| !name.starts_with('.'))
            .collect()
    };
    let missing_lower = missing.to_ascii_lowercase();
    let mut scored: Vec<(usize, &String)> = pool
        .iter()
        .map(|name| {
            let name_lower = name.to_ascii_lowercase();
            let common_prefix = missing_lower
                .chars()
                .zip(name_lower.chars())
                .take_while(|(a, b)| a == b)
                .count();
            let substring_bonus =
                if name_lower.contains(&missing_lower) || missing_lower.contains(&name_lower) {
                    100
                } else {
                    0
                };
            (common_prefix + substring_bonus, *name)
        })
        .collect();
    scored.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(b.1)));
    if scored.first().is_none_or(|(score, _)| *score == 0) {
        let mut all: Vec<String> = pool.iter().map(|n| (*n).clone()).collect();
        all.sort();
        all.truncate(limit);
        return all;
    }
    scored
        .into_iter()
        .take(limit)
        .map(|(_, n)| n.clone())
        .collect()
}

/// Where to point an agent after a missing index. `ax-*` is the default
/// autoindex prefix, so it is the right guess on an empty cluster and on a
/// cluster that actually has `ax-*` indices. It is the wrong guess when the
/// node only has other prefixes — name those instead.
fn index_not_found_guidance(available: &[String]) -> String {
    let cat = "`GET /_cat/indices?v` lists every index that actually exists.";
    let ax_sentence = "Data indexed by `xerj autoindex` lives under indices named `ax-*` — \
         `GET /ax-*/_search` (or any `ax-*` pattern) searches all of it without needing \
         the exact name, and `GET /_cat/indices?v` lists every index that actually exists.";
    let user: Vec<&str> = available
        .iter()
        .map(String::as_str)
        .filter(|name| !name.starts_with('.'))
        .collect();
    if user.is_empty() {
        return ax_sentence.to_string();
    }
    let mut prefixes: Vec<String> = Vec::new();
    for name in &user {
        if let Some((pre, rest)) = name.split_once('-') {
            if !pre.is_empty() && !rest.is_empty() {
                let pattern = format!("{pre}-*");
                if !prefixes.contains(&pattern) {
                    prefixes.push(pattern);
                }
            }
        }
    }
    prefixes.sort();
    if prefixes.is_empty() {
        return cat.to_string();
    }
    if prefixes.len() == 1 && prefixes[0] == "ax-*" {
        return ax_sentence.to_string();
    }
    let listed = prefixes.join(", ");
    let ax_note = if prefixes.iter().any(|p| p == "ax-*") {
        " `GET /ax-*/_search` searches the autoindex prefix."
    } else {
        ""
    };
    format!("Indices on this node use these prefixes: {listed}.{ax_note} {cat}")
}

/// Build the additive `_xerj.hints` hint for a `404 index_not_found_exception`
/// on `_search`. The ES-parity `reason` ("no such index [name]") is fixed
/// byte-for-byte by conformance tests and untouched here — this only rides
/// alongside it with something an agent can actually act on: nearby index
/// names, and the prefix those indices actually use.
fn index_not_found_hint(missing: &str, available: &[String]) -> Value {
    let candidates = nearby_index_names(missing, available, 5);
    let candidates_line = if candidates.is_empty() {
        String::new()
    } else {
        format!(
            "Existing index name(s) close to that: {}. ",
            candidates.join(", ")
        )
    };
    json!({
        "hints": [{
            "reason": format!(
                "no index matches [{missing}]. {candidates_line}{}",
                index_not_found_guidance(available),
            ),
            "candidates": candidates,
        }],
    })
}

#[cfg(test)]
mod search_response_hint_tests {
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::Request,
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    /// Index one document whose `content` field alone is comfortably over
    /// `LARGE_RESPONSE_HINT_THRESHOLD_BYTES`, so an unprojected `_search`
    /// against it is the exact shape the hint exists for.
    async fn index_one_big_doc(state: &AppState, index: &str) {
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("content", FieldType::Text));
        state.engine.create_index(index, schema).unwrap();
        let idx = state.engine.get_index(index).unwrap();
        idx.index_document(
            Some("1".into()),
            json!({"content": "the quick brown fox jumps over the lazy dog. ".repeat(200)}),
        )
        .await
        .unwrap();
        idx.refresh().await.unwrap();
    }

    async fn run_search(router: &axum::Router, index: &str, body: Value) -> (Value, String) {
        let response = router
            .clone()
            .oneshot(
                Request::post(format!("/{index}/_search"))
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let text = String::from_utf8(bytes.to_vec()).expect("utf8 response body");
        let json: Value = serde_json::from_str(&text).expect("valid JSON response body");
        (json, text)
    }

    fn has_unknown_value_hint(json: &Value) -> bool {
        json["_xerj"]["hints"].as_array().is_some_and(|hints| {
            hints
                .iter()
                .any(|h| h["code"].as_str() == Some("unknown_value"))
        })
    }

    #[test]
    fn zero_hit_value_sample_gates_on_the_match_set_not_the_page() {
        // #2451: a `size: 0` probe never samples, hit or miss.
        assert!(!super::zero_hit_value_sample_applies(0, true, 0, false));
        assert!(!super::zero_hit_value_sample_applies(0, true, 7, false));
        assert!(!super::zero_hit_value_sample_applies(0, true, 0, true));
        // A page past the end of a non-empty match set is not a wrong value.
        assert!(!super::zero_hit_value_sample_applies(10, true, 7, false));
        // The case the hint exists for, tracked total or not.
        assert!(super::zero_hit_value_sample_applies(10, true, 0, false));
        assert!(super::zero_hit_value_sample_applies(10, true, 0, true));
        assert!(!super::zero_hit_value_sample_applies(10, false, 3, false));
    }

    #[tokio::test]
    async fn size_zero_term_probe_skips_the_unknown_value_sample() {
        let state = test_state();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("kind", FieldType::Keyword));
        state.engine.create_index("hint-probe", schema).unwrap();
        let idx = state.engine.get_index("hint-probe").unwrap();
        for (id, kind) in [("1", "alpha"), ("2", "beta")] {
            idx.index_document(Some(id.into()), json!({ "kind": kind }))
                .await
                .unwrap();
        }
        idx.refresh().await.unwrap();
        let router = crate::router::build_es_compat_router(state);

        // A search that asked for hits and matched nothing keeps the hint.
        let (json, _) = run_search(
            &router,
            "hint-probe",
            json!({"size": 10, "query": {"term": {"kind": "gamma"}}}),
        )
        .await;
        assert!(has_unknown_value_hint(&json), "hint expected: {json}");

        // The autoindex existence-probe shape, miss and hit: an exact total,
        // no sample (#2451).
        for (value, total) in [("gamma", 0), ("alpha", 1)] {
            let (json, _) = run_search(
                &router,
                "hint-probe",
                json!({"size": 0, "track_total_hits": true,
                       "query": {"term": {"kind": value}}}),
            )
            .await;
            assert_eq!(json["hits"]["total"]["value"], total, "{json}");
            assert!(!has_unknown_value_hint(&json), "no hint for size 0: {json}");
        }
    }

    #[tokio::test]
    async fn hint_appears_for_a_large_unprojected_response() {
        let state = test_state();
        index_one_big_doc(&state, "hint-large").await;
        let router = crate::router::build_es_compat_router(state);

        let (json, _) =
            run_search(&router, "hint-large", json!({"query": {"match_all": {}}})).await;
        let hints = json["_xerj"]["hints"]
            .as_array()
            .expect("hints array present");
        assert!(!hints.is_empty());
        assert!(
            hints[0]["reason"].as_str().unwrap().contains("_passage"),
            "hint should point at `_passage`: {json}"
        );
        assert_eq!(hints[0]["try"]["body"]["fields"], json!(["_passage"]));
        // Additive only — must not disturb the real ES-compat fields.
        assert_eq!(json["hits"]["total"]["value"], 1);
    }

    #[tokio::test]
    async fn hint_is_absent_when_source_is_disabled() {
        let state = test_state();
        index_one_big_doc(&state, "hint-projected").await;
        let router = crate::router::build_es_compat_router(state);

        let (json, _) = run_search(
            &router,
            "hint-projected",
            json!({"query": {"match_all": {}}, "_source": false}),
        )
        .await;
        assert!(json.get("_xerj").is_none(), "unexpected hint: {json}");
    }

    /// Regression for a defect a blind usability run exposed: the hint used to
    /// be suppressed whenever the caller projected `_source` at all. A fresh
    /// user projected early — a good instinct — and thereby silenced the hint
    /// for the rest of the session, then pulled 372 KB with `_source:["body"]`
    /// and never discovered `_passage`. Projecting to a whole-file field is the
    /// case that needs the hint most, so the trigger is size, not projection.
    #[tokio::test]
    async fn hint_still_appears_when_source_is_projected_to_a_large_field() {
        let state = test_state();
        index_one_big_doc(&state, "hint-projected-big").await;
        let router = crate::router::build_es_compat_router(state);

        let (json, _) = run_search(
            &router,
            "hint-projected-big",
            json!({"query": {"match_all": {}}, "_source": ["content"]}),
        )
        .await;
        assert!(
            json.get("_xerj").is_some(),
            "a large projected response must still hint: {json}"
        );
    }

    #[tokio::test]
    async fn hint_is_absent_when_passage_already_requested() {
        let state = test_state();
        index_one_big_doc(&state, "hint-passage").await;
        let router = crate::router::build_es_compat_router(state);

        let (json, _) = run_search(
            &router,
            "hint-passage",
            json!({
                "query": {"match": {"content": "fox"}},
                "fields": ["_passage"]
            }),
        )
        .await;
        assert!(json.get("_xerj").is_none(), "unexpected hint: {json}");
    }

    #[tokio::test]
    async fn hint_is_absent_for_a_small_response() {
        let state = test_state();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("content", FieldType::Text));
        state.engine.create_index("hint-small", schema).unwrap();
        let idx = state.engine.get_index("hint-small").unwrap();
        idx.index_document(Some("1".into()), json!({"content": "tiny"}))
            .await
            .unwrap();
        idx.refresh().await.unwrap();
        let router = crate::router::build_es_compat_router(state);

        let (json, _) =
            run_search(&router, "hint-small", json!({"query": {"match_all": {}}})).await;
        assert!(json.get("_xerj").is_none(), "unexpected hint: {json}");
    }

    /// PLACEMENT MATTERS: an agent that truncates long output from the
    /// bottom never sees a hint trailing a multi-hundred-KB `hits` array.
    /// Assert on the raw wire bytes, not the parsed `Value` — a
    /// `serde_json::Value` only preserves the order it was built in
    /// (workspace-wide `preserve_order`, see xerj-common/Cargo.toml); this
    /// test is what actually proves that order survives serialisation onto
    /// the wire.
    #[tokio::test]
    async fn hint_key_precedes_hits_in_the_serialised_bytes() {
        let state = test_state();
        index_one_big_doc(&state, "hint-order").await;
        let router = crate::router::build_es_compat_router(state);

        let (json, text) =
            run_search(&router, "hint-order", json!({"query": {"match_all": {}}})).await;
        assert!(json.get("_xerj").is_some(), "expected a hint: {json}");

        let hint_pos = text.find("\"_xerj\"").expect("_xerj key in wire bytes");
        let hits_pos = text.find("\"hits\"").expect("hits key in wire bytes");
        assert!(
            hint_pos < hits_pos,
            "_xerj (byte {hint_pos}) must precede hits (byte {hits_pos}): {text}"
        );
    }

    #[tokio::test]
    async fn index_not_found_hint_suggests_nearby_index_names_and_wildcard() {
        let state = test_state();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("content", FieldType::Text));
        // Shares a long prefix with the typo'd name searched below.
        state.engine.create_index("ax-reports", schema).unwrap();
        let router = crate::router::build_es_compat_router(state);

        let response = router
            .oneshot(
                Request::post("/ax-report/_search")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({"query": {"match_all": {}}}).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NOT_FOUND);
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json: Value = serde_json::from_slice(&bytes).unwrap();

        // ES-compat contract (conformance-tested elsewhere) stays byte-exact.
        assert_eq!(json["error"]["type"], "index_not_found_exception");
        assert_eq!(json["error"]["reason"], "no such index [ax-report]");

        // The additive hint rides alongside it, unrecognized by ES clients.
        let hints = json["_xerj"]["hints"]
            .as_array()
            .expect("hints array present");
        assert!(
            hints[0]["candidates"]
                .as_array()
                .unwrap()
                .contains(&json!("ax-reports")),
            "expected ax-reports among candidates: {json}"
        );
        assert!(hints[0]["reason"].as_str().unwrap().contains("ax-*"));
    }

    /// A missing index with no live indices at all (an empty/fresh cluster)
    /// still gets the `ax-*` wildcard guidance — the hint must not assume a
    /// nonempty candidate list.
    #[tokio::test]
    async fn index_not_found_hint_on_an_empty_cluster_still_mentions_the_wildcard() {
        let state = test_state();
        let router = crate::router::build_es_compat_router(state);

        let response = router
            .oneshot(
                Request::post("/anything/_search")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({"query": {"match_all": {}}}).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NOT_FOUND);
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(json["error"]["reason"], "no such index [anything]");
        let hints = json["_xerj"]["hints"]
            .as_array()
            .expect("hints array present");
        assert_eq!(hints[0]["candidates"], json!([]));
        assert!(hints[0]["reason"].as_str().unwrap().contains("ax-*"));
    }

    /// Score-0 fallback used to sort every name and keep the first five.
    /// `.` sorts before letters, so `.xerj_users` won over `logs-app` and the
    /// reason still claimed the data lived under `ax-*`.
    #[tokio::test]
    async fn index_not_found_hint_skips_system_indices_and_names_the_real_prefix() {
        let state = test_state();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("content", FieldType::Text));
        state
            .engine
            .create_index(".xerj_users", schema.clone())
            .unwrap();
        state.engine.create_index("logs-app", schema).unwrap();
        let router = crate::router::build_es_compat_router(state);

        let response = router
            .oneshot(
                Request::post("/qqqq/_search")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({"query": {"match_all": {}}}).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NOT_FOUND);
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(json["error"]["type"], "index_not_found_exception");
        assert_eq!(json["error"]["reason"], "no such index [qqqq]");
        let hints = json["_xerj"]["hints"].as_array().expect("hints");
        assert_eq!(hints[0]["candidates"], json!(["logs-app"]));
        let reason = hints[0]["reason"].as_str().unwrap();
        assert!(reason.contains("logs-*"), "{reason}");
        assert!(reason.contains("_cat/indices"), "{reason}");
        assert!(
            !reason.contains("ax-*"),
            "must not claim an ax-* corpus that is not on this node: {reason}"
        );
    }
}

#[cfg(test)]
mod semantic_text_lexical_hint_tests {
    //! #363 — `match` on a `semantic_text` field runs BM25 and answers a
    //! different question than the caller thinks they asked. The lexical
    //! behaviour itself is deliberate and separately tested (xerj-engine
    //! `test_semantic_text_match_survives_flush`), so the remedy is to say
    //! so out loud, not to rewrite `match` into `semantic` underneath the
    //! caller. `control_index_*` is the reproduction: the same documents,
    //! the same query, one index declaring `ctx` as `semantic_text` and one
    //! as plain `text`, asserted to return the same ids AND the same scores.
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::Request,
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    async fn request_json(
        state: &AppState,
        method: &str,
        path: &str,
        body: Value,
    ) -> (StatusCode, Value) {
        let response = crate::router::build_es_compat_router(state.clone())
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("route response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json = serde_json::from_slice(&bytes).unwrap_or_else(|error| {
            panic!(
                "{method} {path} returned non-JSON ({error}): {}",
                String::from_utf8_lossy(&bytes)
            )
        });
        (status, json)
    }

    /// Three documents about graph pruning, indexed into `index` with `ctx`
    /// declared as `ctx_type`. Everything except that one mapping entry is
    /// identical between calls, which is what makes the control comparison
    /// below a control.
    const DOCS: [&str; 3] = [
        "the hnsw graph builder prunes redundant neighbour edges",
        "the segment merger rewrites postings and term dictionaries",
        "a graph left unpruned becomes densely clustered near the entry node",
    ];

    async fn build_index(state: &AppState, index: &str, ctx_type: Value) {
        let (status, body) = request_json(
            state,
            "PUT",
            &format!("/{index}"),
            json!({"mappings": {"properties": {
                "ctx": ctx_type,
                "title": {"type": "text"},
            }}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        for (id, text) in DOCS.iter().enumerate() {
            let (status, body) = request_json(
                state,
                "PUT",
                &format!("/{index}/_doc/{id}"),
                json!({"ctx": text, "title": format!("doc {id}")}),
            )
            .await;
            assert!(status.is_success(), "{body}");
        }
        state
            .engine
            .get_index(index)
            .expect("index")
            .refresh()
            .await
            .expect("refresh");
    }

    fn hint_codes(json: &Value) -> Vec<String> {
        json["_xerj"]["hints"]
            .as_array()
            .map(|hints| {
                hints
                    .iter()
                    .filter_map(|h| h["code"].as_str().map(str::to_string))
                    .collect()
            })
            .unwrap_or_default()
    }

    fn semantic_hint(json: &Value) -> Option<&Value> {
        json["_xerj"]["hints"]
            .as_array()?
            .iter()
            .find(|h| h["code"] == json!("lexical_on_semantic_text"))
    }

    /// THE REPRODUCTION. `match` on `semantic_text` is not merely "also
    /// lexical" — it is indistinguishable from `match` on a field that has
    /// no embedding at all, down to the score. Nothing about the response
    /// tells the caller which of the two questions was answered.
    #[tokio::test]
    async fn control_index_proves_match_on_semantic_text_is_plain_bm25() {
        let state = test_state();
        build_index(
            &state,
            "sem-ctl-sem",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;
        build_index(&state, "sem-ctl-txt", json!({"type": "text"})).await;

        let query = json!({"query": {"match": {"ctx": "graph edges"}}, "_source": false});
        let (status, semantic_index) =
            request_json(&state, "POST", "/sem-ctl-sem/_search", query.clone()).await;
        assert_eq!(status, StatusCode::OK, "{semantic_index}");
        let (status, control_index) =
            request_json(&state, "POST", "/sem-ctl-txt/_search", query).await;
        assert_eq!(status, StatusCode::OK, "{control_index}");

        let ids = |json: &Value| -> Vec<String> {
            json["hits"]["hits"]
                .as_array()
                .expect("hits")
                .iter()
                .map(|h| h["_id"].as_str().unwrap().to_string())
                .collect()
        };
        let scores = |json: &Value| -> Vec<f64> {
            json["hits"]["hits"]
                .as_array()
                .expect("hits")
                .iter()
                .map(|h| h["_score"].as_f64().unwrap())
                .collect()
        };
        assert!(!ids(&semantic_index).is_empty(), "{semantic_index}");
        assert_eq!(
            ids(&semantic_index),
            ids(&control_index),
            "semantic_text: {semantic_index}\ncontrol: {control_index}"
        );
        assert_eq!(
            scores(&semantic_index),
            scores(&control_index),
            "identical BM25 scores prove the embedding is never consulted"
        );
    }

    /// The fix: the response now says which question it answered and names
    /// the query that answers the other one.
    #[tokio::test]
    async fn match_on_semantic_text_is_flagged_and_names_the_semantic_query() {
        let state = test_state();
        build_index(
            &state,
            "sem-hint",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-hint/_search",
            json!({"query": {"match": {"ctx": "graph edges"}}, "_source": false}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");

        // Additive only: the lexical answer itself is unchanged.
        assert!(
            !json["hits"]["hits"].as_array().unwrap().is_empty(),
            "the hint must not change what `match` returns: {json}"
        );

        let hint = semantic_hint(&json)
            .unwrap_or_else(|| panic!("expected a lexical_on_semantic_text hint: {json}"));
        let reason = hint["reason"].as_str().expect("reason string");
        assert!(reason.contains("ctx"), "must name the field: {reason}");
        assert!(reason.contains("BM25"), "must name what it ran: {reason}");
        // NAME THE REMEDY, in a form that can be pasted back.
        assert_eq!(hint["try"]["body"]["query"]["semantic"]["field"], "ctx");
        assert_eq!(
            hint["try"]["body"]["query"]["semantic"]["query"], "graph edges",
            "the suggested body must carry the caller's own text: {hint}"
        );

        // A remedy that does not run is worse than no remedy: paste the
        // hint's own body straight back and require a real answer from it.
        let (status, remedy) = request_json(
            &state,
            "POST",
            "/sem-hint/_search",
            hint["try"]["body"].clone(),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{remedy}");
        assert!(
            !remedy["hits"]["hits"].as_array().unwrap().is_empty(),
            "the suggested `semantic` body must actually return hits: {remedy}"
        );
    }

    /// The same trap through `multi_match` — the shape the issue flagged as
    /// untested and expected to behave identically.
    #[tokio::test]
    async fn multi_match_naming_a_semantic_text_field_is_flagged() {
        let state = test_state();
        build_index(
            &state,
            "sem-mm",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-mm/_search",
            json!({"query": {"multi_match": {
                "query": "graph edges",
                "fields": ["title", "ctx^2"],
            }}, "_source": false}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        let hint = semantic_hint(&json)
            .unwrap_or_else(|| panic!("expected a lexical_on_semantic_text hint: {json}"));
        assert!(
            hint["reason"].as_str().unwrap().contains("ctx"),
            "the boost suffix must not hide the field: {hint}"
        );
    }

    /// A plain `text` field is the whole point of `match`. Firing there
    /// would make the hint noise, and noise is how a hint channel dies.
    #[tokio::test]
    async fn match_on_a_plain_text_field_is_not_flagged() {
        let state = test_state();
        build_index(&state, "sem-plain", json!({"type": "text"})).await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-plain/_search",
            json!({"query": {"match": {"ctx": "graph edges"}}, "_source": false}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        assert!(
            semantic_hint(&json).is_none(),
            "no embedding config, nothing to warn about: {json}"
        );
    }

    /// #394: a `semantic` clause sitting BESIDE a lexical one in a multi-clause
    /// bool never reaches the vector. `peel_semantic_query` dispatches a bool to
    /// the vector only when `must`+`should` holds exactly one candidate, so this
    /// query runs BM25-only and the embedding is not consulted. The prior rule
    /// read the bare `semantic` clause as "the caller reached the vector" and
    /// suppressed the hint — reintroducing the very silence it exists to break.
    /// It must be flagged.
    #[tokio::test]
    async fn a_semantic_clause_that_never_reached_the_vector_is_still_flagged() {
        let state = test_state();
        build_index(
            &state,
            "sem-both",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-both/_search",
            json!({"query": {"bool": {"should": [
                {"match": {"ctx": "graph edges"}},
                {"semantic": {"field": "ctx", "query": "graph edges", "k": 3}},
            ]}}, "_source": false}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        let hint = semantic_hint(&json).unwrap_or_else(|| {
            panic!(
                "#394: a nested semantic beside a lexical clause never reached the \
                 vector, so the `match` must still be flagged: {json}"
            )
        });
        assert!(
            hint["reason"].as_str().unwrap().contains("ctx"),
            "must name the field: {hint}"
        );
    }

    /// Regression guard for the #394 dispatch-aware suppression: a `hybrid`
    /// query fuses and runs its lexical AND vector branches, so the vector IS
    /// consulted and the lexical branch must NOT be nagged. Narrowing the rule
    /// to genuinely-dispatching clauses must keep suppressing here.
    #[tokio::test]
    async fn a_hybrid_query_over_the_semantic_field_is_not_flagged() {
        let state = test_state();
        build_index(
            &state,
            "sem-hyb",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-hyb/_search",
            json!({"query": {"hybrid": {"queries": [
                {"query": {"match": {"ctx": "graph edges"}}},
                {"query": {"knn": {"field": "ctx_vector", "query_vector": vec![0.1_f32; 32], "k": 3}}},
            ]}}, "_source": false}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        assert!(
            semantic_hint(&json).is_none(),
            "a hybrid consults the vector; nagging its lexical half is wrong: {json}"
        );
    }

    /// The ES 8.x hand-rolled hybrid — top-level `knn` over the companion
    /// vector plus a `match` for the lexical half — lives OUTSIDE `query`,
    /// so a suppression check that only walked `query` would nag the one
    /// caller who did the most correct thing available to them.
    #[tokio::test]
    async fn a_top_level_knn_over_the_companion_vector_suppresses_the_hint() {
        let state = test_state();
        build_index(
            &state,
            "sem-knn",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-knn/_search",
            json!({
                "query": {"match": {"ctx": "graph edges"}},
                "knn": {"field": "ctx_vector", "query_vector": vec![0.1_f32; 32], "k": 3},
                "_source": false,
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        assert!(
            semantic_hint(&json).is_none(),
            "the caller already reached the vector: {json}"
        );
    }

    /// The hint rides alongside the existing diagnostics rather than
    /// displacing one: a query naming a nonexistent field AND a
    /// semantic_text field must report both. Runs in the default (lenient)
    /// mode — the strict opt-in of #1093 would refuse this query before
    /// hints exist, and the additivity being pinned here is a property of
    /// lenient responses.
    #[tokio::test]
    async fn the_hint_is_additive_to_the_unknown_field_hint() {
        let state = test_state();
        build_index(
            &state,
            "sem-multi",
            json!({"type": "semantic_text", "dimensions": 32}),
        )
        .await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/sem-multi/_search",
            json!({"query": {"bool": {"should": [
                {"match": {"ctx": "graph edges"}},
                {"match": {"nope": "graph edges"}},
            ]}}, "_source": false}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        let codes = hint_codes(&json);
        assert!(
            codes.contains(&"unknown_field".to_string())
                && codes.contains(&"lexical_on_semantic_text".to_string()),
            "both diagnostics must survive: {codes:?} / {json}"
        );
    }
}

/// #1093 — opt-in strict mode refuses lookup clauses (`term`, `match`,
/// `range`, …) naming fields no target index maps, instead of ES's silent
/// 0-hit 200 that a caller cannot tell from an empty corpus. The default is
/// ES's own lenient answer (with the `_xerj.hints` diagnostic); strictness
/// comes from `?strict_unknown_fields=true`, the
/// `index.query.strict_unknown_fields` setting, or an autoindex-created
/// index. Pinned here: the refusal, both opt-in routes and the per-request
/// opt-out, the `exists` exemption, the fresh-index exemption, and the
/// walker's span_multi/intervals special cases.
#[cfg(test)]
mod unknown_field_refusal_tests {
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::Request,
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    async fn request_json(
        state: &AppState,
        method: &str,
        path: &str,
        body: Value,
    ) -> (StatusCode, Value) {
        let response = crate::router::build_es_compat_router(state.clone())
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("route response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json = serde_json::from_slice(&bytes).unwrap_or_else(|error| {
            panic!(
                "{method} {path} returned non-JSON ({error}): {}",
                String::from_utf8_lossy(&bytes)
            )
        });
        (status, json)
    }

    /// `ctx` text + `status` keyword, three documents.
    async fn build_index(state: &AppState, index: &str) {
        let (status, body) = request_json(
            state,
            "PUT",
            &format!("/{index}"),
            json!({"mappings": {"properties": {
                "ctx": {"type": "text"},
                "status": {"type": "keyword"},
                "title": {"type": "text"},
            }}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        for (id, text) in ["alpha graph", "beta edges", "gamma nodes"]
            .iter()
            .enumerate()
        {
            let (status, body) = request_json(
                state,
                "PUT",
                &format!("/{index}/_doc/{id}"),
                json!({"ctx": text, "status": "ok", "title": format!("doc {id}")}),
            )
            .await;
            assert!(status.is_success(), "{body}");
        }
        state
            .engine
            .get_index(index)
            .expect("index")
            .refresh()
            .await
            .expect("refresh");
    }

    fn reason(json: &Value) -> String {
        json["error"]["root_cause"][0]["reason"]
            .as_str()
            .unwrap_or_default()
            .to_string()
    }

    /// The refusal itself: every unknown lookup clause is named, the envelope
    /// is the house 400, and the reason carries the way out.
    #[tokio::test]
    async fn unknown_lookup_fields_are_refused_with_every_clause_named() {
        let state = test_state();
        build_index(&state, "uf-strict").await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/uf-strict/_search?strict_unknown_fields=true",
            json!({"query": {"bool": {"must": [
                {"term": {"stauts": "ok"}},
                {"range": {"titel": {"gte": "a"}}},
            ]}}}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{json}");
        assert_eq!(json["error"]["type"], "search_phase_execution_exception");
        let r = reason(&json);
        assert!(
            r.contains("unknown field `stauts` in term clause")
                && r.contains("unknown field `titel` in range clause"),
            "both clauses named: {r}"
        );
        assert!(
            r.contains("strict_unknown_fields=false"),
            "the per-request opt-out is in the reason: {r}"
        );

        // The default, no param: ES's own silent 0-hit.
        let (status, json) = request_json(
            &state,
            "POST",
            "/uf-strict/_search",
            json!({"query": {"term": {"stauts": "ok"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "default is lenient: {json}");
        assert_eq!(json["hits"]["total"]["value"], 0, "{json}");
    }

    /// The default carries the `_xerj.hints` unknown-field diagnostic, so a
    /// lenient caller keeps the explanation a strict caller gets as a 400 —
    /// and the per-request opt-out beats a strict index setting.
    #[tokio::test]
    async fn the_default_is_lenient_with_the_hint_and_false_beats_the_setting() {
        let state = test_state();
        build_index(&state, "uf-lenient").await;

        let (status, json) = request_json(
            &state,
            "POST",
            "/uf-lenient/_search",
            json!({"query": {"term": {"stauts": "ok"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        assert_eq!(json["hits"]["total"]["value"], 0, "{json}");
        let codes = json["_xerj"]["hints"]
            .as_array()
            .map(|h| {
                h.iter()
                    .filter_map(|x| x["code"].as_str())
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        assert!(
            codes.contains(&"unknown_field"),
            "lenient mode keeps the hint: {codes:?} / {json}"
        );

        // Now make the index strict and opt out for one request.
        let (status, body) = request_json(
            &state,
            "PUT",
            "/uf-lenient/_settings",
            json!({"index.query.strict_unknown_fields": true}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let (status, _) = request_json(
            &state,
            "POST",
            "/uf-lenient/_search",
            json!({"query": {"term": {"stauts": "ok"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "the setting enforces");

        let (status, json) = request_json(
            &state,
            "POST",
            "/uf-lenient/_search?strict_unknown_fields=false",
            json!({"query": {"term": {"stauts": "ok"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "?false beats the setting: {json}");
        assert_eq!(json["hits"]["total"]["value"], 0, "{json}");
    }

    /// The per-index setting — any ONE resolved index marked strict covers
    /// the whole request, so a heterogeneous alias cannot answer the very
    /// 0-hit its strict member was configured to refuse.
    #[tokio::test]
    async fn the_index_setting_enforces_strict_for_the_whole_request() {
        let state = test_state();
        build_index(&state, "uf-set-a").await;
        build_index(&state, "uf-set-b").await;
        let (status, body) = request_json(
            &state,
            "PUT",
            "/uf-set-b/_settings",
            json!({"index.query.strict_unknown_fields": true}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");

        // No strict member: the lenient default.
        let (status, _) = request_json(
            &state,
            "POST",
            "/uf-set-a/_search",
            json!({"query": {"term": {"stauts": "ok"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK);

        // With the strict member in the target set: refused.
        let (status, json) = request_json(
            &state,
            "POST",
            "/uf-set-a,uf-set-b/_search",
            json!({"query": {"term": {"stauts": "ok"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{json}");
        assert!(
            reason(&json).contains("unknown field `stauts` in term clause"),
            "the field is named: {json}"
        );
    }

