    /// `_msearch` refuses the offending item alone, ES's per-item error
    /// shape, and the rest of the batch still runs — against a strict index,
    /// since NDJSON items carry no URL params.
    #[tokio::test]
    async fn msearch_refuses_the_offending_item_and_runs_its_sibling() {
        let state = test_state();
        build_index(&state, "uf-ms").await;
        let (status, body) = request_json(
            &state,
            "PUT",
            "/uf-ms/_settings",
            json!({"index.query.strict_unknown_fields": true}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");

        let response = crate::router::build_es_compat_router(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/_msearch")
                    .header("content-type", "application/x-ndjson")
                    .body(Body::from(concat!(
                        "{\"index\":\"uf-ms\"}\n",
                        "{\"query\":{\"term\":{\"stauts\":\"ok\"}}}\n",
                        "{\"index\":\"uf-ms\"}\n",
                        "{\"query\":{\"term\":{\"status\":\"ok\"}}}\n",
                    )))
                    .expect("request"),
            )
            .await
            .expect("route response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json: Value = serde_json::from_slice(&bytes).expect("msearch json");
        assert_eq!(status, StatusCode::OK, "{json}");
        let responses = json["responses"].as_array().expect("responses");
        assert_eq!(responses.len(), 2, "{json}");
        assert_eq!(responses[0]["status"], 400, "{json}");
        assert_eq!(
            responses[0]["error"]["type"],
            "search_phase_execution_exception"
        );
        assert!(
            responses[0]["error"]["root_cause"][0]["reason"]
                .as_str()
                .unwrap_or_default()
                .contains("unknown field `stauts` in term clause"),
            "the item names the field: {json}"
        );
        assert_eq!(responses[1]["status"], 200, "{json}");
        assert!(
            responses[1]["hits"]["total"]["value"].as_i64().unwrap_or(0) > 0,
            "the sibling item ran: {json}"
        );
    }

    /// #2121: `xerj search` and MCP `xerj_search` send one plain-string
    /// definition-first body at the prefix pattern (`proj-*`). That pattern
    /// spans a code index and a JSON/CSV index that maps none of
    /// `body`/`defs`/`code`/`name`. Those fields exist on the code index, so
    /// the search must return that hit and must not attach an `unknown_field`
    /// hint. The hint stays when no matched index maps the field.
    ///
    /// The comma target lists the CSV index first. Resolution preserves that
    /// order, which is the case a first-schema check gets wrong. `proj-*` is
    /// the pattern `xerj search --prefix proj` sends.
    #[tokio::test]
    async fn mixed_pattern_does_not_hint_a_field_some_index_maps() {
        let state = test_state();
        let strict_settings = json!({
            "settings": {"index": {"query": {"strict_unknown_fields": true}}},
        });
        let mut code_create = strict_settings.clone();
        code_create["mappings"] = json!({"properties": {
            "name": {"type": "keyword"},
            "code": {"type": "text"},
            "body": {"type": "text"},
            "defs": {"type": "text"},
            "title": {"type": "text"},
            "ax_path": {"type": "keyword"},
            "line": {"type": "long"},
        }});
        let mut csv_create = strict_settings;
        csv_create["mappings"] = json!({"properties": {
            "sku": {"type": "keyword"},
            "qty": {"type": "long"},
            "note": {"type": "text"},
        }});
        for (index, body) in [("proj-code", code_create), ("proj-csv", csv_create)] {
            let (status, resp) = request_json(&state, "PUT", &format!("/{index}"), body).await;
            assert_eq!(status, StatusCode::OK, "{index}: {resp}");
        }

        let (status, resp) = request_json(
            &state,
            "PUT",
            "/proj-code/_doc/sign",
            json!({
                "name": "SignWithSM2",
                "code": "func SignWithSM2(digest []byte)",
                "body": "func SignWithSM2(digest []byte) signature",
                "defs": "func SignWithSM2",
                "title": "sm2_dsa.go",
                "ax_path": "sm2/sm2_dsa.go",
                "line": 126,
            }),
        )
        .await;
        assert!(status.is_success(), "{resp}");
        let (status, resp) = request_json(
            &state,
            "PUT",
            "/proj-csv/_doc/row1",
            json!({"sku": "A1", "qty": 3, "note": "crate of bolts"}),
        )
        .await;
        assert!(status.is_success(), "{resp}");
        for index in ["proj-code", "proj-csv"] {
            state
                .engine
                .get_index(index)
                .expect(index)
                .refresh()
                .await
                .expect("refresh");
        }

        // The body both plain-string clients send. `mapped_property_names`
        // is the union `xerj search` and `xerj_search` read from
        // `GET /{pattern}/_mapping`; one code index is enough to keep
        // `defs` / `name` even though the CSV index maps neither.
        let mapping = json!({
            "proj-csv": {"mappings": {"properties": {
                "sku": {"type": "keyword"},
                "qty": {"type": "long"},
                "note": {"type": "text"},
            }}},
            "proj-code": {"mappings": {"properties": {
                "name": {"type": "keyword"},
                "code": {"type": "text"},
                "body": {"type": "text"},
                "defs": {"type": "text"},
                "title": {"type": "text"},
                "ax_path": {"type": "keyword"},
                "line": {"type": "long"},
            }}},
        });
        let mapped = xerj_common::code_query::mapped_property_names(&mapping)
            .expect("heterogeneous mapping");
        let numeric = xerj_common::code_query::numeric_property_names(&mapping);
        let query = xerj_common::code_query::search_query_body_for_mapping(
            "SignWithSM2",
            10,
            Some(&mapped),
            Some(&numeric),
        );
        let rendered = query["query"].to_string();
        assert!(
            rendered.contains("\"defs\"") && rendered.contains("\"name\""),
            "plain-string body must keep a field any matched index maps: {query}"
        );
        for path in ["/proj-csv,proj-code/_search", "/proj-*/_search"] {
            let (status, json) = request_json(&state, "POST", path, query.clone()).await;
            assert_eq!(status, StatusCode::OK, "{path}: {json}");
            let hits = json["hits"]["hits"].as_array().expect("hits");
            assert!(
                hits.iter().any(|h| {
                    h["_index"] == "proj-code" && h["_source"]["ax_path"] == "sm2/sm2_dsa.go"
                }),
                "{path} must return the code hit: {json}"
            );
            let codes = json["_xerj"]["hints"]
                .as_array()
                .map(|h| {
                    h.iter()
                        .filter_map(|x| x["code"].as_str())
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            assert!(
                !codes.contains(&"unknown_field"),
                "{path} hinted a field another matched index maps: {codes:?} / {json}"
            );
        }

        // No matched index maps `phantom`. Lenient mode still explains it;
        // strict mode (already on these indices, the autoindex default)
        // still refuses it.
        let (status, json) = request_json(
            &state,
            "POST",
            "/proj-csv,proj-code/_search?strict_unknown_fields=false",
            json!({"query": {"term": {"phantom": "x"}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{json}");
        let reason = json["_xerj"]["hints"]
            .as_array()
            .and_then(|h| h.iter().find(|x| x["code"] == "unknown_field"))
            .and_then(|h| h["reason"].as_str())
            .unwrap_or("");
        assert!(
            reason.contains("phantom"),
            "a field on no matched index must still hint: {json}"
        );

        let (status, json) = request_json(
            &state,
            "POST",
            "/proj-*/_search",
            json!({"query": {"term": {"phantom": "x"}}}),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::BAD_REQUEST,
            "strict still refuses a field no index maps: {json}"
        );
    }
}

/// `POST /{index}/_search`.
///
/// Thin wrapper over [`search_impl`] that installs the Painless fault sink for
/// every script this handler evaluates *itself* — `script_fields` and
/// `runtime_mappings` emit-scripts run during response assembly, outside the
/// spawned search task, so they are not covered by the engine-side capture in
/// `Index::search`. Both used to drop a failed script's value on the floor
/// (`if let Ok(pv) = …`), which is right for a script outside our Painless
/// subset but wrong for a resource-limit trip: the field silently vanished
/// from the response with no error anywhere. A limit fault now fails the
/// request.
pub async fn search(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<EsSearchQueryParams>,
    // Issue #329: the audit entry this handler writes used to record the string
    // literal `"anonymous"` for every search, authenticated or not, so the one
    // audited data-path operation was unattributable. The principal is threaded
    // through to `search_impl` for that entry and nothing else.
    principal: crate::auth::Principal,
    body: EsSearchJson,
) -> Response {
    // `Box::pin` is load-bearing, not style. `search_impl`'s future is
    // enormous (thousands of lines of inlined async state), and without the
    // box this wrapper's future embeds a second copy of it by value —
    // `memory_api`'s recall test, which calls this handler directly, overflows
    // its stack on the extra copy. Boxing keeps the wrapper pointer-sized.
    let (response, fault) = xerj_engine::painless::with_script_fault_capture(Box::pin(
        search_dispatch(state, index, params, principal, body),
    ))
    .await;
    match fault {
        Some(reason) => script_limit_response(&reason),
        None => response,
    }
}

/// Emit a collapse inner-hit member's snapshotted `_version` / `_seq_no` +
/// `_primary_term` into `hit_obj`, honouring the inner_hits `version` /
/// `seq_no_primary_term` flags.
///
/// When the snapshot value is ABSENT -- `Hit.seq_no`/`version` was `None` (a
/// concurrent tombstone or a version-map miss) and serialized as JSON `null` in
/// the collapse group -- the field is OMITTED, not fabricated. Elasticsearch
/// omits versioning it cannot resolve; the previous code fell through
/// `unwrap_or(i as u64)` / `unwrap_or(1)`, re-fabricating a *positional* `_seq_no`
/// (the exact #506 bug) and `_version = 1` -- values a client could feed back
/// into `if_seq_no` / `if_primary_term` and corrupt optimistic concurrency
/// (#566, residual of #506).
fn emit_inner_hit_versioning(
    member: &Value,
    emit_seq_no: bool,
    emit_version: bool,
    hit_obj: &mut serde_json::Map<String, Value>,
) {
    if emit_version {
        if let Some(v) = member.get("_version").and_then(Value::as_u64) {
            hit_obj.insert("_version".to_string(), json!(v));
        }
    }
    if emit_seq_no {
        if let Some(sn) = member.get("_seq_no").and_then(Value::as_u64) {
            hit_obj.insert("_seq_no".to_string(), json!(sn));
            hit_obj.insert("_primary_term".to_string(), json!(1));
        }
    }
}

/// #603: resolve a top-level / scroll hit's wire `(_version, _seq_no,
/// _primary_term)`, honouring the request's `version` / `seq_no_primary_term`
/// flags. A value is emitted ONLY when the engine actually resolved it: an
/// absent `seq_no`/`version` (a concurrent tombstone or version-map miss,
/// carried as `None` on the `Hit`) is OMITTED, never fabricated into a
/// positional hit index or a default `1` — values a client could replay into
/// `if_seq_no`/`if_primary_term` and corrupt optimistic concurrency. The
/// placeholder `_primary_term = 1` is emitted only alongside a real `_seq_no`.
/// This is the non-collapse twin of [`emit_inner_hit_versioning`] (#566).
fn resolve_hit_versioning(
    seq_no: Option<u64>,
    version: Option<u64>,
    emit_seq_no: bool,
    emit_version: bool,
) -> (Option<u64>, Option<u64>, Option<u64>) {
    let out_version = if emit_version { version } else { None };
    let (out_seq_no, out_primary_term) = match (emit_seq_no, seq_no) {
        (true, Some(sn)) => (Some(sn), Some(1u64)),
        _ => (None, None),
    };
    (out_version, out_seq_no, out_primary_term)
}

#[cfg(test)]
mod inner_hit_versioning_tests {
    use super::*;

    /// #566: an absent snapshot `_seq_no`/`_version` (JSON null — a concurrent
    /// tombstone or version-map miss) must be OMITTED from a collapse inner hit,
    /// never fabricated into a positional `_seq_no` or `_version = 1` a client
    /// could feed back into `if_seq_no`/`if_primary_term`.
    #[test]
    fn absent_snapshot_versioning_is_omitted_not_fabricated() {
        let member = json!({ "_id": "x", "_seq_no": null, "_version": null });
        let mut hit = serde_json::Map::new();
        emit_inner_hit_versioning(&member, true, true, &mut hit);
        assert!(
            !hit.contains_key("_seq_no"),
            "absent snapshot _seq_no must be omitted, not fabricated (#566)"
        );
        assert!(
            !hit.contains_key("_primary_term"),
            "no _primary_term without a real _seq_no (#566)"
        );
        assert!(
            !hit.contains_key("_version"),
            "absent snapshot _version must be omitted, not defaulted to 1 (#566)"
        );

        // A member with real snapshot values emits them verbatim.
        let real = json!({ "_id": "y", "_seq_no": 42, "_version": 7 });
        let mut hit2 = serde_json::Map::new();
        emit_inner_hit_versioning(&real, true, true, &mut hit2);
        assert_eq!(hit2.get("_seq_no"), Some(&json!(42)));
        assert_eq!(hit2.get("_primary_term"), Some(&json!(1)));
        assert_eq!(hit2.get("_version"), Some(&json!(7)));

        // The inner_hits flags gate emission.
        let mut hit3 = serde_json::Map::new();
        emit_inner_hit_versioning(&real, false, false, &mut hit3);
        assert!(hit3.is_empty(), "flags off => nothing emitted");
    }

    /// #603: the top-level and scroll hit render paths must honour the SAME
    /// omit-on-absent contract as the collapse inner_hit path — an absent
    /// `_seq_no`/`_version` is omitted, never a positional index or a
    /// default `1`, and `_primary_term` never appears without a real `_seq_no`.
    #[test]
    fn absent_top_level_versioning_is_omitted_not_fabricated() {
        // Both flags on, both values absent → everything omitted (the bug was
        // `(Some(1), Some(hit_idx), Some(1))` here).
        assert_eq!(
            resolve_hit_versioning(None, None, true, true),
            (None, None, None),
            "absent seq_no/version must be omitted, never positional/defaulted (#603)"
        );
        // Real values → emitted verbatim, with the placeholder primary_term.
        assert_eq!(
            resolve_hit_versioning(Some(42), Some(7), true, true),
            (Some(7), Some(42), Some(1))
        );
        // seq_no resolved but version absent (independent axes) → version omitted,
        // seq_no + primary_term emitted.
        assert_eq!(
            resolve_hit_versioning(Some(42), None, true, true),
            (None, Some(42), Some(1))
        );
        // version resolved but seq_no absent → version emitted, but NO
        // `_primary_term` without a real `_seq_no`.
        assert_eq!(
            resolve_hit_versioning(None, Some(7), true, true),
            (Some(7), None, None)
        );
        // Flags off → nothing emitted even when the engine resolved values.
        assert_eq!(
            resolve_hit_versioning(Some(42), Some(7), false, false),
            (None, None, None)
        );
    }
}

/// Render a collapse leader's `inner_hits` from the `__xy_collapse_group__`
/// / `__xy_collapse_spec__` sentinels `apply_collapse` planted in its
/// `_source`, honoring each spec's `size`/`from`/`sort`/`collapse`/`fields`
/// and the snapshot `_version`/`_seq_no` carried per member (never a
/// render-time live lookup — #506/#566). Shared by `search_impl` and the
/// scroll continuation (`scroll_page_response`) so a collapsed scroll renders
/// inner_hits identically instead of leaking the sentinels into `_source`
/// (#621).
fn render_collapse_inner_hits(
    group: Vec<Value>,
    spec: Value,
    idx_name: &str,
    rest_total_hits_as_int: bool,
    strip_companions: Option<&std::collections::HashSet<String>>,
) -> Value {
    let spec_list: Vec<Value> = match spec {
        Value::Array(a) => a,
        other => vec![other],
    };
    let mut combined = serde_json::Map::new();
    for spec in &spec_list {
        let name = spec
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or("inner_hits")
            .to_string();
        let size = spec.get("size").and_then(Value::as_u64).unwrap_or(3) as usize;
        let sort_spec = spec.get("sort").cloned().unwrap_or(Value::Null);
        let from_spec = spec.get("from").and_then(Value::as_u64).unwrap_or(0) as usize;
        let mut members = group.clone();
        if let Value::Array(sort_arr) = &sort_spec {
            for s in sort_arr.iter().rev() {
                if let Some(obj) = s.as_object() {
                    for (field, opts) in obj {
                        let desc = match opts {
                            Value::String(s) => s == "desc",
                            Value::Object(o) => o
                                .get("order")
                                .and_then(Value::as_str)
                                .map(|v| v == "desc")
                                .unwrap_or(false),
                            _ => false,
                        };
                        let f = field.clone();
                        // Compare numerically when both sides
                        // parse as numbers, else fall back to a
                        // lexicographic string compare so keyword
                        // and date fields sort correctly. Ties
                        // break on `_id` so the result is
                        // deterministic across runs and matches
                        // ES's `_doc` secondary sort for
                        // monotonically-assigned ids.
                        members.sort_by(|a, b| {
                            let av = a.get("_source").and_then(|s| s.get(&f));
                            let bv = b.get("_source").and_then(|s| s.get(&f));
                            let av_n = av.and_then(Value::as_f64);
                            let bv_n = bv.and_then(Value::as_f64);
                            let primary = match (av_n, bv_n) {
                                (Some(x), Some(y)) => {
                                    x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal)
                                }
                                _ => {
                                    let to_str = |v: Option<&Value>| match v {
                                        Some(Value::String(s)) => Some(s.clone()),
                                        Some(other) if !other.is_null() => Some(other.to_string()),
                                        _ => None,
                                    };
                                    let av_s = to_str(av);
                                    let bv_s = to_str(bv);
                                    match (av_s, bv_s) {
                                        (Some(x), Some(y)) => x.cmp(&y),
                                        (Some(_), None) => std::cmp::Ordering::Less,
                                        (None, Some(_)) => std::cmp::Ordering::Greater,
                                        (None, None) => std::cmp::Ordering::Equal,
                                    }
                                }
                            };
                            let primary = if desc { primary.reverse() } else { primary };
                            if primary != std::cmp::Ordering::Equal {
                                return primary;
                            }
                            let aid = a.get("_id").and_then(Value::as_str).unwrap_or("");
                            let bid = b.get("_id").and_then(Value::as_str).unwrap_or("");
                            aid.cmp(bid)
                        });
                    }
                }
            }
        }
        let emit_seq_no_ih = spec
            .get("seq_no_primary_term")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let emit_version_ih = spec
            .get("version")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        // `inner_hits.collapse.field` — second-level collapse
        // applied to the group members. ES counts `total` against
        // the pre-collapse member set but the returned `hits` are
        // deduped by the inner collapse field, preserving sort
        // order. (See ES 8.13 multi-level collapse.)
        let total = members.len();
        if let Some(inner_field) = spec
            .get("collapse")
            .and_then(|c| c.get("field"))
            .and_then(Value::as_str)
        {
            let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
            members.retain(|m| {
                let key = m
                    .get("_source")
                    .and_then(|s| s.get(inner_field))
                    .map(|v| match v {
                        Value::String(s) => s.clone(),
                        Value::Number(n) => n.to_string(),
                        Value::Bool(b) => b.to_string(),
                        Value::Null => "\0null".to_string(),
                        other => other.to_string(),
                    })
                    .unwrap_or_else(|| "\0missing".to_string());
                seen.insert(key)
            });
        }
        let rendered_hits: Vec<Value> = members
            .into_iter()
            .skip(from_spec)
            .take(size)
            .map(|mut m| {
                if let Some(src) = m.get_mut("_source").and_then(Value::as_object_mut) {
                    src.remove("__xy_collapse_group__");
                    src.remove("__xy_collapse_spec__");
                    // #646: a member's source is stashed BEFORE the engine's
                    // `_source` projection, so it still carries the passage
                    // sentinels (always internal) and, under the default
                    // projection, the generated embedding companions. Match the
                    // top-level hit rendering: strip the sentinels unconditionally
                    // and the companions when the caller passed the set.
                    src.retain(|k, _| {
                        !k.starts_with(xerj_query::executor::PASSAGE_METADATA_PREFIX)
                    });
                    if let Some(companions) = strip_companions {
                        src.retain(|k, _| !companions.contains(k));
                    }
                }
                let mut hit_obj = serde_json::Map::new();
                hit_obj.insert("_index".to_string(), Value::String(idx_name.to_string()));
                if let Some(id) = m.get("_id").cloned() {
                    hit_obj.insert("_id".to_string(), id);
                }
                if let Some(score) = m.get("_score").cloned() {
                    hit_obj.insert("_score".to_string(), score);
                }
                // Snapshotted `_version` / `_seq_no` carried in the
                // collapse group (#506) — NOT a render-time live
                // lookup, which could pair a live version with the
                // snapshot `_source` on a collapsed scroll. An absent
                // snapshot value is OMITTED, not fabricated (#566).
                emit_inner_hit_versioning(&m, emit_seq_no_ih, emit_version_ih, &mut hit_obj);
                if let Some(src) = m.get("_source").cloned() {
                    hit_obj.insert("_source".to_string(), src);
                }
                // inner_hits `fields` — emit the requested
                // source fields as a `fields: {name: [values]}`
                // map matching top-level hit semantics.
                let mut fmap = serde_json::Map::new();
                if let Some(ih_fields) = spec.get("fields").and_then(Value::as_array) {
                    for f in ih_fields {
                        let fname = match f {
                            Value::String(s) => s.as_str(),
                            Value::Object(o) => {
                                o.get("field").and_then(Value::as_str).unwrap_or("")
                            }
                            _ => continue,
                        };
                        if fname.is_empty() {
                            continue;
                        }
                        if let Some(src) = m.get("_source") {
                            if let Some(v) = src.get(fname).cloned() {
                                let wrapped = match v {
                                    Value::Array(a) => Value::Array(a),
                                    Value::Null => continue,
                                    other => Value::Array(vec![other]),
                                };
                                fmap.insert(fname.to_string(), wrapped);
                            }
                        }
                    }
                }
                // ES auto-emits the inner-collapse field into
                // `fields` even without an explicit `fields`
                // clause, mirroring the top-level collapse
                // behavior (see line ~7070).
                if let Some(inner_field) = spec
                    .get("collapse")
                    .and_then(|c| c.get("field"))
                    .and_then(Value::as_str)
                {
                    if !fmap.contains_key(inner_field) {
                        if let Some(v) = m.get("_source").and_then(|s| s.get(inner_field)).cloned()
                        {
                            let wrapped = match v {
                                Value::Array(a) => Value::Array(a),
                                Value::Null => Value::Array(vec![]),
                                other => Value::Array(vec![other]),
                            };
                            if !matches!(&wrapped, Value::Array(a) if a.is_empty()) {
                                fmap.insert(inner_field.to_string(), wrapped);
                            }
                        }
                    }
                }
                if !fmap.is_empty() {
                    hit_obj.insert("fields".to_string(), Value::Object(fmap));
                }
                Value::Object(hit_obj)
            })
            .collect();
        // When the caller set `rest_total_hits_as_int: true`
        // on the outer request, inner_hits totals become
        // bare numbers — mirror the top-level hits.total
        // shape.
        let inner_total = if rest_total_hits_as_int {
            json!(total as u64)
        } else {
            json!({ "value": total as u64, "relation": "eq" })
        };
        combined.insert(
            name,
            serde_json::json!({
                "hits": {
                    "total": inner_total,
                    "max_score": Value::Null,
                    "hits": rendered_hits,
                }
            }),
        );
    }
    Value::Object(combined)
}

/// Whether the index mapping sets `_source.enabled: false`. ES suppresses
/// `_source` in the response for such an index; xerj keeps the underlying
/// source available internally (fields/highlight/_ignored extraction) and makes
/// the suppression a response-time decision. Extracted from `search_impl`'s
/// per-hit render so the scroll continuation (`scroll_page_response`) can apply
/// the SAME per-hit decision from each hit's own index — mapping suppression is
/// NOT a snapshot constant, because a scroll can span indices with divergent
/// `_source` settings (#637).
fn mapping_source_disabled(state: &AppState, index: &str) -> bool {
    state
        .engine
        .index_mappings
        .get(index)
        .and_then(|m| {
            m.get("mappings")
                .and_then(|mm| mm.get("_source"))
                .or_else(|| m.get("_source"))
                .cloned()
        })
        .and_then(|src| src.get("enabled").and_then(Value::as_bool))
        .map(|b| !b)
        .unwrap_or(false)
}

/// Who a search served: `"machine"` or `"user"` (#1109). Decided by the
/// server from what the request itself IS, so no client input can mark its
/// own traffic machine and dodge the `xerj gain` user hit-rate stat:
///
/// * `size == 0` — a counting probe. It asks for no hits back; the canonical
///   issuer is autoindex's verification step, which reads back exact group
///   counts that way (#1105). A human looking for documents always wants
///   hits, and the ES-YAML suite's `size: 0` aggregation requests are tool
///   traffic by the same definition.
/// * the target is the autoindex catalog — a maintenance index no person
///   searches; every query against it comes from `xerj autoindex`'s sweeps
///   (`xerj gain` itself reads it the same way).
///
/// Everything a client CAN set — headers, principal, query body apart from
/// these two semantics — is deliberately not consulted. The spoofable
/// `X-Xerj-Internal` header proposal was rejected during #1107 and this is
/// the replacement: classification from request shape, not request claim.
/// A superuser running `size: 10` against a data index is classified user,
/// because that is what the request is.
fn search_actor_class(size: usize, index: &str) -> &'static str {
    if size == 0 || index == xerj_common::AUTOINDEX_CATALOG_INDEX {
        "machine"
    } else {
        "user"
    }
}

/// How a search the node issues to ITSELF differs from one that arrived over
/// HTTP. Only [`crate::hub_api`]'s in-process caller sets it, around the one
/// internal request it makes; a request off the wire cannot carry it, because it
/// is a task-local and not a header, a parameter or a body field.
///
/// Both effects exist because the hosted hub's routes are public and a pack's
/// contents are not the operator's: neither may be a lever on the node.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct InProcessSearch {
    /// Do not append this search to the audit ring. The ring is a bounded piece
    /// of operator evidence shared by the whole node (4,096 entries); a public
    /// route that appended one entry per request would let a crowd of strangers
    /// age every earlier entry out of it. The HTTP access log still records the
    /// request.
    pub skip_audit: bool,
    /// A fan-out over several indices skips an index whose search fails — it
    /// is counted in `_shards.failed` and logged — instead of failing the whole
    /// request. One pack with an unusable mapping must not take `search` down
    /// for every other pack. When EVERY index fails the first failure is still
    /// returned, so an outage never reads as "no results".
    pub skip_failed_indices: bool,
}

tokio::task_local! {
    static IN_PROCESS_SEARCH: InProcessSearch;
}

/// Run `fut` — the whole internal request, handler included — with `mode`
/// installed. Same shape as `xerj_engine::index_guard::scoped`, and for the same
/// reason: the handler reads it on the task that drives `fut`.
pub(crate) async fn scoped_in_process_search<F>(mode: InProcessSearch, fut: F) -> F::Output
where
    F: std::future::Future,
{
    IN_PROCESS_SEARCH.scope(mode, fut).await
}

/// The mode the current request runs under; the default (a request off the
/// wire, or engine-internal work) changes nothing.
fn in_process_search() -> InProcessSearch {
    IN_PROCESS_SEARCH.try_with(|m| *m).unwrap_or_default()
}

/// Bookkeeping for [`InProcessSearch::skip_failed_indices`]: how many indices a
/// fan-out tried, how many failed, and the first failure to report if all did.
#[derive(Default)]
struct SkippedIndices {
    searched: u32,
    failed: u32,
    first_failure: Option<Response>,
}

impl SkippedIndices {
    /// One more index was attempted.
    fn attempt(&mut self) {
        self.searched += 1;
    }

    /// An attempted index failed with `why`; keep the first such response.
    fn skip(&mut self, why: impl FnOnce() -> Response) {
        self.failed += 1;
        if self.first_failure.is_none() {
            self.first_failure = Some(why());
        }
    }

    /// The failure to answer with when nothing at all could be searched.
    fn all_failed(self) -> Option<Response> {
        if self.failed > 0 && self.failed == self.searched {
            self.first_failure
        } else {
            None
        }
    }
}

/// #2305: indices a wildcard, `_all`/`*`, or alias expansion included that
/// have no `semantic_text` field for the queried name. They cannot answer
/// and must not 400 the indices that can. An explicitly named index is not
/// recorded here (#530 still fails that request).
#[derive(Default)]
struct ExpandedSemanticSkips {
    attempted: u32,
    skipped: u32,
    first_reason: Option<String>,
    failures: Vec<Value>,
}

impl ExpandedSemanticSkips {
    fn note_attempt(&mut self) {
        self.attempted += 1;
    }

    /// `Ok(())` — `index_name` was expanded and lacks the field; the miss is
    /// recorded and the caller continues. `Err(err)` — the caller must fail
    /// the request with `err` (explicit index, or a different error).
    fn take_skippable(
        &mut self,
        selector: &str,
        index_name: &str,
        node: &str,
        err: xerj_common::XerjError,
    ) -> Result<(), xerj_common::XerjError> {
        let Some(reason) = absent_semantic_field_reason(&err) else {
            return Err(err);
        };
        if selector_names_index_explicitly(selector, index_name) {
            return Err(err);
        }
        let reason = reason.to_string();
        tracing::warn!(
            index = %index_name,
            error = %reason.chars().take(300).collect::<String>(),
            "semantic search: expanded index has no semantic_text field; skipping it"
        );
        self.failures
            .push(semantic_field_shard_failure(index_name, node, &reason));
        self.skipped += 1;
        if self.first_reason.is_none() {
            self.first_reason = Some(reason);
        }
        Ok(())
    }

    /// When every index that was searched lacked the field, there is nothing
    /// to answer from. A wrong field name on a wildcard must stay a 400
    /// rather than an empty 200.
    fn failure_if_every_index_skipped(&self) -> Option<xerj_common::XerjError> {
        if self.attempted > 0 && self.skipped == self.attempted {
            self.first_reason
                .clone()
                .map(xerj_common::XerjError::invalid_query)
        } else {
            None
        }
    }
}

/// The engine's refusal for a `semantic` query against a field that is not
/// `semantic_text` (lexical embedder, no comparable stored vector). The
/// clause is the contract the coordinator matches; the rest of the sentence
/// is the operator hint and may be reworded.
fn absent_semantic_field_reason(err: &xerj_common::XerjError) -> Option<&str> {
    match err {
        xerj_common::XerjError::InvalidQuery { reason }
            if reason.contains("it is not a `semantic_text` field") =>
        {
            Some(reason.as_str())
        }
        _ => None,
    }
}

/// True when `index_name` is a concrete token of `selector` (comma-separated,
/// date math already resolved the way the search path resolves it). A
/// wildcard, `_all`/`*`, or an alias token is not the concrete index name, so
/// members reached only through that expansion are not explicitly named.
fn selector_names_index_explicitly(selector: &str, index_name: &str) -> bool {
    selector.split(',').any(|token| {
        let token = resolve_date_math_index(token.trim());
        token == index_name
    })
}

fn semantic_field_shard_failure(index: &str, node: &str, reason: &str) -> Value {
    json!({
        "shard": 0,
        "index": index,
        "node": node,
        "reason": {
            "type": "illegal_argument_exception",
            "reason": reason
        }
    })
}

#[cfg(test)]
mod expanded_semantic_selector_tests {
    use super::selector_names_index_explicitly;

    #[test]
    fn a_concrete_token_is_explicit_and_a_pattern_is_not() {
        assert!(selector_names_index_explicitly("proj-notes", "proj-notes"));
        assert!(selector_names_index_explicitly(
            "proj-notes,proj-tags",
            "proj-tags"
        ));
        assert!(!selector_names_index_explicitly("proj-*", "proj-notes"));
        assert!(!selector_names_index_explicitly("proj-*", "proj-tags"));
        assert!(!selector_names_index_explicitly("_all", "proj-notes"));
        assert!(!selector_names_index_explicitly("*", "proj-notes"));
        // An alias token is not the concrete member name.
        assert!(!selector_names_index_explicitly("proj", "proj-notes"));
        // A concrete name beside a pattern is still explicit.
        assert!(selector_names_index_explicitly(
            "proj-*,proj-tags",
            "proj-tags"
        ));
        assert!(!selector_names_index_explicitly(
            "proj-*,proj-tags",
            "proj-notes"
        ));
    }
}

async fn search_dispatch(
    state: AppState,
    index: String,
    params: EsSearchQueryParams,
    principal: crate::auth::Principal,
    body: EsSearchJson,
) -> Response {
    // #2400: `post_filter` narrows the hits, never the aggregations.
    if let Some(split) = split_post_filter(&params, &body) {
        return search_with_post_filter(state, index, params, principal, split).await;
    }
    search_routed(state, index, params, principal, body).await
}

/// One search through the cluster fan-out when it applies, else on this node.
async fn search_routed(
    state: AppState,
    index: String,
    params: EsSearchQueryParams,
    principal: crate::auth::Principal,
    body: EsSearchJson,
) -> Response {
    if let Some(response) =
        crate::cluster_shard::fanout_search(&state, &index, &params, &principal, &body).await
    {
        return response;
    }
    search_impl(state, index, params, principal, body).await
}

/// The searches a request with `post_filter` becomes (#2400). Elasticsearch
/// applies `post_filter` to the hits after the aggregations are computed, so
/// a faceted UI can show a facet's other values while one is selected.
///
/// - `hits`: the query wrapped as `bool{must: [query], filter: [post_filter]}`,
///   without aggregations. A filter clause does not score, so the hits, their
///   scores and `hits.total` are what Elasticsearch returns.
/// - `aggs`: when the request aggregates, the original request without
///   `post_filter` and with `size: 0`, so the aggregations are exactly what
///   they were before.
struct PostFilterSplit {
    hits: EsSearchBody,
    aggs: Option<(EsSearchQueryParams, EsSearchBody)>,
}

/// `None` leaves the request as it is: no `post_filter`; a hybrid query, which
/// `build_search_request` rejects beside `post_filter` (#943); or a `?q=`
/// query, which replaces the body query this wraps.
fn split_post_filter(params: &EsSearchQueryParams, body: &EsSearchJson) -> Option<PostFilterSplit> {
    let original = body.0.as_ref()?;
    let filter = original.post_filter.clone()?;
    if params.q.is_some() {
        return None;
    }
    let query = original
        .query
        .clone()
        .unwrap_or_else(|| json!({ "match_all": {} }));
    let hybrid = parse_request(&json!({ "query": query }))
        .map(|req| req.query.contains_hybrid())
        .unwrap_or(false);
    if hybrid {
        return None;
    }

    let mut hits = original.clone();
    hits.post_filter = None;
    hits.query = Some(json!({ "bool": { "must": [query], "filter": [filter] } }));
    let had_aggs = hits.aggs.take().is_some();
    let had_aggregations = hits.aggregations.take().is_some();

    let aggs = (had_aggs || had_aggregations).then(|| {
        let mut body = original.clone();
        body.post_filter = None;
        body.size = 0;
        body.from = 0;
        let mut params = params.clone();
        // Query-string paging overrides the body, and a second scroll context
        // would leak: this search only reads the aggregations.
        params.size = Some("0".to_string());
        params.from = None;
        params.scroll = None;
        (params, body)
    });
    Some(PostFilterSplit { hits, aggs })
}

/// Run the split searches and answer with the hits of one and the
/// aggregations of the other. An error from either is returned as it is.
async fn search_with_post_filter(
    state: AppState,
    index: String,
    params: EsSearchQueryParams,
    principal: crate::auth::Principal,
    split: PostFilterSplit,
) -> Response {
    let hits_search = search_routed(
        state.clone(),
        index.clone(),
        params,
        principal.clone(),
        EsSearchJson(Some(split.hits)),
    );
    let Some((aggs_params, aggs_body)) = split.aggs else {
        return hits_search.await;
    };
    let aggs_search = search_routed(
        state,
        index,
        aggs_params,
        principal,
        EsSearchJson(Some(aggs_body)),
    );
    let (hits_response, aggs_response) = tokio::join!(Box::pin(hits_search), Box::pin(aggs_search));
    if !hits_response.status().is_success() {
        return hits_response;
    }
    if !aggs_response.status().is_success() {
        return aggs_response;
    }

    let (mut parts, hits_body) = hits_response.into_parts();
    let read = |body: axum::body::Body| async move {
        axum::body::to_bytes(body, usize::MAX)
            .await
            .ok()
            .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
    };
    let (Some(mut merged), Some(aggs_value)) =
        (read(hits_body).await, read(aggs_response.into_body()).await)
    else {
        return ApiError::new(xerj_common::XerjError::internal(
            "post_filter: could not read the search responses to merge them",
        ))
        .into_response();
    };
    if let (Some(obj), Some(aggregations)) =
        (merged.as_object_mut(), aggs_value.get("aggregations"))
    {
        obj.insert("aggregations".to_string(), aggregations.clone());
    }
    parts.headers.remove(axum::http::header::CONTENT_LENGTH);
    Response::from_parts(parts, axum::body::Body::from(merged.to_string()))
}

#[cfg(test)]
mod post_filter_split_tests {
    use super::*;

    fn body(v: Value) -> EsSearchJson {
        EsSearchJson(Some(serde_json::from_value(v).expect("search body")))
    }

    #[test]
    fn no_post_filter_is_left_alone() {
        let params = EsSearchQueryParams::default();
        assert!(split_post_filter(&params, &body(json!({"query": {"match_all": {}}}))).is_none());
        assert!(split_post_filter(&params, &EsSearchJson(None)).is_none());
    }

    #[test]
    fn hits_search_wraps_the_query_and_drops_aggregations() {
        let params = EsSearchQueryParams::default();
        let split = split_post_filter(
            &params,
            &body(json!({
                "query": {"match": {"body": "alpha"}},
                "post_filter": {"term": {"provenance": "draft"}},
            })),
        )
        .expect("split");
        assert_eq!(
            split.hits.query,
            Some(json!({"bool": {
                "must": [{"match": {"body": "alpha"}}],
                "filter": [{"term": {"provenance": "draft"}}],
            }}))
        );
        assert!(split.hits.post_filter.is_none());
        assert!(split.aggs.is_none(), "no aggregations, no second search");
    }

    #[test]
    fn a_missing_query_is_match_all() {
        let split = split_post_filter(
            &EsSearchQueryParams::default(),
            &body(json!({"post_filter": {"term": {"provenance": "draft"}}})),
        )
        .expect("split");
        assert_eq!(
            split.hits.query.unwrap()["bool"]["must"][0],
            json!({"match_all": {}})
        );
    }

    #[test]
    fn aggregations_come_from_the_unfiltered_request_with_no_hits_and_no_scroll() {
        let params = EsSearchQueryParams {
            size: Some("25".into()),
            from: Some("5".into()),
            scroll: Some("1m".into()),
            ..Default::default()
        };
        let split = split_post_filter(
            &params,
            &body(json!({
                "query": {"match_all": {}},
                "size": 25,
                "post_filter": {"term": {"provenance": "draft"}},
                "aggs": {"p": {"terms": {"field": "provenance"}}},
            })),
        )
        .expect("split");
        assert!(split.hits.aggs.is_none() && split.hits.aggregations.is_none());
        let (aggs_params, aggs_body) = split.aggs.expect("an aggregation search");
        assert!(aggs_body.post_filter.is_none());
        assert_eq!(aggs_body.query, Some(json!({"match_all": {}})));
        assert_eq!((aggs_body.size, aggs_body.from), (0, 0));
        assert!(aggs_body.aggs.is_some());
        assert_eq!(aggs_params.size.as_deref(), Some("0"));
        assert!(aggs_params.from.is_none() && aggs_params.scroll.is_none());
    }

    #[test]
    fn hybrid_and_query_string_requests_are_not_split() {
        let hybrid = body(json!({
            "query": {"hybrid": {"queries": [
                {"query": {"match": {"body": "alpha"}}},
                {"query": {"match": {"body": "beta"}}},
            ]}},
            "post_filter": {"term": {"provenance": "draft"}},
        }));
        assert!(split_post_filter(&EsSearchQueryParams::default(), &hybrid).is_none());
        let q_param = EsSearchQueryParams {
            q: Some("body:alpha".into()),
            ..Default::default()
        };
        let with_filter = body(json!({"post_filter": {"term": {"provenance": "draft"}}}));
        assert!(split_post_filter(&q_param, &with_filter).is_none());
    }
}

/// One shard's search, used by the cluster fan-out. Does not fan out again.
///
/// `Box::pin` keeps this future pointer-sized. `search_impl`'s state is
/// enormous, and a fan-out that awaited it by value would embed a second
/// copy inside the coordinator's already-boxed search future.
pub(crate) async fn search_shard_local(
    state: AppState,
    index: String,
    params: EsSearchQueryParams,
    principal: crate::auth::Principal,
    body: EsSearchBody,
) -> Response {
    Box::pin(search_impl(
        state,
        index,
        params,
        principal,
        EsSearchJson(Some(body)),
    ))
    .await
}

/// Heap-allocate the publish future before it is polled.
///
/// `publish_memtables_if_budget_engaged` awaits `Index::flush`. That future
/// is large enough that building it inside `search_impl` overflows the worker
/// stack (#2321). A sync function creates it here, on the task that is about
/// to poll it, and only the box escapes.
#[inline(never)]
fn boxed_memtable_publish(
    engine: std::sync::Arc<xerj_engine::Engine>,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = usize> + Send>> {
    Box::pin(async move { engine.publish_memtables_if_budget_engaged().await })
}

/// Publish memtables that are holding the process budget, on a fresh task.
///
/// A no-op — and no spawn — when the memtable breaker is off, so an ordinary
/// search does not flush. The spawn keeps `Index::flush`'s frame off
/// `search_impl`'s stack.
async fn publish_engaged_memtables(engine: std::sync::Arc<xerj_engine::Engine>) {
    if !xerj_engine::governor::global().is_some_and(|governor| governor.memtable_breaker_engaged())
    {
        return;
    }
    let _ = tokio::spawn(async move {
        let _published = boxed_memtable_publish(engine).await;
    })
    .await;
}

async fn search_impl(
    state: AppState,
    index: String,
    params: EsSearchQueryParams,
    principal: crate::auth::Principal,
    body: EsSearchJson,
) -> Response {
    let started = Instant::now();
    // Read once, before the first `.await`: what the in-process hub caller asked
    // of this search. A request off the wire gets the default and is unaffected.
    let in_process = in_process_search();
    // #2321: a memtable sitting on the process budget is what a `{prefix}-*`
    // search scans. Publish it before this request walks it. No-op unless
    // that breaker is engaged. Read `in_process` first — it is task-local.
    publish_engaged_memtables(std::sync::Arc::clone(&state.engine)).await;
    // Closed-index handling is deferred to after index resolution below so
    // `ignore_unavailable` / `expand_wildcards` are honored per ES semantics.

    // Strict: empty body → defaults (ES match-all). Malformed body → 400
    // via OptionalJsonRejection, NOT a silent fallback to match-all that
    // hides the real problem from the caller. (See `extract::OptionalJson`
    // module docs for the silent-drop pitfall this closes.)
    let mut body = body.into_or_default();

    // URL-level `?explain=true` (ES accepts the flag either as a
    // URL parameter or a body field). Merge into the body so the
    // downstream search-request builder sees it uniformly.
    if !body.explain {
        body.explain = params
            .explain
            .as_deref()
            .map(|v| v == "true" || v == "1")
            .unwrap_or(false);
    }

    // ES forbids asking for internal meta-fields via the `fields`
    // parameter (they're not stored as doc values; there's a separate
    // fetch sub-phase for each). Reject up front with the ES-standard
    // 400 illegal_argument_exception per field.
    if let Some(Value::Array(arr)) = &body.fields {
        for entry in arr {
            let name = match entry {
                Value::String(s) => s.as_str(),
                Value::Object(o) => o.get("field").and_then(Value::as_str).unwrap_or(""),
                _ => continue,
            };
            if matches!(
                name,
                "_seq_no"
                    | "_source"
                    | "_feature"
                    | "_nested_path"
                    | "_field_names"
                    | "_version"
                    | "_routing"
                    | "_id"
                    | "_ignored"
                    | "_type"
                    | "_parent"
                    | "_index"
                    | "_primary_term"
            ) {
                // ES allows fetching metadata fields with real doc_values
                // (_id, _index, _version, _ignored, _routing). _seq_no,
                // _primary_term, _source, _field_names, _feature,
                // _nested_path, _type, _parent are NOT fetchable — ES
                // returns illegal_argument_exception 400 for those.
                if matches!(
                    name,
                    "_id" | "_index" | "_version" | "_ignored" | "_routing"
                ) {
                    continue;
                }
                let reason = format!(
                    "error fetching [{}]: Cannot fetch values for internal field [{}].",
                    name, name
                );
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "root_cause": [{
                                "type": "illegal_argument_exception",
                                "reason": reason,
                            }],
                            "type": "illegal_argument_exception",
                            "reason": reason,
                        },
                        "status": 400,
                    })),
                )
                    .into_response();
            }
        }
    }

    // ── Merge GET query params into body ─────────────────────────────────────
    // `?q=foo` overrides the query body. `df`, `default_operator` and
    // `analyzer` attach to the synthesized `query_string`.
    if let Some(ref q) = params.q {
        let mut qs = serde_json::Map::new();
        qs.insert("query".to_string(), Value::String(q.clone()));
        if let Some(ref df) = params.df {
            qs.insert("default_field".to_string(), Value::String(df.clone()));
        }
        if let Some(ref op) = params.default_operator {
            qs.insert("default_operator".to_string(), Value::String(op.clone()));
        }
        if let Some(ref an) = params.analyzer {
            qs.insert("analyzer".to_string(), Value::String(an.clone()));
        }
        body.query = Some(json!({ "query_string": qs }));
    }
    // Parse `?size=` / `?from=` here (not at the axum `Query` layer) so a
    // non-numeric value yields ES's JSON `illegal_argument_exception` rather
    // than axum's `text/plain` 400 (item 4d).
    if let Some(ref size_s) = params.size {
        match size_s.parse::<usize>() {
            Ok(n) => body.size = n,
            Err(_) => return int_param_parse_error("size", size_s),
        }
    }
    if let Some(ref from_s) = params.from {
        match from_s.parse::<usize>() {
            Ok(n) => body.from = n,
            Err(_) => match from_s.parse::<i64>() {
                Ok(n) if n < 0 => return negative_from_error(n),
                _ => return int_param_parse_error("from", from_s),
            },
        }
    }
    // URL-level `seq_no_primary_term=true` / `version=true` promote the
    // corresponding body flag when the caller didn't already set one.
    if body.seq_no_primary_term.is_none() {
        if let Some(v) = params.seq_no_primary_term.as_deref() {
            if v == "true" || v == "1" {
                body.seq_no_primary_term = Some(true);
            }
        }
    }
    if body.version.is_none() {
        if let Some(v) = params.version.as_deref() {
            if v == "true" || v == "1" {
                body.version = Some(true);
            }
        }
    }
    // `?timeout=100ms` → promote to body (body wins when both set) so
    // build_search_request arms the cooperative deadline (RC4 blocker 12).
    if body.timeout.is_none() {
        body.timeout = params.timeout.clone();
    }
    // ── Scroll support ──────────────────────────────────────────────────────
    // If `?scroll=1m` is present, snapshot all matching hits into a scroll
    // context and return the first page + `_scroll_id`. Subsequent pages
    // come through `POST /_search/scroll`.
    //
    // Remember the caller-requested page size before we bump body.size to
    // capture every matching hit; we'll truncate the response hits back to
    // this size after building the response.
    let is_scroll_request = params.scroll.is_some();
    let scroll_page_size = body.size;
    // The caller's `from`, before the scroll snapshot below rewrites it; the
    // per-index window checks (`find_index_request_limit_violation`) need it.
    let requested_from = body.from;
    if is_scroll_request {
        // RC4 blocker 11: enforce the open-scroll cap BEFORE running the
        // search — each context pins a fully-hydrated Vec<Hit>, so an
        // uncapped open loop is an unauthenticated memory DoS. Expired
        // contexts are swept opportunistically first so the cap counts
        // only live contexts.
        state.engine.sweep_expired_scrolls();
        let scroll_cap = state.config.search_context.max_open_scrolls;
        if state.engine.scrolls.len() >= scroll_cap {
            return too_many_scroll_contexts(scroll_cap);
        }
        // Cap scroll snapshot at 10k hits — matches the default max_result_window.
        body.size = SCROLL_SNAPSHOT_MAX_HITS;
        body.from = 0;
        // Scroll totals must be EXACT: the truncation check at context-
        // registration time (issue #198) compares the exact total against
        // the snapshot cap, and ES itself refuses anything less in a scroll
        // context ("disabling [track_total_hits] is not allowed in a scroll
        // context" — SearchSourceBuilder validation). Forcing `true` here
        // overrides a body-level `false`/limit, and the URL-param merge
        // below only fills in when the body value is None, so it cannot
        // undo this.
        body.track_total_hits = Some(Value::Bool(true));
    }
    // `?sort=field:order` → convert to sort array.
    if let Some(ref sort_str) = params.sort {
        if body.sort.is_none() {
            let sort_val = parse_sort_param(sort_str);
            body.sort = Some(sort_val);
        }
    }

    // Reject the search-body semantic combinations ES rejects at query-build
    // time (items 4b + 4c): search_after without/against the wrong sort arity,
    // and rescore alongside a non-relevance sort. Silently ignored before this
    // (200 with wrong results); now the ES-shaped 400. Placed after the URL
    // `?sort=` merge so a URL-provided sort counts toward the arity/field rules
    // exactly as ES does (URL sort + body search_after is valid; URL sort +
    // body rescore is rejected — both live-verified).
    if let Some(err) = validate_search_after_rescore(&body) {
        return err;
    }

    // `?_source=field1,field2`
    if let Some(ref src_str) = params.source {
        if body.source.is_none() {
            let fields: Vec<Value> = src_str
                .split(',')
                .map(|s| Value::String(s.trim().to_string()))
                .collect();
            body.source = Some(Value::Array(fields));
        }
    }
    // `?track_total_hits=false` / `true` / integer
    if let Some(ref tth_str) = params.track_total_hits {
        if body.track_total_hits.is_none() {
            body.track_total_hits = Some(match tth_str.as_str() {
                "false" => Value::Bool(false),
                "true" => Value::Bool(true),
                other => other
                    .parse::<u64>()
                    .map(|n| json!(n))
                    .unwrap_or(Value::Bool(true)),
            });
        }
    }
    // ES 8.x default: when `track_total_hits` is absent, totals are only
    // tracked accurately up to 10,000 — beyond that the response reports
    // {"value": 10000, "relation": "gte"}. Scroll requests are exempt:
    // ES keeps scroll totals exact (scroll/10_basic.yml asserts relation
    // "eq" without setting track_total_hits).
    if body.track_total_hits.is_none() && !is_scroll_request {
        body.track_total_hits = Some(json!(10_000));
    }
    // `?_source_includes=f1,f2` and `?_source_excludes=f3` — query-param
    // source filter. ES resolves these to take precedence over any body-
    // level `_source` value (see test search/10_source_filtering.yml
    // "_source_includes and _source in body" which passes both and expects
    // the URL-param includes to win).
    // `?stored_fields=f1,f2` → promote to body if body lacks stored_fields.
    if body.stored_fields.is_none() {
        if let Some(ref csv) = params.stored_fields {
            let arr: Vec<Value> = csv
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(|s| Value::String(s.to_string()))
                .collect();
            if !arr.is_empty() {
                body.stored_fields = Some(Value::Array(arr));
            }
        }
    }
    // `?docvalue_fields=f1,f2` → promote to body if body lacks docvalue_fields.
    if body.docvalue_fields.is_none() {
        if let Some(ref csv) = params.docvalue_fields {
            let arr: Vec<Value> = csv
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(|s| Value::String(s.to_string()))
                .collect();
            if !arr.is_empty() {
                body.docvalue_fields = Some(Value::Array(arr));
            }
        }
    }
    // `?fields=f1,f2` → promote to body if body lacks fields.
    if body.fields.is_none() {
        if let Some(ref csv) = params.fields {
            let arr: Vec<Value> = csv
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .map(|s| Value::String(s.to_string()))
                .collect();
            if !arr.is_empty() {
                body.fields = Some(Value::Array(arr));
            }
        }
    }
    if params.source_includes.is_some() || params.source_excludes.is_some() {
        let includes: Vec<String> = params
            .source_includes
            .as_deref()
            .unwrap_or("")
            .split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(String::from)
            .collect();
        let excludes: Vec<String> = params
            .source_excludes
            .as_deref()
            .unwrap_or("")
            .split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(String::from)
            .collect();
        body.source = Some(json!({
            "includes": includes,
            "excludes": excludes
        }));
    }

    // Validate `rerank` and widen the page to its window *before* the search
    // runs; the stage itself runs on the rendered hits further down. Placed
    // after every URL parameter has been merged into `body` — `?sort=`,
    // `?_source=false`, `?_source_excludes=`, `?size=`, `?from=` are all things
    // the stage refuses or pages by, and a check that ran before the merge let
    // the URL spelling of each one straight through.
    let rerank_plan = match crate::rerank_stage::RerankPlan::prepare(&mut body, is_scroll_request) {
        Ok(plan) => plan,
        Err(reason) => {
            crate::rerank_stage::record_refused(&state.metrics);
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": {
                        "root_cause": [{
                            "type": "illegal_argument_exception",
                            "reason": reason,
                        }],
                        "type": "illegal_argument_exception",
                        "reason": reason,
                    },
                    "status": 400,
                })),
            )
                .into_response();
        }
    };

    // Validate the `judge` block under the same discipline, before the search
    // runs: a request whose judge block is unsatisfiable should not pay for
    // the search that cannot be judged. Runs AFTER `rerank`'s prepare because
    // that is the one stage allowed to widen the page; the judge judges the
    // page as emitted and needs no widening of its own.
    let judge_plan = match crate::judge_stage::JudgePlan::prepare(&mut body, is_scroll_request) {
        Ok(plan) => plan,
        Err(reason) => {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": {
                        "root_cause": [{
                            "type": "illegal_argument_exception",
                            "reason": reason,
                        }],
                        "type": "illegal_argument_exception",
                        "reason": reason,
                    },
                    "status": 400,
                })),
            )
                .into_response();
        }
    };

    // `?typed_keys` — prefix agg names with their type in the response.
    let typed_keys = params.typed_keys.is_some();

    // RC4 W4 item 2: bracket the live-search gauge for this request. The guard
    // increments `active_searches` now and decrements on drop (any return path
    // below), so `/metrics` reflects real in-flight search concurrency.
    // `queries_by_index` is recorded per resolved index in the loop below;
    // `queries_executed` + the latency histograms via `record_query_global` at
    // completion.
    let _search_guard = state.metrics.active_search_guard();

    // Support comma-separated multi-index with wildcard patterns:
    // /index1,index2/_search   — comma-separated exact names
    // /log-*/_search           — wildcard pattern (fnmatch-style)
    // /_all/_search            — all indices
    // Resolve date math in each index name: <log-{now/d}> → log-2026.04.11
    let resolved_names_owned: Vec<String> = index
        .split(',')
        .map(|n| resolve_date_math_index(n.trim()))
        .collect();
    let raw_names: Vec<&str> = resolved_names_owned.iter().map(|s| s.as_str()).collect();
    // An ALIAS also needs resolving, and used not to be counted here — which is
    // why a multi-index alias behaved as an alias over one member on every read
    // path (#433). `_count` and plain `_search` truncated the same way: three
    // indices of 40 documents behind one alias answered 40, from the first
    // member, with no error and a `_count` that agreed with the short result.
    // The `_index`-stamping problem reported alongside it is downstream of this
    // — the hits could not carry the right index because the other indices were
    // never searched.
    let needs_resolve = raw_names
        .iter()
        .any(|n| *n == "_all" || n.contains('*') || state.engine.aliases.contains_key(*n));
    let index_names: Vec<String> = if needs_resolve {
        let all_names = state.engine.index_name_list();
        let mut resolved: Vec<String> = Vec::new();
        for pattern in &raw_names {
            if *pattern == "_all" || *pattern == "*" {
                for name in &all_names {
                    if !resolved.contains(name) {
                        resolved.push(name.clone());
                    }
                }
            } else if pattern.contains('*') {
                for name in &all_names {
                    if glob_match_simple(pattern, name) && !resolved.contains(name) {
                        resolved.push(name.clone());
                    }
                }
            } else if let Some(targets) = state.engine.aliases.get(*pattern) {
                // Expand to the concrete members, exactly as
                // `resolve_index_selector` already does for every other
                // endpoint. An alias naming one index resolves to that one, so
                // the single-member case is unchanged.
                for name in targets.value() {
                    if !resolved.contains(name) {
                        resolved.push(name.clone());
                    }
                }
            } else {
                let s = pattern.to_string();
                if !resolved.contains(&s) {
                    resolved.push(s);
                }
            }
        }
        resolved
    } else {
        raw_names.iter().map(|s| s.to_string()).collect()
    };
    // Point-in-time override: when `body.pit.id` is set, fetch the
    // recorded indices from the PIT snapshot. The path-level `index`
    // for PIT searches is typically `_search` (no index in the URL);
    // the PIT context provides the real index list.
    let pit_context: Option<xerj_engine::engine::PitContext> = body
        .pit
        .as_ref()
        .and_then(|p| p.get("id").and_then(Value::as_str))
        .and_then(|id| state.engine.pits.get(id).map(|r| r.value().clone()));
    let index_names: Vec<String> = if let Some(pit) = pit_context.as_ref() {
        pit.indices.clone()
    } else {
        index_names
    };

    // `match: {_index: pattern}` / `term: {_index: pattern}` filters the
    // index_names list to just those matching the pattern. ES treats
    // _index as metadata so this happens at coordination time (no index
    // data is scanned on non-matching shards).
    let mut index_name_filter_patterns: Vec<String> = Vec::new();
    if let Some(q) = body.query.as_mut() {
        strip_index_constraints(q, &mut index_name_filter_patterns);
        // If the query is now empty, replace with MatchAll.
        if q.as_object().map(|o| o.is_empty()).unwrap_or(false) {
            *q = json!({ "match_all": {} });
        }
    }
    let index_names: Vec<String> = if index_name_filter_patterns.is_empty() {
        index_names
    } else {
        index_names
            .into_iter()
            .filter(|n| {
                index_name_filter_patterns
                    .iter()
                    .any(|p| p == n || glob_match(p, n))
            })
            .collect()
    };
    let index_names: Vec<&str> = index_names.iter().map(|s| s.as_str()).collect();
    // ── Closed-index resolution (ES expand_wildcards / ignore_unavailable) ──
    // A closed index cannot be searched. ES rules:
    //   * named explicitly   → index_closed_exception (400), unless
    //                           ignore_unavailable=true (then skip → empty).
    //   * matched by wildcard → silently dropped unless expand_wildcards
    //                           includes "closed"/"all" (default "open"); when
    //                           explicitly included, surface the exception.
    let index_names: Vec<&str> = {
        let iu = params.ignore_unavailable.as_deref() == Some("true");
        let ew = params.expand_wildcards.as_deref().unwrap_or("open");
        let include_closed = ew.split(',').any(|t| {
            let t = t.trim();
            t == "closed" || t == "all"
        });
        let concrete_tokens: Vec<&str> = raw_names
            .iter()
            .copied()
            .filter(|p| *p != "_all" && !p.contains('*'))
            .collect();
        let mut kept: Vec<&str> = Vec::with_capacity(index_names.len());
        for name in &index_names {
            if !state.engine.closed_indices.contains_key(*name) {
                kept.push(*name);
                continue;
            }
            if concrete_tokens.iter().any(|t| t == name) {
                if iu {
                    continue;
                } // explicit + ignore_unavailable → skip
                return closed_index_error(name); // explicit closed → 400
            } else if include_closed {
                return closed_index_error(name); // wildcard + expand_wildcards=closed → 400
            }
            // wildcard + default open → drop silently
        }
        kept
    };
    // allow_no_indices=false with nothing left after dropping closed → 404
    if index_names.is_empty() {
        let allow_no = params
            .allow_no_indices
            .as_deref()
            .map(|v| v == "true")
            .unwrap_or(true);
        let iu = params.ignore_unavailable.as_deref() == Some("true");
        if !allow_no && !iu {
            return ApiError::new(xerj_common::XerjError::index_not_found(&index)).into_response();
        }
    }

    // PIT index_filter: AND it with body.query so every PIT search
    // respects the filter chosen at PIT-open time.
    if let Some(pit) = pit_context.as_ref() {
        if let Some(ref filter) = pit.index_filter {
            body.query = Some(match body.query.take() {
                None => json!({ "bool": { "filter": [filter.clone()] } }),
                Some(existing) => json!({
                    "bool": {
                        "must": [existing],
                        "filter": [filter.clone()]
                    }
                }),
            });
        }
    }

    // ── #1093: refuse lookup clauses naming fields no resolved index maps ──
    // Opt-in (`?strict_unknown_fields=true`, the `index.query.strict_unknown_fields`
    // setting, or an autoindex-created index); runs after the PIT filter merge and
    // `_index`-constraint strip, on the query as it will actually execute. ES answers
    // these with a silent 0-hit 200; here that made a wrong field name indistinguishable from an
    // empty corpus (the map-gate run counted 5 silent wrong-field misses in
    // 30 agent intents). The refusal names the field and both escape hatches;
    // `exists` is exempt (zero IS the truthful answer there) and fresh
    // all-dynamic indices are exempt (nothing is mapped yet).
    if !index_names.is_empty() {
        if let Some(reason) = unknown_lookup_field_reason(
            &state,
            &index_names,
            params.strict_unknown_fields.as_deref(),
            body.query.as_ref(),
        )
        .await
        {
            return search_shard_validation_error(&reason);
        }
    }

    // Track the original knn config for downstream profile emission.
    // After we synthesise the inner Knn query and clear body.knn, the
    // profile builder still needs to know whether this was a knn search.
    let original_knn: Option<Value> = body.knn.clone();

    // Normalise the top-level `knn` spec. ES accepts an object OR an array
    // of clauses; the array form used to fall through every `.get(...)` in
    // this block (arrays have no keys) and silently return ZERO hits. A
    // single-element array is exactly the object form; a multi-element
    // array is the ES multi-kNN search (per-clause top-k, summed scores).
    let knn_norm: Option<Value> = match body.knn.clone() {
        Some(Value::Array(arr)) if arr.is_empty() => {
            let reason = "[knn] must not be empty";
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": {
                        "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                        "type": "illegal_argument_exception",
                        "reason": reason,
                    },
                    "status": 400,
                })),
            )
                .into_response();
        }
        Some(Value::Array(arr)) if arr.len() == 1 => Some(arr.into_iter().next().unwrap()),
        other => other,
    };

    // Per-clause effective k (explicit `k`, else `num_candidates`, else 10 —
    // the same derivation the query parser applies).
    fn knn_clause_k(knn_val: &Value) -> usize {
        let num_candidates = knn_val
            .get("num_candidates")
            .and_then(Value::as_u64)
            .map(|n| n as usize);
        knn_val
            .get("k")
            .and_then(Value::as_u64)
            .map(|n| n as usize)
            .or(num_candidates)
            .unwrap_or(10)
    }

    // Pass the ES knn spec through to the query DSL `knn` node VERBATIM —
    // field, query_vector, k, num_candidates, filter (object or array),
    // boost, and similarity all reach the parser. The old path round-tripped
    // through a lossy QueryNode builder that DROPPED `filter` (unfiltered
    // results ranked above filtered ones), `similarity` (sub-threshold docs
    // returned), and `boost`.
    fn knn_spec_to_query_json(knn_val: &Value) -> Value {
        let mut knn = serde_json::Map::new();
        for key in [
            "field",
            "query_vector",
            "k",
            "num_candidates",
            "filter",
            "boost",
            "similarity",
        ] {
            if let Some(v) = knn_val.get(key) {
                knn.insert(key.to_string(), v.clone());
            }
        }
        json!({ "knn": knn })
    }

    // ES knn semantics: a pure (non-hybrid) `knn` search returns at most `k`
    // nearest neighbours (summed across clauses for the array form), further
    // bounded by the request `size`, and reports `hits.total` as the number
    // of candidates actually returned — NOT the brute-force match count over
    // the whole index. Capture that cap here, before the knn query is folded
    // into a `bool` and `body.size` is bumped.
    // Hybrid knn (knn + a sibling `query`) keeps normal scoring/counting.
    let knn_total_cap: Option<usize> =
        knn_norm
            .as_ref()
            .filter(|_| body.query.is_none())
            .map(|knn_val| {
                let k_total = match knn_val {
                    Value::Array(arr) => arr
                        .iter()
                        .fold(0usize, |acc, c| acc.saturating_add(knn_clause_k(c))),
                    single => knn_clause_k(single),
                };
                k_total.min(body.size)
            });

    // If top-level "knn" is present, synthesise knn query node(s) and merge
    // with any "query".
    let effective_body: EsSearchBody = if let Some(ref knn_val) = knn_norm {
        let (knn_query_json, k_total) = match knn_val {
            Value::Array(arr) => {
                if body.query.is_some() {
                    // Multiple knn clauses + a sibling `query` need ES's
                    // full score-union executor; XERJ does not implement
                    // that combination. Fail loud instead of silently
                    // dropping the knn contributions.
                    let reason = "multiple [knn] clauses combined with a [query] are not \
                                  supported by this XERJ version; run the knn array \
                                  without [query], or a single knn clause with [query]";
                    return (
                        StatusCode::BAD_REQUEST,
                        Json(json!({
                            "error": {
                                "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                                "type": "illegal_argument_exception",
                                "reason": reason,
                            },
                            "status": 400,
                        })),
                    )
                        .into_response();
                }
                let clauses: Vec<Value> = arr.iter().map(knn_spec_to_query_json).collect();
                let k_total = arr
                    .iter()
                    .fold(0usize, |acc, c| acc.saturating_add(knn_clause_k(c)));
                (json!({ "bool": { "should": clauses } }), k_total)
            }
            single => (knn_spec_to_query_json(single), knn_clause_k(single)),
        };
        let merged_query = if let Some(ref existing_q) = body.query {
            // ES 8.x canonical hybrid: a top-level `knn` block beside a
            // `query` folds to `{"bool":{"should":[query, knn]}}` — a
            // disjunction, which is exactly ES's documented contract for the
            // shape: the knn side contributes the global top-k neighbours,
            // the hit set is the union of both halves, a document reached by
            // both scores the SUM `query_score + knn_score` (`boost`
            // weighting each side), and aggregations run over the union.
            //
            // The engine pre-executes a `knn` clause it finds inside a
            // compound bool and pins its top-k documents into the tree
            // (#825, `pin_knn_clause` in xerj-engine), so this fold carries
            // BOTH halves through the NORMAL search path — aggs, sort,
            // collapse, search_after, rescore, highlight, explain, profile
            // and min_score all apply to the union. That retires the #458
            // `hybrid_safe` special case, which routed the no-extras case to
            // the XERJ-native `hybrid` (RRF) executor — itself a scoring
            // divergence from ES (RRF fuses ranks; ES sums raw scores) — and
            // kept the kNN-dropped lexical `bool.should` whenever any of
            // those features was present (#395's silent drop).
            json!({ "bool": { "should": [existing_q, knn_query_json] } })
        } else {
            knn_query_json
        };
        EsSearchBody {
            query: Some(merged_query),
            size: body.size.max(k_total),
            knn: None,
            ..body.clone()
        }
    } else {
        body
    };

    // Rebind body so all downstream references use the effective (KNN-merged) body.
    let mut body = effective_body;

    // Default `@timestamp DESC` sort when the index declares
    // `index.sort.field`. ES sets this automatically when @timestamp is
    // declared at create time (or after close/reopen picks up the current
    // mapping). Mirror that behaviour using the `__xy_index_sort_*` hints
    // stored in settings at create / reopen time.
    //
    // For the implicit auto-@timestamp hint this is LEAF ordering, not a
    // per-doc sort — see `implicit_leaf_ts` below.
    let mut implicit_leaf_ts: Option<String> = None;
    if index_names.len() == 1 {
        let idx_name = index_names[0];
        let (sort_field, sort_order, explicit, reopen_derived) = state
            .engine
            .index_settings
            .get(idx_name)
            .map(|r| {
                let s = r.value();
                let f = s
                    .get("__xy_index_sort_field")
                    .and_then(Value::as_str)
                    .map(str::to_string);
                let o = s
                    .get("__xy_index_sort_order")
                    .and_then(Value::as_str)
                    .unwrap_or("desc")
                    .to_string();
                let ex = s
                    .get("__xy_index_sort_explicit")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let ro = s
                    .get("__xy_index_sort_reopen")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                (f, o, ex, ro)
            })
            .unwrap_or((None, "desc".to_string(), false, false));
        if let Some(f) = sort_field {
            // Apply the index sort ONLY for an EXPLICITLY declared
            // `index.sort` (settings), when no sort was requested or the
            // only sort key is the implicit `_doc` order (ES returns docs
            // in index-sort order for a `sort: _doc` request against an
            // index-sorted index).
            //
            // The auto-@timestamp heuristic (any index that merely MAPS a
            // `@timestamp` date field) is no longer applied: real ES does
            // NOT implicitly sort query results just because @timestamp is
            // mapped (index.sort is a physical layout setting, auto-set
            // only for logsdb/time-series modes), and the injected sort
            // routed EVERY sortless query on such indexes through the
            // global top-N heap — an O(total-docs) walk of every segment
            // per request.  Live-verified as the dominant cost of the
            // read-under-write collapse: an LLM-telemetry corpus (maps
            // @timestamp) saw sortless term/match_all size=10 queries walk
            // 1.5 M docs (~2-7 s each, `walked=1500002 admitted=250252
            // allhits_cap=false`) while the same query with an explicit
            // `sort: _doc` took 45 ms.
            // For the implicit auto-@timestamp hint, real ES (7.16+
            // "sort segments on timestamp") orders the LEAVES — segments
            // are read newest-max-@timestamp-first while docs inside each
            // segment keep arrival order, scores stay 1.0 and max_score
            // stays 1.0.  The old implementation approximated that with an
            // injected per-doc `@timestamp desc` sort, which diverges from
            // real ES on any settled index: page windows are cut by
            // timestamp value (from:500 returned timestamp-ranked ids, ES
            // returns arrival ids 500..549), equal timestamps re-ordered
            // lexicographically by _id, and the sort suppressed max_score
            // (null vs ES 1.0) — all three live-verified against ES 8.13.4.
            // So for the implicit hint pass a leaf-order flag to the engine
            // instead (`SearchRequest::leaf_ts_field`), only for the
            // match_all-shaped sortless requests the old injection covered
            // (the shape search/380_sort_segments_on_timestamp.yml
            // observes).  Filtered queries (term/range/bool) are untouched
            // — real ES's segment ordering doesn't impose a query-time
            // global sort on them either.
            let implicit_ok = body.query.is_none()
                || body
                    .query
                    .as_ref()
                    .and_then(|q| q.as_object())
                    .map(|o| o.len() == 1 && o.contains_key("match_all"))
                    .unwrap_or(false);
            if explicit {
                // Explicitly declared `index.sort` (settings): keep the
                // injected per-doc sort — ES returns docs in index-sort
                // order for sortless and `sort: _doc` requests there.
                let apply = body.sort.is_none()
                    || body.sort.as_ref().map(is_lone_doc_sort).unwrap_or(false);
                if apply {
                    body.sort = Some(json!([{ f: { "order": sort_order } }]));
                }
            } else if implicit_ok && body.sort.is_none() {
                if reopen_derived {
                    // Reopen-derived hint: the close-time full-drain flush
                    // already consolidated the per-refresh leaves ES would
                    // have kept, so settled leaf ordering can't reproduce
                    // the reopen contract — keep the historical per-doc
                    // sort for these indices (see the `_open` handler).
                    body.sort = Some(json!([{ f: { "order": sort_order } }]));
                } else {
                    implicit_leaf_ts = Some(f);
                }
            }
        }
    }

    // ── Passthrough field rewriting ────────────────────────────────────
    // ES `flattened` and `passthrough` types support `passthrough.priority`,
    // which exposes their sub-field paths at the index root. A query like
    // `term: { status: "active" }` against an index where `labels` is
    // `type: flattened, passthrough: { priority: 10, properties: { status }
    // }` should resolve to `term: { labels.status: "active" }`. Higher-
    // priority fields win ties with same-named sub-fields from other
    // passthrough roots. We do this rewrite at coordination time so the
    // engine's matcher sees the canonical dotted path.
    {
        // Collect (root_field, parent_path) per index, sorted by descending
        // passthrough priority so higher priority wins. A concrete root
        // field with the same name as a passthrough sub-field always
        // shadows the passthrough alias (per ES rules).
        let mut pass_map: std::collections::HashMap<String, (String, i64)> =
            std::collections::HashMap::new();
        let mut concrete_roots: std::collections::HashSet<String> =
            std::collections::HashSet::new();
        for ix in &index_names {
            let Some(m) = state.engine.index_mappings.get(*ix) else {
                continue;
            };
            let mapping = m.clone();
            let props = mapping
                .get("mappings")
                .and_then(|mm| mm.get("properties"))
                .or_else(|| mapping.get("properties"));
            let Some(pobj) = props.and_then(Value::as_object) else {
                continue;
            };
            // First pass: record every concrete root-level field.
            for (name, spec) in pobj {
                let pt = spec.get("type").and_then(Value::as_str);
                let is_passthrough_root = pt == Some("passthrough")
                    || spec
                        .get("passthrough")
                        .and_then(|p| p.get("priority"))
                        .is_some();
                if !is_passthrough_root {
                    concrete_roots.insert(name.clone());
                }
            }
            // Second pass: collect passthrough sub-fields.
            for (parent_name, parent_spec) in pobj {
                let pt = parent_spec.get("type").and_then(Value::as_str);
                let is_passthrough = pt == Some("passthrough");
                let priority = parent_spec
                    .get("passthrough")
                    .and_then(|p| p.get("priority"))
                    .and_then(Value::as_i64)
                    .or_else(|| {
                        if is_passthrough {
                            parent_spec.get("priority").and_then(Value::as_i64)
                        } else {
                            None
                        }
                    });
                let Some(prio) = priority else { continue };
                let sub_props = parent_spec.get("properties").and_then(Value::as_object);
                let Some(sp) = sub_props else { continue };
                for (sub_name, _spec) in sp {
                    let parent_path = parent_name.clone();
                    let entry = pass_map
                        .entry(sub_name.clone())
                        .or_insert((parent_path.clone(), prio));
                    if entry.1 < prio {
                        *entry = (parent_path, prio);
                    }
                }
            }
        }
        // Concrete-root shadowing.
        for n in &concrete_roots {
            pass_map.remove(n);
        }
        if !pass_map.is_empty() {
            fn rewrite_query(
                q: &mut Value,
                pass: &std::collections::HashMap<String, (String, i64)>,
            ) {
                match q {
                    Value::Object(obj) => {
                        for clause_key in [
                            "term",
                            "terms",
                            "match",
                            "match_phrase",
                            "range",
                            "prefix",
                            "wildcard",
                            "fuzzy",
                            "regexp",
                            "exists",
                            "match_phrase_prefix",
                        ] {
                            if let Some(Value::Object(inner)) = obj.get_mut(clause_key) {
                                let keys: Vec<String> = inner.keys().cloned().collect();
                                for k in keys {
                                    if let Some((parent, _)) = pass.get(&k) {
                                        // Rename key to parent.k
                                        if let Some(v) = inner.remove(&k) {
                                            let new_key = format!("{}.{}", parent, k);
                                            inner.insert(new_key, v);
                                        }
                                    }
                                }
                            }
                        }
                        for (_, child) in obj.iter_mut() {
                            rewrite_query(child, pass);
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr.iter_mut() {
                            rewrite_query(item, pass);
                        }
                    }
                    _ => {}
                }
            }
            if let Some(q) = body.query.as_mut() {
                rewrite_query(q, &pass_map);
            }
            // Also rewrite sort fields that reference passthrough roots.
            if let Some(sort) = body.sort.as_mut() {
                fn rewrite_sort(
                    v: &mut Value,
                    pass: &std::collections::HashMap<String, (String, i64)>,
                ) {
                    match v {
                        Value::String(s) => {
                            if let Some((parent, _)) = pass.get(s.as_str()) {
                                *s = format!("{}.{}", parent, s);
                            }
                        }
                        Value::Object(obj) => {
                            let keys: Vec<String> = obj.keys().cloned().collect();
                            for k in keys {
                                if let Some((parent, _)) = pass.get(&k) {
                                    if let Some(v) = obj.remove(&k) {
                                        obj.insert(format!("{}.{}", parent, k), v);
                                    }
                                }
                            }
                        }
                        Value::Array(arr) => {
                            for item in arr.iter_mut() {
                                rewrite_sort(item, pass);
                            }
                        }
                        _ => {}
                    }
                }
                rewrite_sort(sort, &pass_map);
            }
        }
    }

    // Apply alias filters: when any index_names entry is a filtered alias,
    // AND the alias's `filter` clause with the user's query. ES applies
    // these on the coordinating node so each underlying index sees the
    // filter. The combined filter is also handed to run_aggs via the
    // background corpus (covered by the query's filter path already).
    {
        // Built from the names as WRITTEN, not from `index_names`. Expanding
        // an alias to its concrete members (#433) removes the alias name from
        // that list, and this lookup matches on the alias name — so reading it
        // from the expanded list silently dropped every filtered alias's
        // filter. `global_with_aliases.yml` caught exactly that.
        let mut alias_filters: Vec<Value> = Vec::new();
        for name in &resolved_names_owned {
            for entry in state.engine.aliases.iter() {
                if entry.key() != name {
                    continue;
                }
                for backing in entry.value().iter() {
                    if let Some(meta) = state.engine.index_alias_metadata.get(backing) {
                        if let Some(filter) = meta
                            .get(name.as_str())
                            .and_then(|v| v.get("filter"))
                            .cloned()
                        {
                            alias_filters.push(filter);
                        }
                    }
                }
            }
        }
        if !alias_filters.is_empty() {
            let original = body
                .query
                .clone()
                .unwrap_or_else(|| json!({"match_all": {}}));
            // ES semantics: alias filters are `filter` clauses (unscored,
            // pre-filter applied before the main query). This matters for
            // knn queries where `bool.filter` acts as a pre-filter but
            // `bool.must` is a post-filter — see
            // vectors/search.vectors/135_knn_query_nested_search_ivf.yml
            // "pre-filtered on alias" (filter → 1 hit) vs. "post-filtered"
            // (must → 0 hits).
            body.query = Some(json!({
                "bool": {
                    "must": [original],
                    "filter": alias_filters.clone(),
                }
            }));
            // Inject the same filter as a default `background_filter` on
            // every `significant_terms` / `significant_text` clause so
            // their `bg_count` is computed against the alias-filtered
            // background instead of the full index.
            let combined = if alias_filters.len() == 1 {
                alias_filters.into_iter().next().unwrap()
            } else {
                json!({"bool": {"must": alias_filters}})
            };
            fn inject_bg_filter(v: &mut Value, filter: &Value) {
                match v {
                    Value::Object(obj) => {
                        for k in ["significant_terms", "significant_text"] {
                            if let Some(body_obj) = obj.get_mut(k).and_then(|x| x.as_object_mut()) {
                                if !body_obj.contains_key("background_filter") {
                                    body_obj.insert("background_filter".into(), filter.clone());
                                }
                            }
                        }
                        let keys: Vec<String> = obj.keys().cloned().collect();
                        for key in keys {
                            if let Some(child) = obj.get_mut(&key) {
                                inject_bg_filter(child, filter);
                            }
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr {
                            inject_bg_filter(item, filter);
                        }
                    }
                    _ => {}
                }
            }
            if let Some(aggs) = body.aggs.as_mut() {
                inject_bg_filter(aggs, &combined);
            }
            if let Some(aggs) = body.aggregations.as_mut() {
                inject_bg_filter(aggs, &combined);
            }
        }
    }

    // Resolve `terms` lookup clauses: `{"terms": {"<field>": {"index": I,
    // "id": D, "path": P}}}` → substitute with the concrete array of
    // values fetched from the source doc at `index:id:path`. ES runs this
    // at coordination time; we do the same here so the downstream parser
    // never sees a lookup object (we'd return MatchNone otherwise).
    if let Some(q) = body.query.as_mut() {
        resolve_terms_lookups(q, &state).await;
    }
    // Aggs (filter / filters buckets / adjacency_matrix sub-filters) can
    // also carry terms lookups — walk those subtrees too so the nested
    // parser doesn't see the raw lookup object.
    if let Some(aggs) = body.aggs.as_mut() {
        resolve_terms_lookups(aggs, &state).await;
    }
    if let Some(aggs) = body.aggregations.as_mut() {
        resolve_terms_lookups(aggs, &state).await;
    }
    // Rewrite `match` queries that target a keyword field into `term`
    // queries. ES treats `match` on keyword fields as exact (the
    // keyword analyzer is a no-op), but our Match parser tokenizes the
    // query string and OR-matches tokens. Without the rewrite, a
    // `match string_field: foo` on the canonical filters_bucket test
    // also matches docs with `string_field: "foo bar"`.
    {
        let mut keyword_fields: std::collections::HashSet<String> =
            std::collections::HashSet::new();
        let mut split_kw_fields: std::collections::HashSet<String> =
            std::collections::HashSet::new();
        // Numeric/boolean-typed fields: `match` on them rewrites to the
        // equivalent exact `term` (see the mapping walk below).
        let mut exact_value_fields: std::collections::HashSet<String> =
            std::collections::HashSet::new();
        for ix in &index_names {
            if let Some(m) = state.engine.index_mappings.get(*ix) {
                let mapping = m.clone();
                let props = mapping
                    .get("mappings")
                    .and_then(|mm| mm.get("properties"))
                    .or_else(|| mapping.get("properties"))
                    .cloned();
                if let Some(Value::Object(props)) = props {
                    for (name, spec) in props {
                        match spec.get("type").and_then(Value::as_str) {
                            Some("keyword") => {
                                keyword_fields.insert(name.clone());
                                if spec
                                    .get("split_queries_on_whitespace")
                                    .and_then(Value::as_bool)
                                    .unwrap_or(false)
                                {
                                    split_kw_fields.insert(name);
                                }
                            }
                            // `match` on numeric/boolean fields is NOT
                            // analyzed either — ES executes it as the
                            // equivalent `term` query (numerics score a
                            // constant 1.0·boost per hit — points carry
                            // no BM25 stats; booleans score BM25 on the
                            // T/F term). Live-verified vs ES 8.13.4:
                            // match num:42 → 1.0 where the tokenizing
                            // Match path BM25-scored it 7.6.
                            Some(
                                "long" | "integer" | "short" | "byte" | "double" | "float"
                                | "half_float" | "scaled_float" | "unsigned_long" | "boolean",
                            ) => {
                                exact_value_fields.insert(name.clone());
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
        if !keyword_fields.is_empty() || !exact_value_fields.is_empty() {
            fn rewrite(
                v: &mut Value,
                kw: &std::collections::HashSet<String>,
                split: &std::collections::HashSet<String>,
                exact: &std::collections::HashSet<String>,
            ) {
                match v {
                    Value::Object(obj) => {
                        let mut new_node: Option<(String, Value)> = None;
                        if let Some(m_val) = obj.get("match").and_then(|m| m.as_object()) {
                            if let Some((field, raw)) = m_val.iter().next() {
                                if kw.contains(field) || exact.contains(field) {
                                    // Preserve a per-clause `boost` through the
                                    // rewrite: ES folds the match boost into the
                                    // term weight, so dropping it here silently
                                    // de-boosted `{"match": {kw: {"query": …,
                                    // "boost": N}}}`.
                                    let mut boost: Option<Value> = None;
                                    let mut lenient = false;
                                    let value = match raw {
                                        Value::Object(inner) => {
                                            boost = inner.get("boost").cloned();
                                            lenient =
                                                matches!(
                                                    inner.get("lenient"),
                                                    Some(Value::Bool(true))
                                                ) || inner.get("lenient").and_then(Value::as_str)
                                                    == Some("true");
                                            inner.get("query").cloned().unwrap_or(raw.clone())
                                        }
                                        _ => raw.clone(),
                                    };
                                    // #1284: a `term` has no `lenient`, and the
                                    // engine 400s a non-numeric term value on a
                                    // numeric field. A lenient `match` whose value
                                    // is not a number stays a `match`, which the
                                    // engine answers with no hits, as ES does.
                                    let lenient_non_numeric = lenient
                                        && exact.contains(field)
                                        && value
                                            .as_str()
                                            .is_some_and(|s| s.trim().parse::<f64>().is_err());
                                    let s_owned = match &value {
                                        Value::String(s) => Some(s.clone()),
                                        Value::Number(n) => Some(n.to_string()),
                                        _ => None,
                                    };
                                    let split_field = split.contains(field);
                                    if lenient_non_numeric {
                                        // Leave the clause as written.
                                    } else if split_field {
                                        if let Some(s) = s_owned.as_deref() {
                                            let toks: Vec<&str> = s.split_whitespace().collect();
                                            if toks.len() > 1 {
                                                // Multi-token query → terms (OR over tokens).
                                                let arr: Vec<Value> = toks
                                                    .iter()
                                                    .map(|t| Value::String(t.to_string()))
                                                    .collect();
                                                let mut terms = serde_json::Map::new();
                                                terms.insert(field.clone(), Value::Array(arr));
                                                if let Some(b) = boost.clone() {
                                                    terms.insert("boost".to_string(), b);
                                                }
                                                new_node = Some((
                                                    "terms".to_string(),
                                                    Value::Object(terms),
                                                ));
                                            } else {
                                                // Single token → term.
                                                let mut term = serde_json::Map::new();
                                                let v = if toks.is_empty() {
                                                    Value::String(String::new())
                                                } else {
                                                    Value::String(toks[0].to_string())
                                                };
                                                let v = match boost.clone() {
                                                    Some(b) => serde_json::json!({
                                                        "value": v, "boost": b
                                                    }),
                                                    None => v,
                                                };
                                                term.insert(field.clone(), v);
                                                new_node =
                                                    Some(("term".to_string(), Value::Object(term)));
                                            }
                                        }
                                    } else {
                                        // Plain keyword → exact term.
                                        let mut term = serde_json::Map::new();
                                        let v = match boost.clone() {
                                            Some(b) => serde_json::json!({
                                                "value": value, "boost": b
                                            }),
                                            None => value,
                                        };
                                        term.insert(field.clone(), v);
                                        new_node = Some(("term".to_string(), Value::Object(term)));
                                    }
                                }
                            }
                        }
                        if let Some((tag, body)) = new_node {
                            obj.remove("match");
                            obj.insert(tag, body);
                        }
                        let keys: Vec<String> = obj.keys().cloned().collect();
                        for k in keys {
                            if let Some(c) = obj.get_mut(&k) {
                                rewrite(c, kw, split, exact);
                            }
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr {
                            rewrite(item, kw, split, exact);
                        }
                    }
                    _ => {}
                }
            }
            if let Some(q) = body.query.as_mut() {
                rewrite(q, &keyword_fields, &split_kw_fields, &exact_value_fields);
            }
            if let Some(aggs) = body.aggs.as_mut() {
                rewrite(aggs, &keyword_fields, &split_kw_fields, &exact_value_fields);
            }
            if let Some(aggs) = body.aggregations.as_mut() {
                rewrite(aggs, &keyword_fields, &split_kw_fields, &exact_value_fields);
            }
        }
    }

    // Annotate `matrix_stats` aggs with `__xy_f32_fields__`: list of
    // its `fields[]` entries whose mapping declares `type: float`. The
    // engine reads this to round-trip values through f32 before
    // reducing, matching ES's index-time precision.
    {
        let mut all_floats: std::collections::HashSet<String> = std::collections::HashSet::new();
        for ix in &index_names {
            if let Some(m) = state.engine.index_mappings.get(*ix) {
                let mapping = m.clone();
                let props = mapping
                    .get("mappings")
                    .and_then(|mm| mm.get("properties"))
                    .or_else(|| mapping.get("properties"))
                    .cloned();
                if let Some(Value::Object(props)) = props {
                    for (name, spec) in props {
                        if spec.get("type").and_then(Value::as_str) == Some("float") {
                            all_floats.insert(name);
                        }
                    }
                }
            }
        }
        if !all_floats.is_empty() {
            fn annotate(v: &mut Value, floats: &std::collections::HashSet<String>) {
                match v {
                    Value::Object(obj) => {
                        if let Some(ms) =
                            obj.get_mut("matrix_stats").and_then(|x| x.as_object_mut())
                        {
                            if !ms.contains_key("__xy_f32_fields__") {
                                let fields = ms
                                    .get("fields")
                                    .and_then(Value::as_array)
                                    .cloned()
                                    .unwrap_or_default();
                                let f32_list: Vec<Value> = fields
                                    .into_iter()
                                    .filter_map(|v| {
                                        let s = v.as_str()?.to_string();
                                        if floats.contains(&s) {
                                            Some(Value::String(s))
                                        } else {
                                            None
                                        }
                                    })
                                    .collect();
                                if !f32_list.is_empty() {
                                    ms.insert(
                                        "__xy_f32_fields__".to_string(),
                                        Value::Array(f32_list),
                                    );
                                }
                            }
                        }
                        let keys: Vec<String> = obj.keys().cloned().collect();
                        for k in keys {
                            if let Some(c) = obj.get_mut(&k) {
                                annotate(c, floats);
                            }
                        }
                    }
                    Value::Array(arr) => {
                        for item in arr {
                            annotate(item, floats);
                        }
                    }
                    _ => {}
                }
            }
            if let Some(aggs) = body.aggs.as_mut() {
                annotate(aggs, &all_floats);
            }
            if let Some(aggs) = body.aggregations.as_mut() {
                annotate(aggs, &all_floats);
            }
        }
    }

    // Annotate every `composite` agg with `__xy_field_types__`: the mapping
    // type of each of its `terms` sources' fields. The engine types the
    // composite bucket keys from the SOURCE FIELD MAPPING (keyword → string,
    // boolean → true/false, numerics → numbers) instead of string-parse
    // heuristics that corrupted keyword values like "007" into the number 7
    // and rendered booleans as the strings "true"/"false".
    {
        fn gather_composite_terms_fields(v: &Value, out: &mut std::collections::HashSet<String>) {
            match v {
                Value::Object(obj) => {
                    if let Some(sources) = obj
                        .get("composite")
                        .and_then(|c| c.get("sources"))
                        .and_then(Value::as_array)
                    {
                        for src in sources {
                            if let Some(src_obj) = src.as_object() {
                                for spec in src_obj.values() {
                                    if let Some(f) = spec
                                        .get("terms")
                                        .and_then(|t| t.get("field"))
                                        .and_then(Value::as_str)
                                    {
                                        out.insert(f.to_string());
                                    }
                                }
                            }
                        }
                    }
                    for c in obj.values() {
                        gather_composite_terms_fields(c, out);
                    }
                }
                Value::Array(arr) => {
                    for item in arr {
                        gather_composite_terms_fields(item, out);
                    }
                }
                _ => {}
            }
        }
        let mut wanted: std::collections::HashSet<String> = std::collections::HashSet::new();
        if let Some(aggs) = body.aggs.as_ref() {
            gather_composite_terms_fields(aggs, &mut wanted);
        }
        if let Some(aggs) = body.aggregations.as_ref() {
            gather_composite_terms_fields(aggs, &mut wanted);
        }
        if !wanted.is_empty() {
            // Resolve a (possibly dotted / multi-field) path against a
            // mapping `properties` object: `user.name` walks properties,
            // `agent.keyword` walks multi-`fields`.
            fn type_in_props(props: &Value, field: &str) -> Option<String> {
                let mut cur = props;
                let mut parts = field.split('.').peekable();
                while let Some(part) = parts.next() {
                    let spec = cur.get(part)?;
                    if parts.peek().is_none() {
                        return spec.get("type").and_then(Value::as_str).map(str::to_string);
                    }
                    cur = spec.get("properties").or_else(|| spec.get("fields"))?;
                }
                None
            }
            let mut types: serde_json::Map<String, Value> = serde_json::Map::new();
            for f in &wanted {
                for ix in &index_names {
                    if let Some(m) = state.engine.index_mappings.get(*ix) {
                        let mapping = m.clone();
                        let props = mapping
                            .get("mappings")
                            .and_then(|mm| mm.get("properties"))
                            .or_else(|| mapping.get("properties"))
                            .cloned();
                        if let Some(p) = props {
                            if let Some(t) = type_in_props(&p, f) {
                                types.insert(f.clone(), Value::String(t));
                                break;
                            }
                        }
                    }
                }
            }
            if !types.is_empty() {
                fn annotate(v: &mut Value, types: &serde_json::Map<String, Value>) {
                    match v {
                        Value::Object(obj) => {
                            if let Some(comp) =
                                obj.get_mut("composite").and_then(|c| c.as_object_mut())
                            {
                                if !comp.contains_key("__xy_field_types__") {
                                    let mut local = serde_json::Map::new();
                                    if let Some(sources) =
                                        comp.get("sources").and_then(Value::as_array)
                                    {
                                        for src in sources {
                                            if let Some(src_obj) = src.as_object() {
                                                for spec in src_obj.values() {
                                                    if let Some(f) = spec
                                                        .get("terms")
                                                        .and_then(|t| t.get("field"))
                                                        .and_then(Value::as_str)
                                                    {
                                                        if let Some(t) = types.get(f) {
                                                            local.insert(f.to_string(), t.clone());
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                    if !local.is_empty() {
                                        comp.insert(
                                            "__xy_field_types__".to_string(),
                                            Value::Object(local),
                                        );
                                    }
                                }
                            }
                            for c in obj.values_mut() {
                                annotate(c, types);
                            }
                        }
                        Value::Array(arr) => {
                            for item in arr {
                                annotate(item, types);
                            }
                        }
                        _ => {}
                    }
                }
                if let Some(aggs) = body.aggs.as_mut() {
                    annotate(aggs, &types);
                }
                if let Some(aggs) = body.aggregations.as_mut() {
                    annotate(aggs, &types);
                }
            }
        }
    }

    // Inject the mapping's per-field date `format` into date_histogram /
    // date_range / range agg bodies that don't carry an explicit
    // `format`. ES uses the mapping's format to render bucket keys
    // (`key_as_string`, `from_as_string`, `to_as_string`) when the agg
    // doesn't override, so without this the output string deviates from
    // the expected mapping-specified shape (e.g. `yyyy-MM-dd HH:mm:ss`
    // vs ISO-8601).
    {
        let mapping_opt: Option<Value> = index_names
            .iter()
            .filter_map(|ix| state.engine.index_mappings.get(*ix).map(|v| v.clone()))
            .next();
        if let Some(mapping) = mapping_opt {
            let props: Option<Value> = mapping
                .get("mappings")
                .and_then(|m| m.get("properties"))
                .or_else(|| mapping.get("properties"))
                .cloned();
            if let Some(props) = props {
                let lookup_format = move |field: &str| -> Option<String> {
                    let fspec = props.get(field)?;
                    let ftype = fspec.get("type").and_then(Value::as_str)?;
                    if !matches!(ftype, "date" | "date_nanos") {
                        return None;
                    }
                    fspec
                        .get("format")
                        .and_then(Value::as_str)
                        // ES format chains ("strict_date_optional_time||epoch_millis"):
                        // bucket keys print with the FIRST format of the chain
                        // (verified live on ES 8.13.4). Injecting the raw chain
                        // made every renderer fall through to java_to_strftime,
                        // which echoed the chain string itself as key_as_string
                        // (b7 DEFECT 2). Normalise to the first component here so
                        // every downstream consumer (date_histogram brute +
                        // columnar, date_range, composite, and the parse side)
                        // sees a single resolvable format.
                        .map(|f| f.split("||").next().unwrap_or(f).trim().to_string())
                };
                fn inject_format(v: &mut Value, lookup: &dyn Fn(&str) -> Option<String>) {
                    match v {
                        Value::Object(obj) => {
                            for key in ["date_histogram", "date_range", "range"].iter() {
                                if let Some(body) =
                                    obj.get_mut(*key).and_then(|x| x.as_object_mut())
                                {
                                    if !body.contains_key("format") {
                                        let field = body
                                            .get("field")
                                            .and_then(Value::as_str)
                                            .map(String::from);
                                        if let Some(f) = field {
                                            if let Some(fmt) = lookup(&f) {
                                                body.insert(
                                                    "format".to_string(),
                                                    Value::String(fmt),
                                                );
                                            }
                                        }
                                    }
                                }
                            }
                            let keys: Vec<String> = obj.keys().cloned().collect();
                            for k in keys {
                                if let Some(child) = obj.get_mut(&k) {
                                    inject_format(child, lookup);
                                }
                            }
                        }
                        Value::Array(arr) => {
                            for item in arr {
                                inject_format(item, lookup);
                            }
                        }
                        _ => {}
                    }
                }
                if let Some(aggs) = body.aggs.as_mut() {
                    inject_format(aggs, &lookup_format);
                }
                if let Some(aggs) = body.aggregations.as_mut() {
                    inject_format(aggs, &lookup_format);
                }
            }
        }
    }

    // Propagate the search-level `fields` request into every top_hits
    // sub-agg that doesn't already specify its own `fields`. ES does
    // this implicitly.
    //
    // The agg tree shape is
    // `{<user_name>: {<agg_type>: {..params..}, aggs: {..}}}`. We walk
    // the tree and, at every agg-body level, if the agg-body has a
    // `top_hits` key (meaning the agg type IS top_hits), we dig into
    // its params map and insert `fields` there. Adding `fields` at the
    // agg-body level would corrupt the agg-type lookup — serde_json::Map
    // iterates keys alphabetically, so a sibling `fields` key would
    // hijack dispatch (fields < top_hits).
    if let Some(top_fields) = body.fields.clone() {
        fn inject_top_hits_fields(v: &mut Value, fields: &Value) {
            if let Value::Object(obj) = v {
                // Current obj is an aggs-container like
                // `{"user_name": {agg-body}}`. For each user_name's
                // agg-body, if its type key is `top_hits`, inject
                // `fields` into that top_hits params map.
                let user_names: Vec<String> = obj.keys().cloned().collect();
                for user_name in &user_names {
                    let Some(agg_body) = obj.get_mut(user_name).and_then(|v| v.as_object_mut())
                    else {
                        continue;
                    };
                    if let Some(Value::Object(th_params)) = agg_body.get_mut("top_hits") {
                        if !th_params.contains_key("fields") {
                            th_params.insert("fields".to_string(), fields.clone());
                        }
                    }
                    // Descend into any nested `aggs` / `aggregations`
                    // container on this agg-body.
                    for sub_key in ["aggs", "aggregations"] {
                        if let Some(sub) = agg_body.get_mut(sub_key) {
                            inject_top_hits_fields(sub, fields);
                        }
                    }
                }
            }
            if let Value::Array(arr) = v {
                for item in arr {
                    inject_top_hits_fields(item, fields);
                }
            }
        }
        if let Some(aggs) = body.aggs.as_mut() {
            inject_top_hits_fields(aggs, &top_fields);
        }
        if let Some(aggs) = body.aggregations.as_mut() {
            inject_top_hits_fields(aggs, &top_fields);
        }
    }

    // Propagate `runtime_mappings` into every top_hits sub-agg's
    // params under the same key — so the top_hits aggregator can
    // evaluate Painless runtime fields against each emitted hit. ES
    // exposes runtime_mappings at the body level globally; we mirror
    // that visibility into top_hits.
    if let Some(rm) = body.runtime_mappings.clone() {
        fn inject_top_hits_runtime(v: &mut Value, rm: &Value) {
            if let Value::Object(obj) = v {
                let user_names: Vec<String> = obj.keys().cloned().collect();
                for user_name in &user_names {
                    let Some(agg_body) = obj.get_mut(user_name).and_then(|v| v.as_object_mut())
                    else {
                        continue;
                    };
                    if let Some(Value::Object(th_params)) = agg_body.get_mut("top_hits") {
                        if !th_params.contains_key("runtime_mappings") {
                            th_params.insert("runtime_mappings".to_string(), rm.clone());
                        }
                    }
                    for sub_key in ["aggs", "aggregations"] {
                        if let Some(sub) = agg_body.get_mut(sub_key) {
                            inject_top_hits_runtime(sub, rm);
                        }
                    }
                }
            }
            if let Value::Array(arr) = v {
                for item in arr {
                    inject_top_hits_runtime(item, rm);
                }
            }
        }
        if let Some(aggs) = body.aggs.as_mut() {
            inject_top_hits_runtime(aggs, &rm);
        }
        if let Some(aggs) = body.aggregations.as_mut() {
            inject_top_hits_runtime(aggs, &rm);
        }
    }

    // When any participating index has `_source.enabled: false` in its
    // mapping, force every top_hits sub-agg to emit `_source: false` so
    // the top_hits response doesn't contain the internal source clone
    // we still keep around for fields/highlight/etc.
    let source_disabled_somewhere = index_names.iter().any(|ix| {
        state
            .engine
            .index_mappings
            .get(*ix)
            .and_then(|m| {
                m.get("mappings")
                    .and_then(|mm| mm.get("_source"))
                    .or_else(|| m.get("_source"))
                    .cloned()
            })
            .and_then(|src| src.get("enabled").and_then(Value::as_bool))
            .map(|b| !b)
            .unwrap_or(false)
    });
    if source_disabled_somewhere {
        fn inject_top_hits_no_source(v: &mut Value) {
            if let Value::Object(obj) = v {
                let user_names: Vec<String> = obj.keys().cloned().collect();
                for user_name in &user_names {
                    let Some(agg_body) = obj.get_mut(user_name).and_then(|v| v.as_object_mut())
                    else {
                        continue;
                    };
                    if let Some(Value::Object(th_params)) = agg_body.get_mut("top_hits") {
                        if !th_params.contains_key("_source") {
                            th_params.insert("_source".to_string(), Value::Bool(false));
                        }
                    }
                    for sub_key in ["aggs", "aggregations"] {
                        if let Some(sub) = agg_body.get_mut(sub_key) {
                            inject_top_hits_no_source(sub);
                        }
                    }
                }
            }
        }
        if let Some(aggs) = body.aggs.as_mut() {
            inject_top_hits_no_source(aggs);
        }
        if let Some(aggs) = body.aggregations.as_mut() {
            inject_top_hits_no_source(aggs);
        }
    }

    // Resolve stored script references inside scripted_metric scripts.
    // ES accepts `init_script: {id: "name"}` where `name` refers to a
    // previously stored script. We substitute these with the stored
    // script's source so the engine sees only inline scripts.
    if let Some(aggs) = body.aggs.as_mut() {
        resolve_stored_scripts(aggs, &state);
    }
    if let Some(aggs) = body.aggregations.as_mut() {
        resolve_stored_scripts(aggs, &state);
    }

    // Rewrite `exists` queries against fields whose mapping declares
    // `index: false` and no doc_values. ES returns 0 hits for those
    // (the field is materially unqueryable). Do this against each
    // participating index's mapping, applying the `match_none`
    // substitution when the field is unqueryable in *every* index.
    let participating_indices: Vec<String> = index_names.iter().map(|s| s.to_string()).collect();
    if let Some(q) = body.query.as_mut() {
        rewrite_unqueryable_exists(q, &state, &participating_indices);
    }

    // Collect alias → target field name mappings from every
    // participating index. Mapping shape:
    //   properties: { my_alias: {type: alias, path: other_field} }
    // We rewrite any reference to `my_alias` across the search body
    // (query/sort/aggs/collapse) to its target path so downstream
    // agg/match/sort/collapse logic sees the real field.
    let alias_map: std::collections::HashMap<String, String> = {
        let mut m = std::collections::HashMap::new();
        for ix in &participating_indices {
            if let Some(mapping) = state.engine.index_mappings.get(ix.as_str()) {
                fn collect_aliases(
                    props: &Value,
                    prefix: &str,
                    out: &mut std::collections::HashMap<String, String>,
                ) {
                    let Some(obj) = props.as_object() else { return };
                    for (name, spec) in obj {
                        let full = if prefix.is_empty() {
                            name.clone()
                        } else {
                            format!("{prefix}.{name}")
                        };
                        if spec.get("type").and_then(Value::as_str) == Some("alias") {
                            if let Some(path) = spec.get("path").and_then(Value::as_str) {
                                out.entry(full.clone()).or_insert_with(|| path.to_string());
                            }
                        }
                        if let Some(nested_props) = spec.get("properties") {
                            collect_aliases(nested_props, &full, out);
                        }
                    }
                }
                let props = mapping
                    .pointer("/mappings/properties")
                    .or_else(|| mapping.pointer("/properties"));
                if let Some(p) = props {
                    collect_aliases(p, "", &mut m);
                }
            }
        }
        m
    };
    if !alias_map.is_empty() {
        // Rewrite field names in the body's interesting shapes.
        fn rewrite_field_name(
            s: &str,
            aliases: &std::collections::HashMap<String, String>,
        ) -> String {
            aliases.get(s).cloned().unwrap_or_else(|| s.to_string())
        }
        fn rewrite_leaf_field_values(
            v: &mut Value,
            aliases: &std::collections::HashMap<String, String>,
        ) {
            match v {
                Value::Object(obj) => {
                    // Special handling: for `term/range/match/exists/prefix/etc.`
                    // the key at the object's level is the field name; we
                    // rename the key if it's an alias.
                    let keys: Vec<String> = obj.keys().cloned().collect();
                    for k in keys {
                        if let Some(target) = aliases.get(&k).cloned() {
                            if !obj.contains_key(&target) {
                                let v = obj.remove(&k).unwrap();
                                obj.insert(target, v);
                            }
                        }
                    }
                    // Also rewrite explicit "field" / "path" string fields
                    // inside aggs, composite sources, and sort specs.
                    if let Some(f) = obj.get_mut("field") {
                        if let Some(s) = f.as_str() {
                            *f = Value::String(rewrite_field_name(s, aliases));
                        }
                    }
                    for (_, child) in obj.iter_mut() {
                        rewrite_leaf_field_values(child, aliases);
                    }
                }
                Value::Array(arr) => {
                    for item in arr {
                        rewrite_leaf_field_values(item, aliases);
                    }
                }
                _ => {}
            }
        }
        if let Some(q) = body.query.as_mut() {
            rewrite_leaf_field_values(q, &alias_map);
        }
        if let Some(s) = body.sort.as_mut() {
            rewrite_leaf_field_values(s, &alias_map);
        }
        if let Some(a) = body.aggs.as_mut() {
            rewrite_leaf_field_values(a, &alias_map);
        }
        if let Some(a) = body.aggregations.as_mut() {
            rewrite_leaf_field_values(a, &alias_map);
        }
        // Note: we intentionally do NOT rewrite `body.fields` or
        // `body.collapse` — both are per-index-dependent. The response
        // layer applies alias resolution at fetch time (`body.fields`)
        // and per-index search dispatch rewrites `collapse.field` only
        // when the current index actually defines the alias (further
        // below — see `per_index_collapse_rewrite`).
    }

    // Enforce per-index `index.disable_sequence_numbers` setting:
    // reject queries/sorts that touch `_seq_no` with ES's specific
    // error messages.
    let any_disabled_seqno = participating_indices.iter().any(|ix| {
        state
            .engine
            .index_settings
            .get(ix)
            .map(|v| {
                let s = v.clone();
                let as_bool = |val: &Value| -> bool {
                    val.as_bool()
                        .unwrap_or_else(|| val.as_str().map(|x| x == "true").unwrap_or(false))
                };
                s.pointer("/index/disable_sequence_numbers")
                    .map(as_bool)
                    .unwrap_or(false)
                    || s.get("index")
                        .and_then(|i| i.get("index.disable_sequence_numbers"))
                        .map(as_bool)
                        .unwrap_or(false)
                    || s.get("index.disable_sequence_numbers")
                        .map(as_bool)
                        .unwrap_or(false)
            })
            .unwrap_or(false)
    });
    if any_disabled_seqno {
        fn mentions_seq_no(v: &Value) -> bool {
            match v {
                Value::Object(obj) => {
                    // `term: {_seq_no: ...}` / `range: {_seq_no: ...}`
                    for leaf in ["term", "range", "terms", "match"] {
                        if let Some(body) = obj.get(leaf).and_then(|x| x.as_object()) {
                            if body.contains_key("_seq_no") {
                                return true;
                            }
                        }
                    }
                    obj.values().any(mentions_seq_no)
                }
                Value::Array(arr) => arr.iter().any(mentions_seq_no),
                _ => false,
            }
        }
        if let Some(q) = body.query.as_ref() {
            if mentions_seq_no(q) {
                let reason = "failed to create query: Cannot query field [_seq_no]: _seq_no cannot be queried when [index.disable_sequence_numbers] is [true]";
                return ApiError::new(xerj_common::XerjError::invalid_query(reason))
                    .into_response();
            }
        }
        // Sort by `_seq_no` → illegal_argument_exception (NOT query_shard).
        fn sort_mentions_seq_no(v: &Value) -> bool {
            match v {
                Value::Object(obj) => obj.contains_key("_seq_no"),
                Value::Array(arr) => arr.iter().any(sort_mentions_seq_no),
                Value::String(s) => s == "_seq_no",
                _ => false,
            }
        }
        if let Some(sort) = body.sort.as_ref() {
            if sort_mentions_seq_no(sort) {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "root_cause": [{
                                "type": "illegal_argument_exception",
                                "reason": "Cannot query field [_seq_no]: _seq_no cannot be queried when [index.disable_sequence_numbers] is [true]"
                            }],
                            "type": "search_phase_execution_exception",
                            "reason": "all shards failed",
                        },
                        "status": 400,
                    })),
                ).into_response();
            }
        }
    }

    // `rerank` widened the engine's page to `rerank.window`, so the engine's
    // own `from + size > max_result_window` check would fire on a page size
    // the caller never sent (they asked for `size: 5`, the stage asked the
    // engine for 30). Say it in the caller's terms, per index, before the
    // engine runs — a wildcard search tripped on one small index the same way.
    if let Some(plan) = &rerank_plan {
        for ix in &participating_indices {
            let max_w = index_max_result_window(&state, ix);
            if plan.window() > max_w {
                let reason = format!(
                    "`rerank.window` ({}) exceeds `index.max_result_window` ({max_w}) on \
                     `{ix}`: the stage judges that many of the engine's top hits, so the \
                     engine must be able to return them. Lower `rerank.window` or raise \
                     the index setting",
                    plan.window()
                );
                crate::rerank_stage::record_refused(&state.metrics);
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "root_cause": [{
                                "type": "illegal_argument_exception",
                                "reason": reason,
                            }],
                            "type": "illegal_argument_exception",
                            "reason": reason,
                        },
                        "status": 400,
                    })),
                )
                    .into_response();
            }
        }
    }

    // Enforce per-index `index.max_result_window` for `ids` clauses.
    // ES rejects queries whose `ids.values` list is longer than the
    // index's configured max_result_window (default 10000).
    for ix in &participating_indices {
        let max_w = index_max_result_window(&state, ix);
        fn max_ids_in_json(q: &Value) -> usize {
            match q {
                Value::Object(obj) => {
                    let mut m = 0;
                    if let Some(ids) = obj
                        .get("ids")
                        .and_then(|v| v.get("values"))
                        .and_then(Value::as_array)
                    {
                        m = m.max(ids.len());
                    }
                    for (_, v) in obj {
                        m = m.max(max_ids_in_json(v));
                    }
                    m
                }
                Value::Array(arr) => arr.iter().map(max_ids_in_json).max().unwrap_or(0),
                _ => 0,
            }
        }
        if let Some(q) = body.query.as_ref() {
            if max_ids_in_json(q) > max_w {
                let reason = format!(
                    "failed to create query: Too many ids specified, allowed max result window is [{}]",
                    max_w
                );
                return ApiError::new(xerj_common::XerjError::invalid_query(reason))
                    .into_response();
            }
        }
    }

    // Enforce per-index `index.max_script_fields` (default 32). ES rejects a
    // search requesting more script_fields than the limit before executing it.
    if let Some(n) = body
        .script_fields
        .as_ref()
        .and_then(Value::as_object)
        .map(|o| o.len())
    {
        for ix in &participating_indices {
            let max_sf = state
                .engine
                .index_settings
                .get(ix)
                .map(|v| v.clone())
                .and_then(|s| {
                    let as_int = |v: &Value| {
                        v.as_u64()
                            .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                    };
                    s.pointer("/index/max_script_fields")
                        .and_then(as_int)
                        .or_else(|| {
                            s.get("index")
                                .and_then(|i| i.get("index.max_script_fields"))
                                .and_then(as_int)
                        })
                        .or_else(|| s.get("index.max_script_fields").and_then(as_int))
                })
                .map(|v| v as usize)
                .unwrap_or(32);
            if n > max_sf {
                let reason = format!(
                    "Trying to retrieve too many script_fields. Must be less than or equal to: \
                     [{max_sf}] but was [{n}]. This limit can be set by changing the \
                     [index.max_script_fields] index level setting."
                );
                return ApiError::new(xerj_common::XerjError::invalid_query(reason))
                    .into_response();
            }
        }
    }

    // Per-index request limits ES enforces before executing a search
    // (`search/30_limits.yml`): result window / scroll batch size, rescore
    // window, docvalue_fields count, regex and prefix length.
    for ix in &participating_indices {
        if let Some(reason) = find_index_request_limit_violation(
            &state,
            ix,
            &body,
            requested_from,
            scroll_page_size,
            is_scroll_request,
        ) {
            return ApiError::new(xerj_common::XerjError::invalid_query(reason)).into_response();
        }
    }

    // Request-cache tracking: ES's shard request cache is on by
    // default for cache-eligible searches (size:0 + aggs), so we
    // record hit/miss counters per participating index unless the
    // caller explicitly sets `request_cache=false`. Only the
    // `indices.stats · request_cache` numbers read these counters.
    let rc_enabled =
        body.size == 0 && body.aggs.is_some() && params.request_cache.as_deref() != Some("false");
    if rc_enabled {
        let body_hash = {
            use std::collections::hash_map::DefaultHasher;
            use std::hash::{Hash, Hasher};
            // EsSearchBody doesn't impl Serialize; reconstruct a canonical
            // representation from the fields we care about for cache-key
            // uniqueness (query + aggs + source filter + size).
            let q = body
                .query
                .as_ref()
                .map(|v| v.to_string())
                .unwrap_or_default();
            let a = body
                .aggs
                .as_ref()
                .map(|v| v.to_string())
                .unwrap_or_default();
            let ag = body
                .aggregations
                .as_ref()
                .map(|v| v.to_string())
                .unwrap_or_default();
            let s = body
                .source
                .as_ref()
                .map(|v| v.to_string())
                .unwrap_or_default();
            let body_str = format!("{}|{}|{}|{}|{}|{}", q, a, ag, s, body.size, body.from);
            let mut h = DefaultHasher::new();
            body_str.hash(&mut h);
            h.finish()
        };
        for idx_name in &index_names {
            if let Ok(idx) = state.engine.get_index(idx_name.as_ref()) {
                idx.track_request_cache(body_hash);
            }
        }
    }
    // Merge `aggs` and `aggregations` keys — ES clients may use either.
    // Cloned AFTER the terms-lookup resolution so the substituted values
    // flow through the parser.
    let aggs_value = body.aggs.clone().or_else(|| body.aggregations.clone());

    // `value_type` shard-failure detection: walk every terms/numeric agg
    // in the request and, for each participating index, check whether the
    // declared `value_type` (e.g. "ip", "long") conflicts with the field
    // mapping in THAT index. A conflict causes the shard to fail: the
    // index is excluded from search + agg merge and `_shards.failed`
    // is bumped. ES's own `value_type` behaviour returns a shard failure
    // when a coerced-IP read finds a non-IP string (like a keyword IP
    // written into a keyword-mapped field).
    let mut shards_failed_count: u32 = 0;
    let mut value_type_failed_indices: std::collections::HashSet<String> =
        std::collections::HashSet::new();
    if let Some(aggs) = aggs_value.as_ref() {
        fn collect_value_types(v: &Value, out: &mut Vec<(String, String)>) {
            let Some(obj) = v.as_object() else { return };
            for (_name, body) in obj.iter() {
                let Some(body_obj) = body.as_object() else {
                    continue;
                };
                for (agg_type, spec) in body_obj.iter() {
                    if matches!(agg_type.as_str(), "aggs" | "aggregations" | "meta") {
                        continue;
                    }
                    if let Some(spec_obj) = spec.as_object() {
                        if let (Some(field), Some(vt)) = (
                            spec_obj.get("field").and_then(Value::as_str),
                            spec_obj.get("value_type").and_then(Value::as_str),
                        ) {
                            out.push((field.to_string(), vt.to_string()));
                        }
                    }
                }
                // Recurse into sub-aggs
                if let Some(subs) = body_obj
                    .get("aggs")
                    .or_else(|| body_obj.get("aggregations"))
                {
                    collect_value_types(subs, out);
                }
            }
        }
        let mut vts: Vec<(String, String)> = Vec::new();
        collect_value_types(aggs, &mut vts);
        if !vts.is_empty() {
            for idx_name in index_names.iter() {
                let name_str: &str = idx_name;
                let Some(mapping_ref) = state.engine.index_mappings.get(name_str) else {
                    continue;
                };
                let mapping = mapping_ref.value().clone();
                drop(mapping_ref);
                for (field, vt) in &vts {
                    let field_type = mapping
                        .pointer(&format!("/mappings/properties/{}/type", field))
                        .or_else(|| mapping.pointer(&format!("/properties/{}/type", field)))
                        .and_then(Value::as_str)
                        .unwrap_or("");
                    let incompatible = match (vt.as_str(), field_type) {
                        ("ip", ft) if !ft.is_empty() && ft != "ip" => true,
                        ("long" | "integer" | "short" | "byte" | "double" | "float", ft)
                            if !ft.is_empty()
                                && !matches!(
                                    ft,
                                    "long"
                                        | "integer"
                                        | "short"
                                        | "byte"
                                        | "double"
                                        | "float"
                                        | "half_float"
                                        | "scaled_float"
                                        | "unsigned_long"
                                ) =>
                        {
                            true
                        }
                        _ => false,
                    };
                    if incompatible {
                        value_type_failed_indices.insert(name_str.to_string());
                        break;
                    }
                }
            }
            shards_failed_count += value_type_failed_indices.len() as u32;
        }
    }
    let index_names: Vec<&str> = index_names
        .into_iter()
        .filter(|n| !value_type_failed_indices.contains(*n))
        .collect();

    let mut search_req = match build_search_request(&body, aggs_value) {
        Ok(mut r) => {
            // ES 7.16 leaf ordering for the implicit auto-@timestamp hint
            // (see the injection block above) — internal field, never on
            // the wire.
            r.leaf_ts_field = implicit_leaf_ts;
            // xerj extension `?savings=` — `_source` savings measurement, on
            // by default. Internal field, never echoed on the wire.
            r.savings = parse_savings_mode(params.savings.as_deref());
            r
        }
        Err(e) => return ApiError::new(e).into_response(),
    };

    // ── The default `_source` projection, and who has to see past it (#310) ──
    //
    // Since #309 a request with no `_source` clause gets `SourceFilter::Default`
    // and the engine drops the generated embedding companions before the
    // response layer ever sees a hit. But `_source` is not the only consumer of
    // the stored document: `fields` and `docvalue_fields` resolve their values
    // out of that same `hit.source`, AFTER the projection has narrowed it. So
    // `{"fields": ["body_vector"]}` came back with nothing — silently, because an
    // unresolvable `fields` entry is legally omitted — while the very same clause
    // under `"_source": false` returned the whole vector, since `Enabled(false)`
    // deliberately keeps the raw source for exactly this resolution. Two spellings
    // of "I do not want `_source`", opposite answers.
    //
    // The fix: if a caller named a companion in `fields`/`docvalue_fields` and
    // wrote no `_source` clause, ask the engine for the intact source and narrow
    // it back to the default at each emission site below. Wire bytes are
    // unchanged; the caller gets the value they explicitly asked for. Decided in
    // the API (the only layer that sees the `fields` clause), not the engine —
    // teaching the engine to treat `Default` as `Enabled(true)` would put
    // companions back into every internal `SearchRequest::default()`.
    let default_source_projection = body.source.is_none();
    // Computed for BOTH projections (#932): for the default projection these
    // names drive the companion pierce below; for an explicit narrowing
    // filter they drive the explicit-filter pierce further down.
    let value_bearing_names = value_bearing_field_names(&body, &search_req.fields);
    // One schema read-lock per participating index, and only for a request that
    // could actually consume the answer: a pierce (a companion named in
    // `fields`/`docvalue_fields`) OR a collapse `inner_hits` block, whose members
    // are stashed before the #309 projection and would otherwise ship the
    // companions on the wire (#646).
    let mut companions_by_index: HashMap<String, HashSet<String>> = HashMap::new();
    if default_source_projection && (!value_bearing_names.is_empty() || body.collapse.is_some()) {
        for idx_name in &index_names {
            let Ok(idx) = state.engine.get_index(idx_name) else {
                continue;
            };
            let companions = idx.embedding_companion_fields().await;
            if !companions.is_empty() {
                companions_by_index.insert((*idx_name).to_string(), companions);
            }
        }
    }
    // The pierce, and the obligation it creates: every site that emits a
    // `_source` for this response must undo it (top-level hit, collapse
    // `inner_hits`, scroll snapshot).
    let pierce_default_source = value_bearing_names
        .iter()
        .any(|f| companions_by_index.values().any(|c| c.contains(f)));
    if pierce_default_source {
        search_req.source = xerj_query::ast::SourceFilter::Enabled(true);
    }

    // ── #932: an EXPLICIT `_source` filter has the same blind spot ──
    //
    // A narrowing filter — `_source: ["title"]`, the object spelling, and
    // the URL spellings (`?_source=`, `?_source_includes=`, all promoted
    // into body.source above) — is applied by the ENGINE
    // (`apply_source_filter`), which narrows `hit.source` before the
    // response layer runs. `fields` and `docvalue_fields` resolve out of
    // that same narrowed source, so `{"_source": ["title"], "fields":
    // ["body"]}` legally omitted `fields.body`: a 200, no warning, nothing.
    // The #310 pierce above cannot fire here — it is keyed on
    // `default_source_projection`.
    //
    // Same fix, second path: when the caller's own includes/excludes drop a
    // value-bearing name, ask the engine for the intact source
    // (`Enabled(true)` — the shape `"_source": false` already uses for
    // exactly this resolution) and re-apply the caller's filter at every
    // `_source` emission site below. Unlike #310 this is not
    // companion-gated: the field being dropped is the caller's own, text or
    // keyword alike. A filter that already selects every named field does
    // not pierce at all — its engine-side narrowing (and its `_savings`
    // note) stays exactly as it was.
    let pierce_explicit_source: Option<(Vec<String>, Vec<String>)> =
        if !default_source_projection && !value_bearing_names.is_empty() {
            match &search_req.source {
                xerj_query::ast::SourceFilter::Includes(includes) => {
                    source_filter_drops_a_name(includes, &[], &value_bearing_names)
                        .then(|| (includes.clone(), Vec::new()))
                }
                xerj_query::ast::SourceFilter::Fields { includes, excludes } => {
                    source_filter_drops_a_name(includes, excludes, &value_bearing_names)
                        .then(|| (includes.clone(), excludes.clone()))
                }
                // `Enabled(true)` narrows nothing; `Enabled(false)` keeps the
                // raw source on purpose (suppression is a response-time
                // decision); `Default` never carries an explicit filter.
                _ => None,
            }
        } else {
            None
        };
    if pierce_explicit_source.is_some() {
        search_req.source = xerj_query::ast::SourceFilter::Enabled(true);
    }
    let search_req = search_req;

    // Execute search on each index and merge results.
    let mut merged_hits: Vec<(String, xerj_query::executor::Hit)> = Vec::new(); // (index_name, hit)

    // Per-(index, doc id) omitted bytes, re-summed after the merge below over
    // the hits this response ACTUALLY emits. The engine measured a per-index
    // page; multi-index merging, PIT filtering, kNN capping and collapse can
    // all drop hits from it afterwards, and counting a dropped hit's bytes
    // would inflate the number.
    let mut savings_by_hit: HashMap<(String, String), u64> = HashMap::new();
    let mut savings_record: Option<xerj_query::executor::PayloadSavings> = None;
    let mut total_count: u64 = 0;
    let mut total_relation = "eq".to_string();
    let mut merged_aggs: Option<Value> = None;
    // Population max score across ALL matched docs (pre-collapse) merged from
    // each per-index result, so collapse+track_scores reports ES `max_score`.
    let mut merged_population_max: Option<f64> = None;
    let mut any_timed_out = false;

    // Request-level index-resolution policy. Wildcards default to silently
    // skipping missing indices; literal names 404 unless the caller opted
    // in to `ignore_unavailable=true`.
    let search_ignore_unavailable = params.ignore_unavailable.as_deref() == Some("true");
    let search_selector_has_wildcard = index
        .split(',')
        .map(str::trim)
        .any(|p| p == "_all" || p == "*" || p.contains('*'));
    let search_allow_no_indices = params
        .allow_no_indices
        .as_deref()
        .map(|v| v == "true")
        .unwrap_or(search_selector_has_wildcard);

    // #875: this fan-out used to execute serially — spawn one search task,
    // await it, merge, then move to the next index — so a wildcard search
    // over N datasets cost ~N × single-index latency (measured: 701 ms over
    // 41 autoindex datasets vs 11.7 ms against one of them). Phase 1 below
    // spawns every per-index search up front; per-index request prep stays
    // serial because it is sync map lookups. Actual concurrency is bounded
    // by the engine's global search permit (`Index::search` acquires
    // `governor.acquire_search`, sized by `limits.max_concurrent_searches`),
    // and excess searches queue on that semaphore deadline-aware exactly as
    // they did when this loop issued them one at a time.
    let mut spawned_searches = Vec::with_capacity(index_names.len());
    // Only used when an in-process caller asked to have failing indices skipped.
    let mut skipped = SkippedIndices::default();
    // #2305: wildcard / `_all` / alias members with no `semantic_text` field.
    let mut semantic_skips = ExpandedSemanticSkips::default();
    let search_node = state.engine.node_id.clone();
    for idx_name in &index_names {
        let idx = match state.engine.get_index(idx_name) {
            Ok(i) => i,
            Err(e) => {
                if search_ignore_unavailable || search_allow_no_indices {
                    // Silently skip; behaves like an empty index.
                    continue;
                }
                if in_process.skip_failed_indices {
                    // An index that is listed but cannot be opened is one bad
                    // index, not a reason to refuse the rest.
                    tracing::warn!(
                        index = %idx_name,
                        error = ?e.to_string().chars().take(300).collect::<String>(),
                        "in-process search: index unavailable, skipping it"
                    );
                    skipped.attempt();
                    skipped.skip(|| ApiError::new(xerj_common::XerjError::from(e)).into_response());
                    shards_failed_count += 1;
                    continue;
                }
                let mut api_err = ApiError::new(xerj_common::XerjError::from(e));
                // Byte-parity `reason` ("no such index [name]") is fixed by
                // ES-compat tests and set unconditionally in `error.rs` — this
                // only adds the additive `_xerj` hint alongside it.
                if matches!(api_err.inner, xerj_common::XerjError::IndexNotFound { .. }) {
                    let available = state.engine.index_name_list();
                    api_err = api_err.with_hint(index_not_found_hint(idx_name, &available));
                }
                return api_err.into_response();
            }
        };

        // RC4-W4 item 5: record the per-index query metric only AFTER the index
        // resolves. Incrementing before resolution let a query against a
        // nonexistent index (`no_such_index_xyz`) mint a
        // `queries_by_index{index="no_such_index_xyz"}` label series that
        // lived forever — an unbounded-cardinality leak driven by client input.
        state
            .metrics
            .queries_by_index
            .with_label_values(&[idx_name])
            .inc();

        let mut req_clone = search_req.clone();
        // PIT search: fetch more hits per-index so the post-merge PIT
        // filter can drop post-snapshot docs without starving the page.
        // Without this bump, size:1 + PIT would see a single hit get
        // dropped and return 0 results.
        if pit_context.is_some() {
            req_clone.size = req_clone
                .size
                .saturating_add(req_clone.from)
                .saturating_mul(4)
                .max(100);
            req_clone.from = 0;
        }
        // Per-index alias rewrite for collapse.field: if the declared
        // field name is an alias in THIS index's mapping, swap in the
        // alias target; otherwise leave the name as-is so indices that
        // store the field directly still collapse correctly.
        if let Some(cs) = req_clone.collapse.as_mut() {
            if let Some(mapping) = state.engine.index_mappings.get(*idx_name) {
                let props = mapping
                    .pointer("/mappings/properties")
                    .or_else(|| mapping.pointer("/properties"));
                if let Some(p) = props.and_then(Value::as_object) {
                    if let Some(field_spec) = p.get(&cs.field).and_then(Value::as_object) {
                        if field_spec.get("type").and_then(Value::as_str) == Some("alias") {
                            if let Some(tgt) = field_spec.get("path").and_then(Value::as_str) {
                                cs.field = tgt.to_string();
                            }
                        }
                    }
                }
            }
        }
        // Keep search work owned by the request future. Dropping the handler
        // (for example when the client disconnects) aborts the child task;
        // awaiting its JoinHandle also converts executor panics into HTTP 500
        // instead of unwinding through axum.
        //
        // No `index_guard` rule is carried across this spawn, and does not need
        // to be: the task closes over `idx`, an `Index` handle the guarded
        // request already resolved and was authorized for, and an `Index` holds
        // no `Engine`, so nothing inside can name a second index. The two ways
        // a search body *does* name another index — a `terms` lookup and a
        // `lookup` runtime field — are both resolved earlier in this function,
        // on the request's own task (`resolve_terms_lookups`), under the guard.
        #[cfg(test)]
        let inject_task_panic = *idx_name == "test-panic-search-task";
        #[cfg(test)]
        let inject_pending_task = idx_name.starts_with("test-pending-search-task");
        let search_task = AbortOnDrop(tokio::spawn(async move {
            #[cfg(test)]
            if inject_task_panic {
                panic!("injected search task panic");
            }
            #[cfg(test)]
            if inject_pending_task {
                let (started, dropped) = TEST_PENDING_SEARCH_SIGNALS
                    .get_or_init(|| std::sync::Mutex::new(Vec::new()))
                    .lock()
                    .expect("pending-search signals lock")
                    .pop()
                    .expect("pending-search signals");
                let _ = started.send(());
                let _drop_signal = SignalOnDrop(Some(dropped));
                std::future::pending().await
            }
            idx.search(&req_clone).await
        }));
        skipped.attempt();
        spawned_searches.push((idx_name, search_task));
    }

    // #875 phase 2 — await and merge in the SAME deterministic index order
    // the serial loop used, so hit ordering and agg-merge order are
    // unchanged. An early error return drops the remaining `AbortOnDrop`
    // handles, aborting their still-running searches.
    for (idx_name, mut search_task) in spawned_searches {
        let search_result = (&mut search_task.0).await;
        semantic_skips.note_attempt();

        match search_result {
            Err(join_err) => {
                if in_process.skip_failed_indices {
                    tracing::warn!(index = %idx_name, "in-process search: index search panicked, skipping it");
                    skipped.skip(|| search_task_panic_response(join_err, idx_name));
                    shards_failed_count += 1;
                    continue;
                }
                return search_task_panic_response(join_err, idx_name);
            }
            Ok(Err(e)) => {
                if in_process.skip_failed_indices {
                    // The engine's own words can quote the query; bound and
                    // escape them before they reach the log.
                    tracing::warn!(
                        index = %idx_name,
                        error = ?e.to_string().chars().take(300).collect::<String>(),
                        "in-process search: index search failed, skipping it"
                    );
                    skipped.skip(|| ApiError::new(xerj_common::XerjError::from(e)).into_response());
                    shards_failed_count += 1;
                    continue;
                }
                // #2305: a wildcard, `_all`, or alias member with no
                // `semantic_text` field for this query contributes no hits.
                // A concrete name in the selector still fails the request.
                let err = xerj_common::XerjError::from(e);
                match semantic_skips.take_skippable(&index, idx_name, search_node.as_str(), err) {
                    Ok(()) => {
                        shards_failed_count += 1;
                        continue;
                    }
                    Err(err) => return ApiError::new(err).into_response(),
                }
            }
            Ok(Ok(result)) => {
                // A Painless resource limit tripped somewhere in scoring or
                // aggregation. Those paths have no error channel, so they
                // fell back to neutral values — the hits below carry wrong
                // scores. Fail the request instead of serving them.
                if let Some(reason) = &result.script_failure {
                    return script_limit_response(reason);
                }
                if result.timed_out {
                    any_timed_out = true;
                }
                total_count += result.total.value;
                if result.total.relation == xerj_query::executor::TotalHitsRelation::Gte {
                    total_relation = "gte".to_string();
                }
                if let Some(ms) = result.max_score {
                    merged_population_max =
                        Some(merged_population_max.map_or(ms as f64, |m: f64| m.max(ms as f64)));
                }
                if let Some(new_aggs) = result.aggs {
                    match &mut merged_aggs {
                        None => merged_aggs = Some(new_aggs),
                        Some(existing) => {
                            if let (Some(ex_obj), Some(new_obj)) =
                                (existing.as_object_mut(), new_aggs.as_object())
                            {
                                for (k, v) in new_obj {
                                    // Metric-agg aware merge: when both shards
                                    // returned a metric result with internal
                                    // tracking, recombine the primitives so
                                    // `avg/sum/min/max` reflect the union
                                    // across indices rather than just the
                                    // first index's value.
                                    if let Some(old) = ex_obj.get(k).cloned() {
                                        if let Some(merged) = merge_metric_agg(&old, v) {
                                            ex_obj.insert(k.clone(), merged);
                                            continue;
                                        }
                                        if let Some(merged) = merge_bucket_agg(&old, v) {
                                            ex_obj.insert(k.clone(), merged);
                                            continue;
                                        }
                                        if let Some(merged) = merge_single_bucket_agg(&old, v) {
                                            ex_obj.insert(k.clone(), merged);
                                            continue;
                                        }
                                    }
                                    let should_replace = match (ex_obj.get(k), v) {
                                        (Some(old), new) => {
                                            let old_empty = old
                                                .get("buckets")
                                                .and_then(|b| b.as_array())
                                                .map(|a| a.is_empty())
                                                .unwrap_or(false);
                                            let new_has_data = new
                                                .get("buckets")
                                                .and_then(|b| b.as_array())
                                                .map(|a| !a.is_empty())
                                                .unwrap_or(false);
                                            old_empty && new_has_data
                                        }
                                        (None, _) => true,
                                    };
                                    if should_replace {
                                        ex_obj.insert(k.clone(), v.clone());
                                    }
                                }
                            }
                        }
                    }
                }
                if let Some(savings) = result.savings {
                    for (id, bytes) in &savings.per_hit {
                        savings_by_hit.insert((idx_name.to_string(), id.clone()), *bytes);
                    }
                    savings_record.get_or_insert(savings);
                }
                for hit in result.hits {
                    merged_hits.push((idx_name.to_string(), hit));
                }
            }
        }
    }

    // Skipping a bad index is isolation, not a way to hide an outage: when every
    // index that was tried failed there is nothing to answer from, and the first
    // failure is the answer.
    if let Some(failure) = skipped.all_failed() {
        return failure;
    }
    // #2305: a pattern that matched only indices without the semantic field
    // is the same 400 an explicit index would return — an empty 200 would
    // hide a wrong field name. A mix (some indices have the field) falls
    // through and answers from those.
    if let Some(err) = semantic_skips.failure_if_every_index_skipped() {
        return ApiError::new(err).into_response();
    }

    // ── Post-merge `auto_date_histogram` re-coordination ────────────────────
    // Each per-shard run chose its own interval against its local min/max,
    // so a two-shard search with one doc per shard can end up with two
    // shards independently picking `1ms` (span=0 locally). ES's coordinator
    // picks ONE interval across the global min/max; mirror that here by
    // scanning the merged bucket keys, re-selecting the interval, and
    // rebucketing at the coarser grid.
    if let Some(aggs_req) = body.aggs.as_ref().or(body.aggregations.as_ref()) {
        if let Some(m) = merged_aggs.as_mut() {
            rebucket_auto_date_histograms(m, aggs_req);
        }
    }

    // Apply slice filter: when `max > 1`, partition hits deterministically
    // by id using ES's Murmur3 routing hash → shard → slice mapping. xerj
    // is single-shard but `_shards.successful` responds with the requested
    // number_of_shards; slice partitioning uses `shard_for(_id) % max` with
    // ES's `number_of_shards` (from index settings) for consistency.
    if let Some(slice_v) = body.slice.as_ref() {
        let slice_id = slice_v.get("id").and_then(|v| {
            v.as_i64()
                .or_else(|| v.as_str().and_then(|s| s.parse::<i64>().ok()))
        });
        let slice_max = slice_v.get("max").and_then(|v| {
            v.as_i64()
                .or_else(|| v.as_str().and_then(|s| s.parse::<i64>().ok()))
        });
        let slice_field = slice_v
            .get("field")
            .and_then(|v| v.as_str())
            .unwrap_or("_id")
            .to_string();
        if let (Some(id), Some(max)) = (slice_id, slice_max) {
            if max > 0 && id >= 0 && id < max {
                // Compute number_of_shards from the first participating index's settings.
                let shards: u32 = index_names
                    .first()
                    .and_then(|n| {
                        let nn: &str = n;
                        state
                            .engine
                            .index_settings
                            .get(nn)
                            .map(|r| r.value().clone())
                    })
                    .and_then(|s| {
                        s.pointer("/index/number_of_shards")
                            .or_else(|| s.pointer("/number_of_shards"))
                            .and_then(|n| {
                                n.as_i64()
                                    .or_else(|| n.as_str().and_then(|s| s.parse::<i64>().ok()))
                            })
                            .map(|n| n as u32)
                    })
                    .unwrap_or(1);
                let slice_by_id = slice_field == "_id";
                let mut kept: Vec<(String, xerj_query::executor::Hit)> =
                    Vec::with_capacity(merged_hits.len());
                for (idx_name, h) in merged_hits.drain(..) {
                    let key = if slice_by_id {
                        h.id.clone()
                    } else if let Ok(idx) = state.engine.get_index(&idx_name) {
                        let doc = idx.get_document(&h.id).await.ok().flatten();
                        doc.as_ref()
                            .and_then(|d| d.get(&slice_field))
                            .map(|v| match v {
                                Value::String(s) => s.clone(),
                                other => other.to_string(),
                            })
                            .unwrap_or_default()
                    } else {
                        String::new()
                    };
                    let shard = murmur3_routing_shard(&key, shards);
                    let in_slice = if (max as u32) <= shards {
                        (shard % (max as u32)) as i64 == id
                    } else {
                        // More slices than shards → subdivide each shard
                        // by id hash. Shard S gets slices [S*max/shards .. (S+1)*max/shards).
                        let slices_per_shard = (max as u32) / shards;
                        let start = shard * slices_per_shard;
                        let end = if shard == shards - 1 {
                            max as u32
                        } else {
                            (shard + 1) * slices_per_shard
                        };
                        if (id as u32) >= start && (id as u32) < end {
                            // Sub-slice by id hash within the shard's slice range.
                            let mut hasher = std::collections::hash_map::DefaultHasher::new();
                            use std::hash::Hasher;
                            hasher.write(key.as_bytes());
                            let h64 = hasher.finish();
                            let sub = (h64 % (end - start) as u64) as u32 + start;
                            (sub as i64) == id
                        } else {
                            false
                        }
                    };
                    if in_slice {
                        kept.push((idx_name, h));
                    }
                }
                let kept_len = kept.len() as u64;
                merged_hits = kept;
                total_count = kept_len;
            }
        }
    }

    // Apply min_score: drop hits whose _score is below the threshold.
    // ES applies this before pagination AND before counting — total
    // also reflects only the surviving docs.
    if let Some(min_score) = body.min_score {
        let before = merged_hits.len();
        merged_hits.retain(|(_, h)| (h.score as f64) >= min_score);
        let dropped = before - merged_hits.len();
        total_count = total_count.saturating_sub(dropped as u64);
    }

    // Apply PIT filter: drop every merged hit whose seq_no was assigned
    // AFTER the PIT snapshot. For `total_count` we subtract the number
    // of docs in the snapshot indexes that arrived after the snapshot
    // (so per-index totals stay correct even when `size` truncated the
    // returned hits).
    if let Some(pit) = pit_context.as_ref() {
        let mut kept: Vec<(String, xerj_query::executor::Hit)> = Vec::new();
        let mut filtered_out_in_page = 0u64;
        for (idx_name, h) in merged_hits.drain(..) {
            let max_seq = pit
                .index_max_seq
                .get(&idx_name)
                .copied()
                .unwrap_or(u64::MAX);
            // Read from the hit itself — resolved at construction time in
            // the engine, from the same read as `_source` — rather than a
            // live re-lookup here (#440).
            let hit_seq = h.seq_no.unwrap_or(0);
            if hit_seq <= max_seq {
                kept.push((idx_name, h));
            } else {
                filtered_out_in_page += 1;
            }
        }
        merged_hits = kept;
        // Subtract the count of docs assigned seq_no's after the
        // snapshot — per index this is current_max_es_seq - snapshot.
        // current_es_seq = current_seq_no() - 2; adjust accordingly.
        let mut post_snapshot_docs: u64 = 0;
        for (idx_name, max_seq) in &pit.index_max_seq {
            if let Ok(idx) = state.engine.get_index(idx_name) {
                let cur = idx.current_seq_no().saturating_sub(2);
                let newer = cur.saturating_sub(*max_seq);
                post_snapshot_docs += newer;
            }
        }
        total_count = total_count.saturating_sub(post_snapshot_docs);
        let _ = filtered_out_in_page;
    }

    // Apply `indices_boost`: multiply each hit's score by the boost
    // registered for the hit's index name (or an alias that points at
    // it). `indices_boost` accepts either ES's canonical list-of-objects
    // form `[{"<idx>": <boost>}]` or the plain object `{<idx>: <boost>}`
    // shorthand some clients use.
    if let Some(ib) = body.indices_boost.as_ref() {
        let mut boosts: Vec<(String, f32)> = Vec::new();
        let push_pair = |arr: &mut Vec<(String, f32)>, k: &String, v: &Value| {
            if let Some(f) = v.as_f64() {
                arr.push((k.clone(), f as f32));
            }
        };
        match ib {
            Value::Array(arr) => {
                for entry in arr {
                    if let Some(o) = entry.as_object() {
                        for (k, v) in o {
                            push_pair(&mut boosts, k, v);
                        }
                    }
                }
            }
            Value::Object(o) => {
                for (k, v) in o {
                    push_pair(&mut boosts, k, v);
                }
            }
            _ => {}
        }
        if !boosts.is_empty() {
            // Resolve aliases AND wildcards in boost keys to concrete index
            // names. A boost registered against an alias applies to every
            // index behind it; a boost registered against a `*` pattern
            // applies to every matching index that participated in this
            // search.
            let participating: Vec<String> = index_names.iter().map(|s| s.to_string()).collect();
            let mut resolved: Vec<(String, f32)> = Vec::new();
            for (k, b) in &boosts {
                if let Some(backing) = state.engine.aliases.get(k) {
                    for real in backing.iter() {
                        resolved.push((real.clone(), *b));
                    }
                    continue;
                }
                if k.contains('*') {
                    for real in &participating {
                        if glob_match_simple(k, real) {
                            resolved.push((real.clone(), *b));
                        }
                    }
                    continue;
                }
                resolved.push((k.clone(), *b));
            }
            for (idx_name, hit) in merged_hits.iter_mut() {
                if let Some((_, boost)) = resolved.iter().find(|(n, _)| n == idx_name) {
                    hit.score *= boost;
                }
            }
        }
    }

    // Replace null sort values with the per-mapping numeric sentinel
    // (Int.MAX / Long.MAX for missing-Last; Int.MIN / Long.MIN for
    // missing-First). Done before the cross-index merge sort so docs
    // group correctly by their effective sort value.
    if !search_req.sort.is_empty() {
        for (idx_name, hit) in merged_hits.iter_mut() {
            let mapping_props = state
                .engine
                .index_mappings
                .get(idx_name.as_str())
                .and_then(|v| {
                    v.get("mappings")
                        .and_then(|m| m.get("properties"))
                        .or_else(|| v.get("properties"))
                        .cloned()
                });
            for (i, raw) in hit.sort.iter_mut().enumerate() {
                if !raw.is_null() {
                    continue;
                }
                let sf = match search_req.sort.get(i) {
                    Some(s) => s,
                    None => continue,
                };
                let ftype = mapping_props
                    .as_ref()
                    .and_then(|p| p.get(&sf.field))
                    .and_then(|fp| fp.get("type"))
                    .and_then(Value::as_str);
                let want_max = matches!(sf.missing, xerj_query::sort::SortMissing::Last);
                let sentinel: Option<i64> = match ftype {
                    Some("integer") | Some("short") | Some("byte") => {
                        if want_max {
                            Some(i32::MAX as i64)
                        } else {
                            Some(i32::MIN as i64)
                        }
                    }
                    Some("long") | Some("unsigned_long") => {
                        if want_max {
                            Some(i64::MAX)
                        } else {
                            Some(i64::MIN)
                        }
                    }
                    _ => None,
                };
                if let Some(s) = sentinel {
                    *raw = Value::Number(serde_json::Number::from(s));
                }
            }
        }
    }

    // Re-sort merged hits from multiple indices.
    if index_names.len() > 1 {
        if search_req.sort.is_empty() {
            // Default: by score descending.
            merged_hits.sort_by(|(_, a), (_, b)| {
                b.score
                    .partial_cmp(&a.score)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
        } else {
            merged_hits.sort_by(|(_, a), (_, b)| {
                xerj_query::sort::compare_sort_keys(&a.sort, &b.sort, &search_req.sort)
                    .then_with(|| a.id.cmp(&b.id))
            });
        }

        // Cross-index collapse merge: collapse field is resolved
        // per-index (aliased). Dedup leaders across indices by the
        // collapse-field value, keeping the first-sorted leader and
        // folding the rest of the group members into its
        // `__xy_collapse_group__` sentinel so `inner_hits` totals
        // reflect the merged group.
        if let Some(ref cf) = search_req.collapse {
            use std::collections::BTreeMap;
            let field = &cf.field;
            let mut first_by_key: BTreeMap<String, usize> = BTreeMap::new();
            let mut seen_keys: Vec<String> = Vec::new();
            let key_of = |src: &Value| -> String {
                // Try the declared field first; if not present (the
                // caller queried a per-index alias target), fall back
                // to a top-level alias-name scan via literal.
                let v = src.get(field).or_else(|| {
                    // Try each other known alias for this collapse
                    // field by searching the src for numeric-ish
                    // values. Simpler: iterate source keys that
                    // aren't meta and aren't the declared field.
                    src.as_object().and_then(|o| {
                        o.iter().find_map(|(k, v)| {
                            if k == field || k.starts_with('_') {
                                None
                            } else {
                                Some(v)
                            }
                        })
                    })
                });
                match v {
                    Some(Value::String(s)) => s.clone(),
                    Some(Value::Number(n)) => n.to_string(),
                    Some(Value::Bool(b)) => b.to_string(),
                    _ => String::new(),
                }
            };
            // Pass 1: find the first (sort-order) leader per key, AND
            // collect every other index's group members for that key
            // so the merged leader's `__xy_collapse_group__` reflects
            // the true cross-index group size. Without this, the
            // leader from index A drops index B's same-key members on
            // the floor — visible as `inner_hits.sub_hits.hits.total`
            // off by N when an alias resolves the collapse field to
            // a different stored field on a sibling index.
            let mut extra_members_by_key: BTreeMap<String, Vec<Value>> = BTreeMap::new();
            for (i, (_, h)) in merged_hits.iter().enumerate() {
                let k = key_of(&h.source);
                if k.is_empty() {
                    continue;
                }
                if !first_by_key.contains_key(&k) {
                    first_by_key.insert(k.clone(), i);
                    seen_keys.push(k);
                } else {
                    // Not the leader — fold this hit's group members
                    // into the bucket so the leader can absorb them.
                    if let Some(group) = h
                        .source
                        .as_object()
                        .and_then(|o| o.get("__xy_collapse_group__"))
                        .and_then(|v| v.as_array())
                    {
                        extra_members_by_key
                            .entry(k.clone())
                            .or_default()
                            .extend(group.iter().cloned());
                    }
                }
            }
            // Pass 2: if every hit has a key and we collapsed at
            // least one cross-index duplicate, rebuild merged_hits
            // to retain only the first leader per collapse key.
            let unique_keys = first_by_key.len();
            if unique_keys > 0 && unique_keys < merged_hits.len() {
                let mut kept: Vec<(String, xerj_query::executor::Hit)> = Vec::new();
                let mut inserted: std::collections::HashSet<String> =
                    std::collections::HashSet::new();
                for &idx in first_by_key.values() {
                    let (idx_name, h) = &merged_hits[idx];
                    let kk = key_of(&h.source);
                    if inserted.insert(kk.clone()) {
                        let mut leader = h.clone();
                        // Absorb dropped indices' group members.
                        if let Some(extras) = extra_members_by_key.get(&kk) {
                            if !extras.is_empty() {
                                if let Some(obj) = leader.source.as_object_mut() {
                                    let combined: Vec<Value> =
                                        match obj.remove("__xy_collapse_group__") {
                                            Some(Value::Array(mut a)) => {
                                                a.extend(extras.iter().cloned());
                                                a
                                            }
                                            _ => extras.clone(),
                                        };
                                    obj.insert(
                                        "__xy_collapse_group__".to_string(),
                                        Value::Array(combined),
                                    );
                                }
                            }
                        }
                        kept.push((idx_name.clone(), leader));
                    }
                    let _ = kk;
                }
                // Preserve the original sort order by re-sorting kept
                // against search_req.sort.
                if search_req.sort.is_empty() {
                    kept.sort_by(|(_, a), (_, b)| {
                        b.score
                            .partial_cmp(&a.score)
                            .unwrap_or(std::cmp::Ordering::Equal)
                    });
                } else {
                    kept.sort_by(|(_, a), (_, b)| {
                        xerj_query::sort::compare_sort_keys(&a.sort, &b.sort, &search_req.sort)
                            .then_with(|| a.id.cmp(&b.id))
                    });
                }
                merged_hits = kept;
            }
        }

        // Apply from/size across merged results.
        let from = search_req.from;
        let size = search_req.size;
        if size == 0 {
            merged_hits.clear();
        } else {
            let end = (from + size).min(merged_hits.len());
            let start = from.min(merged_hits.len());
            merged_hits = merged_hits[start..end].to_vec();
        }
    } else if pit_context.is_some() {
        // Single-index PIT search: per-index fetch was bumped above to
        // allow PIT filtering without starving the page. Now apply
        // the caller-requested from/size on the post-filter hits.
        let from = search_req.from;
        let size = search_req.size;
        if size == 0 {
            merged_hits.clear();
        } else {
            let end = (from + size).min(merged_hits.len());
            let start = from.min(merged_hits.len());
            merged_hits = merged_hits[start..end].to_vec();
        }
    }

    // ── kNN result capping (ES knn semantics) ──────────────────────────────
    // Pure-knn search: trim the brute-force candidate set to `k` (already
    // bounded by `size` above) and report `hits.total` as the number of
    // candidates actually returned, rather than the whole-index match count.
    if let Some(cap) = knn_total_cap {
        merged_hits.truncate(cap);
        total_count = merged_hits.len() as u64;
        total_relation = "eq".to_string();
    }

    // ── HDR percentiles: negative-value shard failure (ES semantics) ─────
    // An HDR histogram can only record non-negative values. ES fails the
    // shard holding a doc with a negative value for an `hdr` percentiles
    // field: that doc is dropped from hits + total, the percentile is
    // recomputed over the surviving values, and a `_shards.failures` entry
    // with an illegal_argument_exception is surfaced. Mirror that here.
    let mut hdr_shard_failure: Option<Value> = None;
    {
        let aggs_req = body.aggs.as_ref().or(body.aggregations.as_ref());
        if let (Some(aggs_req), Some(magg)) = (aggs_req, merged_aggs.as_mut()) {
            let mut hdr_aggs: Vec<(String, String, Value)> = Vec::new();
            collect_hdr_percentile_aggs(aggs_req, &mut hdr_aggs);
            if !hdr_aggs.is_empty() {
                let fields: std::collections::HashSet<String> =
                    hdr_aggs.iter().map(|(_, f, _)| f.clone()).collect();
                let before = merged_hits.len();
                let mut negative_present = false;
                merged_hits.retain(|(_, h)| {
                    let neg = fields
                        .iter()
                        .any(|f| source_numeric_values(&h.source, f).iter().any(|v| *v < 0.0));
                    if neg {
                        negative_present = true;
                    }
                    !neg
                });
                let excluded = (before - merged_hits.len()) as u64;
                if negative_present {
                    total_count = total_count.saturating_sub(excluded);
                    // Recompute each HDR percentiles agg over the surviving
                    // (non-negative) values.
                    for (name, field, spec) in &hdr_aggs {
                        let vals: Vec<f64> = merged_hits
                            .iter()
                            .flat_map(|(_, h)| source_numeric_values(&h.source, field))
                            .filter(|v| *v >= 0.0)
                            .collect();
                        if let Some(agg_obj) = magg.get_mut(name).and_then(|v| v.as_object_mut()) {
                            agg_obj
                                .insert("values".to_string(), hdr_percentiles_values(&vals, spec));
                        }
                    }
                    hdr_shard_failure = Some(json!({
                        "shard": 0,
                        "index": index_names.first().copied().unwrap_or(""),
                        "node": "xerj-node-1",
                        "reason": {
                            "type": "illegal_argument_exception",
                            "reason": "Negative values are not supported by the HDRHistogram percentiles aggregation"
                        }
                    }));
                    shards_failed_count += 1;
                }
            }
        }
    }

    // ── `_savings` (xerj extension, `?savings=`) ──────────────────────────
    // Summed over the hits that survived every post-merge filter, so the
    // number describes THIS response and nothing else.
    //
    // Only this layer knows whether `_source` really was suppressed on the
    // wire: suppression keys off the literal body value, so `_source: "false"`
    // as a *string* still emits `_source` and the engine's claim would be
    // wrong. Requests that re-materialise values through `fields` are not
    // refused — they are netted at the emission site below, once the `fields`
    // objects actually exist.
    let source_withheld_claim_ok = !matches!(
        search_req.source,
        xerj_query::ast::SourceFilter::Enabled(false)
    ) || matches!(body.source, Some(Value::Bool(false)));
    let savings_page_bytes: u64 = merged_hits
        .iter()
        .filter_map(|(idx_name, h)| savings_by_hit.get(&(idx_name.clone(), h.id.clone())))
        .sum();
    let savings_claim = savings_record
        .as_ref()
        // Defense in depth against a stale cache entry: the engine's query
        // cache keys on the mode, but a record must never reach a caller who
        // asked for no measurement at all.
        .filter(|_| !matches!(search_req.savings, xerj_query::ast::SavingsMode::Off))
        .filter(|_| source_withheld_claim_ok)
        .map(|record| (record, savings_page_bytes));

    let took_ms = started.elapsed().as_millis() as u64;
    // RC4 W4 item 2: record the index-agnostic side of the completed search —
    // the global `queries_executed` counter plus BOTH latency histograms
    // (overall + by query type, which were previously never recorded).
    // `queries_by_index` is deliberately NOT touched here: it is already
    // incremented once per *resolved* concrete index in the loop above, which
    // correctly attributes multi-index / wildcard searches (vs. this handler's
    // single raw target label). Replaces the bare `query_latency.observe`.
    state
        .metrics
        .record_query_global(top_level_query_type(&body.query), took_ms as f64 / 1000.0);
    // v0.8 8-P6 / RC4-W4 item 3: record into the slow query log if over the
    // threshold. `maybe_record` also emits the unified slow-query tracing line
    // (same runtime threshold as the ring buffer), and captures the query body
    // so the entry is actionable.
    state.engine.slow_query.maybe_record(
        index.as_str(),
        "search",
        started.elapsed(),
        merged_hits.len() as u64,
        if body.aggs.is_some() { "with-aggs" } else { "" },
        // An omitted `query` (match_all) or a top-level `knn` with no query
        // clause used to log `query=` empty. `logged_search_query` records
        // the clause the engine actually ran.
        &xerj_engine::slow_query::logged_search_query(body.query.as_ref(), body.knn.as_ref()),
    );
    // v0.9 9-P4: append to the audit log. The subject was the literal
    // "anonymous" until issue #329 — the API-key operations had been passing a
    // real `principal.label()` since #201, so the plumbing existed and this one
    // site simply did not use it.
    //
    // Not for a search the hosted hub issues to itself (`InProcessSearch`): that
    // is a public read, and one audit entry per request would let anyone age the
    // operator's evidence out of the ring.
    if !in_process.skip_audit {
        state.engine.audit.append_as(
            // #1109: the machine/user split is decided HERE, server-side, from
            // what the request itself is — never from anything a client can set
            // (the spoofable `X-Xerj-Internal` header was considered and
            // rejected during #1107, and that decision stands). See
            // `search_actor_class` for exactly which requests are machine.
            search_actor_class(body.size, index.as_str()),
            "search",
            principal.label(),
            index.as_str(),
            "ok",
            // `size=` is the requested page size. A `size:0` search asks for no
            // hits — it is a counting probe (autoindex's verification reads back
            // exact group counts that way), not someone looking for documents,
            // and `xerj gain` needs exactly that distinction to report a hit
            // rate that is about people (#1105).
            &format!(
                "took={}ms hits={} size={}",
                took_ms,
                merged_hits.len(),
                body.size
            ),
        );
    }

    // ES semantics: when the sort has any non-score key, `max_score` is null
    // (scores aren't tracked during field-sorted execution unless
    // `track_scores: true` is set). Otherwise it's the top hit's score —
    // unless the sort is explicit-field, in which case the top hit isn't
    // necessarily the highest-scoring one and `max_score` must reflect
    // the population max across the merged hit set (search/111
    // `track_scores: true` with `sort: user_id asc`).
    // NOTE: a sort containing ONLY `_score` keys does NOT populate
    // `max_score` unless it is pure `_score` DESC (normalized to an empty
    // sort at parse time): live-verified on ES 8.13.4, `[{"_score":"asc"}]`
    // and `["_score","_doc"]` both return `max_score: null` while their
    // hits still carry `_score` values.
    let sort_tracks_scores = search_req.sort.is_empty() || body.track_scores.unwrap_or(false);
    let max_score = if sort_tracks_scores {
        let explicit_field_sort =
            !search_req.sort.is_empty() && search_req.sort.iter().any(|s| !s.is_score());
        if explicit_field_sort {
            // Prefer the per-index pre-collapse population max; fall back to the
            // (possibly collapsed/paged) merged hit set when unavailable.
            merged_population_max
                .map(|m| score_wire(m as f32))
                .or_else(|| {
                    merged_hits.iter().map(|(_, h)| score_wire(h.score)).fold(
                        None,
                        |acc: Option<f64>, s| {
                            Some(match acc {
                                Some(m) if m >= s => m,
                                _ => s,
                            })
                        },
                    )
                })
        } else if search_req.from > 0 && search_req.size > 0 {
            // ES's no-sort `max_score` is the top COLLECTED doc's score —
            // the population max — which `from` skips past but does not
            // erase (live-verified on ES 8.13.4: pinned/bool deep pages
            // keep the global max even when every higher scorer sits
            // before `from`, and a beyond-end page reports it with 0
            // hits). xerj used to report the PAGE head, under-reporting
            // whenever the head of the ranking was skipped. from == 0
            // keeps the page-head read (it IS the max under score-DESC
            // order — byte-identical); size == 0 keeps ES's null.
            let page_head = merged_hits.first().map(|(_, h)| score_wire(h.score));
            match (
                merged_population_max.map(|m| score_wire(m as f32)),
                page_head,
            ) {
                (Some(p), Some(h)) => Some(if p >= h { p } else { h }),
                (Some(p), None) => Some(p),
                (None, h) => h,
            }
        } else {
            merged_hits.first().map(|(_, h)| score_wire(h.score))
        }
    } else {
        None
    };

    // Snapshot every matching hit for the scroll context BEFORE we consume
    // merged_hits to build `hits`. We'll register the context after the
    // response_body is built.
    let scroll_snapshot: Option<Vec<(String, xerj_query::executor::Hit)>> = if is_scroll_request {
        // Keep the index name with each hit (#414): dropping it here is what
        // made continuation pages fall back to a single context-level name.
        let mut snap = merged_hits.clone();
        // #310 emission site 3: the snapshot outlives this response, and every
        // later page is rendered by `scroll_page_response`, which carries no
        // `fields` clause of its own and so has no reason to hold companions.
        // Undo the pierce before the context is stored — otherwise page 1
        // honours #309 and pages 2..n ship the companion in `_source`.
        if pierce_default_source {
            for (idx_name, h) in snap.iter_mut() {
                if let (Some(companions), Some(obj)) = (
                    companions_by_index.get(idx_name.as_str()),
                    h.source.as_object_mut(),
                ) {
                    obj.retain(|name, _| !companions.contains(name));
                }
            }
        }
        // #932 emission site 3: the same obligation for the caller's EXPLICIT
        // filter — continuation pages are rendered by `scroll_page_response`,
        // which carries no `fields` clause, so the snapshot must be re-narrowed
        // before the context is stored. The collapse sentinels are preserved
        // across the filtering exactly as the engine's own Includes/Fields
        // branches do (take → filter → reattach, #651), so a scroll+collapse
        // context keeps rendering inner_hits on pages 2..n.
        if let Some((includes, excludes)) = &pierce_explicit_source {
            for (_, h) in snap.iter_mut() {
                let sentinels: Vec<(&str, Value)> =
                    ["__xy_collapse_group__", "__xy_collapse_spec__"]
                        .into_iter()
                        .filter_map(|k| {
                            h.source
                                .as_object()
                                .and_then(|o| o.get(k))
                                .map(|v| (k, v.clone()))
                        })
                        .collect();
                h.source = xerj_engine::filter_object(&h.source, includes, excludes);
                if !sentinels.is_empty() {
                    if let Some(obj) = h.source.as_object_mut() {
                        for (k, v) in sentinels {
                            obj.insert(k.to_string(), v);
                        }
                    }
                }
            }
        }
        Some(snap)
    } else {
        None
    };

    let explain = search_req.explain;

    // `script_fields` are evaluated per hit (against each hit's source) inside
    // the fields-building closure below, so the computed values merge into the
    // same `fields` object ES uses. See the `script_fields` block near the end
    // of that closure.

    let requested_fields = &search_req.fields;

    // Parse the raw `fields` body value into a list of (name, format,
    // include_unmapped) specs. ES accepts both plain strings and objects
    // like `{"field": "date", "format": "yyyy-MM-dd"}` (7.11+). When the
    // body is absent, falls back to search_req.fields (plain strings).
    let field_specs: Vec<(String, Option<String>, bool)> = match &body.fields {
        Some(Value::Array(arr)) => arr
            .iter()
            .filter_map(|v| match v {
                Value::String(s) => Some((s.clone(), None, false)),
                Value::Object(o) => {
                    let name = o.get("field").and_then(Value::as_str)?.to_string();
                    let fmt = o.get("format").and_then(Value::as_str).map(str::to_string);
                    let inc = o
                        .get("include_unmapped")
                        .and_then(Value::as_bool)
                        .unwrap_or(false);
                    Some((name, fmt, inc))
                }
                _ => None,
            })
            .collect(),
        Some(Value::String(s)) => vec![(s.clone(), None, false)],
        _ => requested_fields
            .iter()
            .map(|s| (s.clone(), None, false))
            .collect(),
    };

    // Parse stored_fields from body.
    let (suppress_source_for_stored, stored_meta_fields) = body
        .stored_fields
        .as_ref()
        .map(parse_stored_fields)
        .unwrap_or((false, vec![]));
    // When parse returns the `__none__` sentinel, suppress `_id` on every
    // hit in the final response. Drop the sentinel from the requested-
    // meta list so it doesn't leak into the output `fields` map.
    let suppress_meta_fields = stored_meta_fields.iter().any(|f| f == "__none__");
    let stored_meta_fields: Vec<String> = stored_meta_fields
        .into_iter()
        .filter(|f| f != "__none__")
        .collect();

    // Parse docvalue_fields from body.
    let docvalue_fields: Vec<Value> = body
        .docvalue_fields
        .as_ref()
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();

    // inner_hits config from body. ES accepts inner_hits at two
    // locations: top-level `inner_hits: { ... }`, or embedded inside
    // `query.nested.inner_hits`. For the nested form we extract the
    // path + inner_hits spec and merge into a single map keyed by
    // path so the hit renderer builds one inner_hits bucket per path.
    let mut inner_hits_config = body.inner_hits.clone().unwrap_or(Value::Null);
    if let Some(q) = body.query.as_ref() {
        fn collect_nested_inner_hits(q: &Value, out: &mut serde_json::Map<String, Value>) {
            let Some(obj) = q.as_object() else { return };
            for (key, val) in obj {
                match key.as_str() {
                    "nested" => {
                        if let Some(n) = val.as_object() {
                            let path = n.get("path").and_then(Value::as_str);
                            let ih = n.get("inner_hits");
                            if let (Some(path), Some(ih)) = (path, ih) {
                                // Use path as bucket key unless spec
                                // provides a `name`.
                                let bucket_name = ih
                                    .as_object()
                                    .and_then(|o| o.get("name"))
                                    .and_then(Value::as_str)
                                    .unwrap_or(path)
                                    .to_string();
                                out.insert(bucket_name, ih.clone());
                            }
                            // Recurse into nested.query in case of bool
                            // nesting.
                            if let Some(inner_q) = n.get("query") {
                                collect_nested_inner_hits(inner_q, out);
                            }
                        }
                    }
                    "bool" => {
                        if let Some(b) = val.as_object() {
                            for sub_key in ["must", "should", "filter", "must_not"] {
                                if let Some(arr) = b.get(sub_key).and_then(Value::as_array) {
                                    for item in arr {
                                        collect_nested_inner_hits(item, out);
                                    }
                                }
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
        let mut extracted: serde_json::Map<String, Value> = serde_json::Map::new();
        collect_nested_inner_hits(q, &mut extracted);
        if !extracted.is_empty() {
            // Merge extracted with existing (top-level wins for name clashes).
            if let Some(existing_obj) = inner_hits_config.as_object_mut() {
                for (k, v) in extracted {
                    existing_obj.entry(k).or_insert(v);
                }
            } else {
                inner_hits_config = Value::Object(extracted);
            }
        }
    }

    // Control flags for meta-field emission on each hit.
    let emit_seq_no = body.seq_no_primary_term.unwrap_or(false);
    let emit_version = body.version.unwrap_or(false);

    let hits: Vec<EsHit> = merged_hits
        .into_iter()
        .map(|(idx_name, h)| {
            // Extract `_ignored` from _source (populated by apply_ignore_malformed
            // at index time). Promote it to a top-level hit meta-field and
            // remove it from the returned _source so _source stays clean.
            let ignored_list: Option<Vec<String>> = h
                .source
                .as_object()
                .and_then(|o| o.get("_ignored"))
                .and_then(|v| v.as_array())
                .map(|arr| arr.iter().filter_map(|x| x.as_str().map(String::from)).collect());
            // Same for the per-field map of original malformed values
            // captured by apply_ignore_malformed under the sentinel key.
            let ignored_field_values: Option<Value> = h
                .source
                .as_object()
                .and_then(|o| o.get("__xy_ignored_values__"))
                .cloned();
            // Extract collapse group members + spec before we strip source
            // keys. These are sentinel entries planted by apply_collapse
            // when the caller requested inner_hits on a collapse.
            let collapse_group: Option<Vec<Value>> = h
                .source
                .as_object()
                .and_then(|o| o.get("__xy_collapse_group__"))
                .and_then(|v| v.as_array())
                .cloned();
            let collapse_spec: Option<Value> = h
                .source
                .as_object()
                .and_then(|o| o.get("__xy_collapse_spec__"))
                .cloned();
            // ES suppresses `_source` in the response when the caller set
            // `_source: false` OR when the index mapping has
            // `_source.enabled: false`. We keep the underlying source
            // available internally for fields/highlight/_ignored
            // extraction, so the suppression is a response-time
            // decision not a data-layer decision.
            let source_body_disabled = matches!(body.source, Some(Value::Bool(false)));
            let source_mapping_disabled = mapping_source_disabled(&state, idx_name.as_str());
            // `stored_fields` implicitly suppressing `_source` (unless the
            // list literally contains `"_source"`) is only a DEFAULT for
            // when the caller left `_source` unspecified. When the request
            // also carries its own explicit top-level `_source` parameter
            // (true/false/{includes,excludes} — e.g. Discover's actual
            // query, which sends `stored_fields: ["*"]` AND `_source:
            // {excludes: []}` in the same request), that explicit value
            // always wins — found empirically: without this, `_source`
            // came back completely absent from every Discover row despite
            // the request explicitly asking to include it, which starved
            // every column except the couple of fields separately pulled
            // in via `docvalue_fields`.
            let source = if (suppress_source_for_stored && body.source.is_none())
                || source_body_disabled
                || source_mapping_disabled
                || h.source.is_null()
            {
                None
            } else {
                // Strip _ignored and collapse sentinels from the returned
                // _source (these are meta-fields, not user data).
                let mut s = h.source.clone();
                if let Some(obj) = s.as_object_mut() {
                    obj.remove("_ignored");
                    obj.remove("__xy_ignored_values__");
                    obj.remove("__xy_collapse_group__");
                    obj.remove("__xy_collapse_spec__");
                    obj.remove("_matched_queries");
                    obj.retain(|name, _| {
                        !name.starts_with(xerj_query::executor::PASSAGE_METADATA_PREFIX)
                    });
                }
                // #310 emission site 1: this request pierced the default
                // `_source` projection so the `fields` builder below could
                // resolve an embedding companion the caller explicitly named.
                // The pierce ends HERE — `fields` reads `h.source`, which is
                // untouched, while the wire `_source` carries exactly what the
                // #309 default would have carried. Miss this and #309's headline
                // guarantee turns into a full-vector response for anyone who
                // named a companion in `fields`.
                if pierce_default_source {
                    if let (Some(companions), Some(obj)) = (
                        companions_by_index.get(idx_name.as_str()),
                        s.as_object_mut(),
                    ) {
                        obj.retain(|name, _| !companions.contains(name));
                    }
                }
                // #932 emission site 1: this request pierced the caller's
                // own EXPLICIT `_source` filter so the `fields` builder below
                // could resolve a name the filter drops. The pierce ends HERE
                // — `fields` reads `h.source`, which is untouched, while the
                // wire `_source` carries exactly what the engine-side filter
                // would have produced (same `filter_object`, same input). The
                // engine's Includes/Fields branches re-attach the collapse
                // sentinels around their filtering; that dance is unnecessary
                // here — the sentinels were already extracted above and
                // stripped from `s`.
                if let Some((includes, excludes)) = &pierce_explicit_source {
                    s = xerj_engine::filter_object(&s, includes, excludes);
                }
                // Non-synthetic mode: strip the internal copy-to
                // tracking marker; keep the copied values in the source
                // since stored-source clients expect them.
                // (Synthetic mode block below handles filter+strip.)
                if let Some(obj) = s.as_object_mut() {
                    obj.remove("__xy_copy_to_only__");
                    obj.remove("__xy_copy_to_pristine__");
                    obj.remove("__xy_pre_rescore_score__");
                }
                // Synthetic source mode: ES reconstructs _source from
                // doc-values and applies specific normalizations. For
                // unmapped dotted keys, split at the FIRST dot so
                // `{"a.very.deeply.nested.field": "X"}` becomes
                // `{"a": {"very.deeply.nested.field": "X"}}`. Known
                // mapped fields (declared in the index properties) are
                // left untouched.
                let synthetic_mode = state.engine.index_settings
                    .get(idx_name.as_str())
                    .map(|v| v.clone())
                    .and_then(|s| {
                        let is_synth = |v: &Value| v.as_str() == Some("synthetic");
                        s.pointer("/index/mapping/source.mode").map(is_synth)
                            .or_else(|| s.get("index").and_then(|i| i.get("mapping.source.mode")).map(is_synth))
                            .or_else(|| s.get("index.mapping.source.mode").map(is_synth))
                    })
                    .unwrap_or(false);
                if synthetic_mode {
                    // Restore each copy_to target to its pristine value
                    // (what the user originally wrote, if anything). This
                    // matches ES synthetic source: copied values live in
                    // doc_values/fields, the reconstructed _source shows
                    // only the explicit user-written entries.
                    if let Some(obj) = s.as_object_mut() {
                        if let Some(Value::Object(pristine)) = h.source.get("__xy_copy_to_pristine__").cloned() {
                            for (tgt, orig) in pristine {
                                // Remove the current (copy-populated) value
                                // at the dotted path, then restore the
                                // pristine value.
                                remove_dotted_path(obj, &tgt);
                                if !matches!(orig, Value::Null) {
                                    set_dotted_path(obj, &tgt, orig);
                                }
                            }
                        }
                        // Restore ignore_malformed dropped values. ES
                        // synthetic source preserves the original value
                        // in `_source` via an "ignored_source" stored
                        // mechanism; we keep it as
                        // `__xy_ignored_values__[field]` and re-inject
                        // here so the reconstructed source matches the
                        // user's original input. A single-element array
                        // is unwrapped to the scalar it originated from.
                        if let Some(Value::Object(iv)) = h.source.get("__xy_ignored_values__").cloned() {
                            for (field, vals) in iv {
                                let restored = match vals {
                                    Value::Array(mut arr) if arr.len() == 1 => arr.remove(0),
                                    other => other,
                                };
                                set_dotted_path(obj, &field, restored);
                            }
                        }
                    }
                    let mapping = state.engine.index_mappings
                        .get(idx_name.as_str())
                        .map(|v| v.clone());
                    let mappings_enabled = mapping.as_ref()
                        .and_then(|m| {
                            m.pointer("/mappings/enabled")
                                .or_else(|| m.pointer("/enabled"))
                                .and_then(Value::as_bool)
                        })
                        .unwrap_or(true);
                    // Walk the mapping properties tree alongside each
                    // dotted key segment. While the current segment is a
                    // mapped property, descend into its children.  At the
                    // first unmapped segment, that becomes a key and the
                    // remaining dots stay as a literal sub-key. This
                    // matches ES synthetic-source's "ignored_source"
                    // reconstruction layout for dynamic fields.
                    if mappings_enabled {
                        let root_props = mapping.as_ref()
                            .and_then(|m| m.pointer("/mappings/properties").or_else(|| m.pointer("/properties")))
                            .cloned()
                            .unwrap_or(Value::Null);
                        let index_settings_val = state.engine.index_settings
                            .get(idx_name.as_str())
                            .map(|v| v.clone());
                        let index_keep_arrays = index_settings_val.as_ref()
                            .and_then(|s| {
                                s.pointer("/index/mapping/synthetic_source_keep")
                                    .or_else(|| s.get("index").and_then(|i| i.get("mapping.synthetic_source_keep")))
                                    .or_else(|| s.get("index.mapping.synthetic_source_keep"))
                                    .and_then(Value::as_str)
                                    .map(|m| matches!(m, "arrays" | "all"))
                            })
                            .unwrap_or(false);
                        // `total_fields.ignore_dynamic_beyond_limit: true`
                        // (or the mapping-root `dynamic: false`) makes new
                        // fields "ignored source" at ingest — their values
                        // are stored verbatim rather than mapped. When
                        // reading synthetic source back, those fields must
                        // preserve their original array-of-objects shape
                        // instead of being flattened column-major.
                        let index_ignore_beyond_limit = index_settings_val.as_ref()
                            .and_then(|s| {
                                s.pointer("/index/mapping/total_fields/ignore_dynamic_beyond_limit")
                                    .or_else(|| s.pointer("/index/mapping.total_fields.ignore_dynamic_beyond_limit"))
                                    .or_else(|| s.pointer("/index.mapping.total_fields.ignore_dynamic_beyond_limit"))
                                    .and_then(Value::as_bool)
                            })
                            .unwrap_or(false);
                        let mapping_root_dynamic_false = mapping.as_ref()
                            .and_then(|m| m.pointer("/mappings/dynamic").or_else(|| m.pointer("/dynamic")))
                            .map(|v| match v {
                                Value::Bool(false) => true,
                                Value::String(s) => s == "false" || s == "runtime",
                                _ => false,
                            })
                            .unwrap_or(false);
                        let root_dynamic_false = index_ignore_beyond_limit || mapping_root_dynamic_false;
                        if let Some(obj) = s.as_object_mut() {
                            synthetic_transform_object_ext2(obj, &root_props, index_keep_arrays, root_dynamic_false, false);
                        }
                    }
                }
                Some(s)
            };
            // Build explanation if requested.
            let explanation = if explain {
                let base = build_explanation(h.score, &search_req.query);
                // Detect script-rescore stages in the request and
                // wrap the base explanation with the ES-format
                // `{description: "script score function", details:
                // [{description: "_score: ", value: base_score}]}`
                // wrapper — each rescore stage wraps the prior
                // explanation for hits that fell within its
                // `window_size`.
                let mut wrapped = base;
                // Prefer the pre-rescore score that apply_rescore
                // stashed in the source — without it, `wrapped.value`
                // already carries the post-rescore score and the
                // `_score: ` detail line would report the final
                // blended number instead of the original BM25.
                // Absent (`None`) means this hit fell outside every
                // rescore stage's window; keep the base explanation.
                let pre_rescore_score = h.source.get("__xy_pre_rescore_score__")
                    .and_then(Value::as_f64);
                let hit_was_rescored = pre_rescore_score.is_some();
                for stage in &search_req.rescore {
                    if stage.script.is_none() { continue; }
                    if !hit_was_rescored { continue; }
                    let inner_value = pre_rescore_score
                        .or_else(|| wrapped.get("value").and_then(Value::as_f64))
                        .unwrap_or(h.score as f64);
                    let inner_desc = wrapped.get("description").and_then(Value::as_str).unwrap_or("").to_string();
                    let inner_details = wrapped.get("details").cloned().unwrap_or(Value::Array(vec![]));
                    // Every script rescore stage wraps the prior
                    // explanation with ES's canonical `{description:
                    // "script score function", details: [{description:
                    // "_score: ", value: prior_value, details: prior_details}]}`
                    // shape. Hits outside the window would carry the
                    // base description instead, but for simplicity we
                    // wrap unconditionally — ES exposes the whole
                    // rescore tree even for non-top-k hits (they're
                    // shown with `_score` = original BM25).
                    // Ignore the inner (rescored) wrap's description
                    // when building the `_score: ` leaf label —
                    // ES emits the literal `"_score: "` string there,
                    // not the base query's Lucene breakdown.
                    let _ = inner_desc;
                    wrapped = json!({
                        "value": h.score,
                        "description": "script score function",
                        "details": [
                            {
                                "value": inner_value,
                                "description": "_score: ",
                                "details": inner_details,
                            }
                        ]
                    });
                }
                Some(wrapped)
            } else {
                None
            };
            // Build fields dict: merge requested_fields + docvalue_fields.
            let fields_map: Option<HashMap<String, Value>> = {
                let mut fmap = HashMap::new();

                // Resolve per-field `ignore_above` — from the field's mapping
                // or from the index-level default `index.mapping.ignore_above`.
                // When a fetched value is longer than the threshold, ES omits
                // it from `fields` output (including in flattened types where
                // a single oversize leaf drops the entire field value).
                let mapping_for_fields = state.engine.index_mappings
                    .get(idx_name.as_str())
                    .map(|v| v.clone());
                let settings_for_fields = state.engine.index_settings
                    .get(idx_name.as_str())
                    .map(|v| v.clone());
                let default_ignore_above: Option<usize> = settings_for_fields.as_ref().and_then(|s| {
                    let as_u = |v: &Value| v.as_u64().or_else(|| v.as_str().and_then(|x| x.parse().ok())).map(|n| n as usize);
                    s.pointer("/index/mapping/ignore_above").and_then(as_u)
                        .or_else(|| s.get("index").and_then(|i| i.get("mapping.ignore_above")).and_then(as_u))
                        .or_else(|| s.get("index.mapping.ignore_above").and_then(as_u))
                });
                let field_ignore_above = |field: &str| -> Option<(usize, &'static str)> {
                    let fspec = mapping_for_fields.as_ref()
                        .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties")))
                        .and_then(|p| p.get(field));
                    let ftype_static: &'static str = match fspec.and_then(|f| f.get("type")).and_then(Value::as_str) {
                        Some("keyword") => "keyword",
                        Some("flattened") | Some("flat_object") => "flattened",
                        _ => "other",
                    };
                    let explicit = fspec.and_then(|f| f.get("ignore_above")).and_then(Value::as_u64).map(|n| n as usize);
                    explicit.or(default_ignore_above).map(|n| (n, ftype_static))
                };
                // Whether the requested top-level field is `type: nested`
                // — used to wrap each nested element's leaf scalars in
                // single-element arrays (ES `fields` shape for nested).
                let is_nested = |field: &str| -> bool {
                    // Walk dotted path through properties/<seg> so
                    // obj.products resolves as nested when the leaf
                    // field's type is nested.
                    let root_props = mapping_for_fields.as_ref()
                        .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties")))
                        .cloned()
                        .unwrap_or(Value::Null);
                    let mut cur = root_props;
                    let segs: Vec<&str> = field.split('.').collect();
                    let last = segs.len() - 1;
                    for (i, seg) in segs.iter().enumerate() {
                        let Some(next) = cur.get(*seg).cloned() else { return false };
                        if i == last {
                            return next.get("type").and_then(Value::as_str) == Some("nested");
                        }
                        if let Some(p) = next.get("properties").cloned() {
                            cur = p;
                        } else { return false; }
                    }
                    false
                };
                // Find the longest prefix of `field` that is a `type:nested`
                // path. Returns Some((nested_path, sub_path)) — e.g. for
                // `products.manufacturer` where `products` is nested →
                // Some(("products", "manufacturer")). Returns None when
                // no nested ancestor exists. Walks the mapping properties
                // tree segment by segment.
                let nested_ancestor = |field: &str| -> Option<(String, String)> {
                    let root_props = mapping_for_fields.as_ref()
                        .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties")))
                        .cloned()?;
                    let segs: Vec<&str> = field.split('.').collect();
                    if segs.len() < 2 { return None; }
                    let mut cur = root_props;
                    let mut nested_at: Option<usize> = None;
                    for (i, seg) in segs.iter().enumerate() {
                        let next = cur.get(*seg).cloned()?;
                        if next.get("type").and_then(Value::as_str) == Some("nested") {
                            nested_at = Some(i);
                            // Record the longest nested prefix found.
                        }
                        if let Some(p) = next.get("properties").cloned() {
                            cur = p;
                        } else if i + 1 < segs.len() {
                            // Cannot descend further — abort.
                            break;
                        }
                    }
                    let idx = nested_at?;
                    if idx + 1 >= segs.len() { return None; } // path IS the nested field, not a sub-field
                    let nested_path = segs[..=idx].join(".");
                    let sub_path = segs[idx + 1..].join(".");
                    Some((nested_path, sub_path))
                };
                fn count_chars(v: &Value) -> usize {
                    match v {
                        Value::String(s) => s.chars().count(),
                        _ => 0,
                    }
                }
                fn has_oversize_string(v: &Value, max: usize) -> bool {
                    match v {
                        Value::String(s) => s.chars().count() > max,
                        Value::Array(arr) => arr.iter().any(|e| has_oversize_string(e, max)),
                        Value::Object(obj) => obj.values().any(|e| has_oversize_string(e, max)),
                        _ => false,
                    }
                }
                /// Walk a flattened value and prune oversize string leaves.
                /// Returns (pruned_value, any_kept) — when no strings
                /// survive and it was a scalar, returns Value::Null so
                /// the caller drops the entry.
                fn prune_oversize(v: Value, max: usize) -> Option<Value> {
                    match v {
                        Value::String(ref s) => {
                            if s.chars().count() > max { None } else { Some(v) }
                        }
                        Value::Array(arr) => {
                            let kept: Vec<Value> = arr.into_iter().filter_map(|e| prune_oversize(e, max)).collect();
                            if kept.is_empty() {
                                None
                            } else if kept.len() == 1 {
                                // Flattened doc-values collapse single-element
                                // arrays to a scalar on fetch — preserve that.
                                Some(kept.into_iter().next().unwrap())
                            } else {
                                Some(Value::Array(kept))
                            }
                        }
                        Value::Object(obj) => {
                            let mut kept = serde_json::Map::new();
                            for (k, val) in obj {
                                if let Some(p) = prune_oversize(val, max) {
                                    kept.insert(k, p);
                                }
                            }
                            if kept.is_empty() { None } else { Some(Value::Object(kept)) }
                        }
                        other => Some(other),
                    }
                }

                // fields (from `fields` key in body).
                // ES semantics: each entry is an array; if the source value is
                // already an array, it stays flat (NOT double-wrapped); scalars
                // are wrapped in a single-element array; missing fields are
                // omitted from the response. Object-form entries support
                // `format` (date patterns) and `include_unmapped` flags.
                for (field_name, format, _include_unmapped) in &field_specs {
                    // Pattern decomposition: when a wildcard pattern
                    // is `<nested_root>.<rest>` with `<nested_root>`
                    // being a `type: nested` mapping path, the
                    // expansion should consider the nested root as a
                    // single emit-key and filter its inner fields by
                    // the trailing `<rest>` pattern. We compute the
                    // (root, sub-pattern) pair here and use it both to
                    // seed `names` and to feed into wrap_nested_element
                    // via thread-local state.
                    let nested_root_pattern: Option<(String, String)> = if field_name.contains('*') {
                        let root_props_full = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties"))
                                .or_else(|| m.get("properties")))
                            .cloned()
                            .unwrap_or(Value::Null);
                        let segs: Vec<&str> = field_name.split('.').collect();
                        // Walk, allowing wildcarded segments that
                        // resolve to exactly one mapped sibling
                        // (e.g. `obj.pro*ts.manufacturer` → `obj.products`
                        // when `obj.products` is declared and
                        // `obj.pro*ts` matches only `products`).
                        let mut root = String::new();
                        let mut cur = root_props_full.clone();
                        let mut found = None;
                        for (i, seg) in segs.iter().enumerate() {
                            let mut matched: Option<String> = None;
                            if seg.contains('*') {
                                if let Some(obj) = cur.as_object() {
                                    for k in obj.keys() {
                                        if wildcard_match(seg, k) {
                                            if matched.is_none() { matched = Some(k.clone()); }
                                            else { matched = None; break; }
                                        }
                                    }
                                }
                            } else if cur.get(seg).is_some() {
                                matched = Some(seg.to_string());
                            }
                            let Some(resolved_seg) = matched else { break };
                            let spec = match cur.get(&resolved_seg).cloned() {
                                Some(s) => s,
                                None => break,
                            };
                            if !root.is_empty() { root.push('.'); }
                            root.push_str(&resolved_seg);
                            if spec.get("type").and_then(Value::as_str) == Some("nested") {
                                let rest = segs[i+1..].join(".");
                                found = Some((root.clone(), rest));
                                break;
                            }
                            cur = spec.get("properties").cloned().unwrap_or(Value::Null);
                            if cur.is_null() { break; }
                        }
                        found
                    } else { None };

                    // Wildcard expansion against the doc's _source.
                    let mut names: Vec<String> = if field_name.contains('*') {
                        let expanded = expand_field_wildcard(&h.source, field_name);
                        // `geo_point`, `geo_shape`, `shape`, `point`
                        // and `dense_vector` fields are atomic leaves
                        // in ES's fields-fetch model — they serialise
                        // as a single structured value, not as
                        // per-sub-key entries. When our source-based
                        // path walker exposes inner keys (e.g.
                        // `field.lat`/`field.lon`) those need to fold
                        // back into the parent path.
                        let atomic_types = ["geo_point", "geo_shape", "shape", "point", "dense_vector"];
                        let root_props = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties"))
                                .or_else(|| m.get("properties")))
                            .cloned()
                            .unwrap_or(Value::Null);
                        let find_atomic_ancestor = |path: &str| -> Option<String> {
                            let segs: Vec<&str> = path.split('.').collect();
                            let mut cur = root_props.clone();
                            let mut so_far = String::new();
                            for (i, seg) in segs.iter().enumerate() {
                                let Some(next) = cur.get(*seg).cloned() else { break };
                                if !so_far.is_empty() { so_far.push('.'); }
                                so_far.push_str(seg);
                                if let Some(t) = next.get("type").and_then(Value::as_str) {
                                    if atomic_types.contains(&t) && i < segs.len() - 1 {
                                        return Some(so_far);
                                    }
                                }
                                if let Some(p) = next.get("properties").cloned() { cur = p; }
                                else { break; }
                            }
                            None
                        };
                        let mut seen: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();
                        let mut out: Vec<String> = Vec::new();
                        for n in expanded {
                            let replacement = find_atomic_ancestor(&n).unwrap_or(n);
                            if seen.insert(replacement.clone()) {
                                out.push(replacement);
                            }
                        }
                        out
                    } else {
                        vec![field_name.clone()]
                    };

                    // Declared multi-fields (`fields: {length: {...}}`).
                    // For every name with a declared `fields` block in
                    // the mapping, add `<name>.<sub>` as a sibling so
                    // fields-fetch surfaces the token_count / keyword /
                    // etc. multi-field alongside the main value.
                    if field_name.contains('*') {
                        if let Some(root_props_v) = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties"))
                                .or_else(|| m.get("properties")))
                            .cloned()
                        {
                            let mut to_add: Vec<String> = Vec::new();
                            for n in &names {
                                // Walk the mapping to find this name's
                                // spec, if any.
                                let segs: Vec<&str> = n.split('.').collect();
                                let mut cur = root_props_v.clone();
                                let mut spec: Option<Value> = None;
                                for (i, seg) in segs.iter().enumerate() {
                                    let Some(next) = cur.get(*seg).cloned() else { break };
                                    if i == segs.len() - 1 {
                                        spec = Some(next);
                                    } else if let Some(p) = next.get("properties").cloned() {
                                        cur = p;
                                    } else { break; }
                                }
                                let Some(spec) = spec else { continue };
                                let Some(sub_fields) = spec.get("fields").and_then(Value::as_object) else { continue };
                                for (sub_name, _sub_spec) in sub_fields {
                                    let full = format!("{}.{}", n, sub_name);
                                    if !names.contains(&full) && !to_add.contains(&full) {
                                        to_add.push(full);
                                    }
                                }
                            }
                            names.extend(to_add);
                        }
                    }

                    // ES dynamic mapping auto-creates a `.keyword`
                    // multi-field on any string-typed field dynamically
                    // mapped under `dynamic: true` (the default). Mirror
                    // that here: for every name whose source value is a
                    // scalar string AND the mapping contains NO
                    // explicit declaration for that path (top-level or
                    // nested), add a `<name>.keyword` synthetic entry.
                    // We only run this pass when the mapping has no
                    // top-level `properties` (i.e. pure dynamic, as in
                    // the subobjects:false + no-properties case) — that
                    // keeps explicit mappings from getting surprise
                    // `.keyword` siblings.
                    // When the wildcard pattern is a nested-root
                    // sub-pattern (e.g. `user.address*` with `user`
                    // being `type: nested`), the wildcard expander
                    // doesn't see paths inside the nested array. Seed
                    // `names` with the nested root so the
                    // nested-emit branch fires (and uses our
                    // sub-pattern key_filter to restrict output).
                    if let Some((root, _)) = nested_root_pattern.as_ref() {
                        if !names.contains(root) {
                            names.push(root.clone());
                        }
                    }
                    if field_name.contains('*') {
                        let has_any_props = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties")))
                            .and_then(Value::as_object)
                            .map(|o| !o.is_empty())
                            .unwrap_or(false);
                        if !has_any_props {
                            let mut to_add: Vec<String> = Vec::new();
                            for n in &names {
                                if n.ends_with(".keyword") { continue; }
                                let kw_name = format!("{}.keyword", n);
                                if names.contains(&kw_name) || to_add.contains(&kw_name) { continue; }
                                let raw = get_source_value_by_path(&h.source, n);
                                if matches!(raw, Some(Value::String(_))) && wildcard_match(field_name, &kw_name) {
                                    to_add.push(kw_name);
                                }
                            }
                            names.extend(to_add);
                        }
                    }
                    // For wildcard expansion, also pick up declared alias
                    // fields that match — they don't appear in _source but
                    // should be resolvable via their `path` target. ES
                    // treats fields: ['*'] as matching every mapped field
                    // including aliases.
                    if field_name.contains('*') {
                        if let Some(m) = mapping_for_fields.as_ref() {
                            let props = m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties"));
                            if let Some(pobj) = props.and_then(Value::as_object) {
                                for (fname, fspec) in pobj {
                                    let is_alias = fspec.get("type").and_then(Value::as_str) == Some("alias");
                                    if is_alias && wildcard_match(field_name, fname) && !names.contains(fname) {
                                        names.push(fname.clone());
                                    }
                                }
                            }
                        }
                    }
                    // For nested-typed top-level paths, drop their
                    // descendant paths from the wildcard expansion: ES
                    // emits only the top-level nested key, with each
                    // element's leaf scalars wrapped in arrays.
                    if field_name.contains('*') {
                        let nested_roots: Vec<String> = names.iter().filter(|n| is_nested(n)).cloned().collect();
                        if !nested_roots.is_empty() {
                            names.retain(|n| {
                                !nested_roots.iter().any(|root| {
                                    n != root && n.starts_with(&format!("{}.", root))
                                })
                            });
                        }
                        // Flattened-typed paths: same treatment — drop
                        // descendant paths, keep only the root, and
                        // include the root itself (leaf-only expand may
                        // have dropped it).
                        let is_flattened = |field: &str| -> bool {
                            matches!(
                                mapping_for_fields.as_ref()
                                    .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties")))
                                    .and_then(|p| p.get(field))
                                    .and_then(|f| f.get("type"))
                                    .and_then(Value::as_str),
                                Some("flattened") | Some("flat_object")
                            )
                        };
                        // First pass: identify declared flattened roots
                        // that match the pattern (either among current
                        // names or directly in the mapping).
                        let mut flat_roots: Vec<String> = Vec::new();
                        if let Some(m) = mapping_for_fields.as_ref() {
                            let props = m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties"));
                            if let Some(pobj) = props.and_then(Value::as_object) {
                                for (fname, fspec) in pobj {
                                    if matches!(fspec.get("type").and_then(Value::as_str), Some("flattened") | Some("flat_object"))
                                        && wildcard_match(field_name, fname)
                                    {
                                        flat_roots.push(fname.clone());
                                    }
                                }
                            }
                        }
                        for root in &flat_roots {
                            if !names.contains(root) { names.push(root.clone()); }
                        }
                        if !flat_roots.is_empty() {
                            names.retain(|n| {
                                !flat_roots.iter().any(|root| {
                                    n != root && n.starts_with(&format!("{}.", root))
                                })
                            });
                        }
                        let _ = is_flattened; // reserved for future leaf-type checks

                        // For wildcard patterns like `flattened.*` or
                        // `flat.some*` — where the unwildcarded prefix
                        // is a flattened-typed root — ES doesn't expand
                        // into sub-keys (flattened doesn't declare
                        // sub-fields). Drop expanded sub-paths under
                        // any flattened root even when the pattern
                        // itself requested them.
                        let prefix = field_name.split('*').next().unwrap_or("");
                        let prefix_root = prefix.trim_end_matches('.').rsplit_once('.').map(|(_, _)| prefix.trim_end_matches('.').to_string())
                            .unwrap_or(prefix.trim_end_matches('.').to_string());
                        // Find any declared flattened root that is a
                        // prefix of `prefix` (e.g. `flattened` is an
                        // ancestor of `flattened.some*`).
                        if let Some(m) = mapping_for_fields.as_ref() {
                            let props = m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties"));
                            if let Some(pobj) = props.and_then(Value::as_object) {
                                let ancestor_flat: Vec<String> = pobj.iter()
                                    .filter(|(_, s)| matches!(s.get("type").and_then(Value::as_str), Some("flattened") | Some("flat_object")))
                                    .map(|(k, _)| k.clone())
                                    .filter(|root| prefix_root.starts_with(root) && prefix_root != *root)
                                    .collect();
                                if !ancestor_flat.is_empty() {
                                    names.retain(|n| {
                                        !ancestor_flat.iter().any(|root| n.starts_with(&format!("{}.", root)))
                                    });
                                }
                            }
                        }
                    }
                    for name in &names {
                        // Metadata field shortcuts — these come from hit
                        // metadata, not the source, so they work even
                        // when _source.enabled: false.
                        match name.as_str() {
                            "_id" => {
                                fmap.insert("_id".to_string(), Value::Array(vec![Value::String(h.id.clone())]));
                                continue;
                            }
                            "_index" => {
                                fmap.insert("_index".to_string(), Value::Array(vec![Value::String(idx_name.to_string())]));
                                continue;
                            }
                            "_version" => {
                                // Read from the hit itself — resolved at
                                // construction time in the engine (same
                                // external-version-map-wins resolver GET/
                                // _mget use), not a later live re-lookup
                                // here (#440).
                                let v = h.version.unwrap_or(1);
                                fmap.insert("_version".to_string(), Value::Array(vec![json!(v)]));
                                continue;
                            }
                            _ => {}
                        }
                        // Runtime fields of `type: lookup` resolve each
                        // hit against an external index by
                        // `input_field` → `target_field`, fetching a
                        // configured set of sub-fields. When the
                        // join misses the response is `null` (ES's
                        // `match: null` shorthand).
                        let lookup_spec = body.runtime_mappings.as_ref()
                            .and_then(|rm| rm.get(name))
                            .and_then(|spec| {
                                if spec.get("type").and_then(Value::as_str) == Some("lookup") {
                                    spec.as_object().cloned()
                                } else { None }
                            });
                        if let Some(ls) = lookup_spec {
                            let target_index_name = ls.get("target_index")
                                .and_then(Value::as_str).unwrap_or("");
                            let input_field = ls.get("input_field")
                                .and_then(Value::as_str).unwrap_or("");
                            let target_field = ls.get("target_field")
                                .and_then(Value::as_str).unwrap_or("_id");
                            let fetch_fields: Vec<String> = ls.get("fetch_fields")
                                .and_then(Value::as_array)
                                .map(|a| a.iter().filter_map(|v| match v {
                                    Value::String(s) => Some(s.clone()),
                                    Value::Object(o) => o.get("field").and_then(Value::as_str).map(String::from),
                                    _ => None,
                                }).collect())
                                .unwrap_or_default();
                            let input_val = get_source_value_by_path(&h.source, input_field);
                            let Some(key) = input_val.and_then(|v| v.as_str().map(String::from)) else {
                                fmap.insert(name.clone(), Value::Null);
                                continue;
                            };
                            let resolved: Option<Value> = tokio::task::block_in_place(|| {
                                let rt = tokio::runtime::Handle::current();
                                rt.block_on(async {
                                    match state.engine.get_index(target_index_name) {
                                        Ok(idx) => {
                                            if target_field == "_id" {
                                                match idx.get_document(&key).await {
                                                    Ok(Some(doc)) => Some(doc),
                                                    _ => None,
                                                }
                                            } else {
                                                let q = xerj_query::ast::QueryNode::Term {
                                                    boost: None,
                                                    field: target_field.to_string(),
                                                    value: Value::String(key.clone()),
                                                };
                                                let req = xerj_query::ast::SearchRequest {
                                                    query: q,
                                                    from: 0,
                                                    size: 1,
                                                    track_total_hits: xerj_query::ast::TrackTotalHits::Limit(1),
                                                    ..Default::default()
                                                };
                                                match idx.search(&req).await {
                                                    Ok(r) => r.hits.into_iter().next().map(|h| h.source),
                                                    _ => None,
                                                }
                                            }
                                        }
                                        Err(_) => None,
                                    }
                                })
                            });
                            let Some(doc) = resolved else {
                                fmap.insert(name.clone(), Value::Null);
                                continue;
                            };
                            let mut grouped = serde_json::Map::new();
                            for ff in &fetch_fields {
                                if let Some(v) = get_source_value_by_path(&doc, ff) {
                                    let arr = match v {
                                        Value::Array(a) => Value::Array(a),
                                        other => Value::Array(vec![other]),
                                    };
                                    grouped.insert(ff.clone(), arr);
                                }
                            }
                            if grouped.is_empty() {
                                fmap.insert(name.clone(), Value::Null);
                            } else {
                                fmap.insert(name.clone(), Value::Array(vec![Value::Object(grouped)]));
                            }
                            continue;
                        }
                        // Runtime fields: when the requested field name is
                        // declared in body.runtime_mappings, evaluate its
                        // Painless script per doc and emit the collected
                        // values. The script communicates results via
                        // `emit(value)` (multiple emits → multi-valued).
                        let runtime_spec = body.runtime_mappings.as_ref()
                            .and_then(|rm| rm.get(name))
                            .and_then(|spec| spec.get("script"))
                            .and_then(Value::as_object);
                        if let Some(rs) = runtime_spec {
                            let source = rs.get("source").and_then(Value::as_str).unwrap_or("");
                            let empty = Value::Object(serde_json::Map::new());
                            let params_v = rs.get("params").unwrap_or(&empty);
                            let ctx = xerj_engine::painless::PainlessCtx::new(
                                &h.source, params_v, h.score,
                            );
                            let _ = xerj_engine::painless::eval_painless(source, &ctx);
                            let emits = ctx.take_emits();
                            if !emits.is_empty() {
                                let arr: Vec<Value> = emits.into_iter().map(painless_to_json).collect();
                                fmap.insert(name.clone(), Value::Array(arr));
                            }
                            continue;
                        }
                        // First try the literal field name. If the source
                        // doesn't carry that key and the field is a declared
                        // alias (in some participating index), fall back to
                        // the alias target path. Response key retains the
                        // caller-requested name either way. Aliases that
                        // point at metadata fields (_id/_index) resolve
                        // to the hit's identity rather than source.
                        let alias_tgt = alias_map.get(name).map(String::as_str);
                        let raw = if let Some(tgt) = alias_tgt {
                            match tgt {
                                "_id" => Some(Value::String(h.id.clone())),
                                "_index" => Some(Value::String(idx_name.to_string())),
                                _ => get_source_value_by_path(&h.source, name)
                                    .or_else(|| get_source_value_by_path(&h.source, tgt)),
                            }
                        } else {
                            // For nested-typed fields, ES merges values
                            // from the literal-dotted source key AND the
                            // walked-nested-object source path. So a doc
                            // that has both `obj.products: [..]` (dotted)
                            // and `obj: { products: [..] }` (nested)
                            // returns the union of both arrays.
                            if is_nested(name) && name.contains('.') {
                                // ES nested-walk precedes the
                                // literal-dotted source key in the
                                // emitted array (subobjects:true
                                // walks first).
                                let literal = h.source.as_object().and_then(|o| o.get(name)).cloned();
                                let parts: Vec<&str> = name.split('.').collect();
                                let walked = get_field_value_via_walk(&h.source, &parts);
                                match (walked, literal) {
                                    (Some(Value::Array(a)), Some(Value::Array(b))) => {
                                        let mut merged = a;
                                        merged.extend(b);
                                        Some(Value::Array(merged))
                                    }
                                    (Some(a), Some(b)) => {
                                        let mut merged = match a { Value::Array(arr) => arr, x => vec![x] };
                                        match b { Value::Array(arr) => merged.extend(arr), x => merged.push(x) }
                                        Some(Value::Array(merged))
                                    }
                                    (Some(v), None) | (None, Some(v)) => Some(v),
                                    _ => None,
                                }
                            } else {
                                get_source_value_by_path(&h.source, name)
                            }
                        };
                        // `.keyword` synthetic multi-field: when the
                        // requested name ends in `.keyword` and there's
                        // no actual value at that path, fall back to
                        // the parent scalar string's value (mirrors ES
                        // dynamic mapping auto-created keyword
                        // sub-fields).
                        let raw = if raw.is_none() && name.ends_with(".keyword") {
                            let base = &name[..name.len() - ".keyword".len()];
                            let base_val = get_source_value_by_path(&h.source, base);
                            match base_val {
                                Some(Value::String(s)) => Some(Value::String(s)),
                                Some(Value::Array(arr))
                                    if arr.iter().all(|v| matches!(v, Value::String(_))) =>
                                {
                                    Some(Value::Array(arr))
                                }
                                _ => None,
                            }
                        } else {
                            raw
                        };
                        // `token_count` multi-field: when the declared
                        // type of this path is `token_count`, the value
                        // is the number of analyzer-produced tokens in
                        // the parent field's source string(s). No value
                        // is stored in source — we derive it on fetch.
                        let raw = if let Some(dot) = (raw.is_none() && name.contains('.'))
                            .then(|| name.rfind('.'))
                            .flatten()
                        {
                            // `name.contains('.')` guarantees `rfind` returns
                            // Some, but we keep the explicit unwrap-free
                            // pattern so a refactor of either guard can't
                            // silently turn this into a runtime panic.
                            let base = &name[..dot];
                            let is_token_count = mapping_for_fields.as_ref()
                                .and_then(|m| {
                                    let root = m.get("mappings").and_then(|mm| mm.get("properties"))
                                        .or_else(|| m.get("properties"))?;
                                    let segs: Vec<&str> = base.split('.').collect();
                                    let mut cur = root.clone();
                                    let mut spec: Option<Value> = None;
                                    for (i, seg) in segs.iter().enumerate() {
                                        let next = cur.get(*seg).cloned()?;
                                        if i == segs.len() - 1 {
                                            spec = Some(next);
                                        } else {
                                            cur = next.get("properties").cloned()?;
                                        }
                                    }
                                    let sub = spec?.get("fields")?
                                        .get(&name[dot+1..])?
                                        .get("type").and_then(Value::as_str)
                                        .map(str::to_string);
                                    sub
                                })
                                .map(|t| t == "token_count")
                                .unwrap_or(false);
                            if is_token_count {
                                let base_val = get_source_value_by_path(&h.source, base);
                                let count = |s: &str| -> i64 {
                                    s.split(|c: char| !c.is_alphanumeric())
                                        .filter(|t| !t.is_empty())
                                        .count() as i64
                                };
                                match base_val {
                                    Some(Value::String(s)) => Some(Value::Number(serde_json::Number::from(count(&s)))),
                                    Some(Value::Array(arr)) => {
                                        let counts: Vec<Value> = arr.iter().filter_map(|v| match v {
                                            Value::String(s) => Some(Value::Number(serde_json::Number::from(count(s)))),
                                            _ => None,
                                        }).collect();
                                        if counts.is_empty() { None } else { Some(Value::Array(counts)) }
                                    }
                                    _ => None,
                                }
                            } else {
                                None
                            }
                        } else {
                            raw
                        };
                        // #1940 stores the embedding as one `xerj:f32:` string.
                        // `fields` reports the vector the caller named, which
                        // is the number array — including `"_source": false`,
                        // where the engine keeps the packed source on purpose.
                        let raw = raw.map(expand_packed_embedding_value);
                        let arr_raw: Vec<Value> = match raw {
                            Some(Value::Array(a)) => a,
                            Some(Value::Null) | None => continue,
                            Some(v) => vec![v],
                        };
                        // Apply ignore_above: for keyword drop oversize
                        // elements; for flattened, prune oversize leaves
                        // within nested objects and drop the field when
                        // the whole scalar value is oversize.
                        let arr_raw: Vec<Value> = if let Some((max, ftype)) = field_ignore_above(name) {
                            let _ = &has_oversize_string; // keep the helper
                            match ftype {
                                "keyword" => arr_raw.into_iter().filter(|v| count_chars(v) <= max).collect(),
                                "flattened" => arr_raw.into_iter().filter_map(|v| prune_oversize(v, max)).collect(),
                                _ => arr_raw,
                            }
                        } else { arr_raw };
                        // Flattened fields surface from doc values sorted
                        // ascending under synthetic source mode only —
                        // outside synthetic mode ES preserves the source
                        // array order.
                        let arr_raw: Vec<Value> = if let Some((_, "flattened")) = field_ignore_above(name) {
                            let synthetic = settings_for_fields.as_ref().map(|s| {
                                let is_synth = |v: &Value| v.as_str() == Some("synthetic");
                                s.pointer("/index/mapping/source.mode").map(is_synth).unwrap_or(false)
                                    || s.pointer("/index/mapping.source.mode").map(is_synth).unwrap_or(false)
                                    || s.get("index").and_then(|i| i.get("mapping.source.mode")).map(is_synth).unwrap_or(false)
                                    || s.get("index.mapping.source.mode").map(is_synth).unwrap_or(false)
                                    || s.get("mapping.source.mode").map(is_synth).unwrap_or(false)
                            }).unwrap_or(false);
                            if synthetic {
                                fn sort_flat(v: &mut Value) {
                                    match v {
                                        Value::Array(arr) => {
                                            for e in arr.iter_mut() { sort_flat(e); }
                                            arr.sort_by(|a, b| match (a, b) {
                                                (Value::String(x), Value::String(y)) => x.cmp(y),
                                                _ => std::cmp::Ordering::Equal,
                                            });
                                        }
                                        Value::Object(o) => { for (_, val) in o { sort_flat(val); } }
                                        _ => {}
                                    }
                                }
                                arr_raw.into_iter().map(|mut v| { sort_flat(&mut v); v }).collect()
                            } else { arr_raw }
                        } else { arr_raw };
                        // Disabled-object flatten: when a field is
                        // declared `type: object, enabled: false`, ES
                        // emits ONE fmap entry per scalar leaf
                        // (sorted — numbers first, then strings, etc.)
                        // and hoists nested object keys to dotted
                        // sibling entries (`f1.a: [b]`).
                        let disabled_object_spec = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties"))
                                .or_else(|| m.get("properties")))
                            .and_then(|root| {
                                let segs: Vec<&str> = name.split('.').collect();
                                let mut cur = root.clone();
                                let mut spec: Option<Value> = None;
                                for (i, seg) in segs.iter().enumerate() {
                                    let next = cur.get(*seg).cloned()?;
                                    if i == segs.len() - 1 {
                                        spec = Some(next);
                                    } else {
                                        cur = next.get("properties").cloned()?;
                                    }
                                }
                                spec
                            })
                            .map(|s| {
                                s.get("type").and_then(Value::as_str) == Some("object")
                                    && s.get("enabled").and_then(Value::as_bool) == Some(false)
                            })
                            .unwrap_or(false);
                        if disabled_object_spec {
                            let mut scalars: Vec<Value> = Vec::new();
                            let mut dotted: std::collections::BTreeMap<String, Vec<Value>> = std::collections::BTreeMap::new();
                            fn walk(v: &Value, prefix: &str, scalars: &mut Vec<Value>, dotted: &mut std::collections::BTreeMap<String, Vec<Value>>) {
                                match v {
                                    Value::Array(a) => { for el in a { walk(el, prefix, scalars, dotted); } }
                                    Value::Object(o) => {
                                        for (k, vv) in o {
                                            let p = if prefix.is_empty() { k.clone() } else { format!("{}.{}", prefix, k) };
                                            walk(vv, &p, scalars, dotted);
                                        }
                                    }
                                    Value::Null => {}
                                    other => {
                                        if prefix.is_empty() {
                                            scalars.push(other.clone());
                                        } else {
                                            dotted.entry(prefix.to_string())
                                                .or_default()
                                                .push(other.clone());
                                        }
                                    }
                                }
                            }
                            for v in &arr_raw { walk(v, "", &mut scalars, &mut dotted); }
                            // Sort scalars: numbers first (asc), then
                            // strings (asc), then everything else.
                            scalars.sort_by(|a, b| {
                                let rank = |v: &Value| -> u8 { match v {
                                    Value::Number(_) => 0,
                                    Value::String(_) => 1,
                                    Value::Bool(_) => 2,
                                    _ => 3,
                                }};
                                match (rank(a), rank(b)) {
                                    (x, y) if x != y => x.cmp(&y),
                                    _ => match (a, b) {
                                        (Value::Number(x), Value::Number(y)) => {
                                            let xf = x.as_f64().unwrap_or(0.0);
                                            let yf = y.as_f64().unwrap_or(0.0);
                                            xf.partial_cmp(&yf).unwrap_or(std::cmp::Ordering::Equal)
                                        }
                                        (Value::String(x), Value::String(y)) => x.cmp(y),
                                        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
                                        _ => std::cmp::Ordering::Equal,
                                    }
                                }
                            });
                            if !scalars.is_empty() {
                                fmap.insert(name.clone(), Value::Array(scalars));
                            }
                            for (k, vs) in dotted {
                                let full = format!("{}.{}", name, k);
                                fmap.insert(full, Value::Array(vs));
                            }
                            continue;
                        }
                        if arr_raw.is_empty() { continue; }
                        // geo_point: ES fields-fetch serialises every
                        // form (`{lat,lon}`, `[lon,lat]`, `"lat,lon"`,
                        // `"POINT (lon lat)"`) as GeoJSON by default
                        // or as WKT when `format: wkt`. Reshape before
                        // the generic format-application step.
                        let is_geo_point = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties"))
                                .or_else(|| m.get("properties")))
                            .and_then(|p| p.get(name))
                            .and_then(|f| f.get("type"))
                            .and_then(Value::as_str)
                            == Some("geo_point");
                        let arr_raw: Vec<Value> = if is_geo_point {
                            let want_wkt = format.as_deref() == Some("wkt");
                            arr_raw.into_iter().map(|v| reshape_geo_point(&v, want_wkt)).collect()
                        } else {
                            arr_raw
                        };
                        // Apply `format` to date values when provided.
                        // (`wkt` and `geojson` on geo_point are
                        // already applied above — don't round-trip
                        // them through apply_field_format.)
                        let arr: Vec<Value> = if let Some(fmt) = format {
                            if is_geo_point {
                                arr_raw
                            } else {
                                arr_raw.into_iter().map(|v| apply_field_format(&v, fmt)).collect()
                            }
                        } else {
                            arr_raw
                        };
                        // Nested-type fields are NOT directly fetchable
                        // by their root path — ES returns no fields
                        // entry. Only their sub-paths get rendered
                        // (handled below via nested_ancestor). Skip the
                        // root-level emit so `fields: [products]` on a
                        // nested-typed `products` produces no entry.
                        if is_nested(name) {
                            // BUT a wildcard expansion that reached the
                            // nested root from `*` should still emit it
                            // as the leaf-grouped nested format —
                            // distinguish by checking whether the
                            // user-typed pattern was a wildcard.
                            if !field_name.contains('*') { continue; }
                            // Walk the mapping subtree starting at this
                            // nested field's `properties` so the
                            // wrapper can distinguish declared nested
                            // sub-fields (emit as array of objects),
                            // declared scalar leaves (wrap value in
                            // array; auto-add `<name>.keyword` for
                            // text/keyword), and unmapped object
                            // children (flatten to dotted keys —
                            // dynamic objects under a nested parent
                            // collapse the same way ES's fields-fetch
                            // does for synthetic source).
                            let nested_props: Value = mapping_for_fields.as_ref()
                                .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties"))
                                    .or_else(|| m.get("properties")))
                                .and_then(|root| {
                                    let mut cur = root.clone();
                                    for seg in name.split('.') {
                                        let next = cur.get(seg).cloned()?;
                                        cur = next.get("properties").cloned().unwrap_or(Value::Null);
                                        if cur.is_null() { return None; }
                                    }
                                    Some(cur)
                                })
                                .unwrap_or(Value::Null);
                            // When the user's wildcard restricts
                            // emission to a sub-pattern (e.g.
                            // `user.address*`), only emit keys whose
                            // sub-path matches. An empty rest means
                            // the whole-nested-root is requested (no
                            // sub-field filter) — leave key_filter
                            // as None so every wrapped key is emitted.
                            let key_filter: Option<String> = nested_root_pattern
                                .as_ref()
                                .filter(|(root, rest)| root == name && !rest.is_empty())
                                .map(|(_, rest)| rest.clone());
                            fn wrap_nested_element(
                                src: &Value,
                                props: &Value,
                            ) -> Value {
                                let Some(obj) = src.as_object() else {
                                    return Value::Array(vec![src.clone()]);
                                };
                                let mut out = serde_json::Map::new();
                                for (k, v) in obj {
                                    let spec = props.get(k);
                                    let ftype = spec.and_then(|s| s.get("type")).and_then(Value::as_str).unwrap_or("");
                                    let sub_props = spec.and_then(|s| s.get("properties")).cloned().unwrap_or(Value::Null);
                                    let sub_fields = spec.and_then(|s| s.get("fields")).and_then(Value::as_object);

                                    if ftype == "nested" {
                                        // Inner nested → emit as array
                                        // of recursively wrapped
                                        // objects.
                                        let arr: Vec<Value> = match v {
                                            Value::Array(a) => a.iter().map(|el| wrap_nested_element(el, &sub_props)).collect(),
                                            other => vec![wrap_nested_element(other, &sub_props)],
                                        };
                                        out.insert(k.clone(), Value::Array(arr));
                                        continue;
                                    }
                                    let is_disabled_object = ftype == "object"
                                        && spec.and_then(|s| s.get("enabled")).and_then(Value::as_bool) == Some(false);
                                    if spec.is_some() && sub_props.is_null() && !is_disabled_object {
                                        // Declared scalar leaf — wrap
                                        // in array. For string types
                                        // (text/keyword), surface
                                        // `<k>.keyword` siblings if
                                        // declared via `fields: {…}`.
                                        let value_arr = match v {
                                            Value::Array(a) => Value::Array(a.clone()),
                                            other => Value::Array(vec![other.clone()]),
                                        };
                                        out.insert(k.clone(), value_arr.clone());
                                        if let Some(sf) = sub_fields {
                                            for (sub_name, _sub_spec) in sf {
                                                let key = format!("{}.{}", k, sub_name);
                                                out.insert(key, value_arr.clone());
                                            }
                                        }
                                        continue;
                                    }
                                    if !sub_props.is_null() {
                                        // Declared object with
                                        // sub-properties (non-nested) —
                                        // recurse into the same
                                        // wrap_nested_element to
                                        // continue distinguishing inner
                                        // children.
                                        let inner = wrap_nested_element(v, &sub_props);
                                        out.insert(k.clone(), inner);
                                        continue;
                                    }
                                    // Unmapped child: dynamic. Flatten
                                    // an object value into dotted
                                    // sub-keys, preserving array form
                                    // for arrays.
                                    fn collect_dotted(prefix: &str, v: &Value, sink: &mut serde_json::Map<String, Value>) {
                                        match v {
                                            Value::Object(o) => {
                                                for (k2, vv) in o {
                                                    let next = if prefix.is_empty() {
                                                        k2.clone()
                                                    } else {
                                                        format!("{}.{}", prefix, k2)
                                                    };
                                                    collect_dotted(&next, vv, sink);
                                                }
                                            }
                                            Value::Array(arr) => {
                                                let all_objects = !arr.is_empty() && arr.iter().all(|x| x.is_object());
                                                if all_objects {
                                                    for el in arr {
                                                        collect_dotted(prefix, el, sink);
                                                    }
                                                } else {
                                                    let entry = sink.entry(prefix.to_string())
                                                        .or_insert_with(|| Value::Array(Vec::new()));
                                                    if let Value::Array(list) = entry {
                                                        for el in arr { list.push(el.clone()); }
                                                    }
                                                }
                                            }
                                            other => {
                                                let entry = sink.entry(prefix.to_string())
                                                    .or_insert_with(|| Value::Array(Vec::new()));
                                                if let Value::Array(list) = entry {
                                                    list.push(other.clone());
                                                }
                                            }
                                        }
                                    }
                                    let mut sink: serde_json::Map<String, Value> = serde_json::Map::new();
                                    collect_dotted(k, v, &mut sink);
                                    // Dynamic-mapped string leaves
                                    // auto-create `<path>.keyword`
                                    // multi-fields under ES's default
                                    // dynamic mapping. Mirror that for
                                    // nested-element leaves so the
                                    // fields-fetch surface matches.
                                    let extra: Vec<(String, Value)> = sink.iter()
                                        .filter_map(|(kk, vv)| {
                                            if kk.ends_with(".keyword") { return None; }
                                            let arr = vv.as_array()?;
                                            if arr.is_empty() || !arr.iter().all(|x| matches!(x, Value::String(_))) {
                                                return None;
                                            }
                                            let kw = format!("{}.keyword", kk);
                                            if sink.contains_key(&kw) { return None; }
                                            Some((kw, vv.clone()))
                                        })
                                        .collect();
                                    for (kk, vv) in sink {
                                        out.insert(kk, vv);
                                    }
                                    for (kk, vv) in extra {
                                        out.insert(kk, vv);
                                    }
                                }
                                Value::Object(out)
                            }
                            let wrapped: Vec<Value> = arr.into_iter()
                                .map(|el| {
                                    let mut wrapped = wrap_nested_element(&el, &nested_props);
                                    if let (Some(filter), Value::Object(obj)) = (key_filter.as_ref(), &mut wrapped) {
                                        let keys: Vec<String> = obj.keys().cloned().collect();
                                        for k in keys {
                                            if !wildcard_match(filter, &k) {
                                                obj.remove(&k);
                                            }
                                        }
                                    }
                                    wrapped
                                })
                                .filter(|w| match w {
                                    Value::Object(o) => !o.is_empty(),
                                    _ => true,
                                })
                                .collect();
                            fmap.insert(name.clone(), Value::Array(wrapped));
                            continue;
                        }
                        let arr: Vec<Value> = arr;
                        // Sub-field of a nested field? Group under the
                        // nested parent: ES emits e.g. `fields.products`
                        // as an array of objects, each object holding
                        // the requested sub-fields wrapped in arrays.
                        // Multiple requested sub-fields merge into the
                        // same parent group.
                        if let Some((nested_path, sub_path)) = nested_ancestor(name) {
                            // Walk + literal-dotted union for source
                            // values at the nested path. ES merges
                            // both forms when both exist (the user
                            // wrote both `obj: { products: [...] }`
                            // and `"obj.products": [...]` in the
                            // doc).
                            let np_parts: Vec<&str> = nested_path.split('.').collect();
                            let walked = get_field_value_via_walk(&h.source, &np_parts);
                            let literal = h.source.as_object()
                                .and_then(|o| o.get(&nested_path))
                                .cloned();
                            let nested_raw = match (walked, literal) {
                                (Some(Value::Array(a)), Some(Value::Array(b))) => {
                                    let mut m = a; m.extend(b); Value::Array(m)
                                }
                                (Some(a), Some(b)) => {
                                    let mut m = match a { Value::Array(arr) => arr, x => vec![x] };
                                    match b { Value::Array(arr) => m.extend(arr), x => m.push(x) }
                                    Value::Array(m)
                                }
                                (Some(v), None) | (None, Some(v)) => v,
                                _ => Value::Null,
                            };
                            let elements: Vec<Value> = match nested_raw {
                                Value::Array(a) => a,
                                Value::Object(_) => vec![nested_raw],
                                _ => Vec::new(),
                            };
                            let parent_entry = fmap
                                .entry(nested_path.clone())
                                .or_insert_with(|| Value::Array(Vec::new()));
                            let parent_arr = match parent_entry.as_array_mut() {
                                Some(a) => a,
                                None => continue,
                            };
                            // Resize parent_arr to match elements.len().
                            while parent_arr.len() < elements.len() {
                                parent_arr.push(Value::Object(serde_json::Map::new()));
                            }
                            for (i, elem) in elements.iter().enumerate() {
                                let sub_val = elem.get(&sub_path).cloned();
                                if let Some(v) = sub_val {
                                    let as_array = match v {
                                        Value::Array(a) => Value::Array(a),
                                        other => Value::Array(vec![other]),
                                    };
                                    if let Value::Object(obj) = &mut parent_arr[i] {
                                        obj.insert(sub_path.clone(), as_array);
                                    }
                                }
                            }
                            // Drop empty parent objects (elements with
                            // no requested sub-fields present).
                            parent_arr.retain(|v| match v {
                                Value::Object(o) => !o.is_empty(),
                                _ => true,
                            });
                            continue;
                        }
                        fmap.insert(name.clone(), Value::Array(arr));
                    }
                }

                // docvalue_fields.
                if !docvalue_fields.is_empty() {
                    if let Some(dv) = build_docvalue_fields(&h.source, &docvalue_fields) {
                        fmap.extend(dv);
                    }
                }

                // stored_fields meta (_id, _routing etc.).
                if !stored_meta_fields.is_empty() {
                    // Look up mapping for the current index so we can check
                    // `store: true` on each requested field. ES's
                    // `stored_fields` only emits a field when it was mapped
                    // with `store: true`; requesting a non-stored field
                    // yields `{field: null}` (not an empty array), which
                    // the YAML runner treats as "field absent".
                    let mapping = state
                        .engine
                        .index_mappings
                        .get(idx_name.as_str())
                        .map(|v| v.clone());
                    let is_stored = |field: &str| -> bool {
                        mapping
                            .as_ref()
                            .and_then(|m| m.get("properties"))
                            .and_then(|p| p.get(field))
                            .and_then(|fp| fp.get("store"))
                            .and_then(Value::as_bool)
                            .unwrap_or(false)
                    };
                    for meta in &stored_meta_fields {
                        match meta.as_str() {
                            "_id" => { fmap.insert("_id".to_string(), Value::Array(vec![Value::String(h.id.clone())])); }
                            "_index" => { fmap.insert("_index".to_string(), Value::Array(vec![Value::String(idx_name.clone())])); }
                            "_ignored" | "_seq_no" | "_primary_term" | "_version" | "_routing" => {
                                // ES treats these as hit-level meta fields —
                                // requesting them via stored_fields surfaces
                                // the hit-level _ignored / _seq_no / … fields
                                // but does NOT mirror into hit.fields.
                            }
                            other => {
                                if is_stored(other) {
                                    if let Some(raw) = get_source_value_by_path(&h.source, other) {
                                        let raw = expand_packed_embedding_value(raw);
                                        let arr = match raw {
                                            Value::Array(a) => a,
                                            Value::Null => continue,
                                            v => vec![v],
                                        };
                                        fmap.insert(other.to_string(), Value::Array(arr));
                                    }
                                }
                                // Non-stored fields: skip — emitting
                                // `[null]` would confuse strict `match: null`
                                // assertions.
                            }
                        }
                    }
                }

                // Collapse auto-emits the collapse field into hit.fields
                // regardless of the `fields` clause (ES behavior).
                if let Some(ref cf) = search_req.collapse {
                    // The user-requested key for `fields.<X>`: prefer the
                    // pre-rewrite alias name when one was provided, so the
                    // response key matches the caller's collapse spec.
                    let response_key: String = alias_map
                        .iter()
                        .find_map(|(orig, target)| if target == &cf.field { Some(orig.clone()) } else { None })
                        .unwrap_or_else(|| cf.field.clone());
                    // `response_key` is read again inside this block (and only
                    // conditionally inserted), so the Entry API would tangle the
                    // borrow / force an extra clone — keep the explicit check.
                    #[allow(clippy::map_entry)]
                    if !fmap.contains_key(&response_key) {
                        // Look up the value from `_source` under any of:
                        //   1. the literal collapse field (covers indices
                        //      that store the collapse field directly),
                        //   2. the alias-rewrite target if `cf.field` is
                        //      itself an alias (covers indices that store
                        //      the target — e.g. alias-test's
                        //      `numeric_group` → `other_numeric_group`),
                        //   3. the response_key (covers the inverse case
                        //      where the user spec already names the alias
                        //      target).
                        let target_via_alias = alias_map.get(&cf.field);
                        let raw = get_source_value_by_path(&h.source, &cf.field)
                            .or_else(|| target_via_alias.and_then(|t| get_source_value_by_path(&h.source, t)))
                            .or_else(|| get_source_value_by_path(&h.source, &response_key));
                        if let Some(raw) = raw {
                            let raw = expand_packed_embedding_value(raw);
                            let arr = match raw {
                                Value::Array(a) => a,
                                Value::Null => vec![],
                                v => vec![v],
                            };
                            if !arr.is_empty() {
                                fmap.insert(response_key, Value::Array(arr));
                            }
                        }
                    }
                }

                // ES fields-fetch enumerates doc_values in sorted order
                // only for copy_to TARGETS (where the target values come
                // from re-indexed per-source contributions). Plain
                // keyword/numeric fields preserve the source-array order
                // in the `fields` response. Identify copy_to targets via
                // the __xy_copy_to_pristine__ sentinel baked into the
                // source by apply_copy_to.
                let copy_to_targets: Vec<String> = h.source
                    .get("__xy_copy_to_pristine__")
                    .and_then(Value::as_object)
                    .map(|o| o.keys().cloned().collect())
                    .unwrap_or_default();
                for (fname, fval) in fmap.iter_mut() {
                    // A copy_to target carries a sorted/deduped
                    // doc_values enumeration. Match either the target
                    // itself or a `.keyword` sub-field of it — keyword
                    // multi-fields inherit the same doc_values order.
                    let base_name = fname.strip_suffix(".keyword").unwrap_or(fname);
                    if !copy_to_targets.iter().any(|t| t == fname || t == base_name) { continue; }
                    // Resolve the declared type by walking dotted segments
                    // through properties/<seg> trees so nested fields
                    // (e.g. c.copy where c is object) still find their
                    // type: keyword leaf.
                    let declared_type: String = {
                        let root_props = mapping_for_fields.as_ref()
                            .and_then(|m| m.get("mappings").and_then(|mm| mm.get("properties")).or_else(|| m.get("properties")))
                            .cloned()
                            .unwrap_or(Value::Null);
                        let mut cur = root_props;
                        let segs: Vec<&str> = fname.split('.').collect();
                        let last = segs.len() - 1;
                        let mut found = String::new();
                        for (i, seg) in segs.iter().enumerate() {
                            let Some(next) = cur.get(*seg).cloned() else { break };
                            if i == last {
                                if let Some(t) = next.get("type").and_then(Value::as_str) {
                                    found = t.to_string();
                                }
                            } else if let Some(p) = next.get("properties").cloned() {
                                cur = p;
                            } else { break; }
                        }
                        found
                    };
                    let declared_type = declared_type.as_str();
                    // Keyword/text copy_to targets stringify non-string
                    // inputs (booleans → "true"/"false", numbers → their
                    // JSON representation) and flatten one level of
                    // nested arrays that apply_copy_to may have produced
                    // when multiple source fields contributed.
                    if matches!(declared_type, "keyword" | "text" | "constant_keyword" | "wildcard") {
                        if let Value::Array(arr) = fval {
                            let mut flat: Vec<Value> = Vec::new();
                            for v in arr.drain(..) {
                                match v {
                                    Value::Array(inner) => {
                                        for iv in inner {
                                            flat.push(stringify_for_keyword(iv));
                                        }
                                    }
                                    other => flat.push(stringify_for_keyword(other)),
                                }
                            }
                            *arr = flat;
                        }
                    } else if let Value::Array(arr) = fval {
                        // Numeric/boolean etc targets: just flatten
                        // one level of nested arrays so downstream sort
                        // sees primitives.
                        let needs_flatten = arr.iter().any(|v| v.is_array());
                        if needs_flatten {
                            let mut flat: Vec<Value> = Vec::new();
                            for v in arr.drain(..) {
                                match v {
                                    Value::Array(inner) => flat.extend(inner),
                                    other => flat.push(other),
                                }
                            }
                            *arr = flat;
                        }
                    }
                    if let Value::Array(arr) = fval {
                        let all_primitive = arr.iter().all(|v| matches!(v, Value::Number(_) | Value::String(_) | Value::Bool(_)));
                        if all_primitive && arr.len() > 1 {
                            arr.sort_by(|a, b| match (a, b) {
                                (Value::Number(x), Value::Number(y)) => {
                                    let xf = x.as_f64().unwrap_or(0.0);
                                    let yf = y.as_f64().unwrap_or(0.0);
                                    xf.partial_cmp(&yf).unwrap_or(std::cmp::Ordering::Equal)
                                }
                                (Value::String(x), Value::String(y)) => x.cmp(y),
                                (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
                                _ => std::cmp::Ordering::Equal,
                            });
                        }
                    }
                }
                // script_fields: evaluate each field's Painless script against
                // THIS hit's source and merge the (array-wrapped) result into
                // `fields`, exactly like ES. The same interpreter backs
                // `script_score`, scripted updates, and `_painless_execute`.
                // Evaluating against `h.source` (not the response `_source`)
                // means script_fields still work when `_source` is filtered out
                // of the response. A script that errors surfaces no value for
                // that field (we keep the hit valid rather than failing the
                // whole search).
                if let Some(sf_obj) = search_req.script_fields.as_ref().and_then(Value::as_object) {
                    for (fname, spec) in sf_obj {
                        let Some(script) = spec.get("script") else { continue };
                        let Some(source) = script
                            .get("source")
                            .or_else(|| script.get("inline"))
                            .and_then(Value::as_str)
                        else {
                            continue;
                        };
                        let empty_params = Value::Object(serde_json::Map::new());
                        let params = script.get("params").unwrap_or(&empty_params);
                        let ctx = xerj_engine::painless::PainlessCtx::new(
                            &h.source, params, h.score,
                        );
                        if let Ok(pv) = xerj_engine::painless::eval_painless(source, &ctx) {
                            // ES wraps script-field results in an array; a script
                            // that returns an array is emitted as-is, and a null
                            // result yields an empty array (no phantom `null`).
                            let arr = match painless_to_json(pv) {
                                Value::Array(a) => Value::Array(a),
                                Value::Null => Value::Array(vec![]),
                                other => Value::Array(vec![other]),
                            };
                            fmap.insert(fname.clone(), arr);
                        }
                    }
                }
                // XERJ's opt-in semantic provenance pseudo-field. Keeping it
                // under the standard ES `fields` envelope preserves the
                // default hit wire shape and lets ES clients request it
                // without a separate response dialect.
                if field_specs.iter().any(|(name, _, _)| name == "_passage") {
                    if let Some(passage) = &h.passage {
                        if let Ok(value) = serde_json::to_value(passage) {
                            fmap.insert("_passage".to_string(), Value::Array(vec![value]));
                        }
                    }
                }
                // When the index has `_source.enabled: false`, ES 8.4+
                // only returns metadata fields (_id, _index, _score) in
                // the fields response — non-meta fields are not
                // retrievable since there's no source to read from (and
                // we don't maintain separate stored-fields). Match that
                // behaviour so `length: hits.hits.0.fields: 1` passes
                // when only `_id` survives the filter.
                if source_mapping_disabled {
                    fmap.retain(|k, _| k.starts_with('_'));
                }
                if fmap.is_empty() { None } else { Some(fmap) }
            };

            // Build inner_hits if configured.
            let mut hit_inner_hits = if !inner_hits_config.is_null() {
                let ih = build_inner_hits(&h.source, &h.id, &idx_name, &inner_hits_config);
                if ih.is_null() || (ih.is_object() && ih.as_object().map(|o| o.is_empty()).unwrap_or(true)) {
                    None
                } else {
                    Some(ih)
                }
            } else {
                None
            };
            // If this hit carries a collapse group, render it under
            // `inner_hits.<name>` honoring each spec's `size` and `sort`.
            // The spec may be a single object or an array of objects so
            // tests can declare multiple named inner_hits per collapse.
            if let (Some(group), Some(spec)) = (collapse_group, collapse_spec) {
                hit_inner_hits = Some(render_collapse_inner_hits(
                    group,
                    spec,
                    &idx_name,
                    params.rest_total_hits_as_int.as_deref() == Some("true"),
                    // #646: under the default projection, strip the generated
                    // companions from each member's `_source` — the members were
                    // stashed before #309 ran. Gated on `!is_scroll_request` so a
                    // collapse SCROLL stays byte-identical across pages (#623):
                    // the continuation path (scroll_page_response) cannot strip
                    // companions yet, so page 1 must not either — scroll+collapse
                    // companion stripping is the clean remaining sub-case.
                    if default_source_projection && !is_scroll_request {
                        companions_by_index.get(idx_name.as_str())
                    } else {
                        None
                    },
                ));
            }

            // Real seq_no (and a placeholder primary_term of 1), read from
            // the hit itself — resolved at construction time in the engine,
            // from the same read as `_source`, not a later live re-lookup
            // here (#440).
            // #603: emit `_version`/`_seq_no`/`_primary_term` only when the
            // engine resolved them; an absent value is omitted, never
            // fabricated into a positional index or a default `1`.
            let (real_version, real_seq_no, real_primary_term) =
                resolve_hit_versioning(h.seq_no, h.version, emit_seq_no, emit_version);
            EsHit {
                index: idx_name.clone(),
                id: h.id.clone(),
                // ES only computes (and emits) per-hit `_score` when scores
                // are tracked: no sort (a pure `_score` DESC sort was
                // normalized to "no sort" at parse), an explicit
                // `track_scores: true`, or `_score` appearing among the
                // sort keys. Field-sorted hits otherwise carry
                // `_score: null` (live-verified on ES 8.13.4 — the B4
                // "sort-heavy _score-vs-null" wire divergence).
                score: if search_req.sort.is_empty()
                    || body.track_scores.unwrap_or(false)
                    || search_req.sort.iter().any(|s| s.is_score())
                {
                    Some(score_wire(h.score))
                } else {
                    None
                },
                // Per-doc `_version`/`_seq_no`/`_primary_term` are read from the
                // hit itself — resolved at construction time in the engine (the
                // external-version map wins so `version_type=external[_gte]`
                // reindexes echo the caller's value; then the write counter),
                // not a later live re-lookup here (#440). An absent value is
                // omitted, never fabricated (#603) — see `resolve_hit_versioning`.
                version: real_version,
                seq_no: real_seq_no,
                primary_term: real_primary_term,
                source,
                fields: fields_map,
                // No requested sort (incl. a pure `_score` DESC sort
                // normalized away at parse) → no `sort` arrays on the wire,
                // even when the engine's internal score-ranked collector
                // populated `h.sort` (ES emits none for score-sorted hits).
                sort: if h.sort.is_empty() || search_req.sort.is_empty() {
                    None
                } else {
                    // Apply each SortField's `format` (e.g.
                    // `strict_date_optional_time_nanos`) to the raw sort
                    // value — epoch-ms/ns numbers become ISO-8601 strings.
                    let mapping_props = state
                        .engine
                        .index_mappings
                        .get(&idx_name)
                        .and_then(|v| {
                            v.get("mappings")
                                .and_then(|m| m.get("properties"))
                                .or_else(|| v.get("properties"))
                                .cloned()
                        });
                    let formatted: Vec<Value> = h
                        .sort
                        .iter()
                        .enumerate()
                        .map(|(i, raw)| {
                            let spec = search_req.sort.get(i);
                            // ES emits numeric MAX/MIN sentinels for missing
                            // sort values. Pick the sentinel based on the
                            // field's mapping type so int/short/byte sort
                            // last with Int.MAX_VALUE and long with
                            // Long.MAX_VALUE.
                            if raw.is_null() {
                                if let Some(sf) = spec {
                                    let ftype = mapping_props
                                        .as_ref()
                                        .and_then(|p| p.get(&sf.field))
                                        .and_then(|fp| fp.get("type"))
                                        .and_then(Value::as_str);
                                    let want_max = matches!(
                                        sf.missing,
                                        xerj_query::sort::SortMissing::Last
                                    );
                                    let sentinel: Option<i64> = match ftype {
                                        Some("integer") | Some("short") | Some("byte") => {
                                            if want_max { Some(i32::MAX as i64) } else { Some(i32::MIN as i64) }
                                        }
                                        Some("long") | Some("unsigned_long") => {
                                            if want_max { Some(i64::MAX) } else { Some(i64::MIN) }
                                        }
                                        _ => None,
                                    };
                                    if let Some(s) = sentinel {
                                        return Value::Number(serde_json::Number::from(s));
                                    }
                                }
                            }
                            format_sort_value(raw, spec.and_then(|s| s.format.as_deref()))
                        })
                        .collect();
                    Some(formatted)
                },
                highlight: h.highlight.clone(),
                explanation,
                inner_hits: hit_inner_hits,
                matched_queries: build_matched_queries_value(
                    &h.matched_queries,
                    body.query.as_ref(),
                    params.include_named_queries_score.as_deref() == Some("true"),
                    Some(h.score as f64),
                ),
                ignored: ignored_list,
                ignored_field_values,
                p_relevant: None,
            }
        })
        .collect();

    // Phrase suggester is not implemented. Detect it and fail loudly with a
    // clear 400 rather than silently defaulting its field to `_all`, scanning
    // for a nonexistent field, and emitting empty/garbage term-style output.
    // Completion and term suggesters are supported.
    if let Some(sobj) = body.suggest.as_ref().and_then(Value::as_object) {
        if sobj.values().any(|d| d.get("phrase").is_some()) {
            let reason = "phrase suggester is not supported by XERJ; supported suggesters are \
                          `completion` and `term`";
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": {
                        "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                        "type": "illegal_argument_exception",
                        "reason": reason,
                    },
                    "status": 400,
                })),
            )
                .into_response();
        }
    }

    // Process suggest block if present.
    let suggest_result = if let Some(ref suggest_body) = body.suggest {
        // Gather field-level indexed terms from all indices for suggest processing.
        // This uses the FTS inverted index for accurate term frequencies rather than
        // re-scanning document sources — much more efficient and accurate.
        let index_terms = {
            // Determine which fields are requested by the suggest block.
            let mut fields: Vec<String> = Vec::new();
            if let Some(obj) = suggest_body.as_object() {
                for (_, suggest_def) in obj {
                    if let Some(completion_opts) = suggest_def.get("completion") {
                        if let Some(f) = completion_opts.get("field").and_then(Value::as_str) {
                            fields.push(f.to_string());
                        }
                    }
                    if let Some(term_opts) = suggest_def.get("term") {
                        if let Some(f) = term_opts.get("field").and_then(Value::as_str) {
                            fields.push(f.to_string());
                        }
                    }
                }
            }
            fields.dedup();

            let mut all_terms: std::collections::HashMap<String, Vec<(String, usize)>> =
                std::collections::HashMap::new();
            for field in &fields {
                let mut combined: std::collections::HashMap<String, usize> =
                    std::collections::HashMap::new();
                for idx_name in &index_names {
                    if let Ok(idx) = state.engine.get_index(idx_name) {
                        for (term, freq) in idx.get_all_terms_for_field(field).await {
                            *combined.entry(term).or_insert(0) += freq;
                        }
                    }
                }
                all_terms.insert(field.clone(), combined.into_iter().collect());
            }
            all_terms
        };

        // Also collect doc sources for backward-compatible completion suggester.
        let all_docs: Vec<Value> = {
            let suggest_req = match xerj_query::parse_request(
                &json!({"query": {"match_all": {}}, "size": 1000, "from": 0}),
            ) {
                Ok(r) => r,
                Err(_) => xerj_query::parse_request(&json!({"size": 1000})).unwrap_or_default(),
            };
            let mut all = Vec::new();
            for idx_name in &index_names {
                if let Ok(idx) = state.engine.get_index(idx_name) {
                    if let Ok(result) = idx.search(&suggest_req).await {
                        for hit in result.hits {
                            if !hit.source.is_null() {
                                all.push(hit.source);
                            }
                        }
                    }
                }
            }
            all
        };
        Some(process_suggest_with_terms(
            suggest_body,
            &all_docs,
            &index_terms,
        ))
    } else {
        None
    };

    // ES: when `track_total_hits: false` (or `0`), the `hits.total` field
    // is omitted entirely (unless the caller asked for
    // `rest_total_hits_as_int=true`, in which case it's rendered as the
    // sentinel `-1`). Otherwise we emit the usual {value, relation} object.
    let track_total_disabled = match body.track_total_hits.as_ref() {
        Some(Value::Bool(false)) => true,
        Some(Value::Number(n)) => n.as_i64() == Some(0),
        _ => false,
    };

    // `track_total_hits: <N>` caps the returned total at N across all
    // indices. Each per-index search already applies its own cap; but
    // the sum can exceed N so we re-apply after the cross-index merge.
    if let Some(Value::Number(n)) = body.track_total_hits.as_ref() {
        if let Some(limit) = n.as_u64() {
            if limit > 0 && total_count > limit {
                total_count = limit;
                total_relation = "gte".to_string();
            }
        }
    }
    let want_int_total = params.rest_total_hits_as_int.as_deref() == Some("true");

    // `_shards.total` is the per-index shard count summed over every
    // participating index so multi-index searches expose N shards,
    // matching ES's per-primary numbers (xerj has one primary per index).
    let shards_total: u32 = index_names
        .iter()
        .map(|n| {
            let s: &str = n;
            state
                .engine
                .index_settings
                .get(s)
                .and_then(|v| {
                    v.get("index")
                        .and_then(|ix| ix.get("number_of_shards"))
                        .or_else(|| v.get("number_of_shards"))
                        .or_else(|| v.get("index.number_of_shards"))
                        .and_then(|x| match x {
                            Value::Number(x) => x.as_u64(),
                            Value::String(s) => s.parse::<u64>().ok(),
                            _ => None,
                        })
                })
                .unwrap_or(1) as u32
        })
        .sum::<u32>()
        .max(1);
    let mut shards_block = crate::responses::EsShards::search_success_n(shards_total);
    if shards_failed_count > 0 {
        let total = shards_block.total.max(shards_failed_count);
        shards_block.total = total;
        shards_block.successful = total.saturating_sub(shards_failed_count);
        shards_block.failed = shards_failed_count;
    }

    // ── rerank stage ────────────────────────────────────────────────────────
    // Runs on the rendered hits, so everything a hit carries — `highlight`,
    // `fields`, `inner_hits`, `matched_queries`, `_ignored` — moves with it.
    // Runs BEFORE the response hints and the `_savings` re-sum below, because
    // both describe the page this response actually emits and the stage is
    // what cuts the widened window back down to that page. `hits.total` and
    // `aggregations` are deliberately untouched: they describe the full match
    // set, not the window.
    let mut hits = hits;
    let mut max_score = max_score;
    let mut took_ms = took_ms;
    let mut savings_claim = savings_claim;
    let rerank_info = match &rerank_plan {
        None => None,
        Some(plan) => {
            let applied = plan.apply(&state.rerank, &mut hits, &mut max_score).await;
            crate::rerank_stage::record_outcome(&state.metrics, &applied);
            match applied {
                Ok(info) => {
                    // Hand the caller's own page back to everything downstream
                    // that reads it (`terminated_early`, the payload hint's
                    // suggested request) — the widening was the stage's business.
                    let (from, size) = plan.requested_page();
                    body.from = from;
                    body.size = size;
                    // `took` is what the caller waited, and the provider call is
                    // most of it. The engine-only figure was already recorded in
                    // the latency histograms above, which is where it belongs.
                    took_ms = started.elapsed().as_millis() as u64;
                    // `_savings` is summed over the hits a response emits; the
                    // earlier sum was over the whole window.
                    if let Some((record, _)) = savings_claim {
                        let emitted: u64 = hits
                            .iter()
                            .filter_map(|h| savings_by_hit.get(&(h.index.clone(), h.id.clone())))
                            .sum();
                        savings_claim = Some((record, emitted));
                    }
                    Some(info)
                }
                Err(e) => {
                    let status = crate::rerank_stage::status_for(&e);
                    let kind = crate::rerank_stage::error_type_for(&e);
                    let reason = format!("rerank failed: {e}");
                    return (
                        StatusCode::from_u16(status).unwrap_or(StatusCode::BAD_GATEWAY),
                        Json(json!({
                            "error": {
                                "root_cause": [{ "type": kind, "reason": reason }],
                                "type": kind,
                                "reason": reason,
                            },
                            "status": status,
                        })),
                    )
                        .into_response();
                }
            }
        }
    };

    // ── judge stage ────────────────────────────────────────────────────────
    // Opt-in local judging (issue #1060). Runs AFTER the rerank stage, so it
    // judges the page this response actually emits: the two blocks compose
    // (the hosted rerank widens and reorders its window, the local judge then
    // re-judges and prunes the emitted page) and each stands alone. The
    // engine's — or the hosted provider's — `_score` stays untouched on every
    // hit; the judge adds `_p_relevant` and may drop hits below `min_p`,
    // which is why `took` and the `_savings` sum are re-stamped here too.
    let judged_info = match &judge_plan {
        None => None,
        Some(plan) => {
            let applied = plan.apply(&state.decide, &mut hits, &mut max_score).await;
            match applied {
                Ok(info) => {
                    took_ms = started.elapsed().as_millis() as u64;
                    // `_savings` is summed over the hits a response emits; a
                    // `min_p` drop removed some.
                    if let Some((record, _)) = savings_claim {
                        let emitted: u64 = hits
                            .iter()
                            .filter_map(|h| savings_by_hit.get(&(h.index.clone(), h.id.clone())))
                            .sum();
                        savings_claim = Some((record, emitted));
                    }
                    Some(info)
                }
                Err(e) => {
                    let status = crate::judge_stage::status_for(&e);
                    let kind = crate::judge_stage::error_type_for(&e);
                    let reason = format!("judge failed: {e}");
                    return (
                        StatusCode::from_u16(status).unwrap_or(StatusCode::BAD_GATEWAY),
                        Json(json!({
                            "error": {
                                "root_cause": [{ "type": kind, "reason": reason }],
                                "type": kind,
                                "reason": reason,
                            },
                            "status": status,
                        })),
                    )
                        .into_response();
                }
            }
        }
    };

    // Computed before `hits` is moved into `response_body` below.
    // Two independent diagnostics, merged into one `hints` array rather than
    // one winning: a query can both name a nonexistent field AND return an
    // oversized payload, and reporting only the first would hide the other.
    //
    // The unknown-field check runs whether or not there were hits. A bogus
    // field inside a `multi_match` that also names a real one is the worst
    // shape of all — it returns plenty of results, silently searching fewer
    // fields than asked, so the caller has no signal at all.
    let mut all_hints: Vec<Value> = Vec::new();
    // #2121: every matched index, not whichever name was resolved first.
    // `xerj search` / `xerj_search` send one body at the whole prefix pattern;
    // a field that any of those indices maps is a real target.
    // A body with no query names no fields, so it skips the per-index reads.
    let hint_schemas: Vec<xerj_common::types::Schema> = if body.query.is_none() {
        Vec::new()
    } else {
        let mut out = Vec::with_capacity(index_names.len());
        for name in &index_names {
            if let Ok(idx) = state.engine.get_index(name) {
                out.push(idx.schema().await);
            }
        }
        out
    };
    if !hint_schemas.is_empty() {
        let refs: Vec<&xerj_common::types::Schema> = hint_schemas.iter().collect();
        if let Some(h) = unknown_field_hint(&index, &body, &refs) {
            if let Some(Value::Array(items)) = h.get("hints") {
                all_hints.extend(items.iter().cloned());
            }
        }
    }
    if let Some(first) = index_names.first() {
        if let Ok(idx) = state.engine.get_index(first) {
            let schema = idx.schema().await;
            // A zero-hit exact filter on a real keyword field is nearly always
            // a wrong-value guess rather than a genuine absence, and the reply
            // gives no way to tell which. Sample a bounded slice of documents
            // and name the values that do exist. Only on zero hits, only for
            // exact clauses, and capped — this must never cost anything on a
            // query that worked.
            //
            // #2451: "zero hits" means the MATCH SET is empty, not the page. A
            // `size: 0` request (a count or existence probe — autoindex's
            // per-upsert `index_holds_content` is one) always has an empty
            // page, so gating on `hits.is_empty()` alone ran the 256-row
            // `match_all` sample — a full-source decode of ~356 rows, 1.4 s on
            // a 234k-doc code index — after EVERY probe, hit or miss. The
            // sample is for a caller who asked for hits and got none.
            if all_hints.is_empty()
                && zero_hit_value_sample_applies(
                    body.size,
                    hits.is_empty(),
                    total_count,
                    track_total_disabled,
                )
            {
                let mut clauses = Vec::new();
                if let Some(q) = body.query.as_ref() {
                    exact_term_clauses(q, &mut clauses);
                }
                for (field, value) in clauses.into_iter().take(2) {
                    let base = field.split('.').next().unwrap_or(&field).to_string();
                    let is_keyword = schema.field(&base).is_some_and(|f| {
                        matches!(f.field_type, xerj_common::types::FieldType::Keyword)
                    });
                    if !is_keyword {
                        continue;
                    }
                    let Ok(sample_req) = xerj_query::parse_request(
                        &json!({"query": {"match_all": {}}, "size": 256}),
                    ) else {
                        continue;
                    };
                    let Ok(sample) = idx.search(&sample_req).await else {
                        continue;
                    };
                    let mut seen = std::collections::BTreeSet::new();
                    for hit in &sample.hits {
                        if let Some(v) = hit.source.get(&base).and_then(Value::as_str) {
                            seen.insert(v.to_string());
                        }
                    }
                    // High-cardinality fields (ids, paths) would produce a
                    // useless wall of values; only enumerate a real taxonomy.
                    if seen.is_empty() || seen.len() > 25 || seen.contains(&value) {
                        continue;
                    }
                    let present: Vec<String> = seen.into_iter().collect();
                    if let Some(Value::Array(items)) =
                        unknown_value_hint(&index, &base, &value, &present).get("hints")
                    {
                        all_hints.extend(items.iter().cloned());
                    }
                    break;
                }
            }
            // Last of the schema-derived diagnostics, deliberately: it fires
            // on queries that returned plenty of hits, so running it earlier
            // would starve the zero-hit checks above of their
            // `all_hints.is_empty()` window.
            if let Some(h) = lexical_on_semantic_text_hint(&index, &body, &schema) {
                if let Some(Value::Array(items)) = h.get("hints") {
                    all_hints.extend(items.iter().cloned());
                }
            }
        }
    }
    if let Some(h) = search_response_hint(&index, &body, &hits) {
        if let Some(Value::Array(items)) = h.get("hints") {
            all_hints.extend(items.iter().cloned());
        }
    }
    let response_hint = (!all_hints.is_empty()).then(|| json!({ "hints": all_hints }));

    let mut response_body = if track_total_disabled {
        if want_int_total {
            json!({
                "took": took_ms,
                "timed_out": any_timed_out,
                "_shards": shards_block,
                "hits": {
                    "total": -1i64,
                    "max_score": max_score,
                    "hits": hits,
                },
            })
        } else {
            json!({
                "took": took_ms,
                "timed_out": any_timed_out,
                "_shards": shards_block,
                "hits": {
                    "max_score": max_score,
                    "hits": hits,
                },
            })
        }
    } else {
        json!({
            "took": took_ms,
            "timed_out": any_timed_out,
            "_shards": shards_block,
            "hits": {
                "total": {
                    "value": total_count as i64,
                    "relation": total_relation,
                },
                "max_score": max_score,
                "hits": hits,
            },
        })
    };

    // PIT searches echo the (still-valid) `pit_id` back in the response —
    // ES 8.x places it as the FIRST key, before `took` (live-verified on
    // 8.13.4).  Clients' PIT + search_after loops read the id off every
    // page and thread it into the next request, so omitting it breaks the
    // canonical pagination pattern (ES helpers fail with a missing-pit_id
    // error).  xerj PIT ids are stable, so the echoed id is the request id.
    if pit_context.is_some() {
        if let Some(pit_id) = body
            .pit
            .as_ref()
            .and_then(|p| p.get("id"))
            .and_then(Value::as_str)
        {
            if let Some(obj) = response_body.as_object_mut() {
                let mut rebuilt = serde_json::Map::with_capacity(obj.len() + 1);
                rebuilt.insert("pit_id".to_string(), Value::String(pit_id.to_string()));
                for (k, v) in obj.iter() {
                    rebuilt.insert(k.clone(), v.clone());
                }
                *obj = rebuilt;
            }
        }
    }

    // Additive, ES-unrecognized field carrying an actionable hint (see
    // `search_response_hint`). MUST land before `hits` — and as early as
    // possible overall — because an agent reading this response truncates
    // long output from the bottom, so a hint trailing a multi-hundred-KB
    // `hits` array is never seen. `pit_id` (above) is the one key ES itself
    // places before `took`, so this splices in right after it, ahead of
    // everything else including `hits`. `serde_json` runs with
    // `preserve_order` workspace-wide (see xerj-common/Cargo.toml), so the
    // rebuilt map's insertion order is exactly the wire order.
    // `_rerank` says which ranking the caller is looking at — applied, or the
    // engine's own after a degrade. It goes ahead of `hits` for the same reason
    // the hint below does: a reader that truncates long output from the bottom
    // must still see it.
    // `judged` says the same thing about the local judge's pass — which
    // scorer judged, what was kept and what was dropped — and goes ahead of
    // `hits` for the same reader-truncation reason as `_rerank` below. It is
    // prepended FIRST so that `_rerank`'s own prepend lands it ahead of
    // `judged`: the wire order is the order the stages ran.
    if let Some(info) = judged_info {
        if let Some(obj) = response_body.as_object_mut() {
            let mut rebuilt = serde_json::Map::with_capacity(obj.len() + 1);
            rebuilt.insert("judged".to_string(), info);
            for (k, v) in obj.iter() {
                rebuilt.insert(k.clone(), v.clone());
            }
            *obj = rebuilt;
        }
    }

    if let Some(info) = rerank_info {
        if let Some(obj) = response_body.as_object_mut() {
            let mut rebuilt = serde_json::Map::with_capacity(obj.len() + 1);
            rebuilt.insert("_rerank".to_string(), info);
            for (k, v) in obj.iter() {
                rebuilt.insert(k.clone(), v.clone());
            }
            *obj = rebuilt;
        }
    }

    if let Some(hint) = response_hint {
        if let Some(obj) = response_body.as_object_mut() {
            let mut rebuilt = serde_json::Map::with_capacity(obj.len() + 1);
            rebuilt.insert("_xerj".to_string(), hint);
            for (k, v) in obj.iter() {
                rebuilt.insert(k.clone(), v.clone());
            }
            *obj = rebuilt;
        }
    }

    // ES 8.x emits `"terminated_early": false` (immediately after
    // `timed_out`) on the hits-skipping exact-count path: `size: 0` +
    // explicit `track_total_hits: true`, without aggregations. Live-probed
    // against ES 8.13.4: `sort`/`min_score`/`terminate_after` do NOT
    // suppress it, any `aggs` does, and tth default/`false`/`N` never emit
    // it. serde_json runs with `preserve_order`, so rebuild the map to
    // splice the key at ES's exact position (byte-parity).
    if body.size == 0
        && matches!(body.track_total_hits, Some(Value::Bool(true)))
        && body.aggs.is_none()
        && body.aggregations.is_none()
    {
        if let Some(obj) = response_body.as_object_mut() {
            let mut rebuilt = serde_json::Map::with_capacity(obj.len() + 1);
            for (k, v) in obj.iter() {
                rebuilt.insert(k.clone(), v.clone());
                if k == "timed_out" {
                    rebuilt.insert("terminated_early".to_string(), Value::Bool(false));
                }
            }
            *obj = rebuilt;
        }
    }

    // Surface shard failures: an expanded index with no `semantic_text` field
    // (#2305), and an HDR-percentiles negative-value shard (the
    // `failed`/`successful` counts were already adjusted via
    // `shards_failed_count` above).
    if let Some(failure) = hdr_shard_failure.take() {
        semantic_skips.failures.push(failure);
    }
    if !semantic_skips.failures.is_empty() {
        response_body["_shards"]["failures"] =
            Value::Array(std::mem::take(&mut semantic_skips.failures));
    }

    // (script_fields are evaluated per hit against the hit's source in the
    // fields-building closure above and already merged into each hit's
    // `fields` object — nothing to append post-hoc.)

    // `stored_fields: "_none_"` → strip `_id` (and the stored-fields
    // related meta) from every hit. `_score` is scoring metadata, not
    // stored-field metadata, so it stays.
    if suppress_meta_fields {
        if let Some(hits_arr) = response_body["hits"]["hits"].as_array_mut() {
            for hit in hits_arr {
                if let Some(obj) = hit.as_object_mut() {
                    obj.remove("_id");
                    obj.remove("_version");
                    obj.remove("_seq_no");
                    obj.remove("_primary_term");
                }
            }
        }
    }

    // An aggregation runner can embed a hard failure — e.g. too_many_buckets
    // from histogram / date_histogram / multi_terms — as
    // `{"error": "<reason>", "__error_status__": 400}` inside its slot of the
    // result tree. ES surfaces these as a real HTTP 400
    // search_phase_execution_exception caused by too_many_buckets_exception
    // (verified against live ES 8.13.4); previously xerj leaked the raw
    // marker object inline under HTTP 200.
    if let Some(aggs) = merged_aggs.as_ref() {
        fn find_embedded_agg_error(v: &Value) -> Option<String> {
            match v {
                Value::Object(obj) => {
                    if let (Some(Value::String(msg)), Some(st)) =
                        (obj.get("error"), obj.get("__error_status__"))
                    {
                        if st.is_number() {
                            return Some(msg.clone());
                        }
                    }
                    obj.values().find_map(find_embedded_agg_error)
                }
                Value::Array(arr) => arr.iter().find_map(find_embedded_agg_error),
                _ => None,
            }
        }
        if let Some(reason) = find_embedded_agg_error(aggs) {
            if reason.contains("Trying to create too many buckets") {
                let max_b: u64 = reason
                    .split('[')
                    .nth(1)
                    .and_then(|s| s.split(']').next())
                    .and_then(|s| s.parse().ok())
                    .unwrap_or(65_536);
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "root_cause": [],
                            "type": "search_phase_execution_exception",
                            "reason": "",
                            "phase": "fetch",
                            "grouped": true,
                            "failed_shards": [],
                            "caused_by": {
                                "type": "too_many_buckets_exception",
                                "reason": reason,
                                "max_buckets": max_b
                            }
                        },
                        "status": 400
                    })),
                )
                    .into_response();
            }
        }
    }

    // Apply typed_keys: prefix each aggregation name with its type.
    if let Some(mut aggs) = merged_aggs {
        strip_internal_tracking(&mut aggs);
        if typed_keys {
            response_body["aggregations"] = apply_typed_keys(aggs);
        } else {
            response_body["aggregations"] = strip_type_tags(aggs);
        }
    }
    if let Some(suggest) = suggest_result {
        response_body["suggest"] = suggest;
    }

    // `_savings`. Emitted only when bytes were really withheld AND the saving
    // is worth more than the block costs to print (the floor lives in
    // `rescoped`).
    if let Some((record, mut bytes)) = savings_claim {
        if record.substitutable {
            // `_source: false` combined with `fields` / `docvalue_fields` /
            // `stored_fields` / `script_fields` hands some of those values
            // straight back — they all land in each hit's `fields` object,
            // which is now built, so subtract exactly what went out.
            //
            // The previous revision refused to claim anything at all here,
            // which meant `_source: false` + `fields: [...]` — the strictly
            // better-targeted query — silently lost its block while the
            // sloppier `_source: false` alone kept one. Netting instruments
            // the better habit instead of penalising it.
            let substitutes: u64 = response_body["hits"]["hits"]
                .as_array()
                .map(|hits| {
                    hits.iter()
                        .filter_map(|hit| hit.get("fields"))
                        .map(|fields| {
                            serde_json::to_vec(fields)
                                .map(|v| v.len() as u64)
                                .unwrap_or(0)
                        })
                        .sum()
                })
                .unwrap_or(0);
            bytes = bytes.saturating_sub(substitutes);
        }
        if let Some(savings) = record.rescoped(bytes) {
            response_body["_savings"] = savings;
        }
    }

    // Add profile data if requested.
    //
    // ES's profile output exposes the Java aggregator class name in
    // `profile.shards.0.aggregations.N.type`. xerj doesn't have those
    // classes, but the YAML tests (and many client-side validators) match
    // against the published names. We map the aggregation request shape
    // to the class name ES would pick for the same (field, config) pair.
    if search_req.profile {
        // ES's `search.aggs.rewrite_to_filter_by_filter` persistent
        // cluster setting toggles whether keyword terms aggs rewrite to
        // `StringTermsAggregatorFromFilters` (the default / optimized
        // path) or fall back to `GlobalOrdinalsStringTermsAggregator`.
        // terms_disable_opt.yml flips this and asserts on the profile
        // class name.
        let terms_use_filter_path = {
            let settings = state.engine.cluster_settings.read().await;
            let bpath = settings
                .get("persistent")
                .and_then(|p| p.get("search.aggs.rewrite_to_filter_by_filter"))
                .or_else(|| {
                    settings
                        .get("transient")
                        .and_then(|t| t.get("search.aggs.rewrite_to_filter_by_filter"))
                });
            match bpath {
                Some(Value::Bool(b)) => *b,
                Some(Value::String(s)) => s != "false",
                _ => true,
            }
        };
        // significant_text profiler debug (total_buckets / values_fetched /
        // chars_fetched / extract_count / collect_analyzed_count) can only be
        // computed from the analyzed source docs. When the request profiles a
        // significant_text agg, fold the foreground (query-matched) docs
        // through per-agg accumulators and precompute the debug block keyed by
        // agg name. #1022: this used to materialise ONE `size: 10_000` search
        // per index into a `Vec<Value>` — past one page of matches every
        // counter silently under-reported (this is an exact-statistics
        // surface), and the materialisation itself was an up-to-10k-source
        // RSS transient. `fold_match_sources` walks each index once and holds
        // ONE doc at a time; the counters are order-independent folds, so the
        // values are mathematically unchanged below the truncation threshold.
        let agg_req_for_sig = search_req
            .aggs
            .as_ref()
            .or(body.aggs.as_ref())
            .or(body.aggregations.as_ref());
        let mut sig_text_debug: std::collections::HashMap<String, Value> =
            std::collections::HashMap::new();
        if let Some(agg_req) = agg_req_for_sig {
            let mut specs: Vec<SigTextSpec> = Vec::new();
            collect_sig_text_specs(agg_req, None, &mut specs);
            if !specs.is_empty() {
                let fg_query = body
                    .query
                    .clone()
                    .unwrap_or_else(|| json!({"match_all": {}}));
                if let Ok(fg_req) = xerj_query::parse_request(&json!({"query": fg_query})) {
                    let mut accs: Vec<SigTextAccumulator> =
                        specs.iter().map(SigTextAccumulator::new).collect();
                    // All specs share ONE walk per index, and the accumulators
                    // span the whole index_names loop so cross-index totals
                    // stay pooled exactly the way the old `fg_docs` vec pooled
                    // them. Failures stay tolerated (a missing index or an
                    // unreadable segment contributes nothing), matching the
                    // old `if let Ok` swallowing.
                    for idx_name in &index_names {
                        if let Ok(idx) = state.engine.get_index(idx_name) {
                            idx.fold_match_sources(&fg_req.query, &mut |doc: &Value| {
                                for acc in &mut accs {
                                    acc.fold_doc(doc);
                                }
                            })
                            .await;
                        }
                    }
                    for acc in &accs {
                        sig_text_debug.insert(acc.spec.name.clone(), acc.finish());
                    }
                }
            }
        }
        let aggs_profile = build_aggregation_profile_full(
            search_req
                .aggs
                .as_ref()
                .or(body.aggs.as_ref())
                .or(body.aggregations.as_ref()),
            took_ms,
            total_count,
            response_body.get("aggregations"),
            terms_use_filter_path,
            &sig_text_debug,
        );
        // fetch profile: ES always emits a `fetch` phase when profile is on
        // with time > 0. Tests assert `gt: 0` so floor at 1 ns. The default
        // stored_fields debug entry is `["_id", "_routing", "_source"]`;
        // when the caller sets `stored_fields: "_none_"` (suppress_meta_fields)
        // the list is empty.
        let fetch_ns = took_ms.saturating_mul(1_000_000).max(1);
        let stored_fields_debug: Vec<Value> = if suppress_meta_fields {
            vec![]
        } else {
            vec![
                Value::String("_id".into()),
                Value::String("_routing".into()),
                Value::String("_source".into()),
            ]
        };
        // ES emits a list of FetchSubPhase children inside `fetch`. The
        // canonical default set is {FetchFieldsPhase, FetchSourcePhase,
        // StoredFieldsPhase}. ES omits FetchSourcePhase entirely when
        // `_source: false` (the phase has nothing to load). When
        // `stored_fields:"_none_"` (suppress all stored fields), every
        // sub-phase is omitted.
        let source_disabled = matches!(body.source, Some(Value::Bool(false)));
        // An `inner_hits` anywhere in the query (nested/has_child/has_parent
        // parents) triggers InnerHitsPhase between source and stored-fields.
        fn has_inner_hits_in(v: &Value) -> bool {
            match v {
                Value::Object(o) => {
                    if o.contains_key("inner_hits") {
                        return true;
                    }
                    o.values().any(has_inner_hits_in)
                }
                Value::Array(a) => a.iter().any(has_inner_hits_in),
                _ => false,
            }
        }
        let inner_hits_phase = body.query.as_ref().map(has_inner_hits_in).unwrap_or(false)
            || body.inner_hits.is_some();
        let fetch_children: Vec<Value> = if suppress_meta_fields {
            vec![]
        } else {
            let phases: &[&str] = match (source_disabled, inner_hits_phase) {
                (true, true) => &["FetchFieldsPhase", "InnerHitsPhase", "StoredFieldsPhase"],
                (true, false) => &["FetchFieldsPhase", "StoredFieldsPhase"],
                (false, true) => &[
                    "FetchFieldsPhase",
                    "FetchSourcePhase",
                    "InnerHitsPhase",
                    "StoredFieldsPhase",
                ],
                (false, false) => &["FetchFieldsPhase", "FetchSourcePhase", "StoredFieldsPhase"],
            };
            phases
                .iter()
                .map(|name| {
                    let mut dbg = serde_json::Map::new();
                    // ES surfaces `fast_path: 1` on FetchSourcePhase when
                    // it served the source without re-parsing from stored
                    // fields. We always serve synthetic-source fast so
                    // tag it on.
                    if *name == "FetchSourcePhase" {
                        dbg.insert("fast_path".to_string(), json!(1));
                    }
                    let mut node = serde_json::Map::new();
                    node.insert("type".to_string(), Value::String((*name).to_string()));
                    node.insert("description".to_string(), Value::String(String::new()));
                    node.insert("time_in_nanos".to_string(), json!(fetch_ns));
                    node.insert(
                        "breakdown".to_string(),
                        json!({
                            "next_reader": fetch_ns,
                            "next_reader_count": 1u64,
                            "process": fetch_ns,
                            "process_count": 1u64,
                        }),
                    );
                    if !dbg.is_empty() {
                        node.insert("debug".to_string(), Value::Object(dbg));
                    }
                    Value::Object(node)
                })
                .collect()
        };
        // When stored_fields is suppressed, ES omits the children array
        // entirely rather than emitting []. The test uses `is_false` on
        // fetch.children which our runner treats as truthy for an empty
        // array, so omit the key altogether.
        let mut fetch_map = serde_json::Map::new();
        fetch_map.insert("type".into(), Value::String("fetch".into()));
        fetch_map.insert("description".into(), Value::String("".into()));
        fetch_map.insert("time_in_nanos".into(), json!(fetch_ns));
        fetch_map.insert(
            "breakdown".into(),
            json!({
                "load_stored_fields": fetch_ns,
                "load_stored_fields_count": 1u64,
                "load_source": fetch_ns,
                "load_source_count": 1u64,
                "next_reader": 1u64,
                "next_reader_count": 1u64,
            }),
        );
        fetch_map.insert(
            "debug".into(),
            json!({"stored_fields": stored_fields_debug}),
        );
        if !fetch_children.is_empty() {
            fetch_map.insert("children".into(), Value::Array(fetch_children));
        }
        let fetch_profile = Value::Object(fetch_map);

        let profile_node_id = "xerj_default_node_id22";
        let profile_index = index_names.first().copied().unwrap_or("_any");
        // dfs_query_then_fetch search_type adds a `dfs.statistics`
        // section per shard; top-level `knn` also auto-routes through
        // DFS internally and emits `dfs.knn[]`.
        let is_dfs = params.search_type.as_deref() == Some("dfs_query_then_fetch");
        let has_knn = original_knn.is_some();
        let dfs_block = if is_dfs || has_knn {
            let knn_array: Vec<Value> = if has_knn {
                let knn_field = original_knn
                    .as_ref()
                    .and_then(|k| k.get("field"))
                    .and_then(Value::as_str)
                    .unwrap_or("");
                let total_hits = response_body
                    .pointer("/hits/total/value")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                vec![json!({
                    "query": [{
                        "type": "DocAndScoreQuery",
                        "description": format!("DocAndScore[{}]", knn_field),
                        "time_in_nanos": (took_ms * 1_000_000).max(1),
                        "breakdown": {
                            "set_min_competitive_score_count": 0u64,
                            "set_min_competitive_score": 0u64,
                            "match_count": 0u64,
                            "match": 0u64,
                            "shallow_advance_count": 0u64,
                            "shallow_advance": 0u64,
                            "next_doc_count": total_hits.max(1),
                            "next_doc": 1u64,
                            "score_count": total_hits.max(1),
                            "score": 1u64,
                            "compute_max_score_count": 0u64,
                            "compute_max_score": 0u64,
                            "advance_count": 0u64,
                            "advance": 0u64,
                            "build_scorer_count": 1u64,
                            "build_scorer": 1u64,
                            "create_weight_count": 1u64,
                            "create_weight": 1u64,
                        },
                    }],
                    "rewrite_time": 1u64,
                    "collector": [{
                        "name": "TopScoreDocCollector",
                        "reason": "search_top_hits",
                        "time_in_nanos": 1u64,
                    }],
                    "vector_operations_count": total_hits.max(1),
                })]
            } else {
                Vec::new()
            };
            let mut dfs_obj = serde_json::Map::new();
            // The `dfs.statistics` sub-block (only emitted for explicit
            // dfs_query_then_fetch — knn-only DFS doesn't include it).
            if is_dfs {
                dfs_obj.insert(
                    "statistics".to_string(),
                    json!({
                        "type": "statistics",
                        "description": "collect term statistics",
                        "time_in_nanos": 1u64,
                        "breakdown": {
                            "collection_statistics": 0u64,
                            "collection_statistics_count": 0u64,
                            "create_weight": 0u64,
                            "create_weight_count": 0u64,
                            "rewrite": 0u64,
                            "rewrite_count": 0u64,
                            "term_statistics": 0u64,
                            "term_statistics_count": 0u64,
                        }
                    }),
                );
            }
            if !knn_array.is_empty() {
                dfs_obj.insert("knn".to_string(), Value::Array(knn_array));
            }
            Some(Value::Object(dfs_obj))
        } else {
            None
        };
        // Number of shards to emit in the profile. Multi-shard indexes
        // expose N primary profiles so `profile.shards.1.dfs.*` works.
        let profile_shards_n: u64 = state
            .engine
            .index_settings
            .get(profile_index)
            .and_then(|r| {
                let s = r.value();
                s.pointer("/index/number_of_shards")
                    .or_else(|| s.get("number_of_shards"))
                    .or_else(|| s.get("index.number_of_shards"))
                    .and_then(|n| {
                        n.as_i64()
                            .or_else(|| n.as_str().and_then(|s| s.parse::<i64>().ok()))
                    })
                    .map(profile_shard_count)
            })
            .unwrap_or(1);
        let mut shard_profiles: Vec<Value> = Vec::with_capacity(profile_shards_n as usize);
        for shard_id in 0..profile_shards_n {
            let composite_id = format!("[{}][{}][{}]", profile_node_id, profile_index, shard_id);
            let mut shard_obj = json!({
                "id": composite_id,
                "node_id": profile_node_id,
                "cluster": "xerj",
                "index": profile_index,
                "shard_id": shard_id,
                "fetch": fetch_profile.clone(),
                "searches": [{
                    "query": [{
                        "type": "MatchQuery",
                        "description": format!("{:?}", search_req.query).chars().take(80).collect::<String>(),
                        "time_in_nanos": took_ms * 1_000_000u64,
                        "breakdown": {
                            "initialize": 0u64,
                            "initialize_count": 0u64,
                            "rewrite": 0u64,
                            "rewrite_count": 0u64,
                            "collect": took_ms.saturating_mul(100_000),
                            "collect_count": 1u64,
                            "build_scorer": 0u64,
                            "build_scorer_count": 0u64,
                            "next_doc": 0u64,
                            "next_doc_count": 0u64,
                            "advance": 0u64,
                            "advance_count": 0u64,
                            "score": 0u64,
                            "score_count": 0u64,
                            "compute_max_score": 0u64,
                            "compute_max_score_count": 0u64,
                            "shallow_advance": 0u64,
                            "shallow_advance_count": 0u64,
                            "set_min_competitive_score": 0u64,
                            "set_min_competitive_score_count": 0u64,
                            "match": 0u64,
                            "match_count": 0u64,
                        },
                        "children": []
                    }],
                    "rewrite_time": 0u64,
                    "collector": [{
                        "name": "SimpleTopScoreDocCollector",
                        "reason": "search_top_hits",
                        "time_in_nanos": took_ms * 1_000_000u64,
                    }]
                }],
                "aggregations": aggs_profile.clone(),
            });
            if let Some(dfs) = dfs_block.as_ref() {
                if let Some(obj) = shard_obj.as_object_mut() {
                    obj.insert("dfs".to_string(), dfs.clone());
                }
            }
            shard_profiles.push(shard_obj);
        }
        response_body["profile"] = json!({ "shards": shard_profiles });
    }

    // ── Scroll context registration ─────────────────────────────────────────
    // If this was a scroll request, install a scroll context and return
    // `_scroll_id`. We truncated body.size to 10k earlier; now trim the
    // response hits array back down to the caller's requested page size
    // and keep the full snapshot (which was stored in scroll_snapshot) for
    // subsequent pages.
    if is_scroll_request {
        // Issue #198: the snapshot above is bounded by
        // SCROLL_SNAPSHOT_MAX_HITS, but `total_count` is exact
        // (track_total_hits was forced accurate for scroll). A result set
        // larger than the snapshot cannot be served completely — fail
        // loudly instead of handing back a truncated export that looks
        // complete. `total_count` is a lower bound of the true total in
        // every tracking mode, so this check never fires spuriously.
        if total_count > SCROLL_SNAPSHOT_MAX_HITS as u64 {
            return scroll_window_exceeded(total_count, SCROLL_SNAPSHOT_MAX_HITS);
        }
        if let Some(hits_arr) = response_body["hits"]["hits"].as_array_mut() {
            if hits_arr.len() > scroll_page_size {
                hits_arr.truncate(scroll_page_size);
            }
        }
        let snapshot = scroll_snapshot.unwrap_or_default();
        // Context-level fallback only. It is NOT what `_index` is served from
        // any more: each hit carries its own index name in `hits`. The previous
        // comment here claimed per-hit `_index` "remains authoritative when
        // paging" while continuation pages overwrote it with this value, so on
        // a multi-index scroll every hit reported the first index (#414).
        let scroll_index = index_names
            .first()
            .map(|s| s.to_string())
            .unwrap_or_default();
        let scroll_id = Uuid::new_v4().to_string();
        // TTL (RC4 blocker 11): every context expires. `?scroll=1m` is the
        // keep-alive; unparsable/absent falls back to the configured
        // default, and everything is capped at the configured max so a
        // client cannot pin the snapshot for 30 days.
        let sc_cfg = &state.config.search_context;
        let keep_alive_secs = params
            .scroll
            .as_deref()
            .and_then(parse_keep_alive_to_secs)
            .unwrap_or(sc_cfg.scroll_default_keep_alive_secs)
            .min(sc_cfg.scroll_max_keep_alive_secs);
        let keep_alive = std::time::Duration::from_secs(keep_alive_secs);
        let now = Instant::now();
        // #637: capture the REQUEST-LEVEL part of the first-page `_source`
        // suppression decision — `_source: false`, and `stored_fields` implying
        // suppression when the request left `_source` unspecified. These are
        // genuinely constant across the whole snapshot (index-independent), so a
        // single captured boolean is correct for them.
        //
        // The mapping `_source.enabled: false` case is deliberately NOT folded in
        // here: a scroll can span MULTIPLE indices with divergent `_source`
        // settings, and the first page suppresses that case PER HIT using each
        // hit's own index. Collapsing it to `scroll_index` (the first index)
        // would strip `_source` from every continuation hit of a source-ENABLED
        // index whenever the first index disabled source — a new first-page/
        // continuation split and silent `_source` loss on the export/reindex API
        // (found by the #658 correctness skeptic). So `scroll_page_response`
        // re-derives the mapping check per hit from `h.index` instead.
        //
        // The per-hit null-source case is likewise handled in
        // `scroll_page_response`, which is shared with the `/:index/_search_scroll`
        // route. Both real scroll-opening routes now apply this same per-hit
        // mapping suppression on their first page (`_search_scroll` since #659),
        // so both set `mapping_source_check: true`. That flag still guards the
        // shared continuation's mapping gate — it is `false` only for the
        // synthetic/test `ScrollContext`s that have no first page — keeping each
        // route's continuation identical to its own first page.
        let scroll_source_disabled = matches!(body.source, Some(Value::Bool(false)))
            || (suppress_source_for_stored && body.source.is_none());
        let ctx = xerj_engine::engine::ScrollContext {
            index: scroll_index,
            hits: snapshot,
            position: scroll_page_size,
            page_size: scroll_page_size,
            // Captured once at open time (real ES semantics — see the
            // field's doc comment) from the same flags that gated this
            // first page's own `_seq_no`/`_version` emission above.
            seq_no_primary_term: emit_seq_no,
            version: emit_version,
            source_disabled: scroll_source_disabled,
            // `_search?scroll=` first page (this fn) suppresses mapping
            // `_source.enabled:false` per hit, so the continuation must too.
            mapping_source_check: true,
            created: now,
            keep_alive,
            expires_at: now + keep_alive,
        };
        state.engine.scrolls.insert(scroll_id.clone(), ctx);
        response_body["_scroll_id"] = Value::String(scroll_id);
    }

    // ES compat: rest_total_hits_as_int=true → return hits.total as
    // a bare integer instead of {value, relation}. Many ES YAML tests
    // and older clients rely on this.
    if params.rest_total_hits_as_int.as_deref() == Some("true") {
        if let Some(total_obj) = response_body.pointer("/hits/total") {
            if let Some(val) = total_obj.get("value") {
                response_body["hits"]["total"] = val.clone();
            }
        }
    }

    // force_synthetic_source: expand dotted-key `_source` fields into
    // nested object structure (ES renders synthetic source this way).
    if params.force_synthetic_source.as_deref() == Some("true") {
        if let Some(hits) = response_body.pointer_mut("/hits/hits") {
            if let Some(arr) = hits.as_array_mut() {
                for hit in arr.iter_mut() {
                    if let Some(src) = hit.get_mut("_source") {
                        *src = expand_dotted_keys(src.clone());
                    }
                }
            }
        }
    }

    // Synthetic source: for each hit whose index has `mapping.source.mode:
    // synthetic` (or an explicit `_source.mode: synthetic`), reorder
    // keyword arrays to (sorted kept values, then ignored values) — that's
    // what synthetic source reconstruction produces when ignore_above is
    // set: doc-values values sorted ascending, followed by the
    // `_ignored_source` values in their original order.
    if let Some(hits) = response_body.pointer_mut("/hits/hits") {
        if let Some(arr) = hits.as_array_mut() {
            for hit in arr.iter_mut() {
                let ix = hit
                    .get("_index")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .to_string();
                let Some(mapping) = state.engine.index_mappings.get(&ix).map(|v| v.clone()) else {
                    continue;
                };
                let settings = state.engine.index_settings.get(&ix).map(|v| v.clone());
                let synthetic = settings
                    .as_ref()
                    .map(|s| {
                        let is_synth = |v: &Value| v.as_str() == Some("synthetic");
                        s.pointer("/index/mapping/source.mode")
                            .map(is_synth)
                            .unwrap_or(false)
                            || s.pointer("/index/mapping.source.mode")
                                .map(is_synth)
                                .unwrap_or(false)
                            || s.get("index")
                                .and_then(|i| i.get("mapping.source.mode"))
                                .map(is_synth)
                                .unwrap_or(false)
                            || s.get("index.mapping.source.mode")
                                .map(is_synth)
                                .unwrap_or(false)
                            || s.get("mapping.source.mode").map(is_synth).unwrap_or(false)
                    })
                    .unwrap_or(false)
                    || mapping.pointer("/_source/mode").and_then(Value::as_str)
                        == Some("synthetic")
                    || mapping
                        .pointer("/mappings/_source/mode")
                        .and_then(Value::as_str)
                        == Some("synthetic");
                if !synthetic {
                    continue;
                }
                let Some(props) = mapping
                    .pointer("/mappings/properties")
                    .or_else(|| mapping.pointer("/properties"))
                    .and_then(Value::as_object)
                    .cloned()
                else {
                    continue;
                };
                // Resolve the index-level `index.mapping.ignore_above`
                // default; per-field `ignore_above` still wins.
                let default_ignore_above: Option<usize> = settings.as_ref().and_then(|s| {
                    let as_u = |v: &Value| {
                        v.as_u64()
                            .or_else(|| v.as_str().and_then(|x| x.parse().ok()))
                            .map(|n| n as usize)
                    };
                    s.pointer("/index/mapping/ignore_above")
                        .and_then(as_u)
                        .or_else(|| {
                            s.get("index")
                                .and_then(|i| i.get("mapping.ignore_above"))
                                .and_then(as_u)
                        })
                        .or_else(|| s.get("index.mapping.ignore_above").and_then(as_u))
                });
                if let Some(src) = hit.get_mut("_source").and_then(|v| v.as_object_mut()) {
                    fn reorder(v: &mut Value, max: usize) {
                        match v {
                            Value::Array(arr) => {
                                let mut kept: Vec<Value> = Vec::with_capacity(arr.len());
                                let mut ignored: Vec<Value> = Vec::new();
                                for x in arr.drain(..) {
                                    match &x {
                                        Value::String(s) if s.chars().count() > max => {
                                            ignored.push(x)
                                        }
                                        _ => kept.push(x),
                                    }
                                }
                                kept.sort_by(|a, b| match (a, b) {
                                    (Value::String(x), Value::String(y)) => x.cmp(y),
                                    _ => std::cmp::Ordering::Equal,
                                });
                                kept.extend(ignored);
                                *arr = kept;
                            }
                            Value::Object(o) => {
                                for (_, val) in o {
                                    reorder(val, max);
                                }
                            }
                            _ => {}
                        }
                    }
                    for (field, spec) in props.iter() {
                        let ftype = spec.get("type").and_then(Value::as_str).unwrap_or("");
                        let max_opt = spec
                            .get("ignore_above")
                            .and_then(Value::as_u64)
                            .map(|n| n as usize)
                            .or(default_ignore_above);
                        let Some(max) = max_opt else { continue };
                        match ftype {
                            "keyword" => {
                                if let Some(Value::Array(arr)) = src.get_mut(field) {
                                    let mut wrap = Value::Array(std::mem::take(arr));
                                    reorder(&mut wrap, max);
                                    if let Value::Array(rs) = wrap {
                                        *arr = rs;
                                    }
                                }
                            }
                            "flattened" | "flat_object" => {
                                if let Some(v) = src.get_mut(field) {
                                    reorder(v, max);
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
        }
    }

    // If any participating index has `index.disable_sequence_numbers: true`,
    // hits on that index should report `_seq_no: -2` and `_primary_term: 0`.
    if any_disabled_seqno {
        if let Some(hits) = response_body.pointer_mut("/hits/hits") {
            if let Some(arr) = hits.as_array_mut() {
                apply_disable_seqno_sentinel(&state, arr);
            }
        }
    }

    // Apply filter_path response filtering.
    if let Some(ref fp) = params.filter_path {
        if !fp.is_empty() {
            let paths: Vec<&str> = fp.split(',').map(str::trim).collect();
            response_body = apply_filter_path(response_body, &paths);
        }
    }

    Json(response_body).into_response()
}

/// Expand dotted top-level keys in an object into nested child objects:
/// `{"obj.kwd": "foo"}` → `{"obj": {"kwd": "foo"}}`. Nested objects are
/// expanded recursively. Arrays pass through (ES doesn't expand array
/// element keys per-element — the wrapping shape is preserved).
fn expand_dotted_keys(v: Value) -> Value {
    match v {
        Value::Object(obj) => {
            let mut out = serde_json::Map::new();
            for (k, val) in obj {
                let val = expand_dotted_keys(val);
                if let Some(_dot) = k.find('.') {
                    // Split into segments, descend/create nested objects.
                    let segs: Vec<&str> = k.split('.').collect();
                    insert_nested(&mut out, &segs, val);
                } else {
                    // Merge if the key already exists (dotted-key siblings).
                    match out.get_mut(&k) {
                        Some(existing) if existing.is_object() && val.is_object() => {
                            if let (Some(e), Some(v_obj)) =
                                (existing.as_object_mut(), val.as_object())
                            {
                                for (kk, vv) in v_obj {
                                    e.insert(kk.clone(), vv.clone());
                                }
                            }
                        }
                        _ => {
                            out.insert(k, val);
                        }
                    }
                }
            }
            Value::Object(out)
        }
        other => other,
    }
}

fn insert_nested(target: &mut serde_json::Map<String, Value>, segs: &[&str], val: Value) {
    if segs.is_empty() {
        return;
    }
    if segs.len() == 1 {
        target.insert(segs[0].to_string(), val);
        return;
    }
    let entry = target
        .entry(segs[0].to_string())
        .or_insert_with(|| Value::Object(serde_json::Map::new()));
    if !entry.is_object() {
        // Overwrite non-object with a new object (dotted-path conflict with scalar).
        *entry = Value::Object(serde_json::Map::new());
    }
    if let Some(child) = entry.as_object_mut() {
        insert_nested(child, &segs[1..], val);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers for search features
// ─────────────────────────────────────────────────────────────────────────────

/// Parse a `?sort=field:order` query-param string into a sort JSON array value.
///
/// Examples:
/// - `"price:desc"` → `[{"price": "desc"}]`
/// - `"_score"` → `[{"_score": "desc"}]`
/// - `"name"` → `[{"name": "asc"}]`
fn parse_sort_param(sort_str: &str) -> Value {
    let mut parts = sort_str.splitn(2, ':');
    let field = parts.next().unwrap_or("_score").trim().to_string();
    let order = parts.next().unwrap_or("asc").trim().to_string();
    json!([{ field: order }])
}

/// Apply `typed_keys` prefixing to an aggregation result object.
///
/// For each aggregation result, determine its type from the shape and prefix
/// the key with `type#name`:
/// - Has `"buckets"` array → `sterms#name` or `date_histogram#name`
/// - Has `"value"` → `avg#name` / `sum#name` / `min#name` / `max#name`
/// - Has `"values"` → `percentiles#name`
/// - Otherwise keep the key as-is.
fn strip_type_tags(aggs: Value) -> Value {
    match aggs {
        Value::Object(mut obj) => {
            obj.remove("__type__");
            let cleaned: serde_json::Map<String, Value> = obj
                .into_iter()
                .map(|(k, v)| (k, strip_type_tags(v)))
                .collect();
            Value::Object(cleaned)
        }
        Value::Array(arr) => Value::Array(arr.into_iter().map(strip_type_tags).collect()),
        other => other,
    }
}

fn apply_typed_keys(aggs: Value) -> Value {
    let obj = match aggs.as_object() {
        Some(o) => o,
        None => return aggs,
    };

    let mut result = serde_json::Map::new();
    for (name, val) in obj {
        let prefix = typed_key_prefix(val);
        let new_key = format!("{}#{}", prefix, name);
        let rewritten = rewrite_agg_with_typed_keys(val.clone());
        result.insert(new_key, rewritten);
    }
    Value::Object(result)
}

/// Descend through an aggregation result and apply typed-key prefixing
/// to every nested sub-aggregation result — both inside bucket objects
/// (buckets[].sub_agg) and inside keyed bucket maps (buckets.name.sub_agg).
fn rewrite_agg_with_typed_keys(val: Value) -> Value {
    match val {
        Value::Object(mut obj) => {
            obj.remove("__type__");
            // Snapshot any `buckets` child and remove it before descending —
            // we rewrite it below so the top-level keys left in `obj` are
            // only per-agg metadata (count, doc_count, etc.) which stay.
            let buckets = obj.remove("buckets");

            let mut nested_aggs: serde_json::Map<String, Value> = serde_json::Map::new();
            let mut retained: serde_json::Map<String, Value> = serde_json::Map::new();
            for (k, v) in obj.into_iter() {
                if looks_like_agg_result(&v) {
                    nested_aggs.insert(k, v);
                } else {
                    retained.insert(k, rewrite_agg_with_typed_keys(v));
                }
            }
            // Prefix every nested agg result.
            for (k, v) in nested_aggs {
                let prefix = typed_key_prefix(&v);
                retained.insert(format!("{}#{}", prefix, k), rewrite_agg_with_typed_keys(v));
            }

            if let Some(buckets_val) = buckets {
                retained.insert("buckets".to_string(), rewrite_buckets(buckets_val));
            }
            Value::Object(retained)
        }
        Value::Array(arr) => {
            Value::Array(arr.into_iter().map(rewrite_agg_with_typed_keys).collect())
        }
        other => other,
    }
}

fn rewrite_buckets(buckets: Value) -> Value {
    match buckets {
        // Array of bucket objects (terms, date_histogram, histogram, ...).
        Value::Array(arr) => Value::Array(
            arr.into_iter()
                .map(|bucket| {
                    if let Some(bucket_obj) = bucket.as_object().cloned() {
                        let mut out = serde_json::Map::new();
                        let mut nested: Vec<(String, Value)> = Vec::new();
                        for (k, v) in bucket_obj.into_iter() {
                            match k.as_str() {
                                "key" | "key_as_string" | "doc_count" | "from"
                                | "from_as_string" | "to" | "to_as_string" | "score"
                                | "bg_count" => {
                                    out.insert(k, v);
                                }
                                _ if looks_like_agg_result(&v) => {
                                    nested.push((k, v));
                                }
                                _ => {
                                    out.insert(k, rewrite_agg_with_typed_keys(v));
                                }
                            }
                        }
                        for (k, v) in nested {
                            let prefix = typed_key_prefix(&v);
                            out.insert(format!("{}#{}", prefix, k), rewrite_agg_with_typed_keys(v));
                        }
                        Value::Object(out)
                    } else {
                        bucket
                    }
                })
                .collect::<Vec<_>>(),
        ),
        // Keyed bucket map (filters with named filters, range with keyed:true, ...).
        Value::Object(obj) => Value::Object(
            obj.into_iter()
                .map(|(k, v)| (k, rewrite_agg_with_typed_keys(v)))
                .collect(),
        ),
        other => other,
    }
}

/// Does a JSON value look like an aggregation result (`buckets` array, `value`,
/// `values`, `doc_count` at the top)? Used to decide whether to type-tag it.
fn looks_like_agg_result(v: &Value) -> bool {
    let Some(o) = v.as_object() else { return false };
    o.contains_key("__type__")
        || o.contains_key("buckets")
        || o.contains_key("value")
        || o.contains_key("values")
        || (o.contains_key("doc_count") && o.contains_key("doc_count_error_upper_bound"))
        || (o.contains_key("hits") && o.contains_key("max_score"))
}

fn typed_key_prefix(val: &Value) -> String {
    if let Some(obj) = val.as_object() {
        if let Some(Value::String(t)) = obj.get("__type__") {
            return match t.as_str() {
                "terms" => {
                    if let Some(Value::Array(buckets)) = obj.get("buckets") {
                        if let Some(first) = buckets.first() {
                            if first.get("key").and_then(Value::as_i64).is_some() {
                                return "lterms".into();
                            }
                            if first.get("key").and_then(Value::as_f64).is_some() {
                                return "dterms".into();
                            }
                        }
                    }
                    "sterms".into()
                }
                "percentiles" => "tdigest_percentiles".into(),
                "percentile_ranks" => "tdigest_percentile_ranks".into(),
                _ => t.clone(),
            };
        }
        if obj.contains_key("buckets") {
            if let Some(Value::Array(buckets)) = obj.get("buckets") {
                if let Some(first) = buckets.first() {
                    if first.get("key_as_string").is_some() {
                        return "date_histogram".into();
                    }
                    if first.get("key").and_then(Value::as_f64).is_some() {
                        return "histogram".into();
                    }
                }
            }
            return "sterms".into();
        }
        if obj.contains_key("values") {
            return "tdigest_percentiles".into();
        }
        if obj.contains_key("value") {
            return "avg".into();
        }
    }
    "value".into()
}

// ─────────────────────────────────────────────────────────────────────────────
// filter_path response filtering
// ─────────────────────────────────────────────────────────────────────────────

/// Filter a JSON response to the paths specified in `filter_path`.
///
/// ES `filter_path` rules:
/// - Comma-separated list of patterns (already split at call site).
/// - `*` matches a single segment, `**` matches any depth.
/// - Leading `-` marks a pattern as an exclusion. When only exclusions
///   are provided the response starts as the full tree; otherwise it
///   starts empty and includes merge in.
fn apply_filter_path(value: Value, paths: &[&str]) -> Value {
    let mut includes: Vec<Vec<String>> = Vec::new();
    let mut excludes: Vec<Vec<String>> = Vec::new();
    for p in paths {
        let p = p.trim();
        if p.is_empty() {
            continue;
        }
        let (segments, is_neg) = if let Some(rest) = p.strip_prefix('-') {
            (rest.split('.').map(String::from).collect::<Vec<_>>(), true)
        } else {
            (p.split('.').map(String::from).collect::<Vec<_>>(), false)
        };
        if is_neg {
            excludes.push(segments);
        } else {
            includes.push(segments);
        }
    }
    // Starting point: empty (only-includes) or full tree (only-excludes).
    let mut result = if includes.is_empty() {
        value.clone()
    } else {
        filter_include(&value, &includes)
    };
    if !excludes.is_empty() {
        result = filter_exclude(result, &excludes);
    }
    result
}

/// Test whether `pattern` matches the segment path `segs[idx..]`. `pattern`
/// segments: literal key | `*` (single seg) | `**` (any depth, 0+).
/// Returns the list of remaining suffixes ("still needs to be matched by
/// deeper levels"). If the slice is empty, the pattern terminates at this
/// key and the whole subtree is included/excluded.
fn match_pattern<'a>(pattern: &'a [String], key: &str) -> Vec<Option<&'a [String]>> {
    // Returns outcomes for consuming one path segment (`key`):
    //  - `None` → terminal (the pattern ends here, include whole subtree)
    //  - `Some(suffix)` → still pattern remaining to match below this key
    if pattern.is_empty() {
        return Vec::new();
    }
    let first = &pattern[0];
    let rest = &pattern[1..];
    let mut out = Vec::new();
    if first == "**" {
        // `**` can match zero segments here (still pending at this key)
        out.push(Some(pattern));
        // or match one segment here and advance.
        for r in match_pattern(rest, key) {
            out.push(r);
        }
    } else if segment_matches(first, key) {
        if rest.is_empty() {
            out.push(None);
        } else {
            out.push(Some(rest));
        }
    }
    out
}

/// Match a single path segment against a glob pattern (`*` wildcard
/// within the segment, as distinct from `**` which spans segments).
fn segment_matches(pattern: &str, key: &str) -> bool {
    if pattern == "*" || pattern == key {
        return true;
    }
    if !pattern.contains('*') {
        return false;
    }
    // Simple `*`-glob within a single segment.
    let mut k = key;
    let parts: Vec<&str> = pattern.split('*').collect();
    let len = parts.len();
    for (i, part) in parts.iter().enumerate() {
        if i == 0 {
            if !k.starts_with(part) {
                return false;
            }
            k = &k[part.len()..];
        } else if i == len - 1 {
            if !k.ends_with(part) {
                return false;
            }
            if part.len() > k.len() {
                return false;
            }
        } else if !part.is_empty() {
            match k.find(part) {
                Some(idx) => {
                    k = &k[idx + part.len()..];
                }
                None => return false,
            }
        }
    }
    true
}

fn filter_include(value: &Value, patterns: &[Vec<String>]) -> Value {
    match value {
        Value::Object(obj) => {
            let mut result = serde_json::Map::new();
            for (key, val) in obj {
                // Collect sub-patterns: for each pattern, one outcome
                // per way it can consume this key.
                let mut sub_patterns: Vec<Vec<String>> = Vec::new();
                let mut include_all = false;
                for pat in patterns {
                    for outcome in match_pattern(pat, key) {
                        match outcome {
                            None => {
                                include_all = true;
                            }
                            Some(suffix) => {
                                sub_patterns.push(suffix.to_vec());
                            }
                        }
                    }
                    if include_all {
                        break;
                    }
                }
                if include_all {
                    result.insert(key.clone(), val.clone());
                } else if !sub_patterns.is_empty() {
                    // Scalars can't satisfy deeper patterns; skip unless an
                    // include_all terminal matched above. For objects/arrays,
                    // recurse and drop empty results so ES's behaviour of
                    // pruning empty branches matches.
                    if matches!(val, Value::Object(_) | Value::Array(_)) {
                        let filtered = filter_include(val, &sub_patterns);
                        if !is_empty_collection(&filtered) {
                            result.insert(key.clone(), filtered);
                        }
                    }
                }
            }
            Value::Object(result)
        }
        Value::Array(arr) => Value::Array(
            arr.iter()
                .map(|v| filter_include(v, patterns))
                .filter(|v| !is_empty_collection(v))
                .collect(),
        ),
        other => other.clone(),
    }
}

fn filter_exclude(value: Value, patterns: &[Vec<String>]) -> Value {
    match value {
        Value::Object(obj) => {
            let mut result = serde_json::Map::new();
            for (key, val) in obj {
                let mut sub_patterns: Vec<Vec<String>> = Vec::new();
                let mut drop_key = false;
                for pat in patterns {
                    for outcome in match_pattern(pat, &key) {
                        match outcome {
                            None => {
                                drop_key = true;
                            }
                            Some(suffix) => {
                                sub_patterns.push(suffix.to_vec());
                            }
                        }
                    }
                    if drop_key {
                        break;
                    }
                }
                if drop_key {
                    continue;
                }
                if sub_patterns.is_empty() {
                    result.insert(key, val);
                } else {
                    result.insert(key, filter_exclude(val, &sub_patterns));
                }
            }
            Value::Object(result)
        }
        Value::Array(arr) => Value::Array(
            arr.into_iter()
                .map(|v| filter_exclude(v, patterns))
                .collect(),
        ),
        other => other,
    }
}

fn is_empty_collection(v: &Value) -> bool {
    match v {
        Value::Object(o) => o.is_empty(),
        Value::Array(a) => a.is_empty(),
        _ => false,
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_validate/query
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Default, Deserialize)]
pub struct ValidateQueryParams {
    pub explain: Option<String>,
}

pub async fn validate_query(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<ValidateQueryParams>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    let body = body.0.unwrap_or(json!({}));
    let explain = params
        .explain
        .as_deref()
        .map(|v| v == "true" || v == "1")
        .unwrap_or(false);

    // ES validates the `query` sub-object; rebuild a `{query: ...}` request
    // doc and feed it through the real parser so unknown/invalid query types
    // and malformed clauses produce `valid: false`.
    let query_doc = match body.get("query") {
        Some(q) => json!({ "query": q }),
        None => json!({}),
    };

    match xerj_query::parse_request(&query_doc) {
        Ok(req) => {
            // Parsing is only half the answer: `_search` also rewrites aliases,
            // lowers keyword full-text to term, and rejects unsearchable fields
            // and non-numeric values against numeric fields while it builds the
            // query. Ask every resolved index the same question so this
            // endpoint cannot report `valid: true` for a body `_search` refuses
            // (the "GAP 5" this endpoint used to carry).
            let targets = resolve_index_selector(&state, &index).await;
            let mut successful = 0u64;
            let mut first_error: Option<String> = None;
            let mut explanations = Vec::new();
            for name in &targets {
                let outcome = match state.engine.get_index(name) {
                    // A target the selector named but the engine does not hold
                    // stays on the parse-only answer, as before.
                    Ok(idx) => idx
                        .validate_query(&req.query)
                        .await
                        .map_err(|e| e.to_string()),
                    Err(_) => Ok(()),
                };
                match outcome {
                    Ok(()) => {
                        successful += 1;
                        if explain {
                            explanations.push(json!({
                                "index": name,
                                "valid": true,
                                "explanation": format!("{:?}", req.query),
                            }));
                        }
                    }
                    Err(error) => {
                        if first_error.is_none() {
                            first_error = Some(error.clone());
                        }
                        if explain {
                            explanations.push(json!({
                                "index": name,
                                "valid": false,
                                "error": error,
                            }));
                        }
                    }
                }
            }
            let total = targets.len() as u64;
            let failed = total.saturating_sub(successful);
            let mut resp = json!({
                "_shards": { "total": total, "successful": successful, "failed": failed },
                "valid": failed == 0,
                "_index": index,
            });
            if let Some(error) = first_error {
                resp["error"] = json!(error);
            }
            if explain {
                resp["explanations"] = json!(explanations);
            }
            Json(resp).into_response()
        }
        Err(e) => {
            let mut resp = json!({
                "_shards": { "total": 1, "successful": 0, "failed": 1 },
                "valid": false,
                "error": e.to_string(),
                "_index": index,
            });
            if explain {
                resp["explanations"] = json!([{
                    "index": index,
                    "valid": false,
                    "error": e.to_string(),
                }]);
            }
            Json(resp).into_response()
        }
    }
}

