pub async fn bulk_ops(
    State(state): State<AppState>,
    Path(index): Path<String>,
    axum::extract::Query(qp): axum::extract::Query<std::collections::HashMap<String, String>>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let started = Instant::now();
    let opts = bulk_opts_from_query(&qp);
    process_bulk_body(&state, Some(&index), &body, started, opts).await
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_bulk — global bulk
// ─────────────────────────────────────────────────────────────────────────────

pub async fn global_bulk(
    State(state): State<AppState>,
    axum::extract::Query(qp): axum::extract::Query<std::collections::HashMap<String, String>>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let started = Instant::now();
    let opts = bulk_opts_from_query(&qp);
    process_bulk_body(&state, None, &body, started, opts).await
}

fn bulk_opts_from_query(
    qp: &std::collections::HashMap<String, String>,
) -> xerj_engine::bulk::BulkOpts {
    // `?_source=true` / `?_source=field` / `?_source_includes=f1,f2` /
    // `?_source_excludes=f3` — translate the ES URL-shape to the
    // search body `_source` filter shape the engine consumes.
    let default_source_req: Option<Value> = {
        let src_param = qp.get("_source");
        let inc = qp.get("_source_includes");
        let exc = qp.get("_source_excludes");
        if inc.is_some() || exc.is_some() {
            let mut obj = serde_json::Map::new();
            if let Some(v) = inc {
                let arr: Vec<Value> = v
                    .split(',')
                    .map(|s| Value::String(s.trim().to_string()))
                    .collect();
                obj.insert("includes".to_string(), Value::Array(arr));
            }
            if let Some(v) = exc {
                let arr: Vec<Value> = v
                    .split(',')
                    .map(|s| Value::String(s.trim().to_string()))
                    .collect();
                obj.insert("excludes".to_string(), Value::Array(arr));
            }
            Some(Value::Object(obj))
        } else if let Some(v) = src_param {
            match v.as_str() {
                "true" => Some(Value::Bool(true)),
                "false" => Some(Value::Bool(false)),
                other => {
                    let arr: Vec<Value> = other
                        .split(',')
                        .map(|s| Value::String(s.trim().to_string()))
                        .collect();
                    Some(Value::Array(arr))
                }
            }
        } else {
            None
        }
    };
    xerj_engine::bulk::BulkOpts {
        require_alias: qp.get("require_alias").and_then(|v| match v.as_str() {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        }),
        default_source_req,
        // `?pipeline=` — the request-level default for every `index`/`create`
        // action that names no pipeline of its own. Read but discarded before
        // (issue #204): the bulk item was written untransformed under a `201`.
        default_pipeline: qp.get("pipeline").cloned(),
    }
}

/// Render the indices a bulk touched for its audit note, bounded.
///
/// An audit entry is evidence, not a report: it says which indices the request
/// wrote to, and says plainly when there were more than it lists rather than
/// silently truncating. The bound exists because the entry shares a fixed-size
/// ring with every other event on the node.
fn render_index_list(names: &std::collections::BTreeSet<String>) -> String {
    const SHOWN: usize = 8;
    let listed = names
        .iter()
        .take(SHOWN)
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join(",");
    if names.len() > SHOWN {
        format!("{listed},+{} more", names.len() - SHOWN)
    } else {
        listed
    }
}

async fn process_bulk_body(
    state: &AppState,
    default_index: Option<&str>,
    body: &bytes::Bytes,
    _started: Instant,
    opts: xerj_engine::bulk::BulkOpts,
) -> axum::response::Response {
    // The request body remains owned by this handler through parsing,
    // grouping, and publication. The opt-in guard is a single branch and
    // performs no atomic work when tracing is disabled.
    let _http_body_memory = xerj_engine::ingest_memory::Retained::new(
        xerj_engine::ingest_memory::Category::HttpBody,
        body.len(),
    );
    let text = match std::str::from_utf8(body) {
        Ok(t) => t,
        Err(_) => {
            let e = xerj_common::XerjError::serialization("bulk body is not valid UTF-8");
            return ApiError::new(e).into_response();
        }
    };

    // ES bulk NDJSON alternates action-lines and source-lines. We rewrite
    // each source line through apply_ignore_malformed so the downstream
    // bulk pipeline sees a doc with _ignored already populated and any
    // malformed values stripped, matching the path taken by the single-
    // doc PUT _doc/{id} / POST _doc routes.
    // TSDB last-wins `_id` rewrite: for `time_series`-mode indices, inject a
    // deterministic `_id` derived from the COMPLETE `_tsid` (all dimension
    // fields — mapping-declared `time_series_dimension:true` AND every
    // `routing_path` entry, nested paths resolved) plus the normalized
    // `@timestamp`. Two docs collapse (later overwrites earlier) ONLY when all
    // dimensions and the instant are identical, matching ES. Returns `None`
    // when no action targets a TSDB index, so normal bulk bodies are unchanged.
    let ts_rewritten = rewrite_bulk_time_series_ids(state, default_index, text);
    let _ts_rewritten_memory = ts_rewritten.as_ref().map(|replacement| {
        xerj_engine::ingest_memory::Retained::new(
            xerj_engine::ingest_memory::Category::HttpRewriteBuffer,
            replacement.capacity(),
        )
    });
    let base_text: &str = ts_rewritten.as_deref().unwrap_or(text);

    let rewritten_body;
    let mut rewritten_capacity = None;
    // P2.2 — the ignore_malformed rewrite parses + re-serialises EVERY
    // source line serially (client-blocking).  `apply_ignore_malformed`
    // can only modify a doc when some field in the target mapping carries
    // `ignore_malformed: true` or `ignore_above`; when no known mapping
    // declares either directive the whole pass is a guaranteed no-op, so
    // skip it instead of round-tripping the body through serde.
    let text_ref: &str = if state.engine.index_mappings.is_empty()
        || !state
            .engine
            .index_mappings
            .iter()
            .any(|e| mapping_has_ignore_directives(e.value()))
    {
        base_text
    } else {
        rewritten_body = rewrite_bulk_ignore_malformed(state, default_index, base_text);
        rewritten_capacity = Some(rewritten_body.capacity());
        &rewritten_body
    };
    let _ignore_rewritten_memory = rewritten_capacity.map(|capacity| {
        xerj_engine::ingest_memory::Retained::new(
            xerj_engine::ingest_memory::Category::HttpRewriteBuffer,
            capacity,
        )
    });

    // Cluster mode routes each action to its shard primary and copies the
    // stored document. No cluster handle: the local bulk pipeline, unchanged.
    // `wire` is the primary's `_version` / `_seq_no`. The accepting node does
    // not have the document, so the lookup below would report a fresh id.
    let (result, wire) = if state.engine.has_cluster() {
        crate::cluster_shard::bulk_on_primaries(state, default_index, text_ref, opts).await
    } else {
        (
            xerj_engine::bulk::process_bulk_with_opts(&state.engine, default_index, text_ref, opts)
                .await,
            Vec::new(),
        )
    };
    let took_ms = result.took_ms;
    let errors = result.errors;

    // Top-level HTTP status: if ALL items came back 429, return a top-level
    // 429 so clients that only look at the HTTP code (e.g. stock Python
    // urllib) also back off.  If only some items are 429 we still return 200
    // per ES bulk semantics, and the client is expected to read per-item
    // statuses.
    let all_backpressure = !result.items.is_empty() && result.items.iter().all(|i| i.status == 429);

    // RC4 W4 item 2: tally successfully-written docs per index so the
    // `docs_indexed` / `docs_indexed_by_index` counters reflect bulk ingest.
    // The bulk pipeline is the demo's primary ingest path and previously never
    // touched these counters — they read 0 even at millions of docs. Tallied
    // locally and flushed with one `inc_by` per index after the loop (keeps the
    // global atomic off the per-doc hot path). `item.index` here is the
    // concrete resolved index, so the label set stays bounded.
    let mut docs_indexed_tally: std::collections::HashMap<String, u64> =
        std::collections::HashMap::new();
    // Issue #329: the audit entry for this request reports what it covered.
    let mut failed_items = 0u64;
    let mut audited_index_names: std::collections::BTreeSet<String> =
        std::collections::BTreeSet::new();
    let mut items: Vec<EsBulkItem> = Vec::with_capacity(result.items.len());
    for (ordinal, item) in result.items.into_iter().enumerate() {
        let failed = item.error.is_some() || !(200..300).contains(&item.status);
        if failed {
            failed_items += 1;
        }
        audited_index_names.insert(item.index.clone());
        if !failed && matches!(item.action.as_str(), "index" | "create" | "update") {
            *docs_indexed_tally.entry(item.index.clone()).or_insert(0) += 1;
        }
        let get = item.get_source.clone().map(|s| {
            serde_json::json!({
                "found": true,
                "_source": s,
            })
        });
        // Real per-item `_seq_no` / `_version` — same resolvers `_mget` and
        // GET `_doc` use (were hardcoded `_version: 1` / a wall-clock
        // timestamp masquerading as `_seq_no`). A failed item omits them:
        // looking up a previous document and printing its version next to
        // `status: 400` reads as "this write landed".
        let (version, seq_no, primary_term, shards) = if failed {
            (None, None, None, None)
        } else if let Some((version, seq_no)) = wire.get(ordinal).copied().flatten() {
            (
                Some(version),
                Some(seq_no),
                Some(1),
                Some(crate::responses::EsShards::single_success()),
            )
        } else {
            let (version, seq_no) = state
                .engine
                .get_index(&item.index)
                .ok()
                .map(|idx| {
                    (
                        idx.lookup_version(&item.id).unwrap_or(1),
                        idx.lookup_seq_no(&item.id).unwrap_or(0),
                    )
                })
                .unwrap_or((1, 0));
            (
                Some(version),
                Some(seq_no),
                Some(1),
                Some(crate::responses::EsShards::single_success()),
            )
        };
        let item_result = EsBulkItemResult {
            index: item.index,
            id: item.id,
            version,
            // A successful action with no explicit result is a `delete`
            // (the only one that does not set one). A FAILED action has no
            // result at all — see `EsBulkItemResult::result`.
            result: if failed {
                None
            } else {
                Some(item.result.clone().unwrap_or_else(|| "deleted".to_string()))
            },
            shards,
            seq_no,
            primary_term,
            status: item.status,
            get,
            error: item.error.map(|e| {
                let error_type = bulk_item_error_type(&e).to_string();
                BulkItemError {
                    error_type,
                    reason: e,
                    status: item.status,
                }
            }),
        };
        let action = EsBulkItem {
            action: match item.action.as_str() {
                "index" => EsBulkItemAction::Index(item_result),
                "create" => EsBulkItemAction::Create(item_result),
                "update" => EsBulkItemAction::Update(item_result),
                "delete" => EsBulkItemAction::Delete(item_result),
                _ => EsBulkItemAction::Index(item_result),
            },
        };
        items.push(action);
    }

    // RC4 W4 item 2: flush the per-index docs-indexed tally (one atomic inc_by
    // per index) now the whole batch is accounted for.
    for (idx_name, n) in &docs_indexed_tally {
        state.metrics.record_docs_indexed(idx_name, *n);
    }

    // Issue #329: hand the audit layer the one thing it cannot see from the
    // request — how much this bulk actually did. `audit_mw` records ONE entry
    // per bulk (per document would let a single ingest evict the whole ring),
    // so the counts have to travel on the entry instead of in it.
    let audit_note = crate::audit_mw::AuditNote(format!(
        "items={} failed={} indices=[{}] took={took_ms}ms",
        items.len(),
        failed_items,
        render_index_list(&audited_index_names),
    ));

    let resp = EsBulkResponse {
        took: took_ms,
        errors,
        items,
    };

    // Fast path (hot bulk-ingest): the Value round-trip below exists ONLY to
    // patch `_seq_no`/`_primary_term` sentinels for indices that declare
    // `disable_sequence_numbers`. Scan the (small) settings map ONCE per
    // request; when no index declares the flag — the overwhelmingly common
    // case — serialize the typed response directly. The old shape paid
    // struct→Value (≈100 k node allocs for a 10 k-item batch), a per-item
    // DashMap get + full settings-Value clone, and then a SECOND
    // serialization of the Value to bytes, on every bulk response.
    let seq_disabled_anywhere = state.engine.index_settings.iter().any(|e| {
        let s = e.value();
        let as_bool = |val: &Value| {
            val.as_bool()
                .unwrap_or_else(|| val.as_str().map(|x| x == "true").unwrap_or(false))
        };
        s.pointer("/index/disable_sequence_numbers")
            .map(as_bool)
            .unwrap_or(false)
            || s.get("index")
                .and_then(|i| i.get("index.disable_sequence_numbers"))
                .map(as_bool)
                .unwrap_or(false)
            || s.get("index.disable_sequence_numbers")
                .map(as_bool)
                .unwrap_or(false)
    });
    if !seq_disabled_anywhere {
        let mut r = Json(&resp).into_response();
        r.extensions_mut().insert(audit_note);
        if all_backpressure {
            *r.status_mut() = axum::http::StatusCode::TOO_MANY_REQUESTS;
            r.headers_mut().insert(
                axum::http::header::RETRY_AFTER,
                axum::http::HeaderValue::from_static("1"),
            );
        }
        return r;
    }

    // Post-process to apply per-index `disable_sequence_numbers` sentinel
    // values (_seq_no=-2, _primary_term=0) in the response. Serialize to
    // Value first so we can mutate the per-item fields without widening
    // the struct-level u64 types.
    let mut resp_val = serde_json::to_value(&resp).unwrap_or(Value::Null);
    {
        let items_v = resp_val
            .pointer_mut("/items")
            .and_then(|v| v.as_array_mut());
        if let Some(items_arr) = items_v {
            for item in items_arr.iter_mut() {
                if let Some(obj) = item.as_object_mut() {
                    for action_key in ["index", "create", "update", "delete"] {
                        if let Some(result) = obj.get_mut(action_key) {
                            let ix = result
                                .get("_index")
                                .and_then(Value::as_str)
                                .unwrap_or("")
                                .to_string();
                            let disabled = state
                                .engine
                                .index_settings
                                .get(&ix)
                                .map(|v| {
                                    let s = v.clone();
                                    let as_bool = |val: &Value| {
                                        val.as_bool().unwrap_or_else(|| {
                                            val.as_str().map(|x| x == "true").unwrap_or(false)
                                        })
                                    };
                                    s.pointer("/index/disable_sequence_numbers")
                                        .map(as_bool)
                                        .unwrap_or(false)
                                        || s.get("index")
                                            .and_then(|i| i.get("index.disable_sequence_numbers"))
                                            .map(as_bool)
                                            .unwrap_or(false)
                                        || s.get("index.disable_sequence_numbers")
                                            .map(as_bool)
                                            .unwrap_or(false)
                                })
                                .unwrap_or(false);
                            if disabled {
                                if let Some(ro) = result.as_object_mut() {
                                    ro.insert("_seq_no".into(), json!(-2i64));
                                    ro.insert("_primary_term".into(), json!(0));
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    let mut r = Json(resp_val).into_response();
    r.extensions_mut().insert(audit_note);
    if all_backpressure {
        *r.status_mut() = axum::http::StatusCode::TOO_MANY_REQUESTS;
        r.headers_mut().insert(
            axum::http::header::RETRY_AFTER,
            axum::http::HeaderValue::from_static("1"),
        );
    }
    r
}

/// Map a per-item `_bulk` error reason to its ES exception type name so
/// clients can match on `error.type`.
fn bulk_item_error_type(e: &str) -> &'static str {
    if e.starts_with("if _id is specified")
        || e.contains("missing document body")
        || e.contains("unknown action type")
        || e.contains("no write index is defined")
        || e.contains("has more than one write index")
        || e.starts_with("pipeline with id")
    {
        "illegal_argument_exception"
    } else if e.starts_with("version conflict") {
        "version_conflict_engine_exception"
    } else if e.contains("index not found") || e.starts_with("no such index") {
        "index_not_found_exception"
    } else if e.contains("dynamic template")
        || e.contains("failed to parse field")
        // Malformed doc-body JSON on a bulk item: ES 8.13
        // reports `document_parsing_exception` ("[1:1] failed
        // to parse: ..."), not illegal_argument.
        || e.contains("invalid document JSON")
    {
        "document_parsing_exception"
    } else if e.contains("embedding backend returned") && e.contains("mapping requires") {
        // #2191: the embedding backend's vector width contradicts the
        // semantic_text mapping. Retrying cannot help, so it is reported as a
        // mapping error, not a retryable `engine_exception`.
        "mapper_parsing_exception"
    } else {
        "engine_exception"
    }
}

#[cfg(test)]
mod bulk_item_error_type_tests {
    use super::bulk_item_error_type;

    /// #2191: an embedding width that contradicts the mapping is a
    /// `mapper_parsing_exception`, while a genuine backend fault stays an
    /// `engine_exception`.
    #[test]
    fn an_embedding_width_mismatch_is_a_mapper_parsing_exception() {
        assert_eq!(
            bulk_item_error_type(
                "invalid mapping: field [body]: embedding backend returned width 4, \
                 mapping requires 8; the embedding backend's vector width is fixed"
            ),
            "mapper_parsing_exception"
        );
        assert_eq!(
            bulk_item_error_type(
                "invalid mapping: field [body]: embedding backend returned 1 vectors with \
                 widths {4} for 1 texts; mapping requires width 8"
            ),
            "mapper_parsing_exception"
        );
        assert_eq!(
            bulk_item_error_type("semantic_text batch embed failed: connection refused"),
            "engine_exception"
        );
        assert_eq!(
            bulk_item_error_type("failed to parse field [n]"),
            "document_parsing_exception"
        );
    }
}

#[cfg(test)]
mod malformed_bulk_route_tests {
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::{Request, StatusCode},
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    #[tokio::test]
    async fn malformed_bulk_source_returns_actionable_public_item_error() {
        let body = concat!(
            "{\"index\":{\"_index\":\"route-errors\",\"_id\":\"valid-doc\"}}\n",
            "{\"title\":\"valid\"}\n",
            "{\"index\":{\"_index\":\"route-errors\",\"_id\":\"broken-doc\"}}\n",
            "{\"title\":\"unterminated}\n",
        );
        let response = crate::router::build_es_compat_router(test_state())
            .oneshot(
                Request::post("/_bulk")
                    .header("content-type", "application/x-ndjson")
                    .body(Body::from(body))
                    .expect("request"),
            )
            .await
            .expect("route response");

        // ES bulk reports per-item parse failures inside a successful HTTP
        // response; callers must inspect `errors` and each item's status.
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        let response: Value = serde_json::from_slice(&bytes).expect("JSON response");
        assert_eq!(response["errors"], true);
        assert_eq!(response["items"][0]["index"]["status"], 201);

        let ok_item = &response["items"][0]["index"];
        assert!(
            ok_item.get("_version").is_some()
                && ok_item.get("_seq_no").is_some()
                && ok_item.get("_primary_term").is_some()
                && ok_item.get("_shards").is_some(),
            "a successful bulk item keeps its versioning fields: {ok_item}"
        );

        let failed = &response["items"][1]["index"];
        assert_eq!(failed["_id"], "broken-doc");
        assert_eq!(failed["status"], 400);
        for absent in ["_version", "_seq_no", "_primary_term", "_shards", "result"] {
            assert!(
                failed.get(absent).is_none(),
                "a failed bulk item must omit {absent}: {failed}"
            );
        }
        assert_eq!(
            failed["error"]["type"], "document_parsing_exception",
            "unexpected response: {response}"
        );
        let reason = failed["error"]["reason"]
            .as_str()
            .expect("error reason string");
        for expected in [
            "document ID \"broken-doc\"",
            "bulk item position 2",
            "parser error:",
            "parser location: line 1, column ",
            "Fix: replace this source line with exactly one complete UTF-8 JSON object.",
            "Related help: xerj index --help and https://xerj.org/llms.txt",
        ] {
            assert!(
                reason.contains(expected),
                "missing {expected:?} in public reason: {reason}"
            );
        }
    }
}

/// Issue #204 — an ingest pipeline that cannot be compiled must be REFUSED,
/// not stored, acknowledged and quietly skipped.
#[cfg(test)]
mod ingest_pipeline_fail_closed_tests {
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::{Request, StatusCode},
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    async fn put_pipeline(state: AppState, id: &str, body: Value) -> (StatusCode, Value) {
        let response = crate::router::build_es_compat_router(state)
            .oneshot(
                Request::put(format!("/_ingest/pipeline/{id}"))
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("route response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    #[tokio::test]
    async fn an_uncompilable_pipeline_is_rejected_and_not_stored() {
        let state = test_state();

        // `social_security` is not a PII type xerj can redact. Pre-fix this
        // answered 200/acknowledged, `GET` echoed it back, and every document
        // routed through it kept its PII.
        let (status, body) = put_pipeline(
            state.clone(),
            "redact",
            json!({
                "processors": [
                    { "pii_redaction": { "types": ["social_security"] } }
                ]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "body: {body}");

        // Nothing was stored: GET must 404 rather than echo a pipeline that
        // does not exist in compiled form.
        let response = crate::router::build_es_compat_router(state.clone())
            .oneshot(
                Request::get("/_ingest/pipeline/redact")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("route response");
        assert_eq!(response.status(), StatusCode::NOT_FOUND);
        assert!(!state.engine.pipelines.contains_key("redact"));
        assert!(!state.engine.transform_pipelines.contains_key("redact"));
    }

    #[tokio::test]
    async fn a_processor_entry_that_is_not_a_processor_is_rejected() {
        // Pre-fix `filter_map` dropped this silently and the pipeline compiled
        // with zero stages.
        let (status, body) = put_pipeline(
            test_state(),
            "broken",
            json!({ "processors": [ "lowercase" ] }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "body: {body}");
    }

    #[tokio::test]
    async fn a_compilable_pipeline_still_round_trips() {
        let state = test_state();
        let (status, _) = put_pipeline(
            state.clone(),
            "ok",
            json!({
                "processors": [
                    { "pii_redaction": { "types": ["email"] } },
                    { "set": { "field": "env", "value": "prod" } }
                ]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(state.engine.transform_pipelines.contains_key("ok"));

        let response = crate::router::build_es_compat_router(state)
            .oneshot(
                Request::get("/_ingest/pipeline/ok")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("route response");
        assert_eq!(response.status(), StatusCode::OK);
    }

    async fn index_doc(
        state: AppState,
        index: &str,
        id: &str,
        pipeline: &str,
        doc: Value,
    ) -> (StatusCode, Value) {
        let response = crate::router::build_es_compat_router(state)
            .oneshot(
                Request::put(format!(
                    "/{index}/_doc/{id}?refresh=true&pipeline={pipeline}"
                ))
                .header("content-type", "application/json")
                .body(Body::from(doc.to_string()))
                .expect("request"),
            )
            .await
            .expect("route response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    async fn get_source(state: AppState, index: &str, id: &str) -> Value {
        let response = crate::router::build_es_compat_router(state)
            .oneshot(
                Request::get(format!("/{index}/_doc/{id}"))
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("route response");
        let bytes = to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        serde_json::from_slice::<Value>(&bytes)
            .expect("json")
            .get("_source")
            .cloned()
            .unwrap_or(Value::Null)
    }

    /// A processor xerj does not implement is ACCEPTED (Elasticsearch accepts
    /// it and `_simulate` still walks it) — but no document may then be
    /// ingested through it. Pre-fix the write answered `201 Created` with the
    /// document stored untransformed.
    #[tokio::test]
    async fn a_pipeline_with_an_unimplemented_processor_refuses_the_write() {
        let state = test_state();

        // `pipeline` (a pipeline calling another pipeline) is a real ES
        // processor that xerj's compiled ingest path does not implement.
        let (status, body) = put_pipeline(
            state.clone(),
            "outer",
            json!({ "processors": [ { "pipeline": { "name": "inner" } } ] }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "body: {body}");
        assert_eq!(body["acknowledged"], json!(true));

        // Stored and visible, exactly as ES does…
        assert!(state.engine.pipelines.contains_key("outer"));
        // …but explicitly marked as having no compiled form.
        assert!(state.engine.unrunnable_pipelines.contains_key("outer"));
        assert!(!state.engine.transform_pipelines.contains_key("outer"));

        // …and a write through it is REFUSED rather than silently untransformed.
        let (status, body) = index_doc(
            state.clone(),
            "logs",
            "1",
            "outer",
            json!({ "msg": "hello" }),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "body: {body}");
        let reason = body["error"]["reason"].as_str().unwrap_or_default();
        assert!(
            reason.contains("outer") && reason.contains("pipeline"),
            "reason should name the pipeline: {reason}"
        );

        // Nothing was written.
        assert!(get_source(state, "logs", "1").await.is_null());
    }

    /// The ES `rename` processor used to translate to a config shape the
    /// `field_rename` plugin rejects (`from`/`to` instead of `mappings`), so
    /// EVERY rename processor failed to compile — invisibly, under a 200.
    #[tokio::test]
    async fn the_es_rename_processor_actually_renames() {
        let state = test_state();
        let (status, body) = put_pipeline(
            state.clone(),
            "ren",
            json!({
                "processors": [
                    { "rename": { "field": "old_name", "target_field": "new_name" } }
                ]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "body: {body}");
        assert!(
            state.engine.transform_pipelines.contains_key("ren"),
            "rename must COMPILE, not merely be stored"
        );

        let (status, body) = index_doc(
            state.clone(),
            "renamed",
            "1",
            "ren",
            json!({ "old_name": "v" }),
        )
        .await;
        assert!(status.is_success(), "body: {body}");

        let source = get_source(state, "renamed", "1").await;
        assert_eq!(source["new_name"], json!("v"), "source: {source}");
        assert!(source.get("old_name").is_none(), "source: {source}");
    }

    /// `DELETE` used to remove only the definition, leaving the compiled
    /// pipeline live for anything that reached it by name.
    #[tokio::test]
    async fn deleting_a_pipeline_removes_the_compiled_form_too() {
        let state = test_state();
        let (status, _) = put_pipeline(
            state.clone(),
            "gone",
            json!({ "processors": [ { "set": { "field": "a", "value": "b" } } ] }),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(state.engine.transform_pipelines.contains_key("gone"));

        let response = crate::router::build_es_compat_router(state.clone())
            .oneshot(
                Request::delete("/_ingest/pipeline/gone")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("route response");
        assert_eq!(response.status(), StatusCode::OK);
        assert!(!state.engine.pipelines.contains_key("gone"));
        assert!(!state.engine.transform_pipelines.contains_key("gone"));
    }

    /// Re-defining a pipeline with something we cannot compile must not leave
    /// the previous stages quietly running under the new definition's name.
    #[tokio::test]
    async fn redefining_with_an_unimplemented_processor_retires_the_old_stages() {
        let state = test_state();
        let (status, _) = put_pipeline(
            state.clone(),
            "evolving",
            json!({ "processors": [ { "set": { "field": "a", "value": "b" } } ] }),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(state.engine.transform_pipelines.contains_key("evolving"));

        let (status, _) = put_pipeline(
            state.clone(),
            "evolving",
            json!({ "processors": [ { "pipeline": { "name": "other" } } ] }),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert!(
            !state.engine.transform_pipelines.contains_key("evolving"),
            "the superseded compiled pipeline must not keep running"
        );
        assert!(state.engine.unrunnable_pipelines.contains_key("evolving"));
    }
}

#[cfg(test)]
mod script_query_end_to_end_tests {
    //! Regression coverage for a real bug: the `script` query's unit tests
    //! (in xerj-engine's index.rs) all exercised `doc_matches_query`
    //! directly, never a real `POST /{index}/_search` — so they passed
    //! while the query silently returned zero hits for every real search,
    //! because `is_doc_scan_query` never routed `QueryNode::Script` into
    //! doc-scan. This test goes through the actual HTTP route so a
    //! regression here fails loudly.
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::Request,
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    #[tokio::test]
    async fn script_query_matches_an_indexed_document_via_real_search() {
        let router = crate::router::build_es_compat_router(test_state());

        let index_response = router
            .clone()
            .oneshot(
                Request::post("/script-query-e2e/_doc/1")
                    .header("content-type", "application/json")
                    .body(Body::from(r#"{"x": 10}"#))
                    .expect("request"),
            )
            .await
            .expect("index response");
        assert!(
            index_response.status().is_success(),
            "indexing failed: {:?}",
            index_response.status()
        );

        let search_body = serde_json::to_vec(&json!({
            "query": {
                "script": {
                    "script": {"source": "doc['x'].value > 5"}
                }
            }
        }))
        .expect("serialize query");

        let search_response = router
            .oneshot(
                Request::post("/script-query-e2e/_search")
                    .header("content-type", "application/json")
                    .body(Body::from(search_body))
                    .expect("request"),
            )
            .await
            .expect("search response");
        assert!(
            search_response.status().is_success(),
            "search failed: {:?}",
            search_response.status()
        );

        let bytes = to_bytes(search_response.into_body(), usize::MAX)
            .await
            .expect("response bytes");
        let response: Value = serde_json::from_slice(&bytes).expect("JSON response");
        let total = response["hits"]["total"]["value"].as_u64().unwrap_or(0);
        assert_eq!(
            total, 1,
            "script query should match the freshly indexed document via a real search, got: {response}"
        );
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Schema conversion helpers
// ─────────────────────────────────────────────────────────────────────────────

/// Decide what a `dense_vector` field's `quantization` means — the single
/// place that knows which schemes this build actually implements.
///
/// **`quantization` is strict; `index_options.type` is not, and the asymmetry
/// is deliberate.** `index_options.type` is Elasticsearch's key: a real ES
/// mapping carrying `hnsw`, `flat`, `bbq_hnsw` or `int4_hnsw` must still
/// create an index here, because refusing it would break the wire
/// compatibility this surface exists for. Those families are served by the
/// exact f32 scan, which still answers the contract ES states for them (a
/// nearest-neighbour result set) — a substitution that costs memory, not
/// answers. `quantization` is XERJ's own key with no ES meaning, so nothing is
/// owed to compatibility and everything is owed to the operator: the value is
/// a request for a specific memory/recall trade, and the only honest answers
/// are "done" and "no".
///
/// Issue #275: this match used to end in `_ => {}`. `"scalar4"`, `"binary"`,
/// `"int4"` and typos such as `"sq8"` were accepted with a `200`, echoed back
/// verbatim by `GET /_mapping`, and then ignored — the field stored
/// full-precision f32 while the mapping the operator read back to confirm it
/// said otherwise. Only `Some("scalar8")` is ever read by the serving path
/// (`xerj-engine/src/index.rs:10440` and `:10847`), so every other value was
/// inert. `Config::validate` has refused an unimplemented `[vector]
/// default_quantization` since #207; this is the same guard at the other
/// surface that sets the same field.
fn resolve_vector_quantization(
    field_name: &str,
    field_def: &Value,
) -> Result<Option<String>, String> {
    // ES expresses 8-bit scalar quantization through `index_options.type`:
    // the `int8_*` families map onto our serving-path SQ8 code store. Every
    // other family keeps the exact f32 scan, so `quantization` stays unset for
    // them and their behaviour is byte-identical to an unquantized field.
    let mut quant: Option<String> = None;
    if let Some(io_type) = field_def
        .get("index_options")
        .and_then(|io| io.get("type"))
        .and_then(Value::as_str)
    {
        if matches!(io_type, "int8_hnsw" | "int8_flat") {
            quant = Some("scalar8".to_string());
        }
    }

    let Some(q) = field_def.get("quantization") else {
        return Ok(quant);
    };
    let Some(q) = q.as_str() else {
        return Err(format!(
            "Failed to parse mapping: [quantization] on field [{field_name}] must be a string; \
             this build implements [\"none\"] and [\"scalar8\"] (alias [\"int8\"])"
        ));
    };
    match q {
        // Honoured: a `scalar8` field keeps a per-field u8 code store and the
        // kNN path scores candidates by decoding those codes.
        "scalar8" | "int8" => Ok(Some("scalar8".to_string())),
        // Explicit opt-out, and it overrides an `int8_*` index_options.type.
        "none" => Ok(None),
        // Named but unimplemented. `binary` is refused for exactly the reason
        // `Config::validate` refuses `default_quantization = "binary"`: there
        // is no BinaryQuantizer, so honouring it would store full precision
        // while the operator sized a cluster on a 32× reduction. `scalar4` /
        // `int4` do have a `Scalar4Quantizer` in xerj-vector, but nothing in
        // the serving path reaches it — an unreachable quantizer is not an
        // implemented one, and accepting the name is the same lie in a
        // smaller font.
        "binary" | "scalar4" | "int4" => Err(format!(
            "Failed to parse mapping: quantization [{q}] on field [{field_name}] is not \
             implemented in this build and would silently store full-precision vectors; \
             this build implements [\"none\"] and [\"scalar8\"] (alias [\"int8\"])"
        )),
        other => Err(format!(
            "Failed to parse mapping: unknown quantization [{other}] on field [{field_name}]; \
             this build implements [\"none\"] and [\"scalar8\"] (alias [\"int8\"])"
        )),
    }
}

fn es_properties_to_schema(properties: &Value) -> Result<Schema, String> {
    let mut schema = Schema::empty();
    for field in es_properties_to_fields(properties)? {
        let _ = schema.add_field(field);
    }
    Ok(schema)
}

/// Convert an ES `properties` object into engine [`FieldConfig`]s.
///
/// Returns `Err` with an ES-shaped `mapper_parsing_exception` reason when a
/// field asks for something this build cannot deliver. The check lives *here*,
/// at the site every engine schema is built from, and not only beside the
/// handlers: #207's sibling defect survived a fix placed next to one handler
/// because a second entry point kept building schemas the old way.
fn es_properties_to_fields(properties: &Value) -> Result<Vec<FieldConfig>, String> {
    let mut fields = Vec::new();
    let obj = match properties.as_object() {
        Some(o) => o,
        None => return Ok(fields),
    };
    for (field_name, field_def) in obj {
        let es_type = field_def
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or("object");

        // Handle alias field type: store the path as a special null_value marker.
        if es_type == "alias" {
            if let Some(path) = field_def.get("path").and_then(Value::as_str) {
                let mut fc = FieldConfig::new(field_name.clone(), FieldType::Object);
                fc.options.null_value = Some(Value::String(format!("__alias__:{}", path)));
                fields.push(fc);
            }
            continue;
        }

        let native_type = es_type_to_native(es_type);
        let mut fc = FieldConfig::new(field_name.clone(), native_type);

        // #790 — remember `date` vs `date_nanos`. Both collapse onto
        // `FieldType::Date`, and without this flag the engine had to guess a
        // date's scale from the value ("4+ fractional digits means nanos"),
        // which mixed millisecond and nanosecond keys inside a single `date`
        // column and broke both its sort order and its ranges. `FieldConfig::new`
        // already defaults a `Date` to `Millis`; the override is what keeps a
        // declared `date_nanos` on its own precision.
        if native_type == FieldType::Date {
            fc.options.date_precision = Some(if es_type == "date_nanos" {
                xerj_common::types::DatePrecision::Nanos
            } else {
                xerj_common::types::DatePrecision::Millis
            });
        }
        if let Some(sub_props) = field_def.get("properties") {
            fc.fields = es_properties_to_fields(sub_props)?;
        }

        // `doc_values` — carry the DECLARED mapping intent onto the field.
        //
        // This option was accepted, echoed back by `GET _mapping`, and then
        // ignored: the doc-values side-car builder is schema-free and filed a
        // column for every `_source` string, so `"doc_values": false` bought
        // nothing and aggregating on such a field still succeeded (where ES
        // errors). An accepted-but-ignored mapping option is a correctness bug
        // on its own, before any footprint argument.
        //
        // The default follows ES: analyzed/large types get no doc-values
        // unless asked for. Keying on the DECLARED es_type is load-bearing —
        // `text` and `semantic_text` both resolve to `FieldType::Text`, and on
        // real corpora `semantic_text` is 86-92% of the side-car while plain
        // `text` is under 5%, so a policy that only looked at the resolved type
        // (or only at the literal string "text") would miss almost all of it.
        //
        // An explicit `"doc_values": true` on a text field is still honoured:
        // modern ES supports that behind the `mapper.text.doc_values` feature,
        // and the conformance suite exercises it in
        // tests/es-compat-yaml/yaml/aggregations/terms_text_docvalues.yml.
        let doc_values_default = !matches!(
            es_type,
            "text"
                | "annotated_text"
                | "match_only_text"
                | "search_as_you_type"
                | "semantic_text"
                | "binary"
                | "object"
                | "nested"
        );
        fc.options.doc_values = field_def
            .get("doc_values")
            .and_then(Value::as_bool)
            .unwrap_or(doc_values_default);

        // `index` — the sibling of `doc_values` above, and the last open
        // instance of the accepted-and-ignored class in #204. `"index": false`
        // was parsed nowhere, echoed back verbatim by `GET _mapping`, and had
        // no effect at all: the field kept its inverted index and every query
        // against it kept matching.
        //
        // Carrying the declared intent here is what makes the two halves of
        // the fix possible — `fts_excluded_fields` (xerj-engine) drops the
        // field from the inverted index at flush/merge, and
        // `unsearchable_query_field` (xerj-engine) rejects queries that ES
        // rejects. Default `true` mirrors ES: every field is indexed unless
        // the mapping says otherwise.
        fc.options.indexed = field_def
            .get("index")
            .and_then(Value::as_bool)
            .unwrap_or(true);

        // Handle copy_to: store the target field in a special null_value marker.
        if let Some(copy_target) = field_def.get("copy_to").and_then(Value::as_str) {
            fc.options.null_value = Some(Value::String(format!("__copy_to__:{}", copy_target)));
        }

        // `semantic_text` — auto-embed on ingest. Attach an EmbeddingConfig so
        // the engine vectorises this field's text into a companion vector field
        // (`<field>_vector`) at index time, making it kNN-searchable via the
        // `semantic` query with zero external configuration (built-in embedder)
        // or via the configured EmbeddingProxy when present. The native type
        // stays `Object` (the raw text still lives in `_source`); the derived
        // vector field carries the searchable embedding.
        if es_type == "semantic_text" {
            // Dimensionality for the built-in embedder — honour an explicit
            // `dimensions`/`dims` override, else the built-in default (384).
            // Default 384 mirrors xerj_ai::local::DEFAULT_DIMS (the built-in
            // embedder width); kept as a literal here to avoid a build-graph
            // dependency from xerj-api onto xerj-ai.
            let dims = field_def
                .get("dimensions")
                .or_else(|| field_def.get("dims"))
                .and_then(Value::as_u64)
                .map(|d| d as usize)
                .unwrap_or(384);
            fc.options.dimensions = Some(dims);
            // Built-in embeddings are L2-normalised, so cosine is the
            // default. Honour an explicit similarity for proxy/custom
            // embedders and carry it onto the internal vector companion.
            let similarity = field_def
                .get("similarity")
                .and_then(Value::as_str)
                .unwrap_or("cosine")
                .to_string();
            fc.options.similarity = Some(similarity);
            let target_field = field_def
                .get("target_field")
                .and_then(Value::as_str)
                .map(str::to_string)
                .unwrap_or_else(|| format!("{field_name}_vector"));
            // `inference_id` / `model_id` / `inference_endpoint` are stored so a
            // mapping round-trips. Ingest does not read them: the server's
            // `--embed-mode` embeds every document, and create/put mapping
            // warns when these keys name a different embedder (#1612).
            let endpoint = field_def
                .get("inference_endpoint")
                .and_then(Value::as_str)
                .map(str::to_string);
            let model = field_def
                .get("inference_id")
                .or_else(|| field_def.get("model_id"))
                .and_then(Value::as_str)
                .map(str::to_string);
            fc.embedding = Some(xerj_common::types::EmbeddingConfig {
                endpoint,
                model,
                target_field: Some(target_field),
            });
        }

        // Propagate dense_vector config into FieldOptions so the search
        // path can look up similarity + dims without re-parsing the raw
        // mapping.
        if es_type == "dense_vector" {
            if let Some(dims) = field_def.get("dims").and_then(Value::as_u64) {
                fc.options.dimensions = Some(dims as usize);
            }
            if let Some(sim) = field_def.get("similarity").and_then(Value::as_str) {
                fc.options.similarity = Some(sim.to_string());
            } else {
                // ES default similarity for dense_vector with index: true.
                fc.options.similarity = Some("cosine".to_string());
            }

            fc.options.quantization = resolve_vector_quantization(field_name, field_def)?;
        }

        fields.push(fc);
    }

    // A semantic_text field writes its embedding to a companion field. That
    // companion is internal when the caller did not declare it explicitly,
    // but it still has to be a native Vector in the engine schema: HNSW pins
    // only mapped vector fields and deliberately ignores arbitrary numeric
    // arrays. Add companions after parsing all public fields so declaration
    // order cannot overwrite an explicit target.
    let semantic_companions: Vec<FieldConfig> = fields
        .iter()
        .filter_map(|field| {
            let embedding = field.embedding.as_ref()?;
            let target = embedding
                .target_field
                .clone()
                .unwrap_or_else(|| format!("{}_vector", field.name));
            if field_configs_contain_logical_path(&fields, &target) {
                return None;
            }
            let mut companion = FieldConfig::new(target, FieldType::Vector);
            companion.options.dimensions = field.options.dimensions;
            companion.options.similarity = field.options.similarity.clone();
            Some(companion)
        })
        .collect();
    fields.extend(semantic_companions);
    Ok(fields)
}

fn field_configs_contain_logical_path(fields: &[FieldConfig], target: &str) -> bool {
    fn walk(fields: &[FieldConfig], prefix: &str, target: &str) -> bool {
        fields.iter().any(|field| {
            let path = if prefix.is_empty() {
                field.name.clone()
            } else {
                format!("{prefix}.{}", field.name)
            };
            path == target || (!field.fields.is_empty() && walk(&field.fields, &path, target))
        })
    }
    walk(fields, "", target)
}

fn es_type_to_native(es_type: &str) -> FieldType {
    match es_type {
        // `semantic_text` carries plain text in `_source` (the derived
        // embedding lives in the companion `<field>_vector` field), so on
        // the LEXICAL side it must behave exactly like `text`: schema type
        // Text puts it in the search path's `text_fields` set and gives it
        // the standard analyzer + positions in the segment FTS built at
        // flush. It used to fall through to `Object`, which FTS-indexes
        // the whole value as ONE keyword token — match/BM25 then found the
        // doc pre-flush (memtable scan) but ZERO hits post-flush (segment
        // FTS had no standard-analyzed tokens for the field).
        "text" | "semantic_text" => FieldType::Text,
        "keyword" | "constant_keyword" | "wildcard" => FieldType::Keyword,
        "long" | "integer" | "short" | "byte" | "unsigned_long" => FieldType::Long,
        "double" | "float" | "half_float" | "scaled_float" => FieldType::Double,
        "boolean" => FieldType::Boolean,
        "date" | "date_nanos" => FieldType::Date,
        "ip" => FieldType::Ip,
        "dense_vector" => FieldType::Vector,
        "geo_point" => FieldType::GeoPoint,
        "binary" => FieldType::Binary,
        "nested" => FieldType::Nested,
        _ => FieldType::Object,
    }
}

#[cfg(test)]
mod date_precision_mapping_tests {
    use super::*;
    use xerj_common::types::DatePrecision;

    /// #790: `date` and `date_nanos` both collapse onto `FieldType::Date`, so
    /// the mapping is the only place the distinction can be recorded. Without
    /// it the engine has to guess a date's epoch scale from each value, which
    /// mixes millisecond and nanosecond keys inside one `date` column.
    #[test]
    fn date_and_date_nanos_record_their_declared_precision() {
        let fields = es_properties_to_fields(&json!({
            "when": { "type": "date" },
            "when_ns": { "type": "date_nanos" },
            "name": { "type": "keyword" },
            "nested": { "type": "object", "properties": { "at": { "type": "date_nanos" } } }
        }))
        .expect("valid mapping");
        let by_name = |n: &str| {
            fields
                .iter()
                .find(|f| f.name == n)
                .unwrap_or_else(|| panic!("{n} missing"))
        };
        assert_eq!(by_name("when").field_type, FieldType::Date);
        assert_eq!(
            by_name("when").options.date_precision,
            Some(DatePrecision::Millis)
        );
        assert_eq!(
            by_name("when_ns").options.date_precision,
            Some(DatePrecision::Nanos)
        );
        // Non-date fields carry nothing, so the flag never widens the
        // persisted mapping for the rest of the schema.
        assert_eq!(by_name("name").options.date_precision, None);
        // Sub-properties go through the same recursion.
        let inner = &by_name("nested").fields[0];
        assert_eq!(inner.name, "at");
        assert_eq!(inner.options.date_precision, Some(DatePrecision::Nanos));
    }
}

#[cfg(test)]
mod date_nanos_cross_index_sort_tests {
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::Request,
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    async fn request_json(
        state: &AppState,
        method: &str,
        path: &str,
        body: Value,
    ) -> (StatusCode, Value) {
        let response = crate::router::build_es_compat_router(state.clone())
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("route response");
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json = serde_json::from_slice(&bytes).unwrap_or_else(|error| {
            panic!(
                "{method} {path} returned non-JSON ({error}): {}",
                String::from_utf8_lossy(&bytes)
            )
        });
        (status, json)
    }

    /// `index`, mapped with a single `timestamp` field of `es_type`, holding
    /// `docs` as `(id, value)`.
    async fn build(state: &AppState, index: &str, es_type: &str, docs: &[(&str, &str)]) {
        let (status, body) = request_json(
            state,
            "PUT",
            &format!("/{index}"),
            json!({"mappings": {"properties": {"timestamp": {"type": es_type}}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        for (id, value) in docs {
            let (status, body) = request_json(
                state,
                "PUT",
                &format!("/{index}/_doc/{id}"),
                json!({"timestamp": value}),
            )
            .await;
            assert!(status.is_success(), "{body}");
        }
        state
            .engine
            .get_index(index)
            .expect("index")
            .refresh()
            .await
            .expect("refresh");
    }

    fn ids(json: &Value) -> Vec<String> {
        json["hits"]["hits"]
            .as_array()
            .expect("hits")
            .iter()
            .map(|h| h["_id"].as_str().unwrap().to_string())
            .collect()
    }

    /// Two indices whose `timestamp` is mapped `date` in one and `date_nanos`
    /// in the other, with instants that INTERLEAVE chronologically.
    async fn two_scaled_indices(state: &AppState) {
        build(
            state,
            "nt-ms",
            "date",
            &[
                ("ms-feb", "2021-02-11T08:30:04.828Z"),
                ("ms-jun", "2021-06-11T04:30:04.828Z"),
            ],
        )
        .await;
        build(
            state,
            "nt-ns",
            "date_nanos",
            &[
                ("ns-apr", "2021-04-15T06:30:04.821123456Z"),
                ("ns-aug", "2021-08-21T03:30:04.732123456Z"),
            ],
        )
        .await;
    }

    /// #889: `numeric_type` is what makes a cross-index sort over a `date` and
    /// a `date_nanos` field comparable at all. Without it both sides emit keys
    /// on their own scale — epoch-ms ~1.6e12 against epoch-ns ~1.6e18 — and no
    /// comparison of the raw longs is chronological. `numeric_type` names one
    /// scale and every participating index produces keys on it.
    #[tokio::test]
    async fn numeric_type_date_nanos_interleaves_a_date_and_a_date_nanos_index() {
        let state = test_state();
        two_scaled_indices(&state).await;
        let (status, body) = request_json(
            &state,
            "POST",
            "/nt-*/_search",
            json!({
                "size": 4,
                "sort": [{"timestamp": {"order": "asc", "numeric_type": "date_nanos"}}]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(
            ids(&body),
            vec!["ms-feb", "ns-apr", "ms-jun", "ns-aug"],
            "#889: numeric_type date_nanos must order both indices by instant: {body}"
        );
        // Every sort value is on the requested scale, so the caller can page
        // with `search_after` in that one space.
        let sorts: Vec<i64> = body["hits"]["hits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| h["sort"][0].as_i64().unwrap())
            .collect();
        assert!(
            sorts.iter().all(|v| *v > 1_000_000_000_000_000),
            "#889: numeric_type date_nanos must emit epoch-NANOSECOND sort values, got {sorts:?}"
        );
        assert!(sorts.windows(2).all(|w| w[0] < w[1]), "{sorts:?}");
    }

    #[tokio::test]
    async fn numeric_type_date_interleaves_on_the_millisecond_scale() {
        let state = test_state();
        two_scaled_indices(&state).await;
        let (status, body) = request_json(
            &state,
            "POST",
            "/nt-*/_search",
            json!({
                "size": 4,
                "sort": [{"timestamp": {"order": "asc", "numeric_type": "date"}}]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(
            ids(&body),
            vec!["ms-feb", "ns-apr", "ms-jun", "ns-aug"],
            "#889: numeric_type date must order both indices by instant: {body}"
        );
        let sorts: Vec<i64> = body["hits"]["hits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| h["sort"][0].as_i64().unwrap())
            .collect();
        assert!(
            sorts.iter().all(|v| *v < 1_000_000_000_000_000),
            "#889: numeric_type date must emit epoch-MILLISECOND sort values, got {sorts:?}"
        );
        assert!(sorts.windows(2).all(|w| w[0] < w[1]), "{sorts:?}");
        // …and paging through that space works, because the cursor is
        // normalised on the same forced scale.
        let (status, page2) = request_json(
            &state,
            "POST",
            "/nt-*/_search",
            json!({
                "size": 2,
                "sort": [{"timestamp": {"order": "asc", "numeric_type": "date"}}],
                "search_after": [sorts[1]]
            }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{page2}");
        assert_eq!(ids(&page2), vec!["ms-jun", "ns-aug"], "{page2}");
    }

    /// The documented DEFAULT, kept honest: with no `numeric_type` ES compares
    /// the raw longs, so every epoch-nanosecond key outranks every
    /// epoch-millisecond one regardless of instant. `search/240_date_nanos.yml`
    /// ("doc value fields are working as expected across date and date_nanos
    /// fields") asserts exactly that — a `date_nanos` doc at …12.123456789
    /// sorts above a `date` doc at …12.987 on `desc`. This test pins that the
    /// #889 change did not quietly turn the default into a conversion.
    #[tokio::test]
    async fn without_numeric_type_the_two_scales_do_not_interleave() {
        let state = test_state();
        two_scaled_indices(&state).await;
        let (status, body) = request_json(
            &state,
            "POST",
            "/nt-*/_search",
            json!({"size": 4, "sort": [{"timestamp": "asc"}]}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(
            ids(&body),
            vec!["ms-feb", "ms-jun", "ns-apr", "ns-aug"],
            "#889: without numeric_type the raw longs are compared, ms block first: {body}"
        );
    }

    /// #889 "related, also unfixed": `date` and `date_nanos` share one native
    /// type, so a schema-derived mapping reported every `date_nanos` field as
    /// `date`. A client that reads a mapping and writes it back — the GET → PUT
    /// round trip every reindex helper performs — silently downgraded the field
    /// to millisecond resolution.
    #[test]
    fn schema_derived_mapping_reports_date_nanos_as_date_nanos() {
        let mut ns = FieldConfig::new("when_ns", FieldType::Date);
        ns.options.date_precision = Some(xerj_common::types::DatePrecision::Nanos);
        let schema = Schema {
            fields: vec![FieldConfig::new("when", FieldType::Date), ns],
            version: 0,
            updated_at: Utc::now(),
        };
        let props = schema_to_es_properties(&schema);
        assert_eq!(props["when"]["type"], json!("date"));
        assert_eq!(props["when_ns"]["type"], json!("date_nanos"));
    }
}

#[cfg(test)]
mod semantic_companion_schema_tests {
    use super::*;

    #[test]
    fn implicit_companion_is_a_native_vector_with_semantic_options() {
        let fields = es_properties_to_fields(&json!({
            "body": {
                "type": "semantic_text",
                "dimensions": 96,
                "similarity": "dot_product"
            },
            "ports": { "type": "object" }
        }))
        .expect("valid mapping");

        let body = fields.iter().find(|field| field.name == "body").unwrap();
        assert_eq!(
            body.embedding.as_ref().unwrap().target_field.as_deref(),
            Some("body_vector")
        );
        let companion = fields
            .iter()
            .find(|field| field.name == "body_vector")
            .unwrap();
        assert_eq!(companion.field_type, FieldType::Vector);
        assert_eq!(companion.options.dimensions, Some(96));
        assert_eq!(companion.options.similarity.as_deref(), Some("dot_product"));
        assert!(
            fields.iter().all(|field| field.name != "ports_vector"),
            "ordinary fields and numeric arrays must not acquire vector mappings"
        );
    }

    #[test]
    fn custom_target_is_registered_without_overwriting_an_explicit_companion() {
        let fields = es_properties_to_fields(&json!({
            "body": {
                "type": "semantic_text",
                "target_field": "model_output",
                "dimensions": 7,
                "similarity": "l2_norm"
            },
            "model_output": {
                "type": "dense_vector",
                "dims": 7,
                "similarity": "l2_norm"
            }
        }))
        .expect("valid mapping");

        assert_eq!(
            fields
                .iter()
                .filter(|field| field.name == "model_output")
                .count(),
            1,
            "the explicit target must not be replaced or duplicated"
        );
        let companion = fields
            .iter()
            .find(|field| field.name == "model_output")
            .unwrap();
        assert_eq!(companion.field_type, FieldType::Vector);
        assert_eq!(companion.options.dimensions, Some(7));
        assert_eq!(companion.options.similarity.as_deref(), Some("l2_norm"));
    }

    #[test]
    fn explicit_companion_collisions_report_actionable_mismatches() {
        let wrong_type = json!({
            "body": { "type": "semantic_text", "target_field": "model_output" },
            "model_output": { "type": "double" }
        });
        let error =
            validate_semantic_companion_targets(wrong_type.as_object().unwrap()).unwrap_err();
        assert!(error.contains("explicitly mapped as [double]"), "{error}");
        assert!(error.contains("map it as [dense_vector]"), "{error}");

        let wrong_dims = json!({
            "body": {
                "type": "semantic_text",
                "target_field": "model_output",
                "dimensions": 384
            },
            "model_output": { "type": "dense_vector", "dims": 768 }
        });
        let error =
            validate_semantic_companion_targets(wrong_dims.as_object().unwrap()).unwrap_err();
        assert!(error.contains("produces 384 dimensions"), "{error}");
        assert!(error.contains("declares 768"), "{error}");

        let wrong_similarity = json!({
            "body": {
                "type": "semantic_text",
                "target_field": "model_output",
                "similarity": "dot_product"
            },
            "model_output": {
                "type": "dense_vector",
                "dims": 384,
                "similarity": "cosine"
            }
        });
        let error =
            validate_semantic_companion_targets(wrong_similarity.as_object().unwrap()).unwrap_err();
        assert!(error.contains("uses similarity [dot_product]"), "{error}");
        assert!(error.contains("declares [cosine]"), "{error}");

        let nested = json!({
            "document": {
                "type": "object",
                "properties": {
                    "body": { "type": "semantic_text" }
                }
            }
        });
        let error = validate_semantic_companion_targets(nested.as_object().unwrap()).unwrap_err();
        assert!(
            error.contains("nested semantic_text field [document.body] is not supported"),
            "{error}"
        );

        let nested_target = json!({
            "body": {
                "type": "semantic_text",
                "target_field": "semantic.embedding",
                "dimensions": 32
            },
            "semantic": {
                "properties": {
                    "embedding": { "type": "dense_vector", "dims": 32 }
                }
            }
        });
        let error =
            validate_semantic_companion_targets(nested_target.as_object().unwrap()).unwrap_err();
        assert!(
            error.contains("must be declared as a literal top-level property key"),
            "{error}"
        );
    }

    #[test]
    fn multiple_semantic_fields_pin_only_declared_companions() {
        let fields = es_properties_to_fields(&json!({
            "body": { "type": "semantic_text", "dimensions": 8 },
            "summary": {
                "type": "semantic_text",
                "target_field": "summary_embedding",
                "dimensions": 16
            },
            "measurements": { "type": "object" }
        }))
        .expect("valid mapping");

        let vectors: Vec<_> = fields
            .iter()
            .filter(|field| field.field_type == FieldType::Vector)
            .map(|field| (field.name.as_str(), field.options.dimensions))
            .collect();
        assert_eq!(
            vectors,
            vec![("body_vector", Some(8)), ("summary_embedding", Some(16))]
        );
    }
}

#[cfg(test)]
mod semantic_companion_hnsw_api_tests {
    use super::*;
    use axum::{
        body::{to_bytes, Body},
        http::{Request, StatusCode},
    };
    use tower::ServiceExt;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    async fn request_json(
        state: AppState,
        method: &str,
        path: &str,
        content_type: Option<&str>,
        body: impl Into<Body>,
    ) -> (StatusCode, Value) {
        let mut builder = Request::builder().method(method).uri(path);
        if let Some(content_type) = content_type {
            builder = builder.header("content-type", content_type);
        }
        let response = crate::router::build_es_compat_router(state)
            .oneshot(builder.body(body.into()).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let bytes = to_bytes(response.into_body(), usize::MAX).await.unwrap();
        let json = serde_json::from_slice(&bytes).unwrap_or_else(|error| {
            panic!(
                "{method} {path} returned non-JSON ({error}): {}",
                String::from_utf8_lossy(&bytes)
            )
        });
        (status, json)
    }

    fn state(config: &Config) -> AppState {
        let engine = Engine::new(config.clone()).unwrap();
        let metrics = Metrics::new().unwrap();
        AppState::new(config.clone(), engine, metrics)
    }

    async fn assert_complete_semantic_graph(state: &AppState) {
        let index = state.engine.get_index("semantic-api").unwrap();
        let stats = index.hnsw_stats().await;
        assert_eq!(stats["present"], true, "{stats}");
        assert_eq!(stats["field"], "body_vector", "{stats}");
        assert_eq!(stats["nodes"], 1024, "{stats}");
        assert_eq!(stats["doc_coverage"], 1024, "{stats}");
        assert_eq!(stats["vector_doc_count"], 1024, "{stats}");
        assert_eq!(stats["covered"], true, "{stats}");
    }

    #[tokio::test]
    async fn api_semantic_bulk_builds_complete_hnsw_and_survives_restart() {
        let data_dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = data_dir.path().to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;

        {
            let state = state(&config);
            let (status, _) = request_json(
                state.clone(),
                "PUT",
                "/semantic-api",
                Some("application/json"),
                json!({
                    "mappings": {
                        "properties": {
                            "body": { "type": "semantic_text", "dimensions": 32 },
                            "measurements": { "type": "object" }
                        }
                    }
                })
                .to_string(),
            )
            .await;
            assert_eq!(status, StatusCode::OK);

            // Public mapping round-trips exactly what the caller declared:
            // the engine-only companion is not exposed as another field.
            let (status, mapping) =
                request_json(state.clone(), "GET", "/semantic-api/_mapping", None, "").await;
            assert_eq!(status, StatusCode::OK);
            let properties = mapping["semantic-api"]["mappings"]["properties"]
                .as_object()
                .unwrap();
            assert_eq!(properties.len(), 2, "{mapping}");
            assert!(!properties.contains_key("body_vector"), "{mapping}");

            let mut bulk = String::new();
            for id in 0..1024 {
                bulk.push_str(&format!(
                    "{{\"index\":{{\"_index\":\"semantic-api\",\"_id\":\"{id}\"}}}}\n"
                ));
                bulk.push_str(&format!(
                    "{{\"body\":\"quarterly finance report revenue item {id}\",\
                     \"measurements\":[{id},{}]}}\n",
                    id + 1
                ));
            }
            let (status, response) = request_json(
                state.clone(),
