pub fn schema_to_es_properties(schema: &Schema) -> serde_json::Map<String, Value> {
    let mut props = serde_json::Map::new();
    for field in &schema.fields {
        // #889 — `date` and `date_nanos` both live as `FieldType::Date`, so
        // rendering the native type alone reported every `date_nanos` field as
        // a plain `date`. A client that reads a mapping and writes it back
        // (the GET → PUT round trip Kibana and every reindex helper performs)
        // then silently downgraded the field to millisecond resolution. Now
        // that the declared precision is recorded, report it.
        let es_type = match (&field.field_type, field.options.date_precision) {
            (FieldType::Date, Some(xerj_common::types::DatePrecision::Nanos)) => "date_nanos",
            (ft, _) => native_type_to_es(ft),
        };
        let mut field_obj = serde_json::Map::new();
        field_obj.insert("type".to_string(), Value::String(es_type.to_string()));
        if let Some(n) = field.options.ignore_above {
            field_obj.insert("ignore_above".to_string(), Value::Number(n.into()));
        }
        if !field.fields.is_empty() {
            let sub_schema = Schema {
                fields: field.fields.clone(),
                version: 0,
                updated_at: Utc::now(),
            };
            let sub_props = schema_to_es_properties(&sub_schema);
            // Children of an object-like parent are real sub-properties;
            // children of a LEAF parent are multi-fields (e.g. the
            // auto-created `keyword` sub-field on a dynamically mapped
            // string, #209) and ES renders those under `fields`, not
            // `properties` — `_field_caps` also discovers `<f>.keyword`
            // from exactly this `fields` shape (`collect_multi_fields`).
            let key = match field.field_type {
                FieldType::Object | FieldType::Nested => "properties",
                _ => "fields",
            };
            field_obj.insert(key.to_string(), Value::Object(sub_props));
        }
        props.insert(field.name.clone(), Value::Object(field_obj));
    }
    props
}

fn native_type_to_es(ft: &FieldType) -> &'static str {
    match ft {
        FieldType::Text => "text",
        FieldType::Keyword => "keyword",
        FieldType::Long => "long",
        FieldType::Double => "double",
        FieldType::Boolean => "boolean",
        FieldType::Date => "date",
        FieldType::Ip => "ip",
        FieldType::Vector => "dense_vector",
        FieldType::Chunk => "dense_vector",
        FieldType::GeoPoint => "geo_point",
        FieldType::Binary => "binary",
        FieldType::Object => "object",
        FieldType::Nested => "nested",
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Date math in index names
// ─────────────────────────────────────────────────────────────────────────────

/// Resolve date math expressions in an index name.
///
/// ES syntax: `<log-{now/d}>` → `log-2026.04.11`
///
/// Supported expressions:
/// - `now`       → current date-time
/// - `now/d`     → today (rounded to day)
/// - `now-1d/d`  → yesterday rounded to day
/// - `now+1d/d`  → tomorrow rounded to day
/// - `now-Nd`    → N days ago (no rounding)
/// - `now+Nd`    → N days from now (no rounding)
///
/// The optional format suffix (e.g. `{now/d{yyyy.MM.dd}}`) can specify the
/// strftime-like format; without it we default to `yyyy.MM.dd`.
pub fn resolve_date_math_index(name: &str) -> String {
    // Look for `<...>` wrapper.
    if let (Some(start), Some(end)) = (name.find('<'), name.rfind('>')) {
        if start < end {
            let inner = &name[start + 1..end];
            let resolved = resolve_date_math_expr(inner);
            // Replace the <...> portion; keep anything outside.
            let mut result = name[..start].to_string();
            result.push_str(&resolved);
            result.push_str(&name[end + 1..]);
            return result;
        }
    }
    name.to_string()
}

/// Resolve a single date math expression (without the `<` `>` brackets).
///
/// Format: `static-prefix-{expr}` or `static-prefix-{expr{format}}`.
fn resolve_date_math_expr(expr: &str) -> String {
    // Find the `{` and `}` delimiters for the date part.
    let brace_start = match expr.find('{') {
        Some(i) => i,
        None => return expr.to_string(),
    };
    let brace_end = match expr.rfind('}') {
        // The closing brace must come AFTER the opening one, or the slice below
        // is `expr[4..0]` — a panic, not an empty string. `<}<}<>{>{}>` is
        // enough, and `panic = "abort"` makes it the process rather than a 400
        // (#207). Braces in the wrong order are not date math, so the name
        // passes through. Second copy of the same defect in
        // `xerj-engine::index::resolve_date_math_inner`.
        Some(i) if i > brace_start => i,
        _ => return expr.to_string(),
    };

    let prefix = &expr[..brace_start];
    let date_part = &expr[brace_start + 1..brace_end];

    // Split on an inner `{` for optional format: `now/d{yyyy.MM.dd}`.
    let (math_expr, fmt) = if let Some(inner_brace) = date_part.find('{') {
        // Same ordering requirement as the outer pair, for the same reason.
        let inner_end = date_part
            .rfind('}')
            .filter(|end| *end > inner_brace)
            .unwrap_or(date_part.len());
        (
            &date_part[..inner_brace],
            &date_part[inner_brace + 1..inner_end],
        )
    } else {
        (date_part, "yyyy.MM.dd")
    };

    // Parse the math expression. ES accepts two forms:
    //   `now[<op><N><unit>][/<unit>]`         — relative to current UTC
    //   `<iso-date>||<op><N><unit>[/<unit>]`  — relative to the anchored date
    // The anchor is everything before `||`; it may stand alone (no math).
    let anchor_end = math_expr.find("||");
    let (anchor_str, tail) = match anchor_end {
        Some(i) => (&math_expr[..i], &math_expr[i + 2..]),
        None => ("", math_expr),
    };
    let base = if anchor_str.is_empty() {
        chrono::Utc::now()
    } else {
        // Accept `yyyy-MM-dd`, `yyyy-MM-ddTHH:mm:ss`, and full RFC3339.
        if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(anchor_str) {
            dt.with_timezone(&chrono::Utc)
        } else if let Ok(ndt) =
            chrono::NaiveDateTime::parse_from_str(anchor_str, "%Y-%m-%dT%H:%M:%S")
        {
            ndt.and_utc()
        } else if let Ok(nd) = chrono::NaiveDate::parse_from_str(anchor_str, "%Y-%m-%d") {
            nd.and_hms_opt(0, 0, 0)
                .map(|ndt| ndt.and_utc())
                .unwrap_or_else(chrono::Utc::now)
        } else {
            chrono::Utc::now()
        }
    };
    // For anchored expressions, the tail is pure math (`/d`, `-1d`, etc.)
    // without a `now` prefix — apply it directly.
    let date = if anchor_str.is_empty() {
        resolve_now_expr(tail, base)
    } else {
        apply_date_math_tail(tail, base)
    };
    let formatted = format_date(date, fmt);

    format!("{}{}", prefix, formatted)
}

/// Apply the math portion of an anchored expression (everything after `||`).
/// Handles `-1d`, `+2h`, `/d`, and empty tail.
///
/// Third copy of the date-math defect the `date_math` fuzz target found in
/// `xerj_query::dates::add_unit` (#207), and the one the first pass at that
/// issue missed: this is the *anchored* branch of the index-name resolver
/// (`<logs-{2026-01-01||+1d}>`), sixty lines above the `now` branch that was
/// patched. Everything below is reached from a request URI through the public
/// `resolve_date_math_index` — the index path parameter of every create/index
/// call and the `_search` index list — and the release profile sets
/// `panic = "abort"`, so each of these was an unauthenticated process kill:
///
/// * `+9999999999999d`  → `TimeDelta::days out of bounds`
/// * `+99999999999h`    → `DateTime + TimeDelta overflowed`
/// * `+9223372036854775807M` → `n * 30` overflows before `Duration` is asked
/// * `+1中` / `/中`     → `byte index 1 is not a char boundary`
///
/// The fixes are the same three the `now` branch got: read the unit as one
/// CHARACTER, build the offset with the fallible `try_*` constructors and
/// `checked_mul`, and add it with `checked_add_signed`. An unrepresentable
/// offset degrades to "no offset", which is what this resolver already does
/// with an unrecognised unit — it has no error channel to report into.
fn apply_date_math_tail(
    tail: &str,
    base: chrono::DateTime<chrono::Utc>,
) -> chrono::DateTime<chrono::Utc> {
    use chrono::Duration;
    let mut dt = base;
    let mut rest = tail;
    while !rest.is_empty() {
        if let Some(r) = rest.strip_prefix('+').or_else(|| rest.strip_prefix('-')) {
            let sign = if rest.starts_with('+') { 1i64 } else { -1i64 };
            let (num_str, r2) =
                r.split_at(r.find(|c: char| !c.is_ascii_digit()).unwrap_or(r.len()));
            let n: i64 = num_str.parse().unwrap_or(0) * sign;
            // One character, not one byte: the digit scan stops at the first
            // non-digit, which may be multi-byte, and `r2[..1]` would split it.
            let (unit, r3) = match r2.chars().next() {
                Some(c) => r2.split_at(c.len_utf8()),
                None => ("", r2),
            };
            let offset = match unit {
                "d" => Duration::try_days(n),
                "h" => Duration::try_hours(n),
                "m" => Duration::try_minutes(n),
                "s" => Duration::try_seconds(n),
                "w" => Duration::try_weeks(n),
                "M" => n.checked_mul(30).and_then(Duration::try_days),
                "y" => n.checked_mul(365).and_then(Duration::try_days),
                _ => Some(Duration::zero()),
            }
            .unwrap_or_else(Duration::zero);
            dt = dt.checked_add_signed(offset).unwrap_or(dt);
            rest = r3;
        } else if let Some(r) = rest.strip_prefix('/') {
            // Same one-character read as above: `/中` panicked on `r[..1]`.
            let (unit, r2) = match r.chars().next() {
                Some(c) => r.split_at(c.len_utf8()),
                None => ("", r),
            };
            dt = round_date_down(dt, unit);
            rest = r2;
        } else {
            break;
        }
    }
    dt
}

fn round_date_down(dt: chrono::DateTime<chrono::Utc>, unit: &str) -> chrono::DateTime<chrono::Utc> {
    use chrono::{Datelike, TimeZone, Timelike};
    match unit {
        "d" => chrono::Utc
            .with_ymd_and_hms(dt.year(), dt.month(), dt.day(), 0, 0, 0)
            .single()
            .unwrap_or(dt),
        "h" => chrono::Utc
            .with_ymd_and_hms(dt.year(), dt.month(), dt.day(), dt.hour(), 0, 0)
            .single()
            .unwrap_or(dt),
        "m" => chrono::Utc
            .with_ymd_and_hms(dt.year(), dt.month(), dt.day(), dt.hour(), dt.minute(), 0)
            .single()
            .unwrap_or(dt),
        "M" => chrono::Utc
            .with_ymd_and_hms(dt.year(), dt.month(), 1, 0, 0, 0)
            .single()
            .unwrap_or(dt),
        "y" => chrono::Utc
            .with_ymd_and_hms(dt.year(), 1, 1, 0, 0, 0)
            .single()
            .unwrap_or(dt),
        _ => dt,
    }
}

/// Parse and evaluate a `now`-based date math expression.
fn resolve_now_expr(
    expr: &str,
    base: chrono::DateTime<chrono::Utc>,
) -> chrono::DateTime<chrono::Utc> {
    use chrono::Duration;

    // Strip leading "now".
    let rest = match expr.strip_prefix("now") {
        Some(r) => r,
        None => return base,
    };

    // Parse optional offset: `-1d`, `+2d`, `-7d`, etc.
    let (mut dt, rest) = if rest.starts_with('+') || rest.starts_with('-') {
        let sign = if rest.starts_with('+') { 1i64 } else { -1i64 };
        let rest = &rest[1..];
        // Parse number.
        let (num_str, rest) = rest.split_at(
            rest.find(|c: char| !c.is_ascii_digit())
                .unwrap_or(rest.len()),
        );
        let n: i64 = num_str.parse().unwrap_or(0) * sign;
        // Parse unit — one CHARACTER, not one byte. The digit scan stops at
        // the first non-digit, which may be multi-byte, and `rest[..1]` would
        // then split it in half and panic. `panic = "abort"` makes that the
        // process, from an index name in a request URI. Second copy of what the
        // `index_name_date_math` fuzz target found in `index.rs` (#207).
        let (unit, rest) = match rest.chars().next() {
            Some(c) => rest.split_at(c.len_utf8()),
            None => ("", rest),
        };
        // `Duration::days` and friends PANIC on a count that does not fit a
        // `TimeDelta`, and `n * 30` overflows first. `expr` is the date math
        // inside an index name (`<logs-{now-9999999999999d}>`) taken from a
        // request URI, so a panic here is an unauthenticated crash. Third copy
        // of the defect the `date_math` fuzz target found in
        // `xerj_query::dates::add_unit`.
        //
        // An unrepresentable offset degrades to "no offset" — the same thing
        // this resolver already does with an unrecognised unit, and it has no
        // error channel to report into.
        let offset = match unit {
            "d" => Duration::try_days(n),
            "h" => Duration::try_hours(n),
            "m" => Duration::try_minutes(n),
            "s" => Duration::try_seconds(n),
            "w" => Duration::try_weeks(n),
            "M" => n.checked_mul(30).and_then(Duration::try_days),
            "y" => n.checked_mul(365).and_then(Duration::try_days),
            _ => Some(Duration::zero()),
        }
        .unwrap_or_else(Duration::zero);
        (base.checked_add_signed(offset).unwrap_or(base), rest)
    } else {
        (base, rest)
    };

    // Parse optional rounding: `/d`, `/h`, `/m`, `/y`, `/M`.
    if let Some(round_rest) = rest.strip_prefix('/') {
        let unit = round_rest.chars().next().unwrap_or('d');
        dt = match unit {
            'd' => {
                // Round down to day.
                chrono::Utc
                    .with_ymd_and_hms(dt.year(), dt.month(), dt.day(), 0, 0, 0)
                    .single()
                    .unwrap_or(dt)
            }
            'h' => chrono::Utc
                .with_ymd_and_hms(dt.year(), dt.month(), dt.day(), dt.hour(), 0, 0)
                .single()
                .unwrap_or(dt),
            'M' => chrono::Utc
                .with_ymd_and_hms(dt.year(), dt.month(), 1, 0, 0, 0)
                .single()
                .unwrap_or(dt),
            'y' => chrono::Utc
                .with_ymd_and_hms(dt.year(), 1, 1, 0, 0, 0)
                .single()
                .unwrap_or(dt),
            _ => dt,
        };
    }

    dt
}

/// Format a datetime using ES-style format strings (subset).
///
/// Supports: `yyyy`, `MM`, `dd`, `HH`, `mm`, `ss`, and literal separators.
fn format_date(dt: chrono::DateTime<chrono::Utc>, fmt: &str) -> String {
    // Simple substitution-based formatter.
    let mut result = fmt.to_string();
    result = result.replace("yyyy", &format!("{:04}", dt.year()));
    result = result.replace("MM", &format!("{:02}", dt.month()));
    result = result.replace("dd", &format!("{:02}", dt.day()));
    result = result.replace("HH", &format!("{:02}", dt.hour()));
    result = result.replace("mm", &format!("{:02}", dt.minute()));
    result = result.replace("ss", &format!("{:02}", dt.second()));
    result
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_update/{id}
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Serialize, Deserialize)]
pub struct EsUpdateBody {
    /// Partial document fields to merge into existing source.
    pub doc: Option<Value>,
    /// When true, use `doc` as the creation body if the document does not exist.
    #[serde(default)]
    pub doc_as_upsert: bool,
    /// Creation body used when the document does not exist (and `doc_as_upsert` is false).
    pub upsert: Option<Value>,
    /// Painless script that mutates `ctx._source` in place. Accepted as the
    /// short string form (`"ctx._source.x = 1"`) or the object form
    /// (`{ "source": "...", "lang": "painless", "params": { ... } }`).
    pub script: Option<Value>,
    /// When true (default), an update that produces no source change reports
    /// `result: "noop"`. Currently informational — writes are always applied.
    #[serde(default)]
    pub detect_noop: Option<bool>,
}

/// Query parameters for the `_update` endpoint.
#[derive(Debug, Default, Serialize, Deserialize)]
pub struct UpdateDocParams {
    /// `refresh=true|wait_for` — accepted without error; memtable is always visible.
    pub refresh: Option<String>,
    /// `_source=false` suppresses the `get` block; any other value (or bare
    /// presence) requests it. Absent + no includes/excludes → no `get` block,
    /// matching real ES (source is NOT returned by default on `_update`).
    #[serde(rename = "_source")]
    pub source: Option<String>,
    /// Comma-separated fields to include in the `get._source` block.
    #[serde(rename = "_source_includes")]
    pub source_includes: Option<String>,
    /// Comma-separated fields to exclude from the `get._source` block.
    #[serde(rename = "_source_excludes")]
    pub source_excludes: Option<String>,
}

/// Whether `_update`'s response should carry a `get` block, per the same
/// `_source`/`_source_includes`/`_source_excludes` semantics `GET _doc` uses.
/// Real ES clients (e.g. Kibana's SavedObjectsRepository, which reads
/// `body.get._source` unconditionally after every update) rely on this.
fn update_wants_get(params: &UpdateDocParams) -> bool {
    match params.source.as_deref() {
        Some("false") => false,
        Some(_) => true,
        None => params.source_includes.is_some() || params.source_excludes.is_some(),
    }
}

/// Build the `get` block for an `_update` response by re-fetching the
/// now-current document and applying the same includes/excludes filtering
/// `GET _doc` uses.
async fn build_update_get_field(
    idx: &std::sync::Arc<xerj_engine::index::Index>,
    id: &str,
    params: &UpdateDocParams,
) -> Value {
    let source = idx.get_document(id).await.ok().flatten();
    match source {
        Some(source) => {
            let includes: Vec<String> = params
                .source_includes
                .as_deref()
                .map(|s| s.split(',').map(str::trim).map(String::from).collect())
                .unwrap_or_default();
            let excludes: Vec<String> = params
                .source_excludes
                .as_deref()
                .map(|s| s.split(',').map(str::trim).map(String::from).collect())
                .unwrap_or_default();
            let filtered = if includes.is_empty() && excludes.is_empty() {
                source
            } else {
                xerj_engine::filter_object(&source, &includes, &excludes)
            };
            json!({ "found": true, "_source": filtered })
        }
        None => json!({ "found": false }),
    }
}

/// Parse an `_update` body from raw bytes.
///
/// The size check runs before `serde_json`. The route used to take
/// `Json<EsUpdateBody>`, so axum built the DOM before the handler. A body
/// between this envelope and `limits.max_body_bytes` (100 MiB) was parsed
/// even when it could not be applied, and that parse is an infallible
/// allocation (`panic = "abort"`, #1122). Bytes that are not JSON and are
/// also over the limit report the size refusal, not a parse error.
pub(crate) fn parse_update_body(body: &[u8]) -> Result<EsUpdateBody, xerj_common::XerjError> {
    if xerj_common::document_limit::update_body_too_large(body.len()) {
        let len = body.len();
        tracing::warn!(
            bytes = len,
            limit = xerj_common::document_limit::MAX_UPDATE_BODY_BYTES,
            "update body refused before parse; the existing document was not changed (#1122)"
        );
        return Err(xerj_common::XerjError::invalid_document_json(
            xerj_common::document_limit::update_body_refusal(len),
        ));
    }
    serde_json::from_slice(body).map_err(|e| {
        xerj_common::XerjError::invalid_document_json(format!("invalid JSON body: {e}"))
    })
}

pub(crate) struct LocalUpdate {
    pub response: axum::response::Response,
    /// The primary stored a new source. A cluster caller copies it. A noop,
    /// a miss, and every error leave this false.
    pub replicate: bool,
}

pub async fn update_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
    Query(query_params): Query<UpdateDocParams>,
    body: bytes::Bytes,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    // Before `get_or_create_index`, so a refused body does not create an
    // index and does not read or write the document.
    let body = match parse_update_body(&body) {
        Ok(body) => body,
        Err(e) => return ApiError::new(e).into_response(),
    };
    if state.engine.has_cluster() {
        match crate::cluster_shard::dispatch_update(&state, &index, &id, &body, &query_params).await
        {
            crate::cluster_shard::Dispatch::Done(response) => return response,
            crate::cluster_shard::Dispatch::Local => {}
        }
    }
    apply_local_update(&state, &index, &id, body, &query_params)
        .await
        .response
}

pub(crate) async fn apply_local_update(
    state: &AppState,
    index: &str,
    id: &str,
    body: EsUpdateBody,
    query_params: &UpdateDocParams,
) -> LocalUpdate {
    fn settled(response: impl IntoResponse, replicate: bool) -> LocalUpdate {
        LocalUpdate {
            response: response.into_response(),
            replicate,
        }
    }
    let idx = match state.engine.get_or_create_index(index) {
        Ok(i) => i,
        Err(e) => {
            return settled(ApiError::new(xerj_common::XerjError::from(e)), false);
        }
    };

    // ── Scripted update path ────────────────────────────────────────────────
    // When the body carries a `script`, load the current document, evaluate
    // the painless script against `ctx._source`, and re-index the mutated
    // source under the SAME id (an in-place update, not an append).
    if let Some(script_val) = body.script.as_ref() {
        let (src, params) = extract_update_script(script_val);
        if src.is_empty() {
            return settled(
                update_script_bad_request("script source is required".to_string()),
                false,
            );
        }
        let upsert_body = body.upsert.clone().or_else(|| {
            if body.doc_as_upsert {
                body.doc.clone()
            } else {
                None
            }
        });
        // Same budget as `_update_by_query`: without a deadline in scope every
        // statement in the script gets its own fresh slice, so a single
        // document is still an unbounded amount of work.
        let deadline = Instant::now() + Duration::from_millis(SCRIPTED_UPDATE_BUDGET_MS);
        let (transformed, fault) = xerj_engine::painless::with_script_fault_capture(
            xerj_engine::painless::with_script_deadline(
                deadline,
                idx.transform_document_serialized(id, upsert_body, move |mut current| {
                    apply_painless_update(&mut current, &src, &params)?;
                    Ok::<_, String>(current)
                }),
            ),
        )
        .await;
        if let Some(reason) = fault {
            return settled(script_limit_response(&reason), false);
        }
        match transformed {
            Ok(Ok(Some(outcome))) => {
                state.metrics.record_doc_indexed(index);
                let resp = outcome.response;
                let mut er = if outcome.created {
                    crate::responses::EsDocResponse::created(
                        index,
                        &resp.id,
                        resp.version,
                        resp.seq_no.saturating_sub(1),
                    )
                } else {
                    crate::responses::EsDocResponse::updated(
                        index,
                        &resp.id,
                        resp.version,
                        resp.seq_no.saturating_sub(1),
                    )
                };
                if update_wants_get(query_params) {
                    er.get = Some(build_update_get_field(&idx, &resp.id, query_params).await);
                }
                return settled(Json(er), true);
            }
            Ok(Ok(None)) => {
                let e = xerj_common::XerjError::document_not_found(id, index);
                return settled(ApiError::new(e), false);
            }
            Ok(Err(error)) => return settled(update_script_bad_request(error), false),
            Err(error) => {
                return settled(ApiError::new(xerj_common::XerjError::from(error)), false);
            }
        }
    }

    match idx
        .update_document_with_upsert(id, body.doc, body.upsert, body.doc_as_upsert)
        .await
    {
        Ok(Some(resp)) => {
            let replicate = resp.result != "noop";
            state.metrics.record_doc_indexed(index);
            let mut er = crate::responses::EsDocResponse::updated(
                index,
                &resp.id,
                resp.version,
                resp.seq_no.saturating_sub(1),
            );
            if update_wants_get(query_params) {
                er.get = Some(build_update_get_field(&idx, &resp.id, query_params).await);
            }
            settled(Json(er), replicate)
        }
        Ok(None) => {
            let e = xerj_common::XerjError::document_not_found(id, index);
            settled(ApiError::new(e), false)
        }
        Err(e) => settled(ApiError::new(xerj_common::XerjError::from(e)), false),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Scripted-update helpers (shared by `_update` and `_update_by_query`)
// ─────────────────────────────────────────────────────────────────────────────

/// ES-shaped 400 for a malformed / unsupported update script.
fn update_script_bad_request(reason: String) -> axum::response::Response {
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "script_exception", "reason": reason.clone() }],
                "type": "script_exception",
                "reason": reason,
            },
            "status": 400,
        })),
    )
        .into_response()
}

/// Pull the `(source, params)` out of an ES `script` value. Accepts the short
/// string form and the object form `{ source, lang, params }`.
fn extract_update_script(script: &Value) -> (String, Value) {
    match script {
        Value::String(s) => (s.trim().to_string(), json!({})),
        Value::Object(_) => {
            let src = script
                .get("source")
                .or_else(|| script.get("inline"))
                .and_then(Value::as_str)
                .unwrap_or("")
                .trim()
                .to_string();
            let params = script.get("params").cloned().unwrap_or_else(|| json!({}));
            (src, params)
        }
        _ => (String::new(), json!({})),
    }
}

/// Consume a `ctx._source` accessor path (`.a.b`, `['a']["b"]`) from the start
/// of `rest`, returning the parsed path segments and the number of bytes
/// consumed. Stops at the first byte that is not part of the path.
fn consume_source_path(rest: &str) -> (Vec<String>, usize) {
    let mut path: Vec<String> = Vec::new();
    let b = rest.as_bytes();
    let mut i = 0;
    loop {
        if i < b.len() && b[i] == b'.' {
            let start = i + 1;
            let mut k = start;
            while k < b.len() && (b[k].is_ascii_alphanumeric() || b[k] == b'_') {
                k += 1;
            }
            if k == start {
                break;
            }
            path.push(rest[start..k].to_string());
            i = k;
        } else if i < b.len() && b[i] == b'[' {
            if let Some(rel) = rest[i..].find(']') {
                let close = i + rel;
                let inner = rest[i + 1..close]
                    .trim()
                    .trim_matches(|c| c == '\'' || c == '"');
                path.push(inner.to_string());
                i = close + 1;
            } else {
                break;
            }
        } else {
            break;
        }
    }
    (path, i)
}

/// Rewrite `ctx._source.<path>` / `ctx._source['<path>']` references inside an
/// expression into the `doc['<path>'].value` form understood by the painless
/// evaluator, so the right-hand side of an update assignment can read the
/// document's current source.
fn rewrite_source_refs(s: &str) -> String {
    const PREFIX: &str = "ctx._source";
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    while i < s.len() {
        if s[i..].starts_with(PREFIX) {
            let after = &s[i + PREFIX.len()..];
            let (path, consumed) = consume_source_path(after);
            if !path.is_empty() {
                out.push_str(&format!("doc['{}'].value", path.join(".")));
                i += PREFIX.len() + consumed;
                continue;
            }
        }
        let ch = s[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    out
}

/// `doc['a.b'].value` form for a parsed source path (used to desugar compound
/// assignment operators).
fn source_path_as_doc_ref(path: &[String]) -> String {
    format!("doc['{}'].value", path.join("."))
}

fn get_source_path(source: &Value, path: &[String]) -> Value {
    let mut cur = source;
    for p in path {
        match cur.get(p) {
            Some(v) => cur = v,
            None => return Value::Null,
        }
    }
    cur.clone()
}

fn set_source_path(source: &mut Value, path: &[String], value: Value) {
    if path.is_empty() {
        return;
    }
    if !source.is_object() {
        *source = json!({});
    }
    let obj = source.as_object_mut().expect("ensured object above");
    if path.len() == 1 {
        obj.insert(path[0].clone(), value);
    } else {
        let child = obj.entry(path[0].clone()).or_insert_with(|| json!({}));
        set_source_path(child, &path[1..], value);
    }
}

/// Integer-preserving conversion of a painless result into JSON (whole numbers
/// stay integers so `ctx._source.x = 42` stores `42`, not `42.0`).
fn painless_update_value(v: xerj_engine::painless::PainlessValue) -> Value {
    use xerj_engine::painless::PainlessValue as P;
    match v {
        P::Number(n) if n.is_finite() && n.fract() == 0.0 && n.abs() < 9.007_199_254_740_992e15 => {
            Value::Number((n as i64).into())
        }
        other => painless_to_json(other),
    }
}

/// Parse a self-contained RHS literal (number / string / bool / null / array /
/// object) so its JSON type is preserved exactly. Returns `None` when the RHS
/// is an expression that must be evaluated.
fn parse_rhs_literal(rhs: &str) -> Option<Value> {
    let t = rhs.trim();
    if t.len() >= 2 && t.starts_with('\'') && t.ends_with('\'') && !t[1..t.len() - 1].contains('\'')
    {
        return Some(Value::String(t[1..t.len() - 1].to_string()));
    }
    serde_json::from_str::<Value>(t).ok()
}

/// Evaluate an expression against the document's current source using the same
/// painless evaluator that backs `/_scripts/painless/_execute`.
fn eval_update_expr(expr: &str, source: &Value, params: &Value) -> Result<Value, String> {
    let ctx = xerj_engine::painless::PainlessCtx::new(source, params, 0.0);
    let pv = xerj_engine::painless::eval_painless(expr, &ctx)?;
    Ok(painless_update_value(pv))
}

/// Apply a painless update script to `source` in place. Supports the common
/// `ctx._source.*` mutation forms: assignment (`=`), compound assignment
/// (`+= -= *= /=`), increment / decrement (`++ --`), and `remove(...)`.
fn apply_painless_update(
    source: &mut Value,
    script_src: &str,
    params: &Value,
) -> Result<(), String> {
    for raw in split_update_statements(script_src) {
        let stmt = raw.trim();
        if stmt.is_empty() {
            continue;
        }
        apply_one_update_stmt(source, stmt, params)?;
    }
    Ok(())
}

/// Split a script into top-level statements on `;`, ignoring separators inside
/// single- or double-quoted string literals.
fn split_update_statements(src: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut quote: Option<char> = None;
    for ch in src.chars() {
        match quote {
            Some(q) => {
                cur.push(ch);
                if ch == q {
                    quote = None;
                }
            }
            None => {
                if ch == '\'' || ch == '"' {
                    quote = Some(ch);
                    cur.push(ch);
                } else if ch == ';' {
                    out.push(std::mem::take(&mut cur));
                } else {
                    cur.push(ch);
                }
            }
        }
    }
    if !cur.trim().is_empty() {
        out.push(cur);
    }
    out
}

fn apply_one_update_stmt(source: &mut Value, stmt: &str, params: &Value) -> Result<(), String> {
    let s = stmt.trim();
    let Some(rest) = s.strip_prefix("ctx._source") else {
        // Tolerate other `ctx.*` statements (e.g. `ctx.op = 'noop'`) as no-ops;
        // reject anything we genuinely don't understand so it surfaces as 400.
        if s.starts_with("ctx.") || s.starts_with("ctx[") {
            return Ok(());
        }
        return Err(format!("unsupported update script statement: {s}"));
    };

    // ctx._source.remove('field') / ctx._source.remove("field")
    if let Some(after) = rest.strip_prefix(".remove") {
        let after = after.trim_start();
        if let Some(inner) = after.strip_prefix('(') {
            let key = inner
                .trim_end_matches(')')
                .trim()
                .trim_matches(|c| c == '\'' || c == '"');
            if let Some(obj) = source.as_object_mut() {
                obj.remove(key);
            }
            return Ok(());
        }
    }

    let (path, consumed) = consume_source_path(rest);
    if path.is_empty() {
        return Err(format!("invalid update script target: {s}"));
    }
    let opr = rest[consumed..].trim_start();

    // Increment / decrement.
    if opr == "++" || opr == "--" {
        let cur = get_source_path(source, &path).as_f64().unwrap_or(0.0);
        let nv = if opr == "++" { cur + 1.0 } else { cur - 1.0 };
        set_source_path(
            source,
            &path,
            painless_update_value(xerj_engine::painless::PainlessValue::Number(nv)),
        );
        return Ok(());
    }

    // Assignment (plain or compound).
    let (compound, rhs) = if let Some(r) = opr.strip_prefix("+=") {
        (Some('+'), r)
    } else if let Some(r) = opr.strip_prefix("-=") {
        (Some('-'), r)
    } else if let Some(r) = opr.strip_prefix("*=") {
        (Some('*'), r)
    } else if let Some(r) = opr.strip_prefix("/=") {
        (Some('/'), r)
    } else if let Some(r) = opr.strip_prefix('=') {
        (None, r)
    } else {
        return Err(format!("unsupported update script statement: {s}"));
    };
    let rhs = rhs.trim();

    let new_value = match compound {
        Some(op) => {
            let expr = format!(
                "({}) {} ({})",
                source_path_as_doc_ref(&path),
                op,
                rewrite_source_refs(rhs)
            );
            eval_update_expr(&expr, source, params)?
        }
        None => match parse_rhs_literal(rhs) {
            Some(v) => v,
            None => eval_update_expr(&rewrite_source_refs(rhs), source, params)?,
        },
    };
    set_source_path(source, &path, new_value);
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_refresh
// ─────────────────────────────────────────────────────────────────────────────

/// One `_shards.failures` entry for `_refresh`, in selector order. The first
/// failure's HTTP status becomes the response status (ES
/// `BaseBroadcastResponse::getStatus`).
fn record_refresh_failure(
    failures: &mut Vec<Value>,
    response_status: &mut StatusCode,
    name: &str,
    rendered: Value,
) {
    let status = rendered
        .get("status")
        .and_then(Value::as_u64)
        .and_then(|code| StatusCode::from_u16(code as u16).ok())
        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    if failures.is_empty() {
        *response_status = status;
    }
    let reason = rendered
        .pointer("/error/root_cause/0")
        .or_else(|| rendered.pointer("/error"))
        .cloned()
        .unwrap_or_else(|| json!({ "type": "exception", "reason": "refresh failed" }));
    let status_name = status
        .canonical_reason()
        .unwrap_or("Internal Server Error")
        .to_ascii_uppercase()
        .replace([' ', '-'], "_");
    failures.push(json!({
        "shard": 0,
        "index": name,
        "status": status_name,
        "reason": reason,
    }));
}

pub async fn refresh_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => return ApiError::new(e).into_response(),
    };
    let total = handles.len() as u64;
    let mut successful = 0u64;
    let mut failures = Vec::new();
    let mut response_status = StatusCode::OK;
    // #2234: `_refresh` makes writes searchable. It is not `_flush`.
    // `Index::flush` also runs verified WAL maintenance (snapshot fsync and
    // prune). That work shares the disk with a background segment merge, and
    // this handler used to await it one index at a time — a wildcard refresh
    // sat behind the first busy index for the whole flush budget, which is
    // what stalled autoindex finalize. `Index::refresh` publishes an
    // unflushed memtable and returns immediately when that memtable is
    // already empty (#1635 still bounds a memtable that does have to be
    // published). The indices run together, so a healthy index is searchable
    // while a busy one is still inside its own budget. Results are collected
    // in selector order: the first failure still sets the HTTP status.
    let mut tasks = Vec::with_capacity(handles.len());
    for (name, idx) in handles {
        let task_name = name.clone();
        tasks.push((
            name,
            tokio::spawn(async move { (task_name, idx.refresh().await) }),
        ));
    }
    for (name, task) in tasks {
        let (name, result) = match task.await {
            Ok(pair) => pair,
            Err(error) => {
                let rendered = ApiError::new(xerj_common::XerjError::internal(format!(
                    "index [{name}] refresh task failed: {error}"
                )))
                .into_value();
                record_refresh_failure(&mut failures, &mut response_status, &name, rendered);
                continue;
            }
        };
        match result {
            Ok(()) => successful += 1,
            Err(error) => {
                let rendered = ApiError::new(xerj_common::XerjError::from(error)).into_value();
                record_refresh_failure(&mut failures, &mut response_status, &name, rendered);
            }
        }
    }
    let failed = failures.len() as u64;
    let mut body = json!({
        "_shards": { "total": total, "successful": successful, "failed": failed }
    });
    if failed > 0 {
        body["_shards"]["failures"] = Value::Array(failures);
    }

    // Refresh is a synchronous publication barrier. Tantivy's analogous
    // blocking commit contract returns its publication error to the caller
    // (`tantivy/src/indexer/index_writer.rs:651-666`, MIT); dropping it here
    // would turn "not published" into an affirmative success response.
    // Match the refresh-specific ES 8.13.4 wire contract, whose REST handler
    // uses `BaseBroadcastResponse::getStatus`: any failed shard makes the HTTP
    // response use the first shard's status, even if another shard succeeded
    // (`RestRefreshAction.java:47-52`, `BaseBroadcastResponse.java:114-122`;
    // semantics only, no ES code). The body still reports every attempted
    // shard (`RestActions.java:79-103`).
    (response_status, Json(body)).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}/_count
// ─────────────────────────────────────────────────────────────────────────────

/// One entry of `_count`'s `_shards.failures`, in ES's shape. `rendered` is the
/// `ApiError` body for the failure; the per-index entry carries the
/// *shard-level* exception (`query_shard_exception`) rather than the
/// `search_phase_execution_exception` wrapper the top-level error uses.
fn count_shard_failure(index: &str, rendered: &Value) -> Value {
    let reason = rendered
        .pointer("/error/root_cause/0")
        .or_else(|| rendered.pointer("/error"))
        .cloned()
        .unwrap_or_else(|| json!({ "type": "exception", "reason": "search failed" }));
    json!({ "shard": 0, "index": index, "reason": reason })
}

/// Locator of an autoindex file-card anchor. Must stay equal to
/// `xerj_autoindex::detect::FILE_CARD_LOCATOR` (`"file"`). The card is a real
/// document so graph edges can resolve it, and it is not a content record.
const FILE_CARD_LOCATOR: &str = "file";

/// `stats.doc_count` minus file-card anchors. A bare `_count` is what
/// `xerj autoindex map` and agents read as the record count; one card per
/// file was inflating it. An explicit query is left alone, so a caller who
/// asks for `ax_locator: file` still gets those documents, and a term query
/// that cannot run (the field is absent) leaves the stat count unchanged.
async fn content_doc_count(idx: &xerj_engine::index::Index) -> u64 {
    let total = idx.stats().await.doc_count;
    let body = json!({
        "query": {"term": {"ax_locator": FILE_CARD_LOCATOR}},
        "size": 0,
        "track_total_hits": true
    });
    let Ok(req) = xerj_query::parse_request(&body) else {
        return total;
    };
    match idx.search(&req).await {
        Ok(result) if result.script_failure.is_none() => total.saturating_sub(result.total.value),
        _ => total,
    }
}

pub async fn count_docs_global(
    State(state): State<AppState>,
    Query(params): Query<CountParams>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    // POST /_count — count across every index. Delegates to count_docs
    // with "_all" as the index selector.
    count_docs(State(state), Path("_all".to_string()), Query(params), body).await
}

#[derive(Debug, Default, Deserialize)]
pub struct CountParams {
    pub filter_path: Option<String>,
}

pub async fn count_docs(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<CountParams>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    // #193-style parity: ES's `_count` body accepts `min_score` and filters the
    // counted set by it. The handler rebuilds a `size: 0` search body from the
    // query alone, so this field used to be dropped and `_count` answered the
    // unfiltered total while `_search` with the same body answered 0. A
    // non-numeric value is the same 400 parse_exception `_search` gives.
    let min_score = match body.as_ref().and_then(|b| b.get("min_score")) {
        None | Some(Value::Null) => None,
        Some(value) => match value.as_f64() {
            Some(ms) => Some(ms),
            None => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "type": "parse_exception",
                            "reason": format!(
                                "malformed JSON in request body: invalid value for [min_score]: {value}"
                            ),
                            "status": 400,
                        }
                    })),
                )
                    .into_response();
            }
        },
    };
    // Multi-index / all selector: sum counts from every participating index.
    //
    // An ALIAS belongs in this branch too. It used not to, so a multi-index
    // alias fell through to the single-index path and answered one member's
    // count — three indices of 40 documents behind one alias reported 40, with
    // no error (#433). This is a THIRD copy of the same resolution, alongside
    // `resolve_index_selector` and the one inside `search_impl`; they disagreed
    // about aliases in different ways, which is why `_search` and `_count`
    // could give different answers for the same selector.
    let alias_selector = index
        .split(',')
        .map(str::trim)
        .any(|n| state.engine.aliases.contains_key(n));
    if index == "_all"
        || index == "*"
        || index.contains(',')
        || index.contains('*')
        || alias_selector
    {
        let wanted: Vec<String> = if index == "_all" || index == "*" {
            state.engine.index_name_list()
        } else {
            let mut all_names: Option<Vec<String>> = None;
            let mut out = Vec::new();
            for pat in index.split(',') {
                let pat = pat.trim();
                if pat.contains('*') {
                    let all_names = all_names.get_or_insert_with(|| state.engine.index_name_list());
                    for n in all_names.iter() {
                        if glob_match_simple(pat, n) && !out.contains(n) {
                            out.push(n.clone());
                        }
                    }
                } else if let Some(targets) = state.engine.aliases.get(pat) {
                    for n in targets.value() {
                        if !out.contains(n) {
                            out.push(n.clone());
                        }
                    }
                } else if !out.iter().any(|e| e == pat) {
                    out.push(pat.to_string());
                }
            }
            out
        };
        // Alias filters, collected from the selector AS WRITTEN. Expanding an
        // alias to its members and summing their raw document counts answers
        // the unfiltered corpus — for a filtered alias that is not a smaller
        // wrong answer than before, it is a LARGER one, and it made `_count`
        // disagree with `_search` in the opposite direction. A filtered alias
        // is the usual poor-man's document boundary, so the count has to be of
        // what the alias exposes.
        let mut alias_filters: Vec<Value> = Vec::new();
        for part in index.split(',').map(str::trim) {
            for entry in state.engine.aliases.iter() {
                if entry.key() != part {
                    continue;
                }
                for backing in entry.value().iter() {
                    if let Some(meta) = state.engine.index_alias_metadata.get(backing) {
                        if let Some(filter) = meta.get(part).and_then(|v| v.get("filter")).cloned()
                        {
                            alias_filters.push(filter);
                        }
                    }
                }
            }
        }
        let has_query = !alias_filters.is_empty()
            || min_score.is_some()
            || body
                .as_ref()
                .and_then(|b| b.get("query"))
                .map(|q| !q.is_null())
                .unwrap_or(false);
        // A refused query is not a zero. This loop used to run the search under
        // `if let Ok(..)` with no else, so an index whose mapping refuses the
        // query — a `match` on an `"index": false` field, say — contributed
        // nothing to `total` and the response still published
        // `"successful": <all>, "failed": 0`: a confident wrong count on the
        // shapes most callers actually write (`logs-*`, a comma list, and
        // `POST /_count`, which routes here through `_all`).
        //
        // The failure is now reported per index, and the HTTP status follows
        // ES's own rule for a broadcast action: the failure status is returned
        // only when NO shard succeeded, and otherwise the response is a 200
        // carrying the partial count with the failures visible in `_shards`
        // (`server/src/main/java/org/elasticsearch/rest/RestStatus.java:548-566`
        // — read for semantics only; ES is AGPL-3.0/SSPL-1.0/Elastic-2.0 and
        // no code from it is reproduced here). So a single-index `_count`, and
        // a `logs-*` whose indices all share the offending mapping, both 400
        // exactly as `_search` does, while a mixed selector answers what it
        // could count and says out loud what it could not.
        let mut total: u64 = 0;
        let mut successful: u64 = 0;
        let mut shard_failures: Vec<Value> = Vec::new();
        let mut first_error: Option<Value> = None;
        for ix_name in &wanted {
            let Ok(idx) = state.engine.get_index(ix_name) else {
                continue;
            };
            if has_query {
                let mut query_val = body
                    .as_ref()
                    .and_then(|b| b.get("query"))
                    .cloned()
                    .unwrap_or(json!({ "match_all": {} }));
                if !alias_filters.is_empty() {
                    query_val = json!({
                        "bool": {
                            "must": [query_val],
                            "filter": alias_filters.clone(),
                        }
                    });
                }
                // Resolve `terms` lookups exactly as `_search` does — without
                // this, `_count` silently returned 0 for a filter that
                // `_search` counts correctly (the parser sees the raw lookup
                // object and rejects it).
                resolve_terms_lookups(&mut query_val, &state).await;
                let search_body = json!({ "query": query_val, "size": 0, "from": 0 });
                // A body that does not parse is not per-index: it is the same
                // 400 the single-index arm returns, for the same reason.
                let mut req = match xerj_query::parse_request(&search_body) {
                    Ok(r) => r,
                    Err(e) => {
                        let ze = xerj_common::XerjError::invalid_query(e.to_string());
                        return ApiError::new(ze).into_response();
                    }
                };
                // `parse_request` leaves `min_score` at None (the `_search`
                // handler fills it from `EsSearchBody`), so the count path has
                // to set it explicitly or the threshold is silently dropped.
                if let Some(ms) = min_score {
                    req.min_score = Some(ms);
                }
                match idx.search(&req).await {
                    Ok(result) => {
                        // A script resource limit in the filter (terms_set's
                        // `minimum_should_match` script, say) makes matching
                        // fail-closed, so the count under-reports with nothing
                        // to distinguish it from a genuine zero.
                        if let Some(reason) = &result.script_failure {
                            return script_limit_response(reason);
                        }
                        total += result.total.value;
                        successful += 1;
                    }
                    Err(e) => {
                        let rendered = ApiError::new(xerj_common::XerjError::from(e)).into_value();
                        shard_failures.push(count_shard_failure(ix_name, &rendered));
                        if first_error.is_none() {
                            first_error = Some(rendered);
                        }
                    }
                }
            } else {
                total += content_doc_count(&idx).await;
                successful += 1;
            }
        }
        // Nothing answered and something refused: the count IS the error, and
        // it is returned with the same body and status the single-index form
        // would have produced.
        if successful == 0 && !shard_failures.is_empty() {
            if let Some(rendered) = first_error {
                let code = rendered
                    .get("status")
                    .and_then(Value::as_u64)
                    .and_then(|c| StatusCode::from_u16(c as u16).ok())
                    .unwrap_or(StatusCode::BAD_REQUEST);
                return (code, Json(rendered)).into_response();
            }
        }
        // `total` is what was actually attempted, so the three numbers add up:
        // a name in a comma list that resolves to no index is skipped here (as
        // it always was) rather than counted as a shard that succeeded.
        let failed = shard_failures.len() as u64;
        let mut body_out = json!({
            "count": total,
            "_shards": { "total": successful + failed, "successful": successful, "skipped": 0, "failed": failed }
        });
        if !shard_failures.is_empty() {
            body_out["_shards"]["failures"] = Value::Array(shard_failures);
        }
        if let Some(ref fp) = params.filter_path {
            if !fp.is_empty() {
                let paths: Vec<&str> = fp.split(',').map(str::trim).collect();
                body_out = apply_filter_path(body_out, &paths);
            }
        }
        return Json(body_out).into_response();
    }
    let idx = match state.engine.get_index(&index) {
        Ok(i) => i,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    // If no query or match_all, use the stored stats for speed. A body that
    // carries `min_score` still has to run the query: match_all scores 1.0, so
    // a threshold above it counts zero.
    let has_query = min_score.is_some()
        || body
            .as_ref()
            .and_then(|b| b.get("query"))
            .map(|q| !q.is_null())
            .unwrap_or(false);

    let count = if has_query {
        // Run a search with size=0 to get the total.
        let mut query_val = body
            .as_ref()
            .and_then(|b| b.get("query"))
            .cloned()
            .unwrap_or(json!({ "match_all": {} }));
        // Resolve `terms` lookups before parsing — `_search` does this at its
        // coordination step, and `_count` must match or it silently returns 0
        // where `_search` returns the real total.
        resolve_terms_lookups(&mut query_val, &state).await;
        let search_body = json!({ "query": query_val, "size": 0, "from": 0 });
        match xerj_query::parse_request(&search_body) {
            Ok(mut req) => {
                // `parse_request` leaves `min_score` at None (the `_search`
                // handler fills it from `EsSearchBody`), so the count path has
                // to set it explicitly or the threshold is silently dropped.
                if let Some(ms) = min_score {
                    req.min_score = Some(ms);
                }
                match idx.search(&req).await {
                    Ok(result) => {
                        if let Some(reason) = &result.script_failure {
                            return script_limit_response(reason);
                        }
                        result.total.value
                    }
                    Err(e) => {
                        return ApiError::new(xerj_common::XerjError::from(e)).into_response()
                    }
                }
            }
            Err(e) => {
                let ze = xerj_common::XerjError::invalid_query(e.to_string());
                return ApiError::new(ze).into_response();
            }
        }
    } else {
        content_doc_count(&idx).await
    };

    let mut body_out = json!({
        "count": count,
        "_shards": { "total": 1, "successful": 1, "skipped": 0, "failed": 0 }
    });
    if let Some(ref fp) = params.filter_path {
        if !fp.is_empty() {
            let paths: Vec<&str> = fp.split(',').map(str::trim).collect();
            body_out = apply_filter_path(body_out, &paths);
        }
    }
    Json(body_out).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// HEAD /{index}/_doc/{id}
// ─────────────────────────────────────────────────────────────────────────────

pub async fn head_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
) -> impl IntoResponse {
    let index = match write_target_or_refusal(&state, &index) {
        Ok(index) => index,
        Err(resp) => return resp,
    };
    let idx = match state.engine.get_index(&index) {
        Ok(i) => i,
        Err(_) => return StatusCode::NOT_FOUND.into_response(),
    };

    match idx.get_document(&id).await {
        Ok(Some(_)) => StatusCode::OK.into_response(),
        _ => StatusCode::NOT_FOUND.into_response(),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_mget
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct MgetRequest {
    pub docs: Vec<MgetDoc>,
}

#[derive(Debug, Deserialize)]
pub struct MgetDoc {
    #[serde(rename = "_index")]
    pub index: String,
    #[serde(rename = "_id")]
    pub id: String,
    /// Per-item `_source` filter (ES): `false` omits `_source`, `true`/absent
    /// returns it whole, a string/array is an includes list, and
    /// `{"includes":[..],"excludes":[..]}` is both.
    #[serde(rename = "_source", default)]
    pub source: Option<Value>,
}

/// Apply a per-item mget `_source` spec to a document's source. Returns `None`
/// when the item asked to suppress `_source` (`_source: false`) so the caller
/// omits the key entirely (ES). Absent / `true` returns the source unchanged.
fn apply_mget_item_source(source: Value, spec: Option<&Value>) -> Option<Value> {
    let str_list = |v: &Value| -> Vec<String> {
        match v {
            Value::String(s) => vec![s.clone()],
            Value::Array(a) => a
                .iter()
                .filter_map(|x| x.as_str().map(String::from))
                .collect(),
            _ => Vec::new(),
        }
    };
    match spec {
        Some(Value::Bool(false)) => None,
        Some(Value::Bool(true)) | None | Some(Value::Null) => Some(source),
        Some(v @ (Value::String(_) | Value::Array(_))) => {
            Some(xerj_engine::filter_object(&source, &str_list(v), &[]))
        }
        Some(Value::Object(o)) => {
            let inc = o.get("includes").map(str_list).unwrap_or_default();
            let exc = o.get("excludes").map(str_list).unwrap_or_default();
            Some(xerj_engine::filter_object(&source, &inc, &exc))
        }
        Some(_) => Some(source),
    }
}

pub async fn mget(
    State(state): State<AppState>,
    Json(body): Json<MgetRequest>,
) -> impl IntoResponse {
    let max = state.config.limits.max_mget_docs;
    if body.docs.len() > max {
        return (
            axum::http::StatusCode::BAD_REQUEST,
            Json(json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": format!(
                        "mget request contains {} docs, exceeds limits.max_mget_docs of {max}",
                        body.docs.len()
                    ),
                },
                "status": 400,
            })),
        )
            .into_response();
    }
    let mut docs: Vec<Value> = Vec::with_capacity(body.docs.len());

    for req_doc in &body.docs {
        let idx = match state.engine.get_index(&req_doc.index) {
            Ok(i) => i,
            Err(_) => {
                docs.push(json!({
                    "_index": req_doc.index,
                    "_id": req_doc.id,
                    "found": false,
                }));
                continue;
            }
        };

        match idx.get_document(&req_doc.id).await {
            Ok(Some(source)) => {
                // Real per-doc `_seq_no` / `_version` — same resolvers the
                // `_search` hit metadata and GET `_doc` use; were hardcoded
                // 0 / 1.
                let seq_no = idx.lookup_seq_no(&req_doc.id).unwrap_or(0);
                let version = idx.lookup_version(&req_doc.id).unwrap_or(1);
                let mut d = json!({
                    "_index": req_doc.index,
                    "_id": req_doc.id,
                    "_version": version,
                    "_seq_no": seq_no,
                    "_primary_term": 1,
                    "found": true,
                });
                if let Some(s) = apply_mget_item_source(source, req_doc.source.as_ref()) {
                    d["_source"] = s;
                }
                docs.push(d);
            }
            _ => {
                docs.push(json!({
                    "_index": req_doc.index,
                    "_id": req_doc.id,
                    "found": false,
                }));
            }
        }
    }

    Json(json!({ "docs": docs })).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET|POST /{index}/_mget
// ─────────────────────────────────────────────────────────────────────────────

/// Index-scoped multi-get. The path index is the default for any entry that
/// omits `_index`. Accepts both the `{"ids": [...]}` short form and the
/// `{"docs": [{"_id": ..., "_index"?: ...}]}` long form.
pub async fn mget_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    // Collect (index, id, per-item _source spec) entries, defaulting the index
    // to the path index.
    let mut entries: Vec<(String, String, Option<Value>)> = Vec::new();
    if let Some(ids) = body.get("ids").and_then(Value::as_array) {
        for id in ids {
            if let Some(s) = id.as_str() {
                entries.push((index.clone(), s.to_string(), None));
            }
        }
    } else if let Some(docs) = body.get("docs").and_then(Value::as_array) {
        for d in docs {
            let i = d
                .get("_index")
                .and_then(Value::as_str)
                .unwrap_or(&index)
                .to_string();
            let id = d
                .get("_id")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            entries.push((i, id, d.get("_source").cloned()));
        }
    }

    let max = state.config.limits.max_mget_docs;
    if entries.len() > max {
        return (
            axum::http::StatusCode::BAD_REQUEST,
            Json(json!({
                "error": {
                    "type": "illegal_argument_exception",
                    "reason": format!(
                        "mget request contains {} docs, exceeds limits.max_mget_docs of {max}",
                        entries.len()
                    ),
                },
                "status": 400,
            })),
        )
            .into_response();
    }

    let mut docs: Vec<Value> = Vec::with_capacity(entries.len());
    for (ix, id, src_spec) in &entries {
        // Resolve the entry's index through the shared resolver (#451): an
        // alias expands to every member, so a doc in any member is found — not
        // just the first. `get_index` collapsed an alias to `aliased.first()`,
        // so a non-first member's doc reported `found:false` (class B).
        let members = match resolve_selector_with_filters(&state, ix).await {
            Ok((m, _filters)) => m,
            Err(_) => {
                docs.push(json!({ "_index": ix, "_id": id, "found": false }));
                continue;
            }
        };
        let mut hit = None;
        for (mname, midx) in &members {
            if let Ok(Some(source)) = midx.get_document(id).await {
                hit = Some((mname.clone(), midx.clone(), source));
                break;
            }
        }
        match hit {
            Some((mname, midx, source)) => {
                // Real per-doc `_seq_no` / `_version` (were hardcoded 0 / 1) —
                // matches the `_search` hit metadata path. `_index` reports the
                // concrete member the doc lives in, not the alias.
                let seq_no = midx.lookup_seq_no(id).unwrap_or(0);
                let version = midx.lookup_version(id).unwrap_or(1);
                let mut d = json!({
                    "_index": mname,
                    "_id": id,
                    "_version": version,
                    "_seq_no": seq_no,
                    "_primary_term": 1,
                    "found": true,
                });
                if let Some(s) = apply_mget_item_source(source, src_spec.as_ref()) {
                    d["_source"] = s;
                }
                docs.push(d);
            }
            None => docs.push(json!({
                "_index": ix,
                "_id": id,
                "found": false,
            })),
        }
    }

    Json(json!({ "docs": docs })).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/ann  &  GET /_cat/ann/{index}   (XERJ extension — RC4-W4 item 7)
// ─────────────────────────────────────────────────────────────────────────────

/// Query params for `/_cat/ann`. `v` (a valueless flag) adds a header row;
/// `format=json` returns a JSON array instead of the plain-text table.
#[derive(Debug, Deserialize, Default)]
pub struct CatAnnParams {
    #[serde(default)]
    pub v: Option<String>,
    #[serde(default)]
    pub format: Option<String>,
}

/// `GET /_cat/ann` — ANN/HNSW health for every index.
///
/// Surfaces the same live state as `GET /{index}/_stats`'s `hnsw` block, but in
/// the `_cat` tabular family operators already reach for. Its reason to exist:
/// a vector index that is `stale` or under-`covered` silently degrades kNN to
/// exact brute force, and without this the only signal was a per-index `_stats`
/// call. Columns: index present field nodes tombstones vector_docs coverage
/// covered stale rebuilding.
pub async fn cat_ann(
    State(state): State<AppState>,
    Query(params): Query<CatAnnParams>,
) -> impl IntoResponse {
    cat_ann_inner(state, None, params).await
}

/// `GET /_cat/ann/{index}` — health for the named index / comma-list / pattern.
pub async fn cat_ann_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<CatAnnParams>,
) -> impl IntoResponse {
    cat_ann_inner(state, Some(index), params).await
}

async fn cat_ann_inner(
    state: AppState,
    index: Option<String>,
    params: CatAnnParams,
) -> axum::response::Response {
    let all = state.engine.index_name_list();
    // Resolve the target set (mirrors _cat/indices selector rules: a concrete
    // name matching nothing 404s; a wildcard matching nothing is an empty 200).
    let targets: Vec<String> = match index.as_deref() {
        None => all,
        Some(sel) => {
            let parts: Vec<&str> = sel
                .split(',')
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .collect();
            for &p in &parts {
                let is_wild = p == "_all" || p == "*" || p.contains('*');
                if !is_wild && !all.iter().any(|n| n == p) {
                    return ApiError::new(xerj_common::XerjError::index_not_found(p))
                        .into_response();
                }
            }
            all.into_iter()
                .filter(|n| {
                    parts
                        .iter()
                        .any(|&p| p == "_all" || p == "*" || n == p || glob_match_simple(p, n))
                })
                .collect()
        }
    };

    let mut rows: Vec<(String, Value)> = Vec::new();
    for name in &targets {
        if let Ok(idx) = state.engine.get_index(name) {
            rows.push((name.clone(), idx.hnsw_stats().await));
        }
    }
    rows.sort_by(|a, b| a.0.cmp(&b.0));

    if params.format.as_deref() == Some("json") {
        let arr: Vec<Value> = rows
            .iter()
            .map(|(name, s)| {
                json!({
                    "index": name,
                    "present": s["present"],
                    "field": s["field"],
                    "nodes": s["nodes"],
                    "tombstones": s["tombstones"],
                    "vector_docs": s["vector_doc_count"],
                    "coverage": s["doc_coverage"],
                    "covered": s["covered"],
                    "passage_exact_fields": s["passage_exact_fields"],
                    "semantic_ann_blocked_by_passages": s["semantic_ann_blocked_by_passages"],
                    "stale": s["stale"],
                    "rebuilding": s["rebuilding"],
                })
            })
            .collect();
        return Json(arr).into_response();
    }

    let mut out = String::new();
    if params.v.is_some() {
        out.push_str(
            "index present field nodes tombstones vector_docs coverage covered stale rebuilding\n",
        );
    }
    for (name, s) in &rows {
        out.push_str(&format!(
            "{} {} {} {} {} {} {} {} {} {}\n",
            name,
            s["present"].as_bool().unwrap_or(false),
            s["field"].as_str().unwrap_or("-"),
            s["nodes"].as_u64().unwrap_or(0),
            s["tombstones"].as_u64().unwrap_or(0),
            s["vector_doc_count"].as_u64().unwrap_or(0),
            s["doc_coverage"].as_u64().unwrap_or(0),
            s["covered"].as_bool().unwrap_or(false),
            s["stale"].as_bool().unwrap_or(false),
            s["rebuilding"].as_bool().unwrap_or(false),
        ));
    }
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        out,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/health
// ─────────────────────────────────────────────────────────────────────────────

/// `GET /_cat/health`.
///
/// The status column used to be the literal string `green`, so the one
/// endpoint an operator's existing dashboard points at was the one endpoint
/// that could not report a broken node — `/v1/health`, `/v1/cluster/health`
/// and `/health/ready` all knew, and `_cat/health` said everything was fine
/// (issue #206). It now reports the same status `_cluster/health` computes,
/// from the same inputs.
pub async fn cat_health(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    let health = state.engine.health().await;
    // epoch  timestamp  cluster  status  node.total  node.data  shards  pri  relo  init  unassign  pending_tasks  max_task_wait_time  active_shards_percent
    let epoch = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let now = Utc::now();
    let ts = now.format("%H:%M:%S").to_string();
    let shards = health.index_count as u32;
    let unassigned = state.engine.list_failed_indices().len() as u32;
    // Mirror `_cluster/health`: an unopenable index is an unassigned primary
    // (red); an unassigned replica is yellow. The engine's own "yellow" means
    // "unflushed memtable", which is a durability nuance rather than an ES
    // shard state, so it deliberately does not colour this column.
    let status = if unassigned > 0 { "red" } else { "green" };
    let total = shards + unassigned;
    let pct = if total == 0 {
        100.0
    } else {
        (shards as f64) / (total as f64) * 100.0
    };

    if params.format.as_deref() == Some("json") {
        return Json(vec![json!({
            "epoch": epoch.to_string(),
            "timestamp": ts,
            "cluster": "xerj",
            "status": status,
            "node.total": "1",
            "node.data": "1",
            "shards": shards.to_string(),
            "pri": shards.to_string(),
            "relo": "0",
            "init": "0",
            "unassign": unassigned.to_string(),
            "pending_tasks": "0",
            "max_task_wait_time": "-",
            "active_shards_percent": format!("{pct:.1}%"),
        })])
        .into_response();
    }

    let body = format!(
        "{epoch} {ts} xerj {status} 1 1 {shards} {shards} 0 0 {unassigned} 0 - {pct:.1}%\n"
    );
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/nodes
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cat_nodes(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // ip  heap.percent  ram.percent  cpu  load_1m  load_5m  load_15m  node.role  master  name
    let (mem_total, mem_avail) = read_meminfo().unwrap_or((0, 0));
    // ram.percent = (1 - MemAvailable/MemTotal) * 100
    let ram_percent = if mem_total > 0 {
        ((1.0 - (mem_avail as f64 / mem_total as f64)) * 100.0).round() as u64
    } else {
        0
    };
    // heap.percent: process RSS as a fraction of MemTotal. We read RSS from
    // /proc/self/status (VmRSS, already in bytes) via the existing helper —
    // equivalent to /proc/self/statm resident-pages * pagesize, but without
    // needing libc::sysconf to obtain the page size.
    let heap_percent = match (read_rss_bytes(), mem_total) {
        (Some(rss), total) if total > 0 => ((rss as f64 / total as f64) * 100.0).round() as u64,
        _ => 0,
    };
    let cpu = sample_cpu_percent().await;
    let (l1, l5, l15) = read_loadavg();
    let name = state.engine.node_id.as_str();

    // Honest membership rows (#1169): one row per configured member. The
    // self row carries live metrics; peer rows — processes we cannot see —
    // carry "-" placeholders, exactly as ES renders values it does not know.
    // `master` is "*" only on a cluster-disabled node (where self is
    // trivially the whole cluster); on a configured ring the leader is not
    // known to this layer yet (see #1170), and stamping "*" on self would
    // be the same fabrication this endpoint is recovering from.
    let members = configured_members(&state.config);
    let own_addr = members
        .first()
        .map(|(_, a)| *a)
        .unwrap_or(std::net::SocketAddr::from(([127, 0, 0, 1], 9300)));
    let master_col = if state.config.cluster.enabled {
        "-"
    } else {
        "*"
    };

    if params.format.as_deref() == Some("json") {
        let mut rows: Vec<Value> = Vec::with_capacity(members.len());
        rows.push(json!({
            "ip": own_addr.ip().to_string(),
            "heap.percent": heap_percent.to_string(),
            "ram.percent": ram_percent.to_string(),
            "cpu": cpu.to_string(),
            "load_1m": format!("{l1:.2}"),
            "load_5m": format!("{l5:.2}"),
            "load_15m": format!("{l15:.2}"),
            "node.role": "cdfhilmrstw",
            "master": master_col,
            "name": name,
        }));
        for (peer_id, addr) in members.iter().skip(1) {
            rows.push(json!({
                "ip": addr.ip().to_string(),
                "heap.percent": "-",
                "ram.percent": "-",
                "cpu": "-",
                "load_1m": "-",
                "load_5m": "-",
                "load_15m": "-",
                "node.role": "-",
                "master": "-",
                "name": peer_id,
            }));
        }
        return Json(rows).into_response();
    }

    let mut body = format!(
        "{ip} {heap_percent} {ram_percent} {cpu} {l1:.2} {l5:.2} {l15:.2} cdfhilmrstw {master_col} {name}\n",
        ip = own_addr.ip(),
    );
    for (peer_id, addr) in members.iter().skip(1) {
        body.push_str(&format!("{ip} - - - - - - - - {peer_id}\n", ip = addr.ip()));
    }
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_analyze
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct EsAnalyzeBody {
    pub text: Option<Value>,
    /// Absent = the index's own text analyzer on `/{index}/_analyze` (its
    /// declared `default`, #1092), `standard` on the global endpoint.
    #[serde(default)]
    pub analyzer: Option<String>,
    /// Analyse as this field of the index is indexed (#1092).
    #[serde(default)]
    pub field: Option<String>,
    /// Ad-hoc chain parts (`tokenizer`, `filter`, `char_filter`): each a
    /// name or an inline definition, built into a one-off `custom` analyzer
    /// by the same registry code index creation uses (#1092). `normalizer`
    /// is refused with a 400 rather than silently answered with another
    /// analyzer's tokens.
    #[serde(default)]
    pub tokenizer: Option<Value>,
    #[serde(default)]
    pub filter: Option<Value>,
    #[serde(default)]
    pub char_filter: Option<Value>,
    #[serde(default)]
    pub normalizer: Option<Value>,
    /// When true, returns step-by-step output of each pipeline stage.
    ///
    /// Shows: tokenizer output → lowercase → stopwords → stemmer.
    /// Mirrors Elasticsearch's `explain: true` analysis response.
    #[serde(default)]
    pub explain: bool,
}

fn analyze_illegal_argument(reason: String) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                "type": "illegal_argument_exception",
                "reason": reason,
            },
            "status": 400,
        })),
    )
        .into_response()
}

/// Name of the one-off analyzer an ad-hoc `_analyze` chain is built as.
const ADHOC_ANALYZER: &str = "_analyze_adhoc";

/// Turn an ad-hoc `_analyze` chain into an `analysis` settings block declaring
/// one `custom` analyzer, so it is built — and validated — by exactly the
/// registry code an index's own analysis goes through (#1092).
///
/// Names refer to built-ins, or on an index-scoped call to the components the
/// index declares (`index_analysis`, the block in force); inline definitions
/// get reserved `_analyze_*` names. With filters and no tokenizer the chain
/// uses `keyword`, as Elasticsearch and OpenSearch do.
fn adhoc_analysis_settings(body: &EsAnalyzeBody, index_analysis: Option<&Value>) -> Value {
    let mut analysis = serde_json::Map::new();
    for kind in ["tokenizer", "filter", "char_filter"] {
        let defs = index_analysis
            .and_then(|a| a.get(kind))
            .cloned()
            .unwrap_or_else(|| json!({}));
        analysis.insert(kind.to_string(), defs);
    }
    let mut define = |kind: &str, name: String, def: &Value| -> String {
        if let Some(m) = analysis.get_mut(kind).and_then(Value::as_object_mut) {
            m.insert(name.clone(), def.clone());
        }
        name
    };
    let tokenizer = match &body.tokenizer {
        Some(Value::String(s)) => s.clone(),
        Some(def) => define("tokenizer", "_analyze_tokenizer".to_string(), def),
        None => "keyword".to_string(),
    };
    let mut chain = |kind: &str, parts: &Option<Value>| -> Vec<String> {
        let items = match parts {
            Some(Value::Array(a)) => a.clone(),
            Some(single) => vec![single.clone()],
            None => Vec::new(),
        };
        items
            .iter()
            .enumerate()
            .map(|(i, part)| match part {
                Value::String(s) => s.clone(),
                def => define(kind, format!("_analyze_{kind}_{i}"), def),
            })
            .collect()
    };
    let filter = chain("filter", &body.filter);
    let char_filter = chain("char_filter", &body.char_filter);
    analysis.insert(
        "analyzer".to_string(),
        json!({ ADHOC_ANALYZER: {
            "type": "custom",
            "tokenizer": tokenizer,
            "filter": filter,
            "char_filter": char_filter,
        }}),
    );
    json!({ "analysis": Value::Object(analysis) })
}

/// Build and run an ad-hoc chain. `Err` = the registry cannot honour it, with
/// the same reasons index creation would give.
fn run_adhoc_analyze(
    body: &EsAnalyzeBody,
    index_analysis: Option<&Value>,
    input: &str,
) -> Result<Vec<xerj_engine::Token>, String> {
    let settings = adhoc_analysis_settings(body, index_analysis);
    let problems = xerj_engine::AnalyzerRegistry::unsupported_analysis(&settings);
    if !problems.is_empty() {
        return Err(format!(
            "xerj cannot honour this analysis chain — {}",
            problems.join("; ")
        ));
    }
    let mut registry = xerj_engine::AnalyzerRegistry::with_defaults();
    registry.apply_settings(&settings);
    let pipeline = registry
        .get_analyzer(ADHOC_ANALYZER)
        .ok_or_else(|| "xerj could not build this analysis chain".to_string())?;
    Ok(pipeline.analyze(input))
}

/// ES `_analyze` token objects from real pipeline output. `type` stays the
/// `word` this endpoint has always reported; offsets and positions are the
/// pipeline's own.
fn analyze_tokens_json(tokens: &[xerj_engine::Token]) -> Vec<Value> {
    tokens
        .iter()
        .map(|t| {
            json!({
                "token": t.text,
                "start_offset": t.start_offset,
                "end_offset": t.end_offset,
                "type": "word",
                "position": t.position,
            })
        })
        .collect()
}

/// Global `POST /_analyze` (no index prefix).
pub async fn analyze_text_global(
    State(state): State<AppState>,
    Json(body): Json<EsAnalyzeBody>,
) -> impl IntoResponse {
    analyze_text(State(state), Path("_none".to_string()), Json(body)).await
}

pub async fn analyze_text(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Json(body): Json<EsAnalyzeBody>,
) -> impl IntoResponse {
    let input = match &body.text {
        Some(Value::String(s)) => s.clone(),
        Some(Value::Array(arr)) => arr
            .iter()
            .filter_map(|v| v.as_str())
            .collect::<Vec<_>>()
            .join(" "),
        _ => String::new(),
    };

    if body.normalizer.is_some() {
        return analyze_illegal_argument(
            "_analyze does not support [normalizer] on xerj (it would otherwise be answered \
             with another analyzer's tokens)"
                .to_string(),
        );
    }
    let adhoc = body.tokenizer.is_some() || body.filter.is_some() || body.char_filter.is_some();
    if adhoc {
        if body.analyzer.is_some() || body.field.is_some() {
            return analyze_illegal_argument(
                "cannot define an ad-hoc chain (tokenizer/filter/char_filter) together with \
                 [analyzer] or [field]"
                    .to_string(),
            );
        }
        if body.explain {
            return analyze_illegal_argument(
                "_analyze explain is not supported for an ad-hoc chain on xerj".to_string(),
            );
        }
        // Index-scoped: the chain may name the index's own components.
        let index_analysis = if index == "_none" {
            None
        } else {
            let targets = resolve_index_selector(&state, &index).await;
            let Some(idx) = targets
                .first()
                .and_then(|name| state.engine.get_index(name).ok())
            else {
                return ApiError::new(xerj_common::XerjError::index_not_found(&index))
                    .into_response();
            };
            idx.analysis_in_force().await
        };
        return match run_adhoc_analyze(&body, index_analysis.as_ref(), &input) {
            Ok(tokens) => Json(json!({ "tokens": analyze_tokens_json(&tokens) })).into_response(),
            Err(reason) => analyze_illegal_argument(reason),
        };
    }

    if index == "_none" {
        // Global endpoint: built-in analyzers only, no index to resolve a
        // field or a custom analyzer against.
        if let Some(f) = &body.field {
            return analyze_illegal_argument(format!(
                "analysing field [{f}] requires an index: use POST /{{index}}/_analyze"
            ));
        }
        let name = body.analyzer.as_deref().unwrap_or("standard");
        if body.explain {
            // Step-by-step pipeline explanation (unchanged): stage-by-stage
            // for "standard"/"english", final tokens otherwise.
            return Json(analyze_explain(&input, name)).into_response();
        }
        let Some(pipeline) = xerj_engine::analyzer_registry().get_analyzer(name) else {
            return analyze_illegal_argument(format!("failed to find global analyzer [{name}]"));
        };
        let tokens = analyze_tokens_json(&pipeline.analyze(&input));
        return Json(json!({ "tokens": tokens })).into_response();
    }

    // Index-scoped (#1092): the index's OWN registry and field resolution —
    // the pipeline a search on this index actually runs, so a declared
    // `analysis.analyzer.default` stemmer shows up here.
    let targets = resolve_index_selector(&state, &index).await;
    let Some(idx) = targets
        .first()
        .and_then(|name| state.engine.get_index(name).ok())
    else {
        return ApiError::new(xerj_common::XerjError::index_not_found(&index)).into_response();
    };
    match idx
        .analyze(body.analyzer.as_deref(), body.field.as_deref(), &input)
        .await
    {
        Ok((name, tokens)) => {
            let tokens = analyze_tokens_json(&tokens);
            if body.explain {
                return Json(json!({
                    "detail": {
                        "custom_analyzer": false,
                        "analyzer": { "name": name, "tokens": tokens },
                    }
                }))
                .into_response();
            }
            Json(json!({ "tokens": tokens })).into_response()
        }
        Err(reason) => analyze_illegal_argument(reason),
    }
}

/// Produce step-by-step analysis explanation.
///
/// For the "standard" analyzer the pipeline is:
/// 1. `tokenizer`  — Unicode word boundaries (StandardTokenizer)
/// 2. `lowercase`  — LowercaseFilter
/// 3. `stopwords`  — StopwordsFilter (English)
/// 4. `stemmer`    — SnowballStemmer (English/Porter2)
///
/// Each stage's token list is shown so developers can debug why a term was
/// dropped, modified, or expanded.
fn analyze_explain(input: &str, analyzer: &str) -> Value {
    // Use the AnalyzerRegistry from xerj-engine's analyzer (via AppState would
    // require async; we use the default registry directly here).
    let _registry = xerj_engine::analyzer_registry();

    if analyzer != "standard" && analyzer != "english" {
        // For non-standard analyzers just show final output.
        let final_tokens = tokenize_for_analyze(input, analyzer);
        return json!({
            "detail": {
                "custom_analyzer": false,
                "analyzer": { "name": analyzer, "tokens": final_tokens },
            }
        });
    }

    // Step-by-step for "standard": tokenize → lowercase → stopwords → stemmer.
    let steps = xerj_engine::analyze_explain_steps(input);

    json!({
        "detail": {
            "custom_analyzer": false,
            "analyzer": {
                "name": analyzer,
                "tokens": steps.final_tokens,
            },
            "tokenizer": {
                "name": "standard",
                "tokens": steps.after_tokenizer,
            },
            "token_filters": [
                { "name": "lowercase", "tokens": steps.after_lowercase },
                { "name": "stop",      "tokens": steps.after_stopwords },
                { "name": "snowball",  "tokens": steps.after_stemmer   },
            ]
        }
    })
}

/// Minimal inline tokenizer for the _analyze endpoint.
fn tokenize_for_analyze(input: &str, analyzer: &str) -> Vec<Value> {
    match analyzer {
        "keyword" => {
            if input.is_empty() {
                vec![]
            } else {
                vec![json!({
                    "token": input,
                    "start_offset": 0,
                    "end_offset": input.len(),
                    "type": "word",
                    "position": 0,
                })]
            }
        }
        "whitespace" => {
            let mut tokens = Vec::new();
            let mut pos = 0u32;
            let mut start = 0usize;
            let mut in_tok = false;
            for (i, byte) in input.bytes().enumerate() {
                let ws = matches!(byte, b' ' | b'\t' | b'\n' | b'\r');
                if !ws && !in_tok {
                    start = i;
                    in_tok = true;
                } else if ws && in_tok {
                    let tok = &input[start..i];
                    tokens.push(json!({
                        "token": tok,
                        "start_offset": start,
                        "end_offset": i,
                        "type": "word",
                        "position": pos,
                    }));
                    pos += 1;
                    in_tok = false;
                }
            }
            if in_tok {
                let end = input.len();
                let tok = &input[start..end];
                tokens.push(json!({
                    "token": tok,
                    "start_offset": start,
                    "end_offset": end,
                    "type": "word",
                    "position": pos,
                }));
            }
            tokens
        }
        // "standard" | "lowercase" | "stemmer" | _ — Unicode word-boundary split + lowercase
        _ => {
            let mut tokens = Vec::new();
            let mut pos = 0u32;
            let mut start = 0usize;
            let mut in_tok = false;
            let bytes = input.as_bytes();
            let mut i = 0usize;
            while i <= input.len() {
                let is_alnum =
                    i < input.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] > 127);
                if is_alnum && !in_tok {
                    start = i;
                    in_tok = true;
                } else if !is_alnum && in_tok {
                    let tok = input[start..i].to_lowercase();
                    tokens.push(json!({
                        "token": tok,
                        "start_offset": start,
                        "end_offset": i,
                        "type": "word",
                        "position": pos,
                    }));
                    pos += 1;
                    in_tok = false;
                }
                i += 1;
            }
            tokens
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}/_stats
// ─────────────────────────────────────────────────────────────────────────────

/// `POST /{index}/_disk_usage` — on-disk store size.
///
/// `store_size_in_bytes` is the real recursive byte sum of the index's
/// `data_dir`. XERJ does NOT compute the ES per-field / per-category
/// breakdown (inverted_index / doc_values / points / norms / term_vectors /
/// knn_vectors), so `fields` is honestly empty rather than fabricated with
/// hardcoded zeros. The total is genuinely useful; only the decomposition is
/// unavailable, and we don't imply otherwise.
pub async fn index_disk_usage(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }
    let mut indices = serde_json::Map::new();
    let mut all_size = 0u64;
    for name in &targets {
        // Real on-disk size: recursive byte sum of the index's data_dir.
        let size = match state.engine.get_index(name) {
            Ok(idx) => dir_size_bytes(idx.data_dir()),
            Err(_) => continue,
        };
        all_size += size;
        indices.insert(
            name.clone(),
            json!({
                // Real on-disk total only. The ES per-field / per-category
                // breakdown is not computed, so `fields` is honestly empty
                // rather than fabricated zeros (see the handler doc-comment).
                "store_size": format!("{}b", size),
                "store_size_in_bytes": size,
                "fields": {}
            }),
        );
    }
    let mut out = serde_json::Map::new();
    out.insert(
        "_shards".to_string(),
        json!({"total":1,"successful":1,"failed":0}),
    );
    let _ = all_size;
    for (k, v) in indices {
        out.insert(k, v);
    }
    Json(Value::Object(out)).into_response()
}

pub async fn index_stats(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    // Resolve `_all` / `*` patterns to all participating indices and
    // sum their stats into a single _all view + per-index breakdown.
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }
    if targets.len() > 1 || index == "_all" || index.contains('*') {
        // Aggregate across multiple indices.
        let mut all_doc_count = 0u64;
        let mut all_deleted_doc_count = 0u64;
        let mut all_store_bytes = 0u64;
        // Aggregated so `GET /_all/_stats` carries the same
        // `primaries.mappings.schema_persist_failures` the per-index form does.
        // Without it `Index::schema_persist_failures`'s doc-comment named an
        // endpoint that did not report the counter, and a fleet-wide health
        // check reading only `_all` saw nothing (issue #204: the claim has to
        // match what the endpoint really answers).
        let mut all_schema_persist_failures = 0u64;
        let mut all_indices = serde_json::Map::new();
        for name in &targets {
            let stats = match state.engine.index_stats(name).await {
                Ok(s) => s,
                Err(_) => continue,
            };
            let doc_count = stats.doc_count;
            all_doc_count += doc_count;
            let deleted_doc_count = state
                .engine
                .get_index(name)
                .map(|idx| idx.deleted_doc_count())
                .unwrap_or(0);
            all_deleted_doc_count += deleted_doc_count;
            // Real on-disk footprint: recursive byte sum of the index's
            // data dir (WAL + segments + everything else it persists).
            let store_size_bytes = state
                .engine
                .get_index(name)
                .map(|idx| dir_size_bytes(idx.data_dir()))
                .unwrap_or(0);
            all_store_bytes += store_size_bytes;
            let dv = per_index_dense_vector_stats(&state, name);
            let (seg_count, merging) = state
                .engine
                .get_index(name)
                .map(|idx| {
                    (
                        idx.store_snapshot().segments.len(),
                        idx.is_merge_in_progress(),
                    )
                })
                .unwrap_or((0, false));
            // XERJ extension (RC4 W2 item 17): live ANN/HNSW health —
            // `stale`/`rebuilding` make a brute-force-degraded index
            // observable (pre-fix it looked identical to a healthy one).
            let hnsw = match state.engine.get_index(name) {
                Ok(idx) => idx.hnsw_stats().await,
                Err(_) => json!({ "present": false }),
            };
            let schema_persist_failures = state
                .engine
                .get_index(name)
                .map(|idx| idx.schema_persist_failures())
                .unwrap_or(0);
            all_schema_persist_failures += schema_persist_failures;
            let primaries = json!({
                "docs": { "count": doc_count, "deleted": deleted_doc_count },
                "store": { "size_in_bytes": store_size_bytes },
                "dense_vector": dv,
                "hnsw": hnsw,
                "mappings": { "schema_persist_failures": schema_persist_failures },
                "merges": {
                    "current": if merging { 1 } else { 0 },
                    "current_docs": 0,
                    "current_size_in_bytes": 0,
                },
                "segments": { "count": seg_count, "memory_in_bytes": 0 },
            });
            all_indices.insert(
                name.clone(),
                json!({
                    "primaries": primaries,
                    "total": primaries,
                }),
            );
        }
        // Build _all by summing per-index stats. dense_vector merges by
        // summing every numeric leaf and dropping per-index `fielddata`.
        let mut all_dv_size = 0u64;
        let mut all_dv_vec = 0u64;
        let mut all_dv_veb = 0u64;
        let mut all_dv_veq = 0u64;
        let mut all_dv_vex = 0u64;
        let mut all_dv_cenivf = 0u64;
        let mut all_dv_clivf = 0u64;
        let mut all_dv_value_count = 0u64;
        for name in &targets {
            let dv = per_index_dense_vector_stats(&state, name);
            let off = dv.get("off_heap").and_then(|v| v.as_object());
            if let Some(o) = off {
                all_dv_size += o
                    .get("total_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                all_dv_vec += o
                    .get("total_vec_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                all_dv_veb += o
                    .get("total_veb_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                all_dv_veq += o
                    .get("total_veq_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                all_dv_vex += o
                    .get("total_vex_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                all_dv_cenivf += o
                    .get("total_cenivf_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                all_dv_clivf += o
                    .get("total_clivf_size_bytes")
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
            }
            all_dv_value_count += dv.get("value_count").and_then(Value::as_u64).unwrap_or(0);
        }
        let all_primaries = json!({
            "docs": { "count": all_doc_count, "deleted": all_deleted_doc_count },
            "store": { "size_in_bytes": all_store_bytes },
            "mappings": { "schema_persist_failures": all_schema_persist_failures },
            "dense_vector": {
                "value_count": all_dv_value_count,
                "off_heap": {
                    "total_size_bytes": all_dv_size,
                    "total_vec_size_bytes": all_dv_vec,
                    "total_veb_size_bytes": all_dv_veb,
                    "total_veq_size_bytes": all_dv_veq,
                    "total_vex_size_bytes": all_dv_vex,
                    "total_cenivf_size_bytes": all_dv_cenivf,
                    "total_clivf_size_bytes": all_dv_clivf,
                }
            }
        });
        return Json(json!({
            "_shards": { "total": 1, "successful": 1, "failed": 0 },
            "_all": { "primaries": all_primaries, "total": all_primaries },
            "indices": all_indices,
        }))
        .into_response();
    }
    let stats = match state.engine.index_stats(&index).await {
        Ok(s) => s,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    let doc_count = stats.doc_count;
    // #2140: `docs.deleted` is the pre-merge physical-minus-live count, not a
    // hard-coded 0. It also has to agree with `_cat/indices` and the
    // cluster/node rollups below.
    let deleted_doc_count = state
        .engine
        .get_index(&index)
        .map(|idx| idx.deleted_doc_count())
        .unwrap_or(0);
    // Real on-disk footprint: recursive byte sum of the index's data dir
    // (WAL + segments + everything else it persists).
    let store_size_bytes = state
        .engine
        .get_index(&index)
        .map(|idx| dir_size_bytes(idx.data_dir()))
        .unwrap_or(0);

    // Pull the live noop + request-cache counters from the index.
    let (noop_total, rc_hit, rc_miss, get_total, get_ms, get_exists, get_missing) =
        match state.engine.get_index(&index) {
            Ok(idx) => (
                idx.noop_update_total(),
                idx.request_cache_hit_count(),
                idx.request_cache_miss_count(),
                idx.metric_get_count
                    .load(std::sync::atomic::Ordering::Relaxed),
                idx.metric_get_total_ms
                    .load(std::sync::atomic::Ordering::Relaxed),
                idx.metric_get_exists_count
                    .load(std::sync::atomic::Ordering::Relaxed),
                idx.metric_get_missing_count
                    .load(std::sync::atomic::Ordering::Relaxed),
            ),
            Err(_) => (0, 0, 0, 0, 0, 0, 0),
        };
    let dense_vector_stats = per_index_dense_vector_stats(&state, &index);
    // XERJ extension (RC4 W2 item 17): live ANN/HNSW health — surfacing
    // `stale`/`rebuilding` makes a brute-force-degraded index observable
    // (pre-fix, permanent staleness after an unclean shutdown was
    // indistinguishable from a healthy index).
    let hnsw_stats = match state.engine.get_index(&index) {
        Ok(idx) => idx.hnsw_stats().await,
        Err(_) => json!({ "present": false }),
    };
    // XERJ extension (issue #392): the ingest-time SQ8 code stores. `fields`
    // is empty for indices with no `scalar8` mapping; per field it reports
    // the dimension, live slot count, coverage denominator, the
    // ready/serving gates, codebook refits, and the resident `codes_bytes`
    // — the flat u8 array the slot addressing is for, observable instead
    // of notional.
    let sq8_stats = match state.engine.get_index(&index) {
        Ok(idx) => json!({ "fields": idx.sq8_stats() }),
        Err(_) => json!({ "fields": {} }),
    };
    // Merge status + real segment count so benchmarks can verify the
    // index is merge-quiescent (merges.current == 0) before measuring.
    let (seg_count, merges_current) = state
        .engine
        .get_index(&index)
        .map(|idx| {
            (
                idx.store_snapshot().segments.len(),
                idx.is_merge_in_progress(),
            )
        })
        .unwrap_or((0, false));
    // XERJ extension (issue #204): dynamic-mapping evolution that could not be
    // written to `schema.json`. Non-zero means the on-disk mapping is behind
    // the live one and a restart will lose those fields. It is counted rather
    // than raised because schema evolution runs after the document has been
    // admitted — there is no caller left to fail — so a health check needs to
    // be able to READ it. This is that read: without it the counter existed and
    // nothing in the workspace looked at it.
    let schema_persist_failures = state
        .engine
        .get_index(&index)
        .map(|idx| idx.schema_persist_failures())
        .unwrap_or(0);
    let primaries = json!({
        "docs": { "count": doc_count, "deleted": deleted_doc_count },
        "store": { "size_in_bytes": store_size_bytes },
        "dense_vector": dense_vector_stats,
        "hnsw": hnsw_stats,
        "sq8": sq8_stats,
        "mappings": { "schema_persist_failures": schema_persist_failures },
        "indexing": {
            // Real cumulative indexing counters (RC4 W4 item 1): plumbed from
            // the per-index `metric_index_count` / `metric_index_total_ms`
            // atomics (index.rs), which every ingest path increments. Noop
            // updates early-return before `index_document`, so — as in ES —
            // they land in `noop_update_total` and NOT `index_total`.
            "index_total": stats.index_count,
            "index_time_in_millis": stats.index_total_ms,
            "index_current": 0,
            "index_failed": 0,
            "delete_total": 0,
            "delete_time_in_millis": 0,
            "delete_current": 0,
            "noop_update_total": noop_total,
            "is_throttled": false,
            "throttle_time_in_millis": 0,
        },
        "get": {
            "total": get_total,
            "time_in_millis": get_ms,
            "exists_total": get_exists,
            "exists_time_in_millis": 0,
            "missing_total": get_missing,
            "missing_time_in_millis": 0,
            "current": 0,
        },
        "search": {
            // Live open-context counts (RC4 blocker 11): scrolls are
            // engine-global (a context spans indices), reported here so
            // the TTL sweeper and 429 cap are observable. Previously
            // hardcoded 0.
            "open_contexts": state.engine.scrolls.len(),
            // Real cumulative search counters (RC4 W4 item 1): plumbed from the
            // per-index `metric_query_count` / `metric_query_total_ms` atomics
            // (index.rs), incremented on every `Index::search`. Previously
            // hardcoded 0 — `_stats.search.query_total` stayed 0 after real
            // searches.
            "query_total": stats.query_count,
            "query_time_in_millis": stats.query_total_ms,
            "query_current": 0,
            "fetch_total": 0,
            "fetch_time_in_millis": 0,
            "fetch_current": 0,
            "scroll_total": 0,
            "scroll_time_in_millis": 0,
            "scroll_current": state.engine.scrolls.len(),
            "suggest_total": 0,
            "suggest_time_in_millis": 0,
            "suggest_current": 0,
        },
        "fielddata": {
            "memory_size_in_bytes": 0,
            "evictions": 0,
        },
        "request_cache": {
            "memory_size_in_bytes": 0,
            "evictions": 0,
            "hit_count": rc_hit,
            "miss_count": rc_miss,
        },
        "refresh": {
            "total": 0,
            "total_time_in_millis": 0,
            "external_total": 0,
            "external_total_time_in_millis": 0,
            "listeners": 0,
        },
        "merges": {
            "current": if merges_current { 1 } else { 0 },
            "current_docs": 0,
            "current_size_in_bytes": 0,
        },
        "segments": {
            "count": seg_count,
            "memory_in_bytes": 0,
        },
    });
    // ES strips the `fielddata` breakdown from the cluster-wide `_all`
    // dense_vector stats but keeps it on the per-index entries (per
    // 220_dense_vector_node_bbq_disk_index_stats).
    let mut all_primaries = primaries.clone();
    if let Some(dv) = all_primaries
        .pointer_mut("/dense_vector/off_heap")
        .and_then(|v| v.as_object_mut())
    {
        dv.remove("fielddata");
    }
    Json(json!({
        "_shards": { "total": 1, "successful": 1, "failed": 0 },
        "_all": {
            "primaries": all_primaries,
            "total": all_primaries,
        },
        "indices": {
            &index: {
                "primaries": primaries,
                "total": primaries,
            }
        }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_aliases  — add/remove aliases in bulk
// GET  /_aliases  — list all aliases
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct AliasAction {
    pub add: Option<AliasActionParams>,
    pub remove: Option<AliasActionParams>,
}

#[derive(Debug, Deserialize)]
pub struct AliasActionParams {
    pub index: String,
    pub alias: String,
    /// `POST /_aliases` carries the same per-alias metadata `PUT
    /// /{index}/_alias/{name}` does. These used to be missing from this struct,
    /// so serde silently discarded them and a filtered alias created through
    /// the standard action API exposed every document.
    #[serde(default)]
    pub filter: Option<Value>,
    #[serde(default)]
    pub routing: Option<Value>,
    #[serde(default)]
    pub index_routing: Option<Value>,
    #[serde(default)]
    pub search_routing: Option<Value>,
    #[serde(default)]
    pub is_write_index: Option<bool>,
    #[serde(default)]
    pub is_hidden: Option<bool>,
}

/// The metadata object `PUT /{index}/_alias/{name}` and `POST /_aliases` both
/// persist for an alias. Empty means "no metadata" (and clears any stale
/// entry on a re-add).
fn alias_action_meta(add: &AliasActionParams) -> Value {
    let mut obj = serde_json::Map::new();
    if let Some(v) = &add.filter {
        obj.insert("filter".to_string(), v.clone());
    }
    if let Some(v) = &add.routing {
        obj.insert("routing".to_string(), v.clone());
    }
    if let Some(v) = &add.index_routing {
        obj.insert("index_routing".to_string(), v.clone());
    }
    if let Some(v) = &add.search_routing {
        obj.insert("search_routing".to_string(), v.clone());
    }
    if let Some(v) = add.is_write_index {
        obj.insert("is_write_index".to_string(), Value::Bool(v));
    }
    if let Some(v) = add.is_hidden {
        obj.insert("is_hidden".to_string(), Value::Bool(v));
    }
    Value::Object(obj)
}

/// Replace (or clear, for empty metadata) one alias's metadata on one index
/// and persist it. Clearing matters: re-adding an alias without a filter must
/// not leave the previous filter enforced.
fn store_alias_meta(state: &AppState, index: &str, alias: &str, meta: &Value) {
    let mut existing = state
        .engine
        .index_alias_metadata
        .get(index)
        .map(|v| v.clone())
        .unwrap_or_else(|| json!({}));
    if !existing.is_object() {
        existing = json!({});
    }
    if let Some(obj) = existing.as_object_mut() {
        if meta.as_object().map(|o| o.is_empty()).unwrap_or(true) {
            obj.remove(alias);
        } else {
            obj.insert(alias.to_string(), meta.clone());
        }
    }
    state
        .engine
        .index_alias_metadata
        .insert(index.to_string(), existing);
    state.engine.flush_alias_metadata();
}

/// Drop one alias's stored metadata after the alias itself was removed.
fn clear_alias_meta(state: &AppState, index: &str, alias: &str) {
    let Some(mut existing) = state
        .engine
        .index_alias_metadata
        .get(index)
        .map(|v| v.clone())
    else {
        return;
    };
    let Some(obj) = existing.as_object_mut() else {
        return;
    };
    if obj.remove(alias).is_none() {
        return;
    }
    state
        .engine
        .index_alias_metadata
        .insert(index.to_string(), existing);
    state.engine.flush_alias_metadata();
}

#[derive(Debug, Deserialize)]
pub struct AliasActionsBody {
    pub actions: Vec<AliasAction>,
}

/// Is this alias-action `index` field a pattern rather than one concrete name?
fn alias_target_is_pattern(spec: &str) -> bool {
    spec.split(',')
        .map(str::trim)
        .any(|p| p == "_all" || p.contains('*'))
}

pub async fn post_aliases(
    State(state): State<AppState>,
    Json(body): Json<AliasActionsBody>,
) -> impl IntoResponse {
    // An `add` whose `index` is a wildcard has to be expanded before the alias
    // can point anywhere. Adding the pattern TEXT as the alias target — which
    // is what the raw `add_alias` below used to do for every action — invents
    // an alias resolving to an index name that cannot exist, and answers
    // `acknowledged: true` for a write that did not happen. It read as a
    // successful alias creation to a caller that had just been told, by the
    // very same response, that it had reached the reserved namespace:
    // `POST /_aliases {"actions":[{"add":{"index":".xerj-memory-*", …}}]}`
    // returned 200 and left a dangling alias behind.
    //
    // ES resolves the wildcard and 404s `index_not_found_exception` when it
    // matches nothing; so do we. A concrete name is left exactly as it was —
    // ES lets an alias be attached to a name before the index exists, and
    // clients rely on that ordering.
    // Resolve every action first and refuse the whole request if any `add`
    // resolved to nothing, so a rejected batch leaves no half-applied aliases
    // behind.
    enum Resolved<'a> {
        Add(&'a AliasActionParams, Vec<String>),
        Remove(&'a AliasActionParams, Vec<String>),
    }
    let mut plan: Vec<Resolved> = Vec::with_capacity(body.actions.len());
    for action in &body.actions {
        if let Some(add) = &action.add {
            let targets = if alias_target_is_pattern(&add.index) {
                let expanded = resolve_index_selector(&state, &add.index).await;
                if expanded.is_empty() {
                    let e = xerj_common::XerjError::index_not_found(&add.index);
                    return ApiError::new(e).into_response();
                }
                expanded
            } else {
                vec![add.index.clone()]
            };
            plan.push(Resolved::Add(add, targets));
        }
        if let Some(remove) = &action.remove {
            // A `remove` that matches nothing removes nothing — idempotent,
            // and it leaves no junk behind, so it is not refused.
            let targets = if alias_target_is_pattern(&remove.index) {
                resolve_index_selector(&state, &remove.index).await
            } else {
                vec![remove.index.clone()]
            };
            plan.push(Resolved::Remove(remove, targets));
        }
    }
    for step in &plan {
        match step {
            Resolved::Add(add, targets) => {
                let meta = alias_action_meta(add);
                if let Some(reason) = alias_value_type_error(&add.alias, &meta) {
                    return es_bad_request("illegal_argument_exception", &reason, None);
                }
                for target in targets {
                    if let Err(error) = state.engine.add_alias(&add.alias, target) {
                        return ApiError::new(xerj_common::XerjError::from(error)).into_response();
                    }
                    store_alias_meta(&state, target, &add.alias, &meta);
                }
            }
            Resolved::Remove(remove, targets) => {
                for target in targets {
                    if let Err(error) = state.engine.remove_alias(&remove.alias, target) {
                        return ApiError::new(xerj_common::XerjError::from(error)).into_response();
                    }
                    clear_alias_meta(&state, target, &remove.alias);
                }
            }
        }
    }
    Json(json!({ "acknowledged": true })).into_response()
}

pub async fn get_aliases(State(state): State<AppState>) -> impl IntoResponse {
    let mut result = serde_json::Map::new();
    // ES returns an entry for EVERY index, with an empty aliases map when the
    // index has none. Enumerate all indices, then fold in any aliases that
    // point at each (with per-alias metadata captured at create-time).
    for info in state.engine.list_indices().await {
        let mut aliases_map = serde_json::Map::new();
        for entry in state.engine.aliases.iter() {
            if entry.value().contains(&info.name) {
                aliases_map.insert(
                    entry.key().clone(),
                    alias_meta_for(&state, &info.name, entry.key()),
                );
            }
        }
        result.insert(info.name.clone(), json!({ "aliases": aliases_map }));
    }
    Json(Value::Object(result)).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT /{index}/_alias/{alias}
// DELETE /{index}/_alias/{alias}
// ─────────────────────────────────────────────────────────────────────────────

/// Resolve an index spec (single name, comma list, wildcard, `_all`, `*`)
/// into the concrete set of existing index names, in stable order.
/// The single index-selector resolver (#451). Every endpoint that used to
/// call `Engine::get_index` directly — collapsing an alias to `aliased.first()`
/// (class B) — or had no alias branch at all (class A) should resolve through
/// here instead, so all sites agree on what a selector means.
///
/// Returns each concrete member the selector names (an alias expands to ALL its
/// members, #433) paired with its `Arc<Index>`, plus any alias `filter` clauses
/// to AND into a query — the same shape `resolve_by_query_targets` uses on the
/// write path (#450). A missing name propagates `index_not_found`, matching
/// ES's default `ignore_unavailable=false`.
async fn resolve_selector_with_filters(
    state: &AppState,
    spec: &str,
) -> std::result::Result<
    (
        Vec<(String, std::sync::Arc<xerj_engine::Index>)>,
        Vec<Value>,
    ),
    xerj_common::XerjError,
> {
    let names = resolve_index_selector(state, spec).await;
    let mut alias_filters: Vec<Value> = Vec::new();
    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if let Some(entry) = state.engine.aliases.get(part) {
            for backing in entry.value().iter() {
                if let Some(meta) = state.engine.index_alias_metadata.get(backing) {
                    if let Some(filter) = meta.get(part).and_then(|v| v.get("filter")).cloned() {
                        alias_filters.push(filter);
                    }
                }
            }
        }
    }
    let mut out = Vec::with_capacity(names.len());
    for name in &names {
        out.push((
            name.clone(),
            state
                .engine
                .get_index(name)
                .map_err(xerj_common::XerjError::from)?,
        ));
    }
    Ok((out, alias_filters))
}

async fn resolve_index_selector(state: &AppState, spec: &str) -> Vec<String> {
    let mut all: Option<Vec<String>> = None;
    let mut out: Vec<String> = Vec::new();
    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if part == "_all" || part == "*" {
            let all = all.get_or_insert_with(|| state.engine.index_name_list());
            for n in all.iter() {
                if !out.contains(n) {
                    out.push(n.clone());
                }
            }
            continue;
        }
        if part.contains('*') {
            let all = all.get_or_insert_with(|| state.engine.index_name_list());
            for n in all.iter() {
                if glob_match_simple(part, n) && !out.contains(n) {
                    out.push(n.clone());
                }
            }
            continue;
        }
        // Exact name — could be a real index, OR an alias pointing at one
        // (real ES/OpenSearch accept both interchangeably on every
        // single-index endpoint: GET/_mapping/_settings/etc.). Resolve to
        // the underlying real index name(s) so callers keying their
        // response by `name` (e.g. get_mapping's `index_mappings` lookup)
        // hit the actually-stored entry instead of silently missing and
        // falling back to a schema-derived reconstruction that drops
        // fields like mappings._meta. Falls back to the literal name
        // (include whether or not it exists; the caller decides) when it
        // isn't a known alias either.
        if let Some(targets) = state.engine.aliases.get(part) {
            for n in targets.value() {
                if !out.contains(n) {
                    out.push(n.clone());
                }
            }
        } else if !out.contains(&part.to_string()) {
            out.push(part.to_string());
        }
    }
    out
}

/// Resolve an index spec to the `Index` handles it actually matches, for the
/// admin endpoints that act on EVERY matching index (`_refresh`,
/// `_forcemerge`, `_cache/clear`, `_close`, `_open`,
/// `_admin/segments/fsck`) — as opposed to `_search`, which has its own much
/// larger resolution+merge path (closed-index rules, PIT, per-hit scoring)
/// that doesn't belong here.
///
/// These endpoints previously called `state.engine.get_index(&index)`
/// directly on the raw path segment, so a wildcard/comma spec just 404'd
/// (or, worse, `refresh_index`/`cat_count` swallowed the error and silently
/// reported success/zero — see the fix commit for details) instead of
/// resolving to the indices it matched, the way ES itself behaves.
///
/// Mirrors ES's `allow_no_indices` default: a literal name that doesn't
/// exist is an error, but a wildcard/`_all`/comma-list that matches nothing
/// is not — it's a legitimate (if unhelpful) query result. Order is stable
/// (`resolve_index_selector`'s enumeration order) so multi-index responses
/// aren't a source of test flakiness.
async fn resolve_indices_for_op(
    state: &AppState,
    spec: &str,
) -> Result<Vec<(String, std::sync::Arc<xerj_engine::Index>)>, xerj_common::XerjError> {
    let is_selector = spec == "_all" || spec.contains('*') || spec.contains(',');
    let mut all: Option<Vec<String>> = None;
    let mut names: Vec<String> = Vec::new();
    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if part == "_all" || part.contains('*') {
            let all = all.get_or_insert_with(|| state.engine.index_name_list());
            for n in all.iter() {
                // ES excludes hidden (dot-prefixed) indices from default
                // wildcard/_all expansion — `POST /*/_close` must never
                // sweep in `.xerj_users`-class system indices. A pattern
                // that itself starts with a dot opts back in, matching
                // ES's hidden-index addressing.
                if n.starts_with('.') && !part.starts_with('.') {
                    continue;
                }
                let matches = part == "_all" || part == "*" || glob_match_simple(part, n);
                if matches && !names.contains(n) {
                    names.push(n.clone());
                }
            }
        } else {
            // A concrete name may be a real index OR an alias. An index of
            // that name wins, matching ES, where an alias may not share a
            // name with an index.
            if state.engine.has_open_index(part) {
                if !names.iter().any(|n| n == part) {
                    names.push(part.to_string());
                }
            } else if let Some(members) = state.engine.aliases.get(part) {
                // This branch did not exist, so an alias was simply "not an
                // index" and the whole request 404'd. `POST /tri/_refresh`
                // over a three-member alias returned index_not_found while
                // `POST /idx-a/_refresh` worked — measured on _refresh,
                // _forcemerge, _cache/clear and _terms_enum. An alias is a
                // valid index selector for every one of these in ES.
                //
                // Expanding to ALL members, not `aliased.first()`: a
                // maintenance op that silently addressed one member of a
                // multi-index alias is the same defect class as #450 on the
                // read side, and `_refresh` reaching only one member makes a
                // subsequent search non-deterministic in a way nothing in the
                // response admits.
                for m in members.value() {
                    if !names.iter().any(|n| n == m) {
                        names.push(m.clone());
                    }
                }
            } else {
                // ES's default `ignore_unavailable=false` 404s the whole
                // request on a missing name instead of silently dropping it —
                // `POST /real,typo/_refresh` must not report success.
                return Err(xerj_common::XerjError::index_not_found(part));
            }
        }
    }
    let handles: Vec<(String, std::sync::Arc<xerj_engine::Index>)> = names
        .into_iter()
        .filter_map(|n| {
            let h = state.engine.get_index(&n).ok()?;
            Some((n, h))
        })
        .collect();
    if handles.is_empty() && !is_selector {
        return Err(xerj_common::XerjError::index_not_found(spec));
    }
    Ok(handles)
}

pub async fn put_alias(
    State(state): State<AppState>,
    Path((index, alias)): Path<(String, String)>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    // ES's alias-name and body checks (`indices.put_alias/10_basic.yml`),
    // before anything is attached.
    const ALIAS_FORBIDDEN: &[char] = &[' ', '"', '*', '\\', '<', '|', ',', '>', '/', '?'];
    if alias.contains(ALIAS_FORBIDDEN) {
        return es_bad_request(
            "invalid_alias_name_exception",
            &format!(
                "Invalid alias name [{alias}]: must not contain the following characters \
                 [ , \", *, \\, <, |, ,, >, /, ?]"
            ),
            None,
        );
    }
    // A concrete index of that name (not this alias already existing —
    // re-putting an alias to change its filter or routing stays allowed).
    if !state.engine.aliases.contains_key(&alias) && state.engine.get_index(&alias).is_ok() {
        return es_bad_request(
            "invalid_alias_name_exception",
            &format!(
                "Invalid alias name [{alias}]: an index or data stream exists with the same name \
                 as the alias"
            ),
            None,
        );
    }
    if let Some(fields) = body.0.as_ref().and_then(Value::as_object) {
        const ALIAS_FIELDS: &[&str] = &[
            "filter",
            "routing",
            "index_routing",
            "search_routing",
            "is_write_index",
            "is_hidden",
        ];
        for (field, v) in fields {
            if !ALIAS_FIELDS.contains(&field.as_str()) {
                return es_bad_request(
                    "illegal_argument_exception",
                    &format!("[{alias}] Unsupported field [{field}]"),
                    None,
                );
            }
            if field.ends_with("routing") && (v.is_array() || v.is_object()) {
                let token = if v.is_array() {
                    "START_ARRAY"
                } else {
                    "START_OBJECT"
                };
                return es_bad_request(
                    "illegal_argument_exception",
                    &format!(
                        "[{alias}] failed to parse field [{field}]: Unexpected token [{token}]"
                    ),
                    None,
                );
            }
        }
        if let Some(reason) = alias_value_type_error(&alias, &Value::Object(fields.clone())) {
            return es_bad_request("illegal_argument_exception", &reason, None);
        }
    }
    let targets = resolve_index_selector(&state, &index).await;
    let alias_meta: Value = body
        .0
        .filter(|v| v.as_object().map(|o| !o.is_empty()).unwrap_or(false))
        .unwrap_or(json!({}));

    let attach = |idx_name: &str| -> xerj_engine::Result<()> {
        state.engine.add_alias(&alias, idx_name)?;
        // Re-putting an alias replaces its definition: an empty body clears a
        // previous filter instead of leaving it enforced.
        store_alias_meta(&state, idx_name, &alias, &alias_meta);
        Ok(())
    };

    if targets.is_empty() {
        // `resolve_index_selector` only ever comes back empty for a wildcard
        // that matched nothing — a concrete name always resolves to itself.
        // Attaching the alias to the pattern text in that case (what this used
        // to do) fabricates an alias pointing at an index name that cannot
        // exist and reports `acknowledged: true` for a write that did not
        // happen; `PUT /.xerj-memory-*/_alias/X` was the case that made it
        // look like the reserved namespace had just been aliased. Refuse, the
        // way ES does.
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }
    for idx in &targets {
        if let Err(error) = attach(idx) {
            return ApiError::new(xerj_common::XerjError::from(error)).into_response();
        }
    }
    Json(json!({ "acknowledged": true })).into_response()
}

pub async fn delete_alias(
    State(state): State<AppState>,
    Path((index, alias)): Path<(String, String)>,
) -> impl IntoResponse {
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        if let Err(error) = state.engine.remove_alias(&alias, &index) {
            return ApiError::new(xerj_common::XerjError::from(error)).into_response();
        }
        clear_alias_meta(&state, &index, &alias);
    } else {
        for idx in &targets {
            if let Err(error) = state.engine.remove_alias(&alias, idx) {
                return ApiError::new(xerj_common::XerjError::from(error)).into_response();
            }
            clear_alias_meta(&state, idx, &alias);
        }
    }
    Json(json!({ "acknowledged": true })).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT    /_index_template/{name}  — create/update template
// GET    /_index_template/{name}  — get template
// DELETE /_index_template/{name}  — delete template
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct IndexTemplateBody {
    #[serde(default)]
    pub index_patterns: Vec<String>,
    #[serde(default)]
    pub priority: Option<i32>,
    #[serde(default)]
    pub template: Option<IndexTemplateInner>,
    // Top-level settings/mappings (legacy style)
    #[serde(default)]
    pub settings: Option<Value>,
    #[serde(default)]
    pub mappings: Option<Value>,
}

#[derive(Debug, Deserialize)]
pub struct IndexTemplateInner {
    #[serde(default)]
    pub settings: Option<Value>,
    #[serde(default)]
    pub mappings: Option<Value>,
}

pub async fn put_index_template(
    State(state): State<AppState>,
    Path(name): Path<String>,
    Json(body): Json<IndexTemplateBody>,
) -> impl IntoResponse {
    let settings = body
        .template
        .as_ref()
        .and_then(|t| t.settings.clone())
        .or(body.settings.clone())
        .unwrap_or(json!({}));
    let mappings = body
        .template
        .as_ref()
        .and_then(|t| t.mappings.clone())
        .or(body.mappings.clone())
        .unwrap_or(json!({}));

    let tmpl = xerj_engine::engine::IndexTemplate {
        index_patterns: body.index_patterns,
        settings,
        mappings,
        priority: body.priority.unwrap_or(0),
    };
    match state.engine.put_index_template(name, tmpl) {
        Ok(()) => Json(json!({ "acknowledged": true })).into_response(),
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

pub async fn get_index_template(
    State(state): State<AppState>,
    Path(name): Path<String>,
) -> impl IntoResponse {
    if name == "*" || name == "_all" {
        // Return all templates.
        let mut templates = serde_json::Map::new();
        for entry in state.engine.templates.iter() {
            let t = entry.value();
            templates.insert(
                entry.key().clone(),
                json!({
                    "name": entry.key().clone(),
                    "index_template": {
                        "index_patterns": t.index_patterns,
                        "priority": t.priority,
                        "template": {
                            "settings": t.settings,
                            "mappings": t.mappings,
                        }
                    }
                }),
            );
        }
        let index_templates: Vec<Value> = templates.values().cloned().collect();
        return Json(json!({ "index_templates": index_templates })).into_response();
    }

    match state.engine.templates.get(&name) {
        Some(t) => {
            let resp = json!({
                "index_templates": [{
                    "name": name,
                    "index_template": {
                        "index_patterns": t.index_patterns,
                        "priority": t.priority,
                        "template": {
                            "settings": t.settings,
                            "mappings": t.mappings,
                        }
                    }
                }]
            });
            Json(resp).into_response()
        }
        None => {
            let e =
                xerj_common::XerjError::index_not_found(format!("index template [{name}] missing"));
            ApiError::new(e).into_response()
        }
    }
}

pub async fn delete_index_template(
    State(state): State<AppState>,
    Path(name): Path<String>,
) -> impl IntoResponse {
    match state.engine.delete_index_template(&name) {
        Ok(true) => Json(json!({ "acknowledged": true })).into_response(),
        Ok(false) => {
            let e =
                xerj_common::XerjError::index_not_found(format!("index template [{name}] missing"));
            ApiError::new(e).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_search?scroll=1m  — initial scroll search
// POST /_search/scroll              — fetch next scroll page
// DELETE /_search/scroll            — clear scroll
// ─────────────────────────────────────────────────────────────────────────────

/// An integer `index.<key>` setting in any of the three spellings a settings
/// document can carry it (see [`index_max_result_window`]).
fn index_int_setting(state: &AppState, ix: &str, key: &str) -> Option<u64> {
    let s = state.engine.index_settings.get(ix).map(|v| v.clone())?;
    let as_int = |v: &Value| {
        v.as_u64()
            .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
    };
    let dotted = format!("index.{key}");
    s.pointer(&format!("/index/{key}"))
        .and_then(as_int)
        .or_else(|| s.get("index").and_then(|i| i.get(&dotted)).and_then(as_int))
        .or_else(|| s.get(&dotted).and_then(as_int))
}

/// The per-index request limits Elasticsearch checks before running a search,
/// with its messages (`search/30_limits.yml`). Each was previously either
/// unchecked (an HTTP 200) or refused deeper with a different message:
///
/// * `from + size` over `index.max_result_window` (default 10 000), or for a
///   scroll the batch `size` — ES's `Result window is too large` / `Batch size
///   is too large`. The engine's own window check stays as a backstop.
/// * a rescore `window_size` over `index.max_rescore_window` (defaults to the
///   result window);
/// * more `docvalue_fields` than `index.max_docvalue_fields_search` (100);
/// * a `regexp`, `prefix` or `/regex/` `query_string` longer than
///   `index.max_regex_length` (1000 characters).
fn find_index_request_limit_violation(
    state: &AppState,
    ix: &str,
    body: &EsSearchBody,
    from: usize,
    size: usize,
    is_scroll: bool,
) -> Option<String> {
    let max_window = index_max_result_window(state, ix);
    let window = from.saturating_add(size);
    if window > max_window {
        return Some(if is_scroll {
            format!(
                "Batch size is too large, size must be less than or equal to: [{max_window}] but \
                 was [{window}]. Scroll batch sizes cost as much memory as result windows so \
                 they are controlled by the [index.max_result_window] index level setting."
            )
        } else {
            format!(
                "Result window is too large, from + size must be less than or equal to: \
                 [{max_window}] but was [{window}]. See the scroll api for a more efficient way \
                 to request large data sets. This limit can be set by changing the \
                 [index.max_result_window] index level setting."
            )
        });
    }

    let max_rescore = index_int_setting(state, ix, "max_rescore_window")
        .map(|v| v as usize)
        .unwrap_or(max_window);
    let rescores: Vec<&Value> = match body.rescore.as_ref() {
        Some(Value::Array(items)) => items.iter().collect(),
        Some(item @ Value::Object(_)) => vec![item],
        _ => Vec::new(),
    };
    for rescore in rescores {
        if let Some(w) = rescore.get("window_size").and_then(Value::as_u64) {
            if w as usize > max_rescore {
                return Some(format!(
                    "Rescore window [{w}] is too large. It must be less than [{max_rescore}]. \
                     This prevents allocating massive heaps for storing the results to be \
                     rescored. This limit can be set by changing the [index.max_rescore_window] \
                     index level setting."
                ));
            }
        }
    }

    let max_dv = index_int_setting(state, ix, "max_docvalue_fields_search").unwrap_or(100);
    if let Some(Value::Array(fields)) = body.docvalue_fields.as_ref() {
        if fields.len() as u64 > max_dv {
            return Some(format!(
                "Trying to retrieve too many docvalue_fields. Must be less than or equal to: \
                 [{max_dv}] but was [{}]. This limit can be set by changing the \
                 [index.max_docvalue_fields_search] index level setting.",
                fields.len()
            ));
        }
    }

    let max_regex = index_int_setting(state, ix, "max_regex_length").unwrap_or(1000) as usize;
    body.query
        .as_ref()
        .and_then(|q| find_overlong_pattern(q, max_regex))
}

/// The first `regexp`, `prefix` or `/regex/` `query_string` in `query` whose
/// pattern is longer than `max` characters, as ES's message.
fn find_overlong_pattern(query: &Value, max: usize) -> Option<String> {
    let too_long = |kind: &str, len: usize, query_name: &str| {
        format!(
            "The length of {kind} [{len}] used in the {query_name} Query request has exceeded the \
             allowed maximum of [{max}]. This maximum can be set by changing the \
             [index.max_regex_length] index level setting."
        )
    };
    /// `{field: "pattern"}` or `{field: {"value": "pattern"}}`.
    fn field_patterns(clause: &Value) -> Vec<&str> {
        clause
            .as_object()
            .map(|o| {
                o.values()
                    .filter_map(|v| {
                        v.as_str()
                            .or_else(|| v.get("value").and_then(Value::as_str))
                    })
                    .collect()
            })
            .unwrap_or_default()
    }
    match query {
        Value::Object(o) => {
            for (key, value) in o {
                match key.as_str() {
                    "regexp" => {
                        for p in field_patterns(value) {
                            let len = p.chars().count();
                            if len > max {
                                return Some(too_long("regex", len, "Regexp"));
                            }
                        }
                    }
                    "prefix" => {
                        for p in field_patterns(value) {
                            let len = p.chars().count();
                            if len > max {
                                return Some(too_long("prefix", len, "Prefix"));
                            }
                        }
                    }
                    "query_string" => {
                        let text = value.get("query").and_then(Value::as_str).unwrap_or("");
                        let t = text.trim();
                        if t.len() >= 2 && t.starts_with('/') && t.ends_with('/') {
                            let len = t[1..t.len() - 1].chars().count();
                            if len > max {
                                return Some(too_long("regex", len, "Regexp"));
                            }
                        }
                    }
                    _ => {}
                }
                if let Some(reason) = find_overlong_pattern(value, max) {
                    return Some(reason);
                }
            }
            None
        }
        Value::Array(items) => items.iter().find_map(|v| find_overlong_pattern(v, max)),
        _ => None,
    }
}

/// An index's `index.max_result_window`, in any of the three spellings a
/// settings document can carry it (nested `index.max_result_window`, a flat
/// dotted key under `index`, or a top-level dotted key), defaulting to the
/// node's `limits.max_result_window` (10,000 by default, the ES default) like
/// the engine's own check. Shared by the `ids` clause check, the
/// `rerank.window` check and [`find_index_request_limit_violation`].
fn index_max_result_window(state: &AppState, ix: &str) -> usize {
    state
        .engine
        .index_settings
        .get(ix)
        .map(|v| v.clone())
        .and_then(|s| {
            let as_int = |v: &Value| {
                v.as_u64()
                    .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
            };
            s.pointer("/index/max_result_window")
                .and_then(as_int)
                .or_else(|| {
                    s.get("index")
                        .and_then(|i| i.get("index.max_result_window"))
                        .and_then(as_int)
                })
                .or_else(|| s.get("index.max_result_window").and_then(as_int))
        })
        .map(|v| v as usize)
        .unwrap_or(state.engine.config().limits.max_result_window)
}

#[derive(Debug, Deserialize, Default)]
pub struct ScrollQueryParams {
    pub scroll: Option<String>,
}

pub async fn search_with_scroll(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<ScrollQueryParams>,
    body: OptionalJson<EsSearchBody>,
) -> impl IntoResponse {
    let started = Instant::now();
    let body = body.into_or_default();

    // A scroll streams the engine's order; `rerank` cannot apply to it, and
    // this handler used to rebuild the body with `rerank: None` — dropping it.
    // The `judge` stage reorders too, so the same refusal applies.
    if body.rerank.is_some() || body.judge.is_some() {
        return (
            StatusCode::BAD_REQUEST,
            Json(if body.rerank.is_some() {
                crate::rerank_stage::unsupported_on("_search_scroll")
            } else {
                crate::judge_stage::unsupported_on("_search_scroll")
            }),
        )
            .into_response();
    }

    // RC4 blocker 11: same open-scroll cap as the `?scroll=` path on
    // `_search` — checked up front so the full-corpus snapshot below is
    // never even computed for a request that cannot get a context.
    if params.scroll.is_some() {
        state.engine.sweep_expired_scrolls();
        let scroll_cap = state.config.search_context.max_open_scrolls;
        if state.engine.scrolls.len() >= scroll_cap {
            return too_many_scroll_contexts(scroll_cap);
        }
    }

    // Resolve aliases and expand comma-separated indices.
    let index_names: Vec<String> = index
        .split(',')
        .flat_map(|n| state.engine.resolve_alias(n.trim()))
        .collect();

    let aggs_value = body.aggs.clone().or_else(|| body.aggregations.clone());

    // For scroll: snapshot up to the scroll window in one search. A result
    // set that does not fit is rejected loudly below (issue #198) rather
    // than silently truncated.
    let scroll_body = EsSearchBody {
        size: SCROLL_SNAPSHOT_MAX_HITS,
        from: 0,
        query: body.query.clone(),
        sort: body.sort.clone(),
        source: body.source.clone(),
        aggs: body.aggs.clone(),
        aggregations: body.aggregations.clone(),
        highlight: body.highlight.clone(),
        // Scroll requires exact totals for the truncation check (and ES
        // rejects disabling track_total_hits in a scroll context anyway).
        track_total_hits: if params.scroll.is_some() {
            Some(Value::Bool(true))
        } else {
            body.track_total_hits.clone()
        },
        suggest: None,
        explain: body.explain,
        script_fields: body.script_fields.clone(),
        fields: body.fields.clone(),
        search_after: None,
        profile: false,
        stored_fields: None,
        docvalue_fields: None,
        inner_hits: None,
        collapse: None,
        knn: None,
        runtime_mappings: None,
        rescore: None,
        track_scores: None,
        indices_boost: None,
        min_score: None,
        seq_no_primary_term: body.seq_no_primary_term,
        version: body.version,
        slice: body.slice.clone(),
        pit: body.pit.clone(),
        timeout: body.timeout.clone(),
        rerank: None,
        judge: None,
        // #943: forward so the post_filter-beside-hybrid rejection in
        // `build_search_request` covers scroll requests too.
        post_filter: body.post_filter.clone(),
    };
    // page_size: what the caller requested (or default 10)
    let page_size = body.size;

    let search_req = match build_search_request(&scroll_body, aggs_value.clone()) {
        Ok(r) => r,
        Err(e) => return ApiError::new(e).into_response(),
    };

    // Execute search across all indices and collect ALL hits.
    let mut all_hits: Vec<(String, xerj_query::executor::Hit)> = Vec::new();
    let mut total_count: u64 = 0;
    // #2305: alias expansion on this route (wildcards are not expanded here)
    // must not 400 every member because one lacks the semantic field.
    let mut semantic_skips = ExpandedSemanticSkips::default();
    let search_node = state.engine.node_id.clone();

    for idx_name in &index_names {
        let idx = match state.engine.get_index(idx_name) {
            Ok(i) => i,
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        };

        // Fetch up to the scroll window per index.
        let mut full_req = search_req.clone();
        full_req.size = SCROLL_SNAPSHOT_MAX_HITS;
        full_req.from = 0;

        semantic_skips.note_attempt();
        match idx.search(&full_req).await {
            Ok(result) => {
                if let Some(reason) = &result.script_failure {
                    return script_limit_response(reason);
                }
                total_count += result.total.value;
                for hit in result.hits {
                    all_hits.push((idx_name.clone(), hit));
                }
            }
            Err(e) => {
                let err = xerj_common::XerjError::from(e);
                match semantic_skips.take_skippable(&index, idx_name, search_node.as_str(), err) {
                    Ok(()) => continue,
                    Err(err) => return ApiError::new(err).into_response(),
                }
            }
        }
    }
    if let Some(err) = semantic_skips.failure_if_every_index_skipped() {
        return ApiError::new(err).into_response();
    }

    let took_ms = started.elapsed().as_millis() as u64;

    // If scroll param present, store context and return first page.
    if params.scroll.is_some() {
        // Issue #198 (and #405: this route used to flag truncation only
        // when a SINGLE index alone exceeded the per-index snapshot fetch
        // — `full_req.size` is `SCROLL_SNAPSHOT_MAX_HITS` PER index, so an
        // N-index request could materialise up to
        // `N * SCROLL_SNAPSHOT_MAX_HITS` hits into one context and never
        // trip that check, even though `POST /{index}/_search?scroll=`
        // (search_impl) rejects the identical summed total. `total_count`
        // above is already the exact sum across every index — compare it
        // against the cap directly, matching search_impl's check
        // (es_compat.rs, `is_scroll_request` block) exactly, so a request
        // whose combined result set cannot fit the snapshot is refused
        // loudly regardless of which route opened it.
        if total_count > SCROLL_SNAPSHOT_MAX_HITS as u64 {
            return scroll_window_exceeded(total_count, SCROLL_SNAPSHOT_MAX_HITS);
        }
        let scroll_id = Uuid::new_v4().to_string();
        // Extract just the hits from the pairs.
        // Index name stays paired with its hit (#414).
        let hits_only: Vec<(String, xerj_query::executor::Hit)> = all_hits.clone();

        // Control flags for meta-field emission — mirrors `search_impl`'s
        // `emit_seq_no`/`emit_version` (es_compat.rs ~11349).
        let emit_seq_no = body.seq_no_primary_term.unwrap_or(false);
        let emit_version = body.version.unwrap_or(false);

        // Return first page. `_seq_no`/`_version` are read from the hit
        // itself — resolved at construction time in the engine, from the
        // same read as `_source` — not hardcoded, and omitted entirely
        // when not requested (#428/#440).
        // #659: bring THIS route's first page into `_source` suppression parity
        // with search_impl. The request-level part (`_source:false`, or
        // `stored_fields` implying suppression when `_source` is unspecified) is
        // constant across the snapshot; the mapping `_source.enabled:false` part
        // is per-hit (applied in the hits_json build below). The continuation
        // then matches via `mapping_source_check: true` on the ctx.
        let (suppress_source_for_stored, _) = body
            .stored_fields
            .as_ref()
            .map(parse_stored_fields)
            .unwrap_or((false, vec![]));
        let scroll_request_source_disabled = matches!(body.source, Some(Value::Bool(false)))
            || (suppress_source_for_stored && body.source.is_none());
        let first_page: Vec<EsHit> = all_hits
            .iter()
            .take(page_size)
            .map(|(idx_name, h)| {
                let (version, seq_no, primary_term) =
                    resolve_hit_versioning(h.seq_no, h.version, emit_seq_no, emit_version);
                EsHit {
                    index: idx_name.clone(),
                    id: h.id.clone(),
                    score: Some(h.score as f64),
                    version,
                    seq_no,
                    primary_term,
                    source: if h.source.is_null() {
                        None
                    } else {
                        Some(h.source.clone())
                    },
                    fields: passage_fields(h),
                    sort: if h.sort.is_empty() {
                        None
                    } else {
                        Some(h.sort.clone())
                    },
                    highlight: h.highlight.clone(),
                    explanation: None,
                    inner_hits: None,
                    matched_queries: if h.matched_queries.is_empty() {
                        Value::Null
                    } else {
                        Value::Array(
                            h.matched_queries
                                .iter()
                                .cloned()
                                .map(Value::String)
                                .collect(),
                        )
                    },
                    ignored: None,
                    ignored_field_values: None,
                    p_relevant: None,
                }
            })
            .collect();

        // TTL (RC4 blocker 11) — mirrors the `_search?scroll=` site.
        let sc_cfg = &state.config.search_context;
        let keep_alive_secs = params
            .scroll
            .as_deref()
            .and_then(parse_keep_alive_to_secs)
            .unwrap_or(sc_cfg.scroll_default_keep_alive_secs)
            .min(sc_cfg.scroll_max_keep_alive_secs);
        let keep_alive = std::time::Duration::from_secs(keep_alive_secs);
        let now = Instant::now();
        let ctx = xerj_engine::engine::ScrollContext {
            index: index.clone(),
            hits: hits_only,
            position: page_size,
            page_size,
            seq_no_primary_term: emit_seq_no,
            version: emit_version,
            source_disabled: scroll_request_source_disabled,
            // #659: this route's first page now applies the per-hit mapping
            // `_source.enabled:false` suppression (below), so the continuation
            // must too — matching search_impl and keeping the route
            // self-consistent page to page.
            mapping_source_check: true,
            created: now,
            keep_alive,
            expires_at: now + keep_alive,
        };
        state.engine.scrolls.insert(scroll_id.clone(), ctx);

        // #630: emit `_version`/`_seq_no`/`_primary_term` when requested. The
        // `EsHit` carried them (gated on the request flags), but this hand-built
        // first-page map previously dropped them, unlike the continuation page
        // (`scroll_page_response`, #428) and the `_search?scroll=` first page
        // (`search_impl`). `_source` emission is unchanged (always present, null
        // when absent). The `disable_sequence_numbers` sentinel is then applied
        // exactly as the continuation does (#440), so both pages agree.
        let mut hits_json: Vec<Value> = first_page
            .iter()
            .map(|h| {
                let mut o = serde_json::Map::new();
                o.insert("_index".to_string(), Value::String(h.index.clone()));
                o.insert("_id".to_string(), Value::String(h.id.clone()));
                o.insert(
                    "_score".to_string(),
                    match h.score {
                        Some(s) => json!(s),
                        None => Value::Null,
                    },
                );
                if let Some(v) = h.version {
                    o.insert("_version".to_string(), json!(v));
                }
                if let Some(sn) = h.seq_no {
                    o.insert("_seq_no".to_string(), json!(sn));
                }
                if let Some(pt) = h.primary_term {
                    o.insert("_primary_term".to_string(), json!(pt));
                }
                // #659: omit `_source` under the same conditions search_impl
                // does — request-level (`_source:false`/stored_fields-implied) or
                // the per-hit mapping `_source.enabled:false`. Otherwise emit the
                // (possibly null) source as before.
                let suppress =
                    scroll_request_source_disabled || mapping_source_disabled(&state, &h.index);
                if !suppress {
                    o.insert(
                        "_source".to_string(),
                        match &h.source {
                            Some(src) => src.clone(),
                            None => Value::Null,
                        },
                    );
                }
                if let Some(fields) = &h.fields {
                    o.insert(
                        "fields".to_string(),
                        serde_json::to_value(fields).unwrap_or(Value::Null),
                    );
                }
                Value::Object(o)
            })
            .collect();
        apply_disable_seqno_sentinel(&state, &mut hits_json);

        let resp = json!({
            "_scroll_id": scroll_id,
            "took": took_ms,
            "timed_out": false,
            "_shards": { "total": 1, "successful": 1, "skipped": 0, "failed": 0 },
            "hits": {
                "total": { "value": total_count, "relation": "eq" },
                "max_score": first_page.first().and_then(|h| h.score),
                "hits": hits_json
            }
        });
        return Json(resp).into_response();
    }

    // No scroll param — behave like normal search with from/size applied.
    let from = body.from;
    let size = body.size;
    let page: Vec<EsHit> = all_hits
        .iter()
        .skip(from)
        .take(size)
        .map(|(idx_name, h)| EsHit {
            index: idx_name.clone(),
            id: h.id.clone(),
            score: Some(h.score as f64),
            version: Some(1),
            seq_no: Some(0),
            primary_term: Some(1),
            source: if h.source.is_null() {
                None
            } else {
                Some(h.source.clone())
            },
            fields: passage_fields(h),
            sort: if h.sort.is_empty() {
                None
            } else {
                Some(h.sort.clone())
            },
            highlight: h.highlight.clone(),
            explanation: None,
            inner_hits: None,
            matched_queries: if h.matched_queries.is_empty() {
                Value::Null
            } else {
                Value::Array(
                    h.matched_queries
                        .iter()
                        .cloned()
                        .map(Value::String)
                        .collect(),
                )
            },
            ignored: None,
            ignored_field_values: None,
            p_relevant: None,
        })
        .collect();

    let max_score = page.first().and_then(|h| h.score);
    let resp = EsSearchResponse {
        took: took_ms,
        timed_out: false,
        shards: crate::responses::EsShards::search_success(),
        hits: EsHits {
            total: EsHitsTotal {
                value: total_count,
                relation: "eq".to_string(),
            },
            max_score,
            hits: page,
        },
        aggregations: None,
    };
    Json(resp).into_response()
}

#[derive(Debug, Deserialize, Default)]
pub struct ScrollBody {
    #[serde(default)]
    pub scroll: Option<String>,
    #[serde(default)]
    pub scroll_id: Option<String>,
    /// Declared so a continuation body carrying `rerank` is refused rather
    /// than ignored: serde drops unknown keys, and a scroll continuation
    /// streams the engine's order, so a caller who added `rerank` here was
    /// getting lexical order under a 200 — the same accepted-and-ignored
    /// class the `?scroll=` path already refuses.
    #[serde(default)]
    pub rerank: Option<Value>,
    /// Same rule for `judge` (issue #1060): a continuation streams the
    /// engine's order and cannot re-judge it.
    #[serde(default)]
    pub judge: Option<Value>,
}

#[derive(Debug, Deserialize, Default)]
pub struct ScrollQueryParamsFull {
    #[serde(default)]
    pub scroll: Option<String>,
    #[serde(default)]
    pub scroll_id: Option<String>,
    #[serde(default)]
    pub rest_total_hits_as_int: Option<String>,
}

pub async fn next_scroll(
    State(state): State<AppState>,
    Query(params): Query<ScrollQueryParamsFull>,
    body: OptionalJson<ScrollBody>,
) -> impl IntoResponse {
    // scroll_id may come from body OR query param
    let body = body.into_or_default();
    if body.rerank.is_some() || body.judge.is_some() {
        return (
            StatusCode::BAD_REQUEST,
            Json(if body.rerank.is_some() {
                crate::rerank_stage::unsupported_on("_search/scroll")
            } else {
                crate::judge_stage::unsupported_on("_search/scroll")
            }),
        )
            .into_response();
    }
    let scroll_id = match body.scroll_id.clone().or_else(|| params.scroll_id.clone()) {
        Some(id) if !id.is_empty() => id,
        _ => {
            let e = xerj_common::XerjError::invalid_query("Missing scroll_id");
            return ApiError::new(e).into_response();
        }
    };
    let scroll_keep_alive = body.scroll.as_deref().or(params.scroll.as_deref());
    scroll_page_response(
        &state,
        scroll_id,
        scroll_keep_alive,
        params.rest_total_hits_as_int.as_deref() == Some("true"),
    )
    .await
}

/// `GET|POST /_search/scroll/{scroll_id}` — the legacy path-parameter form
/// of scroll continuation. A real, documented ES/OpenSearch REST API
/// variant alongside the body/query-param form above (`next_scroll`), not
/// a client mistake: found missing while investigating why OpenSearch
/// Dashboards 3.7.0 crashes fatally partway through its saved-objects
/// migration (`.kibana_1` → `.kibana_2`) against xerj. Traced via request
/// tracing (`logging.access_log = true`) to the exact call: the migration
/// opens a scroll (`POST /.kibana_1/_search?scroll=15m`, 200), bulk-indexes
/// the first page into the new index (200), then continues the scroll via
/// `GET /_search/scroll/{scroll_id}` — which had no matching route at all,
/// so axum's default fallback returned a bare 404 with an empty body. OSD's
/// migration code treats that as fatal and aborts the whole process rather
/// than retrying, so ANY client using this form — not just OSD 3.7.0's
/// migrator — would have hit the same wall.
pub async fn next_scroll_path(
    State(state): State<AppState>,
    Path(scroll_id): Path<String>,
    Query(params): Query<ScrollQueryParamsFull>,
) -> impl IntoResponse {
    scroll_page_response(
        &state,
        scroll_id,
        params.scroll.as_deref(),
        params.rest_total_hits_as_int.as_deref() == Some("true"),
    )
    .await
}

/// Apply the ES `index.disable_sequence_numbers` sentinel — `_seq_no: -2`,
/// `_primary_term: 0` — to every hit in `hits` whose own `_index` setting
/// has it enabled. Shared by `search_impl` (plain `_search`) and
/// `scroll_page_response` (#440: scroll had no equivalent at all, so a
/// continuation page for such an index reported whatever `_seq_no` the
/// snapshotted hit carried instead of the sentinel real ES uses).
fn apply_disable_seqno_sentinel(state: &AppState, hits: &mut [Value]) {
    for hit in hits.iter_mut() {
        let ix = hit
            .get("_index")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let disabled = state
            .engine
            .index_settings
            .get(&ix)
            .map(|v| {
                let s = v.clone();
                let as_bool = |val: &Value| {
                    val.as_bool()
                        .unwrap_or_else(|| val.as_str().map(|x| x == "true").unwrap_or(false))
                };
                s.pointer("/index/disable_sequence_numbers")
                    .map(as_bool)
                    .unwrap_or(false)
                    || s.get("index")
                        .and_then(|i| i.get("index.disable_sequence_numbers"))
                        .map(as_bool)
                        .unwrap_or(false)
                    || s.get("index.disable_sequence_numbers")
                        .map(as_bool)
                        .unwrap_or(false)
            })
            .unwrap_or(false);
        if disabled {
            if let Some(obj) = hit.as_object_mut() {
                obj.insert("_seq_no".into(), json!(-2i64));
                obj.insert("_primary_term".into(), json!(0));
            }
        }
    }
}

async fn scroll_page_response(
    state: &AppState,
    scroll_id: String,
    scroll_keep_alive: Option<&str>,
    rest_total_hits_as_int: bool,
) -> Response {
    // An id xerj never issued (its scroll ids are v4 UUIDs) cannot name a
    // context: ES answers 400 `Cannot parse scroll id`, not a 404 (item 4e).
    if Uuid::parse_str(&scroll_id).is_err() {
        return cannot_parse_scroll_id();
    }

    match state.engine.scrolls.get_mut(&scroll_id) {
        Some(mut ctx) => {
            // Keep-alive enforcement (RC4 blocker 11): an expired context
            // is gone even if the background sweeper hasn't collected it
            // yet — same 404 as an unknown id, matching ES.
            let now = Instant::now();
            if ctx.expires_at <= now {
                drop(ctx); // release the DashMap shard guard before remove
                state.engine.scrolls.remove(&scroll_id);
                return search_context_missing(&scroll_id);
            }
            // Re-arm the deadline: an explicit `scroll` on the continuation
            // (body wins over query param, like scroll_id) sets a new
            // keep-alive (capped); absent → the previous keep-alive window
            // restarts from now, matching ES.
            if let Some(ka_secs) = scroll_keep_alive.and_then(parse_keep_alive_to_secs) {
                let capped = ka_secs.min(state.config.search_context.scroll_max_keep_alive_secs);
                ctx.keep_alive = std::time::Duration::from_secs(capped);
            }
            ctx.expires_at = now + ctx.keep_alive;

            let page_size = ctx.page_size.max(1);
            let position = ctx.position;
            let total = ctx.hits.len() as u64;
            // Captured once at scroll-open time (real ES semantics) — see
            // `ScrollContext::seq_no_primary_term`/`::version`'s doc
            // comments. Read into locals before the per-hit closure below
            // borrows `ctx.hits`.
            let emit_seq_no = ctx.seq_no_primary_term;
            let emit_version = ctx.version;
            // #624/#637: the opening request's REQUEST-level `_source` decision
            // (`_source:false`, stored_fields-implied) governs the whole scroll —
            // omit `_source` on continuation pages too (ES fixes source selection
            // at open). inner_hits still render from the collapse group snapshot
            // regardless.
            let source_disabled = ctx.source_disabled;
            // #637/#659: whether to ALSO apply the mapping `_source.enabled:false`
            // suppression per hit below. True for scrolls opened by either real
            // route — `search_impl` and, since #659, `_search_scroll` — both of
            // which apply it on their first page; false only for synthetic/test
            // contexts. Keeps the continuation byte-identical to the opening
            // route's own first page.
            let mapping_source_check = ctx.mapping_source_check;

            // Detect whether the initial search sorted by a non-score key;
            // in that case `max_score` must be null on scroll pages too.
            let has_non_score_sort = ctx
                .hits
                .first()
                .map(|(_, h)| !h.sort.is_empty())
                .unwrap_or(false);

            // `_seq_no`/`_version` are read from each hit itself — resolved
            // at construction time in the engine, from the same read as
            // `_source`, snapshotted into `ctx.hits` at scroll-open (a
            // single request-duration window, never re-read live) — not
            // hardcoded, and omitted when the flag wasn't requested
            // (#428/#440).
            let page_hits: Vec<EsHit> = ctx
                .hits
                .iter()
                .skip(position)
                .take(page_size)
                .map(|(hit_index, h)| {
                    let (version, seq_no, primary_term) =
                        resolve_hit_versioning(h.seq_no, h.version, emit_seq_no, emit_version);
                    EsHit {
                        // Per-hit index, not the context-level one (#414).
                        index: hit_index.clone(),
                        id: h.id.clone(),
                        score: Some(h.score as f64),
                        version,
                        seq_no,
                        primary_term,
                        source: if h.source.is_null() {
                            None
                        } else {
                            Some(h.source.clone())
                        },
                        fields: passage_fields(h),
                        sort: if h.sort.is_empty() {
                            None
                        } else {
                            Some(h.sort.clone())
                        },
                        highlight: h.highlight.clone(),
                        explanation: None,
                        inner_hits: None,
                        matched_queries: if h.matched_queries.is_empty() {
                            Value::Null
                        } else {
                            Value::Array(
                                h.matched_queries
                                    .iter()
                                    .cloned()
                                    .map(Value::String)
                                    .collect(),
                            )
                        },
                        ignored: None,
                        ignored_field_values: None,
                        p_relevant: None,
                    }
                })
                .collect();

            ctx.position = (position + page_size).min(ctx.hits.len());

            let max_score: Option<f64> = if has_non_score_sort {
                None
            } else {
                page_hits.first().and_then(|h| h.score)
            };
            let mut hits_json: Vec<Value> = page_hits
                .iter()
                .map(|h| {
                    let mut o = serde_json::Map::new();
                    o.insert("_index".to_string(), Value::String(h.index.clone()));
                    o.insert("_id".to_string(), Value::String(h.id.clone()));
                    o.insert(
                        "_score".to_string(),
                        match h.score {
                            Some(s) => json!(s),
                            None => Value::Null,
                        },
                    );
                    // Previously always omitted regardless of `version`/
                    // `seq_no_primary_term` — `EsHit` carried them but
                    // this hand-built map never read them out (#428).
                    if let Some(v) = h.version {
                        o.insert("_version".to_string(), json!(v));
                    }
                    if let Some(sn) = h.seq_no {
                        o.insert("_seq_no".to_string(), json!(sn));
                    }
                    if let Some(pt) = h.primary_term {
                        o.insert("_primary_term".to_string(), json!(pt));
                    }
                    if let Some(src) = &h.source {
                        // A collapse leader carries `__xy_collapse_group__` /
                        // `__xy_collapse_spec__` sentinels snapshotted into the
                        // scroll context at open time. `search_impl` renders them
                        // into `inner_hits` and strips them from `_source`; the
                        // scroll continuation must do the same or it leaks the
                        // sentinels and emits no inner_hits (#621/#566).
                        let mut src = src.clone();
                        let collapse_inner = src.as_object_mut().and_then(|obj| {
                            let group = obj
                                .get("__xy_collapse_group__")
                                .and_then(Value::as_array)
                                .cloned();
                            let spec = obj.get("__xy_collapse_spec__").cloned();
                            obj.remove("__xy_collapse_group__");
                            obj.remove("__xy_collapse_spec__");
                            match (group, spec) {
                                (Some(g), Some(s)) => Some(render_collapse_inner_hits(
                                    g,
                                    s,
                                    &h.index,
                                    rest_total_hits_as_int,
                                    // The scroll continuation has no companion set
                                    // in scope (it would need threading through
                                    // ScrollContext); the unconditional passage
                                    // sentinel strip still applies. Scroll+collapse
                                    // companion stripping is a scoped remaining
                                    // sub-case of #646.
                                    None,
                                )),
                                _ => None,
                            }
                        });
                        // #624/#637: honor the first page's `_source` suppression
                        // (the sentinels have already been consumed into
                        // `inner_hits` above). `source_disabled` carries the
                        // request-level constant (`_source:false`, stored_fields-
                        // implied). The mapping `_source.enabled:false` case is
                        // re-derived PER HIT from this hit's own index (a scroll
                        // can span indices with divergent `_source` settings, and
                        // the first page suppresses it per-hit — #658 skeptic),
                        // but ONLY when the opening route applies it on its first
                        // page (`mapping_source_check`). Both real scroll routes
                        // now do (search_impl, and `_search_scroll` since #659);
                        // the flag is false only for synthetic contexts.
                        // inner_hits are emitted regardless.
                        if !source_disabled
                            && !(mapping_source_check && mapping_source_disabled(state, &h.index))
                        {
                            o.insert("_source".to_string(), src);
                        }
                        if let Some(inner) = collapse_inner {
                            o.insert("inner_hits".to_string(), inner);
                        }
                    }
                    if let Some(sort) = &h.sort {
                        o.insert("sort".to_string(), Value::Array(sort.clone()));
                    }
                    if let Some(fields) = &h.fields {
                        o.insert(
                            "fields".to_string(),
                            serde_json::to_value(fields).unwrap_or(Value::Null),
                        );
                    }
                    Value::Object(o)
                })
                .collect();
            // `index.disable_sequence_numbers` sentinel (`_seq_no: -2`,
            // `_primary_term: 0`) — scroll previously had no equivalent of
            // `search_impl`'s handling at all (#440).
            apply_disable_seqno_sentinel(state, &mut hits_json);

            let mut resp = json!({
                "_scroll_id": scroll_id,
                "took": 0u64,
                "timed_out": false,
                "_shards": { "total": 1, "successful": 1, "skipped": 0, "failed": 0 },
                "hits": {
                    "total": { "value": total, "relation": "eq" },
                    "max_score": max_score,
                    "hits": hits_json
                }
            });

            // rest_total_hits_as_int=true → flatten hits.total to a bare integer.
            if rest_total_hits_as_int {
                resp["hits"]["total"] = json!(total);
            }
            Json(resp).into_response()
        }
        None => search_context_missing(&scroll_id),
    }
}

#[cfg(test)]
mod passage_scroll_tests {
    use super::*;
    use axum::{body::Body, http::Request};
    use std::time::{Duration, Instant};
    use tower::ServiceExt;
    use xerj_query::executor::{Hit, PassageMatch};

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    fn passage_hit(id: &str, ordinal: u32) -> Hit {
        Hit {
            id: id.to_string(),
            score: 1.0,
            source: json!({"company": "ACME"}),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: Some(PassageMatch {
                field: "content".into(),
                ordinal,
                start_offset: 0,
                end_offset: 8,
                text: "evidence".into(),
                page: Some(u64::from(ordinal) + 1),
            }),
        }
    }

    #[tokio::test]
    async fn scroll_continuation_preserves_opted_in_passage_fields() {
        let state = test_state();
        let scroll_id = Uuid::new_v4().to_string();
        let now = Instant::now();
        state.engine.scrolls.insert(
            scroll_id.clone(),
            xerj_engine::engine::ScrollContext {
                index: "reports".into(),
                hits: vec![
                    ("reports".to_string(), passage_hit("page-1", 0)),
                    ("reports".to_string(), passage_hit("page-2", 1)),
                ],
                position: 1,
                page_size: 1,
                seq_no_primary_term: false,
                version: false,
                source_disabled: false,
                mapping_source_check: false,
                created: now,
                keep_alive: Duration::from_secs(60),
                expires_at: now + Duration::from_secs(60),
            },
        );
        let app = crate::router::build_es_compat_router(state);
        let response = app
            .oneshot(
                Request::post("/_search/scroll")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({"scroll_id": scroll_id}).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body["hits"]["hits"][0]["_id"], "page-2");
        assert_eq!(
            body["hits"]["hits"][0]["fields"]["_passage"][0]["ordinal"],
            1
        );
        assert_eq!(body["hits"]["hits"][0]["fields"]["_passage"][0]["page"], 2);
    }

    /// Regression test for #414. A scroll spanning two indices stored bare
    /// hits plus one context-level `index`, so every continuation page stamped
    /// that single name onto hits regardless of which index they came from.
    /// With ids colliding across indices — the normal case for a reindex or
    /// migration, where each index numbers its own documents — `(_index, _id)`
    /// stopped being distinct and a consumer keyed on it silently kept half
    /// the corpus. Measured before the fix on 300+300 documents: 600 hits
    /// collapsed to 300 distinct `(_index, _id)` pairs, every one labelled
    /// with the first index.
    ///
    /// The pairing is now structural (`hits: Vec<(String, Hit)>`), so a hit
    /// cannot exist in a context without the index it came from.
    #[tokio::test]
    async fn scroll_continuation_reports_the_index_each_hit_came_from() {
        let state = test_state();
        let scroll_id = Uuid::new_v4().to_string();
        let now = Instant::now();
        // Same `_id` in both indices: only `_index` tells them apart.
        state.engine.scrolls.insert(
            scroll_id.clone(),
            xerj_engine::engine::ScrollContext {
                index: "mi_a".into(),
                hits: vec![
                    ("mi_a".to_string(), passage_hit("dup-1", 0)),
                    ("mi_b".to_string(), passage_hit("dup-1", 1)),
                ],
                position: 1,
                page_size: 1,
                seq_no_primary_term: false,
                version: false,
                source_disabled: false,
                mapping_source_check: false,
                created: now,
                keep_alive: Duration::from_secs(60),
                expires_at: now + Duration::from_secs(60),
            },
        );
        let app = crate::router::build_es_compat_router(state);
        let response = app
            .oneshot(
                Request::post("/_search/scroll")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({"scroll_id": scroll_id}).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body["hits"]["hits"][0]["_id"], "dup-1");
        // The continuation hit belongs to mi_b. Before the fix this was
        // "mi_a" — the context-level name — making it indistinguishable
        // from the mi_a document with the same id on page 1.
        assert_eq!(
            body["hits"]["hits"][0]["_index"], "mi_b",
            "continuation page must report the index the hit came from, not the context's"
        );
    }

    /// Regression test for a real bug found live: OpenSearch Dashboards
    /// 3.7.0's saved-objects migration (`.kibana_1` → `.kibana_2`) continues
    /// its scroll via `GET /_search/scroll/{scroll_id}` (the legacy
    /// path-parameter form — a real ES/OpenSearch REST variant, not a
    /// client mistake), which had no matching route at all and 404'd with
    /// an empty body. OSD's migration code treats that as fatal and crashes
    /// the whole process rather than retrying.
    #[tokio::test]
    async fn scroll_continuation_via_legacy_path_param_form_works() {
        let state = test_state();
        let scroll_id = Uuid::new_v4().to_string();
        let now = Instant::now();
        state.engine.scrolls.insert(
            scroll_id.clone(),
            xerj_engine::engine::ScrollContext {
                index: "reports".into(),
                hits: vec![
                    ("reports".to_string(), passage_hit("page-1", 0)),
                    ("reports".to_string(), passage_hit("page-2", 1)),
                ],
                position: 1,
                page_size: 1,
                seq_no_primary_term: false,
                version: false,
                source_disabled: false,
                mapping_source_check: false,
                created: now,
                keep_alive: Duration::from_secs(60),
                expires_at: now + Duration::from_secs(60),
            },
        );
        let app = crate::router::build_es_compat_router(state);

        // GET form, exactly as OSD 3.7.0's migrator calls it.
        let response = app
            .clone()
            .oneshot(
                Request::get(format!("/_search/scroll/{scroll_id}"))
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body["hits"]["hits"][0]["_id"], "page-2");
        assert_eq!(body["_scroll_id"], scroll_id);

        // An id xerj never issued still gets ES's 400 "cannot parse", not a
        // bare 404, matching the body-form endpoint's existing behavior.
        let response = app
            .oneshot(
                Request::get("/_search/scroll/not-a-real-scroll-id")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    }

    #[tokio::test]
    async fn passage_field_scalar_array_and_object_forms_reach_the_engine() {
        let state = test_state();
        let mut schema = Schema::empty();
        let mut content = FieldConfig::new("content", FieldType::Text);
        content.options.dimensions = Some(32);
        content.embedding = Some(xerj_common::types::EmbeddingConfig {
            endpoint: None,
            model: None,
            target_field: Some("embedding".into()),
        });
        schema.fields.push(content);
        state.engine.create_index("passage-fields", schema).unwrap();
        let index = state.engine.get_index("passage-fields").unwrap();
        index
            .index_document(
                Some("report-page".into()),
                json!({
                    "content": format!(
                        "{} quarterly zephyr liquidity evidence {}",
                        "operating narrative ".repeat(50),
                        "tax footnote ".repeat(50)
                    ),
                    "page": 7
                }),
            )
            .await
            .unwrap();
        index.refresh().await.unwrap();
        let app = crate::router::build_es_compat_router(state);

        for fields in [
            json!("_passage"),
            json!(["_passage"]),
            json!([{"field": "_passage"}]),
        ] {
            let response = app
                .clone()
                .oneshot(
                    Request::post("/passage-fields/_search")
                        .header("content-type", "application/json")
                        .body(Body::from(
                            json!({
                                "fields": fields,
                                "query": {"semantic": {
                                    "field": "content",
                                    "query": "quarterly zephyr liquidity evidence",
                                    "k": 1
                                }}
                            })
                            .to_string(),
                        ))
                        .unwrap(),
                )
                .await
                .unwrap();
