// GET /_cluster/stats
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cluster_stats(State(state): State<AppState>) -> impl IntoResponse {
    let health = state.engine.health().await;
    let (idx_count, total_docs, total_deleted, store_bytes) = real_index_totals(&state).await;
    let rss_bytes = read_rss_bytes().unwrap_or(0);
    let (mem_total, mem_avail) = read_meminfo().unwrap_or((rss_bytes * 4, rss_bytes * 3));
    let mem_used = mem_total.saturating_sub(mem_avail);
    let num_cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);
    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;

    Json(json!({
        "cluster_name": "xerj",
        "cluster_uuid": "xerj-cluster-1",
        "timestamp": now_ms,
        "status": health.status,
        "_nodes": { "total": 1, "successful": 1, "failed": 0 },
        "indices": {
            "count": idx_count,
            "shards": { "total": idx_count, "primaries": idx_count, "replication": 0.0 },
            "docs": { "count": total_docs, "deleted": total_deleted },
            "store": { "size_in_bytes": store_bytes },
            "fielddata": { "memory_size_in_bytes": 0, "evictions": 0 },
            "query_cache": { "memory_size_in_bytes": 0, "total_count": 0, "hit_count": 0, "miss_count": 0 },
            "segments": { "count": 0, "memory_in_bytes": 0 },
        },
        "nodes": {
            "count": { "total": 1, "data": 1, "master": 1 },
            "os": {
                "available_processors": num_cpus,
                "mem": {
                    "total_in_bytes": mem_total,
                    "free_in_bytes": mem_avail,
                    "used_in_bytes": mem_used,
                }
            },
            "jvm": {
                "mem": {
                    "heap_used_in_bytes": rss_bytes,
                    "heap_max_in_bytes": mem_total,
                }
            },
            "versions": ["8.13.0"],
        }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// Explain helper — builds _explanation for a hit when explain: true
// ─────────────────────────────────────────────────────────────────────────────

/// Build a basic ES-style `_explanation` object for a scored hit.
fn build_explanation(score: f32, query: &xerj_query::ast::QueryNode) -> Value {
    let (description, details) = explain_query_node(query);
    json!({
        "value": score,
        "description": description,
        "details": details,
    })
}

fn explain_query_node(q: &xerj_query::ast::QueryNode) -> (String, Vec<Value>) {
    use xerj_query::ast::QueryNode;

    match q {
        QueryNode::MatchAll => ("match all docs, score 1.0".to_string(), vec![]),
        QueryNode::MatchNone => ("match no docs".to_string(), vec![]),
        QueryNode::Match { field, query, .. } => {
            // ES explains a Match with multiple tokens as a
            // per-term weight sum (Lucene builds a BooleanQuery).
            // Single-token match stays as the direct weight label.
            let tokens: Vec<&str> = query.split_whitespace().collect();
            if tokens.len() <= 1 {
                (
                    format!(
                        "weight({}:{} in 0) [PerFieldSimilarity], result of:",
                        field, query
                    ),
                    vec![],
                )
            } else {
                let details: Vec<Value> = tokens.iter().map(|t| json!({
                    "value": 0.0,
                    "description": format!("weight({}:{} in 0) [PerFieldSimilarity], result of:", field, t),
                    "details": [],
                })).collect();
                ("sum of:".to_string(), details)
            }
        }
        QueryNode::MatchPhrase { field, query, .. } => {
            (format!("weight(phrase {}:{} in doc)", field, query), vec![])
        }
        QueryNode::MultiMatch { query, fields, .. } => (
            format!("weight({}:{} in doc)", fields.join("|"), query),
            vec![],
        ),
        QueryNode::Term { field, value, .. } => {
            (format!("weight({}:{} in doc)", field, value), vec![])
        }
        QueryNode::Terms { field, values, .. } => (
            format!(
                "weight({}:({}) in doc)",
                field,
                values
                    .iter()
                    .map(|v| v.to_string())
                    .collect::<Vec<_>>()
                    .join(" | ")
            ),
            vec![],
        ),
        QueryNode::Range {
            field,
            gte,
            gt,
            lte,
            lt,
            ..
        } => {
            let mut parts = Vec::new();
            if let Some(v) = gte {
                parts.push(format!("{} >= {}", field, v));
            }
            if let Some(v) = gt {
                parts.push(format!("{} > {}", field, v));
            }
            if let Some(v) = lte {
                parts.push(format!("{} <= {}", field, v));
            }
            if let Some(v) = lt {
                parts.push(format!("{} < {}", field, v));
            }
            (format!("range({})", parts.join(", ")), vec![])
        }
        QueryNode::Prefix { field, value, .. } => {
            (format!("weight({}:{} in doc)", field, value), vec![])
        }
        QueryNode::Exists { field } => (format!("ConstantScore(exists(field={}))", field), vec![]),
        QueryNode::Bool {
            must,
            should,
            filter,
            must_not,
            ..
        } => {
            let mut detail_children: Vec<Value> = Vec::new();
            for c in must {
                let (d, ch) = explain_query_node(c);
                detail_children.push(
                    json!({ "value": 0, "description": format!("must: {}", d), "details": ch }),
                );
            }
            for c in should {
                let (d, ch) = explain_query_node(c);
                detail_children.push(
                    json!({ "value": 0, "description": format!("should: {}", d), "details": ch }),
                );
            }
            for c in filter {
                let (d, ch) = explain_query_node(c);
                detail_children.push(
                    json!({ "value": 0, "description": format!("filter: {}", d), "details": ch }),
                );
            }
            for c in must_not {
                let (d, ch) = explain_query_node(c);
                detail_children.push(
                    json!({ "value": 0, "description": format!("must_not: {}", d), "details": ch }),
                );
            }
            ("sum of:".to_string(), detail_children)
        }
        QueryNode::Boosting {
            positive,
            negative,
            negative_boost,
        } => {
            let (pd, pc) = explain_query_node(positive);
            let (nd, nc) = explain_query_node(negative);
            (
                format!("boosting query (negative_boost={})", negative_boost),
                vec![
                    json!({ "value": 0, "description": format!("positive: {}", pd), "details": pc }),
                    json!({ "value": 0, "description": format!("negative: {}", nd), "details": nc }),
                ],
            )
        }
        QueryNode::DisMax {
            queries,
            tie_breaker,
        } => {
            let children: Vec<Value> = queries
                .iter()
                .map(|c| {
                    let (d, ch) = explain_query_node(c);
                    json!({ "value": 0, "description": d, "details": ch })
                })
                .collect();
            (format!("max of, tie_breaker={}", tie_breaker), children)
        }
        QueryNode::Constant { score, query } => {
            let (d, ch) = explain_query_node(query);
            (format!("ConstantScore({}) = {}", d, score), ch)
        }
        QueryNode::Boosted { boost, query } => {
            let (d, ch) = explain_query_node(query);
            (format!("boosted({}, boost={})", d, boost), ch)
        }
        _ => ("opaque query".to_string(), vec![]),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_delete_by_query
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct DeleteByQueryBody {
    pub query: Value,
    /// ES `max_docs`: "The maximum number of documents to process. Defaults
    /// to all documents." `None` = purge every match.
    #[serde(default)]
    pub max_docs: Option<u64>,
    /// ES `scroll_size`: "The size of the scroll request that powers the
    /// operation." Default 1 000, clamped to `1..=10_000` (the per-request
    /// `max_result_window` ceiling — paging is keyset, so a small page never
    /// hits the deep-paging wall). `max_docs <= scroll_size` naturally
    /// degenerates to the documented single-batch fast path.
    #[serde(default)]
    pub scroll_size: Option<u64>,
}

/// Resolve a by-query selector to the concrete member indices it must touch and
/// the effective query to run against each.
///
/// The destructive by-query handlers used to call `Engine::get_index`, which
/// resolves an alias to `aliased.first()` — one member. A `_delete_by_query`
/// through a 3-member alias therefore deleted a third of the corpus and
/// reported a clean success (#450). This fans the selector out to every member
/// the read paths already see (`resolve_index_selector`, #433) and — crucially
/// for a destructive path — ANDs in any alias `filter` the way `search_impl`
/// does, so a *filtered* alias deletes only its slice, not the whole backing
/// index (the #524 hazard).
async fn resolve_by_query_targets(
    state: &AppState,
    spec: &str,
    user_query: Value,
) -> std::result::Result<
    (Vec<std::sync::Arc<xerj_engine::Index>>, Vec<String>, Value),
    xerj_common::XerjError,
> {
    let member_names = resolve_index_selector(state, spec).await;

    // Alias filters are keyed on the name AS WRITTEN (the alias, not its
    // expanded members) — mirror `search_impl`'s alias-filter path exactly.
    let mut alias_filters: Vec<Value> = Vec::new();
    for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if let Some(entry) = state.engine.aliases.get(part) {
            for backing in entry.value().iter() {
                if let Some(meta) = state.engine.index_alias_metadata.get(backing) {
                    if let Some(filter) = meta.get(part).and_then(|v| v.get("filter")).cloned() {
                        alias_filters.push(filter);
                    }
                }
            }
        }
    }
    let effective_query = if alias_filters.is_empty() {
        user_query
    } else {
        json!({ "bool": { "must": [user_query], "filter": alias_filters } })
    };

    let mut indices = Vec::with_capacity(member_names.len());
    for name in &member_names {
        indices.push(
            state
                .engine
                .get_index(name)
                .map_err(xerj_common::XerjError::from)?,
        );
    }
    Ok((indices, member_names, effective_query))
}

/// Combine the per-member results of a fanned-out by-query into one response.
///
/// A single member (the common case: a plain index, or a one-member alias) is
/// returned byte-for-byte unchanged so the existing wire format never drifts.
/// Multiple members are summed field-by-field with their `failures` arrays
/// concatenated; if any member produced an error body (it carries a `status`),
/// that error is surfaced rather than a clean aggregate — a destructive
/// by-query that partially failed must not report success.
pub(crate) fn aggregate_by_query_results(mut results: Vec<Value>, count_key: &str) -> Value {
    if results.len() == 1 {
        return results.pop().unwrap();
    }
    if let Some(err) = results.iter().find(|v| v.get("status").is_some()) {
        return err.clone();
    }
    let mut took = 0u64;
    let mut timed_out = false;
    let mut total = 0u64;
    let mut affected = 0u64;
    let mut batches = 0u64;
    let mut version_conflicts = 0u64;
    let mut noops = 0u64;
    let mut failures: Vec<Value> = Vec::new();
    for r in &results {
        took += r.get("took").and_then(Value::as_u64).unwrap_or(0);
        timed_out |= r.get("timed_out").and_then(Value::as_bool).unwrap_or(false);
        total += r.get("total").and_then(Value::as_u64).unwrap_or(0);
        affected += r.get(count_key).and_then(Value::as_u64).unwrap_or(0);
        batches += r.get("batches").and_then(Value::as_u64).unwrap_or(0);
        version_conflicts += r
            .get("version_conflicts")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        noops += r.get("noops").and_then(Value::as_u64).unwrap_or(0);
        if let Some(f) = r.get("failures").and_then(Value::as_array) {
            failures.extend(f.iter().cloned());
        }
    }
    let mut out = serde_json::Map::new();
    out.insert("took".into(), json!(took));
    out.insert("timed_out".into(), json!(timed_out));
    out.insert("total".into(), json!(total));
    out.insert(count_key.to_string(), json!(affected));
    // `_update_by_query` bodies also carry a `"deleted": 0` field (an update
    // never deletes); the single-member response includes it, so the aggregate
    // does too — otherwise the 2+-member update body drops a field the
    // 1-member body has (#553 nit).
    if count_key == "updated" {
        out.insert("deleted".into(), json!(0));
    }
    out.insert("batches".into(), json!(batches));
    out.insert("version_conflicts".into(), json!(version_conflicts));
    out.insert("noops".into(), json!(noops));
    out.insert("failures".into(), json!(failures));
    out.insert("throttled_millis".into(), json!(0));
    out.insert("requests_per_second".into(), json!(-1));
    out.insert("throttled_until_millis".into(), json!(0));
    Value::Object(out)
}

/// Build the cluster fan-out off this handler's state machine.
///
/// `delete_by_query` is already large enough that a debug build's worker
/// stack (2 MiB, the `#[tokio::test]` default) overflows once a second copy
/// of the runner is inlined into the same future. `[cluster] enabled = false`
/// never polls the fan-out, so the future is allocated here and only the
/// pointer is stored on the handler. `inline(never)` keeps that allocation
/// in this frame: inlining it back into `delete_by_query` puts the fan-out
/// on the worker stack again.
#[inline(never)]
fn begin_cluster_delete_by_query(
    state: AppState,
    index_names: Vec<String>,
    parts: crate::cluster_shard::DeleteByQueryParts,
    wait_for_completion: bool,
    handle: crate::state::TaskHandle,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Response> + Send>> {
    Box::pin(cluster_delete_by_query(
        state,
        index_names,
        parts,
        wait_for_completion,
        handle,
    ))
}

async fn cluster_delete_by_query(
    state: AppState,
    index_names: Vec<String>,
    parts: crate::cluster_shard::DeleteByQueryParts,
    wait_for_completion: bool,
    handle: crate::state::TaskHandle,
) -> Response {
    if !wait_for_completion {
        let task_key = handle.key().to_string();
        let spawned_key = task_key.clone();
        let tasks = state.tasks.clone();
        let names = index_names.clone();
        // The fan-out calls `Engine::get_index` on the detached task, so
        // the request's visibility rule has to come with it. See
        // `xerj_engine::index_guard`.
        let rule = xerj_engine::index_guard::current();
        tokio::spawn(xerj_engine::index_guard::scoped_opt(rule, async move {
            let mut results = Vec::with_capacity(names.len());
            for name in &names {
                results.push(
                    crate::cluster_shard::pin_delete_by_query_on_primaries(
                        state.clone(),
                        name.clone(),
                        parts.clone(),
                    )
                    .await,
                );
            }
            tasks.complete(&spawned_key, aggregate_by_query_results(results, "deleted"));
            drop(handle);
        }));
        return Json(json!({ "task": task_key })).into_response();
    }
    let mut results = Vec::with_capacity(index_names.len());
    for name in &index_names {
        results.push(
            crate::cluster_shard::pin_delete_by_query_on_primaries(
                state.clone(),
                name.clone(),
                parts.clone(),
            )
            .await,
        );
    }
    drop(handle);
    by_query_response(aggregate_by_query_results(results, "deleted"))
}

pub async fn delete_by_query(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<HashMap<String, String>>,
    Json(body): Json<DeleteByQueryBody>,
) -> impl IntoResponse {
    // Fan the selector out to every member of a multi-index alias (#450), with
    // any alias filter already ANDed into the query.
    let (indices, index_names, effective_query) =
        match resolve_by_query_targets(&state, &index, body.query.clone()).await {
            Ok(t) => t,
            Err(e) => return ApiError::new(e).into_response(),
        };

    // Validate the (alias-filter-ANDed) query once, up front, so a malformed
    // body is an immediate 400 before a task is registered or any member is
    // touched — the runner below re-parses per batch as the cursor advances.
    let scroll_size = body
        .scroll_size
        .unwrap_or(DEFAULT_BY_QUERY_SCROLL_SIZE)
        .clamp(1, 10_000) as usize;
    let validation_body = json!({
        "query": effective_query,
        "size": scroll_size,
        "from": 0,
        "sort": [{ "_id": "asc" }],
    });
    if let Err(e) = xerj_query::parse_request(&validation_body) {
        return ApiError::new(xerj_common::XerjError::invalid_query(e.to_string())).into_response();
    }

    // ES defaults `wait_for_completion` to true (synchronous); only an
    // explicit `false` switches to the async `{"task": "node:id"}` form.
    let wait_for_completion = params
        .get("wait_for_completion")
        .map(|v| v != "false")
        .unwrap_or(true);
    let handle = state.tasks.register("indices:data/write/delete/byquery");

    if state.engine.has_cluster() {
        let parts = crate::cluster_shard::DeleteByQueryParts {
            query: effective_query,
            max_docs: body.max_docs,
            scroll_size,
        };
        return begin_cluster_delete_by_query(
            state,
            index_names,
            parts,
            wait_for_completion,
            handle,
        )
        .await;
    }

    if !wait_for_completion {
        let task_key = handle.key().to_string();
        let spawned_key = task_key.clone();
        let tasks = state.tasks.clone();
        let task_query = effective_query.clone();
        let task_max_docs = body.max_docs;
        // Detached, so no `index_guard` rule — and none is needed: the task
        // owns the already-authorized `Index` handles this request resolved,
        // and an `Index` cannot name another index (it holds no `Engine`). See
        // `xerj_engine::index_guard` for the contract a spawn that *can* reach
        // `Engine::get_index` has to follow instead.
        tokio::spawn(async move {
            let mut results = Vec::with_capacity(indices.len());
            for idx in indices {
                results.push(
                    pin_local_delete_by_query(idx, task_query.clone(), task_max_docs, scroll_size)
                        .await,
                );
            }
            tasks.complete(&spawned_key, aggregate_by_query_results(results, "deleted"));
            drop(handle);
        });
        return Json(json!({ "task": task_key })).into_response();
    }

    let mut results = Vec::with_capacity(indices.len());
    for idx in indices {
        results.push(
            pin_local_delete_by_query(idx, effective_query.clone(), body.max_docs, scroll_size)
                .await,
        );
    }
    drop(handle);
    by_query_response(aggregate_by_query_results(results, "deleted"))
}

/// Give a `_delete_by_query` / `_update_by_query` result the HTTP status its
/// own body claims.
///
/// Both runners return a plain `Value` because the detached
/// (`wait_for_completion=false`) path stores it as the `response` of a
/// `_tasks/{id}` entry, which has no HTTP status of its own. The synchronous
/// path then handed that value straight to `Json(..)` — always 200. So a
/// refusal went out as `200 OK` carrying `{"error": {…}, "status": 400}`, and a
/// client branching on the HTTP status read a completed run and then found no
/// `deleted` / `updated` key (#123).
///
/// Every error body these runners produce — `script_limit_error_value` and
/// `ApiError::into_value` — already carries the right code in `status`, so this
/// reads it rather than re-deriving one. A successful run has no `status` key
/// and stays 200.
fn by_query_response(body: Value) -> Response {
    let status = body
        .get("status")
        .and_then(Value::as_u64)
        .and_then(|s| u16::try_from(s).ok())
        .and_then(|s| StatusCode::from_u16(s).ok())
        .unwrap_or(StatusCode::OK);
    (status, Json(body)).into_response()
}

/// ES `scroll_size` default for the by-query write paths ("The size of the
/// scroll request that powers the operation").
const DEFAULT_BY_QUERY_SCROLL_SIZE: u64 = 1_000;

/// One member's paginated `_delete_by_query` run (#1019).
///
/// Shaped like the `_reindex` loop: flush the member first — `_id`-keyset
/// paging is only correct over on-disk segments (the memtable's field-sort
/// path does not order by `_id` reliably, so paging over unflushed docs
/// could skip or duplicate ids), and a failed flush aborts the delete rather
/// than under-deleting — then pull `scroll_size` pages sorted `_id: asc`
/// with a `search_after` cursor until an empty page or `max_docs`, deleting
/// per id. XERJ has no batch-delete API; per-id is the liveness-authoritative
/// semantic everywhere else, and ES's per-batch bulk is an internal detail.
///
/// Every page runs with the INTERNAL ids-only projection
/// (`SearchRequest::ids_only`, set here and never deserialisable from the
/// wire): the runner reads nothing from the hits but `hit.id`, so the search
/// phase skips `_source` materialisation entirely — previously the single
/// `size: 10_000` shot hydrated 10 100 full `Value` trees just to read ids,
/// the dominant RSS transient of a purge (the #950 follow-up headroom).
///
/// ES semantics matched: `total` is the exact match count when unlimited
/// (the collection snapshot / first page's `hits.total`, taken before any
/// deletion) or the processed count under `max_docs`; `batches` is the real
/// batch count; `noops`/`version_conflicts` are always 0 for this runner (an
/// unconditional per-id delete cannot conflict).
///
/// Two arms, same counters: `match_all` / `ids` selectors take the
/// single-pass id-set collection (`Index::matching_ids_sorted`) and delete it
/// in `scroll_size` batches; every other query shape takes the `_id`-keyset
/// paged loop below, whose pages run with the ids-only projection.
/// #1222 gate in front of both by-query runners' flush-first precondition:
/// does this query match anything, read through the ordinary search path
/// (active memtable + segments)?
///
/// A `_delete_by_query` / `_update_by_query` that matches nothing used to
/// flush the index unconditionally anyway — and a flush is a full memtable
/// drain into a segment, so a caller firing defensive no-match deletes pays
/// one segment per call. The corpus apply loop is that caller at scale:
/// #1224's cve-records build issued 402,744 no-match `delete_by_query`s,
/// and the node log showed 6,848 one-doc segments for ~3,005 writes — every
/// bulk's document flushed straight back out by the next op's delete. (The
/// idle-flush fingerprint #1222 first blamed is NOT this mechanism: that
/// node ran `flush_idle_secs = 0`, and a single write under that config
/// provably stays in the memtable.) Reading the probe through the search
/// path matters for the same reason: a matching doc that was never flushed
/// still counts, and the run proceeds to the flush arm exactly as before.
///
/// `Err` carries the error response value and propagates — an unanswered
/// probe never authorizes a skip, the same strictness as the client-side
/// twin in xerj-autoindex (#1225). A script resource limit during the probe
/// refuses the whole run, matching the fail-closed per-batch check below.
async fn by_query_matches_anything(
    idx: &std::sync::Arc<xerj_engine::Index>,
    query: &Value,
) -> Result<bool, Value> {
    let probe = match xerj_query::parse_request(&json!({ "query": query, "size": 0 })) {
        Ok(r) => r,
        Err(e) => {
            return Err(
                ApiError::new(xerj_common::XerjError::invalid_query(e.to_string())).into_value(),
            )
        }
    };
    let results = match idx.search(&probe).await {
        Ok(r) => r,
        Err(e) => return Err(ApiError::new(xerj_common::XerjError::from(e)).into_value()),
    };
    if let Some(reason) = &results.script_failure {
        return Err(script_limit_error_value(reason));
    }
    Ok(results.total.value > 0)
}

fn record_deleted(deleted_ids: &Option<std::sync::Arc<std::sync::Mutex<Vec<String>>>>, id: &str) {
    let Some(ids) = deleted_ids else {
        return;
    };
    ids.lock()
        .unwrap_or_else(|err| err.into_inner())
        .push(id.to_string());
}

async fn run_delete_by_query(
    idx: &std::sync::Arc<xerj_engine::Index>,
    query: &Value,
    max_docs: Option<u64>,
    scroll_size: usize,
) -> Value {
    run_delete_by_query_recorded(idx, query, max_docs, scroll_size, None).await
}

/// Box the single-node runner so `delete_by_query`'s future stays a pointer.
///
/// The cluster branch and this branch share one state machine. Leaving the
/// runner inline makes that machine as large as the runner, and allocating
/// it on a 2 MiB debug worker overflows before the cluster branch can
/// forward. `inline(never)` builds the runner in this frame, then the box
/// is what the handler stores. `[cluster] enabled = false` still runs this
/// runner and no other.
#[inline(never)]
fn pin_local_delete_by_query(
    idx: std::sync::Arc<xerj_engine::Index>,
    query: Value,
    max_docs: Option<u64>,
    scroll_size: usize,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Value> + Send>> {
    Box::pin(async move { run_delete_by_query(&idx, &query, max_docs, scroll_size).await })
}

/// Own the runner's arguments, then box it.
///
/// A primary's `_delete_by_query` is reached from the fan-out. Inlining the
/// runner into that future puts the search state machine on the caller's
/// stack and overflows a debug worker. The box is the same split
/// [`run_update_by_query_recorded_boxed`] uses.
#[inline(never)]
pub(crate) fn run_delete_by_query_recorded_boxed(
    idx: std::sync::Arc<xerj_engine::Index>,
    query: Value,
    max_docs: Option<u64>,
    scroll_size: usize,
    deleted_ids: Option<std::sync::Arc<std::sync::Mutex<Vec<String>>>>,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Value> + Send>> {
    Box::pin(async move {
        run_delete_by_query_recorded(&idx, &query, max_docs, scroll_size, deleted_ids).await
    })
}

/// Same run as `run_delete_by_query`. When `deleted_ids` is set, every id
/// this run removed is appended, including ids removed before a later page
/// refuses the rest. The cluster primary copies that list onto its replicas.
pub(crate) async fn run_delete_by_query_recorded(
    idx: &std::sync::Arc<xerj_engine::Index>,
    query: &Value,
    max_docs: Option<u64>,
    scroll_size: usize,
    deleted_ids: Option<std::sync::Arc<std::sync::Mutex<Vec<String>>>>,
) -> Value {
    let started = Instant::now();

    // #1222: no match, no flush (see `by_query_matches_anything`). The zero
    // response mirrors what both arms below already return for a no-match
    // run over a flushed index: `batches: 0` with `total: 0`.
    match by_query_matches_anything(idx, query).await {
        Ok(true) => {}
        Ok(false) => {
            return json!({
                "took": started.elapsed().as_millis() as u64,
                "timed_out": false,
                "total": 0,
                "deleted": 0,
                "batches": 0,
                "version_conflicts": 0,
                "noops": 0,
                "failures": [],
                "throttled_millis": 0,
                "requests_per_second": -1,
                "throttled_until_millis": 0,
            });
        }
        Err(value) => return value,
    }

    // Flush precondition (see doc comment). Propagated, not swallowed, for
    // the same reason as `reindex`: the flush is a precondition of the
    // paging being complete, so a failed flush must not be followed by a
    // purge that reports a `total` over an index it could not read
    // consistently.
    if let Err(e) = idx.flush().await {
        return ApiError::new(xerj_common::XerjError::internal(format!(
            "delete_by_query was not attempted: flushing the index failed ({e}); the purge \
             needs a flushed index to page over it without skipping documents"
        )))
        .into_value();
    }

    // Parse once for the fast-path eligibility check below. The handler
    // already validated the (page-1-shaped) query, so this cannot fail for a
    // request that got here; the paged arm re-parses per page only because it
    // rebuilds the body to attach `search_after`.
    let parsed_query = match xerj_query::parse_request(&json!({ "query": query })) {
        Ok(r) => r.query,
        Err(e) => {
            return ApiError::new(xerj_common::XerjError::invalid_query(e.to_string())).into_value()
        }
    };

    // #1019 single-pass fast path: for `match_all` / `ids` selectors the
    // whole live match set is collected once from the cached per-segment
    // `_id` maps (#950), then deleted in `scroll_size` batches — one O(N)
    // pass. The paged arm below re-scans every stored section once per page
    // (252 pages on the 252k-doc measurement corpus at the default
    // `scroll_size`), which dominated the wall time once per-page `_source`
    // hydration was gone. `None` — any other query shape, or a segment
    // without a complete id index — runs the paged arm unchanged. The
    // collection is admission-bracketed against concurrent flush
    // publications (#1023), so a purge storm cannot collect an empty set out
    // of another call's drain→publish window and report a clean no-op.
    if let Some(mut ids) = idx.matching_ids_sorted(&parsed_query).await {
        // ES `max_docs`: stop after N documents; `total` then reports the
        // processed count (the same rule the paged arm applies).
        let matched = ids.len() as u64;
        if let Some(cap) = max_docs {
            ids.truncate(cap as usize);
        }
        let mut processed: u64 = 0;
        let mut deleted: u64 = 0;
        let mut batches: u64 = 0;
        let mut failures: Vec<Value> = Vec::new();
        for chunk in ids.chunks(scroll_size) {
            batches += 1;
            for id in chunk {
                processed += 1;
                match idx.delete_document(id).await {
                    Ok(_) => {
                        deleted += 1;
                        record_deleted(&deleted_ids, id);
                    }
                    Err(e) => {
                        failures.push(json!({
                            "id": id,
                            "cause": { "reason": e.to_string() },
                        }));
                    }
                }
            }
        }
        let total = if max_docs.is_none() {
            // Never under-report if a concurrent writer extended the match
            // set past the collection snapshot mid-purge.
            matched.max(deleted)
        } else {
            processed
        };
        let took = started.elapsed().as_millis() as u64;
        return json!({
            "took": took,
            "timed_out": false,
            "total": total,
            "deleted": deleted,
            "batches": batches,
            "version_conflicts": 0,
            "noops": 0,
            "failures": failures,
            "throttled_millis": 0,
            "requests_per_second": -1,
            "throttled_until_millis": 0,
        });
    }

    let mut total: u64 = 0;
    let mut processed: u64 = 0;
    let mut deleted: u64 = 0;
    let mut batches: u64 = 0;
    let mut failures: Vec<Value> = Vec::new();
    // Keyset cursor: the last id of the previous page (the sole sort key is
    // `_id: asc`). `None` on the first page.
    let mut search_after: Option<String> = None;
    // Safety backstop only, mirroring reindex's `max_total`: with keyset
    // paging every page is a fresh top-N far below `max_result_window`, so
    // this just bounds a runaway loop.
    let max_total: u64 = 10_000_000;

    loop {
        let page = match max_docs {
            Some(cap) => (scroll_size as u64).min(cap.saturating_sub(processed)) as usize,
            None => scroll_size,
        };
        if page == 0 {
            break; // max_docs reached
        }

        let mut search_body_val = json!({
            "query": query,
            "size": page,
            "sort": [{ "_id": "asc" }],
            // Belt only — the ids-only projection below is the load-bearing
            // `_source` cut (`_source: false` alone keeps raw sources for
            // fields/highlight resolution).
            "_source": false,
        });
        if let Some(ref cursor) = search_after {
            search_body_val["search_after"] = json!([cursor]);
        }
        let mut search_req = match xerj_query::parse_request(&search_body_val)
            .map_err(|e| xerj_common::XerjError::invalid_query(e.to_string()))
        {
            Ok(r) => r,
            Err(e) => return ApiError::new(e).into_value(),
        };
        // Internal-only projection hint — `parse_request` can never set it.
        search_req.ids_only = true;

        let results = match idx.search(&search_req).await {
            Ok(r) => r,
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_value(),
        };
        // A script resource limit makes matching fail-closed, so the
        // selection is a subset of what the caller asked to delete — checked
        // PER BATCH, before a single id of the page is deleted. Deleting
        // that subset and reporting success is both destructive and wrong;
        // refuse instead.
        if let Some(reason) = &results.script_failure {
            return script_limit_error_value(reason);
        }

        if results.hits.is_empty() {
            break;
        }
        batches += 1;
        // Page 1's `hits.total` is the EXACT pre-delete match count (later
        // pages run over an already-shrunk live set). Under `max_docs` ES
        // reports the processed count instead.
        if max_docs.is_none() && total == 0 {
            total = results.total.value;
        }

        // Capture the cursor before the loop consumes `results.hits`.
        let last_id = results.hits.last().map(|h| h.id.clone());
        for hit in results.hits {
            processed += 1;
            match idx.delete_document(&hit.id).await {
                Ok(_) => {
                    deleted += 1;
                    record_deleted(&deleted_ids, &hit.id);
                }
                Err(e) => {
                    failures.push(json!({
                        "id": hit.id,
                        "cause": { "reason": e.to_string() },
                    }));
                }
            }
        }

        match last_id {
            Some(id) => search_after = Some(id),
            None => break,
        }
        if processed >= max_total {
            break;
        }
    }

    if max_docs.is_none() {
        // Never under-report if a concurrent writer extended the match set
        // past page 1's snapshot count mid-purge.
        total = total.max(processed);
    } else {
        total = processed;
    }

    let took = started.elapsed().as_millis() as u64;
    json!({
        "took": took,
        "timed_out": false,
        "total": total,
        "deleted": deleted,
        "batches": batches,
        "version_conflicts": 0,
        "noops": 0,
        "failures": failures,
        "throttled_millis": 0,
        "requests_per_second": -1,
        "throttled_until_millis": 0,
    })
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_update_by_query
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct UpdateByQueryBody {
    pub query: Option<Value>,
    /// Script block (`ctx._source.*` mutations applied per matched doc).
    pub script: Option<Value>,
    /// ES `max_docs`: "Maximum number of documents to process. Defaults to
    /// all documents." `total` then reports the processed count.
    #[serde(default)]
    pub max_docs: Option<u64>,
    /// ES `scroll_size`: "Size of the scroll request that powers the
    /// operation. Defaults to 1000."
    #[serde(default)]
    pub scroll_size: Option<u64>,
}

/// Why `pipeline` cannot run on this engine, in the same words the
/// `_update_by_query?pipeline=` handler has always used.
pub(crate) fn unrunnable_pipeline_reason(
    engine: &xerj_engine::Engine,
    pipeline: &str,
) -> Option<String> {
    if !engine.pipelines.contains_key(pipeline) {
        Some(format!("pipeline with id [{pipeline}] does not exist"))
    } else {
        engine.unrunnable_pipelines.get(pipeline).map(|reason| {
            format!(
                "pipeline with id [{pipeline}] cannot be run: {}",
                reason.value()
            )
        })
    }
}

pub(crate) fn pipeline_rejected_body(reason: &str) -> Value {
    json!({
        "error": {
            "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
            "type": "illegal_argument_exception",
            "reason": reason,
        },
        "status": 400,
    })
}

/// Build the cluster fan-out off this handler's state machine.
///
/// `update_by_query` is already large enough that a debug build's worker
/// stack (2 MiB, the `#[tokio::test]` default) overflows once a second copy
/// of the runner is inlined into the same future. `[cluster] enabled = false`
/// never polls the fan-out, so the future is allocated here and only the
/// pointer is stored on the handler. The server runtime is 4 MiB; this keeps
/// the single-node path the size it was before the fan-out existed.
fn begin_cluster_update_by_query(
    state: AppState,
    index_names: Vec<String>,
    parts: crate::cluster_shard::UpdateByQueryParts,
    wait_for_completion: bool,
    handle: crate::state::TaskHandle,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Response> + Send>> {
    Box::pin(cluster_update_by_query(
        state,
        index_names,
        parts,
        wait_for_completion,
        handle,
    ))
}

async fn cluster_update_by_query(
    state: AppState,
    index_names: Vec<String>,
    parts: crate::cluster_shard::UpdateByQueryParts,
    wait_for_completion: bool,
    handle: crate::state::TaskHandle,
) -> Response {
    if !wait_for_completion {
        let task_key = handle.key().to_string();
        let spawned_key = task_key.clone();
        let tasks = state.tasks.clone();
        let names = index_names.clone();
        // The fan-out calls `Engine::get_index` on the detached task, so
        // the request's visibility rule has to come with it. See
        // `xerj_engine::index_guard`.
        let rule = xerj_engine::index_guard::current();
        tokio::spawn(xerj_engine::index_guard::scoped_opt(rule, async move {
            let mut results = Vec::with_capacity(names.len());
            for name in &names {
                results.push(
                    crate::cluster_shard::pin_update_by_query_on_primaries(
                        state.clone(),
                        name.clone(),
                        parts.clone(),
                    )
                    .await,
                );
            }
            tasks.complete(&spawned_key, aggregate_by_query_results(results, "updated"));
            drop(handle);
        }));
        return Json(json!({ "task": task_key })).into_response();
    }
    let mut results = Vec::with_capacity(index_names.len());
    for name in &index_names {
        results.push(
            crate::cluster_shard::pin_update_by_query_on_primaries(
                state.clone(),
                name.clone(),
                parts.clone(),
            )
            .await,
        );
    }
    drop(handle);
    by_query_response(aggregate_by_query_results(results, "updated"))
}

/// Own the runner's arguments, then box it.
///
/// A primary's `_update_by_query` runs on the coordinator's task when this
/// node is that primary. Inlining the runner into the fan-out future puts
/// two copies of it on the stack under `search_inner` and overflows a debug
/// worker. The box is the same split `MemoryShardRpc` uses for a remote
/// primary: the heavy future is not built on the caller's state machine.
pub(crate) fn run_update_by_query_recorded_boxed(
    idx: std::sync::Arc<xerj_engine::Index>,
    query: Value,
    max_docs: Option<u64>,
    scroll_size: usize,
    script: Option<(String, Value)>,
    pipeline: Option<(std::sync::Arc<xerj_engine::Engine>, String)>,
    updated_ids: Option<std::sync::Arc<std::sync::Mutex<Vec<String>>>>,
) -> std::pin::Pin<Box<dyn std::future::Future<Output = Value> + Send>> {
    Box::pin(async move {
        run_update_by_query_recorded(
            &idx,
            &query,
            max_docs,
            scroll_size,
            script,
            pipeline,
            updated_ids,
        )
        .await
    })
}

pub async fn update_by_query(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<HashMap<String, String>>,
    Json(body): Json<UpdateByQueryBody>,
) -> impl IntoResponse {
    let query_val = body.query.clone().unwrap_or(json!({ "match_all": {} }));
    // Fan the selector out to every member of a multi-index alias (#450), with
    // any alias filter already ANDed into the query.
    let (indices, index_names, effective_query) =
        match resolve_by_query_targets(&state, &index, query_val).await {
            Ok(t) => t,
            Err(e) => return ApiError::new(e).into_response(),
        };

    // Validate the (alias-filter-ANDed) query once, up front, so a malformed
    // body is an immediate 400 before a task is registered or any member is
    // touched — the runner below re-parses per batch as the cursor advances
    // (#1022: same shape as `_delete_by_query`).
    let scroll_size = body
        .scroll_size
        .unwrap_or(DEFAULT_BY_QUERY_SCROLL_SIZE)
        .clamp(1, 10_000) as usize;
    let validation_body = json!({
        "query": effective_query,
        "size": scroll_size,
        "from": 0,
        "sort": [{ "_id": "asc" }],
    });
    if let Err(e) = xerj_query::parse_request(&validation_body) {
        return ApiError::new(xerj_common::XerjError::invalid_query(e.to_string())).into_response();
    }

    // Optional painless script — when present, each matched hit's source is
    // mutated by the script and re-indexed under its EXISTING `_id`, so the
    // update happens in place (no duplicate-`_id` docs are appended).
    let script = body.script.as_ref().map(extract_update_script);

    // `?pipeline=` — every matched document is run through it before being
    // written back. Issue #204: the parameter used to be read by nothing, so
    // `_update_by_query?pipeline=redact` reported `"updated": N` having
    // rewritten every document EXACTLY as it was. Resolved and validated
    // before any document is touched: an unknown or unrunnable name fails the
    // whole request rather than half of it.
    //
    // With a cluster handle the pipeline runs on each primary, which is where
    // the current source is. The check is that primary's, before it writes.
    // Single-node mode still refuses here, on the node that accepted the call.
    let pipeline_name = match params.get("pipeline").map(String::as_str) {
        None | Some("_none") => None,
        Some(p) => Some(p.to_string()),
    };
    let pipeline = if state.engine.has_cluster() {
        None
    } else if let Some(p) = pipeline_name.as_deref() {
        if let Some(reason) = unrunnable_pipeline_reason(&state.engine, p) {
            return (
                StatusCode::BAD_REQUEST,
                Json(pipeline_rejected_body(&reason)),
            )
                .into_response();
        }
        Some((state.engine.clone(), p.to_string()))
    } else {
        None
    };

    // ES defaults `wait_for_completion` to true (synchronous); only an
    // explicit `false` switches to the async `{"task": "node:id"}` form.
    let wait_for_completion = params
        .get("wait_for_completion")
        .map(|v| v != "false")
        .unwrap_or(true);
    let handle = state.tasks.register("indices:data/write/update/byquery");

    if state.engine.has_cluster() {
        let parts = crate::cluster_shard::UpdateByQueryParts {
            query: effective_query,
            script,
            pipeline: pipeline_name,
            max_docs: body.max_docs,
            scroll_size,
        };
        return begin_cluster_update_by_query(
            state,
            index_names,
            parts,
            wait_for_completion,
            handle,
        )
        .await;
    }

    if !wait_for_completion {
        let task_key = handle.key().to_string();
        let spawned_key = task_key.clone();
        let tasks = state.tasks.clone();
        let task_query = effective_query.clone();
        let task_max_docs = body.max_docs;
        // Same reasoning as the `_delete_by_query` spawn above: the task owns
        // the already-authorized `Index` handles and can reach no other index.
        tokio::spawn(async move {
            let mut results = Vec::with_capacity(indices.len());
            for idx in &indices {
                results.push(
                    run_update_by_query(
                        idx,
                        &task_query,
                        task_max_docs,
                        scroll_size,
                        script.clone(),
                        pipeline.clone(),
                    )
                    .await,
                );
            }
            tasks.complete(&spawned_key, aggregate_by_query_results(results, "updated"));
            drop(handle);
        });
        return Json(json!({ "task": task_key })).into_response();
    }

    let mut results = Vec::with_capacity(indices.len());
    for idx in &indices {
        results.push(
            run_update_by_query(
                idx,
                &effective_query,
                body.max_docs,
                scroll_size,
                script.clone(),
                pipeline.clone(),
            )
            .await,
        );
    }
    drop(handle);
    by_query_response(aggregate_by_query_results(results, "updated"))
}

/// Wall-clock ceiling for the Painless work one scripted-update request may
/// do, mirroring the 30 s `_search` falls back to when a request names no
/// timeout. It bounds the request as a whole — every statement, every
/// document — rather than any single evaluation, which is the only bound that
/// survives `_update_by_query`'s hit loop and its detached
/// `wait_for_completion=false` form.
const SCRIPTED_UPDATE_BUDGET_MS: u64 = 30_000;

/// Run `doc` through `pipeline`, or say why it could not be run.
///
/// Issue #204: every caller must get a document that really went through the
/// pipeline, or an error. There is deliberately no "return the input unchanged"
/// branch — that is precisely how an unrun redaction became a `200`.
///
/// A `drop` action is an error here rather than a deletion:
/// `_update_by_query` updates documents in place and has no delete path, so
/// honouring `drop` is not something this endpoint can do. Saying so per
/// document beats writing the document as if the processor had not asked.
fn apply_pipeline_or_fail(
    engine: &xerj_engine::Engine,
    pipeline: &str,
    doc_id: &str,
    doc: Value,
) -> std::result::Result<Value, String> {
    match engine.process_through_pipeline(pipeline, vec![doc]) {
        Ok(mut results) if !results.is_empty() => {
            let (action, transformed) = results.remove(0);
            if matches!(action, xerj_wasm::pipeline::ProcessAction::Drop) {
                return Err(format!(
                    "pipeline [{pipeline}] dropped document [{doc_id}]; _update_by_query \
                     updates in place and cannot delete it, so the document was left \
                     unchanged"
                ));
            }
            Ok(transformed)
        }
        Ok(_) => Err(format!(
            "pipeline [{pipeline}] returned no document for [{doc_id}]"
        )),
        Err(e) => Err(format!("pipeline [{pipeline}] failed: {e}")),
    }
}

/// One member's paginated `_update_by_query` run (#1022).
///
/// Shaped like `run_delete_by_query` (#1019), with one extra hazard delete
/// did not have: the updates themselves repopulate the memtable, and a later
/// page's search must never page over unflushed state — the memtable's
/// field-sort path does not order by `_id` reliably, so a rewritten doc with
/// `_id <= cursor` could resurface on a later page and get the script applied
/// TWICE (silent corruption, versus delete's idempotent duplicate). The paged
/// arm therefore flushes after every batch that mutated at least one doc
/// (mirroring ES's per-batch refresh), keeping each page search over on-disk
/// segments where the immutable-segment scan + cursor decline are proven.
///
/// Two arms, same counters:
///
/// * script mode over a `match_all` / `ids` selector takes the #1019
///   single-pass id collection (`Index::matching_ids_sorted`) and transforms
///   per id in `scroll_size` batches — NO hydration search at all: the
///   per-id serialized transform (`transform_document_serialized`) re-reads
///   and holds ONE doc at a time, which is a strictly tighter bound than any
///   page size. No per-batch flush is needed because this arm never
///   re-searches (the id set is fixed at the snapshot, ES's documented
///   start-of-run collection semantics).
///
/// * everything else takes the `_id`-keyset paged loop. Script-mode pages run
///   with the INTERNAL ids-only projection (`SearchRequest::ids_only`, never
///   deserialisable from the wire) — the transform re-reads each source
///   itself. No-script pages keep sources attached, bounded at one
///   `scroll_size` page of `Value` trees — the same bound one ES scroll batch
///   materialises.
///
/// ES semantics matched (#1019's rule set, the same transport contract):
/// `total` is the exact match count when unlimited (page 1's `hits.total`,
/// the pre-mutation snapshot — later pages run over a mutated index) or the
/// processed count under `max_docs`; `batches` is the real batch count;
/// `version_conflicts` stays 0 (the transform is serialized per id and the
/// no-script write is blind — XERJ cannot produce a version conflict);
/// `noops` stays 0 (the mini-painless tolerates `ctx.*` statements without
/// skipping the write).
fn record_updated(updated_ids: &Option<std::sync::Arc<std::sync::Mutex<Vec<String>>>>, id: &str) {
    let Some(ids) = updated_ids else {
        return;
    };
    ids.lock()
        .unwrap_or_else(|err| err.into_inner())
        .push(id.to_string());
}

async fn run_update_by_query(
    idx: &std::sync::Arc<xerj_engine::Index>,
    query: &Value,
    max_docs: Option<u64>,
    scroll_size: usize,
    script: Option<(String, Value)>,
    pipeline: Option<(std::sync::Arc<xerj_engine::Engine>, String)>,
) -> Value {
    run_update_by_query_recorded(idx, query, max_docs, scroll_size, script, pipeline, None).await
}

pub(crate) async fn run_update_by_query_recorded(
    idx: &std::sync::Arc<xerj_engine::Index>,
    query: &Value,
    max_docs: Option<u64>,
    scroll_size: usize,
    script: Option<(String, Value)>,
    pipeline: Option<(std::sync::Arc<xerj_engine::Engine>, String)>,
    updated_ids: Option<std::sync::Arc<std::sync::Mutex<Vec<String>>>>,
) -> Value {
    let started = Instant::now();

    // #1222: no match, no flush (see `by_query_matches_anything`) — the
    // update twin of the delete gate, same zero shape the arms below return
    // for a no-match run over a flushed index.
    match by_query_matches_anything(idx, query).await {
        Ok(true) => {}
        Ok(false) => {
            return json!({
                "took": started.elapsed().as_millis() as u64,
                "timed_out": false,
                "total": 0,
                "updated": 0,
                "deleted": 0,
                "batches": 0,
                "version_conflicts": 0,
                "noops": 0,
                "failures": [],
                "throttled_millis": 0,
                "requests_per_second": -1,
                "throttled_until_millis": 0,
            });
        }
        Err(value) => return value,
    }

    // Flush precondition (see doc comment): the keyset paging below is only
    // correct over on-disk segments, and the single-pass id collection reads
    // the flushed segments' id maps. Propagated, not swallowed, for the same
    // reason as `reindex` and `run_delete_by_query`: the flush is a
    // precondition of the run being complete, so a failed flush must not be
    // followed by an update that reports a `total` over an index it could not
    // read consistently.
    if let Err(e) = idx.flush().await {
        return ApiError::new(xerj_common::XerjError::internal(format!(
            "update_by_query was not attempted: flushing the index failed ({e}); the update \
             needs a flushed index to page over it without skipping or duplicating documents"
        )))
        .into_value();
    }

    // Parse once for the single-pass eligibility check below. The handler
    // already validated the (page-1-shaped) query, so this cannot fail for a
    // request that got here; the paged arm re-parses per page only because it
    // rebuilds the body to attach `search_after`.
    let parsed_query = match xerj_query::parse_request(&json!({ "query": query })) {
        Ok(r) => r.query,
        Err(e) => {
            return ApiError::new(xerj_common::XerjError::invalid_query(e.to_string())).into_value()
        }
    };

    // One budget for the whole request, the way `_search` already gets one —
    // and it now spans the page searches too, since the search phases are part
    // of the request it bounds. Publishing a single deadline bounds the
    // request however it is spelled, and the fault sink turns a resource-limit
    // trip into one honest error instead of the same failure recorded once per
    // batch.
    let deadline = Instant::now() + Duration::from_millis(SCRIPTED_UPDATE_BUDGET_MS);
    // `Box::pin`: the loop body below is a large async state machine, and the
    // deadline/fault wrappers store their future INLINE (`F: Future`, not
    // `Pin<Box<dyn Future>>`), so unboxed the whole nested machine lands on
    // the tokio worker's 2 MiB stack — measured as a stack overflow in debug
    // builds. Boxing moves it to the heap; the per-iteration cost is one
    // indirection.
    let (outcome, fault) = xerj_engine::painless::with_script_fault_capture(
        xerj_engine::painless::with_script_deadline(
            deadline,
            Box::pin(async move {
                // ── Single-pass arm: script mode, match_all / ids selectors ──────
                //
                // The whole live match set is collected once from the cached
                // per-segment `_id` maps (#950), then transformed per id in
                // `scroll_size` batches — one O(N) id materialisation, no
                // per-page stored-section re-scan, no `_source` hydration outside
                // the per-id transform. The collection is admission-bracketed
                // against concurrent flush publications (#1023): without the
                // bracket, sixteen concurrent runners each flushed, the one
                // flush carrying the doc held the drain→publish window open,
                // and the other fifteen collected EMPTY match sets and
                // reported total:0/updated:0/failures:[] — a silent no-op.
                if script.is_some() {
                    if let Some(mut ids) = idx.matching_ids_sorted(&parsed_query).await {
                        // ES `max_docs`: stop after N documents; `total` then
                        // reports the processed count (the same rule the paged
                        // arm applies).
                        let matched = ids.len() as u64;
                        if let Some(cap) = max_docs {
                            ids.truncate(cap as usize);
                        }
                        let mut processed: u64 = 0;
                        let mut updated: u64 = 0;
                        let mut batches: u64 = 0;
                        let mut failures: Vec<Value> = Vec::new();
                        let mut timed_out = false;
                        'single: for chunk in ids.chunks(scroll_size) {
                            batches += 1;
                            for id in chunk {
                                // The deadline bounds each evaluation, but not the
                                // loop (see the paged arm's per-hit check for the
                                // reasoning) — the loop stops on its own and says
                                // that it did.
                                if Instant::now() >= deadline {
                                    timed_out = true;
                                    break 'single;
                                }
                                processed += 1;
                                if let Some(f) = transform_one(idx, id, &script, &pipeline).await {
                                    match f {
                                        Ok(()) => {
                                            updated += 1;
                                            record_updated(&updated_ids, id);
                                        }
                                        Err(reason) => failures.push(json!({
                                            "id": id,
                                            "cause": { "reason": reason },
                                        })),
                                    }
                                }
                                // `None` = the doc vanished mid-run: skip silently,
                                // no counter — the same outcome the pre-fix
                                // `hit.source.is_null()` guard produced.
                            }
                        }
                        let total = if max_docs.is_none() {
                            matched.max(updated)
                        } else {
                            processed
                        };
                        return Ok((total, updated, batches, failures, timed_out));
                    }
                }

                // ── Paged arm: every other shape ─────────────────────────────────
                let mut total: u64 = 0;
                let mut processed: u64 = 0;
                let mut updated: u64 = 0;
                let mut batches: u64 = 0;
                let mut failures: Vec<Value> = Vec::new();
                let mut timed_out = false;
                // Keyset cursor: the last id of the previous page (the sole sort
                // key is `_id: asc`). `None` on the first page.
                let mut search_after: Option<String> = None;
                // Safety backstop only, mirroring reindex's `max_total`.
                let max_total: u64 = 10_000_000;

                loop {
                    let page = match max_docs {
                        Some(cap) => {
                            (scroll_size as u64).min(cap.saturating_sub(processed)) as usize
                        }
                        None => scroll_size,
                    };
                    if page == 0 {
                        break; // max_docs reached
                    }

                    let mut search_body_val = json!({
                        "query": query,
                        "size": page,
                        "sort": [{ "_id": "asc" }],
                        // Belt only — under the ids-only projection this is not
                        // even consulted for the source cut; on the no-script
                        // arm it is overridden below because that arm NEEDS its
                        // page's sources.
                        "_source": false,
                    });
                    if script.is_none() {
                        // No-script re-index-in-place: the page search itself
                        // hydrates JUST this page's sources (bounded by
                        // `scroll_size` — the same bound one ES scroll batch
                        // materialises; no second ids-then-hydrate query needed).
                        search_body_val["_source"] = json!(true);
                    }
                    if let Some(ref cursor) = search_after {
                        search_body_val["search_after"] = json!([cursor]);
                    }
                    let mut search_req = match xerj_query::parse_request(&search_body_val)
                        .map_err(|e| xerj_common::XerjError::invalid_query(e.to_string()))
                    {
                        Ok(r) => r,
                        Err(e) => return Err(ApiError::new(e).into_value()),
                    };
                    // Internal-only projection hint for script-mode pages: the
                    // per-id transform re-reads the source itself, so the page
                    // carries nothing but ids. `parse_request` can never set it.
                    if script.is_some() {
                        search_req.ids_only = true;
                    }

                    let results = match idx.search(&search_req).await {
                        Ok(r) => r,
                        Err(e) => {
                            return Err(ApiError::new(xerj_common::XerjError::from(e)).into_value())
                        }
                    };
                    // A script resource limit makes matching fail-closed, so the
                    // selection is a subset of what the caller asked to update —
                    // checked PER BATCH, before a single doc of the page is
                    // touched. Updating that subset and reporting success is both
                    // destructive and wrong; refuse instead.
                    if let Some(reason) = &results.script_failure {
                        return Err(script_limit_error_value(reason));
                    }

                    if results.hits.is_empty() {
                        break;
                    }
                    batches += 1;
                    // Page 1's `hits.total` is the EXACT pre-mutation match count
                    // (later pages run over an already-mutated index). Under
                    // `max_docs` ES reports the processed count instead.
                    if max_docs.is_none() && total == 0 {
                        total = results.total.value;
                    }

                    // Capture the cursor before the loop consumes `results.hits`.
                    let last_id = results.hits.last().map(|h| h.id.clone());
                    let mut mutated_in_batch: u64 = 0;
                    for hit in results.hits {
                        // The deadline bounds each evaluation, but not the loop:
                        // the per-evaluation slice is clamped to a floor even once
                        // the request deadline has passed — so an ordinary script
                        // is not cut off just because a slow search overran — and
                        // that floor times a whole index is unbounded CPU from one
                        // request. The loop has to stop on its own, and say that
                        // it did rather than reporting `timed_out: false` over a
                        // run that was cut short.
                        if Instant::now() >= deadline {
                            timed_out = true;
                            break;
                        }
                        processed += 1;
                        if script.is_some() {
                            // ids-only hits carry `source: Null` BY CONSTRUCTION —
                            // the old `hit.source.is_null()` skip must NOT run
                            // here or every hit would be skipped; liveness is
                            // delegated to the transform's `Ok(Ok(None))` (the
                            // doc vanished mid-run).
                            if let Some(f) = transform_one(idx, &hit.id, &script, &pipeline).await {
                                match f {
                                    Ok(()) => {
                                        updated += 1;
                                        mutated_in_batch += 1;
                                        record_updated(&updated_ids, &hit.id);
                                    }
                                    Err(reason) => failures.push(json!({
                                        "id": hit.id,
                                        "cause": { "reason": reason },
                                    })),
                                }
                            }
                        } else {
                            // No script: preserve the historical re-index-in-place
                            // behavior, with `?pipeline=` applied when one was
                            // named.
                            if hit.source.is_null() {
                                continue;
                            }
                            let doc = match pipeline.as_ref() {
                                None => hit.source,
                                Some((engine, name)) => {
                                    match apply_pipeline_or_fail(engine, name, &hit.id, hit.source)
                                    {
                                        Ok(d) => d,
                                        Err(reason) => {
                                            failures.push(json!({
                                                "id": hit.id,
                                                "cause": { "reason": reason },
                                            }));
                                            continue;
                                        }
                                    }
                                }
                            };
                            match idx.index_document(Some(hit.id.clone()), doc).await {
                                Ok(_) => {
                                    updated += 1;
                                    mutated_in_batch += 1;
                                    record_updated(&updated_ids, &hit.id);
                                }
                                Err(e) => {
                                    failures.push(json!({
                                        "id": hit.id,
                                        "cause": { "reason": e.to_string() },
                                    }));
                                }
                            }
                        }
                    }

                    // MID-RUN REWRITE HAZARD (see doc comment): this batch's
                    // writes are memtable-resident, and the next page's search
                    // must not page over unflushed state. Flush before searching
                    // again — the updated docs carry `_id <= cursor`, so the next
                    // page's cursor decline skips them in one compare. A failed
                    // flush aborts the run rather than letting the next page
                    // search unflushed state.
                    if mutated_in_batch > 0 {
                        if let Err(e) = idx.flush().await {
                            return Err(ApiError::new(xerj_common::XerjError::internal(format!(
                                "update_by_query aborted mid-run: flushing a batch failed ({e}); \
                             paging on without the flush could apply the script twice"
                            )))
                            .into_value());
                        }
                    }

                    match last_id {
                        Some(id) => search_after = Some(id),
                        None => break,
                    }
                    if processed >= max_total {
                        break;
                    }
                }

                if max_docs.is_none() {
                    // Never under-report if a concurrent writer extended the match
                    // set past page 1's snapshot count mid-run.
                    total = total.max(processed);
                } else {
                    total = processed;
                }

                Ok((total, updated, batches, failures, timed_out))
            }),
        ),
    )
    .await;
    // A trip is a property of the request, not of the document that happened
    // to be in flight: report it once and refuse the run rather than claiming
    // a partial update succeeded.
    if let Some(reason) = fault {
        return script_limit_error_value(&reason);
    }
    let (total, updated, batches, failures, timed_out) = match outcome {
        Ok(t) => t,
        Err(e) => return e,
    };

    let took = started.elapsed().as_millis() as u64;
    json!({
        "took": took,
        "timed_out": timed_out,
        "total": total,
        "updated": updated,
        "deleted": 0,
        "batches": batches,
        "version_conflicts": 0,
        "noops": 0,
        "failures": failures,
        "throttled_millis": 0,
        "requests_per_second": -1,
        "throttled_until_millis": 0,
    })
}

/// Apply one `_update_by_query` hit: the scripted transform (with the optional
/// pipeline inside the same serialized publication bracket), shared by the
/// single-pass and paged arms.
///
/// `None` = the document vanished mid-run (`Ok(Ok(None))` from the engine):
/// there is nothing to update and no failure to report. `Some(Err(reason))`
/// is a per-document failure (script/pipeline error or write error).
#[allow(clippy::type_complexity)]
async fn transform_one(
    idx: &std::sync::Arc<xerj_engine::Index>,
    id: &str,
    script: &Option<(String, Value)>,
    pipeline: &Option<(std::sync::Arc<xerj_engine::Engine>, String)>,
) -> Option<std::result::Result<(), String>> {
    let (src, params) = script.as_ref()?;
    if src.is_empty() {
        return Some(Err("script source is required".to_string()));
    }
    let result = idx
        .transform_document_serialized(id, None, |mut current| {
            apply_painless_update(&mut current, src, params)?;
            // ES runs `?pipeline=` on the result of the script, and so do we —
            // inside the same serialized transform, so the pipeline sees
            // exactly the document that is about to be written.
            if let Some((engine, name)) = pipeline.as_ref() {
                current = apply_pipeline_or_fail(engine, name, id, current)?;
            }
            Ok::<_, String>(current)
        })
        .await;
    match result {
        Ok(Ok(Some(_))) => Some(Ok(())),
        Ok(Ok(None)) => None,
        Ok(Err(error)) => Some(Err(error)),
        Err(error) => Some(Err(error.to_string())),
    }
}

#[cfg(test)]
mod scripted_update_publication_tests {
    use super::*;
    use std::sync::Arc;
    use xerj_common::{
        config::{Config, WalSync},
        metrics::Metrics,
    };
    use xerj_engine::Engine;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir");
        let path = dir.keep();
        let mut config = Config::default();
        config.server.data_dir = path.to_string_lossy().into_owned();
        config.storage.wal_sync = WalSync::Async;
        let metrics = Metrics::new().expect("metrics");
        let engine = Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn concurrent_scripted_update_requests_preserve_every_increment() {
        let state = test_state();
        let idx = state.engine.get_or_create_index("script-counter").unwrap();
        idx.index_document(Some("counter".into()), json!({"n": 0}))
            .await
            .unwrap();

        let start = Arc::new(tokio::sync::Barrier::new(33));
        let mut tasks = Vec::new();
        for _ in 0..32 {
            let state = state.clone();
            let start = Arc::clone(&start);
            tasks.push(tokio::spawn(async move {
                start.wait().await;
                update_doc(
                    State(state),
                    Path(("script-counter".to_string(), "counter".to_string())),
                    Query(UpdateDocParams::default()),
                    bytes::Bytes::from(
                        serde_json::to_vec(&json!({"script": "ctx._source.n += 1"}))
                            .expect("script update body"),
                    ),
                )
                .await
                .into_response()
                .status()
            }));
        }
        start.wait().await;
        for task in tasks {
            assert!(task.await.unwrap().is_success());
        }

        assert_eq!(idx.get_document("counter").await.unwrap().unwrap()["n"], 32);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn concurrent_scripted_update_by_query_preserves_every_increment() {
        let state = test_state();
        let idx = state
            .engine
            .get_or_create_index("script-query-counter")
            .unwrap();
        idx.index_document(Some("counter".into()), json!({"n": 0}))
            .await
            .unwrap();

        let start = Arc::new(tokio::sync::Barrier::new(17));
        let mut tasks = Vec::new();
        for _ in 0..16 {
            let idx = Arc::clone(&idx);
            let start = Arc::clone(&start);
            tasks.push(tokio::spawn(async move {
                start.wait().await;
                run_update_by_query(
                    &idx,
                    &json!({ "match_all": {} }),
                    None,
                    DEFAULT_BY_QUERY_SCROLL_SIZE as usize,
                    Some(("ctx._source.n += 1".into(), json!({}))),
                    None,
                )
                .await
            }));
        }
        start.wait().await;
        for task in tasks {
            assert_eq!(task.await.unwrap()["failures"], json!([]));
        }

        assert_eq!(idx.get_document("counter").await.unwrap().unwrap()["n"], 16);
    }

    /// #1023 delete twin: `run_delete_by_query` flushes then collects the
    /// match set through the SAME `matching_ids_sorted` enumeration, so it
    /// shares the update arm's hole — pre-fix, a concurrent purge storm
    /// collected empty sets out of another runner's drain→publish window and
    /// reported clean no-ops. No failures may be swallowed, the doc must be
    /// purged, and at least one runner must report it (a runner collecting
    /// after another's delete legitimately reports `total:0` — ES's
    /// start-of-run collection semantics; the deterministic lost-work proof
    /// is the update twin above).
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn concurrent_delete_by_query_purges_the_document() {
        let state = test_state();
        let idx = state
            .engine
            .get_or_create_index("query-purge-counter")
            .unwrap();
        idx.index_document(Some("counter".into()), json!({"n": 0}))
            .await
            .unwrap();

        let start = Arc::new(tokio::sync::Barrier::new(17));
        let mut tasks = Vec::new();
        for _ in 0..16 {
            let idx = Arc::clone(&idx);
            let start = Arc::clone(&start);
            tasks.push(tokio::spawn(async move {
                start.wait().await;
                run_delete_by_query(
                    &idx,
                    &json!({ "match_all": {} }),
                    None,
                    DEFAULT_BY_QUERY_SCROLL_SIZE as usize,
                )
                .await
            }));
        }
        start.wait().await;
        let mut seen: u64 = 0;
        for task in tasks {
            let out = task.await.unwrap();
            assert_eq!(out["failures"], json!([]), "no swallowed purge errors");
            seen += out["total"].as_u64().unwrap_or(0);
        }
        assert!(seen >= 1, "at least one runner must have matched the doc");

        assert_eq!(
            idx.get_document("counter").await.unwrap(),
            None,
            "the doc must actually be purged, not just reported"
        );
    }

    /// #1222: a no-match `_delete_by_query` (and its `_update_by_query`
    /// twin) must NOT flush. The flush-first is the runners' paging
    /// precondition (#1019), but a no-op run pages over nothing — and the
    /// corpus apply loop fires one defensive no-match delete per group op
    /// (#1224: 402,744 on cve-records), so pre-fix every bulk's document
    /// was flushed straight back out into a one-doc segment (6,848 of them
    /// for ~3,005 writes in the node log; ~121 files each on the cvelistV5
    /// dynamic mapping). Observable here at the unit level: the
    /// just-written document stays IN the memtable after the no-match run.
    #[tokio::test]
    async fn no_match_by_query_does_not_flush() {
        let state = test_state();
        let idx = state
            .engine
            .get_or_create_index("noop-byquery-no-flush")
            .unwrap();
        idx.index_document(Some("d1".into()), json!({"kind": "keep"}))
            .await
            .unwrap();
        assert!(idx.memtable_bytes() > 0, "precondition: doc unflushed");

        let out = run_delete_by_query(
            &idx,
            &json!({ "term": { "kind": "absent" } }),
            None,
            DEFAULT_BY_QUERY_SCROLL_SIZE as usize,
        )
        .await;
        assert_eq!(out["total"], json!(0));
        assert_eq!(out["deleted"], json!(0));
        assert_eq!(out["batches"], json!(0));
        assert_eq!(out["failures"], json!([]));
        assert!(
            idx.memtable_bytes() > 0,
            "a no-match delete must not drain the memtable (#1222: the flush \
             itself was the per-write segment storm)"
        );

        let out = run_update_by_query(
            &idx,
            &json!({ "term": { "kind": "absent" } }),
            None,
            DEFAULT_BY_QUERY_SCROLL_SIZE as usize,
            None,
            None,
        )
        .await;
        assert_eq!(out["total"], json!(0));
        assert_eq!(out["updated"], json!(0));
        assert_eq!(out["failures"], json!([]));
        assert!(
            idx.memtable_bytes() > 0,
            "a no-match update must not drain the memtable either"
        );
    }

    /// The #1222 gate must not weaken the real run: a matching
    /// `_delete_by_query` still flushes, purges, and reports ES totals —
    /// the unflushed matching doc is visible to the gate's probe (ordinary
    /// search path), so it takes the flush arm exactly as before.
    #[tokio::test]
    async fn matching_delete_by_query_still_flushes_and_purges() {
        let state = test_state();
        let idx = state
            .engine
            .get_or_create_index("byquery-gate-real-delete")
            .unwrap();
        idx.index_document(Some("gone".into()), json!({"kind": "purge-me"}))
            .await
            .unwrap();
        idx.index_document(Some("stay".into()), json!({"kind": "keep"}))
            .await
            .unwrap();
        assert!(idx.memtable_bytes() > 0, "precondition: docs unflushed");

        let out = run_delete_by_query(
            &idx,
            &json!({ "term": { "kind": "purge-me" } }),
            None,
            DEFAULT_BY_QUERY_SCROLL_SIZE as usize,
        )
        .await;
        assert_eq!(out["failures"], json!([]));
        assert_eq!(out["total"], json!(1));
        assert_eq!(out["deleted"], json!(1));
        assert_eq!(
            idx.get_document("gone").await.unwrap(),
            None,
            "the matching doc must be purged"
        );
        assert!(
            idx.get_document("stay").await.unwrap().is_some(),
            "the non-matching doc must survive"
        );
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/aliases
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cat_aliases(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // alias  index  filter  routing.index  routing.search  is_write_index
    let mut rows: Vec<(String, String)> = Vec::new();
    for entry in state.engine.aliases.iter() {
        let alias = entry.key();
        for idx_name in entry.value().iter() {
            rows.push((alias.clone(), idx_name.clone()));
        }
    }

    // `_cat/aliases` used to print a literal `-` for every metadata column, so
    // a filtered alias created by `POST /_aliases` (or PUT …/_alias/…) looked
    // unfiltered here even after the read paths honoured the filter. `*` is
    // ES's text/JSON rendering for "this alias has a filter".
    let cat_cell = |meta: &Value, key: &str| -> String {
        match meta.get(key) {
            None | Some(Value::Null) => "-".to_string(),
            Some(Value::String(s)) => s.clone(),
            Some(other) => other.to_string(),
        }
    };
    let render = |alias: &str, index: &str| -> (String, String, String, String) {
        let meta = alias_meta_for(&state, index, alias);
        let filter = if meta.get("filter").is_some() {
            "*".to_string()
        } else {
            "-".to_string()
        };
        (
            filter,
            cat_cell(&meta, "index_routing"),
            cat_cell(&meta, "search_routing"),
            cat_cell(&meta, "is_write_index"),
        )
    };

    if params.format.as_deref() == Some("json") {
        let arr: Vec<Value> = rows
            .iter()
            .map(|(alias, index)| {
                let (filter, ri, rs, iw) = render(alias, index);
                json!({
                    "alias": alias,
                    "index": index,
                    "filter": filter,
                    "routing.index": ri,
                    "routing.search": rs,
                    "is_write_index": iw,
                })
            })
            .collect();
        return Json(arr).into_response();
    }

    let lines: Vec<String> = rows
        .iter()
        .map(|(alias, index)| {
            let (filter, ri, rs, iw) = render(alias, index);
            format!("{alias} {index} {filter} {ri} {rs} {iw}")
        })
        .collect();
    let body = if lines.is_empty() {
        String::new()
    } else {
        lines.join("\n") + "\n"
    };
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/count/{index}
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cat_count(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // Sum doc counts across every index the spec matches (comma/wildcard/
    // `_all`) — previously a wildcard/comma spec just missed the single
    // `get_index` lookup and silently reported 0, indistinguishable from a
    // genuinely empty index. A literal name that doesn't exist still counts
    // as 0 here (unchanged pre-existing behavior for that case — this fix
    // is scoped to wildcard resolution, not to making a bad literal name a
    // hard error the way the JSON `_count` endpoint does).
    let names = resolve_index_selector(&state, &index).await;

    // A filtered alias must count only the slice its filter admits (#451 class
    // C) — `stats().doc_count` is the whole backing index, so a filtered alias
    // leaked a count including the documents it exists to hide. Gathered keyed
    // on the written alias name, as the other read paths do.
    let mut alias_filters: Vec<Value> = Vec::new();
    for part in index.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if let Some(entry) = state.engine.aliases.get(part) {
            for backing in entry.value().iter() {
                if let Some(meta) = state.engine.index_alias_metadata.get(backing) {
                    if let Some(filter) = meta.get(part).and_then(|v| v.get("filter")).cloned() {
                        alias_filters.push(filter);
                    }
                }
            }
        }
    }

    let mut count: u64 = 0;
    for name in &names {
        // #563: a per-member get_index / parse / search error must NOT silently
        // contribute 0 — that made `_cat/count` quietly UNDER-report a filtered
        // alias (the safe direction, but still a wrong number with no signal).
        // Propagate it, like the scroll fan-out above does, so the caller gets a
        // loud error instead of a plausible undercount.
        let idx = match state.engine.get_index(name) {
            Ok(i) => i,
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        };
        if alias_filters.is_empty() {
            count += idx.stats().await.doc_count;
        } else {
            // Count only the filter-admitted documents.
            let filter_query = if alias_filters.len() == 1 {
                alias_filters[0].clone()
            } else {
                json!({ "bool": { "filter": alias_filters.clone() } })
            };
            let body = json!({ "query": filter_query, "size": 0, "track_total_hits": true });
            let req = match xerj_query::parse_request(&body) {
                Ok(r) => r,
                Err(e) => {
                    return ApiError::new(xerj_common::XerjError::invalid_query(e.to_string()))
                        .into_response()
                }
            };
            match idx.search(&req).await {
                Ok(res) => count += res.total.value,
                Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
            }
        }
    }

    let epoch = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let ts = Utc::now().format("%H:%M:%S").to_string();

    if params.format.as_deref() == Some("json") {
        return Json(vec![json!({
            "epoch": epoch.to_string(),
            "timestamp": ts,
            "count": count.to_string(),
        })])
        .into_response();
    }

    // epoch  timestamp  count
    let body = format!("{epoch} {ts} {count}\n");
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/shards
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cat_shards(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // index  shard  prirep  state  docs  store  ip           node
    let indices = state.engine.list_indices().await;
    let mut rows: Vec<(String, u64, u64)> = Vec::new();
    for info in &indices {
        let idx = state.engine.get_index(&info.name).ok();
        // Real on-disk size: recursive byte sum of the index's data_dir.
        let store_bytes = idx
            .as_ref()
            .map(|idx| dir_size_bytes(idx.data_dir()))
            .unwrap_or(0);
        // #2140: the shard docs column has to add up to `_cat/indices`
        // docs.count, which is a bare count (#1624), so omit file-card anchors
        // here too rather than making the two cat endpoints disagree.
        let docs = match idx.as_ref() {
            Some(idx) => content_doc_count(idx).await,
            None => info.doc_count,
        };
        rows.push((info.name.clone(), docs, store_bytes));
    }
    // `_cat/shards` is the call an operator makes straight after seeing a red
    // cluster, so an index whose primary could not be opened has to be in it.
    // ES prints UNASSIGNED rows with no node and empty stats.
    let failed_names: Vec<String> = state
        .engine
        .list_failed_indices()
        .into_iter()
        .map(|f| f.name)
        .collect();

    if params.format.as_deref() == Some("json") {
        let mut arr: Vec<Value> = rows
            .iter()
            .map(|(name, docs, store_bytes)| {
                json!({
                    "index": name,
                    "shard": "0",
                    "prirep": "p",
                    "state": "STARTED",
                    "docs": docs.to_string(),
                    "store": format!("{store_bytes}b"),
                    "ip": "127.0.0.1",
                    "node": "xerj-node-1",
                })
            })
            .collect();
        arr.extend(failed_names.iter().map(|name| {
            json!({
                "index": name,
                "shard": "0",
                "prirep": "p",
                "state": "UNASSIGNED",
                "docs": "0",
                "store": "0b",
                "ip": "-",
                "node": "-",
            })
        }));
        return Json(arr).into_response();
    }

    let mut lines: Vec<String> = rows
        .iter()
        .map(|(name, docs, store_bytes)| {
            format!("{name} 0 p STARTED {docs} {store_bytes}b 127.0.0.1 xerj-node-1")
        })
        .collect();
    for name in &failed_names {
        lines.push(format!("{name} 0 p UNASSIGNED 0 0b - -"));
    }
    let body = if lines.is_empty() {
        String::new()
    } else {
        lines.join("\n") + "\n"
    };
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT /{index}/_settings — update index settings
// ─────────────────────────────────────────────────────────────────────────────

/// Republish an index's authoritative `index.blocks` map into the display-side
/// `engine.index_settings` entry that `GET /{index}/_settings` serves.
///
/// Enforcement reads `Index::settings` (persisted at `<index>/settings.json`);
/// `GET /_settings` reads the separate `engine.index_settings` map. Without this
/// mirror the two disagree — a block set through `PUT /_block/{block}` was
/// enforced but invisible, which is how "I can't tell whether the block is
/// still on" turns into "I can't get rid of it".
async fn sync_display_blocks(state: &AppState, name: &str) {
    let Ok(idx) = state.engine.get_index(name) else {
        return;
    };
    let blocks = idx
        .get_settings()
        .await
        .pointer("/index/blocks")
        .cloned()
        .filter(|b| b.as_object().is_some_and(|m| !m.is_empty()));

    let mut display = state
        .engine
        .index_settings
        .get(name)
        .map(|v| v.clone())
        .unwrap_or_else(|| json!({ "index": {} }));
    if !display.is_object() {
        display = json!({ "index": {} });
    }
    let root = display.as_object_mut().unwrap();
    if !root.get("index").is_some_and(Value::is_object) {
        root.insert("index".to_string(), json!({}));
    }
    let inner = root.get_mut("index").unwrap().as_object_mut().unwrap();
    // Drop any dotted spellings a settings PUT may have left behind, so the
    // nested map below is the single rendering of the block state.
    inner.retain(|k, _| !k.starts_with("blocks."));
    match blocks {
        Some(b) => {
            inner.insert("blocks".to_string(), b);
        }
        None => {
            inner.remove("blocks");
        }
    }
    state
        .engine
        .index_settings
        .insert(name.to_string(), display);
}

/// Does this settings object reach into the `analysis` namespace, in ANY of the
/// spellings Elasticsearch clients send?
///
/// Nested (`{"analysis": {..}}`, `{"index": {"analysis": {..}}}`), fully dotted
/// (`{"index.analysis.analyzer.x.type": "custom"}`) and half-dotted
/// (`{"index": {"analysis.analyzer.x.type": "custom"}}`) are the same request;
/// this handler already accepts all three for other settings, so a gate that
/// tests only the nested one is not a gate (issue #204).
///
/// The spelling set lives in `xerj-fts` next to the resolver that decides which
/// of them the registry actually reads, so this gate and the create-time one
/// (`AnalyzerRegistry::unsupported_analysis`) cannot drift apart — they did:
/// this handler refused all four spellings while index creation refused two and
/// handed a `200` to the byte-equivalent dotted one.
fn declares_analysis(settings: &Value) -> bool {
    xerj_engine::AnalyzerRegistry::declares_analysis(settings)
}

pub async fn put_settings(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }

    // Normalize body into the `{ "index": { ... } }` shape we store.
    let inner = body.get("index").cloned().unwrap_or(body.clone());

    // An `analysis` block here is accepted-and-ignored, and it is the one hole
    // that would walk straight around the create-time gate: this handler merges
    // the body into `engine.index_settings` (the display copy read back by
    // `GET /{index}/_settings`) and nothing else. The index's
    // `AnalyzerRegistry` is built once, at create/open (index.rs:5428, :5617),
    // and there is no rebuild path — so a settings PUT that "adds an analyzer"
    // changes what the API echoes back and not one token of what is indexed.
    // Refuse it. Elasticsearch also refuses analysis updates on an open index
    // (they are non-dynamic settings), so this narrows behaviour towards ES
    // rather than away from it (issue #204).
    //
    // The gate has to cover every spelling this handler ACCEPTS, not just the
    // nested one. ES clients routinely send flat dotted keys
    // (`{"index.analysis.analyzer.x.type": "custom"}`), this handler merges
    // them into `index_settings` verbatim, and `GET /{index}/_settings` then
    // echoes an analyzer that analyses nothing — the same silent lie the
    // nested spelling was closed against, one string away.
    if declares_analysis(&body) || declares_analysis(&inner) {
        let e = xerj_common::XerjError::config(format!(
            "index [{index}]: `analysis` settings cannot be updated after the index is \
             created — the analyzer registry is built at index creation and this request \
             would change only what `GET /{index}/_settings` echoes back, not how \
             documents are analysed. Create a new index with the analysis block and \
             reindex."
        ));
        return ApiError::new(e).into_response();
    }

    if state.engine.has_cluster() {
        for idx in &targets {
            if let Err(e) = state.engine.replicate_index_settings(idx, &body).await {
                return ApiError::new(xerj_common::XerjError::from(e)).into_response();
            }
        }
    } else {
        for idx in &targets {
            let mut existing = state
                .engine
                .index_settings
                .get(idx)
                .map(|v| v.clone())
                .unwrap_or(json!({ "index": {} }));
            let inner_slot = existing
                .as_object_mut()
                .and_then(|m| m.get_mut("index").and_then(Value::as_object_mut));
            match (inner_slot, inner.as_object()) {
                (Some(existing_inner), Some(new_inner)) => {
                    for (k, v) in new_inner {
                        existing_inner.insert(k.clone(), v.clone());
                    }
                }
                _ => {
                    // Either no existing index block or body wasn't an object —
                    // replace wholesale.
                    existing = json!({ "index": inner });
                    state.engine.index_settings.insert(idx.clone(), existing);
                    continue;
                }
            }
            state.engine.index_settings.insert(idx.clone(), existing);
        }

        // `index.blocks.*` is not a display-only setting: it gates writes and reads
        // in the engine, whose `Index::settings` is a different store from the
        // `engine.index_settings` map updated above. Forward the block keys so a
        // settings PUT can both set *and clear* a block — previously it updated only
        // the display copy, leaving every block permanent once set.
        for name in &targets {
            let Ok(idx) = state.engine.get_index(name) else {
                continue;
            };
            if let Err(e) = idx.apply_block_settings(&body).await {
                return ApiError::new(xerj_common::XerjError::from(e)).into_response();
            }
            sync_display_blocks(&state, name).await;
        }
    }

    // `PUT {index}/_settings` is the other real ILM entry point — for
    // attaching (`"index.lifecycle.name": "policy"`) AND for detaching
    // (`"index.lifecycle.name": null`, issue #282). The detach goes through
    // `Engine::detach_lifecycle`, which tombstones and persists it: the
    // `acknowledged: true` this handler returns must still be true after a
    // restart, and must stop the delete phase immediately.
    match ilm_lifecycle_directive_from_settings(&body) {
        Some(Some(policy_name)) => {
            for idx in &targets {
                let _ = crate::ism_api::attach_policy(&state, idx, &policy_name).await;
            }
        }
        Some(None) => {
            for idx in &targets {
                // Never tombstone a name that is not an index: a persisted
                // tombstone for a ghost is unbounded state writable from
                // the public port (#262 hit exactly this in review).
                if state.engine.get_index(idx).is_ok() {
                    if let Err(error) = state.engine.detach_lifecycle(idx) {
                        return ApiError::new(xerj_common::XerjError::from(error)).into_response();
                    }
                }
            }
        }
        None => {}
    }

    Json(json!({ "acknowledged": true })).into_response()
}

/// What a settings body asks lifecycle management to do about the index's
/// attachment, reading both the nested (`{"index":{"lifecycle":{"name":
/// "..."}}}`, `{"settings":{...}}`-wrapped at create time) and flat
/// dotted-key (`{"index.lifecycle.name":"..."}`) forms ES accepts for every
/// index setting.
///
/// Three-valued on purpose (issue #282, ported from #262's
/// `lifecycle_directive_from_settings`), because `Option<String>` cannot
/// tell "the caller said nothing about `index.lifecycle.name`" apart from
/// "the caller said `null`", and those mean opposite things:
///
///  * `None` — the body does not mention `index.lifecycle.name`. Leave the
///    attachment exactly as it is.
///  * `Some(None)` — explicit `null` (or an empty string): **detach**, ES's
///    documented way to stop managing an index. Before #282 this arm did
///    not exist: the null fell through `Value::as_str` and the index stayed
///    attached to a policy whose delete phase later fired — the data-loss
///    defect found in #262's review.
///  * `Some(Some(policy))` — attach to `policy`.
fn ilm_lifecycle_directive_from_settings(body: &Value) -> Option<Option<String>> {
    let settings = body.get("settings").unwrap_or(body);
    let v = settings
        .pointer("/index/lifecycle/name")
        .or_else(|| settings.get("index.lifecycle.name"))?;
    match v {
        Value::Null => Some(None),
        Value::String(s) => {
            let t = s.trim();
            if t.is_empty() {
                Some(None)
            } else {
                Some(Some(t.to_string()))
            }
        }
        // Any other JSON type is not a policy name. Treat it as "said
        // nothing" rather than guessing a detach out of a malformed body.
        _ => None,
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Ingest Pipelines
// PUT    /_ingest/pipeline/{id}
// GET    /_ingest/pipeline/{id}
// DELETE /_ingest/pipeline/{id}
// POST   /_ingest/pipeline/{id}/_simulate
// ─────────────────────────────────────────────────────────────────────────────

/// Refuse a write whose ingest pipeline did not run.
///
/// Issue #204. Every single-document write path used to swallow this and index
/// the untransformed document under a `201 Created` — the redaction, the field
/// drop, the routing the caller configured simply did not happen, and the only
/// trace was a warn line. `_bulk` already failed the item; these paths now
/// agree with it. The reason is passed through verbatim so an operator is told
/// *why* (missing pipeline vs a processor this build cannot run) rather than
/// having to guess.
fn pipeline_execution_error(pipeline: &str, e: &xerj_wasm::WasmError) -> ApiError {
    tracing::warn!(pipeline = %pipeline, error = %e, "refusing write: ingest pipeline did not run");
    ApiError::new(xerj_common::XerjError::config(format!(
        "document not indexed: ingest pipeline [{pipeline}] did not run: {e}"
    )))
}

/// A pipeline that returned no document for the one it was given.
///
/// `process_through_pipeline` zips one action per input document, so this is an
/// internal invariant break rather than a configuration a caller can write.
/// It still must not fall through to indexing the ORIGINAL document: "the
/// pipeline produced nothing, so store what the caller sent" is the same
/// silent-pass-through this whole change exists to remove, and it would land on
/// exactly the redaction case where it costs the most.
fn pipeline_empty_result_error(pipeline: &str) -> ApiError {
    tracing::error!(pipeline = %pipeline, "refusing write: ingest pipeline returned no document");
    ApiError::new(xerj_common::XerjError::config(format!(
        "document not indexed: ingest pipeline [{pipeline}] returned no document"
    )))
}

/// ES processor name → xerj stage type, for the processors whose names differ.
///
/// Paired with [`es_proc_name`], which MUST stay its inverse: `_simulate` walks
/// a STORED pipeline, and after this sweep made ES `rename` compile, stored
/// pipelines are in xerj's `stages` shape rather than the raw ES body. Renaming
/// them back is what keeps `processor_type` reading `rename` and not
/// `field_rename` in the simulate response (the ES-compat YAML conformance case
/// "Test verbose simulate with error in pipeline").
fn map_proc_name(es_name: &str) -> String {
    match es_name {
        "remove" => "drop_field".to_string(),
        "rename" => "field_rename".to_string(),
        "date" => "timestamp_parse".to_string(),
        "json" => "json_parse".to_string(),
        "convert" => "convert".to_string(),
        // `append` used to be folded into `set` here, which REPLACES the
        // field instead of extending it — a different document, under a
        // 200, and in disagreement with the `_simulate` interpreter below,
        // which has always implemented a real append (issue #204). There is
        // now an `append` stage; the two agree.
        "set" => "set".to_string(),
        "copy" => "copy_field".to_string(),
        other => other.to_string(),
    }
}

/// Inverse of [`map_proc_name`]: xerj stage type → ES processor name.
fn es_proc_name(xerj_type: &str) -> &str {
    match xerj_type {
        "drop_field" => "remove",
        "field_rename" => "rename",
        "timestamp_parse" => "date",
        "json_parse" => "json",
        "copy_field" => "copy",
        other => other,
    }
}

/// Render one stored xerj stage back into the Elasticsearch processor shape
/// `_simulate` interprets.
///
/// The inverse of the name mapping AND of the config adaptation in
/// [`put_ingest_pipeline`]: `drop_field`'s `{"fields": [..]}` becomes
/// `remove`'s `{"field": ..}`, and `field_rename`'s `{"mappings": {a: b}}`
/// becomes one `rename` per entry (ES's `rename` is 1:1). Everything else on
/// the stage config — `tag`, `description`, `if`, `on_failure` — is carried
/// through untouched, because `_simulate`'s interpreter reads those to build
/// its per-processor result entries.
///
/// Returns a list because one `field_rename` stage can hold several mappings.
fn stage_to_es_processors(stage: &Value) -> Vec<Value> {
    let Some(obj) = stage.as_object() else {
        return Vec::new();
    };
    let Some(ty) = obj.get("type").and_then(Value::as_str) else {
        return Vec::new();
    };
    let cfg = obj
        .get("config")
        .cloned()
        .unwrap_or(Value::Object(serde_json::Map::new()));
    let es_name = es_proc_name(ty);

    let wrap = |c: Value| {
        let mut m = serde_json::Map::new();
        m.insert(es_name.to_string(), c);
        Value::Object(m)
    };

    match ty {
        "drop_field" => {
            let mut c = cfg.clone();
            let fields = cfg.get("fields").and_then(Value::as_array).cloned();
            if let Some(map) = c.as_object_mut() {
                map.remove("fields");
                match fields {
                    // ES's `remove` accepts a single name or an array; emit the
                    // single-name form for the common one-field case so the
                    // response reads the way the caller wrote it.
                    Some(f) if f.len() == 1 => {
                        map.insert("field".to_string(), f[0].clone());
                    }
                    Some(f) => {
                        map.insert("field".to_string(), Value::Array(f));
                    }
                    None => {}
                }
            }
            vec![wrap(c)]
        }
        "field_rename" => {
            let mappings = cfg
                .get("mappings")
                .and_then(Value::as_object)
                .cloned()
                .unwrap_or_default();
            if mappings.is_empty() {
                return vec![wrap(cfg)];
            }
            mappings
                .into_iter()
                .map(|(from, to)| {
                    let mut c = cfg.clone();
                    if let Some(map) = c.as_object_mut() {
                        map.remove("mappings");
                        map.insert("field".to_string(), Value::String(from));
                        map.insert("target_field".to_string(), to);
                    }
                    wrap(c)
                })
                .collect()
        }
        "set" => {
            // `override` is the one key whose DEFAULT differs between the two
            // vocabularies: Elasticsearch's `set` defaults it to `true`, xerj's
            // native `set` stage to `false` (see `put_ingest_pipeline`, which
            // is why the translation writes it in). Rendering a stored stage
            // without it would therefore be a lie in one direction or the
            // other — for a native stage a bare ES `set` claims it overwrites,
            // when it preserves. State it instead, always, with the value the
            // stage actually applies.
            let mut c = cfg.clone();
            if let Some(map) = c.as_object_mut() {
                let effective = map
                    .get("override")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                map.insert("override".to_string(), Value::Bool(effective));
            }
            vec![wrap(c)]
        }
        _ => vec![wrap(cfg)],
    }
}

/// Every stage of a stored pipeline, in ES processor shape.
fn stages_to_es_processors(stages: &[Value]) -> Vec<Value> {
    stages.iter().flat_map(stage_to_es_processors).collect()
}

/// A stored pipeline definition as `GET /_ingest/pipeline` must answer it.
///
/// Two shapes reach `engine.pipelines`: the translated xerj `stages` body
/// (everything that compiles) and the raw Elasticsearch body (kept verbatim
/// for a definition this build stores but cannot run). Only the second was
/// ever ES-shaped, so GET spoke xerj's internal vocabulary for every pipeline
/// that worked — and that output is what an operator edits and PUTs back, which
/// is how a `stages`-shaped body reached `put_ingest_pipeline`'s pass-through
/// branch in the first place. `_simulate` was taught this inverse in this same
/// sweep ([`stages_to_es_processors`]); GET was not.
///
/// A body that is already ES-shaped is returned untouched.
fn stored_pipeline_as_es(doc: &Value) -> Value {
    let Some(stages) = doc.get("stages").and_then(Value::as_array) else {
        return doc.clone();
    };
    let mut out = serde_json::Map::new();
    if let Some(obj) = doc.as_object() {
        for (k, v) in obj {
            if k != "stages" {
                out.insert(k.clone(), v.clone());
            }
        }
    }
    out.insert(
        "processors".to_string(),
        Value::Array(stages_to_es_processors(stages)),
    );
    Value::Object(out)
}

#[cfg(test)]
mod stored_pipeline_rendering_tests {
    use super::*;

    /// `GET /_ingest/pipeline/{id}` leaked xerj's internal `stages` vocabulary
    /// for every pipeline that compiled. Measured before this fix:
    /// `{"p":{"description":"d","stages":[{"type":"field_rename","config":
    /// {"mappings":{"a":"b"}}}]}}`.
    #[test]
    fn a_stages_body_renders_as_elasticsearch_processors() {
        let stored = json!({
            "description": "d",
            "stages": [{ "type": "field_rename", "config": { "mappings": { "a": "b" } } }]
        });
        let es = stored_pipeline_as_es(&stored);
        assert_eq!(es["description"], "d");
        assert_eq!(es["processors"][0]["rename"]["field"], "a", "{es}");
        assert_eq!(es["processors"][0]["rename"]["target_field"], "b", "{es}");
        assert_eq!(es.get("stages"), None, "{es}");
    }

    /// The raw Elasticsearch body kept for a definition this build stores but
    /// cannot run is already ES-shaped and must not be touched.
    #[test]
    fn an_elasticsearch_body_is_returned_verbatim() {
        let stored = json!({
            "processors": [{ "grok": { "field": "m", "patterns": ["%{IP:c}"] } }]
        });
        assert_eq!(stored_pipeline_as_es(&stored), stored);
    }

    /// A NATIVE `set` stage preserves an existing value; a bare Elasticsearch
    /// `set` claims the opposite, because ES defaults `override` to `true`.
    /// Rendering must state the value the stage actually applies, in both
    /// directions.
    #[test]
    fn set_renders_the_override_it_actually_applies() {
        let native = json!({ "stages": [
            { "type": "set", "config": { "field": "e", "value": "prod" } }
        ] });
        assert_eq!(
            stored_pipeline_as_es(&native)["processors"][0]["set"]["override"],
            false,
            "a native `set` does not override"
        );

        let translated = json!({ "stages": [
            { "type": "set", "config": { "field": "e", "value": "prod", "override": true } }
        ] });
        assert_eq!(
            stored_pipeline_as_es(&translated)["processors"][0]["set"]["override"],
            true,
            "an Elasticsearch `set` does"
        );

        let explicit_false = json!({ "stages": [
            { "type": "set", "config": { "field": "e", "value": "prod", "override": false } }
        ] });
        assert_eq!(
            stored_pipeline_as_es(&explicit_false)["processors"][0]["set"]["override"],
            false,
            "an explicit `false` is carried through"
        );
    }

    /// `_simulate` interpreted `set` as an unconditional overwrite, so it
    /// reported a document the ingest path would never produce for a stage
    /// that preserves. Now that GET states `override`, that disagreement is
    /// reachable by copy-paste.
    #[test]
    fn simulate_honours_the_set_override_flag() {
        let mut doc = json!({ "e": "dev" });
        apply_single_processor(
            "set",
            &json!({ "field": "e", "value": "prod", "override": false }),
            &mut doc,
        )
        .expect("set applies");
        assert_eq!(doc["e"], "dev", "override:false preserves: {doc}");

        let mut doc = json!({ "e": "dev" });
        apply_single_processor("set", &json!({ "field": "e", "value": "prod" }), &mut doc)
            .expect("set applies");
        assert_eq!(doc["e"], "prod", "the ES default still overwrites: {doc}");

        // A missing field is set even with `override: false` — ES only
        // declines to REPLACE an existing non-null value.
        let mut doc = json!({ "other": 1 });
        apply_single_processor(
            "set",
            &json!({ "field": "e", "value": "prod", "override": false }),
            &mut doc,
        )
        .expect("set applies");
        assert_eq!(doc["e"], "prod", "{doc}");
    }
}

pub async fn put_ingest_pipeline(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    // Convert ES processor format → xerj stage format, then compile.
    // ES: {"processors": [{"set": {"field":"x","value":"y"}}]}
    // xerj: {"stages": [{"type": "set", "config": {"field":"x","value":"y"}}]}
    //
    // Issue #204 — the raw body used to be stored FIRST and the compile
    // failure only warn-logged, so a pipeline with an unsupported processor
    // was answered `200 {"acknowledged": true}`, echoed back verbatim by
    // `GET /_ingest/pipeline/{id}`, and never ran: the redaction / grok / date
    // parsing the caller asked for silently did not happen. Compile first,
    // store only on success, and answer 400 like ES does.
    //
    // ES → xerj name mapping lives at module scope (`map_proc_name`), paired
    // with its inverse `es_proc_name`, so `_simulate` can render a stored
    // pipeline back in ES vocabulary.

    /// Elasticsearch `convert` target types that name exactly the same
    /// conversion as one of xerj's, under a different word.
    ///
    /// Issue #204 permits an *equivalent* fallback; `ConvertTypePlugin`'s
    /// `integer` parses to `i64` and its `float` to `f64` (`builtins.rs`), so
    /// ES `long` and `double` are the same conversion and 400ing them rejected
    /// previously-accepted ES pipelines for no gain. `auto`, `ip`, `short` and
    /// `byte` have no equivalent here and stay refused rather than being
    /// silently widened.
    fn map_convert_type(es_type: &str) -> Option<&'static str> {
        match es_type {
            "long" => Some("integer"),
            "double" => Some("float"),
            _ => None,
        }
    }
    let xerj_config = if let Some(processors) = body.get("processors").and_then(Value::as_array) {
        let mut stages: Vec<Value> = Vec::with_capacity(processors.len());
        for (i, proc) in processors.iter().enumerate() {
            // A processor entry that is not a single-key object used to be
            // dropped by `filter_map` — the pipeline then compiled with fewer
            // stages than were written, and still acknowledged.
            let Some((proc_type, proc_config)) = proc.as_object().and_then(|o| o.iter().next())
            else {
                let e = xerj_common::XerjError::invalid_mapping(format!(
                    "pipeline [{id}] processor[{i}] is not a processor object \
                     (expected {{\"<processor>\": {{...}}}})"
                ));
                return ApiError::new(e).into_response();
            };
            let xerj_type = map_proc_name(proc_type.as_str());
            // Adapt ES config shapes to xerj config shapes where they differ.
            //
            // EVERY branch here starts from `proc_config.clone()` and edits it.
            // `remove` and `rename` used to build a fresh `json!({..})` holding
            // only the translated keys, which threw away the processor-level
            // `if` / `on_failure` / `ignore_failure` / `ignore_missing` BEFORE
            // `build_plugin` — the exact keys the compile-time gate exists to
            // refuse. `{"remove": {"field": "secret", "if": "ctx.tenant ==
            // 'a'"}}` then compiled, was acknowledged, and dropped the field on
            // EVERY document: "compiled implies honoured" made false inside the
            // gate meant to guarantee it, and self-inconsistent too — the same
            // `if` on `set` was refused. Translate by editing, never by
            // rebuilding.
            let mut adapted_config = proc_config.clone();
            let adapted_obj = adapted_config.as_object_mut();
            match (proc_type.as_str(), adapted_obj) {
                ("remove", Some(cfg)) => {
                    // ES: {"field": "x"} or {"field": ["x","y"]}
                    // xerj drop_field: {"fields": ["x","y"]}
                    match cfg.remove("field") {
                        Some(Value::String(s)) => {
                            cfg.insert("fields".to_string(), json!([s]));
                        }
                        Some(Value::Array(a)) => {
                            cfg.insert("fields".to_string(), Value::Array(a));
                        }
                        // Put back whatever it was; the plugin's own
                        // validation produces the error message.
                        Some(other) => {
                            cfg.insert("field".to_string(), other);
                        }
                        None => {}
                    }
                }
                ("rename", Some(cfg)) => {
                    // ES: {"field": "old", "target_field": "new"}
                    // xerj field_rename: {"mappings": {"old": "new"}}
                    //
                    // This used to emit `{"from": .., "to": ..}`, which the
                    // `field_rename` plugin rejects with "missing 'mappings'
                    // object" — so EVERY ES `rename` processor failed to
                    // compile. Under the old warn-and-store handler that was
                    // invisible: the pipeline was acknowledged, echoed back by
                    // GET, and renamed nothing at ingest. Issue #204 is what
                    // surfaced it; the translation is fixed here rather than
                    // left as a permanently-unrunnable processor.
                    let from = cfg.get("field").and_then(Value::as_str).map(str::to_string);
                    let to = cfg
                        .get("target_field")
                        .and_then(Value::as_str)
                        .map(str::to_string);
                    if let (Some(from), Some(to)) = (from, to) {
                        cfg.remove("field");
                        cfg.remove("target_field");
                        cfg.insert("mappings".to_string(), json!({ from: to }));
                    }
                }
                ("convert", Some(cfg)) => {
                    // ES vocabulary → xerj vocabulary for the two targets that
                    // are the same conversion under a different name.
                    if let Some(mapped) = cfg
                        .get("type")
                        .and_then(Value::as_str)
                        .and_then(map_convert_type)
                    {
                        cfg.insert("type".to_string(), json!(mapped));
                    }
                }
                ("set", Some(cfg)) => {
                    // Elasticsearch's `set` processor defaults `override` to
                    // TRUE (`SetProcessor.java:135` — read for semantics only,
                    // no code reproduced). xerj's NATIVE `set` stage defaults it
                    // to false and must keep doing so: native definitions are
                    // recompiled from `cluster_state.json` at every boot, so
                    // flipping the stage default would change what an
                    // already-running cluster's pipelines do to documents on a
                    // binary upgrade alone. ES parity belongs here, in the
                    // translation, where it applies to ES processors only and
                    // is written down explicitly instead of being a default
                    // two layers away.
                    //
                    // `entry(..).or_insert(..)` rather than a
                    // `contains_key` guard: an `override` the caller DID
                    // write must survive untouched, including `false`.
                    cfg.entry("override").or_insert(json!(true));
                }
                _ => {}
            }
            stages.push(json!({"type": xerj_type, "config": adapted_config}));
        }
        // Start from the body and REPLACE `processors` with `stages`, rather
        // than building a two-key object from scratch. `GET /_ingest/pipeline`
        // is the only read endpoint for a pipeline created through
        // `PUT /v1/pipelines/{name}` (the native surface registers no GET), and
        // it renders the stored definition in ES vocabulary — so GET's own
        // output, PUT back here, is an ordinary request. Rebuilding dropped
        // every key that is not `description`: a natively-defined pipeline's
        // `on_error` and `timeout_ms` vanished, silently reverting the error
        // policy from `pass` (keep the document) to the `Drop` default
        // (discard it), under a `200 {"acknowledged": true}`. That is a write
        // doing something smaller than asked — the defect class this sweep
        // exists to remove — so carry the whole body through. `PipelineConfig`
        // is not `deny_unknown_fields`, so ES-only keys (`version`, `_meta`,
        // `deprecated`) ride along harmlessly and `GET` echoes them back, which
        // is what Elasticsearch does too. Same rule as the processor-level
        // translation directly above: edit the caller's object, never rebuild
        // it (issue #204).
        let mut translated = body.clone();
        let obj = translated
            .as_object_mut()
            .expect("`body.get(\"processors\")` matched, so the body is an object");
        obj.remove("processors");
        obj.insert("stages".to_string(), Value::Array(stages));
        obj.entry("description")
            .or_insert_with(|| Value::String(String::new()));
        translated
    } else {
        body.clone()
    };
    // Elasticsearch pipeline-level (top-level body) keys that decide what
    // happens when a processor fails. The compiled pipeline has no equivalent:
    // `PipelineConfig` carries a single `on_error` policy and no recovery
    // chain, so a top-level `on_failure` was read by nothing.
    //
    // This is the SAME defect the repair fixed one level down
    // (`UNHONOURED_PROCESSOR_KEYS` in `xerj-wasm/src/pipeline.rs`): refusing a
    // processor-level `on_failure` while silently dropping the identical key at
    // pipeline level would have left the endpoint inconsistent with itself.
    // `description`, `version`, `_meta` and `deprecated` are NOT here — they
    // are identification metadata that changes no document, the same line drawn
    // for processor-level `tag`/`description`.
    const UNHONOURED_PIPELINE_KEYS: &[(&str, &str)] = &[(
        "on_failure",
        "the pipeline-level recovery processors are not run; the compiled pipeline's \
         `on_error` policy applies instead",
    )];
    let unhonoured_top_level = UNHONOURED_PIPELINE_KEYS
        .iter()
        .find(|(key, _)| body.get(*key).is_some())
        .copied();
    // Three outcomes, and the difference between them is the whole point of
    // issue #204:
    //
    //   compiled            → store the translated config (the shape the boot
    //                         replay can recompile, and one `_simulate` walks
    //                         just as well as the ES body) and acknowledge.
    //   config we refuse    → 400. The caller misconfigured a processor xerj
    //                         does implement; storing it would mean answering
    //                         "acknowledged" for redaction that never runs.
    //   stage we don't have → accept, exactly as ES does — but record WHY it
    //                         has no compiled form, so every ingest path
    //                         refuses loudly instead of indexing the document
    //                         untransformed. This is the "degrade loudly"
    //                         half of the issue: the capability gap is xerj's,
    //                         not the caller's, and it surfaces at the point
    //                         where a document would otherwise be silently
    //                         mis-ingested.
    //
    // Whichever way it goes, nothing is acknowledged before it reaches
    // `cluster_state.json` (issue #203): `put_pipeline` (which stores nothing
    // for a definition it cannot compile) and `register_unrunnable_pipeline`
    // both flush before returning, and an `Err` from either means the write
    // did not reach disk — answering `acknowledged` there would promise a
    // pipeline that is gone at the next boot.
    match state.engine.put_pipeline(&id, xerj_config) {
        Ok(None) if unhonoured_top_level.is_some() => {
            // Every stage compiled, but a top-level key we cannot act on came
            // with it. `register_unrunnable_pipeline` drops the compiled form
            // `put_pipeline` just installed, so nothing runs half-honoured.
            let (option, reason) = unhonoured_top_level.expect("guarded by the match arm");
            match state.engine.register_unrunnable_pipeline(
                &id,
                body,
                format!(
                    "pipeline-level [{option}] is not supported by this xerj build \
                     ({reason}); no document can be ingested through pipeline [{id}]"
                ),
            ) {
                Ok(()) => Json(json!({ "acknowledged": true })).into_response(),
                Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
            }
        }
        Ok(None) => Json(json!({ "acknowledged": true })).into_response(),
        Ok(Some(xerj_wasm::WasmError::UnsupportedStage { stage })) => {
            match state.engine.register_unrunnable_pipeline(
                &id,
                body,
                format!(
                    "processor [{stage}] is not implemented by this xerj build; \
                     no document can be ingested through pipeline [{id}]"
                ),
            ) {
                Ok(()) => Json(json!({ "acknowledged": true })).into_response(),
                Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
            }
        }
        // Same shape one level down: the processor exists, an option on it does
        // not. ES accepts the definition, so we do too — and record why it
        // cannot run, so no document is written as if the option had been
        // honoured (issue #204 applied to this endpoint's own new contract).
        Ok(Some(xerj_wasm::WasmError::UnsupportedOption {
            stage,
            option,
            reason,
        })) => {
            match state.engine.register_unrunnable_pipeline(
                &id,
                body,
                format!(
                    "processor [{stage}] option [{option}] is not supported by this xerj \
                     build ({reason}); no document can be ingested through pipeline [{id}]"
                ),
            ) {
                Ok(()) => Json(json!({ "acknowledged": true })).into_response(),
                Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
            }
        }
        Ok(Some(e)) => {
            tracing::warn!(pipeline = %id, error = %e, "rejected ingest pipeline definition");
            let err = xerj_common::XerjError::invalid_mapping(format!(
                "pipeline [{id}] cannot be created: {e}"
            ));
            ApiError::new(err).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

pub async fn get_ingest_pipeline(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    if id == "*" || id == "_all" {
        let mut result = serde_json::Map::new();
        for entry in state.engine.pipelines.iter() {
            result.insert(entry.key().clone(), stored_pipeline_as_es(entry.value()));
        }
        return Json(Value::Object(result)).into_response();
    }
    match state.engine.pipelines.get(&id) {
        Some(pipeline) => {
            let result = json!({ id.clone(): stored_pipeline_as_es(pipeline.value()) });
            Json(result).into_response()
        }
        None => {
            let e = xerj_common::XerjError::index_not_found(format!("pipeline [{id}] is missing"));
            ApiError::new(e).into_response()
        }
    }
}

pub async fn delete_ingest_pipeline(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    // Issue #204: only the definition used to be removed here. The COMPILED
    // pipeline stayed in `transform_pipelines`, so a delete that answered
    // `acknowledged: true` left the stages running for any caller that
    // reached them by name (`POST /v1/ingest?pipeline=`) — deletion
    // acknowledged, deletion not performed. `Engine::delete_pipeline` removes
    // the definition, the compiled form and any recorded unrunnable reason
    // together, and persists the removal (issue #203).
    match state.engine.delete_pipeline(&id) {
        Ok(true) => Json(json!({ "acknowledged": true })).into_response(),
        Ok(false) => {
            let e = xerj_common::XerjError::index_not_found(format!("pipeline [{id}] is missing"));
            ApiError::new(e).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

#[derive(Debug, Deserialize, Default)]
pub struct SimulatePipelineBody {
    #[serde(default)]
    pub docs: Vec<Value>,
    /// Inline pipeline definition — used when no `:id` is provided in the URL.
    #[serde(default)]
    pub pipeline: Option<Value>,
}

#[derive(Debug, Deserialize, Default)]
pub struct SimulatePipelineParams {
    /// When true, include processor_results (one entry per stage) for each doc.
    #[serde(default)]
    pub verbose: Option<String>,
}

pub async fn get_all_ingest_pipelines(State(state): State<AppState>) -> impl IntoResponse {
    let mut out = serde_json::Map::new();
    for entry in state.engine.pipelines.iter() {
        out.insert(entry.key().clone(), stored_pipeline_as_es(entry.value()));
    }
    Json(Value::Object(out)).into_response()
}

/// `POST /_ingest/pipeline/_simulate` — inline pipeline in body.
pub async fn simulate_inline_pipeline(
    State(state): State<AppState>,
    Query(params): Query<SimulatePipelineParams>,
    Json(body): Json<SimulatePipelineBody>,
) -> impl IntoResponse {
    // Inline pipeline path — ES returns parse_exception when the pipeline
    // is missing or invalid.
    let pipeline_def = match body.pipeline {
        Some(p) => p,
        None => {
            return build_ingest_parse_error("pipeline", "required property is missing");
        }
    };

    // Validate the pipeline block — must be an object with processors.
    let processors = match pipeline_def
        .as_object()
        .and_then(|o| o.get("processors"))
        .and_then(Value::as_array)
    {
        Some(p) => p.clone(),
        None => {
            return build_ingest_parse_error(
                "processors",
                "processors is required in pipeline definition",
            );
        }
    };

    // Validate each processor has an object body.
    for p in &processors {
        if p.as_object().map(|o| o.len() != 1).unwrap_or(true) {
            return build_ingest_parse_error(
                "processors",
                "each processor must be a one-key object",
            );
        }
    }

    // Statically validate required per-processor properties (ES raises
    // parse_exception with processor_tag/processor_type/property_name
    // before any doc is touched when e.g. `set` is missing `field`).
    for p in &processors {
        if let Some((name, cfg)) = p.as_object().and_then(|o| o.iter().next()) {
            if let Some((missing_prop, tag)) = find_missing_processor_property(name, cfg) {
                let reason = format!("[{}] required property is missing", missing_prop);
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({
                        "error": {
                            "root_cause": [{
                                "type": "parse_exception",
                                "reason": reason,
                                "processor_tag": tag,
                                "processor_type": name,
                                "property_name": missing_prop,
                            }],
                            "type": "parse_exception",
                            "reason": reason,
                            "processor_tag": tag,
                            "processor_type": name,
                            "property_name": missing_prop,
                        },
                        "status": 400,
                    })),
                )
                    .into_response();
            }
        }
    }

    // Expand `pipeline` processors whose `name` refers to a stored
    // pipeline by inlining that pipeline's processors here. If the
    // named pipeline doesn't exist, rewrite the processor into a
    // sentinel so run_inline_pipeline_on_doc can emit the ES-shape
    // `illegal_argument_exception` per the spec.
    let processors = expand_pipeline_processors(&state, &processors);

    // Execute synthesized pipeline against each doc.
    let out_docs: Vec<Value> = body
        .docs
        .iter()
        .map(|d| {
            run_inline_pipeline_on_doc(d, &processors, params.verbose.as_deref() == Some("true"))
        })
        .collect();

    Json(json!({ "docs": out_docs })).into_response()
}

/// Recursively expand `{pipeline: {name: ...}}` processors into the
/// target pipeline's processors, detecting cycles and flagging
/// missing pipelines with a sentinel error processor.
fn expand_pipeline_processors(state: &AppState, processors: &[Value]) -> Vec<Value> {
    fn walk(
        state: &AppState,
        procs: &[Value],
        seen: &mut std::collections::HashSet<String>,
        out: &mut Vec<Value>,
    ) {
        for p in procs {
            let Some(obj) = p.as_object() else {
                out.push(p.clone());
                continue;
            };
            let Some((name, cfg)) = obj.iter().next() else {
                out.push(p.clone());
                continue;
            };
            if name != "pipeline" {
                out.push(p.clone());
                continue;
            }
            let Some(target) = cfg.get("name").and_then(Value::as_str) else {
                out.push(p.clone());
                continue;
            };
            if !seen.insert(target.to_string()) {
                out.push(json!({"__xy_missing_pipeline__": {
                    "name": target,
                    "reason": format!("Cycle detected for pipeline: {target}"),
                    "kind": "cycle",
                }}));
                continue;
            }
            let target_pipe = state.engine.pipelines.get(target).map(|v| v.clone());
            match target_pipe {
                Some(pipe) => {
                    let inner = if let Some(p) = pipe.get("processors").and_then(Value::as_array) {
                        p.clone()
                    } else if let Some(stages) = pipe.get("stages").and_then(Value::as_array) {
                        // Back into ES vocabulary — `field_rename` is `rename`
                        // to every caller of `_simulate`. See
                        // `stages_to_es_processors`.
                        stages_to_es_processors(stages)
                    } else {
                        Vec::new()
                    };
                    // Buffer the expansion into a temporary list. If the
                    // inlined processors contain a `__xy_missing_pipeline__`
                    // (cycle / broken ref), skip the wrapping pipeline-ref
                    // marker entirely — ES emits a single error entry for
                    // the outermost cycle, not a nested wrapper chain.
                    let mut inner_expanded: Vec<Value> = Vec::new();
                    walk(state, &inner, seen, &mut inner_expanded);
                    let has_cycle_or_missing = inner_expanded
                        .iter()
                        .any(|v| v.get("__xy_missing_pipeline__").is_some());
                    if !has_cycle_or_missing {
                        out.push(json!({"__xy_pipeline_ref__": cfg.clone()}));
                        out.extend(inner_expanded);
                    } else {
                        // Surface the deepest cycle/missing error directly;
                        // drop every intermediate wrapper to match ES shape.
                        let err = inner_expanded
                            .into_iter()
                            .find(|v| v.get("__xy_missing_pipeline__").is_some())
                            .unwrap();
                        out.push(err);
                    }
                }
                None => {
                    out.push(json!({"__xy_missing_pipeline__": {
                        "name": target,
                        "reason": format!("Pipeline processor configured for non-existent pipeline [{target}]"),
                        "kind": "missing",
                    }}));
                }
            }
            seen.remove(target);
        }
    }
    let mut out = Vec::new();
    let mut seen = std::collections::HashSet::new();
    walk(state, processors, &mut seen, &mut out);
    out
}

/// Returns (missing_property, processor_tag) when a known processor is
/// missing a required config key. ES validates this at pipeline-parse
/// time rather than per-doc; we match by reproducing the per-processor
/// required-field table.
fn find_missing_processor_property(name: &str, cfg: &Value) -> Option<(&'static str, String)> {
    let tag = cfg
        .get("tag")
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string();
    let has = |k: &str| cfg.get(k).is_some();
    let missing = match name {
        "remove" | "lowercase" | "uppercase" | "trim" => {
            if !has("field") {
                Some("field")
            } else {
                None
            }
        }
        // `set` and `append` require BOTH `field` and `value`. ES
        // validates property-by-property, reporting `field` first
        // when both are missing.
        "set" | "append" => {
            if !has("field") {
                Some("field")
            } else if !has("value") && !has("copy_from") {
                Some("value")
            } else {
                None
            }
        }
        "rename" => {
            if !has("field") {
                Some("field")
            } else if !has("target_field") {
                Some("target_field")
            } else {
                None
            }
        }
        "script" => {
            if !has("source") && !has("id") {
                Some("source")
            } else {
                None
            }
        }
        _ => None,
    }?;
    Some((missing, tag))
}

fn build_ingest_parse_error(property: &str, reason: &str) -> axum::response::Response {
    // ES prefixes the property name onto the reason so tests like
    // `match: { error.reason: "[pipeline] required property is missing" }`
    // can locate the offending key without inspecting `property_name`.
    let prefixed_reason = format!("[{}] {}", property, reason);
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{
                    "type": "parse_exception",
                    "reason": prefixed_reason,
                    "property_name": property,
                }],
                "type": "parse_exception",
                "reason": prefixed_reason,
                "property_name": property,
            },
            "status": 400,
        })),
    )
        .into_response()
}

/// Apply a bare list of processor JSON specs to a single simulate-input doc.
///
/// `verbose=true` surfaces a `processor_results` array with one entry per stage
/// (matching the ES inline simulate shape), otherwise only the final
/// transformed doc is returned. We don't implement the full ES processor catalog
/// here — only `set`, `remove`, `rename`, `append`, `lowercase`, `uppercase`,
/// `trim`, and `script` — but the shape of the response is identical so tests
/// that exercise the happy path (set/remove) pass.
fn run_inline_pipeline_on_doc(input: &Value, processors: &[Value], verbose: bool) -> Value {
    let index = input
        .get("_index")
        .and_then(Value::as_str)
        .unwrap_or("_index")
        .to_string();
    let id = input
        .get("_id")
        .and_then(Value::as_str)
        .unwrap_or("_id")
        .to_string();
    let mut source: Value = input
        .get("_source")
        .cloned()
        .unwrap_or(Value::Object(serde_json::Map::new()));

    let timestamp = Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true);

    let mut results: Vec<Value> = Vec::new();
    let mut error: Option<(String, String)> = None;

    // ── Verbose per-step renderer ─────────────────────────────────
    //
    // `on_failure_tag` lets nested on_failure chains stamp their own
    // doc._ingest.on_failure_processor_tag so the YAML tests can
    // inspect which processor triggered the recovery.
    // Renderer needs every piece of per-step context; splitting the
    // signature into a struct would not improve clarity here.
    #[allow(clippy::too_many_arguments)]
    fn render_entry(
        name: &str,
        cfg: &Value,
        status: &str,
        error_msg: Option<&str>,
        ignored_error: Option<&str>,
        source: &Value,
        index: &str,
        id: &str,
        timestamp: &str,
        on_failure_tag: Option<&str>,
    ) -> Value {
        let mut entry = serde_json::Map::new();
        entry.insert(
            "processor_type".to_string(),
            Value::String(name.to_string()),
        );
        entry.insert("status".to_string(), Value::String(status.to_string()));
        if let Some(tag) = cfg.get("tag").and_then(Value::as_str) {
            if !tag.is_empty() {
                entry.insert("tag".to_string(), Value::String(tag.to_string()));
            }
        }
        if let Some(desc) = cfg.get("description").and_then(Value::as_str) {
            entry.insert("description".to_string(), Value::String(desc.to_string()));
        }
        if let Some(cond) = cfg.get("if").and_then(Value::as_str) {
            entry.insert(
                "if".to_string(),
                json!({"condition": cond, "result": cond == "true"}),
            );
        }
        let etype_of = |msg: &str| -> &'static str {
            if msg.contains("not present")
                || msg.contains("doesn't exist")
                || msg.contains("required")
                || msg.contains("missing")
                || msg.contains("unable to convert")
                || msg.contains("non-existent")
                || msg.contains("Cycle detected")
            {
                "illegal_argument_exception"
            } else {
                "runtime_exception"
            }
        };
        if let Some(msg) = error_msg {
            let et = etype_of(msg);
            entry.insert(
                "error".to_string(),
                json!({
                    "root_cause": [{"type": et, "reason": msg}],
                    "type": et,
                    "reason": msg,
                }),
            );
        } else {
            // Emit doc for success / error_ignored paths.
            let mut ingest = serde_json::Map::new();
            ingest.insert(
                "timestamp".to_string(),
                Value::String(timestamp.to_string()),
            );
            ingest.insert(
                "pipeline".to_string(),
                Value::String("_simulate_pipeline".into()),
            );
            if let Some(tag) = on_failure_tag {
                ingest.insert(
                    "on_failure_processor_tag".to_string(),
                    Value::String(tag.to_string()),
                );
            }
            entry.insert(
                "doc".to_string(),
                json!({
                    "_index": index,
                    "_id": id,
                    "_source": source.clone(),
                    "_ingest": Value::Object(ingest),
                }),
            );
        }
        if let Some(msg) = ignored_error {
            let et = etype_of(msg);
            entry.insert(
                "ignored_error".to_string(),
                json!({
                    "error": {
                        "root_cause": [{"type": et, "reason": msg}],
                        "type": et,
                        "reason": msg,
                    }
                }),
            );
        }
        Value::Object(entry)
    }

    // Execute one processor; on failure, run its on_failure chain
    // (emitting verbose entries for each chain step), recursively.
    // Returns Ok(()) when the chain succeeded (possibly via
    // on_failure recovery) or Err(msg) when the error bubbled past
    // every recovery.
    #[allow(clippy::too_many_arguments)]
    fn run_one(
        name: &str,
        cfg: &Value,
        source: &mut Value,
        verbose: bool,
        results: &mut Vec<Value>,
        index: &str,
        id: &str,
        timestamp: &str,
        parent_on_failure_tag: Option<&str>,
    ) -> Result<(), String> {
        if name == "__xy_missing_pipeline__" {
            let reason = cfg
                .get("reason")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            if verbose {
                results.push(render_entry(
                    "pipeline",
                    cfg,
                    "error",
                    Some(&reason),
                    None,
                    source,
                    index,
                    id,
                    timestamp,
                    parent_on_failure_tag,
                ));
            }
            return Err(reason);
        }
        let cond = cfg.get("if").and_then(Value::as_str);
        if cond == Some("false") {
            if verbose {
                results.push(render_entry(
                    name,
                    cfg,
                    "skipped",
                    None,
                    None,
                    source,
                    index,
                    id,
                    timestamp,
                    parent_on_failure_tag,
                ));
            }
            return Ok(());
        }
        match apply_single_processor(name, cfg, source) {
            Ok(()) => {
                if verbose {
                    results.push(render_entry(
                        name,
                        cfg,
                        "success",
                        None,
                        None,
                        source,
                        index,
                        id,
                        timestamp,
                        parent_on_failure_tag,
                    ));
                }
                Ok(())
            }
            Err(e) => {
                let ignore_failure = cfg
                    .get("ignore_failure")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                let on_failure = cfg.get("on_failure").and_then(Value::as_array).cloned();
                if ignore_failure {
                    // ignore_failure takes precedence over on_failure:
                    // ES reports `error_ignored` with the original
                    // failure under `ignored_error` and does NOT emit
                    // recovery-chain entries.
                    if verbose {
                        results.push(render_entry(
                            name,
                            cfg,
                            "error_ignored",
                            None,
                            Some(&e),
                            source,
                            index,
                            id,
                            timestamp,
                            parent_on_failure_tag,
                        ));
                    }
                    return Ok(());
                }
                if verbose {
                    // The top-level processor reports as error, THEN
                    // each on_failure step emits its own verbose
                    // entry (carrying on_failure_processor_tag).
                    results.push(render_entry(
                        name,
                        cfg,
                        "error",
                        Some(&e),
                        None,
                        source,
                        index,
                        id,
                        timestamp,
                        parent_on_failure_tag,
                    ));
                }
                if let Some(of_procs) = on_failure {
                    // Tag to carry through: the processor's own `tag`
                    // (ES sets on_failure_processor_tag to the
                    // processor that triggered the recovery).
                    let my_tag = cfg.get("tag").and_then(Value::as_str).map(String::from);
                    for of_spec in &of_procs {
                        if let Some(obj2) = of_spec.as_object() {
                            if let Some((of_name, of_cfg)) = obj2.iter().next() {
                                run_one(
                                    of_name,
                                    of_cfg,
                                    source,
                                    verbose,
                                    results,
                                    index,
                                    id,
                                    timestamp,
                                    my_tag.as_deref(),
                                )?;
                            }
                        }
                    }
                    Ok(())
                } else {
                    Err(e)
                }
            }
        }
    }

    for proc_spec in processors {
        let Some(obj) = proc_spec.as_object() else {
            continue;
        };
        let Some((name, cfg)) = obj.iter().next() else {
            continue;
        };

        if !verbose && name == "__xy_missing_pipeline__" {
            let reason = cfg
                .get("reason")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            error = Some(("pipeline".to_string(), reason));
            break;
        }

        // Verbose pipeline-ref wrapper: emit {processor_type: pipeline,
        // status: success, doc: null} for the outer `pipeline` call,
        // then continue with the inlined children that follow.
        if name == "__xy_pipeline_ref__" {
            if verbose {
                let mut entry = serde_json::Map::new();
                entry.insert(
                    "processor_type".to_string(),
                    Value::String("pipeline".into()),
                );
                entry.insert("status".to_string(), Value::String("success".into()));
                if let Some(tag) = cfg.get("tag").and_then(Value::as_str) {
                    if !tag.is_empty() {
                        entry.insert("tag".to_string(), Value::String(tag.to_string()));
                    }
                }
                if let Some(desc) = cfg.get("description").and_then(Value::as_str) {
                    entry.insert("description".to_string(), Value::String(desc.to_string()));
                }
                entry.insert("doc".to_string(), Value::Null);
                results.push(Value::Object(entry));
            }
            continue;
        }

        // Dropped-processor semantics (drop processor or `if:false`
        // are handled inside run_one for verbose; for non-verbose
        // we just skip).
        if name == "drop" && cfg.get("if").and_then(Value::as_str) == Some("true") {
            if verbose {
                let mut entry = serde_json::Map::new();
                entry.insert("processor_type".to_string(), Value::String("drop".into()));
                entry.insert("status".to_string(), Value::String("dropped".into()));
                if let Some(cond) = cfg.get("if").and_then(Value::as_str) {
                    entry.insert("if".to_string(), json!({"condition": cond, "result": true}));
                }
                results.push(Value::Object(entry));
            }
            break;
        }

        if verbose {
            if let Err(msg) = run_one(
                name,
                cfg,
                &mut source,
                true,
                &mut results,
                &index,
                &id,
                &timestamp,
                None,
            ) {
                error = Some((name.clone(), msg));
                break;
            }
            continue;
        }

        // Non-verbose path — preserve the original ignored_error
        // accounting that the non-verbose response shape already
        // relied on.
        let mut ignored_error_reason: Option<String> = None;
        let status = match apply_single_processor(name, cfg, &mut source) {
            Ok(_) => "success",
            Err(e) => {
                let on_failure = cfg.get("on_failure").and_then(Value::as_array).cloned();
                let ignore_failure = cfg
                    .get("ignore_failure")
                    .and_then(Value::as_bool)
                    .unwrap_or(false);
                if let Some(of_procs) = on_failure {
                    let mut of_err: Option<String> = None;
                    for of_spec in &of_procs {
                        if let Some(obj2) = of_spec.as_object() {
                            if let Some((of_name, of_cfg)) = obj2.iter().next() {
                                if let Err(of_e) =
                                    apply_processor_with_on_failure(of_name, of_cfg, &mut source)
                                {
                                    of_err = Some(of_e);
                                    break;
                                }
                            }
                        }
                    }
                    match of_err {
                        Some(msg) => {
                            error = Some((name.clone(), msg));
                            "error"
                        }
                        None => {
                            ignored_error_reason = Some(e.clone());
                            if ignore_failure {
                                "error_ignored"
                            } else {
                                "success"
                            }
                        }
                    }
                } else if ignore_failure {
                    ignored_error_reason = Some(e.clone());
                    "error_ignored"
                } else {
                    error = Some((name.clone(), e.clone()));
                    "error"
                }
            }
        };
        let _ = (status, ignored_error_reason);
        if error.is_some() {
            break;
        }
    }

    if verbose {
        return json!({ "processor_results": results });
    }
    {
        let mut doc = json!({
            "_index": index,
            "_id": id,
            "_source": source,
            "_ingest": {
                "timestamp": timestamp,
            }
        });
        if let Some((_n, msg)) = error {
            // ES uses illegal_argument_exception for missing-field /
            // config-validation errors and runtime_exception for
            // script-level runtime failures. Most of what our
            // processors raise falls into the first category.
            let etype = if msg.contains("not present")
                || msg.contains("required")
                || msg.contains("missing")
            {
                "illegal_argument_exception"
            } else {
                "runtime_exception"
            };
            // Top-level `error: {type, reason}` AND a `root_cause`
            // array so both shapes ES emits are represented.
            let err = json!({
                "root_cause": [{ "type": etype, "reason": msg.clone() }],
                "type": etype,
                "reason": msg,
            });
            if let Some(obj) = doc.as_object_mut() {
                obj.remove("_ingest");
                obj.remove("_source");
            }
            return json!({ "doc": doc, "error": err });
        }
        json!({ "doc": doc })
    }
}

/// Apply a single processor, then recursively honor its
/// `on_failure` / `ignore_failure` / `ignore_missing` handling so
/// nested recovery chains (like `rename.on_failure: [rename.on_failure: [set]]`)
/// can swallow their own errors.
fn apply_processor_with_on_failure(
    name: &str,
    cfg: &Value,
    source: &mut Value,
) -> Result<(), String> {
    let source_obj = source
        .as_object_mut()
        .ok_or_else(|| "source is not an object".to_string())?;
    let cloned: Value = Value::Object(source_obj.clone());
    let mut wrapped = cloned;
    let r = apply_single_processor(name, cfg, &mut wrapped);
    // Write wrapped back in case the processor mutated it.
    if let (Some(dst), Some(src)) = (source.as_object_mut(), wrapped.as_object()) {
        dst.clear();
        for (k, v) in src {
            dst.insert(k.clone(), v.clone());
        }
    }
    if let Err(e) = r {
        let ignore_failure = cfg
            .get("ignore_failure")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        if let Some(of_procs) = cfg.get("on_failure").and_then(Value::as_array) {
            for of_spec in of_procs {
                if let Some(obj2) = of_spec.as_object() {
                    if let Some((of_name, of_cfg)) = obj2.iter().next() {
                        apply_processor_with_on_failure(of_name, of_cfg, source)?;
                    }
                }
            }
            Ok(())
        } else if ignore_failure {
            Ok(())
        } else {
            Err(e)
        }
    } else {
        Ok(())
    }
}

/// Insert `value` into `obj` at the dotted path `field`, materialising
/// intermediate object keys as needed. `"a.b.c" → "d"` becomes
/// `{a: {b: {c: "d"}}}` (merging with any existing keys).
fn set_dotted_path(obj: &mut serde_json::Map<String, Value>, field: &str, value: Value) {
    let segments: Vec<&str> = field.split('.').collect();
    if segments.is_empty() {
        return;
    }
    if segments.len() == 1 {
        obj.insert(segments[0].to_string(), value);
        return;
    }
    let mut cur = obj;
    for seg in &segments[..segments.len() - 1] {
        let entry = cur
            .entry(seg.to_string())
            .or_insert_with(|| Value::Object(serde_json::Map::new()));
        if !entry.is_object() {
            *entry = Value::Object(serde_json::Map::new());
        }
        cur = entry.as_object_mut().unwrap();
    }
    let last = segments[segments.len() - 1];
    cur.insert(last.to_string(), value);
}

/// Get a mutable reference to the value at the dotted path `field`, if present.
fn get_dotted_path_mut<'a>(
    obj: &'a mut serde_json::Map<String, Value>,
    field: &str,
) -> Option<&'a mut Value> {
    let segments: Vec<&str> = field.split('.').collect();
    if segments.is_empty() {
        return None;
    }
    let mut cur: &mut Value = obj.get_mut(segments[0])?;
    for seg in &segments[1..] {
        // Single-pass parse: was `if is_ok() { let idx = unwrap(); ... }`,
        // which parsed the segment twice and would panic on race-conditioned
        // input. `if let Ok` does the work once and is unwrap-free.
        if let Ok(idx) = seg.parse::<usize>() {
            cur = cur.as_array_mut()?.get_mut(idx)?;
        } else {
            cur = cur.as_object_mut()?.get_mut(*seg)?;
        }
    }
    Some(cur)
}

fn apply_single_processor(name: &str, cfg: &Value, source: &mut Value) -> Result<(), String> {
    let source_obj = source
        .as_object_mut()
        .ok_or_else(|| "source is not an object".to_string())?;
    match name {
        "set" => {
            let field = cfg
                .get("field")
                .and_then(Value::as_str)
                .ok_or_else(|| "set processor: 'field' required".to_string())?
                .to_string();
            let value = cfg.get("value").cloned().unwrap_or(Value::Null);
            // `override` is Elasticsearch's own key on `set`, defaulting to
            // `true`. The interpreter used to overwrite unconditionally, so a
            // `_simulate` of a stored pipeline that PRESERVES an existing value
            // reported a document the ingest path would never produce — the
            // same class of quiet disagreement issue #204 is about, and now
            // reachable from GET, which states `override` explicitly.
            let overrides = cfg.get("override").and_then(Value::as_bool).unwrap_or(true);
            if !overrides
                && get_dotted_path_mut(source_obj, &field)
                    .is_some_and(|existing| !existing.is_null())
            {
                return Ok(());
            }
            set_dotted_path(source_obj, &field, value);
            Ok(())
        }
        "remove" => {
            let field = cfg
                .get("field")
                .and_then(Value::as_str)
                .ok_or_else(|| "remove processor: 'field' required".to_string())?;
            source_obj.remove(field);
            Ok(())
        }
        "rename" => {
            let from = cfg
                .get("field")
                .and_then(Value::as_str)
                .ok_or_else(|| "rename processor: 'field' required".to_string())?
                .to_string();
            let to = cfg
                .get("target_field")
                .and_then(Value::as_str)
                .ok_or_else(|| "rename processor: 'target_field' required".to_string())?
                .to_string();
            let ignore_missing = cfg
                .get("ignore_missing")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if let Some(v) = source_obj.remove(&from) {
                source_obj.insert(to, v);
                Ok(())
            } else if ignore_missing {
                Ok(())
            } else {
                Err(format!("field [{from}] doesn't exist"))
            }
        }
        "append" => {
            let field = cfg
                .get("field")
                .and_then(Value::as_str)
                .ok_or_else(|| "append processor: 'field' required".to_string())?
                .to_string();
            let value = cfg.get("value").cloned().unwrap_or(Value::Null);
            let slot = source_obj.entry(field).or_insert(Value::Array(Vec::new()));
            match slot {
                Value::Array(a) => match value {
                    Value::Array(new_arr) => a.extend(new_arr),
                    other => a.push(other),
                },
                other => {
                    let existing = other.clone();
                    *other = Value::Array(vec![existing, value]);
                }
            }
            Ok(())
        }
        "convert" => {
            let field = cfg
                .get("field")
                .and_then(Value::as_str)
                .ok_or_else(|| "convert processor: 'field' required".to_string())?
                .to_string();
            let target_field = cfg
                .get("target_field")
                .and_then(Value::as_str)
                .unwrap_or(&field)
                .to_string();
            let ty = cfg
                .get("type")
                .and_then(Value::as_str)
                .ok_or_else(|| "convert processor: 'type' required".to_string())?;
            let Some(existing) = get_dotted_path_mut(source_obj, &field).map(|v| v.clone()) else {
                return if cfg
                    .get("ignore_missing")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    Ok(())
                } else {
                    Err(format!(
                        "field [{field}] not present as part of path [{field}]"
                    ))
                };
            };
            let converted: Value = match ty {
                "integer" | "long" => {
                    let n = match &existing {
                        Value::Number(n) => n.as_i64(),
                        Value::String(s) => s.parse::<i64>().ok(),
                        Value::Bool(b) => Some(if *b { 1 } else { 0 }),
                        _ => None,
                    }
                    .ok_or_else(|| format!("unable to convert [{existing}] to integer"))?;
                    json!(n)
                }
                "float" | "double" => {
                    let f = match &existing {
                        Value::Number(n) => n.as_f64(),
                        Value::String(s) => s.parse::<f64>().ok(),
                        Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
                        _ => None,
                    }
                    .ok_or_else(|| format!("unable to convert [{existing}] to float"))?;
                    serde_json::Number::from_f64(f)
                        .map(Value::Number)
                        .unwrap_or(Value::Null)
                }
                "string" => match &existing {
                    Value::String(s) => Value::String(s.clone()),
                    Value::Number(n) => Value::String(n.to_string()),
                    Value::Bool(b) => Value::String(b.to_string()),
                    other => Value::String(other.to_string()),
                },
                "boolean" => match &existing {
                    Value::Bool(b) => Value::Bool(*b),
                    Value::String(s) => match s.as_str() {
                        "true" => Value::Bool(true),
                        "false" => Value::Bool(false),
                        _ => return Err(format!("unable to convert [{existing}] to boolean")),
                    },
                    _ => return Err(format!("unable to convert [{existing}] to boolean")),
                },
                _ => existing,
            };
            set_dotted_path(source_obj, &target_field, converted);
            Ok(())
        }
        "lowercase" | "uppercase" | "trim" => {
            let field = cfg
                .get("field")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("{name} processor: 'field' required"))?
                .to_string();
            let ignore_missing = cfg
                .get("ignore_missing")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            match get_dotted_path_mut(source_obj, &field) {
                Some(v) => {
                    if let Value::String(s) = v {
                        *s = match name {
                            "lowercase" => s.to_lowercase(),
                            "uppercase" => s.to_uppercase(),
                            "trim" => s.trim().to_string(),
                            _ => s.clone(),
                        };
                    }
                    Ok(())
                }
                None => {
                    if ignore_missing {
                        Ok(())
                    } else {
                        // ES raises illegal_argument_exception when the
                        // referenced field isn't present and
                        // ignore_missing isn't true.
                        Err(format!(
                            "field [{field}] not present as part of path [{field}]"
                        ))
                    }
                }
            }
        }
        // Everything else is accepted as a no-op so that custom processors
        // don't fail the simulate. The ES spec requires every declared
        // processor to be known, but xerj's compat layer is deliberately
        // forgiving here to match what YAML tests actually exercise.
        _ => Ok(()),
    }
}

pub async fn simulate_ingest_pipeline(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(params): Query<SimulatePipelineParams>,
    Json(body): Json<SimulatePipelineBody>,
) -> impl IntoResponse {
    // Look up the stored pipeline; treat missing as 404.
    let stored = match state.engine.pipelines.get(&id) {
        Some(p) => p.clone(),
        None => {
            let e = xerj_common::XerjError::index_not_found(format!("pipeline [{id}] is missing"));
            return ApiError::new(e).into_response();
        }
    };

    // The stored pipeline may be in ES shape (`processors: [{set: {...}}]`)
    // when it was round-tripped verbatim, OR in xerj internal shape
    // (`stages: [{type: "set", config: {...}}]`) after compilation.
    // Accept either — convert stages back into the ES-processor shape.
    //
    // The conversion has to invert BOTH halves of the translation
    // `put_ingest_pipeline` applied, name and config. Emitting the internal
    // name here reported `processor_type: "field_rename"` where ES reports
    // `"rename"` — invisible while every ES `rename` failed to compile (the
    // raw ES body was stored, so this branch was never taken), and a
    // conformance failure the moment `rename` started compiling.
    let processors: Vec<Value> = if let Some(p) = stored.get("processors").and_then(Value::as_array)
    {
        p.clone()
    } else if let Some(stages) = stored.get("stages").and_then(Value::as_array) {
        stages_to_es_processors(stages)
    } else {
        Vec::new()
    };

    // If the caller also inlined a pipeline, ES rejects with parse_exception.
    if body.pipeline.is_some() {
        return build_ingest_parse_error(
            "pipeline",
            "cannot combine stored pipeline and inline pipeline",
        );
    }

    let verbose = params.verbose.as_deref() == Some("true");
    let out_docs: Vec<Value> = body
        .docs
        .iter()
        .map(|d| run_inline_pipeline_on_doc(d, &processors, verbose))
        .collect();

    Json(json!({ "docs": out_docs })).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_close — mark index as closed
// POST /{index}/_open  — mark index as open
// ─────────────────────────────────────────────────────────────────────────────

pub async fn close_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    // Closing stays stricter than `action.destructive_requires_name`: a
    // wildcard or `_all` is refused even when that setting is false. Only
    // concrete names may close.
    if index == "_all" || index.contains('*') {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({
                "error": {
                    "root_cause": [{
                        "type": "illegal_argument_exception",
                        "reason": "Wildcard expressions or all indices are not allowed"
                    }],
                    "type": "illegal_argument_exception",
                    "reason": "Wildcard expressions or all indices are not allowed"
                },
                "status": 400
            })),
        )
            .into_response();
    }
    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => return ApiError::new(e).into_response(),
    };
    let mut indices = serde_json::Map::new();
    for (name, _) in &handles {
        // #463: actually release the index's RAM (flush → drop the in-memory
        // handle), not just flip the closed flag. A flush failure aborts the
        // close and leaves the index in service rather than losing data.
        if let Err(e) = state.engine.close_index(name).await {
            return ApiError::new(xerj_common::XerjError::from(e)).into_response();
        }
        indices.insert(name.clone(), json!({ "closed": true }));
    }
    Json(json!({
        "acknowledged": true,
        "shards_acknowledged": true,
        "indices": indices
    }))
    .into_response()
}

pub async fn open_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => return ApiError::new(e).into_response(),
    };
    for (name, idx) in &handles {
        state.engine.closed_indices.remove(name);
        // On reopen, re-evaluate index-sort from the CURRENT mapping —
        // dynamic mapping may have since added a `@timestamp` date
        // field. ES sorts segments on reopen when the mapping permits.
        let has_ts_declared = state
            .engine
            .index_mappings
            .get(name)
            .map(|r| {
                let m = r.value();
                let t = m
                    .pointer("/mappings/properties/@timestamp/type")
                    .or_else(|| m.pointer("/properties/@timestamp/type"))
                    .and_then(Value::as_str);
                matches!(t, Some("date") | Some("date_nanos"))
            })
            .unwrap_or(false);
        // Fallback: probe any indexed doc. ES treats a
        // successfully-ingested `@timestamp` value as evidence the
        // field exists for sort-on-reopen purposes, even when the
        // mapping was never formalised (pure-dynamic ingest).
        let has_ts_via_source = if has_ts_declared {
            true
        } else {
            // A minimal one-doc match_all probe.
            let req = xerj_query::ast::SearchRequest {
                query: xerj_query::ast::QueryNode::MatchAll,
                from: 0,
                size: 1,
                track_total_hits: xerj_query::ast::TrackTotalHits::Limit(1),
                ..Default::default()
            };
            match idx.search(&req).await {
                Ok(r) => r
                    .hits
                    .first()
                    .map(|h| h.source.get("@timestamp").is_some())
                    .unwrap_or(false),
                _ => false,
            }
        };
        let has_ts = has_ts_declared || has_ts_via_source;
        if has_ts {
            let existing = state
                .engine
                .index_settings
                .get(name)
                .map(|r| r.value().clone())
                .unwrap_or(Value::Null);
            let mut merged = match existing {
                Value::Object(m) => m,
                _ => serde_json::Map::new(),
            };
            merged.insert("__xy_index_sort_field".to_string(), json!("@timestamp"));
            merged.insert("__xy_index_sort_order".to_string(), json!("desc"));
            // Reopen-derived hint (dynamic @timestamp picked up at
            // close/open): `_close` drains the whole memtable into ONE
            // consolidated segment, so the per-refresh leaf structure ES
            // preserves is already gone by the first post-reopen search.
            // Mark the provenance so the search path keeps the
            // historical per-doc `@timestamp desc` sort for these
            // indices (the 380_sort_segments_on_timestamp.yml reopen
            // contract) instead of the settled leaf-order semantics
            // reserved for create-time-mapped indices.
            merged.insert("__xy_index_sort_reopen".to_string(), json!(true));
            state
                .engine
                .index_settings
                .insert(name.clone(), Value::Object(merged));
        }
    }
    Json(json!({
        "acknowledged": true,
        "shards_acknowledged": true,
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_forcemerge — trigger a merge pass synchronously
// ─────────────────────────────────────────────────────────────────────────────

#[derive(serde::Deserialize)]
pub struct ForcemergeParams {
    /// ES `max_num_segments`: merge down to at most this many segments.
    /// XERJ defaults to 1 (full merge) so a bench "forcemerge + settle"
    /// step leaves the index fully quiesced, matching what it does to ES.
    pub max_num_segments: Option<usize>,
}

pub async fn forcemerge(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<ForcemergeParams>,
) -> impl IntoResponse {
    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => {
            return (
                axum::http::StatusCode::NOT_FOUND,
                Json(json!({
                    "error": {"type": "index_not_found_exception", "reason": e.to_string()}
                })),
            )
                .into_response()
        }
    };
    // ES semantics: SYNCHRONOUS, and — for a wildcard/comma spec — applies
    // to EVERY matching index. `force_merge` waits for any in-flight
    // background merge pass (instead of the pre-fix behaviour of returning
    // `merged_batches: 0` and leaving the background merge churning through
    // the caller's read phase), then drives merge passes until the segment
    // count converges to the target. Long-running is fine — callers wait;
    // bound each index with a generous 30-minute request timeout.
    let target = params.max_num_segments.unwrap_or(1);
    let mut merged_batches_total: usize = 0;
    let mut segments_total: usize = 0;
    for (_, idx) in &handles {
        match tokio::time::timeout(
            std::time::Duration::from_secs(30 * 60),
            idx.force_merge(target),
        )
        .await
        {
            Ok(Ok(total)) => {
                merged_batches_total += total;
                segments_total += idx.store_snapshot().segments.len();
            }
            Ok(Err(e)) => {
                return (
                    axum::http::StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({
                        "error": {"type": "force_merge_failed", "reason": e.to_string()}
                    })),
                )
                    .into_response()
            }
            Err(_) => {
                return (
                    axum::http::StatusCode::SERVICE_UNAVAILABLE,
                    Json(json!({
                        "error": {"type": "force_merge_timeout", "reason": "forcemerge did not complete within 30 minutes"}
                    })),
                )
                    .into_response()
            }
        }
    }
    let n = handles.len() as u32;
    Json(json!({
        "_shards": { "total": n, "successful": n, "failed": 0 },
        "merged_batches": merged_batches_total,
        "segments": segments_total,
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_admin/segments/fsck — re-validate every section CRC32C
//
// xerj segments carry a per-section CRC32C computed at write time (see
// xerj-storage/src/segment.rs::SectionEntry::crc32c). The whole-file
// CRC is verified at open time; per-section CRC is normally skipped on
// the search hot path for perf. This endpoint is the on-demand fsck —
// it walks every section in every segment and recomputes the CRC,
// returning a structured report. Operators run it periodically, on
// suspicion, or after a hardware event.
// ─────────────────────────────────────────────────────────────────────────────

pub async fn admin_segments_fsck(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => return ApiError::new(e).into_response(),
    };
    // A wildcard/comma spec fscks every matching index; segment_ids are
    // globally unique so the merged `segments` list needs no per-index
    // tagging to stay unambiguous. `xerj_storage::FsckReport` isn't a type
    // this crate depends on directly, so the merge is done on the `Value`
    // each per-index report already serializes to, rather than pulling in
    // a new crate dependency for one struct literal.
    let mut segments: Vec<Value> = Vec::new();
    let mut total_segments_checked: u64 = 0;
    let mut total_sections_checked: u64 = 0;
    let mut corrupt_sections: u64 = 0;
    for (_, idx) in &handles {
        // Block-in-place: fsck is CPU-bound (Crc32c over potentially
        // hundreds of MB) and we don't want to stall a tokio worker for it.
        let report = tokio::task::block_in_place(|| idx.fsck_segments());
        let report_val = serde_json::to_value(&report).unwrap_or(json!({}));
        total_segments_checked += report_val
            .get("total_segments_checked")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        total_sections_checked += report_val
            .get("total_sections_checked")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        corrupt_sections += report_val
            .get("corrupt_sections")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        if let Some(Value::Array(mut segs)) = report_val.get("segments").cloned() {
            segments.append(&mut segs);
        }
    }
    let status = if corrupt_sections == 0 {
        StatusCode::OK
    } else {
        // 500 so any monitoring (Datadog, Prometheus blackbox) treats
        // a corruption hit as a hard incident, not a green ping.
        StatusCode::INTERNAL_SERVER_ERROR
    };
    (
        status,
        Json(json!({
            "segments": segments,
            "total_segments_checked": total_segments_checked,
            "total_sections_checked": total_sections_checked,
            "corrupt_sections": corrupt_sections,
        })),
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_flush — synchronously drain memtable to a durable segment
// ─────────────────────────────────────────────────────────────────────────────
//
// ES wire shape:
//     POST /<index>/_flush  ->  { "_shards": {...} }
//
// XERJ semantics: walks every memtable shard, flushes each to a segment,
// awaits all writes, then forces a WAL checkpoint + prune.  After the call
// returns 200 the index is durable across SIGKILL — no data lives only in
// the memtable.  Does the same work as the native /v1/indices/:name/_flush
// handler; the only difference is the wire shape ES clients expect.

pub async fn flush_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    match state.engine.flush_index(&index).await {
        Ok(()) => Json(json!({
            "_shards": { "total": 1, "successful": 1, "failed": 0 }
        }))
        .into_response(),
        Err(e) => {
            // index-not-found wraps as 404; everything else is 500
            let msg = e.to_string();
            let status = if msg.contains("not found") || msg.contains("no such") {
                axum::http::StatusCode::NOT_FOUND
            } else {
                axum::http::StatusCode::INTERNAL_SERVER_ERROR
            };
            (
                status,
                Json(json!({
                    "error": { "type": "flush_failed", "reason": msg }
                })),
            )
                .into_response()
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_flush — flush every index in the cluster
// ─────────────────────────────────────────────────────────────────────────────

pub async fn flush_all(State(state): State<AppState>) -> impl IntoResponse {
    let names: Vec<String> = state
        .engine
        .list_indices()
        .await
        .into_iter()
        .map(|i| i.name)
        .collect();
    let mut succ = 0usize;
    let mut fail = 0usize;
    for name in names {
        match state.engine.flush_index(&name).await {
            Ok(()) => succ += 1,
            Err(_) => fail += 1,
        }
    }
    Json(json!({
        "_shards": { "total": succ + fail, "successful": succ, "failed": fail }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_tasks — return empty tasks list
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_tasks(State(state): State<AppState>) -> impl IntoResponse {
    let node = state.engine.node_id.as_str().to_string();
    let mut tasks = serde_json::Map::new();
    for entry in state.tasks.list() {
        tasks.insert(entry.key(), task_to_json(&entry));
    }
    Json(json!({
        "nodes": {
            node.clone(): {
                "name": node,
                "tasks": Value::Object(tasks),
            }
        }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_cache/clear — release the index's rebuildable caches
// ─────────────────────────────────────────────────────────────────────────────

pub async fn clear_cache(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    // Resolve wildcard/comma/_all specs to every matching index (404 only
    // when a literal name doesn't exist). Clearing flushes each index and
    // releases its hydrated per-segment caches (#950); the next read
    // re-hydrates from disk, so this is a memory lever, never a data change.
    let index = strip_remote_cluster_prefix(&index);
    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => return ApiError::new(e).into_response(),
    };
    let indices: Vec<_> = handles
        .iter()
        .map(|(_, idx)| std::sync::Arc::clone(idx))
        .collect();
    state.engine.release_rebuildable_memory(&indices).await;
    let n = handles.len() as u32;
    Json(json!({
        "_shards": { "total": n, "successful": n, "failed": 0 }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// HEAD /{index} — check if index exists (200 / 404)
// ─────────────────────────────────────────────────────────────────────────────

pub async fn head_index(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    if state.engine.get_index(&index).is_ok() {
        return StatusCode::OK.into_response();
    }
    // This is the existence probe every ES client's `indices.exists()` calls,
    // and existence is a metadata question. An index whose directory refused
    // to open still occupies its name and still has bytes on disk, so 404 here
    // was the same lie `GET /{index}` told (issue #206) — and a client that
    // did HEAD (404) then PUT (503 `no_shard_available_action_exception`) got
    // two incompatible answers about one name. Visibility-filtered via
    // `list_failed_indices`, so a scoped key cannot probe for another brain's
    // failed index either.
    if state
        .engine
        .list_failed_indices()
        .iter()
        .any(|f| f.name == index)
    {
        return StatusCode::OK.into_response();
    }
    StatusCode::NOT_FOUND.into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/templates — list templates in text format
// ─────────────────────────────────────────────────────────────────────────────

/// Query params for `/_cat/templates` (and its `{pattern}` variant).
/// `format=json` returns a JSON array instead of the plain-text table —
/// OpenSearch Dashboards' own `cat.templates()` call requests this.
#[derive(Debug, Deserialize, Default)]
pub struct CatTemplatesParams {
    #[serde(default)]
    pub format: Option<String>,
}

pub async fn cat_templates(
    State(state): State<AppState>,
    Query(params): Query<CatTemplatesParams>,
) -> impl IntoResponse {
    cat_templates_inner(state, None, params).await
}

/// `GET /_cat/templates/{pattern}` — the pattern-scoped variant.
///
/// Previously unrouted, so a wildcard-pattern call (e.g. OpenSearch
/// Dashboards' own startup check for `opensearch_dashboards_index_template*`)
/// fell through to the router's bare 404 fallback: no body at all, not even
/// an ES-shaped JSON error. `opensearch-js`'s `cat.templates()` can't parse
/// an empty body and throws — found empirically, this is what actually
/// crashes OSD's saved-objects migration, not the (perfectly well-formed)
/// `.kibana` 404 it hits right before this call.
///
/// Same `_cat` selector semantics as `/_cat/indices/{pattern}`: a WILDCARD
/// matching nothing is an empty 200, never a 404 — a concrete template name
/// matching nothing does 404, but templates have no equivalent of `_all`
/// index-not-found semantics worth enforcing here since nothing currently
/// creates a naming collision risk.
pub async fn cat_templates_pattern(
    State(state): State<AppState>,
    Path(pattern): Path<String>,
    Query(params): Query<CatTemplatesParams>,
) -> impl IntoResponse {
    cat_templates_inner(state, Some(pattern), params).await
}

async fn cat_templates_inner(
    state: AppState,
    pattern: Option<String>,
    params: CatTemplatesParams,
) -> axum::response::Response {
    let matches_pattern = |name: &str| match pattern.as_deref() {
        None => true,
        Some(pat) => pat
            .split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .any(|p| p == "_all" || p == "*" || p == name || glob_match_simple(p, name)),
    };

    let mut rows: Vec<(String, Vec<String>, i32)> = state
        .engine
        .templates
        .iter()
        .filter(|entry| matches_pattern(entry.key()))
        .map(|entry| {
            let t = entry.value();
            (entry.key().clone(), t.index_patterns.clone(), t.priority)
        })
        .collect();
    rows.sort_by(|a, b| a.0.cmp(&b.0));

    if params.format.as_deref() == Some("json") {
        let arr: Vec<Value> = rows
            .iter()
            .map(|(name, index_patterns, priority)| {
                json!({
                    "name": name,
                    "index_patterns": format!("[{}]", index_patterns.join(", ")),
                    "order": priority.to_string(),
                    "version": "",
                })
            })
            .collect();
        return Json(arr).into_response();
    }

    let mut lines: Vec<String> = Vec::new();
    for (name, index_patterns, priority) in &rows {
        lines.push(format!(
            "{} {} {} -",
            name,
            index_patterns.join(","),
            priority
        ));
    }
    let body = if lines.is_empty() {
        String::new()
    } else {
        lines.join("\n") + "\n"
    };
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// Data Streams
// PUT    /_data_stream/{name}
// GET    /_data_stream/{name}
// DELETE /_data_stream/{name}
// POST   /{data_stream}/_rollover
// ─────────────────────────────────────────────────────────────────────────────

pub async fn put_data_stream(
    State(state): State<AppState>,
    Path(name): Path<String>,
) -> impl IntoResponse {
    match state.engine.create_data_stream(&name) {
        Ok(()) => Json(json!({ "acknowledged": true })).into_response(),
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

/// `GET /_data_stream/{pattern}` — a comma-separated list of concrete names
/// and/or glob patterns, same selector rules as `_cat/indices/{pattern}`: a
/// WILDCARD matching nothing is an empty 200, a CONCRETE name matching
/// nothing 404s. Previously only recognized the exact literals `*`/`_all`
/// as wildcards — anything else, including the double-asterisk `**`
/// OpenSearch Dashboards' own Data Streams page requests, fell through to
/// the concrete-name branch and 404'd with `index_not_found_exception`
/// even though it's a legitimate wildcard matching zero streams.
pub async fn get_data_stream(
    State(state): State<AppState>,
    Path(name): Path<String>,
) -> impl IntoResponse {
    let parts: Vec<&str> = name
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .collect();
    let is_wildcard = |p: &str| p == "_all" || p.contains('*');

    for &p in &parts {
        if !is_wildcard(p) && !state.engine.data_streams.contains_key(p) {
            let e = xerj_common::XerjError::index_not_found(format!("data_stream [{p}] missing"));
            return ApiError::new(e).into_response();
        }
    }

    let streams: Vec<Value> = state
        .engine
        .data_streams
        .iter()
        .filter(|entry| {
            let ds_name = entry.key();
            parts
                .iter()
                .any(|&p| is_wildcard(p) || p == ds_name || glob_match_simple(p, ds_name))
        })
        .map(|entry| data_stream_to_json(entry.value()))
        .collect();
    Json(json!({ "data_streams": streams })).into_response()
}

fn data_stream_to_json(ds: &xerj_engine::engine::DataStream) -> Value {
    json!({
        "name": ds.name,
        "timestamp_field": { "name": ds.timestamp_field },
        "indices": ds.backing_indices.iter().map(|i| json!({ "index_name": i })).collect::<Vec<_>>(),
        "generation": ds.generation,
        "status": "GREEN",
        "template": "",
    })
}

#[cfg(test)]
mod data_stream_wildcard_tests {
    use super::*;
    use axum::{body::Body, http::Request};
    use tower::ServiceExt;

    fn test_state() -> AppState {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        AppState::new(config, engine, metrics)
    }

    /// OpenSearch Dashboards' Data Streams page calls `GET _data_stream/**`
    /// to list everything. Only the exact literals `*`/`_all` were ever
    /// recognized as wildcards, so `**` fell into the concrete-name branch
    /// and 404'd with `index_not_found_exception: data_stream [**] missing`
    /// — even with zero data streams, where real ES/OS returns an empty
    /// array with 200. Confirmed against a real OpenSearch node.
    #[tokio::test]
    async fn double_asterisk_wildcard_with_no_streams_is_empty_200_not_404() {
        let state = test_state();
        let app = crate::router::build_es_compat_router(state);
        let response = app
            .oneshot(
                Request::get("/_data_stream/**")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body["data_streams"], json!([]));
    }

    /// A concrete, non-wildcard name that doesn't exist must still 404 —
    /// this fix is scoped to wildcard recognition, not to loosening that.
    #[tokio::test]
    async fn concrete_missing_name_still_404s() {
        let state = test_state();
        let app = crate::router::build_es_compat_router(state);
        let response = app
            .oneshot(
                Request::get("/_data_stream/does-not-exist")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NOT_FOUND);
    }

    /// OSD's Index Management pages call `/api/dataconnections` on every
    /// load, which proxies straight through to this route; it was entirely
    /// unregistered (404), which OSD's own backend turned into an opaque
    /// 500 and a stray "Not Found" toast even on pages unrelated to Query
    /// Workbench. xerj has no external-data-connection subsystem, so an
    /// honest empty list (not a 404) is the correct answer.
    #[tokio::test]
    async fn query_workbench_datasources_is_an_honest_empty_list_not_404() {
        let state = test_state();
        let app = crate::router::build_es_compat_router(state);
        let response = app
            .oneshot(
                Request::get("/_plugins/_query/_datasources")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(body, json!([]));
    }
}

