// ─────────────────────────────────────────────────────────────────────────────
// GET /_cluster/state
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cluster_state(State(state): State<AppState>) -> impl IntoResponse {
    let indices = state.engine.list_indices().await;
    let node_id = state.engine.node_id.as_str();
    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;

    let mut metadata_indices = serde_json::Map::new();
    let mut routing_table = serde_json::Map::new();

    for info in &indices {
        metadata_indices.insert(
            info.name.clone(),
            json!({
                "state": "open",
                "settings": {
                    "index": {
                        "number_of_shards": "1",
                        "number_of_replicas": "0",
                        "uuid": uuid::Uuid::new_v4().to_string(),
                        "version": { "created": "8130099" },
                        "provided_name": info.name,
                    }
                },
                "mappings": {},
                "aliases": [],
            }),
        );
        routing_table.insert(
            info.name.clone(),
            json!({
                "shards": {
                    "0": [{
                        "state": "STARTED",
                        "primary": true,
                        "node": node_id,
                        "relocating_node": null,
                        "shard": 0,
                        "index": info.name,
                    }]
                }
            }),
        );
    }

    // An index that would not open still exists — its metadata belongs in
    // cluster state, and its shard is UNASSIGNED with the open error as the
    // allocation-failure detail. Leaving it out is what made a failed index
    // invisible to every tool that reads cluster state (issue #206).
    let mut unassigned_shards: Vec<Value> = Vec::new();
    for f in state.engine.list_failed_indices() {
        metadata_indices.insert(
            f.name.clone(),
            json!({
                "state": "open",
                "settings": {
                    "index": {
                        "number_of_shards": "1",
                        "number_of_replicas": "0",
                        "uuid": stable_index_uuid(&f.name),
                        "version": { "created": "8130099" },
                        "provided_name": f.name,
                    }
                },
                "mappings": {},
                "aliases": [],
            }),
        );
        let shard = json!({
            "state": "UNASSIGNED",
            "primary": true,
            "node": null,
            "relocating_node": null,
            "shard": 0,
            "index": f.name,
            "unassigned_info": unassigned_info_json(&f),
        });
        routing_table.insert(
            f.name.clone(),
            json!({ "shards": { "0": [shard.clone()] } }),
        );
        unassigned_shards.push(shard);
    }

    // Honest topology (#1169): the self entry's transport address is this
    // node's real configured cluster address (previously the never-bound
    // default 9300), and configured peers appear as minimal entries. On a
    // configured ring `master_node` is null rather than self: the REST
    // layer does not know the elected leader (#1170), and claiming
    // mastership from every node is the same fabrication this fixes.
    let members = configured_members(&state.config);
    let own_addr = members
        .first()
        .map(|(_, a)| a.to_string())
        .unwrap_or_else(|| "127.0.0.1:9300".to_string());
    let mut state_nodes = serde_json::Map::new();
    state_nodes.insert(
        node_id.to_string(),
        json!({
            "name": node_id,
            "transport_address": own_addr,
            "roles": ["master", "data", "ingest"],
        }),
    );
    for (peer_id, addr) in members.iter().skip(1) {
        state_nodes.insert(
            peer_id.clone(),
            json!({
                "name": peer_id,
                "transport_address": addr.to_string(),
            }),
        );
    }

    Json(json!({
        "cluster_name": "xerj",
        "cluster_uuid": "xerj-cluster-1",
        "version": 1,
        "state_uuid": uuid::Uuid::new_v4().to_string(),
        "master_node": if state.config.cluster.enabled { Value::Null } else { json!(node_id) },
        "blocks": {},
        "nodes": Value::Object(state_nodes),
        "metadata": {
            "cluster_uuid": "xerj-cluster-1",
            "templates": {},
            "indices": metadata_indices,
        },
        "routing_table": {
            "indices": routing_table,
        },
        "routing_nodes": {
            "unassigned": unassigned_shards,
            "nodes": {
                node_id: []
            }
        },
        "timestamp": now_ms,
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cat/allocation
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cat_allocation(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // shards  disk.indices  disk.used  disk.avail  disk.total  disk.percent  host         ip           node
    let health = state.engine.health().await;

    // Real disk.indices = sum of every index's on-disk data_dir byte size.
    let indices = state.engine.list_indices().await;
    let mut indices_bytes: u64 = 0;
    for info in &indices {
        if let Ok(idx) = state.engine.get_index(&info.name) {
            indices_bytes += dir_size_bytes(idx.data_dir());
        }
    }
    // disk.used: best available real signal is the xerj-managed bytes on disk
    // (sum of index data_dirs); without statvfs/libc we cannot read true fs
    // used, so used == indices here.
    // Real filesystem stats for the data dir (statvfs); disk.used is the true
    // fs used (total - avail), disk.indices stays the xerj-managed byte sum.
    let (disk_total, disk_avail) = read_disk_stats(&state.config.server.data_dir)
        .unwrap_or((10 * 1024 * 1024 * 1024, 8 * 1024 * 1024 * 1024));
    let disk_used_bytes = disk_total.saturating_sub(disk_avail);
    // Same integer percent the governor admits on (`used * 100 / total` in
    // u128). The previous u64 multiply overflows on a volume larger than
    // `u64::MAX / 100`, which would report a low percent while the write
    // block used the real one. Realistic disks are unchanged.
    let disk_percent = if disk_total == 0 {
        0
    } else {
        ((disk_used_bytes as u128 * 100) / disk_total as u128) as u64
    };

    let shards = health.index_count;

    if params.format.as_deref() == Some("json") {
        let mut row = json!({
            "shards": shards.to_string(),
            "disk.indices": format!("{indices_bytes}b"),
            "disk.used": format!("{disk_used_bytes}b"),
            "disk.avail": format!("{disk_avail}b"),
            "disk.total": format!("{disk_total}b"),
            "disk.percent": disk_percent.to_string(),
            "host": "127.0.0.1",
            "ip": "127.0.0.1",
            "node": "xerj-node-1",
            // #2284: memory writes name this directory when the flood-stage
            // block fires. Not a cat column — the text table below is unchanged.
            "path.data": state.config.server.data_dir,
        });
        // #2077: effective flood-stage gate, so autoindex can refuse before
        // it walks. Not cat columns — the text table below is unchanged.
        // Omitted when no governor is installed; the client then does not
        // guess a threshold.
        if let Some(governor) = xerj_engine::governor::global() {
            let gate = governor.disk_flood_admission();
            row["disk.flood_stage"] = json!(gate.flood_pct.to_string());
            row["disk.threshold_enabled"] = json!(gate.threshold_enabled.to_string());
            row["disk.flood_blocked"] = json!(gate.blocked.to_string());
        }
        return Json(vec![row]).into_response();
    }

    let body = format!(
        "{shards} {indices_bytes}b {disk_used_bytes}b {disk_avail}b {disk_total}b {disk_percent} 127.0.0.1 127.0.0.1 xerj-node-1\n"
    );
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

/// Real `(total_bytes, avail_bytes)` for the filesystem backing `path`,
/// delegated to `xerj_engine::governor::disk_stats` (`statvfs` on Unix,
/// `GetDiskFreeSpaceExW` on Windows). Returns `None` if the probe fails.
fn read_disk_stats(path: &str) -> Option<(u64, u64)> {
    xerj_engine::governor::disk_stats(path)
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}/_alias           — all aliases for an index
// GET /{index}/_alias/{alias}   — check specific alias for index
// ─────────────────────────────────────────────────────────────────────────────

/// Look up the stored alias metadata for (index, alias) — falls back to `{}`.
///
/// The raw blob that came in on `PUT /{index}/_alias/{name}` (or via
/// `POST /_aliases`) carries ES-style keys: `routing`, `index_routing`,
/// `search_routing`, `filter`, `is_write_index`, `is_hidden`. On read we
/// normalize `routing` into the pair `(index_routing, search_routing)`
/// because that's the shape the YAML tests and `GET /_alias` match on.
fn alias_meta_for(state: &AppState, index: &str, alias: &str) -> Value {
    let raw = state
        .engine
        .index_alias_metadata
        .get(index)
        .and_then(|v| v.get(alias).cloned())
        .unwrap_or_else(|| json!({}));
    normalize_alias_meta(raw)
}

fn normalize_alias_meta(meta: Value) -> Value {
    let Some(mut obj) = meta.as_object().cloned() else {
        return json!({});
    };
    if let Some(r) = obj.remove("routing") {
        obj.entry("index_routing".to_string()).or_insert(r.clone());
        obj.entry("search_routing".to_string()).or_insert(r);
    }
    Value::Object(obj)
}

/// `HEAD /_alias` — 200 iff any alias exists on any index.
pub async fn head_all_aliases_all_indices(State(state): State<AppState>) -> impl IntoResponse {
    if state.engine.aliases.is_empty() {
        StatusCode::NOT_FOUND
    } else {
        StatusCode::OK
    }
}

/// `HEAD /_alias/:alias` — 200 iff the named alias (or one of the
/// comma-separated / wildcard names) maps to at least one index.
pub async fn head_alias_all_indices(
    State(state): State<AppState>,
    Path(alias): Path<String>,
) -> impl IntoResponse {
    let indices: Vec<String> = state
        .engine
        .list_indices()
        .await
        .into_iter()
        .map(|i| i.name)
        .collect();
    let alias_matches = |a: &str| -> bool {
        alias
            .split(',')
            .map(str::trim)
            .any(|pat| pat == "_all" || pat == "*" || glob_match_simple(pat, a) || pat == a)
    };
    let found = indices.iter().any(|idx| {
        state
            .engine
            .aliases
            .iter()
            .any(|entry| entry.value().contains(idx) && alias_matches(entry.key()))
    });
    if found {
        StatusCode::OK
    } else {
        StatusCode::NOT_FOUND
    }
}

