/// `GET /_alias` — every alias on every index.
pub async fn get_all_aliases_all_indices(State(state): State<AppState>) -> impl IntoResponse {
    let indices: Vec<String> = state
        .engine
        .list_indices()
        .await
        .into_iter()
        .map(|i| i.name)
        .collect();
    let mut result = serde_json::Map::new();
    for idx in &indices {
        let mut aliases_map = serde_json::Map::new();
        for entry in state.engine.aliases.iter() {
            if entry.value().contains(idx) {
                aliases_map.insert(
                    entry.key().clone(),
                    alias_meta_for(&state, idx, entry.key()),
                );
            }
        }
        result.insert(idx.clone(), json!({ "aliases": aliases_map }));
    }
    Json(Value::Object(result)).into_response()
}

/// `GET /_alias/{alias}` — look up which indices (if any) carry this alias.
///
/// Supports comma-separated names and wildcards (`alias*`, `*`, `_all`).
pub async fn get_alias_all_indices(
    State(state): State<AppState>,
    Path(alias): Path<String>,
) -> impl IntoResponse {
    let indices: Vec<String> = state
        .engine
        .list_indices()
        .await
        .into_iter()
        .map(|i| i.name)
        .collect();

    let alias_matches = |a: &str| -> bool {
        alias
            .split(',')
            .map(str::trim)
            .any(|pat| pat == "_all" || pat == "*" || glob_match_simple(pat, a) || pat == a)
    };

    let mut result = serde_json::Map::new();
    for idx in &indices {
        let mut aliases_map = serde_json::Map::new();
        for entry in state.engine.aliases.iter() {
            if entry.value().contains(idx) && alias_matches(entry.key()) {
                aliases_map.insert(
                    entry.key().clone(),
                    alias_meta_for(&state, idx, entry.key()),
                );
            }
        }
        if !aliases_map.is_empty() {
            result.insert(idx.clone(), json!({ "aliases": aliases_map }));
        }
    }

    // ES returns an empty object (not 404) when no alias matches on a
    // query like `GET /_alias/nonexistent`. That matches the YAML tests'
    // `is_false: foo` expectations.
    Json(Value::Object(result)).into_response()
}

pub async fn get_index_aliases(
    State(state): State<AppState>,
    Path(index): Path<String>,
) -> impl IntoResponse {
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }

    // For each resolved concrete index, collect every alias whose backing
    // set contains it, attaching the real stored filter/routing metadata
    // (normalized to ES index_routing/search_routing form). ES shape:
    // { index: { aliases: { aliasName: { ...meta } } } }.
    let mut out = serde_json::Map::new();
    for name in &targets {
        let mut aliases_map = serde_json::Map::new();
        for entry in state.engine.aliases.iter() {
            if entry.value().contains(name) {
                aliases_map.insert(
                    entry.key().clone(),
                    alias_meta_for(&state, name, entry.key()),
                );
            }
        }
        out.insert(name.clone(), json!({ "aliases": aliases_map }));
    }
    Json(Value::Object(out)).into_response()
}

pub async fn get_index_alias(
    State(state): State<AppState>,
    Path((index, alias)): Path<(String, String)>,
) -> impl IntoResponse {
    let targets = resolve_index_selector(&state, &index).await;
    if targets.is_empty() {
        let e = xerj_common::XerjError::index_not_found(&index);
        return ApiError::new(e).into_response();
    }

    let alias_matches = |a: &str| -> bool {
        alias
            .split(',')
            .map(str::trim)
            .any(|pat| pat == "_all" || pat == "*" || glob_match_simple(pat, a) || pat == a)
    };

    let mut out = serde_json::Map::new();
    for name in &targets {
        let mut aliases_map = serde_json::Map::new();
        for entry in state.engine.aliases.iter() {
            if entry.value().contains(name) && alias_matches(entry.key()) {
                aliases_map.insert(
                    entry.key().clone(),
                    alias_meta_for(&state, name, entry.key()),
                );
            }
        }
        if !aliases_map.is_empty() {
            out.insert(name.clone(), json!({ "aliases": aliases_map }));
        }
    }
    Json(Value::Object(out)).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// Snapshot Repository & Snapshot APIs
// PUT    /_snapshot/{repo}
// GET    /_snapshot/{repo}
// DELETE /_snapshot/{repo}
// PUT    /_snapshot/{repo}/{snapshot}
// GET    /_snapshot/{repo}/{snapshot}
// ─────────────────────────────────────────────────────────────────────────────

/// Validate a snapshot repository name. The `repo` is used as a key in the
/// in-memory `snapshot_repos` map, but it is also echoed in API responses and
/// surfaced in logs, and a future change could path-join it. Reject anything
/// that could traverse (`..`) or contain a path separator.
fn validate_snapshot_repo_name(repo: &str) -> Result<(), xerj_common::XerjError> {
    if repo.is_empty() {
        return Err(xerj_common::XerjError::invalid_mapping(
            "snapshot repository name must not be empty",
        ));
    }
    if repo.contains("..") || repo.contains('/') || repo.contains('\\') || repo.contains('\0') {
        return Err(xerj_common::XerjError::invalid_mapping(format!(
            "invalid snapshot repository name [{repo}]: must not contain '..', '/', '\\', or NUL"
        )));
    }
    Ok(())
}

/// Validate a snapshot name. The snapshot name is path-joined onto the repo's
/// `settings.location` inside the engine (`Path::new(repo_path).join(name)`),
/// so `..` or a separator would let a write escape the repo. ES restricts
/// snapshot names to `[a-zA-Z0-9._-]`; we apply the same traversal-blocking
/// rule as `IndexName::validate` (no `..`, no separators, no NUL).
fn validate_snapshot_name(name: &str) -> Result<(), xerj_common::XerjError> {
    if name.is_empty() {
        return Err(xerj_common::XerjError::invalid_mapping(
            "snapshot name must not be empty",
        ));
    }
    if name == "."
        || name == ".."
        || name.contains("..")
        || name.contains('/')
        || name.contains('\\')
        || name.contains('\0')
    {
        return Err(xerj_common::XerjError::invalid_mapping(format!(
            "invalid snapshot name [{name}]: must not be '.' or '..' and must not contain '..', '/', '\\', or NUL"
        )));
    }
    Ok(())
}

pub async fn put_snapshot_repo(
    State(state): State<AppState>,
    Path(repo): Path<String>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    // Reject repository names that would let a later create/restore escape
    // the configured filesystem location via `..` or separators. The snapshot
    // name is path-joined onto `repo_path` inside the engine; a `repo` of
    // `..` is a path-traversal vector even before the repo's `settings.location`
    // is consulted.
    if let Err(e) = validate_snapshot_repo_name(&repo) {
        return ApiError::new(e).into_response();
    }
    state.engine.snapshot_repos.insert(repo, body);
    Json(json!({ "acknowledged": true })).into_response()
}

pub async fn get_snapshot_repo(
    State(state): State<AppState>,
    Path(repo): Path<String>,
) -> impl IntoResponse {
    if repo == "*" || repo == "_all" {
        let mut result = serde_json::Map::new();
        for entry in state.engine.snapshot_repos.iter() {
            result.insert(entry.key().clone(), entry.value().clone());
        }
        return Json(Value::Object(result)).into_response();
    }
    match state.engine.snapshot_repos.get(&repo) {
        Some(r) => Json(json!({ repo.clone(): r.clone() })).into_response(),
        None => {
            let e = xerj_common::XerjError::index_not_found(format!("repository [{repo}] missing"));
            ApiError::new(e).into_response()
        }
    }
}

pub async fn delete_snapshot_repo(
    State(state): State<AppState>,
    Path(repo): Path<String>,
) -> impl IntoResponse {
    if state.engine.snapshot_repos.remove(&repo).is_some() {
        Json(json!({ "acknowledged": true })).into_response()
    } else {
        let e = xerj_common::XerjError::index_not_found(format!("repository [{repo}] missing"));
        ApiError::new(e).into_response()
    }
}

pub async fn create_snapshot(
    State(state): State<AppState>,
    Path((repo, snapshot)): Path<(String, String)>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    // Validate both path params before any lookup. The snapshot name is
    // path-joined onto the repo's `settings.location`; a name containing `..`
    // or a separator would let the engine write outside the repo.
    if let Err(e) = validate_snapshot_repo_name(&repo) {
        return ApiError::new(e).into_response();
    }
    if let Err(e) = validate_snapshot_name(&snapshot) {
        return ApiError::new(e).into_response();
    }
    // Look up the repository config to get the filesystem location.
    let repo_config = match state.engine.snapshot_repos.get(&repo) {
        Some(cfg) => cfg.clone(),
        None => {
            let e = xerj_common::XerjError::index_not_found(format!("repository [{repo}] missing"));
            return ApiError::new(e).into_response();
        }
    };

    // Determine the repo filesystem path.
    let repo_path = repo_config
        .pointer("/settings/location")
        .and_then(Value::as_str)
        .unwrap_or("/tmp/xerj-snapshots");

    // ES accepts `indices` as an array of names/patterns or a single
    // (possibly comma-separated) string; absent means "every index".  Reading
    // only the array spelling silently turned the string one into "absent",
    // so `{"indices":"logs-*"}` captured the whole node -- every other
    // tenant's data included -- while authorization had only ever seen the
    // narrow pattern the caller asked for.  Parsed exactly as the restore
    // side already parses it.
    let requested: Option<Vec<String>> = match body.as_ref().and_then(|b| b.get("indices")) {
        Some(Value::Array(arr)) => Some(
            arr.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect(),
        ),
        Some(Value::String(s)) => Some(vec![s.clone()]),
        _ => None,
    };
    // `create_snapshot` takes concrete names, so patterns have to be resolved
    // here. Resolving them against `index_name_list` — which the visibility
    // guard filters — is what makes the set captured equal the set
    // authorization decided on: previously a wildcard reached the engine
    // verbatim, matched nothing, and produced an empty snapshot, while the
    // string spelling was dropped entirely and captured the whole node.
    let indices: Option<Vec<String>> = requested.map(|specs| {
        let all = state.engine.index_name_list();
        let mut out: Vec<String> = Vec::new();
        let push = |name: String, out: &mut Vec<String>| {
            if !out.contains(&name) {
                out.push(name);
            }
        };
        for spec in &specs {
            for part in spec.split(',').map(str::trim).filter(|s| !s.is_empty()) {
                if part == "_all" || part == "*" {
                    for n in &all {
                        push(n.clone(), &mut out);
                    }
                } else if part.contains('*') {
                    for n in all.iter().filter(|n| glob_match_simple(part, n)) {
                        push(n.clone(), &mut out);
                    }
                } else {
                    push(part.to_string(), &mut out);
                }
            }
        }
        out
    });

    match state
        .engine
        .create_snapshot(repo_path, &snapshot, indices)
        .await
    {
        Ok(snap_info) => {
            let key = format!("{}/{}", repo, snapshot);
            state.engine.snapshots.insert(key, snap_info.clone());
            Json(json!({ "accepted": true, "snapshot": snap_info })).into_response()
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

pub async fn get_snapshot(
    State(state): State<AppState>,
    Path((repo, snapshot)): Path<(String, String)>,
) -> impl IntoResponse {
    if !state.engine.snapshot_repos.contains_key(&repo) {
        let e = xerj_common::XerjError::index_not_found(format!("repository [{repo}] missing"));
        return ApiError::new(e).into_response();
    }
    let key = format!("{}/{}", repo, snapshot);
    match state.engine.snapshots.get(&key) {
        Some(info) => Json(json!({ "snapshots": [info.clone()] })).into_response(),
        None => {
            let e = xerj_common::XerjError::index_not_found(format!(
                "snapshot [{snapshot}] missing in repository [{repo}]"
            ));
            ApiError::new(e).into_response()
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_snapshot/{repo}/{snapshot}/_restore
// ─────────────────────────────────────────────────────────────────────────────

pub async fn restore_snapshot(
    State(state): State<AppState>,
    Path((repo, snapshot)): Path<(String, String)>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    if let Err(e) = validate_snapshot_repo_name(&repo) {
        return ApiError::new(e).into_response();
    }
    if let Err(e) = validate_snapshot_name(&snapshot) {
        return ApiError::new(e).into_response();
    }
    let repo_config = match state.engine.snapshot_repos.get(&repo) {
        Some(cfg) => cfg.clone(),
        None => {
            let e = xerj_common::XerjError::index_not_found(format!("repository [{repo}] missing"));
            return ApiError::new(e).into_response();
        }
    };

    let repo_path = repo_config
        .pointer("/settings/location")
        .and_then(Value::as_str)
        .unwrap_or("/tmp/xerj-snapshots");

    let body = body.map(|Json(b)| b).unwrap_or(Value::Null);

    // Restore options that would CHANGE what gets written (index renames,
    // per-index setting rewrites, feature states) are not implemented.
    // Fail loud rather than restoring something other than what was asked
    // for — ignoring a rename_pattern would clobber the source index.
    for unsupported in [
        "rename_pattern",
        "rename_replacement",
        "feature_states",
        "index_settings",
        "ignore_index_settings",
    ] {
        if body.get(unsupported).is_some() {
            let reason =
                format!("restore option [{unsupported}] is not supported by this XERJ version");
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": {
                        "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                        "type": "illegal_argument_exception",
                        "reason": reason,
                    },
                    "status": 400,
                })),
            )
                .into_response();
        }
    }

    // ES accepts `indices` as an array of names/patterns or a single
    // (possibly comma-separated) string; absent means "all indices in
    // the snapshot".
    let indices: Option<Vec<String>> = match body.get("indices") {
        Some(Value::Array(arr)) => Some(
            arr.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect(),
        ),
        Some(Value::String(s)) => Some(vec![s.clone()]),
        _ => None,
    };

    let wait_for_completion = params
        .get("wait_for_completion")
        .map(|v| v == "true")
        .unwrap_or(false);

    match state
        .engine
        .restore_snapshot(repo_path, &snapshot, indices)
        .await
    {
        // Restores run synchronously either way; `wait_for_completion`
        // only selects the ES response shape (accepted vs full info).
        Ok(restored) => {
            if wait_for_completion {
                Json(json!({
                    "snapshot": {
                        "snapshot": snapshot,
                        "indices": restored,
                        "shards": {
                            "total": restored.len(),
                            "failed": 0,
                            "successful": restored.len(),
                        }
                    }
                }))
                .into_response()
            } else {
                Json(json!({ "accepted": true })).into_response()
            }
        }
        Err(e) => ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Cluster Settings
// GET  /_cluster/settings
// PUT  /_cluster/settings
// POST /_cluster/reroute
// GET  /_cluster/pending_tasks
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_cluster_settings(
    State(state): State<AppState>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> impl IntoResponse {
    let settings = state.engine.cluster_settings.read().await;
    let flat = flat_settings_param(&params);
    Json(json!({
        "persistent": render_settings(settings.get("persistent"), flat),
        "transient": render_settings(settings.get("transient"), flat),
        "defaults": {},
    }))
    .into_response()
}

pub async fn put_cluster_settings(
    State(state): State<AppState>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    let mut settings = state.engine.cluster_settings.write().await;
    // ES merges an update into the stored settings, keyed by the flat dotted
    // name whichever form the request used, and `null` removes a setting.
    // The response lists only the settings this request set.
    let mut updated = json!({ "persistent": {}, "transient": {} });
    for scope in ["persistent", "transient"] {
        let Some(update) = body.get(scope) else {
            continue;
        };
        let mut flat = serde_json::Map::new();
        flatten_settings("", update, &mut flat);
        if !settings[scope].is_object() {
            settings[scope] = json!({});
        }
        if let Some(stored) = settings[scope].as_object_mut() {
            for (key, value) in flat {
                if value.is_null() {
                    stored.remove(&key);
                } else {
                    updated[scope][key.as_str()] = value.clone();
                    stored.insert(key, value);
                }
            }
        }
    }
    let flat = flat_settings_param(&params);
    Json(json!({
        "acknowledged": true,
        "persistent": render_settings(updated.get("persistent"), flat),
        "transient": render_settings(updated.get("transient"), flat),
    }))
    .into_response()
}

/// `?flat_settings` / `?flat_settings=true`; ES defaults to the nested form.
fn flat_settings_param(params: &std::collections::HashMap<String, String>) -> bool {
    matches!(
        params.get("flat_settings").map(String::as_str),
        Some("" | "true")
    )
}

/// Settings are stored under flat dotted keys; render them nested unless the
/// caller asked for `flat_settings`.
fn render_settings(stored: Option<&Value>, flat: bool) -> Value {
    let stored = stored.cloned().unwrap_or(json!({}));
    if flat {
        stored
    } else {
        expand_dotted_keys(stored)
    }
}

/// Flattens `{"a": {"b": 1}}` into `{"a.b": 1}`.
fn flatten_settings(prefix: &str, value: &Value, out: &mut serde_json::Map<String, Value>) {
    match value {
        Value::Object(map) => {
            for (key, child) in map {
                let key = if prefix.is_empty() {
                    key.clone()
                } else {
                    format!("{prefix}.{key}")
                };
                flatten_settings(&key, child, out);
            }
        }
        _ => {
            out.insert(prefix.to_string(), value.clone());
        }
    }
}

pub async fn cluster_reroute(
    State(state): State<AppState>,
    axum::extract::Query(params): axum::extract::Query<std::collections::HashMap<String, String>>,
) -> impl IntoResponse {
    // Single-node cluster: every shard is permanently assigned to the local
    // node, so a reroute is always a no-op. Report this honestly while still
    // returning a routing summary derived entirely from live state — real
    // index + shard totals, and the real `dry_run`/`explain` flags echoed.
    let indices = state.engine.list_indices().await;
    let index_count = indices.len();
    // One primary shard per index on a single node => every shard is active
    // and locally assigned; nothing relocating / initializing / unassigned.
    let active_shards = index_count as u64;
    let node_id = state.engine.node_id.as_str();
    let dry_run = params.get("dry_run").map(|v| v == "true").unwrap_or(false);
    let explain = params.get("explain").map(|v| v == "true").unwrap_or(false);
    let mut resp = json!({
        "acknowledged": true,
        "dry_run": dry_run,
        "state": {
            "cluster_name": "xerj",
            "cluster_uuid": "xerj-cluster-1",
            "nodes": {
                node_id: {
                    "name": node_id,
                    "transport_address": "127.0.0.1:9300"
                }
            },
            "routing_summary": {
                "node_id": node_id,
                "index_count": index_count,
                "active_shards": active_shards,
                "relocating_shards": 0,
                "initializing_shards": 0,
                "unassigned_shards": 0,
                "explanation": "single-node cluster; all shards are assigned locally, nothing to move or rebalance"
            }
        }
    });
    if explain {
        // No reroute commands on a single node => no per-command decisions.
        if let Some(o) = resp.as_object_mut() {
            o.insert("explanations".to_string(), json!([]));
        }
    }
    Json(resp).into_response()
}

pub async fn cluster_pending_tasks(State(_state): State<AppState>) -> impl IntoResponse {
    // Single-node: there is no master task queue, so the pending list is
    // legitimately always empty. Derived from node state for shape-correctness
    // rather than returned as a bare constant.
    let tasks: Vec<Value> = Vec::new();
    Json(json!({ "tasks": tasks })).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_cluster/allocation/explain
//
// xerj is single-node, single-shard: every existing shard is STARTED and
// already assigned to the local node, and a missing index has nothing
// allocated. The explanation is derived from live index state (does the
// requested/selected index exist, is its shard assigned) rather than canned
// text — which is the real, correct allocation answer for this topology.
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cluster_allocation_explain(
    State(state): State<AppState>,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    let indices = state.engine.list_indices().await;
    let req = body.map(|Json(b)| b).unwrap_or_else(|| json!({}));

    // Choose the shard to explain: from the request body if given, else the
    // first non-system (user) index, else the first index of any kind.
    let explain_index = req
        .get("index")
        .and_then(Value::as_str)
        .map(str::to_string)
        .or_else(|| {
            indices
                .iter()
                .find(|i| !i.name.starts_with('.'))
                .map(|i| i.name.clone())
        })
        .or_else(|| indices.first().map(|i| i.name.clone()))
        .unwrap_or_else(|| ".xerj-default".to_string());
    let explain_shard = req.get("shard").and_then(Value::as_u64).unwrap_or(0);
    let primary = req.get("primary").and_then(Value::as_bool).unwrap_or(true);

    let node_id = state.engine.node_id.as_str();
    let exists = indices.iter().any(|i| i.name == explain_index);

    // Single-node: an existing shard is STARTED and already assigned locally;
    // there is no other node to allocate or rebalance to.
    let (can_allocate, explanation) = if exists {
        (
            "already_allocated",
            format!(
                "the shard is already assigned to node [{node_id}] and is in the STARTED state; \
                 xerj is single-node, so there is no other node to allocate or rebalance to"
            ),
        )
    } else {
        (
            "yes",
            format!(
                "index [{explain_index}] does not exist on this node; nothing is currently allocated for it"
            ),
        )
    };

    Json(json!({
        "index": explain_index,
        "shard": explain_shard,
        "primary": primary,
        "current_state": if exists { "started" } else { "unassigned" },
        "current_node": {
            "id": node_id,
            "name": node_id,
            "transport_address": "127.0.0.1:9300",
            "attributes": {},
            "weight_ranking": 1
        },
        "can_allocate": can_allocate,
        "allocate_explanation": explanation,
        "can_remain_on_current_node": "yes",
        "can_rebalance_cluster": "no",
        "can_rebalance_cluster_decisions": [{
            "decider": "cluster_rebalance",
            "decision": "NO",
            "explanation": "single-node cluster; rebalancing is not applicable"
        }],
        "can_rebalance_to_other_node": "no",
        "rebalance_explanation": "xerj is single-node; all shards are permanently assigned locally"
    }))
    .into_response()
}

