// _cat APIs
// GET /_cat/recovery
// GET /_cat/segments/{index}
// GET /_cat/thread_pool
// GET /_cat/fielddata
// GET /_cat/pending_tasks
// GET /_cat/plugins
// GET /_cat/nodeattrs
// GET /_cat/master
// ─────────────────────────────────────────────────────────────────────────────

pub async fn cat_recovery(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // ES _cat/recovery default column order:
    // index shard time type stage source_host source_node target_host
    // target_node repository snapshot files files_recovered files_percent
    // files_total bytes bytes_recovered bytes_percent bytes_total
    // translog_ops translog_ops_recovered translog_ops_percent
    //
    // Single-node: every shard is reported as an already-completed
    // existing_store recovery (stage=done, 100.0%). Files = segment count,
    // bytes = real on-disk data_dir size, translog ops = doc count.
    let indices = state.engine.list_indices().await;
    let mut rows: Vec<(String, u64, u64, u64)> = Vec::new();
    for info in &indices {
        let bytes = state
            .engine
            .get_index(&info.name)
            .map(|idx| dir_size_bytes(idx.data_dir()))
            .unwrap_or(0);
        rows.push((
            info.name.clone(),
            info.segment_count as u64,
            bytes,
            info.doc_count,
        ));
    }

    if params.format.as_deref() == Some("json") {
        let arr: Vec<Value> = rows
            .iter()
            .map(|(name, files, bytes, docs)| {
                json!({
                    "index": name,
                    "shard": "0",
                    "time": "0ms",
                    "type": "existing_store",
                    "stage": "done",
                    "source_host": "n/a",
                    "source_node": "n/a",
                    "target_host": "127.0.0.1",
                    "target_node": "xerj-node-1",
                    "repository": "n/a",
                    "snapshot": "n/a",
                    "files": files.to_string(),
                    "files_recovered": files.to_string(),
                    "files_percent": "100.0%",
                    "files_total": files.to_string(),
                    "bytes": bytes.to_string(),
                    "bytes_recovered": bytes.to_string(),
                    "bytes_percent": "100.0%",
                    "bytes_total": bytes.to_string(),
                    "translog_ops": docs.to_string(),
                    "translog_ops_recovered": docs.to_string(),
                    "translog_ops_percent": "100.0%",
                })
            })
            .collect();
        return Json(arr).into_response();
    }

    let lines: Vec<String> = rows
        .iter()
        .map(|(name, files, bytes, docs)| {
            format!(
                "{name} 0 0ms existing_store done n/a n/a 127.0.0.1 xerj-node-1 n/a n/a {files} {files} 100.0% {files} {bytes} {bytes} 100.0% {bytes} {docs} {docs} 100.0%",
            )
        })
        .collect();
    let body = if lines.is_empty() {
        String::new()
    } else {
        lines.join("\n") + "\n"
    };
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

pub async fn cat_segments(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    cat_segments_inner(state, &index, params).await
}

/// `GET /_cat/segments` — the whole-cluster form ES also serves.
pub async fn cat_segments_all(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    cat_segments_inner(state, "*", params).await
}

async fn cat_segments_inner(
    state: AppState,
    index: &str,
    params: CatFormatParams,
) -> axum::response::Response {
    // index  shard  prirep  ip  segment  generation  docs.count  docs.deleted
    //        size  size.memory  committed  searchable  version  compound
    //
    // #1202: one row per LIVE segment from the durable snapshot. The
    // predecessor fabricated a single `_0` row per index ("one logical
    // segment") — an index the node log showed merging 13 segments listed
    // "1 segment, 0 deleted" (the #1186 investigation), pointing the
    // operator away from the cause. Real per-segment values come from
    // `Index::segment_rows`: id, docs (physical, tombstones excluded by
    // construction),
    // deleted (the segment's own ZTB2 tombstone section) and the
    // segment's on-disk bytes. `generation` stays 0: our segment ids are
    // UUIDs, not ES's monotonically numbered `_N` names, so there is no
    // generation ordering to report, and inventing one would be the same
    // fabrication this fix removes. `version` is the xerj build — there is
    // no Lucene here and no Lucene version to fake.
    let cat_params = match params.cat_params() {
        Ok(p) => p,
        Err(e) => return e.into_response(),
    };
    // Resolve the selector through the shared resolver (#451): an alias expands
    // to every member (`get_index` collapsed it to `aliased.first()`, so an
    // alias listed a single row under the alias name), and `_all` / `*` / glob /
    // comma forms resolve uniformly. A cat endpoint lists what exists rather
    // than 404ing, so an unknown selector is an empty listing.
    let members = resolve_selector_with_filters(&state, index)
        .await
        .map(|(m, _filters)| m)
        .unwrap_or_default();

    let mut table = crate::cat::CatTable {
        columns: vec![
            "index",
            "shard",
            "prirep",
            "ip",
            "segment",
            "generation",
            "docs.count",
            "docs.deleted",
            "size",
            "size.memory",
            "committed",
            "searchable",
            "version",
            "compound",
        ],
        rows: Vec::new(),
    };
    let node_ip = "127.0.0.1";
    for (idx_name, idx) in &members {
        for seg in idx.segment_rows() {
            table.rows.push(vec![
                crate::cat::CatCell::plain(idx_name.clone()),
                crate::cat::CatCell::plain("0"),
                crate::cat::CatCell::plain("p"),
                crate::cat::CatCell::plain(node_ip),
                crate::cat::CatCell::plain(seg.id),
                crate::cat::CatCell::plain("0"),
                crate::cat::CatCell::plain(seg.doc_count.to_string()),
                crate::cat::CatCell::plain(seg.deleted_doc_count.to_string()),
                crate::cat::CatCell::size(seg.size_bytes, human_bytes(seg.size_bytes)),
                crate::cat::CatCell::plain("0"),
                crate::cat::CatCell::plain("true"),
                crate::cat::CatCell::plain("true"),
                crate::cat::CatCell::plain(env!("CARGO_PKG_VERSION")),
                crate::cat::CatCell::plain("true"),
            ]);
        }
    }
    table.render(&cat_params)
}

pub async fn cat_thread_pool(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // ES default columns: node_name name active queue rejected
    //
    // xerj does NOT use ES-style fixed, bounded thread pools — it schedules all
    // work on a shared tokio work-stealing runtime. There is therefore no
    // per-pool queue or rejection counter to read: active/queue/rejected are a
    // truthful 0 (work is stolen across workers, never queued into a named pool
    // or rejected). We still emit the standard ES pool names against the REAL
    // node name so Kibana / cerebro render the panel correctly.
    let node = state.engine.node_id.as_str();
    let pools = [
        "search",
        "write",
        "bulk",
        "get",
        "analyze",
        "management",
        "flush",
        "refresh",
        "warmer",
        "generic",
    ];

    if params.format.as_deref() == Some("json") {
        let arr: Vec<Value> = pools
            .iter()
            .map(|p| {
                json!({
                    "node_name": node,
                    "name": p,
                    "active": "0",
                    "queue": "0",
                    "rejected": "0",
                })
            })
            .collect();
        return Json(arr).into_response();
    }

    let body = pools
        .iter()
        .map(|p| format!("{node} {p} 0 0 0"))
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

pub async fn cat_fielddata(
    State(state): State<AppState>,
    Query(params): Query<CatFormatParams>,
) -> impl IntoResponse {
    // id  host         ip           node          field  size
    let node = state.engine.node_id.as_str();
    let indices = state.engine.list_indices().await;

    if params.format.as_deref() == Some("json") {
        let arr: Vec<Value> = indices
            .iter()
            .map(|info| {
                json!({
                    "id": node,
                    "host": "127.0.0.1",
                    "ip": "127.0.0.1",
                    "node": node,
                    "field": info.name,
                    "size": "0b",
                })
            })
            .collect();
        return Json(arr).into_response();
    }

    let mut lines: Vec<String> = Vec::new();
    for info in &indices {
        // Honest 0b fielddata usage per index: xerj has no fielddata cache.
        lines.push(format!(
            "{node} 127.0.0.1 127.0.0.1 {node} {} 0b",
            info.name,
        ));
    }
    let body = if lines.is_empty() {
        String::new()
    } else {
        lines.join("\n") + "\n"
    };
    (
        StatusCode::OK,
        [(
            axum::http::header::CONTENT_TYPE,
            "text/plain; charset=utf-8",
        )],
        body,
    )
        .into_response()
}

