pub async fn nodes_info(
    State(state): State<AppState>,
    headers: axum::http::HeaderMap,
) -> impl IntoResponse {
    // OpenSearch Dashboards' own initial-handshake compatibility check
    // hits THIS endpoint (GET /_nodes?filter_path=nodes.*.version,...), not
    // GET / — found empirically: a real OSD 2.11.1 container pointed at
    // xerj logged "This version of OpenSearch Dashboards (v2.11.1) is
    // incompatible with the following OpenSearch nodes in your cluster:
    // v8.13.0 ..." even though OSD's own request carried a recognizable
    // `opensearch-js/...` User-Agent — this handler just wasn't reading it.
    // Same resolution `es_info` (GET /) uses.
    let compat_version = resolve_compat_version(&state, &headers);
    let reported_version = compat_version.number.clone();
    let (_idx_count, total_docs, total_deleted, store_bytes) = real_index_totals(&state).await;
    let rss_bytes = read_rss_bytes().unwrap_or(0);
    // Real host memory total from /proc/meminfo (falls back to an RSS-derived
    // estimate if unreadable).
    let mem_total = read_meminfo().map(|(t, _)| t).unwrap_or(rss_bytes * 4);
    let num_cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);
    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;

    let node_id = state.engine.node_id.as_str();
    // Honest membership (#1169): `total` is the configured cluster size;
    // `successful` stays 1 because only THIS process's info is known —
    // peers are listed with name/transport only, never invented versions
    // or metrics. The transport fields report this node's real configured
    // cluster address instead of a phantom 9300.
    let members = configured_members(&state.config);
    let node_total = members.len().max(1);
    let own_addr = members
        .first()
        .map(|(_, a)| a.to_string())
        .unwrap_or_else(|| "127.0.0.1:9300".to_string());
    let own_ip = members
        .first()
        .map(|(_, a)| a.ip().to_string())
        .unwrap_or_else(|| "127.0.0.1".to_string());

    let mut nodes_map = serde_json::Map::new();
    nodes_map.insert(
        node_id.to_string(),
        json!({
                "name": node_id,
                "transport_address": own_addr.clone(),
                "host": own_ip.clone(),
                "ip": own_ip,
                "version": reported_version,
                "build_flavor": "default",
                "build_type": "tar",
                "build_hash": "xerj",
                "total_indexing_buffer": rss_bytes / 10,
                "roles": ["master", "data", "ingest", "remote_cluster_client"],
                "attributes": {
                    "ml.machine_memory": mem_total.to_string(),
                    "ml.max_open_jobs": "20",
                },
                "settings": {
                    "cluster": { "name": "xerj" },
                    "node": { "name": node_id }
                },
                "os": {
                    "refresh_interval_in_millis": 1000,
                    "name": "Linux",
                    "arch": std::env::consts::ARCH,
                    "version": "7.0.0",
                    "available_processors": num_cpus,
                    "allocated_processors": num_cpus,
                },
                "process": {
                    "refresh_interval_in_millis": 1000,
                    "id": std::process::id(),
                    "mlockall": false,
                },
                "jvm": {
                    "pid": std::process::id(),
                    "version": format!("Rust {}", env!("CARGO_PKG_VERSION")),
                    "vm_name": "xerj-rs",
                    "vm_version": env!("CARGO_PKG_VERSION"),
                    "vm_vendor": "Anthropic",
                    "bundled_jdk": false,
                    "start_time_in_millis": now_ms,
                    "mem": {
                        "heap_init_in_bytes": rss_bytes,
                        "heap_max_in_bytes": mem_total,
                        "non_heap_init_in_bytes": 0,
                        "non_heap_max_in_bytes": 0,
                    },
                    "gc_collectors": ["G1 Young Generation", "G1 Old Generation"],
                    "memory_pools": ["Code Cache", "Metaspace", "Compressed Class Space"],
                    "using_bundled_jdk": false,
                    "using_compressed_ordinary_object_pointers": "unknown",
                    "input_arguments": [],
                },
                "thread_pool": {
                    "analyze":    { "type": "fixed", "size": 1, "queue_size": 16 },
                    "bulk":       { "type": "fixed", "size": num_cpus, "queue_size": 200 },
                    "fetch_shard_started": { "type": "scaling", "min": 1, "max": num_cpus * 2, "queue_size": -1 },
                    "flush":      { "type": "scaling", "min": 1, "max": num_cpus / 2 + 1, "queue_size": -1 },
                    "generic":    { "type": "scaling", "min": 4, "max": 128, "queue_size": -1 },
                    "get":        { "type": "fixed", "size": num_cpus, "queue_size": 1000 },
                    "management": { "type": "scaling", "min": 1, "max": 5, "queue_size": -1 },
                    "refresh":    { "type": "scaling", "min": 1, "max": num_cpus / 2 + 1, "queue_size": -1 },
                    "search":     { "type": "fixed_auto_queue_size", "size": num_cpus * 3 / 2 + 1, "queue_size": 1000 },
                    "write":      { "type": "fixed", "size": num_cpus, "queue_size": 200 },
                },
                "transport": {
                    "bound_address": [own_addr.clone()],
                    "publish_address": own_addr,
                    "profiles": {},
                },
                "http": {
                    "bound_address": ["0.0.0.0:9200"],
                    "publish_address": "0.0.0.0:9200",
                    "max_content_length_in_bytes": 104857600,
                },
                "plugins": [],
                "modules": [],
                "indices": {
                    "docs": { "count": total_docs, "deleted": total_deleted },
                    "store": { "size_in_bytes": store_bytes },
                },
        }),
    );
    // Configured peers: name and transport address are known from config;
    // everything else about a remote process would be invented, so it is
    // omitted (#1169). On a cluster-disabled node the peer list is empty
    // and this response is byte-equivalent to the old single-entry one.
    for (peer_id, addr) in members.iter().skip(1) {
        nodes_map.insert(
            peer_id.clone(),
            json!({
                "name": peer_id,
                "transport_address": addr.to_string(),
                "host": addr.ip().to_string(),
                "ip": addr.ip().to_string(),
            }),
        );
    }

    Json(json!({
        "_nodes": { "total": node_total, "successful": 1, "failed": 0 },
        "cluster_name": "xerj",
        "nodes": Value::Object(nodes_map),
    }))
    .into_response()
}

pub async fn node_stats_by_id(
    State(state): State<AppState>,
    Path(_node_id): Path<String>,
) -> impl IntoResponse {
    // Delegate to the same full nodes_stats handler — single node, so node_id is ignored.
    nodes_stats(State(state)).await
}

// ─────────────────────────────────────────────────────────────────────────────
// Index clone / shrink / split
// POST /{index}/_clone/{target}
// POST /{index}/_shrink/{target}
// POST /{index}/_split/{target}
// ─────────────────────────────────────────────────────────────────────────────

async fn clone_index_to(state: &AppState, source: &str, target: &str) -> Result<(), ApiError> {
    // Get source index.
    let src_idx = state
        .engine
        .get_index(source)
        .map_err(|e| ApiError::new(xerj_common::XerjError::from(e)))?;

    // Create target index with same schema.
    let schema = src_idx.schema().await;
    state
        .engine
        .create_index(target, schema)
        .map_err(|e| ApiError::new(xerj_common::XerjError::from(e)))?;

    let dest_idx = state
        .engine
        .get_index(target)
        .map_err(|e| ApiError::new(xerj_common::XerjError::from(e)))?;

    // Copy EVERY document, and fail loudly if any copy fails.
    //
    // Issue #204, the "a partial export instead of a full one" case, verbatim.
    // This used to be a single `size: 10000` search whose per-document writes
    // were swallowed with `let _ =`, and then answered `{"acknowledged": true,
    // "shards_acknowledged": true}` — so cloning an index with 10,001
    // documents silently produced a 10,000-document copy, and a clone in which
    // every single write failed was reported as a success. `_clone`, `_shrink`
    // and `_split` all land here, on user data.
    //
    // Same keyset (`search_after` on `_id`) paging the `_reindex` handler uses,
    // for the same reason: `from`-offset paging truncates at
    // `max_result_window`. The source is flushed first because the in-memory
    // memtable's sort path does not order by `_id` reliably, so un-flushed
    // writes would be skipped or duplicated across pages.
    //
    // That makes the flush a CORRECTNESS precondition of the paging below, not
    // a best-effort hint — so it is propagated rather than swallowed. A
    // `let _ =` here would have produced exactly the defect this function was
    // rewritten to remove: a silently partial (or duplicated) copy answering
    // `{"acknowledged": true, "shards_acknowledged": true}`.
    src_idx.flush().await.map_err(|e| {
        ApiError::new(xerj_common::XerjError::internal(format!(
            "clone of [{source}] into [{target}] was not attempted: flushing the source \
             failed ({e}); the copy needs a flushed source to page over it without \
             skipping or duplicating documents"
        )))
    })?;

    const CLONE_PAGE_SIZE: usize = 1_000;
    let mut search_after: Option<Value> = None;
    let mut copied = 0usize;

    loop {
        let mut search_body = json!({
            "query": { "match_all": {} },
            "size": CLONE_PAGE_SIZE,
            "sort": [{ "_id": "asc" }],
            // Cloning copies documents verbatim: always read the COMPLETE
            // `_source`, including engine-generated embedding companions,
            // rather than inheriting the search default which hides them from
            // ordinary API responses. Dropping this would make the clone a
            // silently lossy copy — the same defect class the paging below
            // exists to remove.
            "_source": true,
        });
        if let Some(sa) = &search_after {
            search_body["search_after"] = sa.clone();
        }
        let search_req = xerj_query::parse_request(&search_body)
            .map_err(|e| ApiError::new(xerj_common::XerjError::invalid_query(e.to_string())))?;

        let results = src_idx
            .search(&search_req)
            .await
            .map_err(|e| ApiError::new(xerj_common::XerjError::from(e)))?;

        let batch = results.hits.len();
        if batch == 0 {
            break;
        }
        search_after = results.hits.last().map(|h| json!([h.id.clone()]));

        for hit in results.hits {
            if hit.source.is_null() {
                continue;
            }
            let id = hit.id.clone();
            dest_idx
                .index_document(Some(hit.id), hit.source)
                .await
                .map_err(|e| {
                    ApiError::new(xerj_common::XerjError::internal(format!(
                        "clone of [{source}] into [{target}] failed after {copied} \
                         document(s): document [{id}] could not be written: {e}"
                    )))
                })?;
            copied += 1;
        }

        if batch < CLONE_PAGE_SIZE {
            break;
        }
    }
    Ok(())
}

pub async fn clone_index(
    State(state): State<AppState>,
    Path((source, target)): Path<(String, String)>,
    _body: Option<Json<Value>>,
) -> impl IntoResponse {
    match clone_index_to(&state, &source, &target).await {
        Ok(()) => Json(json!({
            "acknowledged": true,
            "shards_acknowledged": true,
            "index": target,
        }))
        .into_response(),
        Err(e) => e.into_response(),
    }
}

pub async fn shrink_index(
    State(state): State<AppState>,
    Path((source, target)): Path<(String, String)>,
    _body: Option<Json<Value>>,
) -> impl IntoResponse {
    // Single-shard — shrink is identical to clone.
    match clone_index_to(&state, &source, &target).await {
        Ok(()) => Json(json!({
            "acknowledged": true,
            "shards_acknowledged": true,
            "index": target,
        }))
        .into_response(),
        Err(e) => e.into_response(),
    }
}

pub async fn split_index(
    State(state): State<AppState>,
