// POST /{index}/_search/template
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct SearchTemplateBody {
    /// Pre-stored template ID (looked up from a store — currently returns 404).
    #[serde(default)]
    pub id: Option<String>,
    /// Inline Mustache template source string or JSON object.
    #[serde(default)]
    pub source: Option<Value>,
    /// Template parameters to substitute.
    #[serde(default)]
    pub params: Option<serde_json::Map<String, Value>>,
}

pub async fn search_template(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Json(body): Json<SearchTemplateBody>,
) -> impl IntoResponse {
    let started = Instant::now();
    let params = body.params.unwrap_or_default();

    // Resolve the template to a search request JSON.
    let search_body_val: Value = if let Some(source_val) = body.source {
        match source_val {
            Value::String(tmpl_str) => {
                let rendered = render_template(&tmpl_str, &params);
                match serde_json::from_str(&rendered) {
                    Ok(v) => v,
                    Err(e) => {
                        let err = xerj_common::XerjError::invalid_query(format!(
                            "template rendered to invalid JSON: {e}"
                        ));
                        return ApiError::new(err).into_response();
                    }
                }
            }
            Value::Object(obj) => {
                // JSON-encoded template object: recursively substitute in string values.
                let rendered_str = render_template(
                    &serde_json::to_string(&Value::Object(obj)).unwrap_or_default(),
                    &params,
                );
                // Issue #204: this used to fall back to the UNRENDERED object
                // with an `"error": "render failed"` key bolted on, and then
                // ran a search with it — a different query from the one the
                // template describes, under a 200. The string arm ten lines
                // above already refuses; both arms now agree.
                match serde_json::from_str(&rendered_str) {
                    Ok(v) => v,
                    Err(e) => {
                        let err = xerj_common::XerjError::invalid_query(format!(
                            "template rendered to invalid JSON: {e}"
                        ));
                        return ApiError::new(err).into_response();
                    }
                }
            }
            other => other,
        }
    } else if let Some(id) = body.id {
        // Stored templates — look up from engine template store.
        match state.engine.search_templates.get(&id) {
            Some(tmpl) => {
                let tmpl_str = render_template(&tmpl.to_string(), &params);
                match serde_json::from_str(&tmpl_str) {
                    Ok(v) => v,
                    Err(e) => {
                        let err = xerj_common::XerjError::invalid_query(format!(
                            "stored template '{id}' rendered to invalid JSON: {e}"
                        ));
                        return ApiError::new(err).into_response();
                    }
                }
            }
            None => {
                let err = xerj_common::XerjError::index_not_found(format!(
                    "search template with id '{id}' not found"
                ));
                return ApiError::new(err).into_response();
            }
        }
    } else {
        return ApiError::new(xerj_common::XerjError::invalid_query(
            "search template requires either `source` or `id`".to_string(),
        ))
        .into_response();
    };

    // A rendered template is user input like any other search body — apply
    // the same request-time script guard `_search` applies in
    // `build_search_request`, over the same `GuardedField` set, since this
    // path also skips it.
    if let Some(msg) = find_body_script_limit_violation(&search_body_val) {
        return ApiError::new(xerj_common::XerjError::invalid_query(msg)).into_response();
    }
    if let Some(msg) = find_invalid_agg_order_path(
        search_body_val
            .get("aggs")
            .or_else(|| search_body_val.get("aggregations")),
    )
    .or_else(|| {
        find_invalid_composite_agg(
            search_body_val
                .get("aggs")
                .or_else(|| search_body_val.get("aggregations")),
        )
        .or_else(|| {
            find_invalid_agg_params(
                search_body_val
                    .get("aggs")
                    .or_else(|| search_body_val.get("aggregations")),
            )
            .or_else(|| {
                find_invalid_pipeline_agg(
                    search_body_val
                        .get("aggs")
                        .or_else(|| search_body_val.get("aggregations")),
                )
            })
        })
    }) {
        return ApiError::new(xerj_common::XerjError::invalid_query(msg)).into_response();
    }

    // A template that renders a `rerank` block: this minimal path does not run
    // the stage, and `parse_request` would drop the key without a word. Same
    // for a `judge` block.
    if crate::judge_stage::carries_second_stage(&search_body_val) {
        return (
            StatusCode::BAD_REQUEST,
            Json(crate::judge_stage::unsupported_second_stage_on(
                "_search/template",
                &search_body_val,
            )),
        )
            .into_response();
    }

    // Parse and execute as a normal search.
    let search_req = match xerj_query::parse_request(&search_body_val)
        .map_err(|e| xerj_common::XerjError::invalid_query(e.to_string()))
    {
        Ok(r) => r,
        Err(e) => return ApiError::new(e).into_response(),
    };

    let handles = match resolve_indices_for_op(&state, &index).await {
        Ok(h) => h,
        Err(e) => return ApiError::new(e).into_response(),
    };

    // A wildcard/comma spec searches every matching index — same as
    // `_search` — but this is a deliberately minimal merge (score-descending
    // only), not `search()`'s full sort/collapse/knn/PIT cross-index
    // machinery: `_search/template` never respected `sort` in its response
    // shape even for a single index (no `sort` field on hits below, same as
    // before this fix), so there's nothing sort-aware to preserve here, and
    // replicating `search()`'s ~1000-line merge path for a legacy templated
    // endpoint would be a large, easy-to-get-subtly-wrong change for a
    // question this sweep didn't ask.
    let mut merged_hits: Vec<(String, xerj_query::executor::Hit)> = Vec::new();
    let mut total: u64 = 0;
    // #2305: this minimal merge still fans a semantic query across every
    // match of a wildcard. An expanded index without the field is skipped.
    let mut semantic_skips = ExpandedSemanticSkips::default();
    let search_node = state.engine.node_id.clone();
    for (name, idx) in &handles {
        semantic_skips.note_attempt();
        match idx.search(&search_req).await {
            Ok(result) => {
                if let Some(reason) = &result.script_failure {
                    return script_limit_response(reason);
                }
                total += result.total.value;
                merged_hits.extend(result.hits.into_iter().map(|h| (name.clone(), h)));
            }
            Err(e) => {
                let err = xerj_common::XerjError::from(e);
                match semantic_skips.take_skippable(&index, name, search_node.as_str(), err) {
                    Ok(()) => continue,
                    Err(err) => return ApiError::new(err).into_response(),
                }
            }
        }
    }
    if let Some(err) = semantic_skips.failure_if_every_index_skipped() {
        return ApiError::new(err).into_response();
    }
    merged_hits.sort_by(|(_, a), (_, b)| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    merged_hits.truncate(search_req.size);

    let took_ms = started.elapsed().as_millis() as u64;
    let max_score = merged_hits.first().map(|(_, h)| h.score as f64);
    let hits: Vec<Value> = merged_hits
        .into_iter()
        .map(|(hit_index, h)| {
            let source = if h.source.is_null() {
                None
            } else {
                Some(h.source)
            };
            json!({
                "_index": hit_index,
                "_id": h.id,
                "_score": h.score,
                "_version": 1,
                "_seq_no": 0,
                "_primary_term": 1,
                "_source": source,
            })
        })
        .collect();
    let mut resp = json!({
        "took": took_ms,
        "timed_out": false,
        "_shards": crate::responses::EsShards::search_success(),
        "hits": {
            "total": { "value": total, "relation": "eq" },
            "max_score": max_score,
            "hits": hits,
        },
    });
    if semantic_skips.skipped > 0 {
        let shard_total = handles.len().max(1) as u32;
        resp["_shards"] = json!({
            "total": shard_total,
            "successful": shard_total.saturating_sub(semantic_skips.skipped),
            "skipped": 0,
            "failed": semantic_skips.skipped,
            "failures": semantic_skips.failures,
        });
    }
    Json(resp).into_response()
}

