// ─────────────────────────────────────────────────────────────────────────────
// GET /_security/_authenticate — return current user info
// ─────────────────────────────────────────────────────────────────────────────

/// Describe the credential that made *this* request (issue #201).
///
/// This used to answer `{"username":"xerj","roles":["superuser"]}` no matter
/// who asked. That was already untrue when it was written and became flatly
/// misleading once minted keys carried real grants (issue #79): a key confined
/// to `logs-*` was told it was the superuser, an operator auditing the cluster
/// was told every key was, and a client had no way to discover its own
/// permissions — the one question this endpoint exists to answer. Enforcement
/// was never affected (`rbac`/`authz` are fail-closed and consult the same
/// [`crate::auth::Principal`] this handler now reads), so it was introspection
/// drift, not an authorization hole. Drift in the direction of "you are more
/// privileged than you are" is still exactly the wrong direction.
///
/// Shape follows ES's `Authentication#toXContentFragment`
/// (`x-pack/plugin/core/.../authc/Authentication.java:773-860`, APPROACH ONLY
/// — AGPL/Elastic, read for semantics): an API-key authentication reports the
/// `_es_api_key` realm, `authentication_type: "api_key"`, and an `api_key:
/// {id, name}` block, while a realm login reports `authentication_type:
/// "realm"`. `username` stays the single owner identity in both cases
/// ([`API_KEY_OWNER_USERNAME`]) — xerj has one owner, and a minted key belongs
/// to it; what differs between callers is the *roles*, which is precisely what
/// was being misreported.
///
/// # One deliberate divergence, in the safe direction
///
/// ES reports `roles: []` for an API-key call — its API-key user is built with
/// `Strings.EMPTY_ARRAY` (`ApiKeyService.java:1641`) and a client is expected
/// to read `GET /_security/api_key` for the descriptors. xerj reports the
/// descriptor names the key was actually minted with. That is a divergence, so
/// it is written down rather than left to be discovered: `[]` is not *wrong*,
/// but it answers "which named cluster roles do you hold" when the question a
/// caller has is "what am I allowed to do", and xerj has no named-role store
/// to point at instead. The divergence is additive and never over-states — a
/// caller that only checks for `"superuser"` behaves identically, and no key
/// is described as holding more than it holds.
///
/// That last sentence is only true because of [`reported_role_label`]: a
/// `role_descriptors` key is caller-chosen free text, so without a guard
/// `POST /_security/api_key {"role_descriptors":{"superuser":{"indices":
/// [{"names":["logs-*"],...}]}}}` would make this endpoint answer
/// `{"roles":["superuser"]}` for a key confined to `logs-*` — the exact drift
/// this handler exists to remove, re-entered through a name.
///
/// Deliberately *not* fixed here: `POST /_security/user/_has_privileges` still
/// answers `true` to everything (see its own handler). Reporting honest roles
/// beside a lying privilege oracle is an improvement, not a completion.
pub async fn security_authenticate(
    State(state): State<AppState>,
    principal: crate::auth::Principal,
) -> impl IntoResponse {
    use crate::auth::Principal;

    let (roles, key): (Vec<String>, Option<(String, String)>) = match &principal {
        // The configured admin key, or open mode (`--insecure` / no key set).
        // This one really is the superuser, and saying so is the truth.
        Principal::Superuser => (vec!["superuser".to_string()], None),
        // The `role_descriptors` keys the caller supplied at mint time, in the
        // order they first appear and deduplicated: one descriptor with three
        // `indices` entries becomes three internal `Role`s named `r[0]`,
        // `r[1]`, `r[2]` (`rbac::roles_from_role_descriptors`), and reporting
        // that encoding back would describe roles the caller never named.
        // Names that collide with a label xerj assigns itself are qualified
        // first — see `reported_role_label`.
        Principal::Scoped { key_id, roles } => (
            dedup_in_order(
                roles
                    .iter()
                    .map(|r| reported_role_label(r.descriptor_name())),
            ),
            Some((key_id.clone(), key_name(&state, key_id))),
        ),
        // A key minted without usable `role_descriptors`. Reporting `[]` would
        // be as wrong as reporting `["superuser"]`, in the other direction: it
        // holds no grant on the reserved `.xerj-memory-*` namespace but keeps
        // its historical reach over ordinary indices. `"unscoped"` is the name
        // of that capability, defined by `Principal::Unscoped`.
        Principal::Unscoped { key_id } => (
            vec!["unscoped".to_string()],
            Some((key_id.clone(), key_name(&state, key_id))),
        ),
        // Unreachable behind `auth_middleware`, which answers 401 first — but
        // if this handler is ever mounted without it, "no credential" must not
        // be described as a user.
        Principal::Denied => {
            return (
                StatusCode::UNAUTHORIZED,
                Json(json!({
                    "error": {
                        "root_cause": [{
                            "type": "security_exception",
                            "reason": "missing or invalid API key in Authorization header"
                        }],
                        "type": "security_exception",
                        "reason": "missing or invalid API key in Authorization header"
                    },
                    "status": 401
                })),
            )
                .into_response()
        }
    };

    let (realm_name, realm_type, auth_type) = match key {
        Some(_) => (API_KEY_REALM, API_KEY_REALM, "api_key"),
        None => (API_KEY_OWNER_REALM, API_KEY_OWNER_REALM, "realm"),
    };

    let mut body = json!({
        "username": API_KEY_OWNER_USERNAME,
        "roles": roles,
        "full_name": "Xerj Administrator",
        "email": null,
        "metadata": {},
        "enabled": true,
        "authentication_realm": { "name": realm_name, "type": realm_type },
        "lookup_realm": { "name": realm_name, "type": realm_type },
        "authentication_type": auth_type
    });
    if let Some((id, name)) = key {
        body["api_key"] = json!({ "id": id, "name": name });
    }
    Json(body).into_response()
}

/// Name of a minted key, for the `api_key` block above. A key that vanished
/// between authentication and this lookup (revoked mid-request) reports an
/// empty name rather than failing the call — the id is the identifying part.
fn key_name(state: &AppState, key_id: &str) -> String {
    state
        .engine
        .api_keys
        .get(key_id)
        .map(|r| r.name.clone())
        .unwrap_or_default()
}

/// Collect into a `Vec<String>`, keeping first-appearance order and dropping
/// repeats. Role lists here are single digits long, so the linear `contains`
/// is cheaper than a set and keeps the output deterministic — a response that
/// reordered its own roles between calls would be a nuisance to diff.
fn dedup_in_order<'a>(items: impl Iterator<Item = std::borrow::Cow<'a, str>>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for item in items {
        if !out.iter().any(|seen| seen.as_str() == item.as_ref()) {
            out.push(item.into_owned());
        }
    }
    out
}

/// Labels `security_authenticate` assigns on xerj's own authority, and which
/// therefore mean something in every response: `superuser` is the admin
/// credential (or open mode), `unscoped` is a key minted without usable
/// `role_descriptors`. Keep in step with the match arms above — these are
/// exactly the strings those arms emit.
const XERJ_ASSIGNED_ROLE_LABELS: [&str; 2] = ["superuser", "unscoped"];

/// Prefix applied to a caller-chosen descriptor name that collides with one of
/// [`XERJ_ASSIGNED_ROLE_LABELS`].
const QUALIFIED_DESCRIPTOR_PREFIX: &str = "api_key_role:";

/// What a scoped key's `role_descriptors` name is reported as in `roles`.
///
/// A descriptor name is free text the caller chose at mint time, and `roles`
/// is read by clients as an authorization summary. Reporting it verbatim lets
/// a caller name a descriptor `superuser`, be confined to `logs-*` by that
/// very descriptor, and then be told by `GET /_security/_authenticate` that it
/// holds `["superuser"]` — the "you are more privileged than you are" drift
/// issue #201 removes, re-entered through a name. So the two labels xerj
/// assigns on its own authority are not mintable from caller input: a
/// descriptor named `superuser` or `unscoped` is reported qualified, as
/// `api_key_role:superuser`, which is still the name the caller wrote (nothing
/// is hidden) but can no longer be mistaken for the label xerj hands out.
///
/// Elasticsearch never has this problem because it reports `roles: []` for an
/// API-key call at all (`ApiKeyService.java:1641`) while keeping `superuser`
/// in a platform-owned store a caller cannot write into
/// (`ReservedRolesStore.java:188`, both APPROACH-ONLY reads — AGPL/Elastic, no
/// code taken). xerj answers the more useful question instead, so it has to
/// own the namespace explicitly; this is that ownership.
///
/// The guarantee is precisely "no caller-chosen name yields a label from
/// [`XERJ_ASSIGNED_ROLE_LABELS`]". It is *not* that the qualified form is
/// itself reserved: a caller may name a descriptor `api_key_role:superuser`
/// and get it back verbatim. That collides with another caller-chosen name,
/// not with a label xerj assigns, so it cannot make a key look like the
/// superuser.
fn reported_role_label(descriptor_name: &str) -> std::borrow::Cow<'_, str> {
    if XERJ_ASSIGNED_ROLE_LABELS.contains(&descriptor_name) {
        std::borrow::Cow::Owned(format!("{QUALIFIED_DESCRIPTOR_PREFIX}{descriptor_name}"))
    } else {
        std::borrow::Cow::Borrowed(descriptor_name)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET/POST /_security/user/_has_privileges
// GET/POST /_security/user/{user}/_has_privileges
// ─────────────────────────────────────────────────────────────────────────────
// Route didn't exist at all — every call 404'd. Kibana's app shell calls this
// right after login (during the same bootstrap pass as `_authenticate`,
// `/_cluster/health`, `/_xpack`) to decide what UI to show the current user;
// its client doesn't handle a 404 here gracefully and the whole page request
// blows up with a generic 500 ("[Internal Server Error]: undefined" — Kibana
// swallows the real cause before it reaches the client), which is a much
// harder failure to diagnose than the 404 itself since nothing about
// privileges appears in the error shown to the user.
//
// It echoes back every cluster/index/application privilege named in the
// request body as granted, keyed exactly the way ES's response is shaped.
//
// ⚠️ That is a STUB, not an answer. The comment here used to justify it as
// "what's actually true: nothing is denied", which was accurate when xerj had
// one built-in superuser and stopped being accurate when minted keys gained
// real grants (issue #79): a key confined to `logs-*` is told it may write
// `payments`, and then the write is refused by `authz`. #201 fixed the same
// class of drift in `security_authenticate` above; this handler is left alone
// on purpose, because answering honestly means denying privileges to callers
// that Kibana's bootstrap currently expects to be granted, and that is a
// behaviour change with its own blast radius rather than a comment fix. Do
// not treat this endpoint as an authorization oracle — `Principal::
// allows_index` is the only one.
pub async fn security_has_privileges(
    State(_state): State<AppState>,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    let body = body.map(|Json(v)| v).unwrap_or(json!({}));

    let mut cluster = serde_json::Map::new();
    if let Some(names) = body.get("cluster").and_then(Value::as_array) {
        for name in names.iter().filter_map(Value::as_str) {
            cluster.insert(name.to_string(), Value::Bool(true));
        }
    }

    let mut index = serde_json::Map::new();
    if let Some(reqs) = body.get("index").and_then(Value::as_array) {
        for req in reqs {
            let names = req.get("names").and_then(Value::as_array);
            let privileges = req.get("privileges").and_then(Value::as_array);
            let (Some(names), Some(privileges)) = (names, privileges) else {
                continue;
            };
            let mut priv_map = serde_json::Map::new();
            for p in privileges.iter().filter_map(Value::as_str) {
                priv_map.insert(p.to_string(), Value::Bool(true));
            }
            for name in names.iter().filter_map(Value::as_str) {
                index.insert(name.to_string(), Value::Object(priv_map.clone()));
            }
        }
    }

    let mut application = serde_json::Map::new();
    if let Some(reqs) = body.get("application").and_then(Value::as_array) {
        for req in reqs {
            let app = req.get("application").and_then(Value::as_str);
            let privileges = req.get("privileges").and_then(Value::as_array);
            let (Some(app), Some(privileges)) = (app, privileges) else {
                continue;
            };
            let mut priv_map = serde_json::Map::new();
            for p in privileges.iter().filter_map(Value::as_str) {
                priv_map.insert(p.to_string(), Value::Bool(true));
            }
            let resources: Vec<String> = req
                .get("resources")
                .and_then(Value::as_array)
                .map(|arr| {
                    arr.iter()
                        .filter_map(Value::as_str)
                        .map(String::from)
                        .collect()
                })
                .filter(|v: &Vec<String>| !v.is_empty())
                .unwrap_or_else(|| vec!["*".to_string()]);
            let mut resource_map = serde_json::Map::new();
            for r in resources {
                resource_map.insert(r, Value::Object(priv_map.clone()));
            }
            application.insert(app.to_string(), Value::Object(resource_map));
        }
    }

    Json(json!({
        "username": "xerj",
        "has_all_requested": true,
        "cluster": cluster,
        "index": index,
        "application": application,
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_security/profile/_activate — activate/create a user profile
// ─────────────────────────────────────────────────────────────────────────────
// The route didn't exist at all (no handler, not registered in router.rs), so
// every call hit axum's default "no route matched" response: a bodyless 404.
// Kibana calls this right after a successful login to get a profile UID for
// the authenticated user; its client expects an ES-shaped JSON body back
// (success or error) and throws on the empty 404, which Kibana's own server
// then surfaces to the browser as a 500 ("Failed to activate user profile: "
// — the empty reason is Kibana failing to parse a reason out of nothing).
// xerj was never actually returning 500 itself; the fix is simply to
// implement the endpoint.
//
// Same single-owner identity model as `security_authenticate` — xerj has no
// multi-user store, so every grant (password or access_token) activates the
// same built-in superuser profile. The uid is a fixed constant rather than
// content-derived from the submitted credentials, so repeated logins (and
// Kibana state keyed on this uid, e.g. space favorites) stay stable — also
// shared with `security_get_user_profile` below, since a uid this endpoint
// hands out needs to resolve when Kibana looks it back up.
const XERJ_SUPERUSER_PROFILE_UID: &str = "u_xerj-superuser-0000000000000000000000000000000000000_0";

fn xerj_superuser_profile_json(now_ms: i64) -> Value {
    json!({
        "uid": XERJ_SUPERUSER_PROFILE_UID,
        "enabled": true,
        "last_synchronized": now_ms,
        "user": {
            "username": "xerj",
            "roles": ["superuser"],
            "realm_name": "native",
            "full_name": "Xerj Administrator",
            "email": null
        },
        "labels": {},
        "data": {},
        "_doc": {
            "_primary_term": 1,
            "_seq_no": 0
        }
    })
}

pub async fn security_activate_user_profile(
    State(_state): State<AppState>,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    let _ = body;
    let now_ms = Utc::now().timestamp_millis().max(0);
    Json(xerj_superuser_profile_json(now_ms)).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_security/profile/{uid}  (comma-separated list of uids accepted)
// ─────────────────────────────────────────────────────────────────────────────
// Route didn't exist at all. After `_activate` hands Kibana a profile uid,
// its user-profile plugin re-fetches the full profile by that uid on every
// subsequent page load — found live, one step past the `_has_privileges`
// fix: login and `_activate` both succeeded, but the next page
// (`/app/home`) still 500'd, logged server-side as "Failed to retrieve user
// profile for the current user ... : ''" (empty reason — same "Kibana
// throws on an unhandled 404" pattern as everywhere else in this family of
// fixes). Only one uid is ever valid — the fixed constant `_activate`
// hands out — so anything else reports back as not found, matching ES's
// documented shape for a missing uid (`profiles: []` plus an `errors`
// block) instead of a blanket 404.
pub async fn security_get_user_profile(
    State(_state): State<AppState>,
    Path(uid): Path<String>,
) -> impl IntoResponse {
    let now_ms = Utc::now().timestamp_millis().max(0);
    let mut profiles = Vec::new();
    let mut error_details = serde_json::Map::new();
    for requested in uid.split(',').map(str::trim).filter(|s| !s.is_empty()) {
        if requested == XERJ_SUPERUSER_PROFILE_UID {
            profiles.push(xerj_superuser_profile_json(now_ms));
        } else {
            error_details.insert(
                requested.to_string(),
                json!({
                    "type": "resource_not_found_exception",
                    "reason": "profile document not found"
                }),
            );
        }
    }
    let mut response = json!({ "profiles": profiles });
    if !error_details.is_empty() {
        response["errors"] = json!({
            "count": error_details.len(),
            "details": error_details,
        });
    }
    Json(response).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_security/api_key — create API key (stub: returns admin key)
// ─────────────────────────────────────────────────────────────────────────────

pub async fn security_create_api_key(
    State(state): State<AppState>,
    principal: crate::auth::Principal,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    // Minting is how privilege is handed out, so it is also the obvious way to
    // escalate: without this gate a caller with no brain access could simply
    // mint itself a key that grants one (issue #79). Only the superuser may
    // create a *scoped* key; a scoped caller may not mint at all (an unscoped
    // key it minted would out-reach it on the general surface); an unscoped
    // caller may mint, but only more unscoped keys.
    if matches!(principal, crate::auth::Principal::Scoped { .. }) {
        return crate::authz::forbidden(
            &principal,
            "<api keys>",
            xerj_engine::rbac::Privilege::SecurityAdmin,
        );
    }
    let payload = body.map(|Json(v)| v);
    let name = payload
        .as_ref()
        .and_then(|b| b.get("name"))
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| "xerj-api-key".to_string());
    let expiration = payload
        .as_ref()
        .and_then(|b| b.get("expiration"))
        .cloned()
        .unwrap_or(Value::Null);
    // Well-formed, unique-per-call key material.
    let key_id = Uuid::new_v4().to_string();
    let raw_secret = format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple());
    let api_key = base64_encode(&raw_secret);
    // ES returns base64("id:api_key") as the `encoded` credential.
    let encoded = base64_encode(&format!("{key_id}:{api_key}"));

    // `role_descriptors` are now parsed into the key's index grants and ARE
    // enforced for the reserved `.xerj-memory-*` namespace (issue #79) — see
    // `authz`. Two honest caveats remain, both warned about below:
    //   * cluster privileges and FLS/DLS inside a descriptor are still
    //     ignored, and
    //   * a key minted with NO usable descriptor keeps its historical reach
    //     over ordinary indices (it just holds nothing in the reserved
    //     namespace), because broad RBAC over the general ES surface is still
    //     deferred.
    let requested_descriptors = payload
        .as_ref()
        .and_then(|b| b.get("role_descriptors"))
        .filter(|v| !v.is_null() && *v != &json!({}));
    let roles = match (&principal, requested_descriptors) {
        (crate::auth::Principal::Superuser, Some(descriptors)) => {
            let parsed = xerj_engine::rbac::roles_from_role_descriptors(descriptors);
            if parsed.is_empty() {
                tracing::warn!(
                    key = %name,
                    "POST /_security/api_key: role_descriptors granted nothing usable \
                     (only index names + index privileges are enforced); the key is \
                     unscoped and holds NO access to the reserved .xerj-memory-* namespace"
                );
            }
            parsed
        }
        (_, Some(_)) => {
            // A non-superuser cannot hand out grants it does not itself hold.
            tracing::warn!(
                key = %name,
                "POST /_security/api_key: role_descriptors ignored — only the admin key \
                 may mint a scoped key; the minted key is unscoped"
            );
            Vec::new()
        }
        (_, None) => Vec::new(),
    };

    // Persist the key so the auth middleware can re-authenticate an inbound
    // `Authorization: ApiKey <encoded>` header. `encoded` decodes to
    // `id:api_key`, so the credential the record must recognise is the
    // `api_key` value — `ApiKeyRecord::new` hashes it (issue #201) and the
    // plaintext leaves this function only in the response below. Persisted
    // across restarts via `persist_api_key` (item 6: `<data_dir>/api_keys.json`).
    let now_ms = Utc::now().timestamp_millis().max(0) as u64;
    let expiration_ms = parse_api_key_expiration_ms(expiration.as_str(), now_ms);
    if let Err(error) = state.engine.persist_api_key(
        key_id.clone(),
        xerj_engine::engine::ApiKeyRecord::new(
            name.clone(),
            &api_key,
            now_ms,
            expiration_ms,
            roles,
        ),
    ) {
        return ApiError::new(xerj_common::XerjError::from(error)).into_response();
    }
    state.engine.audit.append(
        "security.api_key.create",
        principal.label(),
        "_security/api_key",
        "ok",
        &format!("id={key_id} name={name}"),
    );
    // Minting privilege is exactly the kind of event that must not be lost to
    // a power cut, and it is rare enough to afford the barrier — unlike the
    // per-search append, which deliberately does not sync (see `audit`).
    state.engine.audit.sync_to_disk();

    Json(json!({
        "id": key_id,
        "name": name,
        "expiration": expiration,
        "api_key": api_key,
        "encoded": encoded
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET    /_security/api_key — list keys (never returns secrets)
// DELETE /_security/api_key — invalidate (revoke) keys
// ─────────────────────────────────────────────────────────────────────────────
// Issue #208: only create existed — GET and DELETE both 405'd. The enforcement
// half was already built (`auth::check_minted_key` rejects a record with
// `invalidated: true`), but nothing could ever set the flag, so a leaked key
// was permanent and rotation impossible.
//
// Wire contract derived from ES source (APPROACH ONLY — AGPL/Elastic, read
// for semantics, no code copied):
//   * request selectors `ids`/`name`/`realm_name`/`username`/`owner` and
//     their mutual-exclusion rules: InvalidateApiKeyRequest.java:163-195,
//     RestInvalidateApiKeyAction.java:87-96
//   * invalidate response `{invalidated_api_keys,
//     previously_invalidated_api_keys, error_count[, error_details]}`, 200:
//     InvalidateApiKeyResponse.java:92-108
//   * unknown ids match nothing and land in neither list (empty response,
//     not an error): ApiKeyService.java:1965-1973
//   * GET query params + "404 with body when `id` names a missing key":
//     RestGetApiKeyAction.java:47-54, 70-73
//   * per-key GET item shape (no secret, `type: rest`, optional
//     `expiration`/`invalidation`): ApiKey.java:289-310

/// The single-node owner identity, matching `GET /_security/_authenticate`
/// (`security_authenticate` above): xerj has no multi-user store, so every
/// minted key belongs to this one principal. A `username`/`realm_name`
/// selector therefore matches either every key or none, and `owner=true`
/// (ES: "only keys owned by the caller") is satisfied by every key.
const API_KEY_OWNER_USERNAME: &str = "xerj";
const API_KEY_OWNER_REALM: &str = "native";

/// Realm name/type ES reports for a request authenticated by an API key
/// (`AuthenticationField.API_KEY_REALM_NAME`/`_TYPE`, both `_es_api_key`).
/// Used by [`security_authenticate`] so a client can tell an API-key call
/// apart from a realm login instead of being told every caller is the
/// built-in `native`-realm superuser.
const API_KEY_REALM: &str = "_es_api_key";

/// 400 in ES's `action_request_validation_exception` shape — what ES's REST
/// layer answers when `InvalidateApiKeyRequest#validate` rejects a request.
/// `errors` are joined as `Validation Failed: 1: a;2: b;`, matching
/// `ActionRequestValidationException`'s message format.
fn api_key_validation_error(errors: &[String]) -> Response {
    let numbered: String = errors
        .iter()
        .enumerate()
        .map(|(i, e)| format!("{}: {};", i + 1, e))
        .collect();
    let reason = format!("Validation Failed: {numbered}");
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{
                    "type": "action_request_validation_exception",
                    "reason": reason
                }],
                "type": "action_request_validation_exception",
                "reason": reason
            },
            "status": 400
        })),
    )
        .into_response()
}

/// Rebuild an ES-shaped `role_descriptors` object from a key's parsed grants.
/// Honest-lossy: creation normalizes descriptors through
/// `rbac::roles_from_role_descriptors` (index names + index privileges only),
/// so what comes back is that normalized form, not the caller's original
/// descriptor JSON. An unscoped key reports `{}` — the same "no usable grant"
/// signal the parse produced.
///
/// Descriptors are keyed by the name the caller supplied, and a descriptor
/// that had several `indices` entries is reassembled into one object with
/// several entries. This used to key by `Role::name`, which is the internal
/// `"{descriptor}[{i}]"` fan-out: a key minted with one `reader` descriptor
/// over two index sets was listed back as two descriptors, `reader[0]` and
/// `reader[1]`, neither of which the caller ever wrote and neither of which
/// could be fed back into `POST /_security/api_key` to reproduce the key. It
/// is the same introspection drift issue #201 fixes in
/// `security_authenticate`, and the two must agree on what a role is called.
fn api_key_role_descriptors_json(roles: &[xerj_engine::rbac::Role]) -> Value {
    use xerj_engine::rbac::Privilege;
    let mut out = serde_json::Map::new();
    for role in roles {
        let mut privileges: Vec<&'static str> = role
            .privileges
            .iter()
            .map(|p| match p {
                Privilege::ReadIndex => "read",
                Privilege::WriteIndex => "write",
                Privilege::AdminIndex => "manage",
                Privilege::SnapshotCreate => "create_snapshot",
                Privilege::SnapshotRestore => "restore_snapshot",
                Privilege::SecurityAdmin => "manage_security",
                Privilege::AuditRead => "read_audit",
            })
            .collect();
        // HashSet order is nondeterministic; sort so the wire shape is stable.
        privileges.sort_unstable();
        privileges.dedup();
        let descriptor = out
            .entry(role.descriptor_name().to_string())
            .or_insert_with(|| json!({ "indices": [] }));
        if let Some(entries) = descriptor.get_mut("indices").and_then(Value::as_array_mut) {
            entries.push(json!({ "names": role.indices, "privileges": privileges }));
        }
    }
    Value::Object(out)
}

/// One `api_keys[]` item, per ES's `ApiKey#innerToXContent` (ApiKey.java:
/// 289-310): `expiration`/`invalidation` appear only when set, and the secret
/// is **never** part of this shape — only the create response carries it.
fn api_key_item_json(id: &str, rec: &xerj_engine::engine::ApiKeyRecord) -> Value {
    let mut item = json!({
        "id": id,
        "name": rec.name,
        "type": "rest",
        "creation": rec.creation_ms,
        "invalidated": rec.invalidated,
        "username": API_KEY_OWNER_USERNAME,
        "realm": API_KEY_OWNER_REALM,
        "realm_type": "native",
        "metadata": {},
        "role_descriptors": api_key_role_descriptors_json(&rec.roles),
    });
    if let Some(exp) = rec.expiration_ms {
        item["expiration"] = json!(exp);
    }
    if let Some(inv) = rec.invalidation_ms {
        item["invalidation"] = json!(inv);
    }
    item
}

/// Only the superuser and unscoped (historical operator) credentials may see
/// or revoke keys; a scoped key gets the same 403 the create gate gives it,
/// and the fail-closed default covers `Denied` too. Listing exposes no
/// secrets, and revocation only ever *reduces* privilege, so the trust level
/// that may mint keys (see `security_create_api_key`) is the right bar.
fn api_key_admin_gate(principal: &crate::auth::Principal) -> Option<Response> {
    if matches!(
        principal,
        crate::auth::Principal::Superuser | crate::auth::Principal::Unscoped { .. }
    ) {
        None
    } else {
        Some(crate::authz::forbidden(
            principal,
            "<api keys>",
            xerj_engine::rbac::Privilege::SecurityAdmin,
        ))
    }
}

#[derive(Deserialize)]
pub struct GetApiKeyParams {
    id: Option<String>,
    name: Option<String>,
    username: Option<String>,
    realm_name: Option<String>,
    /// Accepted for ES parity; a no-op filter here (see
    /// [`API_KEY_OWNER_USERNAME`] — every key is owned by the caller).
    #[serde(default)]
    #[allow(dead_code)]
    owner: bool,
    #[serde(default)]
    active_only: bool,
}

pub async fn security_get_api_keys(
    State(state): State<AppState>,
    principal: crate::auth::Principal,
    Query(params): Query<GetApiKeyParams>,
) -> impl IntoResponse {
    if let Some(denied) = api_key_admin_gate(&principal) {
        return denied;
    }
    let now_ms = Utc::now().timestamp_millis().max(0) as u64;
    let mut items: Vec<(u64, String, Value)> = Vec::new();
    // A username/realm selector that names anything but the single-node
    // identity matches nothing (there is no such user/realm here).
    let identity_mismatch = params
        .username
        .as_deref()
        .is_some_and(|u| u != API_KEY_OWNER_USERNAME)
        || params
            .realm_name
            .as_deref()
            .is_some_and(|r| r != API_KEY_OWNER_REALM);
    if !identity_mismatch {
        for entry in state.engine.api_keys.iter() {
            let (id, rec) = (entry.key(), entry.value());
            if params.id.as_deref().is_some_and(|want| want != id) {
                continue;
            }
            if params.name.as_deref().is_some_and(|want| want != rec.name) {
                continue;
            }
            // `active_only` drops invalidated AND expired keys — ES filters
            // both (ApiKeyService#findApiKeys: `api_key_invalidated: false`
            // plus an expiration-window clause).
            if params.active_only
                && (rec.invalidated || rec.expiration_ms.is_some_and(|exp| now_ms >= exp))
            {
                continue;
            }
            items.push((rec.creation_ms, id.clone(), api_key_item_json(id, rec)));
        }
    }
    // DashMap iteration order is arbitrary; sort by (creation, id) so
    // repeated listings are stable. ES guarantees no order here.
    items.sort_by(|a, b| (a.0, &a.1).cmp(&(b.0, &b.1)));
    let api_keys: Vec<Value> = items.into_iter().map(|(_, _, v)| v).collect();
    state.engine.audit.append(
        "security.api_key.get",
        principal.label(),
        "_security/api_key",
        "ok",
        &format!("returned={}", api_keys.len()),
    );
    // Looking up one specific id that doesn't exist is a resource lookup:
    // 404, with the (empty) body still attached — RestGetApiKeyAction.java:
    // 70-73 returns the rendered response at NOT_FOUND.
    let status = if params.id.is_some() && api_keys.is_empty() {
        StatusCode::NOT_FOUND
    } else {
        StatusCode::OK
    };
    (status, Json(json!({ "api_keys": api_keys }))).into_response()
}

pub async fn security_invalidate_api_key(
    State(state): State<AppState>,
    principal: crate::auth::Principal,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    if let Some(denied) = api_key_admin_gate(&principal) {
        return denied;
    }
    let payload = body.map(|Json(v)| v).unwrap_or(Value::Null);

    // ── Parse the selector fields (RestInvalidateApiKeyAction.java:87-96) ──
    // `ids` is the documented plural; a bare string `id` is also accepted
    // (ES kept it as a deprecated REST-compat alias) — lenient parsing is
    // this file's convention.
    let mut blank_id_positions: Vec<usize> = Vec::new();
    let ids: Option<Vec<String>> = match payload.get("ids") {
        Some(Value::Array(arr)) => Some(
            arr.iter()
                .enumerate()
                .map(|(i, v)| {
                    let s = v.as_str().unwrap_or("").trim();
                    if s.is_empty() {
                        blank_id_positions.push(i);
                    }
                    s.to_string()
                })
                .collect(),
        ),
        Some(Value::String(s)) => Some(vec![s.clone()]),
        _ => payload
            .get("id")
            .and_then(|v| v.as_str())
            .map(|s| vec![s.to_string()]),
    };
    let name = payload
        .get("name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let realm_name = payload
        .get("realm_name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let username = payload
        .get("username")
        .and_then(|v| v.as_str())
        .filter(|s| !s.trim().is_empty())
        .map(str::to_string);
    let owner = payload
        .get("owner")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    // ── Validate, mirroring InvalidateApiKeyRequest.java:163-195/228-252 ──
    let mut errors: Vec<String> = Vec::new();
    if let Some(ids) = &ids {
        if ids.is_empty() {
            errors.push("Field [ids] cannot be an empty array".to_string());
        } else if !blank_id_positions.is_empty() {
            let (noun, pos) = if blank_id_positions.len() == 1 {
                ("id", "position")
            } else {
                ("ids", "positions")
            };
            errors.push(format!(
                "Field [ids] must not contain blank id, but got blank {noun} at index {pos}: {blank_id_positions:?}"
            ));
        }
    }
    if ids.is_none() && name.is_none() && realm_name.is_none() && username.is_none() && !owner {
        errors.push(
            "One of [api key id(s), api key name, username, realm name] must be specified if \
             [owner] flag is false"
                .to_string(),
        );
    }
    if (ids.is_some() || name.is_some()) && (realm_name.is_some() || username.is_some()) {
        errors.push(
            "username or realm name must not be specified when the api key id(s) or api key \
             name are specified"
                .to_string(),
        );
    }
    if owner && (realm_name.is_some() || username.is_some()) {
        errors.push(
            "neither username nor realm-name may be specified when invalidating owned API keys"
                .to_string(),
        );
    }
    if ids.is_some() && name.is_some() {
        errors.push("only one of [api key id(s), api key name] can be specified".to_string());
    }
    if !errors.is_empty() {
        return api_key_validation_error(&errors);
    }

    // ── Resolve the selector to concrete key ids ──
    let target_ids: Vec<String> = if let Some(ids) = ids {
        // Dedupe, preserving order — ES's find phase returns each key once
        // however many times its id was repeated.
        let mut seen = std::collections::HashSet::new();
        ids.into_iter()
            .filter(|id| seen.insert(id.clone()))
            .collect()
    } else if let Some(name) = &name {
        state
            .engine
            .api_keys
            .iter()
            .filter(|e| &e.value().name == name)
            .map(|e| e.key().clone())
            .collect()
    } else if username
        .as_deref()
        .is_some_and(|u| u != API_KEY_OWNER_USERNAME)
        || realm_name
            .as_deref()
            .is_some_and(|r| r != API_KEY_OWNER_REALM)
    {
        // A user/realm this node has never issued for: nothing to invalidate.
        Vec::new()
    } else {
        // realm_name/username naming the single-node identity, or owner=true:
        // both select every minted key (see API_KEY_OWNER_USERNAME).
        state
            .engine
            .api_keys
            .iter()
            .map(|e| e.key().clone())
            .collect()
    };

    let now_ms = Utc::now().timestamp_millis().max(0) as u64;
    let (invalidated, previously) = match state.engine.invalidate_api_keys(&target_ids, now_ms) {
        Ok(result) => result,
        Err(error) => {
            return ApiError::new(xerj_common::XerjError::from(error)).into_response();
        }
    };
    state.engine.audit.append(
        "security.api_key.invalidate",
        principal.label(),
        "_security/api_key",
        "ok",
        &format!(
            "invalidated=[{}] previously_invalidated=[{}]",
            invalidated.join(","),
            previously.join(",")
        ),
    );
    // Revocation, like minting, is a privilege change worth an fsync.
    state.engine.audit.sync_to_disk();
    // ES answers 200 whatever matched; ids that matched nothing appear in
    // neither list. `error_details` exists only when per-key errors occurred,
    // which this single-node store cannot produce — so `error_count` is 0 and
    // the field is omitted (InvalidateApiKeyResponse.java:96-106).
    Json(json!({
        "invalidated_api_keys": invalidated,
        "previously_invalidated_api_keys": previously,
        "error_count": 0
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET    /_security/privilege
// GET    /_security/privilege/{application}
// GET    /_security/privilege/{application}/{name}
// PUT    /_security/privilege
// DELETE /_security/privilege/{application}/{name}
// ─────────────────────────────────────────────────────────────────────────────
// xerj has no application-privilege store built into RBAC:
// `xerj_engine::rbac::Privilege` is a closed enum of index-scoped operations
// (read/write/admin index, snapshot, security admin, audit), a different
// concept from ES's user-defined per-application privilege objects
// (`application`/`name`/`actions`/`metadata`) — so this gets its own store,
// `state.engine.application_privileges`, keyed by `"{application}\0{name}"`.
//
// Kibana polls GET at startup to check its own `kibana-.kibana` application
// privileges, and calls PUT to register them if the GET doesn't already
// match — originally NEITHER route existed, so every poll 404'd and Kibana
// logged "Error registering Kibana Privileges" every ~5s (non-fatal, but
// noisy). Not enforced (same honest-surface convention as `roles`/minted API
// keys' `role_descriptors`): privileges round-trip through this store, but
// nothing in the auth path actually gates on them yet.

pub async fn security_get_all_privileges(State(state): State<AppState>) -> impl IntoResponse {
    Json(privileges_grouped_by_application(&state, None)).into_response()
}

pub async fn security_get_application_privileges(
    State(state): State<AppState>,
    Path(application): Path<String>,
) -> impl IntoResponse {
    Json(privileges_grouped_by_application(
        &state,
        Some(&application),
    ))
    .into_response()
}

pub async fn security_get_privilege(
    State(state): State<AppState>,
    Path((application, name)): Path<(String, String)>,
) -> impl IntoResponse {
    // Unlike the list forms above, looking up one specific privilege by name
    // is a resource lookup: ES responds 404 when it doesn't exist, matching
    // the convention used for other named-resource lookups in this file
    // (e.g. `get_task_by_id`).
    match state
        .engine
        .application_privileges
        .get(&application_privilege_key(&application, &name))
    {
        Some(entry) => Json(json!({ application: { name: entry.value() } })).into_response(),
        None => (
            StatusCode::NOT_FOUND,
            Json(json!({
                "error": {
                    "type": "resource_not_found_exception",
                    "reason": format!(
                        "application privilege [{name}] not found for application [{application}]"
                    ),
                },
                "status": 404
            })),
        )
            .into_response(),
    }
}

pub async fn security_put_privileges(
    State(state): State<AppState>,
    Json(body): Json<Value>,
) -> impl IntoResponse {
    let Some(apps) = body.as_object() else {
        return ApiError::new(xerj_common::XerjError::invalid_query(
            "request body must be an object of {application: {privilege_name: {...}}}",
        ))
        .into_response();
    };
    let mut result = serde_json::Map::new();
    for (application, privileges) in apps {
        let Some(privileges) = privileges.as_object() else {
            continue;
        };
        let mut app_result = serde_json::Map::new();
        for (name, spec) in privileges {
            let key = application_privilege_key(application, name);
            let created = !state.engine.application_privileges.contains_key(&key);
            let stored = json!({
                "application": application,
                "name": name,
                "actions": spec.get("actions").cloned().unwrap_or(json!([])),
                "metadata": spec.get("metadata").cloned().unwrap_or(json!({})),
            });
            state.engine.application_privileges.insert(key, stored);
            app_result.insert(name.clone(), json!({ "created": created }));
        }
        result.insert(application.clone(), Value::Object(app_result));
    }
    Json(Value::Object(result)).into_response()
}

pub async fn security_delete_privilege(
    State(state): State<AppState>,
    Path((application, name)): Path<(String, String)>,
) -> impl IntoResponse {
    let key = application_privilege_key(&application, &name);
    let found = state.engine.application_privileges.remove(&key).is_some();
    // ES nests the result per application/name and 404s when nothing was
    // deleted: {"<application>": {"<name>": {"found": bool}}} — typed clients
    // (DeletePrivilegesResponse) index into resp[app][name].
    let mut by_name = serde_json::Map::new();
    by_name.insert(name, json!({ "found": found }));
    let mut by_app = serde_json::Map::new();
    by_app.insert(application, Value::Object(by_name));
    let status = if found {
        StatusCode::OK
    } else {
        StatusCode::NOT_FOUND
    };
    (status, Json(Value::Object(by_app))).into_response()
}

fn application_privilege_key(application: &str, name: &str) -> String {
    format!("{application}\0{name}")
}

/// Build the ES-shaped `{application: {name: {...}}}` response, optionally
/// filtered to one application (`None` = every application).
fn privileges_grouped_by_application(state: &AppState, application: Option<&str>) -> Value {
    let mut by_app: serde_json::Map<String, Value> = serde_json::Map::new();
    for entry in state.engine.application_privileges.iter() {
        let priv_obj = entry.value();
        let Some(app) = priv_obj.get("application").and_then(Value::as_str) else {
            continue;
        };
        if let Some(want) = application {
            if app != want {
                continue;
            }
        }
        let Some(name) = priv_obj.get("name").and_then(Value::as_str) else {
            continue;
        };
        by_app
            .entry(app.to_string())
            .or_insert_with(|| json!({}))
            .as_object_mut()
            .expect("inserted as object above")
            .insert(name.to_string(), priv_obj.clone());
    }
    Value::Object(by_app)
}

/// Parse an ES time-value expiration (e.g. `"7d"`, `"1h"`, `"30m"`, `"500ms"`)
/// into an ABSOLUTE expiration in epoch milliseconds relative to `now_ms`.
/// Returns `None` when the spec is absent or unparseable — meaning the key
/// never expires.
fn parse_api_key_expiration_ms(spec: Option<&str>, now_ms: u64) -> Option<u64> {
    let s = spec?.trim();
    if s.is_empty() {
        return None;
    }
    // Split the leading number from the trailing unit.
    let split = s.find(|c: char| c.is_ascii_alphabetic())?;
    let (num, unit) = s.split_at(split);
    let n: u64 = num.trim().parse().ok()?;
    let per_ms: u64 = match unit.trim() {
        "d" => 86_400_000,
        "h" => 3_600_000,
        "m" => 60_000,
        "s" => 1_000,
        "ms" => 1,
        _ => return None,
    };
    now_ms.checked_add(n.checked_mul(per_ms)?)
}

/// Minimal base64 decoder (standard alphabet, tolerates `=` padding). Mirrors
/// [`base64_encode`]; returns `None` on any invalid input. Used by the auth
/// middleware to decode an `Authorization: ApiKey <encoded>` credential.
pub fn base64_decode(input: &str) -> Option<Vec<u8>> {
    fn val(c: u8) -> Option<u32> {
        match c {
            b'A'..=b'Z' => Some((c - b'A') as u32),
            b'a'..=b'z' => Some((c - b'a' + 26) as u32),
            b'0'..=b'9' => Some((c - b'0' + 52) as u32),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }
    let bytes: Vec<u8> = input.bytes().filter(|&b| b != b'=').collect();
    let mut out = Vec::with_capacity(bytes.len() * 3 / 4);
    for chunk in bytes.chunks(4) {
        let mut acc = 0u32;
        let mut bits = 0u32;
        for &b in chunk {
            acc = (acc << 6) | val(b)?;
            bits += 6;
        }
        // Emit the fully-formed bytes (drop the leftover partial bits from
        // the dropped padding).
        while bits >= 8 {
            bits -= 8;
            out.push(((acc >> bits) & 0xFF) as u8);
        }
    }
    Some(out)
}

/// Minimal base64 encoder (standard alphabet, no padding variant for ES compat).
pub(crate) fn base64_encode(input: &str) -> String {
    let bytes = input.as_bytes();
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let b0 = bytes[i] as u32;
        let b1 = if i + 1 < bytes.len() {
            bytes[i + 1] as u32
        } else {
            0
        };
        let b2 = if i + 2 < bytes.len() {
            bytes[i + 2] as u32
        } else {
            0
        };
        output.push(alphabet[((b0 >> 2) & 0x3F) as usize] as char);
        output.push(alphabet[(((b0 & 0x3) << 4) | (b1 >> 4)) as usize] as char);
        if i + 1 < bytes.len() {
            output.push(alphabet[(((b1 & 0xF) << 2) | (b2 >> 6)) as usize] as char);
        } else {
            output.push('=');
        }
        if i + 2 < bytes.len() {
            output.push(alphabet[(b2 & 0x3F) as usize] as char);
        } else {
            output.push('=');
        }
        i += 3;
    }
    output
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_license — license info
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_license(State(state): State<AppState>) -> impl IntoResponse {
    // Reflect exactly what the in-process license currently holds (defaults
    // set in AppState::new, or whatever a prior PUT /_license merged in).
    let license = state.license.read().await.clone();
    Json(json!({ "license": license })).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT /_license — update license (stub: accept and acknowledge)
// ─────────────────────────────────────────────────────────────────────────────

pub async fn put_license(
    State(state): State<AppState>,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    // Accept a license posted as {"license": {...}}, {"licenses": [{...}]},
    // or a bare license object; merge it over the stored license so a
    // subsequent GET /_license reflects what was PUT.
    if let Some(Json(payload)) = body {
        let incoming = if let Some(l) = payload.get("license").cloned() {
            l
        } else if let Some(first) = payload
            .get("licenses")
            .and_then(|v| v.as_array())
            .and_then(|a| a.first())
            .cloned()
        {
            first
        } else {
            payload
        };
        if let Some(incoming_obj) = incoming.as_object() {
            let mut guard = state.license.write().await;
            if let Some(existing) = guard.as_object_mut() {
                for (k, v) in incoming_obj {
                    existing.insert(k.clone(), v.clone());
                }
            } else {
                *guard = incoming.clone();
            }
        }
    }
    Json(json!({
        "acknowledged": true,
        "license_status": "valid"
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_tasks/{task_id} — get task by ID (stub)
// POST /_tasks/{task_id}/_cancel — cancel task (no-op)
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_task_by_id(
    State(state): State<AppState>,
    Path(task_id): Path<String>,
) -> impl IntoResponse {
    if let Some(entry) = state.tasks.get(&task_id) {
        return Json(json!({
            "completed": false,
            "task": task_to_json(&entry),
        }))
        .into_response();
    }
    if let Some(completed) = state.tasks.get_completed(&task_id) {
        return Json(json!({
            "completed": true,
            "task": task_to_json_with_nanos(
                &completed.entry,
                completed.running_nanos,
                completed.entry.is_cancelled(),
            ),
            "response": completed.response,
        }))
        .into_response();
    }
    (
        StatusCode::NOT_FOUND,
        Json(json!({
            "error": {
                "type": "resource_not_found_exception",
                "reason": format!(
                    "task [{task_id}] isn't running and hasn't stored its results"
                ),
            },
            "status": 404
        })),
    )
        .into_response()
}

pub async fn cancel_task(
    State(state): State<AppState>,
    Path(task_id): Path<String>,
) -> impl IntoResponse {
    // Flip the cooperative cancel flag on the real registry; `cancel` returns
    // false (and `get` yields None) for an unknown task id.
    let existed = state.tasks.cancel(&task_id);
    let node = state.engine.node_id.as_str().to_string();
    let mut tasks = serde_json::Map::new();
    if existed {
        // Re-read so the emitted task reflects cancelled = true via task_to_json,
        // keeping the same node/tasks shape as GET /_tasks.
        if let Some(entry) = state.tasks.get(&task_id) {
            tasks.insert(entry.key(), task_to_json(&entry));
        }
    }
    Json(json!({
        "node_failures": [],
        "nodes": {
            node.clone(): {
                "name": node,
                "tasks": Value::Object(tasks),
            }
        }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_pit?keep_alive=1m — open a Point-in-Time context
// DELETE /_pit                      — close a PIT context
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Default, Deserialize)]
pub struct PitQueryParams {
    pub keep_alive: Option<String>,
}

pub async fn open_pit(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<PitQueryParams>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    let pit_id = Uuid::new_v4().to_string();
    let body_val = body.0.unwrap_or(Value::Null);
    // Resolve keep_alive: parse `?keep_alive=5m` (ES syntax) or fall
    // back to Config.pit.default_keep_alive_secs. Hard-cap at
    // Config.pit.max_keep_alive_secs so a 30-day request becomes 24h
    // silently. Sweeper reaps expired PITs on schedule.
    let pit_cfg = &state.config.pit;
    let keep_alive_secs = params
        .keep_alive
        .as_deref()
        .and_then(parse_keep_alive_to_secs)
        .unwrap_or(pit_cfg.default_keep_alive_secs)
        .min(pit_cfg.max_keep_alive_secs);
    let now = std::time::Instant::now();
    let expires_at = now + std::time::Duration::from_secs(keep_alive_secs);
    // Opportunistic sweep on every open — caps memory growth even
    // for clients that open in a tight loop without closing.
    state.engine.sweep_expired_pits();
    let index_filter = body_val.get("index_filter").cloned();
    // Resolve the pattern into concrete indices (wildcards expanded).
    // Use the live index list so indices created without explicit
    // mapping/settings bodies still show up.
    let all_indices = state.engine.index_name_list();
    let indices: Vec<String> = index
        .split(',')
        .flat_map(|n| {
            let n = n.trim();
            if n.contains('*') {
                state
                    .engine
                    .aliases
                    .iter()
                    .filter(|e| glob_match(n, e.key()))
                    .map(|e| e.key().clone())
                    .chain(
                        all_indices
                            .iter()
                            .filter(|name| glob_match(n, name))
                            .cloned(),
                    )
                    .collect::<Vec<_>>()
            } else {
                state.engine.resolve_alias(n)
            }
        })
        .collect::<std::collections::HashSet<_>>()
        .into_iter()
        .collect();
    // Snapshot the highest-visible seq_no per index. Storage's
    // `current_seq_no` is the NEXT internal counter (1-based), and
    // `lookup_seq_no` exposes the ES-form (0-based) via subtract-1.
    // The highest visible ES-form seq_no is therefore `current - 2`
    // (or 0 when no writes). We store it as the inclusive boundary.
    let mut index_max_seq: std::collections::HashMap<String, u64> =
        std::collections::HashMap::new();
    for ix in &indices {
        if let Ok(idx) = state.engine.get_index(ix) {
            let cur = idx.current_seq_no();
            index_max_seq.insert(ix.clone(), cur.saturating_sub(2));
        }
    }
    state.engine.pits.insert(
        pit_id.clone(),
        xerj_engine::engine::PitContext {
            indices,
            index_filter,
            index_max_seq,
            created: now,
            expires_at,
        },
    );
    (StatusCode::OK, Json(json!({ "id": pit_id }))).into_response()
}

/// GET /_internal/desired_balance — ES cluster desired-balance snapshot.
/// Returns shard allocation plans + cluster_balance_stats + cluster_info
/// so the 30_desired_balance YAML tests can assert on the structural
/// shape. xerj runs single-primary-per-index so `current` has one
/// STARTED entry per shard with zero replicas; an unassigned `desired`
/// slot is reported when the index was created with `replicas >= 1`.
pub async fn get_desired_balance(State(state): State<AppState>) -> impl IntoResponse {
    // Node identity is shared with the `cluster_state` handler: the YAML tests
    // read an "arbitrary key" out of cluster.state (the node id) and expect
    // desired_balance to surface the same name, so this must track
    // cluster_state's node id rather than the raw engine node_id.
    let node_id = "xerj-node-1";
    let node_name = node_id;

    // Real topology: xerj is single-node and every index is one primary shard
    // routed to the local node (Index uses num_shards = 1, always local).
    // Replicas can't be allocated on a single node, so the honest desired
    // allocation is exactly one assigned primary per index, zero unassigned.
    let indices = state.engine.list_indices().await;
    // Per-index shard / replica counts from index settings (default 1 / 0).
    let setting_u64 = |name: &str, key: &str, default: u64| -> u64 {
        state
            .engine
            .index_settings
            .get(name)
            .and_then(|v| {
                v.get("index")
                    .and_then(|ix| ix.get(key))
                    .or_else(|| v.get(key))
                    .and_then(|n| match n {
                        Value::Number(x) => x.as_u64(),
                        Value::String(s) => s.parse::<u64>().ok(),
                        _ => None,
                    })
            })
            .unwrap_or(default)
    };
    let mut routing_table = serde_json::Map::new();
    let mut total_shards: u64 = 0;
    let mut total_disk_bytes: u64 = 0;
    for info in &indices {
        let idx_name = info.name.clone();
        let disk_bytes = state
            .engine
            .get_index(&idx_name)
            .ok()
            .map(|idx| dir_size_bytes(idx.data_dir()))
            .unwrap_or(0);
        total_disk_bytes += disk_bytes;

        let num_shards = setting_u64(&idx_name, "number_of_shards", 1).max(1);
        let num_replicas = setting_u64(&idx_name, "number_of_replicas", 0);
        // Each shard copy (one primary + `num_replicas` replicas) is reported
        // STARTED on the local node. ES allocates replicas to other nodes,
        // but the desired_balance YAML test explicitly does NOT assert on the
        // node ids for replicas (it can't tell single- vs multi-node), only
        // that every requested copy is STARTED — so synthesizing them all as
        // STARTED here gives the ES-shaped routing_table the test expects.
        let copies = 1 + num_replicas;
        let mut shards = serde_json::Map::new();
        for shard_id in 0..num_shards {
            let current: Vec<Value> = (0..copies)
                .map(|copy| {
                    json!({
                        "state": "STARTED",
                        "shard_id": shard_id,
                        "index": idx_name,
                        "node_id": node_id,
                        "node_is_desired": true,
                        "relocating_node": null,
                        "relocating_node_is_desired": null,
                        "primary": copy == 0,
                        "tier_preference": ["data_content"],
                    })
                })
                .collect();
            shards.insert(
                shard_id.to_string(),
                json!({
                    "current": current,
                    "desired": {
                        "total": copies,
                        "unassigned": 0,
                        "ignored": 0,
                        "node_ids": [node_id],
                    },
                }),
            );
        }
        routing_table.insert(idx_name, Value::Object(shards));
        total_shards += num_shards;
    }

    // `is_true` in the YAML runner treats 0/0.0 as falsy and asserts every
    // balance_metric leaf is truthy. shard_count and disk usage are real;
    // write-load forecasting isn't tracked yet, so it carries a tiny positive
    // sentinel to stay shape-compatible.
    let balance_metric = |val: f64| {
        let v = val.max(1e-9);
        json!({ "total": v, "min": v, "max": v, "average": v, "std_dev": v })
    };

    Json(json!({
        "stats": {
            "computation_submitted": 1,
            "computation_executed": 1,
            "computation_converged": 1,
            "computation_iterations": 1,
            "computation_converged_index": 1,
            "computation_time_in_millis": 1,
            "reconciliation_time_in_millis": 1,
        },
        "routing_table": Value::Object(routing_table),
        "cluster_balance_stats": {
            "tiers": {
                "data_content": {
                    "shard_count": balance_metric(total_shards as f64),
                    "forecast_write_load": balance_metric(0.0),
                    "forecast_disk_usage": balance_metric(total_disk_bytes as f64),
                    "actual_disk_usage": balance_metric(total_disk_bytes as f64),
                },
            },
            "nodes": {
                node_name: {
                    "shard_count": total_shards,
                    "forecast_write_load": 0.0,
                    "forecast_disk_usage_bytes": total_disk_bytes,
                    "actual_disk_usage_bytes": total_disk_bytes,
                },
            },
        },
        "cluster_info": {
            "nodes": {
                node_id: {
                    "node_name": node_name,
                    "least_available": 0,
                    "most_available": 0,
                },
            },
            "total_bytes": total_disk_bytes,
        },
    }))
    .into_response()
}

pub async fn close_pit(
    State(state): State<AppState>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    let id = body
        .as_ref()
        .and_then(|v| v.get("id").and_then(Value::as_str))
        .map(String::from);
    let freed = match id {
        Some(i) if state.engine.pits.remove(&i).is_some() => 1,
        _ => 0,
    };
    Json(json!({ "succeeded": freed > 0, "num_freed": freed })).into_response()
}

/// Minimal glob matcher for index-name wildcard expansion (* only).
/// ES routing hash for `_id` → shard. Uses Murmur3_32 with seed 0 over
/// the UTF-16 little-endian byte encoding of each char's UTF-16 code unit,
/// matching `org.elasticsearch.cluster.routing.Murmur3HashFunction.hash(String)`.
/// Returns (positive-modulo) hash % shard_count.
fn murmur3_routing_shard(routing: &str, shard_count: u32) -> u32 {
    // Encode as per ES: for each UTF-16 code unit (2 bytes little-endian).
    let units: Vec<u16> = routing.encode_utf16().collect();
    let mut bytes: Vec<u8> = Vec::with_capacity(units.len() * 2);
    for c in units {
        bytes.push((c & 0xff) as u8);
        bytes.push(((c >> 8) & 0xff) as u8);
    }
    let bytes: &[u8] = &bytes;
    let mut h: u32 = 0; // seed
    let nblocks = bytes.len() / 4;
    let c1: u32 = 0xcc9e2d51;
    let c2: u32 = 0x1b873593;
    for i in 0..nblocks {
        let b = i * 4;
        let mut k: u32 = (bytes[b] as u32)
            | ((bytes[b + 1] as u32) << 8)
            | ((bytes[b + 2] as u32) << 16)
            | ((bytes[b + 3] as u32) << 24);
        k = k.wrapping_mul(c1);
        k = k.rotate_left(15);
        k = k.wrapping_mul(c2);
        h ^= k;
        h = h.rotate_left(13);
        h = h.wrapping_mul(5).wrapping_add(0xe6546b64);
    }
    // Tail
    let tail_start = nblocks * 4;
    let tail = &bytes[tail_start..];
    let mut k: u32 = 0;
    if tail.len() >= 3 {
        k ^= (tail[2] as u32) << 16;
    }
    if tail.len() >= 2 {
        k ^= (tail[1] as u32) << 8;
    }
    if !tail.is_empty() {
        k ^= tail[0] as u32;
        k = k.wrapping_mul(c1);
        k = k.rotate_left(15);
        k = k.wrapping_mul(c2);
        h ^= k;
    }
    // Finalization
    h ^= bytes.len() as u32;
    h ^= h >> 16;
    h = h.wrapping_mul(0x85ebca6b);
    h ^= h >> 13;
    h = h.wrapping_mul(0xc2b2ae35);
    h ^= h >> 16;
    // ES uses the java-style "positive modulo" on the i32 reinterpretation.
    let as_i32 = h as i32;
    let m = as_i32.rem_euclid(shard_count as i32);
    m as u32
}

/// Remove a value at a dotted path from an object, cleaning up empty
/// parent objects along the way.
fn remove_dotted_path(obj: &mut serde_json::Map<String, Value>, path: &str) {
    let segs: Vec<&str> = path.split('.').collect();
    if segs.is_empty() {
        return;
    }
    if segs.len() == 1 {
        obj.remove(segs[0]);
        return;
    }
    // Descend to parent.
    let mut stack: Vec<*mut serde_json::Map<String, Value>> = Vec::new();
    let mut cur: *mut serde_json::Map<String, Value> = obj;
    for seg in &segs[..segs.len() - 1] {
        // SAFETY: single-threaded mutation, we don't alias overlapping borrows
        let c = unsafe { &mut *cur };
        stack.push(cur);
        match c.get_mut(*seg) {
            Some(Value::Object(next)) => {
                cur = next;
            }
            _ => return,
        }
    }
    let c = unsafe { &mut *cur };
    c.remove(segs.last().copied().unwrap_or(""));
    // Prune empty ancestors (bottom-up).
    for i in (0..segs.len() - 1).rev() {
        let parent = unsafe { &mut *stack[i] };
        let seg = segs[i];
        let should_remove = parent
            .get(seg)
            .and_then(Value::as_object)
            .map(|o| o.is_empty())
            .unwrap_or(false);
        if should_remove {
            parent.remove(seg);
        } else {
            break;
        }
    }
}

/// Convert a primitive JSON value to its keyword-field string form
/// (ES coerces `true` → "true", `1` → "1" for keyword-mapped targets).
fn stringify_for_keyword(v: Value) -> Value {
    match v {
        Value::String(_) => v,
        Value::Number(n) => Value::String(n.to_string()),
        Value::Bool(b) => Value::String(if b {
            "true".to_string()
        } else {
            "false".to_string()
        }),
        Value::Null => Value::Null,
        other => Value::String(other.to_string()),
    }
}

/// Strip `match`/`term`/`bool` constraints that target the metadata
/// `_index` field. The stripped patterns are pushed to `out`, so the
/// caller can use them to filter the coordination-time index_names
/// list. Empty-leaf objects from removal are pruned.
fn strip_index_constraints(q: &mut Value, out: &mut Vec<String>) {
    let Some(obj) = q.as_object_mut() else { return };
    let keys: Vec<String> = obj.keys().cloned().collect();
    for key in keys {
        let remove_this = match key.as_str() {
            "match" | "term" => {
                let take_out = obj
                    .get(&key)
                    .and_then(Value::as_object)
                    .and_then(|vo| {
                        vo.get("_index").map(|idx_v| {
                            if let Some(query_obj) = idx_v.as_object() {
                                query_obj
                                    .get("query")
                                    .or_else(|| query_obj.get("value"))
                                    .and_then(Value::as_str)
                                    .map(str::to_string)
                            } else {
                                idx_v.as_str().map(str::to_string)
                            }
                        })
                    })
                    .flatten();
                if let Some(pat) = take_out {
                    out.push(pat);
                    true
                } else {
                    false
                }
            }
            "bool" => {
                if let Some(b) = obj.get_mut(&key).and_then(Value::as_object_mut) {
                    for sub_key in ["must", "filter", "should"] {
                        if let Some(arr) = b.get_mut(sub_key).and_then(Value::as_array_mut) {
                            for item in arr.iter_mut() {
                                strip_index_constraints(item, out);
                            }
                            arr.retain(|item| {
                                !item.as_object().map(|o| o.is_empty()).unwrap_or(false)
                            });
                        }
                    }
                }
                false
            }
            _ => false,
        };
        if remove_this {
            obj.remove(&key);
        }
    }
}

/// Parse an ES-style duration (`1ms` / `5s` / `2m` / `1h` / `7d`) to
/// seconds. Returns `None` on garbage so callers can fall back to a
/// configured default rather than 400.
///
/// Used by `_pit?keep_alive=5m` (and any other endpoint that accepts
/// the same shape). Sub-second units round up to 1 second so
/// `keep_alive=500ms` doesn't produce a zero-duration PIT.
fn parse_keep_alive_to_secs(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    if let Some(ms) = s.strip_suffix("ms") {
        let n: u64 = ms.parse().ok()?;
        return Some((n / 1000).max(1));
    }
    let (digits, mul) = match s.as_bytes().last()? {
        b's' => (&s[..s.len() - 1], 1u64),
        b'm' => (&s[..s.len() - 1], 60),
        b'h' => (&s[..s.len() - 1], 3_600),
        b'd' => (&s[..s.len() - 1], 86_400),
        _ => (s, 1), // bare number → seconds
    };
    let n: u64 = digits.parse().ok()?;
    Some(n.saturating_mul(mul).max(1))
}

fn glob_match(pattern: &str, name: &str) -> bool {
    if pattern == "*" || pattern == "_all" {
        return true;
    }
    if !pattern.contains('*') {
        return pattern == name;
    }
    let parts: Vec<&str> = pattern.split('*').collect();
    let mut pos = 0usize;
    for (i, part) in parts.iter().enumerate() {
        if part.is_empty() {
            continue;
        }
        if i == 0 {
            if !name.starts_with(part) {
                return false;
            }
            pos = part.len();
        } else if i == parts.len() - 1 {
            return name[pos..].ends_with(part);
        } else {
            match name[pos..].find(part) {
                Some(idx) => {
                    pos += idx + part.len();
                }
                None => return false,
            }
        }
    }
    true
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_eql/search — EQL search stub
// ─────────────────────────────────────────────────────────────────────────────

/// Compare two EQL timestamp-field values (pulled from each event's `_source`)
/// for the ascending merge sort (#567). Epoch numbers compare numerically (one
/// unit per corpus). Strings are parsed as RFC3339 / ISO-8601 and compared as
/// real instants — NOT byte-wise: a raw string compare misorders mixed
/// fractional-second precision (`…:01.500Z` vs `…:01Z`, since `.` < `Z`) and
/// non-UTC offsets (`…+05:00` is an earlier instant than the lexically-smaller
/// `…Z`), which are the norm in SIEM/log corpora. `chrono::DateTime` orders by
/// the UTC instant, so both are handled. An unparseable value falls back to a
/// deterministic byte order; a missing field sorts last so a malformed doc never
/// displaces a real earliest hit.
fn eql_timestamp_cmp(a: Option<&Value>, b: Option<&Value>) -> std::cmp::Ordering {
    use std::cmp::Ordering::{Equal, Greater, Less};
    match (a, b) {
        (Some(x), Some(y)) => {
            if let (Some(nx), Some(ny)) = (x.as_f64(), y.as_f64()) {
                nx.partial_cmp(&ny).unwrap_or(Equal)
            } else if let (Some(sx), Some(sy)) = (x.as_str(), y.as_str()) {
                match (
                    chrono::DateTime::parse_from_rfc3339(sx),
                    chrono::DateTime::parse_from_rfc3339(sy),
                ) {
                    (Ok(dx), Ok(dy)) => dx.cmp(&dy),
                    // Non-RFC3339 formats the engine may still accept: fall back
                    // to a deterministic byte order rather than misrank silently.
                    _ => sx.cmp(sy),
                }
            } else {
                Equal
            }
        }
        (Some(_), None) => Less,
        (None, Some(_)) => Greater,
        (None, None) => Equal,
    }
}

pub async fn eql_search(
    State(state): State<AppState>,
    Path(index): Path<String>,
    body: Option<Json<Value>>,
) -> impl IntoResponse {
    let started = Instant::now();
    let body = body.map(|b| b.0).unwrap_or_else(|| json!({}));

    // EQL request body carries the program in the `query` string field.
    let eql = match body.get("query").and_then(Value::as_str) {
        Some(q) => q.to_string(),
        None => {
            let reason = "request body must contain a `query` string";
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({
                    "error": {
                        "root_cause": [{ "type": "parsing_exception", "reason": reason }],
                        "type": "parsing_exception",
                        "reason": reason,
                    },
                    "status": 400,
                })),
            )
                .into_response();
        }
    };

    // EQL sequence/sample queries (multi-event correlation) are not
    // implemented. Detect them by their leading keyword and fail loudly
    // rather than silently degrading to a single-condition query — or, for a
    // bare `sequence ... by ...` with no inner `where`, to `match_all` over
    // EVERY doc. A silent wrong answer is a correctness hazard for SIEM
    // users. Single-event queries (`<category> where <condition>`) are
    // supported and continue through the normal path below.
    let first_word: String = eql
        .trim_start()
        .chars()
        .take_while(|c| c.is_alphanumeric() || *c == '_')
        .collect::<String>()
        .to_ascii_lowercase();
    if first_word == "sequence" || first_word == "sample" {
        let reason = format!(
            "EQL {first_word} queries (multi-event correlation) are not supported by XERJ. \
             Only single-event EQL is implemented (`<category> where <condition>`)."
        );
        return (
            StatusCode::NOT_IMPLEMENTED,
            Json(json!({
                "error": {
                    "root_cause": [{ "type": "verification_exception", "reason": reason }],
                    "type": "verification_exception",
                    "reason": reason,
                },
                "status": 501,
            })),
        )
            .into_response();
    }

    // Translate EQL -> xerj DSL, then run it through the normal search path.
    let inner_query = eql_to_query(&eql);
    let size = body.get("size").and_then(Value::as_u64).unwrap_or(10);
    // #567: EQL orders single-event results by the timestamp field ascending
    // (default `@timestamp`, overridable via `timestamp_field`). The alias
    // fan-out below must sort the MERGED events by it before truncating to
    // `size`, otherwise the surviving page is biased toward the earlier-iterated
    // members rather than the globally-earliest events.
    let ts_field = body
        .get("timestamp_field")
        .and_then(Value::as_str)
        .unwrap_or("@timestamp")
        .to_string();

    // Fan out to every member of a multi-index alias (#451 `_eql` arm):
    // eql_search used Engine::get_index -> aliased.first(), silently returning
    // only the first member's events. Search each member and merge the event
    // lists, reporting the concrete member in `_index`. Resolve BEFORE building
    // the request so any alias `filter` is ANDed into the query: a *filtered*
    // alias is a document boundary (#451 class C, commit 170f41f2 closed this
    // exact leak for _search/_msearch), so EQL must honour it too — fanning out
    // unfiltered would leak the hidden members' rows.
    let (members, filters) = match resolve_selector_with_filters(&state, &index).await {
        Ok(t) => t,
        Err(e) => return ApiError::new(e).into_response(),
    };
    let effective_query = if filters.is_empty() {
        inner_query
    } else {
        json!({ "bool": { "must": [inner_query], "filter": filters } })
    };
    // Sort each member ascending by the timestamp field: a member with more than
    // `size` matches must contribute its EARLIEST events to the merge, not its
    // top-scored ones, or the global-earliest page can miss them. `unmapped_type`
    // is ES's escape hatch so a member index without the timestamp field is not a
    // 400 ("No mapping found for [@timestamp] in order to sort on") — XERJ's EQL,
    // unlike ES, does not require a timestamp field, so this must degrade to
    // unsorted for such a corpus rather than fail.
    let mut ts_sort = serde_json::Map::new();
    ts_sort.insert(
        ts_field.clone(),
        json!({ "order": "asc", "unmapped_type": "date" }),
    );
    let search_body = json!({
        "query": effective_query,
        "size": size,
        "from": 0,
        "sort": [Value::Object(ts_sort)],
    });

    let req = match xerj_query::parse_request(&search_body)
        .map_err(|e| xerj_common::XerjError::invalid_query(e.to_string()))
    {
        Ok(r) => r,
        Err(e) => return ApiError::new(e).into_response(),
    };
    let mut events: Vec<Value> = Vec::new();
    let mut total: u64 = 0;
    for (mname, midx) in &members {
        match midx.search(&req).await {
            Ok(result) => {
                total += result.total.value;
                for h in result.hits {
                    let source = if h.source.is_null() {
                        Value::Null
                    } else {
                        h.source
                    };
                    events.push(json!({
                        "_index": mname,
                        "_id": h.id,
                        "_source": source,
                    }));
                }
            }
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    }
    // #567: order the merged events by the timestamp field ascending BEFORE
    // truncating, so the returned page is the globally-earliest `size` events
    // (ES EQL semantics), not whichever alias members were iterated first. Stable
    // so events with equal timestamps keep member/order determinism.
    events.sort_by(|a, b| {
        eql_timestamp_cmp(
            a.get("_source").and_then(|s| s.get(&ts_field)),
            b.get("_source").and_then(|s| s.get(&ts_field)),
        )
    });
    // Apply the EQL `size` limit across the merged member results.
    events.truncate(size as usize);
    let took_ms = started.elapsed().as_millis() as u64;
    Json(json!({
        "is_partial": false,
        "is_running": false,
        "took": took_ms,
        "timed_out": false,
        "hits": {
            "total": { "value": total, "relation": "eq" },
            "events": events,
        },
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_field_caps — global field_caps across all indices (index=*)
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize, Default)]
pub struct GlobalFieldCapsParams {
    pub fields: Option<String>,
    pub index: Option<String>,
}

pub async fn global_field_caps(
    State(state): State<AppState>,
    Query(params): Query<GlobalFieldCapsParams>,
    _body: Option<Json<Value>>,
) -> impl IntoResponse {
    let index_names = state.engine.index_name_list();
    let fields_filter = params.fields.as_deref().unwrap_or("*");

    let mut fields_map: HashMap<String, serde_json::Map<String, Value>> = HashMap::new();

    for index_name in &index_names {
        let idx = match state.engine.get_index(index_name) {
            Ok(i) => i,
            Err(_) => continue,
        };
        let schema = idx.schema().await;

        // See the matching comment in `field_caps`: `flattened`/
        // `flat_object` both collapse to `FieldType::Object` natively, so
        // the mapping itself is the only place the real declared type
        // still lives.
        let stored_mapping = state
            .engine
            .index_mappings
            .get(index_name.as_str())
            .map(|v| v.clone())
            .unwrap_or(Value::Null);
        let mut live_properties = schema_to_es_properties(&schema);
        let properties = if stored_mapping.is_null() {
            Value::Object(live_properties)
        } else {
            // Same merge as `field_caps` (per-index) -- without it, a field
            // discovered dynamically since this index was created (flat or
            // nested, at any depth) is invisible here too, and this
            // cluster-wide endpoint would silently disagree with the
            // per-index one about which fields exist.
            let stored_properties = stored_mapping
                .get("properties")
                .and_then(|p| p.as_object())
                .cloned()
                .unwrap_or_default();
            let companions = semantic_companion_field_names(&stored_properties);
            live_properties.retain(|k, _| !companions.contains(k));
            Value::Object(merge_mapping_properties(
                &stored_properties,
                &live_properties,
            ))
        };

        for field in &schema.fields {
            register_field_cap_entry(
                field,
                "",
                &properties,
                fields_filter,
                index_name,
                &mut fields_map,
            );
        }

        // Multi-fields (`"fields": {"keyword": {...}}`) -- same #209
        // mechanism as `field_caps` (per-index); this cluster-wide form
        // never had it at all.
        let mut multi_fields = Vec::new();
        collect_multi_fields(&properties, "", &mut multi_fields);
        for (name, es_type) in multi_fields {
            if fields_filter != "*" {
                let matches = fields_filter
                    .split(',')
                    .any(|f| glob_match(f.trim(), &name));
                if !matches {
                    continue;
                }
            }
            let (searchable, aggregatable) = match es_type.as_str() {
                "text" => (true, false),
                _ => (true, true),
            };
            let type_map = fields_map.entry(name).or_default();
            let type_entry = type_map.entry(es_type.clone()).or_insert_with(|| {
                json!({
                    "type": es_type,
                    "searchable": searchable,
                    "aggregatable": aggregatable,
                    "indices": []
                })
            });
            if let Some(arr) = type_entry["indices"].as_array_mut() {
                if !arr.iter().any(|v| v.as_str() == Some(index_name.as_str())) {
                    arr.push(Value::String(index_name.clone()));
                }
            }
        }
    }

    let fields_val: Value = Value::Object(
        fields_map
            .into_iter()
            .map(|(field_name, type_map)| (field_name, Value::Object(type_map)))
            .collect(),
    );

    Json(json!({
        "indices": index_names,
        "fields": fields_val,
    }))
    .into_response()
}

fn field_name_matches(field: &str, pattern: &str) -> bool {
    if let Some(prefix) = pattern.strip_suffix('*') {
        field.starts_with(prefix)
    } else {
        field == pattern
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{index}/_mapping/field/{field}
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_mapping_field(
    State(state): State<AppState>,
    Path((index, field)): Path<(String, String)>,
) -> impl IntoResponse {
    let idx = match state.engine.get_index(&index) {
        Ok(i) => i,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    let schema = idx.schema().await;
    let properties = schema_to_es_properties(&schema);
    // `flattened`/`flat_object` (and anything else that collapses to a
    // generic native FieldType) only survive as their real declared name
    // in the stored mapping — the native-schema-derived `properties` above
    // has already lost that distinction. Used as a per-field override
    // below so a dynamically-inferred field with no stored-mapping entry
    // still falls back to the schema-derived type, same as before.
    let stored_mapping = state
        .engine
        .index_mappings
        .get(index.as_str())
        .map(|v| v.clone())
        .unwrap_or(Value::Null);
    let stored_properties = stored_mapping
        .get("properties")
        .cloned()
        .unwrap_or_else(|| json!({}));

    // Collect matching field entries. Supports comma-separated field names and wildcard `*`.
    let field_names: Vec<&str> = field.split(',').map(str::trim).collect();
    let mut mapping_result = serde_json::Map::new();

    for (field_name, field_def) in &properties {
        let matches = field_names.iter().any(|pat| {
            if *pat == "*" {
                true
            } else {
                field_name_matches(field_name, pat)
            }
        });
        if matches {
            let native_es_type = field_def
                .get("type")
                .and_then(Value::as_str)
                .unwrap_or("object");
            let es_type = declared_flattened_type(&stored_properties, field_name)
                .or_else(|| declared_numeric_type(&stored_properties, field_name))
                .unwrap_or(native_es_type);
            mapping_result.insert(
                field_name.clone(),
                json!({
                    "full_name": field_name,
                    "mapping": {
                        field_name: {
                            "type": es_type
                        }
                    }
                }),
            );
        }
    }

    let resp = json!({
        index: {
            "mappings": mapping_result
        }
    });
    Json(resp).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// PUT    /{index}/_block/{block}   — add a block
// DELETE /{index}/_block/{block}   — remove it again
// ─────────────────────────────────────────────────────────────────────────────

/// Shared body of the two `_block` verbs.
///
/// `enabled` selects add vs remove. Removal exists because the only other way
/// off a block — `PUT /_settings` — used to write the display copy alone, so an
/// index that took a block could never be un-blocked without a restart.
async fn set_index_block(
    state: AppState,
    index: String,
    block: String,
    enabled: bool,
) -> axum::response::Response {
    let idx = match state.engine.get_index(&index) {
        Ok(i) => i,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    if !xerj_engine::Index::BLOCK_NAMES.contains(&block.as_str()) {
        let e = xerj_common::XerjError::invalid_query(format!(
            "invalid index block: {block}; valid values are: {}",
            xerj_engine::Index::BLOCK_NAMES.join(", ")
        ));
        return ApiError::new(e).into_response();
    }

    if let Err(e) = idx.set_block_state(&block, enabled).await {
        return ApiError::new(xerj_common::XerjError::from(e)).into_response();
    }
    // Keep GET /_settings in step with what is actually enforced.
    sync_display_blocks(&state, &index).await;

    Json(json!({
        "acknowledged": true,
        "shards_acknowledged": true,
        "indices": [{ "name": index, "blocked": enabled }]
    }))
    .into_response()
}

pub async fn put_index_block(
    State(state): State<AppState>,
    Path((index, block)): Path<(String, String)>,
) -> impl IntoResponse {
    set_index_block(state, index, block, true).await
}

pub async fn delete_index_block(
    State(state): State<AppState>,
    Path((index, block)): Path<(String, String)>,
) -> impl IntoResponse {
    set_index_block(state, index, block, false).await
}

// ─────────────────────────────────────────────────────────────────────────────
// _explain API
// GET/POST /{index}/_explain/{id}
// ─────────────────────────────────────────────────────────────────────────────

pub async fn explain_doc(
    State(state): State<AppState>,
    Path((index, id)): Path<(String, String)>,
    body: OptionalJson<Value>,
) -> impl IntoResponse {
    // Resolve the selector through the shared resolver (#451): an alias expands
    // to every member, so the document is explained against the member that
    // actually holds it. `get_index` collapsed an alias to `aliased.first()`,
    // so a non-first member's doc reported `matched:false` / "document not
    // found" (class B).
    let (members, _filters) = match resolve_selector_with_filters(&state, &index).await {
        Ok(t) => t,
        Err(e) => return ApiError::new(e).into_response(),
    };
    let mut resolved = None;
    for (mname, midx) in &members {
        match midx.get_document(&id).await {
            Ok(Some(s)) => {
                resolved = Some((mname.clone(), midx.clone(), s));
                break;
            }
            Ok(None) => {}
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    }
    // On a hit, `index` is rebound to the concrete member (reported in
    // `_index`); the not-found arm still names the selector the caller wrote.
    let (index, idx, doc_source) = match resolved {
        Some((mname, midx, s)) => (mname, midx, s),
        None => {
            return Json(json!({
                "_index": index,
                "_id": id,
                "matched": false,
                "explanation": {
                    "value": 0.0,
                    "description": "document not found",
                    "details": []
                }
            }))
            .into_response();
        }
    };

    // Parse the query from the body (default to match_all if absent).
    let query_val = body
        .as_ref()
        .and_then(|b| b.get("query"))
        .cloned()
        .unwrap_or(json!({ "match_all": {} }));

    let search_body = json!({ "query": query_val, "size": 0 });
    let search_req = match xerj_query::parse_request(&search_body) {
        Ok(r) => r,
        Err(e) => {
            let ze = xerj_common::XerjError::invalid_query(e.to_string());
            return ApiError::new(ze).into_response();
        }
    };

    // Check if the document matches the query by running it as an Ids query + the actual query.
    // We run the query and check if our doc_id is in the results.
    let mut ids_req = search_req.clone();
    // Replace the query with a bool filter: must match the given query AND the doc id.
    use xerj_query::ast::QueryNode;
    ids_req.query = QueryNode::Bool {
        must: vec![search_req.query.clone()],
        should: vec![],
        must_not: vec![],
        filter: vec![QueryNode::Ids {
            values: vec![id.clone()],
        }],
        minimum_should_match: None,
    };
    ids_req.size = 1;
    ids_req.from = 0;

    // A Painless resource limit that tripped while answering this. It is
    // REPORTED rather than refused, which is the opposite of what every other
    // surface does, and deliberately so: `_explain` is a diagnostic endpoint.
    //
    // Most script faults here come from SCORING (`function_score`'s
    // `script_score`, `rescore`), and scoring does not decide `matched` —
    // that comes from the ids-filtered hit list. Refusing turned a correct
    // 200 into a 400 for exactly the person trying to debug the script.
    // Where the script IS load-bearing for matching, `matched: false` would be
    // a confident negative, so it cannot simply be published silently either.
    // Reporting the fault alongside the verdict satisfies both: the caller
    // still gets the answer, and never gets it without being told a limit
    // tripped.
    let (matched, script_failure) = match idx.search(&ids_req).await {
        Ok(result) => (!result.hits.is_empty(), result.script_failure),
        // The engine REFUSED to run the query — e.g. it names a field the
        // mapping declared `"index": false` with no doc values, which ES
        // rejects with `Cannot search on field [f] since it is not indexed
        // nor has doc values.` Publishing `matched: false` here would be a
        // confident negative for a question that was never asked, which is
        // the accepted-and-ignored failure of #204 wearing a diagnostic hat.
        // Every other error path in this handler already returns `ApiError`;
        // so does this one, giving `_explain` the same 400 envelope
        // `_search` and `_count` return for the identical query.
        //
        // Deliberately NOT the same as `script_failure` above: there the
        // engine DID produce a hit list and only scoring was degraded, so the
        // verdict is real and the fault is reported alongside it.
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    let score = if matched { 1.0_f64 } else { 0.0_f64 };
    let description = if matched {
        format!("document [{}] matches the query", id)
    } else {
        format!("document [{}] does not match the query", id)
    };

    // Build a simple explanation tree.
    let explanation = build_explanation(score as f32, &search_req.query);

    // A tripped resource limit becomes an extra detail node rather than
    // vanishing. `matched` above is still the verdict; this says what the
    // engine refused to finish while reaching it, so a scoring-script fault
    // is visible without costing the caller the answer.
    let details = match &script_failure {
        Some(reason) => json!([
            explanation,
            {
                "value": 0.0,
                "description": format!(
                    "a script hit a resource limit while answering this explain: {reason}"
                ),
                "details": []
            }
        ]),
        None => json!([explanation]),
    };

    Json(json!({
        "_index": index,
        "_id": id,
        "matched": matched,
        "_source": doc_source,
        "explanation": {
            "value": score,
            "description": description,
            "details": details
        }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// Search body extensions: stored_fields, docvalue_fields, inner_hits
// These are handled in build_search_request and the search handler.
// The helpers below process the raw body fields that are not part of
// SearchRequest (they are purely response-time transformations).
// ─────────────────────────────────────────────────────────────────────────────

/// Process `stored_fields` from the ES search body.
///
/// - `["_id", "_routing"]` — return only the listed meta-fields per hit.
/// - `"_none_"` — return no stored fields at all (suppress _source too).
///
/// Returns `(suppress_source, meta_fields_to_include)`.
/// Parse the `stored_fields` body parameter.
///
/// Returns `(suppress_source, meta_fields, suppress_meta)`:
/// - `suppress_source`: drop `_source` from hits.
/// - `meta_fields`: list of explicit stored-field names to fetch into `fields`.
/// - `suppress_meta`: drop `_id` (and other meta) from hits. ES returns this
///   for `"_none_"` only — the empty-array form keeps `_id`.
pub(crate) fn parse_stored_fields(stored_fields_val: &Value) -> (bool, Vec<String>) {
    match stored_fields_val {
        Value::String(s) if s == "_none_" => (true, vec!["__none__".to_string()]),
        // ES: `stored_fields: []` (empty array) or `stored_fields: null`
        // both suppress `_source` but keep `_id`.
        Value::Array(arr) if arr.is_empty() => (true, vec![]),
        Value::Null => (true, vec![]),
        // ES: a non-empty `stored_fields` list suppresses `_source` unless
        // the caller explicitly opts back in by including `_source` as a
        // list entry. This matches the behavior covered by
        // search/10_source_filtering.yml "fields in body" (suppressed) and
        // "fields in body with source" (kept).
        Value::Array(arr) => {
            let fields: Vec<String> = arr
                .iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect();
            let opt_in_source = fields.iter().any(|f| f == "_source");
            let keepers: Vec<String> = fields.iter().filter(|f| f != &"_source").cloned().collect();
            (!opt_in_source, keepers)
        }
        Value::String(s) => {
            // `stored_fields: "field"` treats single field same as array.
            let opt_in_source = s == "_source";
            if opt_in_source {
                (false, vec![])
            } else {
                (true, vec![s.clone()])
            }
        }
        _ => (false, vec![]),
    }
}

/// Build the `fields` map for docvalue_fields: `{"price": [29.99], "category": ["tools"]}`.
///
/// For now we read from _source (doc values are not separately stored).
/// Expand a wildcard pattern like `user.*` or `*_name` against a doc's
/// _source, returning the list of matching dotted field paths.
pub(crate) fn expand_field_wildcard(source: &Value, pattern: &str) -> Vec<String> {
    let mut out: Vec<(String, bool)> = Vec::new(); // (path, is_scalar_leaf)
    collect_field_paths(source, "", &mut out);
    out.retain(|(p, _)| wildcard_match(pattern, p));
    // ES's fields: [*] returns only LEAF paths (no intermediate object
    // paths). Drop any path that is a prefix of another collected path —
    // UNLESS the path itself resolves to a scalar value in _source, which
    // happens when subobjects:false indexes split a dotted key. In that
    // case both `root` and `root.subfield` are leaves and both should be
    // fetchable.
    let is_scalar: std::collections::HashMap<String, bool> = out.iter().cloned().collect();
    out.retain(|(p, this_is_scalar)| {
        if *this_is_scalar {
            // Scalar leaves are always leaves — keep regardless of
            // whether some sibling-like key happens to start with p+"."
            return true;
        }
        !is_scalar
            .keys()
            .any(|other| other != p && other.starts_with(&format!("{}.", p)))
    });
    out.into_iter().map(|(p, _)| p).collect()
}

fn collect_field_paths(v: &Value, prefix: &str, out: &mut Vec<(String, bool)>) {
    if let Value::Object(map) = v {
        for (k, child) in map {
            let path = if prefix.is_empty() {
                k.clone()
            } else {
                format!("{}.{}", prefix, k)
            };
            let is_scalar = !matches!(child, Value::Object(_));
            out.push((path.clone(), is_scalar));
            collect_field_paths(child, &path, out);
        }
    }
}

fn wildcard_match(pattern: &str, text: &str) -> bool {
    // Simple `*` wildcard match (no `?`). Linear two-pointer.
    let p = pattern.as_bytes();
    let t = text.as_bytes();
    let (mut pi, mut ti) = (0usize, 0usize);
    let (mut star, mut star_t) = (None::<usize>, 0usize);
    while ti < t.len() {
        if pi < p.len() && (p[pi] == b'?' || p[pi] == t[ti]) {
            pi += 1;
            ti += 1;
        } else if pi < p.len() && p[pi] == b'*' {
            star = Some(pi);
            star_t = ti;
            pi += 1;
        } else if let Some(sp) = star {
            pi = sp + 1;
            star_t += 1;
            ti = star_t;
        } else {
            return false;
        }
    }
    while pi < p.len() && p[pi] == b'*' {
        pi += 1;
    }
    pi == p.len()
}

/// Apply an ES date format pattern to a single field value.
/// When `val` is a string, parse as RFC3339/ISO and re-render using the
/// SimpleDateFormat-derived pattern; otherwise return unchanged.
/// Normalise a geo_point value into the format ES emits in the
/// `fields` response. Accepts every ingestible shape — `{lat,lon}`,
/// `[lon,lat]`, `"lat,lon"`, `"POINT (lon lat)"` — and returns
/// either a GeoJSON Point object (default) or a WKT string when
/// the caller asked for `format: wkt`.
/// Scan the target index's mapping for a `*_range`-typed field that
/// declares `copy_to` AND is present in the doc. ES rejects those
/// at ingest (since ranges aren't "value-type" fields from a
/// copy-to perspective) with a `document_parsing_exception`. Returns
/// the offending field name when found.
fn first_range_copy_to_field_in_mapping(
    state: &AppState,
    index: &str,
    doc: Option<&serde_json::Map<String, Value>>,
) -> Option<String> {
    let doc = doc?;
    let mapping = state.engine.index_mappings.get(index)?.clone();
    let props = mapping
        .get("mappings")
        .and_then(|m| m.get("properties"))
        .or_else(|| mapping.get("properties"))?
        .as_object()?
        .clone();
    for (fname, spec) in &props {
        if !doc.contains_key(fname) {
            continue;
        }
        let ftype = spec.get("type").and_then(Value::as_str).unwrap_or("");
        let is_range = ftype.ends_with("_range");
        if !is_range {
            continue;
        }
        if spec.get("copy_to").is_some() {
            return Some(fname.clone());
        }
    }
    None
}

pub(crate) fn reshape_geo_point(val: &Value, want_wkt: bool) -> Value {
    let parse_f = |v: &Value| -> Option<f64> {
        match v {
            Value::Number(n) => n.as_f64(),
            Value::String(s) => s.parse::<f64>().ok(),
            _ => None,
        }
    };
    let (lon, lat): (f64, f64) = match val {
        Value::Object(obj) => {
            let lat = obj.get("lat").and_then(parse_f);
            let lon = obj.get("lon").and_then(parse_f);
            match (lat, lon) {
                (Some(lat), Some(lon)) => (lon, lat),
                _ => return val.clone(),
            }
        }
        Value::Array(arr) if arr.len() == 2 => {
            let a = parse_f(&arr[0]);
            let b = parse_f(&arr[1]);
            match (a, b) {
                (Some(x), Some(y)) => (x, y), // ES convention: [lon, lat]
                _ => return val.clone(),
            }
        }
        Value::String(s) => {
            // "POINT (lon lat)" — WKT.
            if let Some(rest) = s.trim().strip_prefix("POINT") {
                let inner = rest
                    .trim_start()
                    .trim_start_matches('(')
                    .trim_end_matches(')');
                let mut it = inner.split_whitespace();
                if let (Some(lons), Some(lats)) = (it.next(), it.next()) {
                    if let (Ok(lon), Ok(lat)) = (lons.parse::<f64>(), lats.parse::<f64>()) {
                        return if want_wkt {
                            Value::String(format!("POINT ({} {})", lon, lat))
                        } else {
                            json!({"type": "Point", "coordinates": [lon, lat]})
                        };
                    }
                }
                return val.clone();
            }
            // "lat,lon"
            if let Some((a, b)) = s.split_once(',') {
                if let (Ok(lat), Ok(lon)) = (a.trim().parse::<f64>(), b.trim().parse::<f64>()) {
                    (lon, lat)
                } else {
                    return val.clone();
                }
            } else {
                return val.clone();
            }
        }
        _ => return val.clone(),
    };
    if want_wkt {
        Value::String(format!("POINT ({} {})", lon, lat))
    } else {
        json!({"type": "Point", "coordinates": [lon, lat]})
    }
}

pub(crate) fn apply_field_format(val: &Value, fmt: &str) -> Value {
    let s = match val {
        Value::String(s) => s.as_str(),
        _ => return val.clone(),
    };
    let ms = parse_iso_to_ms(s);
    if let Some(ms) = ms {
        let dt = chrono::DateTime::from_timestamp_millis(ms).unwrap_or_default();
        let out = xerj_engine::aggs::render_date_format(Some(fmt), ms, dt);
        return Value::String(out);
    }
    val.clone()
}

fn parse_iso_to_ms(s: &str) -> Option<i64> {
    if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(s) {
        return Some(dt.timestamp_millis());
    }
    if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
        return Some(dt.and_utc().timestamp_millis());
    }
    if let Ok(d) = chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d") {
        return Some(d.and_hms_opt(0, 0, 0).unwrap().and_utc().timestamp_millis());
    }
    None
}

pub(crate) fn build_docvalue_fields(
    source: &Value,
    docvalue_fields: &[Value],
) -> Option<HashMap<String, Value>> {
    if docvalue_fields.is_empty() {
        return None;
    }
    let mut map = HashMap::new();
    for entry in docvalue_fields {
        let (field_name, format) = match entry {
            Value::String(s) => (s.as_str(), None),
            Value::Object(obj) => {
                let name = obj.get("field").and_then(Value::as_str).unwrap_or("");
                let fmt = obj.get("format").and_then(Value::as_str);
                (name, fmt)
            }
            _ => continue,
        };
        if field_name.is_empty() {
            continue;
        }
        let raw = get_source_value_by_path(source, field_name);
        // `.keyword` is ES's conventional multi-field sub-type on
        // dynamic/keyword fields. When the declared field doesn't
        // carry an explicit `.keyword` leaf but the base field holds
        // a string (or array of strings), treat the request as
        // asking for the base value (keyword multi-field semantics).
        let raw = raw.or_else(|| {
            let base = field_name.strip_suffix(".keyword")?;
            get_source_value_by_path(source, base)
        });
        // Same packed-embedding expansion as `fields` (#1940). Doc values
        // skip the string, so this path is the one that still sees it.
        let raw = raw.map(expand_packed_embedding_value);
        let arr: Vec<Value> = match raw {
            Some(Value::Array(a)) => a,
            Some(Value::Null) | None => vec![],
            Some(v) => vec![v],
        };
        // Apply ES `format` to each value when set. For dates this
        // re-renders nanosecond-precision strings at the requested
        // precision (strict_date_optional_time → ms; epoch_millis →
        // numeric epoch ms with optional fractional ns).
        let formatted: Vec<Value> = if let Some(fmt) = format {
            arr.into_iter()
                .map(|v| reformat_docvalue(&v, fmt))
                .collect()
        } else {
            arr
        };
        // A field that resolves to NO values is omitted, never emitted as a bare
        // `[]` (#310): `{"body_vector": []}` is a positive claim that the doc has
        // no values for that field. ES omits an unresolvable `docvalue_fields`
        // entry entirely (mirrors the `fields` builder's `None => continue`).
        if formatted.is_empty() {
            continue;
        }
        map.insert(field_name.to_string(), Value::Array(formatted));
    }
    if map.is_empty() {
        return None;
    }
    Some(map)
}

fn reformat_docvalue(v: &Value, fmt: &str) -> Value {
    let s = match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        _ => return v.clone(),
    };
    // Split off optional sub-second fractional part to support both ms
    // and ns inputs.
    let (head, frac_with_z) = match s.find('.') {
        Some(p) => (&s[..p], &s[p..]),
        None => (s.as_str(), ""),
    };
    let (frac, tz) = if let Some(end) = frac_with_z.find(['Z', '+', '-']) {
        (&frac_with_z[..end], &frac_with_z[end..])
    } else {
        (frac_with_z, "")
    };
    match fmt {
        "strict_date_optional_time" | "date_optional_time" => {
            // Truncate sub-second to 3 digits.
            let mut frac_trim = frac.to_string();
            if frac.starts_with('.') && frac.len() > 4 {
                frac_trim = frac[..4].to_string();
            }
            Value::String(format!("{head}{frac_trim}{tz}"))
        }
        "epoch_millis" => {
            // Try parsing as date string then converting to epoch ms,
            // preserving sub-ms fraction as a decimal.
            if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(&s) {
                let ms = dt.timestamp_millis();
                let extra_ns = dt.timestamp_subsec_nanos() % 1_000_000;
                if extra_ns > 0 {
                    return Value::String(format!("{ms}.{:06}", extra_ns));
                }
                return Value::String(ms.to_string());
            }
            v.clone()
        }
        _ => {
            // Generic Java pattern fallback: SSSSSSSSS pads sub-second
            // to 9 digits. Used by strict_date_optional_time_nanos and
            // explicit `uuuu-MM-dd'T'HH:mm:ss.SSSSSSSSSX` patterns.
            if fmt.contains("SSSSSSSSS")
                || fmt == "strict_date_optional_time_nanos"
                || fmt == "date_optional_time_nanos"
            {
                let frac_padded: String = if let Some(rest) = frac.strip_prefix('.') {
                    let mut digits = rest.to_string();
                    while digits.len() < 9 {
                        digits.push('0');
                    }
                    digits.truncate(9);
                    format!(".{digits}")
                } else {
                    ".000000000".to_string()
                };
                return Value::String(format!("{head}{frac_padded}{tz}"));
            }
            v.clone()
        }
    }
}

/// Traverse a dotted-path against a `_source` JSON value.
///
/// Returns the leaf value at `a.b.c` — supports nested objects.  If any
/// segment is missing or a scalar (can't descend further), returns `None`.
/// The full key is tried first (so a literal field named `"a.b"` resolves
/// before walking); otherwise segments are walked one at a time.
/// Convert a `PainlessValue` back to `serde_json::Value` so the
/// HTTP response can serialize it.
fn painless_to_json(v: xerj_engine::painless::PainlessValue) -> Value {
    use xerj_engine::painless::PainlessValue as P;
    match v {
        P::Null => Value::Null,
        P::Bool(b) => Value::Bool(b),
        P::Number(n) => serde_json::Number::from_f64(n)
            .map(Value::Number)
            .unwrap_or(Value::Null),
        P::String(s) => Value::String(s),
        P::Array(a) => Value::Array(a.into_iter().map(painless_to_json).collect()),
        P::Object(o) => Value::Object(o),
        // A function value has no JSON representation — same fail-closed
        // treatment as the equivalent conversion in aggs.rs.
        P::Closure(..) => Value::Null,
    }
}

/// Walk a JSON object segment-by-segment WITHOUT first checking for
/// the literal dotted key at the root. Used by `fields` emit to
/// fetch the "nested" alternate of a path that ALSO has a dotted key
/// at the source root, so we can union the two.
pub(crate) fn get_field_value_via_walk(source: &Value, segs: &[&str]) -> Option<Value> {
    if segs.is_empty() {
        return Some(source.clone());
    }
    fn walk(cur: &Value, segs: &[&str]) -> Option<Value> {
        if segs.is_empty() {
            return Some(cur.clone());
        }
        match cur {
            Value::Object(obj) => {
                let next = obj.get(segs[0])?;
                walk(next, &segs[1..])
            }
            Value::Array(arr) => {
                let mut out = Vec::new();
                for elem in arr {
                    if let Some(v) = walk(elem, segs) {
                        match v {
                            Value::Array(sub) => out.extend(sub),
                            other => out.push(other),
                        }
                    }
                }
                if out.is_empty() {
                    None
                } else {
                    Some(Value::Array(out))
                }
            }
            _ => None,
        }
    }
    walk(source, segs)
}

/// Expand a packed embedding (`xerj:f32:` hex) into the number array
/// `fields` and `docvalue_fields` have always returned. Leaves every other
/// value unchanged, including a vector that is already a number array.
fn expand_packed_embedding_value(mut value: Value) -> Value {
    xerj_common::packed_f32::expand_packed_f32_values(&mut value);
    value
}

pub(crate) fn get_source_value_by_path(source: &Value, path: &str) -> Option<Value> {
    if let Some(v) = source.get(path) {
        return Some(v.clone());
    }
    if !path.contains('.') {
        return None;
    }
    fn walk(cur: &Value, segs: &[&str]) -> Option<Value> {
        if segs.is_empty() {
            return Some(cur.clone());
        }
        let head = segs[0];
        let tail = &segs[1..];
        match cur {
            Value::Object(obj) => {
                if let Some(next) = obj.get(head) {
                    walk(next, tail)
                } else {
                    // Support dotted-key variants stored at this level
                    // for subobjects:false mappings.
                    let dotted = segs.join(".");
                    obj.get(&dotted).cloned()
                }
            }
            Value::Array(arr) => {
                // Nested field array: walk each element and return a
                // flat list of leaf values.
                let mut out: Vec<Value> = Vec::new();
                for elem in arr {
                    if let Some(v) = walk(elem, segs) {
                        match v {
                            Value::Array(sub) => out.extend(sub),
                            other => out.push(other),
                        }
                    }
                }
                if out.is_empty() {
                    None
                } else {
                    Some(Value::Array(out))
                }
            }
            _ => None,
        }
    }
    let segs: Vec<&str> = path.split('.').collect();
    walk(source, &segs)
}

/// Build inner_hits for a nested query.
///
/// For now we return the full document source as a single inner hit per nested field.
/// The nested_field name is extracted from the query body.
/// Walk an ES index mapping and validate each field in `doc` that declares
/// `ignore_malformed: true`. Fields that fail validation are removed from
/// the source and their names are appended to the `_ignored` array on the
/// doc. Ignores fields with no mapping (they pass through untouched).
///
/// Supports: date (any ES-accepted format string/number), ip (IPv4 or IPv6),
/// integer/long/short/byte, float/double, boolean, geo_point.
/// Walk a NDJSON bulk body alternating (action, source) line pairs,
/// rewriting the source line through `apply_ignore_malformed` against the
/// action's target index. Actions without a source body (delete) pass
/// through unchanged. Each source line's target index is picked from the
/// action's `_index` field, falling back to `default_index`.
/// For a `time_series`-mode index, return the ordered list of dimension
/// field names (those declared `time_series_dimension: true`, falling back
/// to the `routing_path` setting). Returns `None` for any index that is not
/// in time_series mode, so callers leave normal indices untouched.
fn time_series_dimension_fields(state: &AppState, index: &str) -> Option<Vec<String>> {
    let settings = state.engine.index_settings.get(index)?;
    let mode = settings
        .get("index")
        .and_then(|ix| ix.get("mode"))
        .or_else(|| settings.get("mode"))
        .and_then(Value::as_str);
    if mode != Some("time_series") {
        return None;
    }
    // The full `_tsid` is the COMPLETE set of dimension fields: every mapping
    // field (recursively, by dotted path) flagged `time_series_dimension:true`
    // UNIONed with every field named in `index.routing_path`. A BTreeSet keeps
    // them sorted and de-duplicated. Two docs collapse only when ALL of these
    // (plus the timestamp) are identical, so missing a single nested dimension
    // (e.g. `k8s.pod.uid`) would wrongly over-merge distinct series.
    let mut dims: std::collections::BTreeSet<String> = std::collections::BTreeSet::new();

    // 1. Mapping-declared dimensions, recursing into nested `properties`
    //    so nested fields contribute their full dotted path.
    fn collect_dims(
        props: &serde_json::Map<String, Value>,
        prefix: &str,
        out: &mut std::collections::BTreeSet<String>,
    ) {
        for (name, fm) in props {
            let full = if prefix.is_empty() {
                name.clone()
            } else {
                format!("{prefix}.{name}")
            };
            if fm
                .get("time_series_dimension")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            {
                out.insert(full.clone());
            }
            if let Some(sub) = fm.get("properties").and_then(Value::as_object) {
                collect_dims(sub, &full, out);
            }
        }
    }
    if let Some(mapping) = state.engine.index_mappings.get(index) {
        let props = mapping
            .get("mappings")
            .and_then(|m| m.get("properties"))
            .or_else(|| mapping.get("properties"))
            .and_then(Value::as_object);
        if let Some(props_obj) = props {
            collect_dims(props_obj, "", &mut dims);
        }
    }

    // 2. Union in every field named in `index.routing_path` (the dimension
    //    subset used for shard routing). Wildcard patterns are skipped — they
    //    aren't concrete field names to read from the document.
    let rp = settings
        .get("index")
        .and_then(|ix| ix.get("routing_path"))
        .or_else(|| settings.get("routing_path"));
    match rp {
        Some(Value::Array(a)) => {
            for v in a {
                if let Some(s) = v.as_str() {
                    if !s.contains('*') {
                        dims.insert(s.to_string());
                    }
                }
            }
        }
        Some(Value::String(s)) if !s.contains('*') => {
            dims.insert(s.clone());
        }
        _ => {}
    }

    if dims.is_empty() {
        return None;
    }
    Some(dims.into_iter().collect())
}

/// Compute a deterministic `_id` for a time_series (TSDB) document from its
/// routing dimension values plus its `@timestamp`, normalized to epoch
/// millis. Two documents that share the same `_tsid` (dimension values) AND
/// the same instant therefore collapse to the same `_id`, so the later one
/// overwrites the earlier via the normal index/upsert path (ES last-wins).
fn time_series_doc_id(doc: &Value, dim_fields: &[String]) -> Option<String> {
    let obj = doc.as_object()?;
    let ts_ms = match obj.get("@timestamp") {
        Some(Value::String(s)) => parse_iso_to_ms(s)?,
        Some(Value::Number(n)) => n.as_i64()?,
        _ => return None,
    };
    let mut composite = String::new();
    for f in dim_fields {
        composite.push_str(f);
        composite.push('\u{1}');
        // Dimension fields may be nested (e.g. `k8s.pod.uid`); resolve the
        // full dotted path against the source document, not just top-level
        // keys, so every dimension actually contributes to the `_tsid`.
        match get_source_value_by_path(doc, f) {
            Some(Value::String(s)) => composite.push_str(&s),
            Some(Value::Null) | None => {}
            Some(other) => composite.push_str(&other.to_string()),
        }
        composite.push('\u{2}');
    }
    composite.push_str(&ts_ms.to_string());
    // FNV-1a 64-bit — deterministic and stable across restarts.
    let mut hash: u64 = 0xcbf29ce484222325;
    for b in composite.as_bytes() {
        hash ^= *b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    Some(format!("tsid{:016x}", hash))
}

/// Inject a deterministic `_id` into `index`/`create` bulk actions that
/// target a `time_series`-mode index and don't already carry an explicit
/// `_id`. Returns `None` (no allocation, no behavior change) when no action
/// in the batch targets a time_series index, so normal indices are byte-for-
/// byte unaffected.
pub(crate) fn rewrite_bulk_time_series_ids(
    state: &AppState,
    default_index: Option<&str>,
    text: &str,
) -> Option<String> {
    let mut out = String::with_capacity(text.len());
    let mut lines = text.lines();
    let mut changed = false;
    while let Some(action_line) = lines.next() {
        let action_trimmed = action_line.trim();
        if action_trimmed.is_empty() {
            out.push_str(action_line);
            out.push('\n');
            continue;
        }
        let action: Value = match serde_json::from_str(action_trimmed) {
            Ok(v) => v,
            Err(_) => {
                out.push_str(action_line);
                out.push('\n');
                continue;
            }
        };
        let (op, op_body) = match action.as_object().and_then(|o| o.iter().next()) {
            Some((k, v)) => (k.clone(), v.clone()),
            None => {
                out.push_str(action_line);
                out.push('\n');
                continue;
            }
        };
        if op == "delete" {
            // no source body line follows
            out.push_str(action_line);
            out.push('\n');
            continue;
        }
        let source_line = match lines.next() {
            Some(s) => s,
            None => {
                out.push_str(action_line);
                out.push('\n');
                break;
            }
        };
        let idx = op_body
            .get("_index")
            .and_then(Value::as_str)
            .map(String::from)
            .or_else(|| default_index.map(String::from))
            .unwrap_or_default();
        let has_id = op_body.get("_id").is_some();
        let mut emitted_action = action_line.to_string();
        if !has_id && (op == "index" || op == "create") {
            if let Some(dim_fields) = time_series_dimension_fields(state, &idx) {
                if let Ok(src_doc) = serde_json::from_str::<Value>(source_line.trim()) {
                    if let Some(id) = time_series_doc_id(&src_doc, &dim_fields) {
                        if let Some(mut act_obj) = action.as_object().cloned() {
                            if let Some(Value::Object(body_obj)) = act_obj.get_mut(&op) {
                                body_obj.insert("_id".to_string(), Value::String(id));
                                if let Ok(s) = serde_json::to_string(&Value::Object(act_obj)) {
                                    emitted_action = s;
                                    changed = true;
                                }
                            }
                        }
                    }
                }
            }
        }
        out.push_str(&emitted_action);
        out.push('\n');
        out.push_str(source_line);
        out.push('\n');
    }
    if changed {
        Some(out)
    } else {
        None
    }
}

/// True when a stored index mapping contains ANY directive that can make
/// `apply_ignore_malformed` modify a document: a truthy `ignore_malformed`
/// or an `ignore_above` anywhere in the (possibly nested) properties tree.
/// Conservative on false positives (e.g. a user field literally named
/// `ignore_above` still returns true and takes the slow rewrite path);
/// never falsely negative, because `validate_doc_fields` only mutates a
/// doc under one of these two directives.
pub(crate) fn mapping_has_ignore_directives(mapping: &Value) -> bool {
    match mapping {
        Value::Object(m) => {
            if m.get("ignore_malformed")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            {
                return true;
            }
            if m.contains_key("ignore_above") {
                return true;
            }
            m.values().any(mapping_has_ignore_directives)
        }
        Value::Array(arr) => arr.iter().any(mapping_has_ignore_directives),
        _ => false,
    }
}

pub(crate) fn rewrite_bulk_ignore_malformed(
    state: &AppState,
    default_index: Option<&str>,
    text: &str,
) -> String {
    let mut out = String::with_capacity(text.len());
    let mut lines = text.lines().peekable();
    while let Some(action_line) = lines.next() {
        out.push_str(action_line);
        out.push('\n');
        let action_trimmed = action_line.trim();
        if action_trimmed.is_empty() {
            continue;
        }
        let action: Value = match serde_json::from_str(action_trimmed) {
            Ok(v) => v,
            Err(_) => continue,
        };
        // Determine if this action has a source body on the next line.
        let (op, op_body) = match action.as_object().and_then(|o| o.iter().next()) {
            Some((k, v)) => (k.clone(), v.clone()),
            None => continue,
        };
        if op == "delete" {
            continue;
        } // no source body
        let Some(source_line) = lines.next() else {
            break;
        };
        let trimmed = source_line.trim();
        if trimmed.is_empty() {
            out.push_str(source_line);
            out.push('\n');
            continue;
        }
        let idx = op_body
            .get("_index")
            .and_then(Value::as_str)
            .map(String::from)
            .or_else(|| default_index.map(String::from))
            .unwrap_or_default();
        // update actions wrap doc under `doc`: only rewrite when present.
        let rewritten: String = if op == "update" {
            match serde_json::from_str::<Value>(trimmed) {
                Ok(Value::Object(mut outer)) => {
                    if let Some(Value::Object(inner)) = outer.remove("doc") {
                        let rewritten_doc =
                            apply_ignore_malformed(state, &idx, Value::Object(inner));
                        outer.insert("doc".to_string(), rewritten_doc);
                        serde_json::to_string(&Value::Object(outer))
                            .unwrap_or_else(|_| source_line.to_string())
                    } else {
                        serde_json::to_string(&Value::Object(outer))
                            .unwrap_or_else(|_| source_line.to_string())
                    }
                }
                _ => source_line.to_string(),
            }
        } else {
            match serde_json::from_str::<Value>(trimmed) {
                Ok(doc) => {
                    let rewritten_doc = apply_ignore_malformed(state, &idx, doc);
                    serde_json::to_string(&rewritten_doc)
                        .unwrap_or_else(|_| source_line.to_string())
                }
                Err(_) => source_line.to_string(),
            }
        };
        out.push_str(&rewritten);
        out.push('\n');
    }
    out
}

/// The 400 envelope ES sends when a document cannot be parsed against the
/// mapping — the same shape the range/`copy_to` rejection above emits, with
/// the specific `caused_by` sentence ES attaches underneath.
fn document_parsing_error(reason: &str, caused_by: &str) -> Response {
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "document_parsing_exception", "reason": reason }],
                "type": "document_parsing_exception",
                "reason": reason,
                "caused_by": { "type": "illegal_argument_exception", "reason": caused_by }
            },
            "status": 400
        })),
    )
        .into_response()
}

/// Enforce the declared type of every numeric/boolean field on a single-doc
/// write (issue #781).
///
/// Returns the document with ES's coercions applied (`1.9` → `1` in an
/// `integer` field, `"5"` → `5`, `"true"` → `true`), or the 400
/// `document_parsing_exception` ES answers for a value no coercion can
/// rescue — an unparseable string, an out-of-range integer, an object where a
/// number belongs, `"yes"` in a boolean.
///
/// The rules live in [`xerj_common::field_coercion`], shared with the
/// per-item `_bulk` loop in `xerj_engine::bulk`, so the two write paths cannot
/// drift apart the way the date validators once did.
pub(crate) fn enforce_field_types(
    state: &AppState,
    index: &str,
    doc_id: &str,
    doc: Value,
) -> Result<Value, Response> {
    let Some(mapping) = state.engine.index_mappings.get(index).map(|v| v.clone()) else {
        return Ok(doc);
    };
    // Borrow the properties out of the cloned blob rather than cloning them
    // again — one clone per write is what `apply_ignore_malformed` already
    // pays to keep the DashMap shard lock off the coercion walk.
    let Some(props) = xerj_common::field_coercion::mapping_properties(&mapping) else {
        return Ok(doc);
    };
    let mut obj = match doc {
        Value::Object(o) => o,
        other => return Ok(other),
    };
    match xerj_common::field_coercion::coerce_document(&mut obj, props) {
        Ok(_) => Ok(Value::Object(obj)),
        Err(bad) => Err(document_parsing_error(&bad.reason(doc_id), &bad.detail)),
    }
}

pub(crate) fn apply_ignore_malformed(state: &AppState, index: &str, doc: Value) -> Value {
    let Some(mapping) = state.engine.index_mappings.get(index).map(|v| v.clone()) else {
        return doc;
    };
    let Some(mut obj) = doc.as_object().cloned() else {
        return doc;
    };
    let mut ignored: Vec<String> = Vec::new();
    let mut ignored_values: serde_json::Map<String, Value> = serde_json::Map::new();
    let props = mapping
        .get("mappings")
        .and_then(|m| m.get("properties"))
        .or_else(|| mapping.get("properties"))
        .and_then(Value::as_object);
    if let Some(props_obj) = props {
        validate_doc_fields("", &mut obj, props_obj, &mut ignored, &mut ignored_values);
    }
    if !ignored.is_empty() {
        ignored.sort();
        ignored.dedup();
        obj.insert(
            "_ignored".to_string(),
            Value::Array(ignored.into_iter().map(Value::String).collect()),
        );
    }
    if !ignored_values.is_empty() {
        // Stash the original malformed values under an internal sentinel
        // key; the hit renderer promotes this to `ignored_field_values`
        // and strips it from the returned `_source`.
        obj.insert(
            "__xy_ignored_values__".to_string(),
            Value::Object(ignored_values),
        );
    }
    Value::Object(obj)
}

fn validate_doc_fields(
    prefix: &str,
    doc: &mut serde_json::Map<String, Value>,
    props: &serde_json::Map<String, Value>,
    ignored: &mut Vec<String>,
    ignored_values: &mut serde_json::Map<String, Value>,
) {
    let keys: Vec<String> = doc.keys().cloned().collect();
    for field in keys {
        if field == "_ignored" {
            continue;
        }
        let full_name = if prefix.is_empty() {
            field.clone()
        } else {
            format!("{}.{}", prefix, field)
        };
        let Some(field_map) = props.get(&field) else {
            continue;
        };
        let ftype = field_map.get("type").and_then(Value::as_str).unwrap_or("");
        let ignore_malformed = field_map
            .get("ignore_malformed")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let ignore_above = field_map.get("ignore_above").and_then(Value::as_u64);

        if ftype == "object" || ftype == "nested" {
            if let Some(child_props) = field_map.get("properties").and_then(Value::as_object) {
                if let Some(Value::Object(child)) = doc.get_mut(&field) {
                    let mut child_ignored: Vec<String> = Vec::new();
                    validate_doc_fields(
                        &full_name,
                        child,
                        child_props,
                        &mut child_ignored,
                        ignored_values,
                    );
                    ignored.extend(child_ignored);
                }
            }
            continue;
        }

        let value = match doc.get(&field).cloned() {
            Some(v) => v,
            None => continue,
        };
        // Keyword ignore_above: strings longer than N are not indexed
        // for search, but ES keeps the original value in `_source` —
        // synthetic source mode reconstructs it via the `_ignored_fields`
        // store. We track the oversize in `_ignored` but leave the
        // source intact so GET/search fetches return the full value.
        if ftype == "keyword" {
            if let Some(max) = ignore_above {
                let (_retained, had_oversized) = filter_keyword_length(&value, max as usize);
                if had_oversized {
                    ignored.push(full_name.clone());
                }
            }
            continue;
        }

        if !ignore_malformed {
            continue;
        }

        // When a date field declares an explicit `format`, validate using
        // ONLY that format (or the aliases ES treats interchangeably for
        // it). Absent that, accept any of the common date forms.
        let declared_format = field_map.get("format").and_then(Value::as_str);
        let valid_value = |v: &Value| -> bool {
            if ftype == "date" || ftype == "date_nanos" {
                if let Some(fmt) = declared_format {
                    return is_date_value_valid_with_format(v, fmt);
                }
            }
            is_field_value_valid(ftype, v)
        };

        // ES treats an empty string for a numeric or boolean field as a
        // "no value": the field is simply not indexed for that doc and is
        // NOT recorded in `_ignored` (unlike a genuinely malformed value).
        // This does NOT apply to ip/date/geo_point, where an empty string is
        // malformed.
        let is_no_value = |v: &Value| -> bool {
            matches!(v, Value::String(s) if s.is_empty())
                && matches!(
                    ftype,
                    "integer"
                        | "long"
                        | "short"
                        | "byte"
                        | "float"
                        | "double"
                        | "half_float"
                        | "scaled_float"
                        | "boolean"
                )
        };

        // geo_point treats an array as a single [lat, lon] value, not as
        // a multi-valued field of per-element values — reject the whole
        // field if the pair is malformed.
        if ftype == "geo_point" {
            if !is_field_value_valid(ftype, &value) {
                ignored.push(full_name.clone());
                ignored_values
                    .entry(full_name.clone())
                    .or_insert_with(|| Value::Array(vec![]))
                    .as_array_mut()
                    .unwrap()
                    .push(value.clone());
                doc.remove(&field);
            }
            continue;
        }

        // For all other field types, per-element validation: keep valid
        // entries, drop invalid ones, and mark the field as ignored only
        // when SOMETHING was dropped.
        match &value {
            Value::Array(arr) => {
                let mut kept: Vec<Value> = Vec::with_capacity(arr.len());
                let mut dropped_any = false;
                let mut dropped_vals: Vec<Value> = Vec::new();
                for v in arr {
                    if is_no_value(v) {
                        // no-value element: drop silently, not ignored.
                        continue;
                    }
                    if valid_value(v) {
                        kept.push(v.clone());
                    } else {
                        dropped_any = true;
                        dropped_vals.push(v.clone());
                    }
                }
                if dropped_any {
                    ignored.push(full_name.clone());
                    let entry = ignored_values
                        .entry(full_name.clone())
                        .or_insert_with(|| Value::Array(vec![]));
                    if let Some(arr) = entry.as_array_mut() {
                        arr.extend(dropped_vals);
                    }
                    if kept.is_empty() {
                        doc.remove(&field);
                    } else {
                        doc.insert(field.clone(), Value::Array(kept));
                    }
                }
            }
            other => {
                if is_no_value(other) {
                    // no-value (empty string for numeric/boolean): drop the
                    // field, do NOT record it in `_ignored`.
                    doc.remove(&field);
                } else if !valid_value(other) {
                    ignored.push(full_name.clone());
                    let entry = ignored_values
                        .entry(full_name.clone())
                        .or_insert_with(|| Value::Array(vec![]));
                    if let Some(arr) = entry.as_array_mut() {
                        arr.push(other.clone());
                    }
                    doc.remove(&field);
                }
            }
        }
    }
}

fn filter_keyword_length(val: &Value, max: usize) -> (Value, bool) {
    match val {
        Value::String(s) => {
            if s.chars().count() > max {
                (Value::Null, true)
            } else {
                (val.clone(), false)
            }
        }
        Value::Array(arr) => {
            let mut out = Vec::with_capacity(arr.len());
            let mut any_dropped = false;
            for v in arr {
                match v {
                    Value::String(s) if s.chars().count() > max => any_dropped = true,
                    _ => out.push(v.clone()),
                }
            }
            (
                if out.is_empty() {
                    Value::Null
                } else {
                    Value::Array(out)
                },
                any_dropped,
            )
        }
        _ => (val.clone(), false),
    }
}

/// Check whether `v` parses under the declared ES date `fmt`.
///
/// Thin alias for [`xerj_query::dates::date_value_valid_with_format`] — the
/// SINGLE ingest-time date predicate, shared with the `ignore_malformed:
/// false` rejection path in `xerj_engine::bulk`. It must stay a delegation:
/// when these two paths had separate implementations, the strict one was the
/// laxer of the pair, so turning `ignore_malformed` off made the engine
/// accept *more*.
///
/// The compiled format is memoised on the format string, so a bulk of N docs
/// compiles a field's declared format once rather than N times.
fn is_date_value_valid_with_format(v: &Value, fmt: &str) -> bool {
    xerj_query::dates::date_value_valid_with_format(v, fmt)
}

#[cfg(test)]
mod ignore_malformed_date_format_tests {
    //! Regression coverage for a real bug found live against OpenSearch's
    //! UBI sample dashboards: `opensearch_dashboards_sample_ubi_events` maps
    //! `timestamp` as `{"type":"date","format":"strict_date_time",
    //! "ignore_malformed":true}`. Every document with a valid ISO timestamp
    //! string was wrongly marked `_ignored` (the named format was matched as
    //! literal text instead of being resolved to its real pattern), while
    //! every document with a bare epoch-millis number was wrongly accepted
    //! (any format treated a JSON number as valid) — exactly backwards from
    //! real behavior. Confirmed by replaying the same mapping and documents
    //! against a real OpenSearch 2.11.1 node.
    use super::*;

    #[test]
    fn valid_iso_string_under_named_strict_format_is_not_ignored() {
        assert!(is_date_value_valid_with_format(
            &json!("2024-12-10T00:50:30.466Z"),
            "strict_date_time"
        ));
    }

    #[test]
    fn bare_epoch_millis_number_under_non_epoch_format_is_ignored() {
        assert!(!is_date_value_valid_with_format(
            &json!(1717527762025i64),
            "strict_date_time"
        ));
    }

    #[test]
    fn bare_epoch_millis_number_is_valid_when_format_allows_it() {
        assert!(is_date_value_valid_with_format(
            &json!(1717527762025i64),
            "strict_date_time||epoch_millis"
        ));
    }

    #[test]
    fn number_under_numeric_shaped_non_epoch_format_is_valid() {
        // basic_date is `yyyyMMdd`; ES stringifies a JSON number before
        // formatting, so 20240101 must be accepted here too — this used to
        // be silently dropped by gating numeric input on epoch formats.
        assert!(is_date_value_valid_with_format(
            &json!(20240101),
            "basic_date"
        ));
    }

    #[test]
    fn real_named_formats_are_not_in_the_fail_closed_bucket() {
        // The regression this replaces: `ordinal_date` and 27 other REAL ES
        // formats were unresolvable, so fail-closed dropped every one of
        // their values under `ignore_malformed: true` — including JSON
        // numbers, which the previous release accepted. They resolve now,
        // and validate for real.
        assert!(is_date_value_valid_with_format(
            &json!("2024-001"),
            "ordinal_date"
        ));
        assert!(!is_date_value_valid_with_format(
            &json!("literally anything"),
            "ordinal_date"
        ));
        // The number shape that main accepted and the fix dropped.
        assert!(is_date_value_valid_with_format(
            &json!(2024001),
            "basic_ordinal_date"
        ));
        assert!(is_date_value_valid_with_format(&json!(12), "hour"));
        assert!(is_date_value_valid_with_format(&json!(2024), "weekyear"));
        assert!(is_date_value_valid_with_format(
            &json!("121030.123Z"),
            "basic_time"
        ));
    }

    #[test]
    fn a_format_elasticsearch_rejects_still_fails_closed() {
        // Fail-closed survives for what it was actually for: a format that
        // is neither a named ES format nor a valid java.time pattern (ES
        // rejects `banana` with `Unknown pattern letter: b` at mapping
        // creation, so no document can legitimately arrive under one).
        assert!(!is_date_value_valid_with_format(
            &json!("2024-01-01"),
            "banana"
        ));
        assert!(!is_date_value_valid_with_format(
            &json!(1717527762025i64),
            "banana"
        ));
    }

    #[test]
    fn no_es_named_format_drops_data_under_ignore_malformed() {
        // Field-level guard on the whole shipped ES format set: a name that
        // stops resolving silently empties the field, so assert none of them
        // reject a value they should accept by construction — every format
        // accepts JSON null, and no format may reject everything.
        for name in xerj_query::dates::ES_NAMED_FORMATS {
            assert!(
                is_date_value_valid_with_format(&Value::Null, name),
                "`{name}` treats null as malformed"
            );
            assert!(
                xerj_query::dates::compile_formats(name).is_ok(),
                "`{name}` is unresolvable — every value of a field declaring \
                 it would be dropped from _source under ignore_malformed"
            );
        }
    }

    #[tokio::test]
    async fn apply_ignore_malformed_end_to_end_matches_ubi_events_mapping() {
        let dir = tempfile::tempdir().expect("tempdir").keep();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        let state = AppState::new(config, engine, metrics);

        state.engine.index_mappings.insert(
            "ubi-repro".to_string(),
            json!({
                "properties": {
                    "timestamp": {
                        "type": "date",
                        "format": "strict_date_time",
                        "ignore_malformed": true
                    },
                    "action_name": {"type": "keyword"}
                }
            }),
        );

        // A "click" event: valid ISO timestamp string — must NOT be ignored.
        let click_doc = apply_ignore_malformed(
            &state,
            "ubi-repro",
            json!({"timestamp": ["2024-12-10T00:50:30.466Z"], "action_name": "click"}),
        );
        assert!(
            click_doc.get("_ignored").is_none(),
            "valid ISO timestamp wrongly ignored: {click_doc:?}"
        );

        // An "on_search" event: bare epoch-millis number — MUST be ignored,
        // since strict_date_time alone doesn't accept numeric input.
        let on_search_doc = apply_ignore_malformed(
            &state,
            "ubi-repro",
            json!({"timestamp": 1717527762025i64, "action_name": "on_search"}),
        );
        assert_eq!(
            on_search_doc.get("_ignored"),
            Some(&json!(["timestamp"])),
            "epoch-millis number under a non-epoch format should be ignored: {on_search_doc:?}"
        );
    }
}

fn is_field_value_valid(ftype: &str, v: &Value) -> bool {
    match ftype {
        "date" | "date_nanos" => match v {
            Value::Number(_) => true,
            Value::String(s) => {
                chrono::DateTime::parse_from_rfc3339(s).is_ok()
                    || chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S").is_ok()
                    || chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S").is_ok()
                    || chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d").is_ok()
                    || chrono::NaiveDate::parse_from_str(s, "%d-%m-%Y").is_ok()
                    || chrono::NaiveDate::parse_from_str(s, "%Y/%m/%d").is_ok()
            }
            _ => false,
        },
        "ip" => match v {
            Value::String(s) => s.parse::<std::net::IpAddr>().is_ok(),
            _ => false,
        },
        "integer" | "long" | "short" | "byte" => match v {
            Value::Number(n) => n.is_i64() || n.as_f64().map(|f| f.fract() == 0.0).unwrap_or(false),
            Value::String(s) => {
                s.parse::<i64>().is_ok()
                    || s.parse::<f64>().map(|f| f.fract() == 0.0).unwrap_or(false)
            }
            _ => false,
        },
        "float" | "double" | "half_float" | "scaled_float" => match v {
            Value::Number(_) => true,
            Value::String(s) => s.parse::<f64>().is_ok(),
            _ => false,
        },
        "boolean" => {
            matches!(v, Value::Bool(_))
                || match v {
                    Value::String(s) => matches!(s.as_str(), "true" | "false"),
                    _ => false,
                }
        }
        "geo_point" => {
            // Parse a number OR number-shaped string ("20.12") to f64.
            let parse_num = |x: &Value| -> Option<f64> {
                match x {
                    Value::Number(n) => n.as_f64(),
                    Value::String(s) => s.trim().parse::<f64>().ok(),
                    _ => None,
                }
            };
            // ES/Lucene NORMALIZES longitude by wrapping it into [-180, 180]
            // (so e.g. 182.22 -> -177.78 is VALID, not malformed); latitude is
            // not wrapped and must be in [-90, 90].
            let valid_lat = |lat: f64| lat.is_finite() && (-90.0..=90.0).contains(&lat);
            let valid_lon = |lon: f64| lon.is_finite();
            // "lat,lon" string form (latitude first), or a WKT POINT literal.
            let is_latlon_string = |s: &str| -> bool {
                if s.starts_with("POINT") {
                    return true;
                }
                if let Some((a, b)) = s.split_once(',') {
                    if let (Ok(lat), Ok(lon)) = (a.trim().parse::<f64>(), b.trim().parse::<f64>()) {
                        return valid_lat(lat) && valid_lon(lon);
                    }
                }
                false
            };
            match v {
                Value::Object(o) => {
                    match (
                        parse_num(o.get("lat").unwrap_or(&Value::Null)),
                        parse_num(o.get("lon").unwrap_or(&Value::Null)),
                    ) {
                        (Some(lat), Some(lon)) => valid_lat(lat) && valid_lon(lon),
                        _ => false,
                    }
                }
                // GeoJSON / ES array form is [lon, lat].
                Value::Array(a) if a.len() == 2 => match (parse_num(&a[0]), parse_num(&a[1])) {
                    (Some(lon), Some(lat)) => valid_lon(lon) && valid_lat(lat),
                    _ => false,
                },
                // A single-element array is NOT a valid geo_point in ES — the
                // array form must be exactly [lon, lat]. So `["45.33, 8.20"]`
                // is malformed (whereas the bare string "45.33, 8.20" is fine).
                Value::String(s) => is_latlon_string(s),
                _ => false,
            }
        }
        _ => true,
    }
}

pub(crate) fn build_inner_hits(
    source: &Value,
    doc_id: &str,
    index: &str,
    inner_hits_config: &Value,
) -> Value {
    if inner_hits_config.is_null() {
        return Value::Null;
    }
    // inner_hits_config is a JSON object: keys are the nested path names.
    let obj = match inner_hits_config.as_object() {
        Some(o) if !o.is_empty() => o,
        _ => {
            // No named inner_hits path — return empty.
            return Value::Object(serde_json::Map::new());
        }
    };

    let mut result = serde_json::Map::new();
    for (path, opts) in obj {
        // Pull options from the inner_hits spec.
        let size = opts
            .get("size")
            .and_then(Value::as_u64)
            .map(|n| n as usize)
            .unwrap_or(3);
        let from = opts
            .get("from")
            .and_then(Value::as_u64)
            .map(|n| n as usize)
            .unwrap_or(0);
        let source_enabled = !matches!(opts.get("_source"), Some(Value::Bool(false)));
        // Field expressions: ES accepts `[ "a.b", "c" ]` OR the newer
        // `[ { field: "a.b" }, ... ]` shape.
        let field_exprs: Vec<String> = opts
            .get("fields")
            .and_then(Value::as_array)
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| {
                        if let Some(s) = v.as_str() {
                            Some(s.to_string())
                        } else if let Some(o) = v.as_object() {
                            o.get("field").and_then(Value::as_str).map(String::from)
                        } else {
                            None
                        }
                    })
                    .collect()
            })
            .unwrap_or_default();

        // Resolve the nested path (may be dotted) and emit one inner
        // hit per element of the nested array.
        let nested_raw = get_source_value_by_path(source, path).unwrap_or(Value::Null);
        let elements: Vec<Value> = match nested_raw {
            Value::Array(arr) => arr,
            Value::Object(_) => vec![nested_raw],
            _ => Vec::new(),
        };
        let total_elements = elements.len() as u64;
        let sliced: Vec<(usize, Value)> = elements
            .into_iter()
            .enumerate()
            .skip(from)
            .take(size)
            .collect();

        let inner_hits: Vec<Value> = sliced
            .into_iter()
            .map(|(offset, elem)| {
                let mut hit = serde_json::Map::new();
                hit.insert("_index".to_string(), Value::String(index.to_string()));
                hit.insert("_id".to_string(), Value::String(doc_id.to_string()));
                hit.insert(
                    "_nested".to_string(),
                    json!({ "field": path, "offset": offset }),
                );
                hit.insert("_score".to_string(), json!(1.0));
                if source_enabled {
                    hit.insert("_source".to_string(), elem.clone());
                }
                if !field_exprs.is_empty() {
                    // Render each field expression as part of a nested
                    // field map. For expressions like "<path>.<sub>",
                    // the result nests at <path>[0].<sub> — mirrors ES
                    // inner_hits fields format.
                    let mut fields_obj: serde_json::Map<String, Value> = serde_json::Map::new();
                    for expr in &field_exprs {
                        if let Some(stripped) = expr.strip_prefix(&format!("{}.", path)) {
                            // Pull stripped field from this nested element.
                            let val = elem.get(stripped).cloned();
                            if let Some(v) = val {
                                let as_array = match v {
                                    Value::Array(a) => Value::Array(a),
                                    other => Value::Array(vec![other]),
                                };
                                // Nest under `<path>[0].<stripped>`.
                                let inner_slot = json!({ stripped: as_array });
                                fields_obj
                                    .entry(path.clone())
                                    .or_insert_with(|| Value::Array(Vec::new()))
                                    .as_array_mut()
                                    .unwrap()
                                    .push(inner_slot);
                            }
                        } else {
                            // Non-nested field — resolve against the
                            // element directly.
                            if let Some(v) = elem.get(expr).cloned() {
                                let as_array = match v {
                                    Value::Array(a) => Value::Array(a),
                                    other => Value::Array(vec![other]),
                                };
                                fields_obj.insert(expr.clone(), as_array);
                            }
                        }
                    }
                    if !fields_obj.is_empty() {
                        hit.insert("fields".to_string(), Value::Object(fields_obj));
                    }
                }
                Value::Object(hit)
            })
            .collect();
        result.insert(
            path.clone(),
            json!({
                "hits": {
                    "total": { "value": total_elements, "relation": "eq" },
                    "max_score": if total_elements > 0 { json!(1.0) } else { Value::Null },
                    "hits": inner_hits
                }
            }),
        );
    }
    Value::Object(result)
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_async_search  — start async search (executed synchronously)
// GET  /_async_search/{id}     — retrieve stored result
// DELETE /_async_search/{id}   — delete stored result
// ─────────────────────────────────────────────────────────────────────────────

/// Query params for `_async_search` submit/get. Only `keep_alive` changes
/// behavior (result TTL); `wait_for_completion_timeout` and
/// `keep_on_completion` are accepted for wire compatibility — searches run
/// synchronously here, so every response is already complete.
#[derive(Debug, Default, Deserialize)]
pub struct AsyncSearchParams {
    #[serde(default)]
    pub keep_alive: Option<String>,
    #[serde(default)]
    pub wait_for_completion_timeout: Option<String>,
    #[serde(default)]
    pub keep_on_completion: Option<String>,
}

pub async fn async_search_submit(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Query(params): Query<AsyncSearchParams>,
    body: OptionalJson<EsSearchBody>,
) -> impl IntoResponse {
    let mut body = body.into_or_default();
    // An async search stores its response and hands it back later; a stored
    // rerank would also be a stored third-party call nobody is waiting on.
    // Refused rather than dropped — and a stored `judge` pass is refused too:
    // the caller asked for judged, pruned hits and would get the stored
    // engine's order instead.
    if body.rerank.is_some() || body.judge.is_some() {
        return (
            StatusCode::BAD_REQUEST,
            Json(if body.rerank.is_some() {
                crate::rerank_stage::unsupported_on("_async_search")
            } else {
                crate::judge_stage::unsupported_on("_async_search")
            }),
        )
            .into_response();
    }
    // ES 8.x default: absent track_total_hits → totals tracked up to 10,000
    // only ({"value":10000,"relation":"gte"} beyond), same as `_search`.
    if body.track_total_hits.is_none() {
        body.track_total_hits = Some(json!(10_000));
    }

    // RC4 blocker 11: stored async results are TTL'd AND capped. Sweep
    // expired entries first so the cap counts only live results, then
    // refuse (429) rather than pinning yet another response JSON forever.
    state.engine.sweep_expired_async_searches();
    let async_cap = state.config.search_context.max_open_async_searches;
    if state.engine.async_searches.len() >= async_cap {
        return too_many_async_searches(async_cap);
    }

    // Wildcard/comma/`_all` specs resolve to every matching existing index
    // (no auto-create — an empty wildcard match is a legitimate empty
    // result, not a reason to create an index literally named e.g.
    // `logs-*`). A single literal name keeps the pre-existing
    // `get_or_create_index` behavior unchanged, since that's a distinct,
    // deliberate convenience this fix isn't touching.
    let is_selector = index == "_all" || index.contains('*') || index.contains(',');
    let handles: Vec<(String, std::sync::Arc<xerj_engine::Index>)> = if is_selector {
        match resolve_indices_for_op(&state, &index).await {
            Ok(h) => h,
            Err(e) => return ApiError::new(e).into_response(),
        }
    } else {
        match state.engine.get_or_create_index(&index) {
            Ok(i) => vec![(index.clone(), i)],
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    };

    let aggs_value = body.aggs.clone().or_else(|| body.aggregations.clone());
    let req = match build_search_request(&body, aggs_value) {
        Ok(r) => r,
        Err(e) => return ApiError::new(e).into_response(),
    };

    let started = Instant::now();
    // Minimal cross-index merge (score-descending hits, summed totals) —
    // same scope decision as `search_template`'s fix: replicating
    // `search()`'s full multi-index machinery here is disproportionate to
    // a wildcard-resolution fix. Aggregations are NOT merged across
    // multiple indices (see below) — that's a real, documented gap, not a
    // silent-wrong-answer: previously a wildcard/comma spec failed
    // outright (400/404), so "hits work, aggs omitted for multi-index" is
    // strictly better, not a regression for anyone who could reach this
    // code path before.
    let mut merged_hits: Vec<(String, xerj_query::executor::Hit)> = Vec::new();
    let mut total_value: u64 = 0;
    let mut any_gte = false;
    let mut timed_out = false;
    let mut single_index_aggs: Option<Value> = None;
    for (name, idx) in &handles {
        match idx.search(&req).await {
            Ok(result) => {
                if let Some(reason) = &result.script_failure {
                    return script_limit_response(reason);
                }
                total_value += result.total.value;
                any_gte = any_gte
                    || result.total.relation == xerj_query::executor::TotalHitsRelation::Gte;
                timed_out = timed_out || result.timed_out;
                if handles.len() == 1 {
                    single_index_aggs = result.aggs;
                }
                merged_hits.extend(result.hits.into_iter().map(|h| (name.clone(), h)));
            }
            Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
        }
    }
    merged_hits.sort_by(|(_, a), (_, b)| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    merged_hits.truncate(req.size);
    let took_ms = started.elapsed().as_millis() as u64;

    // TTL (RC4 blocker 11): honor the request's `keep_alive` (pre-rc.4 it
    // was parsed nowhere and every result silently got 5 minutes), fall
    // back to the configured default, cap at the configured max. The
    // expiry is enforced on GET and by the background sweeper.
    let sc_cfg = &state.config.search_context;
    let keep_alive_secs = params
        .keep_alive
        .as_deref()
        .and_then(parse_keep_alive_to_secs)
        .unwrap_or(sc_cfg.async_default_keep_alive_secs)
        .min(sc_cfg.async_max_keep_alive_secs);
    let now_ms = chrono::Utc::now().timestamp_millis();
    let exp_ms = now_ms + (keep_alive_secs as i64) * 1000;

    // Build a normal search response body to embed.
    let max_score = merged_hits.first().map(|(_, h)| h.score as f64);
    let n = handles.len() as u32;
    let hits: Vec<Value> = merged_hits
        .into_iter()
        .map(|(hit_index, h)| {
            json!({
                "_index": hit_index,
                "_id": h.id,
                "_score": h.score,
                "_source": h.source,
            })
        })
        .collect();
    let mut search_response = json!({
        "took": took_ms,
        "timed_out": timed_out,
        "_shards": { "total": n, "successful": n, "skipped": 0, "failed": 0 },
        "hits": {
            "total": {
                "value": total_value,
                "relation": if any_gte { "gte" } else { "eq" },
            },
            "max_score": max_score,
            "hits": hits,
        }
    });
    // Include aggregations in the completed payload, same shape as `_search`
    // (internal tracking + type tags stripped) — but only when exactly one
    // index was searched; see the merge comment above for why multi-index
    // aggregations are omitted rather than merged.
    if let Some(mut aggs) = single_index_aggs {
        strip_internal_tracking(&mut aggs);
        search_response["aggregations"] = strip_type_tags(aggs);
    }

    let async_id = Uuid::new_v4().to_string();
    let stored = json!({
        "id": async_id,
        "is_partial": false,
        "is_running": false,
        "start_time_in_millis": now_ms,
        "expiration_time_in_millis": exp_ms,
        "response": search_response
    });

    state
        .engine
        .async_searches
        .insert(async_id.clone(), stored.clone());

    Json(stored).into_response()
}

pub async fn async_search_get(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(params): Query<AsyncSearchParams>,
) -> impl IntoResponse {
    let now_ms = chrono::Utc::now().timestamp_millis();
    match state.engine.async_searches.get_mut(&id) {
        Some(mut entry) => {
            // Expiry enforcement on read (RC4 blocker 11): a result past
            // its keep-alive is gone even before the sweeper collects it.
            let expired = entry
                .get("expiration_time_in_millis")
                .and_then(Value::as_i64)
                .map(|exp| exp <= now_ms)
                .unwrap_or(true);
            if expired {
                drop(entry); // release the DashMap shard guard before remove
                state.engine.async_searches.remove(&id);
                return async_search_not_found(&id);
            }
            // `GET …?keep_alive=…` extends the stored result's TTL (ES
            // semantics), capped like submit.
            if let Some(ka_secs) = params
                .keep_alive
                .as_deref()
                .and_then(parse_keep_alive_to_secs)
            {
                let capped = ka_secs.min(state.config.search_context.async_max_keep_alive_secs);
                entry["expiration_time_in_millis"] = json!(now_ms + (capped as i64) * 1000);
            }
            Json(entry.clone()).into_response()
        }
        // Unknown id → ES returns 404 resource_not_found, not a 500.
        None => async_search_not_found(&id),
    }
}

pub async fn async_search_delete(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    match state.engine.async_searches.remove(&id) {
        Some(_) => Json(json!({ "acknowledged": true })).into_response(),
        None => async_search_not_found(&id),
    }
}

/// Maximum number of hits a scroll context may snapshot (issue #198).
///
/// xerj scroll is a bounded up-front snapshot, not a segment-walking
/// cursor: the initial search materialises every hit into the context and
/// continuation requests page that Vec. This cap matches the default
/// `index.max_result_window` (10,000), which the engine enforces on
/// `from + size` anyway — a larger snapshot request would be rejected at
/// the engine boundary. A result set that exceeds the cap is REFUSED with
/// [`scroll_window_exceeded`] rather than silently truncated.
///
/// Public because it is a documented compatibility boundary, not an internal
/// tuning knob (issue #370): the published pages that state the cap are
/// checked against this constant by
/// `tests/scroll_snapshot_cap_is_documented.rs`, so changing the number here
/// fails the build until the docs follow.
pub const SCROLL_SNAPSHOT_MAX_HITS: usize = 10_000;

/// ES-shaped 400 for a scroll whose exact result set exceeds the snapshot
/// window (issue #198).
///
/// Before this existed, a scroll over >10k documents returned the first
/// 10k pages and then stopped, indistinguishable from a complete export —
/// the worst possible failure mode on the reindex/backup/migration path
/// scroll exists for. ES never truncates a scroll (it is a true cursor),
/// so there is no ES-native error for this condition; the response
/// mirrors the `illegal_argument_exception` shape of
/// `ResultWindowTooLarge`, which is the closest ES analogue (deep
/// pagination past the window).
fn scroll_window_exceeded(total: u64, cap: usize) -> axum::response::Response {
    let reason = format!(
        "Scroll result set is too large: [{total}] matching documents exceed the scroll \
         snapshot window of [{cap}]. xerj materialises the full scroll snapshot up front \
         and will not return a silently truncated result set. Page with [search_after] on \
         a unique sort key instead, or narrow the query."
    );
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "illegal_argument_exception", "reason": reason }],
                "type": "illegal_argument_exception",
                "reason": reason,
            },
            "status": 400,
        })),
    )
        .into_response()
}

/// ES-shaped 429 for exceeding the open-scroll-contexts cap (RC4
/// blocker 11). Mirrors ES's `search.max_open_scroll_context` rejection
/// text, naming xerj's own setting key.
fn too_many_scroll_contexts(cap: usize) -> axum::response::Response {
    let reason = format!(
        "Trying to create too many scroll contexts. Must be less than or equal to: [{cap}]. \
         This limit can be set by changing the [search_context.max_open_scrolls] setting."
    );
    (
        StatusCode::TOO_MANY_REQUESTS,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "exception", "reason": reason }],
                "type": "exception",
                "reason": reason,
            },
            "status": 429,
        })),
    )
        .into_response()
}

/// ES-shaped 429 for exceeding the stored-async-search cap (RC4 blocker 11).
fn too_many_async_searches(cap: usize) -> axum::response::Response {
    let reason = format!(
        "Trying to store too many async searches. Must be less than or equal to: [{cap}]. \
         This limit can be set by changing the [search_context.max_open_async_searches] \
         setting, or free slots with DELETE /_async_search/<id>."
    );
    (
        StatusCode::TOO_MANY_REQUESTS,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "exception", "reason": reason }],
                "type": "exception",
                "reason": reason,
            },
            "status": 429,
        })),
    )
        .into_response()
}

/// ES-shaped 404 for an unknown async-search id.
fn async_search_not_found(id: &str) -> axum::response::Response {
    let reason = format!("no async search found for id [{id}]");
    (
        StatusCode::NOT_FOUND,
        Json(json!({
            "error": {
                "root_cause": [{ "type": "resource_not_found_exception", "reason": reason }],
                "type": "resource_not_found_exception",
                "reason": reason,
            },
            "status": 404,
        })),
    )
        .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /_sql  — basic SQL query execution
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, serde::Deserialize)]
pub struct SqlQueryBody {
    pub query: String,
    #[serde(default)]
    pub fetch_size: Option<usize>,
}

pub async fn sql_query(
    State(state): State<AppState>,
    Json(body): Json<SqlQueryBody>,
) -> impl IntoResponse {
    use xerj_engine::sql::parse_sql;

    let parsed = match parse_sql(&body.query) {
        Ok(p) => p,
        Err(e) => {
            let err = xerj_common::XerjError::invalid_query(format!("SQL parse error: {}", e));
            return ApiError::new(err).into_response();
        }
    };

    let idx = match state.engine.get_or_create_index(&parsed.index) {
        Ok(i) => i,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    let limit = body.fetch_size.or(parsed.limit).unwrap_or(10);

    let mut req = xerj_query::ast::SearchRequest {
        query: parsed.query,
        size: limit,
        sort: parsed.sort,
        ..Default::default()
    };

    // Set source filter if specific fields requested.
    if !parsed.fields.contains(&"*".to_string()) {
        req.source = xerj_query::ast::SourceFilter::Includes(parsed.fields.clone());
    }

    let result = match idx.search(&req).await {
        Ok(r) => r,
        Err(e) => return ApiError::new(xerj_common::XerjError::from(e)).into_response(),
    };

    // Build column metadata from first hit or requested fields.
    let columns: Vec<Value> = if parsed.fields.contains(&"*".to_string()) {
        // Infer columns from first hit's keys.
        result
            .hits
            .first()
            .and_then(|h| h.source.as_object())
            .map(|obj| {
                obj.keys()
                    .map(|k| json!({"name": k, "type": "text"}))
                    .collect()
            })
            .unwrap_or_default()
    } else {
        parsed
            .fields
            .iter()
            .map(|f| json!({"name": f, "type": "text"}))
            .collect()
    };

    let field_names: Vec<String> = columns
        .iter()
        .filter_map(|c| c.get("name").and_then(Value::as_str).map(String::from))
        .collect();

    let rows: Vec<Value> = result
        .hits
        .iter()
        .map(|h| {
            let row: Vec<Value> = field_names
                .iter()
                .map(|f| h.source.get(f).cloned().unwrap_or(Value::Null))
                .collect();
            Value::Array(row)
        })
        .collect();

    Json(json!({
        "columns": columns,
        "rows": rows
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{index}/_rank_eval
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, serde::Deserialize)]
pub struct RankEvalBody {
    pub requests: Vec<RankEvalRequest>,
    #[serde(default)]
    pub metric: Option<Value>,
}

#[derive(Debug, serde::Deserialize)]
pub struct RankEvalRequest {
    pub id: String,
    pub request: Value,
    #[serde(default)]
    pub ratings: Vec<RankEvalRating>,
}

#[derive(Debug, serde::Deserialize)]
pub struct RankEvalRating {
    #[serde(rename = "_index")]
    pub index: Option<String>,
    #[serde(rename = "_id")]
    pub id: String,
    pub rating: u32,
}

/// Real per-request rank_eval metric score. `ranked` is the graded relevance
/// of each retrieved doc in rank order; `all_ratings` is every rating supplied
/// for the request (used for recall's denominator, nDCG's ideal ordering, and
/// ERR's default max grade). Pure so it can be unit-tested against known values.
fn rank_eval_metric_score(
    metric: &str,
    mparams: &Value,
    ranked: &[u32],
    all_ratings: &[u32],
    k: usize,
    threshold: u32,
    normalize: bool,
) -> f64 {
    match metric {
        "precision" => {
            let rel = ranked.iter().filter(|&&r| r >= threshold).count();
            if ranked.is_empty() {
                0.0
            } else {
                rel as f64 / ranked.len() as f64
            }
        }
        "recall" => {
            let total_rel = all_ratings.iter().filter(|&&r| r >= threshold).count();
            let rel = ranked.iter().filter(|&&r| r >= threshold).count();
            if total_rel == 0 {
                0.0
            } else {
                rel as f64 / total_rel as f64
            }
        }
        // DCG = Σ (2^rating − 1) / log2(rank + 1), rank 1-based.
        // nDCG divides by the ideal DCG (ratings sorted descending, top-k).
        "dcg" => {
            let dcg = |gains: &[u32]| -> f64 {
                gains
                    .iter()
                    .enumerate()
                    .map(|(i, &g)| (2f64.powi(g as i32) - 1.0) / ((i as f64) + 2.0).log2())
                    .sum()
            };
            let raw = dcg(ranked);
            if normalize {
                let mut ideal: Vec<u32> = all_ratings.to_vec();
                ideal.sort_unstable_by(|a, b| b.cmp(a));
                ideal.truncate(k);
                let idcg = dcg(&ideal);
                if idcg > 0.0 {
                    raw / idcg
                } else {
                    0.0
                }
            } else {
                raw
            }
        }
        // Reciprocal rank of the first doc at/above the relevance threshold.
        "mean_reciprocal_rank" => ranked
            .iter()
            .position(|&r| r >= threshold)
            .map(|p| 1.0 / (p as f64 + 1.0))
            .unwrap_or(0.0),
        // ERR = Σ_i (1/i)·(Π_{j<i}(1−R_j))·R_i, R_g = (2^g − 1)/2^max_grade.
        "expected_reciprocal_rank" => {
            let max_grade = mparams
                .get("maximum_relevance")
                .and_then(Value::as_u64)
                .map(|v| v as u32)
                .unwrap_or_else(|| all_ratings.iter().copied().max().unwrap_or(1))
                .max(1);
            let denom = 2f64.powi(max_grade as i32);
            let mut err = 0.0;
            let mut p_stay = 1.0;
            for (i, &g) in ranked.iter().enumerate() {
                let r = (2f64.powi(g as i32) - 1.0) / denom;
                err += p_stay * r / (i as f64 + 1.0);
                p_stay *= 1.0 - r;
            }
            err
        }
        _ => 0.0,
    }
}

#[cfg(test)]
mod rank_eval_metric_tests {
    use super::rank_eval_metric_score;
    use serde_json::json;

    // ranked ratings [3,0,1] retrieved in that order; all ratings [3,0,1].
    // Each metric must produce a DISTINCT, correct value (the bug was that
    // dcg/mrr/err all silently returned precision).
    const RANKED: [u32; 3] = [3, 0, 1];
    const ALL: [u32; 3] = [3, 0, 1];

    fn score(metric: &str, params: serde_json::Value, normalize: bool) -> f64 {
        rank_eval_metric_score(metric, &params, &RANKED, &ALL, 3, 1, normalize)
    }

    #[test]
    fn precision_is_relevant_over_retrieved() {
        assert!((score("precision", json!({}), false) - 2.0 / 3.0).abs() < 1e-9);
    }

    #[test]
    fn recall_is_relevant_retrieved_over_total() {
        assert!((score("recall", json!({}), false) - 1.0).abs() < 1e-9);
    }

    #[test]
    fn dcg_uses_graded_gain_and_log_discount() {
        // 7/log2(2) + 0/log2(3) + 1/log2(4) = 7 + 0 + 0.5
        assert!((score("dcg", json!({}), false) - 7.5).abs() < 1e-9);
    }

    #[test]
    fn ndcg_normalizes_against_ideal() {
        // ideal [3,1,0] → 7 + 1/log2(3) = 7.630930; ndcg = 7.5 / 7.630930
        assert!((score("dcg", json!({}), true) - (7.5 / (7.0 + 1.0 / 3f64.log2()))).abs() < 1e-9);
    }

    #[test]
    fn mrr_is_reciprocal_of_first_relevant_rank() {
        // first rating>=1 is at rank 1 → 1.0
        assert!((score("mean_reciprocal_rank", json!({}), false) - 1.0).abs() < 1e-9);
    }

    #[test]
    fn err_uses_cascade_probabilities() {
        // max_grade 3, denom 8; R=[7/8,0,1/8] → 0.875 + 0 + (1/3)(0.125)(0.125)
        let expected = 0.875 + (1.0 / 3.0) * 0.125 * 0.125;
        assert!(
            (score(
                "expected_reciprocal_rank",
                json!({"maximum_relevance":3}),
                false
            ) - expected)
                .abs()
                < 1e-9
        );
    }

    #[test]
    fn non_precision_metrics_do_not_collapse_to_precision() {
        // The original bug: dcg / nDCG / mrr / err all silently returned the
        // precision value. Each must now differ from precision.
        let precision = score("precision", json!({}), false);
        for (name, val) in [
            ("dcg", score("dcg", json!({}), false)),
            ("ndcg", score("dcg", json!({}), true)),
            ("mrr", score("mean_reciprocal_rank", json!({}), false)),
            (
                "err",
                score(
                    "expected_reciprocal_rank",
                    json!({"maximum_relevance":3}),
                    false,
                ),
            ),
        ] {
            assert!(
                (val - precision).abs() > 1e-6,
                "{name} collapsed to precision ({precision})"
            );
        }
    }
}

pub async fn rank_eval(
    State(state): State<AppState>,
    Path(index): Path<String>,
    Json(body): Json<RankEvalBody>,
) -> impl IntoResponse {
    let mut details: serde_json::Map<String, Value> = serde_json::Map::new();
    let mut all_scores: Vec<f64> = Vec::new();

    // The metric object carries exactly one key naming the metric. Default
    // to precision when omitted (back-compat). Each metric computes its own
    // real score below — an unknown metric fails loud (400) rather than
    // silently returning precision.
    let (metric_name, mparams): (String, Value) = body
        .metric
        .as_ref()
        .and_then(|m| m.as_object())
        .and_then(|o| o.iter().next().map(|(k, v)| (k.clone(), v.clone())))
        .unwrap_or_else(|| ("precision".to_string(), json!({})));

    const KNOWN_METRICS: [&str; 5] = [
        "precision",
        "recall",
        "dcg",
        "mean_reciprocal_rank",
        "expected_reciprocal_rank",
    ];
    if !KNOWN_METRICS.contains(&metric_name.as_str()) {
        return ApiError::new(xerj_common::XerjError::invalid_query(format!(
            "unknown rank_eval metric [{metric_name}]; supported: precision, recall, dcg, \
             mean_reciprocal_rank, expected_reciprocal_rank"
        )))
        .into_response();
    }

    let k = mparams.get("k").and_then(Value::as_u64).unwrap_or(10) as usize;
    let threshold = mparams
        .get("relevant_rating_threshold")
        .and_then(Value::as_u64)
        .unwrap_or(1) as u32;
    let normalize = mparams
        .get("normalize")
        .and_then(Value::as_bool)
        .unwrap_or(false);

    let mut failures = serde_json::Map::new();

    // A request `_rank_eval` cannot run is recorded in `failures`, never
    // dropped. The three arms below used to be `Err(_) => continue`, so a
    // refused request vanished from `details` AND from `failures` while
    // `metric_score` was still published — the batch silently shrank and the
    // mean was taken over the survivors, on the one endpoint whose entire
    // purpose is measuring relevance quality. `failures` is the channel ES
    // provides for exactly this (the `script_failure` arm further down already
    // used it); a faulted request contributes nothing to `metric_score`, and a
    // caller can now see that it did not.
    let record_failure =
        |failures: &mut serde_json::Map<String, Value>, id: &str, err: xerj_common::XerjError| {
            let detail = ApiError::new(err)
                .into_value()
                .get("error")
                .cloned()
                .unwrap_or_else(|| json!({ "type": "exception", "reason": "request failed" }));
            failures.insert(id.to_string(), detail);
        };

    for req_spec in &body.requests {
        // `_rank_eval` runs the engine's ranking and nothing else: the request
        // below is rebuilt from `query` and `size`, so a `rerank` block would
        // vanish and the metric would be computed over the engine's order —
        // "reranking changed nothing", under a 200, from the one endpoint whose
        // job is measuring ranking quality. Reported per request in `failures`
        // (the rest of the batch still runs), like every other request this
        // handler cannot run, and nothing is sent to the provider. A `judge`
        // block would vanish the same way, for the same reason.
        if crate::judge_stage::carries_second_stage(&req_spec.request) {
            crate::rerank_stage::record_refused(&state.metrics);
            // The same `illegal_argument_exception` body every other surface
            // that does not run the stage answers with, not the
            // `search_phase_execution_exception` a failed search gets: the
            // request was never run.
            failures.insert(
                req_spec.id.clone(),
                crate::judge_stage::unsupported_second_stage_on("_rank_eval", &req_spec.request)
                    ["error"]
                    .clone(),
            );
            continue;
        }
        let query_val = req_spec
            .request
            .get("query")
            .cloned()
            .unwrap_or(json!({"match_all": {}}));
        let size = req_spec
            .request
            .get("size")
            .and_then(Value::as_u64)
            .unwrap_or(k as u64) as usize;

        let search_req =
            match xerj_query::parse_request(&json!({"query": query_val, "size": size.max(k)})) {
                Ok(r) => r,
                Err(e) => {
                    record_failure(
                        &mut failures,
                        &req_spec.id,
                        xerj_common::XerjError::invalid_query(e.to_string()),
                    );
                    continue;
                }
            };

        let idx = match state.engine.get_index(&index) {
            Ok(i) => i,
            Err(e) => {
                record_failure(&mut failures, &req_spec.id, xerj_common::XerjError::from(e));
                continue;
            }
        };

        let result = match idx.search(&search_req).await {
            Ok(r) => r,
            Err(e) => {
                record_failure(&mut failures, &req_spec.id, xerj_common::XerjError::from(e));
                continue;
            }
        };
        // A Painless resource limit tripped while scoring or matching this
        // request. `_rank_eval` exists to *measure relevance quality*, so a
        // `metric_score` computed over degraded scores (or over a ranking a
        // fail-closed script truncated) does not just return a bad answer — it
        // corrupts the number a caller would use to notice bad answers.
        //
        // The failure is recorded PER REQUEST rather than failing the batch.
        // `failures` is the channel ES provides for exactly this, keyed by the
        // request id, and a body of ten requests where one carries a bad script
        // should not lose the other nine. The faulted request contributes
        // nothing to `metric_score`, so the published number is computed only
        // over requests that actually produced trustworthy scores.
        if let Some(reason) = &result.script_failure {
            failures.insert(
                req_spec.id.clone(),
                script_limit_error_value(reason)
                    .get("error")
                    .cloned()
                    .unwrap_or_else(|| json!({ "type": "script_exception", "reason": reason })),
            );
            continue;
        }

        let retrieved_ids: Vec<String> = result.hits.iter().take(k).map(|h| h.id.clone()).collect();

        // Rating of each retrieved doc, in rank order (unrated → 0).
        let rating_of = |id: &str| -> u32 {
            req_spec
                .ratings
                .iter()
                .find(|r| r.id == id)
                .map(|r| r.rating)
                .unwrap_or(0)
        };
        let ranked: Vec<u32> = retrieved_ids.iter().map(|id| rating_of(id)).collect();
        let all_ratings: Vec<u32> = req_spec.ratings.iter().map(|r| r.rating).collect();

        let score = rank_eval_metric_score(
            &metric_name,
            &mparams,
            &ranked,
            &all_ratings,
            k,
            threshold,
            normalize,
        );

        all_scores.push(score);

        details.insert(req_spec.id.clone(), json!({
            "metric_score": score,
            "unrated_docs": [],
            "hits": retrieved_ids.iter().enumerate().map(|(i, id)| {
                let rating = req_spec.ratings.iter().find(|r| &r.id == id).map(|r| r.rating as i64).unwrap_or(-1);
                json!({
                    "hit": { "_index": index, "_id": id },
                    "rating": rating,
                    "position": i + 1
                })
            }).collect::<Vec<_>>()
        }));
    }

    // Top-level score is the mean across requests (ES aggregates every
    // rank_eval metric by averaging per-request scores).
    let mean_score = if all_scores.is_empty() {
        0.0
    } else {
        all_scores.iter().sum::<f64>() / all_scores.len() as f64
    };

    Json(json!({
        "metric_score": mean_score,
        "details": details,
        "failures": Value::Object(failures)
    }))
    .into_response()
}

