        assert_eq!(body["_nodes"]["total"], 3);
        assert_eq!(body["_nodes"]["successful"], 1, "only self answered");
        let nodes = body["nodes"].as_object().expect("nodes map");
        assert_eq!(nodes.len(), 3);
