/// Response to `PUT /{index}` (create index).
#[derive(Debug, Serialize, Deserialize)]
pub struct EsIndexResponse {
    pub acknowledged: bool,
    pub shards_acknowledged: bool,
    pub index: String,
    /// Present only when a mapping asked for an embedder this server will not
    /// use. Empty stays off the wire so existing clients see the same JSON.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub warnings: Vec<String>,
}

impl EsIndexResponse {
    pub fn ok(index: impl Into<String>) -> Self {
        Self {
            acknowledged: true,
            shards_acknowledged: true,
            index: index.into(),
            warnings: Vec::new(),
        }
    }
}

/// Response to `DELETE /{index}`.
#[derive(Debug, Serialize, Deserialize)]
pub struct EsDeleteIndexResponse {
    pub acknowledged: bool,
}

impl EsDeleteIndexResponse {
    pub fn ok() -> Self {
        Self { acknowledged: true }
    }
}

