/// Response to `PUT /{index}/_doc/{id}` and `POST /{index}/_doc`.
#[derive(Debug, Serialize, Deserialize)]
pub struct EsDocResponse {
    #[serde(rename = "_index")]
    pub index: String,
    #[serde(rename = "_id")]
    pub id: String,
    #[serde(rename = "_version")]
    pub version: u64,
    pub result: String, // "created" | "updated"
    #[serde(rename = "_shards")]
    pub shards: EsShards,
    #[serde(rename = "_seq_no")]
    pub seq_no: u64,
    #[serde(rename = "_primary_term")]
    pub primary_term: u64,
    /// `_update`-only: the post-update document, present only when the
    /// caller requested it via `_source`/`_source_includes`/`_source_excludes`
    /// (real ES's `_update` response omits `get` entirely otherwise). Index
    /// and create responses never set this.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub get: Option<Value>,
}

impl EsDocResponse {
    /// `result: "created"` — `version` is NOT always 1: a re-index after a
    /// delete reports `created` while `_version` continues from the
    /// tombstone (ES 8.13.4 live-verified).
    pub fn created(
        index: impl Into<String>,
        id: impl Into<String>,
        version: u64,
        seq_no: u64,
    ) -> Self {
        Self {
            index: index.into(),
            id: id.into(),
            version,
            result: "created".to_string(),
            shards: EsShards::single_success(),
            seq_no,
            primary_term: 1,
            get: None,
        }
    }

    pub fn updated(
        index: impl Into<String>,
        id: impl Into<String>,
        version: u64,
        seq_no: u64,
    ) -> Self {
        Self {
            index: index.into(),
            id: id.into(),
            version,
            result: "updated".to_string(),
            shards: EsShards::single_success(),
            seq_no,
            primary_term: 1,
            get: None,
        }
    }
}

/// Response to `GET /{index}/_doc/{id}`.
///
/// The metadata fields are `Option` because ES omits `_version` /
/// `_seq_no` / `_primary_term` entirely on a not-found GET — the 404 body
/// is exactly `{"_index": ..., "_id": ..., "found": false}` (live-verified
/// against ES 8.13.4).
#[derive(Debug, Serialize, Deserialize)]
pub struct EsGetResponse {
    #[serde(rename = "_index")]
    pub index: String,
    #[serde(rename = "_id")]
    pub id: String,
    #[serde(rename = "_version", skip_serializing_if = "Option::is_none")]
    pub version: Option<u64>,
    #[serde(rename = "_seq_no", skip_serializing_if = "Option::is_none")]
    pub seq_no: Option<u64>,
    #[serde(rename = "_primary_term", skip_serializing_if = "Option::is_none")]
    pub primary_term: Option<u64>,
    pub found: bool,
    #[serde(rename = "_source", skip_serializing_if = "Option::is_none")]
    pub source: Option<Value>,
}

impl EsGetResponse {
    pub fn found(
        index: impl Into<String>,
        id: impl Into<String>,
        version: u64,
        seq_no: u64,
        source: Value,
    ) -> Self {
        Self {
            index: index.into(),
            id: id.into(),
            version: Some(version),
            seq_no: Some(seq_no),
            primary_term: Some(1),
            found: true,
            source: Some(source),
        }
    }

    pub fn not_found(index: impl Into<String>, id: impl Into<String>) -> Self {
        Self {
            index: index.into(),
            id: id.into(),
            version: None,
            seq_no: None,
            primary_term: None,
            found: false,
            source: None,
        }
    }
}

/// Response to `DELETE /{index}/_doc/{id}`.
#[derive(Debug, Serialize, Deserialize)]
pub struct EsDeleteDocResponse {
    #[serde(rename = "_index")]
