    #[test]
    fn labels_for_gives_a_noul_two_sides_and_a_choice_its_options() {
        let cfg = DecisionsConfig::default();
        let noul = Question {
            vote_text: "payload".into(),
            kind: Kind::Noul,
        };
        assert_eq!(
            labels_for(&noul, &cfg),
