    /// Only a JSON boolean `true` earns the correction weight — "true", 1,
    /// and a missing field are ordinary history.
    #[test]
    fn only_a_boolean_true_marks_a_human_correction() {
        assert!(is_human_correction(&json!({"human": true})));
        assert!(!is_human_correction(&json!({"human": "true"})));
        assert!(!is_human_correction(&json!({"human": 1})));
        assert!(!is_human_correction(&json!({"human": false})));
        assert!(!is_human_correction(&json!({"text": "no human field"})));
        assert!(!is_human_correction(&Value::Null));
    }

    /// Every tier's wire name is stable — it is `tier`, `source`, and the
    /// cached document's `source` all at once.
    #[test]
    fn tier_names_are_the_source_names() {
        assert_eq!(DecideTier::History.as_str(), "history");
        assert_eq!(DecideTier::Local.as_str(), "local");
        assert_eq!(DecideTier::Hosted.as_str(), "hosted");
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Calibration (#1063)
    // ─────────────────────────────────────────────────────────────────────────

    /// The fit's data contract: a labelled outcome document is a pair, the
    /// positive label's probability against the outcome; a flywheel answer
    /// (`source`) is NOT, because its label is the model's own prediction —
    /// calibrating on predictions would learn the model is right by
    /// construction.
    #[test]
    fn calibration_pairs_come_from_outcomes_not_predictions() {
        let cfg = DecisionsConfig::default(); // label_field "label", positive "true"
                                              // An outcome the system got wrong: it said 0.9, the truth is "false".
                                              // The positive-label probability is 1 − 0.9, the outcome 0.
        let doc = json!({"text": "…", "label": "false", "p": 0.9});
        let pair = pair_from_doc(&doc, &cfg).expect("outcome pair");
        assert!(
            (pair.p - 0.1).abs() < 1e-12,
            "p_pos = 1 − p when label ≠ positive"
        );
        assert_eq!(pair.y, 0.0);
        // An outcome it got right: p of the positive label, outcome 1.
        let doc = json!({"text": "…", "label": "true", "p": 0.8});
        let pair = pair_from_doc(&doc, &cfg).expect("outcome pair");
        assert!((pair.p - 0.8).abs() < 1e-12);
        assert_eq!(pair.y, 1.0);
        // A human correction carrying the p it corrects: still an outcome,
        // and the best kind — truth plus the number that was wrong.
        let doc = json!({"text": "…", "label": "true", "p": 0.3, "human": true});
        assert!(pair_from_doc(&doc, &cfg).is_some());
        // A flywheel answer: a prediction, never a pair.
        let doc = json!({"text": "…", "label": "true", "p": 0.8, "source": "local", "ts": "…"});
        assert!(
            pair_from_doc(&doc, &cfg).is_none(),
            "a `source` document is the model's own answer"
        );
        // No p, no pair — a seeded example has a truth but no raw
        // probability to calibrate.
        assert!(pair_from_doc(&json!({"text": "…", "label": "true"}), &cfg).is_none());
        // No label, no pair.
        assert!(pair_from_doc(&json!({"text": "…", "p": 0.8}), &cfg).is_none());
        // A p that is not a probability is not calibration data.
        assert!(pair_from_doc(&json!({"label": "true", "p": 1.4}), &cfg).is_none());
        assert!(pair_from_doc(&json!({"label": "true", "p": -0.1}), &cfg).is_none());
        assert!(pair_from_doc(&json!({"label": "true"}), &cfg).is_none());
    }

    /// The three states on the wire: off ships no p_cal at all, unfit ships
    /// null with the reason published in the block, fitted ships the fit's
    /// value — and never a copy of p_raw pretending to be calibrated.
    #[test]
    fn p_cal_is_absent_null_or_calibrated_never_a_copy() {
        // Off: nothing.
        assert!(p_cal_value(&CalibrationState::Off, 0.7).is_none());
        assert!(calibration_block(&CalibrationState::Off).is_none());
        // Unfit: null, with the reason riding in the block.
        let unfit = CalibrationState::Unfit("only 3 labelled pairs".into());
        assert_eq!(p_cal_value(&unfit, 0.7), Some(Value::Null));
        let block = calibration_block(&unfit).expect("block");
        assert_eq!(block["reason"], "only 3 labelled pairs");
        // Fitted: the fit's value and its ECE, not p_raw echoed back. The
        // identity fit (one knot per distinct p, already monotone) would echo
        // — so use a fit that learned the opposite of the raw number.
        let report = Arc::new(
            xerj_common::calibration::fit_calibration(
                xerj_common::calibration::CalibrationMethod::Isotonic,
                &[
                    CalibrationPair { p: 0.9, y: 0.0 },
                    CalibrationPair { p: 0.9, y: 0.0 },
                    CalibrationPair { p: 0.9, y: 0.0 },
                    CalibrationPair { p: 0.9, y: 0.0 },
                    CalibrationPair { p: 0.9, y: 0.0 },
                    CalibrationPair { p: 0.2, y: 0.0 },
                    CalibrationPair { p: 0.2, y: 0.0 },
                    CalibrationPair { p: 0.2, y: 0.0 },
                    CalibrationPair { p: 0.2, y: 0.0 },
                    CalibrationPair { p: 0.2, y: 0.0 },
                ],
            )
            .expect("fit"),
        );
        let fitted = CalibrationState::Fitted(report);
        let p_cal = p_cal_value(&fitted, 0.9).expect("a value");
        let p_cal = p_cal.as_f64().expect("a number");
        assert!(
            (p_cal - 0.9).abs() > 1e-9,
            "a fit that learned 0.9 means 0 must not echo 0.9 back (got {p_cal})"
        );
        assert!(
            (p_cal - 0.0).abs() < 1e-9,
            "five negatives at 0.9 → p_cal 0"
        );
        let block = calibration_block(&fitted).expect("block");
        assert_eq!(block["method"], "isotonic");
        assert_eq!(block["scope"], "noul");
        assert!(
            block["ece"]["calibrated"].is_number(),
            "the ECE rides beside: {block}"
        );
        assert!(block["ece"]["raw"].is_number());
        assert_eq!(block["fitted_on"], 8);
        assert_eq!(block["held_out"], 2);
    }

    /// The unfit reason names what a fit needs and how to record it — an
    /// operator who sees `p_cal: null` can act on the string beside it.
    #[test]
    fn the_unfit_reason_names_the_recording_path() {
        let reason = unfit_reason(&DecisionsConfig::default(), 3);
        assert!(reason.contains("3 labelled calibration pairs"), "{reason}");
        assert!(
            reason.contains("10"),
            "the minimum is in the message: {reason}"
        );
        assert!(
            reason.contains("source"),
            "the flywheel exclusion is explained: {reason}"
        );
    }
}

//! REST surface for the single-node WAL tap (issue #320).
//!
//! ```text
//! GET    /_xerj/wal_tap          current configuration (never the credential)
//! PUT    /_xerj/wal_tap          merge-patch it, durably, no restart
//! DELETE /_xerj/wal_tap          drop the runtime overlay, revert to the file
//! GET    /_xerj/wal_tap/_stats   per-index cursors, lag, counters, last error
//! ```
//!
//! This is a native (`_xerj`-namespaced) surface, not an Elasticsearch one:
//! there is no ES endpoint that means "push my WAL somewhere", and pretending
//! `_ccr/*` did would be exactly the silent-stub behaviour those handlers were
//! made to `501` to avoid.
//!
//! ## Why every route here is superuser-only
//!
//! `PUT /_xerj/wal_tap` is a whole-node export primitive: `target_url` plus
//! `indices: ["*"]` streams every index on this node to a host of the
//! caller's choosing, with an operator-supplied `Authorization` header
//! attached — exfiltration and authenticated SSRF in one request. Nothing
//! here is index-scoped, so there is no per-index decision to make, and that
//! is the same reasoning `authz.rs` already applies to snapshot and restore.
//! The reads are covered for the same reason: `GET /_xerj/wal_tap` echoes
//! `target_url` and `_stats` enumerates the node's whole index inventory.
//! Enforced in [`crate::authz`] on the `_xerj` first segment, not here, so a
//! second `_xerj` route cannot be added without inheriting it.

use axum::{
    extract::State,
    response::{IntoResponse, Response},
    Json,
};
use serde::Deserialize;
use serde_json::{json, Value};

use xerj_common::config::WalTapConfig;
use xerj_engine::wal_tap::WalTap;

use crate::{extract::OptionalJson, state::AppState};

/// The configuration as the API reports it.
///
/// `target_auth` is deliberately absent: it is a bearer credential for another
/// cluster, and an endpoint that reads it back turns "can call the admin API"
/// into "holds the target's credential". `target_auth_configured` is the
/// operator-visible part.
///
/// `target_url` is **redacted**, and that is not belt and braces — it closes
/// the hole the omission above left wide open. `https://user:pass@host:9200`
/// is an ordinary URL, and `reqwest` turns its userinfo into a `Basic`
/// `Authorization` header, so an operator who put the credential there was
/// configuring `target_auth` by another spelling — and this endpoint would
/// have handed it straight back. [`WalTapConfig::check_target_url`] refuses
/// userinfo on the way in; this makes sure a URL that arrived some other way
/// (an older state file, a hand-edited config) still cannot be read back out.
fn config_body(config: &WalTapConfig) -> Value {
    json!({
        "enabled": config.enabled,
        "target_url": config.redacted_target_url(),
        "target_auth_configured": !config.target_auth.is_empty(),
        "indices": config.indices,
        "poll_interval_ms": config.poll_interval_ms,
        "max_batch_docs": config.max_batch_docs,
        "max_batch_bytes": config.max_batch_bytes,
        "request_timeout_secs": config.request_timeout_secs,
        "max_retry_backoff_secs": config.max_retry_backoff_secs,
        "min_retained_generations": config.min_retained_generations,
    })
}

/// `GET /_xerj/wal_tap`
pub async fn get_wal_tap(State(state): State<AppState>) -> Response {
    let mut body = config_body(&state.engine.wal_tap.config());
    if let Some(obj) = body.as_object_mut() {
        // Which of the two sources this configuration came from is the
        // question an operator asks after a restart, and the one the tap used
        // to answer wrongly by silently reverting to the file.
        obj.insert(
            "source".into(),
            json!(if state.engine.wal_tap.has_runtime_config() {
                "runtime"
            } else {
                "config_file"
            }),
        );
    }
    Json(body).into_response()
}

/// The mutable half. Every field optional — an absent field keeps its current
/// value, so an operator can flip `enabled` without restating the allowlist.
#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct WalTapPatch {
    pub enabled: Option<bool>,
    pub target_url: Option<String>,
    /// Write-only. `""` clears the stored credential.
    pub target_auth: Option<String>,
    pub indices: Option<Vec<String>>,
    pub poll_interval_ms: Option<u64>,
    pub max_batch_docs: Option<usize>,
    pub max_batch_bytes: Option<usize>,
    pub request_timeout_secs: Option<u64>,
    pub max_retry_backoff_secs: Option<u64>,
    pub min_retained_generations: Option<u64>,
}

fn bad_request(reason: &str) -> Response {
    (
        axum::http::StatusCode::BAD_REQUEST,
        Json(json!({
            "error": {"type": "illegal_argument_exception", "reason": reason},
            "status": 400,
        })),
    )
        .into_response()
}

/// `PUT /_xerj/wal_tap`
///
/// Takes effect on the next poll. Cursors are keyed by index name and are
/// untouched here, so adding an index to the allowlist starts it "from now"
/// while an index that was already running resumes exactly where it was —
/// removing and re-adding one does not re-ship what it already shipped.
pub async fn put_wal_tap(
    State(state): State<AppState>,
    OptionalJson(body): OptionalJson<WalTapPatch>,
) -> Response {
    let patch = body.unwrap_or_default();
    let mut config = state.engine.wal_tap.config();

    if let Some(v) = patch.enabled {
        config.enabled = v;
    }
    if let Some(v) = patch.target_url {
        let trimmed = v.trim().to_string();
        // Shape AND credential check. `https://user:pass@host` passed the old
        // scheme-only test, and `reqwest` would have turned that userinfo into
        // a `Basic Authorization` header — a credential smuggled into the one
        // field this API echoes back (and logs at boot).
        if let Err(reason) = WalTapConfig::check_target_url(&trimmed) {
            return bad_request(&reason);
        }
        config.target_url = trimmed;
    }
    if let Some(v) = patch.target_auth {
        config.target_auth = v;
    }
    if let Some(v) = patch.indices {
        // A pattern that can only ever match system indices is a mistake worth
        // reporting rather than silently dropping: the tap refuses `.xerj*`
        // unconditionally, so such a pattern would ship nothing forever and
        // look like a broken tap.
        if let Some(bad) = v.iter().find(|p| p.starts_with(".xerj")) {
            return bad_request(&format!(
                "wal_tap.indices pattern {bad:?} only matches system indices, which are \
                 never shipped"
            ));
        }
        config.indices = v;
    }
    if let Some(v) = patch.poll_interval_ms {
        config.poll_interval_ms = v;
    }
    if let Some(v) = patch.max_batch_docs {
        config.max_batch_docs = v;
    }
    if let Some(v) = patch.max_batch_bytes {
        config.max_batch_bytes = v;
    }
    if let Some(v) = patch.request_timeout_secs {
        config.request_timeout_secs = v;
    }
    if let Some(v) = patch.max_retry_backoff_secs {
        config.max_retry_backoff_secs = v;
    }
    if let Some(v) = patch.min_retained_generations {
        config.min_retained_generations = v;
    }

    // One range check for the numeric knobs, shared verbatim with
    // `Config::validate` so the config file cannot be used to get a value past
    // the bound this endpoint enforces. It used to be six inline checks here
    // and none at all at boot: `PUT {"min_retained_generations": 100}` was a
    // `400` because the knob costs `n × storage.wal_max_size_mb` per WAL shard
    // per index, while `xerj.toml` took the same 100 in silence.
    if let Err(reason) = config.check_limits() {
        return bad_request(&reason);
    }

    if config.enabled && config.target_url.is_empty() {
        return bad_request("wal_tap.enabled requires a target_url");
    }

    let body = config_body(&config);
    state.engine.wal_tap.set_config(config);
    // `min_retained_generations` is the one setting here that does not live in
    // the tap — it lives in every open index's `WalWriter`, and those were
    // seeded from `Engine.config`, an `Arc<Config>` written once at boot and
    // never mutated. Push it onto the live writers NOW, before answering.
    //
    // The previous shape acknowledged the value and attached a warning saying
    // it would take effect after a restart. It did not take effect after a
    // restart: `store_config_from` read the boot file, not the persisted
    // runtime config. An operator raising the floor to survive a target
    // outage, seeing `200`, restarting, and still losing WAL entries had been
    // told a falsehood by the API — on the one knob whose entire purpose is
    // preventing that loss.
    let applied_to = state.engine.apply_wal_retention_floor();
    let mut resp = json!({"acknowledged": true, "wal_tap": body, "persisted": true});
    if patch.min_retained_generations.is_some() {
        // Not a warning — a receipt. It names the number of live WAL writers
        // the new floor reached, which is the only claim here that an operator
        // cannot verify from the echoed config alone.
        resp["retention_floor_applied_to_indices"] = json!(applied_to);
    }
    Json(resp).into_response()
}

/// `DELETE /_xerj/wal_tap`
///
/// Drop the persisted runtime configuration and revert to the config file.
///
/// The counterpart to `PUT` now that a `PUT` is durable: without this, one
/// API call would permanently shadow `xerj.toml` with no way back short of
/// deleting a file in the data directory. Modelled on `_cluster/settings`,
/// where writing `null` clears a persistent setting.
pub async fn delete_wal_tap(State(state): State<AppState>) -> Response {
    // Taken from the tap, which kept `xerj.toml`'s value verbatim at
    // construction. It used to be read back off `state.engine.config()`, which
    // was only correct while nothing else wrote to that field —
    // `Engine::new` now folds the tap's *effective* config into the boot
    // `Config` so index stores open with the retention floor actually in
    // force, and reading it back here would have reverted a persisted runtime
    // config to itself.
    let file_config = state.engine.wal_tap.file_config();
    state.engine.wal_tap.clear_runtime_config(file_config);
    // The file's floor is now the live one; the open indices have to be told.
    state.engine.apply_wal_retention_floor();
    Json(json!({
        "acknowledged": true,
        "wal_tap": config_body(&state.engine.wal_tap.config()),
        "source": "config_file",
    }))
    .into_response()
}

/// `GET /_xerj/wal_tap/_stats`
///
/// The honesty surface. `gaps > 0` means entries were pruned out of the WAL
/// before the tap could ship them and are gone; `lag_seq` is how far behind
/// the index's own sequence counter the tap is; `last_error` is why it stopped
/// advancing; `healthy` is false when either of the two states that used to
/// be indistinguishable from working is in effect — sends failing, or a
/// target answering 200 while applying none of the actions inside it, for any
/// reason (`version_conflict_engine_exception`, `mapper_parsing_exception`,
/// anything else). `last_item_rejection` carries the target's own word for
/// the last non-conflict rejection, because "fix the mapping" and "look for a
/// second writer" are opposite responses.
///
/// Superuser-only ([`crate::authz`]): this enumerates every index on the node
/// that the allowlist matches, and it echoes `target_url`. It applies no
/// principal filter of its own precisely because it is never reached by a
/// principal that would need one.
pub async fn wal_tap_stats(State(state): State<AppState>) -> Response {
    let tap = &state.engine.wal_tap;
    let config = tap.config();
    let stats = tap.stats();
    let cursors = tap.cursors();

    let mut indices = serde_json::Map::new();
    let mut all_healthy = true;
    for name in state.engine.index_name_list() {
        if !WalTap::ships(&config, &name) {
            continue;
        }
        let stat = stats.get(&name).cloned().unwrap_or_default();
        // `current_seq_no` is the NEXT seq to be handed out, so the highest
        // reserved one is that minus 1.
        let head = state
            .engine
            .get_index(&name)
            .map(|i| i.current_seq_no().saturating_sub(1))
            .unwrap_or(0);
        let mut body = serde_json::to_value(&stat).unwrap_or_else(|_| json!({}));
        if let Some(obj) = body.as_object_mut() {
            obj.insert(
                "lag_seq".into(),
                json!(head.saturating_sub(stat.last_shipped_seq)),
            );
            // One boolean an operator can alert on, so "is replication
            // working?" does not require correlating five counters.
            obj.insert("healthy".into(), json!(stat.healthy()));
            obj.insert(
                "cursors".into(),
                serde_json::to_value(cursors.get(&name).cloned().unwrap_or_default())
                    .unwrap_or_else(|_| json!({})),
            );
        }
        if !stat.healthy() {
            all_healthy = false;
        }
        indices.insert(name, body);
    }

    Json(json!({
        "enabled": config.enabled,
        // Redacted for the same reason as in `config_body`: `_stats` is a
        // second read path onto the same string.
        "target_url": config.redacted_target_url(),
        "ticks": tap.ticks(),
        "healthy": all_healthy,
        "indices": indices,
    }))
    .into_response()
}

//! Issue #524: an alias's `filter` must survive a restart.
//!
//! The alias→members topology is persisted to `aliases.json`, but each alias's
//! `filter` lived only in the in-memory `index_alias_metadata` map and was
//! never written to disk. So a filtered alias came back after a restart with
//! its members but no filter: `_search`/`_count` through it silently returned
//! the whole backing corpus instead of the slice the filter names, and once
//! the by-query paths honour the filter (#453) a `_delete_by_query` through
//! such an alias would empty the whole backing index. The fix persists the
//! metadata to a `alias_metadata.json` sidecar and reloads it on boot.
//!
//! This test creates a filtered alias, drops the engine, opens a fresh one on
//! the same data dir, and asserts the filter is still there. Before the fix it
//! comes back empty.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

fn config_for(dir: &std::path::Path) -> xerj_common::config::Config {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config
}

/// Build a fresh app over `dir`. Calling this after the previous app has been
/// dropped is a restart: nothing is handed over in memory, the second boot
/// sees only what reached the disk.
fn app_over(dir: &std::path::Path) -> axum::Router {
    let config = config_for(dir);
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    xerj_api::router::build_es_compat_router(state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, body)
}

fn put_json(path: &str, body: Value) -> Request<Body> {
    Request::put(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

fn get(path: &str) -> Request<Body> {
    Request::get(path).body(Body::empty()).expect("request")
}

#[tokio::test]
async fn an_alias_filter_survives_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");
    let the_filter = json!({ "term": { "tier": "gold" } });

    // ── Session 1: create an index and a FILTERED alias over it. ──
    {
        let app = app_over(dir.path());

        let (st, body) = send(&app, put_json("/orders", json!({}))).await;
        assert_eq!(st, StatusCode::OK, "create index: {body}");

        let (st, body) = send(
            &app,
            put_json("/orders/_alias/gold", json!({ "filter": the_filter })),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create filtered alias: {body}");

        // Sanity BEFORE the restart: the filter is visible, so a failure after
        // the restart is unambiguously a persistence failure, not a write that
        // never landed.
        let (st, body) = send(&app, get("/_alias/gold")).await;
        assert_eq!(st, StatusCode::OK, "read alias before restart: {body}");
        assert_eq!(
            body.pointer("/orders/aliases/gold/filter"),
            Some(&the_filter),
            "the filter must be present before the restart: {body}"
        );
    } // app — and with it the engine and its node lock — dropped here.

    // ── Session 2: a fresh engine on the same dir sees only what reached disk. ──
    let app = app_over(dir.path());
    let (st, body) = send(&app, get("/_alias/gold")).await;
    assert_eq!(st, StatusCode::OK, "read alias after restart: {body}");
    assert_eq!(
        body.pointer("/orders/aliases/gold/filter"),
        Some(&the_filter),
        "the alias filter must survive a restart, not come back empty: {body}"
    );
}

//! An alias is a valid index selector in Elasticsearch for every maintenance
//! endpoint. Here it was not: `resolve_indices_for_op` had no alias branch at
//! all, so an alias was simply "not an index" and the whole request 404'd.
//!
//! Measured before the fix, on a three-member alias `tri`:
//!
//!   POST /tri/_refresh       -> 404      POST /idx-a/_refresh       -> 200
//!   POST /tri/_forcemerge    -> 404      POST /idx-a/_forcemerge    -> 200
//!   POST /tri/_cache/clear   -> 404      POST /idx-a/_cache/clear   -> 200
//!   POST /tri/_terms_enum    -> 404      POST /idx-a/_terms_enum    -> 200
//!
//! The alias expands to EVERY member rather than `aliased.first()`. A
//! maintenance op that silently addressed one member of a multi-index alias is
//! the same defect class as #450 on the destructive side — and a `_refresh`
//! that reaches one of three members makes the next search non-deterministic
//! in a way nothing in the response admits.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn req(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut b = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        b = b.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let res = app.clone().oneshot(b.body(body).unwrap()).await.unwrap();
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn three_members(app: &axum::Router) {
    for m in ["idx-a", "idx-b", "idx-c"] {
        req(
            app,
            "PUT",
            &format!("/{m}"),
            json!({"mappings":{"properties":{"n":{"type":"integer"}}}}),
        )
        .await;
        for n in 1..=3 {
            req(app, "POST", &format!("/{m}/_doc/{m}{n}"), json!({"n": n})).await;
        }
        let (st, _) = req(app, "PUT", &format!("/{m}/_alias/tri"), Value::Null).await;
        assert!(st.is_success(), "alias on {m}: {st}");
    }
}

#[tokio::test]
async fn maintenance_endpoints_accept_an_alias_and_reach_every_member() {
    let (app, _d) = app().await;
    three_members(&app).await;

    for (method, path, body) in [
        ("POST", "/tri/_refresh", Value::Null),
        ("POST", "/tri/_forcemerge", Value::Null),
        ("POST", "/tri/_cache/clear", Value::Null),
        ("POST", "/tri/_terms_enum", json!({"field": "n"})),
    ] {
        let (st, b) = req(&app, method, path, body).await;
        assert_eq!(st, StatusCode::OK, "{path} must accept an alias. body: {b}");
    }

    // Not just accepted — every member must be reached. One-member behaviour
    // would still return 200 and would still be wrong.
    let (st, b) = req(&app, "POST", "/tri/_refresh", Value::Null).await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(
        b["_shards"]["total"], 3,
        "an alias over three indices must refresh all three, not aliased.first(). body: {b}"
    );
    assert_eq!(b["_shards"]["failed"], 0, "body: {b}");
}

/// The alias branch must not weaken the missing-name rule: ES defaults
/// `ignore_unavailable=false`, so a typo in a comma list fails the whole
/// request rather than silently doing less than asked.
#[tokio::test]
async fn an_unknown_name_still_fails_the_whole_request() {
    let (app, _d) = app().await;
    three_members(&app).await;

    let (st, _) = req(&app, "POST", "/no-such-thing/_refresh", Value::Null).await;
    assert_eq!(st, StatusCode::NOT_FOUND);

    let (st, _) = req(&app, "POST", "/idx-a,typo/_refresh", Value::Null).await;
    assert_eq!(
        st,
        StatusCode::NOT_FOUND,
        "a typo beside a real name must 404"
    );

    // And an index of the same name as an alias wins, as in ES.
    let (st, b) = req(&app, "POST", "/idx-a/_refresh", Value::Null).await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(
        b["_shards"]["total"], 1,
        "concrete name addresses one index. body: {b}"
    );
}

//! Issue #433: a multi-index alias answered as an alias over ONE member on
//! every read path.
//!
//! Three indices behind one alias, 40 documents each. `GET /_alias/kb` listed
//! all three, and `_count`, `_search` and a scroll through the alias all
//! answered 40 — from the first member, with no error and a count that agreed
//! with the short result. Not a keyed consumer silently keeping a fraction:
//! every consumer got a fraction.
//!
//! The cause was three independent copies of index-selector resolution.
//! `resolve_index_selector` expanded aliases; `search_impl`'s own resolver only
//! looked for `_all` and `*`; `count_docs` gated its whole multi-index branch on
//! the same two plus a comma or a star. A plain alias fell through both.
//!
//! These go through the real HTTP routes because that is the only place the
//! three resolvers meet.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

const PER_INDEX: usize = 40;

async fn seed(app: &axum::Router) {
    for member in ["kb-a", "kb-b", "kb-c"] {
        let (st, _) = call(
            app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {"v": {"type": "long"}, "home": {"type": "keyword"}}}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");

        let mut bulk = String::new();
        for i in 0..PER_INDEX {
            bulk.push_str(&format!("{}\n", json!({"index": {"_id": i.to_string()}})));
            bulk.push_str(&format!("{}\n", json!({"v": i, "home": member})));
        }
        let response = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/{member}/_bulk"))
                    .header("content-type", "application/x-ndjson")
                    .body(Body::from(bulk))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK, "bulk {member}");
        let (st, _) = call(app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK);
    }
    let (st, _) = call(
        app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "kb-a", "alias": "kb"}},
            {"add": {"index": "kb-b", "alias": "kb"}},
            {"add": {"index": "kb-c", "alias": "kb"}},
            {"add": {"index": "kb-a", "alias": "solo"}}
        ]}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create aliases");
}

/// `_count` and `_search` must see every member, and a one-member alias must
/// keep answering for exactly that member.
#[tokio::test]
async fn every_read_path_through_a_multi_index_alias_sees_every_member() {
    let (app, _dir) = app().await;
    seed(&app).await;
    let all = (PER_INDEX * 3) as u64;

    let (_, count) = call(&app, "GET", "/kb/_count", Value::Null).await;
    assert_eq!(
        count["count"].as_u64(),
        Some(all),
        "_count through the alias must cover all three members: {count}"
    );

    let (_, search) = call(
        &app,
        "POST",
        "/kb/_search",
        json!({"query": {"match_all": {}}, "size": 0}),
    )
    .await;
    assert_eq!(
        search["hits"]["total"]["value"].as_u64(),
        Some(all),
        "_search through the alias must cover all three members: {search}"
    );

    // The single-member case is the one a narrowing fix would break.
    let (_, solo) = call(&app, "GET", "/solo/_count", Value::Null).await;
    assert_eq!(
        solo["count"].as_u64(),
        Some(PER_INDEX as u64),
        "an alias over one index still answers for that index: {solo}"
    );
    let (_, concrete) = call(&app, "GET", "/kb-a/_count", Value::Null).await;
    assert_eq!(concrete["count"].as_u64(), Some(PER_INDEX as u64));
}

/// A scroll through the alias must walk every document AND report the index
/// each hit truly came from — `(_index, _id)` is the key reindex, migration,
/// backup and CDC consumers use, and ids collide across the members.
#[tokio::test]
async fn a_scroll_through_an_alias_walks_every_member_and_labels_each_hit() {
    let (app, _dir) = app().await;
    seed(&app).await;

    let (st, mut page) = call(
        &app,
        "POST",
        "/kb/_search?scroll=2m",
        json!({"query": {"match_all": {}}, "size": 50}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "scroll start: {page}");
    let mut sid = page["_scroll_id"].as_str().map(str::to_string);
    let mut hits: Vec<(String, String, String)> = Vec::new();

    for _ in 0..16 {
        let page_hits = page["hits"]["hits"].as_array().cloned().unwrap_or_default();
        if page_hits.is_empty() {
            break;
        }
        for h in &page_hits {
            hits.push((
                h["_index"].as_str().unwrap_or_default().to_string(),
                h["_id"].as_str().unwrap_or_default().to_string(),
                h["_source"]["home"]
                    .as_str()
                    .unwrap_or_default()
                    .to_string(),
            ));
        }
        let Some(id) = sid.clone() else { break };
        let (st, next) = call(
            &app,
            "POST",
            "/_search/scroll",
            json!({"scroll": "2m", "scroll_id": id}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "continuation: {next}");
        sid = next["_scroll_id"].as_str().map(str::to_string).or(sid);
        page = next;
    }

    assert_eq!(hits.len(), PER_INDEX * 3, "every member must be walked");

    let mislabelled: Vec<_> = hits
        .iter()
        .filter(|(reported, _, home)| reported != home)
        .take(5)
        .collect();
    assert!(
        mislabelled.is_empty(),
        "hits must report the index they came from, not the alias: {mislabelled:?}"
    );

    let distinct: std::collections::HashSet<(&str, &str)> = hits
        .iter()
        .map(|(i, id, _)| (i.as_str(), id.as_str()))
        .collect();
    assert_eq!(
        distinct.len(),
        PER_INDEX * 3,
        "(_index, _id) must be distinct — ids collide across the members"
    );
}

//! Writes through a multi-index alias must follow ES's write-index rule.
//!
//! `Engine::get_index` resolves an alias to its FIRST backing index (fine for
//! reads by name), and every single-document write used to reach the store
//! through it. A two-index alias therefore accepted `PUT /alias/_doc/1` with
//! 201 and wrote the document to whichever member happened to be listed
//! first, even when the other member carried `is_write_index: true`. ES
//! refuses the ambiguous shape and routes the designated one.
//!
//! All document writes now resolve through `Engine::write_target`: one backing
//! index, or exactly one `is_write_index: true`; otherwise ES's 400. The bulk
//! path uses the same helper and rewrites the item's target so its result and
//! storage agree.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn ndjson(app: &axum::Router, path: &str, body: String) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(path)
                .header("content-type", "application/x-ndjson")
                .body(Body::from(body))
                .unwrap(),
        )
        .await
        .unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn docs_in(app: &axum::Router, index: &str) -> u64 {
    let (status, body) = call(app, "POST", &format!("/{index}/_refresh"), Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let (status, body) = call(app, "GET", &format!("/{index}/_count"), Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    body["count"].as_u64().unwrap_or(0)
}

fn refusal(body: &Value) -> &str {
    body.pointer("/error/root_cause/0/reason")
        .and_then(Value::as_str)
        .or_else(|| body.get("error").and_then(Value::as_str))
        .unwrap_or_default()
}

#[tokio::test]
async fn writes_follow_the_alias_write_index_and_refuse_ambiguity() {
    let (app, _dir) = app().await;
    for ix in ["i1", "i2"] {
        let (status, body) = call(&app, "PUT", &format!("/{ix}"), json!({})).await;
        assert_eq!(status, StatusCode::OK, "{body}");
    }
    let (status, body) = call(
        &app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "i1", "alias": "multi"}},
            {"add": {"index": "i2", "alias": "multi"}},
        ]}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");

    // Ambiguous: more than one backing index, none designated. ES refuses and
    // nothing is written.
    let (status, body) = call(&app, "PUT", "/multi/_doc/1", json!({"t": "one"})).await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    assert_eq!(
        body.pointer("/error/type").and_then(Value::as_str),
        Some("illegal_argument_exception"),
        "{body}"
    );
    assert!(
        refusal(&body).contains("no write index is defined for alias [multi]"),
        "{body}"
    );
    assert_eq!(
        docs_in(&app, "i1").await,
        0,
        "no index received the refused write"
    );
    assert_eq!(docs_in(&app, "i2").await, 0);

    // Designate i2: the write must land there, not on the first member.
    let (status, body) = call(
        &app,
        "PUT",
        "/i2/_alias/multi",
        json!({"is_write_index": true}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let (status, body) = call(&app, "PUT", "/multi/_doc/2", json!({"t": "two"})).await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    assert_eq!(
        body["_index"], "i2",
        "response names the concrete index: {body}"
    );
    let (status, body) = call(&app, "GET", "/i2/_doc/2", Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let (status, body) = call(&app, "GET", "/multi/_doc/2", Value::Null).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "get via the alias uses the write index: {body}"
    );
    assert_eq!(body["_index"], "i2", "{body}");
    let (status, _) = call(&app, "HEAD", "/multi/_doc/2", Value::Null).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "head via the alias uses the write index"
    );
    let (status, _) = call(&app, "GET", "/i1/_doc/2", Value::Null).await;
    assert_eq!(status, StatusCode::NOT_FOUND);
    assert_eq!(docs_in(&app, "i1").await, 0);
    assert_eq!(docs_in(&app, "i2").await, 1);

    // Every document-write entry point takes the same route.
    let (status, body) = call(&app, "POST", "/multi/_doc", json!({"t": "auto"})).await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    assert_eq!(body["_index"], "i2", "{body}");

    let (status, body) = call(&app, "PUT", "/multi/_create/3", json!({"t": "created"})).await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    assert_eq!(body["_index"], "i2", "{body}");

    let (status, body) = call(
        &app,
        "POST",
        "/multi/_update/2",
        json!({"doc": {"t": "updated"}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["_index"], "i2", "{body}");
    let (_, doc) = call(&app, "GET", "/i2/_doc/2", Value::Null).await;
    assert_eq!(doc["_source"]["t"], "updated", "{doc}");

    let (status, body) = call(&app, "DELETE", "/multi/_doc/2", Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["_index"], "i2", "{body}");

    // Bulk resolves and rewrites the target too, including the item result.
    let (status, body) = ndjson(
        &app,
        "/_bulk",
        "{\"index\":{\"_index\":\"multi\",\"_id\":\"9\"}}\n{\"t\":\"bulk\"}\n".to_string(),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["items"][0]["index"]["_index"], "i2", "{body}");
    assert_eq!(body["items"][0]["index"]["status"], 201, "{body}");

    // A one-index alias needs no designation.
    let (status, body) = call(
        &app,
        "POST",
        "/_aliases",
        json!({"actions": [{"add": {"index": "i1", "alias": "solo"}}]}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let (status, body) = call(&app, "PUT", "/solo/_doc/7", json!({"t": "solo"})).await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    assert_eq!(body["_index"], "i1", "{body}");

    // Two designated write indices are refused like the ambiguous shape.
    let (status, body) = call(
        &app,
        "PUT",
        "/i1/_alias/multi",
        json!({"is_write_index": true}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let (status, body) = call(&app, "PUT", "/multi/_doc/10", json!({"t": "ten"})).await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    assert!(
        refusal(&body).contains("has more than one write index"),
        "{body}"
    );
}

//! Issue #1092: an index's analysis configuration must be observable over the
//! wire exactly as search applies it.
//!
//! Before the fix:
//! * `GET /{index}/_settings` replayed an in-memory display copy of the create
//!   body. After a restart that copy is empty, so a declared
//!   `analysis.analyzer.default` stemmer vanished from the response while
//!   search kept stemming — and a top-level `analysis` beside an `index` block
//!   was never echoed at all.
//! * `POST /{index}/_analyze` ignored the index entirely: an inline lowercase
//!   splitter answered every request, so a stemmer index showed `bagels`
//!   where search indexes `bagel`.
//!
//! An agent verifying "is my stemmer on?" through the ES wire concluded it was
//! off. Elasticsearch and OpenSearch are referenced for wire semantics only
//! (public API docs: `_analyze` without `analyzer`/`field` uses the index's
//! default analyzer; `field` uses that field's analyzer); no code is reproduced.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

fn app_over(dir: &std::path::Path) -> axum::Router {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    xerj_api::router::build_es_compat_router(state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, body)
}

fn with_body(method: &str, path: &str, body: Value) -> Request<Body> {
    Request::builder()
        .method(method)
        .uri(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

fn get(path: &str) -> Request<Body> {
    Request::get(path).body(Body::empty()).expect("request")
}

async fn analyze(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Vec<String>, Value) {
    let (st, resp) = send(app, with_body("POST", path, body)).await;
    let tokens = resp["tokens"]
        .as_array()
        .map(|a| {
            a.iter()
                .map(|t| t["token"].as_str().unwrap_or_default().to_string())
                .collect()
        })
        .unwrap_or_default();
    (st, tokens, resp)
}

const STEM: &str = "/stem";

async fn create_stem_index(app: &axum::Router) {
    let (st, body) = send(
        app,
        with_body(
            "PUT",
            STEM,
            json!({
                "settings": { "analysis": { "analyzer": { "default": { "type": "stemmer" } } } },
                "mappings": { "properties": {
                    "t": { "type": "text" }, "tag": { "type": "keyword" }
                }}
            }),
        ),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create: {body}");
}

#[tokio::test]
async fn settings_report_the_analysis_in_force_across_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");
    let want = json!({ "analyzer": { "default": { "type": "stemmer" } } });
    {
        let app = app_over(dir.path());
        create_stem_index(&app).await;
        let (st, body) = send(&app, get("/stem/_settings")).await;
        assert_eq!(st, StatusCode::OK);
        assert_eq!(
            body.pointer("/stem/settings/index/analysis"),
            Some(&want),
            "{body}"
        );
    }
    // Restart: only what reached disk survives.
    let app = app_over(dir.path());
    let (_, body) = send(&app, get("/stem/_settings")).await;
    assert_eq!(
        body.pointer("/stem/settings/index/analysis"),
        Some(&want),
        "the declared stemmer must still be reported after a restart: {body}"
    );
    let (_, body) = send(&app, get("/stem")).await;
    assert_eq!(
        body.pointer("/stem/settings/index/analysis"),
        Some(&want),
        "GET /{{index}} reports the same block: {body}"
    );
    // Search still stems after the restart — the thing being reported.
    let (_, tokens, _) = analyze(&app, "/stem/_analyze", json!({ "text": "bagels" })).await;
    assert_eq!(tokens, ["bagel"]);
}

#[tokio::test]
async fn top_level_analysis_beside_an_index_block_is_reported() {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    let (st, body) = send(
        &app,
        with_body(
            "PUT",
            "/both",
            json!({ "settings": {
                "index": { "number_of_replicas": 0 },
                "analysis": { "analyzer": { "default": { "type": "stemmer" } } }
            }}),
        ),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create: {body}");
    let (_, body) = send(&app, get("/both/_settings")).await;
    assert_eq!(
        body.pointer("/both/settings/index/analysis/analyzer/default/type"),
        Some(&json!("stemmer")),
        "{body}"
    );
    assert_eq!(
        body.pointer("/both/settings/index/number_of_replicas"),
        Some(&json!("0"))
    );
}

#[tokio::test]
async fn analyze_uses_the_index_default_and_the_field_mapping() {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    create_stem_index(&app).await;

    // No analyzer, no field → the index's default analyzer.
    let (st, tokens, body) =
        analyze(&app, "/stem/_analyze", json!({ "text": "Bagels running" })).await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(tokens, ["bagel", "run"], "{body}");

    // A text field → the analyzer that field is indexed with.
    let (_, tokens, _) = analyze(
        &app,
        "/stem/_analyze",
        json!({ "field": "t", "text": "Bagels running" }),
    )
    .await;
    assert_eq!(tokens, ["bagel", "run"]);

    // A keyword field → one exact token.
    let (_, tokens, _) = analyze(
        &app,
        "/stem/_analyze",
        json!({ "field": "tag", "text": "Bagels running" }),
    )
    .await;
    assert_eq!(tokens, ["Bagels running"]);

    // An explicitly named built-in still wins over the default.
    let (_, tokens, _) = analyze(
        &app,
        "/stem/_analyze",
        json!({ "analyzer": "standard", "text": "Bagels running" }),
    )
    .await;
    assert_eq!(tokens, ["bagels", "running"]);

    // An index WITHOUT an analysis block analyses as `standard`.
    let (st, _) = send(&app, with_body("PUT", "/plain", json!({}))).await;
    assert_eq!(st, StatusCode::OK);
    let (_, tokens, _) =
        analyze(&app, "/plain/_analyze", json!({ "text": "Bagels running" })).await;
    assert_eq!(tokens, ["bagels", "running"]);
    let (_, body) = send(&app, get("/plain/_settings")).await;
    assert!(
        body.pointer("/plain/settings/index/analysis").is_none(),
        "no analysis is in force, so none is reported: {body}"
    );
}

#[tokio::test]
async fn analyze_refuses_what_it_cannot_honour() {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    create_stem_index(&app).await;

    for (path, body) in [
        ("/stem/_analyze", json!({ "analyzer": "nope", "text": "x" })),
        ("/_analyze", json!({ "analyzer": "nope", "text": "x" })),
        ("/_analyze", json!({ "field": "t", "text": "x" })),
        (
            "/_analyze",
            json!({ "tokenizer": "standard", "filter": ["no_such_filter"], "text": "x" }),
        ),
        (
            "/_analyze",
            json!({ "tokenizer": "no_such_tokenizer", "text": "x" }),
        ),
        (
            "/_analyze",
            json!({ "normalizer": "lowercase", "text": "x" }),
        ),
    ] {
        let (st, _, resp) = analyze(&app, path, body.clone()).await;
        assert_eq!(st, StatusCode::BAD_REQUEST, "{path} {body}: {resp}");
        assert_eq!(
            resp.pointer("/error/type"),
            Some(&json!("illegal_argument_exception")),
            "{resp}"
        );
    }

    // Unknown index → 404, as ES and OpenSearch answer.
    let (st, _, _) = analyze(&app, "/missing/_analyze", json!({ "text": "x" })).await;
    assert_eq!(st, StatusCode::NOT_FOUND);

    // The global endpoint runs the real built-in pipelines.
    let (st, tokens, _) = analyze(
        &app,
        "/_analyze",
        json!({ "analyzer": "english", "text": "the running bagels" }),
    )
    .await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(tokens, ["run", "bagel"]);
    let (_, tokens, _) = analyze(&app, "/_analyze", json!({ "text": "Foo BAR" })).await;
    assert_eq!(tokens, ["foo", "bar"]);
}

/// An ad-hoc chain is built by the same registry code index creation uses,
/// with the Elasticsearch/OpenSearch defaults (filters alone → `keyword`
/// tokenizer) — it used to be answered by the `standard` splitter whatever
/// it named.
#[tokio::test]
async fn analyze_builds_an_adhoc_chain() {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    let (st, tokens, body) = analyze(
        &app,
        "/_analyze",
        json!({ "tokenizer": "whitespace", "filter": ["lowercase"], "text": "Foo-Bar BAZ" }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(tokens, ["foo-bar", "baz"]);

    let (_, tokens, _) = analyze(
        &app,
        "/_analyze",
        json!({ "filter": ["lowercase"], "text": "Foo Bar" }),
    )
    .await;
    assert_eq!(
        tokens,
        ["foo bar"],
        "filters alone run on the keyword tokenizer"
    );
}

//! Executable statement of issue #201: a minted API-key secret must not be
//! recoverable from `<data_dir>/api_keys.json`, `GET /_security/_authenticate`
//! must describe the credential that actually made the call, and the
//! tamper-evident audit chain must survive a restart.
//!
//! All three used to be false at once:
//!
//! * `ApiKeyRecord.secret` held the plaintext credential and the auth path
//!   compared plaintext to plaintext, so one readable file — a backup, a
//!   snapshot, a container layer, a support bundle — handed over every live
//!   credential on the node.
//! * `security_authenticate` answered `{"username":"xerj","roles":
//!   ["superuser"]}` unconditionally, so a key with two index grants was told
//!   it was the superuser and an auditor was told every key was.
//! * the audit ring lived only in `AuditLog`'s `VecDeque`, so the evidence of
//!   an incident died with the process the incident was about.
//!
//! Every assertion below fails on the pre-fix tree.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use http_body_util::BodyExt;
use serde_json::Value;
use tower::ServiceExt;
use xerj_api::{
    router::{build_es_compat_router, build_native_router},
    state::AppState,
};
use xerj_common::{config::Config, metrics::Metrics};
use xerj_engine::Engine;

const ADMIN_KEY: &str = "admin-secret-key-for-hash-at-rest-test";

/// An auth-enabled node over `data_dir`. Returned by value so a test can drop
/// it and build a second one over the same directory — that is what "restart"
/// means here.
fn state_over(data_dir: &str) -> AppState {
    let mut config = Config::default();
    config.server.data_dir = data_dir.to_string();
    config.auth.enabled = true;
    config.auth.admin_api_key = ADMIN_KEY.to_string();
    let metrics = Metrics::new().expect("metrics");
    let engine = Engine::new(config.clone()).expect("engine");
    AppState::new(config, engine, metrics)
}

async fn send(
    app: &axum::Router,
    method: &str,
    uri: &str,
    auth: &str,
    body: &str,
) -> (StatusCode, Value) {
    let mut builder = Request::builder()
        .method(method)
        .uri(uri)
        .header("content-type", "application/json");
    if !auth.is_empty() {
        builder = builder.header("authorization", auth);
    }
    let req = builder.body(Body::from(body.to_string())).expect("request");
    let resp = app.clone().oneshot(req).await.expect("response");
    let status = resp.status();
    let bytes = resp.into_body().collect().await.expect("body").to_bytes();
    let json: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, json)
}

fn admin() -> String {
    format!("ApiKey {ADMIN_KEY}")
}

/// Mint a key and return `(id, plaintext secret, Authorization header value)`.
async fn mint(app: &axum::Router, body: &str) -> (String, String, String) {
    let (status, resp) = send(app, "POST", "/_security/api_key", &admin(), body).await;
    assert_eq!(status, StatusCode::OK, "mint should succeed: {resp}");
    let id = resp["id"].as_str().expect("id").to_string();
    let secret = resp["api_key"].as_str().expect("api_key").to_string();
    let encoded = resp["encoded"].as_str().expect("encoded").to_string();
    (id, secret, format!("ApiKey {encoded}"))
}

fn store_text(data_dir: &std::path::Path) -> String {
    std::fs::read_to_string(data_dir.join("api_keys.json")).expect("api_keys.json")
}

/// Standard-alphabet base64 with `=` padding — the encoding the auth path
/// decodes. Local to the test so it exercises the wire format rather than the
/// engine's own (crate-private) helper.
fn b64(input: &str) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let bytes = input.as_bytes();
    let mut out = String::new();
    for chunk in bytes.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        out.push(ALPHABET[((b0 >> 2) & 0x3F) as usize] as char);
        out.push(ALPHABET[(((b0 & 0x3) << 4) | (b1 >> 4)) as usize] as char);
        if chunk.len() > 1 {
            out.push(ALPHABET[(((b1 & 0xF) << 2) | (b2 >> 6)) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(ALPHABET[(b2 & 0x3F) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. Plaintext at rest
// ─────────────────────────────────────────────────────────────────────────────

/// The core of #201: the on-disk store must not contain the credential.
#[tokio::test]
async fn a_minted_secret_never_lands_on_disk_in_plaintext() {
    let dir = tempfile::tempdir().expect("tempdir");
    let state = state_over(dir.path().to_str().unwrap());
    let app = build_es_compat_router(state);

    let (_id, secret, auth) = mint(&app, r#"{"name":"leaky"}"#).await;

    let on_disk = store_text(dir.path());
    assert!(
        !on_disk.contains(&secret),
        "api_keys.json still holds the plaintext secret:\n{on_disk}"
    );

    // …and the key must still work — a "fix" that breaks authentication is
    // not a fix.
    let (status, body) = send(&app, "GET", "/_cluster/health", &auth, "").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "hashed key must authenticate: {body}"
    );
}

/// Hashing is only useful if the stored form survives the round trip that made
/// persistence worth having in the first place.
#[tokio::test]
async fn a_hashed_key_still_authenticates_after_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");
    let auth = {
        let state = state_over(dir.path().to_str().unwrap());
        let app = build_es_compat_router(state);
        let (_id, _secret, auth) = mint(&app, r#"{"name":"survivor"}"#).await;
        auth
    };

    // Restart: a brand-new Engine over the same data directory.
    let state = state_over(dir.path().to_str().unwrap());
    let app = build_es_compat_router(state);
    let (status, body) = send(&app, "GET", "/_cluster/health", &auth, "").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "key minted before the restart must still authenticate: {body}"
    );

    // A wrong secret under the right id must still be refused — proving the
    // comparison is a comparison and not "the id was found, let them in".
    let forged = b64(&format!(
        "{}:{}",
        // id of the only key in the store
        store_key_id(dir.path()),
        "not-the-secret"
    ));
    let (status, _) = send(
        &app,
        "GET",
        "/_cluster/health",
        &format!("ApiKey {forged}"),
        "",
    )
    .await;
    assert_eq!(status, StatusCode::UNAUTHORIZED, "forged secret must 401");
}

fn store_key_id(data_dir: &std::path::Path) -> String {
    let v: Value = serde_json::from_str(&store_text(data_dir)).expect("store json");
    v.as_object()
        .expect("object")
        .keys()
        .next()
        .expect("one key")
        .clone()
}

/// A node upgraded in place has a plaintext `api_keys.json` already on disk.
/// Loading it must keep the key working *and* rewrite the file without the
/// secret — a migration that only applies to new keys leaves every existing
/// deployment exposed.
#[tokio::test]
async fn a_legacy_plaintext_store_is_migrated_on_load() {
    let dir = tempfile::tempdir().expect("tempdir");
    let id = "11111111-2222-3333-4444-555555555555";
    let secret = "legacy-plaintext-secret-value";
    let legacy = format!(
        r#"{{"{id}":{{"name":"legacy","secret":"{secret}",
             "creation_ms":1753600000000,"expiration_ms":null,
             "invalidated":false}}}}"#
    );
    std::fs::write(dir.path().join("api_keys.json"), legacy).expect("seed legacy store");

    let state = state_over(dir.path().to_str().unwrap());
    let app = build_es_compat_router(state);

    let encoded = b64(&format!("{id}:{secret}"));
    let (status, body) = send(
        &app,
        "GET",
        "/_cluster/health",
        &format!("ApiKey {encoded}"),
        "",
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "a migrated legacy key must keep working: {body}"
    );

    let on_disk = store_text(dir.path());
    assert!(
        !on_disk.contains(secret),
        "legacy plaintext survived the migration:\n{on_disk}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. `_authenticate` must not lie
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn authenticate_describes_the_credential_that_called_it() {
    let dir = tempfile::tempdir().expect("tempdir");
    let state = state_over(dir.path().to_str().unwrap());
    let app = build_es_compat_router(state);

    // The admin key really is the superuser — that answer must not change.
    let (status, me) = send(&app, "GET", "/_security/_authenticate", &admin(), "").await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(me["roles"], serde_json::json!(["superuser"]));
    assert_eq!(me["authentication_type"], "realm");

    // A scoped key is not the superuser and must not be told that it is.
    let (id, _secret, scoped) = mint(
        &app,
        r#"{"name":"scoped-agent","role_descriptors":{"reader":{"indices":[
             {"names":["logs-*"],"privileges":["read"]}]}}}"#,
    )
    .await;
    let (status, me) = send(&app, "GET", "/_security/_authenticate", &scoped, "").await;
    assert_eq!(status, StatusCode::OK);
    assert_ne!(
        me["roles"],
        serde_json::json!(["superuser"]),
        "a scoped key was told it is the superuser: {me}"
    );
    assert_eq!(me["roles"], serde_json::json!(["reader"]));
    assert_eq!(me["authentication_type"], "api_key");
    assert_eq!(me["authentication_realm"]["name"], "_es_api_key");
    assert_eq!(me["api_key"]["id"], id);
    assert_eq!(me["api_key"]["name"], "scoped-agent");

    // One descriptor with several `indices` entries becomes several internal
    // `Role`s (`reader[0]`, `reader[1]`, …). The caller named one role and
    // must be told about one role, under the name they used — reporting the
    // internal encoding would describe roles that do not exist.
    let (_id3, _s3, multi) = mint(
        &app,
        r#"{"name":"multi-entry","role_descriptors":{"analyst":{"indices":[
             {"names":["logs-*"],"privileges":["read"]},
             {"names":["metrics-*"],"privileges":["read","write"]}]},
           "auditor":{"indices":[{"names":["audit-*"],"privileges":["read"]}]}}}"#,
    )
    .await;
    let (status, me) = send(&app, "GET", "/_security/_authenticate", &multi, "").await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(
        me["roles"],
        serde_json::json!(["analyst", "auditor"]),
        "roles must be the descriptor names, deduped: {me}"
    );

    // An unscoped key holds no named role at all.
    let (_id2, _s2, unscoped) = mint(&app, r#"{"name":"plain-agent"}"#).await;
    let (status, me) = send(&app, "GET", "/_security/_authenticate", &unscoped, "").await;
    assert_eq!(status, StatusCode::OK);
    assert_ne!(
        me["roles"],
        serde_json::json!(["superuser"]),
        "an unscoped key was told it is the superuser: {me}"
    );
    assert_eq!(me["authentication_type"], "api_key");
}

/// A `role_descriptors` key is caller-chosen free text, and `_authenticate`
/// reports those names in `roles` — so nothing may stop a caller from *naming*
/// a descriptor `superuser` and being handed `{"roles":["superuser"]}` back for
/// a key confined to `logs-*`. That is the same "you are more privileged than
/// you are" drift #201 exists to remove, re-entered through a name.
///
/// `superuser` and `unscoped` are the two labels xerj assigns itself in this
/// field; a caller-chosen descriptor must never be able to produce either.
#[tokio::test]
async fn a_descriptor_name_cannot_forge_a_xerj_assigned_role_label() {
    let dir = tempfile::tempdir().expect("tempdir");
    let state = state_over(dir.path().to_str().unwrap());
    let app = build_es_compat_router(state);

    for forged in ["superuser", "unscoped"] {
        let (_id, _secret, auth) = mint(
            &app,
            &format!(
                r#"{{"name":"pretender-{forged}","role_descriptors":{{"{forged}":{{"indices":[
                     {{"names":["logs-*"],"privileges":["read"]}}]}}}}}}"#
            ),
        )
        .await;

        let (status, me) = send(&app, "GET", "/_security/_authenticate", &auth, "").await;
        assert_eq!(status, StatusCode::OK);
        let roles = me["roles"].as_array().expect("roles array");
        assert!(
            !roles.iter().any(|r| r == forged),
            "a key confined to logs-* reported the reserved label {forged:?}: {me}"
        );

        // The grant itself is unaffected — this is about what the key is
        // *told* it holds, not about narrowing what it holds. A read inside
        // the granted pattern still works; one outside it is still refused.
        let (status, body) = send(&app, "GET", "/logs-app/_search", &auth, "").await;
        assert_ne!(
            status,
            StatusCode::FORBIDDEN,
            "the logs-* grant must survive the label fix: {body}"
        );
        let (status, body) = send(&app, "GET", "/.xerj-memory-alice/_search", &auth, "").await;
        assert_eq!(
            status,
            StatusCode::FORBIDDEN,
            "a logs-* key must not reach the reserved namespace: {body}"
        );
    }
}

/// `GET /_security/api_key` must describe a key with the descriptor names the
/// caller minted it with. It used to key `role_descriptors` by the internal
/// per-entry role name, so one `reader` descriptor over two index sets came
/// back as `reader[0]` and `reader[1]` — names the caller never wrote, in a
/// shape that could not be posted back to recreate the key.
#[tokio::test]
async fn listing_a_key_reports_the_descriptors_it_was_minted_with() {
    let dir = tempfile::tempdir().expect("tempdir");
    let state = state_over(dir.path().to_str().unwrap());
    let app = build_es_compat_router(state);

    let minted = r#"{"indices":[
         {"names":["logs-*"],"privileges":["read"]},
         {"names":["metrics-*"],"privileges":["read","write"]}]}"#;
    let (id, _secret, _auth) = mint(
        &app,
        &format!(r#"{{"name":"round-trip","role_descriptors":{{"reader":{minted}}}}}"#),
    )
    .await;

    let (status, body) = send(
        &app,
        "GET",
        &format!("/_security/api_key?id={id}"),
        &admin(),
        "",
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let descriptors = &body["api_keys"][0]["role_descriptors"];
    assert_eq!(
        descriptors.as_object().map(|o| o.len()),
        Some(1),
        "one descriptor was minted, so one must be listed: {descriptors}"
    );
    assert!(
        descriptors.get("reader").is_some(),
        "descriptor must keep the caller's name, not the internal encoding: {descriptors}"
    );
    let entries = descriptors["reader"]["indices"]
        .as_array()
        .expect("indices array");
    assert_eq!(
        entries.len(),
        2,
        "both index entries survive: {descriptors}"
    );
    assert_eq!(entries[0]["names"], serde_json::json!(["logs-*"]));
    assert_eq!(entries[1]["names"], serde_json::json!(["metrics-*"]));
    assert_eq!(
        entries[1]["privileges"],
        serde_json::json!(["read", "write"])
    );
}

/// A record that carries a `secret_hash` which is *present but not a hash*
/// (truncated by a half-written file, mangled by a hand edit, written by a
/// future scheme this build does not know) can never authenticate: every
/// verifier in `secret_hash.rs` denies what it cannot decode. Keeping such a
/// record would list it through `GET /_security/api_key` as a live credential
/// that nothing can ever use — the accept-then-ignore shape issue #204 tracks,
/// and exactly what the empty-hash case is already dropped to avoid.
///
/// The discriminator is `secret_hash::is_usable_hash`, not `is_empty`.
#[tokio::test]
async fn an_unusable_secret_hash_is_dropped_not_listed_as_live() {
    for (case, stored) in [
        ("empty", ""),
        ("truncated", "$ssha256$truncated"),
        ("wrong-scheme", "$argon2id$v=19$m=1,t=1,p=1$c2FsdA$aGFzaA"),
        ("bare-plaintext-leftover", "not-a-hash-at-all"),
    ] {
        let dir = tempfile::tempdir().expect("tempdir");
        let id = "99999999-8888-7777-6666-555555555555";
        std::fs::write(
            dir.path().join("api_keys.json"),
            format!(
                r#"{{"{id}":{{"name":"bricked-{case}","secret_hash":"{stored}",
                     "creation_ms":1753600000000,"expiration_ms":null,
                     "invalidated":false}}}}"#
            ),
        )
        .expect("seed store");

        let state = state_over(dir.path().to_str().unwrap());
        let app = build_es_compat_router(state);

        let (status, body) = send(&app, "GET", "/_security/api_key", &admin(), "").await;
        assert_eq!(status, StatusCode::OK, "{body}");
        assert_eq!(
            body["api_keys"].as_array().map(Vec::len),
            Some(0),
            "[{case}] a record that can never authenticate was listed as a live key: {body}"
        );

        // And it must not authenticate either — including with the stored
        // string presented as if it were the secret.
        for presented in [stored, "anything"] {
            let encoded = b64(&format!("{id}:{presented}"));
            let (status, _) = send(
                &app,
                "GET",
                "/_cluster/health",
                &format!("ApiKey {encoded}"),
                "",
            )
            .await;
            assert_eq!(
                status,
                StatusCode::UNAUTHORIZED,
                "[{case}] a record with an unusable hash authenticated"
            );
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. The audit chain must outlive the process
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn the_audit_chain_survives_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");
    {
        let state = state_over(dir.path().to_str().unwrap());
        let app = build_es_compat_router(state);
        mint(&app, r#"{"name":"audited"}"#).await;
    }

    let state = state_over(dir.path().to_str().unwrap());
    let native = build_native_router(state);
    let (status, body) = send(&native, "GET", "/_audit/_search", &admin(), "").await;
    assert_eq!(status, StatusCode::OK, "audit search: {body}");
    let entries = body["entries"].as_array().expect("entries array");
    assert!(
        entries.iter().any(|e| e["op"] == "security.api_key.create"),
        "the pre-restart audit entry is gone: {body}"
    );

    let (status, verified) = send(&native, "GET", "/_audit/_verify", &admin(), "").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "restored chain must still verify: {verified}"
    );
    assert_eq!(verified["ok"], true, "{verified}");
}

//! Route-level tests for `POST /_ask` (issue #1056) — the four hard lines of
//! the contract, exercised over the real router with real indexes:
//!
//! 1. **zero invalid DSL out** — for a battery of adversarial prompts, every
//!    200 response's `query` re-parses through `xerj_query::parse_request`;
//! 2. **unresolved phrases are 422s naming them** — unknown values, unknown
//!    fields, unroutable patterns;
//! 3. **deterministic** — the same request three times is byte-identical;
//! 4. values come back in their CANONICAL casing from the terms agg, and
//!    combos assemble eq-then-range like the gold ordering.
//!
//! The high-cardinality BM25 arm is covered with a real 1,006-distinct-value
//! field whose agg provably overflows (`sum_other_doc_count > 0`), and the
//! catalog-routing arm with a real `autoindex-catalog` index.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn native_app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_native_router(state), dir)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// NDJSON and other raw bodies (the `_bulk` wire format is not a JSON
/// document — sending it through `Value` would escape every newline).
async fn raw_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: String,
) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/x-ndjson")
                .body(Body::from(body))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn ask(app: &axum::Router, index: &str, prompt: &str) -> (StatusCode, Value) {
    json_req(
        app,
        "POST",
        "/_ask",
        json!({ "index": index, "prompt": prompt }),
    )
    .await
}

/// The USGS-earthquakes fixture shape (the harness dataset): typed fields,
/// a date `time`, and a handful of keyword values.
async fn seeded_quakes() -> (axum::Router, tempfile::TempDir) {
    let (app, dir) = app().await;
    let (status, body) = json_req(
        &app,
        "PUT",
        "/ax-quakes",
        json!({
            "mappings": { "properties": {
                "time":   { "type": "date" },
                "place":  { "type": "keyword" },
                "mag":    { "type": "double" },
                "depth":  { "type": "double" },
                "magType": { "type": "keyword" },
                "net":    { "type": "keyword" }
            }}
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "create ax-quakes failed: {body}");
    let mut ndjson = String::new();
    for (i, (net, magtype, mag, depth, time)) in [
