        json!({ "bool": { "filter": [
            { "term": { "year": 2007 } },
            { "range": { "pop": { "gt": 100_000_000 } } },
        ]}})
    );
    // adjectival continent form ("European") grounds to the stored "Europe"
    let (status, body) = ask(
