/// Grants are persisted with the key. A node restart must not silently turn a
/// scoped key back into an unscoped one — nor, worse, into a superuser.
#[tokio::test]
async fn grants_survive_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");
    let data_dir = dir.path().to_str().unwrap().to_string();

    // Scope the first node so its data-dir lock is released before the second
    // one boots over the same directory.
    let alice = {
        let state = state_over(&data_dir, true);
        let app = build_es_compat_router(state.clone());
        seed_two_brains(&app).await;
        let admin = format!("ApiKey {ADMIN_KEY}");
        let alice = mint(&app, &admin, &brain_grant("alice", r#""read","write""#)).await;
        drop(app);
        drop(state);
        alice
    };

    // Boot a second engine over the same data directory — the restart.
    let restarted = build_es_compat_router(state_over(&data_dir, true));

    let (status, resp) = send(&restarted, "GET", "/_graph/alice/overview", &alice, "").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "the grant must survive restart, got {status}: {resp}"
    );
    let (status, resp) = send(&restarted, "GET", "/_graph/bob/overview", &alice, "").await;
    assert_eq!(
        status,
        StatusCode::FORBIDDEN,
        "the boundary must survive restart, got {status}: {resp}"
    );
}

//! Issue #450: `_delete_by_query` (and `_update_by_query`) through a
//! multi-index alias silently operate on only the FIRST member and report a
//! complete success.
//!
//! Both handlers begin with `Engine::get_index(&index)`, which resolves an
//! alias to `aliased.first()` — one member. A destructive by-query against a
//! 3-member alias therefore deletes a third of the corpus and answers
//! `{"deleted": N, "total": N}` with no partial-failure flag: the counts are
//! internally consistent and a caller cannot tell it from a correct run. This
//! is strictly worse than the read-path truncation of #433/#449 — a short read
//! is recoverable, a short delete leaves the caller believing the operation
//! completed.
//!
//! The read paths were taught to fan an alias out to every member in #433; the
//! two by-query WRITE paths were carved out as this separate issue. These
//! tests go through the real HTTP routes, the only place the selector is
//! resolved.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

const MEMBERS: [&str; 3] = ["idx-a", "idx-b", "idx-c"];
const PER_INDEX: usize = 4;

/// Three indices, `PER_INDEX` docs each, all behind the alias `tri`.
async fn seed(app: &axum::Router) {
    for member in MEMBERS {
        let (st, _) = call(
            app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {"v": {"type": "long"}, "home": {"type": "keyword"}}}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        for i in 0..PER_INDEX {
            let (st, _) = call(
                app,
                "POST",
                &format!("/{member}/_doc/{i}"),
                json!({"v": i, "home": member}),
            )
            .await;
            assert_eq!(st, StatusCode::CREATED, "index doc {i} into {member}");
        }
        let (st, _) = call(app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }
    let (st, _) = call(
        app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "idx-a", "alias": "tri"}},
            {"add": {"index": "idx-b", "alias": "tri"}},
            {"add": {"index": "idx-c", "alias": "tri"}}
        ]}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create alias tri");
}

async fn count(app: &axum::Router, index: &str) -> u64 {
    let (_, body) = call(app, "GET", &format!("/{index}/_count"), Value::Null).await;
    body.get("count")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX)
}

/// The #450 bug: a `_delete_by_query` through a 3-member alias must delete
/// every matching document in every member, not just the first member's share.
#[tokio::test]
async fn delete_by_query_through_a_multi_index_alias_deletes_every_member() {
    let (app, _dir) = app().await;
    seed(&app).await;

    let total = (MEMBERS.len() * PER_INDEX) as u64;
    assert_eq!(
        count(&app, "tri").await,
        total,
        "precondition: the alias must see every member's documents"
    );

    let (status, body) = call(
        &app,
        "POST",
        "/tri/_delete_by_query",
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_delete_by_query status: {body}");

    // The whole corpus behind the alias matched match_all, so a complete run
    // deletes all of it. The bug reports only the first member's share.
    assert_eq!(
        body.get("deleted").and_then(Value::as_u64),
        Some(total),
        "_delete_by_query through a {}-member alias must delete every member's docs, \
         not just the first member's (#450): {body}",
        MEMBERS.len()
    );

    // And it must actually be gone on disk in every member, not merely counted.
    for member in MEMBERS {
        assert_eq!(
            count(&app, member).await,
            0,
            "member {member} still holds documents after _delete_by_query through the alias (#450)"
        );
    }
}

/// The `_update_by_query` sibling: it shares the same `get_index → first`
/// defect, so an update through the alias must reindex every member's matching
/// documents, not just the first member's.
#[tokio::test]
async fn update_by_query_through_a_multi_index_alias_updates_every_member() {
    let (app, _dir) = app().await;
    seed(&app).await;

    let total = (MEMBERS.len() * PER_INDEX) as u64;

    let (status, body) = call(
        &app,
        "POST",
        "/tri/_update_by_query",
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_update_by_query status: {body}");
    assert_eq!(
        body.get("updated").and_then(Value::as_u64),
        Some(total),
        "_update_by_query through a {}-member alias must touch every member's docs, \
         not just the first member's (#450): {body}",
        MEMBERS.len()
    );

    // Every member is still fully present (update reindexes in place; nothing
    // is lost) — the point is that the count is honest about the whole corpus.
    for member in MEMBERS {
        assert_eq!(
            count(&app, member).await,
            PER_INDEX as u64,
            "member {member} document count changed unexpectedly after _update_by_query"
        );
    }
}

//! Issue #950: `POST /{index}/_cache/clear` was a stub — it resolved the
//! indices and reported an honest `_shards` block but freed nothing, so the
//! one operator lever for a node pinned above its memory watermark was not
//! connected to `Index::release_memory`. It must flush, release the hydrated
//! per-segment caches, keep the response shape, and lose no data.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut b = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        b = b.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let res = app.clone().oneshot(b.body(body).unwrap()).await.unwrap();
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// FAIL-BEFORE: with the handler reverted to the stub, `after == 0` fails
/// (the caches stay resident) and the unrefreshed doc count is unchanged only
/// because nothing ran.
#[tokio::test]
async fn cache_clear_releases_hydrated_caches_and_loses_nothing() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    let engine = state.engine.clone();
    let app = xerj_api::router::build_es_compat_router(state);

    call(
        &app,
        "PUT",
        "/docs",
        json!({"mappings":{"properties":{"body":{"type":"text"}}}}),
    )
    .await;
    for i in 0..40 {
        call(
            &app,
            "PUT",
            &format!("/docs/_doc/d{i}"),
            json!({"body": format!("document number {i}")}),
        )
        .await;
    }
    call(&app, "POST", "/docs/_refresh", Value::Null).await;
    // Hydrate the per-segment caches with a size>0 search.
    let (st, _) = call(
        &app,
        "POST",
        "/docs/_search",
        json!({"query":{"match":{"body":"document"}},"size":10}),
    )
    .await;
    assert_eq!(st, StatusCode::OK);
    let idx = engine.get_index("docs").expect("index");
    let before = idx.total_cache_entries();
    assert!(
        before > 0,
        "a query should have hydrated the caches, got {before}"
    );

    // A doc written but never refreshed must survive the clear (flush first).
    call(
        &app,
        "PUT",
        "/docs/_doc/late",
        json!({"body": "document late"}),
    )
    .await;

    let (st, body) = call(&app, "POST", "/docs/_cache/clear", Value::Null).await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(
        body,
        json!({"_shards": {"total": 1, "successful": 1, "failed": 0}})
    );

    let after = idx.total_cache_entries();
    assert_eq!(
        after, 0,
        "#950: _cache/clear must release caches (was {before}, now {after})"
    );

    call(&app, "POST", "/docs/_refresh", Value::Null).await;
    let (_, c) = call(
        &app,
        "POST",
        "/docs/_count",
        json!({"query":{"match_all":{}}}),
    )
    .await;
    assert_eq!(c["count"], 41, "clear must lose no document: {c}");
}

//! #1201 + #1202 endpoint coverage: the shared `_cat` common params (`h`, `v`,
//! `bytes`) through the real router, and `_cat/segments` reporting one row per
//! LIVE durable segment instead of a fabricated `_0` row.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

/// Issue a request; return status + body. JSON when the body parses, raw text
/// otherwise (the `_cat` text format is not JSON).
async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, String) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (status, String::from_utf8(bytes.to_vec()).unwrap())
}

async fn call_json(app: &axum::Router, method: &str, path: &str, body: Value) -> Value {
    let (st, text) = call(app, method, path, body).await;
    assert_eq!(st, StatusCode::OK, "{method} {path}: {text}");
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{path} body not JSON ({e}): {text}"))
}

/// Create an index, index one doc, refresh — the minimal state every test
/// below starts from.
async fn seeded_index(app: &axum::Router, name: &str) {
    let (st, body) = call(
        app,
        "PUT",
        &format!("/{name}"),
        json!({"mappings": {"properties": {"v": {"type": "keyword"}}}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create {name}: {body}");
    let (st, body) = call(app, "PUT", &format!("/{name}/_doc/1"), json!({"v": "one"})).await;
    assert_eq!(st, StatusCode::CREATED, "index doc into {name}: {body}");
    let (st, body) = call(app, "POST", &format!("/{name}/_refresh"), Value::Null).await;
    assert_eq!(st, StatusCode::OK, "refresh {name}: {body}");
}

// ── #1201: h / v / bytes through the router ──────────────────────────────────

/// `h` selects and reorders the printed columns; `v` adds the header row.
#[tokio::test]
async fn cat_indices_h_selects_and_v_adds_header() {
    let (app, _dir) = app().await;
    seeded_index(&app, "books").await;

    let (st, text) = call(
        &app,
        "GET",
        "/_cat/indices?h=docs.count,index&v=true",
        Value::Null,
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{text}");
    let lines: Vec<&str> = text.trim_end().lines().collect();
    assert_eq!(
        lines[0], "docs.count index",
        "header is the selected columns in request order"
    );
    assert_eq!(lines.len(), 2, "one header + one row: {text}");
    assert!(
        lines[1].starts_with("1 ") && lines[1].ends_with(" books"),
        "row carries the values in the selected order: {text}"
    );

    // json honours h the same way, without the header.
    let rows = call_json(
        &app,
        "GET",
        "/_cat/indices?h=docs.count,index&format=json",
        Value::Null,
    )
    .await;
    let row = rows[0].as_object().unwrap();
    let keys: Vec<&str> = row.keys().map(|k| k.as_str()).collect();
    assert_eq!(
        keys,
        vec!["docs.count", "index"],
        "json keys follow the h order: {rows}"
    );
}

/// `bytes=b` re-renders the size columns as plain byte integers; an unknown
