    );

    members[primary_a].handle.clear_shard_handler();
    let (status, got) = get(&members[writer].app, &format!("/orders/_doc/{id_a}")).await;
    assert_eq!(
        status,
        StatusCode::NOT_FOUND,
        "a primary that is down still does not serve a copy the delete removed: {status} {got}"
    );
    restore_shard_handler(&members[primary_a]);

    index_titled(&members[writer].app, &id_a, "alpha").await;
    index_titled(&members[writer].app, &id_b, "beta").await;
    let (status, body) = post_json(
        &members[writer].app,
        "/orders/_delete_by_query",
        json!({ "query": { "ids": { "values": [id_a] } } }),
    )
    .await;
    assert!(status.is_success(), "ids delete_by_query: {status} {body}");
    assert_eq!(
        body.get("deleted").and_then(|v| v.as_u64()),
        Some(1),
        "{body}"
    );
    assert!(user_source(&members[primary_a], &id_a).await.is_none());
    assert!(replica_source(&members[replica_a], shard_a, &id_a)
        .await
        .is_none());
    assert_eq!(
        user_source(&members[primary_b], &id_b)
            .await
            .expect("primary b")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("beta"),
        "the other shard stays"
    );
    assert_eq!(
        replica_source(&members[replica_b], shard_b, &id_b)
            .await
            .expect("replica b")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("beta")
    );

    index_titled(&members[writer].app, &id_a, "alpha").await;
    let (status, body) = post_json(
        &members[writer].app,
        "/orders/_delete_by_query",
        json!({ "query": { "match": { "title": "alpha" } } }),
    )
    .await;
    assert!(
        status.is_success(),
        "match delete_by_query: {status} {body}"
    );
    assert_eq!(
        body.get("deleted").and_then(|v| v.as_u64()),
        Some(1),
        "a non-ids query still deletes on the owning primary: {body}"
    );
    assert!(user_source(&members[primary_a], &id_a).await.is_none());
    assert!(replica_source(&members[replica_a], shard_a, &id_a)
        .await
        .is_none());
    assert_eq!(
        user_source(&members[primary_b], &id_b)
            .await
            .expect("primary b")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("beta")
    );
    assert_eq!(
        replica_source(&members[replica_b], shard_b, &id_b)
            .await
            .expect("replica b")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("beta")
    );

    index_titled(&members[writer].app, &id_a, "alpha").await;
    let (status, body) = post_json(
        &members[writer].app,
        "/orders/_delete_by_query",
        json!({ "query": { "match_all": {} }, "max_docs": 1 }),
    )
    .await;
    assert!(
        status.is_success(),
        "max_docs delete_by_query: {status} {body}"
    );
    assert_eq!(
        body.get("deleted").and_then(|v| v.as_u64()),
        Some(1),
        "max_docs is one budget for the index, not one per shard: {body}"
    );
    let left_a = user_source(&members[primary_a], &id_a).await.is_some();
    let left_b = user_source(&members[primary_b], &id_b).await.is_some();
    assert_eq!(
        left_a as u8 + left_b as u8,
        1,
        "exactly one primary still has its document"
    );
    assert_eq!(
        replica_source(&members[replica_a], shard_a, &id_a)
            .await
            .is_some(),
        left_a,
        "replica a matches the primary"
    );
    assert_eq!(
        replica_source(&members[replica_b], shard_b, &id_b)
            .await
            .is_some(),
        left_b,
        "replica b matches the primary"
    );

    index_titled(&members[writer].app, &id_a, "async").await;
    index_titled(&members[writer].app, &id_b, "async").await;
    let (status, body) = post_json(
        &members[writer].app,
        "/orders/_delete_by_query?wait_for_completion=false",
        json!({ "query": { "match_all": {} } }),
    )
    .await;
    assert!(
        status.is_success(),
        "async delete_by_query: {status} {body}"
    );
    let task = body
        .get("task")
        .and_then(|v| v.as_str())
        .unwrap_or_else(|| panic!("task id: {body}"))
        .to_string();
    let deadline = Instant::now() + Duration::from_secs(5);
    let completed = loop {
        let (status, got) = get(&members[writer].app, &format!("/_tasks/{task}")).await;
        if status.is_success() && got.get("completed").and_then(|v| v.as_bool()) == Some(true) {
            break got;
        }
        if Instant::now() > deadline {
            panic!("task {task} did not finish: {status} {got}");
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    };
    assert_eq!(
        completed
            .pointer("/response/deleted")
            .and_then(|v| v.as_u64()),
        Some(2),
        "{completed}"
    );
    assert!(user_source(&members[primary_a], &id_a).await.is_none());
    assert!(user_source(&members[primary_b], &id_b).await.is_none());
    assert!(replica_source(&members[replica_a], shard_a, &id_a)
        .await
        .is_none());
    assert!(replica_source(&members[replica_b], shard_b, &id_b)
        .await
        .is_none());

    index_titled(&members[writer].app, &id_a, "stay").await;
    index_titled(&members[writer].app, &id_b, "stay").await;
    members[primary_a].handle.clear_shard_handler();
    let (status, body) = post_json(
        &members[writer].app,
        "/orders/_delete_by_query",
        json!({ "query": { "match_all": {} } }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::SERVICE_UNAVAILABLE,
        "a primary that does not answer refuses before writing: {body}"
    );
    assert_eq!(
        user_source(&members[primary_a], &id_a)
            .await
            .expect("primary a")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("stay"),
        "the down primary was not deleted"
    );
    assert_eq!(
        replica_source(&members[replica_a], shard_a, &id_a)
            .await
            .expect("replica a")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("stay")
    );
    assert_eq!(
        user_source(&members[primary_b], &id_b)
            .await
            .expect("primary b")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("stay"),
        "a later primary is not deleted once an earlier one cannot be checked"
    );
    assert_eq!(
        replica_source(&members[replica_b], shard_b, &id_b)
            .await
            .expect("replica b")
            .get("title")
            .and_then(|v| v.as_str()),
        Some("stay")
    );

    for member in &members {
        let _ = member.shutdown.send(true);
    }
}

fn native_app(member: &Member) -> Router {
    xerj_api::router::build_native_router(member.state.clone())
}

fn title_of(doc: &Value) -> Option<&str> {
    doc.get("title").and_then(Value::as_str)
}

/// `POST /v1/indices/{name}/docs`, native `_bulk`, and
/// `DELETE /v1/indices/{name}/docs/{id}` accepted by a node that owns
/// neither id land on the primaries and the in-sync replicas. The
/// receiver's user index does not keep them. A primary that does not
/// answer refuses the write.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn native_doc_writes_from_a_non_owner_hit_the_primary_and_the_replica() {
    let members = ring(true).await;
    let _leader = wait_leader(&members, &[false, false, false]).await;

    let (status, body) = put_json(
        &members[0].app,
        "/orders",
        json!({
            "settings": { "index": { "number_of_replicas": 1 } },
            "mappings": { "properties": { "title": { "type": "text" } } }
        }),
    )
    .await;
    assert!(status.is_success(), "create: {status} {body}");
    for member in &members {
        wait_status(&member.app, "/orders", StatusCode::OK).await;
    }

    let mut placed: Vec<(String, usize, usize, u32)> = Vec::new();
    for n in 0..128 {
        let id = format!("n{n}");
        let Some(primary) = members
            .iter()
            .position(|member| member.engine.owns_shard("orders", &id))
        else {
            continue;
        };
        let (shard, _) = members[primary]
            .engine
            .primary_of("orders", &id)
            .expect("placement");
        let replicas = members[primary].engine.replica_nodes("orders", shard);
        if replicas.len() != 1 {
            continue;
        }
        let Some(replica) = members
            .iter()
            .position(|member| member.handle.node_id() == replicas[0])
        else {
            continue;
        };
        if placed.iter().any(|(_, owner, _, _)| *owner == primary) {
            continue;
        }
        placed.push((id, primary, replica, shard));
        if placed.len() == 2 {
            break;
        }
    }
    assert_eq!(placed.len(), 2, "two primaries: {placed:?}");
    let (id_a, primary_a, replica_a, shard_a) = placed[0].clone();
    let (id_b, primary_b, replica_b, shard_b) = placed[1].clone();
    assert_ne!(primary_a, primary_b);
    let writer = (0..3)
        .find(|n| *n != primary_a && *n != primary_b)
        .expect("a node that owns neither id");
    let native = native_app(&members[writer]);

    let (status, body) = post_json(
        &native,
        "/v1/indices/orders/docs",
        json!({ "_id": id_a, "title": "alpha" }),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED, "native index: {status} {body}");
    assert_eq!(
        body.pointer("/data/id").and_then(Value::as_str),
        Some(id_a.as_str())
    );
    assert_eq!(
        body.pointer("/data/result").and_then(Value::as_str),
        Some("created")
    );
    assert!(
        body.pointer("/data/seq_no")
            .and_then(Value::as_u64)
            .unwrap_or(0)
            >= 1,
        "native seq_no is the engine sequence, not the ES wire value: {body}"
    );
    assert!(body
        .get("request_id")
        .and_then(Value::as_str)
        .is_some_and(|id| !id.is_empty()));
    assert!(
        user_source(&members[writer], &id_a).await.is_none(),
        "the receiver stored {id_a}"
    );
    assert_eq!(
        title_of(
            &user_source(&members[primary_a], &id_a)
                .await
                .expect("primary a")
        ),
        Some("alpha")
    );
    assert_eq!(
        title_of(
            &replica_source(&members[replica_a], shard_a, &id_a)
                .await
                .expect("replica a")
        ),
        Some("alpha")
    );
    let (status, got) = get(&members[writer].app, &format!("/orders/_doc/{id_a}")).await;
    assert_eq!(status, StatusCode::OK, "ES get of a native write: {got}");
    assert_eq!(
        got.pointer("/_source/title").and_then(Value::as_str),
        Some("alpha")
    );

    let first_seq = body
        .pointer("/data/seq_no")
        .and_then(Value::as_u64)
        .unwrap();
    let (status, body) = post_json(
        &native,
        "/v1/indices/orders/docs",
        json!({ "_id": id_a, "title": "beta" }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::CREATED,
        "native update: {status} {body}"
    );
    assert_eq!(
        body.pointer("/data/result").and_then(Value::as_str),
        Some("updated")
    );
    assert!(
        body.pointer("/data/seq_no")
            .and_then(Value::as_u64)
            .unwrap_or(0)
            > first_seq,
        "an update advances seq_no: {body}"
    );
    assert_eq!(
        title_of(
            &replica_source(&members[replica_a], shard_a, &id_a)
                .await
                .expect("replica a")
        ),
        Some("beta")
    );

    let (status, body) = post_json(
        &native,
        "/v1/indices/orders/docs",
        json!([
            { "_id": id_a, "title": "array" },
            { "_id": id_b, "title": "array-b" }
        ]),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED, "native array: {status} {body}");
    assert_eq!(
        body.pointer("/data/indexed").and_then(Value::as_u64),
        Some(2),
        "{body}"
    );
    assert_eq!(
        title_of(
            &user_source(&members[primary_a], &id_a)
                .await
                .expect("primary a")
        ),
        Some("array")
    );
    assert_eq!(
        title_of(
            &user_source(&members[primary_b], &id_b)
                .await
                .expect("primary b")
        ),
        Some("array-b")
    );
    assert_eq!(
        title_of(
            &replica_source(&members[replica_b], shard_b, &id_b)
                .await
                .expect("replica b")
        ),
        Some("array-b")
    );
    assert!(user_source(&members[writer], &id_b).await.is_none());

    let (status, body) = post_json(
        &native,
        "/v1/indices/orders/docs/_bulk",
        json!({ "docs": [{ "_id": id_b, "title": "bulk" }] }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "native bulk: {status} {body}");
    assert_eq!(
        body.pointer("/data/indexed").and_then(Value::as_u64),
        Some(1),
        "{body}"
    );
    assert_eq!(
        body.pointer("/data/errors").and_then(Value::as_bool),
        Some(false),
        "{body}"
    );
    assert_eq!(
        title_of(
            &user_source(&members[primary_b], &id_b)
                .await
                .expect("primary b")
        ),
        Some("bulk")
    );
    assert_eq!(
        title_of(
            &replica_source(&members[replica_b], shard_b, &id_b)
                .await
                .expect("replica b")
        ),
        Some("bulk")
    );

    let (status, body) = delete(&native, &format!("/v1/indices/orders/docs/{id_a}")).await;
    assert_eq!(status, StatusCode::OK, "native delete: {status} {body}");
    assert_eq!(
        body.pointer("/data/result").and_then(Value::as_str),
        Some("deleted")
    );
    assert!(user_source(&members[primary_a], &id_a).await.is_none());
    assert!(replica_source(&members[replica_a], shard_a, &id_a)
        .await
        .is_none());
    assert_eq!(
        title_of(
            &user_source(&members[primary_b], &id_b)
                .await
                .expect("primary b")
        ),
        Some("bulk")
    );
    let (status, got) = get(&members[writer].app, &format!("/orders/_doc/{id_a}")).await;
    assert_eq!(
        status,
        StatusCode::NOT_FOUND,
        "ES get after native delete: {got}"
    );

    let (status, body) = delete(&native, &format!("/v1/indices/orders/docs/{id_a}")).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "a second delete of a missing document stays the native 200: {status} {body}"
    );

    members[primary_b].handle.clear_shard_handler();
    let (status, body) = post_json(
        &native,
        "/v1/indices/orders/docs",
        json!({ "_id": id_b, "title": "down" }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::SERVICE_UNAVAILABLE,
        "a primary that does not answer is a native error: {status} {body}"
    );
    assert!(
        body.get("data").is_none(),
        "the error is not the success envelope: {body}"
    );
    assert!(
        body.get("error").and_then(Value::as_str).is_some(),
        "{body}"
    );
    assert!(user_source(&members[writer], &id_b).await.is_none());
    assert_eq!(
        title_of(
            &user_source(&members[primary_b], &id_b)
                .await
                .expect("primary b")
        ),
        Some("bulk"),
        "the down primary was not written"
    );
    assert_eq!(
        title_of(
            &replica_source(&members[replica_b], shard_b, &id_b)
                .await
                .expect("replica b")
        ),
        Some("bulk")
    );
    restore_shard_handler(&members[primary_b]);

    for member in &members {
        let _ = member.shutdown.send(true);
    }
}

/// Native document writes with no cluster handle stay on the node that
/// accepted them and do not open a replica store.
#[tokio::test]
async fn cluster_disabled_native_doc_stays_on_the_node_that_received_it() {
    async fn lone() -> (Router, Router, tempfile::TempDir) {
        let dir = tempfile::tempdir().expect("tempdir");
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        assert!(!engine.has_cluster());
        let state = xerj_api::state::AppState::new(config, engine, metrics);
        let native = xerj_api::router::build_native_router(state.clone());
        let es = xerj_api::router::build_es_compat_router(state);
        (es, native, dir)
    }

    let (es_a, native_a, _dir_a) = lone().await;
    let (es_b, _native_b, _dir_b) = lone().await;
    let (status, body) = put_json(&es_a, "/local", json!({})).await;
    assert!(status.is_success(), "{status} {body}");

    let (status, body) = post_json(
        &native_a,
        "/v1/indices/local/docs",
        json!({ "_id": "1", "title": "here" }),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED, "{status} {body}");
    assert_eq!(body.pointer("/data/id").and_then(Value::as_str), Some("1"));
    assert_eq!(
        body.pointer("/data/result").and_then(Value::as_str),
        Some("created")
    );
    let (status, got) = get(&es_a, "/local/_doc/1").await;
    assert_eq!(status, StatusCode::OK, "{got}");
    assert_eq!(
        got.pointer("/_source/title").and_then(Value::as_str),
        Some("here")
    );
    let (status, _) = get(&es_b, "/local/_doc/1").await;
    assert_eq!(status, StatusCode::NOT_FOUND);
    let (status, _) = get(&es_a, "/.xerj_replica_local_0/_doc/1").await;
    assert_eq!(
        status,
        StatusCode::NOT_FOUND,
        "single-node native ingest does not open a replica store"
    );

    let (status, body) = delete(&native_a, "/v1/indices/local/docs/1").await;
    assert_eq!(status, StatusCode::OK, "{status} {body}");
    assert_eq!(
        body.pointer("/data/result").and_then(Value::as_str),
        Some("deleted")
    );
    let (status, _) = get(&es_a, "/local/_doc/1").await;
    assert_eq!(status, StatusCode::NOT_FOUND);
}

//! Issue #203: index templates, legacy templates, component templates,
//! ingest pipelines, data streams and ILM policies must survive a restart.
//!
//! Before the fix each of these lived only in an in-memory `DashMap` on
//! `Engine`. `Engine::new` restored index directories, `es_mapping.json`,
//! API keys and aliases — nothing else — so a `PUT _index_template/logs`
//! answered `200 {"acknowledged": true}` and then evaporated on the next
//! boot. The operator got no error, and the next index that should have
//! matched the template was created without it.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use tower::ServiceExt;

fn config_for(dir: &std::path::Path) -> xerj_common::config::Config {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config
}

/// Build a fresh app over `dir`. Calling this twice (with the first engine
/// dropped in between) is a restart: nothing is handed over in memory, the
/// second boot sees only what reached the disk.
fn app_over(dir: &std::path::Path) -> axum::Router {
    app_and_engine_over(dir).0
}

fn app_and_engine_over(dir: &std::path::Path) -> (axum::Router, xerj_engine::Engine) {
    let (es_app, _native_app, engine) = apps_and_engine_over(dir);
    (es_app, engine)
}

fn apps_and_engine_over(
    dir: &std::path::Path,
) -> (axum::Router, axum::Router, xerj_engine::Engine) {
    let config = config_for(dir);
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine.clone(), metrics);
    (
        xerj_api::router::build_es_compat_router(state.clone()),
        xerj_api::router::build_native_router(state),
        engine,
    )
}

fn hex_digest(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn recursive_inventory(root: &std::path::Path) -> Vec<String> {
    fn walk(root: &std::path::Path, path: &std::path::Path, out: &mut Vec<String>) {
        let mut entries: Vec<_> = std::fs::read_dir(path)
            .expect("read inventory directory")
            .map(|entry| entry.expect("read inventory entry"))
            .collect();
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let entry_path = entry.path();
            let relative = entry_path
                .strip_prefix(root)
                .expect("inventory entry under root")
                .to_string_lossy()
                .into_owned();
            let kind = entry.file_type().expect("inventory file type");
            out.push(format!(
                "{}:{relative}",
                if kind.is_dir() {
                    "d"
                } else if kind.is_symlink() {
                    "l"
                } else {
                    "f"
                }
            ));
            if kind.is_dir() {
                walk(root, &entry_path, out);
            }
        }
    }

    let mut out = Vec::new();
    walk(root, root, &mut out);
    out
}

fn recursive_storage_snapshot(root: &std::path::Path) -> Vec<String> {
    fn walk(root: &std::path::Path, path: &std::path::Path, out: &mut Vec<String>) {
        let mut entries: Vec<_> = std::fs::read_dir(path)
            .expect("read storage snapshot directory")
            .map(|entry| entry.expect("read storage snapshot entry"))
            .collect();
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let entry_path = entry.path();
            let relative = entry_path
                .strip_prefix(root)
                .expect("storage snapshot entry under root")
                .to_string_lossy();
            let kind = entry.file_type().expect("storage snapshot file type");
            if kind.is_dir() {
                out.push(format!("d:{relative}"));
                walk(root, &entry_path, out);
            } else if kind.is_symlink() {
                out.push(format!(
                    "l:{relative}->{}",
                    std::fs::read_link(&entry_path)
                        .expect("read storage snapshot symlink")
                        .to_string_lossy()
                ));
            } else {
                let bytes = std::fs::read(&entry_path).expect("read storage snapshot file");
                out.push(format!(
                    "f:{relative}:{}:{}",
                    bytes.len(),
                    hex_digest(&bytes)
                ));
            }
        }
    }

    let mut out = Vec::new();
    walk(root, root, &mut out);
    out
}

#[derive(Debug, PartialEq, Eq)]
struct ManagedInventory {
    indices: Vec<String>,
    aliases: Vec<(String, Vec<String>)>,
    index_templates: Vec<String>,
    legacy_templates: Vec<String>,
    component_templates: Vec<String>,
    pipelines: Vec<String>,
    data_streams: Vec<String>,
    ilm_policies: Vec<String>,
    directory_entries: Vec<String>,
}

async fn managed_inventory(
    engine: &xerj_engine::Engine,
    dir: &std::path::Path,
) -> ManagedInventory {
    fn keys<V>(map: &dashmap::DashMap<String, V>) -> Vec<String> {
        let mut keys: Vec<_> = map.iter().map(|entry| entry.key().clone()).collect();
        keys.sort();
        keys
    }

    let mut indices: Vec<_> = engine
        .list_indices()
        .await
        .into_iter()
        .map(|index| index.name)
        .collect();
    indices.sort();
    let mut aliases: Vec<_> = engine
        .aliases
        .iter()
        .map(|entry| {
            let mut targets = entry.value().clone();
            targets.sort();
            (entry.key().clone(), targets)
        })
        .collect();
    aliases.sort();
    ManagedInventory {
        indices,
        aliases,
        index_templates: keys(&engine.templates),
        legacy_templates: keys(&engine.legacy_templates),
        component_templates: keys(&engine.component_templates),
        pipelines: keys(&engine.pipelines),
        data_streams: keys(&engine.data_streams),
        ilm_policies: keys(&engine.ilm_policies),
        directory_entries: recursive_inventory(dir),
    }
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn put_json(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    send(
        app,
        Request::put(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn get_text(app: &axum::Router, path: &str) -> (StatusCode, String) {
    let response = app
        .clone()
        .oneshot(Request::get(path).body(Body::empty()).expect("request"))
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        String::from_utf8(bytes.to_vec()).expect("utf8 body"),
    )
}

async fn delete(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::delete(path).body(Body::empty()).expect("request"),
    )
    .await
}

/// Write one of each managed object. Kept separate from the assertions so
/// the same fixture can be replayed after a restart.
async fn write_all_the_config(app: &axum::Router) {
    let (st, _) = put_json(
        app,
        "/_index_template/logs",
        json!({
            "index_patterns": ["logs-*"],
            "priority": 200,
            "template": {
                "settings": { "number_of_replicas": 0 },
                "mappings": { "properties": { "host": { "type": "keyword" } } }
            }
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "PUT _index_template");

    let (st, _) = put_json(
        app,
        "/_template/legacy-logs",
        json!({
            "index_patterns": ["legacy-*"],
            "settings": { "number_of_shards": 1 },
            "mappings": { "properties": { "msg": { "type": "text" } } }
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "PUT _template");

    let (st, _) = put_json(
        app,
        "/_component_template/base-settings",
        json!({ "template": { "settings": { "number_of_replicas": 1 } } }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "PUT _component_template");

    let (st, _) = put_json(
        app,
        "/_ingest/pipeline/tagger",
        json!({
            "description": "tag every doc",
            "processors": [ { "set": { "field": "tagged", "value": "yes" } } ]
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "PUT _ingest/pipeline");

    let (st, _) = put_json(
        app,
        "/_ilm/policy/hot-warm",
        json!({ "policy": { "phases": { "hot": { "actions": {} } } } }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "PUT _ilm/policy");

    let (st, _) = put_json(app, "/_data_stream/metrics-app", json!({})).await;
    assert_eq!(st, StatusCode::OK, "PUT _data_stream");
}

/// The read side of each managed object.
const READ_BACK: [&str; 6] = [
    "/_index_template/logs",
    "/_template/legacy-logs",
    "/_component_template/base-settings",
    "/_ingest/pipeline/tagger",
    "/_ilm/policy/hot-warm",
    "/_data_stream/metrics-app",
];

/// Read every managed object back, asserting each is present, and return the
/// exact responses so a later boot can be compared against them verbatim.
///
/// Comparing whole bodies is deliberate: it catches a partial restore (a
/// template that comes back without its mappings, a data stream that comes
/// back at generation 1) that a spot-check on one field would wave through.
async fn read_back_everything(app: &axum::Router, when: &str) -> Vec<Value> {
    let mut out = Vec::new();
    for path in READ_BACK {
        let (st, body) = get(app, path).await;
        assert_eq!(st, StatusCode::OK, "GET {path} {when}: {body}");
        out.push(body);
    }

    // Enough content assertions to prove the fixture really was written, so
    // an all-empty "equal" comparison cannot pass for a restore.
    let tmpl = &out[0]["index_templates"][0]["index_template"];
    assert_eq!(tmpl["index_patterns"][0], "logs-*", "{when}: {}", out[0]);
    assert_eq!(tmpl["priority"], 200, "{when}: {}", out[0]);
    assert_eq!(
        tmpl["template"]["mappings"]["properties"]["host"]["type"], "keyword",
        "{when}: {}",
        out[0]
    );
    assert_eq!(
        out[1]["legacy-logs"]["index_patterns"][0], "legacy-*",
        "{when}: {}",
        out[1]
    );
    assert_eq!(
        out[2]["component_templates"][0]["component_template"]["template"]["settings"]
            ["number_of_replicas"],
        1,
        "{when}: {}",
        out[2]
    );
    assert_eq!(
        out[5]["data_streams"][0]["name"], "metrics-app",
        "{when}: {}",
        out[5]
    );
    out
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn templates_pipelines_streams_and_policies_survive_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");

    let before = {
        let app = app_over(dir.path());
        write_all_the_config(&app).await;
        // Sanity: it is all readable *before* the restart, so a failure
        // below is about durability and not about the write path.
        read_back_everything(&app, "before restart").await
    }; // engine dropped — the node.lock is released, nothing is handed over

    let app = app_over(dir.path());
    let after = read_back_everything(&app, "after restart").await;

    for (path, (b, a)) in READ_BACK.iter().zip(before.iter().zip(after.iter())) {
        assert_eq!(
            b, a,
            "GET {path} answered differently after a restart\nbefore: {b}\nafter:  {a}"
        );
    }
}

/// A restored ingest pipeline must actually *run*, not merely round-trip
/// through `GET /_ingest/pipeline`. Storing the raw JSON without
/// recompiling it would leave `?pipeline=tagger` accepted and ignored.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_restored_pipeline_still_transforms_documents() {
    let dir = tempfile::tempdir().expect("tempdir");

    {
        let app = app_over(dir.path());
        write_all_the_config(&app).await;
    }

    let app = app_over(dir.path());
    let (st, body) = send(
        &app,
        Request::post("/_ingest/pipeline/tagger/_simulate")
            .header("content-type", "application/json")
            .body(Body::from(
                json!({ "docs": [ { "_source": { "host": "a" } } ] }).to_string(),
            ))
            .expect("request"),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "simulate after restart: {body}");
    assert_eq!(
        body["docs"][0]["doc"]["_source"]["tagged"], "yes",
        "the restored pipeline must still execute its processors: {body}"
    );
}

/// Deletes must be durable too — a deleted template that comes back on the
/// next boot is the same class of surprise as one that disappears.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_deleted_template_stays_deleted_across_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");

    {
        let app = app_over(dir.path());
        write_all_the_config(&app).await;
        let (st, _) = delete(&app, "/_index_template/logs").await;
        assert_eq!(st, StatusCode::OK, "DELETE _index_template");
        let (st, _) = delete(&app, "/_ingest/pipeline/tagger").await;
        assert_eq!(st, StatusCode::OK, "DELETE _ingest/pipeline");
    }

    let app = app_over(dir.path());
    let (st, _) = get(&app, "/_index_template/logs").await;
    assert_eq!(
        st,
        StatusCode::NOT_FOUND,
        "a deleted index template must not resurrect on restart"
    );
    let (st, _) = get(&app, "/_ingest/pipeline/tagger").await;
    assert_eq!(
        st,
        StatusCode::NOT_FOUND,
        "a deleted pipeline must not resurrect on restart"
    );
}

async fn post(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    send(
        app,
        Request::post(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

/// A rollover interrupted between "backing index created" and "generation
/// written" must not wedge the stream.
///
/// `rollover_data_stream` creates `.ds-<name>-00000N` on disk first and only
/// then flushes the new generation, so a `kill -9` in that window leaves the
/// index present and the document still saying N-1. Restoring N-1 verbatim
/// makes the next rollover recompute the *same* name, which `create_index`
/// refuses as `index_already_exists` — and it does so on every subsequent
/// attempt, so the stream can never roll again.
///
/// The crash window is reproduced exactly rather than approximated: the
/// backing index is left on disk and the persisted generation is rewound by
/// hand, which is byte-for-byte the state a crash at that instant leaves.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_rollover_interrupted_before_its_flush_does_not_wedge_the_stream() {
    let dir = tempfile::tempdir().expect("tempdir");

    {
        let app = app_over(dir.path());
        let (st, _) = put_json(&app, "/_data_stream/metrics-app", json!({})).await;
        assert_eq!(st, StatusCode::OK, "PUT _data_stream");
        let (st, body) = post(&app, "/metrics-app/_rollover", json!({})).await;
        assert_eq!(st, StatusCode::OK, "rollover: {body}");
    }

    // Rewind only the generation, exactly as a crash between `create_index`
    // and `flush_cluster_state` would have left it: `.ds-metrics-app-000002`
    // is on disk, the document still reads generation 1.
    let state_path = dir.path().join("cluster_state.json");
    let mut state: Value =
        serde_json::from_slice(&std::fs::read(&state_path).expect("read state")).expect("parse");
    let ds = &mut state["data_streams"]["metrics-app"];
    ds["generation"] = json!(1);
    ds["backing_indices"] = json!([".ds-metrics-app-000001"]);
    std::fs::write(&state_path, serde_json::to_vec(&state).expect("serialize")).expect("write");
    assert!(
        dir.path().join(".ds-metrics-app-000002").is_dir(),
        "fixture is wrong: the generation-2 backing index should still be on disk"
    );

    let app = app_over(dir.path());
    let (st, body) = post(&app, "/metrics-app/_rollover", json!({})).await;
    assert_eq!(
        st,
        StatusCode::OK,
        "a stream recovered from an interrupted rollover must still roll: {body}"
    );
    assert!(
        body.to_string().contains(".ds-metrics-app-000003"),
        "the next rollover must skip past the backing index the crash left \
         behind, not reissue it: {body}"
    );
}

/// A corrupt `cluster_state.json` must not be destroyed by the next write.
///
/// The node boots with empty maps and logs the failure, so without this the
/// first `PUT /_index_template/...` rewrote the file — taking whatever was
/// still legible in it along. Hand-recovery out of a damaged document is the
/// operator's last option; it should not be silently removed. The write is
/// refused and the original stays where it is. A blocked diagnostic boot must
/// not create a second recovery file either.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_corrupt_cluster_state_is_preserved_before_it_is_overwritten() {
    let dir = tempfile::tempdir().expect("tempdir");

    {
        let app = app_over(dir.path());
        write_all_the_config(&app).await;
    }

    // Truncate mid-document — the shape a torn write would have had, if the
    // rewrite were not atomic, and the shape media damage leaves.
    let state_path = dir.path().join("cluster_state.json");
    let original = std::fs::read_to_string(&state_path).expect("read state");
    let truncated = &original[..original.len() / 2];
    std::fs::write(&state_path, truncated).expect("write truncated");
    let truncated_digest = hex_digest(truncated.as_bytes());

    let (app, native_app, engine) = apps_and_engine_over(dir.path());
    let (st, _) = get(&app, "/health/live").await;
    assert_eq!(
        st,
        StatusCode::OK,
        "malformed state blocks readiness, not liveness"
    );
    for (surface, path) in [(&app, "/health/ready"), (&native_app, "/v1/health/ready")] {
        let (st, body) = get_text(surface, path).await;
        assert_eq!(st, StatusCode::SERVICE_UNAVAILABLE, "{path}");
        assert_eq!(
            body,
            "not ready: persisted cluster metadata was not accepted at boot; inspect server logs"
        );
    }
    let (st, body) = get(&app, "/_index_template/logs").await;
    assert_eq!(
        st,
        StatusCode::SERVICE_UNAVAILABLE,
        "a corrupt document cannot be restored, but an empty-map 404 would be a lie: {body}"
    );
    assert_eq!(body["error"]["type"], "cluster_state_unavailable");

    // The write that would have destroyed the evidence.
    let (st, body) = put_json(
        &app,
        "/_index_template/fresh",
        json!({ "index_patterns": ["fresh-*"] }),
    )
    .await;
    assert_eq!(
        st,
        StatusCode::SERVICE_UNAVAILABLE,
        "a management write on top of a state that did not load must be \
         refused, not acknowledged: {body}"
    );

    assert!(
        !dir.path().join("cluster_state.corrupt.json").exists(),
        "a blocked diagnostic boot must not create recovery files"
    );
    assert_eq!(
        std::fs::read_to_string(&state_path).expect("read state"),
        truncated,
        "the live document must be left exactly as it was found"
    );
    assert_eq!(
        hex_digest(&std::fs::read(&state_path).expect("hash live malformed state")),
        truncated_digest,
        "the live malformed bytes must keep the exact SHA-256"
    );

    // Moving the damaged file aside is the documented recovery, and it must
    // actually work: the next boot loads cleanly and writes are accepted again.
    drop(app);
    drop(native_app);
    drop(engine);
    std::fs::remove_file(&state_path).expect("operator moves the file aside");
    let app = app_over(dir.path());
    let (st, body) = put_json(
        &app,
        "/_index_template/fresh",
        json!({ "index_patterns": ["fresh-*"] }),
    )
    .await;
    assert_eq!(
        st,
        StatusCode::OK,
        "PUT after the operator recovered: {body}"
    );
    assert!(
        std::fs::read_to_string(&state_path)
            .expect("read state")
            .contains("fresh-*"),
        "the live document must have moved on once the node loaded cleanly"
    );
}

/// An **intact but unreadable** `cluster_state.json` must survive untouched,
/// and the node must refuse management writes until a boot can load it.
///
/// This is the worse half of the corrupt case and it was missed on the first
/// pass: the bytes are perfectly good, only the `read(2)` failed — a uid
/// change on a container volume, a backup tool's chmod, `EIO`, `EMFILE` at
/// boot. The maps come up empty, and `write_file_atomic` renames its staged
/// file over the target; `rename(2)` needs write permission on the *directory*,
/// not on the file, so a `PUT` answering
/// `{"acknowledged": true}` unlinked a fully recoverable document. Measured
/// before the fix with a read-error target that the atomic writer could replace:
///
/// ```text
/// PUT /_index_template/fresh -> 200 {"acknowledged":true}
/// cluster_state.corrupt.json exists: false
/// live file still contains "logs-*": false     <-- the operator's templates
/// ```
#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn an_unreadable_cluster_state_is_never_overwritten() {
    use std::os::unix::fs::symlink;

    let dir = tempfile::tempdir().expect("tempdir");
    {
        let app = app_over(dir.path());
        write_all_the_config(&app).await;
    }

    let state_path = dir.path().join("cluster_state.json");
    let saved_path = dir.path().join("cluster_state.saved.json");
    let original = std::fs::read_to_string(&state_path).expect("read state");
    assert!(original.contains("logs-*"), "fixture must be on disk");

    // Prove that this filesystem permits the destructive operation the latch
    // prevents. A directory at the target would be a bad oracle because rename
    // fails independently; a regular file can replace a symlink atomically.
    let control_path = dir.path().join("replaceability-control");
    let control_staged = dir.path().join("replaceability-staged");
    symlink("replaceability-control", &control_path).expect("create control self-loop");
    std::fs::write(&control_staged, b"replacement").expect("write control staging file");
    std::fs::rename(&control_staged, &control_path)
        .expect("a regular staged file must be able to replace the self-loop");
    assert_eq!(
        std::fs::read(&control_path).expect("read replacement control"),
        b"replacement"
    );
    std::fs::remove_file(&control_path).expect("remove replacement control");

    // A self-referential symlink makes read(2) fail with ELOOP even under root,
    // while remaining replaceable by the atomic writer. Keep the valid bytes
    // beside it so we can prove that the failed boot and refused writes did not
    // alter the operator's configuration.
    std::fs::rename(&state_path, &saved_path).expect("save valid cluster state");
    symlink("cluster_state.json", &state_path).expect("create cluster-state self-loop");
    let read_error = std::fs::read(&state_path).expect_err("self-loop must fail to read");
    assert_ne!(
        read_error.kind(),
        std::io::ErrorKind::NotFound,
        "the fixture must exercise the non-NotFound read-error branch"
    );
    assert!(
        std::fs::symlink_metadata(&state_path)
            .expect("inspect cluster-state self-loop")
            .file_type()
            .is_symlink(),
        "the failing target must be a symlink, not a directory"
    );

    let (app, native_app, engine) = apps_and_engine_over(dir.path());

    let (st, _) = get(&app, "/health/live").await;
    assert_eq!(st, StatusCode::OK, "the blocked node remains live");
    for (surface, path) in [(&app, "/health/ready"), (&native_app, "/v1/health/ready")] {
        let (st, _) = get(surface, path).await;
        assert_eq!(
            st,
            StatusCode::SERVICE_UNAVAILABLE,
            "{path} must expose the boot-time cluster-state fence"
        );
    }

    let (st, body) = get(&app, "/_index_template/logs").await;
    assert_eq!(
        st,
        StatusCode::SERVICE_UNAVAILABLE,
        "the diagnostic shell must not turn unloaded durable objects into a false 404: {body}"
    );
    assert_eq!(body["error"]["type"], "cluster_state_unavailable");

    // The write that used to destroy it.
    let (st, body) = put_json(
        &app,
        "/_index_template/fresh",
        json!({ "index_patterns": ["fresh-*"] }),
    )
    .await;
    assert_eq!(
        st,
        StatusCode::SERVICE_UNAVAILABLE,
        "a management write must be refused while the persisted state is \
         unloaded, not acknowledged: {body}"
    );
    assert_eq!(body["error"]["type"], "cluster_state_unavailable", "{body}");
    let reason = body["error"]["reason"].as_str().unwrap_or_default();
    for required in [
        "start a compatible XERJ build",
        "restore supported cluster_state.json bytes",
        "then restart",
    ] {
        assert!(
            reason.contains(required),
            "the refusal must give both bounded recovery actions: {body}"
        );
    }

    assert_eq!(
        std::fs::read_link(&state_path).expect("read cluster-state self-loop"),
        std::path::PathBuf::from("cluster_state.json"),
        "the refused write must not replace the unreadable target"
    );
    assert_eq!(
        std::fs::read_to_string(&saved_path).expect("read saved state"),
        original,
        "the intact document must remain recoverable, byte for byte"
    );
    assert!(
        !dir.path().join("cluster_state.corrupt.json").exists(),
        "a read error must not be mislabeled as parse corruption"
    );
    assert!(
        std::fs::read_dir(dir.path())
            .expect("list data directory")
            .all(|entry| !entry
                .expect("read data-directory entry")
                .file_name()
                .to_string_lossy()
                .starts_with("cluster_state.json.tmp.")),
        "a refused write must not even stage a uniquely named temp file"
    );

    // And the refusal is not a one-off. Reads remain unavailable too: the
    // node did not open storage, so an empty-map 404 would be a lie.
    let (st, body) = get(&app, "/_index_template/fresh").await;
    assert_eq!(
        st,
        StatusCode::SERVICE_UNAVAILABLE,
        "blocked reads must stay unavailable: {body}"
    );
    assert_eq!(body["error"]["type"], "cluster_state_unavailable");
    let (st, _) = delete(&app, "/_ilm/policy/hot-warm").await;
    assert_eq!(
        st,
        StatusCode::SERVICE_UNAVAILABLE,
        "deletes are writes too — they must be refused as well"
    );

    // Recovery path: remove the bad directory entry, put the saved bytes back,
    // and restart. The latch belongs to the failed engine lifetime only.
    drop(app);
    drop(native_app);
    drop(engine);
    std::fs::remove_file(&state_path).expect("remove cluster-state self-loop");
    std::fs::rename(&saved_path, &state_path).expect("restore valid cluster state");
    let app = app_over(dir.path());
    let (st, _) = get(&app, "/health/ready").await;
    assert_eq!(
        st,
        StatusCode::OK,
        "valid replacement plus restart clears the fence"
    );
    let (st, body) = get(&app, "/_index_template/logs").await;
    assert_eq!(
        st,
        StatusCode::OK,
        "a restart once the file is readable must restore everything: {body}"
    );
    let (st, _) = put_json(
        &app,
        "/_index_template/fresh",
        json!({ "index_patterns": ["fresh-*"] }),
    )
    .await;
    assert_eq!(
        st,
        StatusCode::OK,
        "and writes must work again — the refusal must not be sticky across a \
         clean boot"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cluster_state_format1_fence_refuses_every_current_metadata_mutation() {
    let dir = tempfile::tempdir().expect("tempdir");
    let future = include_bytes!(
        "../../xerj-engine/tests/fixtures/cluster_state/v2-format-version-minimal.json"
    );
    let state_path = dir.path().join("cluster_state.json");
    std::fs::write(&state_path, future).expect("write future state");

    // A complete-looking snapshot source proves the fence fires before the
    // restore handler can copy it into a new index and open its WAL. Keeping
    // the source under data_dir satisfies the normal repository allowlist.
    let snapshot_repo = dir.path().join("snapshot-repo");
    let snapshot = snapshot_repo.join("ready");
    let snapshot_index = snapshot.join("restored-index");
    std::fs::create_dir_all(snapshot_index.join("wal/s1")).expect("create snapshot fixture");
    std::fs::write(
        snapshot.join("manifest.json"),
        br#"{"indices":["restored-index"]}"#,
    )
    .expect("write snapshot manifest");
    std::fs::write(
        snapshot_index.join("wal/s1/0000000000000001.wal"),
        b"sentinel",
    )
    .expect("write snapshot WAL sentinel");

    let (app, native_app, engine) = apps_and_engine_over(dir.path());
    let before = managed_inventory(&engine, dir.path()).await;
    let before_storage = recursive_storage_snapshot(dir.path());
    assert!(before.indices.is_empty());
    assert!(before.aliases.is_empty());
    assert!(before.index_templates.is_empty());
    assert!(before.legacy_templates.is_empty());
    assert!(before.component_templates.is_empty());
    assert!(before.pipelines.is_empty());
    assert!(before.data_streams.is_empty());
    assert!(before.ilm_policies.is_empty());

    for (surface, path) in [(&app, "/health/ready"), (&native_app, "/v1/health/ready")] {
        let (status, body) = get_text(surface, path).await;
        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{path}");
        assert_eq!(
            body,
            "not ready: persisted cluster metadata was not accepted at boot; inspect server logs",
            "the unauthenticated probe must not expose paths, object names, or state contents"
        );
    }
    let (status, _) = get(&app, "/health/live").await;
    assert_eq!(status, StatusCode::OK);

    // The fence is admission-wide, not a hand-maintained list of metadata
    // handlers. These routes cover read, user-index creation, direct ingest,
    // and the native surface; none may return an ordinary success/404 shape
    // from the deliberately empty diagnostic engine.
    let (status, response) = get(&app, "/").await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{response}");
    assert_eq!(response["error"]["type"], "cluster_state_unavailable");
    let (status, response) = put_json(&app, "/blocked-index", json!({"mappings":{}})).await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{response}");
    assert_eq!(response["error"]["type"], "cluster_state_unavailable");
    for (surface, path, body) in [
        (&app, "/_bulk", json!({"must":"not parse"})),
        (
            &native_app,
            "/v1/indices",
            json!({"name":"blocked-native","schema":{"fields":[]}}),
        ),
    ] {
        let (status, response) = post(surface, path, body).await;
        assert_eq!(
            status,
            StatusCode::SERVICE_UNAVAILABLE,
            "{path}: {response}"
        );
        assert_eq!(
            response["error"]["type"], "cluster_state_unavailable",
            "{path}: {response}"
        );
    }

    let put_cases = [
        ("/_index_template/new", json!({"index_patterns":["new-*"]})),
        ("/_template/new", json!({"index_patterns":["legacy-*"]})),
        ("/_component_template/new", json!({"template":{}})),
        (
            "/_ilm/policy/new",
            json!({"policy":{"phases":{"hot":{"actions":{}}}}}),
        ),
        ("/_ingest/pipeline/new", json!({"processors":[]})),
        ("/_data_stream/new", json!({})),
    ];
    for (path, body) in put_cases {
        let (status, response) = put_json(&app, path, body).await;
        assert_eq!(
            status,
            StatusCode::SERVICE_UNAVAILABLE,
            "PUT {path}: {response}"
        );
        assert_eq!(
            response["error"]["type"], "cluster_state_unavailable",
            "PUT {path}: {response}"
        );
    }

    let delete_cases = [
        "/_index_template/missing",
        "/_template/missing",
        "/_component_template/missing",
        "/_ilm/policy/missing",
        "/_ingest/pipeline/missing",
        "/_data_stream/missing",
    ];
    for path in delete_cases {
        let (status, response) = delete(&app, path).await;
        assert_eq!(
            status,
            StatusCode::SERVICE_UNAVAILABLE,
            "DELETE {path}: {response}"
        );
        assert_eq!(response["error"]["type"], "cluster_state_unavailable");
    }

    let (status, response) = post(&app, "/missing/_rollover", json!({})).await;
    assert_eq!(
        status,
        StatusCode::SERVICE_UNAVAILABLE,
        "rollover must guard before stream lookup: {response}"
    );

    let (status, response) = put_json(
        &app,
        "/_snapshot/blocked-repo",
        json!({"type":"fs","settings":{"location":snapshot_repo}}),
    )
    .await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{response}");
    assert_eq!(response["error"]["type"], "cluster_state_unavailable");
    let (status, response) = post(&app, "/_snapshot/blocked-repo/ready/_restore", json!({})).await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{response}");
    assert_eq!(response["error"]["type"], "cluster_state_unavailable");

    let restore_err: xerj_common::XerjError = engine
        .restore_snapshot(
            snapshot_repo.to_str().expect("UTF-8 snapshot path"),
            "ready",
            None,
        )
        .await
        .expect_err("direct restore must share the storage fence")
        .into();
    assert!(matches!(
        restore_err,
        xerj_common::XerjError::ClusterStateUnavailable
    ));

    assert_eq!(
        std::fs::read(&state_path).expect("read future state"),
        future,
        "readiness and refused mutations must preserve future bytes"
    );
    assert_eq!(
        managed_inventory(&engine, dir.path()).await,
        before,
        "every refused mutation must preserve the exact alias, index, map, and directory inventories"
    );
    assert_eq!(
        recursive_storage_snapshot(dir.path()),
        before_storage,
        "refused HTTP and direct restore paths must not copy, open, replay, or rewrite storage"
    );
    assert!(
        std::fs::read_dir(dir.path())
            .unwrap()
            .filter_map(|entry| entry.ok())
            .all(|entry| !entry.file_name().to_string_lossy().starts_with(".ds-new-")),
        "refused data-stream creation must not create a backing directory"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn blocked_app_state_skips_ml_registries_and_http_preserves_auth_order() {
    const ADMIN: &str = "blocked-admin";
    let dir = tempfile::tempdir().expect("tempdir");
    std::fs::write(
        dir.path().join("cluster_state.json"),
        br#"{"format_version":2}"#,
    )
    .expect("write future cluster state");
    let ml_dir = dir.path().join("_ml");
    std::fs::create_dir_all(&ml_dir).expect("create ML registry dir");
    let detectors = br#"[{"detector_id":"seeded-detector","source_index":"logs","time_field":"@timestamp","function":"count","bucket_span":"1h","anomaly_threshold":3.0,"create_time_ms":1}]"#;
    let datafeeds = br#"[{"datafeed_id":"seeded-feed","job_id":"seeded-detector","indices":["logs"],"query":{"match_all":{}},"frequency_secs":60,"state":"started"}]"#;
    std::fs::write(ml_dir.join("detectors.json"), detectors).expect("seed detectors");
    std::fs::write(ml_dir.join("datafeeds.json"), datafeeds).expect("seed datafeeds");

    let mut config = config_for(dir.path());
    config.auth.enabled = true;
    config.auth.admin_api_key = ADMIN.to_owned();
    config.limits.max_body_bytes = 16;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("blocked engine");
    assert!(!engine.cluster_state_boot_status().is_writable());
    // Seed one non-superuser credential without using the deliberately fenced
    // persistence API. It can authenticate but has no reserved-index grant.
    engine.api_keys.insert(
        "limited".to_owned(),
        xerj_engine::engine::ApiKeyRecord::new("limited", "secret", 1, None, Vec::new()),
    );
    let before_state = recursive_storage_snapshot(dir.path());
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    assert!(
        state.ml_detectors.is_empty() && state.ml_datafeeds.is_empty(),
        "a blocked AppState must not load valid persisted ML entries"
    );
    assert_eq!(
        recursive_storage_snapshot(dir.path()),
        before_state,
        "constructing a blocked AppState must not rewrite any seeded ML byte"
    );

    let native_app = xerj_api::router::build_native_router(state.clone());
    let app = xerj_api::router::build_es_compat_router(state);
    let response = app
        .clone()
        .oneshot(
            Request::post("/_bulk")
                .header("authorization", format!("ApiKey {ADMIN}"))
                .header("content-type", "application/x-ndjson")
                // A real HTTP transport supplies Content-Length for this
                // fixed body. Set it explicitly because Router::oneshot does
                // not synthesize transport headers; without it the limit
                // layer can discover overflow only when an inner handler
                // reads the streaming body, and the storage fence correctly
                // prevents that handler from running.
                .header("content-length", "17")
                .body(Body::from("x".repeat(17)))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::PAYLOAD_TOO_LARGE,
        "the existing request-size gate must keep precedence over the storage fence"
    );
    let response = app
        .clone()
        .oneshot(Request::get("/").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::UNAUTHORIZED,
        "authentication must run before the storage fence"
    );
    let response = native_app
        .clone()
        .oneshot(Request::get("/v1/indices").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::UNAUTHORIZED,
        "native authentication must run before the storage fence"
    );

    let response = app
        .clone()
        .oneshot(
            Request::get("/_memory/bob")
                .header("authorization", "ApiKey bGltaXRlZDpzZWNyZXQ=")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::FORBIDDEN,
        "authorization must run before the storage fence"
    );
    let response = native_app
        .clone()
        .oneshot(
            Request::post("/v1/indices/.xerj-memory-bob-edges/search")
                .header("authorization", "ApiKey bGltaXRlZDpzZWNyZXQ=")
                .header("content-type", "application/json")
                .body(Body::from("{}"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::FORBIDDEN,
        "native authorization must run before the storage fence"
    );

    let response = app
        .clone()
        .oneshot(
            Request::get("/")
                .header("authorization", format!("ApiKey {ADMIN}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::SERVICE_UNAVAILABLE,
        "an authenticated, authorized request must reach the storage fence"
    );
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let body: Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(body["error"]["type"], "cluster_state_unavailable");
    let response = native_app
        .clone()
        .oneshot(
            Request::get("/v1/indices")
                .header("authorization", format!("ApiKey {ADMIN}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        response.status(),
        StatusCode::SERVICE_UNAVAILABLE,
        "authorized native storage access must reach the storage fence"
    );
    assert_eq!(
        recursive_storage_snapshot(dir.path()),
        before_state,
        "auth and fence responses must not touch seeded ML registries"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn every_incompatible_format1_fixture_is_fenced_across_two_full_boots() {
    let fixtures = [
        "v1-unknown-top-level.json",
        "v1-unknown-index-template-field.json",
        "v1-unknown-data-stream-field.json",
        "v1-duplicate-version.json",
        "v1-duplicate-nested-value-key.json",
        "v2-format-version-minimal.json",
    ];

    for fixture in fixtures {
        let dir = tempfile::tempdir().expect("tempdir");
        let fixture_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../xerj-engine/tests/fixtures/cluster_state")
            .join(fixture);
        let original = std::fs::read(&fixture_path).expect("read fixture");
        let original_digest = hex_digest(&original);
        let state_path = dir.path().join("cluster_state.json");
        std::fs::write(&state_path, &original).expect("install fixture");
        let mut first_boot_inventory = None;

        for boot in 1..=2 {
            let (app, native_app, engine) = apps_and_engine_over(dir.path());
            let before = managed_inventory(&engine, dir.path()).await;
            assert!(before.indices.is_empty(), "{fixture}, boot {boot}");
            assert!(before.aliases.is_empty(), "{fixture}, boot {boot}");
            assert!(before.index_templates.is_empty(), "{fixture}, boot {boot}");
            assert!(before.legacy_templates.is_empty(), "{fixture}, boot {boot}");
            assert!(
                before.component_templates.is_empty(),
                "{fixture}, boot {boot}"
            );
            assert!(before.pipelines.is_empty(), "{fixture}, boot {boot}");
            assert!(before.data_streams.is_empty(), "{fixture}, boot {boot}");
            assert!(before.ilm_policies.is_empty(), "{fixture}, boot {boot}");
            if let Some(first) = &first_boot_inventory {
                assert_eq!(
                    &before.directory_entries, first,
                    "{fixture}: a refused restart must not add a directory entry"
                );
            } else {
                first_boot_inventory = Some(before.directory_entries.clone());
            }

            let (status, _) = get(&app, "/health/live").await;
            assert_eq!(status, StatusCode::OK, "{fixture}, boot {boot}");
            for (surface, path) in [(&app, "/health/ready"), (&native_app, "/v1/health/ready")] {
                let (status, body) = get_text(surface, path).await;
                assert_eq!(
                    status,
                    StatusCode::SERVICE_UNAVAILABLE,
                    "{fixture}, boot {boot}, {path}"
                );
                assert_eq!(
                    body,
                    "not ready: persisted cluster metadata was not accepted at boot; inspect server logs",
                    "{fixture}, boot {boot}, {path}"
                );
            }

            let (status, body) = put_json(
                &app,
                "/_index_template/must-not-land",
                json!({"index_patterns": ["blocked-*"]}),
            )
            .await;
            assert_eq!(
                status,
                StatusCode::SERVICE_UNAVAILABLE,
                "{fixture}, boot {boot}, PUT: {body}"
            );
            assert_eq!(body["error"]["type"], "cluster_state_unavailable");

            let (status, body) = delete(&app, "/_ilm/policy/must-not-land").await;
            assert_eq!(
                status,
                StatusCode::SERVICE_UNAVAILABLE,
                "{fixture}, boot {boot}, DELETE: {body}"
            );
            assert_eq!(body["error"]["type"], "cluster_state_unavailable");

            assert_eq!(
                managed_inventory(&engine, dir.path()).await,
                before,
                "{fixture}, boot {boot}: blocked mutations changed an alias, index, map, or directory"
            );
            let after = std::fs::read(&state_path).expect("read state after refused writes");
            assert_eq!(after, original, "{fixture}, boot {boot}");
            assert_eq!(
                hex_digest(&after),
                original_digest,
                "{fixture}, boot {boot}"
            );
            assert!(
                !dir.path().join("cluster_state.corrupt.json").exists(),
                "{fixture}: unsupported, unknown, and duplicate-key bytes are never salvage"
            );

            drop(app);
            drop(native_app);
            drop(engine);
            assert_eq!(
                recursive_inventory(dir.path()),
                first_boot_inventory.clone().unwrap(),
                "{fixture}, boot {boot}: shutdown changed the persisted inventory"
            );
            let after_shutdown = std::fs::read(&state_path).expect("read after shutdown");
            assert_eq!(after_shutdown, original, "{fixture}, boot {boot}");
            assert_eq!(
                hex_digest(&after_shutdown),
                original_digest,
                "{fixture}, boot {boot}"
            );
        }
    }
}

/// Concurrent writers must not trip over each other.
///
/// The atomic rewrite stages through one fixed temp path, so two flushes
/// running at once create, truncate and rename the *same* file: one loses
/// its bytes to the other's truncate, or finds the temp file already renamed
/// away. A provisioning script that fires its `PUT`s in parallel is all it
/// takes — no stress needed. Measured without the engine's write lock, 32
/// requests over a multi-threaded runtime fail immediately:
///
/// ```text
/// PUT template t2: {"error":{"type":"store_exception",
///                            "reason":"storage error: IO error"},"status":500}
/// ```
#[tokio::test(flavor = "multi_thread", worker_threads = 8)]
async fn concurrent_writes_do_not_corrupt_the_store() {
    const N: usize = 32;
    let dir = tempfile::tempdir().expect("tempdir");

    {
        let app = app_over(dir.path());
        let mut writes = Vec::with_capacity(N);
        for i in 0..N {
            let app = app.clone();
            writes.push(tokio::spawn(async move {
                put_json(
                    &app,
                    &format!("/_index_template/t{i}"),
                    json!({ "index_patterns": [format!("t{i}-*")], "priority": i }),
                )
                .await
            }));
        }
        for (i, w) in writes.into_iter().enumerate() {
            let (st, body) = w.await.expect("join");
            assert_eq!(st, StatusCode::OK, "PUT template t{i}: {body}");
        }
    }

    let app = app_over(dir.path());
    for i in 0..N {
        let (st, body) = get(&app, &format!("/_index_template/t{i}")).await;
        assert_eq!(
            st,
            StatusCode::OK,
            "template t{i} did not survive concurrent writes + restart: {body}"
        );
        assert_eq!(
            body["index_templates"][0]["index_template"]["priority"], i,
            "template t{i} came back with the wrong contents: {body}"
        );
    }
}

/// `DELETE /_data_stream/<name>` must not leave a backing index behind.
///
/// Now that the stream is persisted, the *order* of the two destructive steps
/// decides whether a crash mid-delete is recoverable. Recording the removal
/// first and destroying the backing indices second leaves `.ds-<name>-00000N`
/// directories that no data-stream API can reach: GET and DELETE answer 404
/// while `PUT /_data_stream/<name>` answers `409
/// resource_already_exists_exception` — permanently, which is the same wedge
/// the interrupted-rollover test above exists to prevent.
///
/// This test pins the observable end state of a clean delete: nothing left on
/// disk, nothing left in the document, and the name immediately reusable
/// after a restart.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_deleted_data_stream_leaves_no_backing_index_behind() {
    let dir = tempfile::tempdir().expect("tempdir");

    {
        let app = app_over(dir.path());
        let (st, body) = put_json(&app, "/_data_stream/events", json!({})).await;
        assert_eq!(st, StatusCode::OK, "PUT _data_stream: {body}");
        for _ in 0..2 {
            let (st, body) = post(&app, "/events/_rollover", json!({})).await;
            assert_eq!(st, StatusCode::OK, "rollover: {body}");
        }
        assert!(
            dir.path().join(".ds-events-000003").is_dir(),
            "fixture is wrong: three generations should exist"
        );

        let (st, body) = delete(&app, "/_data_stream/events").await;
        assert_eq!(st, StatusCode::OK, "DELETE _data_stream: {body}");
    }

    let leftovers: Vec<String> = std::fs::read_dir(dir.path())
        .expect("read data dir")
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|n| n.starts_with(".ds-events-"))
        .collect();
    assert!(
        leftovers.is_empty(),
        "a delete that answered 200 left backing indices on disk: {leftovers:?}"
    );

    let state: Value = serde_json::from_slice(
        &std::fs::read(dir.path().join("cluster_state.json")).expect("read"),
    )
    .expect("parse");
    assert!(
        state["data_streams"]["events"].is_null(),
        "the removal did not reach disk: {state}"
    );

    // The name must be reusable — the wedge shows up here as a 409 naming a
    // backing index the operator can no longer see.
    let app = app_over(dir.path());
    let (st, body) = put_json(&app, "/_data_stream/events", json!({})).await;
    assert_eq!(
        st,
        StatusCode::OK,
        "the stream name must be free after a delete + restart: {body}"
    );
}

/// A backing index that cannot be destroyed must abort the delete, not be
/// acknowledged.
///
/// This is the ordering above stated as a property rather than an outcome: the
/// removal is only recorded once every backing index is really gone. The
/// failure is injected where it actually happens in the field — the directory
/// cannot be unlinked (read-only mount, EACCES after a uid change, EIO) —
/// and the assertions are that the operator is told, that the stream is still
/// fully addressable, that the document on disk still names it, and that the
/// retry after the cause is fixed completes the job.
///
/// Unix-only, and skipped when the process can write through a `chmod 555`
/// (i.e. running as root), where the failure cannot be injected this way.
#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_backing_index_that_cannot_be_deleted_aborts_the_delete() {
    use std::os::unix::fs::PermissionsExt;

    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    let (st, body) = put_json(&app, "/_data_stream/orders", json!({})).await;
    assert_eq!(st, StatusCode::OK, "PUT _data_stream: {body}");

    let backing = dir.path().join(".ds-orders-000001");
    assert!(backing.is_dir(), "fixture is wrong: no backing index");
    let before = std::fs::read_to_string(dir.path().join("cluster_state.json")).expect("read");

    // Make the backing index's own contents un-unlinkable. Nothing inside is
    // destroyed, and the data dir stays writable — so a flush would succeed
    // if the code reached one, which is what makes the assertion below about
    // the document meaningful.
    std::fs::set_permissions(&backing, std::fs::Permissions::from_mode(0o555)).expect("chmod 555");
    if std::fs::File::create(backing.join("root-probe")).is_ok() {
        let _ = std::fs::remove_file(backing.join("root-probe"));
        std::fs::set_permissions(&backing, std::fs::Permissions::from_mode(0o755))
            .expect("chmod 755");
        eprintln!("skipped: permissions do not deny this process (running as root?)");
        return;
    }

    let (st, body) = delete(&app, "/_data_stream/orders").await;
    std::fs::set_permissions(&backing, std::fs::Permissions::from_mode(0o755)).expect("chmod 755");
    assert_eq!(
        st,
        StatusCode::INTERNAL_SERVER_ERROR,
        "a delete that could not destroy a backing index must report it, not \
         answer acknowledged: {body}"
    );

    let (st, body) = get(&app, "/_data_stream/orders").await;
    assert_eq!(
        st,
        StatusCode::OK,
        "the stream must stay addressable after a failed delete, or the \
         operator has no way to retry it: {body}"
    );
    assert_eq!(
        std::fs::read_to_string(dir.path().join("cluster_state.json")).expect("read"),
        before,
        "the removal must not have been recorded while the data is still there"
    );

    // The cause is fixed; the retry finishes the job.
    let (st, body) = delete(&app, "/_data_stream/orders").await;
    assert_eq!(st, StatusCode::OK, "retry after the cause is fixed: {body}");
    assert!(
        !backing.exists(),
        "the retry left the backing index on disk"
    );
    let state: Value = serde_json::from_slice(
        &std::fs::read(dir.path().join("cluster_state.json")).expect("read"),
    )
    .expect("parse");
    assert!(
        state["data_streams"]["orders"].is_null(),
        "the retry did not record the removal: {state}"
    );
}

/// A DELETE that fails part-way still destroys every backing index it can —
/// and the release note says so, so pin it.
///
/// The loop deliberately does not stop at the first error: the caller asked
/// for the whole stream to go, so a generation that *can* be destroyed is
/// destroyed and only the ones that could not are left. The 500 therefore
/// means "did not finish", never "nothing happened", and this test exists so
/// that sentence cannot quietly stop being true — a `break` added to that
/// loop would leave `-000002` and `-000003` on disk and fail here.
///
/// Unix-only, and skipped when the process can write through a `chmod 555`
/// (i.e. running as root), where the failure cannot be injected this way.
#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_partly_failed_delete_still_removes_what_it_could() {
    use std::os::unix::fs::PermissionsExt;

    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    let (st, body) = put_json(&app, "/_data_stream/audit", json!({})).await;
    assert_eq!(st, StatusCode::OK, "PUT _data_stream: {body}");
    for _ in 0..2 {
        let (st, body) = post(&app, "/audit/_rollover", json!({})).await;
        assert_eq!(st, StatusCode::OK, "rollover: {body}");
    }

    let first = dir.path().join(".ds-audit-000001");
    let second = dir.path().join(".ds-audit-000002");
    let third = dir.path().join(".ds-audit-000003");
    for p in [&first, &second, &third] {
        assert!(p.is_dir(), "fixture is wrong: {} missing", p.display());
    }

    // Only the FIRST generation is un-unlinkable. It is also the first one
    // the loop reaches, so a loop that stopped on error would leave the other
    // two behind.
    std::fs::set_permissions(&first, std::fs::Permissions::from_mode(0o555)).expect("chmod 555");
    if std::fs::File::create(first.join("root-probe")).is_ok() {
        let _ = std::fs::remove_file(first.join("root-probe"));
        std::fs::set_permissions(&first, std::fs::Permissions::from_mode(0o755)).expect("chmod");
        eprintln!("skipped: permissions do not deny this process (running as root?)");
        return;
    }

    let (st, body) = delete(&app, "/_data_stream/audit").await;
    std::fs::set_permissions(&first, std::fs::Permissions::from_mode(0o755)).expect("chmod 755");
    assert_eq!(
        st,
        StatusCode::INTERNAL_SERVER_ERROR,
        "a delete that could not destroy every backing index must report it: {body}"
    );

    assert!(
        first.exists(),
        "the generation that could not be deleted must still be there"
    );
    assert!(
        !second.exists() && !third.exists(),
        "the delete stopped at the first failure — the generations it could \
         have destroyed are still on disk, which contradicts the release note"
    );

    // The stream is still addressable and still recorded, so the retry has
    // something to finish.
    let (st, body) = get(&app, "/_data_stream/audit").await;
    assert_eq!(st, StatusCode::OK, "stream must stay addressable: {body}");
    let state: Value = serde_json::from_slice(
        &std::fs::read(dir.path().join("cluster_state.json")).expect("read"),
    )
    .expect("parse");
    assert!(
        !state["data_streams"]["audit"].is_null(),
        "the removal must not have been recorded while a backing index remains: {state}"
    );

    let (st, body) = delete(&app, "/_data_stream/audit").await;
    assert_eq!(st, StatusCode::OK, "retry after the cause is fixed: {body}");
    assert!(!first.exists(), "the retry left the backing index on disk");
}

//! `PUT /_cluster/settings` merges into the stored settings, the way
//! Elasticsearch does: a later request for one setting must not drop the
//! others, the nested object form is stored under the same dotted keys as the
//! flat form, and `null` removes a setting. The runtime readers (disk
//! flood-stage and memory-breaker overrides) look settings up by flat key, so
//! a replaced or nested setting silently stopped applying. `GET` renders the
//! nested form unless `flat_settings=true` is passed.
//!
//! Elasticsearch is referenced for semantics only; no code from it is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn put_settings(app: &axum::Router, body: Value) {
    let (status, _) = send(
        app,
        Request::put("/_cluster/settings")
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
}

async fn get_settings(app: &axum::Router) -> Value {
    get_settings_at(app, "/_cluster/settings?flat_settings=true").await
}

async fn get_settings_at(app: &axum::Router, uri: &str) -> Value {
    let (status, body) = send(app, Request::get(uri).body(Body::empty()).expect("request")).await;
    assert_eq!(status, StatusCode::OK);
    body
}

const FLOOD: &str = "cluster.routing.allocation.disk.watermark.flood_stage";
const BREAKER: &str = "indices.breaker.total.limit";

#[tokio::test]
async fn a_second_put_keeps_earlier_settings() {
    let (app, _dir) = app().await;
    put_settings(&app, json!({ "persistent": { FLOOD: "99%" } })).await;
    put_settings(&app, json!({ "persistent": { BREAKER: "70%" } })).await;
    put_settings(&app, json!({ "transient": { "search.max_buckets": 100 } })).await;

    let got = get_settings(&app).await;
    assert_eq!(got["persistent"][FLOOD], "99%", "{got}");
    assert_eq!(got["persistent"][BREAKER], "70%", "{got}");
    assert_eq!(got["transient"]["search.max_buckets"], 100, "{got}");
}

#[tokio::test]
async fn nested_form_is_stored_under_dotted_keys() {
    let (app, _dir) = app().await;
    put_settings(
        &app,
        json!({ "persistent": { "cluster": { "routing": { "allocation": { "disk": {
            "watermark": { "flood_stage": "99%" }
        } } } } } }),
    )
    .await;

    let got = get_settings(&app).await;
    assert_eq!(got["persistent"][FLOOD], "99%", "{got}");
}

#[tokio::test]
async fn null_removes_a_setting() {
    let (app, _dir) = app().await;
    put_settings(
        &app,
        json!({ "persistent": { FLOOD: "99%", BREAKER: "70%" } }),
    )
    .await;
    put_settings(&app, json!({ "persistent": { FLOOD: null } })).await;

    let got = get_settings(&app).await;
    assert!(got["persistent"].get(FLOOD).is_none(), "{got}");
    assert_eq!(got["persistent"][BREAKER], "70%", "{got}");
}

#[tokio::test]
async fn get_is_nested_unless_flat_settings() {
    let (app, _dir) = app().await;
    put_settings(&app, json!({ "persistent": { BREAKER: "70%" } })).await;

    let nested = get_settings_at(&app, "/_cluster/settings").await;
    assert_eq!(
        nested["persistent"]["indices"]["breaker"]["total"]["limit"], "70%",
        "{nested}"
    );
    let flat = get_settings_at(&app, "/_cluster/settings?flat_settings=true").await;
    assert_eq!(flat["persistent"][BREAKER], "70%", "{flat}");
}

#[tokio::test]
async fn put_response_lists_only_this_requests_settings() {
    let (app, _dir) = app().await;
    put_settings(&app, json!({ "persistent": { FLOOD: "99%" } })).await;

    let (status, body) = send(
        &app,
        Request::put("/_cluster/settings?flat_settings=true")
            .header("content-type", "application/json")
            .body(Body::from(
                json!({ "persistent": { BREAKER: "70%" } }).to_string(),
            ))
            .expect("request"),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(body["persistent"], json!({ BREAKER: "70%" }), "{body}");
    assert_eq!(body["transient"], json!({}), "{body}");
}

//! Issue #646 (follow-up to #310): a collapse `inner_hits` block must not ship
//! the generated embedding companions in each member's `_source` under the
//! default projection.
//!
//! The collapse machinery stashes each group member's source BEFORE the engine's
//! `_source` projection runs, so the members carry `*_vector` / `*_vector_chunks`
//! even though #309 keeps them off the top-level `_source`. The leader honours
//! #309; the `inner_hits` underneath it leaked the vectors.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_common::types::{EmbeddingConfig, FieldConfig, FieldType, Schema};

const DIMS: usize = 32;

async fn seeded_app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);

    let mut schema = Schema::empty();
    let mut body = FieldConfig::new("body", FieldType::Text);
    body.options.dimensions = Some(DIMS);
    body.options.similarity = Some("cosine".into());
    body.embedding = Some(EmbeddingConfig {
        endpoint: None,
        model: None,
        target_field: Some("body_vector".into()),
    });
    schema.add_field(body).expect("body field");
    let mut companion = FieldConfig::new("body_vector", FieldType::Vector);
    companion.options.dimensions = Some(DIMS);
    companion.options.similarity = Some("cosine".into());
    schema.add_field(companion).expect("body_vector field");
    schema
        .add_field(FieldConfig::new("grp", FieldType::Keyword))
        .expect("grp field");

    state.engine.create_index("docs", schema).expect("create");
    let idx = state.engine.get_index("docs").expect("get index");
    // Two docs in the same collapse group so the leader has an inner_hits member.
    for id in ["1", "2"] {
        idx.index_document(
            Some(id.into()),
            json!({
                "body": format!("companion leak guard document number {id}. ").repeat(8),
                "grp": "A",
            }),
        )
        .await
        .expect("index document");
    }
    idx.refresh().await.expect("refresh");

    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn post(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::post(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

/// A collapse `inner_hits` member's `_source` must omit the generated companion
/// under the default projection, exactly as the collapse leader's `_source`
/// does (#309 / #646).
#[tokio::test]
async fn collapse_inner_hits_member_source_omits_the_companion() {
    let (app, _dir) = seeded_app().await;
    let (status, response) = post(
        &app,
        "/docs/_search",
        json!({
            "query": { "match_all": {} },
            "size": 10,
            "collapse": {
                "field": "grp",
                "inner_hits": { "name": "members", "size": 10 }
            }
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{response}");

    let leader = &response["hits"]["hits"][0];
    // #309 already holds on the leader.
    assert!(
        !leader["_source"]
            .as_object()
            .expect("leader _source")
            .contains_key("body_vector"),
        "the collapse leader must not leak the companion (#309): {response}"
    );

    // The inner_hits members must honour the same default projection (#646).
    let members = leader["inner_hits"]["members"]["hits"]["hits"]
        .as_array()
        .expect("inner_hits members");
    assert!(
        !members.is_empty(),
        "expected inner_hits members: {response}"
    );
    for m in members {
        let src = m["_source"].as_object().expect("member _source");
        assert!(
            !src.contains_key("body_vector"),
            "#646: a collapse inner_hits member must not leak body_vector in _source: {m}"
        );
        assert!(
            !src.contains_key("body_vector_chunks"),
            "#646: a collapse inner_hits member must not leak body_vector_chunks: {m}"
        );
    }
}

//! Issue #506(1): collapse `inner_hits` fabricated `_seq_no` as the array index
//! (`i as u64`) and re-read `_version` live at render time, instead of carrying
//! the doc's snapshotted sequence number / version. On a collapsed scroll that
//! hands an inner hit a positional `_seq_no` (0 for each group's first member)
//! and a live `_version` beside a snapshot `_source` — the torn-read class #499
//! fixed for top-level hits, on the inner_hits path.
//!
//! This test pins the real seq_no: with `inner_hits` sorted so the array order
//! is the reverse of the insertion (seq_no) order, the first inner hit — the
//! last-indexed document — must carry a HIGHER `_seq_no` than the last inner
//! hit, which a positional index (0, 1, 2) inverts.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// Collapse `inner_hits` must carry each member's real snapshot `_seq_no`, not
/// the array index (#506).
#[tokio::test]
async fn collapse_inner_hits_seq_no_is_the_real_snapshot_value() {
    let (app, _dir) = app().await;
    let (st, _) = call(
        &app,
        "PUT",
        "/docs",
        json!({"mappings": {"properties": {
            "grp": { "type": "keyword" },
            "v": { "type": "long" }
        }}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create index");

    // One collapse group ("A"), three members indexed in ascending v — so
    // insertion order (== seq_no order) is v=10, v=20, v=30.
    for (id, v) in [("a", 10), ("b", 20), ("c", 30)] {
        let (st, _) = call(
            &app,
            "POST",
            &format!("/docs/_doc/{id}"),
            json!({ "grp": "A", "v": v }),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index {id}");
    }
    let (_s, _b) = call(&app, "POST", "/docs/_refresh", Value::Null).await;

    // Collapse by grp; inner_hits sorted v DESC -> array order [v=30, v=20, v=10]
    // = reverse of insertion (seq_no) order. Request seq_no on the inner hits.
    let (status, body) = call(
        &app,
        "POST",
        "/docs/_search",
        json!({
            "query": { "match_all": {} },
            "collapse": { "field": "grp", "inner_hits": {
                "name": "members", "size": 10,
                "sort": [{ "v": "desc" }],
                "seq_no_primary_term": true
            } }
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "collapse search: {body}");

    let inner = body
        .pointer("/hits/hits/0/inner_hits/members/hits/hits")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    assert_eq!(inner.len(), 3, "expected 3 inner hits: {body}");

    let seq_nos: Vec<i64> = inner
        .iter()
        .map(|h| h.get("_seq_no").and_then(Value::as_i64).unwrap_or(-999))
        .collect();

    // The first inner hit (v=30, indexed LAST) must have a higher seq_no than
    // the last inner hit (v=10, indexed FIRST). A positional index emits [0,1,2],
    // inverting this.
    assert!(
        seq_nos[0] > seq_nos[2],
        "collapse inner_hits _seq_no is positional (array index), not the real snapshot \
         sequence number: the last-indexed member must have the highest seq_no (#506). \
         got _seq_no sequence {seq_nos:?}: {body}"
    );
    // And it must not be the tell-tale positional [0, 1, 2].
    assert_ne!(
        seq_nos,
        vec![0, 1, 2],
        "collapse inner_hits _seq_no is the array index [0,1,2], not the doc's seq_no (#506): {body}"
    );
}

//! Issue #651: a collapse `inner_hits` block must still render when the request
//! sets an explicit `_source: {"includes": [...]}` that does not list the
//! internal `__xy_collapse_group__` sentinel.
//!
//! The collapse group members are stashed into `__xy_collapse_group__` on the
//! leader's source; the API extracts them at render time. But the engine applies
//! the `_source` include projection to `hit.source` FIRST, dropping that
//! sentinel when it is not in the include list — so the leader came back with no
//! `inner_hits` at all. ES renders `inner_hits` regardless of the top-level
//! `_source` include list.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_common::types::{FieldConfig, FieldType, Schema};

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);

    let mut schema = Schema::empty();
    schema
        .add_field(FieldConfig::new("grp", FieldType::Keyword))
        .expect("grp field");
    schema
        .add_field(FieldConfig::new("title", FieldType::Text))
        .expect("title field");
    state.engine.create_index("docs", schema).expect("create");
    let idx = state.engine.get_index("docs").expect("get index");
    for (id, grp) in [("1", "A"), ("2", "A"), ("3", "B")] {
        idx.index_document(
            Some(id.into()),
            json!({ "grp": grp, "title": format!("doc {id}") }),
        )
        .await
        .expect("index document");
    }
    idx.refresh().await.expect("refresh");

    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn post(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::post(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// A collapse `inner_hits` must render even under an explicit
/// `_source.includes` that omits the collapse sentinel (#651).
#[tokio::test]
async fn collapse_inner_hits_render_under_explicit_source_includes() {
    let (app, _dir) = app().await;

    // Collapse on grp with inner_hits AND an explicit `_source.includes` that
    // lists only `grp` (NOT the internal collapse sentinel).
    let (st, resp) = post(
        &app,
        "/docs/_search",
        json!({
            "query": { "match_all": {} },
            "size": 10,
            "_source": { "includes": ["grp"] },
            "collapse": { "field": "grp", "inner_hits": { "name": "members", "size": 10 } }
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{resp}");

    let leaders = resp["hits"]["hits"].as_array().expect("hits");
    assert!(!leaders.is_empty(), "expected collapse leaders: {resp}");
    // Every leader must carry its inner_hits (the explicit include must not
    // starve them) — #651 fail-before: on main inner_hits is absent.
    for leader in leaders {
        assert!(
            leader
                .pointer("/inner_hits/members/hits/hits")
                .and_then(Value::as_array)
                .is_some(),
            "#651: a collapse leader must render inner_hits under _source.includes: {leader}"
        );
        // And the projection still applies to the leader's own _source.
        let src = leader["_source"].as_object().expect("leader _source");
        assert!(
            src.contains_key("grp") && !src.contains_key("title"),
            "#651: the explicit include still narrows the leader _source to grp: {leader}"
        );
        assert!(
            !src.contains_key("__xy_collapse_group__"),
            "#651: the internal sentinel must not leak on the wire: {leader}"
        );
    }
}

//! Issue #623: the collapse `inner_hits` a client sees for a given group must be
//! byte-identical whether that group's leader is rendered on the FIRST page (by
//! `search_impl`, plain `_search`) or on a scroll CONTINUATION page (by
//! `scroll_page_response`). Both now route through the shared
//! `render_collapse_inner_hits` (#621/#622), so this pins them to each other —
//! the #622 verification recommended committing exactly this guard, since the
//! PR's own test only checked the continuation page in isolation.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// Extract the `inner_hits` object of the hit whose `_source.grp == grp`.
fn inner_for_group(page: &Value, grp: &str) -> Value {
    page["hits"]["hits"]
        .as_array()
        .expect("hits array")
        .iter()
        .find(|h| h["_source"]["grp"] == grp)
        .unwrap_or_else(|| panic!("group {grp} leader not present: {page}"))
        .get("inner_hits")
        .cloned()
        .unwrap_or_else(|| panic!("group {grp} leader has no inner_hits: {page}"))
}

/// The `inner_hits` for collapse group "B" must be identical whether B's leader
/// is rendered by `search_impl` (first page) or `scroll_page_response`
/// (continuation) — a rich spec: inner sort, size/from, `fields`, and
/// `seq_no_primary_term`/`version` (#623).
#[tokio::test]
async fn collapse_inner_hits_are_identical_on_first_and_continuation_pages() {
    let (app, _dir) = app().await;
    let (st, body) = call(
        &app,
        "PUT",
        "/docs",
        json!({"mappings": {"properties": {
            "grp": { "type": "keyword" },
            "v": { "type": "long" }
        }}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create index: {body}");

    // Group A (2 members) sorts before group B (3 members) under `grp asc`.
    for (id, grp, v) in [
        ("a0", "A", 10),
        ("a1", "A", 11),
        ("b0", "B", 20),
        ("b1", "B", 21),
        ("b2", "B", 22),
    ] {
        let (st, _) = call(
            &app,
            "POST",
            &format!("/docs/_doc/{id}"),
            json!({ "grp": grp, "v": v }),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index {id}");
    }
    let _ = call(&app, "POST", "/docs/_refresh", Value::Null).await;

    // A rich collapse spec, reused verbatim on both paths.
    let collapse = json!({
        "field": "grp",
        "inner_hits": {
            "name": "members",
            "size": 2,
            "from": 1,
            "sort": [{ "v": "desc" }],
            "fields": ["v"],
            "seq_no_primary_term": true,
            "version": true
        }
    });

    // Path A — first page: plain `_search`, size 10 → both leaders (A then B).
    let (st, plain) = call(
        &app,
        "POST",
        "/docs/_search",
        json!({
            "query": { "match_all": {} },
            "size": 10,
            "sort": [{ "grp": "asc" }],
            "collapse": collapse
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "plain collapse search: {plain}");
    let first_page_b = inner_for_group(&plain, "B");

    // Path B — continuation page: collapse scroll, size 1 → page 1 = A, page 2 = B.
    let (st, first) = call(
        &app,
        "POST",
        "/docs/_search?scroll=5m",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "sort": [{ "grp": "asc" }],
            "collapse": collapse
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "collapse scroll start: {first}");
    let sid = first["_scroll_id"].as_str().expect("scroll id").to_string();
    assert_eq!(
        first["hits"]["hits"][0]["_source"]["grp"], "A",
        "scroll page 1 must be group A: {first}"
    );
    let (st, page2) = call(
        &app,
        "POST",
        "/_search/scroll",
        json!({ "scroll": "5m", "scroll_id": sid }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "scroll continuation: {page2}");
    let continuation_b = inner_for_group(&page2, "B");

    // The heart of #623: the two renders of group B's inner_hits must match.
    assert_eq!(
        first_page_b, continuation_b,
        "collapse inner_hits for group B diverge between the first page (search_impl) \
         and the scroll continuation (scroll_page_response):\n first_page={first_page_b}\n continuation={continuation_b}"
    );
    // And they must be non-empty (guards against a vacuous match of two empties).
    assert!(
        continuation_b.pointer("/members/hits/hits/0").is_some(),
        "group B inner_hits must render members: {continuation_b}"
    );
}

//! Issue #566 (items 2 & 3): the collapse `inner_hits` render must carry each
//! member's SNAPSHOT `_seq_no`/`_version`, not a live lookup at render time.
//! The #506 repro (`collapse_inner_hits_seqno_is_real.rs`) is a plain
//! `POST /_search`, where snapshot == live (docs are versioned once at search
//! time), so it cannot distinguish the two. This test holds a collapse scroll
//! across an update: a member is bumped AFTER the scroll snapshot but BEFORE the
//! continuation page that renders its inner hit, so a live lookup would surface
//! the post-update `_version`/`_seq_no` beside the snapshot `_source` — the torn
//! read #499/#506 describe, on the collapse path.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// A collapse scroll whose continuation page renders a member that was updated
/// after the snapshot must report the member's SNAPSHOT `_version`/`_seq_no`,
/// not the live (bumped) one (#566 items 2 & 3).
///
/// Before #621, `scroll_page_response` never rendered the collapse group (unlike
/// `search_impl`), so it leaked `__xy_collapse_group__` / `__xy_collapse_spec__`
/// into the wire `_source` and emitted no `inner_hits`. The snapshot values were
/// carried correctly all along (the sentinel showed the pre-update `_version`),
/// so the fix ported the collapse render (`render_collapse_inner_hits`) into the
/// scroll continuation path. This test guards both halves: no sentinel leak, and
/// the member's snapshot `_version` beside its snapshot `_source`.
#[tokio::test]
async fn collapse_scroll_inner_hit_reports_snapshot_version_not_live() {
    let (app, _dir) = app().await;
    let (st, body) = call(
        &app,
        "PUT",
        "/docs",
        json!({"mappings": {"properties": {
            "grp": { "type": "keyword" },
            "v": { "type": "long" }
        }}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create index: {body}");

    // Two collapse groups. Group "A" sorts before group "B" (grp asc), so with
    // page_size 1 the scroll returns A's leader on page 1 and B's leader on
    // page 2 — the page rendered AFTER the update below.
    for (id, grp, v) in [
        ("a0", "A", 10),
        ("a1", "A", 11),
        ("b0", "B", 20),
        ("b1", "B", 21),
    ] {
        let (st, _) = call(
            &app,
            "POST",
            &format!("/docs/_doc/{id}"),
            json!({ "grp": grp, "v": v }),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index {id}");
    }
    let _ = call(&app, "POST", "/docs/_refresh", Value::Null).await;

    // Open a collapse scroll, one group per page, sorted by grp asc. Inner hits
    // request version + seq_no so the render carries the snapshot pair.
    let (st, first) = call(
        &app,
        "POST",
        "/docs/_search?scroll=5m",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "sort": [{ "grp": "asc" }],
            "collapse": { "field": "grp", "inner_hits": {
                "name": "members", "size": 10,
                "sort": [{ "v": "asc" }],
                "seq_no_primary_term": true,
                "version": true
            } }
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "collapse scroll start: {first}");
    let sid = first["_scroll_id"].as_str().expect("scroll id").to_string();
    assert_eq!(
        first["hits"]["hits"][0]["_source"]["grp"], "A",
        "page 1 must be group A: {first}"
    );

    // Concurrent update AFTER the snapshot: bump b1's `v`, seq_no and version.
    let (st, upd) = call(
        &app,
        "PUT",
        "/docs/_doc/b1",
        json!({ "grp": "B", "v": 999 }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "concurrent update b1: {upd}");
    let live_version_after = upd["_version"].as_i64().expect("_version on update");
    assert!(live_version_after >= 2, "update must bump version: {upd}");

    // Continue to page 2 (group B), rendered AFTER the update.
    let (st, page2) = call(
        &app,
        "POST",
        "/_search/scroll",
        json!({ "scroll": "5m", "scroll_id": sid }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "scroll continuation: {page2}");
    let leader = &page2["hits"]["hits"][0];
    assert_eq!(
        leader["_source"]["grp"], "B",
        "page 2 must be group B: {page2}"
    );
    // The internal collapse sentinels must NOT leak into the wire `_source`:
    // `search_impl` strips them when it renders inner_hits; the scroll
    // continuation path (`scroll_page_response`) must do the same (#566).
    assert!(
        leader["_source"].get("__xy_collapse_group__").is_none()
            && leader["_source"].get("__xy_collapse_spec__").is_none(),
        "collapse scroll continuation leaked internal sentinels into _source — \
         scroll_page_response does not render the collapse group like search_impl: {leader}"
    );

    // Find b1's inner hit on the group-B leader.
    let inner = page2
        .pointer("/hits/hits/0/inner_hits/members/hits/hits")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let b1 = inner
        .iter()
        .find(|h| h["_id"] == "b1")
        .unwrap_or_else(|| panic!("b1 must be a group-B inner hit: {page2}"));

    // The snapshot `_source` (v=21, pre-update) must be paired with the snapshot
    // `_version`/`_seq_no`, NOT the live post-update values.
    assert_eq!(
        b1["_source"]["v"].as_i64(),
        Some(21),
        "b1 inner-hit _source must be the SNAPSHOT body (v=21), got {b1}"
    );
    assert_eq!(
        b1["_version"].as_i64(),
        Some(1),
        "b1 inner-hit _version must be the SNAPSHOT version (1), not the live post-update \
         value {live_version_after} — a torn read a client could replay into if_seq_no (#566): {b1}"
    );
}

//! Issue #624: a collapse `_search?scroll=` continuation under `_source: false`.
//!
//! Two facts, established by reproduction:
//!   1. `inner_hits` DO render (the scroll snapshot is `merged_hits.clone()` taken
//!      BEFORE `_source` suppression, so the context keeps the sentinel-laden
//!      source) — #622's cautious "no inner_hits" scoping note was wrong.
//!   2. The real bug: the continuation used to EMIT `_source` even though the
//!      opening request set `_source: false` — a divergence from ES and from the
//!      `_search?scroll=` first page (search_impl). Fixed by capturing
//!      `source_disabled` once at scroll-open (`ScrollContext`) and omitting
//!      `_source` on continuation pages, while still rendering `inner_hits`.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

#[tokio::test]
async fn collapse_scroll_source_false_still_renders_inner_hits() {
    let (app, _dir) = app().await;
    let (st, _) = call(
        &app,
        "PUT",
        "/docs",
        json!({"mappings": {"properties": {"grp": {"type": "keyword"}, "v": {"type": "long"}}}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK);
    for (id, grp, v) in [
        ("a0", "A", 10),
        ("a1", "A", 11),
        ("b0", "B", 20),
        ("b1", "B", 21),
    ] {
        let (st, _) = call(
            &app,
            "POST",
            &format!("/docs/_doc/{id}"),
            json!({"grp": grp, "v": v}),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index {id}");
    }
    let _ = call(&app, "POST", "/docs/_refresh", Value::Null).await;

    // Collapse scroll, size 1, sorted grp asc, WITH `_source: false`.
    let (st, first) = call(
        &app,
        "POST",
        "/docs/_search?scroll=5m",
        json!({
            "query": {"match_all": {}},
            "size": 1,
            "_source": false,
            "sort": [{"grp": "asc"}],
            "collapse": {"field": "grp", "inner_hits": {"name": "members", "size": 10, "sort": [{"v": "asc"}]}}
        }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "collapse scroll start: {first}");
    let sid = first["_scroll_id"].as_str().expect("scroll id").to_string();

    // Continue to page 2 (group B).
    let (st, page2) = call(
        &app,
        "POST",
        "/_search/scroll",
        json!({"scroll": "5m", "scroll_id": sid}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "continuation: {page2}");
    let leader = &page2["hits"]["hits"][0];

    // #624 finding: inner_hits DO render under _source:false (the scroll snapshot
    // retains the sentinel-laden source), so the filed "no inner_hits" premise is
    // wrong — assert they render (a guard for that good behavior).
    assert!(
        leader.pointer("/inner_hits/members/hits/hits").is_some(),
        "#624: collapse scroll continuation renders inner_hits even under _source:false: {leader}"
    );
    // The REAL bug: under `_source: false` the continuation must OMIT `_source`
    // entirely (ES does; the `_search?scroll=` first page does via search_impl).
    // The scroll continuation currently emits it — this assertion fails before
    // the fix.
    assert!(
        leader.get("_source").is_none(),
        "#624: scroll continuation must omit _source under _source:false (ES parity), got: {leader}"
    );
}

//! Issue #202, from the outside — a torn `schema.json` has to reach the
//! recovery surfaces, not just the engine.
//!
//! Refusing to open an index whose metadata is unparseable is only useful if
//! the ES-compat API (`:9200`, the port every ES client, Kibana and monitoring
//! dashboard talks to) then tells the truth about it and offers a way out. The
//! engine-level tests in `xerj-engine/tests/corrupt_index_metadata.rs` call
//! `engine.delete_index` / `engine.health()` directly and therefore cannot see
//! the HTTP layer at all.
//!
//! **The HTTP behaviour asserted here is not this change's work.** Issue #206
//! built it — failed indices in `_cat/indices` and `_cluster/state`, a red
//! `_cluster/health` that names them, `DELETE` reaching a failed index through
//! literal, `_all` and wildcard forms, `GET /_cluster/indices/failed`, the
//! retry endpoint, and a readiness probe scoped to "this node has nothing to
//! serve" rather than "cluster is red". What #202 adds is a *new way in*: an
//! unparseable sidecar is now one of the conditions that puts an index in that
//! failed set. This file pins the join between the two, so a change to either
//! side that stops a corrupt-metadata index from being visible, deletable and
//! survivable on `:9200` fails here rather than in production.
//!
//! Nine of the eleven cases below quarantine an index by truncating its
//! `schema.json` — the #202 trigger — and then assert the #206 contract over
//! `build_es_compat_router`. The other two are controls that pin the negative
//! half of that contract, and deliberately corrupt nothing:
//! `cluster_health_is_not_red_without_a_failed_index` (an intact node must not
//! be dragged red by the code that reports failures) and `an_empty_node_is_ready`
//! (a fresh pod with no indices at all must still join the Service).

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_common::types::{FieldConfig, FieldType, Schema};

fn config_for(dir: &tempfile::TempDir) -> xerj_common::config::Config {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config
}

fn mapped_schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .add_field(FieldConfig::new("code", FieldType::Keyword))
        .unwrap();
    schema
}

/// Boot a node over `dir`, create `names` with an explicit mapping and one
/// flushed document each, then drop the engine so every file is closed.
async fn seed_indices(dir: &tempfile::TempDir, names: &[&str]) {
    let engine = xerj_engine::Engine::new(config_for(dir)).expect("engine");
    for name in names {
        engine
            .create_index(name, mapped_schema())
            .expect("create_index");
        let idx = engine.get_index(name).expect("get_index");
        idx.index_document(Some("d1".into()), json!({ "code": "A-1" }))
            .await
            .expect("index_document");
        idx.flush().await.expect("flush");
    }
    drop(engine);
}

/// Truncate `schema.json` to half its bytes — the torn write this PR refuses.
fn tear_schema(dir: &tempfile::TempDir, name: &str) {
    let path = dir.path().join(name).join("schema.json");
    let good = std::fs::read(&path).expect("read schema.json");
    std::fs::write(&path, &good[..good.len() / 2]).expect("write torn schema.json");
}

/// A node booted over a data dir that already contains a corrupt index.
async fn app_over(dir: &tempfile::TempDir) -> axum::Router {
    let config = config_for(dir);
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    xerj_api::router::build_es_compat_router(state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn delete(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::delete(path).body(Body::empty()).expect("request"),
    )
    .await
}

/// The default refuses `DELETE /_all` and `DELETE /pattern*`. These two tests
/// exist to prove expansion still reaches a failed index, so they opt out.
async fn allow_wildcard_delete(app: &axum::Router) {
    let (status, body) = send(
        app,
        Request::put("/_cluster/settings")
            .header("content-type", "application/json")
            .body(Body::from(
                r#"{"persistent":{"action.destructive_requires_name":false}}"#,
            ))
            .expect("request"),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
}

// ── DELETE /{index} is the documented escape hatch ───────────────────────────

/// The recovery story for a corrupt sidecar ("restore the file and retry,
/// restore from a snapshot, or DELETE the index") has to hold on the ES-compat
/// port for an index quarantined by #202, not only for the #206 triggers the
/// delete path was built against.
#[tokio::test]
async fn delete_removes_a_failed_index_over_the_es_api() {
    let dir = tempfile::tempdir().unwrap();
    seed_indices(&dir, &["victim"]).await;
    tear_schema(&dir, "victim");

    let app = app_over(&dir).await;
    let (status, body) = delete(&app, "/victim").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "DELETE on a failed index must succeed on :9200, got {status} {body}"
    );
    assert_eq!(body["acknowledged"], json!(true));
    assert!(
        !dir.path().join("victim").exists(),
        "the acknowledgement must mean the directory is gone"
    );

    // The name is usable again — that is the whole point of the escape hatch.
    let (status, body) = send(
        &app,
        Request::put("/victim")
            .header("content-type", "application/json")
            .body(Body::from(json!({}).to_string()))
            .unwrap(),
    )
    .await;
    assert!(
        status.is_success(),
        "the name must be re-creatable after the delete, got {status} {body}"
    );
}

/// Deleting the failed index must clear the failure, not just the directory:
