//! Issue #362, from the outside: `_count` must never report documents that
//! `_search` cannot return.
//!
//! `POST /{index}/_count` is implemented as `search({query, size: 0}).total`
//! (`es_compat::count_docs`), so the two endpoints are supposed to answer the
//! same question. On a `text` field they did not. A `text` mapping carries
//! `doc_values: false`, so the engine's term-count shortcut had no column to
//! read and fell back to the segment's FTS term dictionary — which holds
//! ANALYZED tokens (tokenised and lowercased by the standard analyzer), while
//! `_search` resolves a `term` on that field against the whole `_source`
//! value. Both spellings below counted a document that no `_search`, at any
//! `size`, could produce:
//!
//! ```text
//! {"term":{"title":"testsegmentreader.java"}}   count 1, hits 0
//! {"term":{"title":"quick"}}                    count 1, hits 0
//! ```
//!
//! The second row has no case component at all, which is why it is here: it is
//! the case that proves the disagreement is not about casing.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// Two documents, one `text` field, flushed to a segment — the shape the
/// issue was filed against (a source-file corpus with CamelCase names).
async fn seeded() -> (axum::Router, tempfile::TempDir) {
    let (app, dir) = app().await;
    let (status, body) = json_req(
        &app,
        "PUT",
        "/files",
        json!({
            "mappings": { "properties": {
                "title": { "type": "text" },
                "path":  { "type": "keyword" }
            }}
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "create index failed: {body}");

    for (id, doc) in [
        (
            "java",
            json!({"title": "TestSegmentReader.java", "path": "lucene/TestSegmentReader.java"}),
        ),
        (
            "fox",
            json!({"title": "the quick brown fox", "path": "docs/fox.txt"}),
        ),
    ] {
        let (status, body) = json_req(&app, "PUT", &format!("/files/_doc/{id}"), doc).await;
        assert!(status.is_success(), "index {id} failed: {status} {body}");
    }
    // The count shortcut under test only runs over flushed segments.
    let (status, body) = json_req(&app, "POST", "/files/_flush", json!({})).await;
    assert!(status.is_success(), "flush failed: {status} {body}");
    (app, dir)
}

/// `_count` and `_search` must agree on both the total AND the number of
/// documents actually retrievable.
async fn assert_agrees(app: &axum::Router, query: Value, label: &str) {
    let (status, count_body) =
        json_req(app, "POST", "/files/_count", json!({ "query": query })).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "{label}: _count failed {count_body}"
    );
    let count = count_body["count"].as_u64().expect("count is a number");

    let (status, search_body) = json_req(
        app,
        "POST",
        "/files/_search",
        json!({ "query": query, "size": 50 }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "{label}: _search failed {search_body}"
    );
    let total = search_body["hits"]["total"]["value"]
        .as_u64()
        .expect("total is a number");
    let hits = search_body["hits"]["hits"]
        .as_array()
        .expect("hits is an array")
        .len() as u64;

    assert_eq!(
        count, total,
        "{label}: _count said {count}, _search total said {total} for {query}"
    );
    assert_eq!(
        count, hits,
        "{label}: _count said {count} but _search returned {hits} document(s) for {query}"
    );
}

#[tokio::test]
async fn count_does_not_overreport_a_lowercased_term_on_a_text_field() {
    let (app, _dir) = seeded().await;
    assert_agrees(
        &app,
        json!({"term": {"title": "testsegmentreader.java"}}),
        "lowercased spelling",
    )
    .await;
}

#[tokio::test]
async fn count_does_not_overreport_an_analyzed_token_on_a_text_field() {
    let (app, _dir) = seeded().await;
    assert_agrees(&app, json!({"term": {"title": "quick"}}), "analyzed token").await;
}

/// The spelling that does match keeps working: no undercount in exchange.
#[tokio::test]
async fn count_still_agrees_on_the_exact_text_term() {
    let (app, _dir) = seeded().await;
    let query = json!({"term": {"title": "TestSegmentReader.java"}});
    assert_agrees(&app, query.clone(), "exact spelling").await;
    let (_, body) = json_req(&app, "POST", "/files/_count", json!({ "query": query })).await;
    assert_eq!(
        body["count"], 1,
        "exact-spelling term must still count its document: {body}"
    );
}

/// A `keyword` field has doc-values and never took the FTS fallback; it must
/// keep its exact, case-sensitive count.
#[tokio::test]
async fn keyword_term_count_is_unchanged() {
    let (app, _dir) = seeded().await;
    let query = json!({"term": {"path": "lucene/TestSegmentReader.java"}});
    assert_agrees(&app, query.clone(), "keyword field").await;
    let (_, body) = json_req(&app, "POST", "/files/_count", json!({ "query": query })).await;
    assert_eq!(body["count"], 1, "keyword term must count 1: {body}");

    let wrong_case = json!({"term": {"path": "LUCENE/TestSegmentReader.java"}});
    assert_agrees(&app, wrong_case.clone(), "keyword field, wrong case").await;
    let (_, body) = json_req(
        &app,
        "POST",
        "/files/_count",
        json!({ "query": wrong_case }),
    )
    .await;
    assert_eq!(
        body["count"], 0,
        "keyword term must stay case-sensitive: {body}"
    );
}

//! `POST /{index}/_count` honours the `min_score` field of its body.
//!
//! It rebuilds a `size: 0` search body from `query` alone, so the field used to
//! be dropped: `_search` with `min_score` returned 0 while `_count` with the
//! same body returned every match — a wrong count, not a slower one. The
//! single-index and multi-index/alias paths both carry it now, and a body with
//! `min_score` but no `query` runs `match_all` through the scoring path because
//! match_all scores 1.0 (a threshold above it counts zero).
//!
//! Elasticsearch is referenced for semantics only. It is AGPL-3.0/SSPL-1.0/
//! Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn search_total(app: &axum::Router, index: &str, body: &Value) -> u64 {
    let (status, resp) = json_req(app, "POST", &format!("/{index}/_search"), body.clone()).await;
    assert_eq!(status, StatusCode::OK, "{resp}");
    resp["hits"]["total"]["value"].as_u64().unwrap_or(0)
}

async fn count(app: &axum::Router, index: &str, body: &Value) -> u64 {
    let (status, resp) = json_req(app, "POST", &format!("/{index}/_count"), body.clone()).await;
    assert_eq!(status, StatusCode::OK, "{resp}");
    resp["count"].as_u64().unwrap_or(0)
}

#[tokio::test]
async fn count_honours_min_score_on_single_and_multi_index_selectors() {
    let (app, _dir) = app().await;
    for (index, docs) in [
        (
            "c1",
            vec![
                json!({"t": "alpha", "k": "a"}),
                json!({"t": "alpha alpha alpha", "k": "b"}),
                json!({"t": "beta", "k": "c"}),
            ],
        ),
        ("c2", vec![json!({"t": "alpha", "k": "a"})]),
    ] {
        let (status, body) = json_req(
            &app,
            "PUT",
            &format!("/{index}"),
            json!({"mappings": {"properties": {"t": {"type": "text"}, "k": {"type": "keyword"}}}}),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        for (i, doc) in docs.into_iter().enumerate() {
            let (status, body) =
                json_req(&app, "PUT", &format!("/{index}/_doc/{}", i + 1), doc).await;
            assert!(status.is_success(), "{body}");
        }
        let (status, body) =
            json_req(&app, "POST", &format!("/{index}/_refresh"), Value::Null).await;
        assert_eq!(status, StatusCode::OK, "{body}");
    }

    // Single index: the same body must give the same answer from both
    // endpoints, including the zero case that exposed the bug.
    for query in [
        json!({"query": {"match": {"t": "alpha"}}, "min_score": 10.0}),
        json!({"query": {"match": {"t": "alpha"}}, "min_score": 0.1}),
        // No query: match_all scores 1.0, so a threshold above it is zero and
        // one below it keeps every document.
        json!({"min_score": 2.0}),
        json!({"min_score": 0.1}),
    ] {
        assert_eq!(
            search_total(&app, "c1", &query).await,
            count(&app, "c1", &query).await,
            "single-index parity for {query}"
        );
    }
    assert_eq!(
        count(
            &app,
            "c1",
            &json!({"query": {"match": {"t": "alpha"}}, "min_score": 10.0})
        )
        .await,
        0,
        "min_score above every score must count zero"
    );

    // Comma selector: the multi-index path must carry the same threshold.
    for query in [
        json!({"query": {"match": {"t": "alpha"}}, "min_score": 10.0}),
        json!({"query": {"match": {"t": "alpha"}}, "min_score": 0.1}),
        json!({"min_score": 2.0}),
        json!({"min_score": 0.1}),
    ] {
        assert_eq!(
            search_total(&app, "c1,c2", &query).await,
            count(&app, "c1,c2", &query).await,
            "multi-index parity for {query}"
        );
    }
    assert_eq!(
        count(&app, "c1,c2", &json!({"min_score": 0.1})).await,
        4,
        "c1 has 3 docs, c2 has 1, and match_all scores 1.0"
    );

    // A non-numeric min_score is the same 400 `_search` gives, not a silently
    // ignored filter.
    for endpoint in ["_search", "_count"] {
        let (status, body) = json_req(
            &app,
            "POST",
            &format!("/c1/{endpoint}"),
            json!({"query": {"match_all": {}}, "min_score": "x"}),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST, "{endpoint}: {body}");
    }
}

//! Issue #1573: `GET /{index}` reported `settings.index.creation_date` as the
//! current time on every request, even though the engine persists each
//! index's real creation time (`created_at.json`, `Engine::index_created_at`).
//!
//! Two effects were user-visible: the value changed on every call, and a
//! restart re-synthesized it. Clients that read `creation_date` (index age,
//! ILM-style tooling) saw "now" forever.
//!
//! This test pins the three surfaces that read the value: `GET /{index}`,
//! `GET /{index}?human=true` (`creation_date_string` must be derived from the
//! SAME millisecond), and `GET /{index}/_settings` — plus survival across a
//! restart on the same data dir.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

fn config_for(dir: &std::path::Path) -> xerj_common::config::Config {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config
}

/// Build a fresh app over `dir`. Calling this after the previous app has been
/// dropped is a restart: nothing is handed over in memory.
fn app_over(dir: &std::path::Path) -> axum::Router {
    let config = config_for(dir);
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    xerj_api::router::build_es_compat_router(state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, body)
}

fn put_json(path: &str, body: Value) -> Request<Body> {
    Request::put(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

fn get(path: &str) -> Request<Body> {
    Request::get(path).body(Body::empty()).expect("request")
}

fn creation_date(body: &Value, index: &str) -> i64 {
    body.pointer(&format!("/{index}/settings/index/creation_date"))
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("no settings.index.creation_date in {body}"))
        .parse()
        .unwrap_or_else(|_| panic!("creation_date is not a millisecond integer in {body}"))
}

#[tokio::test]
async fn creation_date_is_the_persisted_creation_time() {
    let dir = tempfile::tempdir().expect("tempdir");
    let index = "born";

    let before_create = chrono::Utc::now().timestamp_millis();

    // ── Session 1 ──
    let first;
    {
        let app = app_over(dir.path());
        let (st, body) = send(&app, put_json(&format!("/{index}"), json!({}))).await;
        assert_eq!(st, StatusCode::OK, "create index: {body}");

        let (st, body) = send(&app, get(&format!("/{index}"))).await;
        assert_eq!(st, StatusCode::OK, "get index: {body}");
        first = creation_date(&body, index);

        // The recorded time is the real creation time, not a far-future or
        // far-past placeholder.
        let now_after = chrono::Utc::now().timestamp_millis();
        assert!(
            first >= before_create && first <= now_after,
            "creation_date {first} must fall between {before_create} and {now_after}"
        );

        // A later request must return the SAME millisecond. Before #1573 this
        // was `Utc::now()` per request, so the sleep makes the two differ.
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        let (st, body) = send(&app, get(&format!("/{index}"))).await;
        assert_eq!(st, StatusCode::OK, "second get index: {body}");
        assert_eq!(
            creation_date(&body, index),
            first,
            "creation_date must not change between requests: {body}"
        );

        // `human=true` renders `creation_date_string` from the same value.
        let (st, body) = send(&app, get(&format!("/{index}?human=true"))).await;
        assert_eq!(st, StatusCode::OK, "human get index: {body}");
        assert_eq!(creation_date(&body, index), first);
        let rendered = body
            .pointer(&format!("/{index}/settings/index/creation_date_string"))
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("no creation_date_string in {body}"));
        let rendered_ms = chrono::DateTime::parse_from_rfc3339(rendered)
            .unwrap_or_else(|e| panic!("creation_date_string {rendered:?} is not RFC3339: {e}"))
            .timestamp_millis();
        assert_eq!(
            rendered_ms, first,
            "creation_date_string must render the same millisecond"
        );

        // The `_settings` surface reads the same engine value.
        let (st, body) = send(&app, get(&format!("/{index}/_settings"))).await;
        assert_eq!(st, StatusCode::OK, "get settings: {body}");
        assert_eq!(creation_date(&body, index), first);
    }

    // ── Session 2: a fresh engine sees only what reached disk. ──
    let app = app_over(dir.path());
    let (st, body) = send(&app, get(&format!("/{index}"))).await;
    assert_eq!(st, StatusCode::OK, "get index after restart: {body}");
    assert_eq!(
        creation_date(&body, index),
        first,
        "creation_date must survive a restart, not be re-synthesized: {body}"
    );
}

//! End-to-end checks for the decide surface's calibration layer (issue
//! #1063): `p_cal` beside every `p_raw`, the fit's ECE riding beside both,
//! `GET /_decide/_calibration` publishing the reliability curve, and the
//! honesty rules — no `p_cal` at all when calibration is not configured,
//! `null` with a published reason when configured but unfitted, and never a
//! copy of `p_raw` pretending to be calibrated.
//!
//! The history is built so the arithmetic is exact and the answer visibly
//! moves: twenty outcome documents whose raw positive-label probability is
//! 0.25, half of them true — isotonic pools the one distinct raw probability
//! into a single knot at the base rate 0.5, so every `p_cal` is 0.5 whatever
//! the vote's share was. (0.25/0.75 are the exactly-representable pair:
//! 1 − 0.75 = 0.25 in f64, where 1 − 0.8 = 0.19999999999999996 — two raw
//! probabilities, no pooling. Ask how the first run of this file failed.) The strictly-parsed `/v1/systemone`
//! answer objects stay untouched (the wire-compatibility #1072 established):
//! `p_raw`/`p_cal` ride in `decisions.evidence`, never in the answer.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

use xerj_api::state::AppState;
use xerj_common::calibration::CalibrationMethod;

// ─────────────────────────────────────────────────────────────────────────────
// The node
// ─────────────────────────────────────────────────────────────────────────────

struct Node {
    native: axum::Router,
    app: axum::Router,
    _dir: tempfile::TempDir,
}

/// A node whose `[decisions]` block names `index`, with the calibration
/// method overrideable — the layer's one new setting.
async fn node_with(index: &str, calibration: CalibrationMethod) -> Node {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.decisions.index = index.to_string();
    config.decisions.calibration = calibration;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = AppState::new(config, engine, metrics);
    Node {
        native: xerj_api::router::build_native_router(state.clone()),
        app: xerj_api::router::build_es_compat_router(state),
        _dir: dir,
    }
}

impl Node {
    async fn call(
        &self,
        router: &axum::Router,
        method: &str,
        path: &str,
        body: Value,
    ) -> (StatusCode, Value) {
        let response = router
            .clone()
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("response");
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        (
            status,
            serde_json::from_str(&String::from_utf8_lossy(&bytes)).unwrap_or(Value::Null),
        )
    }

    async fn systemone(&self, body: Value) -> (StatusCode, Value) {
        self.call(&self.native.clone(), "POST", "/v1/systemone", body)
            .await
    }
    async fn decide(&self, body: Value) -> (StatusCode, Value) {
        self.call(&self.app.clone(), "POST", "/_decide", body).await
    }
    async fn calibration(&self, query: &str) -> (StatusCode, Value) {
        self.call(&self.app.clone(), "GET", query, json!({})).await
    }
    async fn put_doc(&self, index: &str, id: &str, doc: Value) {
        let (st, b) = self
            .call(
                &self.app.clone(),
                "PUT",
                &format!("/{index}/_doc/{id}"),
                doc,
            )
            .await;
        assert!(st.is_success(), "index {index}/{id}: {st} {b}");
    }
    async fn create_index(&self, index: &str) {
        let (st, b) = self
            .call(
                &self.app.clone(),
                "PUT",
                &format!("/{index}"),
                json!({"mappings": {"properties": {
                    "text": {"type": "text"},
                    "label": {"type": "keyword"}
                }}}),
            )
            .await;
        assert!(st.is_success(), "create {index}: {st} {b}");
    }
    async fn refresh(&self, index: &str) {
        let (st, b) = self
            .call(
                &self.app.clone(),
                "POST",
                &format!("/{index}/_refresh"),
                json!({}),
            )
            .await;
        assert!(st.is_success(), "refresh {index}: {st} {b}");
    }
}

/// Seed the outcome history: `per_side` `refund` texts labelled positive
/// (`true`, `p: 0.25`) and `per_side` `outage` texts labelled negative
/// (`false`, `p: 0.75`). Each document's `p` is the probability the system
/// served FOR ITS OWN LABEL, so both sides convert to the same positive-label
/// probability: the positives are (0.25, 1), the negatives (1 − 0.75 = 0.25,
/// 0) — exactly, because 0.75 and 0.25 are exactly representable (1 − 0.8 is
/// not, and the two-tenths the first draft used landed on two DIFFERENT raw
/// probabilities: 0.19999999999999996 and 0.2). Every pair therefore sits at
/// raw 0.25 against a 0.5 base rate — isotonic pools the one distinct raw
/// probability into a single knot at 0.5, so every `p_cal` on this history is
/// exactly 0.5, visibly not a copy of any vote share. The outage texts share
/// no query term with the refund texts, so a refund-shaped question retrieves
/// only refund documents and votes 1.0.
async fn seed_outcomes(node: &Node, index: &str, per_side: usize) {
    node.create_index(index).await;
    for i in 0..per_side {
        node.put_doc(
            index,
            &format!("refund-{i}"),
            json!({
                "text": format!("refund request number {i} for the annual subscription"),
                "label": "true",
                "p": 0.25,
                "ts": "2026-09-28T10:00:00.000Z",
            }),
        )
        .await;
        node.put_doc(
            index,
            &format!("outage-{i}"),
            json!({
                "text": format!("outage report number {i} for the weekend window"),
                "label": "false",
                "p": 0.75,
                "ts": "2026-09-29T10:00:00.000Z",
            }),
        )
        .await;
    }
    node.refresh(index).await;
}

// ─────────────────────────────────────────────────────────────────────────────
// /_decide
// ─────────────────────────────────────────────────────────────────────────────

/// The core contract: `p_raw` beside `p_cal`, the calibration block naming
/// the method and its ECE, and `p_cal` moved by the fit — 0.5 on this
/// history, whatever the vote's share was — never a copy of `p_raw`.
#[tokio::test]
async fn decide_ships_p_cal_beside_p_raw_with_the_fit_ece() {
    let node = node_with("judgements", CalibrationMethod::Isotonic).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .decide(json!({"index": "judgements", "question": "refund request for the annual subscription", "k": 10}))
        .await;
    assert!(st.is_success(), "{st} {body}");
    // The vote: all ten neighbours are `refund` docs, so the positive share
    // is 1.0 — a confident raw probability.
    assert_eq!(body["p_raw"], 1.0, "p_raw is the positive label's share");
    assert_eq!(
        body["p_cal"], 0.5,
        "the fit pooled the one distinct raw probability to the base rate: {body}"
    );
    assert_eq!(body["confidence"], 1.0, "confidence keeps its raw meaning");
    let cal = &body["calibration"];
    assert_eq!(cal["method"], "isotonic", "{cal}");
    assert_eq!(cal["scope"], "noul");
    assert!(cal["ece"]["raw"].is_number(), "the ECE rides beside: {cal}");
    assert!(cal["ece"]["calibrated"].is_number(), "{cal}");
    assert_eq!(cal["labelled_pairs"], 20);
    assert_eq!(cal["fitted_on"], 16, "the deterministic 80/20: {cal}");
    assert_eq!(cal["held_out"], 4);
}

/// An uncalibrated node ships `p_raw` alone: no `p_cal` field at all, and a
/// calibration block that says so — never a p_cal copying p_raw.
#[tokio::test]
async fn without_calibration_there_is_no_p_cal_at_all() {
    let node = node_with("judgements", CalibrationMethod::None).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .decide(json!({"index": "judgements", "question": "refund request for the annual subscription"}))
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert_eq!(body["p_raw"], 1.0);
    assert!(
        body.get("p_cal").is_none(),
        "no calibration configured → no p_cal field: {body}"
    );
    assert_eq!(body["calibration"], json!({"configured": "none"}));
}

/// Configured but unfitted: `p_cal` is `null`, and the reason rides beside
/// it in the calibration block — the operator can act on the string.
#[tokio::test]
async fn a_configured_but_unfitted_node_ships_null_with_the_reason() {
    let node = node_with("judgements", CalibrationMethod::Isotonic).await;
    seed_outcomes(&node, "judgements", 2).await; // 4 pairs < the 10-pair minimum

    let (st, body) = node
        .decide(json!({"index": "judgements", "question": "refund request for the annual subscription"}))
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert!(
        body["p_raw"].is_number(),
        "p_raw ships whatever the four-document vote said: {body}"
    );
    assert!(
        body["p_cal"].is_null(),
        "configured but unfitted → null, not a copy: {body}"
    );
    let reason = body["calibration"]["reason"]
        .as_str()
        .expect("the reason is published beside the null");
    assert!(reason.contains("4 labelled calibration pairs"), "{reason}");
    assert!(
        reason.contains("source"),
        "the flywheel exclusion is explained: {reason}"
    );
}

/// Temperature calibrates the same quantity through the same seam. On this
/// history every fit pair sits at p 0.2 with a 0.5 base rate, so the NLL
/// optimum is "as flat as the bracket allows": T pins at its ceiling (16) and
/// the saturated p_raw 1.0 pulls most of the way back toward the base rate —
/// σ(logit(1)/16) ≈ 0.703. Rank preserved, confidence honestly deflated,
/// never all the way to a pretend 0.5.
#[tokio::test]
async fn temperature_calibrates_the_same_quantity() {
    let node = node_with("judgements", CalibrationMethod::Temperature).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .decide(json!({"index": "judgements", "question": "refund request for the annual subscription"}))
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert_eq!(body["p_raw"], 1.0);
    let p_cal = body["p_cal"].as_f64().expect("a number");
    assert!(
        (p_cal - 0.703_386).abs() < 0.005,
        "T pinned at its ceiling pulls σ(logit(1)/16) back toward the base rate: {p_cal}"
    );
    assert!(
        p_cal < body["p_raw"].as_f64().expect("p_raw"),
        "the saturated raw probability deflates: {p_cal}"
    );
    assert_eq!(body["calibration"]["method"], "temperature");
}

// ─────────────────────────────────────────────────────────────────────────────
// /v1/systemone — the strictly-parsed wire stays untouched
// ─────────────────────────────────────────────────────────────────────────────

/// `p_raw`/`p_cal` ride in `decisions.evidence` (the extras channel), the
/// answer object keeps exactly its documented fields, a noul calibrates, and
/// a choice's per-option shares — a different quantity — do not.
#[tokio::test]
async fn systemone_calibrates_nouls_in_evidence_and_leaves_the_wire_alone() {
    let node = node_with("judgements", CalibrationMethod::Isotonic).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .systemone(json!({
            "state": {"documents": {
                "doc_0": "refund request for the annual subscription",
                "doc_1": "outage report for the weekend window"
            }},
            "questions": {
                "n": {"type": "noul", "instructions": "Judge `documents.doc_0` for a refund request."},
                "c": {"type": "choice", "instructions": "Route `documents.doc_1`.", "criteria": {"true": {}, "false": {}}}
            }
        }))
        .await;
    assert!(st.is_success(), "{st} {body}");

    // The wire objects: exactly the documented fields, no p_raw/p_cal inside.
    let noul = &body["answers"]["n"];
    assert_eq!(
        noul.as_object().map(|o| o.len()),
        Some(2),
        "type + noul only: {noul}"
    );
    let choice = &body["answers"]["c"];
    assert!(
        choice.get("p_raw").is_none() && choice.get("p_cal").is_none(),
        "the answer object is strictly parsed and stays untouched: {choice}"
    );

    // The evidence: the noul calibrates, the choice does not.
    let evidence = &body["decisions"]["evidence"];
    assert_eq!(evidence["n"]["p_raw"], 1.0, "the noul's p_raw: {evidence}");
    assert_eq!(
        evidence["n"]["p_cal"], 0.5,
        "the pooled base rate: {evidence}"
    );
    assert!(
        evidence["c"].get("p_raw").is_none() && evidence["c"].get("p_cal").is_none(),
        "a choice's per-option shares are a different quantity, out of this fit's scope: {evidence}"
    );

    // The block with the ECE rides at the decisions level.
    let cal = &body["decisions"]["calibration"];
    assert_eq!(cal["method"], "isotonic");
    assert_eq!(cal["scope"], "noul");
    assert!(cal["ece"]["calibrated"].is_number(), "{cal}");
    assert_eq!(cal["labelled_pairs"], 20);
}

/// An uncalibrated wire node carries no calibration block at all and no
/// p_cal in any evidence.
#[tokio::test]
async fn systemone_without_calibration_carries_no_block() {
    let node = node_with("judgements", CalibrationMethod::None).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .systemone(json!({
            "state": "refund request for the annual subscription",
            "questions": {"n": {"type": "noul", "instructions": "Is this a refund request?"}}
        }))
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert!(
        body["decisions"].get("calibration").is_none(),
        "no calibration configured → no block: {body}"
    );
    assert_eq!(body["decisions"]["evidence"]["n"]["p_raw"], 1.0);
    assert!(
        body["decisions"]["evidence"]["n"].get("p_cal").is_none(),
        "and no p_cal: {body}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /_decide/_calibration
// ─────────────────────────────────────────────────────────────────────────────

/// The publication: the reliability curve (binned p_raw against empirical
/// frequency, with bin counts), the ECE raw and calibrated, the fit's
/// parameters, and what it was fitted on. On this history every pair sits at
/// raw 0.2, so the raw curve is one bin of 20 at rate 0.5.
#[tokio::test]
async fn calibration_publishes_the_reliability_curve() {
    let node = node_with("judgements", CalibrationMethod::Isotonic).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .calibration("/_decide/_calibration?index=judgements")
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert_eq!(body["index"], "judgements");
    assert_eq!(body["configured"], "isotonic");
    assert_eq!(body["method"], "isotonic");
    assert_eq!(body["scope"], "noul");
    assert_eq!(body["labelled_pairs"], 20);
    assert_eq!(body["fitted_on"], 16);
    assert_eq!(body["held_out"], 4);
    assert_eq!(body["bins"], 10);

    let raw_curve = body["curve"]["raw"].as_array().expect("the raw curve");
    assert_eq!(
        raw_curve.len(),
        1,
        "one occupied bin (all pairs at 0.25): {raw_curve:?}"
    );
    let bin = &raw_curve[0];
    assert_eq!(bin["n"], 20, "bin counts publish");
    assert_eq!(bin["lo"], 0.2);
    assert_eq!(bin["hi"], 0.3); // the bin edge: (b+1)/10 in f64
    assert!((bin["mean_p"].as_f64().unwrap() - 0.25).abs() < 1e-12);
    assert!((bin["positive_rate"].as_f64().unwrap() - 0.5).abs() < 1e-12);
    assert!(
        body["curve"]["calibrated"].is_array(),
        "the calibrated curve publishes too: {body}"
    );
    assert!(body["ece"]["raw"].is_number() && body["ece"]["calibrated"].is_number());
    let knots = body["params"]["knots"].as_array().expect("the fit's knots");
    assert_eq!(
        knots.len(),
        1,
        "one distinct raw probability → one knot: {knots:?}"
    );
    assert_eq!(knots[0][0], 0.25);
    assert_eq!(knots[0][1], 0.5);
    assert_eq!(
        body["ts_range"],
        json!(["2026-09-28T10:00:00.000Z", "2026-09-29T10:00:00.000Z"]),
        "the fitted documents' date range publishes"
    );
}

/// The endpoint also publishes WITHOUT a configured calibration — the raw
/// reliability of the history is audit information in its own right — with a
/// reason naming the setting that would fit it.
#[tokio::test]
async fn calibration_publishes_the_raw_curve_even_when_not_configured() {
    let node = node_with("judgements", CalibrationMethod::None).await;
    seed_outcomes(&node, "judgements", 10).await;

    let (st, body) = node
        .calibration("/_decide/_calibration?index=judgements")
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert_eq!(body["configured"], "none");
    assert_eq!(body["labelled_pairs"], 20);
    assert!(
        body["curve"]["raw"].is_array(),
        "the raw curve still publishes: {body}"
    );
    assert!(body["ece"]["raw"].is_number(), "{body}");
    let reason = body["reason"]
        .as_str()
        .expect("the reason names the setting");
    assert!(reason.contains("calibration"), "{reason}");
}

/// Cached flywheel answers (`source`) are predictions, not outcomes: they do
/// not feed the fit, whatever else they do to the vote.
#[tokio::test]
async fn cached_answers_do_not_feed_the_fit() {
    let node = node_with("judgements", CalibrationMethod::Isotonic).await;
    seed_outcomes(&node, "judgements", 10).await;
    // Five cached local-tier answers — confident, and self-consistent by
    // construction. If they fed the fit they would drag it off the recorded
    // outcomes' base rate.
    for i in 0..5 {
        node.put_doc(
            "judgements",
            &format!("cached-{i}"),
            json!({
                "text": format!("cached answer number {i}"),
                "label": "true",
                "p": 0.99,
                "source": "local",
                "ts": "2026-09-30T10:00:00.000Z",
            }),
        )
        .await;
    }
    node.refresh("judgements").await;

    let (st, body) = node
        .calibration("/_decide/_calibration?index=judgements")
        .await;
    assert!(st.is_success(), "{st} {body}");
    assert_eq!(
        body["labelled_pairs"], 20,
        "the five `source` documents are predictions, not outcomes: {body}"
    );
    assert_eq!(body["fitted_on"], 16);
}

/// No index to read: the endpoint refuses naming what it needs, instead of
/// publishing an empty curve as if it were a measurement.
#[tokio::test]
async fn calibration_with_no_index_refuses() {
    // A node with no [decisions] index and nothing named per request.
    let node = node_with("", CalibrationMethod::Isotonic).await;
    let (st, body) = node.calibration("/_decide/_calibration").await;
    assert_eq!(st, StatusCode::UNPROCESSABLE_ENTITY, "{st} {body}");
    let reason = body["error"]["reason"].as_str().expect("the refusal");
    assert!(reason.contains("index"), "{reason}");
}

/// A named index that does not exist is the vote's own error shape — the
/// calibration surface never invents a fit from an unreadable history.
#[tokio::test]
async fn calibration_on_a_missing_index_errors() {
    let node = node_with("judgements", CalibrationMethod::Isotonic).await;
    let (st, body) = node.calibration("/_decide/_calibration?index=nope").await;
    assert_eq!(st, StatusCode::UNPROCESSABLE_ENTITY, "{st} {body}");
    assert_eq!(body["error"]["type"], "history_index_error", "{body}");
}

//! End-to-end checks for the decision cache flywheel (issue #1061): every
//! tier-2+ answer written back to the `[decisions]` index, every answer
//! naming its tier in a `source` field, and human corrections weighted
//! `decisions.human_weight`× (default 2.0) in the vote.
//!
//! Three of the contracts here hold in ANY build (they are the history
//! tier's, and the default node is history-only), so they are not
//! feature-gated:
//!
//! - the `source` field on both surfaces (`/_decide` top level,
//!   `/v1/systemone` per-question in `decisions.evidence.*.source`), without
//!   touching the strictly-parsed answer objects — the wire compatibility
//!   #1072 established;
//! - a history document carrying `human: true`, indexed through the ordinary
//!   `PUT /{index}/_doc` path, is weighted by the configured `human_weight`
//!   in the vote — at 1.0 the plain vote wins, at the default 2.0 the
//!   corrections flip it;
//! - history-tier answers are never written back (the write-back tests below
//!   assert the negative half of that on the same node).
//!
//! The write-back itself needs an answer produced by tier 2, so those tests
//! are gated on `decide-local` and arm the same tiny untrained fixture as
//! `systemone_local_decide.rs` — the probabilities are reproducible
//! arithmetic, not judgement quality, and nothing here measures accuracy.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

use xerj_api::state::AppState;

// ─────────────────────────────────────────────────────────────────────────────
// The node
// ─────────────────────────────────────────────────────────────────────────────

struct Node {
    native: axum::Router,
    app: axum::Router,
    _dir: tempfile::TempDir,
}

/// A node whose `[decisions]` block names `index`, with `human_weight`
/// overrideable (the flywheel's one new setting). No local tier: the
/// ungated tests are the history tier's contract.
async fn node_with_decisions(index: &str, human_weight: f64, min_confidence: f64) -> Node {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.decisions.index = index.to_string();
    config.decisions.human_weight = human_weight;
    config.decisions.min_confidence = min_confidence;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = AppState::new(config, engine, metrics);
    Node {
        native: xerj_api::router::build_native_router(state.clone()),
        app: xerj_api::router::build_es_compat_router(state),
        _dir: dir,
    }
}

impl Node {
    async fn call(
        &self,
        router: &axum::Router,
        method: &str,
        path: &str,
        body: Value,
    ) -> (StatusCode, Value) {
        let response = router
            .clone()
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("response");
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        (
            status,
            serde_json::from_str(&String::from_utf8_lossy(&bytes)).unwrap_or(Value::Null),
        )
    }

    async fn systemone(&self, body: Value) -> (StatusCode, Value) {
        self.call(&self.native.clone(), "POST", "/v1/systemone", body)
            .await
    }
    async fn decide(&self, body: Value) -> (StatusCode, Value) {
        self.call(&self.app.clone(), "POST", "/_decide", body).await
    }
    async fn put_doc(&self, index: &str, id: &str, doc: Value) {
        let (st, b) = self
            .call(
                &self.app.clone(),
                "PUT",
                &format!("/{index}/_doc/{id}"),
                doc,
            )
            .await;
        assert!(st.is_success(), "index {index}/{id}: {st} {b}");
    }
    async fn create_index(&self, index: &str) {
        let (st, b) = self
            .call(
                &self.app.clone(),
                "PUT",
                &format!("/{index}"),
                json!({"mappings": {"properties": {
                    "text": {"type": "text"},
                    "label": {"type": "keyword"}
                }}}),
            )
            .await;
        assert!(st.is_success(), "create {index}: {st} {b}");
    }
    async fn refresh(&self, index: &str) {
        let (st, b) = self
            .call(
                &self.app.clone(),
                "POST",
                &format!("/{index}/_refresh"),
                json!({}),
            )
            .await;
        assert!(st.is_success(), "refresh {index}: {st} {b}");
    }
    /// Every document's `_source` in the index, refreshed first.
    #[cfg_attr(not(feature = "decide-local"), allow(dead_code))]
    async fn docs(&self, index: &str) -> Vec<Value> {
        self.refresh(index).await;
        self.search_all(index).await
    }
    /// `_source` of every document, no refresh.
    #[cfg_attr(not(feature = "decide-local"), allow(dead_code))]
    async fn search_all(&self, index: &str) -> Vec<Value> {
        let (st, r) = self
            .call(
                &self.app.clone(),
                "POST",
                &format!("/{index}/_search"),
                json!({"query": {"match_all": {}}, "size": 100}),
            )
            .await;
        assert!(st.is_success(), "search {index}: {st} {r}");
        r["hits"]["hits"]
            .as_array()
            .map(|hits| hits.iter().map(|h| h["_source"].clone()).collect())
            .unwrap_or_default()
    }
    /// Poll until the index holds at least `n` documents — the write-back is
    /// a spawned task, so the test yields until it lands (and says so, with
    /// what it saw, if it never does). Tolerates the index not existing YET:
    /// in the bootstrap case the write-back itself creates it.
    #[cfg_attr(not(feature = "decide-local"), allow(dead_code))]
    async fn wait_for_docs(&self, index: &str, n: usize) -> Vec<Value> {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            let (rst, _) = self
                .call(
                    &self.app.clone(),
                    "POST",
                    &format!("/{index}/_refresh"),
                    json!({}),
                )
                .await;
            if rst.is_success() {
                let docs = self.search_all(index).await;
                if docs.len() >= n {
                    return docs;
                }
            }
            if std::time::Instant::now() > deadline {
                panic!("write-back did not land: wanted {n} docs in `{index}`");
            }
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// The source field — every build, both surfaces, wire-compatible
// ─────────────────────────────────────────────────────────────────────────────

/// Every answer names the tier that produced it: `/_decide` at the top
/// level, `/v1/systemone` per-question in the evidence — and the strictly
/// parsed answer objects are untouched, exactly as #1072 left them (extras
/// ride in `decisions`, which every verified client ignores).
#[tokio::test]
async fn every_answer_names_its_source_on_both_surfaces() {
    let node = node_with_decisions("history", 2.0, 0.0).await;
    node.create_index("history").await;
    node.put_doc(
        "history",
        "h1",
        json!({"text": "refund refund refund asked for money back", "label": "true"}),
    )
    .await;
    node.put_doc(
        "history",
        "h2",
        json!({"text": "refund policy says money back", "label": "true"}),
    )
    .await;
    node.refresh("history").await;

    // /_decide: the audit surface, top level.
    let (st, r) = node
        .decide(json!({"index": "history", "question": "refund asked for money back"}))
        .await;
    assert!(st.is_success(), "{st} {r}");
    assert_eq!(r["tier"], "history", "{r}");
    assert_eq!(r["source"], "history", "source names the tier: {r}");

    // /v1/systemone: per question, in the evidence — and the answer object
    // itself still carries ONLY its documented fields.
    let (st, r) = node
        .systemone(json!({
            "state": {"documents": {"doc_0": "refund asked for money back"}},
            "questions": {"d0": {"type": "noul", "instructions": "Is `documents.doc_0` about refunds?"}}
        }))
        .await;
    assert!(st.is_success(), "{st} {r}");
    assert_eq!(r["decisions"]["evidence"]["d0"]["tier"], "history", "{r}");
    assert_eq!(
        r["decisions"]["evidence"]["d0"]["source"], "history",
        "source names the tier: {r}"
    );
    let answer = r["answers"]["d0"].as_object().expect("answer: {r}");
    let mut keys = answer.keys().collect::<Vec<_>>();
    keys.sort();
    assert_eq!(
        keys,
        ["noul", "type"],
        "the answer object is unchanged — extras stay in `decisions`: {r}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Human corrections — ordinary write path, weighted ≥ 2x in the vote
// ─────────────────────────────────────────────────────────────────────────────

/// The flywheel's correction arithmetic over the real vote. One history
/// document says `billing` and ranks first (it matches every query term);
/// two HUMAN corrections say `tech` and rank below it. At `human_weight = 1.0`
/// (corrections are ordinary neighbours) billing wins; at the DEFAULT 2.0 the
/// corrections outweigh it — the same documents, the same ranks, only the
/// weight differs, so the flip is the weight's and nothing else's.
#[tokio::test]
async fn a_two_x_human_correction_flips_the_vote_the_plain_arithmetic_settles() {
    for (human_weight, expected) in [(1.0, "billing"), (2.0, "tech")] {
        let node = node_with_decisions("history", human_weight, 0.0).await;
        node.create_index("history").await;
        node.put_doc(
            "history",
            "plain",
            json!({"text": "refund money back guarantee", "label": "billing"}),
        )
        .await;
        // The corrections are written through the ORDINARY indexing path —
        // `human: true` is a field on a document, not a new API.
        node.put_doc(
            "history",
            "human1",
            json!({"text": "refund money", "label": "tech", "human": true}),
        )
        .await;
        node.put_doc(
            "history",
            "human2",
            json!({"text": "refund policy", "label": "tech", "human": true}),
        )
        .await;
        node.refresh("history").await;

        let (st, r) = node
            .decide(json!({"index": "history", "question": "refund money back guarantee"}))
            .await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(r["label"], expected, "human_weight {human_weight}: {r}");
        assert!(!r["abstain"].as_bool().unwrap_or(true), "{r}");
        assert_eq!(r["source"], "history", "{r}");
    }
}

/// The boosted weight is the weight the vote USED, so the audit surface must
/// show it: every neighbour's `weight` is its reciprocal rank, ×
/// `human_weight` exactly when the document is a correction. Asserted
/// per-position in the returned (rank-ordered) neighbour list, so the test
/// does not depend on predicting BM25's ordering — only on reading it.
#[tokio::test]
async fn the_audit_surface_shows_the_boosted_weight() {
    let human_weight = 3.0;
    let node = node_with_decisions("history", human_weight, 0.0).await;
    node.create_index("history").await;
    node.put_doc(
        "history",
        "plain",
        json!({"text": "refund money back guarantee", "label": "billing"}),
    )
    .await;
    node.put_doc(
        "history",
        "human1",
        json!({"text": "refund money", "label": "tech", "human": true}),
    )
    .await;
    node.refresh("history").await;

    let (st, r) = node
        .decide(json!({"index": "history", "question": "refund money back guarantee"}))
        .await;
    assert!(st.is_success(), "{st} {r}");
    let neighbours = r["neighbours"].as_array().expect("neighbours: {r}");
    for (rank, n) in neighbours.iter().enumerate() {
        let id = n["_id"].as_str().expect("id: {r}");
        let expected = if id == "human1" {
            human_weight / (rank as f64 + 1.0)
        } else {
            1.0 / (rank as f64 + 1.0)
        };
        let got = n["weight"].as_f64().expect("weight: {r}");
        assert!(
            (got - expected).abs() < 1e-9,
            "{id} at rank {rank}: weight {got}, expected {expected}: {r}"
        );
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// The write-back — needs tier 2, so `decide-local`
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(feature = "decide-local")]
mod write_back {
    use super::*;

    struct LocalNode {
        node: Node,
        _model_dir: tempfile::TempDir,
    }

    /// The same armed node as `systemone_local_decide.rs`: a tiny untrained
    /// fixture model, `[decisions] index` set to `index`.
    async fn local_node(index: &str, min_confidence: f64) -> LocalNode {
        local_node_escalating(index, min_confidence, 0.8).await
    }

    /// [`local_node`] with `[decisions] escalate_below` set (#1094).
    async fn local_node_escalating(
        index: &str,
        min_confidence: f64,
        escalate_below: f64,
    ) -> LocalNode {
        let dir = tempfile::tempdir().expect("tempdir");
        let model_dir = tempfile::tempdir().expect("model tempdir");
        xerj_ai::decide::testing::write_fixture(model_dir.path())
            .unwrap_or_else(|e| panic!("write decide fixture: {e:#}"));

        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.storage.wal_sync = xerj_common::config::WalSync::Async;
        config.decisions.index = index.to_string();
        config.decisions.min_confidence = min_confidence;
        config.decisions.escalate_below = escalate_below;
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        let mut state = AppState::new(config, engine, metrics);
        // The injection seam, not the environment.
        state.decide = std::sync::Arc::new(xerj_api::systemone_api::DecideSettings::local(
            model_dir.path().to_path_buf(),
        ));
        LocalNode {
            node: Node {
                native: xerj_api::router::build_native_router(state.clone()),
                app: xerj_api::router::build_es_compat_router(state),
                _dir: dir,
            },
            _model_dir: model_dir,
        }
    }

    /// THE flywheel test. One request, two questions: history answers d0
    /// (seeded refund neighbours), the local head answers d1 (payload unlike
    /// anything seeded). Exactly ONE document is written back — d1's, with
    /// the text that was decided, the label and probability served, the
    /// source that produced them, and a timestamp — and d0's history answer
    /// is NOT written again. Then the same request again: d1 is now answered
    /// by HISTORY, from the cached answer, which is the entire point.
    #[tokio::test]
    async fn local_answers_are_cached_once_and_then_answer_the_next_request() {
        let ln = local_node("history", 0.0).await;
        let node = &ln.node;
        node.create_index("history").await;
        node.put_doc(
            "history",
            "h1",
            json!({"text": "refund refund refund asked for money back", "label": "true"}),
        )
        .await;
        node.put_doc(
            "history",
            "h2",
            json!({"text": "refund policy says money back", "label": "true"}),
        )
        .await;
        node.refresh("history").await;
        assert_eq!(node.docs("history").await.len(), 2, "the seeded history");

        let request = json!({
            "state": {"documents": {
                "doc_0": "refund asked for money back",
                "doc_1": "zzzqqq nothing like the history"
            }},
            "questions": {
                "d0": {"type": "noul", "instructions": "Is `documents.doc_0` about refunds?"},
                "d1": {"type": "noul", "instructions": "Is `documents.doc_1` about refunds?"}
            }
        });
        let (st, r) = node.systemone(request.clone()).await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(r["decisions"]["evidence"]["d0"]["tier"], "history", "{r}");
        assert_eq!(r["decisions"]["evidence"]["d1"]["tier"], "local", "{r}");
        let served_p = r["decisions"]["evidence"]["d1"]["support"]
            .as_f64()
            .expect("p: {r}");

        // The write-back lands: exactly one new document.
        let docs = node.wait_for_docs("history", 3).await;
        assert_eq!(
            docs.len(),
            3,
            "history answers are not double-written: {docs:?}"
        );
        let cached: Vec<&Value> = docs.iter().filter(|d| d.get("source").is_some()).collect();
        assert_eq!(cached.len(), 1, "exactly one cached answer: {docs:?}");
        let cached = cached[0];
        assert_eq!(
            cached["text"], "zzzqqq nothing like the history",
            "{cached}"
        );
        assert!(
            cached["label"].is_string(),
            "the label the head served: {cached}"
        );
        assert_eq!(cached["source"], "local", "{cached}");
        assert!(
            (cached["p"].as_f64().unwrap_or(-1.0) - served_p).abs() < 1e-9,
            "p is the probability that was served ({served_p}): {cached}"
        );
        let ts = cached["ts"].as_str().expect("ts: {cached}");
        assert!(
            ts.ends_with('Z') && ts.len() == 24,
            "an RFC 3339 millisecond timestamp: {cached}"
        );
        // The flywheel closes: the SAME request again has d1 answered by
        // history — the cached answer is the labelled neighbour now.
        let (st, r2) = node.systemone(request).await;
        assert!(st.is_success(), "{st} {r2}");
        assert_eq!(
            r2["decisions"]["evidence"]["d1"]["tier"], "history",
            "the cached answer answered it: {r2}"
        );
        assert_eq!(
            r2["decisions"]["evidence"]["d1"]["source"], "history",
            "{r2}"
        );
        // And nothing was written back for it: still three documents.
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        assert_eq!(
            node.docs("history").await.len(),
            3,
            "a history-tier answer is never cached again"
        );
    }

    /// `/_decide` caches its local answers too — and an abstain is NOT an
    /// answer, so it is never cached. Two nodes, the same fixture and
    /// question, differing only in `min_confidence`: one answers and writes,
    /// the other abstains and writes nothing (not even the index).
    #[tokio::test]
    async fn decide_caches_answered_local_answers_but_never_an_abstain() {
        // Answers: min_confidence 0 → the answer stands, the write-back
        // creates the configured-but-never-created index itself.
        let answered = local_node("history", 0.0).await;
        let (st, r) = answered
            .node
            .decide(json!({"index": "history", "question": "urgent prize claim call now"}))
            .await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(r["tier"], "local", "{r}");
        assert_eq!(r["source"], "local", "{r}");
        let docs = answered.node.wait_for_docs("history", 1).await;
        assert_eq!(docs.len(), 1, "{docs:?}");
        assert_eq!(docs[0]["text"], "urgent prize claim call now", "{docs:?}");
        assert_eq!(docs[0]["source"], "local", "{docs:?}");
        let confidence = r["confidence"].as_f64().expect("confidence: {r}");
        assert!(
            (docs[0]["p"].as_f64().unwrap_or(-1.0) - confidence).abs() < 1e-9,
            "p is the served confidence ({confidence}): {docs:?}"
        );

        // Abstains: min_confidence 2.0 is above any probability, so the same
        // question abstains — and nothing is written, not even the index.
        let abstained = local_node("history", 2.0).await;
        let (st, r) = abstained
            .node
            .decide(json!({"index": "history", "question": "urgent prize claim call now"}))
            .await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(r["tier"], "local", "{r}");
        assert!(r["abstain"].as_bool().unwrap_or(false), "{r}");
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        let (st, r) = abstained
            .node
            .call(
                &abstained.node.app.clone(),
                "GET",
                "/history/_count",
                json!({}),
            )
            .await;
        assert_eq!(st, StatusCode::NOT_FOUND, "no index was created: {st} {r}");
    }

    /// Issue #1094: once the history index has BM25 support for common stop
    /// words, split votes whose winning share is below `escalate_below` (default
    /// 0.8) MUST escalate to `local` on both `/_decide` and `/v1/systemone` and
    /// write the local judgement back into `[decisions] index` — unfreezing the
    /// flywheel instead of locking the cache at 12 documents.
    #[tokio::test]
    async fn split_history_below_escalate_below_escalates_to_local_and_writes_back() {
        let ln = local_node("history", 0.0).await;
        let node = &ln.node;
        node.create_index("history").await;
        // Two seeded neighbours sharing the token `refund` with opposite labels:
        // rank 0 gets weight 1.0, rank 1 gets weight 0.5 → winning share 2/3 ≈ 0.6667 < 0.8.
        node.put_doc(
            "history",
            "h_true",
            json!({"text": "refund money back request", "label": "true"}),
        )
        .await;
        node.put_doc(
            "history",
            "h_false",
            json!({"text": "refund inquiry status", "label": "not true"}),
        )
        .await;
        node.refresh("history").await;
        assert_eq!(node.docs("history").await.len(), 2);

        // 1. `/_decide` escalates the split 2/3 vote (< 0.8) to `local` and caches the judgement.
        let (st, r) = node
            .decide(json!({"index": "history", "question": "refund money back check"}))
            .await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(
            r["tier"], "local",
            "split history vote (2/3 < 0.8) must escalate to local: {r}"
        );
        assert_eq!(r["source"], "local", "{r}");
        let docs = node.wait_for_docs("history", 3).await;
        assert_eq!(
            docs.len(),
            3,
            "local escalation wrote back to history: {docs:?}"
        );

        // 2. `/v1/systemone` on another split index also escalates and writes back.
        let ln2 = local_node("history_s1", 0.0).await;
        let node2 = &ln2.node;
        node2.create_index("history_s1").await;
        node2
            .put_doc(
                "history_s1",
                "s_true",
                json!({"text": "invoice payment dispute", "label": "true"}),
            )
            .await;
        node2
            .put_doc(
                "history_s1",
                "s_false",
                json!({"text": "invoice summary receipt", "label": "not true"}),
            )
            .await;
        node2.refresh("history_s1").await;

        let (st, r2) = node2
            .systemone(json!({
                "state": {"documents": {"doc_0": "invoice payment question"}},
                "questions": {"d0": {"type": "noul", "instructions": "Is `documents.doc_0` a dispute?"}}
            }))
            .await;
        assert!(st.is_success(), "{st} {r2}");
        assert_eq!(
            r2["decisions"]["evidence"]["d0"]["tier"], "local",
            "split history vote on /v1/systemone escalates to local: {r2}"
        );
        assert_eq!(r2["decisions"]["evidence"]["d0"]["source"], "local", "{r2}");
        let docs2 = node2.wait_for_docs("history_s1", 3).await;
        assert_eq!(
            docs2.len(),
            3,
            "/v1/systemone escalation wrote back to history_s1: {docs2:?}"
        );
    }

    /// #1094 follow-up: a question that keeps escalating (its own cached
    /// answer is one neighbour among split ones) must not append a fresh
    /// cached document every time — repetition alone would then let the
    /// local head out-vote the history. Re-deciding the same text overwrites
    /// its one cached answer. `escalate_below = 1.0` makes every split vote
    /// escalate, so the second request is guaranteed to reach the local head.
    #[tokio::test]
    async fn re_escalating_the_same_question_keeps_one_cached_answer() {
        let ln = local_node_escalating("history", 0.0, 1.0).await;
        let node = &ln.node;
        node.create_index("history").await;
        node.put_doc(
            "history",
            "h_true",
            json!({"text": "refund money back request", "label": "true"}),
        )
        .await;
        node.put_doc(
            "history",
            "h_false",
            json!({"text": "refund inquiry status", "label": "not true"}),
        )
        .await;
        node.refresh("history").await;

        let question = json!({"index": "history", "question": "refund money back check"});
        let (st, r) = node.decide(question.clone()).await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(r["tier"], "local", "{r}");
        let docs = node.wait_for_docs("history", 3).await;
        let cached_ts = |docs: &[Value]| -> Vec<String> {
            docs.iter()
                .filter(|d| d["source"] == "local")
                .map(|d| d["ts"].as_str().unwrap_or_default().to_string())
                .collect()
        };
        let first = cached_ts(&docs);
        assert_eq!(first.len(), 1, "one cached answer: {docs:?}");

        // Same question again: still a split vote, so it escalates again.
        tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        let (st, r) = node.decide(question).await;
        assert!(st.is_success(), "{st} {r}");
        assert_eq!(r["tier"], "local", "the re-asked split vote escalates: {r}");
        // Wait for the second write-back to land (its ts differs), then the
        // index must still hold exactly one cached answer for that text.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            let docs = node.docs("history").await;
            let ts = cached_ts(&docs);
            assert!(
                ts.len() <= 1,
                "a repeat escalation appended a duplicate: {docs:?}"
            );
            if ts.len() == 1 && ts[0] != first[0] {
                assert_eq!(docs.len(), 3, "{docs:?}");
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "the second write-back never landed: {docs:?}"
            );
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }
    }
}

//! Issue #2294: an index created with a persisted `index.default_pipeline`
//! kept reporting the binding from `GET /_settings` after a clean restart
//! (the response falls back to `settings.json`), and the pipeline definition
//! survived in cluster state, but an ordinary write no longer ran it.
//!
//! `Engine::default_pipeline_for` reads the in-memory `index_settings` map.
//! That map was filled on create and on `PUT /_settings`, and the boot,
//! failed-index retry, and snapshot-restore open paths never copied
//! `settings.json` back into it. Explicit `?pipeline=` still worked because
//! it does not consult the map.
//!
//! `index.final_pipeline` is not a setting this build reads.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

fn app_on(dir: &std::path::Path) -> (axum::Router, xerj_api::state::AppState) {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    let app = xerj_api::router::build_es_compat_router(state.clone());
    (app, state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let res = app.clone().oneshot(req).await.expect("response");
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body(), 8 * 1024 * 1024)
        .await
        .expect("body");
    let body = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, body)
}

fn put(path: &str, body: Value) -> Request<Body> {
    Request::builder()
        .method("PUT")
        .uri(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

fn get(path: &str) -> Request<Body> {
    Request::builder()
        .method("GET")
        .uri(path)
        .body(Body::empty())
        .expect("request")
}

fn ndjson(path: &str, body: &str) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri(path)
        .header("content-type", "application/x-ndjson")
        .body(Body::from(body.to_string()))
        .expect("request")
}

/// The pipeline from the report: copy `source_marker` onto `copied_marker`.
/// The ES `copy` processor is stored as `copy_field`.
async fn define_copy_pipeline(app: &axum::Router) {
    let (status, body) = send(
        app,
        put(
            "/_ingest/pipeline/restart-copy",
            json!({
                "processors": [{
                    "copy": { "source": "source_marker", "target": "copied_marker" }
                }]
            }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
}

fn assert_copied(doc: &Value, marker: &str) {
    assert_eq!(
        doc["_source"]["source_marker"].as_str(),
        Some(marker),
        "source field missing: {doc}"
    );
    assert_eq!(
        doc["_source"]["copied_marker"].as_str(),
        Some(marker),
        "default pipeline did not copy the field: {doc}"
    );
}

/// Dotted `index.default_pipeline` (the spelling in #2294) and the nested
/// spelling both have to keep transforming writes after the process that
/// created the index is gone.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn persisted_default_pipeline_runs_after_clean_restart() {
    let dir = tempfile::tempdir().expect("data dir");

    {
        let (app, state) = app_on(dir.path());
        define_copy_pipeline(&app).await;

        let (status, body) = send(
            &app,
            put(
                "/restart-probe",
                json!({
                    "settings": { "index.default_pipeline": "restart-copy" },
                    "mappings": { "properties": {
                        "source_marker": { "type": "keyword" },
                        "copied_marker": { "type": "keyword" }
                    }}
                }),
            ),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");

        let (status, body) = send(
            &app,
            put(
                "/nested-probe",
                json!({
                    "settings": { "index": { "default_pipeline": "restart-copy" } },
                    "mappings": { "properties": {
                        "source_marker": { "type": "keyword" },
                        "copied_marker": { "type": "keyword" }
                    }}
                }),
            ),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");

        // #2281 stored a template pipeline on the index at create. That copy
        // lives in settings.json and has to come back on open too.
        let (status, body) = send(
            &app,
            put(
                "/_index_template/restart-template",
                json!({
                    "index_patterns": ["from-template-*"],
                    "priority": 100,
                    "template": {
                        "settings": { "index.default_pipeline": "restart-copy" }
                    }
                }),
            ),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let (status, body) = send(&app, put("/from-template-probe", json!({}))).await;
        assert_eq!(status, StatusCode::OK, "{body}");

        // A template registered after the index exists must not become that
        // index's pipeline on the next open.
        let (status, body) = send(&app, put("/plain-probe", json!({}))).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let (status, body) = send(
            &app,
            put(
                "/_index_template/plain-template",
                json!({
                    "index_patterns": ["plain-*"],
                    "priority": 100,
                    "template": {
                        "settings": { "index.default_pipeline": "restart-copy" }
                    }
                }),
            ),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "{body}");

        let (status, body) = send(
            &app,
            put(
                "/restart-probe/_doc/before?refresh=true",
                json!({ "source_marker": "before-clean-restart" }),
            ),
        )
        .await;
        assert_eq!(status, StatusCode::CREATED, "{body}");
        let (status, doc) = send(&app, get("/restart-probe/_doc/before")).await;
        assert_eq!(status, StatusCode::OK, "{doc}");
        assert_copied(&doc, "before-clean-restart");

        assert_eq!(
            state
                .engine
                .default_pipeline_for("restart-probe")
                .as_deref(),
            Some("restart-copy")
        );
        assert_eq!(
            state.engine.default_pipeline_for("nested-probe").as_deref(),
            Some("restart-copy")
        );
        assert_eq!(
            state
                .engine
                .default_pipeline_for("from-template-probe")
                .as_deref(),
            Some("restart-copy")
        );
        assert_eq!(
            state.engine.default_pipeline_for("plain-probe"),
            None,
            "a template added after create must not bind the existing index"
        );

        drop(app);
        drop(state);
    }

    let (app, state) = app_on(dir.path());

    let (status, settings) = send(&app, get("/restart-probe/_settings")).await;
    assert_eq!(status, StatusCode::OK, "{settings}");
    assert_eq!(
        settings.pointer("/restart-probe/settings/index/index.default_pipeline"),
        Some(&json!("restart-copy")),
        "GET _settings must still report the persisted binding: {settings}"
    );
    let (status, settings) = send(&app, get("/nested-probe/_settings")).await;
    assert_eq!(status, StatusCode::OK, "{settings}");
    assert_eq!(
        settings.pointer("/nested-probe/settings/index/default_pipeline"),
        Some(&json!("restart-copy")),
        "nested default_pipeline must still be reported: {settings}"
    );

    let (status, pipeline) = send(&app, get("/_ingest/pipeline/restart-copy")).await;
    assert_eq!(status, StatusCode::OK, "{pipeline}");

    assert_eq!(
        state
            .engine
            .default_pipeline_for("restart-probe")
            .as_deref(),
        Some("restart-copy"),
        "the in-memory binding must be rebuilt from settings.json"
    );
    assert_eq!(
        state.engine.default_pipeline_for("nested-probe").as_deref(),
        Some("restart-copy"),
        "the nested spelling must be rebuilt too"
    );
    assert_eq!(
        state
            .engine
            .default_pipeline_for("from-template-probe")
            .as_deref(),
        Some("restart-copy"),
        "a pipeline copied from a template at create must survive restart"
    );
    assert_eq!(
        state.engine.default_pipeline_for("plain-probe"),
        None,
        "reopen must not attach a template the index was not created with"
    );

    let (status, before) = send(&app, get("/restart-probe/_doc/before")).await;
    assert_eq!(status, StatusCode::OK, "{before}");
    assert_copied(&before, "before-clean-restart");

    let (status, body) = send(
        &app,
        put(
            "/restart-probe/_doc/after?refresh=true",
            json!({ "source_marker": "after-clean-restart" }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    let (status, doc) = send(&app, get("/restart-probe/_doc/after")).await;
    assert_eq!(status, StatusCode::OK, "{doc}");
    assert_copied(&doc, "after-clean-restart");

    let (status, body) = send(
        &app,
        ndjson(
            "/_bulk?refresh=true",
            "{\"index\":{\"_index\":\"nested-probe\",\"_id\":\"after\"}}\n{\"source_marker\":\"after-nested\"}\n",
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["errors"], false, "{body}");
    let (status, doc) = send(&app, get("/nested-probe/_doc/after")).await;
    assert_eq!(status, StatusCode::OK, "{doc}");
    assert_copied(&doc, "after-nested");

    let (status, body) = send(
        &app,
        put(
            "/from-template-probe/_doc/after?refresh=true",
            json!({ "source_marker": "after-template" }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    let (status, doc) = send(&app, get("/from-template-probe/_doc/after")).await;
    assert_eq!(status, StatusCode::OK, "{doc}");
    assert_copied(&doc, "after-template");

    let (status, body) = send(
        &app,
        put(
            "/plain-probe/_doc/after?refresh=true",
            json!({ "source_marker": "after-plain" }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED, "{body}");
    let (status, doc) = send(&app, get("/plain-probe/_doc/after")).await;
    assert_eq!(status, StatusCode::OK, "{doc}");
    assert_eq!(doc["_source"]["source_marker"], "after-plain", "{doc}");
    assert!(
        doc["_source"].get("copied_marker").is_none(),
        "plain-probe must stay unbound after restart: {doc}"
    );
}

//! Issue #1019: `_delete_by_query` truncates at 10 000 documents per call.
//!
//! The handler built ONE search body — `{"query": …, "size": 10000, "from":
//! 0}` — deleted whatever came back, and reported `total` as the page length
//! with `batches` hardcoded to 1. An index with more than `max_result_window`
//! matching documents was therefore silently under-deleted by a single call
//! (the autoindex client works around it by looping up to 1 000 delete
//! passes, each paying the full search again). ES semantics: delete-by-query
//! has NO default document cap — it processes the entire matching result set
//! in `scroll_size` batches (default 1 000) unless `max_docs` limits it, and
//! `total` is the exact match count, not the truncated page length.
//!
//! These tests go through the real HTTP route. They fail before the fix at
//! `total`/`deleted` == 10 000 (and `_count` == 15 000 afterwards).
//!
//! Elasticsearch is referenced for wire semantics only (approach-only per the
//! licence rules); no ES code is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// Seed `n` docs into `index` via `_bulk` (chunked so no single request body
/// is enormous). Ids are zero-padded so lexicographic `_id` order is
/// deterministic — the paginated runner pages by `_id` keyset.
async fn seed_bulk(app: &axum::Router, index: &str, n: u64) {
    let (st, _) = call(
        app,
        "PUT",
        &format!("/{index}"),
        json!({"mappings": {"properties": {"v": {"type": "long"}}}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create {index}");

    let width = n.to_string().len();
    let chunk = 2_500u64;
    let mut start = 0u64;
    while start < n {
        let end = (start + chunk).min(n);
        let mut ndjson = String::new();
        for i in start..end {
            ndjson.push_str(&format!(
                "{{\"index\":{{\"_id\":\"d{i:0width$}\"}}}}\n{{\"v\":{i}}}\n",
                width = width
            ));
        }
        let response = app
            .clone()
            .oneshot(
                Request::post(format!("/{index}/_bulk"))
                    .header("content-type", "application/x-ndjson")
                    .body(Body::from(ndjson))
                    .unwrap(),
            )
            .await
            .expect("bulk request");
        assert_eq!(
            response.status(),
            StatusCode::OK,
            "bulk chunk {start}..{end}"
        );
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).expect("bulk body");
        assert_eq!(
            body["errors"],
            json!(false),
            "bulk chunk {start}..{end}: {body}"
        );
        start = end;
    }
    let (st, _) = call(app, "POST", &format!("/{index}/_refresh"), Value::Null).await;
    assert_eq!(st, StatusCode::OK, "refresh {index}");
}

async fn count(app: &axum::Router, index: &str) -> u64 {
    let (st, body) = call(
        app,
        "POST",
        &format!("/{index}/_count"),
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "_count {index}");
    body["count"].as_u64().unwrap_or(u64::MAX)
}

/// One `_delete_by_query` over 25 000 matching docs must delete ALL of them —
/// no 10k truncation, `total` the exact match count, `batches` the real page
/// count. Fails before the fix at total/deleted == 10 000.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn delete_by_query_purges_past_ten_thousand_in_one_call() {
    let (app, _dir) = app().await;
    const N: u64 = 25_000;
    seed_bulk(&app, "dbq-big", N).await;
    assert_eq!(count(&app, "dbq-big").await, N, "seeded");

    let (st, body) = call(
        &app,
        "POST",
        "/dbq-big/_delete_by_query",
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(
        body["total"],
        json!(N),
        "total must be the exact match count, not the page length: {body}"
    );
    assert_eq!(
        body["deleted"],
        json!(N),
        "every matching doc deleted by ONE call: {body}"
    );
    let batches = body["batches"].as_u64().expect("batches");
    assert!(batches >= 3, "a 25k purge at the default scroll_size of 1000 must pull real batches, got {batches}: {body}");
    assert_eq!(body["failures"], json!([]), "{body}");

    assert_eq!(
        count(&app, "dbq-big").await,
        0,
        "index must be empty after the purge"
    );
}

/// ES `max_docs`: "The maximum number of documents to process. Defaults to
/// all documents." Exactly `max_docs` documents are deleted, `total` reports
/// the processed count, and a `max_docs <= scroll_size` run is a single
/// batch (the documented no-scroll fast path).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn delete_by_query_honors_max_docs() {
    let (app, _dir) = app().await;
    seed_bulk(&app, "dbq-max", 20).await;

    let (st, body) = call(
        &app,
        "POST",
        "/dbq-max/_delete_by_query",
        json!({"query": {"match_all": {}}, "max_docs": 7}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(
        body["total"],
        json!(7),
        "with max_docs set, total is the processed count: {body}"
    );
    assert_eq!(body["deleted"], json!(7), "{body}");
    assert_eq!(
        body["batches"],
        json!(1),
        "max_docs <= scroll_size is a single batch: {body}"
    );

    assert_eq!(count(&app, "dbq-max").await, 13, "exactly max_docs deleted");
}

/// ES `scroll_size` (default 1 000): the size of the batch that powers the
/// operation — `batches` is the number of batches actually pulled.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn delete_by_query_reports_real_batch_count() {
    let (app, _dir) = app().await;
    seed_bulk(&app, "dbq-scroll", 10).await;

    let (st, body) = call(
        &app,
        "POST",
        "/dbq-scroll/_delete_by_query",
        json!({"query": {"match_all": {}}, "scroll_size": 3}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(body["total"], json!(10), "{body}");
    assert_eq!(body["deleted"], json!(10), "{body}");
    assert_eq!(
        body["batches"],
        json!(4),
        "10 docs at scroll_size 3 = 4 batches: {body}"
    );

    assert_eq!(count(&app, "dbq-scroll").await, 0);
}

/// A selective query must page exactly like match_all: every matching doc
/// deleted, non-matching untouched, total the exact match count.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn delete_by_query_paginates_selective_queries() {
    let (app, _dir) = app().await;
    seed_bulk(&app, "dbq-sel", 30).await;

    let (st, body) = call(
        &app,
        "POST",
        "/dbq-sel/_delete_by_query",
        json!({"query": {"range": {"v": {"gte": 10}}}, "scroll_size": 4}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(body["total"], json!(20), "docs with v >= 10: {body}");
    assert_eq!(body["deleted"], json!(20), "{body}");
    assert_eq!(
        body["batches"],
        json!(5),
        "20 matches at scroll_size 4 = 5 batches: {body}"
    );

    assert_eq!(count(&app, "dbq-sel").await, 10, "docs with v < 10 survive");
}

//! `DELETE /{index}` refuses `*`, `_all` and any wildcard unless
//! `action.destructive_requires_name` is false.
//!
//! The default is true, matching Elasticsearch 8. A concrete name, and a
//! comma list of concrete names, still delete. Transient overrides persistent.
//! Closing an index is unchanged: it refuses wildcards even when this setting
//! is false.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
