    assert!(exists(&app, "ax-docs").await);
}

//! Issue #1022: `POST /_enrich/policy/{name}/_execute` truncates its source
//! copy at 10 000 documents per source index.
//!
//! The executor ran ONE search per source index — `{"query":{"match_all":{}},
//! "size":10000,"_source":true}` — and copied whatever came back into the
//! system index `.enrich-<name>`. With more than 10 000 docs in a source
//! index the documents past the first page were silently never materialised,
//! so every later enrich lookup against those keys silently misses (enrich
//! correctness is keyed on completeness of the copy), and `records`
//! under-reports.
//!
//! This endpoint is a reindex into a system index, so the fix adopts
//! reindex's exact `_id`-keyset `search_after` loop. ES `_execute` has no
//! `max_docs`/`scroll_size` wire parameters — none are invented here.
//!
//! Fails before the fix at `records` == 10 000 with the `.enrich-` index
//! holding 10 000 of 10 500 documents.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// Seed `n` docs `{"k": "key-i", "payload": i}` with zero-padded ids so the
/// `_id`-keyset copy pages deterministically.
async fn seed_bulk(app: &axum::Router, index: &str, n: u64, offset: u64) {
    let (st, _) = call(
        app,
        "PUT",
        &format!("/{index}"),
        json!({"mappings": {"properties": {
            "k": {"type": "keyword"},
            "payload": {"type": "long"},
        }}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create {index}");

    let width = (offset + n).to_string().len();
    let chunk = 2_500u64;
    let mut start = 0u64;
    while start < n {
        let end = (start + chunk).min(n);
        let mut ndjson = String::new();
        for i in start..end {
            let gid = offset + i;
            ndjson.push_str(&format!(
                "{{\"index\":{{\"_id\":\"d{gid:0width$}\"}}}}\n{{\"k\":\"key-{gid}\",\"payload\":{gid}}}\n",
                width = width
            ));
        }
        let response = app
            .clone()
            .oneshot(
                Request::post(format!("/{index}/_bulk"))
                    .header("content-type", "application/x-ndjson")
                    .body(Body::from(ndjson))
                    .unwrap(),
            )
            .await
            .expect("bulk request");
        assert_eq!(response.status(), StatusCode::OK, "bulk {start}..{end}");
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let body: Value = serde_json::from_slice(&bytes).expect("bulk body");
        assert_eq!(body["errors"], json!(false), "bulk {start}..{end}: {body}");
        start = end;
    }
    let (st, _) = call(app, "POST", &format!("/{index}/_refresh"), Value::Null).await;
    assert_eq!(st, StatusCode::OK, "refresh {index}");
}

async fn count(app: &axum::Router, index: &str) -> u64 {
    let (st, body) = call(
        app,
        "POST",
        &format!("/{index}/_count"),
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "_count {index}: {body}");
    body["count"].as_u64().unwrap_or(u64::MAX)
}

/// Executing a policy over a 10 500-doc source must materialise ALL of them
/// into `.enrich-<name>` — the copy is a lookup table, and a key missing from
/// it is a lookup that silently misses forever. Fails before the fix at
/// `records`/count == 10 000.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn enrich_execute_copies_past_ten_thousand() {
    let (app, _dir) = app().await;
    const N: u64 = 10_500;
    seed_bulk(&app, "enrich-src", N, 0).await;

    let (st, body) = call(
        &app,
        "PUT",
        "/_enrich/policy/pol-big",
        json!({"match": {
            "indices": "enrich-src",
            "match_field": "k",
            "enrich_fields": ["payload"],
        }}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");

    let (st, body) = call(
        &app,
        "POST",
        "/_enrich/policy/pol-big/_execute",
        Value::Null,
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(
        body["records"],
        json!(N),
        "records must be the exact source count, not the page length: {body}"
    );

    assert_eq!(
        count(&app, ".enrich-pol-big").await,
        N,
        "the enrich index must hold every source document"
    );
    // Completeness is keyed: the LAST document of the _id order (the one the
    // truncation dropped) must be present with its payload.
    let (st, body) = call(
        &app,
        "POST",
        "/.enrich-pol-big/_search",
        json!({"query": {"term": {"k": "key-10499"}}, "size": 1}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(
        body["hits"]["hits"][0]["_source"]["payload"],
        json!(10_499),
        "the final source doc must be materialised with its fields"
    );
}

/// A policy naming multiple source indices copies each one completely; a
/// missing source index is skipped, not fatal (existing ES-tolerated
/// behavior, pinned here so the paged rewrite keeps it).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn enrich_execute_copies_every_source_index_and_skips_missing() {
    let (app, _dir) = app().await;
    seed_bulk(&app, "enrich-a", 300, 0).await;
    seed_bulk(&app, "enrich-b", 200, 1_000).await;

    let (st, body) = call(
        &app,
        "PUT",
        "/_enrich/policy/pol-multi",
        json!({"match": {
            "indices": ["enrich-a", "enrich-b", "enrich-missing"],
            "match_field": "k",
            "enrich_fields": ["payload"],
        }}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");

    let (st, body) = call(
        &app,
        "POST",
        "/_enrich/policy/pol-multi/_execute",
        Value::Null,
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{body}");
    assert_eq!(body["records"], json!(500), "{body}");
    assert_eq!(count(&app, ".enrich-pol-multi").await, 500);
}

//! Issue #451 (failure class B, `_eql/search` arm): `eql_search` resolves the
//! path index with `Engine::get_index`, which collapses an alias to
//! `aliased.first()` — one member. So an EQL search through a multi-index alias
//! silently returns only the first member's events, the same silent
//! wrong-answer as `_mget`/`_explain`/`_cat/segments`/`_segments` (fixed in
//! #555). `_eql/search` was left for last because a correct fan-out has to
//! merge the members' event lists.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// An EQL search through a 2-member alias must return matching events from every
/// member, not just the first member's.
#[tokio::test]
async fn eql_search_through_a_multi_index_alias_sees_every_member() {
    let (app, _dir) = app().await;

    for member in ["idx-a", "idx-b"] {
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {"status": {"type": "keyword"}}}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        // One matching event per member.
        let (st, _) = call(
            &app,
            "POST",
            &format!("/{member}/_doc/{member}"),
            json!({ "status": "active" }),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index into {member}");
        let (st, _) = call(&app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }
    let (st, _) = call(
        &app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "idx-a", "alias": "tri"}},
            {"add": {"index": "idx-b", "alias": "tri"}}
        ]}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create alias tri");

    let (status, body) = call(
        &app,
        "POST",
        "/tri/_eql/search",
        json!({ "query": "any where status == \"active\"" }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_eql/search status: {body}");

    let events = body
        .pointer("/hits/events")
        .and_then(Value::as_array)
        .map(|a| a.len())
        .unwrap_or(usize::MAX);
    assert_eq!(
        events, 2,
        "_eql/search through a 2-member alias must return the matching event from BOTH \
         members, not just the first member's — the alias collapsed to aliased.first() \
         (#451 _eql arm): {body}"
    );
}

/// An EQL search through a *filtered* alias must honour the filter on EVERY
/// member — a filtered alias is a document boundary (#451 class C, the same
/// leak #559 closed for `_msearch`). The fan-out must not return the members'
/// out-of-slice rows. Regression guard: fanning out unfiltered leaked them.
#[tokio::test]
async fn eql_search_through_a_filtered_alias_honours_the_filter_on_every_member() {
    let (app, _dir) = app().await;

    // idx-a holds an in-slice doc, idx-b holds an out-of-slice doc; both share
    // `host` so the EQL condition matches both and ONLY the alias filter can
    // exclude idx-b's row.
    for (member, status) in [("idx-a", "active"), ("idx-b", "deleted")] {
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {
                "status": {"type": "keyword"}, "host": {"type": "keyword"}
            }}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        let (st, _) = call(
            &app,
            "POST",
            &format!("/{member}/_doc/{member}"),
            json!({ "status": status, "host": "h1" }),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index into {member}");
        let (st, _) = call(&app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }

    // Filtered alias `hot` (status==active) over BOTH members.
    for member in ["idx-a", "idx-b"] {
        let (st, body) = call(
            &app,
            "PUT",
            &format!("/{member}/_alias/hot"),
            json!({ "filter": { "term": { "status": "active" } } }),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "filtered alias on {member}: {body}");
    }

    let (status, body) = call(
        &app,
        "POST",
        "/hot/_eql/search",
        json!({ "query": "any where host == \"h1\"" }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_eql/search status: {body}");

    let events = body
        .pointer("/hits/events")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    assert_eq!(
        events.len(),
        1,
        "_eql/search through a filtered alias leaked an out-of-slice document: the EQL \
         condition matched both members' docs, but the alias filter (status==active) must \
         hide idx-b's status=deleted row. Fanning out unfiltered returns it (#451 _eql arm \
         must AND the alias filter in, like _search/_msearch do): {body}"
    );
    // The one surviving event is the in-slice member's, not the leaked one.
    assert_eq!(
        events[0].get("_index").and_then(Value::as_str),
        Some("idx-a"),
        "the surviving event must be idx-a's in-slice doc, reported under its concrete \
         member name: {body}"
    );
}

/// #567: when the summed match count across alias members exceeds `size`, the
/// returned page must be the globally-earliest by `@timestamp` (ES EQL ascending
/// order), not biased toward the earlier-iterated member. Two members with
/// interleaving timestamps and a `size` below the combined count.
#[tokio::test]
async fn eql_events_are_timestamp_ordered_across_members_before_truncation() {
    let (app, _dir) = app().await;

    // ts-a at odd seconds, ts-b at even — the global @timestamp order interleaves
    // the two members, so a member-order concat + truncate would return the wrong
    // page.
    let members: [(&str, &[u32]); 2] = [("ts-a", &[1, 3, 5]), ("ts-b", &[2, 4, 6])];
    for (member, secs) in members {
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {
                "status": {"type": "keyword"},
                "@timestamp": {"type": "date"}
            }}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        for s in secs {
            let (st, _) = call(
                &app,
                "POST",
                &format!("/{member}/_doc/{member}-{s}"),
                json!({ "status": "active", "@timestamp": format!("2026-01-01T00:00:0{s}Z") }),
            )
            .await;
            assert_eq!(st, StatusCode::CREATED, "index {member}-{s}");
        }
        let (st, _) = call(&app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }
    let (st, _) = call(
        &app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "ts-a", "alias": "ts-all"}},
            {"add": {"index": "ts-b", "alias": "ts-all"}}
        ]}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create alias ts-all");

    // 3 of 6 total: must be the three earliest by @timestamp (01, 02, 03), which
    // spans BOTH members — not ts-a's first three (01, 03, 05).
    let (status, body) = call(
        &app,
        "POST",
        "/ts-all/_eql/search",
        json!({ "query": "any where status == \"active\"", "size": 3 }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_eql/search status: {body}");

    let stamps: Vec<String> = body
        .pointer("/hits/events")
        .and_then(Value::as_array)
        .expect("events array")
        .iter()
        .map(|e| {
            e.pointer("/_source/@timestamp")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string()
        })
        .collect();
    assert_eq!(
        stamps,
        vec![
            "2026-01-01T00:00:01Z".to_string(),
            "2026-01-01T00:00:02Z".to_string(),
            "2026-01-01T00:00:03Z".to_string(),
        ],
        "the returned page must be the globally-earliest by @timestamp across members, not the \
         first member's earliest three (#567): {body}"
    );
    assert_eq!(
        body.pointer("/hits/total/value").and_then(Value::as_u64),
        Some(6),
        "total must be the true summed match count: {body}"
    );
}

/// #567 (correctness): the cross-member merge must order by the true INSTANT, not
/// the raw timestamp string. Mixed fractional-second precision and non-UTC
/// offsets are the norm in log/SIEM corpora, and a lexical byte compare misorders
/// both: `…:01.500Z` sorts before `…:01Z` (`.` < `Z`), and `…+05:00` — an earlier
/// instant — sorts after the lexically-smaller `…Z`.
#[tokio::test]
async fn eql_events_order_by_instant_not_lexical_string() {
    let (app, _dir) = app().await;
    // True chronological order of the four events:
    //   2026-01-01T05:00:00+05:00  == 00:00:00.000Z
    //   2026-01-01T00:00:01Z       == 00:00:01.000Z
    //   2026-01-01T00:00:01.500Z   == 00:00:01.500Z
    //   2026-01-01T01:00:00Z       == 01:00:00.000Z
    let members: [(&str, &[&str]); 2] = [
        (
            "iz-a",
            &["2026-01-01T05:00:00+05:00", "2026-01-01T00:00:01.500Z"],
        ),
        ("iz-b", &["2026-01-01T00:00:01Z", "2026-01-01T01:00:00Z"]),
    ];
    for (member, stamps) in members {
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {
                "status": {"type": "keyword"},
                "@timestamp": {"type": "date"}
            }}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        for (i, ts) in stamps.iter().enumerate() {
            let (st, _) = call(
                &app,
                "POST",
                &format!("/{member}/_doc/{member}-{i}"),
                json!({ "status": "active", "@timestamp": ts }),
            )
            .await;
            assert_eq!(st, StatusCode::CREATED, "index {member}-{i} ({ts})");
        }
        let (st, _) = call(&app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }
    let (st, _) = call(
        &app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "iz-a", "alias": "iz"}},
            {"add": {"index": "iz-b", "alias": "iz"}}
        ]}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create alias iz");

    let (status, body) = call(
        &app,
        "POST",
        "/iz/_eql/search",
        json!({ "query": "any where status == \"active\"", "size": 4 }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_eql/search status: {body}");

    let stamps: Vec<String> = body
        .pointer("/hits/events")
        .and_then(Value::as_array)
        .expect("events array")
        .iter()
        .map(|e| {
            e.pointer("/_source/@timestamp")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string()
        })
        .collect();
    assert_eq!(
        stamps,
        vec![
            "2026-01-01T05:00:00+05:00".to_string(),
            "2026-01-01T00:00:01Z".to_string(),
            "2026-01-01T00:00:01.500Z".to_string(),
            "2026-01-01T01:00:00Z".to_string(),
        ],
        "EQL events must be ordered by the true instant, not the lexical string (#567): {body}"
    );
}

//! Issue #451 (failure class B): `_explain` resolves the path index with
//! `Engine::get_index`, which collapses an alias to `aliased.first()`. A
//! document that lives in any other member of the alias is reported
//! `matched: false` / "document not found" — the same `get_index` cause as
//! `_mget`, on the explain diagnostic.
//!
//! Migrated onto the shared `resolve_selector_with_filters` resolver (#451):
//! `_explain` now finds the member that actually holds the document and
//! explains against it, reporting the concrete member in `_index`.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

/// A doc that lives in the alias's SECOND member must still be explained
/// (matched), not reported "document not found" because the alias collapsed to
/// its first member.
#[tokio::test]
async fn explain_through_a_multi_index_alias_finds_a_non_first_member_doc() {
    let (app, _dir) = app().await;

    for (member, id) in [("idx-a", "1"), ("idx-b", "2")] {
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {"v": {"type": "keyword"}}}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}/_doc/{id}"),
            json!({"v": member}),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index doc {id} into {member}");
        let (st, _) = call(&app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }
    let (st, _) = call(
        &app,
        "POST",
        "/_aliases",
        json!({"actions": [
            {"add": {"index": "idx-a", "alias": "tri"}},
            {"add": {"index": "idx-b", "alias": "tri"}}
        ]}),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create alias tri");

    // Explain doc "2" (lives in idx-b, the non-first member) against match_all.
    let (status, body) = call(
        &app,
        "POST",
        "/tri/_explain/2",
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_explain status: {body}");
    assert_eq!(
        body.get("matched").and_then(Value::as_bool),
        Some(true),
        "_explain through the alias must find doc 2 in idx-b and match it, not report \
         'document not found' because the alias collapsed to its first member (#451): {body}"
    );
    // And it reports the concrete member the doc lives in, not the alias.
    assert_eq!(
        body.get("_index").and_then(Value::as_str),
        Some("idx-b"),
        "_explain must report the concrete member in _index (#451): {body}"
    );
}

//! Issue #204, from the outside: configuration xerj cannot honour must be
//! refused at the door, or refused at the point of use — never accepted with a
//! 200 and then quietly not done.
//!
//! Every case here was found by measurement against the first cut of this
//! branch, and each one is the HTTP-level statement of a defect that had only
//! engine-level (or no) coverage:
//!
//! 1. the create-time analysis gate had no HTTP test at all — neither its
//!    status code nor its ES error shape;
//! 2. the gate judged a declared filter by its `type` while `apply_settings`
//!    resolves it by NAME, so the canonical Elasticsearch-docs
//!    `english_stop` block started 400ing although xerj serves it correctly;
//! 3. `PUT /{index}/_settings` walked straight around the gate — it merged an
//!    `analysis` block into the display copy and rebuilt nothing;
//! 4. `PUT /_ingest/pipeline` was redefined by this branch to mean "compiled ⇒
//!    xerj honours this", and then accepted an ES `grok` `patterns` array, a
//!    processor-level `if` guard, and an `append` it executed as `set`;
//! 5. `_clone` copied at most 10,000 documents and swallowed every write
//!    error, then answered `{"acknowledged": true}`.
//!
//! Elasticsearch is referenced for semantics only. It is AGPL-3.0/SSPL-1.0/
//! Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_in(dir.path());
    (app, dir)
}

/// A node on an EXISTING data dir — i.e. a restart. Dropping the previous
/// router and building another one over the same directory replays
/// `cluster_state.json` exactly as a process restart does; it is the only way
/// to reach the boot path from a request-level test.
fn app_in(data_dir: &std::path::Path) -> axum::Router {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = data_dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    xerj_api::router::build_es_compat_router(state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let res = app.clone().oneshot(req).await.expect("response");
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body(), 4 * 1024 * 1024)
        .await
        .expect("body");
    let body = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, body)
}

fn put(path: &str, body: Value) -> Request<Body> {
    Request::builder()
        .method("PUT")
        .uri(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

fn post(path: &str, body: Value) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

fn get(path: &str) -> Request<Body> {
    Request::builder()
        .method("GET")
        .uri(path)
        .body(Body::empty())
        .expect("request")
}

// ── The create-time analysis gate ────────────────────────────────────────────

#[tokio::test]
async fn an_analysis_block_we_cannot_honour_is_a_400_in_the_es_error_shape() {
    let (app, _dir) = app();
    let (status, body) = send(
        &app,
        put(
            "/autocomplete",
            json!({
                "settings": { "analysis": { "analyzer": {
                    "ac": { "type": "custom", "tokenizer": "edge_ngram_tok" }
                } } }
            }),
        ),
    )
    .await;

    // Pre-fix this was `200 {"acknowledged": true}` and the index tokenised
    // with `standard` — an autocomplete index that matches nothing.
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    assert_eq!(body["status"], 400, "{body}");
    assert!(body["error"]["type"].is_string(), "{body}");
    assert!(body["error"]["root_cause"].is_array(), "{body}");
    assert!(
        body["error"]["reason"]
            .as_str()
            .expect("reason")
            .contains("edge_ngram_tok"),
        "the reason must name the construct we cannot honour: {body}"
    );

    // And nothing was left behind.
    let (status, _) = send(&app, get("/autocomplete")).await;
    assert_eq!(status, StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn the_canonical_elasticsearch_analysis_block_is_still_accepted() {
    let (app, _dir) = app();
    // Straight from the Elasticsearch docs' `rebuilt_english`, cut to the parts
    // xerj implements. `english_stop` declares `type: stop`, which
    // `apply_settings` cannot BUILD — and then resolves by NAME to the built-in
    // English stopword filter, which is exactly what it declares. Judging it on
    // `type` alone made this a 400: a straight regression on a settings block
    // xerj had always accepted and analysed correctly.
    let (status, body) = send(
        &app,
        put(
            "/blog",
            json!({
                "settings": { "analysis": {
                    "filter": { "english_stop": { "type": "stop", "stopwords": "_english_" } },
                    "analyzer": { "rebuilt_english": {
                        "type": "custom",
                        "tokenizer": "standard",
                        "filter": ["lowercase", "english_stop"]
                    } }
                } },
                "mappings": { "properties": {
                    "body": { "type": "text", "analyzer": "rebuilt_english" }
                } }
            }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["acknowledged"], true, "{body}");
}

#[tokio::test]
async fn analysis_cannot_be_smuggled_past_the_gate_through_put_settings() {
    let (app, _dir) = app();
    let (status, _) = send(&app, put("/blog", json!({}))).await;
    assert_eq!(status, StatusCode::OK);

    // The registry is built at create/open and there is no rebuild path, so
    // this could only ever have changed what `GET /_settings` echoes back.
    let (status, body) = send(
        &app,
        put(
            "/blog/_settings",
            json!({ "analysis": { "analyzer": {
                "late": { "type": "custom", "tokenizer": "whitespace" }
            } } }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    assert!(
        body["error"]["reason"]
            .as_str()
            .expect("reason")
            .contains("analysis"),
        "{body}"
    );

    // …and the display copy was not quietly updated either.
    let (_, settings) = send(&app, get("/blog/_settings")).await;
    assert!(
        settings.pointer("/blog/settings/index/analysis").is_none(),
        "a refused settings PUT must not leave the analysis block behind: {settings}"
    );

    // A settings PUT that xerj *can* honour is unaffected.
    let (status, _) = send(
        &app,
        put(
            "/blog/_settings",
            json!({ "index": { "number_of_replicas": 0 } }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
}

// ── PUT /_ingest/pipeline: compiled ⇒ honoured ───────────────────────────────

/// Register `pipeline`, then write one document through it. Returns the write's
/// status and body.
async fn write_through(
    app: &axum::Router,
    id: &str,
    processors: Value,
    doc: Value,
) -> (StatusCode, Value) {
    let (status, body) = send(
        app,
        put(
            &format!("/_ingest/pipeline/{id}"),
            json!({ "processors": processors }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "pipeline definition: {body}");
    assert_eq!(body["acknowledged"], true, "{body}");
    send(
        app,
        put(&format!("/docs/_doc/1?pipeline={id}&refresh=true"), doc),
    )
    .await
}

#[tokio::test]
async fn an_es_grok_processor_is_accepted_and_then_refuses_the_write() {
    let (app, _dir) = app();
    // Measured pre-fix: this compiled to the SYSLOG default, answered 200, and
    // indexed `{"message": "10.0.0.1 GET"}` with no `client` field anywhere.
    let (status, body) = write_through(
        &app,
        "grok_pipe",
        json!([{ "grok": { "field": "message", "patterns": ["%{IP:client} %{WORD:method}"] } }]),
        json!({ "message": "10.0.0.1 GET" }),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    let reason = body["error"]["reason"].as_str().expect("reason");
    assert!(reason.contains("patterns"), "{body}");

    // The document was NOT indexed untransformed.
    let (status, _) = send(&app, get("/docs/_doc/1")).await;
    assert_ne!(status, StatusCode::OK, "the write must not have happened");
}

#[tokio::test]
async fn a_processor_level_if_guard_is_accepted_and_then_refuses_the_write() {
    let (app, _dir) = app();
    // Measured pre-fix: `{"foo": "something-else"}` was indexed as
    // `{"foo": "something-else", "env": "prod"}` — the guard excluded it.
    let (status, body) = write_through(
        &app,
        "guarded",
        json!([{ "set": { "field": "env", "value": "prod", "if": "ctx.foo == 'never'" } }]),
        json!({ "foo": "something-else" }),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "{body}");
    assert!(
        body["error"]["reason"]
            .as_str()
            .expect("reason")
            .contains("if"),
        "{body}"
    );
}

#[tokio::test]
async fn set_overrides_an_existing_value_like_elasticsearch() {
    let (app, _dir) = app();
    let (status, body) = write_through(
        &app,
        "setter",
        json!([{ "set": { "field": "env", "value": "prod" } }]),
        json!({ "env": "dev" }),
    )
    .await;
    assert!(status.is_success(), "{body}");

    let (_, doc) = send(&app, get("/docs/_doc/1")).await;
    // Pre-fix: `override` defaulted to false and this stayed "dev".
    assert_eq!(doc["_source"]["env"], "prod", "{doc}");
}

#[tokio::test]
async fn append_appends_rather_than_replacing() {
    let (app, _dir) = app();
    let (status, body) = write_through(
        &app,
        "appender",
        json!([{ "append": { "field": "tags", "value": "b" } }]),
        json!({ "tags": ["a"] }),
    )
    .await;
    assert!(status.is_success(), "{body}");

    let (_, doc) = send(&app, get("/docs/_doc/1")).await;
    // Pre-fix: `append` was mapped onto `set`, so this was `"b"` — while the
    // `_simulate` interpreter for the same pipeline produced `["a","b"]`.
    assert_eq!(doc["_source"]["tags"], json!(["a", "b"]), "{doc}");
}

#[tokio::test]
async fn convert_accepts_the_elasticsearch_spellings_of_the_same_conversion() {
    let (app, _dir) = app();
    // `long` is xerj's `integer` (i64) and `double` is its `float` (f64) — an
    // equivalent fallback, which issue #204 explicitly permits. Refusing them
    // 400ed previously-working ES pipelines for no gain.
    let (status, body) = write_through(
        &app,
        "converter",
        json!([
            { "convert": { "field": "count", "type": "long" } },
            { "convert": { "field": "ratio", "type": "double" } }
        ]),
        json!({ "count": "404", "ratio": "1.5" }),
    )
    .await;
    assert!(status.is_success(), "{body}");

    let (_, doc) = send(&app, get("/docs/_doc/1")).await;
    assert_eq!(doc["_source"]["count"], 404, "{doc}");
    assert_eq!(doc["_source"]["ratio"], 1.5, "{doc}");

    // `auto` has no equivalent here and stays refused.
    let (status, _) = send(
        &app,
        put(
            "/_ingest/pipeline/auto_conv",
            json!({ "processors": [{ "convert": { "field": "c", "type": "auto" } }] }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);
}

// ── _clone copies everything, or says it did not ─────────────────────────────

/// More documents than one clone page (1,000) and more than the old hardcoded
/// `size: 10000` ceiling, so the test fails on both the truncation and the
/// paging bug rather than only the second.
#[tokio::test]
async fn clone_copies_every_document_not_the_first_ten_thousand() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);

    const DOCS: usize = 10_001;
    state
        .engine
        .create_index("src", xerj_common::types::Schema::empty())
        .expect("create_index");
    let idx = state.engine.get_index("src").expect("get_index");
    for i in 0..DOCS {
        idx.index_document(Some(format!("{i:08}")), json!({ "n": i }))
            .await
            .expect("index_document");
    }
    idx.refresh().await.expect("refresh");

    let app = xerj_api::router::build_es_compat_router(state);

    // The source really does hold more than the old ceiling, and the single
    // `size: 10000` search the pre-fix clone used really does stop at it — so
    // the assertion below fails on the old code rather than passing vacuously.
    let (_, src_count) = send(&app, get("/src/_count")).await;
    assert_eq!(
        src_count["count"].as_u64(),
        Some(DOCS as u64),
        "{src_count}"
    );
    let (_, capped) = send(
        &app,
        post(
            "/src/_search",
            json!({ "query": { "match_all": {} }, "size": 10000 }),
        ),
    )
    .await;
    assert_eq!(
        capped["hits"]["hits"].as_array().map(Vec::len),
        Some(10_000),
        "the pre-fix clone's one-shot search tops out here"
    );

    let (status, body) = send(&app, post("/src/_clone/dst", json!({}))).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["acknowledged"], true, "{body}");

    let (_, count) = send(&app, get("/dst/_count")).await;
    // Pre-fix: exactly 10000 — a partial copy reported as a completed one.
    assert_eq!(
        count["count"].as_u64(),
        Some(DOCS as u64),
        "clone must copy every document: {count}"
    );
}

// ── Every ingest path, not just the single-document one ──────────────────────
//
// The first cut of this branch made `PUT /_ingest/pipeline` mean "compiled ⇒
// xerj honours this" and wired the refusal into the three single-document
// handlers only. Measured against that build, `_bulk?pipeline=`, an index
// carrying `index.default_pipeline`, `_reindex` `dest.pipeline` and
// `_update_by_query?pipeline=` all answered 200/201 and stored the document
// UNTRANSFORMED — including for a pipeline that was perfectly runnable.

fn ndjson(path: &str, body: &str) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri(path)
        .header("content-type", "application/x-ndjson")
        .body(Body::from(body.to_string()))
        .expect("request")
}

/// `{"set": {"field": "env", "value": "prod"}}` — compiles and runs.
async fn define_runnable_pipeline(app: &axum::Router, id: &str) {
    let (status, body) = send(
        app,
        put(
            &format!("/_ingest/pipeline/{id}"),
            json!({ "processors": [{ "set": { "field": "env", "value": "prod" } }] }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
}

/// An ES `grok` `patterns` array — accepted by `PUT`, recorded unrunnable.
async fn define_unrunnable_pipeline(app: &axum::Router, id: &str) {
    let (status, body) = send(
        app,
        put(
            &format!("/_ingest/pipeline/{id}"),
            json!({ "processors": [{ "grok": {
                "field": "message",
                "patterns": ["%{IP:client} %{WORD:method}"]
            } }] }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["acknowledged"], true, "{body}");
}

#[tokio::test]
async fn bulk_runs_the_url_level_pipeline() {
    let (app, _dir) = app();
    define_runnable_pipeline(&app, "setp").await;

    let (status, body) = send(
        &app,
        ndjson(
            "/_bulk?pipeline=setp&refresh=true",
