#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn the_failed_index_can_be_inspected_retried_and_deleted_over_http() {
    let (state, dir) = node_with_one_broken_index().await;
    let app = build_es_compat_router(state);

    // Inspect: name AND reason, plus the two commands that act on it.
    let (status, listing) = send_json(&app, "GET", "/_cluster/indices/failed").await;
    assert_eq!(status, StatusCode::OK);
    let items = listing["data"]["failed_indices"].as_array().expect("array");
    assert_eq!(items.len(), 1, "{listing}");
    assert_eq!(items[0]["index"], "broken");
    assert!(
        items[0]["reason"]
            .as_str()
            .unwrap_or_default()
            .contains("snapshot.json"),
        "{listing}"
    );

    // Reading it names the real problem instead of claiming it does not exist.
    let (status, err) = send_json(&app, "GET", "/broken/_search").await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{err}");
    assert_eq!(
        err["error"]["type"], "no_shard_available_action_exception",
        "{err}"
    );

    // Retry while still broken: 503 with the live reason, not a cheerful 200.
    let (status, err) = send_json(&app, "POST", "/_cluster/indices/failed/broken/_retry").await;
    assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{err}");
    assert!(
        err["error"]["reason"]
            .as_str()
            .unwrap_or_default()
            .contains("snapshot.json"),
        "{err}"
    );

    // Delete without a restart.
    let (status, body) = send_json(&app, "DELETE", "/broken").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["acknowledged"], true, "{body}");
    assert!(
        !dir.path().join("broken").exists(),
        "DELETE must remove the bytes on disk"
    );

    // The node is green again and nothing is left to inspect.
    let (_, listing) = send_json(&app, "GET", "/_cluster/indices/failed").await;
    assert_eq!(listing["data"]["count"], 0, "{listing}");
    let (_, health) = send_json(&app, "GET", "/_cluster/health").await;
    assert_eq!(health["status"], "green", "{health}");
    let (status, body) = send(&app, "GET", "/_cat/indices").await;
    assert_eq!(status, StatusCode::OK);
    assert!(!body.contains("broken"), "{body:?}");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn retry_over_http_reopens_the_index_once_the_cause_is_fixed() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    {
        let engine = Engine::new(config.clone()).expect("first boot");
        engine.create_index("broken", Schema::empty()).unwrap();
        let idx = engine.get_index("broken").unwrap();
        idx.index_document(Some("1".into()), serde_json::json!({"t": "hello"}))
            .await
            .unwrap();
        engine.flush_index("broken").await.unwrap();
    }
    let manifest = dir.path().join("broken").join("snapshot.json");
    let good = std::fs::read(&manifest).unwrap();
    std::fs::write(&manifest, b"{not json").unwrap();

    let engine = Engine::new(config.clone()).expect("reboot");
    let state = AppState::new(config, engine, Metrics::new().expect("metrics"));
    let app = build_es_compat_router(state);

    // Operator restores the manifest the storage error pointed them at, then
    // retries — no restart.
    std::fs::write(&manifest, &good).unwrap();
    let (status, body) = send_json(&app, "POST", "/_cluster/indices/failed/broken/_retry").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["data"]["reopened"], true, "{body}");

    let (_, health) = send_json(&app, "GET", "/_cluster/health").await;
    assert_eq!(health["status"], "green", "{health}");
    let (status, count) = send_json(&app, "GET", "/broken/_count").await;
    assert_eq!(status, StatusCode::OK, "{count}");
    assert_eq!(count["count"], 1, "the reopened index must serve its data");

    // Retrying a name that is not a failed index is a 404, not a silent ok.
    let (status, err) = send_json(&app, "POST", "/_cluster/indices/failed/broken/_retry").await;
    assert_eq!(status, StatusCode::NOT_FOUND, "{err}");
}

// ─────────────────────────────────────────────────────────────────────────────
// The boundary half: making a failed index visible must not make it visible to
// everyone. A brain a scoped key may not read stays unreadable when it breaks.
// ─────────────────────────────────────────────────────────────────────────────

const ADMIN_KEY: &str = "admin-secret-key-for-failed-index-test";

async fn send_auth(
    app: &axum::Router,
    method: &str,
    uri: &str,
    auth: &str,
) -> (StatusCode, String) {
    let req = Request::builder()
        .method(method)
        .uri(uri)
        .header("content-type", "application/json")
        .header("authorization", auth)
        .body(Body::empty())
        .expect("request");
    let resp = app.clone().oneshot(req).await.expect("response");
    let status = resp.status();
    let bytes = resp.into_body().collect().await.expect("body").to_bytes();
    (status, String::from_utf8_lossy(&bytes).into_owned())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_failed_brain_is_not_leaked_to_a_scoped_key() {
    // A brain and an ordinary index; the brain's manifest is corrupted so it
    // is a FAILED index on the boot that serves the requests below.
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config.auth.enabled = true;
    config.auth.admin_api_key = ADMIN_KEY.to_string();
    {
        let engine = Engine::new(config.clone()).expect("first boot");
        for name in [".xerj-memory-bob-edges", "logs-2026"] {
            engine.create_index(name, Schema::empty()).unwrap();
            let idx = engine.get_index(name).unwrap();
            idx.index_document(Some("1".into()), serde_json::json!({"t": "x"}))
                .await
                .unwrap();
            engine.flush_index(name).await.unwrap();
        }
    }
    std::fs::write(
        dir.path()
            .join(".xerj-memory-bob-edges")
            .join("snapshot.json"),
        b"{not json",
    )
    .unwrap();
    let engine = Engine::new(config.clone()).expect("reboot");
    let state = AppState::new(config, engine, Metrics::new().expect("metrics"));
    let app = build_es_compat_router(state);

    let admin = format!("ApiKey {ADMIN_KEY}");
    let mint = Request::builder()
        .method("POST")
        .uri("/_security/api_key")
        .header("content-type", "application/json")
        .header("authorization", &admin)
        .body(Body::from(
            r#"{"name":"logs-agent","role_descriptors":{"logs":{"indices":[
                 {"names":["logs-2026"],"privileges":["read","write"]}]}}}"#,
        ))
        .expect("request");
    let resp = app.clone().oneshot(mint).await.expect("response");
    assert_eq!(resp.status(), StatusCode::OK);
    let bytes = resp.into_body().collect().await.expect("body").to_bytes();
    let minted: Value = serde_json::from_slice(&bytes).expect("json");
    let agent = format!("ApiKey {}", minted["encoded"].as_str().expect("encoded"));

    for uri in [
        "/_cat/indices",
        "/_cat/shards",
        "/_cluster/state",
        "/_cluster/health?level=indices",
        "/_cluster/indices/failed",
    ] {
        let (status, body) = send_auth(&app, "GET", uri, &agent).await;
        assert!(status.is_success(), "{uri}: {status} {body}");
        assert!(
            !body.contains("bob"),
            "{uri} leaked a failed brain to a scoped key: {body}"
        );
    }

    // The admin still sees it — "prune everything" would pass the test above.
    let (status, body) = send_auth(&app, "GET", "/_cluster/indices/failed", &admin).await;
    assert!(status.is_success(), "{body}");
    assert!(body.contains("bob"), "the admin must still see it: {body}");
}

//! Issue #310 — a `fields` clause must see past the default `_source`
//! projection, and must not drag the projection open on the wire.
//!
//! Since #309 a request with no `_source` clause gets `SourceFilter::Default`
//! and the engine strips the generated embedding companions before the response
//! layer runs. `fields` and `docvalue_fields` resolve their values out of that
//! same `hit.source`, so a caller who explicitly named `body_vector` in `fields`
//! got nothing back — silently, since an unresolvable `fields` entry is legally
//! omitted — while the identical clause under `"_source": false` returned every
//! float, because `Enabled(false)` deliberately keeps the raw source.
//!
//! Every assertion below is paired. The POSITIVE half (the value comes back) is
//! the fix; the NEGATIVE half (`_source` still has no companion key) is what
//! makes the test worth having, because the fix works by asking the engine for
//! the intact source and re-narrowing it at emission — miss one emission site
//! and #309's guarantee regresses to a full-vector response with the positive
//! assertions still passing.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_common::types::{EmbeddingConfig, FieldConfig, FieldType, Schema};

const DIMS: usize = 32;

async fn seeded_app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);

    let mut schema = Schema::empty();
    let mut body = FieldConfig::new("body", FieldType::Text);
    body.options.dimensions = Some(DIMS);
    body.options.similarity = Some("cosine".into());
    body.embedding = Some(EmbeddingConfig {
        endpoint: None,
        model: None,
        target_field: Some("body_vector".into()),
    });
    schema.add_field(body).expect("body field");
    let mut companion = FieldConfig::new("body_vector", FieldType::Vector);
    companion.options.dimensions = Some(DIMS);
    companion.options.similarity = Some("cosine".into());
    schema.add_field(companion).expect("body_vector field");
    schema
        .add_field(FieldConfig::new("title", FieldType::Keyword))
        .expect("title field");

    state.engine.create_index("docs", schema).expect("create");
    let idx = state.engine.get_index("docs").expect("get index");
    idx.index_document(
        Some("1".into()),
        json!({
            "body": "XERJ resolves an explicitly named embedding companion \
                     through the fields API without widening _source. "
                .repeat(8),
            "title": "first",
        }),
    )
    .await
    .expect("index document");
    idx.refresh().await.expect("refresh");

    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn post(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::post(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

fn first_hit(response: &Value) -> &Value {
    &response["hits"]["hits"][0]
}

/// The three spellings of the same `fields` request must agree.
///
/// `_source` omitted was the broken one: it returned nothing while `_source:
/// false` — a strictly *stronger* statement of "do not send me the document" —
/// returned all 32 floats.
#[tokio::test]
async fn fields_resolves_a_named_companion_under_every_source_spelling() {
    let (app, _dir) = seeded_app().await;

    for source_clause in [None, Some(json!(false)), Some(json!(true))] {
        let mut body = json!({
            "query": { "match_all": {} },
            "size": 1,
            "fields": ["body_vector"],
        });
        if let Some(clause) = source_clause.clone() {
            body["_source"] = clause;
        }
        let label = source_clause
            .as_ref()
            .map(|c| c.to_string())
            .unwrap_or_else(|| "omitted".to_string());

        let (status, response) = post(&app, "/docs/_search", body).await;
        assert_eq!(status, StatusCode::OK, "_source {label}: {response}");

        let values = first_hit(&response)["fields"]["body_vector"]
            .as_array()
            .unwrap_or_else(|| panic!("_source {label}: no fields.body_vector in {response}"));
        assert_eq!(
            values.len(),
            DIMS,
            "_source {label}: fields.body_vector must carry the whole vector: {response}"
        );
    }
}

/// The #309 guarantee, restated as the negative control for the fix above: the
/// pierce hands the engine's intact source to the `fields` builder, so the ONLY
/// thing keeping the vector off the wire is the emission-time re-narrowing.
#[tokio::test]
async fn piercing_for_fields_does_not_widen_source_on_the_wire() {
    let (app, _dir) = seeded_app().await;

    let (status, response) = post(
        &app,
        "/docs/_search",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "fields": ["body_vector"],
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{response}");

    let hit = first_hit(&response);
    let source = hit["_source"]
        .as_object()
        .unwrap_or_else(|| panic!("_source must still be emitted: {response}"));
    assert!(
        !source.contains_key("body_vector"),
        "#309: the default projection must not return the generated companion in _source: {response}"
    );
    assert!(
        !source.contains_key("body_vector_chunks"),
        "#309: the default projection must not return the generated chunks in _source: {response}"
    );
    assert_eq!(
        source.get("title"),
        Some(&json!("first")),
        "ordinary user fields must survive the re-narrowing: {response}"
    );
    // …and the value the caller actually asked for is still there.
    assert_eq!(
        hit["fields"]["body_vector"]
            .as_array()
            .map(|v| v.len())
            .unwrap_or(0),
        DIMS,
        "{response}"
    );
}

/// A request that names nothing special must be byte-identical to the #309
/// default: no pierce, no `fields` block, no companion anywhere.
#[tokio::test]
async fn a_plain_default_search_is_untouched() {
    let (app, _dir) = seeded_app().await;

    let (status, response) = post(
        &app,
        "/docs/_search",
        json!({ "query": { "match_all": {} }, "size": 1 }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{response}");

    let source = first_hit(&response)["_source"]
        .as_object()
        .expect("_source object");
    assert!(!source.contains_key("body_vector"), "{response}");
    assert!(!source.contains_key("body_vector_chunks"), "{response}");
    assert!(source.contains_key("body"), "{response}");
}

/// `docvalue_fields` is the same resolution path, and used to emit the wrong
/// thing rather than nothing: `{"body_vector": []}` — a positive claim that the
/// document has no values for that field. A field that resolves to nothing is
/// omitted; a field that resolves is complete. Never an empty array.
#[tokio::test]
async fn docvalue_fields_never_emits_a_bare_empty_array() {
    let (app, _dir) = seeded_app().await;

    let (status, response) = post(
        &app,
        "/docs/_search",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "docvalue_fields": ["body_vector", "no_such_field"],
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{response}");

    let hit = first_hit(&response);
    assert_eq!(
        hit["fields"]["body_vector"]
            .as_array()
            .map(|v| v.len())
            .unwrap_or(0),
        DIMS,
        "docvalue_fields must resolve the named companion: {response}"
    );
    assert!(
        hit["fields"].get("no_such_field").is_none(),
        "an unresolvable docvalue_field is omitted, not emitted as []: {response}"
    );
    let source = hit["_source"].as_object().expect("_source object");
    assert!(
        !source.contains_key("body_vector"),
        "#309 must hold on the docvalue_fields route too: {response}"
    );
}

