    for (i, hit) in hits(&resp).iter().enumerate() {
        assert_eq!(
            hit["fields"]["body"],
            json!([full_body(DOCS[i].2)]),
            "object spelling: fields.body: {hit}"
        );
        assert_eq!(
            hit["_source"],
            json!({ "title": DOCS[i].1 }),
            "object spelling: _source narrowed: {hit}"
        );
    }

    // `?_source_includes=title` with a body `fields` clause.
    let (status, resp) = post(
