/// The pierce is an instrumentation trade, not a free fix: `Enabled(true)` is
/// not a measured shape in the engine, so a PIERCED request loses its
/// `_savings` note (the same trade #310's default-projection pierce makes) —
/// while a filter that already covers every named field must NOT pierce, and
/// so keeps the note it has always had. That asymmetry is the proof that the
/// coverage check keeps unaffected requests on the un-pierced path.
#[tokio::test]
async fn a_covered_name_keeps_the_savings_note_a_pierced_one_trades_it() {
    let (app, _dir) = seeded_app().await;

    // Covered (`title` is in the includes list): no pierce, `_savings` intact.
    let (status, covered) = post(
        &app,
        "/docs/_search",
        json!({ "query": { "match_all": {} }, "size": 4, "_source": ["title"], "fields": ["title"] }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{covered}");
    assert!(
        covered["_savings"].is_object(),
        "a covered name does not pierce; the default savings note stays: {covered}"
    );

    // Pierced (`body` is dropped by the includes list): the note is the cost.
    let (status, pierced) = post(
        &app,
        "/docs/_search",
        json!({ "query": { "match_all": {} }, "size": 4, "_source": ["title"], "fields": ["body"] }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{pierced}");
    assert!(
        pierced.get("_savings").is_none(),
        "a pierced request asks the engine for the intact source — nothing was \
         withheld, and no note may claim otherwise: {pierced}"
    );
    // …and the value the caller asked for is there.
    assert_eq!(
        pierced["hits"]["hits"][0]["fields"]["body"],
        json!([full_body(DOCS[0].2)]),
        "{pierced}"
    );
}

//! A file-card anchor (`ax_locator: "file"`) lives in the dataset index so a
//! graph edge can resolve it. It is not a content record. A bare `_count` —
//! what `xerj autoindex map` reads, and what an agent curls — must not count
//! it. An explicit query still does, and `_search` can still return the card.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

#[tokio::test]
async fn bare_count_skips_file_cards_and_a_term_query_still_sees_them() {
    let (app, _dir) = app().await;
    let (status, body) = json_req(
        &app,
        "PUT",
        "/docs",
        json!({
            "mappings": { "properties": {
                "body": { "type": "text" },
                "ax_locator": { "type": "keyword" }
            }}
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "create index: {body}");

    for (id, doc) in [
        ("s0", json!({"body": "the design", "ax_locator": "s0"})),
        ("s1", json!({"body": "the rest", "ax_locator": "s1"})),
        ("card", json!({"body": "README.md", "ax_locator": "file"})),
    ] {
        let (status, body) = json_req(&app, "PUT", &format!("/docs/_doc/{id}"), doc).await;
        assert!(status.is_success(), "index {id}: {status} {body}");
    }
    let (status, body) = json_req(&app, "POST", "/docs/_refresh", json!({})).await;
    assert!(status.is_success(), "refresh: {status} {body}");

    let (status, count) = json_req(&app, "GET", "/docs/_count", Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{count}");
    assert_eq!(
        count["count"].as_u64(),
        Some(2),
        "the file card must not inflate a bare count: {count}"
    );

    let (status, glob) = json_req(&app, "GET", "/docs*/_count", Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{glob}");
    assert_eq!(glob["count"].as_u64(), Some(2), "{glob}");

    let (status, cards) = json_req(
        &app,
        "POST",
        "/docs/_count",
        json!({"query": {"term": {"ax_locator": "file"}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{cards}");
    assert_eq!(
        cards["count"].as_u64(),
        Some(1),
        "an explicit card query still counts the anchor: {cards}"
    );

    let (status, search) = json_req(
        &app,
        "POST",
        "/docs/_search",
        json!({"size": 0, "track_total_hits": true, "query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{search}");
    assert_eq!(
        search.pointer("/hits/total/value").and_then(Value::as_u64),
        Some(3),
        "the card stays in the index: {search}"
    );
}

//! Issue #553 (fast-follow to #450): the #450 fix ANDs an alias's `filter` into
//! the by-query so a `_delete_by_query` through a FILTERED alias removes only
//! the slice the filter names — never the whole backing index (the #524
//! over-delete hazard). The 3-skeptic verification of #552 confirmed this is
//! correct by code inspection but flagged that no test EXERCISES it. This is
//! that test: it fails loudly if the alias filter is ever dropped and a filtered
//! by-query starts draining out-of-slice documents.
//!
//! Two members, each holding one in-slice (`status:active`) and one out-of-slice
//! (`status:archived`) document, behind a filtered alias. A `match_all`
//! `_delete_by_query` through the alias must delete exactly the two active docs
//! and leave the two archived docs untouched.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn count(app: &axum::Router, index: &str) -> u64 {
    let (_, body) = call(app, "GET", &format!("/{index}/_count"), Value::Null).await;
    body.get("count")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX)
}

/// A `_delete_by_query` through a FILTERED multi-index alias deletes only the
/// in-slice documents, never the whole backing index (#553 / #524).
#[tokio::test]
async fn delete_by_query_through_a_filtered_alias_deletes_only_the_slice() {
    let (app, _dir) = app().await;

    // Two members; each has one active (in-slice) and one archived (out-of-slice) doc.
    for member in ["idx-a", "idx-b"] {
        let (st, _) = call(
            &app,
            "PUT",
            &format!("/{member}"),
            json!({"mappings": {"properties": {"status": {"type": "keyword"}}}}),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {member}");
        for (id, status) in [("active", "active"), ("archived", "archived")] {
            let (st, _) = call(
                &app,
                "PUT",
                &format!("/{member}/_doc/{id}"),
                json!({"status": status}),
            )
            .await;
            assert_eq!(st, StatusCode::CREATED, "index {id} into {member}");
        }
        let (st, _) = call(&app, "POST", &format!("/{member}/_refresh"), Value::Null).await;
        assert_eq!(st, StatusCode::OK, "refresh {member}");
    }

    // Filtered alias 'hot' over both members: only status=active is in-slice.
    let the_filter = json!({ "term": { "status": "active" } });
    for member in ["idx-a", "idx-b"] {
        let (st, body) = call(
            &app,
            "PUT",
            &format!("/{member}/_alias/hot"),
            json!({ "filter": the_filter }),
        )
        .await;
        assert_eq!(
            st,
            StatusCode::OK,
            "create filtered alias on {member}: {body}"
        );
    }

    // A match_all delete through the filtered alias must touch ONLY the slice.
    let (status, body) = call(
        &app,
        "POST",
        "/hot/_delete_by_query",
        json!({"query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "_delete_by_query status: {body}");
    assert_eq!(
        body.get("deleted").and_then(Value::as_u64),
        Some(2),
        "a match_all delete through a filtered alias must delete only the two in-slice \
         (active) docs, not the whole backing index (#553/#524): {body}"
    );

    // The archived (out-of-slice) doc in each member must SURVIVE — the alias
    // filter is what stands between "delete my slice" and "empty my index".
    for member in ["idx-a", "idx-b"] {
        assert_eq!(
            count(&app, member).await,
            1,
            "member {member} must keep its out-of-slice (archived) doc after a filtered-alias \
             delete — over-deleting past the filter is the #524 data-loss hazard: {member}"
        );
    }
}

//! Issue #451 (failure class C): `msearch` (and `search_with_scroll`,
//! `msearch_template`, `_cat/count`) resolve an alias to its members and search
//! them directly, but never read `index_alias_metadata`, so an alias's `filter`
//! is dropped. A filtered alias is the standard poor-man's document-level
//! boundary, so these paths return document bodies the alias exists to hide —
//! while `_search` through the same alias honours the filter.
//!
//! This test pins the divergence on `_msearch`: a filtered alias that shows one
//! document via `_search` must show the same one document via `_msearch`, not
//! leak the out-of-slice document.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
