        &app,
        "PUT",
        "/idx-a/_alias/hot",
        json!({ "filter": { "term": { "status": "active" } } }),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create filtered alias");

    let nd = format!(
        "{}\n{}\n",
        json!({ "index": "hot" }),
        json!({ "source": "{\"query\":{\"match_all\":{}},\"track_total_hits\":true}", "params": {} })
    );
    let (status, body) = ndjson(&app, "/_msearch/template", nd).await;
    assert_eq!(status, StatusCode::OK, "_msearch/template status: {body}");
    let total = body
        .pointer("/responses/0/hits/total/value")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX);
    assert_eq!(
        total, 1,
        "_msearch/template through a filtered alias must honour the filter, not leak the \
         out-of-slice doc (#451 class C): {body}"
    );
}

//! `/_cat/allocation?format=json` carries the node's flood-stage gate (#2077).
//!
//! Autoindex reads this before it walks. The numbers are the data directory's
//! filesystem (the same `statvfs` the governor admits on), not a client-side
//! guess, and the threshold is the governor's effective percent — config
//! default 95, after any live cluster-settings override. The plain-text cat
//! table does not grow a column.

use axum::body::Body;
use axum::http::Request;
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

#[tokio::test]
async fn allocation_json_reports_the_flood_stage_gate_and_text_does_not() {
    let (app, _dir) = app().await;

    let response = app
        .clone()
        .oneshot(
            Request::get("/_cat/allocation?format=json")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .expect("json allocation");
    assert!(response.status().is_success());
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let body: serde_json::Value = serde_json::from_slice(&bytes).expect("json");
    let row = body
        .as_array()
        .and_then(|rows| rows.first())
        .expect("one allocation row");
    assert_eq!(row["disk.flood_stage"], "95");
    assert_eq!(row["disk.threshold_enabled"], "true");
    assert!(
        row["disk.flood_blocked"] == "true" || row["disk.flood_blocked"] == "false",
        "blocked is a cat-style boolean string: {row}"
    );
    let avail = row["disk.avail"].as_str().expect("disk.avail");
    assert!(
        avail.ends_with('b') && avail[..avail.len() - 1].chars().all(|c| c.is_ascii_digit()),
        "free space is a raw byte count, which is what autoindex parses: {avail}"
    );
    let percent: u64 = row["disk.percent"]
        .as_str()
        .expect("disk.percent")
        .parse()
        .expect("integer percent");
    assert!(percent <= 100, "{percent}");
    let data_dir = _dir.path().to_string_lossy().into_owned();
    assert_eq!(
        row["path.data"].as_str(),
        Some(data_dir.as_str()),
        "memory writes name this directory when the flood-stage block fires: {row}"
    );

    let response = app
        .oneshot(
            Request::get("/_cat/allocation")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .expect("text allocation");
    assert!(response.status().is_success());
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    let text = String::from_utf8(bytes.to_vec()).unwrap();
    assert!(
        text.contains("xerj-node-1"),
        "the text table is still the cat line: {text}"
    );
    assert!(
        !text.contains("flood"),
        "flood-stage fields are not text columns: {text}"
    );
}

//! Issue #1281: field names in `highlight.fields` may be patterns (`"*"`,
//! `"mess*"`, `"obj.*"`). XERJ looked each key up as a literal `_source` key,
//! so a Kibana-Discover-style `"fields": {"*": {}}` returned no highlight at
//! all. Expected results below were each verified against ES 8.13.4 on the
//! same mapping and document.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .unwrap(),
        )
        .await
        .unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn seeded() -> (axum::Router, tempfile::TempDir) {
    let (app, dir) = app().await;
    let (st, body) = call(
        &app,
