            vec!["message", "title"],
        ),
        (
            json!({"query_string": {"query": "timeout"}}),
            vec!["host", "message", "obj.inner", "title"],
        ),
        (json!({"term": {"host": "timeout"}}), vec!["host"]),
    ] {
