async fn highlight_fields_array_form_matches_the_object_form() {
    let (app, _dir) = seeded().await;
    let object_form = json!({
        "query": {"match": {"body": "pricing"}},
        "highlight": {"fields": {"body": {"pre_tags": ["["], "post_tags": ["]"]}}}
    });
    let array_form = json!({
        "query": {"match": {"body": "pricing"}},
        "highlight": {"fields": [{"body": {"pre_tags": ["["], "post_tags": ["]"]}}]}
    });
    let (st, want) = send(
