fn defs_mapping() -> Value {
    json!({ "properties": {
        "symbol": {"type": "keyword"}, "symbol_text": {"type": "text"},
        "kind": {"type": "keyword"}, "lang": {"type": "keyword"},
        "file": {"type": "keyword"}, "line": {"type": "integer"},
