        .iter()
        .any(|(k, v)| k == "cache-control" && v == "public, max-age=3600"));
    assert!(body.contains("\"corpora\""));
    // …and the rest of the node is still closed.
    let (status, _, _) = raw_get(addr, "/_cluster/health", &[]).await;
    assert_eq!(status, 401);

