    // Nested knn on `items.vector`, which the nested mapping does not have.
    let (status, body) = json_req(
        &app,
        "POST",
        "/docs/_search",
        json!({ "query": { "nested": { "path": "items", "query": { "knn": {
            "field": "items.vector", "query_vector": [0.1, 0.2, 0.3], "k": 5, "num_candidates": 50
        } } } } }),
