//! Issue #1932: `_msearch` did not expand a wildcard index. A header
//! `{"index":"logs-*"}` or the path form `/logs-*/_msearch` answered the item
//! with 404 `index_not_found_exception` for the literal pattern, while
//! `_search` on the same pattern found the documents. The item now resolves
//! its target through the same selector the other read endpoints use.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(
    app: &axum::Router,
    method: &str,
    path: &str,
    ctype: &str,
    body: String,
) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    if !body.is_empty() {
        req = req.header("content-type", ctype);
    }
    let response = app
        .clone()
        .oneshot(req.body(Body::from(body)).unwrap())
        .await
        .unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

fn hit_indices(item: &Value) -> Vec<String> {
    let mut out: Vec<String> = item["hits"]["hits"]
        .as_array()
        .unwrap_or(&Vec::new())
        .iter()
        .filter_map(|h| h["_index"].as_str().map(str::to_string))
        .collect();
    out.sort();
    out
}

#[tokio::test]
async fn msearch_expands_a_wildcard_index_in_the_header_and_the_path() {
    let (app, _dir) = app().await;
    for index in ["logs-app", "logs-web", "metrics-app"] {
        let (st, resp) = send(
            &app,
            "PUT",
            &format!("/{index}"),
            "application/json",
            json!({"mappings": {"properties": {"msg": {"type": "text"}}}}).to_string(),
        )
        .await;
        assert_eq!(st, StatusCode::OK, "create {index}: {resp}");
        let (st, resp) = send(
            &app,
            "PUT",
            &format!("/{index}/_doc/1?refresh=true"),
            "application/json",
            json!({"msg": format!("disk full on {index}")}).to_string(),
        )
        .await;
        assert_eq!(st, StatusCode::CREATED, "index into {index}: {resp}");
    }

    let query = r#"{"query":{"match":{"msg":"disk"}}}"#;
    let cases = [
        ("/_msearch", format!("{{\"index\":\"logs-*\"}}\n{query}\n")),
        ("/logs-*/_msearch", format!("{{}}\n{query}\n")),
        (
            "/_msearch",
            format!("{{\"index\":\"logs-*,metrics-app\"}}\n{query}\n"),
        ),
    ];
    let expected: [&[&str]; 3] = [
        &["logs-app", "logs-web"],
        &["logs-app", "logs-web"],
        &["logs-app", "logs-web", "metrics-app"],
    ];
    for ((path, body), want) in cases.into_iter().zip(expected) {
        let (st, resp) = send(&app, "POST", path, "application/x-ndjson", body.clone()).await;
        assert_eq!(st, StatusCode::OK, "{path} {body}: {resp}");
        let item = &resp["responses"][0];
        assert_eq!(item["status"], 200, "{path} {body}: {resp}");
        assert_eq!(hit_indices(item), want, "{path} {body}: {resp}");
        assert_eq!(
            item["hits"]["total"]["value"],
            want.len(),
            "{path} {body}: {resp}"
        );
    }

    // A pattern that matches nothing is an empty result, as on `_search`,
    // not a 404 for the pattern.
    let (st, resp) = send(
        &app,
        "POST",
        "/_msearch",
        "application/x-ndjson",
        format!("{{\"index\":\"nomatch-*\"}}\n{query}\n"),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "{resp}");
    let item = &resp["responses"][0];
    assert_eq!(item["status"], 200, "{resp}");
    assert_eq!(item["hits"]["total"]["value"], 0, "{resp}");

    // A missing concrete name still fails that item with 404.
    let (_, resp) = send(
        &app,
        "POST",
        "/_msearch",
        "application/x-ndjson",
        format!("{{\"index\":\"missing\"}}\n{query}\n"),
    )
    .await;
    assert_eq!(resp["responses"][0]["status"], 404, "{resp}");
}

//! Issue #395: a `semantic`/`knn` clause nested inside a `bool` is silently
//! dropped — the engine only *peels the top* of the query tree, so a vector
//! clause that is not at the top (or is one of several `bool` clauses) never
//! reaches the vector path. The request answers `200 OK` with the purely lexical
//! result set, no error and no `_shards.failed`.
//!
//! Case B from the report: a `bool` whose only clause is `semantic` returns zero
//! hits, while the same clause at the top level returns all three documents.
//! Whatever the resolution (dispatch the nested clause, or reject it loudly),
//! `bool{must:[semantic]}` must not silently answer `200`/zero.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn total(app: &axum::Router, query: Value) -> (StatusCode, u64) {
    let (status, body) = call(
        app,
        "POST",
        "/docs/_search",
        json!({ "query": query, "size": 10, "track_total_hits": true }),
    )
    .await;
    let t = body
        .pointer("/hits/total/value")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX);
    (status, t)
}

/// A `bool` whose only clause is `semantic` must return the same documents as
/// the bare `semantic` clause — not silently drop the vector half to zero (#395).
#[tokio::test]
async fn semantic_clause_nested_in_bool_is_not_silently_dropped() {
    let (app, _dir) = app().await;
    let (st, body) = call(
        &app,
        "PUT",
        "/docs",
        json!({"mappings": {"properties": {
            "ctx": { "type": "semantic_text", "dimensions": 32 }
        }}}),
    )
    .await;
    assert!(st.is_success(), "create semantic_text index: {st} {body}");

    for (id, text) in [
        ("0", "graph edges connect nodes in a network"),
        ("1", "weather forecast sunshine and rain today"),
        ("2", "edges and vertices form a graph structure"),
    ] {
        let (st, _) = call(
            &app,
            "POST",
            &format!("/docs/_doc/{id}"),
            json!({ "ctx": text }),
        )
        .await;
        assert!(st.is_success(), "index doc {id}: {st}");
    }
    let (_s, _b) = call(&app, "POST", "/docs/_refresh", Value::Null).await;

    let q = "graph edges";
    let sem = json!({ "semantic": { "field": "ctx", "query": q, "k": 10 } });

    // A: bare semantic — the baseline the nested form must match.
    let (sa, bare_total) = total(&app, sem.clone()).await;
    assert_eq!(sa, StatusCode::OK, "bare semantic status");
    assert!(
        bare_total > 0,
        "precondition: bare semantic must find the semantic_text docs (got {bare_total})"
    );

    // B: the SAME clause nested in a single-clause bool.must.
    let (sb, nested_total) = total(&app, json!({ "bool": { "must": [ sem ] } })).await;

    // If the executor cannot dispatch the nested clause it must say so (400),
    // not answer 200 with a silently lexical/empty result. Either way it must
    // NOT return a smaller, misleading hit set than the bare form.
    if sb == StatusCode::OK {
        assert_eq!(
            nested_total, bare_total,
            "a bool wrapping only a `semantic` clause returned {nested_total} hits vs {bare_total} \
             for the bare clause — the vector half was silently dropped (#395)"
        );
    } else {
        assert_eq!(
            sb,
            StatusCode::BAD_REQUEST,
            "a nested vector clause that cannot be dispatched must 400 (naming `hybrid`), \
             not answer a silent lexical 200 (#395): got {sb}"
        );
    }
}

//! Issue #1284: a string that is not a number, sent to a numeric field by a
//! `term` / `terms` / `range` clause, or by a full-text clause that is not
