    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(
    app: &axum::Router,
    method: &str,
    path: &str,
    ctype: &str,
    body: String,
) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    if !body.is_empty() {
        req = req.header("content-type", ctype);
    }
    let response = app
        .clone()
        .oneshot(req.body(Body::from(body)).unwrap())
        .await
        .unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

async fn seeded() -> (axum::Router, tempfile::TempDir) {
    let (app, dir) = app().await;
    let (st, body) = send(
        &app,
        "PUT",
        "/t84",
        "application/json",
        json!({"mappings": {"properties": {
            "bytes": {"type": "long"},
            "ms": {"type": "float"},
            "h": {"type": "keyword"},
            "msg": {"type": "text"}
        }}})
        .to_string(),
    )
    .await;
    assert_eq!(st, StatusCode::OK, "create index: {body}");
    let (st, body) = send(
        &app,
        "PUT",
        "/t84/_doc/1?refresh=true",
        "application/json",
        json!({"bytes": 1, "ms": 1.5, "h": "a", "msg": "hello"}).to_string(),
    )
    .await;
    assert_eq!(st, StatusCode::CREATED, "index doc: {body}");
    (app, dir)
}

async fn count(app: &axum::Router, query: Value) -> (StatusCode, Value) {
    send(
        app,
        "POST",
        "/t84/_count",
        "application/json",
        json!({ "query": query }).to_string(),
    )
    .await
}

/// Every shape here returned 400 on ES 8.13.4 with this exact reason.
#[tokio::test]
async fn non_numeric_term_level_values_are_a_400() {
    let (app, _dir) = seeded().await;
    for query in [
        json!({"term": {"bytes": "abc"}}),
        json!({"term": {"bytes": {"value": "abc"}}}),
        json!({"terms": {"bytes": ["1", "abc"]}}),
        json!({"range": {"bytes": {"gte": "abc"}}}),
        json!({"term": {"ms": "abc"}}),
        json!({"bool": {"filter": [{"term": {"bytes": "abc"}}]}}),
    ] {
        for path in ["/t84/_count", "/t84/_search"] {
            let (st, resp) = send(
                &app,
                "POST",
                path,
                "application/json",
                json!({ "query": query }).to_string(),
            )
            .await;
            assert_eq!(st, StatusCode::BAD_REQUEST, "{path} {query}: {resp}");
            assert!(
                resp.to_string()
                    .contains(r#"failed to create query: For input string: \"abc\""#),
                "{path} {query}: reason must name the bad value: {resp}"
            );
        }
    }
}

/// Valid queries that ES answers 200 must keep answering 200.
#[tokio::test]
async fn numeric_strings_and_non_numeric_fields_stay_valid() {
    let (app, _dir) = seeded().await;
    for (query, hits) in [
        (json!({"term": {"bytes": "1"}}), 1),
        (json!({"term": {"bytes": 1}}), 1),
        // ES: a decimal against a long is a valid query that matches nothing.
        (json!({"term": {"bytes": "1.5"}}), 0),
        (json!({"range": {"bytes": {"gte": "0", "lte": "5"}}}), 1),
        (json!({"term": {"h": "abc"}}), 0),
        // `query_string` without `lenient`: 200 on ES 8.13.4 too.
        (json!({"query_string": {"query": "bytes:abc"}}), 0),
    ] {
        let (st, resp) = count(&app, query.clone()).await;
        assert_eq!(st, StatusCode::OK, "{query}: {resp}");
        assert_eq!(resp["count"], json!(hits), "{query}: {resp}");
    }
}

/// Full-text clauses that are not lenient. Every shape here returned 400 on
/// ES 8.13.4 with this exact reason: `match` with `lenient` absent or false,
/// and `multi_match` / `query_string` / `simple_query_string` whose field set
/// is narrower than every field (so ES defaults `lenient` to false), or that
/// say `lenient: false` outright.
#[tokio::test]
async fn non_lenient_full_text_clauses_are_a_400() {
    let (app, _dir) = seeded().await;
    for query in [
        json!({"match": {"bytes": "abc"}}),
        json!({"match": {"bytes": {"query": "abc", "lenient": false}}}),
        json!({"match": {"ms": "abc"}}),
        json!({"match_phrase": {"bytes": "abc"}}),
        json!({"multi_match": {"query": "abc", "fields": ["bytes", "msg"]}}),
        json!({"multi_match": {"query": "abc", "fields": ["b*"]}}),
        json!({"multi_match": {"query": "abc", "fields": ["bytes"], "type": "phrase"}}),
        json!({"query_string": {"query": "bytes:abc", "lenient": false}}),
        json!({"query_string": {"query": "abc", "default_field": "bytes"}}),
        json!({"query_string": {"query": "abc", "fields": ["bytes", "msg"]}}),
        json!({"query_string": {"query": "bytes:(1 OR abc)", "lenient": false}}),
        json!({"query_string": {"query": "bytes:>abc", "lenient": false}}),
        json!({"query_string": {"query": "bytes:\"abc\"", "lenient": false}}),
        json!({"query_string": {"query": "msg:abc AND bytes:abc", "lenient": false}}),
        json!({"simple_query_string": {"query": "abc", "fields": ["bytes"]}}),
        json!({"simple_query_string": {"query": "abc", "fields": ["bytes", "msg"]}}),
        json!({"bool": {"filter": [{"match": {"bytes": "abc"}}]}}),
    ] {
        for path in ["/t84/_count", "/t84/_search"] {
            let (st, resp) = query_on(&app, path, &query).await;
            assert_eq!(st, StatusCode::BAD_REQUEST, "{path} {query}: {resp}");
            assert!(
                resp.to_string()
                    .contains(r#"failed to create query: For input string: \"abc\""#),
                "{path} {query}: reason must name the bad value: {resp}"
            );
        }
    }
}

/// Lenient full-text clauses stay a 200, as on ES 8.13.4: an explicit
/// `lenient: true`, and the every-field default (`query_string` with no
/// `default_field`, or `["*"]`), which is lenient even for a clause that names
/// the numeric field itself. The two `query_string` ranges were a 200 on main
/// and must not become a 400 now that ranges are checked.
#[tokio::test]
async fn lenient_full_text_clauses_stay_a_200() {
    let (app, _dir) = seeded().await;
    for (query, hits) in [
        (
            json!({"match": {"bytes": {"query": "abc", "lenient": true}}}),
            0,
        ),
        (
            json!({"match": {"bytes": {"query": "abc", "lenient": "true"}}}),
            0,
        ),
        (
            json!({"multi_match": {"query": "abc", "fields": ["bytes", "msg"], "lenient": true}}),
            0,
        ),
        (json!({"query_string": {"query": "bytes:abc"}}), 0),
        (
            json!({"query_string": {"query": "bytes:abc", "lenient": true}}),
            0,
        ),
        (json!({"query_string": {"query": "bytes:>abc"}}), 0),
        (json!({"query_string": {"query": "bytes:[abc TO 5]"}}), 0),
        (json!({"query_string": {"query": "bytes:\"abc\""}}), 0),
        (
            json!({"query_string": {"query": "bytes:>abc", "default_field": "*"}}),
            0,
        ),
        (
            json!({"simple_query_string": {"query": "abc", "fields": ["bytes"], "lenient": true}}),
            0,
        ),
        // Valid values on a numeric field, and full-text on text fields.
        (json!({"match": {"bytes": "1"}}), 1),
        (json!({"match": {"bytes": "1.5"}}), 0),
        (
            json!({"multi_match": {"query": "1", "fields": ["bytes"]}}),
            1,
        ),
        (
            json!({"query_string": {"query": "bytes:1", "lenient": false}}),
            1,
        ),
        (json!({"match": {"msg": "hello"}}), 1),
    ] {
        // `_search` matters on its own: its ES-compat layer rewrites a `match`
        // on a numeric field to a `term` before the engine sees it.
        for path in ["/t84/_count", "/t84/_search"] {
            let (st, resp) = query_on(&app, path, &query).await;
            assert_eq!(st, StatusCode::OK, "{path} {query}: {resp}");
            let got = if path.ends_with("_count") {
                &resp["count"]
            } else {
                &resp["hits"]["total"]["value"]
            };
            assert_eq!(got, &json!(hits), "{path} {query}: {resp}");
        }
    }
}

async fn query_on(app: &axum::Router, path: &str, query: &Value) -> (StatusCode, Value) {
    send(
        app,
        "POST",
        path,
        "application/json",
        json!({ "query": query }).to_string(),
    )
    .await
}

/// `_msearch` fails only the offending item.
#[tokio::test]
async fn non_numeric_value_fails_only_that_msearch_item() {
    let (app, _dir) = seeded().await;
    let ndjson = "{\"index\":\"t84\"}\n{\"query\":{\"term\":{\"bytes\":\"abc\"}}}\n\
                  {\"index\":\"t84\"}\n{\"query\":{\"term\":{\"bytes\":\"1\"}}}\n"
        .to_string();
    let (st, resp) = send(&app, "POST", "/_msearch", "application/x-ndjson", ndjson).await;
    assert_eq!(st, StatusCode::OK, "{resp}");
    let items = resp["responses"].as_array().expect("responses");
    assert_eq!(items[0]["status"], 400, "bad item: {resp}");
    assert_eq!(items[1]["status"], 200, "good item still runs: {resp}");
    assert_eq!(items[1]["hits"]["total"]["value"], 1, "{resp}");
}

//! Numeric and boolean fields enforce their declared type, from the outside —
//! issue #781.
//!
//! A field mapped `integer` used to accept and keep literally anything: `1.9`
//! stayed `1.9`, `9999999999` stayed exact, `"abc"` was stored as a string,
//! and even `{"bad": "x"}` was indexed. Every one of those was a `201`.
//!
//! The worst of it is not leniency, it is wrong hits. With `1.9` sitting in an
//! `integer` field, `range {"i": {"gte": 1.5}}` MATCHED in xerj and would not
//! in ES (which indexes the truncated `1`), while `term {"i": 1}` matched in
//! ES and returned nothing here. Same mapping, same document, same query,
//! different answers — `wrong_results_the_declared_type_used_to_produce`
//! below is that case, pinned.
//!
//! ES 8.x semantics, with `coerce` defaulting to `true`:
//!
//! * `1.9` → `1` (truncated toward zero), `"5"` → `5`, `"1.9"` → `1`
//! * `"true"`/`"false"` → the booleans
//! * out of range for the declared width → **400**
//! * unparseable string, object, array, `"yes"` in a boolean → **400**
//! * `"coerce": false` additionally refuses the decimal part and the string
//!
//! Every write path that knows the typed schema is covered here: `PUT
//! /{index}/_doc/{id}`, `POST /{index}/_doc` (auto-id), `PUT
//! /{index}/_create/{id}`, and `_bulk` — including the turbo batch path
//! auto-id bulk takes, which never parses the document body and so had to be
//! reached by a partition-time check rather than the per-item loop.
//!
//! Elasticsearch is referenced for semantics only. It is AGPL-3.0/SSPL-1.0/
//! Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method(method)
            .uri(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn bulk(app: &axum::Router, path: &str, ndjson: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::post(path)
            .header("content-type", "application/x-ndjson")
            .body(Body::from(ndjson.to_owned()))
            .expect("request"),
    )
    .await
}

/// `i` integer, `l` long, `f` float, `b` boolean, `strict` integer with
/// `coerce: false`, `lenient` integer with `ignore_malformed: true`, plus a
/// nested object and a `keyword` this check must not touch.
async fn typed_index(name: &str) -> (axum::Router, tempfile::TempDir) {
    let (app, dir) = app().await;
    let (status, _) = json_req(
        &app,
        "PUT",
        &format!("/{name}"),
        json!({
            "mappings": {
                "properties": {
                    "i": { "type": "integer" },
                    "l": { "type": "long" },
                    "f": { "type": "float" },
                    "b": { "type": "boolean" },
                    "strict": { "type": "integer", "coerce": false },
                    "lenient": { "type": "integer", "ignore_malformed": true },
                    "k": { "type": "keyword" },
                    "inner": { "properties": { "n": { "type": "integer" } } }
                }
            }
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "mapping should be accepted");
    (app, dir)
}

async fn put_doc(app: &axum::Router, index: &str, id: &str, doc: Value) -> (StatusCode, Value) {
    json_req(app, "PUT", &format!("/{index}/_doc/{id}"), doc).await
}

/// Flush the memtable into a segment.
///
/// This matters for the query-side tests at the bottom of this file: while a
/// document is memtable-resident, `term`/`terms` are answered by the doc-values
/// fast path, which compares STRINGIFIED values and so is blind to the
/// boolean-versus-`"boolean"` spelling. It is the flushed segment path — a
/// doc-values prefilter refined by an exact re-test of `_source` — that
/// distinguishes them, which is why the ES-YAML case that caught this
/// (`search/390_doc_values_search.yml`) does `indices.refresh` before it
/// queries. A test that skips the refresh passes on the broken code.
async fn refresh(app: &axum::Router, index: &str) {
    let (status, body) = json_req(app, "POST", &format!("/{index}/_refresh"), json!({})).await;
    assert_eq!(status, StatusCode::OK, "refresh should succeed: {body}");
}

async fn search(app: &axum::Router, index: &str, query: Value) -> Value {
    let (status, body) = json_req(
        app,
        "POST",
        &format!("/{index}/_search"),
        json!({ "query": query }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "search should succeed: {body}");
    body
}

fn hit_count(body: &Value) -> u64 {
    body["hits"]["total"]["value"].as_u64().unwrap_or(0)
}

fn is_parsing_rejection(status: StatusCode, body: &Value, field: &str) -> bool {
    status == StatusCode::BAD_REQUEST
        && body["error"]["type"] == "document_parsing_exception"
        && body["error"]["reason"]
            .as_str()
            .map(|r| r.contains(&format!("failed to parse field [{field}]")))
            .unwrap_or(false)
}

// ─────────────────────────────────────────────────────────────────────────────
// The wrong-results case that makes this a bug and not a style preference.
// ─────────────────────────────────────────────────────────────────────────────

/// `1.9` into an `integer` field. ES truncates it to `1` at ingest, so
/// `range {gte: 1.5}` misses and `term {i: 1}` hits. Before the fix xerj
/// stored `1.9` verbatim and answered both queries the other way round.
#[tokio::test]
async fn wrong_results_the_declared_type_used_to_produce() {
    let (app, _dir) = typed_index("t").await;

    let (status, _) = put_doc(&app, "t", "1", json!({ "i": 1.9 })).await;
    assert_eq!(status, StatusCode::CREATED);

    // The stored value is the integer ES would have indexed.
    let (_, doc) = get(&app, "/t/_doc/1").await;
    assert_eq!(doc["_source"]["i"], json!(1), "1.9 should truncate to 1");

    let gte = search(&app, "t", json!({ "range": { "i": { "gte": 1.5 } } })).await;
    assert_eq!(
        hit_count(&gte),
        0,
        "an integer field holding ES's 1 must not match gte 1.5: {gte}"
    );

    let term = search(&app, "t", json!({ "term": { "i": 1 } })).await;
    assert_eq!(
        hit_count(&term),
        1,
        "term 1 must find the truncated value: {term}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Coercion: the values ES accepts and rewrites.
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn numeric_strings_and_boolean_spellings_are_coerced() {
    let (app, _dir) = typed_index("t").await;

    let (status, _) = put_doc(
        &app,
        "t",
        "1",
        json!({ "i": "5", "l": "-7", "f": "2.5", "b": "true", "inner": { "n": "3" } }),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED);

    let (_, doc) = get(&app, "/t/_doc/1").await;
    assert_eq!(doc["_source"]["i"], json!(5));
    assert_eq!(doc["_source"]["l"], json!(-7));
    assert_eq!(doc["_source"]["f"], json!(2.5));
    assert_eq!(doc["_source"]["b"], json!(true));
    assert_eq!(doc["_source"]["inner"]["n"], json!(3), "nested too");

    // Coerced, therefore queryable as the number it now is.
    let term = search(&app, "t", json!({ "term": { "i": 5 } })).await;
    assert_eq!(hit_count(&term), 1, "coerced string is numerically indexed");
}

#[tokio::test]
async fn arrays_are_coerced_element_wise() {
    let (app, _dir) = typed_index("t").await;

    let (status, _) = put_doc(&app, "t", "1", json!({ "i": [1.9, "3", 4] })).await;
    assert_eq!(status, StatusCode::CREATED);

    let (_, doc) = get(&app, "/t/_doc/1").await;
    assert_eq!(doc["_source"]["i"], json!([1, 3, 4]));
}

#[tokio::test]
async fn values_that_already_match_the_type_are_left_alone() {
    let (app, _dir) = typed_index("t").await;

    // `2.0` is already the integer ES indexes — no `_source` churn — and a
    // `keyword` field is not this check's business at all.
    let (status, _) = put_doc(
        &app,
        "t",
        "1",
        json!({ "i": 2.0, "l": 42, "b": false, "k": 7, "unmapped": { "any": "shape" } }),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED);

    let (_, doc) = get(&app, "/t/_doc/1").await;
    assert_eq!(doc["_source"]["l"], json!(42));
    assert_eq!(doc["_source"]["b"], json!(false));
    assert_eq!(doc["_source"]["k"], json!(7), "keyword is not coerced");
    assert_eq!(doc["_source"]["unmapped"], json!({ "any": "shape" }));
}

// ─────────────────────────────────────────────────────────────────────────────
// Rejection: the values ES refuses outright.
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn a_non_numeric_string_is_refused() {
    let (app, _dir) = typed_index("t").await;
    let (status, body) = put_doc(&app, "t", "1", json!({ "i": "abc" })).await;
    assert!(
        is_parsing_rejection(status, &body, "i"),
        "expected 400 document_parsing_exception, got {status}: {body}"
    );
    assert!(
        body["error"]["caused_by"]["reason"]
            .as_str()
            .unwrap_or_default()
            .contains("abc"),
        "the caused_by should name the offending input: {body}"
    );
    // Nothing was written.
    assert_eq!(get(&app, "/t/_doc/1").await.0, StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn an_out_of_range_value_is_refused_even_though_it_is_an_integer() {
    let (app, _dir) = typed_index("t").await;

    let (status, body) = put_doc(&app, "t", "1", json!({ "i": 9999999999i64 })).await;
    assert!(
        is_parsing_rejection(status, &body, "i"),
        "9999999999 does not fit an integer: {status} {body}"
    );

    // The same number in a `long` is perfectly fine.
    let (status, _) = put_doc(&app, "t", "2", json!({ "l": 9999999999i64 })).await;
    assert_eq!(status, StatusCode::CREATED);
}

#[tokio::test]
async fn a_boolean_takes_only_true_and_false() {
    let (app, _dir) = typed_index("t").await;

    let (status, body) = put_doc(&app, "t", "1", json!({ "b": "yes" })).await;
    assert!(
        is_parsing_rejection(status, &body, "b"),
        "\"yes\" is not a boolean: {status} {body}"
    );

    let (status, body) = put_doc(&app, "t", "2", json!({ "b": 1 })).await;
    assert!(
        is_parsing_rejection(status, &body, "b"),
        "1 is not a boolean in ES 8.x: {status} {body}"
    );
}

/// The comment on the issue: an OBJECT went into an integer field and the
/// document was indexed, so the declared type enforced nothing at all.
#[tokio::test]
async fn an_object_is_not_a_number() {
    let (app, _dir) = typed_index("t").await;
    let (status, body) = put_doc(&app, "t", "1", json!({ "i": { "bad": "x" } })).await;
    assert!(
        is_parsing_rejection(status, &body, "i"),
        "an object in an integer field must be refused: {status} {body}"
    );
    assert!(
        body["error"]["reason"]
            .as_str()
            .unwrap_or_default()
            .contains("bad=x"),
        "the preview should render the object ES-style: {body}"
    );
}

#[tokio::test]
async fn a_bad_nested_field_is_named_by_its_dotted_path() {
    let (app, _dir) = typed_index("t").await;
    let (status, body) = put_doc(&app, "t", "1", json!({ "inner": { "n": "abc" } })).await;
    assert!(
        is_parsing_rejection(status, &body, "inner.n"),
        "expected the dotted path in the reason: {status} {body}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// The two mapping parameters that change the answer.
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn coerce_false_refuses_what_the_default_would_fix() {
    let (app, _dir) = typed_index("t").await;

    for bad in [json!(1.9), json!("5")] {
        let (status, body) = put_doc(&app, "t", "1", json!({ "strict": bad })).await;
        assert!(
            is_parsing_rejection(status, &body, "strict"),
            "coerce:false should refuse {bad}: {status} {body}"
        );
    }

    // An in-range integer still goes in.
    let (status, _) = put_doc(&app, "t", "1", json!({ "strict": 3 })).await;
    assert_eq!(status, StatusCode::CREATED);
}

#[tokio::test]
async fn ignore_malformed_still_wins_over_rejection() {
    let (app, _dir) = typed_index("t").await;

    // The field asked for the bad value to be dropped into `_ignored`, not for
    // the document to be refused — that contract must survive this change.
    let (status, _) = put_doc(&app, "t", "1", json!({ "lenient": "abc", "i": 4 })).await;
    assert_eq!(status, StatusCode::CREATED, "ignore_malformed must not 400");

    let (_, doc) = get(&app, "/t/_doc/1").await;
    assert_eq!(doc["_source"]["i"], json!(4));
    assert!(
        doc["_source"].get("lenient").is_none(),
        "the malformed value should have been dropped: {doc}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Every other write path agrees with `PUT /_doc/{id}`.
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn the_auto_id_and_create_endpoints_enforce_the_same_rules() {
    let (app, _dir) = typed_index("t").await;

    let (status, body) = json_req(&app, "POST", "/t/_doc", json!({ "i": "abc" })).await;
    assert!(
        is_parsing_rejection(status, &body, "i"),
        "POST /_doc must refuse it too: {status} {body}"
    );

    let (status, body) = json_req(&app, "PUT", "/t/_create/9", json!({ "b": "yes" })).await;
    assert!(
        is_parsing_rejection(status, &body, "b"),
        "PUT /_create/{{id}} must refuse it too: {status} {body}"
    );

    // …and coerce on the happy path.
    let (status, _) = json_req(&app, "PUT", "/t/_create/10", json!({ "i": 1.9 })).await;
    assert_eq!(status, StatusCode::CREATED);
    let (_, doc) = get(&app, "/t/_doc/10").await;
    assert_eq!(doc["_source"]["i"], json!(1));
}

/// `_bulk` reports per item and isolates failures — including on the auto-id
/// turbo batch path, which never parses the document body.
#[tokio::test]
async fn bulk_rejects_per_item_and_keeps_the_good_ones() {
    let (app, _dir) = typed_index("t").await;

    let ndjson = concat!(
        "{\"index\":{\"_id\":\"ok\"}}\n{\"i\":1.9}\n",
        "{\"index\":{\"_id\":\"bad-str\"}}\n{\"i\":\"abc\"}\n",
        "{\"index\":{\"_id\":\"bad-range\"}}\n{\"i\":9999999999}\n",
        "{\"index\":{\"_id\":\"bad-obj\"}}\n{\"i\":{\"bad\":\"x\"}}\n",
        "{\"index\":{\"_id\":\"bad-bool\"}}\n{\"b\":\"yes\"}\n",
        "{\"create\":{\"_id\":\"ok2\"}}\n{\"i\":\"7\"}\n",
    );
    let (status, body) = bulk(&app, "/t/_bulk", ndjson).await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(body["errors"], json!(true), "{body}");

    let items = body["items"].as_array().expect("items");
    assert_eq!(items.len(), 6);
    let code = |n: usize| -> u64 {
        items[n]
            .as_object()
            .and_then(|o| o.values().next())
            .and_then(|v| v["status"].as_u64())
            .unwrap_or(0)
    };
    assert_eq!(code(0), 201, "the coercible one lands: {body}");
    for (n, what) in [(1, "string"), (2, "range"), (3, "object"), (4, "boolean")] {
        assert_eq!(code(n), 400, "bad {what} should be a per-item 400: {body}");
    }
    assert_eq!(code(5), 201, "create coerces too: {body}");

    // Only the two good documents exist, with ES's values.
    let (_, ok) = get(&app, "/t/_doc/ok").await;
    assert_eq!(ok["_source"]["i"], json!(1));
    let (_, ok2) = get(&app, "/t/_doc/ok2").await;
    assert_eq!(ok2["_source"]["i"], json!(7));
    assert_eq!(get(&app, "/t/_doc/bad-str").await.0, StatusCode::NOT_FOUND);

    let (_, count) = get(&app, "/t/_count").await;
    assert_eq!(count["count"], json!(2), "{count}");
}

/// Auto-id bulk is the turbo batch path: the doc body is never parsed and the
/// whole group is appended in one shot, so it needed its own check. Without
/// it, every bad value in this batch was a silent 201.
#[tokio::test]
async fn the_bulk_turbo_path_is_not_a_way_around_the_check() {
    let (app, _dir) = typed_index("t").await;

    let ndjson = concat!(
        "{\"index\":{}}\n{\"i\":1.9}\n",
        "{\"index\":{}}\n{\"i\":\"abc\"}\n",
        "{\"index\":{}}\n{\"i\":\"6\"}\n",
    );
    let (status, body) = bulk(&app, "/t/_bulk", ndjson).await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(body["errors"], json!(true), "{body}");

    let (_, count) = get(&app, "/t/_count").await;
    assert_eq!(count["count"], json!(2), "only the two valid docs: {count}");

    // Both survivors were coerced, so both are numerically queryable.
    let one = search(&app, "t", json!({ "term": { "i": 1 } })).await;
    assert_eq!(hit_count(&one), 1, "{one}");
    let six = search(&app, "t", json!({ "term": { "i": 6 } })).await;
    assert_eq!(hit_count(&six), 1, "{six}");
}

/// An index with no numeric or boolean field skips the check entirely — the
/// gate that keeps the turbo path free must not change behaviour for it.
#[tokio::test]
async fn an_index_with_no_numeric_mapping_is_untouched() {
    let (app, _dir) = app().await;
    let (status, _) = json_req(
        &app,
        "PUT",
        "/plain",
        json!({ "mappings": { "properties": { "msg": { "type": "text" } } } }),
    )
    .await;
    assert_eq!(status, StatusCode::OK);

    let (status, _) = put_doc(&app, "plain", "1", json!({ "msg": "hi", "n": "abc" })).await;
    assert_eq!(status, StatusCode::CREATED);
    let (_, doc) = get(&app, "/plain/_doc/1").await;
    assert_eq!(doc["_source"]["n"], json!("abc"), "unmapped stays verbatim");
}

// ─────────────────────────────────────────────────────────────────────────────
// The query side of the same coercion. Rewriting `_source` moves the STORED
// spelling, so a query operand written the pre-coercion way has to keep
// matching — this is the case CI caught in
// `tests/es-compat-yaml/yaml/search/390_doc_values_search.yml`, and the reason
// the first cut of this change regressed conformance from 0 failed to 1.
// ─────────────────────────────────────────────────────────────────────────────

/// A document written `{"b": "true"}` is now STORED as `{"b": true}`. ES accepts
/// either spelling in a `term`/`terms` operand against a `boolean` field
/// (`terms {b: ["true"]}` is literally what the ES YAML suite asserts), so both
/// must still find it. Pre-fix, `terms` with the string operand found nothing:
/// `terms` verifies each admitted doc with exact JSON equality, and `true` is
/// not `"true"`.
#[tokio::test]
async fn a_query_in_the_pre_coercion_spelling_still_matches_the_coerced_document() {
    let (app, _dir) = typed_index("t").await;

    let (status, _) = put_doc(&app, "t", "1", json!({ "b": "true", "i": "5" })).await;
    assert_eq!(status, StatusCode::CREATED);
    let (_, doc) = get(&app, "/t/_doc/1").await;
    assert_eq!(
        doc["_source"]["b"],
        json!(true),
        "ingest coerced the spelling"
    );
    assert_eq!(doc["_source"]["i"], json!(5));
    refresh(&app, "t").await;

    for query in [
        json!({ "terms": { "b": ["true"] } }),
        json!({ "terms": { "b": [true] } }),
        json!({ "term": { "b": "true" } }),
        json!({ "term": { "b": true } }),
        json!({ "terms": { "b": ["false", "true"] } }),
        json!({ "terms": { "i": ["5"] } }),
        json!({ "terms": { "i": [5] } }),
    ] {
        let body = search(&app, "t", query.clone()).await;
        assert_eq!(
            hit_count(&body),
            1,
            "both spellings of {query} must find the coerced document: {body}"
        );
    }

    // Tolerance, not blindness: the other boolean still must not match.
    for query in [
        json!({ "terms": { "b": ["false"] } }),
        json!({ "term": { "b": false } }),
        json!({ "terms": { "b": ["yes"] } }),
        json!({ "terms": { "i": ["6"] } }),
    ] {
        let body = search(&app, "t", query.clone()).await;
        assert_eq!(hit_count(&body), 0, "{query} must not match: {body}");
    }
}

/// An index that spans the upgrade holds BOTH representations of the same
/// logical value: documents written before this change keep `"true"` / `"5"`,
/// documents written after hold `true` / `5`. One query must not silently see
/// half the index. `_update` is the shortest way to plant the old spelling —
/// it merges into a document that was already validated on write and is
/// deliberately not re-validated, which is exactly the shape a pre-upgrade
/// document has.
#[tokio::test]
async fn an_index_holding_both_spellings_answers_every_query_with_both_docs() {
    let (app, _dir) = typed_index("t").await;

    // Post-upgrade document: coerced on the way in.
    let (status, _) = put_doc(&app, "t", "new", json!({ "b": "true", "i": "5" })).await;
    assert_eq!(status, StatusCode::CREATED);

    // Pre-upgrade document: the raw spelling, planted past the check.
    let (status, _) = put_doc(&app, "t", "legacy", json!({ "k": "a" })).await;
    assert_eq!(status, StatusCode::CREATED);
    let (status, body) = json_req(
        &app,
        "POST",
        "/t/_update/legacy",
        json!({ "doc": { "b": "true", "i": "5" } }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "update should apply: {body}");

    refresh(&app, "t").await;

    let (_, legacy) = get(&app, "/t/_doc/legacy").await;
    let (_, fresh) = get(&app, "/t/_doc/new").await;
    assert_eq!(
        legacy["_source"]["b"],
        json!("true"),
        "the legacy spelling is what makes this test meaningful"
    );
    assert_eq!(fresh["_source"]["b"], json!(true));

    for query in [
        json!({ "terms": { "b": ["true"] } }),
        json!({ "terms": { "b": [true] } }),
        json!({ "term": { "b": "true" } }),
        json!({ "term": { "b": true } }),
        json!({ "terms": { "i": ["5"] } }),
        json!({ "terms": { "i": [5] } }),
        json!({ "term": { "i": 5 } }),
    ] {
        let body = search(&app, "t", query.clone()).await;
        assert_eq!(
            hit_count(&body),
            2,
            "{query} must see both spellings in one index: {body}"
        );
    }
}

//! `POST /_aliases` must persist the alias metadata it is given.
//!
//! `AliasActionParams` used to carry only `index` and `alias`, so serde
//! silently discarded `filter` (and routing / is_write_index). The requested
//! alias was created, `acknowledged: true` came back, and every read through it
//! exposed the whole backing index — a filtered alias is the standard
//! poor-man's document boundary, so that is a data leak, not a cosmetic one.
//!
//! The standard action API now stores the same metadata `PUT
//! /{index}/_alias/{name}` does, persists it, and removes it on `remove` (or
//! when an alias is re-added without a filter) so a stale filter cannot
//! outlive its definition.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is
//! reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

fn config_for(dir: &std::path::Path) -> xerj_common::config::Config {
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config
}

fn app_over(dir: &std::path::Path) -> axum::Router {
    let config = config_for(dir);
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    xerj_api::router::build_es_compat_router(state)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let body = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, body)
}

fn json_req(method: &str, path: &str, body: Value) -> Request<Body> {
    Request::builder()
        .method(method)
        .uri(path)
        .header("content-type", "application/json")
        .body(Body::from(body.to_string()))
        .expect("request")
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn post(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    send(app, json_req("POST", path, body)).await
}

async fn put(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    send(app, json_req("PUT", path, body)).await
}

async fn seed(app: &axum::Router) {
    let (status, body) = put(
        app,
        "/di",
        json!({"mappings": {"properties": {"k": {"type": "keyword"}}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    for (id, k) in [("1", "a"), ("2", "a"), ("3", "b")] {
        let (status, body) = put(app, &format!("/di/_doc/{id}"), json!({"k": k})).await;
        assert!(status.is_success(), "{body}");
    }
    let (status, body) = post(app, "/di/_refresh", Value::Null).await;
    assert_eq!(status, StatusCode::OK, "{body}");
}

async fn search_total(app: &axum::Router, index: &str, body: Value) -> u64 {
    let (status, resp) = post(app, &format!("/{index}/_search"), body).await;
    assert_eq!(status, StatusCode::OK, "{resp}");
    resp["hits"]["total"]["value"].as_u64().unwrap_or(0)
}

async fn count(app: &axum::Router, index: &str, body: Value) -> u64 {
    let (status, resp) = post(app, &format!("/{index}/_count"), body).await;
    assert_eq!(status, StatusCode::OK, "{resp}");
    resp["count"].as_u64().unwrap_or(0)
}

async fn add_filtered_alias(app: &axum::Router) {
    let (status, body) = post(
        app,
        "/_aliases",
        json!({"actions": [{"add": {
            "index": "di",
            "alias": "da",
            "filter": {"term": {"k": "a"}},
        }}]}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["acknowledged"], true, "{body}");
}

#[tokio::test]
async fn post_aliases_filter_is_stored_and_enforced() {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    seed(&app).await;
    add_filtered_alias(&app).await;

    // The definition itself: metadata came back rather than `-`.
    let (status, body) = get(&app, "/_alias/da").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(
        body.pointer("/di/aliases/da/filter"),
        Some(&json!({"term": {"k": "a"}})),
        "the filter must be part of the alias definition: {body}"
    );
    let (status, body) = get(&app, "/_cat/aliases?format=json&h=alias,index,filter").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert!(
        !body[0]["filter"].as_str().unwrap_or_default().contains('-'),
        "cat/aliases must render the filter, not `-`: {body}"
    );

    // Every read path that resolves an alias must honour the slice.
    assert_eq!(
        search_total(&app, "da", json!({"size": 0, "query": {"match_all": {}}})).await,
        2,
        "the alias exposes only k=a"
    );
    assert_eq!(
        count(&app, "da", json!({"query": {"match_all": {}}})).await,
        2
    );
    assert_eq!(
        search_total(
            &app,
            "da",
            json!({"size": 0, "query": {"term": {"k": "b"}}})
        )
        .await,
        0,
        "a document outside the filter must not be reachable through the alias"
    );

    // The msearch alias path shares the same metadata.
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/_msearch")
                .header("content-type", "application/x-ndjson")
                .body(Body::from(
                    "{\"index\":\"da\"}\n{\"size\":0,\"query\":{\"match_all\":{}}}\n".to_string(),
                ))
                .expect("request"),
        )
        .await
        .expect("response");
    let body: Value = serde_json::from_slice(
        &axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap(),
    )
    .unwrap();
    assert_eq!(body["responses"][0]["hits"]["total"]["value"], 2, "{body}");
}

#[tokio::test]
async fn post_aliases_filter_survives_restart_and_is_removed_with_the_alias() {
    let dir = tempfile::tempdir().expect("tempdir");
    {
        let app = app_over(dir.path());
        seed(&app).await;
        add_filtered_alias(&app).await;
        assert_eq!(
            search_total(&app, "da", json!({"size": 0, "query": {"match_all": {}}})).await,
            2
        );
    }

    // Fresh engine, same data dir: only what reached disk is visible.
    let app = app_over(dir.path());
    let (status, body) = get(&app, "/_alias/da").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(
        body.pointer("/di/aliases/da/filter"),
        Some(&json!({"term": {"k": "a"}})),
        "the POST /_aliases filter must be persisted: {body}"
    );
    assert_eq!(
        search_total(&app, "da", json!({"size": 0, "query": {"match_all": {}}})).await,
        2,
        "the persisted filter must still be enforced"
    );

    // Remove the alias: its metadata must go with it, so re-adding the alias
    // without a filter exposes the whole index instead of a stale slice.
    let (status, body) = post(
        &app,
        "/_aliases",
        json!({"actions": [{"remove": {"index": "di", "alias": "da"}}]}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    let (status, body) = get(&app, "/_alias/da").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert!(
        body.get("di").is_none(),
        "the removed alias must be gone: {body}"
    );
    let (status, body) = post(
        &app,
        "/_aliases",
        json!({"actions": [{"add": {"index": "di", "alias": "da"}}]}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(
        search_total(&app, "da", json!({"size": 0, "query": {"match_all": {}}})).await,
        3,
        "a re-added alias without a filter is not filtered"
    );
}

#[tokio::test]
async fn re_putting_an_alias_without_a_body_clears_its_filter() {
    let dir = tempfile::tempdir().expect("tempdir");
    let app = app_over(dir.path());
    seed(&app).await;
    let (status, body) = put(
        &app,
        "/di/_alias/da",
        json!({"filter": {"term": {"k": "a"}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(
        search_total(&app, "da", json!({"size": 0, "query": {"match_all": {}}})).await,
        2
    );
    let (status, body) = put(&app, "/di/_alias/da", json!({})).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(
        search_total(&app, "da", json!({"size": 0, "query": {"match_all": {}}})).await,
        3,
        "an empty re-put replaces the alias definition, filter included"
    );
}

//! Issue #2306: a semantic autoindex run whose embedder is `--embed-mode proxy`
//! must resume after a mid-run failure. Documents already embedded are not
//! sent to the proxy again when the backend, model, endpoint, and vector
//! width are unchanged.
//!
//! The mock answers OpenAI `/v1/embeddings` with 384-wide vectors (the width
//! `semantic_text` uses when the mapping omits `dimensions`). The identity
//! probe always succeeds. The first document embed succeeds and is indexed;
//! every later document embed is refused with HTTP 400 until the rerun turns
//! the refusal off. 400 is permanent, so the interrupted run fails without
//! retry backoff. Which file is first does not matter.

use std::path::Path;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_autoindex::cli::IndexCfg;

const DIMS: usize = 384;
const ALPHA: &str = "ALPHA_DOC_ONE";
const BETA: &str = "BETA_DOC_TWO";
/// Same text `confirm_proxy_embedding_width` sends. Kept here so the interrupt
/// does not treat the identity probe as a document.
const PROBE: &str = "xerj-proxy-identity-probe";

fn prose(marker: &str) -> String {
    format!(
        "{marker} The quarterly revenue report describes how the operating team closed the books \
         after a long review of customer contracts and deferred revenue. The narrative is ordinary \
         prose so the indexer treats the file as a document and embeds the body once, instead of \
         splitting it into line windows."
    )
}

struct EmbedLog {
    texts: Mutex<Vec<String>>,
    /// Document embed requests that may still succeed while `reject` is set.
    allow_document_requests: AtomicUsize,
    reject: AtomicBool,
}

async fn mock_embedder() -> (String, Arc<EmbedLog>) {
    let log = Arc::new(EmbedLog {
        texts: Mutex::new(Vec::new()),
        allow_document_requests: AtomicUsize::new(1),
        reject: AtomicBool::new(true),
    });
    let shared = Arc::clone(&log);
    let app = axum::Router::new().route(
        "/v1/embeddings",
        axum::routing::post(move |axum::Json(body): axum::Json<Value>| {
            let shared = Arc::clone(&shared);
            async move {
                let inputs: Vec<String> = match body.get("input") {
                    Some(Value::Array(items)) => items
                        .iter()
                        .filter_map(|item| item.as_str().map(str::to_owned))
                        .collect(),
                    Some(Value::String(text)) => vec![text.clone()],
                    _ => Vec::new(),
                };
                shared.texts.lock().unwrap().extend(inputs.iter().cloned());
                let document = inputs.iter().any(|text| !text.contains(PROBE));
                let allowed = !document
                    || !shared.reject.load(Ordering::SeqCst)
                    || shared
                        .allow_document_requests
                        .fetch_update(Ordering::SeqCst, Ordering::SeqCst, |left| {
                            left.checked_sub(1)
                        })
                        .is_ok();
                if !allowed {
                    return (
                        StatusCode::BAD_REQUEST,
                        axum::Json(json!({"error": "interrupted"})),
                    );
                }
                let data: Vec<Value> = inputs
                    .iter()
                    .enumerate()
                    .map(|(index, _)| {
                        let mut embedding = vec![0.0_f64; DIMS];
                        embedding[0] = 1.0;
                        json!({"index": index, "embedding": embedding})
                    })
                    .collect();
                (StatusCode::OK, axum::Json(json!({"data": data})))
            }
        }),
    );
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind mock embedder");
    let addr = listener.local_addr().expect("mock embedder addr");
    tokio::spawn(async move {
        let _ = axum::serve(listener, app).await;
    });
    (format!("http://{addr}/v1/embeddings"), log)
}

async fn proxy_node(endpoint: String) -> (axum::Router, String) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.auth.enabled = false;
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.embedding.mode = "proxy".into();
    config.embedding.default_endpoint = endpoint;
    config.embedding.default_model = "mock-embed".into();
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    std::mem::forget(dir);
    let app = xerj_api::router::build_es_compat_router(state);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind xerj");
    let addr = listener.local_addr().expect("xerj addr");
    let served = app.clone();
    tokio::spawn(async move {
        let _ = axum::serve(listener, served).await;
    });
    (app, format!("http://{addr}"))
}

async fn call(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    let body = if body.is_null() {
        Body::empty()
    } else {
        req = req.header("content-type", "application/json");
        Body::from(body.to_string())
    };
    let response = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(Value::Null),
    )
}

fn index_cfg(root: &Path, state_dir: &Path, url: &str, prefix: &str, no_graph: bool) -> IndexCfg {
    IndexCfg {
        root: root.to_owned(),
        endpoint_url: None,
        stub_globs: Vec::new(),
        url: url.to_owned(),
        api_key: None,
        api_key_file: None,
        workers: 1,
        scan_workers: 1,
        pdf_workers: 1,
        resource_notes: Vec::new(),
        xerj_url_note: None,
        pdf_timeout_secs: 30,
        bulk_mb: 1,
        bulk_timeout_secs: 30,
        snapshot_max_bytes: 64 << 30,
        prefix: prefix.to_owned(),
        replace_prefix: false,
        prefix_note: None,
        state_dir: Some(state_dir.to_owned()),
        fresh: false,
        follow_symlinks: false,
        follow_symlinks_outside_root: false,
        ignore: xerj_autoindex::ignore_rules::IgnoreOptions::default(),
        max_file_bytes: 1 << 30,
        sample: 50,
        no_semantic: false,
        code_analyzer: Default::default(),
        brain: Some(format!("brain-{prefix}")),
        no_graph,
        max_minutes: 0,
        approve: None,
        max_index_bytes: None,
        budget_plan: None,
        drop_indexed: false,
        dry_run: false,
        walk_only: false,
        json: false,
        quiet: true,
        progress: xerj_autoindex::progress::ProgressMode::None,
        progress_interval: None,
        watch: false,
        label: None,
        debounce: Duration::from_millis(0),
        exclude_rels: Vec::new(),
        skip_corpus_data: false,
    }
}

fn run_autoindex(
    root: &Path,
    state_dir: &Path,
    url: &str,
    prefix: &str,
    no_graph: bool,
) -> Result<i32, String> {
    let cfg = index_cfg(root, state_dir, url, prefix, no_graph);
    match xerj_autoindex::run_index_report(cfg) {
        Ok((code, _)) => Ok(code),
        Err(error) => Err(format!("{error:#}")),
    }
}

async fn run_autoindex_blocking(
    root: &Path,
    state_dir: &Path,
    url: &str,
    prefix: &str,
    no_graph: bool,
) -> Result<i32, String> {
    let root = root.to_owned();
    let state_dir = state_dir.to_owned();
    let url = url.to_owned();
    let prefix = prefix.to_owned();
    tokio::task::spawn_blocking(move || run_autoindex(&root, &state_dir, &url, &prefix, no_graph))
        .await
        .expect("autoindex task")
}

fn texts_containing(log: &[String], marker: &str) -> usize {
    log.iter().filter(|text| text.contains(marker)).count()
}

async fn indexed_markers(app: &axum::Router, prefix: &str) -> (bool, bool) {
    let (refresh_status, refresh_body) =
        call(app, "POST", &format!("/{prefix}-*/_refresh"), Value::Null).await;
    assert!(
        refresh_status.is_success(),
        "refresh {prefix}: {refresh_status} {refresh_body}"
    );
    let (status, body) = call(
        app,
        "POST",
        &format!("/{prefix}-*/_search"),
        json!({"size": 50, "query": {"match_all": {}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "search {prefix}: {body}");
    let rendered = body.to_string();
    (rendered.contains(ALPHA), rendered.contains(BETA))
}

async fn interrupt_then_resume(no_graph: bool) {
    let (endpoint, log) = mock_embedder().await;
    let (app, url) = proxy_node(endpoint).await;
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    std::fs::write(corpus.path().join("a-alpha.txt"), prose(ALPHA)).unwrap();
    std::fs::write(corpus.path().join("b-beta.txt"), prose(BETA)).unwrap();
    let prefix = if no_graph { "pxresumeng" } else { "pxresume" };

    let interrupted = run_autoindex_blocking(corpus.path(), state.path(), &url, prefix, no_graph)
        .await
        .expect_err("the refused document must stop the run");
    assert!(
        interrupted.contains("embedding") || interrupted.contains("bulk"),
        "the failure must name the embedding problem: {interrupted}"
    );

    let during = log.texts.lock().unwrap().clone();
    assert!(
        texts_containing(&during, ALPHA) >= 1 && texts_containing(&during, BETA) >= 1,
        "the run must embed one document and reach the next before it stops: {during:?}"
    );
    let (alpha_indexed, beta_indexed) = indexed_markers(&app, prefix).await;
    assert!(
        alpha_indexed != beta_indexed,
        "exactly one document is indexed before the refusal \
         (alpha={alpha_indexed} beta={beta_indexed})"
    );
    let already = if alpha_indexed { ALPHA } else { BETA };
    let pending = if alpha_indexed { BETA } else { ALPHA };

    let cutoff = during.len();
    log.reject.store(false, Ordering::SeqCst);
    let code = run_autoindex_blocking(corpus.path(), state.path(), &url, prefix, no_graph)
        .await
        .unwrap_or_else(|error| panic!("resume failed: {error}"));
    assert_eq!(code, 0, "resume must finish");

    let resumed = log.texts.lock().unwrap().clone();
    let again = &resumed[cutoff..];
    assert_eq!(
        texts_containing(again, already),
        0,
        "already-indexed documents must not be re-embedded: {again:?}"
    );
    assert!(
        texts_containing(again, pending) >= 1,
        "the document that failed must be embedded on the rerun: {again:?}"
    );
    let (alpha_indexed, beta_indexed) = indexed_markers(&app, prefix).await;
    assert!(
        alpha_indexed && beta_indexed,
        "both documents are searchable after resume (alpha={alpha_indexed} beta={beta_indexed})"
    );
}

#[tokio::test]
async fn proxy_semantic_autoindex_resumes_without_reembedding() {
    interrupt_then_resume(false).await;
}

#[tokio::test]
async fn proxy_semantic_autoindex_resumes_without_reembedding_no_graph() {
    interrupt_then_resume(true).await;
}

//! A `dense_vector` mapping's `quantization` value, from the outside — issue
//! #275, another instance of the accepted-and-ignored class tracked in #204.
//!
//! Before the fix, `es_properties_to_fields` ended its `quantization` match on
//! `_ => {}`. `"scalar4"`, `"binary"`, `"int4"` and typos such as `"sq8"` were
//! taken with a `200 acknowledged`, echoed back verbatim by
//! `GET /{index}/_mapping`, and then ignored — the field stored full-precision
//! f32 while the mapping the operator read back to confirm it said otherwise.
//! Only `Some("scalar8")` is ever read by the serving path
//! (`xerj-engine/src/index.rs:10440`, `:10847`), so every other value was
//! inert — a kNN over such a field scored bit-identically to a field carrying
//! no `quantization` key at all.
//!
//! `Config::validate` has refused an unimplemented `[vector]
//! default_quantization` since #207. These tests pin the same guard on the
//! per-field mapping key, in all three of its branches:
//!
//!  * **honoured** — `scalar8` / `int8` / `index_options.type: int8_hnsw`
//!    accepted AND observably quantized; `none` accepted and observably not;
//!  * **refused-unimplemented** — `binary`, `scalar4`, `int4`: named schemes
//!    with no reachable quantizer behind them;
//!  * **refused-unknown** — anything else, including case variants and
//!    non-strings.
//!
//! The tests live at the crate boundary rather than beside the function on
//! purpose: #207's sibling defect survived a fix placed next to one handler,
//! so both entry points that build a schema (`PUT /{index}` and
//! `PUT /{index}/_mapping`) are exercised over real HTTP here.
//!
//! Elasticsearch is referenced for wire semantics only. It is AGPL-3.0/
//! SSPL-1.0/Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method(method)
            .uri(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

/// `PUT /{index}` with a single `dense_vector` field carrying `field_def`.
async fn create_vector_index(
    app: &axum::Router,
    index: &str,
    field_def: Value,
) -> (StatusCode, Value) {
    json_req(
        app,
        "PUT",
        &format!("/{index}"),
        json!({ "mappings": { "properties": { "v": field_def } } }),
    )
    .await
}

/// Index a small corpus and return the kNN scores, in hit order.
///
/// The scores are the observable: a `scalar8` field is scored by decoding its
/// u8 codes, so its scores move off the exact-f32 values. A field that only
/// *claims* quantization scores bit-identically to one that claims nothing.
async fn knn_scores(app: &axum::Router, index: &str) -> Vec<f64> {
    for i in 1..=5u32 {
        let (status, body) = json_req(
            app,
            "POST",
            &format!("/{index}/_doc/{i}"),
            json!({ "v": [0.1 * i as f64, 0.2, 0.3, 0.4] }),
        )
        .await;
        assert!(status.is_success(), "index doc {i}: {status} {body}");
    }
    let (status, _) = json_req(app, "POST", &format!("/{index}/_refresh"), json!({})).await;
    assert!(status.is_success(), "refresh: {status}");

    let (status, body) = json_req(
        app,
        "POST",
        &format!("/{index}/_search"),
        json!({
            "knn": {
                "field": "v",
                "query_vector": [0.15, 0.25, 0.3, 0.4],
                "k": 5,
                "num_candidates": 50
            },
            "_source": false
        }),
    )
    .await;
    assert!(status.is_success(), "knn on {index}: {status} {body}");
    let hits = body["hits"]["hits"]
        .as_array()
        .unwrap_or_else(|| panic!("no hits on {index}: {body}"));
    assert_eq!(hits.len(), 5, "expected the whole corpus back: {body}");
    hits.iter()
        .map(|h| h["_score"].as_f64().expect("score"))
        .collect()
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. accepted-and-honoured
// ─────────────────────────────────────────────────────────────────────────────

/// `scalar8` is the one value with a quantizer the serving path actually
/// reads, so it must be accepted — and accepted has to mean *honoured*, which
/// is what the score comparison establishes. `int8` is its ES-flavoured alias
/// and `index_options.type: int8_hnsw` is how an ES mapping asks for the same
/// thing; all three must land on the same behaviour.
#[tokio::test]
async fn scalar8_is_accepted_and_observably_quantizes() {
    let (app, _dir) = app().await;

    for (index, field_def) in [
        (
            "exact",
            json!({ "type": "dense_vector", "dims": 4, "quantization": "none" }),
        ),
        ("unset", json!({ "type": "dense_vector", "dims": 4 })),
        (
            "sq8",
            json!({ "type": "dense_vector", "dims": 4, "quantization": "scalar8" }),
        ),
        (
            "sq8-alias",
            json!({ "type": "dense_vector", "dims": 4, "quantization": "int8" }),
        ),
        (
            "sq8-es",
            json!({
                "type": "dense_vector",
                "dims": 4,
                "index_options": { "type": "int8_hnsw" }
            }),
        ),
    ] {
        let (status, body) = create_vector_index(&app, index, field_def).await;
        assert_eq!(status, StatusCode::OK, "create {index}: {body}");
    }

    let exact = knn_scores(&app, "exact").await;
    let unset = knn_scores(&app, "unset").await;
    let sq8 = knn_scores(&app, "sq8").await;
    let alias = knn_scores(&app, "sq8-alias").await;
    let es = knn_scores(&app, "sq8-es").await;

    // `none` is not a synonym for "some quantization": it must be bit-equal to
    // the field that declared nothing at all.
    assert_eq!(
        exact, unset,
        "quantization: none must score identically to an unquantized field"
    );

    // The honoured branch: SQ8 decode moves the scores off exact f32. If this
    // ever comes back equal, `scalar8` has silently stopped being honoured and
    // #275 is back in a new form.
    assert_ne!(
        sq8, exact,
        "quantization: scalar8 must change the scores — equal scores mean the \
         SQ8 code store was never consulted"
    );
    assert_eq!(alias, sq8, "int8 is an alias for scalar8");
    assert_eq!(
        es, sq8,
        "index_options.type: int8_hnsw must reach the same quantizer"
    );

    // The values are close, not arbitrary — a wrong quantizer would not land
    // within a percent of the exact scores. (Recall/RAM effects are not
    // claimed here; nothing in this test measures them.)
    for (q, e) in sq8.iter().zip(exact.iter()) {
        assert!(
            (q - e).abs() < 0.01,
            "SQ8 score {q} is not a plausible approximation of exact {e}"
        );
    }

    // And the mapping still round-trips the value it honoured.
    let (status, body) = get(&app, "/sq8/_mapping").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(
        body["sq8"]["mappings"]["properties"]["v"]["quantization"],
        json!("scalar8"),
        "{body}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. refused-unimplemented
// ─────────────────────────────────────────────────────────────────────────────

/// `binary` has no `BinaryQuantizer` at all; `scalar4`/`int4` have a
/// `Scalar4Quantizer` in xerj-vector that nothing in the serving path reaches.
/// Either way the operator would get f32 while sizing a cluster on a 4×–32×
/// reduction, which is precisely what `Config::validate` refuses at startup for
/// `default_quantization = "binary"`. Refuse it here too, and say why.
#[tokio::test]
async fn unimplemented_quantization_is_refused_with_a_reason() {
    let (app, _dir) = app().await;

    for (i, q) in ["binary", "scalar4", "int4"].iter().enumerate() {
        let index = format!("bad{i}");
        let (status, body) = create_vector_index(
            &app,
            &index,
            json!({ "type": "dense_vector", "dims": 4, "quantization": q }),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::BAD_REQUEST,
            "quantization {q} must be refused, got {status}: {body}"
        );
        let reason = body.to_string();
        assert!(
            reason.contains("not implemented"),
            "the error must say the scheme is unimplemented, got: {reason}"
        );
        assert!(
            reason.contains(q) && reason.contains("scalar8"),
            "the error must name the rejected value and the accepted set, got: {reason}"
        );

        // Refused means not created — no index left behind to be discovered
        // later with a mapping that lies. (`GET /{index}/_mapping` is
        // wildcard-lenient and answers `200 {}` for a missing index, so the
        // existence question is asked of `GET /{index}`, which 404s.)
        let (status, body) = get(&app, &format!("/{index}")).await;
        assert_eq!(
            status,
            StatusCode::NOT_FOUND,
            "a refused mapping must not create the index: {body}"
        );
        let (_, body) = get(&app, &format!("/{index}/_mapping")).await;
        assert!(
            body.get(&index).is_none(),
            "a refused value must never be echoed back: {body}"
        );
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. refused-unknown
// ─────────────────────────────────────────────────────────────────────────────

/// A typo is the common case and the worst one: `"sq8"` looks like it worked.
/// Reject anything outside the implemented set, including case variants (the
/// key is not case-insensitive anywhere else) and non-string values.
#[tokio::test]
async fn unknown_quantization_is_refused_and_never_echoed() {
    let (app, _dir) = app().await;

    for (i, q) in ["sq8", "SCALAR8", "Scalar8", "int_8", "", "pq", "true"]
        .iter()
        .enumerate()
    {
        let index = format!("typo{i}");
        let (status, body) = create_vector_index(
            &app,
            &index,
            json!({ "type": "dense_vector", "dims": 4, "quantization": q }),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::BAD_REQUEST,
            "quantization {q:?} must be refused, got {status}: {body}"
        );
        assert!(
            body.to_string().contains("scalar8"),
            "the error must name what this build does implement, got: {body}"
        );
        let (status, _) = get(&app, &format!("/{index}")).await;
        assert_eq!(
            status,
            StatusCode::NOT_FOUND,
            "{q:?} must not create {index}"
        );
        let (_, body) = get(&app, &format!("/{index}/_mapping")).await;
        assert!(
            body.get(&index).is_none(),
            "a refused value must never be echoed back: {body}"
        );
    }

    // A non-string is a different mistake with the same consequence.
    let (status, body) = create_vector_index(
        &app,
        "nonstring",
        json!({ "type": "dense_vector", "dims": 4, "quantization": 8 }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "a non-string quantization must be refused, got {status}: {body}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. the guard is structural, not per-handler
// ─────────────────────────────────────────────────────────────────────────────

/// `PUT /{index}/_mapping` is the second way a schema gets built, and #207's
/// sibling defect survived a fix that only covered the first. Adding a bad
/// vector field to an existing index must be refused there too — and refused
/// in the plan phase, so nothing about the request is published.
#[tokio::test]
async fn put_mapping_refuses_the_same_values() {
    let (app, _dir) = app().await;
    let (status, body) = json_req(&app, "PUT", "/later", json!({})).await;
    assert_eq!(status, StatusCode::OK, "{body}");

    let (status, body) = json_req(
        &app,
        "PUT",
        "/later/_mapping",
        json!({ "properties": { "v": {
            "type": "dense_vector", "dims": 4, "quantization": "binary"
        }}}),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "PUT _mapping must refuse it too: {body}"
    );

    // Nothing was published: the field is absent, not present-and-lying.
    let (status, body) = get(&app, "/later/_mapping").await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert!(
        body["later"]["mappings"]["properties"]["v"].is_null(),
        "a refused PUT _mapping must not leave the field behind: {body}"
    );

    // The good value still lands on the same endpoint.
    let (status, body) = json_req(
        &app,
        "PUT",
        "/later/_mapping",
        json!({ "properties": { "v": {
            "type": "dense_vector", "dims": 4, "quantization": "scalar8"
        }}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
}

/// A `dense_vector` nested under an object, and one declared as a multi-field,
/// go through the same recursive parse. The guard must reach them: a mapping
/// that hides the bad value one level down is the obvious way a same-file fix
/// gets bypassed.
#[tokio::test]
async fn nested_and_multi_field_vectors_are_checked_too() {
    let (app, _dir) = app().await;

    let (status, body) = json_req(
        &app,
        "PUT",
        "/nested",
        json!({ "mappings": { "properties": { "doc": {
            "type": "object",
            "properties": { "v": {
                "type": "dense_vector", "dims": 4, "quantization": "scalar4"
            }}
        }}}}),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "a nested dense_vector must be checked: {body}"
    );
    assert!(body.to_string().contains("scalar4"), "{body}");

    // A multi-field `dense_vector` never reaches the schema builder at all —
    // `es_properties_to_fields` recurses into `properties` but not `fields` —
    // so before #275 it was the one shape that could be accepted, echoed back
    // by `GET /_mapping`, and dropped entirely. The validation walk does
    // recurse into `fields`, which is why the guard is wired there too.
    let (status, body) = json_req(
        &app,
        "PUT",
        "/multifield",
        json!({ "mappings": { "properties": { "t": {
            "type": "keyword",
            "fields": { "v": {
                "type": "dense_vector", "dims": 4, "quantization": "binary"
            }}
        }}}}),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::BAD_REQUEST,
        "a multi-field dense_vector must be checked: {body}"
    );
    assert!(body.to_string().contains("binary"), "{body}");

    // And the good value still creates in both shapes.
    for (index, mapping) in [
        (
            "nested-ok",
            json!({ "mappings": { "properties": { "doc": {
                "type": "object",
                "properties": { "v": {
                    "type": "dense_vector", "dims": 4, "quantization": "scalar8"
                }}
            }}}}),
        ),
        (
            "multifield-ok",
            json!({ "mappings": { "properties": { "t": {
                "type": "keyword",
                "fields": { "v": {
                    "type": "dense_vector", "dims": 4, "quantization": "scalar8"
                }}
            }}}}),
        ),
    ] {
        let (status, body) = json_req(&app, "PUT", &format!("/{index}"), mapping).await;
        assert_eq!(status, StatusCode::OK, "create {index}: {body}");
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. ES wire compatibility is NOT tightened
// ─────────────────────────────────────────────────────────────────────────────

/// The strictness belongs on XERJ's own `quantization` key only. ES's
/// `index_options.type` must stay permissive: `hnsw`, `flat`, `bbq_*` and
/// `int4_*` are real Elasticsearch mappings, and a migrating user's index
/// definition has to keep creating. Those families are served by the exact f32
/// scan, which satisfies the contract ES states for them (a nearest-neighbour
/// result set) at recall 1.00 — a substitution that costs memory, not answers,
/// unlike a quantization that was asked for and skipped.
#[tokio::test]
async fn es_index_options_families_still_create() {
    let (app, _dir) = app().await;

    for (i, io) in [
        "hnsw",
        "flat",
        "int8_hnsw",
        "int8_flat",
        "int4_hnsw",
        "int4_flat",
        "bbq_hnsw",
        "bbq_flat",
    ]
    .iter()
    .enumerate()
    {
        let (status, body) = create_vector_index(
            &app,
            &format!("es{i}"),
            json!({
                "type": "dense_vector",
                "dims": 4,
                "index_options": { "type": io, "m": 16, "ef_construction": 100 }
            }),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::OK,
            "ES index_options.type {io} must still create an index: {body}"
        );
    }
}

//! The root README quickstart must keep the node data directory outside any
//! folder an agent will autoindex. `landing/llms.txt` already says why:
//! `data/` is not in the built-in ignore list, so `--data-dir ./data` inside
//! that tree makes the node index its own storage. The root READMEs are the
//! page an agent copies first, and they used to show `./data`.

use std::path::PathBuf;

fn readme(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join(name);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

#[test]
fn quickstart_puts_the_data_dir_outside_the_indexed_tree() {
    for name in [
        "README.md",
        "README.zh-CN.md",
        "README.ja-JP.md",
        "README.es.md",
        "README.ar.md",
    ] {
        let text = readme(name);
        assert!(
            text.contains("xerj --insecure --data-dir ~/xerj-data &"),
            "{name} quickstart must start the node at ~/xerj-data"
        );
        assert!(
            text.contains("~/xerj-data/admin.key"),
            "{name} must read the admin key from the same directory"
        );
        assert!(
            !text.contains("xerj --insecure --data-dir ./data")
                && !text.contains("xerj --data-dir ./data"),
            "{name} still starts a node inside ./data"
        );
    }
    let en = readme("README.md");
    assert!(
        en.contains("outside any folder you will autoindex"),
        "the English README must say why ./data is the wrong place"
    );
}

//! A refresh is a synchronous visibility barrier: its HTTP response must not
//! claim success when the engine could not publish the requested segment.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

async fn request(app: &axum::Router, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::builder()
                .method(method)
                .uri(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("response body");
    let body = serde_json::from_slice(&bytes).expect("JSON response");
    (status, body)
}

fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("data dir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let app = xerj_api::router::build_es_compat_router(xerj_api::state::AppState::new(
        config, engine, metrics,
    ));
    (app, dir)
}

async fn create_text_index_with_document(app: &axum::Router, name: &str) {
    let (status, body) = request(
        app,
        "PUT",
        &format!("/{name}"),
        json!({"mappings": {"properties": {"body": {"type": "text"}}}}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "create {name}: {body}");

    let (status, body) = request(
        app,
        "PUT",
        &format!("/{name}/_doc/1"),
        json!({"body": "must remain searchable after a successful refresh"}),
    )
    .await;
    assert!(status.is_success(), "index document: {status} {body}");
}

fn block_segment_publication(dir: &std::path::Path, name: &str) {
    let segments = dir.join(name).join("segments");
    std::fs::remove_dir(&segments).expect("empty segments directory");
    std::fs::write(&segments, b"not a directory").expect("segments blocker");
}

#[tokio::test]
async fn refresh_reports_a_segment_publication_failure() {
    let (app, dir) = app();
    create_text_index_with_document(&app, "refresh-failure").await;

    // Make segment publication fail independently of any particular encoder:
    // replacing the still-empty segments directory with a regular file makes
    // the real storage/FTS finalizer return an I/O error. This is deterministic
    // even as individual side-car filename bugs are fixed.
    block_segment_publication(dir.path(), "refresh-failure");

    let (status, body) = request(&app, "POST", "/refresh-failure/_refresh", json!({})).await;
    assert_eq!(
        status,
        StatusCode::INTERNAL_SERVER_ERROR,
        "an all-shards refresh failure must not be HTTP 200: {body}"
    );
    assert_eq!(body.pointer("/_shards/total"), Some(&json!(1)), "{body}");
    assert_eq!(
        body.pointer("/_shards/successful"),
        Some(&json!(0)),
        "{body}"
    );
    assert_eq!(body.pointer("/_shards/failed"), Some(&json!(1)), "{body}");
    assert_eq!(
        body.pointer("/_shards/failures/0/index"),
        Some(&json!("refresh-failure")),
        "{body}"
    );
    assert_eq!(
        body.pointer("/_shards/failures/0/status"),
        Some(&json!("INTERNAL_SERVER_ERROR")),
        "{body}"
    );
    let failure = body
        .pointer("/_shards/failures/0")
        .and_then(Value::as_object)
        .expect("failure object");
    let mut failure_fields: Vec<&str> = failure.keys().map(String::as_str).collect();
    failure_fields.sort_unstable();
    assert_eq!(
        failure_fields,
        ["index", "reason", "shard", "status"],
        "ES 8.13.4 DefaultShardOperationFailedException shape: {body}"
    );
    assert_eq!(
        body.pointer("/_shards/failures/0/reason/type"),
        Some(&json!("store_exception")),
        "{body}"
    );
    let reason = body
        .pointer("/_shards/failures/0/reason/reason")
        .and_then(Value::as_str)
        .unwrap_or_default();
    assert!(
        !reason.is_empty() && reason != "refresh failed" && reason.contains("I/O error:"),
        "segment publication must preserve the real storage I/O reason: {body}"
    );
}

#[tokio::test]
async fn multi_index_refresh_attempts_every_index_after_a_failure() {
    let (app, dir) = app();
    create_text_index_with_document(&app, "refresh-good").await;
    create_text_index_with_document(&app, "refresh-bad").await;
    block_segment_publication(dir.path(), "refresh-bad");

    // The broken index is explicitly first: `successful == 1` proves the
    // handler did not abort before attempting the second resolved index.
    let (status, body) = request(
        &app,
        "POST",
        "/refresh-bad,refresh-good/_refresh",
        json!({}),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::INTERNAL_SERVER_ERROR,
        "ES 8.13.4 refresh uses the first failed shard's status: {body}"
    );
    assert_eq!(body.pointer("/_shards/total"), Some(&json!(2)), "{body}");
    assert_eq!(
        body.pointer("/_shards/successful"),
        Some(&json!(1)),
        "{body}"
    );
    assert_eq!(body.pointer("/_shards/failed"), Some(&json!(1)), "{body}");
    assert_eq!(
        body.pointer("/_shards/failures/0/index"),
        Some(&json!("refresh-bad")),
        "{body}"
    );
}

/// #2234 — an already-searchable index must refresh without the durability
/// tail. `Index::flush` (what `_refresh` used to call) always runs verified
/// WAL maintenance, which renames a new `snapshot.json` into place. Replacing
/// that file with a directory makes the rename fail. `_refresh` of an empty
/// memtable must still succeed; `_flush` must still report the failure.
#[tokio::test]
async fn refresh_does_not_wait_on_wal_maintenance() {
    let (app, dir) = app();
    create_text_index_with_document(&app, "refresh-ready").await;

    let (status, body) = request(&app, "POST", "/refresh-ready/_refresh", json!({})).await;
    assert!(
        status.is_success(),
        "the first refresh publishes the document: {status} {body}"
    );
    let (status, body) = request(&app, "GET", "/refresh-ready/_count", json!({})).await;
    assert!(status.is_success(), "{body}");
    assert_eq!(body.get("count"), Some(&json!(1)), "{body}");

    let snap = dir.path().join("refresh-ready").join("snapshot.json");
    assert!(
        snap.is_file(),
        "the publishing refresh should have written snapshot.json"
    );
    std::fs::remove_file(&snap).expect("remove snapshot");
    std::fs::create_dir(&snap).expect("wedge snapshot path");

    let (status, body) = request(&app, "POST", "/refresh-ready/_refresh", json!({})).await;
    assert!(
        status.is_success(),
        "_refresh must not run WAL maintenance: {status} {body}"
    );
    let (status, body) = request(&app, "POST", "/refresh-ready/_flush", json!({})).await;
    assert_eq!(
        status,
        StatusCode::INTERNAL_SERVER_ERROR,
        "_flush must still persist the snapshot: {status} {body}"
    );
}

/// #2234 — a multi-index refresh must not be serialized behind one index.
/// `refresh-busy` is held inside `Index::refresh`. `refresh-healthy` has to
/// finish (its completion counter moves) before that hold is released.
#[tokio::test]
async fn multi_index_refresh_is_not_serialized_behind_one_index() {
    let dir = tempfile::tempdir().expect("data dir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let probe = engine.clone();
    let app = xerj_api::router::build_es_compat_router(xerj_api::state::AppState::new(
        config, engine, metrics,
    ));
    create_text_index_with_document(&app, "refresh-busy").await;
    create_text_index_with_document(&app, "refresh-healthy").await;

    let busy = probe.get_index("refresh-busy").expect("busy index");
    let healthy = probe.get_index("refresh-healthy").expect("healthy index");
    busy.test_set_pause_refresh(true);

    let app_for_request = app.clone();
    let request_task = tokio::spawn(async move {
        request(
            &app_for_request,
            "POST",
            "/refresh-busy,refresh-healthy/_refresh",
            json!({}),
        )
        .await
    });

    tokio::time::timeout(std::time::Duration::from_secs(5), async {
        while !busy.test_refresh_is_paused() {
            tokio::task::yield_now().await;
        }
    })
    .await
    .expect("busy index never entered refresh");

    tokio::time::timeout(std::time::Duration::from_secs(5), async {
        while healthy.test_refresh_finished_count() == 0 {
            tokio::task::yield_now().await;
        }
    })
    .await
    .expect("healthy index did not finish refresh while the busy index was held");
    assert_eq!(
        busy.test_refresh_finished_count(),
        0,
        "the held index must not look finished"
    );

    busy.test_set_pause_refresh(false);
    let (status, body) = tokio::time::timeout(std::time::Duration::from_secs(10), request_task)
        .await
        .expect("refresh request did not finish after the hold was released")
        .expect("refresh task");
    assert!(status.is_success(), "{status} {body}");
    assert_eq!(body.pointer("/_shards/total"), Some(&json!(2)), "{body}");
    assert_eq!(
        body.pointer("/_shards/successful"),
        Some(&json!(2)),
        "{body}"
    );
}

//! Regression coverage for document-copying paths.
//!
//! The default `_source` projection now omits engine-generated embedding
//! companions. `_reindex` must opt into the complete source explicitly, or it
//! silently loses the vectors while reporting a successful copy.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_common::types::{FieldConfig, FieldType, Schema};

async fn seeded_app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);

    let mut schema = Schema::empty();
    let mut body = FieldConfig::new("body", FieldType::Text);
    body.options.dimensions = Some(32);
    body.options.similarity = Some("cosine".into());
    body.embedding = Some(xerj_common::types::EmbeddingConfig {
        endpoint: None,
        model: None,
        target_field: Some("body_vector".into()),
    });
    schema.add_field(body).expect("body field");
    let mut companion = FieldConfig::new("body_vector", FieldType::Vector);
    companion.options.dimensions = Some(32);
    companion.options.similarity = Some("cosine".into());
    schema.add_field(companion).expect("body_vector field");

    state
        .engine
        .create_index("src", schema)
        .expect("create source index");
    let idx = state.engine.get_index("src").expect("get source index");
    let body_text =
        "XERJ preserves generated embedding companions when documents move through copy paths. "
            .repeat(24);
    idx.index_document(Some("1".into()), json!({ "body": body_text }))
        .await
        .expect("index source document");
    idx.refresh().await.expect("refresh source");

    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn post(app: &axum::Router, path: &str, body: Value) -> (StatusCode, Value) {
    let response = app
        .clone()
        .oneshot(
            Request::post(path)
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

#[tokio::test]
async fn reindex_preserves_generated_embedding_companions() {
    let (app, _dir) = seeded_app().await;

    let (status, source_search) = post(
        &app,
        "/src/_search",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "_source": true,
        }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "source search with explicit full _source failed: {source_search}"
    );
    let source = &source_search["hits"]["hits"][0]["_source"];
    let source_vector = source["body_vector"].clone();
    assert!(
        source_vector
            .as_array()
            .is_some_and(|values| !values.is_empty()),
        "the source fixture must contain a generated body_vector: {source}"
    );
    let source_chunks = source
        .get("body_vector_chunks")
        .filter(|chunks| chunks.is_array())
        .cloned();

    let (status, reindex_response) = post(
        &app,
        "/_reindex",
        json!({
            "source": { "index": "src" },
            "dest": { "index": "dst" },
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "reindex failed: {reindex_response}");
    assert_eq!(
        reindex_response["total"], 1,
        "reindex response: {reindex_response}"
    );

    let (status, refresh_response) = post(&app, "/dst/_refresh", json!({})).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "destination refresh failed: {refresh_response}"
    );

    let (status, destination_search) = post(
        &app,
        "/dst/_search",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "_source": true,
        }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "destination search with explicit full _source failed: {destination_search}"
    );
    let destination = &destination_search["hits"]["hits"][0]["_source"];
    assert_eq!(
        destination["body_vector"], source_vector,
        "reindex must request `_source: true` explicitly or generated body_vector is silently lost"
    );
    if let Some(chunks) = source_chunks {
        assert_eq!(
            destination["body_vector_chunks"], chunks,
            "reindex must preserve generated body_vector_chunks when the source document has them"
        );
    }
}

/// `_clone` / `_shrink` / `_split` all funnel through `clone_index_to`, which
/// is a copy path with exactly the same requirement as `_reindex`: read the
/// COMPLETE `_source`, companions included.
///
/// This pins the reconciliation of two changes that landed independently on
/// the same function. One replaced the single `size: 10000` search with a
/// keyset-paged loop that propagates write failures (issue #204 — a clone that
/// silently copied the first 10,000 documents, or copied nothing at all, still
/// answered `{"acknowledged": true}`). The other added the explicit
/// `"_source": true` to the search body, because the default projection hides
/// engine-generated embedding companions. Keeping the loop while dropping the
/// projection would have traded a silently truncated copy for a silently lossy
/// one — the same defect wearing a different hat — so the per-page body
/// carries it, and this test fails if a future edit drops it again.
#[tokio::test]
async fn clone_preserves_generated_embedding_companions() {
    let (app, _dir) = seeded_app().await;

    let (status, source_search) = post(
        &app,
        "/src/_search",
        json!({
            "query": { "match_all": {} },
            "size": 1,
            "_source": true,
        }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "source search with explicit full _source failed: {source_search}"
    );
    let source = &source_search["hits"]["hits"][0]["_source"];
    let source_vector = source["body_vector"].clone();
    assert!(
        source_vector
            .as_array()
            .is_some_and(|values| !values.is_empty()),
        "the source fixture must contain a generated body_vector: {source}"
    );

    // A second document whose companion was supplied by the CALLER and does
    // not match what the embedder would produce from `body`. Without the
    // explicit projection the clone reads the default `_source`, which hides
    // companions, and the destination silently regenerates one from `body` —
    // so this is the document that can tell a verbatim copy from a lossy one.
    // (Document 1 cannot: the destination inherits the source schema, so its
    // regenerated companion is byte-identical to the source's.)
    let supplied: Vec<f64> = (0..32).map(|i| (i as f64) / 32.0).collect();
    let (status, indexed) = post(
        &app,
        "/src/_doc/2?refresh=true",
        json!({ "body": "a second document", "body_vector": supplied }),
    )
    .await;
    assert!(
        status.is_success(),
        "seeding the caller-supplied companion failed: {indexed}"
    );
    let (status, supplied_search) = post(
        &app,
        "/src/_search",
        json!({
            "query": { "ids": { "values": ["2"] } },
            "_source": true,
        }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "source search failed: {supplied_search}"
    );
    let supplied_vector = supplied_search["hits"]["hits"][0]["_source"]["body_vector"].clone();

    let (status, clone_response) = post(&app, "/src/_clone/cloned", json!({})).await;
    assert_eq!(status, StatusCode::OK, "clone failed: {clone_response}");

    let (status, refresh_response) = post(&app, "/cloned/_refresh", json!({})).await;
    assert_eq!(
        status,
        StatusCode::OK,
        "clone refresh failed: {refresh_response}"
    );

    let (status, cloned_search) = post(
        &app,
        "/cloned/_search",
        json!({
            "query": { "match_all": {} },
            "size": 10,
            "_source": true,
        }),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "clone search with explicit full _source failed: {cloned_search}"
    );
    assert_eq!(
        cloned_search["hits"]["total"]["value"], 2,
        "the clone must contain every source document: {cloned_search}"
    );
    let by_id = |id: &str| -> Value {
        cloned_search["hits"]["hits"]
            .as_array()
            .expect("hits array")
            .iter()
            .find(|hit| hit["_id"] == id)
            .unwrap_or_else(|| panic!("document [{id}] missing from the clone: {cloned_search}"))
            ["_source"]
            .clone()
    };
    assert_eq!(
        by_id("1")["body_vector"],
        source_vector,
        "clone lost the generated body_vector"
    );
    assert_eq!(
        by_id("2")["body_vector"],
        supplied_vector,
        "clone must request `_source: true` on every page: without it the copy \
         reads the default projection, the companion never crosses, and the \
         destination regenerates a DIFFERENT vector from `body` while still \
         answering {{\"acknowledged\": true}}"
    );
}

//! End-to-end checks for the `rerank` stage of `_search`, over HTTP, against an
//! in-process stub that speaks TypeSafe's documented System One wire format:
//!
//! ```text
//! POST /v1/systemone
//! request  { state: <query string>, model, questions: { id: { type:"noul", instructions: { question, document } } } }
//! response { model, answers: { id: { type:"noul", noul: 0..1 } }, usage }
//! ```
//!
//! THE STUB IS A TEST DOUBLE, NOT A JUDGE. It scores by a table the test hands
//! it (or by word overlap), so ordering is checkable. Nothing here says
//! anything about ranking quality with the real model — that is measured in
//! docs/research/typesafe-skill-2026-09 (NOTES.md, pilot of 2026-09-20), not
//! by these tests.
//!
//! # Why there is no `set_var` in this file
//!
//! The provider used to read `TYPESAFE_API_KEY` / `TYPESAFE_ENDPOINT` from the
//! process environment on every request. Cargo runs the tests of one binary as
//! parallel threads of one process, so a test that sets those variables races
//! every other test that reads them. Each test here builds its own stub on an
//! ephemeral port and its own node, and points the node at the stub through
//! `AppState::rerank` — the injection seam — so nothing process-wide is touched.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use axum::body::Body;
use axum::http::{HeaderMap, Request, StatusCode};
use axum::response::IntoResponse;
use axum::routing::post;
use serde_json::{json, Value};
use tower::ServiceExt;
use xerj_rerank::ProviderSettings;

// ─────────────────────────────────────────────────────────────────────────────
// The stub provider
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Clone)]
enum Verdicts {
    /// Fraction of the query's words found in the document (what the scratch
    /// `stub.py` did).
    Overlap,
    /// Probability by document title; titles not listed score 0.0.
    ByTitle(HashMap<String, f64>),
}

#[derive(Clone)]
enum Fault {
    None,
    /// Answer every call with this status and an error body.
    Status(u16),
    /// Answer the first `n` calls with `status`, then behave.
    StatusThenOk {
        n: usize,
        status: u16,
    },
    /// 200 with a body that is not JSON.
    Garbage,
    /// Sleep this long before answering correctly.
    Delay(Duration),
    /// 401 with a body that echoes the bearer token back, as some APIs do.
    EchoKey,
    /// Answer correctly, and ALSO return a 0.99 verdict for `d0`..`d9` whether
    /// or not those documents were sent — a provider that misbehaves.
    AnswerUnsent,
    /// Answer every other document in each call and stay silent on the rest.
    Partial,
    /// Answer ONLY for keys nobody sent (`d999`, `x`): a provider that parses
    /// but says nothing about the documents it was asked about.
    WrongKeys,
    /// Answer correctly, and ALSO echo a 0.5 verdict for `d0`..`d59` on every
    /// call — a provider that leaks other batches' keys back.
    EchoOtherBatches,
    /// Answer every document correctly, under a `usage` block whose numbers
    /// are not the unsigned integers the documentation promises.
    OddUsage,
    /// 200 with a valid JSON body of several megabytes: a provider (or
    /// something answering in its place) that does not know when to stop.
    HugeBody,
}

#[derive(Clone)]
struct Captured {
    authorization: Option<String>,
    body: Value,
}

#[derive(Clone)]
struct Stub {
    verdicts: Arc<Mutex<Verdicts>>,
    fault: Arc<Mutex<Fault>>,
    seen: Arc<Mutex<Vec<Captured>>>,
    endpoint: String,
}

impl Stub {
    async fn start() -> Self {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind an ephemeral port");
        let addr = listener.local_addr().expect("local addr");
        let stub = Stub {
            verdicts: Arc::new(Mutex::new(Verdicts::Overlap)),
            fault: Arc::new(Mutex::new(Fault::None)),
            seen: Arc::new(Mutex::new(Vec::new())),
            endpoint: format!("http://{addr}/v1/systemone"),
        };
        let app = axum::Router::new()
            .route("/v1/systemone", post(systemone))
            .with_state(stub.clone());
        tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        stub
    }

    fn by_title(&self, table: &[(&str, f64)]) {
        *self.verdicts.lock().unwrap() =
            Verdicts::ByTitle(table.iter().map(|(t, p)| (t.to_string(), *p)).collect());
    }
    fn fault(&self, f: Fault) {
        *self.fault.lock().unwrap() = f;
    }
    fn calls(&self) -> Vec<Captured> {
        self.seen.lock().unwrap().clone()
    }
    /// Everything that left the node, as one string — for "this text was never
    /// sent" assertions.
    fn everything_sent(&self) -> String {
        self.calls()
            .iter()
            .map(|c| c.body.to_string())
            .collect::<Vec<_>>()
            .join("\n")
    }
}

fn words(s: &str) -> std::collections::HashSet<String> {
    s.to_lowercase()
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(str::to_string)
        .collect()
}

async fn systemone(
    axum::extract::State(stub): axum::extract::State<Stub>,
    headers: HeaderMap,
    body: String,
) -> axum::response::Response {
    let parsed: Value = serde_json::from_str(&body).unwrap_or(Value::Null);
    let nth = {
        let mut seen = stub.seen.lock().unwrap();
        seen.push(Captured {
            authorization: headers
                .get("authorization")
                .and_then(|v| v.to_str().ok())
                .map(str::to_string),
            body: parsed.clone(),
        });
        seen.len()
    };
    let fault = stub.fault.lock().unwrap().clone();
    match fault {
        Fault::Status(code) => {
            return (
                StatusCode::from_u16(code).unwrap(),
                axum::Json(json!({"error": "stub fault"})),
            )
                .into_response();
        }
        Fault::StatusThenOk { n, status } if nth <= n => {
            return (
                StatusCode::from_u16(status).unwrap(),
                axum::Json(json!({"error": "stub fault"})),
            )
                .into_response();
        }
        Fault::EchoKey => {
            let auth = headers
                .get("authorization")
                .and_then(|v| v.to_str().ok())
                .unwrap_or_default();
            return (
                StatusCode::UNAUTHORIZED,
                axum::Json(json!({"error": format!("invalid api key: {auth}")})),
            )
                .into_response();
        }
        Fault::Garbage => return (StatusCode::OK, "not json").into_response(),
        Fault::HugeBody => {
            let padding = "x".repeat(3 * 1024 * 1024);
            return axum::Json(json!({"model": "m", "answers": {}, "padding": padding}))
                .into_response();
        }
        Fault::Delay(d) => tokio::time::sleep(d).await,
        _ => {}
    }

    let query = words(parsed["state"].as_str().unwrap_or_default());
    let verdicts = stub.verdicts.lock().unwrap().clone();
    let mut answers = serde_json::Map::new();
    if matches!(fault, Fault::WrongKeys) {
        answers.insert("d999".into(), json!({"type": "noul", "noul": 0.9}));
        answers.insert("x".into(), json!({"type": "noul", "noul": 0.9}));
        return axum::Json(json!({
            "model": parsed["model"],
            "answers": answers,
            "usage": {"input_tokens": 100, "output_tokens": 10},
        }))
        .into_response();
    }
    if let Some(qs) = parsed["questions"].as_object() {
        for (i, (key, q)) in qs.iter().enumerate() {
            if matches!(fault, Fault::Partial) && i % 2 == 1 {
                continue;
            }
            // The candidate rides inside its own question's instructions,
            // joined "title. text" — the wire shape `build_jev_request` sends.
            let doc = q["instructions"]["document"].as_str().unwrap_or_default();
            let (title, text) = match doc.split_once(". ") {
                Some((t, x)) => (t, x),
                None => (doc, ""),
            };
            let p = match &verdicts {
                Verdicts::Overlap => {
                    let have = words(&format!("{title} {text}"));
                    query.intersection(&have).count() as f64 / query.len().max(1) as f64
                }
                Verdicts::ByTitle(table) => table.get(title).copied().unwrap_or(0.0),
            };
            answers.insert(key.clone(), json!({"type": "noul", "noul": p}));
        }
    }
    if matches!(fault, Fault::AnswerUnsent) {
        for i in 0..10 {
            answers
                .entry(format!("d{i}"))
                .or_insert_with(|| json!({"type": "noul", "noul": 0.99}));
        }
    }
    if matches!(fault, Fault::EchoOtherBatches) {
        for i in 0..60 {
            answers
                .entry(format!("d{i}"))
                .or_insert_with(|| json!({"type": "noul", "noul": 0.5}));
        }
    }
    let usage = if matches!(fault, Fault::OddUsage) {
        json!({"input_tokens": 9_223_372_036_854_775_808u64, "output_tokens": -5})
    } else {
        json!({"input_tokens": 100, "output_tokens": 10})
    };
    axum::Json(json!({
        "model": parsed["model"],
        "answers": answers,
        "usage": usage,
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// The node
// ─────────────────────────────────────────────────────────────────────────────

struct Node {
    app: axum::Router,
    /// The XERJ-native REST API (`/v1/...`), over the SAME state as `app`.
    native: axum::Router,
    _dir: tempfile::TempDir,
}

async fn node_with(settings: ProviderSettings) -> Node {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let mut state = xerj_api::state::AppState::new(config, engine, metrics);
    // The seam. Whatever TYPESAFE_* the developer's shell happens to hold was
    // read into `state.rerank` by `AppState::new`; it is replaced wholesale
    // here, so no test can reach the real provider or depend on the ambient
    // environment.
    state.rerank = Arc::new(settings);
    Node {
        native: xerj_api::router::build_native_router(state.clone()),
        app: xerj_api::router::build_es_compat_router(state),
        _dir: dir,
    }
}

async fn node(stub: &Stub) -> Node {
    node_with(ProviderSettings::with_key_and_endpoint(
        "test-key",
        &stub.endpoint,
    ))
    .await
}

impl Node {
    async fn raw(&self, method: &str, path: &str, body: String) -> (StatusCode, String) {
        let response = self
            .app
            .clone()
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body))
                    .expect("request"),
            )
            .await
            .expect("response");
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        (status, String::from_utf8_lossy(&bytes).into_owned())
    }

    async fn call(&self, method: &str, path: &str, body: Value) -> (StatusCode, Value) {
        let (status, text) = self.raw(method, path, body.to_string()).await;
        (status, serde_json::from_str(&text).unwrap_or(Value::Null))
    }

    async fn search(&self, path: &str, body: Value) -> (StatusCode, Value) {
        self.call("POST", path, body).await
    }

    /// The four documents the scratch script used.
    async fn seed_kb(&self) {
        self.seed(
            "kb",
            &[
                (
                    "1",
                    "Bone health basics",
                    "vitamin supplements are popular. vitamin vitamin vitamin vitamin.",
                    "health",
                    1,
                ),
                (
                    "2",
                    "Trial results",
                    "vitamin d supplementation improved bone density in the treatment group",
                    "trial",
                    2,
                ),
                (
                    "3",
                    "Cooking",
                    "vitamin rich vegetables for dinner",
                    "food",
                    3,
                ),
                (
                    "4",
                    "Density of materials",
                    "bone china has high density",
                    "materials",
                    4,
                ),
            ],
        )
        .await;
    }

    async fn seed(&self, index: &str, docs: &[(&str, &str, &str, &str, i64)]) {
        let (st, b) = self
            .call(
                "PUT",
                &format!("/{index}"),
                json!({"mappings": {"properties": {
                    "title": {"type": "text"},
                    "body": {"type": "text"},
                    "cat": {"type": "keyword"},
                    "n": {"type": "integer"}
                }}}),
            )
            .await;
        assert!(st.is_success(), "create {index}: {st} {b}");
        for (id, title, body, cat, n) in docs {
            let (st, b) = self
                .call(
                    "PUT",
                    &format!("/{index}/_doc/{id}"),
                    json!({"title": title, "body": body, "cat": cat, "n": n}),
                )
                .await;
            assert!(st.is_success(), "index {index}/{id}: {st} {b}");
        }
        let (st, b) = self
            .call("POST", &format!("/{index}/_refresh"), json!({}))
            .await;
        assert!(st.is_success(), "refresh {index}: {st} {b}");
    }
}

const Q: &str = "vitamin d supplementation bone density";

fn match_q() -> Value {
    json!({"match": {"body": Q}})
}

fn ids(r: &Value) -> Vec<String> {
    r["hits"]["hits"]
        .as_array()
        .map(|a| {
            a.iter()
                .map(|h| h["_id"].as_str().unwrap_or_default().to_string())
                .collect()
        })
        .unwrap_or_default()
}

fn reason(r: &Value) -> String {
    r["error"]["reason"]
        .as_str()
        .unwrap_or_default()
        .to_string()
}

/// A judge that inverts whatever the engine said about the four `kb` docs.
fn inverted(stub: &Stub) {
    stub.by_title(&[
        ("Cooking", 0.9),
        ("Bone health basics", 0.7),
        ("Density of materials", 0.3),
        ("Trial results", 0.1),
    ]);
}
const INVERTED_IDS: [&str; 4] = ["3", "1", "4", "2"];

