        .await;
    assert_eq!(st, StatusCode::OK, "{r}");
    assert_eq!(r["_rerank"]["applied"], true, "{r}");
    assert_eq!(r["_rerank"]["judged"], 4, "{r}");
    let sent = stub.everything_sent();
    assert!(sent.contains("supplementation"), "{sent}");
