/// The `#437` gate must NOT reject a sort on an unmapped field that carries
/// ES's `unmapped_type` escape hatch: real Elasticsearch answers 200 and
/// treats every document as missing, and XERJ's own memory-list endpoint
/// issues exactly `{"stored_at":{"order":"desc","unmapped_type":"long"}}` as a
/// guard for namespaces created before `stored_at` existed. Rejecting it (the
/// #504 review's blocking finding) would 400 those requests. Both directions
/// are pinned here so the exemption cannot silently regress in either sense.
#[tokio::test]
async fn sort_on_an_unmapped_field_with_unmapped_type_is_not_rejected() {
    let (app, _dir) = app().await;
    seed(&app, "umt", 4).await; // docs carry only `n`; `stored_at` is unmapped

    // With unmapped_type: ES treats every doc as missing — 200, not an error.
    let (status, body) = send(
        &app,
        Request::builder()
            .method("POST")
            .uri("/umt/_search")
            .header("content-type", "application/json")
            .body(Body::from(
                json!({
                    "query": {"match_all": {}},
                    "sort": [{"stored_at": {"order": "desc", "unmapped_type": "long"}}]
                })
                .to_string(),
            ))
            .unwrap(),
    )
    .await;
    assert_eq!(
        status,
        StatusCode::OK,
        "sort on an unmapped field carrying unmapped_type must be answered (ES \
         treats it as all-missing), not rejected: {body}"
    );
    assert_eq!(
        body["hits"]["total"]["value"], 4,
        "all four docs must come back, sorted as missing: {body}"
    );

    // Without unmapped_type the same field is still rejected (the #437 fix).
    let (status, body) = send(
        &app,
        Request::builder()
            .method("POST")
            .uri("/umt/_search")
            .header("content-type", "application/json")
            .body(Body::from(
                json!({"query": {"match_all": {}}, "sort": [{"stored_at": "desc"}]}).to_string(),
            ))
            .unwrap(),
    )
    .await;
    assert_no_mapping_found_error(status, &body, "stored_at");
}

//! A `quantization: "scalar8"` field must score the vector the document
//! CURRENTLY holds even when the new vector falls outside the range the
//! codebook was fitted from — issue #371, second half.
//!
//! `sq8_codes_follow_document_updates.rs` pins the per-document half: codes
//! must not be cached write-once per document id. This file pins the CODEBOOK
//! half, which is the same defect one level up. The per-dimension min/scale
//! pair (`Sq8Params`) was fitted from the first ≤1000 candidate vectors the
//! field was ever scanned with and then kept for the life of the process. A
//! vector written afterwards that falls outside that fitted range is clamped
//! into it, and when the fitted range is narrow the clamped decode is
//! indistinguishable from the vector that was there before — so the headline
//! symptom of #371 survives unchanged:
//!
//!  * `codebook_tracks_a_vector_written_outside_the_fitted_range` — 20 docs
//!    whose first dimension is pinned at +1.0, so dimension 0 fits to the
//!    degenerate range [1,1]. Overwrite doc 0 with its exact negation and a
//!    stale codebook decodes -1.0 straight back to +1.0: doc 0 still first at
//!    `_score` 1.000000, whole score list frozen. Verbatim the issue.
//!
//!  * `codebook_tracks_a_whole_corpus_re_embedding` — the workload the issue
//!    names as what makes it a blocker. Fit the codebook on model-A vectors,
//!    bulk-rewrite every document with model-B vectors, query with a model-B
//!    vector. A stale codebook clamps the entire corpus onto a handful of
//!    codes: every document collapses onto one identical score and the exact
//!    match ranks nowhere.
//!
//! Both carry the full-precision index as a control through every step, so a
//! failure here cannot be a test artifact — the control performs the identical
//! manipulation and is asserted first.
//!
//! Elasticsearch is referenced for wire semantics only. It is AGPL-3.0/
//! SSPL-1.0/Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

const SQ8: &str = "sq8";
const EXACT: &str = "exact";

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method(method)
            .uri(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn ndjson(app: &axum::Router, path: &str, body: String) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method("POST")
            .uri(path)
            .header("content-type", "application/x-ndjson")
            .body(Body::from(body))
            .expect("request"),
    )
    .await
}

/// Create the quantized index and its full-precision control, identical apart
/// from the `quantization` option.
async fn create_pair(app: &axum::Router, dim: usize) {
    for (index, field_def) in [
        (
            SQ8,
            json!({ "type": "dense_vector", "dims": dim, "quantization": "scalar8" }),
        ),
        (EXACT, json!({ "type": "dense_vector", "dims": dim })),
    ] {
        let (status, body) = json_req(
            app,
            "PUT",
            &format!("/{index}"),
            json!({ "mappings": { "properties": { "v": field_def } } }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "create {index}: {body}");
    }
}

async fn refresh(app: &axum::Router, index: &str) {
    let (status, body) = json_req(app, "POST", &format!("/{index}/_refresh"), json!({})).await;
    assert!(status.is_success(), "refresh {index}: {status} {body}");
}

/// Write `vectors` into `index` through `_bulk`, then refresh.
async fn bulk_index(app: &axum::Router, index: &str, vectors: &[Vec<f32>]) {
    let mut body = String::new();
    for (i, v) in vectors.iter().enumerate() {
        body.push_str(&json!({ "index": { "_index": index, "_id": i.to_string() } }).to_string());
        body.push('\n');
        body.push_str(&json!({ "v": v }).to_string());
        body.push('\n');
    }
    let (status, response) = ndjson(app, "/_bulk?refresh=true", body).await;
    assert_eq!(status, StatusCode::OK, "bulk {index}: {response}");
    assert_eq!(
        response["errors"],
        json!(false),
        "bulk {index} reported errors: {response}"
    );
    refresh(app, index).await;
}

/// `(id, score)` for the whole corpus, in hit order.
async fn knn(app: &axum::Router, index: &str, query: &[f32], n: usize) -> Vec<(String, f64)> {
    let (status, body) = json_req(
        app,
        "POST",
        &format!("/{index}/_search"),
        json!({
            "knn": {
                "field": "v",
                "query_vector": query,
                "k": n,
                "num_candidates": n * 4
            },
            "size": n,
            "_source": false
        }),
    )
    .await;
    assert!(status.is_success(), "knn on {index}: {status} {body}");
    body["hits"]["hits"]
        .as_array()
        .unwrap_or_else(|| panic!("no hits on {index}: {body}"))
        .iter()
        .map(|h| {
            (
                h["_id"].as_str().expect("_id").to_string(),
                h["_score"].as_f64().expect("_score"),
            )
        })
        .collect()
}

fn score_of(hits: &[(String, f64)], id: &str) -> f64 {
    hits.iter()
        .find(|(hit_id, _)| hit_id == id)
        .unwrap_or_else(|| panic!("{id} missing from {hits:?}"))
        .1
}

fn rank_of(hits: &[(String, f64)], id: &str) -> usize {
    hits.iter()
        .position(|(hit_id, _)| hit_id == id)
        .unwrap_or_else(|| panic!("{id} missing from {hits:?}"))
}

/// Confirm the write landed in `_source`. If this fails nothing below means
/// anything.
async fn assert_source(app: &axum::Router, index: &str, id: &str, want: &[f32]) {
    let (status, body) = get(app, &format!("/{index}/_doc/{id}")).await;
    assert!(status.is_success(), "get {index}/{id}: {status} {body}");
    let stored: Vec<f64> = body["_source"]["v"]
        .as_array()
        .unwrap_or_else(|| panic!("no _source.v on {index}: {body}"))
        .iter()
        .map(|v| v.as_f64().expect("float"))
        .collect();
    let want: Vec<f64> = want.iter().map(|x| *x as f64).collect();
    assert_eq!(stored, want, "{index}/{id}: _source did not take the write");
}

/// How many distinct `_score` values the hit list carries. A codebook that has
/// clamped the whole corpus collapses this to 1.
fn distinct_scores(hits: &[(String, f64)]) -> usize {
    let mut seen: Vec<u64> = hits.iter().map(|(_, s)| s.to_bits()).collect();
    seen.sort_unstable();
    seen.dedup();
    seen.len()
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. Narrow fitted range: the update falls outside the codebook
// ─────────────────────────────────────────────────────────────────────────────

const NARROW_DIM: usize = 8;
const NARROW_DOCS: usize = 20;

/// Every document pins dimension 0 at +1.0 and varies only in dimension 1, so
/// the fitted range for dimension 0 is the degenerate `[1, 1]`. That is what a
/// real corpus of near-identical embeddings looks like to a per-dimension
/// min/max fit, and it is the case a codebook cannot represent a later `-1`
/// in: it clamps back to `+1`.
fn narrow_vector(i: usize) -> Vec<f32> {
    let mut v = vec![0.0f32; NARROW_DIM];
    v[0] = 1.0;
    v[1] = i as f32 * 0.001;
    v
}

fn narrow_negated() -> Vec<f32> {
    narrow_vector(0).iter().map(|x| -x).collect()
}

#[tokio::test]
async fn codebook_tracks_a_vector_written_outside_the_fitted_range() {
    let (app, _dir) = app().await;
    create_pair(&app, NARROW_DIM).await;

    let corpus: Vec<Vec<f32>> = (0..NARROW_DOCS).map(narrow_vector).collect();
    bulk_index(&app, SQ8, &corpus).await;
    bulk_index(&app, EXACT, &corpus).await;

    let query = narrow_vector(0);

    // Step 1 — query once. This is what fits the codebook, over a corpus whose
    // dimension 0 never leaves +1.0.
    let sq8_before = knn(&app, SQ8, &query, NARROW_DOCS).await;
    let exact_before = knn(&app, EXACT, &query, NARROW_DOCS).await;
    for (index, hits) in [(SQ8, &sq8_before), (EXACT, &exact_before)] {
        assert_eq!(
            hits[0].0, "0",
            "{index}: doc 0 IS the query vector, it must rank first: {hits:?}"
        );
    }

    // Step 2/3 — overwrite doc 0 with its exact negation (true cosine -1) and
    // confirm the write landed.
    let negated = narrow_negated();
    for index in [SQ8, EXACT] {
        let (status, body) = json_req(
            &app,
            "PUT",
            &format!("/{index}/_doc/0"),
            json!({ "v": negated }),
        )
        .await;
        assert!(status.is_success(), "update {index}: {status} {body}");
        refresh(&app, index).await;
        assert_source(&app, index, "0", &negated).await;
    }

    // Step 4 — the same query again.
    let sq8_after = knn(&app, SQ8, &query, NARROW_DOCS).await;
    let exact_after = knn(&app, EXACT, &query, NARROW_DOCS).await;

    // Control first: if the full-precision index does not move doc 0 either,
    // the manipulation is wrong and the SQ8 assertion below is meaningless.
    assert_ne!(
        exact_after[0].0, "0",
        "EXACT control did not move doc 0 — the manipulation is wrong: {exact_after:?}"
    );
    assert!(
        score_of(&exact_after, "0") < 0.1,
        "EXACT control: doc 0 is the exact negation of the query, expected \
         _score 0.0, got {}: {exact_after:?}",
        score_of(&exact_after, "0")
    );

    // The assertion the stale codebook fails.
    assert_ne!(
        sq8_after[0].0, "0",
        "SQ8: doc 0 now holds the NEGATION of the query vector and must not be \
         the top hit. The codebook was fitted while dimension 0 never left \
         +1.0, so -1.0 clamps back to +1.0 and the document is scored on a \
         vector it no longer holds (#371): {sq8_after:?}"
    );
    let before_scores: Vec<f64> = sq8_before.iter().map(|(_, s)| *s).collect();
    let after_scores: Vec<f64> = sq8_after.iter().map(|(_, s)| *s).collect();
    assert_ne!(
        before_scores, after_scores,
        "SQ8: the score list is unchanged by a vector rewrite — the ranking is \
         frozen at first observation (#371): {sq8_after:?}"
    );
    let moved = score_of(&sq8_after, "0");
    assert!(
        moved < 0.1,
        "SQ8: doc 0 is the exact negation of the query (true cosine -1, _score \
         0.0) but scored {moved}: {sq8_after:?}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. Whole-corpus re-embedding — the workload #371 calls out as the blocker
// ─────────────────────────────────────────────────────────────────────────────

const EMBED_DIM: usize = 16;
const EMBED_DOCS: usize = 50;
/// The document whose model-B vector is the query vector itself.
const TARGET: usize = 9;

/// "model A": a narrow positive cone. Every component sits within 0.7% of 1.0,
/// so after cosine's L2 normalisation each dimension occupies a band about
/// 0.0006 wide around 0.25. Real embedding models are famously anisotropic in
/// exactly this way, and a per-dimension min/max fit over such a corpus is a
/// codebook that can represent almost nothing else.
fn model_a(i: usize) -> Vec<f32> {
    (0..EMBED_DIM)
        .map(|d| 1.0 + ((i * 31 + d * 17) % 64) as f32 / 10_000.0)
        .collect()
}

/// "model B": a different embedding space entirely — components spread over
/// `[-1, 1]`, which is what swapping an embedding model actually does to a
/// corpus. Nothing here is inside model A's fitted range.
fn model_b(i: usize) -> Vec<f32> {
    (0..EMBED_DIM)
        .map(|d| ((i * 53 + d * 29) % 128) as f32 / 63.5 - 1.0)
        .collect()
}

#[tokio::test]
async fn codebook_tracks_a_whole_corpus_re_embedding() {
    let (app, _dir) = app().await;
    create_pair(&app, EMBED_DIM).await;

    let a: Vec<Vec<f32>> = (0..EMBED_DOCS).map(model_a).collect();
    let b: Vec<Vec<f32>> = (0..EMBED_DOCS).map(model_b).collect();

    bulk_index(&app, SQ8, &a).await;
    bulk_index(&app, EXACT, &a).await;

    // Query once under model A. This is what fits the codebook — over vectors
    // that all live in [0, 0.25].
    let warm = model_a(0);
    knn(&app, SQ8, &warm, EMBED_DOCS).await;
    knn(&app, EXACT, &warm, EMBED_DOCS).await;

    // Re-embed: rewrite every document with its model-B vector.
    bulk_index(&app, SQ8, &b).await;
    bulk_index(&app, EXACT, &b).await;
    for index in [SQ8, EXACT] {
        assert_source(&app, index, &TARGET.to_string(), &b[TARGET]).await;
    }

    // Query with a model-B vector whose exact match is doc TARGET.
    let query = model_b(TARGET);
    let sq8 = knn(&app, SQ8, &query, EMBED_DOCS).await;
    let exact = knn(&app, EXACT, &query, EMBED_DOCS).await;

    // Control first.
    assert_eq!(
        exact[0].0,
        TARGET.to_string(),
        "EXACT control: doc {TARGET} IS the query vector and must rank first: {exact:?}"
    );

    // A codebook clamped to model A's [0, 0.25] band maps the whole re-embedded
    // corpus onto the same handful of codes, which collapses every score onto
    // one value and destroys ranking entirely.
    let distinct = distinct_scores(&sq8);
    assert!(
        distinct > EMBED_DOCS / 2,
        "SQ8: {distinct} distinct scores across {EMBED_DOCS} re-embedded \
         documents — the codebook is still fitted to the pre-re-embedding \
         corpus and has clamped them together (#371): {sq8:?}"
    );
    let rank = rank_of(&sq8, &TARGET.to_string());
    assert_eq!(
        rank, 0,
        "SQ8: doc {TARGET} IS the query vector after re-embedding but ranks \
         {rank} — the codebook did not follow the corpus (#371): {sq8:?}"
    );
    // Doc TARGET is the query vector itself, so its `_score` is 1.0 on the
    // control. A codebook fitted to the pre-re-embedding corpus crushes it
    // into the same ~0.59 band as everything else; a codebook fitted to the
    // corpus that is actually there has to put it back near 1.0.
    let target_score = score_of(&sq8, &TARGET.to_string());
    assert!(
        target_score > 0.95,
        "SQ8: doc {TARGET} IS the query vector after re-embedding but scored \
         {target_score} (control: {}) — the codebook did not follow the corpus \
         (#371): {sq8:?}",
        score_of(&exact, &TARGET.to_string())
    );
    // Ranking discrimination, pinned against the control rather than against a
    // threshold picked out of this corpus: the quantized index must agree with
    // the full-precision one on the top of the re-embedded list. Under a stale
    // codebook the SQ8 order here is unrelated to the control's.
    let sq8_order: Vec<&str> = sq8.iter().map(|(id, _)| id.as_str()).collect();
    let exact_order: Vec<&str> = exact.iter().map(|(id, _)| id.as_str()).collect();
    assert_eq!(
        sq8_order[..5],
        exact_order[..5],
        "SQ8 and the full-precision control disagree on the post-re-embedding \
         top 5: {sq8:?} vs {exact:?}"
    );
    // And the score range must still span the corpus rather than sit in a
    // clamped band. The control spreads over roughly [0.22, 1.0]; a stale
    // codebook squeezed the whole 50 documents into 0.002.
    let spread = sq8[0].1 - sq8[sq8.len() - 1].1;
    assert!(
        spread > 0.5,
        "SQ8: the whole re-embedded corpus spans only {spread} in _score — \
         the codebook has clamped it into a band (#371): {sq8:?}"
    );
}

//! Issue #392 — `scalar8` codes must be written at INGEST time, addressed by
//! a dense slot, and scored against a codebook that is a property of the
//! index rather than of the query's candidate set.
//!
//! Two observable consequences, each pinned here from the outside over real
//! HTTP:
//!
//!  * `sq8_codes_exist_at_ingest_before_any_query` — after indexing (and
//!    before a single kNN), `GET /{index}/_stats` reports a live, ready SQ8
//!    code store for the field. Before #392 nothing quantized anything at
//!    ingest: the serving path read each candidate's f32 vector out of
//!    `_source` and quantized it per query, so no such store existed and the
//!    stats section is absent (null).
//!
//!  * `scores_do_not_depend_on_a_filter_that_keeps_the_fitted_range` /
//!    `a_filter_that_narrows_the_fitted_range_keeps_scores_within_the_quantization_step`
//!    — the reconciled filter contract. UNFILTERED kNN scores from the
//!    ingest-time codes under the whole-corpus codebook (#392's fast path);
//!    FILTERED kNN scores through the exact scan's per-query codec, fitted
//!    over the POST-FILTER candidate set, because that is the arithmetic the
//!    exact-scan oracle (`exact_scan_hydration_tests`, #979) defines and a
//!    filtered subset's per-dimension bounds are generally narrower than the
//!    corpus fit. Where the two agree by construction — a filter that
//!    removes only documents strictly INSIDE the fitted range, leaving every
//!    per-dimension bound in place — the per-query codec reproduces the
//!    store's codes exactly and every survivor scores bit-identically to the
//!    unfiltered query (asserted EXACTLY). Where the filter narrows the
//!    fitted range (the wide-doc fixture below), scores move by at most
//!    SQ8's reconstruction error (asserted within a generous step-sized
//!    bound; measured 1e-7 on this fixture). Before #392 the codebook was
//!    fitted per query with NO ingest-time store at all — the defect these
//!    two tests still guard against regressing into.
//!
//!  * `codes_survive_a_restart` — the code store is re-derived from the live
//!    documents when the index reopens (WAL replay never re-runs vector
//!    indexing), and once the rebuild lands the same query returns the same
//!    neighbours. A regression pin for the rebuild, not a fail-before: the
//!    per-query-fit path that preceded it also survives a restart.
//!
//!  * `a_wrong_dimension_document_does_not_break_the_field` — a document
//!    whose vector has the wrong dimensionality breaks the store's coverage
//!    invariant; queries must then fall back to the exact path and still
//!    return correct results (the malformed document is skipped, exactly as
//!    the brute-force scan skips it).
//!
//! Elasticsearch is referenced for wire semantics only. It is AGPL-3.0/
//! SSPL-1.0/Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

const DIM: usize = 8;
const INDEX: &str = "sq8";

/// 25 corpus documents whose every dimension lies in `[0, 1)` — the documents
/// both queries score. Deterministic prime-stride walk, all values distinct
/// and not representable on both SQ8 grids (that is what makes the unfixed
/// code's score drift observable rather than coincidentally zero).
const KEEP: usize = 25;

/// 5 documents carrying `tag: "wide"` whose dimension 0 sits far outside the
/// keep documents' range. They widen the per-query-fitted codebook only when
/// present, which is exactly the candidate-set dependency under test.
const WIDE_IDS: [usize; 5] = [100, 101, 102, 103, 104];

fn keep_vector(i: usize) -> Vec<f32> {
    (0..DIM)
        .map(|d| ((i * 37 + d * 101) % 199) as f32 / 199.0)
        .collect()
}

fn wide_vector(i: usize) -> Vec<f32> {
    let mut v = vec![0.0f32; DIM];
    v[0] = 5.0 + i as f32;
    for (d, cell) in v.iter_mut().enumerate().skip(1) {
        *cell = ((i * 53 + d * 97) % 199) as f32 / 199.0;
    }
    v
}

/// The vector document `i` carries, L2-normalized exactly as the ingest hook
/// and the exact scan normalize it (`l2_normalize_vec`'s arithmetic). The
/// codebook — the store's and the per-query codec's — is fitted over these.
fn normalized_vector(i: usize) -> Vec<f32> {
    let raw = if WIDE_IDS.contains(&i) {
        wide_vector(i)
    } else {
        keep_vector(i)
    };
    let norm: f32 = raw.iter().map(|x| x * x).sum::<f32>().sqrt();
    if norm > 0.0 {
        raw.into_iter().map(|x| x / norm).collect()
    } else {
        raw
    }
}

/// Documents strictly INSIDE the fitted per-dimension range of the full
/// corpus: no dimension of their normalized vector holds a bound, so
/// filtering them away leaves the fitted codebook bit-identical — the one
/// filtered shape whose scores must equal the unfiltered codes path's
/// exactly.
fn interior_ids() -> Vec<usize> {
    let all: Vec<Vec<f32>> = (0..KEEP)
        .chain(WIDE_IDS.iter().copied())
        .map(normalized_vector)
        .collect();
    let mut interior = Vec::new();
    for (i, v) in all.iter().enumerate() {
        let id = if i < KEEP { i } else { WIDE_IDS[i - KEEP] };
        let holds_bound = (0..DIM).any(|d| {
            v[d] == all.iter().map(|w| w[d]).fold(f32::MAX, f32::min)
                || v[d] == all.iter().map(|w| w[d]).fold(f32::MIN, f32::max)
        });
        if !holds_bound {
            interior.push(id);
        }
    }
    interior
}

fn doc(i: usize) -> Value {
    // Interior WIDE documents exist too (only two of the five wide docs hold
    // dimension 0's bounds); they must carry the removable tag as well or the
    // interior filter's removal set would not line up with the docs that
    // actually hold no bound.
    let interior = interior_ids().contains(&i);
    if WIDE_IDS.contains(&i) {
        if interior {
            json!({ "tag": ["wide", "interior"], "v": wide_vector(i) })
        } else {
            json!({ "tag": "wide", "v": wide_vector(i) })
        }
    } else if interior {
        json!({ "tag": ["keep", "interior"], "v": keep_vector(i) })
    } else {
        json!({ "tag": "keep", "v": keep_vector(i) })
    }
}

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method(method)
            .uri(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn create_and_index(app: &axum::Router) {
    let (status, body) = json_req(
        app,
        "PUT",
        &format!("/{INDEX}"),
        json!({
            "mappings": { "properties": {
                "v": { "type": "dense_vector", "dims": DIM, "quantization": "scalar8" }
            } }
        }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "create: {body}");
    for i in 0..KEEP {
        let (status, body) = json_req(app, "PUT", &format!("/{INDEX}/_doc/{i}"), doc(i)).await;
        assert!(status.is_success(), "index {i}: {status} {body}");
    }
    for &i in &WIDE_IDS {
        let (status, body) = json_req(app, "PUT", &format!("/{INDEX}/_doc/{i}"), doc(i)).await;
        assert!(status.is_success(), "index {i}: {status} {body}");
    }
    let (status, body) = json_req(app, "POST", &format!("/{INDEX}/_refresh"), json!({})).await;
    assert!(status.is_success(), "refresh: {status} {body}");
}

/// The query vector: keep document 0's own vector. All keep documents score
/// distinctly against it (deterministic corpus), so score identity between
/// the two queries is not satisfiable by accident.
fn query_vector() -> Vec<f32> {
    keep_vector(0)
}

/// Run the kNN, returning `(id, _score)` per hit.
async fn knn(app: &axum::Router, filter: Option<Value>) -> Vec<(String, f64)> {
    let mut knn_body = json!({
        "field": "v",
        "query_vector": query_vector(),
        "k": KEEP + WIDE_IDS.len(),
        "num_candidates": 100
    });
    if let Some(f) = filter {
        knn_body["filter"] = f;
    }
    let (status, body) = json_req(
        app,
        "POST",
        &format!("/{INDEX}/_search"),
        json!({ "knn": knn_body, "size": KEEP + WIDE_IDS.len(), "_source": false }),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "knn: {status} {body}");
    body["hits"]["hits"]
        .as_array()
        .unwrap_or_else(|| panic!("no hits: {body}"))
        .iter()
        .map(|h| {
            (
                h["_id"].as_str().expect("_id").to_string(),
                h["_score"].as_f64().expect("_score"),
            )
        })
        .collect()
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. Codes exist at ingest — before any query is served
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn sq8_codes_exist_at_ingest_before_any_query() {
    let (app, _dir) = app().await;
    create_and_index(&app).await;

    // No kNN has run. If SQ8 codes are written at ingest, the per-index stats
    // section reports them; on the per-query-fit path this whole section is
    // absent because nothing exists to report.
    let (status, body) = get(&app, &format!("/{INDEX}/_stats")).await;
    assert_eq!(status, StatusCode::OK, "stats: {status} {body}");
    let field = &body["indices"][INDEX]["primaries"]["sq8"]["fields"]["v"];
    assert!(
        field.is_object(),
        "no ingest-time SQ8 code store in stats (issue #392): {body}"
    );
    assert_eq!(field["dim"], json!(DIM), "{body}");
    assert_eq!(
        field["live"],
        json!(KEEP + WIDE_IDS.len()),
        "every indexed document must hold a live code slot: {body}"
    );
    assert_eq!(
        field["expected"],
        json!(KEEP + WIDE_IDS.len()),
        "coverage numerator and denominator must agree: {body}"
    );
    assert_eq!(field["ready"], json!(true), "{body}");
    // 1 byte per dimension per live document — the resident array itself.
    assert_eq!(
        field["codes_bytes"],
        json!((KEEP + WIDE_IDS.len()) * DIM),
        "{body}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. A document's _score and the filter — the reconciled contract
// ─────────────────────────────────────────────────────────────────────────────

/// The filter shape where #392's filter-independence holds exactly: the
/// filter removes only INTERIOR documents, every per-dimension bound of the
/// fitted codebook stays put, and the filtered query's per-query codec
/// reproduces the ingest-time codes bit for bit.
#[tokio::test]
async fn scores_do_not_depend_on_a_filter_that_keeps_the_fitted_range() {
    let (app, _dir) = app().await;
    create_and_index(&app).await;

    let interior = interior_ids();
    assert!(
        !interior.is_empty(),
        "the fixture needs interior documents to drop"
    );

    let unfiltered = knn(&app, None).await;
    let filtered = knn(
        &app,
        Some(json!({ "bool": { "must_not": [
        { "term": { "tag": "interior" } }
    ] } })),
    )
    .await;

    assert_eq!(unfiltered.len(), KEEP + WIDE_IDS.len());
    assert_eq!(
        filtered.len(),
        KEEP + WIDE_IDS.len() - interior.len(),
        "filter must remove exactly the interior documents"
    );

    let score_of = |hits: &[(String, f64)], id: &str| {
        hits.iter()
            .find(|(hit_id, _)| hit_id == id)
            .map(|(_, s)| *s)
            .unwrap_or_else(|| panic!("{id} missing"))
    };

    for (hit_id, score) in &filtered {
        let a = score_of(&unfiltered, hit_id);
        assert_eq!(
            *score, a,
            "doc {hit_id} scores {a} unfiltered but {score} filtered although \
             the filter kept every fitted bound — the codes path and the \
             per-query codec must agree bit for bit here"
        );
    }
}

/// The filter shape where the two references deliberately differ: removing
/// the wide documents narrows dimension 0's fitted range, the filtered
/// query's per-query codec requantizes onto the finer grid, and scores move
/// — but never by more than SQ8's reconstruction error.
#[tokio::test]
async fn a_filter_that_narrows_the_fitted_range_keeps_scores_within_the_quantization_step() {
    let (app, _dir) = app().await;
    create_and_index(&app).await;

    let unfiltered = knn(&app, None).await;
    let filtered = knn(&app, Some(json!({ "term": { "tag": "keep" } }))).await;

    assert_eq!(unfiltered.len(), KEEP + WIDE_IDS.len());
    assert_eq!(filtered.len(), KEEP, "filter must remove the wide docs");

    let score_of = |hits: &[(String, f64)], id: &str| {
        hits.iter()
            .find(|(hit_id, _)| hit_id == id)
            .map(|(_, s)| *s)
            .unwrap_or_else(|| panic!("{id} missing"))
    };

    // Measured on this fixture: max |Δ_score| 1e-7 (the two fits differ by
    // the wide docs' whole range on dimension 0, but that dimension's
    // contribution to the cosine is small). The bound asserted is the same
    // generous step-sized tolerance `codes_survive_a_restart` uses; the
    // pre-#392 write-once-codebook defect this family guards against
    // collapsed scores by ~1.0 and trips it loudly.
    let mut drift: f64 = 0.0;
    for i in 0..KEEP {
        let id = i.to_string();
        let a = score_of(&unfiltered, &id);
        let b = score_of(&filtered, &id);
        drift = drift.max((a - b).abs());
        assert!(
            (a - b).abs() < 1e-2,
            "doc {id} scores {a} unfiltered but {b} filtered — a filter that \
             narrows the fitted range may move a score by at most SQ8's \
             reconstruction error, not {drift}"
        );
    }
    assert!(drift < 1e-2, "drift must stay step-sized, got {drift}");
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. The code store is re-derived when the index reopens
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn codes_survive_a_restart() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;

    let before = {
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        let state = xerj_api::state::AppState::new(config.clone(), engine, metrics);
        let app = xerj_api::router::build_es_compat_router(state.clone());
        create_and_index(&app).await;
        let hits = knn(&app, None).await;
        state.engine.flush_all_force().await;
        hits
    };

    let (app, _keep) = {
        let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
        let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
        let state = xerj_api::state::AppState::new(config.clone(), engine, metrics);
        let app = xerj_api::router::build_es_compat_router(state.clone());
        // The open-time rebuild is background work; wait for it so the
        // assertion observes the codes path, not a mid-rebuild fallback.
        if let Ok(idx) = state.engine.get_index(INDEX) {
            idx.await_sq8_rebuilds().await;
        }
        (app, ())
    };

    let after = knn(&app, None).await;

    // Same neighbours in the same order: quantizing the same live vectors
    // under a codebook spanning the same per-dimension ranges reproduces the
    // ranking. Scores may shift by at most the SQ8 quantization step (the
    // re-fit walk re-encodes from the true f32 sources, while the live path
    // may have re-encoded through a decode), so ids/order are asserted
    // strictly and scores within a generous step-sized tolerance.
    assert_eq!(
        before.len(),
        after.len(),
        "restart must not lose documents: {before:?} vs {after:?}"
    );
    let order_before: Vec<&str> = before.iter().map(|(id, _)| id.as_str()).collect();
    let order_after: Vec<&str> = after.iter().map(|(id, _)| id.as_str()).collect();
    assert_eq!(
        order_before, order_after,
        "ranking changed across restart: {before:?} vs {after:?}"
    );
    for ((_, a), (_, b)) in before.iter().zip(after.iter()) {
        assert!(
            (a - b).abs() < 1e-2,
            "score for the same document moved from {a} to {b} across restart"
        );
    }

    // And the re-derived store is again serving-shape.
    let (status, body) = get(&app, &format!("/{INDEX}/_stats")).await;
    assert_eq!(status, StatusCode::OK);
    let field = &body["indices"][INDEX]["primaries"]["sq8"]["fields"]["v"];
    assert_eq!(field["ready"], json!(true), "{body}");
    assert_eq!(field["live"], json!(KEEP + WIDE_IDS.len()), "{body}");
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. Coverage broken → exact fallback, correct results
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn a_wrong_dimension_document_does_not_break_the_field() {
    let (app, _dir) = app().await;
    create_and_index(&app).await;

    // A document whose vector has the wrong dimensionality. The brute-force
    // scan has always skipped it (`doc_vec.len() != dim`); the code store
    // must not serve around it either — coverage breaks and queries fall
    // back to the exact path rather than returning wrong results.
    let (status, body) = json_req(
        &app,
        "PUT",
        &format!("/{INDEX}/_doc/broken"),
        json!({ "tag": "keep", "v": vec![0.5f32; DIM + 3] }),
    )
    .await;
    assert!(status.is_success(), "index broken: {status} {body}");
    let (status, body) = json_req(&app, "POST", &format!("/{INDEX}/_refresh"), json!({})).await;
    assert!(status.is_success(), "{status} {body}");

    let hits = knn(&app, Some(json!({ "term": { "tag": "keep" } }))).await;
    assert_eq!(
        hits.len(),
        KEEP,
        "the malformed doc must be skipped: {hits:?}"
    );
    assert!(
        !hits.iter().any(|(id, _)| id == "broken"),
        "malformed document must not appear in hits: {hits:?}"
    );
    // The control: doc 0 is the query vector and must still top the list.
    assert_eq!(hits[0].0, "0", "query-vector doc must rank first: {hits:?}");
    assert!(hits[0].1 > 0.99, "expected ~1.0, got {}", hits[0].1);
}

//! A `quantization: "scalar8"` field must score the vector the document
//! CURRENTLY holds — issue #371.
//!
//! Before the fix, the per-field SQ8 code store was populated write-once on
//! the first kNN that observed a document (`index.rs`, `if
//! !store.codes.contains_key(id)`). Nothing invalidated an entry, so once a
//! document had been scored its codes were frozen: overwrite its vector with
//! the exact negation and the quantized index kept returning it at cosine
//! 1.000000, with scores byte-identical to the query before the update, while
//! the identical unquantized index correctly dropped it. Wrong results,
//! silently, through a documented ES mapping option (`int8_hnsw`).
//!
//! These tests pin the observable from the outside, over real HTTP, in the
//! shape the issue reported it:
//!
//!  * a `PUT /{index}/_doc/{id}` that negates a vector must move that
//!    document out of the top of the result list on the `scalar8` index, not
//!    just on the full-precision control;
//!  * the same through `_bulk`, which is how every realistic re-embedding
//!    pipeline writes.
//!
//! The full-precision index is carried through every step as a control: it
//! establishes that the manipulation itself is sound, so a failure here
//! cannot be a test artifact. Both indices are asserted to agree on the
//! ranking *before* the update, which is also what proves the SQ8 store was
//! populated at all — a store that was never consulted could not go stale.
//!
//! Elasticsearch is referenced for wire semantics only. It is AGPL-3.0/
//! SSPL-1.0/Elastic-2.0 licensed and no code from it is reproduced here.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

const DIM: usize = 8;
const DOCS: usize = 20;

/// The one document the tests move. `[1,0,0,...]` before, its exact negation
/// `[-1,0,0,...]` after — true cosine 1.0 then -1.0 against the query, the
/// widest possible swing, so no threshold in here is delicate.
const MOVED: &str = "0";

async fn app() -> (axum::Router, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    (xerj_api::router::build_es_compat_router(state), dir)
}

async fn send(app: &axum::Router, req: Request<Body>) -> (StatusCode, Value) {
    let response = app.clone().oneshot(req).await.expect("response");
    let status = response.status();
    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("body");
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    (status, value)
}

async fn json_req(
    app: &axum::Router,
    method: &str,
    path: &str,
    body: Value,
) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method(method)
            .uri(path)
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .expect("request"),
    )
    .await
}

async fn get(app: &axum::Router, path: &str) -> (StatusCode, Value) {
    send(
        app,
        Request::get(path).body(Body::empty()).expect("request"),
    )
    .await
}

async fn ndjson(app: &axum::Router, path: &str, body: String) -> (StatusCode, Value) {
    send(
        app,
        Request::builder()
            .method("POST")
            .uri(path)
            .header("content-type", "application/x-ndjson")
            .body(Body::from(body))
            .expect("request"),
    )
    .await
}

/// The two indices under test: the quantized one and its full-precision
/// control, identical in every other respect (8-dim, default `cosine`).
const SQ8: &str = "sq8";
const EXACT: &str = "exact";

async fn create_pair(app: &axum::Router, sq8_field: Value) {
    for (index, field_def) in [
        (SQ8, sq8_field),
        (EXACT, json!({ "type": "dense_vector", "dims": DIM })),
    ] {
        let (status, body) = json_req(
            app,
            "PUT",
            &format!("/{index}"),
            json!({ "mappings": { "properties": { "v": field_def } } }),
        )
        .await;
        assert_eq!(status, StatusCode::OK, "create {index}: {body}");
    }
}

/// The document that takes the top slot once doc 0 is negated. Its cosine
/// against the query is 0.9939 against 0.4918 for the next filler doc, so the
/// post-update winner is unambiguous and SQ8's approximation error cannot
/// reorder it.
const RUNNER_UP: &str = "2";

/// Deterministic corpus.
///
///  * doc `0` is the query vector itself — cosine 1.0, the top hit;
///  * doc `1` is its negation. That also anchors the fitted SQ8 range for
///    dimension 0 at exactly -1, so doc 0's post-update code is representable
///    rather than clamped, and its decoded score is exactly 0.0;
///  * doc `2` is the clear runner-up (see [`RUNNER_UP`]);
///  * the rest are spread over `[-1,1]` by a prime-stride walk, all distinct
///    and all well below doc 2.
fn corpus_vector(i: usize) -> Vec<f32> {
    match i {
        0 => first_dim(1.0),
        1 => first_dim(-1.0),
        2 => {
            let mut v = vec![0.0f32; DIM];
            v[0] = 0.9;
            v[1] = 0.1;
            v
        }
        _ => (0..DIM)
            .map(|d| ((i * 37 + d * 101) % 199) as f32 / 99.0 - 1.0)
            .collect(),
    }
}

fn first_dim(x: f32) -> Vec<f32> {
    let mut v = vec![0.0f32; DIM];
    v[0] = x;
    v
}

fn negated() -> Vec<f32> {
    corpus_vector(0).iter().map(|x| -x).collect()
}

async fn index_corpus(app: &axum::Router, index: &str) {
    for i in 0..DOCS {
        let (status, body) = json_req(
            app,
            "PUT",
            &format!("/{index}/_doc/{i}"),
            json!({ "v": corpus_vector(i) }),
        )
        .await;
        assert!(status.is_success(), "index {index}/{i}: {status} {body}");
    }
    refresh(app, index).await;
}

async fn refresh(app: &axum::Router, index: &str) {
    let (status, body) = json_req(app, "POST", &format!("/{index}/_refresh"), json!({})).await;
    assert!(status.is_success(), "refresh {index}: {status} {body}");
}

/// `(id, score)` for the whole corpus, in hit order.
async fn knn(app: &axum::Router, index: &str) -> Vec<(String, f64)> {
    let (status, body) = json_req(
        app,
        "POST",
        &format!("/{index}/_search"),
        json!({
            "knn": {
                "field": "v",
                "query_vector": corpus_vector(0),
                "k": DOCS,
                "num_candidates": 100
            },
            // `size` defaults to 10 and caps the hit list independently of `k`.
            "size": DOCS,
            "_source": false
        }),
    )
    .await;
    assert!(status.is_success(), "knn on {index}: {status} {body}");
    let hits = body["hits"]["hits"]
        .as_array()
        .unwrap_or_else(|| panic!("no hits on {index}: {body}"));
    assert_eq!(hits.len(), DOCS, "expected the whole corpus back: {body}");
    hits.iter()
        .map(|h| {
            (
                h["_id"].as_str().expect("_id").to_string(),
                h["_score"].as_f64().expect("_score"),
            )
        })
        .collect()
}

fn score_of(hits: &[(String, f64)], id: &str) -> f64 {
    hits.iter()
        .find(|(hit_id, _)| hit_id == id)
        .unwrap_or_else(|| panic!("{id} missing from {hits:?}"))
        .1
}

/// Assert the corpus is in its pre-update shape on `index`: doc 0 is the query
/// vector, so it is the single best hit at cosine 1.0 (`_score` (1+cos)/2 = 1).
/// This is also what populates the SQ8 code store — without it there would be
/// no cached entry to go stale and the tests below would pass vacuously.
fn assert_top_before(index: &str, hits: &[(String, f64)]) {
    assert_eq!(
        hits[0].0, MOVED,
        "{index}: doc {MOVED} IS the query vector, it must rank first: {hits:?}"
    );
    assert!(
        hits[0].1 > 0.99,
        "{index}: doc {MOVED} must score ~1.0 before the update, got {}: {hits:?}",
        hits[0].1
    );
}

/// Assert the update landed in `_source` — the issue's step 3. If this fails
/// the write never happened and nothing below would mean anything.
async fn assert_source_negated(app: &axum::Router, index: &str) {
    let (status, body) = get(app, &format!("/{index}/_doc/{MOVED}")).await;
    assert!(status.is_success(), "get {index}/{MOVED}: {status} {body}");
    let stored: Vec<f64> = body["_source"]["v"]
        .as_array()
        .unwrap_or_else(|| panic!("no _source.v on {index}: {body}"))
        .iter()
        .map(|v| v.as_f64().expect("float"))
        .collect();
    let want: Vec<f64> = negated().iter().map(|x| *x as f64).collect();
    assert_eq!(stored, want, "{index}: _source did not take the update");
}

/// The assertion the bug fails: after the update, doc 0 holds the exact
/// negation of the query, so it must be scored on that vector.
fn assert_moved_out(index: &str, before: &[(String, f64)], after: &[(String, f64)]) {
    assert_ne!(
        after[0].0, MOVED,
        "{index}: doc {MOVED} now holds the NEGATION of the query vector and \
         must not be the top hit — it is being scored from a stale SQ8 code \
         (#371): {after:?}"
    );
    assert_eq!(
        after[0].0, RUNNER_UP,
        "{index}: doc {RUNNER_UP} (cosine 0.9939) must take the top slot once \
         doc {MOVED} is negated: {after:?}"
    );
    let moved = score_of(after, MOVED);
    assert!(
        moved < 0.1,
        "{index}: doc {MOVED} is the exact negation of the query (true cosine \
         -1, _score 0.0) but scored {moved}: {after:?}"
    );
    let before_scores: Vec<f64> = before.iter().map(|(_, s)| *s).collect();
    let after_scores: Vec<f64> = after.iter().map(|(_, s)| *s).collect();
    assert_ne!(
        before_scores, after_scores,
        "{index}: the score list is unchanged by a vector rewrite — the \
         ranking is frozen at first observation (#371)"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. `PUT /{index}/_doc/{id}` — the shape reported in #371
// ─────────────────────────────────────────────────────────────────────────────

#[tokio::test]
async fn sq8_scores_follow_a_document_update() {
    let (app, _dir) = app().await;
    create_pair(
        &app,
        json!({ "type": "dense_vector", "dims": DIM, "quantization": "scalar8" }),
    )
    .await;

    index_corpus(&app, SQ8).await;
    index_corpus(&app, EXACT).await;

    // Step 1 — query once, which is what populates the SQ8 code store.
    let sq8_before = knn(&app, SQ8).await;
    let exact_before = knn(&app, EXACT).await;
    assert_top_before(SQ8, &sq8_before);
    assert_top_before(EXACT, &exact_before);

    // Step 2/3 — overwrite doc 0 with its exact negation, and confirm it took.
    for index in [SQ8, EXACT] {
        let (status, body) = json_req(
            &app,
            "PUT",
            &format!("/{index}/_doc/{MOVED}"),
            json!({ "v": negated() }),
        )
        .await;
        assert!(status.is_success(), "update {index}: {status} {body}");
        refresh(&app, index).await;
        assert_source_negated(&app, index).await;
    }

    // Step 4 — the same query again.
    let sq8_after = knn(&app, SQ8).await;
    let exact_after = knn(&app, EXACT).await;

    // The control first: if the full-precision index does not move the
    // document either, the manipulation is wrong and the SQ8 failure below
    // would be meaningless.
    assert_moved_out(EXACT, &exact_before, &exact_after);
    assert_moved_out(SQ8, &sq8_before, &sq8_after);

    // The quantized index must not merely have moved doc 0 — it must land on
    // the same ordering the full-precision index does, to within SQ8 error.
    let sq8_order: Vec<&str> = sq8_after.iter().map(|(id, _)| id.as_str()).collect();
    let exact_order: Vec<&str> = exact_after.iter().map(|(id, _)| id.as_str()).collect();
    assert_eq!(
        sq8_order[..3],
        exact_order[..3],
        "quantized and exact indices disagree on the post-update top 3: \
         {sq8_after:?} vs {exact_after:?}"
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. `_bulk` — the path a re-embedding pipeline actually writes through
// ─────────────────────────────────────────────────────────────────────────────

/// #371 was reported against `PUT /_doc/{id}` and explicitly did not test
/// `_bulk`. `_bulk` is how vectors are rewritten in bulk after a model change,
/// which is the workload that makes this a blocker, so it gets its own pin.
/// The mapping is spelled `index_options.type: int8_hnsw` here — the
/// Elasticsearch spelling an ES user reaches for by default, and the one that
/// makes the defect reachable without ever typing "scalar8".
#[tokio::test]
async fn sq8_scores_follow_a_bulk_update() {
    let (app, _dir) = app().await;
    create_pair(
        &app,
        json!({
            "type": "dense_vector",
            "dims": DIM,
            "index_options": { "type": "int8_hnsw" }
        }),
    )
    .await;

    index_corpus(&app, SQ8).await;
    index_corpus(&app, EXACT).await;

    let sq8_before = knn(&app, SQ8).await;
    let exact_before = knn(&app, EXACT).await;
    assert_top_before(SQ8, &sq8_before);
    assert_top_before(EXACT, &exact_before);

    for index in [SQ8, EXACT] {
        let body = format!(
            "{}\n{}\n",
            json!({ "index": { "_index": index, "_id": MOVED } }),
            json!({ "v": negated() })
        );
        let (status, response) = ndjson(&app, "/_bulk?refresh=true", body).await;
        assert_eq!(status, StatusCode::OK, "bulk {index}: {response}");
        assert_eq!(
            response["errors"],
            json!(false),
            "bulk {index} reported errors: {response}"
        );
        refresh(&app, index).await;
        assert_source_negated(&app, index).await;
    }

    let sq8_after = knn(&app, SQ8).await;
    let exact_after = knn(&app, EXACT).await;
    assert_moved_out(EXACT, &exact_before, &exact_after);
    assert_moved_out(SQ8, &sq8_before, &sq8_after);
}

//! End-to-end checks for the local judge — `POST /v1/systemone` (native
//! router) and `POST /_decide` (ES-compat router) — over HTTP, against real
//! in-process indexes of labelled history.
//!
//! THE VOTE IS RETRIEVAL, NOT A MODEL. It is a weighted nearest-neighbour vote
//! over an index the test seeds, so every probability here is checkable
//! arithmetic. Nothing in this file says anything about judge-model quality —
//! that is measured in `benchmarks/beir-hybrid/results/`, not by these tests.
//!
//! The `systemone` tests speak the request/response shape TypeSafe documents
//! and `jev-reranker` sends, because that client — unmodified — is the
//! acceptance gate for this endpoint:
//!
//! ```text
//! request  { state: { query, documents: { doc_0: "...", ... } }, model,
//!            questions: { d0: { type: "noul",
//!                               instructions: "Is `documents.doc_0` relevant?" } } }
//! response { model, answers: { d0: { type: "noul", noul: 0..1 } }, usage }
//! ```
//!
//! Two deliberate wire breaks are asserted here too, so they cannot regress
//! into silence: `model` is echoed as this node's own id (never the requested
//! Jev name), and a question with zero support is a 422 naming the question —
//! never a fabricated 0.5.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use serde_json::{json, Value};
use tower::ServiceExt;

// ─────────────────────────────────────────────────────────────────────────────
// The node
// ─────────────────────────────────────────────────────────────────────────────

struct Node {
    /// The XERJ-native REST API (`/v1/...`): /v1/systemone, /v1/models.
    native: axum::Router,
    /// The ES-compat API: index creation, _search, /_decide.
    app: axum::Router,
    _dir: tempfile::TempDir,
}

/// A node whose `[decisions]` block names `index`. Empty string leaves the
/// endpoints unconfigured (503), which is itself under test.
async fn node_with_decisions(index: &str, positive_label: &str, min_confidence: f64) -> Node {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.decisions.index = index.to_string();
    config.decisions.positive_label = positive_label.to_string();
    config.decisions.min_confidence = min_confidence;
    let metrics = xerj_common::metrics::Metrics::new().expect("metrics");
    let engine = xerj_engine::Engine::new(config.clone()).expect("engine");
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    Node {
        native: xerj_api::router::build_native_router(state.clone()),
        app: xerj_api::router::build_es_compat_router(state),
        _dir: dir,
    }
}

/// The refund-history node: two `true` docs about refunds, one `false` doc
/// about shipping, so a refund question votes 1.0 and a shipping question 0.0
/// whatever the internal ordering — every neighbour of "refund …" is `true`.
async fn gate_node() -> Node {
    let node = node_with_decisions("history", "true", 0.0).await;
    seed(
        &node,
        "history",
        &[
            ("h1", "refund refund refund asked for money back", "true"),
            ("h2", "refund policy says money back", "true"),
            ("h3", "shipping delivery times", "false"),
        ],
    )
    .await;
    node
}

impl Node {
    async fn call(
        &self,
        router: &axum::Router,
        method: &str,
        path: &str,
        body: Value,
    ) -> (StatusCode, Value) {
        let response = router
            .clone()
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(path)
                    .header("content-type", "application/json")
                    .body(Body::from(body.to_string()))
                    .expect("request"),
            )
            .await
            .expect("response");
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        (
            status,
            serde_json::from_str(&String::from_utf8_lossy(&bytes)).unwrap_or(Value::Null),
        )
    }

    async fn systemone(&self, body: Value) -> (StatusCode, Value) {
        self.call(&self.native.clone(), "POST", "/v1/systemone", body)
            .await
    }
    async fn models(&self) -> (StatusCode, Value) {
        self.call(&self.native.clone(), "GET", "/v1/models", json!({}))
            .await
    }
    async fn decide(&self, body: Value) -> (StatusCode, Value) {
        self.call(&self.app.clone(), "POST", "/_decide", body).await
    }
}

/// Create an index of `text`/`label` documents and refresh it.
async fn seed(node: &Node, index: &str, docs: &[(&str, &str, &str)]) {
    let (st, b) = node
        .call(
            &node.app.clone(),
            "PUT",
            &format!("/{index}"),
            json!({"mappings": {"properties": {
                "text": {"type": "text"},
                "label": {"type": "keyword"}
            }}}),
        )
        .await;
    assert!(st.is_success(), "create {index}: {st} {b}");
    for (id, text, label) in docs {
        let (st, b) = node
            .call(
                &node.app.clone(),
                "PUT",
                &format!("/{index}/_doc/{id}"),
                json!({"text": text, "label": label}),
            )
            .await;
        assert!(st.is_success(), "index {index}/{id}: {st} {b}");
    }
    let (st, b) = node
        .call(
            &node.app.clone(),
            "POST",
            &format!("/{index}/_refresh"),
            json!({}),
        )
        .await;
    assert!(st.is_success(), "refresh {index}: {st} {b}");
}

fn reason(r: &Value) -> String {
    r["error"]["reason"]
        .as_str()
        .unwrap_or_default()
        .to_string()
}

