/// Plans a caller can name with `--plan`. The order is the tie-break: an
/// earlier plan wins when two that fit keep the same number of source bytes,
/// so `default` wins whenever it fits.
pub const PLAN_NAMES: &[&str] = &[
    "default",
    "skip-vendored",
    "skip-data",
    "code-and-docs",
    "no-vectors",
    "cap-1mb",
