                avail: 4_000,
            })
        );
        let mut missing = volume;
        missing.flood_stage = None;
        assert!(disk_budget(&missing).is_none());
        let mut no_total = volume;
        no_total.total = None;
        assert!(disk_budget(&no_total).is_none());
