        let wide = rendered
            .lines()
            .find(|l| l.contains("alpha beta"))
            .expect("a tab is a space");
        assert!(wide.starts_with('|'), "{wide}");
        assert!(wide.contains('…'), "a long example is capped: {wide}");
        assert!(!wide.contains(&"n".repeat(40)), "{wide}");
    }

