    #[test]
    fn prefix_scoping_disambiguates_hyphenated_prefixes_across_catalog_doc_kinds() {
        let tantivy_ds = json!({
            "doc_kind": "dataset",
            "slug": "code",
            "index_name": "xc-tantivy-code"
        });
        assert!(dataset_matches_prefix(&tantivy_ds, "xc-tantivy"));
        assert!(!dataset_matches_prefix(&tantivy_ds, "xc"));
        assert!(!dataset_matches_prefix(&tantivy_ds, "xc-tantivy-extra"));

        let xc_hyphen_slug_ds = json!({
            "doc_kind": "dataset",
            "slug": "tantivy-code",
            "index_name": "xc-tantivy-code"
        });
        assert!(dataset_matches_prefix(&xc_hyphen_slug_ds, "xc"));
        assert!(!dataset_matches_prefix(&xc_hyphen_slug_ds, "xc-tantivy"));

        // Legacy dataset doc without `slug` falls back to `{prefix}-` boundary.
        let legacy_ds = json!({
            "doc_kind": "dataset",
            "index_name": "ax-logs"
        });
        assert!(dataset_matches_prefix(&legacy_ds, "ax"));
        assert!(!dataset_matches_prefix(&legacy_ds, "ax2"));

        let corr = json!({
            "doc_kind": "correlation",
            "a_index": "xc-tantivy-code",
            "a_dataset": "code",
            "b_index": "xc-tantivy-symbols",
            "b_dataset": "symbols"
        });
        assert!(correlation_matches_prefix(&corr, "xc-tantivy"));
        assert!(!correlation_matches_prefix(&corr, "xc"));

        let file_with_prefix = json!({
            "doc_kind": "file",
            "prefix": "xc-tantivy",
            "path": "a.rs"
        });
        let file_with_scope_only = json!({
            "doc_kind": "file",
            CORPUS_SCOPE_FIELD: "xc-tantivy",
            "path": "b.rs"
        });
        assert!(file_matches_prefix(&file_with_prefix, "xc-tantivy"));
        assert!(!file_matches_prefix(&file_with_prefix, "xc"));
        assert!(file_matches_prefix(&file_with_scope_only, "xc-tantivy"));
    }
}

#[cfg(test)]
mod sample_query_tests {
    use super::*;
    use crate::infer::FieldSpec;

    fn spec(name: &str, es_type: &str, avg_len: f64, examples: &[&str]) -> FieldSpec {
        FieldSpec {
            name: name.into(),
            es_type: es_type.into(),
            date_enc: None,
            semantic: None,
            cardinality_est: 0,
            cardinality_overflow: false,
            null_ratio: 0.0,
            avg_len,
            coverage: 1.0,
            examples: examples.iter().map(|s| s.to_string()).collect(),
            notes: vec![],
            date_min: None,
            date_max: None,
            date_evidence: vec![],
            num_min: None,
            num_max: None,
        }
    }

    fn dataset(slug: &str, specs: Vec<FieldSpec>) -> PlanDataset {
        PlanDataset {
            slug: slug.into(),
            index: format!("ax-{slug}"),
            family: "document".into(),
            group: None,
            specs,
            time_field: None,
            semantic_field: None,
            text_analyzer: None,
            scope: None,
            sampled_records: 1,
            file_count: 1,
        }
    }

    /// A dataset carrying `defs` (the code extractor's per-symbol index —
    /// see `dataset.rs`) must get the code-aware bool shape: a `[body, defs]`
    /// `most_fields` query plus a self-gating `match_phrase` on `defs`, with
    /// `_source` projected and `_passage` requested instead of the whole file.
    #[test]
    fn code_dataset_with_defs_gets_a_code_aware_projected_passage_query() {
        let pd = dataset(
            "repo",
            vec![
                spec("title", "keyword", 8.0, &["main.rs"]),
                spec("body", "text", 400.0, &["fn main implementation body"]),
                spec("defs", "text", 20.0, &["function main"]),
            ],
        );
        let queries = build_sample_queries(&pd, &[]);
        let full_text = queries
            .iter()
            .find(|q| q["class"] == "full_text")
            .expect("a full_text sample query");
        let should = full_text["body"]["query"]["bool"]["should"]
            .as_array()
            .expect("code-aware query should have bool.should");
        assert_eq!(should.len(), 2);
        assert_eq!(should[0]["multi_match"]["fields"], json!(["body", "defs"]));
        assert_eq!(should[0]["multi_match"]["type"], "most_fields");
        assert_eq!(
            should[1]["match_phrase"]["defs"]["query"],
            should[0]["multi_match"]["query"]
        );
        // 4, not 8: measured identical to ^8 on the sealed holdout, better on
        // the smaller corpus, and it amplifies the single-word case least.
        assert_eq!(should[1]["match_phrase"]["defs"]["boost"], json!(4));
        assert_eq!(full_text["body"]["_source"], json!(["ax_path", "title"]));
        assert_eq!(full_text["body"]["fields"], json!(["_passage"]));
    }

    /// A dataset with no `defs` field (the overwhelming majority — plain
    /// data/text datasets) must keep the original single-field `match`
    /// shape unchanged: no `defs` reference, no forced projection.
    #[test]
    fn non_code_dataset_keeps_the_plain_single_field_match() {
        let pd = dataset(
            "logs",
            vec![spec(
                "message",
                "text",
                200.0,
                &["connection reset by peer"],
            )],
        );
        let queries = build_sample_queries(&pd, &[]);
        let full_text = queries
            .iter()
            .find(|q| q["class"] == "full_text")
            .expect("a full_text sample query");
        assert!(full_text["body"]["query"]["match"]["message"].is_string());
        assert!(full_text["body"]["query"].get("bool").is_none());
        assert!(full_text["body"]["query"].get("match_phrase").is_none());
        assert!(full_text["body"].get("_source").is_none());
        assert!(full_text["body"].get("fields").is_none());
    }

    /// #416 (data-loss): the shared `autoindex-catalog` index is written by
    /// every corpus, so its doc ids MUST be scoped by the corpus `--prefix` —
    /// otherwise two corpora indexing the same file key (or producing the same
    /// slug) overwrite each other's catalog entry. FAIL-BEFORE: dropping the
    /// prefix from the id bodies makes these `assert_ne!` collide.
    #[test]
    fn catalog_ids_are_prefix_scoped_across_corpora() {
        // Same key, different corpus prefix -> distinct ids (no overwrite).
        assert_ne!(super::file_id("ax-a", "k"), super::file_id("ax-b", "k"));
        assert_ne!(
            super::duplicate_file_id("ax-a", "k", "p", "pi"),
            super::duplicate_file_id("ax-b", "k", "p", "pi"),
        );
        // Idempotent within one corpus (a re-run must upsert, not duplicate).
        assert_eq!(super::file_id("ax-a", "k"), super::file_id("ax-a", "k"));
        // The prefix is actually in the id (not just concatenated key).
        assert!(super::file_id("ax-a", "k").starts_with("file:ax-a:"));
    }
}

#[cfg(test)]
mod prefix_reuse_tests {
    use super::*;

    fn run(prefix: &str, root: &str) -> Value {
        json!({"doc_kind": "run", "prefix": prefix, "root": root})
    }

    /// Same prefix, different folder: the earlier root is named, and the
    /// message says finalize retires `ds:<prefix>:<slug>` and that separately
    /// indexed repos collapse into `<prefix>-docs`.
    #[test]
    fn a_different_folder_under_the_same_prefix_is_named() {
        let runs = vec![
            run("ref", "/data/stockfish"),
            run("ref", "/data/stockfish"),
            run("ref-other", "/data/elsewhere"),
            json!({"doc_kind": "dataset", "prefix": "ref", "root": "/data/not-a-run"}),
        ];
        let foreign = foreign_prefix_roots(&runs, "ref", "/data/lucaschess");
        assert_eq!(foreign, vec!["/data/stockfish".to_string()]);
        let message = prefix_reuse_message("ref", "/data/lucaschess", &foreign, false);
        assert!(message.contains("this run: /data/lucaschess"), "{message}");
        assert!(message.contains("/data/stockfish"), "{message}");
        assert!(message.contains("ds:ref:<slug>"), "{message}");
        assert!(message.contains("ref-*"), "{message}");
        assert!(message.contains("ref-docs"), "{message}");
        assert!(message.contains("ds:ref:docs"), "{message}");
        assert!(message.contains("Nothing was written"), "{message}");
        assert!(message.contains("--replace-prefix"), "{message}");
        assert!(message.contains("Do not delete"), "{message}");
        let copy_at = message
            .find("--prefix lucaschess")
            .expect("the ready-to-copy command names a distinct prefix");
        let taken_at = message
            .find("--prefix ref already")
            .expect("the taken prefix is still named");
        let replace_at = message.find("--replace-prefix").expect("flag");
        assert!(
            copy_at < taken_at && copy_at < replace_at,
            "a distinct --prefix is the first remedy:\n{message}"
        );
        assert!(
            message.contains("xerj autoindex /data/lucaschess --prefix lucaschess"),
            "{message}"
        );
        assert!(
            !message.contains("/data/elsewhere"),
            "a sibling prefix is not this corpus: {message}"
        );
    }

    #[test]
    fn the_suggested_prefix_is_not_the_taken_one_and_the_path_is_quoted() {
        let message = prefix_reuse_message("ref", "/data/my folder", &["/data/old".into()], false);
        assert!(
            message.contains("xerj autoindex '/data/my folder' --prefix my-folder"),
            "{message}"
        );
        let digit = prefix_reuse_message("ref", "/data/2024", &["/data/old".into()], false);
        assert!(
            digit.contains("--prefix data-2024"),
            "a digit-leading folder name cannot be an index prefix, so the parent is used: {digit}"
        );
        assert!(
            !digit.contains("--prefix 2024\n") && !digit.contains("--prefix 2024 "),
            "{digit}"
        );
    }

    /// Re-running the same folder is not a collision, even when older run
    /// documents for that root are still in the catalog.
    #[test]
    fn the_same_folder_is_not_a_collision() {
        let runs = vec![run("ref", "/data/stockfish"), run("ref", "/data/stockfish")];
        assert!(foreign_prefix_roots(&runs, "ref", "/data/stockfish").is_empty());
    }

    /// After `--replace-prefix`, the new folder's run is the latest. Re-running
    /// that folder must not keep seeing the folder it replaced.
    #[test]
    fn the_latest_run_owns_the_prefix() {
        let runs = vec![
            json!({"doc_kind":"run","prefix":"ref","root":"/data/old","started":"2026-10-01T00:00:00Z"}),
            json!({"doc_kind":"run","prefix":"ref","root":"/data/new","started":"2026-10-02T00:00:00Z"}),
        ];
        assert!(foreign_prefix_roots(&runs, "ref", "/data/new").is_empty());
        assert_eq!(
            foreign_prefix_roots(&runs, "ref", "/data/old"),
            vec!["/data/new".to_string()]
        );
    }

    /// A run that never recorded its root cannot be proved to be this folder.
    #[test]
    fn a_run_with_no_root_is_a_collision() {
        let runs = vec![json!({"doc_kind": "run", "prefix": "ref"})];
        assert_eq!(
            foreign_prefix_roots(&runs, "ref", "/data/stockfish"),
            vec![UNRECORDED_PREFIX_ROOT.to_string()]
        );
    }

    #[test]
    fn the_same_folder_under_another_prefix_is_named() {
        let runs = vec![
            json!({"doc_kind": "run", "prefix": "ax", "root": "/data/proj", "started": "2026-01-01T00:00:00Z"}),
            json!({"doc_kind": "run", "prefix": "ax", "root": "/data/old", "started": "2026-02-01T00:00:00Z"}),
            json!({"doc_kind": "run", "prefix": "proj", "root": "/data/proj", "started": "2026-03-01T00:00:00Z"}),
        ];
        assert_eq!(
            other_prefixes_for_root(&runs, "/data/proj", "proj"),
            vec!["ax".to_string()]
        );
        let line = same_root_other_prefix_line("proj", &["ax".into()]);
        assert!(line.contains("under ax"), "{line}");
        // `ax` also holds /data/old here, so a delete hint would destroy a
        // folder this run never touched (#2114).
        assert!(!line.contains("DELETE"), "{line}");
        assert!(line.contains("--prefix ax"), "{line}");
        assert_eq!(
            other_prefixes_for_root(&runs, "/data/proj", "ax"),
            vec!["proj".to_string()]
        );
    }

    #[test]
    fn replace_prefix_says_the_run_continues() {
        let message = prefix_reuse_message("ref", "/data/new", &["/data/old".into()], true);
        assert!(message.contains("--replace-prefix is set"), "{message}");
        assert!(message.contains("this run continues"), "{message}");
        assert!(!message.contains("Nothing was written"), "{message}");
        assert!(
            !message.contains("Ready to copy"),
            "the opt-in warning is not the refusal's first remedy: {message}"
        );
    }
}

//! Hand-rolled arg parser (house style of xerj-server — no clap).

use crate::gate::{Approval, DEFAULT_MAX_MINUTES};
use crate::ignore_rules::IgnoreOptions;
use crate::progress::ProgressMode;
use std::path::PathBuf;
use std::time::Duration;
// Loopback guard + local admin-key discovery, shared with `xerj mcp` (which
// hit the identical 401 failure mode, #961). The invariants — a false
// positive on `url_is_loopback` is a credential leak, not a cosmetic bug —
// are pinned by the `local admin-key discovery` tests at the bottom of this
// file: they stayed here when the helpers moved to `xerj-common`, so they
// are the shared helpers' tests wherever the helpers live.
use xerj_common::localauth::{discover_local_admin_key_for_url, url_is_loopback};

/// Largest `--max-minutes` accepted: one week. Past that the flag is a typo,
/// and `--max-minutes 0` already exists to mean "never ask".
pub const MAX_MAX_MINUTES: u64 = 7 * 24 * 60;

/// Largest `--debounce` accepted: one minute. A quiet period longer than that
/// is not debouncing, it is a timer — and `xerj autoindex` on a cron schedule
/// already is one, without holding watches open.
pub const MAX_DEBOUNCE_MS: u64 = 60_000;

/// Largest `--bulk-mb` accepted. Past this a single bulk body stops being a
/// unit of work and starts being a memory incident on the server.
pub const MAX_BULK_MB: usize = 24;

#[derive(Debug, Clone)]
pub struct IndexCfg {
    /// The positional argument: a folder, or `s3://bucket/prefix` /
    /// `r2://bucket/prefix`. An object URL is turned into the local mirror the
    /// run walks by [`crate::objsource::prepare`], which rewrites this field —
    /// everything after that point sees a path, exactly as it did before object
    /// storage existed.
    pub root: PathBuf,
    /// `--endpoint-url`: the S3-compatible endpoint to talk to (MinIO, Ceph,
    /// R2, localstack). Falls back to `AWS_ENDPOINT_URL_S3` then
    /// `AWS_ENDPOINT_URL`. Meaningless for a folder, and refused there rather
    /// than ignored.
    pub endpoint_url: Option<String>,
    pub url: String,
    pub api_key: Option<String>,
    /// Set only when `api_key` was discovered on disk rather than supplied by
    /// the user, so completion hints can reference the file instead of
    /// printing the secret into output people paste into bug reports.
    pub api_key_file: Option<PathBuf>,
    /// Phase-B index workers (concurrent bulk senders).
    pub workers: usize,
    /// Phase-A scan pool width (content hashing, sniffing, sampling). Both come
    /// from `--workers`; they differ only when the memory safe zone cannot pay
    /// for as many in-flight bulk buffers as the machine has cores.
    pub scan_workers: usize,
    pub pdf_workers: usize,
    /// What the machine forced on this run, printed once at start-up.
    pub resource_notes: Vec<String>,
    /// #768: the `XERJ_URL`-ignored safety note (set when `XERJ_URL` is present
    /// but `--url` was not passed). Carried separately from `resource_notes`
    /// because it is a safety warning, not routine progress chatter: the index
    /// path emits it through `pr.warn` (which, unlike `pr.note`, is not silenced
    /// by `--quiet`/`Surface::Silent`, yet stays a well-formed event on
    /// `--progress json`) and mirrors it into the `--json` result. `map`/`status`
    /// carry the same note but `eprintln` it, having no progress surface.
    pub xerj_url_note: Option<String>,
    pub pdf_timeout_secs: u64,
    pub bulk_mb: usize,
    pub bulk_timeout_secs: u64,
    pub snapshot_max_bytes: u64,
    pub prefix: String,
    /// #1845: set when `--prefix` was rewritten on the way to `prefix` (a
    /// trailing `-`/`_`, a `_`, a repeated separator, upper case). Said out loud
    /// through `pr.warn` because the rewrite is exactly what makes sibling
    /// projects collide under a `<prefix>-*` wildcard.
    pub prefix_note: Option<String>,
    /// `--replace-prefix`: this folder may take over a prefix whose catalog
    /// runs were indexed from a different root. Off by default; without it
    /// that run is refused before anything is written.
    pub replace_prefix: bool,
    pub state_dir: Option<PathBuf>,
    pub fresh: bool,
    pub follow_symlinks: bool,
    /// `--follow-symlinks-outside-root`: waive the root boundary for followed
    /// links. The hidden-name rule still applies to whatever they resolve to.
    pub follow_symlinks_outside_root: bool,
    /// `--stub <glob>` patterns: matching files are indexed as one
    /// existence-only name card, contents never opened.
    pub stub_globs: Vec<String>,
    /// `.gitignore` / `.xerjignore` / built-in build-output rules (#276).
    /// `deep_count` is set from `--dry-run` (and from `--walk-only`, which
    /// implies it).
    pub ignore: IgnoreOptions,
    /// Whole-file size cap in BYTES for non-streaming families (JSON, HTML,
    /// prose, PDF, …). Streaming families are never capped. Set on the CLI by
    /// any one of `--max-file-gb` / `--max-file-mb` / `--max-file-bytes`
    /// (mutually exclusive), all normalised to bytes here so a sub-GB cap —
    /// e.g. a 10 MB source-watcher budget (#1233) — is expressible. Default
    /// 2 GB.
    pub max_file_bytes: u64,
    pub sample: usize,
    pub no_semantic: bool,
    /// `--code-analyzer` (#1198): `code` declares the built-in identifier-aware
    /// analyzer on newly created datasets that hold source code.
    pub code_analyzer: crate::infer::CodeAnalyzer,
    /// Second-brain name; None derives it from the root folder basename.
    pub brain: Option<String>,
    /// Disable edge detection entirely (no `.xerj-memory-*-edges` writes).
    pub no_graph: bool,
    pub dry_run: bool,
    /// `--walk-only`: print the per-folder walk summary and return before
    /// hashing. The parser also sets [`Self::dry_run`], so nothing is indexed.
    /// `--dry-run` without this flag still hashes, sniffs and prints the plan.
    pub walk_only: bool,
    /// Stop and ask before indexing when phase A's measured estimate exceeds
    /// this many minutes. `0` disables the gate outright.
    pub max_minutes: u64,
    /// An answer to a previous decision request. `None` means "nobody has
    /// answered yet", which is what arms the gate.
    pub approve: Option<Approval>,
    /// `--max-index-size`, in bytes. `None` means the only budget is the free
    /// space under the node's flood-stage watermark, when the node reports one.
    pub max_index_bytes: Option<u64>,
    /// `--plan`. `None` means the default plan, which is indexed when it fits
    /// and refused when it does not. A named plan runs even when the estimate
    /// says it does not fit (with a warning): that is the override.
    pub budget_plan: Option<String>,
    /// `--drop-indexed`. Confirms that a reduced plan may delete files it
    /// leaves out when those files are already indexed. Without it that
    /// re-run exits 4 and lists them. `--plan` and `--yes` do not set this.
    pub drop_indexed: bool,
    pub json: bool,
    pub quiet: bool,
    /// Progress surface. Orthogonal to `json`: `--json` shapes *stdout* (the
    /// result), `--progress` shapes *stderr* (liveness).
    pub progress: ProgressMode,
    /// Progress cadence. `None` means "the surface's default" — 1 s on a
    /// terminal, 5 s for a pipe.
    pub progress_interval: Option<Duration>,
    /// `--label <question-set.json>`: run every extracted record's payload
    /// through the node's `POST /_decide` at ingest and stamp `label` /
    /// `label_p` (plus per-question `label_<id>` / `label_<id>_p`) onto the
    /// document (#1062). `None` — the default — never constructs a Labeler.
    pub label: Option<PathBuf>,
    /// `--watch`: after the first pass, stay resident and reindex what changes.
    pub watch: bool,
    /// `--watch`'s quiet period. One editor save is several filesystem events,
    /// so a pass waits for the tree to go quiet for this long before running.
    pub debounce: Duration,
    /// Root-relative paths dropped after the walk. Empty for a normal
    /// `xerj autoindex <folder>`. `xerj corpus index` sets `corpus.json` so
    /// the hub manifest is not indexed as a document dataset.
    pub exclude_rels: Vec<String>,
    /// `xerj corpus index` only (#1985): skip data files (CSV/HDF/simulation
    /// output — see [`crate::CORPUS_DATA_EXTS`]) instead of indexing them as
    /// records. `--include-data` turns it off. Never set by
    /// `xerj autoindex <folder>`: a user's own project may want its data.
    pub skip_corpus_data: bool,
}

#[derive(Debug, Clone)]
pub struct MapCfg {
    pub url: String,
    pub api_key: Option<String>,
    /// Explicit `--prefix` filter (`None` when the user did not pass `--prefix`,
    /// preserving the #971 multi-corpus view on a bare `autoindex map`).
    pub prefix: Option<String>,
    pub json: bool,
    pub dataset: Option<String>,
    /// `--offset` for the map's per-dataset field detail. The summary table
    /// always lists every dataset.
    pub detail_offset: usize,
    /// `--limit` for that detail page. `None` uses the default page when
    /// there are more datasets than [`crate::catalog::MAP_DETAIL_PAGE`].
    pub detail_limit: Option<usize>,
    /// A startup note when `XERJ_URL` was set but ignored (endpoint comes from
    /// `--url` only). `map` reads the catalog, so a stale var shows the wrong
    /// node's map without a word — same trap as the index path, read side.
    pub xerj_url_note: Option<String>,
}

#[derive(Debug, Clone)]
pub struct StatusCfg {
    pub url: String,
    pub api_key: Option<String>,
    pub prefix: String,
    pub state_dir: Option<PathBuf>,
    /// See [`MapCfg::xerj_url_note`]: `status` queries the same endpoint, so a
    /// set-but-ignored `XERJ_URL` would report the wrong node's progress.
    pub xerj_url_note: Option<String>,
}

/// `xerj autoindex remove --prefix P [--root DIR]`.
///
/// Deletes one autoindexed folder after printing the plan. `--prefix` is
/// required: the default name `ax` is shared, and guessing it is how an agent
/// deletes another project's index. `--yes` confirms. It does not choose a
/// folder when the prefix holds more than one.
#[derive(Debug, Clone)]
pub struct RemoveCfg {
    pub url: String,
    pub api_key: Option<String>,
    pub prefix: String,
    pub root: Option<String>,
    pub yes: bool,
    /// Accepted. Stdout is the JSON plan either way.
    pub json: bool,
    pub quiet: bool,
    pub xerj_url_note: Option<String>,
    /// When set, `remove` also deletes `journal.ndjson` here. The default
    /// journal for the selected folder is deleted either way.
    pub state_dir: Option<PathBuf>,
}

/// `xerj autoindex s3://bucket/prefix --watch`: poll a bucket and emit a change
/// feed. Deliberately its own config rather than fields on [`IndexCfg`]: the
/// watch path shares no phase-A/phase-B machinery with folder indexing, and
/// bolting its flags onto the index config is what makes an accepted-and-ignored
/// flag possible.
#[derive(Debug, Clone)]
pub struct WatchCfg {
    /// `s3://bucket/prefix` as the user wrote it.
    pub url: String,
    /// Endpoint that serves the bucket (`--endpoint-url`, else
    /// `AWS_ENDPOINT_URL`, else AWS's regional endpoint).
    pub endpoint: Option<String>,
    /// `--region`, else `AWS_REGION`, else `auto` (which is what R2 wants).
    pub region: String,
    pub poll_interval: Duration,
    /// `None` = until stopped.
    pub max_cycles: Option<u64>,
    /// Fetch bytes of changed objects to digest them. `--no-fetch` turns every
    /// GET off: metadata-only change detection, zero Class B operations.
    pub fetch: bool,
    pub max_object_bytes: u64,
    pub append_only: bool,
    pub max_monthly_ops: u64,
    /// Class B (GET) budget per calendar month.
    pub max_monthly_gets: u64,
    pub allow_cost: bool,
    pub page_size: u64,
    pub state_dir: Option<PathBuf>,
    pub fresh: bool,
    /// JSONL change feed destination. `None` = stdout.
    pub events_out: Option<PathBuf>,
    pub status_file: Option<PathBuf>,
    /// One cycle, no fetches, nothing emitted: measure what the poll costs.
    pub dry_run: bool,
    pub json: bool,
    pub quiet: bool,
}

#[derive(Debug)]
pub enum Cmd {
    /// Boxed: `IndexCfg` is an order of magnitude larger than the other
    /// variants, so inlining it made every `Cmd` — including `Help` — pay for
    /// it (`clippy::large_enum_variant`).
    Index(Box<IndexCfg>),
    Map(MapCfg),
    Status(StatusCfg),
    Remove(RemoveCfg),
    /// Boxed for the same reason as `Index`.
    Watch(Box<WatchCfg>),
    Help,
}

/// Object-storage URL schemes the watcher understands. `r2://` is accepted as a
/// spelling of `s3://` because Cloudflare R2 IS the S3 API — it is the endpoint
/// that differs, not the protocol.
pub const OBJECT_URL_SCHEMES: [&str; 2] = ["s3://", "r2://"];

pub fn looks_like_object_url(arg: &str) -> bool {
    OBJECT_URL_SCHEMES.iter().any(|s| arg.starts_with(s))
}

/// Largest `--poll-interval` accepted: one day. Past that a watch is a cron job.
pub const MAX_POLL_INTERVAL_SECS: u64 = 86_400;

