    fn index(args: &[&str]) -> super::IndexCfg {
        match parse(args.iter().map(|s| s.to_string()).collect()).unwrap() {
            Cmd::Index(cfg) => *cfg,
            other => panic!("expected index config, got {other:?}"),
        }
