/// §8.1 — all five bodies verbatim; the wikilink byte offsets in §8.2 are
/// offsets into these exact strings.
fn write_fixture(dir: &Path) {
    fs::write(
        dir.join("alpha.md"),
        "Alpha is the hub note. It links to [[beta]] and [[gamma]].",
    )
    .unwrap();
    fs::write(
        dir.join("beta.md"),
        "Beta continues the thread and references [[gamma]].",
    )
    .unwrap();
    fs::write(
        dir.join("gamma.md"),
        "Gamma is the sink note with no outgoing links.",
    )
    .unwrap();
    fs::write(dir.join("delta.md"), "Delta cites [[alpha]] as its source.").unwrap();
    fs::write(dir.join("epsilon.md"), "Epsilon stands alone.").unwrap();
}

pub(super) fn journal_graph_summary(state_dir: &Path) -> Value {
    let journal = fs::read_to_string(state_dir.join("journal.ndjson")).unwrap();
    journal
        .lines()
        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
        .rfind(|v| v.get("kind").and_then(Value::as_str) == Some("finish"))
        .and_then(|v| v.pointer("/summary/graph").cloned())
        .expect("finish event with graph summary")
}

/// Comparable edge shape: everything the contract §8.3 table pins for
/// autoindex output (node-id derivation included via the live anchors).
#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
struct EdgeKey {
    src: String,
    dst: String,
    edge_type: String,
    detector: String,
    weight: String,
    confidence: String,
    src_file: String,
    quote: String,
    offset: u64,
    src_format: String,
    dst_format: String,
}

fn edge_keys(edges: &BTreeMap<String, Value>) -> Vec<EdgeKey> {
    let mut out: Vec<EdgeKey> = edges
        .iter()
        .filter(|(id, _)| id.as_str() != detect::BRAIN_META_ID)
        .map(|(id, s)| {
            // Identity discipline: _id == edge_id field == the §2.3 hash.
            assert_eq!(s["edge_id"].as_str().unwrap(), id);
            assert_eq!(
                detect::edge_id(
                    s["src"].as_str().unwrap(),
                    s["type"].as_str().unwrap(),
                    s["dst"].as_str().unwrap(),
                    s["valid_at"].as_i64().unwrap(),
                ),
                id.as_str()
            );
            assert_eq!(s["schema_version"], json!(1));
            EdgeKey {
                src: s["src"].as_str().unwrap().into(),
                dst: s["dst"].as_str().unwrap().into(),
                edge_type: s["type"].as_str().unwrap().into(),
                detector: s["detector"].as_str().unwrap().into(),
                weight: s["weight"].to_string(),
                confidence: s["confidence"].to_string(),
                src_file: s["src_file"].as_str().unwrap().into(),
                quote: s["evidence"]["quote"].as_str().unwrap().into(),
                offset: s["evidence"]["offset"].as_u64().unwrap(),
                src_format: s["src_format"].as_str().unwrap_or("").into(),
                dst_format: s["dst_format"].as_str().unwrap_or("").into(),
            }
        })
        .collect();
    out.sort();
    out
}

/// `src_map`/`dst_map` pick the endpoint node per edge semantics: authored
/// text edges (wikilink) START at the section holding the evidence and LAND on
/// the target's file card; structural samedir edges connect card to card.
#[allow(clippy::too_many_arguments)]
fn expect(
    src_map: &HashMap<String, String>,
    dst_map: &HashMap<String, String>,
    src_rel: &str,
    dst_rel: &str,
    edge_type: &str,
    detector: &str,
    weight: &str,
    confidence: &str,
    quote: &str,
    offset: u64,
) -> EdgeKey {
    EdgeKey {
        src: src_map[src_rel].clone(),
        dst: dst_map[dst_rel].clone(),
        edge_type: edge_type.into(),
        detector: detector.into(),
        weight: weight.into(),
        confidence: confidence.into(),
        src_file: src_rel.into(),
        quote: quote.into(),
        offset,
        src_format: "md".into(),
        dst_format: "md".into(),
    }
}

/// The @2 opening edge of every text file's reading chain: card → section 0.
fn expect_opener(
    anchors: &HashMap<String, String>,
    sections: &HashMap<String, String>,
    rel: &str,
) -> EdgeKey {
    EdgeKey {
        src: anchors[rel].clone(),
        dst: sections[rel].clone(),
        edge_type: "sequence".into(),
        detector: "sequence@2".into(),
        weight: "0.8".into(),
        confidence: "0.99".into(),
        src_file: rel.into(),
        quote: format!("section 0 opens {rel}"),
        offset: 0,
        src_format: "md".into(),
        dst_format: "md".into(),
    }
}

#[test]
fn fixture_folder_end_to_end_matches_the_contract_edge_set() {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    write_fixture(corpus.path());
    let es = MockEs::start();

    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        0
    );

    let anchors = es.anchors();
    assert_eq!(anchors.len(), 5, "five file-card anchor nodes");
    let sections = es.nodes_at("s0");
    assert_eq!(sections.len(), 5, "five s0 section nodes");
    for rel in anchors.keys() {
        assert_ne!(
            anchors[rel], sections[rel],
            "card and first section are distinct nodes"
        );
    }
    let edges = es.index(EDGES_INDEX);
    assert!(
        edges.contains_key(detect::BRAIN_META_ID),
        "brain meta doc must exist"
    );
    let meta = &edges[detect::BRAIN_META_ID];
    assert_eq!(meta["brain"], json!("notes"));
    assert_eq!(meta["meta_version"], json!(1));
    assert!(meta["nodes_index"].as_str().unwrap().starts_with("ax-"));

    let alpha_line = "Alpha is the hub note. It links to [[beta]] and [[gamma]].";
    let mut expected = vec![
        // §8.2/§8.3 wikilink edges — exact quotes and byte offsets.
        expect(
            &sections,
            &anchors,
            "alpha.md",
            "beta.md",
            "wikilink",
            "wikilink@2",
            "1.0",
            "0.95",
            alpha_line,
            35,
        ),
        expect(
            &sections,
            &anchors,
            "alpha.md",
            "gamma.md",
            "wikilink",
            "wikilink@2",
            "1.0",
            "0.95",
            alpha_line,
            48,
        ),
        expect(
            &sections,
            &anchors,
            "beta.md",
            "gamma.md",
            "wikilink",
            "wikilink@2",
            "1.0",
            "0.95",
            "Beta continues the thread and references [[gamma]].",
            41,
        ),
        expect(
            &sections,
            &anchors,
            "delta.md",
            "alpha.md",
            "wikilink",
            "wikilink@2",
            "1.0",
            "0.95",
            "Delta cites [[alpha]] as its source.",
            12,
        ),
        // §8.3 samedir chain over rel-sorted files — 4 edges, not a clique.
        expect(
            &anchors,
            &anchors,
            "alpha.md",
            "beta.md",
            "same_dir",
            "samedir@2",
            "0.3",
            "0.4",
            "alpha.md and beta.md share directory .",
            0,
        ),
        expect(
            &anchors,
            &anchors,
            "beta.md",
            "delta.md",
            "same_dir",
            "samedir@2",
            "0.3",
            "0.4",
            "beta.md and delta.md share directory .",
            0,
        ),
        expect(
            &anchors,
            &anchors,
            "delta.md",
            "epsilon.md",
            "same_dir",
            "samedir@2",
            "0.3",
            "0.4",
            "delta.md and epsilon.md share directory .",
            0,
        ),
        expect(
            &anchors,
            &anchors,
            "epsilon.md",
            "gamma.md",
            "same_dir",
            "samedir@2",
            "0.3",
            "0.4",
            "epsilon.md and gamma.md share directory .",
            0,
        ),
        // sequence@2 opening edges: every file's card starts its reading
        // chain (single-section notes have exactly the opener).
        expect_opener(&anchors, &sections, "alpha.md"),
        expect_opener(&anchors, &sections, "beta.md"),
        expect_opener(&anchors, &sections, "delta.md"),
        expect_opener(&anchors, &sections, "epsilon.md"),
        expect_opener(&anchors, &sections, "gamma.md"),
    ];
    expected.sort();
    assert_eq!(edge_keys(&edges), expected, "the exact §8.3 edge set");

    let g = journal_graph_summary(state.path());
    assert_eq!(g["edges_written"], json!(13));
    assert_eq!(g["by_detector"]["wikilink@2"], json!(4));
    assert_eq!(g["by_detector"]["samedir@2"], json!(4));
    assert_eq!(g["by_detector"]["sequence@2"], json!(5));
    assert_eq!(g["edges_unresolved"], json!(0));
    assert_eq!(g["edges_ambiguous"], json!(0));
    assert_eq!(g["edges_self_dropped"], json!(0));
    assert_eq!(g["edges_invalidated"], json!(0));

    // Determinism (§6.4): a fresh re-run over the unchanged corpus overwrites
    // every edge in place — byte-identical modulo created_at.
    let strip_created = |m: &BTreeMap<String, Value>| -> BTreeMap<String, Value> {
        m.iter()
            .map(|(id, s)| {
                let mut s = s.clone();
                if let Some(o) = s.as_object_mut() {
                    o.remove("created_at");
                }
                (id.clone(), s)
            })
            .collect()
    };
    let first = strip_created(&edges);
    let state2 = tempfile::tempdir().unwrap();
    assert_eq!(
        crate::run_index(cfg(corpus.path(), state2.path(), &es.url)).unwrap(),
        0
    );
    assert_eq!(
        strip_created(&es.index(EDGES_INDEX)),
        first,
        "re-run must converge on the identical edge set"
    );
}

/// The corpus-wide pass, end to end: documents that never cite each other and
/// do not even share a directory are linked by the words only they use — and
/// the edge lands in the edges index carrying those words as its evidence.
/// `detect_corpus` runs after Phase B, so this is also the proof that the
/// third detection phase is wired into the pipeline at all.
#[test]
fn shared_vocabulary_links_documents_that_cite_nothing() {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    // Two recipes in different folders: no link, no shared directory, one
    // shared distinctive vocabulary.
    fs::create_dir(corpus.path().join("bread")).unwrap();
    fs::create_dir(corpus.path().join("pickles")).unwrap();
    fs::create_dir(corpus.path().join("admin")).unwrap();
    fs::write(
        corpus.path().join("bread/sourdough.md"),
        "The starter ferments overnight. Lactobacillus and wild yeast do the \
         work; the note on hydration is filed.",
    )
    .unwrap();
    fs::write(
        corpus.path().join("pickles/kimchi.md"),
        "Cabbage ferments in brine. Lactobacillus again, and the note says \
         three days.",
    )
    .unwrap();
    // Ten unrelated documents: enough corpus for "distinctive" to mean
    // something (the 10% rule), and everyday words in all of them.
    for i in 0..10 {
        fs::write(
            corpus.path().join(format!("admin/memo{i:02}.md")),
            format!("The note was filed. Item unique{i:02} is recorded."),
        )
        .unwrap();
    }
    let es = MockEs::start();
    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        0
    );

    let anchors = es.anchors();
    let edges = es.index(EDGES_INDEX);
    let shared: Vec<&Value> = edges
        .values()
        .filter(|s| s["type"] == json!("shared_term"))
        .collect();
    assert_eq!(
        shared.len(),
        1,
        "exactly one vocabulary link, between the two recipes: {shared:#?}"
    );
    let e = shared[0];
    assert_eq!(e["detector"], json!("sharedterm@1"));
    assert_eq!(e["weight"], json!(0.45));
    assert_eq!(e["confidence"], json!(0.5));
    assert_eq!(e["src"], json!(anchors["bread/sourdough.md"]));
    assert_eq!(e["dst"], json!(anchors["pickles/kimchi.md"]));
    assert_eq!(e["src_file"], json!("bread/sourdough.md"));
    let quote = e["evidence"]["quote"].as_str().unwrap();
    assert!(
        quote.contains("lactobacillus") && quote.contains("ferments"),
        "the shared terms must be inspectable on the edge: {quote}"
    );
    assert!(
        !quote.contains("note") && !quote.contains("filed"),
        "words the whole corpus uses are not evidence of anything: {quote}"
    );

    let g = journal_graph_summary(state.path());
    assert_eq!(g["by_detector"]["sharedterm@1"], json!(1));
    assert_eq!(g["edges_capped"], json!(0), "nothing hit the density cap");

    // Same corpus, fresh run: the vocabulary edge is byte-identical, so a
    // re-run converges instead of accumulating beliefs.
    let state2 = tempfile::tempdir().unwrap();
    assert_eq!(
        crate::run_index(cfg(corpus.path(), state2.path(), &es.url)).unwrap(),
        0
    );
    let after: Vec<Value> = es
        .index(EDGES_INDEX)
        .values()
        .filter(|s| s["type"] == json!("shared_term"))
        .cloned()
        .collect();
    assert_eq!(after.len(), 1, "the re-run overwrote in place");
    assert_eq!(after[0]["evidence"]["quote"], json!(quote));
}

#[test]
fn dangling_wikilink_is_counted_not_silently_dropped() {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    fs::write(
        corpus.path().join("zeta.md"),
        "Zeta links [[nowhere]] and [[eta]].",
    )
    .unwrap();
    fs::write(corpus.path().join("eta.md"), "Eta stands alone.").unwrap();
    let es = MockEs::start();

    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        0
    );

    let edges = es.index(EDGES_INDEX);
    let keys = edge_keys(&edges);
    let mut by_type: BTreeMap<(&str, &str), u64> = BTreeMap::new();
    for k in &keys {
        *by_type
            .entry((k.edge_type.as_str(), k.detector.as_str()))
            .or_default() += 1;
    }
    // One resolved wikilink + one samedir chain edge + two sequence openers
    // (card → s0, one per file); [[nowhere]] must not fabricate an edge…
    assert_eq!(
        by_type,
        BTreeMap::from([
            (("same_dir", "samedir@2"), 1),
            (("sequence", "sequence@2"), 2),
            (("wikilink", "wikilink@2"), 1),
        ])
    );
    // …but it must not vanish either: it is a dangling-link fact of record.
    let g = journal_graph_summary(state.path());
    assert_eq!(g["edges_unresolved"], json!(1));
    assert_eq!(g["edges_written"], json!(4));
}

#[test]
fn replaced_file_soft_invalidates_its_prior_edges() {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    fs::write(
        corpus.path().join("alpha.md"),
        "Alpha cites [[beta]] today.",
    )
    .unwrap();
    fs::write(corpus.path().join("beta.md"), "Beta stands alone.").unwrap();
    let es = MockEs::start();
    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        0
    );
    let before = es.index(EDGES_INDEX);
    let old_wikilink: Vec<String> = before
        .iter()
        .filter(|(_, s)| s["type"] == json!("wikilink"))
        .map(|(id, _)| id.clone())
        .collect();
    assert_eq!(old_wikilink.len(), 1);

    // Rewrite alpha at a strictly later mtime-ms: same fact, new valid_at →
    // a NEW edge_id; the old edge must survive as an invalidated document.
    std::thread::sleep(std::time::Duration::from_millis(15));
    fs::write(
        corpus.path().join("alpha.md"),
        "Alpha still cites [[beta]], reworded.",
    )
    .unwrap();
    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        0
    );

    let after = es.index(EDGES_INDEX);
    let old = &after[&old_wikilink[0]];
    assert!(
        old.get("invalid_at").is_some() && old.get("expired_at").is_some(),
        "prior edge is soft-invalidated, not deleted: {old}"
    );
    let live_wikilinks: Vec<&Value> = after
        .values()
        .filter(|s| s["type"] == json!("wikilink") && s.get("invalid_at").is_none())
        .collect();
    assert_eq!(live_wikilinks.len(), 1, "exactly one live replacement edge");
    assert_eq!(
        live_wikilinks[0]["evidence"]["quote"],
        json!("Alpha still cites [[beta]], reworded.")
    );
    let g = journal_graph_summary(state.path());
    assert!(
        g["edges_invalidated"].as_u64().unwrap() >= 1,
        "invalidation surfaced in the run summary: {g}"
    );
}

fn preseed_meta(es: &MockEs, edges: &str, nodes_index: &str, created_at: i64) {
    let mut store = BTreeMap::new();
    store.insert(
        detect::BRAIN_META_ID.to_string(),
        json!({
            "meta_version": 1,
            "brain": "nbkristqik",
            "nodes_index": nodes_index,
            "created_at": created_at,
        }),
    );
    es.docs.lock().unwrap().insert(edges.to_string(), store);
}

/// #2351: a later autoindex of the same folder under a new prefix must
/// replace `nodes_index`. The first writer (default prefix `ax`, or
/// `graph_api::link`'s memory default) used to stick forever because the
/// meta doc is create-if-absent.
#[test]
fn ensure_brain_meta_replaces_stale_prefix_and_keeps_created_at() {
    let es = MockEs::start();
    let client = crate::esclient::Es::new(&es.url, None).unwrap();
    let edges = ".xerj-memory-nbkristqik-edges";
    preseed_meta(&es, edges, "ax-code,ax-docs", 42);

    detect::ensure_brain_meta(
        &client,
        edges,
        "nbkristqik",
        "nbkristqik-code,nbkristqik-docs",
        99,
    )
    .unwrap();
    let meta = es.index(edges).remove(detect::BRAIN_META_ID).unwrap();
    assert_eq!(
        meta["nodes_index"],
        json!("nbkristqik-code,nbkristqik-docs")
    );
    assert_eq!(meta["created_at"], json!(42), "created_at is not rewritten");
    assert_eq!(meta["brain"], json!("nbkristqik"));
    assert_eq!(meta["meta_version"], json!(1));

    // Same set, different order: leave the stored string alone.
    detect::ensure_brain_meta(
        &client,
        edges,
        "nbkristqik",
        "nbkristqik-docs, nbkristqik-code",
        100,
    )
    .unwrap();
    let again = es.index(edges).remove(detect::BRAIN_META_ID).unwrap();
    assert_eq!(again, meta);

    // An empty desired list must not wipe a pointer a reader already resolved.
    detect::ensure_brain_meta(&client, edges, "nbkristqik", "", 101).unwrap();
    assert_eq!(es.index(edges).remove(detect::BRAIN_META_ID).unwrap(), meta);

    let fresh = ".xerj-memory-freshprefix-edges";
    detect::ensure_brain_meta(
        &client,
        fresh,
        "freshprefix",
        "freshprefix-code,freshprefix-docs",
        7,
    )
    .unwrap();
    let created = es.index(fresh).remove(detect::BRAIN_META_ID).unwrap();
    assert_eq!(
        created["nodes_index"],
        json!("freshprefix-code,freshprefix-docs")
    );
    assert_eq!(created["created_at"], json!(7));
    assert_eq!(created["brain"], json!("freshprefix"));
}

/// #2351: `brain overview` reads `nodes_index` off this meta doc. A custom
/// prefix on a folder that was already indexed under `ax` must show the
/// indexes this run created, and a `_source` include of path/start_line/end_line
/// must locate both code symbols and prose.
#[test]
fn custom_prefix_overview_and_hit_locators_follow_the_run() {
    let parent = tempfile::tempdir().unwrap();
    let corpus = parent.path().join("nbkristqik");
    fs::create_dir_all(corpus.join("src/bot")).unwrap();
    fs::write(
        corpus.join("src/bot/dailyCheckIn.ts"),
        "export function dailyCheckIn() {\n  return 1;\n}\n",
    )
    .unwrap();
    fs::write(
        corpus.join("notes.md"),
        "Daily check-in lives in the bot.\n",
    )
    .unwrap();
    // Three lines: the log family probe ignores a one-line file.
    fs::write(
        corpus.join("xferlog"),
        "Fri Oct 16 09:06:58 2026 1 10.0.0.7 4242 /uploads/fw.bin b _ o r admin ftp 0 * c\n\
         Fri Oct 16 09:07:10 2026 2 10.0.0.7 10 /uploads/invalid.bin b _ o r admin ftp 0 * i\n\
         Sat Oct 17 11:00:00 2026 0 10.0.0.9 0 /pub/README b _ i a guest ftp 0 * c\n",
    )
    .unwrap();
    let state = tempfile::tempdir().unwrap();
    let es = MockEs::start();
    let edges = ".xerj-memory-nbkristqik-edges";
    preseed_meta(&es, edges, "ax-code,ax-docs", 1);

    let mut cfg = cfg(&corpus, state.path(), &es.url);
    cfg.prefix = "nbkristqik".into();
    cfg.brain = None;
    assert_eq!(crate::run_index(cfg).unwrap(), 0);

    let meta = &es.index(edges)[detect::BRAIN_META_ID];
    assert_eq!(meta["brain"], json!("nbkristqik"));
    assert_eq!(meta["created_at"], json!(1));
    let listed: Vec<&str> = meta["nodes_index"]
        .as_str()
        .unwrap()
        .split(',')
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .collect();
    assert!(
        listed.iter().all(|name| name.starts_with("nbkristqik-")),
        "overview nodes_index must be this prefix, not a stale ax-* list: {listed:?}"
    );
    assert!(
        listed.iter().all(|name| !name.starts_with("ax-")),
        "{listed:?}"
    );
    let live: BTreeMap<String, BTreeMap<String, Value>> = es
        .docs
        .lock()
        .unwrap()
        .iter()
        .filter(|(index, _)| index.starts_with("nbkristqik-"))
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    let mut live_names: Vec<&str> = live.keys().map(String::as_str).collect();
    live_names.sort_unstable();
    let mut listed_sorted = listed.clone();
    listed_sorted.sort_unstable();
    assert_eq!(
        listed_sorted, live_names,
        "nodes_index is exactly the datasets"
    );

    let mut saw_symbol = false;
    let mut saw_code_file = false;
    let mut saw_prose = false;
    let mut saw_log_path = false;
    for docs in live.values() {
        for source in docs.values() {
            let rel = source.get("ax_path").and_then(Value::as_str).unwrap_or("");
            let locator = source
                .get("ax_locator")
                .and_then(Value::as_str)
                .unwrap_or("");
            if source.get("name").and_then(Value::as_str) == Some("dailyCheckIn") {
                saw_symbol = true;
                assert_eq!(source["path"], json!("src/bot/dailyCheckIn.ts"));
                assert_eq!(source["ax_path"], json!("src/bot/dailyCheckIn.ts"));
                assert_eq!(source["start_line"], source["line"]);
                assert!(source.get("end_line").is_some(), "{source}");
            }
            if rel == "src/bot/dailyCheckIn.ts" && locator == "code" {
                saw_code_file = true;
                assert_eq!(source["path"], json!(rel));
                assert_eq!(source["start_line"], json!(1));
                assert!(source["end_line"].as_u64().unwrap_or(0) >= 1);
            }
            if rel == "notes.md" && locator.starts_with('s') {
                saw_prose = true;
                assert_eq!(source["path"], json!("notes.md"));
                assert_eq!(source["ax_path"], json!("notes.md"));
                assert!(source.get("start_line").is_some(), "{source}");
                assert!(source.get("end_line").is_some(), "{source}");
            }
            if source.get("path").and_then(Value::as_str) == Some("/uploads/fw.bin") {
                saw_log_path = true;
                assert_eq!(source["ax_path"], json!("xferlog"));
                assert_ne!(source["path"], json!("xferlog"));
            }
        }
    }
    assert!(saw_symbol, "dailyCheckIn symbol document was not indexed");
    assert!(saw_code_file, "code file document was not indexed");
    assert!(saw_prose, "prose section was not indexed");
    assert!(
        saw_log_path,
        "xferlog path column must stay /uploads/fw.bin"
    );
}

//! End-to-end mail ingest over the synthetic Google Takeout fixture: a real
//! `run_index` against the fake ES endpoint, checked against the GROUND TRUTH
//! the generator wrote — not against numbers typed into this file.
//!
//! The fixture is `tests/fixtures/takeout-small/`, produced by
//! `scripts/synthetic-takeout.py` with [`FIXTURE_ARGS`]. It is committed so
//! this test never depends on Python and is never skipped;
//! [`the_committed_fixture_is_what_the_generator_writes`] is the separate check
//! that the two have not drifted apart.
//!
//! ## What this cannot see
//! PDF extraction runs in an isolated worker process — `current_exe()
//! __extract-pdf` — and inside a unit test `current_exe()` is the TEST binary,
//! which has no such subcommand. So here every PDF attachment takes the
//! fallback path (a name card, counted as junk). That path is real and worth
//! pinning: it is what a scanned or corrupt PDF gets. PDF PAGE records from
//! mbox attachments are verified against the real `xerj` binary on a live
//! node by `benchmarks/mbox-ingest/verify.py`, and the result is recorded in
//! that directory's README.

use super::e2e::{cfg, journal_graph_summary, Docs, MockEs};
use super::emailthread::{ATTACHMENT_OF, REPLIES_TO, TAG};
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

const EDGES_INDEX: &str = ".xerj-memory-notes-edges";
const MBOX_REL: &str = "Takeout/Mail/All mail Including Spam and Trash.mbox";

/// The generator arguments the committed fixture was written with. Small
/// blobs and a short "long line" keep the tree under 300 KB; `--ascii-names`
/// keeps FILE names portable across every OS that checks the repo out (the
/// message CONTENT is non-ASCII regardless).
const FIXTURE_ARGS: &[&str] = &[
    "--seed",
    "42",
    "--messages",
    "36",
    "--blob-max",
    "2K",
    "--long-line-bytes",
    "3K",
    "--keep-notes",
    "4",
    "--ascii-names",
    "--with-archive",
    "--quiet",
];

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/takeout-small")
}

fn truth() -> Value {
    serde_json::from_slice(&std::fs::read(fixture().join("truth.json")).unwrap()).unwrap()
}

fn copy_tree(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for e in std::fs::read_dir(from).unwrap() {
        let e = e.unwrap();
        let dst = to.join(e.file_name());
        if e.file_type().unwrap().is_dir() {
            copy_tree(&e.path(), &dst);
        } else {
            std::fs::copy(e.path(), dst).unwrap();
        }
    }
}

/// Pins the PDF worker to a binary that does not exist for the life of the
/// guard, under the crate-wide env lock. Without this the outcome of every PDF
/// attachment depends on which sibling test last set `XERJ_PDF_WORKER_BIN`
/// (some point it at a stub that answers for ANY path).
struct NoPdfWorker {
    previous: Option<std::ffi::OsString>,
    _lock: std::sync::MutexGuard<'static, ()>,
}

impl NoPdfWorker {
    fn pin() -> Self {
        let lock = crate::extract::pdf::WORKER_BIN_ENV_LOCK
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        let previous = std::env::var_os("XERJ_PDF_WORKER_BIN");
        std::env::set_var("XERJ_PDF_WORKER_BIN", "/nonexistent/xerj-pdf-worker");
        Self {
            previous,
            _lock: lock,
        }
    }
}

impl Drop for NoPdfWorker {
    fn drop(&mut self) {
        match self.previous.take() {
            Some(v) => std::env::set_var("XERJ_PDF_WORKER_BIN", v),
            None => std::env::remove_var("XERJ_PDF_WORKER_BIN"),
        }
    }
}

struct Indexed {
    /// Node docs of every dataset index: `_id` → source.
    nodes: BTreeMap<String, Value>,
    edges: BTreeMap<String, Value>,
    catalog: BTreeMap<String, Value>,
    graph: Value,
}

fn split(docs: &Docs, state: &Path) -> Indexed {
    let mut nodes = BTreeMap::new();
    for (index, store) in docs {
        if index.starts_with("ax-") {
            nodes.extend(store.iter().map(|(k, v)| (k.clone(), v.clone())));
        }
    }
    Indexed {
        nodes,
        edges: docs.get(EDGES_INDEX).cloned().unwrap_or_default(),
        catalog: docs.get("autoindex-catalog").cloned().unwrap_or_default(),
        graph: journal_graph_summary(state),
    }
}

fn index_fixture() -> (Indexed, MockEs, tempfile::TempDir, tempfile::TempDir) {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    copy_tree(&fixture().join("tree"), corpus.path());
    let es = MockEs::start();
    // 3 = completed-with-junk: the two unextracted archives are refused by
    // design, and that is exactly what this exit code reports.
    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        3
    );
    let indexed = split(&es.docs.lock().unwrap(), state.path());
    (indexed, es, corpus, state)
}

fn s<'a>(doc: &'a Value, key: &str) -> &'a str {
    doc.get(key).and_then(Value::as_str).unwrap_or("")
}

fn mbox_records(ix: &Indexed) -> Vec<(&String, &Value)> {
    ix.nodes
        .iter()
        .filter(|(_, d)| {
            s(d, "ax_path") == MBOX_REL && s(d, "ax_locator") != super::FILE_CARD_LOCATOR
        })
        .collect()
}

#[test]
fn a_takeout_mailbox_indexes_to_what_the_ground_truth_says() {
    let _pdf = NoPdfWorker::pin();
    let truth = truth();
    let (ix, _es, _corpus, _state) = index_fixture();
    let recs = mbox_records(&ix);
    let n = |key: &str| truth[key].as_u64().unwrap() as usize;

    // ── every entry of the mailbox is accounted for ──
    // One node per message (`…-msg-s0`), or `…-raw-s0` for an entry the MIME
    // parser refused; the separator-only entry has no text and is junk.
    let heads: Vec<&str> = recs
        .iter()
        .map(|(_, d)| s(d, "ax_locator"))
        .filter(|l| l.ends_with("-msg-s0") || l.ends_with("-raw-s0"))
        .collect();
    assert_eq!(
        heads.len(),
        n("entries") - n("entries_empty"),
        "every entry but the separator-only one, which is junk: {heads:?}"
    );
    assert!(
        heads.iter().all(|l| l.starts_with('m')),
        "every locator is namespaced by byte offset: {heads:?}"
    );
    let unique: BTreeSet<&&str> = heads.iter().collect();
    assert_eq!(
        unique.len(),
        heads.len(),
        "offsets are unique within the file"
    );
    for (_, d) in &recs {
        assert_eq!(s(d, "ax_format"), "mbox");
    }

    // ── the unquoted prose `From ` line did NOT split its message ──
    let prose = recs
        .iter()
        .find(|(_, d)| s(d, "body").contains("From what I understand, the deal closes Monday"))
        .expect("the prose line is body text of some record");
    let after = truth["needles"]
        .as_array()
        .unwrap()
        .iter()
        .find(|nd| nd["where"] == "after-unquoted-prose-from")
        .unwrap();
    assert!(
        s(prose.1, "body").contains(after["token"].as_str().unwrap()),
        "the sentence after the prose `From ` line is in the SAME record"
    );
    assert_eq!(
        s(prose.1, "email_message_id"),
        after["message_id"].as_str().unwrap()
    );

    // ── mboxrd quoting is undone by exactly one level ──
    let line_starts = |needle: &str| {
        recs.iter()
            .filter(|(_, d)| s(d, "body").lines().any(|l| l.starts_with(needle)))
            .count()
    };
    let from_lines = ["From the desk of", "From what I can tell", "From now on,"];
    let unquoted: usize = from_lines.iter().map(|f| line_starts(f)).sum();
    assert_eq!(
        unquoted,
        n("from_lines_in_bodies"),
        "`>From ` came back as `From `"
    );
    let still_quoted: usize = from_lines
        .iter()
        .map(|f| line_starts(&format!(">{f}")))
        .sum();
    assert_eq!(still_quoted, 0, "no `>From the desk…` left behind");
    assert_eq!(
        line_starts(">From the archive"),
        n("quoted_from_lines_in_bodies"),
        "`>>From ` lost ONE `>`, not both"
    );

    // ── every planted needle is found exactly once, where it was planted ──
    let all: Vec<&Value> = ix.nodes.values().collect();
    for nd in truth["needles"].as_array().unwrap() {
        let (token, place) = (nd["token"].as_str().unwrap(), nd["where"].as_str().unwrap());
        let hits: Vec<&&Value> = all
            .iter()
            .filter(|d| s(d, "body").contains(token))
            .collect();
        if place == "pdf-attachment" {
            // See the module docs: no PDF worker inside a unit test.
            assert!(
                hits.is_empty(),
                "{token}: PDF text cannot be extracted here"
            );
            continue;
        }
        assert_eq!(
            hits.len(),
            1,
            "{place} needle {token} must be found exactly once"
        );
        let hit = hits[0];
        match place {
            // 8-bit bodies: declared latin-1, and UNDECLARED cp1252, both decoded.
            "latin1-8bit-body" => assert!(s(hit, "body").contains("Grüße aus Köln"), "{hit}"),
            "cp1252-undeclared-body" => {
                assert!(
                    s(hit, "body").contains("\u{201c}Quoted\u{201d} price: \u{20ac}420"),
                    "{hit}"
                )
            }
            "text-attachment" => {
                assert!(s(hit, "ax_locator").contains("-att"), "{hit}");
                assert!(!s(hit, "attachment_name").is_empty());
                assert_eq!(
                    s(hit, "email_message_id"),
                    nd["message_id"].as_str().unwrap()
                );
            }
            // Exactly once is the point: the `.html` twin of each note is skipped.
            "keep-note" => {
                assert!(s(hit, "ax_path").starts_with("Takeout/Keep/"));
                assert!(s(hit, "ax_path").ends_with(".json"));
                assert_eq!(s(hit, "ax_locator"), "note-s0");
                assert!(
                    hit.get("keep_trashed").is_some(),
                    "a document, with Keep's fields"
                );
            }
            "drive-markdown" => assert_eq!(s(hit, "ax_path"), "Takeout/Drive/meeting-notes.md"),
            "body" | "after-unquoted-prose-from" => {
                assert_eq!(
                    s(hit, "email_message_id"),
                    nd["message_id"].as_str().unwrap()
                )
            }
            other => panic!("the generator plants a kind this test does not check: {other}"),
        }
    }

    // ── Gmail's headers became fields ──
    let labelled = recs
        .iter()
        .filter(|(_, d)| d.get("email_labels").is_some())
        .count();
    assert!(
        labelled >= n("messages_regular"),
        "every regular message carries its labels"
    );
    for (_, d) in recs
        .iter()
        .filter(|(_, d)| d.get("email_thread_id").is_some())
    {
        let id = s(d, "email_thread_id");
        assert!(
            id.len() <= 16 && id.bytes().all(|b| b.is_ascii_hexdigit()),
            "thread id is hex, never a digit string that coerces to a long: {id}"
        );
    }
    // A non-ASCII subject arrives decoded, not as `=?UTF-8?B?…?=`. (The one
    // deliberately BROKEN encoded-word, with invalid UTF-8 inside it, is left
    // as the sender wrote it — garbage in, the same garbage out, no panic.)
    assert!(recs
        .iter()
        .filter(|(_, d)| !s(d, "email_message_id").starts_with("badword-"))
        .all(|(_, d)| !s(d, "email_subject").contains("=?UTF-8?")));
    assert!(recs.iter().any(|(_, d)| !s(d, "email_subject").is_ascii()));
}

#[test]
fn thread_and_attachment_edges_match_the_ground_truth_and_carry_evidence() {
    let _pdf = NoPdfWorker::pin();
    let truth = truth();
    let (ix, _es, _corpus, _state) = index_fixture();
    let n = |key: &str| truth[key].as_u64().unwrap();

    let mail: Vec<&Value> = ix
        .edges
        .values()
        .filter(|e| s(e, "detector") == TAG)
        .collect();
    let replies: Vec<&&Value> = mail.iter().filter(|e| s(e, "type") == REPLIES_TO).collect();
    let attached: Vec<&&Value> = mail
        .iter()
        .filter(|e| s(e, "type") == ATTACHMENT_OF)
        .collect();
    assert_eq!(
        replies.len() + attached.len(),
        mail.len(),
        "two edge types, nothing else"
    );

    // replies_to: one per reply whose parent — or nearest References ancestor —
    // is in the mailbox. The generator knows how many that is.
    assert_eq!(replies.len() as u64, n("replies_resolvable"));
    let via_refs = replies
        .iter()
        .filter(|e| s(&e["evidence"], "quote").starts_with("References: <"))
        .count() as u64;
    assert_eq!(
        via_refs,
        n("replies_via_references"),
        "resolved through References, and SAYS so"
    );
    for e in &replies {
        let quote = s(&e["evidence"], "quote");
        assert!(
            quote.starts_with("In-Reply-To: <") || quote.starts_with("References: <"),
            "evidence names the header and the id: {quote}"
        );
        for end in ["src", "dst"] {
            let node = ix
                .nodes
                .get(s(e, end))
                .unwrap_or_else(|| panic!("{end} of {e} is a ghost"));
            assert!(
                s(node, "ax_locator").ends_with("-msg-s0"),
                "{end} is a message node"
            );
        }
        assert_ne!(s(e, "src"), s(e, "dst"));
        assert_eq!(s(e, "src_file"), MBOX_REL);
    }
    // A parent that is not in the mailbox is COUNTED, never invented; the
    // duplicated Message-ID is counted as ambiguous.
    assert_eq!(
        ix.graph["edges_unresolved"].as_u64().unwrap(),
        n("replies_dangling")
    );
    assert_eq!(ix.graph["edges_ambiguous"], serde_json::json!(1));
    assert_eq!(
        ix.graph["by_detector"][TAG].as_u64().unwrap(),
        mail.len() as u64
    );

    // attachment_of: exactly one per attachment RECORD, to the message in the
    // same container slot.
    let att_records: BTreeMap<&String, &Value> = ix
        .nodes
        .iter()
        .filter(|(_, d)| d.get("attachment_name").is_some())
        .collect();
    assert_eq!(attached.len(), att_records.len());
    let total_attachments: u64 = truth["attachments"]
        .as_object()
        .unwrap()
        .values()
        .map(|v| v.as_u64().unwrap())
        .sum();
    assert!(
        att_records.len() as u64 >= total_attachments,
        "at least one record per attachment"
    );
    for e in &attached {
        let src = att_records
            .get(&s(e, "src").to_string())
            .expect("src is an attachment record");
        let dst = ix.nodes.get(s(e, "dst")).expect("dst exists");
        let slot = |d: &Value| {
            s(d, "ax_locator")
                .split('-')
                .next()
                .unwrap_or("")
                .to_string()
        };
        assert_eq!(slot(src), slot(dst), "same mbox slot (m<offset>)");
        assert!(s(dst, "ax_locator").ends_with("-msg-s0"));
        assert_eq!(s(src, "email_message_id"), s(dst, "email_message_id"));
        let quote = s(&e["evidence"], "quote");
        assert!(quote.starts_with("attachment \""), "{quote}");
        assert!(quote.contains(s(src, "attachment_name")), "{quote}");
    }
    // The PDFs (cards here — see the module docs) stay findable by name.
    let pdf_cards = att_records
        .values()
        .filter(|d| {
            s(d, "attachment_name").ends_with(".pdf") && s(d, "ax_locator").ends_with("-card")
        })
        .count() as u64;
    assert_eq!(
        pdf_cards,
        truth["attachments"]["pdf"].as_u64().unwrap()
            + truth["attachments_malformed"]["pdf"].as_u64().unwrap(),
        "every PDF, the truncated one in the malformed block included"
    );
}

#[test]
fn takeout_noise_is_skipped_and_archives_say_extract_me_first() {
    let _pdf = NoPdfWorker::pin();
    let truth = truth();
    let (ix, _es, _corpus, state) = index_fixture();

    let paths: BTreeSet<&str> = ix.nodes.values().map(|d| s(d, "ax_path")).collect();
    assert!(
        !paths.iter().any(|p| p.ends_with("archive_browser.html")),
        "{paths:?}"
    );
    assert!(
        !paths
            .iter()
            .any(|p| p.starts_with("Takeout/Keep/") && p.ends_with(".html")),
        "Keep html twins are skipped: {paths:?}"
    );
    let notes = ix
        .nodes
        .values()
        .filter(|d| s(d, "ax_locator") == "note-s0")
        .count() as u64;
    assert_eq!(notes, truth["keep_notes"].as_u64().unwrap());

    for archive in truth["archives"].as_array().unwrap() {
        let name = archive.as_str().unwrap();
        let row = ix
            .catalog
            .values()
            .find(|d| s(d, "path") == name)
            .unwrap_or_else(|| panic!("{name} must be in the catalog, not silently gone"));
        assert_eq!(s(row, "status"), "junk");
        let reason = s(row, "reason");
        assert!(reason.contains("extract it first"), "{name}: {reason}");
        assert!(
            reason.contains("does not open archives"),
            "{name}: {reason}"
        );
        assert!(!paths.contains(name), "{name} was not indexed as content");
    }
    let tgz = ix
        .catalog
        .values()
        .find(|d| s(d, "path").ends_with(".tgz"))
        .unwrap();
    assert!(
        s(tgz, "reason").contains("tar -xzf"),
        "a .tgz gets the tar command, not unzip"
    );

    // …and the RUN says so, not only the catalog (review finding on PR #949: a
    // folder holding just the Takeout .zip ended `ok=true exit=3`, 0 records,
    // and never mentioned extracting). The run summary names every archive
    // with its command; the human summary prints the same lines.
    let journal = std::fs::read_to_string(state.path().join("journal.ndjson")).unwrap();
    let summary = journal
        .lines()
        .filter_map(|l| serde_json::from_str::<Value>(l).ok())
        .rfind(|v| v.get("kind").and_then(Value::as_str) == Some("finish"))
        .map(|v| v["summary"].clone())
        .unwrap();
    let said: Vec<&str> = summary["unextracted_archives"]
        .as_array()
        .expect("the run summary lists unextracted archives")
        .iter()
        .filter_map(Value::as_str)
        .collect();
    for archive in truth["archives"].as_array().unwrap() {
        let name = archive.as_str().unwrap();
        assert!(
            said.iter()
                .any(|line| line.starts_with(name) && line.contains("extract it first")),
            "{name} missing from the run's own summary: {said:?}"
        );
    }
}

/// Same bytes → same ids. A second run over the same state, and a run from a
/// brand-new state directory, must both leave the node set exactly as it was.
#[test]
fn rerunning_never_duplicates_a_message() {
    let _pdf = NoPdfWorker::pin();
    let (first, es, corpus, state) = index_fixture();
    let ids = |ix: &Indexed| ix.nodes.keys().cloned().collect::<BTreeSet<String>>();
    let mail_edges = |ix: &Indexed| {
        ix.edges
            .iter()
            .filter(|(_, e)| s(e, "detector") == TAG)
            .map(|(k, _)| k.clone())
            .collect::<BTreeSet<String>>()
    };

    assert_eq!(
        crate::run_index(cfg(corpus.path(), state.path(), &es.url)).unwrap(),
        3
    );
    let again = split(&es.docs.lock().unwrap(), state.path());
    assert_eq!(ids(&again), ids(&first), "incremental re-run");

    let fresh_state = tempfile::tempdir().unwrap();
    assert_eq!(
        crate::run_index(cfg(corpus.path(), fresh_state.path(), &es.url)).unwrap(),
        3
    );
    let fresh = split(&es.docs.lock().unwrap(), fresh_state.path());
    assert_eq!(
        ids(&fresh),
        ids(&first),
        "full re-index from an empty state dir"
    );
    assert_eq!(
        mail_edges(&fresh),
        mail_edges(&first),
        "edge ids are deterministic too"
    );
}

// ─── runs that do not re-read every mailbox (review finding, PR #949) ─────

/// One mbox entry. Fixed-width on purpose: every message of a tree built from
/// these is the same length, so removing one moves each later message onto the
/// byte offset — and therefore the node id — of its successor. That is the
/// nastiest form of the compaction defect: not a dangling edge, a WRONG one.
fn entry(id: &str, from: &str, subject: &str, body: &str, reply_to: Option<&str>) -> String {
    let mut m = format!(
        "From {from} Tue Nov 14 22:13:20 2023\nFrom: {from}\nTo: bob@example.org\n\
         Subject: {subject}\nDate: Tue, 14 Nov 2023 22:13:20 +0000\nMessage-ID: <{id}>\n"
    );
    if let Some(parent) = reply_to {
        m.push_str(&format!("In-Reply-To: <{parent}>\n"));
    }
    m.push_str(&format!("\n{body}\n\n"));
    m
}

/// Live `replies_to` edges as (file that taught it, evidence quote, dst node).
fn live_replies(es: &MockEs) -> BTreeSet<(String, String, String)> {
    es.index(EDGES_INDEX)
        .values()
        .filter(|e| s(e, "type") == REPLIES_TO && e.get("invalid_at").is_none())
        .map(|e| {
            (
                s(e, "src_file").to_string(),
                e.pointer("/evidence/quote")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .to_string(),
                s(e, "dst").to_string(),
            )
        })
        .collect()
}

/// Node id of the message with this Message-ID, from the published docs.
fn node_of(es: &MockEs, message_id: &str) -> String {
    let docs = es.docs.lock().unwrap();
    let mut found = docs
        .iter()
        .filter(|(index, _)| index.starts_with("ax-"))
        .flat_map(|(_, store)| store.iter())
        .filter(|(_, d)| {
            s(d, "email_message_id") == message_id && s(d, "ax_locator").ends_with("msg-s0")
        })
        .map(|(id, _)| id.clone());
    let id = found
        .next()
        .unwrap_or_else(|| panic!("no node for <{message_id}>"));
    assert!(found.next().is_none(), "<{message_id}> indexed twice");
    id
}

fn run_ok(corpus: &Path, state: &Path, es: &MockEs) {
    assert_eq!(crate::run_index(cfg(corpus, state, &es.url)).unwrap(), 0);
}

/// `Inbox` + `Sent` is how Thunderbird, Apple Mail and mutt store mail, and a
/// conversation crosses the two files on every turn. An incremental run
/// re-reads only the file that changed; the reply edges must not depend on
/// which one that was.
///
/// Before the fix: appending one unrelated message to `Inbox` invalidated
/// `Inbox`'s edges (correct), re-read `Inbox` alone, could not see `<s2@x>` in
/// the un-re-read `Sent`, and the Inbox → Sent reply edge was gone — 2 live
/// edges became 1, with `unresolved: 1`, while both messages were still there.
#[test]
fn a_reply_across_two_mailboxes_survives_an_incremental_run() {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    let mail = corpus.path().join("Mail");
    std::fs::create_dir_all(&mail).unwrap();
    let inbox = entry(
        "a1@x",
        "alice@example.org",
        "Budget",
        "how much is left",
        None,
    ) + &entry(
        "a3@x",
        "alice@example.org",
        "Re: Budget",
        "thanks",
        Some("s2@x"),
    );
    std::fs::write(mail.join("Inbox"), &inbox).unwrap();
    std::fs::write(
        mail.join("Sent"),
        entry(
            "s2@x",
            "bob@example.org",
            "Re: Budget",
            "about four thousand",
            Some("a1@x"),
        ),
    )
    .unwrap();
    let es = MockEs::start();
    run_ok(corpus.path(), state.path(), &es);

    let expected = |es: &MockEs| -> BTreeSet<(String, String, String)> {
        [
            ("Mail/Inbox", "In-Reply-To: <s2@x>", node_of(es, "s2@x")),
            ("Mail/Sent", "In-Reply-To: <a1@x>", node_of(es, "a1@x")),
        ]
        .into_iter()
        .map(|(f, q, d)| (f.to_string(), q.to_string(), d))
        .collect()
    };
    assert_eq!(live_replies(&es), expected(&es), "full run");

    // One unrelated new mail lands in Inbox. Sent is untouched and not re-read.
    let appended = inbox + &entry("a4@x", "dora@example.org", "Lunch", "friday?", None);
    std::fs::write(mail.join("Inbox"), appended).unwrap();
    run_ok(corpus.path(), state.path(), &es);
    assert_eq!(
        live_replies(&es),
        expected(&es),
        "the Inbox → Sent reply must survive a run that re-read only Inbox"
    );
    let graph = journal_graph_summary(state.path());
    assert_eq!(graph["edges_unresolved"], 0, "{graph}");

    // And the other direction: a reply lands in the un-re-read file's PARENT
    // position — a new Sent message answering the new Inbox mail, then only
    // Sent changes. Inbox is carried over this time.
    let sent = std::fs::read_to_string(mail.join("Sent")).unwrap()
        + &entry("s5@x", "bob@example.org", "Re: Lunch", "yes", Some("a4@x"));
    std::fs::write(mail.join("Sent"), sent).unwrap();
    run_ok(corpus.path(), state.path(), &es);
    let mut want = expected(&es);
    want.insert((
        "Mail/Sent".into(),
        "In-Reply-To: <a4@x>".into(),
        node_of(&es, "a4@x"),
    ));
    assert_eq!(live_replies(&es), want);

    // What an incremental history converges to is what a clean index holds.
    // Compared without node ids: a file's key survives an in-place edit, so an
    // edited history and a clean index name the same messages by different ids
    // (each side's ids were checked against its own docs above).
    let clean = MockEs::start();
    let clean_state = tempfile::tempdir().unwrap();
    run_ok(corpus.path(), clean_state.path(), &clean);
    let shape = |es: &MockEs| -> BTreeSet<(String, String)> {
        live_replies(es)
            .into_iter()
            .map(|(f, q, _)| (f, q))
            .collect()
    };
    assert_eq!(shape(&es), shape(&clean));
    assert_eq!(shape(&clean).len(), 3);
}

/// Thunderbird's "compact folder" removes deleted messages and every later
/// message moves down. Node ids are positional (`m{offset}-msg-s0`), so a
/// saved `.eml` that replies into the mailbox — a file the run does NOT
/// re-read — holds an edge to the parent's OLD node id.
///
/// Before the fix that edge stayed live. With equal-length messages it is not
/// even dangling: the old id of `<b4@x>` is now the id of `<b5@x>`, so the
/// graph said, with 0.95 confidence and the quote `In-Reply-To: <b4@x>`, that
/// the reply answers a different message.
#[test]
fn a_reply_into_a_compacted_mailbox_follows_its_parent() {
    let corpus = tempfile::tempdir().unwrap();
    let state = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(corpus.path().join("Mail")).unwrap();
    std::fs::create_dir_all(corpus.path().join("saved")).unwrap();
    let msgs: Vec<String> = (1..=5)
        .map(|i| {
            entry(
                &format!("b{i}@x"),
                "bea@example.org",
                &format!("Topic {i}"),
                &format!("body of message {i}"),
                None,
            )
        })
        .collect();
    let mbox = corpus.path().join("Mail/Inbox.mbox");
    std::fs::write(&mbox, msgs.concat()).unwrap();
    std::fs::write(
        corpus.path().join("saved/reply.eml"),
        "From: bob@example.org\nTo: bea@example.org\nSubject: Re: Topic 4\n\
         Date: Wed, 15 Nov 2023 09:00:00 +0000\nMessage-ID: <r4@x>\nIn-Reply-To: <b4@x>\n\n\
         replying to topic four\n",
    )
    .unwrap();
    let es = MockEs::start();
    run_ok(corpus.path(), state.path(), &es);
    let before = node_of(&es, "b4@x");
    let one = |dst: String| -> BTreeSet<(String, String, String)> {
        [(
            "saved/reply.eml".to_string(),
            "In-Reply-To: <b4@x>".to_string(),
            dst,
        )]
        .into()
    };
    assert_eq!(live_replies(&es), one(before.clone()));

    // Compact: <b2@x> is gone, every later message moves down one slot.
    let compacted: String = msgs
        .iter()
        .enumerate()
        .filter(|(i, _)| *i != 1)
        .map(|(_, m)| m.as_str())
        .collect();
    std::fs::write(&mbox, compacted).unwrap();
    run_ok(corpus.path(), state.path(), &es);

    let after = node_of(&es, "b4@x");
    assert_ne!(after, before, "the parent moved — that is the scenario");
    assert_eq!(
        node_of(&es, "b5@x"),
        before,
        "…onto an id that is now a DIFFERENT message, so a stale edge is wrong, not just dangling"
    );
    assert_eq!(
        live_replies(&es),
        one(after),
        "the un-re-read .eml's reply edge must follow <b4@x> to its new node"
    );
    // The superseded edge is history, not gone: invalidated, still stored.
    let superseded: Vec<Value> = es
        .index(EDGES_INDEX)
        .values()
        .filter(|e| s(e, "type") == REPLIES_TO && s(e, "dst") == before)
        .cloned()
        .collect();
    assert_eq!(superseded.len(), 1);
    assert!(superseded[0].get("invalid_at").is_some());
    assert!(journal_graph_summary(state.path())["edges_invalidated"].as_u64() >= Some(1));

    // The parent leaves the corpus altogether: no live edge, one unresolved.
    let without_b4: String = msgs
        .iter()
        .enumerate()
        .filter(|(i, _)| *i != 1 && *i != 3)
        .map(|(_, m)| m.as_str())
        .collect();
    std::fs::write(&mbox, without_b4).unwrap();
    run_ok(corpus.path(), state.path(), &es);
    assert!(live_replies(&es).is_empty(), "{:?}", live_replies(&es));
    assert_eq!(journal_graph_summary(state.path())["edges_unresolved"], 1);
}

/// The committed fixture must be exactly what `scripts/synthetic-takeout.py`
/// writes for [`FIXTURE_ARGS`] — otherwise "the tests use the generator" stops
/// being true the first time someone edits one and not the other.
///
/// `XERJ_REGENERATE_TAKEOUT_FIXTURE=1` rewrites the fixture instead of
/// checking it (that is the supported way to update it).
///
/// Honest limits: the generator's byte-identical guarantee is only VERIFIED
/// within one Python minor version (CPython documents `random()` as stable
/// across versions, not `choices`/`randint`). So a mismatch under a different
/// Python than the fixture was written with is reported and tolerated, and a
/// machine with no Python at all cannot run this check — loudly, and as a
/// failure when `CI` is set, because CI is where drift has to be caught.
#[test]
fn the_committed_fixture_is_what_the_generator_writes() {
    let script =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../scripts/synthetic-takeout.py");
    assert!(
        script.is_file(),
        "generator missing at {}",
        script.display()
    );
    let python = ["python3", "python"].into_iter().find(|p| {
        std::process::Command::new(p)
            .arg("--version")
            .output()
            .is_ok_and(|o| o.status.success())
    });
    let Some(python) = python else {
        assert!(
            std::env::var_os("CI").is_none(),
            "CI has no python3: fixture drift cannot be checked"
        );
        eprintln!("NOT CHECKED: no python3 on PATH, fixture drift check did not run");
        return;
    };
    let version = std::process::Command::new(python)
        .args(["-c", "import sys;print('%d.%d'%sys.version_info[:2])"])
        .output()
        .unwrap();
    let version = String::from_utf8_lossy(&version.stdout).trim().to_string();

    let out = tempfile::tempdir().unwrap();
    let tree = out.path().join("tree");
    let truth_path = out.path().join("truth.json");
    let status = std::process::Command::new(python)
        .arg(&script)
        .arg("--out")
        .arg(&tree)
        .arg("--truth")
        .arg(&truth_path)
        .args(FIXTURE_ARGS)
        .status()
        .unwrap();
    assert!(status.success(), "generator failed");

    fn files(root: &Path, dir: &Path, out: &mut BTreeMap<String, Vec<u8>>) {
        for e in std::fs::read_dir(dir).unwrap() {
            let e = e.unwrap();
            if e.file_type().unwrap().is_dir() {
                files(root, &e.path(), out);
            } else {
                let rel = e
                    .path()
                    .strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                out.insert(rel, std::fs::read(e.path()).unwrap());
            }
        }
    }
    let mut generated = BTreeMap::new();
    files(&tree, &tree, &mut generated);
    generated.insert("../truth.json".into(), std::fs::read(&truth_path).unwrap());

    if std::env::var_os("XERJ_REGENERATE_TAKEOUT_FIXTURE").is_some() {
        let _ = std::fs::remove_dir_all(fixture().join("tree"));
        copy_tree(&tree, &fixture().join("tree"));
        std::fs::copy(&truth_path, fixture().join("truth.json")).unwrap();
        std::fs::write(
            fixture().join("GENERATED_WITH_PYTHON.txt"),
            format!("{version}\n"),
        )
        .unwrap();
        eprintln!("fixture regenerated with python {version}");
        return;
    }

    let mut committed = BTreeMap::new();
    files(
        &fixture().join("tree"),
        &fixture().join("tree"),
        &mut committed,
    );
    committed.insert(
        "../truth.json".into(),
        std::fs::read(fixture().join("truth.json")).unwrap(),
    );
    let differing: Vec<&String> = generated
        .keys()
        .chain(committed.keys())
        .filter(|k| generated.get(*k) != committed.get(*k))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    if differing.is_empty() {
        return;
    }
    // WHICH files exist is not a property of the Python version: the generator
    // decides names from its arguments, and only the bytes inside a file can
    // move between interpreter releases. So a file on one side only is never
    // tolerated. This is the check that catches a fixture file that never
    // reached the commit (the repo's blanket `*.md` ignore rule swallowed
    // `Drive/meeting-notes.md`, the tree was complete on the author's disk and
    // absent from every clean checkout; on CI's different Python the tolerant
    // branch below then reported "NOT VERIFIED" and passed).
    let one_sided: Vec<&String> = differing
        .iter()
        .copied()
        .filter(|k| generated.contains_key(*k) != committed.contains_key(*k))
        .collect();
    assert!(
        one_sided.is_empty(),
        "the committed fixture and the generator disagree about WHICH files exist \
         (python {version}): {one_sided:?}\n\
         a file the generator writes but the checkout lacks is usually an ignore rule: \
         `git check-ignore -v <file>`, then `git add -f` it or re-include the path in .gitignore"
    );
    let written_with =
        std::fs::read_to_string(fixture().join("GENERATED_WITH_PYTHON.txt")).unwrap_or_default();
    if written_with.trim() != version {
        eprintln!(
            "NOT VERIFIED: fixture written with python {}, this is {version}; {} file(s) differ \
             and the cause cannot be told apart from a generator change",
            written_with.trim(),
            differing.len()
        );
        return;
    }
    panic!(
        "fixture drifted from scripts/synthetic-takeout.py (same python {version}): {differing:?}\n\
         regenerate: XERJ_REGENERATE_TAKEOUT_FIXTURE=1 cargo test -p xerj-autoindex --lib \
         the_committed_fixture_is_what_the_generator_writes"
    );
}

//! Second-brain edge detectors: deterministic, versioned relationship
//! extraction over the corpus autoindex is already walking (contract:
//! SECOND_BRAIN_SPEC §6).
//!
//! Why deterministic instead of an LLM pass: the same corpus must produce a
//! byte-identical edge set on every run (given unchanged mtimes), because edge
//! identity — and therefore idempotent re-runs, kill -9 safety, and the
//! bi-temporal history — hangs off a content hash of (src, type, dst,
//! valid_at). A model in that loop would turn every re-run into a new belief
//! set. Every emitted edge instead carries the exact quote that taught it and
//! a `detector` tag like `wikilink@1`; bump the `@N` on ANY behavior change so
//! old edges remain attributable to the rules that produced them.
//!
//! Edges are ordinary documents in one reserved `.xerj-memory-{brain}-edges`
//! index per brain — no storage-format change, they ride the normal
//! WAL → memtable → segment path and are soft-invalidated (never deleted) so
//! "what did it believe last Tuesday" stays answerable.

pub mod cratecite;
pub mod emailthread;
pub mod href;
pub mod mdlink;
pub mod pathcite;
pub mod samedir;
pub mod sequence;
pub mod sharedterm;
pub mod wikilink;

#[cfg(test)]
mod e2e;
#[cfg(test)]
mod e2e_mail;

use crate::esclient::Es;
use anyhow::{anyhow, Context, Result};
use serde_json::{json, Value};
use std::collections::BTreeMap;

/// Edge-schema version stamped into every emitted edge (`schema_version`).
pub const EDGE_SCHEMA_VERSION: u32 = 1;

/// Reserved `_id` of the per-brain meta document. It carries no `src`/`dst`,
/// so the hop path and every edge count (all filter on `exists src`) never
/// see it.
pub const BRAIN_META_ID: &str = "__xerj-brain-meta";

/// edge_id = xxh3_128("xg1\0" src "\0" type "\0" dst "\0" decimal(valid_at_ms)),
/// rendered as 32 lowercase hex chars ({:032x}).
pub fn edge_id(src: &str, edge_type: &str, dst: &str, valid_at_ms: i64) -> String {
    use xxhash_rust::xxh3::xxh3_128;
    let mut input = Vec::with_capacity(16 + src.len() + edge_type.len() + dst.len());
    input.extend_from_slice(b"xg1\x00");
    input.extend_from_slice(src.as_bytes());
    input.push(0);
    input.extend_from_slice(edge_type.as_bytes());
    input.push(0);
    input.extend_from_slice(dst.as_bytes());
    input.push(0);
    input.extend_from_slice(valid_at_ms.to_string().as_bytes());
    format!("{:032x}", xxh3_128(&input))
}

/// Edges index name for a brain (SECOND_BRAIN_SPEC §1). The leading dot keeps
/// it out of user index APIs and `_cat` listings.
pub fn edges_index_name(brain: &str) -> String {
    format!(".xerj-memory-{brain}-edges")
}

/// Brain-name validation: identical rules to the agent-memory namespace
/// (lowercase/digit start, `[a-z0-9._-]`, ≤200 chars, no `..`) plus the
/// `-edges` suffix rejection — without it a brain named `kb-edges` would
/// collide with brain `kb`'s edge index.
pub fn validate_brain(brain: &str) -> std::result::Result<(), String> {
    if brain.is_empty() {
        return Err("brain name must not be empty".into());
    }
    if brain.len() > 200 {
        return Err("brain name too long (max 200 chars)".into());
    }
    let first = brain.chars().next().unwrap();
    if !(first.is_ascii_lowercase() || first.is_ascii_digit()) {
        return Err("brain name must start with a lowercase letter or digit".into());
    }
    for c in brain.chars() {
        let ok = c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '_' | '-' | '.');
        if !ok {
            return Err(format!(
                "brain name contains illegal character '{c}' (allowed: a-z 0-9 _ - .)"
            ));
        }
    }
    if brain.contains("..") {
        return Err("brain name must not contain '..'".into());
    }
    if brain.ends_with("-edges") {
        return Err("namespace suffix '-edges' is reserved for graph edge indices".into());
    }
    Ok(())
}

/// The exact edges-index mapping body (SECOND_BRAIN_SPEC §2.1). The API
/// stream's `graph_api::link` sends the byte-identical body — the two writers
/// must agree or the first one to touch a brain decides the column types for
/// everyone.
pub fn edge_index_mapping() -> Value {
    json!({
        "mappings": {
            "properties": {
                "edge_id":        { "type": "keyword" },
                "src":            { "type": "keyword" },
                "dst":            { "type": "keyword" },
                "type":           { "type": "keyword" },
                "weight":         { "type": "float" },
                "valid_at":       { "type": "date", "format": "epoch_millis" },
                "invalid_at":     { "type": "date", "format": "epoch_millis" },
                "created_at":     { "type": "date", "format": "epoch_millis" },
                "expired_at":     { "type": "date", "format": "epoch_millis" },
                "detector":       { "type": "keyword" },
                "confidence":     { "type": "float" },
                "schema_version": { "type": "integer" },
                "src_file":       { "type": "keyword" },
                "src_format":     { "type": "keyword" },
                "dst_format":     { "type": "keyword" },
                "evidence": {
                    "properties": {
                        "quote":  { "type": "text" },
                        "source": { "type": "keyword" },
                        "offset": { "type": "long" }
                    }
                }
            }
        }
    })
}

// ─── corpus resolution table ─────────────────────────────────────────────

/// Corpus-wide resolution table, built once after Phase A (plan assignment):
/// every indexed file's rel path → identity + the doc id of its first section.
pub struct CorpusIndex {
    /// key: root-relative path with forward slashes (`FileEntry.rel`).
    pub files: BTreeMap<String, CorpusFile>,
    /// lowercase file-stem → rel paths bearing it (wikilink resolution;
    /// BTreeMap + sorted values so ambiguity resolution is deterministic).
    pub by_stem: BTreeMap<String, Vec<String>>,
    /// exact file NAME (final path segment, case-sensitive) → rel paths
    /// bearing it. pathcite's suffix resolution: a token's last segment keys
    /// this table, then candidates are filtered by full-suffix match — O(log n)
    /// instead of scanning every rel per token.
    pub by_name: BTreeMap<String, Vec<String>>,
    /// crate-directory basename → rels of the `Cargo.toml` files directly
    /// inside a directory of that name (cratecite's Phase-A crate table). Keyed
    /// by DIRECTORY name, not `[package] name` — CorpusIndex never reads file
    /// contents, and saying otherwise would overclaim.
    pub crate_dirs: BTreeMap<String, Vec<String>>,
}

pub struct CorpusFile {
    pub rel: String,
    /// `ids::file_key` output.
    pub file_key: String,
    pub dataset_slug: String,
    /// `ids::doc_id(dataset_slug, file_key, "file")` — the file's CARD node.
    /// Every file-level edge terminates here. Historically this was the `s0`
    /// section doc id, which does not exist for row/line/page-locator families
    /// (CSV, JSONL, PDF…) — incoming links then pointed at a ghost. The card
    /// is a real emitted node for EVERY indexed file (lib.rs stages it before
    /// the file's records), so anchors are always hydratable and focusable.
    pub anchor_doc_id: String,
    pub mtime_ms: i64,
    /// Parent dir rel path, "" for root.
    pub dir: String,
    /// Sniffed format family (`Family::as_str`), from the frozen plan — NOT
    /// guessed from the extension. href@2 gates on this: the contract scopes
    /// anchor detection to html-extracted files, and an `.html` extension is
    /// not proof of that (sniffing decides the family).
    pub family: String,
    /// File-type label stamped into edges as `src_format`/`dst_format`:
    /// lowercase extension when the name has one ("md", "rs", "pdf"), else the
    /// sniffed family. Extension-level truth is what makes the dashboard's
    /// cross-type counts (md→rs, md→pdf) sayable at all — two txt-prose
    /// families would hide exactly the crossings the map exists to show.
    pub format: String,
}

/// Build one [`CorpusFile`], deriving the anchor node id and parent dir from
/// the identity fields so every caller (pipeline and tests) derives them the
/// same way.
pub fn corpus_file(
    rel: &str,
    file_key: &str,
    dataset_slug: &str,
    family: &str,
    mtime_ms: i64,
) -> CorpusFile {
    CorpusFile {
        rel: rel.to_string(),
        file_key: file_key.to_string(),
        dataset_slug: dataset_slug.to_string(),
        anchor_doc_id: crate::ids::doc_id(dataset_slug, file_key, FILE_CARD_LOCATOR),
        mtime_ms,
        dir: rel
            .rsplit_once('/')
            .map(|(d, _)| d.to_string())
            .unwrap_or_default(),
        family: family.to_string(),
        format: format_of(rel, family),
    }
}

/// Locator of the per-file card node. Cannot collide with content locators —
/// every extractor's locators are letter+digit shaped (`s3`, `p2-s0`, `b1024`,
/// `row7`, table/row pairs), never the bare word `file`.
pub const FILE_CARD_LOCATOR: &str = "file";

/// Lowercase extension of the final path segment, falling back to the sniffed
/// family for extension-less names and dotfiles. Extensions longer than 12
/// chars or with non-alphanumerics are treated as not-an-extension (version
/// suffixes, minified-name noise).
pub(crate) fn format_of(rel: &str, family: &str) -> String {
    let name = rel.rsplit('/').next().unwrap_or(rel);
    match name.rsplit_once('.') {
        Some((stem, ext))
            if !stem.is_empty()
                && !ext.is_empty()
                && ext.len() <= 12
                && ext.bytes().all(|b| b.is_ascii_alphanumeric()) =>
        {
            ext.to_ascii_lowercase()
        }
        _ => family.to_string(),
    }
}

impl CorpusIndex {
    pub fn build(files: Vec<CorpusFile>) -> Self {
        let mut map: BTreeMap<String, CorpusFile> = BTreeMap::new();
        let mut by_stem: BTreeMap<String, Vec<String>> = BTreeMap::new();
        let mut by_name: BTreeMap<String, Vec<String>> = BTreeMap::new();
        let mut crate_dirs: BTreeMap<String, Vec<String>> = BTreeMap::new();
        for f in files {
            by_stem
                .entry(stem_of(&f.rel).to_ascii_lowercase())
                .or_default()
                .push(f.rel.clone());
            let name = f.rel.rsplit('/').next().unwrap_or(&f.rel);
            by_name
                .entry(name.to_string())
                .or_default()
                .push(f.rel.clone());
            if let Some(dir) = f.rel.strip_suffix("/Cargo.toml") {
                let dir_name = dir.rsplit('/').next().unwrap_or(dir);
                if !dir_name.is_empty() {
                    crate_dirs
                        .entry(dir_name.to_string())
                        .or_default()
                        .push(f.rel.clone());
                }
            }
            map.insert(f.rel.clone(), f);
        }
        for rels in by_stem.values_mut() {
            rels.sort();
            rels.dedup();
        }
        for rels in by_name.values_mut() {
            rels.sort();
            rels.dedup();
        }
        for rels in crate_dirs.values_mut() {
            rels.sort();
            rels.dedup();
        }
        CorpusIndex {
            files: map,
            by_stem,
            by_name,
            crate_dirs,
        }
    }
}

/// File stem of a rel path: final path segment minus its last extension.
/// Dotfiles (".env") keep their full name — an empty stem would collide every
/// dotfile into one wikilink bucket.
pub(crate) fn stem_of(rel: &str) -> &str {
    let name = rel.rsplit('/').next().unwrap_or(rel);
    match name.rsplit_once('.') {
        Some((stem, _)) if !stem.is_empty() => stem,
        _ => name,
    }
}

/// Rel path minus its last extension (whole-path form used by wikilink's
/// "with or without extension" rule). "" stem is preserved as-is for dotfiles.
pub(crate) fn rel_without_ext(rel: &str) -> String {
    let (dir, name) = rel.rsplit_once('/').unwrap_or(("", rel));
    let stem = match name.rsplit_once('.') {
        Some((s, _)) if !s.is_empty() => s,
        _ => name,
    };
    if dir.is_empty() {
        stem.to_string()
    } else {
        format!("{dir}/{stem}")
    }
}

// ─── detector trait ──────────────────────────────────────────────────────

/// One detected edge before identity/envelope assembly.
pub struct EdgeDraft {
    /// Node doc id (usually the section containing the evidence).
    pub src: String,
    /// Node doc id (target file's anchor_doc_id).
    pub dst: String,
    pub edge_type: &'static str,
    pub weight: f32,
    pub confidence: f32,
    /// §6.4 determinism rule: mtime of `src_file`, never the wall clock —
    /// re-runs over an unchanged corpus reproduce identical edge_ids.
    pub valid_at_ms: i64,
    /// Rel path that taught this edge (top-level keyword — exists so
    /// replacement invalidation is a doc-values term query, not an
    /// `evidence.source` object scan).
    pub src_file: String,
    /// evidence.quote (≤240 chars, trimmed).
    pub quote: String,
    /// evidence.offset (byte offset in section text; 0 for structural).
    pub offset: u64,
    /// File-type labels of the two endpoints (`CorpusFile.format`), stored as
    /// `src_format`/`dst_format`. Empty string = unknown → key omitted from
    /// the stored doc (same omission discipline as `invalid_at`).
    pub src_format: String,
    pub dst_format: String,
}

/// Per-section textual context. `text` is the exact section string that became
/// the node doc's `body` (post `split_sections`).
pub struct SectionCtx<'a> {
    pub corpus: &'a CorpusIndex,
    pub file: &'a CorpusFile,
    /// Human label of this section within its file, derived from the locator
    /// by `lib.rs::section_label`: "section 3" for `s3`, "page 2 section 0"
    /// for `p2-s0`. Used verbatim in sequence evidence rationales.
    pub section_label: &'a str,
    /// (doc id, label) of the previously staged section of the SAME file;
    /// None for the file's first section. Tracked by the pipeline in stream
    /// order — the only way to know a page boundary's predecessor (`p2-s0`'s
    /// predecessor is the LAST section of page 1, which the locator alone
    /// cannot name).
    pub prev_section: Option<(&'a str, &'a str)>,
    pub section_doc_id: &'a str,
    pub text: &'a str,
}

/// Per-RECORD structured context: the FIELDS of a staged record rather than
/// its text. For relationships the extractor already parsed out of the source
/// (an email's `In-Reply-To`), where re-finding them in body text would be both
/// slower and wrong. Unlike [`SectionCtx`] this is offered for every record of
/// every family — locators that are not text sections included.
pub struct RecordCtx<'a> {
    pub corpus: &'a CorpusIndex,
    pub file: &'a CorpusFile,
    /// The record's content locator (`RawRecord::locator`).
    pub locator: &'a str,
    /// The node doc id the record was staged under.
    pub doc_id: &'a str,
    /// The record exactly as staged: coerced, with the `ax_*` provenance.
    pub fields: &'a serde_json::Map<String, Value>,
}

/// What a resolving detector could not turn into edges. Surfaced in the run
/// summary so a dangling `[[link]]` is recorded, never silently dropped.
#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct DetectorCounters {
    /// Link targets that resolved to no corpus file (dangling).
    pub unresolved: u64,
    /// Link targets with >1 candidate; the lexicographically smallest rel won.
    pub ambiguous: u64,
    /// Candidate edges a density budget refused to draw (sharedterm's
    /// per-document cap). The map's "what it did not show" is a fact about the
    /// corpus too, and swallowing it would make a sparse map look complete.
    pub capped: u64,
}

/// Deterministic, versioned edge detector. NO network, NO LLM, NO clock reads
/// (all time comes from ctx mtimes) — same inputs must yield the same drafts.
pub trait EdgeDetector: Sync {
    /// Versioned tag stored in `detector`, e.g. "wikilink@1". Bump the @N on
    /// ANY behavior change.
    fn tag(&self) -> &'static str;
    /// Per-section textual detection. Default: no-op.
    fn detect_text(&self, _ctx: &SectionCtx<'_>, _out: &mut Vec<EdgeDraft>) {}
    /// Per-record structured detection, called for EVERY staged record right
    /// after `detect_text` would have been. Default: no-op, and a detector that
    /// implements it must return early for families it does not read — this is
    /// the hot path of Phase B.
    fn detect_record(&self, _ctx: &RecordCtx<'_>, _out: &mut Vec<EdgeDraft>) {}
    /// A record of a file this run did NOT re-read — unchanged since an earlier
    /// run, or finished by an interrupted one — loaded back from the index by
    /// the caller and offered before `detect_corpus`. For detectors whose
    /// corpus pass must be a function of the corpus rather than of which files
    /// this invocation happened to read (email-thread: a reply in `Inbox`
    /// names a parent in an unchanged `Sent`). The detector itself still does
    /// no network: `ctx.fields` holds what the caller fetched. Emits nothing
    /// here; whatever it learns comes out of `detect_corpus`. Default: no-op.
    fn carry_over(&self, _ctx: &RecordCtx<'_>) {}
    /// Corpus-structural detection, called once after Phase A — before any
    /// file is read, so it sees identities and paths only. Default: no-op.
    fn detect_structure(&self, _corpus: &CorpusIndex, _out: &mut Vec<EdgeDraft>) {}
    /// Corpus-wide detection over the text of the whole run, called ONCE after
    /// Phase B. This is where a detector emits edges that cannot be judged one
    /// section at a time — sharedterm cannot know a term is distinctive until
    /// every document's terms are in. Such a detector accumulates in
    /// `detect_text` behind interior mutability and emits here; determinism is
    /// its own responsibility, since Phase B's worker interleaving is not.
    /// Default: no-op.
    fn detect_corpus(&self, _corpus: &CorpusIndex, _out: &mut Vec<EdgeDraft>) {}
    /// Run-summary honesty counters (default: nothing to report). Detectors
    /// that resolve link targets keep these in atomics so the counts survive
    /// the shared `&self` the parallel Phase B workers hold.
    fn counters(&self) -> DetectorCounters {
        DetectorCounters::default()
    }
}

/// The registry. Order is normative (fixture edge ordering depends on it only
/// via edge sort, so this is cosmetic — but keep it).
pub fn default_detectors() -> Vec<Box<dyn EdgeDetector>> {
    vec![
        Box::new(wikilink::Wikilink::default()),
        Box::new(mdlink::Mdlink::default()),
        Box::new(href::Href::default()),
        Box::new(pathcite::Pathcite::default()),
        Box::new(cratecite::Cratecite::default()),
        Box::new(sequence::Sequence),
        Box::new(samedir::SameDir),
        Box::new(sharedterm::SharedTerm::default()),
        Box::new(emailthread::EmailThread::default()),
    ]
}

/// Detector tag for an edge type. The draft deliberately carries only the
/// type (§6.3 shape); the 1:1 type→tag map lives here, next to the registry,
/// so a version bump touches exactly one detector file plus nothing else.
pub fn detector_tag_for(edge_type: &str) -> &'static str {
    match edge_type {
        wikilink::EDGE_TYPE => wikilink::TAG,
        mdlink::EDGE_TYPE => mdlink::TAG,
        href::EDGE_TYPE => href::TAG,
        pathcite::EDGE_TYPE => pathcite::TAG,
        cratecite::EDGE_TYPE => cratecite::TAG,
        sequence::EDGE_TYPE => sequence::TAG,
        samedir::EDGE_TYPE => samedir::TAG,
        sharedterm::EDGE_TYPE => sharedterm::TAG,
        // One detector, two edge types: both are facts read off the same
        // parsed message, versioned together.
        emailthread::REPLIES_TO | emailthread::ATTACHMENT_OF => emailthread::TAG,
        _ => "unknown@0",
    }
}

// ─── shared text/link helpers ────────────────────────────────────────────

/// Evidence quote discipline: the full trimmed line containing `offset`,
/// clipped to 240 chars — enough to show a human (or agent) exactly what
/// taught the edge without dragging whole sections into every edge doc.
pub(crate) fn line_at(text: &str, offset: usize) -> String {
    let offset = offset.min(text.len());
    let start = text[..offset].rfind('\n').map(|i| i + 1).unwrap_or(0);
    let end = text[offset..]
        .find('\n')
        .map(|i| offset + i)
        .unwrap_or(text.len());
    clip_quote(&text[start..end])
}

pub(crate) fn clip_quote(s: &str) -> String {
    let t = s.trim();
    if t.chars().count() <= 240 {
        t.to_string()
    } else {
        t.chars().take(240).collect()
    }
}

/// Outcome of scheme-less link resolution (mdlink/href rule, §6.5).
pub(crate) enum LinkTarget<'a> {
    /// Has a scheme or `//` prefix — external by design, not dangling.
    External,
    /// Nothing left after stripping fragment/query (same-page anchor).
    Empty,
    /// Scheme-less but no corpus file matches — dangling, counted.
    Miss,
    Hit(&'a CorpusFile),
}

/// Resolve a scheme-less url against the corpus: relative to the containing
/// file's dir first, then as root-relative. Fragment (`#…`) and query (`?…`)
/// are stripped; percent-encoding is NOT decoded (a deliberate v1 limit —
/// decoding would need an escaping table and links in local corpora rarely
/// use it; a miss is counted, not hidden).
pub(crate) fn resolve_local<'a>(
    corpus: &'a CorpusIndex,
    containing_dir: &str,
    url: &str,
) -> LinkTarget<'a> {
    let url = url.trim();
    if url.is_empty() {
        return LinkTarget::Empty;
    }
    if url.starts_with("//") || has_scheme(url) {
        return LinkTarget::External;
    }
    let path = url.split(['#', '?']).next().unwrap_or("");
    if path.is_empty() {
        return LinkTarget::Empty;
    }
    let candidates: [Option<String>; 2] = if let Some(site_abs) = path.strip_prefix('/') {
        // Site-absolute → root-relative only; joining it under the containing
        // dir would invent a path the author never wrote.
        [normalize_rel(site_abs), None]
    } else {
        let joined = if containing_dir.is_empty() {
            path.to_string()
        } else {
            format!("{containing_dir}/{path}")
        };
        [normalize_rel(&joined), normalize_rel(path)]
    };
    for cand in candidates.into_iter().flatten() {
        if let Some(f) = corpus.files.get(&cand) {
            return LinkTarget::Hit(f);
        }
    }
    LinkTarget::Miss
}

/// Any ':' before the first '/' marks the target external ("https:", "mailto:",
/// "tel:", "host:8080"…). Corpus rel paths essentially never contain a colon,
/// and a rule this blunt is deterministic where scheme-grammar parsing would
/// accumulate special cases.
fn has_scheme(url: &str) -> bool {
    match (url.find(':'), url.find('/')) {
        (Some(c), Some(s)) => c < s,
        (Some(_), None) => true,
        (None, _) => false,
    }
}

/// Normalize `a/./b/../c` → `a/c`; `..` escaping the corpus root is a miss
/// (None), not a guess.
fn normalize_rel(path: &str) -> Option<String> {
    let mut parts: Vec<&str> = Vec::new();
    for seg in path.split('/') {
        match seg {
            "" | "." => {}
            ".." => {
                parts.pop()?;
            }
            s => parts.push(s),
        }
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join("/"))
    }
}

// ─── envelope assembly + write path ──────────────────────────────────────

/// One edge ready for `_bulk`: the two ndjson lines plus the tag for
/// per-detector accounting.
pub struct AssembledEdge {
    pub detector: &'static str,
    pub edge_id: String,
    pub ndjson: Vec<u8>,
}

pub struct AssembleOutcome {
    pub edges: Vec<AssembledEdge>,
    /// Self-edges (src == dst) dropped by the assembler — counted, per §6.4.
    pub self_dropped: u64,
}

/// f32 → JSON number without widening artifacts: `0.3f32 as f64` is
/// 0.30000001192092896, which would poison every stored weight and the
/// doc-values compare downstream. The shortest f32 display ("0.3") parsed as
/// f64 is the number the contract fixtures assert.
fn clean_f64(v: f32) -> f64 {
    format!("{v}").parse().unwrap_or(f64::from(v))
}

/// Turn drafts into `_bulk` actions (§2.2 stored-type discipline: every
/// scalar a plain string/number, `invalid_at`/`expired_at` omitted — the
/// null_bitmap IS the "still valid" signal). `created_at_ms` is the one
/// non-deterministic field and never participates in `edge_id`.
pub fn assemble(drafts: &[EdgeDraft], edges_index: &str, created_at_ms: i64) -> AssembleOutcome {
    let mut edges = Vec::with_capacity(drafts.len());
    let mut self_dropped = 0u64;
    for d in drafts {
        if d.src == d.dst {
            self_dropped += 1;
            continue;
        }
        let id = edge_id(&d.src, d.edge_type, &d.dst, d.valid_at_ms);
        let tag = detector_tag_for(d.edge_type);
        let action = json!({"index": {"_index": edges_index, "_id": id}});
        let mut doc = json!({
            "edge_id": id,
            "src": d.src,
            "dst": d.dst,
            "type": d.edge_type,
            "weight": clean_f64(d.weight),
            "valid_at": d.valid_at_ms,
            "created_at": created_at_ms,
            "detector": tag,
            "confidence": clean_f64(d.confidence),
            "schema_version": EDGE_SCHEMA_VERSION,
            "src_file": d.src_file,
            "evidence": {
                "quote": d.quote,
                "source": d.src_file,
                "offset": d.offset,
            }
        });
        // Endpoint file-type labels: omitted (not null) when unknown, same
        // discipline as invalid_at — the API stream's hand-asserted edges
        // carry neither, and that absence must stay a null_bitmap fact.
        if let Some(obj) = doc.as_object_mut() {
            if !d.src_format.is_empty() {
                obj.insert("src_format".into(), json!(d.src_format));
            }
            if !d.dst_format.is_empty() {
                obj.insert("dst_format".into(), json!(d.dst_format));
            }
        }
        let mut ndjson = action.to_string().into_bytes();
        ndjson.push(b'\n');
        ndjson.extend_from_slice(doc.to_string().as_bytes());
        ndjson.push(b'\n');
        edges.push(AssembledEdge {
            detector: tag,
            edge_id: id,
            ndjson,
        });
    }
    AssembleOutcome {
        edges,
        self_dropped,
    }
}

/// Write the §2.5 brain meta doc.
///
/// A missing doc is created. An existing doc whose `nodes_index` names a
/// different non-empty set is updated in place: only `nodes_index` changes,
/// so `created_at`, `brain`, and `meta_version` stay. That is what makes
/// `brain overview` follow a later `xerj autoindex --prefix` of the same
/// folder (#2351). The same set, ignoring order and surrounding spaces, is
/// a no-op. An empty desired list does not wipe a pointer a reader already
/// resolved. `graph_api::link` still creates the doc only when it is absent.
pub fn ensure_brain_meta(
    es: &Es,
    edges_index: &str,
    brain: &str,
    nodes_index: &str,
    created_at_ms: i64,
) -> Result<()> {
    if let Some(existing) = es.get_doc(edges_index, BRAIN_META_ID)? {
        return align_existing_brain_meta(es, edges_index, existing, nodes_index);
    }
    let doc = json!({
        "meta_version": 1,
        "brain": brain,
        "nodes_index": nodes_index,
        "created_at": created_at_ms,
    });
    let outcome = write_brain_meta(es, edges_index, "create", &doc)?;
    if outcome.server_errors > 0 {
        return Err(anyhow!(
            "brain meta write failed: {}",
            outcome
                .first_server_error
                .as_deref()
                .unwrap_or("unknown server error")
        ));
    }
    if outcome.item_errors > 0 {
        // Create conflict: another writer landed between the GET and the
        // bulk. Align to this run when the doc is readable.
        if let Some(existing) = es.get_doc(edges_index, BRAIN_META_ID)? {
            return align_existing_brain_meta(es, edges_index, existing, nodes_index);
        }
        return Err(anyhow!(
            "brain meta create conflicted and the doc is not readable: {}",
            outcome
                .first_error
                .as_deref()
                .unwrap_or("unknown item error")
        ));
    }
    Ok(())
}

fn align_existing_brain_meta(
    es: &Es,
    edges_index: &str,
    existing: Value,
    nodes_index: &str,
) -> Result<()> {
    let current = existing
        .get("nodes_index")
        .and_then(Value::as_str)
        .unwrap_or("");
    if nodes_index_names(nodes_index).is_empty() || same_nodes_index(current, nodes_index) {
        return Ok(());
    }
    let mut doc = existing;
    let Some(obj) = doc.as_object_mut() else {
        return Err(anyhow!("brain meta doc is not an object"));
    };
    obj.insert("nodes_index".into(), Value::String(nodes_index.to_string()));
    let outcome = write_brain_meta(es, edges_index, "index", &doc)?;
    if outcome.server_errors > 0 || outcome.item_errors > 0 {
        return Err(anyhow!(
            "brain meta update failed: {}",
            outcome
                .first_server_error
                .as_deref()
                .or(outcome.first_error.as_deref())
                .unwrap_or("unknown error")
        ));
    }
    Ok(())
}

fn nodes_index_names(raw: &str) -> Vec<&str> {
    let mut names: Vec<&str> = raw
        .split(',')
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .collect();
    names.sort_unstable();
    names.dedup();
    names
}

fn same_nodes_index(current: &str, desired: &str) -> bool {
    nodes_index_names(current) == nodes_index_names(desired)
}

fn write_brain_meta(
    es: &Es,
    edges_index: &str,
    op: &str,
    doc: &Value,
) -> Result<crate::esclient::BulkOutcome> {
    let action = match op {
        "index" => json!({"index": {"_index": edges_index, "_id": BRAIN_META_ID}}),
        _ => json!({"create": {"_index": edges_index, "_id": BRAIN_META_ID}}),
    };
    let mut body = action.to_string().into_bytes();
    body.push(b'\n');
    body.extend_from_slice(doc.to_string().as_bytes());
    body.push(b'\n');
    es.bulk(body).context("write brain meta doc")
}

/// Soft-invalidate every live edge whose keyword `field` equals `value`.
/// Each pass re-indexes its hits with `invalid_at = expired_at = now` and
/// refreshes, so repeat-until-empty converges; the pass bound turns a broken
/// endpoint into an error instead of an infinite loop. Callers pass `src_file`
/// (edges a file taught) or `dst` (edges pointing at a file's anchor node).
pub fn invalidate_edges_by_field(
    es: &Es,
    edges_index: &str,
    field: &str,
    value: &str,
    now_ms: i64,
) -> Result<u64> {
    const MAX_PASSES: usize = 1_000;
    let query = json!({
        "query": {"bool": {
            "filter": [{"term": {field: value}}],
            "must_not": [{"exists": {"field": "invalid_at"}}]
        }},
        "size": 1000,
        "_source": true
    });
    let mut total = 0u64;
    for _ in 0..MAX_PASSES {
        // `search_present`, not `search`: the exclusion sweep (#694) may call
        // this before the edges index has ever been created (it runs ahead of
        // the graph phase's `ensure_index`). A missing index is not a failure —
        // it simply holds no edges to invalidate. The replacement-invalidation
        // caller always ensures the index first, so its behaviour is unchanged
        // (the index is present → `Some`).
        let Some(resp) = es.search_present(edges_index, &query)? else {
            return Ok(total);
        };
        let hits = resp
            .pointer("/hits/hits")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        if hits.is_empty() {
            return Ok(total);
        }
        let mut body = Vec::new();
        for hit in &hits {
            let id = hit
                .get("_id")
                .and_then(Value::as_str)
                .ok_or_else(|| anyhow!("edge hit without _id in {edges_index}"))?;
            let mut source = hit
                .get("_source")
                .and_then(Value::as_object)
                .cloned()
                .ok_or_else(|| anyhow!("edge {id} returned without _source"))?;
            source.insert("invalid_at".into(), json!(now_ms));
            source.insert("expired_at".into(), json!(now_ms));
            body.extend_from_slice(
                json!({"index": {"_index": edges_index, "_id": id}})
                    .to_string()
                    .as_bytes(),
            );
            body.push(b'\n');
            body.extend_from_slice(Value::Object(source).to_string().as_bytes());
            body.push(b'\n');
        }
        let outcome = es.bulk(body).context("invalidate prior edges")?;
        if outcome.server_errors > 0 || outcome.item_errors > 0 {
            return Err(anyhow!(
                "edge invalidation for {}={} was partial: {}",
                field,
                value,
                outcome
                    .first_server_error
                    .or(outcome.first_error)
                    .unwrap_or_else(|| "unknown bulk error".into())
            ));
        }
        total += hits.len() as u64;
        es.refresh(edges_index)?;
    }
    Err(anyhow!(
        "edge invalidation for {field}={value} still found live edges after {MAX_PASSES} passes"
    ))
}

/// Hits per page of the carry-over scans ([`scan_by_id`]).
pub const SCAN_PAGE: usize = 1000;
/// Values per `terms` filter in the carry-over scans. A corpus can hold tens
/// of thousands of un-re-read `.eml` files; one filter naming all of them is a
/// request body nobody sized, so the list is walked in slices.
pub const SCAN_TERMS: usize = 256;

/// Every hit of `query` on `index`, in `_id` order, paged with `search_after`
/// so the walk is complete at any size (a `from`/`size` window is not). A
/// missing index holds nothing and is not an error. Returns the hit count.
pub fn scan_by_id(
    es: &Es,
    index: &str,
    query: &Value,
    source: &Value,
    each: &mut dyn FnMut(&str, &serde_json::Map<String, Value>),
) -> Result<u64> {
    let mut seen = 0u64;
    let mut search_after: Option<Value> = None;
    loop {
        let mut body = json!({
            "size": SCAN_PAGE,
            "sort": [{"_id": "asc"}],
            "_source": source,
            "query": query,
        });
        if let Some(after) = &search_after {
            body["search_after"] = after.clone();
        }
        // #1212: `search_page_present`, not `search_present` — the engine
        // answers a missed default search deadline with a partial 200
        // (`timed_out`), and this walk's short-page return read one partial
        // page as the end of the index. The page variant retries a timed-out
        // page instead of returning it; a missing index is still an answer.
        let Some(resp) = es.search_page_present(index, &body)? else {
            return Ok(seen);
        };
        let hits = resp
            .pointer("/hits/hits")
            .and_then(Value::as_array)
            .ok_or_else(|| anyhow!("scan of {index} returned no hits array"))?;
        let empty = serde_json::Map::new();
        for hit in hits {
            let id = hit
                .get("_id")
                .and_then(Value::as_str)
                .ok_or_else(|| anyhow!("scan hit without _id in {index}"))?;
            let fields = hit
                .get("_source")
                .and_then(Value::as_object)
                .unwrap_or(&empty);
            each(id, fields);
            seen += 1;
        }
        if hits.len() < SCAN_PAGE {
            return Ok(seen);
        }
        search_after = hits.last().and_then(|hit| hit.get("sort")).cloned();
        if search_after.is_none() {
            return Err(anyhow!(
                "a full page of {index} came back without a continuation sort key"
            ));
        }
    }
}

/// Soft-invalidate every LIVE edge of `edge_type` taught by one of `src_files`
/// whose `edge_id` is not in `keep`.
///
/// The counterpart of [`EdgeDetector::carry_over`]: the caller re-derived the
/// edges of files it did not re-read and hands over the ids that still hold.
/// A live edge that is not among them names a parent that moved (a compacted
/// mailbox shifts every later node id) or left the corpus — it would otherwise
/// stay live pointing at a node that no longer exists. Same soft-invalidate as
/// [`invalidate_edges_by_field`]: the bi-temporal record survives.
pub fn invalidate_edges_except(
    es: &Es,
    edges_index: &str,
    edge_type: &str,
    src_files: &[&str],
    keep: &std::collections::HashSet<String>,
    now_ms: i64,
) -> Result<u64> {
    let mut stale: Vec<(String, serde_json::Map<String, Value>)> = Vec::new();
    for slice in src_files.chunks(SCAN_TERMS) {
        let query = json!({"bool": {
            "filter": [
                {"term": {"type": edge_type}},
                {"terms": {"src_file": slice}}
            ],
            "must_not": [{"exists": {"field": "invalid_at"}}]
        }});
        scan_by_id(es, edges_index, &query, &json!(true), &mut |id, source| {
            if !keep.contains(id) {
                stale.push((id.to_string(), source.clone()));
            }
        })?;
    }
    if stale.is_empty() {
        return Ok(0);
    }
    for batch in stale.chunks(SCAN_PAGE) {
        let mut body = Vec::new();
        for (id, source) in batch {
            let mut source = source.clone();
            source.insert("invalid_at".into(), json!(now_ms));
            source.insert("expired_at".into(), json!(now_ms));
            body.extend_from_slice(
                json!({"index": {"_index": edges_index, "_id": id}})
                    .to_string()
                    .as_bytes(),
            );
            body.push(b'\n');
            body.extend_from_slice(Value::Object(source).to_string().as_bytes());
            body.push(b'\n');
        }
        let outcome = es.bulk(body).context("invalidate superseded edges")?;
        if outcome.server_errors > 0 || outcome.item_errors > 0 {
            return Err(anyhow!(
                "invalidation of superseded {edge_type} edges was partial: {}",
                outcome
                    .first_server_error
                    .or(outcome.first_error)
                    .unwrap_or_else(|| "unknown bulk error".into())
            ));
        }
    }
    es.refresh(edges_index)?;
    Ok(stale.len() as u64)
}

/// Soft-invalidate every live edge a file taught (`src_file` == `rel`). The
/// replacement hook (§6.6.3): runs before this run rewrites the file's edges,
/// so it only matches prior generations. Also reused by the exclusion sweep.
pub fn invalidate_prior_edges(es: &Es, edges_index: &str, rel: &str, now_ms: i64) -> Result<u64> {
    invalidate_edges_by_field(es, edges_index, "src_file", rel, now_ms)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// §2.3 pin vector — xerj-api carries a byte-identical copy of `edge_id`;
    /// this shared vector is what keeps the two in lockstep.
    #[test]
    fn edge_id_pin_vector() {
        assert_eq!(
            edge_id("note-alpha", "wikilink", "note-beta", 1753600000000),
            "bef814a75bd3d914c3e561f610154304"
        );
    }

    #[test]
    fn edge_id_is_valid_at_sensitive() {
        let a = edge_id("a", "t", "b", 1);
        assert_eq!(a, edge_id("a", "t", "b", 1));
        assert_ne!(a, edge_id("a", "t", "b", 2));
        assert_ne!(a, edge_id("a", "u", "b", 1));
    }

    #[test]
    fn brain_names_reject_the_edges_suffix_and_bad_shapes() {
        assert!(validate_brain("notes").is_ok());
        assert!(validate_brain("a.b-c_9").is_ok());
        assert!(validate_brain("kb-edges").is_err());
        assert!(validate_brain("").is_err());
        assert!(validate_brain("-notes").is_err());
        assert!(validate_brain("Notes").is_err());
        assert!(validate_brain("a..b").is_err());
    }

    #[test]
    fn assembler_drops_self_edges_and_stamps_the_envelope() {
