            "go",
            "package p\nconst Limit = 10\nvar Table = []byte{1}\nfunc F(){ var local = 1; _ = local }\n",
        );
        assert!(has(&s, "Limit", "const"), "got {s:?}");
        assert!(has(&s, "Table", "static"), "got {s:?}");
        // Function-local `var` must NOT be captured, or defs fills with locals.
