/// Leading-ASCII-whitespace trim over a raw byte buffer (the `str::trim_start`
/// equivalent that needs no UTF-8 validity).
fn trim_start_bytes(b: &[u8]) -> &[u8] {
    let mut i = 0;
    while i < b.len() && b[i].is_ascii_whitespace() {
        i += 1;
    }
    &b[i..]
}

/// Drain a raw value buffer into a `String`, decoding UTF-8 once at the
/// boundary.  Invalid sequences become U+FFFD rather than mojibake — the
/// previous per-byte `as char` cast turned every multi-byte character into two
/// Latin-1 characters.
fn take_utf8(buf: &mut Vec<u8>) -> String {
    let s = String::from_utf8_lossy(buf).into_owned();
    buf.clear();
    s
}

#[cfg(test)]
mod utf8_safety_tests {
    use super::*;

    /// Regression: the head/value buffers used to be `String`s fed with
    /// `b as char`, which turns any byte >= 0x80 into a Latin-1 codepoint that
    /// re-encodes to TWO UTF-8 bytes. Byte offsets into the buffer then stopped
    /// being char boundaries and `head[..6]` panicked — and with
    /// `panic = "abort"` that killed the entire `autoindex` run instead of
    /// skipping one file. An em-dash in a comment was enough to trigger it.
    #[test]
    fn trim_start_bytes_handles_multibyte_without_panicking() {
        // "  — INSERT INTO t VALUES" — the em-dash is 3 UTF-8 bytes.
        let raw = "  — INSERT INTO t VALUES".as_bytes();
        let t = trim_start_bytes(raw);
        assert!(!t.is_empty());
        assert!(!t[0].is_ascii_whitespace());
        // The slice that used to panic is now a plain byte slice.
        assert!(t.len() >= 6);
        let _ = &t[..6];
    }

    /// Regression: `process_statement_head` guarded with `trimmed.len() < 12`
    /// (a BYTE length) and then sliced `trimmed[..12]` on a `&str`. Any head
    /// whose 12th byte lands inside a multi-byte character passed the guard and
    /// panicked on the slice. Found by indexing ClickHouse: fixtures containing
    /// 'ا' and '设' each aborted the whole `autoindex` run (`panic = "abort"`).
    /// Neither of these heads is a CREATE TABLE — the only correct behaviour is
    /// to return quietly, never to abort the process.
    #[test]
    fn statement_head_with_multibyte_at_byte_12_does_not_panic() {
        let mut tables: HashMap<String, Vec<String>> = HashMap::new();
        for head in [
            "-- comment ا rest of the line", // 'ا' spans bytes 11..13
            "-- comment 设计 rest",          // '设' spans bytes 11..14
            "  — leading em-dash then text", // multibyte before byte 12
            "短",                            // shorter than 12 bytes
            "",
        ] {
            process_statement_head(head.as_bytes(), &mut tables);
        }
        assert!(tables.is_empty(), "none of these heads declare a table");
    }

    /// The byte-wise comparison must still accept a real CREATE TABLE, in any
    /// case, and must not regress into matching a mere prefix.
    #[test]
    fn statement_head_still_captures_create_table() {
        let mut tables: HashMap<String, Vec<String>> = HashMap::new();
        process_statement_head(b"  CrEaTe TaBlE users (id INT, name TEXT)", &mut tables);
        assert_eq!(
            tables.get("users").map(|c| c.len()),
            Some(2),
            "case-insensitive CREATE TABLE must still be captured"
        );

        let mut other: HashMap<String, Vec<String>> = HashMap::new();
        process_statement_head("create tableX ا (id INT)".as_bytes(), &mut other);
        assert!(other.is_empty(), "`create tableX` is not `create table`");
    }

    #[test]
    fn take_utf8_round_trips_multibyte_values() {
        let mut buf: Vec<u8> = "naïve — 日本語".as_bytes().to_vec();
        let s = take_utf8(&mut buf);
        assert_eq!(s, "naïve — 日本語", "multibyte values must not mojibake");
        assert!(buf.is_empty(), "buffer must be drained");
    }

    #[test]
    fn take_utf8_replaces_invalid_sequences_instead_of_panicking() {
        let mut buf: Vec<u8> = vec![0xff, 0xfe, b'o', b'k'];
        let s = take_utf8(&mut buf);
        assert!(s.ends_with("ok"));
        assert!(s.contains('\u{FFFD}'), "invalid bytes become U+FFFD");
    }

    /// The exact shape that crashed: a non-SQL file whose text contains an
    /// `INSERT … VALUES` fragment alongside multibyte punctuation. The sniffer
    /// can hand this to the SQL-dump extractor; it must not panic.
    #[test]
    fn insert_values_fragment_with_em_dash_does_not_panic() {
        let src = "//! SQL dump — targeted streaming parser, O(1) memory per tuple.\n\
                   //! No sqlparser: multi-row `INSERT … VALUES (…),(…)…` statements —\n\
                   //! parsed byte-by-byte.\n";
        // Drive the same keyword-detection logic the streaming loop runs.
        let mut head: Vec<u8> = Vec::new();
        for b in src.as_bytes() {
            head.push(*b);
            if (*b == b'S' || *b == b's') && head.len() >= 6 {
                let tail = &head[head.len() - 6..];
                let trimmed = trim_start_bytes(&head);
                if tail.eq_ignore_ascii_case(b"values") && trimmed.len() >= 6 {
                    // This comparison is what used to slice mid-character.
                    let _ = trimmed[..6].eq_ignore_ascii_case(b"insert");
                }
            }
        }
    }
}

//! Plain text: prose files become one document record (title = first line,
//! body split into ~32KB sections); line-oriented files become overlapping
//! line-window chunks.
//!
//! ## Why line-oriented text is chunked, not emitted per line
//!
//! `extract_lines` used to emit ONE record per line. That makes BM25 nearly
//! useless for anything but exact-substring lookup: relevance is scored per
//! document, so a single line can only match when it literally contains the
//! query terms. A question phrased in its own words — the normal case for an
//! agent — matches nothing, because no single line carries all of it.
//!
//! Measured on this repository (234 files, 170k LOC + docs + 460 commit
//! messages), answering 8 "where/why is X" questions:
//!
//!   one record per line ....... 3/8 answers found
//!   40-line windows, 10 overlap 8/8 answers found
//!
//! The window carries enough surrounding context that a natural-language
//! query matches the region, and the overlap stops an answer from being split
//! across a boundary. `start_line` / `end_line` travel with each chunk so a
//! caller can jump straight to the source — the old per-line record only
//! carried an opaque byte locator.

use super::{emit_document, ExtractStats, FieldOrigin, RawRecord, Sink, MAX_RECORDS_PER_FILE};
use anyhow::Result;
use serde_json::{Map, Value};
use std::path::Path;

const TXT_CAP: u64 = 16 << 20;

/// Lines per chunk, and how many of them the next chunk repeats.  40/10 is the
/// configuration measured at 8/8 answer recall (see module docs); the overlap
/// is what keeps an answer that straddles a boundary retrievable from both
/// sides.
const CHUNK_LINES: usize = 40;
const CHUNK_OVERLAP: usize = 10;
/// Byte ceiling per chunk, so a file of very long lines cannot produce a
/// multi-megabyte record that would blow up `_source` on every hit.
const CHUNK_MAX_BYTES: usize = 8 << 10;

pub fn extract_prose(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
    let mut stats = ExtractStats::default();
    let Some(bytes) = super::read_whole(path, gzip, TXT_CAP)? else {
        stats.junk += 1;
        return Ok(stats);
    };
    let (text, _) = crate::sniff::decode_text(&bytes);
    let title = text
        .lines()
        .find(|l| !l.trim().is_empty())
        .map(|l| {
            let t = l.trim();
            let mut s: String = t.chars().take(200).collect();
            if s.len() < t.len() {
                s.push('…');
            }
            s
        })
        .unwrap_or_else(|| {
            path.file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| "untitled".into())
        });
    // #1941: a prose section's record must carry the file line it starts on,
    // or a hit has no line to cite (`guide.md:1` for a passage at line 245).
    // `body` below is `text.trim()`, so shift by the newlines the trim removed.
    let leading = &text[..text.len() - text.trim_start().len()];
    let base_line = 1 + leading.bytes().filter(|b| *b == b'\n').count() as u64;
    emit_document(
        &title,
        &[],
        text.trim(),
        Some(base_line),
        MAX_RECORDS_PER_FILE,
        sink,
        &mut stats,
    );
    Ok(stats)
}

pub fn extract_lines(
    path: &Path,
    gzip: bool,
    limit_bytes: Option<u64>,
    sink: Sink,
) -> Result<ExtractStats> {
    let mut r = super::open_reader(path, gzip, limit_bytes)?;
    let mut stats = ExtractStats::default();
    let mut offset = 0u64;
    let mut buf: Vec<u8> = Vec::new();

    // Sliding window over non-blank lines.  Each entry carries the line's text,
    // its 1-based line number, and the byte offset it started at (the offset of
    // the window's first line becomes the chunk locator, so ids stay stable
    // across re-runs exactly like the old per-line records did).
    let mut window: Vec<(String, usize, u64)> = Vec::with_capacity(CHUNK_LINES);
    let mut line_no = 0usize;
    let mut stopped = false;

    // Emit `window[..CHUNK_LINES]` as one record, then drop the non-overlapping
    // prefix.  Returns false when the sink asks us to stop.
    fn flush(
        window: &mut Vec<(String, usize, u64)>,
        drain: bool,
        stats: &mut ExtractStats,
        sink: Sink,
    ) -> bool {
        if window.is_empty() {
            return true;
        }
        let mut text = String::new();
        let mut used = 0usize;
        for (l, _, _) in window.iter() {
            if used > 0 && used + l.len() + 1 > CHUNK_MAX_BYTES {
                break;
            }
            if used > 0 {
                text.push('\n');
            }
            text.push_str(l);
            used += l.len() + 1;
        }
        if text.trim().is_empty() {
            return true;
        }
        let start_line = window[0].1;
        let start_byte = window[0].2;
        let end_line = window[window.len() - 1].1;

        let mut fields = Map::new();
        fields.insert("text".into(), Value::String(text));
        fields.insert(
            "start_line".into(),
            Value::Number((start_line as u64).into()),
        );
        fields.insert("end_line".into(), Value::Number((end_line as u64).into()));
        stats.records += 1;
        let ok = sink(RawRecord {
            fields,
            locator: format!("b{start_byte}"),
            group: None,
            // text/start_line/end_line describe this chunker, not the file.
            origin: FieldOrigin::Extractor,
        });
        if drain {
            window.clear();
        } else {
            let keep = CHUNK_OVERLAP.min(window.len());
            window.drain(..window.len() - keep);
        }
        ok
    }

    loop {
        buf.clear();
        let n = super::jsonl::read_capped_line(&mut r, &mut buf)?;
        if n == 0 {
            break;
        }
        let start = offset;
        offset += n as u64;
        line_no += 1;
        let (line, _) = crate::sniff::decode_text(&buf);
        let line = line.trim_end_matches(['\n', '\r']);
        if line.trim().is_empty() {
            continue;
        }
        window.push((line.to_string(), line_no, start));
        if window.len() >= CHUNK_LINES && !flush(&mut window, false, &mut stats, sink) {
            stopped = true;
            break;
        }
    }
    // Trailing partial window (also the whole-file case for short files).
    if !stopped {
        flush(&mut window, true, &mut stats, sink);
    }
    Ok(stats)
}

#[cfg(test)]
mod chunk_tests {
    use super::*;
    use std::io::Write;

    fn run(lines: &[&str]) -> Vec<(String, u64, u64, String)> {
        let dir = std::env::temp_dir().join(format!("xerj-chunk-{}", lines.len()));
        std::fs::create_dir_all(&dir).unwrap();
        let p = dir.join("f.txt");
        let mut f = std::fs::File::create(&p).unwrap();
        for l in lines {
            writeln!(f, "{l}").unwrap();
        }
        drop(f);
        let mut out = Vec::new();
        {
            let mut sink = |r: RawRecord| {
                out.push((
                    r.fields["text"].as_str().unwrap().to_string(),
                    r.fields["start_line"].as_u64().unwrap(),
                    r.fields["end_line"].as_u64().unwrap(),
                    r.locator.clone(),
                ));
                true
            };
            extract_lines(&p, false, None, &mut sink).unwrap();
        }
        let _ = std::fs::remove_file(&p);
        out
    }

    #[test]
    fn short_file_is_one_chunk_covering_every_line() {
        let lines: Vec<String> = (1..=10).map(|i| format!("line {i}")).collect();
        let refs: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
        let out = run(&refs);
        assert_eq!(out.len(), 1);
        assert_eq!((out[0].1, out[0].2), (1, 10));
        assert!(out[0].0.contains("line 1") && out[0].0.contains("line 10"));
    }

    /// The property that fixed retrieval: consecutive chunks OVERLAP, so an
    /// answer straddling a boundary is findable from either side.
    #[test]
    fn consecutive_chunks_overlap_by_the_configured_amount() {
        let lines: Vec<String> = (1..=100).map(|i| format!("line {i}")).collect();
        let refs: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
        let out = run(&refs);
        assert!(out.len() >= 2, "100 lines must produce several chunks");
        for w in out.windows(2) {
            let (_, _s0, e0, _) = &w[0];
            let (_, s1, _, _) = &w[1];
            assert!(
                s1 <= e0,
                "chunk {s1} must start at/before previous end {e0}"
            );
            let repeated = e0 - s1 + 1;
            assert_eq!(
                repeated as usize, CHUNK_OVERLAP,
                "expected {CHUNK_OVERLAP} repeated lines across the boundary"
            );
        }
    }

    #[test]
    fn every_line_appears_in_some_chunk() {
        let lines: Vec<String> = (1..=95).map(|i| format!("unique{i}")).collect();
        let refs: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
        let out = run(&refs);
        for i in 1..=95 {
            let tok = format!("unique{i}");
            assert!(
                out.iter()
                    .any(|(t, _, _, _)| t.split('\n').any(|l| l == tok)),
                "line {i} lost"
            );
        }
    }

    #[test]
    fn line_numbers_are_one_based_and_ordered() {
        let lines: Vec<String> = (1..=60).map(|i| format!("l{i}")).collect();
        let refs: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
        let out = run(&refs);
        assert_eq!(out[0].1, 1, "first chunk starts at line 1, not 0");
        for (_, s, e, _) in &out {
            assert!(s <= e);
        }
    }

    /// A file of very long lines must not produce an unbounded record.
    #[test]
    fn chunk_is_byte_capped() {
        let long = "x".repeat(4000);
        let lines: Vec<&str> = (0..50).map(|_| long.as_str()).collect();
        let out = run(&lines);
        for (t, _, _, _) in &out {
            assert!(
                t.len() <= CHUNK_MAX_BYTES + 4001,
                "chunk of {} bytes exceeds the cap",
                t.len()
            );
        }
    }

    /// Blank lines are skipped but must not desynchronise the line numbering.
    #[test]
    fn blank_lines_do_not_break_numbering() {
        let out = run(&["alpha", "", "beta", "", "gamma"]);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0].1, 1);
        assert_eq!(
            out[0].2, 5,
            "end_line must be the real file line of `gamma`"
        );
    }

    /// #1941: a prose section carries the FILE line it starts on, so a hit can
    /// cite `guide.md:4`, not the record-relative `:1`. The source is the
    /// oracle — a section can start mid-line after a hard cut.
    #[test]
    fn prose_sections_carry_their_file_start_line() {
        let paragraph = "word ".repeat(700); // 3500 chars: forces section cuts
        let text = format!("\n\n\n{paragraph}\n\n{paragraph}\n\n{paragraph}\n");
        let dir = std::env::temp_dir().join(format!("xerj-prose-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let p = dir.join("guide.md");
        std::fs::write(&p, &text).unwrap();
        let mut got: Vec<(u64, String)> = Vec::new();
        {
            let mut sink = |r: RawRecord| {
                got.push((
                    r.fields["start_line"]
                        .as_u64()
                        .expect("every prose section carries start_line"),
                    r.fields["body"].as_str().unwrap().to_string(),
                ));
                true
            };
            extract_prose(&p, false, &mut sink).unwrap();
        }
        let _ = std::fs::remove_file(&p);
        let lines: Vec<&str> = text.lines().collect();
        assert!(got.len() > 1, "3500-char paragraphs must split");
        assert_eq!(
            got[0].0, 4,
            "three leading blank lines put the body on line 4"
        );
        for (line, body) in &got {
            let first = body.lines().next().unwrap_or("");
            let source = lines
                .get(*line as usize - 1)
                .unwrap_or_else(|| panic!("start_line {line} is past the file"));
            assert!(
                source.ends_with(first),
                "start_line {line} does not hold the section start: {first:?} vs {source:?}"
            );
        }
    }
}

//! Unity text-serialized assets — streaming multi-document splitter — and
//! `.meta` sidecars.
//!
//! Unity YAML is a multi-document stream where every document opens with
//! `--- !u!<classId> &<fileID>` (optionally suffixed `stripped` for prefab
//! instances). serde_yaml cannot be used on the whole stream: it resolves
//! anchors internally and never exposes the anchor NAME, and the `fileID`
//! that makes Unity objects joinable lives in that anchor. So the splitter
//! owns the document boundaries (a cheap line prefix match) and hands each
//! body — plain YAML once the `%YAML`/`%TAG` header is dropped — to
//! serde_yaml individually. Owning the boundaries is also what makes it safe
//! to `continue` past a corrupt document: unlike `yaml_x`, there is no
//! iterator that would re-yield the same broken document forever.
//!
//! Files stream line-by-line (real scenes can exceed 200 MB; a single
//! AnimationClip document can be tens of MB), with a 16 MiB per-document
//! cap: over-cap documents are junked and skipped to the next boundary,
//! the rest of the file survives.
//!
//! Emitted fields per object document:
//! - `unity_class`      body's top-level key (authoritative), else class-id table
//! - `unity_class_id`   from the `!u!<id>` tag
//! - `file_id`          from the `&<anchor>` — the join key for local refs
//! - `stripped`         only present (true) on stripped prefab-instance docs
//! - `name`             `m_Name` when present
//! - `ref_guids`        deduped guids of every `{fileID, guid, type}` reference
//! - `script_guid`      the `m_Script` reference's guid (MonoBehaviour → .cs)
//! - flattened body fields
//!
//! `ref_guids` is a multi-valued keyword array; each guid is indexed as its
//! own term (xerj-org/xerj#332, fixed in #470), so a `term`/`match` on a
//! single guid matches before and after a flush. The documented "which
//! scenes use this script?" query still goes through the single-valued
//! `script_guid`, `script_path` and `script_class`.
//!
//! `.meta` sidecars emit ONE record: `guid`, `asset_name`, `importer`, and
//! flattened settings. The root-relative `asset_path` (and the
//! `script_path`/`script_class` denormalization on MonoBehaviour records) is
//! stamped by the pipeline, which knows the walk root — extractors stay
//! per-file pure.

use super::{flatten_object, yaml_to_json, ExtractStats, FieldOrigin, RawRecord, Sink, MAX_LINE};
use anyhow::Result;
use serde_json::{Map, Value};
use std::path::Path;

/// Per-document cap. One logical unit follows the `MAX_LINE` convention;
/// 16 MiB covers large AnimationClip / font documents while bounding memory.
/// (A 4 MiB cap was considered and rejected: it junks those documents.)
const DOC_CAP: usize = 16 << 20;

const META_CAP: u64 = 16 << 20;

/// Field names this extractor invents on object records. A body field with
/// the same name (possible on MonoBehaviour custom fields) is renamed
/// `data_<name>` rather than dropped, mirroring the `ax_*` collision policy.
const RESERVED: &[&str] = &[
    "unity_class",
    "unity_class_id",
    "file_id",
    "stripped",
    "name",
    "ref_guids",
    "script_guid",
    "script_path",
    "script_class",
];

pub fn extract_unity(
    path: &Path,
    gzip: bool,
    limit_bytes: Option<u64>,
    sink: Sink,
) -> Result<ExtractStats> {
    let mut r = super::open_reader(path, gzip, limit_bytes)?;
    let mut stats = ExtractStats::default();
    let mut offset: u64 = 0;
    let mut line: Vec<u8> = Vec::new();
    let mut doc: Vec<u8> = Vec::new();
    let mut header: Option<DocHeader> = None;
    let mut skipping = false;
    loop {
        line.clear();
        let n = super::jsonl::read_capped_line(&mut r, &mut line)?;
        let eof = n == 0;
        offset += n as u64;
        let boundary = if eof { None } else { parse_boundary(&line) };
        if eof || boundary.is_some() {
            if let Some(h) = header.take() {
                if skipping {
                    skipping = false;
                } else {
                    let truncated = eof && limit_bytes.is_some_and(|l| offset >= l);
                    if !emit_doc(&h, &doc, truncated, &mut stats, sink) {
                        return Ok(stats);
                    }
                }
            }
            doc.clear();
            header = boundary;
            if eof {
                break;
            }
            continue;
        }
        if header.is_none() || skipping {
            continue; // %YAML/%TAG preamble, or discarding an over-cap doc
        }
        if doc.len() + line.len() > DOC_CAP {
            stats.junk += 1;
            skipping = true;
            doc.clear();
            continue;
        }
        doc.extend_from_slice(&line);
    }
    // Empty yield from a FULL read means the file was preamble-only (or
    // junk-shaped throughout) — record it. A sampling read that truncated
    // before the first document completed is not evidence of anything.
    let truncated_run = limit_bytes.is_some_and(|l| offset >= l);
    if stats.records == 0 && stats.junk == 0 && !truncated_run {
        stats.junk += 1;
    }
    Ok(stats)
}

struct DocHeader {
    class_id: i64,
    /// Raw anchor text (handles negative 64-bit ids verbatim).
    file_id: String,
    stripped: bool,
}

/// `--- !u!<classId> &<fileID>[ stripped]` — cheap manual parse, no regex on
/// the hot per-line path.
fn parse_boundary(line: &[u8]) -> Option<DocHeader> {
    let s = std::str::from_utf8(line).ok()?.trim_end();
    let rest = s.strip_prefix("--- !u!")?;
    let (id_part, rest) = rest.split_once(" &")?;
    let class_id: i64 = id_part.trim().parse().ok()?;
    let (anchor, tail) = match rest.split_once(' ') {
        Some((a, t)) => (a, t.trim()),
        None => (rest, ""),
    };
    let anchor = anchor.trim();
    if anchor.is_empty() || !anchor.chars().all(|c| c.is_ascii_digit() || c == '-') {
        return None;
    }
    Some(DocHeader {
        class_id,
        file_id: anchor.to_string(),
        stripped: tail == "stripped",
    })
}

fn emit_doc(
    h: &DocHeader,
    body: &[u8],
    truncated_by_sampling: bool,
    stats: &mut ExtractStats,
    sink: Sink,
) -> bool {
    let text = String::from_utf8_lossy(body);
    let parsed: serde_yaml::Value = match serde_yaml::from_str(&text) {
        Ok(v) => v,
        Err(_) => {
            if !truncated_by_sampling {
                stats.junk += 1;
            }
            return true;
        }
    };
    let jv = yaml_to_json(parsed);
    let (class_from_body, inner) = match jv {
        Value::Object(m) if m.len() == 1 => {
            let (k, v) = m.into_iter().next().expect("len checked");
            (Some(k), v)
        }
        other => (None, other),
    };
    let unity_class = class_from_body.unwrap_or_else(|| {
        class_name(h.class_id)
            .map(str::to_string)
            .unwrap_or_else(|| format!("class_{}", h.class_id))
    });

    let mut refs: Vec<String> = Vec::new();
    let mut script_guid: Option<String> = None;
    collect_guid_refs(&inner, &mut refs);
    if let Some(script) = inner.get("m_Script") {
        if let Some(g) = script.get("guid").and_then(Value::as_str) {
            script_guid = Some(g.to_string());
        }
    }

    let mut fields = match inner {
        Value::Object(m) => flatten_object(m),
        Value::Null => Map::new(),
        other => {
            let mut m = Map::new();
            m.insert("value".into(), other);
            m
        }
    };
    for k in RESERVED {
        if let Some(v) = fields.remove(*k) {
            fields.insert(format!("data_{k}"), v);
        }
    }
    if let Some(Value::String(n)) = fields.get("m_Name") {
        if !n.is_empty() {
            fields.insert("name".into(), Value::String(n.clone()));
        }
    }
    fields.insert("unity_class".into(), Value::String(unity_class.clone()));
    fields.insert("unity_class_id".into(), Value::Number(h.class_id.into()));
    fields.insert("file_id".into(), Value::String(h.file_id.clone()));
    if h.stripped {
        fields.insert("stripped".into(), Value::Bool(true));
    }
    if !refs.is_empty() {
        let mut seen = std::collections::HashSet::new();
        let deduped: Vec<Value> = refs
            .into_iter()
            .filter(|g| seen.insert(g.clone()))
            .map(Value::String)
            .collect();
        fields.insert("ref_guids".into(), Value::Array(deduped));
    }
    if let Some(g) = script_guid {
        fields.insert("script_guid".into(), Value::String(g));
    }

    stats.records += 1;
    sink(RawRecord {
        fields,
        locator: format!("u{}", h.file_id),
        group: Some(unity_class),
        // Body field names are Unity's serialization vocabulary plus per-script
        // custom fields; letting them cluster would split MonoBehaviours into
        // schema-similarity datasets and re-home documents when scripts change
        // (issue #178). Family+group clustering gives one stable dataset per
        // Unity class instead.
        origin: FieldOrigin::Extractor,
    })
}

/// Walk the parsed document for `{fileID, guid, type}` reference mappings and
/// collect every guid, including inside arrays (`m_Modifications` — prefab
/// overrides — is where the highest-value references live).
fn collect_guid_refs(v: &Value, out: &mut Vec<String>) {
    match v {
        Value::Object(m) => {
            if m.contains_key("fileID") {
                if let Some(g) = m.get("guid").and_then(Value::as_str) {
                    out.push(g.to_string());
                }
            }
            for vv in m.values() {
                collect_guid_refs(vv, out);
            }
        }
        Value::Array(a) => {
            for vv in a {
                collect_guid_refs(vv, out);
            }
        }
        _ => {}
    }
}

pub fn extract_meta(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
    let mut stats = ExtractStats::default();
    let Some(bytes) = super::read_whole(path, gzip, META_CAP)? else {
        stats.junk += 1;
        return Ok(stats);
    };
    let (text, _) = crate::sniff::decode_text(&bytes);
    let text = text.trim_start_matches('\u{feff}');
    let parsed: serde_yaml::Value = match serde_yaml::from_str(text) {
        Ok(v) => v,
        Err(_) => {
            stats.junk += 1;
            return Ok(stats);
        }
    };
    let Value::Object(m) = yaml_to_json(parsed) else {
        stats.junk += 1;
        return Ok(stats);
    };
    let guid = m.get("guid").and_then(Value::as_str).map(str::to_string);
    let importer = m
        .keys()
        .find(|k| k.ends_with("Importer") || k.ends_with("importer"))
        .cloned();
    let mut fields = flatten_object(m);
    if let Some(g) = guid {
        fields.insert("guid".into(), Value::String(g));
    }
    if let Some(imp) = importer {
        fields.insert("importer".into(), Value::String(imp));
    }
    if let Some(name) = path
        .file_name()
        .and_then(|n| n.to_str())
        .and_then(|n| n.strip_suffix(".meta"))
    {
        fields.insert("asset_name".into(), Value::String(name.to_string()));
    }
    stats.records += 1;
    sink(RawRecord {
        fields,
        locator: "meta".into(),
        group: None,
        origin: FieldOrigin::Extractor,
    });
    Ok(stats)
}

/// Fallback names for documents whose body failed to yield a top-level key
/// (the body key is authoritative when present). Sourced from Unity's public
/// class-id reference; unknown ids render `class_<id>`.
fn class_name(id: i64) -> Option<&'static str> {
    Some(match id {
        1 => "GameObject",
        2 => "Component",
        4 => "Transform",
        20 => "Camera",
