// The `MAX_LINE` import is load-bearing indirectly: `read_capped_line` caps
// each physical line at 16 MiB, and DOC_CAP matches it so a single-line
// document cannot bypass the document cap.
const _: () = assert!(DOC_CAP == MAX_LINE);

#[cfg(test)]
mod tests {
    use super::*;

    const SCENE: &str = "\u{feff}%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n--- !u!1 &1234567890\nGameObject:\n  m_ObjectHideFlags: 0\n  m_Name: Player\n  m_IsActive: 1\n--- !u!4 &1234567891\nTransform:\n  m_GameObject: {fileID: 1234567890}\n  m_LocalPosition: {x: 0, y: 1.5, z: 0}\n--- !u!114 &1234567892\nMonoBehaviour:\n  m_GameObject: {fileID: 1234567890}\n  m_Script: {fileID: 11500000, guid: abc123def456, type: 3}\n  m_EditorClassIdentifier: \n  speed: 4.5\n  target: {fileID: 5555, guid: fedcba987654, type: 2}\n";

    fn run(text: &str, limit: Option<u64>) -> (ExtractStats, Vec<RawRecord>) {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("t.unity");
        std::fs::write(&path, text).unwrap();
        let mut recs = Vec::new();
        let stats = extract_unity(&path, false, limit, &mut |r| {
            recs.push(r);
            true
        })
        .unwrap();
        (stats, recs)
    }

    fn run_meta(text: &str, name: &str) -> (ExtractStats, Vec<RawRecord>) {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join(name);
        std::fs::write(&path, text).unwrap();
        let mut recs = Vec::new();
        let stats = extract_meta(&path, false, &mut |r| {
            recs.push(r);
            true
        })
        .unwrap();
        (stats, recs)
    }

    #[test]
    fn each_document_becomes_one_record_with_class_and_file_id() {
        let (stats, recs) = run(SCENE, None);
        assert_eq!((stats.records, stats.junk), (3, 0));
        assert_eq!(recs[0].fields["unity_class"], "GameObject");
        assert_eq!(recs[0].fields["unity_class_id"], 1);
        assert_eq!(recs[0].fields["file_id"], "1234567890");
        assert_eq!(recs[0].fields["name"], "Player");
        assert_eq!(recs[0].locator, "u1234567890");
        assert_eq!(recs[0].group.as_deref(), Some("GameObject"));
        assert_eq!(recs[1].fields["unity_class"], "Transform");
        assert_eq!(
            recs[1].fields["m_LocalPosition_y"], 1.5,
            "nested mappings flatten like every other extractor"
        );
    }

    #[test]
    fn monobehaviour_carries_script_guid_and_deduped_ref_guids() {
        let (_, recs) = run(SCENE, None);
        let mb = &recs[2];
        assert_eq!(mb.fields["unity_class"], "MonoBehaviour");
        assert_eq!(mb.fields["script_guid"], "abc123def456");
        assert_eq!(
            mb.fields["ref_guids"],
            serde_json::json!(["abc123def456", "fedcba987654"])
        );
        assert_eq!(mb.fields["speed"], 4.5, "custom script fields survive");
    }

    #[test]
    fn stripped_and_negative_file_ids_parse() {
        let text = "%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n--- !u!4 &-8679921383154817045 stripped\nTransform:\n  m_PrefabInstance: {fileID: 100100000, guid: 0123456789abcdef, type: 3}\n";
        let (stats, recs) = run(text, None);
        assert_eq!((stats.records, stats.junk), (1, 0));
        assert_eq!(recs[0].fields["file_id"], "-8679921383154817045");
        assert_eq!(recs[0].fields["stripped"], true);
        assert_eq!(recs[0].locator, "u-8679921383154817045");
    }

    #[test]
    fn crlf_line_endings_are_tolerated() {
        let text = SCENE.replace('\n', "\r\n");
        let (stats, recs) = run(&text, None);
        assert_eq!((stats.records, stats.junk), (3, 0));
        assert_eq!(recs[2].fields["script_guid"], "abc123def456");
    }

    #[test]
    fn a_corrupt_document_junks_only_itself() {
        let text = "%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n--- !u!1 &1\nGameObject:\n  m_Name: A\n--- !u!4 &2\n\t{{{ not yaml\n--- !u!1 &3\nGameObject:\n  m_Name: B\n";
        let (stats, recs) = run(text, None);
        assert_eq!(stats.junk, 1);
        assert_eq!(stats.records, 2);
        assert_eq!(recs[1].fields["name"], "B");
    }

    #[test]
    fn an_over_cap_document_is_skipped_and_the_stream_continues() {
        let mut text = String::from("%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n--- !u!74 &1\nAnimationClip:\n  m_Name: huge\n  data: ");
        text.push_str(&"x".repeat(DOC_CAP + 1024));
        text.push_str("\n--- !u!1 &2\nGameObject:\n  m_Name: after\n");
        let (stats, recs) = run(&text, None);
        assert_eq!(stats.junk, 1, "the oversized doc is junked, not fatal");
        assert_eq!(stats.records, 1);
        assert_eq!(recs[0].fields["name"], "after");
    }

    #[test]
    fn a_doc_cut_short_by_a_sampling_limit_is_not_junk() {
        let (stats, _) = run(SCENE, Some(120));
        assert_eq!(stats.junk, 0, "sampling truncation is not corruption");
        assert!(stats.records <= 1);
    }

    #[test]
    fn sampling_early_stop_via_sink_leaves_no_junk() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("t.unity");
        std::fs::write(&path, SCENE).unwrap();
        let mut n = 0;
        let stats = extract_unity(&path, false, None, &mut |_r| {
            n += 1;
            n < 2
        })
        .unwrap();
        assert_eq!(n, 2);
        assert_eq!(stats.junk, 0);
    }

    #[test]
    fn locators_are_idempotent_across_runs() {
        let (_, a) = run(SCENE, None);
        let (_, b) = run(SCENE, None);
        let la: Vec<_> = a.iter().map(|r| r.locator.clone()).collect();
        let lb: Vec<_> = b.iter().map(|r| r.locator.clone()).collect();
        assert_eq!(la, lb);
    }

    #[test]
    fn a_reserved_body_field_is_renamed_not_clobbered() {
        let text = "%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n--- !u!114 &1\nMonoBehaviour:\n  name: custom-field\n  m_Name: Real\n";
        let (_, recs) = run(text, None);
        assert_eq!(recs[0].fields["data_name"], "custom-field");
        assert_eq!(recs[0].fields["name"], "Real");
    }

    #[test]
    fn unknown_class_id_with_unparseable_body_still_names_the_class() {
        let text = "%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n--- !u!999999 &1\nsome scalar\n";
        let (stats, recs) = run(text, None);
        assert_eq!(stats.records, 1);
        assert_eq!(recs[0].fields["unity_class"], "class_999999");
    }

    #[test]
    fn meta_yields_guid_importer_and_asset_name() {
        let text = "fileFormatVersion: 2\nguid: 9f1c4d0ab2e34f6\nMonoImporter:\n  externalObjects: {}\n  serializedVersion: 2\n";
        let (stats, recs) = run_meta(text, "Player.cs.meta");
        assert_eq!((stats.records, stats.junk), (1, 0));
        assert_eq!(recs[0].fields["guid"], "9f1c4d0ab2e34f6");
        assert_eq!(recs[0].fields["importer"], "MonoImporter");
        assert_eq!(recs[0].fields["asset_name"], "Player.cs");
        assert_eq!(recs[0].locator, "meta");
    }

    #[test]
    fn a_file_with_only_preamble_is_junk() {
        let (stats, recs) = run("%YAML 1.1\n%TAG !u! tag:unity3d.com,2011:\n", None);
        assert_eq!(stats.records, 0);
        assert!(stats.junk >= 1);
        assert!(recs.is_empty());
    }
}

//! XLS — legacy Excel 97-2003 workbooks (BIFF8 inside an OLE2 compound file),
//! read as tables on the same record model as [`super::xlsx`].
//!
//! Each worksheet is its own dataset (`RawRecord.group` = sheet name) and each
//! row below the sheet's header row is one record keyed by the header cells,
//! with values carrying the type the cell stored: numbers stay numbers,
//! booleans stay booleans, and a date/time cell becomes an ISO-8601 string so
//! type inference elects `date` rather than seeing a serial number. The header
//! is the first row (among the first [`HEADER_SCAN_ROWS`] non-empty rows) with
//! at least two cells, all text or date and at least one text, that is not
//! immediately followed by a wider row of the same kind; rows above it are not
//! indexed. A sheet with no such header is indexed as a document, one line per
//! row with cells joined by ` | `.
//!
//! Reading is delegated to calamine, which ships its own OLE2/BIFF reader. The
//! heavy lifting of BIFF record parsing, the shared-string table and the
//! legacy 8-bit cell codepage all live there; this module only maps calamine's
//! `Data` cells onto the extractor's typed record model.
//!
//! Differences from the XLSX extractor, by design: calamine materialises a
//! whole worksheet as a `Range` (the BIFF format caps a sheet at 65,536 rows ×
//! 256 columns, and calamine reads it in one pass), so there is no streaming
//! row cap of our own — the per-sheet sample limit bounds how many rows we
//! EMIT, and [`MAX_ROWS_PER_SHEET`] bounds how many we even look at against a
//! crafted dimension record. Vertical merge fill-down is not applied (`.xls`
//! merge ranges are not surfaced on calamine's `Range`); a category label
//! merged down a column therefore appears only on its first row.

use super::{
    emit_document_with_fields, sanitize_field_name, ExtractStats, FieldOrigin, RawRecord, Sink,
    MAX_FIELDS_PER_RECORD,
};
use anyhow::Result;
use calamine::{Data, DataType, Reader, Xls};
use chrono::Timelike;
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use std::io::Read;
use std::path::Path;

/// Non-empty rows searched for a header before the sheet is treated as a
/// document (mirrors the XLSX extractor).
const HEADER_SCAN_ROWS: usize = 20;

/// Defensive cap on rows inspected per sheet, in case a crafted BIFF dimension
/// record claims a range far larger than the format's own 65,536-row ceiling.
const MAX_ROWS_PER_SHEET: usize = 1 << 20;

/// Text kept from one sheet indexed as a document.
const MAX_DOC_SHEET_BYTES: usize = 16 << 20;

/// BIFF8 worksheet ceiling: 65,536 rows × 256 columns. A `DIMENSIONS` record
/// (`0x0200`) claiming more than this is malformed or crafted — and it matters
/// because calamine materialises a *dense* `Range` sized from that record
/// before we ever iterate a row (`MAX_ROWS_PER_SHEET` on `range.rows()` is
/// applied too late). An inflated dimension therefore drives an unbounded
/// allocation that aborts the whole scan (release builds are `panic = abort`,
/// and nothing wraps the extractor in `catch_unwind`). So we read the
/// dimensions ourselves and refuse the file before handing it to calamine.
const BIFF_MAX_ROWS: u32 = 65_536;
const BIFF_MAX_COLS: u32 = 256;

/// Upper bound on the Workbook stream bytes read for the dimension pre-flight.
/// A legitimate `.xls` Workbook stream is far below this; the `take()` cap also
/// bounds the pre-flight's own allocation regardless of what the container
/// claims the stream length to be.
const MAX_WORKBOOK_STREAM: u64 = 512 << 20;

/// `false` ⇒ refuse the file: a `DIMENSIONS` record exceeds the BIFF8 ceiling,
/// so calamine would over-allocate. `true` ⇒ no crafted dimension found;
/// calamine may read it. Never panics — any CFB/IO failure returns `true` (not
/// our gate; `Xls::new` rejects a genuinely broken file cleanly), and the read
/// is `take()`-bounded so it cannot itself be driven to over-allocate.
fn xls_allocations_bounded(path: &Path) -> bool {
    let Ok(mut comp) = cfb::open(path) else {
        return true;
    };
    let name = if comp.is_stream("Workbook") {
        "Workbook"
    } else if comp.is_stream("Book") {
        "Book"
    } else {
        return true;
    };
    let Ok(stream) = comp.open_stream(name) else {
        return true;
    };
    let mut buf = Vec::new();
    if stream
        .take(MAX_WORKBOOK_STREAM)
        .read_to_end(&mut buf)
        .is_err()
    {
        return true;
    }
    biff_allocations_bounded(&buf)
}

/// Walk the BIFF record stream and refuse the file if any record would drive
/// calamine 0.26.1 to an unbounded allocation from attacker-controlled bytes.
/// It is not enough to bound one record shape (an earlier version gated only
/// the 14-byte `DIMENSIONS` and was still abortable through three other
/// records): this covers every byte-driven allocation site audited in
/// calamine's `xls.rs`:
///
///   * `DIMENSIONS` (`0x0200`), BOTH the 14-byte (BIFF8) and 10-byte (BIFF2-5)
///     forms — `parse_dimensions` dispatches on the body length, then the
///     caller `reserve`s `(rl-rf)*(cl-cf)` cells for a dense `Range`. We refuse
///     a last-row past 65,536, a last-col past 256, or an inverted range (which
///     underflows calamine's `end - start` into a vast count).
///   * `SST` (`0x00FC`) — `Vec::with_capacity(cstUnique)` before a single
///     string is read, and `i32::try_into::<usize>().unwrap()` which *panics*
///     on a negative count. We refuse a negative count or one larger than the
///     stream can hold (every SST entry costs at least a byte).
///
/// Linear, bounds-checked and terminating: every step advances `pos` past a
/// `u16` length, and every slice is guarded by `end <= stream.len()`, so a
/// crafted length can neither loop nor read out of bounds. Unrecognised records
/// are skipped by their length.
fn biff_allocations_bounded(stream: &[u8]) -> bool {
    let mut pos = 0usize;
    while pos + 4 <= stream.len() {
        let rectype = u16::from_le_bytes([stream[pos], stream[pos + 1]]);
        let reclen = u16::from_le_bytes([stream[pos + 2], stream[pos + 3]]) as usize;
        let body = pos + 4;
        let Some(end) = body.checked_add(reclen) else {
            break;
        };
        if end > stream.len() {
            break;
        }
        let d = &stream[body..end];
        match rectype {
            // DIMENSIONS — the dense-`Range` reserve. `rl`/`cl` are last-index
            // plus one; `rf`/`cf` are first index.
            0x0200 => {
                let (rf, rl, cf, cl) = if reclen >= 14 {
                    (
                        u32::from_le_bytes([d[0], d[1], d[2], d[3]]),
                        u32::from_le_bytes([d[4], d[5], d[6], d[7]]),
                        u16::from_le_bytes([d[8], d[9]]) as u32,
                        u16::from_le_bytes([d[10], d[11]]) as u32,
                    )
                } else if reclen >= 10 {
                    (
                        u16::from_le_bytes([d[0], d[1]]) as u32,
                        u16::from_le_bytes([d[2], d[3]]) as u32,
                        u16::from_le_bytes([d[4], d[5]]) as u32,
                        u16::from_le_bytes([d[6], d[7]]) as u32,
                    )
                } else {
                    // Too short for either form; calamine errors on it cleanly.
                    (0, 0, 0, 0)
                };
                if rl > BIFF_MAX_ROWS || cl > BIFF_MAX_COLS || rl < rf || cl < cf {
                    return false;
                }
            }
            // SST — shared-string table. `cstUnique` (a signed i32 at offset 4)
            // sizes the Vec before any string is parsed.
            0x00FC if reclen >= 8 => {
                let cst_unique = i32::from_le_bytes([d[4], d[5], d[6], d[7]]);
                if cst_unique < 0 || cst_unique as u64 > stream.len() as u64 {
                    return false;
                }
            }
            _ => {}
        }
        pos = end;
    }
    true
}

/// Hidden worker argv[1] the isolated BIFF reader is dispatched on. Reachable
/// through the ordinary `xerj` binary (see `xerj-server/src/main.rs`), spawned
/// via `current_exe()` — the same mechanism the PDF worker and the `xerj brain`
/// server boot already use.
pub const WORKER_ARG: &str = "__extract-xls";

/// Test/developer hook: substitute the worker executable. Production uses
/// `current_exe()`. A cargo test's `current_exe()` is the *test* binary, which
/// does not carry the `__extract-xls` dispatch, so the isolation integration
/// test points this at the built `xerj` binary — mirrors `XERJ_PDF_WORKER_BIN`.
const WORKER_BIN_ENV: &str = "XERJ_XLS_WORKER_BIN";

/// Address-space ceiling imposed on the worker (`RLIMIT_AS`). A crafted
/// `DIMENSIONS`/`SST` that slips the pre-filter, or any other attacker-driven
/// `Vec::with_capacity`, hits this and fails the allocation inside the worker —
/// where it only kills the worker — instead of aborting the indexer.
#[cfg(unix)]
const WORKER_ADDRESS_SPACE: u64 = 2 << 30; // 2 GiB

/// CPU-time ceiling imposed on the worker (`RLIMIT_CPU`, seconds). A record
/// stream crafted to spin inside calamine is bounded here; the kernel sends
/// `SIGXCPU` at the soft limit and `SIGKILL` at the hard limit, either of which
/// the parent reports as junk.
#[cfg(unix)]
const WORKER_CPU_SECONDS: u64 = 15;

/// Wall-clock backstop for the whole worker, independent of CPU time — covers a
/// worker wedged in a blocking syscall that burns no CPU. `RLIMIT_CPU` is the
/// primary guard; this only fires if the worker is stuck without the kernel
/// noticing.
#[cfg(unix)]
const WORKER_WALL_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(60);

/// Upper bound on the NDJSON the parent will buffer from one worker. A legacy
/// `.xls` sheet is capped by the format at 65,536 rows × 256 columns, so a
/// well-formed workbook is far below this; a worker emitting more than this is
/// treated as junk rather than letting the parent's own memory grow unbounded
/// on the worker's say-so.
#[cfg(unix)]
const MAX_WORKER_OUTPUT: usize = 128 << 20; // 128 MiB

/// One line of the parent↔worker protocol. The worker serializes every produced
/// record as a `Rec` line and closes with exactly one `End` line carrying the
/// truncation flag; the parent parses them back into the identical records the
/// in-process path would have emitted. Internally tagged on `k` so a record
/// line (which never carries a `k` field) and the terminator are distinguished
/// without a second pass.
#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "k")]
enum WorkerLine {
    /// One extracted record, byte-for-byte the `RawRecord` the sink receives.
    #[serde(rename = "rec")]
    Rec(RawRecord),
    /// Terminator: the worker finished the file cleanly. Its presence is what
    /// tells the parent the stream was not cut short by a crash mid-emit.
    #[serde(rename = "end")]
    End { truncated: bool },
}

/// `name` is the file as the corpus names it (under durable preparation this is
/// not `path`, a sealed snapshot blob); document sheets are titled from it.
/// `per_sheet_limit` caps the rows emitted from each sheet (phase-A sampling);
/// `None` reads every row.
///
/// The dump being indexed is untrusted (Jira/Confluence/GitLab attachments) and
/// calamine 0.26.1 is *not* panic-safe on hostile BIFF: beyond the allocation
/// vectors [`xls_allocations_bounded`] pre-filters, it indexes a short `Lbl`
/// (`0x0018`) or `ExternSheet` (`0x0017`) record straight out of bounds and
/// panics. The engine release profile is `panic = abort` with no `catch_unwind`
/// around the scan, so such a panic aborts the WHOLE indexer, and `catch_unwind`
/// cannot help under `panic = abort`. So on unix the actual BIFF read runs in a
/// short-lived child process under `RLIMIT_AS`/`RLIMIT_CPU`: a panic, abort,
/// OOM-kill or runaway there dies with the child and is counted as junk, and the
/// parent never calls calamine on the raw file itself. Non-unix keeps the
/// in-process bounded path as a documented best-effort (the dump is Linux).
pub fn extract(
    path: &Path,
    name: &Path,
    per_sheet_limit: Option<u64>,
    sink: Sink,
) -> Result<ExtractStats> {
    // Cheap pre-filter, kept from #1324: refuse the whole crafted-allocation
    // class before paying to spawn a worker at all. It is a pre-filter now, not
    // the whole defence — the worker's rlimits catch what byte-walking a record
    // stream cannot (every other allocation site, and the out-of-bounds panics).
    if !xls_allocations_bounded(path) {
        let mut stats = ExtractStats::default();
        stats.junk += 1;
        return Ok(stats);
    }
    #[cfg(unix)]
    {
        extract_isolated(path, name, per_sheet_limit, sink)
    }
    #[cfg(not(unix))]
    {
        // No `setrlimit`/`pre_exec` here; best-effort in-process read bounded by
        // the pre-filter above. Documented: the production dump is Linux.
        extract_in_process(path, name, per_sheet_limit, sink)
    }
}

/// Parent side of the isolation: spawn `current_exe() __extract-xls <path>
/// <name> <limit>`, read its NDJSON, and deliver the records to `sink` exactly
/// as the in-process path would. Any abnormal exit — non-zero, signal
/// (SIGABRT/SIGKILL/SIGXCPU), wall-clock timeout, over-cap output, a line that
/// will not parse, or a missing `End` terminator — becomes `junk += 1` and
/// `Ok`, so one hostile file is skipped and the scan continues. All-or-nothing:
/// records are buffered and only delivered once the worker has closed cleanly,
/// so a worker that crashes mid-file indexes nothing from it (no partial rows).
#[cfg(unix)]
fn extract_isolated(
    path: &Path,
    name: &Path,
    per_sheet_limit: Option<u64>,
    sink: Sink,
) -> Result<ExtractStats> {
    let mut stats = ExtractStats::default();
    match run_worker(path, name, per_sheet_limit) {
        Ok((records, truncated)) => {
            for rec in records {
                stats.records += 1;
                if !sink(rec) {
                    // Sampling stop: the caller has what it wanted. Success.
                    return Ok(stats);
                }
            }
            if stats.records == 0 {
                // Clean run that produced nothing (unreadable-but-not-crafted
                // workbook, or an empty one) — junk, mirroring the in-process
                // `records == 0` rule.
                stats.junk += 1;
            } else {
                stats.truncated = truncated;
            }
        }
        // Crash / timeout / protocol failure: skip the file, keep scanning.
        Err(_) => stats.junk += 1,
    }
    Ok(stats)
}

/// Run one worker to completion and return its buffered records plus the
/// truncation flag, or an error describing why the file could not be trusted.
#[cfg(unix)]
fn run_worker(
    path: &Path,
    name: &Path,
    per_sheet_limit: Option<u64>,
) -> Result<(Vec<RawRecord>, bool)> {
    use anyhow::{anyhow, Context};
    use std::os::unix::process::CommandExt;
    use std::process::{Command, Stdio};

    let exe = std::env::var_os(WORKER_BIN_ENV)
        .map(std::path::PathBuf::from)
        .or_else(|| std::env::current_exe().ok())
        .context("locate the xerj binary for isolated .xls extraction")?;

    let mut command = Command::new(exe);
    command
        .arg(WORKER_ARG)
        .arg(path.as_os_str())
        .arg(name.as_os_str())
        .arg(match per_sheet_limit {
            Some(n) => n.to_string(),
            None => "none".to_string(),
        })
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null());
    // Probe in the parent. A kernel that rejects RLIMIT_AS (macOS 27, EINVAL)
    // must not fail this spawn; the warning is taken from the progress stream
    // after the scan. The child still skips EINVAL/EPERM itself.
    let _ = super::rlimit::address_space_cap_supported();
    // SAFETY: the closure runs in the forked child before exec and calls only
    // async-signal-safe libc (`setpgid`, `setrlimit`). Its own process group so
    // the parent can reap the whole tree; the rlimits cap the child's blast
    // radius to itself. A benign RLIMIT_AS refusal does not allocate.
    unsafe {
        command.pre_exec(worker_pre_exec);
    }

    let mut child = command
        .spawn()
        .with_context(|| format!("spawn the isolated .xls reader for {}", path.display()))?;
    let pid = child.id();

    let stdout = child.stdout.take().expect("piped stdout");
    // Read on a thread so the wall-clock watchdog below can act even if the
    // worker stalls with the pipe open.
    //
    // #1122: `std::thread::spawn` panics when a thread cannot be created and
    // release builds are panic=abort; a failed spawn stops the worker and
    // fails this one file instead of aborting the run.
    let reader =
        match xerj_common::thread_spawn::try_spawn_returning("xerj-xls-stdout", move || {
            read_capped(stdout, MAX_WORKER_OUTPUT)
        }) {
            Ok(reader) => reader,
            Err(failure) => {
                drop(failure.job);
                kill_group(pid);
                let _ = child.wait();
                return Err(failure.error).with_context(|| {
                    format!(
                        "could not start the .xls reader's output thread for {}",
                        path.display()
                    )
                });
            }
        };

    let started = std::time::Instant::now();
    let status = loop {
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) => {}
            Err(e) => {
                kill_group(pid);
                let _ = child.wait();
                let _ = reader.join();
                return Err(e)
                    .with_context(|| format!("monitor the .xls reader for {}", path.display()));
            }
        }
        if started.elapsed() >= WORKER_WALL_TIMEOUT {
            kill_group(pid);
            let _ = child.wait();
            let _ = reader.join();
            return Err(anyhow!(
                "isolated .xls reader for {} exceeded the {}s wall-clock limit",
                path.display(),
                WORKER_WALL_TIMEOUT.as_secs()
            ));
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    };
    // Reap any stragglers left in the group, then collect the output.
    kill_group(pid);
    let captured = reader
        .join()
        .map_err(|_| anyhow!("the .xls reader output thread panicked"))??;
    if captured.overflow {
        return Err(anyhow!(
            "isolated .xls reader for {} produced more than {} MiB of output",
            path.display(),
            MAX_WORKER_OUTPUT >> 20
        ));
    }
    if !status.success() {
        return Err(anyhow!(
            "isolated .xls reader for {} exited abnormally ({status})",
            path.display()
        ));
    }
    parse_worker_output(&captured.bytes).with_context(|| {
        format!(
            "parse the isolated .xls reader output for {}",
            path.display()
        )
    })
}

/// Parse the worker's NDJSON into the records and truncation flag. A clean run
/// ends with exactly one `End` line; its absence means the stream was cut short
/// (a crash the exit status somehow did not surface) and is an error.
#[cfg(unix)]
fn parse_worker_output(bytes: &[u8]) -> Result<(Vec<RawRecord>, bool)> {
    use anyhow::anyhow;
    let mut records = Vec::new();
    let mut ended: Option<bool> = None;
    for line in bytes.split(|&b| b == b'\n') {
        if line.is_empty() {
            continue;
        }
        if ended.is_some() {
            return Err(anyhow!("trailing output after the .xls reader terminator"));
        }
        match serde_json::from_slice::<WorkerLine>(line)? {
            WorkerLine::Rec(rec) => records.push(rec),
            WorkerLine::End { truncated } => ended = Some(truncated),
        }
    }
    match ended {
        Some(truncated) => Ok((records, truncated)),
        None => Err(anyhow!("the .xls reader did not emit a terminator")),
    }
}

/// Pre-exec child setup: own process group + address-space and CPU-time caps.
/// Runs in the forked child; only async-signal-safe libc calls.
#[cfg(unix)]
fn worker_pre_exec() -> std::io::Result<()> {
    // SAFETY: `setpgid`/`setrlimit` are async-signal-safe and documented here.
    unsafe {
        if libc::setpgid(0, 0) != 0 {
            return Err(std::io::Error::last_os_error());
        }
    }
    set_worker_rlimits()
}

/// Apply `RLIMIT_AS` and `RLIMIT_CPU` to the current process. Used by
/// [`worker_pre_exec`] (parent-forked child) and again by the worker itself at
/// entry (belt-and-suspenders, in case it was spawned some other way).
///
/// Only ever *lowers* a limit: an unprivileged process cannot raise its hard
/// limit, so the target is clamped to whatever was inherited. This matters when
/// the indexer already runs under a tighter cgroup or `ulimit -v` — trying to
/// set a higher ceiling there would `EPERM`.
///
/// `RLIMIT_AS` treats `EINVAL` and `EPERM` as "this platform will not install
/// the cap" and returns `Ok` (#2336). The cap is crash isolation. Failing the
/// spawn junked every `.xls` on macOS 27, where `setrlimit(RLIMIT_AS)` is
/// rejected outright. `RLIMIT_CPU` stays strict: a failure there is still a
/// failed spawn.
#[cfg(unix)]
fn set_worker_rlimits() -> std::io::Result<()> {
    // Set `$res`'s soft/hard limits to the requested values, each capped at the
    // inherited hard limit so the call never tries to RAISE a ceiling (which an
    // unprivileged process may not do). A macro, not a function, so the
    // resource constant is passed straight to libc without naming its type —
    // that type is `__rlimit_resource_t` on glibc but `c_int` on macOS/BSD.
    // `$benign` skips EINVAL/EPERM without allocating; the fatal path builds
    // the `io::Error` only when the spawn must fail.
    macro_rules! clamp {
        ($res:expr, $soft:expr, $hard:expr, $benign:expr) => {{
            let mut current = libc::rlimit {
                rlim_cur: 0,
                rlim_max: 0,
            };
            // SAFETY: plain libc FFI over an out-param `rlimit`.
            let refused = if unsafe { libc::getrlimit($res, &mut current) } != 0 {
                let errno = super::rlimit::errno_raw();
                if $benign && super::rlimit::refusal_is_benign(errno) {
                    true
                } else {
                    return Err(std::io::Error::from_raw_os_error(errno));
                }
            } else {
                false
            };
            if !refused {
                let ceiling = current.rlim_max; // inherited hard limit (maybe RLIM_INFINITY)
                let want_hard = ($hard as libc::rlim_t).min(ceiling);
                let want_soft = ($soft as libc::rlim_t).min(want_hard);
                let limit = libc::rlimit {
                    rlim_cur: want_soft,
                    rlim_max: want_hard,
                };
                // SAFETY: as above; cur <= max <= inherited max, so this only lowers.
                if unsafe { libc::setrlimit($res, &limit) } != 0 {
                    let errno = super::rlimit::errno_raw();
                    if $benign && super::rlimit::refusal_is_benign(errno) {
                        // Inherited limit stands. The worker still starts.
                    } else {
                        return Err(std::io::Error::from_raw_os_error(errno));
                    }
                }
            }
        }};
    }
    clamp!(
        libc::RLIMIT_AS,
        WORKER_ADDRESS_SPACE,
        WORKER_ADDRESS_SPACE,
        true
    );
    // Soft limit sends SIGXCPU; hard limit (a touch higher) escalates to SIGKILL.
    clamp!(
        libc::RLIMIT_CPU,
        WORKER_CPU_SECONDS,
        WORKER_CPU_SECONDS + 2,
        false
    );
    Ok(())
}

/// SIGKILL the worker's whole process group (negative pid). Best effort.
#[cfg(unix)]
fn kill_group(pid: u32) {
    // SAFETY: plain libc FFI; an already-dead group is a harmless ESRCH.
    unsafe {
        libc::kill(-(pid as i32), libc::SIGKILL);
    }
}

#[cfg(unix)]
struct Captured {
    bytes: Vec<u8>,
    overflow: bool,
}

/// Read `input` to EOF, keeping at most `cap` bytes and flagging overflow.
/// Keeps draining past the cap so the child never blocks on a full pipe.
#[cfg(unix)]
fn read_capped(mut input: impl Read, cap: usize) -> Result<Captured> {
    use anyhow::Context;
    let mut bytes = Vec::new();
    let mut overflow = false;
    let mut chunk = [0u8; 64 << 10];
    loop {
        let n = input
            .read(&mut chunk)
            .context("read isolated .xls reader output")?;
        if n == 0 {
            break;
        }
        if !overflow {
            let room = cap.saturating_sub(bytes.len());
            let take = room.min(n);
            bytes.extend_from_slice(&chunk[..take]);
            overflow |= take < n;
        }
    }
    Ok(Captured { bytes, overflow })
}

/// Hidden same-binary worker entry point (`xerj __extract-xls <path> <name>
/// <limit|none>`). One invocation reads one workbook and streams its records as
/// NDJSON on stdout. If calamine panics/aborts here, this process dies and the
/// parent handles it; nothing in the parent ever touches the raw file.
pub fn run_worker_cli() -> i32 {
    // Re-apply the resource caps the parent set via `pre_exec`, so the worker is
    // bounded even if it was launched directly (tests, a future caller).
    #[cfg(unix)]
    if let Err(e) = set_worker_rlimits() {
        eprintln!(".xls worker could not set its resource limits: {e}");
        // Not fatal: the parent's `pre_exec` is the authoritative cap.
    }

    let mut args = std::env::args_os().skip(2);
    let (Some(path), Some(name), Some(limit)) = (args.next(), args.next(), args.next()) else {
        eprintln!(".xls worker protocol error: expected <path> <name> <limit>");
        return 2;
    };
    if args.next().is_some() {
        eprintln!(".xls worker protocol error: unexpected trailing arguments");
        return 2;
    }
    let per_sheet_limit = match limit.to_string_lossy().as_ref() {
        "none" => None,
        other => match other.parse::<u64>() {
            Ok(n) => Some(n),
            Err(_) => {
                eprintln!(".xls worker protocol error: bad limit {other:?}");
                return 2;
            }
        },
    };

    let path = std::path::PathBuf::from(path);
    let name = std::path::PathBuf::from(name);

    use std::io::Write;
    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut write_err = false;
    let mut emit = |rec: RawRecord| -> bool {
        if serde_json::to_writer(&mut out, &WorkerLine::Rec(rec)).is_err()
            || out.write_all(b"\n").is_err()
        {
            write_err = true;
            return false;
        }
        true
    };

    match extract_in_process(&path, &name, per_sheet_limit, &mut emit) {
        Ok(stats) => {
            if write_err {
                return 1;
            }
            let end = WorkerLine::End {
                truncated: stats.truncated,
            };
            if serde_json::to_writer(&mut out, &end).is_err()
                || out.write_all(b"\n").is_err()
                || out.flush().is_err()
            {
                return 1;
            }
            0
        }
        Err(e) => {
            eprintln!(".xls worker failed: {e:#}");
            1
        }
    }
}

/// The in-process BIFF read. On unix this runs *inside the worker*; on non-unix
/// it is the whole (best-effort) path. It still runs the allocation pre-filter
/// itself, so it is self-contained wherever it is called from.
fn extract_in_process(
    path: &Path,
    name: &Path,
    per_sheet_limit: Option<u64>,
    sink: Sink,
) -> Result<ExtractStats> {
    let mut stats = ExtractStats::default();
    // DoS gate: calamine allocates a dense `Range` from the sheet's declared
    // `DIMENSIONS` before any row is read, so a crafted record makes it attempt
    // a multi-terabyte allocation and abort the process (release = panic=abort,
    // no catch_unwind around the scan). Refuse such a file up front; the read
    // here is bounded by `cfb`'s FAT chain, so the gate cannot itself be driven
    // to over-allocate.
    if !xls_allocations_bounded(path) {
        stats.junk += 1;
        return Ok(stats);
    }
    let f = std::fs::File::open(path)?;
    // A malformed/truncated workbook that still clears the dimension gate is
    // treated as junk rather than propagating — a single unreadable legacy file
    // must not abort a folder scan. (calamine *returns* an error for most such
    // files, but is not panic-free on hostile input, which is why the gate
    // above runs first.)
    let mut wb = match Xls::new(f) {
        Ok(wb) => wb,
        Err(_) => {
            stats.junk += 1;
            return Ok(stats);
        }
    };

    let stem = name
        .file_stem()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "untitled".into());

    let sheet_names = wb.sheet_names().to_vec();
    for sheet_name in sheet_names {
        let Ok(range) = wb.worksheet_range(&sheet_name) else {
            continue;
        };
        let start_row = range.start().map(|(r, _)| r).unwrap_or(0);
        let start_col = range.start().map(|(_, c)| c).unwrap_or(0);

        // Build the non-empty rows, each carrying 1-based column numbers so the
        // header/column machinery matches the XLSX extractor's.
        let mut rows: Vec<Row> = Vec::new();
        for (i, cells) in range.rows().take(MAX_ROWS_PER_SHEET).enumerate() {
            let mut out = Vec::new();
            for (j, data) in cells.iter().enumerate() {
                if let Some(cell) = convert_cell(start_col + j as u32 + 1, data) {
                    out.push(cell);
                }
            }
            if !out.is_empty() {
                rows.push(Row {
                    num: start_row + i as u32 + 1,
                    cells: out,
                });
            }
        }
        if rows.is_empty() {
            continue;
        }

        if let Some(h) = find_header(&rows) {
            if !emit_table(&sheet_name, &rows, h, per_sheet_limit, sink, &mut stats) {
                break;
            }
        } else if !emit_document_sheet(&sheet_name, &stem, &rows, sink, &mut stats) {
            break;
        }
    }

    if stats.records == 0 {
        stats.junk += 1;
    }
    Ok(stats)
}

/// A cell's typed kind, mirroring the XLSX extractor so header detection and
/// type inference agree across the two formats.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Kind {
    Text,
    Number,
    Bool,
    Date,
}

#[derive(Debug, Clone)]
struct Cell {
    /// 1-based column (A = 1).
    col: u32,
    value: Value,
    kind: Kind,
}

impl Cell {
    fn display(&self) -> String {
        match &self.value {
            Value::String(s) => s.clone(),
            Value::Bool(true) => "TRUE".into(),
            Value::Bool(false) => "FALSE".into(),
            v => v.to_string(),
        }
    }
}

#[derive(Debug)]
struct Row {
    /// 1-based row number, as Excel shows it.
    num: u32,
    cells: Vec<Cell>,
}

/// Map one calamine cell onto the typed model; `None` for an empty cell or an
/// error value (`#N/A`, `#DIV/0!`), exactly as the XLSX extractor drops them.
fn convert_cell(col: u32, data: &Data) -> Option<Cell> {
    match data {
        Data::Empty | Data::Error(_) => None,
        Data::String(s) => {
            let s = s.trim();
            (!s.is_empty()).then(|| Cell {
                col,
                value: Value::String(s.to_string()),
                kind: Kind::Text,
            })
        }
        Data::Int(i) => Some(Cell {
            col,
            value: Value::Number((*i).into()),
            kind: Kind::Number,
        }),
        Data::Float(f) => Some(Cell {
            col,
            value: number_value(*f)?,
            kind: Kind::Number,
        }),
        Data::Bool(b) => Some(Cell {
            col,
            value: Value::Bool(*b),
            kind: Kind::Bool,
        }),
        Data::DateTimeIso(s) => {
            let s = s.trim();
            (!s.is_empty()).then(|| Cell {
                col,
                value: Value::String(s.to_string()),
                kind: Kind::Date,
            })
        }
        Data::DurationIso(s) => {
            let s = s.trim();
            (!s.is_empty()).then(|| Cell {
                col,
                value: Value::String(s.to_string()),
                kind: Kind::Text,
            })
        }
        Data::DateTime(_) => date_cell(col, data),
    }
}

/// A calamine `Data::DateTime` rendered to the same ISO-8601 strings the XLSX
/// extractor emits: a bare date at midnight, a `T`-joined datetime otherwise,
/// and `HH:MM:SS` for a duration/time-of-day. Falls back to the raw serial
/// number if calamine cannot resolve it to a chrono value.
fn date_cell(col: u32, data: &Data) -> Option<Cell> {
    // A time of day (fraction of a day with no date part) resolves to a
    // `NaiveTime` but not a sensible `NaiveDateTime`; check it first.
    if let Some(dt) = data.as_datetime() {
        let iso = if dt.num_seconds_from_midnight() == 0 && dt.nanosecond() == 0 {
            dt.format("%Y-%m-%d").to_string()
        } else if dt.nanosecond() == 0 {
            dt.format("%Y-%m-%dT%H:%M:%S").to_string()
        } else {
            dt.format("%Y-%m-%dT%H:%M:%S%.3f").to_string()
        };
        return Some(Cell {
            col,
            value: Value::String(iso),
            kind: Kind::Date,
        });
    }
    if let Some(t) = data.as_time() {
        return Some(Cell {
            col,
            value: Value::String(t.format("%H:%M:%S").to_string()),
            kind: Kind::Date,
        });
    }
    // Could not resolve a calendar value: keep the serial number as a number so
    // nothing is dropped.
    let f = data.as_f64()?;
    Some(Cell {
        col,
        value: number_value(f)?,
        kind: Kind::Number,
    })
}

/// Integral floats inside the i64-exact range become integers (so `1250.0`
/// indexes as `1250`), matching the XLSX extractor's `number_value`.
fn number_value(f: f64) -> Option<Value> {
    if !f.is_finite() {
        return None;
    }
    if f.fract() == 0.0 && f.abs() < 9_007_199_254_740_992.0 {
        Some(Value::Number((f as i64).into()))
    } else {
        serde_json::Number::from_f64(f).map(Value::Number)
    }
}

/// Column letters of a column number (28 → `AB`).
fn column_letters(mut col: u32) -> String {
    let mut out = Vec::new();
    while col > 0 {
        let rem = (col - 1) % 26;
        out.push(b'A' + rem as u8);
        col = (col - 1) / 26;
    }
    out.reverse();
    String::from_utf8(out).unwrap_or_default()
}

/// Whether a row can be a header: two or more cells, some text, and no numbers
/// or booleans (date cells are allowed, for month-column headers).
fn is_header_candidate(row: &Row) -> bool {
    row.cells.len() >= 2
        && row
            .cells
            .iter()
            .all(|c| matches!(c.kind, Kind::Text | Kind::Date))
        && row.cells.iter().any(|c| c.kind == Kind::Text)
}

/// Index of the header row. A candidate followed by a WIDER candidate is a
/// title line above the real header and is passed over. Only the first
/// [`HEADER_SCAN_ROWS`] non-empty rows are considered.
fn find_header(rows: &[Row]) -> Option<usize> {
    let scan = rows.len().min(HEADER_SCAN_ROWS);
    rows[..scan].windows(2).position(|w| {
        is_header_candidate(&w[0])
            && !(is_header_candidate(&w[1]) && w[1].cells.len() > w[0].cells.len())
    })
}

/// Emit every data row under `header_idx` as a typed record keyed by the header
/// cells. Returns false if the sink asked to stop the whole file.
fn emit_table(
    sheet: &str,
    rows: &[Row],
    header_idx: usize,
    limit: Option<u64>,
    sink: Sink,
    stats: &mut ExtractStats,
) -> bool {
    let header = &rows[header_idx];
    let mut seen = std::collections::HashSet::new();
    let mut names: std::collections::HashMap<u32, String> = std::collections::HashMap::new();
    for c in &header.cells {
        let mut name = sanitize_field_name(&c.display());
        while !seen.insert(name.clone()) {
            name.push_str("_2");
        }
        names.insert(c.col, name);
    }
    let header_cells: Vec<(u32, String)> =
        header.cells.iter().map(|c| (c.col, c.display())).collect();

    let mut emitted = 0u64;
    for row in &rows[header_idx + 1..] {
        // A repeated header row (common when a sheet stacks sections) is not a
        // data record.
        let row_text: Vec<(u32, String)> = row.cells.iter().map(|c| (c.col, c.display())).collect();
        if row_text == header_cells {
            continue;
        }
        let mut fields = Map::new();
        for c in &row.cells {
            if fields.len() >= MAX_FIELDS_PER_RECORD {
                break;
            }
            let name = names
                .get(&c.col)
                .cloned()
                .unwrap_or_else(|| format!("col_{}", column_letters(c.col)));
            fields.insert(name, c.value.clone());
        }
        stats.records += 1;
        if !sink(RawRecord {
            fields,
            locator: format!("{sheet}!r{}", row.num),
            group: Some(sheet.to_string()),
            origin: FieldOrigin::Data,
        }) {
            return false;
        }
        emitted += 1;
        if limit.is_some_and(|lim| emitted >= lim) {
            break;
        }
    }
    true
}

/// Emit a sheet with no detectable header as a document: one line per row,
/// cells joined by ` | `. Returns false if the sink asked to stop.
fn emit_document_sheet(
    sheet: &str,
    stem: &str,
    rows: &[Row],
    sink: Sink,
    stats: &mut ExtractStats,
) -> bool {
    let mut body = String::new();
    let mut last_row = 0u32;
    for row in rows {
        let line = row
            .cells
            .iter()
            .map(Cell::display)
            .collect::<Vec<_>>()
            .join(" | ");
        if body.len() + line.len() + 2 > MAX_DOC_SHEET_BYTES {
            stats.truncated = true;
            break;
        }
        if !body.is_empty() {
            // A gap in row numbers is a paragraph break, where section
            // splitting prefers to cut.
            body.push_str(if row.num > last_row + 1 { "\n\n" } else { "\n" });
        }
        body.push_str(&line);
        last_row = row.num;
    }
    if body.trim().is_empty() {
        return true;
    }
    let mut base = Map::new();
    base.insert("sheet".into(), Value::String(sheet.to_string()));
    emit_document_with_fields(
        &base,
        &format!("{stem} — {sheet}"),
        &body,
        sheet,
        sink,
        stats,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn fields(r: &RawRecord) -> Value {
        Value::Object(r.fields.clone())
    }

    /// A BIFF8 `DIMENSIONS` record (type 0x0200, len 14): rwMic, rwMac, colMic,
    /// colMac (each last-index-plus-one), reserved.
    fn dimensions_record(rw_mic: u32, rw_mac: u32, col_mic: u16, col_mac: u16) -> Vec<u8> {
        let mut r = vec![0x00, 0x02, 14, 0x00]; // type 0x0200, length 14
        r.extend_from_slice(&rw_mic.to_le_bytes());
        r.extend_from_slice(&rw_mac.to_le_bytes());
        r.extend_from_slice(&col_mic.to_le_bytes());
        r.extend_from_slice(&col_mac.to_le_bytes());
        r.extend_from_slice(&[0x00, 0x00]); // reserved
        r
    }

    #[test]
    fn a_real_dimension_is_accepted() {
        // A 100-row × 10-column sheet is well within the BIFF8 ceiling.
        assert!(biff_allocations_bounded(&dimensions_record(0, 100, 0, 10)));
        // And the format's own maximum is still accepted.
        assert!(biff_allocations_bounded(&dimensions_record(
            0, 65_536, 0, 256
        )));
    }

    #[test]
    fn a_crafted_dimension_past_the_biff_ceiling_is_refused() {
        // The shape of the 36 KB proof-of-concept: a DIMENSIONS claiming a vast
        // row range, which drove calamine to attempt a ~2.1 TB Range alloc.
        assert!(!biff_allocations_bounded(&dimensions_record(
            0,
            0x7FFF_FFFF,
            0,
            256
        )));
        // An inflated column count is refused the same way.
        assert!(!biff_allocations_bounded(&dimensions_record(
            0, 100, 0, 60_000
        )));
        // Inverted ranges (mac < mic) are malformed and refused.
        assert!(!biff_allocations_bounded(&dimensions_record(
            500, 100, 0, 10
        )));
    }

    #[test]
    fn a_truncated_or_dimensionless_stream_is_not_mistaken_for_crafted() {
        // No DIMENSIONS record at all: nothing to object to, let calamine try.
        assert!(biff_allocations_bounded(
            b"\x09\x08\x04\x00\x00\x00\x00\x00"
        )); // a BOF-ish record, no 0x0200
            // A record header whose declared length runs past the buffer end stops
            // the walk without a panic and without a false refusal.
        assert!(biff_allocations_bounded(&[0x00, 0x02, 0xFF, 0xFF, 0x01]));
        // Empty stream.
        assert!(biff_allocations_bounded(&[]));
    }

    /// The 10-byte (BIFF2-5) `DIMENSIONS` form: type 0x0200, length 10, four
    /// u16 fields (rf, rl, cf, cl).
    fn dimensions_record_biff5(rf: u16, rl: u16, cf: u16, cl: u16) -> Vec<u8> {
        let mut r = vec![0x00, 0x02, 10, 0x00]; // type 0x0200, body length 10
        for v in [rf, rl, cf, cl] {
            r.extend_from_slice(&v.to_le_bytes()); // 8 bytes of fields
        }
        r.extend_from_slice(&[0x00, 0x00]); // + 2 bytes so the body is 10, as calamine expects
        r
    }

    /// An `SST` record (type 0x00FC): cstTotal (i32) then cstUnique (i32). The
    /// body past the header is irrelevant to the allocation gate.
    fn sst_record(cst_unique: i32) -> Vec<u8> {
        let mut r = vec![0xFC, 0x00, 8, 0x00];
        r.extend_from_slice(&0i32.to_le_bytes()); // cstTotal
        r.extend_from_slice(&cst_unique.to_le_bytes()); // cstUnique
        r
    }

    #[test]
    fn the_10_byte_dimensions_form_is_also_bounded() {
        // A real small BIFF5 sheet is accepted.
        assert!(biff_allocations_bounded(&dimensions_record_biff5(
            0, 100, 0, 10
        )));
        // The reviewer's bypass: rl = cl = 0xFFFF drove calamine to a ~171 GB
        // reserve because the earlier gate only checked the 14-byte form. The
        // 65,535-column claim is past the 256 ceiling and is now refused.
        assert!(!biff_allocations_bounded(&dimensions_record_biff5(
            0, 0xFFFF, 0, 0xFFFF
        )));
    }

    #[test]
    fn a_crafted_sst_count_is_refused() {
        // A sane shared-string count is accepted (well under the stream length).
        let mut benign = sst_record(3);
        benign.extend_from_slice(&[0u8; 64]); // give the stream some length
        assert!(biff_allocations_bounded(&benign));
        // A huge cstUnique drove `Vec::with_capacity(~2.1e9)` → ~51 GB abort.
        assert!(!biff_allocations_bounded(&sst_record(0x7FFF_FFFF)));
        // A negative cstUnique made calamine `i32::try_into::<usize>().unwrap()`
        // panic (also an abort under panic=abort).
        assert!(!biff_allocations_bounded(&sst_record(-1)));
    }

    /// Build a one-sheet `.xls` in a tempdir with `rustexcel`-free, synthetic
    /// content by driving calamine's own writer? calamine has no writer, so the
    /// unit tests here exercise the typed-model mapping and the table/document
    /// routing directly on synthetic rows. The end-to-end round-trip through a
    /// real BIFF file is covered by `extract_real_xls_fixture` (gated on a
    /// generated fixture), so these pin the behaviour deterministically.
    fn row(num: u32, cells: &[Cell]) -> Row {
        Row {
            num,
            cells: cells.to_vec(),
        }
    }
    fn txt(col: u32, s: &str) -> Cell {
        Cell {
            col,
            value: Value::String(s.into()),
            kind: Kind::Text,
        }
    }
    fn num(col: u32, v: i64) -> Cell {
        Cell {
            col,
            value: Value::Number(v.into()),
            kind: Kind::Number,
        }
    }
    fn boolean(col: u32, v: bool) -> Cell {
        Cell {
            col,
            value: Value::Bool(v),
            kind: Kind::Bool,
        }
    }

    fn collect_table(sheet: &str, rows: &[Row]) -> (ExtractStats, Vec<RawRecord>) {
        let h = find_header(rows).expect("a header should be found");
        let mut recs = Vec::new();
        let mut stats = ExtractStats::default();
        emit_table(
            sheet,
            rows,
            h,
            None,
            &mut |r| {
                recs.push(r);
                true
            },
            &mut stats,
        );
        (stats, recs)
    }

    #[test]
    fn convert_cell_types_mirror_the_xlsx_model() {
        assert!(convert_cell(1, &Data::Empty).is_none());
        assert!(convert_cell(1, &Data::Error(calamine::CellErrorType::Div0)).is_none());
        // An integral float indexes as an integer, not 1250.0.
        assert_eq!(
            convert_cell(3, &Data::Float(1250.0)).unwrap().value,
            json!(1250)
        );
        assert_eq!(
            convert_cell(3, &Data::Float(980.5)).unwrap().value,
            json!(980.5)
        );
        assert_eq!(convert_cell(4, &Data::Bool(true)).unwrap().kind, Kind::Bool);
        // A whitespace-only string is dropped like an empty cell.
        assert!(convert_cell(1, &Data::String("   ".into())).is_none());
    }

    #[test]
    fn a_title_row_is_skipped_and_each_row_under_the_header_is_a_typed_record() {
        // Row 1 is a single-cell title; row 3 the header; 4-5 the data.
        let rows = vec![
            row(1, &[txt(1, "Q3 Sales Report")]),
            row(
                3,
                &[
                    txt(1, "Region"),
                    txt(2, "Month"),
                    txt(3, "Revenue"),
                    txt(4, "Closed"),
                ],
            ),
            row(
                4,
                &[
                    txt(1, "EMEA"),
                    txt(2, "July"),
                    num(3, 1250),
                    boolean(4, true),
                ],
            ),
            row(
                5,
                &[
                    txt(1, "APAC"),
                    txt(2, "August"),
                    num(3, 980),
                    boolean(4, false),
                ],
            ),
        ];
        let (stats, recs) = collect_table("Sales", &rows);
        assert_eq!((stats.records, stats.junk), (2, 0));
        assert_eq!(recs[0].group.as_deref(), Some("Sales"));
        assert_eq!(recs[0].locator, "Sales!r4");
        assert_eq!(recs[0].origin, FieldOrigin::Data);
        assert_eq!(
            fields(&recs[0]),
            json!({"Region": "EMEA", "Month": "July", "Revenue": 1250, "Closed": true})
        );
        assert_eq!(
            fields(&recs[1]),
            json!({"Region": "APAC", "Month": "August", "Revenue": 980, "Closed": false})
        );
    }

    #[test]
    fn a_repeated_header_row_is_not_a_data_record() {
        let rows = vec![
            row(1, &[txt(1, "Name"), txt(2, "Score")]),
            row(2, &[txt(1, "Ann"), num(2, 10)]),
            row(3, &[txt(1, "Name"), txt(2, "Score")]), // stacked header again
            row(4, &[txt(1, "Bob"), num(2, 20)]),
        ];
        let (stats, recs) = collect_table("S", &rows);
        assert_eq!(stats.records, 2);
        assert_eq!(fields(&recs[0]), json!({"Name": "Ann", "Score": 10}));
        assert_eq!(fields(&recs[1]), json!({"Name": "Bob", "Score": 20}));
    }

    #[test]
    fn duplicate_header_names_are_disambiguated() {
        let rows = vec![
            row(1, &[txt(1, "Amount"), txt(2, "Amount")]),
            row(2, &[num(1, 1), num(2, 2)]),
        ];
        let (_stats, recs) = collect_table("S", &rows);
        let obj = recs[0].fields.clone();
        assert!(obj.contains_key("Amount") && obj.contains_key("Amount_2"));
    }

    #[test]
    fn a_sheet_with_no_header_is_emitted_as_a_document() {
        // Every row leads with a number, so no row is a header candidate.
        let rows = vec![
            row(1, &[num(1, 1), txt(2, "alpha")]),
            row(2, &[num(1, 2), txt(2, "beta")]),
        ];
        assert!(find_header(&rows).is_none());
        let mut recs = Vec::new();
        let mut stats = ExtractStats::default();
        emit_document_sheet(
            "Notes",
            "book",
            &rows,
            &mut |r| {
                recs.push(r);
                true
            },
            &mut stats,
        );
        assert_eq!(stats.records, 1);
        let body = recs[0].fields["body"].as_str().unwrap();
        assert!(body.contains("1 | alpha") && body.contains("2 | beta"));
        assert_eq!(recs[0].fields["title"], "book — Notes");
        assert_eq!(recs[0].fields["sheet"], "Notes");
    }

    #[test]
    fn date_cell_formats_match_the_xlsx_extractor() {
        // calamine resolves an ExcelDateTime; check the bare-date vs datetime
        // split against a serial we can predict (1904-01-01 is serial 1462 in
        // the 1900 system; use a known midnight serial instead).
        use calamine::ExcelDateTime;
        // 2025-07-01 00:00:00 — serial 45839 in the 1900 date system.
        let d = Data::DateTime(ExcelDateTime::new(
            45839.0,
            calamine::ExcelDateTimeType::DateTime,
            false,
        ));
        let cell = date_cell(1, &d).unwrap();
        assert_eq!(cell.kind, Kind::Date);
        assert_eq!(cell.value, json!("2025-07-01"));
    }

    fn rec(locator: &str) -> RawRecord {
        let mut fields = Map::new();
        fields.insert("Region".into(), Value::String("EMEA".into()));
        fields.insert("Revenue".into(), Value::Number(1250.into()));
        RawRecord {
            fields,
            locator: locator.to_string(),
            group: Some("Sales".into()),
            origin: FieldOrigin::Data,
        }
    }

    /// The parent reconstructs the worker's records byte-for-byte: a `Rec` line
    /// round-trips every field, the locator, the group and the origin, and the
    /// `End` line is not mistaken for a record.
    #[test]
    fn worker_line_rec_and_end_round_trip() {
        let line = serde_json::to_string(&WorkerLine::Rec(rec("Sales!r4"))).unwrap();
        // A record line carries no discriminator a RawRecord could own.
        assert!(line.contains("\"k\":\"rec\""));
        match serde_json::from_str::<WorkerLine>(&line).unwrap() {
            WorkerLine::Rec(r) => {
                assert_eq!(r.locator, "Sales!r4");
                assert_eq!(r.group.as_deref(), Some("Sales"));
                assert_eq!(r.origin, FieldOrigin::Data);
                assert_eq!(r.fields["Region"], json!("EMEA"));
                assert_eq!(r.fields["Revenue"], json!(1250));
            }
            WorkerLine::End { .. } => panic!("record line decoded as terminator"),
        }
        let end = serde_json::to_string(&WorkerLine::End { truncated: true }).unwrap();
        assert!(matches!(
            serde_json::from_str::<WorkerLine>(&end).unwrap(),
            WorkerLine::End { truncated: true }
        ));
    }

    /// The NDJSON parser rebuilds the record list and the truncation flag, and
    /// tolerates the blank splits a trailing newline produces.
    #[cfg(unix)]
    #[test]
    fn parse_worker_output_reconstructs_records_and_truncation() {
        let mut buf = Vec::new();
        buf.extend_from_slice(
            serde_json::to_string(&WorkerLine::Rec(rec("Sales!r4")))
                .unwrap()
                .as_bytes(),
        );
        buf.push(b'\n');
        buf.extend_from_slice(
            serde_json::to_string(&WorkerLine::Rec(rec("Sales!r5")))
                .unwrap()
                .as_bytes(),
        );
        buf.push(b'\n');
        buf.extend_from_slice(
            serde_json::to_string(&WorkerLine::End { truncated: true })
                .unwrap()
                .as_bytes(),
        );
        buf.push(b'\n');
        let (records, truncated) = parse_worker_output(&buf).unwrap();
        assert_eq!(records.len(), 2);
        assert_eq!(records[0].locator, "Sales!r4");
        assert_eq!(records[1].locator, "Sales!r5");
        assert!(truncated);
    }

    /// A stream cut short before the terminator — exactly the shape of a worker
    /// that crashed mid-emit after flushing a record — is an error, so the
    /// parent discards the partial file rather than indexing half of it.
    #[cfg(unix)]
    #[test]
    fn parse_worker_output_rejects_a_missing_terminator() {
        let mut buf = Vec::new();
        buf.extend_from_slice(
            serde_json::to_string(&WorkerLine::Rec(rec("Sales!r4")))
                .unwrap()
                .as_bytes(),
        );
        buf.push(b'\n');
        assert!(parse_worker_output(&buf).is_err());
        // Garbage that is not our protocol is also rejected.
        assert!(parse_worker_output(b"{not json}\n").is_err());
        // A clean empty run (no rows, just a terminator) is valid and empty.
        let end = serde_json::to_string(&WorkerLine::End { truncated: false }).unwrap();
        let (records, truncated) = parse_worker_output(end.as_bytes()).unwrap();
        assert!(records.is_empty() && !truncated);
    }
}

//! YAML — multi-document streams; each doc becomes a record (a top-level
//! sequence of mappings becomes per-element records). 16MB file cap.

use super::{flatten_object, yaml_to_json, ExtractStats, FieldOrigin, RawRecord, Sink};
use anyhow::Result;
use serde_json::{Map, Value};
use std::path::Path;

const YAML_CAP: u64 = 16 << 20;

pub fn extract(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
    let mut stats = ExtractStats::default();
    let Some(bytes) = super::read_whole(path, gzip, YAML_CAP)? else {
        stats.junk += 1;
        return Ok(stats);
    };
    let (text, _) = crate::sniff::decode_text(&bytes);
    let mut any = false;
    for (d, de) in serde_yaml::Deserializer::from_str(&text).enumerate() {
        let yv: serde_yaml::Value = match serde_yaml::Value::deserialize(de) {
            Ok(v) => v,
            Err(_) => {
                // MUST break, never continue: serde_yaml's multi-document
                // iterator does not advance past a document that fails to
                // parse — `continue` re-yields the same broken document
                // forever (live hang: a markdown task list `- [ ] …` sniffed
                // as YAML spun autoindex phase A indefinitely). Junk-file the
                // rest of the stream instead; the loss is recorded, not
                // hidden.
                stats.junk += 1;
                break;
            }
        };
        any = true;
        let jv = yaml_to_json(yv);
        match jv {
            Value::Array(arr) if arr.iter().all(|e| e.is_object()) && !arr.is_empty() => {
                for (i, el) in arr.into_iter().enumerate() {
                    if let Value::Object(m) = el {
                        stats.records += 1;
                        if !sink(RawRecord {
                            fields: flatten_object(m),
                            locator: format!("d{d}e{i}"),
                            group: None,
                            origin: FieldOrigin::Data,
                        }) {
                            return Ok(stats);
                        }
                    }
                }
            }
            Value::Object(m) => {
                stats.records += 1;
                if !sink(RawRecord {
                    fields: flatten_object(m),
                    locator: format!("d{d}"),
                    group: None,
                    origin: FieldOrigin::Data,
                }) {
                    return Ok(stats);
                }
            }
            other => {
                let mut m = Map::new();
                m.insert("value".into(), other);
                stats.records += 1;
                if !sink(RawRecord {
                    fields: m,
                    locator: format!("d{d}"),
                    group: None,
                    origin: FieldOrigin::Data,
                }) {
                    return Ok(stats);
                }
            }
        }
    }
    if !any && stats.junk == 0 {
        stats.junk += 1;
    }
    Ok(stats)
}

use serde::Deserialize;

#[cfg(test)]
mod tests {
    use super::*;

    fn extract_str(text: &str) -> (ExtractStats, usize) {
        let dir = std::env::temp_dir().join(format!(
            "xerj-yamlx-test-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("t.yaml");
        std::fs::write(&path, text).unwrap();
        let mut n = 0usize;
        let stats = extract(&path, false, &mut |_r| {
            n += 1;
            true
        })
        .unwrap();
        std::fs::remove_dir_all(&dir).ok();
        (stats, n)
    }

    /// Regression for a live hang: serde_yaml's multi-document iterator does
    /// not advance past a document that fails to parse, so `continue` on the
    /// error re-yielded the same broken document forever. A markdown task
    /// list sniffed as YAML (`- [ ] …` is invalid YAML) spun autoindex phase
    /// A indefinitely. The extractor must terminate and junk-file instead.
    #[test]
    fn broken_document_terminates_as_junk_not_forever() {
        let (stats, n) = extract_str("# Launch checklist\n- [ ] alpha\n- [ ] beta\n");
        assert_eq!(n, 0, "invalid YAML must not fabricate records");
        assert!(stats.junk >= 1, "the unparseable stream is junk-filed");
    }

    #[test]
    fn valid_multi_document_stream_still_yields_records() {
        let (stats, n) = extract_str("a: 1\nb: two\n---\nc: 3\n");
        assert_eq!(n, 2);
        assert_eq!(stats.records, 2);
        assert_eq!(stats.junk, 0);
    }
}

//! HTTP-level regression tests for the file replacement transaction.
//!
//! These deliberately exercise `run_index`, `Es`, extraction, staging, bulk
//! splitting, and the durable journal together. The fake endpoint injects a
//! per-item backend failure after applying part of a bulk, which models the
//! most dangerous response shape: visibility changed, but `file_done` must
//! not be durable.

use super::*;
use std::collections::HashMap;
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};
use std::thread;

static FAILPOINT_TEST_LOCK: Mutex<()> = Mutex::new(());

/// #953: the replacement failpoint fires only in the run it was armed for.
///
/// It was a bare process-wide boundary number, so any concurrent test that
/// drove the legacy path took the injected crash: that test failed with an
/// error it had nothing to do with and the arming test ran clean. Keyed on the
/// state directory, another run at the same boundary passes straight through,
/// and so does the armed run at a different boundary. Holds
/// `FAILPOINT_TEST_LOCK` because arming REPLACES whatever is armed.
#[test]
fn replacement_failpoint_cannot_be_taken_by_another_run() {
    let _guard = FAILPOINT_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let mine = tempfile::tempdir().unwrap();
    let theirs = tempfile::tempdir().unwrap();
    arm_replacement_failpoint(4, mine.path());

    replacement_failpoint(4, theirs.path()).expect("another run at the armed boundary");
    replacement_failpoint(2, mine.path()).expect("the armed run at another boundary");

    let error = replacement_failpoint(4, mine.path()).unwrap_err();
    assert!(
        format!("{error:#}").contains("injected replacement crash boundary 4"),
        "{error:#}"
    );
    replacement_failpoint(4, mine.path()).expect("the failpoint is one-shot");
}

/// Owns the process-global PDF worker environment for the duration of one
/// test. `XERJ_PDF_WORKER_BIN` is read inside `spawn_worker`, so a test that
/// sets it silently rewrites what every concurrently running test in this
/// binary observes — including the unit tests in `extract::pdf`. Acquire this
/// **before** the first `set_var`; the shared lock is the only thing that
/// makes those two suites safe to run at the default thread count.
#[cfg(unix)]
struct PdfWorkerEnvGuard {
    /// Held, never read: dropping it after the environment is cleared is the
    /// whole point.
    _lock: std::sync::MutexGuard<'static, ()>,
}

#[cfg(unix)]
impl PdfWorkerEnvGuard {
    fn acquire() -> Self {
        Self {
            _lock: crate::extract::pdf::WORKER_BIN_ENV_LOCK
                .lock()
                .unwrap_or_else(|poison| poison.into_inner()),
        }
    }
}

#[cfg(unix)]
impl Drop for PdfWorkerEnvGuard {
    fn drop(&mut self) {
        std::env::remove_var("XERJ_PDF_WORKER_BIN");
        std::env::remove_var("XERJ_TEST_PDF_COUNT");
    }
}

fn inject_pdf_spool_capacity(state_dir: &Path) {
    for (name, value) in [
        ("available-bytes", 16_u64 << 30),
        ("fd-limit", 4096),
        ("fd-open", 16),
    ] {
        fs::write(
            state_dir.join(format!(".autoindex-test-pdf-spool-{name}")),
            value.to_string(),
        )
        .unwrap();
    }
}

#[derive(Default)]
struct MockState {
    docs: HashMap<String, Value>,
    /// Catalog documents, kept apart from `docs` on purpose: `docs.len()` is
    /// what `_count`/`_search` answer with, and the run verifies live data
    /// counts against the journal (#195). Catalog rows are not data rows.
    catalog_docs: HashMap<String, Value>,
    /// Every (method, path) the run issued. The refusal tests assert on the
    /// ABSENCE of remote mutations, which no document count can express.
    requests: Vec<(String, String)>,
    data_bulk_number: usize,
    fail_data_bulk: usize,
    failed_once: bool,
    delete_calls: usize,
    response_delay_ms: u64,
    catalog_preexists: bool,
    catalog_mapping_upgraded: bool,
    /// #755: whether a catalog `_mapping` PUT declared the keyword corpus-scope
    /// field. On this legacy path it arrives in its own PUT, because `prefix`
    /// cannot be re-declared on a catalog that already holds it as `text`.
    catalog_corpus_scope_mapped: bool,
    catalog_bulk_before_upgrade: bool,
    /// Set if the additive mapping upgrade ever asks for `started`. This is
    /// the executable half of `catalog::catalog_mapping`'s tripwire: against a
    /// legacy (v1.0.0-rc.4) catalog that request is refused 400 and aborts the
    /// run, so the product must never send it. Asserted false rather than left
    /// to the 400 branch below, which a correct product never reaches.
    started_mapping_requested: bool,
    /// Catalog bulk actions the fixture does not model. Recorded rather than
    /// panicked on: this runs inside the server thread while the state guard
    /// is held, so a panic here would poison the `Mutex` and turn
    /// `MockEndpoint::drop`'s `join().unwrap()` into a second, misleading
    /// panic. Tests assert on it from the test thread instead.
    unexpected_catalog_actions: Vec<String>,
    stop: bool,
    embedding_identity_sha256: String,
    /// Reject every data-bulk item with a 403 explicit write-block error
    /// (the status ES gives `index.blocks.write` / `read_only`; only the
    /// flood-stage block is 429) without applying anything — the #195 shape.
    block_writes: bool,
    /// Accept every data bulk (`errors: false`) but persist nothing — the
    /// shape of any rejection path the client-side classifier misses.
    swallow_data_bulks: bool,
    /// `_count` answers 200 with no `count`, and a size:0 `_search` answers
    /// `timed_out`. Models a node that accepted the writes and then could
    /// not finish a count (merge, deadline). Must not look like zero docs.
    fail_counts: bool,
    /// Answer the catalog's duplicate-alias sweep — and ONLY that request —
    /// with a 500 whose body names the condition. Scoped to the one call so
    /// the fixture proves the sweep is what wedged the run (#345), not that a
    /// server which 500s everything fails.
    ///
    /// #905: the sweep is a candidate `_search` followed by a by-`_id` delete
    /// now, not one `_delete_by_query`, so the fault is injected on the search.
    /// It is still the first and only server call the sweep makes, which is
    /// what the fixture needs.
    fail_alias_sweep: bool,
    /// One entry per alias-sweep request, holding the paths it named. The
    /// sweep used to be one round trip per duplicate path, so the batching is
    /// only observable here.
    alias_sweep_batches: Vec<Vec<String>>,
    /// Refuse the FIRST document of every data bulk with a per-item 400 and
    /// apply the rest. This is the one bulk shape that produces an
    /// `item_error` without a `server_error`: status is neither 429 nor 5xx
    /// and the type is not a block, so the run continues and must still
    /// report the rejection.
    reject_first_data_item: bool,
    /// Opt-in (#929): refuse the create-index PUT — which on this path carries
    /// the dataset's whole mapping — of every index whose name contains one of
    /// these, with the 400 a real engine returns for a field it cannot map.
    refused_dataset_indices: Vec<String>,
    /// Opt-in (#944): answer this many data bulks — the next ones — with a
    /// per-item 429 on EVERY item and apply nothing, the way the engine's
    /// memory circuit breaker does for the moment it is engaged. Then behave
    /// normally, so the client's re-send of exactly those items can land.
    throttle_data_bulks: usize,
    /// Opt-in (#955): the engine's `limits.max_actions_per_bulk`. A `_bulk` of
    /// more than twice this many lines — data or catalog — is refused whole
    /// with the engine's literal answer: HTTP 200, ONE item of status 413,
    /// nothing applied.
    max_actions_per_bulk: Option<usize>,
    /// Line count of every bulk `max_actions_per_bulk` refused, in order.
    oversize_bulks_refused: Vec<usize>,
    /// Opt-in (#1977): answer the catalog bulk `errors: false` and persist
    /// nothing. The data path's zero-live gate already refuses this shape;
    /// the catalog write used to exit 0 with an empty `autoindex-catalog`.
    swallow_catalog_bulks: bool,
    /// Opt-in (#1977): refuse every catalog action with a per-item 400 and
    /// persist nothing. Status 400 is not a `server_error`, so it used to be
    /// a warning on an exit-0 run.
    reject_catalog_items: bool,
}

struct MockEndpoint {
    url: String,
    state: Arc<Mutex<MockState>>,
    join: Option<thread::JoinHandle<()>>,
}

impl MockEndpoint {
    fn start(fail_data_bulk: usize) -> Self {
        Self::start_with_delay(fail_data_bulk, 0)
    }

    fn start_with_delay(fail_data_bulk: usize, response_delay_ms: u64) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        let state = Arc::new(Mutex::new(MockState {
            fail_data_bulk,
            response_delay_ms,
            embedding_identity_sha256: "a".repeat(64),
            ..MockState::default()
        }));
        let server_state = Arc::clone(&state);
        let join = thread::spawn(move || loop {
            match listener.accept() {
                Ok((stream, _)) => {
                    // BSD/macOS: accepted sockets inherit the listener's
                    // O_NONBLOCK; the handler does blocking reads.
                    stream.set_nonblocking(false).unwrap();
                    handle(stream, &server_state)
                }
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    if server_state
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .stop
                    {
                        break;
                    }
                    thread::yield_now();
                }
                Err(error) => panic!("mock endpoint accept failed: {error}"),
            }
        });
        Self {
            url,
            state,
            join: Some(join),
        }
    }

    fn start_with_existing_catalog() -> Self {
        let endpoint = Self::start(usize::MAX);
        endpoint.state.lock().unwrap().catalog_preexists = true;
        endpoint
    }
}

impl Drop for MockEndpoint {
    fn drop(&mut self) {
        self.state
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .stop = true;
        // Wake the nonblocking listener even on heavily loaded test hosts.
        let _ = TcpStream::connect(self.url.trim_start_matches("http://"));
        let _ = self.join.take().unwrap().join();
    }
}

fn handle(mut stream: TcpStream, state: &Arc<Mutex<MockState>>) {
    let clone = stream.try_clone().unwrap();
    let mut reader = BufReader::new(clone);
    let mut request_line = String::new();
    if reader.read_line(&mut request_line).unwrap() == 0 {
        return;
    }
    let mut content_length = 0usize;
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        if line == "\r\n" || line.is_empty() {
            break;
        }
        if let Some(value) = line
            .to_ascii_lowercase()
            .strip_prefix("content-length:")
            .map(str::trim)
        {
            content_length = value.parse().unwrap();
        }
    }
    let mut body = vec![0; content_length];
    reader.read_exact(&mut body).unwrap();
    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("");
    let path = parts.next().unwrap_or("");
    state
        .lock()
        .unwrap()
        .requests
        .push((method.to_owned(), path.to_owned()));
    let response_delay_ms = state.lock().unwrap().response_delay_ms;
    if response_delay_ms > 0 {
        thread::sleep(std::time::Duration::from_millis(response_delay_ms));
    }

    let (status, response) = if method == "GET" && path == "/v1/embedding/identity" {
        let identity = state.lock().unwrap().embedding_identity_sha256.clone();
        (
            200,
            json!({"data": {
                "version": 1,
                "backend": "lexical",
                "identity_sha256": identity,
                "dimensions": 384,
                "semantic_contract": "semantic_text-derived-vector.v1",
                "resumable": true
            }, "took_ms": 0, "request_id": "test"}),
        )
    } else if method == "PUT"
        && !path.starts_with("/autoindex-catalog")
        && state
            .lock()
            .unwrap()
            .refused_dataset_indices
            .iter()
            .any(|needle| path.contains(needle.as_str()))
    {
        // #929. Deliberately worded without "exists": `Es::ensure_index` reads
        // a 400 containing that word as "the index is already there".
        let reason = "nested semantic_text field [a.b] is not supported; map semantic_text as a \
                      top-level field";
        (
            400,
            json!({
                "error": {
                    "root_cause": [{"type": "mapper_parsing_exception", "reason": reason}],
                    "type": "mapper_parsing_exception",
                    "reason": reason
                },
                "status": 400
            }),
        )
    } else if method == "PUT" && path == "/autoindex-catalog" {
        if state.lock().unwrap().catalog_preexists {
            (
                400,
                json!({"error": {"type": "resource_already_exists_exception"}}),
            )
        } else {
            (200, json!({"acknowledged": true}))
        }
    } else if method == "PUT" && path == "/autoindex-catalog/_mapping" {
        let mapping: Value = serde_json::from_slice(&body).unwrap();
        let started_requested = mapping.pointer("/properties/started").is_some();
        let required = ["summary_generated_at", "invocation_telemetry_scope"];
        let upgraded = required.iter().all(|field| {
            mapping
                .pointer(&format!("/properties/{field}/type"))
                .and_then(Value::as_str)
                .is_some()
        });
        let corpus_scope_requested = mapping
            .pointer(&format!("/properties/{}/type", catalog::CORPUS_SCOPE_FIELD))
            .and_then(Value::as_str)
            == Some("keyword");
        let mut locked = state.lock().unwrap();
        locked.started_mapping_requested |= started_requested;
        if locked.catalog_preexists && started_requested {
            // The shape a real engine returns when the additive upgrade asks
            // for `started` on a legacy (v1.0.0-rc.4) catalog, where `started`
            // was dynamically inferred as `text`. Measured against a live
            // v1.0.0-rc.13 engine, not read off the handler: the request falls
            // past the `illegal_argument_exception` guard — that one only sees
            // *declared* mappings, and `started` was never declared — and is
            // refused by the `idx.schema()` guard, which returns
            // `XerjError::invalid_mapping` and therefore a 400
            // `mapper_parsing_exception`.
            //
            // A correct product never reaches this branch (see
            // `started_mapping_requested`, asserted false in
            // `existing_catalog_is_upgraded_before_new_run_metadata_is_written`).
            // It is kept, and kept accurate, so that adding `started` to the
            // additive upgrade fails here with the message the operator would
            // really see rather than passing silently.
            let reason = "field [started] already exists as [text], cannot add [date]";
            (
                400,
                json!({
                    "error": {
                        "root_cause": [{"type": "mapper_parsing_exception", "reason": reason}],
                        "type": "mapper_parsing_exception",
                        "reason": reason,
                    },
                    "status": 400,
                }),
            )
        } else {
            // #755: the additive upgrade and the corpus-scope field arrive in
            // SEPARATE PUTs now, so this accumulates rather than overwrites —
            // the flag means "the additive upgrade has landed", and the guard
            // that new run metadata must not precede it depends on that.
            locked.catalog_mapping_upgraded |= upgraded;
            locked.catalog_corpus_scope_mapped |= corpus_scope_requested;
            (200, json!({"acknowledged": true}))
        }
    } else if method == "POST" && path == "/_bulk" {
        (200, bulk_response(&body, state))
    } else if method == "POST" && path.contains("/_delete_by_query") {
        let query: Value = serde_json::from_slice(&body).unwrap();
        // A replacement purge is a `bool.should` of `ax_file` and `ax_path`
        // (#2139). A lone `term` is the older shape, still sent by sweeps.
        // Either term matching is enough: the path term is what drops a
        // generation published under a different content key.
        let mut file_terms: Vec<(String, String)> = Vec::new();
        for field in ["ax_file", "ax_path"] {
            if let Some(value) = query
                .pointer(&format!("/query/term/{field}"))
                .and_then(Value::as_str)
            {
                file_terms.push((field.to_string(), value.to_string()));
            }
        }
        if let Some(should) = query
            .pointer("/query/bool/should")
            .and_then(Value::as_array)
        {
            for clause in should {
                for field in ["ax_file", "ax_path"] {
                    if let Some(value) = clause
                        .pointer(&format!("/term/{field}"))
                        .and_then(Value::as_str)
                    {
                        file_terms.push((field.to_string(), value.to_string()));
                    }
                }
            }
        }
        let file_key = query
            .pointer("/query/term/file_key")
            .and_then(Value::as_str)
            .map(str::to_owned);
        // #905: the scoped catalog sweeps delete by exact `_id` now — the
        // corpus scope is decided client-side, per hit, so the delete carries
        // no predicate at all beyond the id list.
        let ids: Vec<String> = query
            .pointer("/query/ids/values")
            .and_then(Value::as_array)
            .map(|values| {
                values
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::to_owned)
                    .collect()
            })
            .unwrap_or_default();
        let mut locked = state.lock().unwrap();
        locked.delete_calls += 1;
        if !file_terms.is_empty() {
            locked.docs.retain(|_, doc| {
                !file_terms.iter().any(|(field, expected)| {
                    doc.get(field).and_then(Value::as_str) == Some(expected.as_str())
                })
            });
        }
        if let Some(key) = file_key {
            locked
                .catalog_docs
                .retain(|_, doc| doc.get("file_key").and_then(Value::as_str) != Some(key.as_str()));
        }
        // Catalog only: every by-`_id` delete this client issues names
        // `catalog::CATALOG_INDEX`. Report how many documents this pass
        // actually removed. `delete_by_query` repeats until a pass reports
        // zero, so answering `ids.len()` after the documents are gone loops
        // until the client gives up (#2314).
        let mut removed = 0u64;
        for id in &ids {
            if locked.catalog_docs.remove(id).is_some() {
                removed += 1;
            }
        }
        (200, json!({"deleted": removed, "failures": []}))
    } else if method == "GET" && path.ends_with("/_count") {
        if state.lock().unwrap().fail_counts {
            (200, json!({"error": "count unavailable"}))
        } else {
            (200, json!({"count": state.lock().unwrap().docs.len()}))
        }
    } else if method == "POST"
        && path.ends_with("/_search")
        && serde_json::from_slice::<Value>(&body)
            .ok()
            .is_some_and(|query| query.get("size").and_then(Value::as_u64) == Some(0))
        && state.lock().unwrap().fail_counts
    {
        (
            200,
            json!({
                "took": 1,
                "timed_out": true,
                "hits": {"total": {"value": 0, "relation": "gte"}, "hits": []}
            }),
        )
    } else if method == "POST"
        && path.starts_with("/autoindex-catalog/")
        && path.ends_with("/_search")
        && serde_json::from_slice::<Value>(&body)
            .ok()
            .is_some_and(|query| {
                query
                    .pointer("/query/ids/values")
                    .and_then(Value::as_array)
                    .is_some()
            })
    {
        // #1977: the graph path reads catalog rows back by `_id` after the
        // write. Answer with the documents actually stored — an empty `hits`
        // array here would fail every successful run.
        let query: Value = serde_json::from_slice(&body).unwrap();
        let wanted = query
            .pointer("/query/ids/values")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let locked = state.lock().unwrap();
        let mut hits: Vec<Value> = wanted
            .iter()
            .filter_map(Value::as_str)
            .filter_map(|id| {
                locked
                    .catalog_docs
                    .get(id)
                    .map(|doc| json!({"_id": id, "_source": doc}))
            })
            .collect();
        hits.sort_by(|left, right| left["_id"].as_str().cmp(&right["_id"].as_str()));
        (
            200,
            json!({
                "hits": {
                    "total": {"value": hits.len(), "relation": "eq"},
                    "hits": hits
                }
            }),
        )
    } else if method == "POST" && path.ends_with("/_search") {
        // Report the REAL number of stored docs: `run_index` verifies live
        // counts against the journal (#195), so a mock that always answered 0
        // hits would (rightly) fail every successful run. The generated path
        // additionally reads back per-file and per-catalog projections, so the
        // count is filtered by whichever identity the query names.
        let query: Value = serde_json::from_slice(&body).unwrap_or(Value::Null);
        // The catalog's duplicate-alias sweep. Recognised by SHAPE — a
        // `status: duplicate` filter beside a `path` terms list — because
        // since #345 one request carries a whole chunk of paths rather than
        // one path per round trip. #905 moved it from `_delete_by_query` to a
        // candidate `_search`: the query is the same, and it is still one
        // request per chunk, which is what the batching assertion measures.
        let filter = query
            .pointer("/query/bool/filter")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let alias_sweep = filter
            .iter()
            .any(|clause| {
                clause.pointer("/term/status").and_then(Value::as_str) == Some("duplicate")
            })
            .then(|| {
                filter
                    .iter()
                    .find_map(|clause| clause.pointer("/terms/path").and_then(Value::as_array))
                    .map(|paths| {
                        paths
                            .iter()
                            .filter_map(Value::as_str)
                            .map(str::to_owned)
                            .collect::<Vec<String>>()
                    })
                    .unwrap_or_default()
            });
        if let Some(swept) = alias_sweep {
            let mut locked = state.lock().unwrap();
            // Recorded before the fault so a refused sweep is counted too —
            // the point of the batching assertion is how many round trips the
            // run made, not how many of them succeeded.
            locked.alias_sweep_batches.push(swept.clone());
            if locked.fail_alias_sweep {
                // What a poisoned catalog collection really answers: a 500
                // whose BODY names the condition. The client used to keep the
                // status and discard the body, which is the whole reason #345
                // was filed "not investigated".
                (
                    500,
                    json!({
                        "error": {
                            "type": "internal_server_error_exception",
                            "reason": "collection publication was interrupted; reopen the index \
                                       so WAL recovery can rebuild a consistent searchable state"
                        },
                        "status": 500
                    }),
                )
            } else {
                let mut hits: Vec<Value> = locked
                    .catalog_docs
                    .iter()
                    .filter(|(_, doc)| {
                        doc.get("status").and_then(Value::as_str) == Some("duplicate")
                            && swept.iter().any(|path| {
                                doc.get("path").and_then(Value::as_str) == Some(path.as_str())
                            })
                    })
                    .map(|(id, doc)| json!({"_id": id, "_source": doc}))
                    .collect();
                // Deterministic order, so a page boundary is never `HashMap`
                // iteration order.
                hits.sort_by(|left, right| left["_id"].as_str().cmp(&right["_id"].as_str()));
                (
                    200,
                    json!({
                        "hits": {
                            "total": {"value": hits.len(), "relation": "eq"},
                            "hits": hits
                        },
                        "aggregations": {}
                    }),
                )
            }
        } else if path.contains(catalog::CATALOG_INDEX)
            && query.pointer("/query/bool/filter").is_some()
        {
            // #2314: a deletion sweep reads catalog candidates with a
            // `bool.filter` of term clauses and deletes the hits by `_id`.
            // An empty `hits` array made that sweep a no-op.
            let filters = query
                .pointer("/query/bool/filter")
                .and_then(Value::as_array)
                .cloned()
                .unwrap_or_default();
            let locked = state.lock().unwrap();
            let mut hits: Vec<Value> = locked
                .catalog_docs
                .iter()
                .filter(|(_, doc)| {
                    filters.iter().all(|clause| {
                        clause
                            .get("term")
                            .and_then(Value::as_object)
                            .is_none_or(|term| {
                                term.iter()
                                    .all(|(field, value)| doc.get(field) == Some(value))
                            })
                            && clause
                                .get("terms")
                                .and_then(Value::as_object)
                                .and_then(|terms| terms.iter().next())
                                .is_none_or(|(field, values)| {
                                    values.as_array().is_some_and(|values| {
                                        values.iter().any(|value| doc.get(field) == Some(value))
                                    })
                                })
                    })
                })
                .map(|(id, doc)| json!({"_id": id, "_source": doc}))
                .collect();
            hits.sort_by(|left, right| left["_id"].as_str().cmp(&right["_id"].as_str()));
            let total = hits.len();
            let from = query.get("from").and_then(Value::as_u64).unwrap_or(0) as usize;
            let size = query
                .get("size")
                .and_then(Value::as_u64)
                .map(|size| size as usize)
                .unwrap_or(total);
            let page: Vec<Value> = hits.into_iter().skip(from).take(size).collect();
            (
                200,
                json!({
                    "hits": {
                        "total": {"value": total, "relation": "eq"},
                        "hits": page
                    }
                }),
            )
        } else {
            let ax_file = query
                .pointer("/query/term/ax_file")
                .or_else(|| query.pointer("/query/bool/must/0/term/ax_file"))
                .and_then(Value::as_str);
            let file_key = query
                .pointer("/query/term/file_key")
                .and_then(Value::as_str);
            let locked = state.lock().unwrap();
            let documents = if file_key.is_some() {
                &locked.catalog_docs
            } else {
                &locked.docs
            };
            let count = documents
                .values()
                .filter(|doc| {
                    ax_file
                        .is_none_or(|key| doc.get("ax_file").and_then(Value::as_str) == Some(key))
                        && file_key.is_none_or(|key| {
                            doc.get("file_key").and_then(Value::as_str) == Some(key)
                        })
                })
                .count();
            (
                200,
                json!({"hits":{"total":{"value":count},"hits":[]},"aggregations":{}}),
            )
        }
    } else {
        // ping, index creation/mapping, refresh, and catalog operations
        (200, json!({"acknowledged": true}))
    };
    let bytes = response.to_string();
    let reason = match status {
        200 => "OK",
        500 => "Internal Server Error",
        _ => "Bad Request",
    };
    write!(
        stream,
        "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        bytes.len(),
        bytes
    )
    .unwrap();
}

fn bulk_response(body: &[u8], state: &Arc<Mutex<MockState>>) -> Value {
    let lines: Vec<&[u8]> = body
        .split(|byte| *byte == b'\n')
        .filter(|line| !line.is_empty())
        .collect();
    let is_data = lines
        .first()
        .and_then(|line| serde_json::from_slice::<Value>(line).ok())
        .and_then(|action| action.pointer("/index/_index").cloned())
        .and_then(|index| index.as_str().map(str::to_owned))
        .is_some_and(|index| index != catalog::CATALOG_INDEX);
    // Graph edge bulks are accepted and discarded: this module counts *data*
    // bulks to place injected failures, so edge bulks must not shift the
    // numbering (the graph pipeline has its own e2e suite in detect::e2e).
    //
    // Read the target off whichever action verb the line carries. The brain
    // meta document is written with `create`, not `index`, so keying on
    // `/index/_index` alone let it fall through to the catalog branch and be
    // recorded as fixture drift once this module started indexing with the
    // graph enabled.
    let is_graph = lines
        .first()
        .and_then(|line| serde_json::from_slice::<Value>(line).ok())
        .and_then(|action| {
            ["index", "create", "delete", "update"]
                .iter()
                .find_map(|verb| {
                    action
                        .pointer(&format!("/{verb}/_index"))
                        .and_then(Value::as_str)
                        .map(str::to_owned)
                })
        })
        .is_some_and(|index| index.ends_with("-edges"));
    if is_graph {
        return json!({"errors": false, "items": []});
    }
    {
        // Checked before anything is applied and by LINES, as
        // `xerj-engine/src/bulk.rs` does.
        let mut locked = state.lock().unwrap();
        if let Some(max_actions) = locked.max_actions_per_bulk {
            if lines.len() > max_actions * 2 {
                locked.oversize_bulks_refused.push(lines.len());
                return json!({
                    "took": 0,
                    "errors": true,
                    "items": [{"index": {
                        "_index": "",
                        "_id": "",
                        "status": 413,
                        "error": {
                            "type": "engine_exception",
                            "reason": format!(
                                "bulk request contains {} lines (~{} actions); exceeds \
                                 max_actions_per_bulk of {max_actions}",
                                lines.len(),
                                lines.len() / 2
                            ),
                            "status": 413
                        }
                    }}]
                });
            }
        }
    }
    if !is_data {
        // Catalog bulks mix `index` and `delete` actions (stale aliases, and
        // the junk sweep of #238), so walk the NDJSON rather than assuming
        // action/document pairs — a delete carries no document line.
        let mut locked = state.lock().unwrap();
        if locked.catalog_preexists && !locked.catalog_mapping_upgraded {
            locked.catalog_bulk_before_upgrade = true;
        }
        if locked.swallow_catalog_bulks {
            return json!({"errors": false, "items": []});
        }
        if locked.reject_catalog_items {
            let mut items = Vec::new();
            let mut line = 0;
            while line < lines.len() {
                let Ok(action) = serde_json::from_slice::<Value>(lines[line]) else {
                    line += 1;
                    continue;
                };
                let is_delete = action.get("delete").is_some();
                items.push(json!({"index": {
                    "status": 400,
                    "error": {
                        "type": "document_parsing_exception",
                        "reason": "failed to parse field [time_min] of type [date]"
                    }
                }}));
                line += if is_delete { 1 } else { 2 };
            }
            return json!({"errors": true, "items": items});
        }
        let mut line = 0;
        while line < lines.len() {
            let Ok(action) = serde_json::from_slice::<Value>(lines[line]) else {
                line += 1;
                continue;
            };
            if action.pointer("/delete/_index").and_then(Value::as_str)
                == Some(catalog::CATALOG_INDEX)
            {
                if let Some(id) = action.pointer("/delete/_id").and_then(Value::as_str) {
                    locked.catalog_docs.remove(id);
                }
                line += 1;
            } else if action.pointer("/index/_index").and_then(Value::as_str)
                == Some(catalog::CATALOG_INDEX)
                && line + 1 < lines.len()
            {
                let id = action.pointer("/index/_id").unwrap().as_str().unwrap();
                let doc: Value = serde_json::from_slice(lines[line + 1]).unwrap();
                locked.catalog_docs.insert(id.to_owned(), doc);
                line += 2;
            } else {
                // Fixture drift, not a product signal. Recorded rather than
                // panicked on: this runs on the server thread with the state
                // guard held, so a panic here poisons the `Mutex` and turns
                // `MockEndpoint::drop`'s `join().unwrap()` into a second,
                // misleading panic. Tests assert on it from the test thread.
                locked
                    .unexpected_catalog_actions
                    .push(format!("unexpected catalog bulk action: {action}"));
                line += 1;
            }
        }
        return json!({"errors": false, "items": []});
    }

    let mut locked = state.lock().unwrap();
    locked.data_bulk_number += 1;
    if locked.throttle_data_bulks > 0 {
        locked.throttle_data_bulks -= 1;
        let items: Vec<Value> = lines
            .as_chunks::<2>()
            .0
            .iter()
            .map(|_| {
                json!({"index": {
                    "status": 429,
                    "error": {
                        "type": "engine_exception",
                        "reason": "[parent] real memory circuit breaker tripped: rss=15679MB >= watermark=15564MB (94% of limit=16384MB); writes rejected to prevent an out-of-memory kill",
                        "status": 429
                    }
                }})
            })
            .collect();
        return json!({"errors": true, "items": items});
    }
    if locked.block_writes {
        // Explicit write block: per-item 403 (never 429/5xx), nothing applied.
        let items: Vec<Value> = lines
            .as_chunks::<2>()
            .0
            .iter()
            .map(|_| {
                json!({"index": {
                    "status": 403,
                    "error": {
                        "type": "cluster_block_exception",
                        "reason": "index [failure-test-csv] is blocked for write operations",
                        "status": 403
                    }
                }})
            })
            .collect();
        return json!({"errors": true, "items": items});
    }
    if locked.swallow_data_bulks {
        return json!({"errors": false, "items": []});
    }
    if locked.reject_first_data_item {
        let mut items = Vec::new();
        for (nth, pair) in lines.as_chunks::<2>().0.iter().enumerate() {
            if nth == 0 {
                items.push(json!({"index": {
                    "status": 400,
                    "error": {
                        "type": "document_parsing_exception",
                        "reason": "refused: value could not be parsed"
                    }
                }}));
                continue;
            }
            let action: Value = serde_json::from_slice(pair[0]).unwrap();
            let doc: Value = serde_json::from_slice(pair[1]).unwrap();
            let id = action.pointer("/index/_id").unwrap().as_str().unwrap();
            locked.docs.insert(id.to_owned(), doc);
            items.push(json!({"index": {"status": 201}}));
        }
        return json!({"errors": true, "items": items});
    }
    let fail = !locked.failed_once && locked.data_bulk_number == locked.fail_data_bulk;
    let (pairs, _) = lines.as_chunks::<2>();
    let visible = if fail { pairs.len() / 2 } else { pairs.len() };
    for pair in pairs.iter().take(visible) {
        let action: Value = serde_json::from_slice(pair[0]).unwrap();
        let doc: Value = serde_json::from_slice(pair[1]).unwrap();
        let id = action.pointer("/index/_id").unwrap().as_str().unwrap();
        locked.docs.insert(id.to_owned(), doc);
    }
    if fail {
        locked.failed_once = true;
        json!({
            "errors": true,
            "items": [{"index": {
                "status": 500,
                "error": {"type": "injected_failure", "reason": "partial bulk"}
            }}]
        })
    } else {
        json!({"errors": false, "items": []})
    }
}

fn cfg(root: &Path, state_dir: &Path, url: &str) -> IndexCfg {
    IndexCfg {
        root: root.to_owned(),
        endpoint_url: None,
        url: url.to_owned(),
        api_key: None,
        api_key_file: None,
        workers: 1,
        scan_workers: 1,
        pdf_workers: 1,
        resource_notes: Vec::new(),
        xerj_url_note: None,
        pdf_timeout_secs: 30,
        bulk_mb: 64,
        bulk_timeout_secs: 3_600,
        snapshot_max_bytes: 64 << 30,
        prefix: "failure-test".into(),
        replace_prefix: false,
        prefix_note: None,
        state_dir: Some(state_dir.to_owned()),
        fresh: false,
        follow_symlinks: false,
        follow_symlinks_outside_root: false,
        stub_globs: Vec::new(),
        ignore: crate::ignore_rules::IgnoreOptions::default(),
        max_file_bytes: 1 << 30,
        sample: 50,
        no_semantic: true,
        code_analyzer: Default::default(),
        // This module preserves legacy graph-enabled failure behavior;
        // incremental non-graph behavior has its own HTTP suite.
        brain: None,
        no_graph: false,
        // The gate is switched off in these fixtures on purpose: they assert
        // indexing, resume and edge behaviour, and a timing-derived stop would
        // make them depend on how loaded the runner was. The gate's own
        // behaviour is covered in `gate_tests` and `cli::tests`.
        max_minutes: 0,
        approve: None,
        max_index_bytes: None,
        budget_plan: None,
        drop_indexed: false,
        dry_run: false,
        walk_only: false,
        json: false,
        quiet: true,
        progress: crate::progress::ProgressMode::None,
        progress_interval: None,
        watch: false,
        label: None,
        debounce: std::time::Duration::from_millis(0),
        exclude_rels: Vec::new(),
        skip_corpus_data: false,
    }
}

/// Row documents only — the file-level graph node document this module's
/// graph-enabled config also publishes (`ax_locator: "file"`) is not part of
/// any replacement transaction's subject.
fn data_rows(state: &MockState) -> Vec<&Value> {
    state
        .docs
        .values()
        .filter(|doc| doc["ax_locator"].as_str() != Some("file"))
        .collect()
}

fn file_done_count(state_dir: &Path) -> usize {
    let journal = fs::read_to_string(state_dir.join("journal.ndjson")).unwrap();
    journal
        .lines()
        .filter(|line| {
            serde_json::from_str::<Value>(line)
                .ok()
                .and_then(|value| value.get("kind").cloned())
                .as_ref()
                .and_then(Value::as_str)
                == Some("file_done")
        })
        .count()
}

fn event_count(state_dir: &Path, kind: &str) -> usize {
    fs::read_to_string(state_dir.join("journal.ndjson"))
        .unwrap()
        .lines()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .filter(|value| value.get("kind").and_then(Value::as_str) == Some(kind))
        .count()
}

fn dataset_catalog_docs(endpoint: &MockEndpoint) -> Vec<Value> {
    let mut docs: Vec<Value> = endpoint
        .state
        .lock()
        .unwrap()
        .catalog_docs
        .values()
        .filter(|doc| doc.get("doc_kind").and_then(Value::as_str) == Some("dataset"))
        .cloned()
        .collect();
    docs.sort_by_key(|doc| {
        doc.get("slug")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string()
    });
    docs
}

/// The documented headline workflow: point autoindex at a folder, add a file,
/// rerun. The rerun must not fail, must say plainly that the added file was
/// not indexed, and `--fresh` must then absorb it in place.
/// Code/AST coverage on the LEGACY (graph-enabled) path.
///
/// #294 only ever affected the generated `--no-graph` executor, and that
/// asymmetry is exactly why it survived: the two paths reported identically,
/// so comparing their terminal lines told a caller nothing. The counters exist
/// on both, from one definition (`CodeCoverage`), so the next divergence
/// between them is visible in the output rather than only in the index.
#[test]
fn the_legacy_terminal_line_and_run_document_report_code_coverage() {
    let _guard = FAILPOINT_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let _io_guard = state::FILE_DONE_IO_FAILPOINT_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let _sink_guard = crate::progress::SINK_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    fs::write(
        corpus.path().join("alpha.rs"),
        "pub struct AlphaConfig {\n    pub retries: u32,\n}\n\n\
         pub fn alpha_connect(cfg: &AlphaConfig) -> bool {\n    cfg.retries > 0\n}\n",
    )
    .unwrap();
    fs::write(corpus.path().join("rows.csv"), "id,value\n1,first\n").unwrap();
    let endpoint = MockEndpoint::start(usize::MAX);
    let mut config = cfg(corpus.path(), state_dir.path(), &endpoint.url);
    assert!(!config.no_graph, "this module covers the legacy path");
    config.quiet = false;
    config.progress = crate::progress::ProgressMode::Plain;

    let buffer = Arc::new(Mutex::new(Vec::new()));
    let (code, report) = {
        let _sink = crate::progress::install_test_sink(&buffer);
        run_index_report(config).unwrap()
    };
    assert_eq!(code, 0);
    let report = report.unwrap();
    assert_eq!(report["code_files"], 1, "{report}");
    assert_eq!(report["code_files_indexed"], 1, "{report}");
    assert_eq!(report["code_files_junked"], 0, "{report}");
    let stream = String::from_utf8(buffer.lock().unwrap().clone()).unwrap();
    let done = stream
        .lines()
        .find(|line| line.starts_with("xerj-done "))
        .unwrap_or_else(|| panic!("{stream}"));
    assert!(
        done.contains("code_files=1 code_files_indexed=1 code_files_junked=0"),
        "{done}"
    );
    assert!(!stream.contains("warning:"), "{stream}");
    let locked = endpoint.state.lock().unwrap();
    let ast = locked
        .docs
        .values()
        // The file-level AST document carries `defs`; the #500 per-symbol
        // documents also carry `language` but no `defs`, so select on `defs`.
        .find(|doc| doc.get("language").is_some() && doc.get("defs").is_some())
        .unwrap_or_else(|| panic!("the legacy path indexes an AST document for alpha.rs"));
    assert_eq!(ast["language"], "rust", "{ast}");
    assert_eq!(ast["title"], "alpha.rs", "{ast}");
    assert!(
        ast["defs"]
            .as_str()
            .is_some_and(|defs| defs.contains("struct AlphaConfig")),
        "{ast}"
    );
}

/// #955 on the legacy (graph) path, where the defect was SILENT. The catalog
/// went out as one `_bulk` whatever `--bulk-mb` said; past the engine's
/// `max_actions_per_bulk` the answer is one item of status 413, which is
/// neither a 429 nor a 5xx, so `write catalog` counted one ignorable
/// `item_error` and the run reported success with no catalog at all — the map
/// every later `xerj autoindex map` and agent query reads. The catalog is now
/// windowed and a refused request is halved, so the whole catalog lands.
#[test]
fn a_catalog_bulk_the_server_refuses_as_too_large_still_lands_whole() {
    let _guard = FAILPOINT_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let _io_guard = state::FILE_DONE_IO_FAILPOINT_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let _sink_guard = crate::progress::SINK_TEST_LOCK
        .lock()
        .unwrap_or_else(|p| p.into_inner());
    let write_corpus = |root: &Path| {
        for name in ["a", "b", "c", "d", "e", "f"] {
            fs::write(
                root.join(format!("{name}.csv")),
                format!("id,value\n1,{name}-first\n2,{name}-second\n"),
            )
            .unwrap();
        }
    };
    let catalog_ids = |endpoint: &MockEndpoint| {
        let locked = endpoint.state.lock().unwrap();
        let mut ids: Vec<String> = locked
            .catalog_docs
            .iter()
            .map(|(id, doc)| {
                // A run document's id carries the run's own timestamp.
                if doc["doc_kind"] == "run" {
                    "run".to_owned()
                } else {
                    id.clone()
                }
            })
            .collect();
        ids.sort();
        ids
    };

    let control_corpus = tempfile::tempdir().unwrap();
    let control_state = tempfile::tempdir().unwrap();
    write_corpus(control_corpus.path());
    let control = MockEndpoint::start(usize::MAX);
    let (code, _) = run_index_report(cfg(
        control_corpus.path(),
        control_state.path(),
        &control.url,
    ))
    .unwrap();
    assert_eq!(code, 0);
    let expected = catalog_ids(&control);
    assert!(expected.len() > 4, "{expected:?}");

    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    write_corpus(corpus.path());
    let endpoint = MockEndpoint::start(usize::MAX);
    // Three actions a request: every data bulk here fits (one file, two rows),
    // so the ONLY request over the limit is the catalog — the silent case.
    endpoint.state.lock().unwrap().max_actions_per_bulk = Some(3);
    let mut config = cfg(corpus.path(), state_dir.path(), &endpoint.url);
    assert!(!config.no_graph, "this module covers the legacy path");
    config.quiet = false;
    config.progress = crate::progress::ProgressMode::Plain;
    let buffer = Arc::new(Mutex::new(Vec::new()));
    let (code, _report) = {
        let _sink = crate::progress::install_test_sink(&buffer);
        run_index_report(config).unwrap()
    };
    assert_eq!(code, 0);
    assert_eq!(
        catalog_ids(&endpoint),
        expected,
        "the catalog is the one an unlimited server gets — before #955 it was empty"
    );
    {
        let locked = endpoint.state.lock().unwrap();
        assert!(
            !locked.oversize_bulks_refused.is_empty(),
            "the limit was actually met"
        );
        assert_eq!(
            data_rows(&locked).len(),
            12,
            "six files of two rows: no data bulk was over the limit"
        );
    }
    let stream = String::from_utf8(buffer.lock().unwrap().clone()).unwrap();
    let done = stream
        .lines()
        .find(|line| line.starts_with("xerj-done "))
        .unwrap_or_else(|| panic!("{stream}"));
    assert!(done.starts_with("xerj-done ok=true exit=0 "), "{done}");
    assert!(
        done.contains(" bulk_splits="),
        "the terminal line must say the server refused a request for its size: {done}"
    );
}

/// Locks the three fixtures this module's HTTP tests share.
fn http_test_guards() -> (
    std::sync::MutexGuard<'static, ()>,
    std::sync::MutexGuard<'static, ()>,
    std::sync::MutexGuard<'static, ()>,
) {
    (
        FAILPOINT_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()),
        state::FILE_DONE_IO_FAILPOINT_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()),
        crate::progress::SINK_TEST_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()),
    )
}

/// #1977: one repository per directory, the shape of the ~210-index report.
/// Every dataset the run publishes has a catalog row before the run exits 0.
///
/// 201 is one past the read-back chunk of 200, so the gate's second ids
/// query is part of the passing run and not only the failure path.
#[test]
fn many_datasets_in_one_run_each_get_a_catalog_row() {
    let _guards = http_test_guards();
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    const REPOS: usize = 201;
    for n in 0..REPOS {
        let repo = corpus.path().join(format!("repo-{n:02}"));
        fs::create_dir_all(repo.join(".git")).unwrap();
        fs::write(repo.join(".git").join("HEAD"), "ref: refs/heads/main\n").unwrap();
        fs::write(
            repo.join("notes.md"),
            format!("# repo {n}\n\nnotes for repository {n}.\n"),
        )
        .unwrap();
    }
    let endpoint = MockEndpoint::start(usize::MAX);
    let config = cfg(corpus.path(), state_dir.path(), &endpoint.url);
    assert!(
        !config.no_graph,
        "the empty-catalog report is the graph path"
    );
    let (code, _) = run_index_report(config).unwrap();
    assert_eq!(code, 0);
    let datasets = dataset_catalog_docs(&endpoint);
    assert_eq!(
        datasets.len(),
        REPOS,
        "each repository is its own dataset and must have a catalog row: {datasets:?}"
    );
    let runs = endpoint
        .state
        .lock()
        .unwrap()
        .catalog_docs
        .values()
        .filter(|doc| doc.get("doc_kind").and_then(Value::as_str) == Some("run"))
        .count();
    assert_eq!(runs, 1, "the run document is part of the catalog gate");
}

/// #1977: the server answers the catalog bulk as a clean success and writes
/// nothing. That is the data path's swallowed-bulk shape (#195). On the graph
/// path it used to exit 0 with `autoindex-catalog` still empty, so `xerj_map`
/// reported no datasets. The run must fail, and the same command must recover
/// once the server accepts the write — the journal is not finished until the
/// rows are visible.
#[test]
fn a_catalog_bulk_answered_success_but_not_stored_does_not_exit_zero() {
    let _guards = http_test_guards();
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    fs::write(
        corpus.path().join("rows.csv"),
        "id,value\n1,first\n2,second\n",
    )
    .unwrap();
    let endpoint = MockEndpoint::start(usize::MAX);
    endpoint.state.lock().unwrap().swallow_catalog_bulks = true;
    let config = cfg(corpus.path(), state_dir.path(), &endpoint.url);
    let error = run_index_report(config.clone()).unwrap_err();
    let message = format!("{error:#}");
    assert!(
        message.contains("not visible"),
        "the failure must say the catalog rows are missing: {message}"
    );
    assert!(
        message.contains("rerun the same command"),
        "the failure must name the recovery: {message}"
    );
    {
        let locked = endpoint.state.lock().unwrap();
        assert!(
            locked.catalog_docs.is_empty(),
            "the swallowed bulk must not have stored a catalog row"
        );
        assert_eq!(
            data_rows(&locked).len(),
            2,
            "the data indices are searchable; only the catalog write was lost"
        );
    }
    assert_eq!(
        event_count(state_dir.path(), "finish"),
        0,
        "a catalog the map cannot see must not finish the resume journal"
    );
    endpoint.state.lock().unwrap().swallow_catalog_bulks = false;
    let (code, _) = run_index_report(config).unwrap();
    assert_eq!(code, 0, "the same command rewrites the catalog");
    assert_eq!(
        dataset_catalog_docs(&endpoint).len(),
        1,
        "the recovered run publishes the dataset row"
    );
}

