    let replacement_bytes = fs::metadata(&path).unwrap().len();
    assert_ne!(replacement_bytes, initial_bytes);
    assert_eq!(run_index(config.clone()).unwrap(), 0);

    // Reopen the durable journal independently of the product invocation.
