    /// The probe runs before the walk: a flooded node refuses with the
    /// override text and never opens the folder, and a healthy node is not
    /// refused (the walk then reports that the root is a file).
    #[test]
    fn autoindex_refuses_before_walk_only_when_the_node_reports_flood_stage() {
        let flooded = Node::start(true);
        let healthy = Node::start(false);
        let root_dir = tempfile::tempdir().unwrap();
        let root = root_dir.path().join("not-a-folder");
        std::fs::write(&root, "bytes the walk must not have to read\n").unwrap();

        let flooded_state = tempfile::tempdir().unwrap();
        let error = crate::run_index_report(index_cfg(&root, flooded_state.path(), &flooded.url))
            .expect_err("a flooded data volume must fail the run");
        let message = format!("{error:#}");
        assert!(
            message.contains("limits.disk_flood_stage_percent"),
            "{message}"
        );
        assert!(message.contains("free 2.0gb"), "{message}");
        assert!(message.contains("threshold 95%"), "{message}");
        assert!(
            !message.contains("is not a directory"),
            "the walk must not have started: {message}"
        );
        assert!(
            !flooded_state.path().join(".autoindex.lock").exists(),
            "refusing before the walk must not open the state directory"
        );
        assert_eq!(
            flooded.requests(),
            vec![
                ("GET".to_string(), "/".to_string()),
                (
                    "GET".to_string(),
                    "/_cat/allocation?format=json".to_string(),
                ),
            ]
        );

        let healthy_state = tempfile::tempdir().unwrap();
        let error = crate::run_index_report(index_cfg(&root, healthy_state.path(), &healthy.url))
            .expect_err("a file root still cannot be walked");
        let message = format!("{error:#}");
        assert!(
            message.contains("is not a directory"),
            "a healthy volume must reach the walk: {message}"
        );
        assert!(
            !message.contains("limits.disk_flood_stage_percent"),
            "{message}"
        );

        // A dry run writes nothing: a flooded node does not refuse it.
        let dry_state = tempfile::tempdir().unwrap();
        let mut dry = index_cfg(&root, dry_state.path(), &flooded.url);
        dry.dry_run = true;
        if let Err(error) = crate::run_index_report(dry) {
            let message = format!("{error:#}");
            assert!(
                !message.contains("limits.disk_flood_stage_percent"),
                "a dry run must not be refused for disk: {message}"
            );
        }
    }

    fn index_cfg(
        root: &std::path::Path,
        state: &std::path::Path,
        url: &str,
    ) -> crate::cli::IndexCfg {
        let args = vec![
            root.to_string_lossy().to_string(),
            "--url".into(),
            url.into(),
            "--state-dir".into(),
            state.to_string_lossy().to_string(),
            "--prefix".into(),
            "flood2077".into(),
            "--no-graph".into(),
            "--quiet".into(),
        ];
        match crate::cli::parse(args).expect("argv parses") {
            crate::cli::Cmd::Index(cfg) => *cfg,
            other => panic!("expected index, got {other:?}"),
        }
    }

    struct Node {
        url: String,
        requests: std::sync::Arc<std::sync::Mutex<Vec<(String, String)>>>,
        stop: std::sync::Arc<std::sync::atomic::AtomicBool>,
        join: Option<std::thread::JoinHandle<()>>,
    }

    impl Node {
        fn start(flooded: bool) -> Self {
            use std::io::{BufRead, BufReader, Read, Write};
            use std::net::TcpListener;
            use std::sync::atomic::{AtomicBool, Ordering};
            use std::sync::{Arc, Mutex};
            use std::time::Duration;

            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            listener.set_nonblocking(true).unwrap();
            let url = format!("http://{}", listener.local_addr().unwrap());
            let requests = Arc::new(Mutex::new(Vec::new()));
            let stop = Arc::new(AtomicBool::new(false));
            let requests_bg = Arc::clone(&requests);
            let stop_bg = Arc::clone(&stop);
            let join = std::thread::spawn(move || {
                while !stop_bg.load(Ordering::Relaxed) {
                    match listener.accept() {
                        Ok((mut stream, _)) => {
                            stream.set_nonblocking(false).unwrap();
                            stream
                                .set_read_timeout(Some(Duration::from_secs(5)))
                                .unwrap();
                            let mut reader = BufReader::new(stream.try_clone().unwrap());
                            let mut request_line = String::new();
                            if reader.read_line(&mut request_line).unwrap_or(0) == 0 {
                                continue;
                            }
                            let mut content_length = 0usize;
                            loop {
                                let mut line = String::new();
                                if reader.read_line(&mut line).unwrap_or(0) == 0 {
                                    break;
                                }
                                if line == "\r\n" || line.is_empty() {
                                    break;
                                }
                                if let Some(value) =
                                    line.to_ascii_lowercase().strip_prefix("content-length:")
                                {
                                    content_length = value.trim().parse().unwrap_or(0);
                                }
                            }
                            if content_length > 0 {
                                let mut body = vec![0; content_length];
                                let _ = reader.read_exact(&mut body);
                            }
                            let mut parts = request_line.split_whitespace();
                            let method = parts.next().unwrap_or("").to_string();
                            let path = parts.next().unwrap_or("").to_string();
                            requests_bg
                                .lock()
                                .unwrap()
                                .push((method.clone(), path.clone()));
                            let (status, body) = if method == "GET" && path == "/" {
                                (200, r#"{"ok":true}"#)
                            } else if method == "GET" && path.starts_with("/_cat/allocation") {
                                if flooded {
                                    (
                                        200,
                                        r#"[{"disk.percent":"98","disk.avail":"2147483648b","disk.flood_stage":"95","disk.threshold_enabled":"true","disk.flood_blocked":"false"}]"#,
                                    )
                                } else {
                                    (
                                        200,
                                        r#"[{"disk.percent":"10","disk.avail":"1073741824b","disk.flood_stage":"95","disk.threshold_enabled":"true","disk.flood_blocked":"false"}]"#,
                                    )
                                }
                            } else {
                                (404, r#"{"error":"absent"}"#)
                            };
                            let reason = if status == 200 { "OK" } else { "Not Found" };
                            let _ = write!(
                                stream,
                                "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                                body.len()
                            );
                        }
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            std::thread::sleep(Duration::from_millis(5));
                        }
                        Err(error) => panic!("accept failed: {error}"),
                    }
                }
            });
            Self {
                url,
                requests,
                stop,
                join: Some(join),
            }
        }

        fn requests(&self) -> Vec<(String, String)> {
            self.requests.lock().unwrap().clone()
        }
    }

    impl Drop for Node {
        fn drop(&mut self) {
            self.stop.store(true, std::sync::atomic::Ordering::Relaxed);
            if let Some(join) = self.join.take() {
                let _ = join.join();
            }
        }
    }
}

//! `xerj gain` — what XERJ actually did for you, from the audit log.
//!
//! Every number here is counted from the node's hash-chained audit log —
//! real requests that really happened. Deliberately absent: "tokens saved",
//! "time saved", or any other counterfactual. Estimated savings dashboards
//! read well until someone A/B-tests the estimate; counted requests do not
//! have that failure mode.

use crate::esclient::Es;
use serde_json::{json, Value};

const USAGE: &str = "\
xerj gain — what this node has done for you, counted (not estimated)

USAGE:
    xerj gain [OPTIONS]

Reads the node's hash-chained audit log and reports real usage: searches
served, hit rate, latency, the busiest indices, and a recent-search strip.

OPTIONS:
    --url <U>       node endpoint (default $XERJ_URL or http://localhost:9200)
    --api-key <K>   Authorization (or $XERJ_API_KEY; --insecure nodes need none)
    --json          machine-readable stats instead of the dashboard
    -h, --help      this help
";

/// One parsed search event from an audit entry.
#[derive(Debug, Clone)]
pub(crate) struct SearchEvent {
    pub index: String,
    pub took_ms: u64,
    pub hits: u64,
}

/// The search events a human caused, plus the machine traffic the same
/// audit window holds (#1105). `xerj gain` is "what did XERJ do FOR YOU" —
/// autoindex's own verification round-trips are not that, and folding them
/// in reported a 3% hit rate immediately after a flawless onboarding where
/// every real search found something.
#[derive(Debug, Default)]
pub(crate) struct SearchWindow {
    pub user: Vec<SearchEvent>,
    /// `size:0` searches — counting probes that asked for no hits.
    pub counting_probes: u64,
    /// Searches against `autoindex-catalog`, the index autoindex itself
    /// maintains (incremental reconcile sweeps it with full-page searches).
    pub catalog_sweeps: u64,
}

impl SearchWindow {
    /// Machine entries excluded from `user`, for the honesty line.
    fn excluded(&self) -> u64 {
        self.counting_probes + self.catalog_sweeps
    }
}

/// Parse the audit `note` written by the search handler:
/// `took=12ms hits=3 size=10`. Tolerant: missing pieces become 0 (or
/// `None` for `size`, which entries written before that field existed —
/// or by any other client — simply do not carry).
pub(crate) fn parse_note(note: &str) -> (u64, u64, Option<u64>) {
    let mut took = 0;
    let mut hits = 0;
    let mut size = None;
    for tok in note.split_whitespace() {
        if let Some(v) = tok.strip_prefix("took=") {
            took = v.trim_end_matches("ms").parse().unwrap_or(0);
        } else if let Some(v) = tok.strip_prefix("hits=") {
            hits = v.parse().unwrap_or(0);
        } else if let Some(v) = tok.strip_prefix("size=") {
            size = v.parse().ok();
        }
    }
    (took, hits, size)
}

/// Pull search events out of the audit snapshot (`{entries: [...]}`),
/// separating the user's searches from autoindex's machine traffic.
///
/// Two sources of truth, in order (#1109): an entry carrying the server-set
/// `actor` field is classified by it — the server derived the class from the
/// request itself at append time, which a client cannot influence; entries
/// written by a binary older than #1109 carry no `actor`, and for those the
/// note/resource heuristics below remain the (only) derivation. The two agree
/// on everything the heuristics could see; the field's value is that it is
/// authoritative rather than inferred.
pub(crate) fn search_events(audit: &Value) -> SearchWindow {
    let mut out = SearchWindow::default();
    let Some(entries) = audit.get("entries").and_then(Value::as_array) else {
        return out;
    };
    for e in entries {
        if e.get("op").and_then(Value::as_str) != Some("search") {
            continue;
        }
        let resource = e
            .get("resource")
            .and_then(Value::as_str)
            .unwrap_or("?")
            .to_string();
        let note = e.get("note").and_then(Value::as_str).unwrap_or("");
        let (took_ms, hits, size) = parse_note(note);
        match e.get("actor").and_then(Value::as_str) {
            // Written by a post-#1109 server: trust the server-side class.
            // Within "machine", keep the probe/sweep split for the honesty
            // line: the two machine classes are exactly size:0 probes and
            // catalog sweeps, so the size alone disambiguates them.
            Some("machine") => {
                if size == Some(0) {
                    out.counting_probes += 1;
                } else {
                    out.catalog_sweeps += 1;
                }
                continue;
            }
            Some(_) => {}
            // No actor field: a log written before #1109. The note/resource
            // heuristics that shipped with #1105 stay as the legacy
            // derivation — an old log read by a new client must still
            // separate machine traffic, or every upgraded install would
            // report a hit-rate dip that is really a version skew.
            None => {
                if size == Some(0) {
                    out.counting_probes += 1;
                    continue;
                }
                if resource == crate::catalog::CATALOG_INDEX {
                    out.catalog_sweeps += 1;
                    continue;
                }
            }
        }
        out.user.push(SearchEvent {
            index: resource,
            took_ms,
            hits,
        });
    }
    out
}

/// Computed stats over the events, ready to render or serialize.
pub(crate) fn stats(events: &[SearchEvent]) -> Value {
    let total = events.len() as u64;
    let with_hits = events.iter().filter(|e| e.hits > 0).count() as u64;
    let zero = total - with_hits;
    let mut tooks: Vec<u64> = events.iter().map(|e| e.took_ms).collect();
    tooks.sort_unstable();
    let pct = |p: f64| -> u64 {
        if tooks.is_empty() {
            0
        } else {
            tooks[((tooks.len() - 1) as f64 * p) as usize]
        }
    };
    // busiest indices
    let mut by_index: std::collections::BTreeMap<&str, (u64, u64)> = Default::default();
    for e in events {
        let slot = by_index.entry(e.index.as_str()).or_default();
        slot.0 += 1;
        if e.hits > 0 {
            slot.1 += 1;
        }
    }
    let mut top: Vec<(&str, u64, u64)> = by_index.iter().map(|(k, v)| (*k, v.0, v.1)).collect();
    top.sort_by_key(|x| std::cmp::Reverse(x.1));
    top.truncate(5);
    serde_json::json!({
        "searches": total,
        "with_hits": with_hits,
        "zero_hit": zero,
        "hit_rate": if total > 0 { (with_hits as f64 / total as f64 * 100.0).round() } else { 0.0 },
        "took_ms": { "p50": pct(0.50), "p95": pct(0.95) },
        "top_indices": top.iter().map(|(name, n, h)| serde_json::json!({
            "index": name, "searches": n, "with_hits": h
        })).collect::<Vec<_>>(),
    })
}

/// The recent-search strip: one glyph per search, newest last.
/// `█` a search that found something, `·` a zero-hit search.
pub(crate) fn strip(events: &[SearchEvent], width: usize) -> String {
    events
        .iter()
        .rev()
        .take(width)
        .rev()
        .map(|e| if e.hits > 0 { '█' } else { '·' })
        .collect()
}

/// Entry point for the `gain` subcommand. Returns a process exit code.
pub fn run_gain_cli() -> i32 {
    let mut url = std::env::var("XERJ_URL")
        .ok()
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "http://localhost:9200".to_string());
    let mut api_key = std::env::var("XERJ_API_KEY").ok().filter(|s| !s.is_empty());
    let mut as_json = false;
    let mut it = xerj_common::argv::args_after_subcommand().into_iter();
    while let Some(a) = it.next() {
        match a.as_str() {
            "-h" | "--help" => {
                print!("{USAGE}");
                return 0;
            }
            "--url" => url = it.next().unwrap_or(url),
            "--api-key" => api_key = it.next(),
            "--json" => as_json = true,
            "--disable-feedback" => {}
            other => {
                eprintln!("xerj gain: unexpected argument '{other}'\n\n{USAGE}");
                return 2;
            }
        }
    }
    let es = match Es::new(&url, api_key) {
        Ok(es) => es,
        Err(e) => {
            eprintln!("xerj gain: could not build client for {url}: {e}");
            return 2;
        }
    };
    // The audit API lives on the node's NATIVE listener, whose default port
    // is 8080 (the startup banner prints it as 'Native REST'). Try the given
    // URL first — it costs one request and keeps working if the routes ever
    // merge — then the default native port on the same host, then the
    // ES-port+1 convention for nodes that co-locate them that way (#1104:
    // probing only port+1 missed the default entirely and `gain` was
    // unusable without hand-guessing the port).
    let audit = match es.get_json("/_audit/_search") {
        Ok(v) => v,
        Err(_) => {
            let key = std::env::var("XERJ_API_KEY").ok().filter(|s| !s.is_empty());
            let mut retry = None;
            let mut tried = vec![url.clone()];
            for candidate in native_candidates(&url) {
                tried.push(candidate.clone());
                if let Ok(nes) = Es::new(&candidate, key.clone()) {
                    if let Ok(v) = nes.get_json("/_audit/_search") {
                        retry = Some(v);
                        break;
                    }
                }
            }
            match retry {
                Some(v) => v,
                None => {
                    eprintln!(
                        "xerj gain: could not read the audit log at {}.\n\
                         (the audit API is served by the node's native listener — the port the\n\
                         startup banner prints as 'native REST'; a default node uses 8080.\n\
                         A node started with --insecure serves it without a key; otherwise\n\
                         the key needs read_audit.)",
                        tried
                            .iter()
                            .map(|u| format!("{u}/_audit/_search"))
                            .collect::<Vec<_>>()
                            .join(" or ")
                    );
                    return 1;
                }
            }
        }
    };
    let window = search_events(&audit);
    let excluded = window.excluded();
    let (probes, sweeps) = (window.counting_probes, window.catalog_sweeps);
    let events = window.user;
    let s = stats(&events);
    if as_json {
        let mut s = s;
        s["excluded_machine_searches"] = json!({
            "counting_probes": probes,
            "catalog_sweeps": sweeps,
        });
        println!("{}", serde_json::to_string_pretty(&s).unwrap_or_default());
        return 0;
    }
    if events.is_empty() && excluded == 0 {
        println!("no searches in the audit window yet.");
        println!("(index something: xerj autoindex <folder> — then: xerj search \"<words>\")");
        return 0;
    }
    println!("xerj gain — counted from the node's audit log, no estimates\n");
    if events.is_empty() {
        println!("  no user searches in the audit window (only machine traffic).");
        println!("  try one: xerj search \"<words>\"");
    } else {
        println!(
            "  searches served   {}   ({}% found something; {} zero-hit)",
            s["searches"], s["hit_rate"], s["zero_hit"]
        );
        println!(
            "  latency           p50 {}ms · p95 {}ms",
            s["took_ms"]["p50"], s["took_ms"]["p95"]
        );
        println!("  recent            {}", strip(&events, 50));
        println!("\n  busiest indices");
        for t in s["top_indices"].as_array().into_iter().flatten() {
            println!(
                "    {:<40} {:>5} searches  ({} with hits)",
                t["index"].as_str().unwrap_or("?"),
                t["searches"],
                t["with_hits"]
            );
        }
    }
    if excluded > 0 {
        println!(
            "\n  (not counted as yours: {} machine search(es) this window — {} counting\n\
             \x20  probe(s) autoindex used to verify its own writes, {} catalog\n\
             \x20  maintenance sweep(s). Nothing was thrown away; they are in the\n\
             \x20  audit log with everything else.)",
            excluded, probes, sweeps
        );
    }
    println!(
        "\n(the audit log keeps the last N entries; this reports that window, \
         nothing more. █ = search with hits, · = zero-hit)"
    );
    0
}

/// `http://host:9200` -> `http://host:9201` (the native-listener convention).
/// None when the URL has no explicit port to bump.
pub(crate) fn bump_port(url: &str) -> Option<String> {
    let idx = url.rfind(':')?;
    // Guard against the scheme colon (`http://host` with no port).
    let tail = &url[idx + 1..];
    let port: u16 = tail.parse().ok()?;
    Some(format!("{}:{}", &url[..idx], port.checked_add(1)?))
}

/// Candidate native-listener base URLs for the audit API, in probe order:
/// the default native port (8080) on the same host first, then the
/// ES-port+1 convention. Deduplicated, so a node whose ES listener already
/// IS on 8080 is probed once.
pub(crate) fn native_candidates(url: &str) -> Vec<String> {
    let after_scheme = url.split_once("://").map(|(_, rest)| rest).unwrap_or(url);
    let mut out = Vec::new();
    if let Some(host) = after_scheme.split([':', '/']).next() {
        if !host.is_empty() {
            out.push(format!("http://{host}:8080"));
        }
    }
    if let Some(bumped) = bump_port(url) {
        if !out.contains(&bumped) {
            out.push(bumped);
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn bump_port_handles_shapes() {
        assert_eq!(
            bump_port("http://localhost:9200").as_deref(),
            Some("http://localhost:9201")
        );
        assert_eq!(
            bump_port("http://10.0.0.5:9280").as_deref(),
            Some("http://10.0.0.5:9281")
        );
        assert_eq!(bump_port("http://localhost"), None);
    }

    #[test]
    fn native_candidates_default_port_first_then_port_plus_one() {
        // #1104: the default node's native REST is 8080 — it must be probed,
        // and probed before the ES-port+1 guess.
        assert_eq!(
            native_candidates("http://localhost:9200"),
            vec![
                "http://localhost:8080".to_string(),
                "http://localhost:9201".to_string()
            ]
        );
        // A node whose ES listener is itself on 8080 still gets both the
        // default native port and its +1 guess — only an exact duplicate
        // (ES port+1 == 8080) is deduplicated.
        assert_eq!(
            native_candidates("http://localhost:8080"),
            vec![
                "http://localhost:8080".to_string(),
                "http://localhost:8081".to_string()
            ]
        );
        assert_eq!(
            native_candidates("http://10.0.0.5:8079"),
            vec!["http://10.0.0.5:8080".to_string()]
        );
        assert_eq!(native_candidates("http://10.0.0.5:9280").len(), 2);
        // No port to bump still yields the default native candidate.
        assert_eq!(
            native_candidates("http://localhost"),
            vec!["http://localhost:8080".to_string()]
        );
    }

    fn audit(entries: Vec<Value>) -> Value {
        json!({ "next_seq": entries.len(), "entries": entries })
    }

    fn search_entry(index: &str, took: u64, hits: u64) -> Value {
        json!({ "op": "search", "subject": "anonymous", "resource": index,
                "outcome": "ok", "note": format!("took={took}ms hits={hits} size=10") })
    }

    #[test]
    fn parses_note_and_filters_non_search_ops() {
        let a = audit(vec![
            search_entry("ax-docs", 12, 3),
            json!({ "op": "index.create", "resource": "ax-docs", "outcome": "ok", "note": "status=200" }),
            search_entry("ref-sled-docs", 4, 0),
        ]);
        let ev = search_events(&a);
        assert_eq!(ev.user.len(), 2);
        assert_eq!((ev.user[0].took_ms, ev.user[0].hits), (12, 3));
        assert_eq!((ev.user[1].took_ms, ev.user[1].hits), (4, 0));
    }

    #[test]
    fn parse_note_tolerates_missing_size() {
        // Entries written before `size=` existed (or by another client) must
        // still count as user searches, never as counting probes.
        assert_eq!(parse_note("took=4ms hits=0"), (4, 0, None));
        assert_eq!(parse_note("took=4ms hits=7 size=0"), (4, 7, Some(0)));
        assert_eq!(parse_note("took=4ms hits=7 size=25"), (4, 7, Some(25)));
    }

    #[test]
    fn counting_probes_and_catalog_sweeps_are_not_user_searches() {
        // #1105, verbatim from the rc.80 harness run: 179 size-0 verification
        // probes on the dataset index, catalog reconcile sweeps, three real
        // searches — gain must report the three. These entries carry no
        // `actor` field (pre-#1109 shape), so they also pin the legacy
        // note/resource derivation an upgraded client reads an old log with.
        let probe = |hits: u64| {
            json!({ "op": "search", "subject": "superuser", "resource": "ax-docs",
                    "outcome": "ok", "note": format!("took=0ms hits={hits} size=0") })
        };
        let mut entries: Vec<Value> = (0..179).map(|_| probe(0)).collect();
        for _ in 0..96 {
            entries.push(json!({ "op": "search", "subject": "superuser",
                    "resource": "autoindex-catalog", "outcome": "ok",
                    "note": "took=0ms hits=0 size=1000" }));
        }
        entries.push(search_entry("ax-*", 145, 5));
        entries.push(search_entry("ax-*", 82, 2));
        entries.push(search_entry("ax-*", 1028, 10));
        let w = search_events(&audit(entries));
        assert_eq!(w.user.len(), 3);
        assert_eq!(w.counting_probes, 179);
        assert_eq!(w.catalog_sweeps, 96);
        let s = stats(&w.user);
        assert_eq!(s["searches"], 3);
        assert_eq!(s["with_hits"], 3);
        assert_eq!(s["hit_rate"], 100.0);
    }

    /// #1109: entries written by a post-#1109 server carry the server-set
    /// `actor` field, and THAT classifies — not the note heuristics. This is
    /// the anti-spoof half of the feature living where its consumer reads it:
    /// the classification was derived from the request itself at append time,
    /// so a note that says `size=10` on machine traffic (or vice versa) is
    /// data, not a verdict.
    #[test]
    fn actor_field_is_authoritative_when_present() {
        let a = audit(vec![
            // Machine by the field, and the note would agree — normal case.
            json!({ "op": "search", "subject": "superuser", "resource": "ax-docs",
                    "outcome": "ok", "actor": "machine",
                    "note": "took=0ms hits=0 size=0" }),
            // Machine by the field with a note the legacy heuristic could NOT
            // parse a class from (no size, data index): still excluded, split
            // into catalog_sweeps as the non-probe machine class.
            json!({ "op": "search", "subject": "superuser", "resource": "ax-docs",
                    "outcome": "ok", "actor": "machine",
                    "note": "took=1ms hits=5" }),
            // User by the field even where the heuristic would have said
            // machine: a post-#1109 server never writes this combination, and
            // pinning that the field wins is what makes one classifier — the
            // server's — authoritative instead of two half-trusted ones.
            json!({ "op": "search", "subject": "superuser", "resource": "ax-docs",
                    "outcome": "ok", "actor": "user",
                    "note": "took=2ms hits=1 size=0" }),
        ]);
        let w = search_events(&a);
        assert_eq!(w.user.len(), 1);
        assert_eq!(w.user[0].hits, 1);
        assert_eq!(w.counting_probes, 1);
        assert_eq!(w.catalog_sweeps, 1);
    }

    /// A mixed-version audit window — an upgraded install whose ring still
    /// holds pre-#1109 entries — must classify both halves correctly in one
    /// pass: the fieldless tail by the legacy derivation, the new head by the
    /// field.
    #[test]
    fn mixed_version_log_classifies_both_halves() {
        let a = audit(vec![
            // Old-shape entry (no actor): heuristic must still exclude it.
            json!({ "op": "search", "subject": "superuser", "resource": "ax-docs",
                    "outcome": "ok", "note": "took=0ms hits=0 size=0" }),
            // New-shape machine entry.
            json!({ "op": "search", "subject": "superuser", "resource": "autoindex-catalog",
                    "outcome": "ok", "actor": "machine",
                    "note": "took=0ms hits=40 size=100" }),
            // New-shape user entry.
            json!({ "op": "search", "subject": "superuser", "resource": "ax-docs",
                    "outcome": "ok", "actor": "user",
                    "note": "took=8ms hits=4 size=10" }),
        ]);
        let w = search_events(&a);
        assert_eq!(w.user.len(), 1);
        assert_eq!(w.user[0].took_ms, 8);
        assert_eq!(w.counting_probes, 1, "the legacy entry");
        assert_eq!(w.catalog_sweeps, 1, "the fielded entry");
    }

    #[test]
    fn stats_count_hit_rate_and_percentiles() {
        let ev: Vec<SearchEvent> = (0..10)
            .map(|i| SearchEvent {
                index: "ax-docs".into(),
                took_ms: (i + 1) * 10,
                hits: if i < 7 { 1 } else { 0 },
            })
            .collect();
        let s = stats(&ev);
        assert_eq!(s["searches"], 10);
        assert_eq!(s["with_hits"], 7);
        assert_eq!(s["hit_rate"], 70.0);
        assert_eq!(s["took_ms"]["p50"], 50);
        assert_eq!(s["took_ms"]["p95"], 90);
    }

    #[test]
    fn strip_marks_hits_and_misses_newest_last() {
        let ev = vec![
            SearchEvent {
                index: "a".into(),
                took_ms: 1,
                hits: 1,
            },
            SearchEvent {
                index: "a".into(),
                took_ms: 1,
                hits: 0,
            },
            SearchEvent {
                index: "a".into(),
                took_ms: 1,
                hits: 2,
            },
        ];
        assert_eq!(strip(&ev, 50), "█·█");
        assert_eq!(strip(&ev, 2), "·█");
    }

    #[test]
    fn empty_audit_yields_zeroed_stats() {
        let s = stats(&[]);
        assert_eq!(s["searches"], 0);
        assert_eq!(s["hit_rate"], 0.0);
    }
}

//! The 10-minute gate: hand the decision back instead of taking the machine.
//!
//! `landing/llms.txt` already tells an agent driving XERJ on someone's laptop
//! to *estimate, tell them, ask if it is big, report progress*. That was
//! advice, and advice is ignorable. This module is the binary enforcing it:
//! when phase A's measured estimate ([`crate::estimate`]) exceeds
//! `--max-minutes` (default 10) and nobody has approved the run, autoindex
//! stops before it touches the index and emits a decision request instead.
//!
//! Three properties the design turns on:
//!
//! * **A distinct exit code.** [`EXIT_NEEDS_DECISION`] is 4, never 1. Exit 1
//!   is autoindex's catch-all for every real failure, so an agent that could
//!   only see 1 would have to parse prose to tell "your endpoint is down" from
//!   "I need you to choose". Anything that has to be distinguished
//!   programmatically gets its own code.
//! * **Never wait on stdin for a question the user cannot see.** The prompt is
//!   offered only when someone can answer it (stdin is a terminal) *and* the
//!   question actually reached a screen (stderr is a terminal, and the progress
//!   surface is not silenced). A run started by an agent, a CI job, a pipe, or
//!   with `--quiet` emits the payload and exits; waiting for an answer that
//!   cannot arrive is how an agent deadlocks, and an invisible prompt is
//!   indistinguishable from a hang — the worst possible failure for a feature
//!   whose whole purpose is to say "this is going to take a while".
//!   [`prompt_blocked_by`] owns that decision and [`answer_from_terminal`]
//!   never opens stdin when it says no.
//! * **Options carry their measured cost, or say they were not measured.**
//!   `narrower` names the heaviest directories in this corpus with real byte
//!   counts and re-costs the run without them using the same measured rates.
//!   `fast` does NOT claim a speed-up factor: `--no-semantic --no-graph`
//!   removes server-side embedding and client-side edge detection, and this
//!   run measured neither. It states the scope it changes and admits the
//!   factor is unmeasured, which is the only honest thing to print.

use crate::estimate::{human_bytes, human_secs, Estimate, MeasuredRate, PlannedFile};
use crate::order;
use serde::Serialize;
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::io::IsTerminal;

/// "I need a decision before I spend your machine." Deliberately not 1 (every
/// error), not 2 (usage), not 3 (completed-with-junk).
pub const EXIT_NEEDS_DECISION: i32 = 4;

/// Default gate threshold in minutes, from the owner's own framing: "if
/// estimated more than 10min work needs to ask AI back what to do".
pub const DEFAULT_MAX_MINUTES: u64 = 10;

/// An answer to a decision request, carried by `--approve`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Approval {
    /// Index everything as planned.
    Proceed,
    /// Index everything, but with `--no-semantic --no-graph`.
    Fast,
    /// Index nothing and exit cleanly.
    Cancel,
}

impl Approval {
    pub fn as_str(self) -> &'static str {
        match self {
            Approval::Proceed => "proceed",
            Approval::Fast => "fast",
            Approval::Cancel => "cancel",
        }
    }

    /// Parse an `--approve` value.
    ///
    /// `narrower` is refused on purpose. It is a real option in the decision
    /// request, but it is not something this flag can carry out: making a run
    /// narrower means pointing autoindex at a different folder, and accepting
    /// `--approve narrower` would mean accepting an instruction and then
    /// indexing the whole tree anyway — the accepted-and-silently-ignored
    /// class this repository keeps re-finding (#204).
    pub fn parse(raw: &str) -> Result<Self, String> {
        match raw {
            "proceed" => Ok(Approval::Proceed),
            "fast" => Ok(Approval::Fast),
            "cancel" => Ok(Approval::Cancel),
            "narrower" => Err(
                "--approve narrower cannot be honoured here: 'narrower' means running autoindex \
                 against a smaller folder, which this run cannot decide for you. Re-run it as \
                 `xerj autoindex <subdirectory>` (the decision request lists the heaviest \
                 directories and what each one costs)"
                    .to_string(),
            ),
            other => Err(format!(
                "--approve {other} is not one of: proceed, fast, cancel (narrower means re-running \
                 against a subdirectory — see the decision request)"
            )),
        }
    }
}

/// Is this run long enough to be worth a question?
///
/// Three ways to answer no, and each matters:
/// * `max_minutes == 0` — the documented opt-out. A caller that says "never
///   ask" is obeyed exactly.
/// * no estimate — phase A measured nothing it could price honestly, and a
///   gate cannot fire on a number that does not exist. Stopping a run on an
///   invented threshold breach would be the worst possible version of this
///   feature.
/// * under the threshold.
///
/// The comparison is against the **upper** bound: the estimate deliberately
/// leaves out server, network and embedding time, so its lower end is a floor
/// that would let long runs through unasked.
pub fn over_threshold(estimate: &Estimate, max_minutes: u64) -> bool {
    if max_minutes == 0 {
        return false;
    }
    estimate
        .gate_seconds()
        .is_some_and(|seconds| seconds > (max_minutes * 60) as f64)
}

/// Weight of one directory in the corpus — measured, never sampled.
#[derive(Debug, Clone, Serialize)]
pub struct DirectoryWeight {
    /// Root-relative directory, or `"."` for files directly under the root.
    pub path: String,
    pub files: u64,
    pub bytes: u64,
    /// Share of planned bytes, 0.0–1.0.
    pub share: f64,
    /// Why this path looks like it can be dropped, when it does.
    pub looks_generated: Option<String>,
}

/// Aggregate planned bytes by first path segment, heaviest first.
pub fn heaviest_directories(files: &[(String, u64)], top_n: usize) -> Vec<DirectoryWeight> {
    let total: u64 = files.iter().map(|(_, bytes)| bytes).sum();
    let mut by_dir: BTreeMap<&str, (u64, u64)> = BTreeMap::new();
    for (rel, bytes) in files {
        let segment = rel.split_once('/').map(|(head, _)| head).unwrap_or(".");
        let entry = by_dir.entry(segment).or_default();
        entry.0 += 1;
        entry.1 += bytes;
    }
    let mut weights: Vec<DirectoryWeight> = by_dir
        .into_iter()
        .map(|(path, (files, bytes))| DirectoryWeight {
            path: path.to_string(),
            files,
            bytes,
            share: if total > 0 {
                bytes as f64 / total as f64
            } else {
                0.0
            },
            looks_generated: order::vendored_reason(&format!("{path}/x"))
                .map(|hit| format!("matches the vendored/generated rule '{hit}'")),
        })
        .collect();
    weights.sort_by(|a, b| b.bytes.cmp(&a.bytes).then_with(|| a.path.cmp(&b.path)));
    weights.truncate(top_n);
    weights
}

/// Everything the caller has to know to answer, assembled once.
pub struct DecisionRequest<'a> {
    pub root: String,
    pub estimate: &'a Estimate,
    pub max_minutes: u64,
    pub bands: Vec<order::BandSummary>,
    pub heaviest: Vec<DirectoryWeight>,
    /// Estimate with every heaviest-directory entry that looks generated
    /// removed — costed with the same measured rates.
    pub without_generated: Option<(Vec<String>, String)>,
    /// Datasets phase A inferred a `semantic_text` field for. `fast` removes
    /// the server-side embedding work for exactly these.
    pub semantic_datasets: Vec<String>,
    pub total_datasets: usize,
    /// Files relationship detection would run over under the current flags.
    pub graph_files: u64,
    /// Why this run did not stop to ask at a terminal, when it did not.
    /// Carried in the payload because stdout is the one channel `--quiet`
    /// leaves open: a user who silenced stderr still has to be able to find
    /// out that a question existed and why they were not asked it.
    pub prompt_blocked: Option<NoPrompt>,
}

impl DecisionRequest<'_> {
    /// The machine-readable payload. One JSON document on stdout, so an agent
    /// never has to scrape prose.
    pub fn to_json(&self) -> Value {
        json!({
            "xerj": "autoindex-decision-request",
            "exit_code": EXIT_NEEDS_DECISION,
            "root": self.root,
            "reason": self.reason(),
            "estimate": self.estimate,
            "estimate_text": self.estimate.headline(),
            "max_minutes": self.max_minutes,
            "priority_order": self.bands,
            "heaviest_directories": self.heaviest,
            "options": self.options(),
            "prompt_offered": self.prompt_blocked.is_none(),
            "prompt_not_offered_because": self.prompt_blocked.map(NoPrompt::explain),
            "how_to_answer":
                "re-invoke the identical command with --approve <id> (--yes is an alias for \
                 --approve proceed). Without an answer nothing has been indexed and nothing has \
                 been changed on the server.",
        })
    }

    /// Why the run stopped, in one sentence, for both renderings.
    pub fn reason(&self) -> String {
        match self.estimate.gate_seconds() {
            Some(seconds) => format!(
                "the measured extraction floor alone is {}; its upper end {} already exceeds \
                 --max-minutes {}. The real run is longer than this — server, network and \
                 embedding time are not in the number",
                self.estimate.range_text(),
                human_secs(seconds),
                self.max_minutes
            ),
            None => "no estimate was possible".to_string(),
        }
    }

    fn options(&self) -> Value {
        let narrower = match &self.without_generated {
            Some((names, text)) => format!(
                "drop {} ({}) and the same measured rates put the run at {text}",
                names.join(", "),
                human_bytes(
                    self.heaviest
                        .iter()
                        .filter(|d| d.looks_generated.is_some())
                        .map(|d| d.bytes)
                        .sum::<u64>()
                ),
            ),
            None => "no single directory dominates this corpus".to_string(),
        };
        json!([
            {
                "id": "proceed",
                "invoke": "--approve proceed   (or --yes)",
                "effect": "index everything as planned",
                "cost": self.estimate.headline(),
            },
            {
                "id": "fast",
                "invoke": "--approve fast",
                "effect": "adds --no-semantic --no-graph: no semantic_text body fields, no \
                           relationship edges. You still get typed BM25 + keyword indices over \
                           the same files.",
                "cost": format!(
                    "speed-up NOT measured by this run. It removes server-side embedding for {} \
                     of {} inferred dataset(s) ({}) and relationship detection over {} file(s). \
                     XERJ's default embedder is lexical feature-hashing, so unless the node runs \
                     --embed-mode neural the embedding saving is smaller than the word 'semantic' \
                     suggests.",
                    self.semantic_datasets.len(),
                    self.total_datasets,
                    if self.semantic_datasets.is_empty() {
                        "none".to_string()
                    } else {
                        self.semantic_datasets.join(", ")
                    },
                    self.graph_files,
                ),
            },
            {
                "id": "narrower",
                "invoke": "re-run as `xerj autoindex <subdirectory>` — --approve cannot carry \
                           this out, autoindex has no --exclude flag",
                "effect": "index only the part that matters",
                "cost": narrower,
                "heaviest_directories": self.heaviest,
            },
            {
                "id": "cancel",
                "invoke": "--approve cancel",
                "effect": "index nothing, exit 0",
                "cost": "none — nothing has been written yet",
            },
        ])
    }

    /// The same information as prose, for a person reading a terminal.
    pub fn prose(&self) -> Vec<String> {
        let mut lines = vec![
            format!("autoindex: STOPPING BEFORE INDEXING — {}", self.reason()),
            format!("  root:     {}", self.root),
            format!(
                "  corpus:   {} files, {}",
                self.estimate.planned_files,
                human_bytes(self.estimate.planned_bytes)
            ),
            format!("  estimate: {}", self.estimate.headline()),
            format!("  basis:    {}", self.estimate.basis),
        ];
        for family in &self.estimate.families {
            lines.push(format!(
                "    {:<10} {:>6} files {:>10}  at {}/s measured over {} file(s)",
                family.family,
                family.planned_files,
                human_bytes(family.planned_bytes),
                human_bytes(family.bytes_per_sec as u64),
                family.measured_files,
            ));
        }
        for family in &self.estimate.unmeasured_families {
            lines.push(format!(
                "    {:<10} {:>6} files {:>10}  NOT in the estimate — {}",
                family.family,
                family.planned_files,
                human_bytes(family.planned_bytes),
                family.reason,
            ));
        }
        lines.push("  not included in the estimate:".to_string());
        for exclude in &self.estimate.excludes {
            lines.push(format!("    - {exclude}"));
        }
        if !self.heaviest.is_empty() {
            lines.push("  heaviest directories:".to_string());
            for dir in &self.heaviest {
                lines.push(format!(
                    "    {:<24} {:>6} files {:>10} ({:.0}%){}",
                    dir.path,
                    dir.files,
                    human_bytes(dir.bytes),
                    dir.share * 100.0,
                    match &dir.looks_generated {
                        Some(reason) => format!("  ← {reason}"),
                        None => String::new(),
                    }
                ));
            }
        }
        lines.push("  options:".to_string());
        let options = self.options();
        if let Some(options) = options.as_array() {
            for option in options {
                lines.push(format!(
                    "    {:<9} {}",
                    option["id"].as_str().unwrap_or_default(),
                    option["effect"].as_str().unwrap_or_default()
                ));
                lines.push(format!(
                    "              cost: {}",
                    option["cost"].as_str().unwrap_or_default()
                ));
            }
        }
        lines.push(
            "  answer by re-running the same command with --approve proceed|fast|cancel (--yes = \
             proceed). Nothing has been indexed."
                .to_string(),
        );
        // Say why nobody was asked, where that can still be read. A log that
        // shows the question but not the reason it went unasked is the same
        // guessing game one layer up.
        if let Some(blocked) = self.prompt_blocked {
            lines.push(format!("  {}", blocked.explain()));
        }
        lines
    }
}

/// Why no terminal prompt was offered. `None` from [`prompt_blocked_by`] means
/// one was.
///
/// This exists as a value rather than a bare `bool` because the reason is
/// printed: a run that stops without asking has to be able to say why it did
/// not ask, or the silence is just another thing for the user to guess at.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NoPrompt {
    /// stdin is a pipe, a file, or closed — an agent, a CI job, a script.
    /// Nobody is at the keyboard, so there is no answer to wait for.
    StdinNotTerminal,
    /// stderr is redirected. The question would land in a log nobody is
    /// watching while the process sat waiting for a reply to it.
    StderrNotTerminal,
    /// `--quiet` / `--progress none` silenced the surface the question is
    /// printed on. Someone *is* at the keyboard, but they were never shown
    /// anything to answer — this is the case that made the run look hung.
    QuestionSilenced,
}

impl NoPrompt {
    /// One sentence, for the decision payload and the prose.
    pub fn explain(self) -> &'static str {
        match self {
            NoPrompt::StdinNotTerminal => {
                "no terminal prompt: stdin is not a terminal, so no answer could be typed. Re-run \
                 with --approve proceed|fast|cancel"
            }
            NoPrompt::StderrNotTerminal => {
                "no terminal prompt: stderr is not a terminal, so the question would not have \
                 reached a screen. Re-run with --approve proceed|fast|cancel"
            }
            NoPrompt::QuestionSilenced => {
                "no terminal prompt: --quiet / --progress none silences the question, and this run \
                 will never wait on stdin for something it did not print. The decision request \
                 below is on stdout, which --quiet does not silence. Re-run with --approve \
                 proceed|fast|cancel, or without --quiet to be asked"
            }
        }
    }
}

/// Should this run stop to ask, and if not, why not?
///
/// Three conditions, and all three have to hold before autoindex touches
/// stdin:
///
/// * `stdin_tty` — someone can type an answer;
/// * `stderr_tty` — the question reaches a screen rather than a log file;
/// * `question_visible` — the progress surface actually printed it. This is
///   the one the first cut of the gate missed. `--quiet` / `--progress none`
///   routes [`crate::progress::Progress::note`] to nothing, so the prose and
///   the prompt vanished while the process still sat on `read_line`. Measured
///   before the fix: a pty run with `--progress none` printed **zero bytes**
///   and was still blocked at 220 s. An invisible prompt is a hang.
///
/// Pure, so the whole rule is testable without a terminal — the same shape as
/// [`crate::progress::resolve`].
pub fn prompt_blocked_by(
    stdin_tty: bool,
    stderr_tty: bool,
    question_visible: bool,
) -> Option<NoPrompt> {
    if !stdin_tty {
        return Some(NoPrompt::StdinNotTerminal);
    }
    if !stderr_tty {
        return Some(NoPrompt::StderrNotTerminal);
    }
    if !question_visible {
        return Some(NoPrompt::QuestionSilenced);
    }
    None
}

/// [`prompt_blocked_by`] against this process's real streams.
///
/// `question_visible` is the caller's progress surface
/// ([`crate::progress::Progress::enabled`]) — gate has no business inspecting
/// the surface itself, and passing the fact in keeps this testable.
pub fn detect_prompt_block(question_visible: bool) -> Option<NoPrompt> {
    prompt_blocked_by(
        std::io::stdin().is_terminal(),
        std::io::stderr().is_terminal(),
        question_visible,
    )
}

/// Ask, but only when [`prompt_blocked_by`] said it was safe to.
///
/// `open_stdin` is a closure and not a reader on purpose: when the prompt is
/// blocked it is **never called**, so there is no path on which this function
/// can end up holding — let alone reading — the process's stdin. That is the
/// invariant, and `a_question_that_cannot_be_seen_is_never_asked` asserts it by
/// handing in a reader that panics if anyone touches it.
pub fn answer_from_terminal<R: std::io::BufRead>(
    blocked: Option<NoPrompt>,
    open_stdin: impl FnOnce() -> R,
    echo: impl FnMut(&str),
) -> Option<Approval> {
    if blocked.is_some() {
        return None;
    }
    read_answer(&mut open_stdin(), echo)
}

/// Read one answer from a terminal. `None` means "no answer" — EOF, an
/// unreadable stdin, or three unrecognised replies — and the caller must treat
/// that as cancel rather than as consent.
pub fn read_answer(
    input: &mut impl std::io::BufRead,
    mut echo: impl FnMut(&str),
) -> Option<Approval> {
    for _ in 0..3 {
        echo("  answer [p]roceed / [f]ast / [c]ancel (narrower = re-run on a subdirectory): ");
        let mut line = String::new();
        match input.read_line(&mut line) {
            Ok(0) | Err(_) => return None,
            Ok(_) => {}
        }
        match line.trim().to_ascii_lowercase().as_str() {
            "p" | "proceed" | "y" | "yes" => return Some(Approval::Proceed),
            "f" | "fast" => return Some(Approval::Fast),
            "c" | "cancel" | "n" | "no" | "q" => return Some(Approval::Cancel),
            "" => echo("  no answer read; type p, f or c"),
            other => echo(&format!("  '{other}' is not one of p, f, c")),
        }
    }
    None
}

/// Cost the run again with the generated-looking heavy directories removed —
/// same measured rates, no new guess. `None` when nothing looks droppable.
pub fn without_generated_directories(
    estimate: &Estimate,
    rates: &BTreeMap<&'static str, MeasuredRate>,
    heaviest: &[DirectoryWeight],
    files: &[(String, String, u64)],
) -> Option<(Vec<String>, String)> {
    let dropped: Vec<String> = heaviest
        .iter()
        .filter(|dir| dir.looks_generated.is_some())
        .map(|dir| dir.path.clone())
        .collect();
    if dropped.is_empty() {
        return None;
    }
    let kept: Vec<PlannedFile> = files
        .iter()
        .filter(|(rel, _, _)| {
            let segment = rel.split_once('/').map(|(head, _)| head).unwrap_or(".");
            !dropped.iter().any(|d| d == segment)
        })
        .map(|(_, family, bytes)| PlannedFile {
            family: family.clone(),
            bytes: *bytes,
        })
        .collect();
    Some((
        dropped,
        estimate.recompute_subset(&kept, rates).range_text(),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rates() -> BTreeMap<&'static str, MeasuredRate> {
        BTreeMap::from([(
            "code",
            MeasuredRate {
                files: 4,
                bytes: 4_000,
                bytes_per_sec: 1_000.0,
            },
        )])
    }

    fn estimate(files: usize, bytes: u64) -> Estimate {
        let planned: Vec<PlannedFile> = (0..files)
            .map(|_| PlannedFile {
                family: "code".into(),
                bytes,
            })
            .collect();
        Estimate::compute(&planned, &rates(), 4)
    }

    /// The point of the whole module: "needs a decision" must be
    /// distinguishable from "something broke" without parsing English.
    #[test]
    fn the_decision_exit_code_is_not_any_existing_one() {
        for taken in [0, 1, 2, 3] {
            assert_ne!(EXIT_NEEDS_DECISION, taken);
        }
    }

    /// The threshold rule itself, including the two ways it must decline to
    /// fire. A gate that stopped a run on a number nobody measured would be
    /// worse than no gate.
    #[test]
    fn the_threshold_fires_on_the_upper_bound_and_never_on_an_absent_one() {
        // 100 files × 1000 B at 1000 B/s over 4 workers = 25 s of work,
        // longest job 1 s → high ≈ 25.75 s.
        let quick = estimate(100, 1_000);
        assert!(quick.high_seconds.unwrap() < 60.0);
        assert!(!over_threshold(&quick, 1));

        // 100 files × 20 kB at the same rate = 20 s each, 2000 s of work over
        // 4 workers → 500 s + a 15 s tail: past one minute, under ten.
        let slow = estimate(100, 20_000);
        let high = slow.high_seconds.unwrap();
        assert!(high > 60.0 && high < 600.0, "{high}");
        assert!(over_threshold(&slow, 1));
        assert!(!over_threshold(&slow, 10));

        // The documented opt-out is obeyed exactly.
        assert!(!over_threshold(&slow, 0));

        // No measurement, no gate — under any threshold.
        let unmeasured = Estimate::compute(
            &[PlannedFile {
                family: "sqlite".into(),
                bytes: 1 << 40,
            }],
            &BTreeMap::new(),
            4,
        );
        assert!(unmeasured.gate_seconds().is_none());
        for minutes in [1, 10, 10_080] {
            assert!(!over_threshold(&unmeasured, minutes));
        }
    }

    #[test]
    fn approve_accepts_the_three_it_can_carry_out_and_refuses_the_one_it_cannot() {
        assert_eq!(Approval::parse("proceed"), Ok(Approval::Proceed));
        assert_eq!(Approval::parse("fast"), Ok(Approval::Fast));
        assert_eq!(Approval::parse("cancel"), Ok(Approval::Cancel));
        // #204: accepting this and indexing everything anyway is the bug.
        let refused = Approval::parse("narrower").unwrap_err();
        assert!(refused.contains("cannot be honoured"), "{refused}");
        assert!(refused.contains("subdirectory"), "{refused}");
        let unknown = Approval::parse("later").unwrap_err();
        assert!(unknown.contains("proceed, fast, cancel"), "{unknown}");
        // Case and spelling are not guessed at.
        assert!(Approval::parse("Proceed").is_err());
        assert!(Approval::parse("").is_err());
    }

    #[test]
    fn the_payload_carries_the_estimate_the_counts_the_bands_and_the_options() {
        let estimate = estimate(10, 1_000);
        let request = DecisionRequest {
            root: "/data".into(),
            estimate: &estimate,
            max_minutes: 10,
            bands: order::summarize(&[order::Item {
                index: 0,
                band: order::Band::SourceAndDocs,
                bytes: 10_000,
            }]),
            heaviest: heaviest_directories(
                &[
                    ("node_modules/a.js".to_string(), 9_000),
                    ("src/main.rs".to_string(), 1_000),
                ],
                5,
            ),
            without_generated: Some((vec!["node_modules".into()], "1.0 s–1.0 s".into())),
            semantic_datasets: vec!["docs".into()],
            total_datasets: 3,
            graph_files: 10,
            prompt_blocked: None,
        };
        let payload = request.to_json();
        assert_eq!(payload["xerj"], "autoindex-decision-request");
        assert_eq!(payload["exit_code"], EXIT_NEEDS_DECISION);
        assert_eq!(payload["estimate"]["planned_files"], 10);
        // An agent reading this must not be able to mistake the floor for a
        // prediction of the run — the machine-readable kind says which it is,
        // and the human-readable line repeats it in words.
        assert_eq!(
            payload["estimate"]["kind"],
            crate::estimate::ESTIMATE_KIND,
            "the payload must name what kind of number this is"
        );
        let estimate_text = payload["estimate_text"].as_str().unwrap();
        assert!(estimate_text.starts_with("at least "), "{estimate_text}");
        assert!(estimate_text.contains("MEASURED FLOOR"), "{estimate_text}");
        assert!(
            payload["reason"]
                .as_str()
                .unwrap()
                .contains("The real run is longer than this"),
            "{}",
            payload["reason"]
        );
        assert_eq!(payload["estimate"]["planned_bytes"], 10_000);
        assert_eq!(payload["priority_order"][0]["band"], "source-and-docs");
        assert!(payload["priority_order"][0]["why"]
            .as_str()
            .unwrap()
            .contains("searches for first"));

        let options = payload["options"].as_array().unwrap();
        let ids: Vec<&str> = options.iter().map(|o| o["id"].as_str().unwrap()).collect();
        assert_eq!(ids, ["proceed", "fast", "narrower", "cancel"]);
        // The honest-claims rule, asserted: `fast` states its scope and admits
        // the factor is not measured, instead of printing an invented "3×".
        let fast = options[1]["cost"].as_str().unwrap();
        assert!(fast.contains("NOT measured"), "{fast}");
        assert!(fast.contains("1 of 3 inferred dataset(s)"), "{fast}");
        assert!(fast.contains("lexical feature-hashing"), "{fast}");
        // `narrower` names the directory and re-costs it with measured rates.
        let narrower = options[2]["cost"].as_str().unwrap();
        assert!(narrower.contains("node_modules"), "{narrower}");
        // …and it never claims --approve can do it.
        assert!(options[2]["invoke"]
            .as_str()
            .unwrap()
            .contains("subdirectory"));

        // The prose carries the same facts for a human.
        let prose = request.prose().join("\n");
        assert!(prose.contains("STOPPING BEFORE INDEXING"));
        assert!(prose.contains("node_modules"));
        assert!(prose.contains("Nothing has been indexed."));
        assert!(prose.contains("not included in the estimate:"));
    }

    #[test]
    fn the_heaviest_directories_are_measured_and_flagged() {
        let dirs = heaviest_directories(
            &[
                ("node_modules/a/b.js".to_string(), 700),
                ("node_modules/c.js".to_string(), 100),
                ("src/main.rs".to_string(), 150),
                ("README.md".to_string(), 50),
            ],
            5,
        );
        assert_eq!(dirs[0].path, "node_modules");
        assert_eq!((dirs[0].files, dirs[0].bytes), (2, 800));
        assert!((dirs[0].share - 0.8).abs() < 1e-9);
        assert!(dirs[0].looks_generated.is_some());
        assert_eq!(dirs[1].path, "src");
        assert!(dirs[1].looks_generated.is_none());
        // Root-level files are their own bucket, not silently merged.
        assert_eq!(dirs[2].path, ".");
        assert_eq!(dirs[2].bytes, 50);
