    }

    #[test]
    fn dropping_the_generated_directories_is_recosted_not_guessed() {
        let files = vec![
            (
                "node_modules/a.js".to_string(),
                "code".to_string(),
                9_000u64,
            ),
            ("src/main.rs".to_string(), "code".to_string(), 1_000),
        ];
        let planned: Vec<PlannedFile> = files
            .iter()
            .map(|(_, family, bytes)| PlannedFile {
                family: family.clone(),
                bytes: *bytes,
            })
            .collect();
        let estimate = Estimate::compute(&planned, &rates(), 1);
        let heaviest = heaviest_directories(
            &files
                .iter()
                .map(|(rel, _, bytes)| (rel.clone(), *bytes))
                .collect::<Vec<_>>(),
            5,
        );
        let (dropped, text) =
            without_generated_directories(&estimate, &rates(), &heaviest, &files).unwrap();
        assert_eq!(dropped, ["node_modules"]);
        // 1000 bytes at the measured 1000 B/s on one worker = 1.0 s.
        assert!(text.starts_with("1.0 s–1.0 s"), "{text}");
        // Nothing droppable → no invented saving.
        let clean = vec![("src/main.rs".to_string(), "code".to_string(), 1_000u64)];
        let clean_dirs = heaviest_directories(&[("src/main.rs".to_string(), 1_000)], 5);
        assert!(without_generated_directories(&estimate, &rates(), &clean_dirs, &clean).is_none());
    }

    /// A non-answer is a cancel. Treating EOF as consent would turn every
    /// piped run into an unattended full index — the exact outcome the gate
    /// exists to prevent.
    #[test]
    fn an_unanswerable_prompt_never_returns_consent() {
        let mut echoed = Vec::new();
        let answer = read_answer(&mut std::io::Cursor::new(b""), |line| {
            echoed.push(line.to_string())
        });
        assert_eq!(answer, None);
        assert_eq!(
            echoed.len(),
            1,
            "EOF must not re-prompt forever: {echoed:?}"
        );

        // Three unrecognised answers and it gives up rather than looping.
        let mut count = 0;
        let answer = read_answer(&mut std::io::Cursor::new(b"x\ny\n\nz\nq\n"), |_| count += 1);
        // 'y' is an accepted spelling of proceed, so this stops at line 2.
        assert_eq!(answer, Some(Approval::Proceed));
        assert!(count >= 2);

        let mut noise = 0;
        assert_eq!(
            read_answer(&mut std::io::Cursor::new(b"a\nb\nc0\nd\n"), |_| noise += 1),
            None
        );
    }

    /// A reader that fails the test if anything reads it. Standing in for the
    /// process's real stdin, which has no EOF and no answer coming.
    struct NeverRead;

    impl std::io::Read for NeverRead {
        fn read(&mut self, _: &mut [u8]) -> std::io::Result<usize> {
            panic!("stdin was read for a question the user was never shown");
        }
    }

    impl std::io::BufRead for NeverRead {
        fn fill_buf(&mut self) -> std::io::Result<&[u8]> {
            panic!("stdin was read for a question the user was never shown");
        }
        fn consume(&mut self, _: usize) {}
    }

    /// THE regression test.
    ///
    /// `--quiet` / `--progress none` silences `Progress::note`, which is where
    /// both the gate's prose and its prompt are printed — but the first cut of
    /// the gate decided whether to ask from the two tty checks alone. So a
    /// person at a terminal who passed `--quiet` was asked a question that was
    /// never printed, and the process sat on `read_line` forever. Measured on
    /// the pre-fix binary: a pty run with `--progress none` over the threshold
    /// emitted **0 bytes** and was still blocked when it was killed at 220 s.
    /// From the outside that is indistinguishable from a hang, in the one
    /// feature whose entire job is to say "this will take a while".
    ///
    /// The reader panics if it is touched, so the invariant asserted here is
    /// the real one — not "an answer was not returned" but "stdin was not
    /// read".
    #[test]
    fn a_question_that_cannot_be_seen_is_never_asked() {
        // Someone IS at the keyboard and both streams are terminals — the one
        // thing missing is that the surface printed nothing.
        let blocked = prompt_blocked_by(true, true, false);
        assert_eq!(
            blocked,
            Some(NoPrompt::QuestionSilenced),
            "a silenced surface must block the prompt on its own"
        );
        let mut echoed = Vec::new();
        // Panics unless the fix is present: pre-fix this opened and read stdin.
        let answer =
            answer_from_terminal(blocked, || NeverRead, |line| echoed.push(line.to_string()));
        assert_eq!(answer, None, "an unaskable question is never consent");
        assert!(
            echoed.is_empty(),
            "nothing may be echoed to a surface that prints nothing: {echoed:?}"
        );

        // …and the run still says so where it can be read. stdout is not
        // silenced by --quiet, so the payload has to carry the reason.
        let estimate = estimate(10, 1_000);
        let request = DecisionRequest {
            root: "/data".into(),
            estimate: &estimate,
            max_minutes: 1,
            bands: Vec::new(),
            heaviest: Vec::new(),
            without_generated: None,
            semantic_datasets: Vec::new(),
            total_datasets: 1,
            graph_files: 0,
            prompt_blocked: blocked,
        };
        let payload = request.to_json();
        assert_eq!(payload["prompt_offered"], false);
        let why = payload["prompt_not_offered_because"].as_str().unwrap();
        assert!(why.contains("--quiet"), "{why}");
        assert!(why.contains("stdout"), "{why}");
        assert!(why.contains("--approve"), "{why}");
        // The exit code is unchanged: a quiet run behaves exactly like the
        // agent-driven one it now matches.
        assert_eq!(payload["exit_code"], EXIT_NEEDS_DECISION);
    }

    /// The other three ways in, so the rule is pinned end to end rather than
    /// only at the case that was broken.
    #[test]
    fn the_prompt_is_offered_only_when_all_three_conditions_hold() {
        // A terminal, a visible surface: this is the one case that asks.
        assert_eq!(prompt_blocked_by(true, true, true), None);
        // Agent, CI, pipe: nobody to type. Checked first because it is the
        // reason that stays true however the surface is configured.
        assert_eq!(
            prompt_blocked_by(false, true, true),
            Some(NoPrompt::StdinNotTerminal)
        );
        assert_eq!(
            prompt_blocked_by(false, false, false),
            Some(NoPrompt::StdinNotTerminal)
        );
        // stderr redirected to a log: the question would not reach a screen.
        assert_eq!(
            prompt_blocked_by(true, false, true),
            Some(NoPrompt::StderrNotTerminal)
        );
        // Every reason names a way out, and none of them is "wait".
        for reason in [
            NoPrompt::StdinNotTerminal,
            NoPrompt::StderrNotTerminal,
            NoPrompt::QuestionSilenced,
        ] {
            let text = reason.explain();
            assert!(text.contains("--approve"), "{text}");
            // Every blocked path must leave stdin alone, not merely decline to
            // return an answer.
            assert_eq!(
                answer_from_terminal(Some(reason), || NeverRead, |_| {}),
                None
            );
        }

        // A visible terminal really does read the answer — the fix must not
        // have turned the prompt off for everyone.
        assert_eq!(
            answer_from_terminal(None, || std::io::Cursor::new(b"f\n"), |_| {}),
            Some(Approval::Fast)
        );
    }

    #[test]
    fn every_spelling_of_an_answer_maps_to_one_decision() {
        for (input, expected) in [
            ("p\n", Approval::Proceed),
            ("PROCEED\n", Approval::Proceed),
            ("  yes  \n", Approval::Proceed),
            ("f\n", Approval::Fast),
            ("Fast\n", Approval::Fast),
            ("c\n", Approval::Cancel),
            ("no\n", Approval::Cancel),
            ("q\n", Approval::Cancel),
        ] {
            assert_eq!(
                read_answer(&mut std::io::Cursor::new(input.as_bytes()), |_| {}),
                Some(expected),
                "{input:?}"
            );
        }
    }
}

//! Identity resolution: turn N source records into unique logical records.
//!
//! Union-find over identity-edge VALUES: every value a recipe declares as
//! an edge (`id`, each element of `aliases`, …) is a node, and a record
//! unions with each of its own values. Two records sharing ANY value merge,
//! transitively and cyclically — exactly the alias closure the sources
//! themselves do not provide (OSV ships one record per source ID, linked
//! only by `aliases`; it does not merge them for you).
//!
//! Derived relations (CVE↔commit, say) are deliberately NOT edges: a single
//! commit fixing two CVEs would fuse two advisories that are distinct
//! findings. Identity is what the sources SAY is the same thing, never what
//! we infer from shared references.
//!
//! Merge is first-non-empty-wins under the recipe's precedence, with arrays
//! unioned — deterministic given the member order, which is itself
//! (precedence rank, store key), never filesystem accident.

use std::collections::HashMap;

use serde_json::{Map, Value};

use super::recipe::{
    slug_rank, Derived, DerivedOp, Envelope, Identity, Merge, LICENCE, SRC, SRC_PATH, SRC_URL,
};

/// The store-key sentinel `store::read_all` injects. Sorting by it keeps
/// member order deterministic when two members share a source rank.
pub(crate) const KEY: &str = "\u{0}key";

/// One cluster of envelopes that are the same logical record.
pub struct Cluster {
    /// Indices into the envelope slice, in canonical order.
    pub members: Vec<usize>,
}

/// Group envelopes into clusters. Deterministic: iteration follows the
/// envelope order, and cluster output order follows each cluster's minimum
/// member index.
pub fn cluster(envelopes: &[Map<String, Value>], identity: &Identity) -> Vec<Cluster> {
    // DSU over [0..envelopes) ∪ value nodes (mapped to >= envelopes). Value
    // nodes always lose unions (records have smaller indices), so every
    // root stays below envelopes.len().
    let mut parent: Vec<usize> = (0..envelopes.len()).collect();
    let mut value_nodes: HashMap<String, usize> = HashMap::new();

    fn find(parent: &mut [usize], mut x: usize) -> usize {
        while parent[x] != x {
            parent[x] = parent[parent[x]]; // path halving
            x = parent[x];
        }
        x
    }

    for (i, env) in envelopes.iter().enumerate() {
        for value in identity_values(env, &identity.edges) {
            let node = *value_nodes.entry(value).or_insert_with(|| {
                parent.push(parent.len());
                parent.len() - 1
            });
            let (ra, rb) = (find(&mut parent, i), find(&mut parent, node));
            if ra != rb {
                let (lo, hi) = if ra < rb { (ra, rb) } else { (rb, ra) };
                parent[hi] = lo;
            }
        }
    }

    let mut by_root: Vec<Vec<usize>> = vec![Vec::new(); envelopes.len()];
    for i in 0..envelopes.len() {
        by_root[find(&mut parent, i)].push(i);
    }
    by_root
        .into_iter()
        .filter(|m| !m.is_empty())
        .map(|mut members| {
            members.sort_by_key(|&i| order_key(&envelopes[i], &identity.canonical_source_order));
            Cluster { members }
        })
        .collect()
}

/// The identity-edge values of one envelope. `each = true` explodes string
/// arrays element-wise; a plain string field is one value; empty strings
/// and other types contribute nothing.
fn identity_values(env: &Map<String, Value>, edges: &[super::recipe::IdentityEdge]) -> Vec<String> {
    let mut out = Vec::new();
    for e in edges {
        match env.get(&e.field) {
            Some(Value::String(s)) if !s.is_empty() => out.push(s.clone()),
            Some(Value::Array(a)) if e.each => {
                for v in a {
                    if let Some(s) = v.as_str() {
                        if !s.is_empty() {
                            out.push(s.to_string());
                        }
                    }
                }
            }
            // each=false on an array: the array as a whole is not an
            // identity — arrays vary by source even for the same record.
            _ => {}
        }
    }
    out
}

/// Sort key for members: the order list's rank first, then the envelope's
/// store key — stability that does not depend on directory iteration order.
fn order_key(env: &Map<String, Value>, order: &[String]) -> (usize, String) {
    let slug = env.get(SRC).and_then(Value::as_str).unwrap_or("");
    let key = env.get(KEY).and_then(Value::as_str).unwrap_or("");
    (slug_rank(order, slug), key.to_string())
}

/// Which member "wins" a scalar: the first (by merge order) carrying a
/// non-empty value.
fn first_str<'a>(members: &[&'a Map<String, Value>], key: &str) -> Option<&'a str> {
    members
        .iter()
        .filter_map(|m| m.get(key).and_then(Value::as_str))
        .find(|s| !s.is_empty())
}

/// Merge one passthrough key: an ARRAY in any member makes the result an
/// array (union across members, deduped, scalars folded in as elements —
/// sources disagree on cardinality more often than they agree); scalars
/// everywhere keep it a scalar, first non-empty under precedence.
fn merge_field(ranked: &[&Map<String, Value>], key: &str) -> Option<Value> {
    let any_array = ranked
        .iter()
        .any(|m| matches!(m.get(key), Some(Value::Array(_))));
    if any_array {
        return union_arrays(ranked, key).map(Value::Array);
    }
    if let Some(s) = first_str(ranked, key) {
        return Some(Value::String(s.to_string()));
    }
    ranked
        .iter()
        .find_map(|m| m.get(key).filter(|v| !v.is_null() && !v.is_string()))
        .cloned()
}

/// Union arrays across members preserving member order, deduped. A lone
/// string folds in as a single element.
fn union_arrays(members: &[&Map<String, Value>], key: &str) -> Option<Vec<Value>> {
    let mut out: Vec<Value> = Vec::new();
    for m in members {
        match m.get(key) {
            Some(Value::Array(a)) => {
                for v in a {
                    if !out.contains(v) {
                        out.push(v.clone());
                    }
                }
            }
            Some(Value::String(s)) if !s.is_empty() => {
                let v = Value::String(s.clone());
                if !out.contains(&v) {
                    out.push(v);
                }
            }
            _ => {}
        }
    }
    (!out.is_empty()).then_some(out)
}

/// The most-restrictive licence across members. A merged record
/// redistributes text from EVERY member, so a restricted member must be
/// able to veto the permissive ones — `is_restricted` is binary (the
/// licence tuple has no total order), so: any restricted member's licence
/// wins (precedence-first among them); otherwise precedence-first
/// non-empty. Attribution-grade obligations the binary predicate cannot
/// rank (CC-BY-4.0 vs CC0) stay visible per record through `sources[]`
/// and per pack through the manifest's source list — the `licence` field
/// is the redistribution-warning signal, not a legal settlement.
fn most_restrictive(members: &[&Map<String, Value>]) -> String {
    let mut first_non_empty = String::new();
    for m in members {
        let lic = m.get(LICENCE).and_then(Value::as_str).unwrap_or("");
        if lic.is_empty() {
            continue;
        }
        if xerj_common::xccode::licence::is_restricted(lic) {
            return lic.to_string();
        }
        if first_non_empty.is_empty() {
            first_non_empty = lic.to_string();
        }
    }
    first_non_empty
}

/// Merge one cluster into a single output record (envelope fields, then
/// passthrough, then derived). `order` is the merge precedence.
pub fn merge_cluster(
    cluster: &[&Map<String, Value>],
    order: &[String],
    envelope: &Envelope,
    merge: &Merge,
    derived: &[Derived],
) -> Map<String, Value> {
    let mut members: Vec<&Map<String, Value>> = cluster.to_vec();
    members.sort_by_key(|m| order_key(m, order));
    let winner = members.first().copied();

    let mut out = Map::new();

    // — envelope fields ────────────────────────────────────────────────────
    let id = first_of(&members, &envelope.id_from);
    out.insert("id".into(), Value::String(id.unwrap_or_default()));
    let title = first_of(&members, &envelope.title_from);
    out.insert("title".into(), Value::String(title.unwrap_or_default()));

    // body: per member, join its body_join fields; the first non-empty
    // joined body wins (joining ACROSS sources would duplicate the same
    // advisory prose written twice).
    let mut body = String::new();
    for m in &members {
        let parts: Vec<&str> = envelope
            .body_join
            .iter()
            .filter_map(|k| m.get(k).and_then(Value::as_str).filter(|s| !s.is_empty()))
            .collect();
        if !parts.is_empty() {
            body = parts.join("\n\n");
            break;
        }
    }
    out.insert("body".into(), Value::String(body));

    // defs: union of the defs_from arrays across ALL members, space-joined —
    // this is the field `xerj code` matches definition queries against.
    let mut defs: Vec<String> = Vec::new();
    for m in &members {
        for k in &envelope.defs_from {
            if let Some(Value::Array(a)) = m.get(k) {
                for v in a {
                    if let Some(s) = v.as_str() {
                        if !s.is_empty() && !defs.iter().any(|d| d == s) {
                            defs.push(s.to_string());
                        }
                    }
                }
            }
        }
    }
    out.insert("defs".into(), Value::String(defs.join(" ")));

    out.insert("licence".into(), Value::String(most_restrictive(&members)));

    // sources: contributing slugs in precedence order; `source` names the
    // winner, `source_url`/`origin` point back into it.
    let mut slugs: Vec<Value> = Vec::new();
    for m in &members {
        if let Some(s) = m.get(SRC).and_then(Value::as_str) {
            let v = Value::String(s.to_string());
            if !slugs.contains(&v) {
                slugs.push(v);
            }
        }
    }
    out.insert("sources".into(), Value::Array(slugs));
    let get = |k: &str| {
        winner
            .and_then(|m| m.get(k))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string()
    };
    out.insert("source".into(), Value::String(get(SRC)));
    out.insert("source_url".into(), Value::String(get(SRC_URL)));
    out.insert("origin".into(), Value::String(get(SRC_PATH)));

    // modified: max member value (RFC3339 UTC strings compare correctly).
    let modified = members
        .iter()
        .filter_map(|m| m.get("modified").and_then(Value::as_str))
        .filter(|s| !s.is_empty())
        .max()
        .unwrap_or("")
        .to_string();
    out.insert("modified".into(), Value::String(modified));

    // — passthrough ───────────────────────────────────────────────────────
    // Every data key any member carries, minus provenance sentinels and
    // what the envelope already fixed. Scalars are first-non-empty under
    // the field's precedence (global, or per-field when overridden); arrays
    // union across members regardless of precedence — evidence accumulates.
    if envelope.passthrough {
        let mut keys: Vec<&String> = members
            .iter()
            .flat_map(|m| m.keys())
            .filter(|k| {
                !k.starts_with('\u{0}') && !k.starts_with('_') && !out.contains_key(k.as_str())
            })
            .collect();
        keys.sort();
        keys.dedup();
        for k in keys {
            let order = merge
                .field_precedence
                .get(k)
                .map(Vec::as_slice)
                .unwrap_or(order);
            let mut ranked = members.clone();
            ranked.sort_by_key(|m| order_key(m, order));
            if let Some(v) = merge_field(&ranked, k) {
                out.insert(k.clone(), v);
            }
        }
    }

    // — derived fields ────────────────────────────────────────────────────
    for d in derived {
        let v = apply_derived(&out, &d.op);
        out.insert(d.name.clone(), v);
    }

    out
}

/// First non-empty string among any of the listed keys, scanning members in
/// order. The key list wins over member order: `title_from = ["summary",
/// "id"]` prefers a summary from ANY source over an id from the top source
/// — the human-readable name wherever it exists.
fn first_of(members: &[&Map<String, Value>], keys: &[String]) -> Option<String> {
    for k in keys {
        if let Some(s) = first_str(members, k) {
            return Some(s.to_string());
        }
    }
    None
}

fn apply_derived(rec: &Map<String, Value>, op: &DerivedOp) -> Value {
    match op {
        DerivedOp::RegexExtract { from, re, unique } => {
            let mut out: Vec<Value> = Vec::new();
            for k in from {
                let texts: Vec<String> = match rec.get(k) {
                    Some(Value::String(s)) => vec![s.clone()],
                    Some(Value::Array(a)) => a
                        .iter()
                        .filter_map(|v| v.as_str().map(str::to_string))
                        .collect(),
                    _ => Vec::new(),
                };
                for t in texts {
                    for m in re.find_iter(&t) {
                        let v = Value::String(m.as_str().to_string());
                        if !*unique || !out.contains(&v) {
                            out.push(v);
                        }
                    }
                }
            }
            Value::Array(out)
        }
        DerivedOp::Map {
            from,
            rules,
            default,
        } => {
            let text = rec.get(from).and_then(Value::as_str).unwrap_or("");
            for (re, value) in rules {
                if re.is_match(text) {
                    return Value::String(value.clone());
                }
            }
            Value::String(default.clone())
        }
        DerivedOp::Present { from } => {
            let present = match rec.get(from) {
                None | Some(Value::Null) => false,
                Some(Value::String(s)) => !s.is_empty(),
                Some(_) => true,
            };
            Value::Bool(present)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::harvest::recipe::IdentityEdge;
    use regex::Regex;
    use serde_json::json;

    fn env(src: &str, fields: &[(&str, Value)]) -> Map<String, Value> {
        let mut m = Map::new();
        m.insert(SRC.into(), json!(src));
        m.insert(SRC_URL.into(), json!(format!("https://example/{src}")));
        m.insert(SRC_PATH.into(), json!(format!("{src}/record.json")));
        m.insert(LICENCE.into(), json!("CC0-1.0"));
        m.insert(KEY.into(), json!(format!("{src}-key")));
        for (k, v) in fields {
            m.insert(k.to_string(), v.clone());
        }
        m
    }

    fn edges(spec: &[(&str, bool)]) -> Vec<IdentityEdge> {
        spec.iter()
            .map(|(f, e)| IdentityEdge {
                field: f.to_string(),
                each: *e,
            })
            .collect()
    }

    fn identity_of(edges: Vec<IdentityEdge>) -> Identity {
        Identity {
            edges,
            canonical_source_order: vec![],
        }
    }

    #[test]
    fn alias_chain_and_cycle_collapse_to_one_cluster() {
        // rustsec --CVE--> ghsa and a direct alias edge, plus a cycle
        let a = env(
            "rustsec",
            &[("id", json!("R1")), ("aliases", json!(["C1"]))],
        );
        let b = env(
            "ghsa",
            &[("id", json!("G1")), ("aliases", json!(["C1", "R1"]))],
        );
        let c = env(
            "osv",
            &[("id", json!("C1")), ("aliases", json!(["R1", "G1"]))],
        );
        let identity = identity_of(edges(&[("id", false), ("aliases", true)]));
        let clusters = cluster(&[a, b, c], &identity);
        assert_eq!(clusters.len(), 1, "all three are one logical record");
        assert_eq!(clusters[0].members.len(), 3);
    }

    #[test]
    fn disjoint_records_stay_apart() {
        let a = env("a", &[("id", json!("X1"))]);
        let b = env("a", &[("id", json!("X2"))]);
        let clusters = cluster(&[a, b], &identity_of(edges(&[("id", false)])));
        assert_eq!(clusters.len(), 2);
    }

    #[test]
    fn shared_commit_is_not_an_identity() {
        // two CVEs referencing the same fixing commit must NOT merge
        let a = env(
            "a",
            &[
                ("id", json!("CVE-1")),
                ("commit_urls", json!(["https://x/commit/deadbeef"])),
            ],
        );
        let b = env(
            "a",
            &[
                ("id", json!("CVE-2")),
                ("commit_urls", json!(["https://x/commit/deadbeef"])),
            ],
        );
        let clusters = cluster(&[a, b], &identity_of(edges(&[("id", false)])));
        assert_eq!(
            clusters.len(),
            2,
            "commits are derived edges, never identity"
        );
    }

    fn envelope() -> Envelope {
        Envelope {
            id_from: vec!["id".into()],
            title_from: vec!["summary".into(), "id".into()],
            body_join: vec!["summary".into(), "details".into()],
            defs_from: vec!["affected_functions".into()],
            passthrough: true,
        }
    }

    #[test]
    fn merge_prefers_precedence_and_unions_arrays() {
        let r = env(
            "rustsec",
            &[
                ("id", json!("R1")),
                ("summary", json!("unsound insert_many")),
                ("details", json!("root cause prose")),
                ("aliases", json!(["CVE-1"])),
                (
                    "affected_functions",
                    json!(["smallvec::SmallVec::insert_many"]),
                ),
                ("fixed_versions", json!(["0.6.14"])),
            ],
        );
        let g = env(
            "ghsa",
            &[
                ("id", json!("G1")),
                ("aliases", json!(["CVE-1", "R1"])),
                ("fixed_versions", json!(["1.6.1", "0.6.14"])),
                ("severity", json!("HIGH")),
            ],
        );
        // g is CC-BY: non-restricted, so precedence-first CC0 wins the FIELD
        // (attribution still rides via sources[]/manifest)…
        let mut g = g;
        g.insert(LICENCE.into(), json!("CC-BY-4.0"));
        let merged = merge_cluster(
            &[&r, &g],
            &["rustsec".to_string(), "ghsa".to_string()],
            &envelope(),
            &Merge::default(),
            &[],
        );
        assert_eq!(
            merged["id"],
            json!("R1"),
            "precedence-first member names the id"
        );
        assert_eq!(merged["title"], json!("unsound insert_many"));
        assert!(merged["body"]
            .as_str()
            .unwrap()
            .contains("root cause prose"));
        assert_eq!(
            merged["defs"],
            json!("smallvec::SmallVec::insert_many"),
            "defs feeds xerj code's definition matching"
        );
        assert_eq!(merged["licence"], json!("CC0-1.0"));
        // …but one restricted member vetoes every permissive one
        let mut g2 = env(
            "cisa",
            &[("id", json!("C1")), ("aliases", json!(["CVE-1", "R1"]))],
        );
        g2.insert(LICENCE.into(), json!("GPL-3.0"));
        let merged = merge_cluster(
            &[&r, &g, &g2],
            &[
                "rustsec".to_string(),
                "ghsa".to_string(),
                "cisa".to_string(),
            ],
            &envelope(),
            &Merge::default(),
            &[],
        );
        assert_eq!(
            merged["licence"],
            json!("GPL-3.0"),
            "restricted wins outright"
        );
        assert_eq!(merged["sources"], json!(["rustsec", "ghsa", "cisa"]));
        assert_eq!(merged["source"], json!("rustsec"));
        assert_eq!(merged["source_url"], json!("https://example/rustsec"));
        assert_eq!(merged["origin"], json!("rustsec/record.json"));
        assert_eq!(
            merged["fixed_versions"],
            json!(["0.6.14", "1.6.1"]),
            "arrays union in member order, deduped"
        );
        assert_eq!(merged["aliases"], json!(["CVE-1", "R1"]));
        assert_eq!(merged["severity"], json!("HIGH"), "only g has it");
    }

    #[test]
    fn title_from_spans_sources_before_falling_back() {
        // a summary in a LOWER precedence source beats the id of a higher one
        let r = env("rustsec", &[("id", json!("R1"))]);
        let g = env(
            "ghsa",
            &[("id", json!("G1")), ("summary", json!("the real title"))],
        );
        let merged = merge_cluster(
            &[&r, &g],
            &["rustsec".to_string(), "ghsa".to_string()],
            &envelope(),
            &Merge::default(),
            &[],
        );
        assert_eq!(merged["title"], json!("the real title"));
    }

    #[test]
    fn modified_takes_the_latest_member_value() {
        let r = env(
            "rustsec",
            &[
                ("id", json!("R1")),
                ("modified", json!("2024-01-01T00:00:00Z")),
            ],
        );
        let g = env(
            "ghsa",
            &[
                ("id", json!("G1")),
                ("modified", json!("2025-06-01T00:00:00Z")),
            ],
        );
        let merged = merge_cluster(
            &[&r, &g],
            &["rustsec".to_string(), "ghsa".to_string()],
            &envelope(),
            &Merge::default(),
            &[],
        );
        assert_eq!(merged["modified"], json!("2025-06-01T00:00:00Z"));
    }

    #[test]
    fn derived_ops_run_over_the_merged_record() {
        let r = env(
            "rustsec",
            &[
                ("id", json!("RUSTSEC-2021-0003")),
                ("aliases", json!(["CVE-2021-25900"])),
                ("summary", json!("Unsound: insert_many")),
                ("withdrawn", Value::Null),
                (
                    "reference_urls",
                    json!([
                        "https://github.com/servo/rust-smallvec/commit/abc1234",
                        "https://github.com/servo/rust-smallvec/pull/9"
                    ]),
                ),
            ],
        );
        let cve = Regex::new(r"(?i)\bCVE-\d{4}-\d{4,}\b").unwrap();
        let commit =
            Regex::new(r"https://github\.com/[^/\s]+/[^/\s]+/commit/[0-9a-f]{7,40}").unwrap();
        let unsound = Regex::new(r"(?i)\bunsound\b").unwrap();
        let merged = merge_cluster(
            &[&r],
            &["rustsec".to_string()],
            &envelope(),
            &Merge::default(),
            &[
                Derived {
                    name: "cve_ids".into(),
                    op: DerivedOp::RegexExtract {
                        from: vec!["id".into(), "aliases".into()],
                        re: cve,
                        unique: true,
                    },
                },
                Derived {
                    name: "commit_urls".into(),
                    op: DerivedOp::RegexExtract {
                        from: vec!["reference_urls".into()],
                        re: commit,
                        unique: true,
                    },
                },
                Derived {
                    name: "record_kind".into(),
                    op: DerivedOp::Map {
                        from: "title".into(),
                        rules: vec![(unsound, "informational".into())],
                        default: "vulnerability".into(),
                    },
                },
                Derived {
                    name: "is_withdrawn".into(),
                    op: DerivedOp::Present {
                        from: "withdrawn".into(),
                    },
                },
            ],
        );
        assert_eq!(merged["cve_ids"], json!(["CVE-2021-25900"]));
        assert_eq!(
            merged["commit_urls"],
            json!(["https://github.com/servo/rust-smallvec/commit/abc1234"]),
            "the PR link is not a commit"
        );
        assert_eq!(merged["record_kind"], json!("informational"));
        assert_eq!(merged["is_withdrawn"], json!(false), "null is not present");
    }
}

//! `xerj corpus build` — build a portable corpus pack from harvested records.
//!
//! The pipeline, end to end:
//!
//! ```text
//! recipe.toml ─→ harvest (dir walk / M2: http-zip, git)
//!             ─→ normalize (format adapter: osv | flat)
//!             ─→ store     (content-addressed, presence = dedup)
//!             ─→ identity  (union-find over declared edge values)
//!             ─→ merge     (precedence + array union + strictest licence)
//!             ─→ suggest   (mapping + join-key hints from a sample — never applied)
//!             ─→ pack      (deterministic sharded JSONL + manifest + SUMS)
//!
//! Publishing is a separate step, never part of a build:
//! `xerj corpus sign <pack-dir> --key <seed-file>` writes the detached
//! ed25519 signature over SHA256SUMS (see `sign.rs`); `xerj corpus add
//! --from <pack> --verify-sig <pubkey-file>` checks it on the way in.
//! ```
//!
//! Incrementality is not a mode, it is the storage layout: every normalized
//! record lands at `store/<slug>.<xxh3-of-canonical-json>.json`, so a re-run
//! recomputes the key, sees the file, and skips. Deleting the source tree's
//! unchanged files and re-running is a no-op beyond the walk; the pack is
//! then rebuilt from the store deterministically.
//!
//! The tool is domain-agnostic by directive: what a "record" is, which
//! fields are identity, and how fields merge all live in the recipe, never
//! here. Licence terms ride along as record data (`licence`, per-source
//! `sources[]`); the tool does not and must not enforce them — the pack
//! author owns what goes in the pack.

pub mod httpget;
pub mod identity;
pub mod normalize;
pub mod pack;
pub mod recipe;
pub mod sign;
pub mod source;
pub mod store;
pub mod suggest;

pub(crate) use store::MAX_FIELDS;

use std::collections::HashSet;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use serde_json::{Map, Value};

use crate::xc::code_root;
use pack::{RunStats, SourceStat};
use recipe::{SourceKind, LICENCE, SRC, SRC_PATH, SRC_URL};

const BUILD_USAGE: &str = "usage: xerj corpus build <name> [--recipe <path>] [--fresh]

build (or incrementally refresh) a harvested corpus pack:
  1. load the recipe (default $XERJ_CODE_HOME/recipes/<name>.toml)
  2. harvest every declared source into the content store
     (already-stored records are skipped — that is the point)
  3. resolve identity, merge duplicates, emit a deterministic pack
     under $XERJ_CODE_HOME/builds/<name>/pack/<name>/

--fresh discards the build state first (full re-harvest).";

/// Entry point from the corpus dispatcher. 0 = pack built, 1 = failure,
/// 2 = usage error.
pub fn run_build(args: &[String]) -> i32 {
    match run_build_inner(args, &code_root()) {
        Ok(code) => code,
        Err(e) => {
            eprintln!("xerj corpus build: {e:#}");
            1
        }
    }
}

fn run_build_inner(args: &[String], home: &Path) -> Result<i32> {
    let mut name: Option<String> = None;
    let mut recipe_path: Option<PathBuf> = None;
    let mut fresh = false;
    let mut it = args.iter();
    while let Some(a) = it.next() {
        match a.as_str() {
            "--recipe" => {
                recipe_path = Some(PathBuf::from(it.next().context("--recipe needs a path")?));
            }
            "--fresh" => fresh = true,
            "-h" | "--help" | "help" => {
                println!("{BUILD_USAGE}");
                return Ok(0);
            }
            s if s.starts_with('-') => bail!("unknown flag '{s}'\n\n{BUILD_USAGE}"),
            s => {
                if name.replace(s.to_string()).is_some() {
                    bail!("unexpected second name '{s}'\n\n{BUILD_USAGE}");
                }
            }
        }
    }
    let Some(name) = name else {
        eprintln!("{BUILD_USAGE}");
        return Ok(2);
    };

    let recipe_file = match recipe_path {
        Some(p) => p,
        None => home.join("recipes").join(format!("{name}.toml")),
    };
    if !recipe_file.is_file() {
        bail!(
            "no recipe for '{name}' at {} (pass --recipe <path>, or create it there)",
            recipe_file.display()
        );
    }
    let recipe = recipe::load(&recipe_file)?;
    if recipe.name != name {
        bail!(
            "recipe at {} builds corpus '{}', not '{}' — the name must match",
            recipe_file.display(),
            recipe.name,
            name
        );
    }
    let recipe_dir = recipe_file
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let recipe_toml = std::fs::read_to_string(&recipe_file)?;

    let build_dir = home.join("builds").join(&recipe.name);
    if fresh && build_dir.exists() {
        std::fs::remove_dir_all(&build_dir)
            .with_context(|| format!("--fresh: cannot clear {}", build_dir.display()))?;
    }
    let store_dir = build_dir.join("store");
    let cache_dir = build_dir.join("cache");

    // ── harvest into the content store ───────────────────────────────────
    let mut per_source = Vec::new();
    for src in &recipe.sources {
        let fetched = source::fetch(src, &recipe_dir, &cache_dir)?;
        let mut stat = SourceStat {
            slug: src.slug.clone(),
            kind: kind_name(src.kind).to_string(),
            path: src.path.clone(),
            url: src.url.clone(),
            licence: src.licence.clone(),
            watermark: fetched.watermark.clone(),
            unchanged: fetched.unchanged,
            records: 0,
            new: 0,
            skipped: 0,
            pruned: 0,
        };
        if fetched.unchanged {
            // The whole upstream tree is byte-identical to the previous run:
            // skip the walk AND the prune — every envelope this source ever
            // stored is still live, and pruning needs the full key set.
            per_source.push(stat);
            continue;
        }
        let files = walk(&fetched.root, &src.glob)?;
        let mut keys = HashSet::new();
        for (rel, path) in files {
            for value in parse_file(&path, src.records_field.as_deref())? {
                let mut env = normalize::normalize(src.format, &value);
                env.insert(SRC.into(), Value::String(src.slug.clone()));
                env.insert(
                    SRC_URL.into(),
                    Value::String(src.url.clone().unwrap_or_default()),
                );
                env.insert(SRC_PATH.into(), Value::String(rel.clone()));
                env.insert(LICENCE.into(), Value::String(src.licence.clone()));
                let (key, was_new) = store::put(&store_dir, &src.slug, &env)?;
                keys.insert(key);
                stat.records += 1;
                if was_new {
                    stat.new += 1;
                } else {
                    stat.skipped += 1;
                }
            }
        }
        stat.pruned = store::prune(&store_dir, &src.slug, &keys);
        // persist the watermark only after the source's harvest fully
        // succeeded — a failed run must re-walk
        if let Some(wm) = &fetched.watermark {
            source::save_watermark(&cache_dir, &src.slug, wm)?;
        }
        per_source.push(stat);
    }

    // ── identity + merge over the FULL store (not just this run's files) ──
    let slugs: HashSet<String> = recipe.sources.iter().map(|s| s.slug.clone()).collect();
    let envelopes = store::read_all(&store_dir, &slugs)?;
    let clusters = identity::cluster(&envelopes, &recipe.identity);
    let merge_order = if recipe.merge.precedence.is_empty() {
        recipe.identity.canonical_source_order.clone()
    } else {
        recipe.merge.precedence.clone()
    };
    let mut records = Vec::with_capacity(clusters.len());
    for c in &clusters {
        let members: Vec<&Map<String, Value>> = c.members.iter().map(|&i| &envelopes[i]).collect();
        records.push(identity::merge_cluster(
            &members,
            &merge_order,
            &recipe.envelope,
            &recipe.merge,
            &recipe.derived,
        ));
    }

    // ── emit ──────────────────────────────────────────────────────────────
    let stats = RunStats {
        envelopes: envelopes.len(),
        per_source,
    };
    // suggestions from a deterministic sample — the recipe author's feedback
    // loop, never applied to the records or the index
    let suggestions = suggest::analyze(&records, recipe.suggest.sample);
    let result = pack::emit(
        &build_dir,
        &recipe,
        &recipe_toml,
        records,
        &stats,
        &suggestions,
    )?;

    // run report: the machine-readable twin of the stdout summary, with the
    // watermarks a scheduled rebuild (M6) will diff against
    let report = serde_json::json!({
        "finished_at": chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
        "pack": recipe.name,
        "generation": result.generation,
        "records": result.records,
        "envelopes": stats.envelopes,
        "sources": stats.per_source.iter()
            .map(|s| serde_json::to_value(s).expect("SourceStat serializes"))
            .collect::<Vec<_>>(),
    });
    std::fs::write(
        build_dir.join("report.json"),
        serde_json::to_vec_pretty(&report)?,
    )
    .with_context(|| format!("write {}", build_dir.join("report.json").display()))?;

    println!(
        "built '{}' generation {}: {} envelopes → {} records, {} shard file(s)",
        recipe.name, result.generation, stats.envelopes, result.records, result.shards
    );
    for s in &stats.per_source {
        if s.unchanged {
            println!(
                "  {}: unchanged (watermark {})",
                s.slug,
                s.watermark.clone().unwrap_or_default()
            );
            continue;
        }
        println!(
            "  {}: {} record(s) — {} new, {} skipped, {} pruned ({})",
            s.slug, s.records, s.new, s.skipped, s.pruned, s.licence
        );
    }
    println!("pack: {}", result.dir.display());
    println!(
        "  suggestions: {} field(s), {} relation(s) — see {}",
        suggestions.fields.len(),
        suggestions.relations.len(),
        result.dir.join("suggestions.md").display()
    );
    Ok(0)
}

fn kind_name(kind: SourceKind) -> &'static str {
    match kind {
        SourceKind::Dir => "dir",
        SourceKind::HttpZip => "http-zip",
        SourceKind::HttpJson => "http-json",
        SourceKind::Git => "git",
    }
}

// ── dir source ──────────────────────────────────────────────────────────────

/// Recursively list files under `root` matching `glob`, as
/// (posix-relative-path, absolute-path), sorted — directory iteration order
/// must never reach the output.
fn walk(root: &Path, glob: &str) -> Result<Vec<(String, PathBuf)>> {
    // A source root that cannot be read is a HARD error, never an empty
    // walk. A `dir` source whose path is typo'd, points at the wrong cwd, or
    // names a tree that was renamed upstream would otherwise walk to zero
    // files; `prune` then deletes every envelope the slug ever stored and
    // the build exits 0 with a smaller, all-checksums-valid pack — silent
    // data loss (#1110 negative-path audit, gap 1). An existing but empty
    // directory is still allowed: a legitimately empty upstream prunes to
    // zero on purpose, a missing one does not.
    let meta = std::fs::metadata(root).with_context(|| {
        format!(
            "source root {} cannot be read — a typo'd path or a moved upstream \
             tree must fail the build, not silently empty the pack",
            root.display()
        )
    })?;
    if !meta.is_dir() {
        bail!("source root {} is not a directory", root.display());
    }
    let re = glob_regex(glob);
    let mut out = Vec::new();
    // A listing error must not become "no files". The autoindex walker
    // skips an unreadable entry (`walk.rs:327`, the `Err` arm of `it.next()`)
    // because a skipped file is only absent from that pass. Here `prune`
    // treats "not seen" as "deleted upstream", so swallowing `read_dir` —
    // on the root or on any nested directory — deletes every envelope under
    // it and the build still exits 0 (#1110 gap 1). `metadata` above already
    // refuses a missing root; this is the root that exists but cannot be
    // listed, and the same failure one directory down.
    fn recurse(
        dir: &Path,
        root: &Path,
        re: &regex::Regex,
        out: &mut Vec<(String, PathBuf)>,
    ) -> Result<()> {
        let entries = std::fs::read_dir(dir).with_context(|| {
            format!(
                "source directory {} cannot be listed — an unreadable tree must \
                 fail the build, not silently empty the pack",
                dir.display()
            )
        })?;
        for e in entries {
            let e = e.with_context(|| format!("cannot read entry in {}", dir.display()))?;
            let p = e.path();
            // `Path::is_dir` follows symlinks, which is the walk this
            // replaced. A stat failure reports "not a directory" (same as
            // before); the failure this function refuses is `read_dir`.
            if p.is_dir() {
                recurse(&p, root, re, out)?;
            } else {
                let rel = p.strip_prefix(root).unwrap_or(&p);
                let rel = rel.to_string_lossy().replace('\\', "/");
                if re.is_match(&rel) {
                    out.push((rel, p));
                }
            }
        }
        Ok(())
    }
    recurse(root, root, &re, &mut out)?;
    out.sort();
    Ok(out)
}

/// Minimal glob → regex: `**` spans directories (`**/` also matches zero
/// directories), `*` stays inside one segment, `?` is one char. Recipes
/// need path matching, not the full glob grammar; if a recipe ever needs
/// character classes we take a real glob crate rather than growing this.
fn glob_regex(glob: &str) -> regex::Regex {
    let mut re = String::from("^");
    let mut chars = glob.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '*' => {
                if chars.peek() == Some(&'*') {
                    chars.next();
                    if chars.peek() == Some(&'/') {
                        chars.next();
                        re.push_str("(.*/)?");
                    } else {
                        re.push_str(".*");
                    }
                } else {
                    re.push_str("[^/]*");
                }
            }
            '?' => re.push_str("[^/]"),
            other => re.push_str(&regex::escape(&other.to_string())),
        }
    }
    re.push('$');
    regex::Regex::new(&re).expect("glob translation always yields a valid regex")
}

/// Parse one harvested file: `.json`/`.jsonl`/`.ndjson`/`.md`. A `.json`
/// array yields its elements; `.jsonl` yields one per non-empty line; a
/// `.md` yields its raw text as ONE string value — the format adapter (e.g.
/// `rustsec-md`) owns interpreting it, so an `.md` globbed by a json-format
/// source is visible junk, not a silent parse error. Other extensions are
/// skipped by the glob, not here — reaching this with an unlisted type is a
/// hard error, not a silent drop.
fn parse_file(path: &Path, records_field: Option<&str>) -> Result<Vec<Value>> {
    let raw =
        std::fs::read_to_string(path).with_context(|| format!("cannot read {}", path.display()))?;
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_lowercase();
    let markdown = name.ends_with(".md") || name.ends_with(".markdown");
    let jsonl = name.ends_with(".jsonl") || name.ends_with(".ndjson");
    // `records_field` only means something for a wrapped `.json` catalog; on
    // any other file type it would be silently ignored, so refuse instead.
    if let (Some(field), true) = (records_field, markdown || jsonl) {
        bail!(
            "{}: records_field '{field}' applies only to .json files, not .md/.jsonl",
            path.display()
        );
    }
    if markdown {
        return Ok(vec![Value::String(raw)]);
    }
    if jsonl {
        let mut out = Vec::new();
        for (n, line) in raw.lines().enumerate() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let v: Value = serde_json::from_str(line)
                .with_context(|| format!("{}:{}: not valid JSON", path.display(), n + 1))?;
            out.push(v);
        }
        Ok(out)
    } else {
        let v: Value = serde_json::from_str(&raw)
            .with_context(|| format!("{}: not valid JSON", path.display()))?;
        if let Some(field) = records_field {
            let Value::Object(mut m) = v else {
                bail!(
                    "{}: records_field '{field}' requires a top-level JSON object",
                    path.display()
                );
            };
            let Some(Value::Array(a)) = m.remove(field) else {
                bail!(
                    "{}: records_field '{field}' missing or not a JSON array",
                    path.display()
                );
            };
            return Ok(a);
        }
        Ok(match v {
            Value::Array(a) => a,
            other => vec![other],
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn glob_matches_paths_like_a_recipe_expects() {
        let re = glob_regex("**/*.json");
        assert!(re.is_match("a.json"));
        assert!(re.is_match("deep/nested/a.json"));
        assert!(!re.is_match("a.jsonl"));
        assert!(!re.is_match("dir/sub")); // '.json' must be a suffix

        let re = glob_regex("osv/*.json");
        assert!(re.is_match("osv/x.json"));
        assert!(!re.is_match("osv/nested/x.json"), "* does not cross '/'");
        assert!(!re.is_match("other/x.json"));

        let re = glob_regex("**/GHSA-????.json");
        assert!(re.is_match("GHSA-1234.json"));
        assert!(!re.is_match("GHSA-12345.json"));
    }

    #[test]
    fn walk_is_sorted_and_relative() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("src");
        std::fs::create_dir_all(root.join("b")).unwrap();
        std::fs::create_dir_all(root.join("a")).unwrap();
        std::fs::write(root.join("b/second.json"), "{}").unwrap();
        std::fs::write(root.join("a/first.json"), "{}").unwrap();
        std::fs::write(root.join("a/note.txt"), "x").unwrap();
        let files = walk(&root, "**/*.json").unwrap();
        let rels: Vec<&str> = files.iter().map(|(r, _)| r.as_str()).collect();
        assert_eq!(rels, vec!["a/first.json", "b/second.json"]);
    }

    #[test]
    fn walk_refuses_a_missing_root_instead_of_pruning_everything() {
        // #1110 gap 1: a missing source root must fail the build, not walk to
        // zero files and let `prune` wipe the slug with a green exit.
        let tmp = tempfile::tempdir().unwrap();
        let missing = tmp.path().join("does-not-exist");
        let err = walk(&missing, "**/*.json").unwrap_err().to_string();
        assert!(err.contains("cannot be read"), "{err}");

        // an existing but empty directory is still fine — a legitimately
        // empty upstream prunes to zero on purpose.
        let empty = tmp.path().join("empty");
        std::fs::create_dir_all(&empty).unwrap();
        assert!(walk(&empty, "**/*.json").unwrap().is_empty());

        // a file where a directory is expected is also refused.
        let afile = tmp.path().join("a.json");
        std::fs::write(&afile, "{}").unwrap();
        let err = walk(&afile, "**/*.json").unwrap_err().to_string();
        assert!(err.contains("is not a directory"), "{err}");
    }

    /// `chmod` a path for the duration of the test, then put the previous
    /// mode back — including on panic — so the tempdir can be removed.
    #[cfg(unix)]
    struct RestoreMode {
        path: PathBuf,
        mode: u32,
    }

    #[cfg(unix)]
    impl RestoreMode {
        fn lock(path: &Path, mode: u32) -> Self {
            use std::os::unix::fs::PermissionsExt;
            let prev = std::fs::metadata(path).unwrap().permissions().mode();
            let mut perms = std::fs::metadata(path).unwrap().permissions();
            perms.set_mode(mode);
            std::fs::set_permissions(path, perms).unwrap();
            RestoreMode {
                path: path.to_path_buf(),
                mode: prev,
            }
        }
    }

    #[cfg(unix)]
    impl Drop for RestoreMode {
        fn drop(&mut self) {
            use std::os::unix::fs::PermissionsExt;
            if let Ok(meta) = std::fs::metadata(&self.path) {
                let mut perms = meta.permissions();
                perms.set_mode(self.mode);
                std::fs::set_permissions(&self.path, perms).ok();
            }
        }
    }

    #[cfg(unix)]
    #[test]
    fn walk_refuses_an_unreadable_root() {
        // #1110 gap 1, the read_dir half: metadata succeeding is not enough.
        // A directory that exists but cannot be listed (mode 000) used to
        // fall through `recurse`'s swallowed `read_dir` and come back as an
        // empty file list — the same silent prune as a typo'd path.
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("src");
        std::fs::create_dir_all(root.join("keep")).unwrap();
        std::fs::write(root.join("keep/a.json"), "{}").unwrap();
        let _restore = RestoreMode::lock(&root, 0o000);
        let err = walk(&root, "**/*.json").unwrap_err().to_string();
        assert!(
            err.contains("cannot be listed"),
            "unreadable root must fail the walk, not return no files: {err}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn walk_refuses_an_unreadable_subdirectory() {
        // A nested directory that cannot be listed must fail the walk too.
        // Skipping it would omit its files from the live key set and `prune`
        // would delete their envelopes as if upstream had removed them.
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("src");
        std::fs::create_dir_all(root.join("keep")).unwrap();
        std::fs::create_dir_all(root.join("secret")).unwrap();
        std::fs::write(root.join("keep/a.json"), "{}").unwrap();
        std::fs::write(root.join("secret/b.json"), "{}").unwrap();
        let _restore = RestoreMode::lock(&root.join("secret"), 0o000);
        let err = walk(&root, "**/*.json").unwrap_err().to_string();
        assert!(
            err.contains("cannot be listed"),
            "unreadable subdirectory must fail the walk: {err}"
        );
        assert!(
            err.contains("secret"),
            "the error must name the directory that could not be listed: {err}"
        );
    }

    #[test]
    fn parse_file_understands_json_and_jsonl() {
        let tmp = tempfile::tempdir().unwrap();
        let a = tmp.path().join("a.json");
        std::fs::write(&a, r#"[{"id":"x"},{"id":"y"}]"#).unwrap();
        assert_eq!(parse_file(&a, None).unwrap().len(), 2);
        let b = tmp.path().join("b.jsonl");
        std::fs::write(&b, "{\"id\":\"z\"}\n\n{\"id\":\"w\"}\n").unwrap();
        assert_eq!(
            parse_file(&b, None).unwrap().len(),
            2,
            "blank lines skipped"
        );
        let c = tmp.path().join("c.json");
        std::fs::write(&c, r#"{"id":"one"}"#).unwrap();
        assert_eq!(parse_file(&c, None).unwrap().len(), 1);
        let d = tmp.path().join("d.md");
        std::fs::write(&d, "```toml\n[advisory]\nid = \"R\"\n```\n\n# T\n").unwrap();
        let parsed = parse_file(&d, None).unwrap();
        assert_eq!(parsed.len(), 1, "one raw string value, not json-parsed");
        assert!(parsed[0].as_str().unwrap().starts_with("```toml"));
        let wrapped = tmp.path().join("wrapped.json");
        std::fs::write(
            &wrapped,
            r#"{"title":"KEV","vulnerabilities":[{"cveID":"CVE-1"},{"cveID":"CVE-2"}]}"#,
        )
        .unwrap();
        assert_eq!(
            parse_file(&wrapped, Some("vulnerabilities")).unwrap().len(),
            2
        );
        let err = parse_file(&wrapped, Some("missing"))
            .unwrap_err()
            .to_string();
        assert!(err.contains("missing or not a JSON array"), "{err}");
        let err = parse_file(&b, Some("vulnerabilities"))
            .unwrap_err()
            .to_string();
        assert!(err.contains("applies only to .json files"), "{err}");
        let err = parse_file(&d, Some("vulnerabilities"))
            .unwrap_err()
            .to_string();
        assert!(err.contains("applies only to .json files"), "{err}");
    }

    // ── end to end: recipe → harvest → identity → pack, twice ─────────────

    const E2E_RECIPE: &str = r#"
[recipe]
format = 1
name = "e2e"
description = "two sources, one alias-linked record"

[[sources]]
slug = "rustsec"
kind = "dir"
path = "data/rustsec"
format = "osv"
licence = "CC0-1.0"

[[sources]]
slug = "ghsa"
kind = "dir"
path = "data/ghsa"
glob = "**/*.jsonl"
format = "osv"
licence = "CC-BY-4.0"

[envelope]
id_from = ["id"]
title_from = ["summary", "id"]
body_join = ["summary", "details"]
defs_from = ["affected_functions"]

[identity]
edges = [{ field = "id" }, { field = "aliases", each = true }]
canonical_source_order = ["rustsec", "ghsa"]

[merge]
precedence = ["rustsec", "ghsa"]

[[derived]]
name = "cve_ids"
op = "regex_extract"
from = ["id", "aliases"]
pattern = '(?i)\bCVE-\d{4}-\d{4,}\b'
unique = true

[emit]
shards = 4
"#;

    fn e2e_env(home: &Path) {
        let root = home.join("recipes");
        std::fs::create_dir_all(root.join("data/rustsec")).unwrap();
        std::fs::create_dir_all(root.join("data/ghsa")).unwrap();
        std::fs::write(root.join("e2e.toml"), E2E_RECIPE).unwrap();
        std::fs::write(
            root.join("data/rustsec/RUSTSEC-2021-0003.json"),
            r#"{
                "id": "RUSTSEC-2021-0003",
                "aliases": ["CVE-2021-25900"],
                "summary": "Out of bounds write in SmallVec::insert_many",
                "details": "An issue was discovered that allows attackers...",
                "modified": "2023-06-20T00:00:00Z",
                "affected": [{
                    "package": {"ecosystem": "crates.io", "name": "smallvec"},
                    "ranges": [{"type": "SEMVER", "events": [{"introduced": "0"}, {"fixed": "0.6.14"}]}]
                }],
                "ecosystem_specific": {"affects": {"functions": {"smallvec::SmallVec::insert_many": ["<0.6.14"]}}}
            }"#,
        )
        .unwrap();
        // second rustsec record with NO alias link: its own cluster
        std::fs::write(
            root.join("data/rustsec/RUSTSEC-2020-0001.json"),
            r#"{"id": "RUSTSEC-2020-0001", "summary": "other issue"}"#,
        )
        .unwrap();
        // same logical record, GHSA shape: split ranges, no functions
        std::fs::write(
            root.join("data/ghsa/reviewed.jsonl"),
            concat!(
                r#"{"id": "GHSA-43w2-9j62-hq99", "aliases": ["CVE-2021-25900"], "summary": "Out of bounds write in insert_many", "modified": "2025-01-02T00:00:00Z", "affected": [{"package": {"ecosystem": "crates.io", "name": "smallvec"}, "ranges": [{"type": "SEMVER", "events": [{"introduced": "1.0.0"}, {"fixed": "1.6.1"}]}]}]}"#,
                "\n",
            ),
        )
        .unwrap();
    }

    fn read_records(pack: &Path) -> Vec<Map<String, Value>> {
        let manifest: Value =
            serde_json::from_str(&std::fs::read_to_string(pack.join("manifest.json")).unwrap())
                .unwrap();
        let mut out = Vec::new();
        for name in manifest["files"].as_object().unwrap().keys() {
            for line in std::fs::read_to_string(pack.join(name)).unwrap().lines() {
                out.push(serde_json::from_str(line).unwrap());
            }
        }
        out.sort_by_key(|r: &Map<String, Value>| {
            r.get("id")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string()
        });
        out
    }

    #[test]
    fn build_end_to_end_and_incrementally() {
        let home = tempfile::tempdir().unwrap();
        e2e_env(home.path());

        let args: Vec<String> = vec!["e2e".to_string()];
        assert_eq!(run_build_inner(&args, home.path()).unwrap(), 0);

        let pack = home.path().join("builds/e2e/pack/e2e");
        let records = read_records(&pack);
        assert_eq!(
            records.len(),
            2,
            "GHSA+RUSTSEC merge via CVE alias; RUSTSEC-2020-0001 alone"
        );

        let merged = records
            .iter()
            .find(|r| r["id"] == json!("RUSTSEC-2021-0003"))
            .expect("precedence-first source names the id");
        assert_eq!(merged["sources"], json!(["rustsec", "ghsa"]));
        assert_eq!(merged["source"], json!("rustsec"));
        assert_eq!(
            merged["title"],
            json!("Out of bounds write in SmallVec::insert_many")
        );
        assert_eq!(
            merged["defs"],
            json!("smallvec::SmallVec::insert_many"),
            "rustsec-only field still feeds xerj code"
        );
        assert_eq!(
            merged["fixed_versions"],
            json!(["0.6.14", "1.6.1"]),
            "split GHSA range unions with the packed RustSec one"
        );
        assert_eq!(
            merged["modified"],
            json!("2025-01-02T00:00:00Z"),
            "max across members"
        );
        assert_eq!(
            merged["licence"],
            json!("CC0-1.0"),
            "neither is restricted; precedence first"
        );
        assert_eq!(
            merged["cve_ids"],
            json!(["CVE-2021-25900"]),
            "derived over the merged record"
        );

        // uniform keys: the GHSA-less record still carries every key
        let lone = records
            .iter()
            .find(|r| r["id"] == json!("RUSTSEC-2020-0001"))
            .unwrap();
        assert_eq!(lone["sources"], json!(["rustsec"]));
        assert_eq!(lone["fixed_versions"], json!([]), "array key fills empty");
        assert_eq!(lone["cve_ids"], json!([]));
        assert_eq!(lone["affected_functions"], json!([]));
        assert_eq!(lone["modified"], json!(""));

        // manifest structure + checksums
        let manifest: Value =
            serde_json::from_str(&std::fs::read_to_string(pack.join("manifest.json")).unwrap())
                .unwrap();
        assert_eq!(manifest["format_version"], json!(1));
        assert_eq!(manifest["kind"], json!("harvested"));
        assert_eq!(manifest["generation"], json!(1));
        assert_eq!(manifest["counts"]["records"], json!(2));
        assert_eq!(
            manifest["description"],
            json!("two sources, one alias-linked record")
        );
        let rs = &manifest["sources"][0];
        assert_eq!(rs["slug"], json!("rustsec"));
        assert_eq!(rs["new"], json!(2));
        assert_eq!(rs["skipped"], json!(0));
        assert!(manifest["recipe_sha256"]
            .as_str()
            .is_some_and(|s| s.len() == 64));
        assert!(pack.join("recipe.toml").is_file(), "recipe ships verbatim");

        // suggestion artifacts: shipped, checksum-covered, and honest about
        // the alias pair this recipe encodes
        let sums = std::fs::read_to_string(pack.join("SHA256SUMS")).unwrap();
        for f in [
            "mapping.suggested.json",
            "relations.jsonl",
            "suggestions.md",
        ] {
            assert!(pack.join(f).is_file(), "{f} ships");
            assert!(sums.contains(&format!("  {f}\n")), "{f} checksum-covered");
        }
        let mapping: Value = serde_json::from_str(
            &std::fs::read_to_string(pack.join("mapping.suggested.json")).unwrap(),
        )
        .unwrap();
        assert_eq!(mapping["total_records"], json!(2));
        assert_eq!(mapping["sampled_records"], json!(2));
        assert!(mapping["es_mapping"]["properties"]["id"]["type"].is_string());
        let rels: Vec<Value> = std::fs::read_to_string(pack.join("relations.jsonl"))
            .unwrap()
            .lines()
            .filter(|l| !l.trim().is_empty())
            .map(|l| serde_json::from_str(l).unwrap())
            .collect();
        let alias = rels
            .iter()
            .find(|r| {
                (r["left"] == json!("aliases") && r["right"] == json!("cve_ids"))
                    || (r["left"] == json!("cve_ids") && r["right"] == json!("aliases"))
            })
            .expect("aliases ↔ cve_ids discovered from the data itself");
        assert_eq!(alias["grammar"], json!("cve"));
        assert_eq!(alias["cardinality"], json!("many-to-many"));
        assert!(alias["overlap"]
            .as_array()
            .is_some_and(|o| o.contains(&json!("CVE-2021-25900"))));
        let md = std::fs::read_to_string(pack.join("suggestions.md")).unwrap();
        assert!(md.contains("Suggestions, not decisions"), "{md}");

        // ── second run: nothing new, shards byte-identical, generation up ──
        let before: Vec<(String, Vec<u8>)> = std::fs::read_dir(&pack)
            .unwrap()
            .flatten()
            .map(|e| {
                (
                    e.file_name().to_string_lossy().to_string(),
                    std::fs::read(e.path()).unwrap(),
                )
            })
            .filter(|(n, _)| {
                n.starts_with("records-")
                    || n == "mapping.suggested.json"
                    || n == "relations.jsonl"
                    || n == "suggestions.md"
            })
            .collect();
        assert_eq!(run_build_inner(&args, home.path()).unwrap(), 0);
        let manifest: Value =
            serde_json::from_str(&std::fs::read_to_string(pack.join("manifest.json")).unwrap())
                .unwrap();
        assert_eq!(
            manifest["generation"],
            json!(2),
            "rebuild advances generation"
        );
        for s in manifest["sources"].as_array().unwrap() {
            assert_eq!(
                s["new"],
                json!(0),
                "content-addressed store skipped everything"
            );
            assert_eq!(s["skipped"], json!(s["records"]));
            assert_eq!(s["pruned"], json!(0));
        }
        for (name, bytes) in before {
            assert_eq!(
                std::fs::read(pack.join(&name)).unwrap(),
                bytes,
                "{name} byte-identical"
            );
        }

        // ── third run after deleting an upstream file: prune removes it ────
        std::fs::remove_file(
            home.path()
                .join("recipes/data/rustsec/RUSTSEC-2020-0001.json"),
        )
        .unwrap();
        assert_eq!(run_build_inner(&args, home.path()).unwrap(), 0);
        let manifest: Value =
            serde_json::from_str(&std::fs::read_to_string(pack.join("manifest.json")).unwrap())
                .unwrap();
        assert_eq!(
            manifest["sources"][0]["pruned"],
            json!(1),
            "dead envelope pruned"
        );
        assert_eq!(read_records(&pack).len(), 1);

        // ── fourth run with --fresh: wipes build dir, resets generation ────
        let fresh_args: Vec<String> = vec!["e2e".to_string(), "--fresh".to_string()];
        assert_eq!(run_build_inner(&fresh_args, home.path()).unwrap(), 0);
        let manifest: Value =
            serde_json::from_str(&std::fs::read_to_string(pack.join("manifest.json")).unwrap())
                .unwrap();
        assert_eq!(
            manifest["generation"],
            json!(1),
            "--fresh wipes previous build dir and resets generation to 1"
        );
        for s in manifest["sources"].as_array().unwrap() {
            assert_eq!(s["skipped"], json!(0), "--fresh re-harvests from scratch");
            assert_eq!(s["new"], s["records"]);
        }
    }

    fn store_files(home: &Path, build: &str, prefix: &str) -> Vec<String> {
        let store = home.join("builds").join(build).join("store");
        let mut names: Vec<String> = std::fs::read_dir(&store)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().to_string())
            .filter(|n| n.starts_with(prefix))
            .collect();
        names.sort();
        names
    }

    fn pack_generation(home: &Path, build: &str) -> u64 {
        let manifest: Value = serde_json::from_str(
            &std::fs::read_to_string(
                home.join("builds")
                    .join(build)
                    .join("pack")
                    .join(build)
                    .join("manifest.json"),
            )
            .unwrap(),
        )
        .unwrap();
        manifest["generation"].as_u64().unwrap()
    }

    #[test]
    fn missing_source_root_fails_the_build_and_does_not_prune() {
        // #1110 gap 1 at the pipeline: a typo'd `dir` path must exit as an
        // error AND leave the previously stored envelopes on disk. `walk`
        // failing is not enough if `prune` already ran.
        let home = tempfile::tempdir().unwrap();
        e2e_env(home.path());
        let args: Vec<String> = vec!["e2e".to_string()];
        assert_eq!(run_build_inner(&args, home.path()).unwrap(), 0);
        let before = store_files(home.path(), "e2e", "rustsec.");
        assert_eq!(before.len(), 2, "two rustsec envelopes stored");
        let gen = pack_generation(home.path(), "e2e");

        std::fs::rename(
            home.path().join("recipes/data/rustsec"),
            home.path().join("recipes/data/rustsec-moved"),
        )
        .unwrap();
        let err = run_build_inner(&args, home.path()).unwrap_err().to_string();
        assert!(
            err.contains("cannot be read"),
            "missing source root must fail the build: {err}"
        );
        assert_eq!(
            store_files(home.path(), "e2e", "rustsec."),
            before,
            "a failed walk must not prune the slug's envelopes"
        );
        assert_eq!(
            pack_generation(home.path(), "e2e"),
            gen,
            "a failed walk must not publish a new generation"
        );
    }

