#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawRecipe {
    recipe: RawHeader,
    #[serde(default)]
    envelope: RawEnvelope,
    sources: Vec<RawSource>,
    identity: RawIdentity,
    #[serde(default)]
    merge: RawMerge,
    #[serde(default)]
    derived: Vec<RawDerived>,
    #[serde(default)]
    emit: RawEmit,
    #[serde(default)]
    suggest: RawSuggest,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawHeader {
    format: u32,
    name: String,
    #[serde(default)]
    description: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawEnvelope {
    #[serde(default = "d_id_from")]
    id_from: Vec<String>,
    #[serde(default = "d_title_from")]
    title_from: Vec<String>,
    #[serde(default)]
    body_join: Vec<String>,
    #[serde(default)]
    defs_from: Vec<String>,
    #[serde(default = "d_true")]
    passthrough: bool,
}

// `#[serde(default)]` on the whole-table fields in RawRecipe falls back to
// `Default::default()` when the table is absent — which would silently zero
// these. The manual impls keep absent-table defaults equal to field defaults.
impl Default for RawEnvelope {
    fn default() -> Self {
        RawEnvelope {
            id_from: d_id_from(),
            title_from: d_title_from(),
            body_join: Vec::new(),
            defs_from: Vec::new(),
            passthrough: d_true(),
        }
    }
}

fn d_id_from() -> Vec<String> {
    vec!["id".to_string()]
}
fn d_title_from() -> Vec<String> {
    vec!["id".to_string()]
}
fn d_true() -> bool {
    true
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawSource {
    slug: String,
    kind: String,
    #[serde(default)]
    path: Option<String>,
    #[serde(default)]
    url: Option<String>,
    #[serde(default)]
    rev: Option<String>,
    #[serde(default = "d_glob")]
    glob: String,
    #[serde(default)]
    records_field: Option<String>,
    format: String,
    #[serde(default)]
    licence: String,
}

fn d_glob() -> String {
    "**/*.json".to_string()
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawIdentity {
    edges: Vec<RawEdge>,
    #[serde(default)]
    canonical_source_order: Vec<String>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawEdge {
    field: String,
    #[serde(default)]
    each: bool,
}

#[derive(Deserialize, Default)]
#[serde(deny_unknown_fields)]
struct RawMerge {
