#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawEmit {
    #[serde(default = "d_shards")]
    shards: usize,
}

impl Default for RawEmit {
    fn default() -> Self {
        RawEmit { shards: d_shards() }
    }
}

fn d_shards() -> usize {
    16
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawSuggest {
    #[serde(default = "d_sample")]
    sample: usize,
}

// absent `[suggest]` table = field defaults, not Default::default() zero —
// the same trap RawEnvelope's manual impl documents.
impl Default for RawSuggest {
    fn default() -> Self {
        RawSuggest { sample: d_sample() }
    }
}

fn d_sample() -> usize {
    512
}

// ── load + validate + compile ───────────────────────────────────────────────

/// A slug becomes a filename component in the content store
/// (`<slug>.<key>.json`), so it is gated to a safe charset the way corpus
/// and repo names are — but locally, because slugs are a builder concept.
fn valid_slug(slug: &str) -> Result<()> {
    let ok = !slug.is_empty()
        && slug.len() <= 64
        && slug
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '.')
        && !slug.starts_with('.');
    if !ok {
        bail!("source slug '{slug}' must be 1-64 chars of [A-Za-z0-9._-], not starting with '.'");
    }
    Ok(())
}

/// Read, validate and compile a recipe. Every error names the file and the
/// offending key — a recipe that fails here must never half-run.
pub fn load(path: &Path) -> Result<Recipe> {
    let raw = std::fs::read_to_string(path)
        .with_context(|| format!("cannot read recipe {}", path.display()))?;
    let file: RawRecipe = toml::from_str(&raw).map_err(|e| {
        // the toml error names the unknown key/line — keep it in the message
        anyhow::anyhow!("{}: recipe parse error: {e}", path.display())
    })?;
    compile(path, file)
}

fn compile(path: &Path, file: RawRecipe) -> Result<Recipe> {
    let at = |what: &str| format!("{}: {}", path.display(), what);

    if file.recipe.format != 1 {
        bail!(at(&format!(
            "recipe format {} is not supported by this build (supported: 1)",
            file.recipe.format
        )));
    }
    let name = file.recipe.name.trim().to_string();
    if let Err(e) = xerj_common::xccode::pathgate::valid_corpus_name(&name) {
        bail!(at(&format!("recipe name '{name}': {e}")));
    }

    if file.sources.is_empty() {
        bail!(at("recipe declares no [[sources]]"));
    }
    let mut slugs: Vec<&str> = Vec::new();
    let mut sources = Vec::new();
    for s in &file.sources {
        valid_slug(&s.slug).with_context(|| at(&format!("source '{}'", s.slug)))?;
        if slugs.contains(&s.slug.as_str()) {
            bail!(at(&format!("duplicate source slug '{}'", s.slug)));
        }
        let kind = match s.kind.as_str() {
            "dir" => SourceKind::Dir,
            "http-zip" => SourceKind::HttpZip,
            "http-json" => SourceKind::HttpJson,
            "git" => SourceKind::Git,
            other => bail!(at(&format!(
                "source '{}': unknown kind '{other}' (supported: dir, http-zip, http-json, git)",
                s.slug
            ))),
        };
        let format = match s.format.as_str() {
            "osv" => Format::Osv,
            "rustsec-md" => Format::RustsecMd,
            "flat" => Format::Flat,
            other => bail!(at(&format!(
                "source '{}': unknown format '{other}' (supported: osv, rustsec-md, flat)",
                s.slug
            ))),
        };
        if let Some(rf) = &s.records_field {
            if rf.trim().is_empty() {
                bail!(at(&format!(
                    "source '{}': 'records_field' cannot be empty",
                    s.slug
                )));
            }
        }
        let url = s.url.as_deref().unwrap_or_default().to_string();
        let rev = s.rev.as_deref().unwrap_or_default().to_string();
        match kind {
            SourceKind::Dir => {
                if s.path.as_deref().unwrap_or("").is_empty() {
                    bail!(at(&format!(
                        "dir source '{}' needs a 'path' (relative to the recipe file)",
                        s.slug
                    )));
                }
                if let Some(p) = &s.path {
                    if Path::new(p).is_absolute() {
                        bail!(at(&format!(
                            "dir source '{}' path must be recipe-relative, got absolute '{p}'",
                            s.slug
                        )));
                    }
                }
                if !url.is_empty() || !rev.is_empty() {
                    bail!(at(&format!(
                        "dir source '{}' takes 'path', not 'url'/'rev'",
                        s.slug
                    )));
                }
            }
            SourceKind::HttpZip | SourceKind::HttpJson => {
                let kind_str = if kind == SourceKind::HttpZip {
                    "http-zip"
                } else {
                    "http-json"
                };
                if !url.starts_with("http://") && !url.starts_with("https://") {
                    bail!(at(&format!(
                        "{kind_str} source '{}' needs an http(s) 'url', got '{url}'",
                        s.slug
                    )));
                }
                if s.path.is_some() || !rev.is_empty() {
                    bail!(at(&format!(
                        "{kind_str} source '{}' takes 'url' only — no 'path'/'rev'",
                        s.slug
                    )));
                }
            }
            SourceKind::Git => {
                if url.is_empty() {
                    bail!(at(&format!(
                        "git source '{}' needs a 'url' (a git URL or local path)",
                        s.slug
                    )));
                }
                if s.path.is_some() {
                    bail!(at(&format!(
                        "git source '{}' takes 'url' (+optional 'rev'), not 'path'",
                        s.slug
                    )));
                }
            }
        }
        slugs.push(&s.slug);
        sources.push(SourceSpec {
            slug: s.slug.clone(),
            kind,
            path: s.path.clone(),
            url: s.url.clone(),
            rev: if rev.is_empty() { None } else { Some(rev) },
            glob: s.glob.clone(),
            records_field: s.records_field.clone(),
            format,
            licence: s.licence.clone(),
        });
    }

    if file.identity.edges.is_empty() {
        bail!(at(
            "[identity] declares no edges: without identity edges every record is its \
             own cluster and nothing deduplicates"
        ));
    }
    let edges = file
        .identity
        .edges
        .iter()
        .map(|e| IdentityEdge {
            field: e.field.clone(),
            each: e.each,
        })
        .collect();

    let known = |s: &str| slugs.contains(&s);
    for s in &file.identity.canonical_source_order {
        if !known(s) {
            bail!(at(&format!(
                "identity.canonical_source_order names source '{s}' which the recipe \
                 does not declare"
            )));
        }
    }
    for s in &file.merge.precedence {
        if !known(s) {
            bail!(at(&format!(
                "merge.precedence names source '{s}' which the recipe does not declare"
            )));
        }
    }
    for (field, order) in &file.merge.field_precedence {
        for s in order {
            if !known(s) {
                bail!(at(&format!(
                    "merge.field_precedence.{field} names source '{s}' which the recipe \
                     does not declare"
                )));
            }
        }
    }

    let mut derived = Vec::new();
    for d in &file.derived {
        if RESERVED_KEYS.contains(&d.name.as_str()) {
            bail!(at(&format!(
                "derived field '{}' collides with a reserved envelope key",
                d.name
            )));
        }
        let op = match d.op.as_str() {
            "regex_extract" => {
                let pattern = d.pattern.as_deref().unwrap_or("");
                if pattern.is_empty() {
                    bail!(at(&format!(
                        "derived '{}': regex_extract needs a 'pattern'",
                        d.name
                    )));
                }
                if d.from.is_empty() {
                    bail!(at(&format!(
                        "derived '{}': regex_extract needs a 'from' list",
                        d.name
                    )));
                }
                let re = Regex::new(pattern)
                    .with_context(|| at(&format!("derived '{}': bad regex /{pattern}/", d.name)))?;
                DerivedOp::RegexExtract {
                    from: d.from.clone(),
                    re,
                    unique: d.unique,
                }
            }
            "map" => {
                if d.from.len() != 1 {
                    bail!(at(&format!(
                        "derived '{}': map needs exactly one 'from' field",
                        d.name
                    )));
                }
                if d.rules.is_empty() {
                    bail!(at(&format!(
                        "derived '{}': map needs at least one rule",
                        d.name
                    )));
                }
                let mut rules = Vec::new();
                for r in &d.rules {
                    let re = Regex::new(&r.r#match).with_context(|| {
                        at(&format!(
                            "derived '{}': bad rule regex /{}/",
                            d.name, r.r#match
                        ))
                    })?;
                    rules.push((re, r.value.clone()));
                }
                DerivedOp::Map {
                    from: d.from[0].clone(),
                    rules,
                    default: d.default.clone().unwrap_or_default(),
                }
            }
            "present" => {
                if d.from.len() != 1 {
                    bail!(at(&format!(
                        "derived '{}': present needs exactly one 'from' field",
                        d.name
                    )));
                }
                DerivedOp::Present {
                    from: d.from[0].clone(),
                }
            }
            other => bail!(at(&format!(
                "derived '{}': unknown op '{other}' (supported: regex_extract, map, present)",
                d.name
            ))),
        };
        derived.push(Derived {
            name: d.name.clone(),
            op,
        });
    }

    if file.emit.shards == 0 || file.emit.shards > 4096 {
        bail!(at(&format!(
            "emit.shards must be 1..=4096, got {}",
            file.emit.shards
        )));
    }
    if file.suggest.sample < 16 || file.suggest.sample > 100_000 {
        bail!(at(&format!(
            "suggest.sample must be 16..=100000, got {}",
            file.suggest.sample
        )));
    }

    Ok(Recipe {
        name,
        description: file.recipe.description,
        envelope: Envelope {
            id_from: file.envelope.id_from,
            title_from: file.envelope.title_from,
            body_join: file.envelope.body_join,
            defs_from: file.envelope.defs_from,
            passthrough: file.envelope.passthrough,
        },
        sources,
        identity: Identity {
            edges,
            canonical_source_order: file.identity.canonical_source_order,
        },
        merge: file.merge.into_recipe(),
        derived,
        emit: Emit {
            shards: file.emit.shards,
        },
        suggest: Suggest {
            sample: file.suggest.sample,
        },
    })
}

impl RawMerge {
    fn into_recipe(self) -> Merge {
        Merge {
            precedence: self.precedence,
            field_precedence: self.field_precedence,
        }
    }
}

/// Rank of a source slug under an order list (absent = last). Members of a
/// cluster are sorted by this before any first-wins merge decision, so the
/// order list — not filesystem accident — decides whose value wins.
pub fn slug_rank(order: &[String], slug: &str) -> usize {
    order
        .iter()
        .position(|s| s == slug)
        .unwrap_or(order.len() + 1)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn write(tmp: &std::path::Path, body: &str) -> std::path::PathBuf {
        let p = tmp.join("recipe.toml");
        std::fs::write(&p, body).unwrap();
        p
    }

    const MINIMAL: &str = r#"
[recipe]
format = 1
name = "demo"

[[sources]]
slug = "a"
kind = "dir"
path = "data/a"
format = "flat"

[identity]
edges = [{ field = "id" }]
"#;

    #[test]
    fn minimal_recipe_loads_with_defaults() {
        let tmp = tempfile::tempdir().unwrap();
        let r = load(&write(tmp.path(), MINIMAL)).unwrap();
        assert_eq!(r.name, "demo");
        assert_eq!(r.envelope.id_from, vec!["id".to_string()]);
        assert!(r.envelope.passthrough);
        assert_eq!(r.emit.shards, 16);
        assert_eq!(
            r.suggest.sample, 512,
            "absent [suggest] table = field default"
        );
        assert_eq!(r.sources[0].glob, "**/*.json");
    }

    #[test]
    fn suggest_sample_bounds_are_enforced() {
        let tmp = tempfile::tempdir().unwrap();
        for bad in ["8", "200000"] {
            let r = MINIMAL.replace(
                "[identity]",
                &format!("[suggest]\nsample = {bad}\n\n[identity]"),
            );
            let err = load(&write(tmp.path(), &r)).unwrap_err().to_string();
            assert!(err.contains("suggest.sample"), "{err}");
        }
        let ok = MINIMAL.replace("[identity]", "[suggest]\nsample = 64\n\n[identity]");
        assert_eq!(load(&write(tmp.path(), &ok)).unwrap().suggest.sample, 64);
    }

    #[test]
    fn unknown_keys_are_loud() {
        let tmp = tempfile::tempdir().unwrap();
        let bad = MINIMAL.replace("format = \"flat\"", "format = \"flat\"\nbogus_key = 1");
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("bogus_key"), "{err}");
    }

    #[test]
    fn unknown_source_kind_is_loud() {
        let tmp = tempfile::tempdir().unwrap();
        let bad = MINIMAL.replace("kind = \"dir\"", "kind = \"svn\"");
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("unknown kind 'svn'"), "{err}");
    }

    #[test]
    fn network_kinds_validate_their_targets() {
        let tmp = tempfile::tempdir().unwrap();
        // http-zip without an http(s) url
        let bad = MINIMAL.replace(
            "kind = \"dir\"\npath = \"data/a\"",
            "kind = \"http-zip\"\nurl = \"ftp://x/y.zip\"",
        );
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("http(s) 'url'"), "{err}");
        // git with a stray path
        let bad = MINIMAL.replace("kind = \"dir\"", "kind = \"git\"\nurl = \"https://x/y\"");
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("not 'path'"), "{err}");
        // dir with a url
        let bad = MINIMAL.replace(
            "path = \"data/a\"",
            "path = \"data/a\"\nurl = \"https://x/y\"",
        );
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("not 'url'/'rev'"), "{err}");
    }

    #[test]
    fn identity_edges_are_mandatory() {
        let tmp = tempfile::tempdir().unwrap();
        let bad = MINIMAL.replace("edges = [{ field = \"id\" }]", "edges = []");
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("declares no edges"), "{err}");
    }

    #[test]
    fn precedence_must_name_declared_sources() {
        let tmp = tempfile::tempdir().unwrap();
        let bad = MINIMAL.replace(
            "[identity]",
            "[merge]\nprecedence = [\"nope\"]\n\n[identity]",
        );
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("'nope'"), "{err}");
    }

    #[test]
    fn derived_name_may_not_clobber_the_envelope() {
        let tmp = tempfile::tempdir().unwrap();
        let bad =
            format!("{MINIMAL}\n[[derived]]\nname = \"title\"\nop = \"present\"\nfrom = [\"x\"]\n");
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("reserved envelope key"), "{err}");
    }

    #[test]
    fn bad_regex_is_rejected_at_load_not_at_build() {
        let tmp = tempfile::tempdir().unwrap();
        let bad = format!(
            "{MINIMAL}\n[[derived]]\nname = \"cves\"\nop = \"regex_extract\"\nfrom = \
             [\"id\"]\npattern = \"([unclosed\"\n"
        );
        let err = load(&write(tmp.path(), &bad)).unwrap_err().to_string();
        assert!(err.contains("bad regex"), "{err}");
    }

    #[test]
    fn slugs_are_path_safe() {
        assert!(valid_slug("rustsec").is_ok());
        assert!(valid_slug("osv-crates-io").is_ok());
        assert!(valid_slug("../escape").is_err());
        assert!(valid_slug(".hidden").is_err());
        assert!(valid_slug("").is_err());
    }
}

//! Detached ed25519 signatures over a pack's SHA256SUMS — the publish half
//! of the pack format.
//!
//! Checksums (M1) prove a pack arrived intact; a signature proves WHO built
//! it. That distinction is the whole design: SHA256SUMS re-hashing catches
//! corruption and lazy tampering, but an attacker who rebuilds a pack
//! self-consistently produces valid checksums for malicious records — the
//! case `read_manifest`'s tests explicitly left to "a later milestone",
//! which is this file. Every prior-art vulnerability database surveyed at
//! design time (Trivy DB, Grype/vunnel, PrimeVul) ships unsigned; this is
//! the open lane, not table stakes.
//!
//! The trust model, stated plainly:
//!
//! - The **public** key travels out of band — committed next to the pack
//!   recipe in this repo, and on xerj.org — never inside the pack (a key
//!   shipped beside its own signature verifies nothing).
//! - The **seed** lives only in CI's secrets; `corpus build` never sees it.
//!   Signing is a separate `corpus sign` step so a local build and a
//!   published build differ by exactly one file.
//! - v1 is a single release key. Rotation is by re-publishing under a new
//!   key and updating the two public locations; consumers pin the file they
//!   fetched, and the README says so.
//!
//! Format, deliberately boring: `SHA256SUMS.sig` is the RAW 64-byte ed25519
//! signature of SHA256SUMS' exact bytes. No armored envelopes, no trusted
//! comments — a consumer with any ed25519 implementation can verify the
//! bytes without this crate. The `.sig` file is intentionally absent from
//! SHA256SUMS itself (it signs that file; covering it would be circular) —
//! `read_manifest` only re-hashes files the SUMS names, so the signature
//! rides in a pack dir or zip without breaking older readers.

use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use ring::rand::SecureRandom;
use ring::signature::{Ed25519KeyPair, KeyPair, UnparsedPublicKey};

/// The signature file name inside a pack directory.
pub const SIG_NAME: &str = "SHA256SUMS.sig";

/// Generate a fresh ed25519 keypair as (seed_hex, public_hex) — 32 bytes
/// each, lower-case hex. The seed is everything an attacker needs: it goes
/// to CI secrets and nowhere else; the public half is published.
pub fn generate_keypair() -> Result<(String, String)> {
    let mut seed = [0u8; 32];
    ring::rand::SystemRandom::new()
        .fill(&mut seed)
        .map_err(|_| anyhow::anyhow!("key generation failed (no entropy source?)"))?;
    let pair = Ed25519KeyPair::from_seed_unchecked(&seed)
        .map_err(|_| anyhow::anyhow!("a fresh 32-byte seed is always valid — ring disagrees"))?;
    Ok((hex(&seed), hex(pair.public_key().as_ref())))
}

/// Sign `<pack>/SHA256SUMS` with a seed file, writing `<pack>/SHA256SUMS.sig`.
/// Refuses to sign a pack whose SUMS is missing (nothing to sign) and
/// overwrites a previous `.sig` — re-signing a rebuilt pack is the normal
/// publish step, and a stale signature would fail verification anyway.
pub fn sign_pack(pack_dir: &Path, seed_hex: &str) -> Result<()> {
    let sums = pack_dir.join("SHA256SUMS");
    let msg = std::fs::read(&sums).with_context(|| format!("read {}", sums.display()))?;
    let seed = parse_key(seed_hex, 32, "seed")?;
    let pair = Ed25519KeyPair::from_seed_unchecked(&seed)
        .map_err(|_| anyhow::anyhow!("seed is not a valid ed25519 key"))?;
    let sig = pair.sign(&msg);
    let out = pack_dir.join(SIG_NAME);
    std::fs::write(&out, sig.as_ref()).with_context(|| format!("write {}", out.display()))?;
    println!(
        "signed {} ({} byte signature over SHA256SUMS)",
        out.display(),
        sig.as_ref().len()
    );
    Ok(())
}

/// Verify `<pack>/SHA256SUMS.sig` against a public-key file. The signature
/// chain is: sig → SHA256SUMS → every file the SUMS names, so verifying here
/// plus `read_manifest`'s re-hashing proves both integrity and origin.
/// `verify_pack` is called BEFORE the pack is materialized, so a failure
/// means nothing was indexed.
pub fn verify_pack(pack_dir: &Path, public_hex: &str) -> Result<()> {
    verify_sig_at(pack_dir, &pack_dir.join(SIG_NAME), public_hex)
}

/// Same verification with an explicit signature path — `corpus add --from
/// <pack.zip>` uses this with the LOOSE signature a release ships beside the
/// zip: the sig is never packed inside the zip (it is deliberately absent
/// from the SUMS it signs, and the signing step runs after the zip is
/// built), so a zip consumer's signature lives in a sibling file.
pub fn verify_sig_at(pack_dir: &Path, sig_path: &Path, public_hex: &str) -> Result<()> {
    let at = |what: &str| format!("{}: {what}", pack_dir.display());
    let sig = std::fs::read(sig_path).with_context(|| at("no SHA256SUMS.sig to verify"))?;
    if sig.len() != 64 {
        bail!(at(&format!(
            "{SIG_NAME} is {} bytes, expected a 64-byte ed25519 signature",
            sig.len()
        )));
    }
    let public = parse_key(public_hex, 32, "public key")?;
    let msg =
        std::fs::read(pack_dir.join("SHA256SUMS")).with_context(|| at("cannot read SHA256SUMS"))?;
    let key = UnparsedPublicKey::new(&ring::signature::ED25519, &public);
    key.verify(&msg, &sig).map_err(|_| {
        anyhow::anyhow!(at(
            "signature does not verify — the pack is not from the holder of the expected key, \
                 or SHA256SUMS changed after signing"
        ))
    })?;
    Ok(())
}

/// True when the pack dir carries a signature file (the `corpus add` hint:
/// "this pack is signed; pass --verify-sig" — presence is public metadata,
/// verification is the consumer's explicit choice).
pub fn pack_is_signed(pack_dir: &Path) -> bool {
    pack_dir.join(SIG_NAME).is_file()
}

/// Raw ed25519 signature (64 bytes, hex) of `bytes`, for the hub pack archive
/// where the signature is a separate file next to the archive. Same key format
/// and primitive as `sign_pack`; the only difference is the message is the
/// caller's buffer (the archive bytes) rather than a SHA256SUMS file, and the
/// output is hex so it can ride in a sibling text file.
pub fn sign_bytes(bytes: &[u8], seed_hex: &str) -> Result<String> {
    let seed = parse_key(seed_hex, 32, "seed")?;
    let pair = Ed25519KeyPair::from_seed_unchecked(&seed)
        .map_err(|_| anyhow::anyhow!("seed is not a valid ed25519 key"))?;
    let sig = pair.sign(bytes);
    Ok(hex(sig.as_ref()))
}

/// Verify a hex ed25519 signature of `bytes` against a hex public key. Mirrors
/// `verify_sig_at`'s `UnparsedPublicKey` check; returns `Ok(())` on a good
/// signature and an `Err` otherwise. The signature is the 64 raw bytes as hex
/// (128 chars) that `sign_bytes` produced.
pub fn verify_bytes(bytes: &[u8], sig_hex: &str, public_hex: &str) -> Result<()> {
    let sig = parse_key(sig_hex, 64, "signature")?;
    let public = parse_key(public_hex, 32, "public key")?;
    let key = UnparsedPublicKey::new(&ring::signature::ED25519, &public);
    key.verify(bytes, &sig).map_err(|_| {
        anyhow::anyhow!(
            "signature does not verify — the archive is not from the holder of the expected key, \
             or the bytes changed after signing"
        )
    })?;
    Ok(())
}

// ── CLI: `xerj corpus keygen`, `xerj corpus sign` ───────────────────────────

const KEYGEN_USAGE: &str = "usage: xerj corpus keygen --out <prefix>

writes <prefix>.key (the 32-byte ed25519 seed, hex — SECRET) and <prefix>.pub
(the verifying key, hex — publish this). Keep the .key out of the repo and out
of logs; it goes to CI secrets and nowhere else.";

const SIGN_USAGE: &str = "usage: xerj corpus sign <pack-dir> --key <seed-file>

writes <pack-dir>/SHA256SUMS.sig, a detached ed25519 signature over the pack's
SHA256SUMS (which covers every pack file). Re-signing overwrites. The pack's
checksums stay untouched — signing is a publish step, never a rebuild.";

/// Entry point for `xerj corpus keygen|sign <args>` from the dispatcher.
pub fn run_sign_cli(sub: &str, args: &[String]) -> i32 {
    match sub {
        "keygen" => run_keygen(args),
        "sign" => run_sign(args),
        _ => unreachable!("dispatcher routes only keygen|sign here"),
    }
}

fn run_keygen(args: &[String]) -> i32 {
    let mut out: Option<PathBuf> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                println!("{KEYGEN_USAGE}");
                return 0;
            }
            "--out" => match args.get(i + 1) {
                Some(v) => {
                    out = Some(PathBuf::from(v));
                    i += 1;
                }
                None => {
                    eprintln!("xerj corpus keygen: --out needs a path prefix\n\n{KEYGEN_USAGE}");
                    return 2;
                }
            },
            a => {
                eprintln!("xerj corpus keygen: unexpected argument '{a}'\n\n{KEYGEN_USAGE}");
                return 2;
            }
        }
        i += 1;
    }
    let Some(prefix) = out else {
        eprintln!("xerj corpus keygen: --out is required\n\n{KEYGEN_USAGE}");
        return 2;
    };
    match generate_keypair() {
        Ok((seed, public)) => {
            let key_path = format!("{}.key", prefix.display());
            if Path::new(&key_path).exists() {
                eprintln!(
                    "xerj corpus keygen: {key_path} already exists — refusing to overwrite a key"
                );
                return 1;
            }
            // the documented first run names a directory that does not exist
            // yet (`--out tools/packs/keys/<name>`) — create it rather than
            // make the user mkdir by hand
            if let Some(parent) = Path::new(&key_path).parent() {
                if let Err(e) = std::fs::create_dir_all(parent) {
                    eprintln!(
                        "xerj corpus keygen: cannot create {}: {e}",
                        parent.display()
                    );
                    return 1;
                }
            }
            if let Err(e) = std::fs::write(&key_path, format!("{seed}\n")).and_then(|_| {
                std::fs::write(format!("{}.pub", prefix.display()), format!("{public}\n"))
            }) {
                eprintln!("xerj corpus keygen: cannot write key files: {e}");
                return 1;
            }
            println!("wrote {key_path} (SECRET — CI secret material, never commit)");
            println!(
                "wrote {}.pub (verifying key — publish next to the pack)",
                prefix.display()
            );
            0
        }
        Err(e) => {
            eprintln!("xerj corpus keygen: {e:#}");
            1
        }
    }
}

fn run_sign(args: &[String]) -> i32 {
    let mut pack: Option<PathBuf> = None;
    let mut key: Option<PathBuf> = None;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                println!("{SIGN_USAGE}");
                return 0;
            }
            "--key" => match args.get(i + 1) {
                Some(v) => {
                    key = Some(PathBuf::from(v));
                    i += 1;
                }
                None => {
                    eprintln!("xerj corpus sign: --key needs a seed file\n\n{SIGN_USAGE}");
                    return 2;
                }
            },
            a if a.starts_with('-') => {
                eprintln!("xerj corpus sign: unknown flag '{a}'\n\n{SIGN_USAGE}");
                return 2;
            }
            a => {
                if pack.is_some() {
                    eprintln!("xerj corpus sign: one <pack-dir>, not two\n\n{SIGN_USAGE}");
                    return 2;
                }
                pack = Some(PathBuf::from(a));
            }
        }
        i += 1;
    }
    let (Some(pack), Some(key)) = (pack, key) else {
        eprintln!(
            "xerj corpus sign: <pack-dir> and --key <seed-file> are both required\n\n{SIGN_USAGE}"
        );
        return 2;
    };
    let seed = match std::fs::read_to_string(&key) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("xerj corpus sign: cannot read {}: {e}", key.display());
            return 1;
        }
    };
    match sign_pack(&pack, &seed) {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("xerj corpus sign: {e:#}");
            1
        }
    }
}

// ── key encoding helpers ────────────────────────────────────────────────────

/// Decode hex of an exact byte length, with a name for the error message.
/// The keys are 32 raw bytes in hex (64 chars) — not PEM, not pkcs8 — so a
/// public key file is copy-pasteable in an issue thread and diffable in a
/// repo.
fn parse_key(hex: &str, want: usize, what: &str) -> Result<Vec<u8>> {
    let t = hex.trim();
    if t.len() != want * 2 || !t.chars().all(|c| c.is_ascii_hexdigit()) {
        bail!(
            "{what} must be {want} bytes as {want}×2 hex chars (got {} chars)",
            t.len()
        );
    }
    (0..want)
        .map(|i| u8::from_str_radix(&t[i * 2..i * 2 + 2], 16).map_err(|e| anyhow::anyhow!("{e}")))
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::harvest::pack;
    use crate::harvest::recipe::{Emit, Envelope, Identity, Merge, Suggest};
    use serde_json::{json, Map};
    use sha2::Digest;

    fn tiny_pack(dir: &Path) -> PathBuf {
        let recipe = crate::harvest::recipe::Recipe {
            name: "t".into(),
            description: String::new(),
            envelope: Envelope {
                id_from: vec!["id".into()],
                title_from: vec!["id".into()],
                body_join: vec![],
                defs_from: vec![],
                passthrough: false,
            },
            sources: vec![],
            identity: Identity {
                edges: vec![],
                canonical_source_order: vec![],
            },
            merge: Merge::default(),
            derived: vec![],
            emit: Emit { shards: 1 },
            suggest: Suggest { sample: 64 },
        };
        let mut rec = Map::new();
        rec.insert("id".into(), json!("a"));
        let records = vec![rec];
        let stats = pack::RunStats {
            envelopes: 1,
            per_source: vec![pack::SourceStat {
                slug: "s".into(),
                kind: "dir".into(),
                path: None,
                url: None,
                licence: "CC0-1.0".into(),
                watermark: None,
                unchanged: false,
                records: 1,
                new: 1,
                skipped: 0,
                pruned: 0,
            }],
        };
        let sugg = crate::harvest::suggest::analyze(&records, 64);
        pack::emit(dir, &recipe, "# r\n", records, &stats, &sugg)
            .unwrap()
            .dir
    }

    #[test]
    fn sign_then_verify_round_trips_on_a_real_pack() {
        let tmp = tempfile::tempdir().unwrap();
        let pack_dir = tiny_pack(tmp.path());
        let (seed, public) = generate_keypair().unwrap();
        sign_pack(&pack_dir, &seed).unwrap();
        assert!(pack_is_signed(&pack_dir));
        // the signed pack still passes checksum verification (the .sig file
        // is not SUMS-covered, by design, and read_manifest ignores it)
        pack::read_manifest(&pack_dir).unwrap();
        verify_pack(&pack_dir, &public).unwrap();
        // and a second key does NOT verify it
        let (_, other) = generate_keypair().unwrap();
        assert!(verify_pack(&pack_dir, &other)
            .unwrap_err()
            .to_string()
            .contains("does not verify"));
    }

    #[test]
    fn a_tampered_sums_fails_verification() {
        // the whole point of signatures: a self-consistent REBUILD (fresh
        // checksums over changed records) has valid checksums, and only the
        // signature catches it.
        let tmp = tempfile::tempdir().unwrap();
        let pack_dir = tiny_pack(tmp.path());
        let (seed, public) = generate_keypair().unwrap();
        sign_pack(&pack_dir, &seed).unwrap();
        // replace a record file AND rewrite SUMS so checksums agree — the
        // scenario read_manifest cannot catch
        let sums = std::fs::read_to_string(pack_dir.join("SHA256SUMS")).unwrap();
        let fname = sums
            .lines()
            .find(|l| l.ends_with("recipe.toml"))
            .unwrap()
            .split_once("  ")
            .unwrap()
            .1
            .to_string();
        std::fs::write(pack_dir.join(&fname), "# tampered recipe\n").unwrap();
        let mut new_sums = String::new();
        for line in sums.lines() {
            if line.ends_with(&fname) {
                let d = sha2::Sha256::digest(b"# tampered recipe\n");
                new_sums.push_str(&hex(&d));
                new_sums.push_str("  ");
                new_sums.push_str(&fname);
                new_sums.push('\n');
            } else {
                new_sums.push_str(line);
                new_sums.push('\n');
            }
        }
        std::fs::write(pack_dir.join("SHA256SUMS"), new_sums).unwrap();
        pack::read_manifest(&pack_dir).unwrap(); // checksums pass…
        let err = verify_pack(&pack_dir, &public).unwrap_err().to_string();
        assert!(err.contains("does not verify"), "{err}");
    }

    #[test]
    fn verification_names_its_failure_modes() {
        let tmp = tempfile::tempdir().unwrap();
        let pack_dir = tiny_pack(tmp.path());
        let (seed, public) = generate_keypair().unwrap();
        // unsigned pack
        assert!(verify_pack(&pack_dir, &public)
            .unwrap_err()
            .to_string()
            .contains("no SHA256SUMS.sig"));
        sign_pack(&pack_dir, &seed).unwrap();
        // truncated signature
        std::fs::write(pack_dir.join(SIG_NAME), vec![0u8; 10]).unwrap();
        assert!(verify_pack(&pack_dir, &public)
            .unwrap_err()
            .to_string()
            .contains("10 bytes"));
        // malformed public key
        sign_pack(&pack_dir, &seed).unwrap();
        assert!(verify_pack(&pack_dir, "not-hex!")
            .unwrap_err()
            .to_string()
            .contains("public key"));
    }

    #[test]
    fn a_seed_determines_one_public_key() {
        // the property keygen relies on: seed → keypair is deterministic, so
        // the .pub derived at keygen time is the same key `sign` uses later
        let (seed, public) = generate_keypair().unwrap();
        let pair =
            Ed25519KeyPair::from_seed_unchecked(&parse_key(&seed, 32, "seed").unwrap()).unwrap();
        assert_eq!(hex(pair.public_key().as_ref()), public);
    }

    #[test]
    fn hex_keys_are_validated_loudly() {
        for bad in ["", "zz", &"a".repeat(63), &"a".repeat(66)] {
            assert!(parse_key(bad, 32, "seed").is_err(), "{bad:?}");
        }
        assert!(parse_key(&"a".repeat(64), 32, "seed").is_ok());
    }

    #[test]
    fn sign_bytes_round_trips_over_a_raw_buffer() {
        // the hub-pack case: the signature is over the archive bytes, not a
        // SHA256SUMS file. A fresh key signs a buffer and the matching public
        // key verifies it — including embedded NULs, which an archive has.
        let (seed, public) = generate_keypair().unwrap();
        let data = b"hub pack archive bytes \x00\x01\x02 not a SHA256SUMS file";
        let sig = sign_bytes(data, &seed).unwrap();
        // raw 64-byte signature as lower-case hex (128 chars)
        assert_eq!(sig.len(), 128);
        assert!(sig
            .chars()
            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
        verify_bytes(data, &sig, &public).unwrap();
    }

    #[test]
    fn sign_bytes_rejects_a_flipped_byte() {
        // flipping one byte of the signed buffer must fail — this is the whole
        // reason the archive is signed rather than just checksummed.
        let (seed, public) = generate_keypair().unwrap();
        let data = b"hub pack archive bytes";
        let sig = sign_bytes(data, &seed).unwrap();
        let mut tampered = data.to_vec();
        tampered[0] ^= 0x01;
        let err = verify_bytes(&tampered, &sig, &public)
            .unwrap_err()
            .to_string();
        assert!(err.contains("does not verify"), "{err}");
    }

    #[test]
    fn sign_bytes_rejects_a_foreign_public_key() {
        // a signature made by one key must not verify under an unrelated key.
        let (seed, _public) = generate_keypair().unwrap();
        let data = b"hub pack archive bytes";
        let sig = sign_bytes(data, &seed).unwrap();
        let (_, other) = generate_keypair().unwrap();
        assert!(verify_bytes(data, &sig, &other).is_err());
    }
}

//! The content-addressed envelope store — "skip already stored" as a
//! filesystem fact, not a promise.
//!
//! Each normalized record plus its provenance becomes ONE immutable JSON
//! file named `<slug>.<xxh3_128-of-canonical-json>.json`. File presence IS
//! the dedup index: a re-run recomputes the key and skips if the file
//! exists, the same recomputed-never-trusted philosophy as `ids.rs` (same
//! content ⇒ same key ⇒ the write converges). No database, no journal —
//! crash at any point and the next run converges.
//!
//! The canonical form is key-sorted JSON with f64 floats in
//! shortest-round-trip form — deterministic for the same logical content
//! regardless of the input file's key order. (Sorting is explicit: the
//! workspace enables serde_json's `preserve_order` for the engine's
//! document store, which would otherwise bake insertion order in.)

use std::collections::HashSet;
use std::io;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use serde_json::{Map, Value};
use xxhash_rust::xxh3::xxh3_128;

/// Cap on flattened fields per envelope, matching the extractor's own cap
/// (`extract::MAX_FIELDS_PER_RECORD`): an envelope fatter than what the
/// index path would keep would silently disagree with the indexed record.
pub(crate) const MAX_FIELDS: usize = 512;

/// Canonical JSON for content hashing: sorted-key serialization. The
/// workspace enables serde_json's `preserve_order` (xerj-common), so `Map`
/// is an IndexMap and `to_string` would bake in INSERTION order — which is
/// exactly what canonical form must not do. Sorting through a `BTreeMap`
/// sidesteps the feature entirely.
pub fn canonical_json(env: &Map<String, Value>) -> String {
    let sorted: std::collections::BTreeMap<&String, &Value> = env.iter().collect();
    serde_json::to_string(&sorted).unwrap_or_default()
}

/// The store key for an envelope: xxh3_128 of the canonical JSON, hex.
/// 128-bit so an accidental collision across a multi-million-record store is
/// not a scenario to reason about.
pub fn key_of(env: &Map<String, Value>) -> String {
    format!("{:032x}", xxh3_128(canonical_json(env).as_bytes()))
}

/// Store one envelope. Returns `true` when it was NEW (written), `false`
/// when an identical envelope was already stored (skipped). The write is
/// atomic (tmp + rename): a partial file never exists under its final name.
pub fn put(store_dir: &Path, slug: &str, env: &Map<String, Value>) -> io::Result<(String, bool)> {
    let key = key_of(env);
    let path = file_for(store_dir, slug, &key);
    if path.exists() {
        return Ok((key, false));
    }
    std::fs::create_dir_all(store_dir)?;
    let tmp = path.with_extension("json.tmp");
    std::fs::write(&tmp, canonical_json(env))?;
    std::fs::rename(&tmp, &path)?;
    Ok((key, true))
}

fn file_for(store_dir: &Path, slug: &str, key: &str) -> PathBuf {
    store_dir.join(format!("{slug}.{key}.json"))
}

/// Every envelope whose `_src` is one of `slugs`, in filename order (the
/// deterministic iteration order every downstream stage relies on).
/// Envelopes from sources the current recipe no longer declares are left on
/// disk but not returned — a retired source must not haunt the cluster set.
/// Each returned map carries the file's store key under the `KEY` sentinel
/// so member ordering can fall back to it; `put` computes the key BEFORE
/// injection, so the sentinel is never part of any stored content.
///
/// Any unreadable or non-object `<slug>.<key>.json` for a live slug is a
/// hard error — silently skipping a corrupt store file would omit that
/// record from the emitted pack with a green exit (#1110 gap 4).
pub fn read_all(store_dir: &Path, slugs: &HashSet<String>) -> Result<Vec<Map<String, Value>>> {
    let mut out = Vec::new();
    let entries = match std::fs::read_dir(store_dir) {
        Ok(entries) => entries,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(out),
        Err(e) => {
            return Err(e).with_context(|| format!("cannot read store dir {}", store_dir.display()))
        }
    };
    let mut names: Vec<String> = Vec::new();
    for entry in entries {
        let e = entry.with_context(|| format!("cannot read entry in {}", store_dir.display()))?;
        if e.path().extension().and_then(|x| x.to_str()) == Some("json") {
            if let Some(name) = e.file_name().to_str() {
                names.push(name.to_string());
            }
        }
    }
    names.sort();
    for name in names {
        // "<slug>.<32-hex>.json" — split from the RIGHT: slugs may contain
        // dots themselves, the key never does.
        let Some(rest) = name.strip_suffix(".json") else {
            continue;
        };
        let Some((slug, key)) = rest.rsplit_once('.') else {
            continue;
        };
        if !slugs.contains(slug) {
            continue;
        }
        let path = store_dir.join(&name);
        let raw = std::fs::read_to_string(&path)
            .with_context(|| format!("cannot read store envelope {}", path.display()))?;
        let v: Value = serde_json::from_str(&raw).with_context(|| {
            format!("corrupt store envelope {} (not valid JSON)", path.display())
        })?;
        let Value::Object(mut m) = v else {
            bail!(
                "corrupt store envelope {} (expected JSON object)",
                path.display()
            );
        };
        m.insert(super::identity::KEY.into(), Value::String(key.to_string()));
        out.push(m);
    }
    Ok(out)
}

/// Drop envelopes of `slug` that this run did NOT re-put — a file deleted
/// upstream, or a record the normalizer no longer emits. Returns how many
/// files were removed. Scoped to one slug so a PARTIAL harvest of another
/// source (network watermark, M2) can never prune what it did not walk.
pub fn prune(store_dir: &Path, slug: &str, live_keys: &HashSet<String>) -> usize {
    let Ok(entries) = std::fs::read_dir(store_dir) else {
        return 0;
    };
    let mut removed = 0usize;
    for e in entries.flatten() {
        let name = e.file_name().to_string_lossy().to_string();
        let Some(rest) = name.strip_prefix(&format!("{slug}.")) else {
            continue;
        };
        let Some(key) = rest.strip_suffix(".json") else {
            continue;
        };
        if live_keys.contains(key) {
            continue;
        }
        if std::fs::remove_file(e.path()).is_ok() {
            removed += 1;
        }
    }
    removed
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn env(id: &str, src: &str) -> Map<String, Value> {
        let mut m = Map::new();
        m.insert("id".into(), json!(id));
        m.insert("_src".into(), json!(src));
        m
    }

    #[test]
    fn same_content_same_key_regardless_of_key_order() {
        let mut a = Map::new();
        a.insert("id".into(), json!("x"));
        a.insert("zz".into(), json!(1));
        let mut b = Map::new();
        b.insert("zz".into(), json!(1));
        b.insert("id".into(), json!("x"));
        assert_eq!(key_of(&a), key_of(&b));
        assert_eq!(canonical_json(&a), canonical_json(&b));
    }

    #[test]
    fn put_is_idempotent_and_read_round_trips() {
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path().join("store");
        let (k1, new1) = put(&dir, "a", &env("x", "a")).unwrap();
        let (_, new2) = put(&dir, "a", &env("x", "a")).unwrap();
        assert!(new1);
        assert!(!new2, "second put of identical content skips");
        let all = read_all(&dir, &HashSet::from(["a".to_string()])).unwrap();
        assert_eq!(all.len(), 1);
        assert_eq!(all[0]["id"], json!("x"));
        assert_eq!(k1.len(), 32);
    }

    #[test]
    fn different_source_is_a_different_envelope() {
        // identical record text from two sources is two evidence rows, not one
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path().join("store");
        put(&dir, "a", &env("x", "a")).unwrap();
        put(&dir, "b", &env("x", "b")).unwrap();
        let all = read_all(&dir, &HashSet::from(["a".to_string(), "b".to_string()])).unwrap();
        assert_eq!(all.len(), 2);
        // retired source stays on disk but is not returned
        let only_a = read_all(&dir, &HashSet::from(["a".to_string()])).unwrap();
        assert_eq!(only_a.len(), 1);
        assert_eq!(only_a[0]["_src"], json!("a"));
    }

    #[test]
    fn prune_drops_only_dead_keys_of_its_slug() {
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path().join("store");
        let (ka, _) = put(&dir, "a", &env("x", "a")).unwrap();
        let (kb, _) = put(&dir, "a", &env("y", "a")).unwrap();
        let (_kc, _) = put(&dir, "b", &env("z", "b")).unwrap();
        let removed = prune(&dir, "a", &HashSet::from([ka.clone(), kb]));
        assert_eq!(removed, 0);
        let removed = prune(&dir, "a", &HashSet::from([ka]));
        assert_eq!(removed, 1, "y died, x lived, b untouched");
        assert_eq!(
            read_all(&dir, &HashSet::from(["a".into(), "b".into()]))
                .unwrap()
                .len(),
            2
        );
    }

    #[test]
    fn read_all_refuses_corrupt_store_envelope_instead_of_dropping_it() {
        // #1110 gap 4: a truncated or non-object file in store/ for a live
        // slug must fail the build loudly, never silently omit the record.
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path().join("store");
        let (k, _) = put(&dir, "a", &env("x", "a")).unwrap();
        let path = dir.join(format!("a.{k}.json"));

        std::fs::write(&path, "{truncated").unwrap();
        let err = read_all(&dir, &HashSet::from(["a".to_string()]))
            .unwrap_err()
            .to_string();
        assert!(err.contains("corrupt store envelope"), "{err}");

        std::fs::write(&path, "[1, 2, 3]").unwrap();
        let err = read_all(&dir, &HashSet::from(["a".to_string()]))
            .unwrap_err()
            .to_string();
        assert!(err.contains("expected JSON object"), "{err}");

        // a corrupt file belonging to a RETIRED slug is ignored, matching the
        // retired-source contract above.
        assert!(read_all(&dir, &HashSet::from(["other".to_string()]))
            .unwrap()
            .is_empty());
    }
}

//! The suggester — mapping and join-key suggestions from a sample.
//!
//! Nothing here mutates records or configures an index: autoindex still
//! infers the real mapping at index time ([`crate::infer`] over the live
//! dataset). What this module adds is the AUTHOR loop — after a first
//! `corpus build`, the recipe author reads what the data actually looks
//! like (field types, which fields look like aliases of each other) and
//! edits the recipe: identity edges, derived `regex_extract`, envelope
//! sources. Suggestions, not decisions.
//!
//! All statistics come from a deterministic stride sample of the merged
//! records (id-sorted, every ⌈n/cap⌉-th record), and every output is
//! built through ordered collections — the three artifacts are
//! byte-stable across rebuilds like the rest of the pack.
//!
//! Type verdicts reuse [`crate::infer`] VERBATIM (the FieldAcc ≥95%
//! rule, `DISTINCT_CAP`, entity and date elections). Forking those
//! heuristics here would produce two disagreeing opinions about the same
//! field, and the index always wins the disagreement, so the suggestion
//! would be wrong by construction.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::sync::OnceLock;

use regex::Regex;
use serde_json::{Map, Value};

use crate::harvest::recipe::RESERVED_KEYS;
use crate::infer::{entities, FieldAcc, FieldSpec, DISTINCT_CAP};

/// The line every suggestions artifact carries. A pack consumer must never
/// read these files as configuration — they are one sample's opinion.
pub const SUGGEST_HEADER: &str =
    "Suggestions, not decisions — generated from a sample; the index infers the real mapping";

/// Fields excluded from relation analysis: the envelope's own mechanics.
/// `source` ⊆ `sources` by construction, `origin`/`source_url` are
/// provenance — reporting those as "joins" would be noise the recipe
/// already knows the answer to.
const RELATION_EXCLUDED: &[&str] = RESERVED_KEYS;

/// Most relations a pack will carry in these files. Truncation is said out
/// loud in the markdown, never silent.
const MAX_RELATIONS: usize = 64;

/// Overlap examples shown per relation.
const OVERLAP_EXAMPLES: usize = 3;

#[derive(Debug, Clone)]
pub struct Suggestions {
    pub total: usize,
    pub sampled: usize,
    pub fields: Vec<FieldSpec>,
    pub relations: Vec<Relation>,
    /// More relations existed than [`MAX_RELATIONS`]; the strongest were kept.
    pub truncated: bool,
}

#[derive(Debug, Clone, serde::Serialize)]
pub struct Relation {
    pub left: String,
    pub right: String,
    /// The shared value grammar: `cve`, `ghsa`, `rustsec`, `sha`, `url`,
    /// `email`, `ip`, `uuid` — or `value` for a shapeless exact-value join.
    pub grammar: String,
    pub jaccard: f64,
    /// |left ∩ right| / |left| — 1.0 means every left value appears in right.
    pub left_in_right: f64,
    pub right_in_left: f64,
    /// Structural, from array-ness in the sample: both array →
    /// many-to-many, and so on.
    pub cardinality: &'static str,
    /// Sorted shared values, at most [`OVERLAP_EXAMPLES`].
    pub overlap: Vec<String>,
}

/// One field's accumulated view: the reused [`FieldAcc`], plus what
/// relation analysis needs and FieldAcc does not expose (array-ness and a
/// capped value set).
#[derive(Default)]
struct FieldView {
    acc: FieldAcc,
    array_n: u64,
    scalar_n: u64,
    values: BTreeSet<String>,
    grammar_hits: BTreeMap<&'static str, u64>,
    value_n: u64,
}

impl FieldView {
    fn add(&mut self, v: &Value) {
        self.acc.add(v);
        if v.is_array() {
            for e in v.as_array().unwrap() {
                if e.is_null() || e.is_array() || e.is_object() {
                    continue;
                }
                self.array_n += 1;
                self.note(e);
            }
            return;
        }
        if v.is_null() || v.is_object() {
            return;
        }
        self.scalar_n += 1;
        self.note(v);
    }

    /// Numbers stringify (a numeric join key is still a join key); bools
    /// and objects carry no join identity.
    fn note(&mut self, v: &Value) {
        let s = match v {
            Value::String(s) => s.clone(),
            Value::Number(n) => n.to_string(),
            _ => return,
        };
        self.value_n += 1;
        if let Some(g) = value_grammar(&s) {
            *self.grammar_hits.entry(g).or_default() += 1;
        }
        if self.values.len() < DISTINCT_CAP {
            self.values.insert(s);
        }
    }

    /// The fraction of sampled values matching ANY known ID grammar. A real
    /// `aliases` array mixes CVEs and GHSAs, so demanding ≥90% of ONE
    /// grammar would disqualify the exact field this analysis exists for —
    /// "identifier-ish" is the property that qualifies a field; the shared
    /// values name the family on the edge ([`overlap_grammar`]).
    fn id_ratio(&self) -> f64 {
        if self.value_n == 0 {
            return 0.0;
        }
        self.grammar_hits.values().sum::<u64>() as f64 / self.value_n as f64
    }

    fn many(&self) -> bool {
        self.array_n > 0
    }
}

/// The grammar of an overlap: the family held by ≥90% of the SHARED values,
/// or `value`. Computed from the shared values themselves so a mixed-family
/// field (CVEs and GHSAs in one `aliases`) still yields a precise label.
fn overlap_grammar(shared: &BTreeSet<&String>) -> String {
    let mut tally: BTreeMap<&'static str, u64> = BTreeMap::new();
    let mut n = 0u64;
    for v in shared {
        n += 1;
        if let Some(g) = value_grammar(v) {
            *tally.entry(g).or_default() += 1;
        }
    }
    tally
        .iter()
        .max_by(|(a, an), (b, bn)| bn.cmp(an).then_with(|| a.cmp(b)))
        .filter(|(_, c)| **c * 10 >= n * 9)
        .map(|(g, _)| g.to_string())
        .unwrap_or_else(|| "value".to_string())
}

/// The ID grammars relation analysis knows. Vuln-corpus shaped on purpose
/// (this grew out of the rust-vulns pack) but none of them is vuln-only:
/// a CVE-shaped or sha-shaped value is an identifier wherever it appears.
fn grammars() -> &'static [(&'static str, Regex)] {
    static G: OnceLock<Vec<(&'static str, Regex)>> = OnceLock::new();
    G.get_or_init(|| {
        vec![
            ("cve", Regex::new(r"(?i)^CVE-\d{4}-\d{4,}$").unwrap()),
            (
                "ghsa",
                Regex::new(r"^GHSA(-[23456789cfghjmpqrvwx]{4}){3}$").unwrap(),
            ),
            ("rustsec", Regex::new(r"^RUSTSEC-\d{4}-\d{4,}$").unwrap()),
            // 7..=40 lowercase hex: git short..full sha. {6} would admit
            // ordinary words-in-hex like "abc123" (the M1 trap).
            ("sha", Regex::new(r"^[0-9a-f]{7,40}$").unwrap()),
        ]
    })
    .as_slice()
}

/// Classify one value. Vuln-id shapes first, then [`entities::classify`]
/// for url/email/ip/uuid — reused, not re-implemented.
fn value_grammar(v: &str) -> Option<&'static str> {
    let t = v.trim();
    if t.is_empty() || t.len() > 512 {
        return None;
    }
    for (name, re) in grammars() {
        if re.is_match(t) {
            return Some(name);
        }
    }
    entities::classify(t).map(|e| e.as_str())
}

/// Analyze a sample of the merged records. `sample_cap` is the recipe's
/// `[suggest] sample`.
pub fn analyze(records: &[Map<String, Value>], sample_cap: usize) -> Suggestions {
    // stride sample over id-sorted records: every ⌈n/cap⌉-th one. Cluster
    // order (the caller's) must never reach the output.
    let mut order: Vec<usize> = (0..records.len()).collect();
    order.sort_by_key(|&i| {
        records[i]
            .get("id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string()
    });
    let step = records.len().div_ceil(sample_cap).max(1);
    let sample: Vec<&Map<String, Value>> =
        order.iter().step_by(step).map(|&i| &records[i]).collect();

    let mut views: HashMap<String, FieldView> = HashMap::new();
    for r in &sample {
        for (k, v) in r.iter() {
            views.entry(k.clone()).or_default().add(v);
        }
    }

    // FieldAcc map for infer_fields — the real verdicts, not a fork.
    let mut accs: HashMap<String, FieldAcc> = HashMap::new();
    for (k, v) in &views {
        accs.insert(k.clone(), v.acc.clone());
    }
    let fields = crate::infer::infer_fields_with_policy(&accs, sample.len() as u64, false, false);

    // Relations over non-envelope fields, in name order (pairs and output
    // both derive their order from it).
    let mut names: Vec<&String> = views
        .keys()
        .filter(|k| !RELATION_EXCLUDED.contains(&k.as_str()))
        .collect();
    names.sort();
    let mut relations = Vec::new();
    for (i, a) in names.iter().enumerate() {
        for b in &names[i + 1..] {
            let (va, vb) = (&views[*a], &views[*b]);
            if va.values.is_empty() || vb.values.is_empty() {
                continue;
            }
            let shared: BTreeSet<&String> = va.values.intersection(&vb.values).collect();
            if shared.is_empty() {
                continue;
            }
            let union = va.values.len() + vb.values.len() - shared.len();
            let jaccard = shared.len() as f64 / union as f64;
            // An identifier-ish pair (≥90% of values in known grammars —
            // families may differ, an `aliases` array mixes them) needs any
            // overlap at all to be worth a look; a shapeless pair must be at
            // least half identical, or it is two keyword fields that happen
            // to share a value.
            let both_ids = va.id_ratio() >= 0.9 && vb.id_ratio() >= 0.9;
            if !both_ids && jaccard < 0.5 {
                continue;
            }
            relations.push(Relation {
                left: (*a).clone(),
                right: (*b).clone(),
                grammar: overlap_grammar(&shared),
                jaccard,
                left_in_right: shared.len() as f64 / va.values.len() as f64,
                right_in_left: shared.len() as f64 / vb.values.len() as f64,
                cardinality: match (va.many(), vb.many()) {
                    (true, true) => "many-to-many",
                    (false, true) => "one-to-many",
                    (true, false) => "many-to-one",
                    (false, false) => "one-to-one",
                },
                overlap: shared
                    .iter()
                    .take(OVERLAP_EXAMPLES)
                    .map(|s| (*s).clone())
                    .collect(),
            });
        }
    }
    // strongest first for truncation, name-ordered for the files
    relations.sort_by(|x, y| {
        y.jaccard
            .partial_cmp(&x.jaccard)
            .unwrap()
            .then_with(|| x.left.cmp(&y.left))
            .then_with(|| x.right.cmp(&y.right))
    });
    let truncated = relations.len() > MAX_RELATIONS;
    relations.truncate(MAX_RELATIONS);
    relations.sort_by(|x, y| x.left.cmp(&y.left).then_with(|| x.right.cmp(&y.right)));

    Suggestions {
        total: records.len(),
        sampled: sample.len(),
        fields,
        relations,
        truncated,
    }
}

impl Suggestions {
    /// `mapping.suggested.json` — the full field verdicts plus a plain
    /// ES-compat properties map (`semantic_text` is XERJ's; ES reads it as
    /// `text`).
    pub fn mapping_doc(&self) -> Value {
        let mut props = BTreeMap::new();
        for f in &self.fields {
            let es_type = if f.es_type == "semantic_text" {
                "text".to_string()
            } else {
                f.es_type.clone()
            };
            props.insert(
                f.name.clone(),
                serde_json::json!({
                    "type": es_type,
                    "xerj_type": f.es_type,
                }),
            );
        }
        serde_json::json!({
            "note": SUGGEST_HEADER,
            "sampled_records": self.sampled,
            "total_records": self.total,
            "fields": self.fields,
            "es_mapping": { "properties": props },
        })
    }

    /// `suggestions.md` — the human-readable half; the recipe author reads
    /// this one.
    pub fn to_markdown(&self) -> String {
        let mut out = String::new();
        out.push_str("# Suggestions\n\n");
        out.push_str(SUGGEST_HEADER);
        out.push_str(&format!(
            ".\n\nSampled {} of {} record(s) (every \u{230c}n/sample\u{230d}-th, id-ordered).\n\n",
            self.sampled, self.total
        ));
        out.push_str("## Fields\n\n");
        out.push_str("| field | type | coverage | distinct | notes |\n");
        out.push_str("|---|---|---|---|---|\n");
        for f in &self.fields {
            let notes = if f.notes.is_empty() {
                String::new()
            } else {
                f.notes.join("; ")
            };
            out.push_str(&format!(
                "| `{}` | {} | {:.0}% | {}{} | {} |\n",
                f.name,
                f.es_type,
                f.coverage * 100.0,
                f.cardinality_est,
                if f.cardinality_overflow { "+" } else { "" },
                notes.replace('|', "\\|"),
            ));
        }
        out.push_str("\n## Possible joins / aliases\n\n");
        if self.relations.is_empty() {
            out.push_str("None found in the sample.\n");
        } else {
            for r in &self.relations {
                out.push_str(&format!(
                    "- `{}` \u{2194} `{}` \u{2014} grammar `{}`, jaccard {:.2} ({:.0}% of `{}` and \
                     {:.0}% of `{}` shared) \u{2014} {}\n",
                    r.left,
                    r.right,
                    r.grammar,
                    r.jaccard,
                    r.left_in_right * 100.0,
                    r.left,
                    r.right_in_left * 100.0,
                    r.right,
                    r.cardinality,
                ));
                if !r.overlap.is_empty() {
                    out.push_str(&format!(
                        "  - e.g. {}\n",
                        r.overlap
                            .iter()
                            .map(|v| format!("`{v}`"))
                            .collect::<Vec<_>>()
                            .join(", ")
                    ));
                }
            }
            if self.truncated {
                out.push_str(&format!(
                    "\n(more than {MAX_RELATIONS} candidate relations existed; the strongest \
                     {} are shown)\n",
                    self.relations.len()
                ));
            }
        }
        out.push_str(
            "\nHow to use: edit the recipe \u{2014} a same-grammar alias pair wants an \
                      `[identity]` edge (or a derived `regex_extract`), a mis-typed field wants \
                      an explicit mapping. Nothing here is applied automatically.\n",
        );
        out
    }

    /// `relations.jsonl` — one JSON object per line, name-ordered.
    pub fn relations_jsonl(&self) -> String {
        let mut out = String::new();
        for r in &self.relations {
            out.push_str(&serde_json::to_string(r).expect("Relation serializes"));
            out.push('\n');
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn rec(id: &str, extra: &[(&str, Value)]) -> Map<String, Value> {
        let mut m = Map::new();
        m.insert("id".into(), json!(id));
        for (k, v) in extra {
            m.insert(k.to_string(), v.clone());
        }
        m
    }

    #[test]
    fn value_grammar_knows_the_id_families() {
        assert_eq!(value_grammar("CVE-2021-25900"), Some("cve"));
        assert_eq!(
            value_grammar("cve-2021-25900"),
            Some("cve"),
            "case-insensitive"
        );
        assert_eq!(value_grammar("GHSA-43w2-9j62-hq99"), Some("ghsa"));
        assert_eq!(value_grammar("RUSTSEC-2021-0003"), Some("rustsec"));
        assert_eq!(
            value_grammar("0e5f1d6c2ba9a3e8f7d4c1b0a987654321abcdef"),
            Some("sha")
        );
        assert_eq!(
            value_grammar("91a3e8f"),
            Some("sha"),
            "7 hex chars = short sha"
        );
        assert_eq!(value_grammar("https://x.example/y"), Some("url"));
        assert_eq!(value_grammar("a@b.example"), Some("email"));
        assert_eq!(
            value_grammar("741e7b6b-dbd2-4a7f-93a9-4ba50fb561d3"),
            Some("uuid")
        );
        assert_eq!(
            value_grammar("abc123"),
            None,
            "6 hex-ish chars is a word, not a sha"
        );
        assert_eq!(value_grammar("hello world"), None);
    }

    #[test]
    fn sampling_is_strided_and_input_order_independent() {
        let mut records: Vec<Map<String, Value>> =
            (0..10).map(|i| rec(&format!("X{i}"), &[])).collect();
        let a = analyze(&records, 4);
        assert_eq!(a.sampled, 4, "step 3 over 10 → indices 0,3,6,9");
        assert_eq!(a.total, 10);

        // cluster order must not reach the output: shuffle in, same stats out
        records.reverse();
        let b = analyze(&records, 4);
        assert_eq!(a.to_markdown(), b.to_markdown());
        assert_eq!(
            serde_json::to_string(&a.mapping_doc()).unwrap(),
            serde_json::to_string(&b.mapping_doc()).unwrap()
        );
    }

    #[test]
    fn field_verdicts_are_infer_verdicts() {
        let records: Vec<_> = (0..24)
            .map(|i| {
                rec(
                    &format!("R{i:02}"),
                    &[
                        ("modified", json!("2026-03-17T00:00:13Z")),
                        ("severity", json!(if i % 2 == 0 { "HIGH" } else { "LOW" })),
                        (
                            "body",
                            json!(
                                "The connection pool retries every failed handshake with \
                                   backoff. Each worker owns one socket and never shares it."
                            ),
                        ),
                        ("score", json!(i)),
                    ],
                )
            })
            .collect();
        let s = analyze(&records, 64);
        let by = |n: &str| {
            s.fields
                .iter()
                .find(|f| f.name == n)
                .unwrap_or_else(|| panic!("{n} missing: {:?}", s.fields))
                .es_type
                .clone()
        };
        assert_eq!(by("modified"), "date");
        assert_eq!(by("severity"), "keyword");
        assert_eq!(by("score"), "long");
        assert_eq!(by("body"), "semantic_text", "the natural-language election");

        // and the ES-compat view downgrades the XERJ-only type
        let doc = s.mapping_doc();
        assert_eq!(
            doc["es_mapping"]["properties"]["body"]["type"],
            json!("text")
        );
        assert_eq!(
            doc["es_mapping"]["properties"]["body"]["xerj_type"],
            json!("semantic_text")
        );
        assert_eq!(
            doc["es_mapping"]["properties"]["modified"]["type"],
            json!("date")
        );
    }

    #[test]
    fn relations_find_the_alias_pair_not_the_noise() {
        let records: Vec<_> = (0..20)
            .map(|i| {
                rec(
                    &format!("R{i:02}"),
                    &[
                        (
                            "aliases",
                            json!([format!("CVE-2021-{i:04}"), format!("GHSA-43w2-9j6{i}-hq99")]),
                        ),
                        ("cve_ids", json!([format!("CVE-2021-{i:04}")])),
                        ("a_text", json!(format!("unique prose number {i}"))),
                        ("b_text", json!(format!("other prose number {i}"))),
                        // envelope mechanics: source ⊂ sources BY CONSTRUCTION
                        ("source", json!("rustsec")),
                        ("sources", json!(["rustsec", "ghsa"])),
                    ],
                )
            })
            .collect();
        let s = analyze(&records, 64);

        let alias_edge = s
            .relations
            .iter()
            .find(|r| r.left == "aliases" && r.right == "cve_ids")
            .expect("the cve-shaped pair must be reported");
        assert_eq!(alias_edge.grammar, "cve");
        assert_eq!(alias_edge.cardinality, "many-to-many");
        assert!(
            (alias_edge.right_in_left - 1.0).abs() < 1e-9,
            "cve_ids ⊂ aliases"
        );

        // prose fields share no values → no relation; envelope keys excluded
        assert!(!s
            .relations
            .iter()
            .any(|r| r.left == "a_text" || r.right == "b_text"));
        assert!(!s.relations.iter().any(|r| {
            r.left == "source" || r.right == "source" || r.left == "sources" || r.right == "sources"
        }));
    }

    #[test]
    fn shapeless_fields_need_half_overlap() {
        let records: Vec<_> = (0..20)
            .map(|i| {
                rec(
                    &format!("R{i:02}"),
                    &[
                        ("left", json!(format!("pkg-{i}"))),
                        ("right", json!(format!("pkg-{}", i % 10))), // 50% of left
                        ("none", json!(format!("zz-{i}"))),
                    ],
                )
            })
            .collect();
        let s = analyze(&records, 64);
        let edge = s
            .relations
            .iter()
            .find(|r| r.left == "left" && r.right == "right")
            .expect("exactly-half overlap qualifies as a value join");
        assert_eq!(edge.grammar, "value");
        assert_eq!(edge.cardinality, "one-to-one");

        // and a field sharing nothing with anyone produces no edges at all
        assert!(!s
            .relations
            .iter()
            .any(|r| r.left == "none" || r.right == "none"));
    }

    #[test]
    fn markdown_carries_the_header_and_the_tables() {
        let records: Vec<_> = (0..4)
            .map(|i| {
                rec(
                    &format!("R{i}"),
                    &[
                        ("aliases", json!([format!("CVE-2021-{i:04}")])),
                        ("cve_ids", json!([format!("CVE-2021-{i:04}")])),
                    ],
                )
            })
            .collect();
        let s = analyze(&records, 64);
        let md = s.to_markdown();
        assert!(md.contains("Suggestions, not decisions"), "{md}");
        assert!(md.contains("| `aliases` |"), "{md}");
        assert!(md.contains("`CVE-2021-0000`"), "{md}");
        assert!(s.relations_jsonl().ends_with("}\n"));
    }
}

//! Ignore rules for the inventory walk (#276).
//!
//! The cheapest file to index is the one that is never read. A repository's
//! `.gitignore` already says which files are build output; honouring it means
//! `target/`, `node_modules/` and friends are pruned before the walk descends
//! into them, so they cost nothing at all — not a stat, not a hash, not a bulk
//! body.
//!
//! # Where the semantics come from
//!
//! gitignore matching is easy to get 80% right and very hard to get right:
//! nested ignore files, negation (`!keep.log`), directory-only patterns
//! (`build/`), anchoring (`/only-here`) and precedence between an ignore file
//! in a subdirectory and one at the root. We do not hand-roll any of that. The
//! matcher is ripgrep's `ignore` crate (`Unlicense OR MIT`, compatible with
//! XERJ's Apache-2.0), used for its **matching** only — traversal stays on
//! `walkdir` so the existing symlink, hidden-file and unreadable-entry
//! behaviour of [`crate::walk`] is unchanged, and so we can report *which*
//! rule discarded *what*, which `ignore`'s own walker does not expose.
//!
//! Three behaviours are copied deliberately from that reference implementation
//! (`ignore-0.4.32/src/dir.rs` — the version this crate's lockfile pins; read
//! at `~/.cargo/registry/src/*/ignore-0.4.32`). All three live in
//! `Ignore::matched_ignore`, `dir.rs:548-685`:
//!
//! * **Deepest ignore file wins, per kind.** The loop at `dir.rs:563-594` walks
//!   matchers from the current directory outward and keeps the first decision
//!   each kind produces — `if m_custom_ignore.is_none() { m_custom_ignore = … }`
//!   at `:565`, and the same shape for the other three kinds.
//! * **The two git kinds stop at a repository boundary.** In that same loop the
//!   git kinds are guarded by `saw_git` — declared `:562`, tested at `:579` and
//!   `:586` (`if any_git && !saw_git && m_gi.is_none()`), and set at `:593`
//!   (`saw_git = saw_git || ig.inner.has_git`). Once the walk outward has
//!   passed a directory holding a `.git`, no `.gitignore` or `.git/info/exclude`
//!   above it is consulted. That is git's own authority model: the repository
//!   that *owns* a file decides whether it is ignored, so an outer repository's
//!   `.gitignore` has no say over a vendored or submoduled checkout nested
//!   inside it. See [`IgnoreStack::lookup`] for our copy of the guard.
//! * **Kinds are ranked, and the rank beats depth.** `dir.rs:679-684` combines
//!   them `m_custom_ignore.or(m_ignore).or(m_gi).or(m_gi_exclude).or(m_global)
//!   .or(m_explicit)`. We reproduce the first four as `.xerjignore` >
//!   `.gitignore` > `.git/info/exclude` > built-in defaults. The last two have
//!   no analogue here: `m_global` is the global gitignore we deliberately do not
//!   read (below), and `m_explicit` is ripgrep's `--ignore-file`, which XERJ
//!   does not offer. So a `.xerjignore` at the root outranks a `.gitignore` in a
//!   deep subdirectory — that is what makes `.xerjignore` useful as the stated
//!   "exclude things git tracks" (and re-include things git ignores) override
//!   rather than just a second `.gitignore`.
//!
//! Within one file the last matching pattern wins; that is `Gitignore::matched`
//! and we do not reimplement it.
//!
//! # What is deliberately not honoured
//!
//! The user's *global* gitignore (`core.excludesFile`) is not read: a machine-
//! wide preference silently deciding what is in someone's search index is a
//! surprise, and it is not visible in the folder being indexed. `.gitignore`,
//! `.xerjignore` and `.git/info/exclude` all live in the tree the user pointed
//! at, so they are.
//!
//! # Bracket directory names
//!
//! Git reads `[locale]` as a character class (one of those letters), so a
//! pattern written as the Next.js directory `app/[locale]/` does not name
//! that directory. After each ignore-file line that contains an unescaped
//! bracket, the same line is added again with those brackets escaped. The
//! original pattern stays, so a real class such as `*.[ch]` still matches
//! `a.c` and `a.h`. The extra pattern is what makes the literal directory
//! follow the line the author wrote (`!app/[locale]/**` re-includes
//! `app/[locale]/…`, and `app/[locale]/` ignores it). A route-like class is
//! named in the ignore summary. A code file that is still skipped is named
//! with the rule, so a miss is not only a count.

use ignore::gitignore::{Gitignore, GitignoreBuilder, Glob};
use ignore::Match;
use std::collections::BTreeMap;
use std::ffi::OsStr;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};

/// Hidden names start with `.` even when they are not valid UTF-8.
/// `OsStr::to_str()` is `None` for those, so a UTF-8 `starts_with('.')`
/// would walk them (and, here, would count them as non-hidden).
pub(crate) fn is_hidden_name(name: &OsStr) -> bool {
    name.as_encoded_bytes().first() == Some(&b'.')
}

/// Ignore file honoured in every directory, ranked below `.xerjignore`.
pub const GITIGNORE: &str = ".gitignore";
/// XERJ's own ignore file. Same syntax as `.gitignore`, higher precedence, so
/// a user can exclude something git tracks (or re-include something git
/// ignores) without editing `.gitignore`.
pub const XERJIGNORE: &str = ".xerjignore";

/// Build output that is junk in practice but is *not* reliably gitignored —
/// `vendor/` is committed by Go projects, `third_party/` and `bower_components/`
/// are committed dependency trees, `dist/` and `build/` are gitignored in one
/// repo and checked in the next, and a folder full of downloaded packages is
/// very often not a git repository at all.
///
/// These are defaults, not law: `--no-default-ignores` turns them off, any
/// ignore file in the tree outranks them (`!third_party/` keeps a tree the
/// operator wants searched), and `--dry-run` names them as the reason a
/// directory disappeared.
pub const DEFAULT_IGNORE_PATTERNS: &[&str] = &[
    "node_modules/",
    "bower_components/",
    "vendor/",
    "third_party/",
    "thirdparty/",
    "target/",
    "dist/",
    "build/",
    ".venv/",
    "__pycache__/",
    // Media and native binaries. Sniffing classifies these as binary and
    // records each one as junk, so a repo of images and shared libraries
    // spent the walk opening files that can never become a document. A
    // gzipped log (`.gz`) and a PDF stay: those families are extracted.
    // `!*.png` in an ignore file puts one extension back.
    "*.png",
    "*.jpg",
    "*.jpeg",
    "*.gif",
    "*.webp",
    "*.ico",
    "*.bmp",
    "*.woff",
    "*.woff2",
    "*.ttf",
    "*.otf",
    "*.wasm",
    "*.so",
    "*.dll",
    "*.dylib",
    "*.exe",
];

/// Rule label used for the pre-existing dotfile skip. It is not one of the
/// ignore rules and `--no-ignore` does not disable it (it is the main thing
/// keeping `.env` and `.ssh` out of a queryable brain), but a user whose file
/// vanished still needs it named, so it shares the reporting.
///
/// It is a rule about names, and under `--follow-symlinks` about where a link
/// resolves. A HARD link has neither, so a visible name hard-linked to a file
/// inside a hidden directory is still indexed — see the note in
/// [`crate::walk`].
pub const HIDDEN_RULE: &str = "hidden:dotfile";

/// A symlink whose resolved target lies outside the folder the operator
/// pointed at. Only reachable with `--follow-symlinks`, and refused there:
/// "index this folder" is not consent to index whatever else the filesystem
/// links to, and `shared -> /etc` would otherwise put `/etc/shadow` in a
/// queryable brain under the rel path `shared/shadow`.
///
/// Reported like a hidden directory — pruned, never deep-counted. The contents
/// are outside the root, so they were never candidates and counting them would
/// inflate [`IgnoreReport::files_inside_pruned_dirs`] with work no run was
/// going to do.
pub const ESCAPED_ROOT_RULE: &str = "symlink:outside-root";

/// A followed entry whose path could not be resolved for a reason other than
/// "it does not exist" — `realpath(3)` is bounded by `PATH_MAX` where the
/// kernel is not, so a canonical path over that limit fails here while `open`
/// on the walk path still succeeds; `ELOOP` and `EACCES` behave the same.
///
/// Refused, because the hidden-name and root-boundary questions could not be
/// answered and "could not compute" is not "yes". Reported so that a file the
/// operator expected is named rather than silently missing.
pub const UNRESOLVED_LINK_RULE: &str = "symlink:unresolved";

/// A followed link that left the folder AND resolved through a dotted
/// component. Refused whatever `--follow-symlinks-outside-root` says, so it
/// needs its own label: reporting it as [`ESCAPED_ROOT_RULE`] tells an operator
/// who already passed that flag to pass it again, and reporting it as
/// [`HIDDEN_RULE`] sends them looking for a dotfile in a folder that has none.
/// Both were tried; this names the two facts that are actually true.
pub const HIDDEN_OUTSIDE_ROOT_RULE: &str = "symlink:outside-root+hidden";

/// A symlink the walk did not follow. The default is not to follow links, and
/// an unfollowed symlink is not a file to walkdir, so it used to be skipped
/// with no line on the ignore report — a tree of links looked empty. One
/// warning names `--follow-symlinks`; each link is counted under this rule.
/// A target outside the folder stays refused even when the flag is on
/// ([`ESCAPED_ROOT_RULE`]).
pub const NOT_FOLLOWED_RULE: &str = "symlink:not-followed";

const MAX_WARNINGS: usize = 20;
/// Skipped code files named in the summary. The rest are a count: a
/// `*.log` tree is not code, and a `*.ts` rule over a huge tree must not
/// print every path.
const CODE_SKIP_SHOWN: usize = 8;
/// Directory entries the `--dry-run` deep count may examine in total. A
/// pathological `node_modules` is not allowed to turn "tell me the plan" into
/// minutes of stat storm on a laptop; past the budget the count is reported as
/// a floor instead of a total.
const DEEP_COUNT_BUDGET: u64 = 1_000_000;
/// How far above the root we look for an ignore file that covers the root
/// itself. Bounded so a root near `/` cannot walk the whole filesystem.
const MAX_ANCESTOR_LEVELS: usize = 64;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct IgnoreOptions {
    /// `--no-ignore` clears this: no `.gitignore`, no `.xerjignore`, no
    /// defaults. The dotfile skip is separate and stays on.
    pub enabled: bool,
    /// `--no-default-ignores` clears this: ignore files still apply,
    /// [`DEFAULT_IGNORE_PATTERNS`] does not.
    pub defaults: bool,
    /// Count the files inside a pruned directory instead of only reporting
    /// that the directory was pruned. Worth its syscalls in `--dry-run`, whose
    /// whole job is explaining the plan, and not otherwise — the point of
    /// pruning is to never touch those paths.
    pub deep_count: bool,
}

impl Default for IgnoreOptions {
    fn default() -> Self {
        Self {
            enabled: true,
            defaults: true,
            deep_count: false,
        }
    }
}

impl IgnoreOptions {
    /// `--no-ignore`.
    pub const fn off() -> Self {
        Self {
            enabled: false,
            defaults: false,
            deep_count: false,
        }
    }

    /// `--dry-run` explains itself; every other run stays cheap.
    pub const fn with_deep_count(mut self, deep_count: bool) -> Self {
        self.deep_count = deep_count;
        self
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct RuleCount {
    /// Files matched directly by this rule.
    pub files: u64,
    /// Directories pruned by this rule (their contents were never walked).
    pub dirs: u64,
    /// Non-hidden files found inside those pruned directories. Only ever
    /// non-zero when the deep count ran (`--dry-run`).
    pub files_inside_pruned_dirs: u64,
    /// How many of `dirs` had their contents counted. Always 0 for
    /// [`HIDDEN_RULE`], whose directories are never counted at all, so the
    /// reporting can stay silent about them instead of printing a `0 files
    /// inside` that is false of the filesystem.
    pub dirs_deep_counted: u64,
}

#[derive(Debug, Clone)]
pub struct IgnoreReport {
    /// rule label → what it discarded.
    pub by_rule: BTreeMap<String, RuleCount>,
    /// The same discards as [`Self::by_rule`], split by top-level folder.
    ///
    /// `"."` is a file that sits directly in the indexed root. A pruned
    /// directory is charged to itself when it is top-level, and to the
    /// top-level directory that contains it otherwise. [`crate::walk`] turns
    /// this into the `--walk-only` per-folder summary; it is not a second walk.
    pub by_top: BTreeMap<String, BTreeMap<String, RuleCount>>,
    pub files_skipped: u64,
    /// `rel — rule` for skipped code files, capped at [`CODE_SKIP_SHOWN`].
    pub code_skipped: Vec<String>,
    /// Code files skipped past [`CODE_SKIP_SHOWN`].
    pub code_skipped_omitted: u64,
    pub dirs_pruned: u64,
    /// Non-hidden files inside the pruned directories — see
    /// [`IgnoreStack::count_inside`] for exactly what is and is not counted.
    /// Directories pruned by [`HIDDEN_RULE`] contribute nothing: their
    /// contents were excluded by the dotfile rule before any ignore rule was
    /// consulted. Never read this without
    /// [`IgnoreReport::files_inside_pruned_dirs_is_exact`].
    pub files_inside_pruned_dirs: u64,
    /// True unless the deep count hit [`DEEP_COUNT_BUDGET`]. When false,
    /// `files_inside_pruned_dirs` is a floor and every line that prints it
    /// says "at least".
    pub deep_count_complete: bool,
    /// Whether the deep count ran at all. When it did not, no file count
    /// inside a pruned directory is printed — an unmeasured number is not
    /// printed as zero.
    pub deep_count_ran: bool,
    pub ignore_files_read: u64,
    /// Set when the folder the user pointed at is itself covered by an ignore
    /// rule. It is indexed anyway; this is the "and here is why you are seeing
    /// files you thought were ignored" line.
    pub root_exemption: Option<String>,
    /// Unreadable or unparseable ignore files. Never fatal: an ignore file we
    /// cannot read means we index more, not less.
    pub warnings: Vec<String>,
}

impl Default for IgnoreReport {
    fn default() -> Self {
        Self {
            by_rule: BTreeMap::new(),
            by_top: BTreeMap::new(),
            files_skipped: 0,
            code_skipped: Vec::new(),
            code_skipped_omitted: 0,
            dirs_pruned: 0,
            files_inside_pruned_dirs: 0,
            deep_count_complete: true,
            deep_count_ran: false,
            ignore_files_read: 0,
            root_exemption: None,
            warnings: Vec::new(),
        }
    }
}

impl IgnoreReport {
    pub fn nothing_to_report(&self) -> bool {
        self.by_rule.is_empty() && self.root_exemption.is_none() && self.warnings.is_empty()
    }

    /// Whether [`Self::files_inside_pruned_dirs`] is the whole count or a
    /// floor.
    ///
    /// False in two cases, and a consumer must treat both the same way: the
    /// deep count never ran (a real run does not pay for it, so the field is a
    /// vacuous 0), or it ran and hit [`DEEP_COUNT_BUDGET`]. A bare `u64` on a
    /// machine surface cannot say "at least", so every such surface must carry
    /// this flag next to the number (#279).
    pub fn files_inside_pruned_dirs_is_exact(&self) -> bool {
        self.deep_count_ran && self.deep_count_complete
    }

    /// Human-readable lines for the progress surface. Every number here was
    /// counted by this run; the ones that were deliberately not counted are
    /// named as such instead of being printed as zero.
    pub fn summary_lines(&self) -> Vec<String> {
        let mut out = Vec::new();
        for warning in &self.warnings {
            out.push(format!("ignore rules: {warning}"));
        }
        if let Some(reason) = &self.root_exemption {
            out.push(format!("ignore rules: {reason}"));
        }
        if self.by_rule.is_empty() {
            return out;
        }
        let mut headline = format!(
            "ignore rules: skipped {} file{} and pruned {} director{}",
            self.files_skipped,
            plural(self.files_skipped),
            self.dirs_pruned,
            if self.dirs_pruned == 1 { "y" } else { "ies" },
        );
        let deep_counted_dirs: u64 = self.by_rule.values().map(|c| c.dirs_deep_counted).sum();
        if self.deep_count_ran && deep_counted_dirs > 0 {
            // "non-hidden" is the whole of the claim: dotfiles are excluded
            // from the count, and directories the dotfile rule pruned are not
            // counted at all. Anything stronger — "files that would otherwise
            // have been indexed" — would be overclaiming, because ignore files
            // nested inside a pruned tree are never read (#279).
            headline.push_str(&format!(
                " ({}{} non-hidden file{} inside them)",
                if self.deep_count_complete {
                    ""
                } else {
                    "at least "
                },
                self.files_inside_pruned_dirs,
                plural(self.files_inside_pruned_dirs),
            ));
        } else if self.dirs_pruned > 0 {
            headline.push_str(" (contents never walked, so not counted)");
        }
        if self.ignore_files_read > 0 {
            headline.push_str(&format!(
                "; {} ignore file{} read",
                self.ignore_files_read,
                plural(self.ignore_files_read)
            ));
        }
        out.push(headline);

        let mut ranked: Vec<(&String, &RuleCount)> = self.by_rule.iter().collect();
        ranked.sort_by(|a, b| {
            let weight = |c: &RuleCount| c.files + c.files_inside_pruned_dirs + c.dirs;
            weight(b.1).cmp(&weight(a.1)).then_with(|| a.0.cmp(b.0))
        });
        const SHOWN: usize = 10;
        for (label, count) in ranked.iter().take(SHOWN) {
            let mut parts = Vec::new();
            if count.files > 0 {
                parts.push(format!("{} file{}", count.files, plural(count.files)));
            }
            if count.dirs > 0 {
                // Silent for the dotfile rule, whose directories are never
                // counted: "0 files inside" would be a false statement about
                // `.git/`, and "N files inside" was the inflated one.
                let inside = if self.deep_count_ran && count.dirs_deep_counted > 0 {
                    format!(
                        " ({}{} non-hidden file{} inside)",
                        if self.deep_count_complete {
                            ""
                        } else {
                            "at least "
                        },
                        count.files_inside_pruned_dirs,
                        plural(count.files_inside_pruned_dirs)
                    )
                } else {
                    String::new()
                };
                parts.push(format!(
                    "{} director{} pruned{inside}",
                    count.dirs,
                    if count.dirs == 1 { "y" } else { "ies" }
                ));
            }
            out.push(format!("ignore rules:   {label} — {}", parts.join(", ")));
        }
        if ranked.len() > SHOWN {
            out.push(format!(
                "ignore rules:   … and {} more rule{}",
                ranked.len() - SHOWN,
                plural((ranked.len() - SHOWN) as u64)
            ));
        }
        for skipped in &self.code_skipped {
            out.push(format!("ignore rules: skipped code file {skipped}"));
        }
        if self.code_skipped_omitted > 0 {
            out.push(format!(
                "ignore rules: … and {} more skipped code file{}",
                self.code_skipped_omitted,
                plural(self.code_skipped_omitted)
            ));
        }
        out
    }
}

fn plural(n: u64) -> &'static str {
    if n == 1 {
        ""
    } else {
        "s"
    }
}

/// Top-level folder of `path` relative to the canonical walk root.
///
/// A file with no parent under the root — `README.md` — is `"."`. A directory
/// the walk prunes at the root — `target/` — is that directory's own name, so
/// the folder summary can say the directory itself was dropped.
pub(crate) fn folder_key(root: &Path, path: &Path, is_dir: bool) -> String {
    let rel = path.strip_prefix(root).unwrap_or(path);
    let mut comps = rel.components();
    let Some(first) = comps.next() else {
        return ".".to_string();
    };
    if comps.next().is_none() && !is_dir {
        ".".to_string()
    } else {
        first.as_os_str().to_string_lossy().into_owned()
    }
}

#[derive(Default)]
struct Layer {
    xerj: Option<Gitignore>,
    git: Option<Gitignore>,
    exclude: Option<Gitignore>,
    /// This directory holds a `.git`, so it is the root of a checkout and the
    /// outward end of the git kinds' authority — see [`IgnoreStack::lookup`].
    /// `.git` is a directory in a normal clone and a file (`gitdir: …`) in a
    /// submodule or linked worktree; both are boundaries, so this is an
    /// `exists()` test rather than `is_dir()`.
    repo_root: bool,
}

/// A stack of ignore matchers, one entry per directory on the current
/// root-to-here path, plus the built-in defaults.
///
/// The caller drives it: [`IgnoreStack::enter_dir`] when a directory is
/// yielded, [`IgnoreStack::skip_dir`] / [`IgnoreStack::skip_file`] to ask
/// whether an entry survives.
pub struct IgnoreStack {
    opts: IgnoreOptions,
    root: PathBuf,
    layers: Vec<Layer>,
    defaults: Option<Gitignore>,
    budget: u64,
    pub report: IgnoreReport,
}

impl IgnoreStack {
    /// `root` must be the canonicalised root folder.
    pub fn new(root: &Path, opts: IgnoreOptions) -> Self {
        let mut stack = Self {
            opts,
            root: root.to_path_buf(),
            layers: Vec::new(),
            defaults: None,
            budget: DEEP_COUNT_BUDGET,
            report: IgnoreReport {
                deep_count_ran: opts.deep_count,
                ..IgnoreReport::default()
            },
        };
        if opts.enabled && opts.defaults {
            let defaults = stack.build_defaults(root);
            stack.defaults = defaults;
        }
        let exemption = stack.root_exemption(root);
        stack.report.root_exemption = exemption;
        stack
    }

    fn build_defaults(&mut self, root: &Path) -> Option<Gitignore> {
        let mut builder = GitignoreBuilder::new(root);
        for pattern in DEFAULT_IGNORE_PATTERNS {
            if let Err(err) = builder.add_line(None, pattern) {
                self.warn(format!("built-in rule `{pattern}` is not usable: {err}"));
            }
        }
        match builder.build() {
            Ok(gi) if gi.is_empty() => None,
            Ok(gi) => Some(gi),
            Err(err) => {
                self.warn(format!("built-in default rules are unusable: {err}"));
                None
            }
        }
    }

    /// Detect that the folder the user pointed at is itself ignored.
    ///
    /// We never act on it — pointing autoindex at `~/proj/target` is an
    /// explicit instruction and silently indexing nothing would be the worst
    /// possible answer. We only explain it, because the alternative is a user
    /// staring at a brain full of build output wondering why their ignore file
    /// did nothing.
    fn root_exemption(&self, root: &Path) -> Option<String> {
        if !self.opts.enabled {
            return None;
        }
        let name = root.file_name()?;
        let parent = root.parent()?;
        // The defaults are anchored at the root itself, so they cannot see the
        // root's own name. Re-anchor a copy one level up to ask the question.
        if self.opts.defaults {
            let mut builder = GitignoreBuilder::new(parent);
            for pattern in DEFAULT_IGNORE_PATTERNS {
                let _ = builder.add_line(None, pattern);
            }
            if let Ok(gi) = builder.build() {
                if let Match::Ignore(glob) = gi.matched(Path::new(name), true) {
                    return Some(format!(
                        "{} matches the built-in default rule `{}`, but you pointed autoindex at \
                         it, so it is being indexed — pass --no-default-ignores to silence this \
                         note",
                        root.display(),
                        glob.original()
                    ));
                }
            }
        }
        // Ignore files *above* the root are consulted for this note only, and
        // never to prune: git itself stops at the repository root, so we do
        // too (plus a hard level cap).
        let mut dir = parent.to_path_buf();
        for _ in 0..MAX_ANCESTOR_LEVELS {
            for file in [XERJIGNORE, GITIGNORE] {
                let path = dir.join(file);
                if !path.is_file() {
                    continue;
                }
                let mut builder = GitignoreBuilder::new(&dir);
                let _ = add_gitignore_file(&mut builder, &path);
                let Ok(gi) = builder.build() else { continue };
                if gi.is_empty() {
                    continue;
                }
                if let Match::Ignore(glob) = gi.matched_path_or_any_parents(root, true) {
                    return Some(format!(
                        "{} is ignored by `{}` in {}, but you pointed autoindex at it, so it is \
                         being indexed",
                        root.display(),
                        glob.original(),
                        path.display()
                    ));
                }
            }
            if dir.join(".git").exists() {
                break;
            }
            match dir.parent() {
                Some(up) => dir = up.to_path_buf(),
                None => break,
            }
        }
        None
    }

    /// Drop the layers of directories the walk has finished with.
    ///
    /// Must be called for **every** entry, not only directories. A depth-first
    /// walk interleaves files and subdirectories in readdir order, so after it
    /// descends into `a/` and comes back it can hand us `b.txt` at the shallower
    /// depth while `a/`'s layer is still on the stack. Without this, `a/`'s
    /// `.gitignore` would silently judge its parent's files.
    pub fn truncate_to(&mut self, depth: usize) {
        self.layers.truncate(depth);
    }

    /// Called for every directory the walk yields, root first, before any of
    /// its children. `depth` is walkdir's depth, so the stack is indexed by
    /// depth and a sibling directory replaces its predecessor's layer.
    pub fn enter_dir(&mut self, dir: &Path, depth: usize) {
        self.layers.truncate(depth);
        let layer = if self.opts.enabled {
            Layer {
                xerj: self.load(dir, dir.join(XERJIGNORE)),
                git: self.load(dir, dir.join(GITIGNORE)),
                // Per-repository excludes, which is where people put "junk
                // only I have". Loaded per directory so a nested checkout gets
                // its own.
                exclude: self.load(dir, dir.join(".git").join("info").join("exclude")),
                // One extra stat per directory entered, next to the three this
                // already pays, and it is the only way to know where one
                // checkout ends and another begins.
                repo_root: dir.join(".git").exists(),
            }
        } else {
            Layer::default()
        };
        self.layers.push(layer);
    }

    fn load(&mut self, dir: &Path, file: PathBuf) -> Option<Gitignore> {
        if !file.is_file() {
            return None;
        }
        let mut builder = GitignoreBuilder::new(dir);
        let (err, notes) = add_gitignore_file(&mut builder, &file);
        if let Some(err) = err {
            self.warn(format!("{}: {err}", file.display()));
        }
        for note in notes {
            self.warn(format!("{}: {note}", file.display()));
        }
        match builder.build() {
            Ok(gi) => {
                self.report.ignore_files_read += 1;
                if gi.is_empty() {
                    None
                } else {
                    Some(gi)
                }
            }
            Err(err) => {
                self.warn(format!("{} is not usable: {err}", file.display()));
                None
            }
        }
    }

    fn warn(&mut self, message: String) {
        if self.report.warnings.len() < MAX_WARNINGS {
            self.report.warnings.push(message);
        }
    }

    /// ripgrep's precedence, reproduced: the deepest match *per kind*, then
    /// the kinds ranked `.xerjignore` > `.gitignore` > `.git/info/exclude` >
    /// built-in defaults (`ignore-0.4.32/src/dir.rs:563-594` and `:679-684`).
    ///
    /// # The repository boundary
    ///
    /// The two git-owned kinds — `.gitignore` and `.git/info/exclude` — stop
    /// as soon as the outward walk has passed a directory holding a `.git`.
    /// This is `saw_git` in the reference implementation (`dir.rs:562`, `:579`,
    /// `:586`, `:593`) and it is git's own rule: the repository that owns a
    /// file is the one that decides whether it is ignored. A vendored or
    /// submoduled checkout inside a tree is a different repository, and the
    /// outer `.gitignore` has no authority over its contents — `git status` in
    /// the outer repo never even descends into it. Without the stop, a root
    /// `*.md` would hide the README of every vendored dependency.
    ///
    /// Two kinds deliberately do **not** stop at the boundary, because neither
    /// is git's to scope:
    ///
    /// * `.xerjignore` is XERJ's own file and its stated job is to govern the
    ///   folder you pointed at. One at the root is how a user says "not this,
    ///   anywhere below here" without editing anyone's `.gitignore`.
    /// * the built-in defaults are anchored at the root and apply throughout —
    ///   a `node_modules/` inside a vendored checkout is still build output.
    fn lookup(&self, path: &Path, is_dir: bool) -> Option<(bool, String)> {
        if !self.opts.enabled {
            return None;
        }
        let mut xerj = None;
        let mut git = None;
        let mut exclude = None;
        // Cleared once the walk outward leaves the checkout that owns `path`.
        let mut in_owning_repo = true;
        for layer in self.layers.iter().rev() {
            if xerj.is_none() {
                xerj = self.decide_with(layer.xerj.as_ref(), path, is_dir);
            }
            if in_owning_repo {
                if git.is_none() {
                    git = self.decide_with(layer.git.as_ref(), path, is_dir);
                }
                if exclude.is_none() {
                    exclude = self.decide_with(layer.exclude.as_ref(), path, is_dir);
                }
                // This layer's own files still count — it is the repository
                // root, not the far side of the boundary. Anything above it is
                // a different repository.
                if layer.repo_root {
                    in_owning_repo = false;
                }
            }
            if xerj.is_some() {
                // Nothing ranked lower can change the answer.
                break;
            }
        }
        xerj.or(git)
            .or(exclude)
            .or_else(|| self.decide_with(self.defaults.as_ref(), path, is_dir))
    }

    fn decide_with(
        &self,
        matcher: Option<&Gitignore>,
        path: &Path,
        is_dir: bool,
    ) -> Option<(bool, String)> {
        match matcher?.matched(path, is_dir) {
            Match::None => None,
            Match::Ignore(glob) => Some((true, self.label(glob))),
            Match::Whitelist(glob) => Some((false, self.label(glob))),
        }
    }

    fn label(&self, glob: &Glob) -> String {
        let from = glob
            .from()
            .map(|p| self.rel(p))
            .unwrap_or_else(|| "<built-in>".to_string());
        format!("{from}:{}", glob.original())
    }

    fn rel(&self, path: &Path) -> String {
        path.strip_prefix(&self.root)
            .unwrap_or(path)
            .to_string_lossy()
            .replace('\\', "/")
    }

    /// Ask whether a directory must be pruned. `Some(label)` means do not
    /// descend; the report has already been updated.
    pub fn skip_dir(&mut self, path: &Path) -> Option<String> {
        let (ignored, label) = self.lookup(path, true)?;
        if !ignored {
            return None;
        }
        self.record_dir(path, &label);
        Some(label)
    }

    /// Ask whether a file must be skipped.
    pub fn skip_file(&mut self, path: &Path) -> Option<String> {
        let (ignored, label) = self.lookup(path, false)?;
        if !ignored {
            return None;
        }
        self.record_file(path, &label);
        Some(label)
    }

    /// The dotfile skip is decided by the walker, not here, but it is reported
    /// through the same accounting so `--dry-run` explains every missing file
    /// with one mechanism.
    ///
    /// A hidden **directory** is recorded as pruned and nothing more: its
    /// contents are never deep-counted. Nothing under `.git/` or `.venv/` was
    /// ever a candidate for indexing — the dotfile rule had already excluded
    /// all of it — so counting those files would inflate
    /// [`IgnoreReport::files_inside_pruned_dirs`] with work that no run was
    /// ever going to do. On this repository that inflation was 97,731 files
    /// against a real exclusion of 273,441 (#279).
    pub fn record_hidden(&mut self, path: &Path, is_dir: bool) {
        if is_dir {
            self.report.dirs_pruned += 1;
            self.report
                .by_rule
                .entry(HIDDEN_RULE.to_string())
                .or_default()
                .dirs += 1;
            self.note_top(path, true, HIDDEN_RULE, |count| count.dirs += 1);
        } else {
            self.record_file(path, HIDDEN_RULE);
        }
    }

    /// #1844: a `.xerjignore` `!pattern` that names a hidden entry looks like it
    /// re-includes it, and `--help` documents `!pattern` as the re-include. It
    /// cannot: the dotfile rule is not an ignore rule (see [`HIDDEN_RULE`]) and
    /// runs before any ignore file is consulted. Saying so — once per entry,
    /// with the named-root workaround — replaces a silent no-op.
    ///
    /// Only `.xerjignore` is asked: a `.gitignore` `!.env.example` is about
    /// what git tracks, not a request to XERJ, and warning on it would fire on
    /// half the repositories in existence. Call it for the hidden entry the
    /// walker is about to skip, after [`IgnoreStack::truncate_to`].
    pub fn note_hidden_reinclude(&mut self, path: &Path, is_dir: bool) {
        if !self.opts.enabled {
            return;
        }
        let decision = self
            .layers
            .iter()
            .rev()
            .find_map(|layer| self.decide_with(layer.xerj.as_ref(), path, is_dir));
        let Some((false, label)) = decision else {
            return;
        };
        let kind = if is_dir { "directory" } else { "file" };
        self.warn(format!(
            "`{label}` re-includes the hidden {kind} {rel}, but hidden (dot-named) entries are \
             never indexed: that rule keeps .env and .ssh out, and no ignore file, !pattern or \
             --no-ignore lifts it. To index it, name it as its own root: `xerj autoindex {abs} \
             --prefix <name>`",
            rel = self.rel(path),
            abs = path.display(),
        ));
    }

    /// A symlink target outside the indexed root, also decided by the walker
    /// (it needs the canonical root, which this stack does not carry) and
    /// reported through the same accounting. See [`ESCAPED_ROOT_RULE`].
    pub fn record_symlink_escape(&mut self, path: &Path, is_dir: bool) {
        if is_dir {
            self.report.dirs_pruned += 1;
            self.report
                .by_rule
                .entry(ESCAPED_ROOT_RULE.to_string())
                .or_default()
                .dirs += 1;
            self.note_top(path, true, ESCAPED_ROOT_RULE, |count| count.dirs += 1);
        } else {
            self.record_file(path, ESCAPED_ROOT_RULE);
        }
    }

    /// A followed link that left the root through a dotted component.
    /// See [`HIDDEN_OUTSIDE_ROOT_RULE`].
    pub fn record_symlink_hidden_escape(&mut self, path: &Path, is_dir: bool) {
        if is_dir {
            self.report.dirs_pruned += 1;
            self.report
                .by_rule
                .entry(HIDDEN_OUTSIDE_ROOT_RULE.to_string())
                .or_default()
                .dirs += 1;
            self.note_top(path, true, HIDDEN_OUTSIDE_ROOT_RULE, |count| {
                count.dirs += 1;
            });
        } else {
            self.record_file(path, HIDDEN_OUTSIDE_ROOT_RULE);
        }
    }

    /// A symlink left unfollowed. See [`NOT_FOLLOWED_RULE`]. The warning is
    /// once per walk: the rule count already says how many links.
    pub fn record_symlink_not_followed(&mut self, path: &Path) {
        if !self.report.by_rule.contains_key(NOT_FOLLOWED_RULE) {
            self.warn(
                "symlink: not followed (pass --follow-symlinks to index a target inside \
                 this folder; a target outside it stays refused)"
                    .into(),
            );
        }
        self.record_file(path, NOT_FOLLOWED_RULE);
    }

    /// A followed entry that could not be resolved. See [`UNRESOLVED_LINK_RULE`].
    pub fn record_symlink_unresolved(&mut self, path: &Path, is_dir: bool) {
        if is_dir {
            self.report.dirs_pruned += 1;
            self.report
                .by_rule
                .entry(UNRESOLVED_LINK_RULE.to_string())
                .or_default()
                .dirs += 1;
            self.note_top(path, true, UNRESOLVED_LINK_RULE, |count| count.dirs += 1);
        } else {
            self.record_file(path, UNRESOLVED_LINK_RULE);
        }
    }

    /// The marker-gated generated-dir prune (`walk::MARKER_GENERATED_DIRS`)
    /// is also decided by the walker — the verdict needs the SIBLING marker
    /// file, which the per-directory matcher stack cannot see — and reported
    /// through the same accounting.
    pub fn record_marker_dir(&mut self, path: &Path, label: &str) {
        self.record_dir(path, label);
    }

    /// The file-level twin of [`Self::record_marker_dir`]: a built-in rule the
    /// walker decided (it needs a SIBLING or PARENT marker, which the matcher
    /// stack cannot see), reported through the same accounting.
    pub fn record_marker_file(&mut self, path: &Path, label: &str) {
        self.record_file(path, label);
    }

    /// Did an ignore file explicitly RE-INCLUDE this path (`!name`)? A
    /// walker-decided default asks before discarding, so that a negation in
    /// `.xerjignore`/`.gitignore` outranks a built-in rule the same way it
    /// outranks [`DEFAULT_IGNORE_PATTERNS`].
    pub fn is_reincluded(&self, path: &Path, is_dir: bool) -> bool {
        matches!(self.lookup(path, is_dir), Some((false, _)))
    }

    fn record_file(&mut self, path: &Path, label: &str) {
        self.report.files_skipped += 1;
        self.report
            .by_rule
            .entry(label.to_string())
            .or_default()
            .files += 1;
        self.note_code_skip(path, label);
        self.note_top(path, false, label, |count| count.files += 1);
    }

    /// A skipped `.ts`/`.tsx` (and every other code extension) is named. A
    /// directory prune never reaches here: the walk does not open the
    /// children, so the summary can only name the directory.
    fn note_code_skip(&mut self, path: &Path, label: &str) {
        let ext = path.extension().and_then(|ext| ext.to_str()).unwrap_or("");
        if !crate::extract::code::is_code_ext(ext) {
            return;
        }
        let shown = format!("{} — {label}", self.rel(path));
        if self.report.code_skipped.len() < CODE_SKIP_SHOWN {
            self.report.code_skipped.push(shown);
        } else {
            self.report.code_skipped_omitted += 1;
        }
    }

    fn record_dir(&mut self, path: &Path, label: &str) {
        let inside = self.count_inside(path);
        let deep = self.opts.deep_count;
        let entry = self.report.by_rule.entry(label.to_string()).or_default();
        entry.dirs += 1;
        entry.files_inside_pruned_dirs += inside;
        if deep {
            entry.dirs_deep_counted += 1;
        }
        self.report.dirs_pruned += 1;
        self.report.files_inside_pruned_dirs += inside;
        let rel = self.rel(path);
        if rel.contains('[') || rel.contains(']') {
            self.warn(format!(
                "pruned directory {rel} ({label}); files under it are not indexed"
            ));
        }
        self.note_top(path, true, label, |count| {
            count.dirs += 1;
            count.files_inside_pruned_dirs += inside;
            if deep {
                count.dirs_deep_counted += 1;
            }
        });
    }

    /// Charge one discard to the top-level folder [`folder_key`] names.
    fn note_top(
        &mut self,
        path: &Path,
        is_dir: bool,
        label: &str,
        update: impl FnOnce(&mut RuleCount),
    ) {
        let key = folder_key(&self.root, path, is_dir);
        let count = self
            .report
            .by_top
            .entry(key)
            .or_default()
            .entry(label.to_string())
            .or_default();
        update(count);
    }

    /// Only under `--dry-run`. Symlinks are never followed here whatever the
    /// run's `--follow-symlinks` setting: this is an accounting pass over a
    /// directory we have already decided not to index, and it must not be able
    /// to wander outside it or loop.
    ///
    /// # Exactly what this counts
    ///
    /// Regular files under `dir`, excluding every dot-named file and the whole
    /// subtree of every dot-named directory — the dotfile rule, applied here
    /// too, because those paths were never indexable. That is the figure the
    /// reporting prints and the phrase it prints it with ("N non-hidden files
    /// inside them"). Two things it is deliberately *not*:
    ///
    /// * It is **not** a promise about what a `--no-ignore` run would have
    ///   indexed. Ignore files nested *inside* the pruned tree are not
    ///   consulted — the point of pruning is to never read that tree — so a
    ///   `node_modules/.gitignore` excluding some of its own contents would
    ///   make the real figure smaller than this one.
    /// * It is **not** guaranteed complete. [`DEEP_COUNT_BUDGET`] caps the
    ///   traversal; past it [`IgnoreReport::deep_count_complete`] goes false
    ///   and every surface says "at least".
    ///
    /// Callers that publish the number to a machine must publish
    /// [`IgnoreReport::files_inside_pruned_dirs_is_exact`] beside it.
    fn count_inside(&mut self, dir: &Path) -> u64 {
        if !self.opts.deep_count {
            return 0;
        }
        let mut files = 0;
        let walker = walkdir::WalkDir::new(dir)
            .follow_links(false)
            .min_depth(1)
            .into_iter()
            .filter_entry(|e| !is_hidden_name(e.file_name()));
        for entry in walker {
            if self.budget == 0 {
                self.report.deep_count_complete = false;
                break;
            }
            self.budget -= 1;
            if entry.is_ok_and(|e| e.file_type().is_file()) {
                files += 1;
            }
        }
        files
    }
}

/// Read one ignore file the way `GitignoreBuilder::add` does, then add a
/// literal-bracket twin of every line that contains an unescaped `[` or `]`.
///
/// The twin is inserted immediately after its source line, so a later line
/// in the same file still wins. `*.[ch]` keeps matching `a.c`; the twin
/// only additionally matches a name that contains the brackets.
///
/// Returns the first error (other lines are still added) and one note per
/// route-like class, for the ignore summary. The error is a string because
/// `ignore::Error`'s path and line tagging is crate-private; the line number
/// is in the text instead.
fn add_gitignore_file(
    builder: &mut GitignoreBuilder,
    path: &Path,
) -> (Option<String>, Vec<String>) {
    let file = match File::open(path) {
        Ok(file) => file,
        Err(err) => return (Some(err.to_string()), Vec::new()),
    };
    let reader = BufReader::new(file);
    let mut first_err: Option<String> = None;
    let mut notes = Vec::new();
    for (i, line) in reader.lines().enumerate() {
        let lineno = i + 1;
        let line = match line {
            Ok(line) => line,
            Err(err) => {
                if first_err.is_none() {
                    first_err = Some(format!("line {lineno}: {err}"));
                }
                break;
            }
        };
        // `GitignoreBuilder::add` strips a leading BOM on line 1 only.
        let line = if i == 0 {
            line.trim_start_matches('\u{feff}').to_string()
        } else {
            line
        };
        if let Err(err) = builder.add_line(Some(path.to_path_buf()), &line) {
            if first_err.is_none() {
                first_err = Some(format!("line {lineno}: {err}"));
            }
        }
        // A `#` comment is not a pattern. Twisting its brackets would turn
        // the comment into a pattern (`\#…` is not a comment).
        if line.starts_with('#') {
            continue;
        }
        let Some(twin) = literal_bracket_twin(&line) else {
            continue;
        };
        if let Some(note) = route_class_note(&line) {
            notes.push(note);
        }
        if let Err(err) = builder.add_line(Some(path.to_path_buf()), &twin) {
            if first_err.is_none() {
                first_err = Some(format!("line {lineno}: {err}"));
            }
        }
    }
    (first_err, notes)
}

/// The same line with every unescaped `[` and `]` prefixed by `\`.
///
/// `None` when the line has no unescaped bracket, including a line that is
/// already escaped (`app/\[locale\]/`).
fn literal_bracket_twin(line: &str) -> Option<String> {
    let mut out = String::with_capacity(line.len() + 4);
    let mut chars = line.chars().peekable();
    let mut changed = false;
    while let Some(c) = chars.next() {
        if c == '\\' {
            out.push('\\');
            if let Some(next) = chars.next() {
                out.push(next);
            }
            continue;
        }
        if c == '[' || c == ']' {
            out.push('\\');
            changed = true;
        }
        out.push(c);
    }
    changed.then_some(out)
}

/// Note for a class that is shaped like a route segment (`[locale]`,
/// `[...slug]`, or `[id]` inside a path). `*.[ch]` is a real class and
/// stays quiet: it has no `/`, and the body is shorter than three
/// characters.
fn route_class_note(line: &str) -> Option<String> {
    let has_slash = line.contains('/');
    let bodies = route_like_class_bodies(line, has_slash);
    if bodies.is_empty() {
        return None;
    }
    let names = bodies
        .iter()
        .map(|body| format!("[{body}]"))
        .collect::<Vec<_>>()
        .join(", ");
    Some(format!(
        "`{line}` reads {names} as a character class, not as a directory name. Also applying the pattern to that literal name, so a route folder such as [locale] is not dropped for this reason"
    ))
}

fn route_like_class_bodies(line: &str, pattern_has_slash: bool) -> Vec<String> {
    let mut bodies = Vec::new();
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            chars.next();
            continue;
        }
        if c != '[' {
            continue;
        }
        let mut body = String::new();
        let mut closed = false;
        while let Some(next) = chars.next() {
            if next == '\\' {
                if let Some(escaped) = chars.next() {
                    body.push(escaped);
                }
                continue;
            }
            if next == ']' {
                closed = true;
                break;
            }
            body.push(next);
        }
        if closed && is_route_like_class(&body, pattern_has_slash) {
            bodies.push(body);
        }
    }
    bodies
}

fn is_route_like_class(body: &str, pattern_has_slash: bool) -> bool {
    if body.contains('-') || body.contains('!') || body.contains('^') {
        return false;
    }
    // `[[...slug]]` yields a first class body of `[...slug`.
    let ident = body.strip_prefix('[').unwrap_or(body);
    let ident = ident.strip_prefix("...").unwrap_or(ident);
    let min = if pattern_has_slash { 2 } else { 3 };
    ident.len() >= min && ident.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}

