        assert_eq!(kept, vec!["keep.log", "src/main.rs"], "{kept:?}");
        // `*.log` has no slash, so it matches at any depth — git's rule.
        assert!(
            report.by_rule.contains_key(".gitignore:*.log"),
            "{report:?}"
