        );
    }

    const ROUTE_TSX: &str =
        "app/[locale]/booking/[token]/temple-selection/TempleSelectionWrapper.tsx";

    /// #2357: a Next.js route directory is the literal name `[locale]`.
    /// Git reads that text as a character class, so a whitelist written the
    /// way the directory is named does not re-include it and `*` keeps the
    /// sources out of the index. The literal twin re-includes them. A plain
    /// `*.[ch]` class is unchanged.
    #[test]
    fn a_bracket_route_whitelist_includes_the_literal_directory() {
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        write(
            root,
            ".gitignore",
            "*\n!app/\n!app/[locale]/\n!app/[locale]/**\n!README.md\n!lib/\n!lib/**\n!data.json\n",
        );
        write(
            root,
            ROUTE_TSX,
            "export function TempleSelectionWrapper() {}\n",
        );
        write(root, "README.md", "# notes\n");
        write(root, "lib/items.json", "{}\n");
        write(root, "data.json", "{}\n");
        write(root, "src/plain.ts", "export const n = 1;\n");

        let (kept, report) = survivors(root, IgnoreOptions::default());
        assert!(
            kept.iter().any(|p| p == ROUTE_TSX),
            "bracketed tsx must be indexed, got {kept:?}"
        );
        assert!(kept.iter().any(|p| p == "README.md"), "{kept:?}");
        assert!(kept.iter().any(|p| p == "data.json"), "{kept:?}");
        assert!(kept.iter().any(|p| p == "lib/items.json"), "{kept:?}");
        assert!(
            !kept.iter().any(|p| p == "src/plain.ts"),
            "`*` still ignores a path the whitelist did not name: {kept:?}"
        );
        let lines = report.summary_lines().join("\n");
        assert!(
            lines.contains("character class"),
            "the pattern must be explained: {lines}"
        );
        assert!(
            lines.contains("[locale]"),
            "the directory name must be in the note: {lines}"
        );
    }

    /// No ignore file at all: the brackets are only in the path, and the
    /// walk must keep the source. This is the case a default Next.js
    /// `.gitignore` (which never names `[locale]`) already had.
    #[test]
    fn a_bracket_route_with_no_ignore_file_is_walked() {
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        write(root, ROUTE_TSX, "export const getPujaName = () => \"a\";\n");
        write(root, "src/plain.ts", "export const n = 1;\n");
        let (kept, report) = survivors(root, IgnoreOptions::default());
        assert!(kept.iter().any(|p| p == ROUTE_TSX), "{kept:?}");
        assert!(kept.iter().any(|p| p == "src/plain.ts"), "{kept:?}");
        assert!(
            !report
                .summary_lines()
                .iter()
                .any(|l| l.contains("character class")),
            "{:?}",
            report.summary_lines()
        );
    }

    /// An author who already escaped the brackets meant the literal
    /// directory. The twin must not unescape that into a class, and the
    /// directory stays ignored.
    #[test]
    fn an_escaped_bracket_pattern_still_ignores_the_literal_directory() {
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        write(root, ".gitignore", "app/\\[locale\\]/\n");
        write(root, ROUTE_TSX, "export const n = 1;\n");
        write(root, "src/plain.ts", "export const n = 1;\n");
        let (kept, report) = survivors(root, IgnoreOptions::default());
        assert!(
            !kept.iter().any(|p| p.contains("[locale]")),
            "escaped pattern must ignore the route dir: {kept:?}"
        );
        assert!(kept.iter().any(|p| p == "src/plain.ts"), "{kept:?}");
        assert!(
            report
                .summary_lines()
                .iter()
                .any(|l| l.contains("pruned directory") && l.contains("[locale]")),
            "{:?}",
            report.summary_lines()
        );
    }

    /// `*.[ch]` is a character class. The literal twin must not stop it
    /// matching `.c` and `.h`, and a `.rs` file stays.
    #[test]
    fn a_character_class_extension_still_ignores_those_extensions() {
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        write(root, ".gitignore", "*.[ch]\n");
        write(root, "foo.c", "int c;\n");
        write(root, "foo.h", "int h;\n");
        write(root, "foo.rs", "fn r() {}\n");
        let (kept, report) = survivors(root, IgnoreOptions::default());
        assert_eq!(kept, vec!["foo.rs"], "{kept:?}");
        assert!(
            !report
                .summary_lines()
                .iter()
                .any(|l| l.contains("character class")),
            "a short class with no slash is not a route folder: {:?}",
            report.summary_lines()
        );
        let lines = report.summary_lines().join("\n");
        assert!(lines.contains("skipped code file foo.c"), "{lines}");
        assert!(lines.contains("skipped code file foo.h"), "{lines}");
        assert!(
            !lines.contains("foo.rs"),
            "the file that was kept is not a skip: {lines}"
        );
    }

    /// A code file the rules still skip is named, with the rule. `*.tsx`
    /// has no bracket, so this is the report the walk owes when the file
    /// really is excluded.
    #[test]
    fn a_skipped_tsx_file_is_named_with_its_rule() {
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        write(root, ".gitignore", "*.tsx\n");
        write(root, ROUTE_TSX, "export const n = 1;\n");
        write(root, "keep.ts", "export const n = 1;\n");
        let (kept, report) = survivors(root, IgnoreOptions::default());
        assert_eq!(kept, vec!["keep.ts"], "{kept:?}");
        let lines = report.summary_lines().join("\n");
        assert!(
            lines.contains("skipped code file") && lines.contains(ROUTE_TSX),
            "{lines}"
        );
        assert!(
            lines.contains(".gitignore:*.tsx"),
            "the rule must be on the line: {lines}"
        );
    }

    /// The twin is inserted after its source line, not at the end of the
    /// file. A later `*.tsx` still excludes the route source; a `.ts` the
    /// whitelist named stays.
    #[test]
    fn a_later_rule_still_beats_the_literal_bracket_twin() {
        let dir = tempfile::TempDir::new().unwrap();
        let root = dir.path();
        write(
            root,
            ".gitignore",
            "*\n!app/\n!app/[locale]/\n!app/[locale]/**\n*.tsx\n",
        );
        write(root, ROUTE_TSX, "export const n = 1;\n");
        write(root, "app/[locale]/keep.ts", "export const n = 1;\n");
        let (kept, report) = survivors(root, IgnoreOptions::default());
        assert!(kept.iter().any(|p| p == "app/[locale]/keep.ts"), "{kept:?}");
        assert!(
            !kept.iter().any(|p| p == ROUTE_TSX),
            "a later *.tsx must still win: {kept:?}"
        );
        let lines = report.summary_lines().join("\n");
        assert!(
            lines.contains("skipped code file") && lines.contains(ROUTE_TSX),
            "{lines}"
        );
        assert!(lines.contains(".gitignore:*.tsx"), "{lines}");
    }

    #[test]
    fn literal_bracket_twin_escapes_unescaped_brackets_only() {
        assert_eq!(
            literal_bracket_twin("!app/[locale]/**").as_deref(),
            Some("!app/\\[locale\\]/**")
        );
        assert_eq!(literal_bracket_twin("app/\\[locale\\]/"), None);
        assert_eq!(
            literal_bracket_twin("*.[ch]").as_deref(),
            Some("*.\\[ch\\]")
        );
        // Comments are filtered by `add_gitignore_file` before this runs.
        // The helper itself only escapes brackets.
        assert_eq!(
            literal_bracket_twin("# [locale]").as_deref(),
            Some("# \\[locale\\]")
        );
        assert!(route_class_note("*.[ch]").is_none());
        assert!(route_class_note("app/[locale]/**")
            .unwrap()
            .contains("[locale]"));
        assert!(route_class_note("app/[id]/page.tsx").is_some());
    }
}

//! Real-HTTP end-to-end coverage for incremental corpus generations.
//!
//! The endpoint below is deliberately stateful. It applies bulk index/update
//! actions, delete-by-query, and exact count searches so `run_index` traverses
//! the same HTTP client and validation barriers as a real server.

use super::*;
use std::collections::{BTreeMap, HashMap};
use std::fs;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;

static HTTP_E2E_LOCK: Mutex<()> = Mutex::new(());

#[derive(Default)]
struct HttpState {
    docs: HashMap<(String, String), Value>,
    requests: Vec<(String, String)>,
    /// Every `POST …/_search` body, in order (#1183): the dataset read-back's
    /// agg-free shape and its sorted time-bound queries are asserted against
    /// these.
    search_bodies: Vec<Value>,
    data_bulk_requests: usize,
    fail_next_data_bulk: bool,
    /// Apply the first half of the next data bulk's items and *then* report
    /// `errors: true`. This is the dangerous backend shape the legacy
    /// replacement transaction was hardened against (visibility changed, but
    /// the durable record must not be): `no_graph` corpora take the generated
    /// executor now, so the shape has to be proven here too.
    partially_apply_next_data_bulk: bool,
    fail_embedding_identity: bool,
    /// #1971: answer semantic `exists` read-backs with no matches while
    /// retaining the published records and catalog for refusal/resume checks.
    hide_semantic_matches: bool,
    stop: bool,
    embedding_identity_sha256: String,
    saw_dataset_mapping_update: bool,
    saw_catalog_mapping_update: bool,
    /// Opt-in (#755/#760): the fields this catalog already holds as `text`,
    /// standing in for an older-build (v1.0.0-rc.15..rc.67) catalog. A catalog
    /// `_mapping` PUT that still declares one of them fails with the exact
    /// `field [X] already exists as [text]` conflict a real engine produces;
    /// a PUT that no longer declares any of them is acknowledged, exactly like
    /// the engine. Empty by default — every other test's faithful-accept
    /// behaviour is unchanged.
    ///
    /// #890: it also governs how a `term` on such a field MATCHES, in searches
    /// and in delete-by-query alike. A legacy field is not merely undeclarable,
    /// it is analyzed, and that is the whole defect — see [`term_matches`].
    legacy_text_catalog_fields: Vec<String>,
    /// Opt-in (#755): fail the catalog `_mapping` PUT with a 503 instead. Not a
    /// type conflict, so it must still abort the run.
    catalog_mapping_unavailable: bool,
    /// The `properties` object of the last catalog `_mapping` PUT the endpoint
    /// ACKNOWLEDGED — what a legacy catalog actually ends up declaring.
    installed_catalog_properties: Option<Value>,
    /// How many catalog `_mapping` PUTs were attempted (the drop-and-retry
    /// loop's cost).
    catalog_mapping_puts: usize,
    /// Opt-in (#929): a DATASET `_mapping` PUT whose index name contains one of
    /// these is refused with the 400 a real engine returns for a field it
    /// cannot map — the literal response that aborted the 48,533-file run.
    /// A refusal is a statement about that one dataset.
    refused_dataset_mappings: Vec<String>,
    /// Opt-in (#929): the same selection, answered 503 instead. That is the
    /// endpoint failing, says nothing about the dataset, and must still abort.
    unavailable_dataset_mappings: Vec<String>,
    /// Every dataset index a `_mapping` PUT was attempted for, in order.
    dataset_mapping_puts: Vec<String>,
    /// Properties installed for a dataset index: the create body the first
    /// time the index is seen, then additive `_mapping` merges. A later
    /// `_mapping` whose `type` disagrees with what is already stored is the
    /// engine's type-change refusal (`field [X] already exists as [old],
    /// cannot add [new]`). A create of an index that already exists is
    /// ignored, the way `Es::ensure_index` swallows "exists" without
    /// re-sending the body.
    installed_dataset_properties: HashMap<String, serde_json::Map<String, Value>>,
    /// Opt-in (#931): fail the Nth data bulk (1-based) the way
    /// `fail_next_data_bulk` fails the next one. Lets a replay be interrupted
    /// AFTER some operations committed, which is the only state in which
    /// "count what remains" differs from "count everything".
    fail_data_bulk_number: Option<usize>,
    /// Opt-in (#944): apply the even-position actions of the next data bulk
    /// and answer the odd-position ones with the per-item 429 the engine's
    /// memory circuit breaker produces while it is engaged. The client must
    /// re-send exactly the odd ones.
    throttle_next_data_bulk_odd_items: bool,
    /// Opt-in (#944, second shape): answer the next N data bulks HTTP 429 as
    /// a whole, applying nothing — how the engine answers when its memory
    /// circuit breaker rejects the request, and the literal end of the resumed
    /// full-corpus run (`error: _bulk: HTTP 429 Too Many Requests`).
    throttle_whole_data_bulks: usize,
    /// Action count of every data bulk answered, in order — how a test proves
    /// a re-send carried only the rejected items.
    data_bulk_item_counts: Vec<usize>,
    /// Opt-in (#955): the engine's `limits.max_actions_per_bulk`. A `_bulk` of
    /// more than twice this many lines — data or catalog — is refused whole,
    /// before anything is applied, with the engine's literal answer: HTTP 200
    /// carrying ONE item of status 413. That response ended the 48,533-file
    /// run in `finalize-catalog` after every operation had been applied.
    max_actions_per_bulk: Option<usize>,
    /// Line count of every bulk refused by `max_actions_per_bulk`, in order.
    oversize_bulks_refused: Vec<usize>,
    /// Line count of every bulk that got past `max_actions_per_bulk`.
    bulk_line_counts: Vec<usize>,
    /// #933 opt-in: hold each DATA bulk for this many milliseconds before
    /// applying it, outside the state lock. A serial client still sends one
    /// request at a time, so for every existing test this changes nothing;
    /// a multi-worker replay is forced into observable overlap.
    data_bulk_delay_ms: u64,
    /// #933: data bulks currently inside their delay window, and the most
    /// that were ever inside it together. `1` forever is the fingerprint of
    /// a serial index phase.
    in_flight_data_bulks: usize,
    max_concurrent_data_bulks: usize,
    /// #2314: the next N catalog searches that filter on `file_key` omit the
    /// last hit and report that shorter total. The visibility race four
    /// identical files hit. The counter, not refresh, clears it, so the
    /// recount after refresh sees the full set.
    short_catalog_file_key_pages: usize,
}

struct HttpEndpoint {
    url: String,
    state: Arc<Mutex<HttpState>>,
    join: Option<thread::JoinHandle<()>>,
}

impl HttpEndpoint {
    fn start() -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        let state = Arc::new(Mutex::new(HttpState {
            embedding_identity_sha256: "a".repeat(64),
            ..HttpState::default()
        }));
        let server_state = Arc::clone(&state);
        let join = thread::spawn(move || loop {
            match listener.accept() {
                Ok((stream, _)) => {
                    // BSD/macOS: accepted sockets inherit the listener's
                    // O_NONBLOCK; the handler does blocking reads.
                    stream.set_nonblocking(false).unwrap();
                    // #933: one thread per connection, so the parallel
                    // durable replay can be served the way a real node is —
                    // several requests inside the endpoint at once. Every
                    // handler touches `HttpState` only through its Mutex and
                    // never sleeps while holding it, and a serial client
                    // still has at most one connection open, so every other
                    // test sees the endpoint it always had.
                    let server_state = Arc::clone(&server_state);
                    thread::spawn(move || handle_http(stream, &server_state));
                }
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    if server_state.lock().unwrap().stop {
                        break;
                    }
                    thread::yield_now();
                }
                Err(error) => panic!("HTTP test endpoint accept failed: {error}"),
            }
        });
        Self {
            url,
            state,
            join: Some(join),
        }
    }

    fn data_docs(&self) -> Vec<Value> {
        self.state
            .lock()
            .unwrap()
            .docs
            .iter()
            .filter(|((index, _), _)| index != catalog::CATALOG_INDEX)
            .map(|(_, doc)| doc.clone())
            .collect()
    }

    /// Every `POST …/_search` body the endpoint has seen, in order (#1183).
    fn search_bodies(&self) -> Vec<Value> {
        self.state.lock().unwrap().search_bodies.clone()
    }

    /// One catalog document by id, from the fake's stored docs.
    fn catalog_doc(&self, id: &str) -> Option<Value> {
        self.state
            .lock()
            .unwrap()
            .docs
            .get(&(catalog::CATALOG_INDEX.to_string(), id.to_string()))
            .cloned()
    }

    fn data_bulk_requests(&self) -> usize {
        self.state.lock().unwrap().data_bulk_requests
    }

    /// Properties the fake has installed for one dataset index (#2176).
    fn dataset_properties(&self, index: &str) -> Option<Value> {
        self.state
            .lock()
            .unwrap()
            .installed_dataset_properties
            .get(index)
            .map(|properties| Value::Object(properties.clone()))
    }

    /// #755: the catalog mapping the endpoint finally acknowledged.
    fn installed_catalog_properties(&self) -> Value {
        self.state
            .lock()
            .unwrap()
            .installed_catalog_properties
            .clone()
            .expect("no catalog _mapping PUT was acknowledged")
    }

    /// #755: every catalog document the run published.
    fn catalog_docs(&self) -> Vec<Value> {
        self.state
            .lock()
            .unwrap()
            .docs
            .iter()
            .filter(|((index, _), _)| index == catalog::CATALOG_INDEX)
            .map(|(_, doc)| doc.clone())
            .collect()
    }
}

impl Drop for HttpEndpoint {
    fn drop(&mut self) {
        self.state.lock().unwrap().stop = true;
        let _ = TcpStream::connect(self.url.trim_start_matches("http://"));
        self.join.take().unwrap().join().unwrap();
    }
}

fn handle_http(mut stream: TcpStream, state: &Arc<Mutex<HttpState>>) {
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut request_line = String::new();
    if reader.read_line(&mut request_line).unwrap() == 0 {
        return;
    }
    let mut content_length = 0usize;
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        if line == "\r\n" || line.is_empty() {
            break;
        }
        if let Some(value) = line
            .to_ascii_lowercase()
            .strip_prefix("content-length:")
            .map(str::trim)
        {
            content_length = value.parse().unwrap();
        }
    }
    let mut body = vec![0; content_length];
    reader.read_exact(&mut body).unwrap();
    let mut parts = request_line.split_whitespace();
    let method = parts.next().unwrap_or("");
    let path = parts.next().unwrap_or("");
    state
        .lock()
        .unwrap()
        .requests
        .push((method.to_owned(), path.to_owned()));

    let (status, response) = if method == "GET" && path == "/v1/embedding/identity" {
        let locked = state.lock().unwrap();
        if locked.fail_embedding_identity {
            (
                500,
                json!({"error": {
                    "type": "injected_identity_failure",
                    "reason": "genesis recovery boundary"
                }}),
            )
        } else {
            (
                200,
                json!({"data": {
                    "version": 1,
                    "backend": "lexical",
                    "identity_sha256": locked.embedding_identity_sha256.clone(),
                    "dimensions": 384,
                    "semantic_contract": "semantic_text-derived-vector.v1",
                    "resumable": true
                }, "took_ms": 0, "request_id": "incremental-http-test"}),
            )
        }
    } else if method == "POST" && path == "/_bulk" {
        let locked = state.lock().unwrap();
        let writes_data = body.split(|byte| *byte == b'\n').any(|line| {
            serde_json::from_slice::<Value>(line)
                .ok()
                .and_then(|action| {
                    action
                        .pointer("/index/_index")
                        .or_else(|| action.pointer("/update/_index"))
                        .and_then(Value::as_str)
                        .map(|index| index != catalog::CATALOG_INDEX)
                })
                .unwrap_or(false)
        });
        assert!(
            locked.saw_catalog_mapping_update
                && (!writes_data || locked.saw_dataset_mapping_update),
            "bulk publication preceded exact generation mapping updates"
        );
        drop(locked);
        bulk_http(&body, state)
    } else if method == "POST" && path.contains("/_delete_by_query") {
        let deleted = delete_http(path, &body, state);
        (200, json!({"deleted": deleted, "failures": []}))
    } else if method == "POST" && path.ends_with("/_mget") {
        (200, mget_http(path, &body, state))
    } else if method == "POST" && path.ends_with("/_search") {
        if let Ok(query) = serde_json::from_slice::<Value>(&body) {
            state.lock().unwrap().search_bodies.push(query);
        }
        (200, search_http(path, &body, state))
    } else if method == "GET" && path.ends_with("/_count") {
        let index = path.trim_start_matches('/').trim_end_matches("/_count");
        let count = state
            .lock()
            .unwrap()
            .docs
            .keys()
            .filter(|(candidate, _)| candidate == index)
            .count();
        (200, json!({"count": count}))
    } else if method == "PUT" {
        let value: Value = serde_json::from_slice(&body).unwrap_or(Value::Null);
        let mut locked = state.lock().unwrap();
        // #755: the first still-declared field this catalog already holds as
        // `text`, if any — the engine reports one conflict per request.
        let mut conflict: Option<String> = None;
        let mut unavailable = false;
        let mut refused_dataset: Option<String> = None;
        let mut type_conflict: Option<String> = None;
        if path.ends_with("/_mapping") {
            assert!(value.get("properties").is_some());
            assert!(value.get("mappings").is_none());
            if path.starts_with(&format!("/{}/", catalog::CATALOG_INDEX)) {
                locked.saw_catalog_mapping_update = true;
                locked.catalog_mapping_puts += 1;
                unavailable = locked.catalog_mapping_unavailable;
                let declared = value["properties"].as_object().cloned().unwrap_or_default();
                conflict = locked
                    .legacy_text_catalog_fields
                    .iter()
                    .find(|field| declared.contains_key(field.as_str()))
                    .cloned();
                if conflict.is_none() && !unavailable {
                    locked.installed_catalog_properties = Some(Value::Object(declared));
                }
            } else {
                locked.saw_dataset_mapping_update = true;
                let index = path
                    .trim_start_matches('/')
                    .trim_end_matches("/_mapping")
                    .to_owned();
                let selected = |needles: &[String]| {
                    needles.iter().any(|needle| index.contains(needle.as_str()))
                };
                unavailable = selected(&locked.unavailable_dataset_mappings);
                if selected(&locked.refused_dataset_mappings) {
                    refused_dataset = Some(index.clone());
                }
                if refused_dataset.is_none() && !unavailable {
                    let incoming = value["properties"].as_object().cloned().unwrap_or_default();
                    type_conflict = apply_dataset_mapping(&mut locked, &index, &incoming);
                }
                locked.dataset_mapping_puts.push(index);
            }
        } else {
            assert!(value.pointer("/mappings/properties").is_some());
            assert!(value.get("properties").is_none());
            let index = path.trim_start_matches('/');
            if !index.is_empty() && index != catalog::CATALOG_INDEX {
                remember_dataset_create(&mut locked, index, &value);
            }
        }
        if let Some(index) = refused_dataset {
            // Byte for byte the shape of the refusal in #929.
            let reason = format!(
                "nested semantic_text field [{index}.unmappable] is not supported; map \
                 semantic_text as a top-level field"
            );
            (
                400,
                json!({
                    "error": {
                        "root_cause": [{"type": "mapper_parsing_exception", "reason": reason}],
                        "type": "mapper_parsing_exception",
                        "reason": reason
                    },
                    "status": 400
                }),
            )
        } else if unavailable {
            (
                503,
                json!({"error": {"type": "unavailable_shards_exception", "reason": "no node"}}),
            )
        } else if let Some(field) = conflict {
            let reason = format!("field [{field}] already exists as [text], cannot add [keyword]");
            (
                400,
                json!({
                    "error": {
                        "root_cause": [{"type": "mapper_parsing_exception", "reason": reason}],
                        "type": "mapper_parsing_exception",
                        "reason": reason
                    },
                    "status": 400
                }),
            )
        } else if let Some(reason) = type_conflict {
            // Same shape as the catalog conflict above, and the same words
            // `xerj-api` uses when `PUT /_mapping` changes a field's type
            // (`es_compat.rs`). `update_mapping` does not swallow a body that
            // contains "exists"; `ensure_index` does, which is why a create
            // of an existing index never reaches this branch.
            (
                400,
                json!({
                    "error": {
                        "root_cause": [{"type": "mapper_parsing_exception", "reason": reason}],
                        "type": "mapper_parsing_exception",
                        "reason": reason
                    },
                    "status": 400
                }),
            )
        } else {
            (200, json!({"acknowledged": true}))
        }
    } else {
        // Readiness, index creation/mapping, and refresh.
        (200, json!({"acknowledged": true}))
    };
    let bytes = response.to_string();
    write!(
        stream,
        "HTTP/1.1 {status} {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        match status {
            200 => "OK",
            400 => "Bad Request",
            429 => "Too Many Requests",
            503 => "Service Unavailable",
            _ => "Internal Server Error",
        },
        bytes.len(),
        bytes
    )
    .unwrap();
}

/// Store the create-body properties the first time an index is seen.
/// A later create is the "index exists" case: the body is not applied.
fn remember_dataset_create(state: &mut HttpState, index: &str, body: &Value) {
    if state.installed_dataset_properties.contains_key(index) {
        return;
    }
    let Some(properties) = body
        .pointer("/mappings/properties")
        .and_then(Value::as_object)
        .cloned()
    else {
        return;
    };
    state
        .installed_dataset_properties
        .insert(index.to_owned(), properties);
}

/// Merge a dataset `_mapping` into the stored properties, or refuse a type
/// change. Returns the engine's reason when a stored field's `type` would
/// change; the stored map is left untouched in that case.
fn apply_dataset_mapping(
    state: &mut HttpState,
    index: &str,
    incoming: &serde_json::Map<String, Value>,
) -> Option<String> {
    if let Some(existing) = state.installed_dataset_properties.get(index) {
        for (name, spec) in incoming {
            let (Some(old), Some(new)) = (
                existing
                    .get(name)
                    .and_then(|value| value.get("type"))
                    .and_then(Value::as_str),
                spec.get("type").and_then(Value::as_str),
            ) else {
                continue;
            };
            if old != new {
                return Some(format!(
                    "field [{name}] already exists as [{old}], cannot add [{new}]"
                ));
            }
        }
    }
    let slot = state
        .installed_dataset_properties
        .entry(index.to_owned())
        .or_default();
    for (name, spec) in incoming {
        slot.entry(name.clone()).or_insert_with(|| spec.clone());
    }
    None
}

fn bulk_http(body: &[u8], state: &Arc<Mutex<HttpState>>) -> (u16, Value) {
    let lines: Vec<&[u8]> = body
        .split(|byte| *byte == b'\n')
        .filter(|line| !line.is_empty())
        .collect();
    let is_data = lines.iter().step_by(2).any(|line| {
        serde_json::from_slice::<Value>(line)
            .ok()
            .and_then(|action| {
                action
                    .pointer("/index/_index")
                    .or_else(|| action.pointer("/update/_index"))
                    .and_then(Value::as_str)
                    .map(|index| index != catalog::CATALOG_INDEX)
            })
            .unwrap_or(false)
    });
    // #933: the artificial hold, OUTSIDE the state lock so concurrent data
    // bulks hold at the same time — the overlap a parallel replay produces
    // and a serial one never can.
    let hold_ms = { state.lock().unwrap().data_bulk_delay_ms };
    if is_data && hold_ms > 0 {
        {
            let mut locked = state.lock().unwrap();
            locked.in_flight_data_bulks += 1;
            locked.max_concurrent_data_bulks = locked
                .max_concurrent_data_bulks
                .max(locked.in_flight_data_bulks);
        }
        thread::sleep(std::time::Duration::from_millis(hold_ms));
        state.lock().unwrap().in_flight_data_bulks -= 1;
    }
    let mut locked = state.lock().unwrap();
    if let Some(max_actions) = locked.max_actions_per_bulk {
        // Checked first and by LINES, as `xerj-engine/src/bulk.rs` does.
        if lines.len() > max_actions * 2 {
            locked.oversize_bulks_refused.push(lines.len());
            return (
                200,
                json!({
                    "took": 0,
                    "errors": true,
                    "items": [{"index": {
                        "_index": "",
                        "_id": "",
                        "status": 413,
                        "error": {
                            "type": "engine_exception",
                            "reason": format!(
                                "bulk request contains {} lines (~{} actions); exceeds \
                                 max_actions_per_bulk of {max_actions}",
                                lines.len(),
                                lines.len() / 2
                            ),
                            "status": 413
                        }
                    }}]
                }),
            );
        }
        locked.bulk_line_counts.push(lines.len());
    }
    if is_data {
        locked.data_bulk_requests += 1;
        let numbered = locked.fail_data_bulk_number == Some(locked.data_bulk_requests);
        if numbered {
            locked.fail_data_bulk_number = None;
        }
        if std::mem::take(&mut locked.fail_next_data_bulk) || numbered {
            return (
                200,
                json!({
                    "errors": true,
                    "items": [{"index": {
                        "status": 500,
                        "error": {
                            "type": "injected_failure",
                            "reason": "leave durable generation pending"
                        }
                    }}]
                }),
            );
        }
    }
    if is_data && locked.throttle_whole_data_bulks > 0 {
        locked.throttle_whole_data_bulks -= 1;
        let mut actions = 0usize;
        let mut cursor = 0;
        while cursor < lines.len() {
            let action: Value = serde_json::from_slice(lines[cursor]).unwrap();
            cursor += if action.get("delete").is_some() { 1 } else { 2 };
            actions += 1;
        }
        locked.data_bulk_item_counts.push(actions);
        return (
            429,
            json!({
                "error": {
                    "type": "circuit_breaking_exception",
                    "reason": "[parent] real memory circuit breaker tripped: rss=15634MB >= watermark=15564MB (94% of limit=16384MB); writes rejected to prevent an out-of-memory kill"
                },
                "status": 429
            }),
        );
    }
    if is_data && std::mem::take(&mut locked.throttle_next_data_bulk_odd_items) {
        let mut items = Vec::new();
        let mut cursor = 0;
        while cursor < lines.len() {
            let action: Value = serde_json::from_slice(lines[cursor]).unwrap();
            cursor += 1;
            let position = items.len();
            if let Some(meta) = action.get("delete") {
                let index = meta["_index"].as_str().unwrap().to_owned();
                let id = meta["_id"].as_str().unwrap().to_owned();
                locked.docs.remove(&(index, id));
                items.push(json!({"delete": {"status": 200}}));
                continue;
            }
            let payload: Value = serde_json::from_slice(lines[cursor]).unwrap();
            cursor += 1;
            if position % 2 == 1 {
                items.push(json!({"index": {
                    "status": 429,
                    "error": {
                        "type": "engine_exception",
                        "reason": "[parent] real memory circuit breaker tripped: rss=15679MB >= watermark=15564MB (94% of limit=16384MB); writes rejected to prevent an out-of-memory kill",
                        "status": 429
                    }
                }}));
                continue;
            }
            if let Some(meta) = action.get("index") {
                let index = meta["_index"].as_str().unwrap().to_owned();
                let id = meta["_id"].as_str().unwrap().to_owned();
                locked.docs.insert((index, id), payload);
            } else if let Some(meta) = action.get("update") {
                let index = meta["_index"].as_str().unwrap().to_owned();
                let id = meta["_id"].as_str().unwrap().to_owned();
                let patch = payload["doc"].as_object().unwrap();
                let target = locked.docs.get_mut(&(index, id)).unwrap();
                let target = target.as_object_mut().unwrap();
                target.extend(patch.clone());
            }
            items.push(json!({"index": {"status": 201}}));
        }
        locked.data_bulk_item_counts.push(items.len());
        return (200, json!({"errors": true, "items": items}));
    }
    // Half-applied bulk: apply the leading actions, then report failure.
    let applied_limit = if is_data && std::mem::take(&mut locked.partially_apply_next_data_bulk) {
        Some(lines.len() / 2)
    } else {
        None
    };
    let mut cursor = 0;
    let mut actions = 0usize;
    while cursor < lines.len() {
        if applied_limit.is_some_and(|limit| cursor >= limit) {
            break;
        }
        let action: Value = serde_json::from_slice(lines[cursor]).unwrap();
        cursor += 1;
        actions += 1;
        if let Some(meta) = action.get("delete") {
            let index = meta["_index"].as_str().unwrap().to_owned();
            let id = meta["_id"].as_str().unwrap().to_owned();
            locked.docs.remove(&(index, id));
            continue;
        }
        let payload: Value = serde_json::from_slice(lines[cursor]).unwrap();
        cursor += 1;
        if let Some(meta) = action.get("index") {
            let index = meta["_index"].as_str().unwrap().to_owned();
            let id = meta["_id"].as_str().unwrap().to_owned();
            locked.docs.insert((index, id), payload);
        } else if let Some(meta) = action.get("update") {
            let index = meta["_index"].as_str().unwrap().to_owned();
            let id = meta["_id"].as_str().unwrap().to_owned();
            let patch = payload["doc"].as_object().unwrap();
            let target = locked.docs.get_mut(&(index, id)).unwrap();
            let target = target.as_object_mut().unwrap();
            target.extend(patch.clone());
        }
    }
    if is_data {
        locked.data_bulk_item_counts.push(actions);
    }
    if applied_limit.is_some() {
        return (
            200,
            json!({
                "errors": true,
                "items": [{"index": {
                    "status": 500,
                    "error": {
                        "type": "injected_failure",
                        "reason": "partial bulk applied before failing"
                    }
                }}]
            }),
        );
    }
    (200, json!({"errors": false, "items": []}))
}

/// Does a `term` query for `expected` on `field` match `doc`, given the fields
/// this catalog holds as legacy `text` (#890)?
///
/// A `term` query is NOT analyzed, but the FIELD is. On a `keyword` field the
/// match is byte-exact, which is what every other test relies on. On a `text`
/// field the term is compared against the stored value's analyzed TOKENS, so
/// `{"term": {"prefix": "ax"}}` matches a document whose prefix is `ax-2`
/// (standard-analyzer tokens `[ax, 2]`) — the cross-corpus reach #890 is about.
/// Tokenisation here is the standard analyzer's shape for these values: split on
/// non-alphanumerics, lowercased.
fn term_matches(doc: &Value, field: &str, expected: &Value, legacy_text: &[String]) -> bool {
    if doc.get(field) == Some(expected) {
        return true;
    }
    if !legacy_text.iter().any(|legacy| legacy == field) {
        return false;
    }
    let (Some(stored), Some(term)) = (doc.get(field).and_then(Value::as_str), expected.as_str())
    else {
        return false;
    };
    stored
        .split(|ch: char| !ch.is_alphanumeric())
        .filter(|token| !token.is_empty())
        .any(|token| token.to_lowercase() == term)
}

fn delete_http(path: &str, body: &[u8], state: &Arc<Mutex<HttpState>>) -> usize {
    let index = path
        .trim_start_matches('/')
        .split("/_delete_by_query")
        .next()
        .unwrap();
    let query: Value = serde_json::from_slice(body).unwrap();
    // Collect every term constraint: the single `/query/term` form AND each
    // `/query/bool/filter[].term` (#737 scopes catalog deletes with a
    // `prefix` + `path`/`file_key` bool filter). A doc is deleted iff it
    // matches EVERY collected term.
    let mut terms: Vec<(String, Value)> = Vec::new();
    // #905: and every `/query/bool/filter[].terms` value ARRAY too — the
    // duplicate-alias sweep's path list is one of those, and an endpoint that
    // dropped it deleted at every path instead of at the named ones, which
    // makes a delete look wider than the engine's.
    let mut any_of: Vec<(String, Vec<Value>)> = Vec::new();
    if let Some((field, value)) = query
        .pointer("/query/term")
        .and_then(Value::as_object)
        .and_then(|term| term.iter().next())
    {
        terms.push((field.clone(), value.clone()));
    }
    if let Some(filters) = query
        .pointer("/query/bool/filter")
        .and_then(Value::as_array)
    {
        for filter in filters {
            if let Some((field, value)) = filter
                .pointer("/term")
                .and_then(Value::as_object)
                .and_then(|term| term.iter().next())
            {
                terms.push((field.clone(), value.clone()));
            }
            if let Some((field, values)) = filter
                .pointer("/terms")
                .and_then(Value::as_object)
                .and_then(|terms| terms.iter().next())
            {
                any_of.push((
                    field.clone(),
                    values.as_array().cloned().unwrap_or_default(),
                ));
            }
        }
    }
    // #739: an `ids` query deletes by exact `_id` (the main `file:` doc sweep).
    let ids: Option<Vec<String>> = query
        .pointer("/query/ids/values")
        .and_then(Value::as_array)
        .map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        });
    let mut locked = state.lock().unwrap();
    let legacy_text = locked.legacy_text_catalog_fields.clone();
    let before = locked.docs.len();
    locked.docs.retain(|(candidate, id), doc| {
        if candidate != index {
            return true;
        }
        if let Some(ids) = &ids {
            // ids query: delete iff this doc's _id is listed (nothing else).
            return !ids.contains(id);
        }
        if terms.is_empty() && any_of.is_empty() {
            return false; // no constraint: a match-all delete
        }
        let legacy: &[String] = if candidate == catalog::CATALOG_INDEX {
            &legacy_text
        } else {
            &[]
        };
        // Retain (do NOT delete) unless the doc matches every term — #890: on
        // the catalog's legacy text fields, "matches" means the analyzed tokens
        // — and lands inside every `terms` value list (#905).
        !(terms
            .iter()
            .all(|(field, expected)| term_matches(doc, field, expected, legacy))
            && any_of.iter().all(|(field, values)| {
                values
                    .iter()
                    .any(|value| term_matches(doc, field, value, legacy))
            }))
    });
    before - locked.docs.len()
}

/// `POST /{index}/_mget` `{"ids":[...]}` — the catalog read-back (#1267).
/// A missing id is `found: false`, not an error, matching the engine.
fn mget_http(path: &str, body: &[u8], state: &Arc<Mutex<HttpState>>) -> Value {
    let index = path
        .trim_start_matches('/')
        .trim_end_matches("/_mget")
        .to_owned();
    let query: Value = serde_json::from_slice(body).unwrap_or(Value::Null);
    let ids = query
        .get("ids")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let locked = state.lock().unwrap();
    let docs: Vec<Value> = ids
        .iter()
        .map(|id| {
            let Some(id) = id.as_str() else {
                return json!({"_index": index, "found": false});
            };
            match locked.docs.get(&(index.clone(), id.to_owned())) {
                Some(source) => json!({
                    "_index": index,
                    "_id": id,
                    "found": true,
                    "_source": source
                }),
                None => json!({"_index": index, "_id": id, "found": false}),
            }
        })
        .collect();
    json!({"docs": docs})
}

fn search_http(path: &str, body: &[u8], state: &Arc<Mutex<HttpState>>) -> Value {
    let indices = path
        .trim_start_matches('/')
        .trim_end_matches("/_search")
        .split(',')
        .collect::<Vec<_>>();
    let query: Value = serde_json::from_slice(body).unwrap();
    let term = query
        .pointer("/query/term")
        .or_else(|| query.pointer("/query/bool/must/0/term"))
        .and_then(Value::as_object)
        .and_then(|term| term.iter().next());
    let terms = query
        .pointer("/query/terms")
        .and_then(Value::as_object)
        .and_then(|terms| terms.iter().next());
    let filters = query
        .pointer("/query/bool/filter")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let exists = query
        .pointer("/query/bool/must/1/exists/field")
        .and_then(Value::as_str);
    // #694: `invalidate_prior_edges` filters live edges with
    // `must_not:[{exists:{field:"invalid_at"}}]`; honour it so the pass
    // converges (an already-invalidated edge must drop out of the result).
    let must_not_exists = query
        .pointer("/query/bool/must_not/0/exists/field")
        .and_then(Value::as_str);
    // #1977: the catalog gate reads rows back with `query.ids`. Dropping that
    // clause made the search a match-all, and `size` (the published id count)
    // then kept the `ds:` rows plus the `file:` rows that sort between `ds:`
    // and `run:`. The run document was in the store and still looked missing.
    // An id that was never written stays out of the hits, which is the case
    // the gate exists to fail.
    let ids: Option<Vec<String>> = query
        .pointer("/query/ids/values")
        .and_then(Value::as_array)
        .map(|values| {
            values
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_owned)
                .collect()
        });
    let mut locked = state.lock().unwrap();
    // #890: a catalog field an older build left as `text` is ANALYZED, so a
    // `term` on it matches tokens, not the raw value. `legacy` is empty for
    // every other index, which keeps every other search byte-exact.
    let legacy_text = locked.legacy_text_catalog_fields.clone();
    let legacy_for = |index: &str| -> &[String] {
        if index == catalog::CATALOG_INDEX {
            &legacy_text
        } else {
            &[]
        }
    };
    let mut matching: Vec<_> = locked
        .docs
        .iter()
        .filter(|((index, id), doc)| {
            indices.contains(&index.as_str())
                && ids.as_ref().is_none_or(|wanted| wanted.contains(id))
                && term
                    .map(|(field, value)| term_matches(doc, field, value, legacy_for(index)))
                    .unwrap_or(true)
                && terms
                    .map(|(field, values)| {
                        values.as_array().is_some_and(|values| {
                            values.iter().any(|value| doc.get(field) == Some(value))
                        })
                    })
                    .unwrap_or(true)
                && filters.iter().all(|filter| {
                    filter
                        .get("term")
                        .and_then(Value::as_object)
                        .and_then(|term| term.iter().next())
                        .is_none_or(|(field, value)| {
                            term_matches(doc, field, value, legacy_for(index))
                        })
                        // A per-dataset read-back scopes `terms` on `ax_file`
                        // and `term` on `ax_dataset` in the same `bool.filter`,
                        // so an endpoint that honoured only the latter would
                        // count every file's records into every dataset.
                        && filter
                            .get("terms")
                            .and_then(Value::as_object)
                            .and_then(|terms| terms.iter().next())
                            .is_none_or(|(field, values)| {
                                values.as_array().is_some_and(|values| {
                                    values.iter().any(|value| doc.get(field) == Some(value))
                                })
                            })
                        // The batched finalize-verify (#1183's count lane)
                        // scopes its semantic windows with an `exists` on the
                        // semantic field inside this same `bool.filter`; the
                        // engine evaluates it there, so the fake must too or
                        // every window counts rows the real server excludes.
                        && filter
                            .get("exists")
                            .and_then(|exists| exists.get("field"))
                            .and_then(Value::as_str)
                            .is_none_or(|field| {
                                !locked.hide_semantic_matches && doc.get(field).is_some()
                            })
                })
                && exists.map(|field| doc.get(field).is_some()).unwrap_or(true)
                && must_not_exists
                    .map(|field| doc.get(field).is_none())
                    .unwrap_or(true)
        })
        .collect();
    // #890: honour `from`/`size` when the request states them — the scoped
    // catalog sweep pages, and a page has to be a page. A request that omits
    // them still gets everything, which is what every older fixture assumes.
    // Ordering is by `_id` so a page boundary is not `HashMap` iteration order.
    //
    // #1183: honour `sort` when the request states it — the dataset read-back's
    // time bounds are size-1 searches sorted on the time field, and the first
    // hit must BE the extreme, the same invariant a doc-values sort gives the
    // real server. A request without `sort` keeps the `_id` order.
    let sort_spec: Option<(String, String)> = query
        .get("sort")
        .and_then(Value::as_array)
        .and_then(|clauses| clauses.first())
        .and_then(|clause| {
            if let Some(field) = clause.as_str() {
                return Some((field.to_owned(), "asc".to_owned()));
            }
            clause
                .as_object()
                .and_then(|object| object.iter().next())
                .map(|(field, spec)| {
                    (
                        field.clone(),
                        spec.get("order")
                            .and_then(Value::as_str)
                            .unwrap_or("asc")
                            .to_owned(),
                    )
                })
        });
    match &sort_spec {
        Some((field, order)) if order == "desc" => {
            matching.sort_by(|(_, a), (_, b)| cmp_docs_by_field(b, a, field))
        }
        Some((field, _)) => matching.sort_by(|(_, a), (_, b)| cmp_docs_by_field(a, b, field)),
        None => matching.sort_by_key(|(key, _)| *key),
    }
    // #2314: one short catalog page, internally consistent (total matches the
    // hits actually returned). The per-group equality then falls short and
    // the retry after refresh must see the document that was held back.
    let catalog_file_key_page = indices.contains(&catalog::CATALOG_INDEX)
        && filters
            .iter()
            .any(|filter| filter.pointer("/terms/file_key").is_some());
    let mut shorten = false;
    if catalog_file_key_page && locked.short_catalog_file_key_pages > 0 && matching.len() > 1 {
        matching.pop();
        shorten = true;
    }
    let total = matching.len();
    let from = query
        .get("from")
        .and_then(Value::as_u64)
        .map_or(0usize, |from| from as usize);
    let size = query
        .get("size")
        .and_then(Value::as_u64)
        .map_or(total, |size| size as usize);
    let hits = matching
        .iter()
        .skip(from)
        .take(size)
        .map(|((_, id), source)| json!({"_id": id, "_source": source}))
        .collect::<Vec<_>>();
    // #1183's batched finalize-verify reads per-digest counts as a `terms`
    // aggregation over the matched set — the engine's terms `doc_count` is
    // exact — so the fake counts the same way instead of answering every
    // request with an empty aggregations body. Only the `terms` sub-agg is
    // evaluated: it is the only shape the read-back asks for.
    let aggregations = query
        .get("aggs")
        .or_else(|| query.get("aggregations"))
        .and_then(Value::as_object)
        .map(|aggs| {
            let mut body = serde_json::Map::new();
            for (name, spec) in aggs {
                let Some(field) = spec
                    .get("terms")
                    .and_then(|terms| terms.get("field"))
                    .and_then(Value::as_str)
                else {
                    continue;
                };
                let mut counts: std::collections::BTreeMap<&str, u64> =
                    std::collections::BTreeMap::new();
                for (_, doc) in &matching {
                    if let Some(key) = doc.get(field).and_then(Value::as_str) {
                        *counts.entry(key).or_insert(0) += 1;
                    }
                }
                body.insert(
                    name.clone(),
                    json!({"buckets": counts
                        .into_iter()
                        .map(|(key, doc_count)| json!({"key": key, "doc_count": doc_count}))
                        .collect::<Vec<_>>()}),
                );
            }
            Value::Object(body)
        })
        .unwrap_or_else(|| json!({}));
    drop(matching);
    if shorten {
        locked.short_catalog_file_key_pages -= 1;
    }
    json!({
        "hits": {
            "total": {"value": total, "relation": "eq"},
            "hits": hits
        },
        "aggregations": aggregations
    })
}

/// Compare two docs on one field for the fake's `sort` support: numbers
/// numerically, strings lexically, a missing value sorting first (the null
/// ordering the real server gives an unmapped/absent field).
fn cmp_docs_by_field(a: &Value, b: &Value, field: &str) -> std::cmp::Ordering {
    let rank = |doc: &Value| match doc.get(field) {
        Some(Value::Number(n)) => (1u8, n.as_f64().unwrap_or(0.0), String::new()),
        Some(Value::String(s)) => (2u8, 0.0, s.clone()),
        _ => (0u8, 0.0, String::new()),
    };
    rank(a)
        .partial_cmp(&rank(b))
        .unwrap_or(std::cmp::Ordering::Equal)
}

