        st.docs.insert(
            (catalog::CATALOG_INDEX.to_string(), legacy_alias_id.clone()),
            json!({"doc_kind": "file", "path": "alias.csv"}),
        );
        st.docs.insert(
            (catalog::CATALOG_INDEX.to_string(), sibling_alias_id.clone()),
