/// A pass that dies mid-publish must not lose or duplicate documents: the next
/// pass — which, after a restart, has no cache at all and therefore hashes in
/// full — has to arrive at the same index a fresh run would build.
#[test]
fn a_pass_that_fails_mid_publish_converges_on_the_next_one() {
    let _guard = HTTP_E2E_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    let root = corpus.path().canonicalize().unwrap();
    fs::write(root.join("a.csv"), "id,value\n1,alpha\n").unwrap();
    fs::write(root.join("b.csv"), "id,value\n2,beta\n").unwrap();
    let endpoint = HttpEndpoint::start();
    let config = cfg(&root, state_dir.path(), &endpoint.url, false);
    let mut carry = crate::watch::Carry::default();
    crate::watch::one_pass(&config, &root, &mut carry, &crate::watch::ChangeSet::full())
        .0
        .unwrap();

    // Change a file, and make the publish of that change fail.
    fs::write(root.join("b.csv"), "id,value\n2,beta-two\n").unwrap();
    endpoint.state.lock().unwrap().fail_next_data_bulk = true;
    let burst = crate::watch::ChangeSet::from_paths(&[root.join("b.csv")]);
    let (outcome, _) = crate::watch::one_pass(&config, &root, &mut carry, &burst);
    assert!(
        outcome.is_err(),
        "the injected bulk failure must fail the pass"
    );

    // The process dies here: a restart starts with an empty cache and a full
    // burst, which is exactly what `watch::run` does on its first pass.
    let mut restarted = crate::watch::Carry::default();
    crate::watch::one_pass(
        &config,
        &root,
        &mut restarted,
        &crate::watch::ChangeSet::full(),
    )
    .0
    .unwrap();

    let live = published(&endpoint);
    let (reference, _reference_state) = fresh_full_index(&root);
    assert_eq!(
        live,
        published(&reference),
        "a crash mid-burst must not lose or duplicate documents"
    );
    let values: Vec<String> = endpoint
        .data_docs()
        .iter()
        .filter_map(|doc| doc.get("value").and_then(Value::as_str))
        .map(str::to_owned)
        .collect();
    assert!(values.iter().any(|v| v == "beta-two"), "{values:?}");
    assert!(!values.iter().any(|v| v == "beta"), "{values:?}");
}

/// The property that justifies the feature: any sequence of creates, writes,
/// renames, deletes and recreates, applied one burst at a time, converges on the
/// index a fresh full run would produce.
#[test]
fn watch_converges_under_a_randomised_change_sequence() {
    let _guard = HTTP_E2E_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    // Fixed seed: a property test that changes shape between runs cannot be
    // debugged. Bump it deliberately to explore more sequences.
    const SEED: u64 = 0x5745_5443_4831_3237;
    let mut rng = Rng(SEED);
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    let root = corpus.path().canonicalize().unwrap();
    fs::create_dir(root.join("sub")).unwrap();
    for i in 0..4 {
        fs::write(
            root.join(format!("f{i}.csv")),
            format!("id,value\n{i},start-{i}\n"),
        )
        .unwrap();
    }
    let endpoint = HttpEndpoint::start();
    let config = cfg(&root, state_dir.path(), &endpoint.url, false);
    let mut carry = crate::watch::Carry::default();
    let (outcome, _) =
        crate::watch::one_pass(&config, &root, &mut carry, &crate::watch::ChangeSet::full());
    assert!(matches!(outcome, Ok((0, _)) | Ok((3, _))), "seed {SEED:#x}");

    let mut serial = 0u64;
    for step in 0..14u64 {
        let mut touched: Vec<PathBuf> = Vec::new();
        let live: Vec<PathBuf> = walkdir::WalkDir::new(&root)
            .into_iter()
            .filter_map(Result::ok)
            .filter(|entry| entry.file_type().is_file())
            .map(|entry| entry.path().to_path_buf())
            .collect();
        match rng.below(6) {
            // create
            0 | 1 => {
                serial += 1;
                let dir = if rng.below(2) == 0 {
                    root.clone()
                } else {
                    root.join("sub")
                };
                let path = dir.join(format!("new{serial}.csv"));
                fs::write(&path, format!("id,value\n{serial},made-{serial}\n")).unwrap();
                touched.push(path);
            }
            // modify
            2 => {
                if let Some(path) = live.first() {
                    serial += 1;
                    fs::write(path, format!("id,value\n{serial},edited-{serial}\n")).unwrap();
                    touched.push(path.clone());
                }
            }
            // rename
            3 => {
                if let Some(path) = live.first() {
                    serial += 1;
                    let renamed = root.join(format!("moved{serial}.csv"));
                    fs::rename(path, &renamed).unwrap();
                    touched.push(path.clone());
                    touched.push(renamed);
                }
            }
            // delete
            4 => {
                if let Some(path) = live.first() {
                    fs::remove_file(path).unwrap();
                    touched.push(path.clone());
                }
            }
            // delete and recreate the same path with different content: the
            // shape that makes a path-keyed cache wrong.
            _ => {
                if let Some(path) = live.first() {
                    serial += 1;
                    fs::remove_file(path).unwrap();
                    fs::write(path, format!("id,value\n{serial},reborn-{serial}\n")).unwrap();
                    touched.push(path.clone());
                }
            }
        }
        if touched.is_empty() {
            continue;
        }
        let burst = crate::watch::ChangeSet::from_paths(&touched);
        let (outcome, _) = crate::watch::one_pass(&config, &root, &mut carry, &burst);
        assert!(
            matches!(outcome, Ok((0, _)) | Ok((3, _))),
            "seed {SEED:#x} step {step}: pass failed: {:?}",
            outcome.err().map(|e| format!("{e:#}"))
        );
    }

    // The property that always holds: a full-hash re-run after the sequence
    // changes nothing, so no carried digest ever hid a real change.
    a_rerun_changes_nothing(&config, &endpoint, &format!("seed {SEED:#x}"));
    let (reference, _reference_state) = fresh_full_index(&root);
    let watched = published(&endpoint);
    let fresh = published(&reference);
    assert_eq!(
        watched.keys().collect::<Vec<_>>(),
        fresh.keys().collect::<Vec<_>>(),
        "seed {SEED:#x}: document ids diverged"
    );
    assert_eq!(
        watched.len(),
        fresh.len(),
        "seed {SEED:#x}: record count diverged"
    );
    assert_eq!(watched, fresh, "seed {SEED:#x}: document contents diverged");
}

/// #933: every operation's `Started` journal record must precede its own
/// `Committed` — the durable order that makes a crash mid-window repeat
/// exactly the operations whose accepted apply was not recorded. Holds
/// trivially for the serial loop; the windowed scheduler is what could break
/// it, so it is asserted where the scheduler runs.
fn started_precedes_committed(state_dir: &Path) {
    let mut started = std::collections::BTreeSet::new();
    let mut committed = std::collections::BTreeSet::new();
    for line in fs::read_to_string(state_dir.join("journal.ndjson"))
        .unwrap()
        .lines()
    {
        let Ok(event) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        if event.get("kind").and_then(Value::as_str) != Some("sync_operation_state") {
            continue;
        }
        let Some(operation) = event.get("operation_id").and_then(Value::as_str) else {
            continue;
        };
        match event.get("state").and_then(Value::as_str) {
            // The journal serializes the state enum lowercase.
            Some("started") => {
                started.insert(operation.to_owned());
            }
            Some("committed") => {
                committed.insert(operation.to_owned());
            }
            _ => {}
        }
    }
    let unstarted: Vec<_> = committed.difference(&started).collect();
    assert!(
        unstarted.is_empty(),
        "operations committed without a Started record first: {unstarted:?}"
    );
}

/// #933: the `--no-graph` index phase used to apply one file at a time —
/// about 6 files/s on the reporter's 48,533-file corpus, ~3.5 h for the phase
/// alone. The durable replay is now a bounded window (`--workers` wide) over
/// operations that touch disjoint groups. End-to-end, against an endpoint
/// that holds every data bulk for a moment: a serial replay can never have
/// two data bulks inside the endpoint at once, a windowed one must. That
/// count is the whole regression — everything else here is the convergence
/// the change may not disturb.
#[test]
fn no_graph_replay_applies_files_in_parallel_and_converges() {
    let _guard = HTTP_E2E_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    for file in 0..6 {
        let rows: String = (0..5)
            .map(|row| format!("{file}-{row},body of row {row} in file {file}\n"))
            .collect();
        fs::write(
            corpus.path().join(format!("file{file}.csv")),
            format!("id,body\n{rows}"),
        )
        .unwrap();
    }
    let endpoint = HttpEndpoint::start();
    endpoint.state.lock().unwrap().data_bulk_delay_ms = 200;
    let mut config = cfg(corpus.path(), state_dir.path(), &endpoint.url, false);
    config.workers = 4;

    assert_eq!(run_index(config).unwrap(), 0);
    let state = endpoint.state.lock().unwrap();
    assert!(
        (2..=4).contains(&state.max_concurrent_data_bulks),
        "a 4-wide replay over 200 ms-held data bulks must overlap; max concurrent data \
         bulks was {} (1 forever is the fingerprint of the serial index phase this \
         fixes)",
        state.max_concurrent_data_bulks
    );
    drop(state);
    assert_eq!(
        endpoint.data_bulk_requests(),
        6,
        "one sealed bulk per file, no duplicate sends"
    );
    let docs = endpoint.data_docs();
    assert_eq!(docs.len(), 6 * 5, "every record landed exactly once");
    assert_eq!(paths(&docs).len(), 6, "every file's records are searchable");
    started_precedes_committed(state_dir.path());
}

/// #933: a bulk failing while other operations are in flight — the state the
/// serial loop never had to think about. The run stops, everything already
/// dispatched is drained and journaled, and the same command resumes to an
/// exact, committed generation: no duplicate documents, no missing file.
#[test]
fn no_graph_parallel_replay_survives_a_bulk_failure_mid_window_and_resumes() {
    let _guard = HTTP_E2E_LOCK.lock().unwrap_or_else(|p| p.into_inner());
    let corpus = tempfile::tempdir().unwrap();
    let state_dir = tempfile::tempdir().unwrap();
    for file in 0..6 {
        let rows: String = (0..5)
            .map(|row| format!("{file}-{row},body of row {row} in file {file}\n"))
            .collect();
        fs::write(
            corpus.path().join(format!("file{file}.csv")),
            format!("id,body\n{rows}"),
        )
        .unwrap();
    }
    let endpoint = HttpEndpoint::start();
    endpoint.state.lock().unwrap().data_bulk_delay_ms = 60;
    endpoint.state.lock().unwrap().fail_data_bulk_number = Some(3);
    let mut config = cfg(corpus.path(), state_dir.path(), &endpoint.url, false);
    config.workers = 4;

    run_index(config.clone()).expect_err("the third data bulk is refused");
    started_precedes_committed(state_dir.path());
    assert_eq!(journal_events(state_dir.path(), "sync_commit"), 0);
    let committed = journal_events_of_state(state_dir.path(), "committed");
    assert!(
        (1..6).contains(&committed),
        "some in-flight operations drained and committed, not all six: {committed}"
    );

    // Which file's bulk was refused is schedule-dependent; convergence is not.
    assert_eq!(run_index(config).unwrap(), 0);
    assert_eq!(journal_events(state_dir.path(), "sync_commit"), 1);
    let docs = endpoint.data_docs();
    assert_eq!(docs.len(), 6 * 5, "every record landed exactly once");
    assert_eq!(paths(&docs).len(), 6);
    started_precedes_committed(state_dir.path());
}

/// Counts `sync_operation_state` records carrying one specific state, so a
/// test can say how many operations reached `Committed` without caring which.
fn journal_events_of_state(state_dir: &Path, state: &str) -> usize {
    fs::read_to_string(state_dir.join("journal.ndjson"))
        .unwrap()
        .lines()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .filter(|event| {
            event.get("kind").and_then(Value::as_str) == Some("sync_operation_state")
                && event.get("state").and_then(Value::as_str) == Some(state)
        })
        .count()
}

/// #1224 scaffolding: one upsert applied through the real executor against
/// the stateful endpoint, with everything hand-built so the only moving part
