    fn an_empty_exclusion_list_keeps_a_root_corpus_json() {
        let files = vec![entry("corpus.json"), entry("README.md")];
        let (kept, dropped) = without_excluded_rels(files, &[]);
        assert_eq!(dropped, 0);
        assert_eq!(kept.len(), 2);
    }
