        };
        let mut initial = state::Journal::open(
            state_dir.path(),
            "corpus",
            "http://engine",
            "ax",
            300,
            false,
        )
        .unwrap();
        initial.write_plan(&plan).unwrap();
        initial
            .file_done(&FileDone {
                file_key: "shared".into(),
                path: "report.dat".into(),
                records: 10,
                junk: 5,
