            })
            .unwrap();
        initial
            .file_done(&FileDone {
                file_key: "quarterly-only".into(),
                path: "quarterly.json".into(),
                records: 2,
                junk: 2,
                bytes: 23,
                dropped_by_dataset: HashMap::from([("quarterly".into(), 11)]),
                generation: Some("digest-2".into()),
            })
            .unwrap();
        let before_resume = durable_dataset_stats(&plan, &initial.done);
