//! `xerj autoindex s3://bucket/prefix --watch`: the CLI route.
//!
//! Everything policy-shaped lives above this file ([`super::poll_once`],
//! [`super::cost`]); this is resolution and plumbing — which endpoint, which
//! credentials, which state directory, where the change feed goes, and how a
//! `^C` stops a watch that may be five minutes into a sleep.
//!
//! Two contracts an operator or an agent can rely on:
//!
//! * **stdout is the change feed and nothing else.** One JSON object per
//!   changed object, so `xerj autoindex s3://… --watch | jq` works. The
//!   per-cycle report goes to stderr. The single exception is the cost
//!   refusal, which prints the same decision-request document the indexing
//!   gate prints and exits [`crate::gate::EXIT_NEEDS_DECISION`] — and it
//!   happens before any event, so the two never interleave.
//! * **credentials come from the environment only.** There is no flag for
//!   them, so they cannot reach a shell history, a CI log or a `ps` listing.

use anyhow::{bail, Context, Result};
use std::io::Write;
use std::sync::atomic::{AtomicBool, Ordering};

use super::journal::{WatchJournal, WatchLock};
use super::s3::{parse_s3_url, Credentials, S3Source};
use super::ObjectSource;
use super::{ChangeSink, CountingSink, CycleReport, JsonlSink, PollCostRefused, WatchOptions};
use crate::cli::WatchCfg;

/// Set by the signal handler, read by the poll loop. A watch is a long-lived
/// foreground process, so `^C` has to stop it between objects rather than in the
/// middle of a journal write — the loop checks this flag, finishes what it is
/// holding, saves, and returns.
static STOP: AtomicBool = AtomicBool::new(false);

extern "C" fn on_signal(_sig: libc::c_int) {
    // Async-signal-safe: one relaxed atomic store, nothing else.
    STOP.store(true, Ordering::SeqCst);
}

fn install_signal_handlers() {
    // SAFETY: `on_signal` does one atomic store and returns, which is
    // async-signal-safe. Installing a handler for SIGINT/SIGTERM is the whole
    // effect.
    unsafe {
        libc::signal(libc::SIGINT, on_signal as *const () as libc::sighandler_t);
        libc::signal(libc::SIGTERM, on_signal as *const () as libc::sighandler_t);
    }
}

/// `r2://bucket/prefix` is a spelling of `s3://bucket/prefix`: Cloudflare R2
/// speaks the S3 API, and what differs is the endpoint, not the protocol.
/// Normalising here rather than teaching the parser two schemes keeps one code
/// path, and keeps `r2://` from being a flag that parses and then does nothing.
pub fn normalize_object_url(url: &str) -> String {
    match url.strip_prefix("r2://") {
        Some(rest) => format!("s3://{rest}"),
        None => url.to_string(),
    }
}

/// Where the bucket is served from. Explicit flag, then `AWS_ENDPOINT_URL`
/// (which is what R2's own documentation tells people to set), then AWS's
/// regional endpoint. A watch against R2 or MinIO with neither set is refused
/// with the thing to do about it, because the alternative is signing a request
/// to Amazon with an R2 key and reporting a 403.
pub fn resolve_endpoint(flag: Option<&str>, env: Option<&str>, region: &str) -> Result<String> {
    if let Some(e) = flag.filter(|e| !e.is_empty()) {
        return Ok(e.to_string());
    }
    if let Some(e) = env.filter(|e| !e.is_empty()) {
        return Ok(e.to_string());
    }
    if region == "auto" {
        bail!(
            "no S3 endpoint and no region: pass --endpoint-url, or set AWS_ENDPOINT_URL. \
             Cloudflare R2 is https://<account-id>.r2.cloudflarestorage.com, MinIO is \
             http://<host>:9000, and AWS S3 needs --region <region> instead"
        );
    }
    Ok(format!("https://s3.{region}.amazonaws.com"))
}

/// Run the watch. Returns the process exit code.
pub fn run(cfg: WatchCfg) -> Result<i32> {
    let normalized = normalize_object_url(&cfg.url);
    let loc = parse_s3_url(&normalized)?;
    let endpoint = resolve_endpoint(
        cfg.endpoint.as_deref(),
        std::env::var("AWS_ENDPOINT_URL").ok().as_deref(),
        &cfg.region,
    )?;
    let creds = Credentials::from_env().ok_or_else(|| {
        anyhow::anyhow!(
            "no object-storage credentials: set AWS_ACCESS_KEY_ID and AWS_SECRET_ACCESS_KEY \
             (and AWS_SESSION_TOKEN if your provider issues one). There is deliberately no flag \
             for them — a flag would put a secret in your shell history and in `ps`"
        )
    })?;

    let src = S3Source::new(
        &endpoint,
        &cfg.region,
        creds,
        loc.clone(),
        std::time::Duration::from_secs(60),
    )?;

    let state_dir = cfg.state_dir.clone().unwrap_or_else(|| {
        // Keyed by the same helper folder watches use, so two watches on
        // different buckets never share a journal.
        crate::state::default_state_dir(&normalized, &endpoint, &loc.prefix)
    });
    // Taken before the journal is read: two watchers that both read an empty
    // journal would both index the whole bucket.
    let _lock = WatchLock::acquire(&state_dir)?;
    let mut journal = WatchJournal::open(
        &state_dir,
        &endpoint,
        &loc.bucket,
        &loc.prefix,
        cfg.append_only,
        cfg.fresh,
    )?;

    let opts = WatchOptions {
        poll_interval: cfg.poll_interval,
        max_cycles: cfg.max_cycles,
        fetch: cfg.fetch,
        max_object_bytes: cfg.max_object_bytes,
        append_only: cfg.append_only,
        max_monthly_class_a: cfg.max_monthly_ops,
        max_monthly_class_b: cfg.max_monthly_gets,
        allow_cost: cfg.allow_cost,
        page_size: cfg.page_size,
        status_path: Some(
            cfg.status_file
                .clone()
                .unwrap_or_else(|| state_dir.join("objwatch-status.json")),
        ),
        dry_run: cfg.dry_run,
    };

    if !cfg.quiet {
        eprintln!(
            "xerj-watch: {} every {}s, state {} ({} object(s) remembered){}",
            src.describe(),
            cfg.poll_interval.as_secs(),
            state_dir.display(),
            journal.len(),
            if cfg.dry_run { ", dry run" } else { "" }
        );
        if cfg.dry_run {
            eprintln!(
                "xerj-watch: dry run — one cycle, no GETs, nothing emitted, no journal. The \
                 LISTING is real: it costs Class A operations and is charged to the spend \
                 ledger like any other cycle."
            );
        }
    }

    install_signal_handlers();
    let stop = || STOP.load(Ordering::SeqCst);

    // stdout is the feed unless --events-out redirects it. --dry-run emits
    // nothing at all: it exists to price a poll, and writing a bucket-sized
    // first change set to a terminal would defeat that. (`poll_once` never
    // calls the sink in a dry run; the counting sink is belt and braces.)
    let mut counting = CountingSink::default();
    let mut file_sink;
    let mut stdout_sink;
    let sink: &mut dyn ChangeSink = if cfg.dry_run {
        &mut counting
    } else if let Some(path) = &cfg.events_out {
        if let Some(dir) = path.parent() {
            if !dir.as_os_str().is_empty() {
                std::fs::create_dir_all(dir)
                    .with_context(|| format!("create events dir {}", dir.display()))?;
            }
        }
        let f = std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)
            .with_context(|| format!("open events file {}", path.display()))?;
        file_sink = JsonlSink::new(std::io::BufWriter::new(f));
        &mut file_sink
    } else {
        stdout_sink = JsonlSink::new(std::io::stdout());
        &mut stdout_sink
    };

    let quiet = cfg.quiet;
    let json = cfg.json;
    let mut on_cycle = move |r: &CycleReport| {
        // Never stdout: that is the change feed.
        if json {
            let _ = writeln!(std::io::stderr(), "{}", r.to_json());
        } else if !quiet {
            let _ = writeln!(std::io::stderr(), "{}", r.line());
            for w in &r.warnings {
                let _ = writeln!(std::io::stderr(), "xerj-watch: WARNING {w}");
            }
            for e in &r.errors {
                let _ = writeln!(std::io::stderr(), "xerj-watch: error {e}");
            }
        }
    };

    let outcome = match super::run_watch(&src, &mut journal, &opts, sink, &stop, &mut on_cycle) {
        Ok(o) => o,
        Err(e) => {
            // The cost refusal is a decision request, not a failure: same
            // document and same exit code as the indexing gate, so one
            // agent-side branch handles both.
            //
            // A breaker can trip after events were written (a bucket that grew
            // mid-watch). The decision request is then the LAST line of the
            // feed, told apart by `"xerj":"objwatch-decision-request"` where every
            // event says `"xerj":"objwatch-change"`.
            if let Some(refused) = e.downcast_ref::<PollCostRefused>() {
                println!("{}", refused.to_json());
                eprintln!("xerj-watch: {refused}");
                return Ok(crate::gate::EXIT_NEEDS_DECISION);
            }
            return Err(e);
        }
    };

    if !quiet {
        let t = &outcome.totals;
        eprintln!(
            "xerj-watch: stopped after {} cycle(s): {} Class A list call(s), {} Class B GET(s), \
             {} fetched, {} event(s), {} error(s). Status: {}",
            t.cycles,
            t.list_calls,
            t.gets,
            super::human_bytes(t.bytes_fetched),
            t.events,
            t.errors,
            opts.status_path
                .as_ref()
                .map(|p| p.display().to_string())
                .unwrap_or_else(|| "-".into())
        );
        if cfg.dry_run {
            if let Some(last) = &outcome.last {
                eprintln!("xerj-watch: {}", last.projection.line());
                eprintln!(
                    "xerj-watch: dry run saw {} added, {} changed, {} deleted; it emitted and \
                     recorded none of them, so the next real run starts from the same state. \
                     The price check itself cost {} Class A list call(s), on the ledger.",
                    last.added, last.changed, last.deleted, last.list_calls
                );
            }
        }
    }
    // An error inside a cycle (one object failed to fetch, the sink refused one
    // write) is not a failed watch: the next cycle retries it, and the journal
    // was left alone on purpose. Exit 3 says "it ran, and something in it did
    // not" — the same meaning `autoindex` gives 3 for completed-with-junk.
    if outcome.totals.errors > 0 {
        return Ok(3);
    }
    Ok(0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn r2_urls_are_a_spelling_of_s3_urls() {
        assert_eq!(normalize_object_url("r2://b/p/"), "s3://b/p/");
        assert_eq!(normalize_object_url("s3://b/p/"), "s3://b/p/");
        // Not a URL at all: left alone so the parser gives the real error.
        assert_eq!(normalize_object_url("/tmp/x"), "/tmp/x");
        // And it must actually parse afterwards, which is the point.
        assert_eq!(
            parse_s3_url(&normalize_object_url("r2://logs/2026/"))
                .unwrap()
                .bucket,
            "logs"
        );
    }

    #[test]
    fn the_endpoint_comes_from_the_flag_then_the_environment_then_the_region() {
        assert_eq!(
            resolve_endpoint(Some("http://flag:1"), Some("http://env:2"), "auto").unwrap(),
            "http://flag:1"
        );
        assert_eq!(
            resolve_endpoint(None, Some("http://env:2"), "auto").unwrap(),
            "http://env:2"
        );
        assert_eq!(
            resolve_endpoint(None, None, "eu-west-1").unwrap(),
            "https://s3.eu-west-1.amazonaws.com"
        );
    }

    /// Region "auto" is what R2 wants, and it names no AWS endpoint — so
    /// guessing one would sign a request to Amazon with an R2 key and report a
    /// 403 that says nothing about the real mistake.
    #[test]
    fn region_auto_with_no_endpoint_is_refused_with_the_thing_to_do() {
        let err = resolve_endpoint(None, None, "auto")
            .unwrap_err()
            .to_string();
        assert!(err.contains("--endpoint-url"), "{err}");
        assert!(err.contains("r2.cloudflarestorage.com"), "{err}");
        assert!(err.contains("--region"), "{err}");
    }

    #[test]
    fn an_empty_endpoint_string_does_not_count_as_set() {
        assert_eq!(
            resolve_endpoint(Some(""), Some("http://env:2"), "auto").unwrap(),
            "http://env:2"
        );
        assert!(resolve_endpoint(Some(""), Some(""), "auto").is_err());
    }
}

//! A minimal, synchronous S3-compatible client: `ListObjectsV2` and `GetObject`.
//!
//! WHY THIS EXISTS AND NOT `aws-sdk-s3`
//!
//! `xerj-autoindex` is a synchronous crate (std threads, `reqwest::blocking`);
//! the server calls it through `spawn_blocking`. `aws-sdk-s3` is async-only, so
//! using it here means standing up a runtime inside a blocking call and pulling
//! the whole SDK into a binary that today needs exactly two S3 verbs. The
//! watcher's needs are small enough to sign by hand: SigV4 over
//! `ListObjectsV2` + `GetObject`, path-style addressing, no session token
//! refresh.
//!
//! This is deliberately behind [`super::ObjectSource`]. When a richer object
//! source lands (streaming reads, multipart-aware fetch, a shared credential
//! resolver), swap the implementation and the watcher does not change.
//!
//! WHAT IS NOT IMPLEMENTED: request retries with backoff (a failed cycle is
//! reported and the next poll retries), virtual-host addressing, IMDS or
//! profile credential chains (environment only), server-side encryption
//! headers, and `ListObjectVersions` (a versioned bucket is watched by current
//! version only).

use anyhow::{anyhow, bail, Context, Result};
use hmac::{Hmac, Mac};
use quick_xml::events::Event;
use quick_xml::Reader;
use sha2::{Digest, Sha256};
use std::time::Duration;

use super::{FetchedObject, ListPage, ListRequest, ObjectMeta, ObjectSource};

type HmacSha256 = Hmac<Sha256>;

/// Credentials, read from the environment only — never from a flag, so they
/// cannot land in a shell history, a CI log or a `ps` listing.
#[derive(Clone)]
pub struct Credentials {
    pub access_key_id: String,
    pub secret_access_key: String,
    pub session_token: Option<String>,
}

impl Credentials {
    /// `AWS_ACCESS_KEY_ID` / `AWS_SECRET_ACCESS_KEY` / `AWS_SESSION_TOKEN`.
    pub fn from_env() -> Option<Credentials> {
        let id = std::env::var("AWS_ACCESS_KEY_ID")
            .ok()
            .filter(|v| !v.is_empty())?;
        let secret = std::env::var("AWS_SECRET_ACCESS_KEY")
            .ok()
            .filter(|v| !v.is_empty())?;
        Some(Credentials {
            access_key_id: id,
            secret_access_key: secret,
            session_token: std::env::var("AWS_SESSION_TOKEN")
                .ok()
                .filter(|v| !v.is_empty()),
        })
    }
}

/// An `s3://bucket/prefix` location plus the endpoint that serves it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct S3Location {
    pub bucket: String,
    /// Key prefix. Empty means the whole bucket.
    pub prefix: String,
}

/// Parse `s3://bucket[/prefix...]`. Rejects anything else, including a bare
/// bucket name, so a typo cannot be read as a folder.
pub fn parse_s3_url(url: &str) -> Result<S3Location> {
    let rest = url
        .strip_prefix("s3://")
        .ok_or_else(|| anyhow!("not an s3 URL (expected s3://bucket/prefix): {url}"))?;
    let (bucket, prefix) = match rest.split_once('/') {
        Some((b, p)) => (b, p),
        None => (rest, ""),
    };
    if bucket.is_empty() {
        bail!("s3 URL has no bucket: {url}");
    }
    if bucket.contains('.') && bucket.ends_with(".com") {
        bail!(
            "s3 URL bucket looks like a hostname ({bucket}). Pass the endpoint with \
             --endpoint-url and the bucket as s3://<bucket>/<prefix>"
        );
    }
    Ok(S3Location {
        bucket: bucket.to_string(),
        prefix: prefix.to_string(),
    })
}

/// Anything the watcher can talk to over the S3 HTTP API: AWS S3, Cloudflare
/// R2, MinIO, Ceph RGW. Path-style addressing is used for all of them because
/// it is the one form every gateway serves.
pub struct S3Source {
    client: reqwest::blocking::Client,
    endpoint: String,
    region: String,
    creds: Credentials,
    loc: S3Location,
}

impl S3Source {
    pub fn new(
        endpoint: &str,
        region: &str,
        creds: Credentials,
        loc: S3Location,
        timeout: Duration,
    ) -> Result<S3Source> {
        let endpoint = endpoint.trim_end_matches('/').to_string();
        if !endpoint.starts_with("http://") && !endpoint.starts_with("https://") {
            bail!("endpoint must start with http:// or https:// (got {endpoint})");
        }
        let client = reqwest::blocking::Client::builder()
            .timeout(timeout)
            .build()
            .context("build blocking HTTP client for object storage")?;
        Ok(S3Source {
            client,
            endpoint,
            region: region.to_string(),
            creds,
            loc,
        })
    }

    pub fn location(&self) -> &S3Location {
        &self.loc
    }

    pub fn endpoint(&self) -> &str {
        &self.endpoint
    }

    /// Sign and send one request. `query` is already in canonical (sorted) form.
    fn send(
        &self,
        method: &str,
        key_path: &str,
        query: &[(String, String)],
        body: &[u8],
    ) -> Result<reqwest::blocking::Response> {
        let host = host_of(&self.endpoint)?;
        // Path-style: /<bucket>/<key>
        let mut canonical_path = String::from("/");
        canonical_path.push_str(&uri_encode(&self.loc.bucket, false));
        if !key_path.is_empty() {
            canonical_path.push('/');
            canonical_path.push_str(&uri_encode(key_path, false));
        }
        let canonical_query = query
            .iter()
            .map(|(k, v)| format!("{}={}", uri_encode(k, true), uri_encode(v, true)))
            .collect::<Vec<_>>()
            .join("&");

        let payload_hash = hex_lower(&Sha256::digest(body));
        let now = chrono::Utc::now();
        let amz_date = now.format("%Y%m%dT%H%M%SZ").to_string();
        let date_stamp = now.format("%Y%m%d").to_string();

        let mut signed_headers = vec![
            ("host".to_string(), host.clone()),
            ("x-amz-content-sha256".to_string(), payload_hash.clone()),
            ("x-amz-date".to_string(), amz_date.clone()),
        ];
        if let Some(tok) = &self.creds.session_token {
            signed_headers.push(("x-amz-security-token".to_string(), tok.clone()));
        }
        signed_headers.sort_by(|a, b| a.0.cmp(&b.0));
        let signed_header_names = signed_headers
            .iter()
            .map(|(k, _)| k.as_str())
            .collect::<Vec<_>>()
            .join(";");
        let canonical_headers = signed_headers
            .iter()
            .map(|(k, v)| format!("{k}:{}\n", v.trim()))
            .collect::<String>();

        let canonical_request = format!(
            "{method}\n{canonical_path}\n{canonical_query}\n{canonical_headers}\n\
             {signed_header_names}\n{payload_hash}"
        );
        let scope = format!("{date_stamp}/{}/s3/aws4_request", self.region);
        let string_to_sign = format!(
            "AWS4-HMAC-SHA256\n{amz_date}\n{scope}\n{}",
            hex_lower(&Sha256::digest(canonical_request.as_bytes()))
        );
        let signature = hex_lower(
            &signing_key(&self.creds.secret_access_key, &date_stamp, &self.region)?
                .chain_update(string_to_sign.as_bytes())
                .finalize()
                .into_bytes(),
        );
        let authorization = format!(
            "AWS4-HMAC-SHA256 Credential={}/{scope}, SignedHeaders={signed_header_names}, \
             Signature={signature}",
            self.creds.access_key_id
        );

        let mut url = format!("{}{canonical_path}", self.endpoint);
        if !canonical_query.is_empty() {
            url.push('?');
            url.push_str(&canonical_query);
        }
        // The URL parser normalises dot segments (`a/../b` -> `b`, and `%2E`
        // counts as a dot under WHATWG rules), so a key such as `x/../y.txt`
        // would be SENT as a different path than the one signed and meant. Refuse
        // it before spending a request on a guaranteed failure — or worse, on
        // another object's bytes.
        let parsed =
            reqwest::Url::parse(&url).with_context(|| format!("parse {}", redact(&url)))?;
        let sent_path = parsed.path();
        let meant_path = match self.endpoint.find("://").map(|i| &self.endpoint[i + 3..]) {
            Some(rest) => match rest.find('/') {
                Some(i) => format!("{}{canonical_path}", &rest[i..]),
                None => canonical_path.clone(),
            },
            None => canonical_path.clone(),
        };
        if sent_path != meant_path {
            bail!(
                "key {key_path:?} cannot be addressed over HTTP: the URL parser rewrites its path \
                 ({meant_path} -> {sent_path}), usually because of a '.' or '..' path segment. \
                 Rename the object; it was not requested"
            );
        }
        let mut req = match method {
            "GET" => self.client.get(&url),
            "PUT" => self.client.put(&url),
            "POST" => self.client.post(&url),
            "DELETE" => self.client.delete(&url),
            other => bail!("unsupported method {other}"),
        };
        req = req
            .header("x-amz-content-sha256", &payload_hash)
            .header("x-amz-date", &amz_date)
            .header("authorization", &authorization);
        if let Some(tok) = &self.creds.session_token {
            req = req.header("x-amz-security-token", tok);
        }
        if !body.is_empty() {
            req = req.body(body.to_vec());
        }
        req.send()
            .with_context(|| format!("{method} {} failed", redact(&url)))
    }
}

impl ObjectSource for S3Source {
    fn describe(&self) -> String {
        // Never the credentials, and never a presigned URL: this string goes
        // into progress output, a JSON result and bug reports.
        format!(
            "s3://{}/{} @ {}",
            self.loc.bucket, self.loc.prefix, self.endpoint
        )
    }

    fn list(&self, req: &ListRequest) -> Result<ListPage> {
        let mut query: Vec<(String, String)> = vec![("list-type".into(), "2".into())];
        if !req.prefix.is_empty() {
            query.push(("prefix".into(), req.prefix.to_string()));
        }
        if let Some(t) = req.continuation_token {
            query.push(("continuation-token".into(), t.to_string()));
        }
        if let Some(sa) = req.start_after {
            query.push(("start-after".into(), sa.to_string()));
        }
        if let Some(d) = req.delimiter {
            query.push(("delimiter".into(), d.to_string()));
        }
        query.push(("max-keys".into(), req.max_keys.to_string()));
        query.sort_by(|a, b| a.0.cmp(&b.0));

        let resp = self.send("GET", "", &query, b"")?;
        let status = resp.status();
        let body = resp.text().context("read ListObjectsV2 body")?;
        if !status.is_success() {
            bail!(
                "ListObjectsV2 on {} returned {status}: {}",
                self.loc.bucket,
                first_chars(&body, 400)
            );
        }
        parse_list_v2(&body)
    }

    fn get(&self, key: &str, max_bytes: u64) -> Result<FetchedObject> {
        let resp = self.send("GET", key, &[], b"")?;
        let status = resp.status();
        let etag = resp
            .headers()
            .get("etag")
            .and_then(|v| v.to_str().ok())
            .map(normalize_etag);
        if !status.is_success() {
            let body = resp.text().unwrap_or_default();
            bail!(
                "GetObject {key} returned {status}: {}",
                first_chars(&body, 400)
            );
        }
        // Bounded read: a watcher must not be turned into an OOM by one
        // enormous object that appeared in the bucket.
        let mut body = Vec::new();
        let mut reader = std::io::Read::take(resp, max_bytes.saturating_add(1));
        std::io::Read::read_to_end(&mut reader, &mut body).context("read object body")?;
        let truncated = body.len() as u64 > max_bytes;
        if truncated {
            body.truncate(max_bytes as usize);
        }
        Ok(FetchedObject {
            bytes: body,
            etag,
            truncated,
        })
    }
}

/// Test/harness support: the watcher itself never writes. These verbs exist so
/// the integration tests can build a bucket state (including a real multipart
/// upload, whose ETag shape differs) through the same signer the read path
/// uses — a separate test client would prove the tests, not the code.
impl S3Source {
    pub fn create_bucket(&self) -> Result<()> {
        let resp = self.send("PUT", "", &[], b"")?;
        let status = resp.status();
        if status.is_success() || status.as_u16() == 409 {
            return Ok(());
        }
        let body = resp.text().unwrap_or_default();
        // MinIO and R2 both answer an existing bucket with a 409-family error.
        if body.contains("BucketAlreadyOwnedByYou") || body.contains("BucketAlreadyExists") {
            return Ok(());
        }
        bail!(
            "CreateBucket returned {status}: {}",
            first_chars(&body, 300)
        )
    }

    pub fn put_object(&self, key: &str, body: &[u8]) -> Result<Option<String>> {
        let resp = self.send("PUT", key, &[], body)?;
        let status = resp.status();
        let etag = resp
            .headers()
            .get("etag")
            .and_then(|v| v.to_str().ok())
            .map(normalize_etag);
        if !status.is_success() {
            let text = resp.text().unwrap_or_default();
            bail!(
                "PutObject {key} returned {status}: {}",
                first_chars(&text, 300)
            );
        }
        Ok(etag)
    }

    pub fn delete_object(&self, key: &str) -> Result<()> {
        let resp = self.send("DELETE", key, &[], b"")?;
        let status = resp.status();
        if !status.is_success() && status.as_u16() != 404 {
            let text = resp.text().unwrap_or_default();
            bail!(
                "DeleteObject {key} returned {status}: {}",
                first_chars(&text, 300)
            );
        }
        Ok(())
    }

    /// A real multipart upload, so a test can assert what the watcher does when
    /// an object is replaced by one: the ETag stops being an MD5 and becomes
    /// `<hex>-<part count>`.
    pub fn put_object_multipart(&self, key: &str, parts: &[Vec<u8>]) -> Result<Option<String>> {
        if parts.len() < 2 {
            bail!("a multipart upload needs at least 2 parts");
        }
        let resp = self.send("POST", key, &[("uploads".into(), String::new())], b"")?;
        let status = resp.status();
        let body = resp.text().context("read CreateMultipartUpload body")?;
        if !status.is_success() {
            bail!(
                "CreateMultipartUpload returned {status}: {}",
                first_chars(&body, 300)
            );
        }
        let upload_id = xml_text(&body, "UploadId")
            .ok_or_else(|| anyhow!("CreateMultipartUpload response had no UploadId"))?;

        let mut etags: Vec<(usize, String)> = Vec::new();
        for (i, part) in parts.iter().enumerate() {
            let n = i + 1;
            let mut q = vec![
                ("partNumber".to_string(), n.to_string()),
                ("uploadId".to_string(), upload_id.clone()),
            ];
            q.sort_by(|a, b| a.0.cmp(&b.0));
            let resp = self.send("PUT", key, &q, part)?;
            let status = resp.status();
            let etag = resp
                .headers()
                .get("etag")
                .and_then(|v| v.to_str().ok())
                .map(|v| v.to_string());
            if !status.is_success() {
                let text = resp.text().unwrap_or_default();
                bail!(
                    "UploadPart {n} returned {status}: {}",
                    first_chars(&text, 300)
                );
            }
            etags.push((
                n,
                etag.ok_or_else(|| anyhow!("UploadPart {n} returned no ETag"))?,
            ));
        }

        let mut xml = String::from("<CompleteMultipartUpload>");
        for (n, etag) in &etags {
            xml.push_str(&format!(
                "<Part><PartNumber>{n}</PartNumber><ETag>{etag}</ETag></Part>"
            ));
        }
        xml.push_str("</CompleteMultipartUpload>");
        let mut q = vec![("uploadId".to_string(), upload_id)];
        q.sort_by(|a, b| a.0.cmp(&b.0));
        let resp = self.send("POST", key, &q, xml.as_bytes())?;
        let status = resp.status();
        let body = resp.text().context("read CompleteMultipartUpload body")?;
        if !status.is_success() {
            bail!(
                "CompleteMultipartUpload returned {status}: {}",
                first_chars(&body, 300)
            );
        }
        // S3 answers 200 with an error document on some failures.
        if body.contains("<Error>") {
            bail!(
                "CompleteMultipartUpload reported an error: {}",
                first_chars(&body, 300)
            );
        }
        Ok(xml_text(&body, "ETag").map(|e| normalize_etag(&e)))
    }
}

fn signing_key(secret: &str, date_stamp: &str, region: &str) -> Result<HmacSha256> {
    let k_date = hmac(format!("AWS4{secret}").as_bytes(), date_stamp.as_bytes())?;
    let k_region = hmac(&k_date, region.as_bytes())?;
    let k_service = hmac(&k_region, b"s3")?;
    let k_signing = hmac(&k_service, b"aws4_request")?;
    HmacSha256::new_from_slice(&k_signing).map_err(|e| anyhow!("signing key: {e}"))
}

fn hmac(key: &[u8], data: &[u8]) -> Result<Vec<u8>> {
    let mut mac = HmacSha256::new_from_slice(key).map_err(|e| anyhow!("hmac key: {e}"))?;
    mac.update(data);
    Ok(mac.finalize().into_bytes().to_vec())
}

fn hex_lower(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        out.push(char::from_digit((b >> 4) as u32, 16).unwrap_or('0'));
        out.push(char::from_digit((b & 0xf) as u32, 16).unwrap_or('0'));
    }
    out
}

/// RFC 3986 encoding as SigV4 defines it: unreserved characters pass through,
/// everything else becomes `%XX` uppercase. `/` is left alone in a path
/// (`encode_slash = false`) and encoded in a query value.
fn uri_encode(s: &str, encode_slash: bool) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.as_bytes() {
        let c = *b as char;
        if c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '~' | '.') {
            out.push(c);
        } else if c == '/' && !encode_slash {
            out.push('/');
        } else {
            out.push('%');
            out.push(
                char::from_digit((b >> 4) as u32, 16)
                    .unwrap_or('0')
                    .to_ascii_uppercase(),
            );
            out.push(
                char::from_digit((b & 0xf) as u32, 16)
                    .unwrap_or('0')
                    .to_ascii_uppercase(),
            );
        }
    }
    out
}

fn host_of(endpoint: &str) -> Result<String> {
    let rest = endpoint
        .strip_prefix("https://")
        .or_else(|| endpoint.strip_prefix("http://"))
        .ok_or_else(|| anyhow!("endpoint has no scheme: {endpoint}"))?;
    let host = rest.split('/').next().unwrap_or("");
    if host.is_empty() {
        bail!("endpoint has no host: {endpoint}");
    }
    Ok(host.to_string())
}

/// Strip an ETag's quotes. Weak-validator ETags (`W/"..."`) are normalised the
/// same way; the watcher compares them as opaque strings.
pub fn normalize_etag(raw: &str) -> String {
    raw.trim()
        .trim_start_matches("W/")
        .trim_matches('"')
        .to_string()
}

fn first_chars(s: &str, n: usize) -> String {
    s.chars().take(n).collect()
}

/// A URL is safe to print here (SigV4 puts the signature in a header, not the
/// query), but presigned URLs would not be — so strip any query that carries
/// one rather than relying on the caller never passing one.
fn redact(url: &str) -> String {
    match url.split_once("X-Amz-Signature") {
        Some((head, _)) => format!("{head}X-Amz-Signature=<redacted>"),
        None => url.to_string(),
    }
}

/// The one XML shape the watcher parses. Written against the ListObjectsV2
/// response as AWS documents it and as MinIO and R2 emit it; `Key` values are
/// XML-unescaped, which matters for keys containing `&`.
pub fn parse_list_v2(body: &str) -> Result<ListPage> {
    // NOT `trim_text(true)`: that trims every text event, and quick-xml emits
    // an entity (`&amp;`) as its own event, so `a &amp; b` arrived as "a", "&",
    // "b" and became `a&b`, and a key ending in a space lost it. Either way the
    // watcher then asked for a key that does not exist and got a 404 on every
    // cycle, forever (F5 of the #968 review). Whitespace between elements is
    // discarded anyway: `text` is cleared at every start and end tag. Fields
    // that are not keys are trimmed where they are read.
    let mut reader = Reader::from_str(body);
    reader.config_mut().trim_text(false);

    let mut objects: Vec<ObjectMeta> = Vec::new();
    let mut common_prefixes: Vec<String> = Vec::new();
    let mut next_token: Option<String> = None;
    let mut truncated = false;

    let mut in_contents = false;
    let mut in_common = false;
    let mut field = String::new();
    let mut cur = ObjectMeta::default();
    let mut text = String::new();

    loop {
        match reader.read_event() {
            Ok(Event::Start(e)) => {
                let name = String::from_utf8_lossy(e.name().as_ref()).to_string();
                match name.as_str() {
                    "Contents" => {
                        in_contents = true;
                        cur = ObjectMeta::default();
                    }
                    "CommonPrefixes" => in_common = true,
                    _ => {}
                }
                field = name;
                text.clear();
            }
            Ok(Event::Text(t)) => {
                text.push_str(&t.xml10_content().unwrap_or_default());
            }
            Ok(Event::GeneralRef(r)) => {
                if let Some(resolved) = resolve_general_ref(&r) {
                    text.push_str(&resolved);
                }
            }
            Ok(Event::End(e)) => {
                let name = String::from_utf8_lossy(e.name().as_ref()).to_string();
                match name.as_str() {
                    "Contents" => {
                        in_contents = false;
                        if !cur.key.is_empty() {
                            objects.push(std::mem::take(&mut cur));
                        }
                    }
                    "CommonPrefixes" => in_common = false,
                    "Key" if in_contents => cur.key = text.clone(),
                    "ETag" if in_contents => cur.etag = normalize_etag(&text),
                    "Size" if in_contents => cur.size = text.trim().parse().unwrap_or(0),
                    "LastModified" if in_contents => cur.last_modified = text.trim().to_string(),
                    "Prefix" if in_common => common_prefixes.push(text.clone()),
                    "NextContinuationToken" => next_token = Some(text.trim().to_string()),
                    "IsTruncated" => truncated = text.trim().eq_ignore_ascii_case("true"),
                    _ => {}
                }
                field.clear();
                text.clear();
            }
            Ok(Event::Eof) => break,
            Ok(_) => {}
            Err(e) => bail!("malformed ListObjectsV2 XML: {e}"),
        }
    }
    let _ = field;

    // A truncated page with no token is a gateway bug we must not paper over:
    // silently stopping would report every unlisted object as deleted.
    if truncated && next_token.is_none() {
        bail!("ListObjectsV2 said IsTruncated but returned no NextContinuationToken");
    }
    Ok(ListPage {
        objects,
        next_token: if truncated { next_token } else { None },
        common_prefixes,
    })
}

/// quick-xml >= 0.38 emits `&amp;` and friends as their own event instead of
/// folding them into the neighbouring text, so a key containing an entity would
/// lose that character unless the reader puts it back. `extract::xml_x` has the
/// same helper but scoped `pub(super)`; this is the two-line version rather
/// than a visibility change in an unrelated module.
fn resolve_general_ref(r: &quick_xml::events::BytesRef) -> Option<String> {
    let name = String::from_utf8_lossy(r.as_ref()).to_string();
    if let Some(hexpart) = name.strip_prefix("#x").or_else(|| name.strip_prefix("#X")) {
        return u32::from_str_radix(hexpart, 16)
            .ok()
            .and_then(char::from_u32)
            .map(|c| c.to_string());
    }
    if let Some(dec) = name.strip_prefix('#') {
        return dec
            .parse::<u32>()
            .ok()
            .and_then(char::from_u32)
            .map(|c| c.to_string());
    }
    quick_xml::escape::resolve_predefined_entity(&name).map(str::to_string)
}

/// First text value of `<tag>` in a small response document.
fn xml_text(body: &str, tag: &str) -> Option<String> {
    let open = format!("<{tag}>");
    let close = format!("</{tag}>");
    let start = body.find(&open)? + open.len();
    let end = body[start..].find(&close)? + start;
    Some(body[start..end].trim().to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn s3_urls_parse_into_bucket_and_prefix() {
        assert_eq!(
            parse_s3_url("s3://logs/2026/09/").unwrap(),
            S3Location {
                bucket: "logs".into(),
                prefix: "2026/09/".into()
            }
        );
        assert_eq!(
            parse_s3_url("s3://logs").unwrap(),
            S3Location {
                bucket: "logs".into(),
                prefix: String::new()
            }
        );
        assert!(parse_s3_url("/tmp/folder").is_err());
        assert!(parse_s3_url("s3://").is_err());
        assert!(parse_s3_url("s3://bucket.example.com/x").is_err());
    }

    #[test]
    fn sigv4_uri_encoding_matches_the_spec() {
        // The four unreserved classes pass through; everything else is %XX
        // uppercase. `/` depends on position.
        assert_eq!(uri_encode("a-z_0.9~", false), "a-z_0.9~");
        assert_eq!(uri_encode("a/b", false), "a/b");
        assert_eq!(uri_encode("a/b", true), "a%2Fb");
        assert_eq!(uri_encode("a b", false), "a%20b");
        assert_eq!(uri_encode("ä", false), "%C3%A4");
        assert_eq!(uri_encode("+", false), "%2B");
    }

    /// AWS's published SigV4 test vector for the signing key derivation
    /// (`AWS4-HMAC-SHA256` documentation, service `iam`, region `us-east-1`,
    /// date `20150830`). Used here with service `s3` replaced only in our
    /// helper, so the vector is adapted: what it pins is the HMAC chain shape,
    /// which is the part that breaks silently.
    #[test]
    fn signing_key_chain_is_deterministic() {
        let a = hex_lower(
            &signing_key(
                "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY",
                "20150830",
                "us-east-1",
            )
            .unwrap()
            .chain_update(b"x")
            .finalize()
            .into_bytes(),
        );
        let b = hex_lower(
            &signing_key(
                "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY",
                "20150830",
                "us-east-1",
            )
            .unwrap()
            .chain_update(b"x")
            .finalize()
            .into_bytes(),
        );
        assert_eq!(a, b);
        assert_eq!(a.len(), 64);
        let other = hex_lower(
            &signing_key(
                "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY",
                "20150831",
                "us-east-1",
            )
            .unwrap()
            .chain_update(b"x")
            .finalize()
            .into_bytes(),
        );
        assert_ne!(a, other, "a different date must derive a different key");
    }

    #[test]
    fn hex_and_sha256_agree_with_the_known_empty_digest() {
        assert_eq!(
            hex_lower(&Sha256::digest(b"")),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
    }

    #[test]
    fn list_v2_response_parses_keys_etags_sizes_and_token() {
        let xml = r#"<?xml version="1.0" encoding="UTF-8"?>
<ListBucketResult>
  <Name>b</Name><Prefix>docs/</Prefix><KeyCount>2</KeyCount>
  <IsTruncated>true</IsTruncated>
  <NextContinuationToken>tok-1</NextContinuationToken>
  <Contents>
    <Key>docs/a&amp;b.md</Key>
    <LastModified>2026-09-19T10:00:00.000Z</LastModified>
    <ETag>&quot;d41d8cd98f00b204e9800998ecf8427e&quot;</ETag>
    <Size>12</Size>
  </Contents>
  <Contents>
    <Key>docs/big.bin</Key>
    <LastModified>2026-09-19T11:00:00.000Z</LastModified>
    <ETag>&quot;abc123-4&quot;</ETag>
    <Size>10485760</Size>
  </Contents>
  <CommonPrefixes><Prefix>docs/sub/</Prefix></CommonPrefixes>
</ListBucketResult>"#;
        let page = parse_list_v2(xml).unwrap();
        assert_eq!(page.objects.len(), 2);
        assert_eq!(page.objects[0].key, "docs/a&b.md");
        assert_eq!(page.objects[0].etag, "d41d8cd98f00b204e9800998ecf8427e");
        assert_eq!(page.objects[0].size, 12);
        assert_eq!(
            page.objects[1].etag, "abc123-4",
            "multipart ETag keeps its -N"
        );
        assert_eq!(page.objects[1].size, 10_485_760);
        assert_eq!(page.next_token.as_deref(), Some("tok-1"));
        assert_eq!(page.common_prefixes, vec!["docs/sub/".to_string()]);
    }

    /// F5 of the #968 review, as a table: every key the parser used to change.
    /// A key is opaque bytes; the listing must hand back exactly what was PUT.
    #[test]
    fn keys_come_back_from_the_listing_byte_for_byte() {
        fn page(key_xml: &str) -> String {
            format!(
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?><ListBucketResult>\
                 <IsTruncated>false</IsTruncated><Contents><Key>{key_xml}</Key>\
                 <LastModified>2026-09-19T10:00:00.000Z</LastModified>\
                 <ETag>&quot;abc&quot;</ETag><Size> 7 </Size></Contents></ListBucketResult>"
            )
        }
        for (xml, want) in [
            ("docs/a &amp; b.md", "docs/a & b.md"),
            ("&#32;leading.txt", " leading.txt"),
            ("trailing&#32;.txt", "trailing .txt"),
            ("a&amp;b.md", "a&b.md"),
            ("tab&#9;sep.txt", "tab\tsep.txt"),
            ("x &lt;y&gt; z", "x <y> z"),
            ("new&#10;line.txt", "new\nline.txt"),
            (" rawlead.txt", " rawlead.txt"),
            ("rawtrail.txt ", "rawtrail.txt "),
            ("a &amp;&amp; b", "a && b"),
            ("mid  double.txt", "mid  double.txt"),
            ("ends ", "ends "),
            ("   ", "   "),
        ] {
            let got = parse_list_v2(&page(xml)).unwrap();
            assert_eq!(got.objects.len(), 1, "{xml:?}");
            assert_eq!(got.objects[0].key, want, "listing XML {xml:?}");
            assert_eq!(got.objects[0].size, 7, "numeric fields are still trimmed");
            assert_eq!(got.objects[0].etag, "abc");
        }
    }

    /// Whitespace-only text between elements must not leak into a field once
    /// trimming is off: pretty-printed XML is what MinIO and R2 both emit.
    #[test]
    fn indentation_between_elements_does_not_leak_into_fields() {
        let xml = "<ListBucketResult>\n  <IsTruncated>true</IsTruncated>\n  \
                   <NextContinuationToken>\n tok \n</NextContinuationToken>\n  <Contents>\n    \
                   <Key>k</Key>\n    <ETag>\"e\"</ETag>\n    <Size>\n3\n</Size>\n  </Contents>\n\
                   </ListBucketResult>";
        let p = parse_list_v2(xml).unwrap();
        assert_eq!(p.objects[0].key, "k");
        assert_eq!(p.objects[0].size, 3);
        assert_eq!(p.next_token.as_deref(), Some("tok"));
    }

    /// A dot-segment key would be sent as a different path than the one signed.
    /// It must be refused before any request goes out.
    #[test]
    fn a_key_the_url_parser_would_rewrite_is_refused_before_sending() {
        let src = S3Source::new(
            "http://127.0.0.1:9",
            "auto",
            Credentials {
                access_key_id: "k".into(),
                secret_access_key: "s".into(),
                session_token: None,
            },
            S3Location {
                bucket: "b".into(),
                prefix: String::new(),
            },
            Duration::from_secs(1),
        )
        .unwrap();
        for key in ["dots/../up.txt", "a/./b.txt", "..", "x/.."] {
            let err = src.get(key, 10).err().expect(key).to_string();
            assert!(err.contains("cannot be addressed"), "{key}: {err}");
        }
    }

    #[test]
    fn an_untruncated_page_reports_no_token() {
        let xml = "<ListBucketResult><IsTruncated>false</IsTruncated>\
                   <NextContinuationToken>stale</NextContinuationToken></ListBucketResult>";
        assert!(parse_list_v2(xml).unwrap().next_token.is_none());
    }

    /// The failure this guards is the dangerous one: a page that says there is
    /// more but hands back no cursor. Treating it as the end of the bucket
    /// would report every unlisted object as deleted.
    #[test]
    fn truncated_without_a_token_is_an_error_not_an_empty_tail() {
        let xml = "<ListBucketResult><IsTruncated>true</IsTruncated></ListBucketResult>";
        let err = parse_list_v2(xml).unwrap_err().to_string();
        assert!(err.contains("NextContinuationToken"), "{err}");
    }

    #[test]
    fn etags_are_normalised_without_losing_the_multipart_suffix() {
        assert_eq!(normalize_etag("\"abc\""), "abc");
        assert_eq!(normalize_etag("W/\"abc\""), "abc");
        assert_eq!(normalize_etag("\"abc-12\""), "abc-12");
    }
}

//! Watcher behaviour, against an in-memory store that counts what it was asked.
//!
//! These tests own the semantics: what counts as changed, that an unchanged
//! bucket costs zero GETs and a bounded number of list calls, that a delete
//! removes records, that an object replaced mid-cycle is not lost, and that the
//! cost guard refuses before spending. The same scenarios run against a real
//! MinIO in `tests/objwatch_minio.rs`; this file is where they are cheap enough
//! to run on every `cargo test`.

use super::*;
use std::collections::BTreeMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

#[derive(Clone)]
struct StoredObject {
    bytes: Vec<u8>,
    etag: String,
    last_modified: String,
}

/// The hook one test uses to mutate the store DURING a fetch, which is how the
/// "replaced while the cycle was reading it" case is reproduced deterministically.
type AfterGet = Box<dyn Fn(&FakeStore, &str) + Send>;

/// An S3-shaped store: sorted keys, `max-keys` paging, continuation tokens,
/// ETag on GET. Counts every call, which is the point.
struct FakeStore {
    objects: Mutex<BTreeMap<String, StoredObject>>,
    list_calls: AtomicU64,
    gets: AtomicU64,
    /// Run after each GET, so a test can replace an object while a cycle is in
    /// flight.
    after_get: Mutex<Option<AfterGet>>,
    /// Drop the ETag from GET responses, the way some gateways and proxies do.
    no_etag_on_get: AtomicU64,
    /// Fail the list call with this 0-based number, the way a 503 SlowDown
    /// does. `u64::MAX` = never.
    fail_list_call: AtomicU64,
    /// Run before each list call is served, with its 0-based number. Lets a
    /// test observe the world MID-SCAN — which is how the crash-safety of the
    /// spend ledger is checked without killing the test process.
    #[allow(clippy::type_complexity)]
    on_list: Mutex<Option<Box<dyn Fn(u64) + Send>>>,
}

impl FakeStore {
    fn new() -> FakeStore {
        FakeStore {
            objects: Mutex::new(BTreeMap::new()),
            list_calls: AtomicU64::new(0),
            gets: AtomicU64::new(0),
            after_get: Mutex::new(None),
            no_etag_on_get: AtomicU64::new(0),
            fail_list_call: AtomicU64::new(u64::MAX),
            on_list: Mutex::new(None),
        }
    }

    fn put(&self, key: &str, body: &str) {
        self.put_with_etag(
            key,
            body,
            &format!("etag-{:x}", xxhash_rust::xxh3::xxh3_64(body.as_bytes())),
        );
    }

    fn put_with_etag(&self, key: &str, body: &str, etag: &str) {
        let mut m = self.objects.lock().unwrap();
        let n = m.len();
        m.insert(
            key.to_string(),
            StoredObject {
                bytes: body.as_bytes().to_vec(),
                etag: etag.to_string(),
                last_modified: format!("2026-09-19T10:{:02}:00.000Z", n % 60),
            },
        );
    }

    fn remove(&self, key: &str) {
        self.objects.lock().unwrap().remove(key);
    }

    fn list_calls(&self) -> u64 {
        self.list_calls.load(Ordering::SeqCst)
    }

    fn gets(&self) -> u64 {
        self.gets.load(Ordering::SeqCst)
    }
}

impl ObjectSource for FakeStore {
    fn describe(&self) -> String {
        "s3://fake/ @ memory".into()
    }

    fn list(&self, req: &ListRequest) -> Result<ListPage> {
        let n = self.list_calls.fetch_add(1, Ordering::SeqCst);
        if let Some(f) = self.on_list.lock().unwrap().as_ref() {
            f(n);
        }
        if n == self.fail_list_call.load(Ordering::SeqCst) {
            anyhow::bail!("ListObjectsV2 returned 503 Service Unavailable: SlowDown");
        }
        let m = self.objects.lock().unwrap();
        let after = req.continuation_token.or(req.start_after);
        let mut objects: Vec<ObjectMeta> = Vec::new();
        let mut next = None;
        for (key, o) in m.iter() {
            if !key.starts_with(req.prefix) {
                continue;
            }
            if let Some(a) = after {
                if key.as_str() <= a {
                    continue;
                }
            }
            if objects.len() as u64 >= req.max_keys {
                next = Some(objects.last().map(|o| o.key.clone()).unwrap_or_default());
                break;
            }
            objects.push(ObjectMeta {
                key: key.clone(),
                size: o.bytes.len() as u64,
                etag: o.etag.clone(),
                last_modified: o.last_modified.clone(),
            });
        }
        Ok(ListPage {
            objects,
            next_token: next,
            common_prefixes: Vec::new(),
        })
    }

    fn get(&self, key: &str, max_bytes: u64) -> Result<FetchedObject> {
        self.gets.fetch_add(1, Ordering::SeqCst);
        let (bytes, etag) = {
            let m = self.objects.lock().unwrap();
            let o = m
                .get(key)
                .ok_or_else(|| anyhow::anyhow!("no such key {key}"))?;
            (o.bytes.clone(), o.etag.clone())
        };
        let hook = self.after_get.lock().unwrap();
        if let Some(f) = hook.as_ref() {
            f(self, key);
        }
        let truncated = bytes.len() as u64 > max_bytes;
        let bytes = if truncated {
            bytes[..max_bytes as usize].to_vec()
        } else {
            bytes
        };
        Ok(FetchedObject {
            bytes,
            etag: if self.no_etag_on_get.load(Ordering::SeqCst) == 1 {
                None
            } else {
                Some(etag)
            },
            truncated,
        })
    }
}

/// Records every event, in order, and can run a hook while it is "indexing".
#[derive(Default)]
struct RecordingSink {
    events: Vec<(String, String)>,
    fail_on: Option<String>,
    during_accept: Option<Box<dyn Fn() + Send>>,
}

impl ChangeSink for RecordingSink {
    fn accept(&mut self, ev: &ChangeEvent) -> Result<()> {
        if self.fail_on.as_deref() == Some(ev.key.as_str()) {
            anyhow::bail!("sink refused {}", ev.key);
        }
        if let Some(f) = &self.during_accept {
            f();
        }
        self.events
            .push((ev.kind.as_str().to_string(), ev.key.clone()));
        Ok(())
    }
}

impl RecordingSink {
    fn keys(&self, kind: &str) -> Vec<String> {
        self.events
            .iter()
            .filter(|(k, _)| k == kind)
            .map(|(_, key)| key.clone())
            .collect()
    }
    fn clear(&mut self) {
        self.events.clear();
    }
}

fn opts() -> WatchOptions {
    WatchOptions {
        poll_interval: Duration::from_secs(300),
        max_cycles: Some(1),
        fetch: true,
        max_object_bytes: 1 << 20,
        append_only: false,
        max_monthly_class_a: cost::DEFAULT_MAX_MONTHLY_CLASS_A,
        max_monthly_class_b: cost::DEFAULT_MAX_MONTHLY_CLASS_B,
        allow_cost: false,
        page_size: 1_000,
        status_path: None,
        dry_run: false,
    }
}

fn journal(dir: &std::path::Path) -> WatchJournal {
    WatchJournal::open(dir, "http://memory", "fake", "", false, false).unwrap()
}

fn never_stop() -> impl Fn() -> bool {
    || false
}

#[test]
fn the_first_poll_indexes_everything_and_the_second_indexes_nothing() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.put("a.md", "alpha");
    store.put("b.txt", "beta");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink::default();
    let mut totals = CostTotals::default();
    let o = opts();

    let first = poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    assert_eq!(first.added, 2);
    assert_eq!(first.changed, 0);
    assert_eq!(first.deleted, 0);
    assert_eq!(first.gets, 2, "the first poll fetches both objects");
    assert_eq!(first.list_calls, 1);
    assert_eq!(sink.keys("added"), vec!["a.md", "b.txt"]);

    // THE load-bearing assertion for cost: an unchanged bucket costs one list
    // call and ZERO GETs. A watcher that re-reads bytes every cycle would pass
    // every other test in this file and quietly bill for it.
    sink.clear();
    let gets_before = store.gets();
    let second = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(second.added, 0);
    assert_eq!(second.changed, 0);
    assert_eq!(second.deleted, 0);
    assert_eq!(second.unchanged, 2);
    assert_eq!(second.gets, 0, "an unchanged object must not be fetched");
    assert_eq!(store.gets(), gets_before);
    assert_eq!(second.list_calls, 1, "one list call for a 2-object bucket");
    assert!(sink.events.is_empty());

    // The reported cost must be the cost the STORE actually served, not a number
    // the accounting produced on its own. Every billing claim in the docs rests
    // on this count, so it is asserted against the other side of the call.
    assert_eq!(
        store.list_calls(),
        2,
        "two cycles served two ListObjectsV2 calls"
    );
    assert_eq!(store.list_calls(), totals.list_calls);
    assert_eq!(store.gets(), totals.gets);
}

#[test]
fn a_changed_object_is_re_extracted_a_new_one_is_added_and_a_deleted_one_is_removed() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.put("keep.md", "keep");
    store.put("edit.md", "before");
    store.put("gone.md", "gone");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink::default();
    let mut totals = CostTotals::default();
    let o = opts();
    poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    sink.clear();

    store.put("edit.md", "after");
    store.put("new.md", "new");
    store.remove("gone.md");

    let r = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(r.changed, 1);
    assert_eq!(r.added, 1);
    assert_eq!(r.deleted, 1);
    assert_eq!(r.unchanged, 1);
    assert_eq!(sink.keys("changed"), vec!["edit.md"]);
    assert_eq!(sink.keys("added"), vec!["new.md"]);
    assert_eq!(sink.keys("deleted"), vec!["gone.md"]);
    assert_eq!(r.gets, 2, "only the changed and the new object are fetched");
    assert!(
        j.get("gone.md").is_none(),
        "a deleted key leaves the journal"
    );
    assert!(j.get("edit.md").unwrap().digest.is_some());
}

/// An object replaced by a multipart upload keeps its size and can keep its
/// last-modified second, but its ETag stops being an MD5 and becomes
/// `<hex>-<parts>`. The watcher must notice on the ETag alone.
/// An object replaced by a multipart upload. The ETag stops being an MD5 and
/// becomes `<hex>-<parts>`, which must be compared as an opaque string and never
/// read as a content hash.
///
/// Both halves matter, and they used to be conflated. Replacing the CONTENT via
/// multipart is a change. Re-uploading the SAME bytes via multipart is only ETag
/// churn, and re-indexing it would cost a bulk request, a merge and a refresh for
/// nothing — so it is deliberately not a change. The original version of this
/// test asserted a change for identical bytes and was wrong about the intended
/// behaviour, not about the code.
#[test]
fn a_multipart_replacement_is_detected_by_the_etag_shape_change() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.put_with_etag("big.bin", "0123456789", "d41d8cd98f00b204e9800998ecf8427e");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink::default();
    let mut totals = CostTotals::default();
    let o = opts();
    poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    sink.clear();

    // New content, delivered multipart: the ETag's SHAPE changes as well as its
    // value, and a size comparison alone would still catch this one.
    store.put_with_etag(
        "big.bin",
        "0123456789abc",
        "9a0364b9e99bb480dd25e1f0284c8555-2",
    );
    let r = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(
        r.changed, 1,
        "multipart content replacement must be a change"
    );
    assert_eq!(r.content_identical, 0);
    assert_eq!(sink.keys("changed"), vec!["big.bin"]);
    let recorded = j.get("big.bin").unwrap().etag.clone();
    assert!(
        recorded.ends_with("-2"),
        "the part-count suffix is kept verbatim, never parsed as a hash: {recorded}"
    );
    sink.clear();

    // Same bytes re-uploaded multipart under yet another ETag: churn, not a
    // change. The journal still catches up so the NEXT cycle is free again.
    store.put_with_etag(
        "big.bin",
        "0123456789abc",
        "ffffffffffffffffffffffffffffffff-3",
    );
    let r = poll_once(&store, &mut j, &o, &mut sink, 2, &mut totals, &never_stop()).unwrap();
    assert_eq!(
        r.changed, 0,
        "identical bytes under a new ETag is not a change"
    );
    assert_eq!(r.content_identical, 1);
    assert!(sink.keys("changed").is_empty());
    assert!(j.get("big.bin").unwrap().etag.ends_with("-3"));
    let r = poll_once(&store, &mut j, &o, &mut sink, 3, &mut totals, &never_stop()).unwrap();
    assert_eq!(r.gets, 0, "and the cycle after the churn costs nothing");
}

/// The overlap case: the object is replaced WHILE the cycle is fetching and
/// indexing it. The journal must end up describing the bytes that were indexed,
/// and the next cycle must re-index exactly once — never zero times (a lost
/// update) and never twice for the same bytes (a double index).
#[test]
fn an_object_replaced_during_a_cycle_is_re_indexed_exactly_once() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.put("live.md", "v1");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink::default();
    let mut totals = CostTotals::default();
    let o = opts();

    // Replace the object right after the GET that read v1 — the window a
    // poll-then-fetch watcher actually has.
    *store.after_get.lock().unwrap() = Some(Box::new(|s: &FakeStore, key: &str| {
        if key == "live.md" {
            let already = s
                .objects
                .lock()
                .unwrap()
                .get(key)
                .map(|o| o.bytes == b"v2")
                .unwrap_or(false);
            if !already {
                s.put("live.md", "v2");
            }
        }
    }));

    let first = poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    assert_eq!(first.added, 1);
    // What the journal remembers is what was read, so the newer bytes are still
    // outstanding.
    let recorded = j.get("live.md").unwrap().clone();
    assert_eq!(
        recorded.digest.unwrap(),
        format!("{:016x}", xxhash_rust::xxh3::xxh3_64(b"v1"))
    );

    *store.after_get.lock().unwrap() = None;
    sink.clear();
    let second = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(second.changed, 1, "the update made mid-cycle is not lost");
    assert_eq!(sink.keys("changed"), vec!["live.md"]);

    sink.clear();
    let third = poll_once(&store, &mut j, &o, &mut sink, 2, &mut totals, &never_stop()).unwrap();
    assert_eq!(third.changed, 0, "and it is not indexed a second time");
    assert_eq!(third.gets, 0);
    assert!(sink.events.is_empty());
}

/// A sink that refuses one object must not have that object recorded as done —
/// otherwise the failure is permanent and silent.
#[test]
fn an_object_the_sink_refused_is_retried_on_the_next_cycle() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.put("ok.md", "fine");
    store.put("bad.md", "boom");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink {
        fail_on: Some("bad.md".into()),
        ..Default::default()
    };
    let mut totals = CostTotals::default();
    let o = opts();
    let first = poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    assert_eq!(first.added, 1);
    assert_eq!(first.errors.len(), 1, "{:?}", first.errors);
    assert!(j.get("bad.md").is_none());

    sink.fail_on = None;
    sink.clear();
    let second = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(second.added, 1);
    assert_eq!(sink.keys("added"), vec!["bad.md"]);
}

#[test]
fn a_store_that_omits_the_etag_on_get_verifies_by_digest_once_then_settles() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.no_etag_on_get.store(1, Ordering::SeqCst);
    store.put("a.md", "alpha");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink::default();
    let mut totals = CostTotals::default();
    let o = opts();
    poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    assert!(
        j.get("a.md").unwrap().etag_unverified,
        "the recorded ETag came from the listing, not from the bytes we read"
    );
    sink.clear();
    // Nothing changed in the bucket, but the recorded ETag describes bytes we
    // did not verify, so the next cycle re-reads once. The digest matches, so it
    // is recorded as the same bytes and NOT re-indexed.
    let second = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(second.gets, 1);
    assert_eq!(second.changed, 0);
    assert_eq!(second.content_identical, 1);
    assert!(sink.events.is_empty());
    assert!(
        !j.get("a.md").unwrap().etag_unverified,
        "one verification is enough — a store with no ETags must not cost a GET every cycle"
    );
    // And now it is free.
    let third = poll_once(&store, &mut j, &o, &mut sink, 2, &mut totals, &never_stop()).unwrap();
    assert_eq!(third.gets, 0);
    assert_eq!(third.unchanged, 1);
}

/// ETag churn: a copy or a lifecycle rewrite gives the same bytes a new ETag.
/// The watcher pays one GET to find out and then must NOT re-index.
#[test]
fn an_etag_rewritten_over_identical_bytes_is_not_re_indexed() {
    let dir = tempfile::tempdir().unwrap();
    let store = FakeStore::new();
    store.put_with_etag("a.md", "alpha", "etag-1");
    let mut j = journal(dir.path());
    let mut sink = RecordingSink::default();
    let mut totals = CostTotals::default();
    let o = opts();
    poll_once(&store, &mut j, &o, &mut sink, 0, &mut totals, &never_stop()).unwrap();
    sink.clear();
    store.put_with_etag("a.md", "alpha", "etag-2");
    let r = poll_once(&store, &mut j, &o, &mut sink, 1, &mut totals, &never_stop()).unwrap();
    assert_eq!(r.gets, 1, "it must read the bytes to know");
    assert_eq!(r.changed, 0);
    assert_eq!(r.content_identical, 1);
    assert!(sink.events.is_empty());
    assert_eq!(
        j.get("a.md").unwrap().etag,
        "etag-2",
        "the new ETag is recorded"
    );
    // Settled: the next cycle is free.
    let third = poll_once(&store, &mut j, &o, &mut sink, 2, &mut totals, &never_stop()).unwrap();
    assert_eq!(third.gets, 0);
    assert_eq!(third.unchanged, 1);
}

