            etag: "e".into(),
            size: 1,
            last_modified: "lm".into(),
            digest: None,
            etag_unverified: false,
            seen_at: "t".into(),
            truncated: false,
        },
    );
    let listed = vec![
        ObjectMeta {
            key: "same".into(),
            size: 1,
            etag: "e".into(),
