            vec!["ax-code".to_string(), "ax-docs".to_string()],
            "{n:?}"
        );
        let ids = row_ids(&plan);
        assert!(!ids.iter().any(|id| id.starts_with("ds:ax-2")), "{ids:?}");
        assert!(!ids.contains(&"run:other".to_string()), "{ids:?}");
    }

