    fn an_unfinished_journal_names_the_partial_prefix() {
        let text = "\
{\"kind\":\"run\",\"root\":\"/site\",\"url\":\"http://127.0.0.1:9200/\",\"prefix\":\"wp-rebuild\"}\n\
{\"kind\":\"plan\",\"plan\":{\"datasets\":[{\"index\":\"wp-rebuild-pages\"},{\"index\":\"wp-rebuild-posts\"}],\"files\":{}}}\n";
