    #[test]
    fn a_pending_generation_is_an_orphan_source_and_a_commit_is_not() {
        let open = "\
{\"kind\":\"run\",\"root\":\"/site\",\"url\":\"http://127.0.0.1:9200\",\"prefix\":\"wp-rebuild\"}\n\
{\"kind\":\"sync_begin\",\"desired\":{\"plan\":{\"datasets\":[{\"index\":\"wp-rebuild-posts\"}]}}}\n";
        assert_eq!(
