    /// #551: a markdown/prose file that opens with a `---` frontmatter block was
    /// sniffed as YAML — the YAML extractor keeps the frontmatter mapping and the
    /// first paragraph and discards the body (silent data loss on the dominant
    /// markdown convention: Jekyll/Hugo/Obsidian/Docusaurus/MkDocs/Astro, and
    /// Claude Code skill files). With the closing-`---` lookahead the file is
    /// classified by its body — identically to a frontmatter-less twin — so the
    /// whole document is indexed.
    #[test]
    fn markdown_frontmatter_is_classified_by_its_body_not_yaml() {
        let with_frontmatter = "---\n\
                                title: Widget outage\n\
                                date: 2026-01-15\n\
                                tags: [widget, outage]\n\
                                ---\n\n\
                                # Outage postmortem\n\n\
                                The sprocket pool was exhausted.\n\n\
                                ## Resolution\n\
                                Raised the sprocket pool size from 4 to 16.\n";
        // Byte-identical body, no frontmatter.
        let no_frontmatter = "# Outage postmortem\n\n\
                              The sprocket pool was exhausted.\n\n\
                              ## Resolution\n\
                              Raised the sprocket pool size from 4 to 16.\n";
        let twin = classify_full(no_frontmatter);
        assert_ne!(
            twin,
            Family::Yaml,
            "sanity: the body itself is prose, not YAML"
        );
        assert_eq!(
            classify_full(with_frontmatter),
            twin,
            "markdown frontmatter must be classified by its body, identical to the \
             frontmatter-less twin, not routed to the YAML extractor (#551)"
        );
    }

    /// #587 (item 1): the #551 frontmatter lookahead classified the body with
    /// `txt_kind` only, so a frontmatter-over-CSV/JSON body was mislabelled a
    /// prose family while its frontmatter-less twin was `Csv`/`Jsonl`. Running
    /// the body through the structured branches makes the family match the twin
    /// for a structured body (a prose body still classifies as prose — the #551
    /// test above).
    #[test]
    fn frontmatter_over_a_structured_body_is_classified_by_that_body() {
        // CSV body under YAML frontmatter.
        let csv_body = "name,role,team\n\
                        alice,eng,core\n\
                        bob,design,platform\n\
                        carol,pm,growth\n";
        let csv_with_frontmatter =
            format!("---\ntitle: Team roster\nowner: ops\n---\n\n{csv_body}");
        let csv_twin = classify_full(csv_body);
        assert_eq!(csv_twin, Family::Csv, "sanity: the bare body is CSV");
        assert_eq!(
            classify_full(&csv_with_frontmatter),
            csv_twin,
            "a frontmatter-over-CSV body must be classified by its structured family \
             (CSV), identical to the frontmatter-less twin (#587)"
        );

        // JSONL body under YAML frontmatter.
        let json_body = "{\"id\":1,\"name\":\"a\"}\n{\"id\":2,\"name\":\"b\"}\n";
        let json_with_frontmatter = format!("---\nsource: export\ncount: 2\n---\n\n{json_body}");
        let json_twin = classify_full(json_body);
        assert_eq!(json_twin, Family::Jsonl, "sanity: the bare body is JSONL");
        assert_eq!(
            classify_full(&json_with_frontmatter),
            json_twin,
            "a frontmatter-over-JSON body must be classified by its structured family \
             (JSONL), identical to the frontmatter-less twin (#587)"
        );
    }

    /// #551 guardrail: the frontmatter lookahead must not reclassify real YAML.
    /// A single document (leading `---` marker, no prose body) and a
    /// multi-document stream (the body after the first `---` separator is itself
    /// YAML) both stay `Yaml`.
    #[test]
    fn yaml_documents_are_unaffected_by_the_frontmatter_lookahead() {
        let pure = "---\n\
                    name: widget-service\n\
                    replicas: 3\n\
                    ports:\n\
                    \x20 - 8080\n\
                    \x20 - 9090\n\
                    env:\n\
                    \x20 LOG_LEVEL: info\n";
        assert_eq!(classify_full(pure), Family::Yaml);

        let multi = "---\n\
                     name: first\n\
                     value: 1\n\
                     ---\n\
                     name: second\n\
                     value: 2\n\
                     kind: config\n";
        assert_eq!(classify_full(multi), Family::Yaml);
    }

    /// #587 (item 2): the lookahead's only test for "is this body YAML?" was
    /// the *line shape* of the body — majority `key:` / `- item`. A genuine
    /// multi-document YAML stream whose second document is dominated by a
    /// block scalar, comments and continuation lines fails that test (those
    /// lines are not `key:`-shaped), so the whole stream was re-classified as
    /// prose and lost its per-document key structure. `parses_as_yaml_stream`
    /// separates the two: this body parses as a YAML mapping, whereas a
    /// markdown body halts `serde_yaml`'s iterator.
    #[test]
    fn multi_document_yaml_with_a_prose_heavy_document_stays_yaml() {
        let multi = "---\n\
                     name: release-notes\n\
                     version: 2.4.0\n\
                     ---\n\
                     # notes for the operators\n\
                     summary: |\n\
                     \x20 The sprocket pool was exhausted during the Tuesday deploy.\n\
                     \x20 Raising the pool size from 4 to 16 restored throughput.\n\
                     \x20 Watch the queue depth dashboard for the next 24 hours.\n\
                     \x20 A follow-up ticket tracks the autoscaler change.\n";
        // Guard the premise: the body really is majority non-`key:`-shaped, so
        // the line-shape tier alone routes it away from YAML.
        let body: Vec<&str> = multi
            .lines()
            .filter(|l| !l.trim().is_empty())
            .skip(4)
            .collect();
        assert!(
            yaml_like_count(&body) * 2 < body.len(),
            "premise: the prose-heavy document is not majority YAML-shaped"
        );
        assert_eq!(
            classify_full(multi),
            Family::Yaml,
            "a multi-document YAML stream whose later document is prose-heavy must \
             stay YAML — it parses as a YAML stream, unlike a markdown body (#587)"
        );
    }

    /// #587 (item 3): the lookahead required `body.len() >= 2`, so a
    /// frontmatter file whose body is a single non-blank line still went to
    /// the YAML extractor, which keeps the frontmatter mapping and discards
    /// that line — the #551 loss, on the smallest possible file.
    #[test]
    fn frontmatter_over_a_single_prose_line_is_classified_by_that_line() {
        let note = "---\n\
                    title: Standup note\n\
                    date: 2026-02-03\n\
                    ---\n\n\
                    Deploy is blocked on the sprocket pool change.\n";
        assert_eq!(
            classify_full(note),
            Family::TxtProse,
            "a one-line prose body under frontmatter must be classified by that \
             line, not handed to the YAML extractor that drops it (#587)"
        );

        // The other side of the same boundary: a one-line *YAML* body after a
        // document separator is still YAML.
        let yaml = "---\n\
                    name: first\n\
                    ---\n\
                    name: second\n";
        assert_eq!(classify_full(yaml), Family::Yaml);
    }

    /// Guardrail for the parse tier added in #587 item 2: it must not drag
    /// ordinary markdown bodies back into YAML. Each of these is a real
    /// markdown shape whose body is majority non-`key:`-shaped, so each one
    /// reaches the parse; each must still come out prose.
    #[test]
    fn markdown_bodies_are_not_rescued_into_yaml_by_the_parse_tier() {
        let bodies = [
            // Task list — `- [ ] x` is invalid YAML (flow sequence then scalar).
            "- [ ] drain the pool\n- [x] raise the limit\n- [ ] verify p99\n",
            // Fenced code block.
            "# How to\nRun this:\n```sh\nxerj autoindex .\n```\nThen read the catalog.\n",
            // Table.
            "| stage | owner |\n|---|---|\n| build | core |\n| ship | ops |\n",
            // Headings and paragraphs.
            "# Title\n## Section one\nSome text about the thing.\n## Section two\nMore text.\n",
            // Emphasis opener — `*` is the YAML alias indicator.
            "**Note**: the pool is small.\nRaise it before the next deploy.\n",
        ];
        for body in bodies {
            let with_frontmatter = format!("---\ntitle: Note\nowner: ops\n---\n\n{body}");
            assert_ne!(
                classify_full(&with_frontmatter),
                Family::Yaml,
                "markdown body must not be classified YAML by the parse tier: {body:?}"
            );
        }
    }

    /// The record-stream side must be unaffected — these are what TxtLines is for.
    #[test]
    fn access_logs_stay_line_records() {
        let log = (0..20)
            .map(|i| format!(
                "10.0.0.{i} - - [01/Jun/2026:10:00:00 +0000] \"GET /api/checkout HTTP/1.1\" 200 {i}00 \"-\" \"Mozilla/5.0\""
            ))
            .collect::<Vec<_>>()
            .join("\n");
        assert_eq!(classify_full(&log), Family::Logs);
    }

    #[test]
    fn syslog_stays_line_records() {
        // One message in five ends with a period — well under the threshold.
        let msgs = [
            "sshd[123]: Accepted publickey for deploy from 10.0.3.4 port 55212",
            "kernel: Out of memory: Killed process 8123 (java)",
            "cron[99]: session opened for user root by (uid=0)",
            "postfix[7]: connection timed out while talking to upstream",
            "systemd[1]: Started Daily apt download activities.",
        ];
        let log = (0..6)
            .flat_map(|_| msgs.iter().map(|m| format!("Jun  1 10:00:00 host1 {m}")))
            .collect::<Vec<_>>()
            .join("\n");
        assert_eq!(classify_full(&log), Family::Logs);
    }

    #[test]
    fn source_code_stays_line_records() {
        let code = "pub struct Pool { max: usize, in_use: usize }\n\
                    impl Pool {\n\
                    pub fn acquire(&mut self) -> Result<Conn, PoolError> {\n\
                    if self.in_use >= self.max { return Err(PoolError::Exhausted); }\n\
                    self.in_use += 1;\n\
                    Ok(Conn::new())\n\
                    }\n\
                    }\n\
                    fn helper() -> u32 { 42 }\n\
                    const LIMIT: usize = 10;\n";
        assert_eq!(kind(code), Family::TxtLines);
    }

    #[test]
    fn long_lines_are_prose_regardless_of_punctuation() {
        let t = (0..10)
            .map(|_| "x".repeat(120))
            .collect::<Vec<_>>()
            .join("\n");
        assert_eq!(kind(&t), Family::TxtProse);
    }

    /// Regression: a markdown checklist (`- [ ]` task items under a heading)
    /// used to sniff as YAML — 2 of 3 nonblank lines start with `- ` — and
    /// the YAML extractor then junk-filed it (and, before the yaml_x
    /// non-progress fix, hung on it). Checkbox items are invalid YAML and
    /// must not count as YAML evidence.
    #[test]
    fn markdown_checklist_is_prose_not_yaml() {
        let md = "# Launch checklist\n\n\
                  - [ ] Sign off the [business plan](01-business-plan.md)\n\
                  - [x] Close out permits\n\
                  - [ ] Dry run: two full batches back to back\n";
        assert_eq!(classify_full(md), Family::TxtProse);
        // A real YAML list is still YAML.
        let yaml = "- alpha\n- beta\n- gamma\n";
        assert_eq!(classify_full(yaml), Family::Yaml);
    }

    /// Regression (second-brain demo vault, live 2026-07-30): a markdown
    /// note hard-wrapped at ~75 columns averages < 60 chars/line and ends
    /// most lines mid-sentence, so it scored below the 0.40 sentence ratio
    /// and landed in TxtLines — silently losing its title, its `s0` section
    /// anchor, and its wikilink detection (8 of 39 vault files). A file that
    /// opens with an ATX heading and shows markdown link syntax (or some
    /// terminal punctuation) is markdown prose.
    #[test]
    fn hard_wrapped_markdown_note_is_prose_not_lines() {
        let md = "# Hydration\n\n\
                  Hydration is water as a percentage of flour weight, the core of\n\
                  [[baker-percentages]]. 65% is a tight sandwich loaf; 75-80% is where open\n\
                  [[crumb-structure]] lives; past 85% the dough demands real skill.\n\n\
                  Higher hydration = looser dough, longer bulk, bigger holes. It is the single\n\
                  most consequential number in the formula.\n";
        assert_eq!(classify_full(md), Family::TxtProse);
        // No heading opener → the rescue must not fire: a Python file whose
        // comment banner starts mid-file stays wherever the base heuristics
        // put it, and a shebang is not a heading.
        let sh = "#!/usr/bin/env bash\n\
                  set -euo pipefail\n\
                  for f in a b c; do\n\
                  echo one\n\
                  echo two\n\
                  echo three\n\
                  done\n";
        assert_eq!(classify_full(sh), Family::TxtLines);
    }
}

#[cfg(test)]
mod mail_and_archive_sniff_tests {
    use super::*;
    use std::path::Path;

    fn sniffed(bytes: &[u8], name: &str, gzip: bool) -> Sniffed {
        sniff_bytes(bytes, Path::new(name), Path::new(name), gzip).unwrap()
    }

    fn family(text: &str, name: &str) -> Family {
        sniffed(text.as_bytes(), name, false).family
    }

    const SEP: &str = "From 1787654321098765432@xxx Tue Nov 14 22:13:20 +0000 2023";
    const HEADERS: &str = "From: Dana Klein <dana@example.org>\nTo: alex@example.org\n\
                           Subject: Term sheet\nDate: Tue, 14 Nov 2023 22:13:20 +0000\n\
                           Message-ID: <a@example.org>\n\nbody text\n";

    /// A mailbox is recognised by what is IN it. Thunderbird folders have no
    /// extension, Apple Mail's file is literally `mbox`, and Takeout's has
    /// spaces in its name — none of which may matter.
    #[test]
    fn a_mailbox_is_detected_by_content_under_any_name() {
        let lf = format!("{SEP}\n{HEADERS}");
        let crlf = lf.replace('\n', "\r\n");
        for name in [
            "Inbox",
            "mbox",
            "All mail Including Spam and Trash.mbox",
            "export.txt",
            "x.eml",
        ] {
            assert_eq!(family(&lf, name), Family::Mbox, "LF {name}");
            assert_eq!(family(&crlf, name), Family::Mbox, "CRLF {name}");
        }
        // Blank lines before the first separator are tolerated.
        assert_eq!(family(&format!("\n\n{lf}"), "Inbox"), Family::Mbox);
        // So is a UTF-8 byte-order mark (review finding on PR #949: such a
        // file was junked as a "yaml candidate" and none of its mail indexed).
        assert_eq!(family(&format!("\u{feff}{lf}"), "bom.mbox"), Family::Mbox);
        assert_eq!(family(&format!("\u{feff}{crlf}"), "bom.mbox"), Family::Mbox);
        // Thunderbird and mutt separators.
        for sep in [
            "From - Tue Oct 10 12:34:56 2023",
            "From MAILER-DAEMON Fri Jul  8 12:08:34 2011",
        ] {
            assert_eq!(
                family(&format!("{sep}\n{HEADERS}"), "Sent"),
                Family::Mbox,
                "{sep}"
            );
        }
    }

    /// …and the extension alone proves nothing.
    #[test]
    fn the_mbox_extension_is_not_evidence() {
        let prose = "Notes about the mbox format.\n\nIt is older than MIME and it shows.\n";
        assert_ne!(family(prose, "notes.mbox"), Family::Mbox);
        // Prose that opens with the word "From" and even looks a bit like mail.
        let essay = format!("From what I understand, the deal closes Monday.\n{HEADERS}");
        assert_ne!(family(&essay, "essay.mbox"), Family::Mbox);
        // A real separator followed by something that is not a message.
        let log = format!("{SEP}\nname: app\nversion: 2\nport: 8080\n");
        assert_ne!(family(&log, "weird.mbox"), Family::Mbox);
        // A QUOTED separator is body text of some other file, not a mailbox.
        assert_ne!(
            family(&format!(">{SEP}\n{HEADERS}"), "reply.mbox"),
            Family::Mbox
        );
        // A single message with no separator stays an email.
        assert_eq!(family(HEADERS, "one.mbox"), Family::Eml);
    }

    /// The sniffer only ever sees a PREFIX of the file, cut at a byte count, so
    /// the cut lands inside multi-byte characters as a matter of course. Every
    /// prefix length of a mailbox full of them: no panic (panic = abort), and
    /// once the headers are in view the answer is stable.
    #[test]
    fn a_prefix_cut_inside_a_multibyte_character_never_panics() {
        let mbox = format!(
            "{SEP}\nFrom: 山田 太郎 <yamada@example.org>\nTo: محمد علي <ali@example.org>\n\
             Subject: 設計書 — Überweisung\nDate: Tue, 14 Nov 2023 22:13:20 +0000\n\
             Message-ID: <a@example.org>\n\nمرحبا بالعالم 設計書 Grüße\n"
        );
        let bytes = mbox.as_bytes();
        let headers_end = mbox.find("\n\n").unwrap();
        for cut in 0..=bytes.len() {
            let got = sniffed(&bytes[..cut], "Inbox", false).family;
            if cut > headers_end {
                assert_eq!(got, Family::Mbox, "cut={cut}");
            }
        }
    }

    fn tar_header(name: &str) -> Vec<u8> {
        let mut h = vec![0u8; 512];
        h[..name.len()].copy_from_slice(name.as_bytes());
        h[100..107].copy_from_slice(b"0000644");
        h[257..263].copy_from_slice(b"ustar\0");
        h[263..265].copy_from_slice(b"00");
        h[148..156].copy_from_slice(b"        ");
        let sum: u32 = h.iter().map(|b| u32::from(*b)).sum();
        h[148..156].copy_from_slice(format!("{sum:06o}\0 ").as_bytes());
        h
    }

    /// Archives are NAMED so the run can say what to do about them. A Takeout
    /// download is one `.zip` or `.tgz`; "binary content (unknown)" tells its
    /// owner nothing.
    #[test]
    fn archives_are_named_and_told_apart_from_text_that_mentions_them() {
        let tar = sniffed(
            &tar_header("Takeout/Mail/All mail.mbox"),
            "takeout-001.tar",
            false,
        );
        assert_eq!(tar.family, Family::Binary);
        assert_eq!(tar.binary_kind.as_deref(), Some("tar"));
        // The same 512 bytes reached through gzip (a .tgz): still a tar.
        let tgz = sniffed(&tar_header("Takeout/x"), "takeout-001.tgz", true);
        assert_eq!(tgz.binary_kind.as_deref(), Some("tar"));
        // `ustar` at offset 257 of a TEXT file, with no valid checksum: not a tar.
        let mut text = vec![b'a'; 512];
        text[257..262].copy_from_slice(b"ustar");
        assert_ne!(
            sniffed(&text, "essay.txt", false).binary_kind.as_deref(),
            Some("tar")
        );
        // Shorter than one header block: `get(..512)` is None, not a panic.
        assert_ne!(
            sniffed(&tar_header("x")[..300], "cut.tar", false)
                .binary_kind
                .as_deref(),
            Some("tar")
        );

        for (magic, kind) in [
            (&b"7z\xbc\xaf\x27\x1c\x00\x04rest"[..], "7z"),
            (&b"Rar!\x1a\x07\x01\x00rest"[..], "rar"),
            (&b"\xfd7zXZ\x00\x00\x04rest"[..], "xz"),
        ] {
            let s = sniffed(magic, "a.bin", false);
            assert_eq!(s.family, Family::Binary, "{kind}");
            assert_eq!(s.binary_kind.as_deref(), Some(kind));
        }
    }

    #[test]
    fn archive_advice_names_the_command_for_the_kind_in_hand() {
        let advice = |kind: &str, gz: bool| archive_advice(kind, gz).unwrap_or_default();
        for (kind, gz, command) in [
            ("zip", false, "unzip <file>"),
            ("tar", false, "tar -xf <file>"),
            ("tar", true, "tar -xzf <file>"),
            ("7z", false, "7z x <file>"),
            ("rar", false, "unrar x <file>"),
            ("xz", false, "xz -dk <file>"),
        ] {
            let text = advice(kind, gz);
            assert!(text.contains("extract it first"), "{kind}: {text}");
            assert!(text.contains(command), "{kind}: {text}");
            assert!(text.contains("does not open archives"), "{kind}: {text}");
        }
        // Not an archive: no advice, the ordinary "binary content (…)" stands.
        for kind in ["png", "pdf", "unknown", "", "設計"] {
            assert_eq!(archive_advice(kind, false), None, "{kind}");
        }
    }
}

#[cfg(test)]
mod zip_container_sniff_tests {
    use super::*;
    use std::io::Write;

    /// Write a zip with the named members to a temp dir and sniff it through
    /// the real read path. ODF and EPUB store `mimetype` uncompressed and first;
    /// fixtures do the same so the bounded read sees what a real file holds.
    fn sniff_zip(members: &[(&str, &str)]) -> Sniffed {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("blob");
        let mut z = zip::ZipWriter::new(std::fs::File::create(&path).unwrap());
        for (name, content) in members {
            let method = if *name == "mimetype" {
                zip::CompressionMethod::Stored
            } else {
                zip::CompressionMethod::Deflated
            };
            let opts = zip::write::SimpleFileOptions::default().compression_method(method);
            z.start_file(*name, opts).unwrap();
            z.write_all(content.as_bytes()).unwrap();
        }
        z.finish().unwrap();
        sniff(&path).unwrap()
    }

    fn kind(members: &[(&str, &str)]) -> (Family, Option<String>) {
        let sn = sniff_zip(members);
        (sn.family, sn.binary_kind)
    }

    fn binary(k: &str) -> (Family, Option<String>) {
        (Family::Binary, Some(k.into()))
    }

    /// An Office or OpenDocument file is a zip, but it is not an archive to
    /// unzip: before this, every container below except DOCX sniffed as
    /// `zip` and was junked with "extract it first (unzip <file>)".
    #[test]
    fn office_containers_are_named_by_their_main_part() {
        let ct = ("[Content_Types].xml", "<Types/>");
        assert_eq!(
            kind(&[ct, ("word/document.xml", "<w:document/>")]),
            (Family::Docx, None)
        );
        assert_eq!(
            kind(&[ct, ("xl/workbook.xml", "<workbook/>")]),
            (Family::Xlsx, None)
        );
        assert_eq!(kind(&[ct, ("xl/workbook.bin", "\u{1}")]), binary("xlsb"));
        assert_eq!(
            kind(&[ct, ("ppt/presentation.xml", "<p:presentation/>")]),
            (Family::Pptx, None)
        );
    }

    #[test]
    fn opendocument_and_epub_are_named_by_their_mimetype_member() {
        let odf = |mime: &'static str| {
            kind(&[
                ("mimetype", mime),
                ("content.xml", "<office:document-content/>"),
                ("META-INF/manifest.xml", "<manifest:manifest/>"),
            ])
        };
        assert_eq!(
            odf("application/vnd.oasis.opendocument.text"),
            binary("odt")
        );
        assert_eq!(
            odf("application/vnd.oasis.opendocument.spreadsheet"),
            binary("ods")
        );
        assert_eq!(
            odf("application/vnd.oasis.opendocument.presentation"),
            binary("odp")
        );
        assert_eq!(
            kind(&[
                ("mimetype", "application/epub+zip"),
                ("META-INF/container.xml", "<container/>"),
            ]),
            (Family::Epub, None)
        );
    }

    /// Everything else stays an archive, so the Takeout advice is unchanged:
    /// a zip of ordinary files, an unknown `mimetype`, and a `mimetype` member
    /// longer than the bounded read (which must not be mistaken for a match).
    #[test]
    fn other_zips_are_still_archives() {
        assert_eq!(
            kind(&[
                ("Takeout/Mail/All mail.mbox", "From x\n"),
                ("notes.txt", "hi")
            ]),
            binary("zip")
        );
        assert_eq!(
            kind(&[("mimetype", "application/vnd.oasis.opendocument.graphics")]),
            binary("zip")
        );
        let long = format!("application/epub+zip{}", " x".repeat(64));
        assert_eq!(kind(&[("mimetype", long.as_str())]), binary("zip"));
    }

    #[test]
    fn unsupported_documents_get_an_export_hint_not_archive_advice() {
        for k in ["xlsb", "odt", "ods", "odp"] {
            assert_eq!(archive_advice(k, false), None, "{k}");
            let advice = unsupported_document_advice(k).unwrap();
            assert!(
                advice.starts_with("unsupported document format (")
                    && advice.contains("to index it now"),
                "{k}: {advice}"
            );
            assert!(!advice.contains("unzip"), "{k}: {advice}");
        }
        assert!(unsupported_document_advice("xlsb")
            .unwrap()
            .contains("Excel binary workbook"));
        // The hint names the format autoindex extracts best for that kind of
        // document: a presentation saved as .pptx keeps one record per slide,
        // which a PDF export also gives but without the slide titles and notes.
        assert!(unsupported_document_advice("ods")
            .unwrap()
            .contains(".xlsx"));
        assert!(unsupported_document_advice("odp")
            .unwrap()
            .contains(".pptx"));
        for k in [
            "zip", "tar", "png", "docx", "pptx", "xlsx", "epub", "unknown", "",
        ] {
            assert_eq!(unsupported_document_advice(k), None, "{k}");
        }
    }
}

#[cfg(test)]
mod data_container_tests {
    use super::*;
    use std::io::Write;

    fn sniffed(bytes: &[u8], name: &str) -> Sniffed {
        let p = Path::new(name);
        sniff_bytes(bytes, p, p, false).unwrap()
    }

    /// Prefixes copied from real files: pyarrow 17 (Parquet snappy/zstd/none,
    /// Feather v2), a Chroma Parquet store, numpy.save, h5py, pickle.dumps.
    #[test]
    fn data_containers_are_named_from_real_file_prefixes() {
        for (bytes, kind) in [
            (&b"PAR1\x15\x04\x150\x15.rest"[..], "parquet"),
            (&b"PAR1\x15\x00\x15\x5crest"[..], "parquet"),
            (&b"ARROW1\x00\x00\xff\xffrest"[..], "arrow"),
            (&b"\x93NUMPY\x01\x00v\x00rest"[..], "npy"),
            (&b"\x89HDF\r\n\x1a\n\x00\x00rest"[..], "hdf5"),
            (&b"\x80\x02}q\x00X\x01\x00rest"[..], "pickle"),
            (&b"\x80\x05\x95\n\x00\x00\x00\x00rest"[..], "pickle"),
        ] {
            let s = sniffed(bytes, "data.bin");
            assert_eq!(s.family, Family::Binary, "{kind}");
            assert_eq!(s.binary_kind.as_deref(), Some(kind));
        }
        // A protocol-4 opcode without its FRAME, and protocol 0 (no header):
        // not claimed as pickles.
        for bytes in [&b"\x80\x04}rest of it"[..], &b"(dp0\nS'k'\nI1\ns."[..]] {
            assert_ne!(
                sniffed(bytes, "x.bin").binary_kind.as_deref(),
                Some("pickle")
            );
        }
    }

    #[test]
    fn a_zip_of_npy_members_is_an_npz() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("arrays.npz");
        {
            let mut w = zip::ZipWriter::new(std::fs::File::create(&path).unwrap());
            let opts = zip::write::SimpleFileOptions::default();
            for m in ["x.npy", "y.npy"] {
                w.start_file(m, opts).unwrap();
                w.write_all(b"\x93NUMPY\x01\x00").unwrap();
            }
            w.finish().unwrap();
        }
        assert_eq!(sniff(&path).unwrap().binary_kind.as_deref(), Some("npz"));
    }

    #[test]
    fn data_containers_get_an_export_hint() {
        for k in ["parquet", "arrow", "npy", "npz", "hdf5"] {
            let advice = unsupported_data_advice(k).unwrap();
            assert!(
                advice.starts_with("unsupported data format (")
                    && advice.contains("to index it now"),
                "{k}: {advice}"
            );
        }
        let pickle = unsupported_data_advice("pickle").unwrap();
        assert!(pickle.contains("never loads pickles"), "{pickle}");
        for k in ["zip", "png", "xlsx", "unknown", ""] {
            assert_eq!(unsupported_data_advice(k), None, "{k}");
        }
    }
}

#[cfg(test)]
mod ole2_sniff_tests {
    use super::*;
    use std::io::Write;
    use std::path::Path;

    /// Write a synthetic OLE2 compound file carrying exactly the named streams
    /// (each with a byte of content), and return its path inside `dir`. Built
    /// with cfb's own writer, so no real Office file is ever needed.
    fn write_ole2(dir: &tempfile::TempDir, file: &str, streams: &[&str]) -> std::path::PathBuf {
        let path = dir.path().join(file);
        {
            let mut comp = cfb::create(&path).unwrap();
            for name in streams {
                let mut s = comp.create_stream(name).unwrap();
                s.write_all(b"x").unwrap();
                s.flush().unwrap();
            }
            comp.flush().unwrap();
        }
        path
    }

    /// A `Workbook` stream inside an OLE2 container routes to `Xls`, by content
    /// and not by the file's extension.
    #[test]
    fn a_workbook_stream_is_detected_as_xls() {
        let dir = tempfile::tempdir().unwrap();
        let path = write_ole2(&dir, "legacy.bin", &["Workbook"]);
        assert_eq!(sniff(&path).unwrap().family, Family::Xls);
        // The pre-BIFF8 name `Book` also counts.
        let path = write_ole2(&dir, "old.bin", &["Book"]);
        assert_eq!(sniff(&path).unwrap().family, Family::Xls);
    }

    /// A `WordDocument` stream routes to `Doc`.
    #[test]
    fn a_worddocument_stream_is_detected_as_doc() {
        let dir = tempfile::tempdir().unwrap();
        let path = write_ole2(
            &dir,
            "report.bin",
            &["WordDocument", "\u{5}SummaryInformation"],
        );
        assert_eq!(sniff(&path).unwrap().family, Family::Doc);
    }

    /// Any other OLE2 container (PowerPoint, Visio, a 1C `.epf`, …) is named
    /// `ole2` and left for the skip report — never parsed, never a panic.
    #[test]
    fn an_unrecognised_ole2_container_is_named_but_not_parsed() {
        let dir = tempfile::tempdir().unwrap();
        let path = write_ole2(&dir, "deck.bin", &["PowerPoint Document"]);
        let sn = sniff(&path).unwrap();
        assert_eq!(sn.family, Family::Binary);
        assert_eq!(sn.binary_kind.as_deref(), Some("ole2"));
    }

    /// The OLE2 magic followed by garbage (a truncated/crafted compound file)
    /// must classify as binary `ole2` without panicking or hanging.
    #[test]
    fn a_truncated_ole2_header_is_binary_not_a_panic() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("broken.bin");
        let mut bytes = OLE2_MAGIC.to_vec();
        bytes.extend_from_slice(&[0xFF; 600]); // nonsense header fields
        std::fs::write(&path, &bytes).unwrap();
        let sn = sniff(&path).unwrap();
        assert_eq!(sn.family, Family::Binary);
        assert_eq!(sn.binary_kind.as_deref(), Some("ole2"));
    }

    /// A `.ssc`-style spreadsheet export is a TEXT XML body, not an OLE2
    /// container, and must stay `Xml` — pinned so the new OLE2 routing (and any
    /// future "spreadsheet" heuristic) never steals it.
    #[test]
    fn an_ssc_xml_spreadsheet_body_stays_xml() {
        let body = concat!(
            r#"<?xml version="1.0" encoding="UTF-8"?>"#,
            "\n",
            r#"<spreadsheet-workbook-data version="2" generator="xerj">"#,
            "\n  <sheet name=\"Totals\"><row><cell>Region</cell><cell>Revenue</cell></row></sheet>\n",
            r#"</spreadsheet-workbook-data>"#,
        );
        let fam = sniff_bytes(
            body.as_bytes(),
            Path::new("export.ssc"),
            Path::new("export.ssc"),
            false,
        )
        .unwrap()
        .family;
        assert_eq!(fam, Family::Xml);
    }
}

//! Where a run's documents come from: a local folder tree, or an object store.
//!
//! `xerj autoindex <folder>` had exactly one source — [`crate::walk`] over a
//! filesystem tree. Pointing it at `s3://bucket/prefix` needs the same two
//! answers from somewhere else: *what candidate documents are there* (with
//! enough metadata to tell an unchanged one from a changed one) and *how do I
//! read one*. That pair is [`DocSource`].
//!
//! What this module is NOT: a rewrite of the walk. The local run still calls
//! [`crate::walk::walk_reporting_opts`] directly and nothing about it changed —
//! [`LocalDirSource`] exists so the trait is implemented by both kinds of source
//! and so the object-store cache logic can be exercised against a filesystem
//! source in tests. The extract/sniff pipeline is not touched at all: an object
//! source hands it the same thing a folder does, a local file whose bytes are
//! the object's bytes (see [`crate::objsource`] for why the bytes are landed on
//! disk rather than piped, and what that costs).

use anyhow::{bail, Result};
use std::io::Read;
use std::path::{Path, PathBuf};

/// Which URL scheme named the store. Both speak the S3 API; the scheme only
/// changes the default region and the wording of the errors, because an
/// operator who typed `r2://` is not helped by advice about `AWS_REGION`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ObjectScheme {
    /// `s3://` — Amazon S3, or anything S3-compatible with `--endpoint-url`.
    S3,
    /// `r2://` — Cloudflare R2. Region is always `auto` there.
    R2,
}

impl ObjectScheme {
    pub fn as_str(self) -> &'static str {
        match self {
            ObjectScheme::S3 => "s3",
            ObjectScheme::R2 => "r2",
        }
    }
}

/// A parsed `s3://bucket/prefix` (or `r2://…`) target.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ObjectSpec {
    pub scheme: ObjectScheme,
    pub bucket: String,
    /// Normalised listing prefix: either empty (whole bucket) or ending in `/`.
    ///
    /// A trailing slash is ADDED when the operator did not type one, so
    /// `s3://bucket/docs` lists `docs/…` and not also `docs-old/…`. Plain S3
    /// prefix matching is a string prefix, which surprises everyone the first
    /// time; a folder is what people mean by `s3://bucket/docs`, and the
    /// effective prefix is printed on every run so the choice is visible rather
    /// than magic.
    pub prefix: String,
    /// `--endpoint-url`, or `AWS_ENDPOINT_URL_S3` / `AWS_ENDPOINT_URL` from the
    /// environment. `None` means the SDK's own endpoint for the region.
    pub endpoint: Option<String>,
}

impl ObjectSpec {
    /// The string this source is known by: the journal's root identity, the
    /// seed of the default state-dir hash, and what progress/errors print.
    ///
    /// It deliberately does NOT include the endpoint. The same bucket reached
    /// through a different endpoint (a VPC endpoint, an account-specific R2
    /// host, `localhost:9000` in a test) is the same corpus, and hashing the
    /// endpoint into the state key would silently start a second index —
    /// re-downloading every object — the first time somebody's URL changed.
    pub fn identity(&self) -> String {
        format!("{}://{}/{}", self.scheme.as_str(), self.bucket, self.prefix)
    }

    /// Directory name for this source's local mirror, and therefore (through
    /// `derive_brain_name`) the default second-brain name. Bucket plus prefix,
    /// so two prefixes of one bucket do not collide.
    pub fn slug(&self) -> String {
        let mut raw = self.bucket.clone();
        if !self.prefix.is_empty() {
            raw.push('-');
            raw.push_str(self.prefix.trim_end_matches('/'));
        }
        let slug: String = raw
            .chars()
            .map(|c| {
                if c.is_ascii_alphanumeric() {
                    c.to_ascii_lowercase()
                } else {
                    '-'
                }
            })
            .collect();
        let slug = slug.trim_matches('-').to_string();
        // Keep it short enough to be a legal directory name everywhere, and
        // never empty (an unnamed mirror directory would collide with itself).
        let slug: String = slug.chars().take(120).collect();
        if slug.is_empty() {
            "objects".into()
        } else {
            slug
        }
    }
}

/// What the positional argument turned out to be.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SourceSpec {
    LocalDir(PathBuf),
    Object(ObjectSpec),
}

/// True when `arg` names an object store rather than a folder.
///
/// Only `s3://` and `r2://` count, matched case-insensitively on the scheme
/// alone — a Windows path (`C:\data`) has no `//`, and a key is never
/// lowercased.
pub fn looks_like_object_url(arg: &str) -> bool {
    let lower = arg.to_ascii_lowercase();
    lower.starts_with("s3://") || lower.starts_with("r2://")
}

/// Parse the positional argument. Anything that is not an object URL is a
/// folder, exactly as before.
///
/// `endpoint_flag` is `--endpoint-url`; when absent, `AWS_ENDPOINT_URL_S3` then
/// `AWS_ENDPOINT_URL` are consulted, which is the precedence the AWS CLI uses.
pub fn parse_source(arg: &Path, endpoint_flag: Option<&str>) -> Result<SourceSpec> {
    let raw = arg.to_string_lossy();
    if !looks_like_object_url(&raw) {
        return Ok(SourceSpec::LocalDir(arg.to_path_buf()));
    }
    let scheme = if raw[..2].eq_ignore_ascii_case("s3") {
        ObjectScheme::S3
    } else {
        ObjectScheme::R2
    };
    let rest = &raw[5..];
    let (bucket, prefix) = match rest.split_once('/') {
        Some((bucket, prefix)) => (bucket, prefix),
        None => (rest, ""),
    };
    if bucket.is_empty() {
        bail!(
            "{raw} names no bucket. Write it as {}://<bucket>/<prefix> — for example \
             {}://my-bucket/docs",
            scheme.as_str(),
            scheme.as_str()
        );
    }
    // A bucket name is a hostname-ish label, and anything else in that position
    // is a paste accident with consequences: `s3://key:secret@bucket/p` would
    // otherwise be sent to a "bucket" called `key:secret@bucket`, putting a
    // credential in the request line and in every log that records it.
    if let Some(bad) = bucket
        .chars()
        .find(|c| !(c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_')))
    {
        bail!(
            "{raw} has an invalid bucket name {bucket:?} (character {bad:?}). A bucket name may \
             hold letters, digits, '.', '-' and '_' only. Credentials do not belong in the URL — \
             they come from the environment (AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY), and an \
             endpoint goes in --endpoint-url"
        );
    }
    let prefix = normalise_prefix(prefix);
    let endpoint = match endpoint_flag {
        Some(url) => Some(url.to_string()),
        None => std::env::var("AWS_ENDPOINT_URL_S3")
            .or_else(|_| std::env::var("AWS_ENDPOINT_URL"))
            .ok()
            .filter(|s| !s.trim().is_empty()),
    };
    Ok(SourceSpec::Object(ObjectSpec {
        scheme,
        bucket: bucket.to_string(),
        prefix,
        endpoint,
    }))
}

/// Strip a leading `/`, collapse an all-slash prefix to empty, and make sure a
/// non-empty prefix ends in exactly one `/` (see [`ObjectSpec::prefix`]).
fn normalise_prefix(prefix: &str) -> String {
    let trimmed = prefix.trim_start_matches('/');
    let trimmed = trimmed.trim_end_matches('/');
    if trimmed.is_empty() {
        String::new()
    } else {
        format!("{trimmed}/")
    }
}

/// Why a listed object is not a candidate document. These share the reporting
/// surface with [`crate::ignore_rules`]' labels, so "where did my file go" has
/// one answer shape for both kinds of source.
///
/// A key that is skipped is never downloaded, so a skip is also money not spent.
pub mod rules {
    /// The key names the prefix itself, or ends in `/`: a folder marker, not a
    /// document. Every S3 console creates these.
    pub const FOLDER_MARKER: &str = "object:folder-marker";
    /// The key cannot be represented as a relative path safely or portably.
    /// See [`super::classify_key`] for the exact list.
    pub const UNSAFE_KEY: &str = "object:unsafe-key";
    /// Two keys differ only in case, so they would be one file on a
    /// case-insensitive filesystem (macOS, Windows) and each run would
    /// overwrite the other.
    pub const CASE_COLLISION: &str = "object:case-collision";
}

/// The verdict on one listed key, already stripped of the listing prefix.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum KeyVerdict {
    /// Admitted as a candidate document with this root-relative path.
    Admit,
    /// Not a candidate, for the named rule.
    Skip(&'static str),
}

/// Longest single path component we will create. 255 bytes is the limit on
/// ext4, APFS and NTFS alike; a longer component would fail at `create_dir`
/// halfway through a run instead of being reported up front.
const MAX_COMPONENT_BYTES: usize = 255;

/// Basenames Windows cannot create, whatever the extension.
const WINDOWS_RESERVED: &[&str] = &[
    "con", "prn", "aux", "nul", "com1", "com2", "com3", "com4", "com5", "com6", "com7", "com8",
    "com9", "lpt1", "lpt2", "lpt3", "lpt4", "lpt5", "lpt6", "lpt7", "lpt8", "lpt9",
];

/// Decide whether a prefix-stripped key can become a document.
///
/// An object key is an arbitrary UTF-8 string, not a path: `../../etc/passwd`,
/// `a//b`, `a\b`, a trailing dot and a 4 KB component are all legal keys. They
/// become a local path here, so each one is a decision rather than an accident:
///
/// - **`..`, `.`, an empty component, a leading `/`** — refused. A key that
///   escapes the mirror directory is the classic object-store traversal, and
///   `a//b` is a different key from `a/b` while being the same path.
/// - **A backslash** — refused. It is an ordinary character in a key and a
///   directory separator on Windows, so admitting it would index a different
///   set of documents per platform.
/// - **Control characters** — refused. They forge lines in the progress stream
///   (the #278 class) and are unrepresentable in half the tooling downstream.
/// - **A trailing `.` or space, or a Windows reserved basename** — refused
///   EVERYWHERE, not only on Windows, so one bucket produces one corpus
///   whatever machine indexes it. The report names the rule, so a refused key
///   is visible rather than silently missing.
/// - **A hidden (dot-prefixed) component** — skipped under
///   [`crate::ignore_rules::HIDDEN_RULE`], the same rule the walker applies at
///   depth > 0, and for the same reason: `.env`, `.git/config` and `.ssh/id_rsa`
///   live in buckets too, and "index this bucket" is not consent to publish
///   them into a queryable index. The two ignore FILES are the exception —
///   `.gitignore` and `.xerjignore` are fetched so the bucket's own ignore
///   rules still apply to it, and the walker then declines to index them
///   because of this same rule.
pub fn classify_key(rel: &str) -> KeyVerdict {
    if rel.is_empty() || rel.ends_with('/') {
        return KeyVerdict::Skip(rules::FOLDER_MARKER);
    }
    if rel.starts_with('/') || rel.contains('\\') {
        return KeyVerdict::Skip(rules::UNSAFE_KEY);
    }
    if rel.chars().any(|c| c.is_control()) {
        return KeyVerdict::Skip(rules::UNSAFE_KEY);
    }
    let components: Vec<&str> = rel.split('/').collect();
    let last = components.len() - 1;
    for (index, component) in components.iter().enumerate() {
        if component.is_empty() || *component == "." || *component == ".." {
            return KeyVerdict::Skip(rules::UNSAFE_KEY);
        }
        if component.len() > MAX_COMPONENT_BYTES {
            return KeyVerdict::Skip(rules::UNSAFE_KEY);
        }
        if component.ends_with('.') || component.ends_with(' ') || component.starts_with(' ') {
            return KeyVerdict::Skip(rules::UNSAFE_KEY);
        }
        let stem = component.split('.').next().unwrap_or(component);
        if WINDOWS_RESERVED
            .iter()
            .any(|reserved| stem.eq_ignore_ascii_case(reserved))
        {
            return KeyVerdict::Skip(rules::UNSAFE_KEY);
        }
        if component.starts_with('.') {
            let is_ignore_file = index == last
                && (*component == crate::ignore_rules::GITIGNORE
                    || *component == crate::ignore_rules::XERJIGNORE);
            if !is_ignore_file {
                return KeyVerdict::Skip(crate::ignore_rules::HIDDEN_RULE);
            }
        }
    }
    // The built-in build-output defaults, applied here as well as in the walk.
    // Same list, so the two can never drift; applying it early means a bucket
    // full of `node_modules/` costs no GET requests instead of costing them and
    // then being thrown away by the walker.
    if crate::ignore_rules::DEFAULT_IGNORE_PATTERNS
        .iter()
        .any(|pattern| {
            let dir = pattern.trim_end_matches('/');
            components[..last].contains(&dir)
        })
    {
        // Reported under the same label shape the walk uses for a pruned
        // directory, so `--dry-run` output reads the same for both sources.
        return KeyVerdict::Skip("default:build-output");
    }
    KeyVerdict::Admit
}

/// One candidate document as a source reports it, before any bytes are read.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceEntry {
    /// Root-relative path with forward slashes — the `ax_path` value, and the
    /// path inside the local mirror for an object source.
    pub rel: String,
    pub size: u64,
    /// An opaque token that changes when the bytes change, if the source can
    /// answer cheaply. `None` means it cannot, and the bytes decide.
    ///
    /// For an object store this is built from the ETag and the size; see
    /// [`crate::objsource::change_token`] for what is and is not assumed about
    /// an ETag. A local folder returns `None`: the walk's own answer is a full
    /// content hash, because file metadata cannot prove byte identity across
    /// every filesystem XERJ runs on.
    pub change_token: Option<String>,
    /// RFC 3339 last-modified, when the source reports one. Recorded for the
    /// operator; never used as change identity on its own unless there is no
    /// ETag at all.
    pub last_modified: Option<String>,
}

/// Requests a source has made, so a run can print what it cost.
///
/// Object stores bill per request, and the two classes are priced very
/// differently (Cloudflare R2: 1M "Class A" list/write operations a month free,
/// 10M "Class B" reads). Keeping them apart is the difference between a number
/// an operator can act on and a number they cannot.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SourceOps {
    /// LIST pages (R2/S3 "Class A" — the scarce one).
    ///
    /// **Wire attempts, not logical calls.** A page the store throttles twice
    /// before answering is three billed requests and counts as three, because
    /// this number exists to predict an invoice.
    pub list_requests: u64,
    /// GET/HEAD requests ("Class B"), counted the same way.
    pub read_requests: u64,
    /// How many of the above were retries of an earlier attempt. Informational:
    /// they are already included in the two counts.
    pub retried_requests: u64,
    pub bytes_read: u64,
}

/// What [`DocSource::list`] returned, plus why anything was left out.
#[derive(Debug, Clone, Default)]
pub struct SourceListing {
    pub entries: Vec<SourceEntry>,
    /// Rule label → how many keys it skipped. Rule labels come from
    /// [`rules`] and [`crate::ignore_rules`].
    pub skipped: std::collections::BTreeMap<String, u64>,
    /// Keys seen before filtering. `objects_listed` in the run's cost report.
    pub seen: u64,
}

/// A place documents come from: enumerate, then read one.
///
/// Implementors must be safe to call `open` on from several threads, which is
/// why it takes `&self`, returns an owned reader, and why the trait is
/// `Send + Sync`: the transfer phase fetches several objects at once.
pub trait DocSource: Send + Sync {
    /// What to print in progress and errors, e.g. `s3://bucket/docs/`.
    fn describe(&self) -> String;

    /// Enumerate candidate documents. Cheap metadata only — no bytes.
    fn list(&self) -> Result<SourceListing>;

    /// A sequential reader over one entry's bytes.
    ///
    /// The contract is streaming: the implementation must not hold the whole
    /// object in memory, because "point XERJ at my bucket" includes buckets
    /// with multi-gigabyte objects in them.
    fn open(&self, entry: &SourceEntry) -> Result<Box<dyn Read + Send>>;

    /// Requests made so far.
    fn ops(&self) -> SourceOps;
}

/// A filesystem folder as a [`DocSource`].
///
/// The production local path does not go through this — it calls
/// [`crate::walk`] and then hashes, exactly as it always has. This impl exists
/// so the trait has two implementations rather than one shaped like S3, and so
/// the mirroring logic in [`crate::objsource`] can be tested against a source
/// with no network at all.
pub struct LocalDirSource {
    root: PathBuf,
    follow_symlinks: bool,
    ignore: crate::ignore_rules::IgnoreOptions,
}

impl LocalDirSource {
    pub fn new(
        root: &Path,
        follow_symlinks: bool,
        ignore: crate::ignore_rules::IgnoreOptions,
    ) -> Self {
        Self {
            root: root.to_path_buf(),
            follow_symlinks,
            ignore,
        }
    }
}

impl DocSource for LocalDirSource {
    fn describe(&self) -> String {
        self.root.display().to_string()
    }

    fn list(&self) -> Result<SourceListing> {
        let (files, report) =
            crate::walk::walk_reporting(&self.root, self.follow_symlinks, self.ignore)?;
        let seen = files.len() as u64 + report.files_skipped;
        let mut skipped = std::collections::BTreeMap::new();
        if report.files_skipped > 0 {
            skipped.insert("walk:ignored".to_string(), report.files_skipped);
        }
        Ok(SourceListing {
            entries: files
                .into_iter()
                .map(|f| SourceEntry {
                    rel: f.rel,
                    size: f.size,
                    change_token: None,
                    last_modified: None,
                })
                .collect(),
            skipped,
            seen,
        })
    }

    fn open(&self, entry: &SourceEntry) -> Result<Box<dyn Read + Send>> {
        // `rel` came from this source's own walk, but it is still joined
        // defensively: a caller that round-trips entries through JSON could
        // hand back `../`, and a source must not read outside its root.
        match classify_key(&entry.rel) {
            KeyVerdict::Admit => {}
            KeyVerdict::Skip(rule) => {
                bail!("{} is not a readable relative path ({rule})", entry.rel)
            }
        }
        let path = self.root.join(&entry.rel);
        Ok(Box::new(std::fs::File::open(&path)?))
    }

    fn ops(&self) -> SourceOps {
        SourceOps::default()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn object(arg: &str) -> ObjectSpec {
        match parse_source(Path::new(arg), None).unwrap() {
            SourceSpec::Object(spec) => spec,
            SourceSpec::LocalDir(p) => panic!("{arg} parsed as a folder: {}", p.display()),
        }
    }

    #[test]
    fn plain_paths_stay_folders() {
        for arg in [
            "/home/me/docs",
            "./docs",
            "docs",
            "C:\\data",
            "s3-bucket",
            "my-s3://thing",
        ] {
            assert!(
                matches!(
                    parse_source(Path::new(arg), None).unwrap(),
                    SourceSpec::LocalDir(_)
                ),
                "{arg} should be a folder"
            );
        }
    }

    #[test]
    fn parses_bucket_and_prefix() {
        let spec = object("s3://my-bucket/docs/2026");
        assert_eq!(spec.scheme, ObjectScheme::S3);
        assert_eq!(spec.bucket, "my-bucket");
        assert_eq!(spec.prefix, "docs/2026/");
        assert_eq!(spec.identity(), "s3://my-bucket/docs/2026/");
    }

    #[test]
    fn whole_bucket_has_an_empty_prefix() {
        for arg in ["s3://my-bucket", "s3://my-bucket/", "s3://my-bucket///"] {
            let spec = object(arg);
            assert_eq!(spec.prefix, "", "{arg}");
            assert_eq!(spec.identity(), "s3://my-bucket/");
        }
    }

    #[test]
    fn r2_scheme_and_case_insensitive_scheme() {
        let spec = object("R2://Bucket-Name/Docs");
        assert_eq!(spec.scheme, ObjectScheme::R2);
        // The bucket and prefix keep their case; only the scheme is folded.
        assert_eq!(spec.bucket, "Bucket-Name");
        assert_eq!(spec.prefix, "Docs/");
    }

    #[test]
    fn credentials_in_the_url_are_refused_by_name() {
        let err = parse_source(Path::new("s3://key:secret@bucket/p"), None)
            .unwrap_err()
            .to_string();
        assert!(err.contains("invalid bucket name"), "{err}");
        assert!(
            err.contains("Credentials do not belong in the URL"),
            "{err}"
        );
    }

    #[test]
    fn empty_bucket_is_refused_with_the_shape_to_type() {
        let err = parse_source(Path::new("s3://"), None)
            .unwrap_err()
            .to_string();
        assert!(err.contains("names no bucket"), "{err}");
        assert!(err.contains("s3://<bucket>/<prefix>"), "{err}");
    }

    #[test]
    fn endpoint_flag_wins_over_environment() {
        let spec = parse_source(Path::new("s3://b/p"), Some("http://127.0.0.1:9000")).unwrap();
        match spec {
            SourceSpec::Object(spec) => {
                assert_eq!(spec.endpoint.as_deref(), Some("http://127.0.0.1:9000"))
            }
            _ => panic!("expected an object source"),
        }
    }

    #[test]
    fn slug_is_a_stable_directory_name() {
        assert_eq!(
            object("s3://my-bucket/docs/2026").slug(),
            "my-bucket-docs-2026"
        );
        assert_eq!(object("s3://my-bucket").slug(), "my-bucket");
        // Two prefixes of one bucket never share a mirror directory.
        assert_ne!(object("s3://b/a").slug(), object("s3://b/c").slug());
    }

    #[test]
    fn folder_markers_are_not_documents() {
        assert_eq!(classify_key(""), KeyVerdict::Skip(rules::FOLDER_MARKER));
        assert_eq!(
            classify_key("docs/"),
            KeyVerdict::Skip(rules::FOLDER_MARKER)
        );
    }

    #[test]
    fn traversal_and_unportable_keys_are_refused() {
        for key in [
            "../etc/passwd",
            "a/../../b",
            "./a",
            "a//b",
            "/abs",
            "a\\b",
            "a\tb",
            "trailing.",
            "trailing ",
            " leading",
            "dir/CON",
            "dir/nul.txt",
        ] {
            assert_eq!(
                classify_key(key),
                KeyVerdict::Skip(rules::UNSAFE_KEY),
                "{key} should be refused"
            );
        }
        let long = format!("dir/{}", "x".repeat(256));
        assert_eq!(classify_key(&long), KeyVerdict::Skip(rules::UNSAFE_KEY));
    }

    #[test]
    fn dotfiles_are_skipped_but_ignore_files_are_fetched() {
        assert_eq!(
            classify_key(".env"),
            KeyVerdict::Skip(crate::ignore_rules::HIDDEN_RULE)
        );
        assert_eq!(
            classify_key(".git/config"),
            KeyVerdict::Skip(crate::ignore_rules::HIDDEN_RULE)
        );
        assert_eq!(
            classify_key("src/.ssh/id_rsa"),
            KeyVerdict::Skip(crate::ignore_rules::HIDDEN_RULE)
        );
        assert_eq!(classify_key(".gitignore"), KeyVerdict::Admit);
        assert_eq!(classify_key("sub/.xerjignore"), KeyVerdict::Admit);
        // …but not an ignore file inside a hidden directory.
        assert_eq!(
            classify_key(".git/.gitignore"),
            KeyVerdict::Skip(crate::ignore_rules::HIDDEN_RULE)
        );
    }

    #[test]
    fn build_output_directories_cost_no_requests() {
        assert_eq!(
            classify_key("app/node_modules/react/index.js"),
            KeyVerdict::Skip("default:build-output")
        );
        assert_eq!(
            classify_key("target/debug/thing"),
            KeyVerdict::Skip("default:build-output")
        );
        // A FILE named like a build directory is still a document.
        assert_eq!(classify_key("notes/target"), KeyVerdict::Admit);
    }

    #[test]
    fn ordinary_keys_are_admitted() {
        for key in ["a.md", "docs/alpha.md", "a b/c-d.txt", "ünïcode/文書.txt"] {
            assert_eq!(classify_key(key), KeyVerdict::Admit, "{key}");
        }
    }

    #[test]
    fn local_source_lists_and_opens_the_same_tree_the_walk_does() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(dir.path().join("sub")).unwrap();
        std::fs::write(dir.path().join("a.txt"), b"alpha").unwrap();
        std::fs::write(dir.path().join("sub/b.txt"), b"beta").unwrap();
        std::fs::write(dir.path().join(".env"), b"SECRET=1").unwrap();
        let source = LocalDirSource::new(
            dir.path(),
            false,
            crate::ignore_rules::IgnoreOptions::default(),
        );
        let listing = source.list().unwrap();
        let mut rels: Vec<&str> = listing.entries.iter().map(|e| e.rel.as_str()).collect();
        rels.sort_unstable();
        assert_eq!(rels, vec!["a.txt", "sub/b.txt"], "dotfiles stay out");
        let entry = listing
            .entries
            .iter()
            .find(|e| e.rel == "sub/b.txt")
            .unwrap();
        let mut body = String::new();
        source
            .open(entry)
            .unwrap()
            .read_to_string(&mut body)
            .unwrap();
        assert_eq!(body, "beta");
        // A local folder cannot answer "did this change" cheaply, and says so.
        assert!(entry.change_token.is_none());
    }

    #[test]
    fn local_source_refuses_to_read_outside_its_root() {
        let dir = tempfile::tempdir().unwrap();
        let source = LocalDirSource::new(
            dir.path(),
            false,
            crate::ignore_rules::IgnoreOptions::default(),
        );
        let err = match source.open(&SourceEntry {
            rel: "../../etc/passwd".into(),
            size: 0,
            change_token: None,
            last_modified: None,
        }) {
            Ok(_) => panic!("a source must not read outside its own root"),
            Err(e) => e.to_string(),
        };
        assert!(err.contains("not a readable relative path"), "{err}");
    }
}

//! Hint when a searched autoindex is older than the folder it came from.
//!
//! `xerj code` refuses a ledger older than 30 days
//! (`xerj_common::xccode::state::check_fresh`). This path does not: a search
//! still returns its passages, and says when a file under the recorded root
//! is newer than the last run or an indexed path is gone (#2345). An agent
//! that sees zero hits can then tell "not in the corpus" from "not in the
//! index yet".
//!
//! # Cost
//!
//! One catalog search (2s timeout, no retry) loads the newest run for the
//! prefix. The freshness stamp is `summary_generated_at` when that parses,
//! otherwise `started`. `started` is the beginning of a run, so a file saved
//! while a long generation was in flight can look newer than a stamp that
//! has no summary time; the hint names a reindex, which is safe.
//!
//! The walk then stats at most [`STAT_CAP`] entries and stops after
//! [`WALK_WALL`]. Children of a directory are stat'd, then admitted
//! subdirectories are entered newest-mtime first, so a new page is visited
//! before an old sibling tree spends the cap. Hidden names, symlinks,
//! `.gitignore` / `.xerjignore`, the built-in ignore defaults, and
//! marker-gated generated directories are skipped the same way `xerj
//! autoindex` skips them — a `target/` or `.git` rewrite is not a stale
//! corpus. A root that is not a directory on this machine (a remote node,
//! an object-store source) produces no hint.
//!
//! A directory mtime newer than the stamp, with no newer child, is a
//! removal. That case confirms against catalog `indexed` / `duplicate`
//! paths, and only those, so deleting `target/` does not warn. The
//! confirmation shares the same stat cap and wall clock. A check that hits
//! either cap without a proven change stays silent.

use std::fs;
use std::io::ErrorKind;
use std::path::{Component, Path, PathBuf};
use std::time::{Duration, Instant, SystemTime};

use crate::catalog::CORPUS_SCOPE_FIELD;
use crate::ignore_rules::{is_hidden_name, IgnoreOptions, IgnoreStack};
use crate::walk::marker_generated_dir;
use serde_json::{json, Value};

/// Metadata reads for one check: the root, each listed child, and catalog
/// paths confirmed for deletion.
pub const STAT_CAP: u64 = 4096;
/// A slow disk stops here instead of turning search into a tree walk.
pub const WALK_WALL: Duration = Duration::from_millis(100);
/// mtime must be newer than the index stamp by more than this. Covers
/// one-second filesystem resolution around the moment the run finished.
pub const MTIME_GRACE: Duration = Duration::from_secs(2);
/// Catalog read cap. The search has already talked to the node; a stuck
/// catalog must not hold the answer.
const CATALOG_TIMEOUT: Duration = Duration::from_secs(2);
const RUN_PAGE: usize = 20;
const FILE_PAGE: usize = 4096;
const MAX_DEPTH: usize = 64;
const HINT_CODE: &str = "index_stale";

/// What `xerj search` prints, and what MCP appends under `_xerj.hints`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StalenessHint {
    pub code: &'static str,
    pub reason: String,
    pub indexed_at: String,
    pub root: String,
    pub run_id: String,
    pub prefix: String,
    pub path: String,
    /// `newer` (added or changed) or `deleted`.
    pub change: &'static str,
}

impl StalenessHint {
    /// The line `xerj search` prints before its passages.
    pub fn cli_line(&self) -> String {
        format!("xerj search: {}", self.reason)
    }
}

/// One indexed path from the catalog, used only to confirm a deletion.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CatalogFile {
    pub path: String,
    pub status: Option<String>,
}

/// Caps for one walk. Tests shrink them; search uses [`WalkLimits::default`].
#[derive(Debug, Clone, Copy)]
pub struct WalkLimits {
    pub stat_cap: u64,
    pub wall: Duration,
    pub grace: Duration,
}

impl Default for WalkLimits {
    fn default() -> Self {
        Self {
            stat_cap: STAT_CAP,
            wall: WALK_WALL,
            grace: MTIME_GRACE,
        }
    }
}

/// The run this check compares the folder to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IndexStamp {
    pub prefix: String,
    pub run_id: String,
    pub root: String,
    pub indexed_at: SystemTime,
    pub indexed_at_raw: String,
}

/// Look up `prefix` in the catalog and, when the recorded root is a local
/// directory, compare it to the files there.
///
/// `None` on every failure: a catalog the node does not have, a transport
/// error, an unreadable folder. The caller prints the search either way.
pub fn check(url: &str, api_key: Option<&str>, prefix: &str) -> Option<StalenessHint> {
    let prefix = prefix.trim();
    let url = url.trim().trim_end_matches('/');
    if prefix.is_empty() || url.is_empty() {
        return None;
    }
    let client = CatalogClient::new(url, api_key)?;
    let runs = fetch_runs(&client, prefix)?;
    let stamp = latest_stamp(&runs, prefix)?;
    hint_for_stamp(&stamp, &WalkLimits::default(), || {
        fetch_files(&client, prefix).unwrap_or_default()
    })
}

/// Decide from an already-loaded stamp. `files` runs only when a directory
/// mtime says something was removed and the walk did not already find a
/// newer admitted file.
pub fn hint_for_stamp(
    stamp: &IndexStamp,
    limits: &WalkLimits,
    files: impl FnOnce() -> Vec<CatalogFile>,
) -> Option<StalenessHint> {
    let root = Path::new(stamp.root.trim());
    if !root.is_dir() {
        return None;
    }
    let root = root.canonicalize().ok()?;
    if !root.is_dir() {
        return None;
    }
    let walked = walk_tree(&root, stamp.indexed_at, limits);
    let (change, rel) = match walked.kind {
        WalkKind::Newer(rel) => ("newer", rel),
        WalkKind::Suspect => {
            if walked.stats >= limits.stat_cap || walked.started.elapsed() >= limits.wall {
                return None;
            }
            let rel = find_deleted(&root, &files(), limits, walked.stats, walked.started)?;
            ("deleted", rel)
        }
        WalkKind::Fresh => return None,
    };
    Some(compose(stamp, &root, &rel, change))
}

/// Append `hint` to `_xerj.hints`, leaving an existing hint list in place.
/// A response that is not a JSON object is left alone.
pub fn attach(resp: &mut Value, hint: &StalenessHint) {
    let Some(obj) = resp.as_object_mut() else {
        return;
    };
    let xerj = obj.entry("_xerj").or_insert_with(|| json!({}));
    let Some(xerj) = xerj.as_object_mut() else {
        return;
    };
    let hints = xerj.entry("hints").or_insert_with(|| json!([]));
    let Some(hints) = hints.as_array_mut() else {
        return;
    };
    if hints
        .iter()
        .any(|h| h.get("code").and_then(Value::as_str) == Some(hint.code))
    {
        return;
    }
    hints.push(json!({
        "code": hint.code,
        "reason": hint.reason,
        "indexed_at": hint.indexed_at,
        "root": hint.root,
        "run_id": hint.run_id,
        "prefix": hint.prefix,
        "path": hint.path,
        "change": hint.change,
    }));
}

/// Merge `hint` into a search JSON body. Non-JSON text is returned unchanged
/// so a truncated budget response is not rewritten into something else.
pub fn merge_response_json(text: &str, hint: &StalenessHint) -> String {
    let Ok(mut value) = serde_json::from_str::<Value>(text) else {
        return text.to_string();
    };
    attach(&mut value, hint);
    serde_json::to_string(&value).unwrap_or_else(|_| text.to_string())
}

/// Newest run for `prefix`, by the freshness stamp.
///
/// Run documents are filtered here as well as in the query: a `prefix`
/// inferred as `text` can make a `match_phrase` hit a neighbor, and `term`
/// on that field misses. `summary_generated_at` is the end of the run.
/// `started` is the fallback the generation catalog writes.
pub fn latest_stamp(runs: &[Value], prefix: &str) -> Option<IndexStamp> {
    let mut best: Option<IndexStamp> = None;
    for run in runs {
        if run.get("doc_kind").and_then(Value::as_str) != Some("run") {
            continue;
        }
        if !scope_matches(run, prefix) {
            continue;
        }
        let root = run.get("root").and_then(Value::as_str)?.trim();
        if root.is_empty() {
            continue;
        }
        let (raw, when) = freshness(run)?;
        let run_id = run
            .get("run_id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let stamp = IndexStamp {
            prefix: prefix.to_string(),
            run_id,
            root: root.to_string(),
            indexed_at: when,
            indexed_at_raw: raw,
        };
        let replace = match &best {
            None => true,
            Some(prev) => {
                stamp.indexed_at > prev.indexed_at
                    || (stamp.indexed_at == prev.indexed_at && stamp.run_id > prev.run_id)
            }
        };
        if replace {
            best = Some(stamp);
        }
    }
    best
}

fn freshness(run: &Value) -> Option<(String, SystemTime)> {
    if let Some(raw) = field_str(run, "summary_generated_at") {
        if let Some(when) = parse_time(raw) {
            return Some((raw.to_string(), when));
        }
    }
    let raw = field_str(run, "started")?;
    Some((raw.to_string(), parse_time(raw)?))
}

fn field_str<'a>(value: &'a Value, key: &str) -> Option<&'a str> {
    value
        .get(key)
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|s| !s.is_empty())
}

fn parse_time(raw: &str) -> Option<SystemTime> {
    let dt = chrono::DateTime::parse_from_rfc3339(raw).ok()?;
    let secs = dt.timestamp();
    if secs < 0 {
        return None;
    }
    Some(SystemTime::UNIX_EPOCH + Duration::new(secs as u64, dt.timestamp_subsec_nanos()))
}

fn scope_matches(doc: &Value, prefix: &str) -> bool {
    field_str(doc, "prefix") == Some(prefix) || field_str(doc, CORPUS_SCOPE_FIELD) == Some(prefix)
}

fn compose(stamp: &IndexStamp, root: &Path, rel: &str, change: &str) -> StalenessHint {
    let rel_shown = sanitize_display(rel);
    let root_shown = sanitize_display(&root.display().to_string());
    let run = if stamp.run_id.is_empty() {
        String::new()
    } else {
        format!(" (run {})", sanitize_display(&stamp.run_id))
    };
    let what = if change == "deleted" {
        format!(
            "`{rel_shown}` was indexed and is no longer in that folder, so these results can name a page that was removed"
        )
    } else {
        format!(
            "`{rel_shown}` is newer than that index, so a page on disk can be missing from these results"
        )
    };
    let reason = format!(
        "The index for prefix `{}` was last built at {}{run}. {what}. Reindex with: xerj autoindex {} --prefix {}",
        sanitize_display(&stamp.prefix),
        sanitize_display(&stamp.indexed_at_raw),
        shell_quote(&root_shown),
        shell_quote(&stamp.prefix),
    );
    StalenessHint {
        code: HINT_CODE,
        reason,
        indexed_at: stamp.indexed_at_raw.clone(),
        root: root_shown,
        run_id: stamp.run_id.clone(),
        prefix: stamp.prefix.clone(),
        path: rel_shown,
        change: if change == "deleted" {
            "deleted"
        } else {
            "newer"
        },
    }
}

fn sanitize_display(value: &str) -> String {
    value
        .chars()
        .take(240)
        .map(|ch| {
            if ch.is_control() || ch == '`' {
                '?'
            } else {
                ch
            }
        })
        .collect()
}

fn shell_quote(value: &str) -> String {
    if !value.is_empty()
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '/' | '.' | '_' | '-' | ':' | '\\'))
    {
        value.to_string()
    } else {
        format!("'{}'", value.replace('\'', "'\\''"))
    }
}

enum WalkKind {
    Newer(String),
    Suspect,
    Fresh,
}

struct Walked {
    kind: WalkKind,
    stats: u64,
    started: Instant,
}

fn walk_tree(root: &Path, indexed_at: SystemTime, limits: &WalkLimits) -> Walked {
    let started = Instant::now();
    let mut walker = Walker {
        root: root.to_path_buf(),
        indexed_at,
        limits: *limits,
        started,
        stats: 0,
        suspect: false,
        stack: IgnoreStack::new(root, IgnoreOptions::default()),
    };
    if started.elapsed() >= limits.wall || !walker.charge() {
        return Walked {
            kind: WalkKind::Fresh,
            stats: walker.stats,
            started,
        };
    }
    let mtime = fs::symlink_metadata(root)
        .and_then(|meta| meta.modified())
        .unwrap_or(SystemTime::UNIX_EPOCH);
    let kind = match walker.visit(root, 0, mtime) {
        WalkControl::Newer(rel) => WalkKind::Newer(rel),
        WalkControl::Stop if walker.suspect => WalkKind::Suspect,
        WalkControl::Stop => WalkKind::Fresh,
        WalkControl::Continue if walker.suspect => WalkKind::Suspect,
        WalkControl::Continue => WalkKind::Fresh,
    };
    Walked {
        kind,
        stats: walker.stats,
        started,
    }
}

enum WalkControl {
    Newer(String),
    Stop,
    Continue,
}

struct Walker {
    root: PathBuf,
    indexed_at: SystemTime,
    limits: WalkLimits,
    started: Instant,
    stats: u64,
    suspect: bool,
    stack: IgnoreStack,
}

impl Walker {
    fn charge(&mut self) -> bool {
        if self.stats >= self.limits.stat_cap || self.started.elapsed() >= self.limits.wall {
            return false;
        }
        self.stats += 1;
        true
    }

    fn newer(&self, mtime: SystemTime) -> bool {
        match mtime.duration_since(self.indexed_at) {
            Ok(age) => age > self.limits.grace,
            Err(_) => false,
        }
    }

    fn visit(&mut self, dir: &Path, depth: usize, dir_mtime: SystemTime) -> WalkControl {
        if depth >= MAX_DEPTH {
            return WalkControl::Continue;
        }
        self.stack.truncate_to(depth);
        self.stack.enter_dir(dir, depth);
        let entries = match fs::read_dir(dir) {
            Ok(entries) => entries,
            Err(_) => return WalkControl::Continue,
        };
        let mut complete = true;
        let mut child_newer = false;
        let mut subdirs: Vec<(SystemTime, PathBuf)> = Vec::new();
        for entry in entries {
            let Ok(entry) = entry else {
                complete = false;
                break;
            };
            if !self.charge() {
                complete = false;
                break;
            }
            let path = entry.path();
            let meta = match fs::symlink_metadata(&path) {
                Ok(meta) => meta,
                Err(_) => continue,
            };
            let mtime = meta.modified().unwrap_or(SystemTime::UNIX_EPOCH);
            if self.newer(mtime) {
                child_newer = true;
            }
            let name = match path.file_name() {
                Some(name) => name,
                None => continue,
            };
            if is_hidden_name(name) {
                continue;
            }
            let file_type = meta.file_type();
            if file_type.is_symlink() {
                continue;
            }
            if file_type.is_dir() {
                if self.stack.skip_dir(&path).is_some() || marker_generated_dir(&path).is_some() {
                    continue;
                }
                subdirs.push((mtime, path));
                continue;
            }
            if !file_type.is_file() || self.stack.skip_file(&path).is_some() {
                continue;
            }
            if self.newer(mtime) {
                return WalkControl::Newer(rel_of(&self.root, &path));
            }
        }
        if complete && self.newer(dir_mtime) && !child_newer {
            self.suspect = true;
        }
        if !complete {
            return WalkControl::Stop;
        }
        subdirs.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
        for (mtime, path) in subdirs {
            match self.visit(&path, depth + 1, mtime) {
                WalkControl::Continue => {}
                other => return other,
            }
        }
        WalkControl::Continue
    }
}

fn rel_of(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .to_string_lossy()
        .replace('\\', "/")
}

fn find_deleted(
    root: &Path,
    files: &[CatalogFile],
    limits: &WalkLimits,
    mut stats: u64,
    started: Instant,
) -> Option<String> {
    for file in files {
        if !counts_as_indexed(file.status.as_deref()) {
            continue;
        }
        let Some(rel) = safe_rel(&file.path) else {
            continue;
        };
        if stats >= limits.stat_cap || started.elapsed() >= limits.wall {
            return None;
        }
        stats += 1;
        let path = root.join(rel);
        match fs::symlink_metadata(&path) {
            Err(err) if err.kind() == ErrorKind::NotFound => return Some(rel.to_string()),
            _ => {}
        }
    }
    None
}

fn counts_as_indexed(status: Option<&str>) -> bool {
    match status {
        None | Some("indexed" | "duplicate") => true,
        Some(_) => false,
    }
}

/// A catalog path that stays inside the root. Absolute paths and `..` are
/// ignored so a catalog row cannot point the stat at another directory.
fn safe_rel(rel: &str) -> Option<&str> {
    if rel.is_empty() || rel.len() > 1024 || rel.starts_with('/') || rel.starts_with('\\') {
        return None;
    }
    let path = Path::new(rel);
    if path.is_absolute() {
        return None;
    }
    if path
        .components()
        .any(|component| !matches!(component, Component::Normal(_)))
    {
        return None;
    }
    Some(rel)
}

struct CatalogClient {
    http: reqwest::blocking::Client,
    base: String,
    api_key: Option<String>,
}

enum CatalogErr {
    BadRequest,
    Failed,
}

impl CatalogClient {
    fn new(url: &str, api_key: Option<&str>) -> Option<Self> {
        let http = reqwest::blocking::Client::builder()
            .timeout(CATALOG_TIMEOUT)
            .connect_timeout(Duration::from_secs(1))
            .danger_accept_invalid_certs(true)
            .build()
            .ok()?;
        let api_key = api_key
            .map(str::trim)
            .filter(|key| !key.is_empty())
            .map(str::to_string);
        Some(Self {
            http,
            base: url.to_string(),
            api_key,
        })
    }

    fn search(&self, body: &Value) -> Result<Value, CatalogErr> {
        let url = format!("{}/autoindex-catalog/_search", self.base);
        let mut req = self.http.post(url).json(body);
        if let Some(key) = &self.api_key {
            req = req.header("Authorization", format!("ApiKey {key}"));
        }
        let resp = req.send().map_err(|_| CatalogErr::Failed)?;
        let status = resp.status();
        if status.as_u16() == 400 {
            return Err(CatalogErr::BadRequest);
        }
        if !status.is_success() {
            return Err(CatalogErr::Failed);
        }
        resp.json().map_err(|_| CatalogErr::Failed)
    }
}

fn scope_clause(prefix: &str) -> Value {
    json!({
        "bool": {
            "should": [
                {"term": {"prefix": prefix}},
                {"match_phrase": {"prefix": prefix}},
                {"term": {CORPUS_SCOPE_FIELD: prefix}}
            ],
            "minimum_should_match": 1
        }
    })
}

fn fetch_runs(client: &CatalogClient, prefix: &str) -> Option<Vec<Value>> {
    let source = json!([
        "prefix",
        CORPUS_SCOPE_FIELD,
        "root",
        "started",
        "summary_generated_at",
        "run_id",
        "doc_kind"
    ]);
    let query = json!({"bool": {"must": [
        {"term": {"doc_kind": "run"}},
        scope_clause(prefix)
    ]}});
    let sorted = json!({
        "size": RUN_PAGE,
        "sort": [{"_id": "desc"}],
        "_source": source,
        "query": query,
    });
    match client.search(&sorted) {
        Ok(body) => Some(hit_sources(&body)),
        Err(CatalogErr::BadRequest) => {
            let unsorted = json!({
                "size": 200,
                "_source": source,
                "query": query,
            });
            client.search(&unsorted).ok().map(|body| hit_sources(&body))
        }
        Err(CatalogErr::Failed) => None,
    }
}

fn fetch_files(client: &CatalogClient, prefix: &str) -> Option<Vec<CatalogFile>> {
    let body = json!({
        "size": FILE_PAGE,
        "_source": ["path", "status", "prefix", CORPUS_SCOPE_FIELD, "doc_kind"],
        "query": {"bool": {"must": [
            {"term": {"doc_kind": "file"}},
            scope_clause(prefix)
        ]}}
    });
    let sources = hit_sources(&client.search(&body).ok()?);
    let mut files = Vec::new();
    for source in sources {
        if source.get("doc_kind").and_then(Value::as_str) != Some("file") {
            continue;
        }
        if !scope_matches(&source, prefix) {
            continue;
        }
        let Some(path) = field_str(&source, "path") else {
            continue;
        };
        files.push(CatalogFile {
            path: path.to_string(),
            status: field_str(&source, "status").map(str::to_string),
        });
    }
    Some(files)
}

fn hit_sources(body: &Value) -> Vec<Value> {
    body.pointer("/hits/hits")
        .and_then(Value::as_array)
        .map(|hits| {
            hits.iter()
                .filter_map(|hit| hit.get("_source").cloned())
                .collect()
        })
        .unwrap_or_default()
}

