    fn historical_issue_283_journal(sync_begin: &str) -> Vec<u8> {
        let run = serde_json::json!({
            "v": 1,
            "kind": "run",
            "root": "root",
            "url": "url",
            "prefix": "prefix",
            "bulk_timeout_secs": 300,
            "run_id": "run-issue-283-fixture",
