    let armed = SNAPSHOT_FAILPOINT.with(|failpoint| {
        if failpoint.get() == boundary {
            failpoint.set(0);
            true
        } else {
            false
        }
    });
    if armed {
        anyhow::bail!("injected snapshot failure at boundary {boundary}");
    }
    Ok(())
}

#[cfg(not(test))]
