        std::fs::write(hubdir.join("manifest.json"), r#"{"corpus":"x"}"#).unwrap();
        let err = resolve_pack_source(&hubdir.display().to_string()).unwrap_err();
        assert!(err.contains("not a harvested pack"), "{err}");
    }

