    fn request_has_api_key(req: &str, key: &str) -> bool {
        let want = format!("ApiKey {key}");
        req.lines().any(|line| {
            let Some((name, value)) = line.split_once(':') else {
                return false;
            };
            name.trim().eq_ignore_ascii_case("authorization") && value.trim() == want
        })
    }

