        &|| false,
    )?;
    assert_eq!(r.added, 1_100);
    assert_eq!(r.list_calls, 2);
    assert_eq!(r.projection.monthly_class_a, 8_640);
    cleanup(&src, &prefix);
    Ok(())
}

/// F8 on the wire: a watched prefix that grows past the budget stops the watch
/// at the next cycle, through `run_watch`, with a decision request.
#[test]
fn f8_growth_past_the_budget_stops_a_running_watch() -> Result<()> {
    let Some(env) = minio() else { return Ok(()) };
    let (src, prefix) = source(&env, "grow")?;
    src.put_object(&format!("{prefix}seed"), b"x")?;
    let dir = tempfile::tempdir()?;
    let mut j = journal_for(&env, dir.path(), &prefix, false);
    // 100 ms interval x 1 call = 25,920,000/month; the budget allows 1 page a
    // cycle and not 2.
    let mut o = opts(100);
    o.fetch = false;
    o.max_cycles = Some(20);
    o.max_monthly_class_a = 26_000_000;
    let keys: Vec<String> = (0..1_100).map(|i| format!("{prefix}g{i:06}")).collect();
    let grown = std::sync::atomic::AtomicBool::new(false);
    let mut cycles = 0u64;
    let res = objwatch::run_watch(
        &src,
        &mut j,
        &o,
        &mut Recorder::default(),
        &|| false,
        &mut |r| {
            cycles += 1;
            if r.cycle == 0 && !grown.swap(true, Ordering::SeqCst) {
                seed(&src, &keys, b"x").unwrap();
            }
        },
    );
    let err = res.expect_err("the breaker must stop the watch, not warn");
    let refused = err
        .downcast_ref::<objwatch::PollCostRefused>()
        .expect("a cost refusal");
    assert_eq!(refused.cycle, 1);
    assert_eq!(refused.projection.list_calls_per_cycle, 2);
    assert_eq!(cycles, 1, "no cycle ran after the trip");
    cleanup(&src, &prefix);
    Ok(())
}

/// One 503 on a later cycle's listing does not end a watch against a real
/// server (the reviewer's rv_transient.rs).
#[test]
fn a_transient_list_failure_is_survived_on_a_real_server() -> Result<()> {
    let Some(env) = minio() else { return Ok(()) };
    let (src, prefix) = source(&env, "flaky")?;
    for i in 0..3 {
        src.put_object(&format!("{prefix}f{i}.txt"), b"body")?;
    }
    struct Flaky<'a> {
        inner: &'a S3Source,
        calls: AtomicU64,
    }
    impl ObjectSource for Flaky<'_> {
        fn describe(&self) -> String {
            self.inner.describe()
        }
        fn list(&self, req: &objwatch::ListRequest) -> Result<objwatch::ListPage> {
            if self.calls.fetch_add(1, Ordering::SeqCst) == 1 {
                anyhow::bail!("ListObjectsV2 returned 503 Service Unavailable: SlowDown");
            }
            self.inner.list(req)
        }
        fn get(&self, key: &str, max: u64) -> Result<objwatch::FetchedObject> {
            self.inner.get(key, max)
        }
    }
    let flaky = Flaky {
        inner: &src,
        calls: AtomicU64::new(0),
    };
    let dir = tempfile::tempdir()?;
    let mut j = journal_for(&env, dir.path(), &prefix, false);
    let mut o = opts(200);
    o.max_cycles = Some(4);
    let out = objwatch::run_watch(
        &flaky,
        &mut j,
        &o,
        &mut Recorder::default(),
        &|| false,
        &mut |_| {},
    )?;
    assert_eq!(out.totals.failed_cycles, 1);
    assert_eq!(out.totals.cycles, 3);
    cleanup(&src, &prefix);
    Ok(())
}

/// F9: a 10,000-object first scan. The cause of the old quadratic cost was one
/// fsynced rewrite of the whole journal per object; the exact regression guard
/// is the SAVES count, not a time.
///
/// The times are printed and the wall-clock bound is deliberately loose,
/// because a shared runner is not a benchmark — and because the journal's
/// filesystem dominates the result when it is saved per object. The published
/// before/after pair was re-measured for the #968 remediation on both, on one
/// host and one MinIO container; see docs/WATCHING_OBJECT_STORAGE.md. Set
/// `XERJ_F9_STATE_BASE` to put the journal somewhere other than the default
/// temp directory (which is tmpfs on many Linux boxes, where fsync is nearly
/// free and a per-object save looks much cheaper than it is on a disk).
#[test]
fn f9_a_ten_thousand_object_first_scan_is_linear() -> Result<()> {
    let Some(env) = minio() else { return Ok(()) };
    let n: usize = std::env::var("XERJ_MINIO_BULK_N")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(10_000);
    let state_base = std::env::var("XERJ_F9_STATE_BASE").ok();
    let (src, prefix) = source(&env, "bulk")?;
    let keys: Vec<String> = (0..n).map(|i| format!("{prefix}b{i:06}.txt")).collect();
    let t = std::time::Instant::now();
    seed(&src, &keys, b"bulk object body")?;
    eprintln!("F9 seeded {n} objects in {:.2}s", t.elapsed().as_secs_f64());

    for fetch in [false, true] {
        let dir = match &state_base {
            Some(base) => tempfile::Builder::new().prefix("f9-").tempdir_in(base)?,
            None => tempfile::tempdir()?,
        };
        let mut j = journal_for(&env, dir.path(), &prefix, false);
        let mut o = opts(300_000);
        o.fetch = fetch;
        let r = objwatch::poll_once(
            &src,
            &mut j,
            &o,
            &mut Recorder::default(),
            0,
            &mut CostTotals::default(),
            &|| false,
        )?;
        eprintln!(
            "F9 first scan fetch={fetch} journal_in={}: {} objects, {} list calls, {} GETs, {} \
             journal saves, wall {:.2}s",
            dir.path().display(),
            r.added,
            r.list_calls,
            r.gets,
            j.saves(),
            r.wall.as_secs_f64()
        );
        assert_eq!(r.added as usize, n);
        assert!(
            j.saves() <= (n as u64) / 256 + 2 + r.wall.as_secs() / 2,
            "{} saves",
            j.saves()
        );
        assert!(
            r.wall.as_secs() < 120,
            "a {n}-object first scan took {:.2}s",
            r.wall.as_secs_f64()
        );
    }
    let t = std::time::Instant::now();
    cleanup(&src, &prefix);
    eprintln!("F9 cleanup {:.2}s", t.elapsed().as_secs_f64());
    Ok(())
}

/// The child half of `b1_a_watcher_killed_mid_scan_still_owes_what_it_spent`:
/// one `--page-size 1` first scan over a 2,000-object prefix, which is 2,000
/// `ListObjectsV2` calls the parent can kill in the middle of.
fn b1_child(state: &str, prefix: &str) -> Result<()> {
    let env = minio().expect("the child inherits the parent's MinIO environment");
    let src = S3Source::new(
        &env.endpoint,
        "us-east-1",
        env.creds.clone(),
        S3Location {
            bucket: env.bucket.clone(),
            prefix: prefix.to_string(),
        },
        std::time::Duration::from_secs(30),
    )?;
    let dir = std::path::Path::new(state);
    let mut j = journal_for(&env, dir, prefix, false);
    let mut o = opts(300_000);
    o.fetch = false;
    o.page_size = 1;
    let r = objwatch::poll_once(
        &src,
        &mut j,
        &o,
        &mut Recorder::default(),
        0,
        &mut CostTotals::default(),
        &|| false,
    )?;
    eprintln!("B1CHILD-COMPLETED list_calls={}", r.list_calls);
    Ok(())
}

fn b1_ledger_class_a(path: &std::path::Path) -> Option<u64> {
    let raw = std::fs::read_to_string(path).ok()?;
    serde_json::from_str::<serde_json::Value>(&raw)
        .ok()?
        .get("class_a")?
        .as_u64()
}

/// B1 of the #968 verification, with a real `kill -9`.
///
/// The blocker: `scan()` may issue up to the whole remaining monthly allowance
/// in one cycle, and the ledger was charged only after it returned. The
/// verifier killed a 2,001-call scan five times — the store served 49, 98, 146,
/// 194 and 241 list calls and `objwatch-spend.json` was never created — so a
/// supervisor restarting a crashing watcher got a fresh budget every attempt,
/// which is the opposite of what the docs and the published answers page
/// promise ("that file survives a restart, so a supervisor that restarts a
/// crashing watcher cannot give it a fresh budget every minute").
///
/// This test re-executes its own test binary as a child, kills it with SIGKILL
/// while the first scan is still listing, and then asserts the two things the
/// claim needs: the ledger on disk owes what was spent, and a restart against
/// that ledger is refused instead of being handed a fresh allowance.
///
/// Before the fix it fails on the `< total_calls` assertion (the only value the
/// ledger ever holds is the whole finished scan) or on "the child finished
/// before the ledger recorded anything".
#[test]
fn b1_a_watcher_killed_mid_scan_still_owes_what_it_spent() -> Result<()> {
    if let Ok(state) = std::env::var("XERJ_B1_CHILD_STATE") {
        let prefix = std::env::var("XERJ_B1_CHILD_PREFIX").expect("child prefix");
        return b1_child(&state, &prefix);
    }
    let Some(env) = minio() else { return Ok(()) };
    let n: u64 = 2_000;
    let (src, prefix) = source(&env, "b1kill")?;
    let keys: Vec<String> = (0..n).map(|i| format!("{prefix}k{i:05}.txt")).collect();
    seed(&src, &keys, b"x")?;
    // One key per page: the scan is at LEAST `n` calls long (MinIO served
    // 2,001 for 2,000 keys), which is the window the kill has to land in.
    let scan_floor_calls = n;

    let dir = tempfile::tempdir()?;
    let ledger = dir.path().join("objwatch-spend.json");
    let mut child = std::process::Command::new(std::env::current_exe()?)
        .arg("b1_a_watcher_killed_mid_scan_still_owes_what_it_spent")
        .arg("--exact")
        .arg("--nocapture")
        .env("XERJ_B1_CHILD_STATE", dir.path())
        .env("XERJ_B1_CHILD_PREFIX", &prefix)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()?;

    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(120);
    let at_kill = loop {
        if let Some(c) = b1_ledger_class_a(&ledger) {
            if c >= 32 {
                break c;
            }
        }
        if let Some(status) = child.try_wait()? {
            cleanup(&src, &prefix);
            anyhow::bail!(
                "the child finished ({status}) before the ledger ever showed a partial spend: \
                 the cost of a scan in flight is not on disk, so a crash loses it"
            );
        }
        if std::time::Instant::now() > deadline {
            let _ = child.kill();
            cleanup(&src, &prefix);
            anyhow::bail!("the spend ledger never appeared while the scan was running");
        }
        std::thread::sleep(std::time::Duration::from_millis(2));
    };
    child.kill()?; // SIGKILL
    let status = child.wait()?;
    let after = b1_ledger_class_a(&ledger).unwrap_or(0);
    eprintln!(
        "B1 killed at class_a={at_kill}, ledger after SIGKILL={after} of >={scan_floor_calls} \
         calls, child {status}"
    );

    assert!(
        status.code().is_none(),
        "the child was supposed to die by signal, not exit ({status})"
    );
    assert!(
        after >= 32,
        "the ledger held {after} after a kill mid-scan: the spend was lost"
    );
    assert!(
        after < scan_floor_calls,
        "the ledger only ever held the FINISHED scan ({after}, and the scan is at least \
         {scan_floor_calls} calls) — the spend of a scan IN FLIGHT never reached the disk, \
         which is the case B1 is about"
    );

    // And the claim itself: a restart does not get a fresh allowance. The
    // budget is set to exactly what the killed run already owes, so the next
    // cycle must refuse before issuing a call.
    let mut j = journal_for(&env, dir.path(), &prefix, false);
    let mut o = opts(300_000);
    o.fetch = false;
    o.page_size = 1;
    o.max_monthly_class_a = after;
    let err = objwatch::poll_once(
        &src,
        &mut j,
        &o,
        &mut Recorder::default(),
        0,
        &mut CostTotals::default(),
        &|| false,
    )
    .expect_err("a restart must not be handed a fresh budget");
    let refused = err
        .downcast_ref::<objwatch::PollCostRefused>()
        .expect("a cost refusal");
    assert_eq!(refused.spent.class_a, after);

    cleanup(&src, &prefix);
    Ok(())
}

//! One bounded run of the watcher against Cloudflare R2, through the CLI route.
//!
//! WHY THIS IS SEPARATE FROM `objwatch_minio.rs`, AND DELIBERATELY SMALL
//!
//! R2's free tier is 1,000,000 Class A operations a month for a whole account,
//! and `PutObject` is Class A just like `ListObjectsV2`. So every object this
//! file creates is spent from the same allowance the watcher is designed to
//! protect. It therefore does the minimum that R2 can tell us and MinIO cannot:
//! that SigV4 signs correctly against R2's endpoint, that R2's `ListObjectsV2`
//! XML and continuation tokens parse, and that R2's ETag and `LastModified`
//! drive the change decision the same way MinIO's do.
//!
//! Everything else — load, tight poll intervals, multipart, thousands of
//! objects — belongs in `objwatch_minio.rs`. Running those here would spend a
//! metered allowance for no extra information.
//!
//! HARD CAPS, enforced below and not merely documented:
//! at most [`MAX_OBJECTS`] objects, each under [`MAX_OBJECT_BYTES`], and the
//! test deletes everything it created before it returns (`DeleteObject` is
//! free). The ledger it prints is the number to quote.
//!
//! Skipped, with a printed reason, unless all of these are set:
//!
//! ```sh
//! XERJ_R2_ENDPOINT=https://ACCOUNT.r2.cloudflarestorage.com \
//! XERJ_R2_ACCESS_KEY=… XERJ_R2_SECRET_KEY=… \
//! XERJ_R2_BUCKET=my-test-bucket XERJ_R2_PREFIX=my-prefix/ \
//! XERJ_R2_SPEND_ACK=1 \
//!   cargo test -p xerj-autoindex --test objwatch_r2 -- --test-threads 1 --nocapture
//! ```
//!
//! `XERJ_R2_SPEND_ACK=1` is required because the other five can plausibly be
//! set by a CI environment; this one cannot be set by accident.

use anyhow::Result;
use std::sync::atomic::{AtomicU64, Ordering};
use xerj_autoindex::objwatch::journal::WatchJournal;
use xerj_autoindex::objwatch::s3::{Credentials, S3Location, S3Source};
use xerj_autoindex::objwatch::{
    self, ChangeEvent, ChangeSink, CostTotals, ObjectSource, WatchOptions,
};

/// Objects this file may create. 24 is two pages at `--page-size 10` plus a
/// remainder, which is what proves R2's continuation tokens without writing the
/// 1,001 objects a natural-page-size test would need.
const MAX_OBJECTS: usize = 24;
const MAX_OBJECT_BYTES: usize = 512;

struct R2 {
    endpoint: String,
    creds: Credentials,
    bucket: String,
    prefix: String,
}

fn r2() -> Option<R2> {
    let get = |k: &str| std::env::var(k).ok().filter(|v| !v.is_empty());
    match (
        get("XERJ_R2_ENDPOINT"),
        get("XERJ_R2_ACCESS_KEY"),
        get("XERJ_R2_SECRET_KEY"),
        get("XERJ_R2_BUCKET"),
        get("XERJ_R2_SPEND_ACK"),
    ) {
        (Some(endpoint), Some(key), Some(secret), Some(bucket), Some(ack)) if ack == "1" => {
            Some(R2 {
                endpoint,
                creds: Credentials {
                    access_key_id: key,
                    secret_access_key: secret,
                    session_token: get("XERJ_R2_SESSION_TOKEN"),
                },
                bucket,
                prefix: get("XERJ_R2_PREFIX").unwrap_or_else(|| "objwatch-r2-test/".into()),
            })
        }
        _ => {
            eprintln!(
                "SKIP: no R2 target acknowledged. This test spends Class A operations from a \
                 real monthly allowance, so it needs XERJ_R2_ENDPOINT, XERJ_R2_ACCESS_KEY, \
                 XERJ_R2_SECRET_KEY, XERJ_R2_BUCKET and XERJ_R2_SPEND_ACK=1. Load and \
                 tight-interval testing belongs in objwatch_minio.rs, never here."
            );
            None
        }
    }
}

/// Every billable call this test makes, so the run can be quoted honestly.
#[derive(Default)]
struct Ledger {
    puts: AtomicU64,
    deletes: AtomicU64,
    bytes_written: AtomicU64,
}

impl Ledger {
    fn report(&self, list_calls: u64, gets: u64, bytes_read: u64) {
        println!(
            "R2 LEDGER: Class A = {} PutObject + {} ListObjectsV2 = {}; \
             Class B = {} GetObject; free = {} DeleteObject; \
             bytes written {} read {}",
            self.puts.load(Ordering::SeqCst),
            list_calls,
            self.puts.load(Ordering::SeqCst) + list_calls,
            gets,
            self.deletes.load(Ordering::SeqCst),
            self.bytes_written.load(Ordering::SeqCst),
            bytes_read,
        );
    }
}

fn put(src: &S3Source, led: &Ledger, key: &str, body: &[u8]) -> Result<()> {
    assert!(
        body.len() <= MAX_OBJECT_BYTES,
        "this test must not write an object over {MAX_OBJECT_BYTES} bytes to a metered bucket"
    );
    assert!(
        led.puts.load(Ordering::SeqCst) < (MAX_OBJECTS * 2) as u64,
        "put cap reached; refusing to spend more Class A operations"
    );
    src.put_object(key, body)?;
    led.puts.fetch_add(1, Ordering::SeqCst);
    led.bytes_written
        .fetch_add(body.len() as u64, Ordering::SeqCst);
    Ok(())
}

#[derive(Default)]
struct Recorder {
    events: Vec<ChangeEvent>,
}

impl ChangeSink for Recorder {
    fn accept(&mut self, ev: &ChangeEvent) -> Result<()> {
        self.events.push(ev.clone());
        Ok(())
    }
}

fn kinds(events: &[ChangeEvent], kind: &str) -> Vec<String> {
    let mut v: Vec<String> = events
        .iter()
        .filter(|e| e.kind.as_str() == kind)
        .map(|e| e.key.clone())
        .collect();
    v.sort();
    v
}

/// The whole R2 run, in one test so the ledger is one number and the cleanup
/// cannot be skipped by a second test failing first.
#[test]
fn a_bounded_watch_against_r2_detects_added_changed_and_deleted_across_pages() -> Result<()> {
    let Some(env) = r2() else { return Ok(()) };
    let led = Ledger::default();
    let src = S3Source::new(
        &env.endpoint,
        // R2 wants "auto"; this also proves the region an S3-only client would
        // have guessed wrong.
        "auto",
        env.creds.clone(),
        S3Location {
            bucket: env.bucket.clone(),
            prefix: env.prefix.clone(),
        },
        std::time::Duration::from_secs(30),
    )?;

    // Always clean up, even on a panic: leaving objects behind in a metered
    // bucket is the one failure mode this file must not have.
    let cleanup = || {
        let mut removed = 0u64;
        let mut token: Option<String> = None;
        loop {
            let page = match src.list(&objwatch::ListRequest {
                prefix: &env.prefix,
                continuation_token: token.as_deref(),
                start_after: None,
                delimiter: None,
                max_keys: 1000,
            }) {
                Ok(p) => p,
                Err(e) => {
                    eprintln!("R2 cleanup listing failed: {e}");
                    break;
                }
            };
            for o in &page.objects {
                if src.delete_object(&o.key).is_ok() {
                    removed += 1;
                    led.deletes.fetch_add(1, Ordering::SeqCst);
                }
            }
            match page.next_token {
                Some(t) => token = Some(t),
                None => break,
            }
        }
        println!(
            "R2 CLEANUP: deleted {removed} object(s) under {}",
            env.prefix
        );
    };
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| -> Result<()> {
        run_scenario(&src, &env, &led)
    }));
    cleanup();
    match result {
        Ok(r) => r,
        Err(p) => std::panic::resume_unwind(p),
    }
}

fn run_scenario(src: &S3Source, env: &R2, led: &Ledger) -> Result<()> {
    // A prefix that is empty at the start, so the run is self-contained.
    for o in src
        .list(&objwatch::ListRequest {
            prefix: &env.prefix,
            continuation_token: None,
            start_after: None,
            delimiter: None,
            max_keys: 1000,
        })?
        .objects
    {
        src.delete_object(&o.key)?;
        led.deletes.fetch_add(1, Ordering::SeqCst);
    }

    for i in 0..MAX_OBJECTS {
        let body = format!("watchs3 r2 object {i:03}\n{}\n", "x".repeat(100 + i));
        put(
            src,
            led,
            &format!("{}k{i:03}.txt", env.prefix),
            body.as_bytes(),
        )?;
    }

    let dir = tempfile::tempdir()?;
    let mut j = WatchJournal::open(
        dir.path(),
        &env.endpoint,
        &env.bucket,
        &env.prefix,
        false,
        false,
    )?;
    let mut sink = Recorder::default();
    let mut totals = CostTotals::default();
    let mut opts = WatchOptions {
        // The production default. The projection for 24 objects at 300 s is
        // 8,640 Class A operations a month, well inside the default budget, so
        // the guard is exercised in its accepting direction rather than switched
        // off.
        poll_interval: std::time::Duration::from_secs(300),
        max_cycles: Some(1),
        max_object_bytes: 1 << 20,
        // 10 keys a page: three pages over 24 objects, which is R2's
        // continuation-token path without writing 1,001 objects for it.
        page_size: 10,
        ..WatchOptions::default()
    };

    let first = objwatch::poll_once(src, &mut j, &opts, &mut sink, 0, &mut totals, &|| false)?;
    println!("R2 cycle 0: {}", first.line());
    assert_eq!(first.added as usize, MAX_OBJECTS, "{}", first.line());
    assert_eq!(first.keys_listed as usize, MAX_OBJECTS);
    assert_eq!(first.list_calls, 3, "24 keys at 10 a page is 3 calls on R2");
    assert_eq!(first.gets as usize, MAX_OBJECTS);
    assert!(
        !first.projection.over_budget(),
        "{}",
        first.projection.line()
    );

    // A quiet poll: the load-bearing cost property, now against R2's own ETags.
    sink.events.clear();
    let quiet = objwatch::poll_once(src, &mut j, &opts, &mut sink, 1, &mut totals, &|| false)?;
    println!("R2 cycle 1 (quiet): {}", quiet.line());
    assert_eq!(
        quiet.gets,
        0,
        "a quiet poll must issue ZERO GETs: {}",
        quiet.line()
    );
    assert_eq!(quiet.list_calls, 3);
    assert_eq!(quiet.unchanged as usize, MAX_OBJECTS);
    assert!(sink.events.is_empty());

    // One changed, one new, one deleted.
    put(
        src,
        led,
        &format!("{}k005.txt", env.prefix),
        b"EDITED on R2, and longer than before\n",
    )?;
    put(
        src,
        led,
        &format!("{}new999.txt", env.prefix),
        b"brand new on R2\n",
    )?;
    src.delete_object(&format!("{}k017.txt", env.prefix))?;
    led.deletes.fetch_add(1, Ordering::SeqCst);

    let changed = objwatch::poll_once(src, &mut j, &opts, &mut sink, 2, &mut totals, &|| false)?;
    println!("R2 cycle 2 (changed): {}", changed.line());
    assert_eq!(changed.added, 1, "{}", changed.line());
    assert_eq!(changed.changed, 1, "{}", changed.line());
    assert_eq!(changed.deleted, 1, "{}", changed.line());
    assert_eq!(
        changed.gets, 2,
        "only the new and the changed object are read"
    );
    assert_eq!(
        kinds(&sink.events, "added"),
        vec![format!("{}new999.txt", env.prefix)]
    );
    assert_eq!(
        kinds(&sink.events, "changed"),
        vec![format!("{}k005.txt", env.prefix)]
    );
    assert_eq!(
        kinds(&sink.events, "deleted"),
        vec![format!("{}k017.txt", env.prefix)]
    );
    let edited = sink
        .events
        .iter()
        .find(|e| e.key.ends_with("k005.txt"))
        .unwrap();
    assert_eq!(edited.reason, "etag", "R2 changes the ETag on a rewrite");

    // And the poll after that is quiet again.
    sink.events.clear();
    let settled = objwatch::poll_once(src, &mut j, &opts, &mut sink, 3, &mut totals, &|| false)?;
    println!("R2 cycle 3 (settled): {}", settled.line());
    assert_eq!(settled.gets, 0, "{}", settled.line());
    assert_eq!(settled.added + settled.changed + settled.deleted, 0);

    // --append-only on R2: one list call, whatever the prefix holds. This is the
    // lever the docs recommend, so it is proved on the metered store too.
    let mut j2 = WatchJournal::open(
        dir.path(),
        &env.endpoint,
        &env.bucket,
        &env.prefix,
        true,
        true,
    )?;
    opts.append_only = true;
    let tail = objwatch::poll_once(src, &mut j2, &opts, &mut sink, 0, &mut totals, &|| false)?;
    println!("R2 cycle 4 (append-only, fresh journal): {}", tail.line());
    // A fresh append-only journal has no `start-after`, so this first pass is a
    // full scan; what it proves is that the SECOND pass is one call.
    sink.events.clear();
    let tail2 = objwatch::poll_once(src, &mut j2, &opts, &mut sink, 1, &mut totals, &|| false)?;
    println!("R2 cycle 5 (append-only, tail only): {}", tail2.line());
    assert_eq!(
        tail2.list_calls,
        1,
        "append-only asks only for keys above the highest one seen: {}",
        tail2.line()
    );
    assert_eq!(
        tail2.keys_listed,
        0,
        "nothing was appended: {}",
        tail2.line()
    );
    assert_eq!(tail2.deleted, 0, "append-only never reports a delete");
    assert_eq!(
        tail2.projection.list_calls_per_cycle,
        1,
        "and it is PRICED at one call, not at the journal size: {}",
        tail2.projection.line()
    );

    led.report(totals.list_calls, totals.gets, totals.bytes_fetched);
    println!(
        "R2 watcher totals: {} list calls (Class A), {} GETs (Class B), {} bytes read",
        totals.list_calls, totals.gets, totals.bytes_fetched
    );
    Ok(())
}

//! The rust-vulns pack's public numbers must be numbers a real build produced.
//!
//! Same discipline as `security_tooling_claims.rs` (issue #207's lesson): a
//! README that advertises record counts nobody measured is a worse failure
//! than admitting the gap. `tools/packs/rust-vulns/pack-stats.json` is the
//! committed record of a measured build (`provenance: "measured"`); these
//! tests fail when the README, the stats and the recipe disagree — so a
//! rebuild with different numbers forces the docs to move with them, and a
//! recipe edit without a rebuild fails the sha pin.

use std::path::{Path, PathBuf};

/// Walk up from this crate to the repository root. Panics rather than
/// skipping: a claims check that turns into a no-op when it cannot find its
/// inputs is the tautological pass this file exists to prevent.
fn repo_root() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    loop {
        if dir.join(".github/workflows/ci.yml").is_file() {
            return dir;
        }
        assert!(
            dir.pop(),
            "no .github/workflows/ci.yml above {} — this test must run from a \
             repository checkout, and must not pass by failing to look",
            env!("CARGO_MANIFEST_DIR"),
        );
    }
}

fn pack_dir_named(root: &Path, name: &str) -> PathBuf {
    root.join("tools/packs").join(name)
}

fn read(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

fn stats_named(root: &Path, name: &str) -> serde_json::Value {
    let dir = pack_dir_named(root, name);
    let text = read(&dir.join("pack-stats.json"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("pack-stats.json is not valid JSON: {e}"))
}

/// The README's table row for `label` must carry exactly the number in
/// pack-stats.json under `key`.
fn readme_row_pins_named(root: &Path, name: &str, label: &str, key: &str) {
    let readme = read(&pack_dir_named(root, name).join("README.md"));
    let want = stats_named(root, name)
        .get(key)
        .and_then(|v| v.as_u64())
        .unwrap_or_else(|| panic!("{name}/pack-stats.json has no numeric '{key}'"));
    // rows look like `| … label … | 1950 |` or `| … label … | 270 (707 …) |`,
    // so pin on maximal digit runs, not whole cells
    let needle = label.to_string();
    let row = readme
        .lines()
        .find(|l| l.contains(&needle))
        .unwrap_or_else(|| panic!("{name}/README has no row containing '{needle}'"));
    let numbers: Vec<String> = row
        .split(|c: char| !c.is_ascii_digit())
        .filter(|s| !s.is_empty())
        .map(str::to_string)
        .collect();
    assert!(
        numbers.contains(&want.to_string()),
        "{name}/README row '{needle}' does not carry {want} (pack-stats.{key}); rebuild \
         the pack and move the docs with the numbers",
    );
}

#[test]
fn pack_stats_are_measured_not_asserted() {
    let root = repo_root();
    let s = stats_named(&root, "rust-vulns");
    assert_eq!(
        s["provenance"], "measured",
        "pack-stats.json must record provenance 'measured' — 'estimated' numbers \
         are exactly what this file exists to keep out of the README"
    );
    for key in [
        "envelopes",
        "records",
        "merged_from_both_sources",
        "records_with_functions",
        "function_paths_distinct",
        "function_entries_total",
        "records_withdrawn",
        "packages",
    ] {
        assert!(
            s.get(key).and_then(|v| v.as_u64()).is_some_and(|v| v > 0),
            "rust-vulns/pack-stats.json lacks a positive numeric '{key}'"
        );
    }
    // internal consistency: the parts cannot exceed the whole
    let records = s["records"].as_u64().unwrap();
    let merged = s["merged_from_both_sources"].as_u64().unwrap();
    let with_fn = s["records_with_functions"].as_u64().unwrap();
    assert!(merged <= records, "more merged records than records");
    assert!(with_fn <= records, "more function records than records");

    let kev = stats_named(&root, "cisa-kev");
    assert_eq!(kev["provenance"], "measured");
    for key in [
        "envelopes",
        "records",
        "vendors",
        "products",
        "records_with_cwe",
        "cwe_ids_distinct",
        "records_ransomware_known",
        "records_bytes",
    ] {
        assert!(
            kev.get(key).and_then(|v| v.as_u64()).is_some_and(|v| v > 0),
            "cisa-kev/pack-stats.json lacks a positive numeric '{key}'"
        );
    }
    let kev_records = kev["records"].as_u64().unwrap();
    assert!(kev["records_with_cwe"].as_u64().unwrap() <= kev_records);
    assert!(kev["records_ransomware_known"].as_u64().unwrap() <= kev_records);
}

