//! Persistent Raft log storage.
//!
//! This is the M5 v4 milestone unblock: the Raft state machine (see
//! [`crate::raft`]) keeps its log in a `Vec<LogEntry>` in RAM which is lost on
//! restart.  That makes the whole cluster design unsafe — acked writes
//! vanish if a leader crashes before its followers receive the commit.
//!
//! `FileRaftLog` stores entries in an append-only file inside
//! `{data_dir}/raft/` with the same framing we already use for the index
//! WAL (see `xerj_storage::wal`):
//!
//! ```text
//!     u32  magic = 0x5A_52_4C_32  ("ZRL2")
//!     u64  entry length
//!     u64  term
//!     u64  index
//!     u8   payload kind
//!     u64  payload length
//!     bytes payload
//!     u32  crc32 of the preceding header + payload
//! ```
//!
//! The file is append-only while the node is running.  On restart we scan
//! the file from start, replay every entry into an in-memory
//! `BTreeMap<index, (term, file_offset, payload_length)>`, and re-derive
//! `commit_index` + `last_applied` from a sidecar `commit.meta` file.
//!
//! The server opens this log at `{data_dir}/_raft` (`RAFT_DIR_NAME`).
//! `_raft` is not a valid index name, and the directory has no `wal`
//! child, so the engine's index scan does not open it.
//!
//! `hard.meta` stores the current term, the vote, and the logical end of
//! the log. Truncation does not rewrite `raft.log`; entries past that end
//! stay in the file and are ignored on the next open. A missing `hard.meta`
//! (a log written before this file existed) keeps every CRC-valid record.
//!
//! Exit criterion for M5.1 (verified by `raft_log_persist_test`):
//!
//! ```ignore
//! let path = tempdir()?;
//! let mut log = FileRaftLog::open(&path)?;
//! for i in 0..1000 { log.append(Entry::new(1, i, "cmd".into()))?; }
//! log.fsync()?;
//! drop(log);
//!
//! let log2 = FileRaftLog::open(&path)?;
//! assert_eq!(log2.len(), 1000);
//! assert_eq!(log2.entry(500)?.term, 1);
//! ```

use std::collections::BTreeMap;
use std::fs::{File, OpenOptions};
use std::io::{BufReader, BufWriter, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};

use anyhow::{anyhow, Context, Result};
use byteorder::{LittleEndian, ReadBytesExt};
use crc32fast::Hasher as Crc32;

/// Magic for the raft log file format.  Distinct from the WAL magic so
/// we never confuse one for the other on recovery.
const MAGIC: u32 = 0x5A52_4C32; // "ZRL2" (ASCII Z R L 2)
const HARD_MAGIC: u32 = 0x5A52_4853; // "ZRHS"
const LOG_FILE: &str = "raft.log";
const COMMIT_FILE: &str = "commit.meta";
const HARD_FILE: &str = "hard.meta";
const SNAPSHOT_FILE: &str = "snapshot.meta";
const SNAPSHOT_MAGIC: u32 = 0x5A52_534E; // "ZRSN"

/// Directory name under the node's data dir. Not a valid index name, so a
/// user index cannot occupy the same path and take the log with it on delete.
pub const RAFT_DIR_NAME: &str = "_raft";

/// One on-disk log record. `append` and log compaction both use this so a
/// rewritten file scans the same way as a file that was only appended to.
fn encode_entry(term: u64, index: u64, payload: &[u8]) -> Vec<u8> {
    let payload_len = payload.len() as u64;
    // Entry length covers everything after the len field up to the CRC,
    // inclusive — useful for future forward-compatible skipping.
    let entry_len: u64 = 8 + 8 + 1 + 8 + payload_len + 4;
    let kind = EntryKind::ClusterCommand as u8;
    let mut h = Crc32::new();
    h.update(&MAGIC.to_le_bytes());
    h.update(&entry_len.to_le_bytes());
    h.update(&term.to_le_bytes());
    h.update(&index.to_le_bytes());
    h.update(&[kind]);
    h.update(&payload_len.to_le_bytes());
    h.update(payload);
    let crc = h.finalize();

    let mut buf = Vec::with_capacity(4 + entry_len as usize);
    buf.extend_from_slice(&MAGIC.to_le_bytes());
    buf.extend_from_slice(&entry_len.to_le_bytes());
    buf.extend_from_slice(&term.to_le_bytes());
    buf.extend_from_slice(&index.to_le_bytes());
    buf.push(kind);
    buf.extend_from_slice(&payload_len.to_le_bytes());
    buf.extend_from_slice(payload);
    buf.extend_from_slice(&crc.to_le_bytes());
    buf
}

fn sync_dir(dir: &Path) -> Result<()> {
    let file = File::open(dir).with_context(|| format!("opening {dir:?} to sync"))?;
    file.sync_all()
        .with_context(|| format!("syncing raft dir {dir:?}"))?;
    Ok(())
}

/// `{data_dir}/_raft`, where the server opens [`FileRaftLog`].
pub fn raft_storage_dir(data_dir: impl AsRef<Path>) -> PathBuf {
    data_dir.as_ref().join(RAFT_DIR_NAME)
}

/// Raft payload kinds.  We only use `ClusterCommand` today but leave room
/// for future out-of-band messages (config changes, snapshots).
#[repr(u8)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EntryKind {
    ClusterCommand = 0,
    ConfigChange = 1,
    Snapshot = 2,
}

/// A single persisted log entry.
///
/// The payload is the `serde_json::to_vec` form of a
/// [`crate::raft::LogEntry::command`] — kept as raw bytes here so the
/// storage layer doesn't depend on the raft module's own command enum.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PersistedEntry {
    pub term: u64,
    pub index: u64,
    pub kind: EntryKind,
    pub payload: Vec<u8>,
}

/// File-backed Raft log.
///
/// Owns the write handle to `{dir}/raft.log` and a seek table mapping
/// Raft log `index` → (term, file offset, payload length).  The seek
/// table is rebuilt on open from the log file.
pub struct FileRaftLog {
    dir: PathBuf,
    writer: BufWriter<File>,
    /// `index → (term, absolute file offset of the entry header,
    /// payload length)`.  Sorted by index.
    seek_table: BTreeMap<u64, (u64, u64, u64)>,
    /// Highest index appended so far (0 if empty).
    last_index: u64,
    /// Commit index persisted to `commit.meta`.
    commit_index: u64,
    /// Current term persisted in `hard.meta`. 0 when that file is absent.
    hard_term: u64,
    /// Vote in `hard_term`, when one was persisted.
    hard_vote: Option<String>,
    /// Logical end of the log. `None` means `hard.meta` did not record one
    /// and the scan is authoritative. `Some(0)` is an empty log.
    log_end: Option<u64>,
    /// Raw snapshot payload from `snapshot.meta`, when that file exists.
    /// The Raft node decodes it. A missing file is a log that has not been
    /// compacted. A truncated or checksum-mismatched file fails the open.
    snapshot: Option<Vec<u8>>,
}

impl FileRaftLog {
    /// Open (or create) a Raft log directory.  Rebuilds the seek table
    /// from the on-disk file.  Skips any corrupt trailing record.
    pub fn open(dir: impl AsRef<Path>) -> Result<Self> {
        let dir = dir.as_ref().to_path_buf();
        std::fs::create_dir_all(&dir).with_context(|| format!("creating raft dir {dir:?}"))?;
        let log_path = dir.join(LOG_FILE);

        // Scan the file (if any) to rebuild the seek table.
        let mut seek_table: BTreeMap<u64, (u64, u64, u64)> = BTreeMap::new();
        let mut last_index: u64 = 0;

        if log_path.exists() {
            let file = File::open(&log_path).with_context(|| format!("opening {log_path:?}"))?;
            let mut reader = BufReader::new(file);

            loop {
                let header_offset = reader
                    .stream_position()
                    .with_context(|| "seek in raft log")?;

                // Try to read a record header.  On EOF or partial read, stop
                // cleanly — the writer's append-only contract means the only
                // time we see a partial record is at the file tail after a
                // crash mid-fsync, in which case we discard it.
                let magic = match reader.read_u32::<LittleEndian>() {
                    Ok(m) => m,
                    Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
                    Err(e) => return Err(anyhow!("reading magic: {e}")),
                };
                if magic != MAGIC {
                    // Corrupt tail — truncate and stop.
                    break;
                }
                let entry_len = match reader.read_u64::<LittleEndian>() {
                    Ok(v) => v,
                    Err(_) => break,
                };
                let term = match reader.read_u64::<LittleEndian>() {
                    Ok(v) => v,
                    Err(_) => break,
                };
                let index = match reader.read_u64::<LittleEndian>() {
                    Ok(v) => v,
                    Err(_) => break,
                };
                let _kind = match reader.read_u8() {
                    Ok(v) => v,
                    Err(_) => break,
                };
                let payload_len = match reader.read_u64::<LittleEndian>() {
                    Ok(v) => v,
                    Err(_) => break,
                };

                // Read the payload + crc.
                let mut payload = vec![0u8; payload_len as usize];
                if reader.read_exact(&mut payload).is_err() {
                    break;
                }
                let expected_crc = match reader.read_u32::<LittleEndian>() {
                    Ok(v) => v,
                    Err(_) => break,
                };

                // Verify CRC — if it mismatches, we hit a torn write.
                let mut h = Crc32::new();
                h.update(&MAGIC.to_le_bytes());
                h.update(&entry_len.to_le_bytes());
                h.update(&term.to_le_bytes());
                h.update(&index.to_le_bytes());
                h.update(&[_kind]);
                h.update(&payload_len.to_le_bytes());
                h.update(&payload);
                if h.finalize() != expected_crc {
                    break;
                }

                // New entries overwrite older ones at the same index
                // (leader truncation on term change); BTreeMap::insert
                // handles it for us.
                seek_table.insert(index, (term, header_offset, payload_len));
                if index > last_index {
                    last_index = index;
                }
            }
        }

        // Reopen the file for append.
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .read(false)
            .open(&log_path)
            .with_context(|| format!("opening {log_path:?} for append"))?;
        let writer = BufWriter::with_capacity(64 * 1024, file);

        // Load committed index (best-effort).
        let commit_index = Self::load_commit_index(&dir).unwrap_or(0);
        let (hard_term, hard_vote, log_end) = Self::load_hard_state(&dir)?;
        if let Some(end) = log_end {
            seek_table.retain(|&idx, _| idx <= end);
            last_index = seek_table.keys().next_back().copied().unwrap_or(0);
        }
        let snapshot = Self::load_snapshot(&dir)?;

        Ok(Self {
            dir,
            writer,
            seek_table,
            last_index,
            commit_index,
            hard_term,
            hard_vote,
            log_end,
            snapshot,
        })
    }

    fn load_commit_index(dir: &Path) -> Option<u64> {
        let path = dir.join(COMMIT_FILE);
        let bytes = std::fs::read(&path).ok()?;
        if bytes.len() < 8 {
            return None;
        }
        let mut arr = [0u8; 8];
        arr.copy_from_slice(&bytes[..8]);
        Some(u64::from_le_bytes(arr))
    }

    /// Append one entry to the log.  Does NOT fsync — call
    /// [`FileRaftLog::fsync`] after a batch to make the entries durable.
    pub fn append(&mut self, term: u64, index: u64, payload: &[u8]) -> Result<()> {
        let header_offset = self.current_offset()?;
        let record = encode_entry(term, index, payload);
        self.writer.write_all(&record)?;

        self.seek_table
            .insert(index, (term, header_offset, payload.len() as u64));
        if index > self.last_index {
            self.last_index = index;
        }
        Ok(())
    }

    /// Bytes of `snapshot.meta`, if a snapshot has been saved.
    pub fn snapshot_bytes(&self) -> Option<&[u8]> {
        self.snapshot.as_deref()
    }

    /// Replace `snapshot.meta`. The in-memory copy updates only after the
    /// rename and directory sync, so a failed write leaves the previous
    /// snapshot in place.
    pub fn save_snapshot(&mut self, payload: &[u8]) -> Result<()> {
        let path = self.dir.join(SNAPSHOT_FILE);
        let tmp = self.dir.join("snapshot.meta.tmp");
        let mut buf = Vec::with_capacity(16 + payload.len() + 4);
        buf.extend_from_slice(&SNAPSHOT_MAGIC.to_le_bytes());
        buf.extend_from_slice(&1u32.to_le_bytes());
        let len = u64::try_from(payload.len()).context("raft snapshot longer than u64")?;
        buf.extend_from_slice(&len.to_le_bytes());
        buf.extend_from_slice(payload);
        let mut h = Crc32::new();
        h.update(&buf);
        buf.extend_from_slice(&h.finalize().to_le_bytes());
        {
            let mut file = OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(&tmp)
                .with_context(|| format!("writing {tmp:?}"))?;
            file.write_all(&buf)
                .with_context(|| format!("writing {tmp:?}"))?;
            file.sync_all()
                .with_context(|| format!("syncing {tmp:?}"))?;
        }
        std::fs::rename(&tmp, &path).with_context(|| format!("replacing {path:?}"))?;
        sync_dir(&self.dir)?;
        self.snapshot = Some(payload.to_vec());
        Ok(())
    }

    /// Rewrite `raft.log` so it contains only entries with `index > through`.
    ///
    /// The new file is synced and renamed over the old one before the seek
    /// table drops the prefix. A failed write leaves the previous file, and
    /// its entries, in place.
    pub fn rewrite_without_prefix(&mut self, through: u64) -> Result<()> {
        if self.seek_table.keys().all(|idx| *idx > through) {
            return Ok(());
        }
        self.writer
            .flush()
            .context("flush raft log before compaction")?;
        let kept_idx: Vec<u64> = self
            .seek_table
            .keys()
            .copied()
            .filter(|idx| *idx > through)
            .collect();
        let mut kept = Vec::with_capacity(kept_idx.len());
        for idx in kept_idx {
            let (term, payload) = self.read(idx)?.ok_or_else(|| {
                anyhow!("raft entry {idx} disappeared while compacting the log prefix")
            })?;
            kept.push((term, idx, payload));
        }

        let new_path = self.dir.join("raft.log.new");
        let mut new_table: BTreeMap<u64, (u64, u64, u64)> = BTreeMap::new();
        {
            let mut file = OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(&new_path)
                .with_context(|| format!("writing {new_path:?}"))?;
            let mut offset = 0u64;
            for (term, index, payload) in &kept {
                let record = encode_entry(*term, *index, payload);
                file.write_all(&record)
                    .with_context(|| format!("writing {new_path:?}"))?;
                new_table.insert(*index, (*term, offset, payload.len() as u64));
                offset += record.len() as u64;
            }
            file.sync_all()
                .with_context(|| format!("syncing {new_path:?}"))?;
        }
        let final_path = self.dir.join(LOG_FILE);
        std::fs::rename(&new_path, &final_path)
            .with_context(|| format!("replacing {final_path:?}"))?;
        sync_dir(&self.dir)?;

        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .read(false)
            .open(&final_path)
            .with_context(|| format!("reopening {final_path:?} after compaction"))?;
        self.writer = BufWriter::with_capacity(64 * 1024, file);
        self.seek_table = new_table;
        self.last_index = self.seek_table.keys().next_back().copied().unwrap_or(0);
        self.set_log_end(self.last_index)?;
        Ok(())
    }

    /// Force durability — flushes buffered writes and `fsync`s the
    /// underlying file.  Callers should batch appends and then fsync
    /// at the end of the batch.
    pub fn fsync(&mut self) -> Result<()> {
        self.writer.flush()?;
        self.writer.get_ref().sync_data()?;
        Ok(())
    }

    fn current_offset(&mut self) -> Result<u64> {
        // BufWriter doesn't expose the underlying cursor directly; we
        // flush then ask the file for the position.  Flush is cheap
        // because append-only keeps the buffer small.
        self.writer.flush()?;
        let pos = self.writer.get_mut().stream_position()?;
        Ok(pos)
    }

    /// Read an entry back from disk by log index.
    ///
    /// Returns `None` if the index has not been written or has been
    /// truncated away.
    pub fn read(&mut self, index: u64) -> Result<Option<(u64, Vec<u8>)>> {
        let Some(&(term, offset, payload_len)) = self.seek_table.get(&index) else {
            return Ok(None);
        };
        // Open a fresh read handle so we don't fight with the writer's
        // buffered position.
        let log_path = self.dir.join(LOG_FILE);
        let mut file =
            File::open(&log_path).with_context(|| format!("reopening {log_path:?} for read"))?;
        // Header is: magic(4) + entry_len(8) + term(8) + index(8) + kind(1) + payload_len(8)
        // = 37 bytes.  Then the payload.
        file.seek(SeekFrom::Start(offset + 37))
            .with_context(|| "seek to entry payload")?;
        let mut payload = vec![0u8; payload_len as usize];
        file.read_exact(&mut payload)
            .with_context(|| "reading entry payload")?;
        Ok(Some((term, payload)))
    }

    /// Drop every seek-table entry with `index >= from`.
    ///
    /// The file is not rewritten. The drop becomes durable when
    /// [`FileRaftLog::set_log_end`] records the new end; until that file
    /// is replaced, a crash reopens the previous tail. Callers that have
    /// already decided the tail is gone must set the end before they
    /// acknowledge the append that conflicted.
    pub fn truncate_from(&mut self, from: u64) {
        self.seek_table.retain(|&idx, _| idx < from);
        self.last_index = self
            .seek_table
            .iter()
            .next_back()
            .map(|(k, _)| *k)
            .unwrap_or(0);
    }

    /// Persist the `commit_index` to a sidecar file.  Called by the
    /// Raft state machine after every commit-index advance.
    pub fn set_commit_index(&mut self, idx: u64) -> Result<()> {
        self.commit_index = idx;
        let path = self.dir.join(COMMIT_FILE);
        let tmp = self.dir.join("commit.meta.tmp");
        std::fs::write(&tmp, idx.to_le_bytes())?;
        std::fs::rename(&tmp, &path)?;
        Ok(())
    }

    /// Term and vote from `hard.meta`. Term 0 and a missing vote mean the
    /// file was absent.
    pub fn hard_term(&self) -> u64 {
        self.hard_term
    }

    pub fn hard_vote(&self) -> Option<&str> {
        self.hard_vote.as_deref()
    }

    /// Logical end recorded in `hard.meta`, if that file had one.
    pub fn persisted_log_end(&self) -> Option<u64> {
        self.log_end
    }

    /// Record the current term and vote. The logical log end is left as it is.
    ///
    /// Memory is updated only after `hard.meta` is replaced. A failed write
    /// leaves the previous term and vote in place, so a later log-end save
    /// cannot publish an election this process aborted.
    pub fn set_hard_state(&mut self, term: u64, voted_for: Option<&str>) -> Result<()> {
        self.persist_hard(term, voted_for, self.log_end)?;
        self.hard_term = term;
        self.hard_vote = voted_for.map(str::to_string);
        Ok(())
    }

    /// Record the highest index that is still part of the log.
    ///
    /// The file is replaced before the seek table drops indexes above `end`.
    /// A failed write leaves those entries readable. The next open ignores
    /// them once this call has succeeded.
    pub fn set_log_end(&mut self, end: u64) -> Result<()> {
        self.persist_hard(self.hard_term, self.hard_vote.as_deref(), Some(end))?;
        if end < self.last_index {
            self.truncate_from(end + 1);
        }
        self.log_end = Some(end);
        Ok(())
    }

    /// Replace `hard.meta`. The caller updates its fields only after this
    /// returns `Ok`.
    fn persist_hard(&self, term: u64, vote: Option<&str>, log_end: Option<u64>) -> Result<()> {
        let path = self.dir.join(HARD_FILE);
        let tmp = self.dir.join("hard.meta.tmp");
        let mut buf = Vec::with_capacity(64);
        buf.extend_from_slice(&HARD_MAGIC.to_le_bytes());
        buf.extend_from_slice(&1u32.to_le_bytes());
        buf.extend_from_slice(&term.to_le_bytes());
        match log_end {
            Some(end) => {
                buf.push(1);
                buf.extend_from_slice(&end.to_le_bytes());
            }
            None => {
                buf.push(0);
                buf.extend_from_slice(&0u64.to_le_bytes());
            }
        }
        match vote {
            Some(vote) => {
                let bytes = vote.as_bytes();
                let len = u32::try_from(bytes.len()).context("raft vote longer than u32")?;
                buf.extend_from_slice(&len.to_le_bytes());
                buf.extend_from_slice(bytes);
            }
            None => buf.extend_from_slice(&u32::MAX.to_le_bytes()),
        }
        {
            let mut file = OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .open(&tmp)
                .with_context(|| format!("writing {tmp:?}"))?;
            file.write_all(&buf)
                .with_context(|| format!("writing {tmp:?}"))?;
            file.sync_all()
                .with_context(|| format!("syncing {tmp:?}"))?;
        }
        std::fs::rename(&tmp, &path).with_context(|| format!("replacing {path:?}"))?;
        // The rename is the publication. Sync the directory so a crash cannot
        // lose the directory entry that names the new file.
        sync_dir(&self.dir)?;
        Ok(())
    }

    fn load_hard_state(dir: &Path) -> Result<(u64, Option<String>, Option<u64>)> {
        let path = dir.join(HARD_FILE);
        if !path.exists() {
            return Ok((0, None, None));
        }
        let bytes = std::fs::read(&path).with_context(|| format!("reading {path:?}"))?;
        if bytes.len() < 4 + 4 + 8 + 1 + 8 + 4 {
            return Err(anyhow!("raft hard state {path:?} is truncated"));
        }
        let magic = u32::from_le_bytes(bytes[0..4].try_into().expect("4 bytes"));
        if magic != HARD_MAGIC {
            return Err(anyhow!("raft hard state {path:?} has a bad magic"));
        }
        let version = u32::from_le_bytes(bytes[4..8].try_into().expect("4 bytes"));
        if version != 1 {
            return Err(anyhow!(
                "raft hard state {path:?} has version {version}, want 1"
            ));
        }
        let term = u64::from_le_bytes(bytes[8..16].try_into().expect("8 bytes"));
        let has_end = bytes[16];
        let end = u64::from_le_bytes(bytes[17..25].try_into().expect("8 bytes"));
        let log_end = match has_end {
            0 => None,
            1 => Some(end),
            other => return Err(anyhow!("raft hard state {path:?} has log-end flag {other}")),
        };
        let vote_len = u32::from_le_bytes(bytes[25..29].try_into().expect("4 bytes"));
        let vote = if vote_len == u32::MAX {
            None
        } else {
            let start = 29;
            let end_at = start + vote_len as usize;
            if bytes.len() < end_at {
                return Err(anyhow!("raft hard state {path:?} vote is truncated"));
            }
            let text = std::str::from_utf8(&bytes[start..end_at])
                .with_context(|| format!("raft vote in {path:?} is not utf-8"))?;
            Some(text.to_string())
        };
        Ok((term, vote, log_end))
    }

    fn load_snapshot(dir: &Path) -> Result<Option<Vec<u8>>> {
        let path = dir.join(SNAPSHOT_FILE);
        if !path.exists() {
            return Ok(None);
        }
        let bytes = std::fs::read(&path).with_context(|| format!("reading {path:?}"))?;
        if bytes.len() < 4 + 4 + 8 + 4 {
            return Err(anyhow!("raft snapshot {path:?} is truncated"));
        }
        let magic = u32::from_le_bytes(bytes[0..4].try_into().expect("4 bytes"));
        if magic != SNAPSHOT_MAGIC {
            return Err(anyhow!("raft snapshot {path:?} has a bad magic"));
        }
        let version = u32::from_le_bytes(bytes[4..8].try_into().expect("4 bytes"));
        if version != 1 {
            return Err(anyhow!(
                "raft snapshot {path:?} has version {version}, want 1"
            ));
        }
        let len = usize::try_from(u64::from_le_bytes(
            bytes[8..16].try_into().expect("8 bytes"),
        ))
        .context("raft snapshot length does not fit usize")?;
        let header = 16;
        let crc_at = header + len;
        if bytes.len() != crc_at + 4 {
            return Err(anyhow!("raft snapshot {path:?} is truncated"));
        }
        let expected = u32::from_le_bytes(bytes[crc_at..crc_at + 4].try_into().expect("4 bytes"));
        let mut h = Crc32::new();
        h.update(&bytes[..crc_at]);
        if h.finalize() != expected {
            return Err(anyhow!("raft snapshot {path:?} has a bad checksum"));
        }
        Ok(Some(bytes[header..crc_at].to_vec()))
    }

    /// Highest log index appended so far (0 if the log is empty).
    pub fn last_index(&self) -> u64 {
        self.last_index
    }

    /// Persisted commit index.  Survives restarts.
    pub fn commit_index(&self) -> u64 {
        self.commit_index
    }

    /// Number of entries currently in the seek table.
    pub fn len(&self) -> usize {
        self.seek_table.len()
    }

    /// `true` if no entries have been appended (ignoring truncated tails).
    pub fn is_empty(&self) -> bool {
        self.seek_table.is_empty()
    }

    /// Term of the entry at `index`, or `None` if missing.
    pub fn term_of(&self, index: u64) -> Option<u64> {
        self.seek_table.get(&index).map(|(t, _, _)| *t)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn append_and_reread() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        for i in 1..=1000u64 {
            log.append(1, i, format!("entry-{}", i).as_bytes()).unwrap();
        }
        log.fsync().unwrap();
        drop(log);

        let mut log2 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log2.len(), 1000);
        assert_eq!(log2.last_index(), 1000);
        let (term, payload) = log2.read(500).unwrap().unwrap();
        assert_eq!(term, 1);
        assert_eq!(payload, b"entry-500");
    }

    #[test]
    fn commit_index_persists() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        log.append(1, 1, b"x").unwrap();
        log.append(1, 2, b"y").unwrap();
        log.fsync().unwrap();
        log.set_commit_index(2).unwrap();
        drop(log);

        let log2 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log2.commit_index(), 2);
    }

    #[test]
    fn truncate_drops_tail() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        for i in 1..=10 {
            log.append(1, i, format!("{i}").as_bytes()).unwrap();
        }
        log.fsync().unwrap();
        log.truncate_from(6);
        assert_eq!(log.last_index(), 5);
        assert!(log.read(7).unwrap().is_none());
        assert_eq!(log.read(3).unwrap().unwrap().1, b"3");
    }

    #[test]
    fn corrupt_tail_is_ignored_on_reopen() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        for i in 1..=5 {
            log.append(1, i, format!("{i}").as_bytes()).unwrap();
        }
        log.fsync().unwrap();
        drop(log);

        // Corrupt the last few bytes of the file.
        let log_path = dir.path().join(LOG_FILE);
        let mut bytes = std::fs::read(&log_path).unwrap();
        let last_byte = bytes.last_mut().unwrap();
        *last_byte ^= 0xff;
        std::fs::write(&log_path, &bytes).unwrap();

        // Reopen — the last entry should be dropped by the CRC check;
        // at minimum, we should have entries 1..=4 recoverable.
        let log2 = FileRaftLog::open(dir.path()).unwrap();
        assert!(log2.len() >= 4);
        assert!(log2.len() <= 5);
    }

    #[test]
    fn log_end_hides_a_truncated_tail_on_reopen() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        for i in 1..=5 {
            log.append(1, i, format!("{i}").as_bytes()).unwrap();
        }
        log.fsync().unwrap();
        log.truncate_from(4);
        log.set_log_end(3).unwrap();
        drop(log);

        let mut log2 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log2.last_index(), 3);
        assert!(log2.read(4).unwrap().is_none());
        assert!(log2.read(5).unwrap().is_none());
        assert_eq!(log2.read(3).unwrap().unwrap().1, b"3");

        log2.append(2, 4, b"new").unwrap();
        log2.fsync().unwrap();
        log2.set_log_end(4).unwrap();
        drop(log2);

        let mut log3 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log3.last_index(), 4);
        assert_eq!(log3.read(4).unwrap().unwrap().1, b"new");
        assert!(log3.read(5).unwrap().is_none());
    }

    #[test]
    fn hard_state_roundtrip_and_a_truncated_file_refuses_to_open() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        log.set_hard_state(4, Some("n2")).unwrap();
        log.set_log_end(0).unwrap();
        drop(log);

        let log2 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log2.hard_term(), 4);
        assert_eq!(log2.hard_vote(), Some("n2"));
        assert_eq!(log2.persisted_log_end(), Some(0));

        std::fs::write(dir.path().join(HARD_FILE), [1u8, 2, 3]).unwrap();
        match FileRaftLog::open(dir.path()) {
            Err(err) => assert!(
                err.to_string().contains("truncated"),
                "corrupt hard state must not look like no vote: {err}"
            ),
            Ok(_) => panic!("corrupt hard state opened"),
        }
    }

    #[test]
    fn snapshot_roundtrip_and_a_bad_checksum_refuses_to_open() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        assert!(log.snapshot_bytes().is_none());
        log.save_snapshot(b"commands").unwrap();
        assert_eq!(log.snapshot_bytes(), Some(b"commands".as_slice()));
        drop(log);

        let log2 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log2.snapshot_bytes(), Some(b"commands".as_slice()));

        let path = dir.path().join(SNAPSHOT_FILE);
        let mut bytes = std::fs::read(&path).unwrap();
        let last = bytes.len() - 1;
        bytes[last] ^= 0xff;
        std::fs::write(&path, bytes).unwrap();
        match FileRaftLog::open(dir.path()) {
            Err(err) => assert!(
                err.to_string().contains("checksum"),
                "a torn snapshot must not open as an empty one: {err}"
            ),
            Ok(_) => panic!("corrupt snapshot opened"),
        }
    }

    #[test]
    fn rewrite_drops_the_prefix_and_keeps_the_suffix() {
        let dir = tempdir().unwrap();
        let mut log = FileRaftLog::open(dir.path()).unwrap();
        for i in 1..=5 {
            log.append(1, i, format!("{i}").as_bytes()).unwrap();
        }
        log.fsync().unwrap();
        log.save_snapshot(b"snap").unwrap();
        log.rewrite_without_prefix(3).unwrap();
        assert_eq!(log.len(), 2);
        assert!(log.read(1).unwrap().is_none());
        assert!(log.read(3).unwrap().is_none());
        assert_eq!(log.read(4).unwrap().unwrap().1, b"4");
        assert_eq!(log.read(5).unwrap().unwrap().1, b"5");
        drop(log);

        let mut log2 = FileRaftLog::open(dir.path()).unwrap();
        assert_eq!(log2.snapshot_bytes(), Some(b"snap".as_slice()));
        assert_eq!(log2.len(), 2);
        assert_eq!(log2.last_index(), 5);
        assert!(log2.read(2).unwrap().is_none());
        assert_eq!(log2.read(5).unwrap().unwrap().1, b"5");
    }
}

//! Cluster runner — drives the Raft consensus loop and message passing.
//!
//! [`ClusterRunner`] owns a [`ClusterNode`] and runs a single async loop that,
//! each iteration, drives one [`ClusterNode::step`]: it drains an inbound
//! message from a peer (bounded by the tick interval), delivers it to the Raft
//! state machine, and then ticks — advancing elections and dispatching
//! heartbeat / log-replication RPCs.
//!
//! Shutdown is controlled via a `tokio::sync::watch` channel. When the watch
//! value becomes `true` the run loop exits cleanly; the shutdown wait is raced
//! against `step` via `tokio::select!` so a shutdown is observed promptly
//! rather than only between ticks.

use std::time::Duration;

use tokio::sync::watch;
use tracing::{info, warn};

use crate::node::ClusterNode;

/// How often a member asks primaries to fill replica shards it is missing.
///
/// The first pass runs as soon as the runner starts. Later passes wait this
/// long, or less when shutdown is signalled. A pass that finds nothing out
/// of sync does not call a peer.
const REPLICA_BACKFILL_INTERVAL: Duration = Duration::from_millis(200);

// ── ClusterRunner ─────────────────────────────────────────────────────────────

/// Drives the Raft state machine in a background async task.
///
/// # Example
///
/// ```rust,no_run
/// use std::time::Duration;
/// use tokio::sync::watch;
/// use xerj_cluster::node::{ClusterNode, in_memory::{InMemoryBus, InMemoryTransport}};
/// use xerj_cluster::runner::ClusterRunner;
///
/// #[tokio::main]
/// async fn main() {
///     let bus = xerj_cluster::node::in_memory::InMemoryBus::new();
///     let transport = InMemoryTransport::new("n1".to_string(), bus).await;
///     let node = ClusterNode::new("n1".to_string(), vec![], Box::new(transport));
///
///     let (shutdown_tx, shutdown_rx) = watch::channel(false);
///     let mut runner = ClusterRunner::new(node, Duration::from_millis(50), shutdown_rx);
///
///     // Spawn the runner
///     let handle = tokio::spawn(async move { runner.run().await });
///
///     // ... later, signal shutdown
///     let _ = shutdown_tx.send(true);
///     let _ = handle.await;
/// }
/// ```
pub struct ClusterRunner {
    /// The cluster node being driven.
    pub node: ClusterNode,
    /// How often to tick the Raft state machine.
    tick_interval: Duration,
    /// Shutdown signal. When the value is `true` the run loop exits.
    shutdown: watch::Receiver<bool>,
}

impl ClusterRunner {
    /// Create a new runner.
    ///
    /// * `node` — the cluster node to drive.
    /// * `tick_interval` — Raft tick period (recommended: 50 ms in production,
    ///   1–10 ms in tests).
    /// * `shutdown` — receive end of a `watch::channel(false)`. Set the watch
    ///   to `true` to request shutdown.
    pub fn new(
        node: ClusterNode,
        tick_interval: Duration,
        shutdown: watch::Receiver<bool>,
    ) -> Self {
        ClusterRunner {
            node,
            tick_interval,
            shutdown,
        }
    }

    /// Run the Raft event loop until the shutdown signal fires.
    ///
    /// Each iteration races two futures with `tokio::select!`:
    /// - [`ClusterNode::step`] — drain one inbound peer message (bounded by
    ///   `tick_interval`), deliver it to the Raft state machine, then tick.
    /// - `shutdown.changed()` — resolves when the shutdown watch is set (or the
    ///   sender is dropped), at which point the loop exits.
    ///
    /// This actually *handles* inbound messages, so leader election and log
    /// replication make progress. (The previous implementation only slept and
    /// ticked, never calling `recv()`, so a multi-node cluster could never
    /// elect a leader.)
    pub async fn run(&mut self) {
        info!(
            node = %self.node.raft.id,
            tick_ms = self.tick_interval.as_millis(),
            "ClusterRunner starting"
        );

        let tick = self.tick_interval;
        let backfill = self.spawn_replica_backfill();
        loop {
            // Fast path: already asked to shut down before we start a step.
            if *self.shutdown.borrow() {
                info!(node = %self.node.raft.id, "ClusterRunner received shutdown signal");
                break;
            }

            tokio::select! {
                // Shutdown requested (value changed) or sender dropped (Err).
                changed = self.shutdown.changed() => {
                    if changed.is_err() || *self.shutdown.borrow() {
                        info!(node = %self.node.raft.id, "ClusterRunner received shutdown signal");
                        break;
                    }
                }
                // Drive one iteration of the Raft loop: recv → handle → tick.
                res = self.node.step(tick) => {
                    if let Err(e) = res {
                        warn!(
                            node = %self.node.raft.id,
                            error = %e,
                            "Raft step error"
                        );
                    }
                }
            }
        }

        backfill.abort();
        info!(node = %self.node.raft.id, "ClusterRunner stopped");
    }

    /// Copy documents onto replica shards this node does not have in sync.
    ///
    /// Runs beside the Raft step so a copy does not delay an election. The
    /// task stops when this runner stops.
    fn spawn_replica_backfill(&self) -> tokio::task::JoinHandle<()> {
        let applier = self.node.applier();
        let mut shutdown = self.shutdown.clone();
        tokio::spawn(async move {
            let Some(applier) = applier else {
                return;
            };
            loop {
                if *shutdown.borrow() {
                    break;
                }
                applier.backfill_local_replicas().await;
                tokio::select! {
                    changed = shutdown.changed() => {
                        if changed.is_err() || *shutdown.borrow() {
                            break;
                        }
                    }
                    _ = tokio::time::sleep(REPLICA_BACKFILL_INTERVAL) => {}
                }
            }
        })
    }

    /// Whether the node currently believes itself to be the Raft leader.
    pub fn is_leader(&self) -> bool {
        self.node.is_leader()
    }

    /// The node ID of the current leader (if known).
    pub fn leader_id(&self) -> Option<&str> {
        self.node.leader_id()
    }
}

// ── ClusterRunnerBuilder ──────────────────────────────────────────────────────

/// Convenience builder that wires together a [`ClusterNode`] and a
/// [`ClusterRunner`].
pub struct ClusterRunnerBuilder {
    tick_interval: Duration,
}

impl ClusterRunnerBuilder {
    pub fn new() -> Self {
        ClusterRunnerBuilder {
            tick_interval: Duration::from_millis(50),
        }
    }

    pub fn tick_interval(mut self, d: Duration) -> Self {
        self.tick_interval = d;
        self
    }

    pub fn build(self, node: ClusterNode, shutdown: watch::Receiver<bool>) -> ClusterRunner {
        ClusterRunner::new(node, self.tick_interval, shutdown)
    }
}

impl Default for ClusterRunnerBuilder {
    fn default() -> Self {
        Self::new()
    }
}

//! Data-plane calls between shard owners.
//!
//! Metadata (index create, the shard plan) goes through the Raft log.
//! A document does not. The node that accepts the HTTP call asks
//! [`crate::router::ShardRouter`] which member owns the document and, when
//! that member is someone else, invokes [`ShardRpc::call`]. The owner's
//! [`ShardHandler`] applies the operation to local storage and returns the
//! JSON the caller's HTTP response forwards.
//!
//! In-process tests share a [`MemoryShardDir`]. The TCP transport opens a
//! fresh authenticated connection, writes one [`crate::raft::RaftMessage::ShardRequest`],
//! and reads one [`crate::raft::RaftMessage::ShardResponse`] before closing.
//! That exchange is not the Raft outbound queue: a dropped heartbeat is
//! retransmitted, a dropped document write must not be.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use serde::{Deserialize, Serialize};

/// One primary-shard assignment carried in a committed index-create entry.
///
/// `replicas` are other members that hold a copy of this shard. Empty when
/// the index was created with `number_of_replicas` 0 (the default) or when
/// the entry predates replica placement.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ShardAssignment {
    pub shard: u32,
    pub node_id: String,
    #[serde(default)]
    pub replicas: Vec<String>,
}

/// One primary per member, shard `i` on the `i`th member id in sorted order.
///
/// No replicas. Equivalent to [`shard_plan`] with `number_of_replicas` 0.
/// The plan is computed by the node that proposes the create and stored in
/// the log entry. Every member applies that list; nobody recomputes it.
pub fn primary_shard_plan(members: &[String]) -> Vec<ShardAssignment> {
    shard_plan(members, 0)
}

/// Primary plan plus up to `number_of_replicas` copies of each shard.
///
/// Replicas are the next members in the sorted ring, wrapping, never the
/// primary. The count is capped at `members - 1`: a node does not hold a
/// replica of a shard it already owns. The proposer stores this list in the
/// create entry. Every member applies it; nobody recomputes it.
pub fn shard_plan(members: &[String], number_of_replicas: u32) -> Vec<ShardAssignment> {
    let mut members: Vec<&str> = members
        .iter()
        .map(String::as_str)
        .filter(|id| !id.is_empty())
        .collect();
    members.sort_unstable();
    members.dedup();
    if members.is_empty() {
        return Vec::new();
    }
    let cap = (members.len() - 1) as u32;
    let replicas = number_of_replicas.min(cap);
    (0..members.len() as u32)
        .map(|shard| {
            let mut copies = Vec::with_capacity(replicas as usize);
            for offset in 1..=replicas {
                let idx = (shard as usize + offset as usize) % members.len();
                copies.push(members[idx].to_string());
            }
            ShardAssignment {
                shard,
                node_id: members[shard as usize].to_string(),
                replicas: copies,
            }
        })
        .collect()
}

/// Hidden index that stores one shard's replica documents on the replica node.
///
/// Replica bytes are not written into the user index. That index is what a
/// primary search reads, and a node is primary for some shards and replica
/// for others — mixing the copies would make a fan-out count every document
/// twice. The name is a `.xerj_*` system index so the default catalogue hides
/// it. `None` when the name would not pass [`xerj_common`] index rules; the
/// caller refuses the create instead of truncating.
pub fn replica_index_name(index: &str, shard: u32) -> Option<String> {
    let name = format!(".xerj_replica_{index}_{shard}");
    if name.len() > 255 || name.contains("..") {
        return None;
    }
    Some(name)
}

/// `index.number_of_replicas` from a create-settings object.
///
/// Accepts the nested form (`{"index": {"number_of_replicas": 1}}`), the
/// flat form, and the dotted key. Strings and numbers both count. Absent or
/// unreadable means 0, which places no copies.
pub fn number_of_replicas_from_settings(settings: &serde_json::Value) -> u32 {
    fn parse(value: &serde_json::Value) -> Option<u32> {
        match value {
            serde_json::Value::Number(n) => n.as_u64().and_then(|n| u32::try_from(n).ok()),
            serde_json::Value::String(s) => s.parse().ok(),
            _ => None,
        }
    }
    settings
        .pointer("/index/number_of_replicas")
        .or_else(|| settings.get("number_of_replicas"))
        .or_else(|| settings.get("index.number_of_replicas"))
        .and_then(parse)
        .unwrap_or(0)
}

/// Replica acknowledgements a document write needs before the caller is told it landed.
///
/// `placed` is how many replicas the create entry named, not how many are
/// still in sync. Copies are that count plus the primary. A quorum is
/// `copies / 2 + 1` (a majority of the group). The primary has already
/// applied the write, so it counts as one and the return value is the
/// number of replica confirmations still required.
///
/// | placed replicas | copies | quorum | replica acks |
/// | --- | --- | --- | --- |
/// | 0 | 1 | 1 | 0 |
/// | 1 | 2 | 2 | 1 |
/// | 2 | 3 | 2 | 1 |
/// | 3 | 4 | 3 | 2 |
///
/// This is the majority of the replication group. [`crate::replication::ReplicationMode::Quorum`]
/// is a different helper (a majority of replicas only, not counting the
/// primary) and is not the document path.
pub fn replica_quorum_acks(placed: usize) -> usize {
    let copies = placed.saturating_add(1);
    let quorum = copies / 2 + 1;
    quorum.saturating_sub(1)
}

/// Assignments embedded in a `CreateIndex` schema envelope, if any.
///
/// A schema that is not the replicated envelope — including the `"{}"`
/// fixtures the Raft tests propose — yields an empty plan.
pub fn shard_plan_from_schema_json(schema_json: &str) -> Vec<ShardAssignment> {
    let Ok(value) = serde_json::from_str::<serde_json::Value>(schema_json) else {
        return Vec::new();
    };
    let Some(items) = value.get("shard_plan").and_then(|v| v.as_array()) else {
        return Vec::new();
    };
    items
        .iter()
        .filter_map(|item| {
            let shard = item.get("shard")?.as_u64()?;
            let node_id = item.get("node_id")?.as_str()?.to_string();
            if node_id.is_empty() || shard > u32::MAX as u64 {
                return None;
            }
            let replicas = item
                .get("replicas")
                .and_then(|v| v.as_array())
                .map(|items| {
                    items
                        .iter()
                        .filter_map(|v| v.as_str())
                        .filter(|id| !id.is_empty() && *id != node_id)
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default();
            Some(ShardAssignment {
                shard: shard as u32,
                node_id,
                replicas,
            })
        })
        .collect()
}

/// A document or search operation forwarded to the shard owner.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ShardOp {
    /// Index or create one document. `source_json` is the body after the
    /// accepting node has run pipelines and field checks.
    IndexDoc {
        index: String,
        id: String,
        source_json: String,
        /// `"index"` or `"create"`.
        op: String,
        /// Internal (1-based) sequence, already translated from the ES wire.
        if_seq_no: Option<u64>,
        if_primary_term: Option<u64>,
        version: Option<u64>,
        version_type: Option<String>,
        /// Apply on the replica store for [`ShardOp::IndexDoc::shard`] and
        /// do not replicate further. The primary sets this when it copies
        /// an acknowledged write.
        #[serde(default)]
        replica: bool,
        /// Shard id. Meaningful when `replica` is set; the primary's own
        /// apply ignores it and routes by document id.
        #[serde(default)]
        shard: u32,
    },
    GetDoc {
        index: String,
        id: String,
        source: Option<String>,
        source_includes: Option<String>,
        source_excludes: Option<String>,
        /// Read the replica store instead of the primary index.
        #[serde(default)]
        replica: bool,
        #[serde(default)]
        shard: u32,
    },
    DeleteDoc {
        index: String,
        id: String,
        if_seq_no: Option<u64>,
        if_primary_term: Option<u64>,
        /// Apply on the replica store and do not replicate further.
        #[serde(default)]
        replica: bool,
        #[serde(default)]
        shard: u32,
    },
    /// Partial or scripted update. The primary applies it, then copies the
    /// stored document onto the in-sync replicas the same way an index does.
    ///
    /// `index` is the name the caller used. An alias is resolved on the
    /// primary before the write is placed.
    UpdateDoc {
        index: String,
        id: String,
        /// JSON update body (`doc`, `upsert`, `doc_as_upsert`, `script`).
        body_json: String,
        /// JSON update query params (`refresh`, `_source`, includes, excludes).
        params_json: String,
    },
    /// A bulk body whose actions belong to shards this node owns.
    ///
    /// The coordinating node assigns missing ids and groups actions by
    /// primary. This node runs the local bulk pipeline, then copies each
    /// successful index, create, update, and delete onto the in-sync replicas.
    Bulk {
        /// NDJSON. Action lines name `_index` and `_id`.
        body: String,
        default_index: Option<String>,
        require_alias: Option<bool>,
        default_pipeline: Option<String>,
        /// JSON value of the URL-level `_source` filter, when one was set.
        default_source_req_json: Option<String>,
    },
    /// Run `_update_by_query` on this primary's shard only.
    ///
    /// The coordinating node sends one of these to every primary. This node
    /// updates documents in its user index and copies each updated document
    /// onto the in-sync replicas. `check_only` confirms the index is open and
    /// the pipeline can run, and writes nothing.
    UpdateByQuery {
        index: String,
        /// JSON query object. Already combined with any alias filter.
        query_json: String,
        /// Painless source. Absent when the request has no script.
        #[serde(default)]
        script_source: Option<String>,
        /// JSON script params. Absent when there is no script.
        #[serde(default)]
        script_params_json: Option<String>,
        /// Ingest pipeline name. The primary runs it; pipelines are not
        /// replicated with the index.
        #[serde(default)]
        pipeline: Option<String>,
        #[serde(default)]
        max_docs: Option<u64>,
        scroll_size: u64,
        #[serde(default)]
        check_only: bool,
    },
    /// Run `_delete_by_query` on this primary's shard only.
    ///
    /// The coordinating node sends one of these to every primary. This node
    /// deletes documents in its user index and copies each delete onto the
    /// in-sync replicas. `check_only` confirms the index is open and writes
    /// nothing.
    DeleteByQuery {
        index: String,
        /// JSON query object. Already combined with any alias filter.
        query_json: String,
        #[serde(default)]
        max_docs: Option<u64>,
        scroll_size: u64,
        #[serde(default)]
        check_only: bool,
    },
    /// Search this member's local shard only. The caller merges hits.
    Search {
        index: String,
        /// JSON object, the search body, with `from`/`size` already widened
        /// to the window the merger needs.
        body_json: String,
        /// JSON [`crate`] search query params. `from` and `size` match the body.
        params_json: String,
    },
    /// Copy this primary's live documents onto `replica_id` and, once that
    /// copy matches, publish `replica_id` in the in-sync set.
    ///
    /// The caller is a replica that is placed for `shard` and is not in the
    /// in-sync set. The primary holds the shard's replica lock across the
    /// copy and the publish, so a document write that lands during the copy
    /// is replicated to the new set when the lock is released. Documents are
    /// not part of the Raft snapshot; this is the copy that fills them in.
    BackfillReplica {
        index: String,
        shard: u32,
        replica_id: String,
    },
    /// Delete replica-store documents whose ids are not in `ids`.
    ///
    /// Sent by the primary at the end of [`ShardOp::BackfillReplica`], after
    /// the live documents have been upserted. Does not replicate further.
    RetainReplicaDocs {
        index: String,
        shard: u32,
        ids: Vec<String>,
    },
}

/// What the owner sends back. `status` is an HTTP status; `body` is JSON.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ShardResult {
    pub status: u16,
    pub body: String,
}

impl ShardResult {
    pub fn http(status: u16, body: impl Into<String>) -> Self {
        ShardResult {
            status,
            body: body.into(),
        }
    }
}

/// Why a shard call did not produce a [`ShardResult`].
///
/// The document was not acknowledged. Callers must not write it locally
/// instead.
#[derive(Debug, thiserror::Error)]
pub enum ShardError {
    #[error("shard call to {to} failed: {reason}")]
    Unavailable { to: String, reason: String },
    #[error("shard call to {to} timed out")]
    Timeout { to: String },
}

/// Executes a [`ShardOp`] against this node's engine.
#[async_trait::async_trait]
pub trait ShardHandler: Send + Sync {
    async fn handle(&self, op: ShardOp) -> ShardResult;
}

/// Sends a [`ShardOp`] to the named member and waits for its result.
#[async_trait::async_trait]
pub trait ShardRpc: Send + Sync {
    async fn call(&self, to: &str, op: ShardOp) -> Result<ShardResult, ShardError>;
    fn set_handler(&self, handler: Arc<dyn ShardHandler>);

    /// Drop this node's handler so later calls fail instead of applying.
    ///
    /// The in-process ring uses this to stand in for a dead member. A TCP
    /// node that has stopped accepting is already [`ShardError::Unavailable`].
    fn clear_handler(&self) {}
}

/// Transport that has no data plane. Calls fail; nothing is written locally.
pub struct NullShardRpc;

#[async_trait::async_trait]
impl ShardRpc for NullShardRpc {
    async fn call(&self, to: &str, _op: ShardOp) -> Result<ShardResult, ShardError> {
        Err(ShardError::Unavailable {
            to: to.to_string(),
            reason: "this transport has no shard path".to_string(),
        })
    }

    fn set_handler(&self, _handler: Arc<dyn ShardHandler>) {}

    fn clear_handler(&self) {}
}

/// Handler map shared by every in-process member of one ring.
#[derive(Default)]
pub struct MemoryShardDir {
    handlers: Mutex<HashMap<String, Arc<dyn ShardHandler>>>,
}

impl MemoryShardDir {
    pub fn new() -> Arc<Self> {
        Arc::new(MemoryShardDir {
            handlers: Mutex::new(HashMap::new()),
        })
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, HashMap<String, Arc<dyn ShardHandler>>> {
        self.handlers.lock().unwrap_or_else(|e| e.into_inner())
    }
}

/// Stack reserved for one in-process shard call. Smaller than this overflows
/// `search_impl`'s future; `std::thread` at this size is the sigaltstack
/// abort #1122 hit.
const SHARD_CALL_STACK_BYTES: usize = 8 * 1024 * 1024;

/// Map a spawn that did not happen into the error the HTTP caller sees.
///
/// The job is dropped. Running it on the caller's stack is the overflow
/// this thread exists to avoid, and dropping it does not write the document.
pub(crate) fn map_shard_spawn_failure<F>(
    to: &str,
    failure: xerj_common::thread_spawn::SpawnFailure<F>,
) -> ShardError {
    let error = failure.error;
    drop(failure.job);
    ShardError::Unavailable {
        to: to.to_string(),
        reason: format!(
            "could not start the shard call: {error}; the node stayed up and this call was not run"
        ),
    }
}

/// In-process [`ShardRpc`]. A call runs the target's handler on a fresh
/// stack and waits for it.
///
/// The handler is not polled on the caller's task. A search coordinator is
/// already inside `search_impl`, whose future is large enough that building
/// a second copy on that same stack overflows. A TCP shard call arrives on
/// its own task; this thread is the in-process equivalent. The caller's
/// index-visibility guard is intentionally not carried across: a TCP handler
/// has none, and an absent guard is how cluster-internal replica stores stay
/// reachable.
///
/// The thread is 8 MiB and is started with [`xerj_common::thread_spawn`], not
/// `std::thread::Builder`. Builder returns `Ok` and then panics in the child
/// when the alternate signal stack cannot be mapped; with `panic = "abort"`
/// that kills the node (#1122). A failed spawn answers the caller and does
/// not run the handler on this stack.
pub struct MemoryShardRpc {
    node_id: String,
    dir: Arc<MemoryShardDir>,
}

impl MemoryShardRpc {
    pub fn new(node_id: impl Into<String>, dir: Arc<MemoryShardDir>) -> Arc<Self> {
        Arc::new(MemoryShardRpc {
            node_id: node_id.into(),
            dir,
        })
    }
}

#[async_trait::async_trait]
impl ShardRpc for MemoryShardRpc {
    async fn call(&self, to: &str, op: ShardOp) -> Result<ShardResult, ShardError> {
        let handler = self.dir.lock().get(to).cloned();
        let Some(handler) = handler else {
            return Err(ShardError::Unavailable {
                to: to.to_string(),
                reason: "no shard handler registered on that member".to_string(),
            });
        };
        let runtime = tokio::runtime::Handle::current();
        let (tx, rx) = tokio::sync::oneshot::channel();
        let target = to.to_string();
        let handle = match xerj_common::thread_spawn::try_spawn_stack(
            "xerj-shard",
            SHARD_CALL_STACK_BYTES,
            move || {
                let result = runtime.block_on(handler.handle(op));
                let _ = tx.send(result);
            },
        ) {
            Ok(handle) => handle,
            Err(failure) => return Err(map_shard_spawn_failure(&target, failure)),
        };
        let received = rx.await.map_err(|_| ShardError::Unavailable {
            to: target,
            reason: "shard call stopped before answering".to_string(),
        });
        // Reap the helper. It has already sent (or dropped the sender);
        // join does not run the handler again.
        drop(handle);
        received
    }

    fn set_handler(&self, handler: Arc<dyn ShardHandler>) {
        self.dir.lock().insert(self.node_id.clone(), handler);
    }

    fn clear_handler(&self) {
        self.dir.lock().remove(&self.node_id);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plan_is_one_primary_per_sorted_member() {
        let plan = primary_shard_plan(&["n3".into(), "n1".into(), "n2".into(), "n1".into()]);
        assert_eq!(
            plan,
            vec![
                ShardAssignment {
                    shard: 0,
                    node_id: "n1".into(),
                    replicas: Vec::new(),
                },
                ShardAssignment {
                    shard: 1,
                    node_id: "n2".into(),
                    replicas: Vec::new(),
                },
                ShardAssignment {
                    shard: 2,
                    node_id: "n3".into(),
                    replicas: Vec::new(),
                },
            ]
        );
    }

    #[test]
    fn replicas_walk_the_sorted_ring_and_cap_at_other_members() {
        let plan = shard_plan(&["n3".into(), "n1".into(), "n2".into()], 1);
        assert_eq!(plan[0].node_id, "n1");
        assert_eq!(plan[0].replicas, vec!["n2".to_string()]);
        assert_eq!(plan[1].replicas, vec!["n3".to_string()]);
        assert_eq!(plan[2].replicas, vec!["n1".to_string()]);

        let full = shard_plan(&["n1".into(), "n2".into(), "n3".into()], 9);
        assert_eq!(full[0].replicas, vec!["n2".to_string(), "n3".to_string()]);
        assert!(!full[0].replicas.iter().any(|id| id == "n1"));
        assert!(shard_plan(&["only".into()], 3)[0].replicas.is_empty());
    }

    #[test]
    fn settings_read_number_of_replicas_or_zero() {
        let nested = serde_json::json!({"index": {"number_of_replicas": "2"}});
        assert_eq!(number_of_replicas_from_settings(&nested), 2);
        let flat = serde_json::json!({"number_of_replicas": 1});
        assert_eq!(number_of_replicas_from_settings(&flat), 1);
        assert_eq!(number_of_replicas_from_settings(&serde_json::json!({})), 0);
        assert_eq!(replica_quorum_acks(0), 0);
        assert_eq!(replica_quorum_acks(1), 1);
        assert_eq!(replica_quorum_acks(2), 1);
        assert_eq!(replica_quorum_acks(3), 2);
        assert_eq!(replica_quorum_acks(4), 2);
        assert_eq!(
            replica_index_name("orders", 1).as_deref(),
            Some(".xerj_replica_orders_1")
        );
        assert!(replica_index_name(&"o".repeat(250), 1).is_none());
    }

    #[test]
    fn schema_without_a_plan_assigns_nothing() {
        assert!(shard_plan_from_schema_json("{}").is_empty());
        assert!(shard_plan_from_schema_json("not-json").is_empty());
        let parsed = shard_plan_from_schema_json(
            r#"{"v":1,"shard_plan":[{"shard":1,"node_id":"n2"},{"shard":0,"node_id":""}]}"#,
        );
        assert_eq!(
            parsed,
            vec![ShardAssignment {
                shard: 1,
                node_id: "n2".into(),
                replicas: Vec::new(),
            }]
        );
    }

    /// #1122: `std::thread::Builder::spawn` panics in the child when the
    /// alternate signal stack cannot be mapped (os error 12), after the
    /// parent has been told the thread exists. The shard call must surface
    /// that as [`ShardError`] and must not run the handler.
    #[test]
    fn a_shard_call_that_cannot_spawn_is_an_error_and_does_not_run() {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::Arc;
        use xerj_common::thread_spawn::{try_spawn_with, Spawn, SpawnedThread};

        struct Refuse;

        impl Spawn for Refuse {
            fn spawn(
                &self,
                _name: &str,
                job: xerj_common::thread_spawn::BoxedJob,
            ) -> std::io::Result<SpawnedThread> {
                drop(job);
                Err(std::io::Error::from_raw_os_error(12))
            }
        }

        let ran = Arc::new(AtomicBool::new(false));
        let job_ran = Arc::clone(&ran);
        let failure = try_spawn_with(&Refuse, true, "xerj-shard", move || {
            job_ran.store(true, Ordering::SeqCst);
        })
        .expect_err("spawn refused");
        let err = super::map_shard_spawn_failure("n2", failure);
        assert!(
            !ran.load(Ordering::SeqCst),
            "handler ran after a failed spawn"
        );
        let text = err.to_string();
        assert!(text.contains("n2"), "{text}");
        assert!(text.contains("could not start the shard call"), "{text}");
        assert!(text.contains("stayed up"), "{text}");
        assert!(
            text.contains("12") || text.contains("Cannot allocate memory"),
            "{text}"
        );
    }

    struct EchoHandler;

    #[async_trait::async_trait]
    impl ShardHandler for EchoHandler {
        async fn handle(&self, op: ShardOp) -> ShardResult {
            ShardResult::http(200, format!("{op:?}"))
        }
    }

    #[tokio::test]
    async fn an_in_process_shard_call_runs_the_handler_on_the_helper_stack() {
        let dir = MemoryShardDir::new();
        let rpc = MemoryShardRpc::new("n1", Arc::clone(&dir));
        rpc.set_handler(Arc::new(EchoHandler));
        let result = rpc
            .call(
                "n1",
                ShardOp::GetDoc {
                    index: "orders".into(),
                    id: "1".into(),
                    source: None,
                    source_includes: None,
                    source_excludes: None,
                    replica: false,
                    shard: 0,
                },
            )
            .await
            .expect("spawn and call");
        assert_eq!(result.status, 200);
        assert!(result.body.contains("orders"), "{}", result.body);
    }
}

//! TCP-based transport for inter-node communication.
//!
//! Every connection is authenticated with the cluster-wide shared secret
//! (HMAC-SHA256, see [`crate::auth`]). There is no unauthenticated mode: the
//! transport cannot be constructed without a validated [`ClusterSecret`].
//!
//! ## Wire format (version 1)
//!
//! ```text
//! receiver → sender   (handshake, sent immediately on accept)
//!   [8]  magic "XERJCLUS"
//!   [1]  wire version (1)
//!   [32] challenge — fresh random bytes, per connection
//!
//! sender → receiver   (hello, exactly once)
//!   [4]  node_id length (u32 BE, ≤ 256)
//!   [n]  node_id (UTF-8)
//!   [32] HMAC tag over (hello-context, version, challenge, node_id)
//!
//! sender → receiver   (message frame, repeated until EOF)
//!   [4]  payload length (u32 BE, ≤ 10 MiB)
//!   [32] HMAC tag over (frame-context, version, challenge, node_id, seq, payload)
//!   [n]  payload — JSON-serialised RaftMessage
//! ```
//!
//! `seq` is the frame's zero-based index within the connection and is never
//! transmitted; both ends count it independently.
//!
//! A frame's tag is verified **before** its payload is handed to the JSON
//! deserialiser, so unauthenticated bytes never reach `serde_json`.
//!
//! ## Wire compatibility
//!
//! This framing is **not** compatible with the pre-authentication format. A
//! node running this version cannot talk to a node running an older one, in
//! either direction: the old sender writes a JSON frame where the new receiver
//! expects to write a challenge first, and the new sender waits for a handshake
//! an old receiver never sends. Upgrading a cluster requires a full stop/start,
//! not a rolling restart.

use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;

use anyhow::{Context, Result};
use async_trait::async_trait;
use rand::RngCore;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{mpsc, Mutex};
use tracing::{debug, info, warn};

use crate::auth::{tags_match, ClusterSecret, CHALLENGE_LEN, TAG_LEN, WIRE_MAGIC, WIRE_VERSION};
use crate::node::ClusterTransport;
use crate::raft::RaftMessage;
use crate::shard::{ShardError, ShardHandler, ShardOp, ShardResult, ShardRpc};

/// Largest accepted frame payload (10 MiB).
const MAX_FRAME_BYTES: usize = 10 * 1024 * 1024;

/// Largest accepted node-id length in the hello header.
const MAX_NODE_ID_BYTES: usize = 256;

/// How long the receiver will wait for a connected peer to complete its hello.
///
/// Without this, a peer that connects and then goes silent pins an accept task
/// (and its buffers) indefinitely — cheap for an attacker, expensive for us.
const HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(10);

/// How long a shard RPC waits for the owner's response, including connect.
///
/// Distinct from [`SEND_TIMEOUT`]: a document index can outlast a heartbeat
/// frame, and a timeout here is a failed write, not a dropped heartbeat.
const SHARD_RPC_TIMEOUT: Duration = Duration::from_secs(10);

/// How long a send may take once the TCP connection is established.
///
/// Authentication makes the sender *read* before it writes (it needs the
/// receiver's challenge), so a peer that accepts connections and then goes
/// silent could otherwise stall the Raft loop indefinitely. The whole
/// post-connect exchange is bounded instead.
const SEND_TIMEOUT: Duration = Duration::from_secs(5);

/// Outbound messages buffered per peer before new ones are dropped (#1168).
///
/// A peer that has not drained its queue in this many messages (hours of
/// heartbeats at the 50 ms rate) is down; Raft retransmits by design — the
/// leader's next AppendEntries resends everything from `next_index` — so
/// dropping is safe where buffering is not.
const OUTBOUND_QUEUE_CAPACITY: usize = 256;

/// Backoff before the next attempt to a peer after `failures` consecutive
/// failed sends: 100 ms, 200, 400, … capped at 6.4 s (#1168).
///
/// Public so the policy is testable from the integration tests: a dead peer
/// costs one immediate attempt, a handful in the first second, then at most
/// one per 6.4 s — never the 20 attempts/s of the pre-fix per-tick retry,
/// and never a `WARN` per tick.
pub fn backoff_after_failures(failures: u32) -> Duration {
    const BASE_MS: u64 = 100;
    const CAP_MS: u64 = 6_400;
    let shift = failures.saturating_sub(1).min(6);
    Duration::from_millis((BASE_MS << shift).min(CAP_MS))
}

/// Length of the receiver's handshake: magic ‖ version ‖ challenge.
const HANDSHAKE_LEN: usize = WIRE_MAGIC.len() + 1 + CHALLENGE_LEN;

// ── Wire helpers ──────────────────────────────────────────────────────────────

/// Write the receiver-side handshake and return the challenge it carried.
async fn write_handshake(stream: &mut TcpStream) -> Result<[u8; CHALLENGE_LEN]> {
    let mut challenge = [0u8; CHALLENGE_LEN];
    rand::rngs::OsRng.fill_bytes(&mut challenge);

    let mut buf = [0u8; HANDSHAKE_LEN];
    buf[..WIRE_MAGIC.len()].copy_from_slice(WIRE_MAGIC);
    buf[WIRE_MAGIC.len()] = WIRE_VERSION;
    buf[WIRE_MAGIC.len() + 1..].copy_from_slice(&challenge);

    stream.write_all(&buf).await.context("write handshake")?;
    stream.flush().await.context("flush handshake")?;
    Ok(challenge)
}

/// Read and validate the receiver's handshake, returning the challenge.
async fn read_handshake(stream: &mut TcpStream) -> Result<[u8; CHALLENGE_LEN]> {
    let mut buf = [0u8; HANDSHAKE_LEN];
    stream
        .read_exact(&mut buf)
        .await
        .context("read handshake")?;

    if &buf[..WIRE_MAGIC.len()] != WIRE_MAGIC {
        anyhow::bail!("peer did not send a xerj cluster handshake (bad magic)");
    }
    let version = buf[WIRE_MAGIC.len()];
    if version != WIRE_VERSION {
        anyhow::bail!(
            "cluster wire version mismatch: peer speaks v{version}, this node speaks v{WIRE_VERSION}"
        );
    }

    let mut challenge = [0u8; CHALLENGE_LEN];
    challenge.copy_from_slice(&buf[WIRE_MAGIC.len() + 1..]);
    Ok(challenge)
}

/// Write the authenticated hello identifying this node.
async fn write_hello(
    stream: &mut TcpStream,
    secret: &ClusterSecret,
    challenge: &[u8; CHALLENGE_LEN],
    node_id: &str,
) -> Result<()> {
    let id = node_id.as_bytes();
    if id.len() > MAX_NODE_ID_BYTES {
        anyhow::bail!("node_id too long: {} bytes", id.len());
    }
    let tag = secret.hello_tag(challenge, node_id);

    stream
        .write_all(&(id.len() as u32).to_be_bytes())
        .await
        .context("write hello length")?;
    stream.write_all(id).await.context("write hello node_id")?;
    stream.write_all(&tag).await.context("write hello tag")?;
    stream.flush().await.context("flush hello")?;
    Ok(())
}

/// Read and authenticate the peer's hello, returning its node id.
async fn read_hello(
    stream: &mut TcpStream,
    secret: &ClusterSecret,
    challenge: &[u8; CHALLENGE_LEN],
) -> Result<String> {
    let mut len_buf = [0u8; 4];
    stream
        .read_exact(&mut len_buf)
        .await
        .context("read hello length")?;
    let len = u32::from_be_bytes(len_buf) as usize;
    if len > MAX_NODE_ID_BYTES {
        anyhow::bail!("hello node_id too large: {len} bytes");
    }

    let mut id_buf = vec![0u8; len];
    stream
        .read_exact(&mut id_buf)
        .await
        .context("read hello node_id")?;
    let mut tag = [0u8; TAG_LEN];
    stream
        .read_exact(&mut tag)
        .await
        .context("read hello tag")?;

    // Authenticate the raw bytes before trusting them as a UTF-8 node id.
    let from = String::from_utf8(id_buf).context("decode hello node_id")?;
    let expected = secret.hello_tag(challenge, &from);
    if !tags_match(&expected, &tag) {
        anyhow::bail!("cluster authentication failed: bad hello tag");
    }
    Ok(from)
}

/// Write a single authenticated frame.
async fn write_frame(
    stream: &mut TcpStream,
    secret: &ClusterSecret,
    challenge: &[u8; CHALLENGE_LEN],
    node_id: &str,
    seq: u64,
    msg: &RaftMessage,
) -> Result<()> {
    let payload = serde_json::to_vec(msg).context("serialize RaftMessage")?;
    if payload.len() > MAX_FRAME_BYTES {
        anyhow::bail!("frame too large to send: {} bytes", payload.len());
    }
    let tag = secret.frame_tag(challenge, node_id, seq, &payload);

    stream
        .write_all(&(payload.len() as u32).to_be_bytes())
        .await
        .context("write frame length")?;
    stream.write_all(&tag).await.context("write frame tag")?;
    stream
        .write_all(&payload)
        .await
        .context("write frame payload")?;
    stream.flush().await.context("flush frame")?;
    Ok(())
}

/// Read, authenticate, and decode a single frame.
///
/// Returns `Ok(None)` on a clean end of stream (the peer closed after its last
/// frame, which is the normal case for the connection-per-send sender).
///
/// The tag is verified before the payload is deserialised, so a forged or
/// tampered frame never reaches `serde_json`.
async fn read_frame(
    stream: &mut TcpStream,
    secret: &ClusterSecret,
    challenge: &[u8; CHALLENGE_LEN],
    from: &str,
    seq: u64,
) -> Result<Option<RaftMessage>> {
    let mut len_buf = [0u8; 4];
    match stream.read_exact(&mut len_buf).await {
        Ok(_) => {}
        Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => return Ok(None),
        Err(e) => return Err(anyhow::Error::new(e).context("read frame length")),
    }
    let len = u32::from_be_bytes(len_buf) as usize;
    if len > MAX_FRAME_BYTES {
        anyhow::bail!("frame too large: {len} bytes");
    }

    let mut tag = [0u8; TAG_LEN];
    stream
        .read_exact(&mut tag)
        .await
        .context("read frame tag")?;
    let mut payload = vec![0u8; len];
    stream
        .read_exact(&mut payload)
        .await
        .context("read frame payload")?;

    let expected = secret.frame_tag(challenge, from, seq, &payload);
    if !tags_match(&expected, &tag) {
        anyhow::bail!("cluster authentication failed: bad frame tag (seq {seq})");
    }

    let msg = serde_json::from_slice(&payload).context("deserialize RaftMessage")?;
    Ok(Some(msg))
}

// ── TcpTransport ─────────────────────────────────────────────────────────────

/// TCP-based transport for inter-node communication.
///
/// Incoming messages arrive via a background listener task and are delivered
/// through an mpsc channel. Outgoing messages are **enqueued** per peer — one
/// bounded queue and one long-lived sender task per peer — so the Raft tick
/// loop never awaits a peer's TCP I/O (#1168). Each attempt still opens a
/// fresh connection (connection pooling is a future optimisation).
///
/// Failure semantics of the outbound path, by design: a send that fails or a
/// queue that is full **drops the message** and backs off
/// ([`backoff_after_failures`]); it never blocks, retries synchronously, or
/// buffers unboundedly. Raft tolerates the drops — heartbeats and log
/// replication are retransmitted from `next_index` on the next tick, and a
/// vote that arrives late is simply ignored. The pre-fix behaviour (inline
/// `await` per send, bounded only by [`SEND_TIMEOUT`]) let one dead peer
/// consume the full 5 s of every heartbeat round while the election timeout
/// is 150–300 ms: the live peers starved, and a 3-node ring killed at its
/// leader churned through a new election every 1.5–11 s indefinitely.
///
/// Every connection is authenticated in both directions of setup: the receiver
/// proves nothing (it holds no identity beyond the secret) but issues a
/// challenge, and the sender proves knowledge of the shared secret on the hello
/// and on every frame.
pub struct TcpTransport {
    /// This node's identifier.
    pub node_id: String,
    /// Address on which this node listens.
    listen_addr: SocketAddr,
    /// Map of peer node_id → socket address.
    peers: Arc<HashMap<String, SocketAddr>>,
    /// Cluster-wide shared secret used to authenticate every frame.
    secret: ClusterSecret,
    /// Receives `(sender_node_id, msg)` from the background listener.
    incoming: Arc<Mutex<mpsc::Receiver<(String, RaftMessage)>>>,
    /// One outbound queue per peer, drained by [`peer_sender_task`]. Built
    /// once in [`TcpTransport::new`] — the peer set is fixed for the
    /// transport's lifetime (membership changes arrive via the Raft log and
    /// will rebuild the transport, #1170).
    outbound: HashMap<String, mpsc::Sender<RaftMessage>>,
    // The sender half is kept alive so the channel is not closed when the
    // background listener task terminates.
    #[allow(dead_code)]
    sender: mpsc::Sender<(String, RaftMessage)>,
    /// Document/search RPC. Shared with the accept loop, which answers
    /// [`RaftMessage::ShardRequest`] on the connection that brought it.
    shard_rpc: Arc<TcpShardRpc>,
}

/// Authenticated request/response for one shard operation.
///
/// Not the Raft outbound queue. Each call opens a connection, writes one
/// request frame, and reads one response frame.
struct TcpShardRpc {
    node_id: String,
    peers: Arc<HashMap<String, SocketAddr>>,
    secret: ClusterSecret,
    handler: std::sync::Mutex<Option<Arc<dyn ShardHandler>>>,
}

impl TcpTransport {
    /// Create a new TCP transport and begin listening for inbound connections.
    ///
    /// `secret` is the cluster-wide shared secret. It is required: there is no
    /// constructor that yields an unauthenticated transport.
    pub async fn new(
        node_id: String,
        listen_addr: SocketAddr,
        peers: HashMap<String, SocketAddr>,
        secret: ClusterSecret,
    ) -> Result<Self> {
        let (tx, rx) = mpsc::channel::<(String, RaftMessage)>(1024);

        // A peer entry naming this node's own address is excluded (#1168).
        // The documented config convention lists the full membership on every
        // node, so a self entry is expected in the input — but a node that
        // sends its own RequestVote back to itself over loopback TCP counts
        // its own vote twice and inflates the wire message rate for nothing.
        let mut self_entry_removed = false;
        let peers: HashMap<String, SocketAddr> = peers
            .into_iter()
            .filter(|(_id, addr)| {
                if *addr == listen_addr {
                    self_entry_removed = true;
                    false
                } else {
                    true
                }
            })
            .collect();
        if self_entry_removed {
            warn!(
                node = %node_id,
                %listen_addr,
                "peer list included this node's own address — excluded (a node sending to \
                 itself double-counts its own vote)"
            );
        }

        // One sender task per peer (#1168). Spawned here, before the listener
        // binds, so a send can be enqueued the moment the transport exists.
        let mut outbound = HashMap::with_capacity(peers.len());
        for (peer_id, addr) in peers.iter() {
            let (peer_tx, peer_rx) = mpsc::channel::<RaftMessage>(OUTBOUND_QUEUE_CAPACITY);
            tokio::spawn(peer_sender_task(
                node_id.clone(),
                peer_id.clone(),
                *addr,
                secret.clone(),
                peer_rx,
            ));
            outbound.insert(peer_id.clone(), peer_tx);
        }

        let peers = Arc::new(peers);
        let shard_rpc = Arc::new(TcpShardRpc {
            node_id: node_id.clone(),
            peers: Arc::clone(&peers),
            secret: secret.clone(),
            handler: std::sync::Mutex::new(None),
        });
        let transport = TcpTransport {
            node_id: node_id.clone(),
            listen_addr,
            peers,
            secret,
            incoming: Arc::new(Mutex::new(rx)),
            outbound,
            sender: tx.clone(),
            shard_rpc,
        };

        // Spawn the background listener task.
        transport.start(tx).await?;

        Ok(transport)
    }

    /// Bind the TCP listener and spawn the accept loop.
    async fn start(&self, tx: mpsc::Sender<(String, RaftMessage)>) -> Result<()> {
        let listener = TcpListener::bind(self.listen_addr)
            .await
            .with_context(|| format!("bind TCP transport on {}", self.listen_addr))?;

        let node_id = self.node_id.clone();
        let secret = self.secret.clone();
        let shard_rpc = Arc::clone(&self.shard_rpc);
        info!(node = %node_id, addr = %self.listen_addr, "TCP transport listening (authenticated)");

        tokio::spawn(async move {
            loop {
                match listener.accept().await {
                    Ok((stream, peer_addr)) => {
                        debug!(node = %node_id, %peer_addr, "Incoming TCP connection");
                        let tx2 = tx.clone();
                        let nid = node_id.clone();
                        let secret = secret.clone();
                        let shard_rpc = Arc::clone(&shard_rpc);
                        tokio::spawn(async move {
                            if let Err(e) = handle_connection(stream, secret, tx2, shard_rpc).await
                            {
                                debug!(node = %nid, %peer_addr, error = %e, "TCP connection closed");
                            }
                        });
                    }
                    Err(e) => {
                        warn!(node = %node_id, error = %e, "TCP accept error");
                    }
                }
            }
        });

        Ok(())
    }

    /// Send a message to a specific peer by node ID, awaiting the full TCP
    /// exchange.
    ///
    /// Opens a fresh TCP connection, completes the authenticated handshake,
    /// writes the frame, then closes. This is the **one-shot** path, bounded
    /// by [`SEND_TIMEOUT`] — used by tests and anywhere a synchronous
    /// delivery result is genuinely needed. The Raft loop does NOT use it:
    /// [`ClusterTransport::send`] enqueues instead (see the struct doc).
    pub async fn send_to(&self, peer_id: &str, msg: &RaftMessage) -> Result<()> {
        let addr = self
            .peers
            .get(peer_id)
            .ok_or_else(|| anyhow::anyhow!("unknown peer: {peer_id}"))?;
        send_frame(&self.node_id, peer_id, *addr, &self.secret, msg).await
    }
}

/// Open a connection to `addr` and deliver one authenticated frame.
///
/// The receiver speaks first: magic, version, challenge. The whole
/// post-connect exchange is bounded by [`SEND_TIMEOUT`] so an
/// accepting-but-silent peer cannot hold the caller indefinitely.
async fn send_frame(
    node_id: &str,
    peer_id: &str,
    addr: SocketAddr,
    secret: &ClusterSecret,
    msg: &RaftMessage,
) -> Result<()> {
    let mut stream = TcpStream::connect(addr)
        .await
        .with_context(|| format!("connect to peer {peer_id} at {addr}"))?;

    tokio::time::timeout(SEND_TIMEOUT, async {
        let challenge = read_handshake(&mut stream).await?;
        write_hello(&mut stream, secret, &challenge, node_id).await?;
        write_frame(&mut stream, secret, &challenge, node_id, 0, msg).await
    })
    .await
    .with_context(|| format!("send to peer {peer_id} at {addr} timed out"))?
    .with_context(|| format!("send to peer {peer_id} at {addr}"))
}

/// Drain one peer's outbound queue, one message per connection attempt,
/// off the Raft loop's critical path (#1168).
///
/// On failure the message is dropped and the next attempt waits
/// [`backoff_after_failures`] — Raft retransmits, so a dropped heartbeat or
/// vote response costs nothing but a tick. Logging is per **state change**
/// (`WARN` when a peer that was up goes down, `INFO` when it answers again),
/// never per attempt: the pre-fix code logged a `WARN` every tick for every
/// dead peer, which is how a 4-minute outage produced thousands of identical
/// lines. The task exits when the queue's sender half is dropped with the
/// transport.
async fn peer_sender_task(
    node_id: String,
    peer_id: String,
    addr: SocketAddr,
    secret: ClusterSecret,
    mut rx: mpsc::Receiver<RaftMessage>,
) {
    let mut failures: u32 = 0;
    let mut down = false;
    let mut retry_at: Option<std::time::Instant> = None;

    while let Some(msg) = rx.recv().await {
        if let Some(deadline) = retry_at {
            if std::time::Instant::now() < deadline {
                continue; // in backoff — drop, the next heartbeat replaces it
            }
        }
        match send_frame(&node_id, &peer_id, addr, &secret, &msg).await {
            Ok(()) => {
                failures = 0;
                retry_at = None;
                if down {
                    down = false;
                    info!(node = %node_id, peer = %peer_id, %addr, "peer reachable again");
                }
            }
            Err(e) => {
                failures += 1;
                retry_at = Some(std::time::Instant::now() + backoff_after_failures(failures));
                if !down {
                    down = true;
                    warn!(
                        node = %node_id,
                        peer = %peer_id,
                        %addr,
                        error = %e,
                        backoff_ms = backoff_after_failures(failures).as_millis() as u64,
                        "peer unreachable — Raft messages to it are dropped until it answers"
                    );
                } else {
                    debug!(node = %node_id, peer = %peer_id, %addr, error = %e, "send still failing");
                }
            }
        }
    }
}

#[async_trait]
impl ShardRpc for TcpShardRpc {
    async fn call(&self, to: &str, op: ShardOp) -> Result<ShardResult, ShardError> {
        if to == self.node_id {
            let handler = self
                .handler
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .clone();
            return match handler {
                Some(handler) => Ok(handler.handle(op).await),
                None => Err(ShardError::Unavailable {
                    to: to.to_string(),
                    reason: "no shard handler registered on this node".to_string(),
                }),
            };
        }
        let Some(addr) = self.peers.get(to).copied() else {
            return Err(ShardError::Unavailable {
                to: to.to_string(),
                reason: "unknown peer".to_string(),
            });
        };
        match tokio::time::timeout(
            SHARD_RPC_TIMEOUT,
            shard_exchange(&self.node_id, to, addr, &self.secret, op),
        )
        .await
        {
            Ok(Ok(result)) => Ok(result),
            Ok(Err(e)) => Err(ShardError::Unavailable {
                to: to.to_string(),
                reason: e.to_string(),
            }),
            Err(_) => Err(ShardError::Timeout { to: to.to_string() }),
        }
    }

    fn set_handler(&self, handler: Arc<dyn ShardHandler>) {
        *self.handler.lock().unwrap_or_else(|e| e.into_inner()) = Some(handler);
    }

    fn clear_handler(&self) {
        *self.handler.lock().unwrap_or_else(|e| e.into_inner()) = None;
    }
}

async fn shard_exchange(
    node_id: &str,
    peer_id: &str,
    addr: SocketAddr,
    secret: &ClusterSecret,
    op: ShardOp,
) -> Result<ShardResult> {
    let mut stream = TcpStream::connect(addr)
        .await
        .with_context(|| format!("connect to shard peer {peer_id} at {addr}"))?;
    let challenge = read_handshake(&mut stream).await?;
    write_hello(&mut stream, secret, &challenge, node_id).await?;
    let request = RaftMessage::ShardRequest { request_id: 1, op };
    write_frame(&mut stream, secret, &challenge, node_id, 0, &request).await?;
    match read_frame(&mut stream, secret, &challenge, peer_id, 0).await? {
        Some(RaftMessage::ShardResponse { result, .. }) => Ok(result),
        Some(_) => anyhow::bail!("peer {peer_id} answered a shard call with a raft frame"),
        None => anyhow::bail!("peer {peer_id} closed before the shard response"),
    }
}

#[async_trait]
impl ClusterTransport for TcpTransport {
    /// Enqueue `msg` on the peer's outbound queue — returns as soon as the
    /// message is accepted for delivery, never after the TCP exchange.
    ///
    /// Errors only for an unknown peer or a full queue (the message is
    /// dropped — see the struct doc for why that is the safe failure mode).
    /// Delivery failures are logged by the per-peer task, not returned here.
    async fn send(&self, to: &str, msg: RaftMessage) -> Result<()> {
        let tx = self
            .outbound
            .get(to)
            .ok_or_else(|| anyhow::anyhow!("unknown peer: {to}"))?;
        match tx.try_send(msg) {
            Ok(()) => Ok(()),
            Err(mpsc::error::TrySendError::Full(_)) => {
                // The peer has not drained OUTBOUND_QUEUE_CAPACITY messages —
                // it is down with the queue still backing up before the
                // backoff deadline. Drop and let retransmission cover it.
                debug!(node = %self.node_id, peer = %to, "outbound queue full — dropping Raft message");
                Ok(())
            }
            Err(mpsc::error::TrySendError::Closed(_)) => {
                anyhow::bail!("peer {to} sender task is gone")
            }
        }
    }

    async fn recv(&self) -> Result<(String, RaftMessage)> {
        let mut rx = self.incoming.lock().await;
        rx.recv()
            .await
            .ok_or_else(|| anyhow::anyhow!("TCP transport incoming channel closed"))
    }

    fn shard_rpc(&self) -> Arc<dyn ShardRpc> {
        Arc::clone(&self.shard_rpc) as Arc<dyn ShardRpc>
    }
}

// ── Connection handler ────────────────────────────────────────────────────────

/// Handle a single inbound TCP connection: issue a challenge, authenticate the
/// hello, then drain authenticated frames into the shared channel.
///
/// Any authentication failure aborts the whole connection — a peer that cannot
/// produce a valid tag does not get to retry on the same socket.
async fn handle_connection(
    mut stream: TcpStream,
    secret: ClusterSecret,
    tx: mpsc::Sender<(String, RaftMessage)>,
    shard_rpc: Arc<TcpShardRpc>,
) -> Result<()> {
    let challenge = write_handshake(&mut stream).await?;

    let from = tokio::time::timeout(
        HANDSHAKE_TIMEOUT,
        read_hello(&mut stream, &secret, &challenge),
    )
    .await
    .context("peer did not complete the cluster handshake in time")??;

    // Read message frames until EOF, a decode error, or an authentication
    // failure. `seq` pins each frame to its position in the connection.
    let mut seq: u64 = 0;
    loop {
        match read_frame(&mut stream, &secret, &challenge, &from, seq).await {
            Ok(Some(RaftMessage::ShardRequest { request_id, op })) => {
                let handler = shard_rpc
                    .handler
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .clone();
                let result = match handler {
                    Some(handler) => handler.handle(op).await,
                    None => ShardResult::http(
                        503,
                        r#"{"error":{"type":"shard_not_ready","reason":"no shard handler registered"},"status":503}"#,
                    ),
                };
                let response = RaftMessage::ShardResponse { request_id, result };
                // seq 0 on the way back: the caller reads the first frame this
                // socket writes. The tag is over this node's id.
                write_frame(
                    &mut stream,
                    &secret,
                    &challenge,
                    &shard_rpc.node_id,
                    0,
                    &response,
                )
                .await?;
                break;
            }
            Ok(Some(msg)) => {
                if tx.send((from.clone(), msg)).await.is_err() {
                    break; // receiver dropped
                }
                seq = seq.saturating_add(1);
            }
            // Clean end of stream — the normal close for a one-frame sender.
            Ok(None) => break,
            Err(e) => {
                // A rejected frame is a security-relevant event, not routine
                // connection churn: log it loudly and drop the connection.
                warn!(peer = %from, error = %e, "cluster frame rejected");
                break;
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The ladder documented on [`backoff_after_failures`]: 100 ms doubling to
    /// a 6.4 s cap. Pinned here because the #1168 churn window (an election
    /// every 1.5–11 s) brackets a 5 s synchronous send timeout — the ladder's
    /// job is to make a dead peer cost ~1 attempt per 6.4 s instead of one
    /// per tick, so a change to these numbers changes the failure story.
    #[test]
    fn backoff_ladder_doubles_then_caps() {
        assert_eq!(backoff_after_failures(1), Duration::from_millis(100));
        assert_eq!(backoff_after_failures(2), Duration::from_millis(200));
        assert_eq!(backoff_after_failures(3), Duration::from_millis(400));
        assert_eq!(backoff_after_failures(4), Duration::from_millis(800));
        assert_eq!(backoff_after_failures(5), Duration::from_millis(1_600));
        assert_eq!(backoff_after_failures(6), Duration::from_millis(3_200));
        assert_eq!(backoff_after_failures(7), Duration::from_millis(6_400));
        assert_eq!(backoff_after_failures(8), Duration::from_millis(6_400));
        assert_eq!(backoff_after_failures(1_000), Duration::from_millis(6_400));
        // failures = 0 is not a state the task reaches (the first failure
        // counts as 1), but saturate rather than panic if it ever does.
        assert_eq!(backoff_after_failures(0), Duration::from_millis(100));
    }
}

//! The file Raft log is what a restarted member and a member that starts
//! with an empty directory use to install committed metadata.
//!
//! Document bytes are not in this log. These tests stop at the metadata
//! state machine: the index and the in-sync set.

use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use async_trait::async_trait;
use tempfile::TempDir;
use xerj_cluster::node::in_memory::{InMemoryBus, InMemoryTransport};
use xerj_cluster::{ApplyEffect, ClusterCommand, ClusterNode, MetadataApplier};

struct RecordingApplier {
    events: Arc<Mutex<Vec<String>>>,
}

#[async_trait]
impl MetadataApplier for RecordingApplier {
    async fn apply_metadata(&self, command: &ClusterCommand) -> ApplyEffect {
        let label = match command.as_metadata() {
            ClusterCommand::CreateIndex { name, .. } => format!("create:{name}"),
            ClusterCommand::SetShardInSync { index, shard, .. } => {
                format!("insync:{index}:{shard}")
            }
            other => format!("other:{other:?}"),
        };
        self.events.lock().expect("events").push(label);
        ApplyEffect::Applied
    }
}

async fn open_node(id: &str, ids: &[&str], bus: &InMemoryBus, dir: &PathBuf) -> ClusterNode {
    let peers: Vec<String> = ids
        .iter()
        .filter(|peer| **peer != id)
        .map(|peer| (*peer).to_string())
        .collect();
    let transport = InMemoryTransport::new(id.to_string(), bus.clone()).await;
    ClusterNode::with_storage(id.to_string(), peers, Box::new(transport), dir)
        .expect("open raft log")
}

async fn boot(ids: &[&str], dirs: &[PathBuf]) -> Vec<ClusterNode> {
    let bus = InMemoryBus::new();
    let mut nodes = Vec::new();
    for (id, dir) in ids.iter().zip(dirs.iter()) {
        nodes.push(open_node(id, ids, &bus, dir).await);
    }
    nodes
}

fn fresh_dirs(n: usize) -> Vec<(TempDir, PathBuf)> {
    (0..n)
        .map(|_| {
            let dir = tempfile::tempdir().expect("tempdir");
            let path = dir.path().to_path_buf();
            (dir, path)
        })
        .collect()
}

async fn pump_until(nodes: &mut [ClusterNode], mut done: impl FnMut(&[ClusterNode]) -> bool) {
    let deadline = Instant::now() + Duration::from_secs(10);
    while Instant::now() < deadline {
        for node in nodes.iter_mut() {
            node.step(Duration::from_millis(5))
                .await
                .expect("raft step");
        }
        if done(nodes) {
            return;
        }
    }
    let summary: Vec<String> = nodes
        .iter()
        .map(|node| {
            format!(
                "{} state={} leader={:?} commit={} log={} indices={:?}",
                node.raft.id,
                node.raft.state(),
                node.leader_id(),
                node.raft.commit_index(),
                node.raft.log_len(),
                node.metadata.indices.keys().collect::<Vec<_>>()
            )
        })
        .collect();
    panic!("timed out: {summary:?}");
}

fn has_orders(node: &ClusterNode) -> bool {
    node.metadata.indices.contains_key("orders")
        && node
            .metadata
            .config
            .get("shard_in_sync:orders:0")
            .map(String::as_str)
            == Some("n2")
}

#[tokio::test]
async fn restart_replays_the_committed_index_and_in_sync_set() {
    let ids = ["n1", "n2", "n3"];
    let held = fresh_dirs(3);
    let paths: Vec<PathBuf> = held.iter().map(|(_, path)| path.clone()).collect();
    let mut nodes = boot(&ids, &paths).await;

    pump_until(&mut nodes, |nodes| {
        nodes.iter().filter(|n| n.is_leader()).count() == 1
    })
    .await;
    let leader = nodes.iter().position(|n| n.is_leader()).expect("leader");
    nodes[leader]
        .propose(ClusterCommand::CreateIndex {
            name: "orders".into(),
            schema_json: "{}".into(),
        })
        .expect("propose create");
    nodes[leader]
        .propose(ClusterCommand::SetShardInSync {
            index: "orders".into(),
            shard: 0,
            nodes: vec!["n2".into()],
        })
        .expect("propose in-sync");
    pump_until(&mut nodes, |nodes| nodes.iter().all(has_orders)).await;
    drop(nodes);

    let mut restored = boot(&ids, &paths).await;
    for node in &restored {
        assert!(
            !node.metadata.indices.contains_key("orders"),
            "opening the log must not apply it before replay"
        );
        assert!(
            node.raft.commit_index() >= 2,
            "commit index must be on disk"
        );
    }
    let events = Arc::new(Mutex::new(Vec::new()));
    for node in &mut restored {
        node.set_applier(Arc::new(RecordingApplier {
            events: Arc::clone(&events),
        }));
        node.replay_committed().await;
        assert!(
            has_orders(node),
            "replay must restore metadata on {}",
            node.raft.id
        );
    }
    let events = events.lock().expect("events").clone();
    assert_eq!(
        events
            .iter()
            .filter(|e| e.as_str() == "create:orders")
            .count(),
        3
    );
    assert_eq!(
        events
            .iter()
            .filter(|e| e.as_str() == "insync:orders:0")
            .count(),
        3
    );
}

#[tokio::test]
async fn an_empty_member_installs_the_leader_log_and_keeps_it_across_restart() {
    let ids = ["n1", "n2", "n3"];
    let held = fresh_dirs(3);
    let paths: Vec<PathBuf> = held.iter().map(|(_, path)| path.clone()).collect();
    let bus = InMemoryBus::new();

    // n3 is in the membership but not started. Two of three is a majority.
    let mut nodes = vec![
        open_node("n1", &ids, &bus, &paths[0]).await,
        open_node("n2", &ids, &bus, &paths[1]).await,
    ];
    pump_until(&mut nodes, |nodes| {
        nodes.iter().filter(|n| n.is_leader()).count() == 1
    })
    .await;
    let leader = nodes.iter().position(|n| n.is_leader()).expect("leader");
    nodes[leader]
        .propose(ClusterCommand::CreateIndex {
            name: "orders".into(),
            schema_json: "{}".into(),
        })
        .expect("propose create");
    nodes[leader]
        .propose(ClusterCommand::SetShardInSync {
            index: "orders".into(),
            shard: 0,
            nodes: vec!["n2".into()],
        })
        .expect("propose in-sync");
    pump_until(&mut nodes, |nodes| nodes.iter().all(has_orders)).await;

    let events = Arc::new(Mutex::new(Vec::new()));
    let mut late = open_node("n3", &ids, &bus, &paths[2]).await;
    late.set_applier(Arc::new(RecordingApplier {
        events: Arc::clone(&events),
    }));
    nodes.push(late);
    pump_until(&mut nodes, |nodes| nodes.iter().all(has_orders)).await;
    assert!(
        nodes[2].raft.log_len() >= 2,
        "the empty member must have stored the leader's entries"
    );
    let caught_up = events.lock().expect("events").clone();
    assert!(
        caught_up.iter().any(|e| e == "create:orders"),
        "the applier runs as the empty member catches up: {caught_up:?}"
    );

    // Drop the late member and reopen only its directory. The other two
    // stay up so a missing disk log cannot be refilled before the assert.
    let late = nodes.pop().expect("n3");
    assert_eq!(late.raft.id, "n3");
    drop(late);
    let mut restarted = open_node("n3", &ids, &bus, &paths[2]).await;
    assert!(
        !restarted.metadata.indices.contains_key("orders"),
        "restart loads the log and does not apply it until replay"
    );
    restarted.replay_committed().await;
    assert!(
        has_orders(&restarted),
        "the caught-up log must restore metadata with the peers stopped from helping"
    );
}

#[tokio::test]
async fn a_compacted_prefix_installs_on_an_empty_member_and_survives_restart() {
    let ids = ["n1", "n2", "n3"];
    let held = fresh_dirs(3);
    let paths: Vec<PathBuf> = held.iter().map(|(_, path)| path.clone()).collect();
    let bus = InMemoryBus::new();
    let mut nodes = vec![
        open_node("n1", &ids, &bus, &paths[0]).await,
        open_node("n2", &ids, &bus, &paths[1]).await,
    ];
    pump_until(&mut nodes, |nodes| {
        nodes.iter().filter(|n| n.is_leader()).count() == 1
    })
    .await;
    let leader = nodes.iter().position(|n| n.is_leader()).expect("leader");
    nodes[leader]
        .propose(ClusterCommand::CreateIndex {
            name: "orders".into(),
            schema_json: "{}".into(),
        })
        .expect("propose create");
    nodes[leader]
        .propose(ClusterCommand::SetShardInSync {
            index: "orders".into(),
            shard: 0,
            nodes: vec!["n2".into()],
        })
        .expect("propose in-sync");
    pump_until(&mut nodes, |nodes| nodes.iter().all(has_orders)).await;

    for node in &mut nodes {
        assert!(node.compact_applied(), "{} did not compact", node.raft.id);
        assert_eq!(
            node.raft.log_len(),
            0,
            "{} still has log entries after compacting the prefix",
            node.raft.id
        );
        assert!(
            node.snapshot_index() >= 2,
            "{} snapshot does not cover both entries",
            node.raft.id
        );
    }
    let leader_id = nodes[leader].raft.id.clone();
    let leader_path = if leader_id == "n1" {
        paths[0].clone()
    } else {
        paths[1].clone()
    };
    let flog = xerj_cluster::raft_log::FileRaftLog::open(&leader_path).expect("reopen log");
    assert_eq!(flog.len(), 0, "raft.log must not keep the compacted prefix");
    assert!(
        flog.snapshot_bytes().is_some(),
        "the prefix has to be in snapshot.meta"
    );
    drop(flog);

    let events = Arc::new(Mutex::new(Vec::new()));
    let mut late = open_node("n3", &ids, &bus, &paths[2]).await;
    late.set_applier(Arc::new(RecordingApplier {
        events: Arc::clone(&events),
    }));
    nodes.push(late);
    pump_until(&mut nodes, |nodes| nodes.iter().all(has_orders)).await;
    let late = nodes.last().expect("n3");
    assert_eq!(late.raft.id, "n3");
    assert!(
        late.snapshot_index() >= 2,
        "n3 must install the snapshot; copying the log cannot work, it was compacted"
    );
    let caught_up = events.lock().expect("events").clone();
    assert!(
        caught_up.iter().any(|e| e == "create:orders"),
        "applying the snapshot must run the create applier: {caught_up:?}"
    );
    assert!(
        caught_up.iter().any(|e| e == "insync:orders:0"),
        "applying the snapshot must run the in-sync applier: {caught_up:?}"
    );

    let leader = nodes.iter().position(|n| n.is_leader()).expect("leader");
    nodes[leader]
        .propose(ClusterCommand::UpdateConfig {
            key: "after".into(),
            value: "1".into(),
        })
        .expect("propose after the snapshot");
    pump_until(&mut nodes, |nodes| {
        nodes
            .iter()
            .all(|node| node.metadata.config.get("after").map(String::as_str) == Some("1"))
    })
    .await;

    let late = nodes.pop().expect("n3");
    assert_eq!(late.raft.id, "n3");
    drop(late);
    let mut restarted = open_node("n3", &ids, &bus, &paths[2]).await;
    restarted.replay_committed().await;
    assert!(
        has_orders(&restarted),
        "restart must restore the compacted prefix from snapshot.meta"
    );
    assert_eq!(
        restarted.metadata.config.get("after").map(String::as_str),
        Some("1"),
        "restart must also replay the entry that landed after the snapshot"
    );
}

//! Metadata commands proposed through a 3-node in-process ring commit on a
//! majority and apply on every member, including after the leader is stopped.

use std::sync::{Arc, Mutex};
use std::time::Duration;

use async_trait::async_trait;
use tokio::sync::watch;
use xerj_cluster::node::in_memory::{InMemoryBus, InMemoryTransport};
use xerj_cluster::runner::ClusterRunner;
use xerj_cluster::{
    ApplyEffect, ClusterCommand, ClusterHandle, ClusterNode, MetadataApplier, ProposeError,
};

struct RecordingApplier {
    events: Arc<Mutex<Vec<String>>>,
}

#[async_trait]
impl MetadataApplier for RecordingApplier {
    async fn apply_metadata(&self, command: &ClusterCommand) -> ApplyEffect {
        let label = match command.as_metadata() {
            ClusterCommand::CreateIndex { name, .. } => format!("create:{name}"),
            ClusterCommand::DeleteIndex { name } => format!("delete:{name}"),
            other => format!("other:{other:?}"),
        };
        self.events.lock().expect("events").push(label);
        ApplyEffect::Applied
    }
}

struct Node {
    shutdown: watch::Sender<bool>,
    handle: ClusterHandle,
    events: Arc<Mutex<Vec<String>>>,
}

async fn boot() -> Vec<Node> {
    let bus = InMemoryBus::new();
    let ids = ["n1", "n2", "n3"];
    let mut nodes = Vec::new();
    for id in ids {
        let peers: Vec<String> = ids
            .iter()
            .filter(|peer| **peer != id)
            .map(|peer| (*peer).to_string())
            .collect();
        let transport = InMemoryTransport::new(id.to_string(), bus.clone()).await;
        let mut node = ClusterNode::new(id.to_string(), peers, Box::new(transport));
        let events = Arc::new(Mutex::new(Vec::new()));
        node.set_applier(Arc::new(RecordingApplier {
            events: Arc::clone(&events),
        }));
        let handle = node.handle();
        let (shutdown, shutdown_rx) = watch::channel(false);
        let mut runner = ClusterRunner::new(node, Duration::from_millis(5), shutdown_rx);
        tokio::spawn(async move {
            runner.run().await;
        });
        nodes.push(Node {
            shutdown,
            handle,
            events,
        });
    }
    nodes
}

async fn wait_leader(nodes: &[Node], dead: &[bool]) -> usize {
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    loop {
        let leaders: Vec<usize> = nodes
            .iter()
            .enumerate()
            .filter(|(i, node)| !dead[*i] && node.handle.is_leader())
            .map(|(i, _)| i)
            .collect();
        if leaders.len() == 1 {
            return leaders[0];
        }
        if std::time::Instant::now() > deadline {
            panic!("timed out waiting for a single leader among the live nodes");
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
}

async fn wait_event(node: &Node, label: &str) {
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    loop {
        if node
            .events
            .lock()
            .expect("events")
            .iter()
            .any(|event| event == label)
        {
            return;
        }
        if std::time::Instant::now() > deadline {
            panic!(
                "timed out waiting for {label}; saw {:?}",
                node.events.lock().expect("events")
            );
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn metadata_replicates_and_survives_leader_loss() {
    let nodes = boot().await;
    let mut dead = [false, false, false];
    let leader = wait_leader(&nodes, &dead).await;
    let follower = (0..3).find(|i| *i != leader).expect("follower");

    nodes[follower]
        .handle
        .propose(ClusterCommand::CreateIndex {
            name: "orders".into(),
            schema_json: r#"{"v":1,"kind":"index_create"}"#.into(),
        })
        .await
        .expect("create commits");

    for node in &nodes {
        wait_event(node, "create:orders").await;
    }

    let _ = nodes[leader].shutdown.send(true);
    dead[leader] = true;
    let next = wait_leader(&nodes, &dead).await;
    assert_ne!(
        next, leader,
        "the stopped node must not stay the only leader"
    );

    let proposer = (0..3).find(|i| !dead[*i] && *i != next).unwrap_or(next);
    nodes[proposer]
        .handle
        .propose(ClusterCommand::DeleteIndex {
            name: "orders".into(),
        })
        .await
        .expect("delete commits after the leader change");

    for (i, node) in nodes.iter().enumerate() {
        if dead[i] {
            continue;
        }
        wait_event(node, "delete:orders").await;
    }

    for node in &nodes {
        let _ = node.shutdown.send(true);
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn propose_without_a_running_node_is_not_acknowledged() {
    let bus = InMemoryBus::new();
    let transport = InMemoryTransport::new("solo".into(), bus).await;
    let node = ClusterNode::new("solo".into(), vec!["other".into()], Box::new(transport));
    let handle = node.handle();
    handle.set_timeout(Duration::from_millis(200));
    // Keep the node so the proposal channel stays open. Nothing steps it,
    // so the command is never appended.
    let _keep = node;

    let err = handle
        .propose(ClusterCommand::CreateIndex {
            name: "orders".into(),
            schema_json: "{}".into(),
        })
        .await
        .expect_err("a write with no running raft loop must not succeed");
    assert!(
        matches!(err, ProposeError::Timeout | ProposeError::NoLeader),
        "{err:?}"
    );
}

//! M5 exit criterion for the persistent Raft log.
//!
//! Given a single-node cluster with `FileRaftLog` wired in, a `propose`
//! call must survive a full `RaftNode` drop + re-open, and the replayed
//! state machine must show the same committed index / log entries.

use std::fs;

use tempfile::tempdir;

use xerj_cluster::raft::{ClusterCommand, LogEntry, RaftMessage, RaftNode};

#[test]
fn single_node_persistent_roundtrip() {
    let dir = tempdir().unwrap();
    let path = dir.path().to_path_buf();

    // ── Phase 1: fresh node, elect, propose 50 commands ──────────────
    {
        let mut node = RaftNode::with_storage("n1".into(), vec![], &path).unwrap();

        // Single-node cluster — fire one election and this node becomes
        // leader because it votes for itself and there are no peers.
        node.force_election_timeout();
        let _ = node.tick();
        assert!(node.is_leader(), "single-node cluster must elect self");

        for i in 0..50 {
            let cmd = ClusterCommand::CreateIndex {
                name: format!("idx-{i}"),
                schema_json: "{}".into(),
            };
            node.propose(cmd).unwrap();
        }

        // Single-node clusters commit immediately in propose().
        assert_eq!(node.commit_index(), 50);
        assert_eq!(node.log_len(), 50);
    }

    // The file must have been fsynced to disk.
    let log_path = path.join("raft.log");
    assert!(log_path.exists(), "raft.log must exist after propose+fsync");
    let commit_path = path.join("commit.meta");
    assert!(commit_path.exists(), "commit.meta must exist");

    let size_after_phase1 = fs::metadata(&log_path).unwrap().len();
    assert!(size_after_phase1 > 0, "raft.log must be non-empty");

    // ── Phase 2: reopen and verify replay ────────────────────────────
    {
        let node2 = RaftNode::with_storage("n1".into(), vec![], &path).unwrap();
        assert_eq!(
            node2.log_len(),
            50,
            "all 50 entries must replay from disk on restart"
        );
        assert_eq!(
            node2.commit_index(),
            50,
            "commit_index must survive restart"
        );
        assert_eq!(
            node2.current_term(),
            1,
            "current_term must be at least the term of the replayed entries"
        );
    }

    // ── Phase 3: reopening must be idempotent — size stays identical
    let size_after_phase2 = fs::metadata(&log_path).unwrap().len();
    assert_eq!(
        size_after_phase1, size_after_phase2,
        "reopening the log must not re-serialize existing entries"
    );
}

fn entry(term: u64, index: u64, name: &str) -> LogEntry {
    LogEntry {
        term,
        index,
        command: ClusterCommand::CreateIndex {
            name: name.to_string(),
            schema_json: "{}".into(),
        },
    }
}

fn append_ok(replies: &[xerj_cluster::raft::OutboundMessage]) -> bool {
    replies.iter().any(|out| {
        matches!(
            out.msg,
            RaftMessage::AppendEntriesResponse { success: true, .. }
        )
    })
}

fn vote_granted(replies: &[xerj_cluster::raft::OutboundMessage]) -> bool {
    replies.iter().any(|out| {
        matches!(
            out.msg,
            RaftMessage::RequestVoteResponse {
                vote_granted: true,
                ..
            }
        )
    })
}

/// A follower has to store entries before it says yes. Reopening must not
/// bring back a tail the leader already replaced.
#[test]
fn follower_persists_appended_entries_and_drops_a_replaced_tail() {
    let dir = tempdir().unwrap();
    let path = dir.path();
    let mut node = RaftNode::with_storage("n2".into(), vec!["n1".into()], path).unwrap();

    let replies = node.handle_message(RaftMessage::AppendEntries {
        term: 1,
        leader_id: "n1".into(),
        prev_log_index: 0,
        prev_log_term: 0,
        entries: vec![entry(1, 1, "a"), entry(1, 2, "b"), entry(1, 3, "c")],
        leader_commit: 1,
    });
    assert!(append_ok(&replies), "first append must be stored");
    assert_eq!(node.commit_index(), 1);
    assert_eq!(node.log_len(), 3);

    let replies = node.handle_message(RaftMessage::AppendEntries {
        term: 2,
        leader_id: "n1".into(),
        prev_log_index: 1,
        prev_log_term: 1,
        entries: vec![entry(2, 2, "b2")],
        leader_commit: 2,
    });
    assert!(append_ok(&replies), "conflicting tail must be replaced");
    assert_eq!(node.entry_term(2), Some(2));
    assert_eq!(node.entry_term(3), None);

    drop(node);
    let node = RaftNode::with_storage("n2".into(), vec!["n1".into()], path).unwrap();
    assert_eq!(
        node.log_len(),
        2,
        "index 3 must not come back from the file"
    );
    assert_eq!(node.entry_term(1), Some(1));
    assert_eq!(node.entry_term(2), Some(2));
    assert_eq!(node.entry_term(3), None);
    assert_eq!(node.commit_index(), 2);
}

/// A vote that was granted has to stick across a restart in the same term.
#[test]
fn a_restart_does_not_grant_a_second_vote_in_the_same_term() {
    let dir = tempdir().unwrap();
    let path = dir.path();
    let mut node =
        RaftNode::with_storage("n1".into(), vec!["n2".into(), "n3".into()], path).unwrap();
    let replies = node.handle_message(RaftMessage::RequestVote {
        term: 1,
        candidate_id: "n2".into(),
        last_log_index: 0,
        last_log_term: 0,
    });
    assert!(vote_granted(&replies), "first vote in the term is granted");

    drop(node);
    let mut node =
        RaftNode::with_storage("n1".into(), vec!["n2".into(), "n3".into()], path).unwrap();
    assert_eq!(node.current_term(), 1);
    let replies = node.handle_message(RaftMessage::RequestVote {
        term: 1,
        candidate_id: "n3".into(),
        last_log_index: 0,
        last_log_term: 0,
    });
    assert!(
        !vote_granted(&replies),
        "a second candidate must not get a vote in this term"
    );
    let replies = node.handle_message(RaftMessage::RequestVote {
        term: 1,
        candidate_id: "n2".into(),
        last_log_index: 0,
        last_log_term: 0,
    });
    assert!(
        vote_granted(&replies),
        "the original candidate is still the vote"
    );
}

//! Integration tests for region management (Milestone 3.5).

use std::collections::HashMap;

use xerj_cluster::regions::{Region, RegionManager};
use xerj_cluster::router::{jump_hash, ShardRouter};

// ── Helpers ───────────────────────────────────────────────────────────────────

fn nodes(names: &[&str]) -> Vec<String> {
    names.iter().map(|s| s.to_string()).collect()
}

// ── Test 1: Region split ──────────────────────────────────────────────────────

/// A region that crosses a size threshold should split into two.
#[test]
fn test_region_split() {
    // Low threshold so our test data triggers it.
    let mut mgr = RegionManager::with_thresholds(500, 1_000_000, 100);
    let regions = mgr.create_initial_regions("products", 1, &nodes(&["n1", "n2"]));
    let id = regions[0].id;

    // Push it over the size threshold.
    mgr.update_region_stats(id, 600, 10); // 600 bytes > 500 threshold

    assert_eq!(
        mgr.regions_to_split().len(),
        1,
        "one region should need splitting"
    );

    let (left, right) = mgr.split_region(id).expect("split should succeed");

    // Original region is gone.
    assert!(
        mgr.regions().iter().all(|r| r.id != id),
        "original region should be removed after split"
    );

    // Two new regions now exist.
    assert!(
        mgr.regions().iter().any(|r| r.id == left.id),
        "left half should exist"
    );
    assert!(
        mgr.regions().iter().any(|r| r.id == right.id),
        "right half should exist"
    );

    // Key ranges are contiguous.
    assert_eq!(
        left.end_key, right.start_key,
        "left end_key must equal right start_key"
    );

    // Stats are approximately halved.
    assert_eq!(
        left.size_bytes + right.size_bytes,
        600,
        "stats should sum to original"
    );
    assert_eq!(left.doc_count + right.doc_count, 10);
}

/// A region that only exceeds the doc_count threshold should also split.
#[test]
fn test_region_split_by_doc_count() {
    let mut mgr = RegionManager::with_thresholds(1_000_000_000, 50, 0);
    let regions = mgr.create_initial_regions("logs", 1, &nodes(&["n1"]));
    let id = regions[0].id;

    mgr.update_region_stats(id, 100, 60); // 60 docs > threshold 50

    assert_eq!(mgr.regions_to_split().len(), 1);

    let (left, right) = mgr.split_region(id).expect("split");
    assert!(left.doc_count + right.doc_count <= 60);
}

/// Split preserves the leader and replica node assignments.
#[test]
fn test_region_split_preserves_assignment() {
    let mut mgr = RegionManager::with_thresholds(100, 100, 0);
    let ns = nodes(&["n1", "n2", "n3"]);
    let regions = mgr.create_initial_regions("idx", 1, &ns);
    let id = regions[0].id;
    let leader = regions[0].leader_node.clone();

    mgr.update_region_stats(id, 200, 0);
    let (left, right) = mgr.split_region(id).expect("split");

    assert_eq!(left.leader_node, leader);
    assert_eq!(right.leader_node, leader);
}

// ── Test 2: Region merge ──────────────────────────────────────────────────────

/// Two small adjacent regions should merge into one.
#[test]
fn test_region_merge() {
    // Merge threshold: 10 MiB. Both regions are empty → both below threshold.
    let mut mgr = RegionManager::with_thresholds(1_000_000_000, 1_000_000_000, 10 * 1024 * 1024);
    let regions = mgr.create_initial_regions("orders", 2, &nodes(&["n1", "n2"]));
    let id_a = regions[0].id;
    let id_b = regions[1].id;

    // Confirm they appear in the merge candidates.
    assert_eq!(mgr.regions_to_merge().len(), 1);

    let merged = mgr.merge_regions(id_a, id_b).expect("merge should succeed");

    // Original regions removed.
    assert!(
        mgr.regions().iter().all(|r| r.id != id_a),
        "region a should be removed"
    );
    assert!(
        mgr.regions().iter().all(|r| r.id != id_b),
        "region b should be removed"
    );

    // Merged region exists.
    assert!(mgr.regions().iter().any(|r| r.id == merged.id));

    // The merged region spans the full key range.
    assert_eq!(
        merged.start_key, "",
        "merged start should be left-unbounded"
    );
    assert_eq!(merged.end_key, "", "merged end should be right-unbounded");

    // Stats are summed (both were 0 here).
    assert_eq!(merged.size_bytes, 0);
    assert_eq!(merged.doc_count, 0);
}

/// Non-adjacent regions cannot be merged.
#[test]
fn test_region_merge_non_adjacent_fails() {
    let mut mgr = RegionManager::with_thresholds(u64::MAX, u64::MAX, 0);
    let regions = mgr.create_initial_regions("idx", 3, &nodes(&["n1"]));
    let id_first = regions[0].id;
    let id_last = regions[2].id;

    let result = mgr.merge_regions(id_first, id_last);
    assert!(
        result.is_err(),
        "merging non-adjacent regions should return Err"
    );
}

/// Merging accumulates stats from both regions.
#[test]
fn test_region_merge_accumulates_stats() {
    let mut mgr = RegionManager::with_thresholds(u64::MAX, u64::MAX, u64::MAX);
    let regions = mgr.create_initial_regions("metrics", 2, &nodes(&["n1"]));
