    assert_eq!(decoded.end_key, "xyz");
    assert_eq!(decoded.leader_node, "n1");
    assert_eq!(decoded.replica_nodes.len(), 2);
    assert_eq!(decoded.size_bytes, 1_024);
    assert_eq!(decoded.doc_count, 100);
}

//! Integration tests for WAL replication (Milestone 3.4).

use std::collections::HashSet;
use std::sync::Arc;

use async_trait::async_trait;
use xerj_cluster::node::in_memory::{InMemoryBus, InMemoryTransport};
use xerj_cluster::node::ClusterTransport;
