/// A transport that succeeds for whitelisted node IDs and errors for all others.
struct PartialTransport {
    reachable: HashSet<String>,
}

impl PartialTransport {
    fn new(reachable: &[&str]) -> Self {
        PartialTransport {
            reachable: reachable.iter().map(|s| s.to_string()).collect(),
        }
    }
}

#[async_trait]
impl ClusterTransport for PartialTransport {
    async fn send(&self, to: &str, _msg: RaftMessage) -> anyhow::Result<()> {
        if self.reachable.contains(to) {
            Ok(())
        } else {
            Err(anyhow::anyhow!(
                "node {to} is unreachable (simulated failure)"
            ))
        }
    }

    async fn recv(&self) -> anyhow::Result<(String, RaftMessage)> {
        futures::future::pending().await
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

fn make_entry(index: &str, shard: u32, seq_no: u64) -> ReplicationEntry {
    ReplicationEntry {
        index: index.to_string(),
        shard,
        seq_no,
        operation: ReplicationOp::Index {
            doc_id: format!("doc-{seq_no}"),
            source_json: r#"{"title":"test document"}"#.to_string(),
        },
    }
}

fn router_with_replicas(index: &str, primary: &str, replicas: &[&str]) -> Arc<ShardRouter> {
    let mut router = ShardRouter::new(8);
    router.assign(index, 0, primary);
    for rep in replicas {
        router.add_replica(index, 0, rep);
    }
    Arc::new(router)
}

// ── Test 1: Async replication ─────────────────────────────────────────────────

/// Fire-and-forget: returns immediately without waiting for replica ACKs.
#[tokio::test]
async fn test_async_replication() {
    let bus = InMemoryBus::new();
    let transport: Arc<dyn ClusterTransport> =
        Arc::new(InMemoryTransport::new("primary".to_string(), bus.clone()).await);
    let _replica = InMemoryTransport::new("replica-1".to_string(), bus.clone()).await;

    let router = router_with_replicas("idx", "primary", &["replica-1"]);
    let replicator = WalReplicator::new(
        ReplicationMode::Async,
        transport,
        router,
        "primary".to_string(),
    );

    let result = replicator
        .replicate(make_entry("idx", 0, 1))
        .await
        .expect("async should succeed");

    // Async mode never waits — ack_count is always 0.
    assert_eq!(result.ack_count, 0, "async mode should not count ACKs");
}

// ── Test 2: Sync replication ──────────────────────────────────────────────────

/// Sync mode waits for the configured number of replicas to ACK.
#[tokio::test]
async fn test_sync_replication() {
    // Both replicas are reachable.
    let transport: Arc<dyn ClusterTransport> =
        Arc::new(PartialTransport::new(&["replica-1", "replica-2"]));
    let router = router_with_replicas("idx", "primary", &["replica-1", "replica-2"]);

    let replicator = WalReplicator::new(
        ReplicationMode::Sync { min_replicas: 2 },
        transport,
        router,
        "primary".to_string(),
    );

    let result = replicator
        .replicate(make_entry("idx", 0, 5))
        .await
        .expect("sync should succeed");

    assert_eq!(result.ack_count, 2, "both replicas must ACK");
}

/// Sync mode returns an error when fewer replicas are reachable than required.
#[tokio::test]
async fn test_sync_replication_insufficient_replicas() {
    // Only replica-1 is reachable; replica-2 will return an error.
    let transport: Arc<dyn ClusterTransport> = Arc::new(PartialTransport::new(&["replica-1"]));
    let router = router_with_replicas("idx", "primary", &["replica-1", "replica-2"]);

    let replicator = WalReplicator::new(
        ReplicationMode::Sync { min_replicas: 2 },
        transport,
        router,
        "primary".to_string(),
    );

    let err = replicator
        .replicate(make_entry("idx", 0, 7))
        .await
        .expect_err("should fail with insufficient replicas");

    assert!(
        matches!(
            err,
            ReplicationError::InsufficientReplicas { needed: 2, got: 1 }
        ),
        "unexpected error: {err}"
    );
}

// ── Test 3: Quorum replication ────────────────────────────────────────────────

/// Quorum mode: majority (2 of 3) of replicas must ACK.
#[tokio::test]
async fn test_quorum_replication() {
    // replica-3 will error — only 2 of 3 reachable.
    let transport: Arc<dyn ClusterTransport> =
        Arc::new(PartialTransport::new(&["replica-1", "replica-2"]));

    let mut router = ShardRouter::new(8);
    router.assign("idx", 0, "primary");
    router.add_replica("idx", 0, "replica-1");
    router.add_replica("idx", 0, "replica-2");
    router.add_replica("idx", 0, "replica-3"); // unreachable
    let router = Arc::new(router);

    let replicator = WalReplicator::new(
        ReplicationMode::Quorum,
        transport,
        router,
        "primary".to_string(),
    );

    let result = replicator
        .replicate(make_entry("idx", 0, 10))
        .await
        .expect("quorum should succeed with 2/3 replicas");

    // 2 of 3 replicas ACKed → majority (floor(3/2)+1 = 2) satisfied.
    assert_eq!(result.ack_count, 2, "2 of 3 replicas should ACK");
}

/// Quorum fails when fewer than majority respond.
#[tokio::test]
async fn test_quorum_replication_fails_below_majority() {
    // Only 1 of 3 replicas is reachable.
    let transport: Arc<dyn ClusterTransport> = Arc::new(PartialTransport::new(&["replica-1"]));

    let mut router = ShardRouter::new(8);
    router.assign("idx", 0, "primary");
    router.add_replica("idx", 0, "replica-1");
    router.add_replica("idx", 0, "replica-2");
    router.add_replica("idx", 0, "replica-3");
    let router = Arc::new(router);

    let replicator = WalReplicator::new(
        ReplicationMode::Quorum,
        transport,
        router,
        "primary".to_string(),
    );

    let err = replicator
        .replicate(make_entry("idx", 0, 11))
        .await
        .expect_err("quorum should fail");

    assert!(
        matches!(err, ReplicationError::QuorumNotReached { .. }),
        "expected QuorumNotReached, got: {err}"
    );
}

// ── Test 4: ReplicationEntry serialisation ────────────────────────────────────

/// Round-trip serialise every combination of ReplicationEntry + ReplicationOp.
#[test]
fn test_replication_entry_serialization() {
    let entries: Vec<ReplicationEntry> = vec![
        ReplicationEntry {
            index: "products".to_string(),
            shard: 0,
            seq_no: 1,
            operation: ReplicationOp::Index {
                doc_id: "prod-1".to_string(),
                source_json: r#"{"name":"widget","price":9.99}"#.to_string(),
            },
        },
        ReplicationEntry {
            index: "orders".to_string(),
            shard: 3,
            seq_no: 999,
            operation: ReplicationOp::Delete {
                doc_id: "order-42".to_string(),
            },
        },
        // Unicode content should survive the round-trip.
        ReplicationEntry {
            index: "интернет".to_string(),
            shard: 7,
            seq_no: u64::MAX,
            operation: ReplicationOp::Index {
                doc_id: "doc-\u{1F600}".to_string(),
                source_json: r#"{"emoji":"😀"}"#.to_string(),
            },
        },
    ];

    for entry in &entries {
        let json = serde_json::to_string(entry).expect("serialize entry");
        let decoded: ReplicationEntry = serde_json::from_str(&json).expect("deserialize entry");

        assert_eq!(entry.index, decoded.index, "index mismatch");
        assert_eq!(entry.shard, decoded.shard, "shard mismatch");
        assert_eq!(entry.seq_no, decoded.seq_no, "seq_no mismatch");

        match (&entry.operation, &decoded.operation) {
            (
                ReplicationOp::Index {
                    doc_id: a,
                    source_json: sa,
                },
                ReplicationOp::Index {
                    doc_id: b,
                    source_json: sb,
                },
            ) => {
                assert_eq!(a, b, "doc_id mismatch in Index");
                assert_eq!(sa, sb, "source_json mismatch");
            }
            (ReplicationOp::Delete { doc_id: a }, ReplicationOp::Delete { doc_id: b }) => {
                assert_eq!(a, b, "doc_id mismatch in Delete");
            }
            _ => panic!("operation variant changed after round-trip"),
        }
    }
}

/// ReplicationMode serialises for all variants.
#[test]
fn test_replication_mode_serialization() {
    let modes = vec![
        ReplicationMode::Async,
        ReplicationMode::Sync { min_replicas: 1 },
        ReplicationMode::Sync { min_replicas: 3 },
        ReplicationMode::Quorum,
    ];
    for mode in &modes {
        let json = serde_json::to_string(mode).expect("serialize mode");
        let _: ReplicationMode = serde_json::from_str(&json).expect("deserialize mode");
    }
}

// ── Test 5: No replicas — all modes succeed vacuously ────────────────────────

/// When there are no replicas configured, all modes should succeed without error.
#[tokio::test]
async fn test_replication_no_replicas() {
    // Transport that always succeeds (no replicas to send to anyway).
    let transport: Arc<dyn ClusterTransport> = Arc::new(PartialTransport::new(&[]));

    let mut router = ShardRouter::new(8);
    router.assign("solo", 0, "primary");
    let router = Arc::new(router);

    for mode in [
        ReplicationMode::Async,
        ReplicationMode::Sync { min_replicas: 0 },
        ReplicationMode::Quorum,
    ] {
        let replicator = WalReplicator::new(
            mode.clone(),
            Arc::clone(&transport),
            Arc::clone(&router),
            "primary".to_string(),
        );
        let result = replicator.replicate(make_entry("solo", 0, 1)).await;
        assert!(
            result.is_ok(),
            "no-replica {mode:?} should succeed: {result:?}"
        );
    }
}

//! Adversarial tests for cluster control-frame authentication (issue #75).
//!
//! Each test drives the real `TcpTransport` listener with a hand-rolled client
//! so it can lie about the things an attacker on the cluster port would lie
//! about: no secret, the wrong secret, a replayed capture, a tampered payload.

use std::collections::HashMap;
use std::net::SocketAddr;
use std::time::Duration;

use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpStream;

use xerj_cluster::auth::{ClusterSecret, CHALLENGE_LEN, WIRE_MAGIC, WIRE_VERSION};
use xerj_cluster::node::ClusterTransport;
use xerj_cluster::raft::RaftMessage;
use xerj_cluster::transport::TcpTransport;

const SECRET: &str = "cluster-secret-for-tests-0123456789";
const OTHER_SECRET: &str = "a-completely-different-secret-9876";

/// How long a test waits before concluding "the listener did not deliver this".
const REJECT_WINDOW: Duration = Duration::from_millis(400);

// ── Helpers ───────────────────────────────────────────────────────────────────

async fn free_addr() -> SocketAddr {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    listener.local_addr().unwrap()
}

fn secret(s: &str) -> ClusterSecret {
    ClusterSecret::new(s).expect("valid test secret")
}

/// `free_addr` yields a port whose listener is already dropped, so between
/// that drop and `TcpTransport::new`'s own bind another parallel test (or any
/// process on the CI runner) can take the port — observed as a spurious
/// `Address already in use` failure in `Build + Test`. Retry a bounded number
/// of times so a lost race picks a fresh port instead of failing the test.
const BIND_ATTEMPTS: usize = 20;

fn is_addr_in_use(err: &anyhow::Error) -> bool {
    err.chain().any(|cause| {
        cause
            .downcast_ref::<std::io::Error>()
            .is_some_and(|io| io.kind() == std::io::ErrorKind::AddrInUse)
    })
}

/// Bind a transport on a free port, retrying the pick-and-bind on `AddrInUse`.
/// Returns the transport and the address it actually bound.
async fn bind_transport(
    node_id: &str,
    peers: HashMap<String, SocketAddr>,
    s: &str,
) -> (TcpTransport, SocketAddr) {
    let mut last_err = None;
    for _ in 0..BIND_ATTEMPTS {
        let addr = free_addr().await;
        match TcpTransport::new(node_id.to_string(), addr, peers.clone(), secret(s)).await {
            Ok(t) => return (t, addr),
            Err(e) if is_addr_in_use(&e) => last_err = Some(e),
            Err(e) => panic!("bind test transport: {e:?}"),
        }
    }
    panic!("no free port after {BIND_ATTEMPTS} attempts: {last_err:?}")
}

/// Start a listening transport with no peers (receive-only).
async fn listener(s: &str) -> (TcpTransport, SocketAddr) {
    bind_transport("receiver", HashMap::new(), s).await
}

fn sample_msg() -> RaftMessage {
    RaftMessage::RequestVote {
        term: 7,
        candidate_id: "attacker".to_string(),
        last_log_index: 0,
        last_log_term: 0,
    }
}

/// Connect and read the receiver's handshake, returning the challenge it issued.
async fn connect_and_handshake(addr: SocketAddr) -> (TcpStream, [u8; CHALLENGE_LEN]) {
    let mut stream = TcpStream::connect(addr).await.expect("connect");
    let mut buf = [0u8; 8 + 1 + CHALLENGE_LEN];
    stream.read_exact(&mut buf).await.expect("read handshake");
    assert_eq!(&buf[..8], WIRE_MAGIC, "handshake magic");
    assert_eq!(buf[8], WIRE_VERSION, "handshake version");
    let mut challenge = [0u8; CHALLENGE_LEN];
    challenge.copy_from_slice(&buf[9..]);
    (stream, challenge)
}

/// The authenticated hello a legitimate sender writes first.
fn hello_bytes(s: &ClusterSecret, node_id: &str, challenge: &[u8; CHALLENGE_LEN]) -> Vec<u8> {
    let mut out = Vec::new();
    let id = node_id.as_bytes();
    out.extend_from_slice(&(id.len() as u32).to_be_bytes());
    out.extend_from_slice(id);
    out.extend_from_slice(&s.hello_tag(challenge, node_id));
    out
}

/// One authenticated message frame at position `seq`.
fn frame_bytes(
    s: &ClusterSecret,
    node_id: &str,
    challenge: &[u8; CHALLENGE_LEN],
    seq: u64,
    msg: &RaftMessage,
) -> Vec<u8> {
    let payload = serde_json::to_vec(msg).unwrap();
    let mut out = Vec::new();
    out.extend_from_slice(&(payload.len() as u32).to_be_bytes());
    out.extend_from_slice(&s.frame_tag(challenge, node_id, seq, &payload));
    out.extend_from_slice(&payload);
    out
}

/// Everything a legitimate sender writes for a single message: hello ‖ frame 0.
fn client_bytes(
    s: &ClusterSecret,
    node_id: &str,
    challenge: &[u8; CHALLENGE_LEN],
    msg: &RaftMessage,
) -> Vec<u8> {
    let mut out = hello_bytes(s, node_id, challenge);
    out.extend_from_slice(&frame_bytes(s, node_id, challenge, 0, msg));
    out
}

/// Assert the transport delivers nothing within the rejection window.
async fn assert_no_delivery(t: &TcpTransport, what: &str) {
    let got = tokio::time::timeout(REJECT_WINDOW, t.recv()).await;
    assert!(
        got.is_err(),
        "{what}: transport accepted a frame it must have rejected: {:?}",
        got.map(|r| r.map(|(from, m)| (from, format!("{m:?}"))))
    );
}

// ── Tests ─────────────────────────────────────────────────────────────────────

/// Baseline: two transports sharing a secret still talk to each other.
#[tokio::test]
async fn authenticated_peers_exchange_messages() {
    // Bind b first: its recorded address is one that is actually bound, not
    // one that was merely free a moment ago.
    let (b, addr_b) = listener(SECRET).await;

    let mut peers_a = HashMap::new();
    peers_a.insert("node-b".to_string(), addr_b);

    let (a, _addr_a) = bind_transport("node-a", peers_a, SECRET).await;

    a.send_to("node-b", &sample_msg()).await.expect("send");

    let (from, msg) = tokio::time::timeout(Duration::from_secs(2), b.recv())
        .await
        .expect("timed out")
        .expect("recv");
    assert_eq!(from, "node-a");
    assert!(matches!(msg, RaftMessage::RequestVote { term: 7, .. }));
}

/// An unauthenticated client speaking the *old* pre-#75 wire format —
/// `[len][node_id]` then `[len][json]`, no tags — is rejected.
///
/// This is the exact shape of the issue: anyone who could reach the cluster
/// port used to be able to inject Raft control messages this way.
#[tokio::test]
async fn legacy_unauthenticated_client_is_rejected() {
    let (t, addr) = listener(SECRET).await;

    let mut stream = TcpStream::connect(addr).await.unwrap();
    // The legacy client writes immediately and never reads the challenge.
    let id = b"evil-node";
    stream
        .write_all(&(id.len() as u32).to_be_bytes())
        .await
        .unwrap();
    stream.write_all(id).await.unwrap();
    let payload = serde_json::to_vec(&sample_msg()).unwrap();
    stream
        .write_all(&(payload.len() as u32).to_be_bytes())
        .await
        .unwrap();
    stream.write_all(&payload).await.unwrap();
    stream.flush().await.unwrap();

    assert_no_delivery(&t, "legacy unauthenticated client").await;
}

/// A client that completes the handshake but holds the wrong secret is rejected
/// at the hello — it never gets to send a frame that counts.
#[tokio::test]
async fn wrong_secret_is_rejected() {
    let (t, addr) = listener(SECRET).await;

    let (mut stream, challenge) = connect_and_handshake(addr).await;
    let bytes = client_bytes(
        &secret(OTHER_SECRET),
        "evil-node",
        &challenge,
        &sample_msg(),
    );
    stream.write_all(&bytes).await.unwrap();
    stream.flush().await.unwrap();

    assert_no_delivery(&t, "wrong secret").await;
}

/// A frame captured off the wire cannot be replayed: the receiver issues a
/// fresh challenge per connection, so the captured tags no longer verify.
#[tokio::test]
async fn captured_frame_cannot_be_replayed() {
    let (t, addr) = listener(SECRET).await;

    // Connection 1: a legitimate, correctly-signed exchange. Keep the bytes.
    let (mut stream, challenge) = connect_and_handshake(addr).await;
    let captured = client_bytes(&secret(SECRET), "node-a", &challenge, &sample_msg());
    stream.write_all(&captured).await.unwrap();
    stream.flush().await.unwrap();

    let (from, _) = tokio::time::timeout(Duration::from_secs(2), t.recv())
        .await
        .expect("legitimate frame timed out")
        .expect("recv");
    assert_eq!(from, "node-a");
    drop(stream);

    // Connection 2: replay the captured bytes verbatim.
    let (mut replay, _new_challenge) = connect_and_handshake(addr).await;
    replay.write_all(&captured).await.unwrap();
    replay.flush().await.unwrap();

    assert_no_delivery(&t, "replayed capture").await;
}

/// Swapping the payload under an otherwise-valid tag is rejected.
///
/// The substituted payload is *perfectly well-formed* Raft JSON — a vote
/// request at a much higher term, which a leader would honour by stepping
/// down — so nothing but the MAC can catch it.
#[tokio::test]
async fn payload_swapped_under_a_valid_tag_is_rejected() {
    let (t, addr) = listener(SECRET).await;

    let (mut stream, challenge) = connect_and_handshake(addr).await;
    let s = secret(SECRET);

    let forged = RaftMessage::RequestVote {
        term: 9_999,
        candidate_id: "attacker".to_string(),
        last_log_index: 0,
        last_log_term: 0,
    };
    let forged_payload = serde_json::to_vec(&forged).unwrap();
    // The tag the attacker captured — computed over the *original* payload.
    let stolen_tag = s.frame_tag(
        &challenge,
        "node-a",
        0,
        &serde_json::to_vec(&sample_msg()).unwrap(),
    );

    let mut bytes = hello_bytes(&s, "node-a", &challenge);
    bytes.extend_from_slice(&(forged_payload.len() as u32).to_be_bytes());
    bytes.extend_from_slice(&stolen_tag);
    bytes.extend_from_slice(&forged_payload);

    stream.write_all(&bytes).await.unwrap();
    stream.flush().await.unwrap();

    assert_no_delivery(&t, "payload swapped under a stolen tag").await;
}

/// A second frame replayed within the same connection is rejected: `seq` is
/// part of the signed material, so frame 0 cannot be re-sent as frame 1.
#[tokio::test]
async fn duplicated_frame_within_connection_is_rejected() {
    let (t, addr) = listener(SECRET).await;

    let (mut stream, challenge) = connect_and_handshake(addr).await;
    let s = secret(SECRET);
    let frame0 = frame_bytes(&s, "node-a", &challenge, 0, &sample_msg());

    // Frame 0 (valid) followed by a byte-identical copy (which lands on seq 1).
    stream
        .write_all(&hello_bytes(&s, "node-a", &challenge))
        .await
        .unwrap();
    stream.write_all(&frame0).await.unwrap();
    stream.write_all(&frame0).await.unwrap();
    stream.flush().await.unwrap();

    // The first frame is legitimate and must arrive.
    let (from, _) = tokio::time::timeout(Duration::from_secs(2), t.recv())
        .await
        .expect("first frame timed out")
        .expect("recv");
    assert_eq!(from, "node-a");

    // The duplicate must not.
    assert_no_delivery(&t, "duplicated frame").await;
}

/// A peer that connects and then goes silent must not pin the accept task
/// forever, and must never be treated as authenticated.
#[tokio::test]
async fn silent_client_delivers_nothing() {
    let (t, addr) = listener(SECRET).await;

    let (_stream, _challenge) = connect_and_handshake(addr).await;
    assert_no_delivery(&t, "silent client").await;
}

//! Integration tests for the TCP transport, cluster runner, and search messages.

use std::collections::HashMap;
use std::net::SocketAddr;
use std::time::Duration;

use tokio::sync::watch;

use xerj_cluster::auth::ClusterSecret;
use xerj_cluster::node::{
    in_memory::{InMemoryBus, InMemoryTransport},
    ClusterNode,
};
use xerj_cluster::raft::{ClusterCommand, RaftMessage};
use xerj_cluster::runner::ClusterRunner;
use xerj_cluster::search::{merge_search_responses, SearchHit, SearchMessage};
use xerj_cluster::transport::TcpTransport;

// ── Helper: find a free port ──────────────────────────────────────────────────

async fn free_addr() -> SocketAddr {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    listener.local_addr().unwrap()
}

// ── Test 1: TCP transport send/recv ──────────────────────────────────────────

/// Two TCP transports on loopback: send a Raft message, verify receipt.
#[tokio::test]
async fn test_tcp_transport_send_recv() {
    // Bind two ports.
    let addr_a = free_addr().await;
    let addr_b = free_addr().await;

    // Node A knows about Node B and vice-versa.
    let mut peers_a = HashMap::new();
    peers_a.insert("node-b".to_string(), addr_b);

    let mut peers_b = HashMap::new();
    peers_b.insert("node-a".to_string(), addr_a);

    // Create both transports. Both sides must hold the same cluster secret —
    // there is no unauthenticated constructor.
    let secret = || ClusterSecret::new("shared-cluster-secret-for-tests").unwrap();
    let transport_a = TcpTransport::new("node-a".to_string(), addr_a, peers_a, secret())
        .await
        .expect("create transport A");
    let transport_b = TcpTransport::new("node-b".to_string(), addr_b, peers_b, secret())
        .await
        .expect("create transport B");

    // Give the listeners a moment to start.
    tokio::time::sleep(Duration::from_millis(50)).await;

    // Node A sends a RequestVote to Node B.
    let msg = RaftMessage::RequestVote {
        term: 1,
        candidate_id: "node-a".to_string(),
        last_log_index: 0,
        last_log_term: 0,
    };

    transport_a
        .send_to("node-b", &msg)
        .await
        .expect("send from A to B");

    // Node B should receive it within a reasonable timeout.
    let result = tokio::time::timeout(Duration::from_secs(2), async {
        use xerj_cluster::node::ClusterTransport;
        transport_b.recv().await
    })
    .await
    .expect("timeout waiting for message")
    .expect("recv error");

    let (from, received) = result;
    assert_eq!(from, "node-a");

    match received {
        RaftMessage::RequestVote {
            term, candidate_id, ..
        } => {
            assert_eq!(term, 1);
            assert_eq!(candidate_id, "node-a");
        }
        other => panic!("unexpected message: {:?}", other),
    }
}

// ── Test 2: Cluster runner election ──────────────────────────────────────────

/// Three in-memory nodes: verify that a leader is elected within a bounded
/// number of ticks when one node has its election timer pre-expired.
#[tokio::test]
async fn test_cluster_runner_election() {
    let bus = InMemoryBus::new();
    let ids = ["n1", "n2", "n3"];
    let all_ids: Vec<String> = ids.iter().map(|s| s.to_string()).collect();

    let mut runners = Vec::new();
    let mut shutdown_txs = Vec::new();

    for id in &ids {
        let peers: Vec<String> = all_ids
            .iter()
            .filter(|p| p.as_str() != *id)
            .cloned()
            .collect();

        let transport = InMemoryTransport::new(id.to_string(), bus.clone()).await;
        let mut node = ClusterNode::new(id.to_string(), peers, Box::new(transport));

        // Force the first node to time out immediately.
        if *id == "n1" {
            node.raft.force_election_timeout();
        }

        let (shutdown_tx, shutdown_rx) = watch::channel(false);
        let runner = ClusterRunner::new(node, Duration::from_millis(5), shutdown_rx);

        runners.push(runner);
        shutdown_txs.push(shutdown_tx);
    }

    // Spawn all runners.
    let handles: Vec<_> = runners
        .into_iter()
        .map(|mut r| {
            tokio::spawn(async move {
                // Run for at most 2 seconds, then return the runner for inspection.
                tokio::time::timeout(Duration::from_secs(2), r.run())
                    .await
                    .ok();
                r
            })
        })
        .collect();

    // Give the cluster 500 ms to elect a leader.
    tokio::time::sleep(Duration::from_millis(500)).await;

    // Signal shutdown.
    for tx in &shutdown_txs {
        let _ = tx.send(true);
    }

    // Collect results.
    let mut leader_count = 0;
    for handle in handles {
        let runner = handle.await.expect("task panicked");
        if runner.is_leader() {
            leader_count += 1;
        }
    }

    // In a 3-node cluster exactly one leader should be elected.
    // (In-memory transport is instantaneous, so this is deterministic enough.)
    assert!(
        leader_count <= 1,
        "at most one leader allowed; got {leader_count}"
    );
    // We cannot assert == 1 because the runner's `node_recv` currently uses
    // `pending()` (a safe placeholder). The election still proceeds via
    // `tick()` alone; the important invariant is "at most 1 leader".
}

// ── Test 3: Distributed search message serialization ─────────────────────────

/// Serialize and deserialize every SearchMessage variant; verify round-trips.
#[tokio::test]
async fn test_distributed_search_message() {
    let messages = vec![
        SearchMessage::SearchRequest {
            request_id: "req-abc-123".to_string(),
            index: "products".to_string(),
            query_json: r#"{"match":{"title":"laptop"}}"#.to_string(),
            size: 10,
            from: 0,
        },
        SearchMessage::SearchResponse {
            request_id: "req-abc-123".to_string(),
            hits: vec![
                SearchHit::new("prod-1", 1.8, r#"{"title":"gaming laptop","price":999}"#),
                SearchHit::new("prod-2", 1.2, r#"{"title":"office laptop","price":599}"#),
            ],
            total: 42,
            took_ms: 7,
        },
        SearchMessage::IndexRequest {
            index: "orders".to_string(),
            doc_id: "order-99".to_string(),
            source_json: r#"{"amount":49.99,"currency":"USD"}"#.to_string(),
        },
        SearchMessage::IndexResponse {
            doc_id: "order-99".to_string(),
            version: 1,
            result: "created".to_string(),
        },
        SearchMessage::Error {
            request_id: Some("req-xyz".to_string()),
            code: "index_not_found".to_string(),
            message: "index 'ghost' does not exist".to_string(),
        },
    ];

    for msg in &messages {
        let json = serde_json::to_string(msg).expect("serialize");
        let decoded: SearchMessage = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(
            msg,
            &decoded,
            "round-trip failed for {:?}",
            std::mem::discriminant(msg)
        );
    }
}

// ── Test 4: merge_search_responses ───────────────────────────────────────────

#[test]
fn test_merge_search_responses_ordering_and_pagination() {
    let shard1 = SearchMessage::SearchResponse {
        request_id: "r1".to_string(),
        hits: vec![
            SearchHit::new("a", 3.0, "{}"),
            SearchHit::new("c", 1.0, "{}"),
        ],
        total: 5,
        took_ms: 10,
    };
    let shard2 = SearchMessage::SearchResponse {
        request_id: "r1".to_string(),
        hits: vec![
            SearchHit::new("b", 2.0, "{}"),
            SearchHit::new("d", 0.5, "{}"),
        ],
        total: 3,
        took_ms: 8,
    };

    let (hits, total, took_ms) = merge_search_responses(vec![shard1, shard2], 1, 2);

    // Total from both shards.
    assert_eq!(total, 8);
    // Max took_ms.
    assert_eq!(took_ms, 10);
    // Sorted: a(3.0), b(2.0), c(1.0), d(0.5) → skip 1 → take 2 → [b, c]
    assert_eq!(hits.len(), 2);
    assert_eq!(hits[0].id, "b");
    assert_eq!(hits[1].id, "c");
}

