#[serde(rename_all = "snake_case")]
pub enum MergeStrategy {
    /// Merge segments of similar size (good for write-heavy workloads).
    SizeTiered,
    /// LSMT-style levelled merge (good for mixed workloads).
    LogStructured,
}

