            text: "#define LZ4_VERSION_RELEASE  0".into(),
            value: Some("0".into()),
        };
        let back: DefRecord = serde_json::from_str(&serde_json::to_string(&with).unwrap()).unwrap();
        assert_eq!(back, with);
        let without = DefRecord {
            value: None,
            ..with
        };
        let back: DefRecord =
            serde_json::from_str(&serde_json::to_string(&without).unwrap()).unwrap();
        assert_eq!(back.value, None);
    }

    fn answer_with(
        mode: AnswerMode,
        hits: Vec<Hit>,
        from: AnsweredFrom,
        warnings: Vec<String>,
    ) -> Answer {
        Answer {
            corpus: "lz4".into(),
            pin_sha: "0774d05537f9762f838f7ab541b7765f1a729cb5".into(),
            pin_date: "2026-10-02".into(),
            age_days: 1,
            licence_spdx: "BSD-2-Clause".into(),
            licence_class: LicenceClass::AdaptWithAttribution,
            answered_from: from,
            mode,
            hits,
            truncated: false,
            warnings,
        }
    }

    #[test]
    fn render_one_def_hit() {
        let a = answer_with(
            AnswerMode::Def,
            vec![Hit {
                file: "lib/lz4.h".into(),
                line: 133,
                kind: "define".into(),
                text: "#define LZ4_VERSION_RELEASE  0".into(),
                value: Some("0".into()),
                score: 14.5,
                licence_warning: None,
            }],
            AnsweredFrom::LocalPack,
            vec![],
        );
        let expected = "lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  lib/lz4.h:133\n\
                        #define LZ4_VERSION_RELEASE  0\n\
                        value: 0\n\
                        answered from: local pack";
        assert_eq!(render(&a), expected);
    }

    #[test]
    fn render_three_hits_how_mode_with_warning() {
        let hit = |f: &str, l: u32| Hit {
            file: f.into(),
            line: l,
            kind: "function".into(),
            text: format!("fn at {f}"),
            value: None,
            score: 1.0,
            licence_warning: None,
        };
        let a = answer_with(
            AnswerMode::How,
            vec![hit("a.rs", 1), hit("b.rs", 2), hit("c.rs", 3)],
            AnsweredFrom::Hosted,
            vec!["pin is 23 days old; the question asks for the current source".into()],
        );
        let expected = "lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  a.rs:1\n\
                        fn at a.rs\n\
                        lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  b.rs:2\n\
                        fn at b.rs\n\
                        lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause  c.rs:3\n\
                        fn at c.rs\n\
                        answered from: hosted hub\n\
                        warning: pin is 23 days old; the question asks for the current source";
        assert_eq!(render(&a), expected);
    }

    #[test]
    fn render_no_hits() {
        let a = answer_with(AnswerMode::Def, vec![], AnsweredFrom::LocalPack, vec![]);
        let expected = "lz4  pin 2026-10-02 (1 day old)  BSD-2-Clause\n\
                        no match in lz4 (pin 2026-10-02)\n\
                        answered from: local pack";
        assert_eq!(render(&a), expected);
    }

    #[test]
    fn age_days_pluralization() {
        let a = answer_with(AnswerMode::Def, vec![], AnsweredFrom::LocalPack, vec![]);
        assert!(render(&a).contains("(1 day old)"));
        let mut a2 = a;
        a2.age_days = 5;
        assert!(render(&a2).contains("(5 days old)"));
    }
}

//! # xerj-common
//!
//! Shared types, configuration, error handling, and observability primitives
//! for the xerj search engine — an Elasticsearch-compatible search engine
//! written in Rust.
//!
//! ## Design philosophy
//!
//! Unlike Elasticsearch's 3000+ configuration knobs, xerj deliberately exposes
//! **137 settings**, each meaningful and production-tested. Every default
//! is chosen so that a fresh deployment with zero configuration changes performs
//! well for the majority of workloads.
//!
//! ## Modules
//!
//! - [`config`]  — TOML-based configuration (137 settings)
//! - [`code_query`] — query shaping shared by `xerj search` and the
//!   `xerj_search` MCP tool (multi-word glue-token stripping, #1364)
//! - [`feedback`] — the bug/UX-report invitation shared by every `--help`
//! - [`error`]   — Unified error type ([`XerjError`])
//! - [`types`]   — Core domain types (documents, fields, IDs)
//! - [`calibration`] — probability calibration for the decide surface:
//!   isotonic (PAVA) and temperature (Platt) scaling, reliability curves, ECE
//! - [`field_coercion`] — ES-faithful ingest-time coercion/enforcement for
//!   numeric and boolean fields (the one predicate every write path shares)
//! - [`schema`]  — Index schema management and mapping evolution
//! - [`metrics`] — Prometheus counters, histograms, and gauges
//! - [`net`]     — Network trust primitives (trusted-proxy CIDR matching)
//! - [`resource`] — The machine-resource policy: cores, memory budget, thread priority
//! - [`home`]    — the home directory: `HOME`, else `USERPROFILE` (native Windows)
//! - [`localauth`] — Loopback guard + `<data_dir>/admin.key` discovery for
//!   same-machine CLI/MCP commands (`xerj mcp`, `xerj autoindex`, `xerj init`)
//! - [`xccode`]  — the reference-coding semantics shared by `xerj code`,
//!   `xerj corpus`, and the `xerj_code_search` MCP tool (issue #977)
//! - [`document_limit`] — the fixed per-document byte ceiling that keeps one
//!   JSON value from being tokenized into an unbounded `String` per word (#1122)
//! - [`thread_spawn`] — spawning helper threads without aborting the node
//!   on a failed spawn (#1122): Unix threads are created with `pthread_create`
//!   so a signal-stack allocation failure is an error instead of a panic in
//!   the child, the closure comes back, and a process-wide memory spawn gate
//!   skips best-effort spawns once the breaker is engaged. Scoped borrows
//!   use the same `pthread_create` path and are joined before the scope
//!   returns
//! - [`hub`]     — Corpus Hub v2 shared types: the catalogue, pack manifest,
//!   definition record, and the [`hub::Answer`] every surface renders (#1374)

pub mod argv;
pub mod calibration;
pub mod code_query;
pub mod config;
pub mod corpus_feedback;
pub mod document_limit;
pub mod error;
pub mod feedback;
pub mod field_coercion;
pub mod field_report;
pub mod fsio;
pub mod home;
pub mod hub;
