/// Name of the catalog index `xerj autoindex` maintains on every node it
/// onboards (`xerj-autoindex/src/catalog.rs` defines it; this copy is the
/// one the SERVER side reads). Single source of truth in xerj-common
/// because the two crates do not depend on each other, and both need the
/// exact spelling: the server classifies searches of this index as
/// machine traffic in the audit record (#1109), the client reads it back
/// from `xerj gain`.
pub const AUTOINDEX_CATALOG_INDEX: &str = "autoindex-catalog";

/// Crate-level result alias — uses [`XerjError`] as the error type.
pub type Result<T> = std::result::Result<T, XerjError>;

//! Local admin-key discovery and the loopback guard that makes it safe.
//!
//! The shipped default config has `[auth] enabled = true`, and the server
//! mints `<data_dir>/admin.key` on first start. Commands that talk to a
//! node from the same machine (`xerj mcp`, `xerj autoindex`, `xerj init`'s
//! advice) can read that file instead of demanding the user paste a key —
//! but only when the target is provably loopback, because a locally
//! readable key sent anywhere else is a credential leak, not a
//! convenience.
//!
//! Both helpers started life in `xerj-autoindex/src/cli.rs` (the autoindex
//! 401 fix); `xerj mcp` hit the identical failure mode (#961), so they
//! moved here rather than being duplicated. The invariants live with the
//! tests in `xerj-autoindex` (`url_is_loopback_is_true_only_for_this_machine`,
//! `userinfo_cannot_disguise_a_remote_host_as_loopback`, and the
//! `discover_local_admin_key` sandbox tests) — the calling crates keep
//! wiring tests of their own.
//!
//! The URL parsing uses a real parser (`url::Url`, the same type reqwest
//! re-exports) rather than string surgery, because the hand-rolled version
//! of this was wrong in a way that leaked credentials: splitting on the
//! last `:` treats the userinfo in `http://localhost:9200@evil.com/` as a
//! host:port pair, judges it loopback, and sends the admin key to
//! `evil.com`. `Url::host_str` resolves that to `evil.com`, which is the
//! whole point of using it.

use std::path::PathBuf;

/// True when `url`'s host is this machine, so a locally readable admin key
/// is the right credential to send. Anything else — a LAN address, a
/// hostname, a remote deployment — must be given a key explicitly.
pub fn url_is_loopback(url: &str) -> bool {
    // A schemeless `localhost:9200` parses as scheme `localhost`, path `9200`,
    // with no host at all, so retry those through `http://`. The retry still
    // goes through the parser: `localhost:9200@evil.com` becomes
    // `http://localhost:9200@evil.com`, whose host is `evil.com`, not loopback.
    let parsed = match url::Url::parse(url) {
        Ok(u) if matches!(u.scheme(), "http" | "https") => u,
        _ => match url::Url::parse(&format!("http://{url}")) {
            Ok(u) => u,
            // Unparseable is not loopback. Failing closed here costs a user
            // with an exotic URL one explicit --api-key; failing open costs
            // them the key itself.
            Err(_) => return false,
        },
    };
    match parsed.host_str() {
        // `host_str` strips the brackets from `[::1]` and does not lowercase
        // an IPv6 literal, so compare case-insensitively and cover both forms.
        Some(h) => {
            let h = h.trim_start_matches('[').trim_end_matches(']');
            h.eq_ignore_ascii_case("localhost") || h == "127.0.0.1" || h == "::1" || h == "0.0.0.0"
        }
        None => false,
    }
}

/// The admin key a local server wrote for itself, if we can find it.
///
/// Checked in the order a user is most likely to have created them: the
/// working directory's data dir (what the quickstart tells you to use), then
/// the documented package install location. Absent or unreadable is not an
/// error — the caller falls back to the actionable 401 message.
///
/// Returns the bare key (trimmed) and the file it came from, so the caller
/// can announce the path — never silently — and format the header per its
/// own wire convention (`ApiKey <key>`). Relative candidates are resolved
/// against the current directory before being returned: the announcement
/// must name a path the reader can act on even when the calling process was
/// spawned with an arbitrary cwd, which is exactly what MCP hosts do.
fn read_admin_key(path: &std::path::Path) -> Option<(String, PathBuf)> {
    std::fs::read_to_string(path)
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .map(|k| (k, path.to_path_buf()))
}

/// `~/.xerj/by-port/<port>` — one line, the absolute path of that listener's
/// `admin.key`. The server writes it on boot. Discovery reads the path, not
/// a second copy of the key.
fn port_pointer(port: u16) -> Option<PathBuf> {
    crate::home::home_dir().map(|home| home.join(".xerj").join("by-port").join(port.to_string()))
}

/// Record which data dir is serving `port`, so a later command on this
/// machine can find that node's admin key without guessing `--data-dir`.
/// The file holds the key's path. A missing home directory is not an error.
pub fn publish_admin_key_for_port(
    port: u16,
    admin_key_file: &std::path::Path,
) -> std::io::Result<()> {
    let Some(dest) = port_pointer(port) else {
        return Ok(());
    };
    if let Some(parent) = dest.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let abs =
        std::fs::canonicalize(admin_key_file).unwrap_or_else(|_| admin_key_file.to_path_buf());
    std::fs::write(&dest, format!("{}\n", abs.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&dest, std::fs::Permissions::from_mode(0o600))?;
    }
    Ok(())
}

/// Port of a XERJ URL. An explicit port wins; a URL with none is the product
/// default `9200` (not the scheme default 80/443).
pub fn xerj_url_port(url: &str) -> u16 {
    // A schemeless `localhost:9207` parses as scheme `localhost`, so retry
    // through `http://` the same way `url_is_loopback` does. An explicit port
    // wins; a URL with none is the product default 9200, not 80/443.
    let parsed = match url::Url::parse(url) {
        Ok(u) if matches!(u.scheme(), "http" | "https") => Some(u),
        _ => url::Url::parse(&format!("http://{url}")).ok(),
    };
    parsed.and_then(|u| u.port()).unwrap_or(9200)
}

/// [`discover_local_admin_key`], but the server's per-port pointer is tried
/// first. Callers must still refuse to send the key anywhere but loopback.
pub fn discover_local_admin_key_for_url(url: &str) -> Option<(String, PathBuf)> {
    let port = xerj_url_port(url);
    if let Some(pointer) = port_pointer(port) {
        if let Ok(text) = std::fs::read_to_string(&pointer) {
            let target = PathBuf::from(text.trim());
            if let Some(found) = read_admin_key(&target) {
                return Some(found);
            }
        }
    }
    discover_local_admin_key()
}

pub fn discover_local_admin_key() -> Option<(String, PathBuf)> {
    // Relative candidates resolve against the current directory (the "./"
    // prefix is dropped so the announced path reads cleanly). `./data` is the
    // quickstart; `./.xerj-data` is what `xerj search` / `xerj def` tell you
    // to start; `./xerj-data` is the same name without the dot.
    const CANDIDATES: &[&str] = &[
        "data/admin.key",
        ".xerj-data/admin.key",
        "xerj-data/admin.key",
        "/var/lib/xerj/admin.key",
    ];
    let cwd = std::env::current_dir().ok();
    let mut paths: Vec<PathBuf> = CANDIDATES
        .iter()
        .map(|c| {
            let p = PathBuf::from(c);
            match (&cwd, p.is_absolute()) {
                (Some(cwd), false) => cwd.join(p),
                _ => p,
            }
        })
        .collect();
    if let Some(home) = crate::home::home_dir() {
        paths.push(home.join(".xerj/brain/admin.key"));
        // llms.txt: `xerj --data-dir ~/xerj-data`.
        paths.push(home.join("xerj-data/admin.key"));
        paths.push(home.join(".xerj/admin.key"));
    }
    paths.into_iter().find_map(|p| read_admin_key(&p))
}

//! Prometheus metrics for the xerj engine.
//!
//! Metrics are registered in a dedicated [`prometheus::Registry`] (not the
//! global default) so that tests can create isolated registries and crates
//! can embed the registry in their own state without racing on global
//! singletons.
//!
//! ## Usage
//!
//! ```no_run
//! use xerj_common::metrics::Metrics;
//!
//! let metrics = Metrics::new().expect("metrics init failed");
//!
//! // Record a document being indexed
//! metrics.docs_indexed.inc();
//! metrics.index_latency.observe(0.003); // 3 ms
//!
//! // Expose via HTTP scrape endpoint:
//! // let body = metrics.gather_text();
//! ```

use prometheus::{
    exponential_buckets, histogram_opts, Histogram, HistogramOpts, HistogramVec, IntCounter,
    IntCounterVec, IntGauge, Opts, Registry,
};

use crate::error::XerjError;

// ═════════════════════════════════════════════════════════════════════════════
// Process-global metrics handle
// ═════════════════════════════════════════════════════════════════════════════

// The registry stays per-instance (see the module docs), but some call sites
// are constructed before the server's `Metrics` exists and without a handle
// to it: the engine's flush/merge pipeline (#804) and the storage layer's
// segment-open path (#819). The server installs the single process-wide
// instance here once at startup; call sites record through `global_metrics()`,
// which is `None` (a no-op) when nothing is installed, so libraries never
// fabricate observations. `xerj_engine::set_engine_metrics` delegates here,
// keeping one install site per process.
static GLOBAL_METRICS: std::sync::OnceLock<std::sync::Arc<Metrics>> = std::sync::OnceLock::new();

/// Install the process-wide metrics handle. Idempotent; the first call wins
/// (later calls are ignored).
pub fn set_global_metrics(metrics: std::sync::Arc<Metrics>) {
    let _ = GLOBAL_METRICS.set(metrics);
}

/// The installed process-wide metrics handle, or `None` if no server has
/// installed one (unit tests, embedded uses).
pub fn global_metrics() -> Option<&'static std::sync::Arc<Metrics>> {
    GLOBAL_METRICS.get()
}

// ═════════════════════════════════════════════════════════════════════════════
// Metrics collection
// ═════════════════════════════════════════════════════════════════════════════

/// All Prometheus metrics for the engine, grouped by type.
///
/// A single `Metrics` instance is created at startup and shared (via `Arc`)
/// across all subsystems.
#[derive(Clone)]
pub struct Metrics {
    /// The Prometheus registry that owns all metrics in this struct.
    pub registry: Registry,

    // ── Counters ─────────────────────────────────────────────────────────────
    /// Total number of documents successfully indexed.
    pub docs_indexed: IntCounter,
    /// Total number of search queries executed.
    pub queries_executed: IntCounter,
    /// Total bytes written to segment files (uncompressed).
    pub bytes_written: IntCounter,
    /// Total on-disk bytes read from segment (.seg) files at open-time
    /// validation (reader-cache misses only).
    pub bytes_read: IntCounter,

    // ── Per-index counters ────────────────────────────────────────────────────
    /// Documents indexed, labelled by index name.
    pub docs_indexed_by_index: IntCounterVec,
    /// Queries executed, labelled by index name.
    pub queries_by_index: IntCounterVec,

    // ── Histograms ────────────────────────────────────────────────────────────
    /// End-to-end query latency in seconds.
    pub query_latency: Histogram,
    /// End-to-end index (ingest) latency in seconds.
    pub index_latency: Histogram,
    /// Time taken to flush an in-memory buffer to a segment in seconds.
    pub flush_duration: Histogram,
    /// Time taken to complete a segment merge in seconds.
    pub merge_duration: Histogram,
    /// WAL write latency in seconds.
    pub wal_write_latency: Histogram,

    // ── Per-operation histograms ──────────────────────────────────────────────
    /// Query latency in seconds, labelled by query type.
    pub query_latency_by_type: HistogramVec,

    // ── Gauges ────────────────────────────────────────────────────────────────
    /// Number of open segments across all indices.
    pub segment_count: IntGauge,
    /// Total number of live (non-deleted) documents across all indices.
    pub doc_count: IntGauge,
    /// Approximate engine memory usage in bytes.
    pub memory_usage: IntGauge,
    /// Number of searches currently in flight.
    pub active_searches: IntGauge,
    /// Size of the WAL on disk in bytes.
    pub wal_size_bytes: IntGauge,

    // ── Query cache (RC4-W4 item 4) ───────────────────────────────────────────
    /// Cumulative internal query-result cache hits across all indices. Exposed
    /// as a gauge because it is reconciled from the engine's own atomic counters
    /// at scrape time (Prometheus `IntCounter` has no set()); the value is
    /// monotonic across a process lifetime, so `hits / (hits + misses)` gives
    /// the cache hit ratio directly.
    pub query_cache_hits: IntGauge,
    /// Cumulative internal query-result cache misses across all indices.
    pub query_cache_misses: IntGauge,

    // ── Rerank stage ──────────────────────────────────────────────────────────
    // Reranking is a search feature the operator pays a third party for, per
    // judged document, on a volume the CALLER chooses. These are the meter.
    /// `rerank` requests by outcome: `applied` (the judge's order was served),
    /// `degraded` (deadline missed, engine order served under a 200),
    /// `refused` (400 / 403 / 503 — nothing was sent to the provider) and
    /// `failed` (502 — the provider was called and the contract broke).
    pub rerank_requests: IntCounterVec,
    /// Documents the provider returned a verdict for. The billing unit.
    pub rerank_documents_judged: IntCounter,
    /// Tokens the provider reported, by `kind` (`input` / `output`). Zero when
    /// the provider omits usage — this is its meter reading, not an estimate.
    pub rerank_provider_tokens: IntCounterVec,
}

impl Metrics {
    /// Create a new `Metrics` instance with its own isolated registry.
    pub fn new() -> Result<Self, XerjError> {
        let registry = Registry::new();
        Self::with_registry(registry)
    }

    /// Create `Metrics` registered against the provided registry.
    ///
    /// Use this when you need to merge xerj metrics into an existing
    /// Prometheus registry (e.g., alongside application-level metrics).
    pub fn with_registry(registry: Registry) -> Result<Self, XerjError> {
        // ── Counters ──────────────────────────────────────────────────────────
        let docs_indexed = IntCounter::with_opts(Opts::new(
            "xerj_docs_indexed_total",
            "Total number of documents successfully indexed",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let queries_executed = IntCounter::with_opts(Opts::new(
            "xerj_queries_executed_total",
            "Total number of search queries executed",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let bytes_written = IntCounter::with_opts(Opts::new(
            "xerj_bytes_written_total",
            "Total on-disk bytes written to segment (.seg) files by flush and merge",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let bytes_read = IntCounter::with_opts(Opts::new(
            "xerj_bytes_read_total",
            "Total on-disk bytes read from segment (.seg) files at open-time validation (reader-cache misses only)",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let docs_indexed_by_index = IntCounterVec::new(
            Opts::new(
                "xerj_docs_indexed_by_index_total",
                "Documents indexed, labelled by index name",
            ),
            &["index"],
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let queries_by_index = IntCounterVec::new(
            Opts::new(
                "xerj_queries_by_index_total",
                "Queries executed, labelled by index name",
            ),
            &["index"],
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        // ── Histograms ────────────────────────────────────────────────────────
        // Latency buckets: 500µs → 30s (15 buckets)
        let latency_buckets =
            exponential_buckets(0.0005, 2.0, 15).expect("latency bucket config is valid");

        let query_latency = Histogram::with_opts(
            HistogramOpts::new("xerj_query_latency_seconds", "End-to-end query latency")
                .buckets(latency_buckets.clone()),
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let index_latency = Histogram::with_opts(
            HistogramOpts::new(
                "xerj_index_latency_seconds",
                "End-to-end document indexing latency",
            )
            .buckets(latency_buckets.clone()),
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        // Flush/merge duration buckets: 10ms → ~5min
        let duration_buckets =
            exponential_buckets(0.01, 2.0, 15).expect("duration bucket config is valid");

        let flush_duration = Histogram::with_opts(
            HistogramOpts::new(
                "xerj_flush_duration_seconds",
                "Time to flush an in-memory buffer to a segment",
            )
            .buckets(duration_buckets.clone()),
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let merge_duration = Histogram::with_opts(
            HistogramOpts::new(
                "xerj_merge_duration_seconds",
                "Time to complete a segment merge operation",
            )
            .buckets(duration_buckets),
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let wal_write_latency = Histogram::with_opts(
            HistogramOpts::new("xerj_wal_write_latency_seconds", "WAL write latency")
                .buckets(latency_buckets),
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let query_latency_by_type = HistogramVec::new(
            histogram_opts!(
                "xerj_query_latency_by_type_seconds",
                "Query latency, labelled by query type",
                exponential_buckets(0.0005, 2.0, 15).expect("valid")
            ),
            &["query_type"],
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        // ── Gauges ────────────────────────────────────────────────────────────
        let segment_count = IntGauge::with_opts(Opts::new(
            "xerj_segment_count",
            "Number of open segments across all indices",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let doc_count = IntGauge::with_opts(Opts::new(
            "xerj_doc_count",
            "Total live documents across all indices",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let memory_usage = IntGauge::with_opts(Opts::new(
            "xerj_memory_usage_bytes",
            "Approximate engine memory usage in bytes",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let active_searches = IntGauge::with_opts(Opts::new(
            "xerj_active_searches",
            "Number of searches currently in flight",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let wal_size_bytes = IntGauge::with_opts(Opts::new(
            "xerj_wal_size_bytes",
            "Current WAL size on disk in bytes",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let query_cache_hits = IntGauge::with_opts(Opts::new(
            "xerj_query_cache_hits",
            "Cumulative internal query-result cache hits across all indices",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let query_cache_misses = IntGauge::with_opts(Opts::new(
            "xerj_query_cache_misses",
            "Cumulative internal query-result cache misses across all indices",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let rerank_requests = IntCounterVec::new(
            Opts::new(
                "xerj_rerank_requests_total",
                "Searches that carried a `rerank` block, by outcome \
                 (applied, degraded, refused, failed)",
            ),
            &["outcome"],
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let rerank_documents_judged = IntCounter::with_opts(Opts::new(
            "xerj_rerank_documents_judged_total",
            "Documents the rerank provider returned a verdict for",
        ))
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        let rerank_provider_tokens = IntCounterVec::new(
            Opts::new(
                "xerj_rerank_provider_tokens_total",
                "Tokens the rerank provider reported, by kind (input, output)",
            ),
            &["kind"],
        )
        .map_err(|e| XerjError::internal(format!("metrics: {e}")))?;

        // ── Register everything ───────────────────────────────────────────────
        macro_rules! reg {
            ($metric:expr) => {
                registry
                    .register(Box::new($metric.clone()))
                    .map_err(|e| XerjError::internal(format!("metrics register: {e}")))?;
            };
        }

        reg!(docs_indexed);
        reg!(queries_executed);
        reg!(bytes_written);
        reg!(bytes_read);
        reg!(docs_indexed_by_index);
        reg!(queries_by_index);
        reg!(query_latency);
        reg!(index_latency);
        reg!(flush_duration);
        reg!(merge_duration);
        reg!(wal_write_latency);
        reg!(query_latency_by_type);
        reg!(segment_count);
        reg!(doc_count);
        reg!(memory_usage);
        reg!(active_searches);
        reg!(wal_size_bytes);
        reg!(query_cache_hits);
        reg!(query_cache_misses);
        reg!(rerank_requests);
        reg!(rerank_documents_judged);
        reg!(rerank_provider_tokens);

        Ok(Self {
            registry,
            docs_indexed,
            queries_executed,
            bytes_written,
            bytes_read,
            docs_indexed_by_index,
            queries_by_index,
            query_latency,
            index_latency,
            flush_duration,
            merge_duration,
            wal_write_latency,
            query_latency_by_type,
            segment_count,
            doc_count,
            memory_usage,
            active_searches,
            wal_size_bytes,
            query_cache_hits,
            query_cache_misses,
            rerank_requests,
            rerank_documents_judged,
            rerank_provider_tokens,
        })
    }

    /// Reconcile the query-cache gauges from the engine's cumulative counters.
    /// Called by the `/v1/metrics` handler at scrape time.
    pub fn set_query_cache(&self, hits: u64, misses: u64) {
        self.query_cache_hits.set(hits as i64);
        self.query_cache_misses.set(misses as i64);
    }

    // ── Scrape helpers ────────────────────────────────────────────────────────

    /// Gather all metrics from the registry as a `MetricFamily` vector.
    pub fn gather(&self) -> Vec<prometheus::proto::MetricFamily> {
        self.registry.gather()
    }

    /// Encode all metrics to the Prometheus text exposition format.
    ///
    /// The returned string can be served directly from `/metrics`.
    pub fn gather_text(&self) -> Result<String, XerjError> {
        use prometheus::Encoder;
        let encoder = prometheus::TextEncoder::new();
        let mut buf = Vec::new();
        encoder
            .encode(&self.gather(), &mut buf)
            .map_err(|e| XerjError::internal(format!("metrics encode: {e}")))?;
        String::from_utf8(buf).map_err(|e| XerjError::internal(format!("metrics utf8: {e}")))
    }

    // ── Ergonomic recording helpers ───────────────────────────────────────────

    /// Record a successful document indexing operation.
    ///
    /// Increments both the global counter and the per-index counter.
    pub fn record_doc_indexed(&self, index: &str) {
        self.docs_indexed.inc();
        self.docs_indexed_by_index.with_label_values(&[index]).inc();
    }

    /// Record `n` documents successfully indexed into `index` in a single
    /// batch. Increments the global and per-index counters with one atomic
    /// `inc_by` each — cheaper on the hot bulk path than calling
    /// [`Self::record_doc_indexed`] per document (which contends the global
    /// counter once per doc). A no-op when `n == 0`.
    pub fn record_docs_indexed(&self, index: &str, n: u64) {
        if n == 0 {
            return;
        }
        self.docs_indexed.inc_by(n);
        self.docs_indexed_by_index
            .with_label_values(&[index])
            .inc_by(n);
    }

    /// Record `n` on-disk bytes written to a segment (.seg) file — called
    /// once per segment finalized by flush or merge with the sealed segment's
    /// `size_bytes`. A no-op when `n == 0`. (#804: the counter was registered
    /// but never incremented, so it read a flat zero regardless of write
    /// volume.)
    pub fn record_bytes_written(&self, n: u64) {
        if n == 0 {
            return;
        }
        self.bytes_written.inc_by(n);
    }

    /// Record `n` on-disk bytes read from a segment (.seg) file, called once
    /// per validated `SegmentReader` open with the opened file's length (the
    /// open path reads and CRC-checks the whole file; the reader-cache hit
    /// path reuses the mmap and reads nothing). A no-op when `n == 0`.
    /// (#819: the counter was registered but never incremented, so it read a
    /// flat zero regardless of read volume.)
    pub fn record_bytes_read(&self, n: u64) {
        if n != 0 {
            self.bytes_read.inc_by(n);
        }
    }

    /// Drop the per-index label series for `index` (RC4-W4 item 5).
    ///
    /// Called when an index is deleted so its `queries_by_index` /
    /// `docs_indexed_by_index` label series don't linger for the lifetime of
    /// the process (unbounded metric cardinality). Removing a label that was
    /// never created is a harmless no-op — the error is ignored.
    pub fn prune_index_labels(&self, index: &str) {
        let _ = self.queries_by_index.remove_label_values(&[index]);
        let _ = self.docs_indexed_by_index.remove_label_values(&[index]);
    }

    /// Record a completed query.
    ///
    /// Increments counters and records latency histograms.
    pub fn record_query(&self, index: &str, query_type: &str, latency_secs: f64) {
        self.queries_executed.inc();
        self.queries_by_index.with_label_values(&[index]).inc();
        self.query_latency.observe(latency_secs);
        self.query_latency_by_type
            .with_label_values(&[query_type])
            .observe(latency_secs);
    }

    /// Record the index-agnostic side of a completed query: the global counter
    /// and both the overall and by-type latency histograms — but NOT
    /// `queries_by_index`. Use this when the caller increments
    /// `queries_by_index` itself, once per *resolved* concrete index (a
    /// multi-index or wildcard search touches several), which is more accurate
    /// than attributing the whole request to a single raw label.
    pub fn record_query_global(&self, query_type: &str, latency_secs: f64) {
        self.queries_executed.inc();
        self.query_latency.observe(latency_secs);
        self.query_latency_by_type
            .with_label_values(&[query_type])
            .observe(latency_secs);
    }

    /// Guard type that decrements `active_searches` when dropped.
    ///
    /// ```no_run
    /// # use xerj_common::metrics::Metrics;
    /// # let metrics = Metrics::new().unwrap();
    /// let _guard = metrics.active_search_guard();
    /// // active_searches is now incremented; decremented when `_guard` is dropped.
    /// ```
    pub fn active_search_guard(&self) -> ActiveSearchGuard {
        self.active_searches.inc();
        ActiveSearchGuard {
            gauge: self.active_searches.clone(),
        }
    }

    // ── Type-erased observe helpers ───────────────────────────────────────────
    //
    // These let crates that do NOT depend on the `prometheus` crate (e.g.
    // `xerj-engine`) record into the duration histograms at their real call
    // sites without ever naming a `prometheus` type. `secs` is the observed
    // duration in seconds (Prometheus convention).

    /// Observe one completed memtable→segment flush, in seconds.
    pub fn observe_flush(&self, secs: f64) {
        self.flush_duration.observe(secs);
    }

    /// Observe one completed segment merge, in seconds.
    pub fn observe_merge(&self, secs: f64) {
        self.merge_duration.observe(secs);
    }

    /// Observe one WAL append (durability write) latency, in seconds.
    pub fn observe_wal_write(&self, secs: f64) {
        self.wal_write_latency.observe(secs);
    }

    /// Observe one end-to-end indexing (ingest) operation latency, in seconds.
    pub fn observe_index(&self, secs: f64) {
        self.index_latency.observe(secs);
    }
}

/// RAII guard for the `active_searches` gauge.
pub struct ActiveSearchGuard {
    gauge: IntGauge,
}

impl Drop for ActiveSearchGuard {
    fn drop(&mut self) {
        self.gauge.dec();
    }
}

