        assert_eq!(m.active_searches.get(), 0);
        {
            let _g = m.active_search_guard();
            assert_eq!(m.active_searches.get(), 1);
        }
        assert_eq!(m.active_searches.get(), 0);
    }

    #[test]
    fn gather_text_is_valid_utf8() {
        let m = Metrics::new().unwrap();
        m.docs_indexed.inc();
        let text = m.gather_text().unwrap();
        assert!(text.contains("xerj_docs_indexed_total"));
    }

    /// `/metrics` must emit the Prometheus text exposition format exactly:
    /// a `# HELP` line, a `# TYPE` line, then the sample.
    ///
    /// This pins the wire contract independently of which `proto` backend the
    /// `prometheus` crate was compiled with. We build with
    /// `default-features = false`, which drops the optional `protobuf` feature
    /// (and with it protobuf 2.x, GHSA-2gh3-rmm4-6rq5); `proto::MetricFamily`
    /// is then prometheus's pure-Rust `plain_model` rather than generated
    /// protobuf code. The text output is required to be byte-identical either
    /// way, and a scrape breaking silently is exactly the regression that
    /// feature flip could cause.
    #[test]
    fn gather_text_emits_prometheus_exposition_format() {
        let m = Metrics::new().unwrap();
        m.docs_indexed.inc_by(3);
        let text = m.gather_text().unwrap();

        assert!(
            text.contains(
                "# HELP xerj_docs_indexed_total Total number of documents successfully indexed"
            ),
            "missing/incorrect HELP line:\n{text}"
        );
        assert!(
            text.contains("# TYPE xerj_docs_indexed_total counter"),
            "missing/incorrect TYPE line:\n{text}"
        );
        assert!(
            text.lines().any(|l| l == "xerj_docs_indexed_total 3"),
            "missing unlabelled sample line:\n{text}"
        );
    }

    /// Labelled series must survive the same encoder path — label rendering is
    /// the other place a `proto` backend swap could diverge.
    #[test]
    fn gather_text_renders_labelled_series() {
        let m = Metrics::new().unwrap();
        m.record_docs_indexed("my-index", 2);
        let text = m.gather_text().unwrap();

        assert!(
            text.contains("# TYPE xerj_docs_indexed_by_index_total counter"),
            "missing TYPE line for labelled counter:\n{text}"
        );
        assert!(
            text.lines()
                .any(|l| l == "xerj_docs_indexed_by_index_total{index=\"my-index\"} 2"),
            "missing/incorrect labelled sample line:\n{text}"
        );
    }

    #[test]
    fn isolated_registries_do_not_conflict() {
        // Two Metrics instances must not share state
        let m1 = Metrics::new().unwrap();
        let m2 = Metrics::new().unwrap();
        m1.docs_indexed.inc();
        assert_eq!(m1.docs_indexed.get(), 1);
        assert_eq!(m2.docs_indexed.get(), 0);
    }
}

//! Network trust primitives — who is allowed to tell us who the client is.
//!
//! Xerj derives the caller's identity (per-IP auth rate-limit bucket,
//! audit-log source address) from the TCP peer address, which a caller
//! cannot forge. Behind a legitimate reverse proxy the peer *is* the proxy,
//! which would collapse every user into one bucket, so the proxy's
//! `X-Forwarded-For` header has to be honoured — but only when the socket
//! peer is a proxy the operator has actually declared.
//!
//! [`TrustedProxies`] is that declaration: a parsed set of addresses / CIDR
//! blocks. It is **empty by default**, and an empty set trusts nothing, so a
//! node that has not been configured for a proxy ignores forwarding headers
//! entirely.

use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

/// One entry of the trusted-proxy list: a base address plus a prefix length.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Cidr {
    base: IpAddr,
    prefix_len: u8,
}

impl Cidr {
    /// Parse `"10.0.0.7"`, `"10.0.0.0/8"`, `"::1"`, `"fd00::/8"`.
    ///
    /// A bare address is treated as a host route (`/32` for v4, `/128` for
    /// v6). The prefix length must fit the address family.
    fn parse(s: &str) -> Result<Self, String> {
        let s = s.trim();
        if s.is_empty() {
            return Err("empty entry".to_string());
        }
        let (addr_str, prefix_str) = match s.split_once('/') {
            Some((a, p)) => (a, Some(p)),
            None => (s, None),
        };
        let base: IpAddr = addr_str
            .parse()
            .map_err(|_| format!("`{addr_str}` is not an IP address"))?;
        let max_len: u8 = match base {
            IpAddr::V4(_) => 32,
            IpAddr::V6(_) => 128,
        };
        let prefix_len = match prefix_str {
            None => max_len,
            Some(p) => {
                let n: u8 = p
                    .parse()
                    .map_err(|_| format!("`{p}` is not a prefix length"))?;
                if n > max_len {
                    return Err(format!("prefix /{n} exceeds /{max_len} for `{addr_str}`"));
                }
                n
            }
        };
        Ok(Self { base, prefix_len })
    }

    fn contains(&self, ip: &IpAddr) -> bool {
        match (self.base, ip) {
            (IpAddr::V4(base), IpAddr::V4(ip)) => {
                prefix_eq(&base.octets(), &ip.octets(), self.prefix_len)
            }
            (IpAddr::V6(base), IpAddr::V6(ip)) => {
                prefix_eq(&base.octets(), &ip.octets(), self.prefix_len)
            }
            // Families never cross: peers are canonicalised (v4-mapped v6
            // folded down to v4) before they get here, so a v4 peer is only
            // ever matched against v4 entries.
            _ => false,
        }
    }
}

/// Do `a` and `b` agree on their first `bits` bits?
fn prefix_eq(a: &[u8], b: &[u8], bits: u8) -> bool {
    let whole = (bits / 8) as usize;
    if a[..whole] != b[..whole] {
        return false;
    }
    let rem = bits % 8;
    if rem == 0 {
        return true;
    }
    let mask = 0xffu8 << (8 - rem);
    a[whole] & mask == b[whole] & mask
}

/// Fold an IPv4-mapped IPv6 address (`::ffff:1.2.3.4`) down to plain IPv4.
///
/// A dual-stack listener reports IPv4 peers in mapped form, so without this
/// a `10.0.0.0/8` entry would never match a real 10.x proxy.
pub fn canonical_ip(ip: IpAddr) -> IpAddr {
    match ip {
        IpAddr::V6(v6) => match v6.to_ipv4_mapped() {
            Some(v4) => IpAddr::V4(v4),
            None => IpAddr::V6(v6),
        },
        v4 => v4,
    }
}

/// The operator-declared set of reverse proxies whose forwarding headers may
/// be believed. Empty means "trust nothing" — the safe default.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct TrustedProxies {
    entries: Vec<Cidr>,
}

impl TrustedProxies {
    /// A set that trusts nothing.
    pub fn none() -> Self {
        Self::default()
    }

    /// Parse a config list. Fails on the first malformed entry — a typo in a
    /// trust boundary must be loud, never silently "trusts nothing" (which
    /// would look like it worked) nor silently "trusts everything".
    pub fn parse(entries: &[String]) -> Result<Self, String> {
        let mut parsed = Vec::with_capacity(entries.len());
        for e in entries {
            parsed.push(Cidr::parse(e).map_err(|why| format!("`{e}`: {why}"))?);
        }
        Ok(Self { entries: parsed })
    }

    /// True when nothing is trusted (the default).
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// Is `ip` one of the declared proxies?
    pub fn contains(&self, ip: &IpAddr) -> bool {
        if self.entries.is_empty() {
            return false;
        }
        let ip = canonical_ip(*ip);
        self.entries.iter().any(|e| e.contains(&ip))
    }
}

/// Parse one element of an `X-Forwarded-For` chain into an address.
///
/// Handles the shapes proxies actually emit: a bare address, a bracketed
/// IPv6 literal with a port (`[2001:db8::1]:443`), and an IPv4 address with
/// a port (`1.2.3.4:5678`). Returns `None` for anything else — including
/// RFC 7239 obfuscated identifiers (`_hidden`) and `unknown`, which carry no
/// address and must not be silently skipped over.
pub fn parse_forwarded_element(raw: &str) -> Option<IpAddr> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    // `[v6]:port` or `[v6]`
    if let Some(rest) = s.strip_prefix('[') {
        let (inner, _) = rest.split_once(']')?;
        return inner.parse::<Ipv6Addr>().ok().map(IpAddr::V6);
    }
    if let Ok(ip) = s.parse::<IpAddr>() {
        return Some(ip);
    }
    // `1.2.3.4:5678` — only valid for v4; a bare v6 with a colon-port is
    // ambiguous and proxies are required to bracket it.
    if let Some((host, port)) = s.rsplit_once(':') {
        if !port.is_empty() && port.bytes().all(|b| b.is_ascii_digit()) {
            if let Ok(v4) = host.parse::<Ipv4Addr>() {
                return Some(IpAddr::V4(v4));
            }
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    fn ip(s: &str) -> IpAddr {
        s.parse().unwrap()
    }

    #[test]
    fn empty_set_trusts_nothing() {
        let t = TrustedProxies::none();
        assert!(t.is_empty());
        for candidate in ["127.0.0.1", "10.0.0.1", "::1", "8.8.8.8"] {
            assert!(
                !t.contains(&ip(candidate)),
                "{candidate} must not be trusted"
            );
        }
    }

    #[test]
    fn host_entry_matches_exactly_one_address() {
        let t = TrustedProxies::parse(&["10.0.0.7".to_string()]).unwrap();
        assert!(t.contains(&ip("10.0.0.7")));
        assert!(!t.contains(&ip("10.0.0.8")));
        assert!(!t.contains(&ip("10.0.0.6")));
    }

    #[test]
    fn cidr_entry_matches_the_block_and_nothing_else() {
        let t = TrustedProxies::parse(&["10.1.2.0/24".to_string()]).unwrap();
        assert!(t.contains(&ip("10.1.2.0")));
        assert!(t.contains(&ip("10.1.2.255")));
        assert!(!t.contains(&ip("10.1.3.0")));
        assert!(!t.contains(&ip("10.1.1.255")));
    }

    #[test]
    fn non_byte_aligned_prefix_masks_correctly() {
        let t = TrustedProxies::parse(&["192.168.4.0/22".to_string()]).unwrap();
        assert!(t.contains(&ip("192.168.4.1")));
        assert!(t.contains(&ip("192.168.7.254")));
        assert!(!t.contains(&ip("192.168.8.1")));
        assert!(!t.contains(&ip("192.168.3.255")));
    }

    #[test]
    fn ipv6_entries_work() {
        let t = TrustedProxies::parse(&["fd00::/8".to_string(), "::1".to_string()]).unwrap();
        assert!(t.contains(&ip("fd12::9")));
        assert!(t.contains(&ip("::1")));
        assert!(!t.contains(&ip("2001:db8::1")));
    }

    #[test]
    fn families_do_not_cross() {
        let v4_only = TrustedProxies::parse(&["0.0.0.0/0".to_string()]).unwrap();
        assert!(v4_only.contains(&ip("8.8.8.8")));
        assert!(!v4_only.contains(&ip("2001:db8::1")));

        let v6_only = TrustedProxies::parse(&["::/0".to_string()]).unwrap();
        assert!(v6_only.contains(&ip("2001:db8::1")));
        assert!(!v6_only.contains(&ip("8.8.8.8")));
    }

    #[test]
    fn v4_mapped_v6_peer_matches_a_v4_entry() {
        let t = TrustedProxies::parse(&["10.0.0.0/8".to_string()]).unwrap();
        assert!(t.contains(&ip("::ffff:10.4.5.6")));
        assert!(!t.contains(&ip("::ffff:11.4.5.6")));
    }

    #[test]
    fn malformed_entries_are_rejected_loudly() {
        for bad in [
            "not-an-ip",
            "10.0.0.0/33",
            "::1/129",
            "10.0.0.0/abc",
            "",
            "example.com",
        ] {
            assert!(
                TrustedProxies::parse(&[bad.to_string()]).is_err(),
                "`{bad}` must be rejected"
            );
        }
    }

    #[test]
    fn forwarded_elements_parse_the_shapes_proxies_emit() {
        assert_eq!(parse_forwarded_element(" 1.2.3.4 "), Some(ip("1.2.3.4")));
        assert_eq!(parse_forwarded_element("1.2.3.4:5678"), Some(ip("1.2.3.4")));
        assert_eq!(
            parse_forwarded_element("2001:db8::1"),
            Some(ip("2001:db8::1"))
        );
        assert_eq!(
            parse_forwarded_element("[2001:db8::1]:443"),
            Some(ip("2001:db8::1"))
        );
        assert_eq!(
            parse_forwarded_element("[2001:db8::1]"),
            Some(ip("2001:db8::1"))
        );
    }

    #[test]
    fn forwarded_elements_that_carry_no_address_are_none() {
        for bad in [
            "",
            "  ",
            "unknown",
            "_hidden",
            "1.2.3.4.5",
            "[bogus]",
            "evil",
        ] {
            assert_eq!(parse_forwarded_element(bad), None, "`{bad}` must not parse");
        }
    }
}

//! Compact stand-in for a JSON array of finite `f32`s.
//!
//! A 384-d embedding stored as `serde_json::Value::Number`s is one `Value`
//! per component. On the lexical embedder that is what `semantic_text`
//! writes into every autoindexed record, and both memtables retain that
//! tree until flush. Measured on the #1940 corpus (5,000 records, ~195
//! bytes each) the parsed tree was ~43 KB/doc in the stored-values cache
//! and ~78 KB/doc of RSS growth during `index`, against ~1.5 KB of actual
//! `f32` payload.
//!
//! The packed form is a single string, `xerj:f32:` plus lowercase hex of
//! the little-endian `f32` bits. It round-trips bit-exactly, survives the
//! stored-section JSON codec, and expands back to a number array only when
//! a response actually returns the field.

use serde_json::Value;

pub const PACKED_F32_PREFIX: &str = "xerj:f32:";

const HEX: &[u8; 16] = b"0123456789abcdef";

/// Pack `values` when every element is finite and the slice is non-empty.
pub fn pack_f32_vector(values: &[f32]) -> Option<String> {
    if values.is_empty() || values.iter().any(|value| !value.is_finite()) {
        return None;
    }
    let mut out = String::with_capacity(PACKED_F32_PREFIX.len() + values.len() * 8);
    out.push_str(PACKED_F32_PREFIX);
    for value in values {
        for byte in value.to_le_bytes() {
            out.push(HEX[(byte >> 4) as usize] as char);
            out.push(HEX[(byte & 0x0f) as usize] as char);
        }
    }
    Some(out)
}

pub fn is_packed_f32(value: &str) -> bool {
    value.starts_with(PACKED_F32_PREFIX)
        && value.len() > PACKED_F32_PREFIX.len()
        && (value.len() - PACKED_F32_PREFIX.len()).is_multiple_of(8)
}

/// Decode a packed vector. `None` for any other string, a bad nibble, a
/// non-multiple-of-8 payload, or a non-finite element.
pub fn unpack_f32_vector(value: &str) -> Option<Vec<f32>> {
    let rest = value.strip_prefix(PACKED_F32_PREFIX)?;
    if rest.is_empty() || !rest.len().is_multiple_of(8) {
        return None;
    }
    let mut out = Vec::with_capacity(rest.len() / 8);
    let bytes = rest.as_bytes();
    for chunk in bytes.chunks_exact(8) {
        let mut le = [0u8; 4];
        for (i, pair) in chunk.chunks_exact(2).enumerate() {
            le[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
        }
        let decoded = f32::from_le_bytes(le);
        if !decoded.is_finite() {
            return None;
        }
        out.push(decoded);
    }
    Some(out)
}

fn hex_nibble(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

/// A JSON number array, or a packed string, as finite `f32`s.
///
/// Number arrays use the same `as_f64() as f32` conversion the exact kNN
/// scan has always used, which is bit-exact for every finite `f32`.
pub fn json_to_f32_vector(value: &Value) -> Option<Vec<f32>> {
    match value {
        Value::String(text) => unpack_f32_vector(text),
        // An empty array is a present-but-empty vector. The kNN projection
        // treats that as supported (`Some(vec![])`), distinct from null and
        // from a shape it cannot score. Packing still refuses it.
        Value::Array(items) => {
            let mut out = Vec::with_capacity(items.len());
            for item in items {
                let decoded = item.as_f64()? as f32;
                if !decoded.is_finite() {
                    return None;
                }
                out.push(decoded);
            }
            Some(out)
        }
        _ => None,
    }
}

/// Replace a number array (or an array of number arrays) with the packed
/// string form, in place. Leaves every other shape untouched, including a
/// value that is already packed and a vector containing a non-finite
/// element.
pub fn compact_vector_value(value: &mut Value) {
    let Some(packed) = try_compact(value) else {
        return;
    };
    *value = packed;
}

fn try_compact(value: &Value) -> Option<Value> {
    let Value::Array(items) = value else {
        return None;
    };
    if items.is_empty() {
        return None;
    }
    if items.iter().all(Value::is_number) {
        return pack_f32_vector(&json_to_f32_vector(value)?).map(Value::String);
    }
    if items.iter().all(|item| {
        item.as_array()
            .is_some_and(|inner| !inner.is_empty() && inner.iter().all(Value::is_number))
    }) {
        let mut chunks = Vec::with_capacity(items.len());
        for item in items {
            chunks.push(Value::String(pack_f32_vector(&json_to_f32_vector(item)?)?));
        }
        return Some(Value::Array(chunks));
    }
    None
}

/// Expand packed strings back into JSON number arrays, recursively.
///
/// Response paths call this on the page (or the one document) they are
/// about to return. The memtable and the stored-values cache keep the
/// packed form.
pub fn expand_packed_f32_values(value: &mut Value) {
    if let Value::String(text) = value {
        if let Some(floats) = unpack_f32_vector(text) {
            *value = Value::Array(floats.into_iter().map(|f| Value::from(f as f64)).collect());
        }
        return;
    }
    match value {
        Value::Array(items) => {
            for item in items {
                expand_packed_f32_values(item);
            }
        }
        Value::Object(map) => {
            for child in map.values_mut() {
                expand_packed_f32_values(child);
            }
        }
        _ => {}
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn round_trip_preserves_f32_bits() {
        let values = [0.0_f32, -0.0, 1.0, -1.5, 1.0e-20, f32::MIN, f32::MAX];
        let packed = pack_f32_vector(&values).unwrap();
        assert!(packed.starts_with(PACKED_F32_PREFIX));
        assert_eq!(unpack_f32_vector(&packed).unwrap(), values);
    }

    #[test]
    fn rejects_non_finite_and_foreign_strings() {
        assert!(pack_f32_vector(&[]).is_none());
        assert!(pack_f32_vector(&[f32::NAN]).is_none());
        assert!(pack_f32_vector(&[f32::INFINITY]).is_none());
        assert!(unpack_f32_vector("xerj:f32:zz").is_none());
        assert!(unpack_f32_vector("hello").is_none());
        assert!(unpack_f32_vector("xerj:f32:0000000").is_none());
    }

    #[test]
    fn compact_then_expand_matches_the_number_array() {
        let mut pooled = json!([0.25, -2.0, 4.0]);
        compact_vector_value(&mut pooled);
        assert!(pooled.as_str().unwrap().starts_with(PACKED_F32_PREFIX));
        expand_packed_f32_values(&mut pooled);
        let back = json_to_f32_vector(&pooled).unwrap();
        assert_eq!(back, vec![0.25, -2.0, 4.0]);

        let mut chunks = json!([[1.0, 0.0], [0.0, 1.0]]);
        compact_vector_value(&mut chunks);
        assert!(chunks.as_array().unwrap()[0].is_string());
        expand_packed_f32_values(&mut chunks);
        assert_eq!(chunks[0].as_array().unwrap().len(), 2);
        assert_eq!(chunks[1].as_array().unwrap().len(), 2);
    }
}

//! The machine-resource policy — the one place that answers *how many cores*
//! and *how much memory* XERJ may take on the machine it is running on.
//!
//! Before this module the answers were scattered magic numbers: `.min(8)` in
//! the autoindex CLI, `(cores * 8).clamp(64, 512)` in the server, `cores / 8`
//! in three engine pools, a hardcoded `8 GiB` "system memory" in the governor
//! on every non-Linux host, and three `EngineConfig` knobs that nothing read
//! (issue #240). Each was defensible on its own; together they had no story,
//! and on a laptop they added up to a bad citizen.
//!
//! # The policy
//!
//! 1. **Latency-critical work gets the whole machine.** Search fan-out and
//!    bulk parse are what a user is waiting on; holding cores back there only
//!    makes the wait longer.
//! 2. **Background work gets a named reserve, not the whole machine.** Merges
//!    and flush side-cars have nobody waiting on them, so they run on a
//!    fraction of the cores and at a lower thread priority.
//! 3. **Memory is budgeted from what the machine actually has**, with an
//!    explicit slice left for the user — never from an assumed constant.
//! 4. **Every rule is a function here with its reason written down**, so the
//!    next tuning argument is about a number in one place instead of six.
//!
//! # Peer precedent (retrieved, not copied — see the reference-coding mandate)
//!
//! * `quickwit-common/src/cpus.rs:23-63` (Apache-2.0): core count comes from
//!   `QW_NUM_CPUS`, then `KUBERNETES_LIMITS_CPU`, then the OS, then a warned
//!   default — an env override ahead of the OS, and a *loud* fallback.
//! * `quickwit-common/src/runtimes.rs:89-110` (Apache-2.0): headroom scaled by
//!   machine size — all cores at 0..=3, `n - 1` at 4..=6, `n - 2` at 7+.
//!   Reserve as a function of the machine, never a flat cap.
//! * `quickwit-config/src/node_config/mod.rs` `default_merge_concurrency()`
//!   (Apache-2.0): background merges get `num_cpus * 2 / 3`.
//! * `meilisearch/crates/meilisearch/src/option.rs:818-821,885` (MIT core):
//!   indexing pool = `num_cpus / 2`, with the stated reason "the indexer
//!   avoids using more than half of a machine's total processing units. This
//!   ensures Meilisearch is always ready to perform searches, even while you
//!   are updating an index"; `option.rs:1103-1106` budgets indexing memory at
//!   two thirds of (cgroup-aware) total RAM.
//! * `tantivy/src/indexer/index_writer.rs:32-36,285-291` (MIT): the writer is
//!   capped at 8 threads, and a memory budget below the per-thread minimum is
//!   **rejected with an error** rather than silently clamped — the same
//!   discipline this module applies to out-of-range knobs.
//!
//! What XERJ takes from that is the *shape* — full parallelism on the path a
//! user waits on, a declared reserve for the path nobody waits on, budgets
//! derived from the real machine — not the specific constants, which are tied
//! to those engines' own measurements.

use std::sync::OnceLock;

const MIB: u64 = 1024 * 1024;
const GIB: u64 = 1024 * MIB;

/// Environment override for the detected core count, honoured ahead of the OS
/// so a container or a CI runner can pin it (quickwit precedent, `cpus.rs:20`).
pub const NUM_CPUS_ENV: &str = "XERJ_NUM_CPUS";

// ─────────────────────────────────────────────────────────────────────────────
// Cores
// ─────────────────────────────────────────────────────────────────────────────

/// What a pool is for. This is the input to every thread-count decision, so a
/// new pool has to say which side of the latency/background line it is on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Workload {
    /// Someone is waiting on it: search fan-out, bulk parse/analyze/insert,
    /// client-side content hashing and sniffing. Gets every core.
    Latency,
    /// Useful work with no client waiting, but which the user's next request
    /// depends on: flush side-cars, segment finalisation. Gets every core, at
    /// a lower thread priority, because holding it back delays visibility.
    Background,
    /// Pure maintenance nobody is waiting on: merges, compaction. Gets a
    /// declared fraction of the machine so it can never take the box over.
    Maintenance,
}

/// Logical cores XERJ may use, in the order the answer is trusted:
/// `XERJ_NUM_CPUS`, the cgroup CPU quota (Linux containers), the OS, then a
/// warned fallback of 4.
///
/// Cached: the answer cannot change usefully within a process, and the cgroup
/// read is a file parse.
pub fn cores() -> usize {
    static CORES: OnceLock<usize> = OnceLock::new();
    *CORES.get_or_init(|| {
        let (n, note) = resolve_cores(
            std::env::var(NUM_CPUS_ENV).ok().as_deref(),
            cgroup_cpu_quota(),
            std::thread::available_parallelism().map(|n| n.get()).ok(),
        );
        if let Some(note) = note {
            warn_once(&note);
        }
        n
    })
}

/// Report a policy problem on both channels.
///
/// The server installs a `tracing` subscriber; `xerj autoindex` does not, so a
/// warning emitted only through `tracing` is invisible to exactly the user most
/// likely to have set `XERJ_NUM_CPUS` wrong. These fire at most once per process
/// and only when something is misconfigured or unreadable, so the duplicate line
/// in a server log is a fair price for never losing the message.
fn warn_once(message: &str) {
    tracing::warn!("{message}");
    eprintln!("xerj: {message}");
}

/// Pure core-count resolution — the tested half of [`cores`].
///
/// Returns the count and an optional warning: an unusable `XERJ_NUM_CPUS` or a
/// machine whose core count cannot be detected must say so, never resolve
/// silently to a number the operator did not ask for (issue #204's class).
fn resolve_cores(
    env: Option<&str>,
    cgroup_quota: Option<usize>,
    os: Option<usize>,
) -> (usize, Option<String>) {
    if let Some(raw) = env.map(str::trim).filter(|s| !s.is_empty()) {
        return match raw.parse::<usize>() {
            Ok(n) if n >= 1 => (n, None),
            _ => (
                os.unwrap_or(4),
                Some(format!(
                    "{NUM_CPUS_ENV}={raw} is not a positive integer; ignoring it and using the \
                     detected core count instead"
                )),
            ),
        };
    }
    match (os, cgroup_quota) {
        // A cgroup CPU quota is a hard ceiling: the kernel throttles past it,
        // so sizing pools off the host's core count only builds queues.
        (Some(os), Some(q)) => (q.min(os).max(1), None),
        (Some(os), None) => (os, None),
        (None, Some(q)) => (q.max(1), None),
        (None, None) => (
            4,
            Some(
                "could not detect the number of CPUs on this machine; assuming 4 — set \
                 XERJ_NUM_CPUS to the real count"
                    .into(),
            ),
        ),
    }
}

/// Whole cores permitted by this process's cgroup CPU quota, if any (cgroup v2
/// `cpu.max`, then cgroup v1 `cpu.cfs_quota_us`/`cpu.cfs_period_us`). A
/// fractional quota rounds up to 1 — half a core still runs one thread.
#[cfg(target_os = "linux")]
fn cgroup_cpu_quota() -> Option<usize> {
    if let Ok(s) = std::fs::read_to_string("/sys/fs/cgroup/cpu.max") {
        let mut parts = s.split_whitespace();
        let quota = parts.next()?;
        let period: u64 = parts.next()?.parse().ok()?;
        if quota != "max" && period > 0 {
            let quota: u64 = quota.parse().ok()?;
            return Some(quota.div_ceil(period).max(1) as usize);
        }
        return None;
    }
    let quota: i64 = std::fs::read_to_string("/sys/fs/cgroup/cpu/cpu.cfs_quota_us")
        .ok()?
        .trim()
        .parse()
        .ok()?;
    let period: i64 = std::fs::read_to_string("/sys/fs/cgroup/cpu/cpu.cfs_period_us")
        .ok()?
        .trim()
        .parse()
        .ok()?;
    (quota > 0 && period > 0).then(|| (quota as u64).div_ceil(period as u64).max(1) as usize)
}

#[cfg(not(target_os = "linux"))]
fn cgroup_cpu_quota() -> Option<usize> {
    None
}

/// Threads for a pool serving `workload` on this machine.
pub fn threads_for(workload: Workload) -> usize {
    threads_for_cores(workload, cores())
}

/// Pure thread-count rule — the tested half of [`threads_for`].
///
/// `Latency` and `Background` get every core: XERJ's measured ingest/read
/// tuning separates them by *thread priority*, not by width (see the pool
/// docs in `xerj-engine/src/lib.rs`), and narrowing them would trade
/// throughput for nothing. `Maintenance` gets `max(2, cores / 8)` — the width
/// measured on the 1M×c8 ingest benchmark, where an all-core merge pool stalled
/// ingest for 17.5 s per merge pass.
pub const fn threads_for_cores(workload: Workload, cores: usize) -> usize {
    let cores = if cores == 0 { 1 } else { cores };
    match workload {
        Workload::Latency | Workload::Background => cores,
        Workload::Maintenance => {
            let eighth = cores / 8;
            if eighth < 2 {
                if cores < 2 {
                    1
                } else {
                    2
                }
            } else {
                eighth
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Per-index concurrent-map sharding
// ─────────────────────────────────────────────────────────────────────────────

/// Ceiling on the shard count of a **per-index** concurrent map (#873).
///
/// `dashmap`'s own default is `(available_parallelism * 4).next_power_of_two()`,
/// which is the right answer for a map there is ONE of per process and the
/// wrong answer for a map there is one of per index: the shard array is
/// `Box<[CachePadded<RwLock<HashMap>>]>`, 128 bytes per shard on x86_64,
/// written at construction and therefore resident forever. Every open index
/// carries ~23 of these maps, so on a 32-core host the default cost 128 × 128 B
/// × 23 ≈ 368 KiB per index before a single document existed — measured as the
/// largest single term in the idle-RSS floor of #873.
///
/// 16 is a ceiling, not a target: a machine whose dashmap default is already
/// smaller keeps that smaller value. Striping wider than this buys nothing here
/// because the contention these maps see is bounded by the concurrency on ONE
/// index, and it is read-dominated — hydration inserts are rare, and readers
/// share the shard lock.
pub const MAX_PER_INDEX_MAP_SHARDS: usize = 16;

/// Shard count for a concurrent map that exists once per index.
///
/// Never larger than the `dashmap` default this replaced, so no machine ends up
/// with *more* striping than before; capped at [`MAX_PER_INDEX_MAP_SHARDS`] so
/// a 64-core host does not pay 256-way striping on every cache of every open
/// index. Must stay a power of two — `DashMap::with_shard_amount` panics
/// otherwise.
pub fn per_index_map_shards() -> usize {
    static SHARDS: OnceLock<usize> = OnceLock::new();
    *SHARDS.get_or_init(|| per_index_map_shards_for(cores()))
}

/// Pure rule behind [`per_index_map_shards`] — the tested half.
pub const fn per_index_map_shards_for(cores: usize) -> usize {
    let cores = if cores == 0 { 1 } else { cores };
    // `dashmap::default_shard_amount()`, then capped.
    let dashmap_default = (cores * 4).next_power_of_two();
    if dashmap_default < MAX_PER_INDEX_MAP_SHARDS {
        dashmap_default
    } else {
        MAX_PER_INDEX_MAP_SHARDS
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Thread priority
// ─────────────────────────────────────────────────────────────────────────────

/// Where a pool sits on the maintenance ladder, i.e. how far below foreground
/// work its threads should be scheduled.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Deprioritize {
    /// Ingest parse/analyze/insert — one step below reads.
    Ingest,
    /// Flush side-cars and finalisation — below ingest.
    Background,
    /// Merges — the bottom of the ladder.
    Maintenance,
}

/// The platform-specific action that implements a rung of the ladder.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PriorityAction {
    /// Leave the thread at normal priority.
    None,
    /// `nice(n)` on the calling **thread** — Linux semantics, where the nice
    /// value is a per-task attribute.
    NiceThread(i32),
    /// `setpriority(PRIO_DARWIN_THREAD, 0, PRIO_DARWIN_BG)` — Darwin's
    /// thread-scoped background tier.
    DarwinThreadBackground,
}

/// The platforms whose scheduling semantics differ enough to matter here.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Platform {
    Linux,
    MacOs,
    Other,
}

/// This build's platform.
pub const HOST_PLATFORM: Platform = if cfg!(target_os = "linux") {
    Platform::Linux
} else if cfg!(target_os = "macos") {
    Platform::MacOs
} else {
    Platform::Other
};

/// The ladder, as a decision table — the tested half of
/// [`deprioritize_current_thread`].
///
/// **Why this is not just `nice()` everywhere.** POSIX `nice()` adjusts the
/// *process*; Linux makes it a per-task (per-thread) attribute, which is what
/// the measured ingest/background/merge ladder relies on. Darwin keeps the
/// POSIX meaning, so calling `nice(5)`, `nice(10)`, `nice(15)` from pool
/// `start_handler`s there does not separate the three pools at all — it
/// ratchets the *whole server process*, search threads included, toward the
/// nice ceiling as pool threads start. That is the opposite of the intent, on
/// the platform whose users reported the slowness (#240).
///
/// Darwin's replacement is thread-scoped: `PRIO_DARWIN_THREAD` with
/// `PRIO_DARWIN_BG` moves *this thread* into the background tier. It is an
/// on/off tier, not a ladder rung, and it throttles I/O as well as CPU — right
/// for merges, wrong for ingest and flush side-cars (a user's next search waits
/// on those). So on macOS only the bottom rung is applied, and the two upper
/// rungs stay at normal priority rather than being faked with a call that would
/// deprioritize the whole process.
///
/// This decision table is reasoned from documented POSIX/Darwin semantics and
/// the libc surface; it has **not** been measured on Apple hardware.
pub const fn priority_action(platform: Platform, class: Deprioritize) -> PriorityAction {
    match platform {
        Platform::Linux => match class {
            Deprioritize::Ingest => PriorityAction::NiceThread(5),
            Deprioritize::Background => PriorityAction::NiceThread(10),
            Deprioritize::Maintenance => PriorityAction::NiceThread(15),
        },
        Platform::MacOs => match class {
            Deprioritize::Ingest | Deprioritize::Background => PriorityAction::None,
            Deprioritize::Maintenance => PriorityAction::DarwinThreadBackground,
        },
        // Windows and the BSDs: no per-thread nice with the semantics above.
        Platform::Other => PriorityAction::None,
    }
}

/// Apply the ladder to the calling thread. Call it from a pool's
/// `start_handler`, once per pool thread.
pub fn deprioritize_current_thread(class: Deprioritize) {
    match priority_action(HOST_PLATFORM, class) {
        PriorityAction::None => {}
        PriorityAction::NiceThread(_n) => {
            #[cfg(all(unix, not(target_os = "macos")))]
            // SAFETY: `nice` takes an int and touches only the caller's
            // scheduling attributes; on Linux that is this thread.
            unsafe {
                let _ = libc::nice(_n);
            }
        }
        PriorityAction::DarwinThreadBackground => {
            #[cfg(target_os = "macos")]
            // SAFETY: `setpriority` with PRIO_DARWIN_THREAD and `who = 0`
            // addresses the calling thread only.
            unsafe {
                let _ = libc::setpriority(libc::PRIO_DARWIN_THREAD, 0, libc::PRIO_DARWIN_BG);
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Memory
// ─────────────────────────────────────────────────────────────────────────────

/// Total physical RAM, or `None` when this platform has no probe here.
///
/// `None` means *unknown*, and callers must treat it as unknown — the bug this
/// replaces was a non-Linux fallback that returned a fictional 8 GiB, so every
/// derived budget on a 64 GB Mac was sized for a machine eight times smaller
/// (#240 §7).
pub fn total_memory_bytes() -> Option<u64> {
    static TOTAL: OnceLock<Option<u64>> = OnceLock::new();
    *TOTAL.get_or_init(|| {
        let total = probe_total_memory();
        if total.is_none() {
            warn_once(&format!(
                "cannot read this machine's total RAM on {}; memory budgets fall back to \
                 conservative defaults — set them explicitly (limits.max_total_memtable_mb, \
                 autoindex --workers/--bulk-mb) if that is wrong",
                std::env::consts::OS
            ));
        }
        total
    })
}

/// RAM available for a new allocation without swapping — Linux `MemAvailable`.
/// `None` where unknown (including macOS: Darwin exposes free/inactive/
/// compressed page counts through `host_statistics64`, which is not in the
/// pinned `libc` surface, and guessing from `hw.memsize` alone would be a
/// fabricated number).
pub fn available_memory_bytes() -> Option<u64> {
    probe_available_memory()
}

/// Resident set size of this process (on macOS its physical footprint, see
/// the macOS `probe_rss`), or `None` where this platform has no probe.
/// `None` must disable an RSS-driven decision, never read as zero.
pub fn current_rss_bytes() -> Option<u64> {
    probe_rss()
}

