/// Parse one `kB` field out of `/proc/meminfo`, in bytes.
#[cfg(any(target_os = "linux", test))]
fn meminfo_field(meminfo: &str, key: &str) -> Option<u64> {
    for line in meminfo.lines() {
        if let Some(rest) = line.trim_start().strip_prefix(key) {
            let kb: u64 = rest.split_whitespace().next()?.parse().ok()?;
            return Some(kb.saturating_mul(1024));
        }
    }
    None
}

#[cfg(target_os = "linux")]
fn probe_rss() -> Option<u64> {
    let statm = std::fs::read_to_string("/proc/self/statm").ok()?;
    let pages: u64 = statm.split_whitespace().nth(1)?.parse().ok()?;
    // SAFETY: `sysconf` reads a system constant.
    let page = unsafe { libc::sysconf(libc::_SC_PAGESIZE) };
    let page = if page > 0 { page as u64 } else { 4096 };
    Some(pages.saturating_mul(page))
}

/// macOS: the process's physical footprint (`ri_phys_footprint`), not its
/// resident size.
///
/// Resident size leaves out the pages the compressor has taken and the pages
/// swapped out, which are still this process's memory, and it counts clean
/// file-backed pages (mmapped segments) the kernel can drop at will. Under a
/// 1 GiB cap a node read 0.8 GB resident while vmmap showed a 2.2 GB
/// footprint, 1.3 GB of it compressed, so the breaker kept admitting writes;
/// and its "released" edges followed the compressor, not a drain. The
/// footprint is what `/usr/bin/time -l` reports as "peak memory footprint"
/// and what the kernel's memory-pressure kills act on.
#[cfg(target_os = "macos")]
fn probe_rss() -> Option<u64> {
    let mut info = std::mem::MaybeUninit::<libc::rusage_info_v2>::zeroed();
    // SAFETY: with flavor RUSAGE_INFO_V2, `proc_pid_rusage` writes one
    // `rusage_info_v2` into the buffer it is given and returns 0, or returns
    // -1 and writes nothing usable.
    let rc = unsafe {
        libc::proc_pid_rusage(
            std::process::id() as libc::c_int,
            libc::RUSAGE_INFO_V2,
            info.as_mut_ptr() as *mut libc::rusage_info_t,
        )
    };
    if rc != 0 {
        return None;
    }
    // SAFETY: proc_pid_rusage returned 0, so it filled the struct.
    Some(unsafe { info.assume_init() }.ri_phys_footprint)
}

#[cfg(target_os = "windows")]
fn probe_rss() -> Option<u64> {
    win_mem::rss()
}

#[cfg(not(any(target_os = "linux", target_os = "macos", target_os = "windows")))]
fn probe_rss() -> Option<u64> {
    None
}

#[cfg(target_os = "macos")]
fn sysctl_u64(name: &std::ffi::CStr) -> Option<u64> {
    let mut value: u64 = 0;
    let mut len = std::mem::size_of::<u64>();
    // SAFETY: `name` is NUL-terminated, and the out-buffer length is the size
    // of the buffer being written.
    let rc = unsafe {
        libc::sysctlbyname(
            name.as_ptr(),
            &mut value as *mut u64 as *mut libc::c_void,
            &mut len,
            std::ptr::null_mut(),
            0,
        )
    };
    (rc == 0 && len == std::mem::size_of::<u64>() && value > 0).then_some(value)
}

/// How many bytes a **client-side** XERJ tool (autoindex) may allocate on a
/// machine whose owner is also using it.
///
/// The server's own admission budgets are cgroup-aware and live in
/// `xerj-engine::governor`; this is the laptop-citizen rule for the client:
///
/// ```text
/// reserve = max(1 GiB, total / 8)                 // left for the user
/// safe    = min(available - reserve, total / 2)   // never more than half
/// ```
///
/// Half of RAM as the ceiling follows the same reasoning meilisearch gives for
/// its two-thirds indexing budget (`option.rs:1103-1106`) — a machine that is
/// also serving its owner should not have its page cache evicted by a
/// background indexer.
///
/// `None` means **this machine's RAM is not knowable here** (Windows, FreeBSD,
/// …: [`total_memory_bytes`] has no probe), and callers must read it as "no
/// memory-derived limit", never as "a small limit". An earlier revision of this
/// function returned a 1 GiB fallback instead, and the result was that a
/// Windows box with 64 GB of RAM was budgeted as a 1 GiB machine — a phantom
/// budget that no code on that platform enforces. meilisearch keeps the same
/// shape for the same reason: `total_memory_bytes() -> Option<u64>` is `None`
/// on an unsupported system (`crates/meilisearch/src/option.rs:1135`) and the
/// derived per-thread budget stays an `Option` all the way down, where `None`
/// means unbounded rather than minimal
/// (`crates/milli/src/update/index_documents/helpers/grenad_helpers.rs:122`).
pub fn memory_safe_zone_bytes() -> Option<u64> {
    total_memory_bytes().map(|total| safe_zone(total, available_memory_bytes()))
}

/// Pure safe-zone rule — the tested half of [`memory_safe_zone_bytes`].
fn safe_zone(total: u64, available: Option<u64>) -> u64 {
    let reserve = (total / 8).max(GIB);
    let headroom = available.unwrap_or(total).saturating_sub(reserve);
    headroom.min(total / 2).max(256 * MIB)
}

/// One Windows commit reading. Bytes. A zero [`WindowsCommitSample::commit_limit`]
/// means the probe did not return commit figures — the budget must then stay
/// on physical RAM rather than invent a tight cap from a failed read.
///
/// Field meanings follow `MEMORYSTATUSEX` (the struct this file already fills
/// via `GlobalMemoryStatusEx`, #1766):
///
/// * `total_phys` — `ullTotalPhys`
/// * `commit_limit` — `ullTotalPageFile`, the commit limit for the system or
///   this process, whichever is smaller
/// * `available_commit` — `ullAvailPageFile`, how many more bytes this process
///   may commit before `VirtualAlloc` fails
/// * `process_commit` — `PROCESS_MEMORY_COUNTERS::PagefileUsage`, charged with
///   or without a pagefile
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WindowsCommitSample {
    pub total_phys: u64,
    pub commit_limit: u64,
    pub available_commit: u64,
    pub process_commit: u64,
}

/// What the governor may treat as the machine after Windows commit charge.
///
/// The AUTO tier is still chosen from physical RAM (or a cgroup). This budget
/// is a second ceiling applied afterwards: a pagefile that covers RAM must not
/// move the 64 GiB / 128 GiB tier steps, and a commit limit a little under RAM
/// (the kernel's own holdback, with nothing else charged) must not either.
/// The ceiling binds when what this process can still reach, minus a reserve,
/// is tighter than the tier.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WindowsCommitBudget {
    /// Bytes the process cap may not exceed. Equal to physical RAM when
    /// commit is not the scarce resource.
    pub effective_bytes: u64,
    /// `effective_bytes` is below physical RAM because commit is scarce.
    pub commit_bound: bool,
    pub commit_limit: u64,
    pub available_commit: u64,
    pub process_commit: u64,
    /// `min(commit_limit, process_commit + available_commit)` — the size at
    /// which the next commit fails if nothing else allocates.
    pub committable: u64,
    /// Held back so a 95% watermark and one flush allocation land before the
    /// allocator abort. Also the live threshold: available commit below this
    /// engages the breaker. `0` when commit figures are missing.
    pub reserve_bytes: u64,
}

/// Bytes of commit held back from the ceiling.
///
/// One quarter of what this process can still reach, clamped to
/// [512 MiB, 2 GiB]. The floor covers the ~100 MiB flush allocation that
/// aborted a 16 GiB no-pagefile run (#1122, field report #2174) plus the
/// sampler interval. The quarter, not the watermark's own 5%, is the gap:
/// that run died with RSS around 3.3–3.7 GiB while the engine was tracking
/// ~0.8 GiB, so a cap sitting on the commit limit itself is already too late.
fn windows_commit_reserve(committable: u64) -> u64 {
    const MIN_RESERVE: u64 = 512 * MIB;
    const MAX_RESERVE: u64 = 2 * GIB;
    (committable / 4).clamp(MIN_RESERVE, MAX_RESERVE)
}

/// Pure commit ceiling. Tested with injected numbers; the live probe is
/// [`windows_commit_sample`].
pub fn windows_commit_budget(sample: WindowsCommitSample) -> WindowsCommitBudget {
    let total = sample.total_phys.max(1);
    if sample.commit_limit == 0 {
        return WindowsCommitBudget {
            effective_bytes: total,
            commit_bound: false,
            commit_limit: 0,
            available_commit: sample.available_commit,
            process_commit: sample.process_commit,
            committable: total,
            reserve_bytes: 0,
        };
    }
    let committable = sample
        .commit_limit
        .min(
            sample
                .process_commit
                .saturating_add(sample.available_commit),
        )
        .max(1);
    let reserve = windows_commit_reserve(committable);
    // Nothing left to give: the live available-commit check rejects writes.
    // The floor keeps a derived memtable budget from becoming 0, which would
    // disable that breaker rather than tighten it.
    const FLOOR: u64 = 256 * MIB;
    let after_reserve = if committable <= reserve {
        FLOOR.min(committable).max(1)
    } else {
        committable.saturating_sub(reserve).max(1)
    };
    // A gap smaller than the reserve is not "the machine is full". Commit is
    // scarce only when the post-reserve ceiling is actually under physical RAM.
    let commit_bound = after_reserve < total;
    WindowsCommitBudget {
        effective_bytes: if commit_bound { after_reserve } else { total },
        commit_bound,
        commit_limit: sample.commit_limit,
        available_commit: sample.available_commit,
        process_commit: sample.process_commit,
        committable,
        reserve_bytes: reserve,
    }
}

/// Live Windows commit sample, or `None` where this platform has no probe
/// (Linux, macOS) and where `GlobalMemoryStatusEx` fails.
pub fn windows_commit_sample() -> Option<WindowsCommitSample> {
    #[cfg(target_os = "windows")]
    {
        let status = win_mem::status()?;
        Some(WindowsCommitSample {
            total_phys: status.ullTotalPhys,
            commit_limit: status.ullTotalPageFile,
            available_commit: status.ullAvailPageFile,
            process_commit: win_mem::commit_charge().unwrap_or(0),
        })
    }
    #[cfg(not(target_os = "windows"))]
    {
        None
    }
}

/// How many more bytes this process may commit, or `None` off Windows.
pub fn available_commit_bytes() -> Option<u64> {
    windows_commit_sample().map(|s| s.available_commit)
}

/// This process's commit charge, or `None` off Windows.
pub fn process_commit_charge_bytes() -> Option<u64> {
    #[cfg(target_os = "windows")]
    {
        win_mem::commit_charge()
    }
    #[cfg(not(target_os = "windows"))]
    {
        None
    }
}

/// One line describing what this policy decided, for a startup log or a
/// `--json` run summary. Sizes are in MiB.
pub fn describe() -> String {
    let mib = |b: Option<u64>| match b {
        Some(b) => format!("{}", b / MIB),
        None => "unknown".to_string(),
    };
    format!(
        "cores={} ram_total_mib={} ram_available_mib={} safe_zone_mib={}",
        cores(),
        mib(total_memory_bytes()),
        mib(available_memory_bytes()),
        mib(memory_safe_zone_bytes()),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn env_override_beats_the_os_and_a_bad_value_is_reported() {
        assert_eq!(resolve_cores(Some("6"), None, Some(64)), (6, None));
        assert_eq!(resolve_cores(Some(" 6 "), None, Some(64)), (6, None));
        // Accepted-and-ignored is the class this repo keeps re-finding (#204):
        // an unusable override must be reported, not silently discarded.
        let (n, note) = resolve_cores(Some("many"), None, Some(64));
        assert_eq!(n, 64);
        assert!(note.unwrap().contains("XERJ_NUM_CPUS=many"));
        let (n, note) = resolve_cores(Some("0"), None, Some(64));
        assert_eq!(n, 64);
        assert!(note.is_some());
        // Empty means "unset", not "invalid".
        assert_eq!(resolve_cores(Some(""), None, Some(8)), (8, None));
    }

    #[test]
    fn a_cgroup_quota_caps_the_host_core_count() {
        assert_eq!(resolve_cores(None, Some(2), Some(64)), (2, None));
        // A quota larger than the machine is not a licence to oversubscribe.
        assert_eq!(resolve_cores(None, Some(128), Some(8)), (8, None));
        assert_eq!(resolve_cores(None, None, Some(8)), (8, None));
        let (n, note) = resolve_cores(None, None, None);
        assert_eq!(n, 4);
        assert!(note.is_some(), "an undetectable machine must say so");
    }

    /// #873 - a per-index concurrent map must not stripe with the machine.
    ///
    /// The rule is asserted at explicit core counts rather than at the host's,
    /// because a 2-core CI runner would otherwise agree with the unfixed
    /// behaviour and report a green that means nothing.
    #[test]
    fn a_per_index_map_is_capped_and_never_wider_than_the_dashmap_default() {
        // The value this replaced, restated so the comparison is explicit.
        let dashmap_default = |cores: usize| (cores * 4).next_power_of_two();
        for cores in [1usize, 2, 3, 4, 8, 12, 16, 32, 64, 128] {
            let n = per_index_map_shards_for(cores);
            assert!(n.is_power_of_two(), "cores={cores} n={n} must be pow2");
            assert!(n >= 1, "cores={cores}");
            assert!(
                n <= MAX_PER_INDEX_MAP_SHARDS,
                "cores={cores} n={n} exceeds the cap"
            );
            assert!(
                n <= dashmap_default(cores),
                "cores={cores}: must never stripe WIDER than dashmap would have"
            );
        }
        // Below the cap the machine still decides; above it, it does not.
        assert_eq!(per_index_map_shards_for(1), 4);
        assert_eq!(per_index_map_shards_for(2), 8);
        assert_eq!(per_index_map_shards_for(4), 16);
        assert_eq!(per_index_map_shards_for(8), 16);
        assert_eq!(per_index_map_shards_for(64), 16);
        // A machine that reports zero cores must not produce a zero shard
        // count: `DashMap::with_shard_amount(0)` panics.
        assert_eq!(per_index_map_shards_for(0), 4);
        // The cached host answer obeys the same rule.
        assert_eq!(per_index_map_shards(), per_index_map_shards_for(cores()));
    }

    #[test]
    fn latency_work_gets_every_core_and_maintenance_gets_a_reserve() {
        for cores in [1usize, 2, 4, 8, 12, 16, 32, 64] {
            assert_eq!(threads_for_cores(Workload::Latency, cores), cores);
            assert_eq!(threads_for_cores(Workload::Background, cores), cores);
            let maint = threads_for_cores(Workload::Maintenance, cores);
            assert!(maint >= 1 && maint <= cores, "cores={cores} maint={maint}");
            assert!(
                maint <= (cores / 2).max(2),
                "maintenance must never take the machine over: cores={cores} maint={maint}"
            );
        }
        // The measured widths this replaces, preserved exactly.
        assert_eq!(threads_for_cores(Workload::Maintenance, 32), 4);
        assert_eq!(threads_for_cores(Workload::Maintenance, 8), 2);
        assert_eq!(threads_for_cores(Workload::Maintenance, 1), 1);
        assert_eq!(threads_for_cores(Workload::Latency, 0), 1);
    }

    #[test]
    fn macos_never_uses_process_wide_nice_for_the_ladder() {
        // The #240 §5 defect: `nice()` is per-process on Darwin, so using it
        // from pool start handlers deprioritizes search along with merges.
        for class in [
            Deprioritize::Ingest,
            Deprioritize::Background,
            Deprioritize::Maintenance,
        ] {
            assert!(
                !matches!(
                    priority_action(Platform::MacOs, class),
                    PriorityAction::NiceThread(_)
                ),
                "{class:?} must not use nice() on macOS"
            );
        }
        assert_eq!(
            priority_action(Platform::MacOs, Deprioritize::Maintenance),
            PriorityAction::DarwinThreadBackground
        );
        // Ingest and flush side-cars stay at normal priority there: Darwin's
        // background tier throttles I/O, and a user's next search waits on them.
        assert_eq!(
            priority_action(Platform::MacOs, Deprioritize::Ingest),
            PriorityAction::None
        );
        assert_eq!(
            priority_action(Platform::MacOs, Deprioritize::Background),
            PriorityAction::None
        );
        // Linux keeps the measured ladder.
        assert_eq!(
            priority_action(Platform::Linux, Deprioritize::Ingest),
            PriorityAction::NiceThread(5)
        );
        assert_eq!(
            priority_action(Platform::Linux, Deprioritize::Background),
            PriorityAction::NiceThread(10)
        );
        assert_eq!(
            priority_action(Platform::Linux, Deprioritize::Maintenance),
            PriorityAction::NiceThread(15)
        );
    }

    #[test]
    fn meminfo_parsing_reads_total_and_available() {
        let sample =
            "MemTotal:       16316908 kB\nMemFree:         1234 kB\nMemAvailable:    8000000 kB\n";
        assert_eq!(meminfo_field(sample, "MemTotal:"), Some(16_316_908 * 1024));
        assert_eq!(
            meminfo_field(sample, "MemAvailable:"),
            Some(8_000_000 * 1024)
        );
        assert_eq!(meminfo_field(sample, "Bogus:"), None);
        assert_eq!(meminfo_field("MemTotal:  garbage\n", "MemTotal:"), None);
    }

    #[test]
    fn the_safe_zone_leaves_the_user_a_reserve_and_never_exceeds_half() {
        // 16 GiB laptop with 10 GiB available: reserve 2 GiB, ceiling 8 GiB.
        assert_eq!(safe_zone(16 * GIB, Some(10 * GIB)), 8 * GIB);
        // Same laptop under pressure: only what is actually free, minus reserve.
        assert_eq!(safe_zone(16 * GIB, Some(4 * GIB)), 2 * GIB);
        // Availability unknown (macOS): fall back to the half-of-RAM ceiling.
        assert_eq!(safe_zone(16 * GIB, None), 8 * GIB);
        // Small container: the 1 GiB floor of the reserve still applies.
        assert_eq!(safe_zone(2 * GIB, Some(2 * GIB)), GIB);
        // Never zero, however tight the machine.
        assert_eq!(safe_zone(512 * MIB, Some(0)), 256 * MIB);
        for total in [GIB, 4 * GIB, 16 * GIB, 128 * GIB] {
            assert!(safe_zone(total, None) <= total / 2 || total < 2 * GIB);
        }
    }

    #[test]
    fn this_machine_probes_are_sane() {
        // Not a fixed expectation — a probe that returns something absurd is
        // the bug (the 8 GiB constant this replaces would fail on this box).
        let cores = cores();
        assert!((1..=4096).contains(&cores));
        if let Some(total) = total_memory_bytes() {
            assert!(total >= 256 * MIB, "implausible total RAM: {total}");
            assert!(memory_safe_zone_bytes().expect("probeable RAM has a safe zone") <= total);
        } else {
            // Unknown must stay unknown: a fabricated small budget here is the
            // Windows PDF-throttling bug this API shape exists to prevent.
            assert_eq!(memory_safe_zone_bytes(), None);
        }
        #[cfg(any(target_os = "linux", target_os = "macos", target_os = "windows"))]
        {
            let rss = current_rss_bytes().expect("RSS must be probeable here");
            assert!(rss > 0, "a running process has non-zero RSS");
            assert_eq!(
                available_memory_bytes().is_some(),
                cfg!(any(target_os = "linux", target_os = "windows"))
            );
        }
    }

    #[test]
    fn windows_commit_sample_is_absent_off_windows() {
        #[cfg(not(target_os = "windows"))]
        {
            assert!(windows_commit_sample().is_none());
            assert!(available_commit_bytes().is_none());
            assert!(process_commit_charge_bytes().is_none());
        }
        #[cfg(target_os = "windows")]
        {
            if let Some(sample) = windows_commit_sample() {
                assert!(sample.total_phys >= 256 * MIB);
                let budget = windows_commit_budget(sample);
                assert!(budget.effective_bytes > 0);
                assert!(budget.effective_bytes <= sample.total_phys.max(1));
            }
        }
    }

    /// #1122 / field report #2174: 16 GiB RAM, no pagefile (commit limit ≈
    /// physical), ~12 GiB already charged by other processes, so about 4 GiB
    /// is still committable. The physical-RAM tier would hand this process an
    /// 8 GiB cap. The commit ceiling must sit under the abort line by enough
    /// for the ~100 MiB flush that killed that run.
    #[test]
    fn a_pagefileless_16gib_box_is_capped_by_available_commit() {
        let sample = WindowsCommitSample {
            total_phys: 16 * GIB,
            commit_limit: 16 * GIB,
            available_commit: 4 * GIB,
            process_commit: 200 * MIB,
        };
        let budget = windows_commit_budget(sample);
        let committable = 4 * GIB + 200 * MIB;
        assert_eq!(budget.committable, committable);
        assert!(budget.commit_bound);
        assert!(budget.reserve_bytes >= 512 * MIB);
        assert!(budget.reserve_bytes <= 2 * GIB);
        assert_eq!(budget.effective_bytes, committable - budget.reserve_bytes);
        // Quarter of 4.2 GiB, inside the clamp: the exact reserve this case
        // must keep, so a later edit cannot silently eat the headroom.
        assert_eq!(budget.reserve_bytes, committable / 4);
        assert_eq!(budget.effective_bytes, 3_378_511_872);
        assert!(
            budget.effective_bytes < 8 * GIB,
            "the 8 GiB physical-RAM tier is above what Windows will commit"
        );
        let watermark = budget.effective_bytes * 95 / 100;
        let headroom = budget.committable - watermark;
        assert!(
            headroom >= 100 * MIB,
            "the field report's 100 MiB flush must fit under the abort line, headroom={headroom}"
        );
        assert!(
            headroom >= 512 * MIB,
            "sampler lag needs more than the watermark's own 5%, headroom={headroom}"
        );
    }

    #[test]
    fn ample_commit_does_not_move_the_physical_tier_input() {
        // 64 GiB with a pagefile: commit limit and available commit both sit
        // above RAM. The budget must hand back physical RAM unchanged so the
        // 16 GiB AUTO step (64 GiB ≤ effective < 128 GiB) stays put.
        let covered = windows_commit_budget(WindowsCommitSample {
            total_phys: 64 * GIB,
            commit_limit: 96 * GIB,
            available_commit: 80 * GIB,
            process_commit: 512 * MIB,
        });
        assert!(!covered.commit_bound);
        assert_eq!(covered.effective_bytes, 64 * GIB);
        assert!(covered.reserve_bytes >= 512 * MIB);

        // 128 GiB, same shape: the 32 GiB step's input is physical RAM.
        let big = windows_commit_budget(WindowsCommitSample {
            total_phys: 128 * GIB,
            commit_limit: 200 * GIB,
            available_commit: 180 * GIB,
            process_commit: GIB,
        });
        assert!(!big.commit_bound);
        assert_eq!(big.effective_bytes, 128 * GIB);

        // No pagefile, but the machine is otherwise idle: commit limit sits a
        // little under RAM (kernel holdback). That gap must not by itself
        // pull a 16 GiB box's ceiling under the 8 GiB tier.
        let idle = windows_commit_budget(WindowsCommitSample {
            total_phys: 16 * GIB,
            commit_limit: 16 * GIB - 256 * MIB,
            available_commit: 15 * GIB,
            process_commit: 200 * MIB,
        });
        assert!(
            idle.effective_bytes >= 8 * GIB,
            "idle no-pagefile box: {:?}",
            idle
        );
    }

    #[test]
    fn a_failed_commit_probe_does_not_invent_a_tight_cap() {
        let failed = windows_commit_budget(WindowsCommitSample {
            total_phys: 16 * GIB,
            commit_limit: 0,
            available_commit: 0,
            process_commit: 0,
        });
        assert!(!failed.commit_bound);
        assert_eq!(failed.effective_bytes, 16 * GIB);
        assert_eq!(failed.reserve_bytes, 0);
    }

    #[test]
    fn no_available_commit_engages_the_reserve_immediately() {
        let full = windows_commit_budget(WindowsCommitSample {
            total_phys: 16 * GIB,
            commit_limit: 16 * GIB,
            available_commit: 0,
            process_commit: 300 * MIB,
        });
        assert!(full.commit_bound);
        assert!(full.available_commit < full.reserve_bytes);
        assert!(full.effective_bytes <= 300 * MIB);
        assert!(full.effective_bytes >= 1);
    }
}

//! Index schema management.
//!
//! This module wraps the [`Schema`] type (defined in [`crate::types`]) with
//! higher-level logic for:
//!
//! - Dynamic field type detection from JSON values
//! - Controlled schema evolution (add fields without re-indexing)
//! - Mapping compatibility checks between schema versions
//! - Field validation before indexing

use serde::{Deserialize, Serialize};

use crate::error::XerjError;
use crate::types::{FieldConfig, FieldType, Schema};

/// Render epoch milliseconds as an ISO-8601 UTC string with millisecond
/// precision (`2026-10-06T11:09:13.000Z`). One definition for every caller
/// that has to render a date the way `min`/`max` aggregations render their
/// `value_as_string`: the engine's agg layer (xerj-engine/src/aggs.rs, its
/// former private copy) and the autoindex catalog read-back, which replaced
/// those aggs with sorted size-1 reads (#1183) and must not diverge from the
/// rendering the catalog already published.
pub fn epoch_ms_to_iso8601_utc(ms: i64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp_millis(ms)
        .map(|dt| dt.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
        .unwrap_or_default()
}

// ═════════════════════════════════════════════════════════════════════════════
// Dynamic mapping mode
// ═════════════════════════════════════════════════════════════════════════════

/// Controls how the engine handles fields that appear in a document but are
/// not defined in the current schema.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum DynamicMapping {
    /// Automatically add new fields to the schema (default).
    ///
    /// Type is inferred from the first JSON value seen for the field.
    /// Schema version is incremented for each newly discovered field.
    #[default]
    Dynamic,
    /// Reject documents containing unmapped fields.
    ///
    /// Prevents unintentional schema sprawl in production indices.
    Strict,
    /// Accept unmapped fields but do not index them.
    ///
    /// The field value is stored in `_source` only; it cannot be searched or
    /// sorted on. Useful for audit-log fields you want to keep but not query.
    Runtime,
}

// ═════════════════════════════════════════════════════════════════════════════
// ManagedSchema
// ═════════════════════════════════════════════════════════════════════════════

/// A schema with its dynamic mapping policy — the unit that an index stores.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ManagedSchema {
    /// The underlying field definitions and version counter.
    pub schema: Schema,
    /// Dynamic mapping behaviour.
    pub dynamic: DynamicMapping,
}

impl ManagedSchema {
    /// Create a new empty managed schema.
    pub fn new(dynamic: DynamicMapping) -> Self {
        Self {
            schema: Schema::empty(),
            dynamic,
        }
    }

    /// Create with `Dynamic` mapping (the default).
    pub fn dynamic() -> Self {
        Self::new(DynamicMapping::Dynamic)
    }

    /// Create with `Strict` mapping.
    pub fn strict() -> Self {
        Self::new(DynamicMapping::Strict)
    }

    // ── Field access ─────────────────────────────────────────────────────────

    /// Return the `FieldConfig` for a field name.
    pub fn field(&self, name: &str) -> Option<&FieldConfig> {
        self.schema.field(name)
    }

    /// Return all field configs.
    pub fn fields(&self) -> &[FieldConfig] {
        &self.schema.fields
    }

    // ── Schema evolution ──────────────────────────────────────────────────────

    /// Explicitly add a field to the schema.
    ///
    /// Fails if:
    /// - A field with the same name already exists.
    /// - The field config is invalid (checked by [`validate_field_config`]:
    ///   empty, padded or `_`-prefixed name, missing or zero vector
    ///   `dimensions`, non-positive boost, an indexed `binary` field).
    pub fn add_field(&mut self, field: FieldConfig) -> Result<(), XerjError> {
        validate_field_config(&field)?;
        self.schema.add_field(field)
    }

    /// Process a JSON object, adding any unknown fields (when `Dynamic`), or
    /// returning an error if `Strict` mode is active and an unmapped field is
    /// encountered.
    ///
    /// Returns the list of newly-added field names.
    pub fn apply_document(
        &mut self,
        value: &serde_json::Value,
        limit: u32,
    ) -> Result<Vec<String>, XerjError> {
        let obj = value
            .as_object()
            .ok_or_else(|| XerjError::invalid_mapping("document must be a JSON object"))?;

        let mut added = Vec::new();
        for (key, val) in obj {
            if self.schema.has_field(key) {
                continue; // already mapped, nothing to do
            }

            match self.dynamic {
                DynamicMapping::Strict => {
                    return Err(XerjError::invalid_mapping(format!(
                        "field '{key}' is not in the schema and dynamic mapping is 'strict'"
                    )));
                }
                DynamicMapping::Runtime => {
                    // Accept but don't index — nothing to do here
                }
                DynamicMapping::Dynamic => {
                    if self.schema.field_count() as u32 >= limit {
                        return Err(XerjError::resource_exhausted(format!(
                            "index has reached the field limit of {limit}; \
                             field '{key}' cannot be auto-mapped"
                        )));
                    }
                    let inferred_type = infer_field_type(val);
                    let field = FieldConfig::new(key.clone(), inferred_type);
                    validate_field_config(&field)?;
                    self.schema.add_field(field)?;
                    added.push(key.clone());
                }
            }
        }
        Ok(added)
    }

    // ── Validation ────────────────────────────────────────────────────────────

    /// Validate that this schema is internally consistent.
    pub fn validate(&self) -> Result<(), XerjError> {
        // Field names must be unique (enforced by add_field but good to check)
        let mut seen = std::collections::HashSet::new();
        for field in &self.schema.fields {
            if !seen.insert(field.name.as_str()) {
                return Err(XerjError::invalid_mapping(format!(
                    "duplicate field name: '{}'",
                    field.name
                )));
            }
            validate_field_config(field)?;
        }
        Ok(())
    }

    // ── Compatibility ─────────────────────────────────────────────────────────

    /// Check whether `other` is compatible with `self` for a schema upgrade.
    ///
    /// Compatible means: every field present in both `self` and `other` has
    /// the same type. Either side may have fields the other lacks (schemas
    /// grow additively). Changing a field's type is never compatible.
    pub fn is_compatible_with(&self, other: &ManagedSchema) -> Result<(), XerjError> {
        for field in &self.schema.fields {
            // A field missing from `other` is fine — schemas grow additively,
            // so `self` having a field the snapshot lacks is allowed. Only a
            // TYPE change on a field both sides know is incompatible.
            if let Some(other_field) = other.field(&field.name) {
                if other_field.field_type != field.field_type {
                    return Err(XerjError::invalid_mapping(format!(
                        "field '{}' type changed from '{}' to '{}'; \
                         type changes require reindexing",
                        field.name, field.field_type, other_field.field_type
                    )));
                }
            }
        }
        Ok(())
    }
}

// ═════════════════════════════════════════════════════════════════════════════
// Field type inference
// ═════════════════════════════════════════════════════════════════════════════

/// Infer a [`FieldType`] from a JSON value.
///
/// The heuristics here match what most users expect from a search engine:
/// strings become `Text`, numbers become `Long` or `Double`, arrays are
/// unwrapped to their element type, etc.
pub fn infer_field_type(value: &serde_json::Value) -> FieldType {
    match value {
        serde_json::Value::Null => FieldType::Keyword, // conservative default
        serde_json::Value::Bool(_) => FieldType::Boolean,
        serde_json::Value::Number(n) => {
            if n.is_f64() {
                FieldType::Double
            } else {
                FieldType::Long
            }
        }
        serde_json::Value::String(s) => infer_string_type(s),
        serde_json::Value::Array(arr) => {
            // Infer from the first non-null element
            arr.iter()
                .find(|v| !v.is_null())
                .map(infer_field_type)
                .unwrap_or(FieldType::Keyword)
        }
        serde_json::Value::Object(_) => FieldType::Object,
    }
}

/// Heuristic type detection for string values.
///
/// Returns `Date` for ISO-8601 timestamps, `Ip` for IP literals, and `Text`
/// for everything else. Strings without whitespace that look like identifiers
/// are mapped to `Keyword` when they are under 256 bytes.
fn infer_string_type(s: &str) -> FieldType {
    // IP address detection (quick check before regex)
    if is_ip_address(s) {
        return FieldType::Ip;
    }
    // ISO-8601 datetime detection (starts with 4 digits followed by '-')
    if is_iso8601_like(s) {
        return FieldType::Date;
    }
    // Short strings without whitespace → Keyword; long or whitespace-containing → Text
    if s.len() <= 256 && !s.contains(char::is_whitespace) {
        FieldType::Keyword
    } else {
        FieldType::Text
    }
}

fn is_ip_address(s: &str) -> bool {
    s.parse::<std::net::IpAddr>().is_ok()
}

fn is_iso8601_like(s: &str) -> bool {
    // Fast path: must be at least "YYYY-MM-DD" (10 chars)
    if s.len() < 10 {
        return false;
    }
    let b = s.as_bytes();
    b[0].is_ascii_digit()
        && b[1].is_ascii_digit()
        && b[2].is_ascii_digit()
        && b[3].is_ascii_digit()
        && b[4] == b'-'
        && b[5].is_ascii_digit()
        && b[6].is_ascii_digit()
        && b[7] == b'-'
        && b[8].is_ascii_digit()
        && b[9].is_ascii_digit()
}

// ═════════════════════════════════════════════════════════════════════════════
// Field validation
// ═════════════════════════════════════════════════════════════════════════════

/// Validate an individual [`FieldConfig`].
pub fn validate_field_config(field: &FieldConfig) -> Result<(), XerjError> {
    // Name must be non-empty and not contain leading/trailing whitespace
    if field.name.trim().is_empty() {
        return Err(XerjError::invalid_mapping("field name cannot be empty"));
    }
    if field.name.trim() != field.name {
        return Err(XerjError::invalid_mapping(format!(
            "field name '{}' must not have leading or trailing whitespace",
            field.name
        )));
    }
    // Field names must not start with '_' (reserved for meta-fields)
    if field.name.starts_with('_') {
        return Err(XerjError::invalid_mapping(format!(
            "field name '{}' must not start with '_' (reserved for meta-fields)",
            field.name
        )));
    }

    // Vector and Chunk fields require explicit dimensionality
    if matches!(field.field_type, FieldType::Vector | FieldType::Chunk) {
        match field.options.dimensions {
            None => {
                return Err(XerjError::invalid_mapping(format!(
                    "field '{}' of type '{}' requires 'dimensions' to be set",
                    field.name, field.field_type
                )));
            }
            Some(0) => {
                return Err(XerjError::invalid_mapping(format!(
                    "field '{}' dimensions must be > 0",
                    field.name
                )));
            }
            _ => {}
        }
    }

    // Boost must be positive
    if field.options.boost <= 0.0 {
        return Err(XerjError::invalid_mapping(format!(
            "field '{}' boost must be > 0.0",
            field.name
        )));
    }

    // Binary fields cannot be indexed (they're too large and opaque)
    if field.field_type == FieldType::Binary && field.options.indexed {
        return Err(XerjError::invalid_mapping(format!(
            "field '{}' of type 'binary' cannot be indexed",
            field.name
        )));
    }

    Ok(())
}

// ═════════════════════════════════════════════════════════════════════════════
// Tests
// ═════════════════════════════════════════════════════════════════════════════

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn infer_types_from_json() {
        assert_eq!(
            infer_field_type(&serde_json::json!(true)),
            FieldType::Boolean
        );
        assert_eq!(infer_field_type(&serde_json::json!(42)), FieldType::Long);
        assert_eq!(infer_field_type(&serde_json::json!(2.5)), FieldType::Double);
        assert_eq!(
            infer_field_type(&serde_json::json!("hello world")),
            FieldType::Text
        );
        assert_eq!(
            infer_field_type(&serde_json::json!("my-tag")),
            FieldType::Keyword
        );
        assert_eq!(
            infer_field_type(&serde_json::json!("192.168.1.1")),
            FieldType::Ip
        );
        assert_eq!(
            infer_field_type(&serde_json::json!("2024-01-15T10:30:00Z")),
            FieldType::Date
        );
        assert_eq!(
            infer_field_type(&serde_json::json!({"key": "value"})),
            FieldType::Object
        );
    }

    #[test]
    fn dynamic_mapping_adds_fields() {
        let mut ms = ManagedSchema::dynamic();
        let doc = serde_json::json!({
            "title": "Hello World",
            "count": 42,
            "active": true
        });
        let added = ms.apply_document(&doc, 500).unwrap();
        assert_eq!(added.len(), 3);
        assert!(ms.field("title").is_some());
        assert_eq!(ms.field("count").unwrap().field_type, FieldType::Long);
    }

    #[test]
    fn strict_mapping_rejects_unknown() {
        let mut ms = ManagedSchema::strict();
        ms.add_field(FieldConfig::new("known", FieldType::Text))
            .unwrap();

        let doc = serde_json::json!({"known": "ok", "unknown": "boom"});
        assert!(ms.apply_document(&doc, 500).is_err());
    }

    #[test]
    fn field_limit_enforced() {
        let mut ms = ManagedSchema::dynamic();
        let doc = serde_json::json!({"a": 1, "b": 2, "c": 3});
        // limit of 2 should trigger an error when trying to add the 3rd field
        let result = ms.apply_document(&doc, 2);
        assert!(result.is_err());
    }

    #[test]
    fn schema_compatibility_type_change_rejected() {
        let mut old = ManagedSchema::dynamic();
        old.add_field(FieldConfig::new("status", FieldType::Keyword))
            .unwrap();

        let mut new = ManagedSchema::dynamic();
        new.add_field(FieldConfig::new("status", FieldType::Long))
            .unwrap();

        assert!(old.is_compatible_with(&new).is_err());
    }

    #[test]
    fn binary_field_cannot_be_indexed() {
        let mut field = FieldConfig::new("data", FieldType::Binary);
        field.options.indexed = true;
        assert!(validate_field_config(&field).is_err());

        field.options.indexed = false;
        assert!(validate_field_config(&field).is_ok());
    }

    #[test]
    fn vector_field_requires_dimensions() {
        let field = FieldConfig::new("embedding", FieldType::Vector);
        assert!(validate_field_config(&field).is_err());

        let mut field = FieldConfig::new("embedding", FieldType::Vector);
        field.options.dimensions = Some(768);
        assert!(validate_field_config(&field).is_ok());
    }
}

//! Spawning helper threads without taking the node down (#1122).
//!
//! The shipped release profile is `panic = "abort"`, so a panic on any thread
//! is a whole-node outage. Two different failures look the same from the
//! outside:
//!
//! * `std::thread::spawn` is `Builder::spawn(..).expect(..)`. An `EAGAIN`
//!   from `pthread_create` (thread or memory limit) aborts the process.
//!   `Builder::spawn` itself returns that `Err`.
//! * On Unix, `Builder::spawn` then **panics inside the new thread** when it
//!   cannot mmap the alternate signal stack (`failed to allocate an
//!   alternative stack: os error 12`). The parent already observed `Ok`.
//!   With `panic = "abort"` that child panic is not catchable.
//!
//! [`StdSpawn`] does not use `std::thread::Builder` on Unix. It calls
//! `pthread_create` directly and runs the job on that thread, so a stack
//! that cannot be reserved comes back as [`SpawnFailure`] and the child
//! never executes std's signal-stack setup. Windows has no alternate-stack
//! mmap; `CreateThread` failure is already an `Err` from `Builder::spawn`.
//! The global allocator aborting on its own (`memory allocation of N bytes
//! failed`) is a different failure and is not what this module handles.
//!
//! Because `Builder::spawn` / a failed `pthread_create` drops the closure,
//! the closure is handed *back* in [`SpawnFailure::job`] so the caller can
//! run it inline, retry, or drop it. Dropping it is the right degrade for
//! an infinite worker loop; running it is the right degrade for a finite
//! job such as freeing a memtable generation.
//!
//! [`try_spawn`] also consults a process-wide spawn gate (the engine
//! installs its governor's RSS-watermark check through
//! [`install_spawn_gate`]). That gate is a backstop: once the breaker is
//! already engaged, a best-effort spawn is not attempted at all. It is not
//! a substitute for the non-panicking spawn. Threads that must be tried
//! even above the watermark (the governor itself, WAL fsync) use
//! [`try_spawn_unguarded`] and still get an `Err` instead of an abort.
//!
//! The actual spawn goes through the [`Spawn`] trait so the failure paths
//! are unit-testable without exhausting a real machine.
//!
//! Scoped work cannot use [`try_spawn`]. The closure borrows the caller's
//! stack: autoindex workers, sync replay, an object-watch fetch, a mailbox
//! splitter. [`std::thread::Builder::spawn_scoped`] still returns `Ok` and
//! then panics in the child when the alternate signal stack cannot be
//! mapped. [`scope`] starts those threads with the same `pthread_create`
//! path and joins them before returning, so the borrow stays valid. A
//! failed spawn is an [`io::Error`]. The closure is dropped unrun; the
//! caller runs the work inline or records the error. This is not on the
//! per-document path: one `pthread_create` per thread, then the job the
//! caller already had.

use std::io;
use std::marker::PhantomData;
use std::panic::AssertUnwindSafe;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::Duration;

/// A process-wide "is it safe to spawn a thread right now?" predicate.
pub type SpawnGate = fn() -> bool;

static GATE: OnceLock<SpawnGate> = OnceLock::new();

/// Install the process-wide spawn gate. The first installation wins (the
/// engine's governor is process-global too); returns whether this call
/// installed it.
pub fn install_spawn_gate(gate: SpawnGate) -> bool {
    GATE.set(gate).is_ok()
}

/// Whether the installed gate currently allows spawning. With no gate
/// installed (unit tests, library embedding, the CLI) spawning is
/// unrestricted.
pub fn spawn_allowed() -> bool {
    GATE.get().map(|gate| gate()).unwrap_or(true)
}

/// The boxed body handed to a [`Spawn`] implementation.
pub type BoxedJob = Box<dyn FnOnce() + Send + 'static>;

/// How a named thread is actually started. [`StdSpawn`] in production; tests
/// inject a spawner that fails.
pub trait Spawn {
    /// Start `job` on a new thread called `name`.
    ///
    /// Failure to create the thread, including a failure while reserving its
    /// stack, is an `Err`. This must not panic: with `panic = "abort"` a
    /// panic here, or in the new thread before `job` runs, kills the process.
    fn spawn(&self, name: &str, job: BoxedJob) -> io::Result<SpawnedThread>;
}

/// `pthread_create` on Unix, `std::thread::Builder` elsewhere.
///
/// Unix does not go through `std::thread`. That path panics in the child
/// when the alternate signal stack cannot be mapped, after the parent has
/// already been told the thread exists (#1122).
#[derive(Debug, Clone, Copy, Default)]
pub struct StdSpawn;

impl Spawn for StdSpawn {
    fn spawn(&self, name: &str, job: BoxedJob) -> io::Result<SpawnedThread> {
        #[cfg(unix)]
        {
            // The OS name is applied on the new thread by the wrapper
            // `try_spawn_with` builds, before `job` runs. `std::thread`
            // would do that itself and then panic if the signal stack
            // cannot be mapped.
            let _ = name;
            spawn_pthread(job)
        }
        #[cfg(not(unix))]
        {
            spawn_std(name, job, None)
        }
    }
}

/// [`StdSpawn`] with an explicit stack reservation.
///
/// The in-process shard call needs 8 MiB: a search future overflows the
/// 2 MiB helper stack. On Unix this still uses `pthread_create`, so a
/// stack the OS will not reserve is an `Err` instead of a panic inside
/// the child after `Builder::spawn` has already returned `Ok` (#1122).
#[derive(Debug, Clone, Copy)]
pub struct StackSpawn {
    pub stack_bytes: usize,
}

impl Spawn for StackSpawn {
    fn spawn(&self, name: &str, job: BoxedJob) -> io::Result<SpawnedThread> {
        #[cfg(unix)]
        {
            let _ = name;
            spawn_pthread_with_stack(job, self.stack_bytes)
        }
        #[cfg(not(unix))]
        {
            spawn_std(name, job, Some(self.stack_bytes))
        }
    }
}

/// A thread started by [`Spawn::spawn`]. Dropping it detaches; [`join`](Self::join)
/// waits. There is no `std::thread::JoinHandle` on Unix because that type
/// only exists for threads std started, and those are the ones that panic
/// while mapping a signal stack.
pub struct SpawnedThread {
    inner: SpawnedInner,
}

impl std::fmt::Debug for SpawnedThread {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("SpawnedThread { .. }")
    }
}

enum SpawnedInner {
    #[cfg(unix)]
    Raw {
        thread: libc::pthread_t,
        joined: bool,
    },
    #[cfg(not(unix))]
    Std(Option<std::thread::JoinHandle<()>>),
    /// Spawn was refused or failed and the caller still needs a handle that
    /// `join`s immediately (a background loop that never started).
    Inert,
}

impl SpawnedThread {
    /// A handle for a thread that was never started. [`join`](Self::join)
    /// returns immediately.
    pub fn inert() -> Self {
        Self {
            inner: SpawnedInner::Inert,
        }
    }

    /// Wait for the thread to finish.
    ///
    /// A panic inside the job aborts the process on the release profile
    /// (`panic = "abort"`). On unwind builds the panic is caught at the
    /// `extern "C"` boundary so it cannot unwind into C; `join` then
    /// returns `Ok` and the panic hook has already printed it. Callers
    /// that detach (the normal best-effort path) do not observe it.
    pub fn join(mut self) -> std::thread::Result<()> {
        self.join_inner()
    }

    fn join_inner(&mut self) -> std::thread::Result<()> {
        match &mut self.inner {
            #[cfg(unix)]
            SpawnedInner::Raw { thread, joined } => {
                if !*joined {
                    *joined = true;
                    // SAFETY: `thread` came from a successful pthread_create
                    // in this process, and this is the only join or detach.
                    let rc = unsafe { libc::pthread_join(*thread, std::ptr::null_mut()) };
                    if rc != 0 {
                        return Err(Box::new(io::Error::from_raw_os_error(rc)));
                    }
                }
                Ok(())
            }
            #[cfg(not(unix))]
            SpawnedInner::Std(handle) => match handle.take() {
                Some(handle) => handle.join(),
                None => Ok(()),
            },
            SpawnedInner::Inert => Ok(()),
        }
    }
}

impl Drop for SpawnedThread {
    fn drop(&mut self) {
        #[cfg(unix)]
        if let SpawnedInner::Raw { thread, joined } = &mut self.inner {
            if !*joined {
                *joined = true;
                // SAFETY: `thread` came from a successful pthread_create in
                // this process, and join has not been called. Detach is what
                // dropping a `JoinHandle` does for a std thread.
                unsafe {
                    libc::pthread_detach(*thread);
                }
            }
        }
    }
}

// `libc::pthread_t` is `*mut c_void` on musl and an integer on glibc
// (`c_ulong`) and Apple (`uintptr_t`, libc 0.2.191). The integer forms
// make `SpawnedThread` auto-`Send` + `Sync`, and a second impl would
// conflict, so these impls exist only for musl.
//
// SAFETY: the stored value is an opaque POSIX thread id. This process
// never dereferences it. `pthread_join` and `pthread_detach` are the
// only uses, and POSIX allows either from any thread. `SpawnedThread`
// is the single owner of that obligation: `join` takes `self`, `Drop`
// detaches, and `joined` is written only through `&mut self`. A shared
// `&SpawnedThread` cannot perform either call (`Debug` prints a
// constant string), so `Sync` is sound and matches the automatic impl
// glibc already provides and `std::thread::JoinHandle`.
#[cfg(target_env = "musl")]
unsafe impl Send for SpawnedThread {}
// SAFETY: same as `Send` above. Shared references do not join or detach.
#[cfg(target_env = "musl")]
unsafe impl Sync for SpawnedThread {}

const _: () = {
    const fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<SpawnedThread>()
};

/// A spawn that did not happen. `job` is the closure that would have run on
/// the thread, returned to the caller so it can degrade (run it inline),
/// retry, or drop it on purpose. It is `None` only if the spawner reported a
/// failure *after* running the job, which [`StdSpawn`] never does.
pub struct SpawnFailure<F> {
    /// Why the thread was not started.
    pub error: io::Error,
    /// The un-run job, handed back.
    pub job: Option<F>,
}

impl<F> std::fmt::Debug for SpawnFailure<F> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SpawnFailure")
            .field("error", &self.error)
            .field("job_returned", &self.job.is_some())
            .finish()
    }
}

impl<F> std::fmt::Display for SpawnFailure<F> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.error.fmt(f)
    }
}

/// Log one degradation for `once`. Hot paths (every memtable publish, every
/// pool call) must not emit a line per failed attempt. Returns whether this
/// call logged.
pub fn warn_best_effort_degraded(once: &AtomicBool, name: &str, error: &io::Error) -> bool {
    if once.swap(true, Ordering::Relaxed) {
        return false;
    }
    tracing::warn!(
        thread = name,
        error = %error,
        "best-effort helper thread was not started; degrading instead of aborting the process (#1122)"
    );
    true
}

/// The error a gate refusal carries.
fn gate_refused(name: &str) -> io::Error {
    io::Error::new(
        io::ErrorKind::OutOfMemory,
        format!(
            "not spawning thread {name}: memory is at the governor watermark, \
             so this best-effort spawn is skipped (#1122)"
        ),
    )
}

/// Spawn a named thread, honouring the process-wide spawn gate. Never
/// panics on spawn failure; see [`SpawnFailure`].
pub fn try_spawn<F>(name: &str, f: F) -> Result<SpawnedThread, SpawnFailure<F>>
where
    F: FnOnce() + Send + 'static,
{
    try_spawn_with(&StdSpawn, spawn_allowed(), name, f)
}

/// [`try_spawn`] without the watermark gate.
///
/// For threads that should still be attempted when RSS is already high
/// (the governor, a WAL fsync worker). A real OS failure is still an
/// `Err` with the job handed back — it does not abort.
pub fn try_spawn_unguarded<F>(name: &str, f: F) -> Result<SpawnedThread, SpawnFailure<F>>
where
    F: FnOnce() + Send + 'static,
{
    try_spawn_with(&StdSpawn, true, name, f)
}

/// Spawn a helper whose only job is to *free* memory (e.g. the memtable's
/// `xerj-drain-free`, which drops drained generations off the publish path).
///
/// Ignores the watermark gate on purpose: the gate closes exactly when RSS
/// is at the governor watermark, which is exactly when a memory-relief
/// helper should run. Gating it meant the drain's frees ran inline on the
/// publish thread under pressure (logged as "best-effort helper thread was
/// not started"). A real OS failure is still an `Err` with the job handed
/// back, and the caller drops it inline.
pub fn try_spawn_memory_relief<F>(name: &str, f: F) -> Result<SpawnedThread, SpawnFailure<F>>
where
    F: FnOnce() + Send + 'static,
{
    try_spawn_with(&StdSpawn, true, name, f)
}

/// [`try_spawn`] with an explicit stack size.
///
/// Used by the in-process shard call, whose handler does not fit on the
/// 2 MiB helper stack. A refused or failed spawn returns the job; the
/// caller must not run that job on its own stack (that is the overflow
/// the extra stack exists to avoid). Drop it and answer the client.
pub fn try_spawn_stack<F>(
    name: &str,
    stack_bytes: usize,
    f: F,
) -> Result<SpawnedThread, SpawnFailure<F>>
where
    F: FnOnce() + Send + 'static,
{
    try_spawn_with(&StackSpawn { stack_bytes }, spawn_allowed(), name, f)
}

/// A thread whose job returns a value.
///
/// [`Spawn`] jobs return `()`. Callers that need the result (a pipe
/// reader) send it through a channel. [`join`](Self::join) waits for the
/// thread and then for that value.
pub struct JoinedThread<T> {
    handle: SpawnedThread,
    rx: std::sync::mpsc::Receiver<T>,
}

impl<T> std::fmt::Debug for JoinedThread<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("JoinedThread").finish_non_exhaustive()
    }
}

impl<T> JoinedThread<T> {
    /// Wait for the job to finish and return its value.
    ///
    /// `Err` means the thread ended without sending a value (it panicked
    /// on an unwind build, where the panic is caught at the `extern "C"`
    /// boundary). On the release profile a panic aborts the process before
    /// this returns.
    pub fn join(self) -> std::thread::Result<T> {
        self.handle.join()?;
        self.rx.recv().map_err(|_| {
            Box::new(io::Error::other("helper thread ended without a result"))
                as Box<dyn std::any::Any + Send>
        })
    }
}

/// [`try_spawn`] for a job that returns `T`.
///
/// Failure hands `f` back unrun, the same contract as [`try_spawn`]. The
/// success path is one extra channel send of `T` after the job returns.
pub fn try_spawn_returning<T, F>(name: &str, f: F) -> Result<JoinedThread<T>, SpawnFailure<F>>
where
    T: Send + 'static,
    F: FnOnce() -> T + Send + 'static,
{
    try_spawn_returning_with(&StdSpawn, spawn_allowed(), name, f)
}

/// [`try_spawn_returning`] with an explicit spawner and gate verdict.
pub fn try_spawn_returning_with<S, T, F>(
    spawner: &S,
    allowed: bool,
    name: &str,
    f: F,
) -> Result<JoinedThread<T>, SpawnFailure<F>>
where
    S: Spawn + ?Sized,
    T: Send + 'static,
    F: FnOnce() -> T + Send + 'static,
{
    let (tx, rx) = std::sync::mpsc::channel();
    let slot = Arc::new(Mutex::new(Some(f)));
    let thread_slot = Arc::clone(&slot);
    match try_spawn_with(spawner, allowed, name, move || {
        let job = thread_slot
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take();
        if let Some(job) = job {
            let _ = tx.send(job());
        }
    }) {
        Ok(handle) => Ok(JoinedThread { handle, rx }),
        Err(failure) => {
            // The wrapper did not run, so `f` is still in the slot.
            drop(failure.job);
            let job = slot
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .take();
            Err(SpawnFailure {
                error: failure.error,
                job,
            })
        }
    }
}

/// Start `job` on a detached thread, for a pool worker that outlives the
/// caller (#1122).
///
/// `Ok` means the thread is running and will be detached when the returned
/// handle is dropped inside this function. `Err` means `job` did not run.
/// This does not consult the watermark gate: a pool is built once, and a
/// soft RSS watermark must not refuse its workers the way it refuses a
/// drain-free thread. `stack_bytes` is the reservation the pool asked for;
/// `None` uses the 2 MiB helper stack.
pub fn spawn_detached(
    name: &str,
    stack_bytes: Option<usize>,
    job: impl FnOnce() + Send + 'static,
) -> io::Result<()> {
    if let Some(stack_bytes) = stack_bytes {
        spawn_detached_with(&StackSpawn { stack_bytes }, name, job)
    } else {
        spawn_detached_with(&StdSpawn, name, job)
    }
}

/// [`spawn_detached`] with an explicit spawner. Tests pass one that fails
/// the way an alternate-stack `ENOMEM` does.
pub fn spawn_detached_with<S, F>(spawner: &S, name: &str, job: F) -> io::Result<()>
where
    S: Spawn + ?Sized,
    F: FnOnce() + Send + 'static,
{
    match try_spawn_with(spawner, true, name, job) {
        Ok(_detached) => Ok(()),
        Err(failure) => {
            drop(failure.job);
            Err(failure.error)
        }
    }
}

/// [`try_spawn`] with an explicit spawner and gate verdict (for tests and
/// callers that already sampled the gate).
pub fn try_spawn_with<S, F>(
    spawner: &S,
    allowed: bool,
    name: &str,
    f: F,
) -> Result<SpawnedThread, SpawnFailure<F>>
where
    S: Spawn + ?Sized,
    F: FnOnce() + Send + 'static,
{
    if !allowed {
        return Err(SpawnFailure {
            error: gate_refused(name),
            job: Some(f),
        });
    }
    // The thread takes the job out of the slot when it runs. If the spawn
    // fails, the thread never ran, and the job is still in the slot even
    // though the spawner dropped the boxed wrapper.
    let slot = Arc::new(Mutex::new(Some(f)));
    let thread_slot = Arc::clone(&slot);
    #[cfg(unix)]
    let comm = os_comm_name(name);
    let wrapper: BoxedJob = Box::new(move || {
        // Before the caller's job, so a panic in the job still shows the
        // OS thread name. std would have set this and then mmap'd a signal
        // stack; that mmap is the panic #1122 hit.
        #[cfg(unix)]
        set_os_name(&comm);
        let job = thread_slot
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take();
        if let Some(job) = job {
            job();
        }
    });
    match spawner.spawn(name, wrapper) {
        Ok(handle) => Ok(handle),
        Err(error) => {
            let job = slot
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .take();
            Err(SpawnFailure { error, job })
        }
    }
}

/// [`try_spawn`] retried up to `attempts` times (at least once), sleeping
/// `backoff`, then twice that, … between attempts. For threads that must
/// exist (samplers, workers) where a transient `EAGAIN` or a brief trip of
/// the memory watermark should not cost the thread for the life of the
/// process. The gate is re-sampled on every attempt.
pub fn spawn_with_retry<F>(
    name: &str,
    attempts: u32,
    backoff: Duration,
    f: F,
) -> Result<SpawnedThread, SpawnFailure<F>>
where
    F: FnOnce() + Send + 'static,
{
    spawn_with_retry_using(&StdSpawn, spawn_allowed, name, attempts, backoff, f)
}

/// [`spawn_with_retry`] with an explicit spawner and gate.
pub fn spawn_with_retry_using<S, G, F>(
    spawner: &S,
    gate: G,
    name: &str,
    attempts: u32,
    backoff: Duration,
    f: F,
) -> Result<SpawnedThread, SpawnFailure<F>>
where
    S: Spawn + ?Sized,
    G: Fn() -> bool,
    F: FnOnce() + Send + 'static,
{
    let attempts = attempts.max(1);
    let mut job = f;
    let mut delay = backoff;
    let mut attempt = 1;
    loop {
        match try_spawn_with(spawner, gate(), name, job) {
            Ok(handle) => return Ok(handle),
            Err(failure) => {
                let Some(returned) = failure.job else {
                    return Err(failure);
                };
                if attempt >= attempts {
                    return Err(SpawnFailure {
                        error: failure.error,
                        job: Some(returned),
                    });
                }
                job = returned;
                std::thread::sleep(delay);
                delay = delay.saturating_mul(2);
                attempt += 1;
            }
        }
    }
}

/// A thread [`scope`] has started and not yet joined.
struct ScopedThread {
    handle: SpawnedThread,
    /// Set when a [`Scope::spawn`] job panics on an unwind build. A
    /// [`Scope::spawn_returning`] job sends its panic to the join handle
    /// instead, so a caller that turned the panic into an error is not
    /// panicked again when the scope ends.
    panic: Arc<Mutex<Option<Box<dyn std::any::Any + Send>>>>,
}

impl Drop for ScopedThread {
    fn drop(&mut self) {
        // Join, do not detach. Detach would let the job use the caller's
        // borrows after `scope` returned.
        let _ = self.handle.join_inner();
    }
}

/// Join handle for [`Scope::spawn_returning`].
///
/// The value is available once the job returns. The scope also joins the
/// operating-system thread if this handle is dropped, so a borrow inside
/// the job cannot outlive the scope. Dropping the handle discards the
/// value, including a panic payload.
pub struct ScopedJoinHandle<'scope, T> {
    rx: std::sync::mpsc::Receiver<std::thread::Result<T>>,
    _scope: PhantomData<&'scope ()>,
}

impl<T> std::fmt::Debug for ScopedJoinHandle<'_, T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ScopedJoinHandle").finish_non_exhaustive()
    }
}

impl<T> ScopedJoinHandle<'_, T> {
    /// Wait for the job and return its value.
    ///
    /// `Err` is a panic from the job on an unwind build. On the release
    /// profile (`panic = "abort"`) a panic aborts the process before this
    /// returns. A thread that exits without sending is also `Err`.
    pub fn join(self) -> std::thread::Result<T> {
        self.rx.recv().unwrap_or_else(|_| {
            Err(Box::new(io::Error::other(
                "scoped thread ended without a result",
            )))
        })
    }
}

/// The threads started inside one [`scope`] call.
///
/// Constructed only by [`scope`], which joins every thread before it
/// returns, including when the body panics. Jobs borrow the caller's
/// stack, so that join is what keeps the borrows valid.
pub struct Scope<'scope, 'env: 'scope> {
    threads: Mutex<Vec<ScopedThread>>,
    _scope: PhantomData<&'scope mut &'scope ()>,
    _env: PhantomData<&'env mut &'env ()>,
}

impl<'scope, 'env: 'scope> Scope<'scope, 'env> {
    /// Start `f` on a helper thread named `name`.
    ///
    /// `Err` means `f` did not run. The caller may do the work on this
    /// thread or skip it. The error is logged once per call.
    pub fn spawn<F>(&self, name: &str, f: F) -> io::Result<()>
    where
        F: FnOnce() + Send + 'scope,
    {
        self.spawn_with(&StdSpawn, spawn_allowed(), name, f)
    }

    /// [`Scope::spawn`] with an explicit spawner and gate verdict.
    ///
    /// Tests pass a spawner that fails. Production code uses [`Scope::spawn`].
    pub fn spawn_with<S, F>(&self, spawner: &S, allowed: bool, name: &str, f: F) -> io::Result<()>
    where
        S: Spawn + ?Sized,
        F: FnOnce() + Send + 'scope,
    {
        if !allowed {
            drop(f);
            let error = gate_refused(name);
            log_scoped_spawn_failure(name, &error);
            return Err(error);
        }
        let panic = Arc::new(Mutex::new(None));
        let slot = Arc::clone(&panic);
        // SAFETY: `scope` joins this thread before it returns, or this
        // function drops the closure before returning `Err`. Either way
        // the `'scope` borrow is still alive.
        let job: Box<dyn FnOnce() + Send + 'static> = unsafe { erase_fnonce_lifetime(Box::new(f)) };
        self.start(
            spawner,
            name,
            Box::new(move || {
                if let Err(payload) = std::panic::catch_unwind(AssertUnwindSafe(job)) {
                    *slot.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(payload);
                }
            }),
            panic,
        )
    }

    /// Start `f` and return a handle for its value.
    ///
    /// Same failure contract as [`Scope::spawn`]: on `Err`, `f` did not run.
    /// A panic on an unwind build is [`ScopedJoinHandle::join`]'s `Err`,
    /// not a panic of the scope, so the caller can record it and keep going.
    pub fn spawn_returning<T, F>(&self, name: &str, f: F) -> io::Result<ScopedJoinHandle<'scope, T>>
    where
        T: Send + 'static,
        F: FnOnce() -> T + Send + 'scope,
    {
        self.spawn_returning_with(&StdSpawn, spawn_allowed(), name, f)
    }

    /// [`Scope::spawn_returning`] with an explicit spawner and gate verdict.
    pub fn spawn_returning_with<S, T, F>(
        &self,
        spawner: &S,
        allowed: bool,
        name: &str,
        f: F,
    ) -> io::Result<ScopedJoinHandle<'scope, T>>
    where
        S: Spawn + ?Sized,
        T: Send + 'static,
        F: FnOnce() -> T + Send + 'scope,
    {
        if !allowed {
            drop(f);
            let error = gate_refused(name);
            log_scoped_spawn_failure(name, &error);
            return Err(error);
        }
        let (tx, rx) = std::sync::mpsc::channel();
        // SAFETY: same as [`Scope::spawn_with`]. `T` is `'static`, so the
        // value can sit in the channel until `join` without borrowing
        // `'scope`. The closure itself is not `'static` and is only erased
        // for the thread.
        let job: Box<dyn FnOnce() -> T + Send + 'static> =
            unsafe { erase_fnonce_returning_lifetime(Box::new(f)) };
        self.start(
            spawner,
            name,
            Box::new(move || {
                let result = std::panic::catch_unwind(AssertUnwindSafe(job));
                let _ = tx.send(result);
            }),
            Arc::new(Mutex::new(None)),
        )?;
        Ok(ScopedJoinHandle {
            rx,
            _scope: PhantomData,
        })
    }

    fn start<S>(
        &self,
        spawner: &S,
        name: &str,
        job: Box<dyn FnOnce() + Send + 'static>,
        panic: Arc<Mutex<Option<Box<dyn std::any::Any + Send>>>>,
    ) -> io::Result<()>
    where
        S: Spawn + ?Sized,
    {
        match try_spawn_with(spawner, true, name, job) {
            Ok(handle) => {
                self.threads
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .push(ScopedThread { handle, panic });
                Ok(())
            }
            Err(failure) => {
                // The thread did not run. Dropping the job drops the
                // caller's closure while `'scope` is still alive.
                drop(failure.job);
                log_scoped_spawn_failure(name, &failure.error);
                Err(failure.error)
            }
        }
    }

    /// Join every thread started so far. A second call joins nothing.
    fn finish(&self) -> Option<Box<dyn std::any::Any + Send>> {
        let threads = {
            let mut guard = self
                .threads
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            std::mem::take(&mut *guard)
        };
        let mut panic = None;
        for mut thread in threads {
            // `ScopedThread`'s drop joins too. Joining here first means the
            // panic slot is filled before we read it.
            let _ = thread.handle.join_inner();
            if panic.is_none() {
                panic = thread
                    .panic
                    .lock()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .take();
            }
        }
        panic
    }
}

/// Run `f`, then join every thread it started.
///
/// A panic in `f` is resumed after the join. A panic in a
/// [`Scope::spawn`] job is resumed after `f` returns, unless `f` itself
/// panicked. A [`Scope::spawn_returning`] panic is only visible from
/// [`ScopedJoinHandle::join`].
pub fn scope<'env, F, R>(f: F) -> R
where
    F: for<'scope> FnOnce(&'scope Scope<'scope, 'env>) -> R,
{
    let scope = Scope {
        threads: Mutex::new(Vec::new()),
        _scope: PhantomData,
        _env: PhantomData,
    };
    let result = std::panic::catch_unwind(AssertUnwindSafe(|| f(&scope)));
    let child_panic = scope.finish();
    match result {
        Err(parent) => std::panic::resume_unwind(parent),
        Ok(value) => {
            if let Some(child) = child_panic {
                std::panic::resume_unwind(child);
            }
            value
        }
    }
}

fn log_scoped_spawn_failure(name: &str, error: &io::Error) {
    tracing::warn!(
        thread = name,
        error = %error,
        "scoped helper thread was not started; the caller degrades and the process stays up (#1122)"
    );
}

/// # Safety
///
/// The caller joins the thread that runs `job`, or drops `job`, before
/// the `'scope` borrows end.
unsafe fn erase_fnonce_lifetime<'scope>(
    job: Box<dyn FnOnce() + Send + 'scope>,
) -> Box<dyn FnOnce() + Send + 'static> {
    // SAFETY: caller contract. The fat pointer does not depend on the
    // lifetime. This is the same erasure `std::thread::scope` uses so a
    // stack borrow can cross `pthread_create`; the join is what makes it
    // sound, and that join is [`scope`]'s.
    unsafe {
        std::mem::transmute::<Box<dyn FnOnce() + Send + 'scope>, Box<dyn FnOnce() + Send + 'static>>(
            job,
        )
    }
}

/// # Safety
///
/// Same as [`erase_fnonce_lifetime`]. `T` is `'static`, so the return
/// value does not borrow `'scope`.
unsafe fn erase_fnonce_returning_lifetime<'scope, T: Send + 'static>(
    job: Box<dyn FnOnce() -> T + Send + 'scope>,
) -> Box<dyn FnOnce() -> T + Send + 'static> {
    // SAFETY: caller contract, same as [`erase_fnonce_lifetime`].
    unsafe {
        std::mem::transmute::<
            Box<dyn FnOnce() -> T + Send + 'scope>,
            Box<dyn FnOnce() -> T + Send + 'static>,
        >(job)
    }
}

/// Linux `TASK_COMM_LEN`, including the trailing NUL. `std::thread` truncates
/// to the same width for the OS name; the full name still goes in our logs.
#[cfg(unix)]
fn os_comm_name(name: &str) -> [u8; 16] {
    let mut buf = [0u8; 16];
    let bytes = if name.is_empty() {
        b"xerj".as_slice()
    } else {
        name.as_bytes()
    };
    let n = bytes.len().min(15);
    buf[..n].copy_from_slice(&bytes[..n]);
    buf
}

#[cfg(unix)]
fn set_os_name(bytes: &[u8; 16]) {
    #[cfg(any(target_os = "linux", target_os = "android", target_os = "macos"))]
    {
        // SAFETY: `bytes` is NUL-terminated (index 15 is never written) and
        // the C string is only read for the duration of the setname call.
        let name = unsafe { std::ffi::CStr::from_ptr(bytes.as_ptr().cast()) };
        #[cfg(any(target_os = "linux", target_os = "android"))]
        unsafe {
            // SAFETY: `name` is a NUL-terminated C string. Setting the
            // calling thread's name cannot fail the spawn.
            let _ = libc::pthread_setname_np(libc::pthread_self(), name.as_ptr());
        }
        #[cfg(target_os = "macos")]
        unsafe {
            // SAFETY: same as Linux, but Darwin's setter only names the
            // calling thread and takes no `pthread_t`.
            let _ = libc::pthread_setname_np(name.as_ptr());
        }
    }
    #[cfg(not(any(target_os = "linux", target_os = "android", target_os = "macos")))]
    {
        let _ = bytes;
    }
}

/// The name of the calling thread, as the spawner set it.
///
/// On Linux and macOS this is the pthread comm. Unix spawn does not go
/// through `Builder::name`, so `std::thread::current().name()` is empty
/// there (#1122). The comm is at most 15 bytes (`xerj-scan-0` fits).
/// Elsewhere this is the std thread name, which `Builder::name` did set.
pub fn current_thread_name() -> Option<String> {
    #[cfg(any(target_os = "linux", target_os = "macos"))]
    {
        let mut buf = [0u8; 16];
        // SAFETY: `buf` is writable for `buf.len()` bytes. On success
        // `pthread_getname_np` writes a NUL-terminated name into it and
        // does not retain the pointer.
        let rc = unsafe {
            libc::pthread_getname_np(libc::pthread_self(), buf.as_mut_ptr().cast(), buf.len())
        };
        if rc != 0 {
            return None;
        }
        let end = buf.iter().position(|byte| *byte == 0).unwrap_or(buf.len());
        String::from_utf8(buf[..end].to_vec()).ok()
    }
    #[cfg(not(any(target_os = "linux", target_os = "macos")))]
    {
        std::thread::current().name().map(str::to_owned)
    }
}

/// Same default std uses for a spawned thread (`2 MiB` on Tier-1). A larger
/// stack would reserve more address space than the path this replaces,
/// which is the opposite of what a memory-pressure spawn should do.
#[cfg(unix)]
const HELPER_STACK_BYTES: usize = 2 * 1024 * 1024;

#[cfg(unix)]
struct AttrGuard(libc::pthread_attr_t);

#[cfg(unix)]
impl Drop for AttrGuard {
    fn drop(&mut self) {
        // SAFETY: the guard is built only after `pthread_attr_init` returned
        // 0, and nothing else destroys this attribute.
        unsafe {
            libc::pthread_attr_destroy(&mut self.0);
        }
    }
}

#[cfg(unix)]
fn spawn_pthread(job: BoxedJob) -> io::Result<SpawnedThread> {
    spawn_pthread_with_stack(job, HELPER_STACK_BYTES)
}

#[cfg(unix)]
fn spawn_pthread_with_stack(job: BoxedJob, stack_bytes: usize) -> io::Result<SpawnedThread> {
    // A second box so the fat pointer of `dyn FnOnce` survives the trip
    // through `pthread_create`'s thin `void*`. This is the same shape std
    // uses. The allocation is the caller's job box plus this one; if it
    // fails, the global allocator aborts — that is every Rust allocation,
    // not the signal-stack panic this function exists to avoid.
    let job = Box::new(job);
    let job_ptr = Box::into_raw(job);

    let mut attr = std::mem::MaybeUninit::<libc::pthread_attr_t>::uninit();
    // SAFETY: `attr` is a valid out-pointer for pthread_attr_init.
    let rc = unsafe { libc::pthread_attr_init(attr.as_mut_ptr()) };
    if rc != 0 {
        // SAFETY: the new thread was not created, so it did not take the box.
        drop(unsafe { Box::from_raw(job_ptr) });
        return Err(io::Error::from_raw_os_error(rc));
    }
    // SAFETY: pthread_attr_init returned 0, so the attribute is initialized.
    let mut attr = AttrGuard(unsafe { attr.assume_init() });
    // SAFETY: `attr` is initialized. Failure leaves the platform default
    // stack; pthread_create still returns an error if that cannot be reserved.
    unsafe {
        let _ = libc::pthread_attr_setstacksize(&mut attr.0, stack_bytes);
    }

    let mut thread = std::mem::MaybeUninit::<libc::pthread_t>::uninit();
    // SAFETY: `attr` is initialized; `thread_main` has the C ABI and frees
    // `job_ptr` exactly once. On failure the thread did not start and the
    // pointer is freed below.
    let rc = unsafe {
        libc::pthread_create(
            thread.as_mut_ptr(),
            &attr.0,
            thread_main,
            job_ptr.cast::<libc::c_void>(),
        )
    };
    drop(attr);
    if rc != 0 {
        // SAFETY: pthread_create failed, so `thread_main` will not run.
        drop(unsafe { Box::from_raw(job_ptr) });
        return Err(io::Error::from_raw_os_error(rc));
    }
    // SAFETY: pthread_create returned 0, so `thread` was written.
    let thread = unsafe { thread.assume_init() };
    Ok(SpawnedThread {
        inner: SpawnedInner::Raw {
            thread,
            joined: false,
        },
    })
}

#[cfg(unix)]
extern "C" fn thread_main(ptr: *mut libc::c_void) -> *mut libc::c_void {
    // SAFETY: the parent leaked this box into pthread_create, and this
    // thread is the unique consumer. The closure is `Send`.
    let job = unsafe { Box::from_raw(ptr.cast::<BoxedJob>()) };
    run_job(*job);
    std::ptr::null_mut()
}

#[cfg(unix)]
fn run_job(job: BoxedJob) {
    // Unwinding out of `extern "C"` is undefined. Release builds abort
    // inside the job (`panic = "abort"`) and never reach the catch.
    // Unwind builds (tests) catch so a panicked helper cannot cross the
    // C boundary; the panic hook has already printed.
    #[cfg(panic = "unwind")]
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(job));
    #[cfg(not(panic = "unwind"))]
    job();
}

#[cfg(not(unix))]
fn spawn_std(name: &str, job: BoxedJob, stack_bytes: Option<usize>) -> io::Result<SpawnedThread> {
    // Windows (and any other non-Unix target) has no sigaltstack mmap.
    // `CreateThread` failure is an `Err` from `Builder::spawn`, which is
    // the degrade path. A global-allocator abort is out of scope here.
    let mut builder = std::thread::Builder::new().name(name.to_owned());
    if let Some(stack_bytes) = stack_bytes {
        builder = builder.stack_size(stack_bytes);
    }
    let handle = builder.spawn(job)?;
    Ok(SpawnedThread {
        inner: SpawnedInner::Std(Some(handle)),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicU32, AtomicUsize};

    /// Fails the first `fail_first` spawns with EAGAIN, then spawns for real.
    struct FlakySpawn {
        fail_first: u32,
        calls: AtomicU32,
    }

    impl FlakySpawn {
        fn new(fail_first: u32) -> Self {
            Self {
                fail_first,
                calls: AtomicU32::new(0),
            }
        }
    }

    impl Spawn for FlakySpawn {
        fn spawn(&self, name: &str, job: BoxedJob) -> io::Result<SpawnedThread> {
            let call = self.calls.fetch_add(1, Ordering::SeqCst);
            if call < self.fail_first {
                drop(job); // exactly what Builder::spawn does on failure
                return Err(io::Error::from_raw_os_error(libc::EAGAIN));
            }
            StdSpawn.spawn(name, job)
        }
    }

    /// Models the failure std reports only by panicking in the child:
    /// the alternate-signal-stack mmap returns ENOMEM (os error 12).
    /// The production spawner must surface that as `Err` with the job
    /// handed back, so the caller can drop it inline and keep running.
    struct SigaltstackEnomem;

    impl Spawn for SigaltstackEnomem {
        fn spawn(&self, _name: &str, job: BoxedJob) -> io::Result<SpawnedThread> {
            drop(job);
            Err(io::Error::from_raw_os_error(12))
        }
    }

    #[test]
    fn a_failed_spawn_returns_the_job_instead_of_panicking() {
        let ran = Arc::new(AtomicUsize::new(0));
        let job_ran = Arc::clone(&ran);
        let failure = try_spawn_with(&FlakySpawn::new(1), true, "t1122", move || {
            job_ran.fetch_add(1, Ordering::SeqCst);
        })
        .expect_err("the spawner fails");
        assert_eq!(failure.error.raw_os_error(), Some(libc::EAGAIN));
        assert_eq!(ran.load(Ordering::SeqCst), 0, "nothing ran on a thread");
        // The caller can degrade by running the job inline.
        (failure.job.expect("job handed back"))();
        assert_eq!(ran.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn a_detached_worker_spawn_returns_enomem_and_does_not_run_the_job() {
        let ran = Arc::new(AtomicUsize::new(0));
        let job_ran = Arc::clone(&ran);
        let error = spawn_detached_with(&SigaltstackEnomem, "xerj-rayon-0", move || {
            job_ran.store(1, Ordering::SeqCst);
        })
        .expect_err("setup failure is an Err, not a panic");
        assert_eq!(error.raw_os_error(), Some(12));
        assert_eq!(
            ran.load(Ordering::SeqCst),
            0,
            "a refused pool worker must not run, and must not abort"
        );
    }

    #[test]
    fn an_enomem_setup_failure_returns_the_job_instead_of_panicking() {
        let ran = Arc::new(AtomicUsize::new(0));
        let job_ran = Arc::clone(&ran);
        let failure = try_spawn_with(&SigaltstackEnomem, true, "xerj-drain-free", move || {
            job_ran.fetch_add(1, Ordering::SeqCst);
        })
        .expect_err("setup failure is an Err, not a panic");
        assert_eq!(failure.error.raw_os_error(), Some(12));
        assert_eq!(
            ran.load(Ordering::SeqCst),
            0,
            "the job did not run on a thread"
        );
        // Drain-free drops the job (the capture's destructors free the
        // memtable). Pools run it inline. Either degrade keeps the process up.
        (failure.job.expect("job handed back"))();
        assert_eq!(ran.load(Ordering::SeqCst), 1);
    }

