//! On macOS the memory breaker must see the process's physical footprint, not
//! its resident set.
//!
//! The two diverge in both directions, and both hurt the breaker:
//!
//! * Pages the compressor has taken (or the pager swapped) leave the resident
//!   set but are still this process's memory. Under a 1 GiB cap a node read
//!   0.8 GB resident while it held 2.2 GB, so the breaker let it keep growing.
//! * Clean file-backed pages (mmapped segment files) count as resident but
//!   the kernel can drop them at any time, so they are not memory the process
//!   can be asked to give back.
//!
//! The first case cannot be forced from a test. The second can, and it tells
//! the two probes apart: map a file, read every page, and the resident set
//! grows by the file's size while the footprint does not move.
//!
//! One test binary of its own, so no other test allocates while it measures.

#![cfg(target_os = "macos")]

use std::io::Write as _;
use std::os::fd::AsRawFd as _;

use xerj_common::resource::current_rss_bytes;

const MIB: u64 = 1024 * 1024;
const SIZE: usize = 128 * 1024 * 1024;

fn probe() -> u64 {
    current_rss_bytes().expect("the macOS memory probe must work")
}

#[test]
fn the_memory_probe_counts_owned_memory_not_mapped_file_pages() {
    // Mapped, read, clean file pages.
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("mapped.bin");
    {
        let mut f = std::fs::File::create(&path).expect("create");
        let chunk = vec![0x5au8; 1024 * 1024];
        for _ in 0..(SIZE / chunk.len()) {
            f.write_all(&chunk).expect("write");
        }
        f.sync_all().expect("sync");
    }
    let file = std::fs::File::open(&path).expect("open");
    let before_map = probe();
    // SAFETY: read-only shared mapping of a file we own, unmapped below.
    let addr = unsafe {
        libc::mmap(
            std::ptr::null_mut(),
            SIZE,
            libc::PROT_READ,
            libc::MAP_SHARED,
            file.as_raw_fd(),
            0,
        )
    };
    assert_ne!(addr, libc::MAP_FAILED, "mmap failed");
    let bytes = addr as *const u8;
    let mut sum = 0u64;
    for off in (0..SIZE).step_by(4096) {
        // SAFETY: `off < SIZE`, inside the mapping.
        sum += u64::from(unsafe { std::ptr::read_volatile(bytes.add(off)) });
    }
    std::hint::black_box(sum);

    // The premise: the pages really are resident, or this test proves nothing.
    let page = 16 * 1024usize;
    let mut vec = vec![0 as libc::c_char; SIZE / page];
    // SAFETY: `vec` holds one byte per page of the mapping.
    let rc = unsafe { libc::mincore(addr, SIZE, vec.as_mut_ptr()) };
    assert_eq!(rc, 0, "mincore failed");
    let resident = vec.iter().filter(|&&b| b & 1 != 0).count();
    assert!(
        resident * 10 >= vec.len() * 9,
        "only {resident} of {} mapped pages are resident",
        vec.len()
    );

    let mapped_growth = probe().saturating_sub(before_map);
    // SAFETY: the mapping created above, with its length.
    unsafe { libc::munmap(addr, SIZE) };
    assert!(
        mapped_growth < 32 * MIB,
        "probe grew {} MiB for 128 MiB of clean mapped file pages",
        mapped_growth / MIB
    );

    // Positive control: memory the process owns does move the probe.
    let before_heap = probe();
    let heap: Vec<u8> = (0..SIZE).map(|i| (i % 251) as u8).collect();
    std::hint::black_box(&heap);
    let heap_growth = probe().saturating_sub(before_heap);
    assert!(
        heap_growth >= 96 * MIB,
        "probe grew only {} MiB for 128 MiB of touched heap",
        heap_growth / MIB
    );
}

//! A memory-relief helper (`xerj-drain-free`) must start when the governor
//! watermark gate is closed — that is when it is needed. Its own test binary
//! because the spawn gate is process-global (first install wins).

use std::sync::mpsc;
use std::time::Duration;

use xerj_common::thread_spawn::{
    install_spawn_gate, spawn_allowed, try_spawn, try_spawn_memory_relief,
};

fn at_watermark() -> bool {
    false
}

#[test]
fn drain_free_helper_starts_at_the_watermark() {
    assert!(install_spawn_gate(at_watermark));
    assert!(!spawn_allowed(), "gate simulates RSS at the watermark");

    // An ordinary best-effort helper is refused at the watermark...
    assert!(try_spawn("xerj-best-effort", || {}).is_err());

    // ...but the memory-relief helper starts and runs its job.
    let (tx, rx) = mpsc::channel();
    let handle = try_spawn_memory_relief("xerj-drain-free", move || {
        tx.send(()).unwrap();
    })
    .unwrap_or_else(|f| panic!("relief spawn refused at the watermark: {}", f.error));
    rx.recv_timeout(Duration::from_secs(10))
        .expect("relief job ran");
    handle.join().unwrap();
}

//! Two Windows installers, two directories. `landing/get` (the `sh` installer,
//! including Git Bash / MSYS / Cygwin) writes `xerj.exe` to `~/.local/bin`.
//! `landing/get.ps1` writes it to `%LOCALAPPDATA%\Programs\xerj` and adds that
//! directory to the user PATH. Docs that name only the PowerShell directory
//! send a Git Bash install looking in the wrong place (#2285).

use std::path::PathBuf;

fn repo(rel: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join(rel);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

/// Pages and agent-facing files that state where the binary lands.
const INSTALL_PATH_DOCS: &[&str] = &[
    "landing/docs/install.html",
    "landing/docs/agents/quickstart.html",
    "landing/docs/cli.html",
    "landing/llms.txt",
    "README.md",
    "AGENTS.md",
];

#[test]
fn install_docs_name_both_windows_installers() {
    let ps_dir = "%LOCALAPPDATA%\\Programs\\xerj";
    for rel in INSTALL_PATH_DOCS {
        let text = repo(rel);
        assert!(
            text.contains(ps_dir),
            "{rel} must name the PowerShell install directory {ps_dir}"
        );
        assert!(
            text.contains("~/.local/bin"),
            "{rel} must name the sh installer's directory, including on Windows Git Bash"
        );
        assert!(
            text.contains("Git Bash"),
            "{rel} must say the sh installer on Git Bash uses ~/.local/bin, not only the PowerShell path"
        );
        assert!(
            text.contains("PowerShell") || text.contains("get.ps1"),
            "{rel} must name the PowerShell installer that uses {ps_dir}"
        );
    }
}

#[test]
fn shell_installer_uses_home_local_bin_including_on_windows() {
    let sh = repo("landing/get");
    assert!(
        sh.contains("MINGW*|MSYS*|CYGWIN*"),
        "the sh installer must recognise Git Bash / MSYS / Cygwin"
    );
    assert!(
        sh.contains("bin=\"xerj.exe\""),
        "Windows via the sh installer installs xerj.exe"
    );
    assert!(
        sh.contains("dir=\"$HOME/.local/bin\""),
        "the sh installer's default directory is ~/.local/bin on every OS it supports"
    );
    // Comments may name the PowerShell directory so a later edit does not
    // retarget this script. The executable lines must not.
    let code: String = sh
        .lines()
        .filter(|l| !l.trim_start().starts_with('#'))
        .collect::<Vec<_>>()
        .join("\n");
    assert!(
        !code.contains("LOCALAPPDATA"),
        "the sh installer must not install to %LOCALAPPDATA%; that directory is get.ps1 only"
    );
}

#[test]
fn powershell_installer_uses_localappdata_programs() {
    let ps1 = repo("landing/get.ps1");
    assert!(
        ps1.contains("Join-Path $env:LOCALAPPDATA 'Programs\\xerj'"),
        "get.ps1 must keep its default of %LOCALAPPDATA%\\Programs\\xerj"
    );
    assert!(
        ps1.contains("XERJ_NO_PATH"),
        "get.ps1 adds the install directory to the user PATH unless XERJ_NO_PATH is set"
    );
}

//! Block compression for 128-document segments.
//!
//! Documents are accumulated into 128-doc blocks, compressed as a unit,
//! then emitted with a fixed header. Readers decompress on demand with
//! random access by block index.

use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use std::io::{Cursor, Read, Write};
use xerj_common::XerjError;

use crate::codec::{get_codec, Codec, CompressionLevel};

/// Result alias for block operations.
pub type Result<T> = std::result::Result<T, XerjError>;

/// Number of documents per compressed block.
pub const BLOCK_SIZE: usize = 128;

/// Magic bytes at the start of every block header.
const BLOCK_MAGIC: u32 = 0x5A424C4B; // "ZBLK"

// ─────────────────────────────────────────────────────────────────────────────
// Block header on-disk layout (20 bytes)
// ─────────────────────────────────────────────────────────────────────────────
//
//  Offset  Size  Field
//  ──────  ────  ─────────────────────────────
//       0     4  magic (ZBLK)
//       4     4  doc_count   (u32 LE)
//       8     4  uncompressed_len (u32 LE)
//      12     4  compressed_len   (u32 LE)
//      16     1  codec_id    (0=none, 1=lz4, 2=zstd)
//      17     3  reserved
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct BlockHeader {
    pub doc_count: u32,
    pub uncompressed_len: u32,
    pub compressed_len: u32,
    pub codec_id: u8,
}

impl BlockHeader {
    pub const SIZE: usize = 20;

    fn codec_id_for(level: CompressionLevel) -> u8 {
        match level {
            CompressionLevel::None => 0,
            CompressionLevel::Fast => 1,
            CompressionLevel::Balanced | CompressionLevel::Best => 2,
        }
    }

    fn write_to(&self, out: &mut impl Write) -> std::io::Result<()> {
        out.write_u32::<LittleEndian>(BLOCK_MAGIC)?;
        out.write_u32::<LittleEndian>(self.doc_count)?;
        out.write_u32::<LittleEndian>(self.uncompressed_len)?;
        out.write_u32::<LittleEndian>(self.compressed_len)?;
        out.write_u8(self.codec_id)?;
        out.write_all(&[0u8; 3])?; // reserved
        Ok(())
    }

    fn read_from(r: &mut impl Read) -> std::io::Result<Self> {
        let magic = r.read_u32::<LittleEndian>()?;
        if magic != BLOCK_MAGIC {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!("bad block magic: 0x{magic:08X}"),
            ));
        }
        let doc_count = r.read_u32::<LittleEndian>()?;
        let uncompressed_len = r.read_u32::<LittleEndian>()?;
        let compressed_len = r.read_u32::<LittleEndian>()?;
        let codec_id = r.read_u8()?;
        let mut _reserved = [0u8; 3];
        r.read_exact(&mut _reserved)?;
        Ok(Self {
            doc_count,
            uncompressed_len,
            compressed_len,
            codec_id,
        })
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// BlockWriter
// ─────────────────────────────────────────────────────────────────────────────

/// Accumulates raw serialized documents and emits compressed blocks of
/// [`BLOCK_SIZE`] documents each.
pub struct BlockWriter {
    codec: Box<dyn Codec>,
    codec_id: u8,
    #[allow(dead_code)]
    level: CompressionLevel,
    /// Length-prefixed raw document payloads for the current block.
    pending: Vec<u8>,
    pending_count: u32,
    /// Completed, compressed blocks ready for flushing.
    completed: Vec<u8>,
}

impl BlockWriter {
    pub fn new(level: CompressionLevel) -> Self {
        let codec_id = BlockHeader::codec_id_for(level);
        Self {
            codec: get_codec(level),
            codec_id,
            level,
            pending: Vec::new(),
            pending_count: 0,
            completed: Vec::new(),
        }
    }

    /// Add a serialized document to the current block.
    ///
    /// Each document is length-prefixed (u32 LE) inside the block payload so
    /// that individual records can be located after decompression.
    pub fn add_document(&mut self, doc: &[u8]) -> Result<()> {
        // Length prefix
        let len = doc.len() as u32;
        self.pending
            .write_u32::<LittleEndian>(len)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        self.pending.extend_from_slice(doc);
        self.pending_count += 1;

        if self.pending_count as usize >= BLOCK_SIZE {
            self.flush_block()?;
        }
        Ok(())
    }

    /// Flush any remaining documents as a partial block.
    pub fn finish(&mut self) -> Result<Vec<u8>> {
        if self.pending_count > 0 {
            self.flush_block()?;
        }
        Ok(std::mem::take(&mut self.completed))
    }

    fn flush_block(&mut self) -> Result<()> {
        let raw = std::mem::take(&mut self.pending);
        let uncompressed_len = raw.len() as u32;
        let doc_count = self.pending_count;
        self.pending_count = 0;

        let compressed = self.codec.compress(&raw)?;
        let compressed_len = compressed.len() as u32;

        let header = BlockHeader {
            doc_count,
            uncompressed_len,
            compressed_len,
            codec_id: self.codec_id,
        };
        header
            .write_to(&mut self.completed)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        self.completed.extend_from_slice(&compressed);
        Ok(())
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// BlockReader
// ─────────────────────────────────────────────────────────────────────────────

/// Reads compressed blocks written by [`BlockWriter`].
///
/// Decompression is lazy — only happens when [`next_block`] is called.
pub struct BlockReader<'a> {
    cursor: Cursor<&'a [u8]>,
}

impl<'a> BlockReader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self {
            cursor: Cursor::new(data),
        }
    }

    /// Read and decompress the next block, returning individual documents.
    ///
    /// Returns `None` when all blocks have been consumed.
    pub fn next_block(&mut self) -> Result<Option<Vec<Vec<u8>>>> {
        if self.cursor.position() as usize >= self.cursor.get_ref().len() {
            return Ok(None);
        }

        let header = BlockHeader::read_from(&mut self.cursor)
            .map_err(|e| XerjError::internal(format!("block header read: {e}")))?;

        let mut compressed = vec![0u8; header.compressed_len as usize];
        self.cursor
            .read_exact(&mut compressed)
            .map_err(|e| XerjError::internal(format!("block data read: {e}")))?;

        // Select decompressor by codec_id
        let decompressed = match header.codec_id {
            0 => {
                // None
                if compressed.len() != header.uncompressed_len as usize {
                    return Err(XerjError::internal("None codec length mismatch"));
                }
                compressed
            }
            1 => {
                // LZ4
                lz4_flex::decompress_size_prepended(&compressed)
                    .map_err(|e| XerjError::internal(format!("LZ4 decompress: {e}")))?
            }
            2 => {
                // Zstd
                zstd::bulk::decompress(&compressed, header.uncompressed_len as usize)
                    .map_err(|e| XerjError::internal(format!("Zstd decompress: {e}")))?
            }
            id => return Err(XerjError::internal(format!("unknown codec_id: {id}"))),
        };

        // Split individual documents by length prefix
        let mut docs = Vec::with_capacity(header.doc_count as usize);
        let mut rdr = Cursor::new(decompressed);
        for _ in 0..header.doc_count {
            let len = rdr
                .read_u32::<LittleEndian>()
                .map_err(|e| XerjError::internal(format!("doc len read: {e}")))?
                as usize;
            let mut doc = vec![0u8; len];
            rdr.read_exact(&mut doc)
                .map_err(|e| XerjError::internal(format!("doc data read: {e}")))?;
            docs.push(doc);
        }

        Ok(Some(docs))
    }

    /// Collect all documents from all blocks.
    pub fn read_all(&mut self) -> Result<Vec<Vec<u8>>> {
        let mut all = Vec::new();
        while let Some(block) = self.next_block()? {
            all.extend(block);
        }
        Ok(all)
    }
}

