            "172.16.0.50",
            "192.168.1.2",
            "8.8.8.8",
        ];
        let refs: Vec<&str> = ips.to_vec();
        let enc = analyzer.analyze("client_ip", &refs);

        match &enc {
            FieldEncoding::PackedIp { values } => {
                assert_eq!(values.len(), 5);
                assert_eq!(values[0], parse_ipv4("192.168.1.1").unwrap());
            }
            other => panic!("expected PackedIp, got {:?}", std::mem::discriminant(other)),
        }

        assert_eq!(enc.bytes_per_value(), 4.0);
        println!(
            "ip: {:.2} bytes/value (raw ~14), ratio {:.1}x",
            enc.bytes_per_value(),
            enc.compression_ratio_vs_raw()
        );
    }

    #[test]
    fn test_url_template_encoding() {
        let analyzer = FieldAnalyzer::new(1024);
        let paths = [
            "/api/users/1",
            "/api/users/2",
            "/api/users/3",
            "/api/users/4/posts",
            "/static/js/app.js",
            "/static/css/main.css",
        ];
        let refs: Vec<&str> = paths.to_vec();
        let enc = analyzer.analyze("path", &refs);

        match &enc {
            FieldEncoding::UrlTemplate {
                templates,
                template_ids,
                variables,
            } => {
                assert!(
                    templates.len() < paths.len(),
                    "should deduplicate templates"
                );
                assert_eq!(template_ids.len(), paths.len());
                assert_eq!(variables.len(), paths.len());
                println!("URL templates: {:?}", templates);
            }
            other => panic!(
                "expected UrlTemplate, got {:?}",
                std::mem::discriminant(other)
            ),
        }

        println!(
            "path: {:.2} bytes/value (raw ~30), ratio {:.1}x",
            enc.bytes_per_value(),
            enc.compression_ratio_vs_raw()
        );
    }

    #[test]
    fn test_varint_encoding() {
        let analyzer = FieldAnalyzer::new(1024);
        let sizes = ["1024", "2048", "512", "65536", "128", "256"];
        let refs: Vec<&str> = sizes.to_vec();
        let enc = analyzer.analyze("content_length", &refs);

        assert!(matches!(enc, FieldEncoding::Varint { .. }));
        println!(
            "content_length: {:.2} bytes/value (raw ~4), ratio {:.1}x",
            enc.bytes_per_value(),
            enc.compression_ratio_vs_raw()
        );
    }

    #[test]
    fn test_boolean_encoding() {
        let analyzer = FieldAnalyzer::new(1024);
        // 2 unique values → BitsetEnum wins (most compact for tiny cardinality)
        let bools: Vec<&str> = (0..64)
            .map(|i| if i % 3 == 0 { "true" } else { "false" })
            .collect();
        let enc = analyzer.analyze("is_active", &bools);
        // Either BitsetEnum or Bitpacked is correct — both are compact
        assert!(
            matches!(enc, FieldEncoding::Bitpacked { .. })
                || matches!(enc, FieldEncoding::BitsetEnum { .. }),
            "expected compact bool encoding"
        );
        assert!(enc.bytes_per_value() < 1.0);
    }

    #[test]
    fn test_float_encoding() {
        let analyzer = FieldAnalyzer::new(1024);
        // Generate 20 distinct float values so cardinality > 16 bypasses BitsetEnum
        let floats: Vec<String> = (0..20).map(|i| format!("{:.2}", i as f64 + 0.34)).collect();
        let refs: Vec<&str> = floats.iter().map(String::as_str).collect();
        let enc = analyzer.analyze("response_time_ms", &refs);

        match &enc {
            FieldEncoding::FixedPrecision { scale, values } => {
                assert_eq!(*scale, 2);
                // First value: 0.34 → 34
                assert_eq!(values[0], 34);
                assert_eq!(values.len(), 20);
            }
            other => panic!(
                "expected FixedPrecision, got {:?}",
                std::mem::discriminant(other)
            ),
        }
    }

    #[test]
    fn test_dictionary_medium_cardinality() {
        let analyzer = FieldAnalyzer::new(1024);
        // 20 unique hostnames — above 16 (BitsetEnum) but below 256 (Dictionary)
        let hosts: Vec<String> = (0..20)
            .flat_map(|i| vec![format!("host-{i}.example.com"); 5])
            .collect();
        let refs: Vec<&str> = hosts.iter().map(String::as_str).collect();
        let enc = analyzer.analyze("hostname", &refs);
        assert!(matches!(enc, FieldEncoding::Dictionary { .. }));
    }

    #[test]
    fn test_raw_string_fallback() {
        let analyzer = FieldAnalyzer::new(1024);
        // High cardinality, non-structured strings
        let msgs: Vec<String> = (0..500)
            .map(|i| format!("Unique log message number {i} with some context"))
            .collect();
        let refs: Vec<&str> = msgs.iter().map(String::as_str).collect();
        let enc = analyzer.analyze("message", &refs);
        assert!(matches!(enc, FieldEncoding::RawString { .. }));
    }

    // ── Compression ratio demo — realistic Apache access log simulation ───

    /// Simulates 10 000 Apache access log entries and measures compression
    /// ratios for each field using its optimal encoding.
    #[test]
    fn test_apache_log_compression_ratios() {
        let n = 10_000usize;

        // Simulate field distributions that match real Apache logs
        let statuses: Vec<&str> = (0..n)
            .map(|i| match i % 20 {
                0 => "404",
                1 => "500",
                2 | 3 => "301",
                4 => "403",
                _ => "200",
            })
            .collect();

        let methods: Vec<&str> = (0..n)
            .map(|i| match i % 10 {
                8 => "POST",
                9 => "PUT",
                _ => "GET",
            })
            .collect();

        let ips: Vec<String> = (0..n)
            .map(|i| format!("192.168.{}.{}", (i / 256) % 256, i % 256))
            .collect();
        let ip_refs: Vec<&str> = ips.iter().map(String::as_str).collect();

        let timestamps: Vec<String> = (0..n)
            .map(|i| format!("2024-01-15T12:{:02}:{:02}Z", (i / 60) % 60, i % 60))
            .collect();
        let ts_refs: Vec<&str> = timestamps.iter().map(String::as_str).collect();

        let paths: Vec<String> = (0..n)
            .map(|i| match i % 5 {
                0 => format!("/api/users/{}", i),
                1 => format!("/api/posts/{}", i / 5),
                2 => "/api/health".to_string(),
                3 => format!("/static/js/app.{:08x}.js", i),
                _ => format!("/api/items/{}/details", i % 100),
            })
            .collect();
        let path_refs: Vec<&str> = paths.iter().map(String::as_str).collect();

        let sizes: Vec<String> = (0..n)
            .map(|i| (512 + (i * 137) % 65536).to_string())
            .collect();
        let size_refs: Vec<&str> = sizes.iter().map(String::as_str).collect();

        let analyzer = FieldAnalyzer::new(1024);

        let status_enc = analyzer.analyze("status", &statuses);
        let method_enc = analyzer.analyze("method", &methods);
        let ip_enc = analyzer.analyze("client_ip", &ip_refs);
        let ts_enc = analyzer.analyze("@timestamp", &ts_refs);
        let path_enc = analyzer.analyze("path", &path_refs);
        let size_enc = analyzer.analyze("content_length", &size_refs);

        // Print compression summary
        println!("\n=== Apache Access Log Compression Ratios ({n} docs) ===");
        println!(
            "{:<20} {:>10} {:>10} {:>8}",
            "field", "bytes/val", "raw bytes", "ratio"
        );
        println!("{}", "-".repeat(52));

        let fields: &[(&str, &FieldEncoding, f64)] = &[
            ("status", &status_enc, 3.0),
            ("method", &method_enc, 4.0),
            ("client_ip", &ip_enc, 14.0),
            ("@timestamp", &ts_enc, 25.0),
            ("path", &path_enc, 30.0),
            ("content_length", &size_enc, 6.0),
        ];

        for (name, enc, raw_bpv) in fields {
            println!(
                "{:<20} {:>10.2} {:>10.1} {:>8.1}x",
                name,
                enc.bytes_per_value(),
                raw_bpv,
                raw_bpv / enc.bytes_per_value().max(0.01)
            );
        }

        // Validate specific assertions from the spec
        // status: 0.5 bytes vs 3
        assert!(
            status_enc.bytes_per_value() < 1.5,
            "status should use <1.5 bytes/value, got {:.2}",
            status_enc.bytes_per_value()
        );

        // IP: 4 bytes vs 15
        assert!(
            (ip_enc.bytes_per_value() - 4.0).abs() < 0.01,
            "IP should use exactly 4 bytes/value"
        );

        // method: < 1.5 bytes vs 4
        assert!(
            method_enc.bytes_per_value() < 1.5,
            "method should use <1.5 bytes/value"
        );

        // path: should compress vs raw (at least 2x)
        assert!(
            path_enc.compression_ratio_vs_raw() > 1.5,
            "path should compress >1.5x, got {:.2}x",
            path_enc.compression_ratio_vs_raw()
        );

        // timestamp: < 4 bytes/value (delta-of-delta of 1s intervals → small deltas)
        assert!(
            ts_enc.bytes_per_value() < 4.0,
            "timestamp should use <4 bytes/value, got {:.2}",
            ts_enc.bytes_per_value()
        );

        // Total bytes across all fields
        let total_encoded = status_enc.total_bytes()
            + method_enc.total_bytes()
            + ip_enc.total_bytes()
            + ts_enc.total_bytes()
            + path_enc.total_bytes()
            + size_enc.total_bytes();

        let total_raw = (3 + 4 + 14 + 25 + 30 + 6) * n;

        println!("\nTotal encoded: {} bytes", total_encoded);
        println!("Total raw:     {} bytes", total_raw);
        println!(
            "Overall ratio: {:.1}x",
            total_raw as f64 / total_encoded as f64
        );

        assert!(
            total_encoded < total_raw,
            "encoded ({total_encoded}) should be smaller than raw ({total_raw})"
        );
    }

    #[test]
    fn test_bitset_enum_bitmap_correctness() {
        let analyzer = FieldAnalyzer::new(1024);
        // Exact pattern: [A, B, A, C, A, B]
        let vals = vec!["A", "B", "A", "C", "A", "B"];
        let enc = analyzer.encode_as_bitset_enum(&vals);

        if let FieldEncoding::BitsetEnum { values, bitmap } = &enc {
            let idx_a = values.iter().position(|v| v == "A").unwrap();
            let bmap_a = &bitmap[idx_a];
            // A is at positions 0, 2, 4 → bits 0, 2, 4 of byte 0 → 0b00010101 = 0x15
            assert_eq!(bmap_a[0] & 0b00010101, 0b00010101);
            // A is NOT at position 1, 3, 5
            assert_eq!(bmap_a[0] & 0b00101010, 0);
        } else {
            panic!("expected BitsetEnum");
        }
    }

    #[test]
    fn test_delta_timestamp_regularity() {
        // Regular 1-second intervals should produce tiny delta-of-delta values
        let analyzer = FieldAnalyzer::new(1024);
        let timestamps: Vec<String> = (0..100)
            .map(|i| format!("2024-01-15T00:00:{:02}Z", i))
            .collect();
        let refs: Vec<&str> = timestamps.iter().map(String::as_str).collect();
        let enc = analyzer.analyze("@timestamp", &refs);

        if let FieldEncoding::DeltaTimestamp { deltas, .. } = &enc {
            // First delta = 1_000_000 µs, all subsequent delta-of-deltas = 0
            let dod_zeros = deltas[1..].iter().filter(|&&d| d == 0).count();
            assert!(
                dod_zeros as f64 / (deltas.len() - 1) as f64 > 0.95,
                "regular timestamps should produce mostly zero delta-of-deltas"
            );
        }
    }

    #[test]
    fn test_unique_count() {
        let vals = vec!["a", "b", "a", "c", "b", "a"];
        assert_eq!(unique_count(&vals), 3);
    }

    #[test]
    fn test_compression_ratio_vs_raw() {
        let analyzer = FieldAnalyzer::new(1024);
        let ips: Vec<String> = (0..100).map(|i| format!("10.0.0.{}", i % 256)).collect();
        let refs: Vec<&str> = ips.iter().map(String::as_str).collect();
        let enc = analyzer.analyze("client_ip", &refs);
        // PackedIp uses 4 bytes vs ~10 bytes average for these IPs
        assert!(enc.compression_ratio_vs_raw() > 2.0);
    }
}

//! # xerj-compress
//!
//! Compression engine for the xerj search engine.
//!
//! Provides:
//! - [`codec`] — Codec trait with LZ4, Zstd, and passthrough implementations
//! - [`block`] — Block-level compression for 128-document segments
//! - [`dictionary`] — Dictionary encoding for repeated string values
//! - [`field_codec`] — Intelligent automatic field encoding engine

pub mod block;
pub mod codec;
pub mod dictionary;
pub mod field_codec;

pub use block::{BlockReader, BlockWriter};
pub use codec::{get_codec, Codec, CompressionLevel, Lz4Codec, NoneCodec, ZstdCodec};
pub use dictionary::{DictionaryDecoder, DictionaryEncoder};
pub use field_codec::{FieldAnalyzer, FieldEncoding, TimestampFormat};

pub use xerj_common::Result;

[package]
name = "xerj-console-api"
version.workspace = true
edition.workspace = true
license.workspace = true
authors.workspace = true
description = "Xerj Console backend API: dashboards, auth, prefs, cluster awareness, and pluggable data sources. Ships compiled into the xerj v1.0 binary; extracts post-v1.0 as a standalone product that can target any data source."

# Bundles the Xerj Console UX (xerj-ux/) (HTML/CSS/JS) into the binary. Walks the
# xerj-ux/ source tree at compile time and emits a `(url, bytes,
# content_type)` slice consumed by `src/spa.rs`.
build = "build.rs"

# Why this is `xerj-console-api`, not `xerj-xerj-console-api`:
# - Xerj Console is its own product. v1.0.x bundles it inside the xerj binary for
#   simplicity, but the surface is *not* "xerj's adapter for the Xerj Console UI" —
#   xerj is just one possible backend (the default), and the crate must
#   stand on its own when extracted (post-v1.0) to connect against ES,
#   OpenSearch, Prometheus, Postgres, or a remote xerj cluster. Naming it
#   xerj-* would freeze the dependency direction the wrong way.
# - The `xerj-local` data-source adapter that talks to the in-process Engine
#   is one of several adapters this crate hosts; it gets no naming privilege
#   over the others.
# - It pulls heavier dependencies (webauthn-rs, axum-extra cookies, sha2,
#   AEAD for connection-secrets crypt) that have no business in the engine's
#   ES-compat layer.

[dependencies]
# Engine-side deps are used by the bundled `xerj-local` adapter, the
# bootstrap helpers, and the cluster/info handler. When this crate is
# extracted post-v1.0 they move behind a `bundled` feature so the standalone
# build can drop them and pull only HTTP-shaped adapters (xerj-remote,
# elasticsearch, opensearch, prometheus, postgres). Unconditional in v1.0
# to keep the build matrix simple while we ship.
xerj-common  = { path = "../xerj-common" }
xerj-engine  = { path = "../xerj-engine" }
xerj-cluster = { path = "../xerj-cluster" }
xerj-query   = { path = "../xerj-query" }

tokio        = { workspace = true }
axum         = { workspace = true }
tower        = { workspace = true }
tower-http   = { workspace = true }
serde        = { workspace = true }
serde_json   = { workspace = true }
tracing      = { workspace = true }
thiserror    = { workspace = true }
anyhow       = { workspace = true }
uuid         = { workspace = true }
chrono       = { workspace = true }
bytes        = { workspace = true }
dashmap      = { workspace = true }
rand         = { workspace = true }
arc-swap     = { workspace = true }
async-trait  = "0.1"

# Crypto: token hashing, cookie signing, AEAD for connection secrets.
sha2         = "0.10"
hmac         = "0.12"
base64       = "0.22"
subtle       = "2"            # constant-time comparison

# WebAuthn / passkeys.
webauthn-rs  = { version = "0.5", default-features = false, features = ["danger-allow-state-serialisation"] }
# webauthn-rs-core links OpenSSL. Vendor it (compiled from source per
# target) so the 8 cross-compiled release binaries are self-contained —
# without this every non-native release target fails in openssl-sys
# looking for system headers that aren't there.
openssl      = { version = "0.10", features = ["vendored"] }

# Cookie helpers (HttpOnly, Secure, SameSite=Lax session cookies).
axum-extra   = { version = "0.9", features = ["cookie"] }

# Time math beyond what chrono gives us at-a-glance.
time         = { version = "0.3", features = ["serde"] }

[dev-dependencies]
tempfile     = { workspace = true }
tower        = { workspace = true, features = ["util"] }
http-body-util = "0.1"

// Bundle the Xerj Console UX (typography-first observability SPA)
// into the xerj binary at compile time.
//
// We walk a single source directory (`xerj-ux/` at the repo root) and
// emit `$OUT_DIR/xerj_console_assets.rs` with a const slice of
// (path, bytes) entries. The asset paths are relative to the
// xerj-ux root and used as the URL path under `/_xerj-console/`.
//
// We deliberately ship only HTML / CSS / JS / SVG / WOFF — anything
// the runtime would never serve to a browser stays out. Files larger
// than 4 MiB are skipped with a build-script warning so an accidental
// PDF in the UX tree doesn't bloat the binary.
//
// Re-run logic: cargo invokes this script when build.rs itself
// changes OR when anything under the xerj-ux source tree is modified,
// added or removed (we emit `cargo:rerun-if-changed` for the tree root
// as well as for each bundled file).

use std::env;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

// Path-resolution strategy: try multiple relative paths so the build
// works from the repo-root layout and from an engine-worktree layout
// (engine/ checked out separately, with the repo root alongside).
const UX_RELS: &[&str] = &[
    "../../../xerj-ux",    // engine/crates/api → repo root → xerj-ux
    "../../../../xerj-ux", // worktree → parent → xerj-ux (sibling)
    "../../xerj-ux",       // direct sibling layout
];
const ALLOWED_EXTS: &[&str] = &["html", "css", "js", "svg", "ico", "woff", "woff2", "png"];
const MAX_FILE_BYTES: u64 = 4 * 1024 * 1024;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    // Walk the candidate list and pick the first one that resolves to
    // an existing xerj-ux directory.
    let ux_root = UX_RELS
        .iter()
        .map(|rel| manifest_dir.join(rel))
        .find_map(|p| fs::canonicalize(&p).ok())
        .or_else(|| {
            // Last-ditch: env var override for CI / monorepo packaging.
            env::var("XERJ_CONSOLE_UX_DIR")
                .ok()
                .and_then(|p| fs::canonicalize(p).ok())
        });
    let ux_root = match ux_root {
        Some(p) => p,
        None => {
            // xerj-ux checkout missing — emit an empty asset table so the
            // engine still builds (e.g. release tarballs that omit the UX).
            write_assets(&[], &manifest_dir);
            println!(
                "cargo:warning=xerj-ux not found in any of: {:?} — Console asset table will be empty (set XERJ_CONSOLE_UX_DIR to override)",
                UX_RELS,
            );
            return;
        }
    };

    // The per-file lines emitted by `walk` only cover files that existed the
    // last time this script ran, so a NEW file — or a whole new directory, as
    // `share/` was — never re-triggered the script on a warm target dir: the
    // binary built, and served 404 for assets that were sitting in the tree.
    // A directory path makes cargo scan the tree, which catches additions and
    // removals as well as edits.
    println!("cargo:rerun-if-changed={}", ux_root.display());

    let mut entries: Vec<(String, PathBuf)> = Vec::new();
    walk(&ux_root, &ux_root, &mut entries);
    entries.sort();

    write_assets(&entries, &ux_root);
}

fn walk(root: &Path, dir: &Path, out: &mut Vec<(String, PathBuf)>) {
    let read = match fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return,
    };
    for entry in read.flatten() {
        let path = entry.path();
        // Skip hidden files / dirs and node_modules (xerj-ux is
        // currently a buildless static SPA but a future build step
        // might pull deps).
        let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if name.starts_with('.') || name == "node_modules" {
            continue;
        }
        let meta = match fs::metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        if meta.is_dir() {
            walk(root, &path, out);
            continue;
        }
        if meta.len() > MAX_FILE_BYTES {
            println!(
                "cargo:warning=xerj-console skipping {} (>{} bytes)",
                path.display(),
                MAX_FILE_BYTES
            );
            continue;
        }
        let ext = path
            .extension()
            .and_then(|e| e.to_str())
            .map(str::to_ascii_lowercase)
            .unwrap_or_default();
        if !ALLOWED_EXTS.contains(&ext.as_str()) {
            continue;
        }
        let rel = path.strip_prefix(root).unwrap_or(&path);
        let url_path = rel
            .components()
            .map(|c| c.as_os_str().to_string_lossy().into_owned())
            .collect::<Vec<_>>()
            .join("/");
        println!("cargo:rerun-if-changed={}", path.display());
        out.push((url_path, path));
    }
}

fn write_assets(entries: &[(String, PathBuf)], _ux_root: &Path) {
    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
    let out_path = out_dir.join("xerj_console_assets.rs");
    let mut f = fs::File::create(&out_path).expect("create xerj_console_assets.rs");

    writeln!(
        f,
        "// auto-generated by build.rs — Xerj Console UX asset bundle\n\
         //\n\
         // (url_path, bytes, content_type) tuples. Order is sorted-by-path\n\
         // so the runtime can binary-search by path.\n\
         pub static XERJ_CONSOLE_ASSETS: &[(&str, &[u8], &str)] = &["
    )
    .unwrap();
    for (url_path, src_path) in entries {
        let ct = content_type_for(url_path);
        // Use absolute path so include_bytes! doesn't depend on the
        // build cwd. include_bytes! is a compile-time op so any change
        // to the source content invalidates the build via the
        // rerun-if-changed lines above.
        writeln!(
            f,
            "    (\"{}\", include_bytes!(r\"{}\"), \"{}\"),",
            url_path,
            src_path.display(),
            ct,
        )
        .unwrap();
    }
    writeln!(f, "];").unwrap();
}

fn content_type_for(path: &str) -> &'static str {
    let ext = path.rsplit('.').next().unwrap_or("");
    match ext.to_ascii_lowercase().as_str() {
        "html" => "text/html; charset=utf-8",
        "css" => "text/css; charset=utf-8",
        "js" => "application/javascript; charset=utf-8",
        "svg" => "image/svg+xml",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "png" => "image/png",
        "json" => "application/json; charset=utf-8",
        _ => "application/octet-stream",
    }
}

//! Append a row to `.xerj_audit` for every auth-relevant write.
//!
//! Best-effort: a failed audit write returns Ok(()) and logs at WARN.
//! We never fail the user-facing request because audit was unavailable —
//! that would let a transient engine error block all logins.

use serde_json::json;
use uuid::Uuid;
use xerj_engine::Engine;

use crate::indices;
use crate::time::now_iso;

/// Append an audit row. `who` is the principal ("system" for unauthenticated
/// flows like login_begin), `action` is short kebab-case
/// (e.g. `"magic-redeemed"`, `"passkey-enrolled"`, `"session-minted"`).
pub async fn record(
    engine: &Engine,
    who: &str,
    action: &str,
    resource: &str,
    resource_id: Option<&str>,
    ip: Option<&str>,
    extra: Option<serde_json::Value>,
) {
    let id = Uuid::new_v4().to_string();
    let mut doc = json!({
        "who":         who,
        "when":        now_iso(),
        "action":      action,
        "resource":    resource,
        "resource_id": resource_id,
        "ip":          ip,
    });
    if let Some(extra) = extra {
        doc["extra"] = extra;
    }

    let idx = match engine.get_index(indices::AUDIT) {
        Ok(i) => i,
        Err(e) => {
            tracing::warn!(error = %e, "audit: cannot open .xerj_audit index");
            return;
        }
    };
    if let Err(e) = idx.create_document(id, doc).await {
        tracing::warn!(error = %e, action, "audit write failed");
    }
}

//! Returning-user login via passkey assertion.
//!
//! - `POST /auth/login/begin   { email }`
//!   → returns the WebAuthn `RequestChallengeResponse` JSON.
//!   Even when the email is unknown we return a *fake* challenge with
//!   no allow-credentials so the response shape is identical — this
//!   denies an attacker the email-enumeration oracle.
//! - `POST /auth/login/finish  { challenge_id, credential }`
//!   → validates the assertion, mints a session cookie.
//!
//! Logout: `POST /auth/logout` revokes the current passkey session.
//! A bearer API token is 403 and does not revoke anything.

use axum::{
    extract::State,
    http::HeaderMap,
    response::{IntoResponse, Response},
    Json,
};
use rand::RngCore;
use serde::{Deserialize, Serialize};
use serde_json::json;
use webauthn_rs::prelude::*;

use crate::auth::{audit, rate_limit, sessions, store, webauthn_setup};
use crate::client_ip::ClientIp;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::response::ok;
use crate::state::{ChallengeKind, ConsoleState, PendingChallenge};
use crate::time::{now_epoch_ms, now_iso};

const CHALLENGE_TTL_MS: i64 = 5 * 60 * 1000;

// ─────────────────────────────────────────────────────────────────────────────
// Begin
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct BeginBody {
    pub email: String,
}

#[derive(Debug, Serialize)]
pub struct BeginResponse {
    pub challenge_id: String,
    pub request_options: RequestChallengeResponse,
}

pub async fn begin(
    State(state): State<ConsoleState>,
    ClientIp(ip): ClientIp,
    Json(body): Json<BeginBody>,
) -> ConsoleResult<Response> {
    rate_limit::charge(&state, &ip, "login-begin")?;

    if body.email.is_empty() {
        return Err(ConsoleApiError::BadRequest("missing email".into()));
    }

    // Find the user (may be None — we still return a challenge to avoid
    // enumeration).
    let user = store::find_user_by_email(&state.engine, &body.email).await?;

    // Collect this user's passkeys (empty list when user is None).
    let passkeys: Vec<Passkey> = match &user {
        None => Vec::new(),
        Some(u) => store::list_passkeys_for_user(&state.engine, &u.id)
            .await?
            .into_iter()
            .filter_map(|p| serde_json::from_value(p.blob).ok())
            .collect(),
    };

    let webauthn = webauthn_setup::build(&state)?;
    let (request_options, auth_state) = if passkeys.is_empty() {
        // Fake challenge: build a real challenge for an empty-credential
        // set so the response shape matches a known-user response.
        let fake_passkey: Vec<Passkey> = Vec::new();
        webauthn
            .start_passkey_authentication(&fake_passkey)
            .map_err(|e| ConsoleApiError::Internal(format!("start fake auth: {e}")))?
    } else {
        webauthn
            .start_passkey_authentication(&passkeys)
            .map_err(|e| ConsoleApiError::Internal(format!("start auth: {e}")))?
    };

    let challenge_id = random_id();
    state.pending_challenges.insert(
        challenge_id.clone(),
        PendingChallenge {
            kind: ChallengeKind::Login {
                email: user.as_ref().map(|u| u.email.clone()),
                state: auth_state,
            },
            created_at_ms: now_epoch_ms(),
        },
    );
    prune_pending(&state);

    Ok(ok(
        BeginResponse {
            challenge_id,
            request_options,
        },
        None,
    ))
}

// ─────────────────────────────────────────────────────────────────────────────
// Finish
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct FinishBody {
    pub challenge_id: String,
    pub credential: PublicKeyCredential,
}

pub async fn finish(
    State(state): State<ConsoleState>,
    ClientIp(ip): ClientIp,
    headers: HeaderMap,
    Json(body): Json<FinishBody>,
) -> ConsoleResult<Response> {
    rate_limit::charge(&state, &ip, "login-finish")?;

    let pending = state
        .pending_challenges
        .remove(&body.challenge_id)
        .map(|(_, v)| v)
        .ok_or_else(|| ConsoleApiError::Unauthorized("unknown challenge".into()))?;
    let auth_state = match pending.kind {
        ChallengeKind::Login { state: s, .. } => s,
        _ => return Err(ConsoleApiError::Unauthorized("wrong challenge kind".into())),
    };

    let webauthn = webauthn_setup::build(&state)?;
    let auth_result: AuthenticationResult = webauthn
        .finish_passkey_authentication(&body.credential, &auth_state)
        .map_err(|e| {
            tracing::debug!(error = %e, "passkey authentication failed");
            ConsoleApiError::Unauthorized("authentication failed".into())
        })?;

    // Look up the credential we just authenticated, then the user.
    let cred_id_b64 = base64::engine::general_purpose::URL_SAFE_NO_PAD
        .encode::<&[u8]>(auth_result.cred_id().as_ref());
    let pk = match get_passkey_by_id(&state, &cred_id_b64).await? {
        Some(p) => p,
        None => {
            // Should be impossible given the challenge state used the
            // same credential set, but stay defensive.
            return Err(ConsoleApiError::Unauthorized(
                "authentication failed".into(),
            ));
        }
    };

    let user = store::get_user(&state.engine, &pk.user_id)
        .await?
        .ok_or_else(|| ConsoleApiError::Unauthorized("user gone".into()))?;
    if user.status != store::UserStatus::Active {
        return Err(ConsoleApiError::Unauthorized("user disabled".into()));
    }

    // Update last_used_at on the passkey + sign-count is handled inside
    // webauthn-rs's Passkey state which we re-serialise.
    let mut updated_pk = pk.clone();
    updated_pk.last_used_at = Some(now_iso());
    // Re-serialise the Passkey blob so any internal counter updates land.
    if let Ok(typed) = serde_json::from_value::<Passkey>(pk.blob.clone()) {
        updated_pk.blob = serde_json::to_value(&typed).unwrap_or(pk.blob);
    }
    store::put_passkey(&state.engine, &updated_pk).await?;

    let ua = headers
        .get("user-agent")
        .and_then(|h| h.to_str().ok())
        .map(|s| s.to_string());
    let (_session, signed) =
        sessions::mint_session(&state, &user.id, "passkey", Some(ip.clone()), ua).await?;

    audit::record(
        &state.engine,
        &user.id,
        "session-minted",
        indices::SESSIONS,
        None,
        Some(&ip),
        Some(json!({ "via": "login" })),
    )
    .await;

    let cookie = sessions::make_set_cookie(signed, false);
    let body = ok(
        json!({
            "user": {
                "id":    user.id,
                "email": user.email,
                "role":  user.role,
            }
        }),
        None,
    );
    Ok((
        axum_extra::extract::cookie::CookieJar::new().add(cookie),
        body,
    )
        .into_response())
}

// ─────────────────────────────────────────────────────────────────────────────
// Logout
// ─────────────────────────────────────────────────────────────────────────────

pub async fn logout(
    State(state): State<ConsoleState>,
    sess: sessions::PasskeySession,
) -> ConsoleResult<Response> {
    store::revoke_session(&state.engine, &sess.session_id, &now_iso()).await?;
    audit::record(
        &state.engine,
        &sess.user.id,
        "session-revoked",
        indices::SESSIONS,
        Some(&sess.session_id),
        None,
        Some(json!({ "reason": "logout" })),
    )
    .await;
    let cookie = sessions::make_clear_cookie();
    Ok((
        axum_extra::extract::cookie::CookieJar::new().add(cookie),
        ok(json!({}), None),
    )
        .into_response())
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

async fn get_passkey_by_id(
    state: &ConsoleState,
    credential_id: &str,
) -> ConsoleResult<Option<store::StoredPasskey>> {
    let idx = state.engine.get_index(indices::PASSKEYS)?;
    let body = json!({
        "query": { "ids": { "values": [credential_id] } },
        "size": 1
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    Ok(match r.hits.into_iter().next() {
        None => None,
        Some(h) => Some(serde_json::from_value(h.source)?),
    })
}

fn random_id() -> String {
    let mut b = [0u8; 24];
    rand::thread_rng().fill_bytes(&mut b);
    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(b)
}

fn prune_pending(state: &ConsoleState) {
    let cutoff = now_epoch_ms() - CHALLENGE_TTL_MS;
    state
        .pending_challenges
        .retain(|_k, v| v.created_at_ms > cutoff);
}

use base64::Engine as _;

//! Magic-link issue + redemption.
//!
//! `POST /auth/magic/issue   { email, role }`
//!
//! An owner or admin mints a single-use invite link for `email`. If no
//! user with that email exists yet a `pending` row is provisioned so the
//! invitee flips to `active` once they enrol a passkey. The raw token is
//! returned exactly once; only its `sha256` is persisted.
//!
//! `POST /auth/magic/redeem  { token }`
//!
//! Looks up `sha256(token)` in `.xerj_magic_links`, validates expiry
//! and single-use, marks `used_at = now`, and returns an enrollment
//! session id the SPA echoes back on `POST /auth/passkey/begin`.
//!
//! Enrollment session lives only in RAM (not persisted) for 30 minutes
//! and is consumed exactly once by `passkey/finish`.

use axum::{extract::State, response::Response, Json};
use rand::RngCore;
use serde::{Deserialize, Serialize};
use serde_json::json;

use crate::auth::{audit, rate_limit, store, PasskeySession};
use crate::bootstrap::sha256_hex;
use crate::client_ip::ClientIp;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::response::ok;
use crate::state::{ConsoleState, EnrollmentSession};
use crate::time::{now_epoch_ms, now_iso, parse_iso};

const ENROLL_TTL_MS: i64 = 30 * 60 * 1000;
/// How long an admin-issued invite link stays valid before it must be
/// re-minted. Invites travel out-of-band (email/chat) so they get a much
/// longer window than the in-session enrollment handoff.
const INVITE_TTL_MS: i64 = 72 * 60 * 60 * 1000; // 72 hours
/// Roles an operator is allowed to grant when issuing an invite. Anything
/// outside this set is rejected rather than written verbatim into a user
/// row, so a typo can't mint an unrecognised (and therefore unchecked)
/// privilege string.
const INVITE_ROLES: &[&str] = &["owner", "admin", "editor", "viewer"];

// ─────────────────────────────────────────────────────────────────────────────
// Issue (admin-only invite minting)
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct IssueBody {
    pub email: String,
    pub role: String,
}

#[derive(Debug, Serialize)]
pub struct IssueResponse {
    /// The raw token — returned exactly once. Only its `sha256` is stored,
    /// so this is the operator's single chance to hand it to the invitee.
    pub token: String,
    /// Host-relative setup link the operator can forward; the origin is
    /// supplied by whatever server rendered the console.
    pub link: String,
    pub user_id: String,
    pub email: String,
    pub role: String,
    pub purpose: String,
    pub expires_at: String,
}

/// `POST /auth/magic/issue { email, role }` — an owner or admin mints a
/// single-use invite link for `email`. When no user with that email exists
/// we provision a `pending` row so the invitee flips to `active` the moment
/// they redeem the link and enrol a passkey (`redeem` → `passkey/finish`).
///
/// The caller must be a [`PasskeySession`]. A bearer API token is 403
/// before any user or magic-link row is written (CVE-2026-97406): issuing
/// an invite was how a stolen owner token enrolled an attacker's passkey.
/// `redeem` stays unauthenticated — the link itself is the credential, and
/// the invitee has no session yet.
pub async fn issue(
    State(state): State<ConsoleState>,
    session: PasskeySession,
    ClientIp(ip): ClientIp,
    Json(body): Json<IssueBody>,
) -> ConsoleResult<Response> {
    // Only owners and admins may invite.
    match session.user.role.as_str() {
        "owner" | "admin" => {}
        _ => {
            return Err(ConsoleApiError::Forbidden(
                "only an owner or admin may issue invites".into(),
            ));
        }
    }

    let email = body.email.trim().to_ascii_lowercase();
    if email.is_empty() || !email.contains('@') {
        return Err(ConsoleApiError::BadRequest(
            "a valid email is required".into(),
        ));
    }
    let role = body.role.trim();
    if !INVITE_ROLES.contains(&role) {
        return Err(ConsoleApiError::BadRequest(format!("unknown role: {role}")));
    }
    // Privilege ceiling: only an owner may grant the owner role, so an admin
    // can't quietly mint a peer with more authority than themselves.
    if role == "owner" && session.user.role != "owner" {
        return Err(ConsoleApiError::Forbidden(
            "only an owner may invite another owner".into(),
        ));
    }

    // Provision or look up the invitee. Re-inviting an existing address reuses
    // that row (and its current role) rather than duplicating the user or
    // silently escalating them via the invite.
    let now = now_iso();
    let user = match store::find_user_by_email(&state.engine, &email).await? {
        Some(u) => u,
        None => {
            let u = store::User {
                id: uuid::Uuid::new_v4().to_string(),
                email: email.clone(),
                display_name: String::new(),
                role: role.to_string(),
                status: store::UserStatus::Pending,
                created_at: now.clone(),
                last_seen_at: None,
            };
            store::upsert_user(&state.engine, &u).await?;
            u
        }
    };
    let user_id = user.id;

    // Mint a random 32-byte URL-safe token; persist only its sha256.
    let mut token_bytes = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut token_bytes);
    let token = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(token_bytes);
    let token_hash = sha256_hex(token.as_bytes());

    let now_ms = now_epoch_ms();
    let expires_at = crate::time::epoch_ms_to_iso(now_ms + INVITE_TTL_MS);

    let link = store::MagicLink {
        id: token_hash.clone(),
        purpose: "invite".to_string(),
        user_id: Some(user_id.clone()),
        email: Some(email.clone()),
        role: role.to_string(),
        created_by: session.user.id.clone(),
        created_at: now,
        expires_at: expires_at.clone(),
        used_at: None,
    };
    store::put_magic_link(&state.engine, &link).await?;

    audit::record(
        &state.engine,
        &session.user.id,
        "magic-issued",
        indices::MAGIC_LINKS,
        Some(&token_hash),
        Some(&ip),
        Some(json!({ "purpose": "invite", "invitee": user_id.clone(), "role": role })),
    )
    .await;

    let setup_link = format!("/_xerj-console/setup#token={token}");
    Ok(ok(
        IssueResponse {
            token,
            link: setup_link,
            user_id,
            email,
            role: role.to_string(),
            purpose: "invite".to_string(),
            expires_at,
        },
        None,
    ))
}

// ─────────────────────────────────────────────────────────────────────────────
// Redeem
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct RedeemBody {
    pub token: String,
}

#[derive(Debug, Serialize)]
pub struct RedeemResponse {
    pub enrollment_session_id: String,
    pub email: Option<String>,
    pub role: String,
    pub expires_at: String,
}

pub async fn redeem(
    State(state): State<ConsoleState>,
    ClientIp(ip): ClientIp,
    Json(body): Json<RedeemBody>,
) -> ConsoleResult<Response> {
    // Rate-limit by source IP. `ClientIp` resolves that from the TCP peer,
    // consulting `x-forwarded-for` only when the peer is a configured
    // trusted proxy (#76 S5-4) — this endpoint is unauthenticated, so a
    // header-derived key would let anyone mint a fresh quota per request.
    rate_limit::charge(&state, &ip, "magic-redeem")?;

    if body.token.is_empty() {
        return Err(ConsoleApiError::BadRequest("missing token".into()));
    }
    let token_hash = sha256_hex(body.token.as_bytes());

    // #76 S5-3: serialize the single-use check and the mark-used commit. The
    // used-check (below) and `mark_magic_link_used` (get→delete→create) are
    // separated by several awaits with no exclusive lock, so two concurrent
    // redeems of one token could both pass the check and both mint a session.
    // Hold the gate for the rest of this function so check→consume is atomic.
    // `lock_owned` avoids tying the guard's lifetime to `state` across awaits.
    let _redeem_guard = state.redeem_gate.clone().lock_owned().await;

    // Look it up.
    let link = store::get_magic_link(&state.engine, &token_hash)
        .await?
        .ok_or_else(|| {
            // Single error message regardless of "doesn't exist" vs
            // "expired" vs "used" — never leak which one.
            audit_redeem_failed(&state, "not-found", &ip);
            ConsoleApiError::Unauthorized("invalid or expired link".into())
        })?;

    // Single-use.
    if link.used_at.is_some() {
        audit_redeem_failed(&state, "already-used", &ip);
        return Err(ConsoleApiError::Unauthorized(
            "invalid or expired link".into(),
        ));
    }
    // Expiry.
    if let Some(exp) = parse_iso(&link.expires_at) {
        if now_epoch_ms() > exp.timestamp_millis() {
            audit_redeem_failed(&state, "expired", &ip);
            return Err(ConsoleApiError::Unauthorized(
                "invalid or expired link".into(),
            ));
        }
    }

    // Resolve target user. Bootstrap links have no user_id yet — we
    // synthesise one. Invite links carry the user_id we already
    // provisioned in pending state.
    let (user_id, email) =
        match link.purpose.as_str() {
            "bootstrap" => {
                // Make sure no active user has snuck in between mint and
                // redeem (race window when two operators open the same
                // banner).
                let active = store::count_active_users(&state.engine).await?;
                if active > 0 {
                    audit_redeem_failed(&state, "bootstrap-already-claimed", &ip);
                    return Err(ConsoleApiError::Conflict(
                        "this server has already been claimed; ask your admin for an invite".into(),
                    ));
                }
                // Provision a placeholder user. The SPA fills in the email
                // and display name during the passkey enrollment flow.
                let synthetic_id = uuid::Uuid::new_v4().to_string();
                (synthetic_id, link.email.clone())
            }
            "invite" => {
                let uid = link.user_id.clone().ok_or_else(|| {
                    ConsoleApiError::Internal("invite link without user_id".into())
                })?;
                // Make sure the invitee row still exists (admin may have
                // deleted them between mint and redeem).
                let user = store::get_user(&state.engine, &uid).await?;
                if user.is_none() {
                    audit_redeem_failed(&state, "invitee-gone", &ip);
                    return Err(ConsoleApiError::Unauthorized(
                        "invalid or expired link".into(),
                    ));
                }
                (uid, link.email.clone())
            }
            "recovery" => {
                // Same shape as invite: the account was provisioned when the
                // link was minted. Harden the redemption identically — refuse
                // if the target row vanished between mint and redeem so a
                // leaked recovery link can never resurrect a deleted account
                // (and thereby hand an attacker a fresh enrollment session for
                // a user the admin already removed).
                let uid = link.user_id.clone().ok_or_else(|| {
                    ConsoleApiError::Internal("recovery link without user_id".into())
                })?;
                if store::get_user(&state.engine, &uid).await?.is_none() {
                    audit_redeem_failed(&state, "recovery-user-gone", &ip);
                    return Err(ConsoleApiError::Unauthorized(
                        "invalid or expired link".into(),
                    ));
                }
                (uid, link.email.clone())
            }
            other => {
                return Err(ConsoleApiError::Internal(format!(
                    "unknown magic-link purpose: {other}"
                )));
            }
        };

    // Mark used.
    store::mark_magic_link_used(&state.engine, &token_hash, &now_iso()).await?;

    // Mint enrollment session.
    let mut id_bytes = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut id_bytes);
    let session_id = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(id_bytes);
    let now_ms = now_epoch_ms();
    let expires_ms = now_ms + ENROLL_TTL_MS;

    let enroll = EnrollmentSession {
        session_id: session_id.clone(),
        email: email.clone().unwrap_or_default(),
        user_id: user_id.clone(),
        role: link.role.clone(),
        created_at_ms: now_ms,
        expires_at_ms: expires_ms,
    };
    state.enrollment_sessions.insert(session_id.clone(), enroll);

    audit::record(
        &state.engine,
        "system",
        "magic-redeemed",
        indices::MAGIC_LINKS,
        Some(&token_hash),
        Some(&ip),
        Some(json!({ "purpose": link.purpose, "user_id": user_id })),
    )
    .await;

    Ok(ok(
        RedeemResponse {
            enrollment_session_id: session_id,
            email,
            role: link.role,
            expires_at: crate::time::epoch_ms_to_iso(expires_ms),
        },
        None,
    ))
}

fn audit_redeem_failed(state: &ConsoleState, why: &str, ip: &str) {
    let engine = state.engine.clone();
    let why = why.to_string();
    let ip = ip.to_string();
    tokio::spawn(async move {
        audit::record(
            &engine,
            "system",
            "magic-redeem-failed",
            indices::MAGIC_LINKS,
            None,
            Some(&ip),
            Some(json!({ "reason": why })),
        )
        .await;
    });
}

use base64::Engine as _;

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use tempfile::TempDir;
    use tokio::sync::Barrier;

    use super::*;
    use crate::state::ClusterMode;

    /// Console state with the `.xerj_*` system indices in place. We skip
    /// `bootstrap::run` — redeem only touches magic links, users and audit,
    /// and dashboard seeding would dominate the runtime of a test that races
    /// hundreds of redemptions.
    fn test_state() -> (ConsoleState, TempDir) {
        let dir = TempDir::new().unwrap();
        let mut cfg = xerj_common::config::Config::default();
        cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
        let engine = xerj_engine::Engine::new(cfg).expect("engine");
        indices::ensure_all(&engine).expect("system indices");
        let state = ConsoleState::new(engine, "local".into(), [0u8; 32], ClusterMode::Standalone);
        (state, dir)
    }

    /// Write an invite link for `token` plus the pending invitee row it
    /// points at — the same pair `issue` persists. `ttl_ms` may be negative
    /// to mint an already-expired link.
    async fn mint_invite(state: &ConsoleState, token: &str, ttl_ms: i64) {
        let user_id = format!("invitee-{token}");
        let user = store::User {
            id: user_id.clone(),
            email: format!("{token}@example.com"),
            display_name: String::new(),
            role: "editor".to_string(),
            status: store::UserStatus::Pending,
            created_at: now_iso(),
            last_seen_at: None,
        };
        store::upsert_user(&state.engine, &user).await.unwrap();

        let link = store::MagicLink {
            id: sha256_hex(token.as_bytes()),
            purpose: "invite".to_string(),
            user_id: Some(user_id),
            email: Some(user.email),
            role: "editor".to_string(),
            created_by: "admin-test".to_string(),
            created_at: now_iso(),
            expires_at: crate::time::epoch_ms_to_iso(now_epoch_ms() + ttl_ms),
            used_at: None,
        };
        store::put_magic_link(&state.engine, &link).await.unwrap();
    }

    /// Drive the handler exactly as axum would. Every call declares its own
    /// resolved source IP so the per-IP limiter (10/min) never fires — a 429
    /// would silently stand in for a rejected redemption and hide the
    /// invariant under test. Note this is the *resolved* address (post trust
    /// check), not a header a caller could set: see `client_ip`.
    async fn redeem_as(state: &ConsoleState, token: &str, ip: &str) -> ConsoleResult<Response> {
        redeem(
            State(state.clone()),
            ClientIp(ip.to_string()),
            Json(RedeemBody {
                token: token.to_string(),
            }),
        )
        .await
    }

    async fn used_at_of(state: &ConsoleState, token: &str) -> Option<String> {
        store::get_magic_link(&state.engine, &sha256_hex(token.as_bytes()))
            .await
            .unwrap()
            .expect("link row must survive redemption")
            .used_at
    }

    /// #76 S5-3: the used-check and the `mark_magic_link_used` commit are
    /// separated by several awaits, so without the redeem gate every racer
    /// passes the used-check on one token and they all go on to consume it —
    /// the single-use rule then rests on whatever the store does with the
    /// colliding writes, not on this handler. Race a fresh token per round,
    /// many rounds, and pin both halves of the guarantee: one winner, and
    /// losers rejected as *used* (the generic 401) rather than surfacing a
    /// write collision from underneath.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn racing_redemptions_of_one_token_mint_exactly_one_session() {
        const ROUNDS: usize = 25;
        const RACERS: usize = 6;

        let (state, _dir) = test_state();

        for round in 0..ROUNDS {
            let token = format!("race-token-{round}");
            mint_invite(&state, &token, INVITE_TTL_MS).await;

            let start = Arc::new(Barrier::new(RACERS));
            let mut racers = Vec::with_capacity(RACERS);
            for racer in 0..RACERS {
                let state = state.clone();
                let token = token.clone();
                let start = start.clone();
                racers.push(tokio::spawn(async move {
                    start.wait().await;
                    redeem_as(&state, &token, &format!("10.0.{round}.{racer}")).await
                }));
            }

            let mut winners = 0usize;
            let mut losses = Vec::new();
            for racer in racers {
                match racer.await.expect("redeem must not panic") {
                    Ok(_) => winners += 1,
                    Err(e) => losses.push(e),
                }
            }

            assert_eq!(
                winners, 1,
                "round {round}: exactly one of {RACERS} concurrent redemptions may mint a session"
            );
            for loss in &losses {
                assert!(
                    matches!(loss, ConsoleApiError::Unauthorized(_)),
                    "round {round}: a losing racer must get the generic 401, got {loss}"
                );
            }
            assert_eq!(
                state.enrollment_sessions.len(),
                round + 1,
                "round {round}: one enrollment session per token, never two"
            );
            assert!(
                used_at_of(&state, &token).await.is_some(),
                "round {round}: the winning redemption must leave the link consumed"
            );
        }
    }

    /// The gate serializes redemptions but must not reject them: two invitees
    /// redeeming their own links at the same instant both get a session. This
    /// is also the control for the test above — it proves the racing harness
    /// can produce more than one winner, so `winners == 1` there is the
    /// single-use rule holding, not the harness serializing the calls.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn racing_redemptions_of_distinct_tokens_all_succeed() {
        const RACERS: usize = 6;

        let (state, _dir) = test_state();
        for racer in 0..RACERS {
            mint_invite(&state, &format!("distinct-token-{racer}"), INVITE_TTL_MS).await;
        }

        let start = Arc::new(Barrier::new(RACERS));
        let mut racers = Vec::with_capacity(RACERS);
        for racer in 0..RACERS {
            let state = state.clone();
            let start = start.clone();
            racers.push(tokio::spawn(async move {
                start.wait().await;
                redeem_as(
                    &state,
                    &format!("distinct-token-{racer}"),
                    &format!("10.1.0.{racer}"),
                )
                .await
            }));
        }
        for racer in racers {
            let outcome = racer.await.expect("redeem must not panic");
            assert!(
                outcome.is_ok(),
                "a distinct token must still redeem under contention: {:?}",
                outcome.err()
            );
        }
        assert_eq!(state.enrollment_sessions.len(), RACERS);
    }

    /// An invite past its `expires_at` is refused, and refusing it neither
    /// mints a session nor consumes the link.
    #[tokio::test]
    async fn an_expired_token_is_refused_and_never_mints_a_session() {
        let (state, _dir) = test_state();
        mint_invite(&state, "stale-token", -60_000).await;

        let outcome = redeem_as(&state, "stale-token", "10.2.0.1").await;
        assert!(
            matches!(outcome, Err(ConsoleApiError::Unauthorized(_))),
            "an expired link must be refused with the generic 401"
        );
        assert!(state.enrollment_sessions.is_empty());
        assert!(
            used_at_of(&state, "stale-token").await.is_none(),
            "a refused redemption must not consume the link"
        );
    }

    /// Replay of a consumed token is refused and leaves the original
    /// consumption record intact — a second attempt must not re-stamp
    /// `used_at` and so blur who redeemed the link and when.
    #[tokio::test]
    async fn an_already_redeemed_token_cannot_be_replayed() {
        let (state, _dir) = test_state();
        mint_invite(&state, "replay-token", INVITE_TTL_MS).await;

        redeem_as(&state, "replay-token", "10.3.0.1")
            .await
            .expect("first redemption");
        let consumed_at = used_at_of(&state, "replay-token").await;
        assert!(consumed_at.is_some());

        let outcome = redeem_as(&state, "replay-token", "10.3.0.2").await;
        assert!(
            matches!(outcome, Err(ConsoleApiError::Unauthorized(_))),
            "a redeemed link must be refused with the generic 401"
        );
        assert_eq!(
            state.enrollment_sessions.len(),
            1,
            "the replay must not mint a second enrollment session"
        );
        assert_eq!(
            used_at_of(&state, "replay-token").await,
            consumed_at,
            "the replay must not re-stamp used_at"
        );
    }
}

//! Authentication & identity for Xerj Console.
//!
//! Implements the design from `engine/docs/xerj-console-backend/API_DESIGN_v1.md`
//! §3 — magic-link bootstrap → passkey enrolment → cookie session, with
//! returning-user passkey login. No passwords. Minting an API token, issuing
//! an invitation, deleting a passkey, or logging out requires a
//! [`PasskeySession`]; a bearer API token is 403 on those routes
//! (CVE-2026-97406 / CERT VU#645818).

pub mod audit;
pub mod login;
pub mod magic;
pub mod me;
pub mod passkey;
pub mod rate_limit;
pub mod sessions;
pub mod store;
pub mod tokens;
pub mod webauthn_setup;

pub use sessions::{AuthSession, OptionalAuthSession, PasskeySession};

//! Per-IP rate limiter for auth endpoints.
//!
//! Sliding-minute counter, capped at 10 hits per IP per minute and 100
//! per hour. Implementation is intentionally tiny — DashMap of
//! `(ip, endpoint) -> RateWindow`. Stale entries are pruned on every
//! 50th insert; we don't bother with a background task.
//!
//! On limit exceeded we return 429 with no body — leaking whether the
//! email/token was valid would defeat the purpose of rate limiting.
//!
//! The `ip` this keys on must come from [`crate::ClientIp`] — the TCP peer,
//! consulting `x-forwarded-for` only from a declared trusted proxy. Deriving
//! it from headers is what made the limiter bypassable (#76 S5-4); there is
//! deliberately no header-reading helper in this module to reach for.

use std::sync::atomic::{AtomicU64, Ordering};

use crate::error::{ConsoleApiError, ConsoleResult};
use crate::state::{ConsoleState, RateWindow};
use crate::time::now_epoch_ms;

const PER_MINUTE: u32 = 10;
const PER_HOUR: u32 = 100;
const WINDOW_MIN_MS: i64 = 60_000;
const WINDOW_HOUR_MS: i64 = 3_600_000;

/// Counter of insertions, used to drive periodic pruning so we never
/// pay for a full sweep. (DashMap iter is per-shard locking, so a
/// 1-in-50 prune keeps tail latency unaffected.)
static INSERT_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Charge one hit against the `(ip, endpoint)` bucket. Returns `Ok(())`
/// if under the limits, `Err(RateLimited)` otherwise.
pub fn charge(state: &ConsoleState, ip: &str, endpoint: &str) -> ConsoleResult<()> {
    let now_ms = now_epoch_ms();

    // Per-minute key
    let key_min = format!("{ip}:{endpoint}:m");
    let win = state
        .auth_rate_counters
        .entry(key_min.clone())
        .or_insert(RateWindow {
            count: 0,
            window_start_ms: now_ms,
        });
    let mut win_val = *win;
    drop(win); // release the entry guard so we can reinsert

    if now_ms - win_val.window_start_ms > WINDOW_MIN_MS {
        win_val = RateWindow {
            count: 0,
            window_start_ms: now_ms,
        };
    }
    win_val.count += 1;
    if win_val.count > PER_MINUTE {
        return Err(ConsoleApiError::RateLimited);
    }
    state.auth_rate_counters.insert(key_min, win_val);

    // Per-hour key
    let key_hour = format!("{ip}:{endpoint}:h");
    let win = state
        .auth_rate_counters
        .entry(key_hour.clone())
        .or_insert(RateWindow {
            count: 0,
            window_start_ms: now_ms,
        });
    let mut win_val = *win;
    drop(win);

    if now_ms - win_val.window_start_ms > WINDOW_HOUR_MS {
        win_val = RateWindow {
            count: 0,
            window_start_ms: now_ms,
        };
    }
    win_val.count += 1;
    if win_val.count > PER_HOUR {
        return Err(ConsoleApiError::RateLimited);
    }
    state.auth_rate_counters.insert(key_hour, win_val);

    if INSERT_COUNTER
        .fetch_add(1, Ordering::Relaxed)
        .is_multiple_of(50)
    {
        prune(state, now_ms);
    }
    Ok(())
}

fn prune(state: &ConsoleState, now_ms: i64) {
    state
        .auth_rate_counters
        .retain(|_k, v| now_ms - v.window_start_ms < WINDOW_HOUR_MS);
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::state::ClusterMode;

    fn make_state() -> ConsoleState {
        let dir = tempfile::TempDir::new().unwrap();
        let mut cfg = xerj_common::config::Config::default();
        cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
        let engine = xerj_engine::Engine::new(cfg).unwrap();
        std::mem::forget(dir); // keep the data dir alive until process exit
        ConsoleState::new(engine, "local".into(), [0u8; 32], ClusterMode::Standalone)
    }

    #[tokio::test]
    async fn allows_under_limit() {
        let s = make_state();
        for _ in 0..PER_MINUTE {
            charge(&s, "1.2.3.4", "login").unwrap();
        }
    }

    #[tokio::test]
    async fn blocks_over_minute_limit() {
        let s = make_state();
        for _ in 0..PER_MINUTE {
            charge(&s, "1.2.3.4", "login").unwrap();
        }
        let r = charge(&s, "1.2.3.4", "login");
        assert!(matches!(r, Err(ConsoleApiError::RateLimited)));
    }

    #[tokio::test]
    async fn separate_endpoints_dont_share() {
        let s = make_state();
        for _ in 0..PER_MINUTE {
            charge(&s, "1.2.3.4", "login").unwrap();
        }
        // Different endpoint key — should still be allowed.
        charge(&s, "1.2.3.4", "magic").unwrap();
    }

    #[tokio::test]
    async fn separate_ips_dont_share() {
        let s = make_state();
        for _ in 0..PER_MINUTE {
            charge(&s, "1.2.3.4", "login").unwrap();
        }
        charge(&s, "5.6.7.8", "login").unwrap();
    }
}

//! Cookie-backed sessions.
//!
//! After a successful passkey assertion (enrollment-finish or login-finish)
//! the server mints a session id, persists a `.xerj_sessions` doc, and
//! returns a `Set-Cookie: xerj_session=<id>.<sig>` header. The signature
//! is HMAC-SHA256 of the session id keyed by `ConsoleState.master_key`.
//!
//! Cookie attributes:
//! - `HttpOnly`: blocks JS from reading the cookie (mitigates XSS theft).
//! - `Secure`: not set on http/localhost (so dev works) — set on https
//!   when the request was over TLS.
//! - `SameSite=Lax`: protects against cross-site POST CSRF; `Lax` (not
//!   `Strict`) lets the SPA bookmark links work cross-origin top-nav.
//! - `Path=/_xerj-console`: scoped tightly so xerj's other surfaces never see
//!   the cookie even when proxied alongside.
//!
//! Idle expiry: a session is considered fresh if `now < expires_at AND
//! now < last_seen_at + idle_seconds`. `last_seen_at` is bumped on
//! every authenticated request via the extractor.

use axum::{extract::FromRequestParts, http::request::Parts};
use axum_extra::extract::cookie::{Cookie, CookieJar, SameSite};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
use hmac::{Hmac, Mac};
use rand::RngCore;
use sha2::Sha256;
use subtle::ConstantTimeEq;

use crate::auth::store;
use crate::bootstrap::sha256_hex;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::state::ConsoleState;
use crate::time::{epoch_ms_to_iso, now_epoch_ms, now_iso, parse_iso};
use xerj_engine::Engine;

type HmacSha256 = Hmac<Sha256>;

pub const COOKIE_NAME: &str = "xerj_session";
pub const SESSION_TTL_MS: i64 = 12 * 60 * 60 * 1000; // 12 hours hard expiry
pub const SESSION_IDLE_MS: i64 = 30 * 60 * 1000; //  30 minutes idle

// ─────────────────────────────────────────────────────────────────────────────
// Mint
// ─────────────────────────────────────────────────────────────────────────────

/// Create a fresh session for `user_id`, persist it, and return both the
/// row and the cookie value the SPA should echo back.
pub async fn mint_session(
    state: &ConsoleState,
    user_id: &str,
    idp: &str,
    ip: Option<String>,
    ua: Option<String>,
) -> ConsoleResult<(store::Session, String)> {
    let mut id_bytes = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut id_bytes);
    let session_id = URL_SAFE_NO_PAD.encode(id_bytes);

    let now_ms = now_epoch_ms();
    let now_iso_s = now_iso();
    let session = store::Session {
        id: session_id.clone(),
        user_id: user_id.to_string(),
        created_at: now_iso_s.clone(),
        expires_at: epoch_ms_to_iso(now_ms + SESSION_TTL_MS),
        last_seen_at: now_iso_s,
        ip,
        ua,
        idp: idp.to_string(),
        revoked_at: None,
    };
    store::put_session(&state.engine, &session).await?;

    let signed = sign_session_id(&session_id, &state.master_key);
    Ok((session, signed))
}

/// Sign `session_id` with the master key. Output is `<id>.<sig_b64u>`.
pub fn sign_session_id(session_id: &str, master_key: &[u8; 32]) -> String {
    let mut mac = HmacSha256::new_from_slice(master_key).expect("hmac key");
    mac.update(session_id.as_bytes());
    let sig = URL_SAFE_NO_PAD.encode(mac.finalize().into_bytes());
    format!("{session_id}.{sig}")
}

/// Verify and split a `<id>.<sig>` cookie. Constant-time comparison.
pub fn verify_session_cookie(value: &str, master_key: &[u8; 32]) -> Option<String> {
    let (id, sig) = value.split_once('.')?;
    let expected = sign_session_id(id, master_key);
    let (_id_part, expected_sig) = expected.rsplit_once('.')?;
    if expected_sig.as_bytes().ct_eq(sig.as_bytes()).into() {
        Some(id.to_string())
    } else {
        None
    }
}

/// Build the `Set-Cookie` value for a freshly minted session.
pub fn make_set_cookie(value: String, secure: bool) -> Cookie<'static> {
    let mut c = Cookie::new(COOKIE_NAME.to_string(), value);
    c.set_http_only(true);
    c.set_secure(secure);
    c.set_same_site(SameSite::Lax);
    c.set_path("/_xerj-console");
    c
}

/// Build a `Set-Cookie` that immediately deletes the session cookie.
pub fn make_clear_cookie() -> Cookie<'static> {
    let mut c = Cookie::new(COOKIE_NAME.to_string(), String::new());
    c.set_http_only(true);
    c.set_same_site(SameSite::Lax);
    c.set_path("/_xerj-console");
    c.set_max_age(time::Duration::seconds(0));
    c
}

// ─────────────────────────────────────────────────────────────────────────────
// Extractor
// ─────────────────────────────────────────────────────────────────────────────

/// How this request authenticated.
///
/// A cookie session and an API token both become an [`AuthSession`], so
/// ordinary console reads and writes can accept either. They are not the
/// same credential. [`PasskeySession`] is the passkey-backed browser session
/// a handler must hold before it mints or changes credentials.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SessionOrigin {
    /// `xerj_session` cookie. `idp` is the `.xerj_sessions` row's identity
    /// provider. Only `"passkey"` satisfies [`AuthSession::require_passkey_session`].
    BrowserSession { idp: String },
    /// `Authorization: Bearer <api token>`. `token_id` is `sha256(secret)`.
    ApiToken { token_id: String },
}

/// Stable text of the 403 returned when a credential-minting or
/// identity-changing handler is reached without a passkey-backed browser
/// session. The console tests and `docs/SECURITY_MODEL.md` quote it.
pub const PASSKEY_SESSION_REQUIRED: &str = concat!(
    "this operation requires a passkey-backed browser session; ",
    "API tokens cannot mint or change credentials"
);

/// Authenticated caller, from the `xerj_session` cookie or from
/// `Authorization: Bearer <api token>`.
///
/// Use as a handler parameter to require authentication. Returns 401 on a
/// missing credential, a bad signature, an expired or revoked session, or
/// an unknown or revoked token.
///
/// This type does **not** mean the caller presented a passkey. Credential
/// minting and identity changes take [`PasskeySession`] instead, which
/// returns 403 for a valid bearer token (CVE-2026-97406 / CERT VU#645818).
#[derive(Debug, Clone)]
pub struct AuthSession {
    pub session_id: String,
    pub user: store::User,
    pub origin: SessionOrigin,
}

impl AuthSession {
    /// Refuse unless this request presented a passkey-backed browser session.
    ///
    /// A valid API token is a 403, not a 401: the caller is authenticated
    /// and the operation is forbidden. Cookie sessions and bearer tokens
    /// used to resolve to the same `AuthSession`, so `POST /auth/api-tokens`
    /// would mint a successor that survived revocation of the parent.
    pub fn require_passkey_session(&self) -> ConsoleResult<()> {
        match &self.origin {
            SessionOrigin::BrowserSession { idp } if idp == "passkey" => Ok(()),
            other => Err(ConsoleApiError::Forbidden(refusal_message(other))),
        }
    }
}

fn refusal_message(origin: &SessionOrigin) -> String {
    match origin {
        SessionOrigin::ApiToken { .. } => PASSKEY_SESSION_REQUIRED.to_string(),
        SessionOrigin::BrowserSession { idp } => {
            format!("{PASSKEY_SESSION_REQUIRED} (this session's idp is {idp}, not passkey)")
        }
    }
}

#[axum::async_trait]
impl FromRequestParts<ConsoleState> for AuthSession {
    type Rejection = ConsoleApiError;

    async fn from_request_parts(
        parts: &mut Parts,
        state: &ConsoleState,
    ) -> Result<Self, Self::Rejection> {
        // API clients authenticate with `Authorization: Bearer <token>`;
        // browsers with a signed session cookie. Bearer wins when the header
        // is present, including when the token is invalid: a token-carrying
        // request is never upgraded onto a cookie that happens to be
        // attached. `PasskeySession` then refuses a *valid* bearer with 403.
        // Preferring the cookie whenever both are present would let that
        // request pass the passkey gate (CVE-2026-97406).
        if let Some(token) = bearer_token(&parts.headers) {
            return authenticate_bearer(state, &token).await;
        }

        let jar = CookieJar::from_headers(&parts.headers);
        let cookie = jar
            .get(COOKIE_NAME)
            .ok_or_else(|| ConsoleApiError::Unauthorized("no session".into()))?;
        let session_id = verify_session_cookie(cookie.value(), &state.master_key)
            .ok_or_else(|| ConsoleApiError::Unauthorized("bad session signature".into()))?;

        let session = store::get_session(&state.engine, &session_id)
            .await?
            .ok_or_else(|| ConsoleApiError::Unauthorized("unknown session".into()))?;

        if session.revoked_at.is_some() {
            return Err(ConsoleApiError::Unauthorized("session revoked".into()));
        }
        let now_ms = now_epoch_ms();
        if let Some(exp) = parse_iso(&session.expires_at) {
            if now_ms > exp.timestamp_millis() {
                return Err(ConsoleApiError::Unauthorized("session expired".into()));
            }
        }
        if let Some(seen) = parse_iso(&session.last_seen_at) {
            if now_ms - seen.timestamp_millis() > SESSION_IDLE_MS {
                return Err(ConsoleApiError::Unauthorized("session idle".into()));
            }
        }

        let user = store::get_user(&state.engine, &session.user_id)
            .await?
            .ok_or_else(|| ConsoleApiError::Unauthorized("session user gone".into()))?;
        if user.status != store::UserStatus::Active {
            return Err(ConsoleApiError::Unauthorized("user disabled".into()));
        }

        // Bump last_seen so the session stays fresh while the user is active.
        // Best-effort — we don't fail the request if the write races with another
        // tab. SECURITY (S5-1): do NOT blind-write the session we read at the top
        // of this function. A concurrent revoke_session() between that read and
        // this write would be clobbered by the stale copy (revoked_at: None),
        // resurrecting a revoked session — a revocation bypass. Re-read and bump
        // only the fresh record, skipping entirely if it is now revoked or gone.
        bump_last_seen(&state.engine, &session_id).await;

        Ok(AuthSession {
            session_id,
            user,
            origin: SessionOrigin::BrowserSession { idp: session.idp },
        })
    }
}

/// Passkey-backed browser session.
///
/// Extract this instead of [`AuthSession`] for any handler that mints a
/// credential or changes identity. A missing credential is 401. A valid
/// `Authorization: Bearer` API token, and a browser session whose `idp` is
/// not `"passkey"`, are 403 with [`PASSKEY_SESSION_REQUIRED`]. The check
/// runs in the extractor, before the handler, so a refusal writes nothing.
///
/// # Handler classification
///
/// **Requires this type** (credential minting or identity change):
/// - `POST /auth/api-tokens` — mint an API token (`tokens::create`)
/// - `DELETE /auth/api-tokens/:id` — revoke an API token (`tokens::revoke`)
/// - `POST /auth/magic/issue` — mint an invitation (`magic::issue`)
/// - `DELETE /auth/passkeys/:id` — delete a passkey (`me::delete_passkey`)
/// - `POST /auth/logout` — revoke the current browser session (`login::logout`)
///
/// **[`AuthSession`] is enough** (ordinary console data; bearer tokens work):
/// - `GET /me`, `GET /auth/passkeys`, `GET /auth/api-tokens` (metadata only)
/// - `GET`/`PUT /prefs`
/// - dashboard and saved-view CRUD, including `_bulk`
/// - data-source connection, index, field, and search routes
/// - `GET /knowledge` and the `/graph/*` reads
///
/// **Not an [`AuthSession`] route.** These authorize with a different
/// credential, and a bearer token does not unlock them:
/// - `POST /auth/magic/redeem` — the magic link is the credential. The
///   invitee has no session yet; requiring one would break bootstrap.
///   A stolen API token cannot issue the link once `magic/issue` is gated.
/// - `POST /auth/passkey/begin` and `/finish` — the in-memory enrollment
///   session from redeem. There is no "enroll a passkey while holding an
///   API token" path.
/// - `POST /auth/login/begin` and `/finish` — WebAuthn, unauthenticated.
///
/// **No handler exists** for user/role management (`/users`) or for
/// revoking a session other than the current cookie via `logout`. A future
/// SSO cookie (`idp` other than `"passkey"`) fails this extractor, so it
/// cannot mint credentials either.
///
/// No API-token row records a parent. `tokens::create` is the only insert
/// of a new token, and it takes this type, so a bearer token cannot mint a
/// descendant for revocation to miss.
#[derive(Debug, Clone)]
pub struct PasskeySession {
    pub session_id: String,
    pub user: store::User,
}

#[axum::async_trait]
impl FromRequestParts<ConsoleState> for PasskeySession {
    type Rejection = ConsoleApiError;

    async fn from_request_parts(
        parts: &mut Parts,
        state: &ConsoleState,
    ) -> Result<Self, Self::Rejection> {
        let sess = AuthSession::from_request_parts(parts, state).await?;
        sess.require_passkey_session()?;
        Ok(PasskeySession {
            session_id: sess.session_id,
            user: sess.user,
        })
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Bearer (API token) authentication
// ─────────────────────────────────────────────────────────────────────────────

/// Refresh a session's `last_seen_at` without clobbering a concurrent revocation.
///
/// S5-1 fix: re-reads the session immediately before writing and skips the write
/// if it is now gone or revoked, so a `revoke_session()` that landed after the
/// request's initial auth read cannot be overwritten by a stale copy. The write
/// carries the *fresh* record's fields (including its `revoked_at`), so even the
/// tiny residual window between this re-read and the put cannot resurrect a
/// revoked session — it would only rewrite an already-revoked record unchanged.
/// Best-effort: any store error is swallowed, exactly as before.
pub(crate) async fn bump_last_seen(engine: &Engine, session_id: &str) {
    let fresh = match store::get_session(engine, session_id).await {
        Ok(Some(s)) => s,
        _ => return, // gone (revoked-by-delete or expired-out) → do not recreate
    };
    if fresh.revoked_at.is_some() {
        return; // revoked between auth read and now → must not refresh
    }
    let mut bumped = fresh;
    bumped.last_seen_at = now_iso();
    let _ = store::put_session(engine, &bumped).await;
}

/// Pull the secret out of an `Authorization: Bearer <secret>` header.
/// Returns `None` when the header is absent, is not a bearer scheme, or
/// carries an empty value — the caller then falls back to the cookie path.
fn bearer_token(headers: &axum::http::HeaderMap) -> Option<String> {
    let raw = headers
        .get(axum::http::header::AUTHORIZATION)?
        .to_str()
        .ok()?;
    let rest = raw
        .strip_prefix("Bearer ")
        .or_else(|| raw.strip_prefix("bearer "))?;
    let trimmed = rest.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

/// Authenticate a presented API token: hash it, look up a non-revoked
/// `ApiToken` row (see `auth::tokens`), and resolve its owner. Failure
/// semantics mirror the cookie path — every mismatch is a flat 401 that
/// never reveals which check failed.
async fn authenticate_bearer(
    state: &ConsoleState,
    presented: &str,
) -> Result<AuthSession, ConsoleApiError> {
    let hash = sha256_hex(presented.as_bytes());
    let token = store::get_api_token(&state.engine, &hash)
        .await?
        .ok_or_else(|| ConsoleApiError::Unauthorized("invalid api token".into()))?;
    if token.revoked_at.is_some() {
        return Err(ConsoleApiError::Unauthorized("api token revoked".into()));
    }
    let user = store::get_user(&state.engine, &token.user_id)
        .await?
        .ok_or_else(|| ConsoleApiError::Unauthorized("api token user gone".into()))?;
    if user.status != store::UserStatus::Active {
        return Err(ConsoleApiError::Unauthorized("user disabled".into()));
    }
    // `session_id` is the token id (= hash), not a `.xerj_sessions` id.
    // `PasskeySession` refuses this origin before a credential handler runs,
    // so logout cannot treat the hash as a browser session to revoke.
    let token_id = token.id.clone();
    Ok(AuthSession {
        session_id: token_id.clone(),
        user,
        origin: SessionOrigin::ApiToken { token_id },
    })
}

/// Allow `Option<AuthSession>` extractors for endpoints that work
/// signed-in *or* signed-out (e.g. `/me` returns 401 explicitly rather
/// than relying on the rejection so the SPA can branch on it).
#[axum::async_trait]
impl FromRequestParts<ConsoleState> for OptionalAuthSession {
    type Rejection = std::convert::Infallible;

    async fn from_request_parts(
        parts: &mut Parts,
        state: &ConsoleState,
    ) -> Result<Self, Self::Rejection> {
        match AuthSession::from_request_parts(parts, state).await {
            Ok(s) => Ok(OptionalAuthSession(Some(s))),
            Err(_) => Ok(OptionalAuthSession(None)),
        }
    }
}

#[derive(Debug, Clone)]
pub struct OptionalAuthSession(pub Option<AuthSession>);

/// Convert an extractor rejection into a JSON 401 (matches the rest of
/// the surface).
impl From<ConsoleApiError> for axum::response::Response {
    fn from(e: ConsoleApiError) -> Self {
        use axum::response::IntoResponse;
        e.into_response()
    }
}

/// Helper for handlers that need to know if the request hit us over
/// HTTPS. We don't have direct TLS info inside axum (that's at the
/// listener layer), so we approximate by checking the `forwarded` /
/// `x-forwarded-proto` headers a reverse proxy sets, defaulting to
/// false (= http) so the local dev cookie still works.
pub fn request_is_secure(parts: &Parts) -> bool {
    if let Some(v) = parts.headers.get("x-forwarded-proto") {
        if v.as_bytes().eq_ignore_ascii_case(b"https") {
            return true;
        }
    }
    if let Some(v) = parts.headers.get("forwarded") {
        if let Ok(s) = v.to_str() {
            for part in s.split(';') {
                if part.trim().to_ascii_lowercase().starts_with("proto=https") {
                    return true;
                }
            }
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cookie_round_trip() {
        let key = [7u8; 32];
        let signed = sign_session_id("abc123", &key);
        let id = verify_session_cookie(&signed, &key).unwrap();
        assert_eq!(id, "abc123");
    }

    #[test]
    fn cookie_rejects_tampered_sig() {
        let key = [7u8; 32];
        let signed = sign_session_id("abc123", &key);
        let mut chars: Vec<char> = signed.chars().collect();
        // flip one byte in the signature half
        let sig_start = signed.find('.').unwrap() + 1;
        chars[sig_start] = if chars[sig_start] == 'a' { 'b' } else { 'a' };
        let tampered: String = chars.into_iter().collect();
        assert!(verify_session_cookie(&tampered, &key).is_none());
    }

    #[test]
    fn cookie_rejects_wrong_key() {
        let signed = sign_session_id("abc123", &[7u8; 32]);
        assert!(verify_session_cookie(&signed, &[8u8; 32]).is_none());
    }

    async fn test_engine() -> (Engine, tempfile::TempDir) {
        let dir = tempfile::TempDir::new().unwrap();
        let mut cfg = xerj_common::config::Config::default();
        cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
        let engine = Engine::new(cfg).expect("engine");
        crate::bootstrap::run(&engine, dir.path(), "http://localhost:9200")
            .await
            .expect("bootstrap");
        (engine, dir)
    }

    fn session(id: &str, revoked: bool) -> store::Session {
        store::Session {
            id: id.to_string(),
            user_id: "u1".into(),
            created_at: now_iso(),
            expires_at: crate::time::epoch_ms_to_iso(now_epoch_ms() + 3_600_000),
            last_seen_at: crate::time::epoch_ms_to_iso(now_epoch_ms() - 600_000),
            ip: None,
            ua: None,
            idp: "passkey".into(),
            revoked_at: if revoked { Some(now_iso()) } else { None },
        }
    }

    /// S5-1: bump_last_seen must NOT resurrect a session that was revoked before
    /// the bump. Pre-fix, the extractor blind-wrote a stale (revoked_at: None)
    /// copy, un-revoking it — a revocation bypass.
    #[tokio::test]
    async fn bump_does_not_resurrect_a_revoked_session() {
        let (engine, _dir) = test_engine().await;
        // A session that is live, then revoked (the realistic race outcome:
        // revoke lands before the in-flight request's bump).
        store::put_session(&engine, &session("s-revoked", false))
            .await
            .unwrap();
        store::revoke_session(&engine, "s-revoked", &now_iso())
            .await
            .unwrap();

        bump_last_seen(&engine, "s-revoked").await;

        let after = store::get_session(&engine, "s-revoked").await.unwrap();
        assert!(
            after.is_some() && after.unwrap().revoked_at.is_some(),
            "bump must not clear revoked_at"
        );
    }

    /// A live session's bump still refreshes last_seen (the feature still works).
    #[tokio::test]
    async fn bump_refreshes_a_live_session() {
        let (engine, _dir) = test_engine().await;
        let mut s = session("s-live", false);
        s.last_seen_at = crate::time::epoch_ms_to_iso(now_epoch_ms() - 600_000);
        let before = s.last_seen_at.clone();
        store::put_session(&engine, &s).await.unwrap();

        bump_last_seen(&engine, "s-live").await;

        let after = store::get_session(&engine, "s-live")
            .await
            .unwrap()
            .unwrap();
        assert!(after.revoked_at.is_none());
        assert_ne!(after.last_seen_at, before, "last_seen should advance");
    }

    fn user() -> store::User {
        store::User {
            id: "u".into(),
            email: "u@example.com".into(),
            display_name: String::new(),
            role: "owner".into(),
            status: store::UserStatus::Active,
            created_at: "2026-01-01T00:00:00.000Z".into(),
            last_seen_at: None,
        }
    }

    fn session_with(origin: SessionOrigin) -> AuthSession {
        AuthSession {
            session_id: "s".into(),
            user: user(),
            origin,
        }
    }

    #[test]
    fn a_passkey_browser_session_may_mint_credentials() {
        let sess = session_with(SessionOrigin::BrowserSession {
            idp: "passkey".into(),
        });
        assert!(sess.require_passkey_session().is_ok());
    }

    #[test]
    fn an_api_token_cannot_mint_credentials() {
        let sess = session_with(SessionOrigin::ApiToken {
            token_id: "hash".into(),
        });
        let err = sess.require_passkey_session().unwrap_err();
        assert!(matches!(err, ConsoleApiError::Forbidden(_)));
        assert!(
            err.to_string().contains(PASSKEY_SESSION_REQUIRED),
            "403 text must name the passkey-session rule, got {err}"
        );
    }

    #[test]
    fn a_non_passkey_browser_session_cannot_mint_credentials() {
        let sess = session_with(SessionOrigin::BrowserSession { idp: "oidc".into() });
        let err = sess.require_passkey_session().unwrap_err();
        assert!(matches!(err, ConsoleApiError::Forbidden(_)));
        let text = err.to_string();
        assert!(text.contains(PASSKEY_SESSION_REQUIRED), "{text}");
        assert!(text.contains("oidc"), "{text}");
    }
}

//! Persistence helpers for the auth subsystem.
//!
//! The Xerj Console auth surface keeps every persistent fact (users, passkeys,
//! magic links, sessions, API tokens) in `.xerj_*` system indices.
//! This module is the **only** place that talks to the engine for those
//! reads and writes — the handler modules call typed helpers here so
//! schema and shape decisions are localised.
//!
//! Document conventions:
//! - All timestamp fields are ISO-8601 RFC 3339 millis with trailing `Z`.
//! - Every doc has `_id` chosen by the caller (we never let the engine
//!   auto-assign), so reads are by-id and idempotent.

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use xerj_engine::Engine;

use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;

/// Single in-place upsert (one WAL append). delete-then-create used to
/// drop the live row when the replacement write was refused (write
/// block, unparseable date, crash between the two ops).
async fn replace_document(idx: &xerj_engine::Index, id: String, doc: Value) -> ConsoleResult<()> {
    idx.index_document(Some(id), doc).await?;
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// User
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct User {
    pub id: String,
    pub email: String,
    #[serde(default)]
    pub display_name: String,
    pub role: String,
    pub status: UserStatus,
    pub created_at: String,
    #[serde(default)]
    pub last_seen_at: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum UserStatus {
    Pending,
    Active,
    Disabled,
}

impl UserStatus {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Pending => "pending",
            Self::Active => "active",
            Self::Disabled => "disabled",
        }
    }
}

pub async fn get_user(engine: &Engine, user_id: &str) -> ConsoleResult<Option<User>> {
    let idx = engine.get_index(indices::USERS)?;
    let body = json!({
        "query": { "ids": { "values": [user_id] } },
        "size": 1
    });
    search_one(&idx, &body).await
}

pub async fn find_user_by_email(engine: &Engine, email: &str) -> ConsoleResult<Option<User>> {
    let idx = engine.get_index(indices::USERS)?;
    let body = json!({
        "query": { "term": { "email": email } },
        "size": 1
    });
    search_one(&idx, &body).await
}

pub async fn upsert_user(engine: &Engine, user: &User) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::USERS)?;
    let doc = serde_json::to_value(user)?;
    replace_document(&idx, user.id.clone(), doc).await
}

pub async fn count_active_users(engine: &Engine) -> ConsoleResult<u64> {
    let idx = engine.get_index(indices::USERS)?;
    let body = json!({
        "query": { "term": { "status": "active" } },
        "size": 0,
        "track_total_hits": true
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    Ok(r.total.value)
}

// ─────────────────────────────────────────────────────────────────────────────
// Magic links
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MagicLink {
    pub id: String, // = sha256(token) hex
    pub purpose: String,
    pub user_id: Option<String>,
    pub email: Option<String>,
    pub role: String,
    pub created_by: String,
    pub created_at: String,
    pub expires_at: String,
    pub used_at: Option<String>,
}

pub async fn get_magic_link(engine: &Engine, token_hash: &str) -> ConsoleResult<Option<MagicLink>> {
    let idx = engine.get_index(indices::MAGIC_LINKS)?;
    let body = json!({
        "query": { "ids": { "values": [token_hash] } },
        "size": 1
    });
    let mut hit: Option<Value> = search_one_raw(&idx, &body).await?;
    Ok(match hit.take() {
        None => None,
        Some(mut v) => {
            // _id round-trip: the engine returns the doc inside `_source`;
            // we don't always have it inside the body so attach the id
            // back from the search hit metadata if needed.
            if v.get("id").is_none() {
                v["id"] = Value::String(token_hash.to_string());
            }
            Some(serde_json::from_value(v)?)
        }
    })
}

pub async fn mark_magic_link_used(
    engine: &Engine,
    token_hash: &str,
    used_at_iso: &str,
) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::MAGIC_LINKS)?;
    let existing = get_magic_link(engine, token_hash).await?;
    let mut link = existing
        .ok_or_else(|| ConsoleApiError::NotFound("magic link not found at consume time".into()))?;
    link.used_at = Some(used_at_iso.to_string());
    let doc = serde_json::to_value(&link)?;
    replace_document(&idx, token_hash.to_string(), doc).await
}

pub async fn put_magic_link(engine: &Engine, link: &MagicLink) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::MAGIC_LINKS)?;
    let doc = serde_json::to_value(link)?;
    replace_document(&idx, link.id.clone(), doc).await
}

