// Passkeys
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StoredPasskey {
    pub id: String, // credential_id (base64url)
    pub user_id: String,
    pub name: String,
    pub created_at: String,
    pub last_used_at: Option<String>,
    /// The full webauthn-rs `Passkey` blob, serialised to JSON. We need
    /// the entire object back at login-time to verify assertions.
    /// (`danger-allow-state-serialisation` feature is enabled in Cargo.toml.)
    pub blob: Value,
}

pub async fn list_passkeys_for_user(
    engine: &Engine,
    user_id: &str,
) -> ConsoleResult<Vec<StoredPasskey>> {
    let idx = engine.get_index(indices::PASSKEYS)?;
    let body = json!({
        "query": { "term": { "user_id": user_id } },
        "size": 100
    });
    search_all(&idx, &body).await
}

pub async fn put_passkey(engine: &Engine, pk: &StoredPasskey) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::PASSKEYS)?;
    let doc = serde_json::to_value(pk)?;
    replace_document(&idx, pk.id.clone(), doc).await
}

pub async fn count_passkeys_for_user(engine: &Engine, user_id: &str) -> ConsoleResult<u64> {
    let idx = engine.get_index(indices::PASSKEYS)?;
    let body = json!({
        "query": { "term": { "user_id": user_id } },
        "size": 0,
        "track_total_hits": true
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    Ok(r.total.value)
}

pub async fn delete_passkey(engine: &Engine, credential_id: &str) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::PASSKEYS)?;
    // Issue #204: this was `let _ = ..`, so a delete refused by the engine
    // (index write block, disk flood stage, storage error) still produced
    // `204 No Content` — the console said the passkey was revoked while it
    // remained on disk and kept authenticating. `delete_document` returns
    // `Ok(false)` for an already-absent credential, so propagating cannot turn
    // a repeat revoke into an error; only a genuine failure surfaces.
    idx.delete_document(credential_id).await?;
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// Sessions
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Session {
    pub id: String,
    pub user_id: String,
    pub created_at: String,
    pub expires_at: String,
    pub last_seen_at: String,
    pub ip: Option<String>,
    pub ua: Option<String>,
    pub idp: String, // "passkey" | "oidc" | "saml"
    pub revoked_at: Option<String>,
}

pub async fn put_session(engine: &Engine, sess: &Session) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::SESSIONS)?;
    let doc = serde_json::to_value(sess)?;
    replace_document(&idx, sess.id.clone(), doc).await
}

pub async fn get_session(engine: &Engine, session_id: &str) -> ConsoleResult<Option<Session>> {
    let idx = engine.get_index(indices::SESSIONS)?;
    let body = json!({
        "query": { "ids": { "values": [session_id] } },
        "size": 1
    });
    search_one(&idx, &body).await
}

pub async fn revoke_session(
    engine: &Engine,
    session_id: &str,
    revoked_at_iso: &str,
) -> ConsoleResult<()> {
    let mut sess = match get_session(engine, session_id).await? {
        Some(s) => s,
        None => return Ok(()), // already gone — idempotent
    };
    sess.revoked_at = Some(revoked_at_iso.to_string());
    put_session(engine, &sess).await
}

// ─────────────────────────────────────────────────────────────────────────────
// API tokens
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApiToken {
    pub id: String, // sha256(secret) hex
    pub user_id: String,
    pub name: String,
    pub scopes: Vec<String>,
    pub created_at: String,
    pub last_used_at: Option<String>,
    pub revoked_at: Option<String>,
}

/// Persist an API token row.
///
/// A new secret is inserted only from `tokens::create`, which takes a
/// `PasskeySession` and returns 403 for a bearer token before this runs
/// (CVE-2026-97406). `tokens::revoke` and [`revoke_api_tokens_for_user`]
/// call it to stamp `revoked_at` on a row that already exists.
pub async fn put_api_token(engine: &Engine, token: &ApiToken) -> ConsoleResult<()> {
    let idx = engine.get_index(indices::API_TOKENS)?;
    let doc = serde_json::to_value(token)?;
    replace_document(&idx, token.id.clone(), doc).await
}

pub async fn get_api_token(engine: &Engine, token_hash: &str) -> ConsoleResult<Option<ApiToken>> {
    let idx = engine.get_index(indices::API_TOKENS)?;
    let body = json!({
        "query": { "ids": { "values": [token_hash] } },
        "size": 1
    });
    search_one(&idx, &body).await
}

pub async fn list_api_tokens_for_user(
    engine: &Engine,
    user_id: &str,
) -> ConsoleResult<Vec<ApiToken>> {
    let idx = engine.get_index(indices::API_TOKENS)?;
    let body = json!({
        "query": { "term": { "user_id": user_id } },
        "size": 100
    });
    search_all(&idx, &body).await
}

pub async fn revoke_api_tokens_for_user(
    engine: &Engine,
    user_id: &str,
    revoked_at_iso: &str,
) -> ConsoleResult<()> {
    let tokens = list_api_tokens_for_user(engine, user_id).await?;
    for mut t in tokens {
        if t.revoked_at.is_some() {
            continue;
        }
        t.revoked_at = Some(revoked_at_iso.to_string());
        put_api_token(engine, &t).await?;
    }
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// Search helpers
// ─────────────────────────────────────────────────────────────────────────────

async fn search_one<T: serde::de::DeserializeOwned>(
    idx: &std::sync::Arc<xerj_engine::Index>,
    body: &Value,
) -> ConsoleResult<Option<T>> {
    Ok(match search_one_raw(idx, body).await? {
        None => None,
        Some(v) => Some(serde_json::from_value(v)?),
    })
}

async fn search_one_raw(
    idx: &std::sync::Arc<xerj_engine::Index>,
    body: &Value,
) -> ConsoleResult<Option<Value>> {
    let req = xerj_query::parser::parse_request(body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let result = idx.search(&req).await?;
    let hit = result.hits.into_iter().next();
    Ok(hit.map(|h| h.source))
}

async fn search_all<T: serde::de::DeserializeOwned>(
    idx: &std::sync::Arc<xerj_engine::Index>,
    body: &Value,
) -> ConsoleResult<Vec<T>> {
    let req = xerj_query::parser::parse_request(body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let result = idx.search(&req).await?;
    let mut out = Vec::with_capacity(result.hits.len());
    for h in result.hits {
        out.push(serde_json::from_value(h.source)?);
    }
    Ok(out)
}

//! WebAuthn relying-party setup.
//!
//! Builds a `Webauthn` instance from `ConsoleState.rp` (rp_id, rp_origin,
//! rp_name). Cheap enough to call per-request — `Webauthn::new` just
//! stores config; no I/O.

use webauthn_rs::prelude::*;

use crate::error::{ConsoleApiError, ConsoleResult};
use crate::state::ConsoleState;

pub fn build(state: &ConsoleState) -> ConsoleResult<Webauthn> {
    let origin = Url::parse(&state.rp.rp_origin)
        .map_err(|e| ConsoleApiError::Internal(format!("rp_origin parse: {e}")))?;
    let builder = WebauthnBuilder::new(&state.rp.rp_id, &origin)
        .map_err(|e| ConsoleApiError::Internal(format!("webauthn build: {e}")))?
        .rp_name(&state.rp.rp_name);
    // A loopback deployment may be reached on a port other than the one the
    // origin was derived from (a container port map, or a passkey enrolled
    // when the node listened elsewhere). `webauthn-rs` still requires the
    // scheme and host to match — only the port check is relaxed, and only
    // for `localhost` (#935). Named-host deployments keep strict matching.
    let builder = if state.rp.rp_id == "localhost" {
        builder.allow_any_port(true)
    } else {
        builder
    };
    builder
        .build()
        .map_err(|e| ConsoleApiError::Internal(format!("webauthn finalise: {e}")))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::state::{ClusterMode, RpConfig};
    use tempfile::TempDir;
    use xerj_common::config::Config;
    use xerj_engine::Engine;

    fn state_with_rp(rp: RpConfig) -> (ConsoleState, TempDir) {
        let dir = TempDir::new().unwrap();
        let mut cfg = Config::default();
        cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
        let engine = Engine::new(cfg).expect("engine");
        let state = ConsoleState::new_with_rp(
            engine,
            "local".into(),
            [0u8; 32],
            ClusterMode::Standalone,
            rp,
        );
        (state, dir)
    }

    #[tokio::test]
    async fn a_derived_loopback_rp_builds_on_any_port() {
        // #935: the RP used to be hard-coded to http://localhost:9200, so a
        // node on any other port had no constructible relying party for the
        // origin its browser actually used.
        let rp = RpConfig::from_bind_url("http://127.0.0.1:9550").unwrap();
        assert_eq!(rp.rp_origin, "http://localhost:9550");
        let (state, _dir) = state_with_rp(rp);
        assert!(build(&state).is_ok());
    }

    #[tokio::test]
    async fn an_ip_literal_origin_cannot_build_an_rp() {
        // Why `from_bind_url` rewrites the host instead of using the bind URL
        // verbatim: `WebauthnBuilder` requires the rp_id to be an effective
        // domain of the origin, and an IP-literal origin has no domain.
        let rp = RpConfig {
            rp_id: "localhost".into(),
            rp_origin: "http://127.0.0.1:9550".into(),
            rp_name: "Xerj Console".into(),
        };
        let (state, _dir) = state_with_rp(rp);
        assert!(build(&state).is_err());
    }

    #[tokio::test]
    async fn a_named_host_rp_builds() {
        let rp = RpConfig::from_bind_url("http://console.example.com:9200").unwrap();
        let (state, _dir) = state_with_rp(rp);
        assert!(build(&state).is_ok());
    }
}

//! First-launch bootstrap.
//!
//! Two responsibilities:
//!
//! 1. **Master key.** Load (or generate-then-persist) a 32-byte secret used
//!    to HMAC session cookies, magic-link tokens, and connection-secret
//!    AEAD keys. Stored at `<data_dir>/.xerj_master_key` mode 0600, or
//!    overridden by the `XERJ_CONSOLE_KEY` env var (32 hex bytes).
//!
//! 2. **Bootstrap mode.** If `.xerj_users` has zero documents with
//!    `status = "active"`, mint a single-use 30-minute magic link with
//!    `purpose = "bootstrap"` and `role = "owner"`, store its sha256 in
//!    `.xerj_magic_links`, and print a bordered banner to stderr with
//!    the redeem URL the operator should open.
//!
//! Idempotent: if an active user already exists, this function is a no-op
//! beyond loading the master key.

use std::path::Path;

use rand::RngCore;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use xerj_engine::Engine;

use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::time::{now_epoch_ms, now_iso};

/// Result of the bootstrap routine, returned to the server's main()
/// so it can fold the master key into `ConsoleState` and decide what to
/// print on stdout.
pub struct BootstrapOutcome {
    pub master_key: [u8; 32],
    /// `Some(url)` if a fresh bootstrap link was minted. The caller is
    /// responsible for printing this — `bootstrap_if_needed` does its
    /// own stderr banner already, but tests want the URL programmatically.
    pub magic_link: Option<String>,
}

/// Run the full first-launch routine. Idempotent on subsequent boots.
///
/// `bind_url` is the URL the operator should browse to (e.g.
/// `http://localhost:9200`). The full link the SPA receives is
/// `{bind_url}/_xerj-console/setup#token=…`.
pub async fn run(
    engine: &Engine,
    data_dir: &Path,
    bind_url: &str,
) -> ConsoleResult<BootstrapOutcome> {
    // Console bootstrap is a storage migration: it creates fourteen system
    // indices, writes a master key and publishes seeded dashboard segments.
    // Keep this guard inside the crate as well as at the server call site so a
    // future embedder cannot accidentally bypass the compatibility fence.
    if !engine.cluster_state_boot_status().is_writable() {
        return Err(ConsoleApiError::Internal(
            "cluster-state storage is unavailable; Console bootstrap requires a supported restart"
                .to_owned(),
        ));
    }
    let master_key = load_or_init_master_key(data_dir)?;

    indices::ensure_all(engine)?;

    // Materialise the built-in dashboards as editable backend data. Idempotent
    // and safe on every boot: creates any missing default, never clobbers an
    // operator's edits, and only re-syncs untouched defaults when the shipped
    // seed revision is bumped. See `crate::seed`.
    crate::seed::seed_default_dashboards(engine).await?;

    let magic_link = if has_any_active_user(engine).await? {
        None
    } else {
        let url = mint_bootstrap_link(engine, bind_url).await?;
        print_bootstrap_banner(&url);
        Some(url)
    };

    Ok(BootstrapOutcome {
        master_key,
        magic_link,
    })
}

// ─────────────────────────────────────────────────────────────────────────────
// Master key
// ─────────────────────────────────────────────────────────────────────────────

const MASTER_KEY_FILENAME: &str = ".xerj_master_key";
const MASTER_KEY_ENV: &str = "XERJ_CONSOLE_KEY";

fn load_or_init_master_key(data_dir: &Path) -> ConsoleResult<[u8; 32]> {
    // Env var wins — covers Kubernetes secret mounts.
    if let Ok(hex) = std::env::var(MASTER_KEY_ENV) {
        let bytes = hex_decode(hex.trim()).ok_or_else(|| {
            ConsoleApiError::Internal(format!("{MASTER_KEY_ENV}: not 64 hex chars"))
        })?;
        if bytes.len() != 32 {
            return Err(ConsoleApiError::Internal(format!(
                "{MASTER_KEY_ENV}: expected 32 bytes (64 hex), got {}",
                bytes.len()
            )));
        }
        let mut out = [0u8; 32];
        out.copy_from_slice(&bytes);
        return Ok(out);
    }

    let path = data_dir.join(MASTER_KEY_FILENAME);
    if path.exists() {
        let raw = std::fs::read_to_string(&path)?;
        let trimmed = raw.trim();
        let bytes = hex_decode(trimmed).ok_or_else(|| {
            ConsoleApiError::Internal(format!(
                "{}: not valid hex (corrupt? regenerate by deleting and restarting)",
                path.display()
            ))
        })?;
        if bytes.len() != 32 {
            return Err(ConsoleApiError::Internal(format!(
                "{}: expected 32 bytes (64 hex), got {}",
                path.display(),
                bytes.len()
            )));
        }
        let mut out = [0u8; 32];
        out.copy_from_slice(&bytes);
        return Ok(out);
    }

    // First boot: generate, persist with mode 0600.
    let mut key = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut key);
    let hex = hex_encode(&key);
    std::fs::write(&path, &hex)?;
    set_owner_readable_only(&path)?;
    tracing::info!(path = %path.display(), "generated xerj-console master key");
    Ok(key)
}

#[cfg(unix)]
fn set_owner_readable_only(p: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let mut perm = std::fs::metadata(p)?.permissions();
    perm.set_mode(0o600);
    std::fs::set_permissions(p, perm)
}

#[cfg(not(unix))]
fn set_owner_readable_only(_p: &Path) -> std::io::Result<()> {
    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// "Any active user?" predicate
// ─────────────────────────────────────────────────────────────────────────────

async fn has_any_active_user(engine: &Engine) -> ConsoleResult<bool> {
    let idx = engine
        .get_index(indices::USERS)
        .map_err(|e| ConsoleApiError::Internal(format!("open {}: {e}", indices::USERS)))?;

    // Build a `term: { status: "active" }` search with size: 1. Cheap on
    // a tiny system index — we only care whether any doc matches.
    let body = json!({
        "query": { "term": { "status": "active" } },
        "size": 1,
        "track_total_hits": true
    });

    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(format!("parse bootstrap probe: {e}")))?;

    let result = idx
        .search(&req)
        .await
        .map_err(|e| ConsoleApiError::Internal(format!("search {}: {e}", indices::USERS)))?;

    Ok(result.total.value > 0)
}

// ─────────────────────────────────────────────────────────────────────────────
// Magic link minting
// ─────────────────────────────────────────────────────────────────────────────

/// Format of the token the operator pastes into a browser. Random 32 bytes,
/// URL-safe base64 (no padding) — always 43 chars. We never log or store
/// the token in plaintext; only its sha256 lands in `.xerj_magic_links`.
const TOKEN_BYTES: usize = 32;
const BOOTSTRAP_TTL_MS: i64 = 30 * 60 * 1000; // 30 minutes

async fn mint_bootstrap_link(engine: &Engine, bind_url: &str) -> ConsoleResult<String> {
    let idx = engine
        .get_index(indices::MAGIC_LINKS)
        .map_err(|e| ConsoleApiError::Internal(format!("open {}: {e}", indices::MAGIC_LINKS)))?;

    let token = random_url_token();
    let token_hash = sha256_hex(token.as_bytes());

    let now_ms = now_epoch_ms();
    let expires_ms = now_ms + BOOTSTRAP_TTL_MS;

    let doc: Value = json!({
        "purpose":     "bootstrap",
        "role":        "owner",
        "user_id":     null,
        "email":       null,
        "created_by":  "system",
        "created_at":  now_iso(),
        "expires_at":  crate::time::epoch_ms_to_iso(expires_ms),
        "used_at":     null,
        "used_from_ip": null
    });

    idx.create_document(token_hash.clone(), doc)
        .await
        .map_err(|e| ConsoleApiError::Internal(format!("write magic link: {e}")))?;

    Ok(format!(
        "{}/_xerj-console/setup#token={}",
        bind_url.trim_end_matches('/'),
        token
    ))
}

/// Printed under the bootstrap link. Names the recovery that actually works:
/// while no active user exists, every boot re-mints and reprints a fresh link
/// (see `run` above) — and the shipped binary has no `admin` subcommand. An
/// earlier revision of this line suggested `xerj admin magic-link --role
/// owner`, which rc.95 rejects with `unknown argument: admin` (#1424).
const RENEWAL_HINT: &str = "Need a fresh link?  Restart this node: a new one is printed on boot.";

fn print_bootstrap_banner(url: &str) {
    let bar = "─".repeat(78);
    eprintln!();
    eprintln!("┌{bar}┐");
    eprintln!("│ {:<76} │", "XERJ CONSOLE  ·  first-launch setup");
    eprintln!("│ {:<76} │", "");
    eprintln!(
        "│ {:<76} │",
        "Open this link in your browser to claim the owner account by"
    );
    eprintln!(
        "│ {:<76} │",
        "enrolling a passkey.  Valid for 30 minutes.  Single use."
    );
    eprintln!("│ {:<76} │", "");
    // The URL can be longer than 76 chars; if so, print it on its own line.
    if url.len() <= 76 {
        eprintln!("│   {:<74} │", url);
    } else {
        eprintln!("├{bar}┤");
        eprintln!("  {url}");
        eprintln!("├{bar}┤");
    }
    eprintln!("│ {:<76} │", "");
    eprintln!("│ {:<76} │", RENEWAL_HINT);
    eprintln!("└{bar}┘");
    eprintln!();
}

// ─────────────────────────────────────────────────────────────────────────────
// Tiny crypto helpers (dependency-light hex + sha256 + url-safe base64).
// ─────────────────────────────────────────────────────────────────────────────

fn random_url_token() -> String {
    let mut bytes = [0u8; TOKEN_BYTES];
    rand::thread_rng().fill_bytes(&mut bytes);
    base64_url_encode(&bytes)
}

pub(crate) fn sha256_hex(input: &[u8]) -> String {
    let mut h = Sha256::new();
    h.update(input);
    hex_encode(&h.finalize())
}

fn hex_encode(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{b:02x}"));
    }
    s
}

fn hex_decode(s: &str) -> Option<Vec<u8>> {
    if !s.len().is_multiple_of(2) {
        return None;
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    let mut chars = s.chars();
    while let (Some(a), Some(b)) = (chars.next(), chars.next()) {
        let h = a.to_digit(16)?;
        let l = b.to_digit(16)?;
        out.push(((h << 4) | l) as u8);
    }
    Some(out)
}

fn base64_url_encode(bytes: &[u8]) -> String {
    use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
    URL_SAFE_NO_PAD.encode(bytes)
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;
    use xerj_common::config::Config;

    fn engine_in(dir: &TempDir) -> Engine {
        let mut cfg = Config::default();
        cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
        Engine::new(cfg).expect("engine init")
    }

    #[tokio::test]
    async fn fresh_data_dir_emits_magic_link() {
        let dir = TempDir::new().unwrap();
        let engine = engine_in(&dir);

        let outcome = run(&engine, dir.path(), "http://localhost:9200")
            .await
            .expect("bootstrap");

        assert!(outcome.magic_link.is_some(), "fresh boot must mint a link");
        let url = outcome.magic_link.unwrap();
        assert!(url.starts_with("http://localhost:9200/_xerj-console/setup#token="));
        assert!(dir.path().join(".xerj_master_key").exists());
    }

    #[tokio::test]
    async fn bootstrap_idempotent_with_active_user() {
        let dir = TempDir::new().unwrap();
        let engine = engine_in(&dir);

        // First boot mints a link.
        let _ = run(&engine, dir.path(), "http://x").await.unwrap();

        // Simulate the operator finishing enrolment by writing an active
        // user. Real flow goes through /auth/passkey/finish in phase 2.
        let users = engine.get_index(indices::USERS).unwrap();
        users
            .create_document(
                "u1".into(),
                json!({
                    "email": "owner@example.com",
                    "role": "owner",
                    "status": "active",
                    "created_at": now_iso()
                }),
            )
            .await
            .unwrap();
        users.flush().await.unwrap();

        let outcome2 = run(&engine, dir.path(), "http://x").await.unwrap();
        assert!(
            outcome2.magic_link.is_none(),
            "second boot with an active user must not mint a new link"
        );
    }

    #[test]
    fn master_key_round_trip() {
        let dir = TempDir::new().unwrap();
        let k1 = load_or_init_master_key(dir.path()).unwrap();
        let k2 = load_or_init_master_key(dir.path()).unwrap();
        assert_eq!(k1, k2, "key must be stable across boots");
    }

    /// #1424: the banner must not name a command the shipped binary lacks.
    /// It used to suggest `xerj admin magic-link --role owner`; the CLI has no
    /// `admin` subcommand and rejects it with `unknown argument: admin`.
    /// The recovery it names instead is a restart — which the next test pins
    /// to actually mint a fresh link.
    #[test]
    fn renewal_hint_names_a_recovery_that_exists() {
        assert!(
            !RENEWAL_HINT.contains("admin"),
            "the hint must not name the nonexistent `xerj admin` subcommand: \
             {RENEWAL_HINT}"
        );
        assert!(
            RENEWAL_HINT.contains("Restart"),
            "the hint must name the real recovery (a restart re-mints a link): \
             {RENEWAL_HINT}"
        );
    }

    /// The banner's advice, exercised: before anyone claims the owner account,
    /// restarting the node mints ANOTHER printable link with a new token —
    /// which is what makes "restart" a genuine recovery for an expired link.
    #[tokio::test]
    async fn restart_without_an_active_user_mints_a_fresh_link() {
        let dir = TempDir::new().unwrap();
        let engine = engine_in(&dir);

        let first = run(&engine, dir.path(), "http://localhost:9200")
            .await
            .expect("first boot")
            .magic_link
            .expect("a fresh boot must mint a link");
        let second = run(&engine, dir.path(), "http://localhost:9200")
            .await
            .expect("restart before enrolment")
            .magic_link
            .expect("a restart before enrolment must mint another link");

        assert_ne!(first, second, "the fresh link must carry a new token");
        assert!(second.starts_with("http://localhost:9200/_xerj-console/setup#token="));
    }
}

//! Who the caller *is*, as opposed to who they claim to be (#76 S5-4).
//!
//! Every auth endpoint charges a per-IP rate-limit bucket and stamps a source
//! address into the audit log. Both used to be derived from `X-Forwarded-For`
//! — a header the caller writes. A rotating `x-forwarded-for: 1.2.3.$RANDOM`
//! therefore got a fresh quota on every request (unthrottled brute force of
//! magic links and the bootstrap claim) while honest clients, who send no such
//! header, stayed throttled. Exactly backwards.
//!
//! The address now comes from the transport: [`axum::extract::ConnectInfo`],
//! i.e. the TCP peer, which the caller cannot forge.
//!
//! ## Reverse proxies
//!
//! Behind a legitimate proxy the peer *is* the proxy, and keying purely on the
//! socket would collapse every user into one bucket — a self-inflicted DoS. So
//! forwarding headers are honoured, but only when the socket peer is a proxy
//! the operator declared in `server.trusted_proxies`. The list is empty by
//! default: **an unconfigured node believes nobody**.
//!
//! ## Reading the chain
//!
//! `X-Forwarded-For` is a comma-separated chain, appended to left-to-right.
//! The left end is whatever the original caller sent — attacker-controlled.
//! The *right-most* entry is the one your own outermost proxy just wrote, so
//! the chain is walked right-to-left, skipping entries that are themselves
//! declared proxies, and the first non-proxy address wins. A malformed
//! element stops the walk (we do not step over it into attacker-authored
//! text) and we fall back to the peer.

use std::net::{IpAddr, SocketAddr};

use axum::{
    async_trait,
    extract::{ConnectInfo, FromRequestParts},
    http::{request::Parts, HeaderMap},
};
use xerj_common::net::{canonical_ip, parse_forwarded_element, TrustedProxies};

/// The bucket key used when we cannot establish any address at all (no
/// `ConnectInfo` in the request extensions — e.g. a router driven directly by
/// `tower::ServiceExt::oneshot` in a test, or a future transport that does not
/// carry a peer). Failing to one shared bucket throttles rather than
/// exempts: strictly safer than believing a header.
pub const UNKNOWN_IP: &str = "unknown";

/// Resolve the caller's address.
///
/// `peer` is the real socket peer. Returns the address as a string because
/// that is what the rate-limit key and the audit record want; the value is
/// always either a canonical IP literal or [`UNKNOWN_IP`], never
/// caller-authored text.
pub fn resolve(peer: Option<IpAddr>, headers: &HeaderMap, trusted: &TrustedProxies) -> String {
    let Some(peer) = peer.map(canonical_ip) else {
        // No transport identity. Header data cannot rescue this — it would
        // reintroduce the very spoof we are closing.
        return UNKNOWN_IP.to_string();
    };

    // The common case, and the whole point: an ordinary client's headers are
    // never consulted.
    if !trusted.contains(&peer) {
        return peer.to_string();
    }

    // Peer is a declared proxy — its forwarding headers may be believed.
    // Multiple `X-Forwarded-For` headers are equivalent to one comma-joined
    // header (RFC 7230 §3.2.2), so walk every value, right-to-left.
    let elements: Vec<&str> = headers
        .get_all("x-forwarded-for")
        .iter()
        .filter_map(|v| v.to_str().ok())
        .flat_map(|v| v.split(','))
        .collect();

    if !elements.is_empty() {
        for element in elements.iter().rev() {
            match parse_forwarded_element(element) {
                Some(ip) => {
                    let ip = canonical_ip(ip);
                    if !trusted.contains(&ip) {
                        return ip.to_string();
                    }
                    // Another of our own proxies — keep walking left.
                }
                // Garbage or an obfuscated identifier. Stop: anything further
                // left is behind text we could not validate.
                None => return peer.to_string(),
            }
        }
        // Every hop in the chain was one of our own proxies; the original
        // client was never recorded.
        return peer.to_string();
    }

    // No forwarded chain — honour the single-valued `X-Real-IP` that nginx
    // and friends set. Same trust gate: only because the peer is declared.
    if let Some(ip) = headers
        .get("x-real-ip")
        .and_then(|v| v.to_str().ok())
        .and_then(parse_forwarded_element)
    {
        return canonical_ip(ip).to_string();
    }

    peer.to_string()
}

/// Extractor form: the caller's address, already trust-resolved.
///
/// Use this in handlers instead of reading headers. It needs `ConnectInfo` in
/// the request extensions, which the server installs via
/// `into_make_service_with_connect_info::<SocketAddr>()` on both the plain and
/// the TLS listener.
#[derive(Debug, Clone)]
pub struct ClientIp(pub String);

impl ClientIp {
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

#[async_trait]
impl<S> FromRequestParts<S> for ClientIp
where
    S: TrustedProxySource + Send + Sync,
{
    type Rejection = std::convert::Infallible;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        let peer = parts
            .extensions
            .get::<ConnectInfo<SocketAddr>>()
            .map(|ci| ci.0.ip());
        Ok(ClientIp(resolve(
            peer,
            &parts.headers,
            state.trusted_proxies(),
        )))
    }
}

/// State that can say which proxies are trusted. Implemented by
/// `ConsoleState`; a trait so the extractor stays testable without one.
pub trait TrustedProxySource {
    fn trusted_proxies(&self) -> &TrustedProxies;
}

#[cfg(test)]
mod tests {
    use super::*;

    fn headers(pairs: &[(&str, &str)]) -> HeaderMap {
        let mut h = HeaderMap::new();
        for (k, v) in pairs {
            h.append(
                axum::http::HeaderName::from_bytes(k.as_bytes()).unwrap(),
                axum::http::HeaderValue::from_str(v).unwrap(),
            );
        }
        h
    }

    fn ip(s: &str) -> IpAddr {
        s.parse().unwrap()
    }

    fn trust(entries: &[&str]) -> TrustedProxies {
        TrustedProxies::parse(&entries.iter().map(|s| s.to_string()).collect::<Vec<_>>()).unwrap()
    }

    // ── The defect itself ────────────────────────────────────────────────

    /// #76 S5-4: an untrusted caller cannot move its own rate-limit bucket.
    #[test]
    fn spoofed_header_from_untrusted_peer_is_ignored() {
        let t = TrustedProxies::none();
        let peer = Some(ip("203.0.113.9"));
        let baseline = resolve(peer, &HeaderMap::new(), &t);
        assert_eq!(baseline, "203.0.113.9");

        for spoof in ["1.2.3.4", "1.2.3.5, 9.9.9.9", "  8.8.8.8  ", "2001:db8::1"] {
            assert_eq!(
                resolve(peer, &headers(&[("x-forwarded-for", spoof)]), &t),
                baseline,
                "x-forwarded-for: {spoof} must not change the key"
            );
        }
        assert_eq!(
            resolve(peer, &headers(&[("x-real-ip", "1.2.3.4")]), &t),
            baseline
        );
    }

    /// The brute-force shape from the finding: a rotating header used to mint
    /// a new bucket per request. Every rotation must now collapse to one key.
    #[test]
    fn rotating_spoof_yields_one_key() {
        let t = TrustedProxies::none();
        let peer = Some(ip("203.0.113.9"));
        let keys: std::collections::HashSet<String> = (0..64)
            .map(|n| {
                resolve(
                    peer,
                    &headers(&[("x-forwarded-for", &format!("1.2.3.{n}"))]),
                    &t,
                )
            })
            .collect();
        assert_eq!(keys.len(), 1, "rotating spoof produced {keys:?}");
    }

    /// Configuring a proxy does not make *other* peers trustworthy.
    #[test]
    fn peer_outside_the_trusted_set_is_still_ignored() {
        let t = trust(&["10.0.0.0/8"]);
        assert_eq!(
            resolve(
                Some(ip("203.0.113.9")),
                &headers(&[("x-forwarded-for", "1.2.3.4")]),
                &t
            ),
            "203.0.113.9"
        );
    }

    // ── The proxy case ───────────────────────────────────────────────────

    #[test]
    fn trusted_peer_has_its_forwarded_address_honoured() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "198.51.100.23")]),
                &t
            ),
            "198.51.100.23"
        );
    }

    /// The attacker owns the left end of the chain; only the right-most entry
    /// was written by our own proxy.
    #[test]
    fn rightmost_entry_wins_over_attacker_prefix() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "1.1.1.1, 2.2.2.2, 198.51.100.23")]),
                &t
            ),
            "198.51.100.23",
            "must not take the caller-authored left end"
        );
    }

    /// Two proxy hops: skip our own, take the first address neither of them.
    #[test]
    fn walks_left_past_our_own_proxies() {
        let t = trust(&["10.0.0.0/8"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "198.51.100.23, 10.0.0.9")]),
                &t
            ),
            "198.51.100.23"
        );
    }

    /// Split across repeated header lines — same chain semantics.
    #[test]
    fn repeated_headers_are_one_chain() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[
                    ("x-forwarded-for", "1.1.1.1"),
                    ("x-forwarded-for", "198.51.100.23"),
                ]),
                &t
            ),
            "198.51.100.23"
        );
    }

    /// An attacker behind our proxy can send garbage as the element to the
    /// left of the real one; we must not step over it and adopt their text.
    #[test]
    fn malformed_element_falls_back_to_the_peer() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "198.51.100.23, unknown")]),
                &t
            ),
            "10.0.0.7"
        );
    }

    #[test]
    fn all_hops_trusted_falls_back_to_the_peer() {
        let t = trust(&["10.0.0.0/8"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "10.0.0.4, 10.0.0.9")]),
                &t
            ),
            "10.0.0.7"
        );
    }

    #[test]
    fn trusted_peer_honours_x_real_ip_when_no_chain() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-real-ip", "198.51.100.23")]),
                &t
            ),
            "198.51.100.23"
        );
    }

    #[test]
    fn trusted_peer_with_no_headers_is_the_peer() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(Some(ip("10.0.0.7")), &HeaderMap::new(), &t),
            "10.0.0.7"
        );
    }

    // ── Edges ────────────────────────────────────────────────────────────

    /// No transport identity: one shared bucket, never a header-derived one.
    #[test]
    fn missing_connect_info_never_falls_back_to_headers() {
        for t in [TrustedProxies::none(), trust(&["0.0.0.0/0"])] {
            assert_eq!(
                resolve(None, &headers(&[("x-forwarded-for", "1.2.3.4")]), &t),
                UNKNOWN_IP
            );
        }
    }

    /// A dual-stack listener reports IPv4 peers as `::ffff:a.b.c.d`; the
    /// trusted-proxy entry is written in plain v4 form.
    #[test]
    fn v4_mapped_peer_matches_v4_trust_entry() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("::ffff:10.0.0.7")),
                &headers(&[("x-forwarded-for", "198.51.100.23")]),
                &t
            ),
            "198.51.100.23"
        );
        // …and the key for an ordinary v4-mapped client is the plain v4 form,
        // so one client never occupies two buckets.
        assert_eq!(
            resolve(Some(ip("::ffff:203.0.113.9")), &HeaderMap::new(), &t),
            "203.0.113.9"
        );
    }

    #[test]
    fn forwarded_entries_with_ports_are_accepted() {
        let t = trust(&["10.0.0.7"]);
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "198.51.100.23:44321")]),
                &t
            ),
            "198.51.100.23"
        );
        assert_eq!(
            resolve(
                Some(ip("10.0.0.7")),
                &headers(&[("x-forwarded-for", "[2001:db8::5]:443")]),
                &t
            ),
            "2001:db8::5"
        );
    }

    /// The socket port is not part of identity — otherwise every connection
    /// from one host would get its own quota.
    #[test]
    fn peer_port_is_not_part_of_the_key() {
        let t = TrustedProxies::none();
        let a: SocketAddr = "203.0.113.9:1111".parse().unwrap();
        let b: SocketAddr = "203.0.113.9:2222".parse().unwrap();
        assert_eq!(
            resolve(Some(a.ip()), &HeaderMap::new(), &t),
            resolve(Some(b.ip()), &HeaderMap::new(), &t)
        );
    }
}

//! Cluster awareness endpoints.
//!
//! Phase 1 ships only `/cluster/info` — the standalone-vs-raft probe the
//! Xerj Console SPA reads at boot to decide whether to render the topology
//! widget. Full RAFT endpoints (`/cluster/raft`, `/cluster/peers`,
//! `/cluster/replication`, admin actions) land in phase 4 once the
//! identity and prefs paths have been proven end-to-end.

use axum::{extract::State, response::Response};
use serde_json::json;

use crate::error::ConsoleResult;
use crate::response::ok;
use crate::state::ConsoleState;

/// `GET /_xerj-console/api/v1/cluster/info`
///
/// Returns enough for the SPA to:
/// - Show "node up since…" without a separate /uptime fetch.
/// - Render `mode == "standalone"` (single-node card, hide topology
///   widget) or `mode == "raft"` (will light up `/cluster/raft` etc.
///   in phase 4 — until then the SPA falls back to standalone view).
pub async fn info(State(state): State<ConsoleState>) -> ConsoleResult<Response> {
    use crate::state::ClusterMode;

    let mode = match state.cluster_mode {
        ClusterMode::Standalone => "standalone",
        ClusterMode::Raft => "raft",
    };

    Ok(ok(info_body(mode, state.started_at.0), None))
}

/// Build the unauthenticated `cluster/info` body.
///
/// AUTHZ-2: this endpoint is unauthenticated (the SPA reads it at boot, before
/// login, to choose standalone-vs-topology view). It must therefore expose only
/// what that decision needs — `mode` — plus the benign uptime. `node_id` and
/// the exact build `version` are deliberately omitted: a pre-auth version string
/// hands an attacker a precise target for known-CVE matching, and the node
/// identity leaks cluster topology. Authenticated callers get the full detail
/// from the credentialed cluster/status paths.
fn info_body(mode: &str, started_at_ms: i64) -> serde_json::Value {
    json!({
        "mode":          mode,
        "started_at_ms": started_at_ms,
    })
}

#[cfg(test)]
mod tests {
    use super::info_body;

    #[test]
    fn info_body_omits_node_id_and_version_pre_auth() {
        let v = info_body("standalone", 1_700_000_000_000);
        assert_eq!(v.get("mode").and_then(|m| m.as_str()), Some("standalone"));
        assert!(v.get("started_at_ms").is_some());
        // The AUTHZ-2 disclosure fields must be gone from the pre-auth body.
        assert!(v.get("node_id").is_none(), "node_id must not leak pre-auth");
        assert!(v.get("version").is_none(), "version must not leak pre-auth");
        // And the whole serialized body must not contain the build version.
        let s = v.to_string();
        assert!(
            !s.contains(env!("CARGO_PKG_VERSION")),
            "build version must not appear in the pre-auth body: {s}"
        );
    }
}

//! Dashboards CRUD.
//!
//! Replaces `localStorage["xerj.dashboards"]` and
//! `localStorage["xerj.layout.<id>"]` with engine-backed durable state.
//! Every dashboard write (PUT / PATCH) **requires** an
//! `If-Match: W/"<version>"` etag for optimistic concurrency: a missing
//! header is rejected with 428 Precondition Required, a stale one with
//! 409 Conflict. This applies to private dashboards too — one owner
//! with two tabs open is still two writers.
//!
//! Real-time push (SSE `/_stream`) is NOT implemented in this release:
//! there is no `/_stream` endpoint on dashboards or views, and none is
//! registered in the router.  Concurrent edits are surfaced only on the
//! next read — an SE who wants to see "another user just renamed this
//! dashboard" must re-fetch (poll) rather than receive a live event.
//! The If-Match etag on writes still makes a stale update fail loudly
//! with 409 instead of silently clobbering, so correctness never
//! depends on live push; it only trades a lower-latency notification.
//! CRUD is complete and correct; live push is deferred (tracked in the
//! crate-level "Coming after RC" list in `lib.rs`).

use axum::{
    extract::{Path, State},
    http::HeaderMap,
    response::Response,
    Json,
};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::auth::sessions::AuthSession;
use crate::auth::store::UserStatus;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::response::{created, no_content, ok};
use crate::state::ConsoleState;
use crate::time::now_iso;

/// A durable dashboard.
///
/// # Panel schema (convention inside `panels[]`)
///
/// The engine stores `panels` **opaquely** — it is a `Vec<Value>` here and an
/// untyped array in the mapping (deliberately *not* typed in
/// [`crate::indices`]).  The frontend panel-builder and the seeding module
/// ([`crate::seed`]) agree on this shape, and it round-trips through
/// create/replace/patch byte-for-byte:
///
/// ```jsonc
/// {
///   "id": "queries",                 // stable & unique within the dashboard
///   "type": "metric|line|topn|heatmap|table|events|markdown|ribbon3d|…",
///   "title": "LLM QUERIES",          // supersedes the old `eyebrow`
///   "layout": { "x": 0, "y": 0, "w": 4, "h": 2 },
///        // FREE-FORM grid: x/w in 12-col units, y/h in row units. Subsumes
///        // the old bare `cols` (== w) and enables drag / move / resize /
///        // height.
///   "query": {                       // null for static panels (markdown)
///     "index": "logs-*",
///     "time_field": "@timestamp",
///     "dsl":  { /* ES query DSL — reuses the ES-compat search port */ },
///     "aggs": { /* ES aggs */ }
///   },
///   "viz":  { "unit": "queries", "value_field": "…", "spark": true, … },
///        // type-specific display config
///   "drilldown": { "to": "<dashId>", "filter_field": "intent" } | null,
///   "builtin":   "ai-overview/queries" | null
///        // provenance key for seeded panels still resolved through the
///        // shipped mock renderer; null for user-authored data-driven panels.
/// }
/// ```
///
/// Per-panel geometry, query, and viz all live here; the dashboard-level time
/// / filter context lives in the top-level `time_default` + `filters_default`.
/// There is intentionally **no per-panel PATCH**: `panels` replaces wholesale
/// (dashboards are small — the frontend sends the full array on save).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Dashboard {
    pub id: String,
    pub owner: String,
    #[serde(default = "default_org")]
    pub org_id: String,
    /// `private` (only owner sees / writes), `shared` (every user in
    /// the org reads, only `editor` and up writes), `default` (engine-
    /// provisioned built-in dashboards — editable by admin/owner, never
    /// deletable; see `managed`).
    pub visibility: String,
    /// `true` for engine-seeded built-in dashboards ([`crate::seed`]). A
    /// managed doc is editable by admin/owner (so layout/title/panel edits
    /// persist) but cannot be deleted, and re-seed leaves it alone once it has
    /// been edited (`version > 1`). User-authored dashboards are always
    /// `managed: false` — clients cannot mint a managed doc through `create`.
    #[serde(default)]
    pub managed: bool,
    pub name: String,
    #[serde(default)]
    pub section: Option<String>,
    #[serde(default)]
    pub group: Option<String>,
    #[serde(default)]
    pub cloned_from: Option<String>,
    #[serde(default)]
    pub panels: Vec<Value>,
    #[serde(default)]
    pub filters_default: Value,
    #[serde(default)]
    pub time_default: Option<String>,
    pub version: u64,
    pub created_at: String,
    pub updated_at: String,
    #[serde(default)]
    pub deleted_at: Option<String>,
}

fn default_org() -> String {
    "default".to_string()
}

#[derive(Debug, Deserialize)]
pub struct CreateBody {
    pub name: String,
    #[serde(default = "default_visibility")]
    pub visibility: String,
    #[serde(default)]
    pub section: Option<String>,
    #[serde(default)]
    pub group: Option<String>,
    #[serde(default)]
    pub cloned_from: Option<String>,
    #[serde(default)]
    pub panels: Vec<Value>,
    #[serde(default)]
    pub filters_default: Value,
    #[serde(default)]
    pub time_default: Option<String>,
}

fn default_visibility() -> String {
    "private".to_string()
}

#[derive(Debug, Deserialize, Default)]
pub struct PatchBody {
    #[serde(default)]
    pub name: Option<String>,
    #[serde(default)]
    pub visibility: Option<String>,
    #[serde(default)]
    pub section: Option<String>,
    #[serde(default)]
    pub group: Option<String>,
    #[serde(default)]
    pub panels: Option<Vec<Value>>,
    #[serde(default)]
    pub filters_default: Option<Value>,
    #[serde(default)]
    pub time_default: Option<String>,
    /// Accepted for a full-object round-trip, but only applied when the caller
    /// is admin/owner (see `apply_managed`). `owner` / `org_id` / `created_at`
    /// are intentionally absent — they are create-only and never patchable.
    #[serde(default)]
    pub managed: Option<bool>,
}

// ─────────────────────────────────────────────────────────────────────────────
// LIST
// ─────────────────────────────────────────────────────────────────────────────

pub async fn list(State(state): State<ConsoleState>, sess: AuthSession) -> ConsoleResult<Response> {
    let idx = state.engine.get_index(indices::DASHBOARDS)?;
    // Pull everything; filter by owner / visibility in code. The
    // `.xerj_dashboards` index is small (≤ low thousands) so the
    // simpler approach beats fighting bool-query semantics in tests.
    let body = json!({
        "query": { "match_all": {} },
        "size": 1000
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;

    let me = sess.user.id.as_str();
    let mut items: Vec<Value> = Vec::with_capacity(r.hits.len());
    for h in r.hits {
        let d: Dashboard = match serde_json::from_value(h.source) {
            Ok(d) => d,
            Err(_) => continue,
        };
        if d.deleted_at.is_some() {
            continue;
        }
        let visible = d.owner == me || d.visibility == "shared" || d.visibility == "default";
        if visible {
            items.push(serde_json::to_value(&d)?);
        }
    }
    Ok(ok(
        json!({ "dashboards": items, "total": items.len() }),
        None,
    ))
}

// ─────────────────────────────────────────────────────────────────────────────
// GET ONE
// ─────────────────────────────────────────────────────────────────────────────

pub async fn get_one(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(id): Path<String>,
) -> ConsoleResult<Response> {
    let dash = read_required(&state, &id).await?;
    enforce_read(&sess, &dash)?;
    let etag = format!("{}", dash.version);
    Ok(ok(dash, Some(&etag)))
}

// ─────────────────────────────────────────────────────────────────────────────
// CREATE
// ─────────────────────────────────────────────────────────────────────────────

pub async fn create(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Json(body): Json<CreateBody>,
) -> ConsoleResult<Response> {
    enforce_can_set_visibility(&sess, &body.visibility, None)?;
    let id = uuid::Uuid::new_v4().to_string();
    let now = now_iso();
    let dash = Dashboard {
        id: id.clone(),
        owner: sess.user.id.clone(),
        org_id: default_org(),
        visibility: body.visibility,
        // Clients never mint managed docs — only the seeder (and the
        // admin/owner-only `_bulk` path) can set `managed: true`.
        managed: false,
        name: body.name,
        section: body.section,
        group: body.group,
        cloned_from: body.cloned_from,
        panels: body.panels,
        filters_default: body.filters_default,
        time_default: body.time_default,
        version: 1,
        created_at: now.clone(),
        updated_at: now,
        deleted_at: None,
    };
    write_doc(&state, &dash).await?;
    let etag = format!("{}", dash.version);
    let location = format!("/_xerj-console/api/v1/dashboards/{id}");
    Ok(created(dash, &location, Some(&etag)))
}

// ─────────────────────────────────────────────────────────────────────────────
// REPLACE (PUT)
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct ReplaceBody {
    pub name: String,
    pub visibility: String,
    #[serde(default)]
    pub section: Option<String>,
    #[serde(default)]
    pub group: Option<String>,
    #[serde(default)]
    pub panels: Vec<Value>,
    #[serde(default)]
    pub filters_default: Value,
    #[serde(default)]
    pub time_default: Option<String>,
    /// See [`PatchBody::managed`] — applied only for admin/owner; create-only
    /// fields (`owner`/`org_id`/`created_at`) are never accepted here.
    #[serde(default)]
    pub managed: Option<bool>,
}

/// Body for `POST /dashboards/_bulk` — whole-set save + uniform seeding path.
#[derive(Debug, Deserialize, Default)]
pub struct BulkBody {
    /// Full dashboard objects (each MUST carry an `id`); upserted in place.
    #[serde(default)]
    pub upserts: Vec<Value>,
    /// Ids to soft-delete.
    #[serde(default)]
    pub deletes: Vec<String>,
}

pub async fn replace(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(id): Path<String>,
    headers: HeaderMap,
    Json(body): Json<ReplaceBody>,
) -> ConsoleResult<Response> {
    let mut dash = read_required(&state, &id).await?;
    enforce_write(&sess, &dash)?;
    enforce_etag(&headers, dash.version)?;
    enforce_can_set_visibility(&sess, &body.visibility, Some(&dash.visibility))?;

    dash.name = body.name;
    dash.visibility = body.visibility;
    dash.section = body.section;
    dash.group = body.group;
    dash.panels = body.panels;
    dash.filters_default = body.filters_default;
    dash.time_default = body.time_default;
    apply_managed(&sess, &mut dash, body.managed);
    dash.version += 1;
    dash.updated_at = now_iso();

    write_doc(&state, &dash).await?;
    let etag = format!("{}", dash.version);
    Ok(ok(dash, Some(&etag)))
}

// ─────────────────────────────────────────────────────────────────────────────
// PATCH
// ─────────────────────────────────────────────────────────────────────────────

pub async fn patch(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(id): Path<String>,
    headers: HeaderMap,
    Json(body): Json<PatchBody>,
) -> ConsoleResult<Response> {
    let mut dash = read_required(&state, &id).await?;
    enforce_write(&sess, &dash)?;
    enforce_etag(&headers, dash.version)?;

    if let Some(name) = body.name {
        dash.name = name;
    }
    if let Some(visibility) = body.visibility {
        enforce_can_set_visibility(&sess, &visibility, Some(&dash.visibility))?;
        dash.visibility = visibility;
    }
    if let Some(section) = body.section {
        dash.section = Some(section);
    }
    if let Some(group) = body.group {
        dash.group = Some(group);
    }
    if let Some(panels) = body.panels {
        dash.panels = panels;
    }
    if let Some(filters) = body.filters_default {
        dash.filters_default = filters;
    }
    if let Some(td) = body.time_default {
        dash.time_default = Some(td);
    }
    apply_managed(&sess, &mut dash, body.managed);

    dash.version += 1;
    dash.updated_at = now_iso();

    write_doc(&state, &dash).await?;
    let etag = format!("{}", dash.version);
    Ok(ok(dash, Some(&etag)))
}

// ─────────────────────────────────────────────────────────────────────────────
// DELETE (soft)
// ─────────────────────────────────────────────────────────────────────────────

pub async fn delete(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(id): Path<String>,
) -> ConsoleResult<Response> {
    let mut dash = read_required(&state, &id).await?;
    // Seeded / managed defaults are editable but not deletable, so a re-seed
    // always has a canonical row to keep in sync and an operator can't nuke a
    // shipped dashboard by accident.
    if dash.managed || dash.visibility == "default" {
        return Err(ConsoleApiError::Forbidden(
            "managed default dashboards cannot be deleted".into(),
        ));
    }
    enforce_write(&sess, &dash)?;
    dash.deleted_at = Some(now_iso());
    dash.version += 1;
    write_doc(&state, &dash).await?;
    Ok(no_content())
}

// ─────────────────────────────────────────────────────────────────────────────
// BULK (whole-set save + uniform seeding path)
// ─────────────────────────────────────────────────────────────────────────────

/// `POST /dashboards/_bulk` — upsert a set of full dashboards and/or
/// soft-delete a set of ids in one call.  This is a **privileged** operation
/// (it can set `owner` / `managed` / `visibility` freely), so it is limited to
/// admin/owner roles.  The frontend uses it for a whole-set save; seeding uses
/// the same shape server-side.
pub async fn bulk(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Json(body): Json<BulkBody>,
) -> ConsoleResult<Response> {
    match sess.user.role.as_str() {
        "admin" | "owner" => require_active(&sess)?,
        _ => {
            return Err(ConsoleApiError::Forbidden(
                "bulk dashboard write requires admin or owner".into(),
            ))
        }
    }

    let now = now_iso();
    let mut upserted: Vec<String> = Vec::with_capacity(body.upserts.len());
    for raw in body.upserts {
        let mut dash: Dashboard = serde_json::from_value(raw).map_err(|e| {
            ConsoleApiError::BadRequest(format!("invalid dashboard in upsert: {e}"))
        })?;
        if dash.id.trim().is_empty() {
            return Err(ConsoleApiError::BadRequest(
                "upsert entry missing id".into(),
            ));
        }
        validate_visibility_value(&dash.visibility)?;
        if dash.org_id.trim().is_empty() {
            dash.org_id = default_org();
        }
        if dash.created_at.trim().is_empty() {
            dash.created_at = now.clone();
        }
        dash.version = dash.version.max(1);
        dash.updated_at = now.clone();
        write_doc(&state, &dash).await?;
        upserted.push(dash.id);
    }

    let mut deleted: Vec<String> = Vec::with_capacity(body.deletes.len());
    for id in body.deletes {
        // Ignore ids that are already gone (idempotent).
        if let Ok(mut dash) = read_required(&state, &id).await {
            dash.deleted_at = Some(now.clone());
            dash.version += 1;
            write_doc(&state, &dash).await?;
            deleted.push(id);
        }
    }

    Ok(ok(
        json!({ "upserted": upserted, "deleted": deleted }),
        None,
    ))
}

// ─────────────────────────────────────────────────────────────────────────────
// helpers
// ─────────────────────────────────────────────────────────────────────────────

async fn read_required(state: &ConsoleState, id: &str) -> ConsoleResult<Dashboard> {
    let idx = state.engine.get_index(indices::DASHBOARDS)?;
    let body = json!({
        "query": { "ids": { "values": [id] } },
        "size": 1
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    let hit = r
        .hits
        .into_iter()
        .next()
        .ok_or_else(|| ConsoleApiError::NotFound(format!("dashboard {id}")))?;
    let dash: Dashboard = serde_json::from_value(hit.source)?;
    if dash.deleted_at.is_some() {
        return Err(ConsoleApiError::NotFound(format!("dashboard {id}")));
    }
    Ok(dash)
}

async fn write_doc(state: &ConsoleState, dash: &Dashboard) -> ConsoleResult<()> {
    let idx = state.engine.get_index(indices::DASHBOARDS)?;
    // Single in-place upsert (one WAL append) instead of delete-then-create,
    // so a crash between the two operations can never leave the id missing
    // (durability, design C.2). `index_document` overwrites an existing id.
    idx.index_document(Some(dash.id.clone()), serde_json::to_value(dash)?)
        .await?;
    Ok(())
}

fn enforce_read(sess: &AuthSession, dash: &Dashboard) -> ConsoleResult<()> {
    if dash.owner == sess.user.id {
        return Ok(());
    }
    match dash.visibility.as_str() {
        "shared" | "default" => Ok(()),
        _ => Err(ConsoleApiError::NotFound("dashboard".into())),
    }
}

fn enforce_write(sess: &AuthSession, dash: &Dashboard) -> ConsoleResult<()> {
    // Managed / default-visibility dashboards used to be flatly read-only.
    // They are now *editable* by admin/owner so the seeded defaults are true
    // editable data — layout, title, and panel edits persist. Lower roles
    // still can't touch them, and DELETE is blocked for everyone (see
    // `delete`). Re-seed leaves any edited default alone (version > 1).
    if dash.managed || dash.visibility == "default" {
        return match sess.user.role.as_str() {
            "admin" | "owner" => require_active(sess),
            _ => Err(ConsoleApiError::Forbidden(
                "managed dashboards are editable only by admin or owner".into(),
            )),
        };
    }
    if dash.owner == sess.user.id {
        return require_active(sess);
    }
    if dash.visibility == "shared" {
        match sess.user.role.as_str() {
            "editor" | "admin" | "owner" => return require_active(sess),
            _ => {}
        }
    }
    Err(ConsoleApiError::Forbidden("not your dashboard".into()))
}

/// Reject an unknown visibility string (used on every write path).
fn validate_visibility_value(visibility: &str) -> ConsoleResult<()> {
    match visibility {
        "private" | "shared" | "default" => Ok(()),
        other => Err(ConsoleApiError::BadRequest(format!(
            "unknown visibility '{other}'"
        ))),
    }
}

/// Validate the requested visibility and guard *escalation* to `default` by a
/// non-owner. The escalation guard fires only when the new visibility is
/// `default` **and differs** from the doc's current visibility — so an admin
/// editing an already-`default` seeded dashboard isn't blocked from keeping it
/// default; only minting a fresh unkillable default is owner-only. Pass
/// `current = None` on create.
fn enforce_can_set_visibility(
    sess: &AuthSession,
    new_visibility: &str,
    current: Option<&str>,
) -> ConsoleResult<()> {
    validate_visibility_value(new_visibility)?;
    if new_visibility == "default" && current != Some("default") && sess.user.role != "owner" {
        return Err(ConsoleApiError::Forbidden(
            "only owner can create default-visibility dashboards".into(),
        ));
    }
    Ok(())
}

/// Apply a requested `managed` flag change. `managed` is a privileged
/// provenance marker: only admin/owner may change it (this prevents an editor
/// from making a shared dashboard un-deletable). Any other caller's value is
/// ignored and the existing flag is preserved, so a full-object round-trip
/// from a normal user is safe.
fn apply_managed(sess: &AuthSession, dash: &mut Dashboard, requested: Option<bool>) {
    if let Some(m) = requested {
        if matches!(sess.user.role.as_str(), "admin" | "owner") {
            dash.managed = m;
        }
    }
}

fn require_active(sess: &AuthSession) -> ConsoleResult<()> {
    if sess.user.status != UserStatus::Active {
        return Err(ConsoleApiError::Forbidden("user disabled".into()));
    }
    Ok(())
}

fn enforce_etag(headers: &HeaderMap, current_version: u64) -> ConsoleResult<()> {
    // If-Match is REQUIRED on every dashboard write (issue #210). It used to
    // be "optional but recommended", which made the 409 lost-update
    // protection opt-in: two writers that never sent the header both
    // succeeded and the second silently clobbered the first. A missing
    // header is now 428 Precondition Required; a present-but-stale header
    // stays 409 Conflict (the value must match the current version, in
    // either weak `W/"7"` or unweak `"7"` form).
    let Some(if_match) = headers.get("if-match").and_then(|v| v.to_str().ok()) else {
        return Err(ConsoleApiError::PreconditionRequired(format!(
            "dashboard writes require an If-Match header; \
             GET the dashboard and retry with If-Match: W/\"<version>\" \
             (current = W/\"{current_version}\")"
        )));
    };
    let trimmed = if_match.trim();
    let unwrapped = trimmed.trim_start_matches("W/").trim_matches('"');
    match unwrapped.parse::<u64>() {
        Ok(v) if v == current_version => Ok(()),
        _ => Err(ConsoleApiError::Conflict(format!(
            "etag mismatch (current = W/\"{current_version}\")"
        ))),
    }
}

#[cfg(test)]
mod tests {
    /// Locks the module-doc disclosure that SSE live push (`/_stream`)
    /// is NOT implemented: no route registered by this crate may expose
    /// a `_stream` (server-sent-events) endpoint. If real-time push is
    /// ever added, this assertion fails on purpose so the disclosure at
    /// the top of this module — and the crate-level "Coming after RC"
    /// list in `lib.rs` — is updated in the same change instead of
    /// silently drifting out of date.
    #[test]
    fn no_sse_stream_endpoint_is_registered() {
        let offenders: Vec<&str> = crate::router::known_routes()
            .iter()
            .copied()
            .filter(|route| route.contains("_stream"))
