}

//! Pluggable data sources.
//!
//! Phase-3 scope: the **read** half — list connections, list indices on
//! a connection, list fields on an index — backed by a single
//! auto-provisioned `built-in` connection that talks straight to the
//! in-process Engine.  This is enough for the SPA to drop its
//! hand-rolled `data-sources.js` overlay.
//!
//! **External-connection disclosure.** Only the `built-in` connection is
//! backed by a live adapter; its index and field listings are read
//! straight from the running Engine's real schema, never a canned map.
//! No external adapter subsystem exists yet — the adapter trait,
//! encrypted credentials, write paths (POST/PATCH/DELETE) and the
//! HTTP-shaped adapters (xerj-remote, elasticsearch, opensearch,
//! prometheus, postgres) all land in a follow-up commit.  Until then,
//! listing indices or fields for any non-`built-in` connection id
//! returns `501 Not Implemented` rather than a fabricated answer, and a
//! connection row that is not `built-in` is reported with status
//! `"unknown"` (no live probe is performed) so the UI never shows a
//! green light it cannot stand behind.

use axum::{
    extract::{Path, State},
    response::{IntoResponse, Response},
    Json,
};
use serde::Serialize;
use serde_json::{json, Value};

use crate::auth::sessions::AuthSession;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::response::ok;
use crate::state::ConsoleState;
use crate::time::now_iso;

/// Indices the data-sources surface must pretend do not exist: the Console's
/// own `.xerj_*` system indices, and the reserved `.xerj-memory-*` namespace
/// holding per-tenant brains / agent memories. The latter is enforced on the
/// data plane by `xerj-api`'s authz middleware, but the Console router is
/// merged onto the engine routers *after* their layers, so that middleware
/// never runs here and the in-process engine calls below carry no visibility
/// scope (absent guard = engine-internal work, allow). This proxy is
/// therefore its own boundary and must refuse the namespace itself — with
/// the same NotFound as a system index, so existence doesn't leak.
pub(crate) fn is_hidden_index(name: &str) -> bool {
    indices::is_system_index(name) || xerj_common::types::is_reserved_index(name)
}

/// Connection record — one row in `.xerj_connections`. Phase-3 only
/// surfaces the built-in adapter; adding new connections lands once the
/// AEAD-at-rest path for `auth.secret` is implemented.
#[derive(Debug, Clone, Serialize, serde::Deserialize)]
pub struct Connection {
    pub id: String,
    pub name: String,
    pub kind: String,
    #[serde(default)]
    pub url: Option<String>,
    #[serde(default = "default_true")]
    pub default: bool,
    #[serde(default = "default_true")]
    pub managed: bool,
    pub created_at: String,
    pub created_by: String,
    pub etag: String,
}

fn default_true() -> bool {
    true
}

const BUILTIN_ID: &str = "built-in";

// ─────────────────────────────────────────────────────────────────────────────
// LIST
// ─────────────────────────────────────────────────────────────────────────────

pub async fn list_connections(
    State(state): State<ConsoleState>,
    _sess: AuthSession,
) -> ConsoleResult<Response> {
    ensure_builtin(&state).await?;
    let idx = state.engine.get_index(indices::CONNECTIONS)?;
    let body = json!({
        "query": { "match_all": {} },
        "size": 100
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;

    let mut conns: Vec<Connection> = Vec::with_capacity(r.hits.len());
    for h in r.hits {
        if let Ok(c) = serde_json::from_value::<Connection>(h.source) {
            conns.push(c);
        }
    }

    // Decorate with live status — for now, only `built-in` is live, and
    // it's always green if the engine itself is responding (we're inside
    // it).  External adapters add real probing in a later commit.
    let mut out: Vec<Value> = Vec::with_capacity(conns.len());
    for c in conns {
        let status = if c.id == BUILTIN_ID {
            "green"
        } else {
            "unknown"
        };
        let mut v = serde_json::to_value(&c)?;
        v["status"] = Value::String(status.into());
        v["last_checked_at"] = Value::String(now_iso());
        out.push(v);
    }

    Ok(ok(json!({ "connections": out, "total": out.len() }), None))
}

// ─────────────────────────────────────────────────────────────────────────────
// INDICES
// ─────────────────────────────────────────────────────────────────────────────

pub async fn list_indices(
    State(state): State<ConsoleState>,
    _sess: AuthSession,
    Path(conn_id): Path<String>,
) -> ConsoleResult<Response> {
    ensure_builtin(&state).await?;

    if conn_id != BUILTIN_ID {
        // External adapters land in a later commit; everything that
        // isn't built-in is a stub for now.
        return Err(ConsoleApiError::NotImplemented(format!(
            "connection '{conn_id}' adapter not yet implemented"
        )));
    }

    // Walk the engine's indices via its public listing surface.  Skip
    // `.xerj_*` system indices and reserved `.xerj-memory-*` brains (see
    // `is_hidden_index`) — neither is a user data source.
    let mut items: Vec<Value> = Vec::new();
    for name in state.engine.index_name_list() {
        if is_hidden_index(&name) {
            continue;
        }
        let idx = match state.engine.get_index(&name) {
            Ok(i) => i,
            Err(_) => continue,
        };
        let stats = idx.stats().await;
        items.push(json!({
            "name": name,
            "docs": stats.doc_count,
            "segments": stats.segment_count,
            "fields": stats.field_count,
            // On-disk store bytes, measured from the index's data dir —
            // the same number /_cat/indices reports (es_compat's
            // dir_size_bytes, mirrored in knowledge.rs for this crate).
            "bytes": crate::knowledge::dir_size_bytes(idx.data_dir()),
            "shards": 1,
            "replicas": 0,
        }));
    }
    items.sort_by(|a, b| {
        a["name"]
            .as_str()
            .unwrap_or("")
            .cmp(b["name"].as_str().unwrap_or(""))
    });
    Ok(ok(json!({ "indices": items, "total": items.len() }), None))
}

// ─────────────────────────────────────────────────────────────────────────────
// FIELDS
// ─────────────────────────────────────────────────────────────────────────────

pub async fn list_fields(
    State(state): State<ConsoleState>,
    _sess: AuthSession,
    Path((conn_id, index)): Path<(String, String)>,
) -> ConsoleResult<Response> {
    if conn_id != BUILTIN_ID {
        return Err(ConsoleApiError::NotImplemented(format!(
            "connection '{conn_id}' adapter not yet implemented"
        )));
    }
    if is_hidden_index(&index) {
        return Err(ConsoleApiError::NotFound(format!("index {index}")));
    }
    let idx = state
        .engine
        .get_index(&index)
        .map_err(|_| ConsoleApiError::NotFound(format!("index {index}")))?;
    let schema = idx.schema().await;
    let fields: Vec<Value> = schema
        .fields
        .iter()
        .map(|f| {
            json!({
                "name": f.name,
                "type": f.field_type.to_string(),
                "indexed": f.options.indexed,
                "doc_values": f.options.doc_values,
                // A `semantic_text` field is a text field with an embedding
                // config; `type` alone reads "text". The console derives
                // which field `semantic` / `hybrid` run against from this
                // flag: it holds a session, not an engine API key, so on an
                // auth-enabled engine it cannot read `GET /{index}/_mapping`.
                "semantic": f.embedding.is_some(),
            })
        })
        .collect();
    Ok(ok(json!({ "fields": fields, "total": fields.len() }), None))
}

// ─────────────────────────────────────────────────────────────────────────────
// SEARCH
// ─────────────────────────────────────────────────────────────────────────────

/// Run an ES-compat `_search` against a single index, authenticated by the
/// caller's Console session instead of a data-plane API key.
///
/// **Why this exists.** The SPA's declarative dashboard panels
/// (`xerj-ux/src/data/panel-query.js`) and the built-in dashboard adapters
/// (`xerj-ux/src/data/backends/xerj.js`) used to `fetch()` `/{index}/_search`
/// directly, same-origin, with no `Authorization` header at all. That is
/// silently correct only when the engine is started with `--insecure`; on
/// any auth-enabled deployment — the default, recommended posture — every
/// such call gets a 401 the caller doesn't even look at (`backends/xerj.js`
/// treats any failure as "no live adapter, fall back to mock"), so the
/// entire "real dashboards" feature quietly regresses to demo data with no
/// visible error. This endpoint reuses the session-cookie gate every other
/// `data-sources` route already has (see `list_indices` / `list_fields`
/// above) and talks to the engine in-process — no data-plane credential is
/// needed at all, the same way `list_indices`/`list_fields` already read
/// the schema/stats in-process.
///
/// **Scope.** Single, exact index names only, matching `list_fields`'s
/// existing scope — no wildcard/`_all` resolution or multi-index merge
/// here (that logic is non-trivial and already lives, correctly, in
/// `xerj-api::es_compat`; duplicating a second copy risks exactly the kind
/// of subtle merge bug that logic has already been hardened against).
/// Callers that need a pattern get a clear `501`, not a silent wrong
/// answer — consistent with how this file already treats non-`built-in`
/// connections.
pub async fn search(
    State(state): State<ConsoleState>,
    _sess: AuthSession,
    Path((conn_id, index)): Path<(String, String)>,
    Json(body): Json<Value>,
) -> ConsoleResult<Response> {
    if conn_id != BUILTIN_ID {
        return Err(ConsoleApiError::NotImplemented(format!(
            "connection '{conn_id}' adapter not yet implemented"
        )));
    }
    if index.contains('*') || index == "_all" || index.split(',').count() > 1 {
        return Err(ConsoleApiError::NotImplemented(
            "panel search proxy supports a single exact index name only; \
             wildcard/_all/multi-index queries are not yet implemented"
                .into(),
        ));
    }
    if is_hidden_index(&index) {
        return Err(ConsoleApiError::NotFound(format!("index {index}")));
    }
    let idx = state
        .engine
        .get_index(&index)
        .map_err(|_| ConsoleApiError::NotFound(format!("index {index}")))?;

    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::BadRequest(e.to_string()))?;
    let result = idx
        .search(&req)
        .await
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;

    let hits: Vec<Value> = result
        .hits
        .iter()
        .map(|h| {
            let mut hit = json!({
                "_index": index,
                "_id": h.id,
                "_score": h.score,
                "_source": h.source,
            });
            // Pass the engine's highlight fragments through when the request
            // asked for them, so the Reader can mark matches for a signed-in
            // operator the same way it does for a guest on the ES-compat
            // route. Fragments are raw document text with the caller's
            // pre/post tags spliced in — the SPA never parses them as markup
            // (`xerj-ux/src/ux/safe-dom.js#highlightChildren`).
            if let Some(hl) = &h.highlight {
                hit["highlight"] = json!(hl);
            }
            hit
        })
        .collect();
    let wire = json!({
        "took": result.took_ms,
        "timed_out": result.timed_out,
        "hits": {
            "total": { "value": result.total.value, "relation": result.total.relation },
            "max_score": result.max_score,
            "hits": hits,
        },
        "aggregations": result.aggs,
    });
    Ok(Json(wire).into_response())
}

// ─────────────────────────────────────────────────────────────────────────────
// Built-in auto-provisioning
// ─────────────────────────────────────────────────────────────────────────────

async fn ensure_builtin(state: &ConsoleState) -> ConsoleResult<()> {
    let idx = state.engine.get_index(indices::CONNECTIONS)?;
    let body = json!({
        "query": { "ids": { "values": [BUILTIN_ID] } },
        "size": 1
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    if !r.hits.is_empty() {
        return Ok(());
    }
    let conn = Connection {
        id: BUILTIN_ID.into(),
        name: "Local Xerj".into(),
        kind: "xerj-local".into(),
        url: None,
        default: true,
        managed: true,
        created_at: now_iso(),
        created_by: "system".into(),
        etag: "1".into(),
    };
    idx.index_document(Some(BUILTIN_ID.into()), serde_json::to_value(&conn)?)
        .await?;
    Ok(())
}

//! Error types for the Xerj Console API surface.
//!
//! Every handler returns `ConsoleResult<T>`, which `axum` serialises into a
//! JSON body with the same envelope as the rest of xerj's HTTP error
//! responses (so a Xerj Console 404 looks the same as a `/v1/...` 404 to the SPA).

use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use serde_json::json;

#[derive(Debug, thiserror::Error)]
pub enum ConsoleApiError {
    #[error("not found: {0}")]
    NotFound(String),

    #[error("conflict: {0}")]
    Conflict(String),

    /// RFC 6585 §3 — the request must carry a precondition header
    /// (`If-Match`) and did not. Distinct from [`Self::Conflict`], which
    /// means the precondition was sent but did not match.
    #[error("precondition required: {0}")]
    PreconditionRequired(String),

    #[error("forbidden: {0}")]
    Forbidden(String),

    #[error("unauthorized: {0}")]
    Unauthorized(String),

    #[error("bad request: {0}")]
    BadRequest(String),

    #[error("not implemented: {0}")]
    NotImplemented(String),

    #[error("rate limited")]
    RateLimited,

    /// Wraps an underlying engine / I/O failure. The full error message is
    /// emitted to tracing; the HTTP body shows a generic 500 to avoid
    /// leaking internal paths.
    #[error("internal: {0}")]
    Internal(String),
}

pub type ConsoleResult<T> = Result<T, ConsoleApiError>;

impl ConsoleApiError {
    pub fn status(&self) -> StatusCode {
        match self {
            Self::NotFound(_) => StatusCode::NOT_FOUND,
            Self::Conflict(_) => StatusCode::CONFLICT,
            Self::PreconditionRequired(_) => StatusCode::PRECONDITION_REQUIRED,
            Self::Forbidden(_) => StatusCode::FORBIDDEN,
            Self::Unauthorized(_) => StatusCode::UNAUTHORIZED,
            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::NotImplemented(_) => StatusCode::NOT_IMPLEMENTED,
            Self::RateLimited => StatusCode::TOO_MANY_REQUESTS,
            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }

    pub fn kind(&self) -> &'static str {
        match self {
            Self::NotFound(_) => "not_found",
            Self::Conflict(_) => "conflict",
            Self::PreconditionRequired(_) => "precondition_required",
            Self::Forbidden(_) => "forbidden",
            Self::Unauthorized(_) => "unauthorized",
            Self::BadRequest(_) => "bad_request",
            Self::NotImplemented(_) => "not_implemented",
            Self::RateLimited => "rate_limited",
            Self::Internal(_) => "internal_error",
        }
    }
}

impl IntoResponse for ConsoleApiError {
    fn into_response(self) -> Response {
        let status = self.status();
        // Internal errors never leak the message to the client. Everything
        // the SPA can act on is in `kind`; the human-readable line is for
        // logs only.
        let display = if matches!(self, Self::Internal(_)) {
            "internal server error".to_string()
        } else {
            self.to_string()
        };

        if matches!(self, Self::Internal(ref msg) if !msg.is_empty()) {
            tracing::error!(error = %self, "xerj-console internal error");
        }

        // Emit the API-contract keys (`code`/`message`) alongside the legacy
        // (`type`/`reason`) pair. `code` uses the contract vocabulary
        // (`conflict|forbidden|not_found|bad_request`, …) via `kind`, so the
        // SPA can read the documented shape while older readers still find
        // `type`/`reason`. Purely additive — no existing consumer breaks.
        let body = json!({
            "error": {
                "code":    self.kind(),
                "message": display,
                "type":    self.kind(),
                "reason":  display,
            }
        });

        (status, Json(body)).into_response()
    }
}

// Common conversions so handlers can use `?` on engine and serde failures.

impl From<xerj_common::XerjError> for ConsoleApiError {
    fn from(e: xerj_common::XerjError) -> Self {
        // Map the few error categories the Xerj Console surface is likely to surface.
        let msg = e.to_string();
        let lower = msg.to_lowercase();
        if lower.contains("not found") {
            Self::NotFound(msg)
        } else if lower.contains("already exists") {
            Self::Conflict(msg)
        } else {
            Self::Internal(msg)
        }
    }
}

impl From<xerj_engine::EngineError> for ConsoleApiError {
    fn from(e: xerj_engine::EngineError) -> Self {
        Self::Internal(e.to_string())
    }
}

impl From<serde_json::Error> for ConsoleApiError {
    fn from(e: serde_json::Error) -> Self {
        Self::BadRequest(format!("invalid json: {e}"))
    }
}

impl From<std::io::Error> for ConsoleApiError {
    fn from(e: std::io::Error) -> Self {
        Self::Internal(format!("io: {e}"))
    }
}

//! Session-authorized Second-Brain graph reads (issue #936).
//!
//! The data plane's `/_graph/{brain}/ego|overview` routes authenticate an
//! engine *credential* (`Authorization` header — API key), and the
//! session-authenticated data-sources proxy deliberately refuses the reserved
//! `.xerj-memory-*` namespace (RC10 B1, pinned by
//! `tests/console_cannot_read_a_brain.rs`). Both decisions are right; together
//! they meant a signed-in console operator could not see any brain at all on
//! an auth-enabled engine — the default posture — while a share-link *guest*,
//! who holds a key, could.
//!
//! This module is the console's own read path for the graph. It authorizes
//! the **console session's role** and then reads the engine in-process (the
//! same `Engine` handle `data_sources` already uses), so no data-plane
//! credential is involved and the data plane's Authorization-header boundary
//! is untouched.
//!
//! ## The authorization rule
//!
//! Console roles `owner` and `admin` may read brains; `editor` and `viewer`
//! may not. Brains are node-local today: there is no per-tenant ownership
//! model anywhere yet, so the operator tier is the node's operator — the same
//! tier that may issue invites (`auth::magic::issue` gates `owner|admin`).
//! When a tenant model lands, this gate is where a per-user allow-list goes.
//!
//! No existence oracle, mirroring the discipline the search proxy set: a
//! role-refused read and a nonexistent brain return **byte-identical**
//! responses (same status, same body modulo the brain name the caller
//! supplied), so a session that may not read brains cannot enumerate them.
//! The `brains` listing is a flat role gate — 403 for a disallowed role —
//! which reveals no per-brain fact.
//!
//! ## Endpoints
//!
//! ```text
//! GET  /_xerj-console/api/v1/graph/brains              list brains (+ nodes_index)
//! GET  /_xerj-console/api/v1/graph/{brain}/ego         §4.3 neighborhood
//! GET  /_xerj-console/api/v1/graph/{brain}/overview    §4.4 brain stats
//! POST /_xerj-console/api/v1/graph/{brain}/edges/_search   ES _search on the
//!                                                     brain's edges index only
//! POST /_xerj-console/api/v1/graph/{brain}/nodes/_search   ES _search on ONE
//!                                                     of the brain's nodes
//!                                                     indices (meta-doc set)
//! ```
//!
//! The read endpoints re-derive their answers with the same engine machinery
//! the data plane uses — `xerj_engine::graph::Index::graph_expand` for the
//! traversal, `Index::search` for the bounded `ids` hydrations and the
//! overview aggregations — and answer in the same JSON contract
//! (`xerj-second-brain/1`) so the SPA consumes one shape whether it reads
//! through the console session (here) or a scoped key (data plane). The
//! implementation mirrors `xerj-api/src/graph_api.rs` handler-for-handler;
//! each mirrored block names its source. Deliberate differences:
//!
//! - the `ego?nodes_index=` override is refused (400): on the data plane it
//!   is authorized against the caller's grants, but a console session holds
//!   no grants, and silently ignoring it would change semantics between the
//!   two surfaces. Hydration always resolves through the brain's meta doc.
//! - the reserved namespace is reached only through these brain-scoped
//!   routes. The generic data-sources proxy still refuses it (B1 unchanged),
//!   and `link`/`unlink` have no console path — brains are written by the
//!   engine's own writers (`xerj brain`, agents with keys), read here.
//!
//! `/v1/metrics` for the Second Brain dashboard's "searches per index" tile
//! deliberately stays key-only: the metrics surface is an ops plane, and the
//! tile already renders the refusal honestly.

use std::collections::{HashMap, HashSet};

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use serde::Deserialize;
use serde_json::{json, Map, Value};

use crate::auth::sessions::AuthSession;
use crate::auth::store;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::response::ok;
use crate::state::ConsoleState;
use xerj_common::types::RESERVED_INDEX_PREFIX;
use xerj_engine::graph::{
    GraphDirection, GraphEdgeLite, GraphExpandRequest, GRAPH_HOPS_CAP_REASON,
};
use xerj_engine::Engine;

/// Contract version string, returned by every read endpoint. Byte-identical
/// to `xerj_api::graph_api::GRAPH_CONTRACT` — the console answers the same
/// contract the data plane does.
const GRAPH_CONTRACT: &str = "xerj-second-brain/1";

/// Reserved `_id` of the per-brain meta document (SECOND_BRAIN_SPEC §2.5).
pub(crate) const BRAIN_META_ID: &str = "__xerj-brain-meta";

/// Max returned edges for `ego` (same clamp as the data plane).
const MAX_EGO_LIMIT: usize = 1000;

/// Max seed ids accepted by `ego`'s `nodes=` param (same cap as the data
/// plane; excess seeds are dropped and counted in `not_shown.frontier_clipped`).
const EGO_SEEDS_CAP: usize = 64;

/// Max dangling node ids listed verbatim in `not_shown.dangling_ids`.
const MAX_DANGLING_LISTED: usize = 50;

/// Max brains listed by `GET /brains`; the excess is counted, never silently
/// dropped. Real nodes hold a handful of brains; the cap is a bound on
/// per-brain meta-doc reads, not a product limit.
const BRAINS_LISTED_CAP: usize = 256;

/// Edges index name for a brain (SECOND_BRAIN_SPEC §1) — same construction as
/// `xerj_api::authz::brain_edges_index`, which names the resource a
/// data-plane grant must hold.
pub(crate) fn edges_index(brain: &str) -> String {
    format!("{RESERVED_INDEX_PREFIX}{brain}-edges")
}

/// Default nodes index for a brain: the agent-memory namespace of the same
/// name. Autoindex brains override this via the §2.5 meta doc.
fn default_nodes_index(brain: &str) -> String {
    format!("{RESERVED_INDEX_PREFIX}{brain}")
}

/// Brain-name validation (SECOND_BRAIN_SPEC §1): byte-identical rules to
/// `xerj_api::graph_api::validate_brain` (lowercase/digit start, `[a-z0-9._-]`,
/// ≤200 chars, no `..`, `-edges` suffix reserved). A copy, not a shared fn,
/// matching the existing deliberate duplication (`memory_api`,
/// `xerj_autoindex::detect`) — the console crate does not depend on
/// `xerj-api`, on purpose (see `lib.rs`).
pub(crate) fn validate_brain(brain: &str) -> Result<(), String> {
    if brain.is_empty() {
        return Err("brain name must not be empty".into());
    }
    if brain.len() > 200 {
        return Err("brain name too long (max 200 chars)".into());
    }
    let first = brain.chars().next().unwrap();
    if !(first.is_ascii_lowercase() || first.is_ascii_digit()) {
        return Err("brain name must start with a lowercase letter or digit".into());
    }
    for c in brain.chars() {
        let ok = c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '_' | '-' | '.');
        if !ok {
            return Err(format!(
                "brain name contains illegal character '{c}' (allowed: a-z 0-9 _ - .)"
            ));
        }
    }
    if brain.contains("..") {
        return Err("brain name must not contain '..'".into());
    }
    if brain.ends_with("-edges") {
        return Err("namespace suffix '-edges' is reserved for graph edge indices".into());
    }
    Ok(())
}

/// May this console session read brains? The node's operator tier — the same
/// roles that may issue invites (`auth::magic::issue`). See module docs for
/// the rule and its no-tenant-model caveat. Public because
/// `tests/console_graph_read.rs` pins the tier boundary; not part of the
/// HTTP surface.
#[doc(hidden)]
pub fn may_read_brains(user: &store::User) -> bool {
    matches!(user.role.as_str(), "owner" | "admin")
}

/// The 404 every "you may not know about this brain" path returns — identical
/// for a role-refused read and a missing brain, modulo the caller-supplied
/// name. Mirrors the data plane's unknown-brain 404 shape (`graph_error`)
/// so the SPA sees one contract.
fn brain_not_found(brain: &str) -> Response {
    (
        StatusCode::NOT_FOUND,
        Json(json!({
            "error": {
                "type": "graph_error",
                "reason": format!("brain '{brain}' does not exist (no edges index)"),
            },
            "status": 404,
        })),
    )
        .into_response()
}

/// A uniform graph error response (same shape as the data plane's).
fn graph_error(status: StatusCode, reason: impl Into<String>) -> Response {
    (
        status,
        Json(json!({
            "error": { "type": "graph_error", "reason": reason.into() },
            "status": status.as_u16(),
        })),
    )
        .into_response()
}

/// Validate the brain name, then apply the role gate in the oracle-safe
/// order: a session that may not read brains gets exactly the response a
/// nonexistent brain produces. Malformed names 400 for every role — a
/// validation error leaks no existence fact. `Some(response)` = return it.
fn gate_brain(user: &store::User, brain: &str) -> Option<Response> {
    if let Err(reason) = validate_brain(brain) {
        return Some(graph_error(StatusCode::BAD_REQUEST, reason));
    }
    if !may_read_brains(user) {
        return Some(brain_not_found(brain));
    }
    None
}

/// Run one ES-shaped `_search` body against one index, in-process. The same
/// pattern `data_sources::search` uses (`parse_request` → `Index::search`);
/// errors surface as a Console 400/500 like every other console read.
async fn run_search(
    engine: &Engine,
    index: &str,
    body: &Value,
) -> ConsoleResult<xerj_query::executor::SearchResult> {
    let idx = engine.get_index(index)?;
    let req = xerj_query::parser::parse_request(body)
        .map_err(|e| ConsoleApiError::BadRequest(e.to_string()))?;
    idx.search(&req)
        .await
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))
}

/// One document by id, via the ids-prefilter fast path (the same read the
/// data plane's `get_doc` resolves to). `None` when absent.
async fn get_doc_source(engine: &Engine, index: &str, id: &str) -> ConsoleResult<Option<Value>> {
    let body = json!({ "query": { "ids": { "values": [id] } }, "size": 1 });
    let r = run_search(engine, index, &body).await?;
    Ok(r.hits.into_iter().next().map(|h| h.source))
}

/// The concrete names in a `nodes_index` value — `xerj brain` records a
/// multi-dataset folder as one comma-joined string (`"ax-mail,ax-pdfs"`).
/// Mirrors `graph_api::nodes_index_names`.
fn nodes_index_names(nodes_index: &str) -> impl Iterator<Item = &str> {
    nodes_index
        .split(',')
        .map(str::trim)
        .filter(|n| !n.is_empty())
}

/// Resolve the nodes index for a brain: the meta doc's `nodes_index`, else
/// the `.xerj-memory-{brain}` default. Mirrors `graph_api::resolve_nodes_index`
/// (explicit-param override excluded — see module docs).
pub(crate) async fn resolve_nodes_index(engine: &Engine, brain: &str, edges: &str) -> String {
    if let Some(src) = get_doc_source(engine, edges, BRAIN_META_ID)
        .await
        .ok()
        .flatten()
    {
        if let Some(ni) = src.get("nodes_index").and_then(Value::as_str) {
            if !ni.is_empty() {
                return ni.to_string();
            }
        }
    }
    default_nodes_index(brain)
}

/// Parse a query-string timestamp: decimal epoch-ms first, RFC3339 second
/// (mirrors `graph_api::parse_ms_str`).
fn parse_ms_str(s: &str) -> Option<i64> {
    if let Ok(n) = s.parse::<i64>() {
        return Some(n);
    }
    chrono::DateTime::parse_from_rfc3339(s)
        .ok()
        .map(|dt| dt.timestamp_millis())
}

/// Server "now" in epoch milliseconds.
fn now_ms() -> i64 {
    chrono::Utc::now().timestamp_millis()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /brains — discovery listing
// ─────────────────────────────────────────────────────────────────────────────

/// `GET /_xerj-console/api/v1/graph/brains` — every brain on this node, with
/// the `nodes_index` its meta doc records. Replaces the SPA's direct
/// `_cat/indices/.xerj-memory-*` walk + per-brain meta-doc reads, both of
/// which 401 for a session. Flat role gate: 403 for a role that may not read
/// brains (reveals no per-brain fact), listing for the operator tier.
pub async fn brains(
    State(state): State<ConsoleState>,
    sess: AuthSession,
) -> ConsoleResult<Response> {
    if !may_read_brains(&sess.user) {
        return Err(ConsoleApiError::Forbidden(format!(
            "the console role '{}' may not read brains",
            sess.user.role
        )));
    }

    // Brain = a reserved `.xerj-memory-{brain}-edges` index that exists.
    let mut names: Vec<String> = state
        .engine
        .index_name_list()
        .into_iter()
        .filter(|n| {
            n.starts_with(RESERVED_INDEX_PREFIX)
                && n.ends_with("-edges")
                && n.len() > RESERVED_INDEX_PREFIX.len() + "-edges".len()
        })
        .map(|n| n[RESERVED_INDEX_PREFIX.len()..n.len() - "-edges".len()].to_string())
        .filter(|b| validate_brain(b).is_ok())
        .collect();
    names.sort();

    let total = names.len();
    let clipped = total.saturating_sub(BRAINS_LISTED_CAP);
    names.truncate(BRAINS_LISTED_CAP);

    let mut brains: Vec<Value> = Vec::with_capacity(names.len());
    for brain in names {
        let edges = edges_index(&brain);
        let nodes_index = resolve_nodes_index(&state.engine, &brain, &edges).await;
        brains.push(json!({
            "name": brain,
            "nodes_index": nodes_index,
            "contract": GRAPH_CONTRACT,
        }));
    }

    Ok(ok(
        json!({
            "brains": brains,
            "total": total,
            "not_shown": { "brains_clipped": clipped as u64 },
        }),
        None,
    ))
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{brain}/ego — bounded neighborhood
// ─────────────────────────────────────────────────────────────────────────────

/// Query params for `GET /graph/{brain}/ego` — the data plane's §4.3 set,
/// minus the `nodes_index` override (refused here; see module docs).
#[derive(Debug, Default, Deserialize)]
pub struct EgoParams {
    #[serde(default)]
    pub node: Option<String>,
    #[serde(default)]
    pub nodes: Option<String>,
    #[serde(default)]
    pub hops: Option<u64>,
    #[serde(default)]
    pub direction: Option<String>,
    #[serde(default)]
    pub types: Option<String>,
    #[serde(default)]
    pub limit: Option<u64>,
    #[serde(default)]
    pub as_of: Option<String>,
    #[serde(default)]
    pub include_expired: Option<bool>,
    #[serde(default)]
    pub include_nodes: Option<bool>,
    #[serde(default)]
    pub nodes_index: Option<String>,
    #[serde(default)]
    pub include_evidence: Option<bool>,
}

/// `GET /_xerj-console/api/v1/graph/{brain}/ego` — the §4.3 neighborhood of
/// one node (or ≤64 via `nodes=`). Mirrors `graph_api::ego` step for step;
/// the authorization halves differ (console role gate instead of Principal
/// grants, in-process hydrations instead of composed ES-compat handlers).
pub async fn ego(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(brain): Path<String>,
    Query(params): Query<EgoParams>,
) -> Response {
    if let Some(resp) = gate_brain(&sess.user, &brain) {
        return resp;
    }
    if let Some(ni) = params.nodes_index.as_deref() {
        let _ = ni;
        return graph_error(
            StatusCode::BAD_REQUEST,
            "`nodes_index` is not supported on the console path: hydration resolves \
             through the brain's meta document",
        );
    }
    if params.node.is_some() && params.nodes.is_some() {
        return graph_error(
            StatusCode::BAD_REQUEST,
            "`node` and `nodes` are mutually exclusive — `nodes` is the multi-seed form",
        );
    }
    // Seed list: `node` is the 1-element case of `nodes`. Deduped preserving
    // order (the order is part of the `reachable` contract), then clamped to
    // EGO_SEEDS_CAP with the clip counted — never silent.
    let raw_seeds: Vec<String> = match (params.node.as_deref(), params.nodes.as_deref()) {
        (Some(n), None) if !n.is_empty() => vec![n.to_string()],
        (None, Some(ns)) => ns
            .split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(String::from)
            .collect(),
        _ => Vec::new(),
    };
    let mut seeds: Vec<String> = Vec::with_capacity(raw_seeds.len());
    {
        let mut seen: HashSet<&str> = HashSet::with_capacity(raw_seeds.len());
        for id in &raw_seeds {
            if seen.insert(id.as_str()) {
                seeds.push(id.clone());
            }
        }
    }
    if seeds.is_empty() {
        return graph_error(
            StatusCode::BAD_REQUEST,
            "`node` (or comma-separated `nodes`) is required: the node id(s) to expand from",
        );
    }
    let mut seeds_clipped = 0u64;
    if seeds.len() > EGO_SEEDS_CAP {
        seeds_clipped = (seeds.len() - EGO_SEEDS_CAP) as u64;
        seeds.truncate(EGO_SEEDS_CAP);
    }
    let hops = params.hops.unwrap_or(1);
    if hops == 0 || hops > 2 {
        return graph_error(StatusCode::BAD_REQUEST, GRAPH_HOPS_CAP_REASON);
    }
    let direction_str = params.direction.as_deref().unwrap_or("both");
    let direction = match direction_str {
        "out" => GraphDirection::Out,
        "in" => GraphDirection::In,
        "both" => GraphDirection::Both,
        other => {
            return graph_error(
                StatusCode::BAD_REQUEST,
                format!("`direction` must be 'out', 'in', or 'both' (got '{other}')"),
            );
        }
    };
    let types: Option<Vec<String>> = params.types.as_deref().map(|t| {
        t.split(',')
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(String::from)
            .collect()
    });
    let types = types.filter(|t| !t.is_empty());
    let limit = (params.limit.unwrap_or(100) as usize).clamp(1, MAX_EGO_LIMIT);
    let as_of = match params.as_of.as_deref() {
        None => now_ms(),
        Some(s) => match parse_ms_str(s) {
            Some(ms) => ms,
            None => {
                return graph_error(
                    StatusCode::BAD_REQUEST,
                    "`as_of` must be an epoch-ms number or an RFC3339 string",
                );
            }
        },
    };
    let include_expired = params.include_expired.unwrap_or(false);
    let include_nodes = params.include_nodes.unwrap_or(false);
    let include_evidence = params.include_evidence.unwrap_or(true);

    let edges = edges_index(&brain);
    let Ok(idx) = state.engine.get_index(&edges) else {
        return brain_not_found(&brain);
    };

    let req = GraphExpandRequest {
        frontier: seeds.clone(),
        hops: hops as u8,
        direction,
        types,
        as_of_ms: as_of,
        include_expired,
        max_result_edges: limit,
    };
    let result = match idx.graph_expand(&req) {
        Ok(r) => r,
        Err(e) => return graph_error(StatusCode::BAD_REQUEST, e.to_string()),
    };

    // Per-edge direction relative to the expansion (mirrors graph_api::ego):
    // an edge discovered at hop h is "out" iff its src was in hop h's
    // frontier; the hop-1 frontier is the seed set, the hop-2 frontier is
    // every endpoint hop 1 discovered.
    let frontier1: HashSet<&str> = seeds.iter().map(String::as_str).collect();
    let mut frontier2: HashSet<&str> = HashSet::new();
    for e in result.edges.iter().filter(|e| e.hop == 1) {
        for id in [e.src.as_str(), e.dst.as_str()] {
            if !frontier1.contains(id) {
                frontier2.insert(id);
            }
        }
    }
    let edge_direction = |e: &GraphEdgeLite| -> &'static str {
        let frontier = if e.hop == 1 { &frontier1 } else { &frontier2 };
        if frontier.contains(e.src.as_str()) {
            "out"
        } else {
            "in"
        }
    };

    // Post-traversal hydration (bounded ≤ limit ≤ 1000): ONE `ids` search on
    // the edges index for evidence/envelope fields — rides the ids-prefilter
    // fast path; the hop itself never touched `_source`.
    let mut hydrated: HashMap<String, Value> = HashMap::new();
    if include_evidence && !result.edges.is_empty() {
        let ids: Vec<&str> = result.edges.iter().map(|e| e.edge_id.as_str()).collect();
        let body = json!({
            "query": { "ids": { "values": ids } },
            "size": ids.len(),
            "_source": ["edge_id", "created_at", "detector", "confidence", "evidence", "expired_at"],
        });
        if let Ok(r) = run_search(&state.engine, &edges, &body).await {
            for h in r.hits {
                if let Some(id) = h.source.get("edge_id").and_then(Value::as_str) {
                    hydrated.insert(id.to_string(), h.source);
                }
            }
        }
    }

    // Node summaries (`include_nodes=true`): ONE `ids` search per concrete
    // nodes-index name for every reachable id. Ids that resolve nowhere are
    // DANGLING — the edge is kept, the honesty is counted, and up to 50 ids
    // are listed.
    let mut nodes_obj = Map::new();
    let mut dangling_nodes = 0u64;
    let mut dangling_ids: Vec<String> = Vec::new();
    if include_nodes {
        let nodes_index = resolve_nodes_index(&state.engine, &brain, &edges).await;
        let mut found: HashSet<String> = HashSet::new();
        for name in nodes_index_names(&nodes_index) {
            // A nodes index that does not exist (edges asserted through the
            // API alone) contributes nothing; every reachable id is then
            // reported dangling, never fabricated.
            if state.engine.get_index(name).is_err() {
                continue;
            }
            let ids: Vec<&str> = result.reachable.iter().map(String::as_str).collect();
            let body = json!({
                "query": { "ids": { "values": ids } },
                "size": ids.len(),
                "_source": ["title", "text", "body", "ax_path"],
            });
            let Ok(r) = run_search(&state.engine, name, &body).await else {
                continue;
            };
            for h in r.hits {
                let id = h.id.clone();
                let title = h
                    .source
                    .get("title")
                    .and_then(Value::as_str)
                    .map(Value::from)
                    .unwrap_or(Value::Null);
                let preview = h
                    .source
                    .get("text")
                    .and_then(Value::as_str)
                    .or_else(|| h.source.get("body").and_then(Value::as_str))
                    .map(|t| Value::from(t.chars().take(160).collect::<String>()))
                    .unwrap_or(Value::Null);
                // Truthful file label: the autoindex writer stamps `ax_path`
                // on every note; null when absent — never fabricated.
                let path = h
                    .source
                    .get("ax_path")
                    .and_then(Value::as_str)
                    .map(Value::from)
                    .unwrap_or(Value::Null);
                found.insert(id.clone());
                nodes_obj.entry(id).or_insert(json!({
                    "title": title,
                    "preview": preview,
                    "path": path,
                    "index": name,
                }));
            }
        }
        let mut dangling: Vec<&String> = result
            .reachable
            .iter()
            .filter(|id| !found.contains(*id))
            .collect();
        dangling.sort();
        dangling_nodes = dangling.len() as u64;
        dangling_ids = dangling
            .into_iter()
            .take(MAX_DANGLING_LISTED)
            .cloned()
            .collect();
    }

    // Edges in the §3.2 stable order (the engine already sorted), each
    // annotated with its expansion direction; `invalid_at` is JSON null when
    // unset (response-side null is fine — the omit-rule binds stored docs).
    let edges_json: Vec<Value> = result
        .edges
        .iter()
        .map(|e| {
            let mut obj = json!({
                "edge_id": e.edge_id,
                "src": e.src,
                "dst": e.dst,
                "type": e.edge_type,
                "weight": e.weight,
                "hop": e.hop,
                "direction": edge_direction(e),
                "valid_at": e.valid_at_ms,
                "invalid_at": e.invalid_at_ms.map(Value::from).unwrap_or(Value::Null),
            });
            if let Some(src) = hydrated.get(&e.edge_id) {
                for field in [
                    "created_at",
                    "detector",
                    "confidence",
                    "evidence",
                    "expired_at",
                ] {
                    if let Some(v) = src.get(field) {
                        obj[field] = v.clone();
                    }
                }
            }
            obj
        })
        .collect();

    // Neighbors: first-discovery order following the sorted edge list,
    // excluding the seed nodes; `via_edge` is the first sorted edge that
    // reached each one.
    let mut neighbors: Vec<Value> = Vec::new();
    let mut seen: HashSet<&str> = seeds.iter().map(String::as_str).collect();
    for e in &result.edges {
        for id in [e.src.as_str(), e.dst.as_str()] {
            if seen.insert(id) {
                neighbors.push(json!({ "id": id, "hop": e.hop, "via_edge": e.edge_id }));
            }
        }
    }

    // `seeds` echoes the ADMITTED seed list (post-dedupe, post-clamp) so the
    // caller can bookkeep exactly what was expanded; `node` stays on the
    // response whenever there is exactly one seed (the 1-element case keeps
    // its historical shape). Handler-clipped seeds fold into the same
    // `frontier_clipped` counter the engine uses — one honesty channel.
    let mut resp = json!({
        "brain": brain,
        "contract": GRAPH_CONTRACT,
        "seeds": seeds,
        "as_of": as_of,
        "hops": hops,
        "direction": direction_str,
        "edges": edges_json,
        "neighbors": neighbors,
        "not_shown": {
            "edges_clipped": result.stats.edges_clipped,
            "frontier_clipped": result.stats.frontier_clipped + seeds_clipped,
            "expired_excluded": result.stats.expired_excluded,
            "type_filtered": result.stats.type_filtered,
            "segments_without_columns": result.stats.segments_without_columns,
            "memtable_docs_scanned": result.stats.memtable_docs_scanned,
            "dangling_nodes": dangling_nodes,
            "dangling_ids": dangling_ids,
        }
    });
    if let [only] = resp["seeds"].as_array().map(Vec::as_slice).unwrap_or(&[]) {
        // §8.5 is a normative instance including key order: `node` sits
        // between `contract` and `seeds`, so rebuild in place rather than
        // appending (which would serialize `node` last).
        let only = only.clone();
        let old = std::mem::take(resp.as_object_mut().expect("ego response is an object"));
        let mut ordered = serde_json::Map::with_capacity(old.len() + 1);
        for (k, v) in old {
            if k == "seeds" {
                ordered.insert("node".to_string(), only.clone());
            }
            ordered.insert(k, v);
        }
        resp = Value::Object(ordered);
    }
    if include_nodes {
        resp["nodes"] = Value::Object(nodes_obj);
    }
    Json(resp).into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /{brain}/overview — brain-level stats
// ─────────────────────────────────────────────────────────────────────────────

/// Query params for `GET /graph/{brain}/overview` (§4.4; same as the data
/// plane's `OverviewParams`).
#[derive(Debug, Default, Deserialize)]
pub struct OverviewParams {
    #[serde(default)]
    pub as_of: Option<String>,
    #[serde(default)]
    pub top: Option<u64>,
    #[serde(default)]
    pub histogram_interval: Option<String>,
}

/// Terms-agg buckets → `[{"<key_name>": key, "<count_name>": doc_count}]`,
/// plus the agg's `sum_other_doc_count` (the not-listed tail, reported
/// in-band). Mirrors `graph_api::terms_list`.
fn terms_list(aggs: &Value, agg: &str, key_name: &str, count_name: &str) -> (Vec<Value>, u64) {
    let buckets = aggs
        .pointer(&format!("/{agg}/buckets"))
        .and_then(Value::as_array);
    let list = buckets
        .map(|bs| {
            bs.iter()
                .map(|b| {
                    json!({
                        key_name: b.get("key").cloned().unwrap_or(Value::Null),
                        count_name: b.get("doc_count").cloned().unwrap_or(json!(0)),
                    })
                })
                .collect()
        })
        .unwrap_or_default();
    let other = aggs
        .pointer(&format!("/{agg}/sum_other_doc_count"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    (list, other)
}

/// The honesty marker for the default embedder (§0 invariant 8): the built-in
/// embedder is LEXICAL feature-hashing — no surface may imply neural
/// semantics. Mirrors `graph_api::embedder_id`, read off the same engine
/// config the data plane's AppState holds.
fn embedder_id(engine: &Engine) -> String {
    let emb = &engine.config().embedding;
    match emb.mode.as_str() {
        "neural" => emb.neural_model.clone(),
        "proxy" if !emb.default_model.is_empty() => emb.default_model.clone(),
        "proxy" => "proxy".into(),
        "auto" if !emb.default_endpoint.is_empty() && !emb.default_model.is_empty() => {
            emb.default_model.clone()
        }
        "auto" if !emb.default_endpoint.is_empty() => "proxy".into(),
        _ => "lexical-feature-hash".into(),
    }
}

/// `GET /_xerj-console/api/v1/graph/{brain}/overview` — totals, live slice
/// (types/detectors/hubs), the created-over-time histogram, and the notes
/// total. Mirrors `graph_api::overview`; exactly three searches on the edges
/// index plus one size-0 count per concrete nodes-index name.
pub async fn overview(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(brain): Path<String>,
    Query(params): Query<OverviewParams>,
) -> Response {
    if let Some(resp) = gate_brain(&sess.user, &brain) {
        return resp;
    }
    let as_of = match params.as_of.as_deref() {
        None => now_ms(),
        Some(s) => match parse_ms_str(s) {
            Some(ms) => ms,
            None => {
                return graph_error(
                    StatusCode::BAD_REQUEST,
                    "`as_of` must be an epoch-ms number or an RFC3339 string",
                );
            }
        },
    };
    let top = (params.top.unwrap_or(10) as usize).clamp(1, 50);
    let interval = params.histogram_interval.as_deref().unwrap_or("day");
    if !matches!(interval, "day" | "hour") {
        return graph_error(
            StatusCode::BAD_REQUEST,
            "`histogram_interval` must be 'day' or 'hour'",
        );
    }

    let edges = edges_index(&brain);
    if state.engine.get_index(&edges).is_err() {
        // Same body the data plane returns for an unknown brain (the SPA
        // treats `exists: false` as a valid answer, not an error) — and the
        // same body a role-refused read got above.
        return (
            StatusCode::NOT_FOUND,
            Json(json!({ "brain": brain, "contract": GRAPH_CONTRACT, "exists": false })),
        )
            .into_response();
    }

    // 1. Totals: every edge ever asserted (`exists src` excludes the meta doc).
    let totals_body = json!({
        "query": { "exists": { "field": "src" } },
        "size": 0,
        "track_total_hits": true,
    });
    let totals = match run_search(&state.engine, &edges, &totals_body).await {
        Ok(v) => v,
        Err(e) => return graph_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    let total = totals.total.value;

    // 2. Live slice at as_of, with the type/detector/hub breakdowns.
    let live_body = json!({
        "query": {
            "bool": {
                "filter": [
                    { "exists": { "field": "src" } },
                    { "range": { "valid_at": { "lte": as_of } } }
                ],
                "must_not": [
                    { "range": { "invalid_at": { "lte": as_of } } }
                ]
            }
        },
        "size": 0,
        "track_total_hits": true,
        "aggs": {
            "by_type":     { "terms": { "field": "type",     "size": top } },
            "by_detector": { "terms": { "field": "detector", "size": top } },
            "top_src":     { "terms": { "field": "src",      "size": top } },
            "top_dst":     { "terms": { "field": "dst",      "size": top } },
        },
    });
    let live_resp = match run_search(&state.engine, &edges, &live_body).await {
        Ok(v) => v,
        Err(e) => return graph_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    let live = live_resp.total.value;
    let aggs = live_resp.aggs.clone().unwrap_or(Value::Null);
    let (types, types_other) = terms_list(&aggs, "by_type", "type", "live");
    let (detectors, detectors_other) = terms_list(&aggs, "by_detector", "detector", "live");
    let (hubs_out, hubs_out_other) = terms_list(&aggs, "top_src", "id", "live_edges");
    let (hubs_in, hubs_in_other) = terms_list(&aggs, "top_dst", "id", "live_edges");

    // 3. Created-over-time histogram (all asserted edges, not just live —
    // the timeline shows assertion activity, invalidation does not erase it).
    let timeline_body = json!({
        "query": { "exists": { "field": "src" } },
        "size": 0,
        "aggs": {
            "created": {
                "date_histogram": { "field": "created_at", "calendar_interval": interval }
            }
        },
    });
    let timeline = match run_search(&state.engine, &edges, &timeline_body).await {
        Ok(v) => v,
        Err(e) => return graph_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    let created_over_time: Vec<Value> = timeline
        .aggs
        .as_ref()
        .and_then(|a| a.pointer("/created/buckets"))
        .and_then(Value::as_array)
        .map(|bs| {
            bs.iter()
                .map(|b| {
                    json!({
                        "t": b.get("key").cloned().unwrap_or(Value::Null),
                        "count": b.get("doc_count").cloned().unwrap_or(json!(0)),
                    })
                })
                .collect()
        })
        .unwrap_or_default();

    let nodes_index = resolve_nodes_index(&state.engine, &brain, &edges).await;

    // 4. Notes total: one size-0 count per concrete nodes-index name. A brain
    // whose nodes index was never created (edges asserted through the API
    // alone) truthfully has 0 stored notes — reported as such, never
    // fabricated from edge endpoints.
    let mut nodes_total: u64 = 0;
    for name in nodes_index_names(&nodes_index) {
        if state.engine.get_index(name).is_err() {
            continue;
        }
        let count_body = json!({
            "query": { "match_all": {} },
            "size": 0,
            "track_total_hits": true,
        });
        if let Ok(r) = run_search(&state.engine, name, &count_body).await {
            nodes_total = nodes_total.saturating_add(r.total.value);
        }
    }

    Json(json!({
        "brain": brain,
        "contract": GRAPH_CONTRACT,
        "exists": true,
        "as_of": as_of,
        "nodes_index": nodes_index,
        "nodes": { "total": nodes_total },
        "embedder": embedder_id(&state.engine),
        "edges": {
            "total": total,
            "live": live,
            "invalidated": total.saturating_sub(live),
        },
        "types": types,
        "detectors": detectors,
        "hubs": { "out": hubs_out, "in": hubs_in },
        "created_over_time": created_over_time,
        "not_shown": {
            "types_not_listed": types_other,
            "detectors_not_listed": detectors_other,
            "hubs_out_not_listed": hubs_out_other,
            "hubs_in_not_listed": hubs_in_other,
        }
    }))
    .into_response()
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{brain}/edges/_search — the brain's edges index, ES wire shape
// ─────────────────────────────────────────────────────────────────────────────

/// Run an ES-shaped `_search` against one index and answer in the ES wire
/// shape (the mapping `data_sources::search` already established for
/// session-authenticated searches).
async fn es_wire_search(engine: &Engine, index: &str, body: &Value) -> Response {
    let result = match run_search(engine, index, body).await {
        Ok(r) => r,
        Err(e) => return e.into_response(),
    };
    let hits: Vec<Value> = result
        .hits
        .iter()
        .map(|h| {
            json!({
                "_index": index,
                "_id": h.id,
                "_score": h.score,
                "_source": h.source,
            })
        })
        .collect();
    Json(json!({
        "took": result.took_ms,
        "timed_out": result.timed_out,
        "hits": {
            "total": { "value": result.total.value, "relation": result.total.relation },
            "max_score": result.max_score,
            "hits": hits,
        },
        "aggregations": result.aggs,
    }))
    .into_response()
}

/// `POST /_xerj-console/api/v1/graph/{brain}/edges/_search` — an ES `_search`
/// against exactly this brain's edges index, for the dashboard's
/// recent-retirements and file-type-crossing reads (both used to go direct to
/// `/.xerj-memory-{brain}-edges/_search`, which 401s for a session). The
/// index is pinned server-side — the caller cannot name another index — so
/// this opens the reserved namespace only through the same role gate as every
/// other console graph read, and the generic data-sources proxy keeps
/// refusing it (RC10 B1 unchanged).
pub async fn edges_search(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(brain): Path<String>,
    Json(body): Json<Value>,
) -> Response {
    if let Some(resp) = gate_brain(&sess.user, &brain) {
        return resp;
    }
    if state.engine.get_index(&edges_index(&brain)).is_err() {
        return brain_not_found(&brain);
    }
    es_wire_search(&state.engine, &edges_index(&brain), &body).await
}

// ─────────────────────────────────────────────────────────────────────────────
// POST /{brain}/nodes/_search — one of the brain's nodes indices
// ─────────────────────────────────────────────────────────────────────────────

/// Query params for `POST /graph/{brain}/nodes/_search`.
#[derive(Debug, Default, Deserialize)]
pub struct NodesSearchParams {
    /// WHICH of the brain's nodes indices to search — mandatory when the
    /// meta doc records more than one (`xerj brain` over a multi-dataset
    /// folder writes `"ax-mail,ax-pdfs"`), ignored-correct when it records
    /// exactly one. Must be one of the brain's own names; anything else is
    /// the same 404 an unknown brain gets.
    #[serde(default)]
    pub index: Option<String>,
}

/// `POST /_xerj-console/api/v1/graph/{brain}/nodes/_search` — an ES `_search`
/// against ONE of the brain's nodes indices, resolved from the brain's own
/// meta doc (never caller-chosen): the dashboard's name hydration, notes
/// tally and FIND reads. Multi-index brains fan out client-side (the SPA
/// merges the per-index answers), so no multi-index merge semantics are
/// invented here.
pub async fn nodes_search(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(brain): Path<String>,
    Query(params): Query<NodesSearchParams>,
    Json(body): Json<Value>,
) -> Response {
    if let Some(resp) = gate_brain(&sess.user, &brain) {
        return resp;
    }
    let edges = edges_index(&brain);
    if state.engine.get_index(&edges).is_err() {
        return brain_not_found(&brain);
    }
    let nodes_index = resolve_nodes_index(&state.engine, &brain, &edges).await;
    let names: Vec<&str> = nodes_index_names(&nodes_index).collect();
    let target = match params.index.as_deref() {
        Some(want) => {
            if !names.contains(&want) {
                return brain_not_found(&brain);
            }
            want
        }
        None => match names.as_slice() {
            [only] => only,
            _ => {
                return graph_error(
                    StatusCode::BAD_REQUEST,
                    format!(
                        "this brain's nodes_index spans {} indices; pass ?index= with one of: {}",
                        names.len(),
                        names.join(", ")
                    ),
                );
            }
        },
    };
    if state.engine.get_index(target).is_err() {
        // A brain can hold edges before its nodes index is created — that is
        // an honest empty answer, not a missing brain.
        return es_wire_search_empty_ok();
    }
    es_wire_search(&state.engine, target, &body).await
}

/// An empty ES `_search` response for a nodes index that does not exist
/// (edges asserted through the API alone): zero hits, honestly.
fn es_wire_search_empty_ok() -> Response {
    Json(json!({
        "took": 0,
        "timed_out": false,
        "hits": {
            "total": { "value": 0, "relation": "eq" },
            "max_score": null,
            "hits": [],
        },
        "aggregations": {},
    }))
    .into_response()
}

//! System indices used by Xerj Console.
//!
//! All Xerj Console persistent state lives in hidden indices prefixed with `.xerj_`.
//! These are created on first boot if missing. Schema is intentionally
//! minimal — only the fields we actually filter or sort on get a typed
//! mapping; everything else is stored in `_source` and read back as-is.
//!
//! Hidden semantics: `_cat/indices` skips `.xerj_*` by default. Admin
//! tools that want them pass `?include_system=true`, or ES's
//! `?expand_wildcards=open,hidden`. A concrete name or a pattern that
//! starts with `.` still addresses them. `.xerj-memory-*` brains are not
//! system indices and stay in the default listing.

use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;

use crate::error::{ConsoleApiError, ConsoleResult};

// ─────────────────────────────────────────────────────────────────────────────
// Index names
// ─────────────────────────────────────────────────────────────────────────────

pub const USERS: &str = ".xerj_users";
pub const PASSKEYS: &str = ".xerj_passkeys";
pub const MAGIC_LINKS: &str = ".xerj_magic_links";
pub const SESSIONS: &str = ".xerj_sessions";
pub const API_TOKENS: &str = ".xerj_api_tokens";
pub const IDP_CONFIG: &str = ".xerj_idp_config";
pub const CLUSTER_STATE: &str = ".xerj_cluster_state";
pub const CONNECTIONS: &str = ".xerj_connections";
pub const PREFS: &str = ".xerj_prefs";
pub const DASHBOARDS: &str = ".xerj_dashboards";
pub const VIEWS: &str = ".xerj_views";
pub const ALERT_RULES: &str = ".xerj_alert_rules";
pub const ALERT_FIRES: &str = ".xerj_alert_fires";
pub const AUDIT: &str = ".xerj_audit";

/// Every system index this crate owns. Iterated by `ensure_all`.
pub const ALL: &[&str] = &[
    USERS,
    PASSKEYS,
    MAGIC_LINKS,
    SESSIONS,
    API_TOKENS,
    IDP_CONFIG,
    CLUSTER_STATE,
    CONNECTIONS,
    PREFS,
    DASHBOARDS,
    VIEWS,
    ALERT_RULES,
    ALERT_FIRES,
    AUDIT,
];

/// Predicate: is this index name owned by Xerj Console? Used by `_cat/indices`
/// to filter out system indices from the default listing.
pub fn is_system_index(name: &str) -> bool {
    name.starts_with(".xerj_")
}

// ─────────────────────────────────────────────────────────────────────────────
// Schemas
// ─────────────────────────────────────────────────────────────────────────────

/// Build the schema for a Xerj Console system index. Only fields we need to
/// filter / sort / aggregate on are typed; the rest of the document is
/// untyped JSON (stored in `_source`, read back as-is). This keeps the
/// mappings small and makes schema evolution a non-event for fields we
/// don't query on.
fn schema_for(index: &str) -> Schema {
    let mut s = Schema::empty();
    let add = |s: &mut Schema, name: &str, ty: FieldType| {
        let _ = s.add_field(FieldConfig::new(name, ty));
    };

    match index {
        USERS => {
            // Filter: status=active, role=admin, email=…; sort: created_at
            add(&mut s, "email", FieldType::Keyword);
            add(&mut s, "role", FieldType::Keyword);
            add(&mut s, "status", FieldType::Keyword);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "last_seen_at", FieldType::Date);
            add(&mut s, "display_name", FieldType::Keyword);
        }
        PASSKEYS => {
            // Lookup: by user_id (login), by credential_id (assertion verify)
            add(&mut s, "user_id", FieldType::Keyword);
            add(&mut s, "credential_id", FieldType::Keyword);
            add(&mut s, "name", FieldType::Keyword);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "last_used_at", FieldType::Date);
        }
        MAGIC_LINKS => {
            // Lookup: by token_hash (= _id, but typed for completeness)
            add(&mut s, "purpose", FieldType::Keyword);
            add(&mut s, "user_id", FieldType::Keyword);
            add(&mut s, "email", FieldType::Keyword);
            add(&mut s, "role", FieldType::Keyword);
            add(&mut s, "created_by", FieldType::Keyword);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "expires_at", FieldType::Date);
            add(&mut s, "used_at", FieldType::Date);
        }
        SESSIONS => {
            // Lookup: by session_id (= _id), reverse by user_id
            add(&mut s, "user_id", FieldType::Keyword);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "expires_at", FieldType::Date);
            add(&mut s, "last_seen_at", FieldType::Date);
            add(&mut s, "ip", FieldType::Keyword);
            add(&mut s, "ua", FieldType::Keyword);
            add(&mut s, "idp", FieldType::Keyword);
            add(&mut s, "revoked_at", FieldType::Date);
        }
        API_TOKENS => {
            // Lookup: by token_hash (= _id), reverse by user_id; expire by exp
            add(&mut s, "user_id", FieldType::Keyword);
            add(&mut s, "name", FieldType::Keyword);
            add(&mut s, "scopes", FieldType::Keyword);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "last_used_at", FieldType::Date);
            add(&mut s, "revoked_at", FieldType::Date);
        }
        IDP_CONFIG => {
            // One row per protocol; no filter fields needed beyond _id.
            add(&mut s, "updated_at", FieldType::Date);
            add(&mut s, "updated_by", FieldType::Keyword);
        }
        CLUSTER_STATE => {
            // One row per node. Filter on role/term/leader.
            add(&mut s, "role", FieldType::Keyword);
            add(&mut s, "term", FieldType::Long);
            add(&mut s, "commit_index", FieldType::Long);
            add(&mut s, "last_applied", FieldType::Long);
            add(&mut s, "updated_at", FieldType::Date);
        }
        CONNECTIONS => {
            add(&mut s, "name", FieldType::Keyword);
            add(&mut s, "kind", FieldType::Keyword);
            add(&mut s, "default", FieldType::Boolean);
            add(&mut s, "managed", FieldType::Boolean);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "created_by", FieldType::Keyword);
            add(&mut s, "etag", FieldType::Keyword);
        }
        PREFS => {
            // _id = user_id; payload is opaque key/value pairs.
            add(&mut s, "updated_at", FieldType::Date);
        }
        DASHBOARDS => {
            add(&mut s, "owner", FieldType::Keyword);
            add(&mut s, "org_id", FieldType::Keyword);
            add(&mut s, "visibility", FieldType::Keyword);
            // Provenance marker for seeded built-ins; typed so admin tooling
            // can filter managed vs user dashboards. Panel contents stay
            // untyped in `_source` (see the panel-schema doc in dashboards.rs).
            add(&mut s, "managed", FieldType::Boolean);
            add(&mut s, "name", FieldType::Keyword);
            add(&mut s, "section", FieldType::Keyword);
            add(&mut s, "group", FieldType::Keyword);
            add(&mut s, "version", FieldType::Long);
            add(&mut s, "etag", FieldType::Keyword);
            add(&mut s, "created_at", FieldType::Date);
            add(&mut s, "updated_at", FieldType::Date);
            add(&mut s, "deleted_at", FieldType::Date);
        }
        VIEWS => {
            add(&mut s, "owner", FieldType::Keyword);
            add(&mut s, "org_id", FieldType::Keyword);
            add(&mut s, "dashboard_id", FieldType::Keyword);
            add(&mut s, "name", FieldType::Keyword);
            add(&mut s, "updated_at", FieldType::Date);
        }
        ALERT_RULES => {
            // The rule body itself (`watch`, `type`, `etag`) is written by
            // the engine-side watcher (xerj-api `PUT /_watcher/watch/{id}`,
            // #1062) — this crate owns the INDEX and its typed filter
            // fields; xerj-api deliberately does not depend on this crate,
            // so both sides write/read through the shared Engine.
            add(&mut s, "owner", FieldType::Keyword);
            add(&mut s, "org_id", FieldType::Keyword);
            add(&mut s, "name", FieldType::Keyword);
            add(&mut s, "enabled", FieldType::Boolean);
            add(&mut s, "etag", FieldType::Keyword);
            add(&mut s, "updated_at", FieldType::Date);
        }
        ALERT_FIRES => {
            // Written by the watcher evaluator (#1062). `p` is the RAW
            // /_decide confidence (calibration is #1063), typed so the
            // console can filter/sort by it; `calibrated` lives in `_source`
            // (constant false today, so filtering on it is pointless).
            add(&mut s, "rule_id", FieldType::Keyword);
            add(&mut s, "level", FieldType::Keyword);
            add(&mut s, "fired_at", FieldType::Date);
            // The document whose decide vote fired this rule.
            add(&mut s, "doc_id", FieldType::Keyword);
            // Raw (uncalibrated, #1063) /_decide confidence of the vote.
            add(&mut s, "p", FieldType::Double);
            // Which decide tier answered: "history" | "local".
            add(&mut s, "tier", FieldType::Keyword);
        }
        AUDIT => {
            add(&mut s, "who", FieldType::Keyword);
            add(&mut s, "when", FieldType::Date);
            add(&mut s, "action", FieldType::Keyword);
            add(&mut s, "resource", FieldType::Keyword);
            add(&mut s, "resource_id", FieldType::Keyword);
            add(&mut s, "ip", FieldType::Keyword);
        }
        _ => {} // Unknown name: empty schema, dynamic mapping picks it up.
    }
    s
}

// ─────────────────────────────────────────────────────────────────────────────
// Auto-create
// ─────────────────────────────────────────────────────────────────────────────

/// Idempotently create every Xerj Console system index, applying the schema
/// from `schema_for`. Does nothing for indices that already exist.
///
/// Logs a single `info` line on first creation and returns the names
/// that were newly created (so the bootstrap module can detect "fresh
/// data dir" purely from the create-set being non-empty).
pub fn ensure_all(engine: &Engine) -> ConsoleResult<Vec<&'static str>> {
    let mut created = Vec::new();
    for name in ALL {
        if engine.get_index(name).is_ok() {
            continue;
        }
        let schema = schema_for(name);
        engine
            .create_index(name, schema)
            .map_err(|e| ConsoleApiError::Internal(format!("create {name}: {e}")))?;
        tracing::info!(index = *name, "created xerj-console system index");
        created.push(*name);
    }
    Ok(created)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_advertised_index_has_a_schema() {
        // schema_for never panics for any ALL entry, and every advertised
        // index either has typed fields or an explicit empty branch.
        for name in ALL {
            let _ = schema_for(name);
        }
    }

    #[test]
    fn is_system_index_predicate() {
        assert!(is_system_index(".xerj_users"));
        assert!(is_system_index(".xerj_dashboards"));
        assert!(!is_system_index("dashboards"));
        assert!(!is_system_index(".kibana"));
        assert!(!is_system_index(".audit"));
    }

    /// #1062: the alert indices are now READ and WRITTEN — rules by the
    /// engine-side watcher (`PUT /_watcher/watch/{id}` in xerj-api), fires
    /// by its evaluator. This pins the typed fields the evaluator writes so
    /// a schema edit there cannot drift from the writer silently.
    #[test]
    fn alert_indices_carry_the_watcher_fields() {
        let fires = schema_for(ALERT_FIRES);
        for field in ["rule_id", "level", "fired_at", "doc_id", "p", "tier"] {
            assert!(
                fires.fields.iter().any(|f| f.name == field),
                "{ALERT_FIRES} must type {field} for the watcher evaluator"
            );
        }
        let rules = schema_for(ALERT_RULES);
        for field in ["name", "enabled", "etag", "updated_at"] {
            assert!(
                rules.fields.iter().any(|f| f.name == field),
                "{ALERT_RULES} must type {field} for the watcher's rule documents"
            );
        }
    }
}

//! The knowledge surface — one payload that answers the three questions a
//! person has the moment `xerj brain` / `xerj autoindex` finishes:
//!
//! ```text
//! GET /_xerj-console/api/v1/knowledge
//! ```
//!
//! 1. **How large is the corpus?** — whole-corpus totals (datasets, records,
//!    files, source bytes summed over the catalog's dataset docs) plus the
//!    live per-index doc counts and on-disk store bytes the engine reports.
//! 2. **Which data is there?** — every catalog dataset with its full field
//!    list (type, semantic flag, null%, cardinality, example values), the
//!    formats and time span autoindex measured, the other user indices the
//!    catalog does not describe, and the cross-dataset relations autoindex
//!    actually inferred (key overlaps and time alignments — nothing is
//!    invented: a corpus with no correlations gets an empty list, not a
//!    guess).
//! 3. **What can I do with this now?** — a capability strip computed from
//!    real facts on the node (catalog present, brains present), each entry
//!    carrying the real console route, CLI command, or HTTP endpoint it
//!    names. No capability is listed that this tree does not ship. The
//!    `semantic` entry (#1099) is the node's own posture — the elected
//!    field, its companion vector field, dims, similarity and the
//!    embedder's own label, read from the live schema — and it NEVER
//!    carries a vector count: no engine stats surface exposes one, and a
//!    number the node cannot back must not reach the UI.
//!
//! This is the server side of the Console's Corpus home (the landing view).
//! It exists as ONE endpoint rather than a client-side fan-out because the
//! answer must be assertable: `tests/knowledge_surface.rs` pins that the
//! payload carries the catalog's own numbers (doc counts, field specs,
//! coverage), so the page cannot drift from what `xerj autoindex map`
//! prints for agents.
//!
//! ## Sources, all in-process
//!
//! - the `autoindex-catalog` index (`doc_kind: dataset` / `correlation`
//!   docs), read through the engine's own index APIs — the same choice
//!   `xerj-api::ask_api` documents ("no `xerj-autoindex` crate dependency"),
//!   so the constant below *mirrors* `xerj_autoindex::catalog::CATALOG_INDEX`
//!   rather than importing it. Keep them in sync.
//! - `Index::stats()` for live doc counts and `dir_size_bytes`-equivalent
//!   walks of each index's `data_dir()` for on-disk store bytes (the same
//!   computation `/_cat/indices` and `/_disk_usage` perform).
//! - the reserved `.xerj-memory-*-edges` brains, listed under the same
//!   operator-tier role gate as [`crate::graph::brains`] (a session that
//!   may not read brains gets an empty list, never a leak).
//!
//! Honesty stance: a missing catalog is the ordinary empty state (`catalog:
//! false`, empty datasets), not an error; every count is either the
//! catalog's own recorded number or the engine's live one, labelled by
//! which; nothing on this surface is sample or illustrative data.

use axum::{extract::State, response::Response};
use serde_json::{json, Map, Value};

use crate::auth::sessions::AuthSession;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::graph;
use crate::response::ok;
use crate::state::ConsoleState;
use xerj_common::types::RESERVED_INDEX_PREFIX;
use xerj_engine::Engine;

/// Mirror of `xerj_autoindex::catalog::CATALOG_INDEX` (see module docs for
/// why this crate does not depend on `xerj-autoindex`).
const CATALOG_INDEX: &str = "autoindex-catalog";

/// Max dataset docs read from the catalog (one per dataset; the corpus
/// prefix keeps ids distinct, real nodes hold a handful).
const MAX_DATASETS: usize = 200;

/// Max correlation docs read from the catalog.
const MAX_RELATIONS: usize = 200;

/// Example values kept per field (the catalog itself stores up to a handful;
/// three is what a card usefully shows).
const MAX_EXAMPLES: usize = 3;

/// Characters kept from one example value — the same bound the terminal map
/// applies (`catalog.rs#render_map` takes 40; the card also shows a type and
/// coverage, so it gets a little less).
const MAX_EXAMPLE_CHARS: usize = 40;

/// One ES-shaped `_search` against one index, in-process (the `graph` and
/// `data_sources` pattern). `Ok(None)` = the index does not exist.
async fn search_docs(
    engine: &Engine,
    index: &str,
    body: &Value,
) -> ConsoleResult<Option<Vec<Value>>> {
    let idx = match engine.get_index(index) {
        Ok(i) => i,
        Err(_) => return Ok(None),
    };
    let req = xerj_query::parser::parse_request(body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx
        .search(&req)
        .await
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    Ok(Some(r.hits.into_iter().map(|h| h.source).collect()))
}

/// Strip control characters (raw document values can carry NULs; they would
/// make the JSON payload read as binary). Same rule as the map renderer's
/// `clean`.
fn clean(s: &str) -> String {
    s.chars()
        .map(|c| {
            if c.is_control() && c != '\n' && c != '\t' {
                '\u{FFFD}'
            } else {
                c
            }
        })
        .collect()
}

fn u64_of(v: Option<&Value>) -> u64 {
    v.and_then(Value::as_u64).unwrap_or(0)
}

fn f64_of(v: Option<&Value>) -> f64 {
    v.and_then(Value::as_f64).unwrap_or(0.0)
}

fn str_of(v: Option<&Value>) -> Option<String> {
    v.and_then(Value::as_str)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

fn strings_of(v: Option<&Value>) -> Vec<String> {
    match v {
        Some(Value::Array(a)) => a
            .iter()
            .filter_map(Value::as_str)
            .map(clean)
            .filter(|s| !s.is_empty())
            .collect(),
        Some(Value::String(s)) => vec![clean(s)],
        _ => Vec::new(),
    }
}

/// `fields_json` on a dataset doc is a JSON *string* holding the array of
/// `xerj_autoindex::infer::FieldSpec` values (the frozen catalog mapping
/// declares it `text`). Parse it and project each spec down to what a card
/// renders: name, type, semantic flag, cardinality, null% and examples.
/// Unknown/missing keys degrade to honest defaults — a spec without a
/// `null_ratio` reads as "not measured" (`null`), never as 0%.
fn parse_fields(fields_json: Option<&Value>) -> Vec<Value> {
    let raw = match fields_json.and_then(Value::as_str) {
        Some(s) => s,
        None => return Vec::new(),
    };
    let specs = match serde_json::from_str::<Value>(raw) {
        Ok(Value::Array(a)) => a,
        _ => return Vec::new(),
    };
    let mut out = Vec::with_capacity(specs.len());
    for spec in specs {
        let obj = match spec.as_object() {
            Some(o) => o,
            None => continue,
        };
        let get = |k: &str| obj.get(k);
        let Some(name) = str_of(get("name")) else {
            continue;
        };
        let es_type = str_of(get("es_type")).unwrap_or_else(|| "object".into());
        let date_enc = str_of(get("date_enc"));
        let ty = match date_enc {
            Some(enc) => format!("{es_type} ({enc})"),
            None => es_type,
        };
        // FieldSpec.semantic is Option<String> (the embedder's label) — the
        // card only needs "is this the semantic body field".
        let semantic = get("semantic").and_then(Value::as_str).is_some();
        let card = get("cardinality_est").and_then(Value::as_u64);
        let overflow = get("cardinality_overflow")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let examples = strings_of(get("examples"));
        out.push(json!({
            "name": name,
            "type": ty,
            "semantic": semantic,
            // null when the spec carried no estimate — rendered as "—" not 0.
            "cardinality": card,
            "cardinality_overflow": overflow,
            "null_ratio": get("null_ratio").and_then(Value::as_f64),
            "coverage": get("coverage").and_then(Value::as_f64),
            // The spec's measured average value length — the corpus's content
            // lives in its LONG fields, so the SPA ranks the fields a person
            // reads first by coverage × avg_len (the dominant fields), not by
            // type. Not rendered as a claim; a ranking input only.
            "avg_len": get("avg_len").and_then(Value::as_f64).unwrap_or(0.0),
            "examples": examples
                .iter()
                .take(MAX_EXAMPLES)
                .map(|e| e.chars().take(MAX_EXAMPLE_CHARS).collect::<String>())
                .collect::<Vec<_>>(),
        }));
    }
    out
}

/// `sample_queries_json` is an array of JSON strings (each a ready-to-send
/// query body). Parse each; unparseable entries are skipped, not guessed.
fn parse_sample_queries(v: Option<&Value>) -> Vec<Value> {
    let arr = match v.and_then(Value::as_array) {
        Some(a) => a,
        None => return Vec::new(),
    };
    arr.iter()
        .filter_map(|q| {
            let s = q.as_str()?;
            serde_json::from_str::<Value>(s).ok()
        })
        .take(12)
        .collect()
}

/// A dataset doc → the card payload. `live` carries the engine's current
/// numbers for the index when it exists (None = the catalog describes an
/// index this engine no longer holds — shown, labelled).
fn dataset_card(doc: &Value, live: Option<(u64, u64)>) -> Value {
    let g = |k: &str| doc.get(k);
    json!({
        "index": str_of(g("index_name")).unwrap_or_default(),
        "slug": str_of(g("slug")),
        "formats": strings_of(g("formats")),
        "records": u64_of(g("record_count")),
        "junk": u64_of(g("junk_records")),
        "files": u64_of(g("file_count")),
        "bytes": u64_of(g("bytes")),
        "live_docs": live.map(|(docs, _)| docs),
        "store_bytes": live.map(|(_, bytes)| bytes),
        "time_field": str_of(g("time_field")),
        "time_min": str_of(g("time_min")),
        "time_max": str_of(g("time_max")),
        "semantic_field": str_of(g("semantic_field")),
        "fields": parse_fields(g("fields_json")),
        "sample_queries": parse_sample_queries(g("sample_queries_json")),
        "notes": strings_of(g("notes")),
        "run_id": str_of(g("run_id")),
    })
}

/// A correlation doc → one relation row. Only the two `corr_kind`s autoindex
/// writes are understood; anything else is dropped (never reinterpreted).
fn relation_row(doc: &Value) -> Option<Value> {
    let g = |k: &str| doc.get(k);
    let base = json!({
        "a_dataset": str_of(g("a_dataset")),
        "a_index": str_of(g("a_index")).unwrap_or_default(),
        "a_field": str_of(g("a_field")).unwrap_or_default(),
        "b_dataset": str_of(g("b_dataset")),
        "b_index": str_of(g("b_index")).unwrap_or_default(),
        "b_field": str_of(g("b_field")).unwrap_or_default(),
    });
    let mut obj = base.as_object()?.clone();
    match g("corr_kind").and_then(Value::as_str) {
        Some("key_overlap") => {
            obj.insert("kind".into(), json!("key_overlap"));
            obj.insert(
                "grade".into(),
                json!(str_of(g("grade")).unwrap_or_default()),
            );
            obj.insert("overlap".into(), json!(u64_of(g("overlap"))));
            obj.insert("containment".into(), json!(f64_of(g("containment"))));
            obj.insert(
                "confirmed_values".into(),
                json!(g("confirmed_values").and_then(Value::as_u64)),
            );
            obj.insert(
                "tested_values".into(),
                json!(g("tested_values").and_then(Value::as_u64)),
            );
            obj.insert("examples".into(), json!(strings_of(g("examples"))));
        }
        Some("time_alignment") => {
            obj.insert("kind".into(), json!("time_alignment"));
            obj.insert("range_overlap".into(), json!(f64_of(g("range_overlap"))));
            obj.insert("shared_buckets".into(), json!(u64_of(g("shared_buckets"))));
            obj.insert(
                "pearson_r".into(),
                json!(g("pearson_r").and_then(Value::as_f64)),
            );
            obj.insert(
                "activity_correlated".into(),
                json!(g("activity_correlated")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)),
            );
        }
        _ => return None,
    }
    Some(Value::Object(obj))
}

/// Recursive byte sum of a directory — the same computation `/_cat/indices`
/// and `/_disk_usage` perform for `store.size` (`es_compat::dir_size_bytes`,
/// mirrored here because it is private to `xerj-api`). Shared with the
/// data-sources facade so both surfaces report the same number.
pub(crate) fn dir_size_bytes(path: &std::path::Path) -> u64 {
    let mut total = 0u64;
    let Ok(read) = std::fs::read_dir(path) else {
        return 0;
    };
    for entry in read.flatten() {
        let Ok(meta) = std::fs::metadata(entry.path()) else {
            continue;
        };
        if meta.is_dir() {
            total += dir_size_bytes(&entry.path());
        } else {
            total += meta.len();
        }
    }
    total
}

/// Live `(doc_count, store_bytes)` for one index, when the engine holds it.
async fn live_stats(engine: &Engine, name: &str) -> Option<(u64, u64)> {
    let idx = engine.get_index(name).ok()?;
    let stats = idx.stats().await;
    Some((stats.doc_count, dir_size_bytes(idx.data_dir())))
}

/// The brains this node holds, under the same operator-tier gate as
/// `graph::brains` (see that module for the rule). Each row carries the
/// brain's link count — real edge docs only: the §2.5 meta doc
/// (`__xerj-brain-meta`) lives in the same index and is excluded, so the
/// number is what a person would count, not the index's raw doc count.
async fn brains_listing(engine: &Engine, may_read: bool) -> ConsoleResult<Vec<Value>> {
    if !may_read {
        return Ok(Vec::new());
    }
    let mut names: Vec<String> = engine
        .index_name_list()
        .into_iter()
        .filter(|n| {
            n.starts_with(RESERVED_INDEX_PREFIX)
                && n.ends_with("-edges")
                && n.len() > RESERVED_INDEX_PREFIX.len() + "-edges".len()
        })
        .map(|n| n[RESERVED_INDEX_PREFIX.len()..n.len() - "-edges".len()].to_string())
        .filter(|b| graph::validate_brain(b).is_ok())
        .collect();
    names.sort();
    let mut out = Vec::with_capacity(names.len());
    for brain in names {
        let edges = graph::edges_index(&brain);
        // Count edge documents, excluding the meta doc. `search_docs`
        // returns sources; a count query would be size-0, so count real
        // hits (an edge index holds one doc per link — bounded by the
        // graph contract, not by corpus size).
        let edge_docs = search_docs(
            engine,
            &edges,
            &json!({
                "query": { "bool": { "must_not": [{ "ids": { "values": [graph::BRAIN_META_ID] } }] } },
                "size": 10_000,
                "track_total_hits": true,
            }),
        )
        .await?;
        let links = edge_docs.map(|d| d.len() as u64).unwrap_or(0);
        let nodes_index = graph::resolve_nodes_index(engine, &brain, &edges).await;
        out.push(json!({
            "name": brain,
            "nodes_index": nodes_index,
            "links": links,
        }));
    }
    Ok(out)
}

/// The corpus's semantic posture, from the live engine — the facts behind
/// the `semantic` capability entry (#1099). Two honest shapes, nothing else:
///
/// - `Semantic` — the catalog elected a semantic field AND the index's live
///   schema carries its embedding config: dims/similarity/embedder exactly as
///   the query and ingest paths resolve them (`Index::semantic_field_facts`).
///   No vector count is included, because no engine surface exposes one — a
///   number the node cannot back must not reach the UI.
/// - `ElectedButMissing` — the catalog's last run elected a semantic field,
///   but this index has no embedding for it (it was rebuilt or mapped another
///   way): the entry then says plainly that there are no vectors on this node
///   for that field.
///
/// `None` (no catalog, or no dataset elected a semantic field) → no entry.
enum SemanticCapability {
    Semantic(xerj_engine::index::SemanticFieldFacts),
    ElectedButMissing { field: String, index: String },
}

/// Render the semantic capability's blurb from the facts above. Every phrase
/// is grounded: dims/similarity/embedder come from the live schema and the
/// embedder's own label; the lexical case says it is NOT neural and how to
/// get neural; the missing case says there is nothing to match.
fn semantic_blurb(sem: &SemanticCapability) -> String {
    match sem {
        SemanticCapability::Semantic(f) => {
            let dims = if f.dims_from_schema {
                format!("{}-D", f.dims)
            } else {
                format!("{}-D (the engine's built-in default)", f.dims)
            };
            if f.embedder_active {
                format!(
                    "Semantic and hybrid over `{}` → `{}`: {dims} · {} · {} — one vector per \
                     embedded document, embedded by that same backend at ingest.",
                    f.field, f.target_field, f.similarity, f.embedder
                )
            } else {
                format!(
                    "Semantic and hybrid over `{}` → `{}`: {dims} · {} · {} — one vector per \
                     embedded document. That embedder is NOT neural; start the node with \
                     `--embed-mode neural` (or `proxy` / `onnx-experimental`) for neural \
                     semantics.",
                    f.field, f.target_field, f.similarity, f.embedder
                )
            }
        }
        SemanticCapability::ElectedButMissing { field, index } => format!(
            "The catalog's last run elected `{field}` as the semantic field, but index \
             `{index}` carries no embedding for it on this node — there are no vectors to \
             match, and semantic/hybrid queries on that field are refused. Re-run \
             `xerj autoindex` over the source (or start with `--embed-mode neural`) to \
             give it one.",
        ),
    }
}

/// The capability strip. Every entry names a shipped surface — console route
/// (`href`), CLI command (`command`), or HTTP endpoint (`endpoint`) — and
/// availability is computed from facts on the node, not from a feature list.
fn capabilities(
    catalog: bool,
    brains: &[Value],
    semantic: Option<&SemanticCapability>,
) -> Vec<Value> {
    let mut caps = vec![json!({
        "id": "search",
        "title": "Search it",
        "blurb": "Seven query types — match, phrase, prefix, term, range, semantic, hybrid lexical+vector — with facets and a request preview.",
        "href": "#/discover",
        "kind": "console",
    })];
    // The semantic row is computed from the node's own schema and embedder
    // (#1099): dims, similarity and the embedder's label come from the engine,
    // and no vector count is ever claimed — the engine backs none.
    if let Some(sem) = semantic {
        caps.push(json!({
            "id": "semantic",
            "title": "Search it semantically",
            "blurb": semantic_blurb(sem),
            "href": "#/discover",
            "kind": "console",
        }));
    }
    caps.push(json!({
        "id": "read",
        "title": "Read the documents",
        "blurb": "Page through records with highlights and the per-record link list.",
        "href": "#/reader",
        "kind": "console",
    }));
    if let Some(brain) = brains.first() {
        let name = brain
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let links = brain.get("links").and_then(Value::as_u64).unwrap_or(0);
        caps.push(json!({
            "id": "graph",
            "title": "See the links between documents",
            "blurb": format!("Brain '{name}' holds {links} links over this corpus — the map, the evidence ledger, belief-time replay."),
            "href": format!("#/dashboards/second-brain?brain={name}"),
            "kind": "console",
        }));
    }
    if catalog {
        caps.push(json!({
            "id": "ask",
            "title": "Ask for a query, not a manual",
            "blurb": "POST /_ask — prompt in, validated query DSL out (it routes by this catalog; unresolved phrases are refused by name).",
            "endpoint": "POST /_ask",
            "kind": "http",
        }));
        caps.push(json!({
            "id": "map",
            "title": "Print the data map",
            "blurb": "The same field/coverage table this page shows, as markdown — for you or for an agent (MCP: xerj_map; `xerj mcp` exposes 20 tools).",
            "command": "xerj autoindex map",
            "kind": "cli",
        }));
    }
    caps.push(json!({
        "id": "decide",
        "title": "Decide with it",
        "blurb": "POST /_decide — the System One decide ladder (history vote by default; the local zero-shot head when the node arms it).",
        "endpoint": "POST /_decide",
        "kind": "http",
    }));
    caps.push(json!({
        "id": "watch",
        "title": "Keep it current",
        "blurb": "Stay resident and reindex what changes — this page follows on reload.",
        "command": "xerj autoindex <folder> --watch",
        "kind": "cli",
    }));
    caps.push(json!({
        "id": "share",
        "title": "Share one index",
        "blurb": "Read-only search over one index: a link, a passcode, an expiry.",
        "command": "xerj share <index>",
        "kind": "cli",
    }));
    caps
}

/// `GET /_xerj-console/api/v1/knowledge` — see the module docs.
pub async fn knowledge(
    State(state): State<ConsoleState>,
    sess: AuthSession,
) -> ConsoleResult<Response> {
    // 1. The catalog: dataset docs + correlation docs. A missing catalog
    //    index is the ordinary empty state, not an error.
    let dataset_docs = search_docs(
        &state.engine,
        CATALOG_INDEX,
        &json!({ "query": { "term": { "doc_kind": "dataset" } }, "size": MAX_DATASETS }),
    )
    .await?
    .unwrap_or_default();
    let corr_docs = search_docs(
        &state.engine,
        CATALOG_INDEX,
        &json!({ "query": { "term": { "doc_kind": "correlation" } }, "size": MAX_RELATIONS }),
    )
    .await?
    .unwrap_or_default();
    let catalog = !dataset_docs.is_empty();

    // 2. Dataset cards, largest first (the terminal map's order), each with
    //    the engine's live numbers for its index.
    let mut datasets: Vec<Value> = Vec::with_capacity(dataset_docs.len());
    for doc in &dataset_docs {
        if doc.get("doc_kind").and_then(Value::as_str) != Some("dataset") {
            continue;
        }
        let index = str_of(doc.get("index_name")).unwrap_or_default();
        let live = if index.is_empty() {
            None
        } else {
            live_stats(&state.engine, &index).await
        };
        datasets.push(dataset_card(doc, live));
    }
    datasets.sort_by(|a, b| {
        let rec = b["records"].as_u64().cmp(&a["records"].as_u64());
        rec.then_with(|| a["index"].as_str().cmp(&b["index"].as_str()))
    });

    // 3. Other user indices the catalog does not describe (an engine filled
    //    some other way must not read as "nothing indexed"). Same hidden-set
    //    rule as the data-sources facade.
    let catalog_indices: Vec<String> = datasets
        .iter()
        .filter_map(|d| d["index"].as_str().map(str::to_string))
        .collect();
    let mut others: Vec<Value> = Vec::new();
    let mut live_docs_total: u64 = 0;
    for name in state.engine.index_name_list() {
        if crate::data_sources::is_hidden_index(&name) || name == CATALOG_INDEX {
            continue;
        }
        let Some((docs, bytes)) = live_stats(&state.engine, &name).await else {
            continue;
        };
        live_docs_total += docs;
        if catalog_indices.contains(&name) {
            continue;
        }
        others.push(json!({ "index": name, "docs": docs, "store_bytes": bytes }));
    }
    others.sort_by(|a, b| a["index"].as_str().cmp(&b["index"].as_str()));

    // 4. Whole-corpus totals. `records`/`files`/`bytes` are the catalog's
    //    own last-run numbers (one run rewrites its dataset doc); `docs` is
    //    the engine's live count across every user index.
    let sum = |k: &str| {
        datasets
            .iter()
            .map(|d| d[k].as_u64().unwrap_or(0))
            .sum::<u64>()
    };
    let totals = json!({
        "datasets": datasets.len(),
        "records": sum("records"),
        "files": sum("files"),
        "bytes": sum("bytes"),
        "docs": live_docs_total,
        "relations": corr_docs.len(),
    });

    // 5. Relations — only what autoindex actually inferred.
    let mut relations: Vec<Value> = corr_docs.iter().filter_map(relation_row).collect();
    relations.sort_by(|a, b| {
        let rank = |v: &Value| match v["kind"].as_str() {
            Some("key_overlap") => v["overlap"].as_u64().unwrap_or(0),
            _ => 0,
        };
        rank(b).cmp(&rank(a))
    });

    // 6. The corpus's semantic posture — largest dataset first (the corpus's
    //    dominant one), from the LIVE index schema, never from a feature list.
    //    See `SemanticCapability` for the two honest shapes.
    let mut semantic: Option<SemanticCapability> = None;
    for d in &datasets {
        let Some(field) = str_of(d.get("semantic_field")) else {
            continue;
        };
        let index = d["index"].as_str().unwrap_or_default();
        let facts = match state.engine.get_index(index) {
            Ok(idx) => idx.semantic_field_facts(&field).await,
            Err(_) => None,
        };
        semantic = Some(match facts {
            Some(f) => SemanticCapability::Semantic(f),
            None => SemanticCapability::ElectedButMissing {
                field,
                index: index.to_string(),
            },
        });
        break;
    }

    // 7. Brains (operator tier) + the capability strip.
    let brains = brains_listing(&state.engine, graph::may_read_brains(&sess.user)).await?;
    let caps = capabilities(catalog, &brains, semantic.as_ref());

    let mut payload = Map::new();
    payload.insert("catalog".into(), json!(catalog));
    payload.insert("totals".into(), totals);
    payload.insert("datasets".into(), Value::Array(datasets));
    payload.insert("others".into(), Value::Array(others));
    payload.insert("relations".into(), Value::Array(relations));
    payload.insert("brains".into(), Value::Array(brains));
    payload.insert("capabilities".into(), Value::Array(caps));
    Ok(ok(Value::Object(payload), None))
}

//! Xerj Console backend API.
//!
//! Mounted at `/_xerj-console/api/v1/*` from the bundled xerj binary. Implements
//! the surface designed in `engine/docs/xerj-console-backend/API_DESIGN_v1.md` —
//! authentication (passkeys, magic links), cluster awareness, preferences,
//! dashboards, saved views, and the pluggable data-source layer.
//!
//! ## Module layout
//!
//! Boot + cluster info:
//! - [`error`], [`response`], [`time`] — primitives.
//! - [`state`] — `ConsoleState` shared into every handler.
//! - [`indices`] — `.xerj_*` system index names + schemas.
//! - [`bootstrap`] — first-launch detection, master-key persistence,
//!   magic-link printout.
//! - [`cluster`] — `/cluster/info`.
//!
//! Auth:
//! - [`auth`] — magic-link redeem, passkey enrol, login, sessions,
//!   audit, rate limits, `/me`, passkey CRUD.
//!
//! User-state (drop the localStorage hacks):
//! - [`prefs`] — `GET/PUT /prefs`.
//! - [`dashboards`] — full CRUD with If-Match etag concurrency.
//! - [`seed`] — first-launch materialisation of the built-in dashboards
//!   ([`seed::BUILTIN_DASHBOARD_COUNT`] of them) as editable backend data
//!   (idempotent, revisioned).
//! - [`views`] — saved views CRUD.
//! - [`data_sources`] — `/data-sources/connections` + descendants
//!   (read-only MVP backed by an auto-provisioned `built-in` adapter).
//! - [`graph`] — session-authorized Second-Brain graph reads (`/graph/*`,
//!   issue #936): brains discovery, `ego`, `overview`, brain-scoped edges and
//!   nodes searches.
//!
//! Coming after RC: `/auth/magic/issue`, `/auth/api-tokens`, `/users`
//! admin surface, `/cluster/raft*`, dashboards/views SSE streams, write
//! paths for /data-sources/connections (alongside encryption-at-rest
//! for connection secrets).
//!
//! ## Why this is a separate crate
//!
//! Xerj Console is its own product. xerj is one possible backend (the default
//! in v1.0); the crate must extract cleanly post-v1.0 to target ES,
//! OpenSearch, Prometheus, Postgres, or remote xerj.

#![allow(clippy::module_name_repetitions)]

pub mod auth;
pub mod bootstrap;
pub mod client_ip;
pub mod cluster;
pub mod dashboards;
pub mod data_sources;
pub mod error;
pub mod graph;
pub mod indices;
pub mod knowledge;
pub mod prefs;
pub mod response;
pub mod router;
pub mod seed;
pub mod spa;
pub mod state;
pub mod time;
