//! Per-user UI preferences — `GET /prefs` and `PUT /prefs`.
//!
//! Replaces every `localStorage["xerj.*"]` write the Console UX does
//! today: theme, default cluster, time range, mobile flag, search-box
//! contents.  We don't constrain the schema — the doc is whatever
//! key/value pairs the SPA asks us to round-trip — but `_id` is always
//! the user_id, so reads are by-id and idempotent.

use axum::{extract::State, response::Response, Json};
use serde_json::{json, Value};

use crate::auth::sessions::AuthSession;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::response::ok;
use crate::state::ConsoleState;
use crate::time::now_iso;

const FALLBACK_PREFS: &str = r#"{
  "theme": "dark",
  "time": "24H",
  "cluster": "LOCAL",
  "mobile": false
}"#;

pub async fn get(State(state): State<ConsoleState>, sess: AuthSession) -> ConsoleResult<Response> {
    let idx = state.engine.get_index(indices::PREFS)?;
    let body = json!({
        "query": { "ids": { "values": [&sess.user.id] } },
        "size": 1
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    let prefs = match r.hits.into_iter().next() {
        Some(h) => h.source,
        None => serde_json::from_str(FALLBACK_PREFS).expect("fallback prefs are valid json"),
    };
    Ok(ok(prefs, None))
}

pub async fn put(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Json(mut body): Json<Value>,
) -> ConsoleResult<Response> {
    if !body.is_object() {
        return Err(ConsoleApiError::BadRequest(
            "prefs body must be a JSON object".into(),
        ));
    }
    // Strip any client-set "updated_at" so the server is authoritative.
    body.as_object_mut()
        .unwrap()
        .insert("updated_at".into(), Value::String(now_iso()));

    let idx = state.engine.get_index(indices::PREFS)?;
    // One in-place upsert. delete-then-create used to drop the live prefs
    // row when the replacement write was refused.
    idx.index_document(Some(sess.user.id.clone()), body.clone())
        .await?;
    Ok(ok(body, None))
}

//! Response envelope used by every Xerj Console endpoint.
//!
//! Every successful response wraps the payload in
//!
//! ```json
//! { "data": <T>, "meta": { "etag": "…", "page": { "next": "…" }, "request_id": "…" } }
//! ```
//!
//! `meta` keys are all optional — the SPA reads them when it needs to
//! pin an `If-Match` etag, follow a cursor, or grep server logs by
//! request id.

use axum::{
    http::{HeaderMap, HeaderValue, StatusCode},
    response::{IntoResponse, Response},
    Json,
};
use serde::Serialize;
use serde_json::{json, Value};

#[derive(Debug, Clone, Default, Serialize)]
pub struct PageMeta {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub next: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub total: Option<u64>,
}

/// Build a JSON `{ data: …, meta: … }` envelope. Pass `meta = None` for
/// endpoints that don't need any meta keys; the field is omitted from the
/// body in that case so wire size stays small.
pub fn envelope<T: Serialize>(data: T, meta: Option<Value>) -> Value {
    match meta {
        Some(m) => json!({ "data": data, "meta": m }),
        None => json!({ "data": data }),
    }
}

/// Convenience: 200 OK with envelope and an optional `ETag` header.
///
/// The etag string is wrapped in `W/"…"` per RFC 7232 §2.3 — Xerj Console etags
/// are always weak (they reflect the resource version, not byte-level
/// equality, and therefore can't satisfy strong-comparison rules).
pub fn ok<T: Serialize>(data: T, etag: Option<&str>) -> Response {
    let mut headers = HeaderMap::new();
    if let Some(e) = etag {
        if let Ok(v) = HeaderValue::from_str(&format!("W/\"{e}\"")) {
            headers.insert(axum::http::header::ETAG, v);
        }
    }
    let body = if let Some(e) = etag {
        envelope(data, Some(json!({ "etag": format!("W/\"{e}\"") })))
    } else {
        envelope(data, None)
    };
    (StatusCode::OK, headers, Json(body)).into_response()
}

/// 201 Created with a `Location` header. Used by `POST` collection endpoints.
pub fn created<T: Serialize>(data: T, location: &str, etag: Option<&str>) -> Response {
    let mut headers = HeaderMap::new();
    if let Ok(v) = HeaderValue::from_str(location) {
        headers.insert(axum::http::header::LOCATION, v);
    }
    if let Some(e) = etag {
        if let Ok(v) = HeaderValue::from_str(&format!("W/\"{e}\"")) {
            headers.insert(axum::http::header::ETAG, v);
        }
    }
    let body = if let Some(e) = etag {
        envelope(data, Some(json!({ "etag": format!("W/\"{e}\"") })))
    } else {
        envelope(data, None)
    };
    (StatusCode::CREATED, headers, Json(body)).into_response()
}

/// 204 No Content — for `DELETE` and idempotent updates with no body.
pub fn no_content() -> Response {
    StatusCode::NO_CONTENT.into_response()
}

//! Public router — Xerj Console exposes a *complete* HTTP surface that any
//! container can mount as a peer to other axum routers.  In the v1.0
//! bundled binary, `xerj-server` brings up this router alongside the
//! engine's ES-compat / native routers via `Router::merge` so they
//! share one TCP listener.  When Xerj Console is extracted post-v1.0 it ships
//! with this same router as the binary's main entry point.
//!
//! Surface owned by this crate:
//!
//! ```text
//! /_xerj-console                 redirect → /_xerj-console/
//! /_xerj-console/                bundled SPA index.html
//! /_xerj-console/setup           bundled setup.html (magic-link claim)
//! /_xerj-console/login           bundled login.html (returning user)
//! /_xerj-console/{path*}         bundled SPA assets (CSS, JS, images, fonts)
//! /_xerj-console/api/v1/...      API endpoints (auth, prefs, dashboards, …)
//! ```
//!
//! ## Why one router, not two?
//!
//! Mounting the SPA assets and the API as one Router ensures Xerj Console
//! owns the full `/_xerj-console/*` namespace exclusively — no risk that the
//! engine's ES-compat router accidentally serves a 404 page over an
//! asset request, or vice versa.  The engine layer enforces its own
//! `Authorization: Bearer` policy on its routes only; this router
//! enforces its session-cookie policy on its routes only.

use axum::{
    routing::{delete, get, patch, post},
    Router,
};

use crate::{
    auth, cluster, dashboards, data_sources, graph, knowledge, prefs, spa, state::ConsoleState,
    views,
};

/// Build the full Xerj Console router. Mount at the root of an axum Router
/// (it owns the `/_xerj-console/*` prefix internally):
///
/// ```ignore
/// let merged = engine_router.merge(xerj_console_api::xerj_console_router(state));
/// axum::serve(listener, merged).await?;
/// ```
pub fn xerj_console_router(state: ConsoleState) -> Router {
    Router::new()
        // ── Bundled SPA assets (index, setup, login, css, js, fonts) ───────
        .route("/_xerj-console", get(spa::xerj_console_redirect))
        .route("/_xerj-console/", get(spa::xerj_console_index))
        .route("/_xerj-console/*rest", get(spa::xerj_console_asset))
        // ── API: cluster awareness ─────────────────────────────────────────
        .route("/_xerj-console/api/v1/cluster/info", get(cluster::info))
        // ── API: auth bootstrap (unauthenticated) ──────────────────────────
        .route(
            "/_xerj-console/api/v1/auth/magic/redeem",
            post(auth::magic::redeem),
        )
        // ── API: invite issue (owner/admin passkey session required) ───────
        // A bearer API token is 403. See `PasskeySession`.
        .route(
            "/_xerj-console/api/v1/auth/magic/issue",
            post(auth::magic::issue),
        )
        .route(
            "/_xerj-console/api/v1/auth/passkey/begin",
            post(auth::passkey::begin),
        )
        .route(
            "/_xerj-console/api/v1/auth/passkey/finish",
            post(auth::passkey::finish),
        )
        .route(
            "/_xerj-console/api/v1/auth/login/begin",
            post(auth::login::begin),
        )
        .route(
            "/_xerj-console/api/v1/auth/login/finish",
            post(auth::login::finish),
        )
        // ── API: session-protected ─────────────────────────────────────────
        // `PasskeySession` (bearer token → 403): logout, passkey delete,
        // api-token create and revoke. List routes and every data route
        // below accept a bearer token. See `auth::sessions::PasskeySession`.
        .route(
            "/_xerj-console/api/v1/auth/logout",
            post(auth::login::logout),
        )
        .route("/_xerj-console/api/v1/me", get(auth::me::me))
        .route(
            "/_xerj-console/api/v1/auth/passkeys",
            get(auth::me::list_passkeys),
        )
        .route(
            "/_xerj-console/api/v1/auth/passkeys/:id",
            delete(auth::me::delete_passkey),
        )
        .route(
            "/_xerj-console/api/v1/auth/api-tokens",
            get(auth::tokens::list).post(auth::tokens::create),
        )
        .route(
            "/_xerj-console/api/v1/auth/api-tokens/:id",
            delete(auth::tokens::revoke),
        )
        .route(
            "/_xerj-console/api/v1/prefs",
            get(prefs::get).put(prefs::put),
        )
        .route(
            "/_xerj-console/api/v1/dashboards",
            get(dashboards::list).post(dashboards::create),
        )
        // Static `_bulk` sits beside the `:id` param route below; matchit
        // gives the static segment priority, so a POST to `_bulk` never
        // lands on the `:id` handler.
        .route(
            "/_xerj-console/api/v1/dashboards/_bulk",
            post(dashboards::bulk),
        )
        .route(
            "/_xerj-console/api/v1/dashboards/:id",
            get(dashboards::get_one)
                .put(dashboards::replace)
                .delete(dashboards::delete),
        )
        .route(
            "/_xerj-console/api/v1/dashboards/:id",
            patch(dashboards::patch),
        )
        .route(
            "/_xerj-console/api/v1/views",
            get(views::list).post(views::create),
        )
        .route(
            "/_xerj-console/api/v1/views/:id",
            get(views::get_one).delete(views::delete),
        )
        .route(
            "/_xerj-console/api/v1/data-sources/connections",
            get(data_sources::list_connections),
        )
        .route(
            "/_xerj-console/api/v1/data-sources/connections/:id/indices",
            get(data_sources::list_indices),
        )
        .route(
            "/_xerj-console/api/v1/data-sources/connections/:id/indices/:name/fields",
            get(data_sources::list_fields),
        )
        .route(
            "/_xerj-console/api/v1/data-sources/connections/:id/indices/:name/search",
            post(data_sources::search),
        )
        // ── API: the knowledge surface (session-authorized) ─
        // One read that answers what a person asks the moment indexing
        // finishes: how large, which data, what can I do now. See
        // src/knowledge.rs.
        .route("/_xerj-console/api/v1/knowledge", get(knowledge::knowledge))
        // ── API: Second-Brain graph reads (session-authorized, issue #936) ─
        // The data plane's /_graph/* routes stay credential-only; these are
        // the console's own role-gated read paths over the same engine
        // traversals. See src/graph.rs for the authorization rule.
        .route("/_xerj-console/api/v1/graph/brains", get(graph::brains))
        .route("/_xerj-console/api/v1/graph/:brain/ego", get(graph::ego))
        .route(
            "/_xerj-console/api/v1/graph/:brain/overview",
            get(graph::overview),
        )
        .route(
            "/_xerj-console/api/v1/graph/:brain/edges/_search",
            post(graph::edges_search),
        )
        .route(
            "/_xerj-console/api/v1/graph/:brain/nodes/_search",
            post(graph::nodes_search),
        )
        .with_state(state)
}

