#[cfg(test)]
mod tests {
    use super::*;

    /// The dashboard ids the UI registry actually exports, read out of
    /// `xerj-ux/src/dashboards/registry.js` and the modules it pulls into its
    /// `all` array.
    ///
    /// Issue #211 named three sources for this one number that disagreed
    /// (13 / 14 / 15). Two of them are Rust and are now one constant; the third
    /// is this JavaScript registry, which is the *actual* definition of "a
    /// built-in dashboard" — `seed.rs` exists to materialise one row per entry.
    /// Comparing against the constant alone would have left the cross-language
    /// half of the drift unchecked, which is how it got to three numbers.
    fn registry_dashboard_ids() -> Vec<String> {
        let repo = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .ancestors()
            .nth(3)
            .expect("crate manifest dir must be <repo>/engine/crates/xerj-console-api")
            .to_path_buf();
        let dir = repo.join("xerj-ux/src/dashboards");
        let registry = std::fs::read_to_string(dir.join("registry.js")).unwrap_or_else(|e| {
            panic!(
                "cannot read {}: {e} — this test pins the seeded dashboards to the UI \
                 registry; if the registry moved, update this path rather than dropping \
                 the check",
                dir.join("registry.js").display()
            )
        });

        // `const all = [ … ];` is the exported dashboard set; everything else in
        // the file (SECTIONS, DASHBOARD_GROUPS, DEFAULT_GROUP) is taxonomy.
        let start = registry
            .find("const all = [")
            .expect("registry.js no longer declares `const all = [` — update this test");
        let end = registry[start..]
            .find("];")
            .expect("registry.js `const all = [` is never closed")
            + start;
        let symbols: Vec<&str> = registry[start..end]
            .lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .skip(1) // the `const all = [` line itself
            .flat_map(|l| l.split(','))
            .map(str::trim)
            .filter(|s| !s.is_empty() && s.chars().all(|c| c.is_ascii_alphanumeric()))
            .collect();

        // Each symbol is imported from a sibling module that declares its own id.
        let mut ids = Vec::new();
        for sym in &symbols {
            let import = registry
                .lines()
                .find(|l| {
                    l.trim_start().starts_with("import")
                        && l.contains(&format!("{{ {sym} }}"))
                        && l.contains("./")
                })
                .unwrap_or_else(|| {
                    panic!("registry.js lists `{sym}` in `all` but never imports it")
                });
            let rel = import
                .split("'")
                .nth(1)
                .unwrap_or_else(|| panic!("cannot read the import path for `{sym}`"));
            let module = dir.join(rel.trim_start_matches("./"));
            let src = std::fs::read_to_string(&module)
                .unwrap_or_else(|e| panic!("cannot read {}: {e}", module.display()));
            // Scan from the export, so a nested panel `id:` can never be
            // mistaken for the dashboard's own registry id.
            let export = format!("export const {sym} ");
            let body = src
                .find(&export)
                .map(|i| &src[i..])
                .unwrap_or_else(|| panic!("{} does not export `{sym}`", module.display()));
            let id = body
                .lines()
                .skip(1)
                .find_map(|l| {
                    l.trim()
                        .strip_prefix("id:")?
                        .trim()
                        .strip_prefix('\'')?
                        .split('\'')
                        .next()
                        .map(str::to_string)
                })
                .unwrap_or_else(|| panic!("{} declares no `id: '…'`", module.display()));
            ids.push(id);
        }
        ids
    }

    #[test]
    fn seeds_every_registry_dashboard() {
        let specs = seed_specs();
        assert_eq!(
            specs.len(),
            BUILTIN_DASHBOARD_COUNT,
            "seed_specs() and BUILTIN_DASHBOARD_COUNT disagree — update the \
             constant in this file, which is what the docs quote"
        );

        // …and both must equal what the UI registry exports.
        let registry: std::collections::BTreeSet<String> =
            registry_dashboard_ids().into_iter().collect();
        let seeded: std::collections::BTreeSet<String> = specs
            .iter()
            .map(|s| s.registry_id.to_string())
            .collect::<std::collections::BTreeSet<_>>();
        assert!(
            registry.len() > 5,
            "only {} ids parsed out of registry.js — the registry layout changed and \
             this check is reading nothing",
            registry.len()
        );
        let unseeded: Vec<_> = registry.difference(&seeded).collect();
        let phantom: Vec<_> = seeded.difference(&registry).collect();
        assert!(
            unseeded.is_empty() && phantom.is_empty(),
            "seed_specs() has drifted from xerj-ux/src/dashboards/registry.js.\n  \
             in the registry but never seeded: {unseeded:?}\n  \
             seeded but not in the registry: {phantom:?}\n  \
             Every registry entry gets one durable `default` row on first launch; \
             also bump BUILTIN_DASHBOARD_COUNT."
        );
        // Deterministic ids, all `default-` prefixed and unique.
        let mut ids: Vec<String> = specs
            .iter()
            .map(|s| format!("default-{}", s.registry_id))
            .collect();
        let n = ids.len();
        ids.sort();
        ids.dedup();
        assert_eq!(ids.len(), n, "seed ids must be unique");
        assert!(ids.iter().all(|id| id.starts_with("default-")));
        assert!(ids.contains(&"default-ai-overview".to_string()));
        assert!(ids.contains(&"default-second-brain".to_string()));
        assert!(ids.contains(&"default-settings".to_string()));
    }

    #[test]
    fn taxonomy_matches_registry() {
        let by = |rid: &str| -> (Option<String>, Option<String>) {
            let s = seed_specs();
            let d = s.iter().find(|d| d.registry_id == rid).unwrap();
            (d.section.map(String::from), d.group.map(String::from))
        };
        assert_eq!(
            by("ai-overview"),
            (Some("dashboards".into()), Some("ai".into()))
        );
        assert_eq!(
            by("second-brain"),
            (Some("dashboards".into()), Some("ai".into()))
        );
        assert_eq!(
            by("logs-overview"),
            (Some("dashboards".into()), Some("logs".into()))
        );
        assert_eq!(
            by("system"),
            (Some("dashboards".into()), Some("infra".into()))
        );
        assert_eq!(by("search-discover"), (Some("discover".into()), None));
        assert_eq!(by("alerts"), (Some("alerts".into()), None));
        assert_eq!(by("settings"), (Some("settings".into()), None));
    }

    #[test]
    fn panel_ids_unique_within_each_dashboard() {
        // registry.js reuses ids like `citations` / `roles`; the builder must
        // disambiguate so every panel id (and builtin key) is unique.
        for spec in seed_specs() {
            let panels = build_panels(spec.registry_id, &spec.panels);
            let mut ids: Vec<&str> = panels.iter().map(|p| p["id"].as_str().unwrap()).collect();
            let raw = ids.len();
            ids.sort_unstable();
            ids.dedup();
            assert_eq!(
                ids.len(),
                raw,
                "duplicate panel id in dashboard `{}`",
                spec.registry_id
            );
        }
        // Spot-check the known collisions were suffixed.
        let rag = build_panels("rag-quality", &spec_panels("rag-quality"));
        let rag_ids: Vec<&str> = rag.iter().map(|p| p["id"].as_str().unwrap()).collect();
        assert!(rag_ids.contains(&"citations"));
        assert!(rag_ids.contains(&"citations-2"));
    }

    #[test]
    fn builtin_key_tracks_panel_id() {
        for spec in seed_specs() {
            let panels = build_panels(spec.registry_id, &spec.panels);
            for panel in &panels {
                let id = panel["id"].as_str().unwrap();
                let builtin = panel["builtin"].as_str().unwrap();
                assert_eq!(builtin, format!("{}/{}", spec.registry_id, id));
                // Seed panels are mock-backed: query null, builtin present.
                assert!(panel["query"].is_null(), "seed panels carry no query");
            }
        }
    }

    #[test]
    fn layout_is_nonoverlapping_and_within_grid() {
        for spec in seed_specs() {
            let panels = build_panels(spec.registry_id, &spec.panels);
            let rects: Vec<(u32, u32, u32, u32)> = panels
                .iter()
                .map(|p| {
                    let l = &p["layout"];
                    (
                        l["x"].as_u64().unwrap() as u32,
                        l["y"].as_u64().unwrap() as u32,
                        l["w"].as_u64().unwrap() as u32,
                        l["h"].as_u64().unwrap() as u32,
                    )
                })
                .collect();
            for &(x, _, w, _) in &rects {
                assert!(
                    w >= 1 && x + w <= 12,
                    "panel out of 12-col grid in {}",
                    spec.registry_id
                );
            }
            for i in 0..rects.len() {
                for j in (i + 1)..rects.len() {
                    let (ax, ay, aw, ah) = rects[i];
                    let (bx, by, bw, bh) = rects[j];
                    let x_overlap = ax < bx + bw && bx < ax + aw;
                    let y_overlap = ay < by + bh && by < ay + ah;
                    assert!(
                        !(x_overlap && y_overlap),
                        "overlapping panels {i}/{j} in {}",
                        spec.registry_id
                    );
                }
            }
        }
    }

    #[test]
    fn seed_doc_deserializes_as_a_dashboard() {
        // The seeded JSON must round-trip through the CRUD struct, or list/get
        // would silently drop the defaults.
        for spec in seed_specs() {
            let doc = build_seed_doc(&spec, "2026-07-13T00:00:00.000Z");
            let dash: crate::dashboards::Dashboard =
                serde_json::from_value(doc).expect("seed doc must parse as Dashboard");
            assert_eq!(dash.owner, "system");
            assert_eq!(dash.visibility, "default");
            assert!(dash.managed);
            assert_eq!(dash.version, 1);
            assert!(!dash.panels.is_empty());
        }
    }

    #[test]
    fn seed_meta_is_not_a_dashboard() {
        // The bookkeeping row must fail Dashboard parse so list/get skip it.
        let meta = json!({ "kind": "seed_meta", "seed_revision": SEED_REVISION });
        assert!(serde_json::from_value::<crate::dashboards::Dashboard>(meta).is_err());
    }

    #[test]
    fn untouched_predicate() {
        assert!(is_untouched_default(
            &json!({ "version": 1, "deleted_at": Value::Null })
        ));
        assert!(!is_untouched_default(&json!({ "version": 2 })));
        assert!(!is_untouched_default(
            &json!({ "version": 1, "deleted_at": "2026-07-13T00:00:00.000Z" })
        ));
    }

    /// helper: fetch one dashboard's panel specs by registry id (test-only).
    fn spec_panels(rid: &str) -> Vec<PanelSpec> {
        seed_specs()
            .into_iter()
            .find(|s| s.registry_id == rid)
            .unwrap()
            .panels
    }
}

//! Xerj Console UX — embedded UI bundle served at `/_xerj-console`.
//!
//! `build.rs` walks the xerj-ux source tree at compile time and
//! generates `OUT_DIR/xerj_console_assets.rs` with a sorted slice of
//! `(url_path, bytes, content_type)` tuples. This module includes
//! that slice and exposes one Axum handler that does an O(log n)
//! lookup by path.
//!
//! ## URL shape
//!
//! ```text
//! GET /_xerj-console             → Console index.html (302 to /_xerj-console/)
//! GET /_xerj-console/            → Console index.html (200, text/html)
//! GET /_xerj-console/{path*}     → static asset by path, 404 if missing
//! GET /_xerj-console/share       → the share-link guest page (share/index.html)
//! ```
//!
//! Cache-Control is set to `public, max-age=300` for static assets;
//! the index.html gets `no-cache` so a deploy of a new binary surfaces
//! the new UI on next page load without ctrl-F5.
//!
//! ## Content-Security-Policy on the console page
//!
//! `index.html` is the page that shows other people's documents (the Reader)
//! and, in guest mode, holds a share's API key in `sessionStorage`. It is
//! served with [`CONSOLE_CSP`]: scripts from this origin only — no inline
//! script, no `eval` — and no connection to any other origin. The SPA builds
//! document-derived DOM without an HTML parser (`xerj-ux/src/ux/safe-dom.js`);
//! the policy is the second wall behind that one, so a missed escape in some
//! other view cannot become script execution or send a key off-origin.
//! `xerj-ux/test/browser/` loads the console under this exact string (it is
//! read out of this file) and fails on any violation report, so the policy
//! and the SPA cannot drift apart silently.
//!
//! `login.html` / `setup.html` carry an inline module script and show no
//! document data, so they are served without it.
//!
//! ## The share-link guest page
//!
//! `share/` is the one part of the bundle meant for someone who is **not** the
//! operator: the page a guest opens from a `xerj share` link, possibly through
//! a public tunnel. Like every other asset it is served without a session —
//! the guest has no credential until the page has exchanged a passcode for
//! one — so serving it makes nothing new reachable: it is three static files
//! that were already in the asset table. What it adds is a directory index
//! (`share` and `share/` both answer with `share/index.html`; the link the CLI
//! prints has no trailing slash) and a header set no other asset gets, see
//! [`GUEST_CSP`]. The page renders text from other people's documents, so the
//! policy is written to make a markup-injection bug inert rather than to rely
//! on there being none.
//!
//! ## Why not include_dir / rust-embed
//!
//! Both pull in proc-macro deps. The build.rs approach is ~80 LOC,
//! depends only on std, and produces a slice of `include_bytes!()`
//! references that the linker resolves directly.

use axum::{
    extract::Path,
    http::{header, StatusCode},
    response::{IntoResponse, Redirect, Response},
};

include!(concat!(env!("OUT_DIR"), "/xerj_console_assets.rs"));

/// The policy `index.html` is served with. One line, no line breaks: the
/// browser tests parse it out of this file verbatim.
///
/// * `script-src 'self'` — no inline script, no `eval`, nothing off-origin.
/// * `connect-src 'self'` — `fetch` reaches this engine and nothing else.
/// * `style-src … 'unsafe-inline'` — the shell sets `style=""` attributes on
///   the markup it builds; styles cannot run script or read storage.
/// * fonts come from Google Fonts, as `index.html` has always linked them.
/// * `img-src data: blob:` — the inline favicon and the PNG chart export.
/// * `frame-ancestors 'none'` — the console cannot be framed (clickjacking).
pub const CONSOLE_CSP: &str = "default-src 'none'; script-src 'self'; connect-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'; object-src 'none'";

/// Find an asset by its url path. Linear scan is fine for ~50 files;
/// the slice is sorted so we could binary-search if the bundle grows.
fn find_asset(path: &str) -> Option<&'static (&'static str, &'static [u8], &'static str)> {
    XERJ_CONSOLE_ASSETS.iter().find(|(p, _, _)| *p == path)
}

/// Everything under this asset directory is the share-link guest page.
const GUEST_DIR: &str = "share";

/// The guest page's Content-Security-Policy.
///
/// `default-src 'none'` and then only what the page uses, all same-origin: its
/// one script, one stylesheet, one icon, and `fetch` back to this node. No
/// inline script or style is permitted — so text that somehow became markup
/// could not run — and no third-party origin is reachable, so nothing a guest
/// reads can be beaconed elsewhere. `form-action 'none'` matters for a
/// specific failure: the passcode form has no `action`, and if the script
/// failed to load a native submit would put the passcode in the query string
/// of a GET, i.e. in the address bar and the access log. `frame-ancestors
/// 'none'` (with `X-Frame-Options` for browsers that predate it) keeps the
/// passcode prompt out of anyone else's frame.
pub const GUEST_CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; \
     img-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; \
     frame-ancestors 'none'";

/// Is `path` (an asset-table path) part of the guest page?
fn is_guest_asset(path: &str) -> bool {
    path.strip_prefix(GUEST_DIR)
        .is_some_and(|rest| rest.starts_with('/'))
}

/// Map a request path onto the asset table: the guest page's directory index,
/// with or without the trailing slash. Everything else is served as asked.
fn resolve_request_path(rest: &str) -> &str {
    match rest {
        "share" | "share/" => "share/index.html",
        other => other,
    }
}

/// Serve the Console's index.html for `/_xerj-console/`.
pub async fn xerj_console_index() -> impl IntoResponse {
    serve("index.html", true)
}

/// Serve a named asset under `/_xerj-console/{path*}`.
pub async fn xerj_console_asset(Path(rest): Path<String>) -> impl IntoResponse {
    // Empty rest path = same as `/_xerj-console/` — serve index.
    let path = if rest.is_empty() {
        "index.html"
    } else {
        resolve_request_path(&rest)
    };
    serve(path, false)
}

/// Bare `/_xerj-console` (no trailing slash) — relative `<script src="src/app.js">`
/// style tags resolve correctly only with the trailing slash, so redirect.
pub async fn xerj_console_redirect() -> impl IntoResponse {
    Redirect::permanent("/_xerj-console/")
}

fn serve(path: &str, no_cache: bool) -> Response {
    // Defence-in-depth: no .. components allowed in a relative URL,
    // even though the asset table is statically built and cannot
    // contain them.
    if path.split('/').any(|seg| seg == ".." || seg.is_empty()) {
        return (StatusCode::BAD_REQUEST, "invalid path").into_response();
    }
    let asset = match find_asset(path) {
        Some(a) => a,
        None => {
            // Fall back to `<name>.html` when the path has no
            // extension — gives us nice URLs like `/_xerj-console/setup` and
            // `/_xerj-console/login` without an explicit `.html`. We never
            // append `.html` to a path with a dot already in the last
            // segment so a typo on a real asset still 404s instead of
            // serving the wrong page.
            if !path.rsplit('/').next().unwrap_or("").contains('.') {
                let html = format!("{path}.html");
                if let Some(a) = find_asset(&html) {
                    return serve_asset(a, no_cache);
                }
            }
            return (
                StatusCode::NOT_FOUND,
                format!("xerj-console asset not found: {path}"),
            )
                .into_response();
        }
    };
    serve_asset(asset, no_cache)
}

fn serve_asset(asset: &(&'static str, &'static [u8], &'static str), no_cache: bool) -> Response {
    if is_guest_asset(asset.0) {
        return serve_guest_asset(asset);
    }
    // The console page is always revalidated — also when it is requested by
    // name (`/_xerj-console/index.html`) rather than as the directory index —
    // so a new binary's UI and policy arrive together.
    let is_console_page = asset.0 == "index.html";
    let cache = if no_cache || is_console_page {
        "no-cache"
    } else {
        "public, max-age=300"
    };
    let mut resp = (
        [
            (header::CONTENT_TYPE, asset.2),
            (header::CACHE_CONTROL, cache),
            // Every asset declares its real type (build.rs); never let a
            // browser second-guess it.
            (header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
        ],
        asset.1,
    )
        .into_response();
    if is_console_page {
        let h = resp.headers_mut();
        h.insert(
            header::CONTENT_SECURITY_POLICY,
            header::HeaderValue::from_static(CONSOLE_CSP),
        );
        // A guest's tab holds a key; never send this page's URL anywhere.
        h.insert(
            header::REFERRER_POLICY,
            header::HeaderValue::from_static("no-referrer"),
        );
    }
    resp
}

/// The guest page and its assets: never stored, never framed, never sniffed,
/// never a `Referer` source, and confined by [`GUEST_CSP`].
///
/// `no-store` rather than the console's five-minute cache: a guest may be on
/// a borrowed or shared browser, and a page fetched through a quick tunnel
/// must not be replayed from a cache after the tunnel — and its hostname — is
/// gone. The files are a few kilobytes; the cost is nothing.
fn serve_guest_asset(asset: &(&'static str, &'static [u8], &'static str)) -> Response {
    (
        [
            (header::CONTENT_TYPE, asset.2),
            (header::CACHE_CONTROL, "no-store, max-age=0"),
            (header::PRAGMA, "no-cache"),
            (header::CONTENT_SECURITY_POLICY, GUEST_CSP),
            (header::REFERRER_POLICY, "no-referrer"),
            (header::X_CONTENT_TYPE_OPTIONS, "nosniff"),
            (header::X_FRAME_OPTIONS, "DENY"),
            (
                header::HeaderName::from_static("cross-origin-opener-policy"),
                "same-origin",
            ),
            (
                header::HeaderName::from_static("cross-origin-resource-policy"),
                "same-origin",
            ),
            (
                header::HeaderName::from_static("permissions-policy"),
                "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
            ),
            (
                header::HeaderName::from_static("x-robots-tag"),
                "noindex, nofollow, noarchive",
            ),
        ],
        asset.1,
    )
        .into_response()
}

/// Number of bundled assets — exposed for the startup banner so
/// operators see at-a-glance whether the Console UX was bundled.
pub fn asset_count() -> usize {
    XERJ_CONSOLE_ASSETS.len()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A release tarball may omit `xerj-ux/` (build.rs then emits an empty
    /// table). With nothing bundled there is nothing to assert about.
    fn bundled() -> bool {
        asset_count() > 0
    }

    fn asset_text(path: &str) -> String {
        let asset = find_asset(path).unwrap_or_else(|| panic!("{path} is not bundled"));
        String::from_utf8(asset.1.to_vec()).expect("utf-8 asset")
    }

    fn header<'a>(resp: &'a Response, name: &str) -> &'a str {
        resp.headers()
            .get(name)
            .unwrap_or_else(|| panic!("missing header {name}"))
            .to_str()
            .unwrap()
    }

    /// Drop `/* … */` blocks and whole-line `//` comments, so a scan for a
    /// forbidden API does not trip over the comment that forbids it.
    fn strip_js_comments(src: &str) -> String {
        let mut out = String::with_capacity(src.len());
        let mut rest = src;
        while let Some(start) = rest.find("/*") {
            out.push_str(&rest[..start]);
            match rest[start..].find("*/") {
                Some(end) => rest = &rest[start + end + 2..],
                None => {
                    rest = "";
                    break;
                }
            }
        }
        out.push_str(rest);
        out.lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n")
    }

    #[test]
    fn the_guest_page_answers_with_and_without_the_trailing_slash() {
        if !bundled() {
            return;
        }
        // The CLI prints `/_xerj-console/share#<id>`; a mail client or a
        // person may add the slash. Both are the page, not a 404 or a 400.
        for rest in ["share", "share/", "share/index.html"] {
            let resp = serve(resolve_request_path(rest), false);
            assert_eq!(resp.status(), StatusCode::OK, "{rest}");
            assert_eq!(header(&resp, "content-type"), "text/html; charset=utf-8");
            assert_eq!(header(&resp, "content-security-policy"), GUEST_CSP);
        }
    }

    #[test]
    fn guest_assets_carry_the_strict_header_set() {
        if !bundled() {
            return;
        }
        for path in ["share/index.html", "share/share.js", "share/share.css"] {
            let resp = serve(path, false);
            assert_eq!(resp.status(), StatusCode::OK, "{path}");
            assert_eq!(header(&resp, "cache-control"), "no-store, max-age=0");
            assert_eq!(header(&resp, "referrer-policy"), "no-referrer");
            assert_eq!(header(&resp, "x-content-type-options"), "nosniff");
            assert_eq!(header(&resp, "x-frame-options"), "DENY");
            assert_eq!(header(&resp, "cross-origin-opener-policy"), "same-origin");
            let csp = header(&resp, "content-security-policy");
            for directive in [
                "default-src 'none'",
                "script-src 'self'",
                "style-src 'self'",
                "connect-src 'self'",
                "base-uri 'none'",
                "form-action 'none'",
                "frame-ancestors 'none'",
            ] {
                assert!(csp.contains(directive), "{path}: CSP lacks {directive}");
            }
            // Nothing that would let injected markup run or phone home.
            for forbidden in [
                "unsafe-inline",
                "unsafe-eval",
                "data:",
                "blob:",
                "*",
                "http",
            ] {
                assert!(!csp.contains(forbidden), "{path}: CSP contains {forbidden}");
            }
        }
    }

    /// The share work (#947) asserted the console page carried NO
    /// Content-Security-Policy, which was true when only `share/` had one.
    /// The Reader (#945) gives the console page its own [`CONSOLE_CSP`] — it
    /// renders other people's documents and, in guest mode, holds a share key
    /// in `sessionStorage`. So the console is deliberately no longer served
    /// "exactly as before"; what must still hold is that it gets the CONSOLE
    /// policy and not the guest one, and that no console asset is mistaken
    /// for a guest asset.
    #[test]
    fn the_console_page_carries_the_console_policy_not_the_guest_one() {
        if !bundled() {
            return;
        }
        let resp = serve("index.html", true);
        assert_eq!(resp.status(), StatusCode::OK);
        assert_eq!(header(&resp, "cache-control"), "no-cache");
        assert_eq!(header(&resp, "content-security-policy"), CONSOLE_CSP);
        assert_ne!(header(&resp, "content-security-policy"), GUEST_CSP);
        assert!(!is_guest_asset("index.html"));
        assert!(!is_guest_asset("shared.js"));
        assert!(!is_guest_asset("share"));
        assert!(is_guest_asset("share/share.js"));
    }

    #[test]
    fn the_directory_index_opens_nothing_else() {
        // Only the two spellings of the directory map anywhere.
        assert_eq!(resolve_request_path("share"), "share/index.html");
        assert_eq!(resolve_request_path("share/"), "share/index.html");
        for other in [
            "shared",
            "share/x",
            "share//",
            "api/v1/me",
            "src/",
            "share/..",
        ] {
            assert_eq!(resolve_request_path(other), other);
        }
        for bad in [
            "share/..",
            "share/../index.html",
            "share//share.js",
            "../share",
        ] {
            assert_eq!(serve(bad, false).status(), StatusCode::BAD_REQUEST, "{bad}");
        }
        for missing in ["share/nope.js", "shared", "share/share", "share/index.htm"] {
            assert_eq!(
                serve(missing, false).status(),
                StatusCode::NOT_FOUND,
                "{missing}"
            );
        }
        // The console's extensionless fallback (`setup` → `setup.html`) also
        // makes `share/index` the page. It is the same file, and it gets the
        // same policy — the guest header set is keyed on the asset served,
        // not on the spelling of the request.
        if bundled() {
            let resp = serve("share/index", false);
            assert_eq!(resp.status(), StatusCode::OK);
            assert_eq!(header(&resp, "content-security-policy"), GUEST_CSP);
        }
    }

    #[test]
    fn the_guest_page_has_no_inline_code_and_loads_nothing_from_elsewhere() {
        if !bundled() {
            return;
        }
        let html = asset_text("share/index.html");
        let lower = html.to_ascii_lowercase();
        // Every <script> is external; the CSP would refuse an inline one, and
        // this fails the build before a browser has to.
        for (at, _) in lower.match_indices("<script") {
            let tag_end = lower[at..].find('>').map(|e| at + e).unwrap_or(lower.len());
            assert!(
                lower[at..tag_end].contains("src="),
                "inline <script> at byte {at}"
            );
        }
        // (`javascript:` is matched as an attribute value: the <noscript> text
        // legitimately says "This page needs JavaScript: …".)
        for forbidden in [
            "<style",
            " style=",
            "=\"javascript:",
            "='javascript:",
            "=javascript:",
            "http://",
            "https://",
            "src=\"//",
            "href=\"//",
            "<iframe",
            "<object",
            "<embed",
            "<base",
        ] {
            assert!(
                !lower.contains(forbidden),
                "guest page contains {forbidden}"
            );
        }
        // No inline event handlers (` onclick=`, ` onerror=`, …).
        for (at, _) in lower.match_indices(" on") {
            let word: String = lower[at + 1..]
                .chars()
                .take_while(|c| c.is_ascii_alphabetic())
                .collect();
            let after = lower[at + 1 + word.len()..].chars().next();
            assert!(
                after != Some('='),
                "inline event handler `{word}=` in the guest page"
            );
        }
        // What the page tells a guest has to be true through a tunnel too
        // (review of PR #947): it used to say the browser "talks to their
        // machine" and that nothing goes "to a third party", on a page served
        // through Cloudflare. The Cloudflare notice ships hidden; share.js
        // shows it on a quick-tunnel hostname.
        for untrue in ["third party", "talks to their machine"] {
            assert!(!lower.contains(untrue), "guest page still says `{untrue}`");
        }
        for id in ["id=\"via-tunnel\" hidden", "id=\"room-via-tunnel\" hidden"] {
            assert!(html.contains(id), "guest page lacks {id}");
        }
        assert!(lower.contains("cloudflare carries the connection and can read"));
        // Every asset it names is one the bundle actually carries.
        for asset in ["share/share.js", "share/share.css", "share/icon.svg"] {
            assert!(find_asset(asset).is_some(), "{asset} is not bundled");
            assert!(
                html.contains(&format!("/_xerj-console/{asset}")),
                "page does not reference {asset}"
            );
        }
    }

    #[test]
    fn the_guest_script_never_parses_document_text_as_markup() {
        if !bundled() {
            return;
        }
        // Text from the shared index is attacker-controlled (it is other
        // people's email). The page may only ever place it as text.
        let code = strip_js_comments(&asset_text("share/share.js"));
        for sink in [
            "innerHTML",
            "outerHTML",
            "insertAdjacentHTML",
            "document.write",
            "DOMParser",
            "createContextualFragment",
            "srcdoc",
            "eval(",
            "new Function",
            "setTimeout('",
            "setTimeout(\"",
            "localStorage",
            "document.cookie",
        ] {
            assert!(!code.contains(sink), "share.js uses `{sink}`");
        }
        // The one storage contract the console's guest mode depends on.
        assert!(code.contains("'xerj.share'"));
        assert!(code.contains("sessionStorage.setItem(SHARE_KEY"));
        // The share id goes to the node in the claim BODY. A path built from
        // it is what put the id into access logs (review of PR #947).
        assert!(code.contains("'/_share/claim'"), "claim route");
        assert!(
            !code.contains("/_share/${"),
            "share.js builds a /_share path from a variable — the id must stay out of URLs"
        );
        assert!(code.contains("{ id: state.shareId, passcode }"));
        // A link pasted over another differs only in its fragment.
        assert!(code.contains("'hashchange'"));
        // The highlight delimiters are private-use code points, which are
        // invisible in an editor and in review: they must be written as
        // escapes, never as the characters themselves.
        assert!(
            !asset_text("share/share.js")
                .chars()
                .any(|c| ('\u{E000}'..='\u{F8FF}').contains(&c)),
            "share.js contains a raw private-use character; write it as \\uE000"
        );
        assert!(code.contains("'\\uE000'") && code.contains("'\\uE001'"));
        // No request leaves the origin: every fetch target is a path.
        assert!(!code.contains("http://") && !code.contains("https://"));
    }
}

//! Shared state for Xerj Console handlers.
//!
//! `ConsoleState` is `Clone` and lives behind `axum::extract::State`. The
//! types it wraps are individually responsible for their own concurrency
//! (the `Engine` is internally `Arc`-shared, the in-memory caches are
//! `Arc<DashMap<…>>` etc.). This struct is just the join.

use std::sync::Arc;

use dashmap::DashMap;
use xerj_common::net::TrustedProxies;
use xerj_engine::Engine;

use crate::client_ip::TrustedProxySource;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::time::now_epoch_ms;

/// Server start time, in epoch ms. Used by `/cluster/info` so the SPA can
/// show "node up since …" without a separate /uptime fetch.
#[derive(Debug, Clone, Copy)]
pub struct StartedAt(pub i64);

/// In-memory record of a WebAuthn challenge that the server issued but
/// the client has not yet completed. Indexed by an opaque challenge id
/// (random 32-byte url-safe base64) that the SPA echoes back on
/// `…/finish`. Auto-expires after 5 minutes; entries past their TTL
/// are pruned on every insert.
#[derive(Debug, Clone)]
pub struct PendingChallenge {
    pub kind: ChallengeKind,
    pub created_at_ms: i64,
}

#[derive(Debug, Clone)]
pub enum ChallengeKind {
    /// `POST /auth/passkey/begin` — enrolling a new credential. We hold
    /// the registration state plus the user_id we're enrolling for so
    /// `…/finish` knows where to attach the credential.
    PasskeyEnroll {
        user_id: String,
        state: webauthn_rs::prelude::PasskeyRegistration,
    },
    /// `POST /auth/login/begin` — proving an existing credential.
    /// The `email` is null when we returned a fake challenge for an
    /// unknown email (anti-enumeration).
    Login {
        email: Option<String>,
        state: webauthn_rs::prelude::PasskeyAuthentication,
    },
}

/// In-memory record of an enrollment session — issued when a user
/// redeems a magic link, consumed when they finish passkey enrollment.
/// Lives only in RAM (max 30 minutes), not persisted; if the server
/// restarts mid-bootstrap, the user re-redeems with a fresh link.
#[derive(Debug, Clone)]
pub struct EnrollmentSession {
    pub session_id: String,
    pub email: String,
    pub user_id: String,
    pub role: String,
    pub created_at_ms: i64,
    pub expires_at_ms: i64,
}

/// Coarse "is this node part of a RAFT cluster?" flag, set at startup
/// from `cfg.cluster.enabled` and never mutated. Phase 4 swaps this for
/// a live handle to the cluster runner so `/cluster/raft` can stream
/// real RAFT state; in phase 1 we only need the standalone-vs-raft
/// branch in `/cluster/info`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClusterMode {
    Standalone,
    Raft,
}

/// WebAuthn Relying Party configuration. `rp_id` is the effective domain
/// (e.g. `"localhost"` for dev, `"xerj-console.example.com"` for prod) and
/// `rp_origin` is the URL the SPA was loaded from (e.g.
/// `"http://localhost:9200"`). Both must match between enrolment and
/// login or the browser refuses the assertion.
#[derive(Debug, Clone)]
pub struct RpConfig {
    pub rp_id: String,
    pub rp_origin: String,
    pub rp_name: String,
}

impl Default for RpConfig {
    fn default() -> Self {
        Self {
            rp_id: "localhost".to_string(),
            rp_origin: "http://localhost:9200".to_string(),
            rp_name: default_rp_name(),
        }
    }
}

fn default_rp_name() -> String {
    "Xerj Console".to_string()
}

impl RpConfig {
    /// Derive the relying party from the URL the console is actually
    /// served on (in `xerj-server` that is the bound address plus the
    /// *bound* ES-compat port, so ephemeral ports are already resolved —
    /// issue #469).
    ///
    /// * Loopback and unspecified hosts (`localhost`, `127.0.0.1`, `::1`,
    ///   `0.0.0.0`, `::`) all map to `rp_id = "localhost"` with the origin
    ///   rewritten to `<scheme>://localhost:<port>`. Browsers refuse an
    ///   IP-literal WebAuthn origin outright, so keeping the bind address
    ///   in the origin makes enrolment impossible on any port; and keeping
    ///   `rp_id` on `localhost` preserves credentials enrolled against the
    ///   historical hard-coded default (#935).
    /// * A named host is used verbatim: `rp_id` = host, origin = the URL.
    /// * A non-loopback IP literal is refused: a WebAuthn RP id must be a
    ///   registrable domain, so there is no honest configuration for
    ///   `http://192.168.0.5:9200`. Serve the console behind a named host
    ///   (reverse proxy) or bind loopback to use passkeys.
    pub fn from_bind_url(bind_url: &str) -> ConsoleResult<Self> {
        let url = webauthn_rs::prelude::Url::parse(bind_url).map_err(|e| {
            ConsoleApiError::Internal(format!("console bind url `{bind_url}`: {e}"))
        })?;
        let Some(host) = url.host_str().map(|h| h.to_string()) else {
            return Err(ConsoleApiError::Internal(format!(
                "console bind url `{bind_url}` has no host"
            )));
        };
        // `Url::host_str` keeps the brackets on an IPv6 literal
        // (`http://[::1]:9550` → `"[::1]"`); a domain name can never contain
        // one, so trimming them restores the parseable spelling.
        let host = host
            .trim_start_matches('[')
            .trim_end_matches(']')
            .to_string();
        let port = url.port().map(|p| format!(":{p}")).unwrap_or_default();
        if bind_host_is_local(&host) {
            Ok(Self {
                rp_id: "localhost".to_string(),
                rp_origin: format!("{}://localhost{port}", url.scheme()),
                rp_name: default_rp_name(),
            })
        } else if host.parse::<std::net::IpAddr>().is_ok() {
            Err(ConsoleApiError::Internal(format!(
                "cannot derive a WebAuthn relying party from `{bind_url}`: a relying-party id \
                 must be a domain, not the IP literal `{host}` — serve the console behind a \
                 named host or bind loopback to use passkeys"
            )))
        } else {
            Ok(Self {
                rp_id: host.clone(),
                rp_origin: format!("{}://{host}{port}", url.scheme()),
                rp_name: default_rp_name(),
            })
        }
    }
}

/// Is this URL host the machine itself, in any of its spellings?
fn bind_host_is_local(host: &str) -> bool {
    match host.parse::<std::net::IpAddr>() {
        Ok(ip) => ip.is_loopback() || ip.is_unspecified(),
        Err(_) => host.eq_ignore_ascii_case("localhost"),
    }
}

/// The host a human should be sent to for the console, given the address
/// the node bound (`server.bind_address`).
///
/// Every loopback or unspecified bind becomes `localhost`: browsers refuse
/// an IP-literal WebAuthn origin, so a first-launch link printed as
/// `http://127.0.0.1:<port>/…` can never complete passkey enrolment even
/// when the relying party is derived correctly (#935). Any other address
/// keeps its spelling, IPv6 bracketed for a URL (`http://[fd00::1]:…`).
pub fn public_bind_host(bind_address: &str) -> String {
    let raw = bind_address.trim();
    match raw.parse::<std::net::IpAddr>() {
        Ok(ip) if ip.is_loopback() || ip.is_unspecified() => "localhost".to_string(),
        Ok(std::net::IpAddr::V6(v6)) => format!("[{v6}]"),
        Ok(_) => raw.to_string(),
        // `localhost` itself, and any name that slips past the server's
        // IP-literal bind guard, keeps its spelling.
        Err(_) => raw.to_string(),
    }
}

/// Top-level state object shared into every Xerj Console handler.
#[derive(Clone)]
pub struct ConsoleState {
    pub engine: Engine,
    pub started_at: StartedAt,
    pub node_id: Arc<String>,
    pub cluster_mode: ClusterMode,
    pub rp: Arc<RpConfig>,

    /// Live WebAuthn challenges. `pending_challenges[challenge_b64u]
    /// = PendingChallenge`. Capped at 1024 entries; stale entries are
    /// pruned on every insert via `prune_pending_challenges`.
    pub pending_challenges: Arc<DashMap<String, PendingChallenge>>,

    /// Live enrollment sessions (post-magic-link, pre-passkey-finish).
    pub enrollment_sessions: Arc<DashMap<String, EnrollmentSession>>,

    /// Per-IP rate-limit counters for auth endpoints. Reset every minute
    /// on first hit after the window. Map key is `"<ip>:<endpoint>"`.
    pub auth_rate_counters: Arc<DashMap<String, RateWindow>>,

    /// HMAC key used to sign session cookies (derived from the
    /// `data_dir/.xerj_master_key` file or the `XERJ_CONSOLE_KEY`
    /// env var; generated on first start and persisted).
    pub master_key: Arc<[u8; 32]>,

    /// Serializes magic-link redemption (#76 S5-3). The single-use check and
    /// the `mark_magic_link_used` commit are separated by several awaits and
    /// the store's mark-used is itself get→delete→create, so two concurrent
    /// redeems of one token could both pass the used-check and both mint a
    /// session. Holding this gate across the whole check→consume makes the
    /// transition atomic. Redemptions are rare (enrollment/recovery), so a
    /// single gate is cheaper than a per-token map and needs no cleanup.
    pub redeem_gate: Arc<tokio::sync::Mutex<()>>,

    /// Reverse proxies whose `X-Forwarded-For` / `X-Real-IP` we believe
    /// (#76 S5-4). Empty by default — an unconfigured node derives client
    /// identity from the socket peer only, so the auth rate limiter cannot be
    /// side-stepped with a forged header. Populated from
    /// `server.trusted_proxies` by `xerj-server` at startup.
    pub trusted_proxies: Arc<TrustedProxies>,
}

#[derive(Debug, Clone, Copy)]
pub struct RateWindow {
    pub count: u32,
    pub window_start_ms: i64,
}

impl ConsoleState {
    pub fn new(
        engine: Engine,
        node_id: String,
        master_key: [u8; 32],
        cluster_mode: ClusterMode,
    ) -> Self {
        Self::new_with_rp(
            engine,
            node_id,
            master_key,
            cluster_mode,
            RpConfig::default(),
        )
    }

    pub fn new_with_rp(
        engine: Engine,
        node_id: String,
        master_key: [u8; 32],
        cluster_mode: ClusterMode,
        rp: RpConfig,
    ) -> Self {
        Self {
            engine,
            started_at: StartedAt(now_epoch_ms()),
            node_id: Arc::new(node_id),
            cluster_mode,
            rp: Arc::new(rp),
            pending_challenges: Arc::new(DashMap::new()),
            enrollment_sessions: Arc::new(DashMap::new()),
            auth_rate_counters: Arc::new(DashMap::new()),
            master_key: Arc::new(master_key),
            redeem_gate: Arc::new(tokio::sync::Mutex::new(())),
            trusted_proxies: Arc::new(TrustedProxies::none()),
        }
    }

    /// Declare the reverse proxies whose forwarding headers may be believed.
    ///
    /// Builder-style so the safe default (trust nothing) is what you get
    /// unless a caller opts in explicitly.
    pub fn with_trusted_proxies(mut self, trusted: TrustedProxies) -> Self {
        self.trusted_proxies = Arc::new(trusted);
        self
    }
}

impl TrustedProxySource for ConsoleState {
    fn trusted_proxies(&self) -> &TrustedProxies {
        &self.trusted_proxies
    }
}

impl std::fmt::Debug for ConsoleState {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ConsoleState")
            .field("node_id", &self.node_id)
            .field("started_at", &self.started_at.0)
            .field("pending_challenges", &self.pending_challenges.len())
            .field("enrollment_sessions", &self.enrollment_sessions.len())
            .finish_non_exhaustive()
    }
}

#[cfg(test)]
mod rp_config_tests {
    use super::*;

    /// The default bind is `127.0.0.1` — before #935 this was exactly the
    /// node that could not enrol on any port but 9200.
    #[test]
    fn loopback_ipv4_bind_maps_to_localhost_with_the_bound_port() {
        let rp = RpConfig::from_bind_url("http://127.0.0.1:9550").unwrap();
        assert_eq!(rp.rp_id, "localhost");
        assert_eq!(rp.rp_origin, "http://localhost:9550");
    }

    #[test]
    fn loopback_ipv6_bind_maps_to_localhost() {
        let rp = RpConfig::from_bind_url("http://[::1]:9550").unwrap();
        assert_eq!(rp.rp_id, "localhost");
        assert_eq!(rp.rp_origin, "http://localhost:9550");
    }

    #[test]
    fn localhost_name_and_unspecified_binds_map_to_localhost() {
        let a = RpConfig::from_bind_url("http://localhost:9550").unwrap();
        let b = RpConfig::from_bind_url("http://0.0.0.0:9200").unwrap();
        let c = RpConfig::from_bind_url("http://[::]:9200").unwrap();
        assert_eq!(
            (a.rp_id.as_str(), a.rp_origin.as_str()),
            ("localhost", "http://localhost:9550")
        );
        assert_eq!(
            (b.rp_id.as_str(), b.rp_origin.as_str()),
            ("localhost", "http://localhost:9200")
        );
        assert_eq!(
            (c.rp_id.as_str(), c.rp_origin.as_str()),
            ("localhost", "http://localhost:9200")
        );
    }

    #[test]
    fn non_loopback_ip_bind_is_refused_with_the_address_named() {
        let err = RpConfig::from_bind_url("http://192.168.1.5:9200").unwrap_err();
        let msg = err.to_string();
        assert!(
            msg.contains("192.168.1.5"),
            "the refusal must name the address so the operator can act: {msg}"
        );
        assert!(RpConfig::from_bind_url("http://[fd00::1]:9200").is_err());
    }

    #[test]
    fn named_host_is_used_verbatim() {
        let rp = RpConfig::from_bind_url("http://console.example.com:9200").unwrap();
        assert_eq!(rp.rp_id, "console.example.com");
        assert_eq!(rp.rp_origin, "http://console.example.com:9200");
    }

    #[test]
    fn portless_url_keeps_a_portless_origin() {
        let rp = RpConfig::from_bind_url("http://localhost").unwrap();
        assert_eq!(rp.rp_id, "localhost");
        assert_eq!(rp.rp_origin, "http://localhost");
    }

    #[test]
    fn unparseable_url_is_refused() {
        assert!(RpConfig::from_bind_url("not a url").is_err());
        assert!(RpConfig::from_bind_url("http://").is_err());
    }

    #[test]
    fn public_bind_host_normalises_every_loopback_spelling() {
        assert_eq!(public_bind_host("127.0.0.1"), "localhost");
        assert_eq!(public_bind_host("::1"), "localhost");
        assert_eq!(public_bind_host("0.0.0.0"), "localhost");
        assert_eq!(public_bind_host("::"), "localhost");
        assert_eq!(public_bind_host("localhost"), "localhost");
    }

    #[test]
    fn public_bind_host_keeps_non_loopback_addresses_bracketing_ipv6() {
        assert_eq!(public_bind_host("192.168.1.5"), "192.168.1.5");
        assert_eq!(public_bind_host("fd00::1"), "[fd00::1]");
    }
}

//! Time helpers used across handlers.
//!
//! Centralises ISO-8601 parse/format and "epoch ms now" so individual
//! handlers don't rebuild the same chrono import / format-string knowledge.

use chrono::{DateTime, TimeZone, Utc};

/// Current wall-clock time as an ISO-8601 RFC 3339 string with millisecond
/// precision and a trailing `Z`. Stored as the canonical format in every
/// `.xerj_*` system index.
pub fn now_iso() -> String {
    Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true)
}

/// Current wall-clock time as Unix milliseconds. Useful for `expires_at`
/// fields the SPA compares to `Date.now()`.
pub fn now_epoch_ms() -> i64 {
    Utc::now().timestamp_millis()
}

/// Convert epoch milliseconds back to an ISO-8601 string. Returns
/// `1970-01-01T00:00:00.000Z` on overflow rather than panicking.
pub fn epoch_ms_to_iso(ms: i64) -> String {
    Utc.timestamp_millis_opt(ms)
        .single()
        .unwrap_or_else(|| Utc.timestamp_millis_opt(0).unwrap())
        .to_rfc3339_opts(chrono::SecondsFormat::Millis, true)
}

/// Parse an ISO-8601 string back into a `DateTime<Utc>`. Tolerant of
/// trailing `Z` vs `+00:00` and of microsecond precision; returns `None`
/// on anything not parseable.
pub fn parse_iso(s: &str) -> Option<DateTime<Utc>> {
    DateTime::parse_from_rfc3339(s)
        .ok()
        .map(|d| d.with_timezone(&Utc))
}

//! Saved views — named time-range + filter snapshots scoped to a
//! dashboard.
//!
//! Replaces `localStorage["xerj.views"]`.  Smaller surface than
//! dashboards: no etag concurrency (views are rarely co-edited), no
//! patch (clients DELETE-and-create instead).

use axum::{
    extract::{Path, Query, State},
    response::Response,
    Json,
};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::auth::sessions::AuthSession;
use crate::error::{ConsoleApiError, ConsoleResult};
use crate::indices;
use crate::response::{created, no_content, ok};
use crate::state::ConsoleState;
use crate::time::now_iso;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct View {
    pub id: String,
    pub owner: String,
    #[serde(default = "default_org")]
    pub org_id: String,
    pub dashboard_id: String,
    pub name: String,
    #[serde(default)]
    pub time: Option<Value>,
    #[serde(default)]
    pub filters: Option<Value>,
    pub updated_at: String,
}

fn default_org() -> String {
    "default".to_string()
}

#[derive(Debug, Deserialize)]
pub struct ListQuery {
    pub dashboard: Option<String>,
}

pub async fn list(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Query(q): Query<ListQuery>,
) -> ConsoleResult<Response> {
    let idx = state.engine.get_index(indices::VIEWS)?;
    let mut must: Vec<Value> = vec![json!({ "term": { "owner": sess.user.id } })];
    if let Some(dash) = q.dashboard {
        must.push(json!({ "term": { "dashboard_id": dash } }));
    }
    let body = json!({
        "query": { "bool": { "must": must } },
        "size": 200
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    let items: Vec<Value> = r.hits.into_iter().map(|h| h.source).collect();
    Ok(ok(json!({ "views": items, "total": items.len() }), None))
}

#[derive(Debug, Deserialize)]
pub struct CreateBody {
    pub dashboard_id: String,
    pub name: String,
    #[serde(default)]
    pub time: Option<Value>,
    #[serde(default)]
    pub filters: Option<Value>,
}

pub async fn create(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Json(body): Json<CreateBody>,
) -> ConsoleResult<Response> {
    let id = uuid::Uuid::new_v4().to_string();
    let view = View {
        id: id.clone(),
        owner: sess.user.id.clone(),
        org_id: default_org(),
        dashboard_id: body.dashboard_id,
        name: body.name,
        time: body.time,
        filters: body.filters,
        updated_at: now_iso(),
    };
    let idx = state.engine.get_index(indices::VIEWS)?;
    idx.create_document(id.clone(), serde_json::to_value(&view)?)
        .await?;
    let location = format!("/_xerj-console/api/v1/views/{id}");
    Ok(created(view, &location, None))
}

pub async fn get_one(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(id): Path<String>,
) -> ConsoleResult<Response> {
    let view = read(&state, &id).await?;
    if view.owner != sess.user.id {
        return Err(ConsoleApiError::NotFound("view".into()));
    }
    Ok(ok(view, None))
}

pub async fn delete(
    State(state): State<ConsoleState>,
    sess: AuthSession,
    Path(id): Path<String>,
) -> ConsoleResult<Response> {
    let view = read(&state, &id).await?;
    if view.owner != sess.user.id {
        return Err(ConsoleApiError::NotFound("view".into()));
    }
    let idx = state.engine.get_index(indices::VIEWS)?;
    // Same contract as `store::delete_passkey`: `Ok(false)` is already-absent
    // (idempotent), so only a refused write becomes an error. Swallowing
    // that error used to return 204 while the view stayed on disk.
    idx.delete_document(&id).await?;
    Ok(no_content())
}

async fn read(state: &ConsoleState, id: &str) -> ConsoleResult<View> {
    let idx = state.engine.get_index(indices::VIEWS)?;
    let body = json!({
        "query": { "ids": { "values": [id] } },
        "size": 1
    });
    let req = xerj_query::parser::parse_request(&body)
        .map_err(|e| ConsoleApiError::Internal(e.to_string()))?;
    let r = idx.search(&req).await?;
    let hit = r
        .hits
        .into_iter()
        .next()
        .ok_or_else(|| ConsoleApiError::NotFound(format!("view {id}")))?;
    Ok(serde_json::from_value(hit.source)?)
}

//! End-to-end test for the API-token surface (issue / list / revoke) and
//! `Authorization: Bearer` authentication.
//!
//! WebAuthn can't be driven from a pure-Rust test (no browser
//! authenticator), so instead of walking the passkey enrolment flow we
//! seed an active user directly and mint a signed session cookie with the
//! same `sessions::mint_session` the login handler uses. That cookie
//! authenticates the issue/list/revoke calls; the minted token then
//! authenticates a protected endpoint over Bearer.
//!
//! Proven here:
//!   - `POST /auth/api-tokens` returns the plaintext secret exactly once,
//!     and only for a passkey-backed session cookie.
//!   - `GET  /auth/api-tokens` lists only the hash/metadata — no plaintext.
//!   - the plaintext used as `Authorization: Bearer` authenticates `/me`
//!     and other ordinary console calls.
//!   - the same bearer token is 403 on credential minting and identity
//!     changes (token create/revoke, invite issue, passkey delete, logout)
//!     and those refusals write nothing (CVE-2026-97406 / CERT VU#645818).
//!   - `DELETE /auth/api-tokens/:id` with the passkey cookie revokes it →
//!     the same Bearer call 401s.
//!   - issuing a token without a session is rejected (401).

use axum::{body::Body, http::Request, Router};
use http_body_util::BodyExt;
use serde_json::{json, Value};
use tempfile::TempDir;
use tower::ServiceExt;
use xerj_common::config::Config;
use xerj_console_api::auth::{sessions, store};
use xerj_console_api::{state::ClusterMode, xerj_console_router, ConsoleState};
use xerj_engine::Engine;

async fn boot() -> (Engine, ConsoleState, Router, TempDir) {
    let dir = TempDir::new().unwrap();
    let mut cfg = Config::default();
    cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(cfg).expect("engine");
    let outcome = xerj_console_api::bootstrap::run(&engine, dir.path(), "http://localhost:9200")
        .await
        .expect("bootstrap");
    let state = ConsoleState::new(
        engine.clone(),
        "local".into(),
        outcome.master_key,
        ClusterMode::Standalone,
    );
    let router = xerj_console_router(state.clone());
    (engine, state, router, dir)
}

async fn body_json(resp: axum::response::Response) -> (axum::http::StatusCode, Value) {
    let status = resp.status();
    let bytes = resp.into_body().collect().await.unwrap().to_bytes();
    let v = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, v)
}

/// Seed an active user + a signed session cookie for it. Returns the
/// `Cookie:` header value the session-protected endpoints accept.
async fn seed_user_and_cookie(engine: &Engine, state: &ConsoleState) -> (String, String) {
    let user = store::User {
        id: "u-token-test".into(),
        email: "owner@example.com".into(),
        display_name: "Owner".into(),
        role: "owner".into(),
        status: store::UserStatus::Active,
        created_at: "2026-01-01T00:00:00.000Z".into(),
        last_seen_at: None,
    };
    store::upsert_user(engine, &user).await.unwrap();

    let (_sess, signed) = sessions::mint_session(state, &user.id, "passkey", None, None)
        .await
        .unwrap();
    (user.id, format!("{}={}", sessions::COOKIE_NAME, signed))
}

#[tokio::test]
async fn api_token_issue_list_bearer_and_revoke() {
    let (engine, state, router, _dir) = boot().await;
    let (user_id, cookie) = seed_user_and_cookie(&engine, &state).await;

    // ── Issue ──────────────────────────────────────────────────────────
    let resp = router
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/_xerj-console/api/v1/auth/api-tokens")
                .header("content-type", "application/json")
                .header("cookie", &cookie)
                .body(Body::from(
                    json!({ "name": "ci-token", "scopes": ["read"] }).to_string(),
                ))
                .unwrap(),
        )
        .await
        .unwrap();
    let (status, body) = body_json(resp).await;
    assert_eq!(status, 200, "issue must succeed: {body}");
    let plaintext = body["data"]["token"].as_str().unwrap().to_string();
    let token_id = body["data"]["id"].as_str().unwrap().to_string();
    assert!(
        plaintext.len() >= 40,
        "secret should be 32 bytes url-safe b64"
    );
    assert_ne!(plaintext, token_id, "id must be the hash, not the secret");
    assert_eq!(body["data"]["name"], "ci-token");

    // ── List: metadata only, never the plaintext ───────────────────────
    let resp = router
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/_xerj-console/api/v1/auth/api-tokens")
                .header("cookie", &cookie)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let (status, body) = body_json(resp).await;
    assert_eq!(status, 200, "list must succeed: {body}");
    let tokens = body["data"]["tokens"].as_array().unwrap();
    assert_eq!(tokens.len(), 1, "exactly one token: {body}");
    assert_eq!(tokens[0]["id"], token_id);
    assert!(
        !body.to_string().contains(&plaintext),
        "plaintext secret leaked into the list response"
    );

    // ── Bearer auth on a protected endpoint → 200 ──────────────────────
    let resp = router
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/_xerj-console/api/v1/me")
                .header("authorization", format!("Bearer {plaintext}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let (status, body) = body_json(resp).await;
    assert_eq!(status, 200, "bearer auth must authenticate: {body}");
    assert_eq!(body["data"]["user"]["id"], user_id);

    // ── Revoke ─────────────────────────────────────────────────────────
    let resp = router
        .clone()
        .oneshot(
            Request::builder()
                .method("DELETE")
                .uri(format!("/_xerj-console/api/v1/auth/api-tokens/{token_id}"))
                .header("cookie", &cookie)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), 204, "revoke must return 204");

    // ── Same Bearer call now 401s ──────────────────────────────────────
    let resp = router
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/_xerj-console/api/v1/me")
                .header("authorization", format!("Bearer {plaintext}"))
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        resp.status(),
        401,
        "a revoked token must no longer authenticate"
    );
}

#[tokio::test]
async fn api_token_issue_requires_a_session() {
    let (_engine, _state, router, _dir) = boot().await;

    // No cookie, no bearer → the AuthSession extractor rejects with 401.
    let resp = router
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/_xerj-console/api/v1/auth/api-tokens")
                .header("content-type", "application/json")
                .body(Body::from(json!({ "name": "x" }).to_string()))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), 401, "issuing a token needs authentication");
}

#[tokio::test]
async fn bogus_bearer_token_is_rejected() {
    let (_engine, _state, router, _dir) = boot().await;

    let resp = router
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/_xerj-console/api/v1/me")
                .header("authorization", "Bearer not-a-real-token")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        resp.status(),
        401,
        "unknown bearer token must not authenticate"
    );
}

const TOKENS: &str = "/_xerj-console/api/v1/auth/api-tokens";

async fn call(
    router: &Router,
    method: &str,
    uri: &str,
    cookie: Option<&str>,
    bearer: Option<&str>,
    json_body: Option<Value>,
) -> (axum::http::StatusCode, Value) {
    let mut builder = Request::builder().method(method).uri(uri);
    if let Some(cookie) = cookie {
        builder = builder.header("cookie", cookie);
    }
    if let Some(bearer) = bearer {
        builder = builder.header("authorization", format!("Bearer {bearer}"));
    }
    let req = match json_body {
        Some(body) => builder
            .header("content-type", "application/json")
            .body(Body::from(body.to_string()))
            .unwrap(),
        None => builder.body(Body::empty()).unwrap(),
    };
    body_json(router.clone().oneshot(req).await.unwrap()).await
}

fn assert_passkey_required(status: axum::http::StatusCode, body: &Value, what: &str) {
    assert_eq!(
        status, 403,
        "{what} must refuse a non-passkey caller: {body}"
    );
    assert_eq!(body["error"]["code"], "forbidden", "{what}: {body}");
    let message = body["error"]["message"].as_str().unwrap_or("");
    assert!(
        message.contains(sessions::PASSKEY_SESSION_REQUIRED),
        "{what} 403 must name the passkey-session rule, got {body}"
    );
}

async fn seed_passkey(engine: &Engine, user_id: &str, id: &str) {
    store::put_passkey(
        engine,
        &store::StoredPasskey {
            id: id.into(),
            user_id: user_id.into(),
            name: id.into(),
            created_at: "2026-01-01T00:00:00.000Z".into(),
            last_used_at: None,
            blob: json!({}),
        },
    )
    .await
    .unwrap();
}

struct Issued {
    engine: Engine,
    router: Router,
    // Kept so the data directory outlives the engine.
    _dir: TempDir,
    user_id: String,
    cookie: String,
    plaintext: String,
    token_id: String,
}

/// Each `call` builds an axum `Router::oneshot` future. Several of those in
/// one async fn overflow the test thread's stack in a debug build, so the
/// CVE checks are separate tests that share this setup.
async fn issue_with_passkey_cookie() -> Issued {
    let (engine, state, router, dir) = boot().await;
    let (user_id, cookie) = seed_user_and_cookie(&engine, &state).await;
    seed_passkey(&engine, &user_id, "pk-laptop").await;
    seed_passkey(&engine, &user_id, "pk-phone").await;
    let (status, body) = call(
        &router,
        "POST",
        TOKENS,
        Some(&cookie),
        None,
        Some(json!({ "name": "ci-token", "scopes": ["read"] })),
    )
    .await;
    assert_eq!(status, 200, "passkey cookie must still mint: {body}");
    Issued {
        engine,
        router,
        _dir: dir,
        user_id,
        cookie,
        plaintext: body["data"]["token"].as_str().unwrap().to_string(),
        token_id: body["data"]["id"].as_str().unwrap().to_string(),
    }
}

/// CVE-2026-97406 / CERT VU#645818. A bearer token used to resolve to the
/// same `AuthSession` as a passkey cookie, so it could mint a successor
/// that survived revocation of the parent. Bearer alone, and bearer sent
/// together with the passkey cookie, are both 403 and insert nothing.
#[tokio::test]
async fn bearer_token_cannot_mint_a_successor() {
    // Boxed so this test's future does not embed the setup future. Several
    // `Router::oneshot` futures in one frame overflow the debug stack.
    let issued = Box::pin(issue_with_passkey_cookie()).await;

    for (label, cookie_hdr) in [
        ("bearer alone", None),
        (
            "bearer plus the passkey cookie",
            Some(issued.cookie.as_str()),
        ),
    ] {
        let name = format!("successor-{label}");
        let (status, body) = call(
            &issued.router,
            "POST",
            TOKENS,
            cookie_hdr,
            Some(&issued.plaintext),
            Some(json!({ "name": name })),
        )
        .await;
        assert_passkey_required(status, &body, label);
    }
    let stored = store::list_api_tokens_for_user(&issued.engine, &issued.user_id)
        .await
        .unwrap();
    assert_eq!(
        stored.len(),
        1,
        "a refused mint must not insert a descendant: {stored:?}"
    );
    assert_eq!(stored[0].id, issued.token_id);
    assert!(stored[0].revoked_at.is_none());

    // An unknown bearer is 401, not the passkey-session 403.
    let (status, body) = call(
        &issued.router,
        "POST",
        TOKENS,
        None,
        Some("not-a-real-token"),
        Some(json!({ "name": "nope" })),
    )
    .await;
    assert_eq!(status, 401, "an unknown bearer is unauthenticated: {body}");
    assert_eq!(body["error"]["code"], "unauthorized");
}

/// Revoking a token, issuing an invitation, and deleting a passkey are the
/// same class of operation. A bearer token is 403 and the rows stay put.
/// The passkey cookie can still delete a passkey.
#[tokio::test]
async fn bearer_token_cannot_revoke_invite_or_delete_a_passkey() {
    // Boxed so this test's future does not embed the setup future. Several
    // `Router::oneshot` futures in one frame overflow the debug stack.
    let issued = Box::pin(issue_with_passkey_cookie()).await;

    let (status, body) = call(
        &issued.router,
        "DELETE",
        &format!("{TOKENS}/{}", issued.token_id),
        None,
        Some(&issued.plaintext),
        None,
    )
    .await;
    assert_passkey_required(status, &body, "revoke");
    let (status, body) = call(
        &issued.router,
        "GET",
        "/_xerj-console/api/v1/me",
        None,
        Some(&issued.plaintext),
        None,
    )
    .await;
    assert_eq!(
        status, 200,
        "refused revoke must leave the token working: {body}"
    );

    let (status, body) = call(
        &issued.router,
        "POST",
        "/_xerj-console/api/v1/auth/magic/issue",
        None,
        Some(&issued.plaintext),
        Some(json!({ "email": "attacker@example.com", "role": "owner" })),
    )
    .await;
    assert_passkey_required(status, &body, "invite issue");
    assert!(
        store::find_user_by_email(&issued.engine, "attacker@example.com")
            .await
            .unwrap()
            .is_none(),
        "a refused invite must not provision the invitee"
    );

    let (status, body) = call(
        &issued.router,
        "DELETE",
        "/_xerj-console/api/v1/auth/passkeys/pk-laptop",
        None,
        Some(&issued.plaintext),
        None,
    )
    .await;
    assert_passkey_required(status, &body, "passkey delete");
    let passkeys = store::list_passkeys_for_user(&issued.engine, &issued.user_id)
        .await
        .unwrap();
    assert_eq!(passkeys.len(), 2, "refused delete must keep both passkeys");

    // Two passkeys are enrolled, so the last-passkey guard does not fire.
    let (status, _) = call(
        &issued.router,
        "DELETE",
        "/_xerj-console/api/v1/auth/passkeys/pk-phone",
        Some(&issued.cookie),
        None,
        None,
    )
    .await;
    assert_eq!(status, 204, "passkey cookie must still delete a passkey");
}

/// Logout revokes the passkey session only. A bearer token cannot end that
/// session, and ending it does not revoke the token.
