    );

    let (status, _) = call(
        &issued.router,
        "POST",
        "/_xerj-console/api/v1/auth/logout",
        Some(&issued.cookie),
        None,
        None,
    )
    .await;
    assert_eq!(status, 200, "passkey cookie must still be able to log out");
    let (status, _) = call(
        &issued.router,
