reqwest    = { workspace = true }
rayon      = { workspace = true }
libc       = "0.2"
uuid       = { workspace = true }
sha2       = "0.10"   # v0.9 9-P4 — audit log hash chain
chrono     = { workspace = true }
chrono-tz  = "0.8"
