// ── Field value cache ─────────────────────────────────────────────────────────

/// Per-aggregation-level cache of pre-extracted field values.
///
/// When multiple sibling aggregations target the same field (e.g. `avg`,
/// `sum`, `max` all on `"price"`), we extract the values for that field once
/// and reuse them across all sibling aggs.  A fresh `FieldCache` is created at
/// each level of `run_aggs_with_all` so nested sub-agg calls automatically get
/// their own cache scoped to the (filtered) bucket docs.
struct FieldCache<'d> {
    docs: &'d [Value],
    /// field → Vec<Vec<f64>> (ALL numeric values per doc, for metric aggs)
    numeric_multi: HashMap<String, Vec<Vec<f64>>>,
    /// field → Vec<Vec<String>>
    strings: HashMap<String, Vec<Vec<String>>>,
}

impl<'d> FieldCache<'d> {
    fn new(docs: &'d [Value]) -> Self {
        Self {
            docs,
            numeric_multi: HashMap::new(),
            strings: HashMap::new(),
        }
    }

    /// Every numeric value per doc (a multi-valued field yields all its
    /// values, ES semantics — not just the first). Coercion matches
    /// `extract_numeric` (number, numeric string, or date string → epoch ms).
    fn get_numeric_multi(&mut self, field: &str) -> &[Vec<f64>] {
        self.numeric_multi
            .entry(field.to_string())
            .or_insert_with(|| {
                self.docs
                    .iter()
                    .map(|d| extract_metric_numeric_values(d, field))
                    .collect()
            })
    }

    fn get_strings(&mut self, field: &str) -> &[Vec<String>] {
        self.strings.entry(field.to_string()).or_insert_with(|| {
            self.docs
                .iter()
                .map(|d| extract_field_values(d, field))
                .collect()
        })
    }
}

// ── Public entry point ────────────────────────────────────────────────────────

/// Execute all aggregations in `aggs_def` over the provided document sources.
///
/// * `aggs_def` — the raw JSON value of the `"aggs"` key from a SearchRequest.
/// * `docs`     — the matching document sources (after query filtering).
///
/// Returns an ES-compatible `aggregations` object:
/// ```json
/// {
///   "my_agg": { "buckets": [...] },
///   "my_metric": { "value": 42 }
/// }
/// ```
pub fn run_aggs(aggs_def: &Value, docs: &[Value]) -> Value {
    run_aggs_with_all(aggs_def, docs, docs)
}

thread_local! {
    /// Mapping/analyzer context for the `filter` and `filters` aggregations
    /// (#1745), installed by [`run_aggs_with_schema`] for one synchronous
    /// aggregation. `None` means no schema was supplied and those aggs fall
    /// back to the legacy `_source`-only matcher.
    ///
    /// Scoped to the calling thread for the same reason as
    /// `BUCKET_CAP_OVERRIDE`: the whole agg evaluator is synchronous and runs
    /// on the caller's thread, so the value covers exactly the call it was
    /// installed for and is invisible to a concurrent aggregation elsewhere.
    static FILTER_SCHEMA: std::cell::RefCell<Option<Schema>> =
        const { std::cell::RefCell::new(None) };
}

/// Restores the previous value on drop, so nested calls compose.
struct FilterSchemaScope(Option<Schema>);

impl FilterSchemaScope {
    fn install(schema: Option<&Schema>) -> Self {
        let previous =
            FILTER_SCHEMA.with(|cell| std::mem::replace(&mut *cell.borrow_mut(), schema.cloned()));
        Self(previous)
    }
}

impl Drop for FilterSchemaScope {
    fn drop(&mut self) {
        FILTER_SCHEMA.with(|cell| *cell.borrow_mut() = self.0.take());
    }
}

/// [`run_aggs_with_all`] with the index's mapping available to `filter` and
/// `filters` aggregations (#1745).
///
/// Those two aggs evaluate their clauses per document. Without a schema they
/// used `doc_matches_filter`'s `_source` approximation — `match` was a
/// substring test, `match: "a b"` was AND rather than ES's default OR, and
/// `match_phrase` ignored adjacency — so the same clause counted differently
/// as an aggregation than as a query. With the schema in scope the clause is
/// evaluated by `doc_matches_query_typed`, the matcher `_search`/`_count`
/// use, so the two surfaces agree.
pub fn run_aggs_with_schema(
    aggs_def: &Value,
    docs: &[Value],
    all_docs: &[Value],
    schema: &Schema,
) -> Value {
    let _scope = FilterSchemaScope::install(Some(schema));
    run_aggs_with_all(aggs_def, docs, all_docs)
}

/// True when every field the clause targets is a declared `text` field.
///
/// Only then does `filter`/`filters` evaluate the clause with the query
/// matcher; every other clause keeps `doc_matches_filter`. Two boundaries are
/// deliberate:
///
/// * Keyword / numeric / boolean / date / ip clauses are already rewritten by
///   the API layer's mapping-aware `match` → exact `term`/`terms` rewrite
///   (`es_compat`), which is the form the legacy matcher answers correctly.
///   Sending them through the query matcher tokenizes keyword values — the
///   `filters_bucket.yml` `split_queries_on_whitespace` case counts 5 instead
///   of ES's 4 that way.
/// * Aggregation targets resolve field names with the agg-side rule
///   (`get_nested_field` strips one suffix segment), while
///   `doc_matches_query_typed` uses the recursive query-side rule. A suffix
///   alias is not a declared field, so it stays on the agg-side matcher —
///   `fast_aggs_multifield_suffix` pins that split.
///
/// `Bool` and the score wrappers recurse, so a clause that mixes a text leaf
/// with an exact leaf stays on the legacy matcher rather than evaluating half
/// of itself with each rule.
fn clause_targets_only_text(node: &QueryNode, schema: &Schema) -> bool {
    match node {
        QueryNode::Match { field, .. }
        | QueryNode::MatchPhrase { field, .. }
        | QueryNode::MatchPhrasePrefix { field, .. }
        | QueryNode::Term { field, .. }
        | QueryNode::Terms { field, .. } => crate::index::declared_field(schema, field)
            .is_some_and(|f| matches!(f.field_type, FieldType::Text)),
        QueryNode::Bool {
            must,
            should,
            must_not,
            filter,
            ..
        } => must
            .iter()
            .chain(should)
            .chain(must_not)
            .chain(filter)
            .all(|q| clause_targets_only_text(q, schema)),
        QueryNode::Constant { query, .. }
        | QueryNode::Boosted { query, .. }
        | QueryNode::Named { query, .. } => clause_targets_only_text(query, schema),
        QueryNode::Boosting { positive, .. } => clause_targets_only_text(positive, schema),
        _ => false,
    }
}

// ── Aggregation bucket cap ────────────────────────────────────────────────────
//
// Hard cap on how many distinct buckets a single aggregation may materialise.
// Mirrors Elasticsearch's `search.max_buckets` cluster setting (default 65536).
// Without this guard, a `terms` agg over a high-cardinality field (e.g. 50M
// unique user IDs) allocates one HashMap entry per unique value before any
// `size`/`shard_size` cap can drop them — easy OOM. Per-bucket-allocator
// loops in this module read `max_buckets()` ONCE, hoisted above the loop,
// and compare against it on each insert; when exceeded the accumulator stops
// adding new keys (existing keys still increment). The read used to sit
// inside the loop; hoisting it is what lets the cap be a per-call value
// without paying for the lookup per document.
//
// The node-wide default is set once at Engine construction via
// `set_max_buckets`; it defaults to the same 65 536 ES uses if never set.
// Atomic + Relaxed: read at the head of agg loops, written once at startup,
// no ordering needed.
//
// A single aggregation run can *override* that default for the duration of
// one call via `run_aggs_with_limits`. The override lives in a thread-local
// (see `BUCKET_CAP_OVERRIDE`) rather than in the static, so one caller's
// tighter cap is never observable by an aggregation running concurrently on
// another thread. Mutating the static to express a per-call limit would be a
// data race in the semantic sense: every other in-flight aggregation in the
// process would silently adopt the foreign cap.
static MAX_BUCKETS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(65_536);

thread_local! {
    /// Per-call bucket-cap override installed by `BucketCapScope`, i.e. by
    /// `run_aggs_with_limits`. `None` (the common case) means "use the
    /// node-wide default". Scoped to the calling thread: the whole agg
    /// evaluator is synchronous and runs on the caller's thread, so the
    /// override covers exactly the call it was installed for.
    static BUCKET_CAP_OVERRIDE: std::cell::Cell<Option<usize>> =
        const { std::cell::Cell::new(None) };
}

/// Set the node-wide default per-aggregation bucket cap. Called once at
/// Engine startup with `config.limits.max_buckets`. Subsequent calls
/// overwrite the previous value.
///
/// This is deliberately *not* the way to express a limit for a single
/// aggregation — use [`run_aggs_with_limits`] for that.
pub fn set_max_buckets(n: usize) {
    MAX_BUCKETS.store(n.max(1), std::sync::atomic::Ordering::Relaxed);
}

/// The bucket cap in force for the aggregation running on this thread: the
/// per-call override if one is installed, otherwise the node-wide default.
///
/// Callers hoist this out of their per-document loops; it is a cap for the
/// whole aggregation, not something that may change mid-run.
#[inline]
pub fn max_buckets() -> usize {
    match BUCKET_CAP_OVERRIDE.with(std::cell::Cell::get) {
        Some(n) => n,
        None => MAX_BUCKETS.load(std::sync::atomic::Ordering::Relaxed),
    }
}

/// [`max_buckets`] as an `i64`, for the gap-filling histogram loops whose
/// bucket keys and spans are `i64`.
///
/// Exists so the columnar fast path (`fast_aggs.rs`) and this brute
/// evaluator read the *same* cap through the *same* accessor: both used to
/// carry their own `const MAX_BUCKETS: i64 = 65_536`, which silently ignored
/// `config.limits.max_buckets` and the per-call [`AggLimits`] override.
/// Callers hoist this above their loop, exactly like `max_buckets()`.
///
/// The `min` is a saturating cast, not a policy: the cap is a `usize`, and on
/// a 64-bit target a configured cap above `i64::MAX` would otherwise wrap
/// negative and reject every aggregation.
#[inline]
pub(crate) fn max_buckets_i64() -> i64 {
    max_buckets().min(i64::MAX as usize) as i64
}

/// Diagnostic counter: aggregation requests answered by the columnar fast
/// path in `fast_aggs.rs` instead of this brute evaluator.
///
/// Monotonic and process-wide, incremented with `Relaxed` once per served
/// request. Nothing in the engine reads it to make a decision.
///
/// The two executors are *intended* to return byte-identical results, which is
/// why a caller cannot tell them apart from the response and needs this signal.
/// That intent is not yet fact: #99, #104, #114 and #120 each closed a case
/// where they diverged (and #128 tracks the nested-object case still open).
/// Treat the invariant as the thing the tests are enforcing, not as something
/// already true.
static FAST_PATH_AGGS_SERVED: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Number of aggregation requests served by the columnar fast path since
/// process start. Read two of these around a search to learn whether that
/// search took the fast path.
pub fn fast_path_aggs_served() -> u64 {
    FAST_PATH_AGGS_SERVED.load(std::sync::atomic::Ordering::Relaxed)
}

/// Record that the columnar fast path answered one aggregation request.
pub(crate) fn note_fast_path_agg() {
    FAST_PATH_AGGS_SERVED.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
}

/// Documents cloned out of segment stored sections into the brute
/// aggregation corpus. Memtable docs are not counted: that buffer is
/// flush-bounded. A verify query that stays on the columnar path leaves
/// this unchanged no matter how many documents the index holds.
static CORPUS_DOCS_HYDRATED: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Segment documents copied into an owned aggregation corpus since process
/// start. Read two of these around a search to see whether that search
/// materialised stored documents.
pub fn corpus_docs_hydrated() -> u64 {
    CORPUS_DOCS_HYDRATED.load(std::sync::atomic::Ordering::Relaxed)
}

pub(crate) fn note_corpus_hydration(n: u64) {
    if n > 0 {
        CORPUS_DOCS_HYDRATED.fetch_add(n, std::sync::atomic::Ordering::Relaxed);
    }
}

/// Per-call aggregation limits. Passed to [`run_aggs_with_limits`] by callers
/// that need a limit other than the node-wide default (a per-request
/// `search.max_buckets` override, or a test pinning the cap for one call).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AggLimits {
    /// Maximum number of buckets a single aggregation may materialise.
    pub max_buckets: usize,
}

impl Default for AggLimits {
    fn default() -> Self {
        Self {
            max_buckets: max_buckets(),
        }
    }
}

/// RAII installer for a per-call bucket cap. Restores the previous value on
/// drop — including on unwind — so a panicking aggregation cannot leave a
/// foreign cap behind for the next aggregation on this thread. Nesting is
/// supported (the inner scope wins, the outer value is restored).
struct BucketCapScope {
    previous: Option<usize>,
}

impl BucketCapScope {
    fn new(max_buckets: usize) -> Self {
        let previous = BUCKET_CAP_OVERRIDE.with(|cell| cell.replace(Some(max_buckets.max(1))));
        Self { previous }
    }
}

impl Drop for BucketCapScope {
    fn drop(&mut self) {
        BUCKET_CAP_OVERRIDE.with(|cell| cell.set(self.previous));
    }
}

/// Run an aggregation under explicit limits instead of the node-wide
/// defaults. Identical to [`run_aggs_with_all`] in every other respect.
///
/// The limits apply to this call only and are invisible to aggregations
/// running concurrently on other threads.
pub fn run_aggs_with_limits(
    aggs_def: &Value,
    docs: &[Value],
    all_docs: &[Value],
    limits: AggLimits,
) -> Value {
    let _scope = BucketCapScope::new(limits.max_buckets);
    run_aggs_with_all(aggs_def, docs, all_docs)
}

thread_local! {
    /// Lowercased query-term set extracted from the outer search query.
    /// `run_top_hits` reads this to build per-bucket highlight / explain
    /// output without having to plumb the query node through every agg
    /// layer. Set by the search handler via `set_outer_query_terms`
    /// before calling `run_aggs_with_all`; cleared afterwards.
    pub static OUTER_QUERY_TERMS: std::cell::RefCell<Vec<String>> =
        const { std::cell::RefCell::new(Vec::new()) };
    /// (field, term) pairs extracted from the outer Match/Term queries.
    /// Used by run_top_hits to build per-hit _explanation output when
    /// the caller sets `explain: true` on top_hits.
    pub static OUTER_QUERY_FIELD_TERMS: std::cell::RefCell<Vec<(String, String)>> =
        const { std::cell::RefCell::new(Vec::new()) };
}

pub fn set_outer_query_terms(terms: Vec<String>) {
    OUTER_QUERY_TERMS.with(|cell| *cell.borrow_mut() = terms);
}

pub fn set_outer_query_field_terms(pairs: Vec<(String, String)>) {
    OUTER_QUERY_FIELD_TERMS.with(|cell| *cell.borrow_mut() = pairs);
}

pub fn clear_outer_query_terms() {
    OUTER_QUERY_TERMS.with(|cell| cell.borrow_mut().clear());
    OUTER_QUERY_FIELD_TERMS.with(|cell| cell.borrow_mut().clear());
}

pub fn outer_query_terms() -> Vec<String> {
    OUTER_QUERY_TERMS.with(|cell| cell.borrow().clone())
}

pub fn outer_query_field_terms() -> Vec<(String, String)> {
    OUTER_QUERY_FIELD_TERMS.with(|cell| cell.borrow().clone())
}

/// Like `run_aggs` but also receives the full index doc set for background
/// frequency calculations (used by `significant_terms`).
pub fn run_aggs_with_all(aggs_def: &Value, docs: &[Value], all_docs: &[Value]) -> Value {
    // Top-level entry point: there is no enclosing bucket, so a bare `_count`
    // has no bucket doc_count to agree with. It reports the physical size of
    // the result set — the number `hits.total.value` carries in the same
    // response. Every *bucket* agg calls `run_aggs_in_bucket` instead and
    // hands over the doc_count it is about to publish.
    run_aggs_in_bucket(aggs_def, docs, all_docs, docs.len() as u64)
}

// #375: counts how many buckets actually had their sub-aggregations
// materialised, so a test can prove the nested-terms path defers sub-aggs to
// the surviving top-N instead of computing them for every candidate bucket.
// Thread-local (not a global atomic) so parallel agg tests don't pollute each
// other's count — the brute agg path runs synchronously on the caller thread.
#[cfg(test)]
thread_local! {
    pub(crate) static SUBAGG_BUCKET_EVALS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

/// `run_aggs_with_all` for the sub-aggs of a single bucket.
///
/// `bucket_doc_count` is the value the CALLER puts in that bucket's
/// `"doc_count"` field. It is passed in rather than recomputed because the
/// two must not be allowed to differ: see the staging comment below.
pub(crate) fn run_aggs_in_bucket(
    aggs_def: &Value,
    docs: &[Value],
    all_docs: &[Value],
    bucket_doc_count: u64,
) -> Value {
    #[cfg(test)]
    SUBAGG_BUCKET_EVALS.with(|c| c.set(c.get() + 1));
    let obj = match aggs_def.as_object() {
        Some(o) => o,
        None => return Value::Object(Map::new()),
    };

    // Create a fresh field-value cache scoped to this docs slice.
    // Sub-agg calls to run_aggs_with_all with filtered bucket docs will
    // create their own independent caches so there's no cross-contamination.
    let mut cache = FieldCache::new(docs);

    let mut result = Map::new();
    for (agg_name, agg_body) in obj {
        let mut agg_result =
            execute_agg_with_all_cached(agg_name, agg_body, docs, all_docs, &mut cache);
        if let Some(meta) = agg_body.get("meta") {
            if let Some(res_obj) = agg_result.as_object_mut() {
                res_obj.insert("meta".into(), meta.clone());
            }
        }
        result.insert(agg_name.clone(), agg_result);
    }

    // A bare `"_count"` buckets_path (no sibling prefix — Timelion's
    // `.opensearch()` datasource emits exactly this for its per-bucket
    // count metric) refers to the CONTAINING bucket's own doc_count, not
    // a named sibling's. `docs` here already IS that bucket's doc slice at
    // every nesting level (top-level query matches, or a terms/
    // date_histogram bucket's filtered docs for a recursive call), so
    // stage it under a transient `doc_count` key for `resolve_bucket_script`
    // to read via `siblings`, then strip it back out — it isn't a real
    // sibling agg and must not leak into the returned aggs tree. Guarded
    // against the (unusual) case of a user-defined agg literally named
    // `doc_count`, which must win over the synthetic value.
    //
    // The staged number is `bucket_doc_count` — the value the calling bucket
    // agg is about to publish in its own `"doc_count"` field — and NOT any
    // count recomputed from `docs` here. A bucket and a `bucket_script`
    // sitting inside it must not disagree about how many documents the bucket
    // holds, and the two families of bucket agg in this file count
    // differently:
    //
    //   `sum_doc_count(docs)` — honours the `_doc_count` metadata field that
    //     rollup / downsampled indices attach to advertise how many logical
    //     events one physical document stands for:
    //     terms, date_histogram, histogram, filter, filters, date_range,
    //     composite.
    //
    //   `docs.len()`          — physical documents, `_doc_count` ignored:
    //     range, multi_terms, ip_range, ip_prefix, rare_terms, geo_distance,
    //     geotile_grid, geohash_grid, adjacency_matrix, time_series,
    //     variable_width_histogram, sampler, diversified_sampler, nested,
    //     reverse_nested, global.
    //
    // Recomputing here with EITHER function therefore disagrees with half the
    // callers — measured: staging `sum_doc_count` gives a `range` bucket
    // `"doc_count": 2` next to a bare `_count` of `8`, and staging
    // `docs.len()` gives a `terms` bucket `"doc_count": 8` next to a `_count`
    // of `2`. Taking the caller's number is the only staging that is right
    // for both families, and it stays right for a bucket type added later.
    //
    // (That the second list ignores `_doc_count` at all is a real,
    // pre-existing ES divergence, but it is a divergence in the *bucket's*
    // doc_count, which `_count` must mirror rather than silently correct.)
    //
    // Staged only when this agg level actually carries a pipeline placeholder
    // for `resolve_sibling_pipelines` to resolve, so an aggs tree with no
    // pipeline in it does not touch `result` at all.
    let staged_doc_count = !result.contains_key("doc_count")
        && result.values().any(|v| {
            v.get("__pipeline__")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        });
    if staged_doc_count {
        result.insert("doc_count".to_string(), json!(bucket_doc_count));
    }
    resolve_sibling_pipelines(&mut result);
    if staged_doc_count {
        result.remove("doc_count");
    }

    Value::Object(result)
}

/// Second pass of `run_aggs_with_all`: resolve pipeline aggregations
/// (`__pipeline__` placeholders emitted by `run_pipeline_agg`) against
/// their already-computed sibling results, in place.
///
/// Extracted so the doc-values fast-agg path (`index.rs`/`fast_aggs.rs`)
/// can reuse the exact same resolution + typed-keys tagging semantics.
pub(crate) fn resolve_sibling_pipelines(result: &mut Map<String, Value>) {
    let pipeline_keys: Vec<String> = result
        .iter()
        .filter(|(_, v)| {
            v.get("__pipeline__")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .map(|(k, _)| k.clone())
        .collect();

    for key in pipeline_keys {
        let (agg_type, buckets_path, extra, format) = {
            let spec = &result[&key];
            let t = spec["type"].as_str().unwrap_or("").to_string();
            let bp = spec["buckets_path"].as_str().unwrap_or("").to_string();
            let format = spec
                .get("format")
                .and_then(Value::as_str)
                .map(str::to_string);
            let extra = spec.clone();
            (t, bp, extra, format)
        };
        let mut resolved = resolve_pipeline_agg_full(&agg_type, &buckets_path, &extra, result);
        if let Some(fmt) = format {
            apply_pipeline_value_format(&mut resolved, &fmt);
        }
        // Tag the resolved result with the ES class name typed_keys uses so
        // downstream rewrite picks the right prefix. ES emits:
        //   bucket_metric_value — max_bucket, min_bucket, avg_bucket, sum_bucket
        //   stats_bucket — stats_bucket
        //   extended_stats_bucket — extended_stats_bucket
        //   percentiles_bucket — percentiles_bucket
        //   simple_value — moving_avg, moving_fn, cumulative_sum, derivative, serial_diff, bucket_script
        if let Some(obj) = resolved.as_object_mut() {
            let typed = match agg_type.as_str() {
                "max_bucket" | "min_bucket" | "avg_bucket" | "sum_bucket" => "bucket_metric_value",
                "stats_bucket" => "stats_bucket",
                "extended_stats_bucket" => "extended_stats_bucket",
                "percentiles_bucket" => "percentiles_bucket",
                _ => "simple_value",
            };
            obj.insert("__type__".into(), Value::String(typed.to_string()));
        }
        result.insert(key, resolved);
    }
}

/// Resolve a pipeline aggregation against already-computed sibling results,
/// with access to the full pipeline spec (for window, script, sort parameters).
fn resolve_pipeline_agg_full(
    agg_type: &str,
    buckets_path: &str,
    spec: &Value,
    siblings: &Map<String, Value>,
) -> Value {
    match agg_type {
        "moving_avg" => {
            let window = spec.get("window").and_then(|v| v.as_u64()).unwrap_or(5) as usize;
            resolve_moving_avg_full(buckets_path, window, siblings)
        }
        "bucket_selector" => {
            let script = spec
                .get("script")
                .and_then(|v| {
                    v.as_str()
                        .or_else(|| v.get("source").and_then(|s| s.as_str()))
                })
                .unwrap_or("")
                .to_string();
            resolve_bucket_selector(buckets_path, &script, siblings)
        }
        "bucket_sort" => {
            let sort = spec.get("sort").cloned();
            let size = spec
                .get("size")
                .and_then(|v| v.as_u64())
                .map(|n| n as usize);
            resolve_bucket_sort(buckets_path, sort.as_ref(), size, siblings)
        }
        "bucket_script" => {
            let script_val = spec.get("script");
            let script = script_val
                .and_then(|v| {
                    v.as_str()
                        .or_else(|| v.get("source").and_then(|s| s.as_str()))
                })
                .unwrap_or("")
                .to_string();
            // Script-provided constant params (e.g. `script.params.extra = 1`).
            let extra_params: HashMap<String, f64> = script_val
                .and_then(|v| v.get("params"))
                .and_then(|v| v.as_object())
                .map(|o| {
                    o.iter()
                        .filter_map(|(k, v)| v.as_f64().map(|f| (k.clone(), f)))
                        .collect()
                })
                .unwrap_or_default();
            let bp_full = spec
                .get("buckets_path_full")
                .cloned()
                .unwrap_or(Value::Null);
            resolve_bucket_script(&bp_full, &script, &extra_params, siblings)
        }
        _ => {
            let gap_policy = spec
                .get("gap_policy")
                .and_then(Value::as_str)
                .unwrap_or("skip");
            resolve_pipeline_agg_with_gap(agg_type, buckets_path, siblings, gap_policy)
        }
    }
}

fn resolve_moving_avg_full(
    buckets_path: &str,
    window: usize,
    siblings: &Map<String, Value>,
) -> Value {
    let (sibling_name, metric_name) = split_buckets_path(buckets_path);
    let sibling = match siblings.get(sibling_name) {
        Some(v) => v,
        None => return json!({"value": Value::Null}),
    };
    let bucket_values: Vec<f64> = collect_bucket_values(sibling, metric_name);
    resolve_moving_avg(&bucket_values, window)
}

fn resolve_bucket_selector(
    buckets_path: &str,
    script: &str,
    siblings: &Map<String, Value>,
) -> Value {
    // Parse a simple comparison from the script string:
    //   "params.count > 10"  →  threshold = 10, operator = ">"
    // We look for the sibling bucket array and filter by the parsed condition.
    let (sibling_name, metric_name) = split_buckets_path(buckets_path);
    let sibling = match siblings.get(sibling_name) {
        Some(v) => v,
        None => return json!({"buckets": []}),
    };

    // Parse the threshold from the script (e.g. "params.count > 10").
    let (operator, threshold) = parse_simple_script(script);

    let buckets = match sibling.get("buckets").and_then(Value::as_array) {
        Some(b) => b,
        None => return json!({"buckets": []}),
    };

    let filtered: Vec<&Value> = buckets
        .iter()
        .filter(|b| {
            let val = if let Some(m) = metric_name {
                b.get(m)
                    .and_then(|mv| mv.get("value"))
                    .and_then(Value::as_f64)
            } else {
                b.get("doc_count").and_then(Value::as_f64)
            };
            if let Some(v) = val {
                match operator {
                    ">" => v > threshold,
                    ">=" => v >= threshold,
                    "<" => v < threshold,
                    "<=" => v <= threshold,
                    "==" | "=" => (v - threshold).abs() < f64::EPSILON,
                    "!=" => (v - threshold).abs() >= f64::EPSILON,
                    _ => true,
                }
            } else {
                false
            }
        })
        .collect();

    json!({"buckets": filtered})
}

fn resolve_bucket_sort(
    buckets_path: &str,
    sort: Option<&Value>,
    size: Option<usize>,
    siblings: &Map<String, Value>,
) -> Value {
    let (sibling_name, _metric_name) = split_buckets_path(buckets_path);
    let sibling = match siblings.get(sibling_name) {
        Some(v) => v,
        None => return json!({"buckets": []}),
    };

    let mut buckets: Vec<Value> = match sibling.get("buckets").and_then(Value::as_array) {
        Some(b) => b.to_vec(),
        None => return json!({"buckets": []}),
    };

    // Parse sort spec: [{"field": {"order": "desc"}}, ...]
    if let Some(sort_arr) = sort.and_then(Value::as_array) {
        for sort_item in sort_arr.iter().rev() {
            if let Some(sort_obj) = sort_item.as_object() {
                for (sort_field, sort_opts) in sort_obj {
                    let descending = match sort_opts {
                        Value::String(s) => s == "desc",
                        Value::Object(o) => o
                            .get("order")
                            .and_then(Value::as_str)
                            .map(|v| v == "desc")
                            .unwrap_or(false),
                        _ => false,
                    };
                    let sf = sort_field.clone();
                    buckets.sort_by(|a, b| {
                        let av = extract_bucket_value(a, &sf);
                        let bv = extract_bucket_value(b, &sf);
                        let cmp = av.partial_cmp(&bv).unwrap_or(std::cmp::Ordering::Equal);
                        if descending {
                            cmp.reverse()
                        } else {
                            cmp
                        }
                    });
                }
            }
        }
    }

    if let Some(sz) = size {
        buckets.truncate(sz);
    }

    json!({"buckets": buckets})
}

/// Apply `bucket_sort` / `bucket_selector` sub-pipeline aggs to a bucket list.
///
/// ES puts these pipelines INSIDE the bucket-producing agg's sub-aggs, but
/// they operate on the PARENT's bucket list (dropping/reordering entries).
/// Call this at the tail of each multi-bucket agg, after all buckets have
/// been built and populated with sub-agg metrics.
pub(crate) fn apply_bucket_pipeline_ops(
    mut buckets: Vec<Value>,
    sub_aggs: Option<&Value>,
) -> Vec<Value> {
    let sub_obj = match sub_aggs.and_then(Value::as_object) {
        Some(o) => o,
        None => return buckets,
    };

    // Collect (sub_name, agg_type, params) for every pipeline op.
    let mut ops: Vec<(String, String, Value)> = Vec::new();
    let mut parent_ops: Vec<(String, String, Value)> = Vec::new();
    for (sub_name, sub_spec) in sub_obj {
        let spec_obj = match sub_spec.as_object() {
            Some(o) => o,
            None => continue,
        };
        for (agg_type, params) in spec_obj {
            if agg_type == "bucket_sort" || agg_type == "bucket_selector" {
                ops.push((sub_name.clone(), agg_type.clone(), params.clone()));
            } else if matches!(
                agg_type.as_str(),
                "serial_diff" | "derivative" | "moving_avg" | "moving_fn" | "cumulative_sum"
            ) {
                parent_ops.push((sub_name.clone(), agg_type.clone(), params.clone()));
            }
        }
    }

    // Apply parent pipeline aggs (serial_diff, derivative, moving_avg,
    // moving_fn, cumulative_sum): each consumes the metric series across
    // the parent's buckets and writes one `{value: N}` per bucket.
    for (sub_name, agg_type, spec) in &parent_ops {
        let bp = spec
            .get("buckets_path")
            .and_then(Value::as_str)
            .unwrap_or("");
        let fmt = spec
            .get("format")
            .and_then(Value::as_str)
            .map(str::to_string);
        let values: Vec<Option<f64>> = buckets.iter().map(|b| resolve_metric_path(b, bp)).collect();
        let lag = spec.get("lag").and_then(Value::as_u64).unwrap_or(1) as usize;
        let window = spec.get("window").and_then(Value::as_u64).unwrap_or(5) as usize;
        for (i, bucket) in buckets.iter_mut().enumerate() {
            let computed: Option<f64> = match agg_type.as_str() {
                "serial_diff" => {
                    if i >= lag {
                        match (values[i], values[i - lag]) {
                            (Some(a), Some(b)) => Some(a - b),
                            _ => None,
                        }
                    } else {
                        None
                    }
                }
                "derivative" => {
                    if i >= 1 {
                        match (values[i], values[i - 1]) {
                            (Some(a), Some(b)) => Some(a - b),
                            _ => None,
                        }
                    } else {
                        None
                    }
                }
                "moving_avg" | "moving_fn" => {
                    // `shift` advances the window by N positions. Defaults
                    // to 0 (window covers the buckets *before* the current).
                    let shift = spec.get("shift").and_then(Value::as_i64).unwrap_or(0);
                    let gap_policy = spec
                        .get("gap_policy")
                        .and_then(Value::as_str)
                        .unwrap_or("skip");
                    let i_signed = i as i64;
                    let win_end_signed = i_signed + shift;
                    if win_end_signed <= 0 {
                        None
                    } else if (gap_policy == "skip") && values[i].is_none() {
                        // gap_policy=skip: if the *current* source bucket
                        // has no value, don't emit a moving_fn output at
                        // this position (ES skips the gap bucket).
                        // keep_values *does* emit at gap buckets, so
                        // that gate doesn't apply here.
                        None
                    } else {
                        let win_end = (win_end_signed as usize).min(values.len());
                        let start = win_end.saturating_sub(window);
                        let wnd: Vec<f64> = match gap_policy {
                            "insert_zeros" => values[start..win_end]
                                .iter()
                                .map(|v| v.unwrap_or(0.0))
                                .collect(),
                            "keep_values" | "keep_value" => {
                                // keep_values: treat the source stream
                                // as a dense vec of non-null values —
                                // identical to `skip` for the moving_fn
                                // window, but it also EMITS a value at
                                // gap buckets (carried over from the
                                // prior non-gap bucket's output).
                                let dense: Vec<f64> =
                                    values[..win_end].iter().filter_map(|v| *v).collect();
                                let take_from = dense.len().saturating_sub(window);
                                dense[take_from..].to_vec()
                            }
                            _ => {
                                // skip (default): treat the source series
                                // as a dense vec of non-null values and
                                // take the LAST `window` values preceding
                                // the current bucket. ES skips over gaps
                                // rather than just filtering them out of
                                // an otherwise-fixed window, so a gap at
                                // position N doesn't shrink the window
                                // used by bucket N+1 — it pulls an older
                                // value in instead.
                                let dense: Vec<f64> =
                                    values[..win_end].iter().filter_map(|v| *v).collect();
                                let take_from = dense.len().saturating_sub(window);
                                dense[take_from..].to_vec()
                            }
                        };
                        if wnd.is_empty() {
                            None
                        } else {
                            // moving_fn allows a `script` field naming the
                            // reducer function. Recognised forms: min, max,
                            // sum, stdDev, linearWeightedAvg, ewma (alpha
                            // default 0.3), unweightedAvg (default: avg).
                            let op = spec
                                .get("script")
                                .and_then(|v| {
                                    v.as_str()
                                        .or_else(|| v.get("source").and_then(Value::as_str))
                                })
                                .map(|s| s.to_ascii_lowercase())
                                .unwrap_or_default();
                            // Handle simple `fn(values) OP fn(values)`
                            // expressions by evaluating each side and
                            // combining with `+`, `-`, `*`, or `/`.
                            let eval_side = |s: &str| -> Option<f64> {
                                if s.contains("max") {
                                    Some(wnd.iter().cloned().fold(f64::NEG_INFINITY, f64::max))
                                } else if s.contains("min") {
                                    Some(wnd.iter().cloned().fold(f64::INFINITY, f64::min))
                                } else if s.contains("sum") {
                                    Some(wnd.iter().sum::<f64>())
                                } else if s.contains("unweightedavg") {
                                    Some(wnd.iter().sum::<f64>() / wnd.len() as f64)
                                } else {
                                    None
                                }
                            };
                            let combined: Option<f64> = if op.contains(") - ") || op.contains(")-")
                            {
                                let idx = op.find(") - ").unwrap_or_else(|| op.find(")-").unwrap());
                                let (l, r) = op.split_at(idx);
                                let (a, b) = (eval_side(l), eval_side(r));
                                match (a, b) {
                                    (Some(x), Some(y)) => Some(x - y),
                                    _ => None,
                                }
                            } else if op.contains(") + ") || op.contains(")+") {
                                let idx = op.find(") + ").unwrap_or_else(|| op.find(")+").unwrap());
                                let (l, r) = op.split_at(idx);
                                let (a, b) = (eval_side(l), eval_side(r));
                                match (a, b) {
                                    (Some(x), Some(y)) => Some(x + y),
                                    _ => None,
                                }
                            } else if op.contains(") * ") || op.contains(")*") {
                                let idx = op.find(") * ").unwrap_or_else(|| op.find(")*").unwrap());
                                let (l, r) = op.split_at(idx);
                                let (a, b) = (eval_side(l), eval_side(r));
                                match (a, b) {
                                    (Some(x), Some(y)) => Some(x * y),
                                    _ => None,
                                }
                            } else if op.contains(") / ") || op.contains(")/") {
                                let idx = op.find(") / ").unwrap_or_else(|| op.find(")/").unwrap());
                                let (l, r) = op.split_at(idx);
                                let (a, b) = (eval_side(l), eval_side(r));
                                match (a, b) {
                                    (Some(x), Some(y)) if y != 0.0 => Some(x / y),
                                    _ => None,
                                }
                            } else {
                                None
                            };
                            if let Some(v) = combined {
                                Some(v)
                            } else if let Some(v) = eval_movingfn_call(&op, &wnd) {
                                Some(v)
                            } else if op.contains("min") {
                                Some(wnd.iter().cloned().fold(f64::INFINITY, f64::min))
                            } else if op.contains("max") {
                                Some(wnd.iter().cloned().fold(f64::NEG_INFINITY, f64::max))
                            } else if op.contains("sum") {
                                Some(wnd.iter().sum::<f64>())
                            } else if op.contains("stddev") {
                                let mean = wnd.iter().sum::<f64>() / wnd.len() as f64;
                                let var = wnd.iter().map(|x| (x - mean).powi(2)).sum::<f64>()
                                    / wnd.len() as f64;
                                Some(var.sqrt())
                            } else if op.contains("linearweighted") {
                                // Weight i+1 across window [v_0,...v_{n-1}].
                                let n = wnd.len() as f64;
                                let total_w = n * (n + 1.0) / 2.0;
                                let weighted: f64 = wnd
                                    .iter()
                                    .enumerate()
                                    .map(|(idx, v)| v * (idx as f64 + 1.0))
                                    .sum();
                                Some(weighted / total_w)
                            } else if op.contains("ewma") {
                                // Recursive exponential smoothing with α=0.3.
                                let alpha = 0.3_f64;
                                let mut ewma = wnd[0];
                                for &v in &wnd[1..] {
                                    ewma = alpha * v + (1.0 - alpha) * ewma;
                                }
                                Some(ewma)
                            } else {
                                Some(wnd.iter().sum::<f64>() / wnd.len() as f64)
                            }
                        }
                    }
                }
                "cumulative_sum" => {
                    let sum: f64 = values[..=i].iter().filter_map(|v| *v).sum();
                    Some(sum)
                }
                _ => None,
            };
            // `__type__` tags the per-bucket pipeline result so the
            // typed_keys rewrite emits `derivative#name` (for derivative)
            // or `simple_value#name` (for moving_avg/moving_fn/serial_diff/
            // cumulative_sum — ES emits these under its SimpleValue class).
            let type_tag = match agg_type.as_str() {
                "derivative" => "derivative",
                _ => "simple_value",
            };
            let result = match computed {
                Some(v) if v.is_finite() => {
                    let num = serde_json::Number::from_f64(v)
                        .map(Value::Number)
                        .unwrap_or(Value::Null);
                    let mut m = serde_json::Map::new();
                    m.insert("value".to_string(), num);
                    if let Some(ref f) = fmt {
                        let formatted = format_number_pattern(v, f);
                        m.insert("value_as_string".to_string(), Value::String(formatted));
                    }
                    m.insert("__type__".to_string(), Value::String(type_tag.to_string()));
                    Value::Object(m)
                }
                _ => {
                    let mut m = serde_json::Map::new();
                    m.insert("value".to_string(), Value::Null);
                    m.insert("__type__".to_string(), Value::String(type_tag.to_string()));
                    Value::Object(m)
                }
            };
            if let Some(bo) = bucket.as_object_mut() {
                bo.insert(sub_name.clone(), result);
            }
        }
    }

    if ops.is_empty() {
        return buckets;
    }

    // Apply bucket_selector: drop buckets whose script evaluates to false.
    for (_, agg_type, spec) in &ops {
        if agg_type != "bucket_selector" {
            continue;
        }
        let bp_obj = spec
            .get("buckets_path")
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default();
        let script_str = spec
            .get("script")
            .and_then(|v| {
                v.as_str()
                    .or_else(|| v.get("source").and_then(Value::as_str))
            })
            .unwrap_or("")
            .to_string();
        let extra_params: HashMap<String, f64> = spec
            .get("script")
            .and_then(|v| v.get("params"))
            .and_then(|v| v.as_object())
            .map(|o| {
                o.iter()
                    .filter_map(|(k, v)| v.as_f64().map(|f| (k.clone(), f)))
                    .collect()
            })
            .unwrap_or_default();
        let gap_policy = spec
            .get("gap_policy")
            .and_then(Value::as_str)
            .unwrap_or("skip");
        buckets.retain(|bucket| {
            let mut params = extra_params.clone();
            for (alias, target) in &bp_obj {
                let tstr = match target.as_str() {
                    Some(s) => s,
                    None => return false,
                };
                match get_bucket_metric_value(bucket, tstr) {
                    Some(v) => {
                        params.insert(alias.clone(), v);
                    }
                    None => match gap_policy {
                        "insert_zeros" => {
                            params.insert(alias.clone(), 0.0);
                        }
                        _ => return false,
                    },
                }
            }
            match eval_script_expr(&script_str, &params) {
                Some(r) => r != 0.0,
                None => false,
            }
        });
    }

    // Apply bucket_sort: gap_policy → reorder → from/size.
    for (_, agg_type, spec) in &ops {
        if agg_type != "bucket_sort" {
            continue;
        }

        // Collect every sort key referenced by this bucket_sort. Gap handling
        // runs across the union of these keys.
        let sort_arr = spec
            .get("sort")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        let sort_keys: Vec<String> = sort_arr
            .iter()
            .filter_map(|item| item.as_object())
            .flat_map(|m| m.keys().cloned().collect::<Vec<_>>())
            .collect();

        // gap_policy: "skip" (default) drops buckets missing any sort key;
        // "insert_zeros" keeps them and treats missing values as 0.0.
        let gap_policy = spec
            .get("gap_policy")
            .and_then(Value::as_str)
            .unwrap_or("skip");
        // ES `gap_policy=skip` drops a bucket only when *every* sort key is
        // missing from it — a bucket with a value for the secondary key
        // survives even if the primary key has a gap (it just sorts by the
        // fallback values). `keep_values` behaves the same for bucket_sort:
        // buckets where every sort key is null/NaN are dropped from the
        // final output (they cannot be placed anywhere in the ordering).
        if (gap_policy == "skip" || gap_policy == "keep_values") && !sort_keys.is_empty() {
            buckets.retain(|b| {
                sort_keys
                    .iter()
                    .any(|k| extract_bucket_value_opt(b, k).is_some())
            });
        }

        for sort_item in sort_arr.iter().rev() {
            let sort_obj = match sort_item.as_object() {
                Some(o) => o,
                None => continue,
            };
            for (sort_field, sort_opts) in sort_obj {
                let desc = match sort_opts {
                    Value::String(s) => s == "desc",
                    Value::Object(o) => o
                        .get("order")
                        .and_then(Value::as_str)
                        .map(|v| v == "desc")
                        .unwrap_or(false),
                    _ => false,
                };
                let sf = sort_field.clone();
                let use_zero_for_missing = gap_policy == "insert_zeros";
                buckets.sort_by(|a, b| {
                    let av = extract_bucket_value_opt(a, &sf).unwrap_or(if use_zero_for_missing {
                        0.0
                    } else if desc {
                        f64::NEG_INFINITY
                    } else {
                        f64::INFINITY
                    });
                    let bv = extract_bucket_value_opt(b, &sf).unwrap_or(if use_zero_for_missing {
                        0.0
                    } else if desc {
                        f64::NEG_INFINITY
                    } else {
                        f64::INFINITY
                    });
                    let cmp = av.partial_cmp(&bv).unwrap_or(std::cmp::Ordering::Equal);
                    if desc {
                        cmp.reverse()
                    } else {
                        cmp
                    }
                });
            }
        }
        if let Some(from) = spec.get("from").and_then(Value::as_u64) {
            let from = from as usize;
            if from < buckets.len() {
                buckets = buckets.split_off(from);
            } else {
                buckets.clear();
            }
        }
        if let Some(sz) = spec.get("size").and_then(Value::as_u64) {
            buckets.truncate(sz as usize);
        }
    }

    // Strip the pipeline agg entries from every remaining bucket (ES does
    // not echo them back in the output).
    for bucket in buckets.iter_mut() {
        if let Some(bo) = bucket.as_object_mut() {
            for (name, _, _) in &ops {
                bo.remove(name);
            }
        }
    }

    buckets
}

/// Read a metric value from a bucket by `buckets_path` (e.g. `"v"` or `"v>value"`).
fn get_bucket_metric_value(bucket: &Value, path: &str) -> Option<f64> {
    if path == "_count" {
        return bucket.get("doc_count").and_then(Value::as_f64);
    }
    // top_hits subscript syntax: `top_hits_name[_source.field]` — extract
    // the named source field from the top (first) hit of a sibling top_hits
    // agg inside this bucket. `_sort` / `_score` refer to the sort-value
    // and score of that same hit (ES semantics).
    if let Some(bracket_open) = path.find('[') {
        if let Some(bracket_close) = path.rfind(']') {
            if bracket_close > bracket_open {
                let sib = &path[..bracket_open];
                let inner = &path[bracket_open + 1..bracket_close];
                let sib_val = bucket.get(sib)?;
                let top_hit = sib_val.pointer("/hits/hits/0")?;
                if let Some(rest) = inner.strip_prefix("_source.") {
                    let ptr = format!("/_source/{}", rest.replace('.', "/"));
                    return top_hit.pointer(&ptr).and_then(Value::as_f64);
                }
                if inner == "_score" {
                    return top_hit.get("_score").and_then(Value::as_f64);
                }
                if inner == "_sort" {
                    // ES `_sort` refers to the first sort value of the hit.
                    return top_hit
                        .get("sort")
                        .and_then(|v| v.as_array())
                        .and_then(|a| a.first())
                        .and_then(Value::as_f64);
                }
                if let Some(rest) = inner.strip_prefix("fields.") {
                    let arr_path = format!("/fields/{}", rest);
                    return top_hit
                        .pointer(&arr_path)
                        .and_then(|v| v.as_array())
                        .and_then(|a| a.first())
                        .and_then(Value::as_f64);
                }
            }
        }
    }
    let (sib, metric) = split_buckets_path(path);
    let sib_val = bucket.get(sib)?;
    if let Some(m) = metric {
        sib_val.get(m).and_then(|x| {
            x.get("value")
                .and_then(Value::as_f64)
                .or_else(|| x.as_f64())
        })
    } else {
        sib_val.get("value").and_then(Value::as_f64)
    }
}

/// Extract a numeric value from a bucket for sorting purposes.
fn extract_bucket_value(bucket: &Value, field: &str) -> f64 {
    extract_bucket_value_opt(bucket, field).unwrap_or(0.0)
}

/// Optional variant — returns `None` when the metric is missing or null,
/// which `bucket_sort`'s `gap_policy="skip"` uses to prune buckets.
fn extract_bucket_value_opt(bucket: &Value, field: &str) -> Option<f64> {
    if field == "_count" || field == "doc_count" {
        return bucket.get("doc_count").and_then(Value::as_f64);
    }
    if field == "_key" {
        return bucket.get("key").and_then(Value::as_f64);
    }
    let raw = bucket.get(field)?;
    if let Some(v) = raw.get("value") {
        if v.is_null() {
            return None;
        }
        return v.as_f64();
    }
    if raw.is_null() {
        return None;
    }
    raw.as_f64()
}

/// Parse a very simple comparison expression like "params.count > 10".
fn parse_simple_script(script: &str) -> (&'static str, f64) {
    for op in &[">=", "<=", "!=", ">", "<", "==", "="] {
        if let Some(pos) = script.find(op) {
            let rhs = script[pos + op.len()..].trim();
            if let Ok(threshold) = rhs.parse::<f64>() {
                let op_str: &'static str = match *op {
                    ">=" => ">=",
                    "<=" => "<=",
                    "!=" => "!=",
                    ">" => ">",
                    "<" => "<",
                    "==" => "==",
                    "=" => "=",
                    _ => ">",
                };
                return (op_str, threshold);
            }
        }
    }
    (">", 0.0)
}

/// Resolve a `bucket_script` pipeline against sibling metric aggs.
///
/// `buckets_path` is an object map `{ "alias": "sibling_agg_name" }`.
/// For each alias, read the `.value` field from the named sibling metric
/// agg in `siblings` and bind it as `params.<alias>` for the script.
/// `extra_params` are constants from `script.params` (user-supplied).
/// Then evaluate a simple arithmetic expression.
fn resolve_bucket_script(
    buckets_path: &Value,
    script: &str,
    extra_params: &HashMap<String, f64>,
    siblings: &Map<String, Value>,
) -> Value {
    // Simple string form (`"buckets_path": "some_agg"`, or the bare
    // `"buckets_path": "_count"` Timelion's `.opensearch()` datasource
    // emits for its per-time-bucket count metric): unlike the object form,
    // ES binds the resolved value to the single variable `_value` in the
    // script, regardless of the path's own name. `_count` with no sibling
    // prefix refers to the CURRENT (immediately containing) bucket's own
    // `doc_count` — `siblings` here IS that bucket's full map (see
    // `fast_aggs.rs`'s `resolve_sibling_pipelines(bucket)`), so it already
    // carries `doc_count` as a plain key alongside the sibling agg results.
    if let Some(s) = buckets_path.as_str() {
        let v = if s == "_count" {
            siblings.get("doc_count").and_then(Value::as_f64)
        } else {
            let (sib_name, metric) = split_buckets_path(s);
            siblings.get(sib_name).and_then(|sib| match metric {
                Some("_count") => sib.get("doc_count").and_then(Value::as_f64),
                Some(m) => sib.get(m).and_then(|x| {
                    x.get("value")
                        .and_then(Value::as_f64)
                        .or_else(|| x.as_f64())
                }),
                None => sib.get("value").and_then(Value::as_f64),
            })
        };
        let v = match v {
            Some(x) => x,
            None => return json!({"value": Value::Null}),
        };
        let mut params = extra_params.clone();
        params.insert("_value".to_string(), v);
        return match eval_script_expr(script, &params) {
            Some(v) => json!({"value": v}),
            None => json!({"value": Value::Null}),
        };
    }
    let bp = match buckets_path.as_object() {
        Some(o) => o,
        None => return json!({"value": Value::Null}),
    };
    let mut params: HashMap<String, f64> = extra_params.clone();
    for (alias, target) in bp {
        let t = match target.as_str() {
            Some(s) => s,
            None => continue,
        };
        // Walk "sibling>metric" if nested, else just ".value".
        let (sib_name, metric) = split_buckets_path(t);
        let sib = match siblings.get(sib_name) {
            Some(v) => v,
            None => return json!({"value": Value::Null}),
        };
        let v = if let Some(m) = metric {
            if m == "_count" {
                sib.get("doc_count").and_then(Value::as_f64)
            } else {
                sib.get(m).and_then(|x| {
                    x.get("value")
                        .and_then(Value::as_f64)
                        .or_else(|| x.as_f64())
                })
            }
        } else {
            sib.get("value").and_then(Value::as_f64)
        };
        let v = match v {
            Some(x) => x,
            None => return json!({"value": Value::Null}),
        };
        params.insert(alias.clone(), v);
    }
    match eval_script_expr(script, &params) {
        Some(v) => json!({"value": v}),
        None => json!({"value": Value::Null}),
    }
}

/// Maximum nesting the `bucket_script` / `bucket_selector` expression
/// evaluator accepts, checked on ENTRY before a single token is produced.
///
/// Mirrors `sql::MAX_SQL_DEPTH` and `xerj-query`'s `MAX_QUERY_DEPTH` (both 64).
///
/// This bound is PRE-EMPTIVE on the current tree, and it is worth being exact
/// about that. The evaluator here is `tokenize_script` -> `shunting_yard` ->
/// `evaluate_rpn`, three flat loops over a `Vec`; `?` is not even a token
/// (`tokenize_script` returns `None` on it). Measured with this bound removed
/// on a 2 MiB stack: an 80,001-byte / 20,000-ternary source returns `None`,
/// and a 1,000,000-deep parenthesised expression returns `Some(1.0)`. Nothing
/// overflows, and no released version was process-killable through this path.
///
/// The recursion arrives with the `eval_tokens` / `find_ternary_split`
/// evaluator, which re-enters once per `?` and per parenthesised
/// sub-expression. Because the release profile sets `panic = "abort"`,
/// exhausting the stack there kills the process instead of returning an error,
/// so the bound is enforced on ENTRY, before a single token is produced, and
/// lands ahead of the evaluator rather than behind it.
const MAX_EXPR_DEPTH: usize = 64;

/// Sentinel returned by [`check_expr_limits`] for an expression the evaluator
/// cannot safely walk.
const EXPR_TOO_DEEP_MSG: &str = "bucket script expression exceeds the maximum nesting depth";

/// Validate a `bucket_script` / `bucket_selector` expression against the
/// evaluator's resource limits WITHOUT evaluating it.
///
/// `Err` is returned only for genuine limit violations — oversized source, or
/// nesting beyond [`MAX_EXPR_DEPTH`]. Ordinary syntax errors stay the
/// evaluator's business and keep degrading to a null bucket value.
///
/// Both counts are taken over the raw source rather than the token stream,
/// because the recursion they bound happens *while consuming* the tokens, so
/// the budget has to be known before tokenizing. Ternaries are counted rather
/// than depth-tracked, because a right-associative chain (`a?b:c?d:e?f:g`)
/// descends one level per `?` while never opening a paren — counting `?` is the
/// only count that bounds it.
///
/// See [`MAX_EXPR_DEPTH`] for why this is pre-emptive on the current tree: the
/// evaluator it guards is still iterative, and the recursion it describes
/// arrives with the `eval_tokens` evaluator.
fn check_expr_limits(script: &str) -> Result<(), String> {
    if script.len() > crate::painless::MAX_SCRIPT_LEN {
        return Err(format!(
            "bucket script expression is {} bytes, exceeds the {}-byte limit",
            script.len(),
            crate::painless::MAX_SCRIPT_LEN
        ));
    }
    let mut paren_depth: usize = 0;
    let mut ternaries: usize = 0;
    for b in script.bytes() {
        match b {
            b'(' => {
                paren_depth += 1;
                if paren_depth > MAX_EXPR_DEPTH {
                    return Err(EXPR_TOO_DEEP_MSG.to_string());
                }
            }
            b')' => paren_depth = paren_depth.saturating_sub(1),
            b'?' => {
                ternaries += 1;
                if ternaries > MAX_EXPR_DEPTH {
                    return Err(EXPR_TOO_DEEP_MSG.to_string());
                }
            }
            _ => {}
        }
    }
    Ok(())
}

/// Evaluate a simple arithmetic / comparison expression against a params map.
///
/// Supports: numbers (incl. decimals), `params.<name>` identifiers, the
/// `null` literal (only meaningful in `==`/`!=` comparisons — matches ES
/// bucket_script scripts like Kibana/OSD TSVB's `filter_ratio`, which
/// guards against missing siblings with `params.x != null && ...`),
/// operators `+ - * / %`, comparisons `< > <= >= == !=` (yield 0.0 or 1.0),
/// logical `&&` / `||` (yield 0.0 or 1.0), the ternary `cond ? a : b`, and
/// parentheses. Honors standard precedence. Returns `None` on parse failure.
///
/// Bounded on entry by [`check_expr_limits`]: an expression past the limits
/// resolves to `None` — the same null bucket value every other unevaluable
/// script already produces — instead of overflowing the stack. The bound is
/// taken once, here, over the whole source: [`eval_tokens`] recurses into
/// itself (not back through this function) in exactly two ways, and each
/// consumes budget the entry check already counted —
///
///   * a ternary split consumes the one `?` it split on, and `?`s are capped
///     at `MAX_EXPR_DEPTH`;
///   * folding a parenthesised ternary ([`fold_paren_ternaries`]) descends
///     through one paren pair, and paren depth is capped at `MAX_EXPR_DEPTH`.
///
/// So the deepest a source that passes the entry check can descend is
/// `2 * MAX_EXPR_DEPTH + 1` frames.
fn eval_script_expr(script: &str, params: &HashMap<String, f64>) -> Option<f64> {
    if check_expr_limits(script).is_err() {
        return None;
    }
    let tokens = tokenize_script(script, params)?;
    eval_tokens(&tokens)
}

/// Evaluate a token slice, handling the ternary operator (which the
/// operator-precedence shunting-yard below doesn't model) before falling back
/// to ordinary shunting-yard + RPN evaluation.
///
/// Two shapes, because `find_ternary_split` only sees paren-depth 0:
///
///   * `cond ? a : b` at this level — split and recurse into the three parts;
///   * a ternary nested inside parentheses, `(cond ? a : b) + 1`, or a ternary
///     branch that is itself parenthesised, `x ? (y ? 1 : 2) : 3` — those
///     never reach a top-level split, and any `?` that survives into
///     `shunting_yard` makes it bail. [`fold_paren_ternaries`] collapses each
///     such group to the number it evaluates to first.
///
/// Without the second case `(1 ? 1 : 0)` — legal Elasticsearch, and the
/// natural way to write anything nested — resolved to a null bucket value.
fn eval_tokens(toks: &[Tok]) -> Option<f64> {
    if let Some((q_idx, c_idx)) = find_ternary_split(toks) {
        let cond = eval_tokens(&toks[..q_idx])?;
        return if cond != 0.0 {
            eval_tokens(&toks[q_idx + 1..c_idx])
        } else {
            eval_tokens(&toks[c_idx + 1..])
        };
    }
    if toks.iter().any(|t| matches!(t, Tok::Question)) {
        let folded = fold_paren_ternaries(toks)?;
        let rpn = shunting_yard(&folded)?;
        return evaluate_rpn(&rpn);
    }
    let rpn = shunting_yard(toks)?;
    evaluate_rpn(&rpn)
}

/// Replace every parenthesised group that contains a `?` with the single
/// number it evaluates to, leaving groups without one untouched for
/// `shunting_yard` to handle as ordinary precedence overrides.
///
/// Outermost-first: the whole group goes back through [`eval_tokens`], so an
/// inner ternary is handled by that call's own split, however deeply the two
/// forms alternate. `None` when a group is unbalanced or its contents don't
/// evaluate — the same null bucket value any other unevaluable script gets.
fn fold_paren_ternaries(toks: &[Tok]) -> Option<Vec<Tok>> {
    let mut out: Vec<Tok> = Vec::with_capacity(toks.len());
    let mut i = 0;
    while i < toks.len() {
        if matches!(toks[i], Tok::LParen) {
            let mut depth = 0i32;
            let mut close = None;
            for (j, t) in toks.iter().enumerate().skip(i) {
                match t {
                    Tok::LParen => depth += 1,
                    Tok::RParen => {
                        depth -= 1;
                        if depth == 0 {
                            close = Some(j);
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let close = close?;
            let inner = &toks[i + 1..close];
            if inner.iter().any(|t| matches!(t, Tok::Question)) {
                out.push(Tok::Num(eval_tokens(inner)?));
            } else {
                out.extend_from_slice(&toks[i..=close]);
            }
            i = close + 1;
        } else {
            out.push(toks[i].clone());
            i += 1;
        }
    }
    Some(out)
}

/// Find the first top-level (paren-depth 0) `?` and its matching top-level
/// `:`. Returns `None` when there's no ternary at this nesting level.
fn find_ternary_split(toks: &[Tok]) -> Option<(usize, usize)> {
    let mut depth = 0i32;
    let mut q_idx = None;
    for (i, t) in toks.iter().enumerate() {
        match t {
            Tok::LParen => depth += 1,
            Tok::RParen => depth -= 1,
            Tok::Question if depth == 0 => {
                q_idx = Some(i);
                break;
            }
            _ => {}
        }
    }
    let q = q_idx?;
    let mut depth = 0i32;
    for (i, t) in toks.iter().enumerate().skip(q + 1) {
        match t {
            Tok::LParen => depth += 1,
            Tok::RParen => depth -= 1,
            Tok::Colon if depth == 0 => return Some((q, i)),
            _ => {}
        }
    }
    None
}

#[derive(Debug, Clone)]
enum Tok {
    Num(f64),
    Null,
    Op(&'static str),
    LParen,
    RParen,
    Question,
    Colon,
}

fn tokenize_script(s: &str, params: &HashMap<String, f64>) -> Option<Vec<Tok>> {
    let bytes = s.as_bytes();
    let mut toks = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i] as char;
        // ASCII-only, for the same reason `painless::tokenize` is (#207): this
        // scanner walks BYTES (`bytes[i] as char` reinterprets each byte as
        // Latin-1) but slices `&s[..]` as a `&str`. `is_whitespace()` is true
        // for Latin-1 NEL (0x85) and NBSP (0xA0), and in valid UTF-8 both of
        // those bytes are only ever *continuation* bytes — accepting them steps
        // `i` into the middle of a character, and the next slice panics on a
        // char boundary. No real script loses anything: those are the only two
        // non-ASCII bytes the old test accepted.
        if c.is_ascii_whitespace() {
            i += 1;
            continue;
        }
        if c.is_ascii_digit()
            || (c == '.' && i + 1 < bytes.len() && (bytes[i + 1] as char).is_ascii_digit())
        {
            let start = i;
            while i < bytes.len()
                && ((bytes[i] as char).is_ascii_digit() || bytes[i] as char == '.')
            {
                i += 1;
            }
            let n: f64 = s[start..i].parse().ok()?;
            toks.push(Tok::Num(n));
            continue;
        }
        if c.is_ascii_alphabetic() || c == '_' {
            let start = i;
            while i < bytes.len()
                && ((bytes[i] as char).is_ascii_alphanumeric()
                    || bytes[i] as char == '_'
                    || bytes[i] as char == '.')
            {
                i += 1;
            }
            let ident = &s[start..i];
            if let Some(rest) = ident.strip_prefix("params.") {
                let v = *params.get(rest)?;
                toks.push(Tok::Num(v));
            } else if ident == "null" {
                toks.push(Tok::Null);
            } else {
                let v = *params.get(ident)?;
                toks.push(Tok::Num(v));
            }
            continue;
        }
        // Two-character operators first.
        //
        // `&s[i..i + 2]` is a `&str` slice on a byte index, so it panics unless
        // BOTH ends sit on a character boundary. Every arm above this one is
        // ASCII-only, so a multi-byte character's lead byte falls straight
        // through to here and `i + 2` lands inside it —
        // `{"bs":{"bucket_script":{"buckets_path":{"x":"s"},"script":"1 中 2"}}}`
        // in an ordinary `_search` body was `end byte index 2 is not a char
        // boundary`, and `panic = "abort"` makes that the process (#207).
        // Every two-character operator is pure ASCII, so requiring both bytes
        // to be ASCII keeps the slice on a boundary by construction; a
        // non-ASCII byte falls to the `_ => return None` arm below, which is
        // the right answer for an operator this subset cannot evaluate.
        if i + 1 < bytes.len() && bytes[i].is_ascii() && bytes[i + 1].is_ascii() {
            let two = &s[i..i + 2];
            match two {
                ">=" | "<=" | "==" | "!=" | "&&" | "||" => {
                    let op: &'static str = match two {
                        ">=" => ">=",
                        "<=" => "<=",
                        "==" => "==",
                        "!=" => "!=",
                        "&&" => "&&",
                        "||" => "||",
                        _ => unreachable!(),
                    };
                    toks.push(Tok::Op(op));
                    i += 2;
                    continue;
                }
                _ => {}
            }
        }
        match c {
            '+' => {
                toks.push(Tok::Op("+"));
            }
            '-' => {
                toks.push(Tok::Op("-"));
            }
            '*' => {
                toks.push(Tok::Op("*"));
            }
            '/' => {
                toks.push(Tok::Op("/"));
            }
            '%' => {
                toks.push(Tok::Op("%"));
            }
            '<' => {
                toks.push(Tok::Op("<"));
            }
            '>' => {
                toks.push(Tok::Op(">"));
            }
            '(' => {
                toks.push(Tok::LParen);
            }
            ')' => {
                toks.push(Tok::RParen);
            }
            '?' => {
                toks.push(Tok::Question);
            }
            ':' => {
                toks.push(Tok::Colon);
            }
            ';' => {} // ignore trailing semicolons
            _ => return None,
        }
        i += 1;
    }
    Some(toks)
}

fn precedence(op: &str) -> u8 {
    match op {
        "||" => 1,
        "&&" => 2,
        "==" | "!=" => 3,
        "<" | ">" | "<=" | ">=" => 4,
        "+" | "-" => 5,
        "*" | "/" | "%" => 6,
        _ => 0,
    }
}

fn shunting_yard(toks: &[Tok]) -> Option<Vec<Tok>> {
    let mut out: Vec<Tok> = Vec::new();
    let mut ops: Vec<Tok> = Vec::new();
    for t in toks {
        match t {
            Tok::Num(_) | Tok::Null => out.push(t.clone()),
            Tok::Op(o) => {
                while let Some(Tok::Op(top)) = ops.last() {
                    if precedence(top) >= precedence(o) {
                        out.push(ops.pop().unwrap());
                    } else {
                        break;
                    }
                }
                ops.push(t.clone());
            }
            Tok::LParen => ops.push(t.clone()),
            Tok::RParen => {
                while let Some(top) = ops.pop() {
                    match top {
                        Tok::LParen => break,
                        op => out.push(op),
                    }
                }
            }
            // `eval_tokens` strips ternary tokens out before a slice reaches
            // shunting_yard — via `find_ternary_split` at this level, and via
            // `fold_paren_ternaries` for parenthesised ones. Reaching here
            // means an unbalanced `?` with no matching `:` (or a stray `:`),
            // which is a syntax error, not a shape this evaluator declines.
            Tok::Question | Tok::Colon => return None,
        }
    }
    while let Some(op) = ops.pop() {
        if matches!(op, Tok::LParen | Tok::RParen) {
            return None;
        }
        out.push(op);
    }
    Some(out)
}

/// A resolved operand on the RPN evaluation stack — either a real number or
/// the `null` literal, which only `==`/`!=` know how to compare against.
#[derive(Debug, Clone, Copy)]
enum EvalVal {
    Num(f64),
    Null,
}

fn evaluate_rpn(rpn: &[Tok]) -> Option<f64> {
    let mut stack: Vec<EvalVal> = Vec::new();
    for t in rpn {
        match t {
            Tok::Num(n) => stack.push(EvalVal::Num(*n)),
            Tok::Null => stack.push(EvalVal::Null),
            Tok::Op(op) => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                // `==` / `!=` are the only operators that accept the `null`
                // literal, so they run off `EvalVal` rather than two f64s.
                //
                // This is NOT a refactor of the pre-#95 numeric-only arms —
                // it changes what `!=` answers when an operand is NaN, and
                // deliberately so. The old `!=` was
                // `(a - b).abs() >= 1e-9`, and every comparison against NaN
                // is false, so `NaN != 0` returned 0.0 — i.e. "they are
                // equal". Deriving `!=` as the negation of `==` makes
                // `NaN != x` report 1.0, which is what IEEE-754, Java and
                // therefore Painless all say. Measured end to end on
                // `params.a * params.a - params.a * params.a != 0` over a
                // single doc with `n = 1e308` (the product overflows to
                // +inf, inf - inf is NaN): 0.0 before, 1.0 after. `==` is
                // unchanged — `NaN == x` was 0.0 and still is. Pinned by
                // `ne_against_a_nan_operand_is_true_not_false`.
                //
                // The `x == y` short-circuit is load-bearing, not an
                // optimisation. Two EQUAL infinities are not NaN and must
                // compare equal, but `inf - inf` IS NaN, so the epsilon test
                // alone reports them unequal: measured, `params.a * params.a
                // != params.a * params.a` over `n = 1e308` answered 1.0 with
                // only the epsilon, where IEEE-754 and the JLS both say
                // `inf == inf`. Exact equality first, epsilon second, keeps
                // NaN reporting unequal (`NaN == NaN` is false and
                // `(NaN).abs() < 1e-9` is false) while equal infinities and
                // ordinary equal values report equal. Pinned by
                // `eq_between_two_equal_infinities_is_true`.
                let r = if *op == "==" || *op == "!=" {
                    let eq = match (a, b) {
                        (EvalVal::Num(x), EvalVal::Num(y)) => x == y || (x - y).abs() < 1e-9,
                        (EvalVal::Null, EvalVal::Null) => true,
                        _ => false,
                    };
                    EvalVal::Num(if eq == (*op == "==") { 1.0 } else { 0.0 })
                } else {
                    let (EvalVal::Num(a), EvalVal::Num(b)) = (a, b) else {
                        return None;
                    };
                    EvalVal::Num(match *op {
                        "+" => a + b,
                        "-" => a - b,
                        "*" => a * b,
                        "/" => {
                            if b == 0.0 {
                                return None;
                            } else {
                                a / b
                            }
                        }
                        "%" => {
                            if b == 0.0 {
                                return None;
                            } else {
                                a % b
                            }
                        }
                        "<" => {
                            if a < b {
                                1.0
                            } else {
                                0.0
                            }
                        }
                        ">" => {
                            if a > b {
                                1.0
                            } else {
                                0.0
                            }
                        }
                        "<=" => {
                            if a <= b {
                                1.0
                            } else {
                                0.0
                            }
                        }
                        ">=" => {
                            if a >= b {
                                1.0
                            } else {
                                0.0
                            }
                        }
                        "&&" => {
                            if a != 0.0 && b != 0.0 {
                                1.0
                            } else {
                                0.0
                            }
                        }
                        "||" => {
                            if a != 0.0 || b != 0.0 {
                                1.0
                            } else {
                                0.0
                            }
                        }
                        _ => return None,
                    })
                };
                stack.push(r);
            }
            _ => return None,
        }
    }
    if stack.len() == 1 {
        match stack[0] {
            EvalVal::Num(n) => Some(n),
            EvalVal::Null => None,
        }
    } else {
        None
    }
}

#[cfg(test)]
mod bucket_script_expr_limit_tests {
    //! The `bucket_script` / `bucket_selector` expression evaluator takes an
    //! arbitrary-length string straight off an unauthenticated request, so its
    //! resource limits are enforced on entry, before tokenizing.
    //!
    //! These tests pin the BOUND, not a crash. The evaluator on this tree is
    //! iterative and does not overflow: see [`MAX_EXPR_DEPTH`] for the
    //! measurements. The bound exists ahead of the `eval_tokens` evaluator,
    //! which walks the token stream recursively (nested parens; the ternary
    //! `cond ? a : b` split, once per `?`) and, with `panic = "abort"` in the
    //! release profile, would turn stack exhaustion into a process kill rather
    //! than an error response.
    use super::*;

    fn no_params() -> HashMap<String, f64> {
        HashMap::new()
    }

    #[test]
    fn deeply_nested_parens_are_rejected_instead_of_evaluated() {
        let src = format!("{}1{}", "(".repeat(5000), ")".repeat(5000));
        assert!(
            check_expr_limits(&src).is_err(),
            "5000-deep parens must trip the entry bound"
        );
        assert_eq!(
            eval_script_expr(&src, &no_params()),
            None,
            "an over-deep expression must resolve to a null bucket value"
        );
    }

    #[test]
    fn chained_ternaries_are_bounded_by_their_count_not_their_paren_depth() {
        // The reported repro, verbatim: a right-associative ternary chain
        // whose conditions are all false, so every step descends into the
        // tail. It never opens a paren, yet a ternary-splitting evaluator
        // re-enters itself once per `?` — counting `?` is the only thing that
        // bounds it. Measured against that evaluator in an optimized build:
        // 80,001 bytes (20k ternaries) overflows a 2 MiB worker stack and
        // SIGABRTs the process; the entry bound below rejects it in ~5 µs.
        let src = format!("{}1", "0?1:".repeat(20_000));
        assert_eq!(src.len(), 80_001, "the fixture must be the ~80 KB repro");
        assert_eq!(
            src.matches('?').count(),
            20_000,
            "the fixture must actually be a 20k-deep ternary chain"
        );
        assert!(
            check_expr_limits(&src).is_err(),
            "a 20k ternary chain must trip the entry bound"
        );
        assert_eq!(eval_script_expr(&src, &no_params()), None);
    }

    #[test]
    fn nested_ternaries_are_rejected_instead_of_evaluated() {
        // The other spelling of the same attack: each ternary nested inside
        // the previous one's false branch.
        let src = format!("0?1:{}1{}", "(0?1:".repeat(10_000), ")".repeat(10_000));
        assert!(check_expr_limits(&src).is_err());
        assert_eq!(eval_script_expr(&src, &no_params()), None);
    }

    #[test]
    fn oversized_expression_is_rejected_instead_of_evaluated() {
        // Valid arithmetic — the pre-bound evaluator happily tokenizes and
        // folds all of it — but far past the 64 KiB source limit.
        let src = format!("{}1", "1+".repeat(crate::painless::MAX_SCRIPT_LEN));
        assert!(src.len() > crate::painless::MAX_SCRIPT_LEN);
        assert!(check_expr_limits(&src).is_err());
        assert_eq!(eval_script_expr(&src, &no_params()), None);
    }

    #[test]
    fn ordinary_expressions_still_evaluate() {
        let mut params = HashMap::new();
        params.insert("numerator".to_string(), 8.0);
        params.insert("denominator".to_string(), 2.0);
        assert_eq!(
            eval_script_expr("params.numerator / params.denominator", &params),
            Some(4.0)
        );
        // Nesting right up to the bound is still accepted — the limit only
        // rejects what no generated script produces.
        let deep_ok = format!(
            "{}params.numerator{}",
            "(".repeat(MAX_EXPR_DEPTH),
            ")".repeat(MAX_EXPR_DEPTH)
        );
        assert!(check_expr_limits(&deep_ok).is_ok());
        assert_eq!(eval_script_expr(&deep_ok, &params), Some(8.0));
    }

    #[test]
    fn an_over_deep_bucket_script_resolves_to_null_not_a_crash() {
        // End to end through the pipeline resolver: the bucket keeps its
        // shape and reports a null value, exactly like any other script the
        // evaluator can't handle.
        let mut siblings = Map::new();
        siblings.insert("total".to_string(), json!({"value": 10.0}));
        let bp = json!({"t": "total"});
        let src = format!("{}params.t{}", "(".repeat(5000), ")".repeat(5000));
        assert_eq!(
            resolve_bucket_script(&bp, &src, &HashMap::new(), &siblings),
            json!({"value": Value::Null})
        );
    }

    #[test]
    fn a_ternary_inside_parentheses_evaluates() {
        // `find_ternary_split` only looks at paren-depth 0, and `shunting_yard`
        // bails on any `?` that reaches it. So before `fold_paren_ternaries`
        // every one of these — all legal Elasticsearch bucket_script sources —
        // resolved to a null bucket value. Measured, verbatim, on the branch
        // this fixes: `(1?1:0)`, `(1?1:0) + 1`, `1 + (1?1:0)`,
        // `0?1:(0?2:3)`, `(0?1:2) * 10`, `(1>0 ? 1 : 0) + 1` and
        // `1?(1?5:6):0` ALL returned `None`.
        let p = no_params();
        for (src, want) in [
            ("(1?1:0)", 1.0),
            ("(0?1:0)", 0.0),
            ("(1?1:0) + 1", 2.0),
            ("1 + (1?1:0)", 2.0),
            ("(0?1:2) * 10", 20.0),
            ("(1>0 ? 1 : 0) + 1", 2.0),
            // Nested both ways round: inside a branch, and inside a condition.
            ("0?1:(0?2:3)", 3.0),
            ("1?(1?5:6):0", 5.0),
            ("(1?1:0) ? 7 : 8", 7.0),
            ("(1?0:1) ? 7 : 8", 8.0),
            // Parens that hold no ternary keep behaving as plain precedence
            // overrides, and a top-level ternary still splits as before.
            ("(1+2)*3", 9.0),
            ("1?2:3", 2.0),
            ("0?2:3", 3.0),
            // Right-associative chain, unparenthesised and parenthesised.
            ("0?1:0?2:3", 3.0),
            ("0?1:(0?2:3)", 3.0),
        ] {
            assert_eq!(
                eval_script_expr(src, &p),
                Some(want),
                "`{src}` must evaluate to {want}"
            );
        }

        // A `?` with no matching `:` is still a syntax error, not a value.
        assert_eq!(eval_script_expr("(1?1)", &p), None);
        assert_eq!(eval_script_expr("(1:1)", &p), None);
    }

    #[test]
    fn parenthesised_ternaries_stay_inside_the_entry_bound() {
        // Folding recurses through one paren pair per frame, so the entry
        // bound has to cover paren depth as well as `?` count. A chain that
        // alternates the two forms is the worst case for the combined
        // `2 * MAX_EXPR_DEPTH + 1` argument in `eval_script_expr`'s docs.
        //
        // Right at the bound: accepted and correct.
        let n = MAX_EXPR_DEPTH / 2;
        let src = format!("{}9{}", "(0?1:".repeat(n), ")".repeat(n));
        assert!(check_expr_limits(&src).is_ok());
        assert_eq!(eval_script_expr(&src, &no_params()), Some(9.0));

        // Far past it: rejected on entry, before a token is produced. If the
        // bound ever stops covering the fold recursion this overflows the
        // test process's stack rather than failing an assertion.
        let deep = format!("{}9{}", "(0?1:".repeat(10_000), ")".repeat(10_000));
        assert!(check_expr_limits(&deep).is_err());
        assert_eq!(eval_script_expr(&deep, &no_params()), None);
    }

    #[test]
    fn ne_against_a_nan_operand_is_true_not_false() {
        // `!=` is derived as the negation of `==` rather than as its own
        // `(a - b).abs() >= 1e-9` test, and that CHANGED an answer: every
        // comparison against NaN is false, so the old form reported
        // `NaN != 0` as 0.0 — "they are equal". Measured by restoring the old
        // arms on this tree: 0.0 before, 1.0 after, for the aggregation in
        // `nan_operand_ne_reports_inequality_end_to_end` below.
        //
        // 1.0 is what IEEE-754 (and therefore Java, and therefore Painless)
        // says, so the new answer is the correct one — this test exists so
        // the change is deliberate and visible, not so it stays frozen.
        let mut p = HashMap::new();
        p.insert("nan".to_string(), f64::NAN);
        p.insert("zero".to_string(), 0.0);
        assert_eq!(eval_script_expr("params.nan != params.zero", &p), Some(1.0));
        assert_eq!(eval_script_expr("params.nan != params.nan", &p), Some(1.0));
        // `==` is untouched: NaN compares equal to nothing, including itself.
        assert_eq!(eval_script_expr("params.nan == params.zero", &p), Some(0.0));
        assert_eq!(eval_script_expr("params.nan == params.nan", &p), Some(0.0));
        // Non-NaN operands are unaffected — same 1e-9 epsilon, both ways.
        p.insert("a".to_string(), 1.0);
        p.insert("b".to_string(), 1.0 + 1e-12);
        p.insert("c".to_string(), 2.0);
        assert_eq!(eval_script_expr("params.a == params.b", &p), Some(1.0));
        assert_eq!(eval_script_expr("params.a != params.b", &p), Some(0.0));
        assert_eq!(eval_script_expr("params.a == params.c", &p), Some(0.0));
        assert_eq!(eval_script_expr("params.a != params.c", &p), Some(1.0));
    }

    #[test]
    fn eq_between_two_equal_infinities_is_true() {
        // Regression: deriving `==` from `(x - y).abs() < 1e-9` alone is wrong
        // for infinities, because `inf - inf` is NaN and NaN fails the epsilon
        // test — so two IDENTICAL values compared unequal. IEEE-754 and the
        // JLS both say `inf == inf`, and this is reachable from an ordinary
        // script: `params.a * params.a` overflows to +inf for a = 1e308, which
        // is exactly the shape `nan_operand_ne_reports_inequality_end_to_end`
        // builds on.
        let mut p = HashMap::new();
        p.insert("inf".to_string(), f64::INFINITY);
        p.insert("ninf".to_string(), f64::NEG_INFINITY);
        p.insert("big".to_string(), 1e308);

        assert_eq!(eval_script_expr("params.inf == params.inf", &p), Some(1.0));
        assert_eq!(eval_script_expr("params.inf != params.inf", &p), Some(0.0));
        assert_eq!(
            eval_script_expr("params.ninf == params.ninf", &p),
            Some(1.0)
        );
        assert_eq!(
            eval_script_expr("params.ninf != params.ninf", &p),
            Some(0.0)
        );

        // Opposite infinities are genuinely unequal.
        assert_eq!(eval_script_expr("params.inf == params.ninf", &p), Some(0.0));
        assert_eq!(eval_script_expr("params.inf != params.ninf", &p), Some(1.0));

        // The end-to-end shape from the report: the product overflows to +inf
        // on both sides, so the two operands are equal and `!=` must be false.
        assert_eq!(
            eval_script_expr("params.big * params.big != params.big * params.big", &p),
            Some(0.0)
        );
        assert_eq!(
            eval_script_expr("params.big * params.big == params.big * params.big", &p),
            Some(1.0)
        );

        // And NaN still reports unequal, which is the behaviour
        // `ne_against_a_nan_operand_is_true_not_false` pins.
        assert_eq!(
            eval_script_expr("params.big * params.big - params.big * params.big != 0", &p),
            Some(1.0)
        );
    }
}

fn split_buckets_path(buckets_path: &str) -> (&str, Option<&str>) {
    if let Some(pos) = buckets_path.find('>') {
        (&buckets_path[..pos], Some(&buckets_path[pos + 1..]))
    } else if let Some(pos) = buckets_path.find('.') {
        // Dot form is a valid ES shorthand for the `<agg>>.<metric>`
        // syntax when the first segment uniquely identifies a sibling.
        // The caller's fallback path (`resolve_metric_path` on the
        // bucket with the full tail) still needs the full dotted tail
        // for subscript/dotted metric lookup (e.g.
        // `percentiles.values[99.9]`).
        (&buckets_path[..pos], Some(&buckets_path[pos + 1..]))
    } else {
        (buckets_path, None)
    }
}

/// Collect per-bucket numeric values from a sibling aggregation result.
fn collect_bucket_values(sibling: &Value, metric_name: Option<&str>) -> Vec<f64> {
    collect_bucket_values_with_policy(sibling, metric_name, "skip")
}

/// Collect sibling bucket metric values, applying the pipeline-agg `gap_policy`.
/// - `skip` (default): drop buckets with missing/null metric
/// - `insert_zeros`: treat missing as 0.0
/// - `keep_values`: ES 8.6+ — keep non-null non-NaN; drop null/NaN
///
/// `metric_name` supports dotted paths (`stats.sum`) and subscript notation
/// (`percentiles[99.9]`, `extended_stats[std_deviation]`).
fn collect_bucket_values_with_policy(
    sibling: &Value,
    metric_name: Option<&str>,
    gap_policy: &str,
) -> Vec<f64> {
    let buckets = match sibling.get("buckets").and_then(Value::as_array) {
        Some(b) => b,
        None => return vec![],
    };
    let mut out = Vec::with_capacity(buckets.len());
    for b in buckets {
        // When the bucket has zero docs, ES treats all its metric
        // sub-aggs as "missing" for the parent pipeline (regardless of
        // whether the metric emitted `0.0` or `null`). Honor gap_policy
        // the same way — `skip` drops the bucket, `insert_zeros` inserts
        // zero, `keep_values` drops.
        let doc_count = b.get("doc_count").and_then(Value::as_u64).unwrap_or(0);
        let bucket_empty = doc_count == 0 && metric_name.is_some();
        let v: Option<f64> = if bucket_empty {
            None
        } else if let Some(metric) = metric_name {
            resolve_metric_path(b, metric)
        } else {
            b.get("doc_count").and_then(Value::as_f64)
        };
        match v {
            Some(n) if n.is_finite() => out.push(n),
            _ => {
                match gap_policy {
                    "insert_zeros" => out.push(0.0),
                    "keep_values" => { /* drop null/NaN */ }
                    _ => { /* "skip" default: drop */ }
                }
            }
        }
    }
    out
}

/// Resolve a pipeline `buckets_path` metric expression against a single
/// bucket. Handles:
///   - plain metric name: `v` → v.value (or v doc_count)
///   - subscript: `v[99.9]` → v.values."99.9"
///   - dotted path: `stats.sum` → stats.sum
///   - multi-hop: `range.bucket_name>v` not handled here (resolved earlier)
fn resolve_metric_path(bucket: &Value, path: &str) -> Option<f64> {
    // Subscript form: name[key]
    if let Some(open) = path.find('[') {
        if let Some(close) = path[open..].find(']') {
            let base = &path[..open];
            let key = &path[open + 1..open + close];
            // Try both "values.<key>" (percentiles) and direct child.
            let node = bucket.get(base)?;
            if let Some(v) = node
                .get("values")
                .and_then(|vals| vals.get(key))
                .and_then(Value::as_f64)
            {
                return Some(v);
            }
            // Numeric percentile rendered as number (not string)
            if let Ok(n) = key.parse::<f64>() {
                if let Some(vals) = node.get("values").and_then(Value::as_object) {
                    for (k, v) in vals {
                        if k.parse::<f64>()
                            .ok()
                            .map(|x| (x - n).abs() < 1e-6)
                            .unwrap_or(false)
                        {
                            return v.as_f64();
                        }
                    }
                }
            }
            if let Some(v) = node.get(key).and_then(Value::as_f64) {
                return Some(v);
            }
            return None;
        }
    }
    // Dotted path: a.b.c
    if path.contains('.') {
        // Special case: `<metric>.<percent>` where metric is percentiles
        // or percentile_ranks with `values` either as array-of-`{key,value}`
        // (keyed:false) or map of percent→value (keyed:true). Resolve the
        // percent numerically so `the_percentiles.99` matches `{key: 99.0}`
        // and `{"99.0": ...}` alike.
        let mut segs = path.split('.');
        if let (Some(first), Some(rest)) = (segs.next(), segs.next()) {
            if segs.next().is_none() {
                // Exactly two segments — try the percentiles path.
                if let Ok(key_num) = rest.parse::<f64>() {
                    if let Some(node) = bucket.get(first) {
                        if let Some(values) = node.get("values") {
                            match values {
                                Value::Array(arr) => {
                                    for entry in arr {
                                        let k = entry.get("key").and_then(Value::as_f64);
                                        if let Some(k) = k {
                                            if (k - key_num).abs() < 1e-6 {
                                                return entry.get("value").and_then(Value::as_f64);
                                            }
                                        }
                                    }
                                }
                                Value::Object(map) => {
                                    for (k, v) in map {
                                        if k.parse::<f64>()
                                            .ok()
                                            .map(|x| (x - key_num).abs() < 1e-6)
                                            .unwrap_or(false)
                                        {
                                            return v.as_f64();
                                        }
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
        let mut cur = bucket;
        for seg in path.split('.') {
            cur = cur.get(seg)?;
        }
        return cur.as_f64();
    }
    // Plain: name → name.value
    let node = bucket.get(path)?;
    if let Some(v) = node.get("value").and_then(Value::as_f64) {
        return Some(v);
    }
    // Single-percentile special case: a `percentiles` sibling with one
    // percent returns `values` as either a one-entry map or a one-entry
    // array of `{key, value}`. ES 8.4+ lets max_bucket/min_bucket/avg_bucket
    // resolve a percentiles sibling with a single percent by taking that
    // single value directly (no subscript required).
    if let Some(values) = node.get("values") {
        match values {
            Value::Object(map) if map.len() == 1 => {
                if let Some((_, v)) = map.iter().next() {
                    if let Some(f) = v.as_f64() {
                        return Some(f);
                    }
                }
            }
            Value::Array(arr) if arr.len() == 1 => {
                if let Some(f) = arr[0].get("value").and_then(Value::as_f64) {
                    return Some(f);
                }
            }
            _ => {}
        }
    }
    node.as_f64()
}

/// Collect the `key` (or `key_as_string`) of every sibling bucket whose metric
/// value equals `target_value`.  Used by `max_bucket` / `min_bucket` to emit
/// the ES `keys: [...]` field.
fn collect_bucket_keys_matching_value(
    sibling: &Value,
    metric_name: Option<&str>,
    target_value: f64,
) -> Vec<Value> {
    let buckets = match sibling.get("buckets").and_then(Value::as_array) {
        Some(b) => b,
        None => return vec![],
    };
    let mut out = Vec::new();
    for b in buckets {
        let v = if let Some(metric) = metric_name {
            // Use the full `resolve_metric_path` — handles plain
            // "name.value", subscript `[99.9]`, dotted stats paths,
            // and the single-percentile fallback (a `percentiles`
            // metric with one percent resolves to its single value).
            resolve_metric_path(b, metric)
        } else {
            b.get("doc_count").and_then(Value::as_f64)
        };
        if let Some(v) = v {
            if (v - target_value).abs() < 1e-9 {
                let k = b
                    .get("key_as_string")
                    .or_else(|| b.get("key"))
                    .cloned()
                    .unwrap_or(Value::Null);
                out.push(k);
            }
        }
    }
    out
}

fn resolve_pipeline_agg_with_gap(
    agg_type: &str,
    buckets_path: &str,
    siblings: &Map<String, Value>,
    gap_policy: &str,
) -> Value {
    let (sibling_name, metric_name) = split_buckets_path(buckets_path);

    let sibling = match siblings.get(sibling_name) {
        Some(v) => v,
        None => return json!({"value": Value::Null}),
    };

    let bucket_values = collect_bucket_values_with_policy(sibling, metric_name, gap_policy);

    if bucket_values.is_empty() {
        // ES `sum_bucket` of an empty series returns 0.0, not null — the
        // identity for addition. Other bucket aggs keep null since they
        // have no meaningful value on an empty input.
        if agg_type == "sum_bucket" {
            return json!({"value": 0.0});
        }
        if agg_type == "percentiles_bucket" {
            // Preserve the values-map shape with all-null entries so
            // path lookups like `agg.values.50_0` still resolve cleanly.
            let pcts = [1.0, 5.0, 25.0, 50.0, 75.0, 95.0, 99.0];
            let mut values = serde_json::Map::new();
            for p in &pcts {
                values.insert(format!("{:.1}", p), Value::Null);
            }
            return json!({"values": Value::Object(values)});
        }
        return json!({"value": Value::Null});
    }

    match agg_type {
        "avg_bucket" => {
            let sum: f64 = bucket_values.iter().sum();
            make_value_result(sum / bucket_values.len() as f64)
        }
        "max_bucket" => {
            let value = bucket_values
                .iter()
                .cloned()
                .fold(f64::NEG_INFINITY, f64::max);
            let keys = collect_bucket_keys_matching_value(sibling, metric_name, value);
            let mut r = make_value_result(value);
            if let Some(obj) = r.as_object_mut() {
                obj.insert("keys".into(), Value::Array(keys));
            }
            r
        }
        "min_bucket" => {
            let value = bucket_values.iter().cloned().fold(f64::INFINITY, f64::min);
            let keys = collect_bucket_keys_matching_value(sibling, metric_name, value);
            let mut r = make_value_result(value);
            if let Some(obj) = r.as_object_mut() {
                obj.insert("keys".into(), Value::Array(keys));
            }
            r
        }
        "sum_bucket" => make_value_result(bucket_values.iter().sum()),
        "stats_bucket" => {
            let count = bucket_values.len() as f64;
            let sum: f64 = bucket_values.iter().sum();
            let min = bucket_values.iter().cloned().fold(f64::INFINITY, f64::min);
            let max = bucket_values
                .iter()
                .cloned()
                .fold(f64::NEG_INFINITY, f64::max);
            let avg = sum / count;
            json!({
                "count": bucket_values.len(),
                "min": serde_json::Number::from_f64(min).map(Value::Number).unwrap_or(Value::Null),
                "max": serde_json::Number::from_f64(max).map(Value::Number).unwrap_or(Value::Null),
                "avg": serde_json::Number::from_f64(avg).map(Value::Number).unwrap_or(Value::Null),
                "sum": serde_json::Number::from_f64(sum).map(Value::Number).unwrap_or(Value::Null),
            })
        }
        "bucket_script" => json!({"value": Value::Null}),
        "extended_stats_bucket" => {
            let n = bucket_values.len() as f64;
            let sum: f64 = bucket_values.iter().sum();
            let min = bucket_values.iter().cloned().fold(f64::INFINITY, f64::min);
            let max = bucket_values
                .iter()
                .cloned()
                .fold(f64::NEG_INFINITY, f64::max);
            let avg = if n > 0.0 { sum / n } else { 0.0 };
            let sum_sq: f64 = bucket_values.iter().map(|v| v * v).sum();
            let variance_pop = if n > 0.0 { sum_sq / n - avg * avg } else { 0.0 };
            let variance_sample = if n > 1.0 {
                (sum_sq - n * avg * avg) / (n - 1.0)
            } else {
                0.0
            };
            let std_pop = variance_pop.max(0.0).sqrt();
            let std_sample = variance_sample.max(0.0).sqrt();
            let num = |x: f64| {
                serde_json::Number::from_f64(x)
                    .map(Value::Number)
                    .unwrap_or(Value::Null)
            };
            json!({
                "count": bucket_values.len(),
                "min": num(min),
                "max": num(max),
                "avg": num(avg),
                "sum": num(sum),
                "sum_of_squares": num(sum_sq),
                "variance": num(variance_pop),
                "variance_population": num(variance_pop),
                "variance_sampling": num(variance_sample),
                "std_deviation": num(std_pop),
                "std_deviation_population": num(std_pop),
                "std_deviation_sampling": num(std_sample),
                "std_deviation_bounds": json!({
                    "upper": num(avg + 2.0 * std_pop),
                    "lower": num(avg - 2.0 * std_pop),
                    "upper_population": num(avg + 2.0 * std_pop),
                    "lower_population": num(avg - 2.0 * std_pop),
                    "upper_sampling": num(avg + 2.0 * std_sample),
                    "lower_sampling": num(avg - 2.0 * std_sample),
                }),
            })
        }
        "percentiles_bucket" => {
            let mut sorted = bucket_values.clone();
            sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            // ES `percentiles_bucket` uses
            // `data[round(p/100 * (n - 1))]` — nearest-rank-by-quantile-position
            // with banker's rounding to the closer index. This matches the
            // observed values across the YAML suite (no_gaps + gaps tests).
            let pcts = [1.0, 5.0, 25.0, 50.0, 75.0, 95.0, 99.0];
            let n = sorted.len();
            let mut values = serde_json::Map::new();
            for p in &pcts {
                let val = if n == 0 {
                    Value::Null
                } else if n == 1 {
                    serde_json::Number::from_f64(sorted[0])
                        .map(Value::Number)
                        .unwrap_or(Value::Null)
                } else {
                    let idx = ((p / 100.0) * (n as f64 - 1.0)).round() as usize;
                    let idx = idx.min(n - 1);
                    serde_json::Number::from_f64(sorted[idx])
                        .map(Value::Number)
                        .unwrap_or(Value::Null)
                };
                values.insert(format!("{:.1}", p), val);
            }
            json!({"values": Value::Object(values)})
        }
        "serial_diff" => {
            if bucket_values.len() >= 2 {
                make_value_result(
                    bucket_values[bucket_values.len() - 1] - bucket_values[bucket_values.len() - 2],
                )
            } else {
                json!({"value": Value::Null})
            }
        }
        "derivative" => {
            if bucket_values.len() >= 2 {
                make_value_result(
                    bucket_values[bucket_values.len() - 1] - bucket_values[bucket_values.len() - 2],
                )
            } else {
                json!({"value": Value::Null})
            }
        }
        "moving_avg" => resolve_moving_avg(&bucket_values, 5),
        "cumulative_sum" => resolve_cumulative_sum(&bucket_values),
        _ => json!({"value": Value::Null}),
    }
}

fn make_value_result(value: f64) -> Value {
    match serde_json::Number::from_f64(value) {
        Some(n) => json!({"value": Value::Number(n)}),
        None => json!({"value": Value::Null}),
    }
}

/// Apply an ES-style numeric format string to a pipeline aggregation's
/// `value` (or each of `values` for a percentile output), populating
/// `value_as_string` (or `values_as_string` entries) with the formatted
/// rendering. Supports `"0.00"`, `"#,##0.00"`, `"0.##"` — the minimal set
/// the YAML tests exercise — via `format_number_pattern`.
fn apply_pipeline_value_format(result: &mut Value, fmt: &str) {
    let Some(obj) = result.as_object_mut() else {
        return;
    };
    if let Some(Value::Number(n)) = obj.get("value").cloned() {
        if let Some(f) = n.as_f64() {
            obj.insert(
                "value_as_string".to_string(),
                Value::String(format_number_pattern(f, fmt)),
            );
        }
    }
    // `stats_bucket` / `extended_stats_bucket` — format each numeric stat.
    for key in [
        "min",
        "max",
        "avg",
        "sum",
        "variance",
        "variance_population",
        "variance_sampling",
        "std_deviation",
        "std_deviation_population",
        "std_deviation_sampling",
        "sum_of_squares",
    ] {
        if let Some(Value::Number(n)) = obj.get(key).cloned() {
            if let Some(f) = n.as_f64() {
                obj.insert(
                    format!("{}_as_string", key),
                    Value::String(format_number_pattern(f, fmt)),
                );
            }
        }
    }
    // `percentiles_bucket` → {values: {"50.0": v, "95.0": v}}.
    // ES inlines the rendered strings as sibling keys `"50.0_as_string"`
    // inside the same `values` object.
    if let Some(Value::Object(values)) = obj.get("values").cloned() {
        let mut out = serde_json::Map::new();
        for (k, v) in values {
            out.insert(k.clone(), v.clone());
            if let Some(f) = v.as_f64() {
                out.insert(
                    format!("{}_as_string", k),
                    Value::String(format_number_pattern(f, fmt)),
                );
            }
        }
        obj.insert("values".to_string(), Value::Object(out));
    }
    // `extended_stats_bucket` → std_deviation_bounds is a nested object;
    // ES emits a sibling `std_deviation_bounds_as_string` object mirroring
    // the shape with each float rendered to the format pattern.
    if let Some(Value::Object(bounds)) = obj.get("std_deviation_bounds").cloned() {
        let mut out = serde_json::Map::new();
        for (k, v) in bounds {
            if let Some(f) = v.as_f64() {
                out.insert(k, Value::String(format_number_pattern(f, fmt)));
            }
        }
        obj.insert(
            "std_deviation_bounds_as_string".to_string(),
            Value::Object(out),
        );
    }
}

/// Evaluate a Painless-style `MovingFunctions.holt(...)` or
/// `MovingFunctions.holtWinters(...)` call against a window. The `script`
/// string is already lower-cased when passed here. Returns None when the
/// call doesn't match one of the supported forms, or when the optional
/// `if (values.length ...)` gate fails.
pub(crate) fn eval_movingfn_call(script: &str, wnd: &[f64]) -> Option<f64> {
    // Honor a leading `if (values.length <op> <n>) { ... }` guard by
    // verifying the condition on the current window. When false, return
    // 0.0 (ES emits 0.0 rather than null for this guarded form).
    let (call_src, guard_passed) = if let Some(if_start) = script.find("if (") {
        let after_if = &script[if_start + 4..];
        // Find the matching `)` then `{`.
        let close_paren = after_if.find(')')?;
        let cond = &after_if[..close_paren];
        let open_brace = after_if[close_paren..].find('{')?;
        let after_brace = &after_if[close_paren + open_brace + 1..];
        let close_brace = after_brace.rfind('}')?;
        let body = &after_brace[..close_brace];
        // Parse cond: must be `values.length <op> <n>`
        let parts: Vec<&str> = cond.split_whitespace().collect();
        let passed = if parts.len() == 3 && parts[0].contains("values.length") {
            let n: usize = parts[2].parse().ok()?;
            match parts[1] {
                ">" => wnd.len() > n,
                ">=" => wnd.len() >= n,
                "<" => wnd.len() < n,
                "<=" => wnd.len() <= n,
                "==" => wnd.len() == n,
                _ => false,
            }
        } else {
            true
        };
        (body.trim().to_string(), passed)
    } else {
        (script.to_string(), true)
    };

    if !guard_passed {
        return Some(0.0);
    }

    // Locate `holtwinters(args)` / `holt(args)` calls (case-insensitive).
    // `fn_name` already includes the opening paren, so we split from just
    // past it; the matching `)` closes the call's argument list.
    let parse_args = |fn_name: &str| -> Option<Vec<f64>> {
        let idx = call_src.find(fn_name)?;
        let after = &call_src[idx + fn_name.len()..];
        let close = after.find(')')?;
        let args_str = &after[..close];
        // Skip the first arg (the values ref). Subsequent args are numeric literals or booleans.
        let parts: Vec<&str> = args_str.split(',').map(str::trim).collect();
        let mut out: Vec<f64> = Vec::new();
        for p in parts.iter().skip(1) {
            if let Ok(n) = p.parse::<f64>() {
                out.push(n);
            } else if *p == "true" {
                out.push(1.0);
            } else if *p == "false" {
                out.push(0.0);
            }
        }
        Some(out)
    };

    if call_src.contains("holtwinters(") {
        let args = parse_args("holtwinters(")?;
        let alpha = *args.first()?;
        let beta = *args.get(1)?;
        let gamma = *args.get(2)?;
        let period = *args.get(3)? as usize;
        let multiplicative = *args.get(4)? > 0.5;
        return holt_winters(wnd, alpha, beta, gamma, period, multiplicative);
    }
    if call_src.contains("holt(") {
        let args = parse_args("holt(")?;
        let alpha = *args.first()?;
        let beta = *args.get(1)?;
        return Some(holt(wnd, alpha, beta));
    }
    None
}

/// ES MovingFunctions.holt: double-exponential smoothing over the window.
/// Returns the smoothed level `s` at the end of the window (matching ES's
/// implementation, which returns the last level estimate — not the forecast).
fn holt(values: &[f64], alpha: f64, beta: f64) -> f64 {
    if values.is_empty() {
        return f64::NAN;
    }
    let mut s = values[0];
    let mut b = 0.0f64;
    for (i, &v) in values.iter().enumerate().skip(1) {
        let old_s = s;
        s = alpha * v + (1.0 - alpha) * (s + b);
        b = beta * (s - old_s) + (1.0 - beta) * b;
        let _ = i;
    }
    s
}

/// ES MovingFunctions.holtWinters: triple-exponential smoothing with
/// seasonality. Requires at least `2 * period` samples to initialize
/// seasonal indices; returns 0.0 otherwise (mirroring ES behaviour when
/// the caller-wrapped `if (values.length > ...)` gate fails).
///
/// Implementation matches the Lucene/ES `MovingFunctions.holtWinters`:
/// initial level = mean of the first full period, initial trend =
/// (mean of 2nd period - mean of 1st period) / period, initial seasonal
/// indices = element-wise residual over the first period.
fn holt_winters(
    values: &[f64],
    alpha: f64,
    beta: f64,
    gamma: f64,
    period: usize,
    multiplicative: bool,
) -> Option<f64> {
    if period == 0 || values.len() < 2 * period {
        return Some(0.0);
    }
    let n = values.len();
    let padding = if multiplicative { 1e-10 } else { 0.0 };
    // Faithful port of ES HoltWintersModel: vs[i] = values[i] + padding.
    let vs: Vec<f64> = values.iter().map(|v| v + padding).collect();
    // Initial level = mean of first season; initial trend is computed but ES
    // keeps `last_b` at 0, so the seed trend is discarded on the first step.
    let mut s = 0.0f64;
    let mut b = 0.0f64;
    for i in 0..period {
        s += vs[i];
        b += (vs[i + period] - vs[i]) / period as f64;
    }
    s /= period as f64;
    b /= period as f64;
    let mut last_s = s;
    let mut last_b = 0.0f64;
    // First-season seasonal indices: ES ALWAYS divides here (even additive).
    let mut seasonal: Vec<f64> = vec![0.0; n];
    if s != 0.0 {
        for i in 0..period {
            seasonal[i] = vs[i] / s;
        }
    }
    for i in period..n {
        if multiplicative {
            s = alpha * (vs[i] / seasonal[i - period]) + (1.0 - alpha) * (last_s + last_b);
        } else {
            s = alpha * (vs[i] - seasonal[i - period]) + (1.0 - alpha) * (last_s + last_b);
        }
        b = beta * (s - last_s) + (1.0 - beta) * last_b;
        if multiplicative {
            seasonal[i] =
                gamma * (vs[i] / (last_s + last_b)) + (1.0 - gamma) * seasonal[i - period];
        } else {
            seasonal[i] =
                gamma * (vs[i] - (last_s - last_b)) + (1.0 - gamma) * seasonal[i - period];
        }
        last_s = s;
        last_b = b;
    }
    let idx = n - period;
    let out = if multiplicative {
        (s + b) * seasonal[idx]
    } else {
        s + b + seasonal[idx]
    };
    Some(out)
}

/// Format a float using a very small subset of ES/Java DecimalFormat
/// patterns. Supports:
/// - `0.00` / `0.###` — fixed decimal with `0` forcing a digit and `#`
///   optional (trailing zeros trimmed).
/// - `#,##0.00` — thousands grouping (US comma) with fixed decimals.
/// - A raw number of decimals (`.NN`) is honored via the count of
///   fractional pattern chars.
///
/// Falls through to `f64::to_string` when the pattern is unrecognized.
pub(crate) fn format_number_pattern(value: f64, pattern: &str) -> String {
    // Java DecimalFormat allows a literal prefix and suffix around the
    // numeric-format chars. Identify the contiguous "active pattern"
    // substring — chars in {0,#,.,,} — and keep the rest as literal.
    let is_fmt = |c: char| matches!(c, '0' | '#' | '.' | ',');
    let start = pattern.find(is_fmt).unwrap_or(pattern.len());
    let end = pattern
        .rfind(is_fmt)
        .map(|i| i + 1)
        .unwrap_or(pattern.len());
    let (prefix, rest) = pattern.split_at(start);
    let (active_pat, suffix) = if end >= start {
        (&rest[..(end - start)], &pattern[end..])
    } else {
        (rest, "")
    };
    if active_pat.is_empty() {
        return pattern.to_string();
    }

    let (int_part_pat, frac_part_pat) = match active_pat.find('.') {
        Some(i) => (&active_pat[..i], &active_pat[i + 1..]),
        None => (active_pat, ""),
    };
    let frac_digits = frac_part_pat
        .chars()
        .filter(|c| *c == '0' || *c == '#')
        .count();
    let fixed_frac_digits = frac_part_pat.chars().filter(|c| *c == '0').count();
    let int_min_digits = int_part_pat.chars().filter(|c| *c == '0').count();
    let use_grouping = int_part_pat.contains(',');

    // Round to `frac_digits` decimals.
    let scale = 10f64.powi(frac_digits as i32);
    let rounded = (value * scale).round() / scale;
    let sign = if rounded < 0.0 { "-" } else { "" };
    let abs = rounded.abs();
    let int_val = abs.trunc() as u64;
    let frac_val = abs - int_val as f64;

    // Render the integer part, zero-pad to `int_min_digits`.
    let mut int_str = int_val.to_string();
    while int_str.len() < int_min_digits {
        int_str.insert(0, '0');
    }
    if use_grouping {
        let s = std::mem::take(&mut int_str);
        let mut out = String::with_capacity(s.len() + s.len() / 3);
        for (i, c) in s.chars().rev().enumerate() {
            if i > 0 && i % 3 == 0 {
                out.push(',');
            }
            out.push(c);
        }
        int_str = out.chars().rev().collect::<String>();
    }

    if frac_digits == 0 {
        return format!("{prefix}{sign}{int_str}{suffix}");
    }

    // Render the fractional part at `frac_digits` precision and trim
    // trailing zeros up to the `fixed_frac_digits` minimum.
    let frac_str = format!("{:.*}", frac_digits, frac_val);
    // `0.xyz` — skip the leading "0.".
    let frac_only = &frac_str[2..];
    let mut trimmed = frac_only.trim_end_matches('0').to_string();
    while trimmed.len() < fixed_frac_digits {
        trimmed.push('0');
    }
    if trimmed.is_empty() {
        format!("{prefix}{sign}{int_str}{suffix}")
    } else {
        format!("{prefix}{sign}{int_str}.{trimmed}{suffix}")
    }
}

fn resolve_moving_avg(bucket_values: &[f64], window: usize) -> Value {
    if bucket_values.is_empty() {
        return json!({"value": Value::Null});
    }
    // Return a per-bucket moving average (only the last bucket's value for the pipeline result).
    let n = bucket_values.len();
    let start = n.saturating_sub(window);
    let slice = &bucket_values[start..];
    let avg = slice.iter().sum::<f64>() / slice.len() as f64;
    make_value_result(avg)
}

fn resolve_cumulative_sum(bucket_values: &[f64]) -> Value {
    if bucket_values.is_empty() {
        return json!({"value": Value::Null});
    }
    let cumsum: f64 = bucket_values.iter().sum();
    make_value_result(cumsum)
}

// ── Dispatch ──────────────────────────────────────────────────────────────────

fn execute_agg_with_all_cached<'d>(
    name: &str,
    body: &Value,
    docs: &'d [Value],
    all_docs: &[Value],
    cache: &mut FieldCache<'d>,
) -> Value {
    let obj = match body.as_object() {
        Some(o) => o,
        None => return json!({"error": "aggregation body must be an object"}),
    };

    // Sub-aggregations live under the "aggs" (or "aggregations") key.
    let sub_aggs = obj.get("aggs").or_else(|| obj.get("aggregations"));

    // Find the aggregation type key (first key that is not "aggs"/"aggregations"/"meta").
    let type_key = obj
        .keys()
        .find(|k| k.as_str() != "aggs" && k.as_str() != "aggregations" && k.as_str() != "meta");

    let agg_type = match type_key {
        Some(k) => k.as_str(),
        None => return json!({"error": format!("no aggregation type found in '{}'", name)}),
    };

    let agg_params = match obj.get(agg_type) {
        Some(p) => p,
        None => return json!({"error": "missing agg params"}),
    };

    let mut result = match agg_type {
        "terms" => run_terms(agg_params, sub_aggs, docs, all_docs),
        "date_histogram" => run_date_histogram(agg_params, sub_aggs, docs, all_docs),
        // Metric aggs receive the shared field cache to avoid redundant JSON walks.
        "value_count" => run_value_count(agg_params, docs, cache),
        "avg" => run_avg(agg_params, docs, cache),
        "sum" => run_sum(agg_params, docs, cache),
        "min" => run_min(agg_params, docs, cache),
        "max" => run_max(agg_params, docs, cache),
        "stats" => run_stats(agg_params, docs, cache),
        "cardinality" => run_cardinality(agg_params, docs, cache),
        "filter" => run_filter(agg_params, sub_aggs, docs, all_docs),
        "filters" => run_filters(agg_params, sub_aggs, docs, all_docs),
        "range" => run_range(agg_params, sub_aggs, docs, all_docs),
        "missing" => run_missing(agg_params, docs),
        "histogram" => run_histogram(agg_params, sub_aggs, docs, all_docs),
        "variable_width_histogram" => {
            run_variable_width_histogram(agg_params, sub_aggs, docs, all_docs)
        }
        "percentiles" => run_percentiles(agg_params, docs),
        "composite" => run_composite(agg_params, sub_aggs, docs, all_docs),
        "significant_terms" => run_significant_terms(agg_params, docs, all_docs),
        "significant_text" => run_significant_text(agg_params, docs, all_docs),
        "top_hits" => run_top_hits(agg_params, docs),
        "sampler" | "random_sampler" => run_sampler(agg_params, sub_aggs, docs, all_docs),
        "adjacency_matrix" => run_adjacency_matrix(agg_params, sub_aggs, docs, all_docs),
        // Geo aggregations
        "geohash_grid" => run_geohash_grid(agg_params, sub_aggs, docs, all_docs),
        "geo_distance" => run_geo_distance(agg_params, sub_aggs, docs, all_docs),
        // Multi-terms aggregation
        "multi_terms" => run_multi_terms(agg_params, sub_aggs, docs, all_docs),
        "rare_terms" => run_rare_terms(agg_params, sub_aggs, docs, all_docs),
        "ip_prefix" => run_ip_prefix(agg_params, sub_aggs, docs, all_docs),
        "geotile_grid" => run_geotile_grid(agg_params, sub_aggs, docs, all_docs),
        "diversified_sampler" => run_diversified_sampler(agg_params, sub_aggs, docs, all_docs),
        // time_series — bucket docs by their time_series_dimension field
        // tuple (the `_tsid`). Dimension fields are declared in the mapping
        // with `time_series_dimension: true`; xerj stores them on the
        // document via `routing_path`. This implementation infers
        // dimensions from the doc's `_source` by finding scalar keyword
        // fields that vary within the index — but the test suite relies
        // on the `key` field being explicitly the dimension, so we pull
        // from the `routing_path` setting when it's passed through.
        "time_series" => run_time_series(agg_params, sub_aggs, docs, all_docs),
        // Auto date histogram
        "auto_date_histogram" => run_auto_date_histogram(agg_params, sub_aggs, docs, all_docs),
        // Gap 3: additional aggregation types
        "extended_stats" => run_extended_stats(agg_params, docs, cache),
        "geo_bounds" => run_geo_bounds(agg_params, docs),
        "geo_centroid" => run_geo_centroid(agg_params, docs),
        "median_absolute_deviation" => run_median_absolute_deviation(agg_params, docs, cache),
        "matrix_stats" => run_matrix_stats(agg_params, docs),
        "string_stats" => run_string_stats(agg_params, docs),
        "boxplot" => run_boxplot(agg_params, docs),
        "top_metrics" => run_top_metrics(agg_params, docs),
        // nested — flatten each parent doc's nested-path array so that
        // doc_count reflects the number of nested objects, and sub-aggs
        // (like `terms` on `courses.name`) see one "doc" per nested entry.
        "nested" => {
            let path = agg_params.get("path").and_then(Value::as_str).unwrap_or("");
            run_nested(path, sub_aggs, docs, all_docs)
        }
        // reverse_nested — unwrap back to parent doc scope. Nested
        // expansion duplicates each parent per nested leaf; reverse_nested
        // deduplicates by parent _id so the parent doc is counted once.
        "reverse_nested" => run_reverse_nested(sub_aggs, docs, all_docs),
        // global — run sub-aggs on ALL docs, regardless of query filter.
        "global" => run_global(sub_aggs, all_docs),
        // Pipeline aggregations — these are computed in a second pass; return placeholder.
        "avg_bucket"
        | "max_bucket"
        | "min_bucket"
        | "sum_bucket"
        | "derivative"
        | "moving_avg"
        | "cumulative_sum"
        | "bucket_selector"
        | "bucket_sort"
        | "bucket_script"
        | "percentiles_bucket"
        | "stats_bucket"
        | "serial_diff"
        | "moving_fn"
        | "extended_stats_bucket" => run_pipeline_agg(agg_type, agg_params),
        // date_range — like range but with date math
        "date_range" => run_date_range(agg_params, sub_aggs, docs, all_docs),
        // percentile_ranks — given values, return percentile rank of each
        "percentile_ranks" => run_percentile_ranks(agg_params, docs),
        // ip_range — like range but for IP addresses
        "ip_range" => run_ip_range(agg_params, sub_aggs, docs, all_docs),
        "scripted_metric" => run_scripted_metric(agg_params, docs),
        other => json!({"error": format!("unsupported aggregation type '{}'", other)}),
    };

    // If this agg produced an array bucket list and its sub-aggs include
    // `bucket_sort` / `bucket_selector`, apply them to the bucket list
    // (they live inside the parent's sub-aggs per ES semantics but operate
    // on the parent's buckets).  Only arrays are mutated — keyed maps
    // (e.g. `filters` with named filters) are left untouched.
    if let Some(obj) = result.as_object_mut() {
        if matches!(obj.get("buckets"), Some(Value::Array(_))) {
            if let Some(Value::Array(buckets)) = obj.remove("buckets") {
                let new_buckets = apply_bucket_pipeline_ops(buckets, sub_aggs);
                obj.insert("buckets".into(), Value::Array(new_buckets));
            }
        }
        obj.insert("__type__".into(), Value::String(agg_type.to_string()));
    }
    result
}

// ── Pipeline aggregation placeholder ─────────────────────────────────────────
// Pipeline aggs reference sibling agg results via `buckets_path`.
// We store the spec and resolve it after the first pass in `run_aggs_with_all`.

pub(crate) fn run_pipeline_agg(agg_type: &str, params: &Value) -> Value {
    // Return a sentinel that will be resolved in the post-processing pass.
    // Extract buckets_path — for moving_avg / cumulative_sum it may be a plain string;
    // for bucket_selector it's an object {"var": "path"}.
    let buckets_path = params.get("buckets_path").cloned().unwrap_or(Value::Null);

    // Normalise buckets_path to a string for the simple cases.
    let bp_str = match &buckets_path {
        Value::String(s) => s.clone(),
        Value::Object(o) => {
            // Take the first value — e.g. {"count": "_count"} → "_count"
            o.values()
                .next()
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string()
        }
        _ => String::new(),
    };

    let mut sentinel = serde_json::Map::new();
    sentinel.insert("__pipeline__".into(), Value::Bool(true));
    sentinel.insert("type".into(), Value::String(agg_type.to_string()));
    sentinel.insert("buckets_path".into(), Value::String(bp_str));
    sentinel.insert("value".into(), Value::Null);
    // `format` / `gap_policy` travel with the sentinel so resolution can
    // honor them without re-reading the request body.
    if let Some(fmt) = params.get("format").and_then(Value::as_str) {
        sentinel.insert("format".into(), Value::String(fmt.to_string()));
    }
    if let Some(gap) = params.get("gap_policy").and_then(Value::as_str) {
        sentinel.insert("gap_policy".into(), Value::String(gap.to_string()));
    }

    // Store extra parameters needed during resolution.
    match agg_type {
        "moving_avg" => {
            let window = params.get("window").and_then(|v| v.as_u64()).unwrap_or(5);
            sentinel.insert("window".into(), Value::Number(window.into()));
        }
        "bucket_selector" => {
            if let Some(script) = params.get("script") {
                sentinel.insert("script".into(), script.clone());
            }
        }
        "bucket_sort" => {
            if let Some(sort) = params.get("sort") {
                sentinel.insert("sort".into(), sort.clone());
            }
            if let Some(size) = params.get("size") {
                sentinel.insert("size".into(), size.clone());
            }
        }
        "bucket_script" => {
            if let Some(script) = params.get("script") {
                sentinel.insert("script".into(), script.clone());
            }
            if let Some(bp) = params.get("buckets_path") {
                sentinel.insert("buckets_path_full".into(), bp.clone());
            }
        }
        _ => {}
    }

    Value::Object(sentinel)
}

// ── Field value extraction ─────────────────────────────────────────────────────

/// Extract all scalar string representations of a field value from a document.
/// Arrays are flattened — each element becomes a separate bucket key.
pub(crate) fn extract_field_values(doc: &Value, field: &str) -> Vec<String> {
    if field.starts_with(xerj_query::executor::PASSAGE_METADATA_PREFIX) {
        return Vec::new();
    }
    let val = get_nested_field(doc, field);
    let mut out = flatten_to_strings(val);
    if out.is_empty() {
        // Array-aware dotted-path fallback: for `users.last` where `users`
        // is an array of objects, fan out through each element and pull
        // the sub-path off every object. This lets nested-path sort/agg
        // paths resolve without a dedicated nested walker.
        out = extract_array_path_values(doc, field);
    }
    out
}

/// Walk a dotted path against arrays transparently: when a segment
/// resolves to an array, apply the rest of the path to each element and
/// collect all leaf scalars. Used by `extract_field_values` as a fallback
/// so nested-path fields like `users.last.keyword` fan out across the
/// `users[]` array.
fn extract_array_path_values(doc: &Value, field: &str) -> Vec<String> {
    fn walk(val: &Value, parts: &[&str]) -> Vec<String> {
        if parts.is_empty() {
            return flatten_to_strings(val);
        }
        let head = parts[0];
        let rest = &parts[1..];
        match val {
            Value::Array(arr) => {
                let mut out = Vec::new();
                for el in arr {
                    out.extend(walk(el, parts));
                }
                out
            }
            Value::Object(obj) => {
                if let Some(next) = obj.get(head) {
                    return walk(next, rest);
                }
                // Multi-field fallback: strip trailing `.keyword` / `.raw`
                // etc. when the suffix isn't mapped.
                if parts.len() == 1 {
                    return Vec::new();
                }
                // try greedy join of remaining parts as a single key
                let joined = parts.join(".");
                if let Some(v) = obj.get(&joined) {
                    return flatten_to_strings(v);
                }
                Vec::new()
            }
            _ => Vec::new(),
        }
    }
    let parts: Vec<&str> = field.split('.').collect();
    let mut out = walk(doc, &parts);
    // Multi-field fallback (strip trailing `.keyword`).
    if out.is_empty() && field.ends_with(".keyword") {
        let parent = &field[..field.len() - ".keyword".len()];
        out = walk(doc, &parent.split('.').collect::<Vec<_>>());
    }
    out
}

/// Walk dot-separated field paths.
///
/// ES text fields auto-create a `.keyword` multi-field (standard dynamic
/// template). If the full dotted path can't be resolved, fall back to
/// stripping a trailing `.keyword` segment — that way aggregations on
/// `category.keyword` still find values when the source only has `category`.
pub(crate) fn get_nested_field<'a>(doc: &'a Value, field: &str) -> &'a Value {
    fn walk<'a>(doc: &'a Value, field: &str) -> Option<&'a Value> {
        let mut current = doc;
        for part in field.split('.') {
            current = current.get(part)?;
        }
        Some(current)
    }
    if let Some(v) = walk(doc, field) {
        return v;
    }
    // Flattened-type source: ES indexes `{"flat.a": "x"}` (literal dot in
    // key) as a sub-path of the top-level `flat` flattened field. Those
    // dots are not nesting — the key is stored verbatim in _source. Try
    // the full path as a direct literal key before falling back.
    if let Some(obj) = doc.as_object() {
        if let Some(v) = obj.get(field) {
            return v;
        }
    }
    // ES multi-field fallback: `<field>.<subfield>` (e.g. `full_text.eng`,
    // `category.keyword`, `name.raw`) refers to a multi-field that shares
    // the parent field's source value. If the dotted path doesn't resolve
    // we strip the trailing segment and try the parent field — that way
    // aggregations and term lookups against `<field>.<sub>` still see the
    // raw source string.
    if let Some(idx) = field.rfind('.') {
        let parent = &field[..idx];
        if let Some(v) = walk(doc, parent) {
            return v;
        }
    }
    &Value::Null
}

fn flatten_to_strings(val: &Value) -> Vec<String> {
    match val {
        Value::Array(arr) => arr.iter().flat_map(flatten_to_strings).collect(),
        Value::Null => vec![],
        Value::String(s) => vec![s.clone()],
        Value::Number(n) => vec![n.to_string()],
        Value::Bool(b) => vec![b.to_string()],
        Value::Object(_) => vec![], // skip objects
    }
}

/// Extract a single numeric value from a field (returns `None` for non-numeric).
pub(crate) fn extract_numeric(doc: &Value, field: &str) -> Option<f64> {
    fn str_to_num(s: &str) -> Option<f64> {
        if let Ok(f) = s.parse::<f64>() {
            return Some(f);
        }
        // Date-shaped strings fall back to epoch ms so min/max/avg on a
        // date field produce the same integer ES surfaces.
        parse_date_ms(&Value::String(s.to_string())).map(|ms| ms as f64)
    }
    match get_nested_field(doc, field) {
        Value::Number(n) => n.as_f64(),
        Value::String(s) => str_to_num(s.as_str()),
        // For arrays, return the first numeric element (legacy single-value extractor).
        Value::Array(arr) => arr.iter().find_map(|v| match v {
            Value::Number(n) => n.as_f64(),
            Value::String(s) => str_to_num(s.as_str()),
            _ => None,
        }),
        _ => None,
    }
}

/// Extract ALL numeric values from a field (flattens arrays).
pub(crate) fn extract_numeric_values(doc: &Value, field: &str) -> Vec<f64> {
    fn walk(v: &Value, out: &mut Vec<f64>) {
        match v {
            Value::Number(n) => {
                if let Some(f) = n.as_f64() {
                    out.push(f);
                }
            }
            Value::String(s) => {
                if let Ok(f) = s.parse::<f64>() {
                    out.push(f);
                }
            }
            Value::Array(arr) => {
                for e in arr {
                    walk(e, out);
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    walk(get_nested_field(doc, field), &mut out);
    out
}

/// All numeric values of a field for a METRIC agg (avg/sum/min/max/stats/…),
/// matching `extract_numeric`'s per-value coercion — a plain number, a numeric
/// string, or a date string parsed to epoch ms — but across EVERY value of a
/// multi-valued field, not just the first. `extract_numeric_values` above is
/// NOT used here because it lacks the date-string fallback that date metric
/// aggs depend on.
pub(crate) fn extract_metric_numeric_values(doc: &Value, field: &str) -> Vec<f64> {
    fn num_of(v: &Value) -> Option<f64> {
        match v {
            Value::Number(n) => n.as_f64(),
            Value::String(s) => s
                .parse::<f64>()
                .ok()
                .or_else(|| parse_date_ms(&Value::String(s.clone())).map(|ms| ms as f64)),
            _ => None,
        }
    }
    fn walk(v: &Value, out: &mut Vec<f64>) {
        match v {
            Value::Array(arr) => {
                for e in arr {
                    walk(e, out);
                }
            }
            other => {
                if let Some(f) = num_of(other) {
                    out.push(f);
                }
            }
        }
    }
    let mut out = Vec::new();
    walk(get_nested_field(doc, field), &mut out);
    out
}

/// Flatten every numeric value across all docs for a metric agg: a multi-valued
/// field contributes ALL its values (ES semantics); a doc with NO numeric value
/// contributes the `missing` placeholder once, when set.
fn metric_numeric_values(cache: &mut FieldCache, field: &str, missing: Option<f64>) -> Vec<f64> {
    let mut out = Vec::new();
    for vals in cache.get_numeric_multi(field) {
        if vals.is_empty() {
            if let Some(m) = missing {
                out.push(m);
            }
        } else {
            out.extend_from_slice(vals);
        }
    }
    out
}

/// Extract ALL parseable date values (as epoch ms) from a field.
pub(crate) fn extract_date_ms_values(doc: &Value, field: &str) -> Vec<i64> {
    fn walk(v: &Value, out: &mut Vec<i64>) {
        match v {
            Value::Array(arr) => {
                for e in arr {
                    walk(e, out);
                }
            }
            other => {
                if let Some(ms) = parse_date_ms(other) {
                    out.push(ms);
                }
            }
        }
    }
    let mut out = Vec::new();
    walk(get_nested_field(doc, field), &mut out);
    out
}

/// Extract range-typed values as (from_inclusive, to_exclusive) numeric pairs.
/// Handles `{gte, gt, lte, lt}` objects, including arrays of them. Unbounded
/// sides default to `f64::MIN`/`f64::MAX` so callers can clamp with
/// `hard_bounds` or `extended_bounds`.
fn extract_numeric_ranges(doc: &Value, field: &str) -> Vec<(f64, f64)> {
    fn walk(v: &Value, out: &mut Vec<(f64, f64)>) {
        match v {
            Value::Array(arr) => {
                for e in arr {
                    walk(e, out);
                }
            }
            Value::Object(obj) => {
                let num = |k: &str| obj.get(k).and_then(Value::as_f64);
                let from = num("gte")
                    .or_else(|| num("gt").map(|g| g + f64::EPSILON))
                    .unwrap_or(f64::MIN);
                let to = num("lt")
                    .or_else(|| num("lte").map(|l| l + f64::EPSILON))
                    .unwrap_or(f64::MAX);
                // Only treat as a range if at least one of the range keys is present.
                if obj.contains_key("gte")
                    || obj.contains_key("gt")
                    || obj.contains_key("lte")
                    || obj.contains_key("lt")
                {
                    out.push((from, to));
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    walk(get_nested_field(doc, field), &mut out);
    out
}

/// Extract range-typed values as (from_inclusive_ms, to_exclusive_ms) date pairs.
fn extract_date_ranges(doc: &Value, field: &str) -> Vec<(i64, i64)> {
    fn walk(v: &Value, out: &mut Vec<(i64, i64)>) {
        match v {
            Value::Array(arr) => {
                for e in arr {
                    walk(e, out);
                }
            }
            Value::Object(obj) => {
                let ms = |k: &str| obj.get(k).and_then(parse_date_ms);
                let from = ms("gte")
                    .or_else(|| ms("gt").map(|g| g + 1))
                    .unwrap_or(i64::MIN);
                let to = ms("lt")
                    .or_else(|| ms("lte").map(|l| l + 1))
                    .unwrap_or(i64::MAX);
                if obj.contains_key("gte")
                    || obj.contains_key("gt")
                    || obj.contains_key("lte")
                    || obj.contains_key("lt")
                {
                    out.push((from, to));
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    walk(get_nested_field(doc, field), &mut out);
    out
}

// ── Terms aggregation ─────────────────────────────────────────────────────────

/// Resolve a terms agg's bucket key(s) for one doc, from either a `field`
/// (the common case) or a Painless `script` (e.g. Kibana's script-bucketed
/// terms aggs like a heatmap's hour-of-day axis). Scripts are evaluated with
/// the same `crate::painless` engine already proven correct for
/// `script_fields`/`top_hits` — this just wires it into the one place that
/// previously only understood `field` and silently produced zero buckets
/// for a script-only terms agg.
fn terms_agg_bucket_keys(field_or_script: &FieldOrScript, doc: &Value) -> Vec<String> {
    match field_or_script {
        FieldOrScript::Field(field) => extract_field_values(doc, field),
        FieldOrScript::Script { source, params } => {
            let ctx = crate::painless::PainlessCtx::new(doc, params, 0.0);
            match crate::painless::eval_painless(source, &ctx) {
                Ok(pv) => flatten_to_strings(&painless_value_to_json(pv)),
                Err(_) => vec![],
            }
        }
    }
}

enum FieldOrScript {
    Field(String),
    Script { source: String, params: Value },
}

fn run_terms(
    params: &Value,
    sub_aggs: Option<&Value>,
    docs: &[Value],
    all_docs: &[Value],
) -> Value {
    let field_or_script = match params.get("field").and_then(Value::as_str) {
        Some(f) => FieldOrScript::Field(f.to_string()),
        None => match params.get("script") {
            Some(script) => {
                let Some(source) = script
                    .get("source")
                    .or_else(|| script.get("inline"))
                    .and_then(Value::as_str)
                else {
                    return json!({"buckets": []});
                };
                let script_params = script.get("params").cloned().unwrap_or(json!({}));
                FieldOrScript::Script {
                    source: source.to_string(),
                    params: script_params,
                }
            }
            None => return json!({"buckets": []}),
        },
    };
    // #864: type bucket keys by the field's source shape — a keyword value that
    // looks numeric ("007") must stay a string. Scripts have no field mapping,
    // so keep the legacy content-based coercion for them.
    let source_is_string = match &field_or_script {
        FieldOrScript::Field(f) => field_source_is_string(docs, f),
        FieldOrScript::Script { .. } => false,
    };
    // ES semantics: size=0 means "return all buckets" (no cap).
    // Any other value caps the result; the default is 10.
    let size_opt: Option<usize> = params
        .get("size")
        .and_then(Value::as_u64)
        .map(|v| v as usize);
    // size=0 → no truncation; absent → default 10.
    let cap: Option<usize> = match size_opt {
        Some(0) => None,    // unlimited
        Some(n) => Some(n), // explicit cap
        None => Some(10),   // ES default
    };

    // Count occurrences of each term, honoring the `_doc_count` metadata
    // field that bulk callers can attach to a document to advertise that a
    // single physical doc represents N logical events (rollup / downsampled
    // indices do this). Missing or non-positive values fall through to 1.
    //
    // The `missing` param supplies a placeholder key for docs that don't
    // have the field — ES treats it as the field value for bucketing.
    let missing_placeholder: Option<String> = params.get("missing").and_then(|v| match v {
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        Value::Bool(b) => Some(b.to_string()),
        _ => None,
    });
    let mut counts: HashMap<String, u64> = HashMap::new();
    let bucket_cap = max_buckets();
    for doc in docs {
        let weight = doc_count_weight(doc);
        let vals = terms_agg_bucket_keys(&field_or_script, doc);
        if vals.is_empty() {
            if let Some(ph) = &missing_placeholder {
                // Bucket cap: skip new keys past the limit, but always
                // accumulate into existing keys so the cap doesn't bias
                // counts of buckets that were already seen.
                if counts.contains_key(ph) || counts.len() < bucket_cap {
                    *counts.entry(ph.clone()).or_insert(0) += weight;
                }
            }
            continue;
        }
        for term in vals {
            if counts.contains_key(&term) || counts.len() < bucket_cap {
                *counts.entry(term).or_insert(0) += weight;
            }
        }
    }

    // `min_doc_count: 0` — include terms that exist in the background
    // (all_docs) even when zero matched docs contain them. ES emits
    // a bucket with doc_count=0 and runs sub-aggs against the empty
    // doc-set (so e.g. `max: null`).
    let min_doc_count_preview: u64 = params
        .get("min_doc_count")
        .and_then(Value::as_u64)
        .unwrap_or(1);
    if min_doc_count_preview == 0 {
        for doc in all_docs {
            for term in terms_agg_bucket_keys(&field_or_script, doc) {
                if counts.contains_key(&term) || counts.len() < bucket_cap {
                    counts.entry(term).or_insert(0);
                }
            }
        }
    }

    // Parse the `order` parameter. ES accepts several forms:
    //   "_count":"asc"  |  "_key":"desc"  |  "<sub_agg_name>":"desc"
    //   "<sub_agg>.<dotted.path>":"desc"      (e.g. `p.values.99`)
    //   [ { "<sub_agg>": "desc" }, { "_key": "asc" } ]  (multi-key)
    // We honor the first non-`_count`/`_key` entry as a sub-agg reference;
    // falling back to count-desc when none is specified.
    fn order_entries(params: &Value) -> Vec<(String, bool)> {
        let order = match params.get("order") {
            Some(v) => v,
            None => return Vec::new(),
        };
        let mut out: Vec<(String, bool)> = Vec::new();
        match order {
            Value::Object(o) => {
                for (k, v) in o {
                    let asc = v.as_str().map(|s| s == "asc").unwrap_or(false);
                    out.push((k.clone(), asc));
                }
            }
            Value::Array(arr) => {
                for item in arr {
                    if let Some(o) = item.as_object() {
                        for (k, v) in o {
                            let asc = v.as_str().map(|s| s == "asc").unwrap_or(false);
                            out.push((k.clone(), asc));
                        }
                    }
                }
            }
            _ => {}
        }
        out
    }
    let orders = order_entries(params);

    // Pre-compute every bucket's sub-aggregations once so we can reorder by
    // a sub-agg metric *before* size-truncation (ES semantics: `size` picks
    // the top N *after* the requested ordering is applied to all candidates).
    //
    // When the ordering only references `_count` or `_key`, skip the
    // pre-compute — simple sort, cheaper.
    let orders_need_sub_agg = orders.iter().any(|(k, _)| k != "_count" && k != "_key");

    let min_doc_count: u64 = params
        .get("min_doc_count")
        .and_then(Value::as_u64)
        .unwrap_or(1);

    // `include: { partition: P, num_partitions: N }` — ES partitions terms
    // by a hash of the term and only returns buckets whose hash falls in
    // the requested partition. This lets clients paginate a very wide
    // terms agg by issuing N independent searches.
    let include_obj = params.get("include").and_then(Value::as_object);
    let partition: Option<u64> = include_obj
        .and_then(|o| o.get("partition"))
        .and_then(Value::as_u64);
    let num_partitions: Option<u64> = include_obj
        .and_then(|o| o.get("num_partitions"))
        .and_then(Value::as_u64);

    // `include: "<regex>"` and `exclude: "<regex>"` — filter terms by a
    // regex (or anchor-less substring match). ES also accepts an array
    // of explicit terms, which we match as literal equality.
    let include_regex = params.get("include").and_then(Value::as_str);
    let exclude_regex = params.get("exclude").and_then(Value::as_str);
    let include_list: Option<Vec<String>> =
        params.get("include").and_then(Value::as_array).map(|a| {
            a.iter()
                .filter_map(|v| match v {
                    Value::String(s) => Some(s.clone()),
                    Value::Number(n) => Some(n.to_string()),
                    Value::Bool(b) => Some(b.to_string()),
                    _ => None,
                })
                .collect()
        });
    let exclude_list: Option<Vec<String>> =
        params.get("exclude").and_then(Value::as_array).map(|a| {
            a.iter()
                .filter_map(|v| match v {
                    Value::String(s) => Some(s.clone()),
                    Value::Number(n) => Some(n.to_string()),
                    Value::Bool(b) => Some(b.to_string()),
                    _ => None,
                })
                .collect()
        });

    // Collection-time filters only (partition + include/exclude) — these
    // terms never existed as buckets, so they don't count toward
    // `sum_other_doc_count` (verified vs live ES). The `min_doc_count`
    // filter is NOT applied here: ES applies it at final reduce, after the
    // shard-size cut — `apply_terms_size_pipeline` below reproduces that
    // ordering so both the bucket set and the "other" count match ES.
    let mut candidates: Vec<(String, u64)> = counts
        .into_iter()
        .filter(|(k, _c)| {
            if let (Some(p), Some(n)) = (partition, num_partitions) {
                if n > 0 {
                    // ES uses Murmur3_32 (`StringHelper.murmurhash3_x86_32`)
                    // with Lucene's GOOD_FAST_HASH_SEED = 0xAD7D2925 for
                    // partition hashing. Numeric terms are hashed as their
                    // sortable 8-byte big-endian long encoding (LongPoint
                    // pack format); string terms as UTF-8 bytes.
                    let h = if let Ok(n_val) = k.parse::<i64>() {
                        murmur3_32_partition_hash(&n_val.to_be_bytes())
                    } else {
                        murmur3_32_partition_hash(k.as_bytes())
                    };
                    if (h as u64) % n != p {
                        return false;
                    }
                }
            }
            if let Some(re) = include_regex {
                if !term_matches_regex(k, re) {
                    return false;
                }
            }
            if let Some(re) = exclude_regex {
                if term_matches_regex(k, re) {
                    return false;
                }
            }
            if let Some(list) = &include_list {
                if !list.iter().any(|s| s == k) {
                    return false;
                }
            }
            if let Some(list) = &exclude_list {
                if list.iter().any(|s| s == k) {
                    return false;
                }
            }
            true
        })
        .collect();

    // Compute bucket_docs + optional sub-agg value for each candidate key.
    let compute_bucket_docs = |key: &str| -> Vec<Value> {
        let is_missing_bucket = missing_placeholder
            .as_deref()
            .map(|ph| ph == key)
            .unwrap_or(false);
        docs.iter()
            .filter(|doc| {
                let vals = terms_agg_bucket_keys(&field_or_script, doc);
                if is_missing_bucket {
                    vals.is_empty()
                } else {
                    vals.contains(&key.to_string())
                }
            })
            .cloned()
            .collect()
    };

    // Build (key, count, sub_aggs) so we can reuse sub-agg results for
    // both ordering and final bucket output.
    // #375: pre-compute sub-aggregations for EVERY candidate bucket ONLY when
    // the requested order actually references a sub-agg metric — otherwise the
    // top-level order (`_count`/`_key`) is independent of the sub-aggs, so we
    // sort + size-truncate first and let the bucket loop below compute
    // sub-aggs for the surviving top-N only (`sub_result`'s `.or_else`). The
    // old `|| sub_aggs.is_some()` here defeated that: a nested terms agg (top
    // 10 of a 100k-term field with a sub-agg) eagerly materialised all 100k
    // sub-buckets and then discarded 99,990 of them (reported by Pascal Seitz).
    let pre_computed: Vec<(String, u64, Option<Value>)> = if orders_need_sub_agg {
        candidates
            .iter()
            .map(|(k, c)| {
                let bucket_docs = compute_bucket_docs(k);
                let sub_res = sub_aggs.map(|sa| run_aggs_in_bucket(sa, &bucket_docs, all_docs, *c));
                (k.clone(), *c, sub_res)
            })
            .collect()
    } else {
        candidates.drain(..).map(|(k, c)| (k, c, None)).collect()
    };

    // Reorder according to the requested sort keys.
    let mut sorted: Vec<(String, u64, Option<Value>)> = pre_computed;
    sorted.sort_by(|a, b| cmp_terms_by_orders(a, b, &orders));

    // ES single-shard truncation accounting: shard-size cut →
    // min_doc_count reduce-drop → size cut; cut/overflowed bucket counts
    // accumulate into the REAL sum_other_doc_count (previously hardcoded 0).
    let shard_size_param: Option<usize> = params
        .get("shard_size")
        .and_then(Value::as_u64)
        .map(|v| v as usize);
    let (sorted, sum_other_doc_count) =
        apply_terms_size_pipeline(sorted, |r| r.1, cap, shard_size_param, min_doc_count);

    let buckets: Vec<Value> = sorted
        .into_iter()
        .map(|(key, count, sub_res)| {
            let is_missing_bucket = missing_placeholder
                .as_deref()
                .map(|ph| ph == key.as_str())
                .unwrap_or(false);
            let bucket_docs: Vec<Value> = docs
                .iter()
                .filter(|doc| {
                    let vals = terms_agg_bucket_keys(&field_or_script, doc);
                    if is_missing_bucket {
                        vals.is_empty()
                    } else {
                        vals.contains(&key)
                    }
                })
                .cloned()
                .collect();
            let _ = &bucket_docs; // silence unused when neither sub nor `count` needs it
            let (key, count, precomputed_sub) = (key, count, sub_res);

            let (typed_key, key_as_string) = typed_term_key(&key, source_is_string);

            let mut bucket = json!({
                "key": typed_key,
                "doc_count": count
            });
            if let Some(kas) = key_as_string {
                bucket["key_as_string"] = json!(kas);
            }

            // Reuse the precomputed sub-agg result when we had to build it
            // for ordering; otherwise compute it now (no-op if no sub_aggs).
            let sub_result = precomputed_sub.or_else(|| {
                sub_aggs.map(|sa| run_aggs_in_bucket(sa, &bucket_docs, all_docs, count))
            });
            if let Some(Value::Object(sub_obj)) = sub_result {
                if let Some(bucket_obj) = bucket.as_object_mut() {
                    for (k, v) in sub_obj {
                        bucket_obj.insert(k, v);
                    }
                }
            }

            bucket
        })
        .collect();

    json!({
        "doc_count_error_upper_bound": 0,
        "sum_other_doc_count": sum_other_doc_count,
        "buckets": buckets
    })
}

/// Apply Elasticsearch's (single-shard) terms-agg size pipeline to an
/// already-ordered candidate list and compute the real
/// `sum_other_doc_count`. Semantics verified against live ES 8.13.4:
///
///   1. Shard select — the shard keeps the top `shard_size` buckets in the
///      requested order (default `size*1.5 + 10`, and never below `size`,
///      matching `BucketUtils.suggestShardSideQueueSize` + ES's
///      shard_size >= size reset). Buckets cut here count toward
///      `sum_other_doc_count`.
///   2. Final reduce — buckets failing `min_doc_count` are dropped
///      SILENTLY (their counts do NOT go to "other"; verified live);
///      passing buckets beyond `size` overflow into "other".
///
/// `cap == None` is xerj's `size: 0` extension (return every bucket): no
/// truncation happens, only the `min_doc_count` filter, and "other" is 0.
///
/// Shared by `run_terms`, `run_multi_terms`, the columnar
/// `fast_aggs::exec_terms` arm and the doc-values fast paths so the
/// bucket set AND the "other" count stay byte-identical across paths.
pub(crate) fn apply_terms_size_pipeline<T>(
    rows: Vec<T>,
    count_of: impl Fn(&T) -> u64,
    cap: Option<usize>,
    shard_size_param: Option<usize>,
    min_doc_count: u64,
) -> (Vec<T>, u64) {
    let mut rows = rows;
    match cap {
        Some(size) => {
            let mut sum_other: u64 = 0;
            let shard_size = shard_size_param.unwrap_or(size + size / 2 + 10).max(size);
            if rows.len() > shard_size {
                for r in &rows[shard_size..] {
                    sum_other += count_of(r);
                }
                rows.truncate(shard_size);
            }
            let mut fin: Vec<T> = Vec::with_capacity(rows.len().min(size));
            for r in rows {
                if count_of(&r) < min_doc_count {
                    continue; // ES final-reduce silent drop
                }
                if fin.len() >= size {
                    sum_other += count_of(&r);
                } else {
                    fin.push(r);
                }
            }
            (fin, sum_other)
        }
        None => {
            rows.retain(|r| count_of(r) >= min_doc_count);
            (rows, 0)
        }
    }
}

/// ES returns typed terms-bucket keys: numbers as numbers, booleans as
/// 1/0 (with key_as_string "true"/"false"), dates as epoch millis
/// (with key_as_string as the ISO string).  Everything else stays
/// a string.  `key_as_string` is only added when it carries extra
/// information that the numeric key can't: booleans and dates.
///
/// #864: `source_is_string` reflects whether the field's source values are
/// JSON STRINGS (keyword / text / date-family) rather than JSON numbers or
/// bools. ES types a bucket key by the field's MAPPING, so a keyword value
/// that merely LOOKS numeric (`"007"`) must stay the string `"007"`, not the
/// number 7 — the string branch skips i64/f64 coercion but still surfaces an
/// ISO date as epoch millis (a genuine `date` field's values are strings).
///
/// Shared by `run_terms` and the doc-values fast-agg path so bucket
/// key shaping is byte-identical between the two.
/// #864: does this field hold JSON STRING values (keyword / text / date) rather
/// than JSON numbers or bools? Inspects the raw source of `docs` — the first
/// present scalar value's JSON type decides (ES types the whole field by its
/// mapping). No values / all null → `false` (there are no keys to shape anyway).
fn field_source_is_string(docs: &[Value], field: &str) -> bool {
    fn scalar_is_string(v: &Value) -> Option<bool> {
        match v {
            Value::String(_) => Some(true),
            Value::Number(_) | Value::Bool(_) => Some(false),
            Value::Array(a) => a.iter().find_map(scalar_is_string),
            _ => None,
        }
    }
    for doc in docs {
        if let Some(v) = crate::index::get_field_value(doc, field) {
            if let Some(is_str) = scalar_is_string(&v) {
                return is_str;
            }
        }
    }
    false
}

pub(crate) fn typed_term_key(key: &str, source_is_string: bool) -> (Value, Option<String>) {
    if source_is_string {
        // Keyword/text/date-family: a numeric-looking value ("007") stays a
        // string. A GENUINE ISO date string still surfaces as epoch millis — but
        // NOT a bare number (`parse_date_ms` treats "007" as epoch 7 via its
        // integer fallback, which would defeat the whole point).
        let is_bare_number = key.parse::<i64>().is_ok() || key.parse::<f64>().is_ok();
        if !is_bare_number {
            if let Some(epoch_ms) = parse_date_ms(&Value::String(key.to_string())) {
                return (json!(epoch_ms), Some(epoch_ms_to_iso8601_utc(epoch_ms)));
            }
        }
        return (json!(key), None);
    }
    let mut key_as_string: Option<String> = None;
    let typed_key: Value = if key == "true" || key == "false" {
        key_as_string = Some(key.to_string());
        json!(if key == "true" { 1 } else { 0 })
    } else if let Ok(n) = key.parse::<i64>() {
        json!(n)
    } else if let Ok(f) = key.parse::<f64>() {
        serde_json::Number::from_f64(f)
            .map(Value::Number)
            .unwrap_or(json!(key))
    } else if let Some(epoch_ms) = parse_date_ms(&Value::String(key.to_string())) {
        // ES emits `key_as_string` in full ISO-8601 UTC with millis
        // regardless of the input granularity (e.g. "2016-05-03" →
        // "2016-05-03T00:00:00.000Z").
        key_as_string = Some(epoch_ms_to_iso8601_utc(epoch_ms));
        json!(epoch_ms)
    } else {
        json!(key)
    };
    (typed_key, key_as_string)
}

/// Comparator for terms-agg candidate buckets against a list of `order`
/// entries. Each entry is `(path, asc)`; `_count`/`_key` are special, any
/// other path is resolved against the bucket's precomputed sub-aggs and
/// compared as a floating-point metric value (missing → -inf for asc,
/// +inf for desc so gaps sort last).
/// Order two terms-agg `_key`s the way ES does: NUMERICALLY when both keys are
/// numbers, otherwise by byte/lexicographic order. XERJ already types numeric
/// keys by value in `typed_term_key` (emitting `10` as JSON `10`, not `"10"`),
/// so the ordering must match — otherwise `[2, 10, 100]` sorts as
/// `["10", "100", "2"]`. Which keys count as numeric mirrors `typed_term_key`
/// exactly: an `i64`, or a finite `f64` (non-finite / bool / date stay lexical).
fn cmp_term_key(a: &str, b: &str) -> std::cmp::Ordering {
    // Both keys are exact integers -> compare as i64 losslessly. Snowflake IDs
    // and epoch-nanos exceed f64's 2^53 exact range, so widening to f64 (the
    // fallback below) would collapse distinct long keys to the same float and
    // mis-order them. ES orders a long field by exact value.
    if let (Ok(x), Ok(y)) = (a.parse::<i64>(), b.parse::<i64>()) {
        return x.cmp(&y);
    }
    // Otherwise order numerically when both parse as a finite number (covers
    // floats and int/float mixes), else byte/lexicographic -- mirroring
    // typed_term_key's numeric-key notion (non-finite/bool/date/keyword lexical).
    fn as_num(s: &str) -> Option<f64> {
        if let Ok(n) = s.parse::<i64>() {
            return Some(n as f64);
        }
        match s.parse::<f64>() {
            Ok(f) if f.is_finite() => Some(f),
            _ => None,
        }
    }
    match (as_num(a), as_num(b)) {
        (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(std::cmp::Ordering::Equal),
        _ => a.cmp(b),
    }
}

fn cmp_terms_by_orders(
    a: &(String, u64, Option<Value>),
    b: &(String, u64, Option<Value>),
    orders: &[(String, bool)],
) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    if orders.is_empty() {
        // ES default: count desc, key asc.
        return b.1.cmp(&a.1).then_with(|| cmp_term_key(&a.0, &b.0));
    }
    for (path, asc) in orders {
        let ord = match path.as_str() {
            "_count" => a.1.cmp(&b.1),
            "_key" => cmp_term_key(&a.0, &b.0),
            other => {
                let va = lookup_agg_metric(a.2.as_ref(), other);
                let vb = lookup_agg_metric(b.2.as_ref(), other);
                va.partial_cmp(&vb).unwrap_or(Ordering::Equal)
            }
        };
        let ord = if *asc { ord } else { ord.reverse() };
        if ord != Ordering::Equal {
            return ord;
        }
    }
    // Final tiebreaker on key.
    cmp_term_key(&a.0, &b.0)
}

/// Resolve a dotted/`>`-separated path against a sub-aggregation result
/// tree into a numeric value. Supports `<agg_name>`, `<agg_name>.value`,
/// `<agg_name>.values.<pct>`, ES nested-bucket paths
/// `<bucket_agg>>.<metric_agg>` (or `>` only), and keyed
/// percentile/percentile_rank lookups.
fn lookup_agg_metric(sub: Option<&Value>, path: &str) -> f64 {
    let Some(root) = sub else {
        return f64::NEG_INFINITY;
    };
    // Normalize ES `>` separator (nested bucket-path syntax) to `.`
    // for uniform walking. `aggA>aggB` → `aggA.aggB`. Strip leading dot.
    let normalized = path.replace('>', ".");
    let mut cur: &Value = root;
    for seg in normalized.split('.').filter(|s| !s.is_empty()) {
        match cur.get(seg) {
            Some(v) => cur = v,
            None => return lookup_keyed_metric(root, path).unwrap_or(f64::NEG_INFINITY),
        }
    }
    if let Some(v) = cur.get("value") {
        if let Some(f) = v.as_f64() {
            return f;
        }
    }
    cur.as_f64()
        .or_else(|| lookup_keyed_metric(root, path))
        .unwrap_or(f64::NEG_INFINITY)
}

/// ES's value-key form for a multi-value metric (#1282): `p.95` or `p[95.0]`
/// on a `percentiles` sub-agg names the 95th percentile, which lives at
/// `p.values["95.0"]` (or in a `{key, value}` array when `keyed: false`). The
/// plain dotted walk above cannot reach it — `"95"` is not the stored key, and
/// `[95.0]` is not a segment — so it ranked every bucket as equal and the
/// terms order silently fell back to the key tiebreaker.
fn lookup_keyed_metric(root: &Value, path: &str) -> Option<f64> {
    let (chain, last) = match path.rsplit_once('>') {
        Some((chain, last)) => (Some(chain), last),
        None => (None, path),
    };
    let mut cur = root;
    for name in chain.into_iter().flat_map(|c| c.split('>')) {
        cur = cur.get(name)?;
    }
    let (name, key) = match last.split_once('[') {
        Some((name, rest)) => (name, rest.strip_suffix(']')?),
        None => last.split_once('.')?,
    };
    let agg = cur.get(name)?;
    if let Some(f) = agg.get(key).and_then(Value::as_f64) {
        return Some(f);
    }
    let want = key.parse::<f64>().ok();
    let same_key = |k: &str| want.is_some() && k.parse::<f64>().ok() == want;
    match agg.get("values")? {
        Value::Object(values) => values
            .get(key)
            .or_else(|| values.iter().find(|(k, _)| same_key(k)).map(|(_, v)| v))
            .and_then(Value::as_f64),
        Value::Array(entries) => entries
            .iter()
            .find(|e| match e.get("key") {
                Some(Value::String(k)) => same_key(k),
                Some(k) => k.as_f64().is_some() && k.as_f64() == want,
                None => false,
            })
            .and_then(|e| e.get("value"))
            .and_then(Value::as_f64),
        _ => None,
    }
}

fn run_ip_prefix(
    params: &Value,
    sub_aggs: Option<&Value>,
    docs: &[Value],
    all_docs: &[Value],
) -> Value {
    let field = match params.get("field").and_then(Value::as_str) {
        Some(f) => f,
        None => return json!({"buckets": []}),
    };
    let prefix_length = params
        .get("prefix_length")
        .and_then(Value::as_u64)
        .unwrap_or(24) as usize;
    let is_ipv6 = params
        .get("is_ipv6")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let append_prefix_length = params
        .get("append_prefix_length")
        .and_then(Value::as_bool)
        .unwrap_or(false);

    // Group docs by their prefixed IP key. ES sorts buckets by the binary
    // octet representation of the masked address, not by lexicographic
    // string order — so we key by octets and render the display string
    // afterward. Key format is a bare IP string (optionally with
    // `/prefix_length` appended when append_prefix_length=true).
    //
    // Binary key: 17 bytes — one tag byte (0 = IPv4, 1 = IPv6) followed
    // by the 16 IPv6 octets or 4 IPv4 octets (padded). Tag is needed so
    // IPv4 and IPv6 entries sort in a stable, consistent order if a
    // caller ever mixes them; with is_ipv6 fixed per-agg this is not
    // user-visible.
    let mut prefix_docs: HashMap<Vec<u8>, (String, Vec<usize>)> = HashMap::new();
    for (i, doc) in docs.iter().enumerate() {
        for v in extract_field_values(doc, field) {
            let (binkey, display): (Option<Vec<u8>>, Option<String>) = if is_ipv6 {
                // Treat every address as 128-bit. v4 maps to ::ffff:V.V.V.V.
                let addr: Option<std::net::Ipv6Addr> = v.parse().ok().or_else(|| {
                    v.parse::<std::net::Ipv4Addr>()
                        .ok()
                        .map(|v4| v4.to_ipv6_mapped())
                });
                match addr {
                    Some(a) => {
                        let masked = mask_ipv6(a, prefix_length);
                        let octets = masked.octets();
                        let mut key = Vec::with_capacity(17);
                        key.push(1u8);
                        key.extend_from_slice(&octets);
                        (Some(key), Some(masked.to_string()))
                    }
                    None => (None, None),
                }
            } else {
                // When the value is IPv6 but is_ipv6=false, ES takes the
                // last 4 bytes and treats them as IPv4 (the "incorrect"
                // classification case) rather than discarding the doc.
                let ip4: Option<std::net::Ipv4Addr> =
                    v.parse::<std::net::Ipv4Addr>().ok().or_else(|| {
                        v.parse::<std::net::Ipv6Addr>().ok().map(|v6| {
                            let oct = v6.octets();
                            std::net::Ipv4Addr::new(oct[12], oct[13], oct[14], oct[15])
                        })
                    });
                match ip4 {
                    Some(ip4) => {
                        let mask = if prefix_length >= 32 {
                            !0u32
                        } else {
                            !0u32 << (32 - prefix_length)
                        };
                        let masked = u32::from_be_bytes(ip4.octets()) & mask;
                        let ip = std::net::Ipv4Addr::from(masked);
                        let octets = ip.octets();
                        let mut key = Vec::with_capacity(17);
                        key.push(0u8);
                        key.extend_from_slice(&octets);
                        (Some(key), Some(ip.to_string()))
                    }
                    None => (None, None),
                }
            };
            if let (Some(bk), Some(k)) = (binkey, display) {
                let disp = if append_prefix_length {
                    format!("{}/{}", k, prefix_length)
                } else {
                    k
                };
                let entry = prefix_docs
                    .entry(bk)
                    .or_insert_with(|| (disp.clone(), Vec::new()));
                entry.1.push(i);
            }
        }
    }

    // Sort by binary key ascending (ES behaviour for ip_prefix).
    let mut entries: Vec<(Vec<u8>, (String, Vec<usize>))> = prefix_docs.into_iter().collect();
    entries.sort_by(|a, b| a.0.cmp(&b.0));
    let entries: Vec<(String, Vec<usize>)> = entries.into_iter().map(|(_, v)| v).collect();

    let buckets: Vec<Value> = entries
        .iter()
        .map(|(key, indices)| {
            let bucket_docs: Vec<Value> = indices.iter().map(|&i| docs[i].clone()).collect();
            let mut bucket = json!({
                "key": key,
                "doc_count": indices.len(),
                "is_ipv6": is_ipv6,
                "prefix_length": prefix_length,
            });
            // netmask is only emitted for IPv4.
            if !is_ipv6 {
                bucket["netmask"] = json!(format_netmask_v4(prefix_length));
            }
            if let Some(sub) = sub_aggs {
                let sub_result =
                    run_aggs_in_bucket(sub, &bucket_docs, all_docs, indices.len() as u64);
                if let (Some(bo), Value::Object(so)) = (bucket.as_object_mut(), sub_result) {
                    for (k, v) in so {
                        bo.insert(k, v);
                    }
                }
            }
            bucket
        })
        .collect();

    json!({"buckets": buckets})
}

/// Apply `prefix_length`-bit mask to the top of the IPv6 address.
fn mask_ipv6(addr: std::net::Ipv6Addr, prefix_length: usize) -> std::net::Ipv6Addr {
    let n = prefix_length.min(128);
    let mut bits = u128::from_be_bytes(addr.octets());
    if n == 0 {
        bits = 0;
    } else if n < 128 {
        let shift = 128 - n;
        bits &= !((1u128 << shift) - 1);
    }
    std::net::Ipv6Addr::from(bits.to_be_bytes())
}

fn format_netmask_v4(prefix_length: usize) -> String {
    let mask = if prefix_length >= 32 {
        !0u32
    } else {
        !0u32 << (32 - prefix_length)
    };
    let ip = std::net::Ipv4Addr::from(mask);
    ip.to_string()
}

fn run_rare_terms(
    params: &Value,
    sub_aggs: Option<&Value>,
    docs: &[Value],
    all_docs: &[Value],
) -> Value {
    let field = match params.get("field").and_then(Value::as_str) {
        Some(f) => f,
        None => return json!({"buckets": []}),
    };
    let max_doc_count = params
        .get("max_doc_count")
        .and_then(Value::as_u64)
        .unwrap_or(1) as usize;

    // include / exclude — ES accepts array of literals (applies to any
    // field type) or regex string (keyword fields only).
    let include_list: Option<Vec<String>> =
        params.get("include").and_then(Value::as_array).map(|a| {
            a.iter()
                .filter_map(|v| {
                    v.as_str()
                        .map(String::from)
                        .or_else(|| v.as_f64().map(|f| f.to_string()))
                })
                .collect()
        });
    let exclude_list: Option<Vec<String>> =
        params.get("exclude").and_then(Value::as_array).map(|a| {
            a.iter()
                .filter_map(|v| {
                    v.as_str()
                        .map(String::from)
                        .or_else(|| v.as_f64().map(|f| f.to_string()))
                })
                .collect()
        });

    let mut term_docs: HashMap<String, Vec<usize>> = HashMap::new();
    for (i, doc) in docs.iter().enumerate() {
        for v in extract_field_values(doc, field) {
            if v.is_empty() {
                continue;
            }
            if let Some(ref inc) = include_list {
                if !inc.contains(&v) {
                    continue;
                }
            }
            if let Some(ref exc) = exclude_list {
                if exc.contains(&v) {
                    continue;
                }
            }
            term_docs.entry(v).or_default().push(i);
        }
    }

    let mut entries: Vec<_> = term_docs
        .into_iter()
        .filter(|(_, indices)| indices.len() <= max_doc_count)
        .collect();
    entries.sort_by(|a, b| a.1.len().cmp(&b.1.len()).then(a.0.cmp(&b.0)));

    let buckets: Vec<Value> = entries
        .iter()
        .map(|(key, indices)| {
            let bucket_docs: Vec<Value> = indices.iter().map(|&i| docs[i].clone()).collect();
            let mut bucket = build_terms_bucket(key, indices.len() as u64);
            if let Some(sub) = sub_aggs {
                let sub_result =
                    run_aggs_in_bucket(sub, &bucket_docs, all_docs, indices.len() as u64);
                if let (Some(bo), Value::Object(so)) = (bucket.as_object_mut(), sub_result) {
                    for (k, v) in so {
                        bo.insert(k, v);
                    }
                }
            }
            bucket
        })
        .collect();

    json!({"buckets": buckets})
}

// ── Date histogram aggregation ────────────────────────────────────────────────

/// Matrix-stats aggregation: per-field count/mean/variance/skewness/kurtosis
/// plus pairwise covariance and correlation. ES only counts a document
/// if *every* requested field has a numeric value (unless `missing` fills
/// in a default for each). Documents where any field is unmapped/missing
/// are skipped, which is why the `Partially unmapped` test expects
/// doc_count=14 out of 15 input docs.
fn run_matrix_stats(params: &Value, docs: &[Value]) -> Value {
    let fields: Vec<String> = params
        .get("fields")
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default();
    if fields.is_empty() {
        return json!({"doc_count": 0, "fields": []});
    }
    let mode = params.get("mode").and_then(Value::as_str).unwrap_or("avg");
    let missing: HashMap<String, f64> = params
        .get("missing")
        .and_then(Value::as_object)
        .map(|o| {
            o.iter()
                .filter_map(|(k, v)| v.as_f64().map(|f| (k.clone(), f)))
                .collect()
        })
        .unwrap_or_default();
    // Sentinel injected by the HTTP coordination layer: list of field
    // names whose mapping declares `type: float`. ES indexes those at
    // f32 precision, so reduction must round-trip through f32 to match
    // the 1e-11 tolerance asserted by ES YAML tests.
    let f32_fields: HashSet<String> = params
        .get("__xy_f32_fields__")
        .and_then(Value::as_array)
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default();
    let cast_if_f32 = |field: &str, v: f64| -> f64 {
        if f32_fields.contains(field) {
            v as f32 as f64
        } else {
            v
        }
    };

    // Per-doc value vector (f64 per field) — doc is included only when
    // every field resolves to a numeric value after the `mode` collapses
    // multi-valued fields.
    let mut rows: Vec<Vec<f64>> = Vec::new();
    for doc in docs {
        let mut row = Vec::with_capacity(fields.len());
        let mut valid = true;
        for f in &fields {
            let nums_raw = extract_numeric_values(doc, f);
            // Cast each value through f32 first when the field is a
            // float-type field per the mapping. ES does the equivalent
            // at index time so reductions read f32 values; without this
            // our f64 sums can drift outside the 1e-11 tolerance.
            let nums: Vec<f64> = nums_raw.into_iter().map(|v| cast_if_f32(f, v)).collect();
            let v = if nums.is_empty() {
                missing.get(f).copied()
            } else {
                match mode {
                    "sum" => Some(nums.iter().sum::<f64>()),
                    "min" => nums.iter().cloned().reduce(f64::min),
                    "max" => nums.iter().cloned().reduce(f64::max),
                    "median" => {
                        let mut s = nums.clone();
                        s.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                        if s.is_empty() {
                            None
                        } else {
                            Some(s[s.len() / 2])
                        }
                    }
                    _ => Some(nums.iter().sum::<f64>() / nums.len() as f64), // "avg" default
                }
            };
            match v {
                Some(val) => row.push(val),
                None => {
                    valid = false;
                    break;
                }
            }
        }
        if valid {
            rows.push(row);
        }
    }
    matrix_stats_from_rows(fields, rows)
}

/// Reduce pre-collapsed per-doc value rows (one `f64` per requested field, for
/// docs where every field resolved) into the ES `matrix_stats` response body:
/// per-field count/mean/variance/skewness/kurtosis plus the pairwise
/// covariance and correlation matrices, emitted in ES's reverse-input field
/// order.  Split out of `run_matrix_stats` so the columnar fast-agg path
/// (`FastCtx::exec_matrix_stats`) can feed rows gathered straight from the
/// numeric `.dv` columns through the identical math.
pub(crate) fn matrix_stats_from_rows(fields: Vec<String>, rows: Vec<Vec<f64>>) -> Value {
    let n = rows.len();
    if n == 0 {
        return json!({"doc_count": 0, "fields": []});
    }

    // Per-field: count, mean, variance, skewness, kurtosis.
    let k = fields.len();
    let mut sum = vec![0.0f64; k];
    for row in &rows {
        for (i, v) in row.iter().enumerate() {
            sum[i] += *v;
        }
    }
    let mean: Vec<f64> = sum.iter().map(|s| s / n as f64).collect();

    let mut m2 = vec![0.0f64; k];
    let mut m3 = vec![0.0f64; k];
    let mut m4 = vec![0.0f64; k];
    for row in &rows {
        for (i, v) in row.iter().enumerate() {
            let d = *v - mean[i];
            m2[i] += d * d;
            m3[i] += d * d * d;
            m4[i] += d * d * d * d;
        }
    }
    let variance: Vec<f64> = if n > 1 {
        m2.iter().map(|s| s / (n - 1) as f64).collect()
    } else {
        vec![0.0; k]
    };
    let std_dev: Vec<f64> = variance.iter().map(|v| v.sqrt()).collect();
    let skewness: Vec<f64> = (0..k)
        .map(|i| {
            if n > 2 && std_dev[i] > 0.0 {
                let s3 = m3[i] / n as f64;
                s3 / std_dev[i].powi(3)
            } else {
                0.0
            }
        })
        .collect();
    let kurtosis: Vec<f64> = (0..k)
        .map(|i| {
            if n > 3 && variance[i] > 0.0 {
                let s4 = m4[i] / n as f64;
                s4 / variance[i].powi(2)
            } else {
                0.0
            }
        })
        .collect();

    // Pairwise covariance and correlation matrices.
    let mut cov = vec![vec![0.0f64; k]; k];
    for row in &rows {
        for i in 0..k {
            for j in 0..k {
                cov[i][j] += (row[i] - mean[i]) * (row[j] - mean[j]);
            }
        }
    }
    let denom = if n > 1 { (n - 1) as f64 } else { 1.0 };
    // cov[i][j] is 2-D matrix indexing; a plain range loop is the clearest
    // form and an iterator refactor would obscure the normalization math.
    #[allow(clippy::needless_range_loop)]
    for i in 0..k {
        for j in 0..k {
            cov[i][j] /= denom;
        }
    }
    let corr = |i: usize, j: usize| -> f64 {
        let d = std_dev[i] * std_dev[j];
        if d > 0.0 {
            cov[i][j] / d
        } else {
            0.0
        }
    };

    // Build per-field output. ES orders fields by the input order.
    // ES emits matrix_stats fields in REVERSE input order (a quirk of
    // the Java implementation that surfaces in the YAML tests — see the
    // expectation that `fields.0.correlation.val1` is not 1.0 when the
    // request lists `val1` first). Mirror that ordering so bucket
    // indices line up with the test assertions.
    let mut fields_out: Vec<Value> = Vec::with_capacity(k);
    for i in (0..k).rev() {
        let mut covariance_obj = serde_json::Map::new();
        let mut correlation_obj = serde_json::Map::new();
        for j in 0..k {
            covariance_obj.insert(
                fields[j].clone(),
                serde_json::Number::from_f64(cov[i][j])
                    .map(Value::Number)
                    .unwrap_or(Value::Null),
            );
            correlation_obj.insert(
                fields[j].clone(),
                serde_json::Number::from_f64(corr(i, j))
                    .map(Value::Number)
                    .unwrap_or(Value::Null),
            );
        }
        fields_out.push(json!({
            "name": fields[i],
            "count": n,
            "mean": mean[i],
            "variance": variance[i],
            "skewness": skewness[i],
            "kurtosis": kurtosis[i],
            "covariance": covariance_obj,
            "correlation": correlation_obj,
        }));
    }
    json!({ "doc_count": n, "fields": fields_out })
}

/// `string_stats`: per-string metric aggregation — count, min/max/avg_length,
/// entropy, optional `distribution` histogram of character frequencies.
fn run_string_stats(params: &Value, docs: &[Value]) -> Value {
    let field = match params.get("field").and_then(Value::as_str) {
        Some(f) => f,
        None => return json!({"count": 0}),
    };
    let show_distribution = params
        .get("show_distribution")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let mut count: u64 = 0;
    let mut min_len = usize::MAX;
    let mut max_len: usize = 0;
    let mut total_len: usize = 0;
    let mut char_counts: HashMap<char, u64> = HashMap::new();
    for doc in docs {
        for v in extract_field_values(doc, field) {
            count += 1;
            let l = v.chars().count();
            if l < min_len {
                min_len = l;
            }
            if l > max_len {
                max_len = l;
            }
            total_len += l;
            for c in v.chars() {
                *char_counts.entry(c).or_insert(0) += 1;
            }
        }
    }
    if count == 0 {
        return json!({
            "count": 0,
            "min_length": Value::Null,
            "max_length": Value::Null,
            "avg_length": Value::Null,
            "entropy": 0.0,
        });
    }
    let total_chars: u64 = char_counts.values().copied().sum();
    let entropy: f64 = if total_chars == 0 {
        0.0
    } else {
        char_counts
            .values()
            .map(|c| {
                let p = *c as f64 / total_chars as f64;
                -p * p.log2()
            })
            .sum()
    };
    let avg_len = total_len as f64 / count as f64;
    let mut out = json!({
        "count": count,
        "min_length": min_len,
        "max_length": max_len,
        "avg_length": avg_len,
        "entropy": entropy,
    });
    if show_distribution {
        let mut dist = serde_json::Map::new();
        for (c, n) in &char_counts {
            dist.insert(c.to_string(), json!(*n as f64 / total_chars as f64));
        }
        out["distribution"] = Value::Object(dist);
    }
    out
}

/// `boxplot`: five-number summary (min, max, median, q1, q3) plus optional
/// lower/upper fences (outlier cutoffs). Uses linear interpolation for the
/// three quartile percentiles.
fn run_boxplot(params: &Value, docs: &[Value]) -> Value {
    let field = match params.get("field").and_then(Value::as_str) {
        Some(f) => f,
        None => {
            return json!({"min": Value::Null, "max": Value::Null, "q1": Value::Null, "q2": Value::Null, "q3": Value::Null})
        }
    };
    let mut values: Vec<f64> = Vec::new();
    for doc in docs {
        for n in extract_numeric_values(doc, field) {
            values.push(n);
        }
    }
    if values.is_empty() {
        return json!({
            "min": Value::Null,
            "max": Value::Null,
            "q1": Value::Null,
            "q2": Value::Null,
            "q3": Value::Null,
            "lower": Value::Null,
            "upper": Value::Null,
        });
    }
    values.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let percentile = |p: f64, vals: &[f64]| -> f64 {
        if vals.is_empty() {
            return 0.0;
        }
        if vals.len() == 1 {
            return vals[0];
        }
        let rank = p / 100.0 * (vals.len() - 1) as f64;
        let lo = rank.floor() as usize;
        let hi = rank.ceil() as usize;
        if lo == hi {
            return vals[lo];
        }
        vals[lo] + (rank - lo as f64) * (vals[hi] - vals[lo])
    };
    let q1 = percentile(25.0, &values);
    let q2 = percentile(50.0, &values);
    let q3 = percentile(75.0, &values);
    let iqr = q3 - q1;
    let lower = q1 - 1.5 * iqr;
    let upper = q3 + 1.5 * iqr;
    json!({
        "min": values[0],
        "max": values[values.len() - 1],
        "q1": q1,
        "q2": q2,
        "q3": q3,
        "lower": lower,
        "upper": upper,
    })
}

/// `top_metrics`: pick the metric values from the doc whose sort field
/// ranks highest (or lowest). Only single-metric selection is implemented.
fn run_top_metrics(params: &Value, docs: &[Value]) -> Value {
    let metrics: Vec<String> = params
        .get("metrics")
        .and_then(|v| match v {
            Value::Array(arr) => Some(
                arr.iter()
                    .filter_map(|m| m.get("field").and_then(Value::as_str).map(String::from))
                    .collect::<Vec<_>>(),
            ),
            Value::Object(o) => o
                .get("field")
                .and_then(Value::as_str)
                .map(|s| vec![s.to_string()]),
            _ => None,
        })
        .unwrap_or_default();
    if metrics.is_empty() {
        return json!({"top": []});
    }
    let size = params.get("size").and_then(Value::as_u64).unwrap_or(1) as usize;

    let sort_spec = params.get("sort").cloned();
    let (sort_field, sort_desc) = match sort_spec {
        Some(Value::Object(o)) => {
            if let Some((k, v)) = o.iter().next() {
                let desc = match v {
                    Value::String(s) => s == "desc",
                    Value::Object(ob) => ob
                        .get("order")
                        .and_then(Value::as_str)
                        .map(|s| s == "desc")
                        .unwrap_or(true),
                    _ => true,
                };
                (k.clone(), desc)
            } else {
                ("_score".to_string(), true)
            }
        }
        Some(Value::Array(arr)) => {
            if let Some(Value::Object(o)) = arr.first() {
                if let Some((k, v)) = o.iter().next() {
                    let desc = match v {
                        Value::String(s) => s == "desc",
                        Value::Object(ob) => ob
                            .get("order")
                            .and_then(Value::as_str)
                            .map(|s| s == "desc")
                            .unwrap_or(true),
                        _ => true,
                    };
                    (k.clone(), desc)
                } else {
                    ("_score".to_string(), true)
                }
            } else {
                ("_score".to_string(), true)
            }
        }
        _ => ("_score".to_string(), true),
    };

    let mut ranked: Vec<(f64, &Value)> = docs
        .iter()
        .filter_map(|d| {
            extract_numeric_values(d, &sort_field)
                .first()
                .copied()
                .map(|v| (v, d))
        })
        .collect();
    ranked.sort_by(|a, b| {
        let cmp = a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal);
        if sort_desc {
            cmp.reverse()
        } else {
            cmp
        }
    });

    let out: Vec<Value> = ranked
        .iter()
        .take(size)
        .map(|(sv, doc)| {
            let mut metrics_out = serde_json::Map::new();
            for m in &metrics {
                let vals = extract_numeric_values(doc, m);
                let v = vals
                    .first()
                    .and_then(|f| serde_json::Number::from_f64(*f).map(Value::Number))
                    .unwrap_or(Value::Null);
                metrics_out.insert(m.clone(), v);
            }
            json!({
                "sort": [sv],
                "metrics": metrics_out,
            })
        })
        .collect();
    json!({ "top": out })
}

/// Check whether a term matches an ES include/exclude regex. ES accepts
/// Java regex syntax; we use the `regex` crate (Rust flavor). Anchors
/// `^` and `$` aren't automatically added — ES matches if the regex
/// finds the term *anywhere* unless the pattern starts/ends explicitly.
fn term_matches_regex(term: &str, pattern: &str) -> bool {
    // ES `terms` include/exclude use a FULLY-ANCHORED Lucene regexp: the
    // pattern must match the ENTIRE term, not a substring (#837). Anchoring
    // with `^(?:…)$` makes `include:"a.*"` keep only terms starting with `a`
    // and `include:"ppl"` keep only the exact term `ppl` — matching ES.
    // Without the anchors `is_match` did a substring find, so `a.*` wrongly
    // matched every term containing an `a`.
    let anchored = format!("^(?:{pattern})$");
    match regex::Regex::new(&anchored) {
        Ok(re) => re.is_match(term),
        Err(_) => false,
    }
}

/// Reads the `_doc_count` metadata field that downsampled / rollup indices
/// attach to each physical document to advertise how many logical events it
/// represents. Defaults to `1` when absent or non-positive.
pub(crate) fn doc_count_weight(doc: &Value) -> u64 {
    doc.get("_doc_count")
        .and_then(|v| match v {
            Value::Number(n) => n.as_u64(),
            Value::String(s) => s.parse::<u64>().ok(),
            _ => None,
        })
        .filter(|&n| n > 0)
        .unwrap_or(1)
}

/// Sum `_doc_count` over a slice of matching docs. Handles missing or
/// non-positive values by contributing 1 per doc.
pub(crate) fn sum_doc_count(docs: &[Value]) -> u64 {
    docs.iter().map(doc_count_weight).sum()
}

/// Render a date using an ES date format name or SimpleDateFormat pattern.
/// Handles the named aliases ES ships (`strict_date_optional_time`,
/// `iso8601`, `epoch_millis`, etc.), falls through to java_to_strftime
/// for user-supplied patterns, and defaults to ISO-8601 UTC.
pub fn render_date_format(
    fmt: Option<&str>,
    epoch_ms: i64,
    dt: chrono::DateTime<chrono::Utc>,
) -> String {
    // ES format chains ("fmt1||fmt2"): rendering uses the FIRST format of
    // the chain (verified live on ES 8.13.4).  Mapping-declared chains are
    // already normalised at the es_compat injection site; this covers
    // request-level chains defensively.  Byte-identical no-op for all
    // non-chained formats (b7 DEFECT 2).
    let fmt = fmt.map(|f| f.split("||").next().unwrap_or(f).trim());
    match fmt {
        Some("epoch_millis") => epoch_ms.to_string(),
        Some("epoch_second") => (epoch_ms / 1000).to_string(),
        Some("strict_date_optional_time")
        | Some("strict_date_optional_time_nanos")
        | Some("iso8601")
        | Some("date_optional_time") => dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
        Some("basic_date") => dt.format("%Y%m%d").to_string(),
        Some("basic_date_time") => dt.format("%Y%m%dT%H%M%S%.3fZ").to_string(),
        Some("basic_time") => dt.format("%H%M%S%.3fZ").to_string(),
        Some("date") | Some("strict_date") => dt.format("%Y-%m-%d").to_string(),
        Some("date_hour_minute_second") | Some("strict_date_hour_minute_second") => {
            dt.format("%Y-%m-%dT%H:%M:%S").to_string()
        }
        Some("date_time") | Some("strict_date_time") => {
            dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string()
        }
        Some("hour") => dt.format("%H").to_string(),
        Some("hour_minute_second") => dt.format("%H:%M:%S").to_string(),
        Some("year") | Some("strict_year") => dt.format("%Y").to_string(),
        Some("year_month") | Some("strict_year_month") => dt.format("%Y-%m").to_string(),
        Some("year_month_day") | Some("strict_year_month_day") => dt.format("%Y-%m-%d").to_string(),
        Some(pat) if !pat.is_empty() => {
            let s = java_to_strftime(pat);
            dt.format(&s).to_string()
        }
        _ => dt.format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
    }
}

/// `true` when `fmt` is one of the named ES date-format aliases that
/// `render_date_format` resolves via its alias table above.  Callers that
/// feed a format straight to `java_to_strftime` (e.g. `run_date_range`'s
/// render closure) must check this first — translating an alias NAME as a
/// SimpleDateFormat pattern emits its letters as pattern tokens
/// ("strict_date_optional_time" → garbage).  Keep in sync with the match
/// arms of `render_date_format`.
pub(crate) fn is_named_date_format(fmt: &str) -> bool {
    matches!(
        fmt,
        "epoch_millis"
            | "epoch_second"
            | "strict_date_optional_time"
            | "strict_date_optional_time_nanos"
            | "iso8601"
            | "date_optional_time"
            | "basic_date"
            | "basic_date_time"
            | "basic_time"
            | "date"
            | "strict_date"
            | "date_hour_minute_second"
            | "strict_date_hour_minute_second"
            | "date_time"
            | "strict_date_time"
            | "hour"
            | "hour_minute_second"
            | "year"
            | "strict_year"
            | "year_month"
            | "strict_year_month"
            | "year_month_day"
            | "strict_year_month_day"
    )
}

/// Translate a small subset of Java SimpleDateFormat patterns into
/// chrono's strftime dialect. Only the common tokens ES YAML tests
/// exercise (`yyyy`, `MM`, `dd`, `HH`, `mm`, `ss`, `SSS`, `Z`) are
/// supported; literal characters pass through unchanged.
pub(crate) fn java_to_strftime(pattern: &str) -> String {
    let mut out = String::with_capacity(pattern.len() + 4);
    let bytes = pattern.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        // Java SimpleDateFormat literal section between two `'` quotes —
        // pass through unchanged after stripping the quotes.
        if bytes[i] == b'\'' {
            i += 1;
            while i < bytes.len() && bytes[i] != b'\'' {
                out.push(bytes[i] as char);
                i += 1;
            }
            if i < bytes.len() {
                i += 1;
            } // skip closing quote
            continue;
        }
        // Match longest-first. Java uses `uuuu` for proleptic year and
        // `yyyy` for year-of-era; both render as 4-digit year in modern
        // ES so map both to `%Y`. `ZZZZZ` is offset with colon; `XXX`
        // similarly emits `+HH:MM`.
        let matched: Option<(usize, &str)> =
            if bytes[i..].starts_with(b"uuuu") || bytes[i..].starts_with(b"yyyy") {
                Some((4, "%Y"))
            } else if bytes[i..].starts_with(b"yy") {
                Some((2, "%y"))
            } else if bytes[i..].starts_with(b"MM") {
                Some((2, "%m"))
            } else if bytes[i..].starts_with(b"dd") {
                Some((2, "%d"))
            } else if bytes[i..].starts_with(b"HH") {
                Some((2, "%H"))
            } else if bytes[i..].starts_with(b"mm") {
                Some((2, "%M"))
            } else if bytes[i..].starts_with(b"ss") {
                Some((2, "%S"))
            } else if bytes[i..].starts_with(b"SSSSSSSSS") {
                Some((9, "%9f"))
            } else if bytes[i..].starts_with(b"SSSSSS") {
                Some((6, "%6f"))
            } else if bytes[i..].starts_with(b"SSS") {
                Some((3, "%3f"))
            } else if bytes[i..].starts_with(b"ZZZZZ") {
                Some((5, "%:z"))
            } else if bytes[i..].starts_with(b"XXX") {
                Some((3, "%:z"))
            } else if bytes[i..].starts_with(b"Z") {
                Some((1, "%z"))
            } else {
                None
            };
        match matched {
            Some((n, s)) => {
                out.push_str(s);
                i += n;
            }
            None => {
                out.push(bytes[i] as char);
                i += 1;
            }
        }
    }
    out
}

/// Format a Unix epoch in milliseconds as the ISO-8601 UTC string with
/// millisecond precision, matching Elasticsearch's default date format
/// (`"yyyy-MM-dd'T'HH:mm:ss.SSSZ"` → `"2016-05-03T00:00:00.000Z"`).
///
/// Moved to `xerj_common::schema` (one definition: the autoindex catalog
/// read-back renders raw-millis date fields with the same format, #1183) and
/// re-exported here so this module's call sites keep the bare name.
pub(crate) use xerj_common::schema::epoch_ms_to_iso8601_utc;

/// Count fractional-second digits in an ISO-8601 string
/// (e.g. "2021-08-12T00:00:00.000000000+02:00" → 9).
pub(crate) fn detect_fractional_digits(s: &str) -> usize {
    let Some(dot) = s.find('.') else { return 0 };
    s[dot + 1..]
        .chars()
        .take_while(|c| c.is_ascii_digit())
        .count()
}

/// Render an epoch-ms instant as an ISO-8601 string with configurable
/// fractional-second precision and optional fixed offset. When `offset`
/// is `None` the output is UTC with a `Z` suffix. With a fixed offset
/// the suffix becomes `±HH:MM`.
pub(crate) fn render_iso_date(
    ms: i64,
    nanos_digits: usize,
    offset: Option<chrono::FixedOffset>,
) -> String {
    let Some(dt_utc) = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(ms) else {
        return String::new();
    };
    let frac = match nanos_digits {
        9 => "%9f",
        6 => "%6f",
        _ => "%3f",
    };
    if let Some(off) = offset {
        let dt = dt_utc.with_timezone(&off);
        let fmt = format!("%Y-%m-%dT%H:%M:%S.{}%:z", frac);
        return dt.format(&fmt).to_string();
    }
    let fmt = format!("%Y-%m-%dT%H:%M:%S.{}Z", frac);
    dt_utc.format(&fmt).to_string()
}

/// Shortest prefix the `%Y-%m-%dT%H:%M:%S` part of the no-colon zone-offset
/// pattern can consume.
///
/// chrono parses numeric fields greedily but with a *minimum* width of one
/// digit, so the smallest input that pattern accepts is `5-1-2T3:4:5` — 11
/// bytes. Nothing that can precede the offset (the optional `%.f`, the
/// whitespace chrono skips before a numeric field, a signed or wider year)
/// shortens that prefix; all of them only push the offset further right.
const DATE_TIME_PREFIX_MIN_LEN: usize = 11;

/// Bytes a `%z` offset needs after its sign: two for the hours and two for
/// the minutes, both mandatory (`allow_missing_minutes` is off for `%z`).
const ZONE_OFFSET_MIN_TAIL: usize = 4;

/// Separator bytes the probe window budgets for between the offset's hours
/// and its minutes — one, which is all the spellings `%z` accepts need.
///
/// chrono's separator scanner trims a *run* of colons and whitespace, so
/// `+00:::00` and `+00 : 00` are legal too and put their sign further left
/// than any constant window can reach. [`may_carry_zone_offset`] answers those
/// by over-matching rather than by chasing the run, which is what keeps it
/// O(1) — see there.
const ZONE_OFFSET_MAX_SEPARATORS: usize = 1;

/// Width of the fixed window at the end of a value that
/// [`may_carry_zone_offset`] reads: the sign, `HH`, the separator budget, `MM`.
///
/// `%z` closes the pattern and `parse_from_str` insists the whole value be
/// consumed, so a `%z` offset is pinned to the *end* of the value — which is
/// what makes a constant-width window possible at all. Spellings it covers
/// exactly, with where each puts its sign:
///
/// | spelling  | sign at   |
/// |-----------|-----------|
/// | `±HHMM`   | `len - 5` |
/// | `±HH:MM`  | `len - 6` |
/// | `±HH MM`  | `len - 6` |
///
/// `−` MINUS SIGN (U+2212) spells its sign in three bytes, of which only the
/// last lands in the window; the high-bit test in [`is_zone_offset_sign`]
/// catches it there. `±HH` on its own is *not* a spelling `%z` accepts —
/// `allow_missing_minutes` is off, so chrono rejects a value that stops after
/// the hours whatever this probe says.
const ZONE_OFFSET_PROBE_BYTES: usize = 1 + 2 + ZONE_OFFSET_MAX_SEPARATORS + 2;

/// The window is a constant, not a function of the value: that is the whole
/// point of it, so pin it at compile time.
const _: () = assert!(ZONE_OFFSET_PROBE_BYTES == 6);

/// Could this byte be the sign that opens a `%z` zone offset?
///
/// chrono accepts `+` (U+002B), `-` (U+002D) and MINUS SIGN (U+2212). The
/// subtraction also matches `,` (U+002C) and the high-bit test matches every
/// non-ASCII byte rather than just U+2212's trailing byte — both over-match on
/// purpose, see [`may_carry_zone_offset`].
#[inline(always)]
fn is_zone_offset_sign(c: u8) -> bool {
    c.wrapping_sub(b'+') <= 2 || c >= 0x80
}

/// Could this byte sit between a `%z` offset's hours and its minutes?
///
/// chrono trims a run of `:` and *any* Unicode whitespace there, so the ASCII
/// set is `:` plus `\t\n\x0b\x0c\r` and space. The high-bit test stands in for
/// the non-ASCII whitespace (and for any other byte of a multi-byte char)
/// instead of decoding it — over-matching on purpose, as above.
#[inline(always)]
fn is_zone_offset_separator(c: u8) -> bool {
    matches!(c, b':' | b' ' | 0x09..=0x0d) || c >= 0x80
}

/// Cheap shape probe: could `s` possibly carry a trailing numeric zone offset
/// that `%z` would accept?
///
/// Answering costs a length check and a look at the last
/// [`ZONE_OFFSET_PROBE_BYTES`] bytes — no scan, and no dependence on how long
/// `s` is. That matters because this runs per date field per document and
/// field values are arbitrary strings: an earlier cut of this guard hunted for
/// the sign across `[11, len - 5)`, which is O(len), and left a 64 KB value
/// ~19x *slower* to reject than it had been with no guard at all.
///
/// A constant window is enough because `%z` ends the pattern and
/// `parse_from_str` requires the whole value to be consumed, so an accepted
/// value ends with the offset's two minute digits and everything the offset
/// needs sits at a fixed distance from that end.
///
/// The probe is deliberately one-sided: a false positive only pays for the
/// parse that would have run anyway, whereas a false negative would change
/// results, so every judgement call here over-matches.
fn may_carry_zone_offset(s: &str) -> bool {
    let b = s.as_bytes();
    // Shortest value the pattern can accept at all: the datetime prefix, the
    // sign, and `HHMM`.
    if b.len() < DATE_TIME_PREFIX_MIN_LEN + 1 + ZONE_OFFSET_MIN_TAIL {
        return false;
    }
    // Take a fixed-width tail and nothing else. The bound is structural —
    // below this line there are six bytes and no slice to walk — rather than
    // an early exit that a hostile value could talk its way out of.
    let &[w0, w1, w2, w3, m1, m2] = &b[b.len() - ZONE_OFFSET_PROBE_BYTES..] else {
        // Unreachable: the length check above leaves at least the window.
        return false;
    };
    // `±HHMM` — the spelling this whole branch exists for — puts its sign
    // right here, and that case is worth answering in three instructions.
    if is_zone_offset_sign(w1) {
        return true;
    }
    // `±HH:MM` and `±HH MM` put it one byte further left, behind a separator.
    // A longer separator run is legal too — `+00 : 00` really does parse — and
    // walks the sign out of the window entirely; chasing that run would cost
    // O(len) on a value that is nothing but separators, so it is over-matched
    // from the separators it leaves behind instead.
    //
    // The leading `&&` is the one branch worth keeping: an index's date field
    // is overwhelmingly all-offset or all-offsetless, so it predicts, and
    // taking it is what makes `…T07:31:52.102` — the shape issue #96 is about
    // — cost two byte compares. The rest are a couple of instructions each and
    // do not predict, so they stay bitwise.
    is_zone_offset_separator(w3)
        && ((is_zone_offset_sign(w0) | is_zone_offset_separator(w2))
            // `%z` needs two minute digits, they are the value's last two
            // bytes, and chrono rejects a first minute digit above '5'.
            & matches!(m1, b'0'..=b'5')
            & m2.is_ascii_digit())
}

// Test-only tally of how many times the no-colon `%z` parse actually ran on
// this thread. Which branch runs is a pure performance property — results are
// identical either way — so `nocolon_offset_parse_is_guarded` asserts it by
// counting attempts rather than by timing anything.
#[cfg(test)]
thread_local! {
    static NOCOLON_OFFSET_ATTEMPTS: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
}

/// The no-colon zone-offset parse itself, behind [`may_carry_zone_offset`].
#[inline]
fn parse_nocolon_zone_offset_ms(s: &str) -> Option<i64> {
    #[cfg(test)]
    NOCOLON_OFFSET_ATTEMPTS.with(|c| c.set(c.get() + 1));
    chrono::DateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.f%z")
        .ok()
        .map(|dt| dt.timestamp_millis())
}

/// Parse an ES date string or epoch-ms number to a Unix timestamp in milliseconds.
pub(crate) fn parse_date_ms(val: &Value) -> Option<i64> {
    match val {
        Value::Number(n) => n.as_i64(),
        Value::String(s) => {
            // Try RFC3339 first, then a few common formats.
            if let Ok(dt) = chrono::DateTime::parse_from_rfc3339(s) {
                return Some(dt.timestamp_millis());
            }
            // RFC3339 requires a colon in the zone offset (`+00:00`); ES's
            // own `strict_date_time`/`XX`-style formats also accept the
            // no-colon numeric form (`+0000`), which real clients emit —
            // e.g. Java's default `OffsetDateTime.toString()`-adjacent
            // formatters. Without this, a validly-mapped, successfully
            // ingested date like "2025-01-24T07:31:52.102+0000" silently
            // drops out of every date aggregation/range query even though
            // it's neither malformed nor `_ignored`.
            //
            // The parse is guarded (issue #96): `parse_date_ms` runs per date
            // field per document on ingest, and unguarded this branch made
            // every *offsetless* ISO value — the overwhelmingly common shape,
            // and one no zone-offset pattern can ever match — pay for a
            // failed offset parse before reaching the branch that does match
            // it, roughly doubling that path. The guard is a necessary
            // condition for the parse below, so gating on it cannot change
            // any result; it only stops offsetless values from paying.
            if may_carry_zone_offset(s) {
                if let Some(ms) = parse_nocolon_zone_offset_ms(s) {
                    return Some(ms);
                }
            }
            // Try ISO-8601 without timezone (treat as UTC).
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.f") {
                return Some(dt.and_utc().timestamp_millis());
            }
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
                return Some(dt.and_utc().timestamp_millis());
            }
            if let Ok(dt) = chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d") {
                return Some(dt.and_hms_opt(0, 0, 0)?.and_utc().timestamp_millis());
            }
            // Partial ISO dates (`strict_date_optional_time` accepts them and
            // ES indexes them min-filled): `2026-02` → 2026-02-01T00:00:00,
            // `2026-02-15T08` / `2026-02-15T08:30` → minutes/seconds zeroed.
            // Bare 4-digit years are intentionally NOT parsed here — a doc
            // value of "2026" is far more likely a numeric string, and the
            // final i64 fallback below keeps its numeric interpretation.
            if let Ok(ym) = chrono::NaiveDate::parse_from_str(&format!("{s}-01"), "%Y-%m-%d") {
                if s.len() == 7 && s.as_bytes()[4] == b'-' {
                    return Some(ym.and_hms_opt(0, 0, 0)?.and_utc().timestamp_millis());
                }
            }
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M") {
                return Some(dt.and_utc().timestamp_millis());
            }
            if s.len() == 13 && s.as_bytes()[10] == b'T' {
                // Hour-partial (`2026-02-15T08`): append minutes so the
                // pattern terminates cleanly, then treat as HH:00.
                if let Ok(dt) =
                    chrono::NaiveDateTime::parse_from_str(&format!("{s}:00"), "%Y-%m-%dT%H:%M")
                {
                    return Some(dt.and_utc().timestamp_millis());
                }
            }
            // Slash-separated form `YYYY/MM/DD` is accepted by ES via the
            // default date mapping — treat it as YMD at UTC midnight.
            if let Ok(dt) = chrono::NaiveDate::parse_from_str(s, "%Y/%m/%d") {
                return Some(dt.and_hms_opt(0, 0, 0)?.and_utc().timestamp_millis());
            }
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y/%m/%d %H:%M:%S") {
                return Some(dt.and_utc().timestamp_millis());
            }
            // Space-separated form `YYYY-MM-DD HH:MM:SS[.fff]` (ES Java
            // pattern `yyyy-MM-dd HH:mm:ss.SSS`).
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S%.f") {
                return Some(dt.and_utc().timestamp_millis());
            }
            if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
                return Some(dt.and_utc().timestamp_millis());
            }
            // Fallback: try parsing as a raw integer string.
            s.parse::<i64>().ok()
        }
        _ => None,
    }
}

#[cfg(test)]
mod parse_date_ms_tests {
    //! Regression coverage for a real bug found live: a validly-mapped,
    //! successfully ingested date string with a no-colon numeric zone
    //! offset ("+0000" instead of "+00:00") silently dropped out of every
    //! aggregation and range query — min/max returned null, a dashboard
    //! panel's time-range filter excluded the document — even though the
    //! field was neither malformed nor `_ignored`. Root cause:
    //! `chrono::DateTime::parse_from_rfc3339` requires the colon per the
    //! RFC3339 spec, and no other branch here handled the no-colon form.
    use super::*;

    #[test]
    fn numeric_offset_without_colon_parses() {
        let ms = parse_date_ms(&Value::String("2025-01-24T07:31:52.102+0000".to_string()));
        assert!(ms.is_some(), "expected a parsed value, got None");
    }

    #[test]
    fn numeric_offset_without_colon_matches_with_colon() {
        // Same instant, two valid spellings of the same offset — both must
        // resolve to the identical epoch-ms value.
        let with_colon = parse_date_ms(&Value::String("2025-01-24T07:31:52.102+00:00".to_string()));
        let without_colon =
            parse_date_ms(&Value::String("2025-01-24T07:31:52.102+0000".to_string()));
        assert_eq!(with_colon, without_colon);
        assert!(with_colon.is_some());
    }

    #[test]
    fn numeric_offset_without_colon_nonzero() {
        // A non-zero offset must actually shift the instant, not just parse
        // and silently treat it as UTC.
        let plus_two = parse_date_ms(&Value::String("2025-01-24T09:31:52.102+0200".to_string()));
        let utc = parse_date_ms(&Value::String("2025-01-24T07:31:52.102Z".to_string()));
        assert_eq!(plus_two, utc);
    }

    #[test]
    fn z_suffix_still_works() {
        let ms = parse_date_ms(&Value::String("2025-01-24T07:31:52.102Z".to_string()));
        assert!(ms.is_some());
    }

    #[test]
    fn colon_offset_still_works() {
        let ms = parse_date_ms(&Value::String("2025-01-24T07:31:52.102+00:00".to_string()));
        assert!(ms.is_some());
    }

    /// Reset the per-thread tally, then report how many no-colon `%z` parses
    /// `parse_date_ms` actually ran for `input`.
    fn zone_offset_parses_for(input: &str) -> u32 {
        NOCOLON_OFFSET_ATTEMPTS.with(|c| c.set(0));
        let _ = parse_date_ms(&Value::String(input.to_string()));
        NOCOLON_OFFSET_ATTEMPTS.with(|c| c.get())
    }

    /// Issue #96: the no-colon `%z` parse must not run for values that cannot
    /// possibly carry a zone offset.
    ///
    /// `parse_date_ms` runs per date field per document on ingest, and the
    /// branch PR #91 added sits ahead of the offsetless fast paths — so before
    /// the guard, *every* offsetless ISO value paid for a doomed offset parse
    /// on the hottest shape there is, roughly doubling that path. Which branch
    /// runs is invisible to results (`parse_date_ms_golden_matrix` is
    /// byte-identical either way), so this asserts the work that was skipped
    /// rather than the value that came out — no timing involved.
    #[test]
    fn nocolon_offset_parse_is_guarded() {
        // Shapes with no offset at all: the parse must never be attempted.
        for offsetless in [
            "2025-01-24T07:31:52.102",
            "2025-01-24T07:31:52.102456789",
            "2025-01-24T07:31:52",
            "2025-01-24T07:31",
            "2025-01-24T07",
            "2025-01-24",
            "2025-01",
            "2025/01/24",
            "2025/01/24 07:31:52",
            "2025-01-24 07:31:52.102",
            "1737704312102",
            "-1737704312102",
            "not-a-date",
            "",
        ] {
            assert_eq!(
                zone_offset_parses_for(offsetless),
                0,
                "{offsetless:?} cannot carry a zone offset, yet the `%z` parse ran"
            );
        }
        // A no-colon offset still reaches the parse, exactly once.
        for with_offset in [
            "2025-01-24T07:31:52.102+0000",
            "2025-01-24T02:31:52.102-0500",
            "2025-01-24T07:31:52+0000",
            "2025-01-24T07:31:52.102 +0000",
            "2025-01-24T07:31:52.102+00 : 00",
            "5-1-2T3:4:5+0000",
        ] {
            assert_eq!(
                zone_offset_parses_for(with_offset),
                1,
                "{with_offset:?} needs the `%z` parse and it did not run"
            );
        }
        // Values the RFC3339 fast path already answers never get that far.
        for rfc3339 in [
            "2025-01-24T07:31:52.102Z",
            "2025-01-24T07:31:52.102+00:00",
            "2025-01-24T02:31:52.102-05:00",
        ] {
            assert_eq!(zone_offset_parses_for(rfc3339), 0, "{rfc3339:?}");
        }
    }

    /// The guard is only allowed to be wrong in one direction. A false
    /// positive costs a doomed parse; a false negative would silently drop a
    /// parseable date back out of every aggregation — the exact bug PR #91
    /// fixed. Assert that one-sidedness directly over a generated corpus:
    /// wherever the guard says no, chrono must agree the parse fails.
    #[test]
    fn zone_offset_guard_never_false_negatives() {
        let mut cases: Vec<String> = GOLDEN
            .iter()
            .map(|(input, _)| (*input).to_string())
            .collect();

        // Every combination of chrono-legal field widths, each with every
        // offset spelling. The widths are the point: chrono accepts one-digit
        // fields, which is what moves the earliest possible sign position and
        // what both of the guard's lower bounds are derived from.
        let tails = [
            "",
            "+0000",
            "-0530",
            "+00:00",
            "-05:30",
            "Z",
            "z",
            "+00:::00",
            "+00  00",
            "\u{2212}0500",
            " +0000",
            "\t-0530",
            "+0",
            "+00",
            "+000",
            "+00000",
        ];
        for y in ["1", "12", "123", "2025", "12025"] {
            for mo in ["1", "01"] {
                for d in ["2", "02"] {
                    for h in ["3", "03"] {
                        for mi in ["4", "04"] {
                            for se in ["5", "05"] {
                                for frac in ["", ".1", ".102", ".102456789"] {
                                    for t in tails {
                                        cases.push(format!("{y}-{mo}-{d}T{h}:{mi}:{se}{frac}{t}"));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Single-edit mutations of a few skeletons, so the boundaries the
        // guard keys on get probed from both sides.
        let interesting = [
            '+', '-', 'Z', 'T', ':', '.', ' ', '0', '9', 'x', '/', '\u{2212}',
        ];
        for skeleton in [
            "2025-01-24T07:31:52.102+0000",
            "2025-01-24T07:31:52",
            "5-1-2T3:4:5+0000",
            "2025-01-24 07:31:52.102",
        ] {
            let chars: Vec<char> = skeleton.chars().collect();
            for i in 0..=chars.len() {
                for c in interesting {
                    let mut ins = chars.clone();
                    ins.insert(i, c);
                    cases.push(ins.into_iter().collect());
                    if i < chars.len() {
                        let mut sub = chars.clone();
                        sub[i] = c;
                        cases.push(sub.into_iter().collect());
                    }
                }
                if i < chars.len() {
                    let mut del = chars.clone();
                    del.remove(i);
                    cases.push(del.into_iter().collect());
                }
            }
        }

        let mut rejected = 0usize;
        let mut parseable = 0usize;
        for s in &cases {
            let parses = chrono::DateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.f%z").is_ok();
            if parses {
                parseable += 1;
            }
            if !may_carry_zone_offset(s) {
                rejected += 1;
                assert!(
                    !parses,
                    "guard rejected {s:?}, but the `%z` parse accepts it — that value \
                     would silently stop parsing again (the bug PR #91 fixed)"
                );
            }
        }
        // Keep the corpus from quietly going vacuous.
        assert!(
            parseable > 1000 && rejected > 1000,
            "corpus stopped exercising both sides: {parseable} parseable, {rejected} \
             rejected out of {}",
            cases.len()
        );
    }

    #[test]
    fn zone_offset_guard_bounds() {
        // The shortest datetime chrono accepts in front of an offset is 11
        // bytes, and `HHMM` behind it is another four, so nothing under 16
        // bytes can carry one — including a bare negative epoch...
        assert!(may_carry_zone_offset("5-1-2T3:4:5+0000"));
        assert!(!may_carry_zone_offset("2025-01-24"));
        assert!(!may_carry_zone_offset("-1737704312102"));
        // ...and the offset ends the value, so a sign in the last four bytes
        // has nowhere to put its minutes.
        assert!(!may_carry_zone_offset("2025-01-24T07:31:52.102+"));
        assert!(!may_carry_zone_offset("2025-01-24T07:31:52.1+000"));
        // One separator between the hours and the minutes is in the window,
        // and one-digit seconds in front of it are legal and really do parse.
        assert!(may_carry_zone_offset("2025-01-02T03:04:5+00:00"));
        assert_eq!(
            parse_date_ms(&Value::String("2025-01-02T03:04:5+00:00".to_string())),
            Some(1735787045000)
        );
        // A longer separator run walks the sign out of the window, and the
        // probe answers "maybe" rather than chase it.
        assert!(may_carry_zone_offset("2025-01-24T07:31:52.102+00 : 00"));
        // Offsetless canonical values — the shape the guard exists to spare.
        assert!(!may_carry_zone_offset("2025-01-24T07:31:52.102"));
        assert!(!may_carry_zone_offset("2025-01-24T07:31:52"));
        // MINUS SIGN U+2212 is a zone-offset sign for chrono too.
        assert!(may_carry_zone_offset("2025-01-24T02:31:52.102\u{2212}0500"));
    }

    /// Issue #96, second cut: the probe has to cost the same on a 64 KB field
    /// value as on a 20 byte one.
    ///
    /// The first cut scanned `[11, len - 5)` for a sign byte. That is O(len)
    /// on the same per-document path this is all supposed to be making
    /// cheaper, and it left long sign-free values several times *slower* than
    /// they had been with no guard at all — 64 KB went 807.8 ns/op → 15617.7
    /// ns/op. Cost is invisible to results, so pin the shape that makes it
    /// O(1) instead of timing it: the answer is fixed by the last
    /// [`ZONE_OFFSET_PROBE_BYTES`] bytes plus the length, so no amount of
    /// filler in front of them can change it — not even filler made entirely
    /// of the bytes a scan would have stopped on.
    #[test]
    fn zone_offset_probe_window_is_bounded() {
        // Every tail shape that reaches a different branch of the probe.
        let tails = [
            "+0000",
            "-0530",
            "+00:00",
            "-05:30",
            "+00 00",
            "+00:::00",
            "+00",
            "+000",
            "Z",
            "z",
            "",
            ".102",
            ":52",
            "00",
            "0",
            "x",
            "\u{2212}0500",
            "\u{2212}05:00",
            "+0060",
            "+9959",
        ];
        // Filler bytes chosen to be exactly what an unbounded scan hunts for.
        let fillers = ["a", "+", "-", ":", ",", "\u{2212}", " ", "0", "-+,: "];
        for tail in tails {
            for filler in fillers {
                let reps = 64 / filler.len();
                let short = format!("{}{tail}", filler.repeat(reps));
                let want = may_carry_zone_offset(&short);
                for scale in [8usize, 64, 1024] {
                    let long = format!("{}{tail}", filler.repeat(reps * scale));
                    assert_eq!(
                        may_carry_zone_offset(&long),
                        want,
                        "probe read past its window: {:?}+{tail:?} at {} bytes disagreed \
                         with the same tail at {} bytes",
                        filler,
                        long.len(),
                        short.len()
                    );
                }
            }
        }
        // And the same property where it actually pays off: a long value must
        // not reach the parse either.
        assert_eq!(zone_offset_parses_for(&"lorem ipsum est ".repeat(4096)), 0);
        assert_eq!(zone_offset_parses_for(&"0123456789".repeat(6554)), 0);
    }

    /// The scaling loop above is true but does not DISCRIMINATE: an unbounded
    /// scan passes it. Growing a homogeneous filler cannot expose a scan,
    /// because a `"+"` filler contains a `+` at every length and an `"a"`
    /// filler contains none at every length, so the scan's answer is invariant
    /// under exactly the transformation being applied. (Verified: replacing
    /// this function's body with the previous O(len) scan leaves that test
    /// green.)
    ///
    /// The property that actually characterises the fix is that the answer is
    /// a function of `(len, last ZONE_OFFSET_PROBE_BYTES bytes)` and nothing
    /// else. So hold BOTH the length and the window fixed and perturb a byte
    /// strictly below `len - ZONE_OFFSET_PROBE_BYTES`. A windowed probe cannot
    /// see the edit; a scan can, and does — the same sweep run against the old
    /// scan violates this on 465 of 480 cases.
    #[test]
    fn zone_offset_probe_ignores_every_byte_below_its_window() {
        let tails = [
            "+0000", "-05:30", "+00 00", "+00:::00", "aaaaaa", "abc123", "Z12345", ".102Z0",
        ];
        // Single-byte edits only: a lone continuation byte is not valid UTF-8,
        // so it could never reach this function through a `&str` anyway. The
        // `>= 0x80` arm of `is_zone_offset_separator` is exercised by the
        // golden matrix's real multi-byte separators instead.
        let injected = *b"+-:,a0 T.";
        let mut checks = 0usize;
        for tail in tails {
            for len in [12usize, 22, 40, 97, ZONE_OFFSET_PROBE_BYTES + 512] {
                // Need room for the tail plus at least one byte in front of
                // the window to perturb.
                if len < tail.len() + 1 {
                    continue;
                }
                // `base` pins the window (the last six bytes) and pads in
                // front with bytes the probe must ignore.
                let pad = len - tail.len();
                let base: Vec<u8> = b"a".repeat(pad).into_iter().chain(tail.bytes()).collect();
                assert_eq!(base.len(), len);
                let want = may_carry_zone_offset(std::str::from_utf8(&base).unwrap());
                for &inj in &injected {
                    // Every position strictly below the window.
                    for pos in 0..base.len().saturating_sub(ZONE_OFFSET_PROBE_BYTES) {
                        let mut probe = base.clone();
                        probe[pos] = inj;
                        let s = std::str::from_utf8(&probe).expect("ascii edit stays utf8");
                        checks += 1;
                        assert_eq!(
                            may_carry_zone_offset(s),
                            want,
                            "probe answered differently after editing byte {pos} of {} \
                             (below the {ZONE_OFFSET_PROBE_BYTES}-byte window) to {inj:#04x}; \
                             the window is unmoved, so it must have read past it",
                            base.len()
                        );
                    }
                }
            }
        }
        // Guard against the sweep silently becoming empty and passing.
        assert!(checks > 1000, "sweep only ran {checks} checks");
    }

    /// Golden matrix over every input class this function accepts, generated
