#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn multivalued_numeric_metric_aggs_use_all_values() {
        // ES aggregates over EVERY value of a multi-valued field; the old path
        // used only the first (extract_numeric), so sum/avg/stats undercounted
        // and min/max could miss the extreme. `n` values: [1,20] + [3].
        let docs = vec![json!({ "n": [1, 20] }), json!({ "n": [3] })];
        let r = run_aggs(
            &json!({
                "s": {"sum": {"field": "n"}},
                "a": {"avg": {"field": "n"}},
                "mn": {"min": {"field": "n"}},
                "mx": {"max": {"field": "n"}},
                "st": {"stats": {"field": "n"}},
                "es": {"extended_stats": {"field": "n"}},
            }),
            &docs,
        );
        assert_eq!(r["s"]["value"].as_f64(), Some(24.0), "sum");
        assert_eq!(r["a"]["value"].as_f64(), Some(8.0), "avg");
        assert_eq!(r["mn"]["value"].as_f64(), Some(1.0), "min");
        assert_eq!(r["mx"]["value"].as_f64(), Some(20.0), "max");
        assert_eq!(r["st"]["count"].as_u64(), Some(3), "stats.count");
        assert_eq!(r["st"]["sum"].as_f64(), Some(24.0), "stats.sum");
        assert_eq!(r["st"]["max"].as_f64(), Some(20.0), "stats.max");
        assert_eq!(r["es"]["count"].as_u64(), Some(3), "extended_stats.count");

        // `missing`: a doc with no value contributes the placeholder once.
        let dm = vec![json!({ "n": [2, 4] }), json!({ "x": 1 })];
        let rm = run_aggs(&json!({ "s": {"sum": {"field": "n", "missing": 10}} }), &dm);
        assert_eq!(rm["s"]["value"].as_f64(), Some(16.0), "sum with missing");

        // Date-string field (single value) must still resolve via date coercion
        // — the all-values extractor keeps `extract_numeric`'s date fallback.
        let dd = vec![json!({ "d": "2016-05-03" }), json!({ "d": "2016-05-01" })];
        let rd = run_aggs(&json!({ "mn": {"min": {"field": "d"}} }), &dd);
        assert!(
            rd["mn"]["value"].as_f64().is_some(),
            "date min resolves: {rd:?}"
        );
        assert!(
            rd["mn"]["value_as_string"].is_string(),
            "date min_as_string: {rd:?}"
        );
    }

    #[test]
    fn missing_agg_counts_empty_and_null_arrays() {
        // ES `missing` agg counts docs with NO value: absent, null, [] and
        // [null] all count as missing; a real value does not. This is the
        // exact complement of `exists` (#792/#793 value_present).
        let docs = vec![
            json!({ "f": 5 }),      // present
            json!({ "f": null }),   // missing
            json!({ "f": [] }),     // missing (empty array)
            json!({ "f": [null] }), // missing (only-null array)
            json!({ "other": 1 }),  // missing (absent)
        ];
        let r = run_aggs(&json!({ "m": { "missing": { "field": "f" } } }), &docs);
        assert_eq!(r["m"]["doc_count"].as_u64(), Some(4), "got {r:?}");
    }

    #[test]
    fn cmp_term_key_orders_longs_beyond_f64_range_exactly() {
        use std::cmp::Ordering;
        // Snowflake IDs / epoch-nanos exceed f64's 2^53 exact range. `cmp_term_key`
        // must compare such keys by exact i64 value: a lossy i64->f64 widening
        // collapses distinct longs to the same float and returns Equal (then the
        // stable sort leaves them in arbitrary hash order — a wrong, unstable
        // result vs ES). f64 rounding is monotonic, so the defect only ever
        // shows as this Equal-collapse, which is why it is asserted directly.
        assert_eq!(
            cmp_term_key("9007199254740992", "9007199254740993"), // 2^53, 2^53+1
            Ordering::Less,
            "adjacent longs past 2^53 must not collapse to Equal"
        );
        assert_eq!(
            cmp_term_key("1500000000000000002", "1500000000000000001"), // snowflake scale
            Ordering::Greater
        );
        // Small ints, negatives, floats and int/float mixes stay numeric; a
        // non-numeric key stays lexical.
        assert_eq!(cmp_term_key("2", "10"), Ordering::Less);
        assert_eq!(cmp_term_key("-5", "-2"), Ordering::Less);
        assert_eq!(cmp_term_key("9.5", "10"), Ordering::Less);
        assert_eq!(cmp_term_key("banana", "apple"), Ordering::Greater);
    }

    #[test]
    fn filters_agg_other_bucket_counts_unmatched_docs() {
        // ES `filters` agg: `other_bucket`/`other_bucket_key` adds a bucket for
        // docs matching NONE of the filters. Was silently dropped.
        let docs = vec![
            json!({ "s": "a" }),
            json!({ "s": "a" }),
            json!({ "s": "b" }),
            json!({ "s": "c" }),
            json!({ "s": "d" }),
        ];
        // Named (keyed) filters + default other key `_other_`.
        let r = run_aggs(
            &json!({ "f": { "filters": {
                "filters": { "aa": {"term": {"s": "a"}}, "bb": {"term": {"s": "b"}} },
                "other_bucket": true
            }}}),
            &docs,
        );
        assert_eq!(r["f"]["buckets"]["aa"]["doc_count"].as_u64(), Some(2));
        assert_eq!(r["f"]["buckets"]["bb"]["doc_count"].as_u64(), Some(1));
        assert_eq!(
            r["f"]["buckets"]["_other_"]["doc_count"].as_u64(),
            Some(2),
            "c,d match no filter: {r}"
        );

        // Custom other_bucket_key (implies other_bucket).
        let rk = run_aggs(
            &json!({ "f": { "filters": {
                "filters": { "aa": {"term": {"s": "a"}} },
                "other_bucket_key": "rest"
            }}}),
            &docs,
        );
        assert_eq!(rk["f"]["buckets"]["rest"]["doc_count"].as_u64(), Some(3));

        // Anonymous array filters -> the other bucket is appended, keyed.
        let ra = run_aggs(
            &json!({ "f": { "filters": {
                "filters": [ {"term": {"s": "a"}} ],
                "other_bucket": true
            }}}),
            &docs,
        );
        let arr = ra["f"]["buckets"].as_array().expect("array buckets");
        let other = arr.last().expect("other bucket");
        assert_eq!(other["key"], json!("_other_"));
        assert_eq!(other["doc_count"].as_u64(), Some(3));
    }

    #[test]
    fn missing_agg_nested_leaf_absent_under_present_parent_object() {
        // A nested leaf `a.b` that is absent must count as MISSING even when
        // the parent object `a` exists; but a leaf that IS present — including
        // one inside an ARRAY of objects (`a=[{b:1}]`) — must count present,
        // exactly like `exists`. #847. `missing` resolves through the same
        // `get_field_value` the exists query uses (array-descends).
        let docs = vec![
            json!({ "a": { "b": 5 } }),    // present
            json!({ "a": [{ "b": 1 }] }),  // present via array-of-objects descent
            json!({ "a": { "c": 1 } }),    // b absent, parent object -> missing
            json!({ "a": {} }),            // missing
            json!({ "a": { "b": null } }), // null -> missing
            json!({ "x": 1 }),             // parent absent -> missing
        ];
        let r = run_aggs(&json!({ "m": { "missing": { "field": "a.b" } } }), &docs);
        assert_eq!(r["m"]["doc_count"].as_u64(), Some(4), "got {r:?}");

        // The legitimate `.keyword` multi-field fallback still works: a SCALAR
        // parent is a real leaf, so `cat.keyword` resolves to `cat`'s value and
        // counts as present.
        let kw = vec![json!({ "cat": "x" }), json!({ "other": 1 })];
        let rk = run_aggs(
            &json!({ "m": { "missing": { "field": "cat.keyword" } } }),
            &kw,
        );
        assert_eq!(rk["m"]["doc_count"].as_u64(), Some(1), "got {rk:?}");
    }

