        // `{"value": null}`.
        let docs = vec![json!({"n": 4}), json!({"n": 6})];
        let agg = json!({
            "total": { "sum": { "field": "n" } },
            "flagged": { "bucket_script": {
                "buckets_path": { "t": "total" },
                "script": "(params.t > 5 ? 1 : 0) + 100"
            }}
        });
        let result = run_aggs(&agg, &docs);
        assert_eq!(
            result["flagged"]["value"].as_f64(),
            Some(101.0),
