#[cfg(test)]
mod lone_surrogate_tests {
    use super::*;
    use tempfile::TempDir;
    use xerj_common::config::Config;
    use xerj_common::types::Schema;

    fn plain_engine(name: &str) -> (TempDir, Engine) {
        let dir = TempDir::new().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = Engine::new(config).unwrap();
        engine.create_index(name, Schema::empty()).unwrap();
        (dir, engine)
    }

    /// The per-item scan must reject exactly the documents serde_json's own
    /// `Value` parse rejects for surrogate escapes — no more, no less. If it
    /// were stricter it would drop valid documents; if it were laxer the bad
    /// document would still reach the batch `Value` parse and sink its
    /// neighbours, which is the bug. Every case below first passes
    /// `IgnoredAny` (the fast path the scan runs after), so the comparison is
    /// apples-to-apples.
    #[test]
    fn surrogate_scan_matches_serde_value_decision() {
        // Build every `\uXXXX` escape from a runtime backslash (code point 92)
        // so the test source carries no literal escape sequences that a tool
        // or editor might normalise — the bytes under test are exactly these.
        let bs = char::from_u32(92).unwrap();
        let u = |hex: &str| format!("{bs}u{hex}");
        let body = |inner: String| format!(r#"{{"body":"{inner}"}}"#).into_bytes();
        let key = |inner: String| format!(r#"{{"{inner}":"v"}}"#).into_bytes();

        let cases: Vec<Vec<u8>> = vec![
            body("plain ascii".to_string()),
            body(format!("emoji {}{} ok", u("d83d"), u("de00"))), // valid pair
            body(format!("clef {}{}", u("d834"), u("dd1e"))),     // valid astral pair
            body(format!("a{}b", u("d83d"))),                     // lone high (issue #1304)
            body(u("d83d")),                                      // lone high at string end
            body(format!("{} low", u("dc00"))),                   // lone low surrogate
            body(format!("{}{}", u("d83d"), u("0041"))),          // high then a non-low escape
            body(format!("{}text", u("d83d"))),                   // high then plain text
            body(format!("{}{}", u("dc00"), u("d83d"))),          // low before high (both wrong)
            body(format!("escaped {}{}u1234 literal", bs, bs)),   // `\\u1234` is not an escape
            body(format!("{}t {}n {}{} tame", bs, bs, bs, bs)),   // ordinary escapes only
            body(format!("bom {} null {}", u("feff"), u("0000"))), // valid non-surrogate escapes
            key(format!("{}{}", u("d83d"), u("de00"))),           // valid pair in an object key
            key(u("d83d")),                                       // lone surrogate in a key
        ];
        for raw in &cases {
            let readable = String::from_utf8_lossy(raw);
            assert!(
                serde_json::from_slice::<serde::de::IgnoredAny>(raw).is_ok(),
                "precondition: IgnoredAny should accept {readable:?}",
            );
            let scan_rejects = lone_surrogate_escape_reason(raw).is_some();
            let value_rejects = serde_json::from_slice::<serde_json::Value>(raw).is_err();
            assert_eq!(
                scan_rejects, value_rejects,
                "scan and serde_json::Value disagree on {readable:?}",
            );
        }
    }

    /// Issue #1304: a single auto-id document carrying an unpaired UTF-16
    /// surrogate must fail per-item while its 127 well-formed neighbours
    /// index. Before the fix the whole batch failed with a single
    /// `lone leading surrogate in hex escape` and nothing was indexed.
    #[tokio::test]
    async fn one_lone_surrogate_does_not_sink_its_bulk_batch() {
        let name = "issue-1304";
        let (_dir, engine) = plain_engine(name);

        const TOTAL: usize = 128;
        const BAD_POS: usize = 42;
        let mut body = String::new();
        for i in 0..TOTAL {
            // Auto-id: no `_id`, so every doc is grouped into one turbo batch.
            body.push_str(&format!("{{\"index\":{{\"_index\":\"{name}\"}}}}\n"));
            if i == BAD_POS {
                // `"a" + String.fromCharCode(0xd83d) + "b"` -> `"a\ud83db"`.
                body.push_str("{\"body\":\"a\\ud83db\"}\n");
            } else {
                body.push_str(&format!("{{\"body\":\"chunk {i} is well formed\"}}\n"));
            }
        }

        let result = process_bulk(&engine, None, &body).await;

        assert!(
            result.errors,
            "a batch containing one bad document must report errors=true",
        );
        assert_eq!(result.items.len(), TOTAL);

        let failed: Vec<usize> = result
            .items
            .iter()
            .enumerate()
            .filter(|(_, item)| item.status != 201)
            .map(|(i, _)| i)
            .collect();
        assert_eq!(
            failed,
            vec![BAD_POS],
            "exactly the one unpaired-surrogate document must fail, not its neighbours",
        );

        let bad = &result.items[BAD_POS];
        assert_eq!(bad.status, 400, "the bad document is a 400, not a 500");
        assert!(
            bad.error
                .as_deref()
                .unwrap_or_default()
                .contains("surrogate"),
            "the per-item error should name the surrogate: {:?}",
            bad.error,
        );

        // The 127 good documents are actually indexed, not merely acked.
        let index = engine.get_index(name).unwrap();
        index.refresh().await.unwrap();
        assert_eq!(
            index.live_doc_count(),
            (TOTAL - 1) as u64,
            "every well-formed document in the batch must be indexed",
        );
    }

    /// Two bad documents in the same batch each fail on their own; the rest
    /// still index. Guards against an off-by-one in the per-item routing.
    #[tokio::test]
    async fn multiple_bad_surrogates_each_fail_individually() {
        let name = "issue-1304-multi";
        let (_dir, engine) = plain_engine(name);

        const TOTAL: usize = 64;
        let bad_positions = [7usize, 50];
        let mut body = String::new();
        for i in 0..TOTAL {
            body.push_str(&format!("{{\"index\":{{\"_index\":\"{name}\"}}}}\n"));
            if bad_positions.contains(&i) {
                body.push_str("{\"body\":\"\\udc00 trailing\"}\n");
            } else {
                body.push_str(&format!("{{\"body\":\"doc {i}\"}}\n"));
            }
        }

        let result = process_bulk(&engine, None, &body).await;
        assert!(result.errors);
        let failed: Vec<usize> = result
            .items
            .iter()
            .enumerate()
            .filter(|(_, item)| item.status != 201)
            .map(|(i, _)| i)
            .collect();
        assert_eq!(failed, bad_positions.to_vec());

        let index = engine.get_index(name).unwrap();
        index.refresh().await.unwrap();
        assert_eq!(index.live_doc_count(), (TOTAL - bad_positions.len()) as u64);
    }
}

