/// Milliseconds since the Unix epoch (wall clock).
fn now_millis() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as i64
}

/// A XERJ-internal system index (`.xerj_*`: auth, sessions, dashboards,
/// audit, …). ES hides its own system indices from default snapshot/restore;
/// we do the same for ours so `_snapshot`/`_restore` operate on user data.
pub(crate) fn is_system_index(name: &str) -> bool {
    name.starts_with(".xerj_")
}

/// Validate a snapshot repo path and snapshot name before any filesystem op.
///
/// Returns the canonicalized `snap_dir` (creating it is the caller's job) or
/// an error. This is the chokepoint for the snapshot path-traversal surface:
///   - the snapshot `name` must not contain `..`, `/`, `\`, or NUL, so
///     `Path::new(repo).join(name)` cannot escape the repo;
///   - the canonicalized `snap_dir` must remain inside the canonicalized
///     `repo_path`, so a `repo_path` like `/tmp/repo/../..` is rejected;
///   - the `repo_path` itself must not be empty (defensive).
///
/// Pre-fix, `PUT /_snapshot/evil` with `location: "/etc"` plus a snapshot
/// `name = ".."` made `snap_dir = "/etc/.."`, so `create_dir_all` and
/// `manifest.json` landed in the parent of `/etc`. The snapshot name was
/// otherwise unvalidated.
fn validate_snapshot_path(
    repo_path: &str,
    name: &str,
    snap_dir: &std::path::Path,
    data_dir: &std::path::Path,
    allowlist: &[String],
    hub_packs: Option<&std::path::Path>,
) -> Result<std::path::PathBuf> {
    if repo_path.is_empty() {
        return Err(EngineError::Common(
            xerj_common::XerjError::invalid_mapping(
                "snapshot repository location must not be empty",
            ),
        ));
    }
    // F-PATH-02: the repo `location` is operator/attacker-supplied via
    // `PUT /_snapshot/{repo}`. The name-containment checks below only prove the
    // snapshot stays inside THAT location — they say nothing about whether the
    // location itself is sane. Bound the location to `data_dir` (default) or a
    // configured allowlist (an ES `path.repo` equivalent), so a repo cannot point
    // at `/etc`, `/root/.ssh`, another tenant's dir, etc.
    // F-PATH-02 (residual): a location whose fully-resolved target does not yet
    // exist makes `canonicalize()` below fail, so the lexical fallback keeps any
    // `..` components. A component-based `starts_with` then treats
    // `<data_dir>/../../escape` as *inside* `<data_dir>` (it never normalizes
    // `..`), and `create_dir_all` lets the OS walk out. Reject `..` outright —
    // no legitimate snapshot root needs parent-dir traversal — so neither the
    // location containment check nor the snapshot-name check can be bypassed
    // with an unresolved parent reference.
    if std::path::Path::new(repo_path)
        .components()
        .any(|c| matches!(c, std::path::Component::ParentDir))
    {
        return Err(EngineError::Common(
            xerj_common::XerjError::invalid_mapping(format!(
                "snapshot repository location [{repo_path}] must not contain '..' path components"
            )),
        ));
    }
    let base_canon = |p: &std::path::Path| p.canonicalize().unwrap_or_else(|_| p.to_path_buf());
    let repo_base = base_canon(std::path::Path::new(repo_path));
    let mut allowed_bases: Vec<std::path::PathBuf> = vec![base_canon(data_dir)];
    allowed_bases.extend(
        allowlist
            .iter()
            .map(|b| base_canon(std::path::Path::new(b))),
    );
    // The hub pack cache (restore only — create passes `None`). Unlike an
    // operator's allowlist entry it is implicit, so it is trusted only in the
    // shape `xerj hub pull` makes it; see `trusted_hub_pack_root`.
    allowed_bases.extend(hub_packs.and_then(trusted_hub_pack_root));
    if !allowed_bases.iter().any(|base| repo_base.starts_with(base)) {
        return Err(EngineError::Common(
            xerj_common::XerjError::invalid_mapping(format!(
                "snapshot repository location [{repo_path}] is outside data_dir and not in \
                 limits.snapshot_repo_allowlist; refusing (set the allowlist to permit external \
                 snapshot roots)"
            )),
        ));
    }
    if name.is_empty()
        || name.contains("..")
        || name.contains('/')
        || name.contains('\\')
        || name.contains('\0')
    {
        return Err(EngineError::Common(xerj_common::XerjError::invalid_mapping(
            format!("invalid snapshot name [{name}]: must not be empty or contain '..', '/', '\\', or NUL"),
        )));
    }
    // Canonicalize repo_path. The repo may not yet exist (create_snapshot
    // creates it on the next line), so fall back to the lexically-cleaned
    // path. `Path::canonicalize` requires the path to exist.
    let repo_canon = std::path::Path::new(repo_path)
        .canonicalize()
        .unwrap_or_else(|_| std::path::PathBuf::from(repo_path));
    // If snap_dir already exists, canonicalize it and verify containment;
    // if it does not yet exist (the create_snapshot case), verify lexically
    // that it starts with the repo.
    if let Ok(snap_canon) = snap_dir.canonicalize() {
        if !snap_canon.starts_with(&repo_canon) {
            return Err(EngineError::Common(
                xerj_common::XerjError::invalid_mapping(format!(
                    "snapshot [{name}] resolves outside its repository; refusing"
                )),
            ));
        }
        Ok(snap_canon)
    } else {
        // Not yet on disk: lexical containment check. This catches `..` in
        // repo_path that canonicalize couldn't resolve because the parent
        // exists but the repo dir does not.
        let snap_lex = snap_dir.to_path_buf();
        if !snap_lex.starts_with(&repo_canon) {
            return Err(EngineError::Common(
                xerj_common::XerjError::invalid_mapping(format!(
                    "snapshot [{name}] resolves outside its repository; refusing"
                )),
            ));
        }
        Ok(snap_lex)
    }
}

/// The canonical hub pack-cache root a restore may read from, or `None` when
/// `packs` is not safe to trust implicitly.
///
/// `limits.snapshot_repo_allowlist` entries are canonicalized as given: an
/// operator who allowlists a symlink means its target. The hub root is NOT an
/// operator's choice — it is derived from the environment — so it is held to
/// the shape `xerj hub pull` creates (`create_dir_all`, by the same user):
///
///   - it exists and is a real directory, not a symlink (`symlink_metadata`),
///     so `~/.xerj/hub/packs -> /` cannot widen the grant to the whole disk;
///   - canonicalizing it changes nothing but its parent's resolution (its own
///     last component is not a link);
///   - it is not a filesystem root;
///   - on Unix it is owned by the server's effective user, so a shared or
///     pre-created directory (a `HOME` under a world-writable dir) is not
///     honoured.
///
/// What is inside it is still checked per request: the caller canonicalizes the
/// repo location, so `packs/x -> /etc` resolves outside this root and is
/// refused, and `..` components are rejected before this is consulted.
fn trusted_hub_pack_root(packs: &std::path::Path) -> Option<std::path::PathBuf> {
    if !packs.is_absolute() {
        return None;
    }
    let meta = std::fs::symlink_metadata(packs).ok()?;
    if meta.file_type().is_symlink() || !meta.is_dir() {
        return None;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        // SAFETY: geteuid has no preconditions and cannot fail.
        if meta.uid() != unsafe { libc::geteuid() } {
            return None;
        }
    }
    let canon = packs.canonicalize().ok()?;
    let parent = packs.parent()?.canonicalize().ok()?;
    if canon != parent.join(packs.file_name()?) || canon.parent().is_none() {
        return None;
    }
    Some(canon)
}

/// Recursively copy all files from `src` to `dst`, recording relative paths in `files`.
fn copy_dir_recursive(
    src: &std::path::Path,
    dst: &std::path::Path,
    files: &mut Vec<String>,
) -> std::io::Result<()> {
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let src_path = entry.path();
        let file_name = entry.file_name();
        let dst_path = dst.join(&file_name);

        if src_path.is_dir() {
            std::fs::create_dir_all(&dst_path)?;
            copy_dir_recursive(&src_path, &dst_path, files)?;
        } else {
            std::fs::copy(&src_path, &dst_path)?;
            files.push(file_name.to_string_lossy().to_string());
        }
    }
    Ok(())
}

/// Simple glob pattern matching (supports `*` and `?`).
pub(crate) fn glob_match(pattern: &str, text: &str) -> bool {
    let pat: Vec<char> = pattern.chars().collect();
    let txt: Vec<char> = text.chars().collect();
    let (m, n) = (pat.len(), txt.len());
    let mut dp = vec![vec![false; n + 1]; m + 1];
    dp[0][0] = true;
    for i in 1..=m {
        if pat[i - 1] == '*' {
            dp[i][0] = dp[i - 1][0];
        }
    }
    for i in 1..=m {
        for j in 1..=n {
            if pat[i - 1] == '*' {
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if pat[i - 1] == '?' || pat[i - 1] == txt[j - 1] {
                dp[i][j] = dp[i - 1][j - 1];
            }
        }
    }
    dp[m][n]
}

/// `index.default_pipeline` in any of the three spellings settings arrive in.
fn pipeline_setting(v: &Value) -> Option<String> {
    v.get("index")
        .and_then(|ix| ix.get("default_pipeline"))
        .or_else(|| v.get("index.default_pipeline"))
        .or_else(|| v.get("default_pipeline"))
        .and_then(Value::as_str)
        .filter(|s| !s.is_empty())
        .map(str::to_string)
}

fn value_is_empty_object(v: &Value) -> bool {
    v.is_null() || v.as_object().is_some_and(|m| m.is_empty())
}

/// Template mappings fill fields the request did not declare. A request
/// property replaces the template's property of the same name. Other mapping
/// keys (`dynamic`, `_source`, …) follow the same rule.
fn merge_template_mappings(template: &Value, request: Value) -> Value {
    let Some(template_obj) = template.as_object().filter(|m| !m.is_empty()) else {
        return request;
    };
    let Some(request_obj) = request.as_object().filter(|m| !m.is_empty()) else {
        return template.clone();
    };
    let mut out = template_obj.clone();
    for (key, value) in request_obj {
        if key == "properties" {
            let mut props = out
                .get("properties")
                .and_then(Value::as_object)
                .cloned()
                .unwrap_or_default();
            if let Some(req_props) = value.as_object() {
                for (field, def) in req_props {
                    props.insert(field.clone(), def.clone());
                }
                out.insert("properties".to_string(), Value::Object(props));
            } else {
                out.insert(key.clone(), value.clone());
            }
        } else {
            out.insert(key.clone(), value.clone());
        }
    }
    Value::Object(out)
}

/// Deep-merge `over` onto `base`. Objects combine; `over` wins on a leaf.
fn deep_merge_request_wins(base: &Value, over: &Value) -> Value {
    match (base.as_object(), over.as_object()) {
        (Some(base), Some(over)) => {
            let mut out = base.clone();
            for (k, v) in over {
                match out.get(k) {
                    Some(existing) if existing.is_object() && v.is_object() => {
                        out.insert(k.clone(), deep_merge_request_wins(existing, v));
                    }
                    _ => {
                        out.insert(k.clone(), v.clone());
                    }
                }
            }
            Value::Object(out)
        }
        _ => over.clone(),
    }
}

/// Write `pipeline` in both spellings `default_pipeline_for` and
/// `GET /_settings` read. Nested `index.default_pipeline` is what the settings
/// response shows once an `index` object exists; a sibling dotted key is
/// dropped by that response, which is how a template pipeline disappeared
/// beside `xerj autoindex`'s `index.xerj_ingest_shards` (#2281).
fn write_default_pipeline(settings: &mut Value, pipeline: &str) {
    if !settings.is_object() {
        *settings = serde_json::json!({});
    }
    let Some(obj) = settings.as_object_mut() else {
        return;
    };
    obj.insert(
        "index.default_pipeline".to_string(),
        Value::String(pipeline.to_string()),
    );
    let index = obj
        .entry("index".to_string())
        .or_insert_with(|| serde_json::json!({}));
    if let Some(index_obj) = index.as_object_mut() {
        index_obj.insert(
            "default_pipeline".to_string(),
            Value::String(pipeline.to_string()),
        );
    }
}

/// Copy single-segment `index.<key>` entries into the nested `index` object
/// when that object does not already name them. Keys with a further dot
/// (`index.query.strict_unknown_fields`) stay as dotted keys: that is a
/// spelling the reader looks up literally, and folding it would hide it.
fn hoist_single_segment_index_keys(mut settings: Value) -> Value {
    let dotted: Vec<(String, Value)> = {
        let Some(obj) = settings.as_object() else {
            return settings;
        };
        obj.iter()
            .filter_map(|(k, v)| {
                let rest = k.strip_prefix("index.")?;
                if rest.is_empty() || rest.contains('.') {
                    return None;
                }
                Some((rest.to_string(), v.clone()))
            })
            .collect()
    };
    if dotted.is_empty() {
        return settings;
    }
    let Some(obj) = settings.as_object_mut() else {
        return settings;
    };
    let index = obj
        .entry("index".to_string())
        .or_insert_with(|| serde_json::json!({}));
    if let Some(index_obj) = index.as_object_mut() {
        for (k, v) in dotted {
            index_obj.entry(k).or_insert(v);
        }
    }
    settings
}

fn merge_template_settings(template: &Value, request: Value) -> Value {
    let request_pipeline = pipeline_setting(&request);
    let template_pipeline = pipeline_setting(template);
    let Some(template_obj) = template.as_object().filter(|m| !m.is_empty()) else {
        return request;
    };
    let mut merged = if value_is_empty_object(&request) {
        Value::Object(template_obj.clone())
    } else {
        deep_merge_request_wins(&Value::Object(template_obj.clone()), &request)
    };
    // The request's spelling wins over the template's, whichever of the two
    // forms each side used. Filling gaps via deep-merge alone keeps a
    // template nested value when the request only set the dotted key.
    if let Some(pipeline) = request_pipeline.or(template_pipeline) {
        write_default_pipeline(&mut merged, &pipeline);
    }
    hoist_single_segment_index_keys(merged)
}

/// One template property, in the same native shape `es_properties_to_fields`
/// builds for an explicit mapping. `semantic_text` is text plus an embedding
/// contract — not `object` (#2281).
fn field_from_template_property(name: &str, field_def: &Value) -> xerj_common::types::FieldConfig {
    use xerj_common::types::{EmbeddingConfig, FieldConfig, FieldType};
    let es_type = field_def
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or("object");
    let native_type = es_type_to_field_type(es_type);
    let mut fc = FieldConfig::new(name.to_string(), native_type);
    // #790: a template's `date_nanos` keeps nanosecond precision;
    // `FieldConfig::new` already made a plain `date` millisecond-scaled.
    if native_type == FieldType::Date && es_type == "date_nanos" {
        fc.options.date_precision = Some(xerj_common::types::DatePrecision::Nanos);
    }
    if es_type == "semantic_text" {
        // Same default as `es_properties_to_fields`: analyzed text has no
        // doc values unless the mapping asks. An explicit `true` is kept.
        fc.options.doc_values = field_def
            .get("doc_values")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let dims = field_def
            .get("dimensions")
            .or_else(|| field_def.get("dims"))
            .and_then(Value::as_u64)
            .map(|d| d as usize)
            .unwrap_or(xerj_ai::local::DEFAULT_DIMS);
        fc.options.dimensions = Some(dims);
        fc.options.similarity = Some(
            field_def
                .get("similarity")
                .and_then(Value::as_str)
                .unwrap_or("cosine")
                .to_string(),
        );
        let target_field = field_def
            .get("target_field")
            .and_then(Value::as_str)
            .map(str::to_string)
            .unwrap_or_else(|| format!("{name}_vector"));
        fc.embedding = Some(EmbeddingConfig {
            endpoint: field_def
                .get("inference_endpoint")
                .and_then(Value::as_str)
                .map(str::to_string),
            model: field_def
                .get("inference_id")
                .or_else(|| field_def.get("model_id"))
                .and_then(Value::as_str)
                .map(str::to_string),
            target_field: Some(target_field),
        });
    }
    fc
}

fn json_properties_have_semantic_text(props: &Value) -> bool {
    let Some(obj) = props.as_object() else {
        return false;
    };
    obj.values().any(|spec| {
        spec.get("type").and_then(Value::as_str) == Some("semantic_text")
            || spec
                .get("properties")
                .is_some_and(json_properties_have_semantic_text)
    })
}

/// Convert an ES field type string to a native FieldType.
fn es_type_to_field_type(es_type: &str) -> xerj_common::types::FieldType {
    use xerj_common::types::FieldType;
    match es_type {
        // `semantic_text` carries the source text. The embedding lives on the
        // companion vector. Falling through to `Object` is what made a
        // template field report `type: object` (#2281).
        "text" | "semantic_text" => FieldType::Text,
        "keyword" | "constant_keyword" | "wildcard" => FieldType::Keyword,
        "long" | "integer" | "short" | "byte" | "unsigned_long" => FieldType::Long,
        "double" | "float" | "half_float" | "scaled_float" => FieldType::Double,
        "boolean" => FieldType::Boolean,
        "date" | "date_nanos" => FieldType::Date,
        "ip" => FieldType::Ip,
        "dense_vector" => FieldType::Vector,
        "geo_point" => FieldType::GeoPoint,
        "binary" => FieldType::Binary,
        "nested" => FieldType::Nested,
        _ => FieldType::Object,
    }
}

#[cfg(test)]
mod snapshot_path_security_tests {
    use super::validate_snapshot_path;

    #[test]
    fn f_path_02_repo_location_outside_data_dir_is_rejected_by_default() {
        let data = tempfile::TempDir::new().unwrap();
        // A repo location pointing outside data_dir (the F-PATH-02 exploit shape)
        // with an empty allowlist must be refused.
        let outside = tempfile::TempDir::new().unwrap();
        let repo = outside.path().to_str().unwrap();
        let snap = std::path::Path::new(repo).join("s1");
        let err = validate_snapshot_path(repo, "s1", &snap, data.path(), &[], None)
            .expect_err("external repo location must be rejected");
        assert!(err.to_string().contains("outside data_dir"), "{err}");
    }

    #[test]
    fn location_inside_data_dir_is_allowed() {
        let data = tempfile::TempDir::new().unwrap();
        let repo_dir = data.path().join("backups");
        std::fs::create_dir_all(&repo_dir).unwrap();
        let repo = repo_dir.to_str().unwrap();
        let snap = repo_dir.join("s1");
        validate_snapshot_path(repo, "s1", &snap, data.path(), &[], None)
            .expect("a repo under data_dir must be allowed");
    }

    #[test]
    fn explicit_allowlist_permits_an_external_root() {
        let data = tempfile::TempDir::new().unwrap();
        let ext = tempfile::TempDir::new().unwrap();
        let repo = ext.path().to_str().unwrap().to_string();
        let snap = std::path::Path::new(&repo).join("s1");
        validate_snapshot_path(
            &repo,
            "s1",
            &snap,
            data.path(),
            std::slice::from_ref(&repo),
            None,
        )
        .expect("an allowlisted external root must be permitted");
    }

    #[test]
    fn traversal_name_still_rejected_even_inside_an_allowed_base() {
        let data = tempfile::TempDir::new().unwrap();
        let snap = data.path().join("..");
        let repo = data.path().to_str().unwrap();
        assert!(validate_snapshot_path(repo, "..", &snap, data.path(), &[], None).is_err());
    }

    #[test]
    fn f_path_02_residual_parent_ref_to_nonexistent_target_is_rejected() {
        // The residual escape (#73): a location containing `..` whose fully
        // resolved target does NOT yet exist. canonicalize() fails, the lexical
        // fallback keeps the `..`, and a component-based starts_with(data_dir)
        // would pass — letting create_dir_all write outside data_dir. It must be
        // refused before any directory is created.
        let data = tempfile::TempDir::new().unwrap();
        let repo = format!("{}/../../xerj-escape", data.path().display());
        let snap = std::path::Path::new(&repo).join("s1");
        let err = validate_snapshot_path(&repo, "s1", &snap, data.path(), &[], None)
            .expect_err("a location containing `..` must be rejected");
        assert!(err.to_string().contains(".."), "unexpected error: {err}");
        // And it stays rejected even if the operator allowlists a broad root:
        // the `..` guard runs before containment, so a parent-ref cannot be
        // laundered through the allowlist either.
        let err2 =
            validate_snapshot_path(&repo, "s1", &snap, data.path(), &["/".to_string()], None)
                .expect_err("`..` must be rejected even with a permissive allowlist");
        assert!(err2.to_string().contains(".."), "unexpected error: {err2}");
    }
}

#[cfg(test)]
mod hub_pack_restore_root_tests {
    //! `limits.hub_pack_restore`: the Corpus Hub pack cache is a restore-only
    //! snapshot root, trusted only in the shape `xerj hub pull` creates it.
    use super::{trusted_hub_pack_root, validate_snapshot_path};
    use std::path::{Path, PathBuf};

    /// `<tmp>/hub/packs/lz4/0774d055/snapshot/<snap>` as `xerj hub pull`
    /// extracts it, plus a data_dir elsewhere. Returns (tmp, data, packs, repo).
    fn layout() -> (tempfile::TempDir, PathBuf, PathBuf, PathBuf) {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path().canonicalize().unwrap();
        let data = root.join("data");
        let packs = root.join("hub").join("packs");
        let repo = packs.join("lz4").join("0774d055").join("snapshot");
        std::fs::create_dir_all(&data).unwrap();
        std::fs::create_dir_all(repo.join("snap-1")).unwrap();
        (tmp, data, packs, repo)
    }

    fn check(repo: &Path, data: &Path, hub: Option<&Path>) -> Result<PathBuf, String> {
        let repo_s = repo.to_str().unwrap();
        validate_snapshot_path(repo_s, "snap-1", &repo.join("snap-1"), data, &[], hub)
            .map_err(|e| e.to_string())
    }

    #[test]
    fn a_pulled_pack_is_restorable_from_the_hub_cache_without_an_allowlist() {
        let (_t, data, packs, repo) = layout();
        let snap = check(&repo, &data, Some(&packs)).expect("restore from the pack cache");
        assert!(snap.starts_with(&packs), "{}", snap.display());
    }

    #[test]
    fn without_the_hub_root_the_same_location_is_refused_as_before() {
        // Create passes `None`, and so does `hub_pack_restore = false`: the
        // pack cache is then exactly as foreign as any other path.
        let (_t, data, _packs, repo) = layout();
        let err = check(&repo, &data, None).expect_err("no hub root, no grant");
        assert!(err.contains("snapshot_repo_allowlist"), "{err}");
    }

    #[test]
    fn the_grant_covers_the_pack_cache_only_not_its_parent_or_a_sibling() {
        let (_t, data, packs, _repo) = layout();
        let hub = packs.parent().unwrap();
        // The hub root itself (catalogue, node data, config) is not a restore source.
        std::fs::create_dir_all(hub.join("node").join("snap-1")).unwrap();
        assert!(check(&hub.join("node"), &data, Some(&packs)).is_err());
        // A sibling sharing the name as a string prefix is not inside it.
        let sibling = hub.join("packs-evil");
        std::fs::create_dir_all(sibling.join("snap-1")).unwrap();
        assert!(check(&sibling, &data, Some(&packs)).is_err());
        // Nor is an unrelated absolute path.
        assert!(check(Path::new("/etc"), &data, Some(&packs)).is_err());
    }

    #[test]
    fn traversal_out_of_the_pack_cache_is_refused() {
        let (_t, data, packs, _repo) = layout();
        let outside = packs.parent().unwrap().parent().unwrap().join("outside");
        std::fs::create_dir_all(outside.join("snap-1")).unwrap();
        let escape = packs
            .join("lz4")
            .join("..")
            .join("..")
            .join("..")
            .join("outside");
        let err = check(&escape, &data, Some(&packs)).expect_err("`..` refused");
        assert!(err.contains(".."), "{err}");
    }

    #[cfg(unix)]
    #[test]
    fn a_symlink_inside_the_pack_cache_cannot_point_the_restore_elsewhere() {
        let (_t, data, packs, _repo) = layout();
        let outside = packs.parent().unwrap().parent().unwrap().join("outside");
        std::fs::create_dir_all(outside.join("snap-1")).unwrap();
        let link = packs.join("evil");
        std::os::unix::fs::symlink(&outside, &link).unwrap();
        let err = check(&link, &data, Some(&packs)).expect_err("escaping link refused");
        assert!(err.contains("snapshot_repo_allowlist"), "{err}");
    }

    #[cfg(unix)]
    #[test]
    fn a_pack_cache_that_is_itself_a_symlink_is_not_trusted() {
        // `~/.xerj/hub/packs -> /` would otherwise turn the grant into the
        // whole disk; `-> <elsewhere>` would move it somewhere nobody chose.
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path().canonicalize().unwrap();
        let data = root.join("data");
        std::fs::create_dir_all(&data).unwrap();
        let hub = root.join("hub");
        std::fs::create_dir_all(&hub).unwrap();
        let packs = hub.join("packs");
        std::os::unix::fs::symlink("/", &packs).unwrap();
        assert_eq!(trusted_hub_pack_root(&packs), None);
        assert!(check(Path::new("/etc"), &data, Some(&packs)).is_err());

        let real = root.join("elsewhere");
        std::fs::create_dir_all(real.join("snap-1")).unwrap();
        std::fs::remove_file(&packs).unwrap();
        std::os::unix::fs::symlink(&real, &packs).unwrap();
        assert_eq!(trusted_hub_pack_root(&packs), None);
        assert!(check(&packs, &data, Some(&packs)).is_err());
        assert!(check(&real, &data, Some(&packs)).is_err());
    }

    #[test]
    fn a_missing_relative_or_non_directory_pack_cache_is_not_trusted() {
        let tmp = tempfile::TempDir::new().unwrap();
        let root = tmp.path().canonicalize().unwrap();
        assert_eq!(trusted_hub_pack_root(&root.join("absent")), None);
        assert_eq!(trusted_hub_pack_root(Path::new("relative/packs")), None);
        let file = root.join("packs");
        std::fs::write(&file, b"not a dir").unwrap();
        assert_eq!(trusted_hub_pack_root(&file), None);
        std::fs::remove_file(&file).unwrap();
        std::fs::create_dir_all(&file).unwrap();
        assert_eq!(trusted_hub_pack_root(&file), Some(file.clone()));
    }

    #[cfg(unix)]
    #[test]
    fn the_filesystem_root_is_never_a_pack_cache() {
        assert_eq!(trusted_hub_pack_root(Path::new("/")), None);
    }
}

#[cfg(test)]
mod ism_policy_persistence_validation_tests {
    use crate::lifecycle::{LifecyclePolicy, LifecycleState};
    use crate::Engine;
    use xerj_common::config::Config;

    fn valid_policy() -> LifecyclePolicy {
        LifecyclePolicy {
            description: None,
            default_state: "only".to_string(),
            states: vec![LifecycleState {
                name: "only".to_string(),
                actions: vec![],
                transitions: vec![],
            }],
        }
    }

    /// `load_persisted_ism_policies` is the one path into `ism_policies`
    /// that doesn't go through the REST layer's `validate()` call (native
    /// PUT and the ILM-translation path both validate before ever storing
    /// a policy) — it just reads back whatever was written to disk. A
    /// hand-edited or otherwise corrupted single entry must not silently
    /// load: `change_ism_policy` only checks "does this policy_id exist",
    /// so an unvalidated entry here would be reachable through it without
    /// ever having passed the same structural checks a direct PUT enforces.
    #[tokio::test]
    async fn corrupt_single_entry_is_skipped_valid_entries_still_restored() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();

        // "broken" transitions to a state that doesn't exist — exactly what
        // `LifecyclePolicy::validate()` rejects, but nothing stops it being
        // written to disk directly (bypassing the REST layer entirely).
        let mut policies = std::collections::HashMap::new();
        policies.insert("good-policy".to_string(), valid_policy());
        policies.insert(
            "broken-policy".to_string(),
            LifecyclePolicy {
                description: None,
                default_state: "start".to_string(),
                states: vec![LifecycleState {
                    name: "start".to_string(),
                    actions: vec![],
                    transitions: vec![crate::lifecycle::LifecycleTransition {
                        state_name: "does-not-exist".to_string(),
                        conditions: None,
                    }],
                }],
            },
        );
        std::fs::write(
            dir.path().join("ism_policies.json"),
            serde_json::to_vec(&policies).unwrap(),
        )
        .unwrap();

        let engine = Engine::new(config).unwrap();
        assert!(
            engine.ism_policies.contains_key("good-policy"),
            "a structurally valid persisted policy must still load"
        );
        assert!(
            !engine.ism_policies.contains_key("broken-policy"),
            "a policy that would fail validate() must not be silently restored"
        );
    }
}

#[cfg(test)]
mod api_key_record_migration_tests {
    use super::ApiKeyRecord;

    /// A record as it comes off disk, before the load path touches it.
    fn loaded(secret_hash: &str, plaintext: Option<&str>) -> ApiKeyRecord {
        ApiKeyRecord {
            name: "loaded".to_string(),
            secret_hash: secret_hash.to_string(),
            legacy_plaintext_secret: plaintext.map(str::to_string),
            creation_ms: 1_753_600_000_000,
            expiration_ms: None,
            invalidated: false,
            invalidation_ms: None,
            roles: Vec::new(),
        }
    }

    /// The discriminator is `is_usable_hash`, not `is_empty` and not a check
    /// of the `$ssha256$` tag: a `secret_hash` that does not decode can never
    /// verify against anything, so a record carrying only that is as unusable
    /// as one carrying nothing and must be dropped, not restored as a live
    /// key. Three of these carry the tag — a prefix test would call them
    /// migrated and keep them.
    #[test]
    fn an_unparseable_hash_with_no_plaintext_is_dropped() {
        for stored in [
            "",
            "$ssha256$",
            "$ssha256$truncated",
            "$ssha256$deadbeef$cafe",
            "$argon2id$v=19$m=1,t=1,p=1$c2FsdA$aGFzaA",
            "left-over-plaintext",
        ] {
            for plaintext in [None, Some("")] {
                let mut rec = loaded(stored, plaintext);
                assert_eq!(
                    rec.migrate_from_plaintext(),
                    Err(()),
                    "{stored:?} + {plaintext:?} must be dropped, not restored"
                );
            }
        }
    }

    /// A plaintext beside a hash-shaped value that does not decode is a store
    /// nobody can explain — not the pre-#201 shape (that has no `secret_hash`
    /// at all), and not a migrated one. Deriving a live credential from the
    /// half of it #201 exists to delete is the fail-open reading, so the
    /// record is dropped instead.
    #[test]
    fn a_plaintext_beside_an_unparseable_hash_is_dropped_not_repaired() {
        for stored in [
            "$ssha256$truncated",
            "$argon2id$v=19$m=1,t=1,p=1$c2FsdA$aGFzaA",
            "left-over-plaintext",
        ] {
            let mut rec = loaded(stored, Some("the-plaintext"));
            assert_eq!(
                rec.migrate_from_plaintext(),
                Err(()),
                "{stored:?} + a plaintext is ambiguous and must be dropped"
            );
        }
    }

    /// A usable hash still wins over a leftover plaintext, and the plaintext is
    /// discarded — re-deriving there could silently swap which secret the
    /// record authenticates.
    #[test]
    fn a_usable_hash_wins_over_a_leftover_plaintext() {
        let hash = crate::secret_hash::hash_secret("hashed-secret");
        let mut rec = loaded(&hash, Some("stale-plaintext"));
        assert_eq!(rec.migrate_from_plaintext(), Ok(true));
        assert_eq!(rec.secret_hash, hash);
        assert!(rec.legacy_plaintext_secret.is_none());
        assert!(rec.verify_secret("hashed-secret"));
        assert!(!rec.verify_secret("stale-plaintext"));
    }

    /// An already-migrated record is left alone and reports no rewrite.
    #[test]
    fn an_already_hashed_record_is_untouched() {
        let hash = crate::secret_hash::hash_secret("s");
        let mut rec = loaded(&hash, None);
        assert_eq!(rec.migrate_from_plaintext(), Ok(false));
        assert_eq!(rec.secret_hash, hash);
    }

    /// The pre-#201 shape: plaintext only.
    #[test]
    fn a_pre_201_plaintext_record_is_hashed() {
        let mut rec = loaded("", Some("legacy-secret"));
        assert_eq!(rec.migrate_from_plaintext(), Ok(true));
        assert!(crate::secret_hash::is_usable_hash(&rec.secret_hash));
        assert!(rec.verify_secret("legacy-secret"));
    }

    /// Even if one reached the auth path unmigrated, an unusable hash denies.
    #[test]
    fn verify_secret_denies_an_unusable_hash() {
        for stored in ["", "$ssha256$truncated", "plaintext-secret"] {
            let rec = loaded(stored, None);
            assert!(
                !rec.verify_secret(stored),
                "{stored:?} must not verify against itself"
            );
            assert!(!rec.verify_secret("anything"));
        }
    }

    #[tokio::test]
    async fn has_open_index_tracks_created_and_deleted_indices() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        assert!(!engine.has_open_index("alpha"));
        engine.get_or_create_index("alpha").unwrap();
        assert!(engine.has_open_index("alpha"));
        engine.delete_index("alpha").await.unwrap();
        assert!(!engine.has_open_index("alpha"));
    }
}

#[cfg(test)]
mod governor_thread_spawn_tests {
    use super::spawn_governor_thread_using;
    use xerj_common::thread_spawn::{BoxedJob, Spawn};

    /// A spawner that always fails the way `pthread_create` does at a
    /// thread or memory limit.
    struct AlwaysEagain;

    impl Spawn for AlwaysEagain {
        fn spawn(
            &self,
            _name: &str,
            _job: BoxedJob,
        ) -> std::io::Result<xerj_common::thread_spawn::SpawnedThread> {
            Err(std::io::Error::from_raw_os_error(libc::EAGAIN))
        }
    }

    #[test]
    fn a_governor_thread_that_cannot_spawn_reports_false_instead_of_aborting() {
        let ran = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let job_ran = std::sync::Arc::clone(&ran);
        let started = spawn_governor_thread_using(
            &AlwaysEagain,
            || true,
            "xerj-test",
            move || {
                job_ran.store(true, std::sync::atomic::Ordering::SeqCst);
            },
        );
        assert!(!started);
        assert!(!ran.load(std::sync::atomic::Ordering::SeqCst));
    }

    #[test]
    fn a_closed_spawn_gate_is_respected() {
        // A working spawner, but the gate is closed. Production passes an
        // always-open gate for these threads (see `spawn_governor_thread`);
        // this pins the plumbing for a caller that does gate.
        let started = spawn_governor_thread_using(
            &xerj_common::thread_spawn::StdSpawn,
            || false,
            "xerj-test",
            || {},
        );
        assert!(!started);
    }
}

#[cfg(test)]
mod index_template_merge_tests {
    //! #2281: a template's `semantic_text` and `index.default_pipeline` have
    //! to survive the merge with the body `xerj autoindex` actually sends.
    use super::{field_from_template_property, merge_template_mappings, merge_template_settings};
    use serde_json::json;

    #[test]
    fn dotted_template_pipeline_survives_an_autoindex_settings_body() {
        let template = json!({ "index.default_pipeline": "jsqlite-copy" });
        let request = json!({
            "index": { "xerj_ingest_shards": 1 },
            "index.query.strict_unknown_fields": true,
            "analysis": { "analyzer": { "default": { "type": "code" } } }
        });
        let merged = merge_template_settings(&template, request);
        assert_eq!(
            merged.pointer("/index/default_pipeline"),
            Some(&json!("jsqlite-copy")),
            "{merged}"
        );
        assert_eq!(
            merged.get("index.default_pipeline"),
            Some(&json!("jsqlite-copy")),
            "{merged}"
        );
        assert_eq!(
            merged.pointer("/index/xerj_ingest_shards"),
            Some(&json!(1)),
            "{merged}"
        );
        assert_eq!(
            merged.get("index.query.strict_unknown_fields"),
            Some(&json!(true)),
            "{merged}"
        );
        assert!(
            merged
                .pointer("/index/query.strict_unknown_fields")
                .is_none(),
            "a multi-dot key must stay dotted: {merged}"
        );
        assert_eq!(
            merged.pointer("/analysis/analyzer/default/type"),
            Some(&json!("code")),
            "{merged}"
        );
    }

    #[test]
    fn the_request_pipeline_wins_in_either_spelling() {
        let dotted_request = merge_template_settings(
            &json!({ "index": { "default_pipeline": "from-template" } }),
            json!({ "index.default_pipeline": "from-request" }),
        );
        assert_eq!(
            dotted_request.pointer("/index/default_pipeline"),
            Some(&json!("from-request")),
            "{dotted_request}"
        );
        let nested_request = merge_template_settings(
            &json!({ "index.default_pipeline": "from-template" }),
            json!({ "index": { "default_pipeline": "from-request" } }),
        );
        assert_eq!(
            nested_request.pointer("/index/default_pipeline"),
            Some(&json!("from-request")),
            "{nested_request}"
        );
        assert_eq!(
            nested_request.get("index.default_pipeline"),
            Some(&json!("from-request")),
            "{nested_request}"
        );
    }

    #[test]
    fn request_properties_replace_template_properties_of_the_same_name() {
        let merged = merge_template_mappings(
            &json!({
                "properties": {
                    "diagnostic_semantic": { "type": "semantic_text" },
                    "diagnostic_template_marker": { "type": "keyword" }
                }
            }),
            json!({
                "properties": {
                    "impl": { "type": "text" },
                    "diagnostic_semantic": { "type": "keyword" }
                }
            }),
        );
        assert_eq!(
            merged.pointer("/properties/diagnostic_semantic/type"),
            Some(&json!("keyword"))
        );
        assert_eq!(
            merged.pointer("/properties/diagnostic_template_marker/type"),
            Some(&json!("keyword"))
        );
        assert_eq!(
            merged.pointer("/properties/impl/type"),
            Some(&json!("text"))
        );
    }

    #[test]
    fn semantic_text_is_text_with_an_embedding_contract() {
        use xerj_common::types::FieldType;
        let semantic = field_from_template_property(
            "diagnostic_semantic",
            &json!({ "type": "semantic_text" }),
        );
        assert_eq!(semantic.field_type, FieldType::Text);
        assert!(!semantic.options.doc_values);
        let embedding = semantic.embedding.expect("embedding");
        assert_eq!(
            embedding.target_field.as_deref(),
            Some("diagnostic_semantic_vector")
        );
        assert_eq!(semantic.options.dimensions, Some(384));

        let keyword = field_from_template_property(
            "diagnostic_template_marker",
            &json!({ "type": "keyword" }),
        );
        assert_eq!(keyword.field_type, FieldType::Keyword);
        assert!(keyword.embedding.is_none());
    }
}

#[cfg(test)]
mod pressure_drain_tests {
    use super::{pressure_drain_due, sample_drain_due, MEMORY_DRAIN_MIN_INTERVAL};
    use crate::governor::MemoryDrainSchedule;
    use std::time::{Duration, Instant};

    /// #2238: the engage edge drains immediately, a still-engaged latch does
    /// not drain again inside the window, and releasing the latch arms the
    /// next engage. The sampler passes the memtable latch; the RSS latch
    /// has its own schedule.
    #[test]
    fn pressure_drain_fires_on_the_engage_edge_and_respects_the_window() {
        let mut last = None;
        let t0 = Instant::now();
        let window = Duration::from_secs(2);
        assert!(pressure_drain_due(true, &mut last, t0, window));
        assert!(
            !pressure_drain_due(true, &mut last, t0 + Duration::from_millis(500), window),
            "one engaged stretch drains once per window"
        );
        assert!(pressure_drain_due(
            true,
            &mut last,
            t0 + Duration::from_secs(2),
            window
        ));
        assert!(!pressure_drain_due(
            false,
            &mut last,
            t0 + Duration::from_secs(3),
            window
        ));
        assert!(last.is_none(), "a released latch clears the timer");
        assert!(
            pressure_drain_due(true, &mut last, t0 + Duration::from_secs(3), window),
            "the next engage drains immediately"
        );
    }

    /// #1981 x #2238: a flat RSS backs off, and that backoff must not hide a
    /// memtable trip. Corpus index hits the summed budget while RSS is
    /// stable; the flush that frees it stays on the 2 s window. A memtable
    /// engage that arrives during an RSS gap drains on that sample, not at
    /// the end of the gap.
    #[test]
    fn memtable_pressure_is_not_stretched_by_the_rss_backoff() {
        let min = MEMORY_DRAIN_MIN_INTERVAL;
        let t0 = Instant::now();
        let stuck = 64 * 1024 * 1024;
        let mut rss_drains = MemoryDrainSchedule::new(min);
        let mut last_memtable = None;

        let mut rss_fires = 0u32;
        let mut t = Duration::ZERO;
        let warmup = Duration::from_secs(60);
        while t < warmup {
            if sample_drain_due(
                t0 + t,
                stuck,
                true,
                false,
                &mut rss_drains,
                &mut last_memtable,
            ) {
                rss_fires += 1;
            }
            t += min;
        }
        assert!(
            rss_fires < 20,
            "a flat RSS must back off across 60s, fired {rss_fires}"
        );
        assert!(
            !sample_drain_due(
                t0 + warmup,
                stuck,
                true,
                false,
                &mut rss_drains,
                &mut last_memtable,
            ),
            "the RSS clock is still inside its backed-off gap"
        );
        assert!(
            sample_drain_due(
                t0 + warmup,
                stuck,
                true,
                true,
                &mut rss_drains,
                &mut last_memtable,
            ),
            "a memtable engage drains immediately during that gap"
        );
        assert!(!sample_drain_due(
            t0 + warmup + Duration::from_millis(500),
            stuck,
            true,
            true,
            &mut rss_drains,
            &mut last_memtable,
        ));
        assert!(sample_drain_due(
            t0 + warmup + min,
            stuck,
            true,
            true,
            &mut rss_drains,
            &mut last_memtable,
        ));

        // Memtable only, RSS stable and disengaged: every 2 s step fires.
        // Folding this latch into the RSS backoff would drop fires well
        // below the step count.
        let mut rss_drains = MemoryDrainSchedule::new(min);
        let mut last_memtable = None;
        let horizon = Duration::from_secs(120);
        let mut mem_fires = 0u32;
        let mut t = Duration::ZERO;
        while t < horizon {
            if sample_drain_due(
                t0 + t,
                stuck,
                false,
                true,
                &mut rss_drains,
                &mut last_memtable,
            ) {
                mem_fires += 1;
            }
            t += min;
        }
        let steps = (horizon.as_secs() / min.as_secs()) as u32;
        assert_eq!(
            mem_fires, steps,
            "memtable pressure keeps the fixed window while RSS does not fall"
        );
    }
}

//! Doc-values (columnar) fast path for `size:0 + match_all + aggs` searches.
//!
//! Root-cause context (2026-07, agg-hang cluster): every agg family that the
//! old M2-G2 fast path didn't serve fell back to `run_aggs_with_all` over a
//! fully materialised JSON corpus — an O(N) stored-section decompress + parse
//! of EVERY live document per request, plus O(N × buckets) per-bucket clone
//! passes inside `run_terms`/`run_composite`, and an O(N²) merge loop in
//! `variable_width_histogram`.  At 1M+ docs that exceeds any network timeout,
//! so the benchmark marked ~27 agg families "collapsed".  The M2-G2 fast path
//! itself had been stubbed to `None` since the M5.1 sharded-memtable refactor
//! (see ARCHITECTURE_V5 §2.4/§6), so *nothing* was served columnar.
//!
//! This module revives the fast path as a real executor over the per-segment
//! `.dv` doc-values sidecars (`Index::dv_columns_for`, cached) plus the live
//! sharded memtable (materialised as a small doc slice — memtables are
//! bounded by the flush threshold).  Coverage: the metric leaves
//! (avg/sum/min/max/stats/value_count), terms (± metric / top_hits sub-aggs),
//! range, date_range, filter, filters, adjacency_matrix, composite,
//! sampler/random_sampler, variable_width_histogram, date_histogram
//! (± metric sub-aggs and the full pipeline-agg family).
//!
//! Correctness contract: the output must be byte-identical to the brute
//! `run_aggs_with_all` path for every shape this module accepts (modulo
//! float-summation rounding order).  Anything not *provably* identical bails
//! with `None` and the caller falls back to the brute path.  Shared shaping
//! helpers (`typed_term_key`, `run_top_hits_with_total`,
//! `apply_bucket_pipeline_ops`, `resolve_sibling_pipelines`,
//! `run_pipeline_agg`, `run_sampler`) are reused from `aggs.rs` so bucket
//! rendering cannot drift.
//!
//! Hard gates (any failure → `None` → brute fallback):
//! * `XERJ_DISABLE_FAST_AGGS=1` env kill switch.
//! * Index must have ≥ `FAST_AGG_MIN_DOCS` docs — small indices are fast on
//!   the brute path anyway, and this keeps the (tiny-corpus) ES-YAML
//!   conformance suite pinned to the reference implementation.
//! * Deletes: either none present, or (since #1260) every non-empty snapshot
//!   segment's ghost-position bitmap is empty — per-segment admission via
//!   `ghost_positions_for`, with the memtable views liveness-gated, the
//!   delete-blind memtable columnar summaries switched off, and the
//!   version-map epoch re-checked before the result is returned.  A MERGED
//!   index (ghosts compacted away) re-qualifies instead of staying disabled
//!   forever on the monotonic `ghost_events` counter.  Since #1267 a segment
//!   with resident ghosts is admitted for ONE provably row-exact plan — a
//!   top-level filter plus a single plain `terms` agg — where every number
//!   comes from the fused row pass (ghosted rows skipped) and the
//!   live-filtered memtable walks, never from a delete-blind O(1) stat;
//!   every other plan still bails on the first dirty bitmap.
//! * Every non-empty segment must have a decodable `.dv` sidecar.
//!
//! Known accepted divergences vs brute (documented, benign for the fast-path
//! trigger conditions): array-valued fields (the `.dv` builder skips arrays)
//! and `_doc_count` rollup weights are not modelled for *segment-resident*
//! docs — memtable docs go through the exact brute extractors.

use super::*;
use crate::aggs::{
    apply_bucket_pipeline_ops, auto_date_offset_ms, auto_date_pick_interval, calendar_bucket_key,
    detect_fractional_digits, doc_count_weight, doc_matches_filter, extract_date_ms_values,
    extract_field_values, extract_numeric, extract_numeric_values, format_histogram_key,
    format_number_pattern, format_range_val, get_nested_field, interval_to_ms,
    is_calendar_interval, java_double_str, matrix_stats_from_rows, next_calendar_bucket,
    parse_date_ms, parse_offset_ms, render_date_format, render_iso_date, resolve_sibling_pipelines,
    run_pipeline_agg, run_sampler, run_top_hits_with_total, typed_term_key,
};
use crate::memtable::MemBoolPred;
use serde_json::{json, Map, Value};
use std::collections::HashMap;
use xerj_storage::doc_values::{Column, KeywordColumn, NumericColumn, PresenceColumn};

/// Compile the top-level agg filter JSON (the restricted shape
/// `query_node_to_agg_filter` emits: `term`/`range`/`bool{must,filter}`) into a
/// pure conjunction of memtable columnar predicates, for the O(matching)
/// filtered-memtable fold (`ShardedFtsMemtable::filtered_docs_arc`).
///
/// Only Term (keyword string) and numeric Range leaves — and a `bool` with just
/// `must`/`filter` clauses of those — are expressible as a `[MemBoolPred]`
/// conjunction.  `terms` (a disjunction), `match_all`, and anything richer yield
/// `None`, so the caller keeps the exact full-memtable walk.  This is the
/// columnar-predicate sibling of `compile_top_pred`; the fast-agg memtable fold
/// always re-applies `doc_matches_filter` on top, so this only needs to be a
/// no-false-negative candidate generator.
fn mem_preds_from_agg_filter(filter: &Value) -> Option<Vec<MemBoolPred>> {
    fn push_leaf(filter: &Value, out: &mut Vec<MemBoolPred>) -> Option<()> {
        let obj = filter.as_object()?;
        if obj.len() != 1 {
            return None;
        }
        let (qtype, body) = obj.iter().next()?;
        match qtype.as_str() {
            "term" => {
                let fm = body.as_object()?;
                if fm.len() != 1 {
                    return None;
                }
                let (field, expected) = fm.iter().next()?;
                let value = match expected {
                    Value::String(s) => {
                        if s.contains('/') {
                            return None; // CIDR — mirror mem_bool_preds
                        }
                        s.clone()
                    }
                    _ => return None,
                };
                out.push(MemBoolPred::Term {
                    field: field.clone(),
                    value,
                });
                Some(())
            }
            "range" => {
                let fm = body.as_object()?;
                if fm.len() != 1 {
                    return None;
                }
                let (field, bounds) = fm.iter().next()?;
                let b = bounds.as_object()?;
                let get = |k: &str| -> Option<Option<f64>> {
                    match b.get(k) {
                        None => Some(None),
                        Some(Value::Number(n)) => Some(n.as_f64()),
                        _ => None, // date-string / non-numeric bound → bail
                    }
                };
                // Reject any present-but-non-numeric bound.
                for k in ["gte", "gt", "lte", "lt"] {
                    if b.contains_key(k) && get(k)?.is_none() {
                        return None;
                    }
                }
                out.push(MemBoolPred::Range {
                    field: field.clone(),
                    gte: get("gte")?,
                    gt: get("gt")?,
                    lte: get("lte")?,
                    lt: get("lt")?,
                });
                Some(())
            }
            "bool" => {
                let bo = body.as_object()?;
                if bo.keys().any(|k| k != "must" && k != "filter") {
                    return None;
                }
                for key in ["must", "filter"] {
                    if let Some(clauses) = bo.get(key) {
                        for c in clauses.as_array()? {
                            push_leaf(c, out)?;
                        }
                    }
                }
                Some(())
            }
            _ => None, // terms / match_all / … → not a pure Term/Range conjunction
        }
    }
    let mut out = Vec::new();
    push_leaf(filter, &mut out)?;
    if out.is_empty() {
        return None;
    }
    Some(out)
}

/// Minimum index size (live docs) before the columnar path activates.
/// Below this the brute JSON path answers in single-digit milliseconds and
/// remains the reference implementation for conformance corpora.
const FAST_AGG_MIN_DOCS: u64 = 10_000;

fn fast_aggs_disabled() -> bool {
    static DISABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *DISABLED.get_or_init(|| {
        std::env::var("XERJ_DISABLE_FAST_AGGS")
            .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
            .unwrap_or(false)
    })
}

/// One on-disk segment's columns + identity.
#[derive(Clone)]
struct SegEntry {
    id: String,
    cols: super::Resident<super::DocValueMap>,
    docs: u32,
    /// [#1267] This segment's ghost-position bitmap, carried only when it
    /// is NON-empty and the admission gate let the segment through anyway
    /// (the row-exact plan — see `try_fast_aggs`).  Bit set ⇔ the row at
    /// that position is deleted or superseded; every row-fold in the
    /// row-exact plan must skip set bits.  `None` = provably ghost-free,
    /// the shape every executor was originally built under.
    ghosts: Option<std::sync::Arc<Vec<u64>>>,
}

/// Bit `row` of a ghost-position bitmap (bit pos set ⇔ row is deleted or
/// superseded).  Out-of-range rows are live: the bitmap is sized for the
/// segment's row space, and a short one simply has no ghosts past its end.
#[inline]
fn ghost_bit(ghosts: &[u64], row: u32) -> bool {
    ghosts
        .get((row >> 6) as usize)
        .is_some_and(|w| (w >> (row & 63)) & 1 != 0)
}

/// Look up a doc-value column for `field`, falling back to the `.keyword`
/// multi-field's parent name when the exact field has no column of its own.
/// A text field's auto-created `.keyword` multi-field shares the *same*
/// physical column, stored under the parent's name — this mirrors the
/// identical `.keyword` fallback the brute-force path applies when walking
/// `_source` directly (`extract_array_path_values` in `aggs.rs`). Without it,
/// every
/// fast-path reference to `<field>.keyword` silently sees no column at all,
/// even though the data is right there under `<field>`.
///
/// EVERY column lookup on the fast path goes through here — both agg
/// *targets* (`SegEntry::col`) and query/filter *predicates*
/// (`resolve_pred`). Keeping one implementation is the point: the two used
/// to resolve names differently, and the predicate side failed CLOSED
/// (missing column ⇒ "this segment matches nothing"), so a filtered panel
/// on `<field>.keyword` returned a small plausible number instead of an
/// error while the unfiltered one next to it was correct.
fn dv_col<'a>(cols: &'a super::DocValueMap, field: &str) -> Option<&'a Column> {
    cols.get(field)
        .or_else(|| field.strip_suffix(".keyword").and_then(|p| cols.get(p)))
}

impl SegEntry {
    /// This segment's doc-value column for `field` — see [`dv_col`].
    fn col(&self, field: &str) -> Option<&Column> {
        dv_col(&self.cols, field)
    }
}

/// True when `field` is a dotted name this segment cannot resolve to a
/// column of its own — not even through [`dv_col`]'s `.keyword` fallback —
/// while some ANCESTOR of it (the name minus one or more trailing
/// `.<segment>`s) does have a column.  That is where the columnar path and
/// the brute reference part company.
///
/// There is more than one brute resolver, and the one a request is actually
/// measured against depends on which part of the request the name appears
/// in.  They do not agree with each other, so this reports the UNION of the
/// names any of them resolves and callers BAIL, letting whichever resolver
/// the request reaches answer it:
///
/// * a top-level query filter (and every other `_source` predicate) is
///   evaluated by `doc_matches_query` → `index.rs::get_field_value`, whose
///   multi-field fallback RECURSES on the parent
///   (`get_field_value(source, &field[..idx])`).  It therefore strips an
///   UNBOUNDED number of trailing segments, provided the name it finally
///   lands on holds a leaf value: `extension.raw.raw`,
///   `extension.keyword.raw` and `extension.raw.raw.raw` all resolve to
///   `extension`'s string.  Measured, not read off the source — see
///   `tests/fast_aggs_multifield_suffix.rs`, whose brute leg returns 3 200
///   for a `term` query on every one of those names.
/// * an aggregation target and a `filters`/`filter` sub-predicate are
///   resolved by `aggs::get_nested_field`, which strips exactly ONE trailing
///   segment, so it resolves `extension.raw` but not `extension.raw.raw`;
/// * `extract_array_path_values` (aggs.rs, just before `get_nested_field`)
///   strips `.keyword` only.
///
/// [`dv_col`] deliberately strips only `.keyword`, so all of these names
/// find no column and the fast path treats the segment as holding no such
/// data: agg targets contribute empty buckets / null metrics and predicates
/// resolve to `SegPred::Never`, i.e. a filtered panel silently reports a
/// small plausible number rather than an error.
///
/// Resolution is deliberately NOT widened to match any one of them (see the
/// module contract: the fast path answers only shapes it can prove
/// byte-identical, and there is no single brute behaviour to be identical
/// TO).  Bailing is correct against all three, because after a bail the
/// request is answered by the very resolver it would have been measured
/// against.
///
/// Ancestors are probed with a plain `cols.get` rather than [`dv_col`]: the
/// loop already visits every prefix, so a `.keyword`-stripping probe would
/// only re-test a prefix the next iteration reaches anyway.
///
/// Ancestors are probed against the doc-value columns, and those exist only
/// for TOP-LEVEL scalar fields: `build_doc_value_columns` (index.rs) iterates
/// only the top-level keys of `_source`, so a scalar leaf nested under an
/// object has no column of its own either.
///
/// The scope, stated honestly because an earlier draft got it wrong: this
/// predicate closes only the MULTI-FIELD-SUFFIX divergence, where the parent
/// that owns a column is a real top-level field (`extension.raw.raw` ->
/// `extension`). It CANNOT see the nested-OBJECT divergence (`geo.city`, which
/// brute resolves by recursing into the object) or the suppressed-array one
/// (`tags`, whose column is dropped for being multi-valued): neither has an
/// ancestor column at any depth, so this returns `false` for both, and a
/// genuinely absent sub-path (`geo.missing`) is indistinguishable from a
/// present one here. Those two are closed instead by the schema-keyed root
/// check in [`field_needs_brute_fallback`] (#128), which is why the predicate
/// path routes its column misses through that function rather than this one.
fn dotted_suffix_diverges_from_brute(cols: &super::DocValueMap, field: &str) -> bool {
    if dv_col(cols, field).is_some() {
        return false;
    }
    let mut rest = field;
    while let Some((ancestor, _)) = rest.rsplit_once('.') {
        if cols.get(ancestor).is_some() {
            return true;
        }
        rest = ancestor;
    }
    false
}

/// True when `field` is a name fast_aggs cannot resolve to a column —
/// neither the exact name nor its `.keyword`-stripped form (see
/// `SegEntry::col`) — in EVERY flushed segment, yet brute's
/// `get_field_value` still resolves it, so answering it columnarly would
/// drop data brute reports. Coverage is judged per segment (#143): the
/// executors `continue` past a column-less segment, so a single segment
/// missing the column already loses that segment's docs even when every
/// other segment carries it. A free function (not a `FastCtx` method) so
/// it's testable without constructing a full `FastCtx`, which needs a real
/// `&Index`.
///
/// Three ways brute out-resolves the columnar path, all bailed here:
///
/// * a multi-field suffix (of any depth) other than `.keyword` that a brute
///   resolver strips and the columnar path does not — see
///   [`dotted_suffix_diverges_from_brute`].  That check is per-segment and
///   runs FIRST, because a name that resolves exactly in one segment but only
///   via an ancestor in another still diverges on the second segment's rows;
/// * a scalar leaf nested under an object (`geo.city`, `machine.os.keyword`):
///   its root (`geo` / `machine`) is a mapped field, but no segment ever
///   carries a column for an object field itself, so brute recurses into the
///   `_source` object while the columnar path has nothing;
/// * a TOP-LEVEL field whose column was SUPPRESSED because it is multi-valued
///   (`tags` / `tags.raw`): `build_doc_value_columns` ships NO column for an
///   array-poisoned field, so brute reads the `_source` array while the
///   columnar path sees no column — indistinguishable at the column level
///   from a genuine absence, hence the schema check below.  Suppression is
///   decided per segment, so the same field can be covered in one segment
///   and suppressed in the next (scalar docs flushed first, array docs
///   later); partial coverage must bail exactly like total absence, which
///   is why the coverage check demands ALL segments, not ANY.
///
/// `mapped_fields` — see `FastCtx::mapped_fields` — is the schema signal that
/// separates those last two (present-but-uncolumned) from a genuine absence:
/// a field whose name AND top-level root are both unmapped was never indexed,
/// and IS a valid empty/null result worth returning on the fast path.
fn field_needs_brute_fallback(
    field: &str,
    segs: &[SegEntry],
    mapped_fields: &std::collections::HashSet<String>,
) -> bool {
    if segs
        .iter()
        .any(|s| dotted_suffix_diverges_from_brute(&s.cols, field))
    {
        return true;
    }
    // Column coverage must be judged PER SEGMENT (#143): array-suppression
    // in `build_doc_value_columns` drops a column for exactly the segments
    // whose docs hold arrays under the field, so one scalar-only segment
    // carrying the column proves nothing about the others — the executors
    // `continue` past a column-less segment, silently dropping its docs.
    // Only full coverage keeps the fast path; the earlier "ANY segment has
    // it" check was the undercount.
    if !segs.is_empty() && segs.iter().all(|s| s.col(field).is_some()) {
        return false;
    }
    // The column is missing from at least one segment. Bail iff brute would
    // still resolve the name — i.e. the exact name (a suppressed top-level
    // array such as `tags`, or a flat dotted field name) or, for a dotted
    // path, its top-level root (`geo` for `geo.city`, `tags` for `tags.raw`)
    // is a field the schema maps: at the column level a per-segment
    // suppression is indistinguishable from the field being absent from that
    // segment's docs, and only the suppressed case has data for brute to
    // find. A name whose root is unmapped is genuinely absent everywhere and
    // stays on the fast path as a real empty result.
    let root = field.split_once('.').map_or(field, |(r, _)| r);
    mapped_fields.contains(field) || mapped_fields.contains(root)
}

/// Memtable docs for the fast path.
///
/// `Owned` is the original brute-parity representation: every buffered doc
/// deep-cloned with `_id` / `_index` / `_seq_no` injected.  It is only
/// needed when the agg tree can actually OBSERVE those meta fields
/// (`top_hits`, or an agg targeting `_id`/`_index`/`_seq_no`).  For every
/// other shape we use `Shared`: Arc clones of the buffered sources — no
/// deep clone, no injection.  Under a bulk writer the memtable holds 10⁴-10⁵
/// docs, and the per-request Owned build (~100-300 ms of `clone_subtree` +
/// version-map lookups) dominated terms/cardinality latency.
enum MemDocs {
    Owned(Vec<Value>),
    Shared {
        ids: Vec<String>,
        srcs: Vec<std::sync::Arc<Value>>,
    },
}

impl MemDocs {
    fn len(&self) -> usize {
        match self {
            MemDocs::Owned(v) => v.len(),
            MemDocs::Shared { srcs, .. } => srcs.len(),
        }
    }
    fn is_empty(&self) -> bool {
        self.len() == 0
    }
    fn iter(&self) -> Box<dyn Iterator<Item = &Value> + '_> {
        match self {
            MemDocs::Owned(v) => Box::new(v.iter()),
            MemDocs::Shared { srcs, .. } => Box::new(srcs.iter().map(|a| a.as_ref())),
        }
    }
    /// Materialise doc `i` brute-corpus-style (meta fields injected).
    fn owned(&self, i: usize, idx: &Index) -> Option<Value> {
        match self {
            MemDocs::Owned(v) => v.get(i).cloned(),
            MemDocs::Shared { ids, srcs } => {
                let mut v: Value = srcs.get(i)?.as_ref().clone();
                let id = ids.get(i)?;
                if let Some(o) = v.as_object_mut() {
                    o.entry("_id".to_string())
                        .or_insert_with(|| Value::String(id.clone()));
                    o.entry("_index".to_string())
                        .or_insert_with(|| Value::String(idx.name.to_string()));
                    if let Some(seq) = idx.lookup_seq_no(id) {
                        o.entry("_seq_no".to_string()).or_insert_with(|| json!(seq));
                    }
                }
                Some(v)
            }
        }
    }
}

pub(super) struct FastCtx<'a> {
    idx: &'a Index,
    segs: Vec<SegEntry>,
    /// Memtable docs (see `MemDocs`), built LAZILY on first executor
    /// access: the columnar terms/cardinality memtable arms don't touch
    /// per-doc sources at all, so the per-request materialisation
    /// (doc_id String clones + Arc bumps over the whole buffered set —
    /// several ms at a drain-lagged memtable, EVERY agg request) is only
    /// paid by executors that genuinely walk docs.
    mem_docs: std::sync::OnceLock<MemDocs>,
    /// Whether the agg tree can observe meta fields (`top_hits`, `_id`,
    /// `_index`, `_seq_no`) — decides Owned vs Shared at build time.
    needs_owned_mem: bool,
    /// Schema fields mapped `boolean`.  Their `.dv` columns are numeric
    /// 0/1 (indistinguishable from real integers at the column level), but
    /// the brute path renders them as "false"/"true" term keys — so the
    /// terms executor needs the mapping to reproduce that.
    bool_fields: &'a std::collections::HashSet<String>,
    /// Every field name the schema maps.  Dynamic mapping only ever maps
    /// TOP-LEVEL keys, so a nested leaf (`geo.city`) is reached through its
    /// root (`geo`), which IS in this set.  A field with no doc-value column
    /// at any depth in any segment, whose name OR top-level root is in this
    /// set, is one brute's `get_field_value` still resolves — an object's
    /// nested leaf (`geo.city`, root `geo` mapped object), or a top-level
    /// field whose column was SUPPRESSED because it is multi-valued (`tags`
    /// / `tags.raw`, mapped keyword, array-poisoned in
    /// `build_doc_value_columns`) — so the columnar path must bail rather
    /// than answer it empty.  A name whose root is absent from this set is
    /// genuinely absent and stays on the fast path.  See
    /// `field_needs_brute_fallback`.
    mapped_fields: &'a std::collections::HashSet<String>,
    /// Top-level query filter (from `{size:0, query:Q, aggs:…}`), compiled to
    /// a columnar predicate.  `None` == match_all (the whole corpus). When
    /// present, EVERY executor restricts its columnar reduction to matching
    /// segment rows (via the `fused_seg_pass` row gate + `exec_metric_top`'s
    /// filtered loop) and every memtable-doc walk is gated by
    /// `doc_matches_filter(doc, top_filter_query)`.  Only metric + terms aggs
    /// support filtering; other agg types bail (None) so the caller falls back
    /// to the exact brute path.
    top_filter: Option<Pred>,
    /// The original ES-JSON query for the top-level filter, used for the
    /// memtable per-doc match (the trusted sibling of `compile_pred`, exactly
    /// as `exec_filter` pairs them).  `None` == match_all.
    top_filter_query: Option<Value>,
    /// The top-level filter compiled to memtable columnar predicates (a pure
    /// Term/Range conjunction), when it is one.  Drives the O(matching)
    /// filtered-memtable fold (`filtered_mem`); `None` when the filter isn't a
    /// pure conjunction (e.g. `terms`) or there is no filter — the executors
    /// then walk the full `mem()` gated by `doc_matches_filter`, exactly as
    /// before.
    top_filter_mem_preds: Option<Vec<MemBoolPred>>,
    /// Lazily-materialised columnar-filtered memtable docs (see `filtered_mem`).
    /// The outer `Option` is the OnceLock cell; the inner `Option` is the
    /// memtable's own "columnar path applicable?" answer (`None` == a bailout,
    /// fall back to full `mem()`).
    mem_filtered: std::sync::OnceLock<Option<Vec<(String, std::sync::Arc<Value>)>>>,
    /// [#1260] `Some(segment-ids-of-the-snapshot)` iff the request was
    /// admitted under the delete-aware gate (every snapshot segment's ghost
    /// bitmap empty — live == physical).  The memtable views (`mem`,
    /// `filtered_mem`) then drop buffered docs whose live copy already sits
    /// in one of those segments (`mem_doc_live`), and the delete-blind
    /// memtable columnar summaries are switched off in favour of the exact
    /// per-doc walks.  `None` == the classic no-deletes path, byte-for-byte
    /// as before.
    mem_live_gate: Option<std::collections::HashSet<String>>,
}

impl<'a> FastCtx<'a> {
    /// Lazy memtable-docs view (see the field doc).  Kept identical to the
    /// eager build this replaces: Owned (deep clone + meta injection) when
    /// the agg tree can observe meta fields, Arc-shared otherwise.
    fn mem(&self) -> &MemDocs {
        self.mem_docs.get_or_init(|| {
            if self.idx.memtable.doc_count() == 0 {
                return MemDocs::Owned(Vec::new());
            }
            if self.needs_owned_mem {
                let gate = self.mem_live_gate.as_ref();
                MemDocs::Owned(
                    self.idx
                        .memtable
                        .all_docs_with_sources()
                        .into_iter()
                        .filter(|(id, _)| gate.is_none_or(|s| self.mem_doc_live(id, s)))
                        .map(|(id, mut v)| {
                            if let Some(o) = v.as_object_mut() {
                                o.entry("_id".to_string())
                                    .or_insert_with(|| Value::String(id.clone()));
                                o.entry("_index".to_string())
                                    .or_insert_with(|| Value::String(self.idx.name.to_string()));
                                if let Some(seq) = self.idx.lookup_seq_no(&id) {
                                    o.entry("_seq_no".to_string()).or_insert_with(|| json!(seq));
                                }
                            }
                            v
                        })
                        .collect(),
                )
            } else {
                let mut pairs = self.idx.memtable.all_docs_with_sources_arc();
                if let Some(snap_ids) = &self.mem_live_gate {
                    pairs.retain(|(id, _)| self.mem_doc_live(id, snap_ids));
                }
                let mut ids = Vec::with_capacity(pairs.len());
                let mut srcs = Vec::with_capacity(pairs.len());
                for (id, src) in pairs {
                    ids.push(id);
                    srcs.push(src);
                }
                MemDocs::Shared { ids, srcs }
            }
        })
    }

    /// [#1260] Liveness of a buffered memtable doc under the admission gate —
    /// the fast path's counterpart of `fold_match_sources`'s memtable check,
    /// adjusted for the OPPOSITE capture order (snapshot first, memtable
    /// lazily after).  A doc is live when nothing in the version map
    /// supersedes it: not deleted, and either still in-memory or repointed
    /// into a segment OUTSIDE this snapshot (that copy is invisible to this
    /// request, so the buffered one remains its only sight).
    fn mem_doc_live(&self, id: &str, snap_ids: &std::collections::HashSet<String>) -> bool {
        match self.idx.store.version_map.get(id) {
            None => true,
            Some(ver) => {
                !ver.deleted
                    && (ver.segment_id.as_ref() == xerj_storage::version_map::IN_MEMORY_SEGMENT_ID
                        || !snap_ids.contains(ver.segment_id.as_ref()))
            }
        }
    }

    /// Columnar-filtered memtable docs for the top-level filter, or `None` when
    /// the columnar fold doesn't apply — the caller then walks the full `mem()`
    /// gated by `doc_matches_filter`, exactly as before.
    ///
    /// Applies ONLY when the top-level filter compiled to a pure Term/Range
    /// conjunction AND the agg tree can't observe meta fields (`needs_owned_mem`
    /// == false — the columnar sources carry no `_id`/`_index`/`_seq_no`, and
    /// under that condition `plan.top_hits` is always `None`, so the positional
    /// `DocRef::Mem`/`mem().len()` paths never run) AND every predicate field is
    /// a scalar doc-valued column in every shard (the memtable returns `None`
    /// otherwise).  The returned set is a no-false-negative superset of the
    /// `doc_matches_filter` set — callers re-apply the JSON matcher for
    /// byte-identical results.
    fn filtered_mem(&self) -> Option<&[(String, std::sync::Arc<Value>)]> {
        if self.needs_owned_mem {
            return None;
        }
        let preds = self.top_filter_mem_preds.as_ref()?;
        self.mem_filtered
            .get_or_init(|| {
                let mut docs = self.idx.memtable.filtered_docs_arc(preds)?;
                // [#1260] Same liveness fold as `mem` — the columnar
                // candidate set may still hold stale pre-drain copies.
                if let Some(snap_ids) = &self.mem_live_gate {
                    docs.retain(|(id, _)| self.mem_doc_live(id, snap_ids));
                }
                Some(docs)
            })
            .as_deref()
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ColKind {
    Numeric,
    Keyword,
    /// `doc_values: false` field. The column records which rows have a
    /// value, not the value. Term and metric executors must not read it
    /// as a dictionary or a number.
    Presence,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum MetricKind {
    Avg,
    Sum,
    Min,
    Max,
    Stats,
    ValueCount,
}

#[derive(Clone, Copy, Default)]
struct MetricAcc {
    count: u64,
    sum: f64,
    min: f64,
    max: f64,
}

impl MetricAcc {
    #[inline]
    fn add(&mut self, v: f64) {
        if self.count == 0 {
            self.min = v;
            self.max = v;
        } else {
            if v < self.min {
                self.min = v;
            }
            if v > self.max {
                self.max = v;
            }
        }
        self.count += 1;
        self.sum += v;
    }
    /// value_count-style: value exists but only the count matters.
    #[inline]
    fn add_presence(&mut self) {
        self.count += 1;
    }
}

#[derive(Clone)]
struct MetricSpec {
    name: String,
    kind: MetricKind,
    field: String,
    meta: Option<Value>,
}

struct TopHitsSpec {
    name: String,
    params: Value,
    sort_field: String,
    desc: bool,
    k: usize,
    meta: Option<Value>,
}

/// Where a doc lives, for late-materialisation (top_hits winners).
#[derive(Clone, Copy)]
enum DocRef {
    Mem(usize),
    Seg(usize, u32),
}

/// Compiled sub-aggregation plan for a bucketing parent.
struct SubPlan {
    metrics: Vec<MetricSpec>,
    top_hits: Option<TopHitsSpec>,
    /// (name, agg_type, params, meta) for pipeline-family sub-aggs.  These
    /// are emitted as `run_pipeline_agg` placeholders per bucket (exactly
    /// like the brute path) and then resolved per-bucket + via
    /// `apply_bucket_pipeline_ops` on the parent's bucket array.
    pipelines: Vec<(String, String, Value, Option<Value>)>,
}

const PIPELINE_TYPES: &[&str] = &[
    "avg_bucket",
    "max_bucket",
    "min_bucket",
    "sum_bucket",
    "derivative",
    "moving_avg",
    "cumulative_sum",
    "bucket_selector",
    "bucket_sort",
    "bucket_script",
    "percentiles_bucket",
    "stats_bucket",
    "serial_diff",
    "moving_fn",
    "extended_stats_bucket",
];

fn metric_kind_of(t: &str) -> Option<MetricKind> {
    Some(match t {
        "avg" => MetricKind::Avg,
        "sum" => MetricKind::Sum,
        "min" => MetricKind::Min,
        "max" => MetricKind::Max,
        "stats" => MetricKind::Stats,
        "value_count" => MetricKind::ValueCount,
        _ => return None,
    })
}

/// Split an agg body into (agg_type, params, sub_aggs, meta) the same way
/// `execute_agg_with_all_cached` does.
fn split_agg_body(body: &Value) -> Option<(&str, &Value, Option<&Value>, Option<&Value>)> {
    let obj = body.as_object()?;
    let sub = obj.get("aggs").or_else(|| obj.get("aggregations"));
    let meta = obj.get("meta");
    let type_key = obj
        .keys()
        .find(|k| k.as_str() != "aggs" && k.as_str() != "aggregations" && k.as_str() != "meta")?;
    let params = obj.get(type_key)?;
    Some((type_key.as_str(), params, sub, meta))
}

/// Whitelist check: params object may only contain the listed keys.
fn params_only(params: &Value, allowed: &[&str]) -> bool {
    match params.as_object() {
        Some(o) => o.keys().all(|k| allowed.contains(&k.as_str())),
        None => false,
    }
}

/// [#1267] The one plan shape admitted with DIRTY ghost bitmaps: the aggs
/// tree is EXACTLY one plain `terms` aggregation — a single named entry
/// whose body is `{"terms": {...}}` and nothing else.  No sub-aggs (no
/// `aggs` key), no metrics, no `meta`, no siblings: anything beyond the
/// single terms body makes the shape's cost depend on an executor that may
/// read a delete-blind whole-segment stat, so it keeps today's bail.  The
/// caller additionally requires a top-level filter (checked before calling)
/// so `exec_terms` routes through the fused row pass.
fn single_plain_terms_agg(aggs_obj: &serde_json::Map<String, Value>) -> bool {
    if aggs_obj.len() != 1 {
        return false;
    }
    let Some(body) = aggs_obj.values().next().and_then(|v| v.as_object()) else {
        return false;
    };
    body.len() == 1 && body.contains_key("terms")
}

impl Index {
    /// Entry point — see module docs.  Returns `Some(agg_result)` (shaped
    /// exactly like `run_aggs_with_all`'s return) or `None` to fall back.
    pub(super) fn try_fast_aggs(
        &self,
        aggs_def: &Value,
        filter: Option<&Value>,
        snap: &xerj_storage::index_store::IndexSnapshot,
        segments_dir: &std::path::Path,
        bool_fields: &std::collections::HashSet<String>,
        mapped_fields: &std::collections::HashSet<String>,
    ) -> Option<(Value, Option<u64>)> {
        if fast_aggs_disabled() {
            return None;
        }
        let aggs_obj = aggs_def.as_object()?;
        if aggs_obj.is_empty() {
            return None;
        }

        // Top-level query filter (`{size:0, query:Q, aggs:…}`).  `None` ==
        // match_all — the pre-existing whole-corpus fast path.  When a filter
        // is present we MUST be able to columnarize it (term/terms/range/
        // match_all, or a pure-conjunction bool of those); anything else bails
        // to the exact brute path.
        let top_filter: Option<Pred> = match filter {
            None => None,
            Some(q) => Some(compile_top_pred(q)?),
        };
        let top_filter_query: Option<Value> = filter.cloned();
        // Columnar-predicate form of the filter for the O(matching) memtable
        // fold.  `None` for match_all or a non-conjunction filter (`terms`, …)
        // — those keep the full-memtable walk.
        let top_filter_mem_preds: Option<Vec<MemBoolPred>> =
            filter.and_then(mem_preds_from_agg_filter);

        // Size + delete gates.
        let seg_physical: u64 = snap.segments.iter().map(|m| m.doc_count).sum();
        let mem_physical = self.memtable.doc_count() as u64;
        let total_physical = seg_physical + mem_physical;
        if total_physical < FAST_AGG_MIN_DOCS {
            return None;
        }
        // Exact ghost signal — see the matching gate in `search_inner` and
        // `VersionMap::ghost_events` (the old live-vs-physical arithmetic
        // false-positived on physical-count drift and disabled this fast
        // path under append-only write load).
        let admission_epoch = self.store.version_map.ghost_events();
        let deletes_present = snap.segments.iter().any(|m| m.has_tombstones) || admission_epoch > 0;
        // [#1260] Deletes no longer disable the fast path outright.  Every
        // O(1) stat the executors use (per_ord_count, live_count,
        // range_count, the sorted run) is DELETE-BLIND — it counts physical
        // rows — which is why one superseded row anywhere used to bail the
        // whole request.  But `ghost_events` is MONOTONIC: after a merge
        // compacts the ghosts away the index is clean again, while the gate
        // stayed tripped forever (measured live: the 402,814-doc
        // autoindex-catalog, rewritten by every finalize-catalog, served a
        // filtered terms agg from the brute path until it hit 429 "query
        // allocation would exceed limits.max_query_memory_mb" — its
        // overwrite history had the gate tripped for its whole life).
        //
        // Admission instead, per non-empty segment: fetch the exact
        // ghost-position bitmap (`ghost_positions_for` — bit pos set ⇔ the
        // stored doc at that row is deleted or superseded; the merge
        // survivor filter guarantees at most one live copy per id, so the
        // id-level predicate is exact and its row space IS the `.dv`
        // column row space).  A segment with an EMPTY bitmap is provably
        // ghost-free — live == physical — which is exactly the invariant
        // every executor was built under, so the row-level arithmetic runs
        // unchanged.  Steady state after merges is clean bitmaps, so the
        // fast path comes BACK.  `None` (stored section unreadable) keeps
        // today's bail.
        //
        // [#1267] A segment with a NON-EMPTY bitmap no longer bails every
        // request: that was the 803,735 ms verify window.  A resumed crawl
        // shard carries tombstones from the resume's overwrites, so EVERY
        // one of its ~800 finalize-verify windows fell to the brute agg
        // corpus, which materialises the whole index per window — measured
        // live on the 53,153-doc `cves-28` shard (issue #1267).  Dirty
        // bitmaps are now admitted for exactly one plan shape that is
        // provably row-exact under ghosts: a top-level filter present (so
        // `exec_terms` takes the fused row pass, never the whole-segment
        // `per_ord_count` shortcut) plus a single plain `terms` agg — no
        // sub-aggs, no metrics, no siblings.  Every number that shape
        // produces comes from per-row accounting (`fused_seg_pass` skips
        // ghosted rows; the filtered total row-scans dirty segments) and
        // the live-filtered memtable walks.  Any other plan still bails on
        // the first dirty bitmap, as before — the O(1) stats it would read
        // (`per_ord_count`, `live_count`, `range_count`) count physical
        // rows and would double-count ghosts.
        let row_exact = top_filter.is_some() && single_plain_terms_agg(aggs_obj);
        let mut dirty_ghosts: std::collections::HashMap<String, std::sync::Arc<Vec<u64>>> =
            std::collections::HashMap::new();
        let mem_live_gate: Option<std::collections::HashSet<String>> = if deletes_present {
            for meta in &snap.segments {
                if meta.doc_count == 0 {
                    continue;
                }
                let ghosts = self.ghost_positions_for(&meta.id, meta.doc_count)?;
                if ghosts.iter().any(|w| *w != 0) {
                    if !row_exact {
                        return None;
                    }
                    dirty_ghosts.insert(meta.id.clone(), ghosts);
                }
            }
            // The memtable leg of the same gate: a buffered doc whose live
            // copy already sits in a snapshot segment is a stale pre-drain
            // duplicate (the liveness check `fold_match_sources` applies).
            // The SNAP-MEMBERSHIP form — not the fold's plain
            // `!= IN_MEMORY_SEGMENT_ID` — is required because this path
            // reads the snapshot FIRST and the memtable lazily AFTER (the
            // fold reads mem first): a fold-style check would also drop
            // docs drained into a segment this snapshot does not contain,
            // undercounting exactly the docs the request must still see.
            Some(snap.segments.iter().map(|m| m.id.clone()).collect())
        } else {
            None
        };

        // Warm the per-segment column cache in parallel first: a cold
        // many-segment index would otherwise decode every `.dv` sidecar
        // serially inside this request (~0.2 s × segments).  The decode work
        // is CPU-bound and `dv_columns_for` is DashMap-backed, so a rayon
        // fan-out is safe; the whole search body already runs inside
        // `block_in_place`.
        {
            use rayon::prelude::*;
            snap.segments.par_iter().for_each(|m| {
                if m.doc_count > 0 {
                    let _ = self.dv_columns_for(segments_dir, &m.id);
                }
            });
        }

        // Column sources.  A non-empty segment without a decodable `.dv`
        // sidecar makes the columnar view lossy → bail.
        let mut segs: Vec<SegEntry> = Vec::with_capacity(snap.segments.len());
        for meta in &snap.segments {
            if meta.doc_count == 0 {
                continue;
            }
            let cols = self.dv_columns_for(segments_dir, &meta.id)?;
            segs.push(SegEntry {
                id: meta.id.clone(),
                cols,
                docs: meta.doc_count as u32,
                ghosts: dirty_ghosts.get(&meta.id).cloned(),
            });
        }

        // Memtable docs, materialised brute-style (see `search_inner`'s
        // full-corpus assembly): `_id` + `_index` + `_seq_no` injected.
        // Owned (deep-clone + meta-field injection) only when the agg tree
        // can observe meta fields; Arc-shared otherwise.  Conservative
        // substring probe — false positives merely fall back to the exact
        // legacy build.
        // Structural walk instead of `aggs_def.to_string()` + substring
        // search — the serialize-the-whole-tree probe ran on every fast-agg
        // request.  Semantics are preserved exactly: `top_hits` matches as a
        // substring of any key/string (a `top_hits` agg key, or a nested
        // one), while the meta fields match the serialized `"_id"` / `"_index"`
        // / `"_seq_no"` tokens, i.e. an exact object key or string value.
        let needs_owned_mem = agg_tree_mentions_meta(aggs_def);

        let ctx = FastCtx {
            idx: self,
            segs,
            mem_docs: std::sync::OnceLock::new(),
            needs_owned_mem,
            bool_fields,
            mapped_fields,
            top_filter,
            top_filter_query,
            top_filter_mem_preds,
            mem_filtered: std::sync::OnceLock::new(),
            mem_live_gate,
        };

        // Filtered `hits.total`: the number of live docs matching the query.
        // For match_all the caller derives it from segment + memtable counts
        // (and later overwrites with the delete-aware live count), so we only
        // compute a total when a filter narrowed the corpus.  Clean segments
        // have live == physical (gated above), so the O(1) stats are exact;
        // [#1267] a dirty-but-admitted segment instead counts live matching
        // rows directly — `seg_pred_count`'s whole-segment arms
        // (`per_ord_count`, `range_count`, `live_count`) are delete-blind
        // and would count ghosted rows.  Each memtable doc is one hit
        // (weights affect agg `doc_count`, not `hits.total`).
        let filtered_total: Option<u64> = match &ctx.top_filter {
            None => None,
            Some(pred) => {
                let mut total: u64 = 0;
                for seg in &ctx.segs {
                    let sp = resolve_pred(&seg.cols, pred, &ctx.segs, ctx.mapped_fields)?;
                    total += match seg.ghosts.as_deref() {
                        None => seg_pred_count(&sp, seg.docs),
                        Some(g) => (0..seg.docs)
                            .filter(|&row| !ghost_bit(g, row) && seg_pred_matches(&sp, row))
                            .count() as u64,
                    };
                }
                if let Some(q) = &ctx.top_filter_query {
                    // O(matching) columnar fold when the filter columnarises;
                    // else the full-memtable walk.  Both re-check
                    // `doc_matches_filter` so the count is exact either way.
                    if let Some(fdocs) = ctx.filtered_mem() {
                        for (_id, src) in fdocs {
                            if doc_matches_filter(src, q) {
                                total += 1;
                            }
                        }
                    } else {
                        for doc in ctx.mem().iter() {
                            if doc_matches_filter(doc, q) {
                                total += 1;
                            }
                        }
                    }
                }
                Some(total)
            }
        };

        // What the top level of an aggs tree publishes as its document count:
        // the filtered total when a top-level query narrowed the corpus, else
        // the whole live corpus. Physical rows either way — the same number
        // `docs.len()` gives `aggs::run_aggs_with_all` on the brute path
        // (live == physical: by the no-deletes gate, or by the [#1260]
        // admission bitmaps — with the memtable leg taken from the
        // live-filtered `mem()` view, whose length drops the stale pre-drain
        // copies `total_physical` still counts).
        let top_doc_count = filtered_total.unwrap_or_else(|| {
            if ctx.mem_live_gate.is_some() {
                ctx.segs.iter().map(|s| s.docs as u64).sum::<u64>() + ctx.mem().len() as u64
            } else {
                total_physical
            }
        });
        let result = ctx.eval_aggs_object(aggs_obj, top_doc_count)?;
        // Capture-scope re-check (#1217's discipline, applied to the
        // admission): an overwrite or delete that landed while the executors
        // ran invalidates the per-segment bitmaps and the memtable liveness
        // fold above.  `ghost_events` only bumps on overwrite/delete — never
        // on a pure flush repoint — so an unchanged epoch proves the
        // admission still holds for everything this request read.  On bump,
        // bail: the caller reruns the whole aggregation on the brute path.
        // (A pure drain straddling the request is NOT caught by the epoch —
        // the same pre-existing window as the lazily built `mem()` view,
        // unchanged by the gate.)
        if self.store.version_map.ghost_events() != admission_epoch {
            return None;
        }
        // Served columnarly — record it. The two executors are INTENDED to
        // return the same bytes, so a caller cannot tell them apart from the
        // response and a test needs this signal (see
        // `aggs::fast_path_aggs_served`, which documents why that intent is
        // not yet fact).
        crate::aggs::note_fast_path_agg();
        Some((Value::Object(result), filtered_total))
    }
}

impl<'a> FastCtx<'a> {
    // ── field/kind helpers ───────────────────────────────────────────────

    /// The column kind of `field` across all segments.  `Ok(None)` = the
    /// field appears in no segment.  Mixed numeric/keyword → `Err` (bail).
    ///
    /// `Err` is also returned for any name [`field_needs_brute_fallback`]
    /// flags — a multi-field suffix a brute resolver strips, a nested-object
    /// leaf, or a mapped field whose column is missing from one or more
    /// segments (per-segment array suppression, #143).  Every caller already
    /// treats `Err` as "bail to brute", and every executor that reads a
    /// column for an agg TARGET gates on this first, so one check here
    /// closes the whole target surface — including the sites that `continue`
    /// past a column-less segment (`exec_terms`, `exec_date_histogram`, the
    /// sub-metric fold) rather than bailing, which is how an aggregation
    /// target silently under-returned.  That matters for the field names
    /// `exec_agg`'s own `params["field"]` gate never sees: sub-metric fields
    /// (`plan_subs`), `top_hits` sort fields, `matrix_stats` `fields` and
    /// composite `sources` all reach columns only through here.
    fn seg_field_kind(&self, field: &str) -> std::result::Result<Option<ColKind>, ()> {
        if field_needs_brute_fallback(field, &self.segs, self.mapped_fields) {
            return Err(());
        }
        let mut kind: Option<ColKind> = None;
        for s in &self.segs {
            let k = match s.col(field) {
                Some(Column::Numeric(_)) => ColKind::Numeric,
                Some(Column::Keyword(_)) => ColKind::Keyword,
                Some(Column::Presence(_)) => ColKind::Presence,
                None => continue,
            };
            match kind {
                None => kind = Some(k),
                Some(prev) if prev == k => {}
                Some(_) => return Err(()),
            }
        }
        Ok(kind)
    }

    /// Global corpus-order rank offset of segment `si` (mem docs first, then
    /// segments in snapshot order) — mirrors the brute corpus assembly.
    fn seg_rank_offset(&self, si: usize) -> u64 {
        let mut off = self.mem().len() as u64;
        for s in &self.segs[..si] {
            off += s.docs as u64;
        }
        off
    }

    /// Materialise one segment-resident doc brute-corpus-style.
    fn fetch_seg_doc(&self, si: usize, row: u32) -> Option<Value> {
        let seg = &self.segs[si];
        let stored = self.idx.stored_values_for(&seg.id)?;
        let d = stored.get(row as usize)?;
        let id = d
            .get("_id")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let mut src = d.get("_source").cloned().unwrap_or_else(|| d.clone());
        if let Some(o) = src.as_object_mut() {
            if !id.is_empty() {
                o.entry("_id".to_string())
                    .or_insert(Value::String(id.clone()));
            }
            o.entry("_index".to_string())
                .or_insert_with(|| Value::String(self.idx.name.to_string()));
            if !id.is_empty() {
                if let Some(seq) = self.idx.lookup_seq_no(&id) {
                    o.entry("_seq_no".to_string()).or_insert_with(|| json!(seq));
                }
            }
        }
        Some(src)
    }

    fn fetch_doc(&self, r: DocRef) -> Option<Value> {
        match r {
            DocRef::Mem(i) => self.mem().owned(i, self.idx),
            DocRef::Seg(si, row) => self.fetch_seg_doc(si, row),
        }
    }

    // ── sub-agg planning ─────────────────────────────────────────────────

    /// Compile a parent's sub-agg tree.  `allow_top_hits` gates the (more
    /// expensive) winner-materialisation machinery to parents that support
    /// it.  Any unsupported shape → `None` (bail).
    fn plan_subs(&self, sub_aggs: Option<&Value>, allow_top_hits: bool) -> Option<SubPlan> {
        let mut plan = SubPlan {
            metrics: Vec::new(),
            top_hits: None,
            pipelines: Vec::new(),
        };
        let Some(sub) = sub_aggs else {
            return Some(plan);
        };
        let sub_obj = sub.as_object()?;
        for (name, body) in sub_obj {
            let (t, params, nested_sub, meta) = split_agg_body(body)?;
            if nested_sub.is_some() {
                return None; // no grandchildren on the fast path
            }
            if let Some(kind) = metric_kind_of(t) {
                if !params_only(params, &["field", "format"]) {
                    return None;
                }
                let field = params.get("field").and_then(Value::as_str)?.to_string();
                // Metric fold semantics require a numeric column (value_count
                // also accepts keyword).  Mixed kinds bail inside.
                match self.seg_field_kind(&field) {
                    Err(()) => return None,
                    Ok(Some(ColKind::Keyword)) if kind != MetricKind::ValueCount => return None,
                    _ => {}
                }
                // Memtable docs must hold plain numbers for the field (or
                // miss it) so brute string/date coercion can't diverge.
                if kind != MetricKind::ValueCount && !self.mem_field_numeric_safe(&field) {
                    return None;
                }
                plan.metrics.push(MetricSpec {
                    name: name.clone(),
                    kind,
                    field,
                    meta: meta.cloned(),
                });
            } else if t == "top_hits" {
                if !allow_top_hits || plan.top_hits.is_some() {
                    return None;
                }
                let spec = self.plan_top_hits(name, params, meta)?;
                plan.top_hits = Some(spec);
            } else if PIPELINE_TYPES.contains(&t) {
                plan.pipelines
                    .push((name.clone(), t.to_string(), params.clone(), meta.cloned()));
            } else {
                return None;
            }
        }
        Some(plan)
    }

    fn mem_field_numeric_safe(&self, field: &str) -> bool {
        // Under a columnarisable top filter, only the MATCHING docs are folded
        // (segments + the columnar memtable candidate set, `doc_matches_filter`-
        // rechecked), so the metric fold never touches a non-matching doc — the
        // numeric-safety check need only cover the candidate set.  That set is a
        // superset of the true matches, so this stays conservative (it may bail
        // to brute on a non-matching candidate, never the reverse) while
        // avoiding the full-memtable hydration.  When the columnar path doesn't
        // apply it walks the full `mem()` exactly as before.
        let is_num =
            |d: &Value| matches!(get_nested_field(d, field), Value::Number(_) | Value::Null);
        if let Some(fdocs) = self.filtered_mem() {
            fdocs.iter().all(|(_id, src)| is_num(src))
        } else {
            self.mem().iter().all(is_num)
        }
    }

    fn plan_top_hits(
        &self,
        name: &str,
        params: &Value,
        meta: Option<&Value>,
    ) -> Option<TopHitsSpec> {
        if !params_only(params, &["size", "from", "sort", "_source"]) {
            return None;
        }
        let size = params.get("size").and_then(Value::as_u64).unwrap_or(3) as usize;
        let from = params.get("from").and_then(Value::as_u64).unwrap_or(0) as usize;
        let k = from + size;
        if k == 0 || k > 100 {
            return None;
        }
        // Exactly one sort entry over a plain numeric field.
        let sort_arr: Vec<Value> = match params.get("sort") {
            Some(Value::Array(a)) => a.clone(),
            Some(Value::Object(o)) => vec![Value::Object(o.clone())],
            _ => return None, // default _score sort → bail
        };
        if sort_arr.len() != 1 {
            return None;
        }
        let obj = sort_arr[0].as_object()?;
        if obj.len() != 1 {
            return None;
        }
        let (field, opts) = obj.iter().next()?;
        if field.starts_with('_') {
            return None;
        }
        let desc = match opts {
            Value::String(s) => s == "desc",
            Value::Object(o) => {
                if !o.keys().all(|k| k == "order") {
                    return None; // mode / nested / missing → bail
                }
                o.get("order")
                    .and_then(Value::as_str)
                    .map(|v| v == "desc")
                    .unwrap_or(false)
            }
            _ => return None,
        };
        // Sort field must be numeric everywhere.
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Numeric)) => {}
            _ => return None,
        }
        if !self.mem_field_numeric_safe(field) {
            return None;
        }
        Some(TopHitsSpec {
            name: name.to_string(),
            params: params.clone(),
            sort_field: field.clone(),
            desc,
            k,
            meta: meta.cloned(),
        })
    }

    // ── metric emission (mirrors run_avg / run_sum / … exactly) ─────────

    fn emit_metric(kind: MetricKind, acc: &MetricAcc) -> Value {
        match kind {
            MetricKind::Avg => {
                if acc.count == 0 {
                    json!({ "value": Value::Null, "__xy_count__": 0, "__xy_sum__": 0.0 })
                } else {
                    let avg = acc.sum / acc.count as f64;
                    json!({ "value": avg, "__xy_count__": acc.count, "__xy_sum__": acc.sum })
                }
            }
            MetricKind::Sum => json!({ "value": acc.sum, "__xy_agg__": "sum" }),
            MetricKind::Min => {
                if acc.count == 0 {
                    json!({ "value": Value::Null, "__xy_agg__": "min" })
                } else {
                    json!({ "value": acc.min, "__xy_agg__": "min" })
                }
            }
            MetricKind::Max => {
                if acc.count == 0 {
                    json!({ "value": Value::Null, "__xy_agg__": "max" })
                } else {
                    json!({ "value": acc.max, "__xy_agg__": "max" })
                }
            }
            MetricKind::Stats => {
                if acc.count == 0 {
                    json!({ "count": 0, "min": Value::Null, "max": Value::Null, "avg": Value::Null, "sum": 0.0 })
                } else {
                    json!({
                        "count": acc.count,
                        "min": acc.min,
                        "max": acc.max,
                        "avg": acc.sum / acc.count as f64,
                        "sum": acc.sum,
                    })
                }
            }
            MetricKind::ValueCount => json!({ "value": acc.count }),
        }
    }

    /// Fold one memtable doc's field value into a metric accumulator using
    /// the brute extractors (so memtable semantics are exactly brute).
    fn fold_mem_metric(doc: &Value, spec: &MetricSpec, acc: &mut MetricAcc) {
        match spec.kind {
            MetricKind::ValueCount => {
                let vals = extract_field_values(doc, &spec.field);
                for _ in vals {
                    acc.add_presence();
                }
            }
            _ => {
                if let Some(v) = extract_numeric(doc, &spec.field) {
                    acc.add(v);
                }
            }
        }
    }

    /// Attach computed sub-agg results (metrics + pipeline placeholders) to
    /// a bucket object, then resolve per-bucket sibling pipelines exactly
    /// like the brute per-bucket `run_aggs_with_all` call does.
    fn finish_bucket(
        &self,
        bucket: &mut Map<String, Value>,
        plan: &SubPlan,
        accs: &[MetricAcc],
        top_hits_result: Option<Value>,
    ) {
        for (mi, spec) in plan.metrics.iter().enumerate() {
            let mut v = Self::emit_metric(spec.kind, &accs[mi]);
            if let Some(o) = v.as_object_mut() {
                o.insert(
                    "__type__".into(),
                    Value::String(metric_type_name(spec.kind).to_string()),
                );
                if let Some(m) = &spec.meta {
                    o.insert("meta".into(), m.clone());
                }
            }
            bucket.insert(spec.name.clone(), v);
        }
        if let (Some(spec), Some(mut th)) = (plan.top_hits.as_ref(), top_hits_result) {
            if let Some(o) = th.as_object_mut() {
                o.insert("__type__".into(), Value::String("top_hits".to_string()));
                if let Some(m) = &spec.meta {
                    o.insert("meta".into(), m.clone());
                }
            }
            bucket.insert(spec.name.clone(), th);
        }
        for (name, t, params, meta) in &plan.pipelines {
            let mut v = run_pipeline_agg(t, params);
            if let Some(o) = v.as_object_mut() {
                o.insert("__type__".into(), Value::String(t.clone()));
                if let Some(m) = meta {
                    o.insert("meta".into(), m.clone());
                }
            }
            bucket.insert(name.clone(), v);
        }
        if !plan.pipelines.is_empty() {
            resolve_sibling_pipelines(bucket);
        }
    }

    // ── dispatch ─────────────────────────────────────────────────────────

    /// Evaluate a whole `aggs` object over this context, mirroring the
    /// top-level dispatch in `try_fast_aggs`: each named entry is executed
    /// (or run as a sibling pipeline), tagged with `__type__`/`meta`, and
    /// then sibling-pipeline references are resolved.  Shared so the `global`
    /// bucket can re-evaluate its sub-aggs over the whole corpus (via a child
    /// context with no top filter) with byte-identical shaping.
    ///
    /// `bucket_doc_count` is the `doc_count` the enclosing level publishes —
    /// the whole-corpus/filtered total at the top level, the `global` bucket's
    /// own count under `global`. It is staged for a bare `_count` buckets_path
    /// exactly as `aggs::run_aggs_in_bucket` stages it on the brute path;
    /// without it a bare `_count` resolved to `null` here while brute returned
    /// the count (measured: a 12,000-doc index, `{"buckets_path": "_count"}`
    /// at the top level, `null` on this path vs `12000.0` with
    /// `XERJ_DISABLE_FAST_AGGS=1`).
    ///
    /// Per-bucket executors do NOT go through this — they call
    /// `resolve_sibling_pipelines` on the finished bucket map, which already
    /// carries the real `doc_count` key.
    fn eval_aggs_object(
        &self,
        aggs_obj: &Map<String, Value>,
        bucket_doc_count: u64,
    ) -> Option<Map<String, Value>> {
        let mut result = Map::new();
        for (agg_name, agg_body) in aggs_obj {
            let (agg_type, params, sub, meta) = split_agg_body(agg_body)?;
            let mut agg_result = if PIPELINE_TYPES.contains(&agg_type) {
                // Sibling pipeline — placeholder now, resolved below.
                run_pipeline_agg(agg_type, params)
            } else {
                self.exec_agg(agg_type, params, sub)?
            };
            if let Some(obj) = agg_result.as_object_mut() {
                obj.insert("__type__".into(), Value::String(agg_type.to_string()));
                if let Some(m) = meta {
                    obj.insert("meta".into(), m.clone());
                }
            }
            result.insert(agg_name.clone(), agg_result);
        }
        let staged_doc_count = !result.contains_key("doc_count")
            && result.values().any(|v| {
                v.get("__pipeline__")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
            });
        if staged_doc_count {
            result.insert("doc_count".to_string(), json!(bucket_doc_count));
        }
        resolve_sibling_pipelines(&mut result);
        if staged_doc_count {
            result.remove("doc_count");
        }
        Some(result)
    }

    /// `global` bucket — ignores the top-level query and aggregates the WHOLE
    /// corpus.  A child context with no top filter (sharing the same decoded
    /// columns via Arc + the same memtable source) evaluates the sub-aggs, so
    /// e.g. `value_count`/`avg`/`terms` run straight off doc-values instead of
    /// hydrating `_source` on the brute path.  Byte-identical to the brute
    /// `run_aggs_with_all` global bucket: `{doc_count, <subs>}`.
    fn exec_global(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        // `global` takes no params.
        if !params.as_object().is_some_and(|o| o.is_empty()) {
            return None;
        }
        let child = FastCtx {
            idx: self.idx,
            segs: self.segs.clone(),
            mem_docs: std::sync::OnceLock::new(),
            needs_owned_mem: self.needs_owned_mem,
            bool_fields: self.bool_fields,
            mapped_fields: self.mapped_fields,
            top_filter: None,
            top_filter_query: None,
            top_filter_mem_preds: None,
            mem_filtered: std::sync::OnceLock::new(),
            // [#1260] carry the admission gate: the child walks the same
            // (possibly ghost-admitted) segment set, so its `mem()` view
            // must apply the same liveness fold.
            mem_live_gate: self.mem_live_gate.clone(),
        };
        let mut bucket = Map::new();
        // Whole-corpus doc_count (live == physical: no deletes, or the
        // [#1260] admission gate + the live-filtered `mem()` view; segment
        // rows are weight-1, memtable docs honour `_doc_count`, matching
        // every other fast-path executor).
        let mut doc_count: u64 = 0;
        for seg in &child.segs {
            doc_count += seg.docs as u64;
        }
        for doc in child.mem().iter() {
            doc_count += doc_count_weight(doc);
        }
        bucket.insert("doc_count".to_string(), json!(doc_count));
        if let Some(sub_aggs) = sub.and_then(Value::as_object) {
            let subs = child.eval_aggs_object(sub_aggs, doc_count)?;
            for (k, v) in subs {
                bucket.insert(k, v);
            }
        }
        Some(Value::Object(bucket))
    }

    fn field_is_structurally_unsupported(&self, field: &str) -> bool {
        field_needs_brute_fallback(field, &self.segs, self.mapped_fields)
    }

    fn exec_agg(&self, agg_type: &str, params: &Value, sub: Option<&Value>) -> Option<Value> {
        // A field referencing a genuinely nested JSON path has no column of
        // its own in any segment — see `field_is_structurally_unsupported`.
        // Every exec_* below keys off `params["field"]`, and without this
        // check each one independently (and inconsistently) treated "no
        // column found" the same as "field genuinely absent" — a valid ES
        // outcome for a sparse/dynamic field — silently returning empty
        // buckets / null metrics instead of bailing to the brute-force
        // path, which resolves nested paths correctly by walking
        // `_source`. Found live: `geo.dest` terms, `machine.ram` avg, and
        // the doubly-nested `machine.os.keyword` terms all went
        // empty/null through the fast path while a byte-identical
        // brute-force query returned real data.
        if let Some(field) = params.get("field").and_then(Value::as_str) {
            if self.field_is_structurally_unsupported(field) {
                return None;
            }
        }
        // Under a top-level query filter only the executors that thread the
        // filter through their columnar reduction are correct; every other
        // agg type falls back to the exact brute path (return None).  The
        // supported set covers the filtered-metric benchmark (avg/sum/…), the
        // common filtered `terms` dashboard, and `global` (which ignores the
        // filter entirely — it reduces over the whole corpus).
        // `extended_stats` and the percentile family joined this list once
        // their value gathering became filter-aware (`gather_numeric_sorted`
        // gates on the `sorted` index's doc_id; `exec_extended_stats` gates
        // its fold on the row).  Before that they were excluded for
        // CORRECTNESS, not speed — folding every row under a filter would
        // report whole-index statistics for a filtered query.  The exclusion
        // meant a filtered `percentiles` fell to the O(N) `_source` scan:
        // measured 11.9 s on 1.12 M docs, 70 s on 5.6 M.
        if self.top_filter.is_some()
            && !matches!(
                agg_type,
                "avg"
                    | "sum"
                    | "min"
                    | "max"
                    | "stats"
                    | "value_count"
                    | "terms"
                    | "cardinality"
                    | "global"
                    | "extended_stats"
                    | "percentiles"
                    | "percentile_ranks"
                    | "median_absolute_deviation"
            )
        {
            return None;
        }
        match agg_type {
            "avg" | "sum" | "min" | "max" | "stats" | "value_count" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_metric_top(metric_kind_of(agg_type)?, params)
            }
            "extended_stats" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_extended_stats(params)
            }
            "percentiles" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_percentiles(params)
            }
            "percentile_ranks" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_percentile_ranks(params)
            }
            "missing" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_missing(params)
            }
            "median_absolute_deviation" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_median_absolute_deviation(params)
            }
            "matrix_stats" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_matrix_stats(params)
            }
            "auto_date_histogram" => self.exec_auto_date_histogram(params, sub),
            "terms" => self.exec_terms(params, sub),
            "rare_terms" => self.exec_rare_terms(params, sub),
            "significant_terms" => self.exec_significant_terms(params, sub),
            "cardinality" => self.exec_cardinality(params, sub),
            "range" => self.exec_range(params, sub),
            "date_range" => self.exec_date_range(params, sub),
            "filter" => self.exec_filter(params, sub),
            "filters" => self.exec_filters(params, sub),
            "adjacency_matrix" => self.exec_adjacency_matrix(params, sub),
            "composite" => self.exec_composite(params, sub),
            "global" => self.exec_global(params, sub),
            "sampler" | "random_sampler" => self.exec_sampler(params, sub),
            "variable_width_histogram" => self.exec_vwh(params, sub),
            "date_histogram" => self.exec_date_histogram(params, sub),
            "histogram" => self.exec_histogram(params, sub),
            "scripted_metric" => {
                if sub.is_some() {
                    return None;
                }
                self.exec_scripted_metric(params)
            }
            _ => None,
        }
    }

    // ── scripted_metric (reducible sum shape) ────────────────────────────
    //
    // The interpreter path (`aggs::run_scripted_metric`) runs only inside the
    // brute `run_aggs_with_all`, which first decompresses + JSON-parses EVERY
    // live doc, then tree-walks the map script per doc (≈730 ms on a 100 k
    // corpus).  When the four scripts form the canonical "sum one numeric doc
    // field" shape (`aggs::scripted_metric_sum_field`), the whole aggregation
    // is exactly `Σ doc.FIELD.value` over the matched docs — served here off the
    // numeric `.dv` column with no materialisation.
    //
    // Correctness contract (byte-identical to the interpreter):
    // * Painless long arithmetic renders an INTEGER as long as every summed
    //   value is integral (`num_binop`'s `both_int` rule); the moment a
    //   fractional value — or a missing field (`doc.F.value` → Null, which
    //   flips the accumulator to a float) — participates, the result becomes a
    //   float.  We therefore serve ONLY the wholly-integral, no-missing case
    //   and render `{"value": <i64>}`; anything else bails (`None`) to the exact
    //   interpreter.  Integer sums below 2^53 are order-independent in f64, so
    //   the columnar summation order is irrelevant to the emitted value.
    // * A top-level query filter never reaches here (scripted_metric is absent
    //   from `exec_agg`'s filtered whitelist, so `top_filter.is_some()` already
    //   returned `None`).
    fn exec_scripted_metric(&self, params: &Value) -> Option<Value> {
        let field = crate::aggs::scripted_metric_sum_field(params)?;
        if self.seg_field_kind(&field).ok()? != Some(ColKind::Numeric) {
            return None;
        }

        // ~9.007e15 == 2^53: the largest magnitude whose integer neighbours are
        // all exactly representable in f64 (mirrors `num_binop`'s int-shape cap).
        const INT_SAFE_ABS: f64 = 9.007e15;
        let mut sum = 0f64;

        // Segments: every doc in the segment must contribute a live, integral
        // value (no missing → no interpreter Null → stays integer).
        for s in &self.segs {
            if s.docs == 0 {
                continue;
            }
            match s.col(&field) {
                Some(Column::Numeric(n)) => {
                    if !n.null_bitmap.is_empty() || n.live_count != s.docs as u64 {
                        return None; // some doc lacks the field
                    }
                    for bits in &n.data {
                        let v = f64::from_bits(*bits as u64);
                        if v.fract() != 0.0 {
                            return None; // fractional → float result
                        }
                        sum += v;
                    }
                }
                _ => return None, // field absent in this segment
            }
        }

        // Memtable docs (usually empty on the drained-corpus fast path): each
        // must carry the field as an integral number, else bail.
        for doc in self.mem().iter() {
            match doc.get(&field) {
                Some(Value::Number(num)) => {
                    let v = num.as_f64()?;
                    if v.fract() != 0.0 {
                        return None;
                    }
                    sum += v;
                }
                _ => return None,
            }
        }

        if !sum.is_finite() || sum.abs() >= INT_SAFE_ABS {
            return None; // interpreter would flip to float shape here
        }
        Some(json!({ "value": sum as i64 }))
    }

    // ── top-level metric ─────────────────────────────────────────────────

    fn exec_metric_top(&self, kind: MetricKind, params: &Value) -> Option<Value> {
        if !params_only(params, &["field", "format"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        let seg_kind = self.seg_field_kind(field).ok()?;
        if kind != MetricKind::ValueCount {
            if seg_kind == Some(ColKind::Keyword) {
                return None;
            }
            if !self.mem_field_numeric_safe(field) {
                return None;
            }
        }

        // ── Filtered path ────────────────────────────────────────────────
        // A top-level query filter invalidates the O(1) precomputed column
        // stats (they cover the whole segment).  Reduce the metric over ONLY
        // the matching rows using the exact fused-pass fold (null handling,
        // value_count presence semantics identical to the unfiltered path),
        // then fold matching memtable docs with the brute extractors.
        if self.top_filter.is_some() {
            let spec = MetricSpec {
                name: String::new(),
                kind,
                field: field.to_string(),
                meta: None,
            };
            let plan = SubPlan {
                metrics: vec![spec.clone()],
                top_hits: None,
                pipelines: Vec::new(),
            };
            let mut accs: Vec<Vec<MetricAcc>> = vec![vec![MetricAcc::default()]];
            let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new()];
            let mut ms = false;
            for si in 0..self.segs.len() {
                let mut slot = |_row: u32| -> Option<usize> { Some(0) };
                self.fused_seg_pass(si, &mut slot, 1, &plan, &mut accs, &mut tops, &mut ms)?;
            }
            let mut acc = std::mem::take(&mut accs[0][0]);
            if let Some(q) = &self.top_filter_query {
                // O(matching) columnar fold when the filter columnarises; else
                // the full-memtable walk.  Both gate on `doc_matches_filter`, so
                // the folded set is byte-identical.
                if let Some(fdocs) = self.filtered_mem() {
                    for (_id, src) in fdocs {
                        if doc_matches_filter(src, q) {
                            Self::fold_mem_metric(src, &spec, &mut acc);
                        }
                    }
                } else {
                    for d in self.mem().iter() {
                        if doc_matches_filter(d, q) {
                            Self::fold_mem_metric(d, &spec, &mut acc);
                        }
                    }
                }
            }
            return Some(Self::emit_metric(kind, &acc));
        }

        let mut acc = MetricAcc::default();
        for s in &self.segs {
            match s.col(field) {
                Some(Column::Numeric(n)) => {
                    if n.live_count > 0 {
                        if kind == MetricKind::ValueCount {
                            acc.count += n.live_count;
                        } else {
                            // O(1) per segment via precomputed column stats.
                            if acc.count == 0 {
                                acc.min = n.live_min;
                                acc.max = n.live_max;
                            } else {
                                if n.live_min < acc.min {
                                    acc.min = n.live_min;
                                }
                                if n.live_max > acc.max {
                                    acc.max = n.live_max;
                                }
                            }
                            acc.count += n.live_count;
                            acc.sum += n.live_sum;
                        }
                    }
                }
                Some(Column::Keyword(k)) => {
                    // Only reachable for value_count.
                    acc.count += (k.doc_count as u64).saturating_sub(k.null_bitmap.len());
                }
                // Text presence is not a value_count of tokens. Bail so the
                // brute extractor answers.
                Some(Column::Presence(_)) => return None,
                None => {}
            }
        }
        let spec = MetricSpec {
            name: String::new(),
            kind,
            field: field.to_string(),
            meta: None,
        };
        for d in self.mem().iter() {
            Self::fold_mem_metric(d, &spec, &mut acc);
        }
        Some(Self::emit_metric(kind, &acc))
    }

    // ── extended_stats / percentiles / percentile_ranks (columnar) ───────
    //
    // These three leaves were the last O(N) brute-force uncached reads: the
    // pre-fix path fell into `run_aggs_with_all`, which decompresses +
    // JSON-parses EVERY live doc before `run_extended_stats` /
    // `run_percentiles` / `run_percentile_ranks` even see a value (~650 ms on
    // a 100 k corpus).  Served columnar they are a single linear fold over the
    // per-segment numeric `.dv` column (extended_stats) or a read of the
    // already-sorted column index (percentiles / percentile_ranks), dropping
    // to low-ms.  Each is byte-identical to its brute counterpart for the
    // shapes it accepts (modulo float-summation order — the same documented
    // divergence the other metric leaves carry), and bails (`None` → brute)
    // on any option that would change value gathering or rendering
    // (`missing`, `format`, `hdr`, `tdigest`).  A top-level query filter is
    // now threaded through the gathering itself (per-row `seg_pred_matches`
    // on the `sorted` index / the fold, plus `doc_matches_filter` on the
    // memtable), so these leaves no longer bail when a filter is present.

    /// Gather every live numeric value of `field` (segments + memtable) into a
    /// single ascending-sorted `Vec<f64>`, mirroring the brute
    /// `nums.sort_by(partial_cmp)` collection so percentile interpolation is
    /// byte-identical.  Returns `None` when the field isn't a scalar numeric
    /// everywhere (keyword column, or a memtable doc holds a non-number) — the
    /// caller then bails to the exact brute path.
    ///
    /// Each segment's `.dv` numeric column already carries a `sorted`
    /// value-index (`Vec<(bits, doc_id)>`, ascending by f64), so the common
    /// single-segment / no-memtable case is a pure O(N) copy with no sort.
    fn gather_numeric_sorted(&self, field: &str) -> Option<Vec<f64>> {
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Keyword)) | Err(()) => return None,
            _ => {}
        }
        if !self.mem_field_numeric_safe(field) {
            return None;
        }
        let mut capacity = self.mem().len();
        for s in &self.segs {
            if let Some(Column::Numeric(n)) = s.col(field) {
                capacity += n.live_count as usize;
            }
        }
        let mut vals: Vec<f64> = Vec::with_capacity(capacity);
        for s in &self.segs {
            // Under a top-level query filter, gather ONLY matching rows.  The
            // `sorted` index carries each value's `doc_id`, so the filter is a
            // per-row gate that preserves ascending order — no re-sort needed
            // and no separate pass.  Without this the percentile family had to
            // bail whenever a filter was present (the whitelist in `exec_agg`),
            // which is what dropped every filtered `percentiles` /
            // `percentile_ranks` / `median_absolute_deviation` onto the O(N)
            // `_source` scan.
            let seg_pred = match &self.top_filter {
                Some(p) => Some(resolve_pred(&s.cols, p, &self.segs, self.mapped_fields)?),
                None => None,
            };
            match s.col(field) {
                Some(Column::Numeric(n)) => match &seg_pred {
                    None => {
                        for (bits, _) in &n.sorted {
                            vals.push(f64::from_bits(*bits as u64));
                        }
                    }
                    Some(sp) => {
                        for (bits, doc_id) in &n.sorted {
                            if seg_pred_matches(sp, *doc_id) {
                                vals.push(f64::from_bits(*bits as u64));
                            }
                        }
                    }
                },
                Some(Column::Keyword(_)) | Some(Column::Presence(_)) => return None,
                None => {}
            }
        }
        // The collected values are already globally sorted iff they came from a
        // single pre-sorted column source and the memtable added none.
        let mut pre_sorted = self.segs.len() <= 1;
        // Memtable docs are gated by the same `doc_matches_filter` the brute
        // path uses, so the gathered multiset is identical either way.
        let mem_filter = self.top_filter_query.clone();
        for doc in self.mem().iter() {
            if let Some(q) = &mem_filter {
                if !doc_matches_filter(doc, q) {
                    continue;
                }
            }
            if let Some(v) = extract_numeric(doc, field) {
                vals.push(v);
                pre_sorted = false;
            }
        }
        if !pre_sorted {
            vals.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        }
        Some(vals)
    }

    /// `extended_stats` — single columnar pass computing count / sum /
    /// sum_of_squares / min / max, then the same exact-arithmetic moments +
    /// `std_deviation_bounds` (honouring `sigma`, default 2) as
    /// `run_extended_stats`.  Whitelisted params only; `missing` / `format`
    /// bail to brute.
    fn exec_extended_stats(&self, params: &Value) -> Option<Value> {
        if !params_only(params, &["field", "sigma"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Keyword)) | Err(()) => return None,
            _ => {}
        }
        if !self.mem_field_numeric_safe(field) {
            return None;
        }

        let mut count: u64 = 0;
        let mut sum: f64 = 0.0;
        let mut sum_sq: f64 = 0.0;
        let mut min = f64::INFINITY;
        let mut max = f64::NEG_INFINITY;
        let mut fold = |v: f64| {
            count += 1;
            sum += v;
            sum_sq += v * v;
            if v < min {
                min = v;
            }
            if v > max {
                max = v;
            }
        };
        for s in &self.segs {
            // Filter-aware fold: with a top-level query filter present, only
            // matching rows contribute.  Previously this loop was
            // filter-blind, which is why `extended_stats` had to be excluded
            // from the filtered whitelist in `exec_agg` — folding every row
            // under a filter would have reported whole-index moments for a
            // filtered query (silently wrong, not merely slow).
            let seg_pred = match &self.top_filter {
                Some(p) => Some(resolve_pred(&s.cols, p, &self.segs, self.mapped_fields)?),
                None => None,
            };
            match s.col(field) {
                Some(Column::Numeric(n)) => {
                    let no_nulls = n.null_bitmap.is_empty();
                    match &seg_pred {
                        None if no_nulls => {
                            for &bits in &n.data {
                                fold(f64::from_bits(bits as u64));
                            }
                        }
                        _ => {
                            for row in 0..n.doc_count {
                                if !no_nulls && n.null_bitmap.contains(row) {
                                    continue;
                                }
                                if let Some(sp) = &seg_pred {
                                    if !seg_pred_matches(sp, row) {
                                        continue;
                                    }
                                }
                                fold(f64::from_bits(n.data[row as usize] as u64));
                            }
                        }
                    }
                }
                Some(Column::Keyword(_)) | Some(Column::Presence(_)) => return None,
                None => {}
            }
        }
        let mem_filter = self.top_filter_query.clone();
        for doc in self.mem().iter() {
            if let Some(q) = &mem_filter {
                if !doc_matches_filter(doc, q) {
                    continue;
                }
            }
            if let Some(v) = extract_numeric(doc, field) {
                fold(v);
            }
        }

        if count == 0 {
            // Mirror run_extended_stats' empty shape exactly: `sum` is a real
            // zero, every higher-order moment is null.
            return Some(json!({
                "count": 0, "min": Value::Null, "max": Value::Null,
                "avg": Value::Null, "sum": 0.0, "sum_of_squares": Value::Null,
                "variance": Value::Null, "variance_population": Value::Null,
                "variance_sampling": Value::Null,
                "std_deviation": Value::Null,
                "std_deviation_population": Value::Null,
                "std_deviation_sampling": Value::Null,
                "std_deviation_bounds": {
                    "upper": Value::Null, "lower": Value::Null,
                    "upper_population": Value::Null, "lower_population": Value::Null,
                    "upper_sampling": Value::Null, "lower_sampling": Value::Null,
                }
            }));
        }

        let avg = sum / count as f64;
        let variance_pop = (sum_sq / count as f64) - avg * avg;
        let variance_pop = variance_pop.max(0.0);
        let variance_samp = if count > 1 {
            variance_pop * count as f64 / (count - 1) as f64
        } else {
            0.0
        };
        let std_deviation = variance_pop.max(0.0).sqrt();
        let std_deviation_samp = variance_samp.max(0.0).sqrt();
        let sigma = params.get("sigma").and_then(Value::as_f64).unwrap_or(2.0);

        Some(json!({
            "count": count,
            "min": min,
            "max": max,
            "avg": avg,
            "sum": sum,
            "sum_of_squares": sum_sq,
            "variance": variance_pop,
            "variance_population": variance_pop,
            "variance_sampling": variance_samp,
            "std_deviation": std_deviation,
            "std_deviation_population": std_deviation,
            "std_deviation_sampling": std_deviation_samp,
            "std_deviation_bounds": {
                "upper": avg + sigma * std_deviation,
                "lower": avg - sigma * std_deviation,
                "upper_population": avg + sigma * std_deviation,
                "lower_population": avg - sigma * std_deviation,
                "upper_sampling": avg + sigma * std_deviation_samp,
                "lower_sampling": avg - sigma * std_deviation_samp,
            }
        }))
    }

    /// `percentiles` — the ES-default (non-hdr) algorithm is exact linear
    /// interpolation over the sorted values (`run_percentiles`), so the
    /// columnar path reads the pre-sorted column index and applies the
    /// identical `rank = (pct/100)*(N-1)` interpolation.  Honours `percents`
    /// (default `[1,5,25,50,75,95,99]`) and `keyed` (default true); `hdr` /
    /// `missing` / `format` / `tdigest` bail to brute.
    fn exec_percentiles(&self, params: &Value) -> Option<Value> {
        if !params_only(params, &["field", "percents", "keyed"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        let percents: Vec<f64> = params
            .get("percents")
            .and_then(Value::as_array)
            .map(|arr| arr.iter().filter_map(Value::as_f64).collect())
            .unwrap_or_else(|| vec![1.0, 5.0, 25.0, 50.0, 75.0, 95.0, 99.0]);
        let keyed = params.get("keyed").and_then(Value::as_bool).unwrap_or(true);

        let nums = self.gather_numeric_sorted(field)?;
        let compute = |pct: f64| -> Option<f64> {
            if nums.is_empty() {
                return None;
            }
            let rank = (pct / 100.0) * (nums.len() as f64 - 1.0);
            let lo = rank.floor() as usize;
            let hi = (lo + 1).min(nums.len() - 1);
            let frac = rank - rank.floor();
            Some(nums[lo] * (1.0 - frac) + nums[hi] * frac)
        };

        if keyed {
            let values: Map<String, Value> = percents
                .iter()
                .map(|&pct| {
                    // ES keys with `String.valueOf(double)` — "25.0", "99.99".
                    let key = java_double_str(pct);
                    let val = match compute(pct) {
                        Some(v) => serde_json::Number::from_f64(v)
                            .map(Value::Number)
                            .unwrap_or(Value::Null),
                        None => Value::Null,
                    };
                    (key, val)
                })
                .collect();
            Some(json!({ "values": values }))
        } else {
            let arr: Vec<Value> = percents
                .iter()
                .map(|&pct| {
                    let val = match compute(pct) {
                        Some(v) => serde_json::Number::from_f64(v)
                            .map(Value::Number)
                            .unwrap_or(Value::Null),
                        None => Value::Null,
                    };
                    let key_num = serde_json::Number::from_f64(pct)
                        .map(Value::Number)
                        .unwrap_or(Value::Null);
                    json!({ "key": key_num, "value": val })
                })
                .collect();
            Some(json!({ "values": arr }))
        }
    }

    /// `percentile_ranks` — for each target value, the fraction of the corpus
    /// at or below it, ×100.  Byte-identical to `run_percentile_ranks`: the
    /// sorted column index turns each brute `filter(v <= t).count()` into a
    /// `partition_point` (same exact count).  `hdr` / `missing` / `format`
    /// bail to brute.
    fn exec_percentile_ranks(&self, params: &Value) -> Option<Value> {
        if !params_only(params, &["field", "values", "keyed"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        let targets = match params.get("values").and_then(Value::as_array) {
            Some(v) => v,
            None => return Some(json!({ "values": {} })),
        };
        let keyed = params.get("keyed").and_then(Value::as_bool).unwrap_or(true);

        let nums = self.gather_numeric_sorted(field)?;
        let total = nums.len() as f64;
        // `nums` is ascending, so the count of values <= t is a partition_point.
        let rank_of = |t: f64| -> f64 {
            if total == 0.0 {
                0.0
            } else {
                let below = nums.partition_point(|&v| v <= t) as f64;
                (below / total) * 100.0
            }
        };
        // ES sorts the requested values ascending before rendering, keys the
        // keyed map with `String.valueOf(double)` ("200.0"), and renders the
        // keyed=false key as a double (200.0) — byte-identical to brute
        // `run_percentile_ranks`.
        let mut sorted: Vec<f64> = targets.iter().filter_map(Value::as_f64).collect();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

        if keyed {
            let mut result = Map::new();
            for &t in &sorted {
                result.insert(java_double_str(t), json!(rank_of(t)));
            }
            Some(json!({ "values": result }))
        } else {
            let arr: Vec<Value> = sorted
                .iter()
                .map(|&t| json!({ "key": t, "value": rank_of(t) }))
                .collect();
            Some(json!({ "values": arr }))
        }
    }

    // ── missing / median_absolute_deviation / matrix_stats / auto_date_histogram ──
    //
    // Four more O(N) brute leaves (`run_aggs_with_all` materialised every live
    // doc — ~1 s / 100 k) rerouted through the doc-values columns.  Each bails
    // (`None` → brute) on any option that would change value gathering or
    // rendering, and (via the `exec_agg` whitelist) under a top-level query
    // filter, so what it serves is byte-identical to its brute counterpart for
    // the shapes it accepts (modulo the documented float-summation-order and
    // array-skip divergences the other fast-agg leaves already carry).

    /// `missing` — count of docs where `field` has no value.  The brute
    /// `run_missing` walks `get_nested_field(doc, field).is_null()`; served
    /// columnar that is `total − present` = each segment column's null count
    /// (whole segment when the field's column is absent) plus the exact
    /// `is_null` walk over the small memtable.  Only `{field}` (and the
    /// `missing`-placeholder short-circuit → `doc_count: 0`, matching brute) is
    /// accepted; `run_missing` ignores sub-aggs, so the `exec_agg` arm bails on
    /// any sub.
    fn exec_missing(&self, params: &Value) -> Option<Value> {
        if !params_only(params, &["field", "missing"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        // `missing` placeholder present → every doc has a synthetic value →
        // count collapses to 0 (identical to brute `has_missing_default`).
        if params.get("missing").is_some() {
            return Some(json!({ "doc_count": 0 }));
        }
        let mut missing: u64 = 0;
        for seg in &self.segs {
            match seg.col(field) {
                Some(Column::Numeric(n)) => missing += n.null_bitmap.len(),
                Some(Column::Keyword(k)) => missing += k.null_bitmap.len(),
                // Complement of `exists`: the bitmap is `value_present`.
                Some(Column::Presence(p)) => {
                    if p.doc_count != seg.docs {
                        return None;
                    }
                    missing += (seg.docs as u64).saturating_sub(p.count());
                }
                // Field absent from this segment's columns → every row missing.
                None => missing += seg.docs as u64,
            }
        }
        for doc in self.mem().iter() {
            if get_nested_field(doc, field).is_null() {
                missing += 1;
            }
        }
        Some(json!({ "doc_count": missing }))
    }

    /// `median_absolute_deviation` — `median(|x_i − median(x)|)`.  XERJ's brute
    /// path is EXACT (sort + positional median), not ES's TDigest, so the
    /// columnar value equals brute byte-for-byte and differs from ES only by
    /// the TDigest approximation error (same accepted divergence as
    /// `percentiles`).  The sorted column (`gather_numeric_sorted`) gives the
    /// first median for free; the abs-deviations need one O(N) map + an
    /// `select_nth_unstable` (same positional order-statistics the brute full
    /// sort would land on).  `compression` (a TDigest knob) is tolerated and
    /// ignored since we are exact; `missing` / `format` change value gathering
    /// so they bail to brute (not in the whitelist).
    fn exec_median_absolute_deviation(&self, params: &Value) -> Option<Value> {
        if !params_only(params, &["field", "compression"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        let nums = self.gather_numeric_sorted(field)?;
        if nums.is_empty() {
            return Some(json!({ "value": Value::Null }));
        }
        let n = nums.len();
        let median = if n % 2 == 0 {
            (nums[n / 2 - 1] + nums[n / 2]) / 2.0
        } else {
            nums[n / 2]
        };
        let mut dev: Vec<f64> = nums.iter().map(|x| (x - median).abs()).collect();
        let cmp = |a: &f64, b: &f64| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal);
        let m = dev.len();
        let mad = if m.is_multiple_of(2) {
            // `select_nth_unstable_by(m/2)` places the (m/2)-th order statistic
            // at `m/2` and leaves everything before it ≤ it, so the low middle
            // is the max of that left partition — exactly the two positions a
            // full sort would read.
            let hi = {
                let (_, p, _) = dev.select_nth_unstable_by(m / 2, cmp);
                *p
            };
            let lo = dev[..m / 2]
                .iter()
                .copied()
                .fold(f64::NEG_INFINITY, f64::max);
            (lo + hi) / 2.0
        } else {
            let (_, p, _) = dev.select_nth_unstable_by(m / 2, cmp);
            *p
        };
        Some(json!({ "value": mad }))
    }

    /// `matrix_stats` — single columnar pass gathering, per doc where EVERY
    /// requested field is present, a value vector straight from the numeric
    /// `.dv` columns, then the identical count/mean/variance/skewness/kurtosis
    /// plus pairwise covariance/correlation reduction as brute
    /// (`matrix_stats_from_rows`, shared).  Only the plain `{fields}` form is
    /// served; `mode` (multi-value collapse), `missing` (per-field default) and
    /// the `__xy_f32_fields__` sentinel (float-precision round-trip, injected by
    /// the REST layer only when a `type: float` field is involved) all change
    /// value gathering, so their presence bails to the exact brute reducer.
    fn exec_matrix_stats(&self, params: &Value) -> Option<Value> {
        if !params_only(params, &["fields"]) {
            return None;
        }
        let fields: Vec<String> = params
            .get("fields")
            .and_then(Value::as_array)
            .map(|a| {
                a.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();
        if fields.is_empty() {
            return Some(json!({ "doc_count": 0, "fields": [] }));
        }
        // Every field must be a scalar numeric doc-value column everywhere
        // (keyword / mixed / non-numeric memtable value → bail to brute).
        for f in &fields {
            match self.seg_field_kind(f) {
                Ok(Some(ColKind::Numeric)) | Ok(None) => {}
                _ => return None,
            }
            if !self.mem_field_numeric_safe(f) {
                return None;
            }
        }
        let k = fields.len();
        let mut rows: Vec<Vec<f64>> = Vec::new();
        // Memtable docs first (brute-parity scalar extraction); a doc is
        // included only when every field resolves to a number.
        for doc in self.mem().iter() {
            let mut row = Vec::with_capacity(k);
            let mut valid = true;
            for f in &fields {
                match extract_numeric(doc, f) {
                    Some(v) => row.push(v),
                    None => {
                        valid = false;
                        break;
                    }
                }
            }
            if valid {
                rows.push(row);
            }
        }
        // Segment rows — join the fields' columns by row id.  If any field's
        // column is absent for the whole segment, no row there can be valid.
        for seg in &self.segs {
            let mut cols: Vec<&NumericColumn> = Vec::with_capacity(k);
            let mut all_present = true;
            for f in &fields {
                match seg.col(f) {
                    Some(Column::Numeric(n)) => cols.push(n),
                    _ => {
                        all_present = false;
                        break;
                    }
                }
            }
            if !all_present {
                continue;
            }
            for row_id in 0..seg.docs {
                let mut row = Vec::with_capacity(k);
                let mut valid = true;
                for n in &cols {
                    // `NumericColumn` stores f64 BITS — decode before use.
                    match n.get(row_id) {
                        Some(bits) => row.push(f64::from_bits(bits as u64)),
                        None => {
                            valid = false;
                            break;
                        }
                    }
                }
                if valid {
                    rows.push(row);
                }
            }
        }
        // Reduction is permutation-invariant up to float ULPs, so the
        // memtable-first row order (vs brute corpus order) only moves the
        // result within the documented summation-order tolerance.
        Some(matrix_stats_from_rows(fields, rows))
    }

    /// `auto_date_histogram` — compute the date column's min/max columnar, pick
    /// the same rounding interval as brute (`auto_date_pick_interval` — the ES
    /// sec/min/hour/day/month/year ladder), then bucket via the EXISTING
    /// columnar `exec_date_histogram` with that fixed interval and annotate the
    /// chosen `interval`.  Byte-identical to brute `run_auto_date_histogram`
    /// (which delegates to `run_date_histogram` the same way) for every case it
    /// serves.  Only `{field, buckets}` is accepted.  Multi-unit intervals
    /// (`3h`/`12h`/`5m`/…/`7d`/`30d`/`90d`) carry the ES min-doc-anchored grid
    /// `offset` (`auto_date_offset_ms`), which the columnar
    /// `exec_date_histogram` applies on its fixed-interval grid.
    fn exec_auto_date_histogram(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(params, &["field", "buckets"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        match self.seg_field_kind(field) {
            // Keyword = ISO-string date column; Numeric = epoch-ms column.
            Ok(Some(ColKind::Keyword)) | Ok(Some(ColKind::Numeric)) | Ok(None) => {}
            _ => return None,
        }
        let target_buckets = params.get("buckets").and_then(Value::as_u64).unwrap_or(10) as usize;

        // Columnar min/max of the parsed date, mirroring the brute
        // `parse_date_ms(get_nested_field(...))` collection.
        let mut min_ts = i64::MAX;
        let mut max_ts = i64::MIN;
        let mut any = false;
        for seg in &self.segs {
            match seg.col(field) {
                Some(Column::Numeric(n)) => {
                    if n.live_count > 0 {
                        // f64::from_bits epoch-ms; exact as i64 (< 2^53).
                        let lo = n.live_min as i64;
                        let hi = n.live_max as i64;
                        if lo < min_ts {
                            min_ts = lo;
                        }
                        if hi > max_ts {
                            max_ts = hi;
                        }
                        any = true;
                    }
                }
                Some(Column::Presence(_)) => return None,
                Some(Column::Keyword(k)) => {
                    let ord_ms = self.date_ord_index(seg, field)?;
                    for (ord, &ms) in ord_ms.iter().enumerate() {
                        if ms == i64::MIN || k.per_ord_count.get(ord).copied().unwrap_or(0) == 0 {
                            continue;
                        }
                        if ms < min_ts {
                            min_ts = ms;
                        }
                        if ms > max_ts {
                            max_ts = ms;
                        }
                        any = true;
                    }
                }
                None => {}
            }
        }
        for doc in self.mem().iter() {
            if let Some(ms) = parse_date_ms(get_nested_field(doc, field)) {
                if ms < min_ts {
                    min_ts = ms;
                }
                if ms > max_ts {
                    max_ts = ms;
                }
                any = true;
            }
        }
        if !any {
            // No parseable dates — brute returns this exact empty shape.
            return Some(json!({ "buckets": [], "interval": "1d" }));
        }

        let (interval_label, interval_ms) = auto_date_pick_interval(min_ts, max_ts, target_buckets);
        // Multi-unit intervals (3h/12h/5m/…/7d/30d/90d) carry the ES
        // min-doc-anchored grid offset (see `auto_date_offset_ms`); pass it to
        // the columnar date_histogram exactly like the brute path does.
        let offset_ms = auto_date_offset_ms(interval_label, interval_ms, min_ts);
        let mut synth = json!({ "field": field, "fixed_interval": interval_label });
        if offset_ms != 0 {
            synth
                .as_object_mut()
                .unwrap()
                .insert("offset".to_string(), json!(format!("+{}ms", offset_ms)));
        }
        let mut result = self.exec_date_histogram(&synth, sub)?;
        if let Some(obj) = result.as_object_mut() {
            obj.insert("interval".to_string(), json!(interval_label));
        }
        Some(result)
    }

    // ── shared fused row pass ────────────────────────────────────────────
    //
    // For a parent that assigns each segment row to at most one bucket slot
    // (terms ord → slot, date_histogram ord → slot, …), fold every metric
    // sub-agg and the optional top_hits accumulator in a single pass.

    #[allow(clippy::too_many_arguments)]
    fn fused_seg_pass(
        &self,
        si: usize,
        slot_of_row: &mut dyn FnMut(u32) -> Option<usize>,
        n_slots: usize,
        plan: &SubPlan,
        accs: &mut [Vec<MetricAcc>],
        tops: &mut [Vec<(f64, u64, DocRef)>],
        missing_sort_seen: &mut bool,
    ) -> Option<()> {
        let seg = &self.segs[si];
        // Top-level query filter: resolve its columnar predicate for this
        // segment ONCE (bail the whole fast path if it can't be resolved —
        // e.g. field-kind mismatch — so the caller uses the brute path).
        // Rows that don't match are skipped before any bucket assignment, so
        // every fused-pass consumer (terms, filtered metric) reduces over
        // exactly the matching doc set.
        let top_sp: Option<SegPred> = match &self.top_filter {
            Some(pred) => Some(resolve_pred(
                &seg.cols,
                pred,
                &self.segs,
                self.mapped_fields,
            )?),
            None => None,
        };
        // A terms window that names no ordinal in this segment resolves to
        // `Never` before any row is visited. Zero-hit finalize probes stop
        // here instead of walking the segment.
        if matches!(top_sp, Some(SegPred::Never)) {
            return Some(());
        }
        // Resolve metric columns once.
        let mut num_cols: Vec<Option<&NumericColumn>> = Vec::with_capacity(plan.metrics.len());
        let mut kw_cols: Vec<Option<&KeywordColumn>> = Vec::with_capacity(plan.metrics.len());
        for m in &plan.metrics {
            match seg.col(&m.field) {
                Some(Column::Numeric(n)) => {
                    num_cols.push(Some(n));
                    kw_cols.push(None);
                }
                Some(Column::Keyword(k)) => {
                    if m.kind != MetricKind::ValueCount {
                        return None;
                    }
                    num_cols.push(None);
                    kw_cols.push(Some(k));
                }
                Some(Column::Presence(_)) => return None,
                None => {
                    num_cols.push(None);
                    kw_cols.push(None);
                }
            }
        }
        let th_col: Option<&NumericColumn> = match &plan.top_hits {
            Some(spec) => match seg.col(&spec.sort_field) {
                Some(Column::Numeric(n)) => Some(n),
                Some(_) => return None,
                None => None,
            },
            None => None,
        };
        let rank_off = self.seg_rank_offset(si);
        debug_assert!(accs.len() == plan.metrics.len());
        let _ = n_slots;

        // Hoist the RoaringBitmap null probes: dense columns (no nulls —
        // the steady state for telemetry-style corpora) skip the per-row
        // `contains()` entirely, which otherwise dominates this loop.
        let dense_num: Vec<bool> = num_cols
            .iter()
            .map(|c| c.is_some_and(|n| n.null_bitmap.is_empty()))
            .collect();
        let dense_kw: Vec<bool> = kw_cols
            .iter()
            .map(|c| c.is_some_and(|k| k.null_bitmap.is_empty()))
            .collect();
        let th_dense = th_col.is_some_and(|n| n.null_bitmap.is_empty());

        // [#1267] Ghosted rows (deleted/superseded but still resident) are
        // skipped before ANY accounting — present only on dirty-but-admitted
        // segments (the row-exact plan), where counting them would
        // double-count docs the brute path no longer sees.  Hoisted beside
        // the null probes: clean segments pay one `Option` check.
        let seg_ghosts = seg.ghosts.as_deref();

        for row in 0..seg.docs {
            if let Some(g) = seg_ghosts {
                if ghost_bit(g, row) {
                    continue;
                }
            }
            if let Some(sp) = &top_sp {
                if !seg_pred_matches(sp, row) {
                    continue;
                }
            }
            let Some(slot) = slot_of_row(row) else {
                continue;
            };
            for (mi, m) in plan.metrics.iter().enumerate() {
                match m.kind {
                    MetricKind::ValueCount => {
                        let present = if let Some(n) = num_cols[mi] {
                            dense_num[mi] || !n.null_bitmap.contains(row)
                        } else if let Some(k) = kw_cols[mi] {
                            dense_kw[mi] || !k.null_bitmap.contains(row)
                        } else {
                            false
                        };
                        if present {
                            accs[mi][slot].add_presence();
                        }
                    }
                    _ => {
                        if let Some(n) = num_cols[mi] {
                            if dense_num[mi] || !n.null_bitmap.contains(row) {
                                let v = f64::from_bits(n.data[row as usize] as u64);
                                accs[mi][slot].add(v);
                            }
                        }
                    }
                }
            }
            if let Some(spec) = &plan.top_hits {
                let v = match th_col {
                    Some(n) if th_dense || !n.null_bitmap.contains(row) => {
                        f64::from_bits(n.data[row as usize] as u64)
                    }
                    _ => {
                        *missing_sort_seen = true;
                        continue;
                    }
                };
                push_top(
                    &mut tops[slot],
                    spec.k,
                    spec.desc,
                    v,
                    rank_off + row as u64,
                    DocRef::Seg(si, row),
                );
            }
        }
        Some(())
    }

    /// Materialise + render a bucket's top_hits from its winner set.
    fn render_top_hits(
        &self,
        spec: &TopHitsSpec,
        winners: &[(f64, u64, DocRef)],
        bucket_total: u64,
    ) -> Option<Value> {
        let mut sorted: Vec<(f64, u64, DocRef)> = winners.to_vec();
        sort_top(&mut sorted, spec.desc);
        let docs: Vec<Value> = sorted
            .iter()
            .map(|(_, _, r)| self.fetch_doc(*r))
            .collect::<Option<Vec<_>>>()?;
        Some(run_top_hits_with_total(
            &spec.params,
            &docs,
            Some(bucket_total),
        ))
    }

    // ── terms ────────────────────────────────────────────────────────────

    /// `cardinality` — exact distinct count from the keyword term
    /// dictionaries, matching the brute path bit-for-bit (xerj's
    /// cardinality is exact, not HLL — see aggs.rs `run_cardinality`).
    ///
    /// Pre-fix `cardinality` was NOT on the fast path, so every uncached
    /// `size:0 + match_all + cardinality` request fell into the
    /// `need_full_corpus` branch of `search_inner`: decompress + JSON-parse
    /// EVERY stored doc in the index (~22 s at 3.5 M docs).  Steady-state
    /// dashboards never noticed because the query cache absorbed it, but a
    /// background bulk writer bumps `dataset_version` on every batch — 100 %
    /// cache misses — and cardinality became the single biggest CPU bomb in
    /// the read-under-write collapse.
    ///
    /// Keyword-shaped columns only (plus schema-boolean 0/1 numerics):
    /// numeric distinct values can't be re-rendered into the brute path's
    /// string keys without risking formatting drift → bail to brute.
    fn exec_cardinality(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        // `precision_threshold` is accepted-and-ignored by the brute path
        // (exact count regardless), so accepting it here is bit-identical.
        if !params_only(params, &["field", "missing", "precision_threshold"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        // Exact-name schema lookup, deliberately (#120): `<bool>.keyword`
        // resolves its column through `dv_col`'s parent fallback but is NOT
        // in `bool_fields`, so `is_bool` is false and the `Numeric` arm below
        // does not match — the request bails to brute. That is a missed
        // optimisation, not a wrong answer: the keys can only be rendered
        // "false"/"true" on the arm this gate refuses to take. Normalising
        // the name here would ADD the wrong-rendering risk, not remove it.
        let is_bool = self.bool_fields.contains(field);
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Keyword)) | Ok(None) => {}
            Ok(Some(ColKind::Numeric)) if is_bool => {}
            _ => return None,
        }
        // Same `missing` placeholder semantics as `run_cardinality`.
        let missing_placeholder: Option<String> = params.get("missing").and_then(|v| match v {
            Value::String(s) => Some(s.clone()),
            Value::Number(n) => Some(n.to_string()),
            Value::Bool(b) => Some(b.to_string()),
            _ => None,
        });

        let mut distinct: std::collections::HashSet<String> = std::collections::HashSet::new();
        const BOOL_TERMS: [&str; 2] = ["false", "true"];
        // Under a top-level query filter the distinct set must cover ONLY the
        // matching docs — the whole-segment `per_ord_count` shortcut (which
        // sees every doc) is valid only for the unfiltered path. The empty
        // plan drives `fused_seg_pass` purely for its columnar filter gate;
        // `slot_of_row` records which term-ords appear among matching rows.
        // This is what stops a `{size:0, query:range, cardinality}` from
        // bailing the whole request to the O(N) brute `_source` hydrate
        // (~1.2 s on a 600 k-doc unflushed memtable) — the mixed-read tail.
        let filtered = self.top_filter.is_some();
        let empty_plan = if filtered {
            Some(self.plan_subs(None, false)?)
        } else {
            None
        };
        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            if !filtered {
                // ── Unfiltered: whole-segment term-dictionary scan (fast) ──
                match seg.col(field) {
                    Some(Column::Keyword(k)) => {
                        for (ord, &cnt) in k.per_ord_count.iter().enumerate() {
                            if cnt > 0 {
                                distinct.insert(k.terms[ord].clone());
                            }
                        }
                        if let Some(ph) = &missing_placeholder {
                            if !k.null_bitmap.is_empty() {
                                distinct.insert(ph.clone());
                            }
                        }
                    }
                    Some(Column::Numeric(n)) if is_bool => {
                        // Same 0/1 purity check as exec_terms: stray numbers
                        // would render as "0"/"2.5" on the brute path → bail.
                        let zeros = n.range_count(0.0, 0.0, true, true);
                        let ones = n.range_count(1.0, 1.0, true, true);
                        if zeros + ones != n.live_count {
                            return None;
                        }
                        if zeros > 0 {
                            distinct.insert(BOOL_TERMS[0].to_string());
                        }
                        if ones > 0 {
                            distinct.insert(BOOL_TERMS[1].to_string());
                        }
                        if let Some(ph) = &missing_placeholder {
                            if !n.null_bitmap.is_empty() {
                                distinct.insert(ph.clone());
                            }
                        }
                    }
                    Some(_) => return None,
                    None => {
                        // Field absent from the whole segment: every doc counts
                        // as missing (brute: empty vals → placeholder).
                        if let Some(ph) = &missing_placeholder {
                            if seg.docs > 0 {
                                distinct.insert(ph.clone());
                            }
                        }
                    }
                }
                continue;
            }
            // ── Filtered: per-row pass, distinct over matching rows only ──
            let plan = empty_plan.as_ref().unwrap();
            let mut mss = false;
            match seg.col(field) {
                Some(Column::Keyword(k)) => {
                    let mut seen = vec![false; k.terms.len()];
                    let mut saw_missing = false;
                    {
                        let dense = k.null_bitmap.is_empty();
                        let mut slot_of_row = |row: u32| -> Option<usize> {
                            let ord = if dense {
                                *k.ords.get(row as usize)? as usize
                            } else {
                                match k.ord_for(row) {
                                    Some(o) => o as usize,
                                    None => {
                                        saw_missing = true;
                                        return None;
                                    }
                                }
                            };
                            seen[ord] = true;
                            Some(ord)
                        };
                        self.fused_seg_pass(
                            si,
                            &mut slot_of_row,
                            k.terms.len(),
                            plan,
                            &mut [],
                            &mut [],
                            &mut mss,
                        )?;
                    }
                    for (ord, &s) in seen.iter().enumerate() {
                        if s {
                            distinct.insert(k.terms[ord].clone());
                        }
                    }
                    if saw_missing {
                        if let Some(ph) = &missing_placeholder {
                            distinct.insert(ph.clone());
                        }
                    }
                }
                Some(Column::Numeric(n)) if is_bool => {
                    let zeros = n.range_count(0.0, 0.0, true, true);
                    let ones = n.range_count(1.0, 1.0, true, true);
                    if zeros + ones != n.live_count {
                        return None;
                    }
                    let mut seen_bool = [false, false];
                    let mut saw_missing = false;
                    {
                        let dense = n.null_bitmap.is_empty();
                        let mut slot_of_row = |row: u32| -> Option<usize> {
                            let bits = if dense {
                                *n.data.get(row as usize)?
                            } else {
                                match n.get(row) {
                                    Some(b) => b,
                                    None => {
                                        saw_missing = true;
                                        return None;
                                    }
                                }
                            };
                            let idx = usize::from(f64::from_bits(bits as u64) != 0.0);
                            seen_bool[idx] = true;
                            Some(idx)
                        };
                        self.fused_seg_pass(
                            si,
                            &mut slot_of_row,
                            2,
                            plan,
                            &mut [],
                            &mut [],
                            &mut mss,
                        )?;
                    }
                    if seen_bool[0] {
                        distinct.insert(BOOL_TERMS[0].to_string());
                    }
                    if seen_bool[1] {
                        distinct.insert(BOOL_TERMS[1].to_string());
                    }
                    if saw_missing {
                        if let Some(ph) = &missing_placeholder {
                            distinct.insert(ph.clone());
                        }
                    }
                }
                Some(_) => return None,
                None => {
                    // Field absent from this segment → every matching row is
                    // "missing"; only need whether ≥1 row matches the filter.
                    if let Some(ph) = &missing_placeholder {
                        let mut any = false;
                        {
                            let mut slot_of_row = |_row: u32| -> Option<usize> {
                                any = true;
                                None
                            };
                            self.fused_seg_pass(
                                si,
                                &mut slot_of_row,
                                0,
                                plan,
                                &mut [],
                                &mut [],
                                &mut mss,
                            )?;
                        }
                        if any {
                            distinct.insert(ph.clone());
                        }
                    }
                }
            }
        }
        // ── Memtable docs ─────────────────────────────────────────────────
        if filtered {
            // Distinct over MATCHING memtable docs only. O(matching) columnar
            // candidates when the filter columnarises (re-checked against the
            // JSON matcher for byte-identical results); else the full walk
            // gated by `doc_matches_filter`.
            let cols = match (self.filtered_mem(), self.top_filter_query.as_ref()) {
                (Some(fdocs), Some(q)) => Some((fdocs, q)),
                _ => None,
            };
            if let Some((fdocs, q)) = cols {
                for (_id, doc) in fdocs {
                    if !doc_matches_filter(doc, q) {
                        continue;
                    }
                    let vals = extract_field_values(doc, field);
                    if vals.is_empty() {
                        if let Some(ph) = &missing_placeholder {
                            distinct.insert(ph.clone());
                        }
                    } else {
                        for v in vals {
                            distinct.insert(v);
                        }
                    }
                }
            } else {
                for doc in self.mem().iter() {
                    if let Some(q) = &self.top_filter_query {
                        if !doc_matches_filter(doc, q) {
                            continue;
                        }
                    }
                    let vals = extract_field_values(doc, field);
                    if vals.is_empty() {
                        if let Some(ph) = &missing_placeholder {
                            distinct.insert(ph.clone());
                        }
                    } else {
                        for v in vals {
                            distinct.insert(v);
                        }
                    }
                }
            }
        } else {
            // Unfiltered memtable.  Columnar fast arm first (same equivalence
            // gates as exec_terms — see `terms_counts_columnar`); the per-doc
            // extraction walk below was the cardinality read-under-write tail
            // at a drain-lagged memtable.
            let mem_columnar: Option<(std::collections::HashMap<String, u64>, u64)> =
                if self.mem_live_gate.is_none() && !field.contains('.') {
                    // [#1260] the memtable columnar summary is delete-blind;
                    // under the admission gate the exact per-doc walk below
                    // (over the live-only `mem()` view) serves instead.
                    self.idx.memtable.terms_counts_columnar(field)
                } else {
                    None
                };
            match mem_columnar {
                Some((counts, missing)) => {
                    for (term, cnt) in counts {
                        if cnt > 0 {
                            distinct.insert(term);
                        }
                    }
                    if missing > 0 {
                        if let Some(ph) = &missing_placeholder {
                            distinct.insert(ph.clone());
                        }
                    }
                }
                None => {
                    // Exact brute extractor so string rendering is identical.
                    for d in self.mem().iter() {
                        let vals = crate::aggs::extract_field_values(d, field);
                        if vals.is_empty() {
                            if let Some(ph) = &missing_placeholder {
                                distinct.insert(ph.clone());
                            }
                            continue;
                        }
                        for v in vals {
                            distinct.insert(v);
                        }
                    }
                }
            }
        }

        // Identical output shape to `run_cardinality` including the
        // internal `__xy_*` fields the cross-index merge consumes.
        let values: Vec<Value> = distinct.iter().map(|s| Value::String(s.clone())).collect();
        Some(json!({
            "value": distinct.len(),
            "__xy_agg__": "cardinality",
            "__xy_values__": values,
        }))
    }

    fn exec_terms(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(
            params,
            &["field", "size", "order", "shard_size", "min_doc_count"],
        ) {
            return None;
        }
        // Brute default & only supported min_doc_count is 1 (0 needs the
        // background corpus, >1 is honored below since it's a plain filter).
        let min_doc_count = params
            .get("min_doc_count")
            .and_then(Value::as_u64)
            .unwrap_or(1);
        if params.get("min_doc_count").is_some() && min_doc_count == 0 {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        // Boolean-mapped fields land in numeric 0/1 columns; the schema is
        // what licenses rendering them back as "false"/"true" term keys
        // (`typed_term_key` then emits key 0/1 + key_as_string, exactly
        // like the brute path does for `Value::Bool`).
        //
        // The lookup is by EXACT name on purpose (#120): a bool field asked
        // for as `<field>.keyword` resolves its numeric column via `dv_col`
        // but is absent from `bool_fields`, so `is_bool` is false, the
        // `Numeric` arm below does not match, and the request bails to
        // brute. Slower, never wrong — the "keys render as strings" failure
        // needs the arm this gate refuses.
        let is_bool = self.bool_fields.contains(field);
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Keyword)) | Ok(None) => {}
            Ok(Some(ColKind::Numeric)) if is_bool => {}
            _ => return None, // numeric terms keys → typed-key subtleties, bail
        }
        // Orders: only _count/_key entries supported (sub-agg ordering needs
        // the per-bucket sub results *before* truncation — brute-only).
        let orders = parse_orders(params);
        if orders.iter().any(|(k, _)| k != "_count" && k != "_key") {
            return None;
        }
        let size_opt: Option<usize> = params
            .get("size")
            .and_then(Value::as_u64)
            .map(|v| v as usize);
        let cap: Option<usize> = match size_opt {
            Some(0) => None,
            Some(n) => Some(n),
            None => Some(10),
        };
        // `search.max_buckets` (issue #121). `size`/`cap` above only trims the
        // OUTPUT; the term MAP itself was previously unbounded, so a terms agg
        // over a high-cardinality field materialised every distinct term on the
        // columnar path while the brute `run_terms` stopped at `max_buckets` —
        // the exact OOM vector the cap exists to close, honoured on brute and
        // ignored here.
        //
        // We do NOT enforce the cap by truncating the map: brute drops the
        // terms past `max_buckets` in doc-iteration order and reports a
        // `sum_other_doc_count` computed only over the terms it kept, so the
        // dropped terms vanish silently (order-dependent, and the total
        // conceals them). Reproducing that on the fast path would copy the bug,
        // not the contract. Instead we BAIL to brute the moment the distinct
        // count would exceed the cap (checked below as the map grows, so the
        // map is bounded to ~`bucket_cap`): after the bail the request is
        // answered by the very `run_terms` a test would measure the fast path
        // against, so the two paths AGREE past the cap by construction — the
        // same shape as the #104 / #120 bail-to-brute fallbacks. An index whose
        // distinct count is at or under the cap is served here as before.
        let bucket_cap = crate::aggs::max_buckets();

        let plan = self.plan_subs(sub, true)?;
        // A top-level query filter forces the per-row pass (the `!has_row_work`
        // segment shortcut reads whole-segment `per_ord_count`, which ignores
        // the filter).  `fused_seg_pass` then gates rows by the filter, and
        // the memtable arm below matches each doc against it.
        let has_row_work =
            !plan.metrics.is_empty() || plan.top_hits.is_some() || self.top_filter.is_some();

        // Global per-term state.
        struct TermState {
            count: u64,
            accs: Vec<MetricAcc>,
            top: Vec<(f64, u64, DocRef)>,
        }
        let mut terms_map: HashMap<String, TermState> = HashMap::new();
        let new_state = |plan: &SubPlan| TermState {
            count: 0,
            accs: vec![MetricAcc::default(); plan.metrics.len()],
            top: Vec::new(),
        };
        let mut missing_sort_seen = false;

        // Per-segment term column view: keyword ords, or a boolean numeric
        // column exposed as the two-term dictionary ["false", "true"].
        enum TCol<'x> {
            Kw(&'x KeywordColumn),
            Bool(&'x NumericColumn),
        }
        const BOOL_TERMS: [&str; 2] = ["false", "true"];

        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            let Some(col) = seg.col(field) else {
                continue;
            };
            let tcol = match col {
                Column::Keyword(k) => TCol::Kw(k),
                Column::Numeric(n) if is_bool => {
                    // Sanity: the column must be pure 0/1 (a mapping change
                    // could have let stray numbers in — brute would render
                    // those as "0"/"1"/"2.5", not booleans → bail).
                    let zeros = n.range_count(0.0, 0.0, true, true);
                    let ones = n.range_count(1.0, 1.0, true, true);
                    if zeros + ones != n.live_count {
                        return None;
                    }
                    TCol::Bool(n)
                }
                _ => return None,
            };
            if !has_row_work {
                match &tcol {
                    TCol::Kw(k) => {
                        for (ord, &cnt) in k.per_ord_count.iter().enumerate() {
                            if cnt > 0 {
                                terms_map
                                    .entry(k.terms[ord].clone())
                                    .or_insert_with(|| new_state(&plan))
                                    .count += cnt as u64;
                            }
                        }
                    }
                    TCol::Bool(n) => {
                        for (ord, term) in BOOL_TERMS.iter().enumerate() {
                            let v = ord as f64;
                            let cnt = n.range_count(v, v, true, true);
                            if cnt > 0 {
                                terms_map
                                    .entry((*term).to_string())
                                    .or_insert_with(|| new_state(&plan))
                                    .count += cnt;
                            }
                        }
                    }
                }
                // Over `search.max_buckets` distinct terms → bail to brute (see
                // the `bucket_cap` note above). Checked per segment so the map
                // never grows more than one segment's dictionary past the cap.
                if terms_map.len() > bucket_cap {
                    return None;
                }
                continue;
            }
            // Row pass: per-ord local accumulators, then merged by term.
            let n_ords = match &tcol {
                TCol::Kw(k) => k.terms.len(),
                TCol::Bool(_) => 2,
            };
            let term_of_ord = |ord: usize| -> &str {
                match &tcol {
                    TCol::Kw(k) => k.terms[ord].as_str(),
                    TCol::Bool(_) => BOOL_TERMS[ord],
                }
            };
            let mut accs: Vec<Vec<MetricAcc>> = plan
                .metrics
                .iter()
                .map(|_| vec![MetricAcc::default(); n_ords])
                .collect();
            let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new(); n_ords];
            let mut counts: Vec<u64> = vec![0; n_ords];
            {
                // Dense term column (no nulls) → skip the per-row roaring
                // `contains()` inside `ord_for`/`get` and read the raw
                // ordinal/value arrays directly.
                let tcol_dense = match &tcol {
                    TCol::Kw(k) => k.null_bitmap.is_empty(),
                    TCol::Bool(n) => n.null_bitmap.is_empty(),
                };
                let mut slot_of_row = |row: u32| -> Option<usize> {
                    let ord = match &tcol {
                        TCol::Kw(k) => {
                            if tcol_dense {
                                *k.ords.get(row as usize)? as usize
                            } else {
                                k.ord_for(row)? as usize
                            }
                        }
                        TCol::Bool(n) => {
                            let bits = if tcol_dense {
                                *n.data.get(row as usize)?
                            } else {
                                n.get(row)?
                            };
                            usize::from(f64::from_bits(bits as u64) != 0.0)
                        }
                    };
                    counts[ord] += 1;
                    Some(ord)
                };
                self.fused_seg_pass(
                    si,
                    &mut slot_of_row,
                    n_ords,
                    &plan,
                    &mut accs,
                    &mut tops,
                    &mut missing_sort_seen,
                )?;
            }
            for ord in 0..n_ords {
                if counts[ord] == 0 {
                    continue;
                }
                let st = terms_map
                    .entry(term_of_ord(ord).to_string())
                    .or_insert_with(|| new_state(&plan));
                st.count += counts[ord];
                for (mi, acc) in st.accs.iter_mut().enumerate() {
                    merge_acc(acc, &accs[mi][ord]);
                }
                if let Some(spec) = &plan.top_hits {
                    for e in tops[ord].drain(..) {
                        push_top(&mut st.top, spec.k, spec.desc, e.0, e.1, e.2);
                    }
                }
            }
            // Same cap bail as the `!has_row_work` arm above, after this
            // segment's terms have merged in.
            if terms_map.len() > bucket_cap {
                return None;
            }
        }

        // Memtable docs.  Columnar fast arm first: when the shape is
        // provably brute-equivalent (no per-row sub-agg work, plain
        // un-dotted field, no array values ever seen for it, no
        // `_doc_count` weights — see `terms_counts_columnar`), count from
        // the keyword column directly.  The per-doc JSON extraction walk
        // below cost 100-300 ms/query against a drain-lagged 300 k-doc
        // memtable under a sustained bulk writer — the terms-agg
        // read-under-write p95/p99 tail.
        let mem_columnar: Option<(std::collections::HashMap<String, u64>, u64)> =
            if self.mem_live_gate.is_none() && !has_row_work && !field.contains('.') {
                // [#1260] delete-blind summary — under the admission gate the
                // exact walks below (live-only views) serve instead.
                self.idx.memtable.terms_counts_columnar(field)
            } else {
                None
            };
        match mem_columnar {
            Some((counts, _missing)) => {
                for (term, cnt) in counts {
                    if cnt > 0 {
                        terms_map
                            .entry(term)
                            .or_insert_with(|| new_state(&plan))
                            .count += cnt;
                    }
                }
            }
            None => {
                // O(matching) columnar fold: when the top filter columnarises
                // AND no meta-observing sub-agg is present (`filtered_mem` is
                // Some ⇒ `needs_owned_mem` false ⇒ `plan.top_hits` is None, so
                // the positional `DocRef::Mem` path is unreachable here), fold
                // only the columnar-matched candidates — re-checked against the
                // JSON matcher for byte-identical results.  Otherwise the full
                // `mem()` walk (brute extractor semantics; multi-value, weights,
                // top_hits) exactly as before.
                let columnar = match (self.filtered_mem(), self.top_filter_query.as_ref()) {
                    (Some(fdocs), Some(q)) if plan.top_hits.is_none() => Some((fdocs, q)),
                    _ => None,
                };
                if let Some((fdocs, q)) = columnar {
                    for (_id, doc) in fdocs {
                        if !doc_matches_filter(doc, q) {
                            continue;
                        }
                        let weight = doc_count_weight(doc);
                        let vals = extract_field_values(doc, field);
                        for term in vals {
                            let st = terms_map.entry(term).or_insert_with(|| new_state(&plan));
                            st.count += weight;
                            for (mi, spec) in plan.metrics.iter().enumerate() {
                                Self::fold_mem_metric(doc, spec, &mut st.accs[mi]);
                            }
                        }
                    }
                } else {
                    for (di, doc) in self.mem().iter().enumerate() {
                        // Top-level query filter: skip non-matching memtable docs
                        // (segment rows are already gated inside `fused_seg_pass`).
                        if let Some(q) = &self.top_filter_query {
                            if !doc_matches_filter(doc, q) {
                                continue;
                            }
                        }
                        let weight = doc_count_weight(doc);
                        let vals = extract_field_values(doc, field);
                        for term in vals {
                            let st = terms_map.entry(term).or_insert_with(|| new_state(&plan));
                            st.count += weight;
                            for (mi, spec) in plan.metrics.iter().enumerate() {
                                Self::fold_mem_metric(doc, spec, &mut st.accs[mi]);
                            }
                            if let Some(spec) = &plan.top_hits {
                                match extract_numeric(doc, &spec.sort_field) {
                                    Some(v) => push_top(
                                        &mut st.top,
                                        spec.k,
                                        spec.desc,
                                        v,
                                        di as u64,
                                        DocRef::Mem(di),
                                    ),
                                    None => missing_sort_seen = true,
                                }
                            }
                        }
                    }
                }
            }
        }

        // Final cap check: the memtable may have introduced terms absent from
        // every segment. Past `search.max_buckets` distinct terms, bail to
        // brute (see the `bucket_cap` note above) rather than returning a
        // fast-path answer the brute cap would never have produced.
        if terms_map.len() > bucket_cap {
            return None;
        }

        if plan.top_hits.is_some() && missing_sort_seen {
            // A bucket doc without the sort value would need brute
            // missing-last + _id tie-breaking — bail for exactness.
            return None;
        }

        // Order + truncate, mirroring run_terms' default and _count/_key
        // orders (cmp_terms_by_orders with no sub-agg references).
        //
        // The min_doc_count filter is NOT applied before the sort: ES drops
        // min_doc_count failures at final reduce, AFTER the shard-size cut.
        // `apply_terms_size_pipeline` reproduces the exact ES single-shard
        // staging (shard cut → silent min drop → size cut) and returns the
        // REAL sum_other_doc_count — byte-identical to the brute run_terms.
        let mut candidates: Vec<(String, TermState)> = terms_map.into_iter().collect();
        candidates.sort_by(|a, b| {
            cmp_by_orders(
                &(a.0.clone(), a.1.count),
                &(b.0.clone(), b.1.count),
                &orders,
            )
        });
        let shard_size_param: Option<usize> = params
            .get("shard_size")
            .and_then(Value::as_u64)
            .map(|v| v as usize);
        let (candidates, sum_other_doc_count) = crate::aggs::apply_terms_size_pipeline(
            candidates,
            |r| r.1.count,
            cap,
            shard_size_param,
            min_doc_count,
        );

        let mut buckets: Vec<Value> = Vec::with_capacity(candidates.len());
        for (key, st) in candidates {
            // #864: a keyword column's keys are strings (`is_bool` marks the
            // boolean-column case, which still renders true/false → 1/0).
            let (typed_key, key_as_string) = typed_term_key(&key, !is_bool);
            let mut bucket = Map::new();
            bucket.insert("key".to_string(), typed_key);
            if let Some(kas) = key_as_string {
                bucket.insert("key_as_string".to_string(), json!(kas));
            }
            bucket.insert("doc_count".to_string(), json!(st.count));
            let th = match &plan.top_hits {
                Some(spec) => Some(self.render_top_hits(spec, &st.top, st.count)?),
                None => None,
            };
            self.finish_bucket(&mut bucket, &plan, &st.accs, th);
            buckets.push(Value::Object(bucket));
        }
        let buckets = apply_bucket_pipeline_ops(buckets, sub);

        Some(json!({
            "doc_count_error_upper_bound": 0,
            "sum_other_doc_count": sum_other_doc_count,
            "buckets": buckets
        }))
    }

    // ── rare_terms ───────────────────────────────────────────────────────

    /// Columnar `rare_terms`: `terms` restricted to the low-frequency tail
    /// (buckets whose GLOBAL `doc_count <= max_doc_count`, default 1).
    ///
    /// Brute (`run_rare_terms`) JSON-walks every doc to build `term → doc`
    /// indices, then keeps the rare tail — O(N) (≈1 s / 100 k docs). This arm
    /// reuses the exact per-term counting of `exec_terms`' whole-segment
    /// shortcut (segments' `per_ord_count` + the memtable columnar folder), then
    /// applies the same rare filter and the same `count asc, key asc` ordering
    /// and typed-key bucket rendering the brute path uses — so the result is
    /// byte-identical, just O(distinct terms) instead of O(N).
    ///
    /// Deliberately narrow — bails (`None` → exact brute) on anything the
    /// counting/rendering can't reproduce exactly: sub-aggs (need per-bucket
    /// docs), `include`/`exclude`/`missing`/`precision` (params_only), a
    /// non-keyword field (numeric/bool/date term-key subtleties render
    /// differently), a dotted field, or a memtable shape the columnar folder
    /// can't count (arrays / `_doc_count` weights). A top-level query filter is
    /// already gated out by `exec_agg` (rare_terms is not in its allowlist).
    fn exec_rare_terms(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        if !params_only(params, &["field", "max_doc_count"]) {
            return None;
        }
        // `exec_agg` only reaches this arm when there is no top-level query
        // filter (rare_terms is not in the filtered-executor allowlist), so the
        // corpus is the whole index — matching `run_rare_terms(docs=all_docs)`.
        debug_assert!(self.top_filter.is_none());
        let field = params.get("field").and_then(Value::as_str)?;
        if field.contains('.') {
            return None;
        }
        let max_doc_count = params
            .get("max_doc_count")
            .and_then(Value::as_u64)
            .unwrap_or(1);
        // Keyword-only: a numeric/bool/date-numeric term column would render its
        // keys differently from the brute string path.
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Keyword)) | Ok(None) => {}
            _ => return None,
        }

        // Whole-corpus per-term counts (identical to `exec_terms`' `!has_row_work`
        // shortcut): segments' `per_ord_count` + the memtable columnar folder.
        let mut counts: HashMap<String, u64> = HashMap::new();
        for seg in &self.segs {
            match seg.col(field) {
                Some(Column::Keyword(k)) => {
                    for (ord, &cnt) in k.per_ord_count.iter().enumerate() {
                        // Skip empty-string values — `run_rare_terms` drops them
                        // (`extract_field_values` → `if v.is_empty() continue`).
                        if cnt > 0 && !k.terms[ord].is_empty() {
                            *counts.entry(k.terms[ord].clone()).or_default() += cnt as u64;
                        }
                    }
                }
                None => {}        // field absent in this segment → no terms
                _ => return None, // non-keyword column for a keyword field → bail
            }
        }
        // [#1260] delete-blind summary — under the admission gate this
        // executor has no exact memtable arm, so it bails whole (same as its
        // array-valued-field bailout immediately below).
        let mem_summary = if self.mem_live_gate.is_some() {
            None
        } else {
            self.idx.memtable.terms_counts_columnar(field)
        };
        match mem_summary {
            Some((mem_counts, _missing)) => {
                for (term, cnt) in mem_counts {
                    if cnt > 0 && !term.is_empty() {
                        *counts.entry(term).or_default() += cnt;
                    }
                }
            }
            // Array-valued field / `_doc_count` weights the columnar folder
            // can't reproduce → exact brute.
            None => return None,
        }

        // Rare filter + brute ordering (`count asc, key asc`, no truncation —
        // rare_terms has no `size`), mirroring `run_rare_terms`.
        let mut entries: Vec<(String, u64)> = counts
            .into_iter()
            .filter(|(_, c)| *c <= max_doc_count)
            .collect();
        entries.sort_by(|a, b| a.1.cmp(&b.1).then_with(|| a.0.cmp(&b.0)));

        let buckets: Vec<Value> = entries
            .into_iter()
            .map(|(key, count)| {
                // #864: exec_rare_terms is keyword-only (guarded above), so the
                // keys are always strings.
                let (typed_key, key_as_string) = typed_term_key(&key, true);
                let mut b = Map::new();
                b.insert("key".to_string(), typed_key);
                if let Some(kas) = key_as_string {
                    b.insert("key_as_string".to_string(), json!(kas));
                }
                b.insert("doc_count".to_string(), json!(count));
                Value::Object(b)
            })
            .collect();

        Some(json!({ "buckets": buckets }))
    }

    // ── significant_terms (degenerate no-query case only) ─────────────────

    /// Columnar `significant_terms` for the ONE case that is provably an empty
    /// result: no top-level query and no `background_filter`, so the foreground
    /// set equals the background set (the whole index). Every term then has
    /// `fg_freq == bg_freq`, so the JLH significance score is exactly `0.0` for
    /// all terms, and with the default `min_doc_count >= 2` (no threshold
    /// bypass) every term is dropped — brute (`run_significant_terms`) returns
    /// `{doc_count: N, bg_count: N, buckets: []}`. This arm returns the same in
    /// O(1)+segment-count instead of the O(N) double JSON walk (≈1 s / 100 k).
    ///
    /// Everything else bails to exact brute (`None`): a `background_filter`
    /// (foreground != background), `min_doc_count <= 1` (threshold bypass keeps
    /// score-0 terms in a HashMap-order-dependent, non-reproducible order),
    /// sub-aggs, or any param outside `field`/`size`/`min_doc_count`. A
    /// top-level query filter is already gated out by `exec_agg`
    /// (significant_terms is not in its allowlist), which is exactly what makes
    /// foreground == background here.
    fn exec_significant_terms(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        if !params_only(params, &["field", "size", "min_doc_count"]) {
            return None; // background_filter / include / exclude / … → brute
        }
        debug_assert!(self.top_filter.is_none());
        // Field must exist as a real agg field (keyword or numeric). `None`
        // (fully unmapped) still yields empty buckets in brute, but keep the arm
        // to the mapped case so `doc_count`/`bg_count` are unambiguous.
        params.get("field").and_then(Value::as_str)?;
        // Default ES `min_doc_count` is 3; only `<= 1` bypasses the score-0
        // filter (and produces non-reproducible ordering) → brute.
        let min_doc_count = params
            .get("min_doc_count")
            .and_then(Value::as_u64)
            .unwrap_or(3);
        if min_doc_count <= 1 {
            return None;
        }
        // Whole-corpus live doc count = brute's `result_docs.len()` ==
        // `all_docs.len()` (live == physical by the no-deletes gate or the
        // [#1260] admission bitmaps; `run_significant_terms` counts docs,
        // unweighted). Foreground == background ⇒ every term scores 0.0 ⇒
        // empty buckets.  Under the gate the memtable leg must come from the
        // live-filtered `mem()` view — the raw `doc_count()` still counts
        // stale pre-drain copies.
        let total: u64 = self.segs.iter().map(|s| s.docs as u64).sum::<u64>()
            + if self.mem_live_gate.is_some() {
                self.mem().len() as u64
            } else {
                self.idx.memtable.doc_count() as u64
            };
        Some(json!({
            "doc_count": total,
            "bg_count": total,
            "buckets": [],
        }))
    }

    // ── range (numeric) ──────────────────────────────────────────────────

    fn exec_range(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(params, &["field", "ranges", "keyed"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        let ranges = params.get("ranges").and_then(Value::as_array)?;
        if ranges.is_empty() {
            return None;
        }
        // Numeric-only (string bounds switch brute into date mode).
        for r in ranges {
            let o = r.as_object()?;
            if !o.keys().all(|k| k == "from" || k == "to" || k == "key") {
                return None;
            }
            for b in ["from", "to"] {
                if let Some(v) = o.get(b) {
                    if !v.is_number() {
                        return None;
                    }
                }
            }
        }
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Numeric)) | Ok(None) => {}
            _ => return None,
        }
        if !self.mem_field_numeric_safe(field) {
            return None;
        }
        let plan = self.plan_subs(sub, false)?;

        let mut buckets: Vec<Value> = Vec::with_capacity(ranges.len());
        for range_def in ranges {
            let from: Option<f64> = range_def.get("from").and_then(Value::as_f64);
            let to: Option<f64> = range_def.get("to").and_then(Value::as_f64);
            let lo = from.unwrap_or(f64::NEG_INFINITY);
            let hi = to.unwrap_or(f64::INFINITY);
            // match: n >= from && n < to  (to == +inf → inclusive is moot)
            let hi_incl = to.is_none();

            let mut count: u64 = 0;
            let mut accs: Vec<MetricAcc> = vec![MetricAcc::default(); plan.metrics.len()];
            for si in 0..self.segs.len() {
                let seg = &self.segs[si];
                let Some(Column::Numeric(n)) = seg.col(field) else {
                    continue;
                };
                if plan.metrics.is_empty() {
                    count += n.range_count(lo, hi, true, hi_incl);
                } else {
                    let rows = n.range_doc_ids(lo, hi, true, hi_incl);
                    count += rows.len() as u64;
                    let mut wrapped: Vec<Vec<MetricAcc>> =
                        accs.iter().map(|_| vec![MetricAcc::default()]).collect();
                    let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new()];
                    // Dense membership bitmap — the fused row pass probes
                    // every row of the segment, so a HashSet here costs a
                    // SipHash per row per range (~50 ms/M rows); a Vec<bool>
                    // probe is ~1 ns.
                    let mut in_range: Vec<bool> = vec![false; seg.docs as usize];
                    for r in rows {
                        if let Some(slot) = in_range.get_mut(r as usize) {
                            *slot = true;
                        }
                    }
                    let mut slot = |row: u32| -> Option<usize> {
                        if in_range.get(row as usize).copied().unwrap_or(false) {
                            Some(0)
                        } else {
                            None
                        }
                    };
                    let mut ms = false;
                    self.fused_seg_pass(si, &mut slot, 1, &plan, &mut wrapped, &mut tops, &mut ms)?;
                    for (mi, w) in wrapped.iter().enumerate() {
                        merge_acc(&mut accs[mi], &w[0]);
                    }
                }
            }
            for doc in self.mem().iter() {
                let Some(v) = extract_numeric(doc, field) else {
                    continue;
                };
                let matches = match (from, to) {
                    (Some(f), Some(t)) => v >= f && v < t,
                    (Some(f), None) => v >= f,
                    (None, Some(t)) => v < t,
                    (None, None) => true,
                };
                if !matches {
                    continue;
                }
                count += 1;
                for (mi, spec) in plan.metrics.iter().enumerate() {
                    Self::fold_mem_metric(doc, spec, &mut accs[mi]);
                }
            }

            let key = range_def
                .get("key")
                .and_then(Value::as_str)
                .map(String::from)
                .unwrap_or_else(|| match (from, to) {
                    (Some(f), Some(t)) => {
                        format!("{}-{}", format_range_val(f), format_range_val(t))
                    }
                    (Some(f), None) => format!("{}-*", format_range_val(f)),
                    (None, Some(t)) => format!("*-{}", format_range_val(t)),
                    (None, None) => "*-*".to_string(),
                });
            let mut bucket = Map::new();
            bucket.insert("key".to_string(), json!(key));
            bucket.insert("doc_count".to_string(), json!(count));
            if let Some(f) = from {
                bucket.insert("from".to_string(), json!(f));
            }
            if let Some(t) = to {
                bucket.insert("to".to_string(), json!(t));
            }
            self.finish_bucket(&mut bucket, &plan, &accs, None);
            buckets.push(Value::Object(bucket));
        }
        let buckets = apply_bucket_pipeline_ops(buckets, sub);

        let keyed = params
            .get("keyed")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        if keyed {
            let mut keyed_map = Map::new();
            for mut b in buckets {
                let k = b
                    .get("key")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .to_string();
                if let Some(obj) = b.as_object_mut() {
                    obj.remove("key");
                }
                keyed_map.insert(k, b);
            }
            return Some(json!({ "buckets": Value::Object(keyed_map) }));
        }
        Some(json!({ "buckets": buckets }))
    }

    // ── date_range ───────────────────────────────────────────────────────

    fn exec_date_range(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        if !params_only(params, &["field", "ranges", "keyed"]) {
            return None;
        }
        let field = params
            .get("field")
            .and_then(Value::as_str)
            .unwrap_or("@timestamp");
        let ranges = params.get("ranges").and_then(Value::as_array)?;
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Keyword)) | Ok(None) => {}
            _ => return None, // numeric-date columns: brute parse semantics differ; bail
        }

        // Fractional-precision detection — mirror run_date_range.
        let nanos_digits: usize = ranges
            .iter()
            .flat_map(|r| {
                let f = r
                    .get("from")
                    .and_then(Value::as_str)
                    .map(detect_fractional_digits)
                    .unwrap_or(0);
                let t = r
                    .get("to")
                    .and_then(Value::as_str)
                    .map(detect_fractional_digits)
                    .unwrap_or(0);
                [f, t]
            })
            .max()
            .unwrap_or(3);
        let nanos_digits = if nanos_digits >= 9 { 9 } else { 3 };
        let render = |ms: i64| -> String { render_iso_date(ms, nanos_digits, None) };

        // Parallel pre-warm of the per-segment date-ordinal cache (chrono
        // parsing of every distinct term is the dominant first-call cost).
        {
            use rayon::prelude::*;
            self.segs.par_iter().for_each(|seg| {
                if matches!(seg.col(field), Some(Column::Keyword(_))) {
                    let _ = self.date_sorted_prefix(seg, field);
                }
            });
        }
        // Per-segment sorted (ms, prefix-count) arrays (cached on the Index):
        // each range is answered with two binary searches instead of a walk
        // over every distinct term ordinal (~O(distinct timestamps) per
        // range pre-fix, which dominated on ms-resolution @timestamp data).
        let mut sorted_per_seg: Vec<Option<std::sync::Arc<(Vec<i64>, Vec<u64>)>>> = Vec::new();
        for s in &self.segs {
            match s.col(field) {
                Some(Column::Keyword(_)) => {
                    sorted_per_seg.push(Some(self.date_sorted_prefix(s, field)?));
                }
                _ => sorted_per_seg.push(None),
            }
        }

        let keyed = params
            .get("keyed")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let mut keyed_map = Map::new();
        let mut buckets: Vec<Value> = Vec::new();
        for range_def in ranges {
            let o = range_def.as_object()?;
            if !o.keys().all(|k| k == "from" || k == "to" || k == "key") {
                return None;
            }
            let from_ms = range_def.get("from").and_then(parse_date_ms);
            let to_ms = range_def.get("to").and_then(parse_date_ms);
            // Unparseable explicit bound → brute would fall to format-aware
            // parsing; bail to stay exact.
            if range_def.get("from").is_some() && from_ms.is_none() {
                return None;
            }
            if range_def.get("to").is_some() && to_ms.is_none() {
                return None;
            }
            let from_str_in = range_def.get("from").and_then(Value::as_str);
            let to_str_in = range_def.get("to").and_then(Value::as_str);

            let mut count: u64 = 0;
            for (si, s) in self.segs.iter().enumerate() {
                let Some(Column::Keyword(_)) = s.col(field) else {
                    continue;
                };
                let sp = sorted_per_seg[si].as_ref()?;
                let (ms_v, prefix) = (&sp.0, &sp.1);
                // Semantics identical to the old per-ord walk: from is
                // inclusive (ms >= from), to is exclusive (ms < to);
                // unparseable terms are excluded at build time.
                let lo = match from_ms {
                    Some(f) => ms_v.partition_point(|&m| m < f),
                    None => 0,
                };
                let hi = match to_ms {
                    Some(t) => ms_v.partition_point(|&m| m < t),
                    None => ms_v.len(),
                };
                if hi > lo {
                    count += prefix[hi] - prefix[lo];
                }
            }
            for doc in self.mem().iter() {
                let v = doc.get(field);
                let Some(ms) = v.and_then(parse_date_ms) else {
                    continue;
                };
                let pass_from = from_ms.map(|f| ms >= f).unwrap_or(true);
                let pass_to = to_ms.map(|t| ms < t).unwrap_or(true);
                if pass_from && pass_to {
                    count += doc_count_weight(doc);
                }
            }

            let from_key = match (from_ms, from_str_in) {
                (Some(ms), _) => render(ms),
                (None, Some(s)) => s.to_string(),
                _ => "*".to_string(),
            };
            let to_key = match (to_ms, to_str_in) {
                (Some(ms), _) => render(ms),
                (None, Some(s)) => s.to_string(),
                _ => "*".to_string(),
            };
            let default_key = format!("{}-{}", from_key, to_key);
            let key = range_def
                .get("key")
                .and_then(Value::as_str)
                .map(String::from)
                .unwrap_or(default_key);

            let mut bucket = Map::new();
            if !keyed {
                bucket.insert("key".to_string(), json!(key));
            }
            if let Some(ms) = from_ms {
                bucket.insert("from".to_string(), json!(ms));
                bucket.insert("from_as_string".to_string(), json!(render(ms)));
            }
            if let Some(ms) = to_ms {
                bucket.insert("to".to_string(), json!(ms));
                bucket.insert("to_as_string".to_string(), json!(render(ms)));
            }
            bucket.insert("doc_count".to_string(), json!(count));
            if keyed {
                keyed_map.insert(key, Value::Object(bucket));
            } else {
                buckets.push(Value::Object(bucket));
            }
        }
        if keyed {
            Some(json!({ "buckets": Value::Object(keyed_map) }))
        } else {
            Some(json!({ "buckets": buckets }))
        }
    }

    /// Cached ord → epoch-ms mapping for a keyword date column.
    /// `i64::MIN` marks unparseable terms.
    fn date_ord_index(&self, seg: &SegEntry, field: &str) -> Option<std::sync::Arc<Vec<i64>>> {
        let key = (seg.id.clone(), field.to_string());
        if let Some(v) = self.idx.fast_date_cache.get(&key) {
            return Some(std::sync::Arc::clone(v.value()));
        }
        let Some(Column::Keyword(k)) = seg.col(field) else {
            return None;
        };
        let mut ord_ms: Vec<i64> = Vec::with_capacity(k.terms.len());
        for t in &k.terms {
            ord_ms.push(parse_date_ms(&Value::String(t.clone())).unwrap_or(i64::MIN));
        }
        let arc = std::sync::Arc::new(ord_ms);
        self.idx
            .fast_date_cache
            .insert(key, std::sync::Arc::clone(&arc));
        Some(arc)
    }

    /// Cached sorted parsed dates + prefix doc counts for a keyword date
    /// column: `ms[i]` ascending, `prefix[i+1] - prefix[lo]` = number of
    /// docs whose parsed date falls in `ms[lo..=i]`.  Unparseable terms
    /// (i64::MIN) and zero-count ordinals are excluded — matching the
    /// brute/date_range walk exactly.
    fn date_sorted_prefix(
        &self,
        seg: &SegEntry,
        field: &str,
    ) -> Option<std::sync::Arc<(Vec<i64>, Vec<u64>)>> {
        let key = (seg.id.clone(), field.to_string());
        if let Some(v) = self.idx.fast_date_sorted_cache.get(&key) {
            return Some(std::sync::Arc::clone(v.value()));
        }
        let Some(Column::Keyword(k)) = seg.col(field) else {
            return None;
        };
        let ord_ms = self.date_ord_index(seg, field)?;
        let mut pairs: Vec<(i64, u64)> = Vec::with_capacity(ord_ms.len());
        for (ord, &ms) in ord_ms.iter().enumerate() {
            let cnt = k.per_ord_count.get(ord).copied().unwrap_or(0) as u64;
            if ms == i64::MIN || cnt == 0 {
                continue;
            }
            pairs.push((ms, cnt));
        }
        pairs.sort_unstable_by_key(|p| p.0);
        let mut ms_v: Vec<i64> = Vec::with_capacity(pairs.len());
        let mut prefix: Vec<u64> = Vec::with_capacity(pairs.len() + 1);
        prefix.push(0);
        let mut acc = 0u64;
        for (ms, c) in pairs {
            ms_v.push(ms);
            acc += c;
            prefix.push(acc);
        }
        let arc = std::sync::Arc::new((ms_v, prefix));
        self.idx
            .fast_date_sorted_cache
            .insert(key, std::sync::Arc::clone(&arc));
        Some(arc)
    }

    // ── filter / filters / adjacency_matrix ─────────────────────────────

    fn exec_filter(&self, filter_query: &Value, sub: Option<&Value>) -> Option<Value> {
        let plan = self.plan_subs(sub, false)?;
        let pred = compile_pred(filter_query)?;
        self.check_pred_kinds(&pred)?;

        let mut count: u64 = 0;
        let mut accs: Vec<MetricAcc> = vec![MetricAcc::default(); plan.metrics.len()];
        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            let sp = resolve_pred(&seg.cols, &pred, &self.segs, self.mapped_fields)?;
            if plan.metrics.is_empty() {
                count += seg_pred_count(&sp, seg.docs);
            } else {
                let mut wrapped: Vec<Vec<MetricAcc>> =
                    accs.iter().map(|_| vec![MetricAcc::default()]).collect();
                let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new()];
                let mut slot = |row: u32| -> Option<usize> {
                    if seg_pred_matches(&sp, row) {
                        count += 1;
                        Some(0)
                    } else {
                        None
                    }
                };
                let mut ms = false;
                self.fused_seg_pass(si, &mut slot, 1, &plan, &mut wrapped, &mut tops, &mut ms)?;
                for (mi, w) in wrapped.iter().enumerate() {
                    merge_acc(&mut accs[mi], &w[0]);
                }
            }
        }
        for doc in self.mem().iter() {
            if doc_matches_filter(doc, filter_query) {
                count += doc_count_weight(doc);
                for (mi, spec) in plan.metrics.iter().enumerate() {
                    Self::fold_mem_metric(doc, spec, &mut accs[mi]);
                }
            }
        }
        let mut bucket = Map::new();
        bucket.insert("doc_count".to_string(), json!(count));
        self.finish_bucket(&mut bucket, &plan, &accs, None);
        Some(Value::Object(bucket))
    }

    fn exec_filters(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(params, &["filters", "keyed"]) {
            return None;
        }
        let plan = self.plan_subs(sub, false)?;
        let filters_val = params.get("filters")?;
        let keyed_override = params.get("keyed").and_then(Value::as_bool);

        // Normalise to (Option<name>, query) preserving order.
        let entries: Vec<(Option<String>, &Value)> = match filters_val {
            Value::Object(map) => map.iter().map(|(k, v)| (Some(k.clone()), v)).collect(),
            Value::Array(arr) => arr.iter().map(|v| (None, v)).collect(),
            _ => return None,
        };
        let named = matches!(filters_val, Value::Object(_));
        let keyed = if named {
            keyed_override.unwrap_or(true)
        } else {
            false
        };

        let mut rendered: Vec<(Option<String>, Value)> = Vec::with_capacity(entries.len());
        for (name, q) in &entries {
            let one = self.filter_bucket_body(q, &plan)?;
            rendered.push((name.clone(), one));
        }

        if named && keyed {
            let mut buckets = Map::new();
            for (name, b) in rendered {
                buckets.insert(name.unwrap_or_default(), b);
            }
            Some(json!({ "buckets": buckets }))
        } else if named {
            let mut buckets: Vec<Value> = Vec::new();
            for (name, mut b) in rendered {
                if let Some(o) = b.as_object_mut() {
                    o.insert("key".to_string(), Value::String(name.unwrap_or_default()));
                }
                buckets.push(b);
            }
            Some(json!({ "buckets": buckets }))
        } else {
            let buckets: Vec<Value> = rendered.into_iter().map(|(_, b)| b).collect();
            Some(json!({ "buckets": buckets }))
        }
    }

    /// A single filters-agg bucket body: `{doc_count, <subs>}`.
    fn filter_bucket_body(&self, filter_query: &Value, plan: &SubPlan) -> Option<Value> {
        let pred = compile_pred(filter_query)?;
        self.check_pred_kinds(&pred)?;
        let mut count: u64 = 0;
        let mut accs: Vec<MetricAcc> = vec![MetricAcc::default(); plan.metrics.len()];
        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            let sp = resolve_pred(&seg.cols, &pred, &self.segs, self.mapped_fields)?;
            if plan.metrics.is_empty() {
                count += seg_pred_count(&sp, seg.docs);
            } else {
                let mut wrapped: Vec<Vec<MetricAcc>> =
                    accs.iter().map(|_| vec![MetricAcc::default()]).collect();
                let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new()];
                let mut slot = |row: u32| -> Option<usize> {
                    if seg_pred_matches(&sp, row) {
                        count += 1;
                        Some(0)
                    } else {
                        None
                    }
                };
                let mut ms = false;
                self.fused_seg_pass(si, &mut slot, 1, plan, &mut wrapped, &mut tops, &mut ms)?;
                for (mi, w) in wrapped.iter().enumerate() {
                    merge_acc(&mut accs[mi], &w[0]);
                }
            }
        }
        for doc in self.mem().iter() {
            if doc_matches_filter(doc, filter_query) {
                count += doc_count_weight(doc);
                for (mi, spec) in plan.metrics.iter().enumerate() {
                    Self::fold_mem_metric(doc, spec, &mut accs[mi]);
                }
            }
        }
        let mut bucket = Map::new();
        bucket.insert("doc_count".to_string(), json!(count));
        self.finish_bucket(&mut bucket, plan, &accs, None);
        Some(Value::Object(bucket))
    }

    fn exec_adjacency_matrix(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        if !params_only(params, &["filters"]) {
            return None;
        }
        let filters_map = params.get("filters").and_then(Value::as_object)?;
        let names: Vec<&String> = filters_map.keys().collect();
        let preds: Vec<Pred> = filters_map
            .values()
            .map(compile_pred)
            .collect::<Option<Vec<_>>>()?;
        for p in &preds {
            self.check_pred_kinds(p)?;
        }
        let n = preds.len();
        if n == 0 {
            return Some(json!({ "buckets": [] }));
        }
        if n > 32 {
            return None;
        }
        let mut singles: Vec<u64> = vec![0; n];
        let mut pairs: Vec<u64> = vec![0; n * n];
        for seg in &self.segs {
            let sps: Vec<SegPred<'_>> = preds
                .iter()
                .map(|p| resolve_pred(&seg.cols, p, &self.segs, self.mapped_fields))
                .collect::<Option<Vec<_>>>()?;
            for row in 0..seg.docs {
                let mut mask: u32 = 0;
                for (i, sp) in sps.iter().enumerate() {
                    if seg_pred_matches(sp, row) {
                        mask |= 1 << i;
                    }
                }
                if mask == 0 {
                    continue;
                }
                let mut m = mask;
                while m != 0 {
                    let i = m.trailing_zeros() as usize;
                    m &= m - 1;
                    singles[i] += 1;
                    let mut m2 = mask & !((1u32 << (i + 1)) - 1);
                    while m2 != 0 {
                        let j = m2.trailing_zeros() as usize;
                        m2 &= m2 - 1;
                        pairs[i * n + j] += 1;
                    }
                }
            }
        }
        for doc in self.mem().iter() {
            let matches: Vec<bool> = filters_map
                .values()
                .map(|q| doc_matches_filter(doc, q))
                .collect();
            for i in 0..n {
                if matches[i] {
                    singles[i] += 1;
                    for j in (i + 1)..n {
                        if matches[j] {
                            pairs[i * n + j] += 1;
                        }
                    }
                }
            }
        }
        let mut buckets: Vec<Value> = Vec::new();
        for i in 0..n {
            if singles[i] > 0 {
                buckets.push(json!({ "key": names[i], "doc_count": singles[i] }));
            }
        }
        for i in 0..n {
            for j in (i + 1)..n {
                if pairs[i * n + j] > 0 {
                    buckets.push(json!({
                        "key": format!("{}&{}", names[i], names[j]),
                        "doc_count": pairs[i * n + j]
                    }));
                }
            }
        }
        buckets.sort_by(|a, b| {
            let ka = a.get("key").and_then(Value::as_str).unwrap_or("");
            let kb = b.get("key").and_then(Value::as_str).unwrap_or("");
            ka.cmp(kb)
        });
        Some(json!({ "buckets": buckets }))
    }

    fn check_pred_kinds(&self, pred: &Pred) -> Option<()> {
        match pred {
            Pred::MatchAll => Some(()),
            Pred::TermKw { field, .. } | Pred::TermsKw { field, .. } => {
                match self.seg_field_kind(field) {
                    Ok(Some(ColKind::Keyword)) | Ok(None) => Some(()),
                    _ => None,
                }
            }
            Pred::RangeNum { field, .. } => match self.seg_field_kind(field) {
                Ok(Some(ColKind::Numeric)) | Ok(None) => Some(()),
                _ => None,
            },
            // Lexicographic range — keyword-backed columns only (this is the
            // shape a `date` field takes; see `Pred::RangeKw`).
            Pred::RangeKw { field, .. } => match self.seg_field_kind(field) {
                Ok(Some(ColKind::Keyword)) | Ok(None) => Some(()),
                _ => None,
            },
            // Keyword, numeric, and presence columns can answer "row is non-null".
            Pred::Exists { field } => match self.seg_field_kind(field) {
                Ok(Some(ColKind::Keyword))
                | Ok(Some(ColKind::Numeric))
                | Ok(Some(ColKind::Presence))
                | Ok(None) => Some(()),
                _ => None,
            },
            Pred::And(subs) => {
                for s in subs {
                    self.check_pred_kinds(s)?;
                }
                Some(())
            }
        }
    }

    // ── composite ────────────────────────────────────────────────────────

    fn exec_composite(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        // `__xy_field_types__` is the HTTP layer's mapping-type sentinel
        // (item 7 key typing) — metadata, not a user param.
        if !params_only(params, &["sources", "size", "__xy_field_types__"]) {
            return None;
        }
        let sources = params.get("sources").and_then(Value::as_array)?;
        let size = params.get("size").and_then(Value::as_u64).unwrap_or(10) as usize;
        let field_types = params.get("__xy_field_types__").and_then(Value::as_object);

        // All sources must be plain `terms` over keyword columns.
        let mut src_names: Vec<String> = Vec::new();
        let mut src_fields: Vec<String> = Vec::new();
        for src in sources {
            let src_obj = src.as_object()?;
            if src_obj.len() != 1 {
                return None;
            }
            let (name, spec) = src_obj.iter().next()?;
            let spec_obj = spec.as_object()?;
            if spec_obj.len() != 1 {
                return None;
            }
            let (t, tp) = spec_obj.iter().next()?;
            if t != "terms" || !params_only(tp, &["field"]) {
                return None;
            }
            let field = tp.get("field").and_then(Value::as_str)?;
            match self.seg_field_kind(field) {
                Ok(Some(ColKind::Keyword)) | Ok(None) => {}
                _ => return None,
            }
            src_names.push(name.clone());
            src_fields.push(field.to_string());
        }
        if src_names.is_empty() {
            return Some(json!({ "buckets": [] }));
        }
        // Mapping-driven key kinds, identical to run_composite's — keeps
        // this arm byte-identical to brute for sorting AND key typing.
        let kinds: Vec<crate::aggs::CompositeKeyKind> = src_fields
            .iter()
            .map(|f| {
                crate::aggs::composite_kind_of(
                    field_types.and_then(|m| m.get(f)).and_then(Value::as_str),
                )
            })
            .collect();

        let mut counts: HashMap<Vec<String>, u64> = HashMap::new();
        for seg in &self.segs {
            let cols: Vec<&KeywordColumn> = match src_fields
                .iter()
                .map(|f| match seg.col(f) {
                    Some(Column::Keyword(k)) => Some(k),
                    _ => None,
                })
                .collect::<Option<Vec<_>>>()
            {
                Some(c) => c,
                None => continue, // some source field absent → no docs from this segment
            };
            // Dense lane: when the ord cross-product is small, count into a
            // flat array indexed by the combined ordinal — no per-row Vec
            // allocation, no hashing.  Row loop is then just c column loads
            // and one add per doc.
            const DENSE_CAP: usize = 1 << 16;
            let dims: Vec<usize> = cols.iter().map(|k| k.terms.len().max(1)).collect();
            let mut dense_total: usize = 1;
            let mut dense_ok = true;
            for &d in &dims {
                match dense_total.checked_mul(d) {
                    Some(t) if t <= DENSE_CAP => dense_total = t,
                    _ => {
                        dense_ok = false;
                        break;
                    }
                }
            }
            if dense_ok {
                let mut dense: Vec<u64> = vec![0; dense_total];
                let no_nulls = cols.iter().all(|k| k.null_bitmap.is_empty())
                    && cols.iter().all(|k| k.ords.len() >= seg.docs as usize);
                if no_nulls {
                    if cols.len() == 2 {
                        // Hot shape (two keyword sources): tight two-slice walk.
                        let a = &cols[0].ords;
                        let b = &cols[1].ords;
                        let n1 = dims[1];
                        for row in 0..seg.docs as usize {
                            dense[a[row] as usize * n1 + b[row] as usize] += 1;
                        }
                    } else {
                        for row in 0..seg.docs as usize {
                            let mut idx = 0usize;
                            for (ci, k) in cols.iter().enumerate() {
                                idx = idx * dims[ci] + k.ords[row] as usize;
                            }
                            dense[idx] += 1;
                        }
                    }
                } else {
                    'dense_rows: for row in 0..seg.docs {
                        let mut idx = 0usize;
                        for (ci, k) in cols.iter().enumerate() {
                            match k.ord_for(row) {
                                Some(o) => idx = idx * dims[ci] + o as usize,
                                None => continue 'dense_rows,
                            }
                        }
                        dense[idx] += 1;
                    }
                }
                for (idx, &c) in dense.iter().enumerate() {
                    if c == 0 {
                        continue;
                    }
                    let mut rem = idx;
                    let mut key: Vec<String> = vec![String::new(); cols.len()];
                    for i in (0..cols.len()).rev() {
                        let o = rem % dims[i];
                        rem /= dims[i];
                        key[i] = cols[i].terms[o].clone();
                    }
                    *counts.entry(key).or_insert(0) += c;
                }
                continue;
            }
            let mut local: HashMap<Vec<u32>, u64> = HashMap::new();
            'rows: for row in 0..seg.docs {
                let mut key: Vec<u32> = Vec::with_capacity(cols.len());
                for k in &cols {
                    match k.ord_for(row) {
                        Some(o) => key.push(o),
                        None => continue 'rows,
                    }
                }
                *local.entry(key).or_insert(0) += 1;
            }
            for (ords, c) in local {
                let key: Vec<String> = ords
                    .iter()
                    .zip(cols.iter())
                    .map(|(o, k)| k.terms[*o as usize].clone())
                    .collect();
                *counts.entry(key).or_insert(0) += c;
            }
        }
        for doc in self.mem().iter() {
            let weight = doc_count_weight(doc);
            // Cross-product across multi-valued fields — brute semantics.
            let mut keys: Vec<Vec<String>> = vec![vec![]];
            let mut dead = false;
            for f in &src_fields {
                let vals = extract_field_values(doc, f);
                if vals.is_empty() {
                    dead = true;
                    break;
                }
                let mut next: Vec<Vec<String>> = Vec::new();
                for k in &keys {
                    for v in &vals {
                        let mut nk = k.clone();
                        nk.push(v.clone());
                        next.push(nk);
                    }
                }
                keys = next;
            }
            if dead {
                continue;
            }
            for k in keys {
                *counts.entry(k).or_insert(0) += weight;
            }
        }

        let mut sorted_keys: Vec<Vec<String>> = counts.keys().cloned().collect();
        sorted_keys.sort_by(|a, b| composite_cmp(a, b, &kinds));
        sorted_keys.truncate(size);

        let result_buckets: Vec<Value> = sorted_keys
            .iter()
            .map(|key| {
                let mut key_obj = Map::new();
                for (i, name) in src_names.iter().enumerate() {
                    let val = key.get(i).cloned().unwrap_or_default();
                    let kind = kinds
                        .get(i)
                        .copied()
                        .unwrap_or(crate::aggs::CompositeKeyKind::Heuristic);
                    key_obj.insert(
                        name.clone(),
                        crate::aggs::composite_typed_key_value(kind, &val),
                    );
                }
                json!({ "key": Value::Object(key_obj), "doc_count": counts[key] })
            })
            .collect();

        let after_key = result_buckets
            .last()
            .and_then(|b| b.get("key").cloned())
            .unwrap_or(Value::Null);
        // ES serializes `after_key` BEFORE `buckets`; with preserve_order
        // enabled the insertion order here is the response byte order.
        let mut obj = serde_json::Map::new();
        if !after_key.is_null() {
            obj.insert("after_key".into(), after_key);
        }
        obj.insert("buckets".into(), Value::Array(result_buckets));
        Some(Value::Object(obj))
    }

    // ── sampler / random_sampler ─────────────────────────────────────────

    fn exec_sampler(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(
            params,
            &["shard_size", "probability", "seed", "max_docs_per_value"],
        ) {
            return None;
        }
        if let Some(s) = sub {
            if sub_tree_needs_background(s) {
                return None;
            }
        }
        let shard_size = params
            .get("shard_size")
            .and_then(Value::as_u64)
            .unwrap_or(200) as usize;
        if shard_size > 10_000 {
            return None; // keep the materialisation bounded
        }
        // Sample = first `shard_size` docs in brute corpus order
        // (memtable docs, then segments in snapshot order).  With
        // match_all every doc scores equal, so the brute sampler's
        // stable score sort preserves exactly this prefix.
        let mut sample: Vec<Value> = Vec::with_capacity(shard_size);
        for d in self.mem().iter() {
            if sample.len() >= shard_size {
                break;
            }
            sample.push(d.clone());
        }
        let mut si = 0usize;
        while sample.len() < shard_size && si < self.segs.len() {
            let take = (shard_size - sample.len()).min(self.segs[si].docs as usize);
            for row in 0..take {
                sample.push(self.fetch_seg_doc(si, row as u32)?);
            }
            si += 1;
        }
        // Brute enriches the first `materialisation_limit` (256) corpus docs
        // with `_score: 1.0` (the match_all hit window).  Mirror it so
        // score-sensitive sub-aggs (top_hits default sort) behave the same.
        for d in sample.iter_mut().take(256) {
            if let Some(o) = d.as_object_mut() {
                o.insert("_score".to_string(), json!(1.0));
            }
        }
        Some(run_sampler(params, sub, &sample, &sample))
    }

    // ── variable_width_histogram ─────────────────────────────────────────

    fn exec_vwh(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if sub.is_some() {
            return None;
        }
        if !params_only(params, &["field", "buckets"]) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        let num_buckets = params.get("buckets").and_then(Value::as_u64).unwrap_or(10) as usize;
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Numeric)) | Ok(None) => {}
            _ => return None,
        }
        if !self.mem_field_numeric_safe(field) {
            return None;
        }

        // Distinct (value → weight) across all sources, ascending by value.
        // Each segment's `n.sorted` is already value-ascending, so collapse
        // each into a distinct-run list and k-way merge — no HashMap (a 1M-row
        // corpus paid ~300 ms of SipHash there), no global re-sort.
        let mut runs: Vec<Vec<(f64, u64)>> = Vec::with_capacity(self.segs.len() + 1);
        for seg in &self.segs {
            let Some(Column::Numeric(n)) = seg.col(field) else {
                continue;
            };
            let mut run: Vec<(f64, u64)> = Vec::new();
            let mut i = 0usize;
            while i < n.sorted.len() {
                let bits = n.sorted[i].0;
                let mut j = i + 1;
                while j < n.sorted.len() && n.sorted[j].0 == bits {
                    j += 1;
                }
                run.push((f64::from_bits(bits as u64), (j - i) as u64));
                i = j;
            }
            if !run.is_empty() {
                runs.push(run);
            }
        }
        if !self.mem().is_empty() {
            let mut mem_vals: Vec<f64> = self
                .mem()
                .iter()
                .filter_map(|doc| extract_numeric(doc, field))
                .collect();
            mem_vals.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
            let mut run: Vec<(f64, u64)> = Vec::new();
            for v in mem_vals {
                match run.last_mut() {
                    Some((lv, w)) if *lv == v => *w += 1,
                    _ => run.push((v, 1)),
                }
            }
            if !run.is_empty() {
                runs.push(run);
            }
        }
        let vals = merge_weighted_runs(runs);
        if vals.is_empty() {
            return Some(json!({ "buckets": [] }));
        }

        // Bound the exact agglomerative clustering working set.  The
        // heap-merge in `vwh_cluster` does (distinct − buckets) merges — on a
        // ~500 k-distinct float column that's hundreds of ms.  ES's own VWH
        // is approximate (it never keeps more than shard_size ≈ buckets×50
        // clusters while collecting), so pre-coarsening the sorted distinct
        // list into equal-weight groups before the exact pass matches ES's
        // accuracy class while keeping the whole agg in the ~10 ms range.
        // Below the cap the behaviour is byte-identical to before.
        const VWH_COARSE_CAP: usize = 5_000;
        let vals = if vals.len() > VWH_COARSE_CAP.max(num_buckets * 50) {
            coarsen_weighted(&vals, VWH_COARSE_CAP.max(num_buckets * 50))
        } else {
            vals
        };

        let buckets = vwh_cluster(&vals, num_buckets);
        let result_buckets: Vec<Value> = buckets
            .iter()
            .map(|b| {
                json!({
                    "min": b.min, "key": b.sum / b.count as f64, "max": b.max,
                    "doc_count": b.count
                })
            })
            .collect();
        Some(json!({ "buckets": result_buckets }))
    }

    // ── date_histogram ───────────────────────────────────────────────────

    fn exec_date_histogram(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(
            params,
            &[
                "field",
                "calendar_interval",
                "fixed_interval",
                "interval",
                "format",
                "keyed",
                "min_doc_count",
                "offset",
            ],
        ) {
            return None;
        }
        let field = params.get("field").and_then(Value::as_str)?;
        match self.seg_field_kind(field) {
            // Keyword = date-as-ISO-string column (parsed via `date_ord_index`).
            // Numeric = epoch-millis column (`date`/`long` doc-values) — the
            // common case, bucketed directly below with no chrono parse. Before
            // this, a Numeric date field fell through to the O(N) brute path
            // (`run_aggs_with_all`), ~1 s / 200k docs.
            Ok(Some(ColKind::Keyword)) | Ok(Some(ColKind::Numeric)) | Ok(None) => {}
            _ => return None,
        }
        let interval_str = params
            .get("fixed_interval")
            .or_else(|| params.get("calendar_interval"))
            .or_else(|| params.get("interval"))
            .and_then(Value::as_str)
            .unwrap_or("1d");
        let interval_ms = interval_to_ms(interval_str)?;
        let use_calendar = is_calendar_interval(interval_str);
        // Fixed-interval grid `offset` (e.g. "+3600000ms" from the
        // auto_date_histogram anchoring, or a user "+30m"): shift the grid by
        // `offset_ms`, exactly the brute `to_local`/`to_utc` pair.  Calendar
        // intervals with an offset keep going through the brute path.
        let offset_ms = params
            .get("offset")
            .and_then(Value::as_str)
            .and_then(parse_offset_ms)
            .unwrap_or(0);
        if offset_ms != 0 && use_calendar {
            return None;
        }
        let bucket_of = |ms: i64| -> i64 {
            if use_calendar {
                calendar_bucket_key(ms, interval_str)
            } else {
                (ms - offset_ms).div_euclid(interval_ms) * interval_ms + offset_ms
            }
        };
        let next_bucket = |key: i64| -> i64 {
            let next = if use_calendar {
                next_calendar_bucket(key, interval_str)
            } else {
                key + interval_ms
            };
            if next <= key {
                key + interval_ms
            } else {
                next
            }
        };

        // Parallel pre-warm of the per-segment date-ordinal cache (chrono
        // parsing of every distinct term is the dominant first-call cost).
        {
            use rayon::prelude::*;
            self.segs.par_iter().for_each(|seg| {
                if matches!(seg.col(field), Some(Column::Keyword(_))) {
                    let _ = self.date_ord_index(seg, field);
                }
            });
        }
        let plan = self.plan_subs(sub, false)?;
        let has_row_work = !plan.metrics.is_empty();

        // Global bucket table.
        let mut bucket_ids: HashMap<i64, usize> = HashMap::new();
        let mut bucket_keys: Vec<i64> = Vec::new();
        let mut counts: Vec<u64> = Vec::new();
        let mut accs: Vec<Vec<MetricAcc>> = plan.metrics.iter().map(|_| Vec::new()).collect();
        let ensure_bucket = |key: i64,
                             bucket_ids: &mut HashMap<i64, usize>,
                             bucket_keys: &mut Vec<i64>,
                             counts: &mut Vec<u64>,
                             accs: &mut Vec<Vec<MetricAcc>>|
         -> usize {
            *bucket_ids.entry(key).or_insert_with(|| {
                bucket_keys.push(key);
                counts.push(0);
                for a in accs.iter_mut() {
                    a.push(MetricAcc::default());
                }
                bucket_keys.len() - 1
            })
        };

        let mut missing_sort_seen = false;
        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            let Some(Column::Keyword(k)) = seg.col(field) else {
                continue;
            };
            let ord_ms = self.date_ord_index(seg, field)?;
            // ord → bucket slot table.  Term ordinals are lexicographic and
            // ISO-8601 timestamps sort chronologically, so `ord_ms` is
            // (near-)ascending: memoise the current bucket's [start, end)
            // window and only pay `bucket_of` (chrono calendar math) + the
            // HashMap probe when the run breaks.  This turns ~1 per distinct
            // timestamp (≈1 per doc at ms resolution) into ~1 per bucket.
            // `bucket_of(ms) == key` for every ms in `[key, next_bucket(key))`
            // is the same invariant the min_doc_count:0 gap-fill below
            // already relies on.
            let mut ord_slot: Vec<i32> = Vec::with_capacity(k.terms.len());
            let mut run: Option<(i64, i64, i32)> = None; // (start, end, slot)
            for (ord, &ms) in ord_ms.iter().enumerate() {
                if ms == i64::MIN || k.per_ord_count.get(ord).copied().unwrap_or(0) == 0 {
                    ord_slot.push(-1);
                    continue;
                }
                let slot = match run {
                    Some((start, end, slot)) if ms >= start && ms < end => slot,
                    _ => {
                        let key = bucket_of(ms);
                        let slot = ensure_bucket(
                            key,
                            &mut bucket_ids,
                            &mut bucket_keys,
                            &mut counts,
                            &mut accs,
                        ) as i32;
                        run = Some((key, next_bucket(key), slot));
                        slot
                    }
                };
                ord_slot.push(slot);
            }
            // Bucket doc counts always come from the per-ord histogram —
            // exactly the count of rows with that (non-null) ordinal — so
            // the row pass below no longer pays a per-row counter bump.
            for (ord, &cnt) in k.per_ord_count.iter().enumerate() {
                if cnt > 0 && ord_slot[ord] >= 0 {
                    counts[ord_slot[ord] as usize] += cnt as u64;
                }
            }
            if !has_row_work {
                continue;
            }
            let n_slots = bucket_keys.len();
            let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new(); n_slots.max(1)];
            {
                let kw_dense = k.null_bitmap.is_empty();
                let mut slot_of_row = |row: u32| -> Option<usize> {
                    let ord = if kw_dense {
                        *k.ords.get(row as usize)? as usize
                    } else {
                        k.ord_for(row)? as usize
                    };
                    let s = ord_slot[ord];
                    if s < 0 {
                        return None;
                    }
                    Some(s as usize)
                };
                self.fused_seg_pass(
                    si,
                    &mut slot_of_row,
                    n_slots,
                    &plan,
                    &mut accs,
                    &mut tops,
                    &mut missing_sort_seen,
                )?;
            }
        }
        // Numeric (epoch-millis) date column: bucket the doc-values integers
        // directly — no chrono parse, no per-ord run memo (values are ~unique
        // per doc). Segments are keyword XOR numeric for a field, so exactly
        // one of these two loops does work. Counts are bumped here; sub-metrics
        // fold via `fused_seg_pass`, mirroring the keyword arm above.
        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            let Some(Column::Numeric(n)) = seg.col(field) else {
                continue;
            };
            let mut row_slot: Vec<i32> = Vec::with_capacity(seg.docs as usize);
            for row in 0..seg.docs {
                match n.get(row) {
                    // `NumericColumn::data` stores f64 BITS (see its doc comment
                    // + `exec_vwh`), not the raw integer — decode to the epoch-ms
                    // value before bucketing.
                    Some(bits) => {
                        let ms = f64::from_bits(bits as u64) as i64;
                        let key = bucket_of(ms);
                        let slot = ensure_bucket(
                            key,
                            &mut bucket_ids,
                            &mut bucket_keys,
                            &mut counts,
                            &mut accs,
                        ) as i32;
                        counts[slot as usize] += 1;
                        row_slot.push(slot);
                    }
                    None => row_slot.push(-1),
                }
            }
            if !has_row_work {
                continue;
            }
            let n_slots = bucket_keys.len();
            let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new(); n_slots.max(1)];
            {
                let mut slot_of_row = |row: u32| -> Option<usize> {
                    let s = *row_slot.get(row as usize)?;
                    if s < 0 {
                        None
                    } else {
                        Some(s as usize)
                    }
                };
                self.fused_seg_pass(
                    si,
                    &mut slot_of_row,
                    n_slots,
                    &plan,
                    &mut accs,
                    &mut tops,
                    &mut missing_sort_seen,
                )?;
            }
        }

        // Memtable docs — brute multi-value date extraction with per-doc
        // bucket dedup.
        for doc in self.mem().iter() {
            let raws = extract_date_ms_values(doc, field);
            let weight = doc_count_weight(doc);
            let mut seen: Vec<i64> = Vec::with_capacity(raws.len());
            for ms in raws {
                let key = bucket_of(ms);
                if seen.contains(&key) {
                    continue;
                }
                seen.push(key);
                let slot = ensure_bucket(
                    key,
                    &mut bucket_ids,
                    &mut bucket_keys,
                    &mut counts,
                    &mut accs,
                );
                counts[slot] += weight;
                for (mi, spec) in plan.metrics.iter().enumerate() {
                    Self::fold_mem_metric(doc, spec, &mut accs[mi][slot]);
                }
            }
        }

        let min_doc_count = params
            .get("min_doc_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let keyed = params
            .get("keyed")
            .and_then(Value::as_bool)
            .unwrap_or(false);

        // Bucket-key set: gap-fill when min_doc_count == 0 (brute default).
        //
        // `search.max_buckets` read ONCE here, above the probe loop — the same
        // `aggs::max_buckets_i64()` accessor `aggs::run_date_histogram` reads,
        // so `config.limits.max_buckets` and a per-call `AggLimits` override
        // bind this path too. It used to be a hardcoded 65 536, which meant an
        // operator's lowered cap applied only when a query happened to miss
        // the columnar path.
        let bucket_cap = crate::aggs::max_buckets_i64();
        let mut final_keys: Vec<i64> = if min_doc_count > 0 {
            bucket_keys.clone()
        } else if let (Some(&min_key), Some(&max_key)) =
            (bucket_keys.iter().min(), bucket_keys.iter().max())
        {
            let mut span: i64 = 0;
            let mut probe = min_key;
            while probe <= max_key {
                span += 1;
                if span > bucket_cap {
                    return Some(json!({
                        "error": format!(
                            "Trying to create too many buckets. Must be less than or equal to: [{}] but this number of buckets was exceeded. This limit can be set by changing the [search.max_buckets] cluster level setting.",
                            bucket_cap
                        ),
                        "__error_status__": 400u32,
                    }));
                }
                probe = next_bucket(probe);
            }
            let mut keys = Vec::with_capacity(span as usize);
            let mut k = min_key;
            while k <= max_key {
                keys.push(k);
                k = next_bucket(k);
            }
            keys
        } else {
            bucket_keys.clone()
        };
        final_keys.sort_unstable();
        if min_doc_count > 0 {
            final_keys.retain(|k| {
                bucket_ids
                    .get(k)
                    .map(|&s| counts[s] >= min_doc_count)
                    .unwrap_or(false)
            });
        }

        let fmt_param = params.get("format").and_then(Value::as_str);
        let render_key = |key: i64| -> String {
            let dt_val = chrono::DateTime::from_timestamp_millis(key).unwrap_or_default();
            render_date_format(fmt_param, key, dt_val)
        };

        let empty_accs: Vec<MetricAcc> = vec![MetricAcc::default(); plan.metrics.len()];
        let mut result_buckets: Vec<Value> = Vec::with_capacity(final_keys.len());
        for &key in &final_keys {
            let slot = bucket_ids.get(&key).copied();
            let count = slot.map(|s| counts[s]).unwrap_or(0);
            let mut bucket = Map::new();
            bucket.insert("key".to_string(), json!(key));
            bucket.insert("key_as_string".to_string(), json!(render_key(key)));
            bucket.insert("doc_count".to_string(), json!(count));
            let bucket_accs: Vec<MetricAcc> = match slot {
                Some(s) => plan
                    .metrics
                    .iter()
                    .enumerate()
                    .map(|(mi, _)| accs[mi][s])
                    .collect(),
                None => empty_accs.clone(),
            };
            self.finish_bucket(&mut bucket, &plan, &bucket_accs, None);
            result_buckets.push(Value::Object(bucket));
        }
        let result_buckets = apply_bucket_pipeline_ops(result_buckets, sub);

        if keyed {
            let mut map = Map::new();
            for b in result_buckets {
                let k = b
                    .get("key_as_string")
                    .and_then(Value::as_str)
                    .map(str::to_string)
                    .or_else(|| b.get("key").and_then(Value::as_i64).map(|i| i.to_string()))
                    .unwrap_or_default();
                map.insert(k, b);
            }
            Some(json!({ "buckets": Value::Object(map) }))
        } else {
            Some(json!({ "buckets": result_buckets }))
        }
    }

    // Fixed-interval `histogram` over a NUMERIC doc-values column. Mirrors the
    // date_histogram numeric arm for the columnar mechanics (per-segment
    // row→slot fold + `fused_seg_pass` for sub-metrics + brute memtable fold)
    // and `aggs::run_histogram` for the exact bucketing/rendering semantics.
    // Before this, `histogram` had no exec_agg arm → every request hit the O(N)
    // `run_aggs_with_all` brute path (~950 ms / 200k docs).
    fn exec_histogram(&self, params: &Value, sub: Option<&Value>) -> Option<Value> {
        if !params_only(
            params,
            &[
                "field",
                "interval",
                "offset",
                "min_doc_count",
                "keyed",
                "format",
                "extended_bounds",
                "hard_bounds",
            ],
        ) {
            return None;
        }
        // `missing`, multi-value range-typed inputs, and every non-listed
        // param are handled only by the brute path — bail (return None) so
        // those requests stay exact.
        let field = params.get("field").and_then(Value::as_str)?;
        // Require a real numeric doc-values column. A Keyword (string) column,
        // a range-typed field (stored differently), or a field that lives only
        // in the memtable (`Ok(None)`) all fall back to the exact brute path —
        // a Numeric segment column proves the mapping is plain-numeric, so the
        // memtable fold below (`extract_numeric_values`) is exact too.
        match self.seg_field_kind(field) {
            Ok(Some(ColKind::Numeric)) => {}
            _ => return None,
        }
        let interval = params
            .get("interval")
            .and_then(Value::as_f64)
            .filter(|i| *i > 0.0)?;
        let offset = params.get("offset").and_then(Value::as_f64).unwrap_or(0.0);
        let min_doc_count = params
            .get("min_doc_count")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let keyed = params
            .get("keyed")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let extended_bounds = params.get("extended_bounds").and_then(Value::as_object);
        let hard_bounds = params.get("hard_bounds").and_then(Value::as_object);
        let extended_min = extended_bounds.and_then(|b| b.get("min").and_then(Value::as_f64));
        let extended_max = extended_bounds.and_then(|b| b.get("max").and_then(Value::as_f64));
        let hard_min = hard_bounds.and_then(|b| b.get("min").and_then(Value::as_f64));
        let hard_max = hard_bounds.and_then(|b| b.get("max").and_then(Value::as_f64));

        let key_of = |v: f64| -> i64 { ((v - offset) / interval).floor() as i64 };

        let plan = self.plan_subs(sub, false)?;
        let has_row_work = !plan.metrics.is_empty();

        let mut bucket_ids: HashMap<i64, usize> = HashMap::new();
        let mut bucket_keys: Vec<i64> = Vec::new();
        let mut counts: Vec<u64> = Vec::new();
        let mut accs: Vec<Vec<MetricAcc>> = plan.metrics.iter().map(|_| Vec::new()).collect();
        let ensure_bucket = |key: i64,
                             bucket_ids: &mut HashMap<i64, usize>,
                             bucket_keys: &mut Vec<i64>,
                             counts: &mut Vec<u64>,
                             accs: &mut Vec<Vec<MetricAcc>>|
         -> usize {
            *bucket_ids.entry(key).or_insert_with(|| {
                bucket_keys.push(key);
                counts.push(0);
                for a in accs.iter_mut() {
                    a.push(MetricAcc::default());
                }
                bucket_keys.len() - 1
            })
        };

        let mut missing_sort_seen = false;
        // Numeric column: bucket the doc-values integers/doubles directly.
        for si in 0..self.segs.len() {
            let seg = &self.segs[si];
            let Some(Column::Numeric(n)) = seg.col(field) else {
                continue;
            };
            let mut row_slot: Vec<i32> = Vec::with_capacity(seg.docs as usize);
            for row in 0..seg.docs {
                match n.get(row) {
                    // `NumericColumn::data` stores f64 BITS (see its doc
                    // comment) — decode to the real value before bucketing.
                    // Unlike date_histogram (epoch-ms integers) histogram keeps
                    // the fractional value, so DO NOT truncate to i64 here.
                    Some(bits) => {
                        let v = f64::from_bits(bits as u64);
                        let key = key_of(v);
                        let slot = ensure_bucket(
                            key,
                            &mut bucket_ids,
                            &mut bucket_keys,
                            &mut counts,
                            &mut accs,
                        ) as i32;
                        counts[slot as usize] += 1;
                        row_slot.push(slot);
                    }
                    None => row_slot.push(-1),
                }
            }
            if !has_row_work {
                continue;
            }
            let n_slots = bucket_keys.len();
            let mut tops: Vec<Vec<(f64, u64, DocRef)>> = vec![Vec::new(); n_slots.max(1)];
            {
                let mut slot_of_row = |row: u32| -> Option<usize> {
                    let s = *row_slot.get(row as usize)?;
                    if s < 0 {
                        None
                    } else {
                        Some(s as usize)
                    }
                };
                self.fused_seg_pass(
                    si,
                    &mut slot_of_row,
                    n_slots,
                    &plan,
                    &mut accs,
                    &mut tops,
                    &mut missing_sort_seen,
                )?;
            }
        }

        // Memtable docs — brute multi-value numeric extraction with per-doc
        // bucket dedup, matching `run_histogram`. No `missing` fold (bailed).
        for doc in self.mem().iter() {
            let nums = extract_numeric_values(doc, field);
            if nums.is_empty() {
                continue;
            }
            let weight = doc_count_weight(doc);
            let mut seen: Vec<i64> = Vec::with_capacity(nums.len());
            for v in nums {
                let key = key_of(v);
                if seen.contains(&key) {
                    continue;
                }
                seen.push(key);
                let slot = ensure_bucket(
                    key,
                    &mut bucket_ids,
                    &mut bucket_keys,
                    &mut counts,
                    &mut accs,
                );
                counts[slot] += weight;
                for (mi, spec) in plan.metrics.iter().enumerate() {
                    Self::fold_mem_metric(doc, spec, &mut accs[mi][slot]);
                }
            }
        }

        // ── Bucket-key set (mirrors run_histogram exactly) ────────────────
        // Including the cap: same `aggs::max_buckets_i64()` accessor, read
        // once above the fill, so the two paths reject the same spans.
        let bucket_cap = crate::aggs::max_buckets_i64();
        let mut final_keys: Vec<i64> = if bucket_ids.is_empty() && extended_min.is_none() {
            Vec::new()
        } else if min_doc_count > 0 && extended_min.is_none() {
            bucket_ids.keys().copied().collect()
        } else {
            let data_min = bucket_ids.keys().min().copied();
            let data_max = bucket_ids.keys().max().copied();
            // #1819: the wider of the bounds and the data, as in
            // `run_histogram` — `extended_bounds` never drops data buckets.
            let min_key = match (extended_min.map(key_of), data_min) {
                (Some(e), Some(d)) => e.min(d),
                (e, d) => e.or(d).unwrap_or(0),
            };
            let max_key = match (extended_max.map(key_of), data_max) {
                (Some(e), Some(d)) => e.max(d),
                (e, d) => e.or(d).unwrap_or(0),
            };
            let span = max_key.saturating_sub(min_key);
            if span > bucket_cap {
                return Some(json!({
                    "error": format!(
                        "Trying to create too many buckets. Must be less than or equal to: [{}] but this number of buckets was exceeded. This limit can be set by changing the [search.max_buckets] cluster level setting.",
                        bucket_cap
                    ),
                    "__error_status__": 400u32,
                }));
            }
            let mut keys = Vec::with_capacity((span as usize).min(bucket_cap as usize) + 1);
            let mut k = min_key;
            while k <= max_key {
                keys.push(k);
                k += 1;
            }
            keys
        };
        final_keys.sort_unstable();

        if let (Some(h_min), Some(h_max)) = (hard_min, hard_max) {
            let hard_min_key = key_of(h_min);
            let hard_max_key = key_of(h_max);
            final_keys.retain(|&k| k >= hard_min_key && k <= hard_max_key);
        }
        if min_doc_count > 0 {
            final_keys.retain(|k| {
                bucket_ids
                    .get(k)
                    .map(|&s| counts[s] >= min_doc_count)
                    .unwrap_or(false)
            });
        }

        let format_pattern = params.get("format").and_then(Value::as_str);
        let empty_accs: Vec<MetricAcc> = vec![MetricAcc::default(); plan.metrics.len()];
        let mut result_buckets: Vec<Value> = Vec::with_capacity(final_keys.len());
        for &key in &final_keys {
            let slot = bucket_ids.get(&key).copied();
            let count = slot.map(|s| counts[s]).unwrap_or(0);
            let actual_key = key as f64 * interval + offset;
            let key_json = if actual_key.fract() == 0.0 {
                json!(actual_key as i64)
            } else {
                json!(actual_key)
            };
            let mut bucket = Map::new();
            bucket.insert("key".to_string(), key_json);
            bucket.insert("doc_count".to_string(), json!(count));
            if let Some(p) = format_pattern {
                bucket.insert(
                    "key_as_string".to_string(),
                    Value::String(format_number_pattern(actual_key, p)),
                );
            }
            let bucket_accs: Vec<MetricAcc> = match slot {
                Some(s) => plan
                    .metrics
                    .iter()
                    .enumerate()
                    .map(|(mi, _)| accs[mi][s])
                    .collect(),
                None => empty_accs.clone(),
            };
            self.finish_bucket(&mut bucket, &plan, &bucket_accs, None);
            result_buckets.push(Value::Object(bucket));
        }

        // Sibling pipeline ops (derivative, cumulative_sum, …) operate on the
        // ordered bucket list before keying, same as date_histogram.
        let result_buckets = apply_bucket_pipeline_ops(result_buckets, sub);
        if keyed {
            // Map key: `key_as_string` when a format is set, else the plain
            // numeric key rendered by `format_histogram_key` — identical to the
            // brute path (aggs::run_histogram).
            let mut map = Map::new();
            for b in result_buckets {
                let label = b
                    .get("key_as_string")
                    .and_then(Value::as_str)
                    .map(str::to_string)
                    .or_else(|| {
                        b.get("key")
                            .and_then(Value::as_f64)
                            .map(format_histogram_key)
                    })
                    .unwrap_or_default();
                map.insert(label, b);
            }
            Some(json!({ "buckets": Value::Object(map) }))
        } else {
            Some(json!({ "buckets": result_buckets }))
        }
    }
}

fn metric_type_name(kind: MetricKind) -> &'static str {
    match kind {
        MetricKind::Avg => "avg",
        MetricKind::Sum => "sum",
        MetricKind::Min => "min",
        MetricKind::Max => "max",
        MetricKind::Stats => "stats",
        MetricKind::ValueCount => "value_count",
    }
}

fn merge_acc(into: &mut MetricAcc, other: &MetricAcc) {
    if other.count == 0 {
        return;
    }
    if into.count == 0 {
        *into = *other;
        return;
    }
    into.count += other.count;
    into.sum += other.sum;
    if other.min < into.min {
        into.min = other.min;
    }
    if other.max > into.max {
        into.max = other.max;
    }
}

/// Keep the top-`k` (by sort value + corpus-rank tiebreak) entries.
fn push_top(buf: &mut Vec<(f64, u64, DocRef)>, k: usize, desc: bool, v: f64, rank: u64, r: DocRef) {
    buf.push((v, rank, r));
    if buf.len() > k.saturating_mul(2).max(16) {
        sort_top(buf, desc);
        buf.truncate(k);
    }
}

fn sort_top(buf: &mut [(f64, u64, DocRef)], desc: bool) {
    buf.sort_by(|a, b| {
        let c = if desc {
            b.0.partial_cmp(&a.0)
        } else {
            a.0.partial_cmp(&b.0)
        }
        .unwrap_or(std::cmp::Ordering::Equal);
        c.then_with(|| a.1.cmp(&b.1))
    });
}

/// Parse a terms `order` param into (path, asc) entries — mirror of the
/// closure in `run_terms`.
fn parse_orders(params: &Value) -> Vec<(String, bool)> {
    let order = match params.get("order") {
        Some(v) => v,
        None => return Vec::new(),
    };
    let mut out: Vec<(String, bool)> = Vec::new();
    match order {
        Value::Object(o) => {
            for (k, v) in o {
                let asc = v.as_str().map(|s| s == "asc").unwrap_or(false);
                out.push((k.clone(), asc));
            }
        }
        Value::Array(arr) => {
            for item in arr {
                if let Some(o) = item.as_object() {
                    for (k, v) in o {
                        let asc = v.as_str().map(|s| s == "asc").unwrap_or(false);
                        out.push((k.clone(), asc));
                    }
                }
            }
        }
        _ => {}
    }
    out
}

/// `cmp_terms_by_orders` for (key, count) with no sub-agg entries.
fn cmp_by_orders(
    a: &(String, u64),
    b: &(String, u64),
    orders: &[(String, bool)],
) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    if orders.is_empty() {
        return b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0));
    }
    for (path, asc) in orders {
        let ord = match path.as_str() {
            "_count" => a.1.cmp(&b.1),
            "_key" => a.0.cmp(&b.0),
            _ => Ordering::Equal,
        };
        let ord = if *asc { ord } else { ord.reverse() };
        if ord != Ordering::Equal {
            return ord;
        }
    }
    a.0.cmp(&b.0)
}

/// Composite key comparison for terms-only sources (mirror of the brute
/// sort: numeric when both sides parse as f64, else lexicographic; asc).
/// Per-source composite key comparison — delegates each part to the
/// mapping-driven `composite_part_cmp` so this fast arm sorts exactly
/// like the brute `run_composite` (keyword sources lexicographic,
/// numeric mappings numeric, unmapped → legacy parse heuristic).
fn composite_cmp(
    a: &[String],
    b: &[String],
    kinds: &[crate::aggs::CompositeKeyKind],
) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    for i in 0..a.len().min(b.len()) {
        let kind = kinds
            .get(i)
            .copied()
            .unwrap_or(crate::aggs::CompositeKeyKind::Heuristic);
        let cmp = crate::aggs::composite_part_cmp(kind, false, &a[i], &b[i]);
        if cmp != Ordering::Equal {
            return cmp;
        }
    }
    a.len().cmp(&b.len())
}

/// True when a sub-agg tree references background-corpus semantics the
/// sampler fast path can't provide (it hands the sample as `all_docs`).
fn sub_tree_needs_background(sub: &Value) -> bool {
    match sub {
        Value::Object(o) => o.iter().any(|(k, v)| {
            matches!(
                k.as_str(),
                "significant_terms" | "significant_text" | "global"
            ) || (k == "min_doc_count" && v.as_u64() == Some(0))
                || sub_tree_needs_background(v)
        }),
        Value::Array(a) => a.iter().any(sub_tree_needs_background),
        _ => false,
    }
}

// ── predicate compilation (filter / filters / adjacency_matrix) ─────────────

enum Pred {
    MatchAll,
    TermKw {
        field: String,
        value: String,
    },
    TermsKw {
        field: String,
        values: Vec<String>,
    },
    RangeNum {
        field: String,
        lo: f64,
        lo_incl: bool,
        hi: f64,
        hi_incl: bool,
    },
    /// Lexicographic range over a keyword-backed column.  This is what serves
    /// **date** ranges: the `.dv` builder keys columns off the stored JSON
    /// type, and a date's `_source` value is a *string*, so date fields live in
    /// `Column::Keyword`, not `Column::Numeric`.  Before this variant existed,
    /// `{"range":{"<date>":{…}}}` compiled to `RangeNum`, hit the
    /// `Column::Keyword => return None` arm in `resolve_pred`, and bailed the
    /// entire aggregation to the brute `_source` path — measured at ~9.9 s for
    /// a one-day window over 1.12 M docs versus ~0.16 s for the same agg with
    /// no date filter (i.e. *narrowing* the query made it ~60× slower).
    ///
    /// Correctness rests on ordinal order == value order.  `KeywordColumn`
    /// assigns ordinals in lexicographic order, so this is exact whenever
    /// lexicographic order agrees with the field's semantic order:
    ///   * keyword fields — ES range semantics *are* lexicographic;
    ///   * date fields — true for the canonical fixed-width RFC3339
    ///     `%Y-%m-%dT%H:%M:%S%.3fZ` form the query parser emits and the
    ///     ingest path normalises to.
    ///
    /// `resolve_pred` enforces that invariant per segment and bails to brute
    /// on any dictionary that is not uniformly canonical, so a mixed-width
    /// column (e.g. hand-indexed `"2026-06-01"` alongside full timestamps)
    /// keeps the exact legacy behaviour rather than silently mis-ranging.
    RangeKw {
        field: String,
        lo: Option<String>,
        lo_incl: bool,
        hi: Option<String>,
        hi_incl: bool,
    },
    /// `exists: {field}` — the row's column entry is non-null.  Brute
    /// parity, both legs:
    /// * segments — `doc_matches_query_typed`'s Exists arm resolves the
    ///   `_source` field and applies `value_present` (Null → false, arrays →
    ///   any-present, everything else — including objects and `""` — →
    ///   true).  The column builder pushes nothing for null values, so a
    ///   non-null column row ⇔ a present `_source` value for every scalar
    ///   shape; object/array/multi-valued shapes never get a column and are
    ///   caught by `miss_is_genuinely_empty`/`field_needs_brute_fallback`.
    /// * memtable — `doc_matches_filter`'s exists arm; its one divergence
    ///   from `value_present` (a directly-object-valued field:
    ///   `flatten(Object)=[]` vs `value_present(Object)=true`) is closed in
    ///   `aggs.rs` alongside this variant.
    ///
    /// Meta fields (`_id`, `_index`, …) are answered from bookkeeping on the
    /// brute query path (always true) but have no column and no consistent
    /// memtable answer (owned views inject `_id`, shared views don't) →
    /// bail at compile.
    Exists {
        field: String,
    },
    /// Conjunction of leaf predicates — a `bool` with only `must`/`filter`
    /// clauses (produced by `compile_top_pred` for the top-level query filter;
    /// `compile_pred` never yields this, so the filter/filters/adjacency
    /// executors are unaffected).
    And(Vec<Pred>),
}

/// Compile a TOP-LEVEL query filter (`{size:0, query:Q, aggs:…}`) into a
/// columnar predicate.  Leaves delegate to the trusted `compile_pred` (kept
/// perfectly in sync with `doc_matches_filter`); a `bool` with only
/// `must`/`filter` clauses becomes a pure conjunction.  Anything else
/// (must_not, should, minimum_should_match, FTS leaves, …) → `None`, so the
/// caller falls back to the exact brute path.
fn compile_top_pred(filter: &Value) -> Option<Pred> {
    let obj = filter.as_object()?;
    if obj.len() != 1 {
        return None;
    }
    let (qtype, body) = obj.iter().next()?;
    if qtype == "bool" {
        let bo = body.as_object()?;
        if bo.keys().any(|k| k != "must" && k != "filter") {
            return None; // must_not / should / minimum_should_match → bail
        }
        let mut subs: Vec<Pred> = Vec::new();
        for key in ["must", "filter"] {
            if let Some(clauses) = bo.get(key) {
                let arr = clauses.as_array()?;
                for c in arr {
                    subs.push(compile_top_pred(c)?);
                }
            }
        }
        return match subs.len() {
            0 => Some(Pred::MatchAll),
            1 => Some(subs.into_iter().next().unwrap()),
            _ => Some(Pred::And(subs)),
        };
    }
    compile_pred(filter)
}

/// Structural equivalent of the old
/// `aggs_def.to_string().contains("top_hits" | "\"_id\"" | ...)` probe.
/// Returns true when the agg tree references a meta field, meaning the
/// memtable docs must be materialised OWNED (with `_id`/`_index`/`_seq_no`
/// injected) rather than Arc-shared.  Conservative: a false positive only
/// costs an extra clone, never correctness — so this deliberately mirrors
/// the substring semantics (`top_hits` anywhere; the meta fields as exact
/// key/string tokens, i.e. the serialized quoted form).
fn agg_tree_mentions_meta(v: &Value) -> bool {
    fn is_meta(s: &str) -> bool {
        s.contains("top_hits") || s == "_id" || s == "_index" || s == "_seq_no"
    }
    match v {
        Value::Object(m) => m
            .iter()
            .any(|(k, val)| is_meta(k) || agg_tree_mentions_meta(val)),
        Value::Array(a) => a.iter().any(agg_tree_mentions_meta),
        Value::String(s) => is_meta(s),
        _ => false,
    }
}

/// Compile the (single-clause) filter queries `doc_matches_filter` supports
/// into a columnar predicate.  Anything not exactly mirrored → `None`.
fn compile_pred(filter: &Value) -> Option<Pred> {
    let obj = filter.as_object()?;
    if obj.len() != 1 {
        return None;
    }
    let (qtype, body) = obj.iter().next()?;
    match qtype.as_str() {
        "match_all" => Some(Pred::MatchAll),
        "term" => {
            let fm = body.as_object()?;
            if fm.len() != 1 {
                return None;
            }
            let (field, expected) = fm.iter().next()?;
            let value = match expected {
                Value::String(s) => s.clone(),
                Value::Object(o) => match o.get("value") {
                    Some(Value::String(s)) => s.clone(),
                    _ => return None,
                },
                _ => return None, // numeric/bool string-form subtleties → bail
            };
            Some(Pred::TermKw {
                field: field.clone(),
                value,
            })
        }
        "terms" => {
            let fm = body.as_object()?;
            if fm.len() != 1 {
                return None;
            }
            let (field, expected) = fm.iter().next()?;
            let arr = expected.as_array()?;
            let mut values = Vec::with_capacity(arr.len());
            for v in arr {
                match v {
                    Value::String(s) => values.push(s.clone()),
                    _ => return None,
                }
            }
            Some(Pred::TermsKw {
                field: field.clone(),
                values,
            })
        }
        "range" => {
            let fm = body.as_object()?;
            if fm.len() != 1 {
                return None;
            }
            let (field, bounds) = fm.iter().next()?;
            let bo = bounds.as_object()?;
            if !bo
                .keys()
                .all(|k| matches!(k.as_str(), "gte" | "gt" | "lte" | "lt"))
            {
                return None;
            }
            // String bounds → lexicographic (keyword/date) range.  All present
            // bounds must agree on kind; a mixed `{gte: 1, lt: "2026-01-01"}`
            // has no single columnar form, so it stays on the brute path.
            let str_bounds = ["gte", "gt", "lte", "lt"]
                .iter()
                .filter_map(|k| bo.get(*k))
                .all(|v| v.is_string());
            let any_bound = ["gte", "gt", "lte", "lt"]
                .iter()
                .any(|k| bo.contains_key(*k));
            if any_bound && str_bounds {
                let get_str = |k: &str| -> Option<Option<String>> {
                    match bo.get(k) {
                        None => Some(None),
                        Some(Value::String(s)) => Some(Some(s.clone())),
                        Some(_) => None,
                    }
                };
                let gte = get_str("gte")?;
                let gt = get_str("gt")?;
                let lte = get_str("lte")?;
                let lt = get_str("lt")?;
                let (lo, lo_incl) = match (gte, gt) {
                    (Some(v), _) => (Some(v), true),
                    (None, Some(v)) => (Some(v), false),
                    (None, None) => (None, true),
                };
                let (hi, hi_incl) = match (lte, lt) {
                    (Some(v), _) => (Some(v), true),
                    (None, Some(v)) => (Some(v), false),
                    (None, None) => (None, true),
                };
                return Some(Pred::RangeKw {
                    field: field.clone(),
                    lo,
                    lo_incl,
                    hi,
                    hi_incl,
                });
            }
            let get_num = |k: &str| -> Option<Option<f64>> {
                match bo.get(k) {
                    None => Some(None),
                    Some(Value::Number(n)) => Some(n.as_f64()),
                    Some(_) => None,
                }
            };
            let gte = get_num("gte")?;
            let gt = get_num("gt")?;
            let lte = get_num("lte")?;
            let lt = get_num("lt")?;
            let (lo, lo_incl) = match (gte, gt) {
                (Some(v), _) => (v, true),
                (None, Some(v)) => (v, false),
                (None, None) => (f64::NEG_INFINITY, true),
            };
            let (hi, hi_incl) = match (lte, lt) {
                (Some(v), _) => (v, true),
                (None, Some(v)) => (v, false),
                (None, None) => (f64::INFINITY, true),
            };
            Some(Pred::RangeNum {
                field: field.clone(),
                lo,
                lo_incl,
                hi,
                hi_incl,
            })
        }
        "exists" => {
            if !params_only(body, &["field"]) {
                return None;
            }
            let field = body.get("field").and_then(Value::as_str)?;
            if field.is_empty() || field.starts_with('_') {
                // Meta fields: brute's Exists arm answers them from
                // bookkeeping (`_id`/`_index`/`_seq_no` always true,
                // `_routing` from source), not from a column — there is no
                // columnar equivalent to stay in sync with.
                return None;
            }
            Some(Pred::Exists {
                field: field.to_owned(),
            })
        }
        _ => None,
    }
}

/// What a missing column means for a predicate on `field`.
///
/// `Some(SegPred::Never)` is an ASSERTION that the segment genuinely holds
/// no matching row.  That assertion only holds when EVERY brute resolver
/// would also find nothing under this name.  It is false for a multi-field
/// suffix one of them resolves by stripping (the widest,
/// `index.rs::get_field_value` behind a top-level query filter, strips
/// trailing segments recursively, so `<field>.raw.raw` counts too); for a
/// scalar leaf nested under an object (`geo.city`, resolved by recursing
/// into the `_source` object); and for a top-level field whose column was
/// suppressed because it is multi-valued (`tags`, read straight from the
/// `_source` array).  All three are exactly what
/// [`field_needs_brute_fallback`] detects, so this defers to it: returning
/// `Never` for any of them is how a `filters`/`filter`/top-level-query
/// predicate reported a small plausible count instead of the real one.
/// `None` bails the whole request to the exact brute path.
fn miss_is_genuinely_empty<'a>(
    field: &str,
    segs: &[SegEntry],
    mapped_fields: &std::collections::HashSet<String>,
) -> Option<SegPred<'a>> {
    if field_needs_brute_fallback(field, segs, mapped_fields) {
        None
    } else {
        Some(SegPred::Never)
    }
}

enum SegPred<'a> {
    Never,
    Always,
    /// Last bool = column has no nulls (hoisted roaring probe).
    KwEq(&'a KeywordColumn, u32, bool),
    KwIn(&'a KeywordColumn, Vec<u32>, bool),
    /// Half-open ordinal window `[lo_ord, hi_ord)` over a keyword column's
    /// lexicographically-sorted dictionary.  Last bool = column has no nulls.
    KwRange(&'a KeywordColumn, u32, u32, bool),
    Num(&'a NumericColumn, f64, bool, f64, bool, bool),
    /// `exists` — the row carries a non-null keyword / numeric value.
    KwExists(&'a KeywordColumn),
    NumExists(&'a NumericColumn),
    /// `exists` on a `doc_values: false` field. The bitmap is the set of
    /// rows `value_present` accepted at flush.
    PresExists(&'a PresenceColumn),
    /// Conjunction — every sub-predicate must match the row.
    And(Vec<SegPred<'a>>),
}

/// Columnarise `pred` against one segment's doc-values.
///
/// `None` means "this shape is not reproducible columnarly" and bails the
/// whole request to the exact brute path. A resolved `SegPred::Never`, by
/// contrast, is an assertion that the segment genuinely holds no matching
/// row — so every column lookup here MUST use [`dv_col`]'s `.keyword`
/// fallback. Resolving the name differently from the agg targets is what
/// turned a `<field>.keyword` filter into a silent segment-wide `Never`.
///
/// A miss on a name the brute reference WOULD resolve is therefore not a
/// `Never` at all — see [`miss_is_genuinely_empty`], which needs the whole
/// segment set and the schema's mapped-field names to tell a genuine absence
/// from a nested/suppressed field the columns simply cannot represent.
fn resolve_pred<'a>(
    cols: &'a super::DocValueMap,
    pred: &Pred,
    segs: &[SegEntry],
    mapped_fields: &std::collections::HashSet<String>,
) -> Option<SegPred<'a>> {
    Some(match pred {
        Pred::MatchAll => SegPred::Always,
        Pred::TermKw { field, value } => match dv_col(cols, field) {
            Some(Column::Keyword(k)) => match k.ord_for_term(value) {
                Some(ord) => SegPred::KwEq(k, ord, k.null_bitmap.is_empty()),
                None => SegPred::Never,
            },
            Some(Column::Numeric(_)) | Some(Column::Presence(_)) => return None,
            None => miss_is_genuinely_empty(field, segs, mapped_fields)?,
        },
        Pred::TermsKw { field, values } => match dv_col(cols, field) {
            Some(Column::Keyword(k)) => {
                let ords: Vec<u32> = values.iter().filter_map(|v| k.ord_for_term(v)).collect();
                if ords.is_empty() {
                    SegPred::Never
                } else {
                    SegPred::KwIn(k, ords, k.null_bitmap.is_empty())
                }
            }
            Some(Column::Numeric(_)) | Some(Column::Presence(_)) => return None,
            None => miss_is_genuinely_empty(field, segs, mapped_fields)?,
        },
        Pred::RangeKw {
            field,
            lo,
            lo_incl,
            hi,
            hi_incl,
        } => match dv_col(cols, field) {
            Some(Column::Keyword(k)) => {
                let terms = &k.terms;
                if terms.is_empty() {
                    return Some(SegPred::Never);
                }
                // Order-safety gate (see `Pred::RangeKw`).  Ordinals are
                // lexicographic; we may only use them as a value range when
                // byte order is guaranteed to agree with the field's semantic
                // order.  Equal-width strings give that unconditionally — it
                // is exactly the shape of canonical RFC3339
                // `%Y-%m-%dT%H:%M:%S%.3fZ` timestamps, and of fixed-width
                // keyword codes.  Anything ragged (mixed `"2026-06-01"` and
                // `"2026-06-01T00:00:00.000Z"`, or free-text keywords) bails
                // to the exact brute path rather than risk a wrong window.
                let width = terms[0].len();
                if !terms.iter().all(|t| t.len() == width) {
                    return None;
                }
                if lo.as_ref().is_some_and(|s| s.len() != width)
                    || hi.as_ref().is_some_and(|s| s.len() != width)
                {
                    return None;
                }
                // Half-open ordinal window over the sorted dictionary.
                let lo_ord = match lo {
                    None => 0u32,
                    Some(b) => terms.partition_point(|t| {
                        if *lo_incl {
                            t.as_str() < b.as_str()
                        } else {
                            t.as_str() <= b.as_str()
                        }
                    }) as u32,
                };
                let hi_ord = match hi {
                    None => terms.len() as u32,
                    Some(b) => terms.partition_point(|t| {
                        if *hi_incl {
                            t.as_str() <= b.as_str()
                        } else {
                            t.as_str() < b.as_str()
                        }
                    }) as u32,
                };
                if lo_ord >= hi_ord {
                    SegPred::Never
                } else {
                    SegPred::KwRange(k, lo_ord, hi_ord, k.null_bitmap.is_empty())
                }
            }
            Some(Column::Numeric(_)) | Some(Column::Presence(_)) => return None,
            None => miss_is_genuinely_empty(field, segs, mapped_fields)?,
        },
        Pred::RangeNum {
            field,
            lo,
            lo_incl,
            hi,
            hi_incl,
        } => match dv_col(cols, field) {
            Some(Column::Numeric(n)) => {
                SegPred::Num(n, *lo, *lo_incl, *hi, *hi_incl, n.null_bitmap.is_empty())
            }
            Some(Column::Keyword(_)) | Some(Column::Presence(_)) => return None,
            None => miss_is_genuinely_empty(field, segs, mapped_fields)?,
        },
        Pred::Exists { field } => match dv_col(cols, field) {
            Some(Column::Keyword(k)) => SegPred::KwExists(k),
            Some(Column::Numeric(n)) => SegPred::NumExists(n),
            Some(Column::Presence(p)) => SegPred::PresExists(p),
            None => miss_is_genuinely_empty(field, segs, mapped_fields)?,
        },
        Pred::And(subs) => {
            let mut resolved: Vec<SegPred<'a>> = Vec::with_capacity(subs.len());
            for s in subs {
                let sp = resolve_pred(cols, s, segs, mapped_fields)?;
                if matches!(sp, SegPred::Never) {
                    return Some(SegPred::Never); // short-circuit: whole AND is empty
                }
                resolved.push(sp);
            }
            SegPred::And(resolved)
        }
    })
}

#[inline]
fn seg_pred_matches(sp: &SegPred<'_>, row: u32) -> bool {
    match sp {
        SegPred::Never => false,
        SegPred::Always => true,
        SegPred::KwEq(k, ord, no_nulls) => {
            if *no_nulls {
                k.ords.get(row as usize) == Some(ord)
            } else {
                k.ord_for(row) == Some(*ord)
            }
        }
        SegPred::KwIn(k, ords, no_nulls) => {
            let o = if *no_nulls {
                k.ords.get(row as usize).copied()
            } else {
                k.ord_for(row)
            };
            match o {
                Some(o) => ords.contains(&o),
                None => false,
            }
        }
        SegPred::KwRange(k, lo_ord, hi_ord, no_nulls) => {
            let o = if *no_nulls {
                k.ords.get(row as usize).copied()
            } else {
                k.ord_for(row)
            };
            match o {
                Some(o) => o >= *lo_ord && o < *hi_ord,
                None => false,
            }
        }
        SegPred::Num(n, lo, lo_incl, hi, hi_incl, no_nulls) => {
            if !*no_nulls && n.null_bitmap.contains(row) {
                return false;
            }
            let v = f64::from_bits(n.data[row as usize] as u64);
            let lo_ok = if *lo_incl { v >= *lo } else { v > *lo };
            let hi_ok = if *hi_incl { v <= *hi } else { v < *hi };
            lo_ok && hi_ok
        }
        SegPred::KwExists(k) => k.ord_for(row).is_some(),
        SegPred::NumExists(n) => !n.null_bitmap.contains(row),
        SegPred::PresExists(p) => p.contains(row),
        SegPred::And(subs) => subs.iter().all(|s| seg_pred_matches(s, row)),
    }
}

fn seg_pred_count(sp: &SegPred<'_>, docs: u32) -> u64 {
    match sp {
        SegPred::Never => 0,
        SegPred::Always => docs as u64,
        SegPred::KwEq(k, ord, _) => k.per_ord_count.get(*ord as usize).copied().unwrap_or(0) as u64,
        SegPred::KwIn(k, ords, _) => ords
            .iter()
            .map(|o| k.per_ord_count.get(*o as usize).copied().unwrap_or(0) as u64)
            .sum(),
        // O(window) over the per-ordinal histogram — no row scan needed.
        SegPred::KwRange(k, lo_ord, hi_ord, _) => k
            .per_ord_count
            .get(*lo_ord as usize..*hi_ord as usize)
            .map(|s| s.iter().map(|c| *c as u64).sum())
            .unwrap_or(0),
        SegPred::Num(n, lo, lo_incl, hi, hi_incl, _) => n.range_count(*lo, *hi, *lo_incl, *hi_incl),
        // Non-null rows: with multi-valued fields column-suppressed, each row
        // carries at most one ord, so the per-ordinal histogram sums to the
        // non-null row count (same form as `KwIn` above).  `live_count` is
        // the numeric column's own precomputed non-null count.
        SegPred::KwExists(k) => k.per_ord_count.iter().map(|c| *c as u64).sum(),
        SegPred::NumExists(n) => n.live_count,
        // Exact for any density. Delete-blind, like the other O(1) arms;
        // dirty segments row-scan via `seg_pred_matches` instead.
        SegPred::PresExists(p) => p.count(),
        // Conjunction has no O(1) form — count matching rows directly.  Only
        // reached from the top-level filter count (compile_pred, used by the
        // filter/filters executors, never yields `And`).
        SegPred::And(_) => (0..docs).filter(|&row| seg_pred_matches(sp, row)).count() as u64,
    }
}

// ── variable_width_histogram weighted clustering ─────────────────────────────

pub(super) struct VwhBucket {
    pub min: f64,
    pub max: f64,
    pub sum: f64,
    pub count: u64,
}

/// Weighted replay of the brute adaptive-merge clustering
/// (`run_variable_width_histogram`): the brute algorithm starts from one
/// bucket per value *instance* and repeatedly merges the adjacent pair with
/// the strictly-smallest centroid gap (earliest pair wins ties).  All
/// zero-gap pairs (duplicate values) merge before any positive gap, and
/// they merge left-to-right, so the instance-level process is exactly
/// reproducible from the sorted distinct (value, weight) sequence.
/// K-way merge of value-ascending `(value, weight)` runs into one distinct
/// ascending list, summing weights of equal values across runs.
fn merge_weighted_runs(mut runs: Vec<Vec<(f64, u64)>>) -> Vec<(f64, u64)> {
    match runs.len() {
        0 => return Vec::new(),
        1 => return runs.pop().unwrap(),
        _ => {}
    }
    use std::cmp::Reverse;
    use std::collections::BinaryHeap;
    // Heap entries keyed on the value's total_cmp bit pattern (all runs come
    // from finite doc values, so the sign-flip trick keeps ordering exact).
    fn key(v: f64) -> u64 {
        let b = v.to_bits();
        if b >> 63 == 1 {
            !b
        } else {
            b | (1 << 63)
        }
    }
    let total: usize = runs.iter().map(Vec::len).sum();
    let mut out: Vec<(f64, u64)> = Vec::with_capacity(total);
    let mut heap: BinaryHeap<Reverse<(u64, usize)>> = BinaryHeap::new();
    let mut pos: Vec<usize> = vec![0; runs.len()];
    for (ri, run) in runs.iter().enumerate() {
        if let Some(&(v, _)) = run.first() {
            heap.push(Reverse((key(v), ri)));
        }
    }
    while let Some(Reverse((_, ri))) = heap.pop() {
        let (v, w) = runs[ri][pos[ri]];
        match out.last_mut() {
            Some((lv, lw)) if *lv == v => *lw += w,
            _ => out.push((v, w)),
        }
        pos[ri] += 1;
        if let Some(&(nv, _)) = runs[ri].get(pos[ri]) {
            heap.push(Reverse((key(nv), ri)));
        }
    }
    out
}

/// Coarsen an ascending distinct `(value, weight)` list into at most `cap`
/// equal-weight groups, each represented by its weighted mean.  Order and
/// total weight are preserved; only used above the exact-clustering budget
/// where the reference (brute) implementation cannot run anyway.
fn coarsen_weighted(vals: &[(f64, u64)], cap: usize) -> Vec<(f64, u64)> {
    let total_w: u64 = vals.iter().map(|&(_, w)| w).sum();
    let per_group: u64 = total_w.div_ceil(cap as u64).max(1);
    let mut out: Vec<(f64, u64)> = Vec::with_capacity(cap + 1);
    let mut g_sum = 0.0_f64;
    let mut g_w = 0_u64;
    for &(v, w) in vals {
        g_sum += v * w as f64;
        g_w += w;
        if g_w >= per_group {
            out.push((g_sum / g_w as f64, g_w));
            g_sum = 0.0;
            g_w = 0;
        }
    }
    if g_w > 0 {
        out.push((g_sum / g_w as f64, g_w));
    }
    out
}

fn vwh_cluster(vals: &[(f64, u64)], num_buckets: usize) -> Vec<VwhBucket> {
    let n_total: u64 = vals.iter().map(|(_, w)| w).sum();
    let effective: u64 = (num_buckets as u64).min(n_total).max(1);
    let mut merges_needed: u64 = n_total - effective;
    let zero_merges: u64 = n_total - vals.len() as u64;

    if merges_needed <= zero_merges {
        // Phase A only: duplicates collapse left-to-right until the target
        // bucket count is reached.
        let mut out: Vec<VwhBucket> = Vec::new();
        for &(v, w) in vals {
            if merges_needed >= w - 1 {
                merges_needed -= w - 1;
                out.push(VwhBucket {
                    min: v,
                    max: v,
                    sum: v * w as f64,
                    count: w,
                });
            } else {
                // Partially collapsed run: one merged bucket of
                // (merges_needed + 1) instances, then singletons.
                let m = merges_needed;
                merges_needed = 0;
                out.push(VwhBucket {
                    min: v,
                    max: v,
                    sum: v * (m + 1) as f64,
                    count: m + 1,
                });
                for _ in 0..(w - 1 - m) {
                    out.push(VwhBucket {
                        min: v,
                        max: v,
                        sum: v,
                        count: 1,
                    });
                }
            }
        }
        return out;
    }

    // Phase B: all duplicates collapsed; merge weighted adjacent buckets by
    // centroid distance (smallest gap, earliest pair) until `effective`
    // buckets remain.  Heap + doubly-linked list = O(d log d).
    let mut remaining = merges_needed - zero_merges;
    let d = vals.len();
    let mut sum: Vec<f64> = vals.iter().map(|&(v, w)| v * w as f64).collect();
    let mut cnt: Vec<u64> = vals.iter().map(|&(_, w)| w).collect();
    let mut mn: Vec<f64> = vals.iter().map(|&(v, _)| v).collect();
    let mut mx: Vec<f64> = vals.iter().map(|&(v, _)| v).collect();
    let mut next: Vec<usize> = (0..d).map(|i| i + 1).collect(); // d = sentinel end
    let mut prev: Vec<usize> = (0..d).map(|i| i.wrapping_sub(1)).collect();
    let mut gen: Vec<u64> = vec![0; d];
    let mut alive: Vec<bool> = vec![true; d];

    use std::cmp::Reverse;
    use std::collections::BinaryHeap;
    #[derive(PartialEq, Eq, PartialOrd, Ord)]
    struct Entry(
        u64,   /*gap bits (total_cmp key)*/
        usize, /*left idx*/
        u64,   /*gen sum*/
    );
    let gap_key = |g: f64| -> u64 {
        // total_cmp-compatible ordering for non-negative floats.
        g.to_bits()
    };
    let mut heap: BinaryHeap<Reverse<Entry>> = BinaryHeap::new();
    let centroid = |i: usize, sum: &[f64], cnt: &[u64]| sum[i] / cnt[i] as f64;
    for i in 0..d.saturating_sub(1) {
        let g = (centroid(i + 1, &sum, &cnt) - centroid(i, &sum, &cnt)).abs();
        heap.push(Reverse(Entry(gap_key(g), i, 0)));
    }
    while remaining > 0 {
        let Some(Reverse(Entry(_, left, gsum))) = heap.pop() else {
            break;
        };
        if !alive[left] {
            continue;
        }
        let right = next[left];
        if right >= d || !alive[right] {
            continue;
        }
        if gen[left] + gen[right] != gsum {
            continue; // stale entry
        }
        // Merge right into left.
        sum[left] += sum[right];
        cnt[left] += cnt[right];
        if mn[right] < mn[left] {
            mn[left] = mn[right];
        }
        if mx[right] > mx[left] {
            mx[left] = mx[right];
        }
        alive[right] = false;
        let rr = next[right];
        next[left] = rr;
        if rr < d {
            prev[rr] = left;
        }
        gen[left] += 1;
        remaining -= 1;
        // Refresh neighbour gaps.
        let pl = prev[left];
        if pl != usize::MAX && pl < d && alive[pl] {
            let g = (centroid(left, &sum, &cnt) - centroid(pl, &sum, &cnt)).abs();
            heap.push(Reverse(Entry(gap_key(g), pl, gen[pl] + gen[left])));
        }
        if rr < d && alive[rr] {
            let g = (centroid(rr, &sum, &cnt) - centroid(left, &sum, &cnt)).abs();
            heap.push(Reverse(Entry(gap_key(g), left, gen[left] + gen[rr])));
        }
    }
    let mut out = Vec::new();
    let mut i = 0usize;
    // Find the first alive bucket.
    while i < d && !alive[i] {
        i += 1;
    }
    while i < d {
        out.push(VwhBucket {
            min: mn[i],
            max: mx[i],
            sum: sum[i],
            count: cnt[i],
        });
        i = next[i];
        while i < d && !alive[i] {
            i += 1;
        }
    }
    out
}

#[cfg(test)]
mod range_kw_tests {
    use super::*;
    use xerj_storage::doc_values::KeywordColumn;

    /// Canonical RFC3339 timestamps, 24 chars — the shape the query parser
    /// emits and the ingest path normalises to.
    fn ts(day: u32, hour: u32) -> String {
        format!("2026-06-{day:02}T{hour:02}:00:00.000Z")
    }

    /// One doc per (day, hour) over 3 days × 24 hours.
    fn cols() -> std::collections::BTreeMap<String, Column> {
        let mut vals: Vec<Option<String>> = Vec::new();
        for day in 1..=3u32 {
            for hour in 0..24u32 {
                vals.push(Some(ts(day, hour)));
            }
        }
        let k = KeywordColumn::from_iter(vals).expect("build column");
        let mut m = std::collections::BTreeMap::new();
        m.insert("ts".to_string(), Column::Keyword(k));
        m
    }

    // Regression: a text field's auto-created `.keyword` multi-field shares
    // the *same* on-disk column, stored under the parent's (unsuffixed)
    // name — confirmed on a real flushed segment, where only `extension.*`
    // files exist on disk, never `extension.keyword.*`. Before `SegEntry::col`
    // existed, every fast-path aggregation (terms, cardinality, ...) did a
    // raw `cols.get("extension.keyword")`, found nothing, and silently
    // treated the segment as having zero rows for that field — every
    // `<field>.keyword` aggregation over a flushed segment returned empty
    // buckets despite the data being right there under `<field>`. Found
    // live: the Kibana/OSD sample "Logs" dashboard's `extension.keyword`,
    // `geo.dest`-adjacent, and `response.keyword` terms panels all went
    // empty once their segment was flushed (memtable-only queries were
    // fine, since the brute-force path already had this `.keyword`
    // fallback for `_source`-walking).
    #[test]
    fn col_falls_back_to_keyword_multi_field_parent() {
        let k = KeywordColumn::from_iter(vec![Some("css".to_string()), Some("gz".to_string())])
            .expect("build column");
        let mut m = std::collections::BTreeMap::new();
        m.insert("extension".to_string(), Column::Keyword(k));
        let seg = SegEntry {
            id: "seg1".to_string(),
            cols: crate::segment_cache_budget::CacheResident::uncached(m),
            docs: 2,
            ghosts: None,
        };
        assert!(
            seg.col("extension").is_some(),
            "direct field lookup must still work"
        );
        assert!(
            seg.col("extension.keyword").is_some(),
            "must fall back to the parent column when the exact `.keyword` name has none"
        );
        // Resolution stays narrow on purpose (#120). Widening `dv_col` would
        // make the fast path CLAIM shapes it cannot prove byte-identical —
        // key typing, bool rendering and composite key kinds all key off the
        // requested name — and there is no single brute behaviour to widen
        // TO: `index.rs::get_field_value` (top-level query filters) strips
        // trailing segments RECURSIVELY, `aggs::get_nested_field` (agg
        // targets, `filters` leaves) strips exactly one, and
        // `extract_array_path_values` (just before it) strips `.keyword`
        // only. So the
        // contract is: resolve exactly, and BAIL to brute for anything else,
        // which is right against all three because after a bail the request
        // is answered by whichever of them it would have been measured
        // against. `dotted_suffix_diverges_from_brute` is the other half —
        // see `multi_field_suffixes_diverge_from_brute_at_any_depth` below.
        assert!(
            seg.col("extension.nonsense").is_none(),
            "must not fall back for suffixes other than `.keyword`"
        );
    }

    /// #120: a multi-field suffix resolves on a brute path but not on the
    /// columnar one, and NOT only at one level of suffixing.
    /// `index.rs::get_field_value` — the resolver a top-level query filter
    /// is measured against — recurses on the parent, so it strips trailing
    /// segments until something leaf-valued answers: `extension.raw.raw`,
    /// `extension.keyword.raw` and `extension.raw.raw.raw` all read
    /// `extension`'s string. Every one of those must be reported so callers
    /// bail, instead of being read as "this segment holds no such data".
    #[test]
    fn multi_field_suffixes_diverge_from_brute_at_any_depth() {
        let k = KeywordColumn::from_iter(vec![Some("css".to_string()), Some("gz".to_string())])
            .expect("build column");
        let mut m = std::collections::BTreeMap::new();
        m.insert("extension".to_string(), Column::Keyword(k));
        for field in [
            "extension.raw",
            "extension.sort",
            "extension.en",
            // Doubly and triply suffixed: `get_field_value`'s fallback is
            // `get_field_value(source, &field[..idx])`, i.e. recursive, so a
            // bail keyed on the IMMEDIATE parent alone still failed closed
            // here — the blocker this test exists for.
            "extension.raw.raw",
            "extension.keyword.raw",
            "extension.raw.keyword",
            "extension.keyword.keyword",
            "extension.raw.raw.raw",
        ] {
            assert!(
                dotted_suffix_diverges_from_brute(&m, field),
                "brute resolves `{field}` to the `extension` column; the fast \
                 path cannot, so it must bail rather than report an empty segment"
            );
        }
        assert!(
            !dotted_suffix_diverges_from_brute(&m, "extension"),
            "the exact name resolves — nothing to bail for"
        );
        assert!(
            !dotted_suffix_diverges_from_brute(&m, "extension.keyword"),
            "`.keyword` already resolves through `dv_col`'s parent fallback"
        );
        assert!(
            !dotted_suffix_diverges_from_brute(&m, "group"),
            "an undotted absent field is a genuine absence"
        );
        // The control that stops the fix degenerating into "every dotted
        // field goes brute". These names are GENUINELY ABSENT — no `nosuchfield`
        // or `a` value exists — so brute's `get_field_value` recursion finds
        // nothing too and the fast path's empty answer is correct. This is the
        // one case where "no ancestor column" and "brute finds nothing" line
        // up; a PRESENT nested-object value (`geo.city`) also has no ancestor
        // column but brute DOES resolve it, which is the separate divergence
        // called out on `dotted_suffix_diverges_from_brute` and not covered
        // here.
        for field in ["nosuchfield.raw", "nosuchfield.raw.raw", "a.b.c.d"] {
            assert!(
                !dotted_suffix_diverges_from_brute(&m, field),
                "`{field}` is genuinely absent — brute finds nothing too, so \
                 an empty answer is correct and bailing would be wasted work"
            );
        }
    }

    /// The predicate half: a miss that a brute path WOULD resolve is not a
    /// `SegPred::Never` (an assertion that the segment matches nothing) but a
    /// bail. `filters`/`filter`/top-level-query predicates all route through
    /// `resolve_pred`, so this one gate covers every predicate site.
    #[test]
    fn suffixed_predicate_bails_instead_of_matching_nothing() {
        let k = KeywordColumn::from_iter(vec![Some("css".to_string()), Some("gz".to_string())])
            .expect("build column");
        let mut cols = std::collections::BTreeMap::new();
        cols.insert("extension".to_string(), Column::Keyword(k));
        // `resolve_pred` now routes a column miss through
        // `field_needs_brute_fallback`, which scans the whole segment set for
        // the ancestor column, so the fixture must be a real segment.
        let segs = vec![seg_with_cols(cols)];
        let mapped = mapped_fields(&["extension"]);
        for field in [
            "extension.raw",
            "extension.raw.raw",
            "extension.keyword.raw",
            "extension.raw.keyword",
            "extension.raw.raw.raw",
        ] {
            let pred = Pred::TermKw {
                field: field.into(),
                value: "css".into(),
            };
            assert!(
                resolve_pred(&segs[0].cols, &pred, &segs, &mapped).is_none(),
                "`{field}` must bail the request to brute, not resolve to Never"
            );
        }
        // Still `Never` (not a bail) where brute genuinely finds nothing.
        let absent = Pred::TermKw {
            field: "nosuchfield.raw".into(),
            value: "css".into(),
        };
        assert!(
            matches!(
                resolve_pred(&segs[0].cols, &absent, &segs, &mapped),
                Some(SegPred::Never)
            ),
            "a genuinely absent dotted field must stay on the fast path as Never"
        );
    }

    /// Agg TARGETS bail through `field_needs_brute_fallback` / the
    /// `seg_field_kind` gate rather than skipping the segment. This asserts
    /// the first of those; the integration suite
    /// (`tests/fast_aggs_multifield_suffix.rs`) covers the executors.
    #[test]
    fn suffixed_agg_target_needs_brute_fallback() {
        let build = || {
            let mut cols = std::collections::BTreeMap::new();
            cols.insert(
                "extension".to_string(),
                Column::Keyword(KeywordColumn::from_iter(vec![Some("css".to_string())]).unwrap()),
            );
            seg_with_cols(cols)
        };
        for field in [
            "extension.raw",
            "extension.raw.raw",
            "extension.keyword.raw",
            "extension.raw.raw.raw",
        ] {
            assert!(
                field_needs_brute_fallback(field, &[build()], &mapped_fields(&[])),
                "a `terms`/metric target on `{field}` must bail to brute — the \
                 executors `continue` past a column-less segment, so it would \
                 otherwise be built from the memtable alone"
            );
        }
        assert!(
            !field_needs_brute_fallback("nosuchfield.raw", &[build()], &mapped_fields(&[])),
            "a dotted field with no ancestor column anywhere is a genuine \
             absence and must stay on the fast path"
        );
    }

    fn seg_with_cols(cols: std::collections::BTreeMap<String, Column>) -> SegEntry {
        SegEntry {
            id: "seg1".to_string(),
            cols: crate::segment_cache_budget::CacheResident::uncached(cols),
            docs: 1,
            ghosts: None,
        }
    }

    fn mapped_fields(names: &[&str]) -> std::collections::HashSet<String> {
        names.iter().map(|s| s.to_string()).collect()
    }

    // Regression: a genuinely nested JSON field (`geo.dest`, `machine.ram`)
    // has no column of its own at all — only its scalar leaves might, and
    // nested JSON leaves never become top-level columns in the first place,
    // so even the parent object's own name never resolves via `col()`
    // either (proven live: `col("geo")` returned `None` on a real index
    // despite `geo` being mapped `object`). The only reliable signal is the
    // SCHEMA: is the dotted path's root mapped `object`/`nested`?
    // `field_needs_brute_fallback` is the guard that makes `exec_agg` bail
    // to the correct brute-force path for these instead of silently
    // returning empty buckets / null metrics through the fast path. Found
    // live: `geo.dest` terms, `machine.ram` avg, and the doubly-nested
    // `machine.os.keyword` terms all went empty/null through fast_aggs on
    // real Kibana/OSD sample dashboards, while the identical query against
    // the brute-force path returned real data.
    #[test]
    fn nested_field_with_object_root_in_schema_needs_fallback() {
        let cols = std::collections::BTreeMap::new();
        let seg = seg_with_cols(cols);
        assert!(
            field_needs_brute_fallback("geo.dest", &[seg], &mapped_fields(&["geo"])),
            "geo.dest has no column of its own and geo is mapped object — must bail to brute force"
        );
    }

    /// The doubly-nested case (`machine.os.keyword`): only the TOP-LEVEL
    /// root (`machine`) needs to be mapped `object` — any depth below an
    /// object field is equally unreachable by the columnar path, so a
    /// single root check covers doubly (or deeper) nested paths too.
    #[test]
    fn doubly_nested_keyword_field_needs_fallback() {
        let cols = std::collections::BTreeMap::new();
        let seg = seg_with_cols(cols);
        assert!(
            field_needs_brute_fallback("machine.os.keyword", &[seg], &mapped_fields(&["machine"])),
            "machine.os.keyword's root (machine) is mapped object — must bail to brute force"
        );
    }

    /// A genuinely absent field (never indexed at all, e.g. a typo) must
    /// NOT be flagged — its root isn't mapped `object` (it isn't mapped at
    /// all), so the fast path's normal empty-result behavior is correct ES
    /// semantics, and forcing a brute-force fallback would just be wasted
    /// work for a legitimately-empty answer.
    #[test]
    fn genuinely_absent_dotted_field_does_not_need_fallback() {
        let cols = std::collections::BTreeMap::new();
        let seg = seg_with_cols(cols);
        assert!(
            !field_needs_brute_fallback("nonexistent.field", &[seg], &mapped_fields(&["geo"])),
            "the field's root isn't mapped object at all — a real absence, not a nested-path gap"
        );
    }

    /// A flat field that the schema does NOT map is a genuine absence — no
    /// column, no `_source` value for brute to find either — so it is never
    /// flagged and stays on the fast path as a real empty result.
    #[test]
    fn unmapped_flat_field_does_not_need_fallback() {
        let cols = std::collections::BTreeMap::new();
        let seg = seg_with_cols(cols);
        assert!(!field_needs_brute_fallback(
            "extension",
            &[seg],
            &mapped_fields(&[])
        ));
    }

    /// #128: a TOP-LEVEL field the schema maps but whose column was SUPPRESSED
    /// in every segment (an array-poisoned multi-valued field like `tags`, for
    /// which `build_doc_value_columns` ships no column) must bail — brute's
    /// `get_field_value` reads the `_source` array, so a columnar `Never`
    /// would report empty where brute reports data. Both the flat name and its
    /// `.raw` multi-field are covered, because the schema check keys off the
    /// top-level root.
    #[test]
    fn suppressed_top_level_array_field_needs_fallback() {
        let seg = seg_with_cols(std::collections::BTreeMap::new());
        for field in ["tags", "tags.raw"] {
            assert!(
                field_needs_brute_fallback(
                    field,
                    &[seg_with_cols(std::collections::BTreeMap::new())],
                    &mapped_fields(&["tags"])
                ),
                "`{field}` is a suppressed multi-valued field — brute resolves \
                 it, so the columnar path must bail"
            );
        }
        // Control: a genuinely unmapped sibling stays fast.
        assert!(!field_needs_brute_fallback(
            "nosuch.raw",
            &[seg],
            &mapped_fields(&["tags"])
        ));
    }

    /// #143: array suppression is PER-SEGMENT — `build_doc_value_columns`
    /// drops the column for exactly the segments whose docs hold arrays under
    /// the field — so a scalar-only segment carrying the column proves
    /// nothing about the others.  The executors `continue` past a column-less
    /// segment, so anything short of FULL coverage must bail: the old
    /// "ANY segment has it" check silently dropped the suppressed segment's
    /// docs from terms buckets, predicates and metric folds.
    #[test]
    fn mixed_segment_suppressed_field_needs_fallback() {
        let covered = || {
            let mut cols = std::collections::BTreeMap::new();
            cols.insert(
                "tags".to_string(),
                Column::Keyword(KeywordColumn::from_iter(vec![Some("a".to_string())]).unwrap()),
            );
            cols.insert(
                "score".to_string(),
                Column::Numeric(NumericColumn::from_iter(vec![Some(
                    5.0_f64.to_bits() as i64
                )])),
            );
            seg_with_cols(cols)
        };
        let suppressed = || seg_with_cols(std::collections::BTreeMap::new());
        let mapped = mapped_fields(&["tags", "score"]);
        // `tags.keyword` resolves through `dv_col`'s parent fallback in the
        // covered segment but not in the suppressed one, so it must bail the
        // same way the flat name does; `score` is the numeric-metric analogue.
        for field in ["tags", "tags.keyword", "score"] {
            assert!(
                field_needs_brute_fallback(field, &[covered(), suppressed()], &mapped),
                "`{field}` has no column in ONE segment while that segment's \
                 docs still exist — a single covered segment must not veto \
                 the bail"
            );
        }
        // Controls, both sides of the line:
        // full coverage stays fast — this is the common all-scalar corpus and
        // the perf-preserving half of the fix;
        assert!(
            !field_needs_brute_fallback("tags", &[covered(), covered()], &mapped),
            "a column present in EVERY segment needs no fallback"
        );
        // and an UNMAPPED name missing from a segment is a genuine absence
        // (never indexed — dynamic mapping would have mapped it), so it stays
        // on the fast path as a real empty result rather than paying brute.
        assert!(
            !field_needs_brute_fallback("unmapped", &[covered(), suppressed()], &mapped),
            "an unmapped name is genuinely absent — partial coverage of OTHER \
             fields must not send it to brute"
        );
    }

    /// The predicate half of #143: resolving a term predicate against the
    /// SUPPRESSED segment's columns must bail the request (`None`), not
    /// assert `SegPred::Never` — that segment's `_source` arrays hold rows
    /// brute matches.
    #[test]
    fn mixed_segment_suppressed_predicate_bails_instead_of_matching_nothing() {
        let mut cols = std::collections::BTreeMap::new();
        cols.insert(
            "tags".to_string(),
            Column::Keyword(KeywordColumn::from_iter(vec![Some("a".to_string())]).unwrap()),
        );
        let segs = vec![
            seg_with_cols(cols),
            seg_with_cols(std::collections::BTreeMap::new()),
        ];
        let mapped = mapped_fields(&["tags"]);
        let pred = Pred::TermKw {
            field: "tags".into(),
            value: "b".into(),
        };
        assert!(
            resolve_pred(&segs[1].cols, &pred, &segs, &mapped).is_none(),
            "the suppressed segment's rows can match `tags:b` — the miss must \
             bail to brute, not resolve to Never"
        );
    }

    /// The already-fixed `.keyword` multi-field case (`extension.keyword`)
    /// must NOT be flagged — `SegEntry::col` already resolves it via the
    /// `.keyword`-stripped fallback (the physical-column check short-circuits
    /// before the schema probe), so the fast path stays fast for this shape
    /// exactly as before this guard was added.
    #[test]
    fn keyword_multi_field_does_not_need_fallback() {
        let mut cols = std::collections::BTreeMap::new();
        cols.insert(
            "extension".to_string(),
            Column::Keyword(KeywordColumn::from_iter(vec![Some("css".to_string())]).unwrap()),
        );
        let seg = seg_with_cols(cols);
        assert!(!field_needs_brute_fallback(
            "extension.keyword",
            &[seg],
            &mapped_fields(&[])
        ));
    }

    /// A dotted field whose root DOES resolve as a physical column (the
    /// pre-existing `.keyword`-stripping case from #99) must not be flagged
    /// even if that root also happens to be schema-mapped `object` — the
    /// physical-column check runs first and already proves the fast path
    /// can serve it.
    #[test]
    fn field_resolving_via_physical_column_short_circuits_schema_check() {
        let mut cols = std::collections::BTreeMap::new();
        cols.insert(
            "geo".to_string(),
            Column::Keyword(KeywordColumn::from_iter(vec![Some("blob".to_string())]).unwrap()),
        );
        let seg = seg_with_cols(cols);
        assert!(!field_needs_brute_fallback(
            "geo.keyword",
            &[seg],
            &mapped_fields(&["geo"])
        ));
    }

    fn count(pred: &Pred, cols: &std::collections::BTreeMap<String, Column>, docs: u32) -> u64 {
        // These fixtures all resolve (or bail inside `resolve_pred` on a
        // type/width gate), never through the column-miss path, so the
        // segment set and schema map are unused here.
        let sp =
            resolve_pred(cols, pred, &[], &std::collections::HashSet::new()).expect("resolvable");
        let by_count = seg_pred_count(&sp, docs);
        let by_scan = (0..docs).filter(|r| seg_pred_matches(&sp, *r)).count() as u64;
        assert_eq!(by_count, by_scan, "seg_pred_count disagrees with row scan");
        by_count
    }

    fn rng(lo: Option<&str>, lo_incl: bool, hi: Option<&str>, hi_incl: bool) -> Pred {
        Pred::RangeKw {
            field: "ts".into(),
            lo: lo.map(str::to_string),
            lo_incl,
            hi: hi.map(str::to_string),
            hi_incl,
        }
    }

    #[test]
    fn half_open_day_window_is_exact() {
        let c = cols();
        // [day2 00:00, day3 00:00) == all 24 hours of day 2.
        let p = rng(Some(&ts(2, 0)), true, Some(&ts(3, 0)), false);
        assert_eq!(count(&p, &c, 72), 24);
    }

    #[test]
    fn inclusive_upper_includes_the_boundary_instant() {
        let c = cols();
        let p = rng(Some(&ts(2, 0)), true, Some(&ts(2, 23)), true);
        assert_eq!(count(&p, &c, 72), 24);
        // Exclusive upper drops exactly the last hour.
        let p = rng(Some(&ts(2, 0)), true, Some(&ts(2, 23)), false);
        assert_eq!(count(&p, &c, 72), 23);
    }

    #[test]
    fn exclusive_lower_drops_the_boundary_instant() {
        let c = cols();
        let p = rng(Some(&ts(2, 0)), false, Some(&ts(3, 0)), false);
        assert_eq!(count(&p, &c, 72), 23);
    }

    #[test]
    fn open_ended_bounds() {
        let c = cols();
        assert_eq!(count(&rng(None, true, Some(&ts(2, 0)), false), &c, 72), 24);
        assert_eq!(count(&rng(Some(&ts(3, 0)), true, None, true), &c, 72), 24);
        assert_eq!(count(&rng(None, true, None, true), &c, 72), 72);
    }

    #[test]
    fn empty_and_out_of_range_windows() {
        let c = cols();
        assert_eq!(
            count(
                &rng(Some("2026-07-01T00:00:00.000Z"), true, None, true),
                &c,
                72
            ),
            0
        );
        assert_eq!(
            count(
                &rng(None, true, Some("2026-05-01T00:00:00.000Z"), false),
                &c,
                72
            ),
            0
        );
    }

    /// The order-safety gate: a dictionary mixing widths (a hand-indexed
    /// `"2026-06-02"` next to full timestamps) must BAIL, not mis-range.
    #[test]
    fn ragged_dictionary_bails_to_brute() {
        let mut vals: Vec<Option<String>> = (0..24).map(|h| Some(ts(2, h))).collect();
        vals.push(Some("2026-06-02".to_string()));
        let k = KeywordColumn::from_iter(vals).expect("build column");
        let mut m = std::collections::BTreeMap::new();
        m.insert("ts".to_string(), Column::Keyword(k));
        let p = rng(Some(&ts(2, 0)), true, Some(&ts(3, 0)), false);
        assert!(
            resolve_pred(&m, &p, &[], &std::collections::HashSet::new()).is_none(),
            "ragged dictionary must bail"
        );
    }

    /// A bound whose width disagrees with the dictionary must bail too.
    #[test]
    fn unnormalised_bound_bails_to_brute() {
        let c = cols();
        let p = rng(Some("2026-06-02"), true, Some("2026-06-03"), false);
        assert!(
            resolve_pred(&c, &p, &[], &std::collections::HashSet::new()).is_none(),
            "short bound must bail"
        );
    }

    /// A numeric column under a lexicographic range must bail (the date/keyword
    /// split is decided by the stored JSON type, not the mapping).
    #[test]
    fn numeric_column_bails() {
        use xerj_storage::doc_values::NumericColumn;
        let mut m = std::collections::BTreeMap::new();
        let n = NumericColumn::from_iter((0..10).map(|i| Some((i as f64).to_bits() as i64)));
        m.insert("ts".to_string(), Column::Numeric(n));
        let p = rng(Some(&ts(2, 0)), true, None, true);
        assert!(resolve_pred(&m, &p, &[], &std::collections::HashSet::new()).is_none());
    }

    /// Regression: the *predicate* resolver must apply the same `.keyword`
    /// fallback as the agg targets do.
    ///
    /// `SegEntry::col` gained the fallback while the four lookups inside
    /// `resolve_pred` kept a raw map probe, and a miss there resolves to
    /// `SegPred::Never` — an assertion that the segment holds no matching
    /// row. So a filter on `<field>.keyword` matched nothing in any flushed
    /// segment while the memtable arm matched correctly: not an error, just
    /// a small wrong number (measured: `filters` on `extension.keyword`
    /// reported the 200 memtable docs out of 3 200, and a top-level
    /// `term group.keyword=b` query reported 0 hits out of 6 000).
    ///
    /// Every predicate variant that carries a field name is covered, since
    /// each one owned its own copy of the lookup.
    #[test]
    fn resolve_pred_falls_back_to_keyword_multi_field_parent() {
        use xerj_storage::doc_values::NumericColumn;
        let mut m = std::collections::BTreeMap::new();
        // Two docs under the parent name `extension` — exactly how a
        // flushed segment stores a text field's `.keyword` multi-field.
        m.insert(
            "extension".to_string(),
            Column::Keyword(
                // Equal-width terms: `Pred::RangeKw` refuses a ragged
                // dictionary outright (see `ragged_dictionary_bails_to_brute`),
                // and this fixture must reach the lookup, not that gate.
                KeywordColumn::from_iter(vec![Some("css".to_string()), Some("zip".to_string())])
                    .expect("build column"),
            ),
        );
        m.insert(
            "v".to_string(),
            Column::Numeric(NumericColumn::from_iter(
                [1.0f64, 2.0].iter().map(|f| Some(f.to_bits() as i64)),
            )),
        );

        let cases: Vec<(&str, Pred, Pred, u64)> = vec![
            (
                "term",
                Pred::TermKw {
                    field: "extension".into(),
                    value: "css".into(),
                },
                Pred::TermKw {
                    field: "extension.keyword".into(),
                    value: "css".into(),
                },
                1,
            ),
            (
                "terms",
                Pred::TermsKw {
                    field: "extension".into(),
                    values: vec!["css".into(), "zip".into()],
                },
                Pred::TermsKw {
                    field: "extension.keyword".into(),
                    values: vec!["css".into(), "zip".into()],
                },
                2,
            ),
            (
                "keyword range",
                Pred::RangeKw {
                    field: "extension".into(),
                    lo: Some("css".into()),
                    lo_incl: true,
                    hi: None,
                    hi_incl: true,
                },
                Pred::RangeKw {
                    field: "extension.keyword".into(),
                    lo: Some("css".into()),
                    lo_incl: true,
                    hi: None,
                    hi_incl: true,
                },
                2,
            ),
            (
                "numeric range",
                Pred::RangeNum {
                    field: "v".into(),
                    lo: 2.0,
                    lo_incl: true,
                    hi: f64::INFINITY,
                    hi_incl: true,
                },
                Pred::RangeNum {
                    field: "v.keyword".into(),
                    lo: 2.0,
                    lo_incl: true,
                    hi: f64::INFINITY,
                    hi_incl: true,
                },
                1,
            ),
        ];

        for (what, parent, suffixed, expect) in cases {
            assert_eq!(
                count(&parent, &m, 2),
                expect,
                "{what}: parent-name baseline"
            );
            assert_eq!(
                count(&suffixed, &m, 2),
                expect,
                "{what} on `<field>.keyword` must resolve against the parent's \
                 column, not fail closed to `Never`"
            );
        }
    }

    /// The fallback must not paper over a genuinely absent field: a
    /// predicate on a column this segment simply does not have still
    /// resolves to `Never` (correct — no row can match).
    #[test]
    fn resolve_pred_still_never_matches_an_absent_field() {
        let c = cols();
        let p = Pred::TermKw {
            field: "nope.keyword".into(),
            value: "x".into(),
        };
        assert!(matches!(
            resolve_pred(&c, &p, &[], &std::collections::HashSet::new()).expect("resolvable"),
            SegPred::Never
        ));
    }
}

//! Process-wide resource governor — the parent circuit breaker for the
//! ingest and search paths.
//!
//! Per-index back-pressure (the memtable soft/hard block in
//! [`crate::index`]) only ever bounds ONE index at `~3×flush_size_mb`. With
//! `N` indices there was no global ceiling: `N × ~1.5 GiB` of memtable could
//! accumulate until the kernel OOM-killed the process — the structural cause
//! of the 112 GiB incident. This module is the missing ceiling. It adds:
//!
//!   * **item 1** — a process-wide memtable byte budget, plus an RSS
//!     admission watermark measured against the cgroup/system memory limit.
//!     Crossing either rejects writes with HTTP 429
//!     `circuit_breaking_exception` (so a 429 beats the OOM-killer), and
//!     wires the hitherto-inert `max_query_memory_mb` into a per-query
//!     allocation guard. An analyze reservation charges in-flight token
//!     spikes before the next RSS sample, so several bulks cannot all pass
//!     one sample and allocate together (#1122).
//!   * **item 2** — a global search-concurrency pool sized from
//!     `max_concurrent_searches` (previously a hardcoded per-index
//!     `Semaphore::new(64)`, i.e. no global cap).
//!   * **item 3** — a disk flood-stage write block driven by a background
//!     `statvfs` poll, mirroring Elasticsearch's
//!     `disk.watermark.flood_stage`.
//!
//! A single process-wide [`OnceLock`] holds the governor. [`init`]
//! initialises it from config; [`Engine::spawn_resource_sampler`] refreshes
//! the RSS / memtable / disk atomics every ~250 ms, so the hot-path
//! admission checks are relaxed atomic loads — never syscalls.

use std::sync::atomic::{AtomicBool, AtomicU64, AtomicU8, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, Instant};

use serde_json::Value;
use tokio::sync::{OwnedSemaphorePermit, Semaphore};
use xerj_common::config::Config;
use xerj_common::XerjError;

use crate::segment_cache_budget::{SegmentHydrationBudget, SegmentHydrationBudgetSnapshot};

/// The process-wide governor singleton.
static GOVERNOR: OnceLock<Arc<ResourceGovernor>> = OnceLock::new();

/// Decides when the sampler may request another memory-pressure drain.
///
/// The engage edge fires immediately. While the breaker stays engaged, the
/// next request waits `interval`, which starts at the 2 s floor and doubles
/// up to [`MEMORY_DRAIN_MAX_INTERVAL`] whenever a request did not lower RSS.
/// A drop resets the spacing, and a climb past the noise band requests a
/// drain as soon as the minimum spacing allows (#2427). Disengaging resets everything, so the next
/// real engage is immediate again.
#[derive(Debug)]
pub(crate) struct MemoryDrainSchedule {
    interval: Duration,
    last_request: Option<Instant>,
    rss_at_request: Option<u64>,
    min: Duration,
}

impl MemoryDrainSchedule {
    pub(crate) fn new(min: Duration) -> Self {
        Self {
            interval: min,
            last_request: None,
            rss_at_request: None,
            min,
        }
    }

    /// `true` when this sample should request a drain.
    pub(crate) fn observe(&mut self, now: Instant, rss: u64, engaged: bool) -> bool {
        if !engaged {
            self.interval = self.min;
            self.last_request = None;
            self.rss_at_request = None;
            return false;
        }
        // #2427: the latch no longer releases above the watermark, so a
        // footprint that CLIMBS while engaged must not sit out a backed-off
        // gap (up to 15 min) — the release gate climbed from 5.1 GB to an
        // 8.4 GB OOM in 84 s. A climb past the noise band since the last
        // request is new pressure: drain again at the minimum spacing.
        let climbed = self
            .rss_at_request
            .is_some_and(|prev| rss.saturating_sub(prev) > MEMORY_RSS_NOISE_BYTES);
        let due = match self.last_request {
            None => true,
            Some(at) => {
                let since = now.saturating_duration_since(at);
                since >= self.interval || (climbed && since >= self.min)
            }
        };
        if !due {
            return false;
        }
        if climbed {
            self.interval = self.min;
            self.rss_at_request = Some(rss);
            self.last_request = Some(now);
            return true;
        }
        if let Some(prev) = self.rss_at_request {
            // A one-page dip is compressor noise, not a drain that worked.
            // Resetting on it would pin the spacing at 2 s for a footprint
            // that never actually shrinks (#1981).
            if prev.saturating_sub(rss) > MEMORY_RSS_NOISE_BYTES {
                self.interval = self.min;
            } else {
                self.interval = self
                    .interval
                    .checked_mul(2)
                    .unwrap_or(MEMORY_DRAIN_MAX_INTERVAL)
                    .min(MEMORY_DRAIN_MAX_INTERVAL);
            }
        }
        self.rss_at_request = Some(rss);
        self.last_request = Some(now);
        true
    }
}

/// Interval at which the background sampler refreshes the RSS / memtable /
/// disk atomics. Kept short so the RSS admission has a tight overshoot margin
/// under a runaway ingest — the sampler runs on a dedicated OS thread (see
/// `Engine::spawn_resource_sampler`), so this cadence is honoured even when the
/// tokio pool is saturated.
pub const SAMPLE_INTERVAL_MS: u64 = 100;

/// Ceiling on the automatic drain spacing once a drain stops lowering RSS.
/// The floor is the sampler's 2 s minimum; doubling from there reaches this
/// in a few minutes instead of staying at 2 s for an 18-hour uptime.
pub const MEMORY_DRAIN_MAX_INTERVAL: Duration = Duration::from_secs(15 * 60);

/// RSS movement at or below this is not a falling drain and not new
/// pressure (#1981).
///
/// macOS reports `ri_phys_footprint`, which moves by pages while the
/// compressor runs even when the process is idle. An exact-byte clock never
/// stays flat on that signal, and a one-byte dip would also reset the drain
/// backoff, so the 2 s flush loop would survive the latch fix. A move past
/// this band is a real working-set change.
pub const MEMORY_RSS_NOISE_BYTES: u64 = 4 * 1024 * 1024;

/// Default release point of the RSS breaker, as a percentage of the
/// watermark that tripped it (#2427).
///
/// The old band was 95% and released on the first sample that did not fall.
/// A 3,000 MB autoindex run engaged at 2,918 MB and flapped 20 times in 16
/// minutes, often releasing 100-500 ms after it engaged: each release
/// re-admitted the write burst that tripped it. Releasing at 85% leaves a
/// band the drain has to clear before writes come back.
/// `XERJ_MEMORY_BREAKER_RELEASE_PCT` overrides it (50..=99).
pub const DEFAULT_MEMORY_RELEASE_PERCENT: u8 = 85;

/// Share of the process memory limit held back for searches, in percent
/// (#2427 read-budget isolation).
///
/// Background merges and their output writes are charged to a merge pool
/// whose ceiling is the limit minus this share (or the watermark, if that is
/// lower). They are refused, and an in-flight batch yields, once process
/// memory reaches that ceiling. Searches are only rejected at the full limit,
/// so the top of the budget stays free for reads instead of being the first
/// thing a merge takes. On the 1 GB gate (3,072 MB cap) the merge pool stops
/// at about 2,458 MB and reads keep the last 614 MB.
pub const SEARCH_READ_RESERVE_PERCENT: u64 = 20;

/// How long a search that arrives with process memory at or above the hard
/// limit waits for the breaker's drain before it is rejected with a 429
/// (#2427 read-budget isolation).
///
/// The drain (flush, cache release, allocator purge) takes RSS from the limit
/// back to the live set in one to two seconds. In the 1 GB gate the raw and
/// MCP searches arrived within 300 ms of a heavy search and were all
/// rejected in 4-14 ms, although RSS was back to about 1.5 GB a second later.
pub const SEARCH_HEADROOM_WAIT: Duration = Duration::from_secs(3);

/// Poll interval while a search waits for headroom. The sampler writes RSS
/// every 100 ms, so polling faster only re-reads the same sample.
const SEARCH_HEADROOM_POLL: Duration = Duration::from_millis(25);

/// Lowest accepted `XERJ_MEMORY_BREAKER_RELEASE_PCT`. Below this, a footprint
/// whose live set is over half the watermark could never release.
pub const MIN_MEMORY_RELEASE_PERCENT: u8 = 50;

/// Highest accepted `XERJ_MEMORY_BREAKER_RELEASE_PCT`.
pub const MAX_MEMORY_RELEASE_PERCENT: u8 = 99;

/// Default minimum time the RSS breaker stays engaged before a release below
/// the watermark (#2427). `XERJ_MEMORY_BREAKER_MIN_ENGAGED_MS` overrides it.
///
/// This stops a 100 ms engage/release cycle: a release needs the drain to
/// have run at least once. A live retune (#1323) or Windows commit recovery
/// are not subject to it. No release ever happens at or above the watermark.
pub const DEFAULT_MEMORY_MIN_ENGAGED: Duration = Duration::from_secs(2);

/// Ceiling on `XERJ_MEMORY_BREAKER_MIN_ENGAGED_MS`.
pub const MAX_MEMORY_MIN_ENGAGED: Duration = Duration::from_secs(60);

/// How long RSS may sit without falling past [`MEMORY_RSS_NOISE_BYTES`]
/// inside the release band `[release, watermark)` before the breaker stops
/// waiting for the drain and releases (#2427).
///
/// Without this the band could hold writes forever on a live set between
/// 85% and 100% of the watermark that no drain can shrink (the #1250
/// concern). Thirty seconds is fifteen drain intervals, and bounds a
/// band-stall re-engage cycle to at most one every 30 s.
pub const MEMORY_BAND_STALL_RELEASE: Duration = Duration::from_secs(30);

/// Bytes at which an engaged RSS breaker releases: `release_pct` percent of
/// `watermark`. `0` for a disabled watermark.
pub fn memory_release_bytes(watermark: u64, release_pct: u8) -> u64 {
    ((watermark as u128 * u128::from(release_pct.min(100))) / 100) as u64
}

/// Parse `XERJ_MEMORY_BREAKER_RELEASE_PCT`. Unset, unparsable, or out of
/// `MIN..=MAX` falls back to [`DEFAULT_MEMORY_RELEASE_PERCENT`].
pub fn resolve_memory_release_percent(raw: Option<&str>) -> u8 {
    let Some(raw) = raw.map(str::trim).filter(|s| !s.is_empty()) else {
        return DEFAULT_MEMORY_RELEASE_PERCENT;
    };
    match raw.trim_end_matches('%').parse::<u8>() {
        Ok(pct) if (MIN_MEMORY_RELEASE_PERCENT..=MAX_MEMORY_RELEASE_PERCENT).contains(&pct) => pct,
        _ => {
            tracing::warn!(
                value = raw,
                default = DEFAULT_MEMORY_RELEASE_PERCENT,
                "XERJ_MEMORY_BREAKER_RELEASE_PCT must be {MIN_MEMORY_RELEASE_PERCENT}..={MAX_MEMORY_RELEASE_PERCENT}; using the default"
            );
            DEFAULT_MEMORY_RELEASE_PERCENT
        }
    }
}

/// Parse `XERJ_MEMORY_BREAKER_MIN_ENGAGED_MS`. Unset or unparsable falls back
/// to [`DEFAULT_MEMORY_MIN_ENGAGED`]; larger values are clamped to
/// [`MAX_MEMORY_MIN_ENGAGED`]. `0` turns the minimum off.
pub fn resolve_memory_min_engaged(raw: Option<&str>) -> Duration {
    let Some(raw) = raw.map(str::trim).filter(|s| !s.is_empty()) else {
        return DEFAULT_MEMORY_MIN_ENGAGED;
    };
    match raw.parse::<u64>() {
        Ok(ms) => Duration::from_millis(ms).min(MAX_MEMORY_MIN_ENGAGED),
        Err(_) => {
            tracing::warn!(
                value = raw,
                "XERJ_MEMORY_BREAKER_MIN_ENGAGED_MS is not a whole number of milliseconds; using the default"
            );
            DEFAULT_MEMORY_MIN_ENGAGED
        }
    }
}

/// Bytes of analyze-time reservation charged per raw JSON input byte (#1122).
///
/// `document_limit` measured about 56 bytes of RSS per token for a
/// `Vec<String>` of the word `word ` (2026-10-23, 8,388,605 input bytes).
/// The densest input that still produces one token per two bytes is `"a "`,
/// so 28 bytes of reservation per input byte covers that spike. One token
/// per byte is outside this factor; the 8 MiB document ceiling bounds that
/// input. Eight such bulks are admitted only while the sum of reservations
/// stays under the watermark.
pub const ANALYZE_RESERVE_PER_INPUT_BYTE: u64 = 28;

/// Reservation for a raw JSON batch of `raw_json_bytes`.
pub fn analyze_reserve_bytes(raw_json_bytes: u64) -> u64 {
    raw_json_bytes.saturating_mul(ANALYZE_RESERVE_PER_INPUT_BYTE)
}

/// `true` when `request` bytes of analyze reservation still fit.
///
/// A watermark of `0` is the disabled breaker: every request fits. Otherwise
/// the request fails when `observed + already_reserved + request` reaches
/// the watermark. The comparison is `>=`, matching RSS admission.
pub fn analyze_reservation_fits(
    watermark: u64,
    observed: u64,
    already_reserved: u64,
    request: u64,
) -> bool {
    if watermark == 0 {
        return true;
    }
    observed
        .saturating_add(already_reserved)
        .saturating_add(request)
        < watermark
}

/// Process-wide resource governor. See the module docs.
pub struct ResourceGovernor {
    /// One admission authority shared by every index in this process.
    segment_hydration_budget: Arc<SegmentHydrationBudget>,
    segment_hydration_budget_source: SegmentHydrationBudgetSource,
    // ── item 1: process-wide memtable budget ────────────────────────────
    /// Ceiling on summed memtable bytes across ALL indices. `0` = disabled.
    memtable_budget_bytes: u64,
    /// Last sampled sum of every index's memtable footprint.
    memtable_used_bytes: AtomicU64,
    /// Latched: last sample crossed the memtable budget.
    memtable_tripped: AtomicBool,

    // ── item 1: RSS admission watermark ─────────────────────────────────
    /// Effective process memory limit (cgroup limit, else system RAM).
    memory_limit_bytes: u64,
    /// Uncapped machine/cgroup memory the process can see — the base a
    /// percentage override is taken against and the hard ceiling an absolute
    /// override is clamped to. Distinct from `memory_limit_bytes`, which is the
    /// AUTO-tier *capped* value (e.g. 16 GiB on a 119 GiB box): a live override
    /// exists precisely to climb past that conservative cap, so it must be able
    /// to reach up to real machine memory, never just a fraction of the cap.
    /// On a commit-bound Windows box this stops at the post-reserve commit
    /// ceiling instead: a raise cannot grant commit the system will not give.
    machine_memory_bytes: u64,
    /// Boot-derived RSS admission threshold = `memory_limit_bytes * pct/100`.
    /// `0` = the watermark was disabled at startup and stays disabled; a runtime
    /// override is then a no-op (see [`Self::set_memory_watermark_override`]).
    memory_watermark_bytes_default: u64,
    /// Effective RSS admission threshold engaging the parent breaker —
    /// `memory_watermark_bytes_default` unless overridden at runtime via the
    /// `indices.breaker.total.limit` persistent cluster setting (see
    /// [`Self::set_memory_watermark_override`]), which lets an operator raise
    /// the watermark on a big box without a restart — the live equivalent of
    /// the boot-only `XERJ_MAX_PROCESS_MEMORY_MB`. `0` = off.
    memory_watermark_bytes: AtomicU64,
    /// Last sampled resident set size of this process.
    rss_bytes: AtomicU64,
    /// Bytes reserved for in-flight analysis spikes that the RSS sample has
    /// not observed yet (#1122). Released once those tokens exist, so the
    /// next admission sees them in live RSS instead of counting them twice.
    analyze_reserved: Arc<AtomicU64>,
    /// Latched: last sample crossed the RSS watermark.
    memory_tripped: AtomicBool,
    /// The effective watermark in force when the breaker last engaged (#1250).
    /// The release hysteresis is only meaningful against the watermark that
    /// tripped; when an operator re-tunes the watermark live
    /// (`indices.breaker.total.limit`, #1323) the latch is re-evaluated
    /// against the new value without the band, so a live raise releases at
    /// once instead of waiting for RSS to fall below the release point of
    /// the NEW watermark.
    memory_trip_watermark: AtomicU64,
    /// When RSS last stopped falling inside the release band while the
    /// breaker was engaged (#2427). `None` outside the band or while
    /// disengaged. Aged by tests; the sampler's wall clock fills it in
    /// production.
    memory_flat_since: Mutex<Option<Instant>>,
    /// Release point of the RSS breaker, percent of the tripped watermark
    /// (#2427). See [`DEFAULT_MEMORY_RELEASE_PERCENT`].
    memory_release_percent: u8,
    /// Minimum time engaged before an in-band or below-band release (#2427).
    memory_min_engaged: Duration,
    /// When the RSS breaker last engaged. `None` while released.
    memory_engaged_since: Mutex<Option<Instant>>,
    /// RSS at which the in-band stall clock started (#2427). A sample more
    /// than [`MEMORY_RSS_NOISE_BYTES`] under it is a falling drain and
    /// restarts the clock. `0` = no band clock.
    memory_band_anchor: AtomicU64,
    /// Process-wide ledger of in-flight segment merges and their estimated
    /// working set (#2427). See [`ResourceGovernor::try_reserve_merge`].
    merge_ledger: Arc<Mutex<MergeLedger>>,

    // ── item 1: per-query memory guard (`max_query_memory_mb`) ──────────
    /// Maximum bytes a single query may be estimated to allocate. `0` = off.
    max_query_memory_bytes: u64,

    // ── item 2: global search pool (`max_concurrent_searches`) ──────────
    /// Global search-concurrency permits.
    search_pool: Arc<Semaphore>,
    /// Configured permit count (for observability / stats).
    max_concurrent_searches: usize,
    /// Live count of in-flight search permits (proof of the cap). `Arc` so a
    /// [`SearchPermit`] guard can decrement it safely on drop.
    search_inflight: Arc<AtomicU64>,
    /// High-water mark of concurrent searches observed (proof of the cap).
    search_inflight_peak: Arc<AtomicU64>,
    /// #2427: one permit. While the RSS breaker is engaged every search
    /// also holds this, so searches run one at a time instead of
    /// `max_concurrent_searches` wide.
    search_pressure: Arc<Semaphore>,
    /// How long a search over the hard limit waits for the drain (#2427).
    /// [`SEARCH_HEADROOM_WAIT`] in production; tests shorten it.
    search_headroom_wait: Duration,
    /// Bound on a lone background merge's wait for headroom (#2427).
    /// `merge_budget::MERGE_HEADROOM_MAX_WAIT` in production.
    merge_headroom_max_wait: Duration,

    // ── item 2b: global bulk pool (concurrent bulk parse cap) ─────────
    /// Global bulk-concurrency permits. Caps the number of concurrent
    /// `_bulk` requests in the parse phase, preventing memory amplification
    /// from N concurrent bulks each materializing ~300 B/action before the
    /// memtable admission check fires.
    bulk_pool: Arc<Semaphore>,
    /// Configured bulk permit count (for observability / stats).
    max_concurrent_bulks: usize,

    // ── item 3: disk flood-stage write block ────────────────────────────
    /// Configured used-percentage watermark from startup config. `0` = the
    /// watermark is disabled and stays disabled — [`Self::set_disk_flood_pct_override`]
    /// is a no-op in that case, so a runtime cluster-settings override can
    /// only re-tune an already-active watermark, never turn the feature on.
    disk_flood_pct_default: u8,
    /// Effective used-percentage watermark that engages the write block —
    /// `disk_flood_pct_default` unless overridden at runtime via the
    /// `cluster.routing.allocation.disk.watermark.flood_stage` persistent
    /// cluster setting (see [`Self::set_disk_flood_pct_override`]), which
    /// lets an operator clear/relax the block without a restart, matching
    /// ES's `PUT _cluster/settings` recovery flow.
    disk_flood_pct: AtomicU8,
    /// `false` while the `cluster.routing.allocation.disk.threshold_enabled`
    /// cluster setting is `false`: the flood stage never engages, and an
    /// engaged block is released on the next sample, as in ES.
    disk_threshold_enabled: AtomicBool,
    /// Latched: the data-dir filesystem is at/over the flood-stage watermark.
    disk_blocked: AtomicBool,
    /// Last sampled used-percentage of the data-dir filesystem.
    disk_used_pct: AtomicU64,

    // ── Windows commit ceiling (#1122) ──────────────────────────────────
    // Physical RAM is the AUTO tier's input on every platform. On Windows the
    // allocator aborts when commit charge hits the commit limit, which with
    // no pagefile is about RAM and is already partly spent by other processes.
    // These fields are zero off Windows (and when the probe fails), and the
    // admission path below then behaves exactly as it did before.
    /// `MEMORYSTATUSEX::ullTotalPageFile`. `0` = no commit probe.
    commit_limit_bytes: u64,
    /// Available commit below this engages the breaker even when RSS is under
    /// the watermark. `0` disables the check.
    commit_reserve_bytes: u64,
    /// Last sampled `ullAvailPageFile`.
    available_commit_bytes: AtomicU64,
    /// Latched: available commit is under [`Self::commit_reserve_bytes`].
    commit_starved: AtomicBool,
    /// The process cap was lowered to the commit ceiling at startup.
    commit_capped: bool,
}

impl ResourceGovernor {
    // ── Admission checks (hot path — relaxed atomic loads only) ─────────

    /// Ingest admission. Returns a 429 `circuit_breaking_exception` when the
    /// process is at/over the memtable budget or the RSS watermark. This is
    /// the parent breaker that turns the OOM into a survivable 429.
    pub fn check_ingest_admission(&self) -> Result<(), XerjError> {
        if self.memtable_tripped.load(Ordering::Relaxed) {
            let used = self.memtable_used_bytes.load(Ordering::Relaxed);
            return Err(XerjError::circuit_breaking(format!(
                "[parent] memtable byte budget exceeded: used={}MB, limit={}MB across all \
                 indices; writes rejected to prevent an out-of-memory kill (raise \
                 limits.max_process_memory_mb or XERJ_MAX_PROCESS_MEMORY_MB — the auto \
                 tier derives this budget from that cap — or set limits.max_total_memtable_mb)",
                used / (1024 * 1024),
                self.memtable_budget_bytes / (1024 * 1024),
            )));
        }
        if self.memory_tripped.load(Ordering::Relaxed) {
            let rss = self.rss_bytes.load(Ordering::Relaxed);
            let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
            let starved = self.commit_starved.load(Ordering::Relaxed);
            // Inside the release band (#1250) RSS is already under the
            // watermark while the drain finishes; say so rather than print a
            // false `>=`. A commit-starvation trip with RSS still under the
            // watermark is neither of those: the process has not crossed the
            // RSS line, Windows has run out of commit.
            let relation = if starved && rss < watermark {
                "under"
            } else if rss >= watermark {
                ">="
            } else {
                "draining below"
            };
            let commit = (self.commit_capped || starved).then(|| CommitBreakerDetail {
                limit: self.commit_limit_bytes,
                available: self.available_commit_bytes.load(Ordering::Relaxed),
                reserve: self.commit_reserve_bytes,
            });
            return Err(XerjError::circuit_breaking(memory_breaker_reason(
                rss,
                relation,
                watermark,
                self.memory_limit_bytes,
                commit,
            )));
        }
        Ok(())
    }

    /// Reserve `bytes` of upcoming analysis allocations (#1122).
    ///
    /// Callers pass [`analyze_reserve_bytes`] of the raw JSON, before the
    /// batch is parsed. The check uses the max of the sampled RSS and a live
    /// probe, plus reservations already held, and rechecks after the atomic
    /// add so two bulks cannot both pass the same snapshot. A watermark of
    /// `0`, or a zero request, reserves nothing. The guard releases on drop.
    pub(crate) fn reserve_analyze(&self, bytes: u64) -> Result<AnalyzeReservation, XerjError> {
        if bytes == 0 || self.memory_watermark_bytes.load(Ordering::Relaxed) == 0 {
            return Ok(AnalyzeReservation::none());
        }
        if self.memory_tripped.load(Ordering::Relaxed) {
            return Err(self.analyze_reservation_refused(bytes));
        }
        let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
        let observed = self.observed_process_memory();
        let already = self.analyze_reserved.load(Ordering::Acquire);
        if !analyze_reservation_fits(watermark, observed, already, bytes) {
            return Err(self.analyze_reservation_refused(bytes));
        }
        let prev = self.analyze_reserved.fetch_add(bytes, Ordering::AcqRel);
        let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
        if watermark == 0 {
            self.analyze_reserved.fetch_sub(bytes, Ordering::AcqRel);
            return Ok(AnalyzeReservation::none());
        }
        let observed = self.observed_process_memory();
        if analyze_reservation_fits(watermark, observed, prev, bytes) {
            return Ok(AnalyzeReservation {
                slot: Some(Arc::clone(&self.analyze_reserved)),
                bytes,
            });
        }
        self.analyze_reserved.fetch_sub(bytes, Ordering::AcqRel);
        Err(self.analyze_reservation_refused(bytes))
    }

    /// Admit one `_bulk` request before its body is split and parsed (#2427).
    ///
    /// Every write path checks the breaker, but only after the bulk parse
    /// has already built its per-action line, pair and document-copy vectors.
    /// A request that arrives while a breaker is latched still did all of that
    /// work, and concurrent bulks between two sampler ticks were admitted
    /// on a sample that predates each other's parse buffers. This refuses the
    /// request with the same 429 when either latch is engaged, and otherwise
    /// reserves `body_bytes` against live RSS plus every other in-flight
    /// reservation, so parse buffers are counted before they are allocated.
    /// The caller drops the reservation when the parse ends; the per-index
    /// write path then takes its own analyze reservation for the tokens.
    pub(crate) fn admit_bulk_parse(
        &self,
        body_bytes: u64,
    ) -> Result<AnalyzeReservation, XerjError> {
        self.check_ingest_admission()?;
        self.reserve_analyze(body_bytes)
    }

    fn observed_process_memory(&self) -> u64 {
        self.rss_bytes
            .load(Ordering::Relaxed)
            .max(current_process_memory_bytes())
    }

    fn analyze_reservation_refused(&self, request: u64) -> XerjError {
        const MIB: u64 = 1024 * 1024;
        let observed = self.observed_process_memory();
        let reserved = self.analyze_reserved.load(Ordering::Relaxed);
        let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
        XerjError::circuit_breaking(format!(
            "[parent] real memory circuit breaker tripped: rss={}MB plus {}MB already reserved \
             for analysis plus {}MB for this batch would reach watermark={}MB ({}% of \
             limit={}MB); writes rejected to prevent an out-of-memory kill (raise \
             limits.max_process_memory_mb or XERJ_MAX_PROCESS_MEMORY_MB, or live with \
             PUT _cluster/settings {{\"persistent\":{{\"indices.breaker.total.limit\":\"<N>gb\"}}}})",
            observed / MIB,
            reserved / MIB,
            request / MIB,
            watermark / MIB,
            pct_of(watermark, self.memory_limit_bytes),
            self.memory_limit_bytes / MIB,
        ))
    }

    /// Resolved process-memory ceiling in bytes. `0` is not used: an
    /// uncapped config stores the machine size here. Merge planning reads
    /// this so a small host's batches follow the AUTO cap instead of a
    /// fixed 512 MiB.
    pub fn process_memory_limit_bytes(&self) -> u64 {
        self.memory_limit_bytes
    }

    /// RSS admission watermark in bytes. `0` means the check is off.
    pub fn memory_watermark_bytes(&self) -> u64 {
        self.memory_watermark_bytes.load(Ordering::Relaxed)
    }

    /// Larger of the last RSS sample and a live read. `0` when this
    /// platform cannot read process memory.
    pub fn observed_rss_bytes(&self) -> u64 {
        self.observed_process_memory()
    }

    /// Whether the parent RSS memory breaker is currently engaged (issue
    /// #948). Admission (429) is only half of the contract: the resource
    /// sampler uses this flag, together with [`Self::memtable_breaker_engaged`],
    /// to request a memory-pressure DRAIN of rebuildable state (flush + cache
    /// release). A breaker that only rejects never lets a workload whose
    /// caches or memtables hold the bytes make progress.
    pub fn memory_breaker_engaged(&self) -> bool {
        self.memory_tripped.load(Ordering::Relaxed)
    }

    /// Start or read the flat-footprint clock. The first sample inside the
    /// noise band records `now` and returns zero; later samples return how
    /// long RSS has stayed there. Cleared when RSS leaves that band, the
    /// breaker releases, or the watermark is retuned.
    fn note_memory_flat(&self) -> Duration {
        let mut slot = self
            .memory_flat_since
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        match *slot {
            Some(at) => at.elapsed(),
            None => {
                *slot = Some(Instant::now());
                Duration::ZERO
            }
        }
    }

    fn clear_memory_flat(&self) {
        *self
            .memory_flat_since
            .lock()
            .unwrap_or_else(|e| e.into_inner()) = None;
    }

    /// Test hook: age the flat-footprint clock without sleeping, so a test
    /// can cross [`MEMORY_BAND_STALL_RELEASE`] on a paused schedule.
    #[cfg(test)]
    fn age_memory_flat_for_test(&self, by: Duration) {
        let mut slot = self
            .memory_flat_since
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        if let Some(at) = *slot {
            *slot = Some(at.checked_sub(by).unwrap_or(at));
        }
    }

    /// Release point of the RSS breaker as a percentage of the watermark.
    pub fn memory_release_percent(&self) -> u8 {
        self.memory_release_percent
    }

    /// Minimum time the RSS breaker stays engaged before an in-band release.
    pub fn memory_min_engaged(&self) -> Duration {
        self.memory_min_engaged
    }

    /// How long the RSS breaker has been engaged. A latch with no recorded
    /// edge (the startup commit trip) counts as having met any minimum.
    fn memory_engaged_for(&self) -> Duration {
        match *self
            .memory_engaged_since
            .lock()
            .unwrap_or_else(|e| e.into_inner())
        {
            Some(at) => at.elapsed(),
            None => Duration::MAX,
        }
    }

    fn set_memory_engaged_since(&self, at: Option<Instant>) {
        *self
            .memory_engaged_since
            .lock()
            .unwrap_or_else(|e| e.into_inner()) = at;
    }

    /// #2427 test hook: age the engaged clock without sleeping.
    #[cfg(test)]
    fn age_memory_engaged_for_test(&self, by: Duration) {
        let mut slot = self
            .memory_engaged_since
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        if let Some(at) = *slot {
            *slot = Some(at.checked_sub(by).unwrap_or(at));
        }
    }

    /// Bytes reserved by in-flight segment merges (#2427).
    pub fn merge_reserved_bytes(&self) -> u64 {
        self.merge_ledger
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .reserved
    }

    /// Segment merges currently holding a [`MergeReservation`] (#2427).
    pub fn merges_in_flight(&self) -> u64 {
        self.merge_ledger
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .in_flight
    }

    /// Ceiling of the merge pool (#2427 read-budget isolation): the process
    /// limit minus [`SEARCH_READ_RESERVE_PERCENT`], or the watermark if that
    /// is lower. Merge admission, the merge yield check and the merge
    /// output-write check stop at this line, so the reserve above it stays
    /// for searches. `0` when no watermark is live.
    pub fn merge_pool_ceiling_bytes(&self) -> u64 {
        merge_pool_ceiling(self.memory_watermark_bytes(), self.memory_limit_bytes)
    }

    /// Reserve the estimated working set of one merge batch whose inputs
    /// total `input_bytes` against the merge pool (#2427).
    ///
    /// Before this, every index started its first merge batch whatever the
    /// process footprint, and each batch was checked against an RSS snapshot
    /// that did not see other indices' merges that had started but not yet
    /// allocated. Under autoindex (hundreds of indices) that put many merge
    /// and FST working sets on top of a node already at the watermark: RSS
    /// climbed about 1 GB past a 3,000 MB cap while writes were getting 429s.
    ///
    /// The reservation is `input_bytes * MERGE_WORKING_SET_NUMERATOR` and is
    /// held until the guard drops. See `merge_budget::decide_merge_admission`
    /// for the rule.
    /// `None` means defer: the caller leaves the batch for a later pass.
    pub fn try_reserve_merge(&self, input_bytes: u64, forced: bool) -> Option<MergeReservation> {
        self.try_reserve_merge_with_footprint(input_bytes, 0, forced)
    }

    /// [`Self::try_reserve_merge`] for a batch whose inputs also occupy
    /// `on_disk_bytes` on disk, side-cars included (#2427). The reservation
    /// is `merge_budget::merge_reservation_bytes`: the planned-input
    /// estimate or `on_disk_bytes * MERGE_ON_DISK_WORKING_SET_NUMERATOR`,
    /// whichever is larger. `0` means unknown.
    pub fn try_reserve_merge_with_footprint(
        &self,
        input_bytes: u64,
        on_disk_bytes: u64,
        forced: bool,
    ) -> Option<MergeReservation> {
        let bytes = crate::merge_budget::merge_reservation_bytes(input_bytes, on_disk_bytes);
        // Concurrent merges are admitted against the merge pool, not the
        // watermark: the read reserve above it is never handed to a merge.
        let watermark = self.merge_pool_ceiling_bytes();
        let observed = self.observed_process_memory();
        let engaged = self.memory_breaker_engaged();
        let mut ledger = self.merge_ledger.lock().unwrap_or_else(|e| e.into_inner());
        // #2427 ingest overshoot: a lone background batch does not start
        // inside the read reserve; it waits (bounded) for the drain. See
        // `merge_budget::lone_merge_waits_for_headroom`.
        if !forced && ledger.in_flight == 0 && watermark > 0 && observed >= watermark {
            let since = *ledger
                .headroom_wait_since
                .get_or_insert_with(std::time::Instant::now);
            if crate::merge_budget::lone_merge_waits_for_headroom(
                observed,
                watermark,
                ledger.in_flight,
                forced,
                since.elapsed(),
                self.merge_headroom_max_wait,
            ) {
                return None;
            }
        } else if observed < watermark {
            // Headroom came back: the next wait starts its own clock.
            ledger.headroom_wait_since = None;
        }
        if !crate::merge_budget::decide_merge_admission(
            watermark,
            observed,
            ledger.reserved,
            ledger.in_flight,
            engaged,
            bytes,
            forced,
        ) {
            return None;
        }
        ledger.reserved = ledger.reserved.saturating_add(bytes);
        ledger.in_flight += 1;
        ledger.headroom_wait_since = None;
        Some(MergeReservation {
            ledger: Arc::clone(&self.merge_ledger),
            bytes,
        })
    }

    /// Whether an in-flight background merge batch must stop now (#2427).
    /// See `merge_budget::merge_must_yield`.
    pub fn merge_must_yield(&self, forced: bool) -> bool {
        let observed = self.observed_process_memory();
        crate::merge_budget::merge_must_yield(
            observed,
            self.merge_pool_ceiling_bytes(),
            self.merge_memory_pressure(observed),
            forced,
        )
    }

    /// Whether merges see memory pressure at `observed` bytes (#2427): the
    /// breaker is engaged, or `observed` is already at the watermark and the
    /// 100 ms sampler has not latched it yet. A merge checks live process
    /// memory, so it need not run on for up to a sampler tick past the
    /// watermark.
    fn merge_memory_pressure(&self, observed: u64) -> bool {
        let watermark = self.memory_watermark_bytes();
        self.memory_breaker_engaged() || (watermark > 0 && observed >= watermark)
    }

    /// [`Self::merge_must_yield`] for a batch of `input_bytes`: after a
    /// streak of yields a small batch completes, so compaction cannot stall
    /// for good. See `merge_budget::merge_must_yield_after`.
    pub fn merge_must_yield_for(&self, forced: bool, input_bytes: u64) -> bool {
        let streak = self
            .merge_ledger
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .yield_streak;
        let observed = self.observed_process_memory();
        crate::merge_budget::merge_must_yield_after(
            observed,
            self.merge_pool_ceiling_bytes(),
            self.merge_memory_pressure(observed),
            forced,
            input_bytes,
            streak,
        )
    }

    /// Record a background batch of `input_bytes` that stopped under memory
    /// pressure: the next batches are planned under half of it (#2427).
    pub fn note_merge_yield(&self, input_bytes: u64) -> u64 {
        let mut ledger = self.merge_ledger.lock().unwrap_or_else(|e| e.into_inner());
        ledger.pressure_cap =
            crate::merge_budget::pressure_cap_after_yield(ledger.pressure_cap, input_bytes);
        ledger.yield_streak = ledger.yield_streak.saturating_add(1);
        ledger.pressure_cap
    }

    /// Record a background batch of `input_bytes` that completed: a batch
    /// that used the adaptive cap widens it again (#2427).
    pub fn note_merge_completed(&self, input_bytes: u64) {
        let mut ledger = self.merge_ledger.lock().unwrap_or_else(|e| e.into_inner());
        ledger.pressure_cap =
            crate::merge_budget::pressure_cap_after_success(ledger.pressure_cap, input_bytes);
        ledger.yield_streak = 0;
    }

    /// The adaptive merge batch input cap, `0` when none is set (#2427).
    pub fn merge_pressure_cap_bytes(&self) -> u64 {
        self.merge_ledger
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .pressure_cap
    }

    /// Whether a batch's output-write step is exempt from
    /// [`Self::admit_merge_write`]'s hard-limit refusal (#2427, #2468).
    ///
    /// True exactly when #2468's streak rule is what keeps this batch
    /// running: the plain rule ([`Self::merge_must_yield`]) says yield, and
    /// the streak-aware rule ([`Self::merge_must_yield_for`]) waives it for
    /// a small batch after a streak of yields with nothing merged. Refusing
    /// that batch's write would bring back the stall the rule exists to
    /// break.
    pub fn merge_write_exempt(&self, forced: bool, input_bytes: u64) -> bool {
        self.merge_must_yield(forced) && !self.merge_must_yield_for(forced, input_bytes)
    }

    /// Charge a merge batch's output-write step to the merge budget before
    /// it runs (#2427).
    ///
    /// The step comes after the last yield checkpoint: the doc-values
    /// build, the stored encode and the FTS side-car build. It allocates
    /// `extra` bytes (`merge_budget::merge_write_phase_bytes`) on top of the
    /// `held` bytes the batch already has. Before this, neither admission
    /// nor the yield checks saw it, and large pg-docs merges took a
    /// 3,072 MB search node to 4.4–4.9 GB in their last seconds.
    ///
    /// Returns `false` when the step would take observed process memory to
    /// the hard limit (`merge_budget::decide_merge_write`). The caller then
    /// yields the batch, keeping its inputs. On `true`, `reservation` grows
    /// to at least `held + extra`, so admission for other merges sees the
    /// step until the batch drops its reservation. A refused step leaves
    /// the ledger as it was. `exempt` covers batches that #2468's streak
    /// rule lets run to completion.
    pub fn admit_merge_write(
        &self,
        reservation: Option<&mut MergeReservation>,
        held: u64,
        extra: u64,
        forced: bool,
        exempt: bool,
    ) -> bool {
        let observed = self.observed_process_memory();
        if !crate::merge_budget::decide_merge_write(
            observed,
            self.merge_pool_ceiling_bytes(),
            extra,
            forced,
            exempt,
        ) {
            return false;
        }
        if let Some(reservation) = reservation {
            let wanted = held.saturating_add(extra);
            if wanted > reservation.bytes {
                let mut ledger = self.merge_ledger.lock().unwrap_or_else(|e| e.into_inner());
                ledger.reserved = ledger.reserved.saturating_add(wanted - reservation.bytes);
                reservation.bytes = wanted;
            }
        }
        true
    }

    /// Whether the summed-memtable budget breaker is currently engaged.
    pub fn memtable_breaker_engaged(&self) -> bool {
        self.memtable_tripped.load(Ordering::Relaxed)
    }

    /// Whether the sampler must request a memory-pressure drain (#948, #2238).
    ///
    /// Both parent latches answer writes with HTTP 429, and a 429 frees
    /// nothing by itself. The RSS latch has requested a drain since #948.
    /// The summed-memtable latch did not. On the 8 GiB auto tier that budget
    /// is 2 GiB (`auto_memtable_budget`: 25% floored at 2 GiB) while each
    /// index flushes at `storage.flush_size_mb` (default 512 MiB), so a
    /// corpus spread across dozens of indices crosses the process budget
    /// with every index still under its own flush line. Writes then stay
    /// 429 and the indexed count stays 0 unless this latch requests the
    /// same drain.
    ///
    /// The two latches do not share a timer. The RSS latch backs off when a
    /// drain does not lower RSS (#1981). The memtable latch stays on the
    /// fixed window, because that flush is what frees this budget and a
    /// stable RSS is the normal shape of a memtable-only trip.
    pub fn ingest_pressure_needs_drain(&self) -> bool {
        self.memory_breaker_engaged() || self.memtable_breaker_engaged()
    }

    /// Whether it is safe to spawn a best-effort helper thread right now (#1122).
    ///
    /// `std::thread::Builder::spawn` panics inside the new thread when the
    /// alternate signal stack cannot be mmap'd, and the shipped profile is
    /// `panic = "abort"`, so that panic aborts the node. The engine's helper
    /// spawner does not use that path (a failed `pthread_create` is an
    /// `Err`), and this gate skips the attempt entirely once the breaker is
    /// engaged so a flush storm does not keep reserving stacks. Callers on
    /// flush/publish paths that have an inline fallback must check this and
    /// take the fallback instead of spawning.
    ///
    /// Reads the *live* RSS (`current_rss_bytes`), not the sampler's last
    /// value, so an RSS spike between samples cannot sneak a spawn through;
    /// the engaged breaker flag is the second, sampled signal. With no RSS
    /// probe or no configured watermark this returns `true` — spawning is
    /// unrestricted, exactly the pre-#1122 behaviour.
    pub fn thread_spawn_safe(&self) -> bool {
        if self.memory_breaker_engaged() {
            return false;
        }
        let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
        if watermark == 0 {
            return true;
        }
        current_rss_bytes() < watermark
    }

    /// Disk flood-stage admission. Returns an ES-shaped
    /// `read_only_allow_delete` cluster block (HTTP 429) when the data-dir
    /// filesystem is over the flood-stage watermark. `index` names the
    /// blocked index for the ES `root_cause`.
    pub fn check_disk_block(&self, index: &str) -> Result<(), XerjError> {
        if self.disk_blocked.load(Ordering::Relaxed) {
            // The `read_only_allow_delete` substring drives the 429 status in
            // the ES error mapper (flood-stage rejections are 429, unlike an
            // explicit 403 write block). Mirrors ES's flood-stage message.
            return Err(XerjError::index_blocked(
                index,
                format!(
                    "read_only_allow_delete (disk usage {}% exceeded flood-stage watermark [{}%])",
                    self.disk_used_pct.load(Ordering::Relaxed),
                    self.disk_flood_pct.load(Ordering::Relaxed),
                ),
            ));
        }
        Ok(())
    }

    /// Effective flood-stage gate for `/_cat/allocation` (#2077).
    ///
    /// `flood_pct` is `limits.disk_flood_stage_percent` after a live
    /// `cluster.routing.allocation.disk.watermark.flood_stage` override.
    /// `0` means the watermark is off. `threshold_enabled` mirrors
    /// `cluster.routing.allocation.disk.threshold_enabled` (default true).
    /// `blocked` is the latched write block, including the 1% release
    /// hysteresis, so a volume that has dipped just under the threshold
    /// still reports that writes will be refused.
    pub fn disk_flood_admission(&self) -> DiskFloodAdmission {
        DiskFloodAdmission {
            flood_pct: self.disk_flood_pct.load(Ordering::Relaxed),
            threshold_enabled: self.disk_threshold_enabled.load(Ordering::Relaxed),
            blocked: self.disk_blocked.load(Ordering::Relaxed),
        }
    }

    /// Applies (or clears) a runtime override of the disk flood-stage
    /// percent, read each sampler tick from the
    /// `cluster.routing.allocation.disk.watermark.flood_stage` persistent
    /// cluster setting (parsed by [`parse_flood_stage_pct`]) — see
    /// `Engine::spawn_resource_sampler`. `None` reverts to the config
    /// default. A no-op when the watermark was disabled at startup
    /// (`disk_flood_stage_percent = 0`): this only re-tunes an
    /// already-active watermark without a restart, the way ES's
    /// `PUT _cluster/settings` does — it doesn't turn the feature on.
    pub fn set_disk_flood_pct_override(&self, override_pct: Option<u8>) {
        if self.disk_flood_pct_default == 0 {
            return;
        }
        let effective = override_pct.unwrap_or(self.disk_flood_pct_default).min(100);
        self.disk_flood_pct.store(effective, Ordering::Relaxed);
    }

    /// Applies the `cluster.routing.allocation.disk.threshold_enabled` cluster
    /// setting (`None` = unset = enabled).
    pub fn set_disk_threshold_enabled(&self, enabled: Option<bool>) {
        self.disk_threshold_enabled
            .store(enabled.unwrap_or(true), Ordering::Relaxed);
    }

    /// Applies (or clears) a runtime override of the parent RSS watermark, read
    /// each sampler tick from the `indices.breaker.total.limit` persistent
    /// cluster setting (parsed by [`parse_breaker_total_limit`]) — see
    /// `Engine::spawn_resource_sampler`. `None` reverts to the boot default.
    ///
    /// This is the live fix for the multi-index ingest oscillation (#1250): on
    /// a big box the AUTO tier caps the watermark conservatively (16 GiB on a
    /// 119 GiB host → it trips at ~15.5 GiB and sheds ALL writes), and the only
    /// prior remedy was `XERJ_MAX_PROCESS_MEMORY_MB` + a restart — which forced
    /// the indexing client into a full source-snapshot reconciliation. Raising
    /// the watermark via `PUT _cluster/settings` now needs no restart.
    ///
    /// `override_bytes` is clamped to `machine_memory_bytes` (a watermark above
    /// physical RAM cannot protect anything) and may be *below* the boot default
    /// too. A no-op when the watermark was disabled at startup
    /// (`memory_watermark_percent = 0`): like the disk override, this only
    /// re-tunes an already-active watermark, it never turns the feature on.
    pub fn set_memory_watermark_override(&self, override_bytes: Option<u64>) {
        if self.memory_watermark_bytes_default == 0 {
            return;
        }
        let effective = match override_bytes {
            Some(bytes) => bytes.min(self.machine_memory_bytes).max(1),
            None => self.memory_watermark_bytes_default,
        };
        self.memory_watermark_bytes
            .store(effective, Ordering::Relaxed);
    }

    /// Per-query memory guard for `max_query_memory_mb` (item 1). Rejects a
    /// query whose *estimated* peak allocation (`bytes`) exceeds the budget,
    /// before the allocation is made, with a 429 `circuit_breaking_exception`.
    /// `label` names the allocation site (e.g. "hydrate", "terms-agg").
    pub fn check_query_alloc(&self, bytes: u64, label: &str) -> Result<(), XerjError> {
        if self.max_query_memory_bytes != 0 && bytes > self.max_query_memory_bytes {
            return Err(XerjError::circuit_breaking(format!(
                "[request] query allocation ({}) would exceed limits.max_query_memory_mb={}MB \
                 at [{label}]; reduce size/aggregation cardinality",
                human_bytes(bytes),
                self.max_query_memory_bytes / (1024 * 1024),
            )));
        }
        Ok(())
    }

    /// Whether the per-query memory guard is active (non-zero budget).
    pub fn query_memory_enabled(&self) -> bool {
        self.max_query_memory_bytes != 0
    }

    // ── item 2: global search pool ──────────────────────────────────────

    /// Acquire one global search permit. Bounds process-wide search
    /// concurrency to `max_concurrent_searches`; the returned guard releases
    /// the permit (and decrements the in-flight gauge) on drop. Excess
    /// searches queue on the semaphore, exactly like ES's search thread
    /// pool bounds active workers.
    ///
    /// Under memory pressure (#2427) searches are non-write memory the RSS
    /// breaker never saw: the 1 GB release gate kept climbing from 5.1 GB to
    /// an 8.4 GB OOM with writes blocked, and its search phase ran 30 s
    /// multi-index searches against a node already over its watermark.
    /// While the breaker is engaged each search also takes the single
    /// `search_pressure` permit, so they run one at a time. At or above the
    /// hard process limit a new search is rejected with a 429
    /// `circuit_breaking_exception` once the drain has had
    /// [`SEARCH_HEADROOM_WAIT`] to bring RSS back under it.
    ///
    /// Read-budget isolation (#2427): bytes held by in-flight merge
    /// reservations do not count against a search (see
    /// [`Self::search_admission_rss`]); those merges yield at the merge-pool
    /// ceiling, below the limit. A search that still finds process memory at
    /// or above the limit waits up to [`SEARCH_HEADROOM_WAIT`] for the drain
    /// before it is rejected, instead of failing in milliseconds against a
    /// transient peak.
    pub async fn acquire_search(&self) -> Result<SearchPermit, XerjError> {
        let permit = Arc::clone(&self.search_pool)
            .acquire_owned()
            .await
            .map_err(|_| XerjError::internal("global search pool closed — shutting down"))?;
        let pressure = if self.memory_breaker_engaged() || self.check_search_hard_limit().is_err() {
            let p = Arc::clone(&self.search_pressure)
                .acquire_owned()
                .await
                .map_err(|_| XerjError::internal("search pressure gate closed — shutting down"))?;
            // RSS may have crossed the hard limit while this search queued.
            self.wait_for_search_headroom().await?;
            Some(p)
        } else {
            None
        };
        let now = self.search_inflight.fetch_add(1, Ordering::Relaxed) + 1;
        self.search_inflight_peak.fetch_max(now, Ordering::Relaxed);
        Ok(SearchPermit {
            _permit: permit,
            _pressure: pressure,
            inflight: Arc::clone(&self.search_inflight),
        })
    }

    /// Wait, holding the `search_pressure` permit, until the hard-limit check
    /// passes or [`Self::search_headroom_wait`] runs out (#2427). The sampler
    /// drains rebuildable state while the breaker is engaged; this gives that
    /// drain time to work before the search is turned away.
    async fn wait_for_search_headroom(&self) -> Result<(), XerjError> {
        let deadline = tokio::time::Instant::now() + self.search_headroom_wait;
        loop {
            match self.check_search_hard_limit() {
                Ok(()) => return Ok(()),
                Err(e) if tokio::time::Instant::now() >= deadline => return Err(e),
                Err(_) => tokio::time::sleep(SEARCH_HEADROOM_POLL).await,
            }
        }
    }

    /// Process memory a search is admitted against (#2427): the last RSS
    /// sample less the bytes in-flight merges hold in the merge ledger. Those
    /// merges must yield at the merge-pool ceiling, so their bytes are
    /// already on their way out and are not the read path's to pay for.
    fn search_admission_rss(&self) -> u64 {
        let rss = self.rss_bytes.load(Ordering::Relaxed);
        rss.saturating_sub(self.merge_reserved_bytes())
    }

    /// RSS line at which new searches are rejected (#2427): the process
    /// memory limit, or the live watermark if an operator raised it past
    /// that (#1323). `0` when no limit is known.
    fn search_hard_limit_bytes(&self) -> u64 {
        let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
        if watermark == 0 {
            return 0;
        }
        self.memory_limit_bytes.max(watermark)
    }

    fn check_search_hard_limit(&self) -> Result<(), XerjError> {
        let limit = self.search_hard_limit_bytes();
        let rss = self.search_admission_rss();
        if limit != 0 && rss >= limit {
            return Err(XerjError::circuit_breaking(format!(
                "[parent] Data too large: process memory [{rss}/{}] is at or above the memory limit [{limit}/{}] after waiting for the memory breaker to drain; search rejected",
                human_bytes(rss),
                human_bytes(limit)
            )));
        }
        Ok(())
    }

    /// Current in-flight search count (for stats / proof).
    pub fn search_inflight(&self) -> u64 {
        self.search_inflight.load(Ordering::Relaxed)
    }

    /// Peak concurrent search count observed since boot (for proof).
    pub fn search_inflight_peak(&self) -> u64 {
        self.search_inflight_peak.load(Ordering::Relaxed)
    }

    /// Configured global search-concurrency cap.
    pub fn max_concurrent_searches(&self) -> usize {
        self.max_concurrent_searches
    }

    // ── item 2b: global bulk pool ──────────────────────────────────────

    /// Acquire one global bulk permit. Bounds process-wide bulk-parse
    /// concurrency to `max_concurrent_bulks` (default 8), preventing N
    /// concurrent bulks from each materializing ~300 B/action of parse-phase
    /// heap before the memtable admission check fires.
    pub async fn acquire_bulk(&self) -> Result<tokio::sync::OwnedSemaphorePermit, XerjError> {
        self.bulk_pool
            .clone()
            .acquire_owned()
            .await
            .map_err(|_| XerjError::internal("global bulk pool closed — shutting down"))
    }

    /// Configured global bulk-concurrency cap.
    pub fn max_concurrent_bulks(&self) -> usize {
        self.max_concurrent_bulks
    }

    // ── Sampler surface (called by the background task) ─────────────────

    /// Refresh every sampled atomic in one call (memtable, RSS, disk).
    /// Convenience wrapper used by tests; the live sampler calls
    /// [`Self::refresh_memory_disk`] and [`Self::refresh_memtable`]
    /// SEPARATELY so a contended memtable read can never delay the memory
    /// admission update (see `Engine::spawn_resource_sampler`).
    pub fn refresh(&self, memtable_used: u64, rss: u64, disk_used_pct: u64) {
        self.refresh_memory_disk(rss, disk_used_pct, 0);
        self.refresh_memtable(memtable_used);
    }

    /// Update the RSS + disk atomics and their latched trip flags. Depends on
    /// NOTHING but two syscalls — never blocks on an engine lock — so the
    /// parent memory breaker stays responsive even while a turbo batch holds
    /// every memtable shard's write lock.
    ///
    /// `disk_avail_bytes` is the raw free-space figure from the same
    /// `statvfs` sample as `disk_used_pct` — carried through purely so the
    /// crossing WARN below can print an absolute free-space figure
    /// alongside the percentage, matching ES's flood-stage log line. Pass
    /// `0` when it isn't available (e.g. from the [`Self::refresh`] test
    /// wrapper); it only affects that one log line, never admission.
    pub fn refresh_memory_disk(&self, rss: u64, disk_used_pct: u64, disk_avail_bytes: u64) {
        self.refresh_memory_observing(rss, disk_used_pct, disk_avail_bytes, None);
    }

    /// [`Self::refresh_memory_disk`] plus an optional Windows available-commit
    /// sample. `None` leaves the commit latch as it was (Linux, and tests
    /// that only move RSS). A `Some` below the commit reserve engages the
    /// breaker even when `rss` is under the watermark (#1122). Once commit is
    /// back above the reserve the RSS latch alone decides, and that latch
    /// never releases at or above the watermark (#2427).
    pub fn refresh_memory_observing(
        &self,
        rss: u64,
        disk_used_pct: u64,
        disk_avail_bytes: u64,
        available_commit: Option<u64>,
    ) {
        // ── RSS watermark, with release hysteresis (#1250, #2427) ──
        //
        // Engage at `rss >= watermark`. Once engaged, the latch releases below
        // `memory_release_percent` of the watermark (85% by default) after the
        // breaker has been engaged for `memory_min_engaged`. Inside the band
        // `[release, watermark)` it holds while the drain is still lowering
        // RSS. A 95% band that released on the first sample that did not fall
        // flapped 20 times in 16 minutes under autoindex (#2427), each release
        // re-admitting the write burst that tripped it. If RSS does not fall
        // past [`MEMORY_RSS_NOISE_BYTES`] inside the band for
        // [`MEMORY_BAND_STALL_RELEASE`], the drain has nothing more to free:
        // holding would only reject writes the node can take and keep the
        // sampler re-draining forever, so the latch releases.
        //
        // At or above the watermark the latch never releases (#2427). The
        // #1981 flat-footprint release that used to apply there is gone: it
        // released a node at 5,121MB against a 2,918MB watermark. A live
        // watermark change (#1323) is judged against the operator's new
        // value on that sample.
        self.rss_bytes.store(rss, Ordering::Relaxed);
        let watermark = self.memory_watermark_bytes.load(Ordering::Relaxed);
        let cur_mem = self.memory_tripped.load(Ordering::Relaxed);
        let retuned = self.memory_trip_watermark.load(Ordering::Relaxed) != watermark;
        // #2427: the release point is `memory_release_percent` of the
        // watermark (85% by default, was a fixed 95%).
        let release_bytes = memory_release_bytes(watermark, self.memory_release_percent);
        // `None` keeps the previous latch so an RSS-only refresh (Linux, and
        // the test helper) does not clear a commit trip it did not sample.
        // Reserve 0 means this platform has no commit probe: starved stays
        // false and the RSS formula below is the pre-#1122 check.
        let starved = if self.commit_reserve_bytes == 0 {
            false
        } else if let Some(available) = available_commit {
            self.available_commit_bytes
                .store(available, Ordering::Relaxed);
            available < self.commit_reserve_bytes
        } else {
            self.commit_starved.load(Ordering::Relaxed)
        };
        self.commit_starved.store(starved, Ordering::Relaxed);
        // RSS latch (#1250, #2427). Commit starvation is applied after this
        // so a pagefileless box stays engaged while available commit is
        // under the reserve.
        let rss_next = watermark != 0
            && if rss >= watermark {
                // #2427: at or above the watermark the RSS latch ALWAYS holds
                // (or engages). There is no release up here, whatever the
                // footprint is doing. The #1981 flat-footprint release that
                // used to live in this arm let a 1 GB release-gate node
                // release at rss=5,121MB against a 2,918MB watermark, re-engage
                // 100 ms later at 5,125MB, and get OOM-killed at 8.4 GB. The
                // drain backoff (`MemoryDrainSchedule`) is what keeps a
                // footprint that will not fall from re-draining every 2 s.
                self.memory_band_anchor.store(0, Ordering::Relaxed);
                self.clear_memory_flat();
                true
            } else if cur_mem && !retuned {
                // #2427 release hysteresis, strictly below the watermark.
                // Below the release point, release once the minimum engaged
                // time has passed. Inside the band, hold while the drain is
                // still lowering RSS; if RSS has not fallen past the noise
                // band for MEMORY_BAND_STALL_RELEASE, the drain has nothing
                // left to free, so release rather than reject writes forever
                // (#1250).
                let min_met = self.memory_engaged_for() >= self.memory_min_engaged;
                if rss < release_bytes {
                    self.clear_memory_flat();
                    self.memory_band_anchor.store(0, Ordering::Relaxed);
                    !min_met
                } else {
                    let anchor = self.memory_band_anchor.load(Ordering::Relaxed);
                    if anchor == 0 || rss.saturating_add(MEMORY_RSS_NOISE_BYTES) < anchor {
                        // Entered the band, or fell past the noise band:
                        // the drain is working. Restart the stall clock.
                        self.memory_band_anchor.store(rss, Ordering::Relaxed);
                        self.clear_memory_flat();
                        self.note_memory_flat();
                        true
                    } else {
                        let stalled = self.note_memory_flat() >= MEMORY_BAND_STALL_RELEASE;
                        if stalled && min_met {
                            self.clear_memory_flat();
                            self.memory_band_anchor.store(0, Ordering::Relaxed);
                            false
                        } else {
                            true
                        }
                    }
                }
            } else {
                // Disengaged under the watermark, or a live retune (#1323)
                // that put RSS under the operator's new value.
                self.clear_memory_flat();
                self.memory_band_anchor.store(0, Ordering::Relaxed);
                false
            };
        // #2427 invariant: the RSS latch never reports released while RSS is
        // at or above the live watermark.
        debug_assert!(rss_next || watermark == 0 || rss < watermark);
        let mem_next = starved || rss_next;
        if mem_next {
            self.memory_trip_watermark
                .store(watermark, Ordering::Relaxed);
        }
        if mem_next != self.memory_tripped.swap(mem_next, Ordering::Relaxed) {
            // Only an RSS engage starts the minimum-engaged clock: a Windows
            // commit trip releases as soon as commit recovers.
            self.set_memory_engaged_since((mem_next && rss_next).then(Instant::now));
            if mem_next && starved {
                tracing::warn!(
                    available_commit_mb = self.available_commit_bytes.load(Ordering::Relaxed)
                        / (1024 * 1024),
                    commit_limit_mb = self.commit_limit_bytes / (1024 * 1024),
                    reserve_mb = self.commit_reserve_bytes / (1024 * 1024),
                    "available Windows commit is under the reserve — engaging the parent memory circuit breaker (writes → 429)"
                );
            } else if mem_next {
                tracing::warn!(
                    rss_mb = rss / (1024 * 1024),
                    watermark_mb = watermark / (1024 * 1024),
                    "RSS crossed the memory watermark — engaging the parent memory circuit breaker (writes → 429)"
                );
            } else {
                tracing::info!(
                    rss_mb = rss / (1024 * 1024),
                    release_mb = release_bytes / (1024 * 1024),
                    "RSS back below the memory watermark — releasing the memory circuit breaker"
                );
            }
        }

        // ── disk flood stage (1% release hysteresis to avoid flapping) ──
        let flood_pct = self.disk_flood_pct.load(Ordering::Relaxed);
        if flood_pct != 0 {
            self.disk_used_pct.store(disk_used_pct, Ordering::Relaxed);
            let cur = self.disk_blocked.load(Ordering::Relaxed);
            let release_pct = (flood_pct as u64).saturating_sub(1);
            let enabled = self.disk_threshold_enabled.load(Ordering::Relaxed);
            let next = if !enabled {
                false
            } else if cur {
                disk_used_pct >= release_pct
            } else {
                disk_used_pct >= flood_pct as u64
            };
            if next != cur {
                if next {
                    tracing::warn!(
                        used_pct = disk_used_pct,
                        flood_pct = flood_pct,
                        free = %human_bytes(disk_avail_bytes),
                        "disk flood-stage watermark crossed — engaging read_only_allow_delete write block"
                    );
                } else if !enabled {
                    tracing::info!(
                        used_pct = disk_used_pct,
                        "disk threshold disabled by cluster setting — releasing write block"
                    );
                } else {
                    tracing::info!(
                        used_pct = disk_used_pct,
                        "disk usage back below flood-stage watermark — releasing write block"
                    );
                }
            }
            self.disk_blocked.store(next, Ordering::Relaxed);
        }
    }

    /// Update the summed-memtable atomic + its trip flag. Called AFTER
    /// [`Self::refresh_memory_disk`] in the sampler, because computing the sum
    /// reads a lock on every memtable shard and a turbo batch can hold those
    /// write-locked for the whole batch — blocking here must never stall the
    /// memory/disk update above.
    pub fn refresh_memtable(&self, memtable_used: u64) {
        self.memtable_used_bytes
            .store(memtable_used, Ordering::Relaxed);
        let next = self.memtable_budget_bytes != 0 && memtable_used >= self.memtable_budget_bytes;
        if next != self.memtable_tripped.swap(next, Ordering::Relaxed) {
            if next {
                tracing::warn!(
                    used_mb = memtable_used / (1024 * 1024),
                    budget_mb = self.memtable_budget_bytes / (1024 * 1024),
                    "summed memtable crossed the process budget — engaging the parent circuit breaker (writes → 429)"
                );
            } else {
                tracing::info!(
                    used_mb = memtable_used / (1024 * 1024),
                    "summed memtable back below the process budget — releasing the parent circuit breaker"
                );
            }
        }
    }

    // ── Observability ───────────────────────────────────────────────────

    /// Snapshot of the current governor state for `_nodes/stats`-style
    /// surfaces.
    pub fn snapshot(&self) -> GovernorSnapshot {
        GovernorSnapshot {
            segment_hydration: self.segment_hydration_budget.snapshot(),
            segment_hydration_source: self.segment_hydration_budget_source,
            memtable_used_bytes: self.memtable_used_bytes.load(Ordering::Relaxed),
            memtable_budget_bytes: self.memtable_budget_bytes,
            memtable_tripped: self.memtable_tripped.load(Ordering::Relaxed),
            rss_bytes: self.rss_bytes.load(Ordering::Relaxed),
            memory_limit_bytes: self.memory_limit_bytes,
            memory_watermark_bytes: self.memory_watermark_bytes.load(Ordering::Relaxed),
            memory_tripped: self.memory_tripped.load(Ordering::Relaxed),
            disk_used_pct: self.disk_used_pct.load(Ordering::Relaxed),
            disk_flood_pct: self.disk_flood_pct.load(Ordering::Relaxed),
            disk_blocked: self.disk_blocked.load(Ordering::Relaxed),
            max_concurrent_searches: self.max_concurrent_searches,
            search_inflight: self.search_inflight.load(Ordering::Relaxed),
            search_inflight_peak: self.search_inflight_peak.load(Ordering::Relaxed),
            max_concurrent_bulks: self.max_concurrent_bulks,
        }
    }

    pub fn segment_hydration_budget(&self) -> Arc<SegmentHydrationBudget> {
        Arc::clone(&self.segment_hydration_budget)
    }
}

/// RAII guard for a held global search permit. Decrements the in-flight
/// gauge on drop; the underlying semaphore permit is released with it.
pub struct SearchPermit {
    _permit: OwnedSemaphorePermit,
    /// The memory-pressure gate's single permit, held when the search was
    /// admitted while the RSS breaker was engaged (#2427).
    _pressure: Option<OwnedSemaphorePermit>,
    inflight: Arc<AtomicU64>,
}

impl Drop for SearchPermit {
    fn drop(&mut self) {
        self.inflight.fetch_sub(1, Ordering::Relaxed);
    }
}

