    #[test]
    fn cidr_term_on_an_ip_field_rewrites_to_the_subnet_range() {
        // #782: a CIDR `term` on an ip field silently returned 0 after a flush
        // because the segment term-dictionary lookup can't expand a CIDR. Fix:
        // rewrite it to the equivalent inclusive range (which every path
        // handles) before execution.
        assert_eq!(
            cidr_to_ip_range("192.168.1.0/24"),
            Some(("192.168.1.0".to_string(), "192.168.1.255".to_string()))
        );
        assert_eq!(
            cidr_to_ip_range("192.168.1.0/25"),
            Some(("192.168.1.0".to_string(), "192.168.1.127".to_string()))
        );
        assert_eq!(
            cidr_to_ip_range("10.0.0.1/32"),
            Some(("10.0.0.1".to_string(), "10.0.0.1".to_string()))
        );
        assert_eq!(
            cidr_to_ip_range("192.168.0.0/16"),
            Some(("192.168.0.0".to_string(), "192.168.255.255".to_string()))
        );
        assert_eq!(cidr_to_ip_range("not-a-cidr"), None);
        assert_eq!(cidr_to_ip_range("192.168.1.5"), None);

        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("addr", FieldType::Ip))
            .unwrap();
        schema
            .add_field(FieldConfig::new("name", FieldType::Keyword))
            .unwrap();

        let term = |f: &str, v: serde_json::Value| QueryNode::Term {
            field: f.into(),
            value: v,
            boost: None,
        };
        // CIDR term on the ip field -> inclusive [network, broadcast] range.
        match rewrite_query_aliases(&term("addr", json!("192.168.1.0/24")), &schema) {
            QueryNode::Range {
                field,
                gte,
                lte,
                gt,
                lt,
                ..
            } => {
                assert_eq!(field, "addr");
                assert_eq!(gte, Some(json!("192.168.1.0")));
                assert_eq!(lte, Some(json!("192.168.1.255")));
                assert_eq!(gt, None);
                assert_eq!(lt, None);
            }
            other => panic!("#782: CIDR term on ip must rewrite to a Range, got {other:?}"),
        }
        // A non-CIDR (exact) term on the ip field stays a Term.
        assert!(matches!(
            rewrite_query_aliases(&term("addr", json!("192.168.1.5")), &schema),
            QueryNode::Term { .. }
        ));
        // A CIDR-looking value on a NON-ip field is a literal string, unchanged.
        assert!(matches!(
            rewrite_query_aliases(&term("name", json!("192.168.1.0/24")), &schema),
            QueryNode::Term { .. }
        ));
    }

    #[test]
    fn boolean_term_and_terms_spellings_normalise_to_the_indexed_value() {
        // #781 follow-up: ingest coercion canonicalises `"true"`/`"false"` to
        // real JSON booleans in `_source`, so a query still spelling them as
        // strings named a value no document held. On a doc-values-only boolean
        // (`390_doc_values_search.yml`) that meant `terms` returned 0 while the
        // equivalent `term` still found the doc. Both arms now run the query
        // value through the SAME `field_coercion` predicate the write path uses.
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("flag", FieldType::Boolean))
            .unwrap();
        schema
            .add_field(FieldConfig::new("name", FieldType::Keyword))
            .unwrap();

        let term = |f: &str, v: serde_json::Value| QueryNode::Term {
            field: f.into(),
            value: v,
            boost: None,
        };
        let terms = |f: &str, v: Vec<serde_json::Value>| QueryNode::Terms {
            field: f.into(),
            values: v,
            boost: None,
        };

        match rewrite_query_aliases(&term("flag", json!("false")), &schema) {
            QueryNode::Term { field, value, .. } => {
                assert_eq!(field, "flag");
                assert_eq!(value, json!(false), "string spelling names the boolean");
            }
            other => panic!("boolean term must stay a Term, got {other:?}"),
        }
        match rewrite_query_aliases(&terms("flag", vec![json!("false"), json!(true)]), &schema) {
            QueryNode::Terms { field, values, .. } => {
                assert_eq!(field, "flag");
                assert_eq!(values, vec![json!(false), json!(true)]);
            }
            other => panic!("boolean terms must stay a Terms, got {other:?}"),
        }
        // A value the ingest predicate refuses is left alone — a search must
        // not 400 on it; it simply matches nothing, exactly as before.
        match rewrite_query_aliases(&terms("flag", vec![json!("yes"), json!(1)]), &schema) {
            QueryNode::Terms { values, .. } => assert_eq!(values, vec![json!("yes"), json!(1)]),
            other => panic!("unparseable boolean values must survive, got {other:?}"),
        }
        // A NON-boolean field keeps its literal string — `"true"` is a keyword.
        match rewrite_query_aliases(&term("name", json!("true")), &schema) {
            QueryNode::Term { value, .. } => assert_eq!(value, json!("true")),
            other => panic!("keyword term must be untouched, got {other:?}"),
        }
    }

    async fn assert_active_reader_waits_for_commit<F, Fut>(
        idx: &Arc<Index>,
        id: &'static str,
        point: PublicationTestPoint,
        operation: F,
        exists_after: bool,
    ) where
        F: FnOnce(Arc<Index>) -> Fut,
        Fut: std::future::Future<Output = std::result::Result<(), String>> + Send + 'static,
    {
        let (entered_tx, entered_rx) = std::sync::mpsc::sync_channel(1);
        let (resume_tx, resume_rx) = std::sync::mpsc::sync_channel(1);
        let entered_tx = parking_lot::Mutex::new(Some(entered_tx));
        let resume_rx = parking_lot::Mutex::new(Some(resume_rx));
        idx.set_publication_test_hook(Some(Arc::new(move |hook_id, hook_point| {
            if hook_id == id && hook_point == point {
                entered_tx.lock().take().unwrap().send(()).unwrap();
                resume_rx.lock().take().unwrap().recv().unwrap();
            }
        })));
        let writer = tokio::spawn(operation(Arc::clone(idx)));
        tokio::task::spawn_blocking(move || entered_rx.recv().unwrap())
            .await
            .unwrap();
        let attempts_before = idx.collection_publication.reader_admission_attempts();
        let read_idx = Arc::clone(idx);
        let read = tokio::spawn(async move { read_idx.get_document(id).await });
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while idx.collection_publication.reader_admission_attempts() == attempts_before {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("GET did not reach collection publication admission");
        assert!(!read.is_finished(), "GET crossed {point:?} for {id}");
        resume_tx.send(()).unwrap();
        writer.await.unwrap().unwrap();
        let observed = read.await.unwrap().unwrap();
        assert_eq!(
            observed.is_some(),
            exists_after,
            "unexpected committed visibility for {id} at {point:?}"
        );
        assert!(!idx.collection_publication.state().2);
        idx.set_publication_test_hook(None);
    }

