        assert_eq!(idx.collection_publication.state(), before);
        assert_eq!(
            idx.get_document("one").await.unwrap().unwrap()["body"],
            "original"
        );
    }

    /// #421: the memtable pre-clone rejection must be META-AWARE. A `_seq_no`
    /// sort resolves its key from the version map (`meta_sort_value`), the same
    /// resolver the heap ranks on, so `memtable_primary_key_rejects` can and
    /// must reject a doc whose `_seq_no` is strictly worse than the bounded
    /// frontier — skipping its `_source` clone. Before the fix the gate
    /// declined every meta-sort field and returned `false` for this exact call,
    /// forcing the full O(memtable) clone-and-offer walk (#401's `search_after`
    /// latency cliff).
    #[tokio::test]
    async fn memtable_preclone_rejection_is_meta_aware_for_seq_no() {
        use std::sync::Arc;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index("seq-reject", text_schema()).unwrap();
        let idx = engine.get_index("seq-reject").unwrap();
        idx.abort_background_tasks();
        for i in 0..6u64 {
            idx.index_document(Some(format!("d{i}")), json!({ "body": format!("doc {i}") }))
                .await
                .unwrap();
        }

        // Hits sorted by `_seq_no` asc: d0..d5 with strictly increasing seq_no.
        let req = xerj_query::parse_request(&json!({
            "query": {"match_all": {}},
            "size": 6,
            "sort": [{"_seq_no": "asc"}],
        }))
        .unwrap();
        let all = idx.search(&req).await.unwrap().hits;
        assert_eq!(all.len(), 6, "corpus size");

        // Fill a size-5 frontier with the five lowest-`_seq_no` docs (d0..d4).
        let mut topk = super::SortTopK::new(Arc::new(req.sort.clone()), 5, None);
        for (seq, hit) in all[..5].iter().enumerate() {
            topk.offer(hit.clone(), seq as u64, &idx);
        }

        // d5 (highest `_seq_no`) is strictly worse than the frontier for an ASC
        // sort → the meta-aware pre-clone gate MUST reject it (before the fix:
        // `false`, the whole point of #421).
        let worse = &all[5];
        assert!(
            super::memtable_primary_key_rejects(&topk, &worse.source, &worse.id, &idx),
            "#421: a `_seq_no` sort must reject a worse-than-frontier doc via the \
             pre-clone gate"
        );
        // Sanity: the best-`_seq_no` doc belongs on the page and must NOT be rejected.
        let best = &all[0];
        assert!(
            !super::memtable_primary_key_rejects(&topk, &best.source, &best.id, &idx),
            "the best `_seq_no` doc belongs on the page and must not be rejected"
        );
    }

    /// #421 "Also unresolved": `_id`'s numeric-prefilter safety rests on a TYPE
    /// invariant, not a gate. `compute_sort_values` emits the `_id` sort value as
    /// a `String`, so `SortTopK::primary_f64_rejects`'s `as_f64()` is always
    /// `None` for an `_id` sort and the numeric pre-filter never mis-rejects a
    /// hit. The invariant held but had no binding test; pin it, so a change that
    /// makes the `_id` sort value numeric fails here instead of silently
    /// re-opening the defect the code comment warns about.
    #[tokio::test]
    async fn id_sort_value_stays_a_string_so_the_numeric_prefilter_declines_it() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("id-sort-invariant", text_schema())
            .unwrap();
        let idx = engine.get_index("id-sort-invariant").unwrap();
        idx.abort_background_tasks();

        let req = xerj_query::parse_request(&json!({
            "query": {"match_all": {}},
            "sort": [{"_id": "asc"}],
        }))
        .unwrap();

        let vals =
            super::compute_sort_values(&json!({"body": "x"}), 1.0, "doc-42", &req.sort, &idx);
        assert_eq!(vals.len(), 1, "one sort field yields one sort value");
        assert!(
            matches!(&vals[0], serde_json::Value::String(s) if s == "doc-42"),
            "#421: the `_id` sort value must be a String (got {:?}); a numeric value \
             would let SortTopK::primary_f64_rejects' as_f64() apply and mis-reject an \
             `_id`-sorted hit",
            vals[0]
        );
        // The consumer end: `as_f64()` on the `_id` sort value is `None`, which is
        // exactly what keeps the numeric pre-filter from ever touching an `_id` sort.
        assert!(
            vals[0].as_f64().is_none(),
            "an `_id` sort value must not be numeric"
        );
    }

    /// #421 "Also unresolved": `sorted_shadow_for`'s correctness rests on
    /// `build_doc_value_columns` skipping `_`-prefixed source keys — `_seq_no`,
    /// `_id`, `_source` and friends are envelope bookkeeping, not user data, and
    /// must never be shadowed into a doc-value column from `_source` (a meta
    /// field is resolved from the version map, never from a source column). That
    /// invariant lived only in a comment (index.rs, the `starts_with('_')` skip)
    /// with no test binding it to `sorted_shadow_for`. Pin it: a source doc
    /// carrying `_`-prefixed keys must yield NO column for them, so removing the
    /// skip fails here instead of silently shadowing meta-fields.
    #[test]
    fn build_doc_value_columns_skips_underscore_prefixed_source_keys() {
        let doc = json!({"_seq_no": 5, "_id": "abc", "title": "hello", "count": 42});
        let skip = std::collections::HashSet::new();
        let cols = super::build_doc_value_columns([Some(&doc)].into_iter(), &skip);
        assert!(
            !cols.keys().any(|k| k.starts_with('_')),
            "#421: no `_`-prefixed source key may become a doc-value column (got {:?})",
            cols.keys().collect::<Vec<_>>()
        );
        // Sanity so the assertion above is not vacuously true: real user fields
        // DO get shadowed, so the function did build columns — it just excluded
        // the meta keys.
        assert!(
            cols.contains_key("title") && cols.contains_key("count"),
            "user fields must be shadowed into columns (got {:?})",
            cols.keys().collect::<Vec<_>>()
        );
    }

    /// A field that is TYPE-mixed inside one segment must ship NO doc-values
    /// column. Only one column can carry a name, so the keyword pass would
    /// overwrite the numeric one and file every number/boolean doc as null —
    /// a column consumers treat as exact, which then hides those docs from the
    /// `term`/`terms` prefilter entirely.
    ///
    /// #781 made this reachable in ordinary use: ingest coercion canonicalises
    /// `"true"` to `true`, so an index written across the upgrade holds both
    /// spellings, and a flush that lands them in ONE segment (the 2-core CI
    /// shape) built the lying column — `terms {b:["true"]}` then returned the
    /// pre-upgrade document and silently dropped the coerced one.
    /// #2427: the merge builds doc-values from its merged stored JSON one
    /// document at a time instead of holding every `_source` tree. The
    /// columns must match what the held trees produced, ordinals included:
    /// a document with no `_source`, a non-object `_source`, and one that
    /// does not parse as an object each keep their row.
    #[test]
    fn merge_doc_value_sources_matches_held_source_trees() {
        let docs = [
            json!({"_id": "a", "_seq_no": 1, "_source": {"k": "x", "n": 1, "b": true}}),
            json!({"_id": "b", "_seq_no": 2}),
            json!({"_id": "c", "_seq_no": 3, "_source": {"k": "y", "n": 2.5, "arr": [1, 2]}}),
            json!({"_id": "d", "_seq_no": 4, "_source": "not-an-object"}),
            json!({"_id": "e", "_seq_no": 5, "_source": {"k": "z", "msg": "hello"}}),
        ];
        let mut merged = b"[".to_vec();
        for (i, doc) in docs.iter().enumerate() {
            if i > 0 {
                merged.push(b',');
            }
            merged.extend_from_slice(serde_json::to_string(doc).unwrap().as_bytes());
        }
        // A raw element that is not an object takes a row too.
        merged.extend_from_slice(b",42]");

        let mut skip = std::collections::HashSet::new();
        skip.insert("msg".to_string());

        // The pre-#2427 input: one held `_source` tree per document.
        let mut held: Vec<Value> = docs
            .iter()
            .map(|doc| doc.get("_source").cloned().unwrap_or(Value::Null))
            .collect();
        held.push(Value::Null);
        let expected = super::build_doc_value_columns(held.iter().map(Some), &skip);

        let streamed = super::build_doc_value_columns(
            super::merge_doc_value_sources(&merged).expect("array parses"),
            &skip,
        );
        assert_eq!(
            format!("{streamed:?}"),
            format!("{expected:?}"),
            "streamed doc-values must equal the held-tree build"
        );
        assert!(streamed.contains_key("k") && streamed.contains_key("n"));
        assert!(
            !streamed.contains_key("arr"),
            "multi-valued field ships no column"
        );
        assert_eq!(
            super::merge_doc_value_sources(&merged).unwrap().count(),
            docs.len() + 1,
            "one item per merged document, in order"
        );
        assert!(super::merge_doc_value_sources(b"not json").is_err());
    }

    #[test]
    fn build_doc_value_columns_ships_nothing_for_a_type_mixed_field() {
        let legacy = json!({"b": "true", "n": "5", "ok": "kw"});
        let coerced = json!({"b": true, "n": 5, "ok": "kw"});
        let skip = std::collections::HashSet::new();
        let cols =
            super::build_doc_value_columns([Some(&legacy), Some(&coerced)].into_iter(), &skip);
        assert!(
            !cols.contains_key("b") && !cols.contains_key("n"),
            "a type-mixed field must ship no column (got {:?})",
            cols.keys().collect::<Vec<_>>()
        );
        // Not vacuous: a field that stayed one type still gets its column.
        assert!(
            cols.contains_key("ok"),
            "a single-typed field must still be shadowed (got {:?})",
            cols.keys().collect::<Vec<_>>()
        );
    }

    /// `doc_values: false` fields (text, semantic_text) record presence, not
    /// values. The bit must follow `value_present`: empty string and a
    /// non-null array element are present; null, `[]`, and `[null]` are not.
    /// An all-absent field still ships a column so `exists` can answer
    /// "no" without a source scan.
    #[test]
    fn build_doc_value_columns_presence_matches_value_present() {
        use xerj_storage::doc_values::Column;
        let mut skip = std::collections::HashSet::new();
        skip.insert("msg".to_string());
        skip.insert("never".to_string());
        let docs = [
            json!({"ax_file": "a"}),
            json!({"ax_file": "a", "msg": null}),
            json!({"ax_file": "a", "msg": []}),
            json!({"ax_file": "a", "msg": ""}),
            json!({"ax_file": "a", "msg": [null]}),
            json!({"ax_file": "a", "msg": "hello"}),
            json!({"ax_file": "a", "msg": [null, "x"]}),
        ];
        let cols = super::build_doc_value_columns(docs.iter().map(Some), &skip);
        let Some(Column::Presence(msg)) = cols.get("msg") else {
            panic!("msg must be a presence column, got {:?}", cols.get("msg"));
        };
        assert_eq!(msg.doc_count, 7);
        assert!(!msg.contains(0) && !msg.contains(1) && !msg.contains(2) && !msg.contains(4));
        assert!(msg.contains(3) && msg.contains(5) && msg.contains(6));
        assert_eq!(msg.count(), 3);
        let Some(Column::Presence(never)) = cols.get("never") else {
            panic!("an all-absent skipped field must still ship a presence column");
        };
        assert_eq!(never.doc_count, 7);
        assert_eq!(never.count(), 0);
        assert!(matches!(cols.get("ax_file"), Some(Column::Keyword(_))));
    }

    /// A dotted mapping name is an object sub-field. The builder only walks
    /// top-level `_source` keys, so it cannot see `user.bio` inside
    /// `{"user": {"bio": ..}}`. It must ship no presence column for it (the
    /// reader then scans source) rather than an empty one that says no row
    /// has the field.
    #[test]
    fn build_doc_value_columns_ships_no_presence_for_a_dotted_text_field() {
        let mut skip = std::collections::HashSet::new();
        skip.insert("user.bio".to_string());
        let docs = [json!({"user": {"bio": "hello"}}), json!({"user": {}})];
        let cols = super::build_doc_value_columns(docs.iter().map(Some), &skip);
        assert!(
            !cols.contains_key("user.bio"),
            "a dotted field must not get a presence column: {:?}",
            cols.get("user.bio")
        );
    }

    async fn assert_flush_freeze_keeps_readers_live_then_finishes(inject_error: bool) {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let name = if inject_error {
            "epoch-flush-rollback"
        } else {
            "epoch-flush-commit"
        };
        engine.create_index(name, text_schema()).unwrap();
        let idx = engine.get_index(name).unwrap();
        idx.abort_background_tasks();
        idx.index_document(Some("one".into()), json!({"body": "alpha"}))
            .await
            .unwrap();

        let ledger: &'static crate::ingest_memory::Ledger =
            Box::leak(Box::new(crate::ingest_memory::Ledger::new()));
        // `entered` fires from `build_fts`, which runs inside the flush
        // finalize's `spawn_blocking`; waiting for it on the blocking pool can
        // starve the very closure that signals it (`await_publication_barrier`).
        let (entered_tx, entered_rx) = tokio::sync::oneshot::channel::<()>();
        let (resume_tx, resume_rx) = std::sync::mpsc::sync_channel(1);
        let entered_tx = parking_lot::Mutex::new(Some(entered_tx));
        let resume_rx = parking_lot::Mutex::new(Some(resume_rx));
        let hook = FlushPublisherTestHook {
            callback: Arc::new(move || {
                let _ = entered_tx.lock().take().unwrap().send(());
                resume_rx.lock().take().unwrap().recv().unwrap();
                inject_error
            }),
            after_warm: None,
            ledger,
            target_memtable: Arc::as_ptr(&idx.memtable) as usize,
            bypass_finalize_gate: false,
            before_blocking_spawn: None,
        };
        let flush_idx = Arc::clone(&idx);
        let flush = tokio::spawn(
            FLUSH_PUBLISHER_TEST_HOOK.scope(hook, async move { flush_idx.flush().await }),
        );
        await_publication_barrier(entered_rx, "entered").await;
        // #1015: the drain is a FREEZE.  The drained docs stay resident in
        // the shard's frozen generations — reader-visible and byte-charged —
        // for the whole segment build; they leave only at `retire()` inside
        // the millisecond-scale publish bracket.  (Pre-#1015 the drain
        // removed them from the memtable here and readers waited out the
        // whole build behind the publication guard.)
        assert_eq!(
            idx.memtable.doc_count(),
            1,
            "freeze must keep the drained docs resident until retire (#1015)"
        );
        assert!(
            idx.memtable.contains("one"),
            "frozen doc left the reader view at freeze"
        );

        let attempts_before = idx.collection_publication.reader_admission_attempts();
        let read_idx = Arc::clone(&idx);
        let read = tokio::spawn(async move { read_idx.get_document("one").await });
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while idx.collection_publication.reader_admission_attempts() == attempts_before {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("GET did not reach collection publication admission");
        // The build holds NO publication bracket, so the GET must run to
        // completion against the frozen generation instead of waiting —
        // this is the #1015 acceptance property at unit scale.
        let read_during_build = tokio::time::timeout(std::time::Duration::from_secs(1), read)
            .await
            .expect("GET stayed blocked across the flush build")
            .unwrap()
            .unwrap()
            .unwrap();
        assert_eq!(
            read_during_build["body"], "alpha",
            "GET during the build must serve the frozen doc"
        );
        resume_tx.send(()).unwrap();

        let result = flush.await.unwrap();
        assert_eq!(result.is_err(), inject_error);
        // A fresh read AFTER the flush finished: the commit path serves the
        // published segment, the failure path serves the still-frozen
        // generation whose claim was released.
        let read_after = idx.get_document("one").await.unwrap().unwrap();
        assert_eq!(
            read_after["body"], "alpha",
            "reader did not observe the completed commit or released rollback"
        );
        assert!(!idx.collection_publication.state().2);
        if inject_error {
            assert_eq!(
                idx.memtable.doc_count(),
                1,
                "failed build must release the claim, not drop the docs"
            );
        } else {
            assert_eq!(idx.memtable.doc_count(), 0);
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn flush_freeze_keeps_readers_live_through_the_build_until_publish() {
        assert_flush_freeze_keeps_readers_live_then_finishes(false).await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn flush_prepublication_failure_rolls_back_without_poison() {
        assert_flush_freeze_keeps_readers_live_then_finishes(true).await;
    }

    #[tokio::test]
    async fn search_waits_for_active_publication_then_revalidates() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index("epoch-wait", text_schema()).unwrap();
        let idx = engine.get_index("epoch-wait").unwrap();
        idx.index_document(Some("one".into()), json!({"body": "alpha"}))
            .await
            .unwrap();

        let mut publication = idx.collection_publication.begin().unwrap();
        let request = xerj_query::parse_request(&json!({
            "query": {"match": {"body": "alpha"}},
            "size": 10,
            "timeout": "5s"
        }))
        .unwrap();
        let attempts_before = idx.collection_publication.reader_admission_attempts();
        let search_index = Arc::clone(&idx);
        let search = tokio::spawn(async move { search_index.search(&request).await });
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while idx.collection_publication.reader_admission_attempts() == attempts_before {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("search did not reach collection publication admission");
        assert!(
            !search.is_finished(),
            "reader crossed an active publication"
        );
        publication.cancel();
        drop(publication);
        let result = search.await.unwrap().unwrap();
        assert_eq!(result.hits.first().map(|hit| hit.id.as_str()), Some("one"));
    }

    /// A publication bracket held for the whole merge repoint used to pin
    /// `_search` until the bracket dropped, and the deadline used to come
    /// back as an error. A retrying client then spent the deadline again.
    /// The page must stop at `timeout` and say it is partial.
    #[tokio::test]
    async fn search_waiting_on_a_publication_stops_at_its_deadline() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("epoch-deadline", text_schema())
            .unwrap();
        let idx = engine.get_index("epoch-deadline").unwrap();
        idx.index_document(Some("one".into()), json!({"body": "alpha"}))
            .await
            .unwrap();

        let mut publication = idx.collection_publication.begin().unwrap();
        let request = xerj_query::parse_request(&json!({
            "query": {"match": {"body": "alpha"}},
            "size": 10,
            "timeout": "200ms"
        }))
        .unwrap();
        let started = std::time::Instant::now();
        let result = idx
            .search(&request)
            .await
            .expect("a missed deadline is a partial page, not an error");
        let elapsed = started.elapsed();
        publication.cancel();
        drop(publication);
        assert!(
            result.timed_out,
            "a bracket held past the deadline must set timed_out"
        );
        assert!(
            result.hits.is_empty(),
            "admission never captured a view: {:?}",
            result.hits
        );
        assert!(
            matches!(
                result.total.relation,
                xerj_query::executor::TotalHitsRelation::Gte
            ),
            "an uncaptured total is a lower bound, not zero"
        );
        assert!(
            elapsed < std::time::Duration::from_secs(2),
            "search must stop at its deadline, took {elapsed:?}"
        );
        // The bracket was cancelled, not dropped pending, so the index
        // still answers once the publication is gone.
        let again = idx
            .search(
                &xerj_query::parse_request(&json!({
                    "query": {"match": {"body": "alpha"}},
                    "size": 10
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        assert!(!again.timed_out);
        assert_eq!(again.hits.first().map(|hit| hit.id.as_str()), Some("one"));
    }

    // #1013 fail-before. Sustained ingest takes a publication bracket per
    // doc write, so writer-free *instants* exist but writer-free *intervals*
    // long enough to cover a whole search do not. The churn thread here
    // reproduces exactly that shape (hold a bracket 1 ms, leave a 2 ms gap,
    // repeat): the gap is far longer than the capture phase (probes +
    // snapshot + a 50-doc memtable walk) yet far shorter than the whole
    // search (a 5000-doc segment scan runs AFTER the capture bracket, inside
    // the search). Before the fix, end-of-search validation demanded the
    // whole search fit inside one gap and this test died at its deadline
    // ("search could not complete within one stable collection generation
    // before its deadline"); the capture-boundary check needs only the
    // instant, so the reader converges.
    #[tokio::test]
    async fn search_completes_under_publication_churn() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index("churn", text_schema()).unwrap();
        let idx = engine.get_index("churn").unwrap();

        // 5000 docs into a segment (the long, post-capture part of the
        // search), 50 into the memtable (inside the capture bracket).
        let docs: Vec<(Option<String>, Value)> = (0..5_000)
            .map(|i| (Some(format!("seg-{i}")), json!({"body": "alpha"})))
            .collect();
        for r in idx.index_documents_batched(docs).await {
            r.unwrap();
        }
        idx.flush().await.unwrap();
        let docs: Vec<(Option<String>, Value)> = (0..50)
            .map(|i| (Some(format!("mem-{i}")), json!({"body": "alpha"})))
            .collect();
        for r in idx.index_documents_batched(docs).await {
            r.unwrap();
        }

        let stop = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let churn_idx = std::sync::Arc::clone(&idx);
        let churn_stop = std::sync::Arc::clone(&stop);
        let churn = std::thread::spawn(move || {
            while !churn_stop.load(std::sync::atomic::Ordering::Relaxed) {
                let mut guard = churn_idx.collection_publication.begin().unwrap();
                std::thread::sleep(std::time::Duration::from_millis(1));
                // A synthetic bracket must be cancelled, never dropped
                // Pending — a Pending drop poisons the publication for good.
                guard.cancel();
                drop(guard);
                std::thread::sleep(std::time::Duration::from_millis(2));
            }
        });

        let request = xerj_query::parse_request(&json!({
            "query": {"match": {"body": "alpha"}},
            "size": 10,
            "timeout": "2s"
        }))
        .unwrap();
        let result = idx.search(&request).await;
        stop.store(true, std::sync::atomic::Ordering::Relaxed);
        churn.join().unwrap();

        let result = result.expect(
            "#1013: search must complete under publication churn — a reader \
             needs a writer-free instant to capture, not a writer-free \
             interval spanning the whole search",
        );
        assert_eq!(result.total.value, 5_050, "exact under churn");
    }

    /// #1761 — finalize-verify's catalog query shares `autoindex-catalog` with
    /// every other corpus build. Explicit-id catalog bulks publish one
    /// document at a time, each bracket covering WAL + memtable insert, and
    /// the next bracket opens immediately. A capture that clones the other
    /// run's buffered rows never fits in that gap, so the verify search waits
    /// out its deadline (`timed_out`, empty hits) and the phase sits at 0/N.
    ///
    /// This holds a tight `index_document` loop of another run's rows across
    /// the exact verify filter (`terms file_key` AND `term run_id`) and
    /// requires the search to return this run's count inside a short timeout.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn catalog_verify_search_completes_while_another_run_writes() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("file_key", FieldType::Keyword))
            .unwrap();
        schema
            .add_field(FieldConfig::new("run_id", FieldType::Keyword))
            .unwrap();
        engine.create_index("autoindex-catalog", schema).unwrap();
        let idx = engine.get_index("autoindex-catalog").unwrap();

        const THIS_RUN: usize = 24;
        const OTHER_RUN: usize = 2_000;
        let this_docs: Vec<(Option<String>, Value)> = (0..THIS_RUN)
            .map(|i| {
                (
                    Some(format!("this-{i}")),
                    json!({"file_key": format!("k{i}"), "run_id": "this-run"}),
                )
            })
            .collect();
        for r in idx.index_documents_batched(this_docs).await {
            r.unwrap();
        }
        idx.flush().await.unwrap();
        let other_docs: Vec<(Option<String>, Value)> = (0..OTHER_RUN)
            .map(|i| {
                (
                    Some(format!("other-{i}")),
                    json!({"file_key": format!("o{i}"), "run_id": "other-run"}),
                )
            })
            .collect();
        for r in idx.index_documents_batched(other_docs).await {
            r.unwrap();
        }

        let stop = Arc::new(AtomicBool::new(false));
        let wrote = Arc::new(AtomicU64::new(0));
        let writer_idx = Arc::clone(&idx);
        let writer_stop = Arc::clone(&stop);
        let writer_wrote = Arc::clone(&wrote);
        let writer = tokio::spawn(async move {
            let mut n: u64 = 0;
            while !writer_stop.load(Ordering::Relaxed) {
                writer_idx
                    .index_document(
                        Some(format!("other-{}", n % OTHER_RUN as u64)),
                        json!({
                            "file_key": format!("o{}", n % OTHER_RUN as u64),
                            "run_id": "other-run"
                        }),
                    )
                    .await
                    .expect("concurrent catalog write");
                writer_wrote.fetch_add(1, Ordering::Relaxed);
                n += 1;
            }
        });
        tokio::time::timeout(std::time::Duration::from_secs(30), async {
            while wrote.load(Ordering::Relaxed) < 8 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("the other run never published a document");

        let keys: Vec<String> = (0..THIS_RUN).map(|i| format!("k{i}")).collect();
        let request = xerj_query::parse_request(&json!({
            "query": {"bool": {"filter": [
                {"terms": {"file_key": keys}},
                {"term": {"run_id": "this-run"}}
            ]}},
            "size": THIS_RUN,
            "track_total_hits": true,
            "_source": ["file_key"],
            "timeout": "2s"
        }))
        .unwrap();
        let started = std::time::Instant::now();
        let result = idx.search(&request).await.expect("verify search");
        let elapsed = started.elapsed();
        let buffered = idx.memtable.doc_count();
        stop.store(true, Ordering::Relaxed);
        tokio::time::timeout(std::time::Duration::from_secs(30), writer)
            .await
            .expect("writer did not stop")
            .unwrap();

        assert!(
            !result.timed_out,
            "finalize-verify catalog search timed out under a concurrent writer \
             in {elapsed:?}: total={} hits={}",
            result.total.value,
            result.hits.len()
        );
        assert_eq!(
            result.total.value, THIS_RUN as u64,
            "the run_id filter must not count the other run's rows"
        );
        assert_eq!(
            result.hits.len(),
            THIS_RUN,
            "the page must carry every match"
        );
        assert!(
            buffered > THIS_RUN,
            "the other run's rows must still be memtable-resident (buffered {buffered}); \
             a flush would hide the publication stall this test exists for"
        );
        assert!(
            elapsed < std::time::Duration::from_secs(2),
            "the search must finish inside its timeout, took {elapsed:?}"
        );
        assert!(
            result.hits.iter().all(|hit| hit.id.starts_with("this-")),
            "a hit from the other run leaked into the page: {:?}",
            result.hits.iter().map(|hit| &hit.id).collect::<Vec<_>>()
        );
    }

