    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn legacy_index_backfills_date_precision_from_es_mapping() {
        // #889 part 2. `date_precision` is written when a field is MAPPED, so
        // an index created by a build older than #790 comes back with no
        // precision at all and every date field falls back to the per-value
        // guess — the #790 defect, still live, on exactly the data dirs that
        // already exist. The raw ES mapping blob beside `schema.json` still
        // says `date` or `date_nanos`, so the flag is recoverable at open.
        //
        // Both directions are checked: a legacy `date_nanos` must come back
        // nanosecond-scaled (a blanket default would silently downgrade it to
        // milliseconds), and a legacy `date` must come back millisecond-scaled
        // (i.e. it inherits the #790 fix instead of waiting for a reindex).
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config.clone()).unwrap();

        // Same two documents in both indices: `sub` is the EARLIER instant, so
        // the per-value guess (which scales them differently) reverses them.
        let docs = [
            ("sub", "2020-06-06T06:06:06.123456Z"),
            ("late", "2025-01-01T00:00:00Z"),
        ];
        let mut index_dirs = Vec::new();
        for (name, es_type, precision) in [
            (
                "legacy-ns",
                "date_nanos",
                xerj_common::types::DatePrecision::Nanos,
            ),
            (
                "legacy-ms",
                "date",
                xerj_common::types::DatePrecision::Millis,
            ),
        ] {
            let idx = date_index(&engine, name, Some(precision), &docs).await;
            engine
                .put_index_mapping(name, json!({"properties": {"ts": {"type": es_type}}}))
                .unwrap();
            idx.flush().await.unwrap();
            assert!(idx.data_dir.join("es_mapping.json").is_file());
            index_dirs.push(idx.data_dir.clone());
            drop(idx);
        }
        drop(engine);
        // Age the schemas only once the engine that owns them is gone, so
        // nothing rewrites `schema.json` behind the fixture on shutdown.
        for dir in &index_dirs {
            strip_date_precision(dir);
        }

        let restarted = crate::Engine::new(config).unwrap();
        for (name, expected) in [
            (
                "legacy-ns",
                vec![json!(1591423566123456000i64), json!(1735689600000000000i64)],
            ),
            (
                "legacy-ms",
                vec![json!(1591423566123i64), json!(1735689600000i64)],
            ),
        ] {
            let idx = restarted.get_index(name).unwrap();
            idx.abort_background_tasks();
            let req = xerj_query::parse_request(
                &json!({"query": {"match_all": {}}, "size": 10, "sort": [{"ts": "asc"}]}),
            )
            .unwrap();
            let hits = idx.search(&req).await.unwrap().hits;
            let got: Vec<(String, Vec<serde_json::Value>)> = hits
                .iter()
                .map(|h| (h.id.clone(), h.sort.clone()))
                .collect();
            assert_eq!(
                got,
                vec![
                    ("sub".to_string(), vec![expected[0].clone()]),
                    ("late".to_string(), vec![expected[1].clone()]),
                ],
                "#889 {name}: an index whose schema.json predates date_precision must \
                 recover its scale from es_mapping.json, not guess it per value"
            );
        }
    }

    #[test]
    fn backfill_only_fills_what_the_mapping_actually_says() {
        // The back-fill is a pure widening: it never overwrites a precision the
        // current build already recorded, and it never invents one for a field
        // the ES mapping does not describe as a date — leaving those on the
        // legacy guess is the whole reason a blanket default was rejected.
        use xerj_common::types::DatePrecision;
        let mut fields = vec![
            FieldConfig::new("declared_ms", FieldType::Date),
            {
                let mut f = FieldConfig::new("legacy_ns", FieldType::Date);
                f.options.date_precision = None;
                f
            },
            {
                let mut f = FieldConfig::new("legacy_ms", FieldType::Date);
                f.options.date_precision = None;
                f
            },
            {
                let mut f = FieldConfig::new("unmentioned", FieldType::Date);
                f.options.date_precision = None;
                f
            },
            {
                let mut f = FieldConfig::new("not_a_date_in_mapping", FieldType::Date);
                f.options.date_precision = None;
                f
            },
            {
                let mut parent = FieldConfig::new("obj", FieldType::Object);
                let mut child = FieldConfig::new("when", FieldType::Date);
                child.options.date_precision = None;
                parent.fields = vec![child];
                parent
            },
        ];
        // `declared_ms` is mapped `date_nanos` here on purpose: the current
        // build already classified it, so the back-fill must not touch it.
        let props = json!({
            "declared_ms": {"type": "date_nanos"},
            "legacy_ns": {"type": "date_nanos"},
            "legacy_ms": {"type": "date"},
            "not_a_date_in_mapping": {"type": "keyword"},
            "obj": {"properties": {"when": {"type": "date_nanos"}}}
        });
        assert_eq!(backfill_date_precision(&mut fields, &props), 3);
        let by_name = |n: &str| {
            fields
                .iter()
                .find(|f| f.name == n)
                .unwrap()
                .options
                .date_precision
        };
        assert_eq!(by_name("declared_ms"), Some(DatePrecision::Millis));
        assert_eq!(by_name("legacy_ns"), Some(DatePrecision::Nanos));
        assert_eq!(by_name("legacy_ms"), Some(DatePrecision::Millis));
        assert_eq!(by_name("unmentioned"), None);
        assert_eq!(by_name("not_a_date_in_mapping"), None);
        assert_eq!(
            fields.iter().find(|f| f.name == "obj").unwrap().fields[0]
                .options
                .date_precision,
            Some(DatePrecision::Nanos)
        );
        // Idempotent: a second pass classifies nothing new.
        assert_eq!(backfill_date_precision(&mut fields, &props), 0);
    }

    #[test]
    fn date_scale_follows_the_declared_mapping() {
        // The whole point of #790: the scale is a property of the FIELD.
        use xerj_common::types::DatePrecision;
        let mut schema = Schema::empty();
        // The native API means ES `date` — `FieldConfig::new` pins it.
        schema
            .add_field(FieldConfig::new("plain", FieldType::Date))
            .unwrap();
        let mut ns = FieldConfig::new("ns", FieldType::Date);
        ns.options.date_precision = Some(DatePrecision::Nanos);
        schema.add_field(ns).unwrap();
        // A mapping written before the flag existed: no silent change of scale.
        let mut legacy = FieldConfig::new("legacy", FieldType::Date);
        legacy.options.date_precision = None;
        schema.add_field(legacy).unwrap();
        schema
            .add_field(FieldConfig::new("word", FieldType::Keyword))
            .unwrap();
        let scale = |name: &str| {
            declared_field(&schema, name)
                .map(date_scale_of_config)
                .unwrap_or(DateScale::PerValue)
        };
        assert_eq!(scale("plain"), DateScale::Millis);
        // #889: a DECLARED `date_nanos` is uniformly nanosecond-scaled — it no
        // longer re-derives its scale from each value.
        assert_eq!(scale("ns"), DateScale::Nanos);
        assert_eq!(scale("legacy"), DateScale::PerValue);
        assert_eq!(scale("word"), DateScale::PerValue);
        assert_eq!(scale("undeclared"), DateScale::PerValue);
        assert_eq!(
            date_field_scales(&schema),
            [
                ("plain".to_string(), DateScale::Millis),
                ("ns".to_string(), DateScale::Nanos),
            ]
            .into_iter()
            .collect()
        );
        // A millisecond field truncates sub-millisecond digits; the per-value
        // scale keeps them, which is the whole ms-vs-ns split.
        let sub = "2020-06-06T06:06:06.123456Z";
        assert_eq!(
            date_string_to_epoch(sub, DateScale::Millis),
            Some(json!(1591423566123i64))
        );
        assert_eq!(
            date_string_to_epoch(sub, DateScale::PerValue),
            Some(json!(1591423566123456000i64))
        );
        assert_eq!(
            date_string_to_epoch(sub, DateScale::Nanos),
            Some(json!(1591423566123456000i64))
        );
        // #889, the defect itself: a WHOLE-SECOND value in a `date_nanos`
        // column. The per-value guess called it milliseconds — six orders of
        // magnitude below the same column's sub-millisecond keys, so it sorted
        // as if it were 1970. `Nanos` puts it on the column's one scale.
        let whole = "2020-06-06T06:06:06Z";
        assert_eq!(
            date_string_to_epoch(whole, DateScale::PerValue),
            Some(json!(1591423566000i64))
        );
        assert_eq!(
            date_string_to_epoch(whole, DateScale::Nanos),
            Some(json!(1591423566000000000i64))
        );
        // Same for the slash-date shape, which had no nanosecond branch at all.
        assert_eq!(
            sort_date_normalize("06/06/2020 06:06:06.123", DateScale::PerValue),
            Some(json!(1591423566123i64))
        );
        assert_eq!(
            sort_date_normalize("06/06/2020 06:06:06.123", DateScale::Nanos),
            Some(json!(1591423566123000000i64))
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn date_term_normalizes_formats_and_epoch_ms_across_flush() {
        // #788: a `term` on a date field must match by instant, not by raw
        // stored representation. "2020-01-01", "2020-01-01T00:00:00Z", and the
        // epoch-ms number 1577836800000 all name the same instant as doc `a`,
        // so all three must return [a] — before AND after flush (the segment
        // path must agree with the memtable source scan; no new divergence).
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("ts", FieldType::Date))
            .unwrap();
        engine.create_index("date-term", schema).unwrap();
        let idx = engine.get_index("date-term").unwrap();
        idx.abort_background_tasks();
        for (id, ts) in [
            ("a", "2020-01-01T00:00:00Z"),
            ("b", "2021-06-15T00:00:00Z"),
            ("c", "2022-12-31T00:00:00Z"),
            // Sub-millisecond precision (>=4 fractional digits): the sort-shadow
            // stores this in nanoseconds, so a ms-scale range would miss it.
            ("d", "2020-03-03T03:03:03.123456Z"),
        ] {
            idx.index_document(Some(id.into()), json!({ "ts": ts }))
                .await
                .unwrap();
        }
        let run = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&json!({
                "query": body, "size": 10, "track_total_hits": true
            }))
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        let shapes: Vec<serde_json::Value> = vec![
            json!({"term": {"ts": "2020-01-01T00:00:00Z"}}),
            json!({"term": {"ts": "2020-01-01"}}),
            json!({"term": {"ts": 1577836800000i64}}),
        ];
        let count0 = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&json!({
                "query": body, "size": 0, "track_total_hits": true
            }))
            .unwrap();
            idx.search(&req).await.unwrap().total.value
        };
        let want = (1u64, vec!["a".to_string()]);
        // A sub-millisecond term must still match its own exact stored value
        // after flush (#789: the ms-scale range rewrite lost these to the
        // nanosecond sort-shadow — the rewrite must be skipped for such values).
        let subms = json!({"term": {"ts": "2020-03-03T03:03:03.123456Z"}});
        let want_d = (1u64, vec!["d".to_string()]);
        for phase in ["pre-flush", "post-flush"] {
            for body in &shapes {
                let got = run(idx.clone(), body.clone()).await;
                assert_eq!(got, want, "#788 {phase} {body} must match doc a by instant");
                // size:0 count fast path must agree with the hit scan.
                let c = count0(idx.clone(), body.clone()).await;
                assert_eq!(c, 1, "#788 {phase} {body} size:0 count must be 1");
            }
            let got_d = run(idx.clone(), subms.clone()).await;
            assert_eq!(
                got_d, want_d,
                "#789 {phase} exact sub-ms term must match doc d"
            );
            let c_d = count0(idx.clone(), subms.clone()).await;
            assert_eq!(
                c_d, 1,
                "#789 {phase} exact sub-ms term size:0 count must be 1"
            );
            if phase == "pre-flush" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn date_nanos_term_and_epoch_millis_bound_survive_flush() {
        // #889 regression. Pinning `date_nanos` to `DateScale::Nanos` moved the
        // segment sort-shadow's keys to epoch-NANOSECONDS, but the bound
        // derivation that feeds the shadow (`shadow_range_bounds`, used by the
        // range dv pre-filter and by the `try_shortcut_count` Range arm) still
        // took a NUMERIC bound verbatim as epoch-milliseconds. Six orders of
        // magnitude apart, the bisect matched nothing, so the pre-filter came
        // back `Some(empty)` — which the scan loop treats as PROOF that no doc
        // in the segment can contribute a hit or a count — and the segment was
        // skipped whole.
        //
        // Two shapes reach that code with a numeric bound:
        //   * the #788 `term`-on-a-date rewrite, which turns a `term` into the
        //     degenerate `range [epoch_ms, epoch_ms]` from `parse_date_ms`, and
        //   * a user-supplied numeric bound, which ES reads as epoch-MILLIS on
        //     a `date_nanos` field too (its default format is
        //     `strict_date_optional_time_nanos||epoch_millis`) — so the
        //     conversion belongs at the BOUND, not at the value.
        //
        // Both answered correctly PRE-flush (the memtable compares ms-to-ms via
        // `parse_date_ms` on both sides) and returned 0 hits POST-flush, which
        // is the flush-invariance break this pins shut.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let idx = date_index(
            &engine,
            "date-ns-term",
            Some(xerj_common::types::DatePrecision::Nanos),
            &[
                ("sub", "2020-06-06T06:06:06.123456Z"),
                ("late", "2025-01-01T00:00:00Z"),
            ],
        )
        .await;
        let run = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&json!({
                "query": body, "size": 10, "track_total_hits": true
            }))
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        let count0 = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&json!({
                "query": body, "size": 0, "track_total_hits": true
            }))
            .unwrap();
            idx.search(&req).await.unwrap().total.value
        };
        // `late` is 1735689600000 ms = 1735689600000000000 ns;
        // `sub`  is 1591423566123 ms = 1591423566123456000 ns.
        let cases: Vec<(serde_json::Value, u64, Vec<&str>)> = vec![
            // The #788 term rewrite, on the whole-second value the old
            // per-value guess used to key in milliseconds.
            (
                json!({"term": {"ts": "2025-01-01T00:00:00Z"}}),
                1,
                vec!["late"],
            ),
            // The same instant spelled as a bare date and as epoch-millis.
            (json!({"term": {"ts": "2025-01-01"}}), 1, vec!["late"]),
            (json!({"term": {"ts": 1735689600000i64}}), 1, vec!["late"]),
            // A user-supplied numeric bound is epoch-MILLIS on `date_nanos`.
            (
                json!({"range": {"ts": {"gte": 1735689600000i64}}}),
                1,
                vec!["late"],
            ),
            // …and it must still DISCRIMINATE, not merely match everything:
            // this window opens 456µs before `sub` and closes on `late`.
            (
                json!({"range": {"ts": {"gte": 1591423566123i64, "lte": 1735689600000i64}}}),
                2,
                vec!["late", "sub"],
            ),
            // A window that closes before `late` excludes it.
            (
                json!({"range": {"ts": {"lt": 1735689600000i64}}}),
                1,
                vec!["sub"],
            ),
            // The equivalent STRING bound already agreed with the shadow;
            // pinned here so the numeric fix cannot drift away from it.
            (
                json!({"range": {"ts": {"gte": "2025-01-01T00:00:00Z"}}}),
                1,
                vec!["late"],
            ),
        ];
        for phase in ["pre-flush", "post-flush"] {
            for (body, total, ids) in &cases {
                let want = (
                    *total,
                    ids.iter().map(|s| (*s).to_string()).collect::<Vec<_>>(),
                );
                assert_eq!(
                    run(idx.clone(), body.clone()).await,
                    want,
                    "#889 {phase}: {body} on a date_nanos field"
                );
                assert_eq!(
                    count0(idx.clone(), body.clone()).await,
                    *total,
                    "#889 {phase}: {body} size:0 count must agree with the hit scan"
                );
            }
            if phase == "pre-flush" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
                assert!(!idx.store.snapshot().segments.is_empty());
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn date_only_value_on_the_nanosecond_scale_is_still_an_epoch() {
        // #889 regression. `date_string_to_epoch`'s nanosecond branch tried
        // only RFC3339 and `%Y-%m-%dT%H:%M:%S%.f`; the `%Y-%m-%d` NaiveDate
        // fallback existed solely in the millisecond branch. `looks_like_date`
        // accepts "2021-01-01", so a date-only value in a `date_nanos` field
        // routed into the nanosecond branch and came back `None` — and
        // `compute_sort_values` does `.unwrap_or(raw)`, so the hit's `sort`
        // value became the JSON STRING "2021-01-01" sitting among i64 epochs.
        // `compare_values` then falls to its string arm, where '"' (0x22) sorts
        // below every digit, so the doc came FIRST ascending whatever its
        // instant. `build_sort_shadow` also `?`s out on that term, silently
        // disabling the segment prefilter for the whole field.
        //
        // Both scales now share ONE ladder of accepted formats, so a format
        // either parses on both or on neither.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let idx = date_index(
            &engine,
            "date-ns-dateonly",
            Some(xerj_common::types::DatePrecision::Nanos),
            &[
                ("day", "2021-01-01"),
                ("sub", "2020-06-06T06:06:06.123456Z"),
            ],
        )
        .await;
        let sort_values = |idx: std::sync::Arc<crate::Index>, nt: Option<&'static str>| async move {
            let sort = match nt {
                Some(t) => json!([{"ts": {"order": "asc", "numeric_type": t}}]),
                None => json!([{"ts": "asc"}]),
            };
            let req = xerj_query::parse_request(
                &json!({"query": {"match_all": {}}, "size": 10, "sort": sort}),
            )
            .unwrap();
            idx.search(&req)
                .await
                .unwrap()
                .hits
                .iter()
                .map(|h| (h.id.clone(), h.sort.clone()))
                .collect::<Vec<_>>()
        };
        let range_ids = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(
                &json!({"query": body, "size": 10, "track_total_hits": true}),
            )
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        for phase in ["pre-flush", "post-flush"] {
            assert_eq!(
                sort_values(idx.clone(), None).await,
                vec![
                    ("sub".to_string(), vec![json!(1591423566123456000i64)]),
                    ("day".to_string(), vec![json!(1609459200000000000i64)]),
                ],
                "#889 {phase}: a date-only value in a date_nanos field is an \
                 epoch-nanosecond number, not the raw string"
            );
            // The instant, not the lexicographic accident: 2021 is LATER.
            assert_eq!(
                sort_ids(&idx, "asc").await,
                vec!["sub".to_string(), "day".to_string()],
                "#889 {phase}: asc must order by instant"
            );
            assert_eq!(
                range_ids(idx.clone(), json!({"range": {"ts": {"gte": "2021-01-01"}}})).await,
                (1u64, vec!["day".to_string()]),
                "#889 {phase}: gte 2021-01-01 keeps only day"
            );
            if phase == "pre-flush" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }

        // The same hole on this change's own headline feature: `numeric_type`
        // forces `DateScale::Nanos` on EVERY participating index, so an
        // ordinary `date` field holding a date-only value went down the very
        // same branch and returned a raw string under a cross-index sort.
        let ms = date_index(
            &engine,
            "date-ms-dateonly",
            Some(xerj_common::types::DatePrecision::Millis),
            &[
                ("day", "2021-01-01"),
                ("sub", "2020-06-06T06:06:06.123456Z"),
            ],
        )
        .await;
        for phase in ["pre-flush", "post-flush"] {
            assert_eq!(
                sort_values(ms.clone(), Some("date_nanos")).await,
                vec![
                    ("sub".to_string(), vec![json!(1591423566123456000i64)]),
                    ("day".to_string(), vec![json!(1609459200000000000i64)]),
                ],
                "#889 {phase}: numeric_type date_nanos re-scales a date-only \
                 value on a `date` field instead of emitting the raw string"
            );
            if phase == "pre-flush" {
                ms.flush().await.unwrap();
                assert_eq!(ms.memtable.doc_count(), 0);
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn flush_increments_the_bytes_written_metric() {
        // #804: `xerj_bytes_written_total` was registered but nothing ever
        // incremented it, so it stayed 0 regardless of write volume. The
        // handle is a process-wide `OnceLock` (set-once) and MORE THAN ONE
        // test installs one (`bytes_written_metric_increments_on_flush`), so
        // whichever runs first wins the race and a locally-constructed
        // `Metrics` may never be the one `engine_metrics()` (and thus flush)
        // increments — reading it gave a flat 0 under high-core parallelism.
        // Read the INSTALLED handle instead, and assert `after > before`
        // rather than an exact delta since concurrent flushes share it.
        crate::set_engine_metrics(std::sync::Arc::new(
            xerj_common::metrics::Metrics::new().unwrap(),
        ));
        let metrics = crate::engine_metrics().expect("engine metrics installed");
        let before = metrics.bytes_written.get();

        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("bytes-written", Schema::empty())
            .unwrap();
        let idx = engine.get_index("bytes-written").unwrap();
        idx.abort_background_tasks();
        idx.index_document(Some("a".into()), json!({ "f": "x" }))
            .await
            .unwrap();
        idx.flush().await.unwrap();

        let after = metrics.bytes_written.get();
