/// Clears an index's `merge_in_progress` flag on every exit path of the
/// merge holder (background pass or forcemerge), including panics.
struct MergeFlagClear<'a>(&'a std::sync::atomic::AtomicBool);
impl<'a> Drop for MergeFlagClear<'a> {
    fn drop(&mut self) {
        self.0.store(false, std::sync::atomic::Ordering::Release);
    }
}

#[cfg(test)]
mod merge_publication_transaction_tests {
    use super::*;
    use crate::Engine;
    use tempfile::TempDir;

    /// Wait for a publication test barrier, bounded.
    ///
    /// These barriers block a tokio worker thread on purpose, and an unbounded
    /// `recv()` turns "the code never reached this point" into a hang. On CI
    /// that surfaced as a job cancelled at the six-hour ceiling with nothing in
    /// the log but "has been running for over 60 seconds". Bounded, the same
    /// bug is a ten-second failure naming the point it waited for.
    #[track_caller]
    fn await_barrier<T>(rx: &std::sync::mpsc::Receiver<T>, what: &str) -> T {
        match rx.recv_timeout(std::time::Duration::from_secs(20)) {
            Ok(v) => v,
            Err(e) => panic!("publication barrier `{what}` never fired ({e:?})"),
        }
    }

    fn config(dir: &TempDir) -> xerj_common::config::Config {
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.merge.min_segments = 2;
        config.merge.min_merge_count = 2;
        config.merge.max_merge_count = 2;
        config
    }

    /// Open an engine plus one index with background merge scheduling already
    /// stopped, for a test that drives every merge itself.
    ///
    /// `Index::create` and `Index::open` wire the store's segments-changed
    /// hook (#871), so every flush a test performs arms a debounced
    /// background merge check — and with this module's
    /// `min_merge_count = max_merge_count = 2` one check rewrites the
    /// segment set two segments at a time.  Every test here calls
    /// `run_merge_once()` by hand, so that background pass is pure
    /// interference with two
    /// distinct failure shapes: it can win the `merge_in_progress` CAS and turn
    /// the test's own `run_merge_once()` into `Ok(0)` (the flake `fixture`
    /// already guarded against), and it can collapse fixture segments before the
    /// test has even looked at them — issue #372, where
    /// `partial_multi_batch_failure_is_reported_without_losing_either_batch`
    /// built its index inline, never stopped the loop, and failed its
    /// *precondition* with `left: 3, right: 4` once a full-parallelism run
    /// stretched the body past one tick.  Constructing every index in this
    /// module here — including the one fixture that needs a custom `Config`,
    /// through `hand_driven_index_with_config` — means the omission cannot be
    /// reintroduced one test at a time.
    fn hand_driven_index(dir: &TempDir, name: &str, schema: Schema) -> (Engine, Arc<Index>) {
        hand_driven_index_with_config(config(dir), name, schema)
    }

    /// #873: an index that is not being written to holds NO WAL file
    /// descriptors and no WAL write buffers, whatever its ingest-shard count.
    ///
    /// The two states that matter are the ones a quiet node is actually in:
    /// freshly opened, and freshly flushed. Both are covered here, either side
    /// of a write that proves the descriptors do appear when they are needed.
    /// Pre-fix every shard opened a file and a 64 KiB buffer at
    /// `IndexStore::open` and kept both for the process lifetime — 8 of them
    /// on a 16-core laptop, 16 here, multiplied by every open index, which is
    /// what made a few hundred idle autoindex datasets expensive.
    #[tokio::test]
    async fn an_index_that_is_not_being_written_to_holds_no_wal_descriptors() {
        let dir = TempDir::new().unwrap();
        let mut cfg = config(&dir);
        // Pin well above 1: the default is a fraction of the host core count,
        // so on a 1- or 2-core runner this test would assert nothing.
        cfg.engine.ingest_shards = 8;
        let (_engine, index) = hand_driven_index_with_config(cfg, "idle-wal", Schema::empty());
        assert_eq!(
            index.store.wal_shard_count(),
            8,
            "fixture must actually open 8 shards"
        );
        assert_eq!(
            index.store.materialized_wal_shards(),
            0,
            "a freshly opened index must hold no WAL descriptors"
        );

        // Enough documents to spread across shards (routing is
        // `xxh3(doc_id) & (shards - 1)`), so this is not a one-shard result.
        for i in 0..64 {
            index
                .index_document(Some(format!("d{i}")), serde_json::json!({"m": i}))
                .await
                .unwrap();
        }
        assert!(
            index.store.materialized_wal_shards() > 1,
            "writes must materialize the shards they route to (got {})",
            index.store.materialized_wal_shards()
        );

        // The flush path (`force_wal_maintenance` → `force_rotate` per shard)
        // freezes every written generation and leaves an empty one active.
        index.flush().await.unwrap();
        assert_eq!(
            index.store.materialized_wal_shards(),
            0,
            "a flushed index must hand every WAL descriptor and buffer back"
        );

        // And the data is still there, through the memtable drain and the
        // released descriptors.
        let hits = index
            .search(
                &xerj_query::parse_request(&serde_json::json!({
                    "query": {"match_all": {}}, "size": 0
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(hits.total.value, 64);
    }

    /// #873: a non-empty memtable BELOW the size thresholds flushes once its
    /// contents have sat unchanged for `flush_idle_secs`. Idleness is
    /// crossed via the test rewind hook, never a sleep. Also proves the two
    /// negative arms: a fingerprint change re-arms the timer, and
    /// `flush_idle_secs = 0` disables the path entirely.
    #[tokio::test]
    async fn small_idle_memtable_flushes_by_age_not_size() {
        let dir = TempDir::new().unwrap();
        let mut cfg = config(&dir);
        cfg.storage.flush_idle_secs = 5;
        let (_engine, index) = hand_driven_index_with_config(cfg, "idle-age", Schema::empty());
        index
            .index_document(Some("d1".into()), serde_json::json!({"m": "tiny"}))
            .await
            .unwrap();
        // Probe 1 records the fingerprint; probe 2 is unchanged but unaged.
        assert!(!index.needs_flush().await, "first probe must only arm");
        assert!(
            !index.needs_flush().await,
            "unaged idle memtable must not flush"
        );
        // Cross the idle threshold without sleeping.
        index.rewind_idle_probe_for_test(6_000);
        assert!(index.needs_flush().await, "aged idle memtable must flush");
        // A write re-arms: fingerprint changes, timer restarts.
        index
            .index_document(Some("d2".into()), serde_json::json!({"m": "tiny2"}))
            .await
            .unwrap();
        assert!(
            !index.needs_flush().await,
            "activity must re-arm the idle timer"
        );
        index.rewind_idle_probe_for_test(6_000);
        assert!(index.needs_flush().await);
        // The flush the periodic sweeper would now run empties the memtable.
        index.flush().await.unwrap();
        assert_eq!(index.memtable_bytes(), 0, "flush must drain the memtable");
        assert!(
            !index.needs_flush().await,
            "empty memtable never idle-flushes"
        );

        // The reviewer's trace on PR #878, reproduced exactly. It needs its
        // OWN index: the collision requires the post-flush memtable to
        // reproduce the SAME (doc_count, bytes) pair the pre-flush one had,
        // which cannot happen above where the memtable held two docs at
        // flush time. One doc in, aged, flushed; then one identically-shaped
        // doc — the ordinary uniform-trickle workload (heartbeats,
        // fixed-shape audit records, a periodic re-sync of the same batch).
        let dir3 = TempDir::new().unwrap();
        let mut cfg3 = config(&dir3);
        cfg3.storage.flush_idle_secs = 5;
        let (_e3, idx3) = hand_driven_index_with_config(cfg3, "idle-recur", Schema::empty());
        idx3.index_document(Some("aa".into()), serde_json::json!({"m": "tiny"}))
            .await
            .unwrap();
        assert!(!idx3.needs_flush().await, "arm");
        idx3.rewind_idle_probe_for_test(6_000);
        assert!(idx3.needs_flush().await, "ages and flushes once");
        idx3.flush().await.unwrap();
        assert_eq!(idx3.memtable_bytes(), 0);
        // Same doc id, same body => same (doc_count, bytes) as before the
        // flush. Without the drained-arm reset this matches the STALE
        // fingerprint, skips the re-arm, and is compared against the
        // pre-flush stamp that is already older than flush_idle_secs — so
        // needs_flush returns true immediately and would do so on every
        // probe forever, a flush every flush_interval_secs on an idle node.
        idx3.index_document(Some("aa".into()), serde_json::json!({"m": "tiny"}))
            .await
            .unwrap();
        assert!(
            !idx3.needs_flush().await,
            "a recurring fingerprint after a flush must arm a FRESH timer, not \
             inherit the pre-flush stamp and flush on the very next probe"
        );
        idx3.rewind_idle_probe_for_test(6_000);
        assert!(
            idx3.needs_flush().await,
            "and then ages normally from that fresh stamp"
        );

        // Disabled: 0 means the old threshold-only behaviour.
        let dir2 = TempDir::new().unwrap();
        let mut cfg2 = config(&dir2);
        cfg2.storage.flush_idle_secs = 0;
        let (_e2, idx2) = hand_driven_index_with_config(cfg2, "idle-off", Schema::empty());
        idx2.index_document(Some("d1".into()), serde_json::json!({"m": "tiny"}))
            .await
            .unwrap();
        assert!(!idx2.needs_flush().await);
        idx2.rewind_idle_probe_for_test(600_000);
        assert!(
            !idx2.needs_flush().await,
            "flush_idle_secs=0 must disable idle flush"
        );
    }

    /// `hand_driven_index` for the fixture that needs a knob `config()` does
    /// not set.
    ///
    /// Only `artifact_bytes_at_level` uses this: it varies
    /// `compression.level` and pins `ingest_shards = 1`.  It exists so that
    /// site does not have to remember `abort_background_tasks()` on its own —
    /// it is the one index in this module that was still being built by hand.
    fn hand_driven_index_with_config(
        cfg: xerj_common::config::Config,
        name: &str,
        schema: Schema,
    ) -> (Engine, Arc<Index>) {
        let engine = Engine::new(cfg).unwrap();
        engine.create_index(name, schema).unwrap();
        let index = engine.get_index(name).unwrap();
        index.abort_background_tasks();
        (engine, index)
    }

    /// Reopen `name` from `dir` with background merge scheduling already
    /// stopped.
    ///
    /// Same contract as `hand_driven_index`: the restart half of these tests
    /// asserts on a recovered segment set, and `Index::open` schedules its
    /// own open-time merge check too (`request_merge_check`, #871 — an
    /// opened index may carry pre-existing merge debt).
    fn reopen_hand_driven(dir: &TempDir, name: &str) -> (Engine, Arc<Index>) {
        let engine = Engine::new(config(dir)).unwrap();
        let index = engine.get_index(name).unwrap();
        index.abort_background_tasks();
        (engine, index)
    }

    fn dot_field_schema() -> Schema {
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new(".", FieldType::Text))
            .unwrap();
        schema
