    #[tokio::test]
    async fn explicit_add_fields_enforces_max_fields_per_index() {
        // #76 S5-5: the explicit mapping path (`add_fields` / PUT _mapping /
        // schema evolve) must enforce `max_fields_per_index` too. The dynamic
        // ingest path did, but `Index::add_fields` previously bypassed the cap,
        // so an authenticated caller could bloat the schema unbounded by sending
        // fields explicitly.
        let dir = TempDir::new().unwrap();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.limits.max_fields_per_index = 50;
        let engine_instance = Engine::new(config).expect("engine");
        engine_instance
            .create_index("field-cap", Schema::empty())
            .unwrap();
        let index = engine_instance.get_index("field-cap").unwrap();

        // Fill exactly to the cap (robust to whatever base fields exist).
        let base = index.schema().await.field_count() as u32;
        let fill: Vec<FieldConfig> = (0..(50 - base))
            .map(|i| FieldConfig::new(format!("f{i}"), FieldType::Keyword))
            .collect();
        index
            .add_fields(fill)
            .await
            .expect("filling exactly to the cap must succeed");

        // One field over the cap via the explicit path must be REFUSED.
        let err = index
            .add_fields(vec![FieldConfig::new("overflow", FieldType::Keyword)])
            .await
            .expect_err("exceeding max_fields_per_index on the explicit path must be rejected");
        assert!(
            err.to_string().contains("Limit of total fields"),
            "unexpected error: {err}"
        );
    }

    /// `index.max_result_window` above 10,000 was stored and then overruled by
    /// the parser's hardcoded 10,000 (measured on rc.89: `from: 20000` on an
    /// index set to 50,000 answered "from + size must be <= 10000"), and the
    /// node's `limits.max_result_window` was read by nothing. The index
    /// setting now governs, the node setting is the fallback, and the check
    /// still refuses a window past either.
    #[tokio::test]
    async fn result_window_comes_from_the_index_setting_then_the_node_limit() {
        let window = |from: u64, size: u64| {
            xerj_query::parse_request(&serde_json::json!({ "from": from, "size": size }))
                .expect("the parser no longer caps the window at 10,000")
        };
        let dir = TempDir::new().unwrap();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.limits.max_result_window = 50;
        let engine_instance = Engine::new(config).expect("engine");
        engine_instance
            .create_index("node-limit", Schema::empty())
            .unwrap();
        engine_instance
            .create_index("index-limit", Schema::empty())
            .unwrap();

        // No index setting: the node limit (50) applies.
        let node = engine_instance.get_index("node-limit").unwrap();
        node.search(&window(40, 10))
            .await
            .expect("40 + 10 fits a window of 50");
        let err = node
            .search(&window(45, 10))
            .await
            .expect_err("45 + 10 exceeds the node's window of 50");
        assert!(err.to_string().contains("max_result_window=50"), "{err}");

        // An index setting wins over the node limit, in both directions, and
        // above the old hardcoded 10,000.
        let idx = engine_instance.get_index("index-limit").unwrap();
        idx.put_settings(serde_json::json!({ "index": { "max_result_window": 50_000 } }))
            .await
            .unwrap();
        idx.search(&window(20_000, 10))
            .await
            .expect("a 50,000 index window admits from 20,000");
        let err = idx
            .search(&window(49_995, 10))
            .await
            .expect_err("49,995 + 10 exceeds the index's window of 50,000");
        assert!(err.to_string().contains("max_result_window=50000"), "{err}");
    }

    /// #312 bug 1: a single dynamic insert whose new top-level field is a nested
    /// OBJECT must count the whole subtree against `max_fields_per_index`, not as
    /// one field — otherwise one document overshoots the budget by the subtree's
    /// key count (bounded, but a real overshoot) before the next evolve blocks it.
    #[tokio::test]
    async fn dynamic_insert_of_a_nested_subtree_cannot_overshoot_the_field_budget() {
        let dir = TempDir::new().unwrap();
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.limits.max_fields_per_index = 5;
        let engine_instance = Engine::new(config).expect("engine");
        engine_instance
            .create_index("budget-312", Schema::empty())
            .unwrap();
        let index = engine_instance.get_index("budget-312").unwrap();

        // Seed a base field so `big` below arrives as a SUBSEQUENT new top-level
        // field on the dynamic-evolve path (the site #312 bug 1 cites), not the
        // first-doc inference path.
        index
            .index_document(Some("seed".to_string()), serde_json::json!({"seed": 1}))
            .await
            .unwrap();
        let base = index.schema().await.field_count();
        assert!(base <= 5, "sanity: base schema within budget, got {base}");

        // A later doc whose only new top-level field is a 6-key nested object:
        // the dynamic `Object` FieldConfig has total_field_count == 7 (1 + 6),
        // which would push base+7 well past the cap of 5.
        index
            .index_document(
                Some("d1".to_string()),
                serde_json::json!({
                    "seed": 1,
                    "big": {"a": 1, "b": 2, "c": 3, "d": 4, "e": 5, "f": 6}
                }),
            )
            .await
            .unwrap();

        let fc = index.schema().await.field_count();
        assert!(
            fc <= 5,
            "a single dynamic insert must not overshoot max_fields_per_index (5); \
             the whole `big` subtree (size 7) should be rejected, got field_count={fc}"
        );
    }

