            TotalHitsRelation::Eq,
            "a fully-fetched hybrid total is exact: {:?}",
            result.total
        );
        assert_eq!(result.total.value, 6, "{:?}", result.total);
    }

    /// #594: a hybrid sub-list with EXACTLY `per_query_topk` matches (and none
    /// beyond) is exact, not capped: the leg reports `total.value ==
    /// per_query_topk` with relation `Eq`, so the capped check does not trip and
    /// the fused total stays `Eq` (ES parity) — where the old
    /// `hits.len() >= per_query_topk` cap reported a needless `Gte`.
    /// Fail-before: reverting the capped check `>` → `>=` flips this leg to `Gte`.
    #[tokio::test]
    async fn hybrid_reports_eq_at_the_exact_per_query_topk_boundary() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine
            .create_index("hybrid-boundary", Schema::empty())
            .unwrap();
        let idx = engine.get_index("hybrid-boundary").unwrap();
        // EXACTLY per_query_topk (default size 10 → 50) docs, identical vectors,
        // so the kNN leg matches all 50 and reports total.value == 50 (Eq).
        for n in 0..50 {
            idx.index_document(
                Some(format!("d{n}")),
                serde_json::json!({"embedding": [1.0, 0.0]}),
            )
            .await
            .unwrap();
        }
        let knn = QueryNode::Knn {
            field: "embedding".into(),
            vector: vec![1.0, 0.0],
            k: 256, // asks for more than exist → returns all 50, none beyond
            num_candidates: None,
            filter: None,
            boost: None,
            similarity: None,
        };
        let far = std::time::Instant::now() + std::time::Duration::from_secs(30);
        let result = idx
            .run_hybrid_with_deadline(
                &match_all(30_000), // default size 10 → per_query_topk = 50
                far,
                vec![xerj_query::ast::WeightedQuery {
                    query: knn,
                    weight: 1.0,
                }],
                xerj_query::ast::FusionStrategy::Rrf { k: 60 },
            )
            .await
            .unwrap();
        assert!(!result.timed_out);
        assert_eq!(
            result.total.relation,
            TotalHitsRelation::Eq,
            "a leg with exactly per_query_topk matches is exact, not capped (#594): {:?}",
            result.total
        );
        assert_eq!(result.total.value, 50, "{:?}", result.total);
    }

    #[tokio::test]
    async fn nested_knn_uses_the_shared_request_deadline() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine
            .create_index("nested-timeout", Schema::empty())
            .unwrap();
        let idx = engine.get_index("nested-timeout").unwrap();
        // 8 parents × 32 nested elements. The shape matters: the parent loop
        // checkpoints every 128 *parents* and so never fires past position 0
        // here, which leaves the nested-array checkpoint (every 128
        // *elements*, first hit inside parent 3) as the only cooperative
        // stop in the scan. Deleting it is therefore visible to this test —
        // with one element per parent the two checkpoints alias at 128 and
        // the parent loop silently covers for the missing one.
        for n in 0..8 {
            let items: Vec<serde_json::Value> = (0..32)
                .map(|_| serde_json::json!({"vector": [1.0, 0.0]}))
                .collect();
            idx.index_document(Some(format!("n{n}")), serde_json::json!({ "items": items }))
                .await
                .unwrap();
        }
        let request = SearchRequest {
            query: QueryNode::Nested {
                path: "items".into(),
                query: Box::new(QueryNode::Knn {
                    field: "items.vector".into(),
                    vector: vec![1.0, 0.0],
                    k: 10,
                    num_candidates: Some(10),
                    filter: None,
                    boost: None,
                    similarity: None,
                }),
                score_mode: None,
            },
            // Large on purpose. The gate parks the SCAN, but it does not stop
            // the request's own budget, which keeps burning real time while
            // the test holds the scan there. A 100 ms budget therefore raced:
            // on a loaded box the budget could expire against the real clock
            // before the test observed the park, and the request then timed
            // out through a different path than the nested-array checkpoint
            // this test exists to pin. The budget has to outlast any
            // plausible parking time while still sitting well under the
            // scripted clock's ten-minute jump, which is what must trip it.
            timeout_ms: Some(60_000),
            ..SearchRequest::default()
        };

        // Issue #100: this used to assert that a 20 ms sleep inside the scan
        // overran a 5 ms request budget — true on an idle box, false the
        // moment the machine is loaded enough that the scan needs more than
        // 5 ms just to reach its first checkpoint.
        //
        // Two facts replace that bet, and neither depends on how busy the
        // machine is.
        //
        // The gate replaces the sleep. While the test holds it, the scan is
        // parked *inside* its nested-array loop, before it has looked at the
        // clock, and it stays there for as long as we like — so "the scan is
        // still mid-flight" is established rather than hoped for. Failing to
        // park at all is the regression this test exists to catch: it means
        // the nested-array loop has no cooperative checkpoint and ran to
        // completion, and it is asserted on explicitly below.
        //
        // The scripted clock replaces the budget race. Checkpoint zero reads
        // an instant taken before the request was even built, so it is
        // always inside the request budget; the nested-array checkpoint
        // reads ten minutes later, so it is always past it.
        idx.test_scan_checkpoint_count.store(0, Ordering::Relaxed);
        idx.test_scan_checkpoint_parked.store(0, Ordering::SeqCst);
        idx.script_scan_clock(1, std::time::Duration::from_secs(600));
        let gate = Arc::clone(&idx.test_scan_checkpoint_gate)
            .lock_owned()
            .await;

        let scan = {
            let idx = Arc::clone(&idx);
            tokio::spawn(async move { idx.search(&request).await })
        };
        tokio::time::timeout(std::time::Duration::from_secs(60), async {
            while idx.test_scan_checkpoint_parked.load(Ordering::SeqCst) == 0 && !scan.is_finished()
            {
                tokio::time::sleep(std::time::Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("nested kNN scan neither parked nor finished within 60 s");
        assert!(
            idx.test_scan_checkpoint_parked.load(Ordering::SeqCst) > 0,
            "nested kNN ran to completion without a cooperative checkpoint inside \
             its nested-array loop (checkpoints reached: {})",
            idx.test_scan_checkpoint_count.load(Ordering::Relaxed)
        );
        drop(gate);

        let result = scan.await.unwrap().unwrap();
        assert!(result.timed_out);
        assert_eq!(result.total.relation, TotalHitsRelation::Gte);
        assert_eq!(
            idx.test_scan_checkpoint_count.load(Ordering::Relaxed),
            2,
            "nested scan must stop at its first nested-array checkpoint"
        );
    }

    #[tokio::test]
    async fn concurrent_unique_semantic_requests_share_bounded_deadlines() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        let mut schema = Schema::empty();
        let mut field = FieldConfig::new("body", FieldType::Text);
        field.options.dimensions = Some(16);
        field.options.similarity = Some("cosine".into());
        field.embedding = Some(xerj_common::types::EmbeddingConfig {
            endpoint: None,
            model: None,
            target_field: Some("body_vector".into()),
        });
        schema.fields.push(field);
        engine.create_index("semantic-concurrent", schema).unwrap();
        let idx = engine.get_index("semantic-concurrent").unwrap();
        for n in 0..256 {
            idx.index_document(
                Some(format!("s{n}")),
                serde_json::json!({"body": format!("semantic document number {n}")}),
            )
            .await
            .unwrap();
        }
        // Issue #100: two wall-clock bets used to live here. The checkpoint
        // count could come back below 16 because a loaded machine burnt the
        // 100 ms budget before a request reached its *first* checkpoint, and
        // "these ran concurrently" was inferred from total elapsed time
        // being under 500 ms — a threshold that says as much about the box
        // as about the engine.
        //
        // Both are now facts rather than bets. The scripted clock puts every
        // request's checkpoint zero inside its budget and every later
        // checkpoint past it, so each request reaches exactly two. And
        // concurrency is established by the gate: all eight scans are parked
        // on it at the same time, with none of the eight tasks finished,
        // before any of them is allowed to observe its deadline. Eight scans
        // simultaneously mid-flight is what "share bounded deadlines" means,
        // and it is now observed instead of timed.
        idx.test_scan_checkpoint_delay_ms
            .store(0, Ordering::Relaxed);
        idx.test_scan_checkpoint_count.store(0, Ordering::Relaxed);
        idx.test_scan_checkpoint_parked.store(0, Ordering::SeqCst);
        idx.script_scan_clock(1, std::time::Duration::from_secs(600));
        let gate = Arc::clone(&idx.test_scan_checkpoint_gate)
            .lock_owned()
            .await;

        let mut tasks = Vec::new();
        for n in 0..8 {
            let idx = Arc::clone(&idx);
            tasks.push(tokio::spawn(async move {
                let request = SearchRequest {
                    query: QueryNode::SemanticSearch {
                        field: "body".into(),
                        text: format!("unique concurrent deadline {n}"),
                        k: 10,
                        filter: None,
                        boost: None,
                    },
                    // Same reason as `nested_knn_uses_the_shared_request_deadline`:
                    // the gate parks the scan but the request's budget keeps
                    // running against the real clock. This test only needs the
                    // eight requests to be in flight together, so the budget
                    // must simply outlast the parking rather than expire during
                    // it. At 100 ms a loaded box could retire a request before
                    // all eight reached the gate, which is what made this flaky.
                    timeout_ms: Some(60_000),
                    ..SearchRequest::default()
                };
                idx.search(&request).await
            }));
        }

        tokio::time::timeout(std::time::Duration::from_secs(60), async {
            while idx.test_scan_checkpoint_parked.load(Ordering::SeqCst) < 8 {
                tokio::time::sleep(std::time::Duration::from_millis(1)).await;
            }
        })
        .await
        .expect("the eight semantic scans never all reached a cooperative checkpoint");
        // Every scan that reached the gate is still holding there, so none of
        // the eight requests can have completed: they are in flight together.
        for (n, task) in tasks.iter().enumerate() {
            assert!(
                !task.is_finished(),
                "request {n} finished while the other scans were still parked"
            );
        }
        drop(gate);

        for task in tasks {
            let result = task.await.unwrap().unwrap();
            assert!(result.timed_out);
            assert_eq!(result.total.relation, TotalHitsRelation::Gte);
        }
        assert!(
            idx.test_scan_checkpoint_count.load(Ordering::Relaxed) >= 16,
            "all semantic requests must reach multiple cooperative scan checkpoints"
        );
    }
}

// Doc-values (columnar) fast path for size:0 + match_all + aggs — child
// module so it can reach Index's private fields/methods via `super::`.
#[path = "fast_aggs.rs"]
mod fast_aggs;

/// Reconstruct the ES-JSON form of a query filter that the columnar fast-agg
/// path (`fast_aggs::compile_top_pred` + `aggs::doc_matches_filter`) can
/// evaluate over doc-values WITHOUT hydrating `_source`.  Returns `None` for
/// any query that isn't a plain conjunctive filter over exact/numeric fields
/// (FTS, wild/prefix, must_not/should bool, date-string ranges, numeric term
/// keys, …) — the caller then keeps the exact brute path.
///
/// Only the leaf/bool shapes that `doc_matches_filter` and `compile_pred`
/// jointly support are emitted, so the memtable matcher and the columnar
/// predicate stay byte-identical.
fn query_node_to_agg_filter(node: &QueryNode) -> Option<Value> {
    match node {
        QueryNode::MatchAll => Some(serde_json::json!({ "match_all": {} })),
        // `constant_score` is pure filter context — matching is exactly the
        // inner filter's (the wrapper only changes scores, which a size:0
        // agg never sees).
        QueryNode::Constant { query, .. } => query_node_to_agg_filter(query),
        // Exact term — keyword (string) values only.  Numeric/bool term keys
        // have typed-coercion subtleties, so bail (brute path handles them).
        QueryNode::Term {
            field,
            value: Value::String(s),
            ..
        } => Some(serde_json::json!({ "term": { field: s } })),
        QueryNode::Terms { field, values, .. } => {
            let mut strs: Vec<Value> = Vec::with_capacity(values.len());
            for v in values {
                match v {
                    Value::String(s) => strs.push(Value::String(s.clone())),
                    _ => return None,
                }
            }
            Some(serde_json::json!({ "terms": { field: Value::Array(strs) } }))
        }
        // #1260: `exists` is columnarizable (a non-null column row).  Before
        // this arm the node fell to the catch-all `None`, which dropped the
        // whole filtered-agg fast path for ANY query containing an exists
        // leaf — the finalize-verify window shape (`bool.filter [terms …,
        // exists …]` + terms agg) ran the brute `_source` path.  Meta
        // fields (`_id`, …) still bail downstream in `compile_pred`.
        QueryNode::Exists { field } => Some(serde_json::json!({ "exists": { "field": field } })),
        // Numeric **or** date/keyword-string range.  Every present bound must
        // be a JSON number, or every present bound must be a string — a mixed
        // pair has no single columnar form and stays on the brute path.
        //
        // String bounds are what a date range looks like here: the parser has
        // already resolved date math and rounding into the canonical RFC3339
        // `%Y-%m-%dT%H:%M:%S%.3fZ` form, and the `.dv` builder files a date's
        // string `_source` value under `Column::Keyword`, so `fast_aggs`
        // serves these via `Pred::RangeKw` (lexicographic == chronological for
        // that fixed-width form; it re-checks the invariant per segment).
        // Rejecting them here previously dropped every date-filtered
        // aggregation onto the full `_source` scan — ~9.9 s for a one-day
        // window over 1.12 M docs, versus ~0.16 s for the same aggregation
        // with no date filter at all.
        QueryNode::Range {
            field,
            gte,
            gt,
            lte,
            lt,
            ..
        } => {
            let present: Vec<&Value> = [gte, gt, lte, lt]
                .iter()
                .filter_map(|o| o.as_ref())
                .collect();
            if present.is_empty() {
                return None;
            }
            let all_num = present.iter().all(|v| v.is_number());
            let all_str = present.iter().all(|v| v.is_string());
            if !all_num && !all_str {
                return None;
            }
            let mut bounds = serde_json::Map::new();
            for (k, opt) in [("gte", gte), ("gt", gt), ("lte", lte), ("lt", lt)] {
                if let Some(v) = opt {
                    match v {
                        Value::Number(_) | Value::String(_) => {
                            bounds.insert(k.to_string(), v.clone());
                        }
                        _ => return None,
                    }
                }
            }
            if bounds.is_empty() {
                return None;
            }
            Some(serde_json::json!({ "range": { field: Value::Object(bounds) } }))
        }
        // Pure conjunction: `must` + `filter` only.  `should`, `must_not` and
        // `minimum_should_match` change matching semantics that the columnar
        // AND / `doc_matches_filter` conjunction can't reproduce here → bail.
        QueryNode::Bool {
            must,
            should,
            must_not,
            filter,
            minimum_should_match,
        } => {
            if !should.is_empty() || !must_not.is_empty() || minimum_should_match.is_some() {
                return None;
            }
            let mut clauses: Vec<Value> = Vec::with_capacity(must.len() + filter.len());
            for c in must.iter().chain(filter.iter()) {
                clauses.push(query_node_to_agg_filter(c)?);
            }
            if clauses.is_empty() {
                // bool with no positive clauses == match_all
                return Some(serde_json::json!({ "match_all": {} }));
            }
            Some(serde_json::json!({ "bool": { "filter": Value::Array(clauses) } }))
        }
        _ => None,
    }
}
