// ── Response types ────────────────────────────────────────────────────────────

/// Response returned after indexing a document.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct IndexResponse {
    pub id: String,
    pub seq_no: u64,
    pub version: u64,
    pub result: String,
}

/// Result of a same-ID serialized read-transform-write operation.
#[derive(Debug, Clone)]
pub struct SerializedDocumentUpdate {
    pub response: IndexResponse,
    /// `true` when the supplied upsert body created a previously missing ID.
    pub created: bool,
}

/// Outcome of a single-document delete (ES `DELETE /{index}/_doc/{id}`).
///
/// `found == true`  → the doc was live and is now tombstoned; `seq_no` is
/// the tombstone's internal (1-based) WAL seq and `version` the bumped
/// per-doc version (ES semantics: deletes increment `_version`).
///
/// `found == false` → nothing was deleted (`result: not_found`). `version`
/// still reports the ES-visible version: an existing tombstone is bumped
/// and persisted (matching ES, where a not-found delete still versions the
/// tombstone), an unknown id reports 1. `seq_no` carries the tombstone's
/// seq when one exists, else the index's latest assigned seq (xerj does
/// not consume a new seq_no for a not-found delete — divergence from ES
/// in the reported VALUE only).
#[derive(Debug, Clone)]
pub struct DeleteDocOutcome {
    pub found: bool,
    pub seq_no: u64,
    pub version: u64,
}

/// Per-field encoding statistics, derived from `FieldAnalyzer`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FieldEncodingInfo {
    /// Field name.
    pub field: String,
    /// Encoding type string, e.g. `"bitset_enum"`, `"delta_timestamp"`.
    pub encoding: String,
    /// Estimated average bytes stored per value in this encoding.
    pub bytes_per_value: f64,
    /// Estimated average bytes if stored as raw UTF-8 strings.
    pub raw_bytes_per_value: f64,
    /// Compression ratio vs raw strings (higher = better).
    pub compression_ratio: f64,
    /// Number of distinct values observed in the sample.
    pub distinct_values: usize,
}

/// What the node runs for semantic search over one field — see
/// [`Index::semantic_field_facts`]. Every value is read from the live schema
/// and embedder; none is derived, and there is intentionally no vector count.
#[derive(Debug, Clone, Serialize)]
pub struct SemanticFieldFacts {
    /// The concrete field (alias-resolved) carrying the embedding config.
    pub field: String,
    /// Companion field the vectors live in (`<field>_vector` by default).
    pub target_field: String,
    /// Effective dimensionality — the schema's own, or the engine's built-in
    /// default when the mapping did not pin one (`dims_from_schema` says which).
    pub dims: usize,
    /// `true` when `dims` came from the mapping, `false` when it is the
    /// engine default the query/ingest paths fall back to.
    pub dims_from_schema: bool,
    /// Effective similarity metric (`cosine` unless the mapping overrode it).
    pub similarity: String,
    /// The embedder's own honesty label, e.g.
    /// `"lexical feature-hash (built-in, 384-dim, non-neural)"`.
    pub embedder: &'static str,
