/// A scripted reading of the clock that cooperative scan checkpoints compare
/// against their deadline, installed per index by
/// [`Index::script_scan_clock`].
///
/// Checkpoints at scan positions below `advance_from` read exactly `base`;
/// `advance_from` and later read `base + skew`. Both readings are fixed at
/// install time, so a deadline derived from `base` is crossed at a position
/// the test chose, on an idle box and a thrashing one alike.
#[cfg(test)]
#[derive(Debug, Clone, Copy)]
struct ScanClockScript {
    base: std::time::Instant,
    advance_from: usize,
    skew: std::time::Duration,
}

#[cfg(test)]
impl ScanClockScript {
    fn reading_at(&self, position: usize) -> std::time::Instant {
        if position < self.advance_from {
            self.base
        } else {
            self.base.checked_add(self.skew).unwrap_or(self.base)
        }
    }
}

/// Per-index coordinator.
///
/// Owns the storage layer (`IndexStore`), the FTS memtable, and the schema.
/// All public methods are `async` so they can be called from Axum handlers
/// without blocking the async runtime.
pub struct Index {
    name: IndexName,
    schema: Arc<RwLock<ManagedSchema>>,
    /// ES `date_detection` mapping toggle (default true). Consulted by
    /// dynamic inference only — an explicit `date_detection: false` in the
    /// index mapping keeps first-seen ISO-looking strings mapped as `text`.
    /// Owned here (not in `ManagedSchema`) because the raw mapping blob is
    /// API-layer state (`engine.index_mappings`); the engine propagates the
    /// flag on create/open/put-mapping via [`Index::set_date_detection`].
    date_detection: AtomicBool,
    /// Fast bail for ingest date validation: true once the schema holds any
    /// `date`-typed field (set at construction and when dynamic inference
    /// adds one; never unset — a stale `true` only costs a schema read).
    has_date_fields: AtomicBool,
    /// Date fields whose mapping declares an explicit `format` (validated
    /// against that format by `bulk::find_bad_date_field`) or
    /// `ignore_malformed` — excluded from the engine's default-format
    /// ingest validation. Engine-propagated alongside `date_detection`.
    date_format_exclusions: std::sync::RwLock<Arc<std::collections::HashSet<String>>>,
    store: Arc<IndexStore>,
    /// 16-shard FTS memtable.  Replaces the pre-v16 single
    /// `Arc<RwLock<FtsMemtable>>` that serialized all concurrent bulk
    /// clients on one write lock.  Bulk batches pick one shard by
    /// `xxh3_64(first_doc_id) & 15` and hold only that shard's mutex
    /// for the WAL append + engine memtable push, so N concurrent
    /// clients on N different shards run truly in parallel on the
    /// write side.  Query paths iterate all shards.
    memtable: Arc<crate::memtable::ShardedFtsMemtable>,
    /// Exact per-document ordering shared by all publication stages wired to
    /// this coordinator. Idle keys are removed immediately.
    write_publication: Arc<crate::write_publication::WritePublicationCoordinator>,
    collection_publication: Arc<crate::collection_publication::CollectionPublication>,
    #[cfg(test)]
    publication_test_hook: Arc<parking_lot::RwLock<Option<PublicationTestHook>>>,
    #[cfg(test)]
    test_panic_after_merge_publish: Arc<AtomicBool>,
    #[cfg(test)]
    test_fail_merge_before_apply: Arc<AtomicBool>,
    #[cfg(test)]
    test_pause_merge_before_apply: Arc<AtomicBool>,
    #[cfg(test)]
    test_merge_repoint_ready: Arc<AtomicBool>,
    /// #2234 — park the merge encode on the merge pool, before any segment
    /// bytes are written, so a test can prove `refresh` proceeds while that
    /// encode is held. The park is a merge-pool thread, not a tokio blocking
    /// thread: occupying the blocking pool here is the stall this hook exists
    /// to catch.
    #[cfg(test)]
    test_hold_merge_encode: Arc<AtomicBool>,
    #[cfg(test)]
    test_merge_encode_held: Arc<AtomicBool>,
    /// #2234 — park `refresh` before it looks at the memtable. Off in release
    /// builds; `xerj-api` tests turn it on with the `refresh-test-hook` feature.
    #[cfg(any(test, feature = "refresh-test-hook"))]
    test_pause_refresh: Arc<AtomicBool>,
    #[cfg(any(test, feature = "refresh-test-hook"))]
    test_refresh_paused: Arc<AtomicBool>,
    #[cfg(any(test, feature = "refresh-test-hook"))]
    test_refresh_finished: Arc<AtomicU64>,
    /// #1212 — park the next search the instant its capture bracket
    /// validates (`test_pause_search_after_capture`), announcing via
    /// `test_search_capture_parked` so a test can publish a merge or flush
    /// into the exact window the capture-scope fix exists to make harmless.
    #[cfg(test)]
    test_pause_search_after_capture: Arc<AtomicBool>,
    #[cfg(test)]
    test_search_capture_parked: Arc<AtomicBool>,
    /// #1220 — the kNN exact-scan twin of the pair above: park the next
    /// kNN scan the instant its capture bracket validates
    /// (`test_pause_knn_after_capture`), announcing via
    /// `test_knn_capture_parked` so a test can publish a write, merge or
    /// flush into the exact window the capture-scoped admission predicate
    /// exists to make harmless.
    #[cfg(test)]
    test_pause_knn_after_capture: Arc<AtomicBool>,
    #[cfg(test)]
    test_knn_capture_parked: Arc<AtomicBool>,
    doc_count: Arc<AtomicU64>,
    /// Counter for `update` operations that detected no change to the
    /// existing source — surfaced via `indices.stats` as
    /// `indexing.noop_update_total`.
    noop_update_count: Arc<AtomicU64>,
    /// Request cache tracking for `request_cache=true` searches.
    /// `seen` stores query-body hashes that have been served before
    /// (bounded FIFO; see `RequestCacheSeen` for the eviction policy).
    /// miss_count increments on first sight, hit_count on repeat.
    request_cache_seen: Arc<RwLock<RequestCacheSeen>>,
    request_cache_hits: Arc<AtomicU64>,
    request_cache_misses: Arc<AtomicU64>,
    /// Internal query-result cache hit/miss counters (RC4-W4 item 4). Distinct
    /// from `request_cache_*` above (the ES `request_cache=true` seen-set):
    /// these track the `query_cache` result cache consulted on every
    /// cache-eligible search. Summed across all indices and surfaced on
    /// `/v1/metrics` as `xerj_query_cache_{hits,misses}`.
    query_cache_hits: Arc<AtomicU64>,
    query_cache_misses: Arc<AtomicU64>,
    registry: Arc<AnalyzerRegistry>,
    /// #937 — whether this index's SEGMENT paths (flush/merge write and the
    /// segment FTS query projection) honour a declared
    /// `analysis.analyzer.default`. `true` for every index created by this
    /// build. `false` ONLY for an index opened from a pre-#937 on-disk
    /// state that declares a default and already holds documents: its
    /// segments were written with `standard` postings, and switching them
    /// to the declared analyzer mid-life would silently split the index
    /// into two term spaces (the exact bug being fixed, in the other
    /// direction). See `segment_analyzer_binding_for_open`.
    ///
    /// The memtable is NOT bound by this flag — it has resolved the
    /// declared default since before #937, and a legacy index keeps that
    /// (pre-existing, split) behaviour rather than silently changing how
    /// its unflushed documents match.
    segment_default_analyzer_honored: bool,
    /// #1092 — which `analysis` spelling built [`Self::registry`]
    /// (`Canonical` for every index this build creates; possibly
    /// `LegacyShorthandOnly` for a pre-#204 index reopened with documents).
    /// Kept so the API can report the analysis block actually in force
    /// rather than the one merely declared — see [`Self::analysis_in_force`].
    analysis_binding: AnalysisBinding,
    data_dir: PathBuf,
    /// Doc count threshold for auto-flush (default: 10,000).
    flush_doc_threshold: usize,
    /// Byte threshold for auto-flush (from config flush_size_mb).
    flush_byte_threshold: usize,
    /// #873: seconds a non-empty memtable may sit unchanged before it is
    /// flushed regardless of size (`storage.flush_idle_secs`; 0 = disabled).
    /// Below the thresholds a small dataset otherwise NEVER flushed: its
    /// documents stayed memtable-resident for the whole process lifetime and
    /// its WAL generations replayed on every boot. Elasticsearch flushes a
    /// shard idle past `indices.memory.shard_inactive_time` (default 5m) via
    /// a periodic controller (IndexingMemoryController.java:76-78 →
    /// IndexShard.flushOnIdle, IndexShard.java:2787-2790; AGPL — approach
    /// only, implementation ours): idleness is detected by a probe, not by
    /// stamping the write path.
    flush_idle_secs: u64,
    /// #873: last memtable fingerprint `needs_flush` observed (doc_count ^
    /// rotated size). A changed fingerprint = write activity since the last
    /// probe; an unchanged one ages toward the idle flush.
    idle_probe_fingerprint: std::sync::atomic::AtomicU64,
    /// #873: coarse ms timestamp (process-monotonic) of the probe that last
    /// saw the fingerprint change.
    idle_probe_at_ms: std::sync::atomic::AtomicU64,
    /// Index-level settings (e.g. number_of_shards, number_of_replicas).
    settings: Arc<RwLock<Value>>,
    /// Cached schema hash for skipping schema evolution on unchanged docs.
    /// Updated every 100 docs; avoids hashing the schema on every ingest.
    schema_hash_cache: Arc<std::sync::atomic::AtomicU64>,
    /// Doc count at which the cached schema hash was last computed.
    schema_hash_epoch: Arc<AtomicU64>,
    /// Optional HNSW index for dense-vector KNN search.
    /// Lazily created on first vector document insertion.
    pub hnsw: Arc<RwLock<Option<HnswIndex>>>,
    /// Maps string doc-id → u64 node-id used by HNSW.
    hnsw_id_map: Arc<RwLock<HashMap<String, u64>>>,
    /// Maps u64 node-id → string doc-id (reverse of hnsw_id_map).
    hnsw_id_rev: Arc<RwLock<HashMap<u64, String>>>,
    /// Monotonic counter for HNSW node IDs.
    hnsw_next_id: Arc<AtomicU64>,
    /// Number of distinct live docs that CARRY the pinned vector field (item
    /// 8). This is the coverage-gate denominator: the ANN query path may only
    /// serve when `hnsw_id_map.len() == vector_doc_count`, i.e. every
    /// vector-bearing doc made it into the graph. The old gate compared
    /// against the index-global `doc_count`, so a SINGLE doc lacking the
    /// vector field (a mixed log/vector corpus) left `id_map.len() < doc_count`
    /// forever and silently pinned the whole index on O(N) brute force.
    /// Incremented once per doc-id newly added to the graph, decremented on
    /// delete; never above the true count (over-count on updates biases the
    /// gate to brute, which is safe).
    vector_doc_count: Arc<AtomicU64>,
    /// Vector-bearing batch publications that have made, or are about to
    /// make, their authoritative document source visible but have not yet
    /// completed the corresponding HNSW update. Any non-zero value forces
    /// ANN to exact fallback so equality of graph coverage counters cannot
    /// expose a stale graph during this interval.
    hnsw_publications_in_flight: Arc<AtomicU64>,
    /// Monotonic begin/end epoch paired with `hnsw_publications_in_flight`.
    /// Snapshot persistence samples this around graph serialization so even
    /// a publication that starts and finishes during the save is detected.
    hnsw_publication_generation: Arc<AtomicU64>,
    /// FIELD IDENTITY: the single field this index's HNSW graph indexes.
    ///
    /// Pinned when the graph is first created (preferring the schema's first
    /// dense_vector-mapped field over the ingested doc's first numeric-array
    /// field). Once `Some(f)`, `index_vectors` inserts ONLY field `f`; docs
    /// lacking `f` get no graph entry, which breaks the
    /// `hnsw_id_map.len() == doc_count` coverage guard and keeps the kNN
    /// query path on exact brute force (safe). `None` with a live graph
    /// means a legacy (pre-field-stamp) snapshot: ingest keeps the historical
    /// per-doc first-field behavior and the HNSW query path never engages.
    ///
    /// std (not tokio) RwLock: read on every ingested doc and inside the
    /// query gate; critical sections are a clone/compare with no `.await`.
    hnsw_field: Arc<std::sync::RwLock<Option<String>>>,
    /// Semantic companion targets for which a passage-vector array has ever
    /// been observed.
    ///
    /// This set is monotonic: update/delete never removes an entry. HNSW
    /// contains pooled document vectors, so it cannot safely select candidates
    /// for a field once any live or historical document may score by its best
    /// passage. A false positive only keeps that field on the exact scorer;
    /// a false negative could omit the true best-passage winner.
    ///
    /// Publication records the target before WAL/memtable visibility. The set
    /// is persisted in the HNSW identity sidecar, unioned with WAL replay, and
    /// reconstructed conservatively for legacy sidecars.
    passage_chunk_fields: Arc<std::sync::RwLock<HashSet<String>>>,
    /// True when the loaded HNSW snapshot is flush-time stale relative to
    /// the replayed WAL (`ids.json` seq_no stamp != store.current_seq_no()).
    /// A WAL-tail UPDATE of an already-graphed doc leaves both
    /// `hnsw_id_map.len()` and `doc_count` unchanged, so the coverage guard
    /// cannot see it — this flag disables the HNSW query path (brute force
    /// serves instead) while ingest-side graph maintenance continues.
    /// Persisted back into ids.json so a later flush of the still-stale
    /// graph cannot re-stamp it as fresh. Cleared ONLY by the background
    /// stale rebuild (RC4 W2 item 17, `rebuild_hnsw_from_docs`) once the
    /// graph has been re-derived from the authoritative doc set.
    hnsw_stale: Arc<std::sync::atomic::AtomicBool>,
    /// True while `rebuild_hnsw_from_docs` is running (RC4 W2 item 17):
    /// guards against double-spawn and is surfaced in stats so operators
    /// can distinguish "healing" from "permanently degraded".
    hnsw_rebuilding: Arc<std::sync::atomic::AtomicBool>,
    /// JoinHandle of the in-flight stale rebuild, aborted by
    /// `abort_background_tasks` so an unfinished rebuild can't hold the
    /// runtime (or the index Arc) alive across shutdown.
    hnsw_rebuild_task: Arc<parking_lot::Mutex<Option<tokio::task::JoinHandle<()>>>>,
    /// Per-field ingest-time SQ8 code stores (#392): field name → handle.
    /// Empty unless the mapping declares `quantization: "scalar8"` — every
    /// other index pays one empty-map read per write.
    sq8_stores: Arc<parking_lot::RwLock<HashMap<String, Arc<Sq8StoreHandle>>>>,
    // ── Per-index concurrency control ─────────────────────────────────────────
    /// Semaphore that limits the number of queries executing concurrently
    /// against this index.  The default is 64 permits, matching the global
    /// `max_concurrent_searches` default.  This prevents a single hot index
    /// from starving other indices in a multi-tenant deployment — a noisy
    /// neighbour cannot exhaust all available query slots.
    max_concurrent_queries: Arc<Semaphore>,
    #[cfg(test)]
    test_scan_checkpoint_delay_ms: Arc<AtomicU64>,
    #[cfg(test)]
    test_scan_checkpoint_count: Arc<AtomicU64>,
    /// Deterministic stand-in for the wall-clock delay above: while a test
    /// holds this mutex, the first cooperative checkpoint of a scan that is
    /// past position 0 parks on it and cannot observe the deadline until the
    /// test lets go. That turns "the scan is still inside its loop when the
    /// request budget runs out" into a fact established by the test instead
    /// of a race against the machine's load.
    #[cfg(test)]
    test_scan_checkpoint_gate: Arc<tokio::sync::Mutex<()>>,
    /// Number of checkpoints that have reached the gate. Lets a test wait
    /// for the scan to be provably parked before it does anything else.
    #[cfg(test)]
    test_scan_checkpoint_parked: Arc<AtomicU64>,
    /// Injected clock for the cooperative scan deadline check, owned by this
    /// index — i.e. by the object under test, never process-wide. `None`
    /// (the default) means every checkpoint reads the real clock.
    ///
    /// This is how a test states "the request's budget is spent by the time
    /// the scan reaches position p" as a fact. The alternative — hand the
    /// scan a budget of a few milliseconds and hope the machine reaches the
    /// first checkpoint inside it — is a race the test loses whenever the
    /// box is busy (issue #100). The deadline comparison itself is
    /// untouched: the scan still compares a clock reading against the real
    /// deadline it was handed, so a scan that ignores its deadline still
    /// fails these tests.
    #[cfg(test)]
    test_scan_clock: Arc<std::sync::Mutex<Option<ScanClockScript>>>,
    #[cfg(test)]
    test_ann_passage_guard_pause: Arc<AtomicBool>,
    #[cfg(test)]
    test_ann_passage_guard_ready: Arc<AtomicBool>,
    #[cfg(test)]
    test_hnsw_save_passage_snapshot_pause: Arc<AtomicBool>,
    #[cfg(test)]
    test_hnsw_save_passage_snapshot_ready: Arc<AtomicBool>,
    #[cfg(test)]
    test_stored_value_load_delay_ms: Arc<AtomicU64>,
    #[cfg(test)]
    test_stored_value_load_count: Arc<AtomicU64>,
    #[cfg(test)]
    test_stored_value_load_pause_before_publish: Arc<std::sync::atomic::AtomicBool>,
    #[cfg(test)]
    test_stored_value_load_ready_to_publish: Arc<std::sync::atomic::AtomicBool>,
    #[cfg(test)]
    test_segment_cache_publish_pause_mask: Arc<AtomicU64>,
    #[cfg(test)]
    test_segment_cache_publish_ready_mask: Arc<AtomicU64>,
    // ── Per-index enrich lookup tables ────────────────────────────────────────
    /// Named enrich tables: each table maps a key to a JSON object of extra
    /// fields to merge into matching documents at ingest time.
    ///
    /// Added via `POST /v1/indices/{name}/enrich`, keyed by table name.
    /// The lookup is keyed by the value of a nominated field; when a document
    /// has that field set and the value appears in the table, the enrichment
    /// fields are merged into the document before indexing.
    pub enrichments: Arc<RwLock<HashMap<String, EnrichTable>>>,

    /// Doc count at which the last automatic flush was triggered.
    last_flush_doc_count: Arc<AtomicU64>,

    /// V4 M4.5 — concurrent flush semaphore.  Replaces the old
    /// `flush_lock` + `flush_in_progress` pair that capped in-flight
    /// flushes at one and became the ingest ceiling on log-bursty
    /// workloads (60 k docs/s ingest, one flush takes ~5 s for 100 k
    /// docs).  Allowing up to `MAX_CONCURRENT_FLUSHES` writers to build
    /// segments in parallel lets ingest use all CPU cores instead of
    /// just the handful rayon uses inside a single flush.
    flush_sema: Arc<tokio::sync::Semaphore>,

    /// Milliseconds a shard flush may wait for `flush_sema` or the
    /// process-global finalize gate before failing. The wait is before the
    /// memtable freeze (#1635). Production sets this once from
    /// `engine.flush_admit_timeout_secs`; tests shrink it.
    flush_admit_timeout_ms: AtomicU64,
    /// Milliseconds `flush` / `refresh` waits for one index before returning
    /// an error that names the index. The publish coordinator is detached,
    /// not aborted (#1015, #1635).
    flush_timeout_ms: AtomicU64,

    /// Set to `true` while a segment merge is in progress.  Prevents the
    /// background merge thread from queueing overlapping merges.
    merge_in_progress: Arc<std::sync::atomic::AtomicBool>,

    /// Snapshot of the operator-tunable merge policy parameters
    /// (tier_floor, min/max merge count, max segment size). Cloned from
    /// `Config.merge` at index construction; reads are cheap and merge
    /// runs hold the snapshot for the duration of one batch.
    merge_config: xerj_common::config::MergeConfig,
    /// Snapshot of `Config.compression`, read by `merge_pass_locked` to pick
    /// the zstd effort for the merged segment's durable artifacts. Only the
    /// merge path consults it: flush stays pinned at the level its own
    /// constants document, because raising it there is the ingest collapse in
    /// `reports/2026-04-25T21-50-00_ingest_perf_regression_zstd19.md`.
    ///
    /// Before #318 this section reached no encoder at all — two nodes
    /// differing only in `[compression]` wrote byte-identical segments.
    compression_config: xerj_common::config::CompressionConfig,
    /// Retained so a semantic field added after index creation can pin the
    /// same embedding identity before its first document is accepted.
    embedding_config: xerj_common::config::EmbeddingConfig,

    /// Snapshot of `config.limits.max_fields_per_index`, enforced on the
    /// dynamic-mapping ingest path (`evolve_schema_from_doc(s)`) to prevent
    /// mapping-explosion DoS. Mirrors `ManagedSchema::apply_document`'s check
    /// but on the production path the engine uses `evolve_schema_from_doc(s)`
    /// directly, which previously bypassed the limit.
    max_fields_per_index: u32,

    /// Snapshot of `config.limits.max_result_window`: the `from + size`
    /// ceiling for an index whose settings carry no `index.max_result_window`.
    max_result_window: usize,

    /// Embedding backend for `semantic` / `semantic_text` (v0.7-P2).
    /// One of lexical (built-in, default), an external proxy, the built-in
    /// Candle neural BERT embedder, or the experimental ONNX Runtime backend
    /// — selected by `Config.embedding.mode`.
    /// [`xerj_ai::Embedder::is_active`] is false only for the lexical
    /// fallback; an active backend embeds arbitrary query text, while the
    /// lexical fallback embeds only `semantic_text` fields (embedded the
    /// same way at ingest). Reused across queries (proxy admission state and
    /// neural/ONNX models are shared behind the `Arc`).
    embedder: Arc<RwLock<xerj_ai::Embedder>>,

    // ── Per-index metrics ─────────────────────────────────────────────────────
    /// Total search queries executed.
    metric_query_count: Arc<AtomicU64>,
    /// Total search latency accumulated (milliseconds).
    metric_query_total_ms: Arc<AtomicU64>,
    /// Total documents indexed.
    metric_index_count: Arc<AtomicU64>,
    /// Total indexing latency accumulated (milliseconds).
    metric_index_total_ms: Arc<AtomicU64>,
    /// Total `_doc/{id}` GET operations — includes both the HTTP
    /// `GET /{index}/_doc/{id}` route and engine-internal lookups
    /// (e.g. terms-lookup in queries). Exposed via indices.stats.
    pub metric_get_count: Arc<AtomicU64>,
    pub metric_get_total_ms: Arc<AtomicU64>,
    pub metric_get_exists_count: Arc<AtomicU64>,
    pub metric_get_missing_count: Arc<AtomicU64>,

    /// M2 G2 — cache of decoded doc-values columns keyed by segment id.
    /// Segments are immutable once flushed, so the decoded columns stay
    /// valid for the lifetime of the segment.  First agg against a segment
    /// decodes the `.dv` sidecar; subsequent queries hit the cache and
    /// skip I/O + LZ4 decompress + per-column decode entirely.
    dv_cache: Arc<dashmap::DashMap<String, Resident<DocValueMap>>>,

    /// Per-(segment, field) sorted sort-key shadow: `(f64-bits, doc_pos)`
    /// ascending by value, used by the field-sort candidate prefilter.
    /// For Numeric dv columns this is a cached copy of `NumericColumn::
    /// sorted`; for Keyword dv columns whose every term is a date-shaped
    /// string it holds the epoch keys produced by the SAME normalisation
    /// `compute_sort_values` applies per hit (`sort_date_normalize`), so
    /// candidate order == heap order.  `None` is cached for ineligible
    /// columns (nulls, non-date terms, count mismatch) to avoid re-probing
    /// per query.  Keyed by `"{segment_id}\u{1}{field}"`; same
    /// immutable-segment lifecycle as `dv_cache` (never invalidated,
    /// retired segment ids are simply never queried again).
    sort_shadow_cache: Arc<dashmap::DashMap<String, Resident<Option<Arc<Vec<(i64, u32)>>>>>>,
    /// Fields that have EVER been requested through `sorted_shadow_for`
    /// on this index (bounded at 16) — the publish-time warm pre-builds
    /// these fields' shadows for every new segment so the first sorted
    /// query after a flush/merge doesn't pay the O(n log n) build inside
    /// its own latency.
    sort_shadow_fields: Arc<dashmap::DashMap<String, DateScale>>,
    /// Sync-readable mirror of every date-mapped field whose epoch scale the
    /// mapping DECLARES — `Millis` for an ES `date`, `Nanos` for an ES
    /// `date_nanos` (#790, #889).
    ///
    /// The mapping lives in `self.schema`, behind an async `RwLock`; the
    /// paths that must agree on a date's epoch scale — `compute_sort_values`
    /// (per hit), `build_sort_shadow` / `shadow_range_bounds` (per segment),
    /// `sort_epoch_memo` (per buffered memtable doc) — are all sync and on the
    /// scan path. The snapshot is swapped wholesale on every schema write
    /// (`save_schema`) so a reader always sees one consistent set.
    date_field_scales: Arc<parking_lot::RwLock<Arc<std::collections::HashMap<String, DateScale>>>>,
    /// Per-segment single-flight guard for the `stored_slices_for` miss
    /// arm: without it, every in-flight query racing the same cold
    /// segment (up to the 64-permit cap) ran its own full stored-section
    /// decompress — one 30 ms decode became a ~1 s, 64-query stall
    /// episode at every flush/merge publish the warm hadn't reached yet.
    stored_slices_build_locks: Arc<dashmap::DashMap<String, Arc<std::sync::Mutex<()>>>>,
    /// #2422/#2423: a weak handle to this index, so a query that answered a
    /// cold segment from its winning rows alone can warm that segment's
    /// stored slices off the query path (see `schedule_cold_stored_warm`).
    self_ref: std::sync::OnceLock<std::sync::Weak<Index>>,
    /// Segments with a background stored-slices warm queued or running.
    cold_stored_warms: dashmap::DashMap<String, ()>,
    /// Cold segments answered by row-selective hydration (observability and
    /// tests).
    cold_row_hydrations: AtomicU64,
    /// Per-(segment, field, bounds) Range pre-filter position sets.
    /// `build_range_prefilter_cached` was cached in name only — it re-ran
    /// the O(matches) `range_doc_ids` walk + HashSet build per query per
    /// segment (~30-80 ms against a freshly-merged multi-M-doc segment,
    /// multiplied by every query racing the same post-publish miss — the
    /// residual range p99 wobble).  Segments are immutable; bounded by a
    /// wholesale clear at 32 entries (worst-case tens of MB per merged-
    /// segment entry — a roaring bitmap representation is the durable
    /// follow-up) and evicted by segment id at merge retire.
    range_prefilter_cache: Arc<dashmap::DashMap<String, Arc<PrefilterSet>>>,

    /// Per-segment `_id → stored-position` index, built lazily on the first
    /// `ids` query that touches a segment and reused thereafter.  An `ids`
    /// query used to full-scan every stored doc (O(N) brace-walk + parse)
    /// just to find a handful of primary keys — 128 ms to return 3 docs at
    /// 100k, scaling linearly with the corpus.  With this map an `ids` query
    /// resolves each requested id to its stored position (like GET
    /// `_doc/{id}` / `_mget`) and hydrates only those positions via the
    /// `StoredSlices` offset index, so it is O(#ids) and FLAT vs corpus
    /// size.  Segments are immutable → the map never goes stale; evicted by
    /// segment id at the merge-completion site alongside the other caches.
    id_pos_cache: Arc<dashmap::DashMap<String, Resident<std::collections::HashMap<String, u32>>>>,

    /// Per-segment `stored-position → seq_no` map for the scored-family
    /// columnar fast path. Segment ROW order is NOT insertion order (the
    /// 16-shard memtable flush + merges interleave rows), but ES's score
    /// tie-break is Lucene doc id = arrival order = our seq_no — so tied
    /// top-k selection must rank rows by seq, not by row index. Built once
    /// per segment from the (cached) `id_pos_map_for` + version map; only
    /// consulted under `!deletes_present` (seq of a live id is then stable),
    /// and evicted by segment id at the merge-completion site.
    row_seq_cache: Arc<dashmap::DashMap<String, Resident<Vec<u64>>>>,

    /// Per-segment cache of decoded `Vec<Value>` from the stored section.
    /// KNN search and segment-scan get-document paths used to call
    /// `decode_stored` + `simd_json::serde::from_slice` *every* time —
    /// for a 100-segment index with 100 MB stored per segment, every
    /// vector query re-paid ~10 GB of decompress + parse work. Segments
    /// are immutable once flushed, so this cache is correct without
    /// invalidation. Same `Left unbounded for now` caveat as `dv_cache`.
    stored_value_cache: Arc<dashmap::DashMap<String, Resident<Vec<Value>>>>,
    /// Serializes the short "is this segment still published? + cache insert"
    /// transaction against merge eviction. Segment parsing never holds it.
    segment_cache_lifecycle: Arc<parking_lot::RwLock<()>>,
    segment_hydration_budget: Arc<SegmentHydrationBudget>,
    /// Per-segment cancellation-safe cold-load single-flight. The sender
    /// publishes the immutable parsed section to every concurrent vector
    /// query; the detached producer survives cancellation of any requester.
    stored_value_loads:
        Arc<dashmap::DashMap<String, tokio::sync::watch::Sender<Option<Resident<Vec<Value>>>>>>,
    /// Bounds simultaneous whole-segment decompression/parsing across distinct
    /// cold segments. Per-segment single-flight removes duplicate work; this
    /// bound prevents a many-segment cold storm from multiplying peak memory.
    stored_value_load_semaphore: Arc<Semaphore>,

    /// Per-segment cache of the DECOMPRESSED stored section plus per-doc
    /// `(start, end)` byte offsets, used by the sorted-DV candidate path
    /// (field-sorted match_all / search_after).  With it, hydrating the
    /// O(from+size) candidate positions of a segment is two vector
    /// lookups + a per-candidate `simd_json` parse — no per-query
    /// zstd/LZ4 decompress and no O(segment-bytes) brace re-scan.
    ///
    /// This holds raw bytes once per segment and shares the process-wide
    /// segment hydration budget with all other immutable cache owners.
    /// Refusal keeps the built value local to the current query. Segments are immutable, so
    /// entries stay valid until a merge drops the segment id (evicted at
    /// the merge-completion site alongside dv_cache/stored_value_cache).
    stored_slices_cache: Arc<dashmap::DashMap<String, Resident<StoredSlices>>>,
    /// Per-segment cache of the DECOMPRESSED stored section bytes for the
    /// UNSORTED scan path (`scan_stored_section_into`).  The bounded
    /// collector already stops the scan O(from+size) docs in, but every
    /// query still paid the full zstd/LZ4 decompress of the FIRST segment
    /// it touched — for a merged multi-million-doc segment that is
    /// 0.5-1.5 s per query, and under a bulk writer (100 % query-cache
    /// misses) it WAS the match_all/bool/range read-under-write tail.
    /// Budgeted like `stored_slices_cache`; entries evicted by id at the
    /// merge-completion site.  Segments are immutable → no invalidation.
    decoded_stored_cache: Arc<dashmap::DashMap<String, Resident<Vec<u8>>>>,
    /// Per-(segment, field-set) cache of an opened `FtsIndexReader`.
    ///
    /// `FtsIndexReader::open` was called INSIDE the per-segment loop of
    /// `search_bounded` on every query, and it is not cheap: it performs TWO
    /// zstd decompressions per field — the whole `.post` blob (`ZPS1`) and the
    /// whole `.meta` flat array (`ZFM4`) — into owned `Vec`s, because a
    /// compressed blob cannot be mmap'd. Measured on one real production field
    /// (`body`, 17.0 MB `.post` -> 25.3 MB, 2.8 MB `.meta` -> 15.8 MB): ~50 ms
    /// and ~41 MB per (segment, field), rebuilt and thrown away every query.
    /// The comment on `PostData` ("open allocates almost nothing per segment")
    /// describes only the uncompressed/mmap path, which modern segments never
    /// take.
    ///
    /// Segments are immutable, so this needs no invalidation — the same
    /// argument every other cache here rests on. Entries are evicted by id at
    /// the merge-completion site and the payload is budget-charged, so a large
    /// corpus degrades to today's open-per-query rather than growing without
    /// bound.
    ///
    /// The key includes the field set because `open` loads exactly the fields
    /// it is asked for; a reader opened for a narrower set must never satisfy
    /// a query needing a wider one.
    fts_reader_cache: Arc<dashmap::DashMap<String, Resident<Arc<FtsIndexReader>>>>,
    /// Flat `f32` vectors of one vector field over one segment, keyed
    /// `"<segment_id>\u{1}<field>\u{1}<mode>"` (#939).
    ///
    /// The exact kNN scan used to read every vector out of the parsed
    /// `_source` tree on every query — after deep-cloning that tree, vectors
    /// included. `stored_value_cache` saves the disk read and the parse; it
    /// cannot save a walk over ~10 M `Value::Number`s per query on a 5 k
    /// document multi-passage corpus. This holds the same numbers once, as
    /// `f32`, at ~1/8 of the bytes the parsed tree spends on them.
    ///
    /// Same lifecycle as every other cache here: segments are immutable so an
    /// entry never goes stale, it is evicted by segment-id prefix when a merge
    /// retires the segment, and it is charged to the hydration budget — over
    /// budget the scan builds the column per query and drops it, which is
    /// still cheaper than the clones it replaced. Liveness is NOT in the
    /// column: deletes and updates are resolved per query against the version
    /// map, exactly as before.
    vector_column_cache:
        Arc<dashmap::DashMap<String, Resident<crate::vector_column::SegmentVectorColumn>>>,
    /// Per-(segment, query-shape) match-count cache for the
    /// `try_shortcut_count` Bool intersection arm.  The fused columnar
    /// walk is O(anchor-predicate matches) per segment PER QUERY — for a
    /// dashboard-style fixed bool filter under a bulk writer (query cache
    /// useless: every batch bumps `dataset_version`) that was ~0.6-1 s of
    /// re-counting per request at 1.5 M docs.  Segments are immutable, so
    /// a (segment_id, canonical-query-json) key never goes stale; bounded
    /// by wholesale clear at `SHORTCUT_COUNT_CACHE_MAX` since query
    /// shapes are client-supplied.
    shortcut_count_cache: Arc<dashmap::DashMap<(String, String), u64>>,
    /// Per-segment GHOST-position bitmap for the flush→merge window
    /// (b7 DEFECT 1c): bit `pos` set ⇔ the stored doc at `pos` is
    /// tombstoned or superseded per the version map.  Keyed by segment
    /// id, value carries the `ghost_events` epoch it was built at — any
    /// new overwrite/delete bumps the epoch and forces a rebuild, and a
    /// merge replaces the segment id, so a stale bitmap can never be
    /// served.  Only ever consulted while `deletes_present` is true;
    /// bounded by wholesale clear (see `ghost_positions_for`).
    ghost_positions_cache: Arc<dashmap::DashMap<String, (u64, Arc<Vec<u64>>)>>,
    /// Regexp term-dictionary expansion cache — keyed by
    /// `(segment_id, field, pattern)`, holds the exact union doc count
    /// plus the first `REGEXP_EXPANSION_POS_CAP` matching doc positions
    /// for that segment (ES keeps the equivalent in its per-segment
    /// query cache).  Segments are immutable, so entries stay valid for
    /// the segment's lifetime — same no-invalidation contract as
    /// `dv_cache` / `stored_value_cache` above.  Bounded: cleared
    /// wholesale when it exceeds `REGEXP_EXPANSION_CACHE_MAX` entries
    /// because patterns are query-supplied.  This is what makes a
    /// cache-busted (size-varied) regexp count O(1) after the first
    /// touch instead of re-opening FTS side-cars and re-merging postings
    /// on every request.
    regexp_expand_cache: Arc<dashmap::DashMap<(String, String, String), Arc<RegexpExpansion>>>,

    /// Fast-agg path: per-(segment, field) parsed date ordinals
    /// (ord → epoch-ms; i64::MIN = unparseable).  Same immutable-segment
    /// lifecycle as `dv_cache`; evicted alongside it on merge.
    fast_date_cache: Arc<dashmap::DashMap<(String, String), Arc<Vec<i64>>>>,

    /// Fast-agg path: per-(segment, field) sorted parsed dates + prefix doc
    /// counts (`ms[i]` ascending, `prefix[i+1]-prefix[lo]` = docs in a ms
    /// range).  Lets `date_range` answer each range with two binary searches
    /// instead of a full ord walk.  Same lifecycle as `fast_date_cache`.
    fast_date_sorted_cache: Arc<dashmap::DashMap<(String, String), Arc<(Vec<i64>, Vec<u64>)>>>,

    /// M3 framework — response cache for identical queries.  Keyed on
    /// `(query_body_hash, dataset_version)` and holds the pre-computed
    /// `SearchResult` ready to serialize.  Cache hit → ~10 µs total
    /// query latency (vs ~500 µs cache miss) because we skip query
    /// parsing, lock acquisition, segment iteration, and result
    /// construction entirely.  Invalidates on every doc write via
    /// `dataset_version.fetch_add(1)` in `index_doc`.
    pub query_cache: Arc<dashmap::DashMap<QueryCacheKey, Arc<SearchResult>>>,
    pub dataset_version: Arc<AtomicU64>,

    /// Single-flight coalescing map for identical in-flight reads, keyed by
    /// the SAME `(query_body_hash, dataset_version)` as `query_cache`. Under
    /// the mixed read-under-write workload the open-loop 300/s reader fires
    /// the IDENTICAL body thousands of times; a flush/merge stall makes the
    /// `query_cache` miss (the flush bumped `dataset_version`) and lets a
    /// burst of same-key requests pile up concurrently, each otherwise
    /// recomputing the whole scan/agg and stealing cores from the writer.
    /// The FIRST request of a key ("leader") computes and publishes on this
    /// watch channel; identical concurrent requests ("followers") await and
    /// clone the leader's result instead of recomputing. Because the key is
    /// identical to the `query_cache` key, a follower's served result is
    /// byte-identical to what a `query_cache` hit would have returned — no
    /// new staleness is introduced. A leader that errors / times out
    /// publishes nothing (drops the sender), so followers fall through and
    /// recompute independently — no poisoning.
    query_inflight:
        Arc<dashmap::DashMap<QueryCacheKey, tokio::sync::watch::Sender<Option<Arc<SearchResult>>>>>,
    /// Count of follower reads served by single-flight coalescing (i.e. the
    /// number of full search recomputes eliminated). Structural evidence for
    /// the read-under-write CPU-contention fix.
    metric_singleflight_coalesced: Arc<AtomicU64>,

    /// Sync-path flush coordinator — notified by `index_batch_sync_raw`
    /// when a shard crosses threshold; drained by a dedicated OS thread
    /// (`xerj-flusher-<idx>`).  Lets rayon scanners stay fully
    /// synchronous instead of crossing into tokio per batch.
    pub(crate) flush_signal: Arc<SyncFlushCoord>,

    /// Caller-supplied `_version` values for docs indexed with
    /// `version_type=external[_gte]`. Used to enforce monotone /
    /// strict CAS on reindex and to echo the exact version back in
    /// the response.
    pub external_versions: Arc<dashmap::DashMap<String, u64>>,

    /// Handle to the currently armed debounced merge-check task, if any
    /// (#871 — armed by [`Index::request_merge_check`] when the segment
    /// set changes; an idle index holds `None`).  Held so the shutdown
    /// path (`Engine::flush_all_force` → SIGTERM exit) can abort the task
    /// explicitly — without it the tokio runtime stays alive after axum
    /// has stopped accepting connections, because a spawned task keeps
    /// the runtime non-empty while its debounce `tokio::time::sleep` is
    /// pending.  The bench at 2026-04-25 caught this as a SIGTERM hang
    /// regression introduced by B-2b (against the old always-on tick
    /// task; the contract is unchanged).
    /// `parking_lot::Mutex` (sync, no async, no `.await`) is fine
    /// because we only ever take/replace under it, never hold across
    /// any awaits.
    pub(crate) merge_task: Arc<parking_lot::Mutex<Option<tokio::task::JoinHandle<()>>>>,
    /// #871 — true while a debounced merge check is scheduled (armed).
    /// Set by [`Index::request_merge_check`], cleared by the check task
    /// when it quiesces; makes arming idempotent so any number of
    /// segment-set changes inside one debounce window cost one task.
    merge_check_armed: std::sync::atomic::AtomicBool,
    /// #871 — count of segment-set change events (flush published a
    /// segment, merge applied, tombstone-only segment persisted). The
    /// debounced check task compares this epoch before/after a pass to
    /// decide whether to run another cycle or quiesce.
    merge_events: AtomicU64,
    /// #871 — once true, no further merge checks are ever scheduled.
    /// Set by [`Index::abort_background_tasks`] (SIGTERM shutdown and
    /// hand-driven test fixtures). Matches the old semantics where the
    /// aborted per-index tick task was never respawned.
    merge_scheduling_stopped: std::sync::atomic::AtomicBool,
    /// #871 — number of merge-policy evaluations actually run (passes
    /// that won the `merge_in_progress` flag and snapshotted the segment
    /// registry). Observability for the idle-cost contract: on an idle
    /// index this counter must stay flat — see
    /// `idle_index_schedules_no_merge_evaluations_without_segment_changes`.
    merge_evaluations: AtomicU64,
    /// Failed writes of `schema.json` during dynamic-mapping evolution.
    /// See [`Index::persist_evolved_schema`] (issue #204).
    schema_persist_failures: AtomicU64,
    /// #876 — documents a merge re-analysed instead of merging their
    /// postings. Merging is supposed to replay the inputs' posting lists,
    /// which costs nothing per document; this counts the documents that took
    /// the fallback (an input the preflight refused, or
    /// `XERJ_MERGE_FTS_REANALYZE=1`). An index whose merges are silently
    /// paying the old O(text) cost shows it here and nowhere else.
    /// `Arc` because the merge encode runs on the merge pool, off the caller.
    merge_fts_reanalysed_docs: Arc<AtomicU64>,
    /// Set for the pass that just finished when at least one selected
    /// batch was left unmerged because its estimated working set would
    /// cross the memory watermark (#1122). The debounced check retries;
    /// a pass that merges everything leaves this false.
    merge_batches_deferred: std::sync::atomic::AtomicBool,
}

/// Counts one `Index::refresh` that got past the test hold, on every exit.
#[cfg(any(test, feature = "refresh-test-hook"))]
struct TestRefreshFinished<'a>(&'a Index);

#[cfg(any(test, feature = "refresh-test-hook"))]
impl Drop for TestRefreshFinished<'_> {
    fn drop(&mut self) {
        self.0.test_refresh_finished.fetch_add(1, Ordering::Release);
    }
}

impl Index {
    /// Apply a WAL-consumer retention floor to this index's WAL shards, live.
    ///
    /// #320. Called by [`Engine`](crate::engine::Engine) immediately after
    /// every open/create, and again on every index when an operator changes
    /// `wal_tap.min_retained_generations` through `PUT /_xerj/wal_tap`. See
    /// [`xerj_storage::index_store::IndexStore::set_wal_min_retained_generations`]
    /// for why the open-time config value alone was not enough.
    pub fn set_wal_min_retained_generations(&self, n: u64) {
        self.store.set_wal_min_retained_generations(n);
    }

    /// The retention floor in force on each of this index's WAL shards.
    pub fn wal_min_retained_generations(&self) -> Vec<u64> {
        self.store.wal_min_retained_generations()
    }

    fn begin_hnsw_publication(&self) -> HnswPublicationGuard {
        HnswPublicationGuard::begin(
            &self.hnsw_publications_in_flight,
            &self.hnsw_publication_generation,
        )
    }

    async fn has_dense_vector_mapping(&self) -> bool {
        let schema = self.schema.read().await;
        !collect_dense_vector_fields(&schema.schema).is_empty()
    }

    /// Aggregate DashMap table capacities for the hydration families, in
    /// `SegmentCacheCategory` order.
    /// These are diagnostic table slots, separate from the refundable
    /// retained-payload/key budget.
    pub fn segment_hydration_cache_capacities(&self) -> [usize; CATEGORY_COUNT] {
        [
            self.stored_slices_cache.capacity(),
            self.dv_cache.capacity(),
            self.stored_value_cache.capacity(),
            self.sort_shadow_cache.capacity(),
            self.id_pos_cache.capacity(),
            self.row_seq_cache.capacity(),
            self.decoded_stored_cache.capacity(),
            self.fts_reader_cache.capacity(),
            self.vector_column_cache.capacity(),
        ]
    }

    #[cfg(test)]
    fn publication_test_point(&self, id: &str, point: PublicationTestPoint) {
        // Clone the callback while holding the hook registry lock, then invoke
        // it after releasing that lock. Test barriers may intentionally block.
        let hook = self.publication_test_hook.read().clone();
        if let Some(hook) = hook {
            hook(id, point);
        }
    }

    #[cfg(test)]
    fn set_publication_test_hook(&self, hook: Option<PublicationTestHook>) {
        *self.publication_test_hook.write() = hook;
    }

    #[cfg(test)]
    fn sync_prepublication_test_point(&self, id: &str) -> Result<()> {
        self.publication_test_point(id, PublicationTestPoint::SyncBeforeCollectionBegin);
        if id == "__fail_sync_before_publication" {
            return Err(EngineError::Common(
                xerj_common::XerjError::invalid_document_json(
                    "injected synchronous preparation failure",
                ),
            ));
        }
        Ok(())
    }

