    /// Create a new index at `data_dir/<name>`.
    pub fn create(
        name: IndexName,
        schema: Schema,
        config: &Config,
        data_dir: &Path,
    ) -> Result<Arc<Self>> {
        Self::create_with_settings(name, schema, Value::Null, config, data_dir)
    }

    /// Resolve the effective auto-flush thresholds `(docs, bytes)`.
    ///
    /// The byte budget is the PRIMARY driver (the memtable RAM ceiling a
    /// shard fills before draining to a segment); the doc count is a
    /// secondary sanity cap.  Both are runtime-overridable for cadence
    /// tuning / benchmarking, mirroring the existing `XERJ_MERGE_*` knobs:
    ///   `XERJ_FLUSH_SIZE_MB` — global in-memory byte budget (MiB).
    ///   `XERJ_FLUSH_DOCS`    — global doc-count sanity cap.
    /// Both are GLOBAL (across all ingest shards); the per-shard trigger
    /// is `value / shard_count` (see the flush scheduler).
    fn resolve_flush_thresholds(config_flush_size_mb: u64) -> (usize, usize) {
        let size_mb = std::env::var("XERJ_FLUSH_SIZE_MB")
            .ok()
            .and_then(|v| v.trim().parse::<u64>().ok())
            .filter(|&v| v > 0)
            .unwrap_or(config_flush_size_mb);
        let byte_threshold = (size_mb as usize).saturating_mul(1024 * 1024);
        let doc_threshold = std::env::var("XERJ_FLUSH_DOCS")
            .ok()
            .and_then(|v| v.trim().parse::<usize>().ok())
            .filter(|&v| v > 0)
            .unwrap_or(FLUSH_DOC_THRESHOLD_DEFAULT);
        (doc_threshold, byte_threshold)
    }

    /// Create a new index with explicit settings at `data_dir/<name>`.
    pub fn create_with_settings(
        name: IndexName,
        schema: Schema,
        settings: Value,
        config: &Config,
        data_dir: &Path,
    ) -> Result<Arc<Self>> {
        // Issue #204 — refuse an analysis block we would only pretend to
        // honour. `apply_settings` is total (it has to be: it also runs on the
        // open path), so an unresolvable tokenizer silently became `standard`
        // and an unresolvable filter was silently dropped — the index was then
        // built with an analyzer the caller never asked for and nothing in the
        // 200 response said so. Checked BEFORE the index directory is created
        // so a rejected create leaves nothing behind.
        let analysis_problems = AnalyzerRegistry::unsupported_analysis(&settings);
        if !analysis_problems.is_empty() {
            return Err(EngineError::Common(xerj_common::XerjError::config(
                format!(
                    "index [{}] cannot be created: xerj cannot honour this analysis \
                 configuration — {}",
                    name.as_str(),
                    analysis_problems.join("; ")
                ),
            )));
        }

        let index_dir = data_dir.join(name.as_str());
        // Defense-in-depth: IndexName::validate rejects '.', '..', separators,
        // and '..' substrings, so join cannot escape data_dir. The debug_assert
        // catches a regression in the validator during development.
        debug_assert!(
            index_dir.starts_with(data_dir),
            "IndexName validation regression: {index_dir:?} escaped {data_dir:?}"
        );
        std::fs::create_dir_all(&index_dir)?;

        let storage_mode = storage_mode_from_config(&config.storage, name.as_str())?;
        let store_config = store_config_from(
            config,
            wal_shards_override_from_settings(&settings),
            storage_mode,
        );
        let store = IndexStore::open(&index_dir, store_config)?;

        let managed = ManagedSchema {
            schema,
            dynamic: xerj_common::schema::DynamicMapping::Dynamic,
        };
        validate_embedding_identity(&index_dir, &managed.schema, &config.embedding, true, false)?;
        let effective_embedder = make_embedder_for_schema(&managed.schema, &config.embedding)?;

        // Doc count is a sanity cap only — the byte threshold is the primary
        // driver.  Historically this was 10 000, which forced flushes every ~8 MB
        // regardless of `flush_size_mb`, producing thousands of tiny segments on
        // log workloads.  Both are env-overridable — see resolve_flush_thresholds.
        let (flush_doc_threshold, flush_byte_threshold) =
            Self::resolve_flush_thresholds(config.storage.flush_size_mb);
        let flush_idle_secs = config.storage.flush_idle_secs;

        // Warn if >1 shard requested (we only support single-shard).
        if let Some(n) = settings
            .pointer("/index/number_of_shards")
            .and_then(Value::as_u64)
        {
            if n > 1 {
                tracing::warn!(
                    shards = n,
                    index = name.as_str(),
                    "xerj is single-shard; number_of_shards={} is ignored",
                    n
                );
            }
        }

        // Persist settings alongside schema.
        let settings_path = index_dir.join("settings.json");
        if !settings.is_null() {
            let bytes = serde_json::to_vec_pretty(&settings)?;
            write_file_atomic(&settings_path, &bytes)?;
        }

        // Persist the schema at create time so an explicit mapping
        // (PUT /{index} with a mappings body) survives a restart.
        // Historically schema.json was only written by put_mapping /
        // dynamic-field evolution, so a create-time mapping silently
        // degraded to ManagedSchema::dynamic() (empty) after reboot —
        // keyword FST routing, analyzers, and doc-values typing all
        // reverted to inference until a manual _mapping PUT.
        {
            let bytes = serde_json::to_vec_pretty(&managed)?;
            write_file_atomic(&index_dir.join("schema.json"), &bytes)?;
        }

        // Build analyzer registry, applying any custom analysis settings.
        // A NEW index always gets the canonical binding, and records that it
        // did — see `analysis_binding_for_open` (issue #204). #937: it also
        // honours a declared `default` analyzer on the SEGMENT paths from
        // birth, and records THAT too, so the first reopen cannot mistake it
        // for a pre-#937 index.
        write_analysis_binding_keys(
            &index_dir,
            &[("binding", "canonical"), ("segment_analyzers", "honored")],
        );
        // #965 — publish the index's small per-index meta files to the
        // bucket so a fresh node (no local dir) opens the same index:
        // settings, schema, the analyzer-binding marker, the embedding
        // identity and the raw ES mapping. Best-effort by design — a failed
        // PUT must not fail an index that already committed locally; the
        // next meta mutation re-publishes.
        publish_index_meta_objects(&store, &index_dir, name.as_str());
        let registry = Arc::new(build_registry_from_settings(&settings));

        info!(name = name.as_str(), "index created");
        let has_dates = managed
            .fields()
            .iter()
            .any(|f| matches!(f.field_type, FieldType::Date));
        let segment_hydration_budget = index_segment_hydration_budget(config);
        let (flush_admit_ms, flush_budget_ms) = configured_flush_timeouts_ms(config);
        let passage_chunk_fields_init = passage_chunk_fields_from_schema(&managed.schema);
        let date_field_scales_snapshot = date_field_scales(&managed.schema);
        // #392: kept back from the struct literal so the SQ8 handle setup at
        // the end of create can read the mapping without re-locking.
        let managed_schema_for_sq8 = managed.schema.clone();
        let index = Arc::new(Self {
            name,
            schema: Arc::new(RwLock::new(managed)),
            date_detection: AtomicBool::new(true),
            has_date_fields: AtomicBool::new(has_dates),
            date_format_exclusions: std::sync::RwLock::new(Arc::new(Default::default())),
            store,
            memtable: Arc::new(
                crate::memtable::ShardedFtsMemtable::with_registry_and_shards(
                    Arc::clone(&registry),
                    config.engine.ingest_shards,
                ),
            ),
            write_publication: crate::write_publication::WritePublicationCoordinator::new(),
            collection_publication: crate::collection_publication::CollectionPublication::new(),
            #[cfg(test)]
            publication_test_hook: Arc::new(parking_lot::RwLock::new(None)),
            #[cfg(test)]
            test_panic_after_merge_publish: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_fail_merge_before_apply: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_pause_merge_before_apply: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_merge_repoint_ready: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_hold_merge_encode: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_merge_encode_held: Arc::new(AtomicBool::new(false)),
            #[cfg(any(test, feature = "refresh-test-hook"))]
            test_pause_refresh: Arc::new(AtomicBool::new(false)),
            #[cfg(any(test, feature = "refresh-test-hook"))]
            test_refresh_paused: Arc::new(AtomicBool::new(false)),
            #[cfg(any(test, feature = "refresh-test-hook"))]
            test_refresh_finished: Arc::new(AtomicU64::new(0)),
