            embedder: Arc::new(RwLock::new(effective_embedder)),
            dv_cache: Arc::new(per_index_map()),
            sort_shadow_cache: Arc::new(per_index_map()),
            sort_shadow_fields: Arc::new(per_index_map()),
            date_field_scales: Arc::new(parking_lot::RwLock::new(Arc::new(
                date_field_scales_snapshot,
            ))),
            stored_slices_build_locks: Arc::new(per_index_map()),
            range_prefilter_cache: Arc::new(per_index_map()),
            id_pos_cache: Arc::new(per_index_map()),
            row_seq_cache: Arc::new(per_index_map()),
            stored_value_cache: Arc::new(per_index_map()),
            segment_cache_lifecycle: Arc::new(parking_lot::RwLock::new(())),
            segment_hydration_budget,
            stored_value_loads: Arc::new(per_index_map()),
            stored_value_load_semaphore: Arc::new(Semaphore::new(4)),
            stored_slices_cache: Arc::new(per_index_map()),
            decoded_stored_cache: Arc::new(per_index_map()),
            fts_reader_cache: Arc::new(per_index_map()),
            vector_column_cache: Arc::new(per_index_map()),
            shortcut_count_cache: Arc::new(per_index_map()),
            ghost_positions_cache: Arc::new(per_index_map()),
            regexp_expand_cache: Arc::new(per_index_map()),
            fast_date_cache: Arc::new(per_index_map()),
            fast_date_sorted_cache: Arc::new(per_index_map()),
            query_cache: Arc::new(per_index_map()),
            dataset_version: Arc::new(AtomicU64::new(0)),
            query_inflight: Arc::new(per_index_map()),
            metric_singleflight_coalesced: Arc::new(AtomicU64::new(0)),
            flush_signal: Arc::new(SyncFlushCoord::new()),
            external_versions: Arc::new(per_index_map()),
            merge_task: Arc::new(parking_lot::Mutex::new(None)),
            merge_check_armed: std::sync::atomic::AtomicBool::new(false),
            merge_events: AtomicU64::new(0),
            merge_scheduling_stopped: std::sync::atomic::AtomicBool::new(false),
            merge_evaluations: AtomicU64::new(0),
            merge_fts_reanalysed_docs: Arc::new(AtomicU64::new(0)),
            merge_batches_deferred: std::sync::atomic::AtomicBool::new(false),
            schema_persist_failures: AtomicU64::new(0),
            self_ref: std::sync::OnceLock::new(),
            cold_stored_warms: dashmap::DashMap::new(),
            cold_row_hydrations: AtomicU64::new(0),
        });
        let _ = index.self_ref.set(Arc::downgrade(&index));
        // #871 — event-driven merge scheduling: the store fires this hook on
        // every segment-set change (flush publication, merge application,
        // tombstone-only segment, orphan recovery) and the debounced check
        // task does the rest — see `request_merge_check`. No per-index tick
        // task: a fresh index has no segments and costs no timer and no
        // wakeup until its first flush publishes one.
        let merge_hook_index = Arc::downgrade(&index);
        index
            .store
            .set_segments_changed_hook(Some(Arc::new(move || {
                if let Some(idx) = merge_hook_index.upgrade() {
                    idx.on_segments_changed();
                }
            })));
        // #392: SQ8 code stores for scalar8 fields. A fresh index carries
        // no documents, so the walk converges (and publishes `ready`)
        // immediately; ingest maintains the store from the first write.
        for field in index.ensure_sq8_stores_from_schema(&managed_schema_for_sq8) {
            index.spawn_sq8_walk(&field);
        }
        Ok(index)
    }

    /// Open an existing index at `data_dir/<name>`.
    pub fn open(name: IndexName, config: &Config, data_dir: &Path) -> Result<Arc<Self>> {
        let index_dir = data_dir.join(name.as_str());

        if !index_dir.exists() {
            return Err(EngineError::Common(
                xerj_common::XerjError::index_not_found(name.as_str()),
            ));
        }

        // Load persisted settings BEFORE opening the store so the WAL shard
        // count (index.xerj_ingest_shards) matches what create used — the WAL
        // write layout (root vs s{N}/) and doc routing depend on it. An
        // unparseable settings.json is refused rather than defaulted to null:
        // the shard count, the custom analyzers and the index blocks all live
        // in here, so "null" is a different index, not a safe fallback.
        //
        // #965 — in object-store mode the meta objects are fetched FIRST, so
        // this open (which may be a fresh node whose local dir is empty)
        // sees the same settings/schema the creating node persisted. The
        // fetch is local-file-absent-only: a node that already has them
        // never pays a round trip.
        let storage_mode = storage_mode_from_config(&config.storage, name.as_str())?;
        if let xerj_storage::StorageMode::ObjectStore { backend, .. } = &storage_mode {
            for meta_name in INDEX_META_FILES {
                IndexStore::fetch_aux_object_from_backend(
                    backend,
                    meta_name,
                    &index_dir.join(meta_name),
                )?;
            }
        }
        let settings = load_settings(&index_dir)?.unwrap_or(Value::Null);
        let store_config = store_config_from(
            config,
            wal_shards_override_from_settings(&settings),
            storage_mode,
        );
        let store = IndexStore::open(&index_dir, store_config)?;

        // Estimate doc count from snapshot.
        let snap = store.snapshot();
        let segment_doc_count: u64 = snap.segments.iter().map(|s| s.doc_count).sum();
        drop(snap);

        // Load schema from disk if it exists. Absent → dynamic mapping (a
        // pre-persistence index legitimately has no schema.json). Present but
        // unparseable → refuse: the explicit mapping is gone and every field
        // type would be silently re-inferred from the next writes (#202).
        let mut schema = load_schema(&index_dir)?.unwrap_or_else(ManagedSchema::dynamic);
        // #889 — an index written before the `date_precision` flag existed has
        // no record of `date` vs `date_nanos` in `schema.json`, so every date
        // field would come back on the per-VALUE epoch guess #790 removed for
        // new indices. The raw ES mapping blob beside it still says which is
        // which; recover the flag from there before anything can read the
        // schema, so an upgraded data dir sorts and ranges the same way a
        // freshly created one does.
        backfill_date_precision_from_disk(&index_dir, &mut schema, name.as_str());
        validate_embedding_identity(
            &index_dir,
            &schema.schema,
            &config.embedding,
            false,
            segment_doc_count > 0 || store.version_map.live_count() > 0,
        )?;
        let effective_embedder = make_embedder_for_schema(&schema.schema, &config.embedding)?;

        // `settings` was loaded above (before the store was opened) so the WAL
        // shard count, the analyzer registry, and WAL replay all agree.

        // Build analyzer registry from persisted settings so WAL replay uses
        // the same custom analyzers (synonyms, ngrams, etc.) that were active
        // when the documents were originally indexed — INCLUDING which
        // `analysis` spelling was in force when they were written, which is
        // not necessarily the one this build resolves at create time
        // (issue #204; see `analysis_binding_for_open`).
        let analysis_binding = analysis_binding_for_open(
            &index_dir,
            &settings,
            segment_doc_count > 0 || store.version_map.live_count() > 0,
        );
        let registry = Arc::new(build_registry_from_settings_with_binding(
            &settings,
            analysis_binding,
        ));
        // #937 — do this index's SEGMENT paths honour a declared `default`
        // analyzer? Decided once, recorded in the binding marker, stable for
        // the life of the index (see `segment_analyzer_binding_for_open`).
        let segment_default_analyzer_honored = segment_analyzer_binding_for_open(
            &index_dir,
            &registry,
            segment_doc_count > 0 || store.version_map.live_count() > 0,
        );
        let passage_scored_fields_at_open = passage_scored_vector_fields(&schema.schema);
        let mut wal_passage_chunk_fields = HashSet::new();

        // Replay WAL entries into the FTS memtable.  The IndexStore already
        // replays the WAL into its own storage memtable (for future flushes);
        // we do a second pass here to rebuild the BM25 in-memory index so that
        // queries against un-flushed documents work correctly after a restart.
        let memtable = {
            let mem = crate::memtable::ShardedFtsMemtable::with_registry_and_shards(
                Arc::clone(&registry),
                config.engine.ingest_shards,
            );
            let wal_dir = store.wal_dir();
            // Must use the sharded-aware discovery: with the 16-shard WAL
            // layout the entries live in wal/s{N}/, and a reader on the
            // root directory alone replays nothing — the FTS memtable then
            // reopens empty and every unflushed doc is unsearchable and
            // un-GETtable until the next flush (chaos_data_integrity).
            let mut replayed = 0usize;
            for replay_entry in xerj_storage::wal::replay_all_sorted(&wal_dir) {
                match replay_entry.entry {
                    WalEntry::Index { doc_id, source } => {
                        observe_passage_chunks_in_source(
                            &passage_scored_fields_at_open,
                            &source,
                            &mut wal_passage_chunk_fields,
                        );
                        // Replay idempotence (2026-07, S2): mirror of the
                        // storage-memtable rule in `IndexStore::replay_wal`.
                        // If the version map (segments rebuilt + storage
                        // replay, which ran inside `IndexStore::open`) shows
                        // this doc live and SEGMENT-resident at seq >= this
                        // op, the exact same (or a newer) version is already
                        // in a segment — the pre-restart shutdown flush
                        // persisted it while batch-6 delete-pinning kept its
                        // WAL shard.  Inserting it here created an equal-seq
                        // FTS-memtable duplicate that inflated term/count
                        // paths (counts saw both copies; hit lists dedup by
                        // _id which masked it in search results).
                        let already_persisted = match store.version_map.get(&doc_id) {
                            Some(e) => {
                                !e.deleted
                                    && e.seq_no >= replay_entry.seq_no
                                    && &*e.segment_id
                                        != xerj_storage::version_map::IN_MEMORY_SEGMENT_ID
                            }
                            None => false,
                        };
                        if !already_persisted {
                            mem.remove(&doc_id);
                            mem.insert(doc_id, &source, &schema.schema, replay_entry.seq_no);
                            replayed += 1;
                        }
                    }
                    WalEntry::Delete { doc_id } => {
                        mem.remove(&doc_id);
                        replayed += 1;
                    }
                    WalEntry::UpdateMapping { .. } => {}
                }
            }
            if replayed > 0 {
                info!(
                    name = name.as_str(),
                    replayed,
                    memtable_docs = mem.doc_count(),
                    "FTS memtable rebuilt from WAL"
                );
            }
            mem
        };

        let memtable_doc_count = memtable.doc_count() as u64;
        let total_doc_count = segment_doc_count + memtable_doc_count;

        // Conservative ghost init: at rest (no in-flight flushes) a live
        // count below the physical count means superseded copies exist
        // from a pre-restart history the WAL replay above cannot see.
        // Flag them so the delete-aware slow paths stay on — the exact
        // per-event tracking (`VersionMap::ghost_events`) only observes
        // events from this process lifetime onward.
        if (store.version_map.live_count() as u64) < total_doc_count {
            store.version_map.force_ghost_event();
        }

        // See create_with_settings — doc count is a sanity cap, byte threshold drives flushes.
        let (flush_doc_threshold, flush_byte_threshold) =
            Self::resolve_flush_thresholds(config.storage.flush_size_mb);
        let flush_idle_secs = config.storage.flush_idle_secs;

        // #392: kept back from the struct literal (which moves `schema`) so
        // the SQ8 handle setup at the end of open can read the mapping.
        let schema_for_sq8 = schema.schema.clone();

        // Try to reload a previously-persisted HNSW snapshot. If both
        // graph.bin and ids.json exist, validate, and the pinned field is
        // dense_vector-mapped (RC4 W2 item 16 — unmapped/legacy graphs are
        // refused at load), we skip the O(N log N) rebuild and load the
        // byte-identical graph that was running pre-restart.
        let dv_fields_at_open = collect_dense_vector_fields(&schema.schema);
        let loaded_hnsw = load_hnsw_artifacts_sync(&index_dir.join("hnsw"), &|f: &str| {
            dv_fields_at_open.iter().any(|df| df == f)
        });
        let initial_hnsw = loaded_hnsw.as_ref().map(|_| ()).is_some();
        let (
            hnsw_init,
            id_map_init,
            id_rev_init,
            next_id_init,
            hnsw_field_init,
            hnsw_stale_init,
            persisted_passage_chunk_fields,
        ) = match loaded_hnsw {
            Some(l) => {
                // Freshness stamp check: the snapshot is flush-time, but
                // WAL replay never calls index_vectors — so a WAL-tail
                // UPDATE of an already-graphed doc leaves the graph
                // holding the pre-update vector while the
                // `id_map.len() == doc_count` coverage guard still
                // passes (len and count both unchanged). A stamp
                // mismatch therefore marks the graph stale: ingest keeps
                // maintaining it and the kNN query path stays on exact
                // brute force until the background stale rebuild
                // (spawned at the end of open — RC4 W2 item 17)
                // re-derives the WAL-tail divergence and clears the
                // flag. (The loader gate guarantees `field` is Some.)
                let stale = l.stale || l.seq_no.is_none_or(|stamp| stamp != store.current_seq_no());
                (
                    Some(l.graph),
                    l.id_map,
                    l.id_rev,
                    l.next_id,
                    l.field,
                    stale,
                    l.passage_chunk_fields,
                )
            }
            None => (None, HashMap::new(), HashMap::new(), 1, None, false, None),
        };
        // Item 8: seed the coverage-gate denominator from the persisted graph.
        // At flush time the graph covered every vector-bearing doc, so the
        // reloaded `id_map.len()` IS the vector-doc count. If the snapshot is
        // stale, `hnsw_stale` already forces brute regardless of this value.
        let vector_doc_count_init = id_map_init.len() as u64;
        let mut passage_chunk_fields_init = passage_chunk_fields_from_schema(&schema.schema);
        match persisted_passage_chunk_fields {
            Some(fields) => passage_chunk_fields_init.extend(fields),
            None if total_doc_count > 0 => {
                // A missing marker means the index predates the passage guard.
                // Its stored documents may contain chunks even when
                // dynamic:false kept `<target>_chunks` out of schema.json.
                // Refuse semantic ANN for every semantic target rather than
                // infer safety from incomplete metadata.
                passage_chunk_fields_init.extend(passage_scored_fields_at_open.iter().cloned());
            }
            None => {}
        }
        passage_chunk_fields_init.extend(wal_passage_chunk_fields);
        if initial_hnsw {
            info!(
                name = name.as_str(),
                field = hnsw_field_init.as_deref().unwrap_or("<legacy>"),
                stale = hnsw_stale_init,
                "HNSW reloaded from disk"
            );
        }

        info!(
            name = name.as_str(),
            doc_count = total_doc_count,
            "index opened"
        );
        let has_dates = schema
            .fields()
            .iter()
            .any(|f| matches!(f.field_type, FieldType::Date));
        let segment_hydration_budget = index_segment_hydration_budget(config);
        let (flush_admit_ms, flush_budget_ms) = configured_flush_timeouts_ms(config);
        let date_field_scales_snapshot = date_field_scales(&schema.schema);
        let index = Arc::new(Self {
            name,
            schema: Arc::new(RwLock::new(schema)),
            date_detection: AtomicBool::new(true),
            has_date_fields: AtomicBool::new(has_dates),
            date_format_exclusions: std::sync::RwLock::new(Arc::new(Default::default())),
            max_concurrent_queries: Arc::new(Semaphore::new(64)),
            #[cfg(test)]
            test_scan_checkpoint_delay_ms: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_scan_checkpoint_count: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_scan_checkpoint_gate: Arc::new(tokio::sync::Mutex::new(())),
            #[cfg(test)]
            test_scan_checkpoint_parked: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_scan_clock: Arc::new(std::sync::Mutex::new(None)),
            #[cfg(test)]
            test_ann_passage_guard_pause: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_ann_passage_guard_ready: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_hnsw_save_passage_snapshot_pause: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_hnsw_save_passage_snapshot_ready: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_stored_value_load_delay_ms: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_stored_value_load_count: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_stored_value_load_pause_before_publish: Arc::new(
                std::sync::atomic::AtomicBool::new(false),
            ),
            #[cfg(test)]
            test_stored_value_load_ready_to_publish: Arc::new(std::sync::atomic::AtomicBool::new(
                false,
            )),
            #[cfg(test)]
            test_segment_cache_publish_pause_mask: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_segment_cache_publish_ready_mask: Arc::new(AtomicU64::new(0)),
            enrichments: Arc::new(RwLock::new(HashMap::new())),
            store,
            memtable: Arc::new(memtable),
            write_publication: crate::write_publication::WritePublicationCoordinator::new(),
            collection_publication: crate::collection_publication::CollectionPublication::new(),
            #[cfg(test)]
            publication_test_hook: Arc::new(parking_lot::RwLock::new(None)),
            #[cfg(test)]
            test_panic_after_merge_publish: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_fail_merge_before_apply: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_pause_merge_before_apply: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_merge_repoint_ready: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_hold_merge_encode: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_merge_encode_held: Arc::new(AtomicBool::new(false)),
            #[cfg(any(test, feature = "refresh-test-hook"))]
            test_pause_refresh: Arc::new(AtomicBool::new(false)),
            #[cfg(any(test, feature = "refresh-test-hook"))]
            test_refresh_paused: Arc::new(AtomicBool::new(false)),
            #[cfg(any(test, feature = "refresh-test-hook"))]
            test_refresh_finished: Arc::new(AtomicU64::new(0)),
            #[cfg(test)]
            test_pause_search_after_capture: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_search_capture_parked: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_pause_knn_after_capture: Arc::new(AtomicBool::new(false)),
            #[cfg(test)]
            test_knn_capture_parked: Arc::new(AtomicBool::new(false)),
            doc_count: Arc::new(AtomicU64::new(total_doc_count)),
            noop_update_count: Arc::new(AtomicU64::new(0)),
            request_cache_seen: Arc::new(RwLock::new(RequestCacheSeen::new(65_536))),
            request_cache_hits: Arc::new(AtomicU64::new(0)),
            request_cache_misses: Arc::new(AtomicU64::new(0)),
            query_cache_hits: Arc::new(AtomicU64::new(0)),
            query_cache_misses: Arc::new(AtomicU64::new(0)),
            registry,
            segment_default_analyzer_honored,
            analysis_binding,
            data_dir: index_dir,
            flush_doc_threshold,
            flush_byte_threshold,
            flush_idle_secs,
            idle_probe_fingerprint: std::sync::atomic::AtomicU64::new(0),
            idle_probe_at_ms: std::sync::atomic::AtomicU64::new(0),
            settings: Arc::new(RwLock::new(settings)),
            schema_hash_cache: Arc::new(std::sync::atomic::AtomicU64::new(0)),
            schema_hash_epoch: Arc::new(AtomicU64::new(0)),
            last_flush_doc_count: Arc::new(AtomicU64::new(0)),
            hnsw: Arc::new(RwLock::new(hnsw_init)),
            hnsw_id_map: Arc::new(RwLock::new(id_map_init)),
            hnsw_id_rev: Arc::new(RwLock::new(id_rev_init)),
            hnsw_next_id: Arc::new(AtomicU64::new(next_id_init)),
            vector_doc_count: Arc::new(AtomicU64::new(vector_doc_count_init)),
            hnsw_publications_in_flight: Arc::new(AtomicU64::new(0)),
            hnsw_publication_generation: Arc::new(AtomicU64::new(0)),
            hnsw_field: Arc::new(std::sync::RwLock::new(hnsw_field_init)),
            passage_chunk_fields: Arc::new(std::sync::RwLock::new(passage_chunk_fields_init)),
            hnsw_stale: Arc::new(std::sync::atomic::AtomicBool::new(hnsw_stale_init)),
            hnsw_rebuilding: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            hnsw_rebuild_task: Arc::new(parking_lot::Mutex::new(None)),
            sq8_stores: Arc::new(parking_lot::RwLock::new(HashMap::new())),
            metric_query_count: Arc::new(AtomicU64::new(0)),
            metric_query_total_ms: Arc::new(AtomicU64::new(0)),
            metric_index_count: Arc::new(AtomicU64::new(0)),
            metric_index_total_ms: Arc::new(AtomicU64::new(0)),
            metric_get_count: Arc::new(AtomicU64::new(0)),
            metric_get_total_ms: Arc::new(AtomicU64::new(0)),
            metric_get_exists_count: Arc::new(AtomicU64::new(0)),
            metric_get_missing_count: Arc::new(AtomicU64::new(0)),
            flush_sema: Arc::new(tokio::sync::Semaphore::new(
                config.engine.ingest_shards.max(4),
            )),
            flush_admit_timeout_ms: AtomicU64::new(flush_admit_ms),
            flush_timeout_ms: AtomicU64::new(flush_budget_ms),
            merge_in_progress: Arc::new(std::sync::atomic::AtomicBool::new(false)),
            merge_config: config.merge.clone(),
            compression_config: config.compression.clone(),
            embedding_config: config.embedding.clone(),
            max_fields_per_index: config.limits.max_fields_per_index,
            max_result_window: config.limits.max_result_window,
            embedder: Arc::new(RwLock::new(effective_embedder)),
            dv_cache: Arc::new(per_index_map()),
            sort_shadow_cache: Arc::new(per_index_map()),
            sort_shadow_fields: Arc::new(per_index_map()),
            date_field_scales: Arc::new(parking_lot::RwLock::new(Arc::new(
                date_field_scales_snapshot,
            ))),
            stored_slices_build_locks: Arc::new(per_index_map()),
            range_prefilter_cache: Arc::new(per_index_map()),
            id_pos_cache: Arc::new(per_index_map()),
            row_seq_cache: Arc::new(per_index_map()),
            stored_value_cache: Arc::new(per_index_map()),
            segment_cache_lifecycle: Arc::new(parking_lot::RwLock::new(())),
            segment_hydration_budget,
            stored_value_loads: Arc::new(per_index_map()),
            stored_value_load_semaphore: Arc::new(Semaphore::new(4)),
            stored_slices_cache: Arc::new(per_index_map()),
            decoded_stored_cache: Arc::new(per_index_map()),
            fts_reader_cache: Arc::new(per_index_map()),
            vector_column_cache: Arc::new(per_index_map()),
            shortcut_count_cache: Arc::new(per_index_map()),
            ghost_positions_cache: Arc::new(per_index_map()),
            regexp_expand_cache: Arc::new(per_index_map()),
            fast_date_cache: Arc::new(per_index_map()),
            fast_date_sorted_cache: Arc::new(per_index_map()),
            query_cache: Arc::new(per_index_map()),
            dataset_version: Arc::new(AtomicU64::new(0)),
            query_inflight: Arc::new(per_index_map()),
            metric_singleflight_coalesced: Arc::new(AtomicU64::new(0)),
            flush_signal: Arc::new(SyncFlushCoord::new()),
            external_versions: Arc::new(per_index_map()),
            merge_task: Arc::new(parking_lot::Mutex::new(None)),
            merge_check_armed: std::sync::atomic::AtomicBool::new(false),
            merge_events: AtomicU64::new(0),
            merge_scheduling_stopped: std::sync::atomic::AtomicBool::new(false),
            merge_evaluations: AtomicU64::new(0),
            merge_fts_reanalysed_docs: Arc::new(AtomicU64::new(0)),
            merge_batches_deferred: std::sync::atomic::AtomicBool::new(false),
            schema_persist_failures: AtomicU64::new(0),
            self_ref: std::sync::OnceLock::new(),
            cold_stored_warms: dashmap::DashMap::new(),
            cold_row_hydrations: AtomicU64::new(0),
        });
        let _ = index.self_ref.set(Arc::downgrade(&index));
        // #871 — event-driven merge scheduling (see `Index::create` and
        // `request_merge_check`): wire the store's segments-changed hook.
        let merge_hook_index = Arc::downgrade(&index);
        index
            .store
            .set_segments_changed_hook(Some(Arc::new(move || {
                if let Some(idx) = merge_hook_index.upgrade() {
                    idx.on_segments_changed();
                }
            })));
        // An opened index can carry pre-existing merge debt — a crash
        // mid-cascade, or merge config lowered since the segments were
        // written — that no future event would pay off on a read-only
        // index. Schedule one debounced check now; it quiesces after a
        // single evaluation when there is nothing to do.
        index.request_merge_check();
        // RC4 W2 item 17: a flush-time-stale HNSW snapshot used to stay
        // stale for the rest of the process lifetime (ingest kept paying
        // full graph-maintenance cost while the ANN path never served).
        // Heal it in the background from the authoritative doc set.
        index.spawn_hnsw_rebuild_if_stale();
        // #392: create SQ8 code-store handles for any scalar8 field and
        // make them serving-ready from the authoritative doc set (WAL
        // replay never re-runs vector indexing).
        for field in index.ensure_sq8_stores_from_schema(&schema_for_sq8) {
            index.spawn_sq8_walk(&field);
        }
        Ok(index)
    }

    // ── Document operations ───────────────────────────────────────────────────

    /// Index a document, assigning an ID if one is not provided.
    ///
    /// If `if_seq_no` and `if_primary_term` are both provided, this performs an
    /// optimistic concurrency check: the document's current `seq_no` must match
    /// `if_seq_no`, otherwise a `VersionConflict` error is returned.
    pub async fn index_document(&self, id: Option<String>, source: Value) -> Result<IndexResponse> {
        self.index_document_with_version(id, source, None, None)
            .await
    }

    /// Index with caller-supplied `version` / `version_type`. Supports
    /// `external` (caller version MUST be strictly greater than
    /// current) and `external_gte` (caller version >= current).
    pub async fn index_document_external(
        &self,
        id: Option<String>,
        source: Value,
        version: u64,
        version_type: &str,
    ) -> Result<IndexResponse> {
        let doc_id = id.unwrap_or_else(|| Uuid::new_v4().to_string());
        let strict = version_type != "external_gte";
        self.index_document_with_version_inner_guarded(
            Some(doc_id),
            source,
            None,
            None,
            false,
            None,
            false,
            Some((version, strict)),
        )
        .await
    }

    /// Index a document with optional optimistic concurrency control.
    pub async fn index_document_with_version(
        &self,
        id: Option<String>,
        source: Value,
        if_seq_no: Option<u64>,
        if_primary_term: Option<u64>,
    ) -> Result<IndexResponse> {
        self.index_document_with_version_inner(id, source, if_seq_no, if_primary_term, false)
            .await
    }

    pub(crate) async fn index_document_prepared(
        &self,
        id: Option<String>,
        source: Value,
    ) -> Result<IndexResponse> {
        #[cfg(test)]
        if crate::bulk::semantic_lifecycle_hook(
            self.name.as_str(),
            crate::bulk::SemanticLifecyclePoint::PublicationInside,
        ) == crate::bulk::SemanticLifecycleFault::Publication
        {
            return Err(crate::EngineError::Common(
                xerj_common::XerjError::invalid_query(
                    "injected semantic publication failure inside index_document_prepared",
                ),
            ));
        }
        self.index_document_with_version_inner(id, source, None, None, true)
            .await
    }

    /// Index several documents, sharing ONE embedding pass across the batch.
    ///
    /// Publication is per document and identical to [`Index::index_document`];
    /// the only difference is that `semantic_text` auto-embedding runs once for
    /// the whole batch through `apply_semantic_embeddings_batch` — the same
    /// entry the HTTP `_bulk` path uses — instead of once per document. With an
    /// active backend that is one inference call per `onnx_scheduling_window`
    /// of passages rather than one call per document (a single document whose
    /// own passages exceed the window is still admitted whole, so it keeps its
    /// own call — see `semantic_embedding_window_end`).
    ///
    /// The returned vector is position-aligned with `docs`: a document whose
    /// embedding or publication failed carries its own error and does not
    /// affect its neighbours.
    pub async fn index_documents_batched(
        &self,
        docs: Vec<(Option<String>, Value)>,
    ) -> Vec<Result<IndexResponse>> {
        if docs.is_empty() {
            return Vec::new();
        }
        let (ids, sources): (Vec<Option<String>>, Vec<Value>) = docs.into_iter().unzip();
        let prepared = self.apply_semantic_embeddings_batch(sources).await;
        let mut responses = Vec::with_capacity(ids.len());
        for (id, prepared_source) in ids.into_iter().zip(prepared) {
            responses.push(match prepared_source {
                Ok(source) => self.index_document_prepared(id, source).await,
                Err(e) => Err(e),
            });
        }
        responses
    }

    async fn index_document_with_version_inner(
        &self,
        id: Option<String>,
        source: Value,
        if_seq_no: Option<u64>,
        if_primary_term: Option<u64>,
        semantic_embeddings_prepared: bool,
    ) -> Result<IndexResponse> {
        self.index_document_with_version_inner_guarded(
            id,
            source,
            if_seq_no,
            if_primary_term,
            semantic_embeddings_prepared,
            None,
            false,
            None,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    async fn index_document_with_version_inner_guarded(
        &self,
        id: Option<String>,
        source: Value,
        if_seq_no: Option<u64>,
        if_primary_term: Option<u64>,
        semantic_embeddings_prepared: bool,
        publication_guard: Option<crate::write_publication::WritePublicationGuard>,
        create_only: bool,
        external_version: Option<(u64, bool)>,
    ) -> Result<IndexResponse> {
        // Check write block.
        if let Some(block) = self.write_block_reason().await {
            return Err(EngineError::Common(xerj_common::XerjError::index_blocked(
                self.name.as_str(),
                block,
            )));
        }
        // Default-format date validation — before any durable write so a
        // rejected doc leaves no WAL/memtable trace.
        self.validate_default_format_dates(&source).await?;
        // Process-wide admission: disk flood-stage block (item 3) + parent
        // memory circuit breaker (item 1). Fires before any per-index work.
        self.governor_write_gate()?;
        // Bodies that arrived already parsed (in-process callers, a pipeline
        // rewrite) still have to be refused before semantic embedding and
        // `analyze_doc`. HTTP `PUT`/`POST /_doc` and bulk NDJSON are refused
        // on the raw bytes earlier.
        if let Some(seen) =
            xerj_common::document_limit::json_value_exceeds_indexed_document_limit(&source)
        {
            return Err(EngineError::Common(
                xerj_common::XerjError::invalid_document_json(
                    xerj_common::document_limit::indexed_document_refusal_at_least(seen),
                ),
            ));
        }
        let index_start = std::time::Instant::now();
        let doc_id = id.unwrap_or_else(|| Uuid::new_v4().to_string());

        // `index.default_pipeline` is resolved and executed at the API layer
        // (xerj-api es_compat::resolve_effective_pipeline) before the document
        // reaches the engine, so no pipeline handling is needed here.

        // Auto-embed `semantic_text` fields: vectorise the field's text into
        // its companion vector field (`<field>_vector`) so it becomes
        // kNN-searchable. Runs before copy_to / storage so the derived vector
        // is part of `_source` and gets picked up by HNSW indexing below.
        let source = if semantic_embeddings_prepared {
            source
        } else {
            self.apply_semantic_embeddings(source).await?
        };

        // Apply copy_to: expand the source by copying field values to their target fields.
        let source = {
            let schema_guard = self.schema.read().await;
            apply_copy_to(&source, &schema_guard.schema)
        };

        // Preprocessing above is independent and can run concurrently.
        // Everything from CAS/liveness through WAL, VM, FTS, HNSW, and the
        // response is one exact per-document publication interval.
        let _publication_guard = match publication_guard {
            Some(guard) => guard,
            None => self.write_publication.lock(doc_id.clone()).await,
        };
        #[cfg(test)]
        self.publication_test_point(&doc_id, PublicationTestPoint::Acquired);

        // Optimistic concurrency check: honour `if_seq_no` whenever it
        // is supplied. ES requires `if_primary_term` alongside it, but
        // xerj is single-shard with primary_term=1, so we treat a
        // missing `if_primary_term` as equivalent to `1` rather than
        // silently skipping the check. Clients that pass a garbled
        // `if_primary_term` (e.g. an unresolved YAML variable) still
        // get the expected seq_no comparison.
        let _ = if_primary_term;
        if let Some(expected_seq) = if_seq_no {
            if let Some(entry) = self.store.version_map.get(&doc_id) {
                if entry.seq_no != expected_seq {
                    return Err(EngineError::Common(
                        xerj_common::XerjError::version_conflict(
                            &doc_id,
                            expected_seq,
                            entry.seq_no,
                        ),
                    ));
                }
            } else {
                // Document doesn't exist but caller expects a specific seq_no.
                return Err(EngineError::Common(
                    xerj_common::XerjError::version_conflict(&doc_id, expected_seq, 0),
                ));
            }
        }

        if create_only {
            let exists = self
                .store
                .version_map
                .get(&doc_id)
                .map(|entry| !entry.deleted)
                .unwrap_or(false)
                || self.memtable.contains(&doc_id);
            if exists {
                return Err(EngineError::Common(
                    xerj_common::XerjError::version_conflict(&doc_id, 0, 1),
                ));
            }
        }

        if let Some((version, strict)) = external_version {
            if let Some(existing) = self.external_versions.get(&doc_id) {
                let current = *existing;
                let valid = if strict {
                    version > current
                } else {
                    version >= current
                };
                if !valid {
                    return Err(EngineError::Common(
                        xerj_common::XerjError::version_conflict(&doc_id, version, current),
                    ));
                }
            }
        }

        // From the first authoritative visibility change through HNSW
        // publication, ANN must not observe the old graph as complete.
        let _hnsw_publication = self
            .has_dense_vector_mapping()
            .await
            .then(|| self.begin_hnsw_publication());
        // Publish the passage-ANN guard before this source can become visible
        // through the WAL/version map or FTS memtable. A concurrent semantic
        // query checks the guard both before and after ANN candidate work, so
        // it either linearizes before this write or falls back to the exact
        // passage scorer.
        self.observe_passage_chunks(std::iter::once(&source)).await;

        // Invalidate the response cache only after admission and CAS succeed.
        self.dataset_version.fetch_add(1, Ordering::Release);

        // Detect whether this is an overwrite (existing doc) vs a new
        // insert BEFORE writing to storage. Used to set the response
        // `result` field to "updated" / "created" per ES semantics so
        // HTTP-layer 200/201 bulk status mapping works. A tombstoned doc
        // counts as NOT existing: ES reports re-index-after-delete as
        // `created`/201 (while its `_version` still continues from the
        // tombstone).
        let existed_before = self
            .store
            .version_map
            .get(&doc_id)
            .map(|e| !e.deleted)
            .unwrap_or(false);

        // Take the FTS schema read guard BEFORE entering the publication
        // interval. Parked here — behind schema evolution's write lock, which
        // `evolve_schema_from_doc` takes every ~100 docs or on any new field —
        // this was the interval's ONLY suspension point, so a dropped PUT
        // future (a client disconnect) landed *inside* begin()..commit() and
        // left the guard Pending, which poisons the index for good. Acquired
        // out here the interval below contains no `.await` at all and cannot
        // be cancelled part-way. The guard is released immediately after the
        // memtable write, before `evolve_schema_from_doc` wants it for writing.
        let schema_guard = self.schema.read().await;

        // Enter only after validation/preparation, immediately before the
        // first authoritative visibility mutation.
        let mut collection_publication = self
            .collection_publication
            .begin()
            .map_err(|_| collection_publication_interrupted())?;
        // Write to storage WAL. A failure here happens before any visibility
        // mutation, so cancel the publication rather than dropping the guard
        // Pending: a transient storage error must fail this request alone, not
        // brick the index until the process restarts.
        #[cfg(test)]
        if let Err(e) = self.wal_admission_test_fault(&doc_id) {
            collection_publication.cancel();
            drop(collection_publication);
            self.collection_publication.handoff_to_readers().await;
            return Err(e.into());
        }
        let seq_no = match self.store.index(&doc_id, source.clone()) {
            Ok(seq_no) => seq_no,
            Err(e) => {
                collection_publication.cancel();
                drop(collection_publication);
                self.collection_publication.handoff_to_readers().await;
                return Err(e.into());
            }
        };
        // External-version admission becomes durable only after the WAL write
        // succeeds. Publishing it before `store.index` would poison an exact
        // retry when WAL append fails.
        if let Some((external_version, _)) = external_version {
            self.external_versions
                .insert(doc_id.clone(), external_version);
        }
        #[cfg(test)]
        self.publication_test_point(&doc_id, PublicationTestPoint::AfterWalVersionMap);

        // Write to FTS memtable, then release the schema read guard so schema
        // evolution below can take it for writing.
        {
            let mem = &*self.memtable;
            mem.remove(&doc_id);
            mem.insert(doc_id.clone(), &source, &schema_guard.schema, seq_no);
        }
        drop(schema_guard);
        #[cfg(test)]
        self.publication_test_point(&doc_id, PublicationTestPoint::AfterFts);

        // Bump counter (flush thresholds / stats bookkeeping only — NOT the
        // response `_version`, which is per-doc).
        self.doc_count.fetch_add(1, Ordering::Relaxed);

        // Real per-doc `_version`: `store.index` just recorded this write
        // in the version map (1 on first index, +1 per overwrite, deletes
        // included). The previous code reported the index-global doc_count
        // here, so any write to doc B inflated the next reported version
        // of doc A (live-verified: three PUTs to the same id after other
        // writes reported 4, 5, 6).
        let version = self
            .store
            .version_map
            .get(&doc_id)
            .map(|e| e.version)
            .unwrap_or(1);
        collection_publication.commit();
        drop(collection_publication);
        // The next document's bracket must not open until a search parked on
        // this one has validated its capture (#1761). No shard lock is held.
        self.collection_publication.handoff_to_readers().await;
        // Auto-evolve schema for new fields.
        // Fast path: skip the schema read lock every doc when schema is stable.
        // We cache a hash of the document field keys and only re-check schema
        // evolution every 100 docs (or when field keys change). The hash
        // walks NESTED field names too, not just the top-level ones (see
        // `hash_all_field_names`) -- a document whose top-level key set is
        // unchanged but whose nested shape changed (e.g. metadata.kind on
        // one document, metadata.project on the next) must still produce a
        // different hash, or this throttle would silently suppress the
        // evolve call that the newly-nested key needs, for up to 100
        // documents -- exactly the failure mode the recursive dynamic-
        // mapping fix (`merge_dynamic_children_into`) exists to close, one
        // layer further up the call chain.
        let should_evolve = {
            let current_count = self.doc_count.load(Ordering::Relaxed);
            let last_epoch = self.schema_hash_epoch.load(Ordering::Relaxed);
            let mut h: u64 = 0xcbf29ce484222325;
            hash_all_field_names(&source, &mut h);
            let cached = self.schema_hash_cache.load(Ordering::Relaxed);
            if cached != h {
                // Field set changed — must evolve and update cache.
                self.schema_hash_cache.store(h, Ordering::Relaxed);
                self.schema_hash_epoch
                    .store(current_count, Ordering::Relaxed);
                true
            } else {
                // Same field set — only re-check every 100 docs.
                current_count.saturating_sub(last_epoch) >= 100
            }
        };
        if should_evolve {
            self.evolve_schema_from_doc(&source).await;
        }

        // Auto-detect log format on the first few documents and log it.
        let current_count = self.doc_count.load(Ordering::Relaxed);
        if current_count <= 5 {
            if let Some(fmt) = detect_log_format(&source) {
                debug!(
                    index = self.name.as_str(),
                    doc_count = current_count,
                    format = ?fmt,
                    "auto-detected log format"
                );
            }
        }

        // Index any vector fields into the HNSW index.
        self.index_vectors(&doc_id, &source).await;
        #[cfg(test)]
        self.publication_test_point(&doc_id, PublicationTestPoint::AfterHnsw);

        // Trigger a background flush if memtable exceeds size or doc-count threshold.
        self.maybe_spawn_flush().await;

        // Record indexing metrics.
        let index_elapsed_ms = index_start.elapsed().as_millis() as u64;
        self.metric_index_count.fetch_add(1, Ordering::Relaxed);
        self.metric_index_total_ms
            .fetch_add(index_elapsed_ms, Ordering::Relaxed);
        // RC4 W4 item 2: end-to-end latency of this single-document index call.
        if let Some(m) = crate::engine_metrics() {
            m.observe_index(index_elapsed_ms as f64 / 1000.0);
        }

        debug!(doc_id = doc_id.as_str(), seq_no, "document indexed");

        #[cfg(test)]
        self.publication_test_point(&doc_id, PublicationTestPoint::BeforeRelease);
        Ok(IndexResponse {
            id: doc_id,
            seq_no,
            version: external_version
                .map(|(version, _)| version)
                .unwrap_or(version),
            result: if existed_before {
                "updated".to_string()
            } else {
                "created".to_string()
            },
        })
    }

    /// Batch index multiple documents using the turbo pipeline.
    ///
    /// Turbo mode achieves higher throughput than calling [`index_document`]
    /// in a loop by:
    ///
    /// 1. **Parallel tokenisation** — all documents in the batch are tokenised
    ///    concurrently via Rayon before any lock is acquired.
    /// 2. **Single lock acquisition** — the FTS memtable write lock is held for
    ///    the entire batch rather than once per document.
    /// 3. **Amortised WAL overhead** — WAL entries are written sequentially
    ///    inside the lock, but the expensive `fsync` cycle is paid only once for
    ///    the batch (as the underlying WAL writer is in `Batched` or `Async` mode).
    ///
    /// # Opt-in
    ///
    /// This method is called by the `/v1/indices/{name}/turbo-ingest` endpoint
    /// and by the standard `_bulk` path when the `X-Turbo: true` request header
    /// is present.
    ///
    /// # Trade-offs
    ///
    /// - When `fast_analyzer` is `true`, stemming and stopword removal are
    ///   skipped, which reduces search recall slightly.
    /// - Documents within the same batch are processed together; partial
    ///   failures are collected and returned rather than aborting the batch.
    pub async fn index_batch_turbo(
        &self,
        docs: Vec<(String, Value)>,
        parallel: bool,
        _fast_analyzer: bool,
    ) -> Result<Vec<IndexResponse>> {
        use crate::turbo_ingest::TurboIngestPipeline;

        if docs.is_empty() {
            return Ok(Vec::new());
        }

        if let Some(block) = self.write_block_reason().await {
            return Err(EngineError::Common(xerj_common::XerjError::index_blocked(
                self.name.as_str(),
                block,
            )));
        }
        // Process-wide admission: disk flood-stage block (item 3) + parent
        // memory circuit breaker (item 1). Fires before any per-index work.
        self.governor_write_gate()?;

        // ── Back-pressure ─────────────────────────────────────────────────
        // Reject the batch with 429 ResourceExhausted if the memtable is
        // already larger than 2× the flush byte threshold.  The previous
        // behaviour — accept-then-buffer-in-memory — caused xerj to OOM
        // under sustained bulk load because flushes could not keep up with
        // incoming writes.  Returning 429 lets upstream clients slow down
        // before the process dies.  The threshold is 2× so transient spikes
        // above the flush target don't trip back-pressure immediately.
        //
        // The check is a quick read under the memtable read-lock; no heavy
        // work is done before we decide to reject.
        //
        // V4 M4: soft back-pressure with bounded yield.
        //
        // When the memtable crosses 1.5 × threshold, we DON'T 429 the
        // client immediately — we kick a flush and yield to the tokio
        // scheduler for a few short naps.  If the background flush
        // drains enough memory within ~250 ms, the write proceeds;
        // otherwise we finally return 429.
        //
        // This eliminates the "200 k-docs/s burst → 63 dropped batches"
        // observed in the SIEM battle — the client hits a brief stall
        // instead of a hard reject, and the existing ingest driver's
        // retry logic isn't needed.
        let hard_block = self.flush_byte_threshold.saturating_mul(3);
        let soft_block = self.flush_byte_threshold.saturating_mul(2);
        {
            let mem_bytes = self.memtable.size_bytes();
            if mem_bytes >= soft_block {
                self.maybe_spawn_flush().await;
                // Block up to 30 s wall-clock until the memtable drains.
                // Pre-fix: 10 × 5 ms then error out — too short for a
                // sustained bulk-ingest workload where a flush of a
                // 512 MB segment takes 250 ms-2 s.  See
                // `2026-04-25T21-50-00_ingest_perf_regression_zstd19.md`.
                let bp_start = std::time::Instant::now();
                let bp_deadline = std::time::Duration::from_secs(30);
                while self.memtable.size_bytes() >= hard_block {
                    if bp_start.elapsed() >= bp_deadline {
                        self.maybe_spawn_flush().await;
                        return Err(EngineError::Common(
                            xerj_common::XerjError::resource_exhausted(format!(
                                "indexing back-pressure: memtable={}MB exceeds 3×flush_threshold={}MB on index [{}] after {}s wait — flusher may be stuck",
                                self.memtable.size_bytes() / (1024 * 1024),
                                self.flush_byte_threshold / (1024 * 1024),
                                self.name.as_str(),
                                bp_deadline.as_secs(),
                            )),
                        ));
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(25)).await;
                    if bp_start.elapsed().as_millis() % 200 < 25 {
                        self.maybe_spawn_flush().await;
                    }
                }
            }
        }

        let index_start = std::time::Instant::now();
        let batch_len = docs.len();

        // ── Step 1: parallel tokenisation (no locks held) ──────────────────
        //
        // Build the pipeline with a batch size equal to the full input so it
        // never auto-flushes mid-way through.
        let mut pipeline = TurboIngestPipeline::new(batch_len + 1, parallel);
        for (id, source) in docs {
            pipeline.push(id, source, Arc::<[u8]>::from([]));
        }
        // Flush collects all IngestResult values (with pre-computed tokens).
        let results = pipeline.flush();

        // ── Step 2: apply copy_to on all docs ─────────────────────────────
        // apply_copy_to deep-clones the document Map — on a 10-field nginx
        // schema with zero copy_to entries that's ~60 allocs per doc for
        // nothing.  Check the schema ONCE per batch and skip the clone
        // entirely on the common (no copy_to) path, wrapping the original
        // source in an Arc directly.
        let schema_guard = self.schema.read().await;
        let has_copy_to = schema_has_copy_to(&schema_guard.schema);
        let has_vector_mapping = !collect_dense_vector_fields(&schema_guard.schema).is_empty();
        let processed: Vec<_> = if has_copy_to {
            results
                .into_iter()
                .map(|r| {
                    let source =
                        std::sync::Arc::new(apply_copy_to(&r.source, &schema_guard.schema));
                    crate::turbo_ingest::IngestResult {
                        id: r.id,
                        tokens: r.tokens,
                        source,
                        // `copy_to` changed the parsed document.  Force WAL
                        // serialization from that value so live indexing and
                        // crash replay cannot observe different sources.
                        source_bytes: Arc::<[u8]>::from([]),
                    }
                })
                .collect()
        } else {
            // Zero-copy path — source is already an `Arc<Value>` from the
            // pipeline, no deep clone.
            results
        };
        drop(schema_guard);
        let _hnsw_publication = has_vector_mapping.then(|| self.begin_hnsw_publication());
        self.observe_passage_chunks(processed.iter().map(|ingest| ingest.source.as_ref()))
            .await;

        // ── Step 3+4: WAL append + FTS memtable insert under one lock ─────
        //
        // The engine memtable write lock spans BOTH the WAL append and
        // the FTS memtable push so that (a) the engine memtable and
        // the storage memtable (inside `wal_append_batch`) see docs
        // in identical order — flush relies on that for FTS-ordinal /
        // stored-section alignment — and (b) no other concurrent bulk
        // batch can race the drain-vs-push interleaving.
        //
        // A previous M5.0 attempt lifted the WAL out of this lock to
        // let concurrent clients pipeline.  It regressed throughput
        // because the two memtables DESYNCED (storage mem had the
        // docs a batch just pushed, engine mem still had fewer) and
        // the periodic flush would pick up a tiny storage drain and
        // a mismatched engine drain — producing 20 k-doc flush
        // segments where 150 k were expected, thrashing the flush
        // path and triggering back-pressure 429s.  Rolled back.
        let t3 = std::time::Instant::now();
        let wal_refs: Vec<(String, Arc<Value>)> = processed
            .iter()
            .map(|r| (r.id.clone(), Arc::clone(&r.source)))
            .collect();
        let copy_schema = if has_copy_to {
            Some(self.schema.read().await)
        } else {
            None
        };

        let mut collection_publication = self
            .collection_publication
            .begin()
            .map_err(|_| collection_publication_interrupted())?;
        let wal_t = std::time::Instant::now();
        let seq_nos = self.store.wal_append_batch(&wal_refs)?;
        #[cfg(test)]
        if let Some(first) = processed.first() {
            self.publication_test_point(&first.id, PublicationTestPoint::TurboAfterWalVersionMap);
        }
        // RC4 W4 item 2: WAL durability-write latency.
        if let Some(m) = crate::engine_metrics() {
            m.observe_wal_write(wal_t.elapsed().as_secs_f64());
        }
        let t3_dur = t3.elapsed();

        // ── M5.1 HOT PATH: one shard lock per BATCH ───────────────────────
        //
        // Pre-M5.1 we called `mem.insert_pretokenized_with_seq(...)` per
        // doc, which acquired the shard mutex TWICE per doc (once for
        // `remove`, once for `insert`).  For a 5 000-doc batch that's
        // 10 000 mutex acquisitions — high contention across 4
        // concurrent clients caused a 4× throughput regression (99 k →
        // 23 k docs/s).
        //
        // Now the bulk batch is routed to exactly ONE shard (by the
        // first doc_id's hash) and the shard lock is held for the
        // entire batch loop — so 4 concurrent clients routed to 4
        // different shards run in parallel with zero per-batch lock
        // churn.
        let t4 = std::time::Instant::now();
        let mut responses = Vec::with_capacity(batch_len);
        let shard_idx = if processed.is_empty() {
            0
        } else {
            // Use the instance method so routing matches the actual
            // configured shard count. The static `shard_for` is hardcoded
            // to assume 16 shards and panics on machines configured for
            // fewer (e.g. ingest_shards=2 on a 4-core box).
            self.memtable.shard_for_dynamic(&processed[0].id)
        };
        // Chunked insert — same read-under-write rationale as the raw path
        // (`index_batch_turbo_raw`): release the shard write lock between
        // chunks so a concurrent search stalls on a writing shard for at
        // most one chunk, not the whole batch.  `remove()` still precedes
        // each `insert_pretokenized_with_seq`, so overwrite semantics are
        // preserved regardless of the chunk boundary.
        {
            let mut base = 0usize;
            while base < batch_len {
                let end = (base + MEMTABLE_INSERT_CHUNK).min(batch_len);
                self.memtable.with_shard_mut(shard_idx, |mem| {
                    for i in base..end {
                        let ingest = &processed[i];
                        mem.remove(&ingest.id);
                        if let Some(schema) = copy_schema.as_ref() {
                            // copy_to created fields after the turbo pipeline
                            // emitted its (currently empty) token list. Analyze
                            // the transformed source so the target is searchable
                            // immediately, not only after flush/merge.
                            mem.insert(
                                ingest.id.clone(),
                                &ingest.source,
                                &schema.schema,
                                seq_nos[i],
                            );
                        } else {
                            mem.insert_pretokenized_with_seq(
                                seq_nos[i],
                                ingest.id.clone(),
                                Arc::clone(&ingest.source),
                                &ingest.tokens,
                            );
                        }

                        let version = self.doc_count.fetch_add(1, Ordering::Relaxed) + 1;

                        responses.push(IndexResponse {
                            id: ingest.id.clone(),
                            seq_no: seq_nos[i],
                            version,
                            result: "created".to_string(),
                        });
                    }
                });
                base = end;
            }
        }
        drop(copy_schema);
        collection_publication.commit();
        drop(collection_publication);
        self.collection_publication.handoff_to_readers().await;
        let t4_dur = t4.elapsed();

        if batch_len >= 1000 {
            tracing::debug!(
                batch_len,
                tokenize_ms = index_start.elapsed().as_millis() as u64
                    - t3_dur.as_millis() as u64
                    - t4_dur.as_millis() as u64,
                wal_ms = t3_dur.as_millis() as u64,
                memtable_ms = t4_dur.as_millis() as u64,
                "turbo batch complete"
            );
        }

        // ── Step 5: schema evolution + vector indexing (post-lock) ────────
        //
        // These were previously called PER DOC inside a `for ingest in
        // &processed` loop = 10 000 async state-machine steps + 10 000
        // `RwLock::read_acquire` ops per 5 000-doc batch.  For the
        // common log-ingest case (stable schema, no dense-vector
        // fields) both functions are no-ops but still paid the lock +
        // `.await` overhead, costing measurable wall time.
        //
        // Hoisted once-per-batch: we take the schema read lock EXACTLY
        // ONCE, scan all sources for unknown field names in one pass,
        // and only call the slow-path `evolve_schema_from_doc` when
        // something new is actually detected.  Similarly for vectors —
        // we detect presence-of-any-vector-field via a single pass over
        // the first doc's object keys (sufficient for our schema model
        // because vector fields are fixed per index, not per doc).
        {
            let schema_guard = self.schema.read().await;
            let is_dynamic = matches!(
                schema_guard.dynamic,
                xerj_common::schema::DynamicMapping::Dynamic
            );
            // Fast-path: for a stable, non-dynamic schema we can skip
            // the entire per-doc evolve pass.  Under dynamic mapping we
            // cheaply collect the sources that might actually change the
            // schema under the read lock, then only upgrade to a write
            // lock (inside `evolve_schema_from_doc`, called per source
            // below) for the ones that do. "Might change the schema" is
            // two things, not one: a brand-new top-level field (as
            // before), OR a new nested child under a top-level field the
            // schema already has (`field_config_needs_merge`) -- without
            // the second check, a document whose only new content is
            // nested (e.g. `metadata.project` after `metadata.kind` was
            // already known) would never reach `evolve_schema_from_doc` at
            // all here, no matter how many times it fixed this same gap
            // internally.
            let mut sources_needing_evolve: Vec<&Value> = Vec::new();
            if is_dynamic {
                for ingest in &processed {
                    if let Some(obj) = ingest.source.as_object() {
                        let needs_evolve =
                            obj.iter().any(|(k, v)| match schema_guard.schema.field(k) {
                                None => true,
                                Some(existing) => field_config_needs_merge(existing, v),
                            });
                        if needs_evolve {
                            sources_needing_evolve.push(ingest.source.as_ref());
                        }
                    }
                }
            }
            drop(schema_guard);
            for src in sources_needing_evolve {
                self.evolve_schema_from_doc(src).await;
            }
        }

        // Vector indexing is only meaningful when at least one document
        // in the batch carries a vector. Scan until the first candidate
        // instead of inspecting only processed[0]: mixed batches may
        // legitimately begin with an ordinary text/log document. A packed
        // `xerj:f32:` string is that vector (#1940); treating only number
        // arrays as candidates skipped HNSW for every semantic bulk batch.
        if processed.iter().any(|r| {
            r.source
                .as_object()
                .map(|obj| {
                    obj.values().any(|v| {
                        v.as_str()
                            .is_some_and(xerj_common::packed_f32::is_packed_f32)
                            || v.as_array()
                                .map(|arr| !arr.is_empty() && arr.iter().all(Value::is_number))
                                .unwrap_or(false)
                    })
                })
                .unwrap_or(false)
        }) {
            for ingest in &processed {
                self.index_vectors(&ingest.id, &ingest.source).await;
            }
        }

        // ── Step 5: check flush threshold ─────────────────────────────────
        self.maybe_spawn_flush().await;

        // ── Metrics ───────────────────────────────────────────────────────
        let elapsed_ms = index_start.elapsed().as_millis() as u64;
        self.metric_index_count
            .fetch_add(batch_len as u64, Ordering::Relaxed);
        self.metric_index_total_ms
            .fetch_add(elapsed_ms, Ordering::Relaxed);
        // RC4 W4 item 2: end-to-end latency of this indexing (batch) call.
        if let Some(m) = crate::engine_metrics() {
            m.observe_index(elapsed_ms as f64 / 1000.0);
        }

        debug!(batch = batch_len, elapsed_ms, "turbo batch indexed");

        Ok(responses)
    }

    /// M5.11 — ULTRA-turbo raw-bytes ingest.
    ///
    /// Takes already-serialized NDJSON document lines, validates and parses
    /// the complete batch once, then reuses those values for WAL, schema, and
    /// FTS work. Validation precedes every write-side action: malformed input
    /// cannot reserve sequence numbers, become replayable, or trigger a flush.
    pub async fn index_batch_turbo_raw(
        &self,
        docs: Vec<(String, Arc<[u8]>)>,
    ) -> Result<Vec<IndexResponse>> {
        if docs.is_empty() {
            return Ok(Vec::new());
        }
        let batch_len = docs.len();
        if let Some(block) = self.write_block_reason().await {
            return Err(EngineError::Common(xerj_common::XerjError::index_blocked(
                self.name.as_str(),
                block,
            )));
        }
        // Process-wide admission: disk flood-stage block (item 3) + parent
        // memory circuit breaker (item 1). Fires before any per-index work.
        self.governor_write_gate()?;
        let syntax_t = std::time::Instant::now();
        let validated = crate::ingest_pool()
            .install(|| xerj_storage::IndexStore::validate_raw_batch(docs))
            .map_err(|error| match error {
                xerj_storage::StorageError::RawBatchValidation { .. } => EngineError::Common(
                    xerj_common::XerjError::invalid_document_json(error.to_string()),
                ),
                error => EngineError::Storage(error),
            })?;
        let syntax_elapsed = syntax_t.elapsed();
        let hard_block = self.flush_byte_threshold.saturating_mul(3);
        let soft_block = self.flush_byte_threshold.saturating_mul(2);
        {
            let mem_bytes = self.memtable.size_bytes();
            if mem_bytes >= soft_block {
                self.maybe_spawn_flush().await;
                // Block up to 30 s wall-clock until the memtable drains.
                // Pre-fix: 10 × 5 ms then error out — too short for a
                // sustained bulk-ingest workload where a flush of a
                // 512 MB segment takes 250 ms-2 s.  See
                // `2026-04-25T21-50-00_ingest_perf_regression_zstd19.md`.
                let bp_start = std::time::Instant::now();
                let bp_deadline = std::time::Duration::from_secs(30);
                while self.memtable.size_bytes() >= hard_block {
                    if bp_start.elapsed() >= bp_deadline {
                        self.maybe_spawn_flush().await;
                        return Err(EngineError::Common(
                            xerj_common::XerjError::resource_exhausted(format!(
                                "indexing back-pressure: memtable={}MB exceeds 3×flush_threshold={}MB on index [{}] after {}s wait — flusher may be stuck",
                                self.memtable.size_bytes() / (1024 * 1024),
                                self.flush_byte_threshold / (1024 * 1024),
                                self.name.as_str(),
                                bp_deadline.as_secs(),
                            )),
                        ));
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(25)).await;
                    if bp_start.elapsed().as_millis() % 200 < 25 {
                        self.maybe_spawn_flush().await;
                    }
                }
            }
        }

        // Charge the token spike before the batch is parsed. Eight bulks can
        // pass one RSS sample and then analyze together; the reservation
        // makes the second one 429 while the first is still allocating (#1122).
        let analyze_reservation = Self::reserve_batch_analyze(validated.docs())?;
        let dom_t = std::time::Instant::now();
        let validated = crate::ingest_pool()
            .install(|| xerj_storage::IndexStore::parse_validated_raw_batch(validated))
            .map_err(|error| match error {
                xerj_storage::StorageError::RawBatchValidation { .. } => EngineError::Common(
                    xerj_common::XerjError::invalid_document_json(error.to_string()),
                ),
                error => EngineError::Storage(error),
            })?;
        let raw_parse_elapsed = syntax_elapsed.saturating_add(dom_t.elapsed());
        let index_start = std::time::Instant::now();
        // THROWAWAY prof (XERJ_PROF): per-phase attribution of the turbo path.
        let prof = std::env::var_os("XERJ_PROF").is_some();
        let mut p_wal_us = 0u128;
        let mut p_parse_us = 0u128;
        let mut p_evolve_us = 0u128;
        let mut p_analyze_us = 0u128;
        let mut p_insert_us = 0u128;
        let p_t = std::time::Instant::now();

        // The complete request was parsed before admission/back-pressure.
        // Record that preflight in the optional phase profiler.
        use rayon::prelude::*;
        if prof {
            p_parse_us = raw_parse_elapsed.as_micros();
        }
        let (has_copy_to, has_vector_mapping) = {
            let schema = self.schema.read().await;
            (
                schema_has_copy_to(&schema.schema),
                !collect_dense_vector_fields(&schema.schema).is_empty(),
            )
        };
        let _hnsw_publication = has_vector_mapping.then(|| self.begin_hnsw_publication());
        let prepared_copy_sources: Option<Vec<Arc<Value>>> = if has_copy_to {
            let schema = self.schema.read().await;
            Some(
                validated
                    .parsed()
                    .expect("parse_validated_raw_batch retains parsed values")
                    .iter()
                    .map(|source| Arc::new(apply_copy_to(source, &schema.schema)))
                    .collect(),
            )
        } else {
            None
        };
        let sources_for_prepare: &[Arc<Value>] =
            prepared_copy_sources.as_deref().unwrap_or_else(|| {
                validated
                    .parsed()
                    .expect("parse_validated_raw_batch retains parsed values")
            });
        self.observe_passage_chunks(sources_for_prepare.iter().map(|source| source.as_ref()))
            .await;
        // Dynamic schema mutation and persistence are additive preparation:
        // they expose no document and do not alter postings for existing
        // documents, so search results remain extensionally unchanged during
        // the schema-only interval. The following document publication bumps
        // the collection generation, isolating every cache/single-flight entry
        // created before these sources become visible. Complete preparation
        // before WAL/VersionMap mutation so cancellation cannot strand a
        // half-published document batch.
        let evolve_t = std::time::Instant::now();
        self.evolve_schema_from_docs(sources_for_prepare).await;
        if prof {
            p_evolve_us = evolve_t.elapsed().as_micros();
        }
        let publication_schema = self.schema.read().await;

        #[cfg(test)]
        if let Some((doc, _)) = validated.docs().first() {
            self.publication_test_point(doc, PublicationTestPoint::RawBeforeCollectionBegin);
            tokio::task::yield_now().await;
        }

        let mut collection_publication = self
            .collection_publication
            .begin()
            .map_err(|_| collection_publication_interrupted())?;
        let wal_t = std::time::Instant::now();
        let (docs, sources, seq_nos) = if has_copy_to {
            let (docs, _) = validated.into_parts();
            let sources =
                prepared_copy_sources.expect("copy_to sources were prepared before publication");
            let wal_docs: Vec<(String, Arc<Value>)> = docs
                .iter()
                .zip(&sources)
                .map(|((id, _), source)| (id.clone(), Arc::clone(source)))
                .collect();
            let seq_nos = self.store.wal_append_batch(&wal_docs)?;
            (docs, sources, seq_nos)
        } else {
            let seq_nos = self.store.wal_append_batch_raw(&validated)?;
            let (docs, parsed) = validated.into_parts();
            (
                docs,
                parsed.expect("parse_validated_raw_batch retains parsed values"),
                seq_nos,
            )
        };
        #[cfg(test)]
        if let Some((doc, _)) = docs.first() {
            self.publication_test_point(doc, PublicationTestPoint::RawAfterWalVersionMap);
            tokio::task::yield_now().await;
        }
        // RC4 W4 item 2: WAL durability-write latency.
        if let Some(m) = crate::engine_metrics() {
            m.observe_wal_write(wal_t.elapsed().as_secs_f64());
        }
        if prof {
            p_wal_us = p_t.elapsed().as_micros();
        }
        // Insert each doc EXACTLY ONCE into the engine FTS memtable,
        // routed to the doc's OWN shard — bit-for-bit identical to the
        // per-doc `index_document` path.
        //
        // The earlier "ultra-turbo" shape pushed every doc TWICE: once
        // as a raw-bytes entry pinned to docs[0]'s shard (intended for
        // _source) and again via `insert` on the doc's own shard (for
        // search/aggs).  That double-represented each doc in
        // `memtable.docs` — often on two different shards — so the
        // brute-force agg corpus (`all_docs_with_sources`) and every
        // terms/stats/cardinality/date_histogram aggregation counted
        // each UNFLUSHED doc twice (140-test regression).
        //
        // A single `insert` discharges BOTH responsibilities: it stores
        // the parsed `source` so `_source` GET (`get_doc_source_as_value`)
        // resolves it, AND it builds the inverted index + columnar
        // doc-values for search + aggregations.  `wal_append_batch`
        // above already wrote the WAL frames and set the version_map
        // (so `_count`/`hits.total` via `version_map.live_count()` and
        // GET visibility are correct), exactly like `self.store.index`
        // does on the per-doc path.
        // ── P2.1: intra-request shard fan-out (the DWPT equivalent). ──
        //
        // The pre-P2.1 shape indexed serially, doc-by-doc, so a single
        // `_bulk` request used exactly one core regardless of the cores
        // available (measured: ~104% CPU on a 32-core box). We now:
        //   1. parse every doc's JSON in parallel (the dominant per-doc
        //      CPU cost) on the rayon pool;
        //   2. evolve the schema SERIALLY in doc order (rare, additive;
        //      a no-op after the first few docs — see
        //      `evolve_schema_from_doc`), so dynamic-mapping resolution
        //      is order-deterministic and identical to the serial path;
        //   3. bucket doc indices by their OWN shard and insert each
        //      shard's docs in parallel, holding that shard's lock
        //      exactly once. Because the buckets partition by shard, no
        //      two rayon workers ever contend on the same lock — one
        //      bulk request now fans across min(Ncore, Nshard) cores.
        //
        // Correctness invariants preserved bit-for-bit vs the serial
        // loop: (a) each doc is inserted EXACTLY ONCE on its own shard
        // with its own `seq_nos[i]`; (b) `version` = prior doc_count +
        // position + 1, assigned in doc order via one batch-level
        // `fetch_add`; (c) response order matches request order.
        // 3. Parallel shard-partitioned insert. Partition the batch by
        // each doc's own shard, then insert each shard's sub-batch on a
        // rayon worker holding that shard's lock exactly once — the
        // DocumentsWriterPerThread analogue.
        {
            let schema = &publication_schema.schema;
            let mem = &*self.memtable;

            // 3a. Pre-analyze every doc OUTSIDE the shard locks.  The
            // schema text-field extraction + dynamic-mapping tree walk
            // + analyzer tokenisation are the dominant per-doc CPU cost
            // of `insert` (~30 s of tokenize per 1 M docs) and are pure
            // — running them here on the rayon pool instead of inside
            // `with_shard_mut` cuts the lock-held work from ~39 µs/doc
            // to ~9 µs/doc, which is what lets 8 concurrent bulk
            // clients actually scale instead of convoying on the shard
            // write locks.  Uses the exact same analyzer lookup as
            // `FtsMemtable::insert`, so the postings are bit-identical.
            let analyzer = mem
                .default_analyzer()
                .expect("standard analyzer always present");
            let excluded_fts_fields = crate::memtable::fts_excluded_fields(schema);
            let p_t = std::time::Instant::now();
            let analyzed: Vec<Vec<(String, Vec<xerj_fts::analyzer::Token>)>> = crate::ingest_pool()
                .install(|| {
                    sources
                        .par_iter()
                        .map(|source| {
                            crate::memtable::analyze_doc_excluding(
                                source.as_ref(),
                                schema,
                                &analyzer,
                                &excluded_fts_fields,
                            )
                        })
                        .collect()
                });
            if prof {
                p_analyze_us = p_t.elapsed().as_micros();
            }
            let p_t = std::time::Instant::now();

            let n_shards = mem.shard_count().max(1);
            let mut buckets: Vec<Vec<usize>> = vec![Vec::new(); n_shards];
            for (i, (id, _)) in docs.iter().enumerate() {
                buckets[mem.shard_for_dynamic(id)].push(i);
            }
            crate::ingest_pool().install(|| {
                buckets.par_iter().enumerate().for_each(|(shard, idxs)| {
                    if idxs.is_empty() {
                        return;
                    }
                    mem.with_shard_mut(shard, |m| {
                        for &i in idxs {
                            let (id, bytes) = &docs[i];
                            // `remove` first so a same-id overwrite within
                            // the batch leaves exactly one live entry
                            // (mirrors index_document).
                            m.remove(id);
                            // Same sizing formula as `insert` (`raw * 3 + 64`)
                            // with the raw NDJSON byte length standing in for
                            // `source.to_string().len()` — keeps the size
                            // re-serialisation off the lock too.
                            let size = (bytes.len() + id.len()) * 3 + 64;
                            m.insert_analyzed(
                                seq_nos[i],
                                id.clone(),
                                Arc::clone(&sources[i]),
                                &analyzed[i],
                                size,
                            );
                        }
                    });
                });
            });
            if prof {
                p_insert_us = p_t.elapsed().as_micros();
            }
        }
        // Tokens are in the memtable. Drop the estimate so the next batch
        // is charged the live RSS of those tokens, not the estimate as well.
        drop(analyze_reservation);
        drop(publication_schema);

        if prof {
            eprintln!(
                "XERJ_PROF turbo-batch docs={} wal_us={} parse_us={} evolve_us={} analyze_us={} insert_us={} total_us={}",
                batch_len, p_wal_us, p_parse_us, p_evolve_us, p_analyze_us, p_insert_us,
                index_start.elapsed().as_micros()
            );
        }

        // 4. One batch-level version stamp, assigned in request order.
        let base = self
            .doc_count
            .fetch_add(batch_len as u64, Ordering::Relaxed);
        let responses: Vec<IndexResponse> = docs
            .iter()
            .enumerate()
            .map(|(i, (id, _))| IndexResponse {
                id: id.clone(),
                seq_no: seq_nos[i],
                version: base + i as u64 + 1,
                result: "created".to_string(),
            })
            .collect();
        collection_publication.commit();
        drop(collection_publication);
        self.collection_publication.handoff_to_readers().await;
        // The raw path already parsed every source for schema evolution and
        // FTS analysis. Publish those same authoritative values to HNSW before
        // the batch becomes observable to its caller.
        #[cfg(test)]
        if let Some((doc, _)) = docs.first() {
            self.publication_test_point(doc, PublicationTestPoint::RawBeforeHnsw);
        }
        for (doc, source) in docs.iter().zip(&sources) {
            self.index_vectors(&doc.0, source).await;
        }

        self.maybe_spawn_flush().await;

        let elapsed_ms = index_start.elapsed().as_millis() as u64;
        self.metric_index_count
            .fetch_add(batch_len as u64, Ordering::Relaxed);
        self.metric_index_total_ms
            .fetch_add(elapsed_ms, Ordering::Relaxed);
        // RC4 W4 item 2: end-to-end latency of this indexing (batch) call.
        if let Some(m) = crate::engine_metrics() {
            m.observe_index(elapsed_ms as f64 / 1000.0);
        }

        Ok(responses)
    }

    /// **Fully synchronous** raw-bytes ingest path.  Intended for bulk CLI
    /// indexing where the caller is a rayon worker — no `.await`, no
    /// `tokio::spawn`, no runtime crossing.  Returns the number of docs
    /// accepted (equal to `docs.len()` on success).
    ///
    /// This path is the sync twin of [`index_batch_turbo_raw`].  Both
    /// append to the same sharded WAL + memtable; the only difference is
    /// that flush scheduling and back-pressure are expressed via a
    /// `parking_lot::Condvar` (one futex pair per signal) instead of
    /// `tokio::time::sleep` + `tokio::spawn` (10-100 µs wake-up chain
    /// per call, futex-heavy at scale).
    ///
    /// **Write-block check is skipped** — the sync path is for bulk
    /// ingest harnesses (`xerj index`) which are not subject to per-
    /// index write blocks.  HTTP handlers should continue to use the
    /// async `index_batch_turbo_raw` which honours blocks.
    pub fn index_batch_sync_raw(&self, docs: Vec<(String, Arc<[u8]>)>) -> Result<usize> {
        if docs.is_empty() {
            return Ok(0);
        }
        let batch_len = docs.len();
        self.governor_write_gate()?;
        let has_vector_mapping = {
            let schema = self.schema.try_read().map_err(|_| {
                EngineError::Common(xerj_common::XerjError::resource_exhausted(
                    "schema is being updated during synchronous ingest; retry the batch",
                ))
            })?;
            !collect_dense_vector_fields(&schema.schema).is_empty()
        };
        if has_vector_mapping {
            if tokio::runtime::Handle::try_current().is_ok() {
                return Err(EngineError::Common(
                    xerj_common::XerjError::resource_exhausted(
                        "synchronous vector ingest cannot run on a Tokio runtime thread; call it from a dedicated/Rayon worker or use async turbo ingest",
                    ),
                ));
            }
            if self.flush_signal.runtime().is_none() {
                return Err(EngineError::Common(
                    xerj_common::XerjError::resource_exhausted(
                        "synchronous vector ingest requires the engine runtime; retry through async turbo ingest",
                    ),
                ));
            }
        }
        let validated = crate::ingest_pool()
            .install(|| xerj_storage::IndexStore::validate_raw_batch(docs))
            .map_err(|error| match error {
                xerj_storage::StorageError::RawBatchValidation { .. } => EngineError::Common(
                    xerj_common::XerjError::invalid_document_json(error.to_string()),
                ),
                error => EngineError::Storage(error),
            })?;

        let hard_block = self.flush_byte_threshold.saturating_mul(3);
        let soft_block = self.flush_byte_threshold.saturating_mul(2);
        {
            let mem_bytes = self.memtable.size_bytes();
            if mem_bytes >= soft_block {
                // Kick a flush on every shard — we're over the global
                // soft cap so they all need to drain.
                self.try_spawn_sync_flush_all();
                // Block on Condvar until the memtable drains below
                // soft_block.  Pre-fix this loop ran 10 × 5 ms = 50 ms
                // and then returned ResourceExhausted — that's far
                // shorter than a single flush takes (250 ms-2 s for a
                // 512 MB segment), so under sustained 16-32-worker
                // ingest the cap was reactive rather than preventive
                // and 75 % of batches errored out (see
                // `2026-04-25T21-50-00_ingest_perf_regression_zstd19.md`).
                //
                // Now: block up to 30 s wall-clock total, in 25 ms
                // Condvar-wake increments.  Returns error only if the
                // flusher is genuinely stuck (deadlock, OOM, disk
                // full).  At 30 s of unbroken back-pressure on a healthy
                // host, something else is wrong and the error is real.
                let bp_start = std::time::Instant::now();
                let bp_deadline = std::time::Duration::from_secs(30);
                while self.memtable.size_bytes() >= hard_block {
                    if bp_start.elapsed() >= bp_deadline {
                        self.try_spawn_sync_flush_all();
                        return Err(EngineError::Common(
                            xerj_common::XerjError::resource_exhausted(format!(
                                "indexing back-pressure: memtable={}MB exceeds 3×flush_threshold={}MB on index [{}] after {}s wait — flusher may be stuck",
                                self.memtable.size_bytes() / (1024 * 1024),
                                self.flush_byte_threshold / (1024 * 1024),
                                self.name.as_str(),
                                bp_deadline.as_secs(),
                            )),
                        ));
                    }
                    self.flush_signal
                        .wait_for_drain(std::time::Duration::from_millis(25));
                    // Re-kick periodically in case a flush completed and a
                    // new shard now needs draining.
                    if bp_start.elapsed().as_millis() % 200 < 25 {
                        self.try_spawn_sync_flush_all();
                    }
                }
            }
        }

        let analyze_reservation = Self::reserve_batch_analyze(validated.docs())?;
        let _hnsw_publication = has_vector_mapping.then(|| self.begin_hnsw_publication());
        let index_start = std::time::Instant::now();
        let wal_t = std::time::Instant::now();
        // Preserve copy_to semantics on the synchronous CLI path too. The
        // common no-copy_to case keeps the sealed raw-byte WAL fast path.
        // For the rare mapped case, materialize once, transform the sole
        // source authority, and retain transformed bytes for the raw
        // memtable so live GET, flush, and replay all observe the same value.
        let (has_copy_to, passage_scored_fields) = {
            let schema = self.schema.try_read().map_err(|_| {
                EngineError::Common(xerj_common::XerjError::resource_exhausted(
                    "schema is being updated during synchronous ingest; retry the batch",
                ))
            })?;
            (
                schema_has_copy_to(&schema.schema),
                passage_scored_vector_fields(&schema.schema),
            )
        };
        let validated =
            if (has_copy_to || !passage_scored_fields.is_empty()) && validated.parsed().is_none() {
                crate::ingest_pool()
                    .install(|| xerj_storage::IndexStore::parse_validated_raw_batch(validated))
                    .map_err(EngineError::Storage)?
            } else {
                validated
            };
        if let Some(parsed) = validated.parsed() {
            self.observe_passage_chunks_for_targets(
                &passage_scored_fields,
                parsed.iter().map(|source| source.as_ref()),
            );
        }
        let (docs, seq_nos, copy_schema, mut collection_publication) = if has_copy_to {
            let (raw_docs, parsed) = validated.into_parts();
            let parsed = parsed.expect("parse_validated_raw_batch retains parsed values");
            let schema = self.schema.try_read().map_err(|_| {
                EngineError::Common(xerj_common::XerjError::resource_exhausted(
                    "schema is being updated during synchronous ingest; retry the batch",
                ))
            })?;
            let copy_schema = schema.schema.clone();
            let transformed: Vec<Arc<Value>> = parsed
                .iter()
                .map(|source| Arc::new(apply_copy_to(source, &copy_schema)))
                .collect();
            drop(schema);
            self.observe_passage_chunks_for_targets(
                &passage_scored_fields,
                transformed.iter().map(|source| source.as_ref()),
            );
            let wal_docs: Vec<(String, Arc<Value>)> = raw_docs
                .iter()
                .zip(&transformed)
                .map(|((id, _), source)| (id.clone(), Arc::clone(source)))
                .collect();
            #[cfg(test)]
            if let Some((id, _)) = raw_docs.first() {
                self.sync_prepublication_test_point(id)?;
            }
            let collection_publication = self
                .collection_publication
                .begin()
                .map_err(|_| collection_publication_interrupted())?;
            let seq_nos = self.store.wal_append_batch(&wal_docs)?;
            let docs = raw_docs
                .into_iter()
                .zip(transformed)
                .map(|((id, _), source)| {
                    serde_json::to_vec(source.as_ref())
                        .map(|bytes| (id, Arc::<[u8]>::from(bytes), Some(source)))
                        .map_err(xerj_storage::StorageError::from)
                })
                .collect::<std::result::Result<Vec<_>, _>>()?;
            (docs, seq_nos, Some(copy_schema), collection_publication)
        } else if has_vector_mapping {
            // Ordinary sync ingest keeps its sealed raw-byte path. A mapped
            // vector index additionally needs parsed sources so the same
            // publication can maintain HNSW and its coverage denominator.
            let validated = if validated.parsed().is_some() {
                validated
            } else {
                crate::ingest_pool()
                    .install(|| xerj_storage::IndexStore::parse_validated_raw_batch(validated))
                    .map_err(EngineError::Storage)?
            };
            #[cfg(test)]
            if let Some((id, _)) = validated.docs().first() {
                self.sync_prepublication_test_point(id)?;
            }
            let collection_publication = self
                .collection_publication
                .begin()
                .map_err(|_| collection_publication_interrupted())?;
            let seq_nos = self.store.wal_append_batch_raw(&validated)?;
            let (raw_docs, parsed) = validated.into_parts();
            let parsed = parsed.expect("parse_validated_raw_batch retains parsed values");
            let docs = raw_docs
                .into_iter()
                .zip(parsed)
                .map(|((id, bytes), source)| (id, bytes, Some(source)))
                .collect();
            (docs, seq_nos, None, collection_publication)
        } else {
            #[cfg(test)]
            if let Some((id, _)) = validated.docs().first() {
                self.sync_prepublication_test_point(id)?;
            }
            let collection_publication = self
                .collection_publication
                .begin()
                .map_err(|_| collection_publication_interrupted())?;
            let seq_nos = self.store.wal_append_batch_raw(&validated)?;
            let (docs, parsed) = validated.into_parts();
            let docs = match parsed {
                Some(parsed) => docs
                    .into_iter()
                    .zip(parsed)
                    .map(|((id, bytes), source)| (id, bytes, Some(source)))
                    .collect(),
                None => docs
                    .into_iter()
                    .map(|(id, bytes)| (id, bytes, None))
                    .collect(),
            };
            (docs, seq_nos, None, collection_publication)
        };
        // RC4 W4 item 2: WAL durability-write latency.
        if let Some(m) = crate::engine_metrics() {
            m.observe_wal_write(wal_t.elapsed().as_secs_f64());
        }

        // Partition by each document's own shard. The old sync path routed the
        // entire batch to docs[0]'s shard, while GET/search route by each ID;
        // every sibling ID hashing elsewhere was therefore invisible until
        // flush. Preserve request order within each shard so duplicate IDs are
        // deterministic last-write-wins.
        let vector_sources: Vec<(String, Arc<Value>)> = if has_vector_mapping {
            docs.iter()
                .filter_map(|(id, _, source)| {
                    source
                        .as_ref()
                        .map(|source| (id.clone(), Arc::clone(source)))
                })
                .collect()
        } else {
            Vec::new()
        };
        let n_shards = self.memtable.shard_count().max(1);
        let mut buckets: Vec<Vec<(u64, String, Arc<[u8]>, Option<Arc<Value>>)>> =
            (0..n_shards).map(|_| Vec::new()).collect();
        for (seq_no, (id, bytes, source)) in seq_nos.iter().copied().zip(docs) {
            let shard = self.memtable.shard_for_dynamic(&id);
            buckets[shard].push((seq_no, id, bytes, source));
        }
        let touched_shards: Vec<usize> = crate::ingest_pool().install(|| {
            use rayon::prelude::*;
            buckets
                .into_par_iter()
                .enumerate()
                .filter_map(|(shard, bucket)| {
                    if bucket.is_empty() {
                        return None;
                    }
                    for chunk in bucket.chunks(MEMTABLE_INSERT_CHUNK) {
                        self.memtable.with_shard_mut(shard, |mem| {
                            for (seq_no, id, bytes, source) in chunk {
                                // `insert_raw_bytes_fresh` requires absence.
                                // Remove unconditionally so an overwrite from
                                // an earlier batch and a duplicate within this
                                // batch have identical last-write-wins
                                // semantics.
                                mem.remove(id);
                                if let (Some(source), Some(schema)) =
                                    (source.as_ref(), copy_schema.as_ref())
                                {
                                    mem.insert(id.clone(), source, schema, *seq_no);
                                } else {
                                    mem.insert_raw_bytes_fresh(
                                        *seq_no,
                                        id.clone(),
                                        Arc::clone(bytes),
                                    );
                                }
                            }
                        });
                    }
                    Some(shard)
                })
                .collect()
        });
        drop(analyze_reservation);
        // Single batch-level atomic instead of one per doc.  At 1.7 M/s
        // × 10 k batch = 170 batches/s this cuts ~17 M atomic ops/s of
        // cache-line bouncing on `doc_count`.
        self.doc_count
            .fetch_add(batch_len as u64, Ordering::Relaxed);
        collection_publication.commit();
        drop(collection_publication);
        self.collection_publication.handoff_to_readers_blocking();

        if !vector_sources.is_empty() {
            // This API runs on the CLI's Rayon workers. Cross into the cached
            // engine runtime once per vector-bearing batch (not once per doc)
            // and complete graph publication before reporting success.
            #[cfg(test)]
            self.publication_test_point(&vector_sources[0].0, PublicationTestPoint::RawBeforeHnsw);
            let rt = self.flush_signal.runtime().expect("validated above");
            rt.block_on(async {
                for (id, source) in vector_sources {
                    self.index_vectors(&id, &source).await;
                }
            });
        }

        for shard in touched_shards {
            let per_shard_doc_t =
                staggered_per_shard_threshold(self.flush_doc_threshold, shard, n_shards);
            let per_shard_byte_t =
                staggered_per_shard_threshold(self.flush_byte_threshold, shard, n_shards);
            let (sd_docs, sd_bytes) = self.memtable.shard_load(shard);
            if sd_docs >= per_shard_doc_t || sd_bytes >= per_shard_byte_t {
                self.try_spawn_sync_flush(shard);
            }
        }

        let elapsed_ms = index_start.elapsed().as_millis() as u64;
        self.metric_index_count
            .fetch_add(batch_len as u64, Ordering::Relaxed);
        self.metric_index_total_ms
            .fetch_add(elapsed_ms, Ordering::Relaxed);
        // RC4 W4 item 2: end-to-end latency of this indexing (batch) call.
        if let Some(m) = crate::engine_metrics() {
            m.observe_index(elapsed_ms as f64 / 1000.0);
        }

        Ok(batch_len)
    }

    /// Spawn one `do_flush_shard` tokio task for `shard_idx`, bounded
    /// by `flush_sema` (non-blocking `try_acquire`).  Called from the
    /// **synchronous** ingest path — no `.await`, just a handful of
    /// atomics to queue the task onto the tokio runtime.  Drops the
    /// request if the sema is already at capacity; the next batch on
    /// this shard will re-request, so there's no lost flush.
    pub(crate) fn try_spawn_sync_flush(&self, shard_idx: usize) {
        let rt = match self.flush_signal.runtime() {
            Some(rt) => rt,
            None => return,
        };
        let permit = match Arc::clone(&self.flush_sema).try_acquire_owned() {
            Ok(p) => p,
            Err(_) => return,
        };
        let store = Arc::clone(&self.store);
        let memtable = Arc::clone(&self.memtable);
        let collection_publication = Arc::clone(&self.collection_publication);
        let registry = Arc::clone(&self.registry);
        let data_dir = self.data_dir.clone();
        let field_configs = self
            .flush_signal
            .field_configs(&self.schema, self.segment_text_analyzer());
        let excluded_fts_fields = self.flush_signal.fts_excluded_fields(&self.schema);
        let dv_skip = self.flush_signal.doc_values_skip_set(&self.schema);
        let dataset_version = Arc::clone(&self.dataset_version);
        let query_cache = Arc::clone(&self.query_cache);
        let warm_caches = self.publish_warm_caches();
        // Permit is released by `on_drained` (fired after Phase 1 drain)
        // so the slow segment-write I/O in Phase 2 doesn't hold up the
        // per-shard flush permit pool.  The `Option` wrapper makes the
        // move into the FnOnce explicit — `take()` + `drop` releases it.
        let permit_cell: std::sync::Mutex<Option<tokio::sync::OwnedSemaphorePermit>> =
            std::sync::Mutex::new(Some(permit));
        let permit_cell = Arc::new(permit_cell);
        let permit_cell_cb = Arc::clone(&permit_cell);
        let flush_signal_cb = Arc::clone(&self.flush_signal);
        let index_name = self.name.as_str().to_string();
        let admit_timeout =
            std::time::Duration::from_millis(self.flush_admit_timeout_ms.load(Ordering::Relaxed));
        rt.spawn(async move {
            let on_drained = move || {
                if let Ok(mut guard) = permit_cell_cb.lock() {
                    let _ = guard.take();
                }
                // Wake any ingest thread blocked on back-pressure.
                flush_signal_cb.notify_drain();
            };
            let result = do_flush_shard(
                shard_idx,
                store,
                memtable,
                collection_publication,
                registry,
                data_dir,
                field_configs,
                excluded_fts_fields,
                dv_skip,
                on_drained,
                warm_caches,
                index_name,
                admit_timeout,
                #[cfg(test)]
                None,
            )
            .await;
            // Fallback: if do_flush_shard aborted before on_drained fired
            // (shouldn't happen with current structure but defensive),
            // the permit_cell still holds the permit — drop it here.
            if let Ok(mut guard) = permit_cell.lock() {
                let _ = guard.take();
            }
            if let Err(e) = result {
                tracing::error!(error = %e, shard_idx, "sync flush failed");
            }
            // P3.2 — additive invalidation. Bump the dataset version
            // (the query_cache is keyed by (query_hash, dataset_version)
            // so every cached result now misses) and clear the small
            // query_cache, but DO NOT clear the per-segment dv_cache: a
            // flush only CREATES new immutable segments and cannot
            // invalidate the doc-values of segments that already
            // existed. The old blanket clear forced a cold mmap+decode
            // on the next read after every flush — the flush-coincident
            // read-p99 spike. Segment-dropping merges evict the exact
            // dropped ids; see run_merge_once.
            dataset_version.fetch_add(1, Ordering::Release);
            query_cache.clear();
        });
    }

    fn try_spawn_sync_flush_all(&self) {
        let n = self.memtable.shard_count();
        for i in 0..n {
            self.try_spawn_sync_flush(i);
        }
    }

    /// Ultra-fast turbo ingest that **skips the WAL entirely**.
    ///
    /// Documents are written directly to the FTS memtable with zero disk I/O.
    /// Data durability is deferred until the next background flush, which
    /// writes a segment to disk.  In the event of a crash before flush,
    /// documents ingested via this method may be lost.
    ///
    /// # Trade-offs
    ///
    /// - **Speed**: WAL write is the dominant bottleneck for batches of
    ///   1 000+ docs.  Skipping it unlocks maximum CPU-bound throughput.
    /// - **Durability**: Documents are only durable after `flush()` completes.
    ///   For log pipelines where occasional re-ingestion is acceptable,
    ///   this is the preferred path.
    ///
    /// # When to use
    ///
    /// Enable with `X-Turbo-Realtime: true` on the bulk endpoint, or call
    /// this method directly when the caller can tolerate losing the most
    /// recent batch on crash.
    pub async fn index_batch_turbo_realtime(
        &self,
        docs: Vec<(String, Value, Arc<[u8]>)>,
        parallel: bool,
    ) -> Result<Vec<IndexResponse>> {
        use crate::turbo_ingest::TurboIngestPipeline;

        if docs.is_empty() {
            return Ok(Vec::new());
        }

        if let Some(block) = self.write_block_reason().await {
            return Err(EngineError::Common(xerj_common::XerjError::index_blocked(
                self.name.as_str(),
                block,
            )));
        }
        // Process-wide admission: disk flood-stage block (item 3) + parent
        // memory circuit breaker (item 1). Fires before any per-index work.
        self.governor_write_gate()?;

        let batch_len = docs.len();
        let index_start = std::time::Instant::now();

        // Step 1: Parallel tokenisation (no locks, no I/O).
        let mut pipeline = TurboIngestPipeline::new(batch_len + 1, parallel);
        for (id, source, source_bytes) in docs {
            pipeline.push(id, source, source_bytes);
        }
        let results = pipeline.flush();

        // Step 2: apply copy_to — wrap each source in Arc immediately.
        let schema_guard = self.schema.read().await;
        let processed: Vec<_> = results
            .into_iter()
            .map(|r| {
                let source = std::sync::Arc::new(apply_copy_to(&r.source, &schema_guard.schema));
                crate::turbo_ingest::IngestResult {
                    id: r.id,
                    tokens: r.tokens,
                    source,
                    source_bytes: r.source_bytes,
                }
            })
            .collect();
        drop(schema_guard);
        let _hnsw_publication = self
            .has_dense_vector_mapping()
            .await
            .then(|| self.begin_hnsw_publication());
        self.observe_passage_chunks(processed.iter().map(|ingest| ingest.source.as_ref()))
            .await;

        // Step 3: Update version map (lock-free atomic operations) — no WAL.
        // Assign monotonically increasing seq_nos from the engine's counter.
        use std::sync::atomic::Ordering;
        let seq_nos: Vec<u64> = processed
            .iter()
            .map(|_| self.doc_count.fetch_add(0, Ordering::Relaxed))
            .collect();

        // Step 4: FTS memtable insert — use standard insert() so the inverted
        // index is populated and match queries work correctly.
        let schema_guard2 = self.schema.read().await;
        let mem = &*self.memtable;
        let mut responses = Vec::with_capacity(batch_len);
        let mut collection_publication = self
            .collection_publication
            .begin()
            .map_err(|_| collection_publication_interrupted())?;

        for (i, ingest) in processed.iter().enumerate() {
            mem.remove(&ingest.id);
            let seq_no = seq_nos[i];
            mem.insert(
                ingest.id.clone(),
                &ingest.source,
                &schema_guard2.schema,
                seq_no,
            );
            let version = self.doc_count.fetch_add(1, Ordering::Relaxed) + 1;
            responses.push(IndexResponse {
                id: ingest.id.clone(),
                seq_no,
                version,
                result: "created".to_string(),
            });
        }
        drop(schema_guard2);
        #[cfg(test)]
        if let Some(first) = processed.first() {
            self.publication_test_point(&first.id, PublicationTestPoint::RealtimeAfterFts);
        }
        collection_publication.commit();
        drop(collection_publication);
        self.collection_publication.handoff_to_readers().await;
        // Step 5: schema evolution + vector indexing (post-lock).
        for ingest in &processed {
            self.evolve_schema_from_doc(&ingest.source).await;
            self.index_vectors(&ingest.id, &ingest.source).await;
        }
        // Step 6: flush threshold check.
        self.maybe_spawn_flush().await;

        let elapsed_ms = index_start.elapsed().as_millis() as u64;
        self.metric_index_count
            .fetch_add(batch_len as u64, Ordering::Relaxed);
        self.metric_index_total_ms
            .fetch_add(elapsed_ms, Ordering::Relaxed);
        // RC4 W4 item 2: end-to-end latency of this indexing (batch) call.
        if let Some(m) = crate::engine_metrics() {
            m.observe_index(elapsed_ms as f64 / 1000.0);
        }

        debug!(
            batch = batch_len,
            elapsed_ms, "turbo-realtime batch indexed (no WAL)"
        );

        Ok(responses)
    }

    /// Index a document only if it does NOT already exist (ES `op_type=create` semantics).
    ///
    /// Returns `Err(VersionConflict)` if a live document with the same ID exists.
    pub async fn create_document(&self, id: String, source: Value) -> Result<IndexResponse> {
        self.index_document_with_version_inner_guarded(
            Some(id),
            source,
            None,
            None,
            false,
            None,
            true,
            None,
        )
        .await
    }

    /// Refresh: flush the current active memtable to a disk segment.
    ///
    /// After refresh, the memtable data is written to a new on-disk segment
    /// (FTS index + stored sources), the active memtable is replaced with a
    /// new empty one, and the old memtable is dropped entirely — freeing all
    /// RAM.  This keeps memory usage bounded regardless of dataset size.
    ///
    /// Search reads: active memtable (RAM) + disk segments (file I/O).
    /// The engine-generated embedding companion field names for this index —
    /// exactly the keys the default `_source` projection omits (#309).
    ///
    /// Published for the API layer, which has to know the same set for a reason
    /// the engine cannot serve: only the API sees the `fields`/`docvalue_fields`
    /// clauses, and only it can decide that a caller who named a companion there
    /// must get the intact source from the engine and the narrowed one on the
    /// wire (#310). The mapping rule stays in `generated_embedding_companion_fields`;
    /// this is a lock-scoped accessor for it, not a second implementation.
    pub async fn embedding_companion_fields(&self) -> HashSet<String> {
        let schema = self.schema.read().await;
        generated_embedding_companion_fields(&schema.schema)
    }

    /// The analyzer name the flush/merge FTS writer uses for `Text` fields
    /// (#937): the registry's `default` when one was declared via index
    /// settings AND this index's segments honour it, else `standard`.
    ///
    /// This MUST agree with the memtable's
    /// `get_analyzer("default").or_else(standard)` resolution or the same
    /// document analyses differently before and after `_flush` — the exact
    /// bug #937 reports. The one divergence kept on purpose is a pre-#937
    /// index with documents (see `segment_analyzer_binding_for_open`):
    /// its segments stay `standard` until the operator reindexes.
    fn segment_text_analyzer(&self) -> &'static str {
        if self.segment_default_analyzer_honored && self.registry.get_analyzer("default").is_some()
        {
            "default"
        } else {
            "standard"
        }
    }

    /// How the segment FTS query projection analyses text clauses (#937) —
    /// the same term space [`Self::segment_text_analyzer`] writes.
    fn segment_analyzer_binding(&self) -> SegmentAnalyzerBinding<'_> {
        if self.segment_default_analyzer_honored {
            SegmentAnalyzerBinding::Honored(&self.registry)
        } else {
            SegmentAnalyzerBinding::Standard
        }
    }

    /// Hold `refresh` until [`Self::test_set_pause_refresh`] clears.
    ///
    /// The flag is announced only after this call has entered, so a test can
    /// wait until the index is actually inside refresh and not merely racing
    /// the request.
    #[cfg(any(test, feature = "refresh-test-hook"))]
    async fn await_test_refresh_hold(&self) {
        if !self.test_pause_refresh.load(Ordering::Acquire) {
            return;
        }
        self.test_refresh_paused.store(true, Ordering::Release);
        while self.test_pause_refresh.load(Ordering::Acquire) {
            tokio::task::yield_now().await;
        }
        self.test_refresh_paused.store(false, Ordering::Release);
    }

    #[cfg(any(test, feature = "refresh-test-hook"))]
    pub fn test_set_pause_refresh(&self, pause: bool) {
        self.test_pause_refresh.store(pause, Ordering::Release);
    }

    #[cfg(any(test, feature = "refresh-test-hook"))]
    pub fn test_refresh_is_paused(&self) -> bool {
        self.test_refresh_paused.load(Ordering::Acquire)
    }

    #[cfg(any(test, feature = "refresh-test-hook"))]
    pub fn test_refresh_finished_count(&self) -> u64 {
        self.test_refresh_finished.load(Ordering::Acquire)
    }

    /// Make recent writes searchable.
    ///
    /// This is the body of HTTP `_refresh` (#2234). An empty memtable is
    /// already searchable — return without verified WAL maintenance, which is
    /// `flush` / `_flush` and is what used to sit behind a background segment
    /// merge. A non-empty memtable is published to a segment. The HNSW graph
    /// is persisted either way: background flushes skip that save, and an
    /// explicit refresh is the checkpoint for it. `save_hnsw_to_disk` returns
    /// immediately when the index has no graph.
    pub async fn refresh(&self) -> Result<()> {
        #[cfg(any(test, feature = "refresh-test-hook"))]
        self.await_test_refresh_hold().await;
        // Count a refresh that actually returned, including the empty-memtable
        // path and errors. The hold above is outside this guard so a paused
        // index does not look finished.
        #[cfg(any(test, feature = "refresh-test-hook"))]
        let _refresh_finished = TestRefreshFinished(self);
        {
            let mem = &*self.memtable;
            if mem.doc_count() == 0 {
                let _ = self.save_hnsw_to_disk().await;
                return Ok(());
            }
        }

        // Publish the memtable to a new segment. This drains the memtable,
        // writes the segment file + FTS index, and swaps the snapshot. The
        // drained memtable is dropped, freeing its RAM. Verified WAL
        // maintenance (snapshot fsync + prune) is `_flush` / `Index::flush`,
        // not this path (#2234).
        let (field_configs, excluded_fts_fields, dv_skip) = {
            let schema = self.schema.read().await;
            (
                build_fts_field_configs(&schema.schema, self.segment_text_analyzer()),
                crate::memtable::fts_excluded_fields(&schema.schema),
                doc_values_skip_set(&schema.schema),
            )
        };
        // Explicit refresh: wait behind any in-flight concurrent flushes
        // (semaphore has 4 permits) so the user-visible flush sees a
        // fully-drained memtable once the await returns. The wait is
        // bounded (#1635); a permit that never arrives fails this index
        // instead of parking the caller.
        let index_name = self.name.as_str().to_string();
        let admit_timeout =
            std::time::Duration::from_millis(self.flush_admit_timeout_ms.load(Ordering::Relaxed));
        let flush_timeout =
            std::time::Duration::from_millis(self.flush_timeout_ms.load(Ordering::Relaxed));
        let deadline = std::time::Instant::now() + flush_timeout;
        let _permit = wait_for_flush_permit(
            &index_name,
            "the flush semaphore",
            admit_timeout.min(deadline.saturating_duration_since(std::time::Instant::now())),
            self.flush_sema.acquire(),
        )
        .await?;
        // M5.2 — explicit refresh drains EVERY non-empty shard in
        // sequence (one shard per `do_flush_shard` call) so the
        // user-visible `refresh()` returns with zero unflushed
        // documents.  Sharded flushes run serially here because the
        // caller is waiting synchronously; the background scheduler
        // still fires shard flushes in parallel.
        let n_shards = self.memtable.shard_count();
        for shard_idx in 0..n_shards {
            // #1226 — skip empty shards (same reasoning as `flush()`): a
            // no-op shard finalize still acquires the process-global
            // `flush_finalize_gate`, so an empty shard would make this
            // serial refresh wait behind unrelated indices' ingest flushes
            // for nothing. Bound the work to the shards actually holding
            // documents.
            if self.memtable.shard_load(shard_idx).0 == 0 {
                continue;
            }
            let left = deadline.saturating_duration_since(std::time::Instant::now());
            if left.is_zero() {
                return Err(flush_budget_timeout_error(&index_name, flush_timeout));
            }
            // Spawn so a timeout detaches the shard task instead of
            // cancelling a publication that has already frozen the
            // memtable (#1015). The success path still waits for it.
            let task = tokio::spawn(do_flush_shard(
                shard_idx,
                Arc::clone(&self.store),
                Arc::clone(&self.memtable),
                Arc::clone(&self.collection_publication),
                Arc::clone(&self.registry),
                self.data_dir.clone(),
                field_configs.clone(),
                excluded_fts_fields.clone(),
                dv_skip.clone(),
                || {}, // serial refresh path — no permit to drop early
                self.publish_warm_caches(),
                index_name.clone(),
                admit_timeout,
                #[cfg(test)]
                None,
            ));
            await_flush_task(&index_name, left, task).await?;
        }

        // Update the doc counter so maybe_auto_flush uses a fresh baseline.
        self.last_flush_doc_count
            .store(self.doc_count.load(Ordering::Relaxed), Ordering::Relaxed);

        // Persist the HNSW graph at the refresh boundary too (flush()
        // already does). Bulk-ingest + _refresh is the standard ES client
        // workflow and background auto-flushes skip the graph save, so
        // without this the on-disk snapshot would stay at some mid-ingest
        // stamp and every restart would (safely, but needlessly) mark the
        // graph flush-time stale and fall back to brute-force kNN.
        let _ = self.save_hnsw_to_disk().await;

        debug!(
            index = self.name.as_str(),
            "refresh complete — memtable flushed to disk segment"
        );
        Ok(())
    }

    /// Spawn a background flush task if the memtable has grown past the
    /// configured doc/byte thresholds.
    ///
    /// V4 M4.5 — CONCURRENT FLUSH PIPELINE.
    ///
    /// Previously a `flush_in_progress` bool limited us to one in-flight
    /// flush at a time.  With a single CPU-bound flush taking ~5-10 s for
    /// 100 k docs, ingest at 60 k docs/s fills the memtable faster than one
    /// flush can drain it, pushing back-pressure.  We now allow up to
    /// `max_concurrent_flushes` flushes to execute in parallel — each drain
    /// is atomic under the memtable write lock (so no two flushes see the
    /// same doc twice), segment ids are unique per flush, and snapshot
    /// publication is atomic via ArcSwap.  Multiple flushes writing
    /// distinct segments to disk in parallel is exactly what Lucene's
    /// IndexWriter does on sustained ingest.
    async fn maybe_spawn_flush(&self) {
        use std::sync::atomic::Ordering as AtomicOrdering;

        // M5.2 — per-shard flush scheduler.  Pre-M5.2 `do_flush`
        // drained ALL shards into one segment, making flush a global
        // serialisation point.  Now we walk per-shard loads and
        // spawn one flush task per shard whose size crosses a
        // per-shard threshold.  Because shards flush independently
        // into their own segments on their own tokio tasks, the
        // aggregate drain rate scales with the number of busy
        // shards instead of being pinned at the single-flush rate.
        //
        // Per-shard threshold: 1/N of the global threshold so the
        // cumulative memtable size across all shards is bounded at
        // the same `flush_byte_threshold` the user configured.
        let shards = self.memtable.shard_loads();
        // M5.3 — per-shard threshold is `global / shard_count` at
        // FULL size (no 15 % soft factor).  Pre-M5.3 the scheduler
        // used a 15 % soft trigger to smooth flush cadence on a
        // single-memtable design; with per-shard flushing the tiny
        // fixed cost per segment (FtsIndexWriter setup + FST build
        // + file I/O) dominates when flushes are only a few
        // thousand docs each, so we let shards fill closer to
        // their share of the global threshold before flushing.
        let n_shards_sched = shards.len().max(1);

        let field_configs_once: std::sync::OnceLock<
            HashMap<String, xerj_fts::index::FieldIndexConfig>,
        > = std::sync::OnceLock::new();

        for (shard_idx, docs, bytes) in shards {
            let per_shard_doc_t =
                staggered_per_shard_threshold(self.flush_doc_threshold, shard_idx, n_shards_sched);
            let per_shard_byte_t =
                staggered_per_shard_threshold(self.flush_byte_threshold, shard_idx, n_shards_sched);
            if docs < per_shard_doc_t && bytes < per_shard_byte_t {
                continue;
            }

            // Try to acquire a flush permit non-blockingly.  A global
            // semaphore caps total concurrent flushes so we don't OOM
            // trying to hold N concurrent drained memtable snapshots.
            let permit = match Arc::clone(&self.flush_sema).try_acquire_owned() {
                Ok(p) => p,
                Err(_) => continue,
            };

            let store = Arc::clone(&self.store);
            let memtable = Arc::clone(&self.memtable);
            let registry = Arc::clone(&self.registry);
            let data_dir = self.data_dir.clone();
            let dataset_version = Arc::clone(&self.dataset_version);
            let query_cache = Arc::clone(&self.query_cache);
            let warm_caches = self.publish_warm_caches();

            // Pre-build field configs ONCE for all shard flushes we
            // spawn this tick — avoids N schema read-lock acquires.
            let field_configs = if let Some(cfg) = field_configs_once.get() {
                cfg.clone()
            } else {
                let schema = self.schema.read().await;
                let cfg = build_fts_field_configs(&schema.schema, self.segment_text_analyzer());
                let _ = field_configs_once.set(cfg.clone());
                cfg
            };
            let (excluded_fts_fields, dv_skip) = {
                let schema = self.schema.read().await;
                (
                    crate::memtable::fts_excluded_fields(&schema.schema),
                    doc_values_skip_set(&schema.schema),
                )
            };

            let flush_signal_cb = Arc::clone(&self.flush_signal);
            let collection_publication = Arc::clone(&self.collection_publication);
            let index_name = self.name.as_str().to_string();
            let admit_timeout = std::time::Duration::from_millis(
                self.flush_admit_timeout_ms.load(Ordering::Relaxed),
            );
            tokio::spawn(async move {
                // Release permit after drain (Phase 1), not after Phase 2
                // I/O — lets new flushes dispatch while segment writes
                // continue in parallel.
                let permit_cell = Arc::new(std::sync::Mutex::new(Some(permit)));
                let permit_cell_cb = Arc::clone(&permit_cell);
                let on_drained = move || {
                    if let Ok(mut guard) = permit_cell_cb.lock() {
                        let _ = guard.take();
                    }
                    // Wake any sync-ingest thread blocked on back-pressure.
                    flush_signal_cb.notify_drain();
                };
                let result = do_flush_shard(
                    shard_idx,
                    store,
                    memtable,
                    collection_publication,
                    registry,
                    data_dir,
                    field_configs,
                    excluded_fts_fields,
                    dv_skip,
                    on_drained,
                    warm_caches,
                    index_name,
                    admit_timeout,
                    #[cfg(test)]
                    None,
                )
                .await;
                if let Ok(mut guard) = permit_cell.lock() {
                    let _ = guard.take();
                }
                if let Err(e) = result {
                    tracing::error!(error = %e, shard_idx, "background shard flush failed");
                }
                // P3.2 — additive invalidation. Old segment IDs are
                // still valid after a flush (segments are immutable), so
                // we keep their per-segment dv_cache / stored_value_cache
                // entries warm and only invalidate the query_cache via
                // the dataset-version bump. This removes the cold-read
                // p99 spike that the old blanket clear produced on every
                // flush. Merges evict their dropped segment ids exactly.
                dataset_version.fetch_add(1, AtomicOrdering::Release);
                query_cache.clear();
            });
        }
    }

    // ── Segment merging ────────────────────────────────────────────────────────

    /// Run one pass of the size-tiered merge policy.  Each selected batch is
    /// merged synchronously; FTS side-cars for the merged segment are built
    /// before the new segment is published, and the old segments' files are
    /// left in place (cleanup happens on next restart via snapshot GC).
    ///
    /// Returns the number of merge batches that succeeded.
    ///
    /// This is called from the debounced background merge check (see
    /// `request_merge_check`, #871) and may also be invoked explicitly by
    /// tests.
    pub async fn run_merge_once(&self) -> Result<usize> {
        match self.try_run_merge_once().await {
            Some(result) => result,
            // Another pass holds the merge flag — same "skip" contract the
            // public signature always had.
            None => Ok(0),
        }
    }

    /// [`Self::run_merge_once`], but a lost `merge_in_progress` race is
    /// distinguishable from "evaluated, nothing to merge": `None` means the
    /// flag was held by another pass (background or `_forcemerge`) and NO
    /// policy evaluation happened. The #871 debounced check task needs the
    /// distinction — on `None` it must retry a cycle later instead of
    /// quiescing with a possibly-unevaluated segment set.
    pub(crate) async fn try_run_merge_once(&self) -> Option<Result<usize>> {
        use std::sync::atomic::Ordering as AtomicOrdering;

        // Serialise merges with ourselves (skip if another pass is running).
        if self
            .merge_in_progress
            .compare_exchange(false, true, AtomicOrdering::AcqRel, AtomicOrdering::Relaxed)
            .is_err()
        {
            return None;
        }
        // Ensure we clear the flag on every exit path.
        let _clear = MergeFlagClear(&self.merge_in_progress);
        // RC4 W4 item 2: record merge latency, but only for passes that
        // actually merged segments (n > 0). A pass that finds nothing to merge
        // returns immediately and must not pollute `merge_duration`.
        let merge_start = std::time::Instant::now();
        let result = self.merge_pass_locked(None).await;
        if let Ok(n) = &result {
            if *n > 0 {
                if let Some(m) = crate::engine_metrics() {
                    m.observe_merge(merge_start.elapsed().as_secs_f64());
                }
            }
        }
        Some(result)
    }

    /// True while a merge pass (background or forced) holds the merge flag.
    /// Exposed through `_stats` so callers (benchmarks) can verify the
    /// index is merge-quiescent before starting a measurement phase.
    pub fn is_merge_in_progress(&self) -> bool {
        self.merge_in_progress
            .load(std::sync::atomic::Ordering::Acquire)
    }

    /// #871 — how many merge-policy evaluations have run on this index
    /// (background debounced checks, hand-driven `run_merge_once`, and
    /// `_forcemerge` passes all count). The idle-cost contract is that this
    /// stays flat while the segment set does not change.
    pub fn merge_evaluation_count(&self) -> u64 {
        self.merge_evaluations
            .load(std::sync::atomic::Ordering::Relaxed)
    }

    /// #876 — how many documents this index's merges have re-analysed
    /// rather than merging their postings.
    ///
    /// Merging replays the input segments' posting lists, so the expected
    /// value is zero: a document's postings are built once, at flush, and
    /// every later merge copies them. A non-zero count means some batch fell
    /// back to the old rebuild — an input whose side-cars the preflight in
    /// [`fts_merge_readers`] would not vouch for, or the
    /// `XERJ_MERGE_FTS_REANALYZE` escape hatch — and that index is paying
    /// analysis cost proportional to (corpus size x merge levels).
    pub fn merge_reanalysed_document_count(&self) -> u64 {
        self.merge_fts_reanalysed_docs
            .load(std::sync::atomic::Ordering::Relaxed)
    }

    /// ES-style `_forcemerge`: run SYNCHRONOUSLY until the index has at
    /// most `max_num_segments` segments.
    ///
    /// Unlike `run_merge_once`, this does NOT bail out when a background
    /// pass currently holds the merge flag — it WAITS for the background
    /// pass to finish, takes the flag over, and then drives merge passes
    /// to convergence before returning.  The old behaviour (return
    /// `merged_batches: 0` immediately) meant a benchmark's
    /// "forcemerge + settle" step quiesced ES but left XERJ's background
    /// merge churning through the entire read phase, polluting every
    /// read-latency sample with merge CPU.
    ///
    /// On return the index is quiescent for the merged segment set: the
    /// memtable has been flushed, segments are merged to the target, and
    /// the size-tiered background policy selects no further work until
    /// new writes arrive.
    pub async fn force_merge(&self, max_num_segments: usize) -> Result<usize> {
        use std::sync::atomic::Ordering as AtomicOrdering;

        let target = max_num_segments.max(1);

        // NOTE: like ES, forcemerge operates on COMMITTED segments only —
        // it does not flush the memtable. (An earlier draft called
        // `self.refresh()` here; that exposed a pre-existing defect where
        // nested dense_vector kNN returns 0 hits once docs move from the
        // memtable into segments — see 135_knn_query_nested_search_ivf.yml.
        // Callers that want memtable docs included must refresh first,
        // exactly as with ES.)

        // Wait for any in-flight background pass instead of skipping.
        // 50 ms poll; background passes always terminate, and the HTTP
        // handler above us applies the request-level timeout.
        while self
            .merge_in_progress
            .compare_exchange(false, true, AtomicOrdering::AcqRel, AtomicOrdering::Relaxed)
            .is_err()
        {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        let _clear = MergeFlagClear(&self.merge_in_progress);

        let merge_start = std::time::Instant::now();
        let mut total = 0usize;
        loop {
            let n = self.merge_pass_locked(Some(target)).await?;
            total += n;
            let seg_count = self.store.snapshot().segments.len();
            // A small budget deferred every remaining batch. Waiting is
            // not "already at `target`": the inputs are still there.
            // The request timeout bounds the wait.
            if n == 0
                && seg_count > target
                && self
                    .merge_batches_deferred
                    .load(std::sync::atomic::Ordering::Relaxed)
            {
                tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                continue;
            }
            if n == 0 || seg_count <= target {
                break;
            }
        }
        // RC4 W4 item 2: record operator-triggered forcemerge latency (the whole
        // convergence) when it actually merged something, so `merge_duration`
        // reflects forcemerges too — background merges are recorded separately
        // in `run_merge_once`.
        if total > 0 {
            if let Some(m) = crate::engine_metrics() {
                m.observe_merge(merge_start.elapsed().as_secs_f64());
            }
        }
        Ok(total)
    }

    /// Process-memory budget the merge scheduler plans against, in bytes.
    ///
    /// A positive numeric `XERJ_MAX_PROCESS_MEMORY_MB` wins. Otherwise the
    /// installed governor's resolved cap. `0` when neither is present
    /// (engine unit tests that never call `Engine::new`): planning then
    /// keeps the historical 512 MiB batch.
    fn merge_process_budget_bytes() -> u64 {
        const MB: u64 = 1024 * 1024;
        if let Some(limit_mb) = std::env::var("XERJ_MAX_PROCESS_MEMORY_MB")
            .ok()
            .and_then(|raw| raw.trim().parse::<u64>().ok())
            .filter(|mb| *mb > 0)
        {
            return limit_mb.saturating_mul(MB);
        }
        crate::governor::global()
            .map(|governor| governor.process_memory_limit_bytes())
            .unwrap_or(0)
    }

    /// Upper bound on the total INPUT bytes of one merge batch.  Issue #948.
    ///
    /// The merge executor materialises decoded and re-encoded copies of
    /// every input document (measured 5-9x input bytes on mailbox-shaped
    /// docs: `merge_parsed` alone held 191 MB current on a 20k-doc index),
    /// so batch heap cost scales with bytes, not segment count.  Peers
    /// bound the same thing by memory, not count: Quickwit caps the bytes
    /// buffered by pending merge writers
    /// (`quickwit-parquet-engine/src/storage/streaming_writer.rs:378`
    /// `pending_writers_memory_size`) and streams segment files
    /// (`quickwit-parquet-engine/src/merge/streaming.rs:148`); tantivy's
    /// `LogMergePolicy` filters candidates by size before batching
    /// (`max_docs_before_merge`, `src/indexer/log_merge_policy.rs:22,94`).
    ///
    /// An explicit numeric `XERJ_MAX_PROCESS_MEMORY_MB` keeps
    /// `clamp(cap / 64, 32 MiB, 512 MiB)` — at a 16 GiB cap that is a
    /// 256 MiB batch. `auto`, `off`, and an unset variable read the
    /// governor's resolved budget ([`crate::merge_budget`]). A budget
    /// that still covers the historical 512 MiB batch keeps it, so a
    /// 16 GiB host does not merge in smaller pieces. A 4 GiB budget
    /// (the AUTO cap on an 8 GiB host) is 64 MiB.
    /// `XERJ_MERGE_BATCH_MAX_INPUT_MB` overrides (0 disables the bound).
    ///
    /// #2427: a batch that had to yield under memory pressure narrows this
    /// for every index through the governor's adaptive cap
    /// (`merge_budget::effective_batch_cap_bytes`).
    fn merge_batch_cap_bytes() -> u64 {
        let pressure_cap = crate::governor::global()
            .map(|governor| governor.merge_pressure_cap_bytes())
            .unwrap_or(0);
        crate::merge_budget::effective_batch_cap_bytes(
            Self::merge_static_batch_cap_bytes(),
            pressure_cap,
        )
    }

    fn merge_static_batch_cap_bytes() -> u64 {
        const MB: u64 = 1024 * 1024;
        if let Ok(raw) = std::env::var("XERJ_MERGE_BATCH_MAX_INPUT_MB") {
            if let Ok(mb) = raw.trim().parse::<u64>() {
                return mb.saturating_mul(MB);
            }
        }
        match std::env::var("XERJ_MAX_PROCESS_MEMORY_MB")
            .ok()
            .and_then(|raw| raw.trim().parse::<u64>().ok())
        {
            Some(limit_mb) if limit_mb > 0 => (limit_mb / 64).clamp(32, 512) * MB,
            _ => {
                crate::merge_budget::merge_batch_input_cap_bytes(Self::merge_process_budget_bytes())
            }
        }
    }

    /// One merge pass.  Caller MUST hold `merge_in_progress` (and clear it
    /// after — see `MergeFlagClear`).
    ///
    /// `force_max_segments: None` → size-tiered policy (background path).
    /// `Some(target)` → forcemerge selection: EVERY segment (large ones
    /// included — ES ignores the max-merged-segment cap on an explicit
    /// forcemerge) is chunked into `max_merge_count`-sized batches; the
    /// caller loops passes until the index converges to `target` segments.
    async fn merge_pass_locked(&self, force_max_segments: Option<usize>) -> Result<usize> {
        use std::sync::atomic::Ordering as AtomicOrdering;
        use xerj_fts::index::FtsIndexWriter;
        use xerj_storage::merge::{MergePolicy, SizeTieredMergePolicy};
        use xerj_storage::segment::{SectionType, SegmentId, SegmentReader, SegmentWriter};

        // #871 idle-cost observability: every pass that reaches this point
        // builds a merge policy and snapshots the segment registry — that IS
        // the per-tick idle cost the event-driven scheduler exists to remove,
        // so it is exactly what the counter measures. Background debounced
        // checks, hand-driven `run_merge_once`, and `_forcemerge` all count.
        self.merge_evaluations.fetch_add(1, AtomicOrdering::Relaxed);
        self.merge_batches_deferred
            .store(false, AtomicOrdering::Relaxed);

        // V4 M4.5 — larger merge batches so a bursty-ingest index with
        // thousands of small segments converges in far fewer passes.
        // Override via `XERJ_MAX_MERGE_COUNT` for battle tests that
        // want to collapse 2 k+ segments in a single pass.
        // M5.16 — merge memory bounds.
        //
        // Pre-M5.16 default max_merge_count was 64, which combined with
        // MERGE_PARALLELISM=4 meant up to 4 × 64 × ~30k = 7.6 M docs
        // held in per-batch `fts_input` / `dv_sources` Vec<Value>
        // simultaneously.  On the 20 M bq forcemerge that spiked RSS
        // to 93-117 GB and pushed the process to swap.
        //
        // Merge policy parameters from Config.merge — operators can tune
        // per-deployment without rebuilding. Defaults match the historical
        // hardcoded values (4 MiB tier floor, 8 GiB max merged segment,
        // min_merge_count=4, max_merge_count=16). The XERJ_MAX_MERGE_COUNT
        // env var was removed; use config.merge.max_merge_count instead.
        let mc = &self.merge_config;
        let policy = SizeTieredMergePolicy {
            min_merge_count: mc.min_merge_count as usize,
            max_merge_count: mc.max_merge_count as usize,
            tier_floor_bytes: mc.tier_floor_mb * 1024 * 1024,
            max_merged_segment_bytes: mc.max_segment_mb * 1024 * 1024,
            max_batch_input_bytes: Self::merge_batch_cap_bytes(),
        };

        let segments_snapshot_init = {
            let snap = self.store.snapshot();
            snap.segments.clone()
        };
        let batches: Vec<Vec<SegmentId>> = match force_max_segments {
            // Forcemerge: chunk every segment (smallest first) into
            // max_merge_count-sized batches, ignoring tier/size caps.
            // #948 — the byte cap still applies: an explicit forcemerge
            // on a mailbox index used to build one count-sized batch of
            // ~100 MB segments and hold ~16 GiB of decoded docs at once.
            // Multiple capped batches still converge to `target`
            // segments (the caller loops passes).
            Some(target) if segments_snapshot_init.len() > target => {
                let cap = Self::merge_batch_cap_bytes();
                let mut segs: Vec<&xerj_storage::segment::SegmentMeta> =
                    segments_snapshot_init.iter().collect();
                segs.sort_by_key(|s| s.size_bytes);
                let sizes: Vec<u64> = segs.iter().map(|s| s.size_bytes).collect();
                let ids: Vec<SegmentId> = segs.into_iter().map(|s| s.id.clone()).collect();
                let chunk_len = (mc.max_merge_count as usize).max(2);
                forcemerge_chunks(&sizes, chunk_len, cap)
                    .into_iter()
                    .map(|chunk| chunk.into_iter().map(|i| ids[i].clone()).collect())
                    .collect()
            }
            // #1122/#2433: at the target count, a forcemerge under
            // XERJ_STORE_SEMANTIC_VECTORS still rewrites each segment that
            // holds rows stored without their derived semantic vectors, so
            // the documented pre-downgrade `_forcemerge` restores them on an
            // index that is already one segment.
            Some(_) if xerj_storage::stored_codec::derived_vectors::store_vectors_opt_out() => {
                let segments_dir = self.data_dir.join("segments");
                segments_snapshot_init
                    .iter()
                    .filter(|meta| {
                        let Ok(reader) = SegmentReader::open(segments_dir.join(&meta.seg_path))
                        else {
                            return false;
                        };
                        matches!(
                            reader.section(SectionType::Stored),
                            Ok(Some(raw)) if xerj_storage::stored_codec::stored_has_derived_rows(raw)
                                .unwrap_or(false)
                        )
                    })
                    .map(|meta| vec![meta.id.clone()])
                    .collect()
            }
            Some(_) => Vec::new(),
            None => policy.select_merges(&segments_snapshot_init),
        };
        if batches.is_empty() {
            return Ok(0);
        }
        tracing::info!(
            num_segments_in = segments_snapshot_init.len(),
            num_batches = batches.len(),
            "run_merge_once: scheduling batches"
        );

        // Resolve per-field analyzer configs once for FTS rebuild.  See
        // `build_fts_field_configs` — keyword/numeric fields must use the
        // `keyword` analyzer or the FST drops their values to stop-words.
        let (field_configs, excluded_fts_fields, mapped_field_names) = {
            let schema = self.schema.read().await;
            (
                build_fts_field_configs(&schema.schema, self.segment_text_analyzer()),
                crate::memtable::fts_excluded_fields(&schema.schema),
                // #876 — a side-car whose field name is not a portable
                // filename is stored under a SHA-256 digest. Enumerating a
                // source segment's fields needs the names back, and the
                // mapping is where they live.
                schema
                    .schema
                    .fields
                    .iter()
                    .map(|field| field.name.clone())
                    .collect::<Vec<String>>(),
            )
        };
        // #876 escape hatch, matching `XERJ_MERGE_PARALLELISM`'s precedent:
        // force every merge back onto the re-analysing FTS rebuild. Exists so
        // an operator (and the A/B measurement in the PR) can pin the old
        // behaviour without a rebuild.
        let reanalyse_fts_on_merge = std::env::var("XERJ_MERGE_FTS_REANALYZE")
            .ok()
            .is_some_and(|value| value != "0");
        // Kept for the legacy "if !text_fields.is_empty()" branch — empty
        // here because the merge path now indexes ALL source fields, not
        // just declared text fields.  See the merge FTS rebuild block.
        let _text_fields: Vec<String> = Vec::new();

        let segments_dir = self.data_dir.join("segments");
        let mut merged_batches = 0usize;
        // P3.2 — collect the exact segment ids a merge drops so we can
        // evict only their per-segment cache entries (vs clearing the
        // whole dv_cache / stored_value_cache).
        let mut dropped_seg_ids: Vec<String> = Vec::new();

        // V4 M4.7 — PARALLEL BATCHES.  Previously the for-loop awaited
        // each batch's spawn_blocking before starting the next, so only
        // one merge ever ran at a time.  On a 2253-segment index that
        // meant ~1 merge per 90 s = 3.5 HOURS to converge.  Spawning all
        // batches in one sweep lets the blocking thread pool fan out to
        // ~N CPU cores, limited only by the rayon pool rebuilding FTS
        // side-cars and by disk write bandwidth.  Observed gain: ~8×
        // on a 32-core host with 60 concurrent batches.
        //
        // Cap parallelism at `MERGE_PARALLELISM` to avoid RAM blowup
        // during the big initial convergence pass — each concurrent
        // merge holds its full drained doc set in RAM.
        // V4 M4.8 — back to 4 after the byte-copy merge refactor cut
        // per-batch peak RAM by ~5×.  Was: 2 (forced down after the
        // pre-M4.8 OOM); pre-M4.7: 8 (OOM'd at 70 GB RSS).  Now each
        // batch holds at most one segment's worth of decoded bytes
        // plus a compact `(id, fields, source)` stream — total ≈ 200 MB
        // per batch on this workload.  4 × 200 MB = 800 MB peak instead
        // of 16 GB.
        // M5.16 — reduce from 4 → 1.  See max_merge_count comment above.
        // 4 parallel × 16 segments × 30k docs × 5 KB = 10 GB peak — still
        // too high for a 20 M-doc index.  Serial merges at 16 segments
        // each give ~2.4 GB peak and let the index converge in
        // predictable time without swapping.  Override via env var
        // for machines with more RAM.
        let configured_parallelism: usize = std::env::var("XERJ_MERGE_PARALLELISM")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(1);
        let merge_parallelism = crate::merge_budget::merge_parallelism_under_budget(
            configured_parallelism,
            Self::merge_process_budget_bytes(),
        );
        if merge_parallelism < configured_parallelism.max(1) {
            tracing::debug!(
                configured = configured_parallelism.max(1),
                running = merge_parallelism,
                "merge parallelism reduced to stay inside the process memory budget"
            );
        }
        use tokio::task::JoinHandle;
        type MergeOutput = (
            Vec<xerj_storage::segment::SegmentId>,
            xerj_storage::segment::SegmentMeta,
            usize,
            // (seq_no, doc_id) per surviving doc, in stored order — used to
            // write the merge output's `.ids` side-car after `apply_merge`
            // commits (flush already writes one; merge outputs previously
            // never got one, forcing the slow decode-stored fallback in
            // `rebuild_version_map_from_segments` on every reopen).
            Vec<(u64, String)>,
            // Immutable `(seq_no, id, deleted)` repoint intents. Building an
            // output must not mutate the live VersionMap before the driver
            // enters the collection publication interval.
            Vec<(u64, String, bool)>,
        );

        // Build the list of (batch, metas) pairs we'll launch.
        let mut launch_queue: Vec<(
            Vec<xerj_storage::segment::SegmentId>,
            Vec<xerj_storage::segment::SegmentMeta>,
        )> = Vec::new();
        for batch in batches {
            let snap = self.store.snapshot();
            let metas: Vec<xerj_storage::segment::SegmentMeta> = batch
                .iter()
                .filter_map(|id| snap.segments.iter().find(|s| &s.id == id).cloned())
                .collect();
            drop(snap);
            if metas.len() == batch.len() {
                launch_queue.push((batch, metas));
            }
        }

        // #1122 — on a small process budget, leave batches whose estimated
        // working set would cross the watermark. The first batch still
        // runs: merge is what retires per-segment caches. A budget that
        // still uses the 512 MiB batch starts every batch, which is the
        // path a 16 GiB host and larger already took.
        let budget_bytes = Self::merge_process_budget_bytes();
        let (rss_bytes, watermark_bytes) = match crate::governor::global() {
            Some(governor) => (
                governor.observed_rss_bytes(),
                governor.memory_watermark_bytes(),
            ),
            None => (0, 0),
        };
        let input_bytes: Vec<u64> = launch_queue
            .iter()
            .map(|(_, metas)| metas.iter().map(|meta| meta.size_bytes).sum())
            .collect();
        let plan = crate::merge_budget::throttle_merge_batches(
            &input_bytes,
            budget_bytes,
            rss_bytes,
            watermark_bytes,
        );
        let mut deferred = 0usize;
        let mut kept = Vec::with_capacity(launch_queue.len());
        for (item, start) in launch_queue.into_iter().zip(plan) {
            if start {
                kept.push(item);
            } else {
                deferred += 1;
            }
        }
        let launch_queue = kept;
        if deferred > 0 {
            self.merge_batches_deferred
                .store(true, AtomicOrdering::Relaxed);
            tracing::info!(
                deferred,
                rss_mb = rss_bytes / (1024 * 1024),
                watermark_mb = watermark_bytes / (1024 * 1024),
                "merge batches deferred: estimated working set would cross the memory watermark; inputs kept"
            );
        }

        // Derived once from the schema, then moved into each merge task: a
        // force-merge must not resurrect a doc-values column that flush
        // correctly skipped.
        let dv_skip = {
            let guard = self.schema.read().await;
            doc_values_skip_set(&guard.schema)
        };

        // Launch up to MERGE_PARALLELISM tasks at a time, consuming the
        // queue as tasks complete.  Results are applied back to the
        // snapshot in the order they finish (apply_merge is atomic).
        let mut in_flight: Vec<JoinHandle<Option<MergeOutput>>> = Vec::new();
        let mut queue_iter = launch_queue.into_iter();
        let mut pending = queue_iter.next();

        // LOSS FIREWALL (2026-07, S1): count batches that ABORTED because an
        // input segment could not be fully read (open / decode-stored / parse
        // failure) or the output could not be written.  Pre-fix, a decode
        // failure was `warn!(...); continue;` — the merge output was still
        // committed by `apply_merge`, which REMOVED the unread input segment
        // from the snapshot and deleted its files: every doc in it was
        // silently and permanently lost (live-verified: 752 → 254 docs on a
        // 48-segment forcemerge whose intermediate carried a CrossDep cycle,
        // see stored_codec.rs).  A merge must never commit unless every input
        // doc was read — aborted batches keep their inputs untouched and the
        // pass returns an ERROR so callers (forcemerge HTTP → 500, background
        // task → error log) hear about it loudly instead of losing data.
        let failed_batches = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        // #2427 — background batches that stopped because the breaker was
        // engaged with RSS at the process limit. Not a failure: inputs stay,
        // the pass is flagged deferred, and the governor narrows the next
        // batches (`merge_budget::merge_must_yield`).
        let yielded_batches = Arc::new(std::sync::atomic::AtomicUsize::new(0));

        // #2427 — process-wide admission. Every launch reserves the batch's
        // estimated working set against the RSS watermark through the
        // governor's merge ledger, so concurrent merges across indices see
        // each other before they allocate, and background merges wait while
        // the breaker is engaged. `None` = defer; `Some(None)` = no governor.
        let forced_merge = force_max_segments.is_some();
        let admit_merge = |metas: &[xerj_storage::segment::SegmentMeta]|
         -> Option<Option<crate::governor::MergeReservation>> {
            let Some(governor) = crate::governor::global() else {
                return Some(None);
            };
            let input: u64 = metas.iter().map(|meta| meta.size_bytes).sum();
            // #2427: reserve on the inputs' whole footprint. `size_bytes` is
            // the segment file alone; the side-cars the merge decodes are
            // usually several times larger (see
            // `merge_budget::MERGE_ON_DISK_WORKING_SET_NUMERATOR`).
            let ids: Vec<xerj_storage::segment::SegmentId> =
                metas.iter().map(|meta| meta.id.clone()).collect();
            let on_disk = self.store.segment_files_bytes(&ids);
            governor
                .try_reserve_merge_with_footprint(input, on_disk, forced_merge)
                .map(Some)
        };
        let mut governor_deferred = 0usize;

        let spawn_one = |batch: Vec<xerj_storage::segment::SegmentId>,
                         metas: Vec<xerj_storage::segment::SegmentMeta>,
                         reservation: Option<crate::governor::MergeReservation>|
         -> JoinHandle<Option<MergeOutput>> {
            let store_for_task = Arc::clone(&self.store);
            let registry_for_task = Arc::clone(&self.registry);
            let field_configs_for_task = field_configs.clone();
            // #937 — the text analyzer this merge writes (and whose term
            // space its replay gate demands of every input), resolved once
            // with the same rule the flush path uses.
            let text_analyzer_for_task = self.segment_text_analyzer();
            let excluded_fts_fields_for_task = excluded_fts_fields.clone();
            let mapped_field_names_for_task = mapped_field_names.clone();
            let reanalysed_docs_for_task = Arc::clone(&self.merge_fts_reanalysed_docs);
            let segments_dir_for_task = segments_dir.clone();
            let dv_skip_for_merge = dv_skip.clone();
            // #318 — the operator's `compression.level`, resolved once per
            // merge task. Merge is the only writer that honours it: it runs
            // on the nice-+15 SMALL pool, off the ingest critical path, which
            // is precisely why raising the effort here is safe and raising it
            // on flush was not.
            let merge_zstd_level = self.compression_config.level.zstd_level();
            // Ingest-regression fix: only an explicit `_forcemerge` (or the
            // `XERJ_MERGE_MAX_EFFORT` opt-in) pays for the level-19 stored
            // chooser. A background merge holds RSS at the breaker
            // watermark for as long as it runs, so its encode speed is
            // ingest throughput.
            let long_effort_merge = merge_uses_long_effort_stored_encode(
                force_max_segments.is_some(),
                std::env::var("XERJ_MERGE_MAX_EFFORT").ok().as_deref(),
            );
            let batch_for_task = batch;
            let metas_for_task = metas;
            let failed_for_task = Arc::clone(&failed_batches);
            let yielded_for_task = Arc::clone(&yielded_batches);
            let forced_for_task = force_max_segments.is_some();
            let input_bytes_for_task: u64 = metas_for_task.iter().map(|meta| meta.size_bytes).sum();
            // Checked at each input segment, every 8192 surviving docs, and
            // before the output segment is created — never after, so a
            // yielded batch leaves no partial output behind.
            let must_yield = move || -> bool {
                let Some(governor) = crate::governor::global() else {
                    return false;
                };
                if !governor.merge_must_yield_for(forced_for_task, input_bytes_for_task) {
                    return false;
                }
                let cap = governor.note_merge_yield(input_bytes_for_task);
                tracing::warn!(
                    input_mb = input_bytes_for_task / (1024 * 1024),
                    rss_mb = governor.observed_rss_bytes() / (1024 * 1024),
                    limit_mb = governor.process_memory_limit_bytes() / (1024 * 1024),
                    next_batch_cap_mb = cap / (1024 * 1024),
                    "merge batch yielded: memory pressure with RSS at the merge-pool ceiling; \
                     inputs kept, later batches narrowed"
                );
                true
            };
            // #2427 — the output-write step (doc-values build, stored
            // encode, FTS side-car build) runs after the last `must_yield`
            // checkpoint and is the batch's peak: large pg-docs merges took a
            // 3,072 MB search node to 4.4–4.9 GB there, about 5 s before they
            // completed. It is charged to the batch's merge reservation before
            // it starts, and refused (the batch yields, inputs kept, later
            // batches narrowed) when it would take RSS to the hard limit. See
            // `ResourceGovernor::admit_merge_write`.
            let admit_write = move |reservation: Option<&mut crate::governor::MergeReservation>,
                                    held: u64,
                                    extra: u64|
                  -> bool {
                let Some(governor) = crate::governor::global() else {
                    return true;
                };
                // #2468 lets a small background batch run to completion
                // after a streak of yields with nothing merged. When that
                // rule is what waived this batch's yield, the write runs
                // too, or refusing it would bring the stall back.
                let exempt = governor.merge_write_exempt(forced_for_task, input_bytes_for_task);
                if governor.admit_merge_write(reservation, held, extra, forced_for_task, exempt) {
                    return true;
                }
                let cap = governor.note_merge_yield(input_bytes_for_task);
                tracing::warn!(
                    input_mb = input_bytes_for_task / (1024 * 1024),
                    write_mb = extra / (1024 * 1024),
                    rss_mb = governor.observed_rss_bytes() / (1024 * 1024),
                    limit_mb = governor.process_memory_limit_bytes() / (1024 * 1024),
                    next_batch_cap_mb = cap / (1024 * 1024),
                    "merge batch yielded before its output write: the write would take RSS \
                     to the process limit; inputs kept, later batches narrowed"
                );
                false
            };
            // Held by the encode job until it ends, so the write step can
            // grow it (see `admit_write`).
            let mut reservation_for_encode = reservation;
            #[cfg(test)]
            let hold_merge_encode = Arc::clone(&self.test_hold_merge_encode);
            #[cfg(test)]
            let merge_encode_held = Arc::clone(&self.test_merge_encode_held);

            // #2234 — the encode used to run inside `spawn_blocking` +
            // `merge_pool().install`, which parked one tokio blocking-pool
            // thread for the whole encode (minutes on a large segment; the
            // shutdown path still names that leftover job). `_refresh` builds
            // its segment on that same blocking pool, so one in-progress
            // merge stalled refresh behind it. Queue the encode on the merge
            // pool and wait from this async driver. `spawn` returns as soon
            // as the job is queued. The #1122 inline fallback (the pool
            // cannot start a thread at all) still runs the encode on the
            // caller — the same degradation `install` already had.
            //
            // The CPU work is unchanged: decompress + byte-copy + FTS/DV
            // rebuild on the small nice-+15 merge pool (`crate::merge_pool`),
            // off the ingest pool that a merge used to stall.
            let (encode_tx, encode_rx) = tokio::sync::oneshot::channel();
            crate::merge_pool().spawn(move || {
                #[cfg(test)]
                if hold_merge_encode.load(Ordering::Acquire) {
                    merge_encode_held.store(true, Ordering::Release);
                    while hold_merge_encode.load(Ordering::Acquire) {
                        std::thread::sleep(std::time::Duration::from_millis(5));
                    }
                    merge_encode_held.store(false, Ordering::Release);
                }
                let encoded = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    use serde_json::value::RawValue;

                    // V4 M4.8 — STREAMING BYTE-COPY MERGE.
                    //
                    // Pre-M4.8 path materialised every source segment as
                    // `Vec<serde_json::Value>` (~1-2 KB heap per doc), held all
                    // 16 × 30 k = 480 k Values in RAM, then `to_vec(&merged_docs)`
                    // → `encode_stored_v2` (which parses back to `Vec<Value>`).
                    // ~2 GB working set per batch; with PARALLELISM=8 that hit
                    // 70 GB total RSS during the 2 291-segment forcemerge and
                    // crawled at 16 k docs/s.
                    //
                    // New path:
                    //   1. Decode ONE segment at a time (RAM ≈ 1 segment).
                    //   2. Parse it as `Vec<Box<RawValue>>` — each element is a
                    //      byte slice, NOT a deep `Value`.
                    //   3. Borrow-extract `_id` + `_seq_no` per doc with a tiny
                    //      `IdSeq<'_>` helper (no String alloc on the id).
                    //   4. Concatenate surviving doc byte slices straight into
                    //      `merged_json_buf` — no Value round-trip.
                    //   5. Parse the surviving doc's source ONCE for FTS / DV
                    //      (these still need a Value), but we don't HOLD them.
                    //      The Value drops at the end of the inner loop body —
                    //      only `fts_input` and `dv_sources` (compact) survive.
                    //
                    // Net: ~5× lower RAM per batch and ~3× faster, allowing
                    // PARALLELISM to be raised back from 2 to 4 and forcemerge
                    // to run in minutes, not hours.
                    #[derive(serde::Deserialize)]
                    struct IdSeq<'a> {
                        #[serde(rename = "_id", borrow)]
                        id: &'a str,
                        #[serde(rename = "_seq_no")]
                        seq_no: u64,
                    }

                    // #876 — decide BEFORE the stored-document pass whether this
                    // batch's FTS side-car can be MERGED (replay the inputs'
                    // posting lists) rather than REBUILT (re-analyse every
                    // surviving document). The rebuild needs that pass to collect
                    // `fts_input`; the merge does not, and skipping it is most of
                    // the win — a merged document's postings are already on disk
                    // and already correct, and size-tiered levelling re-derives
                    // them O(log N) times.
                    //
                    // Anything the postings merge cannot reproduce exactly puts
                    // the batch back on the rebuild: an unresolvable digest
                    // filename component, a segment whose side-cars will not
                    // open, a doc-carrying input with no FTS data at all, or a
                    // field whose stored shape (positions vs docs-only)
                    // contradicts what this writer would emit for it.
                    let merge_readers: Option<Vec<xerj_fts::index::FtsIndexReader>> =
                        if reanalyse_fts_on_merge {
                            None
                        } else {
                            fts_merge_readers(
                                &segments_dir_for_task,
                                &metas_for_task,
                                &field_configs_for_task,
                                &excluded_fts_fields_for_task,
                                &mapped_field_names_for_task,
                                text_analyzer_for_task,
                            )
                        };
                    let merge_postings = merge_readers.is_some();

                    // Ingest-memory attribution (#948): the replay path holds
                    // every input's decompressed postings + norms for the whole
                    // batch, and the same bytes bound the writer's in-memory
                    // rebuild (a merged posting list is the inputs' lists
                    // remapped, not re-derived). `retained_bytes` charges only
                    // what the reader OWNS (an mmap'd `.post` contributes 0),
                    // matching what this batch adds to the heap.
                    let merge_reader_bytes: u64 = merge_readers
                        .as_ref()
                        .map(|readers| {
                            readers
                                .iter()
                                .map(|reader| reader.retained_bytes())
                                .sum::<u64>()
                        })
                        .unwrap_or(0);
                    let merge_reader_retained = merge_readers.as_ref().map(|_| {
                        crate::ingest_memory::Retained::new(
                            crate::ingest_memory::Category::MergeDecoded,
                            merge_reader_bytes as usize,
                        )
                    });

                    // Per-phase attribution of one merge batch, gated on
                    // XERJ_PROF, matching the flush path's `XERJ_PROF
                    // flush-sidecar` line. The #876 A/B is read off `fts_us`.
                    let prof = std::env::var_os("XERJ_PROF").is_some();

                    let mut min_seq = u64::MAX;
                    let mut max_seq = 0u64;

                    // #1122: `Vec::with_capacity(60 MiB)` aborts the process
                    // when the allocator refuses (`memory allocation of N
                    // bytes failed`, no panic line). `try_reserve` of the
                    // same 60 MiB keeps the success path and turns a refusal
                    // into an aborted batch. Inputs stay on disk.
                    let mut merged_json_buf: Vec<u8> = Vec::new();
                    if let Err(error) = crate::merge_reserve::reserve_merge_output_buffer(
                        &mut merged_json_buf,
                        crate::merge_reserve::MERGE_OUTPUT_RESERVE_BYTES,
                    ) {
                        tracing::error!("{error}");
                        failed_for_task.fetch_add(1, Ordering::Relaxed);
                        return None;
                    }
                    if let Err(error) =
                        crate::merge_reserve::extend_merge_output(&mut merged_json_buf, b"[")
                    {
                        tracing::error!("{error}");
                        failed_for_task.fetch_add(1, Ordering::Relaxed);
                        return None;
                    }
                    let mut first_doc = true;
                    let mut live_doc_count: u64 = 0;

                    // M5.22 — merge memory halving via Arc<Value> fan-out.
                    //
                    // Pre-M5.22 `run_merge_once` held BOTH `fts_input: Vec<(_,_,Value)>`
                    // and `dv_sources: Vec<Value>` — one full `Value` per doc
                    // in each, which meant every merged doc occupied ~10 KB
                    // twice (the Value tree is heap-allocated and `Value::Object`
                    // is a HashMap<String, Value> with its own String keys).
                    // For a 16-segment batch of ~30 k docs each = 480 k docs ×
                    // 2 × 10 KB = ~10 GB per merge batch.  M5.16 capped batches
                    // to 16 and parallelism to 1 to keep worst case at ~2.4 GB,
                    // but the 2× duplication still doubles the working set.
                    //
                    // M5.22: store Arc<Value> once in fts_input, iterate the
                    // same source via `fts_input.iter().map(|(_, _, v)| Some(v))`
                    // for the doc-values pass.  Drops `dv_sources` entirely.
                    // Halves merge working memory and frees the Arc<Value>
                    // immediately after both passes complete.
                    // #2427: the third slot used to carry each surviving
                    // document's whole `_source` `Value` tree for the
                    // doc-values pass, held from the drain loop through the
                    // stored encode (which parses the same batch into a
                    // second `Vec<Value>` of its own), the FTS build and the
                    // doc-values build. Two full Value trees of the batch
                    // were live at once after the last yield point. The
                    // doc-values columns are now built from `merged_json_buf`
                    // one document at a time (`merge_doc_value_sources`), so
                    // the slot is empty.
                    let mut fts_input: Vec<(
                        String,
                        HashMap<String, xerj_fts::index::FieldValues>,
                        (),
                    )> = Vec::new();
                    // (seq_no, doc_id) for every surviving doc — kept exactly
                    // aligned with the stored-section byte copy (pushed right
                    // after `live_doc_count += 1`, BEFORE the per-doc Value
                    // parse that can `continue`), so the `.ids` side-car covers
                    // all stored docs even if a doc fails the FTS/DV re-parse.
                    let mut ids_pairs: Vec<(u64, String)> = Vec::new();

                    // ES tie-order parity (LOSS_BATTLE_PLAN B1): collect every
                    // surviving doc as (seq_no, _id, raw JSON) FIRST, then sort
                    // globally by _seq_no and derive ALL four merge outputs
                    // (stored bytes / .ids side-car / FTS input / DV input) from
                    // that ONE sorted stream.  Ingest hash-routes docs across 16
                    // memtable shards and each shard flushes its own segment, so
                    // input-order concatenation scrambled physical row order vs
                    // insertion (_seq_no) order — ES tie-breaks equal scores by
                    // internal doc id == arrival order, so every constant-score
                    // top-k diverged from ES.  With physical == seq order the
                    // existing doc-position tie-breaks ARE the ES tie-break; no
                    // comparator changes anywhere.  Memory: the owned raw copy
                    // replaces the same bytes that previously went straight into
                    // `merged_json_buf` (drained into it below), so the peak
                    // stays ~1× stored size + the fts_input Values, unchanged
                    // from the M5.22 profile.
                    // #876 adds the source coordinates: `(input index, that
                    // input's own document ordinal)`. The postings merge needs to
                    // know where each surviving document CAME FROM to remap its
                    // doc ids, and the global `_seq_no` sort below scrambles the
                    // per-input order, so the pair has to ride along.
                    let mut survivors: Vec<(u64, String, String, u32, u32)> = Vec::new();
                    // #948 attribution: running estimate of the survivor
                    // set's retained bytes (raw JSON + id + tuple), observed
                    // once per input segment as a sampled checkpoint.
                    let mut survivor_bytes: usize = 0;
                    // One entry per document in each input segment, in that
                    // segment's own ordinal order: the merged ordinal it becomes,
                    // or `None` if it does not survive.
                    let mut doc_maps: Vec<Vec<Option<u32>>> =
                        vec![Vec::new(); metas_for_task.len()];

                    // RC4 W2 #14 — union of the inputs' SEQ-AWARE tombstone
                    // sections (ZTB2), max seq per doc.  A load-bearing
                    // tombstone (doc deleted, an OLDER copy possibly live in
                    // a segment OUTSIDE this batch) must survive the merge:
                    // its input segment is removed by `apply_merge`, so
                    // without carry-forward the next restart's rebuild would
                    // resurrect the older copy.
                    let mut tomb_union: HashMap<String, u64> = HashMap::new();

                    for (source_index, meta) in metas_for_task.iter().enumerate() {
                        if must_yield() {
                            yielded_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                        min_seq = min_seq.min(meta.min_seq_no);
                        max_seq = max_seq.max(meta.max_seq_no);
                        let seg_path = segments_dir_for_task.join(&meta.seg_path);
                        // LOSS FIREWALL (S1): every failure to fully read an
                        // input segment ABORTS the whole batch (`return None`
                        // — inputs stay live in the snapshot, nothing is
                        // committed or deleted).  The old `continue` dropped
                        // the segment's docs from the merge output while
                        // `apply_merge` still removed the input: silent,
                        // permanent data loss.
                        let reader = match SegmentReader::open(&seg_path) {
                            Ok(r) => r,
                            Err(e) => {
                                tracing::error!(
                                    ?seg_path,
                                    "merge ABORTED: failed to open input segment \
                                     (inputs preserved, no docs dropped): {e}"
                                );
                                failed_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                        };
                        // Collect tombstones BEFORE the stored-section read:
                        // tombstone-only segments (doc_count 0) `continue`
                        // out of the doc pass below but their pairs must
                        // still ride along.  A tombstone section that fails
                        // to read/decode aborts the batch like any other
                        // unreadable input (dropping it silently would
                        // resurrect deleted docs after the inputs are gone).
                        if meta.has_tombstones {
                            match reader.section(SectionType::Tombstones) {
                                Ok(Some(tb)) => {
                                    match xerj_storage::segment::decode_tombstones_v2(tb) {
                                        Some(pairs) => {
                                            for (seq, id) in pairs {
                                                let e = tomb_union.entry(id).or_insert(0);
                                                if seq > *e {
                                                    *e = seq;
                                                }
                                            }
                                        }
                                        None if tb.starts_with(b"ZTB2") => {
                                            // Corrupt V2 payload — dropping it
                                            // silently would resurrect deleted
                                            // docs once the input is removed.
                                            tracing::error!(
                                                ?seg_path,
                                                "merge ABORTED: corrupt ZTB2 tombstone \
                                                 section (inputs preserved)"
                                            );
                                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                                            return None;
                                        }
                                        // Legacy id-only JSON payload: no seq
                                        // info — those deletes are WAL-pinned,
                                        // not segment-durable; nothing to carry.
                                        None => {}
                                    }
                                }
                                Ok(None) => {}
                                Err(e) => {
                                    tracing::error!(
                                        ?seg_path,
                                        "merge ABORTED: failed to read tombstone section \
                                         (inputs preserved): {e}"
                                    );
                                    failed_for_task.fetch_add(1, Ordering::Relaxed);
                                    return None;
                                }
                            }
                        }
                        let stored_bytes_raw = match reader.section(SectionType::Stored) {
                            Ok(Some(b)) => b,
                            Ok(None) => {
                                // A doc-less segment legitimately has no
                                // stored section; a doc-CARRYING one missing
                                // it would lose docs — abort.
                                if meta.doc_count == 0 {
                                    continue;
                                }
                                tracing::error!(
                                    ?seg_path,
                                    doc_count = meta.doc_count,
                                    "merge ABORTED: input segment has docs but no \
                                     stored section (inputs preserved)"
                                );
                                failed_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                            Err(e) => {
                                tracing::error!(
                                    ?seg_path,
                                    "merge ABORTED: failed to read stored section \
                                     (inputs preserved, no docs dropped): {e}"
                                );
                                failed_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                        };
                        let stored_bytes =
                            // #1122/#2433: keep stripped semantic vectors
                                // stripped (the merged encode would only
                                // re-derive and drop them again), unless
                                // XERJ_STORE_SEMANTIC_VECTORS restores them.
                            match xerj_storage::stored_codec::decode_stored_for_rewrite(
                                stored_bytes_raw,
                            ) {
                                Ok(b) => b,
                                Err(e) => {
                                    tracing::error!(
                                        ?seg_path,
                                        "merge ABORTED: failed to decode stored section \
                                         (inputs preserved, no docs dropped): {e}"
                                    );
                                    failed_for_task.fetch_add(1, Ordering::Relaxed);
                                    return None;
                                }
                            };
                        // Ingest-memory attribution (#948): one guard per
                        // input for its decompressed stored section, held
                        // until this iteration ends (the RawValue parse and
                        // the survivor scan both read it; the buffer drops
                        // with the iteration scope).
                        let _stored_guard = crate::ingest_memory::Retained::new(
                            crate::ingest_memory::Category::MergeDecoded,
                            stored_bytes.len(),
                        );
                        // `Box<RawValue>` uses a serde-private newtype tag that
                        // simd_json's serde adapter does not recognise — the
                        // deserialiser fails with "invalid type: newtype struct,
                        // expected any valid JSON value" on every segment, the
                        // `continue` below skips the entire segment, and merge
                        // silently loses every document in it.  Use serde_json
                        // here (which DOES handle RawValue correctly).  All other
                        // simd_json call sites in this file parse to `Vec<Value>`
                        // which doesn't trigger the RawValue private path.
                        //
                        // Bonus: serde_json takes `&[u8]` immutably so we don't
                        // need the `.to_vec()` the simd_json path required.
                        let raw_docs: Vec<Box<RawValue>> =
                            match serde_json::from_slice(&stored_bytes) {
                                Ok(d) => d,
                                Err(e) => {
                                    tracing::error!(
                                        ?seg_path,
                                        "merge ABORTED: failed to parse stored as RawValue \
                                         (inputs preserved, no docs dropped): {e}"
                                    );
                                    failed_for_task.fetch_add(1, Ordering::Relaxed);
                                    return None;
                                }
                            };

                        // The FTS/doc-values ordinal space of a segment is the
                        // order of its stored documents, so the map is exactly as
                        // long as this vector. `vec![None; n]` aborts if that
                        // allocation is refused (#1122); `try_reserve` does not.
                        let mut ordinals = Vec::new();
                        if ordinals.try_reserve(raw_docs.len()).is_err() {
                            tracing::error!(
                                ?seg_path,
                                docs = raw_docs.len(),
                                "merge aborted: not enough memory to reserve the document map; \
                                 input segments were preserved and the node stayed up"
                            );
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                        ordinals.resize(raw_docs.len(), None);
                        doc_maps[source_index] = ordinals;
                        for (source_ordinal, raw) in raw_docs.iter().enumerate() {
                            // #2427 — the survivor scan copies each input's
                            // live docs, so a batch can grow hundreds of MB
                            // inside one input. Check the governor every
                            // `MERGE_YIELD_CHECKPOINT_DOCS` docs, not only
                            // between inputs.
                            if source_ordinal > 0
                                && (source_ordinal as u64)
                                    .is_multiple_of(crate::merge_budget::MERGE_YIELD_CHECKPOINT_DOCS)
                                && must_yield()
                            {
                                yielded_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                            let raw_str = raw.get();
                            let id_seq: IdSeq = match serde_json::from_str(raw_str) {
                                Ok(v) => v,
                                Err(e) => {
                                    // A doc we cannot even extract (_id, _seq_no)
                                    // from must not be silently dropped either.
                                    tracing::error!(
                                        ?seg_path,
                                        "merge ABORTED: stored doc failed _id/_seq_no \
                                         parse (inputs preserved): {e}"
                                    );
                                    failed_for_task.fetch_add(1, Ordering::Relaxed);
                                    return None;
                                }
                            };
                            if id_seq.id.is_empty() {
                                continue;
                            }
                            if let Some(entry) = store_for_task.version_map.get(id_seq.id) {
                                if entry.deleted {
                                    continue;
                                }
                                if entry.seq_no > id_seq.seq_no {
                                    continue;
                                }
                            }

                            // Survives — hold (seq, id, raw) for the global
                            // _seq_no-ordered build below. Growth is fallible:
                            // `push` aborts the process when the allocator
                            // refuses (#1122).
                            if let Err(error) = crate::merge_reserve::try_push_merge(
                                &mut survivors,
                                (
                                    id_seq.seq_no,
                                    id_seq.id.to_string(),
                                    raw_str.to_string(),
                                    source_index as u32,
                                    source_ordinal as u32,
                                ),
                            ) {
                                tracing::error!("{error}");
                                failed_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                            survivor_bytes = survivor_bytes.saturating_add(
                                raw_str.len()
                                    + id_seq.id.len()
                                    + std::mem::size_of::<(u64, String, String, u32, u32)>(),
                            );
                        }
                        // raw_docs + stored_bytes drop here — segment RAM reclaimed.
                        // One sampled checkpoint per input segment: the
                        // survivor set grows monotonically inside the input
                        // loop, so the trailing edge of the peak is at most
                        // one input's worth of growth (#948 attribution).
                        crate::ingest_memory::observe_checkpoint(
                            crate::ingest_memory::Category::MergeSurvivor,
                            survivor_bytes,
                        );
                    }

                    // Global insertion-order (_seq_no) sort — see the B1 note
                    // above.  seq_nos are unique per surviving doc (stale /
                    // duplicate copies were filtered by the version map).
                    survivors.sort_unstable_by_key(|(seq, _, _, _, _)| *seq);

                    // Single sorted stream → all four outputs.  `into_iter`
                    // frees each raw String right after its bytes are copied
                    // into `merged_json_buf`, keeping peak memory ~1× stored.
                    let mut drain_checkpoint = 0u64;
                    let mut fts_input_bytes: usize = 0;
                    for (seq_no, id_str, raw_str, source_index, source_ordinal) in survivors {
                        if !first_doc {
                            if let Err(error) = crate::merge_reserve::extend_merge_output(
                                &mut merged_json_buf,
                                b",",
                            ) {
                                tracing::error!("{error}");
                                failed_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                        }
                        first_doc = false;
                        if let Err(error) = crate::merge_reserve::extend_merge_output(
                            &mut merged_json_buf,
                            raw_str.as_bytes(),
                        ) {
                            tracing::error!("{error}");
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                        live_doc_count += 1;
                        // The .ids side-car must cover every stored doc
                        // (alignment invariant, see above).
                        if let Err(error) = crate::merge_reserve::try_push_merge(
                            &mut ids_pairs,
                            (seq_no, id_str.clone()),
                        ) {
                            tracing::error!("{error}");
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }

                        // Per-doc Value parse for FTS / DV builders.
                        //
                        // A document whose stored bytes will not re-parse still
                        // takes its seat in `fts_input`. These bytes already
                        // parsed as a `RawValue` above, so reaching the fallback
                        // is close to impossible — but `continue`-ing out of the
                        // push (which is what this did) shifts every LATER
                        // document's FTS and doc-values ordinal one place off its
                        // stored ordinal, and that alignment is what every reader
                        // addresses a document by. An empty `_source` indexes and
                        // columnises nothing for it, which is the same as the
                        // skip minus the shift.
                        // The merged FTS/doc-values ordinal is this document's
                        // index in `fts_input`.
                        doc_maps[source_index as usize][source_ordinal as usize] =
                            Some(fts_input.len() as u32);
                        // The re-analysis input. `merge_postings` replays the
                        // inputs' posting lists instead, so it needs no field
                        // values and no per-document parse at all (#2427: the
                        // doc-values pass re-reads `merged_json_buf`). An
                        // empty `HashMap` allocates nothing. The `Value` the
                        // rebuild parses drops at the end of this iteration.
                        let fields = if merge_postings {
                            HashMap::new()
                        } else {
                            let doc_value: Value =
                                serde_json::from_str(&raw_str).unwrap_or_else(|error| {
                                    tracing::warn!(
                                        doc = %id_str,
                                        "merge: surviving doc failed its re-parse, indexing it empty: {error}"
                                    );
                                    Value::Null
                                });
                            let source = doc_value.get("_source").unwrap_or(&Value::Null);
                            // #948 attribution: the transient parse, per doc,
                            // only when tracing is enabled.
                            if crate::ingest_memory::enabled() {
                                fts_input_bytes = fts_input_bytes
                                    .saturating_add(crate::ingest_memory::estimated_json_heap(source));
                            }
                            extract_fts_fields_excluding(source, &excluded_fts_fields_for_task)
                        };
                        if let Err(error) =
                            crate::merge_reserve::try_push_merge(&mut fts_input, (id_str, fields, ()))
                        {
                            tracing::error!("{error}");
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                        // Sampled checkpoints every 8192 drained docs: the
                        // survivor set shrinks as `merged_json_buf` and
                        // `fts_input` grow, so the crossover IS the batch's
                        // stored-side peak.
                        drain_checkpoint += 1;
                        // #2427 — the yield check runs every
                        // `MERGE_YIELD_CHECKPOINT_DOCS` docs. At 8192 a pg-docs
                        // batch on the 1 GB gate grew RSS 300+ MB past the
                        // watermark between two checks.
                        if drain_checkpoint
                            .is_multiple_of(crate::merge_budget::MERGE_YIELD_CHECKPOINT_DOCS)
                            && must_yield()
                        {
                            yielded_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                        if drain_checkpoint.is_multiple_of(8192) {
                            crate::ingest_memory::observe_checkpoint(
                                crate::ingest_memory::Category::MergeJsonBuffer,
                                merged_json_buf.len(),
                            );
                            crate::ingest_memory::observe_checkpoint(
                                crate::ingest_memory::Category::MergeParsed,
                                fts_input_bytes,
                            );
                        }
                    }
                    // Drained: the survivors vec is empty now.
                    crate::ingest_memory::observe_checkpoint(
                        crate::ingest_memory::Category::MergeSurvivor,
                        0,
                    );

                    if live_doc_count == 0 {
                        return None;
                    }
                    if let Err(error) =
                        crate::merge_reserve::extend_merge_output(&mut merged_json_buf, b"]")
                    {
                        tracing::error!("{error}");
                        failed_for_task.fetch_add(1, Ordering::Relaxed);
                        return None;
                    }
                    crate::ingest_memory::observe_checkpoint(
                        crate::ingest_memory::Category::MergeJsonBuffer,
                        merged_json_buf.len(),
                    );
                    crate::ingest_memory::observe_checkpoint(
                        crate::ingest_memory::Category::MergeParsed,
                        fts_input_bytes,
                    );

                    if must_yield() {
                        yielded_for_task.fetch_add(1, Ordering::Relaxed);
                        return None;
                    }
                    // #2427 — last chance to stop: everything below allocates
                    // on top of what the batch holds now and cannot yield.
                    // Charge it to the merge budget first, or yield.
                    {
                        let json_bytes = merged_json_buf.len() as u64;
                        let fts_bytes = fts_input_bytes as u64;
                        let write_fts_bytes = if merge_postings {
                            merge_reader_bytes
                        } else {
                            fts_bytes
                        };
                        let held = json_bytes
                            .saturating_add(fts_bytes)
                            .saturating_add(merge_reader_bytes);
                        let extra = crate::merge_budget::merge_write_phase_bytes(
                            json_bytes,
                            write_fts_bytes,
                        );
                        if !admit_write(reservation_for_encode.as_mut(), held, extra) {
                            yielded_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                    }
                    // Doc-values columns, built here from the merged stored
                    // JSON one document at a time (#2427) and written once the
                    // merged segment id exists, below. The columns are what
                    // survives; the per-document `_source` trees do not.
                    // Before, those trees were held in `fts_input` for the
                    // whole batch, through the stored encode that parses the
                    // same documents into a second `Vec<Value>`: two decoded
                    // copies of the batch at once, past the last yield point.
                    let dv_timer = std::time::Instant::now();
                    let dv_columns = match merge_doc_value_sources(&merged_json_buf) {
                        Ok(sources) => Some(build_doc_value_columns(sources, &dv_skip_for_merge)),
                        Err(e) => {
                            tracing::warn!(
                                "merge: merged stored JSON did not re-parse for doc-values, \
                                 segment ships no doc-values side-car: {e}"
                            );
                            None
                        }
                    };
                    let dv_build_us = dv_timer.elapsed().as_micros();
                    // Write merged stored section using the columnar v2 codec.
                    let mut writer = match SegmentWriter::new(&segments_dir_for_task, 1, 0, 0) {
                        Ok(w) => w,
                        Err(e) => {
                            tracing::error!("merge ABORTED: failed to create writer: {e}");
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                    };
                    let stored_timer = std::time::Instant::now();
                    // The merge entry also runs the per-column long-effort
                    // zstd chooser (#1038) only on an explicit `_forcemerge`
                    // or the opt-in; background merges use the plain level.
                    let encoded = if long_effort_merge {
                        xerj_storage::stored_codec::encode_stored_v2_forcemerge_at_level(
                            &merged_json_buf,
                            merge_zstd_level,
                        )
                    } else {
                        xerj_storage::stored_codec::encode_stored_v2_merge_at_level(
                            &merged_json_buf,
                            merge_zstd_level,
                        )
                    };
                    // #948 attribution: the compressed output buffer is an
                    // exact owned length; it coexists with the drained buffer
                    // for one encode call.
                    let _encoded_guard = crate::ingest_memory::Retained::new(
                        crate::ingest_memory::Category::MergeEncoded,
                        encoded.len(),
                    );
                    let stored_us = stored_timer.elapsed().as_micros();
                    drop(merged_json_buf);
                    crate::ingest_memory::observe_checkpoint(
                        crate::ingest_memory::Category::MergeJsonBuffer,
                        0,
                    );
                    if let Err(e) = writer.add_section(SectionType::Stored, &encoded) {
                        tracing::error!("merge ABORTED: failed to add section: {e}");
                        failed_for_task.fetch_add(1, Ordering::Relaxed);
                        return None;
                    }

                    // RC4 W2 #14 — carry still-load-bearing tombstones into
                    // the merged output.  GC rule (mirrors the
                    // `sweep_pending_deletes` unpin proof): a tombstone
                    // subsumed by a strictly newer, SEGMENT-durable live
                    // version can be dropped — every rebuild would ignore it
                    // anyway (max-seq-wins).  Everything else is carried:
                    // an older copy of the doc may live in a segment outside
                    // this batch, and the tombstone is what keeps it dead
                    // across restarts.
                    let tomb_carry: Vec<(u64, String)> = tomb_union
                        .into_iter()
                        .filter(|(id, seq)| {
                            !matches!(store_for_task.version_map.get(id),
                                Some(e)
                                    if !e.deleted
                                        && e.seq_no > *seq
                                        && &*e.segment_id
                                            != xerj_storage::version_map::IN_MEMORY_SEGMENT_ID)
                        })
                        .map(|(id, seq)| (seq, id))
                        .collect();
                    if !tomb_carry.is_empty() {
                        let pair_refs: Vec<(u64, &str)> = tomb_carry
                            .iter()
                            .map(|(seq, id)| (*seq, id.as_str()))
                            .collect();
                        if let Err(e) = writer.add_section(
                            SectionType::Tombstones,
                            xerj_storage::segment::encode_tombstones_v2(&pair_refs),
                        ) {
                            tracing::error!("merge ABORTED: failed to add tombstone section: {e}");
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                    }

                    let merged_meta = match writer.finish(live_doc_count, min_seq, max_seq) {
                        Ok(m) => m,
                        Err(e) => {
                            tracing::error!("merge ABORTED: failed to finish segment: {e}");
                            failed_for_task.fetch_add(1, Ordering::Relaxed);
                            return None;
                        }
                    };
                    // #804: count the merge-written segment's on-disk bytes.
                    if let Some(m) = crate::engine_metrics() {
                        m.record_bytes_written(merged_meta.size_bytes);
                    }

                    let fts_timer = std::time::Instant::now();
                    // Build FTS side-cars using the parallel per-field builder.
                    // We pre-built `fts_input` during the byte-copy pass above,
                    // so this is just one rayon `add_documents_parallel` call.
                    {
                        let mut fts_writer = FtsIndexWriter::new(
                            &segments_dir_for_task,
                            merged_meta.id.as_str(),
                            Arc::clone(&registry_for_task),
                        )
                        .with_zstd_level(merge_zstd_level);
                        for (field_name, cfg) in &field_configs_for_task {
                            fts_writer.configure_field(field_name.clone(), cfg.clone());
                        }
                        if !fts_input.is_empty() {
                            // Dedicated merge pool: a merged-segment FTS build
                            // is the single longest rayon job in the system —
                            // on the global pool it queued every concurrent
                            // search's par_iter behind it (read-under-write
                            // collapse), and on the ingest pool it stalled
                            // every bulk request (see `crate::merge_pool`).
                            // Same-pool install here is a no-op re-entry —
                            // the whole batch already runs inside merge_pool.
                            let built = crate::merge_pool()
                                .install(|| -> std::result::Result<(), String> {
                                match merge_readers.as_ref() {
                                    // #876 — replay the inputs' postings.
                                    Some(readers) => {
                                        let sources: Vec<xerj_fts::index::FtsMergeSource<'_>> =
                                            readers
                                                .iter()
                                                .zip(doc_maps.iter())
                                                .map(|(reader, doc_map)| {
                                                    xerj_fts::index::FtsMergeSource {
                                                        reader,
                                                        doc_map: doc_map.as_slice(),
                                                    }
                                                })
                                                .collect();
                                        fts_writer
                                            .merge_from_segments(&sources)
                                            .map_err(|e| e.to_string())?;
                                    }
                                    None => {
                                        reanalysed_docs_for_task.fetch_add(
                                            fts_input.len() as u64,
                                            Ordering::Relaxed,
                                        );
                                        fts_writer.add_documents_parallel(&fts_input)
                                    }
                                }
                                if fts_writer
                                    .uses_case_distinguished_field_filename_components()
                                {
                                    if let Err(e) = store_for_task
                                        .ensure_fts_case_distinguished_field_component_format()
                                    {
                                        return degrade_fts_publish(
                                            &segments_dir_for_task,
                                            merged_meta.id.as_str(),
                                            &format!("{e:#}"),
                                        )
                                        .map_err(|error| error.to_string());
                                    }
                                    if let Err(e) = fts_writer
                                        .publish_case_distinguished_filename_layout()
                                    {
                                        return degrade_fts_publish(
                                            &segments_dir_for_task,
                                            merged_meta.id.as_str(),
                                            &format!("{e:#}"),
                                        )
                                        .map_err(|error| error.to_string());
                                    }
                                } else if fts_writer.uses_encoded_field_filename_components() {
                                    if let Err(e) = store_for_task
                                        .ensure_fts_encoded_field_component_format()
                                    {
                                        return degrade_fts_publish(
                                            &segments_dir_for_task,
                                            merged_meta.id.as_str(),
                                            &format!("{e:#}"),
                                        )
                                        .map_err(|error| error.to_string());
                                    }
                                    if let Err(e) =
                                        fts_writer.publish_encoded_filename_layout()
                                    {
                                        return degrade_fts_publish(
                                            &segments_dir_for_task,
                                            merged_meta.id.as_str(),
                                            &format!("{e:#}"),
                                        )
                                        .map_err(|error| error.to_string());
                                    }
                                }
                                if let Err(e) = fts_writer.finish() {
                                    degrade_fts_publish(
                                        &segments_dir_for_task,
                                        merged_meta.id.as_str(),
                                        &format!("{e:#}"),
                                    )
                                    .map_err(|error| error.to_string())?;
                                }
                                Ok(())
                            });
                            // A postings-merge failure, or a side-car publish
                            // failure whose leftover files could not be removed,
                            // aborts the batch: the inputs stay live. A publish
                            // failure that left no FTS files does not: the
                            // merged segment is searched by stored scan until a
                            // later merge rebuilds full text (#2349).
                            if let Err(message) = built {
                                tracing::error!(
                                    "merge ABORTED: postings merge failed (inputs \
                                     preserved): {message}"
                                );
                                failed_for_task.fetch_add(1, Ordering::Relaxed);
                                return None;
                            }
                        }
                    }

                    let fts_us = fts_timer.elapsed().as_micros();
                    // Release the inputs' decompressed postings before the
                    // doc-values build, which is now the batch's memory peak.
                    drop(merge_readers);
                    drop(merge_reader_retained);

                    // Update version_map so doc → segment_id points to the
                    // merged segment, using each doc's REAL seq_no from
                    // `ids_pairs` (collected during the byte-copy pass).
                    //
                    // CRITICAL correctness fix (2026-07): the previous code set
                    // EVERY surviving doc's entry to the segment's `max_seq`
                    // ("monotone upper bound").  That poisoned the version map:
                    // on the NEXT merge round the survivor filter compares
                    // `entry.seq_no > stored._seq_no` and, with entry.seq_no
                    // faked to max_seq, every doc except the one that actually
                    // owns max_seq looks stale and is dropped.  Any second-
                    // level merge (merged segment merged again — routine on a
                    // converging index) silently discarded ~all docs; live-
                    // verified as 200 k → 12 docs after one background merge
                    // cascade.  The loss was masked on restart only because
                    // merged-away input segments were never deleted from disk
                    // and `recover_orphaned_segments` resurrected them — a
                    // crutch removed by the merge-commit file deletion below.
                    //
                    // `set_if_latest` (>= guard) rather than unconditional
                    // `set`: a doc updated while the merge ran already has a
                    // newer entry that must not be clobbered by the merged
                    // (older) copy.
                    let mut version_repoint_intents =
                        Vec::with_capacity(ids_pairs.len().saturating_add(tomb_carry.len()));
                    version_repoint_intents
                        .extend(ids_pairs.iter().map(|(seq, id)| (*seq, id.clone(), false)));
                    version_repoint_intents
                        .extend(tomb_carry.iter().map(|(seq, id)| (*seq, id.clone(), true)));

                    // Doc-values side-car — the columns were built before the
                    // stored encode (#2427, see `dv_columns`).
                    let dv_timer = std::time::Instant::now();
                    if let Some(columns) = dv_columns {
                        if !columns.is_empty() {
                            if let Err(e) = write_doc_values_sidecar_at_level(
                                &segments_dir_for_task,
                                merged_meta.id.as_str(),
                                &columns,
                                merge_zstd_level,
                            ) {
                                tracing::warn!("merge: doc-values write failed: {e:#}");
                            }
                        }
                    }

                    let dv_us = dv_build_us + dv_timer.elapsed().as_micros();
                    // `fts_input` (raw ids + the re-analysis field values;
                    // no `_source` trees since #2427) survives its last
                    // reader here — the batch's parsed-side attribution ends
                    // with it.
                    crate::ingest_memory::observe_checkpoint(
                        crate::ingest_memory::Category::MergeParsed,
                        0,
                    );
                    if prof {
                        eprintln!(
                            "XERJ_PROF merge-batch inputs={} docs={live_doc_count} \
                             fts={} stored_us={stored_us} fts_us={fts_us} dv_us={dv_us}",
                            metas_for_task.len(),
                            if merge_postings { "replayed" } else { "reanalysed" },
                        );
                    }

                    Some((
                        batch_for_task,
                        merged_meta,
                        live_doc_count as usize,
                        ids_pairs,
                        version_repoint_intents,
                    ))
                }));
                // Held until the encode (the allocation-heavy part: stored
                // decode, FST and doc-values build) has finished.
                drop(reservation_for_encode);
                let _ = encode_tx.send(encoded);
            });
            tokio::spawn(async move {
                match encode_rx.await {
                    Ok(Ok(value)) => {
                        if value.is_some() && !forced_for_task {
                            if let Some(governor) = crate::governor::global() {
                                governor.note_merge_completed(input_bytes_for_task);
                            }
                        }
                        value
                    }
                    Ok(Err(payload)) => std::panic::resume_unwind(payload),
                    // The encode task vanished without a result. Panic so the
                    // driver counts a failed batch (the `JoinError` arm)
                    // instead of treating a lost encode as an empty output
                    // and dropping its inputs.
                    Err(_closed) => panic!("merge encode dropped its result"),
                }
            })
        };

        // Launch the pending batch if the governor admits it (#2427). A
        // refusal leaves it and every later batch of this pass unmerged and
        // flags the pass deferred, so the scheduler retries after the drain.
        macro_rules! launch_next {
            () => {
                match pending.take() {
                    Some((batch, metas)) => match admit_merge(&metas) {
                        Some(reservation) => {
                            in_flight.push(spawn_one(batch, metas, reservation));
                            pending = queue_iter.next();
                            true
                        }
                        None => {
                            governor_deferred += 1 + queue_iter.by_ref().count();
                            false
                        }
                    },
                    None => false,
                }
            };
        }

        // Fill in_flight up to the cap, then drain one-by-one as they
        // complete, launching replacements from `queue_iter`.
        while in_flight.len() < merge_parallelism {
            if !launch_next!() {
                break;
            }
        }
        while !in_flight.is_empty() {
            // Await the first handle in the queue.  tokio doesn't provide
            // a built-in "select any", but for small parallelism this FIFO
            // drain is fine — the encodes run concurrently on the merge
            // pool anyway, we're just reaping their results in submission
            // order.
            let handle = in_flight.remove(0);
            match handle.await {
                Ok(Some((
                    batch_slice,
                    merged_meta,
                    live_doc_count,
                    ids_pairs,
                    version_repoint_intents,
                ))) => {
                    // Warm the merged segment's stored slices BEFORE the
                    // swap makes it visible: the first sorted-candidates
                    // queries after a merge otherwise each pay the fresh
                    // multi-100 MB stored-section decompress inside their
                    // own latency (dec=1.1-3.8 s p99 spikes at every merge
                    // completion under the mixed read/write bench).  On the
                    // blocking pool — the decompress is CPU-bound and must
                    // not stall the async merge driver.
                    let prepublication_lease = {
                        let w_store = Arc::clone(&self.store);
                        let w_caches = self.publish_warm_caches();
                        let w_dir = self.data_dir.join("segments");
                        let w_id = merged_meta.id.clone();
                        let w_docs = merged_meta.doc_count;
                        let lease = PrePublicationLease::known(w_caches.clone(), w_id.clone());
                        let worker_lease = lease.clone();
                        let warm_join = tokio::task::spawn_blocking(move || {
                            warm_segment_at_publish(&w_store, &w_dir, &w_caches, &w_id, w_docs);
                            drop(worker_lease);
                        })
                        .await;
                        if let Err(error) = warm_join {
                            tracing::warn!(
                                merged_id = merged_meta.id.as_str(),
                                "merge: pre-publication cache warm failed: {error}"
                            );
                            // Warming is optional. Remove any partial entries
                            // left before the panic, then publish the valid
                            // merge output cold.
                            self.publish_warm_caches()
                                .remove_failed_output(merged_meta.id.as_str());
                        }
                        // Keep the parent lease armed across all work between
                        // warm and publication.
                        lease
                    };
                    // Mixed-RUW: seed the merged segment's SHORTCUT-COUNT
                    // cache from its inputs, BEFORE the swap makes it
                    // visible.  Per-segment shortcut counts are PHYSICAL
                    // (delete-blind — the `deletes_present` gate discards
                    // them globally when ghosts exist) and segments are
                    // disjoint doc sets, so for any cached query shape the
                    // merged segment's count is EXACTLY the sum of its
                    // inputs' cached counts — PROVIDED the merge dropped no
                    // docs (output doc_count == Σ input doc_counts; a merge
                    // that dropped superseded/tombstoned docs skips seeding
                    // and the first query rebuilds as before).  Without
                    // this, the first count-bearing query after every merge
                    // publish re-ran the O(doc_count) fused per-segment
                    // walk INLINE — live-measured 477 ms at a 2.3M-doc
                    // output, with the single-flight/cold-miss convoying
                    // every concurrent same-shape reader behind it (the
                    // mixed `bool` p99 cliff, 431-452 ms at iso 40k docs/s).
                    {
                        let inputs: std::collections::HashSet<&str> =
                            batch_slice.iter().map(|s| s.as_str()).collect();
                        let pre = self.store.snapshot();
                        let in_metas: Vec<&xerj_storage::segment::SegmentMeta> = pre
                            .segments
                            .iter()
                            .filter(|m| inputs.contains(m.id.as_str()))
                            .collect();
                        let input_docs: u64 = in_metas.iter().map(|m| m.doc_count).sum();
                        if in_metas.len() == batch_slice.len()
                            && merged_meta.doc_count == input_docs
                        {
                            // shape → (inputs seen with this shape, running sum)
                            let mut sums: HashMap<String, (usize, u64)> = HashMap::new();
                            for e in self.shortcut_count_cache.iter() {
                                let (seg, shape) = e.key();
                                if inputs.contains(seg.as_str()) {
                                    let ent = sums.entry(shape.clone()).or_insert((0, 0));
                                    ent.0 += 1;
                                    ent.1 = ent.1.saturating_add(*e.value());
                                }
                            }
                            for (shape, (n, sum)) in sums {
                                // Only when EVERY input had the shape cached
                                // is the sum the complete merged count.
                                if n == batch_slice.len()
                                    && self.shortcut_count_cache.len() < SHORTCUT_COUNT_CACHE_MAX
                                {
                                    self.shortcut_count_cache
                                        .insert((merged_meta.id.to_string(), shape), sum);
                                }
                            }
                        }
                    }
                    #[cfg(test)]
                    {
                        self.test_merge_repoint_ready.store(true, Ordering::Release);
                        while self.test_pause_merge_before_apply.load(Ordering::Acquire) {
                            tokio::task::yield_now().await;
                        }
                        self.test_merge_repoint_ready
                            .store(false, Ordering::Release);
                    }
                    // Segment construction is private scratch work. Enter the
                    // collection epoch only for the short authoritative
                    // VersionMap + durable snapshot publication performed by
                    // storage's transactional apply.
                    let mut collection_publication = self
                        .collection_publication
                        .begin()
                        .map_err(|_| collection_publication_interrupted())?;
                    let mut version_repoints =
                        xerj_storage::version_map::VersionRepointTransaction::with_capacity(
                            Arc::clone(&self.store.version_map),
                            version_repoint_intents.len(),
                        );
                    let merged_arc: Arc<str> = Arc::from(merged_meta.id.as_str());
                    for (seq_no, id, deleted) in &version_repoint_intents {
                        version_repoints.repoint_if_latest(
                            id,
                            *seq_no,
                            Arc::clone(&merged_arc),
                            *deleted,
                        );
                    }
                    #[cfg(test)]
                    self.publication_test_point(
                        merged_meta.id.as_str(),
                        PublicationTestPoint::MergeAfterRepoint,
                    );
                    #[cfg(test)]
                    tokio::task::yield_now().await;
                    #[cfg(test)]
                    let apply_result = if self
                        .test_fail_merge_before_apply
                        .swap(false, Ordering::AcqRel)
                    {
                        Err(
                            xerj_storage::index_store::MergePublicationError::NotPublished(
                                xerj_storage::StorageError::MergeAborted(
                                    "injected merge apply failure before snapshot publication"
                                        .into(),
                                ),
                            ),
                        )
                    } else if self
                        .test_panic_after_merge_publish
                        .swap(false, Ordering::AcqRel)
                    {
                        self.store.apply_merge_with_repoints_and_post_publish(
                            &batch_slice,
                            merged_meta.clone(),
                            version_repoints,
                            || panic!("injected panic after durable merge publication"),
                        )
                    } else {
                        self.store.apply_merge_with_repoints(
                            &batch_slice,
                            merged_meta.clone(),
                            version_repoints,
                        )
                    };
                    #[cfg(not(test))]
                    let apply_result = self.store.apply_merge_with_repoints(
                        &batch_slice,
                        merged_meta.clone(),
                        version_repoints,
                    );
                    match &apply_result {
                        Ok(xerj_storage::index_store::MergePublicationOutcome::Published {
                            ..
                        }) => collection_publication.commit(),
                        Err(xerj_storage::index_store::MergePublicationError::NotPublished(_)) => {
                            collection_publication.cancel();
                        }
                        Err(xerj_storage::index_store::MergePublicationError::Indeterminate {
                            ..
                        }) => {
                            // Pending Drop poisons the index. Recovery/reopen is
                            // the only authority that can classify this state.
                        }
                    }
                    drop(collection_publication);
                    self.collection_publication.handoff_to_readers().await;
                    if let Err(e) = apply_result {
                        tracing::warn!("merge: apply_merge failed: {e:?}");
                        failed_batches.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        // Seeded shortcut counts for a segment that never
                        // became visible — drop them. The armed lease removes
                        // all seven hydration owners when this scope exits.
                        self.shortcut_count_cache
                            .retain(|(seg, _), _| seg != merged_meta.id.as_str());
                        // `continue` bypasses the common top-up below. Launch
                        // the next disjoint batch first so one failed apply
                        // does not silently suppress the rest of this pass.
                        launch_next!();
                        continue;
                    }
                    // `apply_merge` has made the output authoritative. No
                    // await is permitted between publication and this commit.
                    prepublication_lease.commit();
                    {
                        // Write the merge output's `.ids` side-car AFTER the
                        // merge is committed: if we crashed before
                        // `apply_merge`, an output segment carrying a valid
                        // `.ids` would be resurrected by
                        // `recover_orphaned_segments` on restart alongside
                        // its still-live inputs (duplicate docs).  Written
                        // here, a crash in between merely loses the side-car
                        // and reopen falls back to the (slow but correct)
                        // decode-stored path — the pre-fix status quo.
                        //
                        // Issue #965 — in object-store mode this is
                        // `finalize_merge_output`: the same `.ids` write,
                        // then a synthesized ZCM1 manifest, then the family
                        // packed into ONE bundle object, then the bucket
                        // catalogue. The catalogue still names the INPUTS
                        // until it succeeds, so on failure the inputs must
                        // NOT be retired below — the bucket would keep a
                        // consistent pre-merge view whose replacement bytes
                        // never landed, and deleting the local input files
                        // would make those referenced bundles unrecoverable.
                        // Local mode keeps today's warn-and-continue exactly.
                        let mut merge_finalize_failed_in_object_mode = false;
                        {
                            let pairs: Vec<(u64, &str)> = ids_pairs
                                .iter()
                                .map(|(seq, id)| (*seq, id.as_str()))
                                .collect();
                            if let Err(e) = self.store.finalize_merge_output(&merged_meta, &pairs) {
                                if self.store.is_object_store_mode() {
                                    tracing::error!(
                                        merged_id = merged_meta.id.as_str(),
                                        "merge: durable publication of the merged segment \
                                         failed; input retirement skipped to keep the bucket \
                                         catalogue consistent: {e}"
                                    );
                                    merge_finalize_failed_in_object_mode = true;
                                } else {
                                    tracing::warn!(
                                        merged_id = merged_meta.id.as_str(),
                                        "merge: failed to write .ids sidecar: {e}"
                                    );
                                }
                            }
                        }
                        if merge_finalize_failed_in_object_mode {
                            failed_batches.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                            // Keep the local input families: they are still
                            // the bucket catalogue's referenced set. The
                            // merged output stays locally authoritative; the
                            // next catalog publish self-heals it (bundle
                            // upload for every snapshot-listed segment).
                            dropped_seg_ids.extend(batch_slice.iter().cloned());
                            // Same pipeline rule as the failed-apply path: the
                            // `continue` below bypasses the loop's bottom
                            // top-up, so launch the next disjoint batch here.
                            launch_next!();
                            continue;
                        }
                        // Disk-space fix (2026-07): the input segments are
                        // now unreachable from the (persisted) snapshot —
                        // reclaim their files instead of leaving them for
                        // the next restart's orphan cleanup (~137 MB of
                        // dead segments after the 1 M-doc benchmark).
                        // Drop the cached SegmentReader mmaps first so the
                        // kernel can actually free the unlinked blocks once
                        // in-flight readers finish (in-flight queries that
                        // already hold an Arc<SegmentReader> keep working —
                        // unlink under a live mmap is safe on Linux).
                        for id in &batch_slice {
                            self.store.evict_segment_reader_cache(id.as_str());
                        }
                        // Merge-race fix (2026-07, follow-up to the disk
                        // fix): RETIRE, don't delete.  An immediate unlink
                        // raced in-flight searches that had snapshotted the
                        // pre-merge segment list but not yet opened every
                        // segment — the scan silently skipped the vanished
                        // segment and undercounted hits.total (observed
                        // live: 798,281 instead of 932,037).
                        // `retire_segment_files` deletes right away when no
                        // snapshot read lease is outstanding, otherwise it
                        // parks the ids in a graveyard swept by the last
                        // lease drop — so deferral is bounded by the
                        // longest-running in-flight query, not a restart.
                        let (rm_files, rm_bytes) =
                            match self.store.retire_segment_files(&batch_slice) {
                                Ok(removed) => removed,
                                Err(error) => {
                                    tracing::error!(
                                        merged_id = merged_meta.id.as_str(),
                                        inputs = batch_slice.len(),
                                        %error,
                                        "merge committed but durable input retirement failed"
                                    );
                                    failed_batches
                                        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                                    (0, 0)
                                }
                            };
                        tracing::info!(
                            merged_id = merged_meta.id.as_str(),
                            inputs = batch_slice.len(),
                            live_docs = live_doc_count,
                            removed_files = rm_files,
                            removed_mb = rm_bytes / 1_000_000,
                            deferred = rm_files == 0,
                            "segment merge complete"
                        );
                        // These input segment ids are now unreachable —
                        // record them for precise per-segment cache
                        // eviction below.
                        dropped_seg_ids.extend(batch_slice.iter().cloned());
                        merged_batches += 1;
                    }
                }
                Ok(None) => {}
                Err(e) => {
                    tracing::error!("merge: encode task panicked: {e}");
                    failed_batches.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
            }
            // Top up in_flight.
            launch_next!();
        }
        let yielded = yielded_batches.load(AtomicOrdering::Relaxed);
        if yielded > 0 {
            self.merge_batches_deferred
                .store(true, AtomicOrdering::Relaxed);
            tracing::info!(
                index = %self.name,
                yielded,
                "merge batches yielded under memory pressure; inputs kept"
            );
        }
        if governor_deferred > 0 {
            self.merge_batches_deferred
                .store(true, AtomicOrdering::Relaxed);
            if let Some(governor) = crate::governor::global() {
                tracing::info!(
                    index = %self.name,
                    deferred = governor_deferred,
                    rss_mb = governor.observed_rss_bytes() / (1024 * 1024),
                    watermark_mb = governor.memory_watermark_bytes() / (1024 * 1024),
                    merge_reserved_mb = governor.merge_reserved_bytes() / (1024 * 1024),
                    merges_in_flight = governor.merges_in_flight(),
                    breaker_engaged = governor.memory_breaker_engaged(),
                    "merge batches deferred by the memory governor; inputs kept"
                );
            }
        }

        // If we applied any merges, bump the dataset version (invalidates
        // the query_cache) and evict ONLY the dropped segments' entries
        // from the per-segment dv_cache / stored_value_cache. P3.2: the
        // segments that survived the merge are immutable and their cached
        // doc-values / stored fields remain valid, so we no longer clear
        // the whole maps (which cold-started every post-merge read).
        if merged_batches > 0 {
            self.dataset_version.fetch_add(1, AtomicOrdering::Release);
            self.query_cache.clear();
            // Pair with cold-load publication's read guard. `apply_merge`
            // already removed these ids from the authoritative snapshot:
            // a loader that checked before retirement must publish before
            // this writer and be removed here; one that arrives after this
            // writer sees the retired snapshot and cannot publish.
            {
                let _publication = self.segment_cache_lifecycle.write();
                for id in &dropped_seg_ids {
                    self.remove_segment_hydration_entries(id.as_str());
                }
            }
            // Do not remove `stored_value_loads` here. Callers holding the
            // pre-merge snapshot are entitled to receive that immutable
            // producer's result; the producer removes its own single-flight
            // key on completion, and the lifecycle transaction above
            // prevents it from retaining the retired value in the cache.
            for id in &dropped_seg_ids {
                self.fast_date_cache
                    .retain(|(seg, _), _| seg != id.as_str());
                self.fast_date_sorted_cache
                    .retain(|(seg, _), _| seg != id.as_str());
                // Sort-key shadows are keyed "{seg}\u{1}{field}" and hold
                // an O(doc_count) Vec each — without eviction every
                // merged-away segment leaked its shadows for the process
                // lifetime under a sustained writer.
                let shadow_prefix = format!("{}\u{1}", id.as_str());
                self.shortcut_count_cache
                    .retain(|(seg, _), _| seg != id.as_str());
                self.range_prefilter_cache
                    .retain(|k, _| !k.starts_with(&shadow_prefix));
                self.stored_slices_build_locks.remove(id.as_str());
            }
        }

        // LOSS FIREWALL (S1): surface aborted batches as a hard error AFTER
        // the successful batches' cache eviction above (their apply_merge
        // already committed and must stay coherent).  Aborted batches kept
        // their input segments — no document was dropped — but the caller
        // must hear about it: `_forcemerge` returns HTTP 500 instead of
        // pretending the index converged, and the background merge task
        // logs an error every pass until the offending segment is repaired.
        let failed = failed_batches.load(std::sync::atomic::Ordering::Relaxed);
        if failed > 0 {
            return Err(EngineError::Common(xerj_common::XerjError::internal(
                format!(
                    "merge pass aborted {failed} batch(es): an input segment could not \
                     be fully read, the output could not be written, or there was not \
                     enough memory to build the merged segment; input segments \
                     were preserved (no documents dropped, the node stayed up, \
                     {merged_batches} other batch(es) merged)"
                ),
            )));
        }

        Ok(merged_batches)
    }

    /// #871 — the debounce window between a segment-set change and the
    /// merge check it schedules. `XERJ_MERGE_INTERVAL_SECS` keeps its
    /// historical meaning (benchmarks push it up so merges don't pollute
    /// ingest-rate measurements): it is now the debounce delay instead of a
    /// free-running tick period. Default 5 s — the old tick cadence, so a
    /// burst of flushes still collapses on the same schedule as before.
    fn merge_check_delay() -> std::time::Duration {
        let secs = std::env::var("XERJ_MERGE_INTERVAL_SECS")
            .ok()
            .and_then(|s| s.parse::<u64>().ok())
            .unwrap_or(5);
        std::time::Duration::from_secs(secs.max(1))
    }

    /// #871 — the segment set changed (the [`IndexStore`
    /// segments-changed hook](xerj_storage::index_store::IndexStore::set_segments_changed_hook)
    /// lands here): bump the event epoch, then make sure a debounced merge
    /// check is scheduled.
    fn on_segments_changed(self: &Arc<Self>) {
        self.merge_events
            .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        self.request_merge_check();
    }

    /// #871 — schedule a debounced merge-policy check for this index.
    ///
    /// Replaces the per-index tick task (`spawn_merge_task`) that gave
    /// EVERY index a tokio timer waking every 5 s forever, writes or no
    /// writes — measured 93 wakeups/s and 15-27% of a core at the
    /// customer-reported 464 idle indices. Merge scheduling is now
    /// event-driven, mirroring the #334 WAL-fsync scheduler
    /// (`xerj-storage/src/wal_fsync.rs`): the storage layer fires its
    /// segments-changed hook on every segment-set change — flush
    /// publication, merge application, tombstone-only segment, orphan
    /// recovery: the only events that can create a merge candidate — and
    /// that hook lands here via [`Self::on_segments_changed`]. Lucene's
    /// writer works the same way: `IndexWriter.maybeMerge` runs on flush
    /// (IndexWriter.java:706,:3681 — MergeTrigger.FULL_FLUSH) and on merge
    /// completion (IndexWriter.java:2452 — MERGE_FINISHED), never on a
    /// clock (lucene corpus, Apache-2.0; design mirrored, no code copied).
    ///
    /// Contract:
    /// * Arming is idempotent — any number of events inside one debounce
    ///   window cost one task (`merge_check_armed` swap).
    /// * The armed task sleeps [`Self::merge_check_delay`], evaluates once,
    ///   and loops only while there is a reason to: the pass lost the merge
    ///   flag to `_forcemerge` (`try_run_merge_once` → `None`, nothing was
    ///   evaluated), the pass errored (the same every-pass retry the old
    ///   tick gave a damaged segment — see the LOSS FIREWALL note in
    ///   `merge_pass_locked`), or the segment set changed since the cycle
    ///   started (`merge_events` epoch). Otherwise it disarms and EXITS —
    ///   an idle index holds zero tasks, zero timers, zero wakeups.
    /// * Merge cascades need no special case: applying a merge fires the
    ///   hook, so the follow-up evaluation schedules itself.
    /// * The disarm race (an event between the epoch check and the disarm
    ///   observed `armed == true` and spawned nothing) is closed by
    ///   re-checking the epoch after the disarm and re-arming on the
    ///   event's behalf.
    ///
    /// The task handle is stored in `self.merge_task` so the SIGTERM path
    /// (`abort_background_tasks`, via `Engine::flush_all_force`) can break
    /// the debounce `tokio::time::sleep` — the same shutdown-hang contract
    /// the tick task had; `merge_scheduling_stopped` then keeps any later
    /// event from re-arming.
    pub fn request_merge_check(self: &Arc<Self>) {
        use std::sync::atomic::Ordering as AtomicOrdering;
        if self.merge_scheduling_stopped.load(AtomicOrdering::SeqCst) {
            return;
        }
        // Resolve the runtime BEFORE arming: if there is nowhere to spawn,
        // leaving `armed` set would eat the next event's arm. The hook can
        // fire from a blocking-pool thread (flush finalize), where
        // `try_current` still resolves; the coord's cached handle covers
        // any path outside every runtime context.
        let rt = match tokio::runtime::Handle::try_current() {
            Ok(handle) => handle,
            Err(_) => match self.flush_signal.runtime() {
                Some(handle) => handle.clone(),
                None => return, // no runtime; the next event retries
            },
        };
        if self.merge_check_armed.swap(true, AtomicOrdering::SeqCst) {
            return; // already scheduled — debounced
        }
        let weak = Arc::downgrade(self);
        let delay = Self::merge_check_delay();
        let handle = rt.spawn(async move {
            loop {
                // Epoch BEFORE the sleep: any event after this read either
                // re-runs this loop (epoch mismatch below) or re-arms after
                // the exit path's disarm.
                let seen = match weak.upgrade() {
                    Some(idx) => idx.merge_events.load(AtomicOrdering::SeqCst),
                    None => return,
                };
                tokio::time::sleep(delay).await;
                let Some(idx) = weak.upgrade() else { return };
                if idx.merge_scheduling_stopped.load(AtomicOrdering::SeqCst) {
                    idx.merge_check_armed.store(false, AtomicOrdering::SeqCst);
                    return;
                }
                let outcome = idx.try_run_merge_once().await;
                let retry = match &outcome {
                    // Lost the flag to `_forcemerge`/another pass: nothing
                    // was evaluated, so we still owe the arming event a
                    // pass.
                    None => true,
                    Some(Err(e)) => {
                        tracing::warn!("merge pass failed: {e}");
                        true
                    }
                    Some(Ok(n)) => {
                        if *n > 0 {
                            tracing::debug!(batches = n, "merge pass ran");
                        }
                        // Batches left behind under a small budget need
                        // another check after the debounce sleep. A pass
                        // that merged something already bumps
                        // `merge_events`; this covers the pass that
                        // started nothing because every extra batch waited.
                        idx.merge_batches_deferred.load(AtomicOrdering::Relaxed)
                    }
                };
                if retry || idx.merge_events.load(AtomicOrdering::SeqCst) != seen {
                    continue;
                }
                idx.merge_check_armed.store(false, AtomicOrdering::SeqCst);
                if idx.merge_events.load(AtomicOrdering::SeqCst) != seen {
                    // An event slipped in between the epoch check and the
                    // disarm: it saw `armed` and spawned nothing. Re-arm on
                    // its behalf.
                    idx.request_merge_check();
                }
                return;
            }
        });
        // Replace the previous handle. It is either None or a task on its
        // way out (a new arm is only possible after the old task disarmed,
        // i.e. past its last await) — dropping it detaches those final
        // instructions, never a pending sleep.
        *self.merge_task.lock() = Some(handle);
        if self.merge_scheduling_stopped.load(AtomicOrdering::SeqCst) {
            // Lost a race with `abort_background_tasks` between the check at
            // the top and the handle store above: finish the abort's job so
            // no debounce sleep outlives shutdown.
            if let Some(handle) = self.merge_task.lock().take() {
                handle.abort();
            }
            self.merge_check_armed.store(false, AtomicOrdering::SeqCst);
        }
    }

    /// Stop this index's background merge scheduling permanently and abort
    /// the armed check task, if any.
    ///
    /// Idempotent and safe to call from a signal handler.  After this
    /// returns, no merge task is holding the tokio runtime alive, so once
    /// axum's listeners stop and the final flush completes, the runtime
    /// exits cleanly instead of waiting up to the debounce delay for a
    /// `tokio::time::sleep` to wake on its own (the bench-found SIGTERM
    /// hang).  `merge_scheduling_stopped` is set FIRST so a segments-changed
    /// hook firing concurrently (e.g. from the shutdown flush that follows
    /// in `Engine::flush_all_force`) cannot re-arm after the abort; the
    /// re-check at the end of `request_merge_check` closes the remaining
    /// interleaving.  The aborted task itself is still being unwound, so
    /// ingest-side callers MUST NOT rely on merges running after this.
    /// Called from `Engine::flush_all_force` and by hand-driven test
    /// fixtures that drive every merge themselves.
    pub fn abort_background_tasks(&self) {
        self.merge_scheduling_stopped
            .store(true, std::sync::atomic::Ordering::SeqCst);
        if let Some(handle) = self.merge_task.lock().take() {
            handle.abort();
        }
        // RC4 W2 item 17: an in-flight HNSW stale rebuild must not hold
        // the runtime (or the index Arc) alive across shutdown. Aborting
        // mid-rebuild is safe: `hnsw_stale` is only cleared AFTER a
        // convergent pass, so an interrupted rebuild leaves the ANN path
        // disabled (brute force serves) and the next open retries.
        if let Some(handle) = self.hnsw_rebuild_task.lock().take() {
            handle.abort();
        }
        // #392: same treatment for in-flight SQ8 code-store walks. An
        // interrupted walk leaves `ready` false (exact scan serves) and the
        // next open retries.
        let walk_handles: Vec<Arc<Sq8StoreHandle>> =
            self.sq8_stores.read().values().cloned().collect();
        for handle in walk_handles {
            if let Some(handle) = handle.walk_task.lock().take() {
                handle.abort();
            }
        }
    }

    /// Update a document with upsert support.
    ///
    /// - If the document exists: merge `partial_doc` fields into existing source.
    /// - If the document does not exist and `upsert_doc` is `Some`: create it
    ///   using `upsert_doc` (then merge `partial_doc` on top if both provided).
    /// - If the document does not exist and `doc_as_upsert` is `true`: use
    ///   `partial_doc` itself as the creation body.
    /// - Otherwise (no doc, no upsert): return `None` (not found).
    ///
    /// Merges use [`Self::deep_merge_json`] — a partial update of one nested
    /// field preserves that object's siblings (ES semantics), not a shallow
    /// top-level replace (#821).
    ///
    /// ES `_update` `doc` semantics: recursively merge `patch` into `target`.
    /// For a key present in both where BOTH values are objects, merge
    /// recursively; otherwise the patch value replaces the target's (arrays and
    /// scalars replace, `null` sets). Without this, a partial update of one
    /// nested field silently dropped the object's other fields (#821 data-loss).
    fn deep_merge_json(target: &mut Value, patch: Value) {
        match (target, patch) {
            (Value::Object(t), Value::Object(p)) => {
                for (k, v) in p {
                    match t.get_mut(&k) {
                        Some(tv) => Self::deep_merge_json(tv, v),
                        None => {
                            t.insert(k, v);
                        }
                    }
                }
            }
            (t, p) => *t = p,
        }
    }

    pub async fn update_document_with_upsert(
        &self,
        id: &str,
        partial_doc: Option<Value>,
        upsert_doc: Option<Value>,
        doc_as_upsert: bool,
    ) -> Result<Option<IndexResponse>> {
        let publication_guard = self.write_publication.lock(id.to_string()).await;
        match self.get_document(id).await? {
            Some(existing) => {
                // Document exists — merge partial_doc on top.
                let merged = if let Some(patch) = partial_doc {
                    match &existing {
                        Value::Object(map) => {
                            let mut merged = Value::Object(map.clone());
                            if patch.is_object() {
                                Self::deep_merge_json(&mut merged, patch.clone());
                            }
                            merged
                        }
                        _ => {
                            if patch.is_object() {
                                patch.clone()
                            } else {
                                existing.clone()
                            }
                        }
                    }
                } else {
                    existing.clone()
                };
                // ES `update` returns `result: noop` when the merge would
                // not change the source. Detect by comparing the merged
                // object against the existing source.
                if merged == existing {
                    self.noop_update_count.fetch_add(1, Ordering::Relaxed);
                    let current = self.store.version_map.get(id);
                    return Ok(Some(IndexResponse {
                        id: id.to_string(),
                        seq_no: current.as_ref().map(|entry| entry.seq_no).unwrap_or(0),
                        version: current.map(|entry| entry.version).unwrap_or(1),
                        result: "noop".to_string(),
                    }));
                }
                let resp = self
                    .index_document_with_version_inner_guarded(
                        Some(id.to_string()),
                        merged,
                        None,
                        None,
                        false,
                        Some(publication_guard),
                        false,
                        None,
                    )
                    .await?;
                Ok(Some(resp))
            }
            None => {
                // Document does not exist.
                if doc_as_upsert {
                    // Use partial_doc as the creation body.
                    let body = partial_doc.unwrap_or(Value::Object(serde_json::Map::new()));
                    let resp = self
                        .index_document_with_version_inner_guarded(
                            Some(id.to_string()),
                            body,
                            None,
                            None,
                            false,
                            Some(publication_guard),
                            false,
                            None,
                        )
                        .await?;
                    Ok(Some(resp))
                } else if let Some(upsert_body) = upsert_doc {
                    // Create with upsert body, then merge partial_doc on top.
                    let body = if let Some(patch) = partial_doc {
                        match upsert_body {
                            Value::Object(map) => {
                                let mut merged = Value::Object(map);
                                if patch.is_object() {
                                    Self::deep_merge_json(&mut merged, patch.clone());
                                }
                                merged
                            }
                            other => other,
                        }
                    } else {
                        upsert_body
                    };
                    let resp = self
                        .index_document_with_version_inner_guarded(
                            Some(id.to_string()),
                            body,
                            None,
                            None,
                            false,
                            Some(publication_guard),
                            false,
                            None,
                        )
                        .await?;
                    Ok(Some(resp))
                } else {
                    Ok(None)
                }
            }
        }
    }

    /// Serialize the load, transform, and publication of one document ID.
    ///
    /// The exact-ID publication guard spans the authoritative read, caller
    /// transform, WAL/version-map update, FTS/HNSW publication, and response.
    /// This is the engine boundary used by API-layer scripted updates: keeping
    /// script evaluation outside this method turns `ctx._source.n += 1` into
    /// an unguarded read-modify-write and loses concurrent increments.
    ///
    /// `transform` is called only for an existing source. If the ID is missing,
    /// `upsert` is created without applying the transform (ES's default
    /// `scripted_upsert=false` behavior); without an upsert this returns
    /// `Ok(Ok(None))`. Transform errors are returned in the inner `Result`
    /// without publishing a write.
    pub async fn transform_document_serialized<E, F>(
        &self,
        id: &str,
        upsert: Option<Value>,
        transform: F,
    ) -> Result<std::result::Result<Option<SerializedDocumentUpdate>, E>>
    where
        F: FnOnce(Value) -> std::result::Result<Value, E>,
    {
        let publication_guard = self.write_publication.lock(id.to_string()).await;
        let (source, created) = match self.get_document(id).await? {
            Some(existing) => match transform(existing) {
                Ok(transformed) => (transformed, false),
                Err(error) => return Ok(Err(error)),
            },
            None => match upsert {
                Some(source) => (source, true),
                None => return Ok(Ok(None)),
            },
        };
        let response = self
            .index_document_with_version_inner_guarded(
                Some(id.to_string()),
                source,
                None,
                None,
                false,
                Some(publication_guard),
                false,
                None,
            )
            .await?;
        Ok(Ok(Some(SerializedDocumentUpdate { response, created })))
    }

    /// Record passage-bearing semantic targets before document visibility.
    ///
    /// The set is monotonic, so this method does no work for ordinary
    /// lexical/vector documents after the cheap source-key scan. It must run
    /// before WAL or memtable publication on every path that can carry a
    /// semantic companion.
    async fn observe_passage_chunks<'a, I>(&self, sources: I)
    where
        I: IntoIterator<Item = &'a Value>,
    {
        let targets = {
            let schema = self.schema.read().await;
            passage_scored_vector_fields(&schema.schema)
        };
        if targets.is_empty() {
            return;
        }
        self.observe_passage_chunks_for_targets(&targets, sources);
    }

    fn observe_passage_chunks_for_targets<'a, I>(&self, targets: &[String], sources: I)
    where
        I: IntoIterator<Item = &'a Value>,
    {
        let mut observed = HashSet::new();
        for source in sources {
            observe_passage_chunks_in_source(targets, source, &mut observed);
        }
        if observed.is_empty() {
            return;
        }
        self.passage_chunk_fields.write().unwrap().extend(observed);
    }

    fn passage_chunks_require_exact(&self, field: &str) -> bool {
        self.passage_chunk_fields.read().unwrap().contains(field)
    }

    /// Scan a document for vector fields and insert them into the HNSW graph.
    ///
    /// FIELD IDENTITY (see `hnsw_field`): one graph indexes exactly ONE
    /// field. The field is pinned when the graph is first created —
    /// preferring the schema's first dense_vector-mapped field over the
    /// ingested doc's first numeric-array field — and every subsequent doc
    /// contributes ONLY that field. Docs lacking the pinned field are
    /// skipped: their absence breaks the `hnsw_id_map.len() == doc_count`
    /// coverage guard, which keeps the kNN query path on exact brute force,
    /// instead of silently searching a graph that mixes semantically
    /// unrelated fields (the pre-2026-07 behavior inserted each doc's own
    /// first numeric-array field, so one graph could span fields).
    ///
    /// UPDATES: re-indexing an existing doc_id tombstones the doc's previous
    /// node before inserting the fresh vector — otherwise the graph would
    /// keep serving the pre-update vector forever.
    async fn index_vectors(&self, doc_id: &str, source: &Value) {
        // #392: SQ8 code stores are maintained for EVERY scalar8 field on
        // every write, independent of the single field the HNSW graph pins.
        self.sq8_ingest(doc_id, source).await;
        let obj = match source.as_object() {
            Some(o) => o,
            None => return,
        };
        let pinned: Option<String> = self.hnsw_field.read().unwrap().clone();
        if let Some(field) = pinned {
            // Enforced path: only the pinned field ever enters the graph.
            if let Some(vector) = extract_numeric_vector(source, &field) {
                self.hnsw_insert_vector(doc_id, vector).await;
            }
            return;
        }

        // No pinned field yet. Cheap sync pre-screen: bail before any async
        // lock when the doc carries no top-level all-numbers array —
        // log/text workloads take this exit.
        //
        // (RC4 W2 item 16: the legacy-graph maintenance block that used to
        // live here — per-doc first-numeric-array inserts into a graph
        // loaded from a pre-field-stamp snapshot — is gone. Field-less and
        // non-dense_vector-pinned snapshots are no longer loaded at all
        // (see the load gate in `Index::open`), so a live graph always has
        // a pinned dense_vector field and takes the fast path above.)
        let has_candidate = obj.values().any(|v| {
            v.as_str()
                .is_some_and(xerj_common::packed_f32::is_packed_f32)
                || v.as_array()
                    .map(|arr| !arr.is_empty() && arr.iter().all(Value::is_number))
                    .unwrap_or(false)
        });
        if !has_candidate {
            return;
        }

        // First vector-bearing doc: decide the field, then pin it under the
        // write lock (re-checking, so concurrent deciders agree on one).
        let decided = match self.choose_hnsw_field(source).await {
            Some(f) => f,
            None => return,
        };
        let field = {
            let mut fg = self.hnsw_field.write().unwrap();
            match fg.as_ref() {
                Some(existing) => existing.clone(),
                None => {
                    *fg = Some(decided.clone());
                    decided
                }
            }
        };
        if let Some(vector) = extract_numeric_vector(source, &field) {
            self.hnsw_insert_vector(doc_id, vector).await;
        }
    }

    /// Pick the field the HNSW graph will index, given the first
    /// vector-bearing document. Preference order:
    ///   1. the first schema dense_vector field this doc carries as an
    ///      all-numbers array (the bench PUTs an explicit dense_vector
    ///      mapping for `v`);
    ///   2. the first schema dense_vector field (pin to the mapping even if
    ///      this particular doc lacks it).
    ///
    /// A graph is ONLY ever built for an explicit dense_vector mapping.
    /// RC4 W2 item 16 deleted the historical heuristic 3 ("no dense_vector
    /// mapping → the doc's first top-level all-numbers array field"): it
    /// auto-built and persisted an HNSW graph for ANY numeric-array field —
    /// a `ports: [80, 443]` log workload silently pinned a full f32 slab +
    /// graph in RAM forever (585 KB per 2 k docs, growing with every doc,
    /// reloaded on every restart) that no realistic query ever used. That
    /// was an RSS-runaway feeder, not a feature.
    async fn choose_hnsw_field(&self, source: &Value) -> Option<String> {
        let dv_fields: Vec<String> = {
            let schema = self.schema.read().await;
            collect_dense_vector_fields(&schema.schema)
        };
        if let Some(f) = dv_fields
            .iter()
            .find(|f| extract_numeric_vector(source, f).is_some())
        {
            return Some(f.clone());
        }
        dv_fields.into_iter().next()
    }

    /// Insert one doc's vector into the HNSW graph (creating the graph on
    /// first use), tombstoning any previous node for the same doc_id.
    /// Returns false when the vector was skipped (empty / dim mismatch /
    /// insert error) — the doc then has no `hnsw_id_map` entry, so the
    /// coverage guard keeps the kNN query path on brute force.
    async fn hnsw_insert_vector(&self, doc_id: &str, vector: Vec<f32>) -> bool {
        let dim = vector.len();
        if dim == 0 {
            return false;
        }
        // UPDATE staleness fix: a doc_id that already has a node must have
        // that node tombstoned before the fresh vector goes in (fresh
        // node_id; the old node is never unmarked).
        let old_node: Option<u64> = self.hnsw_id_map.read().await.get(doc_id).copied();
        if old_node.is_none() {
            // Item 8: a new vector-bearing doc-id. Counted on ATTEMPT (here),
            // not on success below: if the insert then fails (dim mismatch /
            // graph error), `id_map.len()` stays behind `vector_doc_count`,
            // which holds the coverage gate on brute force — the safe
            // direction (a doc that isn't in the graph must not be answered
            // from it). An update (old_node.is_some()) is already counted.
            self.vector_doc_count.fetch_add(1, Ordering::Relaxed);
        }
        let node_id = self.hnsw_next_id.fetch_add(1, Ordering::Relaxed);
        {
            let mut hnsw_guard = self.hnsw.write().await;
            if hnsw_guard.is_none() {
                let params = HnswParams::new(dim, DistanceMetric::Cosine);
                *hnsw_guard = Some(HnswIndex::new(params));
            }
            if let Some(ref hnsw) = *hnsw_guard {
                if hnsw.params().dim != dim {
                    // Mismatched dimension — skip (no id_map entry → the
                    // coverage guard keeps queries on brute force).
                    return false;
                }
                if let Some(old) = old_node {
                    hnsw.mark_deleted(old);
                }
                if let Err(e) = hnsw.insert(node_id, vector) {
                    warn!(doc_id, error = %e, "HNSW insert failed");
                    return false;
                }
            }
        }
        // Update id maps.
        let mut id_map = self.hnsw_id_map.write().await;
        let mut id_rev = self.hnsw_id_rev.write().await;
        if let Some(old) = old_node {
            id_rev.remove(&old);
        }
        id_map.insert(doc_id.to_string(), node_id);
        id_rev.insert(node_id, doc_id.to_string());
        true
    }

    // ── SQ8 ingest-time code stores (#392) ──────────────────────────────
    //
    // One `Sq8CodeStore` per `quantization: "scalar8"` dense_vector field:
    // one u8 per dimension per document, written by the ingest hook the
    // moment a write publishes, addressed by dense slot (`slot * dim..`) —
    // the same slot discipline the HNSW slab uses for its f32 vectors. The
    // codebook is fitted from the vectors as they are ingested (widening +
    // re-encode on out-of-range values, never clamping), so a document's
    // quantized score is a function of index state alone — not of the
    // candidate set a query scans. That is the Lucene property #392 asks
    // for; qdrant's `EncodedVectorsU8` does the same at build time.
    //
    // Fail-safe direction everywhere: a store that is missing, not yet
    // converged, or whose coverage gate is broken (a wrong-dimension write)
    // leaves the kNN paths on the exact `_source` scan — nothing is ever
    // served from incomplete codes.

    /// The SQ8 code store handle for one field, if the mapping declared
    /// `scalar8` and the handle exists.
    fn sq8_store_for(&self, field: &str) -> Option<Arc<Sq8StoreHandle>> {
        self.sq8_stores.read().get(field).cloned()
    }

    /// Create code-store handles for every `scalar8` field the schema
    /// declares and none exists for yet. Returns the NEW fields — the caller
    /// spawns the authoritative doc walk for those (an existing index may
    /// carry documents that predate the handle; a fresh index converges on
    /// an empty walk).
    async fn ensure_sq8_stores(&self) -> Vec<String> {
        let schema = self.schema.read().await;
        self.ensure_sq8_stores_from_schema(&schema.schema)
    }

    /// Sync variant for call sites that already hold the schema.
    fn ensure_sq8_stores_from_schema(&self, schema: &Schema) -> Vec<String> {
        let scalar8_fields = collect_scalar8_fields(schema);
        if scalar8_fields.is_empty() {
            return Vec::new();
        }
        let mut created = Vec::new();
        let mut guard = self.sq8_stores.write();
        for field in scalar8_fields {
            if guard.contains_key(&field) {
                continue;
            }
            let similarity = lookup_vector_similarity(schema, &field);
            let dim = declared_field(schema, &field)
                .and_then(|fc| fc.options.dimensions)
                .unwrap_or(0);
            let handle = Arc::new(Sq8StoreHandle {
                store: parking_lot::RwLock::new(Sq8CodeStore::new(dim)),
                normalize: !matches!(
                    similarity.as_str(),
                    "l2_norm" | "dot_product" | "max_inner_product"
                ),
                ready: std::sync::atomic::AtomicBool::new(false),
                walking: std::sync::atomic::AtomicBool::new(false),
                walk_task: parking_lot::Mutex::new(None),
            });
            guard.insert(field.clone(), Arc::clone(&handle));
            created.push(field);
        }
        drop(guard);
        created
    }

    /// Spawn the authoritative doc walk that makes a (new) code store
    /// serving-ready. Single-flight per handle. The walk re-derives codes
    /// for every live document — WAL replay never re-runs vector indexing,
    /// so this is also the restart path — and then publishes `ready` when
    /// coverage is intact.
    fn spawn_sq8_walk(self: &Arc<Self>, field: &str) {
        let Some(handle) = self.sq8_store_for(field) else {
            return;
        };
        if handle
            .walking
            .swap(true, std::sync::atomic::Ordering::AcqRel)
        {
            return;
        }
        let weak = Arc::downgrade(self);
        let field = field.to_string();
        let index_name = self.name.as_str().to_string();
        let walk_handle = Arc::clone(&handle);
        let join = tokio::spawn(async move {
            let started = std::time::Instant::now();
            let mut converged = false;
            if let Some(idx) = weak.upgrade() {
                converged = idx.sq8_rebuild_one_field(&walk_handle, &field).await;
            }
            walk_handle
                .walking
                .store(false, std::sync::atomic::Ordering::Release);
            if converged {
                info!(
                    index = %index_name,
                    field = %field,
                    elapsed_ms = started.elapsed().as_millis() as u64,
                    "SQ8 code store rebuilt — codes serving path enabled"
                );
            } else {
                warn!(
                    index = %index_name,
                    field = %field,
                    "SQ8 code store rebuild did not converge — staying on exact scan"
                );
            }
        });
        let mut slot = handle.walk_task.lock();
        if let Some(prev) = slot.replace(join) {
            prev.abort();
        }
    }

    /// Walk every live document once and make `handle`'s store describe
    /// exactly the live corpus: upsert each doc that carries `field`, then
    /// reconcile the remaining slots against the authoritative doc state.
    /// Returns `false` (store left not-ready, exact scan keeps serving) if
    /// any segment was unreadable or a suspect doc could not be fetched.
    async fn sq8_rebuild_one_field(
        self: &Arc<Self>,
        handle: &Arc<Sq8StoreHandle>,
        field: &str,
    ) -> bool {
        // Live-doc walk, same discipline as `rebuild_hnsw_from_docs`:
        // memtable first, then every flushed segment, dedup by doc id,
        // skipping tombstoned and seq-superseded copies.
        let mut seen: HashSet<String> = HashSet::new();
        let mem_docs = self.memtable.all_docs_with_sources();
        for (doc_id, src) in &mem_docs {
            seen.insert(doc_id.clone());
            if let Some(mut vector) = extract_numeric_vector(src, field) {
                if handle.normalize {
                    l2_normalize_vec(&mut vector);
                }
                handle.store.write().upsert(doc_id, &vector);
            }
        }
        drop(mem_docs);

        let snap = self.store.snapshot();
        for meta in snap.segments.iter() {
            let Some(docs_arc) = self.stored_values_for_async(&meta.id).await else {
                warn!(
                    index = self.name.as_str(),
                    segment = meta.id.as_str(),
                    field,
                    "SQ8 rebuild: segment not readable — not ready"
                );
                return false;
            };
            for doc in docs_arc.iter() {
                let Some(id) = doc.get("_id").and_then(Value::as_str) else {
                    continue;
                };
                if let Some(ver) = self.store.version_map.get(id) {
                    if ver.deleted {
                        continue;
                    }
                    if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                        if doc_seq < ver.seq_no {
                            continue;
                        }
                    }
                }
                if !seen.insert(id.to_string()) {
                    continue;
                }
                let src_owned;
                let src: &Value = match doc.get("_source") {
                    Some(s) => s,
                    None => {
                        let mut d = doc.clone();
                        if let Some(obj) = d.as_object_mut() {
                            obj.remove("_id");
                        }
                        src_owned = d;
                        &src_owned
                    }
                };
                if let Some(mut vector) = extract_numeric_vector(src, field) {
                    if handle.normalize {
                        l2_normalize_vec(&mut vector);
                    }
                    handle.store.write().upsert(id, &vector);
                }
            }
        }

        // Reconcile slots the walk did not confirm. A slot is dropped when
        // its doc is gone (deleted, or no longer in the authoritative view)
        // or no longer carries the field; a slot whose doc raced the walk
        // (updated after its segment was passed) is refreshed from the live
        // source rather than trusted or dropped blind.
        let suspects: Vec<String> = {
            let store = handle.store.read();
            store
                .iter_live()
                .map(|(id, _)| id.to_string())
                .filter(|id| !seen.contains(id))
                .collect()
        };
        for id in suspects {
            let gone = self
                .store
                .version_map
                .get(&id)
                .map(|e| e.deleted)
                .unwrap_or(true);
            if gone {
                handle.store.write().remove(&id);
                continue;
            }
            match self.get_document_uncounted(&id).await {
                Ok(Some(src)) => match extract_numeric_vector(&src, field) {
                    Some(mut vector) => {
                        if handle.normalize {
                            l2_normalize_vec(&mut vector);
                        }
                        handle.store.write().upsert(&id, &vector);
                    }
                    None => {
                        // Live doc no longer carries the field.
                        handle.store.write().remove(&id);
                    }
                },
                Ok(None) => {
                    // Not in the authoritative view any more.
                    handle.store.write().remove(&id);
                }
                Err(e) => {
                    warn!(
                        index = self.name.as_str(),
                        field,
                        doc_id = %id,
                        error = %e,
                        "SQ8 rebuild: suspect doc not fetchable — not ready"
                    );
                    return false;
                }
            }
        }

        let coverage = handle.store.read().coverage_ok();
        handle.ready.store(coverage, Ordering::Release);
        coverage
    }

    /// Await all in-flight SQ8 code-store walks (deterministic test hook,
    /// mirroring [`Self::await_hnsw_rebuild`]).
    pub async fn await_sq8_rebuilds(&self) {
        let handles: Vec<Arc<Sq8StoreHandle>> = self.sq8_stores.read().values().cloned().collect();
        for handle in handles {
            let join = handle.walk_task.lock().take();
            if let Some(join) = join {
                let _ = join.await;
            }
        }
    }

    /// Maintain every scalar8 field's code store for one document write.
    /// Runs inside the write's publication interval (the same bracket the
    /// HNSW inserts use), so a codes-served query either sees the slot or
    /// falls back — never a half-published vector. A doc that stops
    /// carrying the field loses its slot in the same step.
    async fn sq8_ingest(&self, doc_id: &str, source: &Value) {
        let handles: Vec<(String, Arc<Sq8StoreHandle>)> = {
            let guard = self.sq8_stores.read();
            guard
                .iter()
                .map(|(f, h)| (f.clone(), Arc::clone(h)))
                .collect()
        };
        if handles.is_empty() {
            return;
        }
        for (field, handle) in handles {
            let Some(mut vector) = extract_numeric_vector(source, &field) else {
                handle.store.write().remove(doc_id);
                continue;
            };
            if handle.normalize {
                l2_normalize_vec(&mut vector);
            }
            handle.store.write().upsert(doc_id, &vector);
        }
    }

    /// Per-field SQ8 code-store health (#392), surfaced by `GET
    /// /{index}/_stats` next to the HNSW section.
    pub fn sq8_stats(&self) -> Value {
        let guard = self.sq8_stores.read();
        let mut fields = serde_json::Map::new();
        for (field, handle) in guard.iter() {
            let store = handle.store.read();
            fields.insert(
                field.clone(),
                serde_json::json!({
                    "dim": store.dim(),
                    "live": store.live_len(),
                    "expected": store.expected(),
                    "covered": store.coverage_ok(),
                    "ready": handle.ready.load(Ordering::Acquire),
                    "serving": handle.serving_fresh(),
                    "refits": store.refits(),
                    "codes_bytes": store.codes_bytes(),
                    // The retained originals exist so codebook re-fits
                    // re-encode from the true vectors (see `sq8_codes`);
                    // reported so the memory story stays honest.
                    "originals_bytes": store.originals_bytes(),
                }),
            );
        }
        Value::Object(fields)
    }

    /// Perform KNN search over the HNSW index.
    ///
    /// Returns the top-`k` (doc_id, distance) pairs.
    pub async fn knn_search(&self, query_vector: &[f32], k: usize) -> Vec<(String, f32)> {
        let hnsw_guard = self.hnsw.read().await;
        let hnsw = match hnsw_guard.as_ref() {
            Some(h) => h,
            None => return vec![],
        };
        let ef = (k * 2).max(64);
        let results = match hnsw.search(query_vector, k, ef) {
            Ok(r) => r,
            Err(e) => {
                warn!(error = %e, "HNSW search failed");
                return vec![];
            }
        };
        let id_rev = self.hnsw_id_rev.read().await;
        results
            .into_iter()
            .filter_map(|(node_id, dist)| id_rev.get(&node_id).map(|doc_id| (doc_id.clone(), dist)))
            .collect()
    }

    /// Spawn the background stale-HNSW heal (RC4 W2 item 17) if the loaded
    /// snapshot was marked flush-time stale. No-op when the graph is fresh,
    /// absent, field-less, or a rebuild is already in flight.
    ///
    /// Pre-fix behavior: `hnsw_stale` was sticky for the process lifetime —
    /// after any unclean shutdown the ANN path was disabled forever while
    /// every ingested doc kept paying full O(log N) graph maintenance, and
    /// nothing surfaced the degradation. The rebuild re-derives exactly the
    /// WAL-tail divergence and re-enables the ANN path; staleness/rebuild
    /// state is surfaced via [`Index::hnsw_stats`].
    pub fn spawn_hnsw_rebuild_if_stale(self: &Arc<Self>) {
        if !self.hnsw_stale.load(Ordering::Acquire) {
            return;
        }
        if self.hnsw_field.read().unwrap().is_none() {
            return;
        }
        // Single-flight: swap-in true; if it was already true a rebuild is
        // running and will publish its own outcome.
        if self
            .hnsw_rebuilding
            .swap(true, std::sync::atomic::Ordering::AcqRel)
        {
            return;
        }
        let weak = Arc::downgrade(self);
        let handle = tokio::spawn(async move {
            let idx = match weak.upgrade() {
                Some(a) => a,
                None => return,
            };
            info!(
                index = idx.name.as_str(),
                "HNSW stale rebuild started (background)"
            );
            let started = std::time::Instant::now();
            let healed = idx.rebuild_hnsw_from_docs().await;
            idx.hnsw_rebuilding
                .store(false, std::sync::atomic::Ordering::Release);
            match healed {
                Ok(true) => info!(
                    index = idx.name.as_str(),
                    elapsed_ms = started.elapsed().as_millis() as u64,
                    "HNSW stale rebuild complete — ANN path re-enabled"
                ),
                Ok(false) => warn!(
                    index = idx.name.as_str(),
                    "HNSW stale rebuild did not converge — staying on exact brute force"
                ),
                Err(e) => warn!(
                    index = idx.name.as_str(),
                    error = %e,
                    "HNSW stale rebuild failed — staying on exact brute force"
                ),
            }
        });
        let mut slot = self.hnsw_rebuild_task.lock();
        if let Some(prev) = slot.replace(handle) {
            prev.abort();
        }
    }

    /// Await the in-flight stale HNSW rebuild to completion, if one is running.
    ///
    /// A deterministic alternative to polling `hnsw_stats` for tests and
    /// diagnostics (#536): the background task clears `hnsw_rebuilding` and
    /// publishes the healed graph *before* its `JoinHandle` resolves, so a
    /// caller observes `stale == false` / `rebuilding == false` immediately
    /// after this returns — with no timeout that can flake under parallel test
    /// load. A no-op when no rebuild was spawned (the snapshot was already
    /// fresh). The handle is `take`n, so a subsequent close/abort is a no-op
    /// (the task has already finished).
    pub async fn await_hnsw_rebuild(&self) {
        let handle = self.hnsw_rebuild_task.lock().take();
        if let Some(handle) = handle {
            let _ = handle.await;
        }
    }

    /// Re-derive the HNSW graph from the authoritative doc set and clear
    /// `hnsw_stale` (RC4 W2 item 17). Returns `Ok(true)` once converged.
    ///
    /// Cost model: the loaded snapshot already matches every doc that was
    /// flushed before the stamp — only the WAL tail diverges. Each pass
    /// walks all live docs (memtable first, then segments, with the same
    /// version-map/`_seq_no`/first-seen discipline as
    /// `run_knn_brute_force`) and
    ///   * skips docs whose graph vector already bit-matches the doc
    ///     source (`HnswIndex::vector_matches` — the overwhelming
    ///     majority), so a pass is O(N·dim) compares;
    ///   * re-inserts diverged docs via `hnsw_insert_vector` (tombstones
    ///     the old node) — O(tail · log N);
    ///   * prunes id-map entries whose doc no longer exists (WAL-tail
    ///     deletes), version-map-confirmed so a doc that flushed
    ///     mid-collection is never mistaken for deleted.
    ///
    /// CONVERGENCE UNDER CONCURRENT WRITES: live ingest maintains the graph
    /// itself, but a rebuild insert computed from a pre-update source could
    /// land AFTER the live insert of the newer vector and silently re-stale
    /// the graph. The seq_no re-check catches exactly that window: a pass
    /// only counts as convergent when no write advanced the WAL during it;
    /// otherwise another (cheap, compare-mostly) pass runs. After
    /// MAX_PASSES of sustained racing the graph stays stale — brute force
    /// keeps serving correct results and the next restart tries again.
    async fn rebuild_hnsw_from_docs(&self) -> Result<bool> {
        const MAX_PASSES: usize = 5;
        let field = match self.hnsw_field.read().unwrap().clone() {
            Some(f) => f,
            None => return Ok(false),
        };
        if self.hnsw.read().await.is_none() {
            return Ok(false);
        }
        let passage_scored_fields = {
            let schema = self.schema.read().await;
            passage_scored_vector_fields(&schema.schema)
        };
        let mut rebuilt_passage_fields = HashSet::new();

        'passes: for pass in 1..=MAX_PASSES {
            let seq_start = self.store.current_seq_no();
            let mut walked = 0u64;
            let mut compared = 0u64;
            let mut reinserted = 0u64;

            // Live-doc walk. Memtable BEFORE the segment snapshot: a shard
            // flush completing mid-pass then presents the doc in both (the
            // `seen` set dedups) instead of in neither.
            let mut seen: HashSet<String> = HashSet::new();
            let mem_docs = self.memtable.all_docs_with_sources();
            for (doc_id, src) in &mem_docs {
                observe_passage_chunks_in_source(
                    &passage_scored_fields,
                    src,
                    &mut rebuilt_passage_fields,
                );
                seen.insert(doc_id.clone());
                if let Some(vector) = extract_numeric_vector(src, &field) {
                    compared += 1;
                    if !self.hnsw_vector_current(doc_id, &vector).await
                        && self.hnsw_insert_vector(doc_id, vector).await
                    {
                        reinserted += 1;
                    }
                }
                walked += 1;
                if walked & 1023 == 0 {
                    tokio::task::yield_now().await;
                }
            }
            drop(mem_docs);

            let snap = self.store.snapshot();
            for meta in snap.segments.iter() {
                let docs_arc = match self.stored_values_for_async(&meta.id).await {
                    Some(a) => a,
                    None => {
                        // Segment unreadable (transient I/O, or merged away
                        // under this pass's snapshot). Its docs may include
                        // WAL-tail-updated vectors, so clearing staleness
                        // without comparing them would be silently wrong —
                        // retry the whole pass on a fresh snapshot instead.
                        warn!(
                            index = self.name.as_str(),
                            segment = meta.id.as_str(),
                            pass,
                            "HNSW rebuild: segment not readable — retrying pass"
                        );
                        continue 'passes;
                    }
                };
                for doc in docs_arc.iter() {
                    let id = match doc.get("_id").and_then(Value::as_str) {
                        Some(s) => s,
                        None => continue,
                    };
                    if let Some(ver) = self.store.version_map.get(id) {
                        if ver.deleted {
                            continue;
                        }
                        // Superseded stale copy (same predicate as
                        // run_knn_brute_force): never let an updated doc's
                        // pre-update segment copy shadow the live one.
                        if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                            if doc_seq < ver.seq_no {
                                continue;
                            }
                        }
                    }
                    if !seen.insert(id.to_string()) {
                        continue;
                    }
                    let src_owned;
                    let src: &Value = match doc.get("_source") {
                        Some(s) => s,
                        None => {
                            let mut d = doc.clone();
                            if let Some(obj) = d.as_object_mut() {
                                obj.remove("_id");
                            }
                            src_owned = d;
                            &src_owned
                        }
                    };
                    observe_passage_chunks_in_source(
                        &passage_scored_fields,
                        src,
                        &mut rebuilt_passage_fields,
                    );
                    if let Some(vector) = extract_numeric_vector(src, &field) {
                        compared += 1;
                        if !self.hnsw_vector_current(id, &vector).await
                            && self.hnsw_insert_vector(id, vector).await
                        {
                            reinserted += 1;
                        }
                    }
                    walked += 1;
                    if walked & 1023 == 0 {
                        tokio::task::yield_now().await;
                    }
                }
            }

            // Prune graphed docs that are no longer live — WAL-tail deletes
            // the flush-time id_map still carries.
            let prune_candidates: Vec<(String, u64)> = {
                let id_map = self.hnsw_id_map.read().await;
                id_map
                    .iter()
                    .filter(|(doc_id, _)| !seen.contains(*doc_id))
                    .map(|(doc_id, node)| (doc_id.clone(), *node))
                    .collect()
            };
            let mut pruned = 0u64;
            for (doc_id, node_id) in prune_candidates {
                // Version-map confirm: prune only genuinely-gone docs. A doc
                // the walk missed because it flushed mid-pass keeps a live
                // version entry and therefore its node.
                let gone = match self.store.version_map.get(&doc_id) {
                    Some(e) => e.deleted,
                    None => true,
                };
                if !gone {
                    continue;
                }
                {
                    // Re-check the mapping still points at the node we saw —
                    // a concurrent re-index replaces the mapping and must
                    // keep its fresh node.
                    let mut id_map = self.hnsw_id_map.write().await;
                    if id_map.get(&doc_id) != Some(&node_id) {
                        continue;
                    }
                    id_map.remove(&doc_id);
                }
                self.hnsw_id_rev.write().await.remove(&node_id);
                if let Some(h) = self.hnsw.read().await.as_ref() {
                    h.mark_deleted(node_id);
                }
                // Item 8: pruned doc leaves the coverage-gate denominator.
                self.vector_doc_count
                    .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |v| {
                        Some(v.saturating_sub(1))
                    })
                    .ok();
                pruned += 1;
            }

            let seq_end = self.store.current_seq_no();
            if seq_end == seq_start {
                // This union must publish before stale=false. A query may
                // observe the healed graph immediately after that release;
                // it must already know whether passage scoring owns the field.
                self.passage_chunk_fields
                    .write()
                    .unwrap()
                    .extend(rebuilt_passage_fields.iter().cloned());
                self.hnsw_stale
                    .store(false, std::sync::atomic::Ordering::Release);
                info!(
                    index = self.name.as_str(),
                    pass, compared, reinserted, pruned, "HNSW rebuild pass converged"
                );
                // Persist the healed graph + fresh stamp so the next
                // restart doesn't redo the work.
                let _ = self.save_hnsw_to_disk().await;
                return Ok(true);
            }
            info!(
                index = self.name.as_str(),
                pass,
                reinserted,
                pruned,
                seq_start,
                seq_end,
                "HNSW rebuild pass raced concurrent writes — repeating"
            );
        }
        Ok(false)
    }

    /// True when `doc_id` has a graph node whose stored vector bit-matches
    /// `vector` (rebuild fast path — no insert needed).
    async fn hnsw_vector_current(&self, doc_id: &str, vector: &[f32]) -> bool {
        let node = match self.hnsw_id_map.read().await.get(doc_id) {
            Some(n) => *n,
            None => return false,
        };
        let guard = self.hnsw.read().await;
        guard
            .as_ref()
            .map(|h| h.vector_matches(node, vector))
            .unwrap_or(false)
    }

    /// Live HNSW/ANN health for stats surfacing (RC4 W2 item 17): pre-fix,
    /// a permanently-stale (brute-force-only) index was indistinguishable
    /// from a healthy one from the outside.
    pub async fn hnsw_stats(&self) -> Value {
        let (present, nodes, tombstones) = {
            let guard = self.hnsw.read().await;
            match guard.as_ref() {
                Some(h) => (true, h.len() as u64, h.tombstone_count() as u64),
                None => (false, 0, 0),
            }
        };
        let graphed = self.hnsw_id_map.read().await.len() as u64;
        // Item 8: coverage is graphed-docs / vector-bearing-docs. `covered`
        // means the ANN path is eligible (every vector doc is in the graph);
        // it stays `true` even when many docs lack the vector field (they are
        // not vector docs and belong in neither the graph nor a brute scan).
        let vector_docs = self.vector_doc_count.load(Ordering::Relaxed);
        let doc_count = self.doc_count.load(Ordering::Relaxed);
        let covered = present && graphed == vector_docs && !self.hnsw_stale.load(Ordering::Acquire);
        let mut passage_exact_fields: Vec<String> = self
            .passage_chunk_fields
            .read()
            .unwrap()
            .iter()
            .cloned()
            .collect();
        passage_exact_fields.sort();
        let semantic_ann_blocked_by_passages = !passage_exact_fields.is_empty();
        serde_json::json!({
            "present": present,
            "field": self.hnsw_field.read().unwrap().clone(),
            "nodes": nodes,
            "tombstones": tombstones,
            "doc_coverage": graphed,
            // How many live docs carry the pinned vector field. The ANN gate
            // compares this against `doc_coverage`, NOT the index-wide
            // `total_docs` — a mixed corpus can be fully covered.
            "vector_doc_count": vector_docs,
            "total_docs": doc_count,
            "covered": covered,
            "passage_exact_fields": passage_exact_fields,
            "semantic_ann_blocked_by_passages": semantic_ann_blocked_by_passages,
            "stale": self.hnsw_stale.load(Ordering::Acquire),
            "rebuilding": self
                .hnsw_rebuilding
                .load(std::sync::atomic::Ordering::Acquire),
        })
    }

    /// Read the running counter of update operations that detected no
    /// change to the source. Surfaced via `indices.stats` as
    /// `indexing.noop_update_total`.
    pub fn noop_update_total(&self) -> u64 {
        self.noop_update_count.load(Ordering::Relaxed)
    }

    /// Approximate (HNSW) top-level kNN. Returns `None` on ANY
    /// ineligibility — the caller then falls back to the exact brute-force
    /// scan, so this path can only ever make eligible queries faster, never
    /// change what an ineligible query returns.
    ///
    /// Eligibility (ALL must hold; the caller has already peeled the query
    /// and established `filter == None`, non-nested):
    ///   * declared similarity is `cosine`, matching the graph metric;
    ///   * the graph is field-pinned to exactly the queried field and not
    ///     flush-time stale (see `hnsw_field` / `hnsw_stale`);
    ///   * the field does not opt into SQ8 (`scalar8` keeps its dedicated
    ///     quantize-then-score brute path, which the graph does not model);
    ///   * `vector_doc_count >= HNSW_MIN_DOCS` — small vector sets (every
    ///     ES-YAML vector test is ≤ a few hundred docs) keep today's
    ///     byte-identical exact path;
    ///   * coverage: `hnsw_id_map.len() == vector_doc_count` (item 8), i.e.
    ///     every doc that CARRIES the pinned vector field has a graph entry.
    ///     Docs lacking the field are not vector docs and belong in neither
    ///     the graph nor a brute scan, so a mixed corpus can be fully covered.
    ///     Racy reads degrade to brute, never to wrong results.
    ///
    /// Results are EXACT-RESCORED: each of the ≤k candidate docs is fetched
    /// (metrics-free, so `indices.stats` get counters stay ES-parity) and
    /// re-scored with `compute_vector_similarity` (f64) against the stored
    /// vector, so `_score`s are byte-identical to the brute/script_score
    /// paths. Accepted divergences from brute (commit body documents them):
    /// tie order is graph-return order, and `total.value` may be < k when
    /// the graph returns fewer candidates (ES ANN behavior class; no pad).
    #[allow(clippy::too_many_arguments)] // query contract plus cooperative deadline
    async fn run_knn_hnsw(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        field: &str,
        query_vec: &[f32],
        k: usize,
        num_candidates: Option<usize>,
        similarity: &str,
    ) -> Option<SearchResult> {
        let started = std::time::Instant::now();
        if std::time::Instant::now() >= deadline {
            return None;
        }
        if similarity != "cosine" {
            return None;
        }
        if self.passage_chunks_require_exact(field) {
            return None;
        }
        #[cfg(test)]
        if self.test_ann_passage_guard_pause.load(Ordering::Acquire) {
            self.test_ann_passage_guard_ready
                .store(true, Ordering::Release);
            while self.test_ann_passage_guard_pause.load(Ordering::Acquire) {
                tokio::task::yield_now().await;
            }
        }
        let publication_generation = self.hnsw_publication_generation.load(Ordering::Acquire);
        if self.hnsw_publications_in_flight.load(Ordering::Acquire) != 0 {
            return None;
        }
        if self.hnsw_stale.load(Ordering::Acquire) {
            return None;
        }
        {
            let fg = self.hnsw_field.read().unwrap();
            if fg.as_deref() != Some(field) {
                return None;
            }
        }
        {
            let schema = self.schema.read().await;
            if lookup_vector_quantization(&schema.schema, field).as_deref() == Some("scalar8") {
                return None;
            }
        }
        // Item 8: both the min-size threshold and the coverage check are gated
        // on the count of docs that CARRY the pinned vector field
        // (`vector_doc_count`), NOT the index-global `doc_count`. The graph only
        // ever holds vector-bearing docs, so its size and coverage are a
        // function of that count. The old `id_map.len() == doc_count` test meant
        // a SINGLE doc lacking the vector field (a mixed log/vector corpus) left
        // `id_map.len() < doc_count` forever, silently pinning the WHOLE index
        // on O(N) brute force. A doc without the field is correctly absent from
        // both the graph and a brute scan, so ANN and brute return identical
        // results. A racy read (id_map.len() != vector_doc_count) degrades to
        // brute — never to wrong results.
        let vector_doc_count = self.vector_doc_count.load(Ordering::Relaxed);
        if vector_doc_count < HNSW_MIN_DOCS {
            return None;
        }
        if self.hnsw_id_map.read().await.len() as u64 != vector_doc_count {
            return None;
        }

        // ES 8.13 defaults num_candidates to 1.5*k when omitted; the beam
        // width never drops below k.
        let ef = num_candidates
            .unwrap_or(((3 * k) / 2).max(k))
            .max(k)
            .max(HNSW_EF_FLOOR);

        // LOCK DISCIPLINE: hold the graph read guard only for the sync
        // sub-ms beam search and copy the results out — index_vectors takes
        // `hnsw.write().await` per ingested doc, so holding this guard
        // across the doc-fetch awaits below would head-of-line-block vector
        // ingest (and, via writer preference, subsequent readers): exactly
        // the mixed-read-under-write failure class.
        let raw: Vec<(u64, f32)> = {
            let hnsw_guard = self.hnsw.read().await;
            let hnsw = hnsw_guard.as_ref()?;
            let params = hnsw.params();
            if params.metric != DistanceMetric::Cosine || params.dim != query_vec.len() {
                return None;
            }
            match hnsw.search(query_vec, k, ef) {
                Ok(r) => r,
                Err(_) => return None,
            }
        };
        #[cfg(test)]
        self.publication_test_point("", PublicationTestPoint::AnnAfterGraphSearch);
        if std::time::Instant::now() >= deadline {
            return None;
        }

        // node_id → doc_id under a short id_rev read. Nodes without a rev
        // entry were deleted between search and mapping — skip them (brute
        // would not return them either). Dedup defensively: a save/update
        // race can briefly leave two live nodes for one doc.
        let doc_ids: Vec<String> = {
            let id_rev = self.hnsw_id_rev.read().await;
            let mut seen: HashSet<&str> = HashSet::with_capacity(raw.len());
            raw.iter()
                .filter_map(|(node_id, _)| id_rev.get(node_id))
                .filter(|doc_id| seen.insert(doc_id.as_str()))
                .cloned()
                .collect()
        };

        // Hydrate + exact-rescore. Any fetch/extract anomaly → whole-request
        // brute fallback (never a partial page). This also covers
        // deleted-doc races and stale-restart deletes: the metrics-free
        // fetch consults the version map first and returns None for
        // tombstoned ids.
        let chunk_field = format!("{field}_chunks");
        let mut scored: Vec<(String, f32, Value, Option<u32>)> = Vec::with_capacity(doc_ids.len());
        for doc_id in doc_ids {
            let remaining = deadline.saturating_duration_since(std::time::Instant::now());
            if remaining.is_zero() {
                return None;
            }
            let src =
                match tokio::time::timeout(remaining, self.get_document_uncounted(&doc_id)).await {
                    Ok(Ok(Some(source))) => source,
                    _ => return None,
                };
            // Multi-chunk semantic docs score by best passage in brute —
            // single-vector rescore would diverge, so hand the request back.
            if get_field_value(&src, &chunk_field).is_some() {
                return None;
            }
            // Packed embeddings are the retained source form (#1940). A
            // number array is still valid for segments written before that.
            // `extract_numeric_vector` reads both. Any other shape, or a
            // vector whose length is not the query's, is an extract anomaly:
            // hand the whole request back to the exact scan.
            let doc_vec = extract_numeric_vector(&src, field)?;
            if doc_vec.len() != query_vec.len() {
                return None;
            }
            let score = compute_vector_similarity(similarity, query_vec, &doc_vec);
            scored.push((doc_id, score, src, None));
        }
        if std::time::Instant::now() >= deadline {
            return None;
        }
        // A writer records this field before making a new chunked document
        // visible. Recheck after graph search and hydration so a query racing
        // the first such write either linearizes before that write or abandons
        // ANN and lets the caller run the exact passage scorer.
        if self.passage_chunks_require_exact(field) {
            return None;
        }

        // A writer may start after the pre-check and finish while ANN searches
        // or hydrates. Never return candidates from a graph generation that
        // overlapped source visibility: hand the whole request to exact scan.
        if self.hnsw_publications_in_flight.load(Ordering::Acquire) != 0
            || self.hnsw_publication_generation.load(Ordering::Acquire) != publication_generation
        {
            return None;
        }

        // Item 8: this line is only reached when the coverage gate admitted
        // the ANN path (`hnsw_id_map.len() == vector_doc_count`). Logged so a
        // mixed-corpus query (docs without the vector field present) is
        // observably served by HNSW rather than silently pinned on brute.
        debug!(
            index = self.name.as_str(),
            field,
            vector_doc_count = self.vector_doc_count.load(Ordering::Relaxed),
            total_docs = self.doc_count.load(Ordering::Relaxed),
            candidates = scored.len(),
            "knn served via HNSW (coverage gate passed)"
        );
        let (generated_companion_fields, knn_schema) = {
            let schema = self.schema.read().await;
            (
                generated_embedding_companion_fields(&schema.schema),
                // #1745: filter/filters aggs evaluate their clauses with the
                // query matcher; only clone the mapping when this request
                // actually carries aggregations.
                request.aggs.as_ref().map(|_| schema.schema.clone()),
            )
        };
        Some(knn_result_from_scored(
            self,
            request,
            field,
            scored,
            k,
            started,
            &generated_companion_fields,
            knn_schema.as_ref(),
        ))
    }

    /// Brute-force exact KNN against every doc's stored source.
    ///
    /// We iterate (memtable ∪ segments.stored) once, extract the vector
    /// field, compute the configured similarity against the query
    /// vector, optionally apply a filter sub-query, and return the top-k
    /// by similarity as `Hit`s. `similarity` is one of
    /// `cosine | dot_product | max_inner_product | l2_norm` — matching
    /// Lucene's score conversion for each metric:
    ///
    /// * `cosine`:              `(1 + dot(a,b) / (|a|*|b|)) / 2`
    /// * `dot_product`:         `sigmoid(dot(a,b))` (≈ Lucene 9.x)
    /// * `max_inner_product`:   `if dot<0 { 1/(1-dot) } else { dot+1 }`
    /// * `l2_norm`:             `1 / (1 + sq_euclid(a,b))`
    ///
    /// Exact (brute force) results match the approximate HNSW path for
    /// small datasets (which is what the BBQ IVF YAML tests produce —
    /// ≤ a few hundred docs per index). Supersets of the tested
    /// behaviour (BBQ disk quantisation, IVF clustering) are not
    /// necessary for wire-correctness on these tests because the
    /// expected doc order is deterministic given exact scoring.
    async fn exact_scan_checkpoint(&self, _position: usize, deadline: std::time::Instant) -> bool {
        tokio::task::yield_now().await;
        #[cfg(test)]
        {
            self.test_scan_checkpoint_count
                .fetch_add(1, Ordering::Relaxed);
            let delay_ms = self.test_scan_checkpoint_delay_ms.load(Ordering::Relaxed);
            if _position > 0 && delay_ms > 0 {
                tokio::time::sleep(std::time::Duration::from_millis(delay_ms)).await;
            }
            // Deterministic gate (see `test_scan_checkpoint_gate`). Free when
            // no test holds the mutex, so this is a no-op for every other
            // test; when one does hold it, the scan waits here — inside its
            // loop, before it looks at the clock — until released.
            if _position > 0 {
                self.test_scan_checkpoint_parked
                    .fetch_add(1, Ordering::SeqCst);
                let _gate = self.test_scan_checkpoint_gate.lock().await;
            }
        }
        self.scan_clock_now(_position) >= deadline
    }

    /// The clock a cooperative scan checkpoint compares against its deadline.
    /// Always the real clock in a non-test build.
    #[cfg(not(test))]
    #[inline]
    fn scan_clock_now(&self, _position: usize) -> std::time::Instant {
        std::time::Instant::now()
    }

    /// The clock a cooperative scan checkpoint compares against its deadline.
    ///
    /// Real, unless a test has scripted this index's clock (see
    /// [`Index::script_scan_clock`]), in which case it returns whatever that
    /// script says the given scan position sees. Scripted readings do not
    /// move with the machine, which is the whole point: it turns "the budget
    /// runs out between checkpoint zero and the next one" from a race the
    /// test can lose into an arithmetic fact.
    #[cfg(test)]
    #[inline]
    fn scan_clock_now(&self, position: usize) -> std::time::Instant {
        let script = *self
            .test_scan_clock
            .lock()
            .unwrap_or_else(|p| p.into_inner());
        match script {
            Some(script) => script.reading_at(position),
            None => std::time::Instant::now(),
        }
    }

    /// Replace this index's scan clock with a scripted one and return the
    /// instant every checkpoint before `advance_from` will read. Checkpoints
    /// at `advance_from` and later read `base + skew` instead.
    ///
    /// A test derives its deadline from the returned `base`, so the position
    /// at which the deadline is crossed is fixed by arithmetic rather than
    /// by how quickly the machine gets from one checkpoint to the next.
    ///
    /// Scoped to this `Index` — the object under test — so a test that
    /// scripts a clock is invisible to every other test in the process,
    /// however they are scheduled.
    #[cfg(test)]
    fn script_scan_clock(
        &self,
        advance_from: usize,
        skew: std::time::Duration,
    ) -> std::time::Instant {
        let base = std::time::Instant::now();
        *self
            .test_scan_clock
            .lock()
            .unwrap_or_else(|p| p.into_inner()) = Some(ScanClockScript {
            base,
            advance_from,
            skew,
        });
        base
    }

    #[allow(clippy::too_many_arguments)]
    pub async fn run_knn_brute_force(
        &self,
        request: &SearchRequest,
        field: &str,
        query_vec: &[f32],
        k: usize,
        filter: Option<Box<QueryNode>>,
        similarity: &str,
        boost: Option<f32>,
        min_similarity: Option<f32>,
    ) -> Result<SearchResult> {
        let deadline = std::time::Instant::now()
            + std::time::Duration::from_millis(request.timeout_ms.unwrap_or(30_000));
        self.run_knn_brute_force_with_deadline(
            request,
            deadline,
            field,
            query_vec,
            k,
            filter,
            similarity,
            boost,
            min_similarity,
        )
        .await
    }

    /// #392 serving fast path: score an UNFILTERED scalar8 kNN entirely
    /// from the ingest-time code store — no `_source` candidates are
    /// collected, no f32 vectors are read, nothing is quantized per query.
    ///
    /// The whole scoring loop runs under ONE read guard of the store, with
    /// no await inside it, so it observes the codes and the codebook of a
    /// single consistent generation (a concurrent ingest waits on the write
    /// guard; a codebook re-fit cannot interleave). Only the top `k`
    /// survivors are hydrated from stored docs afterwards — any hydration
    /// anomaly (doc deleted mid-scan, unreadable segment, a chunked-passage
    /// doc) abandons the path and the caller falls back to the exact scan,
    /// mirroring `run_knn_hnsw`'s never-a-partial-page discipline.
    ///
    /// Returns `None` whenever the path cannot serve: store missing, walk
    /// not converged, coverage broken (a wrong-dimension write), dim
    /// mismatch, deadline, or a publication racing source visibility. The
    /// fail-safe direction is always the exact `_source` scan.
    #[allow(clippy::too_many_arguments)] // mirrors run_knn_brute_force_with_deadline
    async fn run_knn_sq8_codes_scan(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        field: &str,
        query_vec: &[f32],
        k: usize,
        similarity: &str,
        boost: Option<f32>,
        min_similarity: Option<f32>,
        started: std::time::Instant,
    ) -> Option<SearchResult> {
        if std::time::Instant::now() >= deadline {
            return None;
        }
        // Chunked-passage docs score by best passage in the exact path; the
        // codes hold the pooled vector, so hand those back to it.
        if self.passage_chunks_require_exact(field) {
            return None;
        }
        let handle = self.sq8_store_for(field)?;
        if !handle.serving_fresh() {
            return None;
        }
        // The codes quantize vectors normalized per the MAPPING's similarity
        // (`handle.normalize`). The exact scan normalizes per the QUERY's
        // similarity (`!matches!(similarity, "l2_norm" | "dot_product" |
        // "max_inner_product")`); a query that overrides `similarity` to the
        // other family quantizes differently-SCALED vectors there (raw
        // magnitudes vs unit), so the codes cannot reproduce its arithmetic
        // — hand it to the exact path, whose per-query codec follows the
        // query's own rule.
        let query_normalizes =
            !matches!(similarity, "l2_norm" | "dot_product" | "max_inner_product");
        if query_normalizes != handle.normalize {
            return None;
        }
        // Same publication discipline as `run_knn_hnsw`: never serve codes
        // from a window that overlapped a vector publication.
        let publication_generation = self.hnsw_publication_generation.load(Ordering::Acquire);
        if self.hnsw_publications_in_flight.load(Ordering::Acquire) != 0 {
            return None;
        }

        // ── Score every live slot from the codes ─────────────────────
        let mut ranked: Vec<(f32, String)> = Vec::new();
        {
            let store = handle.store.read();
            // Re-check the gates under the guard: the freshness check above
            // raced a concurrent walk/ingest if this now fails.
            if !store.coverage_ok() || store.dim() != query_vec.len() {
                return None;
            }
            let codebook = store.codebook();
            let mut decoded = vec![0.0f32; store.dim()];
            ranked.reserve(store.live_len() as usize);
            for (id, codes) in store.iter_live() {
                // Cheap deadline poll — no await can run under this guard.
                // On expiry hand the request to the exact path (which owns
                // the timed_out semantics), never serve a partial scan.
                if ranked.len() & 8191 == 8191 && std::time::Instant::now() >= deadline {
                    return None;
                }
                codebook.decode_into(codes, &mut decoded);
                let score = compute_vector_similarity(similarity, query_vec, &decoded);
                ranked.push((score, id.to_string()));
            }
        }
        debug!(
            index = self.name.as_str(),
            field,
            scored = ranked.len(),
            "SQ8 kNN served from ingest-time codes (#392)"
        );

        // ── Same cutoff → boost → rank pipeline as the exact path ─────
        if let Some(raw) = min_similarity {
            let cut = raw_similarity_to_score(similarity, raw);
            ranked.retain(|(score, _)| *score >= cut);
        }
        if let Some(b) = boost {
            if (b - 1.0).abs() > f32::EPSILON {
                for (score, _) in ranked.iter_mut() {
                    *score *= b;
                }
            }
        }
        // Deterministic order for equal scores (the slot walk's HashMap
        // order is not), then cap the pool at k — only these are hydrated.
        ranked.sort_by(|a, b| {
            b.0.partial_cmp(&a.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.1.cmp(&b.1))
        });
        ranked.truncate(k.max(1));

        // ── Hydrate the top-k from stored docs ────────────────────────
        let chunk_field = format!("{field}_chunks");
        let mut scored: Vec<(String, f32, Value, Option<u32>)> = Vec::with_capacity(ranked.len());
        for (score, doc_id) in ranked {
            let remaining = deadline.saturating_duration_since(std::time::Instant::now());
            if remaining.is_zero() {
                return None;
            }
            let src =
                match tokio::time::timeout(remaining, self.get_document_uncounted(&doc_id)).await {
                    Ok(Ok(Some(source))) => source,
                    _ => return None,
                };
            // A chunked doc must be scored by its best passage, not the
            // pooled codes — same bail as `run_knn_hnsw`.
            if get_field_value(&src, &chunk_field).is_some() {
                return None;
            }
            scored.push((doc_id, score, src, None));
        }
        if std::time::Instant::now() >= deadline {
            return None;
        }
        if self.passage_chunks_require_exact(field) {
            return None;
        }
        if self.hnsw_publications_in_flight.load(Ordering::Acquire) != 0
            || self.hnsw_publication_generation.load(Ordering::Acquire) != publication_generation
        {
            return None;
        }

        let (generated_companion_fields, knn_schema) = {
            let schema = self.schema.read().await;
            (
                generated_embedding_companion_fields(&schema.schema),
                // #1745: filter/filters aggs evaluate their clauses with the
                // query matcher; only clone the mapping when this request
                // actually carries aggregations.
                request.aggs.as_ref().map(|_| schema.schema.clone()),
            )
        };
        Some(knn_result_from_scored(
            self,
            request,
            field,
            scored,
            k,
            started,
            &generated_companion_fields,
            knn_schema.as_ref(),
        ))
    }

    /// Whether the exact scan makes a candidate of the stored copy `id` with
    /// `doc_seq` in captured segment `hit_segment`, recording it in `seen`
    /// when it does. Shared by the scan over stored documents and the scan
    /// over a cached column (#1091), so the two cannot disagree about which
    /// copy is live.
    ///
    /// #1220: the version-map read is scoped to the scan's capture (see
    /// [`CapturedEntryVerdict`]). `seen` is consulted FIRST, and its pre-seed
    /// is the memtable capture's ids — so an id that reaches the version-map
    /// read is one the memtable capture did NOT hold, which makes a
    /// memtable-resident entry here a write that landed AFTER the capture:
    /// every write takes its own publication bracket, and one that straddles
    /// the capture makes the bracket below answer with the retry signal. A
    /// later world's entry cannot retire the captured copy, and its `seq_no`
    /// belongs to that later world, so neither the tombstone check nor the
    /// stale-copy check may see it. Pre-fix, a post-capture update read the
    /// live entry's bumped `seq_no`, dropped the captured copy as stale, and
    /// the fresh copy sat in a world this scan never saw — the #1212 vanish
    /// shape on the vector path, whose walk runs long enough (#1091 FiQA:
    /// seconds) for concurrent writes to land inside it. A post-capture
    /// DELETE still takes effect (`deletes win`, the same semantic the #1218
    /// legs chose); only the not-deleted entries of a later world are
    /// ignored.
    fn admit_exact_scan_candidate(
        &self,
        seen: &mut HashSet<String>,
        id: &str,
        doc_seq: Option<u64>,
        hit_segment: &str,
        captured_segment_ids: &std::collections::HashSet<&str>,
    ) -> bool {
        if seen.contains(id) {
            return false;
        }
        if let Some(ver) = self.store.version_map.get(id) {
            let verdict = if !ver.deleted
                && ver.segment_id.as_ref() == xerj_storage::version_map::IN_MEMORY_SEGMENT_ID
            {
                CapturedEntryVerdict::PostCapture
            } else {
                captured_verdict_for_segment_hit(&ver, hit_segment, captured_segment_ids)
            };
            match verdict {
                // Tombstoned or superseded WITHIN the captured world (the
                // same predicates the count path's b8 T2 fix uses): an
                // updated doc appears in both its old and new segments, and
                // first-seen dedup over oldest-first segment order would
                // resurrect the PRE-update vector (live-verified
                // 2026-07-12: update + flush + kNN returned the old vector
                // as if the update never happened). The live copy is the
                // one this hit must equal: same segment, not deleted, and
                // not itself superseded by a higher `seq_no` inside the
                // captured world.
                CapturedEntryVerdict::Invisible => return false,
                CapturedEntryVerdict::Live => {
                    if let Some(doc_seq) = doc_seq {
                        if doc_seq < ver.seq_no {
                            return false;
                        }
                    }
                }
                // A later world's entry: neither its tombstone nor its
                // `seq_no` may retire the captured copy (see the #1220
                // note above). Deletes are the one exception — they win
                // before the verdict is computed.
                CapturedEntryVerdict::PostCapture => {}
            }
        }
        seen.insert(id.to_string());
        true
    }

    /// Run `work` on the engine's background pool and await its answer —
    /// never on tokio's blocking pool, for the #751 reason spelled out in
    /// `stored_values_for_async`. A panic answers `None`, as there.
    async fn on_background_pool<T, F>(work: F) -> Option<T>
    where
        T: Send + 'static,
        F: FnOnce() -> Option<T> + Send + 'static,
    {
        let (sender, receiver) = tokio::sync::oneshot::channel();
        crate::background_pool().spawn(move || {
            let answer =
                std::panic::catch_unwind(std::panic::AssertUnwindSafe(work)).unwrap_or(None);
            let _ = sender.send(answer);
        });
        receiver.await.ok().flatten()
    }

    /// #1091: build a segment's `BestPassage` vector column from the storage
    /// layer's typed kNN projection — identity and vector columns decoded
    /// straight to `f32`, no `_source` reconstructed — and publish it under
    /// `column_key`. The decode it replaces materialised every stored document
    /// as `serde_json::Value` (~53 KB a document on FiQA's passage-chunked
    /// corpus), and that transient alone pushed RSS over the memory watermark,
    /// whose drain then dropped every cached column again.
    ///
    /// `Unavailable` whenever the projection cannot stand in for the stored
    /// documents — a legacy or ZBS3 section, no such vector column, a cell
    /// shape the typed decoder refuses — and the caller reads the stored
    /// documents instead.
    async fn projected_vector_column(
        &self,
        segment_id: &str,
        field: &str,
        column_key: String,
    ) -> ProjectedColumn {
        use crate::vector_column::{ColumnBuilder, ColumnMode};
        use xerj_storage::stored_codec::{
            decode_stored_v2_knn_projection, StoredV2KnnProjectionResult,
        };

        let Ok(permit) = Arc::clone(&self.stored_value_load_semaphore)
            .acquire_owned()
            .await
        else {
            return ProjectedColumn::Unavailable;
        };
        let store = Arc::clone(&self.store);
        let load_segment_id = segment_id.to_string();
        let vector_field = field.to_string();
        let built = Self::on_background_pool(move || {
            let _permit = permit;
            let reader = store.open_segment_arc(&load_segment_id).ok()?;
            // A segment of tombstones alone has no stored section: nothing to
            // scan, exactly as the stored-document path skips it.
            let Some(bytes) = reader.section(SectionType::Stored).ok()? else {
                return Some(None);
            };
            let chunk_field = format!("{vector_field}_chunks");
            let StoredV2KnnProjectionResult::Projected(projection) =
                decode_stored_v2_knn_projection(bytes, &vector_field, Some(&chunk_field)).ok()?
            else {
                return None;
            };
            let rows = projection.num_docs;
            if projection.ids.len() != rows
                || projection.seq_nos.len() != rows
                || projection.vectors.len() != rows
                || projection
                    .vector_chunks
                    .as_ref()
                    .is_some_and(|chunks| chunks.len() != rows)
            {
                return None;
            }
            let mut builder = ColumnBuilder::new(&vector_field, ColumnMode::BestPassage);
            for row in 0..rows {
                builder.push_projected(
                    projection.ids[row].as_deref(),
                    projection.seq_nos[row],
                    projection.vectors[row].as_deref(),
                    projection
                        .vector_chunks
                        .as_ref()
                        .and_then(|chunks| chunks[row].as_deref()),
                );
            }
            Some(Some(builder.finish()))
        })
        .await;
        let column = match built {
            Some(Some(column)) => column,
            Some(None) => return ProjectedColumn::NoStoredSection,
            None => return ProjectedColumn::Unavailable,
        };
        let bytes = column
            .retained_bytes()
            .saturating_add(column_key.len() as u64);
        ProjectedColumn::Built(self.publish_current(
            &self.vector_column_cache,
            segment_id,
            column_key,
            SegmentCacheCategory::VectorColumn,
            bytes,
            column,
        ))
    }

    /// #1091: the `(_id, _source)` of the stored documents at `positions` of
    /// one segment, decoded row-selectively, aligned with `positions`. These
    /// are the very copies the scan scored — segments are immutable — so the
    /// hit is what the full decode would have produced, less the top-level
    /// `omit` fields when given. `None` when the section cannot be hydrated by
    /// row; the caller then reads the segment's stored documents.
    async fn hydrate_segment_rows(
        &self,
        segment_id: &str,
        positions: Vec<usize>,
        omit: Option<Arc<HashSet<String>>>,
    ) -> Option<Vec<(String, Value)>> {
        use xerj_storage::stored_codec::{
            decode_stored_v2_rows, decode_stored_v2_rows_projected, stored_v2_source_column_names,
            StoredV2RowHydrationResult,
        };

        let store = Arc::clone(&self.store);
        let load_segment_id = segment_id.to_string();
        Self::on_background_pool(move || {
            let reader = store.open_segment_arc(&load_segment_id).ok()?;
            let bytes = reader.section(SectionType::Stored).ok()??;
            let hydrated = match omit {
                // The vector companions are by far the largest columns of a
                // passage-chunked segment, and a row-selective decode still
                // walks a whole column to reach its rows: decoding them for
                // ten hits cost seconds on FiQA. Every other column is read.
                Some(omit) => {
                    let names = stored_v2_source_column_names(bytes).ok()??;
                    let include: Vec<&str> = names
                        .iter()
                        .map(String::as_str)
                        .filter(|name| !omit.contains(*name))
                        .collect();
                    decode_stored_v2_rows_projected(bytes, &positions, &include).ok()?
                }
                None => decode_stored_v2_rows(bytes, &positions).ok()?,
            };
            let StoredV2RowHydrationResult::Hydrated { rows, .. } = hydrated else {
                return None;
            };
            let mut by_ordinal: HashMap<usize, (String, Value)> = rows
                .into_iter()
                .filter_map(|row| {
                    let id = row.id.as_str()?.to_string();
                    Some((row.ordinal, (id, Value::Object(row.source))))
                })
                .collect();
            positions
                .iter()
                .map(|position| by_ordinal.remove(position))
                .collect()
        })
        .await
    }

    /// #2422/#2423: `{"_id", "_source"}` docs for the scored FTS walk of a
    /// segment whose stored offset index is NOT resident, decoded
    /// row-selectively for `positions` only — and, when `keep` names the
    /// source fields the request can observe, only those columns.
    ///
    /// The legacy cold path (`stored_slices_for`) decompressed and
    /// brace-walked the WHOLE stored section to read the top-k: a size-45
    /// query on a 30k-doc autoindex segment spent ~3 s there, and on a
    /// flight-trace index whose rows carry a ~72 KB `trace` field, 650 ms for
    /// five hits. Segments are immutable, so a row decode of the same
    /// positions yields the same document; `None` (legacy LZ4 layout,
    /// unsupported column shape, open/decode error, a missing row) sends the
    /// caller back to the full decode, so nothing is lost.
    /// Warm a segment's full stored slices on the blocking pool after a query
    /// answered it from its winning rows (#2422/#2423). Later queries with
    /// other winners then read the warm cache instead of each paying a
    /// projected decode, and the query that found the segment cold no longer
    /// waits for the whole-section decompress. One warm per segment at a
    /// time; `stored_slices_for` keeps its single-flight, budget and
    /// retirement rules.
    fn schedule_cold_stored_warm(&self, segment_id: &str, doc_count: u64) {
        let Some(index) = self.self_ref.get().and_then(std::sync::Weak::upgrade) else {
            return;
        };
        let Ok(runtime) = tokio::runtime::Handle::try_current() else {
            return;
        };
        if crate::governor::global().is_some_and(|g| g.memory_breaker_engaged()) {
            return;
        }
        if self
            .cold_stored_warms
            .insert(segment_id.to_string(), ())
            .is_some()
        {
            return;
        }
        let segment_id = segment_id.to_string();
        runtime.spawn_blocking(move || {
            if !index.stored_slices_cache.contains_key(segment_id.as_str()) {
                let _ = index.stored_slices_for(&segment_id, doc_count);
            }
            index.cold_stored_warms.remove(segment_id.as_str());
        });
    }

    /// #2427: find the row of every `hits` entry whose `_source` came from a
    /// column-projected stored scan (`scan_projected`: id → segment) and
    /// record it in `row_projected`, so the whole-document reader (TF-IDF
    /// fallback) can restore the full source. Decodes only the identity
    /// columns of each segment involved; rare path.
    fn locate_scan_projected_rows(
        &self,
        hits: &[Hit],
        scan_projected: &HashMap<String, String>,
        row_projected: &mut HashMap<String, (String, u32)>,
    ) {
        let mut wanted: HashMap<&str, HashSet<&str>> = HashMap::new();
        for hit in hits {
            if let Some(segment) = scan_projected.get(&hit.id) {
                wanted
                    .entry(segment.as_str())
                    .or_default()
                    .insert(hit.id.as_str());
            }
        }
        for (segment, ids) in wanted {
            let Some(reader) = self.store.open_segment_arc(segment).ok() else {
                continue;
            };
            let Some(bytes) = reader.section(SectionType::Stored).ok().flatten() else {
                continue;
            };
            let Some(identity) =
                xerj_storage::stored_codec::decode_stored_keeping(bytes, &|_: &str| false)
                    .ok()
                    .flatten()
            else {
                continue;
            };
            let Ok(rows) = serde_json::from_slice::<Vec<Value>>(&identity) else {
                continue;
            };
            for (position, row) in rows.iter().enumerate() {
                let Some(id) = row.get("_id").and_then(Value::as_str) else {
                    continue;
                };
                if ids.contains(id) {
                    if let Ok(position) = u32::try_from(position) {
                        row_projected.insert(id.to_string(), (segment.to_string(), position));
                    }
                }
            }
        }
    }

    fn hydrate_fts_rows_cold(
        &self,
        segment_id: &str,
        positions: &[u32],
        keep: Option<&[String]>,
    ) -> Option<HashMap<u32, Value>> {
        use xerj_storage::stored_codec::{
            decode_stored_v2_rows_projected_parallel, stored_v2_source_column_names,
            StoredV2RowHydrationResult,
        };
        let reader = self.store.open_segment_arc(segment_id).ok()?;
        let bytes = reader.section(SectionType::Stored).ok()??;
        let ordinals: Vec<usize> = positions.iter().map(|&p| p as usize).collect();
        // Columns decode concurrently: a handful of rows still streams every
        // wanted column, so the serial sum was the cost of a cold page.
        let hydrated = match keep {
            Some(keep) => {
                let names = stored_v2_source_column_names(bytes).ok()??;
                let include: Vec<&str> = names
                    .iter()
                    .map(String::as_str)
                    .filter(|column| row_projection_keeps_column(keep, column))
                    .collect();
                decode_stored_v2_rows_projected_parallel(bytes, &ordinals, Some(&include)).ok()?
            }
            None => decode_stored_v2_rows_projected_parallel(bytes, &ordinals, None).ok()?,
        };
        let StoredV2RowHydrationResult::Hydrated { rows, .. } = hydrated else {
            return None;
        };
        let mut out: HashMap<u32, Value> = HashMap::with_capacity(rows.len());
        for row in rows {
            let id = row.id.as_str()?.to_string();
            let mut doc = serde_json::Map::with_capacity(2);
            doc.insert("_id".to_string(), Value::String(id));
            doc.insert("_source".to_string(), Value::Object(row.source));
            out.insert(u32::try_from(row.ordinal).ok()?, Value::Object(doc));
        }
        // Every requested position must come back; a short answer means the
        // section and the FTS doc ids disagree, which the full decode path
        // already knows how to handle.
        if positions.iter().any(|p| !out.contains_key(p)) {
            return None;
        }
        Some(out)
    }

    /// `_id` per row for `positions` of a cold segment, decoded from the
    /// identity columns alone (no `_source` column is read). `None` (legacy
    /// layout, open/decode error, a missing row) sends the caller back to
    /// the full decode.
    fn cold_fts_row_ids(
        &self,
        segment_id: &str,
        positions: &[u32],
    ) -> Option<HashMap<u32, String>> {
        use xerj_storage::stored_codec::{
            decode_stored_v2_rows_projected, StoredV2RowHydrationResult,
        };
        let reader = self.store.open_segment_arc(segment_id).ok()?;
        let bytes = reader.section(SectionType::Stored).ok()??;
        let ordinals: Vec<usize> = positions.iter().map(|&p| p as usize).collect();
        let StoredV2RowHydrationResult::Hydrated { rows, .. } =
            decode_stored_v2_rows_projected(bytes, &ordinals, &[]).ok()?
        else {
            return None;
        };
        let mut out: HashMap<u32, String> = HashMap::with_capacity(rows.len());
        for row in rows {
            out.insert(
                u32::try_from(row.ordinal).ok()?,
                row.id.as_str()?.to_string(),
            );
        }
        if positions.iter().any(|p| !out.contains_key(p)) {
            return None;
        }
        Some(out)
    }

    /// Fill the `_source` of the cold FTS hits the segment loop kept with
    /// identity only (`deferred`: `_id` -> (segment, row, doc count)). Only
    /// the page's winners are read, row-selectively and per segment in
    /// parallel. A segment whose rows cannot be hydrated that way falls back
    /// to the full decode, as the walk itself used to; a hit whose document
    /// cannot be read at all is dropped, as the walk skipped an unreadable
    /// row. Projected hits are recorded in `row_projected` so the TF-IDF
    /// fallback can restore their whole source.
    fn hydrate_deferred_cold_sources(
        &self,
        hits: Vec<Hit>,
        deferred: &HashMap<String, (String, u32, u64)>,
        keep: Option<&[String]>,
        row_projected: &mut HashMap<String, (String, u32)>,
    ) -> Vec<Hit> {
        use rayon::prelude::*;
        let mut by_segment: HashMap<&str, (Vec<u32>, u64)> = HashMap::new();
        for hit in &hits {
            if let Some((seg, pos, doc_count)) = deferred.get(&hit.id) {
                by_segment
                    .entry(seg.as_str())
                    .or_insert_with(|| (Vec::new(), *doc_count))
                    .0
                    .push(*pos);
            }
        }
        if by_segment.is_empty() {
            return hits;
        }
        let segments: Vec<(&str, Vec<u32>, u64)> = by_segment
            .into_iter()
            .map(|(seg, (positions, doc_count))| (seg, positions, doc_count))
            .collect();
        // (segment, docs by row, projected?)
        let loaded: Vec<(&str, HashMap<u32, Value>, bool)> = segments
            .par_iter()
            .map(|(seg, positions, doc_count)| {
                if let Some(rows) = self.hydrate_fts_rows_cold(seg, positions, keep) {
                    return (*seg, rows, keep.is_some());
                }
                let mut docs: HashMap<u32, Value> = HashMap::with_capacity(positions.len());
                if let Some(slices) = self.stored_slices_for(seg, *doc_count) {
                    for &pos in positions {
                        let doc = slices
                            .offsets
                            .get(pos as usize)
                            .and_then(|&(start, end)| {
                                slices.bytes.get(start as usize..end as usize)
                            })
                            .and_then(|slice| serde_json::from_slice::<Value>(slice).ok());
                        if let Some(doc) = doc {
                            docs.insert(pos, doc);
                        }
                    }
                } else if let Some(all) = self.store.open_segment_arc(seg).ok().and_then(|reader| {
                    match reader.section(SectionType::Stored) {
                        Ok(Some(raw)) => xerj_storage::stored_codec::decode_stored(raw)
                            .ok()
                            .and_then(|b| serde_json::from_slice::<Vec<Value>>(&b).ok()),
                        _ => None,
                    }
                }) {
                    for &pos in positions {
                        if let Some(doc) = all.get(pos as usize) {
                            docs.insert(pos, doc.clone());
                        }
                    }
                }
                (*seg, docs, false)
            })
            .collect();
        let mut docs_by_segment: HashMap<&str, (HashMap<u32, Value>, bool)> = loaded
            .into_iter()
            .map(|(seg, docs, projected)| (seg, (docs, projected)))
            .collect();
        let mut out = Vec::with_capacity(hits.len());
        for mut hit in hits {
            let Some((seg, pos, _)) = deferred.get(&hit.id) else {
                out.push(hit);
                continue;
            };
            let Some((docs, projected)) = docs_by_segment.get_mut(seg.as_str()) else {
                continue;
            };
            let Some(mut doc) = docs.remove(pos) else {
                continue;
            };
            hit.source = doc
                .get_mut("_source")
                .map(Value::take)
                .unwrap_or(Value::Null);
            if *projected {
                row_projected.insert(hit.id.clone(), (seg.clone(), *pos));
            }
            out.push(hit);
        }
        out
    }

    #[allow(clippy::too_many_arguments)]
    async fn run_knn_brute_force_with_deadline(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        field: &str,
        query_vec: &[f32],
        k: usize,
        filter: Option<Box<QueryNode>>,
        similarity: &str,
        boost: Option<f32>,
        min_similarity: Option<f32>,
    ) -> Result<SearchResult> {
        // #1091: an unfiltered scan first ranks from vector columns alone and
        // hydrates only the winners. It hands the request back (`None`) when a
        // winner's segment can no longer be read — a merge retired it between
        // scoring and hydration — and the scan below then answers from the
        // stored documents, exactly as it always did.
        if filter.is_none() {
            if let Some(result) = self
                .run_knn_exact_scan(
                    request,
                    deadline,
                    field,
                    query_vec,
                    k,
                    None,
                    similarity,
                    boost,
                    min_similarity,
                    true,
                )
                .await?
            {
                return Ok(result);
            }
        }
        let result = self
            .run_knn_exact_scan(
                request,
                deadline,
                field,
                query_vec,
                k,
                filter,
                similarity,
                boost,
                min_similarity,
                false,
            )
            .await?;
        Ok(result.expect("a scan over stored documents always answers"))
    }

    /// The exact kNN scan. With `columns_only` (honoured only unfiltered and
    /// off `scalar8`), a segment whose vector column is cached, or can be
    /// built from the typed projection, is scanned from that column without
    /// its stored documents, and the ranked winners are hydrated by position;
    /// `Ok(None)` means one of them could not be, and the caller must rescan
    /// without `columns_only`. Without it the result is always `Some`.
    #[allow(clippy::too_many_arguments)]
    async fn run_knn_exact_scan(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        field: &str,
        query_vec: &[f32],
        k: usize,
        filter: Option<Box<QueryNode>>,
        similarity: &str,
        boost: Option<f32>,
        min_similarity: Option<f32>,
        columns_only: bool,
    ) -> Result<Option<SearchResult>> {
        use crate::vector_column::{ColumnBuilder, ColumnMode, DocVectorsView};

        let started = std::time::Instant::now();
        let mut timed_out = false;
        let trace_phases = std::env::var_os("XERJ_TRACE_SEMANTIC_PHASES").is_some();
        if trace_phases {
            tracing::info!(index=%self.name, field, k, "semantic_phase=start_brute");
        }

        // #423: evaluate the kNN `filter` through the SAME schema-aware matcher
        // the rest of search uses (`search_inner` runs its filter through
        // `doc_matches_query_typed(.., &dmq_schema)`). The schemaless
        // `doc_matches_query` has no field types, so on a `keyword`/`text` field
        // it folds case and OVER-MATCHES — a `prefix`/`match`/`fuzzy` filter kept
        // documents a plain (non-knn) search would reject. A filtered knn ALWAYS
        // takes this brute-force path (HNSW serves only `filter.is_none()`), so
        // this is the whole filtered-kNN path. Owned clone; the lock is released.
        let dmq_schema = self.schema().await;

        // ── Determine whether this field opts into SQ8 (scalar8) ──────
        // Default fields keep the exact f32 brute-force scan below,
        // byte-identical to before. A `scalar8` field may take the codes
        // fast path instead (#392). Determined up front so the fast path
        // can skip the candidate collection altogether; a FILTERED
        // `scalar8` query always runs this scan on the per-query codec in
        // the `use_sq8` branch below (bit-identical to the reference
        // oracle, which fits over the post-filter set).
        let use_sq8 = {
            let schema = self.schema.read().await;
            lookup_vector_quantization(&schema.schema, field).as_deref() == Some("scalar8")
        };

        // ── #392 fast path: unfiltered scalar8 kNN from ingest-time codes ──
        // Scores every live slot straight out of the code store — no
        // `_source` candidates collected, no per-query quantization — and
        // hydrates only the top k. Any gate miss (store not converged,
        // coverage broken, publication racing, a similarity family whose
        // normalization differs from the mapping's) falls through to the
        // exact scan below; filtered queries take the per-query codec in
        // the use_sq8 branch further down.
        if use_sq8 && filter.is_none() {
            if let Some(result) = self
                .run_knn_sq8_codes_scan(
                    request,
                    deadline,
                    field,
                    query_vec,
                    k,
                    similarity,
                    boost,
                    min_similarity,
                    started,
                )
                .await
            {
                return Ok(Some(result));
            }
        }
        // The column-only scan needs no source before ranking; a filter reads
        // sources, and `scalar8` keeps the scan its filtered oracle pins.
        let columns_only = columns_only && filter.is_none() && !use_sq8;

        // `scalar8` reads only the pooled vector; the default scan prefers the
        // per-passage companion. The two shapes are cached under different keys.
        let column_mode = if use_sq8 {
            ColumnMode::PooledOnly
        } else {
            ColumnMode::BestPassage
        };

        // ── Collect candidate ADDRESSES, not documents (#939) ─────────
        // A candidate is where a live document sits — a memtable slot or a
        // (segment, position) pair — never a copy of it. The scan this
        // replaces deep-cloned every live `_source`, vectors included, into
        // this list before it had scored or filtered anything: ~10 M
        // `Value::Number`s per query on a 5 k-document multi-passage corpus,
        // and half of each request. Sources are now cloned for the documents
        // that are RETURNED, after ranking. Same shape as qdrant's
        // `ScoredPointOffset` → `process_search_result` and tantivy's
        // `DocAddress` → `Searcher::doc` (pointers in `vector_column.rs`).
        //
        // Candidate ORDER is unchanged — memtable first, then segments in
        // snapshot order, then position — because the rank below is a stable
        // sort and that order is what breaks score ties.
        // #1220 — the capture, bracketed like the BM25 leg's (#1013): the
        // memtable capture and the segment snapshot below must describe ONE
        // publication world, or the admission predicate's version-map reads
        // below have no world to be scoped against. The reference is taken
        // immediately before the pair and validated immediately after (a
        // writer-free instant, not a writer-free scan); a straddling
        // publication answers with the typed retry signal `search()`'s loop
        // already knows how to recapture on. The pre-fix capture had no
        // bracket: this leg returns before `search_inner` validates its own
        // capture at the #1013 check, so nothing ever established that
        // `mem_docs` and `snap` agreed.
        let (capture_generation, _, capture_poisoned) = self.collection_publication.state();
        if capture_poisoned {
            return Err(collection_publication_interrupted());
        }
        // Memtable first (newest writes). `Arc` clones, not tree clones.
        let mem_docs: Vec<(String, Arc<Value>)> = self.memtable.all_docs_with_sources_arc();
        let mut candidates: Vec<KnnCandidateAt> =
            (0..mem_docs.len()).map(KnnCandidateAt::Memtable).collect();
        // Then every flushed segment's stored section.
        let snap = self.store.snapshot();
        {
            let (generation, in_flight, poisoned) = self.collection_publication.state();
            if poisoned {
                return Err(collection_publication_interrupted());
            }
            if generation != capture_generation || in_flight != 0 {
                return Err(collection_capture_crossed());
            }
            self.collection_publication.note_capture_validated();
        }
        // #1220 regression hook: park the scan the instant its capture
        // validates, so a test can publish a write, merge or flush into the
        // window this fix exists to make harmless.
        #[cfg(test)]
        {
            if self.test_pause_knn_after_capture.load(Ordering::Acquire) {
                self.test_knn_capture_parked.store(true, Ordering::Release);
                while self.test_pause_knn_after_capture.load(Ordering::Acquire) {
                    tokio::task::yield_now().await;
                }
                self.test_knn_capture_parked.store(false, Ordering::Release);
            }
        }
        // #1220 — the captured world's segment ids, scoping every LIVE
        // version-map read the admission predicate performs below (see
        // [`CapturedEntryVerdict`]). O(segments) once per search; the walk
        // that consumes it is O(candidates).
        let captured_segment_ids: std::collections::HashSet<&str> =
            snap.segments.iter().map(|meta| meta.id.as_str()).collect();
        // Track seen IDs so later-segment copies don't duplicate memtable entries.
        let mut seen: HashSet<String> = mem_docs.iter().map(|(id, _)| id.clone()).collect();
        let mut segment_views: Vec<KnnSegmentView> = Vec::with_capacity(snap.segments.len());
        for meta in snap.segments.iter() {
            let segment_started = std::time::Instant::now();
            // Cache-backed: first KNN against this segment pays the
            // I/O + decompress + serde_json parse, every subsequent
            // query reads from `stored_value_cache`. For a 100-segment
            // index this turns repeated KNN from O(seg_count * 100MB)
            // copy work into Arc clone + iterate.
            // A cold miss is coalesced and parsed on the bounded blocking
            // pool. This executor's absolute deadline can drop the await
            // while the detached producer finishes warming the segment.
            if std::time::Instant::now() >= deadline {
                timed_out = true;
                break;
            }
            // The segment's vectors as flat `f32`s. Cached per immutable
            // segment; on a miss it is derived in the SAME pass that collects
            // candidates, so a cold query walks the stored documents once and
            // keeps the cooperative checkpoints it always had. Every position
            // is pushed — live or not — because liveness is this query's
            // business and the column outlives it.
            let column_key = format!("{}\u{1}{field}\u{1}{}", meta.id, column_mode.key_tag());
            let cached_column = self
                .vector_column_cache
                .get(&column_key)
                .map(|entry| Arc::clone(entry.value()));
            // #1091: a cached column carries every position's `_id` and
            // `_seq_no`, which is all candidate selection reads. Scanning it
            // alone skips the segment's parsed stored documents — on a
            // passage-chunked corpus tens of kilobytes a document, so they
            // overflow the hydration budget and every query used to decode
            // the whole corpus again (FiQA, 57,638 documents: 6-7 s a query).
            if columns_only {
                let column = match cached_column.as_ref() {
                    Some(column) => Some(Arc::clone(column)),
                    // Bounded like the stored-document load below: past the
                    // deadline the request stops waiting and reports a
                    // timed-out partial answer (the abandoned column is not
                    // published; the next query builds it again).
                    None => match tokio::time::timeout_at(
                        tokio::time::Instant::from_std(deadline),
                        self.projected_vector_column(&meta.id, field, column_key.clone()),
                    )
                    .await
                    {
                        Ok(ProjectedColumn::Built(column)) => Some(column),
                        Ok(ProjectedColumn::NoStoredSection) => continue,
                        Ok(ProjectedColumn::Unavailable) => None,
                        Err(_) => {
                            timed_out = true;
                            break;
                        }
                    },
                };
                if let Some(column) = column {
                    let view = segment_views.len();
                    let mut segment_complete = true;
                    for position in 0..column.len() {
                        if position & 127 == 0
                            && self.exact_scan_checkpoint(position, deadline).await
                        {
                            timed_out = true;
                            segment_complete = false;
                            break;
                        }
                        let Some((id, doc_seq)) = column.identity(position) else {
                            continue;
                        };
                        if self.admit_exact_scan_candidate(
                            &mut seen,
                            id,
                            doc_seq,
                            &meta.id,
                            &captured_segment_ids,
                        ) {
                            candidates.push(KnnCandidateAt::Segment { view, position });
                        }
                    }
                    segment_views.push(KnnSegmentView {
                        segment_id: meta.id.clone(),
                        docs: None,
                        column,
                    });
                    if trace_phases {
                        tracing::info!(index=%self.name, segment=%meta.id, elapsed_ms=segment_started.elapsed().as_millis() as u64, candidates=candidates.len(), "semantic_phase=column_segment");
                    }
                    if !segment_complete {
                        break;
                    }
                    continue;
                }
            }
            let docs_arc = match tokio::time::timeout_at(
                tokio::time::Instant::from_std(deadline),
                self.stored_values_for_async(&meta.id),
            )
            .await
            {
                Ok(Some(a)) => a,
                Ok(None) => continue,
                Err(_) => {
                    timed_out = true;
                    break;
                }
            };
            if std::time::Instant::now() >= deadline {
                timed_out = true;
                break;
            }
            let mut builder = cached_column
                .is_none()
                .then(|| ColumnBuilder::new(field, column_mode));
            let view = segment_views.len();
            let mut segment_complete = true;
            // Cache-backed iteration: stored_values_for() handles the
            // I/O + decode + parse; subsequent KNN over the same segment
            // is an Arc clone. The underlying parse uses serde_json (not
            // simd_json) per ffd49ac — simd_json silently corrupts some
            // raw-bytes-flush payloads, the per-doc alloc cost is
            // irrelevant on the brute-force similarity scan.
            for (position, doc) in docs_arc.iter().enumerate() {
                if position & 127 == 0 && self.exact_scan_checkpoint(position, deadline).await {
                    timed_out = true;
                    segment_complete = false;
                    break;
                }
                if let Some(builder) = builder.as_mut() {
                    builder.push_stored_doc(doc);
                }
                let Some(id) = doc.get("_id").and_then(Value::as_str) else {
                    continue;
                };
                let doc_seq = doc.get("_seq_no").and_then(Value::as_u64);
                if self.admit_exact_scan_candidate(
                    &mut seen,
                    id,
                    doc_seq,
                    &meta.id,
                    &captured_segment_ids,
                ) {
                    candidates.push(KnnCandidateAt::Segment { view, position });
                }
            }
            let column = match (cached_column, builder) {
                (Some(column), _) => column,
                // A column abandoned at the deadline covers a prefix of the
                // segment. It serves this request's partial answer and is
                // dropped — only a complete column is ever published.
                (None, Some(builder)) if !segment_complete => {
                    CacheResident::uncached(builder.finish())
                }
                (None, Some(builder)) => {
                    let column = builder.finish();
                    let bytes = column
                        .retained_bytes()
                        .saturating_add(column_key.len() as u64);
                    // Over budget this comes back uncached: the next query
                    // derives it again, which is what every query did before.
                    self.publish_current(
                        &self.vector_column_cache,
                        &meta.id,
                        column_key,
                        SegmentCacheCategory::VectorColumn,
                        bytes,
                        column,
                    )
                }
                (None, None) => unreachable!("a builder exists whenever the column is not cached"),
            };
            segment_views.push(KnnSegmentView {
                segment_id: meta.id.clone(),
                docs: Some(docs_arc),
                column,
            });
            if trace_phases {
                tracing::info!(index=%self.name, segment=%meta.id, elapsed_ms=segment_started.elapsed().as_millis() as u64, candidates=candidates.len(), "semantic_phase=load_segment");
            }
            if !segment_complete {
                break;
            }
        }
        let collect_elapsed = started.elapsed();

        // `use_sq8` was determined before candidate collection (the codes
        // fast path above may already have returned).
        // The filter runs BEFORE scoring and without the vectors (#939): see
        // `KnnFilterPlan`. It used to clone the whole source a second time,
        // per candidate, to insert `_id` beside ~1,900 numbers it never read.
        let filter_plan = filter.as_deref().map(KnnFilterPlan::for_filter);
        // Memtable documents have no column (the memtable is mutable), so
        // their vectors are read out of the `Arc`'d source one document at a
        // time into this reused scratch — after the filter, never before.
        let mut memtable_scratch = ColumnBuilder::new(field, column_mode);

        // ── Score each candidate against the query vector ─────────────
        // `(candidate index, score, passage ordinal)`: 16 bytes a candidate,
        // where this used to carry every candidate's cloned source through the
        // sort and then drop all but `k` of them.
        let mut scored: Vec<(usize, f32, Option<u32>)> = Vec::with_capacity(candidates.len());
        if use_sq8 {
            // Cosine fields are L2-normalised before quantising so SQ8 fits
            // over bounded [-1,1] per-dim ranges (much better recall); cosine
            // is invariant to that scaling so ranking stays correct. Non-cosine
            // metrics must keep raw magnitudes, so they are quantised as-is.
            let normalize = !matches!(similarity, "l2_norm" | "dot_product" | "max_inner_product");
            let dim = query_vec.len();

            // Post-filter candidate vectors for this field: (candidate, doc_vec).
            let mut cand: Vec<(usize, Vec<f32>)> = Vec::with_capacity(candidates.len());
            for (position, at) in candidates.iter().enumerate() {
                if position & 127 == 0 && self.exact_scan_checkpoint(position, deadline).await {
                    timed_out = true;
                    break;
                }
                if let (Some(plan), Some(f)) = (filter_plan.as_ref(), filter.as_deref()) {
                    let (id, source) = at.id_and_source(&mem_docs, &segment_views);
                    if !plan.matches(f, id, source, &dmq_schema) {
                        continue;
                    }
                }
                let vectors = match *at {
                    KnnCandidateAt::Memtable(slot) => {
                        memtable_scratch.clear();
                        memtable_scratch.push_source(&mem_docs[slot].1);
                        memtable_scratch.column().doc(0)
                    }
                    KnnCandidateAt::Segment {
                        view,
                        position: doc_position,
                    } => segment_views[view].column.doc(doc_position),
                };
                let DocVectorsView::Pooled(vector) = vectors else {
                    continue;
                };
                if vector.values.len() != dim {
                    continue;
                }
                let mut doc_vec = vector.values.to_vec();
                if normalize {
                    l2_normalize_vec(&mut doc_vec);
                }
                cand.push((position, doc_vec));
            }

            // ── Per-query fit over the post-filter candidates ───────────
            //
            // Fit this field's SQ8 codebook over the candidate vectors this
            // query is about to score, and drop it when the query ends. No
            // codec state survives a query (#371).
            //
            // The codebook used to be fitted from the first ≤1000 vectors
            // the field was ever scanned with and then kept for the life of
            // the process, which is the same write-once defect as the
            // per-document code map one level up: a vector written
            // afterwards outside the fitted per-dimension range is CLAMPED
            // into it, and when that range is narrow the clamped decode is
            // indistinguishable from the vector the document used to hold —
            // a corpus whose dimension 0 never left +1.0 fitted `[1,1]`
            // there, so overwriting a document with its exact negation
            // decoded straight back to +1.0 and it stayed top at cosine
            // 1.000000. Fitting over exactly the set being encoded makes
            // clamping structurally impossible here: every value passed to
            // `encode_into` is inside `[min,max]` by construction.
            //
            // A FILTERED `scalar8` query deliberately stays on this codec
            // rather than the ingest-time codes (#392's unfiltered fast
            // path): the reference this scan is pinned against —
            // `exact_scan_hydration_tests`' clone-everything oracle, #979 —
            // fits over the POST-FILTER candidate set, and a filtered
            // subset's per-dimension bounds are generally NARROWER than the
            // whole-corpus fit the store holds (measured on that fixture:
            // three of five filters move at least four of eight bounds), so
            // corpus-fitted codes cannot reproduce its scores. Quantizing
            // exactly the set being scored is also the pre-#392 behaviour,
            // which keeps the filtered path bit-identical to the oracle.
            // The consequence, documented in #392: a filtered score can
            // move by up to SQ8's quantization step relative to the
            // unfiltered codes path when the filter changes the fitted
            // range — the exactness of the scan is the stronger contract.
            let params = Sq8Params::fit_borrowed(cand.iter().map(|(_, v)| v.as_slice()), dim);
            debug!(
                field,
                dim,
                candidates = cand.len(),
                normalize,
                "SQ8 codec fitted for this query (filtered or non-serving codes store)"
            );

            // Score by quantizing each candidate's CURRENT vector and
            // decoding it straight back — 1 byte/dim, so `scalar8`
            // keeps its recall profile, and the score describes the
            // vector the document holds right now. Both buffers are
            // reused across the scan. `v.len() == dim` was
            // established when `cand` was built.
            let mut codes = vec![0u8; dim];
            let mut decoded = vec![0.0f32; dim];
            for (position, (candidate, v)) in cand.into_iter().enumerate() {
                if position & 127 == 0 && self.exact_scan_checkpoint(position, deadline).await {
                    timed_out = true;
                    break;
                }
                params.encode_into(&v, &mut codes);
                params.decode_into(&codes, &mut decoded);
                let score = compute_vector_similarity(similarity, query_vec, &decoded);
                scored.push((candidate, score, None));
            }
        } else {
            // Per-chunk (passage) companion: multi-chunk `semantic_text` docs
            // persist their per-passage vectors under `<field>_chunks` at
            // ingest. When present we score by the BEST-matching passage
            // (max-sim) rather than the single pooled vector — a query that
            // matches one section of a long document ranks that document on
            // that section, not on the whole-doc average. Plain `dense_vector`
            // kNN and short single-chunk docs have no such companion, so they
            // fall through to the exact single-vector scan below (unchanged).
            let scorer = QueryScorer::new(similarity, query_vec);
            for (position, at) in candidates.iter().enumerate() {
                if position & 127 == 0 && self.exact_scan_checkpoint(position, deadline).await {
                    timed_out = true;
                    break;
                }
                // Apply filter: if the filter doesn't match this doc, skip.
                if let (Some(plan), Some(f)) = (filter_plan.as_ref(), filter.as_deref()) {
                    let (id, source) = at.id_and_source(&mem_docs, &segment_views);
                    if !plan.matches(f, id, source, &dmq_schema) {
                        continue;
                    }
                }
                let vectors = match *at {
                    KnnCandidateAt::Memtable(slot) => {
                        memtable_scratch.clear();
                        memtable_scratch.push_source(&mem_docs[slot].1);
                        memtable_scratch.column().doc(0)
                    }
                    KnnCandidateAt::Segment {
                        view,
                        position: doc_position,
                    } => segment_views[view].column.doc(doc_position),
                };
                let (score, passage_ordinal) = match vectors {
                    DocVectorsView::Absent => continue,
                    DocVectorsView::Chunks(passages) => {
                        // Best-matching passage over the stored chunk vectors.
                        let mut best: Option<(f32, u32)> = None;
                        for passage in passages {
                            // Bounds ONE pathological document. The per-128-
                            // documents checkpoint above is the scan's cadence;
                            // this used to fire at passage 0 of every document
                            // as well, which was one `yield_now` per document
                            // per query for no bound the outer check lacks.
                            if passage.ordinal > 0
                                && passage.ordinal & 31 == 0
                                && self
                                    .exact_scan_checkpoint(passage.ordinal as usize, deadline)
                                    .await
                            {
                                timed_out = true;
                                break;
                            }
                            if passage.values.len() != query_vec.len() {
                                continue;
                            }
                            choose_passage_winner(
                                &mut best,
                                scorer.score(passage),
                                passage.ordinal,
                            );
                        }
                        match best {
                            Some((score, ordinal)) => (score, Some(ordinal)),
                            None => continue,
                        }
                    }
                    DocVectorsView::Pooled(vector) => {
                        if vector.values.len() != query_vec.len() {
                            continue;
                        }
                        (scorer.score(vector), Some(0))
                    }
                };
                scored.push((position, score, passage_ordinal));
            }
        }
        if trace_phases {
            tracing::info!(index=%self.name, collect_ms=collect_elapsed.as_millis() as u64, elapsed_ms=started.elapsed().as_millis() as u64, scored=scored.len(), "semantic_phase=scored");
        }

        // ── ES `knn.similarity` cutoff ─────────────────────────────────
        // Convert the RAW-metric threshold into the equivalent
        // transformed-score threshold (the same transform
        // `compute_vector_similarity` applies to candidates) and drop
        // everything below it BEFORE ranking, so `hits.total` reflects
        // the cutoff — ES 8.13 excludes sub-threshold docs from hits AND
        // total (live-verified 2026-07-12).
        if let Some(raw) = min_similarity {
            let cut = raw_similarity_to_score(similarity, raw);
            scored.retain(|(_, score, _)| *score >= cut);
        }
        // ES applies `boost` to the final `_score` AFTER the similarity
        // cutoff (a boosted sub-threshold doc stays excluded; a boosted
        // passing doc scores `transform(sim) * boost`).
        if let Some(b) = boost {
            if (b - 1.0).abs() > f32::EPSILON {
                for (_, score, _) in scored.iter_mut() {
                    *score *= b;
                }
            }
        }

        // ── Rank, cap the pool at k, THEN hydrate (#939) ──────────────
        // Same comparator, same stability and same `k.max(1)` cap as
        // `knn_result_from_scored`, applied to 16-byte tuples instead of to
        // every candidate's source. Only the survivors are cloned out of the
        // shared stored values, so a query pays for `k` sources, not for the
        // corpus.
        rank_knn_pool(&mut scored, k, |entry| entry.1);
        // #1091: winners in a column-scanned segment are hydrated together,
        // one row-selective decode per segment, before the page is assembled.
        let mut by_view: HashMap<usize, Vec<usize>> = HashMap::new();
        for (candidate, _, _) in &scored {
            if let KnnCandidateAt::Segment { view, position } = candidates[*candidate] {
                if segment_views[view].docs.is_none() {
                    by_view.entry(view).or_default().push(position);
                }
            }
        }
        let (generated_companion_fields, knn_schema) = {
            let schema = self.schema.read().await;
            (
                generated_embedding_companion_fields(&schema.schema),
                // #1745: filter/filters aggs evaluate their clauses with the
                // query matcher; only clone the mapping when this request
                // actually carries aggregations.
                request.aggs.as_ref().map(|_| schema.schema.clone()),
            )
        };
        // The default `_source` drops the generated embedding companions from
        // every hit without reporting it (`apply_source_filter_measured`), and
        // none of the shapes below reads a hit's source before that: so for
        // them the companions are not hydrated at all. Anything else — an
        // explicit `_source`, aggregations over the neighbours, `fields`,
        // scripts, sort, collapse, rescore — gets the whole document.
        //
        // #1947: a semantic highlight against an active embedder scores the
        // stored per-chunk vectors. Those columns are normally omitted (they
        // are the expensive ones). Keep `<target>_chunks` and still omit the
        // pooled vector. The lexical embedder re-embeds chunk text instead
        // and does not need the columns.
        let mut companion_omit = generated_companion_fields.clone();
        if SEMANTIC_HIGHLIGHT_PLAN
            .try_with(|plan| !plan.lexical)
            .unwrap_or(false)
        {
            companion_omit.retain(|name| !name.ends_with("_chunks"));
        }
        let omit_companions = (matches!(request.source, SourceFilter::Default)
            && !companion_omit.is_empty()
            && request.aggs.is_none()
            && request.fields.is_empty()
            && request.script_fields.is_none()
            && request.sort.is_empty()
            && request.collapse.is_none()
            && request.rescore.is_empty())
        .then(|| Arc::new(companion_omit));
        let mut column_hits: HashMap<(usize, usize), (String, Value)> = HashMap::new();
        for (view, positions) in by_view {
            let hydrate_started = std::time::Instant::now();
            let rows_wanted = positions.len();
            let rows = match self
                .hydrate_segment_rows(
                    &segment_views[view].segment_id,
                    positions.clone(),
                    omit_companions.clone(),
                )
                .await
            {
                Some(rows) => rows,
                // A section the row decoder cannot address — LZ4 below
                // `V2_MIN_DOCS` documents, a ZBS3 wrapper, a dependency shape
                // it refuses — is hydrated the way it always was, from the
                // segment's parsed stored documents. Only a segment that is
                // gone altogether sends the request back to a full rescan.
                None => {
                    let Some(docs) = self
                        .stored_values_for_async(&segment_views[view].segment_id)
                        .await
                    else {
                        return Ok(None);
                    };
                    let Some(rows) = positions
                        .iter()
                        .map(|&position| docs.get(position).map(knn_stored_hit))
                        .collect::<Option<Vec<_>>>()
                    else {
                        return Ok(None);
                    };
                    rows
                }
            };
            for (position, (id, source)) in positions.into_iter().zip(rows) {
                // The row must be the document the column scored.
                if segment_views[view]
                    .column
                    .identity(position)
                    .map(|(id, _)| id)
                    != Some(id.as_str())
                {
                    return Ok(None);
                }
                column_hits.insert((view, position), (id, source));
            }
            if trace_phases {
                tracing::info!(index=%self.name, segment=%segment_views[view].segment_id, rows=rows_wanted, elapsed_ms=hydrate_started.elapsed().as_millis() as u64, "semantic_phase=hydrate_rows");
            }
        }
        let mut ranked: Vec<(String, f32, Value, Option<u32>)> = Vec::with_capacity(scored.len());
        for (candidate, score, ordinal) in scored {
            let (id, source) = match candidates[candidate].hydrate(&mem_docs, &segment_views) {
                KnnHydrated::Ready(id, source) => (id, source),
                KnnHydrated::Columnar { view, position } => {
                    match column_hits.remove(&(view, position)) {
                        Some(hit) => hit,
                        None => return Ok(None),
                    }
                }
            };
            ranked.push((id, score, source, ordinal));
        }

        // (result shaping is shared with the HNSW path so hits format / total
        // semantics cannot drift between the exact and approximate executors)
        let mut result = knn_result_from_ranked(
            self,
            request,
            field,
            ranked,
            started,
            &generated_companion_fields,
            knn_schema.as_ref(),
        );
        result.timed_out = timed_out;
        if timed_out {
            result.total.relation = TotalHitsRelation::Gte;
        }
        if trace_phases {
            tracing::info!(index=%self.name, elapsed_ms=started.elapsed().as_millis() as u64, hits=result.hits.len(), "semantic_phase=complete");
        }
        Ok(Some(result))
    }

    /// PURE multi-KNN executor (the ES top-level `knn: [...]` array form,
    /// synthesised by the compat layer as `bool.should` of Knn nodes).
    ///
    /// ES 8.13 semantics (live-verified 2026-07-12 against 8.13.4):
    ///   * each clause independently retrieves its own top `k_i`;
    ///   * a doc found by multiple clauses scores the SUM of its
    ///     per-clause scores (each already boosted/cut per clause);
    ///   * `hits.total` is the size of the deduplicated union.
    async fn run_multi_knn_brute_force(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        clauses: Vec<PeeledKnn>,
    ) -> Result<SearchResult> {
        let started = std::time::Instant::now();
        let mut merged: Vec<(String, f32, Value, Option<u32>)> = Vec::new();
        let mut slot_by_id: HashMap<String, usize> = HashMap::new();
        let mut k_sum: usize = 0;
        let mut any_timed_out = false;
        for clause in clauses {
            if std::time::Instant::now() >= deadline {
                any_timed_out = true;
                break;
            }
            k_sum = k_sum.saturating_add(clause.k);
            let similarity = {
                let schema = self.schema.read().await;
                lookup_vector_similarity(&schema.schema, &clause.field)
            };
            // Per-clause top-k: window the sub-search to exactly the
            // clause's own pool so the union matches ES's per-clause
            // retrieval (from/size pagination applies to the MERGED
            // list below, not to each clause).
            let mut sub_request = request.clone();
            sub_request.from = 0;
            sub_request.size = clause.k;
            let sub = self
                .run_knn_brute_force_with_deadline(
                    &sub_request,
                    deadline,
                    &clause.field,
                    &clause.vector,
                    clause.k,
                    clause.filter,
                    &similarity,
                    clause.boost,
                    clause.similarity,
                )
                .await?;
            any_timed_out |= sub.timed_out;
            for hit in sub.hits {
                match slot_by_id.get(&hit.id) {
                    Some(&i) => merged[i].1 += hit.score,
                    None => {
                        slot_by_id.insert(hit.id.clone(), merged.len());
                        merged.push((
                            hit.id,
                            hit.score,
                            hit.source,
                            hit.passage.map(|passage| passage.ordinal),
                        ));
                    }
                }
            }
            if any_timed_out {
                break;
            }
        }
        // Multi-field KNN has no single vector field with which to resolve
        // passage metadata. Child clauses retain ordinary ranking semantics;
        // provenance is intentionally omitted until per-clause ownership is
        // represented in the merged winner.
        let (generated_companion_fields, knn_schema) = {
            let schema = self.schema.read().await;
            (
                generated_embedding_companion_fields(&schema.schema),
                // #1745: filter/filters aggs evaluate their clauses with the
                // query matcher; only clone the mapping when this request
                // actually carries aggregations.
                request.aggs.as_ref().map(|_| schema.schema.clone()),
            )
        };
        let mut result = knn_result_from_scored(
            self,
            request,
            "",
            merged,
            k_sum,
            started,
            &generated_companion_fields,
            knn_schema.as_ref(),
        );
        result.timed_out = any_timed_out;
        if any_timed_out {
            result.total.relation = TotalHitsRelation::Gte;
        }
        Ok(result)
    }

    /// True iff at least one indexed document carries a numeric-array vector at
    /// `field` — the execution-truth signal that a field CAN answer a vector
    /// query even when it was never declared `dense_vector`. This is the case a
    /// schema-only (or `hnsw_field`) check gets wrong: a field seeded with, say,
    /// 256 undeclared vectors is below `HNSW_MIN_DOCS`, so no graph exists and
    /// `hnsw_field` is `None`, yet the field is fully brute-force answerable
    /// (#498/#529). Early-exits on the first hit and is only invoked on an empty
    /// knn result, so it never runs on the hot path.
    async fn index_has_any_vector_at(&self, field: &str) -> bool {
        for (_id, source) in self.memtable.all_docs_with_sources() {
            if extract_numeric_vector(&source, field).is_some() {
                return true;
            }
        }
        let snap = self.store.snapshot();
        for meta in snap.segments.iter() {
            if let Some(docs) = self.stored_values_for_async(&meta.id).await {
                for doc in docs.iter() {
                    let src = doc.get("_source").unwrap_or(doc);
                    if extract_numeric_vector(src, field).is_some() {
                        return true;
                    }
                }
            }
        }
        false
    }

    /// #498: reject a `knn`/`semantic` clause naming a field the index cannot
    /// answer with a `400`, instead of the silent empty `200` it used to return.
    /// "Cannot answer" is execution truth: the field is neither declared
    /// `dense_vector`/`semantic_text` NOR does any indexed document carry a
    /// vector for it. A declared-but-empty vector field, and an undeclared field
    /// that nonetheless holds indexed vectors, both legitimately return an empty
    /// result — only a genuinely non-vector field is rejected (the distinction
    /// #529's mapping-only gate got wrong). Called only on an empty, non-timed-
    /// out result, so the extra scan never touches the hot path.
    async fn reject_unanswerable_knn_field(&self, field: &str) -> Result<()> {
        {
            let schema = self.schema.read().await;
            if collect_dense_vector_fields(&schema.schema)
                .iter()
                .any(|f| f == field)
            {
                return Ok(());
            }
            if schema
                .schema
                .field(field)
                .is_some_and(|fc| fc.embedding.is_some())
            {
                return Ok(());
            }
        }
        if self.index_has_any_vector_at(field).await {
            return Ok(());
        }
        Err(EngineError::Common(xerj_common::XerjError::invalid_query(
            format!(
                "[knn] query field [{field}] is not a vector field: it is absent from the \
                 mapping and carries no indexed vector data. Map it as [dense_vector] (or \
                 [semantic_text]) before running vector search."
            ),
        )))
    }

    /// #542: the nested-knn analogue of [`Self::index_has_any_vector_at`].
    /// Nested vectors live at `<nested_path>[].<subfield>` (see the scoring loop
    /// in `run_nested_knn_brute_force_with_deadline`), so the top-level scan
    /// would false-negative on them — this mirrors that traversal exactly.
    /// Early-exits on the first hit; only invoked on an empty nested-knn result.
    async fn index_has_any_nested_vector_at(&self, nested_path: &str, subfield: &str) -> bool {
        fn elem_has_vector(elem: &Value, subfield: &str) -> bool {
            match elem.get(subfield) {
                Some(Value::String(text)) => xerj_common::packed_f32::unpack_f32_vector(text)
                    .is_some_and(|values| !values.is_empty()),
                Some(value) => value
                    .as_array()
                    .is_some_and(|a| !a.is_empty() && a.iter().all(Value::is_number)),
                None => false,
            }
        }
        fn doc_has(source: &Value, nested_path: &str, subfield: &str) -> bool {
            match get_field_value(source, nested_path) {
                Some(Value::Array(arr)) => arr.iter().any(|e| elem_has_vector(e, subfield)),
                Some(single) => elem_has_vector(&single, subfield),
                None => false,
            }
        }
        for (_id, source) in self.memtable.all_docs_with_sources() {
            if doc_has(&source, nested_path, subfield) {
                return true;
            }
        }
        let snap = self.store.snapshot();
        for meta in snap.segments.iter() {
            if let Some(docs) = self.stored_values_for_async(&meta.id).await {
                for doc in docs.iter() {
                    let src = doc.get("_source").unwrap_or(doc);
                    if doc_has(src, nested_path, subfield) {
                        return true;
                    }
                }
            }
        }
        false
    }

    /// #542: reject a NESTED `knn` clause naming a field the index cannot
    /// answer with a 400, symmetric with [`Self::reject_unanswerable_knn_field`].
    /// Declared `dense_vector` (dotted path) short-circuits; otherwise the nested
    /// vector-presence scan decides, so declared-but-empty and
    /// indexed-but-undeclared nested fields still return their real empty result.
    async fn reject_unanswerable_nested_knn_field(
        &self,
        nested_path: &str,
        field: &str,
    ) -> Result<()> {
        {
            let schema = self.schema.read().await;
            if collect_dense_vector_fields(&schema.schema)
                .iter()
                .any(|f| f == field)
            {
                return Ok(());
            }
        }
        let subfield = field
            .strip_prefix(&format!("{nested_path}."))
            .unwrap_or(field);
        if self
            .index_has_any_nested_vector_at(nested_path, subfield)
            .await
        {
            return Ok(());
        }
        Err(EngineError::Common(xerj_common::XerjError::invalid_query(
            format!(
                "[knn] nested query field [{field}] is not a vector field: it is absent from \
                 the nested mapping and carries no indexed vector data. Map it as \
                 [dense_vector] before running vector search."
            ),
        )))
    }

    /// Brute-force nested KNN: score each parent by the best (max)
    /// similarity among its `<nested_path>` array elements.
    ///
    /// Semantic search executor. Embeds the natural-language query
    /// text via the configured `EmbeddingProxy`, then runs filtered
    /// kNN against the same field.
    ///
    /// Failure modes:
    ///  * No proxy configured → 400 with a clear config hint.
    ///  * Proxy returns an empty / mismatched-dim vector → 400.
    ///  * Proxy network / 5xx error → propagate the proxy's error.
    ///
    /// We deliberately do NOT silently fall back to BM25 on embed
    /// failure — the semantic query type is opt-in by the caller and
    /// quietly degrading would mask deployment bugs (missing API
    /// key, throttled key, model name typo). Operators wanting that
    /// behaviour can wrap the call in a `dis_max` of `semantic` +
    /// `match` clauses.
    pub async fn run_semantic(
        &self,
        request: &SearchRequest,
        field: &str,
        text: &str,
        k: usize,
        filter: Option<Box<QueryNode>>,
    ) -> Result<SearchResult> {
        let deadline = std::time::Instant::now()
            + std::time::Duration::from_millis(request.timeout_ms.unwrap_or(30_000));
        self.run_semantic_with_deadline(request, deadline, field, text, k, filter)
            .await
    }

    async fn run_semantic_with_deadline(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        field: &str,
        text: &str,
        k: usize,
        filter: Option<Box<QueryNode>>,
    ) -> Result<SearchResult> {
        // Resolve whether `field` is a `semantic_text` field (has an embedding
        // config). If so, the vector lives in the companion `target_field` and
        // was produced by the same embedder used at ingest — so we must embed
        // the query with that same embedder and kNN against `target_field`.
        let (knn_field, dims, is_semantic_text, similarity) = {
            let schema = self.schema.read().await;
            // Resolve a field alias to its concrete target first, so `semantic`
            // respects field aliases the way `match`/`term` already do. A console
            // or agent that queries `embedding` — aliased to the corpus's real
            // semantic field (e.g. autoindex's `body`) — then finds that field's
            // embedding config and kNNs against its companion vector. Without
            // this the aliased, vectorless name falls through to the arm below
            // and the query is rejected as "not a `semantic_text` field"
            // (pinned by `test_semantic_field_alias_resolution`).
            let field = &resolve_field_alias(&schema.schema, field);
            match schema.schema.field(field) {
                Some(fc) if fc.embedding.is_some() => {
                    let emb = fc.embedding.as_ref().unwrap();
                    let target = emb
                        .target_field
                        .clone()
                        .unwrap_or_else(|| format!("{field}_vector"));
                    let dims = fc
                        .options
                        .dimensions
                        .unwrap_or(xerj_ai::local::DEFAULT_DIMS);
                    let sim = fc
                        .options
                        .similarity
                        .clone()
                        .unwrap_or_else(|| "cosine".to_string());
                    (target, dims, true, sim)
                }
                _ => (
                    field.to_string(),
                    xerj_ai::local::DEFAULT_DIMS,
                    false,
                    lookup_vector_similarity(&schema.schema, field),
                ),
            }
        };

        // Embed the query text with the effective embedder:
        //   * An ACTIVE backend (Candle neural BERT, experimental ONNX, or an
        //     external proxy) embeds the query text directly — the same
        //     backend used at ingest.
        //   * Otherwise the built-in lexical embedder — but ONLY for
        //     `semantic_text` fields, which were embedded that same way at
        //     ingest. A `semantic` query against a plain dense_vector field
        //     with no active backend still returns the original 400 (there
        //     is no comparable stored vector to match against).
        let semantic_started = std::time::Instant::now();
        let trace_phases = std::env::var_os("XERJ_TRACE_SEMANTIC_PHASES").is_some();
        let embedder = self.embedder.read().await;
        if trace_phases {
            tracing::info!(index=%self.name, field, k, "semantic_phase=embed_start");
        }
        // Captured before the embed so the highlighter scores chunks in the
        // same space as `query_vec` (#1947). An active backend's vectors are
        // already stored; the lexical fallback re-embeds chunk text.
        let lexical_embedder = !embedder.is_active();
        let query_vec = if embedder.is_active() {
            // `embed_batch` takes Vec<String>; we only have one text but
            // batching keeps the wire format stable for callers.
            let mut vectors = embedder
                .embed_batch(vec![text.to_string()])
                .await
                .map_err(|e| {
                    // Item 9: preserve the embedder's 5xx class. An embedding
                    // backend outage/misconfig is NOT a client query error;
                    // wrapping it as invalid_query (400) hid proxy failures
                    // behind a 400 and drove clients to retry a broken backend.
                    EngineError::Common(embed_backend_error(e, "semantic query embed failed"))
                })?;
            match vectors.pop() {
                Some(v) if !v.is_empty() => v,
                _ => {
                    return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                        "embedder returned no vector for semantic query",
                    )));
                }
            }
        } else if is_semantic_text {
            xerj_ai::local::local_embed(text, dims)
        } else {
            // #530: name the offending field, symmetric with the knn 400 (#498).
            // A concrete index keeps this 400. A wildcard, `_all`, or alias
            // expansion is isolated by the search coordinator (#2305): those
            // indices contribute no hits instead of failing the request.
            // Do not soften this error here — the explicit-index contract is
            // the 400, and the coordinator matches this reason text.
            return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                format!(
                    "semantic query on field [{field}]: it is not a `semantic_text` field, so \
                     there is no comparable stored vector to match. A `semantic` query requires \
                     either a `semantic_text` field (auto-embedded with the built-in lexical \
                     embedder) or an active embedding backend (`embedding.mode = \"neural\"`; \
                     `\"proxy\"` with `embedding.default_endpoint` set to an OpenAI-compatible \
                     endpoint; or `\"onnx-experimental\"` in an ONNX-enabled build with explicit \
                     model and tokenizer paths)."
                ),
            )));
        };
        drop(embedder);
        if trace_phases {
            tracing::info!(index=%self.name, elapsed_ms=semantic_started.elapsed().as_millis() as u64, "semantic_phase=embed_complete");
        }

        // #1947: the semantic highlighter reads this plan from the task that
        // runs the kNN executors. Threading it through every executor
        // signature would touch the plain-knn call sites for a post-pass
        // those queries do not use. The plan is set only when this request
        // actually asks to highlight a `semantic_text` field.
        let highlight_plan = if request.highlight.is_some() {
            let schema = self.schema.read().await;
            let resolved = resolve_field_alias(&schema.schema, field);
            let fields = collect_semantic_highlight_fields(&schema.schema, field, &resolved);
            drop(schema);
            request.highlight.as_ref().and_then(|hl| {
                semantic_highlight_plan(
                    hl,
                    fields,
                    query_vec.clone(),
                    dims,
                    similarity.clone(),
                    lexical_embedder,
                )
            })
        } else {
            None
        };

        // Match the top-level kNN serving policy: plain, unfiltered semantic
        // queries may use the fully covered HNSW graph and are exact-rescored
        // against stored vectors. Filters and aggregations remain exact scans
        // so approximation cannot change filter/analytics membership.
        let searched = async {
            if filter.is_none() && request.aggs.is_none() {
                match Box::pin(self.run_knn_hnsw(
                    request,
                    deadline,
                    &knn_field,
                    &query_vec,
                    k,
                    None,
                    &similarity,
                ))
                .await
                {
                    Some(result) => Ok(result),
                    None => {
                        Box::pin(self.run_knn_brute_force_with_deadline(
                            request,
                            deadline,
                            &knn_field,
                            &query_vec,
                            k,
                            filter,
                            &similarity,
                            None,
                            None,
                        ))
                        .await
                    }
                }
            } else {
                Box::pin(self.run_knn_brute_force_with_deadline(
                    request,
                    deadline,
                    &knn_field,
                    &query_vec,
                    k,
                    filter,
                    &similarity,
                    None,
                    None,
                ))
                .await
            }
        };
        let result = match highlight_plan {
            Some(plan) => SEMANTIC_HIGHLIGHT_PLAN.scope(plan, searched).await,
            None => searched.await,
        };
        if trace_phases {
            tracing::info!(index=%self.name, elapsed_ms=semantic_started.elapsed().as_millis() as u64, ok=result.is_ok(), "semantic_phase=request_complete");
        }
        result
    }

    /// Auto-embed `semantic_text` fields on ingest.
    ///
    /// For each schema field carrying an [`EmbeddingConfig`], reads the field's
    /// text from `source` and writes an embedding into the config's
    /// `target_field` (default `<field>_vector`). Uses the configured
    /// [`EmbeddingProxy`] when present, else the zero-config built-in
    /// deterministic embedder — the *same* choice made at query time so the
    /// vectors are comparable. Fields where the target already holds a value
    /// (caller pre-embedded) or whose value is not a string are left untouched.
    async fn apply_semantic_embeddings(&self, source: Value) -> Result<Value> {
        self.apply_semantic_embeddings_batch(vec![source])
            .await
            .pop()
            .expect("one input produces one output")
    }

    /// Prepare embeddings for several documents in shared inference windows.
    ///
    /// The returned vector is position-aligned with `sources`. A failed
    /// backend window is retried per document-field job so one bad item does
    /// not turn otherwise valid bulk items into failures.
    pub(crate) async fn apply_semantic_embeddings_batch(
        &self,
        mut sources: Vec<Value>,
    ) -> Vec<Result<Value>> {
        // Collect (field, target_field, dims) specs without holding the schema
        // lock across the (possibly async) embedding calls.
        let specs: Vec<(String, String, usize)> = {
            let schema = self.schema.read().await;
            schema
                .schema
                .fields
                .iter()
                .filter_map(|fc| {
                    fc.embedding.as_ref().map(|emb| {
                        let target = emb
                            .target_field
                            .clone()
                            .unwrap_or_else(|| format!("{}_vector", fc.name));
                        let dims = fc
                            .options
                            .dimensions
                            .unwrap_or(xerj_ai::local::DEFAULT_DIMS);
                        (fc.name.clone(), target, dims)
                    })
                })
                .collect()
        };
        #[cfg(test)]
        if crate::bulk::semantic_lifecycle_hook(
            self.name.as_str(),
            crate::bulk::SemanticLifecyclePoint::EmbeddingInside,
        ) == crate::bulk::SemanticLifecycleFault::Embedding
        {
            return sources
                .into_iter()
                .map(|_| {
                    Err(crate::EngineError::Common(
                        xerj_common::XerjError::invalid_query(
                            "injected semantic embedding failure inside \
                             apply_semantic_embeddings_batch",
                        ),
                    ))
                })
                .collect();
        }
        if specs.is_empty() {
            return sources.into_iter().map(Ok).collect();
        }

        struct EmbedJob {
            source_idx: usize,
            field: String,
            target: String,
            dims: usize,
            original_text: String,
            texts: Vec<String>,
            offsets: Vec<(usize, usize)>,
        }

        let mut jobs = Vec::<EmbedJob>::new();
        let mut pre_failures: Vec<Option<String>> = (0..sources.len()).map(|_| None).collect();
        let allowed_metadata_fields: HashSet<String> = specs
            .iter()
            .map(|(_, target, _)| passage_metadata_field(target))
            .collect();
        for (source_idx, source) in sources.iter().enumerate() {
            let Some(object) = source.as_object() else {
                continue;
            };
            if let Some(name) = object.keys().find(|name| {
                name.starts_with(PASSAGE_METADATA_PREFIX)
                    && !allowed_metadata_fields.contains(*name)
            }) {
                pre_failures[source_idx] = Some(format!(
                    "field [{name}] uses XERJ's reserved passage-metadata prefix; \
                     remove it or rename the user field"
                ));
            }
        }
        let onnx_pinned = self
            .embedding_config
            .mode
            .eq_ignore_ascii_case("onnx-experimental");
        for (source_idx, source) in sources.iter().enumerate() {
            if pre_failures[source_idx].is_some() {
                continue;
            }
            #[cfg(test)]
            if crate::bulk::semantic_lifecycle_hook(
                self.name.as_str(),
                crate::bulk::SemanticLifecyclePoint::EmbeddingItemInside,
            ) == crate::bulk::SemanticLifecycleFault::Embedding
            {
                pre_failures[source_idx] =
                    Some("injected per-item semantic embedding failure".to_string());
                continue;
            }
            let Some(obj) = source.as_object() else {
                continue;
            };
            for (field, target, dims) in &specs {
                let supplied_vector = obj.get(target).map(|v| !v.is_null()).unwrap_or(false);
                let supplied_chunks = obj
                    .get(&format!("{target}_chunks"))
                    .map(|v| !v.is_null())
                    .unwrap_or(false);
                let supplied_metadata = obj.contains_key(&passage_metadata_field(target));
                if supplied_metadata {
                    pre_failures[source_idx] = Some(format!(
                        "field [{}] is engine-owned passage metadata; submit semantic text \
                         without derived vectors or reserved metadata",
                        passage_metadata_field(target)
                    ));
                    continue;
                }
                if onnx_pinned && (supplied_vector || supplied_chunks) {
                    pre_failures[source_idx] = Some(format!(
                        "field [{field}]: caller-supplied derived vectors are not accepted for \
                         an ONNX-pinned semantic index because their model identity cannot be \
                         verified; submit text only or use a separate explicitly pre-embedded index"
                    ));
                    continue;
                }
                if supplied_vector {
                    continue;
                }
                let Some(text) = obj.get(field).and_then(Value::as_str) else {
                    continue;
                };
                let chunks = semantic_chunker().chunk(text, None);
                let (texts, offsets) = if chunks.len() <= 1 {
                    (vec![text.to_string()], vec![(0, text.len())])
                } else {
                    (
                        chunks.iter().map(|c| c.text.clone()).collect(),
                        chunks
                            .iter()
                            .map(|c| (c.start_offset, c.end_offset))
                            .collect(),
                    )
                };
                jobs.push(EmbedJob {
                    source_idx,
                    field: field.clone(),
                    target: target.clone(),
                    dims: *dims,
                    original_text: text.to_string(),
                    texts,
                    offsets,
                });
            }
        }

        let mut outputs: Vec<Option<Vec<Vec<f32>>>> = vec![None; jobs.len()];
        let mut failures = pre_failures;
        let mut admission_rejections = vec![false; sources.len()];
        // #2191: a backend that answers with the wrong vector WIDTH is a
        // mapping contradiction, not a transient fault — retrying the same
        // document can never succeed. Those failures surface as a per-item
        // 400 (`invalid mapping`) instead of a retryable 500.
        let mut width_mismatches = vec![false; sources.len()];

        let embedder = self.embedder.read().await;
        if embedder.is_active() {
            // Bound caller-side windows as well as backend-internal batches.
            // This avoids an arbitrarily large proxy payload and gives ONNX a
            // useful cross-document scheduling window without giant padding.
            let max_passages_per_window = self.embedding_config.onnx_scheduling_window;
            let passage_counts = jobs.iter().map(|job| job.texts.len()).collect::<Vec<_>>();
            // Window boundaries only — do NOT materialize passage texts here.
            // Pre-building (and cloning) every window's texts up front held
            // ~N× the request's semantic text for the entire embedding loop
            // (#71). Keep `(start, end, passages)` and build each window's texts
            // lazily, MOVING them into `embed_batch`, so only the in-flight
            // window(s) are resident at a time.
            let mut windows = Vec::new();
            let mut start = 0;
            while start < jobs.len() {
                let (end, passages) =
                    semantic_embedding_window_end(&passage_counts, start, max_passages_per_window);
                windows.push((start, end, passages));
                start = end;
            }
            // Collect one window's passage texts on demand (borrows `jobs`).
            let window_texts = |start: usize, end: usize| -> Vec<String> {
                jobs[start..end]
                    .iter()
                    .flat_map(|job| job.texts.iter().cloned())
                    .collect()
            };

            // Two sessions are an explicit opt-in. Launch at most two complete
            // windows together, drain both, then consume results in input
            // order. This bounds native work and keeps retry/publication
            // behavior deterministic when one sibling fails.
            //
            // Every other backend runs the same windows through a
            // bounded-concurrency scheduler: the default bound of 1 is the
            // historical one-window-at-a-time loop, and
            // `embedding.neural_window_concurrency` raises it so a single
            // `_bulk` stream can keep several neural forward passes in flight
            // on the shared model instead of one (#938). Each window is still
            // embedded as its own batch and reassembled by position, so the
            // vectors computed per passage are identical to the serial loop.
            let mut window_results = Vec::with_capacity(windows.len());
            if dual_session_scheduler_enabled(
                onnx_pinned,
                self.embedding_config.onnx_session_pool_size,
            ) {
                let results = collect_ordinal_buffered_two(windows.len(), |ordinal| {
                    let (start, end, _passages) = windows[ordinal];
                    embedder.embed_batch(window_texts(start, end))
                })
                .await;
                window_results.extend(
                    windows
                        .iter()
                        .zip(results)
                        .map(|(window, result)| (window.0, window.1, window.2, result)),
                );
            } else {
                let results = collect_ordinal_buffered(
                    windows.len(),
                    self.embedding_config.neural_window_concurrency,
                    |ordinal| {
                        let (start, end, _passages) = windows[ordinal];
                        embedder.embed_batch(window_texts(start, end))
                    },
                )
                .await;
                window_results.extend(
                    windows
                        .iter()
                        .zip(results)
                        .map(|(window, result)| (window.0, window.1, window.2, result)),
                );
            }

            for (start, end, passages, batch_result) in window_results {
                match batch_result {
                    Ok(vectors) if vectors.len() == passages => {
                        let mut offset = 0;
                        for job_idx in start..end {
                            let count = jobs[job_idx].texts.len();
                            let job_vectors = &vectors[offset..offset + count];
                            if let Some(vector) = job_vectors
                                .iter()
                                .find(|vector| vector.len() != jobs[job_idx].dims)
                            {
                                width_mismatches[jobs[job_idx].source_idx] = true;
                                failures[jobs[job_idx].source_idx] = Some(format!(
                                    "field [{}]: embedding backend returned width {}, mapping requires {}",
                                    jobs[job_idx].field,
                                    vector.len(),
                                    jobs[job_idx].dims
                                ));
                            } else {
                                outputs[job_idx] = Some(job_vectors.to_vec());
                            }
                            offset += count;
                        }
                    }
                    batch_result => {
                        // Preserve per-item bulk behavior on a backend error:
                        // retry each document-field job separately and only
                        // fail the sources whose own retry fails.
                        let batch_error = match batch_result {
                            Ok(v) => format!(
                                "embedding backend returned {} vectors for {passages} texts",
                                v.len()
                            ),
                            Err(e) => e.to_string(),
                        };
                        tracing::warn!(
                            error = %batch_error,
                            jobs = end - start,
                            passages,
                            "semantic embedding window failed; retrying per item"
                        );
                        for job_idx in start..end {
                            match embedder.embed_batch(jobs[job_idx].texts.clone()).await {
                                Ok(v)
                                    if v.len() == jobs[job_idx].texts.len()
                                        && v.iter()
                                            .all(|vector| vector.len() == jobs[job_idx].dims) =>
                                {
                                    outputs[job_idx] = Some(v);
                                }
                                Ok(v) => {
                                    let widths = v
                                        .iter()
                                        .map(Vec::len)
                                        .collect::<std::collections::BTreeSet<_>>();
                                    // Only a width error when every text got a
                                    // vector; a short answer is a backend fault.
                                    width_mismatches[jobs[job_idx].source_idx] =
                                        v.len() == jobs[job_idx].texts.len();
                                    failures[jobs[job_idx].source_idx] = Some(format!(
                                        "field [{}]: embedding backend returned {} vectors with widths {:?} for {} texts; mapping requires width {}",
                                        jobs[job_idx].field,
                                        v.len(),
                                        widths,
                                        jobs[job_idx].texts.len(),
                                        jobs[job_idx].dims,
                                    ));
                                }
                                Err(e) => {
                                    width_mismatches[jobs[job_idx].source_idx] = false;
                                    admission_rejections[jobs[job_idx].source_idx] =
                                        is_embedding_admission_rejection(&e);
                                    failures[jobs[job_idx].source_idx] =
                                        Some(format!("field [{}]: {e}", jobs[job_idx].field));
                                }
                            }
                        }
                    }
                }
            }
        } else {
            for (job_idx, job) in jobs.iter().enumerate() {
                // The lexical fallback intentionally keeps its deterministic
                // per-document chunking behavior.
                outputs[job_idx] = Some(local_chunk_vectors(&job.original_text, job.dims));
            }
        }

        for (job_idx, job) in jobs.into_iter().enumerate() {
            if failures[job.source_idx].is_some() {
                continue;
            }
            let chunk_vecs_and_offsets: Vec<(Vec<f32>, (usize, usize))> = outputs[job_idx]
                .take()
                .unwrap_or_default()
                .into_iter()
                .zip(job.offsets.iter().copied())
                .filter(|(vector, _)| !vector.is_empty())
                .collect();
            let chunk_vecs: Vec<Vec<f32>> = chunk_vecs_and_offsets
                .iter()
                .map(|(vector, _)| vector.clone())
                .collect();
            let Some(obj) = sources[job.source_idx].as_object_mut() else {
                continue;
            };
            // Pooled vector for `target`: single chunk is stored as-is (no
            // re-normalization, matching pre-chunking behavior); multiple
            // chunks are L2-normalized, mean-pooled, then re-normalized. This
            // keeps `target` back-compatible for plain kNN and for callers
            // that read the companion vector directly.
            let pooled = match chunk_vecs.len() {
                0 => continue,
                1 => chunk_vecs[0].clone(),
                _ => mean_pool_normalize(&chunk_vecs),
            };
            // #1940: a 384-d `Vec<Value>` is tens of KB of retained heap per
            // record (two memtables plus any later stored-source parse) for
            // ~1.5 KB of f32s. Keep the packed string in the source; readers
            // unpack it, and response paths expand it back to a number array.
            match xerj_common::packed_f32::pack_f32_vector(&pooled) {
                Some(packed) => {
                    obj.insert(job.target.clone(), Value::String(packed));
                }
                None => {
                    let arr: Vec<Value> =
                        pooled.into_iter().map(|f| Value::from(f as f64)).collect();
                    obj.insert(job.target.clone(), Value::Array(arr));
                }
            }
            // Compact, durable passage provenance. Text is deliberately NOT
            // duplicated: the response reconstructs only the winning page
            // slice from the original semantic field using these UTF-8 byte
            // offsets. The field name is stored once per document/target and
            // ordinals are implicit in array order.
            let offsets_json: Vec<Value> = chunk_vecs_and_offsets
                .iter()
                .map(|(_, (start, end))| {
                    Value::Array(vec![Value::from(*start as u64), Value::from(*end as u64)])
                })
                .collect();
            obj.insert(
                passage_metadata_field(&job.target),
                serde_json::json!({
                    "field": job.field,
                    "chunks": offsets_json,
                }),
            );
            // Per-chunk passage vectors — persisted ONLY when the document
            // actually spans more than one chunk, under `<target>_chunks` as an
            // array of vectors. Semantic search prefers these and scores by the
            // best-matching passage (max-sim) instead of the blurred pooled
            // average. Single-chunk docs store nothing extra, so their `_source`
            // and single-vector scoring are byte-identical to before.
            if chunk_vecs.len() > 1 {
                let chunks_json: Vec<Value> = chunk_vecs
                    .iter()
                    .map(|cv| match xerj_common::packed_f32::pack_f32_vector(cv) {
                        Some(packed) => Value::String(packed),
                        None => Value::Array(cv.iter().map(|f| Value::from(*f as f64)).collect()),
                    })
                    .collect();
                obj.insert(format!("{}_chunks", job.target), Value::Array(chunks_json));
            }
        }

        // Caller-supplied vectors skip the job loop above and would otherwise
        // stay as number arrays — the same retained-heap shape. Pack those
        // too, field by field, after every generated vector is in place.
        for source in sources.iter_mut() {
            let Some(obj) = source.as_object_mut() else {
                continue;
            };
            for (_, target, _) in &specs {
                if let Some(value) = obj.get_mut(target) {
                    xerj_common::packed_f32::compact_vector_value(value);
                }
                let chunks_name = format!("{target}_chunks");
                if let Some(value) = obj.get_mut(&chunks_name) {
                    xerj_common::packed_f32::compact_vector_value(value);
                }
            }
        }

        sources
            .into_iter()
            .enumerate()
            .map(|(idx, source)| match failures[idx].take() {
                Some(error) if admission_rejections[idx] => Err(EngineError::Common(
                    xerj_common::XerjError::resource_exhausted(format!(
                        "semantic_text batch embed rejected before tokenization: {error}"
                    )),
                )),
                Some(error) if width_mismatches[idx] => {
                    Err(EngineError::Common(semantic_width_mismatch_error(&error)))
                }
                Some(error) => Err(EngineError::Common(embed_backend_error(
                    anyhow::anyhow!(error),
                    "semantic_text batch embed failed",
                ))),
                None => Ok(source),
            })
            .collect()
    }

    pub(crate) async fn semantic_vector_fields(&self) -> std::collections::HashSet<String> {
        let schema = self.schema.read().await;
        crate::memtable::semantic_derived_vector_fields(&schema.schema)
    }

    /// Hybrid (multi-query + fusion) executor. Recursively runs each
    /// sub-query as its own search and combines the result lists via
    /// the chosen fusion strategy (RRF / Linear / Learned). Pagination
    /// is applied to the fused list, not to the sub-lists — each
    /// sub-list is fetched at `top_k = max(50, request.size + request.from)`
    /// to give the fusion enough material to produce stable top-N.
    ///
    /// Aggregations are NOT supported in hybrid queries today (the
    /// natural semantics — agg over the fused result set vs over each
    /// sub-query — is application-specific). If the request asks for
    /// aggs we reject it with an explicit 400 rather than silently
    /// dropping them; a bounded aggregation over the fused top-N would
    /// present under-counted `doc_count`s as if they were exact. Run
    /// the aggregation as a separate, non-hybrid search instead. The
    /// v0.7-P1 scope is hits + scores only.
    pub async fn run_hybrid(
        &self,
        request: &SearchRequest,
        sub_queries: Vec<xerj_query::ast::WeightedQuery>,
        fusion: xerj_query::ast::FusionStrategy,
    ) -> Result<SearchResult> {
        let deadline = std::time::Instant::now()
            + std::time::Duration::from_millis(request.timeout_ms.unwrap_or(30_000));
        self.run_hybrid_with_deadline(request, deadline, sub_queries, fusion)
            .await
    }

    async fn run_hybrid_with_deadline(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        sub_queries: Vec<xerj_query::ast::WeightedQuery>,
        fusion: xerj_query::ast::FusionStrategy,
    ) -> Result<SearchResult> {
        let started = std::time::Instant::now();

        // Aggregations over a fused (RRF/Linear/Learned) result set have
        // no well-defined exact semantics — a bounded agg over the fused
        // top-N would silently under-count. Fail loud (400) instead of
        // returning `aggs: null`, mirroring `result_window_too_large`.
        if request.aggs.is_some() {
            return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                "aggregations are not supported with hybrid/fusion queries; \
                 run the aggregation as a separate non-hybrid search",
            )));
        }

        // Each sub-list needs to be deeper than the final top-N so
        // fusion has enough material for stable rank-merge. ES uses
        // 50 by default; we mirror that, growing if the caller asked
        // for a deeper page.
        let per_query_topk = request.size.saturating_add(request.from).max(50);

        // Run the legs CONCURRENTLY, not in parallel (#939). A search runs
        // inside `block_in_place(block_on(..))`, so these futures share one
        // thread and only overlap where a leg awaits. The await worth
        // overlapping is the query embedding of a `semantic` leg under an
        // active backend: a BERT forward pass on the blocking pool (~14 ms) or
        // a proxy round trip, during which this thread used to sit idle and
        // the lexical leg had not started. So legs that embed are POLLED
        // FIRST — they park on the embedder, the lexical legs run underneath
        // them — while results are still consumed in the caller's order, which
        // is what fusion weights and the timeout rule below are defined over.
        // Under the default lexical embedder the embedding is synchronous and
        // there is nothing to overlap; this costs nothing there.
        //
        // Spawning each leg as its own task would buy real parallelism, but
        // needs an `Arc<Self>` this `&self` chain does not have, next to the
        // `block_in_place` hand-off that produced #751. Not for ~10 ms.
        let mut sub_results: Vec<(Vec<Hit>, f32)> = Vec::with_capacity(sub_queries.len());
        let mut sub_savings: Vec<PayloadSavings> = Vec::new();
        let mut any_timed_out = false;
        // #569: whether the fused total is a lower bound rather than exact.
        // Each sub-query is fetched at `per_query_topk`; if any sub-list hit that
        // cap (or reported its own count as capped), the fused union under-counts
        // the true match set, so the reported relation must be Gte, not a false
        // Eq. Stays false only when every sub-list was fully retrieved.
        let mut fused_count_capped = false;
        let sub_requests: Vec<SearchRequest> = sub_queries
            .iter()
            .map(|wq| SearchRequest {
                query: wq.query.clone(),
                from: 0,
                size: per_query_topk,
                sort: Vec::new(),
                search_after: None,
                source: request.source.clone(),
                aggs: None,
                track_total_hits: request.track_total_hits,
                explain: false,
                highlight: None,
                collapse: None,
                rescore: Vec::new(),
                min_score: None,
                timeout_ms: request.timeout_ms,
                script_fields: None,
                fields: Vec::new(),
                profile: false,
                leaf_ts_field: None,
                savings: request.savings,
                ids_only: false,
            })
            .collect();
        let mut leg_outcomes: Vec<Option<Result<SearchResult>>> =
            sub_requests.iter().map(|_| None).collect();
        if std::time::Instant::now() >= deadline {
            any_timed_out = true;
        } else {
            let mut poll_order: Vec<usize> = (0..sub_requests.len()).collect();
            // Stable: legs that embed keep their relative order, then the rest.
            poll_order.sort_by_key(|&leg| peel_semantic_query(&sub_requests[leg].query).is_none());
            // Box::pin to break the type-recursion (search_inner ↔
            // run_hybrid both async fn).
            let legs = poll_order
                .iter()
                .map(|&leg| Box::pin(self.search_inner(&sub_requests[leg], deadline)));
            for (&leg, outcome) in poll_order
                .iter()
                .zip(futures_util::future::join_all(legs).await)
            {
                leg_outcomes[leg] = Some(outcome);
            }
        }
        // Consume in the CALLER'S order with the sequential loop's exact
        // rules: the first failing leg in that order is the error returned,
        // and a leg that timed out ends the list — the legs after it are
        // dropped, as they were when they had simply never been started.
        for (wq, outcome) in sub_queries.into_iter().zip(leg_outcomes) {
            let Some(outcome) = outcome else {
                break;
            };
            let sub_result = outcome?;
            any_timed_out |= sub_result.timed_out;
            // #569/#594: this sub-list under-counts the fused total only when the
            // leg genuinely has MORE than `per_query_topk` matches — signalled by
            // the leg's own exact total exceeding the cap, or its own count
            // already being a lower bound (Gte). `total.value` is the load-bearing
            // capping signal (`total.value >= hits.len()` always). A leg with
            // EXACTLY `per_query_topk` matches reports `total.value ==
            // per_query_topk` (Eq) → NOT capped → the fused total stays Eq at the
            // boundary (ES parity), where the old `hits.len() >= per_query_topk`
            // tripped a needless Gte because a full page cannot distinguish
            // "exactly N" from ">N". The `hits.len() > per_query_topk` arm is a
            // cheap defensive guard: it never fires for `size == per_query_topk`
            // (a leg cannot return more than it was asked for), but it catches any
            // future leg that over-returns hits without a matching total.
            if sub_result.hits.len() > per_query_topk
                || sub_result.total.value > per_query_topk as u64
                || sub_result.total.relation == TotalHitsRelation::Gte
            {
                fused_count_capped = true;
            }
            // Fusion de-duplicates documents across sub-queries, so the
            // per-hit records are merged by document id below — a document
            // retrieved by both the lexical and the vector leg saved its
            // bytes ONCE, and must be counted once.
            if let Some(s) = sub_result.savings {
                sub_savings.push(s);
            }
            sub_results.push((sub_result.hits, wq.weight));
            if any_timed_out {
                break;
            }
        }

        // Apply fusion. A tied fused score is broken by arrival order, the
        // same `seq_no ASC, _id ASC` every other score-ranked page uses
        // (#270/#940) — resolved through the version map once per distinct
        // fused document, which is at most `legs × per_query_topk` lookups.
        let seq_no_of = |id: &str| self.lookup_seq_no(id).unwrap_or(u64::MAX);
        let fused = match fusion {
            xerj_query::ast::FusionStrategy::Rrf { k } => fuse_rrf(&sub_results, k, &seq_no_of),
            xerj_query::ast::FusionStrategy::Linear => fuse_linear(&sub_results, &seq_no_of),
            // Defense in depth: the parser already rejects `fusion: learned`
            // with a 400 (see xerj-query parser.rs::parse_hybrid), so this
            // arm is unreachable via the ES API. Fail loud rather than
            // silently substituting RRF, in case a future non-parser caller
            // constructs the AST directly.
            xerj_query::ast::FusionStrategy::Learned => {
                return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                    "hybrid fusion learned is not yet supported; use rrf or linear",
                )));
            }
        };

        // Apply pagination on the fused list.
        let total_value = fused.len() as u64;
        let page: Vec<Hit> = fused
            .into_iter()
            .skip(request.from)
            .take(request.size)
            .collect();

        let took_ms = started.elapsed().as_millis() as u64;
        Ok(SearchResult {
            hits: page,
            total: TotalHits {
                value: total_value,
                relation: if any_timed_out || fused_count_capped {
                    TotalHitsRelation::Gte
                } else {
                    TotalHitsRelation::Eq
                },
            },
            took_ms,
            aggs: None,
            timed_out: any_timed_out,
            profile: None,
            max_score: None,
            script_failure: None,
            savings: merge_sub_savings(sub_savings),
        })
    }

    /// #825: execute one `Knn` clause standalone and return a replacement
    /// sub-tree that pins its top-k results as per-document constant scores:
    /// `bool.should = [Constant{score, Ids{[id]}}, …]` (or `MatchNone` when
    /// the leg returns nothing). The generic matcher/scorer has no `Knn`
    /// arm, so this is what lets a `knn` clause inside a compound `bool`
    /// contribute at all — and it reproduces ES's hybrid contract exactly:
    /// the knn side contributes the GLOBAL top-k neighbours, a document in
    /// both halves scores the SUM (Bool sums clause scores), and every
    /// request feature (aggs over the union, sort, collapse, highlight,
    /// rescore, min_score) applies through the normal path afterwards.
    ///
    /// The leg runs on the SAME executors as the single-clause peel in
    /// `search_inner`: HNSW only for the plain case (exact-rescored scores,
    /// but `aggs` on the OUTER request forces exact brute force — the rc.6
    /// rule that ANN approximation must not leak into agg buckets), brute
    /// force otherwise. Boost and the raw-similarity cutoff are applied by
    /// those executors before the scores reach the pinned constants.
    async fn pin_knn_clause(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        knn: &QueryNode,
    ) -> Result<QueryNode> {
        if let QueryNode::Knn {
            field,
            vector,
            k,
            num_candidates,
            filter,
            boost,
            similarity: min_similarity,
        } = knn
        {
            let similarity = {
                let schema = self.schema.read().await;
                lookup_vector_similarity(&schema.schema, field)
            };
            // The leg needs the FULL top-k regardless of the caller's page:
            // ES unions the global k nearest into the candidate set even when
            // `size` is smaller, so pagination happens after the merge.
            let sub_request = SearchRequest {
                query: knn.clone(),
                from: 0,
                size: *k,
                sort: Vec::new(),
                search_after: None,
                aggs: None,
                explain: false,
                source: request.source.clone(),
                timeout_ms: request.timeout_ms,
                highlight: None,
                track_total_hits: request.track_total_hits,
                script_fields: None,
                fields: Vec::new(),
                profile: false,
                collapse: None,
                rescore: Vec::new(),
                min_score: None,
                leaf_ts_field: None,
                savings: request.savings,
                ids_only: false,
            };
            let plain = filter.is_none()
                && boost.is_none()
                && min_similarity.is_none()
                && request.aggs.is_none();
            let hnsw = if plain {
                Box::pin(self.run_knn_hnsw(
                    &sub_request,
                    deadline,
                    field,
                    vector,
                    *k,
                    *num_candidates,
                    &similarity,
                ))
                .await
            } else {
                None
            };
            let leg = match hnsw {
                Some(result) => result,
                None => {
                    Box::pin(self.run_knn_brute_force_with_deadline(
                        &sub_request,
                        deadline,
                        field,
                        vector,
                        *k,
                        filter.clone(),
                        &similarity,
                        *boost,
                        *min_similarity,
                    ))
                    .await?
                }
            };
            // Same execution-truth check as the single-knn and multi-knn
            // arms (#498): an empty leg on an unanswerable field must fail
            // loud, not degrade to lexical-only.
            if leg.hits.is_empty() && !leg.timed_out {
                self.reject_unanswerable_knn_field(field).await?;
            }
            let pinned: Vec<QueryNode> = leg
                .hits
                .iter()
                .map(|hit| QueryNode::Constant {
                    score: hit.score,
                    query: Box::new(QueryNode::Ids {
                        values: vec![hit.id.clone()],
                    }),
                })
                .collect();
            Ok(if pinned.is_empty() {
                QueryNode::MatchNone
            } else {
                // The `filter` is a REDUNDANT accelerator, not semantics: it
                // holds exactly the union of the `should` clauses' ids, so
                // `filter ∧ (≥1 should)` and `(≥1 should)` have the same match
                // set, and `filter` contributes nothing to `_score` (only
                // must/should are summed — `BooleanClause.isScoring()`).
                // What it buys is the shape of the DOC-SCAN cost. The scan
                // evaluates must/must_not/filter BEFORE should, so a document
                // outside the top-k is now rejected by ONE `_id` lookup plus a
                // memcmp sweep, instead of recursing into all k
                // `Constant{Ids}` clauses and re-reading `_id` from the source
                // map k times. Measured on a 100 k-doc index, together with
                // the `should` short-circuit in `doc_matches_query_typed`
                // (see the PR's measurement table): hybrid k=1000
                // 2309 ms → 385 ms, k=10000 24 437 ms → 5 071 ms.
                // `minimum_should_match: 1` is written out rather than left
                // implicit: with a non-empty `filter` the default would fall
                // to 0 ("filter alone decides"), which is the same match set
                // here but is NOT the same statement, and any other reader of
                // this tree should see the disjunction that was meant.
                QueryNode::Bool {
                    must: Vec::new(),
                    should: pinned,
                    filter: vec![QueryNode::Ids {
                        values: leg.hits.iter().map(|hit| hit.id.clone()).collect(),
                    }],
                    must_not: Vec::new(),
                    minimum_should_match: Some(MinShouldMatch::Fixed(1)),
                }
            })
        } else {
            // Caller contract: `knn` is a `QueryNode::Knn` (see
            // `compound_bool_direct_knn`). Anything else passes through
            // untouched rather than panicking.
            Ok(knn.clone())
        }
    }

    /// `field` is the full dotted path as the ES query provides it
    /// (e.g. `nested.vector`). The element inside the nested array is
    /// the sub-field after the path prefix (`vector`).
    ///
    /// Parents whose nested array is empty or whose elements have a
    /// vector of the wrong dim are skipped. `extra_filter` is applied
    /// at parent-doc granularity.
    #[allow(clippy::too_many_arguments)] // ES nested-kNN request surface; 1:1 with query DSL
    pub async fn run_nested_knn_brute_force(
        &self,
        request: &SearchRequest,
        nested_path: &str,
        field: &str,
        query_vec: &[f32],
        k: usize,
        num_candidates: usize,
        pre_filter: Option<Box<QueryNode>>,
        post_filter: Option<Box<QueryNode>>,
        similarity: &str,
    ) -> Result<SearchResult> {
        let deadline = std::time::Instant::now()
            + std::time::Duration::from_millis(request.timeout_ms.unwrap_or(30_000));
        self.run_nested_knn_brute_force_with_deadline(
            request,
            deadline,
            nested_path,
            field,
            query_vec,
            k,
            num_candidates,
            pre_filter,
            post_filter,
            similarity,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)] // deadline plus ES nested-kNN request surface
    async fn run_nested_knn_brute_force_with_deadline(
        &self,
        request: &SearchRequest,
        deadline: std::time::Instant,
        nested_path: &str,
        field: &str,
        query_vec: &[f32],
        k: usize,
        num_candidates: usize,
        pre_filter: Option<Box<QueryNode>>,
        post_filter: Option<Box<QueryNode>>,
        similarity: &str,
    ) -> Result<SearchResult> {
        let started = std::time::Instant::now();
        let mut timed_out = false;
        // #423: evaluate the nested-kNN pre/post filters through the SAME
        // schema-aware matcher the rest of search uses (`search_inner` runs its
        // filter through `doc_matches_query_typed(.., &dmq_schema)`). The
        // schemaless `doc_matches_query` has no field types, so on a
        // `keyword`/`text` field it folds case and OVER-MATCHES — a
        // `prefix`/`match`/`fuzzy` pre/post filter kept parent docs a plain
        // (non-knn) search would reject. Nested kNN always takes this
        // brute-force path (there is no nested HNSW graph). Owned clone; the
        // lock is released.
        let dmq_schema = self.schema().await;
        // The sub-field name inside each nested element.
        let subfield = field
            .strip_prefix(&format!("{}.", nested_path))
            .unwrap_or(field)
            .to_string();

        // ── Collect candidate parent docs ─────────────────────────────
        // #1220 — the same capture discipline the top-level exact scan now
        // applies: memtable capture + segment snapshot inside a validated
        // writer-free instant, and every version-map read below scoped to
        // the captured segment ids (see [`CapturedEntryVerdict`]). The
        // pre-fix inline predicate read the LIVE map, so a delete or update
        // publishing after the capture silently dropped captured candidates.
        let (capture_generation, _, capture_poisoned) = self.collection_publication.state();
        if capture_poisoned {
            return Err(collection_publication_interrupted());
        }
        let mut candidates: Vec<(String, Value)> = Vec::new();
        {
            let mem = &*self.memtable;
            candidates.extend(mem.all_docs_with_sources());
        }
        let snap = self.store.snapshot();
        {
            let (generation, in_flight, poisoned) = self.collection_publication.state();
            if poisoned {
                return Err(collection_publication_interrupted());
            }
            if generation != capture_generation || in_flight != 0 {
                return Err(collection_capture_crossed());
            }
            self.collection_publication.note_capture_validated();
        }
        let captured_segment_ids: std::collections::HashSet<&str> =
            snap.segments.iter().map(|meta| meta.id.as_str()).collect();
        let mut seen: HashSet<String> = candidates.iter().map(|(id, _)| id.clone()).collect();
        'segments: for meta in snap.segments.iter() {
            if std::time::Instant::now() >= deadline {
                timed_out = true;
                break;
            }
            // Cache-backed: see comment on the matching loop in
            // run_knn_brute_force.
            let docs_arc = match tokio::time::timeout_at(
                tokio::time::Instant::from_std(deadline),
                self.stored_values_for_async(&meta.id),
            )
            .await
            {
                Ok(Some(a)) => a,
                Ok(None) => continue,
                Err(_) => {
                    timed_out = true;
                    break;
                }
            };
            if std::time::Instant::now() >= deadline {
                timed_out = true;
                break;
            }
            // Cache + serde_json under the hood (see stored_values_for).
            for (position, doc) in docs_arc.iter().enumerate() {
                if position & 127 == 0 && self.exact_scan_checkpoint(position, deadline).await {
                    timed_out = true;
                    break 'segments;
                }
                let id = match doc.get("_id").and_then(Value::as_str) {
                    Some(s) => s.to_string(),
                    None => continue,
                };
                // #1220: the SAME capture-scoped admission the top-level
                // exact scan applies (never a divergent copy of the
                // predicate): a later world's entry cannot retire a
                // captured parent, a captured-world tombstone or superseding
                // copy still drops it.
                let doc_seq = doc.get("_seq_no").and_then(Value::as_u64);
                if !self.admit_exact_scan_candidate(
                    &mut seen,
                    &id,
                    doc_seq,
                    &meta.id,
                    &captured_segment_ids,
                ) {
                    continue;
                }
                // Reassembled segment docs have shape
                //   { "_id":..., "_seq_no":..., "_source": {...} }
                // but the scoring loop's `get_field_value(src, nested_path)`
                // expects fields at the top level (memtable shape). Without
                // this unwrap every flushed parent's nested array resolved
                // to None and segment-resident docs scored zero hits — the
                // exact silent-empty class the top-level kNN collector
                // already guards against (see run_knn_brute_force).
                let src = doc.get("_source").cloned().unwrap_or_else(|| {
                    let mut d = doc.clone();
                    if let Some(obj) = d.as_object_mut() {
                        obj.remove("_id");
                    }
                    d
                });
                candidates.push((id, src));
            }
        }

        // ── Score each parent by best-matching nested element ─────────
        // Pre-filter is applied before scoring (alias filter, knn.filter).
        let mut scored: Vec<(String, f32, Value)> = Vec::new();
        let mut nested_position = 0usize;
        'candidates: for (position, (id, src)) in candidates.into_iter().enumerate() {
            if position & 127 == 0 && self.exact_scan_checkpoint(position, deadline).await {
                timed_out = true;
                break;
            }
            if let Some(ref f) = pre_filter {
                let mut src_with_id = src.clone();
                if let Some(obj) = src_with_id.as_object_mut() {
                    obj.insert("_id".to_string(), Value::String(id.clone()));
                }
                if !doc_matches_query_typed(f, &src_with_id, &dmq_schema) {
                    continue;
                }
            }
            let nested_arr = match get_field_value(&src, nested_path) {
                Some(Value::Array(a)) => a,
                Some(single) => vec![single],
                None => continue,
            };
            let mut best: Option<f32> = None;
            for elem in &nested_arr {
                nested_position = nested_position.saturating_add(1);
                if nested_position & 127 == 0
                    && self.exact_scan_checkpoint(nested_position, deadline).await
                {
                    timed_out = true;
                    break 'candidates;
                }
                let vec_val = match elem.get(&subfield) {
                    Some(v) => v,
                    None => continue,
                };
                let doc_vec: Vec<f32> = match vec_val {
                    Value::Array(arr) => arr
                        .iter()
                        .filter_map(|v| v.as_f64().map(|f| f as f32))
                        .collect(),
                    Value::String(text) => {
                        xerj_common::packed_f32::unpack_f32_vector(text).unwrap_or_default()
                    }
                    _ => continue,
                };
                if doc_vec.len() != query_vec.len() {
                    continue;
                }
                let s = compute_vector_similarity(similarity, query_vec, &doc_vec);
                best = Some(match best {
                    Some(b) => b.max(s),
                    None => s,
                });
            }
            if let Some(score) = best {
                scored.push((id, score, src));
            }
        }

        // Truncate to num_candidates BEFORE post-filtering — this is
        // what makes "post-filter with num_candidates:1" return 0 when
        // the single top candidate doesn't match the outer filter.
        scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        scored.truncate(num_candidates);

        // Apply post-filter (sibling bool.must clauses).
        if let Some(ref f) = post_filter {
            scored.retain(|(id, _, src)| {
                let mut src_with_id = src.clone();
                if let Some(obj) = src_with_id.as_object_mut() {
                    obj.insert("_id".to_string(), Value::String(id.clone()));
                }
                doc_matches_query_typed(f, &src_with_id, &dmq_schema)
            });
        }

        let total_value = scored.len() as u64;
        let k_final = k.max(request.size).max(1);
        scored.truncate(k_final);

        let hits: Vec<Hit> = scored
            .into_iter()
            .map(|(id, score, source)| {
                // Same read the final page's `_source` is served from
                // (post-truncate, post-filter) — not a later pass (#440).
                let (seq_no, version) = self
                    .store
                    .version_map
                    .get(&id)
                    .map(|ver| self.hit_seq_version(&id, &ver))
                    .unwrap_or((None, None));
                Hit {
                    id,
                    score,
                    source,
                    seq_no,
                    version,
                    sort: Vec::new(),
                    explain: None,
                    highlight: None,
                    matched_queries: Vec::new(),
                    passage: None,
                }
            })
            .collect();

        Ok(SearchResult {
            hits,
            total: TotalHits {
                value: total_value,
                relation: if timed_out {
                    TotalHitsRelation::Gte
                } else {
                    TotalHitsRelation::Eq
                },
            },
            took_ms: started.elapsed().as_millis() as u64,
            aggs: None,
            timed_out,
            profile: None,
            max_score: None,
            script_failure: None,
            savings: None,
        })
    }

    /// Current max seq_no across this index's storage. Used to snapshot
    /// visibility at `open_point_in_time` time — docs with `_seq_no`
    /// greater than the snapshot are considered unborn relative to
    /// the PIT and filtered out at search time.
    pub fn current_seq_no(&self) -> u64 {
        self.store.current_seq_no()
    }

    // ── HNSW persistence ─────────────────────────────────────────────────
    //
    // Pre-v0.6.2 the HNSW graph lived only in memory; on every restart
    // we re-inserted every vector by walking the WAL — O(N log N)
    // startup cost on million-vector indices. v0.6.2 ships save/load
    // for the graph (xerj-vector::HnswIndex::save_to/load_from) and
    // a tiny sidecar for the doc_id ↔ node_id map.
    //
    // Layout under `<index_data_dir>/hnsw/`:
    //   graph.bin    HNSW graph (xerj-vector format, CRC32C-validated)
    //   ids.json     { next_id, map: { "doc_id": node_id, ... } }
    //
    // Caller invariants:
    //   * `save_hnsw_to_disk` writes both files atomically (via .tmp +
    //     rename). A crash leaves either both old files or no files;
    //     in the latter case startup falls back to WAL replay.
    //   * `load_hnsw_from_disk` is best-effort. Any error returns Ok(())
    //     and leaves `self.hnsw = None`; the next vector ingest re-
    //     creates the graph.

    fn hnsw_dir(&self) -> std::path::PathBuf {
        self.data_dir.join("hnsw")
    }

    fn hnsw_graph_path(&self) -> std::path::PathBuf {
        self.hnsw_dir().join("graph.bin")
    }

    fn hnsw_ids_path(&self) -> std::path::PathBuf {
        self.hnsw_dir().join("ids.json")
    }

    /// Persist the in-memory HNSW graph + id-map to disk. No-op when
    /// `self.hnsw` is None (no vector field has been indexed yet).
    /// Called on flush completion and graceful shutdown.
    pub async fn save_hnsw_to_disk(&self) -> Result<()> {
        let publication_generation_before =
            self.hnsw_publication_generation.load(Ordering::Acquire);
        // This stamp brackets graph, identity-map, and passage-guard
        // serialization. A write publishes its WAL before graph mutation, so
        // any advance during this window means the captured pieces are not one
        // current generation and must reopen stale.
        let seq_before = self.store.current_seq_no();
        let hnsw_guard = self.hnsw.read().await;
        let hnsw = match &*hnsw_guard {
            Some(h) => h,
            None => return Ok(()),
        };
        let dir = self.hnsw_dir();
        if let Err(e) = std::fs::create_dir_all(&dir) {
            warn!(error = %e, "HNSW save: cannot create dir");
            return Ok(());
        }
        if let Err(e) = hnsw.save_to(&self.hnsw_graph_path()) {
            warn!(error = %e, "HNSW save: graph serialization failed");
            return Ok(());
        }
        // Save the id map alongside. JSON is fine — the map is at most
        // a few hundred MB even for the largest indices and writes
        // infrequently (once per flush). The shape is fixed so a v0.7
        // codec swap (e.g. to a binary keyed by doc_id length) won't
        // break loaders that read both fields.
        //
        // Integrity stamp (2026-07): `field` records the graph's pinned
        // field identity and `seq_no` the store's WAL position at save
        // time. At load, a fielded snapshot whose stamp differs from the
        // replayed `current_seq_no()` is flush-time stale relative to a WAL
        // tail (which may contain updates of already-graphed docs that the
        // coverage guard cannot detect) → the HNSW query path is disabled.
        // `stale` persists an already-detected staleness so a later flush
        // of the still-stale graph cannot re-stamp it as fresh. Loaders are
        // duck-typed in both directions: old binaries ignore the extra
        // keys, and this loader treats a missing `field` as legacy.
        let id_map = self.hnsw_id_map.read().await;
        let hnsw_field = self.hnsw_field.read().unwrap().clone();
        let mut passage_chunk_fields: Vec<String> = self
            .passage_chunk_fields
            .read()
            .unwrap()
            .iter()
            .cloned()
            .collect();
        passage_chunk_fields.sort();
        #[cfg(test)]
        if self
            .test_hnsw_save_passage_snapshot_pause
            .load(Ordering::Acquire)
        {
            self.test_hnsw_save_passage_snapshot_ready
                .store(true, Ordering::Release);
            while self
                .test_hnsw_save_passage_snapshot_pause
                .load(Ordering::Acquire)
            {
                tokio::task::yield_now().await;
            }
        }
        let seq_after = self.store.current_seq_no();
        let publication_generation_after = self.hnsw_publication_generation.load(Ordering::Acquire);
        let publication_in_flight = self.hnsw_publications_in_flight.load(Ordering::Acquire);
        let snapshot_stale = self.hnsw_stale.load(Ordering::Acquire)
            || seq_after != seq_before
            || publication_in_flight != 0
            || publication_generation_before != publication_generation_after;
        let snapshot = serde_json::json!({
            "next_id": self.hnsw_next_id.load(Ordering::Relaxed),
            "map": *id_map,
            "field": hnsw_field,
            "seq_no": seq_before,
            "stale": snapshot_stale,
            "passage_guard_version": 1,
            "passage_chunk_fields": passage_chunk_fields,
        });
        // Durable atomic publish (RC4 W2 item 19 — same treatment as
        // graph.bin in HnswIndex::save_to): fsync file + rename + fsync
        // parent dir, so power loss can't leave a torn/evaporating
        // ids.json. Write order is graph.bin THEN ids.json: a crash
        // between the two renames leaves new-graph/old-ids, whose seq_no
        // stamp then mismatches the replayed WAL position → the loader
        // marks the pair stale and the rebuild path re-derives it (never
        // serves a mixed pair).
        if let Err(e) = xerj_common::fsio::write_file_durable(
            &self.hnsw_ids_path(),
            &serde_json::to_vec(&snapshot).unwrap_or_default(),
        ) {
            warn!(error = %e, "HNSW save: ids.json write failed");
            return Ok(());
        }
        debug!(
            graph = %self.hnsw_graph_path().display(),
            nodes = hnsw.len(),
            "HNSW persisted"
        );
        Ok(())
    }

    /// Try to load a previously-persisted HNSW graph + id-map.
    /// Returns `Ok(true)` on a successful load (graph and ids both
    /// present and self-consistent), `Ok(false)` if no snapshot
    /// exists or load failed (caller falls back to WAL replay).
    pub async fn load_hnsw_from_disk(&self) -> Result<bool> {
        let dv_fields = {
            let schema = self.schema.read().await;
            collect_dense_vector_fields(&schema.schema)
        };
        let loaded = match load_hnsw_artifacts_sync(&self.hnsw_dir(), &|f: &str| {
            dv_fields.iter().any(|df| df == f)
        }) {
            Some(l) => l,
            None => return Ok(false),
        };
        let mut id_map = self.hnsw_id_map.write().await;
        let mut id_rev = self.hnsw_id_rev.write().await;
        *id_map = loaded.id_map;
        *id_rev = loaded.id_rev;
        // Item 8: re-seed the coverage-gate denominator from the reloaded
        // graph (every graphed doc is a vector doc). Staleness is handled
        // separately by `hnsw_stale`.
        self.vector_doc_count
            .store(id_map.len() as u64, Ordering::Relaxed);
        drop(id_map);
        drop(id_rev);
        self.hnsw_next_id.store(loaded.next_id, Ordering::Relaxed);
        // Same freshness-stamp handling as Index::open (the loader gate
        // guarantees `field` is Some).
        let stale = loaded.stale
            || loaded
                .seq_no
                .is_none_or(|stamp| stamp != self.store.current_seq_no());
        *self.hnsw_field.write().unwrap() = loaded.field;
        let passage_scored_fields = {
            let schema = self.schema.read().await;
            passage_scored_vector_fields(&schema.schema)
        };
        {
            let mut passage_fields = self.passage_chunk_fields.write().unwrap();
            match loaded.passage_chunk_fields {
                Some(fields) => passage_fields.extend(fields),
                None => passage_fields.extend(passage_scored_fields),
            }
        }
        self.hnsw_stale
            .store(stale, std::sync::atomic::Ordering::Release);
        let nodes = loaded.graph.len();
        *self.hnsw.write().await = Some(loaded.graph);
        info!(
            nodes,
            stale, "HNSW reloaded from disk — skipping WAL replay rebuild"
        );
        Ok(true)
    }

    /// Re-validate every section's CRC32C across every segment in
    /// this index's current snapshot. Returns a structured report
    /// with `corrupt_sections > 0` indicating on-disk bit rot.
    ///
    /// Whole-file CRC is checked once at segment open; per-section
    /// CRC is normally skipped on the search hot path for perf
    /// (see `xerj_storage::SegmentReader::section` docs). This
    /// method goes back over every section to detect rot at rest.
    /// Cost is O(total stored bytes) — runs in seconds for typical
    /// indexes, minutes for hundreds of GB. Designed for periodic
    /// scheduling, not per-request use.
    pub fn fsck_segments(&self) -> xerj_storage::FsckReport {
        self.store.fsck_segments()
    }

    /// Track a request_cache-eligible search. Increments hit_count when
    /// the same query hash has been seen before, miss_count on first
    /// sight. Caller decides whether the search is cache-eligible
    /// (request_cache=true + size:0 + no aggs that mutate the result).
    pub fn track_request_cache(&self, body_hash: u64) {
        // RwLock here is tokio's async one; block_in_place isn't available
        // from a non-async caller. Use std::sync::Mutex semantics via
        // try_write spin since this is a small hot path — the dataset is
        // bounded so contention is negligible.
        let mut seen = loop {
            match self.request_cache_seen.try_write() {
                Ok(g) => break g,
                Err(_) => std::thread::yield_now(),
            }
        };
        if seen.record(body_hash) {
            self.request_cache_misses.fetch_add(1, Ordering::Relaxed);
        } else {
            self.request_cache_hits.fetch_add(1, Ordering::Relaxed);
        }
    }

    pub fn request_cache_hit_count(&self) -> u64 {
        self.request_cache_hits.load(Ordering::Relaxed)
    }

    pub fn request_cache_miss_count(&self) -> u64 {
        self.request_cache_misses.load(Ordering::Relaxed)
    }

    /// Cumulative internal query-result cache hits/misses for this index
    /// (RC4-W4 item 4). Summed across indices by [`Engine::query_cache_totals`]
    /// and surfaced on `/v1/metrics`.
    pub fn query_cache_hit_count(&self) -> u64 {
        self.query_cache_hits.load(Ordering::Relaxed)
    }

    pub fn query_cache_miss_count(&self) -> u64 {
        self.query_cache_misses.load(Ordering::Relaxed)
    }

    /// The last-ranking `(score, seq_no, _id)` page key held by `hits`, under
    /// the exact comparator the final page sort uses (score DESC, `seq_no` ASC,
    /// `_id` ASC).
    ///
    /// #191 — the bounded collector's admission bound has to be this WHOLE key,
    /// not just the score.  Documents that tie on score are separated by
    /// `seq_no`, and the collection walk visits segments in snapshot order and
    /// documents in stored-layout order — neither is `seq_no`-ascending — so a
    /// score-only bound silently rejected tied documents that outrank the kept
    /// set, and a `size:5` page stopped agreeing with a `size:1000` one.
    ///
    /// The score minimum is found first with a lookup-free scan; the `seq_no`
    /// (a `VersionMap` hash lookup) is resolved only for the hits that actually
    /// tie that minimum, so the usual tie-free case costs one lookup.
    fn worst_page_key(&self, hits: &[Hit]) -> Option<(f32, u64, String)> {
        let min_score = hits
            .iter()
            .map(|h| h.score)
            .fold(None, |acc: Option<f32>, s| {
                Some(match acc {
                    Some(a) if a <= s => a,
                    _ => s,
                })
            })?;
        let mut worst: Option<(f32, u64, String)> = None;
        for h in hits.iter().filter(|h| h.score == min_score) {
            let key = (
                h.score,
                self.lookup_seq_no(&h.id).unwrap_or(u64::MAX),
                h.id.clone(),
            );
            let worse = match worst.as_ref() {
                None => true,
                // Ranks LATER than the incumbent = worse: same score, then
                // larger seq_no, then larger `_id`.
                Some(w) => (key.1, &key.2) > (w.1, &w.2),
            };
            if worse {
                worst = Some(key);
            }
        }
        worst
    }

    /// Reduce `hits` to the best `cap` under the SAME comparator the final page
    /// sort uses (`score DESC, seq_no ASC, _id ASC` — `index.rs:16222-16228`),
    /// and return the surviving cap-th `(score, seq_no, _id)` page key.
    ///
    /// #191 — every bounded collector in `search` trims through here, so
    /// admission and final ordering can never drift apart: a `size:5` page is
    /// the first five of a `size:1000` one whatever order the walk visited the
    /// documents in.
    #[allow(clippy::type_complexity)]
    fn trim_page_to_cap(
        &self,
        hits: Vec<Hit>,
        cap: usize,
    ) -> (Vec<Hit>, Option<(f32, u64, String)>) {
        let mut decorated: Vec<(u64, Hit)> = hits
            .into_iter()
            .map(|h| (self.lookup_seq_no(&h.id).unwrap_or(u64::MAX), h))
            .collect();
        decorated.sort_by(|a, b| {
            b.1.score
                .partial_cmp(&a.1.score)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.0.cmp(&b.0))
                .then_with(|| a.1.id.cmp(&b.1.id))
        });
        decorated.truncate(cap);
        let worst = decorated
            .last()
            .map(|(seq, h)| (h.score, *seq, h.id.clone()));
        let kept = decorated.into_iter().map(|(_, h)| h).collect();
        (kept, worst)
    }

    /// Sort `hits` into the ONE total order every score-ranked page uses:
    /// `score DESC, seq_no ASC (arrival — ES `_doc`), _id ASC`.  Decorates
    /// with the resolved `seq_no` once, sorts, undecorates — same shape as
    /// the main page sort (a per-comparison `VersionMap` lookup was ~6% of a
    /// `term` page in the P1 profile).
    ///
    /// #270 — five post-sort re-sorts (the bool-text IDF rescore, the TF-IDF
    /// fallback, and the three `request.rescore` sorts) used to tie by `_id`
    /// ALONE, so any of them firing on a tied hit set silently reordered the
    /// page into `_id` ASC — for UUID-shaped ids exactly the "essentially
    /// random" ordering the main sort's `seq_no` tie-break replaced.  The
    /// peer engines keep ONE comparator through collection, merge and final
    /// sort (Lucene `HitQueue.java:76-82`; tantivy
    /// `collector/sort_key/sort_by_score.rs:105-109` heap entry vs `:187`
    /// final sort, same key; quickwit `quickwit-search/src/collector.rs:
    /// 1131-1156` ties by `GlobalDocAddress` in both comparators) — every
    /// score re-sort routes through here so they cannot drift again.
    fn sort_hits_page_order(&self, hits: &mut Vec<Hit>) {
        let mut decorated: Vec<(u64, Hit)> = std::mem::take(hits)
            .into_iter()
            .map(|h| (self.lookup_seq_no(&h.id).unwrap_or(u64::MAX), h))
            .collect();
        decorated.sort_by(|a, b| {
            b.1.score
                .partial_cmp(&a.1.score)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.0.cmp(&b.0))
                .then_with(|| a.1.id.cmp(&b.1.id))
        });
        *hits = decorated.into_iter().map(|(_, h)| h).collect();
    }

    /// Look up the latest `seq_no` for a document by id via the version
    /// map. Returns `None` when the doc is unknown or tombstoned.
    ///
    /// The internal WAL counter starts at 1 so the first WAL op has seq=1,
    /// but ES semantics number seq_no from 0 per shard. We subtract 1 to
    /// match the ES wire format.
    /// Same transform as [`Self::lookup_seq_no`]/[`Self::lookup_version`],
    /// but from a `VersionEntry` the caller already has in scope — for
    /// building a `Hit` inline with the doc's version-map entry already in
    /// hand, so `_seq_no`/`_version` come from the SAME read as `_source`,
    /// never a later pass over the version map (#440: a second pass lets a
    /// concurrent write pair a stale `_source` with a live `_seq_no`, which
    /// is a silent lost update once a caller round-trips it as `if_seq_no`).
    fn hit_seq_version(
        &self,
        id: &str,
        ver: &xerj_storage::version_map::VersionEntry,
    ) -> (Option<u64>, Option<u64>) {
        if ver.deleted {
            return (None, None);
        }
        (
            Some(ver.seq_no.saturating_sub(1)),
            Some(
                self.external_versions
                    .get(id)
                    .map(|v| *v)
                    .unwrap_or(ver.version),
            ),
        )
    }

    pub fn lookup_seq_no(&self, id: &str) -> Option<u64> {
        self.store.version_map.get(id).and_then(|entry| {
            if entry.deleted {
                None
            } else {
                Some(entry.seq_no.saturating_sub(1))
            }
        })
    }

    /// Look up the ES `_version` for a live document by id.
    ///
    /// The external-version map wins (docs written with
    /// `version_type=external[_gte]` must echo the caller's version, per
    /// ES), falling back to the engine-tracked per-doc write counter.
    /// Returns `None` when the doc is unknown or tombstoned.
    pub fn lookup_version(&self, id: &str) -> Option<u64> {
        let tracked = self.store.version_map.get(id).and_then(|entry| {
            if entry.deleted {
                None
            } else {
                Some(entry.version)
            }
        })?;
        Some(
            self.external_versions
                .get(id)
                .map(|v| *v)
                .unwrap_or(tracked),
        )
    }

    /// Resolve an ES meta-field named as a SORT key (#401).
    ///
    /// These fields are engine metadata: they are never literal keys in
    /// `_source`, so `compute_sort_values`' generic `get_field_value` path
    /// resolved every one of them to `Null` on every document — a sort that
    /// silently ties the whole result set, and a `search_after` cursor that
    /// can never advance past page one (`[null]` is never strictly greater
    /// than `[null]`).  Lucene has no such failure mode because a sort key
    /// is read from the field's DOC VALUES column rather than from the
    /// stored document — `SortedNumericSortField` selects the document's
    /// representative sort value out of `SortedNumericDocValues`
    /// (`lucene/core/src/java/org/apache/lucene/search/SortedNumericSortField.java:49-59`)
    /// and `NumericComparator` compares those column values directly
    /// (`lucene/core/src/java/org/apache/lucene/search/comparators/NumericComparator.java:47-63`).
    /// xerj has no column for these fields, so it resolves them through the
    /// SAME version-map accessors (`lookup_seq_no` / `lookup_version`) that
    /// back the response meta-fields — so a hit's `sort` value equals its
    /// `_seq_no` / `_version` whenever the lookup RESOLVES. It can only diverge
    /// for a doc whose lookup returns `None` after it was collected (a
    /// concurrent tombstone / version-map miss): this function then yields
    /// `Value::Null` (so the request's `missing` policy governs the sort key),
    /// while the response side applies its own `None` fallback — a narrow,
    /// already-racing case that does not affect the ranking key computed here.
    ///
    /// Returns `None` for every other field name, so the caller falls
    /// through to the ordinary `_source` lookup.
    fn meta_sort_value(&self, field: &str, id: &str) -> Option<Value> {
        // Hot path: this runs per candidate doc per sort field inside the
        // bounded collectors, and an ordinary field name is the overwhelming
        // case — settle it with one byte compare instead of four `str` eq.
        if !field.starts_with('_') {
            return None;
        }
        match field {
            // `_seq_no`: the ES-sortable one (real ES gives it doc values
            // and rejects the sort only under
            // `index.disable_sequence_numbers`, which es_compat.rs already
            // rejects at the API edge before the request reaches here).
            // Unresolvable (unknown / tombstoned) stays `Null` so the
            // request's `missing` policy still applies.
            "_seq_no" => Some(
                self.lookup_seq_no(id)
                    .map_or(Value::Null, |s| Value::Number(s.into())),
            ),
            "_version" => Some(
                self.lookup_version(id)
                    .map_or(Value::Null, |v| Value::Number(v.into())),
            ),
            // xerj is single-shard with `primary_term` fixed at 1 — the same
            // constant the hit meta-field emits (es_compat.rs:13250). Constant
            // for every doc, so it ties like any other constant sort key;
            // callers paginating on it still need a tie-breaker field.
            "_primary_term" => Some(Value::Number(1.into())),
            // Constant within one index; it discriminates only in the
            // cross-index merge, which re-sorts on these same `sort` arrays
            // (es_compat.rs:10855).
            "_index" => Some(Value::String(self.name.as_str().to_string())),
            _ => None,
        }
    }

    /// Live document ids, sorted by id.
    ///
    /// A tombstone is not included. The id is present once the index call
    /// has returned, including before refresh.
    pub fn live_document_ids(&self) -> Vec<String> {
        self.store.version_map.live_ids()
    }

    /// Retrieve a document by its string ID.
    ///
    /// Checks the memtable first, then searches on-disk segments.
    /// Counts every GET, regardless of the result, so indices.stats
    /// reflects the true ES `get.total` counter (which includes
    /// missing + exists).
    pub async fn get_document(&self, id: &str) -> Result<Option<Value>> {
        use crate::collection_publication::ReadAdmission;

        let get_started = std::time::Instant::now();
        self.metric_get_count.fetch_add(1, Ordering::Relaxed);
        let mut res = loop {
            let token = loop {
                let notified = self.collection_publication.notified();
                tokio::pin!(notified);
                notified.as_mut().enable();
                match self.collection_publication.try_admit_reader() {
                    ReadAdmission::Admitted(token) => break token,
                    ReadAdmission::Poisoned => {
                        return Err(collection_publication_interrupted());
                    }
                    ReadAdmission::WriterActive => notified.await,
                }
            };
            let result = self.get_document_uncounted(id).await;
            match self.collection_publication.validate_reader(token) {
                ReadAdmission::Admitted(_) => break result,
                ReadAdmission::Poisoned => return Err(collection_publication_interrupted()),
                ReadAdmission::WriterActive => continue,
            }
        };
        if let Ok(Some(source)) = &mut res {
            strip_internal_passage_metadata(source);
            // The stored source keeps embeddings packed (#1940). GET returns
            // the number array callers already see.
            xerj_common::packed_f32::expand_packed_f32_values(source);
        }
        match &res {
            Ok(Some(_)) => {
                self.metric_get_exists_count.fetch_add(1, Ordering::Relaxed);
            }
            Ok(None) => {
                self.metric_get_missing_count
                    .fetch_add(1, Ordering::Relaxed);
            }
            Err(_) => {}
        }
        self.metric_get_total_ms
            .fetch_add(get_started.elapsed().as_millis() as u64, Ordering::Relaxed);
        res
    }

    /// Metrics-free internal fetch: `get_document` minus the get.total /
    /// exists / missing counters. Used by the HNSW kNN hydration path —
    /// counting k internal fetches per kNN query would inflate
    /// `indices.stats` get.total by k per search, a wire-visible ES
    /// divergence (ES does not count knn hydration as gets).
    ///
    /// Same lookup semantics as `get_document`: version map first
    /// (tombstoned ids → None), then memtable, then the B2 primary-key
    /// fast path, then the legacy full-segment scan.
    async fn get_document_uncounted(&self, id: &str) -> Result<Option<Value>> {
        // Check version map — if the document was deleted, return None.
        if let Some(entry) = self.store.version_map.get(id) {
            if entry.deleted {
                return Ok(None);
            }
        } else {
            // Document not in version map at all.
            return Ok(None);
        }

        // Check the memtable first — documents live here until a flush.
        {
            let mem = &*self.memtable;
            if mem.contains(id) {
                return Ok(mem.get_doc_source_as_value(id));
            }
        }

        // Search segments for the stored document.
        let snap = self.store.snapshot();

        // ── Primary-key fast path (B2, 2026-07-10 scorecard) ─────────────
        // Resolve the id to its stored position via the same per-segment
        // `_id → position` index the `ids` query uses, then hydrate ONLY
        // that doc's slice through the `StoredSlices` offset index.  The
        // legacy loop below decompresses + parses the ENTIRE stored section
        // per lookup (~470 ms/id at 100 k docs), which made `_mget` ~4
        // orders of magnitude slower than the ids-query path serving the
        // same lookup.  Falls through to the full scan when any piece is
        // unavailable (id index incomplete, slice cache miss, parse error).
        if let Some(ver) = self.store.version_map.get(id) {
            let seg_id: std::sync::Arc<str> = std::sync::Arc::clone(&ver.segment_id);
            drop(ver);
            // RC4 W2 #15 — resolve the owning segment's doc_count from the
            // snapshot, FALLING BACK to the on-disk segment header when the
            // id isn't listed there.  During a merge there is a window
            // between the version-map repoint (`set_if_latest` onto the
            // merged id, inside the merge task) and the snapshot publish
            // (`apply_merge`) — pre-fix, a GET in that window found no
            // snapshot meta, every legacy-loop segment was skipped by the
            // "not this segment" check below, and an EXISTING doc returned
            // 404 (live repro: 47 transient 404s hammering 8 ids through
            // one forcemerge).  The merged segment file is fully durable
            // before the repoint (`SegmentWriter::finish` fsyncs), and
            // `open_segment_arc` derives `{id}.seg` for ids missing from
            // the snapshot, so opening it directly is race-free.
            let seg_doc_count: Option<u64> =
                match snap.segments.iter().find(|m| m.id.as_str() == &*seg_id) {
                    Some(meta) => Some(meta.doc_count),
                    None if &*seg_id != xerj_storage::version_map::IN_MEMORY_SEGMENT_ID => self
                        .store
                        .open_segment_arc(&seg_id)
                        .ok()
                        .map(|r| r.header().doc_count),
                    None => None,
                };
            if let Some(doc_count) = seg_doc_count {
                if let (Some(pos_map), Some(slices)) = (
                    self.id_pos_map_for(&seg_id, doc_count),
                    self.stored_slices_for(&seg_id, doc_count),
                ) {
                    if let Some(&pos) = pos_map.get(id) {
                        if let Some(&(start, end)) = slices.offsets.get(pos as usize) {
                            if let Some(slice) = slices.bytes.get(start as usize..end as usize) {
                                // serde_json (not simd_json): same root cause
                                // as the KNN cache — see ffd49ac.
                                if let Ok(doc) = serde_json::from_slice::<Value>(slice) {
                                    if doc.get("_id").and_then(Value::as_str) == Some(id) {
                                        return Ok(doc.get("_source").cloned());
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        for meta in snap.segments.iter().rev() {
            // Check version map: is this doc in this segment?
            if let Some(ver) = self.store.version_map.get(id) {
                if &*ver.segment_id != meta.id.as_str() {
                    continue; // not this segment
                }
            }

            if let Ok(reader) = self.store.open_segment(&meta.id) {
                if let Ok(Some(stored_bytes_raw)) = reader.section(SectionType::Stored) {
                    let stored_bytes =
                        match xerj_storage::stored_codec::decode_stored(stored_bytes_raw) {
                            Ok(b) => b,
                            Err(_) => continue,
                        };
                    // serde_json (not simd_json): same root cause as the
                    // KNN cache — see ffd49ac. simd_json silently corrupts
                    // some stored payloads from the M7 raw-bytes flush path.
                    if let Ok(docs) = serde_json::from_slice::<Vec<Value>>(&stored_bytes) {
                        for doc in docs {
                            if doc.get("_id").and_then(Value::as_str) == Some(id) {
                                return Ok(doc.get("_source").cloned());
                            }
                        }
                    }
                }
            }
        }

        // RC4 W2 #15 — last-resort direct open for the merge-publish
        // window: the version map points at a segment the snapshot does
        // not list (merged output between repoint and `apply_merge`) and
        // the slice-cache fast path above couldn't serve it (e.g. caches
        // not yet warm).  Decode that one segment's stored section
        // directly rather than 404-ing an existing doc.
        if let Some(ver) = self.store.version_map.get(id) {
            let seg_id: std::sync::Arc<str> = std::sync::Arc::clone(&ver.segment_id);
            drop(ver);
            if &*seg_id != xerj_storage::version_map::IN_MEMORY_SEGMENT_ID
                && !snap.segments.iter().any(|m| m.id.as_str() == &*seg_id)
            {
                if let Ok(reader) = self.store.open_segment_arc(&seg_id) {
                    if let Ok(Some(stored_bytes_raw)) = reader.section(SectionType::Stored) {
                        if let Ok(stored_bytes) =
                            xerj_storage::stored_codec::decode_stored(stored_bytes_raw)
                        {
                            if let Ok(docs) = serde_json::from_slice::<Vec<Value>>(&stored_bytes) {
                                for doc in docs {
                                    if doc.get("_id").and_then(Value::as_str) == Some(id) {
                                        return Ok(doc.get("_source").cloned());
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        drop(snap);

        Ok(None)
    }

    /// Delete a document by ID.
    ///
    /// Thin compatibility wrapper over [`Self::delete_document_versioned`]
    /// (no optimistic-concurrency check). Returns whether a live document
    /// was found and tombstoned.
    pub async fn delete_document(&self, id: &str) -> Result<bool> {
        self.delete_document_versioned(id, None, None)
            .await
            .map(|outcome| outcome.found)
    }

    /// Delete a document by ID with ES delete semantics.
    ///
    /// When `if_seq_no` is supplied (internal 1-based form), the delete is
    /// conditional: the doc's current seq_no must match or a
    /// `VersionConflict` is returned — including when the doc does not
    /// exist (ES returns 409 for a conditional delete of a missing doc).
    /// xerj is single-shard with `primary_term` fixed at 1, so a supplied
    /// `if_primary_term` is accepted but only `if_seq_no` is compared
    /// (same treatment as `index_document_with_version`).
    ///
    /// Unconditional deletes of a missing doc return `found: false` with
    /// the ES-visible version bookkeeping described on [`DeleteDocOutcome`].
    pub async fn delete_document_versioned(
        &self,
        id: &str,
        if_seq_no: Option<u64>,
        if_primary_term: Option<u64>,
    ) -> Result<DeleteDocOutcome> {
        // Check write block.
        if let Some(block) = self.write_block_reason().await {
            return Err(EngineError::Common(xerj_common::XerjError::index_blocked(
                self.name.as_str(),
                block,
            )));
        }
        // Process-wide admission: disk flood-stage block (item 3) + parent
        // memory circuit breaker (item 1). Fires before any per-index work.
        self.governor_write_gate()?;
        let _publication_guard = self.write_publication.lock(id.to_string()).await;
        #[cfg(test)]
        self.publication_test_point(id, PublicationTestPoint::Acquired);
        // Optimistic concurrency check (see index_document_with_version for
        // the if_primary_term rationale).
        let _ = if_primary_term;
        if let Some(expected_seq) = if_seq_no {
            match self.store.version_map.get(id) {
                Some(entry) if !entry.deleted => {
                    if entry.seq_no != expected_seq {
                        return Err(EngineError::Common(
                            xerj_common::XerjError::version_conflict(
                                id,
                                expected_seq,
                                entry.seq_no,
                            ),
                        ));
                    }
                }
                // Missing or tombstoned doc + conditional delete → conflict
                // (ES: "required seqNo [N] ... but no document was found").
                _ => {
                    return Err(EngineError::Common(
                        xerj_common::XerjError::version_conflict(id, expected_seq, 0),
                    ));
                }
            }
        }

        // Check whether the document actually exists and is not already deleted.
        let is_live = self
            .store
            .version_map
            .get(id)
            .map(|entry| !entry.deleted)
            .unwrap_or(false);

        // Also check the memtable (newly indexed docs may not yet be in the
        // version map or may have been put there after the version_map check).
        let in_memtable = {
            let mem = &*self.memtable;
            mem.contains(id)
        };

        let should_delete = is_live || in_memtable;

        if !should_delete {
            // ES `result: not_found` bookkeeping: a repeat delete of a
            // tombstoned doc still bumps (and persists) the tombstone's
            // version; a never-seen id reports version 1. No WAL entry or
            // seq_no is consumed for a not-found delete.
            let existing = self.store.version_map.get(id);
            let version = self
                .store
                .version_map
                .bump_tombstone_version(id)
                .unwrap_or(1);
            let seq_no = existing
                .map(|e| e.seq_no)
                .unwrap_or_else(|| self.store.current_seq_no().saturating_sub(1));
            #[cfg(test)]
            self.publication_test_point(id, PublicationTestPoint::BeforeRelease);
            return Ok(DeleteDocOutcome {
                found: false,
                seq_no,
                version,
            });
        }

        let _hnsw_publication = self
            .has_dense_vector_mapping()
            .await
            .then(|| self.begin_hnsw_publication());

        let mut collection_publication = self
            .collection_publication
            .begin()
            .map_err(|_| collection_publication_interrupted())?;
        // Invalidate response caches only once the OCC check has succeeded and
        // the delete will mutate publication state. A rejected conditional
        // delete must not make unrelated cached responses look stale.
        self.dataset_version.fetch_add(1, Ordering::Release);
        // As on the index path: a storage failure here precedes every
        // visibility mutation (the bump above only invalidates caches, which
        // is conservative), so cancel instead of leaving the guard Pending and
        // poisoning the index for every later request.
        let deleted_seq = match self.store.delete(id) {
            Ok(deleted_seq) => deleted_seq,
            Err(e) => {
                collection_publication.cancel();
                drop(collection_publication);
                self.collection_publication.handoff_to_readers().await;
                return Err(e.into());
            }
        };
        #[cfg(test)]
        self.publication_test_point(id, PublicationTestPoint::AfterWalVersionMap);
        let existed = deleted_seq.is_some();

        // Remove from memtable.
        {
            let mem = &*self.memtable;
            mem.remove(id);
        }
        #[cfg(test)]
        self.publication_test_point(id, PublicationTestPoint::AfterFts);

        if existed {
            self.doc_count.fetch_sub(1, Ordering::Relaxed);
        }
        let found = existed || in_memtable;
        if !found {
            // Raced away between the liveness check and store.delete. Finish
            // tombstone bookkeeping inside the lexical publication interval.
            let version = self
                .store
                .version_map
                .bump_tombstone_version(id)
                .unwrap_or(1);
            let seq_no = self.store.current_seq_no().saturating_sub(1);
            collection_publication.commit();
            drop(collection_publication);
            self.collection_publication.handoff_to_readers().await;
            #[cfg(test)]
            self.publication_test_point(id, PublicationTestPoint::BeforeRelease);
            return Ok(DeleteDocOutcome {
                found: false,
                seq_no,
                version,
            });
        }
        let version = self
            .store
            .version_map
            .get(id)
            .map(|e| e.version)
            .unwrap_or(1);
        let seq_no = deleted_seq.unwrap_or_else(|| self.store.current_seq_no().saturating_sub(1));
        collection_publication.commit();
        drop(collection_publication);
        self.collection_publication.handoff_to_readers().await;
        // v0.6.2 — propagate the delete into the HNSW graph. Pre-fix
        // a deleted doc was unfindable via _get / _search but the
        // vector still showed up in kNN results forever (the node
        // and its neighbour edges stayed in the graph). mark_deleted
        // tombstones the node so kNN skips it; the edges remain
        // until a graph compaction (planned v0.7+).
        let node_id_to_tomb = {
            let id_map = self.hnsw_id_map.read().await;
            id_map.get(id).copied()
        };
        if let Some(node_id) = node_id_to_tomb {
            let hnsw_guard = self.hnsw.read().await;
            if let Some(ref h) = *hnsw_guard {
                h.mark_deleted(node_id);
            }
            drop(hnsw_guard);
            // Remove from id maps so a re-index of the same doc_id
            // gets a fresh node_id (the old one stays tombstoned).
            self.hnsw_id_map.write().await.remove(id);
            self.hnsw_id_rev.write().await.remove(&node_id);
            // Item 8: this doc leaves the coverage-gate denominator.
            self.vector_doc_count
                .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |v| {
                    Some(v.saturating_sub(1))
                })
                .ok();
        }
        // #392: drop the deleted doc's SQ8 code slots so the per-field
        // coverage gates stay exact (mirrors the vector_doc_count decrement
        // above).
        {
            let guard = self.sq8_stores.read();
            for handle in guard.values() {
                handle.store.write().remove(id);
            }
        }
        #[cfg(test)]
        self.publication_test_point(id, PublicationTestPoint::AfterHnsw);

        #[cfg(test)]
        self.publication_test_point(id, PublicationTestPoint::BeforeRelease);
        Ok(DeleteDocOutcome {
            found: true,
            seq_no,
            version,
        })
    }

    /// Update a document by merging a partial document into the existing source.
    ///
    /// Fetches the current document, merges the provided `partial_doc` fields
    /// (top-level keys) into the existing source, then re-indexes the merged result.
    /// Returns `None` if the document does not exist.
    pub async fn update_document(
        &self,
        id: &str,
        partial_doc: Value,
    ) -> Result<Option<IndexResponse>> {
        let publication_guard = self.write_publication.lock(id.to_string()).await;
        // Fetch existing document source.
        let existing = match self.get_document(id).await? {
            Some(src) => src,
            None => return Ok(None),
        };

        // Merge: start from existing, overlay partial_doc fields.
        let merged = match existing {
            Value::Object(mut map) => {
                if let Some(partial_obj) = partial_doc.as_object() {
                    for (k, v) in partial_obj {
                        map.insert(k.clone(), v.clone());
                    }
                }
                Value::Object(map)
            }
            other => {
                // Non-object source — just replace with the partial.
                if partial_doc.is_object() {
                    partial_doc
                } else {
                    other
                }
            }
        };

        // Re-index with the same ID (upsert-style).
        let resp = self
            .index_document_with_version_inner_guarded(
                Some(id.to_string()),
                merged,
                None,
                None,
                false,
                Some(publication_guard),
                false,
                None,
            )
            .await?;
        Ok(Some(resp))
    }

    /// The complete live `_id` match set for `match_all` / `ids` queries,
    /// ascending — the #1019 single-pass alternative to paging a purge.
    ///
    /// Reads each flushed segment's cached `_id → position` map (`#950`'s
    /// `id_pos_map_for`, which decodes the `_id` column alone) and the
    /// version map, so the whole match set costs one O(N) id
    /// materialisation (~48 B per match: `String` + vec slot) instead of the
    /// paged loop's one full stored-section re-scan per page (O(N × pages)
    /// over the corpus — the dominant cost of a default-size purge once the
    /// per-page `_source` hydration was gone).
    ///
    /// Caller SHOULD flush first (same precondition as the paged loop): the
    /// memtable leg below keeps the enumeration COMPLETE without it, but the
    /// paged fallback arm the caller eventually runs for other query shapes
    /// pages `_id`-keyset over on-disk segments only.
    ///
    /// `None` = this query shape (or a segment without a complete id index)
    /// is not served here — the caller falls back to the paged keyset loop,
    /// which answers every query. Liveness and byte-order match that loop
    /// exactly: a missing version-map entry counts as live, a deleted entry
    /// is skipped, and ids sort as byte strings (the `_id` sort key's order).
    ///
    /// Linearized against concurrent publications (the #1023 CI regression):
    /// the enumeration reads only the snapshot's segments, so without reader
    /// admission a doc sitting in a flush's drain→publish window — drained
    /// out of the memtable, not yet in a published segment — was invisible,
    /// and sixteen concurrent `update_by_query` calls collected FIFTEEN empty
    /// match sets and reported `total:0 / updated:0 / failures:[]` while one
    /// lone increment landed (`n == 1`, expected 16). The enumeration now
    /// takes the same `CollectionPublication` reader-admission bracket
    /// `get_document` uses (acquire token, capture, validate, retry): the
    /// flush writer bracket provably spans drain→publish (`do_flush_shard`
    /// begins the guard before the memtable drain and commits it in the
    /// finalize worker after the snapshot publish), so a validated
    /// enumeration cannot land inside that window. On `Poisoned` the answer
    /// is `None` — the caller's paged arm runs `search()`, which surfaces the
    /// poison as a real error instead of a silent no-op.
    ///
    /// COMPLETE, not just consistent (the runner-only #1023 residual):
    /// admission alone made every capture consistent but left it INCOMPLETE —
    /// the segment id maps say nothing about a doc whose live copy is still
    /// memtable-only, so at any validated instant before the first drain (or
    /// after a failed finalize restored a drained doc) the enumeration
    /// answered `Some([])`, a perfectly consistent EMPTY match set, and the
    /// by-query arms no-opped silently (`total:0 / failures:[]`). On CI's
    /// 4-vCPU / `--test-threads=2` / slow-fsync runners sixteen concurrent
    /// `_update_by_query` calls still lost fourteen of sixteen increments
    /// (`left:2`) after the admission fix, while every local shape (40+
    /// isolated, full-suite, `RUST_TEST_THREADS=2` on pinned cores) held the
    /// entry-flush precondition that made the memtable-only instant
    /// unreachable. The memtable leg removes the dependence on that
    /// precondition entirely: the FTS memtable's live ids are captured inside
    /// the SAME validated bracket (`fold_match_sources`'s capture shape), so
    /// a doc is enumerated from its memtable copy until a flush's publish
    /// bracket commits, and from its segment's id map from then on — never
    /// from neither.
    pub async fn matching_ids_sorted(&self, query: &QueryNode) -> Option<Vec<String>> {
        use crate::collection_publication::ReadAdmission;

        // Membership resolved against a set: an `ids` query can carry tens of
        // thousands of values, and a per-doc linear scan would reintroduce
        // exactly the O(N × k) blowup this method exists to remove.
        let values: Option<std::collections::HashSet<&str>> = match query {
            QueryNode::MatchAll => None,
            QueryNode::Ids { values } => Some(values.iter().map(String::as_str).collect()),
            _ => return None,
        };
        // `get_document`'s admission shape exactly: wait out any active
        // publication bracket (flush, merge, or write), enumerate, and retry
        // the whole enumeration if a bracket opened while we read. Retrying
        // is safe — the enumeration has no side effects.
        let ids = loop {
            let token = loop {
                let notified = self.collection_publication.notified();
                tokio::pin!(notified);
                notified.as_mut().enable();
                match self.collection_publication.try_admit_reader() {
                    ReadAdmission::Admitted(token) => break token,
                    ReadAdmission::Poisoned => return None,
                    ReadAdmission::WriterActive => notified.await,
                }
            };
            // BOTH legs captured inside ONE bracket (`fold_match_sources`'s
            // capture shape): the memtable's live ids and the segment
            // snapshot. A drain happens only inside a publication bracket
            // whose commit follows the snapshot publish, so a validated pair
            // cannot straddle a drain→publish window — every live doc is in
            // exactly one leg (the sort+dedup below collapses an id that a
            // concurrent update left in both).
            let mem_ids = self.memtable.all_doc_ids();
            let snap = self.store.snapshot();
            let mut ids: Vec<String> = Vec::with_capacity(
                mem_ids.len()
                    + snap
                        .segments
                        .iter()
                        .map(|m| m.doc_count as usize)
                        .sum::<usize>(),
            );
            // ── Memtable leg: a doc lives here from its write until a flush
            // publish commits it into a segment. Deletes remove from the
            // memtable, so the only liveness rule needed on top is the same
            // version-map tombstone skip the segment leg applies.
            for id in mem_ids {
                if let Some(set) = &values {
                    if !set.contains(id.as_str()) {
                        continue;
                    }
                }
                if let Some(ver) = self.store.version_map.get(&id) {
                    if ver.deleted {
                        continue;
                    }
                }
                ids.push(id);
            }
            let mut unsupported = false;
            for meta in snap.segments.iter() {
                let map = match self.id_pos_map_for(meta.id.as_str(), meta.doc_count) {
                    Some(map) => map,
                    None => {
                        unsupported = true;
                        break;
                    }
                };
                for id in map.keys() {
                    if let Some(set) = &values {
                        if !set.contains(id.as_str()) {
                            continue;
                        }
                    }
                    if let Some(ver) = self.store.version_map.get(id) {
                        if ver.deleted {
                            continue;
                        }
                    }
                    ids.push(id.clone());
                }
            }
            if unsupported {
                return None;
            }
            ids.sort_unstable();
            // Same contract as the paged loop's `seen_ids`: an id resolves to one
            // delete even if a legacy multi-segment layout lists it twice.
            ids.dedup();
            match self.collection_publication.validate_reader(token) {
                ReadAdmission::Admitted(_) => break ids,
                ReadAdmission::Poisoned => return None,
                ReadAdmission::WriterActive => continue,
            }
        };
        Some(ids)
    }

    /// Single-pass `_source` fold over the whole live match set (#1022).
    ///
    /// Calls `f` with the `_source` of every live document matching `query`,
    /// holding ONE parsed doc at a time. This is the read-side analogue of
    /// `matching_ids_sorted`: the significant_text profiler fast path used to
    /// issue ONE `size: 10_000` search and fold the materialised hits, so on
    /// a corpus past one page it silently under-counted every exact-statistics
    /// counter — and it materialised up to 10 k full `Value` trees per index
    /// to do it (the #950 RSS-transient class). The fold is exact at any
    /// corpus size and never holds more than one source.
    ///
    /// Why a fold and not keyset paging: the consumers of this walk need
    /// completeness and duplicate-freedom, not page ORDER (their counters are
    /// order-independent folds). That is exactly the property `_id`-keyset
    /// `search_after` paging cannot give without a flush — the memtable's
    /// field-sort path does not order by `_id` reliably, and a read endpoint
    /// (`_search`) must not flush. One walk needs neither.
    ///
    /// Membership agrees with the search path's: the query is resolved
    /// through the same pipeline `search_inner` applies (alias rewrite,
    /// keyword→term, lexically-typeless lowering, single-clause bool unwrap)
    /// and then matched per doc with the same typed matcher the memtable scan
    /// arm uses (`doc_matches_query_typed`); liveness is the same rule the
    /// scan arms apply (version-map tombstone skip, superseded-copy skip, one
    /// id per walk, memtable copy preferred over a stale segment copy).
    ///
    /// Consistency under a concurrent publication: the memtable capture and
    /// the segment snapshot are taken inside ONE `CollectionPublication`
    /// reader bracket, validated before the walk starts (#1023 — previously
    /// a doc drained from the memtable after the capture and unpublished at
    /// the snapshot was silently missed). The segment snapshot then holds
    /// its read lease for the whole walk (retired segment files persist), so
    /// a mid-walk flush or merge can neither orphan a byte range nor feed an
    /// id twice — a drained-then-flushed doc is either still in this
    /// snapshot's memtable capture or in one of its segments, never both
    /// (dedup by id) and never neither (the lease keeps the old segment
    /// readable). Docs written after the walk started may or may not be seen;
    /// that is the same window any single search has.
    pub async fn fold_match_sources<F: FnMut(&Value)>(&self, query: &QueryNode, f: &mut F) {
        // Resolve the query exactly as `search_inner` does (two guard takes,
        // same as that function's `dmq_schema` then `schema.read()` pair).
        let dmq_schema = self.schema().await;
        let resolved_query = {
            let schema = self.schema.read().await;
            let resolved = rewrite_keyword_full_text_to_term(
                &rewrite_query_aliases(query, &schema.schema),
                &schema.schema,
            );
            let typeless = crate::memtable::lexically_typeless_fields(&schema.schema);
            let lowered = if typeless.is_empty() {
                resolved
            } else {
                lower_lexically_typeless_clauses(&resolved, &typeless)
            };
            unwrap_single_clause_bool(lowered)
        };
        let is_match_all = matches!(resolved_query, QueryNode::MatchAll);
        let needs_id_injection = query_needs_id_injection(&resolved_query);
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();

        // ── Capture bracket (#1023): both captures under ONE admission ──────
        //
        // The memtable capture and the segment snapshot were previously taken
        // apart, and the gap between them was the narrow variant of the hole
        // `matching_ids_sorted`'s admission loop closes: a doc drained out of
        // the memtable after the capture but unpublished at the snapshot sat
        // in neither and was silently missed. Both captures are now taken
        // inside one `CollectionPublication` reader bracket and validated
        // BEFORE the walk starts — a drain happens only inside a publication
        // bracket, and a flush's publish completes before its bracket drops,
        // so a validated pair cannot straddle a drain→publish window. On
        // `WriterActive` only the captures are retried (they are cheap);
        // `f` has side effects, so the walk itself is never re-run.
        let ghost_filter = self.store.version_map.ghost_events() > 0;
        let (mem_docs, snap) = {
            use crate::collection_publication::ReadAdmission;

            loop {
                let token = loop {
                    let notified = self.collection_publication.notified();
                    tokio::pin!(notified);
                    notified.as_mut().enable();
                    match self.collection_publication.try_admit_reader() {
                        ReadAdmission::Admitted(token) => break Some(token),
                        // Poisoned: nothing consistent is left to wait for —
                        // every collection-wide reader on this index errors
                        // from here on, and the fold has no error channel, so
                        // walk the captures best-effort (the pre-fix
                        // behaviour) rather than silently folding nothing.
                        ReadAdmission::Poisoned => break None,
                        ReadAdmission::WriterActive => notified.await,
                    }
                };
                let mem_docs = self.memtable.all_docs_with_seq_arc();
                let snap = self.store.snapshot();
                let raced = token.is_some_and(|token| {
                    matches!(
                        self.collection_publication.validate_reader(token),
                        ReadAdmission::WriterActive
                    )
                });
                if raced {
                    continue;
                }
                break (mem_docs, snap);
            }
        };

        // ── Memtable: one Arc-shared snapshot, matched per doc ──────────────
        // Deletes remove from the memtable, so `docs` is live by construction;
        // the ghost-window check (below) only guards the window where the
        // live copy of an id moved to a segment between snapshot and now —
        // the segment walk covers that id instead.
        for (_seq_no, doc_id, source) in mem_docs {
            if ghost_filter {
                if let Some(ver) = self.store.version_map.get(&doc_id) {
                    if ver.deleted
                        || ver.segment_id.as_ref()
                            != xerj_storage::version_map::IN_MEMORY_SEGMENT_ID
                    {
                        continue;
                    }
                }
            }
            if !seen.insert(doc_id.clone()) {
                continue;
            }
            let matched = if is_match_all {
                true
            } else if let QueryNode::Ids { values } = &resolved_query {
                values.iter().any(|v| v == doc_id.as_str())
            } else if !needs_id_injection || source.get("_id").is_some() {
                doc_matches_query_typed(&resolved_query, &source, &dmq_schema)
            } else {
                // Inject `_id` so deeply-nested Ids queries can resolve it
                // (same fallback as the memtable scan arm).
                let source_with_id = if let Some(obj) = source.as_object() {
                    let mut o = obj.clone();
                    o.insert("_id".to_string(), Value::String(doc_id.clone()));
                    Value::Object(o)
                } else {
                    (*source).clone()
                };
                doc_matches_query_typed(&resolved_query, &source_with_id, &dmq_schema)
            };
            if matched && !source.is_null() {
                f(&source);
            }
        }

        // ── Segments: one stored-section walk per segment, one doc parsed
        // at a time. The scan arms' brace-walk, reduced to its bones. The
        // snapshot is the admission bracket's capture above — NOT a fresh
        // one — so the walk reads exactly the segment set the bracket
        // validated.
        for meta in snap.segments.iter() {
            let seg_id = meta.id.clone();
            // Same cache discipline as the unsorted search path: reuse the
            // retained decompressed section when present, else cold-decode
            // (under the segment's single-flight lock, so concurrent cold
            // walkers decode once) and publish it back for the next query.
            let cached_bytes: Option<Vec<u8>> = self
                .decoded_stored_cache
                .get(seg_id.as_str())
                .map(|e| e.value().value().clone())
                .or_else(|| {
                    self.stored_slices_cache
                        .get(seg_id.as_str())
                        .map(|e| e.value().bytes.clone())
                });
            let stored_bytes = match cached_bytes {
                Some(bytes) => bytes,
                None => {
                    let flight = {
                        let entry = self
                            .stored_slices_build_locks
                            .entry(seg_id.clone())
                            .or_default();
                        std::sync::Arc::clone(entry.value())
                    };
                    let _flight_guard = flight.lock().ok();
                    // Re-check under the flight lock — another thread may
                    // have decoded and published while we waited.
                    let rechecked: Option<Vec<u8>> = self
                        .decoded_stored_cache
                        .get(seg_id.as_str())
                        .map(|e| e.value().value().clone())
                        .or_else(|| {
                            self.stored_slices_cache
                                .get(seg_id.as_str())
                                .map(|e| e.value().bytes.clone())
                        });
                    match rechecked {
                        Some(bytes) => bytes,
                        None => {
                            let decoded: Option<Vec<u8>> =
                                match self.store.open_segment_arc(&seg_id) {
                                    Ok(reader) => match reader.section(SectionType::Stored) {
                                        Ok(Some(raw)) => {
                                            xerj_storage::stored_codec::decode_stored(raw).ok()
                                        }
                                        _ => None,
                                    },
                                    Err(_) => None,
                                };
                            match decoded {
                                Some(bytes) => {
                                    let est = crate::segment_cache_estimates::decoded_stored_bytes(
                                        &seg_id,
                                        std::mem::size_of::<CacheResident<Vec<u8>>>(),
                                        bytes.capacity(),
                                    );
                                    let _ = self.publish_current(
                                        &self.decoded_stored_cache,
                                        &seg_id,
                                        seg_id.clone(),
                                        SegmentCacheCategory::DecodedStored,
                                        est,
                                        bytes.clone(),
                                    );
                                    bytes
                                }
                                // Unreadable/undecodable section: the search
                                // path fails the whole query here; a fold has
                                // no error channel, so skip the segment and
                                // let the caller's own tolerance stand (the
                                // pre-fold fast path swallowed search errors
                                // the same way).
                                None => continue,
                            }
                        }
                    }
                }
            };

            // Brace-walk the section: `[{...}, {...}, ...]` — find each
            // top-level object's byte range by balanced-brace counting and
            // parse only that slice (the same per-doc allocation discipline
            // as `scan_stored_section_into`).
            let bytes: &[u8] = &stored_bytes;
            let n = bytes.len();
            let mut i = 0usize;
            while i < n && (bytes[i].is_ascii_whitespace() || bytes[i] == b'[') {
                i += 1;
            }
            loop {
                while i < n && (bytes[i].is_ascii_whitespace() || bytes[i] == b',') {
                    i += 1;
                }
                if i >= n || bytes[i] == b']' {
                    break;
                }
                if bytes[i] != b'{' {
                    break; // unexpected byte — stop this section gracefully
                }
                let start = i;
                let mut depth = 0i32;
                let mut in_str = false;
                let mut escape = false;
                while i < n {
                    let b = bytes[i];
                    if in_str {
                        if escape {
                            escape = false;
                        } else if b == b'\\' {
                            escape = true;
                        } else if b == b'"' {
                            in_str = false;
                        }
                    } else {
                        match b {
                            b'"' => in_str = true,
                            b'{' => depth += 1,
                            b'}' => {
                                depth -= 1;
                                if depth == 0 {
                                    i += 1;
                                    break;
                                }
                            }
                            _ => {}
                        }
                    }
                    i += 1;
                }
                if depth != 0 {
                    break; // malformed tail — stop this section gracefully
                }
                let slice = &bytes[start..i];

                // Id first, borrowed where the layout allows (the #1019
                // trick), falling back to the parsed doc's `_id`.
                let borrowed_id = extract_stored_id_str(slice).map(str::to_string);
                let mut doc_buf = slice.to_vec();
                let doc: Value = match simd_json::serde::from_slice(&mut doc_buf) {
                    Ok(v) => v,
                    Err(_) => continue,
                };
                let id_owned = borrowed_id
                    .or_else(|| doc.get("_id").and_then(Value::as_str).map(str::to_string));
                let id_ref: &str = match id_owned.as_deref() {
                    Some(id) => id,
                    None => continue,
                };
                if !seen.insert(id_ref.to_string()) {
                    continue;
                }
                // Version-map liveness + superseded-copy skip (the scan arm's
                // exact predicate, including the raw-source-without-`_seq_no`
                // pass-through).
                if let Some(ver) = self.store.version_map.get(id_ref) {
                    if ver.deleted {
                        continue;
                    }
                    if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                        if doc_seq < ver.seq_no {
                            continue;
                        }
                    }
                }
                let matched = if is_match_all {
                    true
                } else if let QueryNode::Ids { values } = &resolved_query {
                    values.iter().any(|v| v == id_ref)
                } else {
                    let source_ref = doc.get("_source").unwrap_or(&doc);
                    if needs_id_injection && source_ref.get("_id").is_none() {
                        let source_with_id = if let Some(obj) = source_ref.as_object() {
                            let mut o = obj.clone();
                            o.insert("_id".to_string(), Value::String(id_ref.to_string()));
                            Value::Object(o)
                        } else {
                            source_ref.clone()
                        };
                        doc_matches_query_typed(&resolved_query, &source_with_id, &dmq_schema)
                    } else {
                        doc_matches_query_typed(&resolved_query, source_ref, &dmq_schema)
                    }
                };
                if !matched {
                    continue;
                }
                // Same source rule as a hydrated hit: the envelope's
                // `_source`, or the whole doc for raw-source layouts.
                let source_ref = doc.get("_source").unwrap_or(&doc);
                if !source_ref.is_null() {
                    f(source_ref);
                }
            }
        }
    }

    /// Delete all documents matching the given query.
    ///
    /// Collects the whole match set in one pass (`matching_ids_sorted`) and
    /// deletes it in `DELETE_BY_QUERY_PAGE` batches when the query shape
    /// allows; anything else pages `_id`-keyset batches with the internal
    /// ids-only projection (the `_reindex` loop's shape). Either way a purge
    /// over more than `max_result_window` documents deletes EVERY match —
    /// the old single-shot `size: 10_000` search silently truncated at one
    /// page and returned a `(total, deleted)` pair that disagreed (#1019).
    /// Returns `(total_matched, deleted_count)`.
    pub async fn delete_by_query(self: &Arc<Self>, query: QueryNode) -> Result<(u64, u64)> {
        // Flush first: the single-pass id collection and `_id`-keyset paging
        // are both only correct over on-disk segments (the memtable's
        // field-sort path does not order by `_id` reliably, so either path
        // over unflushed docs could skip or duplicate ids) — the same
        // precondition `reindex` establishes.
        self.flush().await?;
        if let Some(ids) = self.matching_ids_sorted(&query).await {
            let total = ids.len() as u64;
            let mut deleted = 0u64;
            for chunk in ids.chunks(DELETE_BY_QUERY_PAGE) {
                for id in chunk {
                    if self.delete_document(id).await? {
                        deleted += 1;
                    }
                }
            }
            // Never under-report if a concurrent writer extended the match
            // set past the collection snapshot mid-purge.
            return Ok((total.max(deleted), deleted));
        }
        let mut total = 0u64;
        let mut deleted = 0u64;
        // Keyset cursor: `[last_id]` of the previous page (the sole sort key
        // is `_id: asc`). `None` on the first page.
        let mut search_after: Option<Vec<Value>> = None;
        loop {
            let req = SearchRequest {
                query: query.clone(),
                from: 0,
                size: DELETE_BY_QUERY_PAGE,
                sort: vec![xerj_query::sort::SortField {
                    field: "_id".to_string(),
                    order: xerj_query::sort::SortOrder::Asc,
                    mode: xerj_query::sort::SortMode::default(),
                    missing: xerj_query::sort::SortMissing::default(),
                    format: None,
                    unmapped_type: None,
                    numeric_type: None,
                }],
                search_after: search_after.clone(),
                ids_only: true,
                ..SearchRequest::default()
            };
            let results = self.search(&req).await?;
            if results.hits.is_empty() {
                break;
            }
            // Page 1's `hits.total` is the EXACT pre-delete match count
            // (later pages run over an already-shrunk live set).
            if total == 0 {
                total = results.total.value;
            }
            let last_id = results.hits.last().map(|h| h.id.clone());
            for hit in results.hits {
                if self.delete_document(&hit.id).await? {
                    deleted += 1;
                }
            }
            match last_id {
                Some(id) => search_after = Some(vec![Value::String(id)]),
                None => break,
            }
        }
        // Never under-report if a concurrent writer extended the match set
        // past page 1's snapshot count mid-purge.
        total = total.max(deleted);
        Ok((total, deleted))
    }

    // ── Search ────────────────────────────────────────────────────────────────

    /// `from + size` against this index's result window: its
    /// `index.max_result_window` setting, else the node's
    /// `limits.max_result_window` (10,000 by default, the ES default).
    ///
    /// Called by [`Index::search`] ahead of the per-query memory guard, so an
    /// oversized window is the 400 `illegal_argument_exception` ES returns
    /// rather than a 429 from the guard, and again at the top of
    /// `search_inner`, ahead of the kNN / semantic short-circuits that never
    /// reach materialisation (hybrid legs re-enter there). The parser used to
    /// refuse any from + size above a hardcoded 10,000, which also overrode a
    /// larger per-index setting.
    ///
    /// The setting may be stored as a nested object `{index: {max_result_window}}`,
    /// a literal-dotted key under `index`, or a top-level dotted key, depending
    /// on the shape the caller provided. (Ids-count validation happens at the
    /// HTTP layer where index_settings is accessible.)
    async fn check_result_window(&self, from: usize, size: usize) -> Result<()> {
        let max_result_window: usize = {
            let settings = self.settings.read().await;
            settings
                .pointer("/index/max_result_window")
                .and_then(|v| {
                    v.as_u64()
                        .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                })
                .or_else(|| {
                    settings
                        .get("index")
                        .and_then(|i| i.get("index.max_result_window"))
                        .and_then(|v| {
                            v.as_u64()
                                .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                        })
                })
                .or_else(|| {
                    settings.get("index.max_result_window").and_then(|v| {
                        v.as_u64()
                            .or_else(|| v.as_str().and_then(|s| s.parse().ok()))
                    })
                })
                .map(|v| v as usize)
                .unwrap_or(self.max_result_window)
        };
        if from.saturating_add(size) > max_result_window {
            return Err(EngineError::Common(
                xerj_common::XerjError::result_window_too_large(from, size, max_result_window),
            ));
        }
        Ok(())
    }

    /// A deadline that expired before any hit was captured. Counted as a
    /// query (the wait was real work) and never cached: the caller is in
    /// `search`, ahead of `search_at_generation`'s cache lookup.
    fn deadline_exhausted_result(&self, started: std::time::Instant) -> SearchResult {
        let took_ms = started.elapsed().as_millis() as u64;
        self.metric_query_count.fetch_add(1, Ordering::Relaxed);
        self.metric_query_total_ms
            .fetch_add(took_ms, Ordering::Relaxed);
        SearchResult {
            hits: vec![],
            total: xerj_query::executor::TotalHits {
                value: 0,
                relation: TotalHitsRelation::Gte,
            },
            took_ms,
            aggs: None,
            timed_out: true,
            profile: None,
            max_score: None,
            script_failure: None,
            savings: None,
        }
    }

    /// Execute a search request against this index.
    /// #1504. Autoindex writes `index.query.default_match_operator: and` on a
    /// logs dataset so an omitted `match` requires every token. The key is
    /// stored the way the create body sent it (a flat dotted key, or nested
    /// under `index.query`). Any other value, including absence, keeps ES's
    /// OR default.
    fn match_operator_defaults_to_and(settings: &Value) -> bool {
        let is_and = |v: &Value| v.as_str().is_some_and(|s| s.eq_ignore_ascii_case("and"));
        if settings
            .pointer("/index/query/default_match_operator")
            .is_some_and(is_and)
        {
            return true;
        }
        [Some(settings), settings.get("index")]
            .into_iter()
            .flatten()
            .any(|container| {
                container
                    .get("index.query.default_match_operator")
                    .is_some_and(is_and)
            })
    }

    pub async fn search(&self, request: &SearchRequest) -> Result<SearchResult> {
        use crate::collection_publication::ReadAdmission;

        let started = std::time::Instant::now();
        let deadline =
            started + std::time::Duration::from_millis(request.timeout_ms.unwrap_or(30_000));
        loop {
            let token = loop {
                let notified = self.collection_publication.notified();
                tokio::pin!(notified);
                notified.as_mut().enable();
                match self.collection_publication.try_admit_reader() {
                    ReadAdmission::Admitted(token) => break token,
                    ReadAdmission::Poisoned => {
                        return Err(collection_publication_interrupted());
                    }
                    // A merge publication holds this bracket across the
                    // version-map repoint. Waiting it out, then failing the
                    // request, is what turned a 30s deadline into minutes:
                    // the HTTP layer maps the error to 500 and a retrying
                    // client spends another deadline on the same bracket.
                    // Elasticsearch answers a missed deadline with HTTP 200
                    // and `timed_out: true`. The hits are empty because
                    // admission never captured a view — `total.relation`
                    // is `gte`, so the page is a bound, not an empty corpus.
                    ReadAdmission::WriterActive => {
                        // Park visibly so the writer, after it drops this
                        // bracket, can keep the next one closed until we
                        // capture (#1761). The guard disarms on timeout and
                        // on the wake.
                        self.collection_publication.arm_reader();
                        let _waiting = ReaderWaitGuard(&self.collection_publication);
                        if tokio::time::timeout_at(
                            tokio::time::Instant::from_std(deadline),
                            notified,
                        )
                        .await
                        .is_err()
                        {
                            return Ok(self.deadline_exhausted_result(started));
                        }
                    }
                }
            };
            // Hold a capture reservation until this attempt returns. The
            // snapshot check inside `search_inner` publishes
            // `note_capture_validated` as soon as the pair is stable, which
            // is what lets the writer open its next bracket while the scan
            // of that snapshot is still running.
            let _capture = ReaderCapture::begin(&self.collection_publication);
            let result = self
                .search_at_generation(request, token.generation(), deadline)
                .await;
            // #1013 — end-of-search validation removed. Demanding that no
            // publication crossed the WHOLE search starved readers under
            // sustained ingest: the flush path holds its publication guard
            // across the entire finalize (drain → segment write → publish),
            // concurrent flushes are allowed, and every document write takes
            // its own bracket, so writer-free intervals covering a full scan
            // stopped existing and `delete_by_query`/search ran to their
            // deadline and returned HTTP 500. The consistency that matters —
            // the segment snapshot and the memtable capture describing ONE
            // world — is now checked at the CAPTURE boundary inside
            // `search_inner`, which needs only a writer-free instant, not a
            // writer-free search. A capture that straddled a publication
            // comes back as the typed retry below.
            match result {
                Err(e) if is_collection_capture_retry(&e) => {
                    if std::time::Instant::now() < deadline {
                        continue;
                    }
                    return Ok(self.deadline_exhausted_result(started));
                }
                other => return other,
            }
        }
    }

    async fn search_at_generation(
        &self,
        request: &SearchRequest,
        publication_generation: u64,
        request_deadline: std::time::Instant,
    ) -> Result<SearchResult> {
        let request_started = std::time::Instant::now();
        let timed_out_result = || {
            let took_ms = request_started.elapsed().as_millis() as u64;
            // Admission and single-flight waits can consume the complete
            // deadline before `search_inner` starts. They are still real
            // queries and must be visible in the same counters as executor
            // timeouts; otherwise overload makes query_count under-report.
            self.metric_query_count.fetch_add(1, Ordering::Relaxed);
            self.metric_query_total_ms
                .fetch_add(took_ms, Ordering::Relaxed);
            SearchResult {
                hits: vec![],
                total: xerj_query::executor::TotalHits {
                    value: 0,
                    relation: TotalHitsRelation::Gte,
                },
                took_ms,
                aggs: None,
                timed_out: true,
                profile: None,
                max_score: None,
                script_failure: None,
                savings: None,
            }
        };
        // #1504: a logs index resolves an omitted match operator to AND
        // before the cache key is hashed, so a cached page cannot be the OR
        // hit list. Indices without the setting keep the request as parsed
        // (Omitted executes as OR). Explicit `"operator": "or"` is untouched.
        let default_match_and = {
            let settings = self.settings.read().await;
            Self::match_operator_defaults_to_and(&settings)
        };
        let rewritten = if default_match_and {
            let mut owned = request.clone();
            xerj_query::apply_default_match_operator(&mut owned, xerj_query::BoolOperator::And);
            Some(owned)
        } else {
            None
        };
        let request = rewritten.as_ref().unwrap_or(request);
        // M3 framework: response cache.  Hash the request shape and the
        // current dataset version; on a hit return the cloned `Arc<SearchResult>`
        // immediately, skipping the semaphore, search_inner, locks, and
        // result construction entirely.  Cache invalidation is via the
        // `dataset_version` counter which bumps on every doc write.
        //
        // Skipped when:
        // - `request.profile == true` (profiling output should always
        //   reflect a fresh execution).
        // - `request.scroll.is_some()` / scroll cursor (stateful).
        // - `request.search_after.is_some()` (cursor-based pagination
        //   could collide with cached state).
        // XERJ_DISABLE_QUERY_CACHE=1 turns off the whole-result cache so a
        // benchmark measures true per-request execution on every call (no
        // took_ms=0 clone). Read once. Normal operation is unaffected.
        let cache_eligible = !request.profile && request.search_after.is_none() && {
            static DISABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
            !*DISABLED.get_or_init(|| {
                matches!(
                    std::env::var("XERJ_DISABLE_QUERY_CACHE").as_deref(),
                    Ok("1") | Ok("true")
                )
            })
        };
        let cache_key: Option<QueryCacheKey> = if cache_eligible {
            // Hash the request via its serde_json representation,
            // streaming the serializer output STRAIGHT INTO the hasher.
            // The previous implementation built a full `String` with
            // `serde_json::to_string` on every request just to hash it —
            // a per-request allocation + copy proportional to the body
            // size that showed up as part of the fixed per-request tax
            // on trivial reads.
            use std::collections::hash_map::DefaultHasher;
            use std::hash::Hasher;
            struct HasherWriter<'a>(&'a mut DefaultHasher);
            impl std::io::Write for HasherWriter<'_> {
                #[inline]
                fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
                    self.0.write(buf);
                    Ok(buf.len())
                }
                #[inline]
                fn flush(&mut self) -> std::io::Result<()> {
                    Ok(())
                }
            }
            let mut h = DefaultHasher::new();
            // `savings` is `serde(skip)`, so it does NOT reach the hasher via
            // the request body — mix it in explicitly. Without this a cached
            // result carries its predecessor's `_savings` record to a caller
            // who asked for a different mode (or asked for none at all, and
            // got a non-ES key on an otherwise stock response). Found on a
            // live server, not in review.
            Hasher::write_u8(
                &mut h,
                match request.savings {
                    SavingsMode::Off => 0,
                    SavingsMode::Sampled => 1,
                    SavingsMode::Exact => 2,
                },
            );
            let body_hash: Option<u64> = serde_json::to_writer(HasherWriter(&mut h), request)
                .ok()
                .map(|_| h.finish());
            // Publication generation isolates cache and single-flight entries
            // produced on opposite sides of any writer interval. The outer
            // reader-token wrapper still validates before returning.
            let dataset_version = self.dataset_version.load(Ordering::Acquire);
            body_hash.map(|body_hash| QueryCacheKey {
                body_hash,
                dataset_version,
                publication_generation,
            })
        } else {
            None
        };
        if let Some(key) = cache_key {
            if let Some(entry) = self.query_cache.get(&key) {
                // Query-cache HIT (RC4-W4 item 4).
                self.query_cache_hits.fetch_add(1, Ordering::Relaxed);
                let mut cloned = (**entry.value()).clone();
                cloned.took_ms = 0;
                self.metric_query_count.fetch_add(1, Ordering::Relaxed);
                return Ok(cloned);
            }
            // Query-cache MISS: eligible + keyed, but not present. The request
            // proceeds to single-flight coalescing / real execution below.
            self.query_cache_misses.fetch_add(1, Ordering::Relaxed);
        }

        // ── Single-flight coalescing ────────────────────────────────────
        // On a `query_cache` miss, coalesce identical concurrent reads: the
        // first request of a `(hash, version)` key becomes the leader and
        // computes below; any identical request that arrives while the
        // leader is still in flight becomes a follower and awaits the
        // leader's published result instead of recomputing. See the
        // `query_inflight` field doc for the correctness argument (the key
        // is identical to the `query_cache` key, so the served result is
        // byte-identical to a cache hit). This removes the redundant
        // recompute CPU exactly in the flush/merge stall window where the
        // open-loop reader piles up same-key requests — the p99 tail.
        //
        // RAII guard: whatever return path the leader takes (success,
        // timed-out partial, or timeout error), the in-flight entry is
        // removed on drop. On the success path the leader also `send`s its
        // result so waiting followers wake immediately; on any other path it
        // publishes nothing, so followers observe the closed channel, re-check
        // the `query_cache`, and otherwise recompute independently.
        struct InflightGuard<'a> {
            map: &'a dashmap::DashMap<
                QueryCacheKey,
                tokio::sync::watch::Sender<Option<Arc<SearchResult>>>,
            >,
            key: QueryCacheKey,
        }
        impl Drop for InflightGuard<'_> {
            fn drop(&mut self) {
                self.map.remove(&self.key);
            }
        }
        fn singleflight_log() -> bool {
            static SF_LOG: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
            *SF_LOG.get_or_init(|| std::env::var("XERJ_SF_LOG").is_ok())
        }

        let mut sf_leader: Option<tokio::sync::watch::Sender<Option<Arc<SearchResult>>>> = None;
        let mut _sf_guard: Option<InflightGuard<'_>> = None;
        if let Some(key) = cache_key {
            use dashmap::mapref::entry::Entry;
            match self.query_inflight.entry(key) {
                Entry::Occupied(o) => {
                    // Follower: subscribe to the leader's result, then release
                    // the shard lock BEFORE awaiting (never hold a DashMap ref
                    // across an await).
                    let mut rx = o.get().subscribe();
                    drop(o);
                    loop {
                        if let Some(r) = rx.borrow_and_update().clone() {
                            let mut cloned = (*r).clone();
                            cloned.took_ms = 0;
                            self.metric_query_count.fetch_add(1, Ordering::Relaxed);
                            self.metric_singleflight_coalesced
                                .fetch_add(1, Ordering::Relaxed);
                            if singleflight_log() {
                                warn!(index = self.name.as_str(), "singleflight follower served");
                            }
                            return Ok(cloned);
                        }
                        match tokio::time::timeout_at(
                            tokio::time::Instant::from_std(request_deadline),
                            rx.changed(),
                        )
                        .await
                        {
                            Err(_) => return Ok(timed_out_result()),
                            Ok(Ok(())) => continue,
                            Ok(Err(_closed)) => {}
                        }
                        {
                            // Leader dropped its sender. If it succeeded it
                            // inserted the result into `query_cache` BEFORE
                            // dropping, so serve that; otherwise recompute.
                            if let Some(entry) = self.query_cache.get(&key) {
                                let mut cloned = (**entry.value()).clone();
                                cloned.took_ms = 0;
                                self.metric_query_count.fetch_add(1, Ordering::Relaxed);
                                self.metric_singleflight_coalesced
                                    .fetch_add(1, Ordering::Relaxed);
                                return Ok(cloned);
                            }
                            break;
                        }
                    }
                }
                Entry::Vacant(v) => {
                    // Leader: publish an empty channel now; identical requests
                    // that arrive during our computation become followers.
                    let (tx, _rx) = tokio::sync::watch::channel(None);
                    v.insert(tx.clone());
                    sf_leader = Some(tx);
                    _sf_guard = Some(InflightGuard {
                        map: &self.query_inflight,
                        key,
                    });
                }
            }
        }

        // Item 2 — global search pool. Acquire a PROCESS-WIDE search permit
        // sized from `limits.max_concurrent_searches` before proceeding. The
        // per-index semaphore below only ever bounded one index (and was a
        // hardcoded 64), so N hot indices could still run N×64 searches at
        // once with no global ceiling. The global permit caps total in-flight
        // searches across every index; excess searches queue on it, exactly
        // like ES's search thread pool bounds active workers. Held (via
        // `_global_permit`) for the whole call; released on drop.
        let _global_permit = match crate::governor::global() {
            Some(g) => match tokio::time::timeout_at(
                tokio::time::Instant::from_std(request_deadline),
                g.acquire_search(),
            )
            .await
            {
                Ok(result) => Some(result?),
                Err(_) => return Ok(timed_out_result()),
            },
            None => None,
        };

        // Acquire a per-index query permit too.  This bounds concurrency
        // against a single index, preventing one hot index from monopolising
        // the global pool.  The permit is automatically released when
        // `_permit` is dropped at the end of this call.
        let _permit = match tokio::time::timeout_at(
            tokio::time::Instant::from_std(request_deadline),
            self.max_concurrent_queries.acquire(),
        )
        .await
        {
            Ok(result) => result.map_err(|_| {
                EngineError::Common(xerj_common::XerjError::internal(
                    "query semaphore closed — index is shutting down",
                ))
            })?,
            Err(_) => return Ok(timed_out_result()),
        };

        let search_start = std::time::Instant::now();

        // Item 1: per-query memory guard (`max_query_memory_mb`). Estimate the
        // hydration cost of the requested result window (from + size hits, each
        // materialised with its `_source` and scoring scratch) and reject
        // up-front with a 429 `circuit_breaking_exception` if it would exceed
        // the budget — before the Vec<Hit> is allocated. This is the
        // request-scoped breaker; the parent (memtable/RSS) breaker is the
        // process-wide one. A no-op when no governor is installed or the
        // budget is 0 (disabled). At the 512 MiB default a full 10 000-hit
        // window (~10 MiB) is nowhere near the cap, so normal search is
        // unaffected; the guard only bites pathological windows or a
        // deliberately low operator budget.
        self.check_result_window(request.from, request.size).await?;

        if let Some(g) = crate::governor::global() {
            if g.query_memory_enabled() {
                // Conservative per-hit estimate: stored source + collector
                // scratch. Deep windows dominate query memory in practice.
                const EST_BYTES_PER_HIT: u64 = 1024;
                let window = (request.from as u64).saturating_add(request.size as u64);
                let est = window.saturating_mul(EST_BYTES_PER_HIT);
                g.check_query_alloc(est, "result-window hydration")
                    .map_err(EngineError::Common)?;
            }
        }

        // Determine the timeout: use the request-level timeout if set, otherwise
        // fall back to the default of 30 seconds.
        let timeout_ms = request.timeout_ms.unwrap_or(30_000);

        // M5.21 — run the CPU-heavy search body inside `block_in_place`
        // on multi-thread runtimes; fall back to plain await on
        // current-thread (used by `#[tokio::test]` default).
        //
        // Pre-M5.21 a concurrent QPS bench collapsed to <1 QPS.  See
        // the commit body for `perf/search-block-in-place` for the
        // full root-cause analysis.
        // Hybrid remains under the M5.21 blocking boundary because it may
        // contain an ordinary lexical child whose generic scan is not yet
        // cooperative. Its vector children still receive the shared absolute
        // deadline and stop at their own checkpoints. Removing the boundary
        // for all hybrid shapes would trade timeout overrun for async-worker
        // starvation on lexical hybrids.
        let cooperative_vector_query = peel_knn_query(&request.query).is_some()
            || peel_multi_knn_query(&request.query).is_some()
            || peel_semantic_query(&request.query).is_some()
            || peel_nested_knn_query(&request.query).is_some();
        let is_multi_thread = tokio::runtime::Handle::current().runtime_flavor()
            == tokio::runtime::RuntimeFlavor::MultiThread;
        // Capture Painless resource-limit faults for the whole search, nested
        // sub-searches and aggregations included. The scoring paths
        // (`apply_function_score`, `apply_rescore`, terms_set
        // `min_should_match`, script-bucketed aggs) return bare values with no
        // error channel, so without this a script that trips the closure
        // call-depth limit degrades to a score of 0.0 and the caller is served
        // a wrong number with nothing to notice. Surfacing it on the result
        // makes the API layer fail the request instead.
        // The same scope also publishes this request's deadline to the script
        // interpreter (issue #122). Every limit the interpreter had bounded a
        // structural property of a script, never its cost, so a flat 38 KiB
        // script of `params.blob;` statements could burn a measured 37.35 s of
        // CPU on ONE document — and the doc-scan timeout poll cannot interrupt
        // that, because it only decides how often a document *boundary* is
        // checked. With the deadline visible
        // inside `eval_painless`, a single evaluation can be abandoned
        // part-way through, and no one document can overshoot the deadline
        // this request was given.
        let search_fut = async {
            let (result, fault) =
                crate::painless::with_script_fault_capture(crate::painless::with_script_deadline(
                    request_deadline,
                    self.search_inner(request, request_deadline),
                ))
                .await;
            match (result, fault) {
                (Ok(mut r), Some(f)) => {
                    // Capture scopes nest, and this one just consumed the
                    // fault. A search running *inside* another request's
                    // capture (a sub-search issued from the `_search` handler,
                    // for instance) would therefore hide the fault from that
                    // outer scope, and its caller may well be one of the many
                    // `if let Ok(result) = idx.search(..)` sites that never
                    // look at `script_failure`. Re-raise so the fault is
                    // surfaced by default and only stops here when this is the
                    // outermost scope.
                    crate::painless::record_script_fault(&f);
                    r.script_failure = Some(f);
                    Ok(r)
                }
                (other, _) => other,
            }
        };
        let search_result = if is_multi_thread && !cooperative_vector_query {
            let fut = async move {
                tokio::task::block_in_place(|| {
                    tokio::runtime::Handle::current().block_on(search_fut)
                })
            };
            tokio::time::timeout_at(tokio::time::Instant::from_std(request_deadline), fut).await
        } else {
            tokio::time::timeout_at(tokio::time::Instant::from_std(request_deadline), search_fut)
                .await
        };
        match search_result {
            Ok(result) => {
                let took_ms = search_start.elapsed().as_millis() as u64;
                // Record metrics.
                self.metric_query_count.fetch_add(1, Ordering::Relaxed);
                self.metric_query_total_ms
                    .fetch_add(took_ms, Ordering::Relaxed);
                // Slow-query observability (tracing warn/error + the operator
                // ring buffer) is emitted once, at the API boundary, via
                // `SlowQueryLog::maybe_record` — RC4-W4 item 3 unified the two
                // so they share the single runtime threshold knob instead of
                // this path's old hardcoded 1s/5s tracing thresholds.
                // Populate the response cache.  Bound the cache to ~1k
                // entries by truncating when it grows; for hot dashboards
                // the working set is far smaller and the cheap O(n)
                // truncate happens once.
                if let (Some(key), Ok(ref r)) = (cache_key, &result) {
                    // Never cache a timed-out partial result — the dataset
                    // version doesn't change on timeout, so a poisoned entry
                    // would be served until the next write. But DO hand it to
                    // any coalesced followers (identical query ⇒ identical
                    // timed-out response) so they return now instead of
                    // waiting for the closed channel and then recomputing an
                    // equally-slow query. The same holds for a script
                    // resource-limit fault: its degraded scores must not be
                    // replayed to later callers, and the fault itself must not
                    // be re-reported against an unrelated request.
                    if r.timed_out || r.script_failure.is_some() {
                        if let Some(tx) = &sf_leader {
                            let _ = tx.send(Some(Arc::new(r.clone())));
                        }
                        return result;
                    }
                    if self.query_cache.len() > 1024 {
                        // Cheap eviction: clear the whole cache rather
                        // than implement LRU.  It rebuilds on the next
                        // few queries.
                        self.query_cache.clear();
                    }
                    // A publisher can fail after the initial admission check
                    // while this query is executing. Never make a result from
                    // that interval reusable after the index becomes poisoned.
                    if self.collection_publication.state().2 {
                        return Err(collection_publication_interrupted());
                    }
                    let arc = Arc::new(r.clone());
                    self.query_cache.insert(key, Arc::clone(&arc));
                    // Single-flight: wake any coalesced followers with the
                    // freshly computed result (byte-identical to this cache
                    // entry). `send` returns Err if there are no followers —
                    // ignored. The `_sf_guard` removes the in-flight entry on
                    // drop. Ordering: cache insert precedes this send, which
                    // precedes the guard's entry removal, so a follower that
                    // races the drop still finds the result in `query_cache`.
                    if let Some(tx) = &sf_leader {
                        let _ = tx.send(Some(arc));
                    }
                }
                result
            }
            Err(_elapsed) => {
                let took_ms = search_start.elapsed().as_millis() as u64;
                self.metric_query_count.fetch_add(1, Ordering::Relaxed);
                self.metric_query_total_ms
                    .fetch_add(took_ms, Ordering::Relaxed);
                warn!(
                    took_ms,
                    timeout_ms,
                    index = self.name.as_str(),
                    "search timed out, returning partial results"
                );
                // Return empty partial results with timed_out=true signaled via
                // a special took_ms value (see es_compat handler).
                let to = SearchResult {
                    hits: vec![],
                    total: xerj_query::executor::TotalHits {
                        value: 0,
                        relation: TotalHitsRelation::Gte,
                    },
                    took_ms,
                    aggs: None,
                    timed_out: true,
                    profile: None,
                    max_score: None,
                    script_failure: None,
                    savings: None,
                };
                // Hand the timed-out response to any coalesced followers so
                // they return immediately rather than waiting for the closed
                // channel and recomputing an equally-slow query. Not cached.
                if let Some(tx) = &sf_leader {
                    let _ = tx.send(Some(Arc::new(to.clone())));
                }
                Ok(to)
            }
        }
    }

    /// Validate a query exactly as [`Index::search`] will build it, without
    /// executing it. One definition of "buildable": the alias and
    /// keyword-full-text rewrites, then the unsearchable-field (#204) and
    /// non-numeric-value (#1284) checks. `_validate/query` uses this so its
    /// `valid` flag cannot disagree with `_search` on the same body.
    pub async fn validate_query(
        &self,
        query: &QueryNode,
    ) -> std::result::Result<(), xerj_common::XerjError> {
        let schema = self.schema.read().await;
        check_buildable_query(query, &schema.schema).map(|_| ())
    }

    /// Inner search implementation (without timeout wrapper).
    async fn search_inner(
        &self,
        request: &SearchRequest,
        search_deadline: std::time::Instant,
    ) -> Result<SearchResult> {
        // #1013 — capture bracket reference. Every collection-state read in
        // this function's capture phase (the leaf-order probes, the early
        // deletes probe, `snap`, `deletes_present`, `mem_doc_count` and the
        // `mem_snapshot` arms) must describe ONE publication world; the check
        // after `mem_snapshot` rejects the whole capture if a publication
        // began or finished (or is still in flight) across it. Reading the
        // reference HERE rather than threading an admission token keeps the
        // recursive callers (hybrid sub-legs) bracketed too.
        let (capture_generation, _, capture_poisoned) = self.collection_publication.state();
        if capture_poisoned {
            return Err(collection_publication_interrupted());
        }
        // Check read block.
        if self.is_read_blocked().await {
            return Err(EngineError::Common(xerj_common::XerjError::index_blocked(
                self.name.as_str(),
                "read",
            )));
        }

        // #396: the memtable brute-scan matcher must see the mapping so
        // `prefix`/`wildcard` apply the same keyword/text folding rules as the
        // segment matcher (buffered answers must not change at flush). Resolved
        // once (owned; the read guard is released immediately, so no re-entrancy
        // with the guards taken later in this function).
        let dmq_schema = self.schema().await;

        // Implicit @timestamp "sort segments on timestamp" handling (see
        // `SearchRequest::leaf_ts_field`).  Two regimes:
        //
        // * SETTLED (empty memtable, ≤1 segment — the read-mostly steady
        //   state): apply NO ordering at all.  A single seq-ordered segment
        //   (the B1 merge invariant) already reads back in arrival order,
        //   which is exactly what real ES 8.13.4 returns on the same
        //   single-segment index — leaf ordering over one leaf is a no-op
        //   there, hits keep `_score` 1.0 and `max_score` 1.0.  The old
        //   injected per-doc sort diverged from ES here on all three axes
        //   (page windows, equal-ts lex re-order, max_score null) —
        //   live-verified.
        //
        // * UNSETTLED (buffered memtable docs, or multiple segments):
        //   xerj's visibility units don't line up with ES's
        //   refresh-generation leaves (a `?refresh=true` doc stays
        //   memtable-resident here but is its own newest-first leaf in ES),
        //   and the final hit ordering ties break by global seq — so
        //   segment-level iteration order can't reproduce ES's leaf order.
        //   Keep the historical injected per-doc `@timestamp desc` sort for
        //   this window — the behaviour the ES conformance contract
        //   (search/380_sort_segments_on_timestamp.yml) validates.
        let leaf_fallback_request: Option<SearchRequest> = match request.leaf_ts_field.as_deref() {
            Some(ts_field)
                if matches!(request.query, QueryNode::MatchAll)
                    && request.sort.is_empty()
                    && (self.memtable.doc_count() > 0
                        || self.store.snapshot().segments.len() > 1) =>
            {
                let mut r = request.clone();
                r.sort = vec![xerj_query::sort::SortField {
                    field: ts_field.to_string(),
                    order: xerj_query::sort::SortOrder::Desc,
                    mode: xerj_query::sort::SortMode::default(),
                    missing: xerj_query::sort::SortMissing::default(),
                    format: None,
                    unmapped_type: None,
                    numeric_type: None,
                }];
                r.leaf_ts_field = None;
                Some(r)
            }
            _ => None,
        };
        let request: &SearchRequest = leaf_fallback_request.as_ref().unwrap_or(request);

        // ── Cooperative deadline ──────────────────────────────────────────
        // The `tokio::time::timeout` wrapper in `search()` is DEAD CODE on
        // the multi-thread runtime: the search body runs inside
        // `block_in_place(block_on(..))`, so the wrapper's first poll only
        // returns when the whole search is already finished — it can never
        // fire mid-flight.  Live-verified during the read-under-write
        // benchmark: 2 118 slow queries (p50 19 s, max 39 s) and ZERO
        // "search timed out" log lines; every piled-up search ran to
        // completion even after its client disconnected, which is what let
        // the backlog snowball keep the CPU pegged for minutes after load
        // stopped.  Instead we compute a wall-clock deadline here and have
        // the O(N) loops below check it cooperatively, returning partial
        // results with `timed_out: true` (ES semantics).
        let mut deadline_exceeded = false;
        // Set when a field-sorted non-match_all scan was narrowed to the
        // per-segment top-cap sort candidates: the scan's own total tally is
        // partial by construction and MUST be replaced by `shortcut_count`
        // post-loop (mirrors `scan_hit_cap` for the unsorted bounded scan).
        let mut sort_candidates_narrowed = false;
        // Slow-query phase attribution (logged for >1 s queries).
        let phase_t0 = std::time::Instant::now();
        let mut phase_marks: Vec<(&'static str, u64)> = Vec::new();
        let mut dbg_segs = 0u32;
        let mut dbg_decode_ms = 0u64;
        let mut dbg_scan_ms = 0u64;
        let mut dbg_fts_ms = 0u64;
        let mut dbg_walked = 0u64;
        let mut dbg_admitted = 0u64;

        // size=0 is valid and means "return no hits but still run aggs / return total".
        let size = request.size;
        let from = request.from;

        self.check_result_window(from, size).await?;

        // Resolve field aliases in the query: rewrite any alias field names to their targets.
        //
        // The unsearchable-field check rides on the same schema guard, and runs
        // AFTER alias resolution so an alias inherits its target's mapping —
        // which is what ES validates. See `unsearchable_query_field`: a field
        // declared `"index": false` with no doc values has neither postings nor
        // a column to scan, and ES fails the query rather than answering it
        // from `_source` (#204 — accepted means honoured).
        let resolved_query = {
            let schema = self.schema.read().await;
            // One definition of "buildable" (alias/keyword rewrites + the
            // unsearchable-field and #1284 numeric checks), shared with
            // `_validate/query`; see `check_buildable_query`.
            let resolved = check_buildable_query(&request.query, &schema.schema)
                .map_err(EngineError::Common)?;
            // #437: a sort field this engine cannot resolve (any of 11 ES
            // meta-field names besides the ones handled below, or an
            // unmapped/misspelled field) fell through to `_source` lookup
            // in `compute_sort_values` and silently returned `null` on
            // every hit — a full-corpus tie that strands `search_after` at
            // page one, HTTP 200, indistinguishable from a correct run.
            // #402 tried to catch this with a request-level allowlist of
            // "known-unresolvable" names and was refuted: xerj permits a
            // metadata-named `_source` key (`{"_seq_no": 1}`), so whether a
            // name resolves is a property of the CORPUS, not of the field
            // name — a static list is guaranteed wrong on some corpus. The
            // schema is the stable thing to check instead, matching what
            // real ES actually validates. Bypass set kept in lockstep with
            // `compute_sort_values`'s own special cases (`_score`/`_doc`/
            // `_id`/`is_meta_sort_field`) — anything else must be declared,
            // via the same recursive dotted-path walk `declared_field`
            // already does for `.keyword` multi-fields and nested/object
            // properties (unlike `Schema::has_field`, which is flat/exact
            // match only and would false-reject both).
            for sf in &request.sort {
                if sf.is_score()
                    || sf.is_doc_order()
                    || sf.field == "_id"
                    || is_meta_sort_field(&sf.field)
                {
                    continue;
                }
                // `unmapped_type` is ES's escape hatch: a sort on an unmapped
                // field carrying it is NOT an error — every doc is treated as
                // missing. Skip the guard so those requests keep working (real
                // ES answers 200, and XERJ's own memory-list issues exactly
                // this against a legacy namespace). #437 / #504 review.
                if sf.unmapped_type.is_none() && declared_field(&schema.schema, &sf.field).is_none()
                {
                    return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                        format!("No mapping found for [{}] in order to sort on", sf.field),
                    )));
                }
            }
            // #328's query half, and it rides the same guard for the same
            // reason: a `dense_vector` has no term dictionary to consult, so a
            // lexical clause naming one is lowered to `match_none` HERE,
            // before `is_doc_scan_query` or `query_node_to_fts` ever see the
            // tree. `unsearchable_query_field` cannot cover it — a vector
            // field is `indexed`, so it is not "unsearchable" — and without
            // the lowering the missing postings hand the clause to the
            // stored-doc scan. See `lower_lexically_typeless_clauses`.
            let typeless = crate::memtable::lexically_typeless_fields(&schema.schema);
            let lowered = if typeless.is_empty() {
                resolved
            } else {
                lower_lexically_typeless_clauses(&resolved, &typeless)
            };
            // #399 — and it belongs HERE for exactly the reason above: every
            // path decision below is made on the SHAPE of this tree, so a
            // `bool` wrapper that ES erases before it builds a `Weight` has to
            // be erased before `is_doc_scan_query` or `query_node_to_fts` can
            // read it. See `unwrap_single_clause_bool`.
            unwrap_single_clause_bool(lowered)
        };
        let query = &resolved_query;
        // #574: resolve each rescore stage's secondary query the same way the
        // main query above (alias-rewrite + keyword→Term). A keyword
        // `match`/`multi_match` in a `rescore.query` otherwise reaches
        // `score_query_against_doc`/`doc_matches_query`, which tokenize `Match`
        // (no schema at that layer), so it would re-score docs matching only a
        // token of the value rather than the whole keyword value. Only the
        // application at the rescore stage below consumes this; the many
        // `request.rescore.is_empty()` presence checks stay on `request` since
        // rewriting never adds or drops a stage.
        let resolved_rescore: Vec<RescoreQuery> = if request.rescore.is_empty() {
            Vec::new()
        } else {
            let schema = self.schema.read().await;
            request
                .rescore
                .iter()
                .map(|rs| rewrite_rescore_keyword(rs, &schema.schema))
                .collect()
        };

        // ── KNN short-circuit ──────────────────────────────────────────────────
        // Vector-only queries (top-level `knn`) bypass the FTS / doc-scan
        // path entirely: we iterate every doc, compute the configured
        // similarity against the query vector, and return the top-k by
        // similarity. This runs against both memtable and segments so
        // refreshed + flushed + merged indexes all work.
        //
        // The mapping's declared `similarity` (cosine | dot_product |
        // max_inner_product | l2_norm) is looked up via self.schema —
        // the es_compat mapper propagates it into FieldOptions.similarity
        // at index-create time. Default is cosine when unspecified.
        //
        // A Knn filter (sub-query) is applied as a doc_matches_query
        // pre-filter before the top-k extraction so filter semantics
        // match ES.
        //
        // Unfiltered top-level knn first attempts the HNSW ANN path
        // (`run_knn_hnsw`), which exact-rescores its ≤k candidates so
        // `_score`s stay byte-identical to brute force; ANY ineligibility
        // (field not pinned to the graph, stale snapshot, partial coverage,
        // non-cosine, SQ8, small index, fetch race, …) falls back to the
        // exact brute-force scan below. Filtered knn stays exact brute
        // force with a pre-filter, where `num_candidates` (the ANN fan-out)
        // has no effect.
        if passage_requested(request)
            && (peel_multi_knn_query(query).is_some() || peel_hybrid_query(query).is_some())
        {
            return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                "`fields: [\"_passage\"]` requires one semantic or kNN clause; \
                     multi-kNN and hybrid queries combine independent score contributions, \
                     so they do not have one unambiguous winning passage; request `_passage` \
                     only with a single semantic/kNN clause, or omit `_passage` for fusion",
            )));
        }
        if let Some(peeled) = peel_knn_query(query) {
            let PeeledKnn {
                field,
                vector: query_vec,
                k,
                num_candidates,
                filter: filter_opt,
                boost,
                similarity: min_similarity,
            } = peeled;
            let similarity = {
                let schema = self.schema.read().await;
                lookup_vector_similarity(&schema.schema, &field)
            };
            // The HNSW ANN path serves only the PLAIN case: no filter, no
            // boost, no similarity cutoff. Boost/cutoff requests go exact
            // brute force where both are applied in the right order
            // (cutoff on the unboosted transformed score, then boost).
            //
            // rc.6: an `aggs`-bearing knn also takes the exact brute-force
            // path. ANN recall is <100%, so the retrieved top-k neighbour
            // SET can differ slightly from exact; aggregations over that set
            // must be exact (analytics counts, not ranked hits), so we do not
            // let ANN approximation leak into agg buckets.
            let plain = filter_opt.is_none()
                && boost.is_none()
                && min_similarity.is_none()
                && request.aggs.is_none();
            let hnsw = if plain {
                Box::pin(self.run_knn_hnsw(
                    request,
                    search_deadline,
                    &field,
                    &query_vec,
                    k,
                    num_candidates,
                    &similarity,
                ))
                .await
            } else {
                None
            };
            let result = match hnsw {
                Some(result) => result,
                None => {
                    Box::pin(self.run_knn_brute_force_with_deadline(
                        request,
                        search_deadline,
                        &field,
                        &query_vec,
                        k,
                        filter_opt,
                        &similarity,
                        boost,
                        min_similarity,
                    ))
                    .await?
                }
            };
            // #498: a knn naming a field the index cannot answer must fail with a
            // 400, not return a silent empty 200. Checked only on a genuinely
            // empty, non-timed-out result, so the hot path is untouched and a
            // declared-but-empty (or indexed-but-undeclared) vector field still
            // returns its real empty result.
            if result.hits.is_empty() && !result.timed_out {
                self.reject_unanswerable_knn_field(&field).await?;
            }
            return Ok(result);
        }
        // PURE multi-KNN (the ES `knn: [...]` array form): every clause runs
        // its own exact top-k, scores are SUMMED for docs found by more than
        // one clause, and `hits.total` is the size of the deduplicated union
        // — matching ES 8.13 multi-kNN semantics (live-verified 2026-07-12).
        if let Some(clauses) = peel_multi_knn_query(query) {
            let fields: Vec<String> = clauses.iter().map(|c| c.field.clone()).collect();
            let result =
                Box::pin(self.run_multi_knn_brute_force(request, search_deadline, clauses)).await?;
            // #542: each knn clause validates its own field. On an empty,
            // non-timed-out union, reject the first clause naming an
            // unanswerable field — the same execution-truth check the single-knn
            // arm uses (#498), so declared-but-empty and indexed-but-undeclared
            // fields still return their real empty result.
            if result.hits.is_empty() && !result.timed_out {
                for field in &fields {
                    self.reject_unanswerable_knn_field(field).await?;
                }
            }
            return Ok(result);
        }
        // Nested `knn` query: `nested { path: P, query: { knn { field: P.vec } } }`.
        // ES scores each parent by the best-matching nested element and
        // returns parents in similarity-descending order. We implement
        // the same by flattening the nested array per parent doc and
        // taking the max score across elements.
        if let Some((
            nested_path,
            field,
            query_vec,
            k,
            num_candidates_opt,
            pre_filter,
            post_filter,
        )) = peel_nested_knn_query(query)
        {
            let similarity = {
                let schema = self.schema.read().await;
                lookup_vector_similarity(&schema.schema, &field)
            };
            // ES semantics: `num_candidates` caps how many docs the vector
            // search returns before the outer bool.must clauses post-filter.
            // It defaults to `k` when omitted and is clamped to `>= k` (a
            // smaller fan-out than the requested top-k makes no sense).
            let num_candidates = num_candidates_opt.unwrap_or(k).max(k);
            let result = self
                .run_nested_knn_brute_force_with_deadline(
                    request,
                    search_deadline,
                    &nested_path,
                    &field,
                    &query_vec,
                    k,
                    num_candidates,
                    pre_filter,
                    post_filter,
                    &similarity,
                )
                .await?;
            // #542: a nested knn naming a field the index cannot answer must
            // 400, not return a silent empty 200. Checked only on a genuinely
            // empty, non-timed-out result, so the hot path and declared-but-
            // empty / indexed-but-undeclared nested fields are untouched.
            if result.hits.is_empty() && !result.timed_out {
                self.reject_unanswerable_nested_knn_field(&nested_path, &field)
                    .await?;
            }
            return Ok(result);
        }

        // ── Semantic search short-circuit ─────────────────────────────────────
        // v0.7-P2: pre-v0.7 the parser accepted `semantic` queries but
        // the executor had no arm for QueryNode::SemanticSearch — every
        // semantic request crashed at runtime. Fix: embed the query
        // text via the configured EmbeddingProxy, then run the existing
        // kNN brute-force path with the embedded vector.
        //
        // Failure modes (all surfaced as proper errors, not crashes):
        //  - no proxy configured → 400 with config hint
        //  - proxy timeout / 5xx → propagate the proxy's error
        //  - dim mismatch         → caught by run_knn_brute_force / HNSW
        if let Some((field, text, k, filter)) = peel_semantic_query(query) {
            return self
                .run_semantic_with_deadline(request, search_deadline, &field, &text, k, filter)
                .await;
        }

        // ── Hybrid (RRF / Linear / Learned) short-circuit ─────────────────────
        // v0.7-P1: pre-v0.7 the parser accepted `hybrid` queries but the
        // executor had no arm for QueryNode::Hybrid — every hybrid request
        // crashed at runtime. Fix is to recursively run each sub-query as
        // its own search, then combine the result lists via the chosen
        // fusion strategy.
        //
        // RRF (default, k=60): each doc's combined score is
        //   Σ_i  weight_i / (k_rrf + rank_i_in_list_i)
        // where rank is 1-based. Docs missing from a list contribute 0
        // for that list. This is the same formula ES / OpenSearch use
        // and is robust to score-scale differences between BM25 and
        // vector similarity.
        //
        // Linear: each doc's combined score is
        //   Σ_i  weight_i * normalised_score_i
        // where normalised_score is min-max normalised to [0,1] within
        // each sub-list. Cheaper than RRF and lets callers bias toward
        // one signal, but sensitive to score-scale outliers.
        //
        // Learned: not yet implemented — falls back to RRF with a warn.
        if let Some((sub_queries, fusion)) = peel_hybrid_query(query) {
            return self
                .run_hybrid_with_deadline(request, search_deadline, sub_queries, fusion)
                .await;
        }

        // ── #943: a `hybrid` the ladder above declined is about to be
        // silently dropped ──────────────────────────────────────────────────
        // Every hybrid-aware peel has passed by now, so a Hybrid node still
        // in the tree is heading for the generic path, where the doc
        // matcher's catch-all (`_ => false`) makes the clause match nothing:
        // `bool{must:[hybrid, …]}`, a hybrid beside a must_not, dis_max over
        // a hybrid … all answered 200 with 0 hits (or with the non-hybrid
        // clauses' hits and the hybrid silently dropped). Fail loud with a
        // 400 naming the supported spellings, mirroring the `_passage` guard
        // above and the aggs-beside-hybrid rejection in
        // `run_hybrid_with_deadline`. `unwrap_single_clause_bool` has already
        // erased the harmless one-clause wrappers, so this only fires on
        // shapes that genuinely cannot execute.
        if query.contains_hybrid() {
            return Err(EngineError::Common(xerj_common::XerjError::invalid_query(
                "hybrid queries are supported at the top level or as \
                 bool{must: [hybrid], filter: […]} (the filter clauses are pushed \
                 into every leg); this query nests a hybrid where it cannot be \
                 executed and would silently match nothing — put the filter inside \
                 each leg of hybrid.queries, or move the hybrid to the top level",
            )));
        }

        // ── #825: `knn` clause inside a compound `bool` ────────────────────────
        // Every vector-aware short-circuit above has declined by now, so a
        // `Knn` node still in the tree is about to hit the generic path,
        // where it matches nothing and scores 0.0 (silent drop). The ES 8.x
        // canonical hybrid — a top-level `knn` beside a `query`, folded by
        // the compat layer into exactly this `bool.should` — lands here for
        // EVERY request since the #458 hybrid_safe fold was retired, and
        // previously landed here whenever aggs/sort/collapse/rescore/… were
        // present. Pre-execute the knn leg and splice its top-k back in as
        // pinned per-document constants; the generic path then serves the
        // union with summed scores and full feature support (see
        // `pin_knn_clause`).
        //
        // `pinned_knn_scores` is the id → knn-score map of the clauses we
        // just spliced in. Everything downstream that RE-WRITES `_score`
        // rather than reading it has to add the vector half back, or the
        // sum contract is lost exactly where it was hardest to see — see
        // the IDF heuristic rescore further down.
        let mut pinned_knn_scores: HashMap<String, f32> = HashMap::new();
        let pinned_query = if let Some(knn_clause) = compound_bool_direct_knn(query) {
            let pinned = self
                .pin_knn_clause(request, search_deadline, knn_clause)
                .await?;
            collect_pinned_knn_scores(&pinned, &mut pinned_knn_scores);
            Some(replace_direct_knn_with_pinned(query, &pinned))
        } else {
            None
        };
        let query = pinned_query.as_ref().unwrap_or(query);

        // Fetch limit is the per-sub-source materialisation cap.  We materialise
        // at most (from + size + 100) hits with their sources, and count the
        // rest as `total` without buffering them.  This keeps query memory
        // O(from + size) regardless of how many documents match.
        //
        // Historical behaviour with `track_total_hits=true` bumped this to 10M
        // and caused OOM kills on match_all queries over segment-heavy indices
        // — see CAPPED_RAM_BATTLE_2026-04-13.md.  The new contract is: count
        // accurately but **only materialise what pagination needs**.
        let materialisation_limit: usize = (from + size + 100).max(256);
        // For the memtable search that already knows how to rank a hit list,
        // we still need a hint for top-k; use the materialisation limit.
        let fetch_limit: usize = materialisation_limit;

        // Columnar function_score fast-path probe (borrows `query`). `Some` iff
        // the request is exactly `function_score { match_all, field_value_factor }`
        // on a plain size>0 page — see `function_score_fast_fvf`.
        let fs_fast_fvf: Option<&FieldValueFactor> = function_score_fast_fvf(query, request, size);

        // Determine whether we need hit *sources* at all.
        // - size > 0          → sources for hits output
        // - rescore           → mutates source after collection
        // - collapse          → needs source field
        // - sort on a field   → needs source
        // - aggs without DV fast path → needs sources
        // When none of these apply (classic `size:0 + match_all + track_total_hits`
        // counting query), we skip materialisation entirely and just count.
        //
        // `highlight` is deliberately NOT in this list (#177): it is a pure
        // post-pass over the rendered page (`apply_highlight`), so at `size: 0`
        // — where there is no page — it has nothing to do, and a `size: 0` body
        // must execute identically with and without it.
        //
        // `min_score` IS in this list (#193): the threshold applies to FINAL
        // scores, so a `size:0 + min_score` count must score its matches
        // exactly like `size:N` does — count-only mode would close the
        // index-wide stats gate below (per-arm scores; a different threshold
        // scale than the size:N page, user-visible since #192) and skip
        // materialisation entirely, leaving the post-collection min_score
        // filter nothing to subtract, i.e. a total that ignores the
        // threshold.  Same call ES makes: `QueryPhaseCollector` refuses the
        // `Weight#count` shortcut whenever min_score is set and collects
        // only docs with `scorer.score() >= minScore` (approach only,
        // QueryPhaseCollector.java:77-79,123 — no code copied).
        let need_hits_output: bool = size > 0;
        let need_sources_for_post: bool = need_hits_output
            || !request.rescore.is_empty()
            || request.collapse.is_some()
            || request
                .sort
                .iter()
                .any(|sf| !sf.is_score() && !sf.is_doc_order())
            || request.aggs.is_some()
            || request.min_score.is_some();
        let count_only: bool = !need_sources_for_post;

        // #1019 — ids-only projection eligibility. `request.ids_only` is set
        // solely by engine-controlled callers (the `_delete_by_query` runner
        // and the engine-level purge loop); `parse_request` can never produce
        // it, so it cannot arrive from the wire. It is honoured only when the
        // request provably needs nothing beyond hit ids: sort keys confined
        // to `_id`/`_doc` (a real field sort or a `_score` ordering would
        // have to read `_source` — via `compute_sort_values` or the per-doc
        // scorer — to rank), and none of the page post-passes that consume
        // sources (`fields` / `script_fields` / `highlight` / `explain` /
        // `collapse` / `rescore` / `aggs` / `min_score`). Any other shape
        // silently degrades to a full request — correctness first. The
        // non-empty-sort requirement also means the columnar
        // `scored_columnar` path (whose `scored_fast_plan` gate demands an
        // EMPTY sort and no `search_after`) is unreachable in ids-only mode,
        // so its Phase-5 hydration needs no branch of its own.
        let ids_only: bool = request.ids_only
            && !request.sort.is_empty()
            && request
                .sort
                .iter()
                .all(|sf| sf.field == "_id" || sf.is_doc_order())
            && request.fields.is_empty()
            && request.script_fields.is_none()
            && request.highlight.is_none()
            && !request.explain
            && request.collapse.is_none()
            && request.rescore.is_empty()
            && request.aggs.is_none()
            && request.min_score.is_none();

        // --- Memtable search ---
        // `all_hits` is the bounded collector of fully-hydrated hits (source +
        // score).  Capacity is `materialisation_limit`; anything beyond that
        // only contributes to `total_count`.  `total_count` is the EXACT
        // number of matching documents — used for `track_total_hits=true`.
        let mut all_hits: Vec<Hit> = Vec::new();
        let mut total_count: u64 = 0;
        // O(1) dedup: tracks doc IDs already added to all_hits.
        let mut seen_ids: HashSet<String> = HashSet::new();

        // ── Global top-(from+size) sorted collector ───────────────────────
        // When the request sorts on a real field (not just `_score` / `_doc`)
        // and asks for hits (`size > 0`), the arrival-order `materialisation_limit`
        // cap on `all_hits` would truncate to the first ~256 docs *in scan
        // order* and then sort only those — returning a wrong subset once total
        // matches exceed the cap.  Instead we route every admitted hit through
        // a bounded max-heap (`SortTopK`) keyed by the final sort order, so the
        // survivors are the true GLOBAL top-(from+size).  `all_hits` is left
        // empty on this path; the heap is drained into `final_hits` after the
        // segment loop.  `total_count` is tallied independently and stays exact.
        let field_sort_active: bool = size > 0
            && request
                .sort
                .iter()
                .any(|sf| !sf.is_score() && !sf.is_doc_order());

        // ── search_after cursor, normalized ONCE up front ─────────────────
        // Date-shaped cursor strings are converted to epoch numbers here so
        // BOTH the bounded sorted collector (pre-heap rejection during
        // collection) and the legacy post-collection filter compare against
        // the same shape the hits' `sort` arrays use (`compute_sort_values`
        // emits epoch numbers for date-shaped strings).  Users may supply
        // either the raw epoch number (`search_after: [1571646604828]`) or a
        // formatted date string (`search_after: ["2019-10-21 08:30:04.828"]`);
        // ES accepts both.
        let after_norm: Option<Vec<Value>> = match &request.search_after {
            Some(vals) if !vals.is_empty() => Some(
                vals.iter()
                    .enumerate()
                    .map(|(i, v)| {
                        let sf = request.sort.get(i);
                        let fmt = sf.and_then(|s| s.format.as_deref());
                        // The cursor is compared against `compute_sort_values`
                        // output, so it must be normalised on the SAME field
                        // scale those keys use (#790).
                        let scale = sf
                            .map(|s| self.date_scale_for_sort(s))
                            .unwrap_or(DateScale::PerValue);
                        normalize_search_after_value(v, fmt, scale)
                    })
                    .collect(),
            ),
            _ => None,
        };

        // Determine text fields once outside the segment loop to avoid
        // re-acquiring the schema read lock on every segment iteration.
        //
        // `exact_fields` mirrors `build_fts_field_configs`: every non-Text
        // schema field (keyword / numeric / date / bool / ip) is FTS-indexed
        // with the `keyword` analyzer — the WHOLE value is one case-preserved
        // token.  The query side (query_node_to_fts) must therefore look
        // these fields up by whole value, never by standard-analyzer tokens:
        // a token like "claude" can never match the keyword term
        // "claude-haiku-4-5", which made multi_match / query_string /
        // simple_query_string return 0 hits on keyword-only mappings.
        // `kw_fields` / `num_fields` / `bool_fields` are the schema-typed
        // field sets the scored-family fast-path gate needs: `exact_fields`
        // alone can't prove "keyword" (it also holds numerics/dates/bools),
        // and Text fields must NEVER enter the columnar scorer (they get
        // Keyword dv columns but ES analyzes them).
        let (text_fields, exact_fields, kw_fields, num_fields, bool_fields): (
            Vec<String>,
            std::collections::HashSet<String>,
            std::collections::HashSet<String>,
            std::collections::HashSet<String>,
            std::collections::HashSet<String>,
        ) = {
            let schema_guard = self.schema.read().await;
            let mut tf: Vec<String> = Vec::new();
            let mut ef: std::collections::HashSet<String> = std::collections::HashSet::new();
            let mut kw: std::collections::HashSet<String> = std::collections::HashSet::new();
            let mut num: std::collections::HashSet<String> = std::collections::HashSet::new();
            let mut bf: std::collections::HashSet<String> = std::collections::HashSet::new();
            for f in &schema_guard.schema.fields {
                // These sets are the field-less expansion: what a bare
                // `query_string` / `simple_query_string` / `multi_match` on
                // `*` projects a clause onto. ES expands `*` over SEARCHABLE
                // fields only (`MappedFieldType.isSearchable()` = has terms OR
                // has doc values), so a field declared `"index": false` with no
                // doc values must not appear here — otherwise the projected
                // clause falls through the per-segment `fts_has_field` gate
                // onto the stored-doc scan and matches the field's `_source`
                // text, which is the accepted-and-ignored bug wearing a
                // different hat (#204). A named query on the same field is
                // rejected outright by `unsearchable_query_field`; this is the
                // implicit-expansion half of the same rule.
                //
                // `index: false` WITH doc values stays in: ES calls it
                // searchable and answers it from the column (8.1 doc-values
                // search). We answer it exactly too — see
                // `memtable::fts_excluded_fields` for why such a field keeps
                // its postings rather than falling back to the scan.
                if !f.options.indexed && !f.options.doc_values {
                    continue;
                }
                // #328 — a `dense_vector` has no lexical representation at
                // all, so it is not a field a `*` expansion may project onto.
                // A vector field is declared with vector attributes and
                // nothing else, so it never acquires index options and can
                // never own terms (`lucene/core/src/java/org/apache/lucene/
                // document/KnnFloatVectorField.java:70`, and `FieldInfo.java:565`
                // for what `IndexOptions.NONE` means). Leaving it in would push
                // a clause onto a field whose term dictionary this release
                // stops building (`memtable::fts_excluded_fields`), and the
                // per-segment `fts_has_field` gate would then hand the whole
                // query to the stored-doc scan. A clause that NAMES the field
                // rather than expanding onto it is handled separately, by
                // `lower_lexically_typeless_clauses`.
                if matches!(f.field_type, FieldType::Vector) {
                    continue;
                }
                if matches!(f.field_type, FieldType::Text) {
                    tf.push(f.name.clone());
                } else {
                    ef.insert(f.name.clone());
                }
                match f.field_type {
                    FieldType::Keyword => {
                        kw.insert(f.name.clone());
                    }
                    FieldType::Long | FieldType::Double => {
                        num.insert(f.name.clone());
                    }
                    FieldType::Boolean => {
                        bf.insert(f.name.clone());
                    }
                    _ => {}
                }
            }
            (tf, ef, kw, num, bf)
        };
        // #1359: `query_node_to_fts_projected` projects a `QueryNode::Term` on a
        // `FieldType::Keyword` field into `FtsQuery::Term` so a `bool` or
        // `dis_max` combining a text clause and a keyword `term` clause does
        // not `?`-abort FTS projection on the keyword child. A standalone
        // top-level `term` on a keyword field, however, is served by
        // `scored_columnar` when `mem_doc_count == 0` and by the doc-values
        // prefilter + stored scan (where memtable `DocValuesHits` and segment
        // `score_doc` both assign constant score `1.0`) when `mem_doc_count > 0`
        // or columnar bails. Routing a top-level keyword `term` into segment FTS
        // gave segment hits BM25 (~0.00147) while memtable `DocValuesHits` gave
        // `1.0` — so `seg_can_enter` rejected every flushed segment against a
        // full memtable collector (`size:1` returned `mem000` over `seg0000`)
        // and `query_needs_fts` flipped true on a `term`-on-keyword query.
        let empty_kw_fields: std::collections::HashSet<String> = std::collections::HashSet::new();
        let fts_kw_fields: &std::collections::HashSet<String> = {
            let mut q = query;
            loop {
                match q {
                    QueryNode::Constant { query, .. }
                    | QueryNode::Boosted { query, .. }
                    | QueryNode::Named { query, .. } => q = query,
                    other => {
                        break if matches!(other, QueryNode::Term { .. }) {
                            &empty_kw_fields
                        } else {
                            &kw_fields
                        };
                    }
                }
            }
        };

        // ── B3: peeled function_score for the brute path ──────────────────
        // The single scoring clause of the request when it is a (wrapped)
        // function_score — the brute scan's per-doc scorer (`score_doc`)
        // composes it exactly once, and the post-loop then only validates.
        let peeled_fs: Option<(&QueryNode, f32)> = peel_function_score_boosted(query);
        // Early deletes probe (own snapshot): decides whether the gated
        // columnar fs path CAN run below, which in turn decides whether the
        // brute score-ranked collector must own the hits instead.
        let fs_deletes_early: bool = peeled_fs.is_some()
            && (self
                .store
                .snapshot()
                .segments
                .iter()
                .any(|m| m.has_tombstones)
                || self.store.version_map.ghost_events() > 0);
        // Brute function_score requests (any shape the columnar gate below
        // won't serve: aggs/min_score/explain/max_boost/weight/filter/
        // boost≠1/non-match_all inner/score-asc sort/deletes-present) route
        // hits through a bounded top-k heap keyed on the FINAL score.  The
        // arrival-order `all_hits` cap used to keep the first ~cap matches
        // in scan order — on a >cap corpus the returned "top-k" wasn't the
        // top-k at all (2026-07-10 scorecard, B3).
        let fs_topk_active: bool = peeled_fs.is_some()
            && size > 0
            && !field_sort_active
            && request.search_after.is_none()
            && request
                .sort
                .iter()
                .all(|sf| sf.is_score() || sf.is_doc_order())
            && (fs_fast_fvf.is_none() || fs_deletes_early);

        let mut sort_topk: Option<SortTopK> = if field_sort_active {
            Some(SortTopK::new(
                Arc::new(request.sort.clone()),
                materialisation_limit,
                // The cursor is applied DURING collection: the collector
                // admits only hits strictly after it, so deep cursors cost
                // the same as page 1 and are correct past the
                // materialisation cap.
                after_norm.clone(),
            ))
        } else if fs_topk_active {
            // Score-keyed global top-k for the brute function_score path.
            // An explicit all-`_score` sort (e.g. `[{"_score":"asc"}]`)
            // keeps its requested order; the default is score-descending.
            let keys: Vec<xerj_query::sort::SortField> = if request.sort.is_empty() {
                vec![xerj_query::sort::SortField::score_desc()]
            } else {
                request.sort.clone()
            };
            Some(SortTopK::new(Arc::new(keys), materialisation_limit, None))
        } else {
            None
        };

        // Exact `hits.total` under `min_score`: ES counts only docs whose
        // FINAL score clears the threshold.  The score-ranked fs scan
        // visits and scores EVERY match, so the per-doc scorer tallies
        // passers here and the post-loop overwrites `total_count` with it.
        let fs_min_tally: Option<f64> = if fs_topk_active {
            request.min_score
        } else {
            None
        };
        let fs_min_passed = std::sync::atomic::AtomicU64::new(0);
        // Population max over every score the brute scorer computes.  Under
        // a field sort only ~page hits survive the heap, but ES's
        // `track_scores: true` max_score is the max over ALL matches — the
        // scan scores every match, so this accumulator sees it (f32 bits:
        // for non-negative IEEE floats, integer max == float max).
        let scored_max_bits = std::sync::atomic::AtomicU32::new(0);

        // Whether the query tree can read `_id` from the scored source
        // (an `ids` clause anywhere).  Stored segment sources don't carry
        // `_id`, so scoring must inject it exactly like the match check
        // does — without this, `ids` hits scored 0.0 where ES returns the
        // constant 1.0 (2026-07-10 scorecard, B1).  Serialized-form probe,
        // computed ONCE per query (mirrors the memtable DocsForScan arm).
        let query_may_read_id: bool = serde_json::to_string(query)
            .map(|s| s.contains("_id") || s.contains("Ids") || s.contains("ids"))
            .unwrap_or(true);

        // Constant BM25 base score when the scoring surface (the peeled
        // function_score's inner query, or the whole query) is a single
        // keyword/bool/numeric leaf — the exact ES score `scored_columnar`
        // would compute, made available to the brute per-doc scorer for
        // shapes the columnar executor doesn't serve (field sorts,
        // track_scores, function_score inners).
        let leaf_base_const: Option<f32> = {
            let score_target: &QueryNode = match peeled_fs {
                Some((QueryNode::FunctionScore { query: inner, .. }, _)) => inner.as_ref(),
                _ => query,
            };
            self.leaf_constant_score(score_target, &kw_fields, &num_fields, &bool_fields)
        };

        // ── Per-doc brute scorer ──────────────────────────────────────────
        // THE scoring entry point for every brute scan path (memtable
        // doc-scan + all three segment scan loops).  Composes a peeled
        // function_score exactly once with full ES semantics:
        //   base = inner-query score × outer boost (Lucene propagates the
        //   query-level boost into the SUBQUERY weight — `_explain` shows
        //   `*:*^3.0` = 3.0 as the base branch) → per-function
        //   weight/filter → score_mode → max_boost cap on the function
        //   score → boost_mode combine(base, fn).  Live-verified on ES
        //   8.13.4 (`boost:3`, fvf(rank=5)): multiply 15, sum 8, avg 4,
        //   max 5, min 3, replace 5 (boost inert when base is discarded)
        //   — NOT `combine(...) × boost`, which is only equivalent for
        //   boost_mode=multiply.
        // Callers only score docs that already MATCHED the query, so the
        // leaf constant applies unconditionally when present.
        let score_doc = |source: &Value, id: &str| -> f32 {
            let injected: Option<Value> = if query_may_read_id && source.get("_id").is_none() {
                source.as_object().map(|obj| {
                    let mut o = obj.clone();
                    o.insert("_id".to_string(), Value::String(id.to_string()));
                    Value::Object(o)
                })
            } else {
                None
            };
            let src: &Value = injected.as_ref().unwrap_or(source);
            let score = if let Some((fs_node, outer_boost)) = peeled_fs {
                if let QueryNode::FunctionScore {
                    query: inner,
                    functions,
                    score_mode,
                    boost_mode,
                    max_boost,
                } = fs_node
                {
                    let base = leaf_base_const
                        .unwrap_or_else(|| score_query_against_doc(inner, src, &dmq_schema))
                        * outer_boost;
                    let mut fn_score =
                        apply_function_score(id, src, functions, *score_mode, base, &dmq_schema);
                    if let Some(cap) = max_boost {
                        fn_score = fn_score.min(*cap);
                    }
                    combine_scores(base, fn_score, *boost_mode)
                } else {
                    score_query_against_doc(query, src, &dmq_schema)
                }
            } else {
                leaf_base_const.unwrap_or_else(|| score_query_against_doc(query, src, &dmq_schema))
            };
            if let Some(min) = fs_min_tally {
                if score.is_finite() && f64::from(score) >= min {
                    fs_min_passed.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
            }
            if score > 0.0 && score.is_finite() {
                scored_max_bits.fetch_max(score.to_bits(), std::sync::atomic::Ordering::Relaxed);
            }
            score
        };
        let score_doc: &(dyn Fn(&Value, &str) -> f32 + Send + Sync) = &score_doc;

        // Helper: admit a hit into the bounded `all_hits` collector.
        //
        // Contract:
        // - Every call increments `total_count` (exact match count).
        // - If `count_only` is true, we do NOT materialise the hit at all.
        // - Otherwise we admit up to `materialisation_limit` hits and then
        //   silently drop the rest.  `max_result_window` (default 10 000)
        //   already prevents pagination from asking for more than that, so
        //   dropping beyond the cap is safe for the user-visible window.
        //
        // Dedup: `seen_ids` guards against the same doc appearing in both the
        // memtable and a segment (possible during a flush race).  We prefer
        // the first appearance (which is usually the memtable, i.e. the
        // newest version).
        //
        // #191 — the `materialisation_limit` bound here is a plain FIFO cut,
        // and it is only CORRECT because every arm that feeds it upholds one
        // of two invariants:
        //
        //   * `AllDocIds` / `DocValuesHits` — the memtable already narrowed
        //     its candidates to the globally best `limit` by `(seq_no, _id)`
        //     (`ShardedFtsMemtable::narrow_to_page`), so the FIFO never
        //     truncates at all; and
        //   * `FtsHits` — the memtable returns its hits already sorted by the
        //     full page key (`sort_hits_by_page_key`), so the first `limit`
        //     ARE the page.  This matters on the ghost-window path, which asks
        //     the memtable for every hit rather than a bounded prefix.
        //
        // The brute-scan arm upholds neither (it walks shards in index order),
        // so it does NOT route post-cap admissions through here — see the
        // `DocsForScan` arm.  Before #191 the FIFO was applied to unordered
        // input and the surviving tied documents were decided by shard-walk
        // order: `size:5` and `size:1000` disagreed on a 600-document
        // all-tied memtable.
        macro_rules! admit_hit {
            ($hit:expr) => {{
                total_count += 1;
                if !count_only {
                    let mut hit: Hit = $hit;
                    if let Some(topk) = sort_topk.as_mut() {
                        // Field-sorted: offer to the bounded top-N heap.  A hit
                        // admitted source-less (memtable FTS / id-only paths)
                        // gets its `_source` filled from the memtable so the
                        // sort key can be computed now — the heap must rank on
                        // the real key, not on a deferred/Null source.
                        if !seen_ids.contains(&hit.id) {
                            if hit.source.is_null() {
                                if let Some(src) = self.memtable.get_doc_source_as_value(&hit.id) {
                                    hit.source = src;
                                }
                                // Resolved at the SAME moment as the deferred
                                // `source` above, not a later pass (#440).
                                if let Some(ver) = self.store.version_map.get(&hit.id) {
                                    let (seq_no, version) = self.hit_seq_version(&hit.id, &ver);
                                    hit.seq_no = seq_no;
                                    hit.version = version;
                                }
                            }
                            seen_ids.insert(hit.id.clone());
                            let seq = hit.seq_no.unwrap_or(u64::MAX);
                            topk.offer(hit, seq, self);
                        }
                    } else if all_hits.len() < materialisation_limit && !seen_ids.contains(&hit.id)
                    {
                        seen_ids.insert(hit.id.clone());
                        all_hits.push(hit);
                    }
                    // else: bound hit or duplicate — already counted.
                }
            }};
            // Count-only variant: increments total without allocating a Hit.
            (count $id:expr) => {{
                total_count += 1;
                if !count_only {
                    if let Some(topk) = sort_topk.as_mut() {
                        let id: String = $id;
                        if !seen_ids.contains(&id) {
                            // Pre-clone primary-key rejection: resolve the
                            // buffered source as a SHARED Arc (lookup only)
                            // and, once the heap is full, drop docs whose
                            // primary sort key is strictly worse than the
                            // heap's worst BEFORE paying the deep source
                            // clone + `seen_ids` insert + full `offer`.
                            // Ties / underivable keys are conservatively
                            // admitted; the doc was already counted above
                            // either way.  This bounds the O(memtable)
                            // field-sorted walk (match_all/range under the
                            // implicit @timestamp index sort) that was
                            // ~1 s per query against a ~1 M-doc memtable.
                            let src_arc = self.memtable.get_doc_source_arc(&id);
                            let rejected = src_arc
                                .as_deref()
                                .is_some_and(|s| memtable_primary_key_rejects(topk, s, &id, self));
                            if !rejected {
                                let source = src_arc.map(|a| (*a).clone()).unwrap_or(Value::Null);
                                seen_ids.insert(id.clone());
                                // Same read `source` came from — not a later
                                // pass (#440) — and reused below for ranking.
                                let (seq_no, version) = self
                                    .store
                                    .version_map
                                    .get(&id)
                                    .map(|ver| self.hit_seq_version(&id, &ver))
                                    .unwrap_or((None, None));
                                let seq = seq_no.unwrap_or(u64::MAX);
                                topk.offer(
                                    Hit {
                                        id,
                                        score: 1.0,
                                        source,
                                        seq_no,
                                        version,
                                        sort: Vec::new(),
                                        explain: None,
                                        highlight: None,
                                        matched_queries: Vec::new(),
                                        passage: None,
                                    },
                                    seq,
                                    self,
                                );
                            }
                        }
                    } else if all_hits.len() < materialisation_limit {
                        let id: String = $id;
                        if !seen_ids.contains(&id) {
                            seen_ids.insert(id.clone());
                            all_hits.push(Hit {
                                id,
                                score: 1.0,
                                source: Value::Null,
                                // Deferred with `source`: `fill_memtable_sources`
                                // resolves both from the SAME read once this
                                // hit is known to be on the returned page
                                // (#440) — not here, where most candidates
                                // never make the final page.
                                seq_no: None,
                                version: None,
                                sort: Vec::new(),
                                explain: None,
                                highlight: None,
                                matched_queries: Vec::new(),
                                passage: None,
                            });
                        }
                    }
                }
            }};
        }

        // When the query was served by the DocValues fast path, we retain the
        // internal doc indices so the aggregation path can use them to iterate
        // DocValues columns directly (Optimization 2: filtered stats agg).
        // `None` means MatchAll (use all docs) or a non-DocValues path.
        let mut mem_dv_doc_indices: Option<Vec<usize>> = None;

        // Take a snapshot of memtable data under a short read lock, then
        // release the lock before doing expensive search work.  This prevents
        // long-held read locks from blocking concurrent document indexing.
        enum MemSnapshot {
            Empty,
            /// (doc_id, score) pairs from the inverted index, plus the
            /// UNCOLLECTED matching-doc remainder beyond the fetch cap —
            /// like `DocValuesHits`, it still counts toward `hits.total`
            /// (pre-fix the variant carried no remainder and size>0 match
            /// totals capped the memtable contribution at ~256 — b7
            /// DEFECT 1b).
            FtsHits(Vec<(String, f32)>, u64),
            AllDocIds(Vec<String>, u64), // MatchAll: bounded IDs + uncollected remainder count
            /// Fast DocValues hit: (doc_id, internal_index) pairs — source is NOT
            /// cloned here; it will be fetched only for the final page of hits.
            /// The `u64` is the UNCOLLECTED matching-doc remainder (bounded
            /// fused-bool path); it still counts toward `hits.total`.
            DocValuesHits(Vec<(String, usize)>, u64),
            /// `(seq_no, doc_id, shared source)` for a term-level brute scan.
            /// #191 — `seq_no` rides along so the bounded collector can rank a
            /// document it reaches after filling the cap against the page it
            /// already holds; shard-concatenation order is not arrival order.
            DocsForScan(Vec<(u64, String, Arc<Value>)>),
        }

        // Search the memtable (unflushed docs only). Flushed docs are searched
        // via segment readers below. This is a known v0.1 limitation: flushed
        // docs are not yet searchable via the FTS segment reader for match
        // queries, but MatchAll and doc-scan queries do work via stored segments.
        // Step 4: fan out the 16-shard `doc_count()` sum ONCE per query and
        // reuse it at the mem_snapshot gate and the size=0 total-synthesis
        // arms below, instead of re-locking all 16 shards 3-4×.  The memtable
        // is written concurrently, so this is a point-in-time snapshot — every
        // consumer here either feeds a total that a later `live_doc_count()`
        // overwrites (match_all) or gates the empty-memtable fast path, both
        // tolerant of a one-instant-stale count.
        // ── Point-in-time capture ORDER (mixed-RUW Fix 1) ─────────────────
        // Take the SEGMENT snapshot BEFORE the memtable walk.  Flushes are
        // drain-first (`do_flush_shard` Phase 1 empties the shard under the
        // FTS write lock; Phase 2 installs the segment), so with this order
        // a doc can never be visible to BOTH captures: installed-before-snap
        // implies drained-before-snap implies absent from the later memtable
        // walk/clone.  The historical layout (snapshot taken ~350 lines
        // below, AFTER the memtable arms) let a flush that drained after the
        // walk and installed before the snapshot surface the same docs in
        // both — a transient DOUBLE-COUNT of `hits.total` under sustained
        // writes.  The remaining race (drained before snap, installed after)
        // is a transient undercount during an in-flight flush — the
        // pre-existing, self-healing behaviour.
        let snap = self.store.snapshot();
        // F1 correctness gate (hoisted to the snapshot so the scan-early-stop
        // decision, the post-loop `total_count` overwrite and the #892 pinned-kNN
        // projection gate below can all see it): the doc-values/FST
        // `shortcut_count` is DELETE-BLIND (counts physical postings, not live
        // docs), whereas the stored-doc scan it lets us skip filters tombstones.
        // The shortcut may only stand in for the EXACT `hits.total` when the
        // index has no deleted/superseded docs. Conservative O(segments) signal:
        // any flushed tombstone, OR live_count < physical (updates + deletes
        // inflate the per-segment/memtable physical tally above the version-map
        // live count). MatchAll is unaffected — overwritten with the
        // delete-aware live_doc_count() regardless of this flag.
        // EXACT ghost signal (see `VersionMap::ghost_events`): flushed
        // tombstones OR any overwrite/delete event ever recorded.  The old
        // `live_count() < seg_physical + mem_physical` arithmetic also
        // tripped on unrelated physical-count drift — live-verified: two
        // duplicate docs per merged segment turned the gate permanently ON
        // for a pure append-only corpus, disabling the F1 bounded scan and
        // forcing every size>0 term/range/bool into a full O(N) stored
        // scan.  That was the dominant per-query cost in the
        // read-under-write collapse.
        //
        // #892 hoist, stated because the binding moved and so did its READ
        // TIME: `ghost_events()` is a live counter, and this read now happens
        // ~850 lines and two `.await` points earlier than it used to. The two
        // pre-existing F1 consumers (the scan early-stop and the post-loop
        // `total_count` overwrite) therefore see a marginally staler value —
        // a delete landing mid-search is slightly less likely to be observed
        // by them. That race pre-dates this change (the counter was always
        // read once and reused across awaits); the hoist widens the window,
        // it does not create it. The consequence is the pre-existing one: a
        // delete that lands after this read can leave that single request's
        // `hits.total` served by the delete-blind shortcut. The #892 gate
        // itself is unaffected — it is paired with `snap`, taken on the line
        // above, so the route it admits reads a consistent segment set.
        let deletes_present: bool = snap.segments.iter().any(|m| m.has_tombstones)
            || self.store.version_map.ghost_events() > 0;

        // ── #892: the #825 pinned kNN disjunct takes the INDEXED route ────
        //
        // `pin_knn_clause` names its top-k documents by `_id`, and `_id` is not
        // in the FTS term dictionary — so the projection `?`-aborted on the
        // pinned `should` clause, `fts_query` came back `None`, and EVERY
        // `knn`-beside-`query` request fell to a full stored-document scan of
        // every segment. Resolving those ids to each segment's stored positions
        // (`id_pos_map_for`, the index `ids` queries and `_mget` already use)
        // turns the disjunct into an ordinary FTS leaf, so the lexical half
        // keeps the inverted index and the `bool` serves the same union with
        // the same summed scores.
        //
        // `Probe` is the shape-only answer for the callers that have no segment
        // in hand — `query_needs_fts` and the index-wide BM25 statistics
        // pre-pass, both of which only need "does this project at all?". The
        // real per-segment map is resolved inside the segment loop.
        //
        // #1303: this is NO LONGER gated on `!deletes_present`. The original
        // #892 gate kept ghost-bearing indexes on the stored-doc scan out of a
        // concern that `id_pos_map_for` keeps ONE position per `_id` and could
        // hand back a SUPERSEDED position (the overwrite's live copy lives in a
        // newer segment or the memtable), which an FTS leaf — unlike the stored
        // scan — would not re-read `_id` to notice. In practice that concern is
        // already answered DOWNSTREAM: the scored-FTS hit walk fetches each
        // hit's stored `_id` and runs the SAME capture-scoped liveness check
        // the pure-lexical path uses (`captured_verdict_for_segment_hit` →
        // `Invisible` ⇒ skip the superseded/tombstoned copy; see the walk near
        // the `CapturedEntryVerdict` match), and the physical ghost count is
        // subtracted from the total via the ghost-bitmap observer. So a pinned
        // id whose position resolves to a ghost in an old segment is dropped
        // there and emitted once, live, from the segment that holds its current
        // copy — the identical treatment a plain `match` already gets under
        // deletes. The per-segment `map.len() == expect_docs` guard in
        // `id_pos_map_for` still declines a segment that physically holds
        // duplicate ids (a rare same-flush overwrite); that lone segment falls
        // to its stored scan as before while every other segment keeps the
        // exact-BM25 FTS path.
        //
        // The gate was a real CORRECTNESS bug, not just a slow path: the whole
        // hybrid `bool{should:[query, knn]}` `?`-aborted the FTS projection on
        // the pinned `Ids` sub-tree and fell to the stored-doc scan, which
        // scores a `multi_match` with a page/heuristic score instead of
        // index-wide BM25. On any index that had ever taken an overwrite or
        // delete (`ghost_events()` is MONOTONIC and global — the common case
        // for a re-indexed corpus) the hybrid returned a flat, id-ordered
        // ranking belonging to NEITHER half (#1303: `_score` ~constant,
        // unrelated docs at the top). The append-only path was correct; the
        // delete-bearing path is now the SAME path.
        let pinned_probe: Option<PinnedIds<'_>> = if pinned_query.is_some() {
            Some(PinnedIds::Probe)
        } else {
            None
        };
        // Exact memtable match total captured by the fused DV walk below and
        // threaded into `try_shortcut_count`, whose bool-conjunction arm
        // then skips its DUPLICATE memtable walk (mixed-RUW Fix 1: the
        // second walk was 6-8 ms of the bool p99 at a deep memtable).
        // INVARIANT (b7 DEFECT 1a guard): `Some` ONLY when a memtable DV
        // walk (`doc_values_bool_query` — fused or limit-0 count-only — or
        // the single-leaf `try_doc_values_query`) actually EXECUTED for
        // this query.  Every other arm leaves `None` — the unlowerable-pred
        // `MemSnapshot::Empty` fallback (no walk ran; the shortcut's own
        // recount is the ONLY memtable authority there), the aggs/sort-gated
        // paths, FTS, DocsForScan, and match_all.
        let mut mem_matches_known: Option<u64> = None;
        let mem_doc_count = self.memtable.doc_count();

        // ── #188: INDEX-WIDE BM25 collection statistics ───────────────────
        //
        // BM25 only compares two documents when both were scored against the
        // same `N`, `avgdl` and `doc_freq`.  Historically every arm used its
        // own: each segment scored against its own `FieldStats`, and the
        // memtable against the union over its shards only.  Two user-visible
        // consequences:
        //
        //   * overwriting a document PROMOTED it — its live copy moves to the
        //     memtable, and alone there it scores idf=ln(4/3), dl/avgdl=1,
        //     i.e. a fixed 0.28768 that beats almost any correctly-normalised
        //     segment hit, regardless of the document's real length;
        //   * scores tracked segment TOPOLOGY — the same 365-doc corpus
        //     flushed into 1 segment vs 16 scored `strong0` at 0.177 vs 0.570.
        //
        // Fix: fold one `CollectionStats` over every live arm (all segments
        // plus the memtable) and hand it to BOTH the memtable scorer and every
        // segment `FtsSearcher`.  This is Lucene's shape —
        // `IndexSearcher.fieldStats` sums `docCount`/`sumTotalTermFreq` over
        // `reader.leaves()` and `TermStates.build` sums `docFreq` over them,
        // then ONE `SimScorer` scores every leaf — and tantivy's
        // (`Bm25StatisticsProvider for Searcher` sums over `segment_readers()`,
        // `Bm25Weight::for_terms` builds one weight from it).  It is also
        // already this repo's convention on the columnar path:
        // `leaf_constant_score` sums df + total_docs across every segment.
        //
        // SINGLE-ARM GATE.  With at most one live scoring arm the union is the
        // identity, so we skip it and take the historical path verbatim.  That
        // is not just an optimisation: for a memtable-only index the union
        // would also redefine `N` from `doc_count()` (all memtable docs) to
        // per-field docs-with-field, so the gate is what keeps every
        // index → refresh → search shape — the ES-YAML suite's dominant one,
        // and one segment per refresh on a 1-ingest-shard runner — byte-exact.
        //
        // `count_only` skips it too: a size:0 count never builds a scorer, and
        // the pre-pass would be pure cost on the `term_doc_freq` shortcut.
        //
        // The stats derive from the SAME `snap` binding as the segment walk —
        // taking a second snapshot would reintroduce the flush double-count
        // race documented above and let scores and `hits.total` disagree
        // mid-flush.
        //
        // LAZY.  Several shapes that project to FTS never build a BM25 scorer
        // at all — the columnar `scored_columnar` / `leaf_constant_score`
        // routes, the precomputed-agg route, a segment loop the F1 early-break
        // skips.  Computing behind a `OnceCell` means only a query that
        // actually scores pays the pre-pass, and it is computed at most once
        // per search however many arms ask for it.
        let stats_gate_open =
            !count_only && snap.segments.len() + usize::from(mem_doc_count > 0) > 1;
        // `OnceLock`, not `OnceCell`: `search_inner` is an async fn whose
        // future must stay `Send`, and a `&OnceCell` is not.
        let stats_cell: std::sync::OnceLock<Option<Arc<xerj_fts::CollectionStats>>> =
            std::sync::OnceLock::new();
        let collection_stats = || -> Option<Arc<xerj_fts::CollectionStats>> {
            if !stats_gate_open {
                return None;
            }
            stats_cell
                .get_or_init(|| {
                    self.build_collection_stats(
                        &snap,
                        query,
                        &text_fields,
                        &exact_fields,
                        fts_kw_fields,
                        mem_doc_count,
                        pinned_probe,
                    )
                    .map(Arc::new)
                })
                .clone()
        };

        let unindexed_dv_text_match = has_unindexed_doc_values_text_match(query, &dmq_schema);

        let mem_snapshot = {
            let mem = &*self.memtable;
            if mem_doc_count == 0 {
                MemSnapshot::Empty
            } else if matches!(query, QueryNode::MatchAll) && size == 0 && request.aggs.is_none() {
                // MatchAll + size=0 + NO aggs: pure count query.
                // Everything is served by try_shortcut_count via the
                // engine atomic doc_count.  Skipping the memtable
                // iteration saves the 200 k doc_id clone.
                //
                // When aggs ARE present we can NOT take this
                // short-circuit because an unsupported agg type (range,
                // filter, histogram, etc.) will fall back to
                // `run_aggs_with_all` which needs the materialised hit
                // sources — and skipping the memtable here leaves that
                // fallback with empty inputs.
                MemSnapshot::Empty
            } else if matches!(query, QueryNode::MatchAll) {
                // size > 0 match_all.  Field-sorted requests must offer
                // EVERY buffered doc to the top-N heap; unsorted requests
                // only ever admit the first `materialisation_limit` ids,
                // so clone just those and carry the remainder as a count.
                if sort_topk.is_some() {
                    // Bounded sorted candidates for the common shape
                    // (single default-flavour field sort, no cursor):
                    // columnar per-shard top-cap extraction instead of
                    // offering EVERY buffered doc to the heap.  Date-string
                    // columns (the implicit `@timestamp` index sort) resolve
                    // through the bounded process-wide epoch memo — the SAME
                    // normalisation `compute_sort_values` applies per hit —
                    // so the candidate cut ranks exactly like the heap would.
                    let bounded: Option<(Vec<String>, u64)> = (|| {
                        use xerj_query::sort::{SortMissing, SortMode, SortOrder};
                        let topk = sort_topk.as_ref()?;
                        if topk.after.is_some() || request.sort.len() != 1 {
                            return None;
                        }
                        let sf = &request.sort[0];
                        if sf.is_score()
                            || sf.is_doc_order()
                            || sf.field == "_id"
                            // `sort_candidates_numeric` cuts the candidate set
                            // by reading the sort field out of each buffered
                            // doc's `_source`, but #401 resolves a meta-field
                            // from the version map — so the cut and the heap
                            // would rank on different data.  Usually `_source`
                            // has no such key at all and EVERY doc classifies
                            // as "missing the field", yielding an arbitrary
                            // `cap`-sized prefix; where a doc DOES carry a
                            // literal `_seq_no` (xerj accepts one, see
                            // `memtable_primary_key_rejects`) the cut ranks on
                            // the shadowing value instead.  Both give a page
                            // of the wrong documents, correctly ranked.  Take
                            // the full walk.
                            || is_meta_sort_field(&sf.field)
                            || sf.mode != SortMode::default()
                            || sf.missing != SortMissing::default()
                        {
                            return None;
                        }
                        // The memo is per-FIELD-scale (#790): this cut has to
                        // rank on the same epoch numbers `compute_sort_values`
                        // emits for this field, not on a per-value guess — and
                        // on the scale THIS SORT asked for, which `numeric_type`
                        // can override (#889).
                        let scale = self.date_scale_for_sort(sf);
                        mem.sort_candidates_numeric(
                            &sf.field,
                            sf.order == SortOrder::Desc,
                            materialisation_limit,
                            &|v: &str| sort_epoch_memo(v, scale),
                        )
                    })();
                    match bounded {
                        Some((ids, total)) => {
                            let extra = total.saturating_sub(ids.len() as u64);
                            MemSnapshot::AllDocIds(ids, extra)
                        }
                        // Ineligible shape (multi-field sort, cursor,
                        // non-default mode/missing, un-normalisable
                        // values): fall back to offering every buffered
                        // doc — via Arc-shared sources so the scan arm's
                        // pre-clone primary-key rejection bounds the
                        // per-doc cost to a memoised epoch lookup once
                        // the heap is full (NOT the id-only snapshot,
                        // whose per-doc deep clone cost ~1 s/query at a
                        // 1 M-doc memtable).
                        None => MemSnapshot::DocsForScan(mem.all_docs_with_seq_arc()),
                    }
                } else {
                    let (ids, total) = mem.doc_ids_bounded(materialisation_limit);
                    let extra = total.saturating_sub(ids.len() as u64);
                    MemSnapshot::AllDocIds(ids, extra)
                }
            } else if unindexed_dv_text_match {
                // These fields have no memtable postings. Route direct Match,
                // normalized bool-Match, and DisMax-of-Match shapes through
                // the mapping-aware scan so pre-flush answers use the same
                // whole-value column semantics as flushed documents.
                MemSnapshot::DocsForScan(mem.all_docs_with_seq_arc())
            } else if let Some((dm_subs, dm_tie)) = dis_max_mem_fts_subs(query) {
                // #834: a `dis_max` of single-field text `match` subs used
                // to fall through to the stored-doc scan, whose scorer has
                // no DisMax arm — every buffered match took the flat-1.0
                // catch-all, so a doc matching MORE disjuncts tied with
                // single-disjunct docs and the ranking changed at flush.
                // Score each sub through the SAME memtable BM25 path a
                // standalone `match` takes and combine per doc as
                // max + tie_breaker·Σ(rest), mirroring the segment's
                // `execute_dis_max`.  GHOST WINDOW: same complete-hit-list
                // widening as the single-`Match` arm below — the consume
                // arm's liveness filter needs every hit.
                let mem_limit = if self.store.version_map.ghost_events() > 0 {
                    usize::MAX
                } else {
                    fetch_limit
                };
                let mem_stats = collection_stats();
                let (hits, mem_total) = mem.search_dis_max_boosted_with_total_using(
                    &dm_subs,
                    dm_tie,
                    mem_limit,
                    mem_stats.as_deref(),
                );
                if hits.is_empty() {
                    MemSnapshot::Empty
                } else {
                    let uncollected = mem_total.saturating_sub(hits.len() as u64);
                    MemSnapshot::FtsHits(
                        hits.into_iter().map(|h| (h.doc_id, h.score)).collect(),
                        uncollected,
                    )
                }
            } else if is_doc_scan_query(query) {
                // count_only + Term/Range short-circuits BEFORE
                // `try_doc_values_query` because the DV-term path walks
                // the whole memtable and clones the matching doc_id
                // Strings into a Vec — for a 170 k-hit term query that
                // was ~15 ms of pure String allocation, just to have the
                // segment `try_shortcut_count` path overwrite the count
                // a moment later.
                if count_only
                    && memtable_count_covered_by_shortcut(query)
                    && self.store.version_map.ghost_events() == 0
                {
                    // NOTE the ghost_events guard (b8 T2b): with ghosts
                    // present `try_shortcut_count` discards its result
                    // (the `!deletes_present` gate) and the counting scan
                    // then runs — it must see the memtable, otherwise
                    // memtable-resident matches count as 0 (unrefreshed
                    // `_count`/`size:0` = 0 while `size:10` returned the
                    // docs).
                    //
                    // Mixed-RUW Fix 1 extension: this arm used to take
                    // `MemSnapshot::Empty` (zero memtable work) on the
                    // promise that `try_shortcut_count` resolves these
                    // shapes MEMTABLE-AWARE.  That promise breaks when the
                    // shortcut abandons on its SEGMENT side (a queried
                    // field with no usable segment DV column / term-dict
                    // entry → `None`): the fallback counting scan then ran
                    // with the memtable already skipped, silently excluding
                    // every memtable-resident match from `_count`/`size:0`
                    // totals — a live b7 DEFECT 1a instance (verified on
                    // c6cbe9f: bare term on a memtable-only field → size:0
                    // = 0 while size:5 returns the doc; conjunctive
                    // bool(term+range on a float field) → size:0 = segment
                    // count only).  So instead of skipping, run the SAME
                    // fused columnar walk the size>0 path uses at LIMIT 0 —
                    // count-only, zero id materialisation, zero allocation,
                    // tens of µs at the (Fix 2) capped memtable depth — and
                    // publish the total as `mem_matches_known`:
                    //   * shortcut resolves → it consumes the walk total
                    //     (bool arm) or computes its own count-map total
                    //     (term arm) and OVERWRITES `total_count` — one
                    //     memtable walk either way (the historical layout
                    //     was zero-walk here + a duplicate recount walk in
                    //     the bool arm);
                    //   * shortcut ABANDONS → the counting scan now runs
                    //     with the memtable contribution already admitted
                    //     by the `DocValuesHits` consume arm below — the
                    //     b7-1a hole is closed.
                    // Preds that don't lower (CIDR-shaped term values,
                    // non-numeric range bounds, a queried field absent from
                    // one shard's columns — `doc_values_bool_hits` is
                    // all-or-nothing per shard) fall THROUGH to the same
                    // `try_doc_values_query`/`DocsForScan` arms the size>0
                    // path uses, so the count keeps the memtable
                    // contribution under a segment-side shortcut abandon —
                    // taking `Empty` here re-opened the hole for exactly
                    // those shapes (live-verified: the missing-bearing
                    // float-field bool below counted 14 seg-only vs 29).
                    mem_matches_known = mem_bool_preds(query)
                        .and_then(|preds| mem.doc_values_bool_query(&preds, 0))
                        .map(|(_, total)| total);
                    if let Some(total) = mem_matches_known {
                        MemSnapshot::DocValuesHits(Vec::new(), total)
                    } else if let Some((hits, total)) = try_doc_values_query(
                        query,
                        mem,
                        // Unsorted count query: only the total matters, but
                        // mirror the size>0 arm's bounded materialisation
                        // (the consume arm tolerates unused ids).
                        materialisation_limit,
                    ) {
                        mem_matches_known = Some(total);
                        let uncollected = total.saturating_sub(hits.len() as u64);
                        MemSnapshot::DocValuesHits(hits, uncollected)
                    } else {
                        // Brute per-doc scan — same authority the size>0
                        // path falls back to; `doc_matches_query` semantics.
                        MemSnapshot::DocsForScan(mem.all_docs_with_seq_arc())
                    }
                } else if let Some((hits, total)) = (|| {
                    // Fused columnar term/range/bool: ONE position walk
                    // per shard, bounded id materialisation, exact total.
                    // Gated off when a field sort is active — the top-N
                    // heap must see EVERY matching doc — and when aggs
                    // are present (the filtered-agg path needs the full
                    // `mem_dv_doc_indices` position set).  Placed BEFORE
                    // `try_doc_values_query`, whose unbounded walks clone
                    // every matching doc_id (~all-of-memtable for broad
                    // range filters) per request.
                    if sort_topk.is_some() || request.aggs.is_some() {
                        return None;
                    }
                    let preds = mem_bool_preds(query)?;
                    mem.doc_values_bool_query(&preds, materialisation_limit)
                })() {
                    let uncollected = total.saturating_sub(hits.len() as u64);
                    // Fused walk RAN: publish its exact point-in-time total
                    // so the shortcut count doesn't re-walk the memtable.
                    mem_matches_known = Some(total);
                    MemSnapshot::DocValuesHits(hits, uncollected)
                } else if let Some((hits, total)) = try_doc_values_query(
                    query,
                    mem,
                    // Field-sorted requests must offer EVERY matching doc to
                    // the top-N heap (sort correctness); unsorted requests
                    // only materialise the id for the first
                    // `materialisation_limit` matches and carry the rest as
                    // an uncollected count (mirrors the fused-bool path).
                    if sort_topk.is_some() {
                        usize::MAX
                    } else {
                        materialisation_limit
                    },
                ) {
                    // DocValues fast path for queries that actually need
                    // the hit list (size > 0 or sort-on-field).
                    let uncollected = total.saturating_sub(hits.len() as u64);
                    // Single-leaf DV walk RAN: publish its exact total (the
                    // bool-conjunction shortcut arm never consumes it for
                    // these shapes — bare Term/Range take their own arms —
                    // but the capture keeps the invariant uniform: Some ⇔
                    // a memtable DV walk executed for this query).
                    mem_matches_known = Some(total);
                    MemSnapshot::DocValuesHits(hits, uncollected)
                } else {
                    // Composite queries (e.g. bool) that the memtable DV
                    // path can't resolve: share the buffered sources via
                    // Arc — the old deep-clone of the ENTIRE memtable per
                    // query (plus a second per-doc clone for `_id`
                    // injection below) was the single hottest search-side
                    // cost in the read-under-write thread dumps.
                    let docs: Vec<(u64, String, Arc<Value>)> = mem.all_docs_with_seq_arc();
                    MemSnapshot::DocsForScan(docs)
                }
            } else {
                let query_text = extract_query_text(query);
                if let Some(text) = query_text {
                    // FTS path: use the inverted index.  Counting is
                    // decoupled from materialisation (`_with_total`), so the
                    // fetch cap no longer truncates `hits.total` (b7 DEFECT
                    // 1b).  GHOST WINDOW (b7 DEFECT 1c mirror): with any
                    // overwrite/delete recorded, the consume arm filters
                    // each memtable hit against the version map — that needs
                    // the COMPLETE hit list (an uncollected remainder can't
                    // be liveness-checked), mirroring the segment side's
                    // `fts_cap = usize::MAX` under `deletes_present`.
                    let mem_limit = if self.store.version_map.ghost_events() > 0 {
                        usize::MAX
                    } else {
                        fetch_limit
                    };
                    // For a single-field Match, restrict FTS to that
                    // field — otherwise docs that store the query tokens
                    // in a *different* field (incl. dynamically-ignored
                    // ones under subobjects:false + dynamic:false) would
                    // spuriously match. QueryString / multi-field
                    // patterns still search all indexed fields.
                    let field_filter: Vec<&str> = match query {
                        QueryNode::Match { field, .. } if field != "*" && !field.ends_with('*') => {
                            vec![field.as_str()]
                        }
                        _ => Vec::new(),
                    };
                    // Per-field boosts (match `boost:` / multi_match `field^N`)
                    // must reach the memtable BM25 scorer too — the segment
                    // path applies them via query_node_to_fts, and without
                    // this the unflushed ranking disagrees with the flushed
                    // one (test_weighted_bool_boost_ranking).
                    let mut field_boosts: std::collections::HashMap<String, f32> =
                        std::collections::HashMap::new();
                    collect_field_boosts(query, &mut field_boosts);
                    // #188: score against the INDEX-WIDE statistics when the
                    // index has more than one live arm, so a document that an
                    // overwrite just moved into the memtable is normalised
                    // against the whole corpus rather than against itself.
                    let mem_stats = collection_stats();
                    let (hits, mem_total) = mem.search_text_boosted_with_total_using(
                        &text,
                        &field_filter,
                        mem_limit,
                        &field_boosts,
                        mem_stats.as_deref(),
                    );
                    if !hits.is_empty() {
                        let uncollected = mem_total.saturating_sub(hits.len() as u64);
                        MemSnapshot::FtsHits(
                            hits.into_iter().map(|h| (h.doc_id, h.score)).collect(),
                            uncollected,
                        )
                    } else {
                        MemSnapshot::Empty
                    }
                } else if let Some((hits, total)) = try_doc_values_query(
                    query,
                    mem,
                    if sort_topk.is_some() {
                        usize::MAX
                    } else {
                        materialisation_limit
                    },
                ) {
                    let uncollected = total.saturating_sub(hits.len() as u64);
                    MemSnapshot::DocValuesHits(hits, uncollected)
                } else {
                    MemSnapshot::Empty
                }
            }
            // Lock dropped here
        };
        phase_marks.push(("mem_snapshot", phase_t0.elapsed().as_millis() as u64));
        // #1013 — capture-bracket validation, replacing end-of-search
        // validation (see `search`). The segment snapshot and the memtable
        // capture above are consistent iff no publication began or finished
        // since the bracket reference at the top of this function and no
        // writer is in flight NOW: a straddling publication could leave the
        // pair torn (docs drained from the memtable but not yet installed in
        // a segment — invisible to both), so retry the capture. This is the
        // seqlock reader's evenness check: the search itself then runs
        // against immutable captured state (the snapshot `Arc` and its read
        // lease keep drained segments alive) and no longer needs a
        // writer-free interval to exist for its whole duration.
        {
            let (generation, in_flight, poisoned) = self.collection_publication.state();
            if poisoned {
                return Err(collection_publication_interrupted());
            }
            if generation != capture_generation || in_flight != 0 {
                return Err(collection_capture_crossed());
            }
            self.collection_publication.note_capture_validated();
        }
        // #1212 — the captured world's segment ids, scoping every LIVE
        // version-map read the walk performs below. The scan's segments are
        // frozen in `snap`; a version entry naming anything else describes a
        // publication after this capture and must be ignored (see
        // [`CapturedEntryVerdict`]). O(segments) once per search — the walk
        // that consumes it is O(matching docs).
        let captured_segment_ids: std::collections::HashSet<&str> =
            snap.segments.iter().map(|meta| meta.id.as_str()).collect();
        // #1212 regression hook: park the scan the instant its capture
        // bracket validates, so a test can publish a merge/flush into the
        // window this fix exists to make harmless.
        #[cfg(test)]
        {
            if self.test_pause_search_after_capture.load(Ordering::Acquire) {
                self.test_search_capture_parked
                    .store(true, Ordering::Release);
                while self.test_pause_search_after_capture.load(Ordering::Acquire) {
                    tokio::task::yield_now().await;
                }
                self.test_search_capture_parked
                    .store(false, Ordering::Release);
            }
        }

        let dbg_mem_arm: &'static str = match &mem_snapshot {
            MemSnapshot::Empty => "empty",
            MemSnapshot::FtsHits(..) => "fts",
            MemSnapshot::AllDocIds(..) => "allids",
            MemSnapshot::DocValuesHits(..) => "dv",
            MemSnapshot::DocsForScan(_) => "scan",
        };
        match mem_snapshot {
            MemSnapshot::Empty => {}
            MemSnapshot::FtsHits(hits, uncollected) => {
                // GHOST-WINDOW liveness (b7 DEFECT 1c mirror): once any
                // overwrite/delete has been recorded, admit only hits whose
                // LIVE version is memtable-resident and not tombstoned —
                // the segment materialisation applies the same rule.  Zero
                // work (and `uncollected` possibly non-zero) on the
                // ghost-free path; with ghosts the snapshot was taken
                // uncapped, so `uncollected == 0` and the filter sees every
                // hit.  #1212: the verdict is capture-scoped — an entry
                // repointed onto a segment this capture never held describes
                // a flush that published AFTER the capture, which cannot
                // retire the captured memtable's copy.
                let ghost_filter = self.store.version_map.ghost_events() > 0;
                for (doc_id, score) in hits {
                    if ghost_filter {
                        if let Some(ver) = self.store.version_map.get(&doc_id) {
                            if captured_verdict_for_memtable_hit(&ver, &captured_segment_ids)
                                == CapturedEntryVerdict::Invisible
                            {
                                continue;
                            }
                        }
                    }
                    admit_hit!(Hit {
                        id: doc_id,
                        score,
                        source: Value::Null, // filled in below
                        // Deferred with `source` — see the deferred-`Hit`
                        // comment in `admit_hit!`'s unsorted `count` arm (#440).
                        seq_no: None,
                        version: None,
                        sort: Vec::new(),
                        explain: None,
                        highlight: None,
                        matched_queries: Vec::new(),
                        passage: None,
                    });
                }
                // Beyond-cap remainder still counts toward hits.total
                // (mirrors AllDocIds / DocValuesHits).
                total_count += uncollected;
            }
            MemSnapshot::AllDocIds(ids, uncollected) => {
                // Bounded id page: the remainder still counts toward
                // hits.total (match_all's total is later overwritten by
                // the authoritative live count anyway).
                total_count += uncollected;
                for doc_id in ids {
                    admit_hit!(count doc_id);
                }
            }
            MemSnapshot::DocValuesHits(hits, uncollected) => {
                // DocValues fast path: source is NOT cloned here — we defer the
                // clone until after pagination so we only pay for from+size docs.
                // Retain the internal indices for filtered aggregation (Opt 2).
                let mut indices: Vec<usize> =
                    Vec::with_capacity(hits.len().min(materialisation_limit));
                for (doc_id, mem_idx) in hits {
                    if !count_only
                        && all_hits.len() < materialisation_limit
                        && !seen_ids.contains(&doc_id)
                    {
                        indices.push(mem_idx);
                    }
                    admit_hit!(count doc_id);
                }
                // Bounded fused-bool remainder: matched but un-materialised
                // docs still count toward hits.total.
                total_count += uncollected;
                mem_dv_doc_indices = Some(indices);
            }
            MemSnapshot::DocsForScan(docs) => {
                // Lock already released — scan docs without holding the memtable lock.
                //
                // `_id` injection (a full per-doc Object clone) is only
                // observable when the query tree can actually read `_id`
                // — a nested Ids query.  Detect that ONCE via the query's
                // serialised form (conservative: false positives merely
                // keep the legacy per-doc clone) instead of cloning every
                // buffered doc on every request.
                let query_may_read_id: bool = serde_json::to_string(query)
                    .map(|s| s.contains("_id") || s.contains("Ids") || s.contains("ids"))
                    .unwrap_or(true);
                // #191 — the cap-th page key the bounded collector currently
                // holds, recomputed only when it can have changed (the moment
                // the collector first fills, and after every trim).  A stale
                // value is always a WEAKER threshold than the truth — it admits
                // more than strictly necessary, never less — which is the safe
                // direction, the same argument the segment walk's `page_worst`
                // relies on.
                let mut scan_worst: Option<(f32, u64, String)> = None;
                for (seq_no, doc_id, source) in docs {
                    let matched = if let QueryNode::Ids { values } = query {
                        values.iter().any(|v| v == doc_id.as_str())
                    } else if !query_may_read_id || source.get("_id").is_some() {
                        doc_matches_query_typed(query, &source, &dmq_schema)
                    } else {
                        // Inject `_id` so deeply-nested Ids queries (e.g.
                        // function_score → ids) can resolve it from source.
                        let source_with_id = if let Some(obj) = source.as_object() {
                            let mut o = obj.clone();
                            o.insert("_id".to_string(), serde_json::Value::String(doc_id.clone()));
                            serde_json::Value::Object(o)
                        } else {
                            (*source).clone()
                        };
                        doc_matches_query_typed(query, &source_with_id, &dmq_schema)
                    };
                    if matched {
                        // Materialise (score + owned source) ONLY when the
                        // hit can actually enter the bounded collector /
                        // top-N heap; everything else is a bare count.
                        //
                        // #191 — "can enter" is no longer "the collector still
                        // has room".  This walk visits shards in index order
                        // and each shard in arrival order, so it is NOT a
                        // globally arrival-ordered walk: a document reached
                        // after the cap is full can still hold a smaller
                        // `seq_no` than the page's worst hit and therefore win
                        // the tie-break against it.  Admit exactly those as
                        // well — one `u64` compare against `scan_worst`, no
                        // extra source clone for the ones that lose — and let
                        // the trim below put the collector back at the cap by
                        // the final comparator.  Documents that lose on
                        // `seq_no` but would have won on SCORE are still
                        // dropped here; that is pre-existing (they were dropped
                        // outright before) and is recorded under Residual risk.
                        let competitive = all_hits.len() < materialisation_limit || {
                            if scan_worst.is_none() {
                                scan_worst = self.worst_page_key(&all_hits);
                            }
                            scan_worst.as_ref().is_some_and(|w| seq_no < w.1)
                        };
                        if count_only {
                            total_count += 1;
                        } else if sort_topk.is_some()
                            || (competitive && !seen_ids.contains(&doc_id))
                        {
                            // Field-sorted: pre-clone primary-key rejection.
                            // Once the heap is full, a doc whose PRIMARY
                            // sort key is strictly worse than the heap's
                            // worst can never enter the page — skip the
                            // `(*source).clone()`, the `seen_ids` insert
                            // and the full `offer` (ties and underivable
                            // keys are conservatively admitted; the doc
                            // still counts toward `total_count` exactly
                            // like `admit_hit!` would have counted it).
                            if let Some(topk) = sort_topk.as_ref() {
                                if !seen_ids.contains(&doc_id)
                                    && memtable_primary_key_rejects(topk, &source, &doc_id, self)
                                {
                                    total_count += 1;
                                    continue;
                                }
                            }
                            let score = score_doc(&source, &doc_id);
                            // Same read `source` (above) is cloned from — not
                            // a later pass (#440). NOT the tuple's own
                            // `seq_no` (that's the memtable's raw arrival
                            // ordinal, used only for the `#191` competitive
                            // tie-break above — a different number from the
                            // ES-wire `_seq_no`/`_version` this resolves).
                            let (hit_seq_no, hit_version) = self
                                .store
                                .version_map
                                .get(&doc_id)
                                .map(|ver| self.hit_seq_version(&doc_id, &ver))
                                .unwrap_or((None, None));
                            let hit = Hit {
                                id: doc_id,
                                score,
                                source: (*source).clone(),
                                seq_no: hit_seq_no,
                                version: hit_version,
                                sort: Vec::new(),
                                explain: None,
                                highlight: None,
                                matched_queries: Vec::new(),
                                passage: None,
                            };
                            if sort_topk.is_some() {
                                admit_hit!(hit);
                            } else {
                                // `admit_hit!`'s FIFO bound would throw the
                                // post-cap admissions above straight back
                                // away, so this arm collects them itself and
                                // trims by the page comparator once the
                                // overflow reaches 2×cap — the same eager-trim
                                // shape the segment walk uses.
                                total_count += 1;
                                if !seen_ids.contains(&hit.id) {
                                    seen_ids.insert(hit.id.clone());
                                    all_hits.push(hit);
                                    if all_hits.len() > materialisation_limit.saturating_mul(2) {
                                        let (kept, worst) = self.trim_page_to_cap(
                                            std::mem::take(&mut all_hits),
                                            materialisation_limit,
                                        );
                                        all_hits = kept;
                                        scan_worst = worst;
                                    }
                                }
                            }
                        } else {
                            total_count += 1;
                        }
                    }
                }
            }
        }

        // #191 — normalise the memtable contribution back to exactly the cap
        // before the segment walk starts, so every downstream stage sees the
        // documented shape (`all_hits` holds the best `materialisation_limit`
        // by the final comparator).  Only the brute-scan arm can overshoot —
        // it admits post-cap documents that outrank the page it holds — and
        // only up to 2×cap before its own eager trim fires.
        if sort_topk.is_none() && all_hits.len() > materialisation_limit {
            let (kept, _worst) =
                self.trim_page_to_cap(std::mem::take(&mut all_hits), materialisation_limit);
            all_hits = kept;
        }

        // --- Segment search ---
        // `snap` is captured ABOVE the memtable arms (see the point-in-time
        // capture ORDER comment there): segment snapshot strictly before the
        // memtable walk, so a drain-first flush can never double-surface a
        // doc in both captures.
        let segments_dir = self.data_dir.join("segments");

        // ── Fast path: count-only shortcut ────────────────────────────────
        //
        // Ported from Elasticsearch's
        // `QueryPhaseCollectorManager.shortcutTotalHitCount`
        // (server/src/main/java/org/elasticsearch/search/query/
        //  QueryPhaseCollectorManager.java:607-660).
        //
        // When the user only asks for `{"size":0, "query":X}` (and possibly
        // `track_total_hits=true`), we don't need to iterate a single
        // document — we can read the count straight out of the FST / segment
        // metadata for a handful of query shapes.  This turns `size:0 term`
        // queries from ~660 ms (full stored-doc scan) to ~1 ms (O(segments)
        // metadata reads).
        //
        // Shortcut-able query shapes:
        //   - MatchAll: sum of segment doc_counts + memtable doc_count.
        //   - Term { field, value }:
        //       - Keyword field with a memtable doc-values column — match
        //         against the column directly.
        //       - FTS term dictionary on disk — read the FST's `doc_freq`
        //         for the term (with a lowercased fallback because the
        //         segment analyzer lowercases).
        //       - If NEITHER path has data for the field, we conservatively
        //         return `None` and fall through to the regular scan.
        //
        // Anything more complex (Bool, Range, Match) currently returns
        // `None` — `Range` will be shortcut-able once G3 (BKD) lands.
        let is_match_all = matches!(query, QueryNode::MatchAll);
        // #270 — a top-level `constant_score`/`boosted` chain over
        // `match_all` matches exactly the documents `match_all` matches, but
        // the raw flag above left it with `count_authoritative == false` (no
        // `try_shortcut_count` arm resolves a bare MatchAll — MatchAll totals
        // are handled by the flag, which the wrapper defeated).  The scan
        // then ran in exact-counting mode: it TALLIES past a full collector
        // but never materialises into it, so with the memtable walked first
        // the bounded page was all memtable documents (`size:1` →
        // `mem0000` where the full page starts `seg0000`) even though the
        // segment documents hold the lowest `seq_no`s and own the head of
        // the page.  This flag widens ONLY the count/bounds decisions
        // (`count_authoritative`, the final `live_doc_count()` total
        // overwrite) so wrapped match_all takes the same bounded-scan +
        // cross-segment re-merge path as bare match_all.  SCORING keeps the
        // raw flag: wrapper hits still go through `score_doc`, and a
        // top-level `Constant`'s scores are overwritten with the wrapper
        // boost before the page sort regardless.
        let is_match_all_effective = is_match_all || {
            let mut q = query;
            loop {
                match q {
                    QueryNode::Constant { query, .. } | QueryNode::Boosted { query, .. } => {
                        q = query
                    }
                    other => break matches!(other, QueryNode::MatchAll),
                }
            }
        };

        // For MatchAll we now skip the memtable iteration entirely at
        // `MemSnapshot` time (it was cloning 200 k doc_ids just to tick a
        // counter).  Re-add the memtable's doc count here so downstream
        // branches that add segment counts on top arrive at the right
        // total.  `try_shortcut_count` + the precomputed agg fast path
        // both overwrite `total_count` anyway, so double-counting isn't a
        // concern there; this only matters for the fallback segment
        // stored-scan path.
        // For MatchAll+size=0 with NO aggs, `MemSnapshot::Empty` skipped
        // the memtable iteration, so `total_count` is missing the
        // memtable contribution — add it back here.  With aggs
        // present, `MemSnapshot::AllDocIds` already counted every
        // memtable doc via `admit_hit!(count ...)` — if we add
        // `mem_count` again we double-count (visible as the 40 vs 20
        // failure on `test_terms_agg_bucket_counts` under M5.1).
        if is_match_all && size == 0 && request.aggs.is_none() {
            let mem_count = mem_doc_count as u64;
            total_count = total_count.saturating_add(mem_count);
        }

        // Compute the authoritative match count via the fast doc-values /
        // FST metadata path.  Historically this was gated on `count_only`
        // (size:0), but F1 decouples the EXACT total from source
        // materialisation for size>0 too: when the count is known cheaply we
        // can bound the stored-doc scan to only the top (from+size) hits
        // instead of walking every match to tally `hits.total`.  For query
        // shapes the shortcut can't resolve it returns `None` (cheaply) and we
        // fall back to the full counting scan — so this is always safe.
        // Probe the scored-family columnar fast path EARLY (the executor
        // itself runs after the agg fast-paths below): when it is going to
        // run, `try_shortcut_count` is dead weight — the executor supplies
        // the exact `hits.total` itself — yet costs several ms on some
        // shapes (live-measured: a boolean-column `term` under `must_not`
        // spent ~6 ms here, dominating the fast path's single-digit budget).
        // If the executor later bails at runtime (missing column, etc.) the
        // stored scan simply runs in full-counting mode — correct, just not
        // F1-bounded.
        let scored_plan: Option<ScoredPlan> =
            scored_fast_plan(query, request, size, &kw_fields, &num_fields, &bool_fields);
        // Deletes/ghosts no longer bail the plan: `scored_columnar` is
        // ghost-aware (physical Lucene-parity term stats, liveness-filtered
        // matching via the per-segment ghost bitmaps). Only a non-empty
        // memtable — rows with no doc-values columns — keeps the brute path.
        let scored_fast_ready: bool = scored_plan.is_some() && self.memtable.doc_count() == 0;
        let shortcut_count: Option<u64> = if scored_fast_ready {
            None
        } else {
            self.try_shortcut_count(query, &snap, is_match_all, mem_matches_known, &dmq_schema)
                .await
        };

        // Whether this query resolves to an FTS (inverted-index) search.  The
        // FTS scored path already counts authoritatively via `seg_hits.len()`
        // and materialises only the top prefix, so the F1 bounded-scan / count
        // overwrite must NOT touch FTS queries — it only applies to the
        // non-FTS stored-doc scan (match_all / term-on-keyword / range).
        //
        // #892 note: this flips false → true for a pinned `knn`-beside-`query`
        // (it is the whole point of the change), so the three branches gated on
        // `!query_needs_fts` are RE-EVALUATED for that shape, not bypassed —
        // the `size:0` columnar agg fast path below, `count_authoritative`, and
        // the F1 `total_count` overwrite after the segment loop. All three are
        // inert here: the fast path additionally needs `is_match_all ||
        // agg_filter.is_some()` and `query_node_to_agg_filter` declines a
        // `should` bool, and the other two only ever REMOVE a bounded-count
        // shortcut, leaving the FTS path's own authoritative `seg_hits.len()`
        // tally. Outcome unchanged; the gates themselves are not.
        let query_needs_fts: bool = query_node_to_fts_projected(
            query,
            &text_fields,
            &exact_fields,
            fts_kw_fields,
            self.segment_analyzer_binding(),
            pinned_probe,
        )
        .is_some();

        // ── Precomputed segment agg fast path (M2 G2) ─────────────────────
        //
        // When the request is `size=0 + aggs + match_all`, every agg can
        // often be served directly from segment `.dv` sidecars.  If that
        // succeeds here — BEFORE the stored-section scan — we skip the
        // scan entirely and synthesize `total_count` from segment metadata
        // + memtable.  This is the M2/G2 "100× agg" win.
        //
        // We only try this when hits output isn't needed (`size==0`), so
        // there's no requirement to materialise source values.  The agg
        // result is stashed in `precomputed_aggs` and consumed at the
        // agg-section below.
        let mut precomputed_aggs: Option<Value> = None;
        phase_marks.push(("mem_admit", phase_t0.elapsed().as_millis() as u64));
        let dbg_sort_topk = sort_topk.is_some();
        let dbg_mem_hits = all_hits.len();
        let dbg_mem_seen = seen_ids.len();
        let dbg_mem_total = total_count;
        // Extend the columnar agg fast path to FILTERED `size:0` aggs: a
        // `{size:0, query:Q, aggs:…}` where Q is a term/terms/numeric-range/
        // conjunctive-bool over doc-values fields.  Without this the filtered
        // shape fell through to the full-corpus `_source` hydration path
        // (~7.8 s on 1 M docs) while the unfiltered shape was ~0.1 ms — a
        // ~78,000× cliff on any filtered-agg benchmark row.  The filter is
        // evaluated columnarly (matching-row gate) and the reduction runs over
        // only the matching docs' doc-values, byte-identical to the brute
        // path.  Non-columnarizable queries (FTS, must_not/should bool, …)
        // yield `agg_filter == None` here and keep the exact brute fallback.
        let agg_filter: Option<Value> = if is_match_all {
            None
        } else {
            query_node_to_agg_filter(query)
        };
        if size == 0
            && request.aggs.is_some()
            && request.min_score.is_none()
            && !query_needs_fts
            && (is_match_all || agg_filter.is_some())
        {
            if let Some(aggs_def) = &request.aggs {
                let r_opt = self
                    .try_aggs_fast_with_segments_cached(
                        aggs_def,
                        agg_filter.as_ref(),
                        &snap,
                        &segments_dir,
                    )
                    .await;
                if let Some((r, filtered_total)) = r_opt {
                    precomputed_aggs = Some(r);
                    match filtered_total {
                        // Filtered fast path already computed the matching-doc
                        // count (exact — no deletes on the fast path).
                        Some(t) => {
                            total_count = t;
                        }
                        // match_all: synthesize total_count from segments +
                        // memtable so we don't touch the stored section at all
                        // (later overwritten with the delete-aware live count).
                        None => {
                            let seg_docs: u64 = snap.segments.iter().map(|m| m.doc_count).sum();
                            let mem_count = mem_doc_count as u64;
                            total_count = seg_docs + mem_count;
                        }
                    }
                }
            }
        }

        // LOSS_BATTLE_PLAN B6 — page-cap materialisation.  The +100/256
        // hydration slack in `materialisation_limit` buys headroom against
        // memtable/segment dedup overlap and version-map rejections; with an
        // empty memtable and no ghosts neither exists, so on the strictly
        // safe unsorted page path a `size:10` query only ever needs
        // `from+size` stored-doc parses (live: the 256-doc floor was ~60% of
        // the range/term page cost).  Every excluded shape (sorts, aggs —
        // the brute agg fallback aggregates the materialised sources —
        // rescore/collapse/explain, min_score, count-only,
        // pinned's phase-4 overlay headroom) keeps the original slack
        // byte-for-byte.  Shadowed AFTER the memtable snapshot: the gate
        // requires the memtable be empty, so the earlier `fetch_limit` uses
        // are untouched.
        //
        // `highlight` was in the excluded list until #177.  It never belonged
        // there — highlighting is a post-pass over the rendered page — and
        // while the segment merge was arrival-order it made this cap
        // observable: a body with `highlight` got 256 candidates, the same
        // body without it got `from+size`, and the two pages carried
        // different `_id`s and different `_score`s.  The merge now selects the
        // global top-k by score (see the FTS admission below), so the cap
        // controls only how much work is done, never which hits win.
        // #2422/#2423 — the source columns a cold scored FTS page needs.
        let fts_row_keep: Option<Vec<String>> = fts_row_hydration_keep(request, query);
        // Hits whose `_source` came back column-projected, by id → (segment,
        // position), so the one post-page reader that looks at the WHOLE
        // document (the TF-IDF fallback below) can restore it.
        let mut row_projected: HashMap<String, (String, u32)> = HashMap::new();
        // #2427: stored-scan hits whose `_source` came from a column-projected
        // cold decode, by id → segment (row located lazily, see
        // `locate_scan_projected_rows`).
        let mut scan_projected: HashMap<String, String> = HashMap::new();
        // Cold score-ordered FTS hits whose `_source` is read only once the
        // segment loop has settled the page: `_id` -> (segment, row).
        let mut deferred_sources: HashMap<String, (String, u32, u64)> = HashMap::new();
        let materialisation_limit: usize = if mem_doc_count == 0
            && !deletes_present
            && size > 0
            && request.sort.is_empty()
            && sort_topk.is_none()
            && request.aggs.is_none()
            && request.rescore.is_empty()
            && request.collapse.is_none()
            && request.min_score.is_none()
            && !request.explain
            && !matches!(query, QueryNode::Pinned { .. })
        {
            from + size
        } else {
            materialisation_limit
        };

        phase_marks.push(("fast_aggs+gates", phase_t0.elapsed().as_millis() as u64));

        // ── Columnar function_score fast path ─────────────────────────────
        // `function_score { match_all, field_value_factor }` scored straight
        // from the numeric doc-values column + live memtable sources, selecting
        // the GLOBAL top-(from+size) and hydrating `_source` only for the
        // winners — replacing the brute stored scan that parses every doc, keeps
        // only the arrival-order first-`materialisation_limit` matches, AND
        // (pre-existing bug) applies the function twice. Bails (leaving
        // `fs_fast_applied = false`) for any uncovered shape, when deletes are
        // present, or on a non-finite/negative score — in which case the brute
        // fallback below reproduces ES behaviour (incl. the error path) exactly.
        let mut fs_fast_applied = false;
        if let Some(fvf) = fs_fast_fvf {
            if !deletes_present {
                if let Some((hits, total)) = self.function_score_columnar(
                    fvf,
                    &snap.segments,
                    &segments_dir,
                    materialisation_limit,
                ) {
                    seen_ids.clear();
                    seen_ids.extend(hits.iter().map(|h| h.id.clone()));
                    all_hits = hits;
                    total_count = total;
                    fs_fast_applied = true;
                }
            }
        }

        // ── Columnar scored-family fast path ──────────────────────────────
        // `dis_max` / `boosting` / `pinned` / scoring `bool` on keyword
        // fields, scored with EXACT ES BM25 (global term stats from the
        // doc-values columns) instead of the IDF-less brute scorer, with the
        // global top-k selected by (score, insertion order) — see
        // `scored_fast_plan` (shape gate) + `scored_columnar` (executor).
        // Bails (leaving `scored_fast_applied = false`) for any uncovered
        // shape, deletes, non-empty memtable, or missing/nulled columns —
        // the brute path below then behaves byte-for-byte as before.
        let mut scored_fast_applied = false;
        // Set when scored_columnar already dropped the first `from` candidates
        // (page-offset hydration) — the final pagination then skips 0.
        let mut scored_from_applied = false;
        // ── #361: request-level companion to `scored_fast_applied` ────────
        // The segment FTS path (`fts_handled` below) also produces EXACT ES
        // BM25, scored against index-wide statistics (#188), and the
        // page-local IDF rescore further down must not overwrite it — that
        // rescore derives its N from `final_hits.len()`, i.e. the RETURNED
        // PAGE, so leaving it armed makes `_score` a function of `size`.
        // `fts_handled` is a per-segment local, so accumulate here.
        //
        // The rescore is only skipped when EVERY arm that could contribute a
        // hit was exact. `heuristic_scored_applied` starts true whenever the
        // memtable holds documents — unflushed hits carry the IDF-less
        // memtable/stored-scan score, and putting the two populations on one
        // scale is precisely what the rescore was papering over until the
        // score unification lands (#354 / #188). Mixed pages therefore keep
        // today's behaviour; a fully-flushed index gets exact BM25.
        let mut fts_scored_applied = false;
        let mut heuristic_scored_applied = mem_doc_count > 0;
        if let Some(plan) = &scored_plan {
            if scored_fast_ready {
                if let Some((hits, total, from_applied)) = self.scored_columnar(
                    plan,
                    &snap.segments,
                    &segments_dir,
                    materialisation_limit,
                    from + size,
                    from,
                    // tth early-termination limit (LOSS_BATTLE_PLAN B5):
                    // only the capped-count mode may stop early; explicit
                    // `track_total_hits: true`/`false` keep the exact walk.
                    match request.track_total_hits {
                        xerj_query::ast::TrackTotalHits::Limit(n) => Some(n),
                        _ => None,
                    },
                ) {
                    seen_ids.clear();
                    seen_ids.extend(hits.iter().map(|h| h.id.clone()));
                    all_hits = hits;
                    total_count = total;
                    scored_fast_applied = true;
                    scored_from_applied = from_applied;
                }
            }
        }

        if precomputed_aggs.is_some() {
            // Skip the entire segment loop — the fast agg path already
            // computed everything we need.  `total_count` is set above.
        } else if count_only && shortcut_count.is_some() && !deletes_present {
            // Overwrite `total_count` — the memtable/bounded-collector scan
            // above has already looked at the memtable, but we want an
            // authoritative per-shape count, not the sum of two sources.
            // (The memtable path bails on `count_only` without double
            // counting, but to be safe we set the total directly.)
            //
            // NOTE: size>0 queries that ALSO have a shortcut count do NOT take
            // this branch — they fall through to the segment loop so their
            // top (from+size) hit *sources* still get materialised.  Their
            // `total_count` is overwritten with `shortcut_count` after the
            // loop, and the scan runs in bounded (`count_authoritative`) mode.
            //
            // `!deletes_present` (2026-07, delete-durability batch): the
            // shortcut is DELETE-BLIND (physical postings, not live docs).
            // Pre-fix this size:0 branch took it unconditionally, so a
            // `{size:0, query:{term:…}}` total counted version-map-deleted
            // segment-resident docs (live-observed: 50 where truth was 0,
            // while the same query with size>0 correctly returned 0).  Same
            // correctness-over-speed gate as the size>0 `count_authoritative`
            // path below; with ghosts present we fall through to the full
            // delete-aware counting scan.
            total_count = shortcut_count.unwrap();
        } else if is_match_all && count_only {
            // Legacy MatchAll fast path (covers the `try_shortcut_count`
            // return as well, but keeps existing behaviour if the helper
            // ever returns None for MatchAll).
            let seg_docs: u64 = snap.segments.iter().map(|m| m.doc_count).sum();
            total_count += seg_docs;
        } else if fs_fast_applied || scored_fast_applied {
            // A columnar fast path (function_score fvf or scored-family)
            // already produced the global top-k (`all_hits`) and the exact
            // total (`total_count`); skip the stored-doc scan entirely.
        } else {
            // Decide up-front whether this query needs FTS side-cars at all.
            // For term/range/etc. queries we skip FtsIndexReader::open
            // entirely — that call eagerly reads .fst/.meta/.post/.norms
            // for every text field, which costs ~50 MB per segment and is
            // wasted work when the query is a stored-doc scan.
            let fts_query_probe = query_node_to_fts_projected(
                query,
                &text_fields,
                &exact_fields,
                fts_kw_fields,
                self.segment_analyzer_binding(),
                pinned_probe,
            );
            let needs_fts = fts_query_probe.is_some();
            // #361: a bool with a non-projectable non-scoring (`filter`/`must_not`)
            // child projects only its scoring subtree — the residual clause is
            // absent from the FTS match set, so when FTS runs we must re-apply
            // membership with `doc_matches_query` over the ORIGINAL query and
            // switch off the seg_total count/bounded fast path (which assumes the
            // FTS bool is the exact match set). Only meaningful when FTS runs.
            let residual_gate = needs_fts
                && bool_has_nonprojectable_nonscoring(
                    query,
                    &text_fields,
                    &exact_fields,
                    fts_kw_fields,
                    self.segment_analyzer_binding(),
                    pinned_probe,
                );
            // A `query_string` whose projection DECLINED still has to be
            // answered by the stored-doc scan — an over-cap `tokens × fields`
            // cross-product returns `None`, and without the scan the segment
            // would be skipped outright, dropping every match it holds.
            //
            // UNLESS it declined because the query analyses to zero tokens, in
            // which case nothing can match and the scan is pure cost. See
            // `query_string_has_no_tokens` for the measurement; hoisted out of
            // the per-segment loop below because it re-tokenises the query.
            let query_string_needs_doc_scan = matches!(query, QueryNode::QueryString { .. })
                && !query_string_has_no_tokens(query, &exact_fields);
            // Open the FTS reader with every field the projected query
            // actually touches, ON TOP of the text fields.  Keyword-typed
            // fields have FTS side-cars too (whole-value keyword-analyzer
            // terms) but were never loaded because `field_refs` only listed
            // Text fields — so keyword projections silently searched an
            // empty reader.  Restricting the extension to the queried
            // fields keeps the eager `.fst/.meta/.post/.norms` read bounded.
            let fts_open_fields: Vec<String> = {
                let mut all = text_fields.clone();
                if let Some(fq) = &fts_query_probe {
                    let mut qf: Vec<String> = Vec::new();
                    collect_fts_query_fields(fq, &mut qf);
                    for f in qf {
                        if !all.contains(&f) {
                            all.push(f);
                        }
                    }
                }
                all
            };
            drop(fts_query_probe); // only needed for the decision + field list

            // F1: when the EXACT total is already known independently of the
            // scan — MatchAll (overwritten with `live_doc_count()` below) or a
            // resolved `shortcut_count` (doc-values / FST) — the stored-doc
            // scan no longer needs to walk every match just to tally
            // `hits.total`.  In that case we let the non-FTS scan STOP as soon
            // as it has materialised the top `materialisation_limit` sources,
            // turning size>0 match_all/term/range from O(total-matches) into
            // O(from+size).  When the count is NOT authoritative (no shortcut,
            // not match_all) we keep the full counting scan for correctness.
            // F1 correctness gate: the doc-values/FST `shortcut_count` is
            // DELETE-BLIND — it counts physical postings, not live docs —
            // whereas the stored-doc scan it lets us skip filters tombstones.
            // So the shortcut may only stand in for the EXACT `hits.total` when
            // the index has no deleted/superseded docs. Cheap, conservative
            // signal: any flushed tombstone, OR live_count < physical (updates
            // and deletes both inflate the per-segment/ memtable physical tally
            // above the version-map live count). MatchAll is unaffected: it is
            // overwritten with the delete-aware `live_doc_count()` regardless.
            // When deletes ARE present (and not match_all) we keep the full
            // delete-aware counting scan for a correct total, at the cost of the
            // pre-F1 scan time — correctness over speed until the shortcut
            // itself is made delete-aware. (`deletes_present` hoisted above.)
            let count_authoritative: bool = !query_needs_fts
                && (is_match_all_effective || (shortcut_count.is_some() && !deletes_present));

            // Whether a Regexp query's field is keyword-typed — gates the
            // FST term-dictionary route of the regexp pre-filter (computed
            // here because the segment loop below is sync).  See
            // `build_regexp_prefilter_cached` for the exactness argument.
            let regexp_field_is_keyword: bool = if let QueryNode::Regexp { field, .. } = query {
                let schema_guard = self.schema.read().await;
                schema_guard
                    .schema
                    .field(field)
                    .map(|f| matches!(f.field_type, FieldType::Keyword))
                    .unwrap_or(false)
            } else {
                false
            };

            // #191 — worst `(score, seq_no, _id)` key currently kept by the
            // stored-scan collector, maintained across segments so the skip
            // below is O(1).  See `worst_page_key`.
            let mut scan_page_worst: Option<(f32, u64, String)> = None;
            // #191 — walk the segments in ARRIVAL order.  `IndexSnapshot`
            // documents its list as "oldest first", but nothing enforces it:
            // `with_new_segment` appends in flush-COMPLETION order (a flush
            // drains each memtable shard into its own segment, so the shards
            // race) and `replace_segments` appends a merge's output — the
            // oldest data in the index — at the very end.  Documents inside a
            // segment ARE `seq_no`-ordered (`drain_for_flush` and the merge
            // both sort by `seq_no`), so ordering the segments by `min_seq_no`
            // is what makes the whole walk approximate the page's own
            // `(score DESC, seq_no ASC)` order — Lucene's "leaves in index
            // order, docs ascending within a leaf" invariant, which is exactly
            // what lets a bounded collector stop early
            // (`TopScoreDocCollector.java:122-124`).  Correctness no longer
            // depends on this — the bounds below are order-independent — but
            // without it a reversed list would defeat every early-out.
            // `id` breaks the remaining tie so the walk is deterministic.
            let ordered_segments: Vec<&xerj_storage::segment::SegmentMeta> = {
                let mut v: Vec<&xerj_storage::segment::SegmentMeta> =
                    snap.segments.iter().collect();
                v.sort_by(|a, b| {
                    a.min_seq_no
                        .cmp(&b.min_seq_no)
                        .then_with(|| a.id.cmp(&b.id))
                });
                v
            };
            for meta in ordered_segments {
                dbg_segs += 1;
                // F1: once the exact total is authoritative AND the bounded
                // collector is full, remaining segments can neither add a
                // materialised hit (page is full) nor change `hits.total`
                // (overwritten by shortcut/live_doc_count).  Skip them WITHOUT
                // opening + decompressing their stored section — otherwise the
                // O(N) cost just moves from JSON-parsing to `decode_stored`
                // over every segment.  This is what turns the whole query into
                // O(from+size) rather than O(segments·docs_per_segment).
                //
                // #191 — this used to be an unconditional `break`, which made
                // the page "the first `cap` matches in SEGMENT-LIST order".
                // That list is flush/merge COMPLETION order, not `seq_no`
                // order: a flush drains each memtable shard into its own
                // segment, and a merge appends its output at the end.  The
                // final page sort ties by `seq_no` ASC (ES `_doc`), so with
                // tied scores a `size:5` page and a `size:1000` page named
                // different documents.  A segment is now skipped only when it
                // provably cannot displace a kept hit: every document in it
                // arrived strictly after the worst kept hit
                // (`min_seq_no > worst.seq_no`), so on a tie it loses.
                // Segments that CAN compete are scanned, and the cross-segment
                // merge at the bottom of the loop re-selects the best `cap` by
                // the same comparator the final page sort uses.
                if count_authoritative && all_hits.len() >= materialisation_limit {
                    if scan_page_worst.is_none() {
                        scan_page_worst = self.worst_page_key(&all_hits);
                    }
                    match scan_page_worst.as_ref() {
                        Some(w) if meta.min_seq_no > w.1 => continue,
                        // No key resolvable (empty collector) — keep the
                        // historical behaviour and stop.
                        None => break,
                        Some(_) => {}
                    }
                }
                // Cooperative deadline: stop fanning into further segments
                // once the request timeout has elapsed — partial results
                // with `timed_out: true`, exactly like ES.
                if std::time::Instant::now() >= search_deadline {
                    deadline_exceeded = true;
                    break;
                }

                let seg_id = meta.id.clone();
                let fts_dir = segments_dir.clone();

                // #191 / #1359 — on the stored-scan path each segment gets its
                // OWN `materialisation_limit` of headroom, whether or not
                // `count_authoritative` is set: `scan_stored_section_into` stops
                // materialising hits at `all_hits.len() >= limit` (continuing to
                // tally `total_count` when `!count_authoritative`), so a
                // collector already filled by an earlier segment or the memtable
                // would otherwise let a genuinely competitive segment contribute
                // zero hits.  Positions inside a segment ARE `seq_no` order
                // (`drain_for_flush` and the merge both sort by `seq_no`), so
                // this segment's first `cap` matches are its own `cap` best; the
                // merge below then re-selects the global best `cap`.  Peak is
                // 2×cap, trimmed at the bottom of the loop.
                let scan_limit = if !count_only && sort_topk.is_none() {
                    all_hits.len().saturating_add(materialisation_limit)
                } else {
                    materialisation_limit
                };
                let hits_before_segment = all_hits.len();

                let field_refs: Vec<&str> = fts_open_fields.iter().map(|s| s.as_str()).collect();
                // `QueryString` is steered by its own flag rather than added
                // to `is_doc_scan_query` (which also steers the MEMTABLE
                // branch, where `query_string` must keep its BM25 route), and
                // that flag is false for the zero-token shape so a
                // `query_string` that can match nothing costs nothing.
                let scan_stored = matches!(query, QueryNode::MatchAll)
                    || query_string_needs_doc_scan
                    || is_doc_scan_query(query);

                // Try FTS path first if we have an FTS query.
                let mut fts_handled = false;
                // Set when the FTS searcher's cooperative deadline fired
                // mid-expansion (RC4 blocker 12) — its hits/total for this
                // segment are partial and the response must say
                // `timed_out: true`.
                let mut fts_deadline_tripped = false;
                let t_fts = std::time::Instant::now();
                let reader_opt = if needs_fts {
                    self.fts_reader_for(&fts_dir, &seg_id, &field_refs)
                } else {
                    None
                };
                dbg_fts_ms += t_fts.elapsed().as_millis() as u64;
                if let Some(reader) = reader_opt {
                    let reader = Arc::clone(&*reader);
                    // Arm the cooperative deadline (RC4 blocker 12): the
                    // searcher's multi-term expansions (prefix / wildcard /
                    // fuzzy term-dictionary walks) are otherwise
                    // uninterruptible units that the outer tokio timeout
                    // can never preempt (`block_in_place` completes the
                    // whole search on first poll — live: `timeout: 1ms`
                    // wildcard ran 3.7 s / fuzzy 8.3 s with
                    // `timed_out: false`).
                    let searcher =
                        FtsSearcher::new(Arc::clone(&reader), Arc::clone(&self.registry))
                            .with_deadline(Some(search_deadline))
                            // #188: index-wide BM25 statistics — one union of
                            // avgdl/N/df over every segment plus the memtable,
                            // so `_score` stops depending on which segment a
                            // document happens to sit in.  `None` keeps this
                            // segment's own stats (single-arm gate).
                            .with_collection_stats(collection_stats());
                    // #892 — resolve the pinned kNN ids to THIS segment's
                    // stored positions. `None` (no pinned tree, ghosts present,
                    // or a segment whose id index is incomplete) leaves the
                    // projection exactly as it was: it declines, and this
                    // segment alone falls through to the stored-doc scan below.
                    let pinned_positions = pinned_probe
                        .and_then(|_| self.id_pos_map_for(seg_id.as_str(), meta.doc_count));
                    let fts_query = query_node_to_fts_projected(
                        query,
                        &text_fields,
                        &exact_fields,
                        fts_kw_fields,
                        self.segment_analyzer_binding(),
                        pinned_positions
                            .as_ref()
                            .map(|map| PinnedIds::Positions(map)),
                    );

                    // Count-only fast path for single-term FTS queries:
                    // call `term_doc_freq` directly on the segment reader
                    // so we never decode the postings list.  This is the
                    // bug fix that pulls `match field:term` from
                    // truncated-256-hits to exact total.
                    // `!deletes_present` (b7 DEFECT 1c): `term_doc_freq` is
                    // the segment's PHYSICAL postings count — in the
                    // flush→merge ghost window it counts tombstoned docs and
                    // superseded old versions.  With ghosts present, fall
                    // through to `search_bounded` + the liveness-filtered
                    // tally below (same correctness-over-speed convention as
                    // the F1 / size:0 shortcut gates).
                    if count_only && !deletes_present {
                        if let Some(FtsQuery::Term(t)) = fts_query.as_ref() {
                            if let Some(df) = reader.term_doc_freq(&t.field, &t.term) {
                                total_count += df as u64;
                                continue;
                            }
                        }
                    }

                    if let Some(fq) = fts_query {
                        // Check if the FTS reader actually has data for the
                        // queried field(s).  M5.4 skips FTS build at flush,
                        // so the reader may open successfully (empty sidecars)
                        // but contain no terms — in that case fall through to
                        // stored-doc scan instead of claiming "0 matches".
                        // Generalised from the old single-`Term` probe: a
                        // Bool projection (multi_match / lowered
                        // query_string / simple_query_string) over a field
                        // with no FTS data would otherwise "authoritatively"
                        // report 0 matches for the segment. Require every
                        // referenced field to be present; if any is missing,
                        // fall through to the stored-doc scan.
                        //
                        // HETEROGENEOUS SEGMENTS: for a pure disjunction that
                        // rule is far stricter than it needs to be. A
                        // field-less `query_string` projects one `should`
                        // clause per (token, text field), and any field first
                        // indexed after a flush is missing from every older
                        // segment — so a single late field pushed EVERY older
                        // segment onto the stored-doc scan. Prune the clauses
                        // naming fields this segment never indexed (they can
                        // only match nothing here) and keep the postings path;
                        // if nothing survives, fall through as before.
                        let fq =
                            prune_missing_should_fields(&fq, &|f| reader.field_stats(f).is_some())
                                .unwrap_or(fq);
                        let fts_has_field = {
                            let mut qf: Vec<String> = Vec::new();
                            collect_fts_query_fields(&fq, &mut qf);
                            qf.iter().all(|f| reader.field_stats(f).is_some())
                        };

                        // Counting is DECOUPLED from materialisation on the
                        // scored FTS path.  `search_bounded` returns the EXACT
                        // segment match `seg_total` (counted over the full match
                        // set, independent of the page cap) alongside the best
                        // `cap` hits.  Previously the size>0 path passed
                        // `fetch_limit` and tallied `total_count` per materialised
                        // hit, so `hits.total` was capped at the ~256
                        // materialisation limit while size:0 (which used
                        // `usize::MAX`) was exact — DEFECT #3.  Now both paths add
                        // the full `seg_total` so the count agrees, and we
                        // materialise *sources* for only the top
                        // `materialisation_limit` hits.
                        //
                        // PERF (bounded top-N): the old code built + fully sorted
                        // the ENTIRE match set per segment even for size:10 —
                        // O(N log N) on tens of thousands of hits.  On the common
                        // path (no field sort, not count-only, no deletes) only
                        // the top `materialisation_limit` sources are ever
                        // materialised (the loop below breaks there), so we cap
                        // the collector heap at `materialisation_limit`: O(N log
                        // cap) work, O(cap) memory, byte-identical top-k prefix.
                        // The three cases that consume PAST the page cap keep the
                        // legacy full-set path (`usize::MAX`):
                        //   * `sort_topk.is_some()` — the field-sort arm narrows
                        //     *every* matching doc_id to sort candidates.
                        //   * `count_only` — wants the exact total with no page
                        //     cap (and never materialises).
                        //   * `deletes_present` — tombstones/superseded dups can
                        //     skip past `materialisation_limit` matches while
                        //     filling the page, so the page needs more than the
                        //     top-`cap` by score.
                        let fts_cap = if count_only || sort_topk.is_some() || residual_gate {
                            usize::MAX
                        } else {
                            // #179 — `deletes_present` no longer forces the
                            // unbounded scan.  The heap is bounded to
                            // `materialisation_limit`; LIVE matches are counted by
                            // an observer over the full (still-scanned) match set
                            // below, and only a segment that truncates a ghost
                            // re-expands (rare).  See `search_bounded_observed`.
                            materialisation_limit
                        };
                        if fts_has_field {
                            // #179 — under deletes, build the segment ghost bitmap
                            // up front and count dead matches with an observer while
                            // the (bounded) scan visits every posting, so the heap
                            // stays O(cap) yet the live count stays exact (b7 DEFECT
                            // 1c).  On the no-delete hot path we call the plain
                            // `search_bounded` (byte-identical to before).
                            let ghost_bm: Option<Arc<Vec<u64>>> = if deletes_present {
                                self.ghost_positions_for(seg_id.as_str(), meta.doc_count)
                            } else {
                                None
                            };
                            let mut dead_matches: u64 = 0;
                            let bounded = if deletes_present {
                                let bm = ghost_bm.as_deref();
                                searcher.search_bounded_observed(&fq, fts_cap, false, |doc_id| {
                                    if let Some(bm) = bm {
                                        let w =
                                            bm.get((doc_id / 64) as usize).copied().unwrap_or(0);
                                        if (w >> (doc_id % 64)) & 1 == 1 {
                                            dead_matches += 1;
                                        }
                                    }
                                })
                            } else {
                                searcher.search_bounded(&fq, fts_cap, false)
                            };
                            // Record a deadline trip regardless of Ok/Err —
                            // the expansion may have stopped early either
                            // way (RC4 blocker 12).
                            if searcher.deadline_tripped() {
                                fts_deadline_tripped = true;
                            }
                            if let Ok((seg_hits, seg_total)) = bounded {
                                // FTS is authoritative for this segment (field
                                // present + searcher ran) — mark handled the same
                                // way for count-only and size>0 so the fall-through
                                // decision (and thus the count) agrees.
                                fts_handled = true;
                                #[cfg(test)]
                                SEG_FTS_HANDLED.with(|c| c.set(c.get() + 1));
                                // #361 — this segment's hits carry exact BM25.
                                fts_scored_applied = true;
                                // #361 — residual membership gate. This bool has a
                                // non-projectable, non-scoring `filter`/`must_not`
                                // that the projection dropped from the FTS bool, so
                                // `seg_hits` (with `fts_cap == usize::MAX` forced
                                // above) is a SUPERSET of the answer. Re-apply
                                // membership with `doc_matches_query` over the
                                // original (alias/keyword-resolved) query on every
                                // match, counting + materialising only survivors.
                                // A dedicated pass, not inline gating: the bounded
                                // walk below early-outs below `page_worst` and skips
                                // non-entering segments, so gating there would
                                // undercount. Cost is O(matches) source reads for
                                // residual queries only (uncommon) — the same
                                // correctness-over-speed convention as the deletes
                                // path.
                                if residual_gate {
                                    let slices =
                                        self.stored_slices_for(seg_id.as_str(), meta.doc_count);
                                    let whole: Option<Vec<Value>> = if slices.is_some() {
                                        None
                                    } else {
                                        let seg_reader = self.store.open_segment_arc(&seg_id)?;
                                        match seg_reader.section(SectionType::Stored) {
                                            Ok(Some(raw)) => {
                                                xerj_storage::stored_codec::decode_stored(raw)
                                                    .ok()
                                                    .and_then(|b| {
                                                        serde_json::from_slice::<Vec<Value>>(&b)
                                                            .ok()
                                                    })
                                            }
                                            _ => None,
                                        }
                                    };
                                    let fetch = |pos: u32| -> Option<Value> {
                                        if let Some(s) = slices.as_deref() {
                                            let &(a, b) = s.offsets.get(pos as usize)?;
                                            serde_json::from_slice::<Value>(
                                                s.bytes.get(a as usize..b as usize)?,
                                            )
                                            .ok()
                                        } else {
                                            whole
                                                .as_ref()
                                                .and_then(|d| d.get(pos as usize).cloned())
                                        }
                                    };
                                    for sh in &seg_hits {
                                        let doc = match fetch(sh.doc_id) {
                                            Some(d) => d,
                                            None => continue,
                                        };
                                        let id = doc
                                            .get("_id")
                                            .and_then(Value::as_str)
                                            .unwrap_or("")
                                            .to_string();
                                        // Same liveness/staleness check the normal
                                        // walk uses: skip tombstoned or superseded
                                        // copies (live version in a newer segment).
                                        // #1212: capture-scoped — see the main
                                        // walk's copy for the PostCapture arm.
                                        let (mut hit_seq_no, mut hit_version) = (None, None);
                                        if let Some(ver) = self.store.version_map.get(&id) {
                                            match captured_verdict_for_segment_hit(
                                                &ver,
                                                seg_id.as_str(),
                                                &captured_segment_ids,
                                            ) {
                                                CapturedEntryVerdict::Invisible => continue,
                                                CapturedEntryVerdict::Live => {
                                                    let (s, v) = self.hit_seq_version(&id, &ver);
                                                    hit_seq_no = s;
                                                    hit_version = v;
                                                }
                                                CapturedEntryVerdict::PostCapture => {}
                                            }
                                        }
                                        if seen_ids.contains(&id) {
                                            continue;
                                        }
                                        let source =
                                            doc.get("_source").cloned().unwrap_or(Value::Null);
                                        // Membership: re-test the dropped residual
                                        // clause via the whole original query.
                                        let mut src_with_id = source.clone();
                                        if let Some(obj) = src_with_id.as_object_mut() {
                                            obj.insert(
                                                "_id".to_string(),
                                                Value::String(id.clone()),
                                            );
                                        }
                                        if !doc_matches_query_typed(
                                            query,
                                            &src_with_id,
                                            &dmq_schema,
                                        ) {
                                            continue;
                                        }
                                        total_count += 1;
                                        seen_ids.insert(id.clone());
                                        // #577: under `count_only` (size:0) the page is
                                        // empty, so — exactly like the normal walk, which
                                        // does NOT materialise a hit at all under
                                        // count_only (the `if !count_only` guards near
                                        // this pass at ~14939/14975) — skip the `Hit`
                                        // build and `_source` retention; only the count
                                        // matters. Without this a size:0 bool with a
                                        // non-projectable filter held O(matches) hydrated
                                        // `Hit`s before the (empty) slice discarded them.
                                        if !count_only {
                                            let hit = Hit {
                                                id,
                                                score: sh.score,
                                                source,
                                                seq_no: hit_seq_no,
                                                version: hit_version,
                                                sort: Vec::new(),
                                                explain: None,
                                                highlight: None,
                                                matched_queries: Vec::new(),
                                                passage: None,
                                            };
                                            if let Some(topk) = sort_topk.as_mut() {
                                                let seq = hit_seq_no.unwrap_or(u64::MAX);
                                                topk.offer(hit, seq, self);
                                            } else {
                                                all_hits.push(hit);
                                                #[cfg(test)]
                                                RESIDUAL_HITS_PEAK
                                                    .with(|c| c.set(c.get().max(all_hits.len())));
                                                // #577: `fts_cap == usize::MAX` for the
                                                // residual gate, so a non-selective
                                                // non-projectable filter over a large
                                                // segment would grow `all_hits` to
                                                // O(matches) before the post-loop slice.
                                                // Eager-trim to the page cap here, the
                                                // same shape the normal walk uses at its
                                                // `materialisation_limit.saturating_mul(2)`
                                                // check — `trim_page_to_cap` keeps the
                                                // top `materialisation_limit` by score, so
                                                // the page is unchanged.
                                                if all_hits.len()
                                                    > materialisation_limit.saturating_mul(2)
                                                {
                                                    let (kept, _worst) = self.trim_page_to_cap(
                                                        std::mem::take(&mut all_hits),
                                                        materialisation_limit,
                                                    );
                                                    all_hits = kept;
                                                }
                                            }
                                        }
                                    }
                                    // Preserve the segment-tail deadline propagation
                                    // that the `continue` below would otherwise skip.
                                    if fts_deadline_tripped {
                                        deadline_exceeded = true;
                                    }
                                    continue;
                                }
                                // Exact count — identical for count_only and size>0.
                                // GHOST WINDOW (b7 DEFECT 1c): `seg_total` is the
                                // segment's PHYSICAL match count — between a flush
                                // that wrote tombstones/overwrites and the merge
                                // that purges them it counts deleted docs and
                                // superseded old versions (live-observed 40 vs
                                // ES 26).  #179 — the LIVE total is
                                // `seg_total - dead_matches`, where `dead_matches`
                                // was tallied by the observer above over the FULL
                                // match set (the scan visits every posting even when
                                // the heap is bounded to the page cap), so this is
                                // exact WITHOUT forcing `fts_cap == usize::MAX` to
                                // hold the complete hit list.  `dead_matches` is 0
                                // unless `deletes_present` and the ghost bitmap was
                                // built — matching the old physical-count fallback.
                                total_count += seg_total.saturating_sub(dead_matches);
                                // #179 — materialisation correctness under deletes.
                                // `seg_hits` is the top-`cap` by SCORE and the walk
                                // below skips ghosts inline.  Underfill is possible
                                // ONLY when this segment truncated its match set
                                // (`seg_total > cap`) AND a ghost sits INSIDE the
                                // kept top-`cap`: that ghost holds a slot a lower-
                                // scored live hit (now stranded past the bound) would
                                // have taken.  A ghost that scored below the cap was
                                // never kept and displaces nothing, so we test the
                                // returned slice, not the whole match set — an
                                // index with an old low-scoring delete keeps the
                                // bounded fast path.  When it can underfill, re-expand
                                // THIS segment uncapped so the walk sees every live
                                // candidate (rare).  The exact live count above used
                                // `dead_matches` over the FULL set and is untouched.
                                let mut seg_hits = seg_hits;
                                if deletes_present
                                    && fts_cap != usize::MAX
                                    && seg_total > fts_cap as u64
                                {
                                    let dead_in_top = ghost_bm
                                        .as_deref()
                                        .map(|bm| {
                                            seg_hits
                                                .iter()
                                                .filter(|sh| {
                                                    bm.get((sh.doc_id / 64) as usize).is_some_and(
                                                        |w| (w >> (sh.doc_id % 64)) & 1 == 1,
                                                    )
                                                })
                                                .count()
                                        })
                                        .unwrap_or(0);
                                    if dead_in_top > 0 {
                                        if let Ok((full, _)) =
                                            searcher.search_bounded(&fq, usize::MAX, false)
                                        {
                                            seg_hits = full;
                                        }
                                    }
                                }
                                // Field-sorted FTS (e.g. bool/match under the
                                // implicit `@timestamp desc` index sort): the
                                // legacy arm below decodes + parses the WHOLE
                                // stored section per segment per query and offers
                                // every match to the heap.  Narrow the match set
                                // to the per-segment top-cap candidates by
                                // primary sort key (+ ties) and hydrate only
                                // those.  `hits.total` is already exact
                                // (`seg_hits.len()` tallied above), so hydrate's
                                // own partial tally is discarded.
                                let mut fts_sorted_handled = false;
                                #[allow(clippy::unnecessary_unwrap)]
                                // is_some() gate; as_mut() below needs the checked form
                                if !count_only && !seg_hits.is_empty() && sort_topk.is_some() {
                                    let cand_opt = {
                                        let topk_ref =
                                            sort_topk.as_ref().expect("gated on is_some");
                                        let matches: HashSet<u32> =
                                            seg_hits.iter().map(|sh| sh.doc_id).collect();
                                        self.narrow_matches_to_sort_candidates(
                                            &segments_dir,
                                            &seg_id,
                                            meta.doc_count,
                                            topk_ref,
                                            materialisation_limit,
                                            &matches,
                                        )
                                    };
                                    if let Some(cand) = cand_opt {
                                        let best_rejected = cand
                                            .ordered
                                            .first()
                                            .zip(sort_topk.as_ref())
                                            .is_some_and(|(&(kb, _), topk)| {
                                                topk.primary_f64_rejects(f64::from_bits(kb as u64))
                                            });
                                        if best_rejected {
                                            // No candidate can enter the page —
                                            // total is already exact from
                                            // seg_hits.len(); skip the stored
                                            // bytes entirely.
                                            fts_sorted_handled = true;
                                        } else if let Some(slices) =
                                            self.stored_slices_for(seg_id.as_str(), meta.doc_count)
                                        {
                                            let mut discard = 0u64;
                                            self.hydrate_sorted_candidates(
                                                &slices,
                                                &cand,
                                                query,
                                                false,
                                                ids_only,
                                                sort_topk.as_mut().expect("gated on is_some"),
                                                &mut seen_ids,
                                                &mut discard,
                                                score_doc,
                                            );
                                            fts_sorted_handled = true;
                                        }
                                    }
                                }
                                // Materialise sources for the top hits only.
                                // `seg_hits` is score-sorted descending, so the
                                // prefix we take is this SEGMENT's top-k.
                                //
                                // #177 — across segments the collector used to be
                                // a plain FIFO capped at `materialisation_limit`:
                                // the first segments visited filled it and every
                                // later segment was dropped whole, however well
                                // its documents scored.  The page was therefore
                                // "the best hits of whichever segments happened to
                                // fit", not the global top-k, and it moved
                                // whenever the cap moved — which is what made a
                                // `highlight` block (which only widened the cap)
                                // rewrite every `_score` and `_id`.
                                //
                                // `page_worst` is the lowest score currently kept,
                                // defined only once the collector is at its cap
                                // (below the cap nothing has to be displaced).  A
                                // segment is opened when it can beat that, and its
                                // descending run is walked until it can't.
                                //
                                // #179 — `page_worst` is maintained INCREMENTALLY
                                // inside the walk (see the push site below), not
                                // only recomputed once per segment here, and the
                                // overflow is trimmed back to the cap the moment
                                // `all_hits` exceeds 2×cap — not just after the
                                // whole segment run.  That is what actually holds
                                // the admission walk to O(cap) work and a 2×cap
                                // peak, and it does so EVEN under `deletes_present`,
                                // where `fts_cap == usize::MAX` (above) hands this
                                // loop a `seg_hits` spanning every physical match.
                                // Before #179 that combination broke the bound: the
                                // fill-up segment left `page_worst == None` for its
                                // whole run, so it hydrated `_source` for every one
                                // of the O(matches) hits and grew `all_hits` to
                                // O(matches) before the end-of-run trim — an ~8×
                                // read regression on any index that had ever seen a
                                // delete/overwrite (`ghost_events()` is monotonic
                                // and global, so that branch is permanent).  (The
                                // O(matches) score-sort *inside* `search_bounded`
                                // is a separate cost governed by `fts_cap`, not by
                                // this admission walk, and is out of scope here.)
                                //
                                // #191 — `page_worst` is the FULL page key
                                // `(score, seq_no, _id)` of the worst kept hit,
                                // not just its score.  A score-only bound is
                                // only sound when the walk visits documents in
                                // tie-break order, which is what Lucene relies
                                // on ("Since docs are returned in-order (i.e.,
                                // increasing doc Id), a document with equal
                                // score to pqTop.score cannot compete since
                                // HitQueue favors documents with lower doc Ids"
                                // — lucene/core/src/java/org/apache/lucene/
                                // search/TopScoreDocCollector.java:122-124, over
                                // the `(score, doc)` comparator in
                                // HitQueue.java:76-82).  XERJ ties by `seq_no`
                                // (arrival order = ES `_doc`) but walks segments
                                // in snapshot order and documents in STORED
                                // LAYOUT order — neither is seq-ascending — so
                                // an equal-scoring hit met later in the walk can
                                // still own a smaller `seq_no` and must be
                                // allowed to compete.
                                let mut page_worst: Option<(f32, u64, String)> = if sort_topk
                                    .is_none()
                                    && !count_only
                                    && all_hits.len() >= materialisation_limit
                                {
                                    self.worst_page_key(&all_hits)
                                } else {
                                    None
                                };
                                // The `sort_topk.is_some()` disjunct keeps the
                                // segment unconditionally enterable on the
                                // field-sort path.  That is deliberate and settled
                                // (#179): the sorted path NEVER pushes to
                                // `all_hits` — every admission routes through
                                // `topk.offer()` (see the push site below and the
                                // sorted admission macros), so `all_hits.len()`
                                // stays 0 and the second disjunct (`0 < cap`) is
                                // ALREADY unconditionally true for it.  The explicit
                                // `sort_topk.is_some()` therefore changes no
                                // decision today; it makes the invariant visible and
                                // future-proofs it, since were `all_hits` ever
                                // pre-seeded past the cap by an earlier stage the
                                // bare length gate would wrongly begin skipping later
                                // segments and drop global sort candidates.  The
                                // bounded `SortTopK` heap — not this cap — bounds the
                                // sorted path's memory.
                                //
                                // #191 — a segment whose best score BEATS the
                                // worst kept hit can always contribute.  A
                                // segment whose best score merely TIES it can
                                // still contribute, but only through the
                                // `seq_no` tie-break, and only if it holds a
                                // document that arrived no later than the worst
                                // kept hit.  `min_seq_no` decides that in O(1)
                                // from the segment meta — the same
                                // later-segment argument `scored_columnar`'s
                                // `later_min_seq` break already makes — so an
                                // all-tied corpus does not degrade into opening
                                // every segment.  A segment written before
                                // `min_seq_no` was recorded reads back 0, which
                                // simply makes the gate admit it: correct, just
                                // not shortcut.
                                let seg_can_enter = sort_topk.is_some()
                                    || all_hits.len() < materialisation_limit
                                    || seg_hits.first().zip(page_worst.as_ref()).is_some_and(
                                        |(sh, worst)| {
                                            sh.score > worst.0
                                                || (sh.score == worst.0
                                                    && meta.min_seq_no <= worst.1)
                                        },
                                    );
                                if !fts_sorted_handled
                                    && !count_only
                                    && !seg_hits.is_empty()
                                    && seg_can_enter
                                {
                                    // F2 RANDOM-ACCESS source hydration.  The
                                    // scored FTS page needs `_source` for only
                                    // the top-(from+size) matched doc_ids, yet
                                    // the legacy path decoded the ENTIRE stored
                                    // section (`from_slice::<Vec<Value>>`,
                                    // ~10 MB / O(N) per 100k docs) just to index
                                    // them — the dominant size>0 scored-read cost
                                    // (~485 ms at size:10 vs ~1 ms at size:0).
                                    // Reuse the per-segment offset index
                                    // (`stored_slices_for`, the SAME
                                    // random-access mechanism the term /
                                    // doc-values page hydration uses) to parse
                                    // ONLY the page's doc slices: O(page) parses
                                    // on a warm segment.  Each slice is a
                                    // complete top-level `{...}` object (see
                                    // `brace_walk_offsets`), so parsing it with
                                    // the SAME `serde_json` parser the legacy
                                    // path used yields a byte-identical
                                    // `_source` — we deliberately do NOT switch
                                    // to simd_json here (the M7 raw-bytes
                                    // payload corruption noted below still
                                    // applies).
                                    //
                                    // #2422/#2423 — but only when that offset
                                    // index is already RESIDENT. Building it
                                    // cold decompresses and brace-walks the
                                    // whole section (every row, every column)
                                    // to read the page, which is what a
                                    // freshly started node, or one whose cache
                                    // budget evicted the segment, paid on
                                    // every query: seconds on a 30k-doc
                                    // autoindex segment. Cold, decode only
                                    // the rows the walk below can visit — the
                                    // score-ordered prefix not already beaten
                                    // by the page's entry worst (the walk's
                                    // threshold only tightens, so this is a
                                    // superset) — and only the columns the
                                    // request can observe.
                                    // #2422: set when the cold row window
                                    // below was cut short; the walk then
                                    // falls back to the full decode for any
                                    // row past it instead of skipping it.
                                    let mut cold_window_truncated = false;
                                    // Cold score-ordered top-k: the walk
                                    // reads only each candidate's `_id`
                                    // (version-map check, dedup, page key),
                                    // so decode the identity columns for
                                    // every candidate and defer `_source`
                                    // until the segment loop has picked the
                                    // page's winners (see the hydration
                                    // after the loop). The first segment a
                                    // page meets has no score floor, so
                                    // without this a broad query decoded the
                                    // whole stored section inline to show
                                    // five hits (~1.45 s on a 131 MB
                                    // section).
                                    let mut cold_ids: Option<HashMap<u32, String>> = None;
                                    let cold_rows: Option<HashMap<u32, Value>> = if self
                                        .stored_slices_cache
                                        .contains_key(seg_id.as_str())
                                        || self.decoded_stored_cache.contains_key(seg_id.as_str())
                                    {
                                        None
                                    } else if sort_topk.is_none() {
                                        let entry_worst = page_worst.as_ref().map(|worst| worst.0);
                                        // A superset of the rows the walk can
                                        // visit: the threshold only tightens.
                                        let candidates: Vec<u32> = seg_hits
                                            .iter()
                                            .take_while(|sh| {
                                                entry_worst.is_none_or(|worst| sh.score >= worst)
                                            })
                                            .map(|sh| sh.doc_id)
                                            .collect();
                                        if !candidates.is_empty() {
                                            cold_ids =
                                                self.cold_fts_row_ids(seg_id.as_str(), &candidates);
                                        }
                                        if cold_ids.is_some() {
                                            self.cold_row_hydrations
                                                .fetch_add(1, Ordering::Relaxed);
                                            self.schedule_cold_stored_warm(
                                                seg_id.as_str(),
                                                meta.doc_count,
                                            );
                                        }
                                        None
                                    } else {
                                        // A field sort offers every match to
                                        // the top-N heap, so its candidates
                                        // are all matches: decode a bounded
                                        // score-ordered window and read any
                                        // row past it from the full decode.
                                        let mut candidates: Vec<u32> =
                                            seg_hits.iter().map(|sh| sh.doc_id).collect();
                                        let window =
                                            materialisation_limit.saturating_mul(4).max(256);
                                        if candidates.len() > window {
                                            candidates.truncate(window);
                                            cold_window_truncated = true;
                                        }
                                        // Only with a column projection: the
                                        // stored columns are whole-stream
                                        // zstd, so an unprojected row decode
                                        // decompresses every column anyway —
                                        // the full cost — without leaving the
                                        // offset index behind, and the
                                        // background warm then pays it a
                                        // second time (measured: a `_savings`
                                        // request's first cold query went
                                        // 2.3 s -> 6.6 s). The full decode
                                        // below caches for the next query.
                                        let worth_it = fts_row_keep.is_some();
                                        if worth_it && !candidates.is_empty() {
                                            let rows = self.hydrate_fts_rows_cold(
                                                seg_id.as_str(),
                                                &candidates,
                                                fts_row_keep.as_deref(),
                                            );
                                            if rows.is_some() {
                                                self.cold_row_hydrations
                                                    .fetch_add(1, Ordering::Relaxed);
                                                self.schedule_cold_stored_warm(
                                                    seg_id.as_str(),
                                                    meta.doc_count,
                                                );
                                            }
                                            rows
                                        } else {
                                            None
                                        }
                                    };
                                    let slices_opt = if cold_rows.is_some() || cold_ids.is_some() {
                                        None
                                    } else {
                                        self.stored_slices_for(seg_id.as_str(), meta.doc_count)
                                    };
                                    // Legacy whole-section fallback ONLY when the
                                    // offset index can't be built (open/decode
                                    // failure or a malformed/incomplete section).
                                    // Merge-race hardening (2026-07): a genuine
                                    // segment-open failure must FAIL the query
                                    // (`?`), not silently shrink its results —
                                    // under the read-lease fix the files are
                                    // guaranteed present, so an open error is
                                    // real corruption.
                                    let whole_fallback: Option<Vec<Value>> = if slices_opt.is_some()
                                        || cold_rows.is_some()
                                        || cold_ids.is_some()
                                    {
                                        None
                                    } else {
                                        let seg_reader = self.store.open_segment_arc(&seg_id)?;
                                        match seg_reader.section(SectionType::Stored) {
                                            Ok(Some(raw)) => {
                                                match xerj_storage::stored_codec::decode_stored(raw)
                                                {
                                                    // serde_json — see ffd49ac,
                                                    // simd_json silently
                                                    // corrupts some M7
                                                    // raw-bytes payloads.
                                                    Ok(b) => {
                                                        serde_json::from_slice::<Vec<Value>>(&b)
                                                            .ok()
                                                    }
                                                    Err(_) => None,
                                                }
                                            }
                                            _ => None,
                                        }
                                    };
                                    if cold_rows.is_some()
                                        || cold_ids.is_some()
                                        || slices_opt.is_some()
                                        || whole_fallback.is_some()
                                    {
                                        // Owned parsed doc for a stored position,
                                        // shared by both source layouts.  The
                                        // slice arm parses one object on demand;
                                        // the fallback clones from the fully
                                        // decoded Vec.
                                        let past_window: std::cell::OnceCell<
                                            Option<Resident<StoredSlices>>,
                                        > = std::cell::OnceCell::new();
                                        let fetch_doc = |pos: u32| -> Option<Value> {
                                            if let Some(ids) = cold_ids.as_ref() {
                                                // Identity only: `_source` is
                                                // hydrated for the winners
                                                // after the segment loop.
                                                let id = ids.get(&pos)?;
                                                let mut doc = serde_json::Map::with_capacity(1);
                                                doc.insert(
                                                    "_id".to_string(),
                                                    Value::String(id.clone()),
                                                );
                                                return Some(Value::Object(doc));
                                            }
                                            if let Some(rows) = cold_rows.as_ref() {
                                                if let Some(doc) = rows.get(&pos) {
                                                    return Some(doc.clone());
                                                }
                                                if !cold_window_truncated {
                                                    return None;
                                                }
                                                let slices = past_window
                                                    .get_or_init(|| {
                                                        self.stored_slices_for(
                                                            seg_id.as_str(),
                                                            meta.doc_count,
                                                        )
                                                    })
                                                    .as_deref()?;
                                                let &(start, end) =
                                                    slices.offsets.get(pos as usize)?;
                                                let slice = slices
                                                    .bytes
                                                    .get(start as usize..end as usize)?;
                                                serde_json::from_slice::<Value>(slice).ok()
                                            } else if let Some(slices) = slices_opt.as_deref() {
                                                let &(start, end) =
                                                    slices.offsets.get(pos as usize)?;
                                                let slice = slices
                                                    .bytes
                                                    .get(start as usize..end as usize)?;
                                                serde_json::from_slice::<Value>(slice).ok()
                                            } else {
                                                whole_fallback
                                                    .as_ref()
                                                    .and_then(|d| d.get(pos as usize).cloned())
                                            }
                                        };
                                        // #179 — reduce `all_hits` to the best
                                        // `materialisation_limit` hits seen so far
                                        // by the SAME comparator the final page sort
                                        // uses (score DESC, seq_no ASC, `_id` ASC),
                                        // and return the surviving worst PAGE KEY
                                        // (the new cap-th `(score, seq_no, _id)`,
                                        // = the last of the kept set under that
                                        // comparator).  Shared by the in-walk 2×cap
                                        // eager trim and the end-of-run trim so
                                        // admission and final ordering always agree.
                                        #[allow(clippy::type_complexity)]
                                        let trim_to_cap = |hits: Vec<Hit>| -> (
                                            Vec<Hit>,
                                            Option<(f32, u64, String)>,
                                        ) {
                                            self.trim_page_to_cap(hits, materialisation_limit)
                                        };
                                        for sh in &seg_hits {
                                            // `seg_hits` descends by score, so once
                                            // a hit's score is STRICTLY below the
                                            // worst kept score, neither it nor any
                                            // hit after it can displace a kept hit —
                                            // the rest are already counted in
                                            // `total_count`, so stop decoding
                                            // sources.  #179 — `page_worst` is now
                                            // maintained incrementally at the push
                                            // site below, so this early-out fires
                                            // WITHIN the fill-up segment too (once
                                            // the collector first reaches its cap),
                                            // not only in later segments; that is
                                            // what bounds the walk under
                                            // `deletes_present`.  The comparison is
                                            // STRICT (`<`): a hit that TIES the
                                            // worst kept score is still hydrated so
                                            // the trim's comparator (seq_no/`_id`)
                                            // can rank it — a `<=` here would drop
                                            // the tie-winners of a boundary or
                                            // all-equal top cluster and move the
                                            // page.  When a field sort is active we
                                            // must NOT stop: every match has to be
                                            // offered to the bounded top-N heap so
                                            // the survivors are the GLOBAL top-N by
                                            // the sort key, not the highest-scoring
                                            // prefix.
                                            if sort_topk.is_none()
                                                && page_worst
                                                    .as_ref()
                                                    .is_some_and(|worst| sh.score < worst.0)
                                            {
                                                break;
                                            }
                                            let doc = match fetch_doc(sh.doc_id) {
                                                Some(d) => d,
                                                None => continue,
                                            };
                                            let id = doc
                                                .get("_id")
                                                .and_then(Value::as_str)
                                                .unwrap_or("")
                                                .to_string();
                                            // Resolved here, from the SAME
                                            // version-map entry the
                                            // deleted/stale check below
                                            // reads, so `_seq_no`/`_version`
                                            // never diverge from `source`
                                            // (#440).
                                            let mut hit_seq_no = None;
                                            let mut hit_version = None;
                                            if let Some(ver) = self.store.version_map.get(&id) {
                                                // Tombstoned, or SUPERSEDED —
                                                // the live version resides in
                                                // a newer segment or the
                                                // memtable, so this segment's
                                                // stored copy is a stale
                                                // ghost.  Pre-fix only
                                                // `deleted` was checked and
                                                // the OLDEST segment's copy
                                                // won the `seen_ids` dedup:
                                                // `_search` served the stale
                                                // gen-0 `_source` for
                                                // overwritten ids while
                                                // `GET /_doc` returned gen-1
                                                // (b7 DEFECT 1c).
                                                //
                                                // #1212: the check is
                                                // CAPTURE-SCOPED. A merge or
                                                // flush that published after
                                                // this capture repoints the
                                                // live entry at a segment the
                                                // frozen snapshot never held;
                                                // the old equality check then
                                                // dropped every hit from the
                                                // merged-away segments and
                                                // the page came back short or
                                                // empty with `timed_out`
                                                // absent. PostCapture keeps
                                                // the hit (the captured
                                                // world's live copy) and
                                                // declines to report the
                                                // later world's seq/version.
                                                match captured_verdict_for_segment_hit(
                                                    &ver,
                                                    seg_id.as_str(),
                                                    &captured_segment_ids,
                                                ) {
                                                    CapturedEntryVerdict::Invisible => continue,
                                                    CapturedEntryVerdict::Live => {
                                                        let (s, v) =
                                                            self.hit_seq_version(&id, &ver);
                                                        hit_seq_no = s;
                                                        hit_version = v;
                                                    }
                                                    CapturedEntryVerdict::PostCapture => {}
                                                }
                                            }
                                            // Dedup against memtable/earlier
                                            // segments WITHOUT touching
                                            // `total_count` (already tallied
                                            // above via `seg_total`).
                                            if seen_ids.contains(&id) {
                                                continue;
                                            }
                                            let source =
                                                doc.get("_source").cloned().unwrap_or(Value::Null);
                                            seen_ids.insert(id.clone());
                                            if cold_ids.is_some() {
                                                deferred_sources.insert(
                                                    id.clone(),
                                                    (seg_id.to_string(), sh.doc_id, meta.doc_count),
                                                );
                                            } else if cold_rows.is_some() && fts_row_keep.is_some()
                                            {
                                                row_projected.insert(
                                                    id.clone(),
                                                    (seg_id.to_string(), sh.doc_id),
                                                );
                                            }
                                            let hit = Hit {
                                                id,
                                                score: sh.score,
                                                source,
                                                seq_no: hit_seq_no,
                                                version: hit_version,
                                                sort: Vec::new(),
                                                explain: None,
                                                highlight: None,
                                                matched_queries: Vec::new(),
                                                passage: None,
                                            };
                                            if let Some(topk) = sort_topk.as_mut() {
                                                let seq = hit_seq_no.unwrap_or(u64::MAX);
                                                topk.offer(hit, seq, self);
                                            } else {
                                                all_hits.push(hit);
                                                // #179 — hold the collector at
                                                // O(cap).  Once it first reaches the
                                                // cap, establish `page_worst` so the
                                                // STRICT early-out above can stop the
                                                // walk within this very segment; once
                                                // it exceeds 2×cap, trim back to the
                                                // best cap by the final comparator
                                                // and refresh `page_worst` to the new
                                                // cap-th key.  Between cap and 2×cap
                                                // no recompute is needed: `page_worst`
                                                // is established the instant the
                                                // collector holds exactly `cap` hits,
                                                // so it IS the cap-th key at that
                                                // moment, and every later push can only
                                                // improve the true cap-th key.  A stale
                                                // `page_worst` is therefore a WEAKER
                                                // threshold than the truth — it admits
                                                // more than strictly necessary, never
                                                // less, which is the safe direction.
                                                if all_hits.len() >= materialisation_limit {
                                                    if all_hits.len()
                                                        > materialisation_limit.saturating_mul(2)
                                                    {
                                                        let (kept, worst) = trim_to_cap(
                                                            std::mem::take(&mut all_hits),
                                                        );
                                                        all_hits = kept;
                                                        page_worst = worst;
                                                    } else if page_worst.is_none() {
                                                        page_worst = self.worst_page_key(&all_hits);
                                                    }
                                                }
                                            }
                                        }
                                        // #177 — trim the overflow back to the cap
                                        // by SCORE, so what survives into the next
                                        // segment is the best `materialisation_limit`
                                        // seen so far rather than the oldest.  The
                                        // comparator is the one the post-loop page
                                        // sort uses (score DESC, seq_no ASC, `_id`
                                        // ASC), so admission and final ordering
                                        // agree and the page is stable under any
                                        // cap: `size:1` and `size:200` return the
                                        // same top hit, and adding `highlight`
                                        // returns the same page.  #179 — the in-walk
                                        // eager trim already caps `all_hits` at
                                        // 2×cap during the segment; this end-of-run
                                        // trim is the final normalisation back to
                                        // exactly the cap before the next segment.
                                        if sort_topk.is_none()
                                            && all_hits.len() > materialisation_limit
                                        {
                                            // `page_worst` is recomputed fresh at the
                                            // next segment's entry, so the trimmed
                                            // worst is not needed past here.
                                            let (kept, _worst) =
                                                trim_to_cap(std::mem::take(&mut all_hits));
                                            all_hits = kept;
                                        }
                                    }
                                }
                            }
                        }
                    } // close fts_has_field
                }

                // Propagate an FTS expansion deadline trip into the
                // response-level flag (RC4 blocker 12): the segment's FTS
                // hits/total above are partial, so the response must carry
                // `timed_out: true` even if this was the last segment (no
                // later between-segment check would run).
                if fts_deadline_tripped {
                    deadline_exceeded = true;
                }

                // If FTS didn't handle it, fall through to stored-doc scan.
                // This covers MatchAll (no FTS query), term-level queries
                // that are routed through doc scan, AND segments missing
                // FTS sidecars (e.g. after M5.4 flush which skips FTS build).
                // When `needs_fts` was true but the reader failed to open,
                // we degrade to stored-section scan so the query still
                // returns correct results (just slower).
                let scan_stored = scan_stored || (needs_fts && !fts_handled);
                if !fts_handled && scan_stored {
                    #[cfg(test)]
                    SEG_STORED_SCANS.with(|c| c.set(c.get() + 1));
                    // #361 — this segment's hits are scored by
                    // `score_query_against_doc` (no IDF, no length norm), so
                    // the page mixes score scales and the IDF rescore below
                    // stays armed.
                    heuristic_scored_applied = true;
                    // M2 G3: for Range queries, compute the matching doc-id
                    // set from the segment's on-disk sorted numeric index
                    // and pass it as a pre-filter so `scan_stored_section_into`
                    // only parses those specific positions.
                    // Field-sort candidate set for THIS segment (page-ordered
                    // positions + primary keys) — set when the bounded
                    // sorted-candidates path is provably safe; the plain
                    // position pre-filter below is derived from it.
                    let mut sort_cand: Option<SortCandidates> = None;
                    let pre_filter: Option<Arc<PrefilterSet>> = if let QueryNode::Range {
                        field,
                        gte,
                        gt,
                        lte,
                        lt,
                        ..
                    } = query
                    {
                        // The sorted-narrowing path below consumes the
                        // COMPLETE match set whatever its size (the top-cap
                        // cut needs every candidate) — only that caller may
                        // request an uncapped build.  Plain scans cap at the
                        // term-prefilter ceiling: broader sets don't help
                        // the F1 early-break scan and their O(matches)
                        // HashSet build is the post-merge p99 cliff.
                        let wants_narrowing = sort_topk.is_some()
                            && shortcut_count.is_some()
                            && !deletes_present
                            && !count_only;
                        let base = self.build_range_prefilter_cached(
                            &segments_dir,
                            &seg_id,
                            field,
                            gte.as_ref(),
                            gt.as_ref(),
                            lte.as_ref(),
                            lt.as_ref(),
                            if wants_narrowing {
                                usize::MAX
                            } else {
                                RANGE_PREFILTER_CAP
                            },
                        );
                        // Field-sorted Range whose exact total comes from
                        // the dv shortcut: narrow the (possibly huge)
                        // match set to the per-segment top-cap by sort
                        // key (+ boundary ties) — every candidate is a
                        // genuine range match, so the bounded hydration
                        // path applies and the heap sees exactly the
                        // candidates that can reach the page.  The
                        // scan-tallied total is partial by design and is
                        // overwritten with `shortcut_count` post-loop
                        // (`sort_candidates_narrowed`).
                        if let (Some(topk), Some(base_set)) = (sort_topk.as_ref(), base.as_ref()) {
                            if shortcut_count.is_some() && !deletes_present && !count_only {
                                sort_cand = self.narrow_matches_to_sort_candidates(
                                    &segments_dir,
                                    &seg_id,
                                    meta.doc_count,
                                    topk,
                                    materialisation_limit,
                                    &base_set.set,
                                );
                            }
                        }
                        match &sort_cand {
                            Some(sc) => Some(Arc::new(PrefilterSet::from_set(sc.set.clone()))),
                            None => base,
                        }
                    } else if let QueryNode::Term { field, value, .. } = query {
                        // Selective `term`: parse only the matching stored
                        // positions instead of the whole section (id lookups,
                        // `code:500`). Without a field sort the builder's
                        // complete set feeds the bounded arrival-order
                        // collector; WITH a field sort the complete set used
                        // to be offered wholesale to the top-N heap —
                        // O(matches) simd_json parses per query (~185 ms for
                        // a 37k-match term on the 100k bench corpus, vs ES
                        // ~2 ms). Narrow it to the per-segment top-cap by
                        // primary sort key exactly like the Range arm above:
                        // the term prefilter set is EXACT (every position is
                        // a genuine match), the scan-tallied total is partial
                        // by design and overwritten with `shortcut_count`
                        // post-loop (`sort_candidates_narrowed`).
                        if let Some(topk) = sort_topk.as_ref() {
                            if shortcut_count.is_some() && !deletes_present && !count_only {
                                sort_cand = self.narrow_term_values_to_sort_candidates(
                                    &segments_dir,
                                    &seg_id,
                                    meta.doc_count,
                                    topk,
                                    materialisation_limit,
                                    field,
                                    std::slice::from_ref(value),
                                );
                            }
                        }
                        match &sort_cand {
                            Some(sc) => Some(Arc::new(PrefilterSet::from_set(sc.set.clone()))),
                            // An analyzed `text` field's column holds raw
                            // values, not tokens: its term set is not a
                            // superset of the scan's matches, so decline
                            // (`None` → full stored scan, which answers per
                            // the pre-flush hit set — see
                            // `field_is_analyzed_text`).
                            None if field_is_analyzed_text(&dmq_schema, field) => None,
                            None => self.build_term_prefilter_cached(
                                &segments_dir,
                                &seg_id,
                                field,
                                std::slice::from_ref(value),
                            ),
                        }
                    } else if let QueryNode::Terms { field, values, .. } = query {
                        // Same field-sort narrowing as the Term arm (the
                        // candidate set is the exact union of per-value
                        // match sets).
                        if let Some(topk) = sort_topk.as_ref() {
                            if shortcut_count.is_some() && !deletes_present && !count_only {
                                sort_cand = self.narrow_term_values_to_sort_candidates(
                                    &segments_dir,
                                    &seg_id,
                                    meta.doc_count,
                                    topk,
                                    materialisation_limit,
                                    field,
                                    values,
                                );
                            }
                        }
                        match &sort_cand {
                            Some(sc) => Some(Arc::new(PrefilterSet::from_set(sc.set.clone()))),
                            // Same analyzed-`text` decline as the Term arm
                            // above: the column stores raw values, so a set
                            // built from it would drop every token-only match.
                            None if field_is_analyzed_text(&dmq_schema, field) => None,
                            None => self.build_term_prefilter_cached(
                                &segments_dir,
                                &seg_id,
                                field,
                                values,
                            ),
                        }
                    } else if let QueryNode::Ids { values } = query {
                        // Resolve primary keys to stored positions via the
                        // per-segment id index (the GET `_doc/{id}` / `_mget`
                        // lookup), so an `ids` query hydrates O(#ids) positions
                        // instead of scanning the whole collection.  Gated on
                        // `!deletes_present`: with overwrites/tombstones a live
                        // id can occupy positions in more than one segment, so
                        // the scan's delete-aware `_id` matching is used
                        // instead.
                        if deletes_present {
                            None
                        } else {
                            self.build_ids_prefilter_cached(&seg_id, meta.doc_count, values)
                        }
                    } else if matches!(query, QueryNode::Bool { .. }) {
                        // Pure-conjunction bool: parse only the most-selective
                        // conjunct's docs; `doc_matches_query` re-tests the full
                        // bool per admitted doc (superset filter).
                        //
                        // A bool carrying a term/terms leaf on an analyzed
                        // `text` field has no valid doc-values anchor at all
                        // (see `field_is_analyzed_text`) — decline the whole
                        // prefilter, the stored scan answers.
                        if has_analyzed_text_term_leaf(query, &dmq_schema) {
                            None
                        } else {
                            self.build_bool_prefilter_cached(&segments_dir, &seg_id, query)
                        }
                    } else if is_match_all && !deletes_present {
                        // Sorted-DV candidate pruning for field-sorted
                        // match_all: the segment's sorted numeric
                        // doc-values index yields the only positions that
                        // can reach the global top-(from+size) page —
                        // including the `search_after` cursor bound — so
                        // the stored scan parses O(from+size) docs per
                        // segment instead of every doc.  `None` when the
                        // shape isn't provably safe (non-numeric field,
                        // nulls/arrays present, dv/stored misalignment,
                        // deletes) → full scan, still correct.
                        sort_cand = sort_topk.as_ref().and_then(|topk| {
                            self.build_sort_candidates_prefilter(
                                &segments_dir,
                                &seg_id,
                                meta.doc_count,
                                topk,
                                materialisation_limit,
                            )
                        });
                        sort_cand
                            .as_ref()
                            .map(|sc| Arc::new(PrefilterSet::from_set(sc.set.clone())))
                    } else if let QueryNode::Regexp {
                        field,
                        pattern,
                        case_insensitive,
                    } = query
                    {
                        // Dictionary-expansion pre-filter (mirrors the
                        // `try_shortcut_count` Regexp arm).  When the
                        // exact total comes from the shortcut
                        // (count_authoritative) AND the hits collector is
                        // the arrival-order bounded `all_hits` (no field
                        // sort), the scan early-breaks at
                        // `materialisation_limit` hits, so cap the
                        // position set there; otherwise the scan must
                        // visit EVERY match — to tally the exact total
                        // and/or to offer every match to the field-sort
                        // top-N heap — so only a COMPLETE position set is
                        // a valid filter.
                        //
                        // The `sort_topk.is_none()` gate is load-bearing:
                        // with a field sort active (incl. the implicit
                        // `@timestamp desc` index sort injected by the ES
                        // layer for time-series mappings) hits bypass
                        // `all_hits`, so the caller's early-break and the
                        // post-loop `scan_hit_cap` shortcut-count
                        // overwrite NEVER fire — a capped prefilter would
                        // leak `segments × materialisation_limit` into
                        // `hits.total` (the 512-vs-847306 bench
                        // regression) and starve the top-N heap of
                        // candidates.
                        let cap = if count_authoritative && sort_topk.is_none() {
                            Some(materialisation_limit)
                        } else {
                            None
                        };
                        // #1812: the dictionary expansion compiles this same
                        // pattern, so it must carry the inline `(?i)` flag too
                        // — a case-sensitive expansion would pre-filter away
                        // exactly the hits the (case-insensitive) doc-scan arm
                        // would have matched.  This arm is a CANDIDATE filter:
                        // the scan re-checks every position against
                        // `doc_matches_query`, so a folded (wider) candidate
                        // set is safe for any field type, and required for
                        // keyword (where the doc-scan folds too).
                        if *case_insensitive {
                            let folded = format!("(?i){}", pattern);
                            self.build_regexp_prefilter_cached(
                                &segments_dir,
                                &seg_id,
                                field,
                                &folded,
                                cap,
                                regexp_field_is_keyword,
                            )
                            .map(|s| Arc::new(PrefilterSet::from_set(s)))
                        } else {
                            self.build_regexp_prefilter_cached(
                                &segments_dir,
                                &seg_id,
                                field,
                                pattern,
                                cap,
                                regexp_field_is_keyword,
                            )
                            .map(|s| Arc::new(PrefilterSet::from_set(s)))
                        }
                    } else {
                        None
                    };

                    // A `Some(∅)` pre-filter proves no doc in this segment can
                    // contribute a hit or a count (Range: no value in range;
                    // sorted-DV: no candidate position): skip the open +
                    // decompress + brace-scan entirely — the scan would have
                    // skipped every position anyway.
                    // Sorted-DV candidate path (field-sorted match_all with a
                    // candidate pre-filter): serve the candidates from the
                    // per-segment `stored_slices_cache` when warm — two vec
                    // lookups + O(candidates) simd_json parses, no per-query
                    // decompress and no O(segment-bytes) brace re-scan.
                    let sorted_candidates_path = sort_topk.is_some() && sort_cand.is_some();
                    if sorted_candidates_path && !is_match_all {
                        // The scan/hydrate below visits only the narrowed
                        // candidates, so its total tally is partial — flag
                        // the post-loop `shortcut_count` overwrite.
                        sort_candidates_narrowed = true;
                    }

                    if pre_filter.as_ref().is_some_and(|pf| pf.is_empty()) {
                        // A `Some(∅)` pre-filter proves no doc in this segment
                        // can contribute a hit or a count (Range: no value in
                        // range; sorted-DV: no candidate position): skip the
                        // open + decompress + brace-scan entirely — the scan
                        // would have skipped every position anyway.
                    } else if sorted_candidates_path
                        && sort_cand
                            .as_ref()
                            .and_then(|sc| sc.ordered.first())
                            .zip(sort_topk.as_ref())
                            .is_some_and(|(&(kb, _), topk)| {
                                topk.primary_f64_rejects(f64::from_bits(kb as u64))
                            })
                    {
                        // This segment's BEST candidate already loses to the
                        // full heap on the primary key — every candidate does
                        // (page order).  Skip the segment without touching
                        // its stored bytes.  The partial tally is overwritten
                        // post-loop (live count / shortcut).
                    } else if sorted_candidates_path && {
                        // Warm-or-build slices, then hydrate ONLY the
                        // page-ordered candidates (pre-parse primary-key
                        // rejection inside).  `false` (slices unavailable —
                        // genuine decode failure) falls through to the
                        // legacy full-scan arm below.
                        let t_dec = std::time::Instant::now();
                        let slices_opt = self.stored_slices_for(seg_id.as_str(), meta.doc_count);
                        dbg_decode_ms += t_dec.elapsed().as_millis() as u64;
                        match slices_opt {
                            Some(slices) => {
                                let t_scan = std::time::Instant::now();
                                self.hydrate_sorted_candidates(
                                    &slices,
                                    sort_cand.as_ref().expect("gated on is_some"),
                                    query,
                                    is_match_all,
                                    ids_only,
                                    sort_topk.as_mut().expect("gated on is_some"),
                                    &mut seen_ids,
                                    &mut total_count,
                                    score_doc,
                                );
                                dbg_scan_ms += t_scan.elapsed().as_millis() as u64;
                                true
                            }
                            None => false,
                        }
                    } {
                        // handled above
                    } else if let Some(cached_bytes) = (!sorted_candidates_path)
                        .then(|| {
                            self.decoded_stored_cache
                                .get(seg_id.as_str())
                                .map(|e| Arc::clone(e.value()))
                        })
                        .flatten()
                    {
                        // Decoded-bytes cache hit: skip open + decompress
                        // entirely.  With the in-section early stop, the
                        // whole per-segment cost is now O(from+size) doc
                        // parses instead of O(section) decompress+parse.
                        let t_scan = std::time::Instant::now();
                        self.scan_stored_section_into(
                            &cached_bytes,
                            query,
                            is_match_all,
                            ids_only,
                            count_only,
                            scan_limit,
                            count_authoritative,
                            &mut total_count,
                            &mut all_hits,
                            &mut seen_ids,
                            pre_filter.as_deref().map(|p| &p.set),
                            sort_topk.as_mut(),
                            None,
                            Some(search_deadline),
                            &mut deadline_exceeded,
                            &mut dbg_walked,
                            &mut dbg_admitted,
                            score_doc,
                            &dmq_schema,
                        );
                        dbg_scan_ms += t_scan.elapsed().as_millis() as u64;
                    } else if let Some(warm_slices) = (!sorted_candidates_path)
                        .then(|| {
                            self.stored_slices_cache
                                .get(seg_id.as_str())
                                .map(|e| Arc::clone(e.value()))
                        })
                        .flatten()
                    {
                        // Unsorted scan (bool/range, no implicit sort) reusing
                        // the merge/flush-warmed `StoredSlices`.  `slices.bytes`
                        // IS the decoded stored section — bit-identical to what
                        // `decoded_stored_cache` would hold — so the FIRST
                        // bool/range query after a merge scans it directly
                        // instead of paying a fresh multi-100 MB decompress.
                        // `warm_segment_at_publish` pre-warms `stored_slices_cache`
                        // (the sorted-candidate source) but NOT
                        // `decoded_stored_cache`; without this arm the unsorted
                        // arm re-decompressed the merged segment on its next
                        // touch (live dec=1.1-3.8 s spikes at every merge
                        // completion under the mixed read/write bench).  No
                        // extra memory: the warmed bytes are shared, not copied.
                        let t_scan = std::time::Instant::now();
                        // F2: with warm slices we have the per-doc offset index,
                        // so an UNSORTED pre-filtered query (selective term /
                        // terms / conjunction bool) random-accesses only its
                        // matching positions instead of brace-walking the whole
                        // section — the O(section bytes)→O(|pre_filter|) fix for
                        // a term fanned across every shard-segment. Sorted or
                        // no-pre-filter queries keep the linear scan.
                        match pre_filter.as_deref() {
                            Some(pf) if sort_topk.is_none() => {
                                self.hydrate_prefiltered_unsorted(
                                    &warm_slices,
                                    pf,
                                    query,
                                    is_match_all,
                                    ids_only,
                                    count_only,
                                    scan_limit,
                                    count_authoritative,
                                    &mut total_count,
                                    &mut all_hits,
                                    &mut seen_ids,
                                    score_doc,
                                    &dmq_schema,
                                );
                            }
                            _ => {
                                self.scan_stored_section_into(
                                    &warm_slices.bytes,
                                    query,
                                    is_match_all,
                                    ids_only,
                                    count_only,
                                    scan_limit,
                                    count_authoritative,
                                    &mut total_count,
                                    &mut all_hits,
                                    &mut seen_ids,
                                    pre_filter.as_deref().map(|p| &p.set),
                                    sort_topk.as_mut(),
                                    None,
                                    Some(search_deadline),
                                    &mut deadline_exceeded,
                                    &mut dbg_walked,
                                    &mut dbg_admitted,
                                    score_doc,
                                    &dmq_schema,
                                );
                            }
                        }
                        dbg_scan_ms += t_scan.elapsed().as_millis() as u64;
                    } else {
                        // Merge-race hardening (2026-07): a snapshot
                        // segment that fails to open is a query error, not
                        // a segment to skip — skipping silently undercounts
                        // hits.total (the observed 798,281-of-932,037 bug).
                        // With the read lease held by `snap`, retired
                        // segment files persist, so this only fires on
                        // genuine corruption.
                        let t_dec = std::time::Instant::now();
                        // SINGLE-FLIGHT the cold decode: without this, N
                        // concurrent requests racing the same cold segment
                        // (every dashboard panel's first query after a
                        // restart, or against any never-before-queried
                        // segment) each paid their own full open+decompress
                        // independently — measured ~4.5s/request under a
                        // real 24-way concurrent burst, collapsing to
                        // 1-5ms once any one of them had warmed the cache.
                        // Same lock registry `stored_slices_for` already
                        // uses for this exact reason on the sorted path.
                        let flight = {
                            let entry = self
                                .stored_slices_build_locks
                                .entry(seg_id.clone())
                                .or_default();
                            Arc::clone(entry.value())
                        };
                        let _flight_guard = flight.lock().ok();
                        // Re-check both caches now that we hold this
                        // segment's flight lock — another thread may have
                        // decoded and published while we waited.
                        // #2427: hold the cached entry by `Arc` instead of
                        // cloning the whole decoded section (hundreds of MB
                        // per waiter on a large segment).
                        enum ColdBytes<D, S> {
                            Decoded(D),
                            Slices(S),
                            // `bool`: column-projected (never cached).
                            Fresh(Vec<u8>, bool),
                        }
                        let cached = self
                            .decoded_stored_cache
                            .get(seg_id.as_str())
                            .map(|e| ColdBytes::Decoded(Arc::clone(e.value())))
                            .or_else(|| {
                                self.stored_slices_cache
                                    .get(seg_id.as_str())
                                    .map(|e| ColdBytes::Slices(Arc::clone(e.value())))
                            });
                        // #2427: an unsorted scan whose page can observe only
                        // a known column set (`fts_row_keep`: the `_source`
                        // includes plus every field the query reads) decodes
                        // just those columns. On a semantic_text corpus the
                        // generated `*_vector` / `*_vector_chunks` / passage
                        // metadata columns are ~85% of a full decode and of
                        // its transient peak (20k-doc segment: ~716 MB peak
                        // full vs ~82 MB projected), none of which the
                        // response can return. Projected bytes are never
                        // published to `decoded_stored_cache`.
                        let scan_keep: Option<&[String]> =
                            if sorted_candidates_path || sort_topk.is_some() {
                                None
                            } else {
                                fts_row_keep.as_deref()
                            };
                        let stored_src = if cached.is_some() {
                            cached
                        } else {
                            let seg_reader = self.store.open_segment_arc(&seg_id)?;
                            match seg_reader.section(SectionType::Stored) {
                                Ok(Some(stored_bytes_raw)) => {
                                    let projected = scan_keep.and_then(|keep| {
                                        xerj_storage::stored_codec::decode_stored_keeping(
                                            stored_bytes_raw,
                                            &|column: &str| {
                                                row_projection_keeps_column(keep, column)
                                            },
                                        )
                                        .ok()
                                        .flatten()
                                    });
                                    match projected {
                                        Some(bytes) => Some(ColdBytes::Fresh(bytes, true)),
                                        None => xerj_storage::stored_codec::decode_stored(
                                            stored_bytes_raw,
                                        )
                                        .ok()
                                        .map(|bytes| ColdBytes::Fresh(bytes, false)),
                                    }
                                }
                                _ => None,
                            }
                        };
                        dbg_decode_ms += t_dec.elapsed().as_millis() as u64;
                        if let Some(stored_src) = stored_src {
                            {
                                let t_scan = std::time::Instant::now();
                                let stored_bytes: &[u8] = match &stored_src {
                                    ColdBytes::Decoded(entry) => entry.value(),
                                    ColdBytes::Slices(slices) => &slices.bytes,
                                    ColdBytes::Fresh(bytes, _) => bytes,
                                };
                                let projected = matches!(stored_src, ColdBytes::Fresh(_, true));
                                // Record per-doc offsets on the sorted path so
                                // the decompressed section can be cached for
                                // the next query (subject to the budget).
                                let mut offsets: Vec<(u32, u32)> = Vec::new();
                                let want_cache = sorted_candidates_path
                                    && !projected
                                    && stored_bytes.len() <= u32::MAX as usize
                                    && !self.stored_slices_cache.contains_key(seg_id.as_str());
                                self.scan_stored_section_into(
                                    stored_bytes,
                                    query,
                                    is_match_all,
                                    ids_only,
                                    count_only,
                                    scan_limit,
                                    count_authoritative,
                                    &mut total_count,
                                    &mut all_hits,
                                    &mut seen_ids,
                                    pre_filter.as_deref().map(|p| &p.set),
                                    sort_topk.as_mut(),
                                    if want_cache { Some(&mut offsets) } else { None },
                                    Some(search_deadline),
                                    &mut deadline_exceeded,
                                    &mut dbg_walked,
                                    &mut dbg_admitted,
                                    score_doc,
                                    &dmq_schema,
                                );
                                dbg_scan_ms += t_scan.elapsed().as_millis() as u64;
                                if projected {
                                    for hit in all_hits.iter().skip(hits_before_segment) {
                                        scan_projected.insert(hit.id.clone(), seg_id.clone());
                                    }
                                }
                                // Cache only a COMPLETE offsets map (a
                                // malformed section bails early) and only
                                // within the retained-bytes budget.
                                if want_cache && offsets.len() as u64 == meta.doc_count {
                                    let slices = StoredSlices {
                                        bytes: match stored_src {
                                            ColdBytes::Fresh(bytes, _) => bytes,
                                            // Promote a decoded-cache entry
                                            // into the sorted-path cache.
                                            ColdBytes::Decoded(entry) => entry.value().clone(),
                                            ColdBytes::Slices(slices) => slices.bytes.clone(),
                                        },
                                        offsets,
                                    };
                                    let bytes = cache_estimates::stored_slices_bytes(
                                        &seg_id,
                                        std::mem::size_of::<CacheResident<StoredSlices>>(),
                                        slices.bytes.capacity(),
                                        slices.offsets.capacity(),
                                    );
                                    let _ = self.publish_current(
                                        &self.stored_slices_cache,
                                        &seg_id,
                                        seg_id.clone(),
                                        SegmentCacheCategory::StoredSlices,
                                        bytes,
                                        slices,
                                    );
                                } else if let (false, ColdBytes::Fresh(stored_bytes, false)) =
                                    (want_cache, stored_src)
                                {
                                    // Unsorted path: retain the decompressed
                                    // section so the NEXT query on this
                                    // segment skips the decompress (the
                                    // read-under-write match_all/bool/range
                                    // tail fix — see `decoded_stored_cache`).
                                    // Only a fresh FULL decode: a cache hit
                                    // is already resident, and projected
                                    // bytes would serve other queries a
                                    // partial `_source`.
                                    let bytes = cache_estimates::decoded_stored_bytes(
                                        &seg_id,
                                        std::mem::size_of::<CacheResident<Vec<u8>>>(),
                                        stored_bytes.capacity(),
                                    );
                                    let _ = self.publish_current(
                                        &self.decoded_stored_cache,
                                        &seg_id,
                                        seg_id.clone(),
                                        SegmentCacheCategory::DecodedStored,
                                        bytes,
                                        stored_bytes,
                                    );
                                }
                            }
                        }
                    }
                }

                // #191 — cross-segment merge for the stored-scan path.  This
                // segment was allowed its own `materialisation_limit` of
                // headroom (see `scan_limit`), so reduce back to the global
                // best `cap` by the SAME comparator the final page sort uses
                // (score DESC, `seq_no` ASC, `_id` ASC) and refresh the skip
                // bound.  Without it the collector kept whichever segment
                // reached the cap first — segment-list order — rather than the
                // documents the page sort would pick, so a bounded page and a
                // full page named different documents whenever scores tied.
                // Trimmed hits stay in `seen_ids`: the cap-th key only ever
                // improves, so a document that lost the trim can never become
                // competitive again.
                if !fts_handled
                    && !count_only
                    && sort_topk.is_none()
                    && all_hits.len() != hits_before_segment
                    && all_hits.len() >= materialisation_limit
                {
                    let mut decorated: Vec<(u64, Hit)> = std::mem::take(&mut all_hits)
                        .into_iter()
                        .map(|h| (self.lookup_seq_no(&h.id).unwrap_or(u64::MAX), h))
                        .collect();
                    decorated.sort_by(|a, b| {
                        b.1.score
                            .partial_cmp(&a.1.score)
                            .unwrap_or(std::cmp::Ordering::Equal)
                            .then_with(|| a.0.cmp(&b.0))
                            .then_with(|| a.1.id.cmp(&b.1.id))
                    });
                    decorated.truncate(materialisation_limit);
                    scan_page_worst = decorated
                        .last()
                        .map(|(seq, h)| (h.score, *seq, h.id.clone()));
                    all_hits = decorated.into_iter().map(|(_, h)| h).collect();
                }
            }
        }
        if !deferred_sources.is_empty() {
            all_hits = self.hydrate_deferred_cold_sources(
                all_hits,
                &deferred_sources,
                fts_row_keep.as_deref(),
                &mut row_projected,
            );
        }
        drop(snap);

        // F1: did the bounded collector fill to the cap?  If so the stored-doc
        // scan may have STOPPED early (count_authoritative), so its
        // `total_count` is only a partial tally and must be replaced by the
        // authoritative shortcut count below.  If it did NOT fill to the cap,
        // every match was visited and `total_count` is already EXACT — and it
        // faithfully reflects full query semantics (flattened / subobjects:false
        // / passthrough field resolution the doc-values shortcut can't model),
        // so we keep it and never overwrite.
        phase_marks.push(("segment_loop", phase_t0.elapsed().as_millis() as u64));
        let scan_hit_cap: bool = all_hits.len() >= materialisation_limit;

        // De-duplication is already enforced by `seen_ids` inside the
        // bounded collector (`admit_hit!`), so `all_hits` is already unique.
        // Field-sorted queries collected into the bounded top-N heap instead
        // of `all_hits` (which stays empty on that path); drain it here.  The
        // heap already holds only the GLOBAL top-(from+size) by the sort key,
        // so the downstream `final_hits.sort_by` + `skip(from).take(size)`
        // produce the correct page.
        let final_hits: Vec<Hit> = match sort_topk.take() {
            Some(topk) => topk.into_hits(),
            None => all_hits,
        };

        // --- Fill memtable sources (for hits that don't yet have a source) ---
        let mut final_hits = self.fill_memtable_sources(final_hits).await;

        // --- Apply pinned query: boost pinned IDs to the top ---
        // Assign pinned IDs a score higher than any organic result so they sort first.
        // Skipped when the scored-family columnar path ran: it already
        // assigned the EXACT ES pin scores (1.7014…e38 family) and this
        // rewrite would clobber them with the legacy max_organic+1+rank
        // fakes (it also only sees hits already inside the bounded
        // collector, which is why pins never floated on the brute path).
        if scored_fast_applied {
            // exact pin scores already in place
        } else if let QueryNode::Pinned { ids, .. } = query {
            // ES pin scores are sentinel constants descending one float ULP
            // per rank from just above 2^127 (1.7014124e38 for the first pin
            // with two ids — live-verified vs ES 8.13.4).  The columnar
            // Pinned fast path already emits exactly these
            // (`f32::from_bits(0x7F00_0001 + (p - rank))`); use the same
            // formula here so `max_score` (population max, reported even on
            // empty beyond-end pages) and per-hit `_score` values match ES
            // regardless of which execution path served the query.  The old
            // `max_organic + 1 + (p - rank)` fakes leaked small integers
            // (4.0/3.0) into `max_score` where ES reports the sentinel.
            let p = ids.len() as u32;
            for hit in &mut final_hits {
                if let Some(rank) = ids.iter().position(|pid| pid == &hit.id) {
                    hit.score = f32::from_bits(0x7F00_0001_u32 + (p - rank as u32));
                }
            }
        }

        // --- Apply / validate function scores ---
        // B3 (2026-07-10 scorecard, pre-batch-3 defect): the brute stored
        // scan used to score each doc through `score_query_against_doc` —
        // which already composes the function_score — and then this
        // post-loop applied the function a SECOND time, squaring the score
        // on every non-gated shape (any sort/aggs/min_score/max_boost/
        // weight/filter/boost≠1/non-match_all inner, or deletes present).
        //
        // The contract now is:
        //   * brute scan paths score every hit through the `score_doc`
        //     closure, which composes the peeled function_score exactly
        //     ONCE (base → per-function weights → score_mode → max_boost
        //     cap → boost_mode → outer wrapper boost);
        //   * the gated columnar path (`function_score_columnar`) still
        //     emits BASE match_all scores and relies on THIS loop for its
        //     single application (`fs_fast_applied == true`) — unchanged,
        //     keeping the batch-3 verified cell bit-exact;
        //   * either way the loop validates the FINAL score exactly like
        //     ES (`illegal_argument_exception` on NaN/±Inf/negative).
        if let Some((
            QueryNode::FunctionScore {
                functions,
                score_mode,
                boost_mode,
                max_boost,
                ..
            },
            fs_outer_boost,
        )) = peeled_fs
        {
            for (doc_idx, hit) in final_hits.iter_mut().enumerate() {
                let combined = if fs_fast_applied {
                    // Query-level boost multiplies the BASE score
                    // BEFORE the boost_mode combine (Lucene bakes it
                    // into the subquery weight — see `score_doc`).
                    // The columnar gate only fires with boost == 1
                    // (a `Boosted` wrapper defeats it), so this is
                    // currently a no-op kept for order-correctness.
                    let query_score = hit.score * fs_outer_boost;
                    let mut fn_score = apply_function_score(
                        &hit.id,
                        &hit.source,
                        functions,
                        *score_mode,
                        query_score,
                        &dmq_schema,
                    );
                    // ES caps the COMBINED FUNCTION score (not the
                    // final) at `max_boost`, before boost_mode
                    // composition — live-verified on ES 8.13.4:
                    // boost_mode=sum + inner boost 3 + max_boost 100
                    // scores 103, outer boost 2 + max_boost 100
                    // scores 200.
                    if let Some(cap) = max_boost {
                        fn_score = fn_score.min(*cap);
                    }
                    combine_scores(query_score, fn_score, *boost_mode)
                } else {
                    // Brute scan hits already carry the fully-composed
                    // final score (single application in `score_doc`).
                    hit.score
                };
                // ES rejects non-finite or negative scores here with
                // `illegal_argument_exception`. Match the exact reason
                // text so the YAML test's root_cause.reason comparison
                // succeeds.
                if !combined.is_finite() || combined < 0.0 {
                    let label = if combined.is_nan() {
                        "NaN".to_string()
                    } else if combined.is_infinite() {
                        if combined > 0.0 {
                            "Infinity".into()
                        } else {
                            "-Infinity".into()
                        }
                    } else {
                        format!("{combined}")
                    };
                    return Err(EngineError::Common(
                            xerj_common::XerjError::invalid_query(format!(
                                "function score query returned an invalid score: {label} for doc: {doc_idx}; score must be a non-negative real number"
                            )),
                        ));
                }
                hit.score = combined;
            }
        }

        // --- Apply field-value sort (populate hit.sort) ---
        if !request.sort.is_empty() {
            let sort_fields = &request.sort;
            // Populate sort key arrays from source.  `compute_sort_values` is
            // the SAME routine the bounded `SortTopK` collector uses at
            // admission time, so the global top-N selection and this final
            // ordering agree on the exact total order (incl. date-string
            // normalisation).
            for hit in &mut final_hits {
                hit.sort = compute_sort_values(&hit.source, hit.score, &hit.id, sort_fields, self);
            }
            // Sort by the populated sort keys.  Key ties break by seq_no
            // ASC (insertion order == ES internal doc-id order post-B1),
            // the SAME chain as `SortHeapEntry::cmp`, so the heap's
            // eviction choices and this final ordering agree.  `_id` is a
            // last-resort fallback for unresolvable seqs only.
            let mut decorated: Vec<(u64, Hit)> = std::mem::take(&mut final_hits)
                .into_iter()
                .map(|h| (self.lookup_seq_no(&h.id).unwrap_or(u64::MAX), h))
                .collect();
            decorated.sort_by(|a, b| {
                xerj_query::sort::compare_sort_keys(&a.1.sort, &b.1.sort, sort_fields)
                    .then_with(|| a.0.cmp(&b.0))
                    .then_with(|| a.1.id.cmp(&b.1.id))
            });
            final_hits = decorated.into_iter().map(|(_, h)| h).collect();
        } else {
            // Default: sort by score descending, with insertion-order
            // (seq_no ASC) as the secondary key so ties resolve to "doc
            // that arrived first comes first" — matching ES's `_doc`
            // tie-break. The previous tie-break was `_id` ascending
            // which is essentially random for UUID-shaped ids and
            // produced reverse-of-insertion order for unsorted match-all
            // results (see search/380_sort_segments_on_timestamp.yml's
            // "NOT sorted on timestamp" sub-test).
            // Top-level `constant_score`: every hit's `_score` is exactly
            // the wrapper's boost (f32) — ES semantics — regardless of which
            // matching path produced the hit (FTS text filters score BM25
            // internally, memtable hits carry 1.0, …). Overwriting BEFORE
            // the sort makes every score tied, so the ordering collapses to
            // seq_no ASC = arrival = ES `_doc` order.
            if let QueryNode::Constant { score, .. } = query {
                for hit in final_hits.iter_mut() {
                    hit.score = *score;
                }
            }
            self.sort_hits_page_order(&mut final_hits);
        }

        // --- IDF-weighted rescore for Bool queries with multiple terms ---
        // When the query is Bool(should: [Match(A), Match(B), ...]) or
        // query_string lowered to one, the per-hit memtable score is
        // uniform (sum of tf contributions without IDF). Re-weight using
        // per-term document frequency across the full hit set so rare
        // terms contribute more. This is the difference between "all
        // docs get 1.0" and "docs with rare terms rank higher" for
        // diversified_sampler / top_hits / 115_multi / interval_query
        // ordering.
        // (`!scored_fast_applied`: the columnar scored path already produced
        // exact ES BM25 scores — this heuristic rescore would rewrite
        // range-less scoring bools with ≥2 clauses.)
        // (`exact_bm25_page`: #361 — the segment FTS path produced the same
        // exact BM25 and needs the identical protection. Its N comes from
        // `final_hits.len()`, so without this `_score` depends on `size` and
        // `bool{must:[A],must:[B]}` ranks differently from the same clauses
        // scoped with `post_filter`.)
        let exact_bm25_page = fts_scored_applied && !heuristic_scored_applied;
        if !scored_fast_applied
            && !exact_bm25_page
            && !final_hits.is_empty()
            && request.sort.is_empty()
            // Top-level constant_score: scores are the wrapper's constant —
            // the hit-set idf heuristic must not rewrite them.
            && !matches!(query, QueryNode::Constant { .. })
            // `query`, not `request.query` (#399): these gates decide whether
            // to REWRITE what the executor just scored, so they have to read
            // the same tree the executor was steered by — alias-resolved,
            // typeless-lowered, one-clause-bools erased. Reading the raw
            // request re-opens the defect from the other side: after the
            // unwrap `bool{must:[X]}` and bare `X` take the same path and
            // score the same, and then a gate that still sees a `Bool` would
            // rewrite one page and not the other.
            && query_uses_bool_text(query)
        {
            let field_term_pairs = collect_match_field_terms(query);
            if !field_term_pairs.is_empty() {
                let n_docs = final_hits.len() as f32;
                // For each (field, term) clause, compute its doc frequency.
                let term_idf: Vec<f32> = field_term_pairs
                    .iter()
                    .map(|(field, term, _boost)| {
                        let df = final_hits
                            .iter()
                            .filter(|h| match_term_frequency(&h.source, field, term) > 0.0)
                            .count() as f32;
                        if df == 0.0 {
                            0.0
                        } else {
                            // BM25-style IDF: ln(1 + (N - df + 0.5) / (df + 0.5))
                            (1.0 + (n_docs - df + 0.5) / (df + 0.5)).ln()
                        }
                    })
                    .collect();
                // Rescore each hit: score = Σ boost(i) · idf(i) · (1 + ln(1 + tf(i)))
                for hit in final_hits.iter_mut() {
                    let mut score = 0.0f32;
                    for (i, (field, term, clause_boost)) in field_term_pairs.iter().enumerate() {
                        let tf = match_term_frequency(&hit.source, field, term);
                        if tf > 0.0 {
                            score += clause_boost * term_idf[i] * (1.0 + (1.0 + tf).ln());
                        }
                    }
                    if score > 0.0 {
                        // #825: this pass derives a score from term
                        // frequencies ALONE, so on a #825-pinned tree it
                        // would overwrite the summed `query_score +
                        // knn_score` with the lexical half only — silently
                        // dropping the vector contribution for exactly the
                        // documents reached by BOTH halves, while a
                        // vector-only doc (tf 0, heuristic 0) keeps its knn
                        // score and can then outrank them. `query_uses_bool_text`
                        // above cannot see the difference: the user's inner
                        // bool supplies the ≥2 text clauses and the pinned
                        // sub-tree contributes 0 text children, so it neither
                        // disqualifies nor suppresses. Add the pinned constant
                        // back rather than suppressing the rescore, so the
                        // lexical half still gets its IDF weighting.
                        // (Empty map — the overwhelmingly common case — costs
                        // one hash lookup that always misses.)
                        hit.score = score
                            + pinned_knn_scores
                                .get(hit.id.as_str())
                                .copied()
                                .unwrap_or(0.0);
                    }
                }
                // Re-sort by the new scores (#270 — full page-order key, so
                // hits the rescore left tied keep arrival order).
                self.sort_hits_page_order(&mut final_hits);
            }
        }

        // --- Score normalization: normalize BM25 scores to [0, max_score] ---
        // When scores are extremely low (BM25 near-zero), fall back to simple TF-IDF scoring.
        // (`!scored_fast_applied`: a term with n ≈ N legitimately scores
        // < 0.001 under exact BM25 — e.g. status:ok over the 100k bench
        // corpus scores 0.012563465, but boosting×0.3 shapes go lower — and
        // this data-dependent fallback would silently rewrite exact scores.)
        // (`exact_bm25_page`: #361 — same argument for the segment FTS path.)
        if !scored_fast_applied
            && !exact_bm25_page
            && !final_hits.is_empty()
            && request.sort.is_empty()
            // Top-level constant_score with a small boost (< 0.001) is a
            // legitimate constant — never TF-IDF-rewrite it.
            && !matches!(query, QueryNode::Constant { .. })
        {
            let max_score = final_hits
                .iter()
                .map(|h| h.score)
                .fold(f32::NEG_INFINITY, f32::max);
            // TF-IDF fallback: when all BM25 scores are negligibly small, recompute
            // using a simpler term-frequency heuristic for more useful ranking.
            if max_score > 0.0 && max_score < 0.001 {
                // `query`, not `request.query` — same argument as the rescore
                // gate above (#399). `extract_query_text` answers `None` for a
                // `Bool`, so with the raw request a very common term (BM25
                // below 0.001) would be TF-IDF-rewritten as a bare `match` and
                // left alone as `bool{must:[match]}` — the identical query
                // shape divergence, one gate further down.
                let query_terms = extract_query_text(query)
                    .map(|t| {
                        t.split_whitespace()
                            .map(|s| s.to_lowercase())
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
                if !query_terms.is_empty() {
                    // This heuristic reads the whole serialized document, so
                    // a column-projected cold hit gets its full source back
                    // first (#2422/#2423); rare path, a handful of rows.
                    if !scan_projected.is_empty() {
                        self.locate_scan_projected_rows(
                            &final_hits,
                            &scan_projected,
                            &mut row_projected,
                        );
                    }
                    if !row_projected.is_empty() {
                        for hit in final_hits.iter_mut() {
                            let Some((seg, pos)) = row_projected.get(&hit.id) else {
                                continue;
                            };
                            if let Some(source) = self
                                .hydrate_fts_rows_cold(seg, &[*pos], None)
                                .and_then(|mut rows| rows.remove(pos))
                                .and_then(|mut doc| doc.get_mut("_source").map(Value::take))
                            {
                                hit.source = source;
                            }
                        }
                    }
                    let n_docs = final_hits.len() as f32;
                    // Pre-compute lowercased source strings to avoid double-borrowing.
                    let src_strings: Vec<String> = final_hits
                        .iter()
                        .map(|h| h.source.to_string().to_lowercase())
                        .collect();
                    // Compute per-term document frequencies from the snapshot.
                    let new_scores: Vec<f32> = src_strings
                        .iter()
                        .map(|src_str| {
                            let mut tfidf = 0.0f32;
                            for term in &query_terms {
                                let tf = src_str.matches(term.as_str()).count() as f32;
                                let df = src_strings
                                    .iter()
                                    .filter(|s| s.contains(term.as_str()))
                                    .count() as f32;
                                if tf > 0.0 && df > 0.0 {
                                    tfidf += tf.sqrt() * (1.0 + (n_docs / df).ln());
                                }
                            }
                            tfidf
                        })
                        .collect();
                    for (hit, score) in final_hits.iter_mut().zip(new_scores) {
                        hit.score = score;
                    }
                    // Re-sort with new TF-IDF scores (#270 — full page-order
                    // key; on ~640 identical docs every fallback score is
                    // exactly 1.0, and an `_id` tie-break inverted the page).
                    self.sort_hits_page_order(&mut final_hits);
                }
            }
        }

        // --- Apply collapse BEFORE rescore (ES order) ---
        // ES applies field collapsing on the initial query results,
        // selecting the top-scoring representative per group, and only
        // THEN re-scores the survivors. Rescoring before collapse would
        // change which doc per group "wins" and produce different
        // results for tests that explicitly check this interaction
        // (search/112_field_collapsing_with_rescore).
        if request.collapse.is_some() && !request.rescore.is_empty() {
            if let Some(collapse) = &request.collapse {
                final_hits = apply_collapse_with_inner(
                    final_hits,
                    &collapse.field,
                    collapse.inner_hits.as_ref(),
                );
            }
        }

        // --- Apply rescore ---
        // For each rescore stage, re-score the top window_size hits using the secondary query.
        // Final score = original_score * query_weight + rescore_score * rescore_query_weight
        if !request.rescore.is_empty() {
            // Sort by score before applying rescore so we work on the correct
            // top-N (#270 — full page-order key at every stage, so the
            // window selection and any hits a stage leaves tied both follow
            // arrival order rather than `_id`).
            self.sort_hits_page_order(&mut final_hits);

            for rescore_stage in &resolved_rescore {
                apply_rescore(&mut final_hits, rescore_stage, &dmq_schema);
                // ES re-sorts between chained rescore stages so the
                // next stage's `window_size` applies to the top-N
                // of the just-rescored order, not the pre-rescore
                // BM25 order.
                self.sort_hits_page_order(&mut final_hits);
            }

            // Re-sort after rescoring.
            self.sort_hits_page_order(&mut final_hits);
        }

        // --- match_all total = authoritative live doc count ---
        // The size>0 segment scan tallies stored doc-versions (and the
        // count-shortcut/precomputed paths use the version-doubling atomic), so
        // an UPDATE would inflate hits.total. For an unfiltered match_all the
        // true total is the live doc count (one entry per `_id`). min_score
        // below still adjusts from this corrected base if present.
        // `_effective` (#270): a wrapped match_all now scans in bounded
        // `count_authoritative` mode, so its tally is partial and needs this
        // same overwrite.
        if is_match_all_effective {
            total_count = self.live_doc_count();
        } else if !count_only
            && !query_needs_fts
            && !scored_fast_applied
            && (scan_hit_cap || sort_candidates_narrowed)
            && !deletes_present
        {
            // `!count_only` (not `size > 0`): a `size:0 + aggs` request also
            // materialises hits (count_only=false) and therefore also runs
            // the scan in bounded early-break mode when the count is
            // authoritative — its partial tally needs the same overwrite.
            // Pure count-only requests never materialise, so scan_hit_cap
            // is always false for them and this branch can't misfire.
            // F1: the non-FTS stored scan filled its bounded collector and may
            // have stopped early, so its `total_count` is partial — replace it
            // with the authoritative doc-values / FST shortcut count.  We only
            // do this when the scan actually hit the cap AND there are no
            // deletes (the shortcut is delete-blind; see the hoisted
            // `deletes_present` gate — with deletes present the scan ran in full
            // delete-aware counting mode so `total_count` is already exact).
            // For small result sets
            // the scan already produced the EXACT, full-semantics count above
            // and must be trusted (the shortcut can under-count flattened /
            // subobjects:false / passthrough fields, returning 0 where the scan
            // finds matches).  The `sc >= final_hits.len()` guard is a final
            // sanity check — the true total can never be below the number of
            // distinct hits we actually materialised.
            if let Some(sc) = shortcut_count {
                if sc >= final_hits.len() as u64 {
                    total_count = sc;
                }
            }
        }

        // --- Apply min_score threshold ---
        // ES drops hits below min_score before pagination + aggregations
        // + total counting.
        if let Some(min_score) = request.min_score {
            let before = final_hits.len();
            final_hits.retain(|h| (h.score as f64) >= min_score);
            let dropped = before - final_hits.len();
            if fs_min_tally.is_some() {
                // Brute function_score path: the scan scored EVERY match
                // through `score_doc`, which tallied the docs whose FINAL
                // score clears the threshold — that tally IS the exact
                // ES `hits.total`.  (The materialised-drop subtraction
                // below only sees the ≤cap page and left `total` at the
                // raw match count on a >cap corpus: 100000 vs ES's 373 on
                // the live-verified min_score cell.)
                total_count = fs_min_passed.load(std::sync::atomic::Ordering::Relaxed);
            } else {
                // Legacy shapes: drop count among materialised hits.
                total_count = total_count.saturating_sub(dropped as u64);
            }
        }

        // --- Collect matched_queries for named queries ---
        for hit in &mut final_hits {
            // Inject `_id` so Ids queries nested inside named wrappers can
            // resolve their membership check from the hit's metadata.
            let source_with_id = if hit.source.get("_id").is_some() {
                hit.source.clone()
            } else if let Some(obj) = hit.source.as_object() {
                let mut o = obj.clone();
                o.insert("_id".to_string(), Value::String(hit.id.clone()));
                Value::Object(o)
            } else {
                hit.source.clone()
            };
            hit.matched_queries =
                collect_matched_queries(&request.query, &source_with_id, &dmq_schema);
        }

        // --- Apply search_after cursor (skip hits up to and including the cursor) ---
        // Field-sorted queries already rejected cursor-≤ hits INSIDE the
        // bounded collector (`SortTopK::would_admit`), so for that path this
        // block is a no-op safety net (position 0 matches immediately).  It
        // remains load-bearing for the score-sort cursor path, which has no
        // field collector.  The cursor was normalized ONCE into `after_norm`
        // before collection (date strings → epoch numbers).
        if let Some(ref after_values) = request.search_after {
            if !after_values.is_empty() {
                let after_values_norm: &[Value] = after_norm.as_deref().unwrap_or(&[]);
                let after_values_ref: &[Value] = after_values_norm;
                // Find the first hit whose sort values are strictly "after" the cursor.
                // For sorted results: skip until we find a hit where sort > after_values.
                // For score-only sort: after_values[0] is the score cursor.
                let pos = if !request.sort.is_empty() {
                    final_hits.iter().position(|hit| {
                        xerj_query::sort::compare_sort_keys(
                            &hit.sort,
                            after_values_ref,
                            &request.sort,
                        ) == std::cmp::Ordering::Greater
                    })
                } else {
                    // Default score sort: find where score < cursor_score (descending).
                    let cursor_score = after_values
                        .first()
                        .and_then(|v| v.as_f64())
                        .unwrap_or(f64::NEG_INFINITY);
                    // Tie-break on _id if provided (second element).
                    let cursor_id = after_values.get(1).and_then(|v| v.as_str()).unwrap_or("");
                    final_hits.iter().position(|hit| {
                        let hit_score = hit.score as f64;
                        if (hit_score - cursor_score).abs() < f64::EPSILON {
                            // Same score: tie-break by id lexicographically.
                            hit.id.as_str() > cursor_id
                        } else {
                            hit_score < cursor_score
                        }
                    })
                };
                if let Some(p) = pos {
                    final_hits = final_hits.split_off(p);
                } else {
                    // All hits are at or before the cursor — return nothing.
                    final_hits.clear();
                }
            }
        }

        // --- Compute total with track_total_hits semantics ---
        // `total_count` is the exact number of documents that matched, as
        // tallied by `admit_hit!` and the fast-paths — we do NOT rely on
        // `final_hits.len()` anymore because the collector is bounded.
        let (total, total_relation) = match request.track_total_hits {
            TrackTotalHits::True => (total_count, TotalHitsRelation::Eq),
            TrackTotalHits::False => {
                let cap = size as u64;
                if total_count > cap {
                    (cap, TotalHitsRelation::Gte)
                } else {
                    (total_count, TotalHitsRelation::Eq)
                }
            }
            TrackTotalHits::Limit(limit) => {
                if total_count > limit {
                    (limit, TotalHitsRelation::Gte)
                } else {
                    (total_count, TotalHitsRelation::Eq)
                }
            }
        };

        // --- Collect background docs for significant_terms (all memtable docs) ---
        // Used as the corpus for background frequency calculation.
        // Skip this when the fast path already served the aggs (precomputed_aggs
        // is Some), or when the request has no significant_terms agg.  Cloning
        // every memtable doc into a Vec<Value> is the dominant overhead for
        // `size:0 + agg` queries on a 200 k-doc memtable.
        // Build the full corpus (live memtable + every segment's stored
        // section) whenever we will need a JSON-scan aggregation fallback.
        //
        // CORRECTNESS: aggregations must see EVERY matching document, not just
        // the `materialisation_limit`-capped hit window (`final_hits`). The
        // segment doc-values fast paths (`try_aggs_fast*`) are disabled under
        // the sharded memtable (M5.1), so for `size:0 + aggs` the agg value is
        // computed by `run_aggs_with_all` — which previously ran over only the
        // first ~256 materialised hits, silently under-counting stats/terms on
        // any index larger than the cap. We hand it the full corpus instead.
        //
        // This corpus also serves as the `significant_terms` / `global` /
        // `min_doc_count:0` background, so it must exist after `_refresh` has
        // flushed the memtable to segments.
        let need_full_corpus = precomputed_aggs.is_none() && request.aggs.is_some();
        // #464: the brute agg corpus below deep-clones EVERY memtable AND
        // segment source into owned `Value`s — the allocation that escaped
        // `max_query_memory_mb` (the window guard bills `from + size` hits, which
        // is 0 for `size:0 + aggs`). This path is reached by ANY agg that bails
        // the columnar fast path: a meta-observing `top_hits`, and equally the
        // no-meta families with no columnar path at all (percentiles /
        // date_histogram / cardinality). Bound the full-corpus materialisation
        // here, before the clone, counting memtable AND flushed-segment docs.
        if need_full_corpus {
            if let Some(g) = crate::governor::global() {
                if g.query_memory_enabled() {
                    const EST_BYTES_PER_OWNED_DOC: u64 = 2048;
                    let seg_docs: u64 = self
                        .store
                        .snapshot()
                        .segments
                        .iter()
                        .map(|m| m.doc_count)
                        .sum();
                    let est = (self.memtable.doc_count() as u64)
                        .saturating_add(seg_docs)
                        .saturating_mul(EST_BYTES_PER_OWNED_DOC);
                    g.check_query_alloc(est, "aggregation corpus materialisation")
                        .map_err(EngineError::Common)?;
                }
            }
        }
        let all_docs: Vec<Value> = if need_full_corpus {
            // `_id` is injected onto each source so `top_hits` / `_id`-keyed
            // aggs over the corpus still work (the fast path never provided it).
            // Arc-share out of the memtable (cheap refcount bump under the
            // per-shard read lock — same fix `all_docs_with_sources_arc`
            // already applies for the fast-agg path, see its doc comment),
            // then deep-clone into owned `Value` AFTER the lock is released.
            // `run_aggs_with_all` needs owned `Value`, but this was previously
            // deep-cloning the whole memtable WHILE holding the shard lock —
            // the dominant `hydrate+corpus` cost under concurrent dashboard
            // load, where several panel queries serialize on the same
            // per-shard RwLock while each does a full O(doc) clone under it.
            let mut docs: Vec<Value> = self
                .memtable
                .all_docs_with_sources_arc()
                .into_iter()
                .map(|(id, v)| {
                    let mut v = (*v).clone();
                    if let Some(o) = v.as_object_mut() {
                        o.entry("_id".to_string())
                            .or_insert_with(|| Value::String(id));
                    }
                    v
                })
                .collect();
            let snap_bg = self.store.snapshot();
            for seg in &snap_bg.segments {
                // A tombstone-only segment is an intentional delete journal:
                // it has `doc_count == 0` and no Stored section to hydrate.
                // Its deletions are already represented in the version map,
                // while this pass only assembles source documents for the
                // aggregation corpus. Trying to load it makes the valid
                // absence of Stored look like an unreadable segment and turns
                // every fallback aggregation after a persisted delete into a
                // 500 response.
                if seg.doc_count == 0 {
                    continue;
                }
                // Cooperative deadline: the full-corpus assembly is the
                // most expensive path in the engine (decompress + parse
                // EVERY stored doc).  Stop pulling further segments once
                // past the request timeout — aggs become partial and the
                // response carries `timed_out: true`.
                if std::time::Instant::now() >= search_deadline {
                    deadline_exceeded = true;
                    break;
                }
                // Cache-backed, single-flight decode: was an unconditional
                // `open_segment_arc` + `decode_stored` + full JSON parse on
                // EVERY search hitting this path — segments are immutable
                // post-flush, so re-decoding the same segment's full stored
                // section on every concurrent dashboard query (each paying
                // the full decompress+parse again) was the dominant
                // `hydrate+corpus` cost once data moved from memtable to
                // segment (15-25s+ observed under a concurrent Kibana
                // burst). `stored_values_for_async` is the same cache KNN
                // search already relies on for this exact reason — first
                // caller decodes and publishes, every other concurrent
                // caller (single-flight) and every later query (cache hit)
                // just clone the `Arc`.
                let arr = match self.stored_values_for_async(&seg.id).await {
                    Some(a) => a,
                    // Segment unreadable (transient I/O, or merged away
                    // under this pass's snapshot). A skipped segment
                    // silently drops its docs from every aggregation
                    // bucket, so surface it rather than continuing.
                    None => {
                        return Err(EngineError::Common(xerj_common::XerjError::internal(
                            format!("segment {} unreadable during corpus assembly", seg.id),
                        )));
                    }
                };
                let mut segment_hydrated: u64 = 0;
                for d in arr.iter() {
                    // Skip tombstoned docs.
                    let id_ref = d.get("_id").and_then(Value::as_str).unwrap_or("");
                    if let Some(ver) = self.store.version_map.get(id_ref) {
                        if ver.deleted {
                            continue;
                        }
                        // Superseded stale copy (b8 DEFECT T2) —
                        // merge.rs stale-copy predicate.
                        if let Some(doc_seq) = d.get("_seq_no").and_then(Value::as_u64) {
                            if doc_seq < ver.seq_no {
                                continue;
                            }
                        }
                    }
                    let id_owned = id_ref.to_string();
                    let mut src = d.get("_source").cloned().unwrap_or_else(|| d.clone());
                    if let Some(o) = src.as_object_mut() {
                        if !id_owned.is_empty() {
                            o.entry("_id".to_string())
                                .or_insert(Value::String(id_owned));
                        }
                    }
                    docs.push(src);
                    segment_hydrated = segment_hydrated.saturating_add(1);
                }
                crate::aggs::note_corpus_hydration(segment_hydrated);
            }
            // Enrich corpus docs with hit-level metadata so score/seq-sensitive
            // sub-aggs reproduce ES semantics: `top_hits` default-sorts by
            // `_score` desc then `_seq_no` asc and surfaces `_index`/`_score`/
            // `matched_queries`; `diversified_sampler` keeps the top
            // max_docs_per_value per field value BY SCORE. Raw stored sources
            // carry none of these, so without this top_hits returns docs in
            // arbitrary corpus order (and Null index/score/matched_queries) and
            // the sampler keeps the wrong doc. `_score`/`matched_queries` come
            // from the already-scored hit window (`final_hits`).
            {
                let hit_meta: std::collections::HashMap<&str, &Hit> =
                    final_hits.iter().map(|h| (h.id.as_str(), h)).collect();
                for d in docs.iter_mut() {
                    if let Some(o) = d.as_object_mut() {
                        o.entry("_index".to_string())
                            .or_insert_with(|| Value::String(self.name.to_string()));
                        let id = o.get("_id").and_then(Value::as_str).map(str::to_string);
                        if let Some(id) = id {
                            if let Some(seq) = self.lookup_seq_no(&id) {
                                o.entry("_seq_no".to_string())
                                    .or_insert_with(|| serde_json::json!(seq));
                            }
                            if let Some(h) = hit_meta.get(id.as_str()) {
                                o.insert("_score".to_string(), serde_json::json!(h.score));
                                if !h.matched_queries.is_empty() {
                                    o.insert(
                                        "_matched_queries".to_string(),
                                        Value::Array(
                                            h.matched_queries
                                                .iter()
                                                .cloned()
                                                .map(Value::String)
                                                .collect(),
                                        ),
                                    );
                                }
                            }
                        }
                    }
                }
            }
            docs
        } else {
            vec![]
        };

        phase_marks.push(("hydrate+corpus", phase_t0.elapsed().as_millis() as u64));
        // --- Run aggregations over the full matched set (before pagination) ---
        let agg_start = std::time::Instant::now();
        let agg_result = if let Some(aggs_def) = &request.aggs {
            // If the pre-segment-loop fast path already computed the agg
            // value, consume it here and skip every slower path.  This is
            // the hot path for `size:0 + match_all + aggs` queries.
            if let Some(r) = precomputed_aggs.take() {
                Some(r)
            } else {
                let is_match_all = matches!(query, QueryNode::MatchAll);

                // Memtable + segments DV fast path (non-size=0 MatchAll still
                // benefits if the stored scan hasn't materialized sources yet).
                let mut agg_result_opt: Option<Value> = None;
                if is_match_all {
                    let snap2 = self.store.snapshot();
                    agg_result_opt = try_aggs_fast_with_segments(
                        aggs_def,
                        &snap2,
                        &segments_dir,
                        &self.memtable,
                    )
                    .await;
                    drop(snap2);
                }

                // Propagate outer query terms into the aggs thread-local so
                // run_top_hits can build highlights without requiring the
                // aggs layer to know about QueryNode trees.
                let hl_terms = extract_highlight_terms(query);
                crate::aggs::set_outer_query_terms(hl_terms);
                // Also propagate (field, term) pairs for explain output.
                let ft_pairs: Vec<(String, String)> = collect_match_field_terms(query)
                    .into_iter()
                    .map(|(f, t, _boost)| (f, t))
                    .collect();
                crate::aggs::set_outer_query_field_terms(ft_pairs);

                let agg_result = if let Some(r) = agg_result_opt {
                    r
                } else {
                    // Memtable-only DV fast path (currently a no-op under the
                    // sharded memtable — returns None; kept wired for when the
                    // cross-shard column aggregator lands).
                    let can_use_dv_fast = is_match_all || mem_dv_doc_indices.is_some();
                    let dv_result = if can_use_dv_fast {
                        try_aggs_fast(aggs_def, mem_dv_doc_indices.as_deref(), &self.memtable).await
                    } else {
                        None
                    };
                    if let Some(r) = dv_result {
                        r
                    } else if need_full_corpus {
                        // JSON-scan over the FULL matching set (correctness fix).
                        // match_all -> the whole corpus; filtered query -> keep only
                        // docs the query matches (same matcher the stored-doc scan
                        // uses), so aggregations reflect every match rather than the
                        // `materialisation_limit`-capped hit window.
                        let fg_owned: Vec<Value>;
                        let fg: &[Value] = if is_match_all {
                            &all_docs[..]
                        } else {
                            fg_owned = all_docs
                                .iter()
                                .filter(|d| doc_matches_query_typed(query, d, &dmq_schema))
                                .cloned()
                                .collect();
                            &fg_owned[..]
                        };
                        // `doc_matches_query` is a boolean matcher and ignores
                        // scoring, so when `min_score` is set the agg foreground
                        // must additionally drop docs whose score fell below it.
                        // `final_hits` is already min_score-filtered (above), so
                        // intersect by `_id`.
                        let fg_min: Vec<Value>;
                        let fg: &[Value] = if request.min_score.is_some() {
                            let keep: std::collections::HashSet<&str> =
                                final_hits.iter().map(|h| h.id.as_str()).collect();
                            fg_min = fg
                                .iter()
                                .filter(|d| {
                                    d.get("_id")
                                        .and_then(Value::as_str)
                                        .is_some_and(|id| keep.contains(id))
                                })
                                .cloned()
                                .collect();
                            &fg_min[..]
                        } else {
                            fg
                        };
                        let bg = if all_docs.is_empty() {
                            fg
                        } else {
                            &all_docs[..]
                        };
                        run_aggs_with_schema(aggs_def, fg, bg, &dmq_schema)
                    } else {
                        // Safety net: corpus not built — aggregate the hit window.
                        let sources: Vec<Value> = final_hits
                            .iter()
                            .map(|h| {
                                let mut s = h.source.clone();
                                if let Some(obj) = s.as_object_mut() {
                                    obj.insert("_score".to_string(), serde_json::json!(h.score));
                                    obj.insert("_id".to_string(), Value::String(h.id.clone()));
                                    obj.insert(
                                        "_index".to_string(),
                                        Value::String(self.name.to_string()),
                                    );
                                    if let Some(seq) = self.lookup_seq_no(&h.id) {
                                        obj.insert("_seq_no".to_string(), serde_json::json!(seq));
                                    }
                                    if !h.matched_queries.is_empty() {
                                        obj.insert(
                                            "_matched_queries".to_string(),
                                            Value::Array(
                                                h.matched_queries
                                                    .iter()
                                                    .cloned()
                                                    .map(Value::String)
                                                    .collect(),
                                            ),
                                        );
                                    }
                                }
                                s
                            })
                            .collect();
                        let bg = if all_docs.is_empty() {
                            &sources[..]
                        } else {
                            &all_docs[..]
                        };
                        run_aggs_with_schema(aggs_def, &sources, bg, &dmq_schema)
                    }
                };
                Some(agg_result)
            }
        } else {
            None
        };
        let agg_nanos = agg_start.elapsed().as_nanos() as u64;

        // Population max over ALL matched docs (pre-collapse, pre-page) so the
        // API can report ES `max_score` with collapse + track_scores correctly
        // (ES reports the max over the whole result set, not just the collapsed
        // top hit per group).
        let population_max_score: Option<f32> = final_hits
            .iter()
            .map(|h| h.score)
            .fold(None, |acc: Option<f32>, s| {
                Some(acc.map_or(s, |m| m.max(s)))
            });
        // Fold in the scan-wide max from the brute scorer: under a field
        // sort the heap only kept ~page hits, but ES's max_score covers
        // every match. Rescore mutates scores after the scan, so the scan
        // max is stale there — skip.
        let population_max_score: Option<f32> = if request.rescore.is_empty() {
            let scan_max =
                f32::from_bits(scored_max_bits.load(std::sync::atomic::Ordering::Relaxed));
            match population_max_score {
                Some(m) if scan_max > m => Some(scan_max),
                other => other,
            }
        } else {
            population_max_score
        };

        // --- Apply field collapsing (deduplicate by field value, keep top hit per value) ---
        // Skipped here when rescore was present (we already collapsed before rescore).
        let final_hits = if let Some(collapse) = &request.collapse {
            if request.rescore.is_empty() {
                apply_collapse_with_inner(final_hits, &collapse.field, collapse.inner_hits.as_ref())
            } else {
                final_hits
            }
        } else {
            final_hits
        };

        // --- Apply pagination (size=0 means no hits returned) ---
        let page: Vec<Hit> = if size == 0 {
            Vec::new()
        } else {
            final_hits
                .into_iter()
                .skip(if scored_from_applied { 0 } else { from })
                .take(size)
                .collect()
        };

        // --- Apply highlighting (BEFORE `_source` filtering) ---
        //
        // `apply_highlight` reads the field text out of `hit.source`.  Running
        // it after `apply_source_filter` meant a request that excluded the
        // highlighted field got NO highlight at all — silently, with a 200 and
        // no `highlight` key.  ES treats the two as independent: highlighting
        // resolves against the stored document, not against whatever `_source`
        // projection the caller asked for.
        //
        // The old order made the token-efficient shape impossible. To get a
        // ~160-byte fragment you had to also ship the whole field: a 1,536-byte
        // body for a 160-byte answer. That matters most to the callers most
        // likely to use highlighting — agents paying per token for context.
        let page = if let Some(hl_req) = &request.highlight {
            // #1281: field names may be patterns (`"*"`, `"mess*"`), which
            // `apply_highlight` would otherwise look up as literal source keys
            // and never find.
            if hl_req.fields.keys().any(|f| f.contains('*')) {
                let schema = self.schema.read().await;
                let expanded = expand_highlight_field_patterns(hl_req, &schema.schema, query);
                apply_highlight(page, &expanded, query)
            } else {
                apply_highlight(page, hl_req, query)
            }
        } else {
            page
        };

        // --- Fill `_passage` for lexical queries (issue #174) ---
        //
        // The `_passage` pseudo-field used to be populated only by the
        // kNN/semantic executors; a lexical query that requested it got a
        // silent no-op, so callers slicing a large `body` had no way to know
        // WHERE in the file the match lived. Like highlighting, this is a
        // post-pass over the returned page only (never the full candidate
        // set), reads the already-materialised `hit.source`, and must run
        // BEFORE `apply_source_filter` for the same reason highlighting does:
        // the passage resolves against the stored document, independent of
        // the `_source` projection.
        let page = if passage_requested(request) {
            apply_lexical_passages(page, query)
        } else {
            page
        };

        // --- Apply _source filtering ---
        let generated_companion_fields = {
            let schema = self.schema.read().await;
            generated_embedding_companion_fields(&schema.schema)
        };
        let (page, savings) = apply_source_filter_measured(
            page,
            &request.source,
            &generated_companion_fields,
            Some(request),
        );

        // --- Build profile data if requested ---
        let profile = if request.profile {
            let query_desc = format!("{:?}", query).chars().take(120).collect::<String>();
            Some(serde_json::json!({
                "shards": [{
                    "id": "0",
                    "searches": [{
                        "query": [{
                            "type": "MatchQuery",
                            "description": query_desc,
                            "time_in_nanos": agg_nanos,
                            "children": []
                        }]
                    }],
                    "aggregations": [{
                        "type": "Aggregations",
                        "description": "aggs",
                        "time_in_nanos": agg_nanos
                    }]
                }]
            }))
        } else {
            None
        };

        let inner_ms = phase_t0.elapsed().as_millis() as u64;
        if inner_ms >= phase_log_threshold_ms() {
            phase_marks.push(("aggs+page", inner_ms));
            // Cumulative marks → per-phase deltas for the log line.
            let mut prev = 0u64;
            let breakdown: Vec<String> = phase_marks
                .iter()
                .map(|(name, at)| {
                    let d = at.saturating_sub(prev);
                    prev = *at;
                    format!("{name}={d}ms")
                })
                .collect();
            warn!(
                total_ms = inner_ms,
                index = self.name.as_str(),
                phases = %breakdown.join(" "),
                gates = %format!(
                    "needs_fts={} shortcut={:?} deletes={} ghosts={} total={} lim={} segs={} dec={}ms scan={}ms ftsopen={}ms walked={} admitted={} allhits_cap={} memhits={} memseen={} memtotal={} memarm={} sorttopk={}",
                    query_needs_fts,
                    shortcut_count,
                    deletes_present,
                    self.store.version_map.ghost_events(),
                    total,
                    materialisation_limit,
                    dbg_segs,
                    dbg_decode_ms,
                    dbg_scan_ms,
                    dbg_fts_ms,
                    dbg_walked,
                    dbg_admitted,
                    scan_hit_cap,
                    dbg_mem_hits,
                    dbg_mem_seen,
                    dbg_mem_total,
                    dbg_mem_arm,
                    dbg_sort_topk
                ),
                "slow search_inner phase breakdown"
            );
        }

        Ok(SearchResult {
            hits: page,
            total: TotalHits {
                value: total,
                relation: total_relation,
            },
            took_ms: 0,
            aggs: agg_result,
            // Set when any cooperative deadline check fired: the hits /
            // total / aggs above are partial, exactly like an ES shard
            // timeout.  `search()` refuses to cache timed-out results.
            timed_out: deadline_exceeded,
            profile,
            max_score: population_max_score,
            script_failure: None,
            savings,
        })
    }

    // ── Flush ─────────────────────────────────────────────────────────────────

    /// Flush the memtable to a new segment on disk, then build the FTS index.
    pub async fn flush(self: &Arc<Self>) -> Result<()> {
        // #873: this flush is about to take whatever the memtable holds, so
        // every idle-probe observation about it is stale from here on. Clear
        // the pair at the ONE coordinator every flush path runs through
        // (user `_flush`, the periodic sweep, a threshold-driven flush,
        // shutdown) rather than lazily in `needs_flush`: a lazy reset only
        // fires if a probe happens to land while the memtable is empty, and
        // nothing schedules a probe between a flush and the next write. A
        // write arriving first would then match the pre-flush fingerprint,
        // skip the re-arm, and be judged against a stamp already older than
        // `flush_idle_secs` — flushing on the very next probe, every probe,
        // forever. The regression test walks exactly that sequence.
        {
            use std::sync::atomic::Ordering;
            self.idle_probe_fingerprint.store(0, Ordering::Relaxed);
            self.idle_probe_at_ms.store(0, Ordering::Relaxed);
        }
        let (field_configs, excluded_fts_fields, dv_skip) = {
            let schema = self.schema.read().await;
            (
                build_fts_field_configs(&schema.schema, self.segment_text_analyzer()),
                crate::memtable::fts_excluded_fields(&schema.schema),
                doc_values_skip_set(&schema.schema),
            )
        };
        // M5.15 — PARALLEL final flush.
        //
        // Pre-M5.15 the user-visible `flush()` walked every shard in
        // sequence (`for shard_idx in 0..N { do_flush_shard(...).await }`)
        // which made the end-of-file flush in the CLI indexer dominate
        // the wall time: 16 shards × ~1 s/shard = 16 s of serial drain
        // at EOF on a 2 GB memtable, dragging the 20 M benchmark down
        // from 1.0 M docs/s peak to as low as 480 k docs/s sustained.
        //
        // Each shard drains into an independent segment with no
        // cross-shard dependency, so we spawn one tokio task per
        // shard and join them concurrently.  The `flush_sema` still
        // bounds global flush concurrency against ingest-time
        // background flushes on other indices.
        let n_shards = self.memtable.shard_count();
        #[cfg(test)]
        let flush_test_hook = FLUSH_PUBLISHER_TEST_HOOK
            .try_with(FlushPublisherTestHook::clone)
            .ok();
        let flush_sema = Arc::clone(&self.flush_sema);
        let store = Arc::clone(&self.store);
        let memtable = Arc::clone(&self.memtable);
        let registry = Arc::clone(&self.registry);
        let data_dir = self.data_dir.clone();
        let warm_caches = self.publish_warm_caches();
        let index = Arc::clone(self);
        let index_name = self.name.as_str().to_string();
        let admit_timeout =
            std::time::Duration::from_millis(self.flush_admit_timeout_ms.load(Ordering::Relaxed));
        let flush_timeout =
            std::time::Duration::from_millis(self.flush_timeout_ms.load(Ordering::Relaxed));
        let coordinator_name = index_name.clone();
        // This coordinator is the cancellation boundary for the whole flush.
        // If the request future is dropped, its JoinHandle detaches and the
        // coordinator continues owning every shard publication transaction.
        // The await below uses the same detach on timeout (#1635): the
        // coordinator is not aborted (#1015).
        let coordinator = tokio::spawn(async move {
            let mut shard_futures = Vec::with_capacity(n_shards);
            for shard_idx in 0..n_shards {
                // #1226 — do not fan a finalize out for an EMPTY shard.
                //
                // `do_flush_shard` acquires the *process-global*
                // `flush_finalize_gate` (a handful of permits shared by every
                // index) before it discovers the shard has nothing to drain,
                // and it first takes a per-index `flush_sema` permit. Under a
                // multi-index bulk storm that global gate is saturated by
                // other indices' ingest flushes, so each no-op shard task
                // still queues behind the whole backlog. A user-visible
                // `_refresh` / `delete_by_query?refresh=true` therefore paid
                // one full admission wait PER SHARD even when the memtable was
                // already drained — the "latency tracks write load, not index
                // size" signature in #1226. Skipping empty shards bounds a
                // flush's finalize-admission cost to the shards it actually
                // has to drain; an all-empty memtable now does zero finalize
                // work (just the durability tail below).
                if memtable.shard_load(shard_idx).0 == 0 {
                    continue;
                }
                let sema = Arc::clone(&flush_sema);
                let store = Arc::clone(&store);
                let memtable = Arc::clone(&memtable);
                let collection_publication = Arc::clone(&index.collection_publication);
                let registry = Arc::clone(&registry);
                let data_dir = data_dir.clone();
                let field_configs = field_configs.clone();
                let excluded_fts_fields = excluded_fts_fields.clone();
                let dv_skip = dv_skip.clone();
                let warm_caches = warm_caches.clone();
                let shard_index_name = coordinator_name.clone();
                #[cfg(test)]
                let test_hook = flush_test_hook.clone();
                shard_futures.push(tokio::spawn(async move {
                    let permit = match wait_for_flush_permit(
                        &shard_index_name,
                        "the flush semaphore",
                        admit_timeout,
                        sema.acquire_owned(),
                    )
                    .await
                    {
                        Ok(permit) => permit,
                        Err(error) => return Err(error),
                    };
                    let permit_cell = Arc::new(std::sync::Mutex::new(permit));
                    let permit_cell_cb = Arc::clone(&permit_cell);
                    let on_drained = move || {
                        if let Ok(mut guard) = permit_cell_cb.lock() {
                            let _ = guard.take();
                        }
                    };
                    let result = do_flush_shard(
                        shard_idx,
                        store,
                        memtable,
                        collection_publication,
                        registry,
                        data_dir,
                        field_configs,
                        excluded_fts_fields,
                        dv_skip,
                        on_drained,
                        warm_caches,
                        shard_index_name,
                        admit_timeout,
                        #[cfg(test)]
                        test_hook,
                    )
                    .await;
                    // Defensive: in case on_drained didn't fire.
                    if let Ok(mut guard) = permit_cell.lock() {
                        let _ = guard.take();
                    }
                    result
                }));
            }
            let mut result: Result<()> = Ok(());
            for fut in shard_futures {
                match fut.await {
                    Ok(Ok(())) => {}
                    Ok(Err(e)) => result = Err(e),
                    Err(error) => {
                        result = Err(EngineError::Common(xerj_common::XerjError::internal(
                            format!("flush shard task failed: {error}"),
                        )));
                    }
                }
            }
            // Publication completion must invalidate results even when the
            // request that initiated the flush was cancelled. The coordinator
            // owns this transition, so it cannot be skipped with the waiter.
            // The detached coordinator owns the complete durability tail.
            // Persist the graph before WAL maintenance can checkpoint vector
            // writes past the point from which restart can rebuild it.
            if result.is_ok() {
                if let Err(error) = index.save_hnsw_to_disk().await {
                    result = Err(error);
                }
            }
            if result.is_ok() {
                if let Err(error) = index.store.force_wal_maintenance() {
                    result = Err(error.into());
                }
            }
            index.dataset_version.fetch_add(1, Ordering::Release);
            index.query_cache.clear();
            result
        });
        await_flush_task(&index_name, flush_timeout, coordinator).await
    }

    /// Check if the memtable exceeds the configured thresholds.
    pub async fn needs_flush(&self) -> bool {
        use std::sync::atomic::Ordering;
        let mem = &*self.memtable;
        let docs = mem.doc_count();
        let bytes = mem.size_bytes();
        if docs >= self.flush_doc_threshold || bytes >= self.flush_byte_threshold {
            return true;
        }
        // #873: idle-age flush. The periodic flusher probes every index on
        // `flush_interval_secs`; a non-empty memtable whose fingerprint has
        // not changed for `flush_idle_secs` flushes regardless of size, so a
        // small dataset reaches a segment, releases its WAL generations, and
        // stops replaying on every boot. Observing change here keeps the
        // write hot path untouched — the ES-controller shape, not per-write
        // stamping. A fingerprint collision (delete+insert of identical
        // sizes inside one probe interval) at worst flushes an active index
        // once, which is always safe.
        if self.flush_idle_secs == 0 {
            return false;
        }
        if docs == 0 {
            // An empty memtable is not idle, it is done — and leaving the
            // previous fingerprint standing here is a live defect, not a
            // cosmetic one. After a flush drains the memtable, a later write
            // that happens to reproduce the same (doc_count, bytes) pair —
            // a uniform trickle of fixed-shape records is the ordinary case,
            // not a contrived one — would match the stale `seen`, skip the
            // re-arm, and be compared against a timestamp already older than
            // `flush_idle_secs`. The very next probe would then flush, and
            // the state would return here unchanged: a stable 10x-cadence
            // loop (a flush every `flush_interval_secs`) on a node the
            // operator believes is idle, which is precisely the background
            // churn this change exists to remove. Clearing the pair makes
            // the next write arm fresh.
            self.idle_probe_fingerprint.store(0, Ordering::Relaxed);
            self.idle_probe_at_ms.store(0, Ordering::Relaxed);
            return false;
        }
        let fp = (docs as u64) ^ (bytes as u64).rotate_left(32);
        let now = Self::coarse_now_ms();
        let seen = self.idle_probe_fingerprint.load(Ordering::Relaxed);
        let seen_at = self.idle_probe_at_ms.load(Ordering::Relaxed);
        // `fp` is never 0 for a non-empty memtable (its low 32 bits are the
        // doc count), so a cleared pair — initial state, or reset by the
        // drained arm above — always mismatches and arms with a current
        // stamp. That is what makes the reset above sufficient.
        if fp != seen {
            self.idle_probe_fingerprint.store(fp, Ordering::Relaxed);
            self.idle_probe_at_ms.store(now, Ordering::Relaxed);
            return false;
        }
        now.saturating_sub(seen_at) >= self.flush_idle_secs.saturating_mul(1000)
    }

    /// Milliseconds since the first call — a process-monotonic coarse clock
    /// for the idle probe (wall-clock jumps cannot move it backwards).
    fn coarse_now_ms() -> u64 {
        static START: std::sync::OnceLock<std::time::Instant> = std::sync::OnceLock::new();
        // Based a day up so early-process probes have room below them — the
        // test rewind hook subtracts, and a floor at 0 near process start
        // would silently pin the stamp instead of aging it.
        86_400_000
            + START
                .get_or_init(std::time::Instant::now)
                .elapsed()
                .as_millis() as u64
    }

    /// #873 test hook: rewind the idle probe so a test can cross
    /// `flush_idle_secs` without sleeping.
    #[cfg(test)]
    pub(crate) fn rewind_idle_probe_for_test(&self, ms: u64) {
        use std::sync::atomic::Ordering;
        let at = self.idle_probe_at_ms.load(Ordering::Relaxed);
        self.idle_probe_at_ms
            .store(at.saturating_sub(ms), Ordering::Relaxed);
    }

    pub fn memtable_bytes(&self) -> usize {
        self.memtable.size_bytes()
    }

    /// Retained JSON-heap estimate of every live memtable source. Test-only
    /// so a regression can bound #1940 without sampling process RSS.
    #[cfg(test)]
    pub(crate) fn memtable_source_heaps_for_test(&self) -> Vec<usize> {
        self.memtable
            .all_docs_with_sources_arc()
            .into_iter()
            .map(|(_, source)| crate::ingest_memory::estimated_json_heap(&source))
            .collect()
    }

    /// #948 — entries currently resident in the STORAGE memtable
    /// (`IndexStore::memtable_shards`).  Diagnostic twin of
    /// [`Self::memtable_bytes`]: the FTS memtable drains on every flush,
    /// the storage one used to never drain at all.
    pub fn resident_memtable_entries(&self) -> usize {
        self.store.resident_memtable_entries()
    }

    pub fn flush_threshold(&self) -> usize {
        self.flush_byte_threshold
    }

    /// Release this index's rebuildable in-memory caches (#463). Every one of
    /// these DashMaps holds hydrated-from-disk data (or recomputable results):
    /// clearing them frees the resident payload — the `Resident` wrappers refund
    /// their hydration budget on drop — and the next read re-hydrates from disk,
    /// exactly as a cache eviction under memory pressure already does. The caller
    /// MUST flush the memtable first (see `Engine::close_index`) so no
    /// not-yet-published document is lost; caches only ever mirror durable data.
    /// The `Arc<Index>` shell itself stays in `Engine::indices` so every
    /// loaded-index view (`_cat/indices`, `_cluster/health`, …) is unchanged.
    pub fn release_memory(&self) {
        self.dv_cache.clear();
        self.sort_shadow_cache.clear();
        self.range_prefilter_cache.clear();
        self.id_pos_cache.clear();
        self.row_seq_cache.clear();
        self.stored_value_cache.clear();
        self.stored_slices_cache.clear();
        self.decoded_stored_cache.clear();
        self.fts_reader_cache.clear();
        self.vector_column_cache.clear();
        self.shortcut_count_cache.clear();
        self.ghost_positions_cache.clear();
        self.regexp_expand_cache.clear();
        self.fast_date_cache.clear();
        self.fast_date_sorted_cache.clear();
        self.query_cache.clear();
    }

    /// Total resident cache entries across every per-segment cache — a
    /// deterministic observable for the `release_memory` effect (#463 tests):
    /// non-zero after a query hydrates segments, zero after `release_memory`.
    pub fn total_cache_entries(&self) -> usize {
        self.dv_cache.len()
            + self.sort_shadow_cache.len()
            + self.range_prefilter_cache.len()
            + self.id_pos_cache.len()
            + self.row_seq_cache.len()
            + self.stored_value_cache.len()
            + self.stored_slices_cache.len()
            + self.decoded_stored_cache.len()
            + self.fts_reader_cache.len()
            + self.vector_column_cache.len()
            + self.shortcut_count_cache.len()
            + self.ghost_positions_cache.len()
            + self.regexp_expand_cache.len()
            + self.fast_date_cache.len()
            + self.fast_date_sorted_cache.len()
            + self.query_cache.len()
    }

    // ── Stats ─────────────────────────────────────────────────────────────────

    /// Return statistics for this index.
    /// Authoritative live document count: one entry per `_id` in the version
    /// map, excluding tombstones. The `doc_count` atomic doubles as the version
    /// generator (bumped on every write, so an UPDATE inflates it by 1), and
    /// summing per-segment `doc_count` includes superseded versions until a
    /// merge — both over-count after updates. The version map holds exactly one
    /// live entry per `_id`, so this is the true count ES clients expect.
    #[inline]
    pub fn live_doc_count(&self) -> u64 {
        self.store.version_map.live_count() as u64
    }

    /// Documents physically present but not live: superseded versions left by
    /// updates and documents killed by deletes, until a merge folds them away.
    /// This is the pre-merge meaning ES gives `docs.deleted`, derived from
    /// segment metadata + the memtable + the version map, so a listing does not
    /// decode every segment's tombstone section.
    ///
    /// It is NOT the same number as `Σ segment_rows().deleted_doc_count`:
    /// xerj writes tombstones only for explicit deletes, while an update
    /// supersedes the old version through the version map without tombstoning
    /// it. Both kinds are absent from search, so both belong here.
    #[inline]
    pub fn deleted_doc_count(&self) -> u64 {
        let snap = self.store.snapshot();
        let physical: u64 = snap
            .segments
            .iter()
            .map(|segment| segment.doc_count)
            .sum::<u64>()
            + self.memtable.doc_count() as u64;
        physical.saturating_sub(self.live_doc_count())
    }

    /// Real per-segment rows for `_cat/segments` (#1202): one entry per LIVE
    /// segment in the durable snapshot — its id, its docs, its deleted docs,
    /// its on-disk bytes. The predecessor endpoint fabricated a single `_0`
    /// row per index ("one logical segment"), which pointed operators AWAY
    /// from the cause during #1186 (an index the log showed merging 13
    /// segments reported "1 segment, 0 deleted").
    ///
    /// `deleted_doc_count` decodes the segment's own ZTB2 tombstone section —
    /// through the cached reader, so a repeated listing costs no re-open and
    /// no whole-file CRC. `doc_count` is the segment's physical document
    /// count, tombstones excluded by construction (a tombstone-only segment
    /// carries 0 docs). A delete's tombstone can persist in a LATER segment
    /// than the doc it kills — xerj tombstones are segment-level records, not
    /// in-place marks — so the honest per-segment reading is
    /// `Σ docs.count − Σ docs.deleted = live docs`, not per-row liveness.
    /// Superseded-until-merge versions of an updated document stay counted in
    /// their segments: only a merge folds them away, the same pre-merge
    /// over-count `_cat/indices`' doc column documents for whole indices.
    pub fn segment_rows(&self) -> Vec<SegmentInfo> {
        let snap = self.store.snapshot();
        let mut out = Vec::with_capacity(snap.segments.len());
        for meta in &snap.segments {
            let mut deleted = 0u64;
            if meta.has_tombstones {
                // The Arc (and its mmap) stays alive across the decode — the
                // section bytes borrow the reader.
                if let Ok(reader) = self.store.open_segment_arc(&meta.id) {
                    if let Ok(Some(bytes)) =
                        reader.section(xerj_storage::segment::SectionType::Tombstones)
                    {
                        if let Some(pairs) = xerj_storage::segment::decode_tombstones_v2(bytes) {
                            deleted = pairs.len() as u64;
                        }
                    }
                }
            }
            out.push(SegmentInfo {
                id: meta.id.clone(),
                doc_count: meta.doc_count,
                deleted_doc_count: deleted,
                size_bytes: meta.size_bytes,
            });
        }
        out
    }

    pub async fn stats(&self) -> IndexStats {
        let snap = self.store.snapshot();
        let segment_count = snap.segments.len();
        drop(snap);

        let _mem = &*self.memtable;
        let schema = self.schema.read().await;

        // Collect per-field encoding info from the memtable's smart analyzer.
        // M5.1 — aggregated across shards; take the union of encodings.
        let field_encodings_map = self.memtable.aggregated_field_encodings();
        let field_encodings = field_encodings_map
            .iter()
            .map(|(field, encoding)| {
                use xerj_compress::field_codec::FieldEncoding;
                let encoding_name = match encoding {
                    FieldEncoding::BitsetEnum { .. } => "bitset_enum",
                    FieldEncoding::DeltaTimestamp { .. } => "delta_timestamp",
                    FieldEncoding::PackedIp { .. } => "packed_ip",
                    FieldEncoding::UrlTemplate { .. } => "url_template",
                    FieldEncoding::Varint { .. } => "varint",
                    FieldEncoding::Dictionary { .. } => "dictionary",
                    FieldEncoding::RawString { .. } => "raw_string",
                    FieldEncoding::Bitpacked { .. } => "bitpacked",
                    FieldEncoding::FixedPrecision { .. } => "fixed_precision",
                };
                let bpv = encoding.bytes_per_value();
                let ratio = encoding.compression_ratio_vs_raw();
                let raw_bpv = bpv * ratio;
                let distinct = match encoding {
                    FieldEncoding::BitsetEnum { values, .. } => values.len(),
                    FieldEncoding::Dictionary { dict, .. } => dict.len(),
                    FieldEncoding::RawString { values } => {
                        let set: std::collections::HashSet<&String> = values.iter().collect();
                        set.len()
                    }
                    _ => 0,
                };
                FieldEncodingInfo {
                    field: field.clone(),
                    encoding: encoding_name.to_string(),
                    bytes_per_value: bpv,
                    raw_bytes_per_value: raw_bpv,
                    compression_ratio: ratio,
                    distinct_values: distinct,
                }
            })
            .collect();

        IndexStats {
            name: self.name.to_string(),
            doc_count: self.live_doc_count(),
            segment_count,
            memtable_doc_count: self.memtable.doc_count(),
            memtable_size_bytes: self.memtable.size_bytes(),
            schema_version: schema.schema.version,
            field_count: schema.schema.field_count(),
            query_count: self.metric_query_count.load(Ordering::Relaxed),
            query_total_ms: self.metric_query_total_ms.load(Ordering::Relaxed),
            index_count: self.metric_index_count.load(Ordering::Relaxed),
            index_total_ms: self.metric_index_total_ms.load(Ordering::Relaxed),
            field_encodings,
        }
    }

    /// Return a snapshot of the current index segments.
    ///
    /// Exposes segment metadata (id, doc_count, size_bytes, seq_no range) for
    /// use by the `_segments` ES-compat API.
    pub fn store_snapshot(&self) -> xerj_storage::index_store::IndexSnapshot {
        let guard = self.store.snapshot();
        (**guard).clone()
    }

    /// Estimate memory usage of this index in bytes.
    ///
    /// Includes:
    /// - Memtable: doc count × ~512 bytes estimated per entry (terms + source JSON overhead)
    /// - Version map entries: doc count × ~64 bytes estimated per entry
    /// - Schema: field count × ~128 bytes per field definition
    pub async fn memory_usage_bytes(&self) -> usize {
        const BYTES_PER_MEMTABLE_ENTRY: usize = 512;
        const BYTES_PER_VERSION_MAP_ENTRY: usize = 64;
        const BYTES_PER_SCHEMA_FIELD: usize = 128;

        let mem = &*self.memtable;
        let memtable_size = mem
            .size_bytes()
            .max(mem.doc_count() * BYTES_PER_MEMTABLE_ENTRY);

        let version_map_count = self.store.version_map.len();
        let version_map_size = version_map_count * BYTES_PER_VERSION_MAP_ENTRY;

        let schema = self.schema.read().await;
        let schema_size = schema.schema.field_count() * BYTES_PER_SCHEMA_FIELD;
        drop(schema);

        memtable_size + version_map_size + schema_size
    }

    // ── Settings ──────────────────────────────────────────────────────────────

    /// Get the index-level settings.
    pub async fn get_settings(&self) -> Value {
        self.settings.read().await.clone()
    }

    /// The `analysis` block this index's analyzer registry was built from —
    /// resolved with the binding the index was opened under, so a pre-#204
    /// index whose canonical `index.analysis` block is declared but NOT
    /// honoured reports `None` rather than an analyzer that analyses nothing
    /// (#1092). Read from the persisted `settings.json` copy, so it survives a
    /// restart (the API's display map does not).
    pub async fn analysis_in_force(&self) -> Option<Value> {
        let settings = self.settings.read().await;
        let root = settings.pointer("/settings").unwrap_or(&settings);
        AnalyzerRegistry::analysis_block_with_binding(root, self.analysis_binding).cloned()
    }

    /// `_analyze` against this index (#1092): run `text` through the pipeline
    /// a search on this index would actually use, and return its name with
    /// the tokens.
    ///
    /// * `analyzer` named → that analyzer from the index's own registry
    ///   (custom analyzers from settings, then the built-ins).
    /// * else `field` named → the analyzer the FTS writer indexes that field
    ///   with ([`build_fts_field_configs`]): the text analyzer for a `text`
    ///   field, `keyword` for every other mapped type, and the registry's
    ///   `default` (else `standard`) for an unmapped field, as the writer's
    ///   unconfigured-field fallback does.
    /// * neither → the index's text analyzer: the declared `default` when this
    ///   index's segments honour it, else `standard`
    ///   ([`Self::segment_text_analyzer`], #937).
    ///
    /// `Err` carries the reason for an unknown analyzer name.
    pub async fn analyze(
        &self,
        analyzer: Option<&str>,
        field: Option<&str>,
        text: &str,
    ) -> std::result::Result<(String, Vec<xerj_fts::analyzer::Token>), String> {
        let name: String = match (analyzer, field) {
            (Some(a), _) => a.to_string(),
            (None, Some(f)) => {
                let schema = self.schema.read().await;
                match schema.schema.field(f).map(|fc| fc.field_type) {
                    Some(FieldType::Text) => self.segment_text_analyzer().to_string(),
                    Some(_) => "keyword".to_string(),
                    None if self.registry.get_analyzer("default").is_some() => {
                        "default".to_string()
                    }
                    None => "standard".to_string(),
                }
            }
            (None, None) => self.segment_text_analyzer().to_string(),
        };
        let pipeline = self
            .registry
            .get_analyzer(&name)
            .ok_or_else(|| format!("failed to find analyzer [{name}]"))?;
        Ok((name, pipeline.analyze(text)))
    }

    /// Update the index-level settings.
    pub async fn put_settings(&self, new_settings: Value) -> Result<()> {
        // Warn if >1 shard requested.
        if let Some(n) = new_settings
            .pointer("/index/number_of_shards")
            .and_then(Value::as_u64)
        {
            if n > 1 {
                tracing::warn!(
                    shards = n,
                    index = self.name.as_str(),
                    "xerj is single-shard; number_of_shards={} is ignored",
                    n
                );
            }
        }
        // Atomic, like every other settings.json writer (create and the index
        // block path). This was the one plain `fs::write` left, i.e. the one
        // way to actually produce the torn settings.json that `Index::open`
        // now refuses (#202) — a kill -9 mid-update left a half-written file.
        let path = self.data_dir.join("settings.json");
        let bytes = serde_json::to_vec_pretty(&new_settings)?;
        write_file_atomic(&path, &bytes).map_err(EngineError::Io)?;
        *self.settings.write().await = new_settings;
        // #965 — keep the bucket's meta copy in step with the local write.
        publish_index_meta_objects(&self.store, &self.data_dir, self.name.as_str());
        Ok(())
    }

    // ── Index blocks ──────────────────────────────────────────────────────────

    /// Process-wide write admission (RC4 W3 items 1 & 3). Applies, in order:
    ///
    ///   1. the disk flood-stage block (item 3) — a 429 `cluster_block_exception`
    ///      `read_only_allow_delete` when the data-dir filesystem is over the
    ///      watermark, before the WAL can be driven to `ENOSPC`;
    ///   2. the parent memory circuit breaker (item 1) — a 429
    ///      `circuit_breaking_exception` when the summed memtable footprint or
    ///      the process RSS is over budget, so a 429 beats the OOM-killer.
    ///
    /// A no-op when no governor is installed (engine-only unit tests that
    /// build an `Index` directly), so their behaviour is unchanged.
    #[inline]
    fn governor_write_gate(&self) -> Result<()> {
        if let Some(g) = crate::governor::global() {
            g.check_disk_block(self.name.as_str())
                .map_err(EngineError::Common)?;
            if let Err(error) = g.check_ingest_admission() {
                // The rejection does not free the memtable or the RSS that
                // tripped it. Request the drain on this 429, not only on the
                // sampler's next tick (#2321, #948).
                crate::engine::request_memory_pressure_drain();
                return Err(EngineError::Common(error));
            }
        }
        Ok(())
    }

    /// Reserve headroom for the token spike of `docs` before they are parsed
    /// (#1122). See [`crate::governor::analyze_reserve_bytes`]. No governor
    /// reserves nothing, so an `Index` built directly in a unit test is unchanged.
    fn reserve_batch_analyze(
        docs: &[xerj_storage::RawJsonDoc],
    ) -> Result<crate::governor::AnalyzeReservation> {
        let Some(governor) = crate::governor::global() else {
            return Ok(crate::governor::AnalyzeReservation::none());
        };
        let raw = docs.iter().map(|(_, bytes)| bytes.len() as u64).sum();
        governor
            .reserve_analyze(crate::governor::analyze_reserve_bytes(raw))
            .map_err(EngineError::Common)
    }

    /// Every block name the `_block` API and `index.blocks.*` settings accept.
    pub const BLOCK_NAMES: [&'static str; 5] = [
        "read_only",
        "read_only_allow_delete",
        "write",
        "metadata",
        "read",
    ];

    /// Every JSON location one `index.blocks.<name>` flag can occupy in a
    /// stored settings document, canonical form first.
    ///
    /// A settings body is stored the way the client wrote it — `PUT /{index}`
    /// forwards its `settings` blob to `Index::new` verbatim — and ES accepts
    /// the nested and the dotted spellings interchangeably. Reading only the
    /// nested one meant an index created with
    /// `{"settings": {"index.blocks.write": true}}` reported no block and
    /// admitted every write.
    fn block_flag_pointers(name: &str) -> [String; 4] {
        [
            format!("/index/blocks/{name}"),
            format!("/index/blocks.{name}"),
            format!("/index.blocks.{name}"),
            format!("/blocks/{name}"),
        ]
    }

    /// Reads one `index.blocks.<name>` flag in whichever spelling it was stored
    /// under. Accepts the boolean `true` and the string `"true"` — ES
    /// normalises index settings to strings on the wire, so a settings round
    /// trip can hand us either shape.
    fn block_flag(settings: &Value, name: &str) -> bool {
        Self::block_flag_pointers(name)
            .iter()
            .find_map(|p| match settings.pointer(p) {
                Some(Value::Bool(b)) => Some(*b),
                Some(Value::String(s)) => Some(s.eq_ignore_ascii_case("true")),
                _ => None,
            })
            .unwrap_or(false)
    }

    /// Names the block that is currently denying **writes** on this index, or
    /// `None` when writes are admitted.
    ///
    /// The returned name is threaded into `XerjError::IndexBlocked` so the HTTP
    /// layer can pick the status ES picks. Three settings deny writes, and they
    /// do *not* all answer the same status:
    ///
    /// | setting | denies | status |
    /// |---|---|---|
    /// | `index.blocks.write` | writes | 403 |
    /// | `index.blocks.read_only` | writes + metadata changes | 403 |
    /// | `index.blocks.read_only_allow_delete` | writes (incl. doc deletes) | 429 |
    ///
    /// Precedence is 403-before-429, matching how ES collapses a multi-block
    /// `ClusterBlockException` down to one status: a non-retryable block always
    /// wins over a retryable one
    /// (`cluster/block/ClusterBlockException.java:95-107`, approach only — ES is
    /// AGPL/SSPL/Elastic-2.0 and no code from it is reproduced here).
    ///
    /// Note what is deliberately **absent**: none of these deny *reads*. Only
    /// `index.blocks.read` does that. `read_only` means "readable, not
    /// writable", and `read_only_allow_delete` is the disk flood-stage block —
    /// the "allow delete" is index deletion, not document deletion
    /// (`docs/reference/elasticsearch/index-settings/index-block.md:29-34`:
    /// "When `index.blocks.read_only_allow_delete` is set to `true`, deleting
    /// documents is not permitted. However, deleting the index entirely …
    /// is still permitted").
    pub async fn write_block_reason(&self) -> Option<&'static str> {
        let settings = self.settings.read().await;
        for name in ["write", "read_only", "read_only_allow_delete"] {
            if Self::block_flag(&settings, name) {
                return Some(name);
            }
        }
        None
    }

    /// Returns true if any write-denying block is set on this index.
    pub async fn is_write_blocked(&self) -> bool {
        self.write_block_reason().await.is_some()
    }

    /// Returns true if the read block is set on this index.
    ///
    /// Only `index.blocks.read` denies reads. `read_only` and
    /// `read_only_allow_delete` leave the index searchable — see
    /// [`Self::write_block_reason`].
    pub async fn is_read_blocked(&self) -> bool {
        let settings = self.settings.read().await;
        Self::block_flag(&settings, "read")
    }

    /// Erase every spelling of one block flag from a settings document, leaving
    /// the canonical nested slot for the caller to write (or leave absent).
    fn remove_block_spellings(settings: &mut Value, name: &str) {
        let Some(root) = settings.as_object_mut() else {
            return;
        };
        root.remove(&format!("index.blocks.{name}"));
        if let Some(blocks) = root.get_mut("blocks").and_then(Value::as_object_mut) {
            blocks.remove(name);
        }
        if let Some(index) = root.get_mut("index").and_then(Value::as_object_mut) {
            index.remove(&format!("blocks.{name}"));
            if let Some(blocks) = index.get_mut("blocks").and_then(Value::as_object_mut) {
                blocks.remove(name);
            }
        }
    }

    /// Set a named block on the index (`read_only`, `read_only_allow_delete`, `write`, `metadata`, `read`).
    ///
    /// Stores as `index.blocks.<block_name> = true` in the settings.
    pub async fn set_block(&self, block_name: &str) -> Result<()> {
        self.set_block_state(block_name, true).await
    }

    /// Clear a named block. The inverse of [`Self::set_block`], and what both
    /// `DELETE /{index}/_block/{block}` and a
    /// `PUT /{index}/_settings {"index.blocks.<name>": false}` land on.
    pub async fn clear_block(&self, block_name: &str) -> Result<()> {
        self.set_block_state(block_name, false).await
    }

    /// Set or clear `index.blocks.<block_name>`, persisting the result.
    ///
    /// Stores exactly the block the caller named — no alias expansion. Deriving
    /// the effect at read time ([`Self::write_block_reason`]) instead of writing
    /// derived flags at set time is what makes removal work: with expansion, a
    /// `read_only` block left an independent `blocks.write: true` behind that
    /// clearing `read_only` could not reach.
    ///
    /// Both directions first drop every non-canonical spelling of the block
    /// ([`Self::block_flag_pointers`]), so a dotted key left by a create-time
    /// settings body cannot outlive the nested key and silently re-block the
    /// index — the same "block with no removal path" shape this fixes.
    pub async fn set_block_state(&self, block_name: &str, enabled: bool) -> Result<()> {
        let mut settings = {
            let guard = self.settings.read().await;
            guard.clone()
        };

        // Ensure nested structure: settings["index"]["blocks"][block_name].
        if !settings.is_object() {
            settings = Value::Object(serde_json::Map::new());
        }
        Self::remove_block_spellings(&mut settings, block_name);
        let obj = settings.as_object_mut().unwrap();
        let index_obj = match obj
            .entry("index")
            .or_insert_with(|| Value::Object(serde_json::Map::new()))
            .as_object_mut()
        {
            Some(o) => o,
            // A non-object `index` value (corrupt settings.json) — replace it
            // rather than panic.
            None => {
                obj.insert("index".to_string(), Value::Object(serde_json::Map::new()));
                obj.get_mut("index").unwrap().as_object_mut().unwrap()
            }
        };
        let blocks_obj = match index_obj
            .entry("blocks")
            .or_insert_with(|| Value::Object(serde_json::Map::new()))
            .as_object_mut()
        {
            Some(o) => o,
            None => {
                index_obj.insert("blocks".to_string(), Value::Object(serde_json::Map::new()));
                index_obj
                    .get_mut("blocks")
                    .unwrap()
                    .as_object_mut()
                    .unwrap()
            }
        };
        if enabled {
            blocks_obj.insert(block_name.to_string(), Value::Bool(true));
        } else {
            // Removing the key rather than storing `false` keeps a cleared
            // block out of GET /_settings, which is what ES shows.
            blocks_obj.remove(block_name);
        }

        let path = self.data_dir.join("settings.json");
        let bytes = serde_json::to_vec_pretty(&settings)?;
        write_file_atomic(&path, &bytes).map_err(EngineError::Io)?;
        *self.settings.write().await = settings;
        // #965 — index blocks live in settings.json; keep the bucket's meta
        // copy in step so a fresh node honours the same blocks.
        publish_index_meta_objects(&self.store, &self.data_dir, self.name.as_str());
        Ok(())
    }

    /// Apply an `index.blocks` sub-document from a settings update.
    ///
    /// Accepts the nested (`{"index": {"blocks": {"write": false}}}`), dotted
    /// (`{"index.blocks.write": false}`) and bare (`{"blocks": {...}}`) shapes
    /// that ES settings bodies come in. Values may be JSON booleans or the
    /// strings `"true"`/`"false"` — ES stringifies index settings on the wire.
    ///
    /// Returns the block names that changed state.
    pub async fn apply_block_settings(&self, body: &Value) -> Result<Vec<String>> {
        let as_bool = |v: &Value| -> Option<bool> {
            match v {
                Value::Bool(b) => Some(*b),
                Value::String(s) if s.eq_ignore_ascii_case("true") => Some(true),
                Value::String(s) if s.eq_ignore_ascii_case("false") => Some(false),
                Value::Null => Some(false),
                _ => None,
            }
        };

        // Collect name → desired state from every accepted shape.
        let mut wanted: Vec<(String, bool)> = Vec::new();
        let mut collect_nested = |blocks: &Value| {
            if let Some(map) = blocks.as_object() {
                for (name, v) in map {
                    if Self::BLOCK_NAMES.contains(&name.as_str()) {
                        if let Some(b) = as_bool(v) {
                            wanted.push((name.clone(), b));
                        }
                    }
                }
            }
        };
        if let Some(b) = body.pointer("/index/blocks") {
            collect_nested(b);
        }
        if let Some(b) = body.get("blocks") {
            collect_nested(b);
        }
        if let Some(map) = body.as_object() {
            for (k, v) in map {
                let name = k
                    .strip_prefix("index.blocks.")
                    .or_else(|| k.strip_prefix("blocks."));
                if let Some(name) = name {
                    if Self::BLOCK_NAMES.contains(&name) {
                        if let Some(b) = as_bool(v) {
                            wanted.push((name.to_string(), b));
                        }
                    }
                }
            }
        }
        // `{"index": {"blocks.write": false}}` — dotted under a nested `index`.
        if let Some(map) = body.get("index").and_then(Value::as_object) {
            for (k, v) in map {
                if let Some(name) = k.strip_prefix("blocks.") {
                    if Self::BLOCK_NAMES.contains(&name) {
                        if let Some(b) = as_bool(v) {
                            wanted.push((name.to_string(), b));
                        }
                    }
                }
            }
        }

        let mut applied = Vec::new();
        for (name, enabled) in wanted {
            let current = {
                let guard = self.settings.read().await;
                Self::block_flag(&guard, &name)
            };
            if current == enabled {
                continue;
            }
            self.set_block_state(&name, enabled).await?;
            applied.push(name);
        }
        Ok(applied)
    }

    // ── Schema ────────────────────────────────────────────────────────────────

    /// Get the current schema.
    pub async fn schema(&self) -> Schema {
        self.schema.read().await.schema.clone()
    }

    /// What this node actually runs for semantic search over `field` — the
    /// facts behind any "semantic" claim a console or agent surface renders.
    ///
    /// Resolved EXACTLY the way the query and ingest paths resolve it (same
    /// alias handling, same `dimensions.unwrap_or(DEFAULT_DIMS)` fallback,
    /// the same embedder instance), so a claim built from these facts cannot
    /// drift from what a query actually does:
    ///
    /// - `Some(facts)` — `field` carries an [`crate::FieldConfig::embedding`]
    ///   config (an ES `semantic_text` field): the companion `target_field`
    ///   holds one vector per embedded document, `dims`/`similarity` are the
    ///   effective ones, and `embedder` is the backend's own label (e.g.
    ///   `"lexical feature-hash (built-in, 384-dim, non-neural)"`).
    /// - `None` — no embedding config: there is no stored vector to match,
    ///   and the honest answer is "none on this node", never a count derived
    ///   from terms or tokens.
    ///
    /// The facts deliberately carry NO vector count: the engine exposes no
    /// per-field vector count on any stats surface, and a number it cannot
    /// back must not exist (the honest-claims rule binds UIs, not just docs).
    pub async fn semantic_field_facts(&self, field: &str) -> Option<SemanticFieldFacts> {
        let guard = self.schema.read().await;
        let resolved = resolve_field_alias(&guard.schema, field);
        let fc = guard.schema.field(&resolved)?;
        let emb = fc.embedding.as_ref()?;
        let target_field = emb
            .target_field
            .clone()
            .unwrap_or_else(|| format!("{resolved}_vector"));
        let (dims, dims_from_schema) = match fc.options.dimensions {
            Some(d) => (d, true),
            None => (xerj_ai::local::DEFAULT_DIMS, false),
        };
        let similarity = fc
            .options
            .similarity
            .clone()
            .unwrap_or_else(|| "cosine".to_string());
        drop(guard);
        let embedder = self.embedder.read().await;
        Some(SemanticFieldFacts {
            field: resolved,
            target_field,
            dims,
            dims_from_schema,
            similarity,
            embedder: embedder.describe(),
            embedder_active: embedder.is_active(),
        })
    }

    /// Add a field to the schema.
    pub async fn add_field(self: &Arc<Self>, field: FieldConfig) -> Result<()> {
        self.add_fields(vec![field]).await
    }

    /// Atomically add several fields to the schema.
    ///
    /// Mapping updates can introduce a semantic source and its derived vector
    /// companion together. Validate and persist the complete candidate schema
    /// before publishing it so a later-field failure cannot leave half of that
    /// contract visible.
    pub async fn add_fields(self: &Arc<Self>, fields: Vec<FieldConfig>) -> Result<()> {
        if fields.is_empty() {
            return Ok(());
        }
        let mut schema = self.schema.write().await;
        let current = schema.clone();
        let activates_embedder =
            schema_needs_embedder(&fields) && !schema_needs_embedder(&current.schema.fields);
        let activated = if activates_embedder {
            Some(make_embedder(&self.embedding_config)?)
        } else {
            None
        };
        if schema_has_embeddings(&fields) {
            if self
                .embedding_config
                .mode
                .eq_ignore_ascii_case("onnx-experimental")
            {
                validate_onnx_dimensions(&fields)?;
            }
            ensure_embedding_identity_for_new_field(&self.data_dir, &self.embedding_config)?;
        }
        let mut candidate = current;
        for field in fields {
            candidate.add_field(field)?;
        }
        // Mapping-explosion guard (#76 S5-5): enforce `max_fields_per_index` on
        // the EXPLICIT mapping path (`PUT /:index/_mapping`,
        // `POST /v1/schema/:name/evolve`) too, not only the dynamic-ingest path.
        // `ManagedSchema::add_field` does not check the cap, so without this an
        // authenticated caller could bypass the mapping-explosion limit by
        // supplying fields explicitly. Reject before publishing the candidate.
        let projected = candidate.schema.field_count() as u32;
        if projected > self.max_fields_per_index {
            return Err(EngineError::Common(
                xerj_common::XerjError::invalid_mapping(format!(
                    "Limit of total fields [{}] has been exceeded: this mapping update would \
                     bring the index to {projected} fields",
                    self.max_fields_per_index
                )),
            ));
        }
        if self.live_doc_count() > 0 {
            let active_before: HashSet<String> = passage_scored_vector_fields(&schema.schema)
                .into_iter()
                .collect();
            let newly_active = passage_scored_vector_fields(&candidate.schema)
                .into_iter()
                .filter(|field| !active_before.contains(field));
            // Existing sources can contain hidden `<field>_chunks` values
            // (notably under dynamic:false). Without an authoritative scan in
            // this mapping transaction, newly activating vector semantics
            // must conservatively choose exact before schema visibility.
            self.passage_chunk_fields
                .write()
                .unwrap()
                .extend(newly_active);
        }
        self.save_schema(&candidate).await?;
        if let Some(embedder) = activated {
            *self.embedder.write().await = embedder;
        }
        *schema = candidate;
        drop(schema);
        // #392: a mapping update can introduce a `scalar8` field — create
        // its code store now and walk the live docs (the index may already
        // carry documents predating the handle).
        for field in self.ensure_sq8_stores().await {
            self.spawn_sq8_walk(&field);
        }
        Ok(())
    }

    // ── Suggest helpers ───────────────────────────────────────────────────────

    /// Return all indexed (term, doc_frequency) pairs for a given field.
    ///
    /// Combines terms from:
    /// 1. The active memtable's inverted index.
    /// 2. All frozen memtables.
    /// 3. On-disk FTS segments (via FST scan).
    ///
    /// This is used by the term suggester to find candidates via Levenshtein
    /// distance, and by the completion suggester for prefix autocomplete.
    pub async fn get_all_terms_for_field(&self, field: &str) -> Vec<(String, usize)> {
        let mut term_counts: HashMap<String, usize> = HashMap::new();

        // 1. Active memtable.
        {
            let mem = &*self.memtable;
            for (term, freq) in mem.all_terms_for_field(field) {
                *term_counts.entry(term).or_insert(0) += freq;
            }
            // Also include keyword values for completion suggester.
            for (val, _) in mem.all_keyword_values_for_field(field) {
                term_counts.entry(val).or_insert(1);
            }
        }

        // 2. On-disk FTS segments.
        {
            let snap = self.store.snapshot();
            let segments_dir = self.data_dir.join("segments");
            for meta in &snap.segments {
                if let Ok(reader) = FtsIndexReader::open(&segments_dir, &meta.id, &[field]) {
                    for term in reader.all_terms(field) {
                        term_counts.entry(term).or_insert(1);
                    }
                }
            }
        }

        term_counts.into_iter().collect()
    }

    /// Return the data directory path for this index (used by snapshot/restore).
    pub fn data_dir(&self) -> &Path {
        &self.data_dir
    }

    /// Root of this index's write-ahead log — the directory holding either
    /// `*.wal` files (legacy single-WAL layout) or `s0`, `s1`, … shard
    /// subdirectories.
    ///
    /// Read-only consumers live here: the WAL tap (`crate::wal_tap`) tails
    /// these files on a timer so it never has to take a lock the write path
    /// wants.
    pub fn wal_dir(&self) -> PathBuf {
        self.store.wal_dir()
    }

    // ── Delete index ──────────────────────────────────────────────────────────

    /// Remove all data files for this index.
    pub async fn delete_all_data(&self) -> Result<()> {
        std::fs::remove_dir_all(&self.data_dir).map_err(EngineError::Io)?;
        Ok(())
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    /// Set the ES `date_detection` toggle for dynamic inference. Called by
    /// the engine whenever the index mapping is created, loaded from disk,
    /// or replaced via PUT /_mapping.
    pub fn set_date_detection(&self, on: bool) {
        self.date_detection.store(on, Ordering::Relaxed);
    }

    /// Current `date_detection` state (default true, like ES).
    pub fn date_detection_enabled(&self) -> bool {
        self.date_detection.load(Ordering::Relaxed)
    }

    /// Replace the set of date fields excluded from default-format ingest
    /// validation (fields with an explicit mapping `format` — validated
    /// separately by `bulk::find_bad_date_field` — or `ignore_malformed`).
    /// Engine-propagated together with [`Index::set_date_detection`].
    pub fn set_date_format_exclusions(&self, excluded: std::collections::HashSet<String>) {
        if let Ok(mut guard) = self.date_format_exclusions.write() {
            *guard = Arc::new(excluded);
        }
    }

    /// Reject documents whose value for a DEFAULT-format date field (most
    /// importantly a dynamically-inferred one) cannot possibly parse under
    /// ES's default `strict_date_optional_time||epoch_millis` — real ES
    /// answers 400 `mapper_parsing_exception`; xerj previously accepted the
    /// doc silently, leaving the value invisible to range queries, sorts,
    /// and Kibana time filters. Runs on the per-doc write funnel only; the
    /// raw-bytes turbo batch paths intentionally skip it (they never parse
    /// doc bodies — same envelope as the pre-existing explicit-format
    /// validation, which routes strict-format indexes off turbo entirely).
    async fn validate_default_format_dates(&self, source: &Value) -> Result<()> {
        if !self.has_date_fields.load(Ordering::Relaxed) {
            return Ok(());
        }
        let Some(obj) = source.as_object() else {
            return Ok(());
        };
        let exclusions = self
            .date_format_exclusions
            .read()
            .map(|g| Arc::clone(&g))
            .unwrap_or_default();
        let schema = self.schema.read().await;
        for (key, val) in obj {
            if val.is_null() {
                continue;
            }
            let Some(fc) = schema.field(key) else {
                continue;
            };
            if !matches!(fc.field_type, FieldType::Date) || exclusions.contains(key) {
                continue;
            }
            if !default_format_date_value_ok(val) {
                let preview: String = match val {
                    Value::String(s) => s.chars().take(64).collect(),
                    other => other.to_string().chars().take(64).collect(),
                };
                return Err(EngineError::Common(
                    xerj_common::XerjError::InvalidMapping {
                        reason: format!(
                            "failed to parse field [{key}] of type [date] with value [{preview}]"
                        ),
                    },
                ));
            }
        }
        Ok(())
    }

    /// Batch variant of [`evolve_schema_from_doc`]: one schema read-lock
    /// acquisition for the WHOLE batch instead of one per doc.  The per-doc
    /// variant paid a tokio `RwLock::read().await` per document — measured
    /// ~22 ms per 10 k-doc bulk batch (≈ a quarter of the whole turbo exec
    /// phase) even though the schema stops evolving after the first docs.
    ///
    /// Semantics are identical to calling `evolve_schema_from_doc` serially
    /// in doc order: new fields are collected in FIRST-SEEN order (so the
    /// first doc that introduces a field decides its inferred type) and
    /// added under a single write lock, which re-checks `has_field` exactly
    /// like the per-doc slow path does.
    async fn evolve_schema_from_docs(&self, sources: &[Arc<Value>]) {
        // Fast path: read-lock scan for TWO kinds of change, not just one --
        // a brand-new top-level field (as before), or a NEW NESTED CHILD
        // under a top-level field the schema already knows about (the fix
        // for a real gap found in review: gating purely on "does the
        // top-level key already exist" meant a later document introducing
        // e.g. `metadata.project` after an earlier one already registered
        // `metadata` from its own `{"kind": ...}` was never inspected again,
        // no matter how many more documents arrived -- see
        // `field_config_needs_merge`'s doc comment for the full story).
        // Stores the raw value (not a precomputed FieldConfig) for both
        // kinds, so the write-lock section below can re-derive against the
        // live schema rather than trusting a possibly-stale read-lock
        // snapshot.
        let (new_top_level, needs_merge): (Vec<(String, Value)>, Vec<(String, Value)>) = {
            let schema = self.schema.read().await;
            if !matches!(schema.dynamic, xerj_common::schema::DynamicMapping::Dynamic) {
                return;
            }
            let mut new_top_level = Vec::new();
            let mut needs_merge = Vec::new();
            for source in sources {
                let Some(obj) = source.as_object() else {
                    continue;
                };
                for (key, val) in obj {
                    if key.starts_with(PASSAGE_METADATA_PREFIX)
                        || is_undeclared_multi_vector_companion(&schema.schema, key, val)
                    {
                        continue;
                    }
                    match schema.schema.field(key) {
                        None => new_top_level.push((key.clone(), val.clone())),
                        Some(existing) => {
                            if field_config_needs_merge(existing, val) {
                                needs_merge.push((key.clone(), val.clone()));
                            }
                        }
                    }
                }
            }
            (new_top_level, needs_merge)
        };

        if new_top_level.is_empty() && needs_merge.is_empty() {
            return;
        }

        // Mapping-explosion guard: enforce `max_fields_per_index` on the
        // production ingest path. `ManagedSchema::apply_document` checks the
        // same limit, but the engine's dynamic-mapping path calls
        // `Schema::add_field` directly, which previously bypassed the cap.
        // An authenticated client could ingest documents with arbitrarily many
        // distinct field names, bloating the schema unbounded. This is an
        // approximate early exit on `new_top_level` alone (a `needs_merge`
        // entry might add zero fields or several, not knowable without
        // walking it against the live schema, which the write-lock section
        // below does anyway) -- the write lock's own per-field checks are
        // the real, exact enforcement.
        {
            let schema = self.schema.read().await;
            let current = schema.schema.field_count() as u32;
            let projected = current.saturating_add(new_top_level.len() as u32);
            if projected > self.max_fields_per_index {
                tracing::warn!(
                    current_fields = current,
                    new_fields = new_top_level.len(),
                    limit = self.max_fields_per_index,
                    "rejecting schema evolution: field limit exceeded"
                );
                return;
            }
        }

        let date_detection = self.date_detection_enabled();
        let mut schema = self.schema.write().await;
        if !matches!(schema.dynamic, xerj_common::schema::DynamicMapping::Dynamic) {
            return;
        }
        // Re-derive against the live schema under the write lock rather than
        // trusting the read-lock snapshot: another concurrent ingest may
        // have already added fields (up to the limit, or the exact ones
        // this batch also wants) between the read-lock check above and this
        // write lock.
        let mut schema_changed = false;
        let mut field_count = schema.schema.field_count() as u32;
        for (key, val) in new_top_level {
            if let Some(existing) = schema.schema.field_mut(&key) {
                // Raced in since the read-lock scan -- merge into it
                // instead of skipping outright, so a key another doc in
                // this same batch also introduces isn't lost.
                if merge_dynamic_children_into(
                    existing,
                    &val,
                    date_detection,
                    1,
                    &mut field_count,
                    self.max_fields_per_index,
                ) {
                    schema_changed = true;
                }
                continue;
            }
            let fc = dynamic_field_config(&key, &val, date_detection);
            // #312: `fc` can carry an entire nested subtree, so count its real
            // recursive size (`total_field_count`, the same measure the guard's
            // `Schema::field_count()` uses) — counting it as one field let a
            // single insert overshoot `max_fields_per_index` by the subtree's
            // key count before the next evolve recomputed the budget.
            let fc_size = fc.total_field_count() as u32;
            if field_count + fc_size > self.max_fields_per_index {
                tracing::warn!(
                    field = %key,
                    limit = self.max_fields_per_index,
                    "rejecting new field: field limit reached"
                );
                break;
            }
            if matches!(fc.field_type, FieldType::Date) {
                self.has_date_fields.store(true, Ordering::Relaxed);
            }
            field_count += fc_size;
            let _ = schema.schema.add_field(fc);
            schema_changed = true;
        }
        for (key, val) in needs_merge {
            if let Some(existing) = schema.schema.field_mut(&key) {
                if merge_dynamic_children_into(
                    existing,
                    &val,
                    date_detection,
                    1,
                    &mut field_count,
                    self.max_fields_per_index,
                ) {
                    schema_changed = true;
                }
            }
        }
        if schema_changed {
            self.persist_evolved_schema(&schema).await;
        }
    }

    async fn evolve_schema_from_doc(&self, source: &Value) {
        let obj = match source.as_object() {
            Some(o) => o,
            None => return,
        };

        // Fast path: check with a read lock first to avoid taking a write lock
        // on every document when all fields are already known.  This is the
        // common case after the first few documents and avoids the write lock
        // bottleneck that otherwise limits indexing throughput. `needs_write`
        // covers both a brand-new top-level field and a new nested child
        // under an already-known one -- see `evolve_schema_from_docs` for
        // the full rationale (same fix, single-document form).
        let needs_write = {
            let schema = self.schema.read().await;
            if !matches!(schema.dynamic, xerj_common::schema::DynamicMapping::Dynamic) {
                return;
            }
            obj.iter().any(|(key, val)| {
                if key.starts_with(PASSAGE_METADATA_PREFIX)
                    || is_undeclared_multi_vector_companion(&schema.schema, key, val)
                {
                    return false;
                }
                match schema.schema.field(key) {
                    None => true,
                    Some(existing) => field_config_needs_merge(existing, val),
                }
            })
        };

        if !needs_write {
            // Nothing new — skip the write lock entirely (hot path).
            return;
        }

        // Mapping-explosion guard (see evolve_schema_from_docs for rationale
        // -- this single-document form only ever contributes at most
        // `obj.len()` brand-new top-level fields, so that bound is used for
        // the same approximate early exit; a merge's real growth is
        // enforced exactly under the write lock below).
        {
            let schema = self.schema.read().await;
            let current = schema.schema.field_count() as u32;
            let new_top_level_upper_bound =
                obj.keys().filter(|k| !schema.schema.has_field(k)).count() as u32;
            let projected = current.saturating_add(new_top_level_upper_bound);
            if projected > self.max_fields_per_index {
                tracing::warn!(
                    current_fields = current,
                    new_fields = new_top_level_upper_bound,
                    limit = self.max_fields_per_index,
                    "rejecting schema evolution: field limit exceeded"
                );
                return;
            }
        }

        // Slow path: at least one new field or new nested child found.
        // Upgrade to write lock and persist the updated schema.
        let date_detection = self.date_detection_enabled();
        let mut schema = self.schema.write().await;
        if !matches!(schema.dynamic, xerj_common::schema::DynamicMapping::Dynamic) {
            return;
        }
        let mut schema_changed = false;
        let mut field_count = schema.schema.field_count() as u32;
        for (key, val) in obj {
            if key.starts_with(PASSAGE_METADATA_PREFIX)
                || is_undeclared_multi_vector_companion(&schema.schema, key, val)
            {
                continue;
            }
            if let Some(existing) = schema.schema.field_mut(key) {
                if merge_dynamic_children_into(
                    existing,
                    val,
                    date_detection,
                    1,
                    &mut field_count,
                    self.max_fields_per_index,
                ) {
                    schema_changed = true;
                }
                continue;
            }
            let fc = dynamic_field_config(key, val, date_detection);
            // #312: count the new field's real recursive subtree size, not one,
            // so a single nested-object insert cannot overshoot the budget (the
            // single-doc evolve path, the twin of `evolve_schema_from_docs`).
            let fc_size = fc.total_field_count() as u32;
            if field_count + fc_size > self.max_fields_per_index {
                tracing::warn!(
                    field = %key,
                    limit = self.max_fields_per_index,
                    "rejecting new field: field limit reached"
                );
                break;
            }
            if matches!(fc.field_type, FieldType::Date) {
                self.has_date_fields.store(true, Ordering::Relaxed);
            }
            field_count += fc_size;
            let _ = schema.schema.add_field(fc);
            schema_changed = true;
        }
        if schema_changed {
            self.persist_evolved_schema(&schema).await;
        }
    }

    /// Persist a dynamic-mapping evolution, complaining loudly if it does not
    /// stick.
    ///
    /// Issue #204: both callers used to be `let _ = self.save_schema(..)`. The
    /// in-memory schema had the new fields, `schema.json` did not, and the next
    /// restart reopened the index with a mapping that had silently rolled back
    /// — documents already on disk carrying those fields, no mapping for them,
    /// and not one line anywhere saying why.
    ///
    /// This is a log-and-surface fix, not a fail-closed one, and deliberately
    /// so: schema evolution runs *after* the document has been admitted, so
    /// there is no caller left to fail. Losing the durable mapping is the lesser
    /// evil against rejecting a document that is already indexed — but it is
    /// an ERROR, not a shrug. `schema_persist_failures` counts it so a health
    /// check can see it without reading logs.
    async fn persist_evolved_schema(&self, schema: &ManagedSchema) {
        if let Err(e) = self.save_schema(schema).await {
            self.schema_persist_failures.fetch_add(1, Ordering::Relaxed);
            tracing::error!(
                index = self.name.as_str(),
                path = %self.data_dir.join("schema.json").display(),
                error = %e,
                "failed to persist dynamic mapping evolution — the new fields are \
                 live in memory but WILL BE LOST on restart"
            );
        }
    }

    /// Number of times [`Self::persist_evolved_schema`] could not write
    /// `schema.json`. Non-zero means the on-disk mapping is behind the
    /// in-memory one and a restart will lose dynamically-mapped fields.
    ///
    /// Read by `GET /{index}/_stats`, which reports it as
    /// `primaries.mappings.schema_persist_failures`, and by `GET /_all/_stats`,
    /// which reports the sum over every index at
    /// `_all.primaries.mappings.schema_persist_failures` — so a health check
    /// can see it without reading logs.
    pub fn schema_persist_failures(&self) -> u64 {
        self.schema_persist_failures.load(Ordering::Relaxed)
    }

    async fn save_schema(&self, schema: &ManagedSchema) -> Result<()> {
        let path = self.data_dir.join("schema.json");
        let bytes = serde_json::to_vec_pretty(schema)?;
        write_file_atomic(&path, &bytes).map_err(EngineError::Io)?;
        // #965 — every schema mutation funnels through here, so this is also
        // the single place the bucket's meta/schema.json copy is refreshed.
        publish_index_meta_objects(&self.store, &self.data_dir, self.name.as_str());
        // Every schema mutation funnels through here (`add_fields` for an
        // explicit mapping update, `persist_evolved_schema` for dynamic
        // evolution), so this is the one place the sync-readable date-scale
        // mirror has to be refreshed (#790). Swapped as a whole `Arc` so a
        // concurrent reader never observes a half-rebuilt set.
        let next = Arc::new(date_field_scales(&schema.schema));
        let changed = {
            let mut cur = self.date_field_scales.write();
            let changed = **cur != *next;
            *cur = next;
            changed
        };
        if changed {
            // A field that just moved between scales has cached shadows and
            // range prefilters keyed on the OLD one. Leaving them would put
            // the shadow keys and a fresh bound back on different scales —
            // the exact divergence #790 is about. They rebuild on demand.
            self.sort_shadow_cache.clear();
            self.sort_shadow_fields.clear();
            self.range_prefilter_cache.clear();
        }
        Ok(())
    }

    /// The epoch scale `field`'s dates normalise on (#790).
    ///
    /// Read off the sync mirror of the mapping; an undeclared field, or one
    /// whose mapping predates the `date_precision` flag and whose index has no
    /// `es_mapping.json` to back-fill it from, keeps the legacy per-value
    /// guess.
    fn date_scale(&self, field: &str) -> DateScale {
        self.date_field_scales
            .read()
            .get(field)
            .copied()
            .unwrap_or(DateScale::PerValue)
    }

    /// The epoch scale ONE SORT wants `sf.field`'s dates on (#889).
    ///
    /// Normally the field's own mapped scale. ES `numeric_type` overrides it,
    /// which is the only way a cross-index sort over a field mapped `date`
    /// here and `date_nanos` there can compare at all: every participating
    /// index is asked for keys on the same scale. `long`/`double` are not date
    /// conversions and leave the field's scale alone.
    fn date_scale_for_sort(&self, sf: &xerj_query::sort::SortField) -> DateScale {
        match sf.numeric_type.as_deref() {
            Some("date") => DateScale::Millis,
            Some("date_nanos") => DateScale::Nanos,
            _ => self.date_scale(&sf.field),
        }
    }

    async fn fill_memtable_sources(&self, hits: Vec<Hit>) -> Vec<Hit> {
        // Look up sources from the active memtable for unflushed docs.
        // Flushed docs already have their sources filled by the segment reader
        // path in search_inner().
        let mem = &*self.memtable;
        hits.into_iter()
            .map(|mut h| {
                if h.source.is_null() {
                    if let Some(source) = mem.get_doc_source_as_value(&h.id) {
                        h.source = source;
                    }
                    // If still null, try loading from disk segments.  This can
                    // happen for FTS hits from the active memtable that were
                    // found by score but whose source was not cloned inline.
                }
                // Catch-all for whichever construction sites deliberately
                // left `seq_no`/`version` unresolved alongside a deferred
                // `source` (#440) — resolved here, at the SAME moment as the
                // `source` fill above, only for hits that reach this final,
                // already-bounded page. A no-op for hits already populated
                // at construction time (the overwhelming majority).
                if h.seq_no.is_none() {
                    if let Some(ver) = self.store.version_map.get(&h.id) {
                        let (seq_no, version) = self.hit_seq_version(&h.id, &ver);
                        h.seq_no = seq_no;
                        h.version = version;
                    }
                }
                h
            })
            .collect()
    }
}

// ── Doc-values side-car helpers ─────────────────────────────────────────────
//
// One side-car file per segment named `{segment_id}.dv` that holds an
// LZ4-compressed `BTreeMap<String, Column>` (numeric or keyword).  Writing
// happens at flush + merge time; reading happens from the agg / sort /
// term-count fast paths.  Mirrors the Lucene `.dvd`/`.dvm` design
// philosophy of "every field has a column store" without tying us to
// Lucene's particular block-bitpacking layout (we use whole-vec encoding
// in M2; M3 introduces 128-doc bitpacked blocks).
//
// Auto-typing: any source field whose values are all numeric becomes a
// numeric column; otherwise a keyword column with the values stringified.
// This mirrors what ES does when `dynamic` mapping infers field types
// without explicit schema declarations.

/// Fields whose declared mapping says they must NOT get a doc-values column.
///
/// Derived from the SCHEMA rather than from the documents, so it is stable
/// across flush and merge — a force-merge must not resurrect a column that
/// flush correctly skipped. Inferred fields carry their own flag too
/// (`dynamic_field_config*`: `Text` gets `false`, mirroring ES's dynamic
/// mapping and the declared default), so they take this skip set rather than
/// the builder's per-document default.
pub fn doc_values_skip_set(schema: &Schema) -> std::collections::HashSet<String> {
    let mut skip = std::collections::HashSet::new();
    for field in &schema.fields {
        if !field.options.doc_values {
            skip.insert(field.name.clone());
        }
    }
    skip
}

/// The doc-values input of a merge batch, read back from the batch's
/// merged stored JSON one document at a time (#2427).
///
/// `merged_json` is the `[doc,doc,...]` array the merge byte-copies its
/// survivors into, in merged ordinal order. Each item is that document's
/// `_source` (or `Null` when it has none or does not parse, the same
/// fallback the merge used when it held the trees), and is dropped by
/// [`build_doc_value_columns`] before the next one is parsed. Only one
/// `_source` tree is alive at a time; before #2427 the merge held one per
/// surviving document from the drain loop to the end of the batch, on top
/// of the stored encoder's own `Vec<Value>` of the same documents.
///
/// `Err` means the buffer is not a JSON array (it is built from documents
/// that already parsed as `RawValue`, so this does not happen in practice).
fn merge_doc_value_sources(
    merged_json: &[u8],
) -> std::result::Result<impl Iterator<Item = Option<Value>> + '_, serde_json::Error> {
    #[derive(serde::Deserialize)]
    struct SourceOnly {
        #[serde(rename = "_source", default)]
        source: Value,
    }
    let docs: Vec<&serde_json::value::RawValue> = serde_json::from_slice(merged_json)?;
    Ok(docs.into_iter().map(|raw| {
        Some(
            serde_json::from_str::<SourceOnly>(raw.get())
                .map(|doc| doc.source)
                .unwrap_or(Value::Null),
        )
    }))
}

/// Build the per-segment doc-values columns.
///
/// `skip` names fields whose declared mapping says they must not have
/// doc-values — either an explicit `"doc_values": false`, or an analyzed/large
/// type (`text`, `semantic_text`, `binary`, …) that did not ask for them. The
/// builder is otherwise schema-free and files a column for every `_source` key
/// it sees, which is how `"doc_values": false` came to be silently ignored.
///
/// This is the single largest artifact on text-heavy corpora: on the 500k-doc
/// rc.12 benchmark the one analyzed `text` field is 95.87% of the `.dv` side-car
/// and 35.6% of the whole index. It is much smaller where `_source` dominates
/// (6.97% across the `xc-*` code corpora), so the saving is corpus-dependent and
/// must always be quoted as a range.
fn build_doc_value_columns<V: std::borrow::Borrow<Value>>(
    sources: impl Iterator<Item = Option<V>>,
    skip: &std::collections::HashSet<String>,
) -> std::collections::BTreeMap<String, xerj_storage::doc_values::Column> {
    use std::collections::BTreeMap;
    use xerj_storage::doc_values::{Column, KeywordColumn, NumericColumn, PresenceColumn};

    // Collect per-field per-doc raw values.  We materialise into vectors
    // so we can decide column-type once we've seen all values.  This is
    // O(docs × fields) memory but much smaller than the segment itself.
    let mut numeric: BTreeMap<String, Vec<Option<i64>>> = BTreeMap::new();
    let mut keyword: BTreeMap<String, Vec<Option<String>>> = BTreeMap::new();
    // `doc_values: false` fields (text, semantic_text) get a presence
    // bitmap instead of a value column. Pre-seed every skipped name so a
    // segment where the field is absent still has a column: `exists` then
    // answers "no row" without parsing source, and a missing column stays
    // reserved for segments written before this bitmap existed.
    //
    // Only top-level names. The loop below sees `_source`'s top-level keys,
    // so a dotted mapping name (`user.bio`, an object sub-field) never gets a
    // bit set; seeding it would ship an all-absent bitmap and `exists` would
    // answer "no row" for documents that have the field. Those fields get
    // no column and keep the source scan.
    let mut presence: BTreeMap<String, PresenceColumn> = skip
        .iter()
        .filter(|name| !name.contains('.'))
        .map(|name| (name.clone(), PresenceColumn::empty()))
        .collect();
    // Fields that carry an ARRAY value in ANY doc of this segment.  The
    // one-slot-per-row column cannot represent a multi-valued doc, and
    // filing it as null makes the column LIE: every consumer (count
    // shortcut, prefilters, fast aggs) treats a PRESENT column as exact,
    // so a range that should match `[5, 105]` silently drops the doc —
    // live-verified: bool(term + range-on-multi-valued) at size:0 counted
    // 27 of 37 whenever the flush landed all docs in one segment (the
    // 2-core CI shape; ≥32-core boxes scatter docs across shards, the
    // array-only segments then have no column and the shortcut abandons
    // to the correct brute scan).  A poisoned field therefore ships NO
    // column at all — consumers take the same abandon-to-scan path they
    // already take for a field that is absent from the segment.
    let mut multi_valued: std::collections::HashSet<String> = std::collections::HashSet::new();

    let mut total_docs: usize = 0;
    for src in sources {
        let doc_idx = total_docs;
        total_docs += 1;
        let Some(obj) = src
            .as_ref()
            .and_then(|v| <V as std::borrow::Borrow<Value>>::borrow(v).as_object())
        else {
            continue;
        };
        for (field, val) in obj {
            // Skip the `_id`, `_seq_no`, `_source` envelope keys — they're
            // bookkeeping, not user data.
            if field.starts_with('_') {
                continue;
            }
            // Honour the declared mapping. A skipped field records presence
            // only — one bit, not the value — so `exists` does not need the
            // stored JSON. Checked before any value allocation.
            if skip.contains(field.as_str()) {
                if value_present(val) {
                    if let Some(bits) = presence.get_mut(field.as_str()) {
                        bits.insert(doc_idx as u32);
                    }
                }
                continue;
            }
            // Lookup-first (`get_mut` before `entry`) so the common case
            // (field already has a column) skips the per-doc-field
            // `field.clone()` String allocation `entry()` would force —
            // ~370k allocs per 31k-doc flush segment on a 12-field corpus.
            match val {
                Value::Number(n) => {
                    // Always store as f64 bit-pattern.  The agg reader uses
                    // `f64::from_bits(v as u64)` to recover the value, which
                    // is lossless for integers up to 2^53 and exact for
                    // doubles.  Mixing i64 and f64 storage in the same column
                    // is undefined-behaviour because we have no per-column
                    // kind flag yet, so commit to one representation.
                    let Some(f) = n.as_f64() else { continue };
                    let v = f.to_bits() as i64;
                    if !numeric.contains_key(field) {
                        numeric.insert(field.clone(), Vec::new());
                    }
                    let col = numeric.get_mut(field).expect("just inserted");
                    pad_with_none(col, doc_idx);
                    col.push(Some(v));
                }
                Value::String(s) => {
                    // A packed embedding is not a keyword term. Filing it
                    // would put one multi-kilobyte dictionary entry per
                    // document into the `.dv` sidecar (#1940). Absence of a
                    // column is the same outcome the number-array form
                    // already had: arrays are multi-valued and ship no column.
                    if xerj_common::packed_f32::is_packed_f32(s) {
                        continue;
                    }
                    if !keyword.contains_key(field) {
                        keyword.insert(field.clone(), Vec::new());
                    }
                    let col = keyword.get_mut(field).expect("just inserted");
                    pad_with_none(col, doc_idx);
                    col.push(Some(s.clone()));
                }
                Value::Bool(b) => {
                    if !numeric.contains_key(field) {
                        numeric.insert(field.clone(), Vec::new());
                    }
                    let col = numeric.get_mut(field).expect("just inserted");
                    pad_with_none(col, doc_idx);
                    let v = (if *b { 1.0_f64 } else { 0.0_f64 }).to_bits() as i64;
                    col.push(Some(v));
                }
                Value::Array(_) if !multi_valued.contains(field.as_str()) => {
                    multi_valued.insert(field.clone());
                }
                _ => {}
            }
        }
    }

    // Drop every column whose field was multi-valued anywhere in the
    // segment (see `multi_valued` above) — no column beats a lying one.
    for f in &multi_valued {
        numeric.remove(f);
        keyword.remove(f);
    }

    // Same rule for a field that arrived TYPE-mixed inside one segment — some
    // docs numeric/boolean, others a string. Each kind was collected into its
    // own map, and only one column can carry the name: the `keyword` loop below
    // runs second and would overwrite the numeric column, leaving every
    // number/boolean doc filed as NULL in a column consumers trust as exact.
    // `build_term_prefilter_cached` then returns a set that is not a superset
    // and the scan never sees the dropped docs — a confident wrong count, the
    // same failure shape the multi-valued poisoning above exists to prevent.
    //
    // This is exactly what #781's ingest coercion makes reachable: an index
    // written across that upgrade holds `"true"` in one doc and `true` in the
    // next, and a flush that lands both in ONE segment (the 2-core CI shape;
    // a many-core box scatters them and each segment stays homogeneous) built
    // the lying column. Ship no column instead; consumers take the
    // abandon-to-scan path they already take for an absent field.
    let mixed_type: Vec<String> = numeric
        .keys()
        .filter(|f| keyword.contains_key(*f))
        .cloned()
        .collect();
    for f in &mixed_type {
        numeric.remove(f);
        keyword.remove(f);
    }

    // Pad every column to total_docs so position == doc_id.
    for col in numeric.values_mut() {
        pad_with_none(col, total_docs);
    }
    for col in keyword.values_mut() {
        pad_with_none(col, total_docs);
    }

    let mut out: BTreeMap<String, Column> = BTreeMap::new();
    for (name, col) in numeric {
        out.insert(name, Column::Numeric(NumericColumn::from_iter(col)));
    }
    for (name, col) in keyword {
        match KeywordColumn::from_iter(col) {
            Ok(k) => {
                out.insert(name, Column::Keyword(k));
            }
            Err(e) => {
                tracing::warn!("doc-values keyword build failed for one field: {e}");
            }
        }
    }
    for (name, mut present) in presence {
        present.set_doc_count(total_docs as u32);
        out.insert(name, Column::Presence(present));
    }
    out
}

fn pad_with_none<T>(v: &mut Vec<Option<T>>, target_len: usize) {
    while v.len() < target_len {
        v.push(None);
    }
}

/// Encode columns to bytes and write them to `{segment_id}.dv`.
///
/// RC4 W1 #10 — durable write (tmp + fsync + rename + dir fsync): the
/// `.dv` side-car is part of the segment publish chain whose WAL entries
/// are pruned ~1 s after the flush; a plain `fs::write` left it in the
/// volatile page cache, so a power loss after the prune produced a
/// segment whose doc-values had evaporated.
fn write_doc_values_sidecar(
    segments_dir: &std::path::Path,
    segment_id: &str,
    columns: &std::collections::BTreeMap<String, xerj_storage::doc_values::Column>,
) -> std::io::Result<()> {
    write_doc_values_sidecar_at_level(
        segments_dir,
        segment_id,
        columns,
        xerj_storage::doc_values::DV_ZSTD_LEVEL,
    )
}

/// [`write_doc_values_sidecar`] at a caller-chosen zstd level — the merge
/// path's entry point for the operator's `compression.level` (#318). The
/// flush path keeps the pinned level; see `DV_ZSTD_LEVEL`.
fn write_doc_values_sidecar_at_level(
    segments_dir: &std::path::Path,
    segment_id: &str,
    columns: &std::collections::BTreeMap<String, xerj_storage::doc_values::Column>,
    level: i32,
) -> std::io::Result<()> {
    let path = segments_dir.join(format!("{segment_id}.dv"));
    let bytes = xerj_storage::doc_values::encode_columns_at_level(columns, level);
    xerj_common::fsio::write_file_durable(&path, &bytes)
}

/// Load `{segment_id}.dv`, returning an empty map if the file doesn't
/// exist (older segments don't have doc-values yet).
fn read_doc_values_sidecar(
    segments_dir: &std::path::Path,
    segment_id: &str,
) -> std::collections::BTreeMap<String, xerj_storage::doc_values::Column> {
    use std::collections::BTreeMap;
    let path = segments_dir.join(format!("{segment_id}.dv"));
    let Ok(bytes) = std::fs::read(&path) else {
        return BTreeMap::new();
    };
    xerj_storage::doc_values::decode_columns(&bytes).unwrap_or_default()
}

/// Build a per-field FTS analyzer config map from a schema.
///
/// This is the bridge between the user's mapping (keyword / integer /
/// date / text) and the analyzer the FTS writer applies to each field's
/// tokens at flush + merge time.  The G4 short-circuit count path
/// depends on this: if a keyword field is indexed with the standard
/// analyzer it gets stop-worded ("GET"/"PUT"/"DELETE" all dropped) and
/// the FST has no entry for the literal value, so `term_doc_freq` falls
/// through to the slow stored-doc scan.
///
/// `text_analyzer` is the analyzer for `Text` fields — `default` when the
/// index settings declare one AND this index's segments honour it, else
/// `standard` (see [`Index::segment_text_analyzer`], #937). The memtable
/// has always resolved `get_analyzer("default").or_else(standard)`
/// (`memtable.rs`), so before #937 an index with a declared default
/// analysed documents one way until `_flush` and another way after it.
///
/// Mapping rules (matches Lucene's behaviour):
/// - `Text` → `text_analyzer` (`standard`, or the declared `default`)
/// - `Keyword`, `Long`, `Integer` (alias), `Double`, `Float`, `Date`,
///   `Boolean`, `Ip` → `keyword` analyzer (whole input as one token, no
///   stop-words)
/// - Any unknown / unmapped field defaults to the registry's `default`
///   (else `standard`) in the writer itself — see
///   `FtsIndexWriter::unconfigured_field_config` — because the memtable
///   insert path passes every source field through and we must not
///   stop-word user data unexpectedly.
fn build_fts_field_configs(
    schema: &Schema,
    text_analyzer: &str,
) -> HashMap<String, xerj_fts::index::FieldIndexConfig> {
    use xerj_fts::index::FieldIndexConfig;
    let mut out = HashMap::new();
    let excluded = crate::memtable::fts_excluded_fields(schema);
    for f in &schema.fields {
        if excluded.contains(&f.name) {
            continue;
        }
        let analyzer = match f.field_type {
            FieldType::Text => text_analyzer,
            // Everything else is exact-match.  We use the registered
            // "keyword" analyzer (KeywordTokenizer) which emits the input
            // string as a single token.
            _ => "keyword",
        };
        out.insert(
            f.name.clone(),
            FieldIndexConfig {
                analyzer: analyzer.to_string(),
                store_positions: matches!(f.field_type, FieldType::Text),
                store_term_vectors: false,
            },
        );
    }
    out
}

/// Log `error` and remove this segment's FTS artifacts.
///
/// `Ok` means nothing FTS-shaped remains, so publishing the stored segment
/// is safe: a query that finds no side-cars scans the stored section, and a
/// later merge rebuilds full text (#2349). `Err` means a leftover file could
/// not be removed; that partial family must not be published. The error
/// string keeps the original publish failure (path and OS error) and the
/// cleanup failure.
fn degrade_fts_publish(segment_dir: &Path, segment_id: &str, error: &str) -> std::io::Result<()> {
    tracing::error!(
        segment_id,
        "FTS side-car publish failed; this segment stays searchable by stored scan until a merge rebuilds full text: {error}"
    );
    if let Err(cleanup) = xerj_fts::index::discard_segment_fts_files(segment_dir, segment_id) {
        return Err(std::io::Error::other(format!(
            "FTS side-car publish failed ({error}); leftover side-cars could not be removed: {cleanup}"
        )));
    }
    Ok(())
}

/// Open a full FTS reader over every input segment of a merge batch, or
/// `None` when this batch has to fall back to re-analysing its documents.
///
/// #876. A merge's output postings ARE its inputs' postings with the doc ids
/// remapped — nothing about them depends on the source text — so the merge
/// should read `.fst`/`.post`/`.meta`/`.norms` rather than re-run the
/// analyzer chain over every surviving document. This is the gate on that
/// path. It says no, and accepts the slow rebuild, whenever the replay could
/// not be proved equivalent:
///
/// * a side-car filename component that is a SHA-256 digest of a field name
///   nobody in the mapping owns — silently omitting the field would drop its
///   postings and stop its terms matching;
/// * an input whose side-cars will not open;
/// * an input that carries documents but has no FTS data to merge (its
///   postings are not on disk, so the only way to give the output an index is
///   to build one);
/// * a field stored with a different position setting than this merge would
///   write for it — a re-encode, not a merge;
/// * a field whose postings were written with a different ANALYZER than this
///   merge would use (#937) — the term spaces differ, so only a re-analysis
///   can produce the output the mapping now calls for.
///
/// The returned readers hold each input's decompressed postings for the rest
/// of the batch. That is a real allocation, but it replaces `fts_input`'s
/// per-document `FieldValues` — a second copy of every indexed field's TEXT —
/// so the batch's peak working set falls rather than rises.
fn fts_merge_readers(
    segments_dir: &std::path::Path,
    metas: &[xerj_storage::segment::SegmentMeta],
    field_configs: &HashMap<String, xerj_fts::index::FieldIndexConfig>,
    excluded: &std::collections::HashSet<String>,
    mapped_field_names: &[String],
    text_analyzer: &str,
) -> Option<Vec<xerj_fts::index::FtsIndexReader>> {
    let default_store_positions = xerj_fts::index::FieldIndexConfig::default().store_positions;
    // ONE directory scan for the whole batch: a converging index keeps tens of
    // thousands of side-car files here, and this runs per merge batch.
    let segment_ids: Vec<&str> = metas.iter().map(|meta| meta.id.as_str()).collect();
    let per_segment_fields = match xerj_fts::index::segments_indexed_field_names(
        segments_dir,
        &segment_ids,
        mapped_field_names,
    ) {
        Ok(names) => names,
        Err(error) => {
            tracing::info!("merge: cannot enumerate FTS fields, re-analysing this batch: {error}");
            return None;
        }
    };
    let mut readers = Vec::with_capacity(metas.len());
    for (meta, names) in metas.iter().zip(per_segment_fields) {
        // An excluded field (a `dense_vector`, say) must not be resurrected
        // from an older segment that predates the exclusion — the rebuild
        // would not have written it either.
        let names: Vec<String> = names
            .into_iter()
            .filter(|name| !excluded.contains(name))
            .collect();
        if names.is_empty() && meta.doc_count > 0 {
            tracing::info!(
                segment = %meta.id,
                doc_count = meta.doc_count,
                "merge: input segment has documents but no FTS side-cars, re-analysing \
                 this batch"
            );
            return None;
        }
        let refs: Vec<&str> = names.iter().map(|name| name.as_str()).collect();
        let reader =
            match xerj_fts::index::FtsIndexReader::open(segments_dir, meta.id.as_str(), &refs) {
                Ok(reader) => reader,
                Err(error) => {
                    tracing::info!(
                        segment = %meta.id,
                        "merge: cannot open FTS side-cars, re-analysing this batch: {error}"
                    );
                    return None;
                }
            };
        // #937 — the analyzer equality gate. Replay copies input postings
        // verbatim, so an input whose TEXT postings were produced by a
        // DIFFERENT analyzer than this merge would write can only be merged
        // by re-analysing it: the term spaces differ. A pre-#937 segment has
        // no `{id}.ftsan` marker and reports `standard`, which is exactly
        // what a build that never read the declared default wrote.
        let recorded_analyzers =
            xerj_fts::index::segment_recorded_analyzers(segments_dir, meta.id.as_str());
        let analyzer_mismatch = reader.indexed_fields().iter().find_map(|field| {
            let expected = match field_configs.get(*field) {
                Some(config) => config.analyzer.as_str(),
                // A field the mapping no longer knows was written by the
                // flush writer's own fallback (see
                // `FtsIndexWriter::unconfigured_field_config`), which resolves
                // exactly `text_analyzer`.
                None => text_analyzer,
            };
            if expected == "keyword" {
                // Keyword postings predate #937 unchanged — nothing to
                // compare against.
                return None;
            }
            let recorded = recorded_analyzers
                .as_ref()
                .and_then(|map| map.get(*field).map(String::as_str))
                .unwrap_or("standard");
            (recorded != expected).then(|| field.to_string())
        });
        if let Some(field) = analyzer_mismatch {
            tracing::info!(
                segment = %meta.id,
                field,
                "merge: field's postings were written with a different analyzer than this \
                 merge would use, re-analysing this batch"
            );
            return None;
        }
        let mismatch = reader
            .indexed_fields()
            .into_iter()
            .find(|field| {
                let expected = field_configs
                    .get(*field)
                    .map(|config| config.store_positions)
                    .unwrap_or(default_store_positions);
                reader.field_has_positions(field) != expected
            })
            .map(|field| field.to_owned());
        if let Some(field) = mismatch {
            tracing::info!(
                segment = %meta.id,
                field,
                "merge: field is stored with a different position setting than this merge \
                 would write, re-analysing this batch"
            );
            return None;
        }
        readers.push(reader);
    }
    Some(readers)
}

/// FTS input extraction for the MERGE path.
///
/// Delegates to the flush path's own walker
/// (`crate::memtable::extract_field_values_excluding`) rather than mirroring
/// it. Until #332 this file carried a private copy (`extract_field_text` +
/// `extract_fts_fields_excluding`) that had to be kept in sync by hand with
/// `memtable::extract_text_value`; both copies flattened a JSON array with
/// `join(" ")`, and a merged segment reproduced the bug even after a flushed
/// one stopped having it. One walker, one behaviour.
///
/// The shared walker also carries #328's nested-exclusion pruning: an
/// object-valued field with an excluded descendant (a `dense_vector` at
/// `passages.vec`) is flattened from a PRUNED copy, so the merge does not
/// resurrect postings the flush path skipped. That pruning used to live inline
/// here; it now lives once, in `extract_field_values_excluding`, so both the
/// flush and the merge path get it.
fn extract_fts_fields_excluding(
    source: &Value,
    excluded: &std::collections::HashSet<String>,
) -> HashMap<String, xerj_fts::index::FieldValues> {
    crate::memtable::extract_field_values_excluding(source, excluded)
}

// ── Short-circuit count helper ───────────────────────────────────────────────

impl Index {
    /// Compute the total hit count for a query without touching a single
    /// stored document, if the query shape allows it.  Returns `Some(total)`
    /// on success, `None` if the query needs a full scan.
    ///
    /// Ported from ES's
    /// `QueryPhaseCollectorManager.shortcutTotalHitCount` — the same method
    /// that makes `{"size":0, "query":{"term":{...}}}` return in ≤ 3 ms on
    /// 66 M-doc indices.
    ///
    /// Supported shapes:
    /// * `MatchAll` — sum of segment `doc_count` + memtable doc count.
    /// * `Term { field, value }` — for a field with doc-values:
    ///     - Counts matches in the memtable via `doc_values_keyword_column`.
    ///     - For each on-disk segment, counts through that segment's
    ///       doc-values column — the same values `_search` compares against.
    ///     - If a segment has no column for the field, the shortcut is
    ///       abandoned (return `None`) and the scan answers.  It used to
    ///       consult the FTS term dictionary instead, whose ANALYZED terms
    ///       are not what `_search` matches a `term` against, so the count
    ///       could exceed the retrievable hit set (#362).
    ///
    /// Exact match count for a `bool` that carries `should` and/or `must_not`
    /// clauses — the shapes the fused must/filter-intersection arm bails on.
    /// Resolves every leaf clause to its doc-values position set per segment
    /// and combines them with set algebra:
    ///   required = ∩(must, filter);  should = positions in ≥k should sets;
    ///   result   = (required ∩ should) − ∪(must_not).
    /// Only Term/Terms/Range leaves are resolvable; anything else → `None`
    /// (caller keeps the counting scan).  Conservative guards make a
    /// delete-blind / memtable-blind count impossible to mistake for
    /// authoritative: bails on any ghost (overwrite/tombstone) event and on a
    /// non-empty memtable.  `minimum_should_match` percentages/field/script →
    /// `None`.
    fn bool_should_mustnot_count(
        &self,
        must: &[QueryNode],
        should: &[QueryNode],
        must_not: &[QueryNode],
        filter: &[QueryNode],
        minimum_should_match: &Option<xerj_query::ast::MinShouldMatch>,
        snap: &xerj_storage::index_store::IndexSnapshot,
    ) -> Option<u64> {
        // Delete/memtable blindness guards — an authoritative count must be
        // exact against live docs, and these sets only see flushed physical
        // segment docs.
        if self.store.version_map.ghost_events() > 0 {
            return None;
        }
        if self.memtable.doc_count() > 0 {
            return None;
        }

        // Effective minimum_should_match required-count.
        let k: u32 = if should.is_empty() {
            0
        } else {
            let default = if must.is_empty() && filter.is_empty() {
                1
            } else {
                0
            };
            match minimum_should_match {
                None => default,
                Some(xerj_query::ast::MinShouldMatch::Fixed(n)) => *n,
                // Percentage / per-doc field / script — not resolvable here.
                Some(_) => return None,
            }
        };
        // `should` only filters when at least one clause is required (k >= 1).
        let should_active = !should.is_empty() && k >= 1;

        let resolve = |cols: &std::collections::BTreeMap<
            String,
            xerj_storage::doc_values::Column,
        >,
                       clause: &QueryNode|
         -> Option<HashSet<u32>> {
            let clause = match clause {
                QueryNode::Constant { query, .. } | QueryNode::Boosted { query, .. } => {
                    query.as_ref()
                }
                _ => clause,
            };
            match clause {
                QueryNode::Term { field, value, .. } => {
                    seg_term_positions(cols, field, std::slice::from_ref(value))
                }
                QueryNode::Terms { field, values, .. } => seg_term_positions(cols, field, values),
                QueryNode::Range {
                    field,
                    gte,
                    gt,
                    lte,
                    lt,
                    ..
                } => seg_range_positions(
                    cols,
                    field,
                    gte.as_ref(),
                    gt.as_ref(),
                    lte.as_ref(),
                    lt.as_ref(),
                ),
                _ => None,
            }
        };

        let segments_dir = self.data_dir.join("segments");
        // Per-(segment, shape) count cache so the warm/repeat query doesn't
        // rebuild the position sets each call (the whole-result cache may be
        // off).  Segments are immutable → the cached seg count never staleness.
        let cache_key: Option<String> =
            serde_json::to_string(&(must, should, must_not, filter, k)).ok();
        let mut total: u64 = 0;
        for meta in &snap.segments {
            if meta.doc_count == 0 {
                continue;
            }
            if let Some(ck) = &cache_key {
                if let Some(hit) = self
                    .shortcut_count_cache
                    .get(&(meta.id.to_string(), ck.clone()))
                {
                    total = total.saturating_add(*hit.value());
                    continue;
                }
            }
            let cols = self.dv_columns_for(&segments_dir, &meta.id)?;

            // Required conjunction: intersection of must + filter sets.
            let required: Option<HashSet<u32>> = if must.is_empty() && filter.is_empty() {
                None
            } else {
                let mut sets: Vec<HashSet<u32>> = Vec::new();
                for c in must.iter().chain(filter.iter()) {
                    sets.push(resolve(&cols, c)?);
                }
                sets.sort_by_key(|s| s.len());
                let mut it = sets.into_iter();
                let mut acc = it.next().unwrap_or_default();
                for s in it {
                    acc.retain(|p| s.contains(p));
                    if acc.is_empty() {
                        break;
                    }
                }
                Some(acc)
            };

            // must_not union.
            let mut mnot: HashSet<u32> = HashSet::new();
            for c in must_not {
                mnot.extend(resolve(&cols, c)?);
            }

            let seg_count: u64 = if should_active {
                // Positions matching >= k of the should sets, then filtered by
                // the required set and the must_not exclusion.
                let mut hits: std::collections::HashMap<u32, u32> =
                    std::collections::HashMap::new();
                for c in should {
                    for p in resolve(&cols, c)? {
                        *hits.entry(p).or_insert(0) += 1;
                    }
                }
                let mut cnt: u64 = 0;
                for (p, h) in hits.iter() {
                    if *h < k {
                        continue;
                    }
                    if let Some(req) = &required {
                        if !req.contains(p) {
                            continue;
                        }
                    }
                    if mnot.contains(p) {
                        continue;
                    }
                    cnt += 1;
                }
                cnt
            } else if let Some(req) = &required {
                req.iter().filter(|p| !mnot.contains(p)).count() as u64
            } else {
                // No required, no active should → all docs minus must_not.
                (meta.doc_count).saturating_sub(mnot.len() as u64)
            };
            if let Some(ck) = &cache_key {
                if self.shortcut_count_cache.len() >= SHORTCUT_COUNT_CACHE_MAX {
                    self.shortcut_count_cache.clear();
                }
                self.shortcut_count_cache
                    .insert((meta.id.to_string(), ck.clone()), seg_count);
            }
            total = total.saturating_add(seg_count);
        }
        Some(total)
    }

    /// `mem_matches_known` (mixed-RUW Fix 1): the exact memtable match
    /// total already computed by `search_inner`'s fused DV walk for THIS
    /// query — `Some` if and only if that walk executed (see the capture
    /// sites in the mem-snapshot block).  Consumed ONLY by the
    /// bool-conjunction arm below to skip its duplicate
    /// `doc_values_bool_query` recount; every other arm (Term count-maps,
    /// Range per-value walk, match_all live count, Regexp) keeps its own
    /// memtable authority — the Range arm in particular lowers bounds
    /// differently (date-string bounds via `parse_date_ms`, per-VALUE
    /// iteration, distinct abandon semantics) and MUST NOT be substituted.
    async fn try_shortcut_count(
        &self,
        query: &QueryNode,
        snap: &xerj_storage::index_store::IndexSnapshot,
        is_match_all: bool,
        mem_matches_known: Option<u64>,
        schema: &Schema,
    ) -> Option<u64> {
        // Unwrap wrapper queries so constant_score and boosted
        // queries benefit from the same fast paths.
        let query = match query {
            QueryNode::Constant { query, .. } | QueryNode::Boosted { query, .. } => query.as_ref(),
            _ => query,
        };
        // Analyzed-text leaves first: every count below is built from
        // doc-values columns, and those are exact only where the column holds
        // what `_search` matches. For a `text` field with doc-values the
        // column holds RAW values while the scan matches TOKENS, so any count
        // derived from it (the Term/Terms arms and the Bool arm's resolver)
        // would drop exactly the token-only matches the pre-flush answer has.
        // Decline the whole shortcut and let the counting scan answer — the
        // same `None` route a field with no column already takes.
        if has_analyzed_text_term_leaf(query, schema) {
            return None;
        }
        // Bool intersection shortcut — for `bool { must: [Term, Range] }`
        // (the most common production filter shape) compute the matching
        // doc-id set per segment via doc-values intersection, no scan.
        // Counted via the same `dv_columns_for` cache as the other paths.
        if let QueryNode::Bool {
            must,
            should,
            must_not,
            filter,
            minimum_should_match,
        } = query
        {
            // `should`/`must_not` shapes: resolve via per-segment doc-values
            // set algebra (the fused must/filter anchor-walk below only does
            // pure conjunctions).  `None` from the helper (unresolvable leaf /
            // ghost / non-empty memtable) falls through to the scan.
            if !should.is_empty() || !must_not.is_empty() {
                return self.bool_should_mustnot_count(
                    must,
                    should,
                    must_not,
                    filter,
                    minimum_should_match,
                    snap,
                );
            }
            // Combine must + filter — both behave identically for counting.
            let mut all_must: Vec<&QueryNode> = must.iter().collect();
            for f in filter {
                all_must.push(f);
            }
            // Shape gate SHARED with the `count_only` memtable-skip in
            // `search_inner` (b7 DEFECT 1a) — the two sites must never
            // drift: non-empty conjunction of plain Term/Range children
            // only; anything else abandons to the scan.
            if !memtable_count_covered_by_shortcut(query) {
                return None;
            }

            let segments_dir = self.data_dir.join("segments");
            let mut seg_matches: u64 = 0;
            // Canonical query key for the per-segment count cache.
            let bool_cache_key: Option<String> = serde_json::to_string(query).ok();
            for meta in &snap.segments {
                if meta.doc_count == 0 {
                    continue;
                }
                if let Some(k) = &bool_cache_key {
                    if let Some(hit) = self.shortcut_count_cache.get(&(meta.id.clone(), k.clone()))
                    {
                        seg_matches = seg_matches.saturating_add(*hit.value());
                        continue;
                    }
                }
                let cols = self.dv_columns_for(&segments_dir, &meta.id)?;
                // Resolve every predicate to a closure ONCE, then run a
                // single fused walk over the segment's doc range applying
                // every predicate per doc.  Zero allocations in the inner
                // loop.
                // `bool` flag = null bitmap is empty (skip null check).
                enum SegPred<'a> {
                    Keyword(&'a xerj_storage::doc_values::KeywordColumn, u32, bool),
                    Numeric(
                        &'a xerj_storage::doc_values::NumericColumn,
                        f64,
                        bool,
                        f64,
                        bool,
                        bool,
                    ),
                }
                let mut preds: Vec<SegPred<'_>> = Vec::with_capacity(all_must.len());
                let mut abandoned = false;
                let mut empty_pred = false;
                for child in &all_must {
                    match child {
                        QueryNode::Term { field, value, .. } => match cols.get(field.as_str()) {
                            Some(xerj_storage::doc_values::Column::Keyword(k)) => {
                                let term = match value {
                                    Value::String(s) => {
                                        // A CIDR value expands to a subnet in the
                                        // source scan (`ip_matches_cidr`); it is
                                        // never a dictionary literal. Abandon this
                                        // fused count (→ full scan) instead of
                                        // treating the whole subnet as an empty
                                        // predicate, which counted 0 after flush
                                        // (#786).
                                        if s.contains('/') {
                                            abandoned = true;
                                            break;
                                        }
                                        s.clone()
                                    }
                                    other => other.to_string(),
                                };
                                match k.ord_for_term(&term) {
                                    Some(ord) => preds.push(SegPred::Keyword(
                                        k,
                                        ord,
                                        k.null_bitmap.is_empty(),
                                    )),
                                    None => {
                                        empty_pred = true;
                                        break;
                                    }
                                }
                            }
                            Some(xerj_storage::doc_values::Column::Numeric(n)) => {
                                let Some(tgt) = value.as_f64() else {
                                    abandoned = true;
                                    break;
                                };
                                preds.push(SegPred::Numeric(
                                    n,
                                    tgt,
                                    true,
                                    tgt,
                                    true,
                                    n.null_bitmap.is_empty(),
                                ));
                            }
                            // Presence answers `exists`, not term equality.
                            Some(xerj_storage::doc_values::Column::Presence(_)) | None => {
                                abandoned = true;
                                break;
                            }
                        },
                        QueryNode::Range {
                            field,
                            gte,
                            gt,
                            lte,
                            lt,
                            ..
                        } => {
                            let to_f64 = |v: &Option<Value>| -> Option<f64> {
                                v.as_ref().and_then(|x| x.as_f64())
                            };
                            let (lo, lo_incl) = match (to_f64(gte), to_f64(gt)) {
                                (Some(v), _) => (v, true),
                                (None, Some(v)) => (v, false),
                                (None, None) => (f64::NEG_INFINITY, true),
                            };
                            let (hi, hi_incl) = match (to_f64(lte), to_f64(lt)) {
                                (Some(v), _) => (v, true),
                                (None, Some(v)) => (v, false),
                                (None, None) => (f64::INFINITY, true),
                            };
                            let Some(xerj_storage::doc_values::Column::Numeric(n)) =
                                cols.get(field.as_str())
                            else {
                                abandoned = true;
                                break;
                            };
                            preds.push(SegPred::Numeric(
                                n,
                                lo,
                                lo_incl,
                                hi,
                                hi_incl,
                                n.null_bitmap.is_empty(),
                            ));
                        }
                        // Anything other than Term or Range is filtered out
                        // upstream. If a new QueryNode variant ever slips
                        // through, fall back to the slow path instead of
                        // panicking on a search request.
                        _ => {
                            abandoned = true;
                            break;
                        }
                    }
                }
                if abandoned {
                    return None;
                }
                if empty_pred {
                    // One predicate matches nothing in this segment →
                    // intersection is empty → contribute 0 hits.
                    continue;
                }

                // Anchor on the smallest-cardinality predicate so the
                // intersection visits ~min(matches) docs instead of all
                // doc_count.  For nginx `bool { GET, 4xx }`, this drops
                // ~300k iterations → ~1.6k per segment (the 4xx range).
                let n_docs = meta.doc_count as u32;

                // Estimate cardinality for each predicate to pick the
                // anchor.  Cheap: keyword uses per_ord_count, numeric
                // uses range_count via the sorted index bisect.
                let card = |p: &SegPred<'_>| -> u32 {
                    match p {
                        SegPred::Keyword(k, ord, _) => {
                            k.per_ord_count.get(*ord as usize).copied().unwrap_or(0)
                        }
                        SegPred::Numeric(n, lo, lo_incl, hi, hi_incl, _) => {
                            n.range_count(*lo, *hi, *lo_incl, *hi_incl) as u32
                        }
                    }
                };
                let anchor_idx = (0..preds.len())
                    .min_by_key(|i| card(&preds[*i]))
                    .unwrap_or(0);
                let anchor_doc_ids: Vec<u32> = match &preds[anchor_idx] {
                    SegPred::Keyword(k, ord, _) => {
                        // Walk ords once to collect matching positions.
                        let mut v = Vec::with_capacity(card(&preds[anchor_idx]) as usize);
                        for (i, &o) in k.ords.iter().enumerate() {
                            if o == *ord && !k.null_bitmap.contains(i as u32) {
                                v.push(i as u32);
                            }
                        }
                        v
                    }
                    SegPred::Numeric(n, lo, lo_incl, hi, hi_incl, _) => {
                        n.range_doc_ids(*lo, *hi, *lo_incl, *hi_incl)
                    }
                };

                let mut sc: u64 = 0;
                'doc: for &i in &anchor_doc_ids {
                    for (idx, p) in preds.iter().enumerate() {
                        if idx == anchor_idx {
                            continue;
                        }
                        let ok = match p {
                            SegPred::Keyword(k, target_ord, no_nulls) => {
                                if !*no_nulls && k.null_bitmap.contains(i) {
                                    false
                                } else {
                                    k.ords[i as usize] == *target_ord
                                }
                            }
                            SegPred::Numeric(n, lo, lo_incl, hi, hi_incl, no_nulls) => {
                                if !*no_nulls && n.null_bitmap.contains(i) {
                                    false
                                } else {
                                    let v = f64::from_bits(n.data[i as usize] as u64);
                                    let pl = if *lo_incl { v >= *lo } else { v > *lo };
                                    let pu = if *hi_incl { v <= *hi } else { v < *hi };
                                    pl && pu
                                }
                            }
                        };
                        if !ok {
                            continue 'doc;
                        }
                    }
                    sc += 1;
                }
                let _ = n_docs; // silence unused
                if let Some(k) = &bool_cache_key {
                    if self.shortcut_count_cache.len() >= SHORTCUT_COUNT_CACHE_MAX {
                        self.shortcut_count_cache.clear();
                    }
                    self.shortcut_count_cache
                        .insert((meta.id.clone(), k.clone()), sc);
                }
                seg_matches = seg_matches.saturating_add(sc);
            }

            // Memtable side — fused columnar walk (one position pass per
            // shard, count-only) via the same predicate lowering the
            // memtable hit path uses.  The old fallback DEEP-CLONED the
            // entire memtable per query (`all_docs_with_sources`) and ran
            // a `doc_matches_query` JSON descent per buffered doc — under
            // a sustained bulk writer that alone was 1-6 s per bool query
            // (the read-under-write bool collapse, WARN mem_admit term).
            // When the columns can't serve the predicates we keep the
            // per-doc scan but share sources via Arc instead of cloning.
            //
            // Fix 1 (mixed-RUW): when `search_inner`'s fused DV arm already
            // walked the memtable for this query (size>0, no sort/aggs),
            // reuse ITS exact total instead of walking a second time —
            // that duplicate recount was ~6-8 ms of the bool p99 at a deep
            // memtable, and reusing the snapshot-time total also makes
            // `hits` and `hits.total` come from ONE point-in-time walk.
            // `mem_matches_known` is `Some` ONLY when that walk executed
            // (capture-site invariant); on the size:0/count paths it is
            // `None` and this recount stays the sole memtable authority.
            let mem_matches: u64 = if let Some(known) = mem_matches_known {
                known
            } else if self.memtable.doc_count() == 0 {
                0
            } else if let Some((_, total)) = mem_bool_preds(query)
                .and_then(|preds| self.memtable.doc_values_bool_query(&preds, 0))
            {
                total
            } else {
                let docs = self.memtable.all_docs_with_sources_arc();
                docs.iter()
                    .filter(|(_, src)| doc_matches_query_typed(query, src, schema))
                    .count() as u64
            };

            return Some(seg_matches + mem_matches);
        }

        if is_match_all {
            // Live doc count from the version map (one non-deleted entry per
            // `_id`). The `doc_count` atomic doubles as the version generator
            // and is bumped on every write, so an UPDATE would inflate `_count`
            // by 1 per update — the version map is the authoritative source and
            // is stable across in-flight flushes (a flush re-points an `_id` to
            // its new segment without changing which ids are live).
            return Some(self.live_doc_count());
        }

        // Range query shortcut (M2 G4-ext): walk segment `.dv` sorted
        // indices in O(log n) per segment, plus the memtable numeric
        // column linearly.  Any segment without a dv sidecar or without
        // the field causes the shortcut to be abandoned — we must not
        // undercount.
        if let QueryNode::Range {
            field,
            gte,
            gt,
            lte,
            lt,
            ..
        } = query
        {
            // Accept date-shaped string bounds by resolving them via
            // `parse_date_ms` so a range on an ISO-8601 date field
            // doesn't abandon to the stored-scan path (which is correct
            // but much slower for large segments). Abandon on non-date,
            // non-numeric strings — the stored-scan path handles those
            // deterministically via `json_compare`.
            let to_f64 = |v: &Option<Value>| -> Option<Option<f64>> {
                match v.as_ref() {
                    None => Some(None),
                    Some(Value::Number(_)) => Some(v.as_ref().and_then(|x| x.as_f64())),
                    Some(Value::String(s)) => {
                        if let Ok(f) = s.parse::<f64>() {
                            return Some(Some(f));
                        }
                        crate::aggs::parse_date_ms(&Value::String(s.clone()))
                            .map(|ms| Some(ms as f64))
                    }
                    _ => None,
                }
            };
            let gte_opt = to_f64(gte)?;
            let gt_opt = to_f64(gt)?;
            let lte_opt = to_f64(lte)?;
            let lt_opt = to_f64(lt)?;
            // Determine [lo, hi] with inclusivity flags.
            let (lo, lo_incl) = match (gte_opt, gt_opt) {
                (Some(v), _) => (v, true),
                (None, Some(v)) => (v, false),
                (None, None) => (f64::NEG_INFINITY, true),
            };
            let (hi, hi_incl) = match (lte_opt, lt_opt) {
                (Some(v), _) => (v, true),
                (None, Some(v)) => (v, false),
                (None, None) => (f64::INFINITY, true),
            };
            let field_str = field.as_str();
            // #1750 — the memtable numeric column keeps only an array's
            // first element, so `for_each_numeric_value` below would count a
            // multi-valued doc by that element alone. Abandon to the counting
            // scan, whose matcher checks every element. (Segments already
            // abandon: a field that is an array anywhere in a segment gets no
            // dv column, which is the `None` arm below.)
            if self.memtable.range_column_unusable(field_str) {
                return None;
            }

            let segments_dir = self.data_dir.join("segments");
            let mut seg_matches: u64 = 0;
            for meta in &snap.segments {
                if meta.doc_count == 0 {
                    continue;
                }
                let cols = self.dv_columns_for(&segments_dir, &meta.id)?;
                match cols.get(field_str) {
                    Some(xerj_storage::doc_values::Column::Numeric(n)) => {
                        seg_matches =
                            seg_matches.saturating_add(n.range_count(lo, hi, lo_incl, hi_incl));
                    }
                    // DATE fields (e.g. `@timestamp`) are date-shaped Keyword dv
                    // columns, not Numeric — without this arm the shortcut
                    // abandoned and the stored scan tallied EVERY matching doc
                    // (O(N), the 340 ms cliff). The sorted epoch shadow gives the
                    // EXACT count via two bisects (same encoding + bounds
                    // derivation as the range dv prefilter). `None` from the
                    // shadow (nulls / ineligible column) abandons → full scan,
                    // still exact.
                    Some(xerj_storage::doc_values::Column::Keyword(_)) => {
                        let shadow = self.sorted_shadow_for(
                            &segments_dir,
                            &meta.id,
                            field_str,
                            meta.doc_count,
                        )?;
                        let shadow = shadow.value().as_ref()?;
                        let (slo, slo_incl, shi, shi_incl) = shadow_range_bounds(
                            gte.as_ref(),
                            gt.as_ref(),
                            lte.as_ref(),
                            lt.as_ref(),
                            self.date_scale(field_str),
                        )?;
                        seg_matches = seg_matches.saturating_add(shadow_range_count(
                            shadow, slo, shi, slo_incl, shi_incl,
                        ));
                    }
                    // A presence bitmap has no numeric or date values.
                    Some(xerj_storage::doc_values::Column::Presence(_)) | None => return None,
                }
            }

            // Memtable side — abandon the shortcut if the memtable has
            // no numeric column for this field. Otherwise we'd silently
            // return 0 and hide stored-string-date range matches that
            // the stored-scan path would otherwise find. Use a probe
            // via `for_each_numeric_value` since `shards` is private.
            //
            // NOTE: a bounded-delta sorted numeric index was trialled here to
            // make this O(log n + tail).  At the shipped 128k-doc global flush
            // cap (`FLUSH_DOC_THRESHOLD_DEFAULT`, ~8k docs/shard; historically
            // 500k/~31k) the memtable numeric column is small enough that this
            // branch-free linear f64 scan (memory-bandwidth bound, tens of µs)
            // BEATS a maintained sorted structure — the structure's per-flush
            // rebuild + sort + high-cardinality (cost_usd double) count-map
            // churn regressed range p99.  Kept the linear scan.
            if self.memtable.doc_count() > 0 {
                let mut has_any = false;
                self.memtable.for_each_numeric_value(field_str, |_| {
                    has_any = true;
                });
                if !has_any {
                    // Confirm by also checking the keyword column — if
                    // the field was indexed as keyword/text the numeric
                    // DV will be absent but so will numeric matches; we
                    // fall back to the stored-scan path rather than
                    // returning a bogus 0 count.
                    return None;
                }
            }
            let mem_matches: u64 = {
                let mut m: u64 = 0;
                self.memtable.for_each_numeric_value(field_str, |v| {
                    let pl = if lo_incl { v >= lo } else { v > lo };
                    let pu = if hi_incl { v <= hi } else { v < hi };
                    if pl && pu {
                        m += 1;
                    }
                });
                m
            };

            return Some(seg_matches + mem_matches);
        }

        // Regexp shortcut — the ES-equivalent term-dictionary rewrite.
        // ES answers `regexp` on a keyword field by expanding the pattern
        // against the field's term dictionary and unioning postings; the
        // XERJ equivalent runs the (compile-once) anchored regex over each
        // segment's DISTINCT terms — the doc-values keyword dictionary
        // when present, else the FTS `.fst` term dictionary — and sums the
        // per-term doc counts, O(segments × dictionary_size) instead of
        // O(doc_count) full stored-doc scans.
        //
        // Exactness vs the doc-scan it replaces: the Regexp arm of
        // `doc_matches_query` matches ONLY `Value::String` sources.  The
        // keyword doc-values column stores exactly those raw strings
        // (numbers / bools / arrays / objects are null in the column and
        // can never regexp-match), so it is exact for any field.  The FTS
        // FST fallback is only exact when the field is KEYWORD-typed in
        // the schema (whole raw string as a single un-lowercased token —
        // see `schema_to_field_configs`); for text/numeric fields the FST
        // holds analyzed/stringified tokens that the doc-scan would never
        // match, so we bail to the scan.  Abandoned (→ full scan) when a
        // segment has neither source (dotted / nested fields, pre-FTS
        // segments) or when deletes are present (both dictionaries tally
        // physical docs, not live ones).
        if let QueryNode::Regexp {
            field,
            pattern,
            case_insensitive,
        } = query
        {
            // Delete-blind guard — same conservative signal as the F1
            // `deletes_present` gate in `search_inner`.
            let seg_physical: u64 = snap.segments.iter().map(|m| m.doc_count).sum();
            let mem_physical = self.memtable.doc_count() as u64;
            if snap.segments.iter().any(|m| m.has_tombstones)
                || self.live_doc_count() < seg_physical + mem_physical
            {
                return None;
            }
            let field_is_keyword = {
                let schema_guard = self.schema.read().await;
                schema_guard
                    .schema
                    .field(field)
                    .map(|f| matches!(f.field_type, FieldType::Keyword))
                    .unwrap_or(false)
            };
            let segments_dir = self.data_dir.join("segments");
            let mut seg_matches: u64 = 0;
            for meta in &snap.segments {
                if meta.doc_count == 0 {
                    continue;
                }
                // Cached per-(segment, field, pattern) expansion — dv
                // keyword dictionary or FST postings union; one dictionary
                // walk + postings merge per segment LIFETIME, O(1) map hit
                // per query after that.  `None` (no usable dictionary /
                // non-keyword field / pathological pattern) abandons to
                // the stored-doc scan.
                //
                // #1812: this shortcut's segment total is used VERBATIM (no
                // doc-scan re-check), so a `case_insensitive` pattern must
                // also fold inside the dictionary expansion — otherwise the
                // count would silently drop the case-variant matches the
                // doc-scan arm would return.  Gated on `field_is_keyword`,
                // the same gate the doc-scan arm applies.
                let folded;
                let pattern: &str = if *case_insensitive && field_is_keyword {
                    folded = format!("(?i){}", pattern);
                    &folded
                } else {
                    pattern
                };
                let exp = self.regexp_segment_expansion(
                    &segments_dir,
                    &meta.id,
                    field,
                    pattern,
                    field_is_keyword,
                )?;
                seg_matches = seg_matches.saturating_add(exp.count);
            }
            // Memtable side — exact per-doc scan, the same fallback the
            // Bool arm above uses.  Memtables are flush-bounded and the
            // compiled regex is cached, so this stays cheap.  The keyword
            // count maps can NOT stand in here: they stringify numbers /
            // bools / first-array-elements, all of which the Regexp
            // doc-scan arm would never match.
            let mem_matches: u64 = if self.memtable.doc_count() == 0 {
                0
            } else {
                let docs = self.memtable.all_docs_with_sources();
                docs.iter()
                    .filter(|(_, src)| doc_matches_query_typed(query, src, schema))
                    .count() as u64
            };
            return Some(seg_matches + mem_matches);
        }

        // `terms` — union of exact per-value doc-values counts.  Distinct
        // values on a single-valued keyword/numeric column are disjoint, so
        // the summed doc-freqs are exact.  Conservative guards (ghost /
        // non-empty memtable) keep the delete/memtable-blind count from ever
        // standing in as authoritative; the ordinary scan handles those cases.
        if let QueryNode::Terms { field, values, .. } = query {
            use xerj_storage::doc_values::Column;
            if self.store.version_map.ghost_events() > 0 || self.memtable.doc_count() > 0 {
                return None;
            }
            let field_str = field.as_str();
            let segments_dir = self.data_dir.join("segments");
            let mut seg_matches: u64 = 0;
            for meta in &snap.segments {
                if meta.doc_count == 0 {
                    continue;
                }
                let cols = self.dv_columns_for(&segments_dir, &meta.id)?;
                match cols.get(field_str) {
                    Some(Column::Keyword(k)) => {
                        let mut seen: HashSet<String> = HashSet::new();
                        for v in values {
                            let raw = match v {
                                Value::String(s) => s.clone(),
                                other => other.to_string(),
                            };
                            if seen.insert(raw.clone()) {
                                seg_matches = seg_matches.saturating_add(k.doc_freq(&raw) as u64);
                            }
                        }
                    }
                    Some(Column::Numeric(n)) => {
                        let mut seen: HashSet<u64> = HashSet::new();
                        for v in values {
                            let f = v.as_f64()?;
                            if seen.insert(f.to_bits()) {
                                seg_matches =
                                    seg_matches.saturating_add(n.range_count(f, f, true, true));
                            }
                        }
                    }
                    // Presence is not a term dictionary.
                    Some(Column::Presence(_)) | None => return None,
                }
            }
            return Some(seg_matches);
        }

        // `exists` — keyword and numeric columns answer only the DENSE case:
        // no nulls and full coverage means every doc has a scalar value
        // (arrays poison the column, so a present column has no hidden
        // multi-values). A presence bitmap answers any density, because it
        // records `value_present` per row — the same predicate the source
        // scan uses — including empty strings and excluding null / `[]` /
        // `[null]`. A missing column, a column that does not cover the
        // segment, or a non-empty memtable abandons to the scan. Meta
        // fields are always present.
        if let QueryNode::Exists { field } = query {
            use xerj_storage::doc_values::Column;
            if self.store.version_map.ghost_events() > 0 || self.memtable.doc_count() > 0 {
                return None;
            }
            match field.as_str() {
                "_id" | "_index" | "_seq_no" | "_version" | "_primary_term" => {
                    return Some(self.live_doc_count());
                }
                _ => {}
            }
            let segments_dir = self.data_dir.join("segments");
            let mut seg_matches: u64 = 0;
            for meta in &snap.segments {
                if meta.doc_count == 0 {
                    continue;
                }
                let cols = self.dv_columns_for(&segments_dir, &meta.id)?;
                let add = match cols.get(field.as_str()) {
                    Some(Column::Keyword(k)) => {
                        if !k.null_bitmap.is_empty() || k.doc_count as u64 != meta.doc_count {
                            return None;
                        }
                        meta.doc_count
                    }
                    Some(Column::Numeric(n)) => {
                        if !n.null_bitmap.is_empty() || n.doc_count as u64 != meta.doc_count {
                            return None;
                        }
                        meta.doc_count
                    }
                    Some(Column::Presence(p)) => {
                        if p.doc_count as u64 != meta.doc_count {
                            return None;
                        }
                        p.count()
                    }
                    None => return None,
                };
                seg_matches = seg_matches.saturating_add(add);
            }
            return Some(seg_matches);
        }

        // Only handle single Term queries for now; Bool goes through
        // the regular path until a Bool-specific shortcut lands.
        let (field, value) = match query {
            QueryNode::Term { field, value, .. } => (field.as_str(), value),
            _ => return None,
        };

        // A CIDR value (`192.168.1.0/24`) is not a term-dictionary / count-map
        // literal: both the memtable count map and the segment `doc_freq` look
        // up the exact string, find nothing, and count 0 for the whole subnet
        // after flush (#786). Abandon the count shortcut so the full source scan
        // — which expands CIDR via `ip_matches_cidr`, exactly as the memtable's
        // hit path does — answers instead.
        if let Value::String(s) = value {
            if s.contains('/') {
                return None;
            }
        }

        // #423/#408: a keyword ARRAY (or whitespace keyword) stores only its
        // FIRST element in the memtable's single-valued count column (see
        // `push_field`), so counting `term` on any non-first element here would
        // undercount — a confident, wrong 0 while the doc is buffered, then N
        // after flush (size:0 = 0 while size:5 returned the doc). Abandon to the
        // stored-source scan, which matches array membership via
        // `doc_matches_query`. Mirrors the identical guard in
        // `doc_values_term_query` / `doc_values_bool_hits`.
        if self.memtable.term_count_needs_source_scan(field) {
            return None;
        }

        // Memtable side — M5.1 sharded count via per-shard count maps.
        // Each shard lazily rebuilds its own count map on first query
        // after an ingest; the sharded `doc_values_*_count` helpers
        // fan out the call across shards and sum the results.
        let mem_matches: u64 = {
            if self.memtable.doc_count() == 0 {
                0
            } else {
                // `value.as_str()`/`.as_f64()` both return `None` for a
                // JSON boolean, so a boolean-field term query previously
                // never matched a single memtable-resident doc regardless
                // of actual content — found empirically: `mem_doc_count`
                // was non-zero (this branch DOES run) yet a real boolean
                // filter still undercounted to a confident, wrong 0. Match
                // `scored_fast_plan`'s `scoring_leaf` (already correct for
                // this exact case) and the memtable's own on-insert
                // encoding (`push_field`'s `Value::Bool` arm, which stores
                // BOTH the 1.0/0.0 numeric form and the "true"/"false"
                // keyword form) by coercing bool → both representations
                // here too.
                let target_str: Option<String> = match value {
                    Value::Bool(b) => Some(b.to_string()),
                    _ => value.as_str().map(String::from),
                };
                let target_num: Option<f64> = match value {
                    Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
                    _ => value.as_f64(),
                };
                let mut m = 0u64;
                if let Some(tgt) = target_num {
                    m += self.memtable.doc_values_numeric_count(field, tgt) as u64;
                }
                if m == 0 {
                    if let Some(ref tgt) = target_str {
                        m += self.memtable.doc_values_keyword_count(field, tgt) as u64;
                    } else if let Some(tgt) = target_num {
                        let s = tgt.to_string();
                        m += self.memtable.doc_values_keyword_count(field, &s) as u64;
                    }
                }
                m
            }
        };

        // Segment side — prefer the on-disk doc-values fast path (G2)
        // over the FTS term dictionary.  DocValues reads are a single
        // DashMap cache hit after the first query; the FTS path has to
        // parse the 13 MB meta.json per segment which is where ~200 ms/
        // query was going.
        //
        // Strategy:
        //   1. For each segment, load the cached doc-values columns.
        //   2. Keyword column → `doc_freq(term)` is an O(n) ord scan.
        //   3. Numeric column → `range_count(v, v, true, true)` bisects
        //      the sorted index in O(log n).
        //   4. Neither column present for this segment → abandon (#362).
        //      The FTS term dictionary used to answer here and it is the
        //      wrong oracle; see the comment on that branch below.
        let segments_dir = self.data_dir.join("segments");
        let raw = match value {
            Value::String(s) => s.as_str().to_string(),
            other => other.to_string(),
        };
        // Same bool coercion as the memtable side above — `value.as_f64()`
        // alone returns `None` for a JSON boolean, which used to make
        // `served_by_dv` false for every segment whose on-disk column for
        // this field is `Column::Numeric` (the boolean encoding
        // `build_doc_value_columns` always uses), falling through to an
        // FTS lookup that has no real content for a non-analyzed boolean
        // field and confidently returns 0 instead of the correct count.
        let target_num: Option<f64> = match value {
            Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
            _ => value.as_f64(),
        };

        let mut seg_matches: u64 = 0;
        for meta in &snap.segments {
            if meta.doc_count == 0 {
                continue;
            }
            let cols = self.dv_columns_for(&segments_dir, &meta.id);

            let mut served_by_dv = false;
            if let Some(cols) = cols {
                match cols.get(field) {
                    Some(xerj_storage::doc_values::Column::Keyword(k)) => {
                        let df = k.doc_freq(&raw);
                        seg_matches = seg_matches.saturating_add(df as u64);
                        served_by_dv = true;
                    }
                    Some(xerj_storage::doc_values::Column::Numeric(n)) => {
                        if let Some(tgt) = target_num {
                            seg_matches =
                                seg_matches.saturating_add(n.range_count(tgt, tgt, true, true));
                            served_by_dv = true;
                        }
                    }
                    // Presence is not a term dictionary. Leave `served_by_dv`
                    // false so the caller abandons to the source scan (#362):
                    // a `term` on text must agree with `_search`, which
                    // compares the whole source value, not a bit.
                    Some(xerj_storage::doc_values::Column::Presence(_)) | None => {}
                }
            }

            if served_by_dv {
                continue;
            }

            // No doc-values column for this field in this segment: ABANDON
            // (#362).  This used to fall back to the segment's FTS term
            // dictionary, which answers a DIFFERENT question than the one
            // `_search` answers, so `_count` published totals no page of hits
            // could reproduce:
            //
            //   term title=testsegmentreader.java   _count 1, _search total 0
            //   term title=quick, "the quick brown fox"
            //                                       _count 1, _search total 0
            //
            // A field only reaches here because it has no column, which on
            // this engine means an analyzed `text` field (`es_compat`'s
            // `doc_values_default`) or an explicit `doc_values: false`.  Its
            // term dictionary holds ANALYZED tokens — `build_fts_field_configs`
            // gives `Text` the standard analyzer, so the entries are
            // tokenized and lowercased — while `query_node_to_fts_with_
            // keyword_fields` declines the FTS projection for a bare `Term`
            // and `_search` resolves it through `doc_matches_query`, comparing
            // the WHOLE `_source` value.  A dictionary hit therefore says
            // nothing about whether the scan will produce a document.
            //
            // The lowercase re-spelling this replaces (`term_doc_freq(raw)`
            // `.or_else(term_doc_freq(lowered))`) was scaffolding over that:
            // it retried with a term the caller never wrote, which is what
            // made `term` look case-normalising next to `prefix`/`wildcard`
            // and is what #362 was filed as.  Deleting only the retry does
            // not fix this — the `quick` row above carries no casing at all,
            // its dictionary hit is genuine, and the byte-exact spelling
            // would start counting 0 where `_search` still answers 1.  The
            // oracle is wrong, not its spelling.
            //
            // Lucene's counts cannot drift this way: the sub-linear answer is
            // a method on the same `Weight` that builds the scorer, and its
            // default is "I cannot answer" — `Weight::count`
            // (lucene/core/src/java/org/apache/lucene/search/Weight.java:198)
            // returns -1, documented as the count not being computable in
            // sub-linear time, so `IndexSearcher::count`
            // (lucene/core/src/java/org/apache/lucene/search/IndexSearcher.java:495)
            // collects for real.  The specialisation that does answer,
            // `TermQuery::TermWeight::count`
            // (lucene/core/src/java/org/apache/lucene/search/TermQuery.java:260),
            // reads `termsEnum.docFreq()` off the query's OWN term state and
            // hands straight back to `super.count` once deletions make that
            // stop being the live answer.  Returning `None` here is that
            // hand-back: the caller's delete-aware scan — the code that
            // materialises the hits — answers instead.
            //
            // Cost: a `term` count on a text field is a scan again.  That is
            // the price of the number being true, and it is paid only by the
            // shape that was wrong.
            //
            // (What `_search` SHOULD do for a `term` on an analyzed field is
            // a separate question — ES matches the analyzed dictionary, so
            // `quick` would find "the quick brown fox" there.  Changing that
            // moves the hit set and needs its own issue; this change only
            // makes `_count` agree with whatever `_search` does today.)
            return None;
        }

        Some(mem_matches + seg_matches)
    }
}

// ── Cached segment doc-values agg fast path ─────────────────────────────────

impl Index {
    /// Cache-backed `.dv` column loader.
    ///
    /// Note: M5.23 (clear-on-overflow cap) and M5.24 (proper LRU) both
    /// failed to improve sustained concurrent QPS.  The fundamental
    /// issue is that with 195 small segments, queries sweep ALL of
    /// them every time, so the working set IS the full cache.  Any
    /// eviction loses state that's needed moments later.  The right
    /// fix is forcemerge → 1 segment (which blows up on a separate
    /// memory issue in run_merge_once, M5.16/22 capped but still
    /// converges slowly).  Left unbounded for now.
    /// Bundle the publish-time warm targets (see `warm_segment_at_publish`).
    fn publish_warm_caches(&self) -> PublishWarmCaches {
        PublishWarmCaches {
            slices: Arc::clone(&self.stored_slices_cache),
            dv: Arc::clone(&self.dv_cache),
            shadow: Arc::clone(&self.sort_shadow_cache),
            shadow_fields: Arc::clone(&self.sort_shadow_fields),
            lifecycle: Arc::clone(&self.segment_cache_lifecycle),
            budget: Arc::clone(&self.segment_hydration_budget),
            stored_values: Arc::clone(&self.stored_value_cache),
            id_positions: Arc::clone(&self.id_pos_cache),
            row_sequences: Arc::clone(&self.row_seq_cache),
            decoded_stored: Arc::clone(&self.decoded_stored_cache),
        }
    }

    /// Publish one already-built immutable value if its segment is still
    /// current. Build and retained-size estimation happen before this short
    /// transaction. Lock order: build mutex → lifecycle → DashMap shard.
    fn publish_current<T>(
        &self,
        map: &dashmap::DashMap<String, Resident<T>>,
        segment_id: &str,
        key: String,
        category: SegmentCacheCategory,
        bytes: u64,
        value: T,
    ) -> Resident<T> {
        self.publish_current_with_budget(
            map,
            segment_id,
            key,
            category,
            bytes,
            value,
            &self.segment_hydration_budget,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn publish_current_with_budget<T>(
        &self,
        map: &dashmap::DashMap<String, Resident<T>>,
        segment_id: &str,
        key: String,
        category: SegmentCacheCategory,
        bytes: u64,
        value: T,
        budget: &Arc<SegmentHydrationBudget>,
    ) -> Resident<T> {
        #[cfg(test)]
        {
            let bit = 1_u64 << category as usize;
            self.test_segment_cache_publish_ready_mask
                .fetch_or(bit, Ordering::Release);
            while self
                .test_segment_cache_publish_pause_mask
                .load(Ordering::Acquire)
                & bit
                != 0
            {
                std::thread::yield_now();
            }
        }
        let _publication = self.segment_cache_lifecycle.read();
        if !self
            .store
            .snapshot()
            .segments
            .iter()
            .any(|meta| meta.id == segment_id)
        {
            return CacheResident::uncached(value);
        }
        use dashmap::mapref::entry::Entry;
        match map.entry(key) {
            Entry::Occupied(entry) => Arc::clone(entry.get()),
            Entry::Vacant(entry) => {
                let Some(charge) = budget.try_charge(category, bytes) else {
                    return CacheResident::uncached(value);
                };
                let resident = CacheResident::admitted(value, charge, category, bytes);
                entry.insert(Arc::clone(&resident));
                resident
            }
        }
    }

    /// Caller holds `segment_cache_lifecycle.write()`.
    fn remove_segment_hydration_entries(&self, segment_id: &str) {
        self.stored_value_cache.remove(segment_id);
        self.dv_cache.remove(segment_id);
        self.id_pos_cache.remove(segment_id);
        self.row_seq_cache.remove(segment_id);
        self.stored_slices_cache.remove(segment_id);
        self.decoded_stored_cache.remove(segment_id);
        // Keyed by "<segment_id>\u{1}<field-set>", so evict by prefix.
        let fts_prefix = format!("{segment_id}\u{1}");
        self.fts_reader_cache
            .retain(|key, _| !key.starts_with(&fts_prefix));
        // Keyed by "<segment_id>\u{1}<field>\u{1}<mode>" — same prefix.
        self.vector_column_cache
            .retain(|key, _| !key.starts_with(&fts_prefix));
        let shadow_prefix = format!("{segment_id}\u{1}");
        self.sort_shadow_cache
            .retain(|key, _| !key.starts_with(&shadow_prefix));

        // DashMap retains shard capacity after logical removals. Shrinking
        // only an entirely empty map avoids locking every shard on each merge.
        if self.stored_value_cache.is_empty() {
            self.stored_value_cache.shrink_to_fit();
        }
        if self.dv_cache.is_empty() {
            self.dv_cache.shrink_to_fit();
        }
        if self.id_pos_cache.is_empty() {
            self.id_pos_cache.shrink_to_fit();
        }
        if self.row_seq_cache.is_empty() {
            self.row_seq_cache.shrink_to_fit();
        }
        if self.stored_slices_cache.is_empty() {
            self.stored_slices_cache.shrink_to_fit();
        }
        if self.decoded_stored_cache.is_empty() {
            self.decoded_stored_cache.shrink_to_fit();
        }
        if self.sort_shadow_cache.is_empty() {
            self.sort_shadow_cache.shrink_to_fit();
        }
    }

    /// Open a segment's FTS side-cars, reusing a cached reader when one exists.
    ///
    /// This is the read-side of `fts_reader_cache`. See that field for why the
    /// open is expensive (two zstd decompressions per field, ~50 ms / ~41 MB on
    /// a real production field) and why caching is sound (segments are
    /// immutable).
    ///
    /// Returns `None` exactly where the previous inline
    /// `FtsIndexReader::open(..).ok()` returned `None`, so a missing or
    /// unreadable side-car still falls through to the stored-doc scan rather
    /// than failing the query.
    fn fts_reader_for(
        &self,
        fts_dir: &std::path::Path,
        segment_id: &str,
        fields: &[&str],
    ) -> Option<Resident<Arc<FtsIndexReader>>> {
        // The field set is part of the identity: `open` loads only the fields
        // it is given, so a reader opened for a narrower set must never serve a
        // query that needs a wider one. Sort so that permutations of the same
        // set share one entry.
        let mut sorted: Vec<&str> = fields.to_vec();
        sorted.sort_unstable();
        sorted.dedup();
        let key = format!("{segment_id}\u{1}{}", sorted.join("\u{2}"));

        if let Some(hit) = self.fts_reader_cache.get(&key) {
            return Some(Arc::clone(hit.value()));
        }

        let reader = Arc::new(FtsIndexReader::open(fts_dir, segment_id, fields).ok()?);
        let bytes = reader.retained_bytes();
        Some(self.publish_current(
            &self.fts_reader_cache,
            segment_id,
            key,
            SegmentCacheCategory::FtsReader,
            bytes,
            reader,
        ))
    }

    fn dv_columns_for(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
    ) -> Option<Resident<DocValueMap>> {
        if let Some(entry) = self.dv_cache.get(segment_id) {
            return Some(Arc::clone(entry.value()));
        }
        let cols = read_doc_values_sidecar(segments_dir, segment_id);
        if cols.is_empty() {
            return None;
        }
        let key = segment_id.to_string();
        let bytes = cache_estimates::doc_values_bytes(
            &key,
            std::mem::size_of::<CacheResident<DocValueMap>>(),
            &cols,
        );
        Some(self.publish_current(
            &self.dv_cache,
            segment_id,
            key,
            SegmentCacheCategory::DocValues,
            bytes,
            cols,
        ))
    }

    /// Columnar `function_score { match_all, field_value_factor }` fast path.
    ///
    /// Scores EVERY live document — segment rows straight from the numeric
    /// doc-values column, plus the in-memory memtable sources — through the
    /// exact [`compute_field_value_factor`] the brute path uses, selects the
    /// GLOBAL top-`cap` by that score, and hydrates `_source` only for the
    /// winners via the F2 random-access slice path. This replaces the brute
    /// stored scan, which (a) parses every doc's JSON and (b) only ranks the
    /// arrival-order first-`cap` matches, so on a >`cap`-doc corpus its top-k
    /// is not the true top-k.
    ///
    /// Returns `None` — so the caller falls back to the unchanged brute scan —
    /// for any segment lacking a numeric dv column for the field, a shape/count
    /// mismatch, a malformed stored slice, or any per-row score that is
    /// non-finite / negative (the ES `illegal_argument_exception` path, which
    /// the brute fallback reproduces with the exact reason + doc index).
    ///
    /// Emitted hits carry the BASE match_all score (`1.0`); the caller's
    /// existing post-loop runs `apply_function_score` exactly once to set the
    /// final ES score — i.e. this path is single-application (correct vs ES),
    /// whereas the legacy brute path double-applies (squares) the function.
    /// The caller only reaches here with `deletes_present == false`, so every
    /// non-tombstoned row/entry is live.
    fn function_score_columnar(
        &self,
        fvf: &FieldValueFactor,
        segments: &[xerj_storage::segment::SegmentMeta],
        segments_dir: &std::path::Path,
        cap: usize,
    ) -> Option<(Vec<Hit>, u64)> {
        use xerj_storage::doc_values::Column;
        let field = fvf.field.as_str();

        enum Cand {
            Mem(u32),
            Seg(u32, u32),
        }
        let mut cands: Vec<(f32, Cand)> = Vec::new();

        // ── Live memtable docs ────────────────────────────────────────────
        // Sources are already parsed Values in memory; score them through the
        // identical `compute_field_value_factor` for byte-for-byte parity.
        let mem_docs = self.memtable.all_docs_with_sources_arc();
        for (i, (id, source)) in mem_docs.iter().enumerate() {
            if let Some(ver) = self.store.version_map.get(id) {
                if ver.deleted {
                    continue;
                }
            }
            let score = compute_field_value_factor(fvf, source);
            if !score.is_finite() || score < 0.0 {
                return None;
            }
            cands.push((score, Cand::Mem(i as u32)));
        }

        // ── Segment numeric doc-values columns ────────────────────────────
        // Score each row straight from the f64 dv value through the SAME
        // `fvf_score_from_raw` the brute scorer uses (a null/absent row scores
        // as `fvf.missing`/0.0, identical to a missing `_source` field) — no
        // per-row `_source`/`Value`/map lookup.
        for (si, meta) in segments.iter().enumerate() {
            let cols = self.dv_columns_for(segments_dir, &meta.id)?;
            let Some(Column::Numeric(n)) = cols.get(field) else {
                return None;
            };
            if n.doc_count as u64 != meta.doc_count {
                return None;
            }
            for row in 0..n.doc_count {
                let raw = if n.null_bitmap.contains(row) {
                    None
                } else {
                    // Numeric dv columns store the f64 bit-pattern.
                    Some(f64::from_bits(n.data[row as usize] as u64))
                };
                let score = fvf_score_from_raw(fvf, raw);
                if !score.is_finite() || score < 0.0 {
                    return None;
                }
                cands.push((score, Cand::Seg(si as u32, row)));
            }
        }

        // Authoritative, delete-aware, de-duplicated live count == ES match_all
        // total (caller guarantees `deletes_present == false`).
        let total = self.store.version_map.live_count() as u64;

        // ── Global top-`cap` selection by score (descending) ──────────────
        let keep = cap.min(cands.len());
        if keep > 0 && cands.len() > keep {
            cands.select_nth_unstable_by(keep - 1, |a, b| {
                b.0.partial_cmp(&a.0).unwrap_or(std::cmp::Ordering::Equal)
            });
            cands.truncate(keep);
        }

        // ── Hydrate winners (final ordering + tie-break happen in the caller's
        // post-loop score sort, keyed by the re-applied function score) ──────
        let mut hits: Vec<Hit> = Vec::with_capacity(keep);
        let mut seen: HashSet<String> = HashSet::with_capacity(keep);
        for (_score, cand) in cands {
            match cand {
                Cand::Mem(i) => {
                    let (id, source) = &mem_docs[i as usize];
                    if !seen.insert(id.clone()) {
                        continue;
                    }
                    // Same read the winner's `_source` is hydrated from
                    // (post-select_nth winners only) — not a later pass (#440).
                    let (seq_no, version) = self
                        .store
                        .version_map
                        .get(id)
                        .map(|ver| self.hit_seq_version(id, &ver))
                        .unwrap_or((None, None));
                    hits.push(Hit {
                        id: id.clone(),
                        score: 1.0,
                        source: (**source).clone(),
                        seq_no,
                        version,
                        sort: Vec::new(),
                        explain: None,
                        highlight: None,
                        matched_queries: Vec::new(),
                        passage: None,
                    });
                }
                Cand::Seg(si, row) => {
                    let meta = &segments[si as usize];
                    let slices = self.stored_slices_for(meta.id.as_str(), meta.doc_count)?;
                    let &(start, end) = slices.offsets.get(row as usize)?;
                    let slice = slices.bytes.get(start as usize..end as usize)?;
                    // serde_json (not simd_json) for the per-doc slice parse:
                    // only `cap` winners are parsed, and serde handles every
                    // raw-bytes-flush payload correctly (see `stored_values_for`).
                    let doc: Value = serde_json::from_slice(slice).ok()?;
                    let id = doc
                        .get("_id")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                        .to_string();
                    if id.is_empty() || !seen.insert(id.clone()) {
                        continue;
                    }
                    let source = doc.get("_source").cloned().unwrap_or(doc);
                    // Same read `source` was just parsed from — not a later
                    // pass (#440).
                    let (seq_no, version) = self
                        .store
                        .version_map
                        .get(&id)
                        .map(|ver| self.hit_seq_version(&id, &ver))
                        .unwrap_or((None, None));
                    hits.push(Hit {
                        id,
                        score: 1.0,
                        source,
                        seq_no,
                        version,
                        sort: Vec::new(),
                        explain: None,
                        highlight: None,
                        matched_queries: Vec::new(),
                        passage: None,
                    });
                }
            }
        }
        Some((hits, total))
    }

    /// Columnar exact-BM25 executor for the scored family
    /// (`dis_max` / `boosting` / `pinned` / scoring `bool`) — the shapes
    /// admitted by [`scored_fast_plan`].
    ///
    /// Walks every segment row straight from the doc-values columns,
    /// computes the EXACT ES score per matching row (per-clause BM25
    /// constants from GLOBAL term stats — see [`bm25_keyword_term_score`] —
    /// combined per shape with ES/Lucene's float widths), keeps the global
    /// top-`cap` by `(score DESC, seq_no ASC)` (= arrival order = ES's
    /// Lucene-doc-id `_doc` tie-break; scores here are massively tied so
    /// score-only selection would return an arbitrary tied subset, and
    /// segment ROW order is NOT arrival order — the sharded memtable flush
    /// interleaves rows — so rows are ranked via the cached per-segment
    /// `row_seqs_for` map, the same key the caller's final sort re-derives
    /// per hit via `lookup_seq_no`), and hydrates
    /// `_source` only for the winners via the F2 random-access slice path.
    /// Also returns the EXACT match total (`track_total_hits: true`).
    ///
    /// Returns `None` — caller falls back to the unchanged brute scan — when
    /// the memtable is non-empty, any referenced column is missing /
    /// kind-mismatched / row-count-mismatched, any SCORING field has nulls
    /// (the null-free gate simultaneously guarantees `N == Σ doc_count` for
    /// the idf and excludes array-valued docs, which the column builder
    /// records as nulls), or a pinned id can't be resolved through a
    /// complete per-segment `_id → position` map. Deletes/overwrites are
    /// handled ghost-aware: term stats stay PHYSICAL (Lucene's deleted-doc
    /// -inclusive docFreq/docCount until a merge purges them) while
    /// matching/totals are liveness-filtered via `ghost_positions_for`;
    /// `Pinned` still bails whenever any ghost event was recorded.
    /// Constant ES BM25 base score of a single scoring LEAF query — a
    /// `term`/`match` on a keyword, boolean or numeric field (the batch-11
    /// keyword scored surface) — derived from the SAME physical dv-column
    /// stats `scored_columnar` uses (Lucene-parity: ghost rows included).
    ///
    /// Keyword fields omit norms and have `freq = 1`, so the per-doc BM25
    /// score is a per-term constant; numeric leaves score the constant
    /// `boost` (ES points carry no BM25 stats). Used by the brute per-doc
    /// scorer for shapes the columnar executor doesn't serve (field sorts,
    /// `track_scores`, function_score inners) so their `_score`s match ES
    /// instead of the IDF-less flat scorer. `None` (→ legacy flat scoring)
    /// when the query isn't such a leaf, the memtable is non-empty, or any
    /// segment lacks a clean column.
    /// Fold the INDEX-WIDE BM25 collection statistics for one query (#188):
    /// per-field `FieldStats` and per-(field, term) `doc_freq`, unioned over
    /// every segment in `snap` PLUS the memtable.
    ///
    /// Modelled on `IndexSearcher.fieldStats` (sums `docCount` over
    /// `reader.leaves()`) + `TermStates.build` (sums `docFreq` over them) —
    /// Apache-2.0, adapted, not copied:
    /// `lucene/core/src/java/org/apache/lucene/search/IndexSearcher.java:1144-1159`
    /// and `.../index/TermStates.java:96-126,158-164`; the Rust shape follows
    /// tantivy's `Bm25StatisticsProvider for Searcher`
    /// (`tantivy/src/query/bm25.rs:26-49`, MIT).
    ///
    /// `None` when there is nothing to unify — no FTS projection, or a query
    /// whose field × term cross-product is too wide to be worth a pre-pass.
    /// The caller then keeps the historical per-arm statistics.
    ///
    /// COST.  Per segment this opens a STATS-ONLY reader
    /// (`FtsIndexReader::open_stats_only`): the FST is mmap'd and the `.meta`
    /// side-car is read AND ZFM4-decoded — a zstd decompress of the
    /// `num_terms × 24`-byte records section, so O(field vocabulary), small
    /// but not free (#193).  What IS skipped are the two expensive parts of a
    /// full open: the postings envelope (whole-file read + zstd decompress of
    /// every posting list, O(index bytes)) and the norms table (O(docs)) —
    /// the statistics never touch either.  The pre-pass also cannot defeat
    /// the two read-path fast paths it sits near: F1's early-break requires
    /// `!query_needs_fts`, and the `term_doc_freq` count-only shortcut
    /// requires `count_only` — the caller gates this whole block off for
    /// both.
    ///
    /// `mem_doc_count` is the caller's ONE point-in-time memtable count —
    /// captured next to the segment snapshot and already the input to the
    /// `stats_gate_open` arm arithmetic (#193).  Re-reading
    /// `self.memtable.doc_count()` here made the include-the-memtable
    /// decision from a SECOND, later reading that could disagree with the
    /// gate's (and re-paid the 16-shard lock fan-out the capture exists to
    /// avoid).  The stats CONTENT still reads the live shards — exactly like
    /// the memtable search arm it feeds, which holds no snapshot either.
    // One argument over clippy's default: `pinned` (#892) joins the field
    // sets, the snapshot and the memtable count that this pre-pass already
    // needs, and they are all borrowed from `search_inner`'s frame — bundling
    // them into a struct would only move the same list one level out.
    #[allow(clippy::too_many_arguments)]
    fn build_collection_stats(
        &self,
        snap: &xerj_storage::index_store::IndexSnapshot,
        query: &QueryNode,
        text_fields: &[String],
        exact_fields: &HashSet<String>,
        keyword_fields: &HashSet<String>,
        mem_doc_count: usize,
        // #892: same projection the segment loop will run, so a pinned kNN
        // hybrid resolves its lexical leaves here too instead of declining and
        // silently reverting every segment to per-segment BM25 statistics.
        pinned: Option<PinnedIds<'_>>,
    ) -> Option<xerj_fts::CollectionStats> {
        // Widest pre-pass we will pay for, budgeted per COST CLASS (#1186):
        //
        //  * FIELD probes — `open_stats_only` mmaps one FST per (segment,
        //    field) and `field_stats` walks its meta.  A field-less
        //    `query_string` over a wide mapping can project hundreds of
        //    leaves, and that product (fields × segments) is the explosion
        //    the original 4096 combined cap existed to stop.  Unchanged.
        //
        //  * TERM probes — one FST seek per (segment, term).  These were
        //    lumped into the same 4096 cap, which had a correctness cost the
        //    field case does not: a long `match` query (an agent pasting a
        //    blob, a 1502-term repro) crossed the cap on any multi-segment
        //    index, the pre-pass silently declined, and every segment fell
        //    back to its own df/avgdl — padding a query with terms that
        //    match NOTHING reordered the whole top-5 (#1186).  Execution
        //    itself already pays ~one postings seek per (segment, term), so
        //    the pre-pass at most doubles a cost the query is already
        //    incurring: Lucene collects `TermStates` for every clause it
        //    executes and never falls back to per-leaf statistics (its
        //    bound is the clause count, which refuses the query instead of
        //    re-scoring it).  The term budget below only exists so a
        //    pathological million-term query cannot make the pre-pass
        //    dominate a search that execution would itself refuse.  The bar
        //    is set at 2^20 probes (~1–2 s of FST seeks) — a query must
        //    exceed a MILLION (term × segment) products to hit it, i.e. a
        //    1,500-term query on a ~700-segment index; anything the engine
        //    answers in sane time keeps index-wide statistics, and when the
        //    budget DOES decline it says so on the log instead of silently
        //    changing the ranking.  (The reporter's literal repro — 1,502
        //    terms on a 32-core box's ~128 flush segments, ≈192k probes —
        //    sits comfortably inside.)
        const MAX_STATS_FIELD_PROBES: usize = 4096;
        const MAX_STATS_TERM_PROBES: usize = 1_048_576;

        let fq = query_node_to_fts_projected(
            query,
            text_fields,
            exact_fields,
            keyword_fields,
            self.segment_analyzer_binding(),
            pinned,
        )?;
        let mut fields: Vec<String> = Vec::new();
        collect_fts_query_fields(&fq, &mut fields);
        if fields.is_empty() {
            return None;
        }
        let mut pairs: Vec<(String, String)> = Vec::new();
        collect_fts_query_terms(&fq, &mut pairs);
        let field_refs: Vec<&str> = fields.iter().map(|s| s.as_str()).collect();

        // The memtable's own contribution, analysed with ITS analyzer over the
        // raw query text — the same input its FTS arm will score, so the
        // tokens line up with the ones it actually uses.  Collected FIRST so
        // any token the segment projection never named (per-field analyzers
        // can differ) joins `pairs` and gets its segment-side df in the single
        // pass below, instead of the memtable silently keeping a local df.
        let mem_stats: Option<xerj_fts::CollectionStats> = if mem_doc_count > 0 {
            extract_query_text(query)
                .and_then(|text| self.memtable.collection_stats(&text, &field_refs))
        } else {
            None
        };
        if let Some(ms) = mem_stats.as_ref() {
            for (f, t) in ms.term_keys() {
                if !pairs.iter().any(|(pf, pt)| pf == f && pt == t) {
                    pairs.push((f.clone(), t.clone()));
                }
            }
        }

        let segs = snap.segments.len().max(1);
        if fields.len() * segs > MAX_STATS_FIELD_PROBES {
            tracing::warn!(
                fields = fields.len(),
                segments = segs,
                "search: BM25 collection statistics declined ({}) field probes > \
                 {MAX_STATS_FIELD_PROBES} — segments will score against their own \
                 df/avgdl and scores will not be comparable across segments",
                fields.len() * segs
            );
            return None;
        }
        if pairs.len() * segs > MAX_STATS_TERM_PROBES {
            tracing::warn!(
                terms = pairs.len(),
                segments = segs,
                "search: BM25 collection statistics declined ({}) term probes > \
                 {MAX_STATS_TERM_PROBES} — segments will score against their own \
                 df/avgdl and scores will not be comparable across segments",
                pairs.len() * segs
            );
            return None;
        }

        let mut out = xerj_fts::CollectionStats::new();
        let segments_dir = self.data_dir.join("segments");
        for meta in snap.segments.iter() {
            let Ok(reader) =
                xerj_fts::FtsIndexReader::open_stats_only(&segments_dir, &meta.id, &field_refs)
            else {
                // A segment whose statistics we cannot read would skew the
                // union low and silently inflate every other arm's IDF.
                // Fall back to per-arm statistics rather than half a union —
                // and SAY so (#1186: every decline from index-wide stats is
                // a silent ranking change, never a quiet local decision).
                tracing::warn!(
                    segment = %meta.id,
                    "search: BM25 collection statistics declined — segment stats \
                     unreadable; segments will score against their own df/avgdl and \
                     scores will not be comparable across segments"
                );
                return None;
            };
            for f in &fields {
                if let Some(fs) = reader.field_stats(f) {
                    out.add_field(f, fs);
                }
            }
            for (f, term) in &pairs {
                if let Some(df) = reader.term_doc_freq(f, term) {
                    out.add_doc_freq(f, term, df as u64);
                }
            }
        }
        if let Some(ms) = mem_stats.as_ref() {
            for (f, fs) in ms.field_iter() {
                if fields.iter().any(|x| x == f) {
                    out.add_field(f, fs);
                }
            }
            for (f, term) in &pairs {
                if let Some(df) = ms.df(f, term) {
                    out.add_doc_freq(f, term, df);
                }
            }
        }

        if out.is_empty() {
            None
        } else {
            Some(out)
        }
    }

    fn leaf_constant_score(
        &self,
        q: &QueryNode,
        kw_fields: &HashSet<String>,
        num_fields: &HashSet<String>,
        bool_fields: &HashSet<String>,
    ) -> Option<f32> {
        use xerj_storage::doc_values::Column;
        if self.memtable.doc_count() != 0 {
            return None;
        }
        enum LeafConst {
            Keyword(String),
            BoolEq(f64),
            Numeric,
        }
        let mut node = q;
        while let QueryNode::Named { query, .. } = node {
            node = query;
        }
        let (field, kind, boost): (&str, LeafConst, f32) = match node {
            // A CIDR value (`192.168.1.0/24`) is not a term-dictionary literal;
            // the source scan expands it via `ip_matches_cidr`. Excluding it here
            // routes it to the full scan (`_ => return None`) instead of summing
            // `per_ord_count` for an ordinal that does not exist, which counted 0
            // for the whole subnet after flush (#786).
            QueryNode::Term {
                field,
                value: Value::String(term),
                boost,
            } if kw_fields.contains(field) && !term.contains('/') => (
                field,
                LeafConst::Keyword(term.clone()),
                boost.unwrap_or(1.0),
            ),
            QueryNode::Term {
                field,
                value,
                boost,
            } if bool_fields.contains(field) => {
                let v = match value {
                    Value::Bool(true) => 1.0,
                    Value::Bool(false) => 0.0,
                    Value::String(s) if s == "true" => 1.0,
                    Value::String(s) if s == "false" => 0.0,
                    _ => return None,
                };
                (field, LeafConst::BoolEq(v), boost.unwrap_or(1.0))
            }
            QueryNode::Term {
                field,
                value,
                boost,
            } if num_fields.contains(field) => {
                value.as_f64()?;
                (field, LeafConst::Numeric, boost.unwrap_or(1.0))
            }
            QueryNode::Match {
                field,
                query,
                analyzer: None,
                boost,
                minimum_should_match: None,
                ..
            } if kw_fields.contains(field) => (
                field,
                LeafConst::Keyword(query.clone()),
                boost.unwrap_or(1.0),
            ),
            QueryNode::Match {
                field,
                query,
                analyzer: None,
                boost,
                minimum_should_match: None,
                ..
            } if num_fields.contains(field) => {
                query.parse::<f64>().ok()?;
                (field, LeafConst::Numeric, boost.unwrap_or(1.0))
            }
            _ => return None,
        };
        if !boost.is_finite() || boost < 0.0 {
            return None;
        }
        if matches!(kind, LeafConst::Numeric) {
            return Some(boost);
        }
        let snap = self.store.snapshot();
        let segments_dir = self.data_dir.join("segments");
        let mut total_docs: u64 = 0;
        let mut df: u64 = 0;
        for meta in snap.segments.iter() {
            let cols = self.dv_columns_for(&segments_dir, &meta.id)?;
            total_docs += meta.doc_count;
            match &kind {
                LeafConst::Keyword(term) => {
                    let Some(Column::Keyword(k)) = cols.get(field) else {
                        return None;
                    };
                    if k.doc_count as u64 != meta.doc_count || !k.null_bitmap.is_empty() {
                        return None;
                    }
                    if let Some(ord) = k.ord_for_term(term) {
                        df += k.per_ord_count.get(ord as usize).copied().unwrap_or(0) as u64;
                    }
                }
                LeafConst::BoolEq(v) => {
                    let Some(Column::Numeric(nc)) = cols.get(field) else {
                        return None;
                    };
                    if nc.doc_count as u64 != meta.doc_count || !nc.null_bitmap.is_empty() {
                        return None;
                    }
                    df += nc
                        .data
                        .iter()
                        .filter(|&&b| f64::from_bits(b as u64) == *v)
                        .count() as u64;
                }
                LeafConst::Numeric => unreachable!(),
            }
        }
        if total_docs == 0 || df == 0 {
            return None;
        }
        Some(bm25_keyword_term_score(df, total_docs, boost))
    }

    #[allow(clippy::too_many_arguments)]
    fn scored_columnar(
        &self,
        plan: &ScoredPlan,
        segments: &[xerj_storage::segment::SegmentMeta],
        segments_dir: &std::path::Path,
        cap: usize,
        page: usize,
        page_from: usize,
        total_limit: Option<u64>,
    ) -> Option<(Vec<Hit>, u64, bool)> {
        use xerj_storage::doc_values::Column;

        // The memtable has no doc-values columns, and its rows would need
        // their own global-stats treatment — serve fully-flushed data only.
        if self.memtable.doc_count() != 0 {
            return None;
        }

        // Ghost-aware (Lucene delete semantics): term stats stay PHYSICAL —
        // per-ord counts and segment doc_counts include deleted/superseded
        // rows exactly like Lucene's docFreq/docCount until a merge purges
        // them — while MATCHING (hits + total) is liveness-filtered through
        // the per-segment ghost bitmaps. With no ghost event ever recorded
        // (the common /bench case) the bitmap lookup is skipped entirely.
        let any_ghosts = self.store.version_map.ghost_events() > 0;
        // Pinned under ghosts would need a superseded-aware `_id → position`
        // map (an updated doc's id resolves in BOTH its old and new
        // segments) — keep the brute path there.
        if any_ghosts && matches!(plan, ScoredPlan::Pinned { .. }) {
            return None;
        }

        // Flat leaf/filter lists in DFS order + (for `Composed`) the eval
        // tree whose leaf/filter indices point into them. Order matters:
        // each bool DFS-walks filter, must_not, must, then should, so the
        // per-segment `sev`/`fev` arrays built below line up 1:1.
        let mut scoring: Vec<&ScoredLeaf> = Vec::new();
        let mut filters: Vec<&ScoredFilterLeaf> = Vec::new();
        let eval_root: Option<ClauseEval> = match plan {
            ScoredPlan::Composed { root } => {
                Some(build_clause_eval(root, &mut scoring, &mut filters))
            }
            ScoredPlan::Boosting {
                positive, negative, ..
            } => {
                scoring.push(positive);
                filters.push(negative);
                None
            }
            ScoredPlan::Pinned { organic, .. } => {
                scoring.push(organic);
                None
            }
            ScoredPlan::Filtered {
                filter, must_not, ..
            } => {
                filters.extend(filter.iter().chain(must_not.iter()));
                None
            }
            // KeywordFuzzy resolves its expansions from the dictionaries in
            // Phase 1 (`fuzzy_stats`) — no flat leaf/filter lists.
            ScoredPlan::KeywordFuzzy { .. } => None,
        };

        // ── Phase 1: per-segment columns + GLOBAL term stats ──────────────
        // idf uses the field's docCount as N; the null-free scoring-column
        // gate forces it to equal Σ segment doc_count (bench mapping has no
        // nulls, so this coincides with ES's field docCount).
        let mut seg_cols = Vec::with_capacity(segments.len());
        let mut seg_seqs: Vec<Resident<Vec<u64>>> = Vec::with_capacity(segments.len());
        let mut seg_ghosts: Vec<Option<Arc<Vec<u64>>>> = Vec::with_capacity(segments.len());
        for meta in segments {
            seg_cols.push(self.dv_columns_for(segments_dir, &meta.id)?);
            seg_seqs.push(self.row_seqs_for(meta.id.as_str(), meta.doc_count)?);
            seg_ghosts.push(if any_ghosts {
                let bm = self.ghost_positions_for(meta.id.as_str(), meta.doc_count)?;
                // All-zero bitmap (e.g. post-merge segments after the ghosts
                // were purged) → skip the per-row test for this segment.
                if bm.iter().any(|w| *w != 0) {
                    Some(bm)
                } else {
                    None
                }
            } else {
                None
            });
        }
        let mut total_docs: u64 = 0;
        let mut df: Vec<u64> = vec![0; scoring.len()];
        for (meta, cols) in segments.iter().zip(seg_cols.iter()) {
            total_docs += meta.doc_count;
            for (ci, leaf) in scoring.iter().enumerate() {
                match &leaf.kind {
                    ScoredLeafKind::Keyword(term) => {
                        let Some(Column::Keyword(k)) = cols.get(leaf.field.as_str()) else {
                            return None;
                        };
                        if k.doc_count as u64 != meta.doc_count || !k.null_bitmap.is_empty() {
                            return None;
                        }
                        if let Some(ord) = k.ord_for_term(term) {
                            df[ci] +=
                                k.per_ord_count.get(ord as usize).copied().unwrap_or(0) as u64;
                        }
                    }
                    ScoredLeafKind::BoolEq(v) => {
                        let Some(Column::Numeric(nc)) = cols.get(leaf.field.as_str()) else {
                            return None;
                        };
                        if nc.doc_count as u64 != meta.doc_count || !nc.null_bitmap.is_empty() {
                            return None;
                        }
                        // Physical df (ghost rows included — Lucene stats).
                        df[ci] += nc
                            .data
                            .iter()
                            .filter(|&&b| f64::from_bits(b as u64) == *v)
                            .count() as u64;
                    }
                    ScoredLeafKind::NumericEq(_) => {
                        // Constant-scored (no BM25 stats → no df needed), but
                        // the column must exist null-free for the row walk.
                        let Some(Column::Numeric(nc)) = cols.get(leaf.field.as_str()) else {
                            return None;
                        };
                        if nc.doc_count as u64 != meta.doc_count || !nc.null_bitmap.is_empty() {
                            return None;
                        }
                    }
                }
            }
            for fl in &filters {
                match fl {
                    ScoredFilterLeaf::KeywordTerm { field, .. }
                    | ScoredFilterLeaf::KeywordTerms { field, .. }
                    | ScoredFilterLeaf::KeywordPrefix { field, .. }
                    | ScoredFilterLeaf::KeywordWildcard { field, .. } => {
                        let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        if k.doc_count as u64 != meta.doc_count {
                            return None;
                        }
                    }
                    ScoredFilterLeaf::NumericWindow { field, .. } => {
                        let Some(Column::Numeric(n)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        if n.doc_count as u64 != meta.doc_count {
                            return None;
                        }
                    }
                    // No doc-values column, no stats: per-row presence is
                    // resolved from the stored slices in the walk below.
                    ScoredFilterLeaf::SourceExists { .. } => {}
                }
            }
        }
        // ── KeywordFuzzy global expansion stats (LOSS_BATTLE_PLAN B4) ────
        // term → (folded Damerau dist, Σ df) over ALL segments'
        // dictionaries, plus the blended df (max Σdf across expansions —
        // ES TopTermsBlendedFreqScoringRewrite).  The match predicate
        // mirrors `xerj_fts::search::expand_fuzzy` / the doc-scan fuzzy
        // arm EXACTLY: whole-value edit distance always, plus the
        // sub-token fallback ONLY when folding (case_insensitive) — the
        // case-sensitive keyword default is whole-term-only on every path
        // (#423/#406). Sub-token-only matches (an intentional xerj
        // leniency ES lacks, fold path only) can carry a whole-value
        // dist > max_edits; their sim clamps to ≥ 0 so the extra hits
        // score deterministically.
        let fuzzy_stats: Option<(HashMap<String, (usize, u64)>, u64)> = match plan {
            ScoredPlan::KeywordFuzzy {
                field,
                value,
                max_edits,
                case_insensitive,
                prefix_length,
                ..
            } => {
                // #423/#406: case-sensitive keyword fuzzy (the ES default)
                // compares the RAW term; case_insensitive folds both sides.
                let ci = *case_insensitive;
                let pl = *prefix_length;
                let q_ref = if ci {
                    value.to_lowercase()
                } else {
                    value.clone()
                };
                let term_matches = |cmp: &str| -> bool {
                    if fuzzy_prefix_ok(cmp, &q_ref, pl)
                        && levenshtein_distance(cmp, &q_ref) <= *max_edits
                    {
                        return true;
                    }
                    // #423/#406: the sub-token fallback is a FOLD-path leniency
                    // ONLY. When case-sensitive (the ES keyword default), the
                    // memtable Fuzzy arm (`token_match`) and the FST
                    // `expand_fuzzy` both match the whole un-analysed term and
                    // nothing else — so this DV path must too, or a
                    // separator-containing keyword ("alpha-beta") answers a
                    // sub-token query ("beta") after flush but not before
                    // (flush-invariance; caught by the PR #675 correctness
                    // skeptic). The post-flush sub-token hit was also non-ES:
                    // keyword fuzzy compares the whole term.
                    if !ci {
                        return false;
                    }
                    cmp.split(|c: char| !c.is_alphanumeric())
                        .filter(|t| !t.is_empty())
                        .any(|tok| {
                            fuzzy_prefix_ok(tok, &q_ref, pl)
                                && levenshtein_distance(tok, &q_ref) <= *max_edits
                        })
                };
                let mut map: HashMap<String, (usize, u64)> = HashMap::new();
                for (meta, cols) in segments.iter().zip(seg_cols.iter()) {
                    let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                        return None;
                    };
                    // Same null-free/coverage gate as the KeywordTerm
                    // scoring arm: a null row's ords entry is not
                    // meaningful, so nullable columns keep the brute path.
                    if k.doc_count as u64 != meta.doc_count || !k.null_bitmap.is_empty() {
                        return None;
                    }
                    for (ord, term) in k.terms.iter().enumerate() {
                        let cmp = if ci {
                            term.to_lowercase()
                        } else {
                            term.clone()
                        };
                        if term_matches(&cmp) {
                            let seg_df = k.per_ord_count.get(ord).copied().unwrap_or(0) as u64;
                            let dist = levenshtein_distance(&cmp, &q_ref);
                            let e = map.entry(term.clone()).or_insert((dist, 0));
                            e.1 += seg_df;
                        }
                    }
                }
                let blend = map.values().map(|(_, n)| *n).max().unwrap_or(0);
                Some((map, blend))
            }
            _ => None,
        };

        // Per-clause score constant: exact ES float32 BM25 op sequence for
        // keyword/boolean terms (a clause whose term is absent everywhere —
        // df = 0 — never matches a row, so its unused value is irrelevant);
        // numeric terms score the composed boost directly (ES points carry
        // no BM25 stats — constant-score weight).
        let clause_scores: Vec<f32> = df
            .iter()
            .zip(scoring.iter())
            .map(|(&n, leaf)| match &leaf.kind {
                ScoredLeafKind::Keyword(_) | ScoredLeafKind::BoolEq(_) => {
                    bm25_keyword_term_score(n, total_docs, leaf.boost)
                }
                ScoredLeafKind::NumericEq(_) => leaf.boost,
            })
            .collect();

        // ── tth early termination (LOSS_BATTLE_PLAN B5) ───────────────────
        // ES's TOP_SCORES collector stops counting once the capped total is
        // exceeded and the top-k can no longer change; xerj walked every row
        // to tally an exact total the renderer then capped to (limit, gte)
        // anyway.  `break_bound` is a static UPPER bound on any row's score
        // (per-plan; None disables).  The walk may stop when ALL hold:
        //   total > limit          (strict — renderer emits (limit, gte)),
        //   heap full at keep_target,
        //   worst-kept score ≥ bound as f64  (no remaining row can beat it),
        //   walk seq-ascending + current seq ≥ worst seq and every later
        //   segment's min_seq_no > worst seq  (equal-score ties break by
        //   seq ASC, so later rows can't displace the kept set either).
        // Boosting (negative_boost can exceed 1) and Pinned (phase-4
        // overlay needs full headroom) never break.
        // A BM25 clause whose term is absent everywhere (df = 0) never
        // matches a row, but its unused clause_scores entry is the HUGE
        // idf-of-nothing constant — it must contribute 0 to the bound or
        // the bound is never reachable (live: multi_match's dead top_doc
        // clause pushed the bound to ~27 and disabled the break).
        // NumericEq leaves carry no df; their boost score stands.
        fn clause_eval_max(
            ev: &ClauseEval,
            clause_scores: &[f32],
            df: &[u64],
            scoring: &[&ScoredLeaf],
        ) -> f64 {
            match ev {
                ClauseEval::Leaf(i) => match &scoring[*i].kind {
                    ScoredLeafKind::Keyword(_) | ScoredLeafKind::BoolEq(_) if df[*i] == 0 => 0.0,
                    _ => clause_scores[*i] as f64,
                },
                ClauseEval::Bool { must, should, .. } => {
                    must.iter()
                        .map(|c| clause_eval_max(c, clause_scores, df, scoring))
                        .sum::<f64>()
                        + should
                            .iter()
                            .map(|c| clause_eval_max(c, clause_scores, df, scoring))
                            .sum::<f64>()
                }
                ClauseEval::DisMax { children, tie } => {
                    let maxes: Vec<f64> = children
                        .iter()
                        .map(|c| clause_eval_max(c, clause_scores, df, scoring))
                        .collect();
                    let m = maxes.iter().cloned().fold(0.0_f64, f64::max);
                    let sum: f64 = maxes.iter().sum();
                    m + *tie * (sum - m)
                }
            }
        }
        let break_bound: Option<f64> = match (total_limit, plan) {
            (Some(_), ScoredPlan::Filtered { score, .. }) => Some(*score as f64),
            (Some(_), ScoredPlan::KeywordFuzzy { boost, .. }) => fuzzy_stats
                .as_ref()
                .map(|(_, blend)| bm25_keyword_term_score(*blend, total_docs, *boost) as f64),
            (Some(_), ScoredPlan::Composed { .. }) => eval_root
                .as_ref()
                .map(|r| clause_eval_max(r, &clause_scores, &df, &scoring)),
            _ => None,
        };

        // ── Phase 2: row walk — exact per-row score + exact total ─────────
        // Candidate = (score, seq_no, segment, row); seq_no is the ES-parity
        // tie-break key, (segment, row) locates the stored slice.
        //
        // P1 bounded top-k: instead of pushing EVERY match into an unbounded
        // Vec and `select_nth`-ing the lot (the profiled tuple-storm: ~98k
        // pushes + a 100k-element select for `term(status)`), keep only the
        // `keep_target` best under `(score DESC, seq_no ASC)` in a size-capped
        // heap. `total` is still tallied over every match (exact, ghost-aware)
        // — only the MATERIALISED set is bounded. Pinned keeps the full `cap`
        // headroom its phase-4 overlay needs; every other exact plan keeps
        // exactly the `from+size` page (drops the 256-doc hydration floor).
        let keep_target: usize = if matches!(plan, ScoredPlan::Pinned { .. }) {
            cap
        } else {
            page.min(cap)
        };
        let mut heap: std::collections::BinaryHeap<TopKCand> =
            std::collections::BinaryHeap::with_capacity(keep_target.saturating_add(1));
        let mut total: u64 = 0;
        let limit_val: u64 = total_limit.unwrap_or(u64::MAX);

        // ── Closed-form totals for CONSTANT-score plans (floor batch) ─────
        // For a plan whose every hit scores the same constant — Filtered
        // (≤1 filter, no must_not) and single-leaf Composed (the bare
        // term/match wrap) — the exact total is pure column arithmetic:
        // Σ per_ord_count over the resolved keyword ordinals, or a
        // partition_point pair over the numeric sorted index.  The row walk
        // then only has to FILL THE PAGE: with all scores tying and a
        // seq-ascending walk, the first keep_target matches ARE the k-best
        // set the heap would keep.  This replaces walking ~2.3× the tth
        // limit to count matches row by row — live-profiled at ~0.35ms of
        // pure eval on `term` at 43% selectivity, the whole residual floor
        // gap vs ES.  Gates: no ghosts (per_ord_count / sorted are
        // live-only = physical exactly there), seq-ascending rows, single-
        // filter conjunctions.  KeywordFuzzy scores VARY per expansion
        // ordinal — excluded (its heap must see every match).
        // For Composed plans: the single LIVE scoring-leaf index (into
        // sev/clause_scores) when the whole tree provably reduces to one
        // constant-scored leaf.  Read off the EVAL tree (indices are
        // authoritative there):
        // * Bool with exactly one must-Leaf and nothing else — the bare
        //   term/match wrap.
        // * DisMax whose children are all Leaves with EXACTLY ONE carrying
        //   global df > 0 — a df=0 clause matches no row anywhere, so every
        //   matching row scores just the live clause's constant (max = the
        //   only match; tie·Σrest = 0).  This is the benchmark's dis_max /
        //   multi_match shape, where one alternative term/field is simply
        //   absent from the corpus.
        let composed_constant_leaf: Option<usize> = if any_ghosts {
            None
        } else {
            match (plan, &eval_root) {
                (
                    ScoredPlan::Composed { .. },
                    Some(ClauseEval::Bool {
                        must,
                        should,
                        filter,
                        must_not,
                        ..
                    }),
                ) if must.len() == 1
                    && should.is_empty()
                    && filter.is_empty()
                    && must_not.is_empty() =>
                {
                    match must[0] {
                        ClauseEval::Leaf(i) => Some(i),
                        _ => None,
                    }
                }
                // Pure-should single leaf (the simple_query_string /
                // lone-should lowering): default minimum_should_match for a
                // must-less bool is 1, so the match set and the score are
                // exactly the leaf's — identical semantics to the must wrap.
                (
                    ScoredPlan::Composed { .. },
                    Some(ClauseEval::Bool {
                        must,
                        should,
                        filter,
                        must_not,
                        required_should,
                        ..
                    }),
                ) if must.is_empty()
                    && should.len() == 1
                    && *required_should <= 1
                    && filter.is_empty()
                    && must_not.is_empty() =>
                {
                    match should[0] {
                        ClauseEval::Leaf(i) => Some(i),
                        _ => None,
                    }
                }
                (ScoredPlan::Composed { .. }, Some(ClauseEval::DisMax { children, .. })) => {
                    let mut live: Option<usize> = None;
                    let mut ok = true;
                    for c in children {
                        match c {
                            ClauseEval::Leaf(i) => {
                                if df[*i] > 0 {
                                    if live.is_some() {
                                        ok = false; // 2+ live clauses → walk
                                        break;
                                    }
                                    live = Some(*i);
                                }
                            }
                            _ => {
                                ok = false;
                                break;
                            }
                        }
                    }
                    if ok {
                        live
                    } else {
                        None
                    }
                }
                _ => None,
            }
        };
        let constant_plan: bool = !any_ghosts
            // Source-backed `exists` leaves have no closed-form count —
            // their per-segment total is only knowable row by row.
            && !filters
                .iter()
                .any(|f| matches!(f, ScoredFilterLeaf::SourceExists { .. }))
            && match plan {
                ScoredPlan::Filtered {
                    filter, must_not, ..
                } => must_not.is_empty() && filter.len() <= 1,
                ScoredPlan::Composed { .. } => composed_constant_leaf.is_some(),
                _ => false,
            };

        // Flat all-constant CONJUNCTION (query_string `a:x AND b:y`, bool
        // must[+filter/must_not] of constant leaves, no should): every
        // matching row scores the SAME f32(Σ f64 must-constants) — the
        // Bool group's one-cast rounding for a fixed match set.  The exact
        // total still needs the walk (conjunction counts aren't
        // closed-form), but a flat short-circuit loop over the ord/window
        // tests replaces the per-row tree recursion, leaves ordered
        // rarest-df-first, and hit-pushing stops once the page is full.
        let flat_conjunction: Option<(
            Vec<usize>,
            std::ops::Range<usize>,
            std::ops::Range<usize>,
            f32,
        )> = if any_ghosts || composed_constant_leaf.is_some() {
            None
        } else {
            match (plan, &eval_root) {
                (
                    ScoredPlan::Composed { .. },
                    Some(ClauseEval::Bool {
                        must,
                        should,
                        filter,
                        must_not,
                        ..
                    }),
                ) if !must.is_empty() && should.is_empty() => {
                    let mut idx = Vec::with_capacity(must.len());
                    let mut ok = true;
                    for c in must {
                        match c {
                            ClauseEval::Leaf(i) => idx.push(*i),
                            _ => {
                                ok = false;
                                break;
                            }
                        }
                    }
                    if ok {
                        let s = idx.iter().map(|&i| clause_scores[i] as f64).sum::<f64>() as f32;
                        idx.sort_by_key(|&i| df[i]); // rarest first → earliest short-circuit
                        Some((idx, filter.clone(), must_not.clone(), s))
                    } else {
                        None
                    }
                }
                _ => None,
            }
        };

        // Flat MUST+ONE-SHOULD bool (the benchmark's 4-clause shape): with
        // all-leaf constant clauses the per-row score is TWO-VALUED —
        // hi = f32(Σmust + should) when the should matches, lo = f32(Σmust)
        // otherwise (each the Bool group's one-cast rounding for its fixed
        // match set).  One flat pass counts the exact total and keeps the
        // first keep_target rows of EACH value class (seq-asc ⇒ those are
        // the classes' k-best); the global heap then merges hi before lo.
        let flat_bool2: Option<(
            Vec<usize>,
            usize,
            std::ops::Range<usize>,
            std::ops::Range<usize>,
            f32,
            f32,
        )> = if any_ghosts || composed_constant_leaf.is_some() || flat_conjunction.is_some() {
            None
        } else {
            match (plan, &eval_root) {
                (
                    ScoredPlan::Composed { .. },
                    Some(ClauseEval::Bool {
                        must,
                        should,
                        filter,
                        must_not,
                        required_should,
                        ..
                    }),
                ) if !must.is_empty() && should.len() == 1 && *required_should == 0 => {
                    let mut idx = Vec::with_capacity(must.len());
                    let mut ok = true;
                    for c in must {
                        match c {
                            ClauseEval::Leaf(i) => idx.push(*i),
                            _ => {
                                ok = false;
                                break;
                            }
                        }
                    }
                    let sh = match should[0] {
                        ClauseEval::Leaf(i) => Some(i),
                        _ => None,
                    };
                    match (ok, sh) {
                        (true, Some(sh)) => {
                            let base: f64 = idx.iter().map(|&i| clause_scores[i] as f64).sum();
                            let lo = base as f32;
                            let hi = (base + clause_scores[sh] as f64) as f32;
                            idx.sort_by_key(|&i| df[i]);
                            Some((idx, sh, filter.clone(), must_not.clone(), hi, lo))
                        }
                        _ => None,
                    }
                }
                _ => None,
            }
        };

        for (si, (meta, cols)) in segments.iter().zip(seg_cols.iter()).enumerate() {
            let seqs: &[u64] = &seg_seqs[si];
            // B5 break / constant-lane preconditions (only paid when one of
            // them can fire): seq-ascending walk (true by construction for
            // B1 merge-sorted segments; verified, not assumed) + the
            // smallest seq any LATER segment can contribute.  NOTE the
            // constant-plan closed-form lane needs this under
            // track_total_hits:true too (break_bound is None there — the
            // official bench convention injects tth:true into every read).
            let seq_asc = (break_bound.is_some()
                || constant_plan
                || flat_conjunction.is_some()
                || flat_bool2.is_some()
                || matches!(plan, ScoredPlan::Pinned { .. }))
                && seqs.windows(2).all(|w| w[0] <= w[1]);
            let later_min_seq: u64 = segments[si + 1..]
                .iter()
                .map(|m| m.min_seq_no)
                .min()
                .unwrap_or(u64::MAX);
            let si = si as u32;
            let mut sev: Vec<ScoreEval> = Vec::with_capacity(scoring.len());
            for leaf in &scoring {
                match &leaf.kind {
                    ScoredLeafKind::Keyword(term) => {
                        let Some(Column::Keyword(k)) = cols.get(leaf.field.as_str()) else {
                            return None;
                        };
                        sev.push(ScoreEval::Kw {
                            col: k,
                            ord: k.ord_for_term(term),
                        });
                    }
                    ScoredLeafKind::BoolEq(v) | ScoredLeafKind::NumericEq(v) => {
                        let Some(Column::Numeric(nc)) = cols.get(leaf.field.as_str()) else {
                            return None;
                        };
                        sev.push(ScoreEval::Bool { col: nc, val: *v });
                    }
                }
            }
            let mut fev: Vec<FilterEval> = Vec::with_capacity(filters.len());
            for fl in &filters {
                match fl {
                    ScoredFilterLeaf::KeywordTerm { field, term } => {
                        let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        fev.push(FilterEval::Kw {
                            col: k,
                            no_nulls: k.null_bitmap.is_empty(),
                            ords: k.ord_for_term(term).into_iter().collect(),
                        });
                    }
                    ScoredFilterLeaf::KeywordTerms { field, terms } => {
                        let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        let mut ords: Vec<u32> =
                            terms.iter().filter_map(|t| k.ord_for_term(t)).collect();
                        ords.sort_unstable();
                        ords.dedup();
                        fev.push(FilterEval::Kw {
                            col: k,
                            no_nulls: k.null_bitmap.is_empty(),
                            ords,
                        });
                    }
                    ScoredFilterLeaf::KeywordPrefix { field, prefix } => {
                        let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        // `terms` is lexicographically sorted: the prefix's
                        // matches form the contiguous ordinal range
                        // [lo, hi) bounded by two partition_points.
                        let lo = k.terms.partition_point(|t| t.as_str() < prefix.as_str());
                        let hi =
                            lo + k.terms[lo..].partition_point(|t| t.starts_with(prefix.as_str()));
                        fev.push(FilterEval::Kw {
                            col: k,
                            no_nulls: k.null_bitmap.is_empty(),
                            ords: (lo as u32..hi as u32).collect(),
                        });
                    }
                    ScoredFilterLeaf::KeywordWildcard {
                        field,
                        pattern,
                        case_insensitive,
                    } => {
                        let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        // #668: honor the node's case flag — the SAME predicate
                        // the brute path (`doc_matches_query`) and the FST route
                        // now apply. `term{case_insensitive:true}` / query_string
                        // rewrites fold BOTH sides (whole-value OR sub-token); a
                        // standalone `{wildcard}` matches the RAW term
                        // case-sensitively (ES default). A folded pattern cannot
                        // bound a byte-ordered prefix range, so walk the whole
                        // (distinct-term) dictionary — same cost class as the FST.
                        let pat_lc = pattern.to_lowercase();
                        let ords: Vec<u32> = (0..k.terms.len())
                            .filter(|&o| {
                                if *case_insensitive {
                                    let lc = k.terms[o].to_lowercase();
                                    wildcard_match(&lc, &pat_lc)
                                        || lc.split(|c: char| !c.is_alphanumeric()).any(|tok| {
                                            !tok.is_empty() && wildcard_match(tok, &pat_lc)
                                        })
                                } else {
                                    wildcard_match(&k.terms[o], pattern.as_str())
                                }
                            })
                            .map(|o| o as u32)
                            .collect();
                        fev.push(FilterEval::Kw {
                            col: k,
                            no_nulls: k.null_bitmap.is_empty(),
                            ords,
                        });
                    }
                    ScoredFilterLeaf::NumericWindow {
                        field,
                        min,
                        max,
                        min_inc,
                        max_inc,
                    } => {
                        let Some(Column::Numeric(n)) = cols.get(field.as_str()) else {
                            return None;
                        };
                        fev.push(FilterEval::Num {
                            col: n,
                            no_nulls: n.null_bitmap.is_empty(),
                            min: *min,
                            max: *max,
                            min_inc: *min_inc,
                            max_inc: *max_inc,
                        });
                    }
                    ScoredFilterLeaf::SourceExists { field } => {
                        // A presence bitmap answers `exists` without parsing
                        // stored JSON. Segments written before the bitmap
                        // existed still fall through to the source slices.
                        if let Some(xerj_storage::doc_values::Column::Presence(p)) =
                            cols.get(field.as_str())
                        {
                            if p.doc_count == meta.doc_count as u32 {
                                fev.push(FilterEval::Presence { col: p });
                                continue;
                            }
                        }
                        // Cache-backed stored slices for this segment; the
                        // `?` bails the whole columnar path (brute answers).
                        let slices = self.stored_slices_for(meta.id.as_str(), meta.doc_count)?;
                        fev.push(FilterEval::Source {
                            field: field.clone(),
                            slices,
                        });
                    }
                }
            }
            let doc_count = meta.doc_count as u32;
            // Liveness test (only segments with ≥1 ghost row pay it).
            let ghost_bm: Option<&[u64]> = seg_ghosts[si as usize].as_deref().map(|v| &v[..]);
            let is_ghost = |row: u32| -> bool {
                match ghost_bm {
                    Some(bm) => (bm[(row / 64) as usize] >> (row % 64)) & 1 == 1,
                    None => false,
                }
            };
            match plan {
                ScoredPlan::Composed { .. } => {
                    // Scoring bool/dis_max tree: recursive per-row eval that
                    // replicates the Lucene scorer tree's rounding exactly
                    // (per-node f64 accumulation with ONE f32 cast per
                    // conjunction/disjunction group, f32 req+opt combine —
                    // see `ScoredClause`).
                    let root = eval_root
                        .as_ref()
                        .expect("Composed plan always builds an eval tree");
                    if let (true, Some((leaves, sh, f_rng, mn_rng, hi, lo))) =
                        (seq_asc, &flat_bool2)
                    {
                        // Flat must+one-should walk (see `flat_bool2`).
                        let mut kept_hi = 0usize;
                        let mut kept_lo = 0usize;
                        'brows: for row in 0..doc_count {
                            for &li in leaves {
                                if !sev[li].matches(row) {
                                    continue 'brows;
                                }
                            }
                            for fi in f_rng.clone() {
                                if !fev[fi].matches(row) {
                                    continue 'brows;
                                }
                            }
                            for fi in mn_rng.clone() {
                                if fev[fi].matches(row) {
                                    continue 'brows;
                                }
                            }
                            total += 1;
                            // Count-only (size:0 → keep_target 0): the
                            // score-class check exists only to fill the
                            // two-valued page — skip it; under a tth cap
                            // stop once (limit, gte) is guaranteed.
                            if keep_target == 0 {
                                if total > limit_val {
                                    break 'brows;
                                }
                                continue 'brows;
                            }
                            let (score, kept) = if sev[*sh].matches(row) {
                                (*hi, &mut kept_hi)
                            } else {
                                (*lo, &mut kept_lo)
                            };
                            if *kept < keep_target {
                                push_topk(
                                    &mut heap,
                                    keep_target,
                                    TopKCand {
                                        score,
                                        seq: seqs[row as usize],
                                        si,
                                        row,
                                    },
                                );
                                *kept += 1;
                            } else if kept_hi >= keep_target
                                && kept_lo >= keep_target
                                && total > limit_val
                            {
                                break 'brows;
                            }
                        }
                        continue;
                    }
                    if let (true, Some((leaves, f_rng, mn_rng, cscore))) =
                        (seq_asc, &flat_conjunction)
                    {
                        // Flat conjunction walk (see `flat_conjunction`).
                        let mut kept = 0usize;
                        'crows: for row in 0..doc_count {
                            for &li in leaves {
                                if !sev[li].matches(row) {
                                    continue 'crows;
                                }
                            }
                            for fi in f_rng.clone() {
                                if !fev[fi].matches(row) {
                                    continue 'crows;
                                }
                            }
                            for fi in mn_rng.clone() {
                                if fev[fi].matches(row) {
                                    continue 'crows;
                                }
                            }
                            total += 1;
                            if kept < keep_target {
                                push_topk(
                                    &mut heap,
                                    keep_target,
                                    TopKCand {
                                        score: *cscore,
                                        seq: seqs[row as usize],
                                        si,
                                        row,
                                    },
                                );
                                kept += 1;
                            } else if total > limit_val {
                                // (tth Limit only) page full + count strictly
                                // past the cap: the renderer emits
                                // (limit, gte) either way, this segment
                                // already contributed its k best (constant
                                // scores, seq-asc), and later segments still
                                // walk for their own contributions.
                                break 'crows;
                            }
                        }
                        continue;
                    }
                    if let (true, true, Some(li)) = (constant_plan, seq_asc, composed_constant_leaf)
                    {
                        // Constant-plan fast lane (see `constant_plan` /
                        // `composed_constant_leaf`): closed-form total from
                        // the single live leaf, walk only until this
                        // segment has contributed its first keep_target
                        // matches — which, all scores tying and rows
                        // seq-ascending, ARE its k-best contribution to
                        // the global heap.
                        total += sev[li].count();
                        let mut kept = 0usize;
                        for row in 0..doc_count {
                            if !sev[li].matches(row) {
                                continue;
                            }
                            push_topk(
                                &mut heap,
                                keep_target,
                                TopKCand {
                                    score: clause_scores[li],
                                    seq: seqs[row as usize],
                                    si,
                                    row,
                                },
                            );
                            kept += 1;
                            if kept >= keep_target {
                                break;
                            }
                        }
                        continue;
                    }
                    for row in 0..doc_count {
                        if is_ghost(row) {
                            continue;
                        }
                        if let Some(score) = root.eval(row, &sev, &fev, &clause_scores) {
                            total += 1;
                            // Count-only (size:0): nothing to keep — under a
                            // tth cap stop once (limit, gte) is guaranteed.
                            if keep_target == 0 {
                                if total > limit_val {
                                    break;
                                }
                                continue;
                            }
                            push_topk(
                                &mut heap,
                                keep_target,
                                TopKCand {
                                    score,
                                    seq: seqs[row as usize],
                                    si,
                                    row,
                                },
                            );
                            // B5 tth break — see `break_bound`.  Checked
                            // every 64th match to keep the hot loop lean.
                            if let Some(bound) = break_bound {
                                if total & 63 == 0
                                    && seq_asc
                                    && total > limit_val
                                    && heap.len() == keep_target
                                {
                                    if let Some(w) = heap.peek() {
                                        if (w.score as f64) >= bound
                                            && seqs[row as usize] >= w.seq
                                            && later_min_seq > w.seq
                                        {
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                ScoredPlan::Boosting { negative_boost, .. } => {
                    // Docs matching only the negative do NOT match at all;
                    // negative-matching positives take a plain f32 multiply
                    // (verified bit-exact vs ES `_explain` "product of:").
                    let ps = clause_scores[0];
                    let (pos, neg) = (&sev[0], &fev[0]);
                    for row in 0..doc_count {
                        if is_ghost(row) || !pos.matches(row) {
                            continue;
                        }
                        total += 1;
                        // Count-only (size:0): membership is positive-only —
                        // the negative rescale can't change the count.
                        if keep_target == 0 {
                            if total > limit_val {
                                break;
                            }
                            continue;
                        }
                        let score = if neg.matches(row) {
                            ps * *negative_boost
                        } else {
                            ps
                        };
                        push_topk(
                            &mut heap,
                            keep_target,
                            TopKCand {
                                score,
                                seq: seqs[row as usize],
                                si,
                                row,
                            },
                        );
                    }
                }
                ScoredPlan::Pinned { .. } => {
                    // Organic rows only; pins are overlaid in phase 4.
                    let org = &sev[0];
                    let s = clause_scores[0];
                    if seq_asc {
                        // Constant-organic fast lane (mirror of the
                        // `constant_plan` lane): Pinned bails on entry
                        // whenever any ghost event was recorded, so the
                        // closed-form column count IS the exact live
                        // total, and — every organic hit scoring the same
                        // per-term constant with rows seq-ascending — the
                        // first keep_target matches ARE this segment's
                        // k-best contribution (identical to what the
                        // full-walk heap kept: the seq-smallest cap
                        // matches). Phase 4 re-scores/adds pins with its
                        // own independent organic-match test on the
                        // columns, so stopping the walk early never
                        // loses a pin. Replaces the profiled 100k-row
                        // walk + ~98.7k heap pushes for a 10-doc page.
                        let seg_matches = org.count();
                        total += seg_matches;
                        if seg_matches > 0 {
                            let mut kept = 0usize;
                            for row in 0..doc_count {
                                if !org.matches(row) {
                                    continue;
                                }
                                push_topk(
                                    &mut heap,
                                    keep_target,
                                    TopKCand {
                                        score: s,
                                        seq: seqs[row as usize],
                                        si,
                                        row,
                                    },
                                );
                                kept += 1;
                                if kept >= keep_target {
                                    break;
                                }
                            }
                        }
                        continue;
                    }
                    for row in 0..doc_count {
                        if is_ghost(row) {
                            continue;
                        }
                        if org.matches(row) {
                            total += 1;
                            push_topk(
                                &mut heap,
                                keep_target,
                                TopKCand {
                                    score: s,
                                    seq: seqs[row as usize],
                                    si,
                                    row,
                                },
                            );
                        }
                    }
                }
                ScoredPlan::Filtered { score, filter, .. } => {
                    if constant_plan && seq_asc {
                        // Constant-plan fast lane (see `constant_plan`):
                        // closed-form total (empty filter == every live
                        // row), walk only to fill this segment's page
                        // contribution.
                        total += match fev.first() {
                            Some(ev) => ev.count(),
                            None => meta.doc_count,
                        };
                        let mut kept = 0usize;
                        for row in 0..doc_count {
                            if let Some(ev) = fev.first() {
                                if !ev.matches(row) {
                                    continue;
                                }
                            }
                            push_topk(
                                &mut heap,
                                keep_target,
                                TopKCand {
                                    score: *score,
                                    seq: seqs[row as usize],
                                    si,
                                    row,
                                },
                            );
                            kept += 1;
                            if kept >= keep_target {
                                break;
                            }
                        }
                        continue;
                    }
                    // Pure filter context: every live row matching all
                    // `filter` and no `must_not` scores the CONSTANT
                    // (constant_score → boost; filter-only bool → 0.0).
                    let n_filter = filter.len();
                    'frows: for row in 0..doc_count {
                        if is_ghost(row) {
                            continue 'frows;
                        }
                        for (fi, ev) in fev.iter().enumerate() {
                            let m = ev.matches(row);
                            if fi < n_filter {
                                if !m {
                                    continue 'frows;
                                }
                            } else if m {
                                continue 'frows;
                            }
                        }
                        total += 1;
                        // Count-only (size:0): nothing to keep — under a
                        // tth cap stop once (limit, gte) is guaranteed.
                        if keep_target == 0 {
                            if total > limit_val {
                                break 'frows;
                            }
                            continue 'frows;
                        }
                        push_topk(
                            &mut heap,
                            keep_target,
                            TopKCand {
                                score: *score,
                                seq: seqs[row as usize],
                                si,
                                row,
                            },
                        );
                        // B5 tth break — see `break_bound`.  Checked
                        // every 64th match to keep the hot loop lean.
                        if let Some(bound) = break_bound {
                            if total & 63 == 0
                                && seq_asc
                                && total > limit_val
                                && heap.len() == keep_target
                            {
                                if let Some(w) = heap.peek() {
                                    if (w.score as f64) >= bound
                                        && seqs[row as usize] >= w.seq
                                        && later_min_seq > w.seq
                                    {
                                        break 'frows;
                                    }
                                }
                            }
                        }
                    }
                }
                ScoredPlan::KeywordFuzzy {
                    field,
                    value,
                    boost,
                    ..
                } => {
                    // Per-ord score LUT for THIS segment's dictionary:
                    // matching ords score bm25(df_blend, N, boost·sim),
                    // everything else is a non-match sentinel (NaN).  The
                    // column is null-free (Phase-1 gate), so `ords[row]`
                    // is meaningful for every live row.
                    let Some(Column::Keyword(k)) = cols.get(field.as_str()) else {
                        return None;
                    };
                    let (fmap, blend) = fuzzy_stats
                        .as_ref()
                        .expect("KeywordFuzzy always builds fuzzy_stats");
                    let q_cp = value.chars().count();
                    let mut ord_scores: Vec<f32> = vec![f32::NAN; k.terms.len()];
                    for (ord, term) in k.terms.iter().enumerate() {
                        if let Some((dist, _)) = fmap.get(term) {
                            // FuzzyTermsEnum: 1 − dist/min(cpLen); exact
                            // match keeps 1.0.  Clamp at 0 for the
                            // sub-token-only extras (see fuzzy_stats).
                            let sim: f32 = if *dist == 0 {
                                1.0
                            } else {
                                let ml = q_cp.min(term.chars().count()).max(1);
                                (1.0 - (*dist as f32) / (ml as f32)).max(0.0)
                            };
                            ord_scores[ord] =
                                bm25_keyword_term_score(*blend, total_docs, boost * sim);
                        }
                    }
                    for row in 0..doc_count {
                        if is_ghost(row) {
                            continue;
                        }
                        let s = ord_scores[k.ords[row as usize] as usize];
                        if s.is_nan() {
                            continue;
                        }
                        total += 1;
                        // Count-only (size:0): nothing to keep — under a
                        // tth cap stop once (limit, gte) is guaranteed.
                        if keep_target == 0 {
                            if total > limit_val {
                                break;
                            }
                            continue;
                        }
                        push_topk(
                            &mut heap,
                            keep_target,
                            TopKCand {
                                score: s,
                                seq: seqs[row as usize],
                                si,
                                row,
                            },
                        );
                        // B5 tth break — see `break_bound`.  Checked
                        // every 64th match to keep the hot loop lean.
                        if let Some(bound) = break_bound {
                            if total & 63 == 0
                                && seq_asc
                                && total > limit_val
                                && heap.len() == keep_target
                            {
                                if let Some(w) = heap.peek() {
                                    if (w.score as f64) >= bound
                                        && seqs[row as usize] >= w.seq
                                        && later_min_seq > w.seq
                                    {
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // ── Phase 3: drain the bounded top-k ──────────────────────────────
        // The heap already holds exactly the `keep_target` best under the
        // TOTAL order `(score DESC, seq_no ASC)` (live seq_nos are unique
        // under the caller's `!deletes_present` gate), so this SET is exactly
        // ES's: arrival order == Lucene `_doc` order — the same kept set the
        // former `select_nth_unstable_by(keep-1)` produced, without the
        // 98k-tuple storm. Heap order is arbitrary; the final page order is
        // re-derived by the caller's `(score desc, seq_no asc)` sort (or
        // phase-4's `cmp` for pinned), so we leave it unsorted here.
        let cmp = |a: &(f32, u64, u32, u32), b: &(f32, u64, u32, u32)| {
            b.0.partial_cmp(&a.0)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.1.cmp(&b.1))
        };
        let mut cands: Vec<(f32, u64, u32, u32)> = heap
            .into_iter()
            .map(|c| (c.score, c.seq, c.si, c.row))
            .collect();

        // ── Phase 4: pinned overlay ───────────────────────────────────────
        // A pinned doc at 0-based position `i` of the P-length ids array
        // gets the CONSTANT score bits `0x7F00_0001 + (P − i)` (base
        // Float.MAX_VALUE/2; verified against ES for P = 1..4). Positions
        // count over the FULL ids array including ids that don't exist; a
        // missing id simply produces no hit. Pinned ids that exist are
        // ALWAYS hits — organic non-matches join the result (total += 1),
        // organic matches are re-scored in place (total unchanged).
        if let ScoredPlan::Pinned { ids, organic } = plan {
            if ids.len() > cap {
                return None;
            }
            let p = ids.len() as u32;
            let mut maps = Vec::with_capacity(segments.len());
            for meta in segments {
                maps.push(self.id_pos_map_for(meta.id.as_str(), meta.doc_count)?);
            }
            for (i, id) in ids.iter().enumerate() {
                let mut found: Option<(u32, u32)> = None;
                for (si, map) in maps.iter().enumerate() {
                    if let Some(&pos) = map.get(id) {
                        found = Some((si as u32, pos));
                        break;
                    }
                }
                let Some((si, row)) = found else {
                    continue; // id not in the index → no hit, no shift
                };
                let pin_score = f32::from_bits(0x7F00_0001_u32 + (p - i as u32));
                if let Some(c) = cands.iter_mut().find(|c| c.2 == si && c.3 == row) {
                    // Organic match that survived selection → re-score.
                    c.0 = pin_score;
                } else {
                    // Either an organic match truncated out of the top-`cap`
                    // (already counted in `total`) or a pure pin (count it).
                    let organic_matched = match &organic.kind {
                        ScoredLeafKind::Keyword(term) => {
                            let Some(Column::Keyword(k)) =
                                seg_cols[si as usize].get(organic.field.as_str())
                            else {
                                return None;
                            };
                            k.ord_for_term(term)
                                .is_some_and(|o| k.ords[row as usize] == o)
                        }
                        ScoredLeafKind::BoolEq(v) | ScoredLeafKind::NumericEq(v) => {
                            let Some(Column::Numeric(nc)) =
                                seg_cols[si as usize].get(organic.field.as_str())
                            else {
                                return None;
                            };
                            f64::from_bits(nc.data[row as usize] as u64) == *v
                        }
                    };
                    if !organic_matched {
                        total += 1;
                    }
                    cands.push((pin_score, seg_seqs[si as usize][row as usize], si, row));
                }
            }
            // Pins outscore everything finite — re-rank + re-truncate.
            cands.sort_unstable_by(cmp);
            cands.truncate(cap);
        }

        // ── Page-offset hydration (deep `from` — LOSS_BATTLE_PLAN B7b) ────
        // For CONSTANT-score plans the caller's final (score DESC, seq ASC)
        // sort + `skip(from)` can be applied HERE on the un-hydrated
        // candidate tuples, so only the `size`-doc page pays the
        // stored-slice parse (from:500/size:50 previously hydrated all
        // 550).  Constant scores keep max_score safe (every hit ties, so
        // dropping the head changes nothing); non-constant plans keep full
        // hydration — their max_score derives from the best hit, which
        // `skip(from)` would drop.  The caller is told `from` was applied
        // and skips 0 (returned flag).
        let from_applied = page_from > 0 && matches!(plan, ScoredPlan::Filtered { .. });
        if from_applied {
            cands.sort_unstable_by(cmp);
            let cut = page_from.min(cands.len());
            cands.drain(..cut);
        }

        // ── Phase 5: hydrate winners via F2 offset slices ─────────────────
        // Identical to `function_score_columnar` hydration, except each hit
        // carries its COMPUTED score (there is no post-loop re-applier for
        // these shapes; the caller's score sort finalises the order).
        let mut hits: Vec<Hit> = Vec::with_capacity(cands.len());
        let mut seen: HashSet<String> = HashSet::with_capacity(cands.len());
        for (score, _seq, si, row) in cands {
            let meta = &segments[si as usize];
            let slices = self.stored_slices_for(meta.id.as_str(), meta.doc_count)?;
            let &(start, end) = slices.offsets.get(row as usize)?;
            let slice = slices.bytes.get(start as usize..end as usize)?;
            let doc: Value = serde_json::from_slice(slice).ok()?;
            let id = doc
                .get("_id")
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string();
            if id.is_empty() || !seen.insert(id.clone()) {
                continue;
            }
            let source = doc.get("_source").cloned().unwrap_or(doc);
            // Same read `source` was just parsed from — not a later pass
            // (#440). Not `_seq` (discarded above): that's the pre-hydration
            // ranking key from `seg_seqs`, a different number from the
            // ES-wire `_seq_no`/`_version` this resolves.
            let (seq_no, version) = self
                .store
                .version_map
                .get(&id)
                .map(|ver| self.hit_seq_version(&id, &ver))
                .unwrap_or((None, None));
            hits.push(Hit {
                id,
                score,
                source,
                seq_no,
                version,
                sort: Vec::new(),
                explain: None,
                highlight: None,
                matched_queries: Vec::new(),
                passage: None,
            });
        }
        Some((hits, total, from_applied))
    }

    /// Stored sections this index currently holds decoded: the decompressed
    /// byte cache, the per-doc slice cache, and the parsed-document cache.
    /// A presence-backed `exists` leaves all three untouched.
    pub fn stored_sections_cached(&self) -> usize {
        self.decoded_stored_cache.len()
            + self.stored_slices_cache.len()
            + self.stored_value_cache.len()
    }

    /// Cache-backed reader for a segment's parsed stored section.
    ///
    /// First call for a segment opens the segment, decodes the Stored
    /// section, and parses the result. Subsequent calls return an
    /// `Arc<Vec<Value>>` clone — no I/O, no decompress, no parse.
    /// Segments are immutable post-flush so the cache value remains
    /// valid until the segment is removed by a merge (at which point its
    /// precise entry is evicted under the lifecycle write guard).
    ///
    /// Uses `serde_json::from_slice` not `simd_json::serde::from_slice`:
    /// per ffd49ac, simd_json silently corrupts some payloads produced
    /// by the raw-bytes flush path (M7) — the deserialiser succeeds but
    /// returns malformed values. The KNN scan is the worst place to
    /// catch that. serde_json handles every variant correctly and the
    /// per-doc parse cost is amortised once across the whole cache
    /// lifetime of a segment.
    fn stored_values_for(&self, segment_id: &str) -> Option<Resident<Vec<Value>>> {
        if let Some(entry) = self.stored_value_cache.get(segment_id) {
            return Some(Arc::clone(entry.value()));
        }
        let reader = self.store.open_segment(segment_id).ok()?;
        let stored_bytes_raw = reader.section(SectionType::Stored).ok()??;
        let stored_bytes = xerj_storage::stored_codec::decode_stored(stored_bytes_raw).ok()?;
        let docs: Vec<Value> = serde_json::from_slice(&stored_bytes).ok()?;
        let key = segment_id.to_string();
        let bytes = cache_estimates::stored_values_bytes(
            &key,
            std::mem::size_of::<CacheResident<Vec<Value>>>(),
            &docs,
        );
        Some(self.publish_current(
            &self.stored_value_cache,
            segment_id,
            key,
            SegmentCacheCategory::StoredValues,
            bytes,
            docs,
        ))
    }

    /// Async boundary for a cold stored-value load.
    ///
    /// A cache miss opens and decompresses the segment and parses its complete
    /// stored section. That is synchronous file/CPU work and can take seconds
    /// for a large segment, so vector queries must not run it on a Tokio
    /// worker. Cache hits stay on the caller because they are only a DashMap
    /// lookup and `Arc` clone.
    ///
    /// The decode runs on the engine's own rayon maintenance pool, never on
    /// tokio's blocking pool: a search already parks a blocking-pool thread
    /// inside `block_in_place` for its whole duration, so queueing this work
    /// there is a circular wait (issue #751, and the rule stated on
    /// `await_publication_barrier`).
    ///
    /// The submitted decode is never cancelled. A timed-out or dropped request
    /// therefore leaves the load running to completion, which is useful: it
    /// warms the immutable segment for the next request. The segment-current
    /// check prevents such a detached completion from resurrecting a cache
    /// entry that a concurrent merge already retired.
    async fn stored_values_for_async(&self, segment_id: &str) -> Option<Resident<Vec<Value>>> {
        if let Some(entry) = self.stored_value_cache.get(segment_id) {
            return Some(Arc::clone(entry.value()));
        }

        let segment_id = segment_id.to_string();
        let mut receiver = {
            use dashmap::mapref::entry::Entry;
            match self.stored_value_loads.entry(segment_id.clone()) {
                Entry::Occupied(entry) => entry.get().subscribe(),
                Entry::Vacant(entry) => {
                    let (sender, receiver) = tokio::sync::watch::channel(None);
                    entry.insert(sender.clone());

                    let store = Arc::clone(&self.store);
                    let cache = Arc::clone(&self.stored_value_cache);
                    let lifecycle = Arc::clone(&self.segment_cache_lifecycle);
                    let budget = Arc::clone(&self.segment_hydration_budget);
                    let loads = Arc::clone(&self.stored_value_loads);
                    let load_semaphore = Arc::clone(&self.stored_value_load_semaphore);
                    let load_segment_id = segment_id.clone();
                    #[cfg(test)]
                    let load_delay_ms = Arc::clone(&self.test_stored_value_load_delay_ms);
                    #[cfg(test)]
                    let load_count = Arc::clone(&self.test_stored_value_load_count);
                    #[cfg(test)]
                    let pause_before_publish =
                        Arc::clone(&self.test_stored_value_load_pause_before_publish);
                    #[cfg(test)]
                    let ready_to_publish =
                        Arc::clone(&self.test_stored_value_load_ready_to_publish);
                    tokio::spawn(async move {
                        let Ok(permit) = load_semaphore.acquire_owned().await else {
                            loads.remove(&segment_id);
                            return;
                        };
                        // #751 — the decode runs on the engine's own rayon
                        // maintenance pool, NOT on tokio's blocking pool.
                        //
                        // `Index::search` wraps its whole body in
                        // `block_in_place(|| Handle::current().block_on(..))`
                        // on multi-thread runtimes (M5.21). `block_in_place`
                        // hands the worker's core to a tokio BLOCKING-pool
                        // thread — which then runs `worker::run` for the rest
                        // of the runtime's life — and parks the calling thread,
                        // itself a blocking-pool thread, for the whole search.
                        // An aggregation with no columnar path assembles the
                        // full corpus from inside that park, so a `spawn_blocking`
                        // here would queue work on the very pool the waiter is
                        // holding a thread of. tokio grows that pool only when
                        // it observes zero idle threads at push time, so the
                        // core hand-off and this submission can both see the
                        // same idle thread, both merely `notify_one()`, and the
                        // one woken thread takes the core and never comes back.
                        // The decode is then queued behind threads that are all
                        // permanently running worker cores: the search waits for
                        // a task that can never be scheduled. Live-reproduced as
                        // the CI hang in issue #751 (12-min step timeout, 12/60
                        // runs on a 4-cpu mask) and pinned deterministically by
                        // `tests/agg_corpus_hydration_deadlock.rs`.
                        //
                        // The maintenance pool's threads exist for the process
                        // lifetime and are never consumed by tokio, so the wait
                        // cannot be circular. It is the read-side twin of the
                        // work already on this pool (flush side-car builds,
                        // segment finalisation); the cost is that a cold
                        // hydration a search is waiting on now runs at the
                        // pool's `nice(10)`, which only bites when every core is
                        // already saturated.
                        let (decoded_tx, decoded_rx) =
                            tokio::sync::oneshot::channel::<Option<Resident<Vec<Value>>>>();
                        let decode = move || -> Option<Resident<Vec<Value>>> {
                            #[cfg(test)]
                            {
                                load_count.fetch_add(1, Ordering::Relaxed);
                                let delay_ms = load_delay_ms.load(Ordering::Relaxed);
                                if delay_ms > 0 {
                                    std::thread::sleep(std::time::Duration::from_millis(delay_ms));
                                }
                            }
                            let reader = store.open_segment(&load_segment_id).ok()?;
                            let stored_bytes_raw = reader.section(SectionType::Stored).ok()??;
                            let stored_bytes =
                                xerj_storage::stored_codec::decode_stored(stored_bytes_raw).ok()?;
                            let docs: Vec<Value> = serde_json::from_slice(&stored_bytes).ok()?;
                            let key = load_segment_id.clone();
                            let bytes = cache_estimates::stored_values_bytes(
                                &key,
                                std::mem::size_of::<CacheResident<Vec<Value>>>(),
                                &docs,
                            );
                            #[cfg(test)]
                            {
                                ready_to_publish.store(true, Ordering::Release);
                                while pause_before_publish.load(Ordering::Acquire) {
                                    std::thread::sleep(std::time::Duration::from_millis(1));
                                }
                            }
                            let resident = {
                                let _publication = lifecycle.read();
                                if !store
                                    .snapshot()
                                    .segments
                                    .iter()
                                    .any(|meta| meta.id == load_segment_id)
                                {
                                    CacheResident::uncached(docs)
                                } else {
                                    use dashmap::mapref::entry::Entry;
                                    match cache.entry(key) {
                                        Entry::Occupied(entry) => Arc::clone(entry.get()),
                                        Entry::Vacant(entry) => {
                                            if let Some(charge) = budget.try_charge(
                                                SegmentCacheCategory::StoredValues,
                                                bytes,
                                            ) {
                                                let resident = CacheResident::admitted(
                                                    docs,
                                                    charge,
                                                    SegmentCacheCategory::StoredValues,
                                                    bytes,
                                                );
                                                entry.insert(Arc::clone(&resident));
                                                resident
                                            } else {
                                                CacheResident::uncached(docs)
                                            }
                                        }
                                    }
                                }
                            };
                            Some(resident)
                        };
                        crate::background_pool().spawn(move || {
                            // Preserve the pre-#751 failure semantics: a panic
                            // in the decode used to surface as a `JoinError`
                            // and leave the waiter with `None` (the caller then
                            // reports the segment unreadable). rayon's default
                            // is to abort the process instead, so catch it here.
                            // Under `panic = "abort"` (the shipped profile) this
                            // is a no-op, exactly as before.
                            let decoded =
                                std::panic::catch_unwind(std::panic::AssertUnwindSafe(decode))
                                    .unwrap_or(None);
                            let _ = decoded_tx.send(decoded);
                        });
                        if let Ok(Some(value)) = decoded_rx.await {
                            let _ = sender.send(Some(value));
                        }
                        drop(permit);
                        loads.remove(&segment_id);
                    });
                    receiver
                }
            }
        };

        loop {
            if let Some(value) = receiver.borrow_and_update().clone() {
                return Some(value);
            }
            if receiver.changed().await.is_err() {
                return None;
            }
        }
    }

    /// Cache-backed range pre-filter — returns the set of internal doc
    /// positions matching a `Range` query, used to skip over non-matching
    /// docs in the stored-section scan.
    #[allow(clippy::too_many_arguments)] // ES range bounds (gte/gt/lte/lt) + segment identity
    /// `cap` — selectivity ceiling (mixed-RUW): above this many matches the
    /// builder returns `None` WITHOUT materialising the set, exactly like
    /// `build_term_prefilter_cached`'s `TERM_PREFILTER_CAP`.  A broad range
    /// (the mixed cells' `latency_ms >= 200` matches ~87% of the corpus)
    /// gains nothing from a prefilter — the F1 early-break / full scan is
    /// already the right path — but the build cost is O(matches) HashSet
    /// inserts: 100-300 ms at a 1-2M-doc merge output, paid by the FIRST
    /// query after every merge publish while the single-flight lock convoys
    /// every concurrent same-shape query behind it (live-measured 46→311 ms
    /// growing with index size; the mixed bool p99 cliff).  The cheap
    /// `range_count`/`shadow_range_count` bisects decide the bail BEFORE any
    /// allocation.  Callers that NEED the complete set regardless of size —
    /// the field-sorted Range `sort_candidates_narrowed` path — pass
    /// `usize::MAX`.  The cache key deliberately EXCLUDES the cap: a set
    /// built uncapped is identical to (and valid for) any capped request.
    #[allow(clippy::too_many_arguments)]
    fn build_range_prefilter_cached(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        field: &str,
        gte: Option<&Value>,
        gt: Option<&Value>,
        lte: Option<&Value>,
        lt: Option<&Value>,
        cap: usize,
    ) -> Option<Arc<PrefilterSet>> {
        use xerj_storage::doc_values::Column;

        let parse = |v: Option<&Value>| -> Option<Option<f64>> {
            match v {
                None => Some(None),
                Some(Value::Number(_)) => Some(v.and_then(|x| x.as_f64())),
                Some(Value::String(s)) => {
                    if let Ok(f) = s.parse::<f64>() {
                        return Some(Some(f));
                    }
                    crate::aggs::parse_date_ms(&Value::String(s.clone())).map(|ms| Some(ms as f64))
                }
                _ => None,
            }
        };
        // Numeric-scale bounds (parse_date_ms → epoch-ms f64) for the
        // `Column::Numeric` arm. The ORIGINAL `gte/gt/lte/lt` `&Value` params
        // are left un-shadowed so the date-shadow fallback below can re-derive
        // its bounds on the shadow's own epoch scale.
        let gte_n = parse(gte)?;
        let gt_n = parse(gt)?;
        let lte_n = parse(lte)?;
        let lt_n = parse(lt)?;

        let (lo, lo_incl) = match (gte_n, gt_n) {
            (Some(v), _) => (v, true),
            (None, Some(v)) => (v, false),
            (None, None) => (f64::NEG_INFINITY, true),
        };
        let (hi, hi_incl) = match (lte_n, lt_n) {
            (Some(v), _) => (v, true),
            (None, Some(v)) => (v, false),
            (None, None) => (f64::INFINITY, true),
        };

        // Segments are immutable → a (segment, field, bounds) key never
        // goes stale.  SINGLE-FLIGHT the build: post-merge-publish, every
        // in-flight range query raced the same miss and each rebuilt the
        // O(matches) set.
        let cache_key = format!(
            "{segment_id}\u{1}{field}\u{1}{:x}\u{1}{:x}\u{1}{}{}",
            lo.to_bits(),
            hi.to_bits(),
            lo_incl as u8,
            hi_incl as u8
        );
        if let Some(hit) = self.range_prefilter_cache.get(&cache_key) {
            return Some(Arc::clone(hit.value()));
        }
        let flight = {
            let e = self
                .stored_slices_build_locks
                .entry(format!("{segment_id}\u{2}rpf"))
                .or_default();
            Arc::clone(e.value())
        };
        let _g = flight.lock().ok()?;
        if let Some(hit) = self.range_prefilter_cache.get(&cache_key) {
            return Some(Arc::clone(hit.value()));
        }

        let cols = self.dv_columns_for(segments_dir, segment_id)?;
        let matching: Vec<u32> = match cols.get(field) {
            Some(Column::Numeric(n)) => {
                // Selectivity precheck (two bisects) BEFORE materialising.
                if n.range_count(lo, hi, lo_incl, hi_incl) as usize > cap {
                    return None;
                }
                n.range_doc_ids(lo, hi, lo_incl, hi_incl)
            }
            // DATE fields (e.g. `@timestamp`) are stored as date-shaped Keyword
            // dv columns, NOT `Column::Numeric`, so the arm above missed and the
            // whole query fell to a full O(N) stored-section scan. Their sorted
            // epoch shadow uses the SAME `(f64-bits-as-i64, pos)` encoding as
            // `NumericColumn.sorted` (sorted by f64 value ascending, one entry
            // per segment doc, built by `build_sort_shadow` only when the column
            // is dense with no nulls), so the identical O(log n + |matches|)
            // bisect applies. Bounds are re-derived on the shadow's OWN epoch
            // scale via `sort_date_normalize` — the exact fn that produced the
            // shadow keys — so bound and key compare on the same scale (exact
            // for the consistent-precision date fields every real ES mapping
            // uses). The stored scan re-tests the full query per admitted
            // position (`doc_matches_query`), so a superset is always safe; an
            // unparseable bound or a column with null/absent values (shadow →
            // `None`) → full scan, still correct.
            Some(Column::Keyword(k)) => {
                let seg_doc_count = k.doc_count as u64;
                let shadow =
                    self.sorted_shadow_for(segments_dir, segment_id, field, seg_doc_count)?;
                let shadow = shadow.value().as_ref()?;
                let (slo, slo_incl, shi, shi_incl) =
                    shadow_range_bounds(gte, gt, lte, lt, self.date_scale(field))?;
                // Same selectivity precheck on the shadow scale.
                if shadow_range_count(shadow, slo, shi, slo_incl, shi_incl) as usize > cap {
                    return None;
                }
                shadow_range_positions(shadow, slo, shi, slo_incl, shi_incl)
            }
            Some(Column::Presence(_)) | None => return None,
        };
        let built: Arc<PrefilterSet> = Arc::new(PrefilterSet::from_vec(matching));
        if self.range_prefilter_cache.len() >= 32 {
            self.range_prefilter_cache.clear();
        }
        self.range_prefilter_cache
            .insert(cache_key, Arc::clone(&built));
        Some(built)
    }

    /// Build a doc-position pre-filter for a `term` / `terms` query against a
    /// segment, so `scan_stored_section_into` parses ONLY the matching stored
    /// docs instead of the whole section. Without this a SELECTIVE term (an id
    /// lookup, `code:500`) walked + JSON-parsed every stored doc looking for
    /// the handful of matches — the size>0 F1 early-break never fired because
    /// the bounded hit collector never filled (few matches).
    ///
    /// Mirrors `build_range_prefilter_cached`: numeric-field terms reuse the
    /// sorted numeric index via a degenerate `[v, v]` range; keyword-field
    /// terms enumerate the positions carrying the term's ordinal.
    ///
    /// Returns:
    /// - `Some(∅)` when the term matches nothing in the segment (caller skips
    ///   the segment entirely — no decompress/scan);
    /// - `Some(set)` (COMPLETE match set) when the match cardinality is
    ///   selective (`<= TERM_PREFILTER_CAP`);
    /// - `None` for very-high-cardinality terms (the ordinary early-break scan
    ///   is already fast) and for shapes the doc-values can't resolve (analyzed
    ///   text, non-numeric value on a numeric column, missing column) → full
    ///   scan, still correct.
    fn build_term_prefilter_cached(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        field: &str,
        values: &[Value],
    ) -> Option<Arc<PrefilterSet>> {
        use xerj_storage::doc_values::Column;
        // Selectivity ceiling: above this the match set is large enough that
        // the ordinary scan's F1 early-break already bounds the parse to
        // O(from+size), so a big position set would only add build + memory
        // cost. Keeps the set to <= ~256 KB.
        const TERM_PREFILTER_CAP: usize = 65_536;

        let cols = self.dv_columns_for(segments_dir, segment_id)?;
        match cols.get(field)? {
            Column::Numeric(n) => {
                // Exact numeric equality per value = a degenerate inclusive
                // range; union across `terms` values. Bail if any value isn't
                // numeric (→ full scan preserves semantics).
                let mut set: HashSet<u32> = HashSet::new();
                for v in values {
                    let f = v.as_f64()?;
                    // Cheap cardinality guard before materialising positions.
                    if set.len() + n.range_count(f, f, true, true) as usize > TERM_PREFILTER_CAP {
                        return None;
                    }
                    set.extend(n.range_doc_ids(f, f, true, true));
                }
                Some(Arc::new(PrefilterSet::from_set(set)))
            }
            Column::Keyword(k) => {
                // One pass over `ords` for every value in the window. The
                // previous loop scanned the whole ordinal column once per
                // terms value, so a 1,024-value finalize-verify window walked
                // a large shared catalog 1,024 times (the seg-loop in #1761).
                // Duplicate values share an ordinal and are counted once.
                let mut wanted: HashSet<u32> = HashSet::new();
                let mut card: usize = 0;
                for v in values {
                    let term = match v {
                        Value::String(s) => {
                            // A CIDR value (`192.168.1.0/24`) is not a literal
                            // in the term dictionary; the source scan expands it
                            // via `ip_matches_cidr`. `ord_for_term` would miss
                            // and this arm would return an EMPTY prefilter, which
                            // silently drops the whole subnet once the docs flush
                            // to a segment (#786). Bail to a full scan instead,
                            // mirroring the memtable fast paths' `/` bailout.
                            if s.contains('/') {
                                return None;
                            }
                            s.clone()
                        }
                        other => other.to_string(),
                    };
                    let Some(ord) = k.ord_for_term(&term) else {
                        continue; // term absent in this segment → contributes 0
                    };
                    if !wanted.insert(ord) {
                        continue;
                    }
                    let n = k.per_ord_count.get(ord as usize).copied().unwrap_or(0) as usize;
                    if card + n > TERM_PREFILTER_CAP {
                        return None;
                    }
                    card += n;
                }
                let mut set: HashSet<u32> = HashSet::with_capacity(card);
                if !wanted.is_empty() {
                    for (pos, &o) in k.ords.iter().enumerate() {
                        if wanted.contains(&o) && !k.null_bitmap.contains(pos as u32) {
                            set.insert(pos as u32);
                        }
                    }
                }
                Some(Arc::new(PrefilterSet::from_set(set)))
            }
            // No ordinals to enumerate. A full scan stays correct.
            Column::Presence(_) => None,
        }
    }

    /// Lazily-built, cached `_id → stored-position` index for a segment.
    ///
    /// Reuses the decompressed `StoredSlices` (offset index) and extracts each
    /// doc's `_id` from the leading bytes of its stored slice, so an `ids`
    /// query can resolve primary keys to positions instead of scanning the
    /// whole section.  Built once per segment (segments are immutable) and
    /// evicted by id at the merge-completion site.
    ///
    /// Returns `None` when the slices can't be decoded OR when the map does
    /// not cover EVERY doc (a stored doc that carries no `_id` — the raw-source
    /// flush shape — can't be indexed here); the caller then falls back to the
    /// stored-doc scan, which has the identical `_id` resolution semantics, so
    /// no match is ever lost.
    fn id_pos_map_for(
        &self,
        seg_id: &str,
        expect_docs: u64,
    ) -> Option<Resident<std::collections::HashMap<String, u32>>> {
        if let Some(entry) = self.id_pos_cache.get(seg_id) {
            return Some(Arc::clone(entry.value()));
        }
        // #950: build the map from the `_id` column ALONE before touching
        // the full stored decode.  `stored_slices_for` materialises every
        // column of every stored document as a `serde_json::Value` tree
        // (~10-20x the JSON text) where this map needs one string per row;
        // a delete-by-query storm over that path was the dominant RSS
        // transient on the #950 corpus server (heap-profiled: 6.1 GiB of
        // 11.1 GiB sampled live).  Same id-resolution shape as meilisearch,
        // which answers id lookups from `external_documents_ids()` and
        // never from the document store.  Deliberately lock-free: the
        // `_id` column decode is a dict-bitpacked microsecond read, so a
        // concurrent-miss race only duplicates trivial work.
        if let Some(map) = self.id_pos_map_from_projection(seg_id, expect_docs) {
            let key = seg_id.to_string();
            let bytes = cache_estimates::id_positions_bytes(
                &key,
                std::mem::size_of::<CacheResident<std::collections::HashMap<String, u32>>>(),
                &map,
            );
            return Some(self.publish_current(
                &self.id_pos_cache,
                seg_id,
                key,
                SegmentCacheCategory::IdPositions,
                bytes,
                map,
            ));
        }
        let slices = self.stored_slices_for(seg_id, expect_docs)?;
        let mut map: std::collections::HashMap<String, u32> =
            std::collections::HashMap::with_capacity(slices.offsets.len());
        for (pos, &(start, end)) in slices.offsets.iter().enumerate() {
            let slice = slices.bytes.get(start as usize..end as usize)?;
            let id = match extract_stored_id(slice) {
                Some(id) => id,
                None => {
                    // Escape-bearing or unusual layout — fall back to a full
                    // parse for just this doc to recover its `_id`.
                    let mut buf = slice.to_vec();
                    match simd_json::serde::from_slice::<Value>(&mut buf) {
                        Ok(v) => match v.get("_id").and_then(Value::as_str) {
                            Some(s) => s.to_string(),
                            None => continue,
                        },
                        Err(_) => continue,
                    }
                }
            };
            map.insert(id, pos as u32);
        }
        // Only cache + serve a COMPLETE map (every stored doc has an `_id`);
        // otherwise defer to the scan so a doc without a stored `_id` is not
        // silently dropped from `ids` results.
        if map.len() as u64 != expect_docs {
            return None;
        }
        let key = seg_id.to_string();
        let bytes = cache_estimates::id_positions_bytes(
            &key,
            std::mem::size_of::<CacheResident<std::collections::HashMap<String, u32>>>(),
            &map,
        );
        Some(self.publish_current(
            &self.id_pos_cache,
            seg_id,
            key,
            SegmentCacheCategory::IdPositions,
            bytes,
            map,
        ))
    }

    /// `_id`-only map build over the stored projection (#950): decodes the
    /// `_id` column without materialising any other column.  `None` falls
    /// back to the full slice walk below — legacy LZ4/raw sections, a missing
    /// `_id` column, a row count that disagrees with the segment metadata, a
    /// non-string id, or duplicate ids (the same completeness guard the slice
    /// walk applies, so a doc without a usable stored `_id` still defers to
    /// the scan and no match is ever lost).
    fn id_pos_map_from_projection(
        &self,
        seg_id: &str,
        expect_docs: u64,
    ) -> Option<std::collections::HashMap<String, u32>> {
        use xerj_storage::stored_codec::{decode_stored_projection, StoredV2ProjectionResult};
        let reader = self.store.open_segment_arc(seg_id).ok()?;
        let raw = reader.section(SectionType::Stored).ok()??;
        let projected = decode_stored_projection(raw, &["__id"]).ok()?;
        let StoredV2ProjectionResult::Projected(projection) = projected else {
            return None;
        };
        let ids = projection.columns.get("__id")?;
        if ids.len() as u64 != expect_docs {
            return None;
        }
        let mut map: std::collections::HashMap<String, u32> =
            std::collections::HashMap::with_capacity(ids.len());
        for (pos, id) in ids.iter().enumerate() {
            let id = id.as_str()?;
            map.insert(id.to_string(), pos as u32);
        }
        if map.len() as u64 != expect_docs {
            return None;
        }
        Some(map)
    }

    /// Lazily-built, cached `stored-position → seq_no` array for a segment
    /// (see `row_seq_cache`). Returns `None` when the segment has no complete
    /// id index or an id is missing from the version map entirely.
    ///
    /// GHOST-AWARE (batch-11, F5): a row whose id has a DELETED version-map
    /// entry keeps the `u64::MAX` sentinel instead of bailing the whole
    /// segment. Pre-batch-11 the `lookup_seq_no(id)?` bail meant that in the
    /// window between a refresh-with-deletes and the purging merge EVERY
    /// scored query on a ghost-bearing segment fell off the columnar path to
    /// the brute flat scorer (live-reproduced: flat 1.6931472 vs ES's
    /// physical-stats BM25). The sole caller (`scored_columnar`) never reads
    /// a ghost row's seq — its ghost bitmaps (`ghost_positions_for`, same
    /// epoch signal) exclude those rows from matching — and an id can never
    /// go BACK to live in place (a re-index lands in the memtable, which
    /// keeps the columnar path off entirely), so the sentinel is never
    /// observable in results.
    fn row_seqs_for(&self, seg_id: &str, expect_docs: u64) -> Option<Resident<Vec<u64>>> {
        if let Some(entry) = self.row_seq_cache.get(seg_id) {
            return Some(Arc::clone(entry.value()));
        }
        let map = self.id_pos_map_for(seg_id, expect_docs)?;
        let mut seqs: Vec<u64> = vec![u64::MAX; expect_docs as usize];
        for (id, &pos) in map.iter() {
            match self.store.version_map.get(id) {
                Some(entry) if entry.deleted => {} // ghost row — sentinel stays
                Some(entry) => seqs[pos as usize] = entry.seq_no.saturating_sub(1),
                None => return None,
            }
        }
        let key = seg_id.to_string();
        let bytes = cache_estimates::row_sequences_bytes(
            &key,
            std::mem::size_of::<CacheResident<Vec<u64>>>(),
            seqs.capacity(),
        );
        Some(self.publish_current(
            &self.row_seq_cache,
            seg_id,
            key,
            SegmentCacheCategory::RowSequences,
            bytes,
            seqs,
        ))
    }

    /// Position pre-filter for an `ids` query: resolve each requested id to its
    /// stored position via the cached `_id → position` index.  Returns
    /// `Some(∅)` when none of the ids live in this segment (caller skips it),
    /// `Some(set)` with the resolved positions, or `None` when the segment has
    /// no complete id index (→ full scan, still correct).
    ///
    /// Callers gate this on `!deletes_present`: with no overwrites/tombstones
    /// each live id occupies exactly one segment position, so the resolved
    /// positions are the exact match set.
    fn build_ids_prefilter_cached(
        &self,
        seg_id: &str,
        expect_docs: u64,
        values: &[String],
    ) -> Option<Arc<PrefilterSet>> {
        let map = self.id_pos_map_for(seg_id, expect_docs)?;
        let mut set: HashSet<u32> = HashSet::with_capacity(values.len());
        for id in values {
            if let Some(&pos) = map.get(id) {
                set.insert(pos);
            }
        }
        Some(Arc::new(PrefilterSet::from_set(set)))
    }

    /// Superset pre-filter for a pure-conjunction `bool` (`must` + `filter`
    /// only — no `should` / `must_not`).
    ///
    /// `scan_stored_section_into` re-runs the FULL query via `doc_matches_query`
    /// on every admitted position, so the pre-filter only needs to be a
    /// SUPERSET of the true matches. A bool AND matches a SUBSET of every one of
    /// its conjuncts, so the COMPLETE position set of ANY single conjunct is a
    /// valid superset — and the SMALLEST such set is the tightest (fewest docs
    /// to parse + re-test). This is what makes the ubiquitous
    /// `bool { filter:[ term, range, … ] }` shape parse O(most-selective-
    /// conjunct) stored docs instead of the whole section.
    ///
    /// Returns `Some(∅)` if a conjunct matches nothing (→ the bool matches
    /// nothing → skip the segment), `Some(set)` (the smallest resolvable
    /// conjunct's complete set), or `None` when no conjunct resolves to a
    /// selective dv-backed Term/Terms/Range (→ full scan, still correct).
    fn build_bool_prefilter_cached(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        query: &QueryNode,
    ) -> Option<Arc<PrefilterSet>> {
        let QueryNode::Bool {
            must,
            should,
            // `must_not` is subtractive: it only REMOVES docs, so it never
            // widens the superset. The stored-scan re-runs the full bool per
            // admitted doc and applies it — no need to read it here.
            must_not: _,
            filter,
            ..
        } = query
        else {
            return None;
        };
        const BOOL_PREFILTER_CAP: usize = 65_536;
        // Resolve a single leaf clause to its COMPLETE match-position set for
        // this segment (term/terms/range only). `None` = not resolvable to a
        // complete set (e.g. a `match`/`wildcard` clause).
        let resolve = |child: &QueryNode| -> Option<Arc<PrefilterSet>> {
            let child = match child {
                QueryNode::Constant { query, .. } | QueryNode::Boosted { query, .. } => {
                    query.as_ref()
                }
                _ => child,
            };
            match child {
                QueryNode::Term { field, value, .. } => self.build_term_prefilter_cached(
                    segments_dir,
                    segment_id,
                    field,
                    std::slice::from_ref(value),
                ),
                QueryNode::Terms { field, values, .. } => {
                    self.build_term_prefilter_cached(segments_dir, segment_id, field, values)
                }
                QueryNode::Range {
                    field,
                    gte,
                    gt,
                    lte,
                    lt,
                    ..
                } => self.build_range_prefilter_cached(
                    segments_dir,
                    segment_id,
                    field,
                    gte.as_ref(),
                    gt.as_ref(),
                    lte.as_ref(),
                    lt.as_ref(),
                    BOOL_PREFILTER_CAP,
                ),
                _ => None,
            }
        };

        // CASE A — at least one REQUIRED conjunct (`must`/`filter`).
        // Every hit is a subset of the AND of all required conjuncts, hence a
        // subset of ANY single required conjunct's complete set. `should` is
        // optional/narrowing when a required clause is present (default
        // `minimum_should_match` is 0), and `must_not` is subtractive — both
        // only REMOVE docs, never add. So the smallest resolvable required
        // conjunct is a valid SUPERSET regardless of `should`/`must_not`; the
        // stored-scan re-runs the full bool per admitted doc, refining it to
        // the exact match set and applying `should` boosts + `must_not`.
        if !must.is_empty() || !filter.is_empty() {
            let mut best: Option<Arc<PrefilterSet>> = None;
            for child in must.iter().chain(filter.iter()) {
                if let Some(set) = resolve(child) {
                    if set.is_empty() {
                        // A required conjunct matches nothing → AND is empty.
                        return Some(set);
                    }
                    best = match best {
                        Some(b) if b.len() <= set.len() => Some(b),
                        _ => Some(set),
                    };
                }
            }
            return best;
        }

        // CASE B — pure `should` (no `must`/`filter`). Here `minimum_should_match`
        // defaults to 1, so a hit matches AT LEAST one should clause: the match
        // set is a subset of the UNION of every should clause's complete set
        // (a larger `minimum_should_match` only shrinks it further, so the union
        // stays a valid superset). `must_not` is still subtractive and gets
        // re-tested by the scan. The union is only valid if EVERY should clause
        // resolves — an unresolvable clause could admit docs outside the union.
        if !should.is_empty() {
            let mut union: HashSet<u32> = HashSet::new();
            for child in should.iter() {
                let set = resolve(child)?;
                if union.len() + set.len() > BOOL_PREFILTER_CAP {
                    return None; // too broad to be worth prefiltering
                }
                union.extend(set.sorted.iter().copied());
            }
            return Some(Arc::new(PrefilterSet::from_set(union)));
        }

        // Pure `must_not` (or nothing resolvable) → base set is ~all docs; no
        // useful superset. Fall back to the full scan.
        None
    }

    /// Sorted-DV candidate pruning for field-sorted `match_all` queries
    /// (the search_after hot-path fix).
    ///
    /// For a segment with a numeric doc-values column on the PRIMARY sort
    /// field, the column's sorted `(value, position)` index tells us exactly
    /// which positions can possibly reach the global top-`cap` page:
    /// - `asc`:  the first `cap` positions at/after the cursor's primary
    ///   value (cursor ties INCLUDED — the secondary sort key may still
    ///   qualify them), plus all positions tied with the boundary value so
    ///   the secondary key can arbitrate;
    /// - `desc`: symmetric from the top end.
    ///
    /// Every other position in the segment provably sorts outside the page
    /// (worse primary key than `cap` closer candidates) or at/before the
    /// cursor, so the stored scan can skip parsing it entirely.  This is
    /// what turns a 1M-doc `search_after` page from an O(N) parse-everything
    /// scan into O(from+size) per segment.
    ///
    /// Returns `None` (→ caller falls back to the full scan, still correct)
    /// unless the shape is provably safe:
    /// - primary sort is a plain field (not `_score`/`_doc`) with a
    ///   `Column::Numeric` sidecar in this segment;
    /// - the column has NO nulls (a null means a missing field, an array,
    ///   or a non-scalar — `missing`/`mode` semantics would need the full
    ///   scan) and covers exactly `seg_doc_count` docs (position alignment);
    /// - the `search_after` primary cursor value (when present) is numeric.
    ///
    /// The caller additionally gates on `is_match_all && !deletes_present`:
    /// deleted/superseded docs occupy positions in the sorted index, so with
    /// deletes present the candidate slice could under-fill the page.
    /// Per-(segment, field) sorted `(key_bits, pos)` source for the
    /// field-sort candidate prefilter.  Serves Numeric dv columns directly
    /// and date-shaped Keyword dv columns via an epoch shadow built with
    /// the SAME normalisation `compute_sort_values` applies per hit —
    /// this is what lets the implicit `@timestamp desc` index sort (a
    /// date STRING in `_source`, stored as a Keyword column) use the
    /// bounded candidate path instead of a full scan+heap walk.
    fn sorted_shadow_for(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        field: &str,
        seg_doc_count: u64,
    ) -> Option<Resident<Option<Arc<Vec<(i64, u32)>>>>> {
        // An ES meta-field (`_seq_no`, `_version`, …) is resolved from the
        // version map, never from the segment, so a dv column keyed by that
        // name must not drive the candidate cut (#401).
        //
        // Today no such column exists — but NOT because the name is
        // impossible: xerj accepts a literal `_seq_no` inside a document
        // (real ES rejects it), so it can reach `_source`.  It is the dv
        // sidecar builder that drops it, skipping every `_`-prefixed source
        // key as envelope bookkeeping (the `starts_with('_')` skip in
        // `build_doc_value_columns`).  That invariant lives elsewhere and
        // is not this path's to assume, so the guard is kept as the local
        // enforcement: relax the skip and the cut would silently rank on a
        // user-supplied value while the heap ranks on real metadata — the
        // memtable's identical shape, which IS reachable today, is what
        // `memtable_primary_key_rejects` had to be gated for.
        //
        // Bailing BEFORE the registry insert also stops the publish-time
        // warm burning one of its 16 slots probing a column that is not
        // written.
        if is_meta_sort_field(field) {
            return None;
        }
        // Register the field so the publish-time warm pre-builds this
        // shadow for every FUTURE segment (bounded registry).
        // The recorded value is the field's date scale, so `warm_segment_at_publish`
        // (which has no schema access) rebuilds the same keys this path would (#790).
        let scale = self.date_scale(field);
        if self.sort_shadow_fields.len() < 16 && !self.sort_shadow_fields.contains_key(field) {
            self.sort_shadow_fields.insert(field.to_string(), scale);
        }
        let key = format!("{segment_id}\u{1}{field}");
        if let Some(entry) = self.sort_shadow_cache.get(&key) {
            return Some(Arc::clone(entry.value()));
        }
        // A missing/unreadable dv sidecar is a TRANSIENT state (a segment can
        // become visible a beat before its sidecar read succeeds under heavy
        // flush churn) — return None WITHOUT caching so the next query
        // re-probes.  Only a successfully-read sidecar whose column SHAPE is
        // ineligible gets a durable `None` (that never changes for an
        // immutable segment).  Caching the transient miss permanently
        // disabled the bounded path for that segment: every subsequent
        // sorted read full-scanned it until a merge retired it.
        let cols = self.dv_columns_for(segments_dir, segment_id)?;
        let built = build_sort_shadow(&cols, field, seg_doc_count, scale);
        let bytes = cache_estimates::sort_shadow_bytes(
            &key,
            std::mem::size_of::<CacheResident<Option<Arc<Vec<(i64, u32)>>>>>(),
            built.as_ref().map(|shadow| shadow.capacity()),
        );
        Some(self.publish_current(
            &self.sort_shadow_cache,
            segment_id,
            key,
            SegmentCacheCategory::SortShadow,
            bytes,
            built,
        ))
    }

    /// Is the segment sort shadow — built once per (segment, field) on the
    /// field's MAPPED scale and cached under that key — usable for this sort?
    ///
    /// It is not when `numeric_type` re-scales the field (#889): the heap would
    /// rank on epoch numbers the shadow was not built from, so the candidate
    /// cut and the ranking would disagree. Rare enough to simply decline —
    /// the sort still runs, unaccelerated and correct.
    fn shadow_scale_matches_sort(&self, sf: &xerj_query::sort::SortField) -> bool {
        self.date_scale_for_sort(sf) == self.date_scale(&sf.field)
    }

    fn build_sort_candidates_prefilter(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        seg_doc_count: u64,
        topk: &SortTopK,
        cap: usize,
    ) -> Option<SortCandidates> {
        use xerj_query::sort::SortOrder;

        let sf = topk.fields.first()?;
        if sf.is_score() || sf.is_doc_order() || !self.shadow_scale_matches_sort(sf) {
            return None;
        }
        let shadow = self.sorted_shadow_for(segments_dir, segment_id, &sf.field, seg_doc_count)?;
        let shadow = shadow.value().as_ref()?;
        let sorted: &[(i64, u32)] = shadow.as_slice();
        if sorted.is_empty() {
            return None;
        }

        // Primary cursor bound (search_after). `None` cursor → page 1.
        let cursor_v: Option<f64> = match topk.after.as_deref() {
            Some(vals) => match vals.first() {
                Some(Value::Number(x)) => Some(x.as_f64()?),
                // Non-numeric cursor against a numeric column — don't
                // guess, take the full scan.
                Some(_) => return None,
                None => None,
            },
            None => None,
        };

        let len = sorted.len();
        let cap = cap.max(1);
        let (start, end) = if sf.order == SortOrder::Asc {
            let lo = match cursor_v {
                // Include cursor ties: `< v0` keeps every position whose
                // value equals the cursor's primary value; the collector's
                // full-key comparison decides via the secondary fields.
                Some(v0) => sorted.partition_point(|(b, _)| f64::from_bits(*b as u64) < v0),
                None => 0,
            };
            let mut end = (lo + cap).min(len);
            // Extend across boundary ties so the secondary sort key can
            // arbitrate between equal primary values.
            if end > lo && end < len {
                let boundary = sorted[end - 1].0;
                while end < len && sorted[end].0 == boundary {
                    end += 1;
                }
            }
            (lo, end)
        } else {
            let hi = match cursor_v {
                // Include cursor ties from the other side: `<= v0` keeps
                // positions with value == v0 inside the slice.
                Some(v0) => sorted.partition_point(|(b, _)| f64::from_bits(*b as u64) <= v0),
                None => len,
            };
            let mut start = hi.saturating_sub(cap);
            if start < hi && start > 0 {
                let boundary = sorted[start].0;
                while start > 0 && sorted[start - 1].0 == boundary {
                    start -= 1;
                }
            }
            (start, hi)
        };

        let sel = &sorted[start..end];
        let ordered: Vec<(i64, u32)> = if sf.order == SortOrder::Asc {
            sel.to_vec()
        } else {
            sel.iter().rev().copied().collect()
        };
        Some(SortCandidates {
            set: sel.iter().map(|(_, d)| *d).collect(),
            ordered,
        })
    }

    /// Field-sort candidate narrowing for a query with a KNOWN per-segment
    /// match position set (Range dv prefilter, FTS hit set): walk the
    /// segment's sort-key shadow in page order (cursor-bounded) and keep
    /// only positions that are in `matches`, stopping after `cap` plus
    /// boundary ties.  The result is EXACTLY the per-segment top-`cap`
    /// matching docs by the primary sort key (ties extended so the heap's
    /// full-key/_id comparison arbitrates) — a valid replacement for
    /// offering every match to the heap, PROVIDED the caller sources
    /// `hits.total` independently (shortcut count / seg_hits tally).
    fn narrow_matches_to_sort_candidates(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        seg_doc_count: u64,
        topk: &SortTopK,
        cap: usize,
        matches: &HashSet<u32>,
    ) -> Option<SortCandidates> {
        self.narrow_pred_to_sort_candidates(
            segments_dir,
            segment_id,
            seg_doc_count,
            topk,
            cap,
            &|pos| matches.contains(&pos),
        )
    }

    /// Field-sort candidate narrowing for Term/Terms queries WITHOUT
    /// materialising the match set: the per-position membership test is a
    /// dv-column equality probe (keyword ordinal / numeric f64-bits), so a
    /// low-selectivity term (e.g. `status:"ok"` matching 98% of the corpus,
    /// above `TERM_PREFILTER_CAP`) narrows in O(cap) shadow steps instead of
    /// building a 100k-entry position set — or, pre-fix, full-scanning the
    /// segment because the capped prefilter builder bailed.
    ///
    /// Membership semantics mirror `build_term_prefilter_cached` exactly
    /// (dv ord equality per value, f64-bits equality for numerics, nulls
    /// never match) plus the boolean-field 1.0/0.0 numeric encoding
    /// (`ScoredLeafKind::BoolEq` precedent, index.rs:12746).  Values the
    /// builder would bail on (non-numeric value against a numeric column)
    /// bail here too → full scan keeps ES coercion semantics.  A value
    /// absent from the keyword dictionary contributes zero matches, exactly
    /// like the builder's `ord_for_term` miss.
    ///
    /// Same output contract as `narrow_matches_to_sort_candidates`: the
    /// caller must source `hits.total` independently (shortcut count).
    #[allow(clippy::too_many_arguments)]
    fn narrow_term_values_to_sort_candidates(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        seg_doc_count: u64,
        topk: &SortTopK,
        cap: usize,
        field: &str,
        values: &[Value],
    ) -> Option<SortCandidates> {
        use xerj_storage::doc_values::Column;
        let cols = self.dv_columns_for(segments_dir, segment_id)?;
        match cols.get(field)? {
            Column::Keyword(k) => {
                let mut target_ords: Vec<u32> = Vec::with_capacity(values.len());
                for v in values {
                    let term = match v {
                        Value::String(s) => s.clone(),
                        other => other.to_string(),
                    };
                    if let Some(ord) = k.ord_for_term(&term) {
                        target_ords.push(ord);
                    }
                }
                if target_ords.is_empty() {
                    // No queried value exists in this segment → provably
                    // zero matches here (Some(∅) lets the caller skip the
                    // segment's stored bytes entirely).
                    return Some(SortCandidates {
                        set: HashSet::new(),
                        ordered: Vec::new(),
                    });
                }
                self.narrow_pred_to_sort_candidates(
                    segments_dir,
                    segment_id,
                    seg_doc_count,
                    topk,
                    cap,
                    &|pos| {
                        !k.null_bitmap.contains(pos)
                            && k.ords
                                .get(pos as usize)
                                .is_some_and(|o| target_ords.contains(o))
                    },
                )
            }
            Column::Numeric(n) => {
                let mut targets: Vec<f64> = Vec::with_capacity(values.len());
                for v in values {
                    let t = match v {
                        // Boolean-mapped fields are stored as 1.0/0.0 in the
                        // numeric dv column (BoolEq encoding).
                        Value::Bool(true) => 1.0,
                        Value::Bool(false) => 0.0,
                        // Strings etc. → bail; the full scan keeps ES's
                        // coercion semantics (same as the prefilter builder).
                        _ => v.as_f64()?,
                    };
                    targets.push(t);
                }
                self.narrow_pred_to_sort_candidates(
                    segments_dir,
                    segment_id,
                    seg_doc_count,
                    topk,
                    cap,
                    &|pos| {
                        !n.null_bitmap.contains(pos)
                            && n.data
                                .get(pos as usize)
                                .is_some_and(|&b| targets.contains(&f64::from_bits(b as u64)))
                    },
                )
            }
            Column::Presence(_) => None,
        }
    }

    /// Shared shadow walk behind `narrow_matches_to_sort_candidates` /
    /// `narrow_term_values_to_sort_candidates`: walk the segment's
    /// primary-sort-key shadow in page order (cursor-bounded), keep
    /// positions accepted by `matches_pos`, stop after `cap` plus boundary
    /// ties (so the heap's full-key/_id comparison arbitrates equal
    /// primaries).
    fn narrow_pred_to_sort_candidates(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        seg_doc_count: u64,
        topk: &SortTopK,
        cap: usize,
        matches_pos: &dyn Fn(u32) -> bool,
    ) -> Option<SortCandidates> {
        use xerj_query::sort::SortOrder;
        let sf = topk.fields.first()?;
        if sf.is_score() || sf.is_doc_order() || !self.shadow_scale_matches_sort(sf) {
            return None;
        }
        let shadow = self.sorted_shadow_for(segments_dir, segment_id, &sf.field, seg_doc_count)?;
        let shadow = shadow.value().as_ref()?;
        let sorted: &[(i64, u32)] = shadow.as_slice();
        if sorted.is_empty() {
            return None;
        }
        // Cursor bound (same semantics as build_sort_candidates_prefilter).
        let cursor_v: Option<f64> = match topk.after.as_deref() {
            Some(vals) => match vals.first() {
                Some(Value::Number(x)) => Some(x.as_f64()?),
                Some(_) => return None,
                None => None,
            },
            None => None,
        };
        let cap = cap.max(1);
        let len = sorted.len();
        let mut ordered: Vec<(i64, u32)> = Vec::with_capacity(cap + 8);
        let mut boundary: Option<i64> = None;
        let mut walk = |it: &mut dyn Iterator<Item = &(i64, u32)>| {
            for &(kb, pos) in it {
                if let Some(b) = boundary {
                    // Tie-extension phase: keep collecting equal-key matches.
                    if kb != b {
                        break;
                    }
                    if matches_pos(pos) {
                        ordered.push((kb, pos));
                    }
                    continue;
                }
                if matches_pos(pos) {
                    ordered.push((kb, pos));
                    if ordered.len() >= cap {
                        boundary = Some(kb);
                    }
                }
            }
        };
        if sf.order == SortOrder::Asc {
            let lo = match cursor_v {
                Some(v0) => sorted.partition_point(|(b, _)| f64::from_bits(*b as u64) < v0),
                None => 0,
            };
            walk(&mut sorted[lo..].iter());
        } else {
            let hi = match cursor_v {
                Some(v0) => sorted.partition_point(|(b, _)| f64::from_bits(*b as u64) <= v0),
                None => len,
            };
            walk(&mut sorted[..hi].iter().rev());
        }
        Some(SortCandidates {
            set: ordered.iter().map(|(_, d)| *d).collect(),
            ordered,
        })
    }

    /// Hydrate the sorted-DV candidate positions of one segment from the
    /// warm `stored_slices_cache` — the fast twin of the
    /// `scan_stored_section_into` sort-topk branch (same version-map delete
    /// check, same dedup, same pre-heap cursor/worst rejection, same
    /// `total_count` tally for parsed live candidates), minus the per-query
    /// decompress and the O(segment-bytes) brace scan.
    ///
    /// Only called on the `is_match_all` sorted-candidates path, so hits
    /// score 1.0 and every live candidate matches by construction.
    /// Warm-or-build access to a segment's `StoredSlices` (decompressed
    /// stored bytes + per-doc offsets).  Cache miss → decompress + one
    /// O(bytes) brace walk (NO per-doc parse) and insert under the budget;
    /// over budget the built value is still returned (per-query cost, but
    /// never a per-doc parse).  `None` on open/decode failure or a
    /// malformed section (offsets incomplete) — caller falls back to the
    /// legacy scan.
    fn stored_slices_for(&self, seg_id: &str, expect_docs: u64) -> Option<Resident<StoredSlices>> {
        if let Some(entry) = self.stored_slices_cache.get(seg_id) {
            return Some(Arc::clone(entry.value()));
        }
        // SINGLE-FLIGHT the miss: up to 64 in-flight queries race the
        // same cold segment; without this every one of them ran its own
        // full stored-section decompress (one ~30 ms decode became a ~1 s
        // 64-query stall episode at every publish the warm hadn't
        // reached).  Waiters block on the per-segment mutex and wake to a
        // cache hit.
        let flight = {
            let entry = self
                .stored_slices_build_locks
                .entry(seg_id.to_string())
                .or_default();
            Arc::clone(entry.value())
        };
        let _flight_guard = flight.lock().ok()?;
        if let Some(entry) = self.stored_slices_cache.get(seg_id) {
            return Some(Arc::clone(entry.value()));
        }
        // Reuse already-decompressed bytes from `decoded_stored_cache`
        // before paying a fresh open + decompress.
        let bytes: Vec<u8> = if let Some(entry) = self.decoded_stored_cache.get(seg_id) {
            entry.value().value().clone()
        } else {
            let reader = self.store.open_segment_arc(seg_id).ok()?;
            let raw = reader.section(SectionType::Stored).ok()??;
            xerj_storage::stored_codec::decode_stored(raw).ok()?
        };
        if bytes.len() > u32::MAX as usize {
            return None;
        }
        let offsets = brace_walk_offsets(&bytes);
        if offsets.len() as u64 != expect_docs {
            return None;
        }
        let slices = StoredSlices { bytes, offsets };
        let key = seg_id.to_string();
        let bytes = cache_estimates::stored_slices_bytes(
            &key,
            std::mem::size_of::<CacheResident<StoredSlices>>(),
            slices.bytes.capacity(),
            slices.offsets.capacity(),
        );
        Some(self.publish_current(
            &self.stored_slices_cache,
            seg_id,
            key,
            SegmentCacheCategory::StoredSlices,
            bytes,
            slices,
        ))
    }

    /// `_id` of every row of a segment's columnar stored section, read from
    /// its identity columns only. `None` (legacy layout, read error, a row
    /// count other than `expect_docs`) sends the caller to the full decode.
    fn cold_segment_ids(&self, seg_id: &str, expect_docs: u64) -> Option<Vec<Value>> {
        let reader = self.store.open_segment_arc(seg_id).ok()?;
        let bytes = reader.section(SectionType::Stored).ok()??;
        let ids = xerj_storage::stored_codec::decode_stored_v2_ids(bytes).ok()??;
        (ids.len() as u64 == expect_docs).then_some(ids)
    }

    /// Per-segment GHOST-position bitmap (b7 DEFECT 1c): bit `pos` set ⇔
    /// the stored doc at `pos` is tombstoned or superseded — its live
    /// version resides in another segment or the memtable per the version
    /// map — so FTS postings for it must not count toward `hits.total`.
    ///
    /// Built once per (segment, `ghost_events` epoch) from the stored
    /// `_id`s and cached; per-query filtering is then a bitmap test.  The
    /// build is O(segment docs) `_id` parses, paid only while ghosts exist
    /// (the window closes at the next merge, which also retires the
    /// segment id) — the same correctness-over-speed convention as the
    /// F1 / batch-6 delete-aware count gates.  `None` when the stored
    /// section can't be sliced or a doc can't be parsed; the caller falls
    /// back to the legacy physical count.
    fn ghost_positions_for(&self, seg_id: &str, expect_docs: u64) -> Option<Arc<Vec<u64>>> {
        let epoch = self.store.version_map.ghost_events();
        if let Some(entry) = self.ghost_positions_cache.get(seg_id) {
            if entry.value().0 == epoch {
                return Some(Arc::clone(&entry.value().1));
            }
        }
        let is_ghost = |id: &str| match self.store.version_map.get(id) {
            Some(ver) => ver.deleted || ver.segment_id.as_ref() != seg_id,
            // Not in the version map → nothing has ever superseded it.
            None => false,
        };
        // A cold segment reads its `_id` column alone: decoding (and
        // caching) the whole stored section here made the first query
        // under deletes pay for every row's `_source`.
        let cold = !self.stored_slices_cache.contains_key(seg_id)
            && !self.decoded_stored_cache.contains_key(seg_id);
        let cold_ids = cold
            .then(|| self.cold_segment_ids(seg_id, expect_docs))
            .flatten();
        let bm = if let Some(ids) = cold_ids {
            let mut bm = vec![0u64; ids.len().div_ceil(64)];
            for (pos, id) in ids.iter().enumerate() {
                if is_ghost(id.as_str().unwrap_or("")) {
                    bm[pos / 64] |= 1u64 << (pos % 64);
                }
            }
            bm
        } else {
            let slices = self.stored_slices_for(seg_id, expect_docs)?;
            let mut bm = vec![0u64; slices.offsets.len().div_ceil(64)];
            for (pos, &(start, end)) in slices.offsets.iter().enumerate() {
                let slice = slices.bytes.get(start as usize..end as usize)?;
                let doc: Value = serde_json::from_slice(slice).ok()?;
                if is_ghost(doc.get("_id").and_then(Value::as_str).unwrap_or("")) {
                    bm[pos / 64] |= 1u64 << (pos % 64);
                }
            }
            bm
        };
        let bm = Arc::new(bm);
        // Bounded like `shortcut_count_cache`: wholesale clear — entries
        // are per-segment (not query-shaped) so the cap is generous.
        if self.ghost_positions_cache.len() >= 512 {
            self.ghost_positions_cache.clear();
        }
        self.ghost_positions_cache
            .insert(seg_id.to_string(), (epoch, Arc::clone(&bm)));
        Some(bm)
    }

    #[allow(clippy::too_many_arguments)]
    fn hydrate_sorted_candidates(
        &self,
        slices: &StoredSlices,
        candidates: &SortCandidates,
        // Retained for signature parity with the sibling scan loops; the
        // score now comes from `scorer` (which closes over the query).
        _query: &QueryNode,
        is_match_all: bool,
        // #1019 — ids-only projection (delete-by-query pages): see the
        // admission block below.
        ids_only: bool,
        topk: &mut SortTopK,
        seen_ids: &mut HashSet<String>,
        total_count: &mut u64,
        // Per-doc scorer from `search_inner` (`score_doc`): single-applies
        // any peeled function_score and resolves `_id` for ids clauses.
        scorer: &(dyn Fn(&Value, &str) -> f32 + Send + Sync),
    ) {
        // Walk candidates in page order (best-first).  Their primary sort
        // key is already known from the dv shadow, so once the heap is
        // full and a candidate's primary is STRICTLY worse than the
        // current worst, every remaining candidate (same or worse primary)
        // is also rejected — break WITHOUT parsing.  After the heap warms
        // up this makes each additional segment O(ties) parses instead of
        // O(cap).
        for &(key_bits, pos) in &candidates.ordered {
            if topk.primary_f64_rejects(f64::from_bits(key_bits as u64)) {
                break;
            }
            let Some(&(start, end)) = slices.offsets.get(pos as usize) else {
                continue;
            };
            let Some(slice) = slices.bytes.get(start as usize..end as usize) else {
                continue;
            };
            // #1019 — ids-only hydration. Candidates are guaranteed query
            // matches by construction (match_all, or positions drawn from
            // the query's own dv/FTS match set), and the eligibility gate
            // in `search_inner` confined the sort to `_id`/`_doc`, so
            // nothing here needs the `_source`: extract the id and offer
            // it with `source: Value::Null` — no `Value` tree, no clone.
            // The version-map liveness filter is kept verbatim; the
            // superseded-copy (`_seq_no`) skip is deliberately dropped (a
            // stale copy carries the SAME id, and id-set membership is all
            // this projection may decide). `extract_stored_id` → `None`
            // (escape-bearing layout) falls through to the full parse.
            if ids_only {
                if let Some(id) = extract_stored_id(slice) {
                    let mut hit_seq_no = None;
                    let mut hit_version = None;
                    if let Some(ver) = self.store.version_map.get(&id) {
                        if ver.deleted {
                            continue;
                        }
                        let (s, v) = self.hit_seq_version(&id, &ver);
                        hit_seq_no = s;
                        hit_version = v;
                    }
                    *total_count += 1;
                    if seen_ids.contains(&id) {
                        continue;
                    }
                    let key =
                        compute_sort_values(&Value::Null, 1.0, &id, topk.fields.as_slice(), self);
                    if !topk.would_admit(&key) {
                        continue;
                    }
                    seen_ids.insert(id.clone());
                    let seq = hit_seq_no.unwrap_or(u64::MAX);
                    topk.offer_keyed(
                        Hit {
                            id,
                            score: 1.0,
                            source: Value::Null,
                            seq_no: hit_seq_no,
                            version: hit_version,
                            sort: key,
                            explain: None,
                            highlight: None,
                            matched_queries: Vec::new(),
                            passage: None,
                        },
                        seq,
                    );
                    continue;
                }
            }
            let mut doc_buf = slice.to_vec();
            let doc: Value = match simd_json::serde::from_slice(&mut doc_buf) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let id_ref = doc.get("_id").and_then(Value::as_str).unwrap_or("");
            // Captured from the SAME version-map entry the
            // deleted/superseded check reads, so `_seq_no`/`_version` never
            // diverge from the `source` parsed above (#440).
            let mut hit_seq_no = None;
            let mut hit_version = None;
            if let Some(ver) = self.store.version_map.get(id_ref) {
                if ver.deleted {
                    continue;
                }
                // Superseded stale copy (b8 DEFECT T2) — merge.rs predicate.
                if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                    if doc_seq < ver.seq_no {
                        continue;
                    }
                }
                let (s, v) = self.hit_seq_version(id_ref, &ver);
                hit_seq_no = s;
                hit_version = v;
            }
            *total_count += 1;
            if seen_ids.contains(id_ref) {
                continue;
            }
            let source_ref = doc.get("_source").unwrap_or(&doc);
            // Candidates are guaranteed query matches by construction
            // (match_all, or positions drawn from the query's own dv/FTS
            // match set) — only the SCORE needs the per-query path.
            // #1019 — under the ids-only projection the score is unused
            // (sort confined to `_id`/`_doc`), so the scorer is skipped and
            // the hit carries `source: Value::Null` instead of a clone.
            let score = if is_match_all || ids_only {
                1.0
            } else {
                scorer(source_ref, id_ref)
            };
            let key = compute_sort_values(source_ref, score, id_ref, topk.fields.as_slice(), self);
            if !topk.would_admit(&key) {
                continue;
            }
            let id = id_ref.to_string();
            seen_ids.insert(id.clone());
            let seq = hit_seq_no.unwrap_or(u64::MAX);
            topk.offer_keyed(
                Hit {
                    id,
                    score,
                    source: if ids_only {
                        Value::Null
                    } else {
                        source_ref.clone()
                    },
                    seq_no: hit_seq_no,
                    version: hit_version,
                    sort: key,
                    explain: None,
                    highlight: None,
                    matched_queries: Vec::new(),
                    passage: None,
                },
                seq,
            );
        }
    }

    /// Hydrate an UNSORTED, pre-filtered query from a warm `StoredSlices` using
    /// the per-doc offset index for RANDOM ACCESS — parse only the pre-filter
    /// positions, never brace-walk the whole section.
    ///
    /// The warm-slices scan path otherwise walks every doc's bytes (balanced-
    /// brace split) to advance the position counter and test pre-filter
    /// membership, so a selective term whose matches fan across all N shard-
    /// segments paid O(total section bytes) per query even though it parses
    /// only a handful of docs. With the offsets already cached, we jump
    /// straight to each matching position instead: O(|pre_filter|) parses, no
    /// section walk.
    ///
    /// `pre_filter` is a SUPERSET of the true matches (bool picks one
    /// conjunct's complete set; term/range sets are exact) — every hydrated doc
    /// is re-tested with `doc_matches_query`, so false positives are dropped
    /// exactly as the brace-walk scan drops them. Admit order is positional
    /// (positions sorted ascending) to match the linear scan's `all_hits`
    /// order, and deletes are filtered via the version map. Early-break mirrors
    /// F1: stop once the bounded page is full and the exact total is supplied
    /// elsewhere (`count_authoritative`).
    #[allow(clippy::too_many_arguments)]
    fn hydrate_prefiltered_unsorted(
        &self,
        slices: &StoredSlices,
        pre_filter: &PrefilterSet,
        query: &QueryNode,
        is_match_all: bool,
        // #1019 — ids-only projection: this arm must still PARSE each
        // candidate (the pre-filter is only a superset, so the full query
        // is re-tested against `_source`), but under the projection the
        // admitted hit carries `source: Value::Null` and skips the scorer.
        // Unreachable for the delete loops themselves (they sort by `_id`,
        // which routes them to the sorted-candidate / scan arms); kept
        // uniform so no ids-only admission can clone a source tree.
        ids_only: bool,
        count_only: bool,
        materialisation_limit: usize,
        count_authoritative: bool,
        total_count: &mut u64,
        all_hits: &mut Vec<Hit>,
        seen_ids: &mut HashSet<String>,
        // Per-doc scorer from `search_inner` (`score_doc`): single-applies
        // any peeled function_score and resolves `_id` for ids clauses.
        scorer: &(dyn Fn(&Value, &str) -> f32 + Send + Sync),
        schema: &Schema,
    ) {
        // LOSS_BATTLE_PLAN B7 (completed): the positions arrive PRE-SORTED
        // ascending from the cached `PrefilterSet` — zero per-query set
        // collection, selection, or sorting.  With an authoritative count
        // the hit loop breaks at `materialisation_limit`, so a broad cached
        // filter (range matching the whole corpus) costs O(page) per query;
        // the exact-total path (`count_authoritative == false`) walks every
        // position exactly as before, in the same ascending (== response)
        // order.  Pre-fix this function collected the whole `HashSet` into
        // a Vec and `select_nth`ed it PER QUERY — a stable ~0.17 ms tax on
        // a 10-doc page over a 100k-position cached set.
        for &pos in pre_filter.sorted.iter() {
            if count_authoritative && !count_only && all_hits.len() >= materialisation_limit {
                break;
            }
            let Some(&(start, end)) = slices.offsets.get(pos as usize) else {
                continue;
            };
            let Some(slice) = slices.bytes.get(start as usize..end as usize) else {
                continue;
            };
            let mut doc_buf = slice.to_vec();
            let doc: Value = match simd_json::serde::from_slice(&mut doc_buf) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let id_ref = doc.get("_id").and_then(Value::as_str).unwrap_or("");
            // Captured from the SAME version-map entry the
            // deleted/superseded check reads, so `_seq_no`/`_version` never
            // diverge from the `source` parsed above (#440).
            let mut hit_seq_no = None;
            let mut hit_version = None;
            if let Some(ver) = self.store.version_map.get(id_ref) {
                if ver.deleted {
                    continue;
                }
                // Superseded stale copy (b8 DEFECT T2) — merge.rs predicate.
                if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                    if doc_seq < ver.seq_no {
                        continue;
                    }
                }
                let (s, v) = self.hit_seq_version(id_ref, &ver);
                hit_seq_no = s;
                hit_version = v;
            }
            // Re-test the full query — the pre-filter is only a superset.
            let matched = if is_match_all {
                true
            } else if let QueryNode::Ids { values } = query {
                values.iter().any(|v| v == id_ref)
            } else {
                let source_ref = doc.get("_source").unwrap_or(&doc);
                let source_with_id = if source_ref.get("_id").is_some() {
                    source_ref.clone()
                } else if let Some(obj) = source_ref.as_object() {
                    let mut o = obj.clone();
                    o.insert("_id".to_string(), Value::String(id_ref.to_string()));
                    Value::Object(o)
                } else {
                    source_ref.clone()
                };
                doc_matches_query_typed(query, &source_with_id, schema)
            };
            if !matched {
                continue;
            }
            *total_count += 1;
            if count_only {
                continue;
            }
            if all_hits.len() >= materialisation_limit {
                if count_authoritative {
                    break;
                }
                continue;
            }
            let id: String = id_ref.to_string();
            if seen_ids.contains(&id) {
                continue;
            }
            // #1019 — ids-only projection: no source clone, no scorer (the
            // eligibility argument is documented on the sort-topk branch of
            // `scan_stored_section_into`).
            let source = if ids_only {
                Value::Null
            } else {
                doc.get("_source").cloned().unwrap_or_else(|| doc.clone())
            };
            let score = if is_match_all || ids_only {
                1.0
            } else {
                scorer(&source, &id)
            };
            seen_ids.insert(id.clone());
            all_hits.push(Hit {
                id,
                score,
                source,
                seq_no: hit_seq_no,
                version: hit_version,
                sort: Vec::new(),
                explain: None,
                highlight: None,
                matched_queries: Vec::new(),
                passage: None,
            });
        }
    }

    /// Regexp pre-filter — the set of internal doc positions whose keyword
    /// term matches the (compile-once) anchored pattern, used to skip
    /// non-matching docs in the stored-section scan the same way the
    /// Range pre-filter does.
    ///
    /// The regex runs over the segment's DISTINCT terms (doc-values
    /// keyword dictionary when present, else the field's FTS `.fst`
    /// dictionary), not per doc: O(dictionary) matcher work + one ords
    /// walk / bounded postings merge.  Exactness mirrors the
    /// `try_shortcut_count` Regexp arm: the doc-scan Regexp arm matches
    /// only `Value::String` sources; the keyword column stores exactly
    /// those strings (non-strings are null), and the FST route is only
    /// taken when `fst_ok` (schema says keyword-typed → term == raw
    /// string, and FTS doc ids == stored positions, see the FTS hit
    /// materialisation which indexes stored docs by `doc_id`).  Fields
    /// with neither source return `None` → full scan, never a wrong skip.
    ///
    /// `cap`: when the caller's `hits.total` is authoritative (F1) the
    /// scan early-breaks after materialising `cap` hits anyway, so we stop
    /// collecting positions there instead of building an ~850 k-entry set
    /// for a broad pattern.  Pass `None` when the scan must tally the
    /// exact total itself — then the set must be complete.  The capped
    /// set holds the FIRST `cap` matching positions in doc order (ords
    /// walk / ascending postings merge), so the scan materialises the
    /// same leading hits the uncapped scan would.
    fn build_regexp_prefilter_cached(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        field: &str,
        pattern: &str,
        cap: Option<usize>,
        fst_ok: bool,
    ) -> Option<HashSet<u32>> {
        let exp =
            self.regexp_segment_expansion(segments_dir, segment_id, field, pattern, fst_ok)?;
        if exp.count == 0 {
            // No dictionary term matches — whole segment skipped without
            // decompressing / parsing a single stored doc.
            return Some(HashSet::new());
        }
        match cap {
            // Bounded (F1 count-authoritative) mode: the scan stops after
            // materialising `c` hits, so the FIRST `c` matching positions
            // (ascending == scan order) reproduce exactly the hits the
            // unfiltered scan would emit.  The expansion retains
            // `REGEXP_EXPANSION_POS_CAP` ≥ any default page, so this only
            // falls back to a full scan for very deep pagination.
            Some(c) => {
                if exp.complete || exp.positions.len() >= c {
                    Some(exp.positions.iter().take(c).copied().collect())
                } else {
                    None
                }
            }
            // Unbounded mode (scan must tally the exact total itself):
            // only a COMPLETE position set is a valid filter.
            None => {
                if exp.complete {
                    Some(exp.positions.iter().copied().collect())
                } else {
                    None
                }
            }
        }
    }

    /// Expand a regexp against one segment's term dictionary, cached per
    /// `(segment_id, field, pattern)` — see `regexp_expand_cache`.
    ///
    /// Sources, in order:
    /// (a) the `.dv` keyword column (sorted distinct terms + ords) — exact
    ///     for any field type because it stores raw strings only;
    /// (b) the field's FTS `.fst` term dictionary + postings union —
    ///     taken only when `fst_ok` (schema says the field is
    ///     keyword-typed, so FST terms are the raw un-analyzed strings and
    ///     the expansion agrees with the stored-doc scan it stands in
    ///     for).  Flushed segments currently carry no `.dv` sidecar, so
    ///     (b) is the path that serves live traffic; merged segments have
    ///     both.
    ///
    /// Returns `None` when neither source can answer exactly (missing
    /// side-cars, non-keyword field, or a pathological pattern matching
    /// > 1024 dictionary terms) — callers fall back to the stored scan.
    fn regexp_segment_expansion(
        &self,
        segments_dir: &std::path::Path,
        segment_id: &str,
        field: &str,
        pattern: &str,
        fst_ok: bool,
    ) -> Option<Arc<RegexpExpansion>> {
        let key = (
            segment_id.to_string(),
            field.to_string(),
            pattern.to_string(),
        );
        if let Some(hit) = self.regexp_expand_cache.get(&key) {
            return Some(Arc::clone(hit.value()));
        }

        // An invalid pattern matches nothing (the doc-scan arm fails the
        // per-doc compile and returns false) — expansion is empty+complete.
        let re = compiled_anchored_regex(pattern);

        let mut exp: Option<RegexpExpansion> = None;
        if let Some(cols) = self.dv_columns_for(segments_dir, segment_id) {
            if let Some(xerj_storage::doc_values::Column::Keyword(k)) = cols.get(field) {
                let mut count: u64 = 0;
                let mut positions: Vec<u32> = Vec::new();
                if let Some(re) = re.as_ref() {
                    let matched_ords: Vec<bool> = k.terms.iter().map(|t| re.is_match(t)).collect();
                    if matched_ords.iter().any(|&m| m) {
                        for (i, &ord) in k.ords.iter().enumerate() {
                            let pos = i as u32;
                            if k.null_bitmap.contains(pos) {
                                continue;
                            }
                            if matched_ords.get(ord as usize).copied().unwrap_or(false) {
                                count += 1;
                                if positions.len() < REGEXP_EXPANSION_POS_CAP {
                                    positions.push(pos);
                                }
                            }
                        }
                    }
                }
                let complete = count == positions.len() as u64;
                exp = Some(RegexpExpansion {
                    count,
                    positions,
                    complete,
                });
            }
        }

        let exp = match exp {
            Some(e) => e,
            None => {
                if !fst_ok {
                    return None;
                }
                let reader = FtsIndexReader::open(segments_dir, segment_id, &[field]).ok()?;
                reader.field_stats(field)?;
                let matched = regexp_matched_fst_terms(&reader, field, re.as_ref())?;
                if matched.is_empty() {
                    RegexpExpansion {
                        count: 0,
                        positions: Vec::new(),
                        complete: true,
                    }
                } else {
                    let (count, positions) =
                        postings_union_expand(&reader, field, &matched, REGEXP_EXPANSION_POS_CAP);
                    let complete = count == positions.len() as u64;
                    RegexpExpansion {
                        count,
                        positions,
                        complete,
                    }
                }
            }
        };

        if self.regexp_expand_cache.len() >= REGEXP_EXPANSION_CACHE_MAX {
            self.regexp_expand_cache.clear();
        }
        let arc = Arc::new(exp);
        self.regexp_expand_cache.insert(key, Arc::clone(&arc));
        Some(arc)
    }

    /// Version of `try_aggs_fast_with_segments` that caches decoded columns
    /// per segment on `self.dv_cache`.  Segments are immutable once flushed,
    /// so a decoded `Arc<BTreeMap<String, Column>>` stays valid until the
    /// segment is merged away (at which point it gets evicted in bulk).
    ///
    /// The cache turns the first query over a segment into a file read +
    /// LZ4 decompress + decode, and every subsequent query into a pointer
    /// chase.  This is what makes `terms agg method` over millions of
    /// docs land in the single-digit ms range instead of 100ms+.
    async fn try_aggs_fast_with_segments_cached(
        &self,
        aggs_def: &Value,
        filter: Option<&Value>,
        snap: &xerj_storage::index_store::IndexSnapshot,
        segments_dir: &std::path::Path,
    ) -> Option<(Value, Option<u64>)> {
        // 2026-07 agg-hang fix: the columnar executor in `fast_aggs.rs`
        // serves `size:0 + match_all + aggs` straight from segment `.dv`
        // sidecars + the live memtable.  It bails (None) on any shape it
        // can't reproduce byte-identically, on small indices, and when
        // deletes/updates are present — the caller then falls back to the
        // brute `run_aggs_with_all` stored-doc path.
        //
        // Boolean-mapped fields are stored as 0/1 in numeric `.dv` columns,
        // indistinguishable from real integers at the column level. The
        // schema is the only source of truth for "render 0/1 as
        // false/true", so snapshot the boolean field names here (async
        // lock) and hand them to the sync executor.
        //
        // `mapped_fields` is every field name the schema knows (dynamic
        // mapping only ever maps top-level keys). A field that has no `.dv`
        // column at any depth in any segment yet whose name — or, for a
        // dotted path, top-level root — is in this set is one brute's
        // `get_field_value` still resolves, and the columnar path structurally
        // cannot: a scalar leaf nested under an object (`geo.dest` under
        // object `geo`, resolved by recursing into `_source`), or a top-level
        // field whose column was SUPPRESSED because it is multi-valued (`tags`
        // / `tags.raw`, read straight from the `_source` array). Both must
        // fall back to the brute path instead of silently returning
        // empty/null; a name whose root is unmapped is genuinely absent and a
        // valid empty result. Keyed off the schema, not a column probe, since
        // by construction neither of those fields carries a column to probe.
        let (bool_fields, mapped_fields): (
            std::collections::HashSet<String>,
            std::collections::HashSet<String>,
        ) = {
            let guard = self.schema.read().await;
            let mut bool_fields = std::collections::HashSet::new();
            let mut mapped_fields = std::collections::HashSet::new();
            for f in &guard.schema.fields {
                if f.field_type == xerj_common::FieldType::Boolean {
                    bool_fields.insert(f.name.clone());
                }
                mapped_fields.insert(f.name.clone());
            }
            (bool_fields, mapped_fields)
        };
        self.try_fast_aggs(
            aggs_def,
            filter,
            snap,
            segments_dir,
            &bool_fields,
            &mapped_fields,
        )
    }
}

// ── Helper for streaming stored-doc scan ─────────────────────────────────────

impl Index {
    /// Scan the stored section of a single segment and push matching docs
    /// into the caller's bounded collector.
    ///
    /// This uses a **streaming parser** that reads one JSON value at a time
    /// out of the `[v1, v2, ...]` array — a full `Vec<Value>` is never
    /// materialised for the segment, which was essential to stop the
    /// query-path OOM in CAPPED_RAM_BATTLE.  For a 50 k-doc segment the
    /// materialised Vec used ~150 MB of heap; the streaming version uses
    /// <1 MB because each doc is dropped before the next is parsed.
    ///
    /// `pre_filter` (M2 G3): when `Some`, restricts parsing to internal
    /// doc positions in the set.  Non-matching positions are skipped via
    /// brace counting only — we never allocate a `Value` tree for them.
    /// This makes Range queries O(matching_docs) instead of O(total_docs)
    /// in the worst case, because `range_doc_ids` on the segment's doc-
    /// values sorted index gives us the exact set in O(log n).
    #[allow(clippy::too_many_arguments)]
    fn scan_stored_section_into(
        &self,
        stored_bytes: &[u8],
        query: &QueryNode,
        is_match_all: bool,
        // #1019 — ids-only projection: the caller reads nothing but `hit.id`
        // (delete-by-query / engine purge pages); sort keys were gated to
        // `_id`/`_doc` in `search_inner`. See the admission block below.
        ids_only: bool,
        count_only: bool,
        materialisation_limit: usize,
        count_authoritative: bool,
        total_count: &mut u64,
        all_hits: &mut Vec<Hit>,
        seen_ids: &mut HashSet<String>,
        pre_filter: Option<&HashSet<u32>>,
        mut sort_topk: Option<&mut SortTopK>,
        // When `Some`, every doc's `(start, end)` byte range is appended as
        // the brace-scan walks the section, so the caller can cache the
        // decompressed bytes + offsets (`stored_slices_cache`) and hydrate
        // future sorted-candidate queries without re-scanning.  Callers must
        // verify `offsets_out.len() == segment doc_count` before caching —
        // a malformed section bails early and leaves the vec incomplete.
        mut offsets_out: Option<&mut Vec<(u32, u32)>>,
        // Cooperative timeout: when `Some`, the walk polls the wall clock
        // every 256 docs and aborts (setting `*timed_out`) once past the
        // deadline.  One giant merged segment is otherwise a multi-second
        // uninterruptible unit — the between-segment deadline check in
        // `search_inner` can't bound it.
        deadline: Option<std::time::Instant>,
        timed_out: &mut bool,
        // Diagnostics: docs brace-walked and hits admitted by THIS call.
        dbg_walked: &mut u64,
        dbg_admitted: &mut u64,
        // Per-doc scorer from `search_inner` (`score_doc`): single-applies
        // any peeled function_score and resolves `_id` for ids clauses.
        scorer: &(dyn Fn(&Value, &str) -> f32 + Send + Sync),
        schema: &Schema,
    ) {
        // Fast path: scan one doc at a time with a hand-rolled array splitter.
        // The stored section is always shaped as `[{...}, {...}, ...]` (a
        // JSON array of objects).  We walk the bytes, find each top-level
        // object's range by balanced-brace counting, and parse only that
        // slice — so the only allocation per doc is the `Value` tree for a
        // single doc, which is released before the next iteration.
        let bytes = stored_bytes;
        let n = bytes.len();
        if n < 2 {
            return;
        }
        // Skip leading whitespace/`[`.
        let mut i = 0usize;
        while i < n && (bytes[i].is_ascii_whitespace() || bytes[i] == b'[') {
            i += 1;
        }

        // Track the current document's internal index so we can match it
        // against `pre_filter`.  Position 0 = first doc in stored section.
        let mut doc_pos: u32 = 0;

        // Computed once for the whole scan, not per doc — see
        // `query_needs_id_injection`'s doc comment.
        let needs_id_injection = query_needs_id_injection(query);

        // #1019 — precomputed cursor for the ids-only fast decline in the
        // admission block below: `(cursor, ascending)` when the sort is a
        // sole `_id` key with a string `search_after` (every delete-by-query
        // page after the first). Any other shape declines through the normal
        // `would_admit` path.
        let ids_only_cursor: Option<(String, bool)> = if !ids_only {
            None
        } else {
            sort_topk.as_ref().and_then(|t| {
                if t.fields.len() == 1 && t.fields[0].field == "_id" {
                    let asc = t.fields[0].order == xerj_query::sort::SortOrder::Asc;
                    t.after
                        .as_ref()
                        .and_then(|a| a.first())
                        .and_then(Value::as_str)
                        .map(|c| (c.to_string(), asc))
                } else {
                    None
                }
            })
        };

        loop {
            // F1b — IN-SEGMENT early stop.  The between-segment F1 break in
            // `search_inner` skips segments once the page is full and the
            // total is authoritative, but a single giant merged segment
            // still paid a FULL walk here: brace-scan + simd_json parse of
            // every stored doc (~11 s for an uncached size=10 `match_all`
            // at 3.5 M docs — completely masked at steady state by the
            // query cache, catastrophic under a bulk writer where every
            // request is a cache miss).  Once the bounded collector is
            // full, nothing later in this section can change the page
            // (admit order is positional) and `total_count` is overwritten
            // by the shortcut/live count anyway — so stop scanning.
            //
            // Excluded, for the same reasons as the outer break:
            //   - `count_only`: the scan tally IS the total when no
            //     shortcut resolved (count_authoritative already implies a
            //     shortcut, but keep the guard belt-and-braces);
            //   - `sort_topk`: top-N needs every matching doc's sort key;
            //   - `offsets_out`: the offsets cache must cover the section.
            if count_authoritative
                && !count_only
                && sort_topk.is_none()
                && offsets_out.is_none()
                && all_hits.len() >= materialisation_limit
            {
                return;
            }
            // Skip whitespace/commas between docs.
            while i < n && (bytes[i].is_ascii_whitespace() || bytes[i] == b',') {
                i += 1;
            }
            if i >= n || bytes[i] == b']' {
                break;
            }
            if bytes[i] != b'{' {
                // Unexpected char — bail gracefully.
                return;
            }
            // Scan for the matching closing brace, tracking strings + escapes.
            let start = i;
            let mut depth = 0i32;
            let mut in_str = false;
            let mut escape = false;
            while i < n {
                let b = bytes[i];
                if in_str {
                    if escape {
                        escape = false;
                    } else if b == b'\\' {
                        escape = true;
                    } else if b == b'"' {
                        in_str = false;
                    }
                } else {
                    match b {
                        b'"' => in_str = true,
                        b'{' => depth += 1,
                        b'}' => {
                            depth -= 1;
                            if depth == 0 {
                                i += 1;
                                break;
                            }
                        }
                        _ => {}
                    }
                }
                i += 1;
            }
            let end = i;
            if depth != 0 {
                // Malformed — bail.
                return;
            }

            if let Some(out) = offsets_out.as_deref_mut() {
                out.push((start as u32, end as u32));
            }

            let cur_pos = doc_pos;
            doc_pos += 1;
            *dbg_walked += 1;

            // Cooperative timeout poll — every 256 docs (~16 µs of clock
            // reads per million docs, against a per-doc cost that is at
            // minimum the ~3 µs JSON parse below; the read is noise).
            //
            // The interval used to be 4 096, sized for that ~3 µs/doc floor.
            // Two separate matcher shapes break that assumption:
            //
            //   - A `script` query: even with the Painless AST cached (see
            //     `painless::compile_script_cached`), *executing* a script
            //     dominates the per-doc cost. Measured on a release build, a
            //     benign 64 KiB script runs 385 µs/doc, so 4 096 docs is a
            //     ~1.6 s stretch in which a `timeout` cannot take effect, and
            //     256 brings that to ~98 ms.
            //   - A field-less `query_string` over a wide mapping: it
            //     tokenises every text-bearing field of every document, so a
            //     few hundred documents is already several times the
            //     request's whole budget — and the scan would report
            //     `timed_out: false` after blowing straight through it.
            //
            // 256 bounds the overshoot to a few hundred documents for every
            // matcher shape, and 16× more clock reads on a million-doc scan is
            // still a rounding error against the parse.
            //
            // For scripts, 256 is an improvement, not a bound. A deliberately
            // adversarial script of legal size — flat, no closure calls,
            // tripping none of MAX_CALL_DEPTH / MAX_CALL_COUNT /
            // MAX_EVAL_DEPTH / MAX_PARSE_DEPTH / MAX_PAINLESS_STRING_LEN — was
            // measured at 1.27 s/doc, which is ~325 s per poll interval.
            // Nothing here bounds that, because there is no per-evaluation CPU
            // budget; the poll interval only decides how often an
            // already-cheap document boundary is checked. Closing that needs a
            // real time or instruction budget inside `eval_painless`, tracked
            // separately.
            if doc_pos & 0xFF == 0 {
                if let Some(dl) = deadline {
                    if std::time::Instant::now() >= dl {
                        *timed_out = true;
                        return;
                    }
                }
            }

            // Pre-filter: if the caller supplied a matching set and this
            // position isn't in it, skip the parse entirely.  We already
            // advanced `i` past the doc, so just loop.
            if let Some(filter) = pre_filter {
                if !filter.contains(&cur_pos) {
                    continue;
                }
            }

            let doc_slice = &bytes[start..end];

            // #1019 — ids-only admission. This scan feeds a caller that
            // reads nothing but `hit.id`, the sort keys are `_id`/`_doc`
            // only (gated in `search_inner`), and the query decides
            // membership without a `_source` (match_all, or an `ids`
            // clause compared by string). Extract the id straight off the
            // stored slice — BORROWED, no per-doc allocation — and admit
            // WITHOUT building the `Value` tree: the full-tree parse of
            // every stored doc was the dominant RSS transient and wall
            // time of a whole-corpus purge (issue #1019 — the residual
            // the #950 fix recorded as follow-up headroom). The version-map
            // liveness filter is kept verbatim (a tombstoned id must not be
            // admitted); the superseded-copy (`_seq_no`) skip is
            // deliberately dropped because a stale copy carries the SAME
            // id — id-set membership is all this projection may decide.
            // `extract_stored_id_str` returns `None` for escape-bearing or
            // unusual layouts; those (and queries that need `_source` to
            // test membership) fall through to the full parse below, which
            // admits with the same ids-only source cut.
            //
            // Cursor decline comes FIRST, before the liveness lookup and
            // every allocation: a delete-by-query purge walks this scan
            // once per `scroll_size` page, and every page after the first
            // re-visits all previously deleted docs — with the id-ordered
            // cursor compared as raw bytes up front, a declined doc costs
            // one prefix scan + one memcmp and nothing else (63.5 M such
            // visits measured on the 252k-doc purge benchmark before this
            // ordering). Below-cursor docs are also skipped out of
            // `total_count`; the only ids-only callers are the delete
            // loops, which read `hits.total` off page 1 (cursor `None`).
            let ids_only_admit: Option<&str> = if !ids_only {
                None
            } else {
                extract_stored_id_str(doc_slice)
            };
            if let Some(id) = ids_only_admit {
                if let Some((ref cursor, asc)) = ids_only_cursor {
                    let ord = id.as_bytes().cmp(cursor.as_bytes());
                    let at_or_below = if asc {
                        ord != std::cmp::Ordering::Greater
                    } else {
                        ord != std::cmp::Ordering::Less
                    };
                    if at_or_below {
                        continue;
                    }
                }
                // Membership without a `_source`. `None` = this query
                // needs the full parse to decide → fall through.
                let member: Option<bool> = match query {
                    QueryNode::MatchAll => Some(true),
                    QueryNode::Ids { values } => Some(values.iter().any(|v| v == id)),
                    _ => None,
                };
                if member == Some(false) {
                    continue;
                }
                if member == Some(true) {
                    let mut hit_seq_no = None;
                    let mut hit_version = None;
                    if let Some(ver) = self.store.version_map.get(id) {
                        if ver.deleted {
                            continue;
                        }
                        let (s, v) = self.hit_seq_version(id, &ver);
                        hit_seq_no = s;
                        hit_version = v;
                    }
                    *total_count += 1;
                    *dbg_admitted += 1;
                    if count_only {
                        continue;
                    }
                    if let Some(topk) = sort_topk.as_deref_mut() {
                        if seen_ids.contains(id) {
                            continue;
                        }
                        let key = compute_sort_values(
                            &Value::Null,
                            1.0,
                            id,
                            topk.fields.as_slice(),
                            self,
                        );
                        if !topk.would_admit(&key) {
                            continue;
                        }
                        seen_ids.insert(id.to_string());
                        let seq = hit_seq_no.unwrap_or(u64::MAX);
                        topk.offer_keyed(
                            Hit {
                                id: id.to_string(),
                                score: 1.0,
                                source: Value::Null,
                                seq_no: hit_seq_no,
                                version: hit_version,
                                sort: key,
                                explain: None,
                                highlight: None,
                                matched_queries: Vec::new(),
                                passage: None,
                            },
                            seq,
                        );
                        continue;
                    }
                    if all_hits.len() >= materialisation_limit {
                        if count_authoritative {
                            break;
                        }
                        continue;
                    }
                    if seen_ids.contains(id) {
                        continue;
                    }
                    seen_ids.insert(id.to_string());
                    all_hits.push(Hit {
                        id: id.to_string(),
                        score: 1.0,
                        source: Value::Null,
                        seq_no: hit_seq_no,
                        version: hit_version,
                        sort: Vec::new(),
                        explain: None,
                        highlight: None,
                        matched_queries: Vec::new(),
                        passage: None,
                    });
                    continue;
                }
            }

            let mut doc_buf = doc_slice.to_vec();
            let doc: Value = match simd_json::serde::from_slice(&mut doc_buf) {
                Ok(v) => v,
                Err(_) => continue,
            };

            let id_ref = doc.get("_id").and_then(Value::as_str).unwrap_or("");
            // Captured from the SAME version-map entry the
            // deleted/superseded check reads, so `_seq_no`/`_version` never
            // diverge from the `source` parsed above (#440).
            let mut hit_seq_no = None;
            let mut hit_version = None;
            if let Some(ver) = self.store.version_map.get(id_ref) {
                if ver.deleted {
                    continue;
                }
                // Superseded stale copy (b8 DEFECT T2): the live version
                // per the version map has a strictly newer seq than this
                // stored envelope's `_seq_no` (same predicate the merge
                // purge uses, merge.rs stale-copy skip).  Raw-source docs
                // without `_seq_no` keep the pre-fix behavior.
                if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                    if doc_seq < ver.seq_no {
                        continue;
                    }
                }
                let (s, v) = self.hit_seq_version(id_ref, &ver);
                hit_seq_no = s;
                hit_version = v;
            }

            let matched = if is_match_all {
                true
            } else if let QueryNode::Ids { values } = query {
                values.iter().any(|v| v == id_ref)
            } else {
                // The stored doc can be either:
                //   {"_id":"..","_seq_no":..,"_source":{fields}}  (envelope format)
                //   {fields}                                       (raw source, e.g. from M5.11 raw-bytes path)
                // Try _source first; fall back to the doc itself.
                let source_ref = doc.get("_source").unwrap_or(&doc);
                if needs_id_injection && source_ref.get("_id").is_none() {
                    // Inject `_id` into source so a deeply-nested Ids query
                    // (e.g. function_score -> ids) can resolve it. Only
                    // reached when `query_needs_id_injection` proved the
                    // tree actually contains one — every other query shape
                    // matches directly against the borrowed `source_ref`
                    // below, no clone.
                    let source_with_id = if let Some(obj) = source_ref.as_object() {
                        let mut o = obj.clone();
                        o.insert("_id".to_string(), Value::String(id_ref.to_string()));
                        Value::Object(o)
                    } else {
                        source_ref.clone()
                    };
                    doc_matches_query_typed(query, &source_with_id, schema)
                } else {
                    doc_matches_query_typed(query, source_ref, schema)
                }
            };

            if !matched {
                continue;
            }

            *total_count += 1;
            *dbg_admitted += 1;

            if count_only {
                continue;
            }

            // Field-sorted queries route every match into the bounded top-N
            // heap: no early stop (we must visit ALL matches so the survivors
            // are the GLOBAL top-N by the sort key), and retention is bounded
            // by the heap capacity rather than by first-N scan order.
            //
            // Hot-path discipline (search_after OOM fix): compute the sort
            // key on the BORROWED source first and reject pre-heap — hits at
            // or before the `search_after` cursor, and hits that cannot beat
            // the current heap-worst, are dropped WITHOUT cloning `_source`
            // and WITHOUT an id insert.  Pre-fix this branch cloned every
            // matching doc's source (~1 KB × 1M docs ≈ 1 GB churn/query) and
            // grew `seen_ids` to one String per match; under piled-up
            // concurrent search_after queries that ballooned RSS to an OOM
            // kill.  `seen_ids` now only tracks OFFERED hits, which is
            // bounded by heap-admission traffic (≈ cap·ln(N) typical).
            if let Some(topk) = sort_topk.as_deref_mut() {
                if seen_ids.contains(id_ref) {
                    continue;
                }
                let source_ref = doc.get("_source").unwrap_or(&doc);
                // #1019 — under the ids-only projection the score is unused
                // (the eligibility gate confined the sort to `_id`/`_doc`,
                // neither of which reads `_source` to rank), so the scorer
                // is skipped and the hit carries `source: Value::Null`
                // instead of a clone of the parsed tree — the per-hit clone
                // is what piled up in the bounded heap across a
                // whole-corpus purge.
                let score = if is_match_all || ids_only {
                    1.0
                } else {
                    scorer(source_ref, id_ref)
                };
                let key =
                    compute_sort_values(source_ref, score, id_ref, topk.fields.as_slice(), self);
                if !topk.would_admit(&key) {
                    continue;
                }
                let id: String = id_ref.to_string();
                seen_ids.insert(id.clone());
                let seq = hit_seq_no.unwrap_or(u64::MAX);
                topk.offer_keyed(
                    Hit {
                        id,
                        score,
                        source: if ids_only {
                            Value::Null
                        } else {
                            source_ref.clone()
                        },
                        seq_no: hit_seq_no,
                        version: hit_version,
                        sort: key,
                        explain: None,
                        highlight: None,
                        matched_queries: Vec::new(),
                        passage: None,
                    },
                    seq,
                );
                continue;
            }

            if all_hits.len() >= materialisation_limit {
                // Bounded collector is full.
                if count_authoritative {
                    // The EXACT `hits.total` is supplied independently (MatchAll
                    // live_doc_count / doc-values shortcut) and is overwritten
                    // by the caller after this scan, so there is nothing left to
                    // do once we have the top (from+size) sources.  Stop the
                    // scan instead of walking every remaining match — this is
                    // the O(from+size) fetch that F1 buys us.  The `*total_count`
                    // tallied so far is discarded by the caller's overwrite.
                    break;
                }
                // Count not authoritative for this shape: keep scanning to
                // tally the exact `hits.total`, just don't materialise sources.
                continue;
            }

            let id: String = id_ref.to_string();
            if seen_ids.contains(&id) {
                continue;
            }

            // #1019 — ids-only projection: no source clone, no scorer (see
            // the sort-topk branch above for the eligibility argument).
            let source = if ids_only {
                Value::Null
            } else {
                doc.get("_source").cloned().unwrap_or_else(|| doc.clone())
            };
            let score = if is_match_all || ids_only {
                1.0
            } else {
                scorer(&source, &id)
            };

            seen_ids.insert(id.clone());
            all_hits.push(Hit {
                id,
                score,
                source,
                seq_no: hit_seq_no,
                version: hit_version,
                sort: Vec::new(),
                explain: None,
                highlight: None,
                matched_queries: Vec::new(),
                passage: None,
            });
        }
    }
}

// ── do_flush ──────────────────────────────────────────────────────────────────

/// Flush the FTS memtable to a new on-disk segment.
///
/// This is a free function (not a method) so it can be called from both
/// `Index::flush()` and background tokio tasks without holding `Arc<Index>`.
///
/// The algorithm:
/// 1. Drain the memtable under a write lock, releasing it immediately.
/// 2. Flush the storage layer (writes the `.seg` file, swaps the snapshot,
///    checkpoints the WAL).
/// 3. Build the FTS inverted index files for the new segment using ordinal
///    positions (0, 1, 2, …) so that the segment search path can look up
///    stored docs by their ordinal.
///
/// RAII timer that records one `flush_duration` (seconds) observation when it
/// drops — i.e. when `do_flush_shard` returns on any path. It holds an owned
/// `Arc<Metrics>` cloned from the process-global handle so it survives across
/// the `.await`s in the flush, and is a no-op when metrics are not installed.
struct FlushDurationTimer {
    start: std::time::Instant,
    metrics: Option<std::sync::Arc<xerj_common::metrics::Metrics>>,
}
impl Drop for FlushDurationTimer {
    fn drop(&mut self) {
        if let Some(m) = &self.metrics {
            m.observe_flush(self.start.elapsed().as_secs_f64());
        }
    }
}

#[cfg(test)]
#[derive(Clone)]
struct FlushPublisherTestHook {
    callback: Arc<dyn Fn() -> bool + Send + Sync>,
    after_warm: Option<Arc<dyn Fn(&str) -> bool + Send + Sync>>,
    ledger: &'static crate::ingest_memory::Ledger,
    target_memtable: usize,
    bypass_finalize_gate: bool,
    before_blocking_spawn: Option<Arc<dyn Fn() + Send + Sync>>,
}
#[cfg(test)]
tokio::task_local! {
    static FLUSH_PUBLISHER_TEST_HOOK: FlushPublisherTestHook;
}

// This deliberately remains a free function so background tasks can own every
// flush dependency without retaining `Index`; grouping the values would only
// hide the same pipeline dependency set behind an uninformative bag of fields.
/// Disarms a reader wait on drop, including the deadline-timeout return.
struct ReaderWaitGuard<'a>(&'a crate::collection_publication::CollectionPublication);

impl Drop for ReaderWaitGuard<'_> {
    fn drop(&mut self) {
        self.0.disarm_reader();
    }
}

/// Reserves a capture slot for one `search()` attempt. Dropped when that
/// attempt returns. `note_capture_validated` is what releases a waiting
/// writer, and it fires at the capture check, not here.
struct ReaderCapture {
    publication: Arc<crate::collection_publication::CollectionPublication>,
}

impl ReaderCapture {
    fn begin(publication: &Arc<crate::collection_publication::CollectionPublication>) -> Self {
        publication.begin_capture();
        Self {
            publication: Arc::clone(publication),
        }
    }
}

impl Drop for ReaderCapture {
    fn drop(&mut self) {
        self.publication.end_capture();
    }
}

fn collection_publication_interrupted() -> EngineError {
    EngineError::Fts(anyhow::anyhow!(
        "collection publication was interrupted; reopen the index so WAL recovery can rebuild a consistent searchable state"
    ))
}

/// #1013 — typed root for the capture-retry signal so `search()` can
/// distinguish "recapture and run again" from every other `Fts` error,
/// structurally (anyhow keeps the root downcastable through `context`
/// wraps), never by matching on a message string.
#[derive(Debug, thiserror::Error)]
#[error("collection capture crossed a publication")]
struct CollectionCaptureCrossedPublication;

fn collection_capture_crossed() -> EngineError {
    EngineError::Fts(anyhow::Error::new(CollectionCaptureCrossedPublication))
}

fn is_collection_capture_retry(e: &EngineError) -> bool {
    matches!(
        e,
        EngineError::Fts(err) if err.downcast_ref::<CollectionCaptureCrossedPublication>().is_some()
    )
}

/// #1212 — the verdict of one LIVE version-map entry read during a scan whose
/// segment snapshot and memtable capture were frozen at a capture instant.
///
/// #1013 deliberately relaxed search consistency to "the capture bracket
/// needs only a writer-free instant": after the bracket validates, the scan
/// runs against immutable captured state while writers keep publishing. But
/// the per-hit liveness checks read the LIVE version map mid-scan, and a
/// merge that publishes after the capture repoints every surviving entry at
/// its output segment — a name the frozen snapshot never held. The old
/// equality check (`ver.segment_id == hit_segment`) then failed for every
/// hit from the merged-away segments and silently dropped them: short or
/// empty pages with `timed_out` absent, self-healing on the next capture.
/// Observed live as the read-back losing 49,568 of 58,568 catalog documents
/// mid-walk (issue #1212).
///
/// The fix is the invariant #1013's comment already claims for the snapshot:
/// a scan may only apply version entries that describe the world it
/// captured. An entry naming a segment outside the captured set belongs to a
/// later world and is invisible to this capture — in both directions: it
/// cannot supersede the hit, and its `seq_no`/`version` are not the hit's.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CapturedEntryVerdict {
    /// The entry describes the captured world and this hit is its live copy.
    Live,
    /// The entry describes the captured world and this hit is a tombstone or
    /// a superseded copy — the scan must drop it.
    Invisible,
    /// The entry names a publication after the capture (a merge output or a
    /// flush segment the captured snapshot never held). The hit stands; the
    /// entry's seq/version belong to that later world and must not be
    /// reported on the hit.
    PostCapture,
}

/// Does `ver` describe the captured world at all? `__memtable__` residency
/// does (buffered writes/deletes are part of the capture via the memtable
/// snapshot); a real segment does iff the captured snapshot held it.
fn entry_describes_capture(
    ver: &xerj_storage::version_map::VersionEntry,
    captured_segment_ids: &std::collections::HashSet<&str>,
) -> bool {
    let residency = ver.segment_id.as_ref();
    residency == xerj_storage::version_map::IN_MEMORY_SEGMENT_ID
        || captured_segment_ids.contains(residency)
}

/// A hit scanned out of captured segment `hit_segment`.
fn captured_verdict_for_segment_hit(
    ver: &xerj_storage::version_map::VersionEntry,
    hit_segment: &str,
    captured_segment_ids: &std::collections::HashSet<&str>,
) -> CapturedEntryVerdict {
    if !entry_describes_capture(ver, captured_segment_ids) {
        return CapturedEntryVerdict::PostCapture;
    }
    if ver.deleted || ver.segment_id.as_ref() != hit_segment {
        return CapturedEntryVerdict::Invisible;
    }
    CapturedEntryVerdict::Live
}

/// A hit the memtable capture produced (the doc was memtable-resident at
/// capture).
fn captured_verdict_for_memtable_hit(
    ver: &xerj_storage::version_map::VersionEntry,
    captured_segment_ids: &std::collections::HashSet<&str>,
) -> CapturedEntryVerdict {
    if !entry_describes_capture(ver, captured_segment_ids) {
        return CapturedEntryVerdict::PostCapture;
    }
    if ver.deleted || ver.segment_id.as_ref() != xerj_storage::version_map::IN_MEMORY_SEGMENT_ID {
        return CapturedEntryVerdict::Invisible;
    }
    CapturedEntryVerdict::Live
}

/// The #1212 decision table, pinned without a server: every cell the two
/// verdict functions can produce, and the one property the fix exists for —
/// an entry naming a segment the capture never held is PostCapture, never
/// Invisible, whichever walk asks.
#[cfg(test)]
mod captured_entry_verdict_table {
    use super::*;

    fn entry(segment: &str, deleted: bool) -> xerj_storage::version_map::VersionEntry {
        xerj_storage::version_map::VersionEntry {
            seq_no: 7,
            segment_id: segment.into(),
            deleted,
            version: 3,
        }
    }

    fn capture<'a>(segments: &[&'a str]) -> std::collections::HashSet<&'a str> {
        segments.iter().copied().collect()
    }

    #[test]
    fn residency_decides_whether_an_entry_describes_the_capture_at_all() {
        let captured = capture(&["seg-1", "seg-2"]);
        // The memtable is always part of the capture (buffered writes came
        // in through the memtable snapshot).
        assert!(entry_describes_capture(
            &entry(xerj_storage::version_map::IN_MEMORY_SEGMENT_ID, false),
            &captured
        ));
        assert!(entry_describes_capture(&entry("seg-1", false), &captured));
        assert!(entry_describes_capture(&entry("seg-2", true), &captured));
        // A merged output or flush segment the capture never held.
        assert!(!entry_describes_capture(
            &entry("seg-merged", false),
            &captured
        ));
        assert!(!entry_describes_capture(
            &entry("seg-merged", false),
            &std::collections::HashSet::new()
        ));
    }

    #[test]
    fn a_segment_hit_is_live_only_against_its_own_captured_segment() {
        let captured = capture(&["seg-1", "seg-2"]);
        assert_eq!(
            captured_verdict_for_segment_hit(&entry("seg-1", false), "seg-1", &captured),
            CapturedEntryVerdict::Live
        );
        // Tombstoned within the captured world.
        assert_eq!(
            captured_verdict_for_segment_hit(&entry("seg-1", true), "seg-1", &captured),
            CapturedEntryVerdict::Invisible
        );
        // Superseded by a copy in another CAPTURED segment — the scan must
        // still drop this one.
        assert_eq!(
            captured_verdict_for_segment_hit(&entry("seg-2", false), "seg-1", &captured),
            CapturedEntryVerdict::Invisible
        );
        // #1212: a merge that published after the capture repointed the live
        // entry at its output segment. Pre-fix this read returned Invisible
        // for every hit out of the merged-away segments and the page came
        // back short or empty.
        assert_eq!(
            captured_verdict_for_segment_hit(&entry("seg-merged", false), "seg-1", &captured),
            CapturedEntryVerdict::PostCapture
        );
        // A tombstone written by the later world cannot retire the captured
        // copy either — the delete is not yet visible to this capture.
        assert_eq!(
            captured_verdict_for_segment_hit(&entry("seg-merged", true), "seg-1", &captured),
            CapturedEntryVerdict::PostCapture
        );
    }

    #[test]
    fn a_memtable_hit_survives_a_post_capture_flush_and_drops_captured_supersessions() {
        let captured = capture(&["seg-1"]);
        assert_eq!(
            captured_verdict_for_memtable_hit(
                &entry(xerj_storage::version_map::IN_MEMORY_SEGMENT_ID, false),
                &captured
            ),
            CapturedEntryVerdict::Live
        );
        // Deleted while still memtable-resident — a captured tombstone.
        assert_eq!(
            captured_verdict_for_memtable_hit(
                &entry(xerj_storage::version_map::IN_MEMORY_SEGMENT_ID, true),
                &captured
            ),
            CapturedEntryVerdict::Invisible
        );
        // Repointed onto a segment the capture DID hold: superseded within
        // the captured world, drop the captured memtable copy.
        assert_eq!(
            captured_verdict_for_memtable_hit(&entry("seg-1", false), &captured),
            CapturedEntryVerdict::Invisible
        );
        // #1212 flush flavor: the entry now names the flush segment, which
        // the capture never held. Pre-fix this was the equality check's
        // `!= __memtable__` arm — Invisible — and the captured memtable's
        // copy vanished from the page.
        assert_eq!(
            captured_verdict_for_memtable_hit(&entry("seg-flush", false), &captured),
            CapturedEntryVerdict::PostCapture
        );
        // ...including when the index had no segments at all at capture.
        assert_eq!(
            captured_verdict_for_memtable_hit(
                &entry("seg-flush", false),
                &std::collections::HashSet::new()
            ),
            CapturedEntryVerdict::PostCapture
        );
    }
}

/// Resolve the two flush deadlines for one index.
///
/// Environment overrides win over the config file, matching `XERJ_FIN_CONC`.
/// A value that is not a whole number of seconds in `1..=86_400` is ignored
/// and reported; an override that would make the caller give up before
/// admission can finish is raised to the admission bound.
fn configured_flush_timeouts_ms(config: &Config) -> (u64, u64) {
    let admit = resolve_flush_timeout_secs(
        "XERJ_FLUSH_ADMIT_TIMEOUT_SECS",
        config.engine.flush_admit_timeout_secs,
        std::env::var("XERJ_FLUSH_ADMIT_TIMEOUT_SECS")
            .ok()
            .as_deref(),
    );
    let mut overall = resolve_flush_timeout_secs(
        "XERJ_FLUSH_TIMEOUT_SECS",
        config.engine.flush_timeout_secs,
        std::env::var("XERJ_FLUSH_TIMEOUT_SECS").ok().as_deref(),
    );
    if overall < admit {
        warn!(
            admit_secs = admit,
            flush_secs = overall,
            "flush timeout is shorter than the admission timeout; raising it so a flush \
             can finish waiting for a permit"
        );
        overall = admit;
    }
    (admit.saturating_mul(1000), overall.saturating_mul(1000))
}

/// `configured` is the validated config value. `env_value` is the raw
/// override, already read by the caller so tests can pass it without
/// touching the process environment.
fn resolve_flush_timeout_secs(name: &str, configured: u64, env_value: Option<&str>) -> u64 {
    let Some(raw) = env_value.map(str::trim).filter(|s| !s.is_empty()) else {
        return configured;
    };
    let max = xerj_common::config::EngineConfig::MAX_FLUSH_TIMEOUT_SECS;
    match raw.parse::<u64>() {
        Ok(secs) if (1..=max).contains(&secs) => secs,
        _ => {
            warn!(
                "{name}={raw} is not a whole number of seconds from 1 to {max}; using {configured}s"
            );
            configured
        }
    }
}

fn flush_admit_timeout_error(index: &str, what: &str, budget: std::time::Duration) -> EngineError {
    warn!(
        index,
        wait = what,
        budget_ms = budget.as_millis() as u64,
        "flush timed out waiting for admission; the memtable was not frozen"
    );
    EngineError::Common(xerj_common::XerjError::internal(format!(
        "index [{index}] flush timed out after {budget:?} waiting for {what}; \
         the memtable was not frozen, so this flush can be retried"
    )))
}

fn flush_budget_timeout_error(index: &str, budget: std::time::Duration) -> EngineError {
    warn!(
        index,
        budget_ms = budget.as_millis() as u64,
        "flush timed out; the publish coordinator was left running"
    );
    EngineError::Common(xerj_common::XerjError::internal(format!(
        "index [{index}] flush timed out after {budget:?}; the publish coordinator was left \
         running so a publication already past the freeze can finish, and this refresh can be \
         retried"
    )))
}

/// Wait for a flush-admission permit.
///
/// A closed semaphore still yields `Ok(None)`, which is what the old
/// `.ok()` did. A timeout is an error and does not hold a permit: the
/// acquire future is dropped, so the wait is cancelled before the freeze.
async fn wait_for_flush_permit<T>(
    index: &str,
    what: &str,
    budget: std::time::Duration,
    acquire: impl std::future::Future<Output = std::result::Result<T, tokio::sync::AcquireError>>,
) -> Result<Option<T>> {
    match within_wall_clock(budget, acquire).await {
        Some(Ok(permit)) => Ok(Some(permit)),
        Some(Err(_)) => Ok(None),
        None => Err(flush_admit_timeout_error(index, what, budget)),
    }
}

/// Await `fut` for at most `budget` of wall-clock time.
///
/// The flush deadlines (#1635) are operator budgets in real seconds, so they
/// are measured with [`std::time::Instant`], not tokio's clock. The two differ
/// when the clock is paused (`#[tokio::test(start_paused = true)]`): a paused
/// runtime that goes idle auto-advances to its next timer. A flush waiting on
/// the process-global finalize gate, whose permit another runtime holds, is
/// idle on its own runtime, so a plain `tokio::time::timeout(120s)` fired at
/// once and failed a healthy flush with "timed out after 120s". A tokio timer
/// never fires before the wall-clock deadline on a running clock, so the
/// early-fire branch below is only taken when the clock is paused. It waits a
/// real slice on the blocking pool (no timer, so no auto-advance) and tries
/// again. `None` means the wall-clock budget ran out; the future is dropped.
/// While blocking-pool work is in flight a paused clock does not advance at
/// all, so the deadline is only checked once that work (or the future)
/// makes progress; a running clock has no such gap.
async fn within_wall_clock<F: std::future::Future>(
    budget: std::time::Duration,
    fut: F,
) -> Option<F::Output> {
    let deadline = std::time::Instant::now() + budget;
    tokio::pin!(fut);
    loop {
        let left = deadline.saturating_duration_since(std::time::Instant::now());
        if let Ok(output) = tokio::time::timeout(left, &mut fut).await {
            return Some(output);
        }
        let left = deadline.saturating_duration_since(std::time::Instant::now());
        if left.is_zero() {
            return None;
        }
        let nap = left.min(std::time::Duration::from_millis(5));
        tokio::select! {
            biased;
            output = &mut fut => return Some(output),
            _ = tokio::task::spawn_blocking(move || std::thread::sleep(nap)) => {}
        }
    }
}

/// Bound one spawned flush task.
///
/// Dropping the [`JoinHandle`] on timeout detaches the task. It does not
/// abort it, so a publication that has already frozen the memtable keeps
/// its non-cancellable worker (#1015).
async fn await_flush_task(
    index: &str,
    budget: std::time::Duration,
    task: tokio::task::JoinHandle<Result<()>>,
) -> Result<()> {
    match within_wall_clock(budget, task).await {
        Some(Ok(result)) => result,
        Some(Err(error)) => Err(EngineError::Common(xerj_common::XerjError::internal(
            format!("index [{index}] flush task failed: {error}"),
        ))),
        None => Err(flush_budget_timeout_error(index, budget)),
    }
}

#[allow(clippy::too_many_arguments)]
async fn do_flush_shard(
    shard_idx: usize,
    store: Arc<IndexStore>,
    memtable: Arc<crate::memtable::ShardedFtsMemtable>,
    collection_publication: Arc<crate::collection_publication::CollectionPublication>,
    registry: Arc<AnalyzerRegistry>,
    data_dir: PathBuf,
    field_configs: HashMap<String, xerj_fts::index::FieldIndexConfig>,
    excluded_fts_fields: std::collections::HashSet<String>,
    // Fields the mapping says get no doc-values column. Threaded through for
    // the same reason as `excluded_fts_fields`: this is a free fn with no
    // access to `Index`.
    dv_skip_for_flush: std::collections::HashSet<String>,
    on_drained: impl FnOnce() + Send + 'static,
    // Publish-time cache warm (see `warm_segment_at_publish`): the index's
    // read-path caches, threaded through because this is a free fn without
    // access to `Index`.
    warm_caches: PublishWarmCaches,
    index_name: String,
    admit_timeout: std::time::Duration,
    #[cfg(test)] test_hook: Option<FlushPublisherTestHook>,
) -> Result<()> {
    // #1226 — re-check emptiness BEFORE the process-global finalize gate.
    // `Index::refresh`/`Index::flush` already skip shards that look empty
    // when they build the fan-out (#1319), but this task may have waited on
    // `flush_sema` since then while a concurrent flush drained the shard,
    // and the ingest-triggered paths call in here directly. Same outcome as
    // the empty-drain branch below (`on_drained` fired, nothing published),
    // minus a wait behind every other index's in-flight finalize.
    if memtable.shard_load(shard_idx).0 == 0 {
        on_drained();
        return Ok(());
    }
    // Acquire admission before draining. Once the memtable has been drained
    // there must be no cancellation point until a non-cancellable blocking
    // worker owns both rollback data and the publication barrier.
    #[cfg(test)]
    let bypass_finalize_gate = test_hook
        .as_ref()
        .is_some_and(|hook| hook.bypass_finalize_gate);
    #[cfg(not(test))]
    let bypass_finalize_gate = false;
    let fin_permit = if bypass_finalize_gate {
        None
    } else {
        // #1635 — this acquire used to wait forever. A finalize that holds
        // the process-global permit and never returns parked every later
        // `_refresh` with no error. Timing out here is before the freeze,
        // so the memtable is unchanged and the caller can retry.
        match wait_for_flush_permit(
            &index_name,
            "the finalize gate",
            admit_timeout,
            crate::flush_finalize_gate().acquire(),
        )
        .await
        {
            Ok(permit) => permit,
            Err(error) => {
                on_drained();
                return Err(error);
            }
        }
    };
    // #2427 — while the parent RSS breaker is engaged, finalizes run one at
    // a time (see `flush_pressure_gate`). Same deadline and same
    // before-the-freeze failure as the finalize gate above.
    let pressure_permit = if !bypass_finalize_gate
        && crate::governor::global().is_some_and(|g| g.memory_breaker_engaged())
    {
        match wait_for_flush_permit(
            &index_name,
            "the memory-pressure flush gate",
            admit_timeout,
            crate::flush_pressure_gate().acquire(),
        )
        .await
        {
            Ok(permit) => permit,
            Err(error) => {
                drop(fin_permit);
                on_drained();
                return Err(error);
            }
        }
    } else {
        None
    };
    // #1015 — NO collection-publication guard here.  The drain below is a
    // FREEZE, not a removal: the claimed docs stay reader-visible in the
    // shard's frozen generations for the whole segment build, so there is
    // no reader-visible state change to guard against yet.  The bracket is
    // opened (in the finalize worker) only around the publish phase —
    // version-map repoint + snapshot swap + generation retire — which is
    // millisecond-scale.  Pre-#1015 the guard spanned drain → build →
    // publish (~600 ms/flush), and every capture-boundary retry under a
    // flush storm paid that window.
    // V4 M4.5: no outer flush_lock — concurrent flushes are allowed.  The
    // memtable write lock below is the only atomicity point we need for
    // correctness (each concurrent flush drains a disjoint set of docs
    // and writes an independent segment).

    // ── Phase 1: atomic drain of BOTH memtables under the FTS write lock ──
    //
    // Ingest blocks only for the duration of this drain — which is fast
    // (memory move, no I/O).  Once we drop `mem`, new ingests can proceed
    // immediately against a fresh memtable while we do the expensive
    // segment + FTS side-car write.
    //
    // Correctness: the ingest path takes the FTS RwLock write BEFORE
    // pushing to both the FTS memtable and the storage memtable (via
    // `wal_append_batch` → storage mutex).  So while we hold the FTS write
    // lock, neither memtable can receive new entries.  Draining them both
    // under this single lock guarantees the FTS drain set == storage drain
    // set — and therefore the ordinals we encode in FTS side-cars match
    // the row positions in the stored section.
    // Peek BEFORE drain to determine if docs came from raw-bytes or FTS insert.
    let is_raw_bytes_path = memtable.peek_shard_has_raw_bytes(shard_idx);
    #[cfg(test)]
    let test_target = Arc::as_ptr(&memtable) as usize;

    // THROWAWAY prof: per-flush finalize breakdown, gated on XERJ_PROF.
    let prof = std::env::var_os("XERJ_PROF").is_some();
    // Run the Phase-1 prep `par_iter` (JIT JSON re-parse + text-field
    // extraction, ~140 ms/flush) on the deprioritised INGEST pool rather
    // than the global rayon pool.  Reason: the sidecar build already does
    // this (see `build_fts`), but the prep par_iter did NOT — so a 16-wide
    // flush storm floods the GLOBAL rayon pool that concurrent search/agg
    // par_iters run on, queuing reads behind ~140 ms of flush CPU and
    // spiking read-under-write p99.  Offloading it to `background_pool`
    // (nice-10, separate from the search pool) keeps reads off that queue.
    // Env-overridable (default ON) for A/B — set XERJ_PREP_OFFLOAD=0 to
    // reproduce the pre-fix global-pool behaviour.
    let prep_offload = std::env::var("XERJ_PREP_OFFLOAD")
        .map(|v| v != "0" && !v.eq_ignore_ascii_case("false"))
        .unwrap_or(true);
    let t_flush_start = std::time::Instant::now();
    let prof_drain_us: u128;
    let mut prof_prep_us: u128 = 0;

    let drained_opt: Option<(
        Vec<(
            String,
            std::collections::HashMap<String, xerj_fts::index::FieldValues>,
            std::sync::Arc<serde_json::Value>,
        )>,
        xerj_storage::index_store::DrainedMemtable,
        crate::memtable::FrozenClaim,
    )> = {
        let t_drain = std::time::Instant::now();
        #[cfg(test)]
        let test_ledger = test_hook
            .as_ref()
            .filter(|hook| hook.target_memtable == test_target)
            .map(|hook| hook.ledger);
        #[cfg(test)]
        let (raw, claim) = if let Some(ledger) = test_ledger {
            memtable.freeze_shard_accounted_for_test(shard_idx, is_raw_bytes_path, ledger)
        } else {
            memtable.freeze_shard_accounted(shard_idx, is_raw_bytes_path)
        };
        #[cfg(not(test))]
        let (raw, claim) = memtable.freeze_shard_accounted(shard_idx, is_raw_bytes_path);
        prof_drain_us = t_drain.elapsed().as_micros();
        let t_prep = std::time::Instant::now();
        let _ = &t_prep;
        if raw.is_empty() {
            None
        } else {
            // M5.4 was a pure-perf optimisation that skipped Value-parse
            // + extract_text_fields when the shard's first entry was the
            // turbo raw-bytes path (CLI bulk).  The cost: the segment FTS
            // sidecar got an empty input set, the per-segment match_all
            // enumeration uses `seg.ids` + segment-FTS as its source of
            // truth, and the docs in raw-bytes segments were invisible
            // to match_all/term/range and the brute-force kNN pre-filter.
            // POV battery (2026-04-25) caught this as a 5-9% missing-doc
            // rate after `?refresh=true` on every bulk.  The save was
            // ~700ns/doc, but at 100 K docs/s that's still <100 ms of
            // CPU per flush — irrelevant against the 50-100 ms segment
            // write.  Always build the drained_fts payload so the FTS
            // sidecar carries the full doc set.
            // Rayon: the per-doc text-field extraction (plus the JSON
            // parse on the raw-bytes path) is pure and was a ~140 ms
            // SERIAL stretch per 31k-doc flush on the flush task —
            // par_iter preserves order and spreads it across the pool.
            let build_drained_fts = || {
                use rayon::prelude::*;
                raw.par_iter()
                    .map(|(_seq, doc_id, arc, bytes)| {
                        // Raw-bytes path stores Value::Null in `arc` and
                        // the actual JSON in `bytes` (skip-parse drain).
                        // Re-parse just-in-time for FTS field extraction.
                        // P2.2: the parsed path SHARES the memtable's Arc
                        // instead of deep-cloning every Value (~3.7s CPU
                        // per 1M docs on the background flush thread).
                        let val: std::sync::Arc<serde_json::Value> = if !arc.is_null() {
                            std::sync::Arc::clone(arc)
                        } else if !bytes.is_empty() {
                            std::sync::Arc::new(
                                serde_json::from_slice::<serde_json::Value>(bytes)
                                    .unwrap_or(serde_json::Value::Null),
                            )
                        } else {
                            std::sync::Arc::new(serde_json::Value::Null)
                        };
                        let fields = crate::memtable::extract_field_values_excluding(
                            &val,
                            &excluded_fts_fields,
                        );
                        (doc_id.clone(), fields, val)
                    })
                    .collect()
            };
            // Off the global rayon pool (default) so the flush-storm prep
            // doesn't queue ahead of concurrent search/agg par_iters.
            let drained_fts: Vec<(
                String,
                std::collections::HashMap<String, xerj_fts::index::FieldValues>,
                std::sync::Arc<serde_json::Value>,
            )> = if prep_offload {
                crate::background_pool().install(build_drained_fts)
            } else {
                build_drained_fts()
            };

            let storage_entries: Vec<xerj_storage::index_store::MemEntry> = raw
                .into_iter()
                .map(|(seq_no, doc_id, arc, raw_bytes)| {
                    let charge = if !raw_bytes.is_empty() {
                        raw_bytes.len() as u64
                    } else {
                        xerj_storage::index_store::estimate_value_bytes(&arc)
                    };
                    xerj_storage::index_store::MemEntry {
                        seq_no,
                        doc_id,
                        source: Some(arc),
                        source_bytes: raw_bytes,
                        charge,
                    }
                })
                .collect();
            let storage_drained = xerj_storage::index_store::DrainedMemtable {
                entries: storage_entries,
            };
            prof_prep_us = t_prep.elapsed().as_micros();
            Some((drained_fts, storage_drained, claim))
        }
    };

    // CRITICAL: fire `on_drained` BEFORE the early-return and BEFORE
    // Phase 2's slow segment I/O.  For callers holding a flush_sema
    // permit, this drops it now — releasing memtable-size back-pressure
    // (memtable bytes are already down post-drain) AND freeing the
    // permit so the next batch's per-shard threshold check can dispatch
    // a fresh flush task in parallel with our own Phase 2 I/O.  Pre-fix,
    // the permit was held for the entire do_flush_shard call including
    // the ~50-100 ms segment write, which capped concurrent drain
    // parallelism at `flush_sema = 16` even though the expensive
    // segment-write I/O could comfortably run at higher concurrency on
    // tmpfs.
    on_drained();

    let (drained_fts, storage_drained, claim) = match drained_opt {
        Some(pair) => pair,
        None => {
            // Another concurrent flush may have claimed this shard after the
            // caller observed it as non-empty (or the shard held only
            // unclaimed leftovers with nothing new). No collection state
            // changed in this attempt — the claim dropped inside the block
            // above already released the frozen generations back to
            // "unclaimed" so the next flush recycles them (#1015), and no
            // publication bracket was ever opened.
            return Ok(());
        }
    };
    let drained_fts = Arc::new(drained_fts);
    let storage_drained = Arc::new(storage_drained);

    // RC4 W4 item 2: record flush latency. Armed only past the empty-drain
    // early-return above, so the histogram reflects real segment builds; fires
    // on drop when this fn returns (covers the multiple Ok(()) exits below).
    let _flush_timer = FlushDurationTimer {
        start: std::time::Instant::now(),
        metrics: crate::engine_metrics().cloned(),
    };

    // ── Phase 2: build segment + FTS side-cars without holding any lock ───
    //
    // From this point on, new ingests are appending to a fresh memtable in
    // parallel with the I/O we're about to do.  The only remaining
    // serialisation point is `flush_lock` (outer mutex on this function).
    let segments_dir = data_dir.join("segments");
    let registry_for_build = Arc::clone(&registry);
    let fts_doc_count = drained_fts.len();
    let drained_fts_for_build = Arc::clone(&drained_fts);
    let segments_dir_for_dv = segments_dir.clone();
    let store_for_warm = Arc::clone(&store);
    // POV battery (B-3) caught that gating FTS+DV on the raw-bytes path
    // hides docs from match_all/term/range and from the kNN brute-force
    // pre-filter — the per-segment enumeration uses these sidecars as
    // its source of truth.  The "skip if raw-bytes" optimisation was
    // only meant for the turbo CLI path where the search cycle never
    // runs against the same data; in any user-facing flow we MUST
    // build them.  The cost (~700 ns / doc) is irrelevant next to the
    // 50-100 ms segment write that follows, and 100K-doc/s ingest
    // bench numbers are unaffected.
    let failed_warm_caches = warm_caches.clone();
    let warmed_segment_id = Arc::new(parking_lot::Mutex::new(None::<String>));
    let callback_warmed_segment_id = Arc::clone(&warmed_segment_id);
    #[cfg(test)]
    let before_blocking_spawn = test_hook
        .as_ref()
        .filter(|hook| hook.target_memtable == test_target)
        .and_then(|hook| hook.before_blocking_spawn.as_ref().map(Arc::clone));
    let build_fts = move |meta: &xerj_storage::segment::SegmentMeta| -> xerj_storage::Result<()> {
        // #804: count the flush-written segment's on-disk bytes (the sealed
        // `.seg` whose `size_bytes` this closure receives).
        if let Some(m) = crate::engine_metrics() {
            m.record_bytes_written(meta.size_bytes);
        }
        #[cfg(test)]
        let test_callback = test_hook
            .as_ref()
            .filter(|hook| hook.target_memtable == test_target)
            .map(|hook| Arc::clone(&hook.callback));
        #[cfg(test)]
        let after_warm_callback = test_hook
            .as_ref()
            .filter(|hook| hook.target_memtable == test_target)
            .and_then(|hook| hook.after_warm.as_ref().map(Arc::clone));
        #[cfg(test)]
        if let Some(callback) = test_callback {
            if callback() {
                return Err(std::io::Error::other("injected flush publisher failure").into());
            }
        }
        // Whole side-car build runs on the dedicated ingest pool so a
        // flush burst can't queue search/agg par_iters behind it on the
        // global rayon pool (read-under-write; see `crate::ingest_pool`).
        crate::background_pool().install(|| -> xerj_storage::Result<()> {
            // ── Doc-values side-car (always built) ────────────────────
            let t_dv = std::time::Instant::now();
            {
                let columns = build_doc_value_columns(
                    drained_fts_for_build
                        .iter()
                        .map(|(_id, _fields, src)| Some(&**src)),
                    &dv_skip_for_flush,
                );
                if !columns.is_empty() {
                    write_doc_values_sidecar(&segments_dir_for_dv, meta.id.as_str(), &columns)
                        .map_err(|error| {
                            xerj_storage::StorageError::Io(std::io::Error::other(format!(
                                "doc-values side-car write failed: {error:#}"
                            )))
                        })?;
                }
            }
            let dv_us = t_dv.elapsed().as_micros();
            let mut fts_add_us: u128 = 0;
            let mut fts_finish_us: u128 = 0;
            // Build FTS sidecars when the drained docs have inverted-index data.
            if fts_doc_count > 0 {
                let mut fts_writer = xerj_fts::index::FtsIndexWriter::new(
                    &segments_dir,
                    meta.id.as_str(),
                    Arc::clone(&registry_for_build),
                );
                for (field_name, cfg) in &field_configs {
                    fts_writer.configure_field(field_name.clone(), cfg.clone());
                }
                let t_add = std::time::Instant::now();
                fts_writer.add_documents_parallel(&drained_fts_for_build);
                fts_add_us = t_add.elapsed().as_micros();
                let t_fin = std::time::Instant::now();
                // The data-dir format marker is a fence, not a side-car. If
                // that preflight fails, this flush must fail and leave the
                // documents uncommitted: a retry then writes the marker and
                // the encoded side-cars. Publishing a no-FTS segment here
                // would clear the memtable and skip that recovery.
                let case_distinguished =
                    fts_writer.uses_case_distinguished_field_filename_components();
                let encoded =
                    !case_distinguished && fts_writer.uses_encoded_field_filename_components();
                if case_distinguished {
                    store_for_warm.ensure_fts_case_distinguished_field_component_format()?;
                } else if encoded {
                    store_for_warm.ensure_fts_encoded_field_component_format()?;
                }
                // #2349 — a side-car publish that fails on a case-folding
                // volume used to fail this flush, and the aggregate `-docs`
                // refresh then aborted the whole autoindex. When the partial
                // files can be removed, keep the stored segment: search scans
                // it, and a later merge rebuilds full text. The error logged
                // by `degrade_fts_publish` names the path and the OS error.
                let segment_id_for_fts = meta.id.clone();
                let publish_result = (move || -> anyhow::Result<()> {
                    if case_distinguished {
                        fts_writer.publish_case_distinguished_filename_layout()?;
                    } else if encoded {
                        fts_writer.publish_encoded_filename_layout()?;
                    }
                    fts_writer.finish()?;
                    Ok(())
                })();
                if let Err(error) = publish_result {
                    degrade_fts_publish(&segments_dir, &segment_id_for_fts, &format!("{error:#}"))
                        .map_err(xerj_storage::StorageError::Io)?;
                }
                fts_finish_us = t_fin.elapsed().as_micros();
            }
            if prof {
                eprintln!(
                    "XERJ_PROF flush-sidecar docs={} dv_us={} fts_add_us={} fts_finish_us={}",
                    fts_doc_count, dv_us, fts_add_us, fts_finish_us
                );
            }
            // Publish-time cache warm — MUST run here, inside the finaliser's
            // pre-publish callback: the snapshot rcu that makes this segment
            // visible happens right after `post_finish` returns, so by the
            // time any query can see the segment its stored slices, dv
            // columns, and sort shadows are already hot.  (A post-finalize
            // warm left a ~250 ms visible-but-cold window per flush storm;
            // 64 racing queries each decompressed all 16 fresh segments
            // inside it — the dec≈900 ms stall episodes.)
            *callback_warmed_segment_id.lock() = Some(meta.id.clone());
            warm_segment_at_publish(
                &store_for_warm,
                &segments_dir_for_dv,
                &warm_caches,
                meta.id.as_str(),
                meta.doc_count,
            );
            #[cfg(test)]
            if let Some(callback) = after_warm_callback {
                if callback(meta.id.as_str()) {
                    return Err(
                        std::io::Error::other("injected post-warm publisher failure").into(),
                    );
                }
            }
            Ok(())
        })?;
        let _ = &segments_dir;
        let _ = &drained_fts_for_build;

        Ok(())
    };

    // Hand the pre-drained storage entries to the finaliser.
    //
    // The segment encode + side-car build (CPU-heavy, ~600 ms) runs on the
    // deprioritised background pool (build_fts's inner install() is a
    // same-pool no-op).  Two flush-storm mitigations wrap it:
    //   1. `flush_finalize_gate()` bounds how many shard finalizes run at
    //      once, staggering the 16-wide storm's core contention off the
    //      readers (see the gate's doc comment for the measured win).
    //   2. `spawn_blocking` runs the (blocking) finalize on a blocking
    //      thread instead of inline, so it never parks a tokio async worker
    //      — a 16-wide storm used to park up to 16 workers, starving the
    //      concurrent bulk clients' HTTP handling and the reader's search
    //      dispatch.
    let t_finalize = std::time::Instant::now();
    let store_for_finalize = Arc::clone(&store);
    let storage_drained_for_finalize = Arc::clone(&storage_drained);
    // #1015 — the claim rides the coordinator into the worker: the build
    // holds it (frozen generations stay reader-visible), publish RETIRES it
    // inside the bracket, and every failure path releases it.
    let claim_for_finalize = claim;
    // A dedicated async coordinator owns and awaits the queued blocking job.
    // Dropping/cancelling the API caller merely detaches this coordinator;
    // it continues to own the blocking JoinHandle and the worker-captured
    // publication transaction until commit or rollback.
    let finalize_coordinator = tokio::spawn(async move {
        #[cfg(test)]
        if let Some(callback) = before_blocking_spawn {
            callback();
        }
        let joined = tokio::task::spawn_blocking(move || {
            let _fin_permit = fin_permit;
            let _pressure_permit = pressure_permit;
            // This lease lives in the blocking worker, not either async waiter.
            // It spans build→publish exactly as before: it tracks the caches
            // `build_fts` warms so a failed publication can evict them.
            let lease =
                PrePublicationLease::tracked(failed_warm_caches, Arc::clone(&warmed_segment_id));
            // ── BUILD — NO publication bracket (#1015).  The frozen
            // generations keep the drained docs fully reader-visible
            // (postings, doc-values, sources) while the segment and its
            // side-cars are written; a search racing the build sees the
            // exact same doc set as before the flush started.  ──
            let built = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                crate::background_pool().install(|| {
                    store_for_finalize.build_flush_segment(&storage_drained_for_finalize, build_fts)
                })
            }));
            let meta = match built {
                Ok(Ok(meta)) => meta,
                Ok(Err(error)) => {
                    // Build failed before anything reader-visible happened:
                    // release the claim — the frozen generations stay
                    // readable and unclaimed, so the next flush of this
                    // shard recycles them.  This pointer-flag flip replaces
                    // the old `restore_failed_flush` re-insert entirely
                    // (the docs never left the view, so there is nothing to
                    // re-insert and no version-map resurrection guard to
                    // re-check).
                    claim_for_finalize.release();
                    return Ok(Err(error));
                }
                Err(payload) => {
                    claim_for_finalize.release();
                    std::panic::resume_unwind(payload);
                }
            };
            // ── PUBLISH — the ONLY reader-visible instant (#1015).  The
            // bracket opened here spans: version-map repoint, the snapshot
            // rcu, the frozen-generation retire, and the guard commit —
            // millisecond-scale.  A capture that straddles any part of it
            // fails the #1014 evenness check and retries on the next
            // instant, instead of retrying against the full drain+build
            // (~600 ms) window the old pre-drain bracket held.  ──
            let mut collection_publication_guard = match collection_publication.begin() {
                Ok(guard) => guard,
                Err(_) => {
                    claim_for_finalize.release();
                    return Err(collection_publication_interrupted());
                }
            };
            let published = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                crate::background_pool().install(|| {
                    store_for_finalize.publish_flush_segment(&storage_drained_for_finalize, &meta)
                })
            }));
            let outcome = match published {
                Ok(Ok(
                    outcome @ xerj_storage::index_store::FlushFinalizeOutcome::Published { .. },
                )) => {
                    // Retire INSIDE the bracket, immediately after the
                    // snapshot swap: "the segment is in the snapshot" and
                    // "the frozen docs left the memtable" are one atomic
                    // instant for capturing readers.  The freed bytes leave
                    // the memtable aggregate here (they were resident — and
                    // charged — for the whole build).
                    let _retained = claim_for_finalize.retire();
                    collection_publication_guard.commit();
                    // finalize published the snapshot before it returned;
                    // commit the lease while still in the worker, no await.
                    lease.commit();
                    outcome
                }
                Ok(Ok(xerj_storage::index_store::FlushFinalizeOutcome::Empty)) => {
                    // publish_flush_segment never returns Empty on a
                    // non-empty drain set (build_flush_segment errors
                    // first); handle it defensively as a failure.
                    claim_for_finalize.release();
                    collection_publication_guard.cancel();
                    xerj_storage::index_store::FlushFinalizeOutcome::Empty
                }
                Ok(Err(error)) => {
                    // Publication failed and was rolled back (failpoints
                    // included): the segment is abandoned, the version map
                    // is restored, and the docs must stay visible — release
                    // the claim so the next flush retries them.
                    claim_for_finalize.release();
                    collection_publication_guard.cancel();
                    return Ok(Err(error));
                }
                Err(payload) => {
                    claim_for_finalize.release();
                    collection_publication_guard.cancel();
                    std::panic::resume_unwind(payload);
                }
            };
            // ── POST-publish maintenance — OUTSIDE the bracket (#1015):
            // the bucket catalog PUT is network I/O and the WAL
            // checkpoint/prune takes locks; neither belongs between
            // `begin()` and `commit()`.  Deferred failures are warn-only —
            // the segment is already published.  ──
            if let Err(error) =
                store_for_finalize.after_flush_publish(&storage_drained_for_finalize, &meta)
            {
                tracing::warn!(
                    error = %error,
                    segment_id = %meta.id,
                    "flush maintenance deferred after publication"
                );
            }
            Ok(Ok(outcome))
        })
        .await;
        match joined {
            Ok(result) => result,
            Err(join_e) => Err(EngineError::Common(xerj_common::XerjError::internal(
                format!("flush finalizer task failed before publication: {join_e}"),
            ))),
        }
    });
    let finalize_outcome = match finalize_coordinator.await {
        Ok(inner) => inner,
        Err(join_e) => {
            return Err(EngineError::Common(xerj_common::XerjError::internal(
                format!("flush coordinator task failed: {join_e}"),
            )));
        }
    };
    let meta = match finalize_outcome {
        Ok(Ok(xerj_storage::index_store::FlushFinalizeOutcome::Published { meta, .. })) => meta,
        Ok(Ok(xerj_storage::index_store::FlushFinalizeOutcome::Empty)) => {
            tracing::warn!("storage finalize returned None — unexpected");
            return Ok(());
        }
        Ok(Err(e)) => {
            return Err(e.into());
        }
        Err(e) => {
            return Err(e);
        }
    };
    // #804: `xerj_bytes_written_total` was registered but nothing ever
    // incremented it, so it stayed 0 regardless of write volume. A flush is
    // the actual byte-producing event on this path; `meta.size_bytes` is the
    // freshly-written `.seg` file's own size (set from the encoded buffer
    // length in `SegmentWriter::finish`), so this is one real, non-double-
    // counted number per flush — not an estimate.
    if let Some(m) = crate::engine_metrics() {
        m.bytes_written.inc_by(meta.size_bytes);
    }
    if prof {
        eprintln!(
            "XERJ_PROF flush-total shard={} docs={} drain_us={} prep_us={} finalize_us={} total_us={}",
            shard_idx,
            fts_doc_count,
            prof_drain_us,
            prof_prep_us,
            t_finalize.elapsed().as_micros(),
            t_flush_start.elapsed().as_micros()
        );
    }

    info!(
        segment_id = meta.id.as_str(),
        doc_count = fts_doc_count,
        "memtable flushed to segment with FTS index"
    );
    Ok(())
}

// ── Sync flush coordination ───────────────────────────────────────────────────
//
// Rayon-scanner ingest (`xerj index`) pre-refactor called
// `rt_handle.block_on(index_batch_turbo_raw(..))` for every batch — ~40 % of
// syscall time was futex from those crossings.  `SyncFlushCoord` removes the
// hot-path crossing.  The sync ingest method (`index_batch_sync_raw`) is fully
// synchronous; when a shard crosses its per-shard threshold it uses the
// coord's **cached tokio Handle** to `Handle::spawn` a `do_flush_shard` task.
// `Handle::spawn` is a handful of atomics plus an mpsc send — no block_on,
// no dedicated flusher thread, no per-batch runtime crossing.  Back-pressure
// is a plain `std::thread::sleep` (nanosleep syscall) instead of
// `tokio::time::sleep` (timer wheel + semaphore + task wake).

pub(crate) struct SyncFlushCoord {
    /// Cached runtime handle captured at Index construction (when we're
    /// guaranteed to be inside `#[tokio::main]`).  Ingest threads use it
    /// to dispatch flush tasks without crossing runtime boundaries on
    /// every batch.
    rt: Option<tokio::runtime::Handle>,
    /// Cached FTS field configs — built once on first flush (requires a
    /// single `schema.read().await` under block_on) and reused.
    field_configs_cache:
        parking_lot::RwLock<Option<HashMap<String, xerj_fts::index::FieldIndexConfig>>>,
    /// Drain-complete signal.  Back-pressure in `index_batch_sync_raw`
    /// used `std::thread::sleep(5 ms) × 10` loops while memtable was
    /// above soft-block — 50 ms of wasted wall-time per batch even if
    /// a drain completed 1 ms in.  Now ingest threads `wait_for(5 ms)`
    /// on this Condvar and `on_drained` callbacks `notify_all`, so a
    /// drain wakes every blocked ingest thread within microseconds.
    drain_mu: parking_lot::Mutex<()>,
    drain_cv: parking_lot::Condvar,
}

impl SyncFlushCoord {
    fn new() -> Self {
        Self {
            rt: tokio::runtime::Handle::try_current().ok(),
            field_configs_cache: parking_lot::RwLock::new(None),
            drain_mu: parking_lot::Mutex::new(()),
            drain_cv: parking_lot::Condvar::new(),
        }
    }

    pub(crate) fn runtime(&self) -> Option<&tokio::runtime::Handle> {
        self.rt.as_ref()
    }

    /// Wake every ingest thread currently blocked on back-pressure.
    /// Called from `on_drained` callbacks right after Phase 1 drain
    /// completes — at that moment memtable bytes have dropped, so any
    /// back-pressure gate is potentially clearable.
    pub(crate) fn notify_drain(&self) {
        let _g = self.drain_mu.lock();
        self.drain_cv.notify_all();
    }

    /// Block until a drain fires (any shard) or `timeout` elapses.
    /// Single futex wait — NOT a tokio timer; no runtime involvement.
    pub(crate) fn wait_for_drain(&self, timeout: std::time::Duration) {
        let mut g = self.drain_mu.lock();
        let _ = self.drain_cv.wait_for(&mut g, timeout);
    }

    /// Get the cached field_configs, or build + cache them on first call.
    /// `text_analyzer` is #937's per-index text analyzer name — fixed at
    /// index open, so caching the configs against it is sound.
    fn field_configs(
        &self,
        schema: &Arc<RwLock<ManagedSchema>>,
        text_analyzer: &str,
    ) -> HashMap<String, xerj_fts::index::FieldIndexConfig> {
        if let Some(cfg) = self.field_configs_cache.read().as_ref() {
            return cfg.clone();
        }
        let rt = match self.rt.as_ref() {
            Some(rt) => rt,
            None => return HashMap::new(),
        };
        let cfg = rt.block_on(async {
            let guard = schema.read().await;
            build_fts_field_configs(&guard.schema, text_analyzer)
        });
        *self.field_configs_cache.write() = Some(cfg.clone());
        cfg
    }

    fn doc_values_skip_set(
        &self,
        schema: &Arc<RwLock<ManagedSchema>>,
    ) -> std::collections::HashSet<String> {
        let Some(rt) = self.rt.as_ref() else {
            return std::collections::HashSet::new();
        };
        rt.block_on(async {
            let guard = schema.read().await;
            doc_values_skip_set(&guard.schema)
        })
    }

    fn fts_excluded_fields(
        &self,
        schema: &Arc<RwLock<ManagedSchema>>,
    ) -> std::collections::HashSet<String> {
        let Some(rt) = self.rt.as_ref() else {
            return std::collections::HashSet::new();
        };
        rt.block_on(async {
            let guard = schema.read().await;
            crate::memtable::fts_excluded_fields(&guard.schema)
        })
    }
}

// ── Free helpers ──────────────────────────────────────────────────────────────

/// Collapse with optional inner_hits emission. When `inner_hits_name` is
/// provided, the representative hit (first per group) carries the rest of
/// its group under a sentinel source key `__xy_collapse_group__` so the
/// response layer can build the inner_hits block. Limits (size, sort) are
/// respected by the response layer.
fn apply_collapse_with_inner(
    hits: Vec<Hit>,
    field: &str,
    inner_hits_spec: Option<&serde_json::Value>,
) -> Vec<Hit> {
    let mut groups: std::collections::BTreeMap<String, Vec<Hit>> =
        std::collections::BTreeMap::new();
    let mut group_order: Vec<String> = Vec::new();
    for hit in hits {
        let key = match hit.source.get(field) {
            Some(v) => match v {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                Value::Bool(b) => b.to_string(),
                Value::Null => "\0null".to_string(),
                other => other.to_string(),
            },
            None => "\0missing".to_string(),
        };
        if !groups.contains_key(&key) {
            group_order.push(key.clone());
        }
        groups.entry(key).or_default().push(hit);
    }

    let mut result = Vec::with_capacity(group_order.len());
    for k in group_order {
        let mut members = groups.remove(&k).unwrap_or_default();
        if members.is_empty() {
            continue;
        }
        let mut lead = members.remove(0);
        if inner_hits_spec.is_some() {
            // Stash every member (including lead) so es_compat.rs can
            // build the inner_hits block with size/sort applied.
            let all_members: Vec<serde_json::Value> = std::iter::once(&lead)
                .chain(members.iter())
                .map(|h| {
                    serde_json::json!({
                        "_id": h.id,
                        "_score": h.score,
                        "_source": h.source,
                        "sort": h.sort,
                        // Carry the snapshotted seq_no/version so the renderer
                        // does not do a live lookup + positional index (#506):
                        // a collapse + scroll must hand inner hits the doc's real
                        // sequence number, not the array index, and a snapshot
                        // version, not one re-read at render time.
                        "_seq_no": h.seq_no,
                        "_version": h.version,
                    })
                })
                .collect();
            if let Some(obj) = lead.source.as_object_mut() {
                obj.insert(
                    "__xy_collapse_group__".to_string(),
                    Value::Array(all_members),
                );
                obj.insert(
                    "__xy_collapse_spec__".to_string(),
                    inner_hits_spec.cloned().unwrap_or(Value::Null),
                );
            }
        }
        result.push(lead);
    }
    result
}

/// Apply `_source` filtering to all hits.
///
/// * `Enabled(true)`  → return source unchanged (default).
/// * `Enabled(false)` → strip source entirely (set to `Value::Null`; serialised
///   as absent via `skip_serializing_if`).
/// * `Includes(fields)` → keep only the listed top-level fields.
/// * `Fields { includes, excludes }` → keep includes, then remove excludes.
///
/// Parse `s` under an ES-pattern `fmt` and return the corresponding
/// epoch-ms (or epoch-ns when the fractional seconds have ≥4 digits).
fn es_format_to_epoch_ms(s: &str, fmt: &str) -> Option<i64> {
    // Passthrough for epoch numerics.
    if fmt.contains("epoch_millis") {
        return s.parse::<i64>().ok();
    }
    if fmt.contains("epoch_second") {
        return s.parse::<i64>().ok().map(|v| v * 1000);
    }
    // Strict_date_optional_time_nanos: ISO-8601 — fall through to the
    // general ISO detector path (not this helper).
    if fmt.contains("strict_date_optional_time") || fmt.contains("date_optional_time") {
        return None;
    }
    // Translate ES pattern to chrono strftime. Minimal subset — covers
    // the tokens the YAML sort-format tests use.
    fn es_to_strftime(es_fmt: &str) -> String {
        let mut out = String::with_capacity(es_fmt.len() + 8);
        let bytes = es_fmt.as_bytes();
        let mut i = 0;
        while i < bytes.len() {
            let rest = &es_fmt[i..];
            if rest.starts_with("yyyy") {
                out.push_str("%Y");
                i += 4;
            } else if rest.starts_with("yy") {
                out.push_str("%y");
                i += 2;
            } else if rest.starts_with("MM") {
                out.push_str("%m");
                i += 2;
            } else if rest.starts_with("dd") {
                out.push_str("%d");
                i += 2;
            } else if rest.starts_with("HH") {
                out.push_str("%H");
                i += 2;
            } else if rest.starts_with("mm") {
                out.push_str("%M");
                i += 2;
            } else if rest.starts_with("ss") {
                out.push_str("%S");
                i += 2;
            } else if rest.starts_with("SSSSSSSSS") {
                out.push_str("%9f");
                i += 9;
            } else if rest.starts_with("SSSSSS") {
                out.push_str("%6f");
                i += 6;
            } else if rest.starts_with("SSS") {
                out.push_str("%3f");
                i += 3;
            } else if rest.starts_with("Z") {
                out.push_str("%z");
                i += 1;
            } else if rest.starts_with("XXX") {
                out.push_str("%:z");
                i += 3;
            } else if rest.starts_with("'") {
                i += 1;
                while i < bytes.len() && bytes[i] != b'\'' {
                    out.push(bytes[i] as char);
                    i += 1;
                }
                if i < bytes.len() {
                    i += 1;
                }
            } else {
                out.push(bytes[i] as char);
                i += 1;
            }
        }
        out
    }
    let pat = es_to_strftime(fmt);
    if let Ok(dt) = chrono::NaiveDateTime::parse_from_str(s, &pat) {
        return Some(dt.and_utc().timestamp_millis());
    }
    if let Ok(d) = chrono::NaiveDate::parse_from_str(s, &pat) {
        return d
            .and_hms_opt(0, 0, 0)
            .map(|dt| dt.and_utc().timestamp_millis());
    }
    None
}

/// A `std::io::Write` sink that counts bytes and keeps none of them.
///
/// Serializing a value into this yields the byte count `serde_json` *would*
/// have written, without allocating a buffer for a payload we are about to
/// throw away. Using serde itself — rather than a hand-rolled length
/// function — means the number cannot silently drift from what the wire
/// format actually produces (float formatting above all).
#[derive(Default)]
struct ByteCounter(u64);

impl std::io::Write for ByteCounter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.0 += buf.len() as u64;
        Ok(buf.len())
    }
    fn write_all(&mut self, buf: &[u8]) -> std::io::Result<()> {
        self.0 += buf.len() as u64;
        Ok(())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

/// Exact serialized JSON length of `value` — measured, not estimated.
fn json_wire_len(value: &Value) -> u64 {
    let mut counter = ByteCounter::default();
    match serde_json::to_writer(&mut counter, value) {
        Ok(()) => counter.0,
        // `Value` → JSON cannot fail. If it somehow did we would not KNOW the
        // size, and an unknown size must never be reported as a saving.
        Err(_) => 0,
    }
}

/// Exact serialized length of a JSON object key, quotes and escaping included.
fn json_key_len(key: &str) -> u64 {
    let mut counter = ByteCounter::default();
    match serde_json::to_writer(&mut counter, key) {
        Ok(()) => counter.0,
        Err(_) => 0,
    }
}

/// How many elements of a long array are actually rendered before the rest is
/// extrapolated.
///
/// 64 was chosen by measurement, not taste. XERJ's built-in (non-ONNX)
/// embedder emits *sparse* vectors — on a real 384-dim companion, 320 of the
/// 384 elements are exactly `0.0` — and the resulting bimodal width
/// distribution is what breaks naive sampling: plain 32-element sampling of
/// that vector came out between -9.7% and +16.8% depending on which 32
/// elements you take. Counting the fixed-width elements exactly (see
/// [`cheap_element_len`]) and sampling only the rest at 64 brings the same
/// vector to 0.00%. Observed error across real and adversarial shapes is
/// tabulated in `SAVINGS-STATS-REPORT.md`.
const SAVINGS_ARRAY_SAMPLE: usize = 64;

/// Sample size at nesting depth `depth` (number of enclosing arrays).
///
/// Nested numeric arrays — a chunk matrix, `[[f32; dims]; chunks]` — multiply:
/// sampling 64 rows of 64 columns is 4,096 float renders, which is most of
/// what the measurement costs on a large document. The rows of an embedding
/// matrix are homogeneous by construction (same dimensionality, same model,
/// same magnitude range), so a smaller sample deeper down costs almost no
/// accuracy and cuts the product hard. Measured effect is in the report.
fn savings_sample_size(depth: u32) -> usize {
    match depth {
        0 => SAVINGS_ARRAY_SAMPLE,
        1 => 16,
        _ => 8,
    }
}

/// Serialized length of an array element whose width is knowable without
/// running the expensive formatter, or `None` if it has to be rendered.
///
/// The whole sampling scheme rests on this: the elements that make a vector's
/// width distribution bimodal — the zeros — are also the ones we can size for
/// free, so they are counted exactly and never sampled. Integers go through
/// `itoa`, which is several times cheaper than the `ryu` float path and is
/// therefore taken exactly too.
fn cheap_element_len(value: &Value) -> Option<u64> {
    match value {
        Value::Null => Some(4),
        Value::Bool(true) => Some(4),
        Value::Bool(false) => Some(5),
        Value::Number(number) => {
            if let Some(float) = number.as_f64() {
                if number.is_f64() {
                    if float != 0.0 {
                        return None;
                    }
                    // ryu renders signed zero as `-0.0`; `-0.0 == 0.0` in
                    // Rust, so the sign has to be asked for explicitly.
                    return Some(if float.is_sign_negative() { 4 } else { 3 });
                }
            }
            Some(json_wire_len(value))
        }
        _ => None,
    }
}

/// Serialized JSON length of `value`, with long arrays extrapolated from a
/// bounded sample instead of rendered in full.
///
/// This is what makes the statistic affordable on every search. An embedding
/// companion is ~250,000 float literals; rendering all of them with `ryu`
/// purely to learn how many bytes they occupy costs ~10 ms per page of ten
/// hits. Sampling 64 of them costs microseconds.
///
/// It is an estimate and is labelled as one on the wire
/// (`_savings.measured: "sampled"`). Three properties keep it honest:
///
/// * Anything short enough to be cheap is measured **exactly** — arrays at or
///   under [`SAVINGS_ARRAY_SAMPLE`] costly elements, every object, every
///   scalar, every string outside a long array.
/// * The elements with a free, exact width are counted exactly and excluded
///   from the sample, so a bimodal (sparse-vector) distribution does not
///   poison the mean.
/// * The sample is strided across the whole array rather than taken from the
///   head, and the extrapolation truncates rather than rounds, so what bias
///   remains leans toward under-claiming.
fn json_len_sampled(value: &Value) -> u64 {
    json_len_sampled_at(value, 0)
}

fn json_len_sampled_at(value: &Value, depth: u32) -> u64 {
    match value {
        Value::Array(items) => {
            if items.is_empty() {
                return 2;
            }
            let sample = savings_sample_size(depth);
            // Pass 1: size everything that is free to size, and count what is
            // left. No allocation — this runs on the hot read path.
            let mut exact = 0u64;
            let mut costly = 0usize;
            for item in items {
                match cheap_element_len(item) {
                    Some(len) => exact += len,
                    None => costly += 1,
                }
            }
            let sampled = if costly == 0 {
                0
            } else if costly <= sample {
                // Few enough to be worth doing properly.
                items
                    .iter()
                    .filter(|item| cheap_element_len(item).is_none())
                    .map(|item| json_len_sampled_at(item, depth + 1))
                    .sum()
            } else {
                // Pass 2: stride across the costly elements, rendering one
                // every `costly / sample`, then extrapolate.
                let mut seen = 0usize;
                let mut taken = 0usize;
                let mut total = 0u64;
                for item in items {
                    if cheap_element_len(item).is_some() {
                        continue;
                    }
                    if taken < sample && seen >= taken * costly / sample {
                        total += json_len_sampled_at(item, depth + 1);
                        taken += 1;
                    }
                    seen += 1;
                }
                let taken = taken.max(1) as u128;
                // Truncating division: the residue is dropped rather than
                // rounded up, so the estimate never drifts high by rounding.
                (total as u128 * costly as u128 / taken) as u64
            };
            // `[`, `]`, and one comma between each pair of elements.
            2 + (items.len() as u64 - 1) + exact + sampled
        }
        Value::Object(map) => {
            if map.is_empty() {
                return 2;
            }
            let inner: u64 = map
                .iter()
                .map(|(key, val)| json_key_len(key) + 1 + json_len_sampled_at(val, depth))
                .sum();
            2 + (map.len() as u64 - 1) + inner
        }
        _ => json_wire_len(value),
    }
}

/// Serialized length of `value` under the caller's chosen measurement mode.
fn json_len(value: &Value, mode: SavingsMode) -> u64 {
    match mode {
        SavingsMode::Exact => json_wire_len(value),
        _ => json_len_sampled(value),
    }
}

/// Per-hit omitted bytes.
#[derive(Default)]
struct SavingsAccumulator {
    per_hit: Vec<(String, u64)>,
}

impl SavingsAccumulator {
    fn record(&mut self, id: &str, bytes: u64) {
        if bytes > 0 {
            self.per_hit.push((id.to_string(), bytes));
        }
    }
}

/// Serialized length of the `_source` this hit would have carried had the
/// caller written **no `_source` clause at all** — the engine's default
/// projection, which strips generated embedding companions.
///
/// This is the baseline every saving below is measured against, and getting
/// it right is the difference between a statistic and a slogan. Measuring
/// against the raw stored document instead credits the caller's projection
/// with the removal of embedding vectors that this engine has not returned by
/// default since #309; a blind UX dogfood measured that overstatement at a
/// consistent ~9.3x and it was the single thing that cost the feature its
/// credibility.
///
/// Note what this does NOT do: it never serializes the companion values. The
/// old baseline had to, because it was claiming them. Fixing the honesty
/// problem removed the expensive half of the measurement with it.
fn default_projection_len(
    source: &Value,
    generated_companion_fields: &HashSet<String>,
    mode: SavingsMode,
) -> u64 {
    let Some(map) = source.as_object() else {
        return json_len(source, mode);
    };
    if generated_companion_fields.is_empty() {
        return json_len(source, mode);
    }
    // A dotted or globbed companion strips a nested key, which the key-wise
    // walk below cannot express; fall back to building the projection.
    if generated_companion_fields
        .iter()
        .any(|f| f.contains('.') || f.contains('*'))
    {
        let excludes: Vec<String> = generated_companion_fields.iter().cloned().collect();
        return json_len(&filter_object(source, &[], &excludes), mode);
    }
    let mut inner = 0u64;
    let mut kept = 0usize;
    for (key, value) in map {
        if generated_companion_fields.contains(key) {
            continue;
        }
        inner += json_key_len(key) + 1 + json_len(value, mode);
        kept += 1;
    }
    if kept == 0 {
        return 2;
    }
    // `{`, `}`, and one comma between each pair of kept members.
    2 + (kept as u64 - 1) + inner
}

fn plural(n: usize) -> &'static str {
    if n == 1 {
        ""
    } else {
        "s"
    }
}

/// The engine-internal collapse sentinels — a user's `_source` include/exclude
/// list must not strip these, or the API renders no `inner_hits` (#651). They
/// are captured before an explicit projection and re-attached after, so the API
/// (which extracts the group and strips the sentinels from the wire `_source`)
/// still sees them.
const COLLAPSE_SENTINELS: [&str; 2] = ["__xy_collapse_group__", "__xy_collapse_spec__"];

fn take_collapse_sentinels(source: &Value) -> Vec<(String, Value)> {
    source
        .as_object()
        .map(|o| {
            COLLAPSE_SENTINELS
                .iter()
                .filter_map(|k| o.get(*k).map(|v| (k.to_string(), v.clone())))
                .collect()
        })
        .unwrap_or_default()
}

fn reattach_collapse_sentinels(source: &mut Value, sentinels: Vec<(String, Value)>) {
    if sentinels.is_empty() {
        return;
    }
    if !source.is_object() {
        *source = Value::Object(serde_json::Map::new());
    }
    if let Some(obj) = source.as_object_mut() {
        for (k, v) in sentinels {
            obj.insert(k, v);
        }
    }
}

/// Unmeasured filtering — the shape every pre-existing test asserts on, and
/// proof that the measurement is strictly additive rather than a rewrite of
/// the `_source` projection semantics.
#[cfg(test)]
fn apply_source_filter(
    hits: Vec<Hit>,
    filter: &SourceFilter,
    generated_companion_fields: &HashSet<String>,
) -> Vec<Hit> {
    apply_source_filter_measured(hits, filter, generated_companion_fields, None).0
}

/// `_source` filtering, measuring what it left out.
///
/// `measure: Some(request)` turns the savings measurement on; `None` skips it
/// for one `Option` check per call and no per-hit work whatsoever — that is
/// the path every internal engine search (reindex, update-by-query, terms
/// lookup, suggesters) takes, because nobody will ever read their number.
/// The user-facing `_search` handler measures by default; see
/// [`SavingsMode`] and [`json_len_sampled`] for how that is made affordable.
///
/// Every number produced here is the difference between what this response
/// carries and what the *same* response would have carried without the
/// omission. Nothing hypothetical is counted, and nothing is counted twice.
fn apply_source_filter_measured(
    hits: Vec<Hit>,
    filter: &SourceFilter,
    generated_companion_fields: &HashSet<String>,
    measure: Option<&SearchRequest>,
) -> (Vec<Hit>, Option<PayloadSavings>) {
    let hits: Vec<Hit> = hits
        .into_iter()
        .map(|mut hit| {
            strip_internal_passage_metadata(&mut hit.source);
            hit
        })
        .collect();
    let mut acc = SavingsAccumulator::default();
    // A request carrying `SavingsMode::Off` is indistinguishable from no
    // request at all, so collapse the two here rather than guarding every
    // measurement site below.
    let mode = measure.map_or(SavingsMode::Off, |request| request.savings);
    let measure = measure.filter(|_| !matches!(mode, SavingsMode::Off));
    let measuring = measure.is_some();
    let mut substitutable = false;
    let filtered = match filter {
        // The default is a passthrough: only engine-generated embedding
        // companions are stripped, so an index without embedding mappings
        // must not pay a per-hit deep copy of its source (issue #311).
        //
        // NOTHING IS REPORTED HERE, deliberately. Stripping the companions is
        // what this engine does on every default response; it is not a choice
        // the caller made and it is not a saving relative to what they would
        // otherwise have received. Claiming it meant a caller who wrote
        // `{"query":…,"size":20}` and asked for everything was told they had
        // saved 22 MB — the engine taking credit for its own default, which is
        // precisely the vanity metric this feature was written to avoid.
        SourceFilter::Default => {
            if generated_companion_fields.is_empty() {
                return (hits, None);
            }
            if generated_companion_fields
                .iter()
                .any(|f| f.contains('.') || f.contains('*'))
            {
                let excludes: Vec<String> = generated_companion_fields.iter().cloned().collect();
                return (
                    hits.into_iter()
                        .map(|mut h| {
                            h.source = filter_object(&h.source, &[], &excludes);
                            h
                        })
                        .collect(),
                    None,
                );
            }
            return (
                hits.into_iter()
                    .map(|mut h| {
                        if let Some(map) = h.source.as_object_mut() {
                            map.retain(|k, _| !generated_companion_fields.contains(k));
                        }
                        h
                    })
                    .collect(),
                None,
            );
        }
        // The caller explicitly asked for the whole document — MORE than the
        // default projection, not less. Nothing was withheld. Expand packed
        // embeddings here, on the page only, so the wire form stays a number
        // array (#1940).
        SourceFilter::Enabled(true) => {
            return (
                hits.into_iter()
                    .map(|mut hit| {
                        xerj_common::packed_f32::expand_packed_f32_values(&mut hit.source);
                        hit
                    })
                    .collect(),
                None,
            );
        }
        // `_source: false`: keep the raw source so the response layer can
        // still resolve `fields` / `_ignored` / `highlight` against it —
        // `_source` emission is suppressed in es_compat.rs.
        SourceFilter::Enabled(false) => {
            if measuring {
                // The response layer may hand some of these values back via
                // `fields` / `docvalue_fields` / `script_fields`. It knows
                // exactly how many bytes it emitted and subtracts them; this
                // flag is what tells it to.
                substitutable = true;
                for h in &hits {
                    let omitted =
                        default_projection_len(&h.source, generated_companion_fields, mode);
                    // Highlighting is the designated substitute when `_source`
                    // is off: the fragments ARE on the wire, so the honest
                    // saving is net of them.
                    let substitute = h
                        .highlight
                        .as_ref()
                        .map(|frags| {
                            json_len(&serde_json::to_value(frags).unwrap_or(Value::Null), mode)
                        })
                        .unwrap_or(0);
                    acc.record(&h.id, omitted.saturating_sub(substitute));
                }
            }
            hits
        }
        SourceFilter::Includes(fields) => hits
            .into_iter()
            .map(|mut h| {
                let baseline = measuring
                    .then(|| default_projection_len(&h.source, generated_companion_fields, mode));
                let sentinels = take_collapse_sentinels(&h.source);
                h.source = filter_object(&h.source, fields, &[]);
                // Expand before the savings measurement so a caller who asked
                // for the companion is billed for the number array on the wire,
                // not the packed string it was stored as.
                xerj_common::packed_f32::expand_packed_f32_values(&mut h.source);
                if let Some(baseline) = baseline {
                    // Saturating: a caller who explicitly projects a generated
                    // companion gets MORE than the default, and more is not a
                    // saving. Measured on the sentinel-free projection.
                    acc.record(&h.id, baseline.saturating_sub(json_len(&h.source, mode)));
                }
                reattach_collapse_sentinels(&mut h.source, sentinels);
                h
            })
            .collect(),
        SourceFilter::Fields { includes, excludes } => hits
            .into_iter()
            .map(|mut h| {
                let baseline = measuring
                    .then(|| default_projection_len(&h.source, generated_companion_fields, mode));
                let sentinels = take_collapse_sentinels(&h.source);
                h.source = filter_object(&h.source, includes, excludes);
                xerj_common::packed_f32::expand_packed_f32_values(&mut h.source);
                if let Some(baseline) = baseline {
                    acc.record(&h.id, baseline.saturating_sub(json_len(&h.source, mode)));
                }
                reattach_collapse_sentinels(&mut h.source, sentinels);
                h
            })
            .collect(),
    };
    let savings =
        measure.and_then(|request| savings_note(filter, request, mode, substitutable, &acc));
    (filtered, savings)
}

/// Merge the savings of a hybrid query's sub-searches.
///
/// Every leg strips the same companions from the same documents, so a
/// document retrieved by two legs must contribute its bytes exactly once —
/// summing the legs' totals would double-count, which is precisely the
/// inflation this stat must not commit. De-duplicating by document id makes
/// the double-count structurally impossible.
fn merge_sub_savings(sub_savings: Vec<PayloadSavings>) -> Option<PayloadSavings> {
    let mut seen: HashSet<String> = HashSet::new();
    let mut per_hit: Vec<(String, u64)> = Vec::new();
    let mut note: Option<String> = None;
    let mut method: Option<SavingsMethod> = None;
    let mut substitutable = false;
    for savings in sub_savings {
        note.get_or_insert_with(|| savings.note.clone());
        method.get_or_insert(savings.measured);
        substitutable |= savings.substitutable;
        for (id, bytes) in savings.per_hit {
            if seen.insert(id.clone()) {
                per_hit.push((id, bytes));
            }
        }
    }
    PayloadSavings::new(method?, note?, substitutable, per_hit)
}

/// Phrase the mechanism that actually fired.
///
/// The point of the stat is not the counter, it is teaching the reader WHICH
/// feature bought them the bytes, so each mechanism gets its own sentence.
/// Kept to a few tens of bytes: a block that costs more tokens than it
/// reports saving would be the worst possible advertisement for the idea.
fn savings_note(
    filter: &SourceFilter,
    request: &SearchRequest,
    mode: SavingsMode,
    substitutable: bool,
    acc: &SavingsAccumulator,
) -> Option<PayloadSavings> {
    // Counts come from the REQUEST, never from what came back. A caller who
    // projects one field that a particular document happens to lack was told
    // "Sent the 0 fields you asked for" — reporting their own request back to
    // them, wrongly. What they asked for is a fact about the request.
    //
    // And no denominators. "not all 15" reads as a claim about the index
    // schema, but it was really the widest document on the page: the same
    // query at a different `size` reported 8, then 11, then 12, then 15, which
    // reads as an unreliable statistic even though each number was true of the
    // page it described.
    let note = match filter {
        // Neither of these reaches here — both return before the note is
        // built — but the match must stay total.
        SourceFilter::Default | SourceFilter::Enabled(true) => return None,
        SourceFilter::Enabled(false) if request.highlight.is_some() => {
            "highlight fragments returned in place of _source".to_string()
        }
        SourceFilter::Enabled(false) if !request.fields.is_empty() => {
            "fields returned in place of _source".to_string()
        }
        SourceFilter::Enabled(false) => "_source withheld, as requested".to_string(),
        SourceFilter::Includes(fields) => format!(
            "_source narrowed to the {} field{} you listed",
            fields.len(),
            plural(fields.len())
        ),
        SourceFilter::Fields { includes, excludes } if includes.is_empty() => format!(
            "_source excluded the {} field{} you listed",
            excludes.len(),
            plural(excludes.len())
        ),
        SourceFilter::Fields { includes, .. } => format!(
            "_source narrowed to the {} field{} you listed",
            includes.len(),
            plural(includes.len())
        ),
    };
    let method = match mode {
        SavingsMode::Exact => SavingsMethod::Exact,
        _ => SavingsMethod::Sampled,
    };
    PayloadSavings::new(method, note, substitutable, acc.per_hit.clone())
}

/// Return the engine-generated embedding companions for a schema.
///
/// This is deliberately derived from `FieldConfig.embedding` rather than from
/// field-name suffixes: a user-owned field called `body_vector` is ordinary
/// source data unless an embedding mapping designates it as a target.
fn generated_embedding_companion_fields(schema: &Schema) -> HashSet<String> {
    let mut companions = HashSet::new();
    for field in &schema.fields {
        let Some(embedding) = &field.embedding else {
            continue;
        };
        let target = embedding
            .target_field
            .clone()
            .unwrap_or_else(|| format!("{}_vector", field.name));
        companions.insert(target.clone());
        companions.insert(format!("{target}_chunks"));
    }
    companions
}

/// Return a filtered copy of a JSON object keeping `includes` and removing `excludes`.
///
/// Supports dotted field paths: `include.field1` matches the nested
/// `{"include": {"field1": ...}}` structure. If `includes` is empty,
/// all fields are kept before exclusions are applied.
/// Faithful ES `_source` include/exclude projection over a single JSON value:
/// dotted paths and `*` globs that span `.` at any depth, includes then
/// excludes (#602). Exposed so the document-GET path (`_source_includes` /
/// `_source_excludes` on `GET /_doc`) projects identically to search instead
/// of the old top-level-only filter that dropped nested includes.
pub fn filter_object(source: &Value, includes: &[String], excludes: &[String]) -> Value {
    let obj = match source.as_object() {
        Some(o) => o,
        None => return source.clone(),
    };

    // Route through the ES automaton whenever a pattern is nested (dotted) OR
    // contains a wildcard. The simple top-level branch below understands only a
    // trailing `*` on a whole key (`field_matches`), so a dot-less LEADING or
    // MID glob must go through the NFA too: in ES a `*` is `Σ*` over the full
    // dotted path whether or not the pattern itself contains a `.`, so `*id`
    // matches `user.groupid` and `exclude ["*secret"]` strips `password_secret`.
    // Without this, `include ["*id"]` dropped the whole source and
    // `exclude ["*secret"]` silently no-oped — the data-loss / data-exposure
    // failure modes #602 exists to eliminate. Only pure-literal top-level
    // patterns (no `.`, no `*`) take the fast path.
    let needs_automaton = includes
        .iter()
        .chain(excludes.iter())
        .any(|f| f.contains('.') || f.contains('*'));

    if !needs_automaton {
        // Simple top-level filtering: literal whole-key includes/excludes only.
        let mut result = serde_json::Map::new();
        for (k, v) in obj {
            let keep = if includes.is_empty() {
                true
            } else {
                includes.iter().any(|inc| field_matches(k, inc))
            };
            let excluded = excludes.iter().any(|exc| field_matches(k, exc));
            if keep && !excluded {
                result.insert(k.clone(), v.clone());
            }
        }
        return Value::Object(result);
    }

    // Dotted path filtering: a faithful ES `_source` include/exclude automaton.
    //
    // ES compiles each include/exclude pattern with `Regex.simpleMatchToAutomaton`,
    // where `*` becomes `Automata.makeAnyString()` — it matches ANY run of
    // characters INCLUDING `.`, so a wildcard spans path segments at any depth
    // (`org.elasticsearch.common.regex.Regex`, Apache-2.0). That is why `obj.*`
    // keeps `obj`'s whole subtree, `*.foo` keeps every `foo` leaf at any depth,
    // and `exclude ["*.secret"]` scrubs a nested `secret` however deep it sits.
    // `XContentMapValues.filter` then walks the document and, at each node, asks
    // the automaton two questions about that node's dotted path:
    //   * ACCEPT — the pattern matches this path in full → include the whole
    //     subtree (subject to excludes);
    //   * LIVE — this path is a proper prefix the pattern can still extend to an
    //     ACCEPT deeper down → descend.
    // A leaf that is only LIVE (never ACCEPTed) was not selected and is dropped.
    //
    // The matcher is a small glob NFA over the FULL dotted path (`*` = any char
    // incl `.`); leading/mid/trailing wildcards, the dot boundary, and
    // multi-level globs all fall out of it (#602). Object descent goes through
    // the automaton; scalars and arrays are handled at the leaf (see below).

    // Reachable-state summary of glob `pat` after consuming `text`, with
    // `*` = Σ* (matches any character, including `.`). Returns `(accept, live)`:
    // `accept` = the whole pattern matched `text`; `live` = some reachable
    // position can still consume a deeper `.segment` (sitting on a `*`, or on a
    // literal `.` awaiting the next level), i.e. `text` is a viable prefix.
    fn glob_reach(pat: &[u8], text: &[u8]) -> (bool, bool) {
        let n = pat.len();
        // Epsilon-closure: a `*` may match zero characters, so reaching the
        // position of a `*` also reaches the position after it. A single forward
        // pass suffices because a `*` only ever skips to `i + 1`.
        let closure = |set: &mut [bool]| {
            for i in 0..n {
                if set[i] && pat[i] == b'*' {
                    set[i + 1] = true;
                }
            }
        };
        let mut cur = vec![false; n + 1];
        let mut nxt = vec![false; n + 1];
        cur[0] = true;
        closure(&mut cur);
        for &c in text {
            for x in nxt.iter_mut() {
                *x = false;
            }
            for i in 0..n {
                if !cur[i] {
                    continue;
                }
                if pat[i] == b'*' {
                    // Σ* consumes any character (including `.`) and stays put.
                    nxt[i] = true;
                } else if pat[i] == c {
                    nxt[i + 1] = true;
                }
            }
            closure(&mut nxt);
            std::mem::swap(&mut cur, &mut nxt);
        }
        let accept = cur[n];
        let live = (0..n).any(|i| cur[i] && (pat[i] == b'*' || pat[i] == b'.'));
        (accept, live)
    }

    // `(accept, live)` of a path against a set of patterns — OR over the set.
    fn reach_any(patterns: &[String], path: &str) -> (bool, bool) {
        let mut acc = false;
        let mut liv = false;
        for p in patterns {
            let (a, l) = glob_reach(p.as_bytes(), path.as_bytes());
            acc |= a;
            liv |= l;
        }
        (acc, liv)
    }

    // Project each element of an array at the same dotted `path` — an array
    // index is transparent to a `_source` path at EVERY depth (#644/#653), so a
    // nested array of objects recurses too. An object element is filtered (and
    // an emptied one dropped, mirroring the map-value rule); a nested-array
    // element recurses here; a scalar survives only in an accepting state.
    fn project_array_at(
        arr: &[Value],
        path: &str,
        child_all: bool,
        includes: &[String],
        excludes: &[String],
    ) -> Vec<Value> {
        arr.iter()
            .filter_map(|elem| match elem {
                Value::Object(child_obj) => {
                    let f = es_filter(elem, path, child_all, includes, excludes);
                    match &f {
                        Value::Object(m) if m.is_empty() => {
                            (child_obj.is_empty() && child_all).then_some(f)
                        }
                        _ => Some(f),
                    }
                }
                Value::Array(inner) => {
                    let p = project_array_at(inner, path, child_all, includes, excludes);
                    (!p.is_empty() || (inner.is_empty() && child_all)).then(|| Value::Array(p))
                }
                other => child_all.then(|| other.clone()),
            })
            .collect()
    }

    // Filter one value at dotted `path`. `include_all` means an ancestor path
    // was ACCEPTed (or the include list is empty), so this subtree is included
    // subject only to excludes.
    fn es_filter(
        value: &Value,
        path: &str,
        include_all: bool,
        includes: &[String],
        excludes: &[String],
    ) -> Value {
        let Value::Object(obj) = value else {
            return value.clone();
        };
        let mut out = serde_json::Map::new();
        for (key, val) in obj {
            let child = if path.is_empty() {
                key.clone()
            } else {
                format!("{path}.{key}")
            };

            let (exc_acc, exc_live) = reach_any(excludes, &child);
            if exc_acc {
                // The exclude matches this path in full → drop the subtree.
                continue;
            }
            let (inc_acc, inc_live) = if includes.is_empty() {
                (true, false)
            } else {
                reach_any(includes, &child)
            };
            let accept = include_all || inc_acc;
            if !(accept || inc_live) {
                continue; // neither selected nor a live prefix
            }
            let child_all = accept;

            match val {
                Value::Object(child_obj) => {
                    // A fully-included object with no exclude reaching into it is
                    // kept whole; otherwise descend to select/strip.
                    if child_all && !exc_live {
                        out.insert(key.clone(), val.clone());
                        continue;
                    }
                    let filtered = es_filter(val, &child, child_all, includes, excludes);
                    let keep = match &filtered {
                        // An object that *filtering* emptied is pruned; one that
                        // was ALREADY empty in the source survives only in an
                        // accepting state — a live-only prefix on the way to a
                        // deeper include is dropped, matching ES (#310).
                        Value::Object(m) if m.is_empty() => child_obj.is_empty() && child_all,
                        _ => true,
                    };
                    if keep {
                        out.insert(key.clone(), filtered);
                    }
                }
                // ES treats an array index as transparent to a `_source` path,
                // so a pattern projects INTO each element (#644): `tags.name`
                // matches `tags[i].name`. A fully-included array with no exclude
                // reaching into it is kept whole (the fast path); otherwise each
                // element is filtered at the SAME `child` path — an object
                // element recurses, a scalar element survives only in an
                // accepting state (like a scalar leaf).
                Value::Array(arr) => {
                    if child_all && !exc_live {
                        out.insert(key.clone(), val.clone());
                    } else {
                        // Project each element at the same path (recursing into
                        // nested arrays — #644/#653).
                        let projected =
                            project_array_at(arr, &child, child_all, includes, excludes);
                        // A key whose array *filtering* emptied is pruned (had
                        // elements, all dropped); an already-empty source array
                        // survives only in an accepting state — mirrors the
                        // object arm so an emptied array does not leave a bare
                        // `[]` (or a `[{}]`) on the wire.
                        if !projected.is_empty() || (arr.is_empty() && child_all) {
                            out.insert(key.clone(), Value::Array(projected));
                        }
                    }
                }
                // A scalar leaf is kept ONLY in an ACCEPTing state. A scalar that
                // merely sits on a LIVE (not-yet-accepted) include path cannot
                // extend to satisfy the pattern, so ES drops it — keeping it
                // would over-include a field the pattern never selected.
                _ => {
                    if child_all {
                        out.insert(key.clone(), val.clone());
                    }
                }
            }
        }
        Value::Object(out)
    }

    es_filter(source, "", false, includes, excludes)
}

#[cfg(test)]
mod source_filter_tests {
    use super::*;
    use serde_json::json;
    use xerj_common::types::{EmbeddingConfig, FieldConfig, FieldType};

    fn embedded_schema() -> Schema {
        let mut schema = Schema::empty();
        schema
            .add_field(
                FieldConfig::new("body", FieldType::Text).with_embedding(EmbeddingConfig {
                    endpoint: None,
                    model: None,
                    target_field: None,
                }),
            )
            .unwrap();
        schema
    }

    fn hit(id: &str, score: f32, source: Value) -> Hit {
        Hit {
            id: id.to_string(),
            score,
            source,
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        }
    }

    fn generated_source() -> Value {
        json!({
            "body": "the source text",
            "body_vector": [0.1, 0.2, 0.3],
            "body_vector_chunks": [[0.1, 0.2], [0.2, 0.3]],
            "title": "a user field"
        })
    }

    #[test]
    fn omitted_source_excludes_mapping_derived_companions_only() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let hits = vec![
            hit("first", 0.9, generated_source()),
            hit("second", 0.4, generated_source()),
        ];

        let filtered = apply_source_filter(hits, &SourceFilter::Default, &companions);

        assert_eq!(
            filtered
                .iter()
                .map(|hit| (hit.id.as_str(), hit.score))
                .collect::<Vec<_>>(),
            vec![("first", 0.9), ("second", 0.4)]
        );
        for hit in filtered {
            assert_eq!(
                hit.source,
                json!({
                    "body": "the source text",
                    "title": "a user field"
                })
            );
        }
    }

    /// #310 (part 2): a dotted include/exclude anywhere in the request forces
    /// `filter_object` into its nested branch, which pruned EVERY empty object.
    /// An object that was already `{}` in the source is a real value the document
    /// carried and must survive; only an object that *filtering* emptied (had
    /// keys, all removed) is pruned. A dotted embedding `target_field` puts the
    /// Default arm on this path, silently dropping every `{"meta": {}}` from
    /// every hit.
    #[test]
    fn dotted_filter_keeps_an_already_empty_source_object_but_prunes_a_filtering_emptied_one() {
        let source = json!({
            "meta": {},                // already empty in the source
            "title": "x",
            "nested": { "drop_me": 1 } // becomes empty only via the exclude below
        });
        // The dotted exclude forces the nested branch (has_dotted) and empties
        // `nested`; `meta` was already empty in the document.
        let filtered = filter_object(&source, &[], &["nested.drop_me".to_string()]);
        assert_eq!(
            filtered,
            json!({ "meta": {}, "title": "x" }),
            "an already-empty object must survive a dotted filter; only a \
             filtering-emptied object is pruned (#310)"
        );
    }

    /// #310 (part 2, include mode): the already-empty relaxation is gated to an
    /// ACCEPTING state. An empty object kept only because it PREFIXES a deeper
    /// include (`meta` for include `meta.foo`) has nothing allow-listed under it,
    /// so ES drops it -- the fix must not resurrect it. But an empty object whose
    /// OWN path matches an include is accepting and is preserved. (Without this
    /// gate, `!obj.is_empty()` alone over-preserves in the prefix case.)
    #[test]
    fn dotted_include_keeps_an_empty_object_only_when_its_own_path_is_accepted() {
        // Prefix-only: `meta` is a non-accepting prefix of `meta.foo`, so nothing
        // under it is allow-listed -> dropped, exactly as ES does.
        assert_eq!(
            filter_object(&json!({ "meta": {} }), &["meta.foo".to_string()], &[]),
            json!({}),
            "an empty object that only prefixes a deeper include is not allow-listed (#310)"
        );
        // Own-path accepted: `meta` itself is an include (the dotted sibling
        // `other.x` forces the nested branch) -> preserved.
        assert_eq!(
            filter_object(
                &json!({ "meta": {} }),
                &["meta".to_string(), "other.x".to_string()],
                &[]
            ),
            json!({ "meta": {} }),
            "an empty object whose own path matches an include is preserved (#310)"
        );
        // Consistency with a non-empty sibling under the same prefix-only include:
        // `{"meta":{"bar":1}}` under `meta.foo` also drops `meta`, so the empty
        // and non-empty cases now agree (no appear/disappear by source emptiness).
        assert_eq!(
            filter_object(
                &json!({ "meta": { "bar": 1 } }),
                &["meta.foo".to_string()],
                &[]
            ),
            json!({}),
            "a non-empty object with no allow-listed leaf is dropped, same as the empty one (#310)"
        );
        // Glob form: `meta.*` — bare `meta` is a non-accepting prefix (ES's
        // automaton needs the trailing dot), so an empty `{"meta":{}}` drops just
        // as under `meta.foo`. `path_is_accepting` expresses this directly
        // (a `base.*` include accepts only paths strictly below `base.`);
        // #602 divergence 1 also made `matches_path`'s own `.*` clause require
        // the dot, so it no longer leaks the dot-less prefix either.
        assert_eq!(
            filter_object(&json!({ "meta": {} }), &["meta.*".to_string()], &[]),
            json!({}),
            "an empty object under a `.*` glob prefix is not allow-listed (#310)"
        );
        // But an empty object strictly BELOW the glob base IS accepted.
        assert_eq!(
            filter_object(
                &json!({ "meta": { "foo": {} } }),
                &["meta.*".to_string()],
                &[]
            ),
            json!({ "meta": { "foo": {} } }),
            "an empty object strictly under a `.*` glob is preserved (#310)"
        );
        // Boundary: a sibling key that merely shares a textual prefix
        // (`metadata` vs glob `meta.*`) is NOT accepted -- the accept test
        // requires the dot boundary, unlike a bare `starts_with("meta")`.
        assert_eq!(
            filter_object(&json!({ "metadata": {} }), &["meta.*".to_string()], &[]),
            json!({}),
            "a prefix-sharing sibling (metadata vs meta.*) is not accepted (#310)"
        );
    }

    /// #602 (divergence 1): a `prefix.*` include keeps ONLY paths under
    /// `prefix.`. The empty-object sibling case was covered by #310's
    /// `path_is_accepting`; this pins the NON-EMPTY case, which leaked through
    /// `matches_path`'s `.*` subtree clause using `starts_with("meta")` (no dot
    /// boundary), so `{"metadata":{"x":1}}` under `meta.*` was wrongly kept where
    /// ES returns `{}`. Fixed by stripping only the trailing `*` (`meta.`), not
    /// `.*` (`meta`), in that clause.
    #[test]
    fn source_glob_prefix_requires_the_dot_boundary_for_nonempty_siblings() {
        // Non-empty prefix-sharing sibling: dropped (ES parity).
        assert_eq!(
            filter_object(
                &json!({ "metadata": { "x": 1 } }),
                &["meta.*".to_string()],
                &[]
            ),
            json!({}),
            "a non-empty prefix-sharing sibling (metadata vs meta.*) is dropped (#602)"
        );
        // Positive control: a real child under `meta.` is kept, subtree and all.
        assert_eq!(
            filter_object(
                &json!({ "meta": { "foo": { "bar": 1 } } }),
                &["meta.*".to_string()],
                &[]
            ),
            json!({ "meta": { "foo": { "bar": 1 } } }),
            "the subtree under meta.* is kept (#602 must not over-prune)"
        );
        // A prefix-sharing sibling next to a real match: only the match survives.
        assert_eq!(
            filter_object(
                &json!({ "meta": { "foo": 1 }, "metadata": { "x": 2 } }),
                &["meta.*".to_string()],
                &[]
            ),
            json!({ "meta": { "foo": 1 } }),
            "meta.* keeps meta.* but not the prefix-sharing metadata (#602)"
        );
    }

    /// #602 (divergences 2, 3, 4): a faithful ES `_source` include/exclude
    /// automaton matches PER SEGMENT — `*` matches exactly one whole path
    /// segment (never across a `.`), a pattern fully consumed at a node includes
    /// that node's entire subtree, and an exclude removes a node only when its
    /// pattern fully matches AT that node. The old `matches_path`/prefix logic
    /// could not step through a leading/mid glob (2) or expand a trailing-`*`
    /// segment across the dot into the subtree (3), and its `exclude a.*` clause
    /// wrongly marked the bare parent excluded (4).
    #[test]
    fn source_glob_leading_mid_and_trailing_match_es_semantics() {
        let cases: Vec<(&str, Value, Vec<String>, Vec<String>, Value)> = vec![
            // 2a: a LEADING glob descends and keeps only the matching leaf.
            (
                "*.foo keeps a.foo, drops a.bar",
                json!({ "a": { "foo": 1, "bar": 2 } }),
                vec!["*.foo".into()],
                vec![],
                json!({ "a": { "foo": 1 } }),
            ),
            // 2b: a MID glob steps through one segment.
            (
                "a.*.c keeps a.b.c, drops a.b.d",
                json!({ "a": { "b": { "c": 1, "d": 2 } } }),
                vec!["a.*.c".into()],
                vec![],
                json!({ "a": { "b": { "c": 1 } } }),
            ),
            // 2c: a leading glob spans multiple parents.
            (
                "*.foo across siblings",
                json!({ "x": { "foo": 1 }, "y": { "foo": 2, "z": 3 } }),
                vec!["*.foo".into()],
                vec![],
                json!({ "x": { "foo": 1 }, "y": { "foo": 2 } }),
            ),
            // 3: a trailing `*` on a full segment includes the whole subtree
            //    (the segment `meta*` matches key `meta`; nothing remains, so
            //    `meta`'s subtree is kept). NOT the same as `*` crossing the dot.
            //    The non-matching dotted sibling `zzz.absent` forces the nested
            //    branch (has_dotted), where the old matcher wrongly dropped the
            //    subtree because `meta*`'s `*` could not cross the dot.
            (
                "meta* keeps meta and its subtree (nested branch)",
                json!({ "meta": { "foo": 1 } }),
                vec!["meta*".into(), "zzz.absent".into()],
                vec![],
                json!({ "meta": { "foo": 1 } }),
            ),
            // 3': but `meta*` must NOT match a differently-named sibling key.
            (
                "meta* does not match sibling `other` (nested branch)",
                json!({ "meta": { "foo": 1 }, "other": { "foo": 2 } }),
                vec!["meta*".into(), "zzz.absent".into()],
                vec![],
                json!({ "meta": { "foo": 1 } }),
            ),
            // 4: `exclude a.*` removes a's CHILDREN, not `a` itself — an empty
            //    `a` has no child to match, so `a` survives. (The
            //    populated-then-emptied case is deliberately NOT asserted here:
            //    XERJ prunes a filtering-emptied object, pinned by the #310
            //    `dotted_filter_keeps_an_already_empty_source_object...` test.)
            (
                "exclude a.* keeps empty a",
                json!({ "a": {} }),
                vec![],
                vec!["a.*".into()],
                json!({ "a": {} }),
            ),
        ];

        let mut actual: Vec<(&str, Value)> = Vec::new();
        let mut expected: Vec<(&str, Value)> = Vec::new();
        for (label, source, inc, exc, want) in cases {
            actual.push((label, filter_object(&source, &inc, &exc)));
            expected.push((label, want));
        }
        assert_eq!(
            actual, expected,
            "ES _source glob parity (#602 divergences 2/3/4)"
        );
    }

    /// #602 (verification follow-up): ES `_source` `*` compiles to
    /// `Automata.makeAnyString()`, so a wildcard matches ACROSS dots at any
    /// depth. Two blocking divergences surfaced by the 3-skeptic pass are pinned
    /// here: (a) a leading/mid glob must descend to ANY depth (`*.foo` keeps
    /// `a.b.foo`, `exclude *.secret` scrubs a nested secret); (b) a SCALAR leaf
    /// sitting on a live-but-non-accepting glob path must be DROPPED, not kept
    /// whole (the pattern never selected it).
    #[test]
    fn source_glob_crosses_dots_at_any_depth_like_es() {
        let cases: Vec<(&str, Value, Vec<String>, Vec<String>, Value)> = vec![
            // (a) leading glob descends past >=2 dots.
            (
                "*.foo keeps a.b.foo (depth 2)",
                json!({ "a": { "b": { "foo": 1, "bar": 2 } } }),
                vec!["*.foo".into()],
                vec![],
                json!({ "a": { "b": { "foo": 1 } } }),
            ),
            // (a) mid glob spans an intermediate level.
            (
                "a.*.c keeps a.b.e.c (glob crosses b.e)",
                json!({ "a": { "b": { "e": { "c": 1, "d": 2 } } } }),
                vec!["a.*.c".into()],
                vec![],
                json!({ "a": { "b": { "e": { "c": 1 } } } }),
            ),
            // `obj.*` includes the whole subtree at any depth.
            (
                "obj.* keeps the whole subtree",
                json!({ "obj": { "a": { "b": 1 } }, "other": 9 }),
                vec!["obj.*".into()],
                vec![],
                json!({ "obj": { "a": { "b": 1 } } }),
            ),
            // (b) Case A: a scalar sibling on a non-accepting glob path is dropped.
            (
                "a.*.c drops scalar sibling a.x",
                json!({ "a": { "b": { "c": 1 }, "x": 9 } }),
                vec!["a.*.c".into()],
                vec![],
                json!({ "a": { "b": { "c": 1 } } }),
            ),
            // (b) Case B: double glob, scalar sibling dropped.
            (
                "*.*.foo drops scalar sibling a.c",
                json!({ "a": { "b": { "foo": 1, "bar": 2 }, "c": 3 } }),
                vec!["*.*.foo".into()],
                vec![],
                json!({ "a": { "b": { "foo": 1 } } }),
            ),
            // (a) exclude wildcard scrubs a nested field at depth >= 2.
            (
                "exclude *.description strips it at depth 2",
                json!({ "a": { "b": { "description": 1, "keep": 2 } } }),
                vec![],
                vec!["*.description".into()],
                json!({ "a": { "b": { "keep": 2 } } }),
            ),
        ];

        let mut actual: Vec<(&str, Value)> = Vec::new();
        let mut expected: Vec<(&str, Value)> = Vec::new();
        for (label, source, inc, exc, want) in cases {
            actual.push((label, filter_object(&source, &inc, &exc)));
            expected.push((label, want));
        }
        assert_eq!(
            actual, expected,
            "ES _source `*` crosses dots at any depth (makeAnyString); scalars kept only when accepted"
        );
    }

    /// #602 (verification follow-up 2): a DOT-LESS leading/mid wildcard is still
    /// `Σ*` over the full path in ES, so `*id` matches `user.groupid` and
    /// `exclude ["*secret"]` strips `password_secret` at any depth. The dispatch
    /// gate must route any pattern containing `*` (not only dotted ones) through
    /// the automaton — the simple top-level branch understands only a trailing
    /// `*`, so without this `include ["*id"]` dropped the whole source and
    /// `exclude ["*secret"]` silently no-oped.
    #[test]
    fn source_dotless_wildcard_routes_through_the_automaton() {
        // include `*id` selects any key ending in `id`, at any depth.
        assert_eq!(
            filter_object(
                &json!({ "user": { "groupid": 1, "name": 2 }, "id": 3 }),
                &["*id".to_string()],
                &[]
            ),
            json!({ "user": { "groupid": 1 }, "id": 3 }),
            "dot-less `*id` must match nested `user.groupid` and top-level `id` (#602)"
        );
        // exclude `*secret` strips a sensitive key at the top level AND at depth.
        assert_eq!(
            filter_object(
                &json!({
                    "password_secret": 1,
                    "keep": 2,
                    "nested": { "api_secret": 3, "host": 4 }
                }),
                &[],
                &["*secret".to_string()]
            ),
            json!({ "keep": 2, "nested": { "host": 4 } }),
            "dot-less `exclude *secret` must strip `password_secret` and nested `api_secret` (#602)"
        );
    }

    /// #644: ES projects INSIDE an array of objects — the array index is
    /// transparent to a `_source` path, so `include ["tags.name"]` keeps only
    /// each element's `name`, and `exclude ["logs.secret"]` scrubs `secret` from
    /// every element. XERJ currently keeps the array whole (the #602 no-array-
    /// projection scope), leaking the un-selected fields.
    #[test]
    fn source_filter_projects_inside_arrays_of_objects() {
        // include: keep only the named leaf inside each array element.
        assert_eq!(
            filter_object(
                &json!({ "tags": [{ "name": "x", "id": 1 }, { "name": "y", "id": 2 }], "n": 9 }),
                &["tags.name".to_string()],
                &[]
            ),
            json!({ "tags": [{ "name": "x" }, { "name": "y" }] }),
            "#644: include tags.name must project into each array element"
        );
        // exclude: scrub the named leaf from each array element.
        assert_eq!(
            filter_object(
                &json!({ "logs": [{ "msg": 1, "secret": 2 }, { "msg": 3, "secret": 4 }] }),
                &[],
                &["logs.secret".to_string()]
            ),
            json!({ "logs": [{ "msg": 1 }, { "msg": 3 }] }),
            "#644: exclude logs.secret must strip secret from every array element"
        );
        // Emptied elements are pruned, not left as `{}`; a heterogeneous array
        // drops the elements (and scalars) that do not match, keeping the rest.
        assert_eq!(
            filter_object(
                &json!({ "tags": [{ "name": "x", "id": 1 }, { "id": 2 }, "loose"] }),
                &["tags.name".to_string()],
                &[]
            ),
            json!({ "tags": [{ "name": "x" }] }),
            "#644: an emptied array element (and a scalar) is dropped, not kept as an empty object"
        );
        // An array all of whose elements empty → the key is pruned entirely.
        assert_eq!(
            filter_object(
                &json!({ "tags": [{ "id": 1 }, { "id": 2 }], "keep": 5 }),
                &["tags.name".to_string()],
                &[]
            ),
            json!({}),
            "#644: an array that filtering emptied drops its key (no bare [])"
        );
        assert_eq!(
            filter_object(
                &json!({ "tags": [{ "secret": 1 }, { "secret": 2 }] }),
                &[],
                &["tags.secret".to_string()]
            ),
            json!({}),
            "#644: an exclude that empties every element prunes the key"
        );
    }

    /// #653 (follow-up to #644): an array is transparent to a `_source` path at
    /// EVERY depth, so a nested array of arrays of objects is projected too —
    /// `a.name` over `{"a":[[{"name":"x","id":1}]]}` keeps `[[{"name":"x"}]]`.
    /// The array arm previously sent a nested-list element to the scalar branch,
    /// dropping it.
    #[test]
    fn source_filter_projects_inside_nested_arrays() {
        assert_eq!(
            filter_object(
                &json!({ "a": [[{ "name": "x", "id": 1 }], [{ "name": "y", "id": 2 }]] }),
                &["a.name".to_string()],
                &[]
            ),
            json!({ "a": [[{ "name": "x" }], [{ "name": "y" }]] }),
            "#653: a nested array of objects must project at depth"
        );
        // Exclude scrubs at depth through the nested array too.
        assert_eq!(
            filter_object(
                &json!({ "logs": [[{ "msg": 1, "secret": 2 }]] }),
                &[],
                &["logs.secret".to_string()]
            ),
            json!({ "logs": [[{ "msg": 1 }]] }),
            "#653: an exclude scrubs inside a nested array of objects"
        );
    }

    #[test]
    fn explicit_source_true_keeps_mapping_derived_companions() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let original = generated_source();
        let filtered = apply_source_filter(
            vec![hit("doc", 0.9, original.clone())],
            &SourceFilter::Enabled(true),
            &companions,
        );

        assert_eq!(filtered[0].source, original);
    }

    #[test]
    fn explicit_source_include_still_returns_a_generated_companion() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filtered = apply_source_filter(
            vec![hit("doc", 0.9, generated_source())],
            &SourceFilter::Includes(vec!["body_vector".to_string()]),
            &companions,
        );

        assert_eq!(filtered[0].source, json!({"body_vector": [0.1, 0.2, 0.3]}));
    }

    #[test]
    fn omitted_source_measures_companion_payload_reduction() {
        let vector = Value::Array((0..384).map(|_| json!(0.123456)).collect());
        let chunks = Value::Array((0..660).map(|_| vector.clone()).collect());
        let source = json!({
            "body": "x".repeat(250_000),
            "body_vector": vector,
            "body_vector_chunks": chunks
        });
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let before = hit("doc", 0.9, source);
        let before_bytes = serde_json::to_vec(&before).unwrap().len();
        let after = apply_source_filter(vec![before], &SourceFilter::Default, &companions);
        let after_bytes = serde_json::to_vec(&after[0]).unwrap().len();

        eprintln!("default _search hit payload bytes: before={before_bytes}, after={after_bytes}");
        assert!(before_bytes > 2_000_000);
        assert!(after_bytes < 300_000);
        assert!(after_bytes * 8 < before_bytes);
    }

    #[test]
    fn user_declared_vector_suffix_without_embedding_is_not_stripped() {
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("body_vector", FieldType::Keyword))
            .unwrap();
        let companions = generated_embedding_companion_fields(&schema);
        assert!(companions.is_empty());

        let original = json!({"body_vector": "user-owned value"});
        let filtered = apply_source_filter(
            vec![hit("doc", 0.9, original.clone())],
            &SourceFilter::Default,
            &companions,
        );

        assert_eq!(filtered[0].source, original);
    }

    /// Heap-buffer pointer of a field's string value. Stable across map
    /// mutation and moves; changes only if the value itself is deep-copied.
    fn str_buf_ptr(source: &Value, field: &str) -> *const u8 {
        source[field].as_str().unwrap().as_ptr()
    }

    // Issue #311: with no embedding mappings there is nothing to strip, so
    // the default `_source` arm must hand every hit back untouched instead
    // of deep-copying O(source bytes) per hit on the hottest read path.
    #[test]
    fn default_source_without_companions_is_a_zero_copy_passthrough() {
        let companions = generated_embedding_companion_fields(&Schema::empty());
        assert!(companions.is_empty());

        let hits = vec![hit(
            "doc",
            0.9,
            json!({"body": "the source text", "title": "a user field"}),
        )];
        let body_ptr = str_buf_ptr(&hits[0].source, "body");
        let title_ptr = str_buf_ptr(&hits[0].source, "title");

        let filtered = apply_source_filter(hits, &SourceFilter::Default, &companions);

        assert_eq!(
            filtered[0].source,
            json!({"body": "the source text", "title": "a user field"})
        );
        assert_eq!(str_buf_ptr(&filtered[0].source, "body"), body_ptr);
        assert_eq!(str_buf_ptr(&filtered[0].source, "title"), title_ptr);
    }

    // Issue #311, companion-bearing indexes: strip the companions in place
    // rather than rebuilding the map with a deep clone of every kept value.
    #[test]
    fn default_source_with_companions_strips_in_place_without_deep_copy() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let hits = vec![hit("doc", 0.9, generated_source())];
        let body_ptr = str_buf_ptr(&hits[0].source, "body");
        let title_ptr = str_buf_ptr(&hits[0].source, "title");

        let filtered = apply_source_filter(hits, &SourceFilter::Default, &companions);

        assert_eq!(
            filtered[0].source,
            json!({"body": "the source text", "title": "a user field"})
        );
        assert_eq!(str_buf_ptr(&filtered[0].source, "body"), body_ptr);
        assert_eq!(str_buf_ptr(&filtered[0].source, "title"), title_ptr);
    }
}

/// The `_savings` statistic, at the point where the bytes are actually
/// dropped.
///
/// Every byte count asserted here is recomputed from scratch with plain
/// `serde_json` — never by re-running the implementation's own arithmetic —
/// because a metric that only agrees with itself proves nothing.
///
/// The load-bearing property, after a blind UX dogfood caught the earlier
/// revision overstating by ~9.3x: **the baseline is the default-projected
/// response**, not the raw stored document. Several tests below exist purely
/// to pin that down.
#[cfg(test)]
mod savings_tests {
    use super::*;
    use serde_json::json;
    use std::collections::HashMap;
    use xerj_common::types::{EmbeddingConfig, FieldConfig, FieldType};

    fn embedded_schema() -> Schema {
        let mut schema = Schema::empty();
        schema
            .add_field(
                FieldConfig::new("body", FieldType::Text).with_embedding(EmbeddingConfig {
                    endpoint: None,
                    model: None,
                    target_field: None,
                }),
            )
            .unwrap();
        schema
    }

    fn hit(id: &str, source: Value) -> Hit {
        Hit {
            id: id.to_string(),
            score: 1.0,
            source,
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        }
    }

    /// Exact mode: the byte-for-byte assertions compare against an
    /// independently serialized oracle, so they must not run against the
    /// sampled estimator. Sampling accuracy has its own tests.
    fn measuring(source: SourceFilter) -> SearchRequest {
        SearchRequest {
            source,
            savings: SavingsMode::Exact,
            ..SearchRequest::default()
        }
    }

    fn measuring_sampled(source: SourceFilter) -> SearchRequest {
        SearchRequest {
            source,
            savings: SavingsMode::Sampled,
            ..SearchRequest::default()
        }
    }

    /// A companion-bearing document: user fields plus the generated vector
    /// and its per-chunk companions. The user fields are deliberately large
    /// enough that a projection clears the reporting floor.
    fn companion_source() -> Value {
        let vector = Value::Array((0..384).map(|_| json!(0.123456)).collect());
        json!({
            "title": "quarterly report",
            "author": "finance",
            "body": "x".repeat(8_000),
            "body_vector": vector,
            "body_vector_chunks": [[0.5, 0.25], [0.125, 0.0625]],
        })
    }

    /// The independent oracle for the baseline: what the caller would have
    /// received had they written no `_source` clause at all. Built here by
    /// hand from the same document, with nothing borrowed from the engine.
    fn default_projected(source: &Value, companions: &HashSet<String>) -> Value {
        let mut map = source.as_object().cloned().unwrap_or_default();
        map.retain(|k, _| !companions.contains(k));
        Value::Object(map)
    }

    fn wire_len(value: &Value) -> u64 {
        serde_json::to_vec(value).unwrap().len() as u64
    }

    // ── the baseline: the whole point of this revision ─────────────────────

    #[test]
    fn a_projection_is_measured_against_the_response_you_would_have_got() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let source = companion_source();
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        let request = measuring(filter.clone());

        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("doc", source.clone())],
            &filter,
            &companions,
            Some(&request),
        );
        let savings = savings.expect("dropping an 8 KB body is a real saving");

        // The oracle: default projection minus what was actually returned.
        // NOT the raw stored document — the embedding companions were never
        // going to be sent, so crediting this projection with removing them
        // would overstate the saving by the size of the vectors.
        let expected =
            wire_len(&default_projected(&source, &companions)) - wire_len(&filtered[0].source);
        assert_eq!(
            savings.bytes, expected,
            "the baseline must be the default-projected response, not the stored document"
        );

        // And prove the two baselines really differ here, so the assertion
        // above is not vacuous.
        let against_stored = wire_len(&source) - wire_len(&filtered[0].source);
        assert!(
            against_stored > savings.bytes,
            "this fixture must have companions worth counting, or the test proves nothing"
        );
    }

    #[test]
    fn the_engines_own_default_is_never_claimed_as_a_saving() {
        // The failure this exists to prevent: a caller who writes no `_source`
        // clause at all, asks for everything, and is told they saved 22 MB.
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let request = measuring(SourceFilter::Default);
        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("doc", companion_source())],
            &SourceFilter::Default,
            &companions,
            Some(&request),
        );
        assert!(
            savings.is_none(),
            "stripping generated vectors is what this engine does on every default \
             response; it is not a choice the caller made and not a saving relative \
             to what they would otherwise have received"
        );
        assert!(
            filtered[0].source.get("body_vector").is_none(),
            "the stripping itself must still happen — only the claim is withdrawn"
        );
    }

    #[test]
    fn projecting_more_than_the_default_is_not_a_saving() {
        // `_source: ["body_vector"]` on a document whose vector dwarfs its
        // user fields returns MORE than the default projection would have.
        // More is not less, and `saturating_sub` must not be allowed to
        // report the shortfall as a win.
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let source = json!({
            "title": "t",
            "body": "short",
            "body_vector": Value::Array((0..384).map(|_| json!(0.123456)).collect()),
        });
        let filter = SourceFilter::Includes(vec!["body_vector".to_string()]);
        let request = measuring(filter.clone());
        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("doc", source.clone())],
            &filter,
            &companions,
            Some(&request),
        );
        assert!(
            filtered[0].source.get("body_vector").is_some(),
            "the caller asked for the vector and must still receive it"
        );
        assert!(
            wire_len(&filtered[0].source) > wire_len(&default_projected(&source, &companions)),
            "this fixture must actually return more than the default, or it proves nothing"
        );
        assert!(
            savings.is_none(),
            "a response larger than the default withheld nothing"
        );
    }

    #[test]
    fn projecting_a_companion_alongside_a_large_body_still_measures_honestly() {
        // The mirror case: the same projection on a document with an 8 KB
        // body DOES withhold bytes, because the body did not go out. The
        // saving is real and is still measured against the default
        // projection, companion or not.
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let source = companion_source();
        let filter = SourceFilter::Includes(vec!["body_vector".to_string()]);
        let request = measuring(filter.clone());
        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("doc", source.clone())],
            &filter,
            &companions,
            Some(&request),
        );
        let expected =
            wire_len(&default_projected(&source, &companions)) - wire_len(&filtered[0].source);
        assert_eq!(
            savings.expect("the 8 KB body did not go out").bytes,
            expected
        );
    }

    #[test]
    fn suppressed_source_is_measured_against_the_default_projection_too() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let source = companion_source();
        let request = SearchRequest {
            source: SourceFilter::Enabled(false),
            savings: SavingsMode::Exact,
            ..SearchRequest::default()
        };
        let (_, savings) = apply_source_filter_measured(
            vec![hit("doc", source.clone())],
            &SourceFilter::Enabled(false),
            &companions,
            Some(&request),
        );
        let savings = savings.expect("withholding an 8 KB document is a real saving");
        assert_eq!(
            savings.bytes,
            wire_len(&default_projected(&source, &companions)),
            "`_source: false` withholds the default projection, not the raw document"
        );
        assert!(
            savings.substitutable,
            "the response layer may hand some of this back via `fields`, and must be told"
        );
    }

    // ── the reporting floor ───────────────────────────────────────────────

    #[test]
    fn a_saving_too_small_to_be_worth_printing_is_not_printed() {
        // Measured on a real corpus: 135 bytes of block to announce a 19-byte
        // saving, net -116, on ordinary single-document lookups.
        let savings = PayloadSavings::new(
            SavingsMethod::Sampled,
            "note",
            false,
            vec![("d".into(), 19)],
        )
        .expect("19 bytes is still a measurement");
        assert_eq!(savings.bytes, 19);
        assert!(
            savings.rescoped(19).is_none(),
            "a block that costs more than it reports is a net loss to the budget it \
             claims to protect"
        );
    }

    #[test]
    fn the_floor_is_measured_against_the_block_that_would_be_printed() {
        let savings = PayloadSavings::new(
            SavingsMethod::Sampled,
            "a note",
            false,
            vec![("d".into(), 1)],
        )
        .expect("non-zero");
        // Walk up until it prints, then check the ratio actually held.
        let mut emitted_at = None;
        for bytes in 1..4000u64 {
            if let Some(block) = savings.rescoped(bytes) {
                emitted_at = Some((bytes, serde_json::to_vec(&block).unwrap().len() as u64 + 11));
                break;
            }
        }
        let (bytes, cost) = emitted_at.expect("it must print eventually");
        assert!(
            bytes >= cost * 10,
            "first emission was {bytes} bytes against a {cost}-byte block — under 10x"
        );
        assert!(
            savings.rescoped(bytes - 1).is_none(),
            "the threshold must be sharp, not approximate"
        );
    }

    // ── the wire block ────────────────────────────────────────────────────

    #[test]
    fn the_block_carries_no_derivable_or_constant_fields() {
        let savings = PayloadSavings::new(
            SavingsMethod::Sampled,
            "_source narrowed to the 2 fields you listed",
            false,
            vec![("d".into(), 100_000)],
        )
        .unwrap();
        let block = savings.rescoped(100_000).expect("well over the floor");
        let keys: Vec<&str> = block
            .as_object()
            .unwrap()
            .keys()
            .map(String::as_str)
            .collect();
        assert_eq!(
            keys,
            vec!["bytes", "measured", "note"],
            "44% of the old block was a constant divisor, a constant label, and a \
             division the reader could do themselves"
        );
        assert!(block.get("tokens_approx").is_none());
        assert!(block.get("bytes_per_token").is_none());
    }

    #[test]
    fn only_an_estimate_is_labelled() {
        let per_hit = vec![("d".to_string(), 100_000u64)];
        let sampled =
            PayloadSavings::new(SavingsMethod::Sampled, "n", false, per_hit.clone()).unwrap();
        let exact = PayloadSavings::new(SavingsMethod::Exact, "n", false, per_hit).unwrap();
        assert_eq!(
            sampled.rescoped(100_000).unwrap()["measured"],
            json!("sampled"),
            "an extrapolated figure must always say so"
        );
        assert!(
            exact.rescoped(100_000).unwrap().get("measured").is_none(),
            "absence means exact — a precise number needs no hedge"
        );
    }

    #[test]
    fn the_wire_block_stays_small() {
        let mut widest = 0usize;
        for note in [
            "_source narrowed to the 2 fields you listed",
            "_source excluded the 3 fields you listed",
            "highlight fragments returned in place of _source",
            "fields returned in place of _source",
            "_source withheld, as requested",
        ] {
            let savings = PayloadSavings::new(
                SavingsMethod::Sampled,
                note,
                false,
                vec![("d".into(), 9_999_999)],
            )
            .unwrap();
            let block = savings.rescoped(9_999_999).unwrap();
            let wire = serde_json::to_vec(&block).unwrap().len() + 11;
            widest = widest.max(wire);
        }
        assert!(
            widest <= 120,
            "the block is {widest} bytes; it was 147 before the constants came out"
        );
    }

    // ── the notes: counts from the request, and no schema claims ──────────

    #[test]
    fn the_note_counts_what_you_asked_for_not_what_came_back() {
        // Reported bug: asking for one field that this document lacks was
        // answered "Sent the 0 fields you asked for" — the caller's own
        // request, reported back to them wrongly.
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filter = SourceFilter::Includes(vec!["absent_field".to_string()]);
        let request = measuring(filter.clone());
        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("doc", companion_source())],
            &filter,
            &companions,
            Some(&request),
        );
        assert_eq!(
            filtered[0].source,
            json!({}),
            "the document genuinely has none of the requested fields"
        );
        let savings = savings.expect("the whole default projection was withheld");
        assert_eq!(
            savings.note, "_source narrowed to the 1 field you listed",
            "the count is a fact about the request, not about what matched"
        );
    }

    #[test]
    fn the_note_makes_no_claim_about_the_schema() {
        // Reported bug: the `not all M` denominator moved 8 -> 11 -> 12 -> 15
        // on the same query at different page sizes, because it described the
        // widest document on the page. Each number was true; together they
        // read as an unreliable statistic. There is no denominator now, so
        // documents of different widths cannot move it.
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        let request = measuring(filter.clone());

        let narrow = json!({"title": "t", "body": "y".repeat(8_000)});
        let wide = {
            let mut m = companion_source().as_object().cloned().unwrap();
            m.insert("extra_a".into(), json!(1));
            m.insert("extra_b".into(), json!(2));
            Value::Object(m)
        };
        let notes: Vec<String> = [vec![hit("a", narrow)], vec![hit("b", wide)]]
            .into_iter()
            .map(|page| {
                apply_source_filter_measured(page, &filter, &companions, Some(&request))
                    .1
                    .expect("both pages saved bytes")
                    .note
            })
            .collect();
        assert_eq!(
            notes[0], notes[1],
            "documents of different widths must not change the sentence"
        );
    }

    #[test]
    fn distinct_mechanisms_produce_distinct_sentences() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let mut notes = Vec::new();
        for (filter, request) in [
            (
                SourceFilter::Includes(vec!["title".to_string()]),
                measuring(SourceFilter::Includes(vec!["title".to_string()])),
            ),
            (
                SourceFilter::Fields {
                    includes: Vec::new(),
                    excludes: vec!["body".to_string()],
                },
                measuring(SourceFilter::Fields {
                    includes: Vec::new(),
                    excludes: vec!["body".to_string()],
                }),
            ),
            (
                SourceFilter::Enabled(false),
                SearchRequest {
                    source: SourceFilter::Enabled(false),
                    savings: SavingsMode::Exact,
                    ..SearchRequest::default()
                },
            ),
            (
                SourceFilter::Enabled(false),
                SearchRequest {
                    source: SourceFilter::Enabled(false),
                    savings: SavingsMode::Exact,
                    fields: vec!["title".to_string()],
                    ..SearchRequest::default()
                },
            ),
        ] {
            let (_, savings) = apply_source_filter_measured(
                vec![hit("doc", companion_source())],
                &filter,
                &companions,
                Some(&request),
            );
            notes.push(savings.expect("each mechanism withheld bytes").note);
        }
        assert_eq!(
            notes,
            vec![
                "_source narrowed to the 1 field you listed",
                "_source excluded the 1 field you listed",
                "_source withheld, as requested",
                "fields returned in place of _source",
            ],
            "the note names the mechanism; it must not read alike across mechanisms"
        );
    }

    #[test]
    fn suppressed_source_with_highlight_is_reported_net_of_the_fragments() {
        let source = json!({ "body": "x".repeat(8_000) });
        let mut h = hit("doc", source.clone());
        let fragments: HashMap<String, Vec<String>> = HashMap::from([(
            "body".to_string(),
            vec!["…the <em>relevant</em> sentence…".to_string()],
        )]);
        h.highlight = Some(fragments.clone());
        let request = SearchRequest {
            source: SourceFilter::Enabled(false),
            savings: SavingsMode::Exact,
            highlight: Some(HighlightRequest::default()),
            ..SearchRequest::default()
        };

        let (_, savings) = apply_source_filter_measured(
            vec![h],
            &SourceFilter::Enabled(false),
            &HashSet::new(),
            Some(&request),
        );
        let savings = savings.expect("an 8 KB body replaced by one fragment is a real saving");
        assert_eq!(
            savings.bytes,
            wire_len(&source) - wire_len(&json!(fragments))
        );
        assert_eq!(
            savings.note,
            "highlight fragments returned in place of _source"
        );
    }

    // ── the anti-inflation half: silence when nothing was saved ────────────

    #[test]
    fn an_index_without_companions_and_no_projection_reports_nothing() {
        let request = measuring(SourceFilter::Default);
        let (_, savings) = apply_source_filter_measured(
            vec![hit("doc", json!({"body": "text", "title": "a user field"}))],
            &SourceFilter::Default,
            &HashSet::new(),
            Some(&request),
        );
        assert!(savings.is_none(), "nothing was withheld");
    }

    #[test]
    fn asking_for_the_whole_document_reports_nothing_at_all() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let request = measuring(SourceFilter::Enabled(true));
        let (_, savings) = apply_source_filter_measured(
            vec![hit("doc", companion_source())],
            &SourceFilter::Enabled(true),
            &companions,
            Some(&request),
        );
        assert!(
            savings.is_none(),
            "`_source: true` returns MORE than the default projection, not less"
        );
    }

    #[test]
    fn a_projection_that_drops_nothing_reports_nothing_at_all() {
        let source = json!({"title": "t", "year": 2026});
        let filter = SourceFilter::Includes(vec!["title".to_string(), "year".to_string()]);
        let request = measuring(filter.clone());
        let (_, savings) = apply_source_filter_measured(
            vec![hit("doc", source)],
            &filter,
            &HashSet::new(),
            Some(&request),
        );
        assert!(
            savings.is_none(),
            "asking for all N of N fields saves nothing, however it is spelled"
        );
    }

    #[test]
    fn an_empty_page_reports_nothing_at_all() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        let request = measuring(filter.clone());
        let (_, savings) =
            apply_source_filter_measured(Vec::new(), &filter, &companions, Some(&request));
        assert!(
            savings.is_none(),
            "an aggregation-only page returned no documents, so it withheld no document bytes"
        );
    }

    #[test]
    fn fragments_larger_than_the_document_report_nothing_at_all() {
        let mut h = hit("doc", json!({ "body": "short" }));
        h.highlight = Some(HashMap::from([(
            "body".to_string(),
            vec!["<em>short</em>".to_string(); 8],
        )]));
        let request = SearchRequest {
            source: SourceFilter::Enabled(false),
            savings: SavingsMode::Exact,
            highlight: Some(HighlightRequest::default()),
            ..SearchRequest::default()
        };
        let (_, savings) = apply_source_filter_measured(
            vec![h],
            &SourceFilter::Enabled(false),
            &HashSet::new(),
            Some(&request),
        );
        assert!(
            savings.is_none(),
            "when the substitute costs more than the original there is no saving to report"
        );
    }

    #[test]
    fn measurement_is_off_unless_the_caller_asks() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("doc", companion_source())],
            &filter,
            &companions,
            None,
        );
        assert!(savings.is_none(), "no opt-in, no measurement, no block");
        assert_eq!(
            filtered[0].source,
            json!({"title": "quarterly report"}),
            "the filtering itself is unchanged by the measurement being off"
        );
    }

    #[test]
    fn a_request_that_declines_measurement_gets_nothing() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        let request = SearchRequest {
            source: filter.clone(),
            savings: SavingsMode::Off,
            ..SearchRequest::default()
        };
        let (_, savings) = apply_source_filter_measured(
            vec![hit("doc", companion_source())],
            &filter,
            &companions,
            Some(&request),
        );
        assert!(savings.is_none(), "`?savings=false` means no block");
    }

    #[test]
    fn a_zero_total_can_never_be_rendered() {
        assert!(
            PayloadSavings::new(
                SavingsMethod::Exact,
                "anything",
                false,
                vec![("d".into(), 0)]
            )
            .is_none(),
            "the constructor is the single gate that makes a 0-byte block unrepresentable"
        );
        let savings = PayloadSavings::new(
            SavingsMethod::Exact,
            "note",
            false,
            vec![("d".into(), 100_000)],
        )
        .unwrap();
        assert!(
            savings.rescoped(0).is_none(),
            "re-scoping to a page that saved nothing must also produce nothing"
        );
    }

    #[test]
    fn every_hit_on_the_page_is_attributed_and_summed() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let source = companion_source();
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        let request = measuring(filter.clone());

        let (filtered, savings) = apply_source_filter_measured(
            vec![hit("a", source.clone()), hit("b", source.clone())],
            &filter,
            &companions,
            Some(&request),
        );
        let savings = savings.expect("two hits saved bytes");
        let per_doc =
            wire_len(&default_projected(&source, &companions)) - wire_len(&filtered[0].source);
        assert_eq!(savings.bytes, per_doc * 2);
        assert_eq!(
            savings.per_hit,
            vec![("a".to_string(), per_doc), ("b".to_string(), per_doc)],
            "per-hit attribution is what lets the API layer re-sum over the page it really emits"
        );
    }

    #[test]
    fn hybrid_legs_that_return_the_same_document_count_it_once() {
        let leg = |id: &str| {
            PayloadSavings::new(
                SavingsMethod::Exact,
                "note",
                false,
                vec![(id.to_string(), 500)],
            )
            .unwrap()
        };
        let merged = merge_sub_savings(vec![leg("a"), leg("a")]).expect("one document saved bytes");
        assert_eq!(
            merged.bytes, 500,
            "a document found by both legs saved its bytes once, not twice"
        );
    }

    // ── the sampled estimator: on by default, so its error is a first-class
    //    property, not an implementation detail ─────────────────────────────

    /// Deterministic LCG — the shapes below must be identical on every run,
    /// or a tolerance assertion is just a coin flip.
    struct Lcg(u64);
    impl Lcg {
        fn next_unit(&mut self) -> f64 {
            self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1);
            ((self.0 >> 11) as f64 / (1u64 << 53) as f64) * 2.0 - 1.0
        }
    }

    /// The shape XERJ's own built-in embedder actually emits: mostly exact
    /// zeros with a scattered minority of full-width floats. This bimodal
    /// distribution is what breaks naive sampling.
    fn sparse_companion_vector() -> Value {
        let mut rng = Lcg(0x5eed);
        Value::Array(
            (0..384)
                .map(|i| {
                    if i % 6 == 0 {
                        json!(rng.next_unit())
                    } else {
                        json!(0.0)
                    }
                })
                .collect(),
        )
    }

    fn dense_vector(dims: usize, seed: u64) -> Value {
        let mut rng = Lcg(seed);
        Value::Array((0..dims).map(|_| json!(rng.next_unit())).collect())
    }

    #[test]
    fn sampling_tracks_the_exact_count_on_the_shapes_that_matter() {
        let mut rng = Lcg(99);
        let chunk_matrix = Value::Array((0..64).map(|i| dense_vector(384, 1000 + i)).collect());
        let mixed = Value::Array(
            (0..1000)
                .map(|i| match i % 4 {
                    0 => json!(1.0e-9),
                    1 => json!(1),
                    2 => json!(123456.789),
                    _ => json!(rng.next_unit()),
                })
                .collect(),
        );
        let cases: Vec<(&str, Value, f64)> = vec![
            ("sparse companion (384)", sparse_companion_vector(), 0.5),
            ("dense vector (384)", dense_vector(384, 7), 1.5),
            ("dense vector (1536)", dense_vector(1536, 11), 1.5),
            ("chunk matrix (64x384)", chunk_matrix, 1.5),
            ("mixed magnitudes (1000)", mixed, 3.0),
            (
                "integers (1000)",
                Value::Array((0..1000).map(|i| json!(i * 7919)).collect()),
                0.0,
            ),
        ];
        for (name, value, tolerance) in cases {
            let exact = json_wire_len(&value);
            let sampled = json_len_sampled(&value);
            let err = (sampled as f64 - exact as f64) / exact as f64 * 100.0;
            eprintln!("{name}: exact={exact} sampled={sampled} err={err:+.2}%");
            assert!(
                err.abs() <= tolerance,
                "{name}: sampled estimate is {err:+.2}% off exact \
                 (exact={exact}, sampled={sampled}), budget {tolerance}%"
            );
        }
    }

    #[test]
    fn anything_cheap_enough_to_count_exactly_is_counted_exactly() {
        for value in [
            json!({"title": "quarterly report", "year": 2026}),
            json!({"body": "x".repeat(20_000)}),
            dense_vector(SAVINGS_ARRAY_SAMPLE, 3),
            json!([1, 2, 3, 4, 5]),
            json!([]),
            json!({}),
        ] {
            assert_eq!(
                json_len_sampled(&value),
                json_wire_len(&value),
                "no sampling should have happened for {value}"
            );
        }
    }

    #[test]
    fn zeros_never_enter_the_sample() {
        let all_zero = Value::Array((0..4096).map(|_| json!(0.0)).collect());
        assert_eq!(json_len_sampled(&all_zero), json_wire_len(&all_zero));
        let signed_zero = Value::Array(
            (0..4096)
                .map(|i| json!(if i % 2 == 0 { 0.0 } else { -0.0 }))
                .collect(),
        );
        assert_eq!(json_len_sampled(&signed_zero), json_wire_len(&signed_zero));
    }

    #[test]
    fn the_default_projection_baseline_is_itself_sampled_consistently() {
        // The baseline never serializes the companions, so it must agree with
        // an independently built default projection under both modes.
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let source = companion_source();
        let oracle = wire_len(&default_projected(&source, &companions));
        assert_eq!(
            default_projection_len(&source, &companions, SavingsMode::Exact),
            oracle
        );
        let sampled = default_projection_len(&source, &companions, SavingsMode::Sampled);
        let err = (sampled as f64 - oracle as f64) / oracle as f64 * 100.0;
        assert!(
            err.abs() <= 1.5,
            "baseline drifted {err:+.2}% under sampling"
        );
    }

    #[test]
    fn the_method_is_labelled_on_every_record() {
        let companions = generated_embedding_companion_fields(&embedded_schema());
        let filter = SourceFilter::Includes(vec!["title".to_string()]);
        for (request, expected) in [
            (measuring(filter.clone()), SavingsMethod::Exact),
            (measuring_sampled(filter.clone()), SavingsMethod::Sampled),
        ] {
            let (_, savings) = apply_source_filter_measured(
                vec![hit("doc", companion_source())],
                &filter,
                &companions,
                Some(&request),
            );
            assert_eq!(
                savings.expect("bytes were withheld").measured,
                expected,
                "a reader must be able to tell an estimate from an exact count"
            );
        }
    }
}

/// Simple field pattern matching — supports trailing `*` wildcard.
fn field_matches(field: &str, pattern: &str) -> bool {
    if let Some(prefix) = pattern.strip_suffix('*') {
        field.starts_with(prefix)
    } else {
        field == pattern
    }
}

/// One `semantic_text` field the semantic highlighter can read.
///
/// `name` is what a highlight request may say (the mapped name, or the alias
/// the semantic query used). `source_field` is the `_source` key holding the
/// text. `vector_field` is the companion the ingest path stored chunk vectors
/// under.
#[derive(Clone)]
struct SemanticFieldRef {
    name: String,
    source_field: String,
    vector_field: String,
}

/// Query embedding and field map for one semantic search that asked for
/// highlights (#1947).
///
/// Lives in a task-local rather than on [`SearchRequest`]: the kNN executors
/// already take the request, and plain `knn` must not grow a parameter it
/// never reads. `run_semantic_with_deadline` sets the scope; result shaping
/// reads it. A search that is not inside that scope highlights nothing here.
#[derive(Clone)]
struct SemanticHighlightPlan {
    query_vec: Vec<f32>,
    dims: usize,
    similarity: String,
    fields: Vec<SemanticFieldRef>,
    /// Re-embed chunk text with the built-in lexical embedder. When `false`,
    /// an active backend produced the stored chunk vectors and those are
    /// scored instead — re-embedding with the lexical embedder would compare
    /// vectors from two different spaces.
    lexical: bool,
}

tokio::task_local! {
    static SEMANTIC_HIGHLIGHT_PLAN: SemanticHighlightPlan;
}

fn collect_semantic_highlight_fields(
    schema: &Schema,
    query_field: &str,
    resolved_field: &str,
) -> Vec<SemanticFieldRef> {
    let mut fields = Vec::new();
    for fc in &schema.fields {
        let Some(emb) = fc.embedding.as_ref() else {
            continue;
        };
        let vector_field = emb
            .target_field
            .clone()
            .unwrap_or_else(|| format!("{}_vector", fc.name));
        fields.push(SemanticFieldRef {
            name: fc.name.clone(),
            source_field: fc.name.clone(),
            vector_field,
        });
    }
    // A query on an alias highlights either the alias or the concrete field.
    if query_field != resolved_field {
        if let Some(src) = fields
            .iter()
            .find(|f| f.source_field == resolved_field)
            .cloned()
        {
            fields.push(SemanticFieldRef {
                name: query_field.to_string(),
                source_field: src.source_field,
                vector_field: src.vector_field,
            });
        }
    }
    fields
}

fn semantic_highlight_plan(
    hl: &HighlightRequest,
    fields: Vec<SemanticFieldRef>,
    query_vec: Vec<f32>,
    dims: usize,
    similarity: String,
    lexical: bool,
) -> Option<SemanticHighlightPlan> {
    if fields.is_empty() || query_vec.is_empty() {
        return None;
    }
    let wanted = hl.fields.iter().any(|(name, opts)| {
        semantic_highlighter_selected(opts, hl)
            && fields
                .iter()
                .any(|field| name_selects_semantic_field(name, field))
    });
    if !wanted {
        return None;
    }
    Some(SemanticHighlightPlan {
        query_vec,
        dims,
        similarity,
        fields,
        lexical,
    })
}

fn name_selects_semantic_field(pattern: &str, field: &SemanticFieldRef) -> bool {
    if pattern.contains('*') {
        field_matches(&field.name, pattern) || field_matches(&field.source_field, pattern)
    } else {
        pattern == field.name || pattern == field.source_field
    }
}

/// `None` and `"semantic"` select the semantic highlighter. Any other
/// explicit type (`unified`, `plain`, `fvh`) stays on the lexical pass.
fn semantic_highlighter_selected(opts: &HighlightFieldOptions, hl: &HighlightRequest) -> bool {
    match opts
        .highlighter_type
        .as_deref()
        .or(hl.highlighter_type.as_deref())
    {
        Some("semantic") | None => true,
        Some(_) => false,
    }
}

fn semantic_highlight_hit(
    source: &Value,
    hl: &HighlightRequest,
    plan: &SemanticHighlightPlan,
) -> std::collections::HashMap<String, Vec<String>> {
    let mut out = std::collections::HashMap::new();
    let mut seen = HashSet::new();
    // Explicit names win over a pattern that covers the same field, matching
    // `expand_highlight_field_patterns`.
    let mut patterns = Vec::new();
    for (name, opts) in &hl.fields {
        if name.contains('*') {
            patterns.push((name, opts));
            continue;
        }
        if !semantic_highlighter_selected(opts, hl) {
            continue;
        }
        let Some(field) = find_semantic_field(name, &plan.fields) else {
            continue;
        };
        seen.insert(field.name.clone());
        let fragments = semantic_fragments(source, field, opts, hl, plan);
        if !fragments.is_empty() {
            out.insert(name.clone(), fragments);
        }
    }
    for (pattern, opts) in patterns {
        if !semantic_highlighter_selected(opts, hl) {
            continue;
        }
        for field in plan
            .fields
            .iter()
            .filter(|field| name_selects_semantic_field(pattern, field))
        {
            if !seen.insert(field.name.clone()) {
                continue;
            }
            let fragments = semantic_fragments(source, field, opts, hl, plan);
            if !fragments.is_empty() {
                out.insert(field.name.clone(), fragments);
            }
        }
    }
    out
}

fn find_semantic_field<'a>(
    name: &str,
    fields: &'a [SemanticFieldRef],
) -> Option<&'a SemanticFieldRef> {
    fields
        .iter()
        .find(|field| field.name == name)
        .or_else(|| fields.iter().find(|field| field.source_field == name))
}

/// Best-scoring chunks of one `semantic_text` field.
///
/// Elasticsearch's semantic highlighter (the default for `semantic_text`)
/// returns the chunks produced at ingest, ordered by similarity to the query,
/// without `<em>` tags. Approach only — the chunk text and vectors are this
/// engine's, scored with [`compute_vector_similarity`]. `number_of_fragments`
/// limits how many chunks are kept (default 5; `0` is the whole field).
/// `order: none` emits that selection in document order; anything else,
/// including the default, emits it by score. Ties keep the earlier chunk,
/// the same rule as [`choose_passage_winner`].
fn semantic_fragments(
    source: &Value,
    field: &SemanticFieldRef,
    opts: &HighlightFieldOptions,
    hl: &HighlightRequest,
    plan: &SemanticHighlightPlan,
) -> Vec<String> {
    let Some(text_val) = get_field_value(source, &field.source_field) else {
        return Vec::new();
    };
    let Some(text) = text_val.as_str() else {
        return Vec::new();
    };
    if text.is_empty() {
        return Vec::new();
    }
    let n = opts
        .number_of_fragments
        .or(hl.number_of_fragments)
        .unwrap_or(5);
    if n == 0 {
        return vec![text.to_string()];
    }
    let passages = semantic_passages(text, source, &field.vector_field);
    if passages.is_empty() {
        return Vec::new();
    }
    let stored = if plan.lexical {
        Vec::new()
    } else {
        stored_chunk_vectors(source, &field.vector_field)
    };
    let mut scored: Vec<(u32, f32, String)> = passages
        .into_iter()
        .map(|(ordinal, raw)| {
            let score = chunk_score(plan, &raw, ordinal, &stored);
            (ordinal, score, raw)
        })
        .collect();
    scored.sort_by(|a, b| {
        b.1.partial_cmp(&a.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then(a.0.cmp(&b.0))
    });
    scored.truncate(n);
    let order = opts
        .order
        .as_deref()
        .or(hl.order.as_deref())
        .unwrap_or("score");
    if order == "none" {
        scored.sort_by_key(|chunk| chunk.0);
    }
    scored
        .into_iter()
        .map(|(_, _, raw)| raw.trim().to_string())
        .filter(|fragment| !fragment.is_empty())
        .collect()
}

fn chunk_score(plan: &SemanticHighlightPlan, text: &str, ordinal: u32, stored: &[Vec<f32>]) -> f32 {
    let vector = if plan.lexical {
        xerj_ai::local::local_embed(text, plan.dims)
    } else {
        let Some(stored) = stored.get(ordinal as usize) else {
            return f32::NEG_INFINITY;
        };
        stored.clone()
    };
    if vector.len() != plan.query_vec.len() {
        return f32::NEG_INFINITY;
    }
    compute_vector_similarity(&plan.similarity, &plan.query_vec, &vector)
}

/// Ingest chunk slices when passage metadata is present and valid, otherwise
/// the same chunker ingest uses. A single short value is one passage covering
/// the whole field, matching `local_chunk_vectors`.
fn semantic_passages(text: &str, source: &Value, vector_field: &str) -> Vec<(u32, String)> {
    if let Some(passages) = passages_from_metadata(text, source, vector_field) {
        return passages;
    }
    let chunks = semantic_chunker().chunk(text, None);
    if chunks.len() <= 1 {
        return vec![(0, text.to_string())];
    }
    chunks
        .into_iter()
        .enumerate()
        .map(|(ordinal, chunk)| (ordinal as u32, chunk.text))
        .collect()
}

fn passages_from_metadata(
    text: &str,
    source: &Value,
    vector_field: &str,
) -> Option<Vec<(u32, String)>> {
    let chunks = source
        .get(passage_metadata_field(vector_field))?
        .as_object()?
        .get("chunks")?
        .as_array()?;
    if chunks.is_empty() {
        return None;
    }
    let mut passages = Vec::with_capacity(chunks.len());
    for (ordinal, pair) in chunks.iter().enumerate() {
        let pair = pair.as_array()?;
        if pair.len() != 2 {
            return None;
        }
        let start = usize::try_from(pair[0].as_u64()?).ok()?;
        let end = usize::try_from(pair[1].as_u64()?).ok()?;
        if start > end
            || end > text.len()
            || !text.is_char_boundary(start)
            || !text.is_char_boundary(end)
        {
            return None;
        }
        passages.push((ordinal as u32, text[start..end].to_string()));
    }
    Some(passages)
}

fn stored_chunk_vectors(source: &Value, vector_field: &str) -> Vec<Vec<f32>> {
    let Some(Value::Array(rows)) = source.get(format!("{vector_field}_chunks")) else {
        return Vec::new();
    };
    let mut vectors = Vec::with_capacity(rows.len());
    for row in rows {
        let Some(vector) = json_f32_vector(row) else {
            return Vec::new();
        };
        vectors.push(vector);
    }
    vectors
}

fn json_f32_vector(value: &Value) -> Option<Vec<f32>> {
    // #1940 stores each chunk as a `xerj:f32:` string. A number array is
    // still valid for segments written before that. Non-finite components
    // in a number array keep the previous `as_f64() as f32` read.
    if value
        .as_str()
        .is_some_and(xerj_common::packed_f32::is_packed_f32)
    {
        return xerj_common::packed_f32::unpack_f32_vector(value.as_str()?);
    }
    let row = value.as_array()?;
    let mut vector = Vec::with_capacity(row.len());
    for component in row {
        vector.push(component.as_f64()? as f32);
    }
    Some(vector)
}

/// Apply highlight to hits, generating fragments per requested field.
///
/// For each field listed in `highlight.fields`, the stored field value is
/// searched for matching terms.  A short fragment surrounding the first match
/// is returned with terms wrapped in configurable pre/post tags.
fn apply_highlight(hits: Vec<Hit>, hl: &HighlightRequest, query: &QueryNode) -> Vec<Hit> {
    if hl.fields.is_empty() {
        return hits;
    }
    // Pre-compute query terms ONCE before iterating hits (Opt 3).
    let query_terms = extract_highlight_terms(query);
    // A `semantic` query has no lexical terms. Its highlights are the
    // best-scoring chunks of the `semantic_text` field, attached in
    // `knn_result_from_ranked` (#1947). This lexical pass correctly
    // leaves those hits alone.
    if query_terms.is_empty() {
        return hits;
    }

    let pre_default = hl.pre_tag.as_deref().unwrap_or("<em>");
    let post_default = hl.post_tag.as_deref().unwrap_or("</em>");
    let frag_size_default = hl.fragment_size.unwrap_or(150);
    // Cap at 3 fragments by default to bound per-hit work (Opt 3).
    let num_frags_default = hl.number_of_fragments.unwrap_or(3).min(3);

    hits.into_iter()
        .map(|mut hit| {
            // Skip entirely if the hit has no source (e.g. _source: false).
            if hit.source.is_null() {
                return hit;
            }

            let mut hl_map: std::collections::HashMap<String, Vec<String>> =
                std::collections::HashMap::new();
            for (field_name, field_opts) in &hl.fields {
                let pre = field_opts.pre_tag.as_deref().unwrap_or(pre_default);
                let post = field_opts.post_tag.as_deref().unwrap_or(post_default);
                let frag_size = field_opts.fragment_size.unwrap_or(frag_size_default);
                let num_frags_raw = field_opts.number_of_fragments.unwrap_or(num_frags_default);

                if let Some(field_val) = get_field_value(&hit.source, field_name) {
                    let text = match &field_val {
                        Value::String(s) => s.clone(),
                        other => other.to_string(),
                    };
                    // Lowercasing can change byte length (e.g. `İ` U+0130 is
                    // 2 bytes but lowercases to 3), so byte offsets found in
                    // `text_lower` are NOT valid indices into `text`. Build a
                    // per-character offset table alongside the lowercased text
                    // so matches can be translated back to original-text char
                    // boundaries (fixes the multibyte highlight SIGABRT).
                    let (text_lower, lower_map) = build_lower_offset_map(&text);
                    let has_any = query_terms
                        .iter()
                        .any(|t| next_term_match(&text_lower, t, 0).is_some());
                    if !has_any {
                        continue;
                    }
                    let fragments = if num_frags_raw == 0 {
                        // ES semantics: `number_of_fragments: 0` disables
                        // fragmenting entirely and emits the full text
                        // with every occurrence of every query term
                        // wrapped in the pre/post tags. Whitespace at
                        // the head/tail is preserved verbatim.
                        vec![highlight_full_text(
                            &text,
                            &text_lower,
                            &lower_map,
                            &query_terms,
                            pre,
                            post,
                        )]
                    } else {
                        let num_frags = num_frags_raw.min(3);
                        build_highlight_fragments(
                            &text,
                            &text_lower,
                            &lower_map,
                            &query_terms,
                            pre,
                            post,
                            frag_size,
                            num_frags,
                        )
                        // ES's unified highlighter trims leading/trailing
                        // whitespace from every emitted fragment.
                        .into_iter()
                        .map(|f| f.trim().to_string())
                        .collect()
                    };
                    if !fragments.is_empty() {
                        hl_map.insert(field_name.clone(), fragments);
                    }
                }
            }
            if !hl_map.is_empty() {
                hit.highlight = Some(hl_map);
            }
            hit
        })
        .collect()
}

/// Expand field-name patterns in a highlight request against the mapping
/// (#1281).
///
/// ES 8.13.4 (verified) expands a pattern to the mapped `text` and `keyword`
/// fields it matches, object sub-fields included (`obj.*` → `obj.inner`) and
/// numeric fields excluded. With `require_field_match` (default `true`) only
/// the fields the query targets survive: `match: {message}` + `"*"` highlights
/// `message` alone, while a field-less `query_string` highlights them all. An
/// explicit entry is kept as written and wins over a pattern that also covers
/// it; the pattern's options are copied to each field it expands to.
fn expand_highlight_field_patterns(
    hl: &HighlightRequest,
    schema: &Schema,
    query: &QueryNode,
) -> HighlightRequest {
    fn highlightable(fields: &[FieldConfig], prefix: &str, out: &mut Vec<String>) {
        for fc in fields {
            let path = if prefix.is_empty() {
                fc.name.clone()
            } else {
                format!("{prefix}.{}", fc.name)
            };
            match fc.field_type {
                FieldType::Text | FieldType::Keyword => out.push(path),
                // Object properties are fields of their own; a text field's
                // `fields` are multi-fields, which this expansion skips.
                FieldType::Object | FieldType::Nested => highlightable(&fc.fields, &path, out),
                _ => {}
            }
        }
    }
    fn glob(pattern: &str, name: &str) -> bool {
        let parts: Vec<&str> = pattern.split('*').collect();
        let (first, last) = (parts[0], parts[parts.len() - 1]);
        if !name.starts_with(first) || name.len() < first.len() + last.len() {
            return false;
        }
        let mut rest = &name[first.len()..];
        for mid in &parts[1..parts.len() - 1] {
            match rest.find(mid) {
                Some(at) => rest = &rest[at + mid.len()..],
                None => return false,
            }
        }
        rest.ends_with(last)
    }
    // Collects the field names (possibly patterns: a field-less
    // `query_string` reaches here as `match` on `"*"`) the query targets.
    // Returns `false` when the query targets every field outright.
    fn spec(f: &str, out: &mut Vec<String>) -> bool {
        out.push(f.split('^').next().unwrap_or(f).to_string());
        true
    }
    fn targeted(q: &QueryNode, out: &mut Vec<String>) -> bool {
        match q {
            QueryNode::Term { field, .. }
            | QueryNode::Terms { field, .. }
            | QueryNode::Range { field, .. }
            | QueryNode::Prefix { field, .. }
            | QueryNode::Wildcard { field, .. }
            | QueryNode::Match { field, .. }
            | QueryNode::MatchPhrase { field, .. }
            | QueryNode::MatchPhrasePrefix { field, .. }
            | QueryNode::Fuzzy { field, .. }
            | QueryNode::Regexp { field, .. } => {
                out.push(field.clone());
                true
            }
            QueryNode::MultiMatch { fields, .. } | QueryNode::SimpleQueryString { fields, .. } => {
                if fields.is_empty() {
                    return false;
                }
                fields.iter().all(|f| spec(f, out))
            }
            QueryNode::QueryString { default_field, .. } => match default_field {
                Some(f) => spec(f, out),
                None => false,
            },
            QueryNode::Bool {
                must,
                should,
                must_not,
                filter,
                ..
            } => must
                .iter()
                .chain(should)
                .chain(must_not)
                .chain(filter)
                .all(|c| targeted(c, out)),
            QueryNode::Constant { query, .. }
            | QueryNode::Boosted { query, .. }
            | QueryNode::Named { query, .. }
            | QueryNode::Nested { query, .. }
            | QueryNode::FunctionScore { query, .. } => targeted(query, out),
            QueryNode::DisMax { queries, .. } => queries.iter().all(|c| targeted(c, out)),
            _ => true,
        }
    }

    let mut candidates = Vec::new();
    highlightable(&schema.fields, "", &mut candidates);
    if hl.require_field_match != Some(false) {
        let mut named = Vec::new();
        if targeted(query, &mut named) {
            candidates.retain(|c| named.iter().any(|n| n == c || glob(n, c)));
        }
    }

    let mut out = hl.clone();
    out.fields.retain(|name, _| !name.contains('*'));
    for (pattern, opts) in hl.fields.iter().filter(|(name, _)| name.contains('*')) {
        for field in candidates.iter().filter(|c| glob(pattern, c)) {
            out.fields
                .entry(field.clone())
                .or_insert_with(|| opts.clone());
        }
    }
    out
}

/// Extract query terms for highlighting.
///
/// Returns lowercase tokens that should be highlighted.
fn extract_highlight_terms(query: &QueryNode) -> Vec<String> {
    let mut terms: Vec<String> = Vec::new();
    collect_highlight_terms(query, &mut terms);
    // Deduplicate.
    terms.sort();
    terms.dedup();
    terms
}

fn collect_highlight_terms(query: &QueryNode, out: &mut Vec<String>) {
    match query {
        QueryNode::Match { query, .. }
        | QueryNode::MatchPhrase { query, .. }
        | QueryNode::MultiMatch { query, .. } => {
            for tok in query.split_whitespace() {
                let tok = tok
                    .trim_matches(|c: char| !c.is_alphanumeric())
                    .to_lowercase();
                if !tok.is_empty() {
                    out.push(tok);
                }
            }
        }
        QueryNode::QueryString { query, .. } => {
            for tok in query.split_whitespace() {
                // `wild*` keeps its star so it highlights `wildcard` as a
                // prefix match; every other term matches whole words only.
                let prefix = tok
                    .trim_start_matches(|c: char| !c.is_alphanumeric())
                    .trim_end_matches(|c: char| !c.is_alphanumeric() && c != '*')
                    .ends_with('*');
                let tok = tok
                    .trim_matches(|c: char| !c.is_alphanumeric())
                    .to_lowercase();
                if !tok.is_empty() {
                    out.push(if prefix { format!("{tok}*") } else { tok });
                }
            }
        }
        QueryNode::Term { value, .. } => {
            if let Some(s) = value.as_str() {
                out.push(s.to_lowercase());
            }
        }
        QueryNode::Bool {
            must,
            should,
            filter,
            ..
        } => {
            for q in must.iter().chain(should.iter()).chain(filter.iter()) {
                collect_highlight_terms(q, out);
            }
        }
        QueryNode::Boosted { query, .. }
        | QueryNode::Constant { query, .. }
        | QueryNode::FunctionScore { query, .. } => {
            collect_highlight_terms(query, out);
        }
        _ => {}
    }
}

/// A character that continues a word, for highlight boundaries.
fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// The next occurrence of highlight `term` in `text_lower` at or after byte
/// `from` that stands as a whole word: the characters on either side are not
/// word characters. A term ending in `*` (a `query_string` prefix) needs a
/// boundary before it only and extends to the end of the word it starts.
///
/// Plain substring search (#1948) highlighted `or` inside `for`, `no` inside `not`
/// and `OR` inside `SECTOR`, and a phrase's short words then claimed the
/// fragment away from the phrase itself.
fn next_term_match(text_lower: &str, term: &str, from: usize) -> Option<(usize, usize)> {
    let (needle, prefix) = match term.strip_suffix('*') {
        Some(stem) => (stem, true),
        None => (term, false),
    };
    if needle.is_empty() || from > text_lower.len() {
        return None;
    }
    let mut start = from;
    while let Some(pos) = text_lower[start..].find(needle) {
        let abs = start + pos;
        let mut end = abs + needle.len();
        let before_ok = !text_lower[..abs]
            .chars()
            .next_back()
            .is_some_and(is_word_char);
        if prefix {
            end += text_lower[end..]
                .char_indices()
                .find(|&(_, c)| !is_word_char(c))
                .map(|(i, _)| i)
                .unwrap_or(text_lower.len() - end);
        }
        let after_ok = prefix || !text_lower[end..].chars().next().is_some_and(is_word_char);
        if before_ok && after_ok {
            return Some((abs, end));
        }
        // Step one character, not one byte, past this candidate.
        start = abs + text_lower[abs..].chars().next().map_or(1, char::len_utf8);
    }
    None
}

/// Wrap every whole-word occurrence of every term inside `text[win_start..
/// win_end]` with `pre`/`post`. Overlapping spans merge into one tag pair.
#[allow(clippy::too_many_arguments)]
fn tag_terms_in_window(
    text: &str,
    text_lower: &str,
    lower_map: &[(usize, usize, usize)],
    terms: &[String],
    win_start: usize,
    win_end: usize,
    pre: &str,
    post: &str,
) -> String {
    let orig_len = text.len();
    // Start the scan at the window, not at the top of a large document.
    let window_lower_start = lower_map
        .get(lower_map.partition_point(|e| e.1 < win_start))
        .map_or(text_lower.len(), |e| e.0);
    let mut spans: Vec<(usize, usize)> = Vec::new();
    for term in terms {
        let mut from = window_lower_start;
        while let Some((ls, le)) = next_term_match(text_lower, term, from) {
            let (oa, ob) = lower_span_to_orig(lower_map, orig_len, ls, le);
            if oa >= win_end {
                break;
            }
            if oa >= win_start && ob <= win_end && ob > oa {
                spans.push((oa, ob));
            }
            from = le.max(ls + 1);
        }
    }
    spans.sort_unstable();
    let mut out = String::with_capacity(win_end - win_start + spans.len() * 9);
    let mut cursor = win_start;
    let mut open: Option<(usize, usize)> = None;
    let flush = |out: &mut String, cursor: &mut usize, (s, e): (usize, usize)| {
        out.push_str(&text[*cursor..s]);
        out.push_str(pre);
        out.push_str(&text[s..e]);
        out.push_str(post);
        *cursor = e;
    };
    for (s, e) in spans {
        match open {
            Some((os, oe)) if s <= oe => open = Some((os, oe.max(e))),
            Some(span) => {
                flush(&mut out, &mut cursor, span);
                open = Some((s, e));
            }
            None => open = Some((s, e)),
        }
    }
    if let Some(span) = open {
        flush(&mut out, &mut cursor, span);
    }
    out.push_str(&text[cursor..win_end]);
    out
}

/// Build highlighted fragments for a single field value.
///
/// `text_lower` must be `text.to_lowercase()` (pre-computed by the caller to
/// avoid a redundant allocation per field per hit).
///
/// Scans `text_lower` for byte-level occurrences of each query term, then
/// extracts a window of `frag_size` bytes centred on each match.  Windows are
/// snapped to UTF-8 character boundaries so the output is always valid UTF-8.
/// Returns up to `num_frags` non-overlapping fragments with `pre`/`post` tags.
/// Build the lowercased form of `text` together with a per-original-character
/// offset table mapping lowercased byte offsets back to original byte spans.
///
/// Rust's `char::to_lowercase` can change both the byte length and the
/// character count of a codepoint (`İ` U+0130 → `i` + combining dot above,
/// 2 bytes → 3 bytes), so a byte offset located by searching the lowercased
/// text is **not** a valid index into the original text. Each entry is
/// `(lower_start, orig_start, orig_end)`: the byte offset in the lowercased
/// string where an original character's lowercased bytes begin, and that
/// original character's `[start, end)` byte span in `text`. The string is
/// lowercased character-by-character so it stays perfectly consistent with
/// the table (this can differ from `str::to_lowercase` only in locale edge
/// cases like Greek final sigma, which is irrelevant to substring matching).
fn build_lower_offset_map(text: &str) -> (String, Vec<(usize, usize, usize)>) {
    let mut lower = String::with_capacity(text.len());
    let mut entries: Vec<(usize, usize, usize)> = Vec::with_capacity(text.len());
    for (orig_start, ch) in text.char_indices() {
        let lower_start = lower.len();
        for lc in ch.to_lowercase() {
            lower.push(lc);
        }
        entries.push((lower_start, orig_start, orig_start + ch.len_utf8()));
    }
    (lower, entries)
}

/// Translate a byte span `[lo_start, lo_end)` located in the lowercased text
/// into the covering byte span in the original text, using the table from
/// [`build_lower_offset_map`]. The returned span fully contains every original
/// character that contributed any byte to the lowercased span, and both
/// endpoints are guaranteed to sit on original-text character boundaries — so
/// slicing `text[oa..ob]` can never panic on a multibyte codepoint.
fn lower_span_to_orig(
    entries: &[(usize, usize, usize)],
    orig_len: usize,
    lo_start: usize,
    lo_end: usize,
) -> (usize, usize) {
    if entries.is_empty() || lo_end <= lo_start {
        return (0, 0);
    }
    // First entry always has lower_start == 0, so partition_point >= 1 and the
    // saturating_sub(1) below never underflows.
    let si = entries
        .partition_point(|e| e.0 <= lo_start)
        .saturating_sub(1);
    let oa = entries[si].1;
    let ei = entries.partition_point(|e| e.0 < lo_end).saturating_sub(1);
    let ob = entries[ei].2.max(oa);
    (oa.min(orig_len), ob.min(orig_len))
}

/// Render the full source text with every match of every query term
/// wrapped in the pre/post tags. Used when the caller requests
/// `number_of_fragments: 0`, which disables fragmenting.
fn highlight_full_text(
    text: &str,
    text_lower: &str,
    lower_map: &[(usize, usize, usize)],
    terms: &[String],
    pre: &str,
    post: &str,
) -> String {
    let orig_len = text.len();
    let mut spans: Vec<(usize, usize)> = Vec::new();
    for term in terms {
        if term.is_empty() {
            continue;
        }
        let mut start = 0;
        while let Some((ls, le)) = next_term_match(text_lower, term, start) {
            // Translate the lowercased-text match offsets back to original
            // text char boundaries before recording the span.
            let (oa, ob) = lower_span_to_orig(lower_map, orig_len, ls, le);
            if ob > oa {
                spans.push((oa, ob));
            }
            start = le.max(ls + 1);
        }
    }
    spans.sort_by_key(|&(s, _)| s);
    // Merge overlaps — a term that spans into another term should not
    // produce double tags.
    let mut merged: Vec<(usize, usize)> = Vec::with_capacity(spans.len());
    for (s, e) in spans {
        if let Some(last) = merged.last_mut() {
            if s <= last.1 {
                last.1 = last.1.max(e);
                continue;
            }
        }
        merged.push((s, e));
    }
    let mut out = String::with_capacity(text.len() + merged.len() * (pre.len() + post.len()));
    let mut cursor = 0;
    for (s, e) in merged {
        if cursor < s {
            out.push_str(&text[cursor..s]);
        }
        out.push_str(pre);
        out.push_str(&text[s..e]);
        out.push_str(post);
        cursor = e;
    }
    if cursor < text.len() {
        out.push_str(&text[cursor..]);
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn build_highlight_fragments(
    text: &str,
    text_lower: &str,
    lower_map: &[(usize, usize, usize)],
    terms: &[String],
    pre: &str,
    post: &str,
    frag_size: usize,
    num_frags: usize,
) -> Vec<String> {
    let orig_len = text.len();
    // Collect all match byte-offsets (start, end) across all terms, translated
    // from the lowercased text back into ORIGINAL-text char boundaries. All the
    // window math below operates on `text` (the original), so mixing in
    // lowercased offsets would slice through multibyte codepoints and panic.
    let mut match_positions: Vec<(usize, usize)> = Vec::new();
    // Parallel record of each candidate in LOWERCASED space, so scoring can
    // look at surrounding text without needing an orig->lower reverse map.
    let mut lower_positions: Vec<(usize, usize)> = Vec::new();
    for term in terms {
        let mut start = 0;
        // Budget the scan PER TERM, not across all terms. A shared budget is
        // spent entirely by whichever term happens to be scanned first, and
        // `terms` arrives sorted alphabetically — so for `function
        // human_time_diff`, the hundreds of early occurrences of "function"
        // filled the quota and "human_time_diff" was never searched for at
        // all. Two independent usability runs hit this: both asked for a
        // phrase deep in a large file, both got fragments from the top of the
        // file highlighting only the common word, and both abandoned
        // highlighting and downloaded whole documents instead.
        let mut per_term = 0usize;
        let per_term_cap = (num_frags * 4).max(4);
        while let Some((ls, le)) = next_term_match(text_lower, term, start) {
            let (oa, ob) = lower_span_to_orig(lower_map, orig_len, ls, le);
            if ob > oa {
                match_positions.push((oa, ob));
                lower_positions.push((ls, le));
            }
            start = le.max(ls + 1);
            per_term += 1;
            if per_term >= per_term_cap {
                break; // enough candidates FOR THIS TERM; keep scanning others
            }
        }
    }

    if match_positions.is_empty() {
        return Vec::new();
    }

    // Rank candidates by how many DISTINCT query terms fall inside the window
    // a fragment would cover, richest first, and only then by position.
    //
    // Sorting purely by position returns whatever appears earliest, which for
    // a multi-term query is almost always the commonest word — the top of the
    // file rather than the place the query is actually about. Counting
    // distinct terms makes the spot where the terms co-occur win, which is the
    // phrase the caller searched for.
    let half_window = (frag_size / 2).max(1);
    let lower_len = text_lower.len();
    let mut scored: Vec<(usize, (usize, usize))> = match_positions
        .iter()
        .zip(lower_positions.iter())
        .map(|(&orig, &(ls, le))| {
            let lo = ls.saturating_sub(half_window).min(lower_len);
            let hi = (le + half_window).min(lower_len);
            // Snap to char boundaries: text_lower is UTF-8 and a naive slice
            // could land mid-codepoint.
            let lo = (0..=lo)
                .rev()
                .find(|&i| text_lower.is_char_boundary(i))
                .unwrap_or(0);
            let hi = (hi..=lower_len)
                .find(|&i| text_lower.is_char_boundary(i))
                .unwrap_or(lower_len);
            let window = &text_lower[lo..hi];
            let distinct = terms
                .iter()
                .filter(|t| next_term_match(window, t, 0).is_some())
                .count();
            (distinct, orig)
        })
        .collect();
    scored.sort_by(|a, b| b.0.cmp(&a.0).then(a.1 .0.cmp(&b.1 .0)));
    let match_positions: Vec<(usize, usize)> = scored.into_iter().map(|(_, p)| p).collect();

    // (Ordering is decided by the distinct-term ranking above; the old
    // earliest-first sort would undo it.)

    let text_bytes = text.as_bytes();
    let total_bytes = text_bytes.len();

    /// Snap `pos` forward to the next UTF-8 character boundary.
    fn snap_start(bytes: &[u8], pos: usize) -> usize {
        let mut p = pos.min(bytes.len());
        // Continuation bytes (10xxxxxx) are not char starts; advance past them.
        while p < bytes.len() && bytes[p] & 0xC0 == 0x80 {
            p += 1;
        }
        p
    }

    /// Snap `pos` backward to a valid UTF-8 char boundary (not mid-char).
    fn snap_end(bytes: &[u8], pos: usize) -> usize {
        let mut p = pos.min(bytes.len());
        // Step back while we're pointing at a continuation byte.
        while p > 0 && p < bytes.len() && bytes[p] & 0xC0 == 0x80 {
            p -= 1;
        }
        p
    }

    let mut fragments: Vec<String> = Vec::new();
    let mut last_win_end: usize = 0;

    for (byte_start, _) in &match_positions {
        if fragments.len() >= num_frags {
            break;
        }

        // Centre a byte window around the match.
        let half = frag_size / 2;
        let win_start_raw = byte_start.saturating_sub(half);
        let win_end_raw = (win_start_raw + frag_size).min(total_bytes);
        let win_start_raw = win_end_raw.saturating_sub(frag_size);

        // Snap to valid UTF-8 boundaries.
        let win_start = snap_start(text_bytes, win_start_raw);
        let win_end = snap_end(text_bytes, win_end_raw);
        let win_end = win_end.max(win_start);

        // Skip if this window overlaps with the previous fragment (avoid duplicates).
        if win_start < last_win_end {
            continue;
        }
        last_win_end = win_end;

        // Build the fragment: every query term inside the window is tagged,
        // not only the match the window is centred on, so a phrase reads as
        // its words tagged in place (original casing kept).
        let mut frag = String::with_capacity(frag_size + pre.len() + post.len() + 6);
        if win_start > 0 {
            frag.push_str("...");
        }
        frag.push_str(&tag_terms_in_window(
            text, text_lower, lower_map, terms, win_start, win_end, pre, post,
        ));
        if win_end < total_bytes {
            frag.push_str("...");
        }
        fragments.push(frag);
    }

    fragments
}

/// #2191: the embedding backend answered with vectors whose width contradicts
/// the `semantic_text` field's mapped `dimensions`. The backend's width is
/// fixed, so a retry cannot succeed: report it as a mapping error (HTTP 400,
/// `mapper_parsing_exception` on `_bulk`) rather than a retryable backend 500.
fn semantic_width_mismatch_error(detail: &str) -> xerj_common::XerjError {
    xerj_common::XerjError::invalid_mapping(format!(
        "{detail}; the embedding backend's vector width is fixed, so retrying cannot \
         succeed: set the semantic_text field's `dimensions` to the backend's width, \
         or point the field at a backend that returns the mapped width"
    ))
}

/// Build the effective [`xerj_ai::Embedder`] from `Config.embedding`.
///
/// Backend selection follows `embedding.mode`:
///   * `"proxy"` — external OpenAI-compatible endpoint (requires
///     `default_endpoint`).
///   * `"neural"` — the built-in BERT embedder (requires the `neural`
///     cargo feature; falls back to lexical with a warning otherwise).
///   * `"onnx-experimental"` — an explicit FP32 ONNX model and tokenizer
///     loaded through ONNX Runtime (requires the `onnx-experimental` feature).
///   * `"lexical"` — the built-in feature-hash embedder.
///   * `"auto"` (default / unknown) — proxy when `default_endpoint` is set,
///     else lexical. Preserves the historical behavior exactly.
///
/// Proxy initialization and an unavailable Candle feature degrade to the
/// lexical fallback with a warning. ONNX is deliberately fail-closed: missing
/// assets, a feature-disabled build, or an incompatible model returns an
/// actionable configuration error instead of silently changing vector
/// identity. A `semantic` query with no active backend against a plain vector
/// field still returns a helpful 400.
/// Map an embedder failure to the correct ES class (item 9). An embedding
/// backend outage or misconfiguration is a server-side (5xx) failure, never a
/// 400 `invalid_query`: downgrading it hid proxy failures behind a client
/// error and drove clients to retry a broken backend. Produces an
/// `EmbeddingError` (500, `circuit_breaking_exception`) with `ctx` prepended.
/// Takes `impl Display` because the `Embedder` surfaces `anyhow::Error` (the
/// classification of transient-vs-permanent already happened inside the proxy).
fn is_embedding_admission_rejection(_e: &anyhow::Error) -> bool {
    #[cfg(feature = "onnx-experimental")]
    if _e
        .downcast_ref::<xerj_ai::embedder::OnnxAdmissionError>()
        .is_some()
    {
        return true;
    }
    false
}

fn embed_backend_error(e: anyhow::Error, ctx: &str) -> xerj_common::XerjError {
    if is_embedding_admission_rejection(&e) {
        return xerj_common::XerjError::resource_exhausted(format!("{ctx}: {e}"));
    }
    xerj_common::XerjError::embedding(format!("{ctx}: {e}"))
}

const EMBEDDING_IDENTITY_FILE: &str = "embedding_identity.json";

/// Which embedder produced this index's vectors, as its resolved EXECUTION
/// identity — not the `embedding.mode` string that was requested.
///
/// A SEPARATE file from [`EMBEDDING_IDENTITY_FILE`] on purpose. Widening that
/// one breaks downgrade: an older binary parses it, sees a record whose ONNX
/// fields are empty, and concludes the index contains ONNX vectors — so a
/// rollback would leave every index the new binary had touched red and
/// unopenable. This repo has already made that call once; the CHANGELOG records
/// a sidecar being chosen elsewhere for exactly this reason. An older binary
/// simply never opens this file.
///
/// Keyed on `identity_sha256` from [`embedding_execution_identity`] because the
/// mode string is not the embedder. `auto` with no endpoint, `proxy` with no
/// endpoint, `neural` in a build without the `neural` feature, and any
/// unrecognised value all resolve to the SAME lexical embedder, so keying on
/// the string refuses an index over a change that cannot alter a single vector.
/// The resolved identity also moves when the mode string does not — a different
/// proxy endpoint or neural model — which is the half a mode check cannot see.
const EMBEDDING_EXECUTION_FILE: &str = "embedding_execution.json";

/// On-disk record version for `embedding_execution.json`. Distinct from the
/// wire `EmbeddingExecutionIdentity.version` (the API contract, pinned == 1 by
/// the autoindex client). Bumped to 2 by #533: the proxy identity_sha256 now
/// folds in the endpoint, so a v1 record's hash was produced by a different
/// algorithm — `validate_embedding_execution` treats a version delta as
/// "unknown" (grandfather + re-record), never a mismatch, so upgrading does not
/// brick a populated proxy index; a later change under v2 is still detected.
///
/// Bumped to 3 by #487 for the same reason on the other backend: the neural
/// identity_sha256 is now the digest of the model assets rather than of the
/// configured model NAME, so every v2 record written by a neural node holds a
/// hash from the superseded algorithm. Without the bump, the first restart
/// after upgrading would read `persisted.identity_sha256 != current` over a
/// populated index and refuse to open it — bricking exactly the indices this
/// change exists to make re-indexable.
const PERSISTED_EMBEDDING_EXECUTION_VERSION: u32 = 3;

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
struct PersistedEmbeddingExecution {
    version: u32,
    backend: String,
    identity_sha256: String,
}

#[derive(Debug, PartialEq, Serialize, Deserialize)]
struct PersistedEmbeddingIdentity {
    version: u32,
    backend: String,
    model_sha256: String,
    tokenizer_sha256: String,
    dimensions: usize,
    pooling: String,
    max_tokens: usize,
}

fn schema_has_embeddings(fields: &[FieldConfig]) -> bool {
    fields
        .iter()
        .any(|field| field.embedding.is_some() || schema_has_embeddings(&field.fields))
}

fn schema_needs_embedder(fields: &[FieldConfig]) -> bool {
    fields.iter().any(|field| {
        field.embedding.is_some()
            || matches!(field.field_type, FieldType::Vector | FieldType::Chunk)
            || schema_needs_embedder(&field.fields)
    })
}

fn validate_onnx_dimensions(fields: &[FieldConfig]) -> Result<()> {
    for field in fields {
        if field.embedding.is_some() {
            let dims = field
                .options
                .dimensions
                .unwrap_or(xerj_ai::local::DEFAULT_DIMS);
            if dims != 384 {
                return Err(EngineError::Common(xerj_common::XerjError::embedding(
                    format!(
                        "semantic field [{}] declares {dims} dimensions, but the experimental \
                         MiniLM ONNX backend returns exactly 384. Change the mapping to 384 or \
                         use an embedding backend matching the declared dimensions.",
                        field.name
                    ),
                )));
            }
        }
        validate_onnx_dimensions(&field.fields)?;
    }
    Ok(())
}

#[cfg(feature = "onnx-experimental")]
fn configured_onnx_assets(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> Result<xerj_common::config::EmbeddingAssetSnapshot> {
    use sha2::{Digest, Sha256};

    cfg.runtime_onnx_assets
        .get_or_init(|| {
            let model = Path::new(&cfg.onnx_model_path)
                .canonicalize()
                .map_err(|e| format!("cannot resolve embedding model asset: {e}"))?;
            let tokenizer = Path::new(&cfg.onnx_tokenizer_path)
                .canonicalize()
                .map_err(|e| format!("cannot resolve embedding tokenizer asset: {e}"))?;
            let model_bytes: Arc<[u8]> = std::fs::read(&model)
                .map(Into::into)
                .map_err(|e| format!("cannot read embedding model asset: {e}"))?;
            let tokenizer_bytes: Arc<[u8]> = std::fs::read(&tokenizer)
                .map(Into::into)
                .map_err(|e| format!("cannot read embedding tokenizer asset: {e}"))?;
            Ok(xerj_common::config::EmbeddingAssetSnapshot {
                model_sha256: format!("{:x}", Sha256::digest(&model_bytes)),
                tokenizer_sha256: format!("{:x}", Sha256::digest(&tokenizer_bytes)),
                model_bytes,
                tokenizer_bytes,
            })
        })
        .clone()
        .map_err(|reason| EngineError::Common(xerj_common::XerjError::embedding(reason)))
}

fn configured_onnx_identity(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> Result<Option<PersistedEmbeddingIdentity>> {
    if !cfg.mode.trim().eq_ignore_ascii_case("onnx-experimental") {
        return Ok(None);
    }
    #[cfg(not(feature = "onnx-experimental"))]
    return Err(EngineError::Common(xerj_common::XerjError::embedding(
        "onnx-experimental was requested but this engine build does not include the \
         onnx-experimental feature; no embedding identity marker was written",
    )));
    #[cfg(feature = "onnx-experimental")]
    {
        let assets = configured_onnx_assets(cfg)?;
        Ok(Some(PersistedEmbeddingIdentity {
            version: 1,
            backend: "onnx-experimental".into(),
            model_sha256: assets.model_sha256,
            tokenizer_sha256: assets.tokenizer_sha256,
            dimensions: 384,
            pooling: "attention-mask-mean+l2-normalize".into(),
            max_tokens: 512,
        }))
    }
}

/// The `NeuralConfig` this server's embedding configuration resolves to.
///
/// Deliberately shared with `make_neural_embedder`: an identity describing a
/// different model than the one that actually loads would be worse than no
/// identity at all.
#[cfg(feature = "neural")]
fn configured_neural_config(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> xerj_ai::neural::NeuralConfig {
    let model_id = if cfg.neural_model.trim().is_empty() {
        xerj_ai::neural::DEFAULT_MODEL_ID.to_string()
    } else {
        cfg.neural_model.clone()
    };
    xerj_ai::neural::NeuralConfig {
        model_id,
        cache_dir: (!cfg.model_cache_dir.is_empty()).then(|| cfg.model_cache_dir.clone().into()),
        local_dir: (!cfg.local_model_dir.is_empty()).then(|| cfg.local_model_dir.clone().into()),
        // The mirror URL is `HF_ENDPOINT`, read inside the hub client. There
        // is no config field for it; tests inject one on `NeuralConfig` directly.
        hub_endpoint: None,
    }
}

/// Execution identity for the built-in Candle backend.
///
/// #487/#367: this arm used to hash the configured model NAME and report
/// `resumable: false` unconditionally. Two consequences, both measured on
/// rc.71 before this change:
///
///   * a brand-new node and a long-running one emit the *identical*
///     `identity_sha256` (`6e51e5ce3e46…` on any host), so the identity could
///     not detect a real model swap — which is why it was correct not to trust
///     it; and
///   * every one of the five `resumable` gates in `xerj-autoindex` fired on a
///     neural node, so `xerj autoindex` was one-shot: the graph path completed
///     generation 1 and then refused the identical re-run over an *unchanged*
///     corpus, and the `--no-graph` path refused even the first run.
///
/// Lucene does not refuse to reuse an artifact it cannot name; it names it from
/// its own bytes and fails only on a proven mismatch —
/// `ReplicaNode.fileIsIdentical`
/// (`lucene/replicator/src/java/org/apache/lucene/replicator/nrt/ReplicaNode.java:855`)
/// compares length + header id + checksum precisely to catch a reused *name*
/// whose content changed. APPROACH ONLY; the digest here is our own, and the
/// ONNX arm 25 lines above already did the same thing. Candle's assets were
/// already resolved to concrete paths in `xerj-ai/src/neural.rs`; nothing was
/// missing but the digest.
///
/// Still fails closed — assets that cannot be hashed stay non-resumable — but
/// the reason then names the file instead of blaming a configuration change
/// that never happened.
#[cfg(feature = "neural")]
fn configured_neural_identity(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> (String, bool, Option<String>, Option<usize>) {
    let neural = configured_neural_config(cfg);
    match xerj_ai::neural::asset_identity(&neural) {
        Ok(identity) => (
            format!(
                "neural.v1;model={};tokenizer={};config={};dimensions={};pooling={};max_tokens={}",
                identity.model_sha256,
                identity.tokenizer_sha256,
                identity.config_sha256,
                identity.dimensions,
                xerj_ai::neural::POOLING,
                xerj_ai::neural::MAX_TOKENS
            ),
            true,
            None,
            Some(identity.dimensions),
        ),
        Err(e) => {
            // `e.detail` names resolved paths and the configured model id.
            // `EmbeddingExecutionIdentity` is documented as carrying neither
            // across the API boundary, and `non_resumable_reason` is the one
            // field of it that is not a digest — so the detail goes to this
            // server's log and only the bare asset name goes on the wire.
            warn!(
                asset = e.asset,
                detail = %e.detail,
                "neural embedding assets could not be content-addressed; semantic resume is \
                 disabled for this node"
            );
            (
                format!("neural-unresolved.v1;configured-model={}", neural.model_id),
                false,
                Some(format!(
                    "the neural model assets could not be content-addressed: cannot read {}",
                    e.asset
                )),
                None,
            )
        }
    }
}

#[cfg(not(feature = "neural"))]
fn configured_neural_identity(
    _cfg: &xerj_common::config::EmbeddingConfig,
) -> (String, bool, Option<String>, Option<usize>) {
    // `backend` below resolves a requested "neural" to "lexical" in slim
    // builds, so this arm is unreachable there; it exists so the match needs
    // no `cfg` of its own.
    unreachable!("the neural backend is not compiled into this build")
}

/// Probe text sent once per process to learn a proxy model's vector width.
///
/// Kept distinct from document text so a resume test can tell the probe apart
/// from a re-embedded document.
const PROXY_WIDTH_PROBE_TEXT: &str = "xerj-proxy-identity-probe";

/// On-disk copy of the last confirmed proxy width, under the data directory.
///
/// A restart whose endpoint is briefly down reuses this instead of reporting
/// a different identity and refusing to resume. It is not an index directory
/// (`Engine::new` only opens subdirectories that contain a `wal`).
const PROXY_WIDTH_CACHE_FILE: &str = "proxy-embedding-probe.json";

fn proxy_width_unconfirmed_reason() -> String {
    "the proxy embedding endpoint has not confirmed a vector width, so semantic \
     resume cannot reuse already-embedded documents. The embedder identity is the \
     backend, the configured model, the endpoint, and the vector width; without a \
     confirmed width a rerun cannot tell this model from a different one. Make the \
     embedding endpoint reachable and rerun — documents already indexed are kept and \
     are not re-embedded once the same width is confirmed. Rebuild with a new \
     --state-dir and a new --prefix only to discard this corpus and start over"
        .to_string()
}

fn confirmed_proxy_width(cfg: &xerj_common::config::EmbeddingConfig) -> Option<usize> {
    let guard = cfg
        .runtime_proxy_width
        .read()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    guard.as_ref().and_then(|confirmed| {
        (confirmed.endpoint == cfg.default_endpoint
            && confirmed.model == cfg.default_model
            && confirmed.dimensions > 0)
            .then_some(confirmed.dimensions)
    })
}

fn remember_proxy_width(cfg: &xerj_common::config::EmbeddingConfig, dimensions: usize) {
    let mut guard = cfg
        .runtime_proxy_width
        .write()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    *guard = Some(xerj_common::config::ConfirmedProxyWidth {
        endpoint: cfg.default_endpoint.clone(),
        model: cfg.default_model.clone(),
        dimensions,
    });
}

fn proxy_mode_selected(cfg: &xerj_common::config::EmbeddingConfig) -> bool {
    let requested = cfg.mode.trim().to_ascii_lowercase();
    match requested.as_str() {
        "proxy" => !cfg.default_endpoint.is_empty(),
        "neural" | "lexical" | "onnx-experimental" => false,
        _ => !cfg.default_endpoint.is_empty(),
    }
}

#[derive(serde::Serialize, serde::Deserialize)]
struct ProxyWidthCacheFile {
    endpoint: String,
    model: String,
    dimensions: usize,
}

fn load_proxy_width_cache(
    data_dir: &Path,
    cfg: &xerj_common::config::EmbeddingConfig,
) -> Option<usize> {
    let bytes = std::fs::read(data_dir.join(PROXY_WIDTH_CACHE_FILE)).ok()?;
    let cached: ProxyWidthCacheFile = serde_json::from_slice(&bytes).ok()?;
    (cached.endpoint == cfg.default_endpoint
        && cached.model == cfg.default_model
        && cached.dimensions > 0)
        .then_some(cached.dimensions)
}

fn store_proxy_width_cache(
    data_dir: &Path,
    cfg: &xerj_common::config::EmbeddingConfig,
    dimensions: usize,
) {
    if let Err(error) = std::fs::create_dir_all(data_dir) {
        warn!(
            error = %error,
            "could not create the data directory for the proxy width cache"
        );
        return;
    }
    let bytes = match serde_json::to_vec(&ProxyWidthCacheFile {
        endpoint: cfg.default_endpoint.clone(),
        model: cfg.default_model.clone(),
        dimensions,
    }) {
        Ok(bytes) => bytes,
        Err(error) => {
            warn!(error = %error, "could not encode the proxy width cache");
            return;
        }
    };
    if let Err(error) = write_file_atomic(&data_dir.join(PROXY_WIDTH_CACHE_FILE), &bytes) {
        warn!(error = %error, "could not store the confirmed proxy vector width");
    }
}

fn probe_proxy_width(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> std::result::Result<usize, String> {
    let proxy =
        xerj_ai::embed::EmbeddingProxy::new(proxy_config(cfg)).map_err(|e| e.to_string())?;
    let probed = proxy.embed(PROXY_WIDTH_PROBE_TEXT.to_string());
    let vector = if let Ok(handle) = tokio::runtime::Handle::try_current() {
        tokio::task::block_in_place(|| handle.block_on(probed))
    } else {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|e| e.to_string())?;
        runtime.block_on(probed)
    }
    .map_err(|e| e.to_string())?;
    if vector.is_empty() {
        return Err("embedding endpoint returned an empty vector".to_string());
    }
    Ok(vector.len())
}

/// Confirm the proxy model's vector width once per process (#2306).
///
/// A successful probe is remembered in memory and under `data_dir`, and the
/// identity that follows reports `resumable: true` with that width. A failed
/// probe reuses the on-disk width for the same endpoint and model so a restart
/// while the endpoint is down does not look like a different embedder. With
/// neither, the identity stays non-resumable and names what to do.
///
/// No-op unless this config actually resolves to the proxy backend. Called from
/// the identity request, not from index open.
pub(crate) fn confirm_proxy_embedding_width(
    cfg: &xerj_common::config::EmbeddingConfig,
    data_dir: &Path,
) {
    if !proxy_mode_selected(cfg) || confirmed_proxy_width(cfg).is_some() {
        return;
    }
    // An endpoint this process cannot even construct a client for is the
    // identity function's error (explicit proxy) or its lexical fallback
    // (auto). Probing it would only repeat that failure.
    if xerj_ai::embed::EmbeddingProxy::new(proxy_config(cfg)).is_err() {
        return;
    }
    match probe_proxy_width(cfg) {
        Ok(dimensions) => {
            remember_proxy_width(cfg, dimensions);
            store_proxy_width_cache(data_dir, cfg, dimensions);
        }
        Err(error) => {
            if let Some(dimensions) = load_proxy_width_cache(data_dir, cfg) {
                warn!(
                    error = %error,
                    dimensions,
                    "proxy width probe failed; reusing the last confirmed width for this \
                     endpoint and model"
                );
                remember_proxy_width(cfg, dimensions);
            } else {
                warn!(
                    error = %error,
                    "proxy embedding width could not be confirmed; semantic autoindex cannot \
                     resume until the endpoint answers a probe"
                );
            }
        }
    }
}

pub(crate) fn embedding_execution_identity(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> Result<crate::engine::EmbeddingExecutionIdentity> {
    use sha2::{Digest, Sha256};

    const CONTRACT: &str = "semantic_text-derived-vector.v1";
    let requested = cfg.mode.trim().to_ascii_lowercase();
    // Explicit mode=proxy with an unusable endpoint is a configuration error,
    // not a lexical degrade (#1189): the identity must report what the
    // embedder would actually run, and after the make_embedder fix that
    // configuration no longer starts. Auto (any non-pinned mode) keeps the
    // historical fallback to lexical.
    let mut backend = match requested.as_str() {
        "neural" => {
            #[cfg(feature = "neural")]
            {
                "neural"
            }
            #[cfg(not(feature = "neural"))]
            {
                "lexical"
            }
        }
        "onnx-experimental" => "onnx-experimental",
        "lexical" => "lexical",
        "proxy" if cfg.default_endpoint.is_empty() => {
            return Err(EngineError::Common(xerj_common::XerjError::embedding(
                "embedding.mode=proxy requires embedding.default_endpoint to be set; \
                 remove mode=proxy (use auto) if a lexical fallback is wanted",
            )));
        }
        "proxy" => "proxy",
        _ if cfg.default_endpoint.is_empty() => "lexical",
        _ => "proxy",
    };
    if backend == "proxy" {
        if let Err(e) = xerj_ai::embed::EmbeddingProxy::new(proxy_config(cfg)) {
            if requested == "proxy" {
                return Err(EngineError::Common(xerj_common::XerjError::embedding(
                    format!("embedding.mode=proxy failed to initialize: {e}"),
                )));
            }
            backend = "lexical";
        }
    }
    // Only report a width for the backends whose width this server actually
    // pins. `neural` reads it from the resolved model's `config.json`
    // (`hidden_size`, the same number `NeuralEmbedder::dims` reports). An
    // unconfirmed `proxy` omits the width rather than reporting 384; once a
    // probe (or the on-disk fallback) has confirmed one, that width is
    // reported (#2306). It is not part of the digest.
    let (material, resumable, reason, dimensions) = match backend {
        "lexical" => (
            format!(
                "lexical-feature-hash.v1;dimensions={};algorithm-probe={}",
                xerj_ai::local::DEFAULT_DIMS,
                lexical_algorithm_probe_sha256()
            ),
            true,
            None,
            Some(xerj_ai::local::DEFAULT_DIMS),
        ),
        "onnx-experimental" => {
            let identity = configured_onnx_identity(cfg)?.ok_or_else(|| {
                EngineError::Common(xerj_common::XerjError::embedding(
                    "ONNX embedding identity is unavailable",
                ))
            })?;
            let onnx_dimensions = identity.dimensions;
            (
                format!(
                    "onnx-experimental.v1;model={};tokenizer={};dimensions={};pooling={};max_tokens={}",
                    identity.model_sha256,
                    identity.tokenizer_sha256,
                    identity.dimensions,
                    identity.pooling,
                    identity.max_tokens
                ),
                true,
                None,
                Some(onnx_dimensions),
            )
        }
        "neural" => configured_neural_identity(cfg),
        "proxy" => {
            // #533: the endpoint is part of the embedder identity — the same
            // model name behind a different `default_endpoint` is a DIFFERENT
            // embedder, and omitting it let the endpoint change silently past the
            // #434 guard (a missed detection). `api_key` is deliberately left out
            // (a rotated key over the same endpoint+model is the same embedder).
            //
            // #2306: the digest stays that model+endpoint string. Folding the
            // probed width into it would change the hash the moment a probe
            // succeeds and refuse to open every index recorded before the probe
            // (or recorded while the endpoint was down). The width travels in
            // `dimensions` instead, and autoindex compares it on resume. A
            // provider that swaps weights without changing the name, the
            // endpoint, or the width is not detectable from here.
            // #2355 completes a `/v1` base (and a bare host) to an embeddings
            // URL on the HTTP request only. The digest stays this configured
            // string: folding the resolved URL in would move identity_sha256
            // for every proxy index recorded before that completion and refuse
            // to open it. `/v1` and `/v1/embeddings` therefore remain distinct
            // identities even when they POST to the same path.
            let material = format!(
                "proxy-unpinned.v1;configured-model={};endpoint={}",
                cfg.default_model, cfg.default_endpoint
            );
            match confirmed_proxy_width(cfg) {
                Some(width) => (material, true, None, Some(width)),
                None => (
                    material,
                    false,
                    Some(proxy_width_unconfirmed_reason()),
                    None,
                ),
            }
        }
        _ => unreachable!(),
    };
    let canonical = format!("{CONTRACT};backend={backend};{material}");
    // The probe is a rate sample, not an input to the digest above. Folding
    // it in would make every boot look like a different embedder.
    let probe = (backend == "neural")
        .then(|| cfg.neural_ingest_probe.get().copied().flatten())
        .flatten()
        .filter(|probe| probe.bytes > 0 && probe.passages > 0 && probe.millis > 0);
    Ok(crate::engine::EmbeddingExecutionIdentity {
        // This is the WIRE/API version the autoindex client pins on
        // (esclient.rs requires == 1); it is NOT the on-disk migration marker.
        // #533 folds the proxy endpoint into `material` (moving identity_sha256)
        // without changing this contract; the on-disk record version is bumped
        // separately (PERSISTED_EMBEDDING_EXECUTION_VERSION) so a populated proxy
        // index is grandfathered, not bricked, on upgrade.
        version: 1,
        backend: backend.to_string(),
        identity_sha256: format!("{:x}", Sha256::digest(canonical.as_bytes())),
        dimensions,
        semantic_contract: CONTRACT.to_string(),
        resumable,
        non_resumable_reason: reason,
        ingest_probe_bytes: probe.map(|probe| probe.bytes),
        ingest_probe_passages: probe.map(|probe| probe.passages),
        ingest_probe_millis: probe.map(|probe| probe.millis),
    })
}

/// Fingerprint representative output from the zero-config embedder.
///
/// The lexical backend has no model asset to hash, so its identity must be
/// bound to executable behaviour instead. Encoding each `f32` as little-endian
/// bytes makes the material stable across host endianness. If tokenisation,
/// feature weights, hashing, normalisation, or the default width changes, this
/// digest (and therefore the resume identity) changes automatically.
fn lexical_algorithm_probe_sha256() -> String {
    use sha2::{Digest, Sha256};

    const PROBES: &[&str] = &[
        "",
        "The quick brown fox jumps over the lazy dog.",
        "Revenue grew 12.5% in Q4 2025; naïve café 東京.",
        "snake_case/path-like:value + punctuation!",
    ];
    let mut digest = Sha256::new();
    for probe in PROBES {
        digest.update((probe.len() as u64).to_le_bytes());
        digest.update(probe.as_bytes());
        for value in xerj_ai::local::local_embed(probe, xerj_ai::local::DEFAULT_DIMS) {
            digest.update(value.to_le_bytes());
        }
    }
    format!("{:x}", digest.finalize())
}

/// Build the proxy client config from engine embedding settings. Public so
/// `xerj-server` runs the same #1189 boot validation the engine runs at
/// index-create, instead of duplicating the mapping.
pub fn proxy_config(
    cfg: &xerj_common::config::EmbeddingConfig,
) -> xerj_ai::embed::EmbeddingProxyConfig {
    xerj_ai::embed::EmbeddingProxyConfig {
        endpoint: cfg.default_endpoint.clone(),
        api_key: std::env::var("XERJ_EMBEDDING_API_KEY").ok(),
        model: cfg.default_model.clone(),
        timeout_ms: cfg.timeout_ms,
        max_concurrent: 4,
        max_retries: 3,
        batch_size: cfg.batch_size.max(1),
    }
}

#[cfg(test)]
mod proxy_config_tests {
    /// `embedding.timeout_ms` reached the HTTP client as `timeout_ms / 1000`
    /// whole seconds: 1500 ms became a 1 s timeout and 900 ms became 0 s, so
    /// a provider answering in 1.2 s failed every request under a 1.5 s
    /// setting (measured on rc.89 against a mock endpoint).
    #[test]
    fn embedding_timeout_reaches_the_proxy_in_milliseconds() {
        for ms in [900, 1500, 5000] {
            let cfg = xerj_common::config::EmbeddingConfig {
                timeout_ms: ms,
                ..Default::default()
            };
            assert_eq!(super::proxy_config(&cfg).timeout_ms, ms);
        }
    }
}

/// Fail closed rather than mixing vectors produced by different model,
/// tokenizer, pooling, or backend configurations after a restart/resume.
fn validate_embedding_identity(
    index_dir: &Path,
    schema: &Schema,
    cfg: &xerj_common::config::EmbeddingConfig,
    new_index: bool,
    has_documents: bool,
) -> Result<()> {
    if !schema_has_embeddings(&schema.fields) {
        return Ok(());
    }
    let marker_path = index_dir.join(EMBEDDING_IDENTITY_FILE);
    let configured = configured_onnx_identity(cfg)?;
    if configured.is_some() {
        validate_onnx_dimensions(&schema.fields)?;
    }
    if marker_path.exists() {
        let persisted: PersistedEmbeddingIdentity =
            serde_json::from_slice(&std::fs::read(&marker_path)?).map_err(|e| {
                EngineError::Common(xerj_common::XerjError::embedding(format!(
                    "cannot read {}: {e}; restore the marker or reindex this index",
                    marker_path.display()
                )))
            })?;
        return match configured {
            Some(current) if current == persisted => Ok(()),
            Some(current) => Err(EngineError::Common(xerj_common::XerjError::embedding(
                format!(
                    "embedding identity mismatch for index {}: persisted backend={} \
                     model={} tokenizer={}, configured backend={} model={} tokenizer={}. \
                     Refusing to mix incompatible vector spaces. Restore the original assets \
                     or rebuild with a new autoindex state directory, new index prefix, and new \
                     brain when graph detection is enabled (or --no-graph); validate before \
                     switching readers and explicitly clean the shared catalog and old target.",
                    index_dir.display(),
                    persisted.backend,
                    persisted.model_sha256,
                    persisted.tokenizer_sha256,
                    current.backend,
                    current.model_sha256,
                    current.tokenizer_sha256,
                ),
            ))),
            None => Err(EngineError::Common(xerj_common::XerjError::embedding(
                format!(
                    "index {} contains ONNX vectors but the server is configured for \
                     embedding.mode={:?}. Restart with onnx-experimental and the original \
                     assets, or rebuild with a new autoindex state directory, new prefix, and new \
                     brain when graph detection is enabled (or --no-graph); validate before \
                     switching readers and explicitly clean the shared catalog and old target.",
                    index_dir.display(),
                    cfg.mode
                ),
            ))),
        };
    }
    // After the ONNX branch, deliberately. When an ONNX marker exists and ONNX
    // is configured, that branch has already returned with a message naming the
    // model and tokenizer digests — strictly more useful than this one, which
    // can only say the backend changed. Running first made the generic message
    // preempt the specific one, which `changed_onnx_assets_are_rejected`
    // caught.
    validate_embedding_execution(index_dir, cfg, new_index, has_documents)?;
    let Some(identity) = configured else {
        return Ok(());
    };
    if !new_index && has_documents {
        return Err(EngineError::Common(xerj_common::XerjError::embedding(
            format!(
                "existing semantic index {} has no embedding identity marker. It may contain \
                 vectors from another backend, so ONNX cannot be enabled safely in place. \
                 Rebuild from source with a new autoindex state directory, new --prefix, and new \
                 --brain when graph detection is enabled (or --no-graph); validate before \
                 switching readers and explicitly clean the shared catalog and old target.",
                index_dir.display()
            ),
        )));
    }
    write_file_atomic(&marker_path, &serde_json::to_vec_pretty(&identity)?)?;
    Ok(())
}

/// Refuse to open an index whose vectors were produced by a DIFFERENT embedder.
///
/// The gap this closes (#434): `configured_onnx_identity` returns `None` for
/// every mode except `onnx-experimental`, so the ONNX identity check
/// short-circuits and never sees a lexical/neural swap. The dimension check
/// cannot see it either — the lexical embedder is 384 wide to match
/// all-MiniLM-L6-v2 on purpose. Measured on a lexical index reopened as neural:
/// status green, no error, and the same query reordering with the score spread
/// collapsing from 0.6303..0.4783 to 0.5496..0.5107, which is what comparing
/// two embedders' vectors looks like — near-uniform similarity, i.e. noise.
///
/// Three boundaries, each of which a previous version of this function got
/// wrong:
///
///   * the record is the RESOLVED identity, so `auto` and the mode it resolves
///     to are one space and a changed proxy endpoint is a different one;
///   * it is REFRESHED while the index is empty rather than written once, so a
///     mode change made while empty (which this permits) cannot leave a stale
///     record that refuses the next restart under the very config that wrote
///     the vectors;
///   * a missing record means UNKNOWN, never mismatched. An index built before
///     this existed is unprotected until it is rebuilt, which is the honest
///     limit — the alternative is inventing a history for it.
fn validate_embedding_execution(
    index_dir: &Path,
    cfg: &xerj_common::config::EmbeddingConfig,
    new_index: bool,
    has_documents: bool,
) -> Result<()> {
    let path = index_dir.join(EMBEDDING_EXECUTION_FILE);
    let current = embedding_execution_identity(cfg)?;
    // #533 migration guard. A genuine embedder change over a POPULATED index is
    // refused. Two signals:
    //  - a backend-NAME change (e.g. lexical -> proxy) is unambiguous at ANY
    //    version — no hash comparison needed, so it is refused even across a
    //    version bump;
    //  - a hash delta is a real change only WITHIN the same on-disk version.
    //    Across an OLDER record the hash was produced by a different algorithm
    //    (v1 hashed a proxy without its endpoint), so it can't be compared and
    //    is grandfathered — the record is then re-recorded at the current
    //    version below, so a LATER change under v2 is still detected.
    let mut version_upgraded = false;
    if path.exists() {
        let persisted: PersistedEmbeddingExecution = serde_json::from_slice(&std::fs::read(&path)?)
            .map_err(|e| {
                EngineError::Common(xerj_common::XerjError::embedding(format!(
                    "cannot read {}: {e}; remove it to re-record, or reindex",
                    path.display()
                )))
            })?;
        let older_record = persisted.version < PERSISTED_EMBEDDING_EXECUTION_VERSION;
        let genuine_change = has_documents
            && (persisted.backend != current.backend
                || (!older_record && persisted.identity_sha256 != current.identity_sha256));
        if genuine_change {
            return Err(EngineError::Common(xerj_common::XerjError::embedding(
                format!(
                    "index {} holds vectors produced by embedding backend {:?} but this server resolves embedding.mode={:?} to backend {:?}. Query vectors from one embedder scored against document vectors from another are silently wrong rather than visibly wrong: the widths can agree, so no dimension check fires, and the scores stay plausible while the ranking degrades toward noise. Restore the previous embedding configuration, or reindex into a new index under this one.",
                    index_dir.display(),
                    persisted.backend,
                    cfg.mode.trim(),
                    current.backend
                ),
            )));
        }
        version_upgraded = older_record;
    }
    if new_index || !has_documents || version_upgraded {
        write_file_atomic(
            &path,
            &serde_json::to_vec_pretty(&PersistedEmbeddingExecution {
                version: PERSISTED_EMBEDDING_EXECUTION_VERSION,
                backend: current.backend.clone(),
                identity_sha256: current.identity_sha256.clone(),
            })?,
        )?;
    }
    Ok(())
}

fn ensure_embedding_identity_for_new_field(
    index_dir: &Path,
    cfg: &xerj_common::config::EmbeddingConfig,
) -> Result<()> {
    // The execution record covers this path too. An index created WITHOUT a
    // semantic field writes no record, so #434 reproduced verbatim through
    // `PUT /_mapping`: the field arrives later, vectors are written under
    // whatever mode is configured then, and nothing had ever recorded which
    // embedder made them. `new_index` is false here and the caller only reaches
    // this before the first write to the new field, so the record is written
    // when the index has no documents and compared when it does.
    // The new field has no vectors yet, so this records rather than compares.
    validate_embedding_execution(index_dir, cfg, false, false)?;
    let Some(configured) = configured_onnx_identity(cfg)? else {
        return Ok(());
    };
    let marker_path = index_dir.join(EMBEDDING_IDENTITY_FILE);
    if marker_path.exists() {
        let persisted: PersistedEmbeddingIdentity =
            serde_json::from_slice(&std::fs::read(&marker_path)?).map_err(|e| {
                EngineError::Common(xerj_common::XerjError::embedding(format!(
                    "cannot read {}: {e}; restore the marker or reindex this index",
                    marker_path.display()
                )))
            })?;
        if persisted != configured {
            return Err(EngineError::Common(xerj_common::XerjError::embedding(
                format!(
                    "embedding identity mismatch for index {}; refusing to add a semantic \
                     field in a different vector space. Restore the original ONNX assets or \
                     create a new index.",
                    index_dir.display()
                ),
            )));
        }
        return Ok(());
    }
    // This field does not exist yet, so existing documents cannot contain its
    // derived vectors. Pin the identity before publishing the mapping; all
    // later writes and restarts are then checked against it.
    write_file_atomic(&marker_path, &serde_json::to_vec_pretty(&configured)?)?;
    Ok(())
}

#[cfg(test)]
mod embedding_identity_tests {
    use super::*;

    fn semantic_schema() -> Schema {
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("body", FieldType::Text).with_embedding(
                xerj_common::types::EmbeddingConfig {
                    endpoint: None,
                    model: None,
                    target_field: None,
                },
            ))
            .unwrap();
        schema
    }

    #[test]
    fn lexical_execution_identity_is_stable_and_sanitized() {
        let cfg = xerj_common::config::EmbeddingConfig::default();
        let identity = embedding_execution_identity(&cfg).unwrap();
        assert_eq!(identity.backend, "lexical");
        assert!(identity.resumable);
        // `Embedder::Lexical` always embeds at DEFAULT_DIMS, so this width is
        // the one the server will really produce.
        assert_eq!(identity.dimensions, Some(xerj_ai::local::DEFAULT_DIMS));
        // The lexical identity has no model asset behind it, so it is bound to
        // the embedder's actual output instead. If this digest moves, every
        // lexical vector moved with it and the resume identity below must move
        // too — see `lexical_algorithm_probe_sha256`.
        assert_eq!(
            lexical_algorithm_probe_sha256(),
            "e6240f3d323831d621fd69a62b39ad70b7efba72e58e949362fdb7f5d53eea53"
        );
        assert_eq!(
            identity.identity_sha256,
            "58a7576ccc1497ee471418bb6e8918c7e5a837161792992e1e213a2dcb2ebdbe"
        );
        let encoded = serde_json::to_string(&identity).unwrap();
        assert!(!encoded.contains("endpoint"));
        assert!(!encoded.contains("path"));
        assert!(
            !encoded.contains("ingest_probe"),
            "an unmeasured probe must stay off the wire: {encoded}"
        );
        assert!(identity.ingest_probe_millis.is_none());
    }

    /// A stored probe must not move `identity_sha256`. The digest is what
    /// resume pins; a rate sample changes every boot.
    #[test]
    fn an_ingest_probe_does_not_change_the_identity_digest() {
        let cfg = xerj_common::config::EmbeddingConfig::default();
        let before = embedding_execution_identity(&cfg).unwrap();
        cfg.neural_ingest_probe
            .set(Some(xerj_common::config::NeuralIngestProbe {
                bytes: 16_384,
                passages: 32,
                millis: 800,
            }))
            .unwrap();
        let after = embedding_execution_identity(&cfg).unwrap();
        assert_eq!(before.identity_sha256, after.identity_sha256);
        assert!(after.ingest_probe_bytes.is_none());
        let encoded = serde_json::to_string(&after).unwrap();
        assert!(!encoded.contains("ingest_probe"), "{encoded}");
    }

    #[test]
    fn configured_backends_report_the_effective_runtime_backend() {
        let neural = xerj_common::config::EmbeddingConfig {
            mode: "neural".into(),
            ..Default::default()
        };
        // Resolve against an EMPTY directory rather than the hub: this asserts
        // the fail-closed arm, and a unit test must never reach the network.
        #[cfg(feature = "neural")]
        let empty_model_dir = tempfile::tempdir().unwrap();
        #[cfg(feature = "neural")]
        let neural = xerj_common::config::EmbeddingConfig {
            local_model_dir: empty_model_dir.path().to_string_lossy().into_owned(),
            ..neural
        };
        let neural_identity = embedding_execution_identity(&neural).unwrap();
        #[cfg(feature = "neural")]
        {
            assert_eq!(neural_identity.backend, "neural");
            // Assets that cannot be resolved stay non-resumable — but the
            // reason names the asset instead of blaming a configuration change
            // (#487: the old text sent operators to reset autoindex state,
            // which no gate here ever reads).
            assert!(!neural_identity.resumable);
            let reason = neural_identity.non_resumable_reason.clone().unwrap();
            assert!(
                reason.contains("content-addressed") && reason.contains("model.safetensors"),
                "the failure must name the missing asset: {reason}"
            );
            // ...and NOTHING else. `non_resumable_reason` is the only field of
            // this struct that is not a digest, so it is the only place a model
            // path or model id could cross the API boundary the struct's own
            // doc comment says they never cross. The operator-facing detail
            // (paths included) goes to the server log instead.
            assert!(
                !reason.contains(&empty_model_dir.path().to_string_lossy().into_owned()),
                "the model directory must not reach a remote client: {reason}"
            );
            assert!(!reason.contains("MiniLM"), "{reason}");
            // The neural width is the resolved model's `hidden_size`, so it is
            // unknown when the model cannot be resolved at all — reporting 384
            // here would be a false statement for any non-384-wide encoder.
            assert_eq!(neural_identity.dimensions, None);
            let encoded = serde_json::to_string(&neural_identity).unwrap();
            assert!(!encoded.contains("dimensions"), "{encoded}");
        }
        #[cfg(not(feature = "neural"))]
        {
            assert_eq!(neural_identity.backend, "lexical");
            assert!(neural_identity.resumable);
            assert_eq!(
                neural_identity.dimensions,
                Some(xerj_ai::local::DEFAULT_DIMS)
            );
        }
        let proxy = xerj_common::config::EmbeddingConfig {
            mode: "proxy".into(),
            default_endpoint: "https://secret.example/v1".into(),
            default_model: "private-alias".into(),
            ..Default::default()
        };
        let identity = embedding_execution_identity(&proxy).unwrap();
        assert_eq!(identity.backend, "proxy");
        assert!(!identity.resumable);
        // No probe has confirmed a width, so it is omitted rather than asserted.
        assert_eq!(identity.dimensions, None);
        let reason = identity.non_resumable_reason.clone().unwrap();
        assert!(
            reason.contains("vector width") && reason.contains("reachable"),
            "an unconfirmed proxy must say why resume is refused and how to retry: {reason}"
        );
        assert!(
            !reason.contains("secret.example") && !reason.contains("private-alias"),
            "the endpoint and model must not reach a remote client: {reason}"
        );
        let encoded = serde_json::to_string(&identity).unwrap();
        assert!(!encoded.contains("secret.example"));
        assert!(!encoded.contains("private-alias"));
        assert!(!encoded.contains("dimensions"), "{encoded}");

        // #1189: an EXPLICIT mode=proxy with an unusable endpoint is a
        // configuration error, not a silent lexical degrade. All three
        // failures previously reported backend "lexical" while the operator
        // believed the node was embedding through their provider.
        for endpoint in ["", "not a url", "file:///private/model"] {
            let broken = xerj_common::config::EmbeddingConfig {
                mode: "proxy".into(),
                default_endpoint: endpoint.into(),
                ..Default::default()
            };
            let err = embedding_execution_identity(&broken)
                .expect_err("explicit proxy with an unusable endpoint must error");
            let msg = format!("{err}");
            assert!(
                msg.contains("embedding.mode=proxy"),
                "the error must name the setting: {msg}"
            );
        }

        // The AUTO path keeps the documented fallback: an unset or unknown
        // mode with a broken endpoint resolves to lexical, never errors.
        for mode in ["auto", "", "somewhere-in-between"] {
            let fallback = xerj_common::config::EmbeddingConfig {
                mode: mode.into(),
                default_endpoint: "not a url".into(),
                ..Default::default()
            };
            let identity = embedding_execution_identity(&fallback).unwrap();
            assert_eq!(identity.backend, "lexical", "{mode}");
            assert!(identity.resumable, "{mode}");
            // The fallback really did become lexical, so the pinned lexical
            // width is the truthful answer here.
            assert_eq!(
                identity.dimensions,
                Some(xerj_ai::local::DEFAULT_DIMS),
                "{mode}"
            );
        }
    }

    /// #1189: explicit mode=proxy fails closed at the embedder too, with the
    /// proxy's own error carried through; the auto path keeps the documented
    /// lexical fallback.
    #[test]
    fn explicit_proxy_mode_fails_closed_at_the_embedder() {
        for endpoint in ["", "htp://typo.example/v1", "file:///etc/hosts"] {
            let cfg = xerj_common::config::EmbeddingConfig {
                mode: "proxy".into(),
                default_endpoint: endpoint.into(),
                ..Default::default()
            };
            // `Embedder` is not Debug, so plain `expect_err` cannot print
            // the Ok side; map it away first.
            let err = make_embedder(&cfg)
                .map(|_| ())
                .expect_err("explicit proxy with an unusable endpoint must error");
            let msg = format!("{err}");
            assert!(
                msg.contains("embedding.mode=proxy"),
                "must name the setting: {msg}"
            );
            // The typo case carries the underlying scheme error so the
            // operator sees what is actually wrong with the URL.
            if endpoint.starts_with("htp://") {
                assert!(
                    msg.contains("http or https"),
                    "must carry the proxy's own init error: {msg}"
                );
            }
        }

        // Auto with the same broken endpoint still boots as lexical — that
        // fallback is the documented auto behavior and stays.
        let auto = xerj_common::config::EmbeddingConfig {
            mode: "auto".into(),
            default_endpoint: "htp://typo.example/v1".into(),
            ..Default::default()
        };
        make_embedder(&auto).unwrap();
        assert_eq!(
            embedding_execution_identity(&auto).unwrap().backend,
            "lexical"
        );
    }

    /// #522: the #434 guard (`validate_embedding_execution`) was unit-tested at
    /// the identity level but never end to end. A populated index must REFUSE
    /// to reopen under a genuinely different embedder, and must NOT refuse a
    /// config change that resolves to the same embedder.
    #[test]
    fn a_populated_index_refuses_reopen_under_a_different_embedder() {
        let dir = tempfile::tempdir().unwrap();
        let index_dir = dir.path();
        let lexical = xerj_common::config::EmbeddingConfig::default();

        // Genesis under lexical (new, empty) records the execution identity;
        // reopening under the SAME embedder with documents is fine.
        validate_embedding_execution(index_dir, &lexical, true, false).unwrap();
        validate_embedding_execution(index_dir, &lexical, false, true).unwrap();

        // Reopening a POPULATED index under a genuinely different embedder
        // (proxy with a real endpoint → backend "proxy") must refuse: querying
        // lexical vectors against proxy vectors is silently wrong.
        let proxy = xerj_common::config::EmbeddingConfig {
            mode: "proxy".into(),
            default_endpoint: "https://vectors.example/v1".into(),
            default_model: "text-embedding-x".into(),
            ..Default::default()
        };
        let err = validate_embedding_execution(index_dir, &proxy, false, true)
            .expect_err("a lexical->proxy swap over a populated index must be refused");
        let msg = format!("{err}");
        assert!(
            msg.contains("holds vectors produced by embedding backend")
                && msg.contains("lexical")
                && msg.contains("proxy"),
            "the refusal must name both the recorded and the current backend: {msg}"
        );

        // Over-refusal guard (#1189 update): a proxy config with NO endpoint
        // used to silently resolve to lexical and reopen cleanly. It is now a
        // configuration error at the identity level, so reopening fails with
        // the same actionable message instead of a confusing mismatch refusal.
        let proxy_without_endpoint = xerj_common::config::EmbeddingConfig {
            mode: "proxy".into(),
            default_endpoint: String::new(),
            ..Default::default()
        };
        let err = validate_embedding_execution(index_dir, &proxy_without_endpoint, false, true)
            .expect_err("proxy with no endpoint is a config error, not a lexical reopen");
        assert!(
            format!("{err}").contains("embedding.mode=proxy"),
            "must name the setting: {err}"
        );
    }

    /// #533: the proxy `default_endpoint` is part of the embedder identity. Same
    /// model behind a different endpoint is a different embedder; before this it
    /// slipped past the #434 guard (a missed detection).
    #[test]
    fn proxy_endpoint_is_part_of_the_execution_identity() {
        let a = xerj_common::config::EmbeddingConfig {
            mode: "proxy".into(),
            default_endpoint: "https://a.example/v1".into(),
            default_model: "text-embedding-x".into(),
            ..Default::default()
        };
        let b = xerj_common::config::EmbeddingConfig {
            default_endpoint: "https://b.example/v1".into(),
            ..a.clone()
        };
        let id_a = embedding_execution_identity(&a).unwrap();
        let id_b = embedding_execution_identity(&b).unwrap();
        assert_eq!(id_a.backend, "proxy");
        assert_ne!(
            id_a.identity_sha256, id_b.identity_sha256,
            "#533: same model + different endpoint must be distinct identities"
        );

        // End to end: a populated proxy index reopened under a swapped endpoint
        // (same identity version, different sha) is refused.
        let dir = tempfile::tempdir().unwrap();
        let index_dir = dir.path();
        validate_embedding_execution(index_dir, &a, true, false).unwrap();
        let err = validate_embedding_execution(index_dir, &b, false, true)
            .expect_err("#533: a swapped proxy endpoint over a populated index must be refused");
        assert!(format!("{err}").contains("holds vectors produced by embedding backend"));
    }

    /// #2306: confirming a proxy width makes the backend resumable and publishes
    /// that width. The digest stays the model+endpoint string, so a probe
    /// cannot change the hash an existing index was recorded under.
    #[test]
    fn confirmed_proxy_width_makes_semantic_resume_possible() {
        let cfg = xerj_common::config::EmbeddingConfig {
            mode: "proxy".into(),
            default_endpoint: "https://secret.example/v1".into(),
            default_model: "private-alias".into(),
            ..Default::default()
        };
        let unconfirmed = embedding_execution_identity(&cfg).unwrap();
        assert!(!unconfirmed.resumable);
        assert_eq!(unconfirmed.dimensions, None);

        let confirmed_cfg = cfg.clone();
        *confirmed_cfg.runtime_proxy_width.write().unwrap() =
            Some(xerj_common::config::ConfirmedProxyWidth {
                endpoint: confirmed_cfg.default_endpoint.clone(),
                model: confirmed_cfg.default_model.clone(),
                dimensions: 384,
            });
        let confirmed = embedding_execution_identity(&confirmed_cfg).unwrap();
        assert!(confirmed.resumable);
        assert_eq!(confirmed.dimensions, Some(384));
        assert!(confirmed.non_resumable_reason.is_none());
        assert_eq!(
            confirmed.identity_sha256, unconfirmed.identity_sha256,
            "the probed width must not move the digest"
        );
        let encoded = serde_json::to_string(&confirmed).unwrap();
        assert!(!encoded.contains("secret.example"));
        assert!(!encoded.contains("private-alias"));

        *confirmed_cfg.runtime_proxy_width.write().unwrap() =
            Some(xerj_common::config::ConfirmedProxyWidth {
                endpoint: confirmed_cfg.default_endpoint.clone(),
                model: confirmed_cfg.default_model.clone(),
                dimensions: 768,
            });
        let wider = embedding_execution_identity(&confirmed_cfg).unwrap();
        assert_eq!(wider.dimensions, Some(768));
        assert_eq!(wider.identity_sha256, unconfirmed.identity_sha256);

        // A cached width for a different endpoint is not this embedder.
        *confirmed_cfg.runtime_proxy_width.write().unwrap() =
            Some(xerj_common::config::ConfirmedProxyWidth {
                endpoint: "https://other.example/v1".into(),
                model: confirmed_cfg.default_model.clone(),
                dimensions: 384,
            });
        let mismatched = embedding_execution_identity(&confirmed_cfg).unwrap();
        assert!(!mismatched.resumable);
        assert_eq!(mismatched.dimensions, None);
    }

    /// #2306: one successful probe confirms the width and stores it. A later
    /// probe that cannot reach the endpoint reuses that store for the same
    /// model. A store for a different model is ignored.
    #[test]
    fn proxy_width_probe_confirms_dimensions_and_falls_back_to_the_last_confirmation() {
        let endpoint = serve_proxy_embeddings(8, 200);
