        let reused_encoded = serde_json::to_string(&reused).unwrap();
        assert!(!reused_encoded.contains("127.0.0.1"));
        assert!(!reused_encoded.contains("\"m\""));

        let other_model = xerj_common::config::EmbeddingConfig {
            default_model: "other".into(),
            ..down.clone()
        };
        confirm_proxy_embedding_width(&other_model, cache_dir.path());
        let ignored = embedding_execution_identity(&other_model).unwrap();
        assert!(!ignored.resumable);
        assert_eq!(ignored.dimensions, None);
    }

    /// One HTTP embedding response, then the socket closes. `status` is 200 or 400.
    fn serve_proxy_embeddings(width: usize, status: u16) -> String {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        std::thread::spawn(move || {
            let _ = listener.set_nonblocking(false);
            if let Ok((mut sock, _)) = listener.accept() {
                let mut buf = [0u8; 8192];
                let _ = std::io::Read::read(&mut sock, &mut buf);
                let embedding: Vec<f64> = (0..width).map(|i| (i as f64) * 0.01).collect();
                let body = if status == 200 {
                    serde_json::json!({"data":[{"index":0,"embedding":embedding}]}).to_string()
                } else {
                    "{\"error\":\"refused\"}".to_string()
                };
                let reason = if status == 200 { "OK" } else { "Bad Request" };
                let resp = format!(
                    "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                let _ = std::io::Write::write_all(&mut sock, resp.as_bytes());
            }
        });
        format!("http://{addr}/v1/embeddings")
    }

    /// #533 migration: a record persisted at version 1 (before the endpoint was
    /// folded in) must be grandfathered — not refused — on upgrade, then
    /// re-recorded at the current version so a LATER change IS detected.
    #[test]
    fn a_version_1_record_is_grandfathered_then_rebaselined() {
        let dir = tempfile::tempdir().unwrap();
        let index_dir = dir.path();
        let path = index_dir.join(EMBEDDING_EXECUTION_FILE);
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&PersistedEmbeddingExecution {
                version: 1,
                backend: "proxy".into(),
                identity_sha256: "legacy-v1-sha-without-endpoint".into(),
            })
            .unwrap(),
        )
        .unwrap();

        let proxy = xerj_common::config::EmbeddingConfig {
            mode: "proxy".into(),
            default_endpoint: "https://a.example/v1".into(),
            default_model: "text-embedding-x".into(),
            ..Default::default()
        };
        // Populated index, v1 record, v2 current → grandfathered (not refused).
        validate_embedding_execution(index_dir, &proxy, false, true)
            .expect("#533: a v1 record must be grandfathered, not refused, on upgrade");

        // Re-baselined to v2 with the current identity.
        let rewritten: PersistedEmbeddingExecution =
            serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        assert_eq!(
            rewritten.version, PERSISTED_EMBEDDING_EXECUTION_VERSION,
            "#533: the record must be re-recorded at the CURRENT version (asserted              against the constant so a later migration bump — #487 took it to 3 —              does not silently turn this into a no-op)"
        );
        assert_eq!(
            rewritten.identity_sha256,
            embedding_execution_identity(&proxy)
                .unwrap()
                .identity_sha256
        );

        // After re-baselining, a LATER endpoint change under v2 IS detected.
        let swapped = xerj_common::config::EmbeddingConfig {
            default_endpoint: "https://b.example/v1".into(),
            ..proxy.clone()
        };
        validate_embedding_execution(index_dir, &swapped, false, true)
            .expect_err("#533: after re-baselining, a v2 endpoint change must be refused");
    }

    /// #487 migration, the same shape as #533 one backend over: content-
    /// addressing the neural identity MOVES `identity_sha256` for every neural
    /// node, so a v2 record over a POPULATED neural index would compare a hash
    /// from the superseded algorithm against the new one and refuse to open the
    /// index. It must be grandfathered and re-baselined instead — otherwise the
    /// change that makes neural corpora re-indexable bricks the ones that exist.
    ///
    /// Fails on the unfixed code because `PERSISTED_EMBEDDING_EXECUTION_VERSION`
    /// was still 2: the record was current, the hash comparison ran, and the
    /// open was refused.
    #[cfg(feature = "neural")]
    #[test]
    fn a_version_2_neural_record_is_grandfathered_then_rebaselined() {
        let dir = tempfile::tempdir().unwrap();
        let index_dir = dir.path();
        let path = index_dir.join(EMBEDDING_EXECUTION_FILE);
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&PersistedEmbeddingExecution {
                version: 2,
                backend: "neural".into(),
                // What rc.71 wrote for EVERY neural node: sha256 of
                // "…;backend=neural;neural-unpinned.v1;configured-model=…".
                identity_sha256: "6e51e5ce3e463db6d6d853516c358e4a529308f213e85d2ed005f731d00ce8f3"
                    .into(),
            })
            .unwrap(),
        )
        .unwrap();

        let model_dir = neural_model_dir(384, "weights-migration");
        let neural = xerj_common::config::EmbeddingConfig {
            mode: "neural".into(),
            local_model_dir: model_dir.path().to_string_lossy().into_owned(),
            ..Default::default()
        };
        // Populated index, v2 record, v3 current → grandfathered, not refused.
        validate_embedding_execution(index_dir, &neural, false, true)
            .expect("#487: a v2 neural record must be grandfathered, not refused, on upgrade");

        let rewritten: PersistedEmbeddingExecution =
            serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        assert_eq!(rewritten.version, PERSISTED_EMBEDDING_EXECUTION_VERSION);
        assert_eq!(
            rewritten.identity_sha256,
            embedding_execution_identity(&neural)
                .unwrap()
                .identity_sha256
        );

        // Re-baselined, so a GENUINE later model swap is still refused.
        let swapped_dir = neural_model_dir(384, "weights-migration-swapped");
        let swapped = xerj_common::config::EmbeddingConfig {
            local_model_dir: swapped_dir.path().to_string_lossy().into_owned(),
            ..neural.clone()
        };
        validate_embedding_execution(index_dir, &swapped, false, true)
            .expect_err("#487: after re-baselining, a swapped model must be refused");
    }

    /// #533: the version-delta grandfather must NOT mask a genuine BACKEND change
    /// — a lexical->proxy swap is a different embedder regardless of hash, so a
    /// populated index whose v1 record names a different backend is still refused
    /// on the first upgraded reopen (the hash is uncomparable across versions,
    /// but the backend name is not).
    #[test]
    fn a_version_delta_still_refuses_a_backend_change() {
        let dir = tempfile::tempdir().unwrap();
        let index_dir = dir.path();
        let path = index_dir.join(EMBEDDING_EXECUTION_FILE);
        // Legacy v1 record: the index holds LEXICAL vectors.
        std::fs::write(
            &path,
            serde_json::to_vec_pretty(&PersistedEmbeddingExecution {
                version: 1,
                backend: "lexical".into(),
                identity_sha256: "legacy-lexical-sha".into(),
            })
            .unwrap(),
        )
        .unwrap();
        // Reopen the POPULATED index under a proxy config → backend "proxy".
        let proxy = xerj_common::config::EmbeddingConfig {
