            query_node_to_fts(&q, &["body".to_string()], &kw(&[])).expect("text phrase projects");
        match fq {
            FtsQuery::Phrase(p) => {
                assert_eq!(p.field, "body");
                // standard analyzer lowercases + tokenizes on word boundaries.
                assert_eq!(p.terms, vec!["quick", "brown", "fox"]);
                assert_eq!(p.slop, 0);
            }
