    /// The two `None`s `query_node_to_fts` returns for a `QueryString` mean
    /// opposite things, and `scan_stored` has to tell them apart: zero tokens
    /// means nothing can match (skip the segment), an over-cap cross-product
    /// means the query is matchable and the stored scan is the only route.
    #[test]
    fn zero_token_query_string_is_distinguished_from_an_over_cap_one() {
        let punctuation = QueryNode::QueryString {
            query: "+++".into(),
            default_field: None,
            default_operator: None,
            boost: None,
        };
        let one_field = vec!["body".to_string()];
        assert!(
            query_node_to_fts(&punctuation, &one_field, &kw(&[])).is_none(),
            "pure punctuation projects to nothing"
        );
        assert!(
            query_string_has_no_tokens(&punctuation, &kw(&[])),
            "…and that `None` must be reported as UNMATCHABLE, not as a \
             decline that needs the stored-doc scan"
        );

        // The other `None`: a matchable query that blew the cross-product cap.
        let many_fields: Vec<String> = (0..2_000).map(|i| format!("f{i}")).collect();
        let over_cap = qs_tokens(3);
        assert!(
            query_node_to_fts(&over_cap, &many_fields, &kw(&[])).is_none(),
            "3 × 2 000 is over the cap"
        );
        assert!(
            !query_string_has_no_tokens(&over_cap, &kw(&[])),
            "an over-cap query still matches documents and MUST keep the scan"
        );

        // An ordinary query is never mistaken for unmatchable.
        assert!(!query_string_has_no_tokens(&qs_tokens(2), &kw(&[])));
        // Non-`QueryString` nodes are not this function's business.
        assert!(!query_string_has_no_tokens(&QueryNode::MatchAll, &kw(&[])));

        // Keyword `default_field`: the projection short-circuits to a
        // whole-value term BEFORE tokenising, so an un-analyzable string is a
        // legitimate term there and must NOT be called unmatchable.
        let on_keyword = QueryNode::QueryString {
            query: "+++".into(),
            default_field: Some("code".into()),
            default_operator: None,
            boost: None,
        };
        assert!(
            query_node_to_fts(&on_keyword, &one_field, &kw(&["code"])).is_some(),
            "a keyword default_field projects to a whole-value term"
        );
        assert!(!query_string_has_no_tokens(&on_keyword, &kw(&["code"])));
        // Same string on a TEXT default_field does tokenise to nothing.
        assert!(query_string_has_no_tokens(&on_keyword, &kw(&[])));
    }

    /// Regression: `query_string` with no `default_field` set (ES/OpenSearch
    /// semantics — `index.query.default_field` defaults to `"*"`, i.e.
    /// search every mapped text field) used to pick only `text_fields[0]`,
    /// an arbitrary single field chosen by schema order. Any match in every
    /// OTHER text field was silently missed. Found live: a Kibana/OSD
    /// Timelion panel's `query_string` (used to select which index's docs
    /// to count inside a `filters` aggregation) undercounted matches by two
    /// orders of magnitude because the schema's first text field happened
    /// not to be the one holding the searched value.
    #[test]
    fn query_string_with_no_default_field_searches_every_text_field() {
        let q = QueryNode::QueryString {
            query: "needle".into(),
            default_field: None,
            default_operator: None,
            boost: None,
        };
        let text_fields = vec!["agent".to_string(), "message".to_string()];
        let fq = query_node_to_fts(&q, &text_fields, &kw(&[])).expect("projects");
        match fq {
            FtsQuery::Bool(b) => {
                let fields: Vec<&str> = b
                    .should
                    .iter()
                    .map(|s| match s {
                        FtsQuery::Term(t) => t.field.as_str(),
                        other => panic!("expected term, got {:?}", other),
                    })
                    .collect();
                assert!(
                    fields.contains(&"message"),
                    "must search every text field, not just the first — got {fields:?}"
                );
                assert!(fields.contains(&"agent"), "got {fields:?}");
            }
            other => panic!("expected bool, got {:?}", other),
        }
    }

    /// Build a field-less `query_string` node over `n_tokens` tokens.
    fn qs_tokens(n_tokens: usize) -> QueryNode {
        QueryNode::QueryString {
            query: (0..n_tokens)
                .map(|i| format!("tok{i} "))
                .collect::<String>(),
            default_field: None,
            default_operator: None,
            boost: None,
        }
    }

    /// BLOCKER: the field-less projection builds one `should` clause per
    /// (token × field) and `execute_bool` then materialises a full hit vector
    /// per clause, so the product must be capped exactly like the
    /// `more_like_this` `fields × like` cross-product is capped at parse time.
    /// Uncapped, 500 tokens × 80 fields is 40 000 clauses re-built for EVERY
    /// segment of the scan.
    #[test]
    fn field_less_query_string_cross_product_is_capped() {
        let text_fields: Vec<String> = (0..80).map(|i| format!("f{i}")).collect();
        assert!(
            query_node_to_fts(&qs_tokens(500), &text_fields, &kw(&[])).is_none(),
            "500 × 80 = 40 000 clauses must not be projected; the request \
             falls back to the stored-doc scan, which is deadline-polled"
        );
        // Either dimension can carry the product past the cap on its own.
        let one_field = vec!["body".to_string()];
        assert!(
            query_node_to_fts(&qs_tokens(5_000), &one_field, &kw(&[])).is_none(),
            "5 000 tokens × 1 field is still 5 000 clauses"
        );
        let many_fields: Vec<String> = (0..2_000).map(|i| format!("f{i}")).collect();
        assert!(
            query_node_to_fts(&qs_tokens(3), &many_fields, &kw(&[])).is_none(),
            "3 tokens × 2 000 fields is 6 000 clauses"
        );
    }

    /// The cap must not touch ordinary queries: a realistic mapping and a
    /// realistic query still project to the postings path, with every clause
    /// accounted for. A WIDE mapping with a short query especially — capping
    /// the field count on its own would have pushed it off the fast path.
    #[test]
    fn field_less_query_string_within_the_cap_still_projects() {
        let text_fields: Vec<String> = (0..8).map(|i| format!("f{i}")).collect();
        let fq = query_node_to_fts(&qs_tokens(20), &text_fields, &kw(&[])).expect("projects");
        match fq {
            FtsQuery::Bool(b) => assert_eq!(
                b.should.len(),
                20 * 8,
                "every (token × field) pair is a clause"
            ),
            other => panic!("expected bool, got {other:?}"),
        }
        let wide: Vec<String> = (0..300).map(|i| format!("f{i}")).collect();
        let fq = query_node_to_fts(&qs_tokens(2), &wide, &kw(&[])).expect("wide mapping projects");
        match fq {
            FtsQuery::Bool(b) => assert_eq!(b.should.len(), 2 * 300),
            other => panic!("expected bool, got {other:?}"),
        }
    }

    /// HIGH: a segment that never indexed one of the queried fields must have
    /// only THAT clause dropped, not the whole disjunction rejected. Rejecting
    /// it sent the segment to a stored-doc scan that had no `query_string`
    /// matcher, so its documents silently vanished from `hits.total`.
    #[test]
    fn prune_drops_only_the_clauses_a_segment_cannot_serve() {
        let q = FtsQuery::Bool(Box::new(
            FtsBool::new()
                .should(FtsQuery::Term(FtsTerm::new("alpha", "needle")))
                .should(FtsQuery::Term(FtsTerm::new("beta", "needle"))),
        ));
        let pruned =
            prune_missing_should_fields(&q, &|f| f == "alpha").expect("prunes to the kept field");
        match pruned {
            FtsQuery::Bool(b) => {
                assert_eq!(b.should.len(), 1);
                match &b.should[0] {
                    FtsQuery::Term(t) => assert_eq!(t.field, "alpha"),
                    other => panic!("expected term, got {other:?}"),
                }
            }
            other => panic!("expected bool, got {other:?}"),
        }
        // Every field present → nothing to prune, caller keeps the original.
        assert!(prune_missing_should_fields(&q, &|_| true).is_none());
        // No field present → indistinguishable from a segment with no FTS
        // side-cars at all; the caller must fall through to the stored scan
        // rather than report an authoritative zero.
        assert!(prune_missing_should_fields(&q, &|_| false).is_none());
        // Conjunctive shapes keep the conservative all-present gate: dropping
        // a `must` clause would BROADEN the query.
        let conj = FtsQuery::Bool(Box::new(
            FtsBool::new()
                .must(FtsQuery::Term(FtsTerm::new("alpha", "needle")))
                .should(FtsQuery::Term(FtsTerm::new("beta", "needle"))),
        ));
        assert!(prune_missing_should_fields(&conj, &|f| f == "alpha").is_none());
    }

    /// HIGH: the stored-doc scan is the ONLY thing that answers for a segment
    /// the FTS route declines, and it had no `query_string` arm — every such
    /// document was a silent non-match.
    #[test]
    fn doc_scan_matches_field_less_query_string_on_any_text_field() {
        let q = QueryNode::QueryString {
            query: "needle".into(),
            default_field: None,
            default_operator: None,
            boost: None,
        };
        assert!(doc_matches_query(
            &q,
            &serde_json::json!({"alpha": "a needle in here"})
        ));
        assert!(doc_matches_query(
            &q,
            &serde_json::json!({"alpha": "nope", "beta": "needle"})
        ));
        assert!(doc_matches_query(
            &q,
            &serde_json::json!({"alpha": ["nope", "needle"]})
        ));
        assert!(!doc_matches_query(
            &q,
            &serde_json::json!({"alpha": "haystack"})
        ));
        // `_id` is spliced into the scanned source but is not a mapped text
        // field — matching it would over-count relative to the FTS route.
        assert!(!doc_matches_query(
            &q,
            &serde_json::json!({"_id": "needle", "alpha": "haystack"})
        ));
        // An explicit default_field stays single-field.
        let pinned = QueryNode::QueryString {
            query: "needle".into(),
            default_field: Some("alpha".into()),
            default_operator: None,
            boost: None,
        };
        assert!(doc_matches_query(
            &pinned,
            &serde_json::json!({"alpha": "needle"})
        ));
        assert!(!doc_matches_query(
            &pinned,
            &serde_json::json!({"beta": "needle"})
        ));
    }

    /// Field collector walks every clause of a projected query.
    #[test]
    fn collect_fields_walks_bool_tree() {
        let q = FtsQuery::Bool(Box::new({
            let mut b = FtsBool::new();
            b = b.must(FtsQuery::Term(FtsTerm::new("model", "x")));
            b = b.should(FtsQuery::Term(FtsTerm::new("status", "ok")));
            b = b.must_not(FtsQuery::Term(FtsTerm::new("model", "y")));
            b
        }));
        let mut out = Vec::new();
        collect_fts_query_fields(&q, &mut out);
        out.sort();
        assert_eq!(out, vec!["model".to_string(), "status".to_string()]);
    }
}

#[cfg(test)]
mod percolate_tests {
    use super::*;
    use serde_json::json;
    use xerj_query::ast::QueryNode;

    /// A stored percolator doc holds a serialized query in `query`; the
    /// percolate query matches that stored doc iff the stored query matches
    /// one of the supplied inline documents.
    #[test]
    fn percolate_term_match_and_miss() {
        let stored = json!({ "query": { "term": { "message": "bonsai" } } });

        let q_hit = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "message": "bonsai" })],
        };
        assert!(
            doc_matches_query(&q_hit, &stored),
            "term matches inline doc"
        );

        let q_miss = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "message": "cactus" })],
        };
        assert!(
            !doc_matches_query(&q_miss, &stored),
            "term does not match a different value"
        );
    }

    #[test]
    fn percolate_range_and_bool() {
        let stored_range = json!({ "query": { "range": { "price": { "gte": 10, "lte": 20 } } } });
        let q = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "price": 15 })],
        };
        assert!(doc_matches_query(&q, &stored_range));
        let q_out = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "price": 25 })],
        };
        assert!(!doc_matches_query(&q_out, &stored_range));

        let stored_bool = json!({
            "query": {
                "bool": {
                    "must": [
                        { "term": { "message": "foo" } },
                        { "range": { "price": { "gte": 5 } } }
                    ]
                }
            }
        });
        let q_bool = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "message": "foo", "price": 9 })],
        };
        assert!(doc_matches_query(&q_bool, &stored_bool));
        let q_bool_miss = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "message": "foo", "price": 1 })],
        };
        assert!(!doc_matches_query(&q_bool_miss, &stored_bool));
    }

    #[test]
    fn percolate_missing_or_unparseable_field_is_no_match() {
        let stored = json!({ "message": "no query here" });
        let q = QueryNode::Percolate {
            field: "query".into(),
            documents: vec![json!({ "message": "anything" })],
        };
        assert!(!doc_matches_query(&q, &stored));

        let stored2 = json!({ "query": "not-an-object" });
        assert!(!doc_matches_query(&q, &stored2));
    }
}

#[cfg(test)]
mod script_query_tests {
    //! A standalone `script` query is a boolean filter (no scoring), used
    //! e.g. by OpenSearch's UBI sample dashboards to filter on a computed
    //! field via a Painless boolean lambda. Distinct from `script_score`.
    use super::*;
    use serde_json::json;
    use xerj_query::ast::QueryNode;

    #[test]
    fn script_query_matches_when_truthy() {
        let doc = json!({"x": 10});
        let q = QueryNode::Script {
            source: "doc['x'].value > params.min".to_string(),
            params: Some(json!({"min": 5})),
        };
        assert!(doc_matches_query(&q, &doc));
    }

    #[test]
    fn script_query_no_match_when_falsy() {
        let doc = json!({"x": 1});
        let q = QueryNode::Script {
            source: "doc['x'].value > params.min".to_string(),
            params: Some(json!({"min": 5})),
        };
        assert!(!doc_matches_query(&q, &doc));
    }

    #[test]
    fn script_query_fails_closed_on_script_error() {
        let doc = json!({"x": 1});
        let q = QueryNode::Script {
            source: "this is not valid painless".to_string(),
            params: None,
        };
        assert!(!doc_matches_query(&q, &doc));
    }

    #[test]
    fn script_query_fails_closed_on_non_boolean_result() {
        // A script that evaluates to a number (not a boolean) must not match
        // — ES itself requires `script` queries to return a boolean.
        let doc = json!({"x": 1});
        let q = QueryNode::Script {
            source: "1 + 1".to_string(),
            params: None,
        };
        assert!(!doc_matches_query(&q, &doc));
    }

    #[test]
    fn script_query_null_guard_filters_rather_than_dropping_everything() {
        // The standard shape for a script filter over a field that isn't on
        // every document, written the way Elasticsearch documents it. If the
        // guard errors instead of yielding a boolean, the script is
        // unrunnable and EVERY document is dropped — including the ones that
        // should match. This is what a `script` query looks like in
        // practice, so it is checked at the query surface and not only in
        // the Painless unit tests.
        let q = QueryNode::Script {
            source: "doc['x'].size() == 0 ? false : doc['x'].value > params.min".to_string(),
            params: Some(json!({"min": 5})),
        };
        assert!(
            doc_matches_query(&q, &json!({"x": 10})),
            "guarded script must still match the document it selects for"
        );
        assert!(!doc_matches_query(&q, &json!({"x": 1})));
        assert!(
            !doc_matches_query(&q, &json!({"other": 1})),
            "a document without the field must be filtered out, not matched"
        );
    }

    #[test]
    fn script_query_with_a_typoed_field_matches_nothing() {
        // The bug the fail-closed `.value` exists for: reading a missing
        // field as 0 made `doc['typo'].value > -1` true for every document,
        // turning a filter into a no-op. It must match NOTHING instead —
        // including documents that do have the correctly-spelled field.
        let q = QueryNode::Script {
            source: "doc['coutn'].value > -1".to_string(),
            params: None,
        };
        for doc in [
            json!({"count": 5}),
            json!({"count": 0}),
            json!({}),
            json!({"coutn": null}),
        ] {
            assert!(
                !doc_matches_query(&q, &doc),
                "a typo'd field name must not match {doc}"
            );
        }
        // And the correctly-spelled query still works, so this is a spelling
        // check and not a blanket refusal.
        let ok = QueryNode::Script {
            source: "doc['count'].value > -1".to_string(),
            params: None,
        };
        assert!(doc_matches_query(&ok, &json!({"count": 5})));
    }
}

#[cfg(test)]
mod highlight_multibyte_tests {
    //! Regression tests for the multibyte-highlight SIGABRT: a term whose
    //! byte offset in the lowercased text does not line up with the original
    //! text (because lowercasing `İ` U+0130 grows 2 bytes → 3) used to make
    //! the renderer slice the ORIGINAL string at a lowercased offset, yielding
    //! `end byte index 15 is out of bounds for string of length 14` and
    //! aborting the whole server (index.rs:14727). All slicing now goes through
    //! [`lower_span_to_orig`], which maps back to original char boundaries.
    use super::*;

    #[test]
    fn offset_map_translates_i_dot_above() {
        // "İa": İ = 2 bytes original, lowercases to `i` + combining dot = 3.
        let (lower, map) = build_lower_offset_map("İa");
        assert_eq!(lower, "i\u{307}a");
        assert_eq!(map, vec![(0, 0, 2), (3, 2, 3)]);
        // The 'a' sits at byte 3 in the lowercased text but byte 2 in the
        // original. A naive slice at 3 would land past the İ inside a 3-byte
        // string. The mapping must recover the original [2,3) span.
        let orig_len = "İa".len();
        assert_eq!(lower_span_to_orig(&map, orig_len, 3, 4), (2, 3));
        // Matching the İ itself (via lowercased 'i') covers the whole char.
        assert_eq!(lower_span_to_orig(&map, orig_len, 0, 1), (0, 2));
    }

    #[test]
    fn full_text_highlight_after_multibyte_does_not_panic() {
        // This is the exact shape that crashed: a normal token ("cafe")
        // preceded by an İ so the lowercased offsets are shifted +1.
        let text = "İstanbul cafe";
        let (lower, map) = build_lower_offset_map(text);
        let terms = vec!["cafe".to_string()];
        let out = highlight_full_text(text, &lower, &map, &terms, "<em>", "</em>");
        assert_eq!(out, "İstanbul <em>cafe</em>");
    }

    #[test]
    fn full_text_highlight_match_at_very_end() {
        // Term is the final character right after the İ — the offset in the
        // lowercased text points one byte past the end of the original string.
        let text = "İa";
        let (lower, map) = build_lower_offset_map(text);
        let terms = vec!["a".to_string()];
        let out = highlight_full_text(text, &lower, &map, &terms, "<em>", "</em>");
        assert_eq!(out, "İ<em>a</em>");
    }

    #[test]
    fn fragment_highlight_finds_a_rare_term_buried_after_many_common_ones() {
        // The defect this guards: the candidate scan used to share one budget
        // across all terms and `terms` arrives sorted, so a common word
        // exhausted the quota and the distinctive word was never searched for.
        // Candidates were then ordered earliest-first, so even when both were
        // found the top-of-document match won. Two blind usability runs asked
        // for a phrase deep in a large file, both got fragments from the head
        // of the file, and both abandoned highlighting entirely.
        // Each filler block is far wider than `fragment_size`, so every common
        // match claims its own fragment window instead of collapsing into a
        // shared one — the shape of a real source file, where the rare term
        // sits thousands of bytes past hundreds of common ones.
        let pad = "x".repeat(600);
        let mut text = String::new();
        for i in 0..300 {
            text.push_str(&format!("function helper_{i}() {{ /* {pad} */ }}\n"));
        }
        text.push_str("function human_time_diff( $from, $to = 0 ) { return 1; }\n");
        for i in 0..300 {
            text.push_str(&format!("function tail_{i}() {{ /* {pad} */ }}\n"));
        }

        let (lower, map) = build_lower_offset_map(&text);
        // Sorted, as `extract_highlight_terms` produces: the common term first.
        let terms = vec!["function".to_string(), "human_time_diff".to_string()];
        let frags = build_highlight_fragments(&text, &lower, &map, &terms, "<em>", "</em>", 200, 2);

        assert!(!frags.is_empty(), "expected fragments");
        assert!(
            frags.iter().any(|f| f.contains("human_time_diff")),
            "the rare term is what the caller searched for; fragments must reach \
             it rather than returning the head of the document: {frags:?}"
        );
    }

    /// #1948: a phrase query highlighted `or` inside `for` and `no` inside
    /// `not`, and only the one match each fragment was centred on, so the
    /// phrase itself came back untagged.
    #[test]
    fn highlight_tags_whole_words_and_every_term_in_the_fragment() {
        let text = "Pricing is per-node for Professional, custom for Enterprise. \
                    No per-doc, per-vector, or per-query fees. Binary delivery \
                    does not require a sector license.";
        let (lower, map) = build_lower_offset_map(text);
        let mut terms: Vec<String> = ["no", "per-doc", "per-vector", "or", "per-query", "fees"]
            .iter()
            .map(|t| t.to_string())
            .collect();
        terms.sort();
        let frags = build_highlight_fragments(text, &lower, &map, &terms, "<em>", "</em>", 150, 1);
        assert_eq!(frags.len(), 1, "{frags:?}");
        let f = &frags[0];
        assert!(
            f.contains("<em>No</em> <em>per-doc</em>, <em>per-vector</em>, <em>or</em> <em>per-query</em> <em>fees</em>"),
            "every phrase word is tagged in place: {f}"
        );
        assert!(!f.contains("f<em>or</em>"), "no match inside `for`: {f}");
        assert!(!f.contains("<em>no</em>t"), "no match inside `not`: {f}");

        let full = highlight_full_text(text, &lower, &map, &terms, "<em>", "</em>");
        assert!(
            !full.contains("f<em>or</em>") && !full.contains("<em>no</em>t"),
            "{full}"
        );
        assert!(!full.contains("sect<em>or</em>"), "{full}");

        // A `query_string` prefix term still reaches into the word.
        let (lower, map) = build_lower_offset_map("a wildcard and wild cats");
        let prefix = vec!["wild*".to_string()];
        let full = highlight_full_text("a wildcard and wild cats", &lower, &map, &prefix, "[", "]");
        assert_eq!(full, "a [wildcard] and [wild] cats");
        assert_eq!(next_term_match("rewild", "wild*", 0), None);
    }

    #[test]
    fn fragment_highlight_after_multibyte_does_not_panic() {
        let text = "İstanbul cafe";
        let (lower, map) = build_lower_offset_map(text);
        let terms = vec!["cafe".to_string()];
        let frags = build_highlight_fragments(text, &lower, &map, &terms, "<em>", "</em>", 150, 3);
        assert_eq!(frags.len(), 1);
        assert!(
            frags[0].contains("<em>cafe</em>"),
            "fragment should wrap the match: {:?}",
            frags[0]
        );
        // The İ context must survive intact (valid UTF-8, no mangled bytes).
        assert!(frags[0].contains('İ'), "context preserved: {:?}", frags[0]);
    }

    #[test]
    fn multiple_multibyte_chars_and_matches() {
        // Several length-growing chars before/around matches to exercise the
        // cumulative offset drift.
        let text = "İİ dodo İ cafe";
        let (lower, map) = build_lower_offset_map(text);
        let terms = vec!["dodo".to_string(), "cafe".to_string()];
        let out = highlight_full_text(text, &lower, &map, &terms, "<em>", "</em>");
        assert_eq!(out, "İİ <em>dodo</em> İ <em>cafe</em>");
    }
}

#[cfg(test)]
mod lexical_passage_tests {
    //! Query-time `_passage` selection for the lexical path (#174): the
    //! query-term-densest window of the source, snapped to line boundaries,
    //! with exact byte offsets so a caller can slice a large field.
    use super::*;
    use serde_json::json;

    fn select(text: &str, weighted: &[(&str, f32)]) -> Option<(f32, usize, usize, u32)> {
        let (lower, map) = build_lower_offset_map(text);
        select_lexical_passage(text, &lower, &map, weighted)
    }

    /// The head of the file (licence banner, includes) must lose to the deep
    /// window that actually contains the query terms — the exact failure in
    /// #174 where head-slicing `body` returned zero relevant characters.
    #[test]
    fn deep_definition_beats_file_head() {
        let mut text = String::new();
        text.push_str("/* Copyright banner licence text */\n");
        for i in 0..200 {
            text.push_str(&format!("#include <header_{i}.h>\n"));
        }
        let def_line_idx = text.lines().count();
        text.push_str("void addReplyNull(client *c) {\n");
        text.push_str("    addReplyProto(c, \"$-1\\r\\n\", 5);\n");
        text.push_str("}\n");
        for _ in 0..100 {
            text.push_str("static int unrelated_trailer(void) { return 0; }\n");
        }
        let weighted = [("addreplynull", 0.5f32), ("reply", 0.25f32)];
        let (score, start, end, ordinal) = select(&text, &weighted).expect("a window");
        assert!(score > 0.0);
        let passage = &text[start..end];
        assert!(
            passage.contains("addReplyNull"),
            "window must cover the definition, got: {passage:?}"
        );
        // Line-snapped: starts at a line start, ends at a line end.
        assert!(start == 0 || text.as_bytes()[start - 1] == b'\n');
        assert!(end == text.len() || text.as_bytes()[end] == b'\n');
        assert!(end - start <= LEXICAL_PASSAGE_MAX_BYTES);
        // `ordinal` is the zero-based line index of the window start; the
        // window is budget-limited so it starts well past the banner and at
        // or before the definition line.
        assert!(ordinal > 0, "must not sit at the file head");
        assert!((ordinal as usize) <= def_line_idx);
    }

    /// A lone occurrence of a rare, distinctive term must outweigh a region
    /// dense in a term that appears everywhere (tantivy's rarity weighting
    /// adapted to one document).
    #[test]
    fn rare_term_outweighs_common_term_swarm() {
        let mut text = String::new();
        for _ in 0..40 {
            text.push_str("null null null null common swamp line\n");
        }
        for _ in 0..80 {
            text.push_str("padding line with nothing relevant at all\n");
        }
        text.push_str("the distinctive addreplynull definition lives here\n");
        let null_count = count_term_occurrences(&text, "null");
        let rare_count = count_term_occurrences(&text, "addreplynull");
        assert_eq!(rare_count, 1);
        // NOTE: "addreplynull" contains "null", so null_count includes it.
        // Same squared-rarity formula as `apply_lexical_passages`.
        let w = |n: usize| {
            let denom = 1.0 + n as f32;
            1.0 / (denom * denom)
        };
        let weighted = [("addreplynull", w(rare_count)), ("null", w(null_count))];
        let (_, start, end, _) = select(&text, &weighted).expect("a window");
        assert!(
            text[start..end].contains("distinctive"),
            "rare-term window must win, got: {:?}",
            &text[start..end]
        );
    }

    /// A single line longer than the whole budget (minified JS) cannot be
    /// line-snapped: the fallback takes a char-boundary window inside the
    /// line, centred on the first term occurrence.
    #[test]
    fn oversized_single_line_falls_back_to_char_window() {
        let mut text = "é".repeat(3000);
        text.push_str("needle");
        text.push_str(&"é".repeat(3000));
        let weighted = [("needle", 0.5f32)];
        let (_, start, end, ordinal) = select(&text, &weighted).expect("a window");
        assert_eq!(ordinal, 0);
        assert!(end - start <= LEXICAL_PASSAGE_MAX_BYTES);
        assert!(text.is_char_boundary(start) && text.is_char_boundary(end));
        assert!(text[start..end].contains("needle"));
    }

    #[test]
    fn no_term_occurrence_returns_none() {
        assert!(select("plain text without the words\n", &[("absent", 1.0)]).is_none());
        assert!(select("", &[("absent", 1.0)]).is_none());
    }

    /// Exact slice contract: `start_offset`/`end_offset` must reproduce
    /// `text` byte-for-byte when sliced from the original field.
    #[test]
    fn apply_fills_passage_with_exact_offsets_and_page() {
        let body = format!(
            "{}fn the_answer() {{\n    compute_bulk_reply()\n}}\n{}",
            "// filler line of no consequence\n".repeat(120),
            "// trailing filler\n".repeat(120)
        );
        let query = QueryNode::MultiMatch {
            fields: vec!["body".into(), "title".into()],
            query: "the_answer bulk reply".into(),
            match_type: Default::default(),
            operator: None,
            analyzer: None,
            boost: None,
            slop: 0,
            max_expansions: 50,
            lenient: false,
        };
        let hit = Hit {
            id: "doc-1".into(),
            score: 1.0,
            source: json!({"body": body, "title": "unrelated", "page": 3}),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        };
        let out = apply_lexical_passages(vec![hit], &query);
        let passage = out[0].passage.as_ref().expect("lexical passage filled");
        assert_eq!(passage.field, "body");
        assert_eq!(passage.page, Some(3));
        let (s, e) = (passage.start_offset as usize, passage.end_offset as usize);
        assert_eq!(&body[s..e], passage.text, "offsets must slice exactly");
        assert!(passage.text.contains("the_answer"));
        assert!(e - s <= LEXICAL_PASSAGE_MAX_BYTES);
        // Line-snapped window with the match centred in surrounding context,
        // and `ordinal` = zero-based line index of the window start.
        assert!(
            s == 0 || body.as_bytes()[s - 1] == b'\n',
            "line-snapped start"
        );
        assert!(
            e == body.len() || body.as_bytes()[e] == b'\n',
            "line-snapped end"
        );
        assert_eq!(
            passage.ordinal as usize,
            body[..s].matches('\n').count(),
            "ordinal = line index of window start"
        );
        assert!(passage.ordinal > 0, "window must not hug the file head");
    }

    /// #2327: a nested test callback under the 16 KiB AST cap used to be
    /// returned whole. The passage stays inside the lexical window and keeps
    /// the line ordinal of that window.
    #[test]
    fn nested_test_callback_passage_stays_inside_the_lexical_window() {
        let mut callback = String::from("() => {\n  const CALLBACK_START_SENTINEL = 1;\n");
        for i in 0..70 {
            callback.push_str(&format!(
                "  const pad_{i:03} = \"session-token-handler-pad\";\n"
            ));
        }
        callback.push_str("  const refreshMarker = sessionTokenHandler();\n}\n");
        assert!(callback.len() > LEXICAL_PASSAGE_MAX_BYTES);
        assert!(callback.len() < crate::code_blocks::DEFAULT_MAX_BLOCK_BYTES);
        let body = format!(
            "{}\ndescribe(\"session token\", () => {{\n  it(\"refreshes the handler\", {callback});\n}});\n",
            "// preamble\n".repeat(8)
        );
        let query = QueryNode::MultiMatch {
            fields: vec!["body".into()],
            query: "refreshMarker sessionTokenHandler".into(),
            match_type: Default::default(),
            operator: None,
            analyzer: None,
            boost: None,
            slop: 0,
            max_expansions: 50,
            lenient: false,
        };
        let hit = Hit {
            id: "doc-1".into(),
            score: 1.0,
            source: json!({
                "body": body,
                "language": "typescript",
                "symbol_count": 2
            }),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        };
        let out = apply_lexical_passages(vec![hit], &query);
        let passage = out[0].passage.as_ref().expect("lexical passage filled");
        assert!(
            passage.text.contains("refreshMarker"),
            "the window must contain the match: {}",
            passage.text
        );
        assert!(
            passage.text.len() <= LEXICAL_PASSAGE_MAX_BYTES,
            "a nested callback must not be returned whole ({} bytes)",
            passage.text.len()
        );
        assert!(
            !passage.text.contains("CALLBACK_START_SENTINEL"),
            "the callback head is outside the window: {}",
            passage.text
        );
        let start = passage.start_offset as usize;
        assert_eq!(
            passage.ordinal as usize,
            body[..start].matches('\n').count(),
            "ordinal is the file line of the bounded window"
        );
        assert!(passage.ordinal > 0, "the preamble keeps a real line");
    }

