        let passage = out[0].passage.as_ref().expect("passage filled");
        assert_eq!(passage.field, "code", "got {passage:?}");
    }

    /// #174: a document that merely carries a field named `language` (not
    /// autoindex's code-extractor shape — no `symbol_count`) must keep the
    /// exact line-snapped window the lexical selector already computed.
    #[test]
    fn non_code_document_lexical_passage_ignores_stray_language_field() {
        let body = format!(
            "{}fn target(x: i32) -> i32 {{\n    let y = x + 1;\n    y * needle_marker\n}}\n{}",
            "// filler line of no consequence\n".repeat(80),
            "// trailing filler\n".repeat(80)
        );
        let query = QueryNode::Match {
            field: "body".into(),
            query: "needle_marker".into(),
            operator: Default::default(),
            analyzer: None,
            boost: None,
            minimum_should_match: None,
            lenient: false,
        };
        let plain_hit = Hit {
            id: "doc-1".into(),
            score: 1.0,
            source: json!({"body": body}),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        };
        let tagged_hit = Hit {
            id: "doc-2".into(),
            score: 1.0,
            // Same body, but with a stray `language` field and no
            // `symbol_count` — not autoindex's code-doc shape.
            source: json!({"body": body, "language": "rust"}),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        };
        let plain_out = apply_lexical_passages(vec![plain_hit], &query);
        let tagged_out = apply_lexical_passages(vec![tagged_hit], &query);
        let plain_passage = plain_out[0].passage.as_ref().expect("plain passage filled");
        let tagged_passage = tagged_out[0]
            .passage
            .as_ref()
            .expect("tagged passage filled");
        assert_eq!(plain_passage.start_offset, tagged_passage.start_offset);
        assert_eq!(plain_passage.end_offset, tagged_passage.end_offset);
        assert_eq!(plain_passage.text, tagged_passage.text);
        assert!(
            !plain_passage.text.starts_with("fn target"),
            "without symbol_count this must stay the raw line-snapped window, not a widened block"
        );
    }

    /// A semantic-path passage (exact ingest-time chunk provenance) must
    /// never be overwritten by the query-time selector.
    #[test]
    fn existing_semantic_passage_is_preserved() {
        let query = QueryNode::Match {
            field: "body".into(),
            query: "needle".into(),
            operator: Default::default(),
            analyzer: None,
            boost: None,
            minimum_should_match: None,
            lenient: false,
        };
        let semantic = PassageMatch {
            field: "body".into(),
            ordinal: 7,
            start_offset: 10,
            end_offset: 20,
            text: "from-chunks".into(),
            page: None,
        };
        let hit = Hit {
            id: "doc-1".into(),
            score: 1.0,
            source: json!({"body": "needle here\n"}),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: Some(semantic.clone()),
        };
        let out = apply_lexical_passages(vec![hit], &query);
        assert_eq!(out[0].passage.as_ref(), Some(&semantic));
    }
}

#[cfg(test)]
mod knn_num_candidates_tests {
    use super::*;
    use xerj_query::ast::QueryNode;

    fn nested_knn(num_candidates: Option<usize>) -> QueryNode {
        QueryNode::Nested {
            path: "passages".into(),
            query: Box::new(QueryNode::Knn {
                field: "passages.vec".into(),
                vector: vec![1.0, 0.0, 0.0],
                k: 2,
                num_candidates,
                filter: None,
                boost: None,
                similarity: None,
            }),
            score_mode: None,
        }
    }

    /// `num_candidates` is peeled out of a nested knn query as its own value.
    #[test]
    fn peel_nested_carries_num_candidates() {
        let q = nested_knn(Some(10));
        let peeled = peel_nested_knn_query(&q).expect("nested knn peels");
        // Tuple: (path, field, vector, k, num_candidates, pre, post).
        assert_eq!(peeled.0, "passages");
        assert_eq!(peeled.3, 2, "k");
        assert_eq!(peeled.4, Some(10), "num_candidates");
    }

    /// When omitted, num_candidates peels to None (the caller then defaults
    /// it to k and clamps to >= k).
    #[test]
    fn peel_nested_num_candidates_none_when_omitted() {
        let q = nested_knn(None);
        let peeled = peel_nested_knn_query(&q).expect("nested knn peels");
        assert_eq!(peeled.4, None);
    }

    /// Top-level knn peels num_candidates too (ignored by exact brute force,
    /// but still surfaced).
    #[test]
    fn peel_top_level_carries_num_candidates() {
        let q = QueryNode::Knn {
            field: "vec".into(),
            vector: vec![0.1, 0.2],
            k: 5,
            num_candidates: Some(64),
            filter: None,
            boost: None,
            similarity: None,
        };
        let peeled = peel_knn_query(&q).expect("knn peels");
        assert_eq!(peeled.k, 5, "k");
        assert_eq!(peeled.num_candidates, Some(64), "num_candidates");
    }

    /// A wrapping `Boosted` multiplies into the peeled knn boost, and the
    /// knn node's own `boost`/`similarity` are carried through the peel.
    #[test]
    fn peel_carries_boost_and_similarity() {
        let inner = QueryNode::Knn {
            field: "vec".into(),
            vector: vec![0.1, 0.2],
            k: 5,
            num_candidates: None,
            filter: None,
            boost: Some(2.0),
            similarity: Some(0.9),
        };
        let q = QueryNode::Boosted {
            boost: 3.0,
            query: Box::new(inner),
        };
        let peeled = peel_knn_query(&q).expect("knn peels");
        assert_eq!(peeled.boost, Some(6.0), "outer boost multiplies inner");
        assert_eq!(peeled.similarity, Some(0.9), "similarity carried");
    }

    /// `bool.should` of >= 2 knn clauses (the ES `knn: [...]` array form)
    /// peels as a multi-knn; any non-knn sibling clause disqualifies it.
    #[test]
    fn peel_multi_knn_shapes() {
        let knn = |x: f32| QueryNode::Knn {
            field: "vec".into(),
            vector: vec![x, 0.0],
            k: 3,
            num_candidates: None,
            filter: None,
            boost: None,
            similarity: None,
        };
        let pure = QueryNode::Bool {
            must: vec![],
            should: vec![knn(1.0), knn(0.5)],
            filter: vec![],
            must_not: vec![],
            minimum_should_match: None,
        };
        let clauses = peel_multi_knn_query(&pure).expect("pure multi-knn peels");
        assert_eq!(clauses.len(), 2);
        assert_eq!(clauses[0].k, 3);

        let hybrid = QueryNode::Bool {
            must: vec![],
            should: vec![
                knn(1.0),
                QueryNode::Term {
                    field: "tag".into(),
                    value: serde_json::json!("a"),
                    boost: None,
                },
                knn(0.5),
            ],
            filter: vec![],
            must_not: vec![],
            minimum_should_match: None,
        };
        assert!(
            peel_multi_knn_query(&hybrid).is_none(),
            "non-knn sibling must fall through to the generic path"
        );
    }
}

#[cfg(test)]
mod span_containment_tests {
    use super::*;
    use serde_json::json;
    use xerj_query::ast::QueryNode;

    fn span_term(field: &str, value: &str) -> QueryNode {
        QueryNode::SpanTerm {
            field: field.into(),
            value: value.into(),
        }
    }

    /// A `big` span_near over [quick, fox] with slop 3, and a `little`
    /// span_term(brown) that falls between them.
    fn near_quick_fox() -> QueryNode {
        QueryNode::SpanNear {
            clauses: vec![span_term("text", "quick"), span_term("text", "fox")],
            slop: 3,
            in_order: true,
        }
    }

    #[test]
    fn span_within_little_inside_big_matches() {
        // "the quick brown fox jumps": brown (pos 2) is inside the
        // quick..fox span (pos 1..3).
        let doc = json!({ "text": "the quick brown fox jumps" });
        let q = QueryNode::SpanWithin {
            little: Box::new(span_term("text", "brown")),
            big: Box::new(near_quick_fox()),
        };
        assert!(doc_matches_query(&q, &doc));
    }

    #[test]
    fn span_containing_big_contains_little_matches() {
        let doc = json!({ "text": "the quick brown fox jumps" });
        let q = QueryNode::SpanContaining {
            little: Box::new(span_term("text", "brown")),
            big: Box::new(near_quick_fox()),
        };
        assert!(doc_matches_query(&q, &doc));
    }

    #[test]
    fn span_within_non_enclosing_does_not_match() {
        // "jumps" (pos 4) is outside the quick..fox span (pos 1..3).
        let doc = json!({ "text": "the quick brown fox jumps" });
        let q = QueryNode::SpanWithin {
            little: Box::new(span_term("text", "jumps")),
            big: Box::new(near_quick_fox()),
        };
        assert!(!doc_matches_query(&q, &doc));

        // And when the big span does not even form (no "quick" near "fox").
        let doc2 = json!({ "text": "brown only here" });
        let q2 = QueryNode::SpanContaining {
            little: Box::new(span_term("text", "brown")),
            big: Box::new(near_quick_fox()),
        };
        assert!(!doc_matches_query(&q2, &doc2));
    }
}

#[cfg(test)]
mod terms_set_tests {
    use super::*;
    use serde_json::json;
    use xerj_query::ast::{MinShouldMatch, QueryNode};

    /// Build the Bool that `terms_set` lowers to: a `should` of Term clauses
    /// over `codes` with the given `minimum_should_match`.
    fn terms_set_bool(codes: &[&str], msm: MinShouldMatch) -> QueryNode {
        QueryNode::Bool {
            must: vec![],
            must_not: vec![],
            filter: vec![],
            should: codes
                .iter()
                .map(|c| QueryNode::Term {
                    field: "codes".into(),
                    value: json!(c),
                    boost: None,
                })
                .collect(),
            minimum_should_match: Some(msm),
        }
    }

    #[test]
    fn terms_set_field_required_count() {
        let q = terms_set_bool(&["a", "b", "c"], MinShouldMatch::Field("required".into()));

        // 2 of the codes present, required 2 => match.
        assert!(doc_matches_query(
            &q,
            &json!({ "codes": ["a", "b"], "required": 2 })
        ));
        // Only 1 present, required 2 => no match.
        assert!(!doc_matches_query(
            &q,
            &json!({ "codes": ["a"], "required": 2 })
        ));
        // required exceeds the number of matching terms => no match.
        assert!(!doc_matches_query(
            &q,
            &json!({ "codes": ["a", "b", "c"], "required": 4 })
        ));
        // required field missing => unsatisfiable, no match.
        assert!(!doc_matches_query(&q, &json!({ "codes": ["a", "b", "c"] })));
        // required field non-numeric => unsatisfiable, no match.
        assert!(!doc_matches_query(
            &q,
            &json!({ "codes": ["a", "b"], "required": "two" })
        ));
    }

    #[test]
    fn terms_set_script_num_terms() {
        // source `params.num_terms` => require ALL terms to match.
        let q = terms_set_bool(
            &["a", "b", "c"],
            MinShouldMatch::Script {
                source: "params.num_terms".into(),
                params: None,
            },
        );
        // All three present => match.
        assert!(doc_matches_query(&q, &json!({ "codes": ["a", "b", "c"] })));
        // Only two present => no match.
        assert!(!doc_matches_query(&q, &json!({ "codes": ["a", "b"] })));
    }
}

#[cfg(test)]
mod rank_feature_tests {
    use super::*;
    use serde_json::json;
    use xerj_query::ast::{RankFeature, RankFeatureFn};

    fn score(function: RankFeatureFn, v: f64) -> f32 {
        let rf = RankFeature {
            field: "pagerank".into(),
            function,
        };
        compute_rank_feature_score(&rf, &json!({ "pagerank": v }))
    }

    #[test]
    fn saturation_formula_and_ordering() {
        // v / (v + pivot); pivot = 8.
        let f = |v| score(RankFeatureFn::Saturation { pivot: Some(8.0) }, v);
        assert!((f(8.0) - 0.5).abs() < 1e-6, "8/(8+8) = 0.5");
        assert!((f(2.0) - 0.2).abs() < 1e-6, "2/(2+8) = 0.2");
        // Monotonic increasing.
        assert!(f(2.0) < f(8.0) && f(8.0) < f(100.0));
    }

    #[test]
    fn linear_is_identity() {
        assert!((score(RankFeatureFn::Linear, 42.0) - 42.0).abs() < 1e-4);
        assert!((score(RankFeatureFn::Linear, 3.5) - 3.5).abs() < 1e-4);
    }

    #[test]
    fn log_is_monotonic() {
        let f = |v| {
            score(
                RankFeatureFn::Log {
                    scaling_factor: 4.0,
                },
                v,
            )
        };
        // log10(4 + 6) = 1.0.
        assert!((f(6.0) - 1.0).abs() < 1e-6);
        assert!(f(1.0) < f(6.0) && f(6.0) < f(96.0));
    }

    #[test]
    fn missing_field_scores_zero() {
        let rf = RankFeature {
            field: "pagerank".into(),
            function: RankFeatureFn::Linear,
        };
        assert_eq!(compute_rank_feature_score(&rf, &json!({ "other": 1 })), 0.0);
    }
}

#[cfg(test)]
mod chunk_embed_tests {
    use super::*;
    use xerj_ai::local::{local_embed, DEFAULT_DIMS};

    fn l2_norm(v: &[f32]) -> f32 {
        v.iter().map(|x| x * x).sum::<f32>().sqrt()
    }

    /// A long, multi-sentence document is split into more than one chunk and
    /// pooled into a single unit-norm vector of exactly `dims` elements.
    #[test]
    fn long_text_chunks_and_pools_to_unit_vector() {
        let text =
            "The quick brown fox jumps over the lazy dog. Pack my box with five dozen liquor jugs. "
                .repeat(20);
        assert!(text.len() > SEMANTIC_CHUNK_SIZE);

        // (b) The chunker actually produced more than one chunk.
        let chunks = semantic_chunker().chunk(&text, None);
        assert!(
            chunks.len() > 1,
            "expected multiple chunks, got {}",
            chunks.len()
        );

        // (a) Output has exactly `dims` elements and is unit-norm.
        let v = local_chunk_embed(&text, DEFAULT_DIMS);
        assert_eq!(v.len(), DEFAULT_DIMS);
        assert!(
            (l2_norm(&v) - 1.0).abs() < 1e-4,
            "pooled vector is unit-norm"
        );
    }

    /// (c) A short string still embeds to a single unit-norm vector identical
    /// to the pre-change `local_embed` path.
    #[test]
    fn short_text_is_identical_to_pre_change_path() {
        let text = "Hello world, this is a short document.";
        assert!(text.len() <= SEMANTIC_CHUNK_SIZE);

        let got = local_chunk_embed(text, DEFAULT_DIMS);
        let expected = local_embed(text, DEFAULT_DIMS);
        assert_eq!(got, expected, "short text is a no-op vs local_embed");
        assert!(
            (l2_norm(&got) - 1.0).abs() < 1e-4,
            "single-chunk vector unit-norm"
        );
    }

    /// mean_pool_normalize on already-unit vectors returns a unit vector.
    #[test]
    fn mean_pool_of_two_vectors_is_unit_norm() {
        let a = local_embed("first chunk of text", DEFAULT_DIMS);
        let b = local_embed("a very different second chunk", DEFAULT_DIMS);
        let pooled = mean_pool_normalize(&[a, b]);
        assert_eq!(pooled.len(), DEFAULT_DIMS);
        assert!((l2_norm(&pooled) - 1.0).abs() < 1e-4);
    }

    /// `local_chunk_vectors` returns one unit-norm vector PER passage for a
    /// multi-chunk document, and pooling those equals `local_chunk_embed`.
    #[test]
    fn chunk_vectors_are_per_passage_and_pool_consistently() {
        let text =
            "The quick brown fox jumps over the lazy dog. Pack my box with five dozen liquor jugs. "
                .repeat(20);
        let n_chunks = semantic_chunker().chunk(&text, None).len();
        assert!(n_chunks > 1, "fixture must span multiple chunks");

        let vecs = local_chunk_vectors(&text, DEFAULT_DIMS);
        assert_eq!(vecs.len(), n_chunks, "one vector per chunk");
        for v in &vecs {
            assert_eq!(v.len(), DEFAULT_DIMS);
            assert!(
                (l2_norm(v) - 1.0).abs() < 1e-4,
                "each passage vector unit-norm"
            );
        }
        // Pooling the per-chunk vectors reproduces the pooled companion.
        assert_eq!(
            mean_pool_normalize(&vecs),
            local_chunk_embed(&text, DEFAULT_DIMS)
        );
    }

    /// The whole point of per-chunk storage: a query that matches ONE buried
    /// passage of a long document scores higher against the best chunk
    /// (max-sim) than against the blurred whole-document pooled vector. This
    /// is the vector-level invariant the ingest+query wiring relies on.
    #[test]
    fn max_sim_over_chunks_beats_pooled_for_a_buried_passage() {
        // A long document whose passages cover distinct topics; the topic of
        // interest ("photosynthesis chloroplast ...") is only ONE passage.
        let filler =
            "quarterly revenue guidance and operating margins for the fiscal year. ".repeat(12);
        let target_passage =
            "photosynthesis converts sunlight into chemical energy inside the chloroplast \
             of a plant cell using chlorophyll pigments. ";
        let doc = format!("{filler}{target_passage}{filler}");
        assert!(
            semantic_chunker().chunk(&doc, None).len() > 1,
            "doc must span multiple chunks"
        );

        let query = "how does chlorophyll drive photosynthesis in a chloroplast";
        let q = local_embed(query, DEFAULT_DIMS);

        // Pooled: the whole-doc average vector (what we stored before).
        let pooled = local_chunk_embed(&doc, DEFAULT_DIMS);
        let pooled_score = compute_vector_similarity("cosine", &q, &pooled);

        // Per-chunk: best-matching passage (what semantic search now uses).
        let chunk_vecs = local_chunk_vectors(&doc, DEFAULT_DIMS);
        let max_sim = chunk_vecs
            .iter()
            .map(|cv| compute_vector_similarity("cosine", &q, cv))
            .fold(f32::MIN, f32::max);

        assert!(
            max_sim > pooled_score,
            "best-passage max-sim ({max_sim}) should beat pooled ({pooled_score})"
        );
    }

    #[test]
    fn passage_scoring_ties_choose_lowest_ordinal() {
        let mut best = None;
        choose_passage_winner(&mut best, 1.0, 0);
        choose_passage_winner(&mut best, 1.0, 1);
        assert_eq!(best, Some((1.0, 0)));
    }

    #[test]
    fn passage_metadata_roundtrip_uses_valid_utf8_byte_boundaries() {
        let text = "Préface αβ. Résumé 📄 quarterly evidence. 終了";
        let start = text.find("Résumé").unwrap();
        let end = text.find("終了").unwrap();
        let source = serde_json::json!({
            "content": text,
            "page": 42,
            "__xerj_passage_meta__embedding": {
                "field": "content",
                "chunks": [[0, start], [start, end], [end, text.len()]]
            }
        });
        let roundtrip: Value =
            serde_json::from_slice(&serde_json::to_vec(&source).unwrap()).unwrap();
        let passage = passage_match_from_source(&roundtrip, "embedding", Some(1)).unwrap();
        assert_eq!(passage.ordinal, 1);
        assert_eq!(passage.page, Some(42));
        assert_eq!(
            passage.text,
            &text[passage.start_offset as usize..passage.end_offset as usize]
        );
        assert!(text.is_char_boundary(passage.start_offset as usize));
        assert!(text.is_char_boundary(passage.end_offset as usize));

        let malformed = serde_json::json!({
            "content": text,
            "__xerj_passage_meta__embedding": {
                "field": "content",
                "chunks": [[3, text.len()]]
            }
        });
        assert!(
            passage_match_from_source(&malformed, "embedding", Some(0)).is_none(),
            "offset inside the multibyte 'P/é' sequence must be refused"
        );
    }

    /// #174 AST-aligned passages: a document that merely carries a field
    /// literally named `language` (e.g. a course-catalog entry tagged
    /// `"language": "rust"`, not a source file) must NOT trigger AST
    /// refinement — `refine_code_passage` also requires autoindex's
    /// code-extractor signature (`symbol_count`) and the canonical `body`
    /// field. Every non-code document must come back byte-identical to the
    /// window computed from the stored chunk offsets, unconditionally.
    #[test]
    fn non_code_document_passage_is_byte_identical_regardless_of_language_field() {
        // Deliberately shaped like the reported bug (a dangling brace mid
        // window) so a wrongly-triggered AST pass would have visibly changed
        // the span rather than silently agreeing with it.
        let text = "\t}\n\n\tif ( isset( $x ) ) {\n\t\tdo_thing();\n\t}\n";
        let start = text.find("if (").unwrap();
        let end = start + "if ( isset( $x ) )".len();
        let source = serde_json::json!({
            "body": text,
            "language": "rust",
            "__xerj_passage_meta__embedding": {
                "field": "body",
                "chunks": [[start, end]]
            }
        });
        let passage = passage_match_from_source(&source, "embedding", Some(0)).unwrap();
        assert_eq!(passage.start_offset as usize, start);
        assert_eq!(passage.end_offset as usize, end);
        assert_eq!(passage.text, &text[start..end]);
    }

    /// #174: a CODE document (autoindex's `language` + `symbol_count` +
    /// `body` shape) whose stored chunk offsets land mid-statement inside a
    /// function — exactly the reported bug, a passage opening on a dangling
    /// brace — must be widened to the smallest enclosing function.
    #[test]
    fn code_document_passage_widens_to_enclosing_function() {
        let body = "fn before() {\n    1\n}\n\nfn target(x: i32) -> i32 {\n    let y = x + 1;\n    y * 2\n}\n\nfn after() {\n    2\n}\n";
        let needle = "y * 2";
        let start = body.find(needle).unwrap();
        let end = start + needle.len();
        let source = serde_json::json!({
            "body": body,
            "language": "rust",
            "symbol_count": 3,
            "__xerj_passage_meta__embedding": {
                "field": "body",
                "chunks": [[start, end]]
            }
        });
        let passage = passage_match_from_source(&source, "embedding", Some(0)).unwrap();
        assert!(
            passage.text.starts_with("fn target"),
            "passage must start at the enclosing function's declaration, got: {:?}",
            passage.text
        );
        assert_eq!(
            passage.text,
            &body[passage.start_offset as usize..passage.end_offset as usize],
            "start/end offsets must still slice exactly onto `text`"
        );
        assert!(!passage.text.contains("before"));
        assert!(!passage.text.contains("after"));
    }

    #[test]
    fn passage_metadata_has_bounded_stored_overhead_without_text_duplication() {
        let content = "quarterly finance evidence with stable page-local wording. ".repeat(24);
        let plain: Vec<Value> = (0..256)
            .map(|id| {
                serde_json::json!({
                    "_id": id.to_string(),
                    "_seq_no": id,
                    "_source": {"content": content.as_str(), "page": id % 32}
                })
            })
            .collect();
        let with_metadata: Vec<Value> = plain
            .iter()
            .cloned()
            .map(|mut doc| {
                doc["_source"]["__xerj_passage_meta__embedding"] = serde_json::json!({
                    "field": "content",
                    "chunks": [[0, 384], [320, 704], [640, 1024], [960, content.len()]]
                });
                doc
            })
            .collect();
        let plain_json = serde_json::to_vec(&plain).unwrap();
        let metadata_json = serde_json::to_vec(&with_metadata).unwrap();
        let plain_stored = xerj_storage::stored_codec::encode_stored_v2(&plain_json);
        let metadata_stored = xerj_storage::stored_codec::encode_stored_v2(&metadata_json);
        let delta = metadata_stored.len().saturating_sub(plain_stored.len());
        assert!(
            delta < 64 * plain.len(),
            "compact offsets added {delta} bytes ({:.2} bytes/doc)",
            delta as f64 / plain.len() as f64
        );
        assert_eq!(
            metadata_json
                .windows(content.len())
                .filter(|window| *window == content.as_bytes())
                .count(),
            plain.len(),
            "metadata must not duplicate passage text"
        );
        eprintln!(
            "controlled passage metadata stored delta: {delta} bytes / {} docs = {:.2} bytes/doc",
            plain.len(),
            delta as f64 / plain.len() as f64
        );
    }

    #[test]
    fn varied_passage_metadata_reports_raw_and_stored_overhead() {
        let mut plain = Vec::with_capacity(256);
        let mut with_metadata = Vec::with_capacity(256);
        let mut authoritative_texts = Vec::with_capacity(256);
        for id in 0..256 {
            let content = format!(
                "Résumé 📄 page {id}. {} 終了 {}",
                "finance covenant narrative. ".repeat(3 + id % 29),
                "auditor footnote. ".repeat(1 + (id * 7) % 17)
            );
            let offsets: Vec<Value> = {
                let chunks = semantic_chunker().chunk(&content, None);
                if chunks.len() <= 1 {
                    vec![serde_json::json!([0, content.len()])]
                } else {
                    chunks
                        .iter()
                        .map(|chunk| serde_json::json!([chunk.start_offset, chunk.end_offset]))
                        .collect()
                }
            };
            let doc = serde_json::json!({
                "_id": format!("report-{id:04}"),
                "_seq_no": id,
                "_source": {
                    "content": content,
                    "page": 1 + id % 97,
                    "company": format!("company-{}", id % 23)
                }
            });
            let mut enriched = doc.clone();
            enriched["_source"]["__xerj_passage_meta__embedding"] = serde_json::json!({
                "field": "content",
                "chunks": offsets
            });
            authoritative_texts.push(
                doc["_source"]["content"]
                    .as_str()
                    .expect("fixture content")
                    .to_string(),
            );
            plain.push(doc);
            with_metadata.push(enriched);
        }
        let plain_json = serde_json::to_vec(&plain).unwrap();
        let metadata_json = serde_json::to_vec(&with_metadata).unwrap();
        let raw_delta = metadata_json.len() - plain_json.len();
        let plain_stored = xerj_storage::stored_codec::encode_stored_v2(&plain_json);
        let metadata_stored = xerj_storage::stored_codec::encode_stored_v2(&metadata_json);
        let stored_delta = metadata_stored.len().saturating_sub(plain_stored.len());
        for text in &authoritative_texts {
            assert_eq!(
                metadata_json
                    .windows(text.len())
                    .filter(|window| *window == text.as_bytes())
                    .count(),
                1,
                "metadata must not duplicate authoritative content"
            );
        }
        assert!(stored_delta < raw_delta);
        eprintln!(
            "varied passage metadata delta: raw={raw_delta} bytes ({:.2}/doc), \
             stored={stored_delta} bytes ({:.2}/doc)",
            raw_delta as f64 / plain.len() as f64,
            stored_delta as f64 / plain.len() as f64
        );
    }
}

#[cfg(test)]
mod write_publication_integration_tests {
    use super::*;
    use serde_json::json;
    use std::sync::atomic::{AtomicBool, AtomicUsize};

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn put_holds_publication_key_through_response_before_delete() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("publication-hook", Schema::empty())
            .unwrap();
        let idx = engine.get_index("publication-hook").unwrap();

        let initial = idx
            .index_document(Some("same".into()), json!({"state": "initial"}))
            .await
            .unwrap();

        let acquired = Arc::new(AtomicUsize::new(0));
        let pause_once = Arc::new(AtomicBool::new(false));
        let (paused_tx, paused_rx) = std::sync::mpsc::sync_channel(1);
        let (resume_tx, resume_rx) = std::sync::mpsc::sync_channel(1);
        let paused_tx = parking_lot::Mutex::new(Some(paused_tx));
        let resume_rx = parking_lot::Mutex::new(Some(resume_rx));
        let hook: PublicationTestHook = {
            let acquired = Arc::clone(&acquired);
            let pause_once = Arc::clone(&pause_once);
            Arc::new(move |id, point| {
                assert_eq!(id, "same");
                if point == PublicationTestPoint::Acquired {
                    acquired.fetch_add(1, Ordering::SeqCst);
                }
                if point == PublicationTestPoint::AfterWalVersionMap
                    && !pause_once.swap(true, Ordering::SeqCst)
                {
                    paused_tx.lock().take().unwrap().send(()).unwrap();
                    resume_rx.lock().take().unwrap().recv().unwrap();
                }
            })
        };
        idx.set_publication_test_hook(Some(hook));

        let put = {
            let idx = Arc::clone(&idx);
            tokio::spawn(async move {
                idx.index_document_with_version(
                    Some("same".into()),
                    json!({"state": "put"}),
                    Some(initial.seq_no),
                    Some(1),
                )
                .await
            })
        };
        tokio::task::spawn_blocking(move || paused_rx.recv().unwrap())
            .await
            .unwrap();
        assert_eq!(acquired.load(Ordering::SeqCst), 1);

        let (queued_tx, queued_rx) = std::sync::mpsc::sync_channel(1);
        let queued_tx = Arc::new(parking_lot::Mutex::new(Some(queued_tx)));
        idx.write_publication.set_before_mutex_await_hook({
            let queued_tx = Arc::clone(&queued_tx);
            Some(Arc::new(move |id| {
                assert_eq!(id, "same");
                queued_tx.lock().take().unwrap().send(()).unwrap();
            }))
        });
        let delete = {
            let idx = Arc::clone(&idx);
            tokio::spawn(async move { idx.delete_document_versioned("same", None, None).await })
        };
        tokio::task::spawn_blocking(move || queued_rx.recv().unwrap())
            .await
            .unwrap();
        idx.write_publication.set_before_mutex_await_hook(None);
        assert_eq!(
            acquired.load(Ordering::SeqCst),
            1,
            "delete acquired the same key while PUT was paused after WAL/VM"
        );

        resume_tx.send(()).unwrap();
        let put = put.await.unwrap().unwrap();
        let delete = delete.await.unwrap().unwrap();
        idx.set_publication_test_hook(None);

        assert_eq!(put.version, 2);
        assert!(delete.found);
        assert_eq!(delete.version, 3);
        assert!(delete.seq_no > put.seq_no);
        assert!(idx.get_document("same").await.unwrap().is_none());
        assert_eq!(acquired.load(Ordering::SeqCst), 2);
