    #[tokio::test]
    async fn sync_raw_cross_batch_overwrite_is_single_and_durable() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("sync-raw-overwrite", Schema::empty())
            .unwrap();
        let idx = engine.get_index("sync-raw-overwrite").unwrap();
        idx.index_batch_sync_raw(raw_test_docs(&[(
            "same-id",
            br#"{"revision":1,"tag":"obsolete"}"#,
        )]))
        .unwrap();
        idx.flush().await.unwrap();
        idx.index_batch_sync_raw(raw_test_docs(&[(
            "same-id",
            br#"{"revision":2,"tag":"current"}"#,
        )]))
        .unwrap();
        let expected = json!({"revision": 2, "tag": "current"});
        assert_eq!(
            idx.get_document("same-id").await.unwrap().as_ref(),
            Some(&expected)
        );
        let request = SearchRequest {
            query: QueryNode::Match {
                field: "tag".to_owned(),
                query: "current".to_owned(),
                operator: Default::default(),
                analyzer: None,
                boost: None,
                minimum_should_match: None,
                lenient: false,
            },
            ..SearchRequest::default()
        };
        let obsolete_request = SearchRequest {
            query: QueryNode::Match {
                field: "tag".to_owned(),
                query: "obsolete".to_owned(),
                operator: Default::default(),
                analyzer: None,
                boost: None,
                minimum_should_match: None,
                lenient: false,
            },
            ..SearchRequest::default()
        };
        let aggregate_request = SearchRequest {
            query: QueryNode::MatchAll,
            size: 0,
            aggs: Some(json!({
                "tags": {"terms": {"field": "tag"}},
                "revision_cardinality": {"cardinality": {"field": "revision"}},
                "max_revision": {"max": {"field": "revision"}}
            })),
            ..SearchRequest::default()
        };
        assert_eq!(
            idx.memtable.doc_count(),
            1,
            "cross-call overwrite must leave one live memtable entry"
        );
        // Ordinary sync raw ingest defers lexical analysis until flush. The
        // disk-old/memory-new overlap must nevertheless hide stale postings;
        // exact source, logical count, and aggregations use revision 2.
        assert_eq!(idx.search(&obsolete_request).await.unwrap().total.value, 0);
        let aggregate = idx.search(&aggregate_request).await.unwrap();
        assert_eq!(aggregate.total.value, 1);
        let aggs = aggregate.aggs.unwrap();
        assert_eq!(aggs["revision_cardinality"]["value"], 1);
        assert_eq!(aggs["max_revision"]["value"], 2.0);
        assert_eq!(aggs["tags"]["buckets"].as_array().unwrap().len(), 1);
        assert_eq!(aggs["tags"]["buckets"][0]["key"], "current");
        drop(idx);
        drop(engine);

        // Revision 2 exists only in WAL/memory here. Restart must replay it
        // over the durable revision-1 segment without exposing stale terms or
        // double-counting the logical document.
        let reopened = crate::Engine::new({
            let mut config = Config::default();
            config.server.data_dir = dir.path().to_string_lossy().into_owned();
            config
        })
        .unwrap();
        let idx = reopened.get_index("sync-raw-overwrite").unwrap();
        assert_eq!(
            idx.get_document("same-id").await.unwrap().as_ref(),
            Some(&expected)
        );
        assert_eq!(idx.search(&request).await.unwrap().total.value, 1);
        assert_eq!(idx.search(&obsolete_request).await.unwrap().total.value, 0);
        let aggregate = idx.search(&aggregate_request).await.unwrap();
        assert_eq!(aggregate.total.value, 1);
        assert_eq!(aggregate.aggs.unwrap()["max_revision"]["value"], 2.0);
        idx.flush().await.unwrap();
        drop(idx);
        drop(reopened);

        // The same invariants must survive publication of revision 2 and a
        // second restart.
        let reopened_after_second_flush = crate::Engine::new({
            let mut config = Config::default();
            config.server.data_dir = dir.path().to_string_lossy().into_owned();
            config
        })
        .unwrap();
        let idx = reopened_after_second_flush
            .get_index("sync-raw-overwrite")
            .unwrap();
        assert_eq!(
            idx.get_document("same-id").await.unwrap().as_ref(),
            Some(&expected)
        );
        assert_eq!(idx.search(&request).await.unwrap().total.value, 1);
        assert_eq!(idx.search(&obsolete_request).await.unwrap().total.value, 0);
        let aggregate = idx.search(&aggregate_request).await.unwrap();
        assert_eq!(aggregate.total.value, 1);
        let aggs = aggregate.aggs.unwrap();
        assert_eq!(aggs["revision_cardinality"]["value"], 1);
        assert_eq!(aggs["max_revision"]["value"], 2.0);
        assert_eq!(aggs["tags"]["buckets"].as_array().unwrap().len(), 1);
        assert_eq!(aggs["tags"]["buckets"][0]["key"], "current");
    }
}

#[cfg(test)]
mod flush_memory_integration_tests {
    use super::*;
    use crate::ingest_memory::{Category, Ledger, Measurement};
    use serde_json::json;
    struct PublisherRelease(Option<std::sync::mpsc::SyncSender<()>>);
    impl PublisherRelease {
        fn release(&mut self) {
            if let Some(tx) = self.0.take() {
                let _ = tx.send(());
            }
        }
    }
    impl Drop for PublisherRelease {
        fn drop(&mut self) {
            self.release();
        }
    }

    async fn run_flush_memory_case(name: &'static str, inject_error: bool) {
        let ledger: &'static Ledger = Box::leak(Box::new(Ledger::new()));
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index(name, Schema::empty()).unwrap();
        let idx = engine.get_index(name).unwrap();
        idx.index_document(Some("doc".into()), json!({"body": "retained"}))
            .await
            .unwrap();
        let bytes_before_flush = idx.memtable_bytes();
        assert!(bytes_before_flush > 0);

        // `entered` fires from inside the flush finalize's `spawn_blocking`;
        // wait for it on the runtime (see `await_publication_barrier`).
        let (entered_tx, entered_rx) = tokio::sync::oneshot::channel::<()>();
        let (release_tx, release_rx) = std::sync::mpsc::sync_channel(1);
        let mut publisher_release = PublisherRelease(Some(release_tx));
        let entered_tx = parking_lot::Mutex::new(Some(entered_tx));
        let release_rx = parking_lot::Mutex::new(Some(release_rx));
        let hook = FlushPublisherTestHook {
            callback: Arc::new(move || {
                let _ = entered_tx.lock().take().unwrap().send(());
                let _ = release_rx.lock().take().unwrap().recv();
                inject_error
            }),
            after_warm: None,
            ledger,
            target_memtable: Arc::as_ptr(&idx.memtable) as usize,
            bypass_finalize_gate: false,
            before_blocking_spawn: None,
        };

        let flush = {
            let idx = Arc::clone(&idx);
            tokio::spawn(FLUSH_PUBLISHER_TEST_HOOK.scope(hook, async move { idx.flush().await }))
        };
        await_publication_barrier(entered_rx, "entered").await;
        // #1015: the drain is a freeze — the docs stay resident and charged
        // to the memtable aggregate for the whole build, and the
        // flush-pipeline gauge stays EMPTY until retire parks the freeing
        // bytes there (the pre-#1015 drain zeroed the memtable immediately
        // and charged FlushDrained for the build's duration).
        assert_eq!(
            idx.memtable_bytes(),
            bytes_before_flush,
            "frozen generations stay charged through the build"
        );
        assert_eq!(
            ledger
                .gauge(Category::FlushDrained, Measurement::Estimated)
                .current,
            0,
            "no flush-pipeline charge until retire"
        );
        publisher_release.release();
        let result = flush.await.unwrap();
        assert_eq!(result.is_err(), inject_error);
        assert_eq!(
            idx.memtable_bytes(),
            if inject_error { bytes_before_flush } else { 0 },
            "retire drops the charge on commit; a failed build keeps it (claim released)"
        );
        assert_eq!(
            ledger
                .gauge(Category::FlushDrained, Measurement::Estimated)
                .current,
            0
        );
    }

    async fn run_post_warm_failure_case(name: &'static str, panic_after_warm: bool) {
        let ledger: &'static Ledger = Box::leak(Box::new(Ledger::new()));
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index(name, Schema::empty()).unwrap();
        let idx = engine.get_index(name).unwrap();
        let doc_id = format!("{name}-doc");
        idx.index_document(Some(doc_id.clone()), json!({"body": "retained", "rank": 7}))
            .await
            .unwrap();

        let shard = idx.memtable.shard_for_dynamic(&doc_id);
        let (field_configs, excluded_fts_fields, dv_skip) = {
            let schema = idx.schema.read().await;
            (
                build_fts_field_configs(&schema.schema, idx.segment_text_analyzer()),
                crate::memtable::fts_excluded_fields(&schema.schema),
                doc_values_skip_set(&schema.schema),
            )
        };
        let mut warm_caches = idx.publish_warm_caches();
        let budget = SegmentHydrationBudget::new(16 * 1024 * 1024);
        warm_caches.budget = Arc::clone(&budget);
        let observed = warm_caches.clone();
        let warmed_id = Arc::new(parking_lot::Mutex::new(None::<String>));
        let callback_id = Arc::clone(&warmed_id);
        let hook = FlushPublisherTestHook {
            callback: Arc::new(|| false),
            after_warm: Some(Arc::new(move |segment_id| {
                *callback_id.lock() = Some(segment_id.to_string());
                assert!(
                    observed.slices.contains_key(segment_id)
                        || observed.dv.contains_key(segment_id),
                    "real publisher did not warm a cache family"
                );
                if panic_after_warm {
                    panic!("injected post-warm panic");
                }
                true
            })),
            ledger,
            target_memtable: Arc::as_ptr(&idx.memtable) as usize,
            bypass_finalize_gate: false,
            before_blocking_spawn: None,
        };

        let result = do_flush_shard(
            shard,
            Arc::clone(&idx.store),
            Arc::clone(&idx.memtable),
            Arc::clone(&idx.collection_publication),
            Arc::clone(&idx.registry),
            idx.data_dir.clone(),
            field_configs,
            excluded_fts_fields,
            dv_skip,
            || {},
            warm_caches,
            idx.name.as_str().to_string(),
            std::time::Duration::from_secs(30),
            Some(hook),
        )
        .await;
        assert!(
            result.is_err(),
            "publisher errors and panics must propagate to the flush caller"
        );
        assert_eq!(
            idx.memtable.doc_count(),
            1,
            "pre-publication failure must restore the drained document"
        );
        let segment_id = warmed_id.lock().clone().expect("warm hook did not run");
        assert!(!idx.stored_slices_cache.contains_key(&segment_id));
        assert!(!idx.dv_cache.contains_key(&segment_id));
        assert!(!idx.stored_value_cache.contains_key(&segment_id));
        assert!(!idx.id_pos_cache.contains_key(&segment_id));
        assert!(!idx.row_seq_cache.contains_key(&segment_id));
        assert!(!idx.decoded_stored_cache.contains_key(&segment_id));
        let prefix = format!("{segment_id}\u{1}");
        assert!(!idx
            .sort_shadow_cache
            .iter()
            .any(|entry| entry.key().starts_with(&prefix)));
        assert_eq!(budget.snapshot().current, 0);
        assert_eq!(budget.snapshot().accounting_errors, 0);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn parallel_real_flushes_route_isolated_ledgers_through_success_and_error() {
        let (success, failure) = tokio::join!(
            run_flush_memory_case("flush-memory-success", false),
            run_flush_memory_case("flush-memory-failure", true),
        );
        assert_eq!((success, failure), ((), ()));
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn real_flush_cleans_warmed_owners_on_post_warm_error_and_panic() {
        run_post_warm_failure_case("flush-post-warm-error", false).await;
        run_post_warm_failure_case("flush-post-warm-panic", true).await;
    }
}

