#[cfg(test)]
mod unwrap_single_clause_643_wrapper_tests {
    use super::*;
    use xerj_query::ast::{BoolOperator, MinShouldMatch, QueryNode};

    fn bare_match() -> QueryNode {
        QueryNode::Match {
            field: "body".into(),
            query: "x".into(),
            operator: BoolOperator::Or,
            analyzer: None,
            boost: None,
            minimum_should_match: None,
            lenient: false,
        }
    }

    fn single_clause_bool() -> QueryNode {
        QueryNode::Bool {
            must: vec![bare_match()],
            should: vec![],
            must_not: vec![],
            filter: vec![],
            minimum_should_match: None,
        }
    }

    /// A `bool` whose only clause is a lone `should` with the given
    /// `minimum_should_match` — the shape #643 gap 1 is about.
    fn single_should_bool(msm: Option<MinShouldMatch>) -> QueryNode {
        QueryNode::Bool {
            must: vec![],
            should: vec![bare_match()],
            must_not: vec![],
            filter: vec![],
            minimum_should_match: msm,
        }
    }

    /// #643: `unwrap_single_clause_bool` must recurse through `function_score`'s
    /// inner query (a score-preserving wrapper), erasing the nested one-clause
    /// bool to the bare clause.
    #[test]
    fn unwrap_recurses_through_function_score() {
        let q = QueryNode::FunctionScore {
            query: Box::new(single_clause_bool()),
            functions: vec![],
            score_mode: Default::default(),
            boost_mode: Default::default(),
            max_boost: None,
        };
        match unwrap_single_clause_bool(q) {
            QueryNode::FunctionScore { query, .. } => assert!(
                matches!(*query, QueryNode::Match { .. }),
                "the single-clause bool inside function_score must be erased to \
                 the bare clause, got {:?}",
                query
            ),
            other => panic!("function_score wrapper must be preserved, got {:?}", other),
        }
    }

    /// #643: same for every disjunct of a `dis_max`.
    #[test]
    fn unwrap_recurses_through_dis_max() {
        let q = QueryNode::DisMax {
            queries: vec![single_clause_bool()],
            tie_breaker: 0.0,
        };
        match unwrap_single_clause_bool(q) {
            QueryNode::DisMax { queries, .. } => {
                assert_eq!(queries.len(), 1);
                assert!(
                    matches!(queries[0], QueryNode::Match { .. }),
                    "the single-clause bool inside dis_max must be erased, got {:?}",
                    queries[0]
                );
            }
            other => panic!("dis_max wrapper must be preserved, got {:?}", other),
        }
    }

    /// #643 (gap 1): a lone `should` whose `minimum_should_match` is a
    /// `Percentage` that resolves to 1 is the clause-required shape Lucene
    /// collapses to the bare clause, so it must unwrap exactly like
    /// `Fixed(1)`/`None`. msm resolution is `max(1, floor(len * pct / 100))`,
    /// so for the single clause (`len == 1`) every `pct < 200` resolves to 1
    /// (`floor(1 * 199 / 100) == 1`, `max(1, 0) == 1` at `pct == 0`).
    #[test]
    fn unwrap_collapses_lone_should_with_percentage_msm_resolving_to_one() {
        for pct in [0u32, 1, 50, 100, 150, 199] {
            let unwrapped = unwrap_single_clause_bool(single_should_bool(Some(
                MinShouldMatch::Percentage(pct),
            )));
            assert!(
                matches!(unwrapped, QueryNode::Match { .. }),
                "a lone should with {pct}% msm resolves to 1 required and must erase \
                 to the bare clause, got {unwrapped:?}",
            );
        }
    }

    /// #643 (gap 1): a `Percentage` that resolves to >= 2 (`pct >= 200`, since
    /// `floor(1 * 200 / 100) == 2`) requires 2 of the single clause — the bool
    /// matches NOTHING, unlike the bare clause — so it must stay wrapped
    /// (strictly conservative). The parser puts no upper cap on `pct`, so
    /// `"200%"` is reachable.
    #[test]
    fn unwrap_keeps_lone_should_wrapped_when_percentage_msm_exceeds_the_clause_count() {
        for pct in [200u32, 250, 400] {
            let unwrapped = unwrap_single_clause_bool(single_should_bool(Some(
                MinShouldMatch::Percentage(pct),
            )));
            assert!(
                matches!(unwrapped, QueryNode::Bool { .. }),
                "a lone should with {pct}% msm resolves to >= 2 over 1 clause (matches \
                 nothing) and must stay wrapped, got {unwrapped:?}",
            );
        }
    }

    /// #643 (gap 1): `Field`/`Script` msm resolve only at query time (a per-doc
    /// field value or a script result) and can exceed the clause count, so a
    /// static rewrite cannot prove they resolve to 1 — they stay wrapped,
    /// conservatively (the same `_ => false` fall-through as any un-erasable
    /// shape).
    #[test]
    fn unwrap_keeps_lone_should_wrapped_for_query_time_msm() {
        let field = unwrap_single_clause_bool(single_should_bool(Some(MinShouldMatch::Field(
            "req".into(),
        ))));
        assert!(
            matches!(field, QueryNode::Bool { .. }),
            "a Field msm is unresolvable at rewrite time and must stay wrapped, got {field:?}",
        );
        let script = unwrap_single_clause_bool(single_should_bool(Some(MinShouldMatch::Script {
            source: "params.num_terms".into(),
            params: None,
        })));
        assert!(
            matches!(script, QueryNode::Bool { .. }),
            "a Script msm is unresolvable at rewrite time and must stay wrapped, got {script:?}",
        );
    }
}

#[cfg(test)]
thread_local! {
    /// #577 fail-before instrument: the high-water mark of `all_hits.len()`
    /// reached inside the `residual_gate` per-segment loop.
    pub(crate) static RESIDUAL_HITS_PEAK: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
    /// #892 fail-before instrument: how many segments the search answered
    /// from the inverted index (`fts_handled`) and how many it answered by
    /// parsing their stored section. Which route a request took is invisible
    /// from the response — the hits, the total and the ordering contract are
    /// the same either way — so this is what a test can assert on.
    pub(crate) static SEG_FTS_HANDLED: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
    pub(crate) static SEG_STORED_SCANS: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

#[cfg(test)]
mod residual_gate_trim_577_tests {
    use super::*;
    use serde_json::json;

    /// #577: the `residual_gate` pass runs with `fts_cap == usize::MAX`, so a
    /// non-selective non-projectable filter (a numeric `range`) alongside an FTS
    /// scoring clause (`match`) must NOT accumulate O(matches) `Hit`s — it eager-
    /// trims to the page cap. Fail-before: with the trim reverted, the peak is
    /// O(matches) (~N); with the fix it stays ~2·materialisation_limit. Page
    /// and count are unchanged either way.
    #[tokio::test]
    async fn residual_gate_bounds_all_hits_to_the_page_cap() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("residual-577", Schema::empty())
            .unwrap();
        let idx = engine.get_index("residual-577").unwrap();

        const N: usize = 2000;
        for i in 0..N {
            idx.index_document(Some(format!("d{i}")), json!({"body": "alpha beta", "n": i}))
                .await
                .unwrap();
        }
        idx.flush().await.unwrap();

        RESIDUAL_HITS_PEAK.with(|c| c.set(0));
        // bool{ must:[match body:alpha — FTS scoring], filter:[range n>=0 — not
        // FTS-projectable, triggers the residual gate] }; every doc matches both.
        let req = xerj_query::parse_request(&json!({
            "size": 10,
            "query": {"bool": {
                "must": [{"match": {"body": "alpha"}}],
                "filter": [{"range": {"n": {"gte": 0}}}]
            }}
        }))
        .unwrap();
        let res = idx.search(&req).await.unwrap();

        assert_eq!(res.total.value, N as u64, "every doc matches match + range");
        assert_eq!(res.hits.len(), 10, "page returns size:10");
        let peak = RESIDUAL_HITS_PEAK.with(|c| c.get());
        assert!(
            peak > 0,
            "the residual_gate path must have run for this query (peak={peak})"
        );
        // For this size:10/from:0 query over a flushed, memtable-empty index the
        // fast-path re-bind (`materialisation_limit = from + size`) applies, so
        // the cap is 10 and the eager trim fires at > 20, giving a real peak of
        // ~21. The `<= 513` bound below is a deliberately loose ceiling (it also
        // covers the general `(from+size+100).max(256)` cap), still far under the
        // no-trim peak of N = 2000 — the assertion is what discriminates the fix.
        assert!(
            peak <= 513,
            "residual survivors must stay O(page cap), not O(matches): peak={peak} (N={N})"
        );
    }
}

#[cfg(test)]
mod pinned_knn_fts_892_tests {
    use super::*;
    use serde_json::json;

    /// #892: a `knn` clause beside a `query` must be answered from the
    /// INVERTED INDEX, not by parsing every stored document of every segment.
    ///
    /// #825/#879 made this shape CORRECT by pre-executing the vector leg and
    /// splicing its top-k back in as `Constant{score, Ids{[id]}}` pinned
    /// clauses. `Ids` has no FTS projection — `_id` is not a term — so the
    /// projection's `should` loop `?`-aborted, `fts_query` came back `None`,
    /// and every segment fell to `scan_stored_section_into`.
    ///
    /// That route is not merely slow, and this test asserts the part that is
    /// USER-VISIBLE. The stored scan admits documents in STORED-LAYOUT order
    /// and, once `all_hits` reaches `materialisation_limit`, materialises
    /// nothing further — it `continue`s to keep counting, with no score
    /// comparison (see the cap in `scan_stored_section_into`). So on a corpus
    /// with more lexical matches than the page cap, the documents reached by
    /// BOTH halves — the ones the #825 contract scores `query_score +
    /// knn_score` and puts at the top — never enter the page at all if they
    /// sit late in the segment. `hits.total` stays exact; the page is wrong.
    ///
    /// FAIL-BEFORE (watched): with `pinned_probe` forced to `None` in
    /// `search_inner` — the pre-#892 behaviour — the page is 10 lexical-only
    /// documents and the assertion below reports the both-halves documents
    /// missing. `hits.total` is 407 either way.
    #[tokio::test]
    async fn pinned_knn_hybrid_is_answered_from_the_inverted_index() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("body", FieldType::Text))
            .unwrap();
        let mut vector = FieldConfig::new("v", FieldType::Vector);
        vector.options.dimensions = Some(2);
        schema.add_field(vector).unwrap();
        engine.create_index("hy892", schema).unwrap();
        let idx = engine.get_index("hy892").unwrap();

        // 1200 documents. Every third carries the lexical probe term with
        // IDENTICAL text (same tf, same field length → identical BM25), so
        // 400 lexical matches — comfortably more than the page cap, which is
        // what makes the stored scan's layout-ordered admission observable.
        // Vectors fan from [0,1] to [1,0], so the query vector [1,0] puts the
        // LAST ten (d1190..d1199) in the k=10 neighbourhood; three of those
        // are also lexical matches (1191, 1194, 1197) and must lead the page
        // in vector order, 1197 first.
        const N: usize = 1200;
        for i in 0..N {
            let body = if i % 3 == 0 {
                "alpha filler"
            } else {
                "beta filler"
            };
            let t = i as f32 / N as f32;
            idx.index_document(
                Some(format!("d{i}")),
                json!({ "body": body, "v": [t, 1.0 - t] }),
            )
            .await
            .unwrap();
        }
        idx.flush().await.unwrap();

        SEG_FTS_HANDLED.with(|c| c.set(0));
        SEG_STORED_SCANS.with(|c| c.set(0));
        let req = xerj_query::parse_request(&json!({
            "size": 10,
            "track_total_hits": true,
            "query": {"bool": {"should": [
                {"match": {"body": "alpha"}},
                {"knn": {"field": "v", "query_vector": [1.0, 0.0], "k": 10,
                         "num_candidates": 100}}
            ]}}
        }))
        .unwrap();
        let res = idx.search(&req).await.unwrap();

        // The union: 400 lexical matches ∪ 10 neighbours, overlapping in
        // three documents. Exact on BOTH routes — the page is what differs.
        assert_eq!(
            res.total.value, 407,
            "hits.total must be the UNION of the lexical half (400) and the \
             vector top-10, which share d1191/d1194/d1197: got {:?}",
            res.total
        );

        let page: Vec<(&str, f32)> = res.hits.iter().map(|h| (h.id.as_str(), h.score)).collect();
        let ids: Vec<&str> = page.iter().map(|(id, _)| *id).collect();
        assert_eq!(
            &ids[..3],
            &["d1197", "d1194", "d1191"],
            "#825/#892: the documents reached by BOTH halves score \
             `query_score + knn_score` and must lead the page, ordered by \
             their vector scores — the stored-doc scan drops them because it \
             admits in layout order and stops materialising at the page cap: \
             page={page:?}"
        );
        assert!(
            page[2].1 > page[3].1,
            "the last both-halves document must still outrank the best \
             lexical-only one: {page:?}"
        );

        // And it came from the index, on every segment.
        let fts = SEG_FTS_HANDLED.with(|c| c.get());
        let scans = SEG_STORED_SCANS.with(|c| c.get());
        assert!(
            fts > 0 && scans == 0,
            "the pinned kNN hybrid must be served by the FTS path on every \
             segment: fts={fts} stored_scans={scans}"
        );
    }

    /// The projection arm in isolation: `pin_knn_clause`'s output lifts to a
    /// `DocScores` leaf carrying the resolved positions and the pinned
    /// scores, and the ids the segment does not hold are simply absent.
    #[test]
    fn pinned_sub_tree_projects_to_a_doc_scores_leaf() {
        let pinned = QueryNode::Bool {
            must: Vec::new(),
            should: vec![
                QueryNode::Constant {
                    score: 0.75,
                    query: Box::new(QueryNode::Ids {
                        values: vec!["a".into()],
                    }),
                },
                QueryNode::Constant {
                    score: 0.25,
                    query: Box::new(QueryNode::Ids {
                        values: vec!["elsewhere".into()],
                    }),
                },
            ],
            filter: vec![QueryNode::Ids {
                values: vec!["a".into(), "elsewhere".into()],
            }],
            must_not: Vec::new(),
            minimum_should_match: Some(MinShouldMatch::Fixed(1)),
        };
        let text_fields: Vec<String> = vec!["body".into()];
        let empty: std::collections::HashSet<String> = std::collections::HashSet::new();

        // Without a resolver the projection declines exactly as it did before
        // #892 — `Ids` is not a term.
        assert!(
            query_node_to_fts_projected(
                &pinned,
                &text_fields,
                &empty,
                &empty,
                SegmentAnalyzerBinding::Standard,
                None,
            )
            .is_none(),
            "no resolver ⇒ the pinned sub-tree must still decline"
        );

        let mut positions: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        positions.insert("a".into(), 7);
        let projected = query_node_to_fts_projected(
            &pinned,
            &text_fields,
            &empty,
            &empty,
            SegmentAnalyzerBinding::Standard,
            Some(PinnedIds::Positions(&positions)),
        )
        .expect("a resolvable pinned sub-tree must project");
        match projected {
            FtsQuery::DocScores(ds) => assert_eq!(
                ds.docs,
                vec![(7u32, 0.75f32)],
                "only the id this segment holds, at its stored position, with \
                 the vector leg's score"
            ),
            other => panic!("expected a DocScores leaf, got {other:?}"),
        }
    }

    /// Guard rails on the shape match: anything that is not what
    /// `pin_knn_clause` emits must NOT be lifted, because the arm skips the
    /// clause-by-clause walk that would otherwise check it.
    #[test]
    fn only_the_pinned_shape_is_lifted() {
        let ids = |v: &str| QueryNode::Ids {
            values: vec![v.into()],
        };
        let pinned_child = |v: &str| QueryNode::Constant {
            score: 1.0,
            query: Box::new(ids(v)),
        };
        // A `must` alongside the pinned disjuncts is not the emitted shape.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: vec![ids("a")],
            should: vec![pinned_child("a")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: None,
        })
        .is_none());
        // A `minimum_should_match` other than 1 changes the match set.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: Vec::new(),
            should: vec![pinned_child("a"), pinned_child("b")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: Some(MinShouldMatch::Fixed(2)),
        })
        .is_none());
        // A duplicate id would be tallied twice by the FTS `should` counter.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: Vec::new(),
            should: vec![pinned_child("a"), pinned_child("a")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: None,
        })
        .is_none());
        // A non-`Constant` disjunct is an ordinary scoring clause.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: Vec::new(),
            should: vec![ids("a")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: None,
        })
        .is_none());
        // The emitted shape itself IS lifted.
        assert_eq!(
            pinned_constant_ids_pairs(&QueryNode::Bool {
                must: Vec::new(),
                should: vec![pinned_child("a"), pinned_child("b")],
                filter: vec![QueryNode::Ids {
                    values: vec!["a".into(), "b".into()]
                }],
                must_not: Vec::new(),
                minimum_should_match: Some(MinShouldMatch::Fixed(1)),
            }),
            Some(vec![("a", 1.0f32), ("b", 1.0f32)])
        );
    }
}

/// #940 — the fused order is total, and a function of the leg lists and the
/// documents' arrival order alone.
///
/// These drive `fuse_rrf`/`fuse_linear` directly, so they exercise the
/// accumulator on every call — the per-index result cache that made repeated
/// in-process requests look stable in the issue's own runs is not in the way.
#[cfg(test)]
mod hybrid_fused_order_tests {
    use super::*;

    fn hit(id: &str, score: f32) -> Hit {
        Hit {
            id: id.to_string(),
            score,
            source: serde_json::json!({ "id": id }),
            seq_no: None,
            version: None,
            sort: Vec::new(),
            explain: None,
            highlight: None,
            matched_queries: Vec::new(),
            passage: None,
        }
    }

    fn ids(hits: &[Hit]) -> Vec<&str> {
        hits.iter().map(|h| h.id.as_str()).collect()
    }

    /// Arrival order used by every test here: the trailing number of the id,
    /// scrambled against `_id` order on purpose (`doc-10` arrives before
    /// `doc-9` but sorts after it as a string) so a test cannot pass by
    /// tying on `_id` alone.
    fn arrival(id: &str) -> u64 {
        id.rsplit('-').next().unwrap().parse().unwrap()
    }

    /// Two disjoint legs of equal weight: the document at rank r of leg A and
    /// the one at rank r of leg B both score exactly `1/(60+r)`. Twelve
    /// structural ties — under the old `HashMap` drain the chance that one
    /// call returns them all in arrival order is 2^-12, and the chance that
    /// 64 calls agree with each other is nil.
    fn disjoint_legs() -> Vec<(Vec<Hit>, f32)> {
        // Leg A holds the ODD arrivals, leg B the EVEN ones, each already in
        // rank order. Scores inside a leg are distinct, as a real leg's are.
        let a: Vec<Hit> = (0..12)
            .map(|r| hit(&format!("doc-{}", 2 * r + 1), 9.0 - r as f32 * 0.5))
            .collect();
        let b: Vec<Hit> = (0..12)
            .map(|r| hit(&format!("doc-{}", 2 * r), 0.99 - r as f32 * 0.01))
            .collect();
        vec![(a, 1.0), (b, 1.0)]
    }

    #[test]
    fn rrf_structural_ties_resolve_by_arrival_order_on_every_call() {
        let legs = disjoint_legs();
        // Rank r → the even arrival (leg B) precedes the odd one (leg A):
        // doc-0, doc-1, doc-2, … — NOT the `_id` order, which would put
        // doc-10 ahead of doc-2.
        let expected: Vec<String> = (0..24).map(|n| format!("doc-{n}")).collect();
        for call in 0..64 {
            let fused = fuse_rrf(&legs, 60, &arrival);
            assert_eq!(
                ids(&fused),
                expected.iter().map(String::as_str).collect::<Vec<_>>(),
                "call {call}: tied fused scores must come back in arrival order"
            );
            // The ties are exact — otherwise this test proves nothing.
            for pair in fused.chunks(2) {
                assert_eq!(
                    pair[0].score.to_bits(),
                    pair[1].score.to_bits(),
                    "fixture must produce EXACT ties, got {} vs {}",
                    pair[0].score,
                    pair[1].score
                );
            }
        }
    }

    /// The symmetric pair the issue names: two documents at swapped ranks
    /// (1,2)/(2,1) both score `1/61 + 1/62`.
    #[test]
    fn rrf_swapped_rank_pair_resolves_by_arrival_order() {
        let legs = vec![
            (vec![hit("doc-7", 3.0), hit("doc-4", 2.0)], 1.0),
            (vec![hit("doc-4", 0.9), hit("doc-7", 0.8)], 1.0),
        ];
        for _ in 0..64 {
            let fused = fuse_rrf(&legs, 60, &arrival);
            assert_eq!(fused[0].score.to_bits(), fused[1].score.to_bits());
            assert_eq!(ids(&fused), ["doc-4", "doc-7"]);
        }
    }

    /// RRF with equal weights is symmetric in its legs, so listing the legs
    /// in the other order must not change the page. This is the property a
    /// rank-derived tie-break ("the earlier-listed leg wins") cannot keep.
    #[test]
    fn rrf_order_does_not_depend_on_how_the_request_lists_its_legs() {
        let legs = disjoint_legs();
        let mut swapped = legs.clone();
        swapped.reverse();
        assert_eq!(
            ids(&fuse_rrf(&legs, 60, &arrival)),
            ids(&fuse_rrf(&swapped, 60, &arrival))
        );
    }

    /// Two documents sharing an arrival key (both unknown to the version map
    /// → `u64::MAX`) still order — by `_id`.
    #[test]
    fn rrf_falls_through_to_id_when_arrival_is_unknown() {
        let legs = vec![
            (vec![hit("zeta", 1.0)], 1.0),
            (vec![hit("alpha", 1.0)], 1.0),
        ];
        for _ in 0..64 {
            let fused = fuse_rrf(&legs, 60, &|_| u64::MAX);
            assert_eq!(ids(&fused), ["alpha", "zeta"]);
        }
    }

    /// `fuse_linear` had the same accumulator and the same score-only sort. A
    /// constant-score leg normalises to 0.0 for every document it returns, so
    /// the whole list ties.
    #[test]
    fn linear_constant_score_leg_resolves_by_arrival_order_on_every_call() {
        let constant: Vec<Hit> = [5, 11, 2, 9, 10, 3, 8, 1]
            .iter()
            .map(|n| hit(&format!("doc-{n}"), 1.0))
            .collect();
        let legs = vec![(constant, 1.0)];
        for call in 0..64 {
            let fused = fuse_linear(&legs, &arrival);
            assert!(fused.iter().all(|h| h.score == 0.0));
            assert_eq!(
                ids(&fused),
                ["doc-1", "doc-2", "doc-3", "doc-5", "doc-8", "doc-9", "doc-10", "doc-11"],
                "call {call}"
            );
        }
    }

    /// A NaN leg score must neither abort the sort nor float to the top of
    /// the page (`f32::total_cmp` alone would rank a positive NaN FIRST).
    #[test]
    fn linear_nan_score_sorts_last_and_does_not_panic() {
        let legs = vec![(
            vec![hit("doc-1", 4.0), hit("doc-2", f32::NAN), hit("doc-3", 1.0)],
            1.0,
        )];
        let fused = fuse_linear(&legs, &arrival);
        assert_eq!(ids(&fused), ["doc-1", "doc-3", "doc-2"]);
        assert!(fused[2].score.is_nan());
    }

    /// Fusion still fuses: a document both legs rank highly beats one that
    /// only one leg found, and duplicates collapse to one hit.
    #[test]
    fn rrf_still_ranks_by_fused_score_first() {
        let legs = vec![
            (vec![hit("doc-9", 3.0), hit("doc-1", 2.0)], 1.0),
            (vec![hit("doc-9", 0.9), hit("doc-2", 0.8)], 1.0),
        ];
        let fused = fuse_rrf(&legs, 60, &arrival);
        assert_eq!(ids(&fused), ["doc-9", "doc-1", "doc-2"]);
        assert!(fused[0].score > fused[1].score);
        assert_eq!(fused[1].score.to_bits(), fused[2].score.to_bits());
    }
}

/// #939 — the exact kNN scan ranks addresses and hydrates only the winners.
///
/// The rewrite is meant to be invisible: same documents, same order, same
/// scores to the bit. These tests pin that against `legacy_scan`, a transcript
/// of the scan as it stood before the change (clone every live source, clone
/// it again for the filter, re-walk the JSON numbers per passage), so the
/// equivalence is checked in CI and not only by a one-off benchmark.
#[cfg(test)]
mod exact_scan_hydration_tests {
    use super::*;
    use crate::Engine;
    use tempfile::TempDir;

    const DIM: usize = 8;

    fn engine(dir: &TempDir) -> Engine {
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        Engine::new(config).expect("engine")
    }

    /// One ingest shard: a flush writes one segment, not one per shard.
    fn single_shard_engine(dir: &TempDir) -> Engine {
        let mut config = xerj_common::config::Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        config.engine.ingest_shards = 1;
        Engine::new(config).expect("engine")
    }

    /// `compute_vector_similarity` as it stood before #939, verbatim. The
    /// oracle must not share code with what it checks.
    fn legacy_similarity(sim: &str, a: &[f32], b: &[f32]) -> f32 {
        let dot: f64 = a
            .iter()
            .zip(b.iter())
            .map(|(x, y)| (*x as f64) * (*y as f64))
            .sum();
        let result: f64 = match sim {
            "l2_norm" => {
                let sq: f64 = a
                    .iter()
                    .zip(b.iter())
                    .map(|(x, y)| {
                        let d = (*x as f64) - (*y as f64);
                        d * d
                    })
                    .sum();
                1.0 / (1.0 + sq)
            }
            "dot_product" => (1.0 + dot) / 2.0,
            "max_inner_product" => {
                if dot < 0.0 {
                    1.0 / (1.0 - dot)
                } else {
                    dot + 1.0
                }
            }
            _ => {
                let na: f64 = a
                    .iter()
                    .map(|x| (*x as f64) * (*x as f64))
                    .sum::<f64>()
                    .sqrt();
                let nb: f64 = b
                    .iter()
                    .map(|x| (*x as f64) * (*x as f64))
                    .sum::<f64>()
                    .sqrt();
                let denom = na * nb;
                let cos = if denom > 0.0 { dot / denom } else { 0.0 };
                (1.0 + cos) / 2.0
            }
        };
        result as f32
    }

    fn json_vector(value: &Value) -> Option<Vec<f32>> {
        match value {
            Value::Array(a) => Some(
                a.iter()
                    .filter_map(|v| v.as_f64().map(|f| f as f32))
                    .collect(),
            ),
            _ => None,
        }
    }

    /// The exact scan as it stood before #939. Returns the ranked, `k`-capped
    /// pool as `(id, score bits, passage ordinal, source)`.
    #[allow(clippy::too_many_arguments)]
    async fn legacy_scan(
        idx: &Index,
        field: &str,
        query_vec: &[f32],
        k: usize,
        filter: Option<&QueryNode>,
        similarity: &str,
        boost: Option<f32>,
        min_similarity: Option<f32>,
    ) -> Vec<(String, u32, Option<u32>, Value)> {
        let schema = idx.schema().await;
        let mut candidates: Vec<(String, Value)> = idx.memtable.all_docs_with_sources();
        let snap = idx.store.snapshot();
        let mut seen: HashSet<String> = candidates.iter().map(|(id, _)| id.clone()).collect();
        for meta in snap.segments.iter() {
            let Some(docs) = idx.stored_values_for(&meta.id) else {
                continue;
            };
            for doc in docs.iter() {
                let Some(id) = doc.get("_id").and_then(Value::as_str).map(str::to_string) else {
                    continue;
                };
                if let Some(ver) = idx.store.version_map.get(&id) {
                    if ver.deleted {
                        continue;
                    }
                    if let Some(doc_seq) = doc.get("_seq_no").and_then(Value::as_u64) {
                        if doc_seq < ver.seq_no {
                            continue;
                        }
                    }
                }
                if !seen.insert(id.clone()) {
                    continue;
                }
                let src = doc.get("_source").cloned().unwrap_or_else(|| {
                    let mut d = doc.clone();
                    if let Some(obj) = d.as_object_mut() {
                        obj.remove("_id");
                    }
                    d
                });
                candidates.push((id, src));
            }
        }
        let passes = |id: &str, src: &Value| -> bool {
            let Some(f) = filter else {
                return true;
            };
            let mut src_with_id = src.clone();
            if let Some(obj) = src_with_id.as_object_mut() {
                obj.insert("_id".to_string(), Value::String(id.to_string()));
            }
            doc_matches_query_typed(f, &src_with_id, &schema)
        };
        let use_sq8 = lookup_vector_quantization(&schema, field).as_deref() == Some("scalar8");
        let mut scored: Vec<(String, f32, Value, Option<u32>)> = Vec::new();
        if use_sq8 {
            let normalize = !matches!(similarity, "l2_norm" | "dot_product" | "max_inner_product");
            let dim = query_vec.len();
            let mut cand: Vec<(String, Value, Vec<f32>)> = Vec::new();
            for (id, src) in candidates {
                if !passes(&id, &src) {
                    continue;
                }
                let Some(mut doc_vec) = get_field_value(&src, field).as_ref().and_then(json_vector)
                else {
                    continue;
                };
                if doc_vec.len() != dim {
                    continue;
                }
                if normalize {
                    l2_normalize_vec(&mut doc_vec);
                }
                cand.push((id, src, doc_vec));
            }
            let params = Sq8Params::fit_borrowed(cand.iter().map(|(_, _, v)| v.as_slice()), dim);
            let mut codes = vec![0u8; dim];
            let mut decoded = vec![0.0f32; dim];
            for (id, src, v) in cand {
                params.encode_into(&v, &mut codes);
                params.decode_into(&codes, &mut decoded);
                scored.push((
                    id,
                    legacy_similarity(similarity, query_vec, &decoded),
                    src,
                    None,
                ));
            }
        } else {
            let chunk_field = format!("{field}_chunks");
            for (id, src) in candidates {
                if !passes(&id, &src) {
                    continue;
                }
                let (score, ordinal) = if let Some(Value::Array(chunks)) =
                    get_field_value(&src, &chunk_field)
                {
                    let mut best: Option<(f32, u32)> = None;
                    for (chunk_position, cv) in chunks.iter().enumerate() {
                        let Some(dv) = json_vector(cv) else {
                            continue;
                        };
                        if dv.len() != query_vec.len() {
                            continue;
                        }
                        let s = legacy_similarity(similarity, query_vec, &dv);
                        if best.is_none_or(|(current, _)| s > current) {
                            best = Some((s, chunk_position as u32));
                        }
                    }
                    match best {
                        Some((score, ordinal)) => (score, Some(ordinal)),
                        None => continue,
                    }
                } else {
                    let Some(doc_vec) = get_field_value(&src, field).as_ref().and_then(json_vector)
                    else {
                        continue;
                    };
                    if doc_vec.len() != query_vec.len() {
                        continue;
                    }
                    (legacy_similarity(similarity, query_vec, &doc_vec), Some(0))
                };
                scored.push((id, score, src, ordinal));
            }
        }
        if let Some(raw) = min_similarity {
            let cut = raw_similarity_to_score(similarity, raw);
            scored.retain(|(_, score, _, _)| *score >= cut);
        }
        if let Some(b) = boost {
            if (b - 1.0).abs() > f32::EPSILON {
                for (_, score, _, _) in scored.iter_mut() {
                    *score *= b;
                }
            }
        }
        scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        scored.truncate(k.max(1));
        scored
            .into_iter()
            .map(|(id, score, src, ordinal)| (id, score.to_bits(), ordinal, src))
            .collect()
    }

    /// Deterministic pseudo-random unit-ish vectors; no `rand` dependency.
    struct Lcg(u64);
    impl Lcg {
        fn next_f32(&mut self) -> f32 {
            self.0 = self
                .0
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            (((self.0 >> 33) as f64) / ((1u64 << 31) as f64) - 1.0) as f32
        }
        fn vector(&mut self) -> Vec<f32> {
            (0..DIM).map(|_| self.next_f32()).collect()
        }
    }

    fn as_json(vector: &[f32]) -> Value {
        Value::Array(vector.iter().map(|v| Value::from(*v as f64)).collect())
    }

    fn vector_schema(quantization: Option<&str>) -> Schema {
        let mut schema = Schema::empty();
        let mut body = FieldConfig::new("body", FieldType::Text);
        body.options.dimensions = Some(DIM);
        body.options.similarity = Some("cosine".into());
        body.embedding = Some(xerj_common::types::EmbeddingConfig {
            endpoint: None,
            model: None,
            target_field: Some("body_vector".into()),
        });
        schema.add_field(body).unwrap();
        let mut companion = FieldConfig::new("body_vector", FieldType::Vector);
        companion.options.dimensions = Some(DIM);
        companion.options.similarity = Some("cosine".into());
        companion.options.quantization = quantization.map(str::to_string);
        schema.add_field(companion).unwrap();
        schema
            .add_field(FieldConfig::new("tag", FieldType::Keyword))
            .unwrap();
        schema
            .add_field(FieldConfig::new("n", FieldType::Long))
            .unwrap();
        schema
            .add_field(FieldConfig::new("title", FieldType::Text))
            .unwrap();
        schema
    }

    /// A document. Every third is multi-passage; a run of ids shares one
    /// vector so the rank has exact score ties to break.
    fn document(id: usize, rng: &mut Lcg, shared: &[f32]) -> Value {
        let pooled = if (10..16).contains(&id) {
            shared.to_vec()
        } else {
            rng.vector()
        };
        let mut doc = serde_json::json!({
            "title": format!("doc {id} {}", if id.is_multiple_of(4) { "cell" } else { "other" }),
            "tag": format!("t{}", id % 5),
            "n": (id * 37) % 1000,
            "body": format!("body text {id}"),
            "body_vector": as_json(&pooled),
        });
        if id.is_multiple_of(3) {
            let passages: Vec<Value> = (0..2 + id % 4).map(|_| as_json(&rng.vector())).collect();
            doc["body_vector_chunks"] = Value::Array(passages);
        }
        doc
    }

    /// Two segments (the second superseding and deleting part of the first)
    /// plus a live memtable, with every awkward document shape the scan has a
    /// rule for.
    async fn seed(idx: &Arc<Index>) {
        let mut rng = Lcg(0x939);
        let shared = rng.vector();
        for id in 0..150 {
            idx.index_document_prepared(Some(format!("d{id}")), document(id, &mut rng, &shared))
                .await
                .unwrap();
        }
        // Shapes with a rule of their own.
        idx.index_document_prepared(
            Some("malformed-passages".into()),
            serde_json::json!({
                "title": "cell malformed", "tag": "t1", "n": 5, "body": "x",
                "body_vector": as_json(&rng.vector()),
                // ordinal 1 is not a vector, ordinal 3 has the wrong length:
                // both skipped, neither renumbers ordinal 2.
                "body_vector_chunks": [as_json(&rng.vector()), "junk", as_json(&rng.vector()), [1.0, 2.0]],
            }),
        )
        .await
        .unwrap();
        idx.index_document_prepared(
            Some("empty-passages".into()),
            serde_json::json!({
                "title": "cell empty", "tag": "t1", "n": 6, "body": "x",
                "body_vector": as_json(&shared),
                "body_vector_chunks": [],
            }),
        )
        .await
        .unwrap();
        idx.index_document_prepared(
            Some("no-vector".into()),
            serde_json::json!({"title": "cell none", "tag": "t1", "n": 7, "body": "x"}),
        )
        .await
        .unwrap();
        idx.flush().await.unwrap();

        // Second segment: supersede some of the first, delete some, add more.
        for id in (0..150).step_by(9) {
            idx.index_document_prepared(
                Some(format!("d{id}")),
                document(id + 1000, &mut rng, &shared),
            )
            .await
            .unwrap();
        }
        for id in (5..150).step_by(17) {
            idx.delete_document(&format!("d{id}")).await.unwrap();
        }
        for id in 150..260 {
            idx.index_document_prepared(Some(format!("d{id}")), document(id, &mut rng, &shared))
                .await
                .unwrap();
        }
        idx.flush().await.unwrap();

        // Live memtable over both: updates of flushed documents and new ones.
        for id in (3..260).step_by(31) {
            idx.index_document_prepared(
                Some(format!("d{id}")),
                document(id + 2000, &mut rng, &shared),
            )
            .await
            .unwrap();
        }
        for id in 260..290 {
            idx.index_document_prepared(Some(format!("d{id}")), document(id, &mut rng, &shared))
                .await
                .unwrap();
        }
        assert!(
            idx.store.snapshot().segments.len() >= 2,
            "the fixture needs flushed segments beside the memtable"
        );
    }

    fn filters() -> Vec<(&'static str, Option<QueryNode>)> {
        let term = QueryNode::Term {
            field: "tag".into(),
            value: Value::from("t3"),
            boost: None,
        };
        let range = QueryNode::Range {
            field: "n".into(),
            gte: Some(Value::from(100)),
            gt: None,
            lte: None,
            lt: Some(Value::from(800)),
            boost: None,
            lenient: false,
        };
        vec![
            ("none", None),
            (
                "ids",
                Some(QueryNode::Ids {
                    values: (0..290).step_by(7).map(|id| format!("d{id}")).collect(),
                }),
            ),
            ("term", Some(term.clone())),
            (
                "bool(term AND range, NOT exists)",
                Some(QueryNode::Bool {
                    must: Vec::new(),
                    should: Vec::new(),
                    filter: vec![term.clone(), range.clone()],
                    must_not: vec![QueryNode::Exists {
                        field: "body_vector_chunks".into(),
                    }],
                    minimum_should_match: None,
                }),
            ),
            (
                // Reads the VECTOR fields themselves: the projection must
                // carry them rather than assume a filter never looks.
                "exists(vector)",
                Some(QueryNode::Exists {
                    field: "body_vector".into(),
                }),
            ),
            (
                // Not on the projection whitelist: takes the full-source path.
                "match (full source)",
                Some(QueryNode::Match {
                    field: "title".into(),
                    query: "cell".into(),
                    operator: xerj_query::ast::BoolOperator::Or,
                    analyzer: None,
                    boost: None,
                    minimum_should_match: None,
                    lenient: false,
                }),
            ),
        ]
    }

    async fn assert_scan_matches_legacy(idx: &Arc<Index>, field: &str, sq8: bool) {
        let mut rng = Lcg(0xBEEF);
        let mut compared = 0usize;
        let mut saw_later_passage = false;
        let similarities: &[&str] = if sq8 {
            &["cosine", "l2_norm"]
        } else {
            &["cosine", "dot_product", "l2_norm", "max_inner_product"]
        };
        for _ in 0..4 {
            let query = rng.vector();
            for similarity in similarities {
                for (filter_name, filter) in filters() {
                    for (k, boost, min_similarity) in [
                        (1usize, None, None),
                        (10, Some(2.5f32), None),
                        (25, None, Some(0.1f32)),
                        (1000, None, None),
                    ] {
                        let expected = legacy_scan(
                            idx,
                            field,
                            &query,
                            k,
                            filter.as_ref(),
                            similarity,
                            boost,
                            min_similarity,
                        )
                        .await;
                        let request = SearchRequest {
                            size: k,
                            fields: vec![PASSAGE_RESPONSE_FIELD.into()],
                            ..SearchRequest::default()
                        };
                        let got = idx
                            .run_knn_brute_force(
                                &request,
                                field,
                                &query,
                                k,
                                filter.clone().map(Box::new),
                                similarity,
                                boost,
                                min_similarity,
                            )
                            .await
                            .unwrap();
                        let context = format!("similarity={similarity} filter={filter_name} k={k}");
                        assert_eq!(got.total.value, expected.len() as u64, "total: {context}");
                        assert_eq!(
                            got.hits
                                .iter()
                                .map(|h| (h.id.clone(), h.score.to_bits()))
                                .collect::<Vec<_>>(),
                            expected
                                .iter()
                                .map(|(id, bits, _, _)| (id.clone(), *bits))
                                .collect::<Vec<_>>(),
                            "ids, order and score BITS: {context}"
                        );
                        for (hit, (_, _, ordinal, source)) in got.hits.iter().zip(&expected) {
                            // Hydrated from the right document: the user
                            // fields are the legacy scan's, value for value.
                            for key in ["title", "tag", "n", "body"] {
                                assert_eq!(
                                    hit.source.get(key),
                                    source.get(key),
                                    "{key}: {context}"
                                );
                            }
                            if let Some(ordinal) = ordinal {
                                saw_later_passage |= *ordinal > 0;
                            }
                        }
                        compared += got.hits.len();
                    }
                }
            }
        }
        assert!(
            compared > 1000,
            "the comparison must have teeth: {compared}"
        );
        if !sq8 {
            assert!(
                saw_later_passage,
                "no query was won by a passage past the first"
            );
        }
    }

