            for (n, doc) in docs.iter().enumerate() {
                let id = format!("id-{n}");
                assert_eq!(
                    plan.matches(filter, &id, doc, &schema),
                    KnnFilterPlan::FullSource.matches(filter, &id, doc, &schema),
