    fn string_relational_is_lexicographic() {
        let doc = json!({"color": "blue"});
        assert!(eval_bool("doc['color'].value < 'red'", &doc));
        assert!(eval_bool("doc['color'].value <= 'blue'", &doc));
        assert!(!eval_bool("doc['color'].value > 'red'", &doc));
        assert!(eval_bool("'9' > '10'", &doc)); // lexicographic, not numeric
    }

