            let v = eval_painless(src, &ctx(&doc, &params, 0.0))
                .unwrap_or_else(|e| panic!("the null-guard idiom must not error on {doc}: {e}"));
            assert_eq!(v.as_f64().unwrap(), expected, "doc {doc}");
        }
    }

