        // `params` is a real `Map<String, Object>` in Painless, so a key
        // that wasn't supplied reads as null and comparing it to null is an
        // ordinary reference comparison — unlike `doc[...]`, which throws.
        let doc = json!({});

        let empty = json!({});
        let v = eval_painless("params.y == null", &ctx(&doc, &empty, 0.0))
            .expect("a params null guard must evaluate, not error");
        assert!(v.as_bool(), "missing param: `== null` must be true");

        let supplied = json!({"y": 3});
        let v = eval_painless("params.y == null", &ctx(&doc, &supplied, 0.0))
            .expect("a params null guard must evaluate, not error");
        assert!(!v.as_bool(), "supplied param: `== null` must be false");

        // `!=` is the same comparison inverted, and a present-but-null value
        // is indistinguishable from an absent one, as in ES.
        let explicit_null = json!({"y": null});
        let v = eval_painless("params.y != null", &ctx(&doc, &explicit_null, 0.0)).unwrap();
        assert!(!v.as_bool());
    }

    #[test]
    fn genuinely_invalid_arithmetic_still_errors() {
        let doc = json!({});
        let params = json!({"obj": {"a": 1}});
        // Null-awareness is scoped to `==`/`!=`; nothing else got looser, so
        // the fail-closed property the script query depends on is intact.
        for src in [
            "'abc' - params.obj",
            "params.missing + 1",
            "params.missing > 0",
            "doc['nope'].value * 2",
            "doc['nope'].value >= 0",
            "-params.missing",
        ] {
            let r = eval_painless(src, &ctx(&doc, &params, 0.0));
            assert!(r.is_err(), "`{src}` must still error, got {:?}", r);
        }
    }

    // ── Compiled-script cache ─────────────────────────────────────────────────
    // The cache is thread-local, and each `#[test]` gets its own thread, so
    // every assertion below observes only what its own test evaluated.

    /// `(entries, src_bytes, actual bytes held)` for the calling thread.
    fn cache_stats() -> (usize, usize, usize) {
        SCRIPT_CACHE.with(|c| {
            let c = c.borrow();
            (
                c.entries.len(),
                c.src_bytes,
                c.entries.keys().map(|k| k.len()).sum(),
            )
        })
    }

    #[test]
    fn compiled_script_cache_is_bounded_by_entry_count() {
        let doc = json!({});
        let params = json!({});
        // Far more distinct sources than the cache may retain. Each is tiny,
        // so the entry-count bound is the one under test.
        for i in 0..(MAX_SCRIPT_CACHE_ENTRIES * 8) {
            let src = format!("{i} + 1");
            eval_painless(&src, &ctx(&doc, &params, 0.0)).unwrap();
        }
        let (entries, src_bytes, actual) = cache_stats();
        assert!(
            entries <= MAX_SCRIPT_CACHE_ENTRIES,
            "cache grew to {entries} entries, bound is {MAX_SCRIPT_CACHE_ENTRIES}"
        );
        assert!(
            src_bytes <= MAX_SCRIPT_CACHE_SRC_BYTES,
            "cache holds {src_bytes} source bytes, bound is {MAX_SCRIPT_CACHE_SRC_BYTES}"
        );
        // The accounting the bound rests on must match reality.
        assert_eq!(actual, src_bytes, "src_bytes accounting drifted");
    }

    #[test]
    fn compiled_script_cache_is_bounded_by_source_bytes() {
        let doc = json!({});
        let params = json!({});
        // Distinct ~33 KiB scripts (each legal under MAX_SCRIPT_LEN, and
        // flat rather than deep so they compile and run cleanly). Well under
        // MAX_SCRIPT_CACHE_ENTRIES of them already exceed the byte budget,
        // so the byte bound has to be what stops the growth.
        for i in 0..24 {
            let src = format!("{}return {i};", "def a = 1;".repeat(3300));
            assert!(src.len() > 32 * 1024);
            eval_painless(&src, &ctx(&doc, &params, 0.0)).unwrap();
        }
        let (entries, src_bytes, actual) = cache_stats();
        assert!(
            src_bytes <= MAX_SCRIPT_CACHE_SRC_BYTES,
            "cache holds {src_bytes} source bytes, bound is {MAX_SCRIPT_CACHE_SRC_BYTES}"
        );
        assert!(entries <= MAX_SCRIPT_CACHE_ENTRIES);
        assert!(
            entries < 24,
            "the byte bound must have evicted something: {entries} entries retained"
        );
        assert_eq!(actual, src_bytes, "src_bytes accounting drifted");
    }

    #[test]
    fn cached_script_is_parsed_once_and_still_correct() {
        let params = json!({"multiplier": 3});
        let src = "doc['n'].value * params.multiplier /* cache-once probe */";
        for n in 1..=5 {
            let doc = json!({ "n": n });
            let v = eval_painless(src, &ctx(&doc, &params, 0.0)).unwrap();
            assert!((v.as_f64().unwrap() - (n * 3) as f64).abs() < 1e-9);
        }
        assert!(
            SCRIPT_CACHE.with(|c| c.borrow().entries.contains_key(src)),
            "repeated evaluation of one source must leave a cached AST"
        );
        assert_eq!(
            cache_stats().0,
            1,
            "five evaluations of one source must leave exactly one entry"
        );
    }

    #[test]
    fn cached_parse_failure_still_reports_the_same_error() {
        let doc = json!({});
        let params = json!({});
        let src = "return ( ( ( /* unbalanced, cache-error probe */";
        let first = eval_painless(src, &ctx(&doc, &params, 0.0)).unwrap_err();
        let second = eval_painless(src, &ctx(&doc, &params, 0.0)).unwrap_err();
        assert_eq!(first, second);
    }

    #[test]
    fn caching_does_not_share_state_between_evaluations() {
        // The AST is shared but mutable evaluation state is not: a script
        // that mutates a local must start from scratch on every document.
        let params = json!({});
        let src = "def acc = 0; acc = acc + doc['n'].value; \
                   acc = acc + doc['n'].value; acc = acc + doc['n'].value; \
                   return acc; /* shared-state probe */";
        for n in 1..=4 {
            let doc = json!({ "n": n });
            let v = eval_painless(src, &ctx(&doc, &params, 0.0)).unwrap();
            assert_eq!(v.as_f64().unwrap(), (n * 3) as f64, "n = {n}");
        }
    }

    #[test]
    fn cached_ast_does_not_leak_the_call_budget_across_evaluations() {
        // MAX_CALL_COUNT lives on the per-evaluation `PainlessCtx`, not on
        // the AST, so memoising the AST must not let one document's closure
        // invocations count against the next document's budget. A script
        // that spends a large slice of the budget has to keep succeeding
        // when it is re-run against document after document.
        let doc = json!({});
        let params = json!({});
        // 2^11 = 2048 invocations per evaluation, comfortably under
        // MAX_CALL_COUNT (10_000) but far more than a per-process budget
        // would survive being run 8 times.
        let src = "def f = (g, n) -> { if (n <= 0) { return 1; } return g(g, n - 1) + g(g, n - 1); }; return f(f, 11); /* budget-reset probe */";
        for round in 0..8 {
            let v = eval_painless(src, &ctx(&doc, &params, 0.0))
                .unwrap_or_else(|e| panic!("round {round} must stay within budget: {e}"));
            assert!((v.as_f64().unwrap() - 2048.0).abs() < 1e-9, "round {round}");
        }
    }

    // ── Per-evaluation work budget (issue #122) ──────────────────────────

    /// The largest *benign* script the 64 KiB source limit admits: 4,300
    /// statements of flat arithmetic (59,773 bytes). This is the number
    /// [`MAX_SCRIPT_OPS`] is calibrated against — if the charging scheme
    /// changes, this test says by how much the margin moved rather than
    /// leaving the ceiling a guess.
    fn largest_benign_script() -> String {
        let mut src = String::from("double t = 0;\n");
        for i in 0..4300 {
            src.push_str(&format!("t = t + {}.5;\n", i % 97));
        }
        src.push_str("return t;");
        src
    }

    #[test]
    fn the_budget_leaves_the_largest_benign_script_a_wide_margin() {
        let src = largest_benign_script();
        assert!(src.len() < MAX_SCRIPT_LEN, "must be a submittable script");
        let doc = json!({ "rank": 7 });
        let params = json!({});
        let c = ctx(&doc, &params, 1.0);
        eval_painless(&src, &c).expect("a benign script must not trip the budget");
        let used = c.work_units();
        assert_eq!(
            used, 34_407,
            "the calibration point moved; re-derive MAX_SCRIPT_OPS rather than \
             editing this number"
        );
        assert!(
            MAX_SCRIPT_OPS / used >= 100,
            "the ceiling must keep a two-order-of-magnitude margin over the \
             largest benign script, got {}x",
            MAX_SCRIPT_OPS / used
        );
    }

    /// Work is not the same thing as shape. This script is *smaller* than the
    /// benign one above and runs a fraction of its statements, yet costs
    /// hundreds of times more — which is the whole of issue #122.
    #[test]
    fn quadratic_string_growth_trips_the_work_budget() {
        let mut src = String::from("def c = \"");
        src.push_str(&"x".repeat(1024));
        src.push_str("\";\ndef s = c;\n");
        for _ in 0..4000 {
            src.push_str("s = s + c;\n");
        }
        src.push_str("return s.length();");
        assert!(src.len() < MAX_SCRIPT_LEN, "must be a submittable script");

        let doc = json!({});
        let params = json!({});
        let err = eval_painless(&src, &ctx(&doc, &params, 0.0)).unwrap_err();
        assert_eq!(err, SCRIPT_OVER_BUDGET_MSG);
        assert!(
            is_resource_limit_error(&err),
            "a budget trip must reach the caller as a 400, not degrade to a \
             wrong score"
        );
    }

    /// Charging only per interpreter *step* would miss it: the trip happens
    /// after a few hundred statements, so the step count at the trip is tiny
    /// next to the benign script's 43,012 — the cost is all in the bytes.
    #[test]
    fn the_budget_is_charged_for_bytes_not_just_steps() {
        let big = PainlessValue::String("x".repeat(64 * 1024));
        assert_eq!(value_work_units(&big), 1 + 1024);
        let small = PainlessValue::Number(1.0);
        assert_eq!(value_work_units(&small), 1);
        // A nested document is weighed by everything it contains, because
        // cloning it copies everything it contains.
        let nested = PainlessValue::from_json(&json!({ "a": [1, 2, 3], "b": { "c": 4 } }));
        assert_eq!(value_work_units(&nested), 7);
    }

    /// A whole-document read is O(document) — `get_doc_value` clones the doc
    /// before walking it — so the budget has to see the document's size, not
    /// the field's.
    #[test]
    fn a_document_read_is_charged_for_the_whole_document() {
        let doc = json!({ "rank": 1, "blob": (0..500).collect::<Vec<u32>>() });
        let params = json!({});
        let c = ctx(&doc, &params, 0.0);
        eval_painless("doc['rank'].value", &c).expect("evaluate");
        assert!(
            c.work_units() > 500,
            "a read of a 500-element document was charged {} units",
            c.work_units()
        );
    }

    /// The budget must not fire on scripts that are merely *long*: the
    /// evaluation below runs the interpreter tens of thousands of times and
    /// must still come out with a real value.
    #[test]
    fn a_long_but_cheap_script_still_returns_its_value() {
        let doc = json!({});
        let params = json!({});
        let src = largest_benign_script();
        let value = eval_painless(&src, &ctx(&doc, &params, 0.0)).expect("evaluate");
        assert!(value.as_f64().is_some());
    }

    /// The time budget's anchor is fixed before any work is charged.
    ///
    /// Deriving it inside the first `clock_check` instead spends a whole
    /// sampling window establishing the deadline and a second one being able
    /// to fail it — and a window is bounded in work units, not in time, so
    /// "one window" is however long the largest single charge takes. Pinning
    /// the resolution point here keeps that structural property a test rather
    /// than a comment.
    #[test]
    fn the_evaluation_deadline_exists_before_any_work_is_charged() {
        let doc = json!({});
        let params = json!({});
        let before = std::time::Instant::now();
        let c = ctx(&doc, &params, 0.0);
        let after = std::time::Instant::now();
        assert_eq!(c.work_units(), 0, "nothing has been charged yet");
        // Outside a request scope the slice is MAX_EVAL_SLICE, and it is
        // measured from construction, not from the first clock read.
        assert!(
            c.eval_deadline >= before + MAX_EVAL_SLICE,
            "the deadline must be anchored at construction"
        );
        assert!(
            c.eval_deadline <= after + MAX_EVAL_SLICE,
            "the deadline must not be anchored later than construction"
        );
    }

    /// A `params` member read is charged for the subtree it materialises, on
    /// both spellings and before the value is built.
    ///
    /// `params.x` / `params['x']` are resolved by a fast path at chain
    /// position 0 that used to `continue` past the access chain's charge, so a
    /// read of an arbitrarily large caller-supplied value cost two units. The
    /// assertion is on the work count, so it holds regardless of how fast the
    /// machine running it is.
    #[test]
    fn a_params_member_read_is_charged_for_the_subtree_it_materialises() {
        let doc = json!({});
        let blob: Vec<Value> = (0..5_000).map(|i| json!(format!("v{i}"))).collect();
        let params = json!({ "blob": blob });
        for src in ["params.blob;", "params['blob'];"] {
            let c = ctx(&doc, &params, 0.0);
            eval_painless(src, &c).expect("evaluate");
            assert!(
                c.work_units() > 5_000,
                "`{src}` materialised a 5,000-node value for {} work units",
                c.work_units()
            );
        }
    }

    /// `params['_source']` clones the document, so it is charged the
    /// document's weight — the same charge `doc['x'].value` pays.
    #[test]
    fn a_params_source_read_is_charged_for_the_document_it_clones() {
        let blob: Vec<Value> = (0..5_000).map(|i| json!(format!("v{i}"))).collect();
        let doc = json!({ "blob": blob });
        let params = json!({});
        let c = ctx(&doc, &params, 0.0);
        eval_painless("params['_source'];", &c).expect("evaluate");
        assert!(
            c.work_units() > 5_000,
            "a whole-document clone was charged {} work units",
            c.work_units()
        );
    }

    /// Regression for the crash the `painless` fuzz target found in under a
    /// second (issue #207). The tokeniser walks bytes but slices `&src[..]` as
    /// a `&str`, and every continuation byte of a multi-byte character reads as
    /// an alphabetic Latin-1 char — so an identifier scan could stop inside one
    /// and the slice panicked on a char boundary. Scripts arrive in ordinary
    /// search and update bodies and the release profile sets `panic = "abort"`,
    /// so this was not a 400, it was the process.
    ///
    /// Before the fix each of these aborts the test process rather than
    /// failing an assertion.
    #[test]
    fn a_non_ascii_character_in_a_script_is_an_error_not_a_panic() {
        let doc = json!({ "title": "the quick brown fox" });
        let params = json!({});

        for src in [
            // The input libFuzzer minimised to: an identifier scan that runs
            // into U+028B.
            "emit(doc[\"title\"].value\u{28b}oUppe",
            "\u{28b}",
            "value\u{28b}",
            "\u{28b}value",
            "doc[\"title\"].\u{4e2d}\u{6587}",
            // Multi-byte inside a string literal must still be fine — the
            // fix must not have made ordinary Unicode text unusable.
            "\"caf\u{e9} \u{4e2d}\u{6587} \u{28b}\"",
            // Non-ASCII at the very end, where the scan runs off the input.
            "a\u{e9}",
            "\u{e9}\u{e9}\u{e9}",
        ] {
            // Neither entry point may panic. Both are allowed to fail.
            let _ = check_script_limits(src);
            let _ = eval_painless(src, &ctx(&doc, &params, 0.0));
        }

        // A string literal carrying non-ASCII still evaluates to itself: the
        // fix narrows the *identifier* scan, not the language.
        let v = eval_painless("\"caf\u{e9}\"", &ctx(&doc, &params, 0.0)).expect("evaluate");
        assert!(
            matches!(&v, PainlessValue::String(s) if s == "caf\u{e9}"),
            "{v:?}"
        );

        // ASCII identifiers are untouched by the narrowed scan.
        let v = eval_painless("doc['title'].value", &ctx(&doc, &params, 0.0)).expect("evaluate");
        assert!(
            matches!(&v, PainlessValue::String(s) if s == "the quick brown fox"),
            "{v:?}"
        );
    }
}

//! Where the engine's thread pools get their widths.
//!
//! Every pool in this crate used to size itself inline from
//! `available_parallelism()` with its own magic fraction, while
//! `EngineConfig::{flush_workers, merge_workers, search_workers}` — declared,
//! defaulted, documented and validated in `xerj-common` — were read by nothing
//! at all. An operator who set `engine.search_workers = 2` to keep XERJ off
//! their laptop's cores got no effect and no warning: the accepted-and-ignored
//! class tracked in #204, and half of #240.
//!
//! This module is the single seam between configuration and pool construction:
//! [`resolve`] turns an [`EngineConfig`] plus the machine policy in
//! [`xerj_common::resource`] into concrete widths, [`init`] installs them once
//! per process, and the pools in `lib.rs` read them. Defaults reproduce the
//! widths the pools already used — the measured ingest/read tuning is
//! unchanged; what changes is that the knobs now do what they say.

use std::cell::RefCell;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Mutex, OnceLock};

use rayon::{ThreadPool, ThreadPoolBuildError, ThreadPoolBuilder};
use xerj_common::config::EngineConfig;
use xerj_common::resource::{self, Workload};

/// Concrete thread counts for one process.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PoolSizing {
    /// `ingest_pool`: bulk parse/analyze/insert. Latency-critical for writers.
    pub ingest: usize,
    /// `background_pool`: flush side-cars and segment finalisation.
    pub background: usize,
    /// `merge_pool`: merge re-encode. Pure maintenance.
    pub merge: usize,
    /// `flush_finalize_gate`: how many shard finalizes may run at once.
    pub flush_finalize: usize,
    /// Rayon's global pool, which is what search segment fan-out runs on.
    pub search: usize,
}

/// What [`resolve`] decided, plus anything the operator asked for that could
/// not be honoured verbatim.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Resolved {
    pub sizing: PoolSizing,
    pub warnings: Vec<String>,
}

/// Turn configuration into pool widths.
///
/// `env_flush_finalize` is `XERJ_FIN_CONC`, kept as the tuning override it has
/// always been; it wins over the config value, and a value that cannot be used
/// is reported rather than dropped on the floor.
pub fn resolve(cfg: &EngineConfig, env_flush_finalize: Option<&str>) -> Resolved {
    let mut warnings = Vec::new();

    let mut flush_finalize = cfg.flush_workers.max(1);
    if let Some(raw) = env_flush_finalize.map(str::trim).filter(|s| !s.is_empty()) {
        match raw.parse::<usize>() {
            Ok(n) if n >= 1 => flush_finalize = n,
            _ => warnings.push(format!(
                "XERJ_FIN_CONC={raw} is not a positive integer; using \
                 engine.flush_workers={flush_finalize} instead"
            )),
        }
    }

    Resolved {
        sizing: PoolSizing {
            ingest: resource::threads_for(Workload::Latency),
            background: resource::threads_for(Workload::Background),
            merge: cfg.merge_workers.max(1),
            flush_finalize,
            search: cfg.search_workers.max(1),
        },
        warnings,
    }
}

static SIZING: std::sync::OnceLock<PoolSizing> = std::sync::OnceLock::new();

/// Install the process-wide pool sizing from config. Idempotent, like
/// [`crate::governor::init`]: the first caller wins, because rayon pools are
/// process-global and already-running threads cannot be resized.
///
/// A second [`Engine`](crate::Engine) built in the same process with *different*
/// widths logs a warning naming the values that were ignored — silently serving
/// one engine's config to another is exactly the bug this module exists to end.
pub fn init(cfg: &EngineConfig) {
    let resolved = resolve(cfg, std::env::var("XERJ_FIN_CONC").ok().as_deref());
    for warning in &resolved.warnings {
        tracing::warn!("{warning}");
    }
    let installed = *SIZING.get_or_init(|| resolved.sizing);
    if installed != resolved.sizing {
        tracing::warn!(
            "engine pool sizing was already fixed for this process ({installed:?}); ignoring \
             {:?} from this engine's config",
            resolved.sizing
        );
    }
    install_search_pool(installed.search);
}

/// The installed sizing, or the policy defaults when no engine has been built
/// yet (engine-only unit tests that touch a pool directly).
pub fn sizing() -> PoolSizing {
    *SIZING.get_or_init(|| resolve(&EngineConfig::default(), None).sizing)
}

/// Search fan-out runs on rayon's *global* pool, so honouring
/// `engine.search_workers` means building that pool explicitly — rayon
/// otherwise defaults it to every core on first use.
///
/// `build_global` can only succeed once per process. If some par_iter already
/// ran, the request cannot be honoured; that is reported with the width the
/// process actually has, instead of leaving the operator to guess.
fn install_search_pool(threads: usize) {
    static DONE: std::sync::Once = std::sync::Once::new();
    DONE.call_once(|| {
        if let Err(err) = rayon::ThreadPoolBuilder::new()
            .num_threads(threads)
            .thread_name(|i| format!("xerj-search-{i}"))
            .spawn_handler(safe_rayon_spawn)
            .build_global()
        {
            let actual = rayon::current_num_threads();
            if actual != threads {
                tracing::warn!(
                    "engine.search_workers={threads} could not be applied ({err}); search \
                     fan-out runs on the already-initialised global pool of {actual} threads"
                );
            }
        }
    });
}

// ── Building the named pools without aborting (#1122) ────────────────────────
//
// `panic = "abort"` in the release profile turns a rayon `build()` failure
// into a dead node. `build()` fails when `pthread_create` returns `EAGAIN`
// (thread or memory limit) — the same moment the node is already degraded.
// A failed build is not cached, so the next call tries again. A wide pool
// that cannot start is retried at one thread and that success is cached.
// When even one thread cannot be started, `install` runs on the calling
// thread and `spawn` runs the job inline rather than aborting.

static POOL_BUILD_LOCK: Mutex<()> = Mutex::new(());

thread_local! {
    /// A one-thread pool made of the calling thread. Kept for the thread's
    /// lifetime so a later `par_iter` on this thread does not fall through to
    /// rayon's global pool, which panics if it cannot start its own threads.
    static INLINE_POOL: RefCell<Option<ThreadPool>> = const { RefCell::new(None) };
}

/// A named engine pool. Callers keep writing `ingest_pool().install(...)`.
/// The pool itself is started on first use, not when this handle is built.
#[derive(Clone, Copy)]
pub(crate) struct PoolCall {
    slot: &'static OnceLock<ThreadPool>,
    label: &'static str,
    threads: fn() -> usize,
    build: fn(usize) -> Result<ThreadPool, ThreadPoolBuildError>,
}

impl PoolCall {
    pub(crate) const fn new(
        slot: &'static OnceLock<ThreadPool>,
        label: &'static str,
        threads: fn() -> usize,
        build: fn(usize) -> Result<ThreadPool, ThreadPoolBuildError>,
    ) -> Self {
        Self {
            slot,
            label,
            threads,
            build,
        }
    }

    pub fn install<R: Send>(&self, op: impl FnOnce() -> R + Send) -> R {
        install_or_inline(self.slot, self.label, (self.threads)(), self.build, op)
    }

    pub fn spawn(&self, op: impl FnOnce() + Send + 'static) {
        spawn_or_inline(self.slot, self.label, (self.threads)(), self.build, op)
    }
}

pub(crate) fn install_or_inline<R: Send>(
    slot: &OnceLock<ThreadPool>,
    label: &str,
    threads: usize,
    build: fn(usize) -> Result<ThreadPool, ThreadPoolBuildError>,
    op: impl FnOnce() -> R + Send,
) -> R {
    match ensure_pool(slot, label, threads, build) {
        Some(pool) => pool.install(op),
        None => inline_install(op),
    }
}

pub(crate) fn spawn_or_inline(
    slot: &OnceLock<ThreadPool>,
    label: &str,
    threads: usize,
    build: fn(usize) -> Result<ThreadPool, ThreadPoolBuildError>,
    op: impl FnOnce() + Send + 'static,
) {
    match ensure_pool(slot, label, threads, build) {
        Some(pool) => pool.spawn(op),
        None => match xerj_common::thread_spawn::try_spawn(label, op) {
            Ok(_) => {}
            Err(failure) => {
                static LOGGED: AtomicBool = AtomicBool::new(false);
                xerj_common::thread_spawn::warn_best_effort_degraded(
                    &LOGGED,
                    label,
                    &failure.error,
                );
                if let Some(job) = failure.job {
                    job();
                }
            }
        },
    }
}

/// The pool in `slot`, built at `threads` or, if that fails, at one thread.
/// `None` when neither could start. A failure is not stored, so the next
/// call tries again.
fn ensure_pool<'a>(
    slot: &'a OnceLock<ThreadPool>,
    label: &str,
    threads: usize,
    build: fn(usize) -> Result<ThreadPool, ThreadPoolBuildError>,
) -> Option<&'a ThreadPool> {
    if let Some(pool) = slot.get() {
        return Some(pool);
    }
    let _guard = POOL_BUILD_LOCK
        .lock()
        .unwrap_or_else(|err| err.into_inner());
    if let Some(pool) = slot.get() {
        return Some(pool);
    }
    let width = threads.max(1);
    let pool = match build(width) {
        Ok(pool) => pool,
        Err(err) if width > 1 => match build(1) {
            Ok(pool) => {
                log_pool_degraded_once(|| {
                    format!(
                        "could not start the {label} pool with {width} threads ({err}); \
                         using one thread (#1122)"
                    )
                });
                pool
            }
            Err(retry) => {
                log_pool_degraded_once(|| {
                    format!(
                        "could not start the {label} pool ({err}; one-thread retry: {retry}); \
                         this call runs on the calling thread (#1122)"
                    )
                });
                return None;
            }
        },
        Err(err) => {
            log_pool_degraded_once(|| {
                format!(
                    "could not start the {label} pool ({err}); \
                     this call runs on the calling thread (#1122)"
                )
            });
            return None;
        }
    };
    Some(slot.get_or_init(|| pool))
}

/// One line per process. A pool that cannot start is retried on the next
/// call; logging every call floods the node that is already out of threads.
fn log_pool_degraded_once(message: impl FnOnce() -> String) {
    static LOGGED: AtomicBool = AtomicBool::new(false);
    if LOGGED.swap(true, Ordering::Relaxed) {
        return;
    }
    tracing::error!("{}", message());
}

/// Rayon worker spawn that cannot abort the process (#1122).
///
/// Rayon's default handler is `std::thread::Builder::spawn`. That returns
/// `Ok` before the child maps its alternate signal stack, and the mmap
/// failure panics in the child. `panic = "abort"` then kills the node
/// during pool build, so the `Err` fallback in [`ensure_pool`] never runs.
/// This handler uses the same non-panicking spawn as the other best-effort
/// threads. The watermark gate is not consulted: these pools are built once
/// and a soft RSS watermark must not refuse them the way it refuses a
/// drain-free thread. A real `pthread_create` failure is an `Err`, which
/// fails the build and lets the caller run inline.
pub(crate) fn safe_rayon_spawn(thread: rayon::ThreadBuilder) -> std::io::Result<()> {
    let name = thread.name().unwrap_or("xerj-rayon").to_owned();
    xerj_common::thread_spawn::spawn_detached(name.as_str(), thread.stack_size(), move || {
        thread.run()
    })
}

/// Run `op`, and every `par_iter` inside it, on the calling thread.
///
/// Calling `op()` directly would not do that: a `par_iter` on a thread that
/// is not a rayon worker goes to the global pool, which panics if its threads
/// cannot start. A `use_current_thread()` pool of width 1 spawns nothing.
fn inline_install<R: Send>(op: impl FnOnce() -> R + Send) -> R {
    if rayon::current_thread_index().is_some() {
        return op();
    }
    // Build, run, then keep the pool alive. Dropping it would unregister this
    // thread, and the next `par_iter` would go to the global pool.
    match ThreadPoolBuilder::new()
        .num_threads(1)
        .use_current_thread()
        .build()
    {
        Ok(pool) => {
            let out = pool.install(op);
            INLINE_POOL.with(|slot| *slot.borrow_mut() = Some(pool));
            out
        }
        Err(err) => {
            tracing::error!("could not register the calling thread with rayon ({err})");
            op()
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg(flush: usize, merge: usize, search: usize) -> EngineConfig {
        EngineConfig {
            flush_workers: flush,
            merge_workers: merge,
            search_workers: search,
            ..EngineConfig::default()
        }
    }

    #[test]
    fn configured_workers_reach_the_pools() {
        // The #240 §4 defect: these three were read by nothing.
        let r = resolve(&cfg(3, 5, 7), None);
        assert_eq!(r.sizing.flush_finalize, 3);
        assert_eq!(r.sizing.merge, 5);
        assert_eq!(r.sizing.search, 7);
        assert!(r.warnings.is_empty());
    }

    #[test]
    fn defaults_reproduce_the_measured_widths() {
        let cores = xerj_common::resource::cores();
        let r = resolve(&EngineConfig::default(), None);
        // Latency-critical pools keep the whole machine ...
        assert_eq!(r.sizing.ingest, cores);
        assert_eq!(r.sizing.background, cores);
        assert_eq!(r.sizing.search, cores);
        // ... maintenance keeps the measured max(2, cores/8).
        assert_eq!(r.sizing.merge, (cores / 8).max(2).min(cores.max(1)));
        assert_eq!(r.sizing.flush_finalize, r.sizing.merge);
    }

    #[test]
    fn the_env_override_wins_and_a_bad_one_is_reported() {
        assert_eq!(resolve(&cfg(3, 2, 4), Some("9")).sizing.flush_finalize, 9);
        assert_eq!(resolve(&cfg(3, 2, 4), Some("")).sizing.flush_finalize, 3);
        let r = resolve(&cfg(3, 2, 4), Some("lots"));
        assert_eq!(r.sizing.flush_finalize, 3);
        assert!(r.warnings[0].contains("XERJ_FIN_CONC=lots"));
        let r = resolve(&cfg(3, 2, 4), Some("0"));
        assert_eq!(r.sizing.flush_finalize, 3);
        assert_eq!(r.warnings.len(), 1);
    }

    /// `pthread_create` returning `EAGAIN`. Injected through rayon's spawn
    /// hook, so `build()` takes its real failure path.
    fn failing_build(n: usize) -> Result<ThreadPool, ThreadPoolBuildError> {
        ThreadPoolBuilder::new()
            .num_threads(n)
            .spawn_handler(|_| {
                Err(std::io::Error::new(
                    std::io::ErrorKind::WouldBlock,
                    "injected EAGAIN",
                ))
            })
            .build()
    }

    fn wide_fails_one_succeeds(n: usize) -> Result<ThreadPool, ThreadPoolBuildError> {
        if n > 1 {
            failing_build(n)
        } else {
            ThreadPoolBuilder::new().num_threads(1).build()
        }
    }

    /// #1122: `.build().expect(..)` aborted the process. A pool that cannot
    /// start must still produce the job's result, on the calling thread, and
    /// must not cache the failure (the next call tries again).
    #[test]
    fn a_pool_that_cannot_spawn_runs_install_on_the_caller() {
        let slot = OnceLock::new();
        let caller = std::thread::current().id();
        let seen = install_or_inline(&slot, "xerj-test", 4, failing_build, || {
            std::thread::current().id()
        });
        assert_eq!(seen, caller);
        assert!(slot.get().is_none(), "a failed build must not be cached");

        let sum: u32 = install_or_inline(&slot, "xerj-test", 4, failing_build, || {
            use rayon::prelude::*;
            (0..32u32).into_par_iter().sum()
        });
        assert_eq!(sum, (0..32u32).sum::<u32>());
    }

    /// The wide pool cannot start, one thread can. That one-thread pool is
    /// what later calls use — the work still runs, and the process stays up.
    #[test]
    fn a_wide_pool_that_cannot_spawn_falls_back_to_one_thread() {
        let slot = OnceLock::new();
        let width = install_or_inline(&slot, "xerj-test", 8, wide_fails_one_succeeds, || {
            rayon::current_num_threads()
        });
        assert_eq!(width, 1);
        assert_eq!(slot.get().unwrap().current_num_threads(), 1);
    }

    /// `spawn` is fire-and-forget on the live pools. When the pool cannot
    /// start, the job still runs (on a thread, or inline if that spawn fails)
    /// instead of aborting at pool construction.
    #[test]
    fn a_pool_that_cannot_spawn_still_runs_a_spawned_job() {
        let slot = OnceLock::new();
        let (tx, rx) = std::sync::mpsc::channel();
        spawn_or_inline(&slot, "xerj-test", 4, failing_build, move || {
            tx.send(std::thread::current().id()).unwrap();
        });
        let ran = rx.recv_timeout(std::time::Duration::from_secs(2));
        assert!(ran.is_ok(), "the spawned job must run");
        assert!(slot.get().is_none());
    }

    /// #1122: production pools spawn workers through `safe_rayon_spawn`,
    /// not `std::thread::Builder`. The work has to actually run — a spawn
    /// handler that detaches wrong, or that never calls `ThreadBuilder::run`,
    /// would hang `install` or drop the job.
    #[test]
    fn the_safe_rayon_spawner_runs_pool_work() {
        let pool = ThreadPoolBuilder::new()
            .num_threads(2)
            .thread_name(|i| format!("xerj-t1122-{i}"))
            .spawn_handler(super::safe_rayon_spawn)
            .build()
            .expect("safe spawner starts a pool");
        let sum = pool.install(|| {
            use rayon::prelude::*;
            (0..64u32).into_par_iter().sum::<u32>()
        });
        assert_eq!(sum, (0..64u32).sum::<u32>());
    }
}

//! Role-based access control — data model, plus the per-key grants that the
//! reserved-namespace authorization in `xerj-api::authz` enforces.
//!
//! ⚠️ HONEST-SURFACE WARNING, NARROWED (was RC4 item 6): the named
//! [`RoleStore`] below — the thing `PUT /_security/role/{name}` writes — is
//! still **data only**. Nothing in the auth path consults it, which is why the
//! `/_security/role*` handlers stamp every response with `"enforced": false`.
//! Broad RBAC over the general ES-compat surface (FLS/DLS, cluster privileges,
//! named-role binding) remains DEFERRED.
//!
//! What *is* enforced: the [`Role`] values attached to a **minted API key**
//! (`ApiKeyRecord::roles`, parsed from `role_descriptors` by
//! [`roles_from_role_descriptors`]). Those gate the reserved `.xerj-memory-*`
//! namespace — agent-memory namespaces and second brains — and confine a
//! scoped key to the indices it names. See `xerj-api::authz` for the decision
//! function and the enumeration of enforcement points.
//!
//! What ships today:
//! - `Privilege` enum covering the seven core ops (read / write / admin
//!   index, snapshot create / restore, security admin, audit read).
//! - `Role` — name + privileges + index-pattern allow list.
//! - `RoleStore` — in-memory map of roles, default seeded with
//!   `admin`, `write`, `read`, `read_only_index`, `snapshot_admin`, `auditor`.
//! - `roles_from_role_descriptors` — ES `role_descriptors` → `Vec<Role>`.

use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Privilege {
    /// Read documents and run searches/aggs.
    ReadIndex,
    /// Write (index, update, delete, bulk).
    WriteIndex,
    /// Admin (create / delete / settings / mappings).
    AdminIndex,
    /// Take snapshots.
    SnapshotCreate,
    /// Restore from snapshot.
    SnapshotRestore,
    /// Manage roles, users, API keys.
    SecurityAdmin,
    /// Read the audit log.
    AuditRead,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Role {
    pub name: String,
    pub privileges: HashSet<Privilege>,
    /// Glob patterns of index names the role applies to ("*" = all).
    pub indices: Vec<String>,
}

impl Role {
    pub fn new(
        name: impl Into<String>,
        privileges: HashSet<Privilege>,
        indices: Vec<String>,
    ) -> Self {
        Self {
            name: name.into(),
            privileges,
            indices,
        }
    }

    /// The `role_descriptors` key this role came from, with the per-entry
    /// index [`roles_from_role_descriptors`] appends stripped off.
    ///
    /// That function fans one descriptor out into one [`Role`] per `indices`
    /// entry and names them `"{descriptor}[{i}]"`, because the privileges and
    /// patterns differ per entry and the names have to stay distinct. `name`
    /// is therefore an internal identifier, not something a caller ever wrote.
    /// This is its inverse, and it lives here — beside the encoder — so the
    /// two cannot drift apart.
    ///
    /// Used by `GET /_security/_authenticate` to report the names the caller
    /// actually supplied (`reader`), not the encoding (`reader[0]`).
    ///
    /// Strips only a trailing `[<digits>]`, so a descriptor legitimately named
    /// `weird[x]` or `weird[]` comes back unchanged rather than mangled. A
    /// role built by any other means (the seeded [`RoleStore`] entries, a test)
    /// has no suffix and is returned as-is.
    pub fn descriptor_name(&self) -> &str {
        let Some(open) = self.name.rfind('[') else {
            return &self.name;
        };
        let Some(digits) = self.name[open + 1..].strip_suffix(']') else {
            return &self.name;
        };
        if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
            return &self.name;
        }
        &self.name[..open]
    }

    /// Does this role apply to the named index?  Glob: "*" matches
    /// everything; literal names must match exactly; suffix-`*` (e.g.
    /// `logs-*`) matches by prefix.
    ///
    /// # `names: ["*"]` includes the reserved namespace, deliberately
    ///
    /// "Everything" means everything: a role granted `*` matches
    /// `.xerj-memory-alice-edges` like any other index, so a key minted with
    /// it can read and write every second brain and every agent-memory
    /// namespace on the node. `xerj_api::authz::may_reach_reserved` is *not*
    /// consulted on this path — it decides whether a name a caller is about to
    /// **create** (an alias, a fresh index, a template pattern) is squatting
    /// the reserved prefix, not whether an existing grant covers a read.
    ///
    /// This is an administrator's explicit choice rather than an escalation:
    /// the only principal that can mint a scoped key at all is the superuser
    /// (`POST /_security/api_key`), and `*` is the plainest possible way to
    /// write "this key gets the whole node". Narrowing it silently would break
    /// the operator who wrote `*` and meant it — a Kibana service account, a
    /// backup runner — with no error to explain the missing data.
    ///
    /// **Operators wanting brain isolation must not hand out `names: ["*"]`.**
    /// Grant the concrete indices, or a prefix that excludes the reserved
    /// namespace (`logs-*`, `app-*`); `.xerj-memory-*` is reachable only by a
    /// grant that reaches it. `a_star_grant_reaches_the_reserved_namespace` in
    /// `xerj_api::authz`'s tests pins this behaviour so it cannot be changed
    /// by accident.
    pub fn applies_to(&self, idx: &str) -> bool {
        for pat in &self.indices {
            if pat == "*" || pat == idx {
                return true;
            }
            if let Some(prefix) = pat.strip_suffix('*') {
                if idx.starts_with(prefix) {
                    return true;
                }
            }
        }
        false
    }

    pub fn allows(&self, idx: &str, p: Privilege) -> bool {
        self.applies_to(idx) && self.privileges.contains(&p)
    }
}

/// Map one Elasticsearch index-privilege name onto this crate's [`Privilege`]s.
///
/// Unknown names map to **nothing** — an unrecognized privilege grants no
/// access rather than being waved through, so a typo (or an ES privilege xerj
/// has not implemented) fails closed.
fn es_index_privilege(name: &str) -> &'static [Privilege] {
    use Privilege::*;
    match name {
        "all" => &[ReadIndex, WriteIndex, AdminIndex],
        "read" | "read_cross_cluster" | "view_index_metadata" | "monitor" => &[ReadIndex],
        "write" | "index" | "create" | "create_doc" | "delete" | "maintenance" => &[WriteIndex],
        "manage" | "create_index" | "delete_index" | "manage_ilm" | "manage_follow_index" => {
            &[AdminIndex]
        }
        _ => &[],
    }
}

/// Map one cluster-privilege name onto the cluster privileges this crate
/// enforces — currently only [`Privilege::AuditRead`] (issue #329).
///
/// Everything else in a `cluster` array still grants nothing, for the reason
/// [`roles_from_role_descriptors`] gives: honouring a privilege nothing checks
/// would be theatre.
///
/// **`all` is deliberately not mapped here**, tempting as it is. `cluster:
/// ["all"]` is the blanket grant operators already write next to their index
/// grants, and honouring it would silently hand the audit log — every tenant's
/// activity, every security event — to keys that were minted before the
/// privilege was enforced and whose owners never asked for it. A fix for a
/// privilege boundary must not widen a different one on upgrade. Reading the
/// audit log is opt-in, by the name that never meant anything until now.
fn es_cluster_privilege(name: &str) -> &'static [Privilege] {
    use Privilege::*;
    match name {
        "read_audit" => &[AuditRead],
        _ => &[],
    }
}

/// Parse an Elasticsearch-shaped `role_descriptors` object — exactly what
/// `POST /_security/api_key` already accepts on the wire — into the roles this
/// crate enforces:
///
/// ```json
/// { "alice-brain": { "indices": [
///     { "names": [".xerj-memory-alice-edges", ".xerj-memory-alice"],
///       "privileges": ["read", "write"] } ] } }
/// ```
///
/// One [`Role`] is emitted per `indices[]` entry (named `"{descriptor}[{i}]"`),
/// because a `Role` carries a single privilege set while one descriptor may
/// list several entries with different privileges.
///
/// Deliberate omissions, all of which fail closed (they grant nothing):
/// - `cluster` privileges are ignored **except** `read_audit`, which grants
///   [`Privilege::AuditRead`] and nothing else (issue #329). Every other cluster
///   name — `all` included — is still dropped; see [`es_cluster_privilege`] for
///   why the blanket grant is not honoured.
/// - `field_security` / `query` (FLS/DLS) are ignored; a descriptor that only
///   makes sense with FLS/DLS therefore over-grants at the field level within
///   an index it was already granted. Callers that need FLS must not rely on
///   this.
/// - Only a trailing `*` globs (see [`Role::applies_to`]); a mid-pattern `*`
///   matches nothing.
pub fn roles_from_role_descriptors(descriptors: &Value) -> Vec<Role> {
    let Some(map) = descriptors.as_object() else {
        return Vec::new();
    };
    let mut roles = Vec::new();
    for (descriptor_name, descriptor) in map {
        // Cluster privileges, of which exactly one name is honoured (#329).
        // A `cluster` array is otherwise still ignored — see the doc comment —
        // but `read_audit` has to be grantable or the gate on `/_audit/*` would
        // mean "superuser only", and the enterprise ask is precisely to hand an
        // auditor a credential that reads the audit log and nothing else.
        // Emitted as a role over `*` because [`Privilege::AuditRead`] is not
        // index-scoped: the pattern is irrelevant to the only check that reads
        // it (`xerj_api::authz::holds_audit_read`), and the privilege set
        // contains no index privilege, so this grants no access to any data.
        if let Some(cluster) = descriptor.get("cluster").and_then(|v| v.as_array()) {
            let privileges: HashSet<Privilege> = cluster
                .iter()
                .filter_map(|v| v.as_str())
                .flat_map(|p| es_cluster_privilege(p).iter().copied())
                .collect();
            if !privileges.is_empty() {
                roles.push(Role::new(
                    format!("{descriptor_name}[cluster]"),
                    privileges,
                    vec!["*".to_string()],
                ));
            }
        }
        let Some(entries) = descriptor.get("indices").and_then(|v| v.as_array()) else {
            continue;
        };
        for (i, entry) in entries.iter().enumerate() {
            let names: Vec<String> = entry
                .get("names")
                .and_then(|v| v.as_array())
                .map(|a| {
                    a.iter()
                        .filter_map(|v| v.as_str())
                        .filter(|s| !s.is_empty())
                        .map(String::from)
                        .collect()
                })
                .unwrap_or_default();
            let privileges: HashSet<Privilege> = entry
                .get("privileges")
                .and_then(|v| v.as_array())
                .map(|a| {
                    a.iter()
                        .filter_map(|v| v.as_str())
                        .flat_map(|p| es_index_privilege(p).iter().copied())
                        .collect()
                })
                .unwrap_or_default();
            if names.is_empty() || privileges.is_empty() {
                // Nothing to grant. Skipping keeps `roles.is_empty()` an
                // accurate "this key was given no usable grant" signal.
                continue;
            }
            roles.push(Role::new(
                format!("{descriptor_name}[{i}]"),
                privileges,
                names,
            ));
        }
    }
    roles
}

pub struct RoleStore {
    roles: RwLock<HashMap<String, Role>>,
}

impl RoleStore {
    pub fn new() -> Arc<Self> {
        let mut roles = HashMap::new();
        // Seed the canonical roles operators expect.
        for r in default_roles() {
            roles.insert(r.name.clone(), r);
        }
        Arc::new(Self {
            roles: RwLock::new(roles),
        })
    }

    pub fn put(&self, role: Role) {
        self.roles.write().insert(role.name.clone(), role);
    }

    pub fn get(&self, name: &str) -> Option<Role> {
        self.roles.read().get(name).cloned()
    }

    pub fn delete(&self, name: &str) -> Option<Role> {
        self.roles.write().remove(name)
    }

    pub fn list(&self) -> Vec<Role> {
        self.roles.read().values().cloned().collect()
    }
}

fn default_roles() -> Vec<Role> {
    use Privilege::*;
    vec![
        Role::new(
            "admin",
            [
                ReadIndex,
                WriteIndex,
                AdminIndex,
                SnapshotCreate,
                SnapshotRestore,
                SecurityAdmin,
                AuditRead,
            ]
            .into_iter()
            .collect(),
            vec!["*".into()],
        ),
        Role::new(
            "write",
            [ReadIndex, WriteIndex].into_iter().collect(),
            vec!["*".into()],
        ),
        Role::new("read", [ReadIndex].into_iter().collect(), vec!["*".into()]),
        Role::new(
            "read_only_index",
            [ReadIndex].into_iter().collect(),
            vec![], // operator must add patterns explicitly
        ),
        Role::new(
            "snapshot_admin",
            [SnapshotCreate, SnapshotRestore].into_iter().collect(),
            vec!["*".into()],
        ),
        Role::new(
            "auditor",
            [AuditRead].into_iter().collect(),
            vec!["*".into()],
        ),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn defaults_seeded() {
        let s = RoleStore::new();
        assert!(s.get("admin").is_some());
        assert!(s.get("read").is_some());
        assert!(s.get("write").is_some());
        assert!(s.get("auditor").is_some());
    }

    #[test]
    fn admin_allows_all_on_all_indices() {
        let s = RoleStore::new();
        let admin = s.get("admin").unwrap();
        assert!(admin.allows("anything", Privilege::WriteIndex));
        assert!(admin.allows("logs-prod", Privilege::AdminIndex));
    }

    #[test]
    fn read_only_index_default_denies_all() {
        let s = RoleStore::new();
        let r = s.get("read_only_index").unwrap();
        assert!(!r.allows("logs-prod", Privilege::ReadIndex));
        assert!(!r.allows("*", Privilege::ReadIndex));
    }

    #[test]
    fn glob_index_pattern_matches() {
        let r = Role::new(
            "logs-reader",
            [Privilege::ReadIndex].into_iter().collect(),
            vec!["logs-*".into()],
        );
        assert!(r.allows("logs-prod", Privilege::ReadIndex));
        assert!(r.allows("logs-stage", Privilege::ReadIndex));
        assert!(!r.allows("metrics-prod", Privilege::ReadIndex));
        assert!(!r.allows("logs-prod", Privilege::WriteIndex));
    }

    #[test]
    fn role_descriptors_parse_into_index_grants() {
        let roles = roles_from_role_descriptors(&serde_json::json!({
            "alice-brain": {
                "cluster": ["all"],
                "indices": [
                    { "names": [".xerj-memory-alice-edges"], "privileges": ["read", "write"] },
                    { "names": [".xerj-memory-alice"], "privileges": ["read"] }
                ]
            }
        }));
        assert_eq!(roles.len(), 2, "one Role per indices[] entry");
        assert!(roles
            .iter()
            .any(|r| r.allows(".xerj-memory-alice-edges", Privilege::WriteIndex)));
        assert!(roles
            .iter()
            .any(|r| r.allows(".xerj-memory-alice", Privilege::ReadIndex)));
        // The read-only entry does not silently grant writes, and nothing
        // grants anything on a brain that was never named.
        assert!(!roles
            .iter()
            .any(|r| r.allows(".xerj-memory-alice", Privilege::WriteIndex)));
        assert!(!roles
            .iter()
            .any(|r| r.allows(".xerj-memory-bob-edges", Privilege::ReadIndex)));
        // `cluster` privileges are ignored, so "all" there granted no index.
        assert!(!roles
            .iter()
            .any(|r| r.allows("anything", Privilege::ReadIndex)));
    }

    /// `descriptor_name` must be the exact inverse of the `"{name}[{i}]"`
    /// encoding `roles_from_role_descriptors` applies — that is what
    /// `GET /_security/_authenticate` reports, so a mismatch shows a caller a
    /// role name it never wrote.
    #[test]
    fn descriptor_name_inverts_the_per_entry_suffix() {
        let roles = roles_from_role_descriptors(&serde_json::json!({
            "alice-brain": {
                "indices": [
                    { "names": [".xerj-memory-alice-edges"], "privileges": ["read"] },
                    { "names": [".xerj-memory-alice"], "privileges": ["read"] }
                ]
            }
        }));
        assert_eq!(roles.len(), 2);
        assert_eq!(roles[0].name, "alice-brain[0]");
        assert_eq!(roles[1].name, "alice-brain[1]");
        // Both entries came from the one descriptor the caller named.
        for r in &roles {
            assert_eq!(r.descriptor_name(), "alice-brain");
        }

        // Only a trailing `[<digits>]` is a suffix we produced. Anything else
        // is part of the name the caller chose and must survive untouched —
        // stripping it would rename someone's role behind their back.
        for name in [
            "plain",
            "weird[x]",
            "weird[]",
            "trailing[",
            "]leading",
            "nested[0][a]",
        ] {
            let r = Role::new(name, HashSet::new(), vec![]);
            assert_eq!(r.descriptor_name(), name, "{name} must not be rewritten");
        }
        // …and ones that genuinely are our encoding, on awkward base names.
        let r = Role::new("has[brackets][2]", HashSet::new(), vec![]);
        assert_eq!(r.descriptor_name(), "has[brackets]");
        // JSON permits `"role_descriptors": {"": {...}}`, which encodes to
        // `"[0]"`. Inverting it to the empty name is faithful — that is what
        // the caller wrote — and is why this is an inverse rather than a
        // prettifier.
        let r = Role::new("[0]", HashSet::new(), vec![]);
        assert_eq!(r.descriptor_name(), "");
    }

    #[test]
    fn unusable_role_descriptors_grant_nothing() {
        // Not an object, no `indices`, empty names, empty/unknown privileges —
        // every one of these must produce zero roles, so `roles.is_empty()`
        // stays a truthful "no grant" signal for the fail-closed path.
        for d in [
            serde_json::json!("all"),
            serde_json::json!({ "r": { "cluster": ["all"] } }),
            serde_json::json!({ "r": { "indices": [{ "names": [], "privileges": ["all"] }] } }),
            serde_json::json!({ "r": { "indices": [{ "names": ["x"], "privileges": [] }] } }),
            serde_json::json!({ "r": { "indices": [{ "names": ["x"], "privileges": ["bogus"] }] } }),
        ] {
            assert!(
                roles_from_role_descriptors(&d).is_empty(),
                "must grant nothing: {d}"
            );
        }
    }

    /// `cluster: ["read_audit"]` is the one cluster name that grants anything
    /// (issue #329): it yields [`Privilege::AuditRead`] and **no** index
    /// privilege, so an auditor credential reads the log and no data.
    #[test]
    fn read_audit_is_the_one_grantable_cluster_privilege() {
        let roles = roles_from_role_descriptors(&serde_json::json!({
            "a": { "cluster": ["read_audit"], "indices": [] }
        }));
        assert_eq!(roles.len(), 1, "one cluster role: {roles:?}");
        assert_eq!(
            roles[0].privileges,
            [Privilege::AuditRead].into_iter().collect::<HashSet<_>>()
        );
        // The `*` pattern it carries is not an index grant — the privilege set
        // holds nothing index-scoped, so every index check still fails.
        for p in [
            Privilege::ReadIndex,
            Privilege::WriteIndex,
            Privilege::AdminIndex,
        ] {
            assert!(!roles[0].allows("payroll", p), "{p:?} must not be granted");
            assert!(!roles[0].allows(".xerj-memory-alice-edges", p));
        }
    }

    /// It composes with index grants instead of replacing them.
    #[test]
    fn read_audit_alongside_index_grants_keeps_both() {
        let roles = roles_from_role_descriptors(&serde_json::json!({
            "a": {
                "cluster": ["read_audit"],
                "indices": [{ "names": ["logs-*"], "privileges": ["read"] }]
            }
        }));
        assert_eq!(roles.len(), 2, "cluster role + index role: {roles:?}");
        assert!(roles
            .iter()
            .any(|r| r.privileges.contains(&Privilege::AuditRead)));
        assert!(roles
            .iter()
            .any(|r| r.allows("logs-prod", Privilege::ReadIndex)));
    }

    #[test]
    fn all_privilege_covers_read_write_admin() {
        let roles = roles_from_role_descriptors(&serde_json::json!({
            "r": { "indices": [{ "names": ["logs-*"], "privileges": ["all"] }] }
        }));
        let r = &roles[0];
        assert!(r.allows("logs-prod", Privilege::ReadIndex));
        assert!(r.allows("logs-prod", Privilege::WriteIndex));
        assert!(r.allows("logs-prod", Privilege::AdminIndex));
        assert!(!r.allows("metrics", Privilege::ReadIndex));
    }
}

//! Salted fast hash for **machine-generated** credentials (issue #201).
//!
//! # Why not Argon2/scrypt/bcrypt
//!
//! Those are password hashes. Their whole job is to be slow, because a human
//! password carries maybe 20–40 bits of entropy and an offline attacker with
//! the hash can otherwise walk the whole space. A xerj API-key secret is not a
//! password: `POST /_security/api_key` mints it from two v4 UUIDs
//! (`es_compat::security_create_api_key`), i.e. **244 bits** of CSPRNG output
//! that no human ever chooses, types or reuses. Brute-forcing that is not
//! "expensive", it is arithmetically out of reach regardless of how fast the
//! hash is — so a slow hash buys nothing against the only attack it defends,
//! and costs a great deal: this comparison runs on **every authenticated
//! request**, and Argon2id at any recommended parameterisation is tens of
//! milliseconds, which would turn a sub-millisecond search into a
//! password-hash benchmark and hand an attacker a trivial CPU-exhaustion DoS
//! (send garbage credentials, make the node hash them).
//!
//! So: one SHA-256 over `salt || secret`. That is the same call Elasticsearch
//! makes for API keys — its default `xpack.security.authc.api_key.hashing.
//! algorithm` is `SSHA256`, salted SHA-256, not one of the PBKDF2/bcrypt
//! options it offers for *user* passwords (approach read from
//! `x-pack/plugin/security/.../ApiKeyService.java:170-174` and
//! `x-pack/plugin/core/.../authc/support/Hasher.java:418-447`; ES is
//! AGPL/Elastic-licensed and APPROACH-ONLY here — no code was copied, the Rust
//! below is ours and the encoding is different).
//!
//! # Why salt at all, if the secret is already unguessable
//!
//! Two reasons, both cheap: a per-record salt means two nodes that somehow
//! minted the same secret do not produce the same stored string, and it kills
//! any precomputation (a shared rainbow table over, say, a leaked generator's
//! output space) before it starts. 16 bytes of salt costs 32 hex characters.
//!
//! # Encoding
//!
//! `$ssha256$<32 hex salt chars>$<64 hex digest chars>` — self-describing, so
//! a future algorithm can be added without a migration flag day and old
//! records keep verifying. [`is_usable_hash`] is the discriminator the load
//! path uses to tell a credential this build can actually check apart from a
//! pre-#201 plaintext secret — or from a corrupt record that can never
//! authenticate at all.

use sha2::{Digest, Sha256};

/// Scheme tag. Present on every string [`hash_secret`] produces.
const SSHA256_PREFIX: &str = "$ssha256$";

/// Salt length in bytes.
const SALT_LEN: usize = 16;

/// Hash `secret` under a freshly generated salt.
///
/// The salt comes from `Uuid::new_v4`, i.e. the `getrandom` CSPRNG — the same
/// source the secret itself is minted from. (122 of the 128 bits are random;
/// the six version/variant bits are fixed. A salt needs uniqueness, not
/// entropy, so that is ample.)
pub fn hash_secret(secret: &str) -> String {
    let salt = uuid::Uuid::new_v4().into_bytes();
    debug_assert_eq!(salt.len(), SALT_LEN);
    encode(&salt, &digest(&salt, secret))
}

/// Constant-time check of `presented` against a string produced by
/// [`hash_secret`].
///
/// Returns `false` — never panics, never errors — for anything it does not
/// recognise: a truncated record, a hand-edited file, a plaintext secret left
/// over from before #201. "Unrecognised" must mean "denied", so a mangled
/// store cannot become an authentication bypass.
pub fn verify_secret(presented: &str, stored: &str) -> bool {
    let Some((salt, expected)) = decode(stored) else {
        return false;
    };
    constant_time_eq(&digest(&salt, presented), &expected)
}

/// Is `stored` a hash this build can actually verify a secret against?
///
/// The discriminator the load path uses
/// (`Engine::load_persisted_api_keys` → `ApiKeyRecord::migrate_from_plaintext`)
/// and the same one `ApiKeyRecord::verify_secret` fails closed on, so the two
/// cannot disagree about what counts as a credential.
///
/// It is a **full parse**, not a scheme-tag check, and that distinction is
/// load-bearing: `"$ssha256$truncated"` carries the tag but decodes to
/// nothing, so [`verify_secret`] denies it against every input. A prefix test
/// would call that record "already hashed" and restore it — leaving a key
/// that `GET /_security/api_key` lists as live while nothing can ever
/// authenticate as it, which is exactly the accept-then-ignore shape issue
/// #204 tracks. "Tagged" is not "usable"; only "decodes" is.
pub fn is_usable_hash(stored: &str) -> bool {
    decode(stored).is_some()
}

// ── internals ────────────────────────────────────────────────────────────────

fn digest(salt: &[u8], secret: &str) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update(salt);
    h.update(secret.as_bytes());
    h.finalize().into()
}

fn encode(salt: &[u8], digest: &[u8; 32]) -> String {
    let mut out = String::with_capacity(SSHA256_PREFIX.len() + SALT_LEN * 2 + 1 + 64);
    out.push_str(SSHA256_PREFIX);
    push_hex(&mut out, salt);
    out.push('$');
    push_hex(&mut out, digest);
    out
}

fn decode(stored: &str) -> Option<(Vec<u8>, [u8; 32])> {
    let body = stored.strip_prefix(SSHA256_PREFIX)?;
    let (salt_hex, digest_hex) = body.split_once('$')?;
    if salt_hex.len() != SALT_LEN * 2 || digest_hex.len() != 64 {
        return None;
    }
    let salt = from_hex(salt_hex)?;
    let digest_bytes = from_hex(digest_hex)?;
    let mut digest = [0u8; 32];
    digest.copy_from_slice(&digest_bytes);
    Some((salt, digest))
}

fn push_hex(out: &mut String, bytes: &[u8]) {
    use std::fmt::Write as _;
    for b in bytes {
        // Writing into a String is infallible.
        let _ = write!(out, "{b:02x}");
    }
}

fn from_hex(s: &str) -> Option<Vec<u8>> {
    if !s.len().is_multiple_of(2) {
        return None;
    }
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(s.len() / 2);
    for pair in bytes.chunks(2) {
        let hi = (pair[0] as char).to_digit(16)?;
        let lo = (pair[1] as char).to_digit(16)?;
        out.push((hi * 16 + lo) as u8);
    }
    Some(out)
}

/// Length-independent-only constant-time comparison. Both operands here are
/// fixed-size digests, so length never varies in practice; the loop exists so
/// a match/mismatch takes the same time regardless of *where* it differs.
fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips() {
        let stored = hash_secret("s3cr3t");
        assert!(is_usable_hash(&stored));
        assert!(verify_secret("s3cr3t", &stored));
        assert!(!verify_secret("s3cr3T", &stored));
        assert!(!verify_secret("", &stored));
    }

    #[test]
    fn the_secret_is_not_recoverable_from_the_encoding() {
        let stored = hash_secret("a-very-recognisable-secret");
        assert!(!stored.contains("a-very-recognisable-secret"));
        assert_eq!(stored.len(), SSHA256_PREFIX.len() + 32 + 1 + 64);
    }

    #[test]
    fn salt_is_per_call() {
        let a = hash_secret("same");
        let b = hash_secret("same");
        assert_ne!(a, b, "two hashes of the same secret must differ");
        assert!(verify_secret("same", &a) && verify_secret("same", &b));
    }

    /// Anything we do not recognise denies. A plaintext leftover must never
    /// verify against itself — that would silently re-create the bug #201 is
    /// about, with the plaintext comparison hiding behind the hash API.
    #[test]
    fn unrecognised_encodings_deny() {
        for stored in [
            "",
            "plaintext-secret",
            "$ssha256$",
            "$ssha256$deadbeef$cafe",
            "$ssha256$00000000000000000000000000000000",
            "$argon2id$v=19$m=1,t=1,p=1$c2FsdA$aGFzaA",
        ] {
            assert!(
                !verify_secret("plaintext-secret", stored),
                "unrecognised stored form {stored:?} must not verify"
            );
            // The two must agree exactly: anything that can never verify is
            // also not a usable hash, so the load path drops it instead of
            // restoring a key nothing can authenticate as. Three of these
            // carry the `$ssha256$` tag, which is why "usable" is a full
            // decode and not a prefix test.
            assert!(
                !is_usable_hash(stored),
                "{stored:?} can never verify, so it must not count as a usable hash"
            );
        }
    }

    /// A record whose digest hex is valid but whose salt is wrong must fail —
    /// i.e. the salt is really mixed in, not decorative.
    #[test]
    fn the_salt_participates() {
        let stored = hash_secret("secret");
        let (salt, digest) = decode(&stored).expect("decodes");
        let mut other_salt = salt.clone();
        other_salt[0] ^= 0xFF;
        let tampered = encode(&other_salt, &digest);
        assert!(!verify_secret("secret", &tampered));
    }
}

//! Deterministic retained-capacity estimates for immutable segment caches.
//!
//! These estimates are intentionally conservative and saturating. They are
//! neither allocator identities nor RSS measurements.

use serde_json::Value;

fn usize_u64(value: usize) -> u64 {
    u64::try_from(value).unwrap_or(u64::MAX)
}

fn capacity_bytes<T>(capacity: usize) -> u64 {
    usize_u64(capacity).saturating_mul(usize_u64(std::mem::size_of::<T>()))
}

/// Key, resident wrapper, Arc counters, and a conservative DashMap
/// slot/control allowance. `resident_inline_size` must be
/// `size_of::<CacheResident<T>>()` for the map's exact resident type.
pub fn common_entry_bytes(key: &String, resident_inline_size: usize) -> u64 {
    usize_u64(resident_inline_size)
        .saturating_add(usize_u64(2 * std::mem::size_of::<usize>()))
        .saturating_add(usize_u64(std::mem::size_of::<String>()))
        .saturating_add(usize_u64(key.capacity()))
        .saturating_add(usize_u64(6 * std::mem::size_of::<usize>()))
}

pub fn stored_slices_bytes(
    key: &String,
    resident_inline_size: usize,
    bytes_capacity: usize,
    offsets_capacity: usize,
) -> u64 {
    common_entry_bytes(key, resident_inline_size)
        .saturating_add(usize_u64(bytes_capacity))
        .saturating_add(capacity_bytes::<(u32, u32)>(offsets_capacity))
}

pub fn decoded_stored_bytes(
    key: &String,
    resident_inline_size: usize,
    bytes_capacity: usize,
) -> u64 {
    common_entry_bytes(key, resident_inline_size).saturating_add(usize_u64(bytes_capacity))
}

pub fn row_sequences_bytes(key: &String, resident_inline_size: usize, capacity: usize) -> u64 {
    common_entry_bytes(key, resident_inline_size).saturating_add(capacity_bytes::<u64>(capacity))
}

pub fn sort_shadow_bytes(
    key: &String,
    resident_inline_size: usize,
    capacity: Option<usize>,
) -> u64 {
    common_entry_bytes(key, resident_inline_size).saturating_add(
        capacity
            .map(|capacity| {
                usize_u64(std::mem::size_of::<Vec<(i64, u32)>>())
                    .saturating_add(usize_u64(2 * std::mem::size_of::<usize>()))
                    .saturating_add(capacity_bytes::<(i64, u32)>(capacity))
            })
            .unwrap_or_default(),
    )
}

pub fn id_positions_bytes(
    key: &String,
    resident_inline_size: usize,
    map: &std::collections::HashMap<String, u32>,
) -> u64 {
    let slots = usize_u64(map.capacity()).saturating_mul(
        usize_u64(std::mem::size_of::<(String, u32)>())
            .saturating_add(usize_u64(std::mem::size_of::<usize>())),
    );
    common_entry_bytes(key, resident_inline_size)
        .saturating_add(slots)
        .saturating_add(map.keys().fold(0_u64, |total, value| {
            total.saturating_add(usize_u64(value.capacity()))
        }))
}

pub fn doc_values_bytes(
    key: &String,
    resident_inline_size: usize,
    columns: &std::collections::BTreeMap<String, xerj_storage::doc_values::Column>,
) -> u64 {
    let node_allowance = usize_u64(std::mem::size_of::<(
        String,
        xerj_storage::doc_values::Column,
        [usize; 3],
    )>());
    common_entry_bytes(key, resident_inline_size).saturating_add(columns.iter().fold(
        0_u64,
        |total, (field, column)| {
            total
                .saturating_add(usize_u64(field.capacity()))
                .saturating_add(node_allowance)
                .saturating_add(column.estimated_retained_bytes())
        },
    ))
}

/// Conservative retained estimate for values produced by serde_json
/// `from_slice` and then left insert-only. All stored-value cache callers meet
/// that precondition; arbitrary remove/reserve/shrink mutation would require a
/// different capacity proof.
pub fn stored_values_bytes(key: &String, resident_inline_size: usize, values: &Vec<Value>) -> u64 {
    common_entry_bytes(key, resident_inline_size)
        .saturating_add(capacity_bytes::<Value>(values.capacity()))
        .saturating_add(values.iter().fold(0_u64, |total, value| {
            total.saturating_add(value_owned_bytes(value))
        }))
}

fn value_owned_bytes(value: &Value) -> u64 {
    match value {
        Value::String(value) => usize_u64(value.capacity()),
        Value::Array(values) => capacity_bytes::<Value>(values.capacity()).saturating_add(
            values.iter().fold(0_u64, |total, value| {
                total.saturating_add(value_owned_bytes(value))
            }),
        ),
        Value::Object(values) => {
            // Pinned serde_json 1.0.149 preserve_order → IndexMap 2.14 →
            // hashbrown 0.16. For from_slice/insert-only maps, growth leaves
            // dense entry capacity <= max(3, 2*n). The raw index table is
            // power-of-two and bounded by max(4, 2*entry_capacity). Charge a
            // full usize index plus one control byte per bucket even though
            // IndexMap uses narrower adaptive indices, plus fixed
            // control/alignment slack.
            let len = values.len();
            let entry_capacity = if len == 0 {
                0
            } else {
                len.saturating_mul(2).max(3)
            };
            let bucket_capacity = if entry_capacity == 0 {
                0
            } else {
                entry_capacity.saturating_mul(2).max(4)
            };
            let dense = capacity_bytes::<(u64, String, Value)>(entry_capacity);
            let hash_index = usize_u64(bucket_capacity)
                .saturating_mul(usize_u64(std::mem::size_of::<usize>() + 1))
                .saturating_add(if bucket_capacity == 0 { 0 } else { 64 });
            dense
                .saturating_add(hash_index)
                .saturating_add(values.iter().fold(0_u64, |total, (key, value)| {
                    total
                        .saturating_add(usize_u64(key.capacity()))
                        .saturating_add(value_owned_bytes(value))
                }))
        }
        Value::Null | Value::Bool(_) | Value::Number(_) => 0,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn capacity_and_nested_json_are_counted() {
        let key = String::with_capacity(64);
        assert!(
            decoded_stored_bytes(&key, 32, 128) > decoded_stored_bytes(&String::from("x"), 32, 1)
        );

        let mut nested = Vec::with_capacity(8);
        nested.push(Value::String(String::from("owned")));
        let values = vec![Value::Array(nested)];
        let segment = String::from("seg");
        let estimate = stored_values_bytes(&segment, 64, &values);
        assert!(estimate > common_entry_bytes(&segment, 64));

        let shadow_key = String::from("seg\u{1}field");
        let none = sort_shadow_bytes(&shadow_key, 32, None);
        let some_empty = sort_shadow_bytes(&shadow_key, 32, Some(0));
        assert!(none > 0);
        assert!(
            some_empty
                >= none
                    .saturating_add(std::mem::size_of::<Vec<(i64, u32)>>() as u64)
                    .saturating_add((2 * std::mem::size_of::<usize>()) as u64)
        );

        let mut object = serde_json::Map::new();
        object.insert(
            String::with_capacity(48),
            Value::Object(serde_json::Map::with_capacity(16)),
        );
        let object_value = Value::Object(object);
        assert!(value_owned_bytes(&object_value) > 0);
    }

    #[test]
    fn insert_only_indexmap_bound_is_monotonic_at_growth_edges() {
        let mut previous = 0;
        for len in [1_usize, 3, 4, 7, 8, 15] {
            let mut object = serde_json::Map::new();
            for i in 0..len {
                object.insert(format!("key-{i}"), Value::Number(i.into()));
            }
            let estimate = value_owned_bytes(&Value::Object(object));
            let entry_capacity = len.saturating_mul(2).max(3);
            let bucket_capacity = entry_capacity.saturating_mul(2).max(4);
            let fixed = capacity_bytes::<(u64, String, Value)>(entry_capacity)
                .saturating_add(
                    usize_u64(bucket_capacity)
                        .saturating_mul(usize_u64(std::mem::size_of::<usize>() + 1)),
                )
                .saturating_add(64);
            assert!(estimate >= fixed);
            assert!(estimate >= previous);
            previous = estimate;
        }
    }

    #[test]
    fn formulas_saturate_instead_of_wrapping() {
        let key = String::from("seg");
        assert_eq!(
            decoded_stored_bytes(&key, usize::MAX, usize::MAX),
            u64::try_from(usize::MAX)
                .unwrap_or(u64::MAX)
                .saturating_add(u64::try_from(usize::MAX).unwrap_or(u64::MAX))
                .saturating_add(
                    u64::try_from(
                        2 * std::mem::size_of::<usize>()
                            + std::mem::size_of::<String>()
                            + key.capacity()
                            + 6 * std::mem::size_of::<usize>(),
                    )
                    .unwrap_or(u64::MAX),
                )
        );
    }
}

//! Slow query log — v0.8 8-P6.
//!
//! When a search exceeds a configurable wall-clock threshold (default
//! 1 second), record a structured entry into a bounded ring buffer.
//! The most-recent N entries can be retrieved via the admin endpoint
//! `GET /v1/admin/slow_queries` so an operator can debug "why is this
//! cluster suddenly slow?" without enabling a full debug log.
//!
//! Design notes:
//! - Bounded by capacity (default 256) — we never grow unbounded under
//!   a runaway slow-query workload.
//! - Lock-free reads: the buffer is a single `parking_lot::RwLock` and
//!   readers take a shared lock to clone the snapshot.
//! - Append is O(1): grow until capacity, then overwrite oldest.
//! - Threshold is per-process global; per-index overrides can be added
//!   later if needed (most cluster-debug scenarios want a single knob).
//! - Each entry carries the query body, bounded to [`SLOW_QUERY_MAX_BODY`]
//!   chars so an operator can see *what* was slow — not just that something
//!   was. The cap keeps the ring safe to serialize over the admin endpoint
//!   even at full capacity (256 × 2 KB ≈ 512 KB worst case).
//! - This is the single source of truth for slow-query observability: the
//!   `tracing` warn/error line is emitted from inside [`maybe_record`] using
//!   the SAME runtime threshold as the ring buffer, so the log and the buffer
//!   can never disagree and both track the hot-reloadable knob.
//!
//! A future enhancement will export this as a Prometheus histogram + counter
//! (`xerj_search_slow_total`) so the operator can graph slow-query rates per
//! index in Grafana.

use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

/// Default threshold: 1 second.
pub const DEFAULT_SLOW_QUERY_MS: u64 = 1_000;
/// Default ring buffer capacity.
pub const DEFAULT_SLOW_QUERY_CAPACITY: usize = 256;
/// Max chars of the query body retained per entry (and emitted on the tracing
/// line). Keeps the bounded ring small and safe to serialize even at full
/// capacity, and stops a pathological multi-megabyte query DSL from bloating
/// either the buffer or a log line.
pub const SLOW_QUERY_MAX_BODY: usize = 2_048;

/// Truncate a query body to [`SLOW_QUERY_MAX_BODY`] chars on a UTF-8 char
/// boundary, appending an ellipsis when clipped.
fn truncate_body(s: &str) -> String {
    if s.len() <= SLOW_QUERY_MAX_BODY {
        return s.to_string();
    }
    let mut end = SLOW_QUERY_MAX_BODY;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &s[..end])
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SlowQueryEntry {
    /// Wall-clock time of the request, milliseconds since epoch.
    pub at_ms: u64,
    /// Index name (or "_all", "_search").
    pub index: String,
    /// Query type / route (e.g. "search", "search/agg", "knn").
    pub op: String,
    /// Total wall-clock duration in milliseconds.
    pub took_ms: u64,
    /// Number of hits (or 0 for size:0 / aggs-only).
    pub hits: u64,
    /// Optional short reason (e.g. "many segments scanned", "agg fan-out").
    pub note: String,
    /// The query body (bounded to [`SLOW_QUERY_MAX_BODY`] chars). Search
    /// callers fill this via [`logged_search_query`], so an omitted clause
    /// is recorded as `{"match_all":{}}` (what the engine runs) and a
    /// top-level `knn` is recorded with the query instead of an empty
    /// `query=` field. This is what makes an entry *actionable* — the
    /// operator sees the exact DSL that ran slow.
    pub query: String,
}

/// Text stored in [`SlowQueryEntry::query`] for one search.
///
/// An omitted query is match_all. A top-level `knn` with no query clause is
/// the knn object, not an empty string — an empty `query=` on the tracing
/// line reads as "the body was lost". Null clauses are treated as absent.
/// When both are present the entry keeps both, because logging only `query`
/// hides the knn that may be why the search was slow.
pub fn logged_search_query(
    query: Option<&serde_json::Value>,
    knn: Option<&serde_json::Value>,
) -> String {
    let query = query.filter(|q| !q.is_null());
    let knn = knn.filter(|k| !k.is_null());
    match (query, knn) {
        (Some(q), None) => q.to_string(),
        (Some(q), Some(knn)) => serde_json::json!({"query": q, "knn": knn}).to_string(),
        (None, Some(knn)) => serde_json::json!({"knn": knn}).to_string(),
        (None, None) => r#"{"match_all":{}}"#.to_string(),
    }
}

/// Bounded ring buffer of slow query entries.
pub struct SlowQueryLog {
    buf: RwLock<Vec<SlowQueryEntry>>,
    capacity: usize,
    threshold_ms: AtomicU64,
    /// Total slow events ever observed (for metrics / sanity).
    total: AtomicU64,
}

impl SlowQueryLog {
    pub fn new(capacity: usize, threshold_ms: u64) -> Arc<Self> {
        Arc::new(Self {
            buf: RwLock::new(Vec::with_capacity(capacity)),
            capacity,
            threshold_ms: AtomicU64::new(threshold_ms),
            total: AtomicU64::new(0),
        })
    }

    /// Threshold getter (atomic).
    pub fn threshold_ms(&self) -> u64 {
        self.threshold_ms.load(Ordering::Relaxed)
    }

    /// Threshold setter (atomic) — can be hot-reloaded from config.
    pub fn set_threshold_ms(&self, ms: u64) {
        self.threshold_ms.store(ms, Ordering::Relaxed);
    }

    /// Total slow events observed since process start.
    pub fn total_slow(&self) -> u64 {
        self.total.load(Ordering::Relaxed)
    }

    /// If `took >= threshold`, record an entry AND emit the slow-query
    /// tracing line. No-op otherwise. Returns `true` if the entry was
    /// recorded.
    ///
    /// This is the ONE place slow queries are surfaced. Both the ring buffer
    /// and the `tracing` warn/error line are gated on the same runtime
    /// `threshold_ms` knob (hot-reloadable via `set_threshold_ms`), so they
    /// can never drift apart — previously the ring buffer respected the knob
    /// while `Index::search` logged against hardcoded 1s/5s thresholds.
    /// `error!` fires at 5× the knob, `warn!` at 1×.
    pub fn maybe_record(
        &self,
        index: &str,
        op: &str,
        took: Duration,
        hits: u64,
        note: &str,
        query: &str,
    ) -> bool {
        let took_ms = took.as_millis() as u64;
        let threshold = self.threshold_ms.load(Ordering::Relaxed);
        if took_ms < threshold {
            return false;
        }
        self.total.fetch_add(1, Ordering::Relaxed);
        let query = truncate_body(query);
        // Unified tracing — same threshold as the ring buffer above.
        if took_ms >= threshold.saturating_mul(5) {
            tracing::error!(took_ms, index, op, hits, query = %query, "slow query");
        } else {
            tracing::warn!(took_ms, index, op, hits, query = %query, "slow query");
        }
        let entry = SlowQueryEntry {
            at_ms: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis() as u64)
                .unwrap_or(0),
            index: index.to_string(),
            op: op.to_string(),
            took_ms,
            hits,
            note: note.to_string(),
            query,
        };
        let mut buf = self.buf.write();
        if buf.len() < self.capacity {
            buf.push(entry);
        } else {
            // Rotate: drop oldest, push newest.  Over-large capacities
            // are rare so the O(N) shift is acceptable; if this ever
            // matters we can switch to a true ring with head index.
            buf.remove(0);
            buf.push(entry);
        }
        true
    }

    /// Snapshot the current buffer (cheap clone of N small structs).
    pub fn snapshot(&self) -> Vec<SlowQueryEntry> {
        self.buf.read().clone()
    }

    /// Clear the buffer (e.g. after operator inspection).
    pub fn clear(&self) {
        self.buf.write().clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn under_threshold_no_record() {
        let log = SlowQueryLog::new(8, 1000);
        let recorded = log.maybe_record("idx", "search", Duration::from_millis(500), 10, "", "");
        assert!(!recorded);
        assert!(log.snapshot().is_empty());
        assert_eq!(log.total_slow(), 0);
    }

    #[test]
    fn over_threshold_records() {
        let log = SlowQueryLog::new(8, 1000);
        let recorded = log.maybe_record(
            "idx",
            "search",
            Duration::from_millis(1500),
            10,
            "test",
            r#"{"match_all":{}}"#,
        );
        assert!(recorded);
        let snap = log.snapshot();
        assert_eq!(snap.len(), 1);
        assert_eq!(snap[0].took_ms, 1500);
        assert_eq!(snap[0].index, "idx");
        // The query body is captured so the entry is actionable.
        assert_eq!(snap[0].query, r#"{"match_all":{}}"#);
        assert_eq!(log.total_slow(), 1);
    }

    #[test]
    fn ring_rotates_at_capacity() {
        let log = SlowQueryLog::new(2, 100);
        for i in 0..5 {
            log.maybe_record("idx", "search", Duration::from_millis(200 + i), i, "", "");
        }
        let snap = log.snapshot();
        assert_eq!(snap.len(), 2);
        // Oldest two were dropped; we should see the last two.
        assert_eq!(snap[0].took_ms, 203);
        assert_eq!(snap[1].took_ms, 204);
        assert_eq!(log.total_slow(), 5);
    }

    #[test]
    fn threshold_can_be_updated() {
        let log = SlowQueryLog::new(8, 1000);
        log.set_threshold_ms(50);
        assert_eq!(log.threshold_ms(), 50);
        let recorded = log.maybe_record("idx", "search", Duration::from_millis(100), 0, "", "");
        assert!(recorded);
    }

    #[test]
    fn long_query_body_is_truncated_on_char_boundary() {
        let log = SlowQueryLog::new(4, 100);
        // A multibyte body larger than the cap must be clipped without
        // panicking on a char boundary, and marked with an ellipsis.
        let big = "é".repeat(SLOW_QUERY_MAX_BODY); // 2 bytes each ⇒ well over the cap
        let recorded = log.maybe_record("idx", "search", Duration::from_millis(200), 1, "", &big);
        assert!(recorded);
        let snap = log.snapshot();
        assert_eq!(snap.len(), 1);
        let stored = &snap[0].query;
        assert!(
            stored.ends_with('…'),
            "clipped body should end with an ellipsis"
        );
        // Body (minus the ellipsis) never exceeds the byte cap.
        assert!(stored.len() <= SLOW_QUERY_MAX_BODY + '…'.len_utf8());
    }

    #[test]
    fn logged_search_query_is_never_empty() {
        let knn = serde_json::json!({"field": "embedding", "query_vector": [0.1, 0.2], "k": 10});
        let lexical = serde_json::json!({"match": {"body": "rotate keys"}});

        let omitted = logged_search_query(None, None);
        assert_eq!(omitted, r#"{"match_all":{}}"#);
        assert!(!omitted.is_empty());

        let nulls = logged_search_query(
            Some(&serde_json::Value::Null),
            Some(&serde_json::Value::Null),
        );
        assert_eq!(nulls, r#"{"match_all":{}}"#);

        assert_eq!(
            logged_search_query(Some(&lexical), None),
            lexical.to_string()
        );

        let knn_only = logged_search_query(None, Some(&knn));
        assert_eq!(knn_only, serde_json::json!({"knn": knn}).to_string());
        assert!(!knn_only.is_empty());

        let both = logged_search_query(Some(&lexical), Some(&knn));
        assert_eq!(
            both,
            serde_json::json!({"query": lexical, "knn": knn}).to_string()
        );
        assert!(both.contains("\"knn\""));
        assert!(both.contains("rotate keys"));
    }
}

//! Minimal SQL → Query DSL translator.
//!
//! Supports:
//! ```sql
//! -- Basic query
//! SELECT field1, field2 FROM index WHERE cond AND cond ORDER BY field [ASC|DESC] LIMIT n
//!
//! -- Distinct (de-duplicate by all returned fields)
//! SELECT DISTINCT field1, field2 FROM index WHERE cond
//!
//! -- GROUP BY with COUNT / COUNT(DISTINCT field)
//! SELECT field, COUNT(*) FROM index GROUP BY field
//! SELECT field, COUNT(DISTINCT other_field) FROM index GROUP BY field
//! ```
//!
//! `GROUP BY` is translated to a `terms` aggregation; `COUNT(DISTINCT field)`
//! becomes a `cardinality` sub-aggregation.  The results are returned as ES
//! aggregation buckets rather than tabular rows.

use xerj_query::ast::QueryNode;
use xerj_query::sort::{SortField, SortOrder};

/// An aggregate function found in the SELECT list.
#[derive(Debug, Clone, PartialEq)]
pub enum AggFunction {
    /// `COUNT(*)`
    CountAll,
    /// `COUNT(DISTINCT field)`
    CountDistinct(String),
    /// `COUNT(field)` — count of non-null values
    CountField(String),
}

/// A parsed SQL query.
pub struct SqlQuery {
    /// Target index name.
    pub index: String,
    /// Fields to return (`["*"]` means all).
    pub fields: Vec<String>,
    /// Translated query node.
    pub query: QueryNode,
    /// LIMIT value (if present).
    pub limit: Option<usize>,
    /// ORDER BY fields.
    pub sort: Vec<SortField>,
    /// `SELECT DISTINCT` was specified — results should be deduplicated.
    pub distinct: bool,
    /// GROUP BY fields.
    pub group_by: Vec<String>,
    /// Aggregate functions referenced in the SELECT list.
    pub agg_functions: Vec<AggFunction>,
}

// ── Tokeniser ─────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Word(String),
    Num(f64),
    Str(String),
    Eq,
    Ne,
    Gt,
    Ge,
    Lt,
    Le,
    LParen,
    RParen,
    Comma,
    Star,
}

fn tokenise(sql: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = sql.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        match chars[i] {
            ' ' | '\t' | '\n' | '\r' => {
                i += 1;
            }
            ',' => {
                tokens.push(Token::Comma);
                i += 1;
            }
            '(' => {
                tokens.push(Token::LParen);
                i += 1;
            }
            ')' => {
                tokens.push(Token::RParen);
                i += 1;
            }
            '*' => {
                tokens.push(Token::Star);
                i += 1;
            }
            '>' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Ge);
                    i += 2;
                } else {
                    tokens.push(Token::Gt);
                    i += 1;
                }
            }
            '<' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Le);
                    i += 2;
                } else if i + 1 < chars.len() && chars[i + 1] == '>' {
                    tokens.push(Token::Ne);
                    i += 2;
                } else {
                    tokens.push(Token::Lt);
                    i += 1;
                }
            }
            '!' => {
                if i + 1 < chars.len() && chars[i + 1] == '=' {
                    tokens.push(Token::Ne);
                    i += 2;
                } else {
                    i += 1;
                }
            }
            '=' => {
                tokens.push(Token::Eq);
                i += 1;
            }
            '\'' | '"' => {
                let quote = chars[i];
                i += 1;
                let mut s = String::new();
                while i < chars.len() && chars[i] != quote {
                    if chars[i] == '\\' && i + 1 < chars.len() {
                        i += 1;
                        s.push(chars[i]);
                    } else {
                        s.push(chars[i]);
                    }
                    i += 1;
                }
                if i < chars.len() {
                    i += 1;
                } // consume closing quote
                tokens.push(Token::Str(s));
            }
            c if c.is_ascii_digit()
                || (c == '-' && i + 1 < chars.len() && chars[i + 1].is_ascii_digit()) =>
            {
                let start = i;
                if chars[i] == '-' {
                    i += 1;
                }
                while i < chars.len() && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    i += 1;
                }
                let raw: String = chars[start..i].iter().collect();
                let n: f64 = raw.parse().unwrap_or(0.0);
                tokens.push(Token::Num(n));
            }
            c if c.is_alphabetic() || c == '_' || c == '.' => {
                let start = i;
                while i < chars.len()
                    && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '.')
                {
                    i += 1;
                }
                let word: String = chars[start..i].iter().collect();
                tokens.push(Token::Word(word));
            }
            _ => {
                i += 1;
            }
        }
    }
    tokens
}

// ── Parser ────────────────────────────────────────────────────────────────────

/// Parse a SQL string.
///
/// Returns `(index, query, fields, limit, sort)`.
pub fn parse_sql(sql: &str) -> Result<SqlQuery, String> {
    let tokens = tokenise(sql);
    let mut pos = 0usize;

    // Helper closures.
    let peek = |pos: usize| -> Option<&Token> { tokens.get(pos) };
    let peek_word = |pos: usize| -> Option<String> {
        match tokens.get(pos) {
            Some(Token::Word(w)) => Some(w.to_uppercase()),
            _ => None,
        }
    };

    // SELECT
    match peek_word(pos) {
        Some(w) if w == "SELECT" => {
            pos += 1;
        }
        _ => return Err("Expected SELECT".to_string()),
    }

    // Optional DISTINCT after SELECT
    let distinct = if peek_word(pos).as_deref() == Some("DISTINCT") {
        pos += 1;
        true
    } else {
        false
    };

    // Fields / aggregate expressions
    let mut fields: Vec<String> = Vec::new();
    let mut agg_functions: Vec<AggFunction> = Vec::new();
    loop {
        match peek(pos) {
            Some(Token::Star) => {
                fields.push("*".to_string());
                pos += 1;
            }
            Some(Token::Word(w)) => {
                let upper = w.to_uppercase();
                if upper == "FROM"
                    || upper == "GROUP"
                    || upper == "ORDER"
                    || upper == "LIMIT"
                    || upper == "WHERE"
                {
                    break;
                }
                if upper == "COUNT" {
                    pos += 1;
                    // Consume `(`
                    if let Some(Token::LParen) = peek(pos) {
                        pos += 1;
                    } else {
                        return Err("Expected '(' after COUNT".to_string());
                    }
                    // Check for DISTINCT
                    if peek_word(pos).as_deref() == Some("DISTINCT") {
                        pos += 1;
                        // Field name or *
                        match peek(pos) {
                            Some(Token::Word(f)) if f.to_uppercase() != "FROM" => {
                                let field_name = f.clone();
                                pos += 1;
                                agg_functions.push(AggFunction::CountDistinct(field_name));
                            }
                            Some(Token::Star) => {
                                pos += 1;
                                agg_functions.push(AggFunction::CountAll);
                            }
                            _ => return Err("Expected field name after COUNT(DISTINCT".to_string()),
                        }
                    } else {
                        match peek(pos) {
                            Some(Token::Star) => {
                                pos += 1;
                                agg_functions.push(AggFunction::CountAll);
                            }
                            Some(Token::Word(f)) => {
                                let field_name = f.clone();
                                pos += 1;
                                agg_functions.push(AggFunction::CountField(field_name));
                            }
                            _ => return Err("Expected field or * after COUNT(".to_string()),
                        }
                    }
                    // Consume `)`
                    if let Some(Token::RParen) = peek(pos) {
                        pos += 1;
                    } else {
                        return Err("Expected ')' to close COUNT(...)".to_string());
                    }
                } else {
                    fields.push(w.clone());
                    pos += 1;
                }
            }
            _ => break,
        }
        // Consume optional comma.
        if let Some(Token::Comma) = peek(pos) {
            pos += 1;
        } else {
            break;
        }
    }
    if fields.is_empty() && agg_functions.is_empty() {
        return Err("No fields in SELECT".to_string());
    }

    // FROM
    match peek_word(pos) {
        Some(w) if w == "FROM" => {
            pos += 1;
        }
        _ => return Err("Expected FROM".to_string()),
    }

    // Index name.
    let index = match peek(pos) {
        Some(Token::Word(w)) => {
            let s = w.clone();
            pos += 1;
            s
        }
        _ => return Err("Expected index name after FROM".to_string()),
    };

    // Optional WHERE.
    let query: QueryNode = if peek_word(pos).as_deref() == Some("WHERE") {
        pos += 1;
        parse_or_expr(&tokens, &mut pos, 0)?
    } else {
        QueryNode::MatchAll
    };

    // Optional GROUP BY.
    let mut group_by: Vec<String> = Vec::new();
    if peek_word(pos).as_deref() == Some("GROUP") {
        pos += 1;
        if peek_word(pos).as_deref() == Some("BY") {
            pos += 1;
        }
        while let Some(Token::Word(field)) = peek(pos) {
            let upper = field.to_uppercase();
            if upper == "ORDER" || upper == "LIMIT" || upper == "HAVING" {
                break;
            }
            group_by.push(field.clone());
            pos += 1;
            if let Some(Token::Comma) = peek(pos) {
                pos += 1;
            } else {
                break;
            }
        }
    }

    // HAVING is not supported over /_sql. There is no GROUP BY execution path
    // here to filter post-aggregation, so silently skipping the predicate would
    // return ungrouped rows that ignore the filter — a wrong answer. Fail loud
    // with a parse error that the /_sql handler surfaces as a 400 invalid_query.
    if peek_word(pos).as_deref() == Some("HAVING") {
        return Err("HAVING clause is not supported over /_sql".to_string());
    }

    // Optional ORDER BY.
    let mut sort: Vec<SortField> = Vec::new();
    if peek_word(pos).as_deref() == Some("ORDER") {
        pos += 1;
        if peek_word(pos).as_deref() == Some("BY") {
            pos += 1;
        }
        while let Some(Token::Word(field)) = peek(pos) {
            let field = field.clone();
            pos += 1;
            let order = match peek_word(pos).as_deref() {
                Some("DESC") => {
                    pos += 1;
                    SortOrder::Desc
                }
                Some("ASC") => {
                    pos += 1;
                    SortOrder::Asc
                }
                _ => SortOrder::Asc,
            };
            sort.push(SortField {
                field,
                order,
                mode: xerj_query::sort::SortMode::default(),
                missing: xerj_query::sort::SortMissing::default(),
                format: None,
                unmapped_type: None,
                numeric_type: None,
            });
            if let Some(Token::Comma) = peek(pos) {
                pos += 1;
            } else {
                break;
            }
        }
    }

    // Optional LIMIT.
    let mut limit: Option<usize> = None;
    if peek_word(pos).as_deref() == Some("LIMIT") {
        pos += 1;
        match peek(pos) {
            Some(Token::Num(n)) => {
                limit = Some(*n as usize);
            }
            _ => return Err("Expected number after LIMIT".to_string()),
        }
    }

    Ok(SqlQuery {
        index,
        fields,
        query,
        limit,
        sort,
        distinct,
        group_by,
        agg_functions,
    })
}

// ── Condition parser (recursive descent) ─────────────────────────────────────

/// Cap on WHERE-clause nesting depth. `parse_or_expr → parse_and_expr →
/// parse_condition → parse_or_expr` is a recursion cycle driven one turn per
/// `(` (and `parse_condition` self-recurses on `NOT`), so without a bound a
/// `WHERE ((((…))))` with tens of thousands of parens overflows the thread
/// stack and aborts the whole process (SIGABRT — not a catchable panic). 64
/// mirrors `xerj-query`'s `MAX_QUERY_DEPTH` for the query_string parser; no
/// legitimate SQL nests that deep.
const MAX_SQL_DEPTH: usize = 64;

fn parse_or_expr(tokens: &[Token], pos: &mut usize, depth: usize) -> Result<QueryNode, String> {
    if depth > MAX_SQL_DEPTH {
        return Err(format!(
            "WHERE clause nesting exceeds max depth of {MAX_SQL_DEPTH}"
        ));
    }
    let left = parse_and_expr(tokens, pos, depth)?;
    let mut clauses = vec![left];

    while let Some(w) = peek_word_at(tokens, *pos) {
        if w == "OR" {
            *pos += 1;
            clauses.push(parse_and_expr(tokens, pos, depth)?);
        } else {
            break;
        }
    }

    if clauses.len() == 1 {
        Ok(clauses.remove(0))
    } else {
        Ok(QueryNode::Bool {
            must: vec![],
            filter: vec![],
            should: clauses,
            must_not: vec![],
            minimum_should_match: Some(xerj_query::ast::MinShouldMatch::Fixed(1)),
        })
    }
}

fn parse_and_expr(tokens: &[Token], pos: &mut usize, depth: usize) -> Result<QueryNode, String> {
    let left = parse_condition(tokens, pos, depth)?;
    let mut musts = vec![left];

    while let Some(w) = peek_word_at(tokens, *pos) {
        if w == "AND" {
            *pos += 1;
            musts.push(parse_condition(tokens, pos, depth)?);
        } else {
            break;
        }
    }

    if musts.len() == 1 {
        Ok(musts.remove(0))
    } else {
        Ok(QueryNode::Bool {
            must: musts,
            filter: vec![],
            should: vec![],
            must_not: vec![],
            minimum_should_match: None,
        })
    }
}

fn parse_condition(tokens: &[Token], pos: &mut usize, depth: usize) -> Result<QueryNode, String> {
    if depth > MAX_SQL_DEPTH {
        return Err(format!(
            "WHERE clause nesting exceeds max depth of {MAX_SQL_DEPTH}"
        ));
    }
    // Handle NOT / parenthesised groups.
    if let Some(Token::Word(w)) = tokens.get(*pos) {
        if w.to_uppercase() == "NOT" {
            *pos += 1;
            let inner = parse_condition(tokens, pos, depth + 1)?;
            return Ok(QueryNode::Bool {
                must: vec![],
                filter: vec![],
                should: vec![],
                must_not: vec![inner],
                minimum_should_match: None,
            });
        }
    }
    if let Some(Token::LParen) = tokens.get(*pos) {
        *pos += 1;
        let inner = parse_or_expr(tokens, pos, depth + 1)?;
        if let Some(Token::RParen) = tokens.get(*pos) {
            *pos += 1;
        }
        return Ok(inner);
    }

    // field op value
    let field = match tokens.get(*pos) {
        Some(Token::Word(f)) => {
            let f = f.clone();
            *pos += 1;
            f
        }
        _ => return Err(format!("Expected field name at pos {}", pos)),
    };

    let op = match tokens.get(*pos) {
        Some(Token::Eq) => {
            *pos += 1;
            "eq"
        }
        Some(Token::Ne) => {
            *pos += 1;
            "ne"
        }
        Some(Token::Gt) => {
            *pos += 1;
            "gt"
        }
        Some(Token::Ge) => {
            *pos += 1;
            "gte"
        }
        Some(Token::Lt) => {
            *pos += 1;
            "lt"
        }
        Some(Token::Le) => {
            *pos += 1;
            "lte"
        }
        Some(Token::Word(w)) if w.to_uppercase() == "LIKE" => {
            *pos += 1;
            "like"
        }
        Some(Token::Word(w)) if w.to_uppercase() == "NOT" => {
            // NOT LIKE
            *pos += 1;
            if let Some(Token::Word(w2)) = tokens.get(*pos) {
                if w2.to_uppercase() == "LIKE" {
                    *pos += 1;
                    "not_like"
                } else {
                    "ne"
                }
            } else {
                "ne"
            }
        }
        _ => return Err(format!("Expected operator at pos {}", pos)),
    };

    let value = match tokens.get(*pos) {
        Some(Token::Str(s)) => {
            let v = serde_json::Value::String(s.clone());
            *pos += 1;
            v
        }
        Some(Token::Num(n)) => {
            let v = serde_json::json!(*n);
            *pos += 1;
            v
        }
        Some(Token::Word(w)) => {
            let upper = w.to_uppercase();
            let v = if upper == "TRUE" {
                serde_json::Value::Bool(true)
            } else if upper == "FALSE" {
                serde_json::Value::Bool(false)
            } else if upper == "NULL" {
                serde_json::Value::Null
            } else {
                serde_json::Value::String(w.clone())
            };
            *pos += 1;
            v
        }
        _ => return Err(format!("Expected value at pos {}", pos)),
    };

    let node = match op {
        "eq" => {
            if let serde_json::Value::String(s) = &value {
                // Use match query for text fields.
                QueryNode::Match {
                    field: field.clone(),
                    query: s.clone(),
                    operator: xerj_query::ast::BoolOperator::default(),
                    boost: None,
                    minimum_should_match: None,
                    analyzer: None,
                    lenient: false,
                }
            } else {
                QueryNode::Term {
                    field: field.clone(),
                    value: value.clone(),
                    boost: None,
                }
            }
        }
        "ne" => QueryNode::Bool {
            must: vec![],
            filter: vec![],
            should: vec![],
            must_not: vec![QueryNode::Term {
                field: field.clone(),
                value: value.clone(),
                boost: None,
            }],
            minimum_should_match: None,
        },
        "gt" => make_range(&field, None, None, Some(value), None),
        "gte" => make_range(&field, None, None, None, Some(value)),
        "lt" => make_range(&field, Some(value), None, None, None),
        "lte" => make_range(&field, None, Some(value), None, None),
        "like" => {
            // Convert SQL LIKE pattern (% → *, _ → ?) to wildcard query.
            let pattern = value
                .as_str()
                .unwrap_or("*")
                .replace('%', "*")
                .replace('_', "?");
            QueryNode::Wildcard {
                field: field.clone(),
                value: pattern,
                boost: None,
                constant_score: false,
                case_insensitive: false,
            }
        }
        "not_like" => {
            let pattern = value
                .as_str()
                .unwrap_or("*")
                .replace('%', "*")
                .replace('_', "?");
            QueryNode::Bool {
                must: vec![],
                filter: vec![],
                should: vec![],
                must_not: vec![QueryNode::Wildcard {
                    field: field.clone(),
                    value: pattern,
                    boost: None,
                    constant_score: false,
                    case_insensitive: false,
                }],
                minimum_should_match: None,
            }
        }
        _ => QueryNode::MatchAll,
    };
    Ok(node)
}

fn make_range(
    field: &str,
    lt: Option<serde_json::Value>,
    lte: Option<serde_json::Value>,
    gt: Option<serde_json::Value>,
    gte: Option<serde_json::Value>,
) -> QueryNode {
    QueryNode::Range {
        field: field.to_string(),
        gt,
        gte,
        lt,
        lte,
        boost: None,
        lenient: false,
    }
}

fn peek_word_at(tokens: &[Token], pos: usize) -> Option<String> {
    match tokens.get(pos) {
        Some(Token::Word(w)) => Some(w.to_uppercase()),
        _ => None,
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_select() {
        let q = parse_sql("SELECT name, price FROM products WHERE price > 30 LIMIT 3").unwrap();
        assert_eq!(q.index, "products");
        assert_eq!(q.fields, vec!["name", "price"]);
        assert_eq!(q.limit, Some(3));
    }

    #[test]
    fn test_select_star() {
        let q = parse_sql("SELECT * FROM logs").unwrap();
        assert_eq!(q.fields, vec!["*"]);
        assert_eq!(q.index, "logs");
        assert!(matches!(q.query, QueryNode::MatchAll));
    }

    #[test]
    fn test_order_by() {
        let q = parse_sql("SELECT id FROM events ORDER BY created DESC LIMIT 10").unwrap();
        assert_eq!(q.sort.len(), 1);
        assert_eq!(q.sort[0].field, "created");
        assert!(matches!(q.sort[0].order, SortOrder::Desc));
    }

    #[test]
    fn test_having_rejected() {
        // HAVING has no GROUP BY execution path over /_sql; it must fail loud
        // (surfaced as 400 invalid_query) rather than silently drop the filter.
        let res = parse_sql(
            "SELECT category, COUNT(*) FROM products GROUP BY category HAVING COUNT(*) > 5",
        );
        match res {
            Err(err) => assert!(
                err.contains("HAVING"),
                "expected HAVING reject error, got: {err}"
            ),
            Ok(_) => panic!("expected HAVING clause to be rejected, but query parsed"),
        }
    }

    #[test]
    fn test_group_by_without_having_still_parses() {
        // A plain GROUP BY (no HAVING) must continue to parse unchanged.
        let q = parse_sql("SELECT category, COUNT(*) FROM products GROUP BY category").unwrap();
        assert_eq!(q.index, "products");
        assert_eq!(q.group_by, vec!["category"]);
    }

    #[test]
    fn test_deeply_nested_where_parens_do_not_overflow_stack() {
        // Regression: `parse_or_expr → parse_and_expr → parse_condition →
        // parse_or_expr` is a recursion cycle driven one turn per `(`. Before
        // the depth guard, ~50k nested parens overflowed the thread stack and
        // aborted the process. Now it returns a bounded parse error, no crash.
        let sql = format!(
            "SELECT * FROM t WHERE {}a = 1{}",
            "(".repeat(5_000),
            ")".repeat(5_000)
        );
        match parse_sql(&sql) {
            Err(e) => assert!(
                e.contains("depth"),
                "rejection should cite the depth cap: {e}"
            ),
            Ok(_) => panic!("deeply nested WHERE must be rejected, not parsed"),
        }
    }

    #[test]
    fn test_deeply_nested_not_does_not_overflow_stack() {
        // `NOT NOT NOT …` is the other arm of the same cycle (self-recursion
        // in parse_condition).
        let sql = format!("SELECT * FROM t WHERE {}a = 1", "NOT ".repeat(5_000));
        assert!(parse_sql(&sql).is_err());
    }

    #[test]
    fn test_moderate_where_nesting_still_parses() {
        // A realistic nesting depth (well under the 64 cap) must be unaffected.
        let q = parse_sql("SELECT * FROM t WHERE ((a = 1 OR b = 2) AND c = 3)").unwrap();
        assert_eq!(q.index, "t");
    }
}

//! Flat `f32` view of one vector field over one immutable segment (#939).
//!
//! The exact kNN scan used to deep-clone every stored `_source` — vectors
//! included, as `serde_json::Value::Number`s — into its candidate list, clone
//! it a second time to evaluate the filter, clone the passage-vector array a
//! third time through `get_field_value`, and then re-walk those JSON numbers
//! into a fresh `Vec<f32>` per passage. All of that ran per document, per
//! query, and none of it was arithmetic: on 5,183 multi-passage documents it
//! was ~400 ms around ~14 ms of model time.
//!
//! This module holds the vectors once, as plain `f32`s, per segment. Segments
//! are immutable, so the column is derived exactly once and then shared; which
//! documents are *live* is still decided per query, by the caller.
//!
//! # Reference designs (approach adapted, no code copied)
//!
//! * **Flattened multi-vector + `dim`.** qdrant stores a multi-vector as one
//!   contiguous buffer and slices it per sub-vector
//!   (`lib/segment/src/data_types/vectors.rs:271`, max-sim at
//!   `lib/segment/src/vector_storage/query_scorer/mod.rs:77`; Apache-2.0,
//!   74f3e85). Ours differs where XERJ's contract differs: one query vector,
//!   best passage wins, lowest ordinal on an exact tie, and passages may be
//!   skipped without renumbering the ones after them.
//! * **Score an address, hydrate the winners.** qdrant ranks
//!   `ScoredPointOffset { idx, score }` and only then retrieves payloads
//!   (`lib/segment/src/segment/read_view/search.rs:222`); tantivy ranks
//!   `DocAddress { segment_ord, doc_id }` and fetches stored documents by
//!   address (`src/lib.rs:338`, `src/core/searcher.rs:88`; MIT, 3a55bc9).
//!
//! # Exactness contract
//!
//! Scores produced from this column are **bit-identical** to the scan it
//! replaces. That is a property of construction, not of tolerance:
//!
//! * elements are converted with the same expression the scan used
//!   (`as_f64()` then `as f32`, non-numbers dropped);
//! * a vector whose converted length differs from the query's is skipped at
//!   query time, exactly as before, and keeps its original passage ordinal;
//! * a document whose `<field>_chunks` is an array with no usable passage is
//!   skipped — it does **not** fall back to the pooled vector, because the old
//!   scan did not;
//! * the dot product and the norms are the same strictly sequential `f64`
//!   reductions ([`dot_f64`], [`norm_f64`]), shared with
//!   `compute_vector_similarity` so the two cannot drift. Precomputing a
//!   document vector's norm stores the value the scan would have recomputed.

use serde_json::Value;
use std::borrow::Cow;

use crate::index::get_field_value;

/// Which stored vectors a column holds for each document.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) enum ColumnMode {
    /// `<field>_chunks` passage vectors when that companion is an array, the
    /// pooled `<field>` vector otherwise. The default exact scan.
    BestPassage,
    /// Always the pooled `<field>` vector. The `scalar8` scan reads only that.
    PooledOnly,
}

impl ColumnMode {
    /// Distinguishes the two shapes in a cache key.
    pub(crate) fn key_tag(self) -> char {
        match self {
            Self::BestPassage => 'c',
            Self::PooledOnly => 'p',
        }
    }
}

/// One stored vector: where it lives in the flat buffer, which passage it was,
/// and its Euclidean norm.
#[derive(Clone, Copy, Debug)]
struct VectorEntry {
    start: usize,
    len: usize,
    ordinal: u32,
    norm: f64,
}

/// The vectors one document contributes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DocVectors {
    /// Nothing usable: the scan skips the document.
    Absent,
    /// The pooled vector, reported as passage ordinal 0.
    Pooled(usize),
    /// `count` passage vectors starting at entry `first`. `count == 0` is a
    /// passage array with no usable element, which also skips the document.
    Chunks { first: usize, count: usize },
}

/// A borrowed stored vector handed to the scorer.
#[derive(Clone, Copy, Debug)]
pub(crate) struct StoredVector<'a> {
    pub(crate) values: &'a [f32],
    pub(crate) ordinal: u32,
    pub(crate) norm: f64,
}

/// What a document offers the scorer.
pub(crate) enum DocVectorsView<'a> {
    Absent,
    Pooled(StoredVector<'a>),
    Chunks(ChunkIter<'a>),
}

pub(crate) struct ChunkIter<'a> {
    column: &'a SegmentVectorColumn,
    next: usize,
    end: usize,
}

impl<'a> Iterator for ChunkIter<'a> {
    type Item = StoredVector<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.next >= self.end {
            return None;
        }
        let vector = self.column.stored(self.next);
        self.next += 1;
        Some(vector)
    }
}

/// Flat vectors for one field over a run of documents, addressed by position.
#[derive(Debug, Default)]
pub(crate) struct SegmentVectorColumn {
    data: Vec<f32>,
    entries: Vec<VectorEntry>,
    docs: Vec<DocVectors>,
    /// Each position's `_id` and `_seq_no`, when it was pushed as a stored
    /// segment document (#1091). These are the only two fields the exact scan
    /// reads from a document before ranking it, so a column that carries them
    /// lets an unfiltered scan choose its candidates without the segment's
    /// parsed stored documents — which, on a passage-chunked corpus, are tens
    /// of kilobytes each and do not fit the hydration budget.
    identities: Vec<Option<DocIdentity>>,
}

/// A stored document's `_id` and `_seq_no`, as the scan reads them.
#[derive(Debug)]
struct DocIdentity {
    id: Box<str>,
    seq_no: Option<u64>,
}

impl SegmentVectorColumn {
    /// Number of document positions covered. A column abandoned part-way (the
    /// request's deadline passed) covers a prefix of its segment.
    pub(crate) fn len(&self) -> usize {
        self.docs.len()
    }

    fn stored(&self, entry: usize) -> StoredVector<'_> {
        let e = &self.entries[entry];
        StoredVector {
            values: &self.data[e.start..e.start + e.len],
            ordinal: e.ordinal,
            norm: e.norm,
        }
    }

    /// The vectors of the document at `position`; `Absent` past the end.
    pub(crate) fn doc(&self, position: usize) -> DocVectorsView<'_> {
        match self.docs.get(position) {
            None | Some(DocVectors::Absent) => DocVectorsView::Absent,
            Some(DocVectors::Pooled(entry)) => DocVectorsView::Pooled(self.stored(*entry)),
            Some(DocVectors::Chunks { first, count }) => DocVectorsView::Chunks(ChunkIter {
                column: self,
                next: *first,
                end: first + count,
            }),
        }
    }

    /// The `_id` and `_seq_no` of the stored document at `position`. `None`
    /// past the end, for a document pushed by source alone (the memtable
    /// scratch), and for a stored document with no string `_id` — the scan
    /// never makes a candidate of that one.
    pub(crate) fn identity(&self, position: usize) -> Option<(&str, Option<u64>)> {
        self.identities
            .get(position)?
            .as_ref()
            .map(|identity| (&*identity.id, identity.seq_no))
    }

    /// Bytes this column keeps alive, for the segment hydration budget.
    pub(crate) fn retained_bytes(&self) -> u64 {
        let id_bytes: usize = self
            .identities
            .iter()
            .flatten()
            .map(|identity| identity.id.len())
            .sum();
        let bytes = self.data.capacity() * std::mem::size_of::<f32>()
            + self.entries.capacity() * std::mem::size_of::<VectorEntry>()
            + self.docs.capacity() * std::mem::size_of::<DocVectors>()
            + self.identities.capacity() * std::mem::size_of::<Option<DocIdentity>>()
            + id_bytes
            + std::mem::size_of::<Self>();
        u64::try_from(bytes).unwrap_or(u64::MAX)
    }
}

/// Builds a [`SegmentVectorColumn`] one document at a time, in position order.
pub(crate) struct ColumnBuilder {
    field: String,
    chunk_field: String,
    mode: ColumnMode,
    column: SegmentVectorColumn,
}

impl ColumnBuilder {
    pub(crate) fn new(field: &str, mode: ColumnMode) -> Self {
        Self {
            field: field.to_string(),
            chunk_field: format!("{field}_chunks"),
            mode,
            column: SegmentVectorColumn::default(),
        }
    }

    /// Forget every document but keep the allocations — the memtable path
    /// reuses one builder as per-document scratch.
    pub(crate) fn clear(&mut self) {
        self.column.data.clear();
        self.column.entries.clear();
        self.column.docs.clear();
        self.column.identities.clear();
    }

    /// The column built so far.
    pub(crate) fn column(&self) -> &SegmentVectorColumn {
        &self.column
    }

    pub(crate) fn finish(mut self) -> SegmentVectorColumn {
        self.column.data.shrink_to_fit();
        self.column.entries.shrink_to_fit();
        self.column.docs.shrink_to_fit();
        self.column.identities.shrink_to_fit();
        self.column
    }

    /// Append a segment's stored document: `{"_id", "_seq_no", "_source"}`,
    /// or a legacy pre-`_source` document whose fields sit at the top level.
    pub(crate) fn push_stored_doc(&mut self, stored: &Value) {
        self.push_vectors(stored_source_view(stored));
        let identity = stored
            .get("_id")
            .and_then(Value::as_str)
            .map(|id| DocIdentity {
                id: id.into(),
                seq_no: stored.get("_seq_no").and_then(Value::as_u64),
            });
        self.column.identities.push(identity);
    }

    /// Append a document given its source object.
    pub(crate) fn push_source(&mut self, source: &Value) {
        self.push_vectors(source);
        self.column.identities.push(None);
    }

    fn push_vectors(&mut self, source: &Value) {
        let doc = match self.mode {
            ColumnMode::PooledOnly => self.push_pooled(source),
            ColumnMode::BestPassage => match field_value_cow(source, &self.chunk_field) {
                Some(chunks) => match chunks.as_ref() {
                    Value::Array(chunks) => self.push_chunks(chunks),
                    _ => self.push_pooled(source),
                },
                None => self.push_pooled(source),
            },
        };
        self.column.docs.push(doc);
    }

    /// Append one row of a segment's typed kNN projection (#1091): the same
    /// document [`Self::push_stored_doc`] would have read, decoded straight to
    /// `f32` by the storage layer instead of through `serde_json::Value`.
    ///
    /// The storage decoder converts each element with the same `as_f64()` then
    /// `as f32` this builder uses, and refuses a column outright — the caller
    /// falls back to the stored documents — whenever a cell holds anything the
    /// `Value` path would have had to drop or skip (a non-number element, a
    /// non-finite value, a passage that is not an array). So every row it does
    /// hand over yields the entries `push_stored_doc` would have pushed:
    /// `chunks` present wins in [`ColumnMode::BestPassage`], a passage keeps
    /// its array index as its ordinal, and `None` is an absent or null cell.
    pub(crate) fn push_projected(
        &mut self,
        id: Option<&str>,
        seq_no: Option<u64>,
        pooled: Option<&[f32]>,
        chunks: Option<&[Vec<f32>]>,
    ) {
        let chunks = match self.mode {
            ColumnMode::BestPassage => chunks,
            ColumnMode::PooledOnly => None,
        };
        let doc = match (chunks, pooled) {
            (Some(chunks), _) => {
                let first = self.column.entries.len();
                for (position, chunk) in chunks.iter().enumerate() {
                    let Ok(ordinal) = u32::try_from(position) else {
                        continue;
                    };
                    self.push_f32_vector(chunk, ordinal);
                }
                DocVectors::Chunks {
                    first,
                    count: self.column.entries.len() - first,
                }
            }
            (None, Some(pooled)) => DocVectors::Pooled(self.push_f32_vector(pooled, 0)),
            (None, None) => DocVectors::Absent,
        };
        self.column.docs.push(doc);
        self.column.identities.push(id.map(|id| DocIdentity {
            id: id.into(),
            seq_no,
        }));
    }

    fn push_f32_vector(&mut self, values: &[f32], ordinal: u32) -> usize {
        let start = self.column.data.len();
        self.column.data.extend_from_slice(values);
        let norm = norm_f64(&self.column.data[start..]);
        self.column.entries.push(VectorEntry {
            start,
            len: values.len(),
            ordinal,
            norm,
        });
        self.column.entries.len() - 1
    }

    fn push_chunks(&mut self, chunks: &[Value]) -> DocVectors {
        let first = self.column.entries.len();
        for (position, chunk) in chunks.iter().enumerate() {
            // The ordinal is the passage's position in the ORIGINAL array, so
            // a skipped passage never renumbers the ones after it.
            let Ok(ordinal) = u32::try_from(position) else {
                continue;
            };
            match chunk {
                Value::Array(elements) => {
                    self.push_vector(elements, ordinal);
                }
                Value::String(text) => {
                    if let Some(values) = xerj_common::packed_f32::unpack_f32_vector(text) {
                        self.push_f32_vector(&values, ordinal);
                    }
                }
                _ => {}
            }
        }
        DocVectors::Chunks {
            first,
            count: self.column.entries.len() - first,
        }
    }

    fn push_pooled(&mut self, source: &Value) -> DocVectors {
        match field_value_cow(source, &self.field).as_deref() {
            Some(Value::Array(elements)) => DocVectors::Pooled(self.push_vector(elements, 0)),
            // #1940 packed form. Same f32 bits `push_vector` would have
            // produced from the number array.
            Some(Value::String(text)) => match xerj_common::packed_f32::unpack_f32_vector(text) {
                Some(values) => DocVectors::Pooled(self.push_f32_vector(&values, 0)),
                None => DocVectors::Absent,
            },
            _ => DocVectors::Absent,
        }
    }

    fn push_vector(&mut self, elements: &[Value], ordinal: u32) -> usize {
        let start = self.column.data.len();
        self.column
            .data
            .extend(elements.iter().filter_map(|v| v.as_f64().map(|f| f as f32)));
        let len = self.column.data.len() - start;
        let norm = norm_f64(&self.column.data[start..]);
        self.column.entries.push(VectorEntry {
            start,
            len,
            ordinal,
            norm,
        });
        self.column.entries.len() - 1
    }
}

/// The source object of a segment's stored document, without cloning it.
///
/// Reassembled segment documents are `{"_id", "_seq_no", "_source": {...}}`;
/// legacy pre-M7 segments keep the fields at the top level, beside `_id`.
pub(crate) fn stored_source_view(stored: &Value) -> &Value {
    stored.get("_source").unwrap_or(stored)
}

/// [`get_field_value`] without the clone when the field is a literal key at
/// the source root — which is where a vector field and its generated
/// companions live. Anything else (a dotted path, an array of objects, the
/// multi-field fallback) is answered by `get_field_value` itself, so the two
/// resolve identically by construction.
fn field_value_cow<'a>(source: &'a Value, field: &str) -> Option<Cow<'a, Value>> {
    if let Value::Object(map) = source {
        if let Some(value) = map.get(field) {
            return Some(Cow::Borrowed(value));
        }
    }
    get_field_value(source, field).map(Cow::Owned)
}

/// Strictly sequential `f64` dot product. Shared with
/// `compute_vector_similarity`; do not reorder or widen this reduction — a
/// different summation order changes the low bits of every score.
#[inline]
pub(crate) fn dot_f64(a: &[f32], b: &[f32]) -> f64 {
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| (*x as f64) * (*y as f64))
        .sum()
}

/// Strictly sequential `f64` Euclidean norm. Same warning as [`dot_f64`].
#[inline]
pub(crate) fn norm_f64(v: &[f32]) -> f64 {
    v.iter()
        .map(|x| (*x as f64) * (*x as f64))
        .sum::<f64>()
        .sqrt()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn views(column: &SegmentVectorColumn, position: usize) -> Vec<(u32, Vec<f32>)> {
        match column.doc(position) {
            DocVectorsView::Absent => Vec::new(),
            DocVectorsView::Pooled(v) => vec![(v.ordinal, v.values.to_vec())],
            DocVectorsView::Chunks(iter) => iter.map(|v| (v.ordinal, v.values.to_vec())).collect(),
        }
    }

    #[test]
    fn best_passage_prefers_the_chunk_companion_over_the_pooled_vector() {
        let mut b = ColumnBuilder::new("body_vector", ColumnMode::BestPassage);
        b.push_stored_doc(&json!({"_id": "a", "_source": {
            "body_vector": [9.0, 9.0],
            "body_vector_chunks": [[1.0, 0.0], [0.0, 1.0]],
        }}));
        let column = b.finish();
        assert_eq!(
            views(&column, 0),
            vec![(0, vec![1.0, 0.0]), (1, vec![0.0, 1.0])]
        );
    }

    #[test]
    fn skipped_passages_keep_the_ordinals_of_the_ones_after_them() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"v_chunks": [[1.0, 0.0], "not a vector", [0.0, 1.0]]}));
        let column = b.finish();
        assert_eq!(
            views(&column, 0),
            vec![(0, vec![1.0, 0.0]), (2, vec![0.0, 1.0])]
        );
    }

    #[test]
    fn an_empty_passage_array_skips_the_document_instead_of_falling_back() {
        // The scan this replaces `continue`d here; falling back to the pooled
        // vector would surface a document it never returned.
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"v": [1.0, 0.0], "v_chunks": ["x", 3]}));
        b.push_source(&json!({"v": [1.0, 0.0], "v_chunks": []}));
        let column = b.finish();
        assert!(views(&column, 0).is_empty());
        assert!(views(&column, 1).is_empty());
    }

    #[test]
    fn a_non_array_chunk_companion_falls_back_to_the_pooled_vector() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"v": [0.5, 0.25], "v_chunks": "nope"}));
        let column = b.finish();
        assert_eq!(views(&column, 0), vec![(0, vec![0.5, 0.25])]);
    }

    #[test]
    fn pooled_only_ignores_the_chunk_companion() {
        let mut b = ColumnBuilder::new("v", ColumnMode::PooledOnly);
        b.push_source(&json!({"v": [0.5, 0.25], "v_chunks": [[1.0, 0.0]]}));
        let column = b.finish();
        assert_eq!(views(&column, 0), vec![(0, vec![0.5, 0.25])]);
    }

    #[test]
    fn non_numeric_elements_are_dropped_like_the_scan_dropped_them() {
        // `filter_map(as_f64)` shortens the vector; the length check against
        // the query then rejects it at query time, as it always did.
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"v": [1.0, "x", 2.0]}));
        let column = b.finish();
        assert_eq!(views(&column, 0), vec![(0, vec![1.0, 2.0])]);
    }

    #[test]
    fn missing_and_non_array_vectors_are_absent_and_positions_stay_aligned() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"other": 1}));
        b.push_source(&json!({"v": "text"}));
        b.push_source(&json!({"v": [3.0]}));
        let column = b.finish();
        assert_eq!(column.len(), 3);
        assert!(views(&column, 0).is_empty());
        assert!(views(&column, 1).is_empty());
        assert_eq!(views(&column, 2), vec![(0, vec![3.0])]);
        assert!(views(&column, 99).is_empty(), "past the end is absent");
    }

    #[test]
    fn legacy_documents_without_source_are_read_at_the_top_level() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_stored_doc(&json!({"_id": "legacy", "v": [1.0, 2.0]}));
        let column = b.finish();
        assert_eq!(views(&column, 0), vec![(0, vec![1.0, 2.0])]);
    }

    #[test]
    fn stored_documents_carry_their_identity_and_sources_do_not() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_stored_doc(&json!({"_id": "a", "_seq_no": 7, "_source": {"v": [1.0]}}));
        b.push_stored_doc(&json!({"_id": "legacy", "v": [2.0]}));
        b.push_stored_doc(&json!({"_id": 3, "_source": {"v": [3.0]}}));
        b.push_source(&json!({"v": [4.0]}));
        let column = b.finish();
        assert_eq!(column.identity(0), Some(("a", Some(7))));
        assert_eq!(column.identity(1), Some(("legacy", None)));
        assert_eq!(column.identity(2), None, "a non-string _id is no candidate");
        assert_eq!(column.identity(3), None, "a bare source has no identity");
        assert_eq!(column.identity(99), None);
        let mut scratch = ColumnBuilder::new("v", ColumnMode::BestPassage);
        scratch.push_stored_doc(&json!({"_id": "a", "_source": {"v": [1.0]}}));
        scratch.clear();
        scratch.push_source(&json!({"v": [1.0]}));
        assert_eq!(
            scratch.column().identity(0),
            None,
            "clear forgets identities"
        );
    }

    #[test]
    fn dotted_vector_fields_resolve_through_get_field_value() {
        let mut b = ColumnBuilder::new("emb.v", ColumnMode::BestPassage);
        b.push_source(&json!({"emb": {"v": [1.0, 2.0]}}));
        let column = b.finish();
        assert_eq!(views(&column, 0), vec![(0, vec![1.0, 2.0])]);
    }

    #[test]
    fn stored_norm_is_the_value_the_scan_would_recompute() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"v": [0.1, -0.7, 0.33, 1e-3]}));
        let column = b.finish();
        let DocVectorsView::Pooled(v) = column.doc(0) else {
            panic!("expected a pooled vector");
        };
        assert_eq!(v.norm.to_bits(), norm_f64(v.values).to_bits());
    }

    #[test]
    fn clear_reuses_the_builder_as_scratch() {
        let mut b = ColumnBuilder::new("v", ColumnMode::BestPassage);
        b.push_source(&json!({"v": [1.0]}));
        b.clear();
        b.push_source(&json!({"v": [2.0]}));
        assert_eq!(b.column().len(), 1);
        assert_eq!(views(b.column(), 0), vec![(0, vec![2.0])]);
    }
}

//! Regressions for the per-index WAL shard override (`index.xerj_ingest_shards`).
//!
//! The override exists because each index eagerly opens one WAL file descriptor
//! per ingest shard, and the ingest-shard count scales with CPU cores: a few
//! hundred autoindex datasets exhausted the macOS fd limit. Two properties have
//! to hold or the fix is worse than the bug — the value must be *ignored* unless
//! it is a sane count, and it must be honored identically at create and on
//! reopen, since the WAL write layout (`wal/*.wal` vs `wal/s{N}/*.wal`) and doc
//! routing both derive from it.

use std::path::Path;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;

use super::{store_config_from, wal_shards_override_from_settings};
use crate::Engine;

fn settings_with(shards: Value) -> Value {
    json!({ "index": { "xerj_ingest_shards": shards } })
}

/// The `s{N}` shard subdirectories under an index's WAL root. Zero of them means
/// the single-shard (legacy root) layout; `IndexStore::open` creates one per
/// shard whenever the count is > 1, so this is the on-disk witness of the shard
/// count the store was actually opened with.
fn wal_shard_dirs(index_dir: &Path) -> usize {
    std::fs::read_dir(index_dir.join("wal"))
        .expect("wal dir")
        .flatten()
        .filter(|e| {
            e.path().is_dir()
                && e.file_name()
                    .to_string_lossy()
                    .strip_prefix('s')
                    .is_some_and(|n| n.parse::<usize>().is_ok())
        })
        .count()
}

fn root_wal_files(index_dir: &Path) -> usize {
    std::fs::read_dir(index_dir.join("wal"))
        .expect("wal dir")
        .flatten()
        .filter(|e| e.path().extension().is_some_and(|ext| ext == "wal"))
        .count()
}

/// `engine.ingest_shards` defaults to a fraction of the host's core count, so a
/// test that let it default would silently assert nothing on a 1- or 2-core
/// runner (the default would already be 1). Pin it well above 1.
fn config_for(dir: &TempDir) -> Config {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_string_lossy().into_owned();
    config.engine.ingest_shards = 8;
    config
}

#[test]
fn a_positive_wal_shard_count_in_index_settings_is_used() {
    assert_eq!(
        wal_shards_override_from_settings(&settings_with(json!(1))),
        Some(1)
    );
    assert_eq!(
        wal_shards_override_from_settings(&settings_with(json!(4))),
        Some(4)
    );
    assert_eq!(
        wal_shards_override_from_settings(&settings_with(json!(256))),
        Some(256),
        "256 is the documented ceiling and must still be accepted"
    );
}

#[test]
fn an_absent_wal_shard_setting_leaves_the_engine_default_in_charge() {
    for absent in [
        Value::Null,
        json!({}),
        json!({ "index": {} }),
        json!({ "index": { "number_of_shards": 1 } }),
        json!({ "xerj_ingest_shards": 1 }),
        json!({ "index.xerj_ingest_shards": 1 }),
    ] {
        assert_eq!(
            wal_shards_override_from_settings(&absent),
            None,
            "no override should be read from {absent}"
        );
    }
}

#[test]
fn zero_and_negative_wal_shard_counts_are_ignored_never_used_as_a_count() {
    for bad in [json!(0), json!(-1), json!(-8)] {
        assert_eq!(
            wal_shards_override_from_settings(&settings_with(bad.clone())),
            None,
            "{bad} must not become a shard count"
        );
    }
}

#[test]
fn non_numeric_wal_shard_values_are_ignored_never_coerced() {
    for bad in [
        json!("4"),
        json!("many"),
        json!(4.5),
        json!(true),
        json!([4]),
        json!({ "value": 4 }),
        Value::Null,
    ] {
        assert_eq!(
            wal_shards_override_from_settings(&settings_with(bad.clone())),
            None,
            "{bad} must not become a shard count"
        );
    }
}

/// The value arrives straight off an index-create request body, and every shard
/// costs a directory plus a permanently open WAL file descriptor at
/// `IndexStore::open`. An out-of-range count is refused outright rather than
/// clamped, so a typo falls back to the engine default instead of quietly
/// running with a shard count nobody asked for.
#[test]
fn absurdly_large_wal_shard_counts_are_refused_and_never_opened() {
    for absurd in [json!(257), json!(100_000), json!(u64::MAX)] {
        assert_eq!(
            wal_shards_override_from_settings(&settings_with(absurd.clone())),
            None,
            "{absurd} exceeds the 256 ceiling and must be refused"
        );
    }
}

#[test]
fn the_store_config_takes_its_wal_shard_count_from_the_override_when_present() {
    let dir = TempDir::new().expect("temp dir");
    let config = config_for(&dir);

    assert_eq!(
        store_config_from(&config, None, xerj_storage::StorageMode::Local).num_wal_shards,
        8
    );
    assert_eq!(
        store_config_from(&config, Some(1), xerj_storage::StorageMode::Local).num_wal_shards,
        1
    );
    assert_eq!(
        store_config_from(&config, Some(2), xerj_storage::StorageMode::Local).num_wal_shards,
        2
    );
}

/// The whole point of persisting the setting: create and reopen must agree on
/// the shard count. If reopen fell back to `engine.ingest_shards`, the reopened
/// store would write into `wal/s{N}/` while the create-time entries live in
/// `wal/`, splitting the layout under a single index.
#[tokio::test]
async fn a_pinned_wal_shard_count_survives_reopen_with_every_document_intact() {
    let dir = TempDir::new().expect("temp dir");
    let config = config_for(&dir);
    let pinned_dir = dir.path().join("pinned");
    let default_dir = dir.path().join("spread");

    // Deliberately below the flush thresholds: the documents stay in the
    // memtable + WAL, so surviving a reopen means the WAL was replayed out of
    // the layout the persisted shard count selected, not read back from a
    // segment that would have survived either way.
    async fn write_docs(idx: &crate::Index, range: std::ops::Range<u32>) {
        for i in range {
            idx.index_document(
                Some(format!("doc-{i}")),
                json!({ "body": format!("payload {i}") }),
            )
            .await
            .expect("index document");
        }
    }

    async fn assert_docs(idx: &crate::Index, count: u32) {
        for i in 0..count {
            let doc = idx
                .get_document(&format!("doc-{i}"))
                .await
                .expect("get document")
                .unwrap_or_else(|| panic!("doc-{i} was lost"));
            assert_eq!(doc["body"], json!(format!("payload {i}")));
        }
        let all = idx
            .search(
                &xerj_query::parse_request(&json!({ "query": { "match_all": {} }, "size": 0 }))
                    .unwrap(),
            )
            .await
            .expect("search");
        assert_eq!(
            all.total.value, count as u64,
            "every document must be searchable after reopen"
        );
    }

    {
        let engine = Engine::new(config.clone()).expect("engine");
        engine
            .create_index_with_settings("pinned", Schema::empty(), settings_with(json!(1)))
            .expect("create pinned index");
        engine
            .create_index("spread", Schema::empty())
            .expect("create default index");

        let idx = engine.get_index("pinned").expect("pinned index");
        write_docs(&idx, 0..25).await;
        write_docs(&engine.get_index("spread").expect("spread index"), 0..1).await;

        assert_eq!(
            wal_shard_dirs(&pinned_dir),
            0,
            "one WAL shard means no s{{N}} subdirectories"
        );
        assert_eq!(
            root_wal_files(&pinned_dir),
            1,
            "one WAL shard means exactly one WAL file"
        );
        // Control: without the setting the same engine config opens the
        // core-scaled layout, so the assertions above are driven by the
        // setting and not by an engine that only ever opens one shard.
        assert_eq!(wal_shard_dirs(&default_dir), 8);
    }

    {
        let engine = Engine::new(config.clone()).expect("reopen engine");
        let idx = engine
            .get_index("pinned")
            .expect("pinned index after reopen");
        assert_docs(&idx, 25).await;

        assert_eq!(
            wal_shard_dirs(&pinned_dir),
            0,
            "reopen must honor the persisted shard count, not engine.ingest_shards"
        );
        assert_eq!(
            wal_shard_dirs(&default_dir),
            8,
            "an index without the setting keeps the default"
        );

        // Writes taken by the *reopened* store must land in the same layout —
        // this is where a create/open mismatch would split the WAL.
        write_docs(&idx, 25..50).await;
        assert_eq!(wal_shard_dirs(&pinned_dir), 0);
        assert_eq!(root_wal_files(&pinned_dir), 1);
    }

    {
        let engine = Engine::new(config).expect("second reopen engine");
        let idx = engine
            .get_index("pinned")
            .expect("pinned index after second reopen");
        assert_docs(&idx, 50).await;
        assert_eq!(wal_shard_dirs(&pinned_dir), 0);
    }
}

//! Single-node WAL tap — push a filtered subset of indices to an external
//! ES-compatible target (issue #320).
//!
//! ## What this is
//!
//! A background loop that tails each allowlisted index's write-ahead log and
//! replays the entries it finds into `{target}/_bulk`. The target can be an
//! Elasticsearch cluster, an OpenSearch cluster, or another xerj node — the
//! wire format is `_bulk` and nothing else, so there is nothing to install on
//! the far side.
//!
//! ## What this is not
//!
//! It is not cross-cluster replication. Nothing flows back, there is no
//! follower state machine, no leader election, no retention leases, and it
//! does not depend on the post-GA multi-node track. `_ccr/*` still answers
//! `501`, honestly, because none of that exists.
//!
//! ## Who may call it
//!
//! Every `/_xerj/*` route is **superuser-only**, enforced in
//! [`crate::authz`](../../xerj_api/authz/index.html) on the first path
//! segment. `PUT /_xerj/wal_tap` names an arbitrary host in `target_url` and
//! an arbitrary index set in `indices`, and attaches an operator-supplied
//! `Authorization` header to what it sends — a whole-node export channel and
//! an authenticated SSRF in one request. Nothing here is index-scoped, so
//! there is no per-index decision to make, which is the same argument that
//! already makes snapshot and restore superuser-only.
//!
//! ## The four decisions
//!
//! **1. Where it hooks.** Nowhere on the write path. The tap reads WAL files
//! from disk on a timer; it takes no lock the writer wants and adds not one
//! instruction to `append` / `append_index_raw_batch`. That is affordable
//! because every append already drains its `BufWriter` to the page cache
//! (`WalWriter::write_one_frame_inner`), so a reader in the same process sees
//! whole frames the moment they are acked. The price is that end-to-end
//! latency has `poll_interval_ms` as its floor.
//!
//! A poll costs the bytes appended since the last one, not the size of the
//! file: `tail_shard` reads through a sliding window over a `File`
//! ([`xerj_storage::wal`]), so a caught-up shard costs one 16-byte header
//! read. It has to — the cost is multiplied by `num_wal_shards` × allowlisted
//! indices × `1000 / poll_interval_ms` per second, and `indices = ["*"]` on a
//! node with thousands of indices is a supported configuration.
//!
//! **2. Ordering and dedup.** The cursor is a **byte offset**, never a
//! sequence number: the lock-free writer reserves seq_nos outside the shard
//! mutex, so a file can hold frames out of seq order and a seq-filtered resume
//! would skip entries (see [`xerj_storage::wal::WalTailCursor`]). Delivery is
//! at-least-once — a batch that could not be confirmed is re-sent from the
//! un-advanced cursor. Every action carries `_id = doc_id` plus
//! `version_type: external` with the entry's `seq_no`, which is the same
//! "highest seq wins" rule this engine's own version map uses
//! (`VersionMap::set_if_latest`), so a redelivery or an out-of-order delivery
//! resolves to the same document the source holds. A target that ignores
//! external versioning — which currently includes xerj's own `_bulk` — falls
//! back to last-write-wins by arrival instead.
//!
//! What the target did with each action is read back per item, positionally,
//! and that is what the counters mean: `docs_shipped` and `last_shipped_seq`
//! move only for items the target **accepted**. A `_bulk` that returns `200`
//! while rejecting every action inside it — a target holding a higher external
//! version for every `_id` because a second writer got there first, or one
//! rejecting every document with a `mapper_parsing_exception` — is a real
//! state and used to be indistinguishable from a healthy tap.
//! `consecutive_unapplied_polls`, `last_item_rejection` and
//! [`IndexTapStats::healthy`] exist so it is not. The counter is deliberately
//! blind to *why* nothing applied: conflict and rejection are opposite
//! diagnoses but the same fact, and it is the fact that `healthy` reports. It
//! counts **polls**, not `_bulk` requests: how many chunks a poll splits into
//! is `max_batch_bytes` arithmetic, and charging each of them separately made
//! one ordinary redelivery look like a dead replication stream.
//!
//! **3. Backpressure.** Bounded by construction: one in-flight request per
//! index, batches capped by `max_batch_docs` and `max_batch_bytes`, and
//! nothing buffered between polls. When the target is down the cursor simply
//! does not advance and the retry backs off exponentially (capped, jittered)
//! — memory does not grow, and neither does anything else on this node.
//!
//! **4a. Where a tap starts.** At the beginning of an index's WAL when
//! nothing in it has ever been pruned (generation 0 still on disk) — so an
//! index created while the tap is running is shipped whole, first document
//! included. On an index that has been running long enough to prune, at the
//! end: the surviving generations are an arbitrary recent slice, and shipping
//! them would look like a backfill without being one. **There is no backfill.**
//! Seed the target with the existing documents first if it needs them.
//! snapshot/restore only seeds another XERJ node — XERJ's snapshot format
//! (WAL + segments) is engine-specific and cannot be restored into an
//! Elasticsearch/OpenSearch target; seed a cross-engine target with an
//! external scan-and-push of the current documents (`_search`/PIT -> `_bulk`).
//!
//! **4b. What falling behind costs.** WAL retention is *not* coupled to the
//! tap, deliberately: `IndexStore::wal_maintain_all_verified` deletes a
//! rotated generation as soon as its entries are durable in a segment, and
//! making that wait on a remote target is how a slow consumer turns into a
//! disk-full incident. So a tap that falls far enough behind loses entries —
//! and always finds out. The
//! cursor carries the generation it sits in, a pruned-out-from-under-us
//! generation is detected exactly ([`WalShardTail::gap`]), and each occurrence
//! logs at `warn` and increments `gaps` in `GET /_xerj/wal_tap/_stats`. The
//! degradation is visible, not silent.
//!
//! "Visible" is not the same as "survivable", though, and at the default
//! `storage.flush_interval_secs = 30` the WAL window is about one flush — so a
//! minute of target downtime on a hot index loses data with nothing but a log
//! line to offer. `wal_tap.min_retained_generations` is the middle path: a
//! **bounded** floor inside that maintenance pass, holding the newest N
//! rotated generations whatever any consumer is doing. Same arithmetic and
//! same placement — inside the deletion pass, not in its callers — as Lucene's
//! `KeepLastNCommitsDeletionPolicy.onCommit`
//! (`lucene/core/src/java/org/apache/lucene/index/KeepLastNCommitsDeletionPolicy.java:51-58`,
//! Apache-2.0). Deliberately **not** a retention lease (Elasticsearch's
//! `ReplicationTracker.addRetentionLease`, Lucene's
//! `SnapshotDeletionPolicy.snapshot`): a lease is held until the consumer
//! releases it, which is exactly how a dead follower wedges a leader's disk.
//! A floor costs `n * wal_max_size_mb` per shard and not one byte more.
//!
//! The floor is **live**: `PUT /_xerj/wal_tap` pushes it straight onto the
//! open `WalWriter`s (`Engine::apply_wal_retention_floor`), because the value
//! that reaches a store at open time comes from `Engine.config`, an
//! `Arc<Config>` written once at boot and never mutated. Setting it through
//! the API used to reach no writer at all — not the open ones, and not after a
//! restart either — on the one knob whose whole purpose is preventing loss
//! during a target outage. Live reconfiguration of an already-open writer is
//! Lucene's `LiveIndexWriterConfig`
//! (`lucene/core/src/java/org/apache/lucene/index/LiveIndexWriterConfig.java:39-126`),
//! and re-applying a policy to state that already exists rather than only at
//! construction is its `IndexFileDeleter.revisitPolicy` (`:516-543`).
//!
//! **4c. Where the configuration lives.** In the state file next to the
//! cursors, not only in memory. `PUT /_xerj/wal_tap` is durable and is
//! re-applied over the config file on the next boot; `DELETE /_xerj/wal_tap`
//! drops it. The alternative — the shape this started as — advertised
//! "runtime config, no restart" while a restart silently reverted the tap to
//! `enabled = false`, froze its cursors, let WAL pruning carry on, and left
//! `_stats` not even listing the affected indices.
//!
//! Prior art consulted before writing this (per the repository's
//! reference-coding mandate):
//!
//! - **quickwit** `quickwit-metastore/src/checkpoint.rs:170` (`SourceCheckpoint`)
//!   and `:280-345` (`check_compatibility` / `try_apply_delta`), Apache-2.0.
//!   Its model is one position per partition, a delta that moves *backwards*
//!   is refused, and a delta that leaves a *hole* is accepted with a warning
//!   because "gaps may happen … if the indexing pipeline is down for more than
//!   the retention period". That is the same shape adopted here: one cursor
//!   per WAL shard, and a pruned generation surfaces as a counted, logged gap
//!   rather than either a stall or silence. Adapted, not copied.
//! - **elasticsearch** `x-pack/plugin/ccr/.../ShardFollowNodeTask.java:270-330`
//!   and `:586-640` — **approach only, AGPL/SSPL/Elastic-2.0, no code taken.**
//!   Confirms the two primitives: an explicitly bounded write buffer (count
//!   *and* bytes) as the whole of backpressure, and capped exponential backoff
//!   with jitter separating retryable transport failures from fatal ones.
//! - **lucene** `lucene/core/src/java/org/apache/lucene/store/BufferedIndexInput.java:289-317`
//!   (`refill`) and `:221-244` (`resolvePositionInBuffer`), plus
//!   `lucene/analysis/common/src/java/org/apache/lucene/analysis/util/SegmentingTokenizerBase.java:124-147`
//!   (`refill`, the compact-then-read step), Apache-2.0 — the shape of the
//!   incremental tail reader in [`xerj_storage::wal`]: a bounded window whose
//!   absolute position is `bufferStart + buffer.position()`, read length
//!   clamped to the file length so it never reads past EOF, and the
//!   unconsumed remainder carried to the front before pulling more. Adapted,
//!   not copied.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;
use std::time::Duration;

use parking_lot::RwLock;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use tracing::{debug, info, warn};

use xerj_common::config::WalTapConfig;
use xerj_common::types::is_reserved_index;
use xerj_storage::wal::{tail_shard, wal_shard_dirs, WalEntry, WalTailCursor};

use crate::engine::Engine;

/// Filename of the durable cursor state, under the engine data directory.
const STATE_FILE: &str = "wal_tap_state.json";

/// Prefix of every index xerj creates for itself.
///
/// Broader than [`is_reserved_index`] on purpose. That predicate's constant is
/// `.xerj-memory-` (the brain namespace, which the authz layer guards); the
/// console bootstraps `.xerj_users`, `.xerj_api_tokens`, `.xerj_sessions`,
/// `.xerj_magic_links` and friends, which hold hashed credentials and live
/// sessions. Nothing under either shape may leave this node.
const XERJ_SYSTEM_INDEX_PREFIX: &str = ".xerj";

/// Is `index` one of xerj's own?
fn is_xerj_system_index(index: &str) -> bool {
    index.starts_with(XERJ_SYSTEM_INDEX_PREFIX) || is_reserved_index(index)
}

/// Persisted format version. Bump on any incompatible change to
/// [`PersistedState`]; an unrecognised version is refused rather than
/// reinterpreted, because misreading a cursor means silently re-shipping or
/// silently skipping.
const STATE_VERSION: u32 = 1;

// ─────────────────────────────────────────────────────────────────────────────
// Durable cursor state
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct IndexCursors {
    /// WAL shard name (`"s0"`, or `""` for the legacy single-WAL layout) →
    /// position.
    shards: BTreeMap<String, WalTailCursor>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PersistedState {
    version: u32,
    indices: BTreeMap<String, IndexCursors>,
    /// The last configuration applied through `PUT /_xerj/wal_tap`.
    ///
    /// Without this, "runtime config, no restart" was a half-truth that
    /// failed in the direction that loses data: the live config lived only in
    /// an `RwLock`, so a restart silently reverted the tap to the file config
    /// — typically `enabled = false`. Cursors then froze while WAL pruning
    /// carried on, and `_stats` did not even list the affected indices,
    /// because it only lists what the *current* allowlist matches.
    ///
    /// Precedent for a persisted overlay winning over the file is
    /// Elasticsearch's `persistent` cluster settings.
    /// `DELETE /_xerj/wal_tap` drops it and reverts to the file.
    #[serde(default)]
    runtime_config: Option<WalTapConfig>,
}

impl Default for PersistedState {
    fn default() -> Self {
        Self {
            version: STATE_VERSION,
            indices: BTreeMap::new(),
            runtime_config: None,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Stats
// ─────────────────────────────────────────────────────────────────────────────

/// Per-index counters, all monotonic within a process lifetime.
#[derive(Debug, Clone, Default, Serialize)]
pub struct IndexTapStats {
    /// `index` actions accepted into a `_bulk` body.
    pub docs_shipped: u64,
    /// `delete` actions accepted into a `_bulk` body.
    pub deletes_shipped: u64,
    /// `_bulk` requests the target answered 2xx to.
    pub batches_sent: u64,
    /// Requests that failed outright (transport error or non-2xx). The cursor
    /// does not advance for these — they are retried.
    pub bulk_failures: u64,
    /// Items the target rejected inside an otherwise-successful `_bulk`
    /// response. The cursor DOES advance past these; see [`WalTap::send_bulk`].
    pub item_failures: u64,
    /// Version conflicts inside a `_bulk` response. Expected and benign: they
    /// are how external versioning absorbs a redelivery. Counted separately so
    /// they never look like data loss.
    pub version_conflicts: u64,
    /// Times a poll found a WAL generation pruned before it could be shipped.
    /// Any value above zero means entries the target will never receive.
    ///
    /// Counted per observation, not per lost generation: while a tap is stuck
    /// behind a live gap, each poll re-observes it and this keeps climbing.
    /// That is the useful reading — "still losing data", not "lost data once".
    pub gaps: u64,
    /// `UpdateMapping` WAL entries seen. No current xerj code path writes one
    /// (only read sites exist), so this is expected to stay 0; if it ever
    /// moves, the target's dynamic mapping is what handled the change.
    pub mapping_updates_skipped: u64,
    /// Frames skipped because their payload did not decode.
    pub corrupt_skipped: u64,
    /// Consecutive failed sends; drives the backoff.
    pub consecutive_failures: u32,
    /// Last failure, as a short string. `None` once a send succeeds.
    pub last_error: Option<String>,
    /// Highest `seq_no` the target **accepted**, for the lag estimate.
    ///
    /// Accepted means the item came back without an `error`. A rejected item
    /// — including a version conflict — does not move this, because the whole
    /// point of the number is to answer "is our data there?" and the answer
    /// for a rejected action is no. Deriving it from the render-time batch
    /// instead is what let a target that rejected every single action report
    /// `lag_seq: 0` while `docs_shipped` climbed.
    pub last_shipped_seq: u64,
    /// Consecutive **polls** in which the target accepted **nothing** — every
    /// action of every `_bulk` the poll sent came back with an error.
    ///
    /// Counted per poll, not per `_bulk`. A poll splits its read into as many
    /// chunks as `max_batch_bytes` dictates, and those chunks are one logical
    /// delivery: at `max_batch_bytes = 1` a single legitimate at-least-once
    /// redelivery of four documents produced four all-conflict `_bulk`
    /// responses and tripped [`UNAPPLIED_UNHEALTHY_AFTER`] on its own, with a
    /// `last_error` claiming "nothing is being replicated" about a poll in
    /// which every document was already at the target. The chunk count is a
    /// transport detail; the operator-visible unit of "did this tap make
    /// progress" is the poll.
    ///
    /// Deliberately blind to *why*. A version conflict and a
    /// `mapper_parsing_exception` are opposite diagnoses but the same
    /// operational fact: the documents are not at the target. An earlier shape
    /// of this counter only counted the conflict case, which meant a target
    /// answering `200` while rejecting every single item with a mapping error
    /// read `healthy: true` with `docs_shipped: 0` — the exact class of lie
    /// the per-item accounting exists to remove.
    ///
    /// One such poll is expected and benign: it is how external versioning
    /// absorbs an at-least-once redelivery. A *sustained run* is not — it means
    /// the tap is a no-op and the two sides are diverging. See
    /// [`IndexTapStats::healthy`].
    pub consecutive_unapplied_polls: u32,
    /// Error `type` of the most recent item the target rejected for a reason
    /// other than a version conflict, e.g. `mapper_parsing_exception`.
    ///
    /// `item_failures` says how many documents were dropped; this says what
    /// the target called them, which is the difference between "fix the
    /// mapping" and "look for a second writer".
    pub last_item_rejection: Option<String>,
}

/// How many **polls** in a row that applied nothing stop counting as "a
/// redelivery landed" and start counting as "this target is not taking our
/// writes".
///
/// Polls, not `_bulk` requests. A poll that applies nothing still advances the
/// cursor past the entries it read (rejected items are not retried — see
/// [`WalTap::send_bulk`]), so the *next* poll reads new entries and a healthy
/// stream clears the counter immediately. A redelivery — a rewound cursor, or
/// a send that failed part-way through and re-ships its earlier chunks on the
/// next poll — is at most one such poll, however many chunks it took.
/// Three in a row cannot be that.
const UNAPPLIED_UNHEALTHY_AFTER: u32 = 3;

impl IndexTapStats {
    /// Is this index's replication actually working?
    ///
    /// `false` for the two states that used to look identical to a healthy
    /// tap in `_stats`: a send that keeps failing, and a target that accepts
    /// every request while rejecting every action inside it — for any reason,
    /// conflict or otherwise.
    pub fn healthy(&self) -> bool {
        self.last_error.is_none() && self.consecutive_unapplied_polls < UNAPPLIED_UNHEALTHY_AFTER
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// The tap
// ─────────────────────────────────────────────────────────────────────────────

/// Shared, runtime-mutable tap state. Held by the [`Engine`] so the REST
/// surface can read stats and edit the allowlist without a restart.
pub struct WalTap {
    config: RwLock<WalTapConfig>,
    /// Exactly what `xerj.toml` said, kept verbatim so `DELETE
    /// /_xerj/wal_tap` has something true to revert to.
    ///
    /// It used to be read back off `Engine.config`, which was safe only while
    /// nothing else ever wrote to that field. `Engine::new` now folds the
    /// tap's *effective* configuration into the boot `Config` (so index stores
    /// open with the retention floor actually in force), which would have made
    /// `DELETE` revert a persisted runtime config to… itself. Owning the file
    /// value here removes the coupling instead of documenting around it.
    file_config: WalTapConfig,
    state: RwLock<PersistedState>,
    stats: RwLock<BTreeMap<String, IndexTapStats>>,
    state_path: PathBuf,
    client: reqwest::Client,
    /// Monotonic tick counter, so tests can observe that the loop ran.
    ticks: AtomicU64,
    /// Milliseconds-since-start before which the next send must not be tried.
    retry_not_before_ms: AtomicU64,
    /// Cursor state has moved since the last durable write.
    ///
    /// Cursors are flushed **once per tick**, not once per index per poll.
    /// The old shape re-serialised and fsynced the WHOLE state file on every
    /// cursor advance — O(N²) bytes and 2N fsyncs per tick at N allowlisted
    /// indices, at a 500 ms default, on a node that `index_store.rs:806-813`
    /// records reaching 9,382 indices. `indices = ["*"]` walked straight into
    /// that.
    ///
    /// Deferring costs nothing that matters: the cursor is only ever
    /// persisted *after* the entries it covers have been shipped, so a crash
    /// in the window re-delivers a batch. Re-delivery is the documented
    /// contract (at-least-once, absorbed by `version_type: external`); losing
    /// a batch would not be, and that direction is impossible here.
    dirty: std::sync::atomic::AtomicBool,
    /// Durable writes of the state file since start.
    ///
    /// Instrumentation, and the only way to assert the property that matters
    /// about [`WalTap::dirty`]: the cost of a tick must not scale with the
    /// number of allowlisted indices. See
    /// `cursor_state_is_written_once_per_tick_not_once_per_index`.
    persists: AtomicU64,
    started: std::time::Instant,
}

impl WalTap {
    /// Build a tap and load any persisted cursors from `data_dir`.
    ///
    /// A state file that cannot be parsed is refused loudly and treated as
    /// absent — which means every allowlisted index restarts "from now"
    /// instead of re-shipping from a position that may be nonsense.
    pub fn new(data_dir: &Path, config: WalTapConfig) -> Self {
        let state_path = data_dir.join(STATE_FILE);
        let state = match std::fs::read(&state_path) {
            Ok(bytes) => match serde_json::from_slice::<PersistedState>(&bytes) {
                Ok(s) if s.version == STATE_VERSION => s,
                Ok(s) => {
                    warn!(
                        found = s.version,
                        expected = STATE_VERSION,
                        "WAL tap state file has an unknown version — starting from now"
                    );
                    PersistedState::default()
                }
                Err(e) => {
                    warn!(error = %e, path = ?state_path,
                          "WAL tap state file is unreadable — starting from now");
                    PersistedState::default()
                }
            },
            Err(_) => PersistedState::default(),
        };

        let file_config = config.clone();

        // A configuration set through the API outlives the process that took
        // it. Without this a restart reverted to the file config — usually
        // `enabled = false` — and the tap went quiet while its cursors froze
        // and WAL pruning carried on regardless.
        let config = match state.runtime_config.clone() {
            Some(saved) => {
                info!(
                    target_url = %saved.redacted_target_url(),
                    enabled = saved.enabled,
                    indices = ?saved.indices,
                    "WAL tap: applying the configuration last set via PUT /_xerj/wal_tap \
                     (overrides the config file; DELETE /_xerj/wal_tap reverts)"
                );
                saved
            }
            None => config,
        };

        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(config.request_timeout_secs.max(1)))
            .build()
            .unwrap_or_default();

        Self {
            config: RwLock::new(config),
            file_config,
            state: RwLock::new(state),
            stats: RwLock::new(BTreeMap::new()),
            state_path,
            client,
            ticks: AtomicU64::new(0),
            retry_not_before_ms: AtomicU64::new(0),
            dirty: std::sync::atomic::AtomicBool::new(false),
            persists: AtomicU64::new(0),
            started: std::time::Instant::now(),
        }
    }

    /// Snapshot of the live configuration.
    pub fn config(&self) -> WalTapConfig {
        self.config.read().clone()
    }

    /// What `xerj.toml` said at boot — the value `DELETE /_xerj/wal_tap`
    /// reverts to.
    pub fn file_config(&self) -> WalTapConfig {
        self.file_config.clone()
    }

    /// Replace the live configuration **durably**.
    ///
    /// Takes effect on the next poll — no restart — and cursors are preserved
    /// so an index that stays in the allowlist does not re-ship or skip. The
    /// configuration is also written next to the cursors and re-applied over
    /// the file config on the next boot, so "no restart needed" does not
    /// quietly mean "and it is gone after one".
    pub fn set_config(&self, config: WalTapConfig) {
        *self.config.write() = config.clone();
        self.state.write().runtime_config = Some(config);
        // Operator action, not a hot path: make it durable now rather than at
        // the next tick, so a crash between the 200 and the next poll cannot
        // lose an acknowledged configuration change.
        self.persist_now();
    }

    /// Drop the persisted runtime overlay and revert to `config` (the value
    /// from the config file).
    pub fn clear_runtime_config(&self, file_config: WalTapConfig) {
        *self.config.write() = file_config;
        self.state.write().runtime_config = None;
        self.persist_now();
    }

    /// Does a configuration set through the API currently override the file?
    pub fn has_runtime_config(&self) -> bool {
        self.state.read().runtime_config.is_some()
    }

    /// Number of completed poll cycles — the "it is actually running" signal
    /// for tests and for `_stats`.
    pub fn ticks(&self) -> u64 {
        self.ticks.load(Ordering::Relaxed)
    }

    /// Per-index counters.
    pub fn stats(&self) -> BTreeMap<String, IndexTapStats> {
        self.stats.read().clone()
    }

    /// Put an index's cursors back, verbatim.
    ///
    /// Test seam. Reconstructs the one state no in-process sequence can reach
    /// on its own: a persisted cursor that outlived its WAL stream because the
    /// delete happened while this process was **not running**, so
    /// [`forget_index`](Self::forget_index) never fired. That is the case
    /// `tail_shard`'s offset-past-EOF check exists for, and it is unreachable
    /// from the public API by construction.
    #[doc(hidden)]
    pub fn restore_cursors_for_test(&self, index: &str, shards: BTreeMap<String, WalTailCursor>) {
        self.state
            .write()
            .indices
            .entry(index.to_string())
            .or_default()
            .shards = shards;
        self.persist_now();
    }

    /// Rewind an index's cursors to the start of their oldest generation.
    ///
    /// Test seam for the redelivery half of the at-least-once contract: it
    /// reproduces exactly what a crash between shipping a batch and persisting
    /// its cursor leaves behind, which is the case `version_type: external`
    /// exists to make safe.
    #[doc(hidden)]
    pub fn rewind_for_test(&self, index: &str) {
        let mut state = self.state.write();
        if let Some(cursors) = state.indices.get_mut(index) {
            for cursor in cursors.shards.values_mut() {
                *cursor = WalTailCursor::start_of(0);
            }
        }
        drop(state);
        self.persist_now();
    }

    /// Per-index, per-shard cursors, for `_stats`.
    pub fn cursors(&self) -> BTreeMap<String, BTreeMap<String, WalTailCursor>> {
        self.state
            .read()
            .indices
            .iter()
            .map(|(k, v)| (k.clone(), v.shards.clone()))
            .collect()
    }

    /// Does `index` match the allowlist, and is it allowed to be shipped at
    /// all?
    ///
    /// Two rules sit above the patterns:
    ///
    /// 1. **xerj's own system indices are never shipped**, whatever the
    ///    allowlist says. That means every `.xerj*` name, not just the
    ///    [`is_reserved_index`] namespace: that constant is `.xerj-memory-`,
    ///    which covers the brain indices but not `.xerj_users`,
    ///    `.xerj_api_tokens` or `.xerj_sessions` — where hashed credentials,
    ///    tokens and console sessions live. An `indices = ["*"]` tap that
    ///    shipped those to another cluster would be a credential leak, and it
    ///    is what the regression test
    ///    `system_indices_are_never_pushed_even_with_a_star_allowlist` exists
    ///    to catch.
    /// 2. **A wildcard does not expand to a hidden index.** `["*"]` means
    ///    "every ordinary index", not "also `.kibana`" — the same rule
    ///    Elasticsearch's `expand_wildcards` uses, where a pattern reaches a
    ///    dotted index only when the pattern is itself dotted. Naming one
    ///    outright (`indices = [".kibana"]`) still works.
    pub fn ships(config: &WalTapConfig, index: &str) -> bool {
        if is_xerj_system_index(index) {
            return false;
        }
        config.indices.iter().any(|pat| {
            if index.starts_with('.') && !pat.starts_with('.') {
                return false;
            }
            crate::engine::glob_match(pat, index)
        })
    }

    fn stat<R>(&self, index: &str, f: impl FnOnce(&mut IndexTapStats) -> R) -> R {
        let mut guard = self.stats.write();
        f(guard.entry(index.to_string()).or_default())
    }

    /// Note that cursor state has moved. The write happens once, at the end of
    /// the tick — see [`WalTap::dirty`] for why deferring is safe.
    fn mark_dirty(&self) {
        self.dirty.store(true, Ordering::Relaxed);
    }

    /// Flush cursor state if anything moved since the last write.
    fn persist_if_dirty(&self) {
        if self.dirty.swap(false, Ordering::Relaxed) {
            self.persist_now();
        }
    }

    /// Durable writes of the state file since start.
    ///
    /// The tap's I/O amplification, exposed so it can be asserted rather than
    /// asserted about: one tick must cost one write however many indices are
    /// allowlisted.
    pub fn persists(&self) -> u64 {
        self.persists.load(Ordering::Relaxed)
    }

    fn persist_now(&self) {
        self.dirty.store(false, Ordering::Relaxed);
        self.persists.fetch_add(1, Ordering::Relaxed);
        let snapshot = self.state.read().clone();
        let bytes = match serde_json::to_vec_pretty(&snapshot) {
            Ok(b) => b,
            Err(e) => {
                warn!(error = %e, "WAL tap: cannot serialise cursor state");
                return;
            }
        };
        // Durable replace at 0600: a torn cursor file is a silent re-ship or a
        // silent skip on the next boot, and the persisted runtime config in
        // this file carries `target_auth` — a credential for another cluster,
        // which must not be world-readable in the data directory. Same writer
        // the API-key store uses.
        if let Err(e) = crate::engine::write_secret_file_atomic(&self.state_path, &bytes) {
            warn!(error = %e, path = ?self.state_path, "WAL tap: cannot persist cursor state");
        }
    }

    fn now_ms(&self) -> u64 {
        self.started.elapsed().as_millis() as u64
    }

    fn in_backoff(&self) -> bool {
        self.now_ms() < self.retry_not_before_ms.load(Ordering::Relaxed)
    }

    /// Capped exponential backoff with jitter, keyed off the worst
    /// consecutive-failure count across indices.
    ///
    /// **Every multiply here saturates**, including the two that used to be
    /// plain `*`. `max_retry_backoff_secs` and `poll_interval_ms` reach this
    /// function from two places, and only one of them is range-checked:
    /// `PUT /_xerj/wal_tap` bounds both, but `Config::validate` bounds
    /// neither, so `xerj.toml` can put any `u64` in either field. At
    /// `max_retry_backoff_secs > u64::MAX / 1000` (~1.8e16) the old
    /// `secs.max(1) * 1000` overflowed — a panic under `cargo test`'s
    /// overflow-checks that killed the spawned tap task with nothing in
    /// `_stats` to say why, and in a release profile a *wrapped* cap that can
    /// be arbitrarily small: the concrete value 18_446_744_073_709_552 wraps
    /// to a 384 ms ceiling, i.e. a retry storm aimed at a target that is
    /// already failing. `uncapped` on the line above already saturated for
    /// exactly this reason.
    ///
    /// Approach (not code) from Elasticsearch's `ShardFollowNodeTask.computeDelay`.
    fn arm_backoff(&self, config: &WalTapConfig, failures: u32) {
        let base = config.poll_interval_ms.max(50);
        let shift = failures.saturating_sub(1).min(20);
        let uncapped = base.saturating_mul(1u64 << shift);
        let cap = config.max_retry_backoff_secs.max(1).saturating_mul(1000);
        let delay = uncapped.min(cap);
        // Deterministic, dependency-free jitter in [50%, 100%] of the delay:
        // enough to stop N indices from re-hammering a recovering target in
        // lockstep, without pulling in an RNG.
        let jitter = self.now_ms() % 50 + 50;
        let delay = delay.saturating_mul(jitter) / 100;
        self.retry_not_before_ms
            .store(self.now_ms().saturating_add(delay), Ordering::Relaxed);
    }

    fn clear_backoff(&self) {
        self.retry_not_before_ms.store(0, Ordering::Relaxed);
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Bulk payload
// ─────────────────────────────────────────────────────────────────────────────

/// One WAL entry rendered as its two (or one) `_bulk` NDJSON lines.
///
/// `version_type: external` with the WAL `seq_no` as the version is what makes
/// at-least-once safe: the target keeps the highest-seq version of each
/// `_id`, which is the same winner [`xerj_storage::version_map::VersionMap`]
/// picks locally.
fn render_action(index: &str, seq_no: u64, entry: &WalEntry, out: &mut String) -> Option<bool> {
    match entry {
        WalEntry::Index { doc_id, source } => {
            let meta = json!({"index": {
                "_index": index,
                "_id": doc_id,
                "version": seq_no,
                "version_type": "external",
            }});
            out.push_str(&meta.to_string());
            out.push('\n');
            out.push_str(&compact_source(source));
            out.push('\n');
            Some(false)
        }
        WalEntry::Delete { doc_id } => {
            let meta = json!({"delete": {
                "_index": index,
                "_id": doc_id,
                "version": seq_no,
                "version_type": "external",
            }});
            out.push_str(&meta.to_string());
            out.push('\n');
            Some(true)
        }
        // Never written by any current code path (grep: only read sites
        // exist). If one ever appears, the target's dynamic mapping is what
        // absorbs the change — forwarding xerj's internal schema would mean
        // translating it into an ES mapping, a second translation surface with
        // its own failure modes, for an entry that does not occur.
        WalEntry::UpdateMapping { .. } => None,
    }
}

/// A document source as one NDJSON line. A WAL source is always a JSON value
/// with no interior newlines once re-serialised compactly, which is what
/// `_bulk` requires.
fn compact_source(source: &Value) -> String {
    source.to_string()
}

/// One rendered action, in the order it appears in the `_bulk` body.
///
/// The `items` array of a `_bulk` response is positionally aligned with the
/// actions of the request, which is the only way to say *which* seq_no the
/// target actually took. Keeping the pairing is what makes
/// [`IndexTapStats::last_shipped_seq`] mean something.
#[derive(Clone, Copy)]
struct RenderedAction {
    seq: u64,
    is_delete: bool,
}

/// One `_bulk` request's worth of rendered actions.
struct Chunk {
    body: String,
    actions: Vec<RenderedAction>,
}

/// Split a batch into `_bulk` bodies no larger than `max_bytes`.
///
/// A single action larger than `max_bytes` gets a chunk of its own rather than
/// being dropped: the cap is there to respect the target's
/// `http.max_content_length`, and silently discarding an oversized document
/// would be data loss dressed up as a limit.
fn render_chunks(index: &str, batch: &[(u64, WalEntry)], max_bytes: usize) -> Vec<Chunk> {
    let max_bytes = max_bytes.max(1);
    let mut chunks: Vec<Chunk> = Vec::new();
    let mut cur = Chunk {
        body: String::new(),
        actions: Vec::new(),
    };

    for (seq, entry) in batch {
        let mut rendered = String::new();
        let Some(is_delete) = render_action(index, *seq, entry, &mut rendered) else {
            continue;
        };
        if !cur.body.is_empty() && cur.body.len() + rendered.len() > max_bytes {
            chunks.push(std::mem::replace(
                &mut cur,
                Chunk {
                    body: String::new(),
                    actions: Vec::new(),
                },
            ));
        }
        cur.body.push_str(&rendered);
        cur.actions.push(RenderedAction {
            seq: *seq,
            is_delete,
        });
    }
    if !cur.body.is_empty() {
        chunks.push(cur);
    }
    chunks
}

// ─────────────────────────────────────────────────────────────────────────────
// The poll loop
// ─────────────────────────────────────────────────────────────────────────────

/// What the target did with one action inside a 2xx `_bulk` response.
#[derive(Clone, Copy, PartialEq, Eq)]
enum ItemOutcome {
    /// The target took it. This — and only this — advances the watermark.
    Accepted,
    /// `version_conflict_engine_exception`: the target already holds a
    /// version at least as high for this `_id`. Benign once (that is how
    /// external versioning absorbs a redelivery), a divergence signal when it
    /// is *every* action of *every* batch.
    Conflict,
    /// Rejected for any other reason — a mapping conflict, say. Counted,
    /// logged, and passed over: see [`WalTap::send_bulk`].
    Rejected,
}

/// Outcome of shipping one `_bulk` request.
enum SendOutcome {
    /// The target accepted the request. Per-item failures may still have
    /// occurred; the cursor advances either way.
    ///
    /// `outcomes` is positionally aligned with the chunk's actions.
    Accepted {
        outcomes: Vec<ItemOutcome>,
        /// Error `type` of the first non-conflict rejection in this response,
        /// so `_stats` can say what the target called the documents it threw
        /// away rather than only how many there were.
        rejection: Option<String>,
    },
    /// The request did not land. The cursor must not advance.
    Failed(String),
}

impl WalTap {
    /// POST one NDJSON body to `{target}/_bulk`.
    ///
    /// Whole-request failures (transport error, any non-2xx) leave the cursor
    /// where it is, so nothing is dropped and the batch is retried. Per-item
    /// failures inside a 2xx response are counted, logged, and *passed over*:
    /// a document the target will reject deterministically — a mapping
    /// conflict, say — would otherwise wedge the tap forever, and a wedged tap
    /// loses everything behind it to WAL pruning rather than just the one bad
    /// document. That trade is deliberate and is why `item_failures` is in
    /// `_stats`.
    async fn send_bulk(&self, config: &WalTapConfig, body: String, actions: usize) -> SendOutcome {
        let url = format!("{}/_bulk", config.target_url.trim_end_matches('/'));
        let mut req = self
            .client
            .post(&url)
            .header("Content-Type", "application/x-ndjson")
            .timeout(Duration::from_secs(config.request_timeout_secs.max(1)))
            .body(body);
        if !config.target_auth.is_empty() {
            req = req.header("Authorization", config.target_auth.clone());
        }

        let resp = match req.send().await {
            Ok(r) => r,
            Err(e) => return SendOutcome::Failed(format!("transport: {e}")),
        };
        let status = resp.status();
        if !status.is_success() {
            let snippet = resp
                .text()
                .await
                .unwrap_or_default()
                .chars()
                .take(300)
                .collect::<String>();
            return SendOutcome::Failed(format!("HTTP {status}: {snippet}"));
        }

        let parsed: Value = match resp.json().await {
            Ok(v) => v,
            // A 2xx the target could not describe. Treat as landed — resending
            // would double-deliver for no new information.
            Err(e) => {
                debug!(error = %e, "WAL tap: unparseable _bulk response body");
                return SendOutcome::Accepted {
                    outcomes: vec![ItemOutcome::Accepted; actions],
                    rejection: None,
                };
            }
        };

        // `errors: false` means every action landed, and ES omits nothing in
        // that case worth walking.
        if parsed.get("errors").and_then(Value::as_bool) != Some(true) {
            return SendOutcome::Accepted {
                outcomes: vec![ItemOutcome::Accepted; actions],
                rejection: None,
            };
        }

        let items = parsed
            .get("items")
            .and_then(Value::as_array)
            .map(Vec::as_slice)
            .unwrap_or_default();
        if items.len() != actions {
            // `errors: true` with an items array that is not positionally
            // aligned with the request. Nothing can be attributed to a
            // specific action, so refuse to claim any of them landed: hold
            // the cursor and retry rather than advance past writes whose fate
            // is unknown. At-least-once is a contract; at-most-once is not.
            return SendOutcome::Failed(format!(
                "target reported errors with {} items for {actions} actions — cannot \
                 attribute outcomes, holding the cursor",
                items.len()
            ));
        }

        let mut outcomes = Vec::with_capacity(items.len());
        let mut rejection: Option<String> = None;
        let mut warned = false;
        for item in items {
            let action = item.as_object().and_then(|o| o.values().next());
            let error = action.and_then(|a| a.get("error"));
            let Some(error) = error else {
                outcomes.push(ItemOutcome::Accepted);
                continue;
            };
            let kind = error.get("type").and_then(Value::as_str).unwrap_or("");
            if kind == "version_conflict_engine_exception" {
                outcomes.push(ItemOutcome::Conflict);
            } else {
                if !warned {
                    warned = true;
                    warn!(error = %error, "WAL tap: target rejected a document — \
                          skipped (see item_failures in _stats)");
                }
                if rejection.is_none() {
                    rejection = Some(if kind.is_empty() {
                        "unknown".to_string()
                    } else {
                        kind.to_string()
                    });
                }
                outcomes.push(ItemOutcome::Rejected);
            }
        }
        SendOutcome::Accepted {
            outcomes,
            rejection,
        }
    }

    /// Poll one index once: read its WAL tail, ship it, advance its cursors.
    ///
    /// `head_seq` is the index's highest reserved sequence number, used only to
    /// seed the lag watermark on a first look — see below.
    ///
    /// Returns `true` when there is more to read immediately (the batch was
    /// truncated), so the caller can keep going without waiting a full poll
    /// interval.
    async fn poll_index(
        &self,
        config: &WalTapConfig,
        name: &str,
        wal_root: PathBuf,
        head_seq: u64,
    ) -> bool {
        let known: BTreeMap<String, WalTailCursor> = self
            .state
            .read()
            .indices
            .get(name)
            .map(|c| c.shards.clone())
            .unwrap_or_default();
        let first_look = known.is_empty();

        let budget = config.max_batch_docs.max(1);
        let read = {
            let known = known.clone();
            // WAL reads are blocking file I/O; keep them off the async
            // runtime's worker threads.
            match tokio::task::spawn_blocking(move || {
                let mut shards = Vec::new();
                for (shard, dir) in wal_shard_dirs(&wal_root) {
                    let cursor = known.get(&shard).copied();
                    let tail = tail_shard(&dir, cursor, budget);
                    shards.push((shard, tail));
                }
                shards
            })
            .await
            {
                Ok(v) => v,
                Err(e) => {
                    warn!(index = %name, error = %e, "WAL tap: WAL read task failed");
                    return false;
                }
            }
        };

        // Merge the shard streams. Every entry read this poll is shipped:
        // the per-shard cursors advance together with the one request, so a
        // partial-batch horizon is unnecessary — each shard either ships all
        // of what it read or none of it.
        let mut batch: Vec<(u64, WalEntry)> = Vec::new();
        let mut new_cursors: BTreeMap<String, WalTailCursor> = known.clone();
        let mut more = false;
        let mut gaps = 0u64;
        let mut corrupt = 0u64;
        let mut mapping_updates = 0u64;

        for (shard, tail) in read {
            if tail.gap {
                gaps += 1;
                warn!(
                    index = %name, shard = %shard,
                    "WAL tap: a discontinuity in this shard's WAL stream — either a \
                     generation was pruned before it could be shipped, or the stream was \
                     replaced (index deleted and recreated, or data directory rolled \
                     back). Entries are missing at the target and cannot be recovered \
                     from the WAL. If the tap is behind, raise poll throughput, check the \
                     target, or set wal_tap.min_retained_generations; `tail_shard` names \
                     which of the two it was at WARN."
                );
            }
            corrupt += tail.corrupt_skipped as u64;
            more |= tail.truncated;
            for entry in tail.entries {
                if matches!(entry.entry, WalEntry::UpdateMapping { .. }) {
                    mapping_updates += 1;
                }
                batch.push((entry.seq_no, entry.entry));
            }
            new_cursors.insert(shard, tail.cursor);
        }

        if gaps > 0 || corrupt > 0 || mapping_updates > 0 {
            self.stat(name, |s| {
                s.gaps += gaps;
                s.corrupt_skipped += corrupt;
                s.mapping_updates_skipped += mapping_updates;
            });
        }

        if batch.is_empty() {
            // Nothing to send, but the cursors may still have moved (a fresh
            // start-at-the-end position, or frames that decoded to nothing).
            if new_cursors != known {
                self.state
                    .write()
                    .indices
                    .entry(name.to_string())
                    .or_default()
                    .shards = new_cursors;
                self.mark_dirty();
                if first_look {
                    // The tap just positioned at the end of an established
                    // index: it is caught up by definition, having deliberately
                    // skipped the history it cannot backfill. Seeding the
                    // watermark keeps `lag_seq` from reporting the whole of
                    // that history as a backlog the tap intends to ship.
                    self.stat(name, |s| {
                        s.last_shipped_seq = s.last_shipped_seq.max(head_seq);
                    });
                }
            }
            return more;
        }

        // Ship in seq order. Byte order is what the cursor resumes from, but
        // seq order is what decides which write wins — both here inside one
        // batch, and at any target that honours external versioning.
        batch.sort_by_key(|(seq, _)| *seq);

        let chunks = render_chunks(name, &batch, config.max_batch_bytes);
        if chunks.is_empty() {
            // Everything read was an entry kind that renders to nothing.
            self.state
                .write()
                .indices
                .entry(name.to_string())
                .or_default()
                .shards = new_cursors;
            self.mark_dirty();
            return more;
        }

        // `max_batch_bytes` bounds one HTTP request, not one poll: a target's
        // `http.max_content_length` is what it exists for. Every chunk of the
        // read has to land before the cursors move, so a failure part-way
        // through redelivers the earlier chunks on the next poll — which is
        // exactly what external versioning makes free.
        // Everything here is counted from the target's PER-ITEM verdict, not
        // from what was rendered. A `_bulk` that returns 200 while rejecting
        // every action inside it is a common, real state — a target holding
        // higher external versions for the same `_id`s makes every action a
        // no-op — and counting render-time values made that indistinguishable
        // from a healthy tap: `docs_shipped` climbed, `lag_seq` read 0, and
        // nothing had been replicated.
        let mut docs = 0u64;
        let mut deletes = 0u64;
        let mut max_accepted_seq = 0u64;
        let mut item_failures = 0u64;
        let mut version_conflicts = 0u64;
        let mut batches = 0u64;
        // Chunks in THIS poll that applied nothing. Kept separate from the
        // health counter on purpose: that counter is per poll (see
        // `UNAPPLIED_UNHEALTHY_AFTER`), and adding this into it is what made
        // one legitimate multi-chunk redelivery report the tap unhealthy.
        let mut unapplied_chunks = 0u32;
        let mut rejection_kind: Option<String> = None;

        for chunk in chunks {
            let actions = chunk.actions.clone();
            match self.send_bulk(config, chunk.body, actions.len()).await {
                SendOutcome::Accepted {
                    outcomes,
                    rejection,
                } => {
                    let mut accepted_here = 0u64;
                    for (action, outcome) in actions.iter().zip(outcomes.iter()) {
                        match outcome {
                            ItemOutcome::Accepted => {
                                accepted_here += 1;
                                max_accepted_seq = max_accepted_seq.max(action.seq);
                                if action.is_delete {
                                    deletes += 1;
                                } else {
                                    docs += 1;
                                }
                            }
                            ItemOutcome::Conflict => version_conflicts += 1,
                            ItemOutcome::Rejected => item_failures += 1,
                        }
                    }
                    // Nothing in this batch was applied. WHY is a separate
                    // question — a conflict says "a second writer beat us", a
                    // rejection says "the target will not take this document"
                    // — but the operational fact is identical and it is the
                    // one `healthy` answers. Counting only the conflict case
                    // let an all-`mapper_parsing_exception` response read as a
                    // healthy zero-lag tap with `docs_shipped: 0`.
                    if accepted_here == 0 && !actions.is_empty() {
                        unapplied_chunks += 1;
                    }
                    if rejection.is_some() {
                        rejection_kind = rejection;
                    }
                    batches += 1;
                }
                SendOutcome::Failed(err) => {
                    let failures = self.stat(name, |s| {
                        s.docs_shipped += docs;
                        s.deletes_shipped += deletes;
                        s.batches_sent += batches;
                        s.item_failures += item_failures;
                        s.version_conflicts += version_conflicts;
                        s.last_shipped_seq = s.last_shipped_seq.max(max_accepted_seq);
                        s.bulk_failures += 1;
                        s.consecutive_failures = s.consecutive_failures.saturating_add(1);
                        s.last_error = Some(err.clone());
                        s.consecutive_failures
                    });
                    warn!(index = %name, error = %err, failures,
                          "WAL tap: _bulk failed — cursor held, will retry");
                    self.arm_backoff(config, failures);
                    return false;
                }
            }
        }

        self.state
            .write()
            .indices
            .entry(name.to_string())
            .or_default()
            .shards = new_cursors;
        self.mark_dirty();
        let unhealthy = self.stat(name, |s| {
            s.docs_shipped += docs;
            s.deletes_shipped += deletes;
            s.batches_sent += batches;
            s.item_failures += item_failures;
            s.version_conflicts += version_conflicts;
            s.last_shipped_seq = s.last_shipped_seq.max(max_accepted_seq);
            s.consecutive_failures = 0;
            if let Some(kind) = &rejection_kind {
                s.last_item_rejection = Some(kind.clone());
            }
            // A run of POLLS that applied nothing is not "replication
            // working". Only a poll that landed something clears it.
            //
            // `+= 1`, not `+= unapplied_chunks`. How many `_bulk` requests a
            // poll needed is a function of `max_batch_bytes`, not of whether
            // replication is progressing: at `max_batch_bytes = 1` the old
            // shape turned ONE legitimate at-least-once redelivery of four
            // documents into `consecutive_unapplied = 4`, tripping the
            // three-in-a-row threshold on the documented-benign path and
            // emitting a `last_error` saying "nothing is being replicated"
            // about a poll in which every document was already at the target.
            if unapplied_chunks > 0 && docs == 0 && deletes == 0 {
                s.consecutive_unapplied_polls = s.consecutive_unapplied_polls.saturating_add(1);
            } else {
                s.consecutive_unapplied_polls = 0;
            }
            if s.consecutive_unapplied_polls >= UNAPPLIED_UNHEALTHY_AFTER {
                let run = s.consecutive_unapplied_polls;
                // Name the cause the target gave *this poll*, not whatever it
                // last gave: a conflict and a mapping error need opposite
                // responses from the operator, and a stale reason would send
                // them the wrong way. `item_failures` is this poll's count.
                let reason = if item_failures > 0 {
                    let kind = rejection_kind
                        .as_deref()
                        .or(s.last_item_rejection.as_deref())
                        .unwrap_or("an unnamed error");
                    format!(
                        "target accepted nothing in the last {run} polls — it rejected \
                         every action, most recently with {kind}. Nothing is being \
                         replicated; these documents are being dropped, not retried."
                    )
                } else {
                    format!(
                        "target rejected every action of the last {run} polls with \
                         version_conflict_engine_exception — it holds a higher version for \
                         every document this tap sends, so nothing is being replicated"
                    )
                };
                s.last_error = Some(reason);
                true
            } else {
                s.last_error = None;
                false
            }
        });
        if unhealthy {
            warn!(
                index = %name, version_conflicts, item_failures,
                rejection = ?rejection_kind,
                "WAL tap: the target is accepting the request and applying none of it. \
                 _stats reports the index unhealthy; check last_item_rejection, and \
                 whether the target is also fed by another writer."
            );
        }
        self.clear_backoff();
        debug!(index = %name, docs, deletes, batches, "WAL tap: batch shipped");
        more
    }

    /// Drop one index's cursors the moment it is deleted.
    ///
    /// Called from [`Engine::delete_index`](crate::engine::Engine::delete_index),
    /// and that timing is the whole point. A deletion is the exact boundary
    /// between two incarnations of a name: after it, any surviving cursor
    /// belongs to a WAL stream that no longer exists.
    ///
    /// Waiting for a poll to *notice* the absence — which is all
    /// [`forget_deleted`](Self::forget_deleted) can do — misses the case that
    /// matters, because `DELETE` + `PUT` inside one 500 ms poll interval is
    /// never observed as an absence at all. The recreated index then starts a
    /// new WAL at generation 0, so the `cursor.generation > newest` guard
    /// never trips, and the stale byte offset either landed past EOF (every
    /// document silently skipped, `gap` false) or mid-frame (the shard wedged
    /// forever with `gaps: 0` and `last_error: null`). Both are the failure a
    /// WAL consumer must never have, and both are unreachable from here.
    ///
    /// `tail_shard`'s offset-past-EOF check is the second line of defence,
    /// for a delete this process never saw — one that happened while the node
    /// was down.
    pub fn forget_index(&self, name: &str) {
        let removed = self.state.write().indices.remove(name).is_some();
        self.stats.write().remove(name);
        if removed {
            debug!(index = %name, "WAL tap: forgetting the cursor of a deleted index");
            self.persist_now();
        }
    }

    /// Drop cursors for indices that no longer exist.
    ///
    /// Hygiene for anything [`forget_index`](Self::forget_index) did not see:
    /// a deletion by a path that does not route through `Engine::delete_index`,
    /// or an index removed while this process was not running.
    fn forget_deleted(&self, live: &[String]) {
        let mut state = self.state.write();
        if state.indices.keys().all(|k| live.iter().any(|l| l == k)) {
            return;
        }
        state.indices.retain(|name, _| {
            let kept = live.iter().any(|l| l == name);
            if !kept {
                debug!(index = %name, "WAL tap: forgetting the cursor of a deleted index");
            }
            kept
        });
        drop(state);
        self.mark_dirty();
    }

    /// One full pass over the allowlisted indices. Exposed for tests; the
    /// server drives [`run`] instead.
    pub async fn tick(&self, engine: &Engine) {
        let config = self.config();
        self.ticks.fetch_add(1, Ordering::Relaxed);
        if !config.enabled || config.target_url.trim().is_empty() || config.indices.is_empty() {
            return;
        }
        if self.in_backoff() {
            return;
        }

        let live = engine.index_name_list();
        self.forget_deleted(&live);
        // One durable write per tick, at the end, whatever moved — not one
        // per index per poll. See `WalTap::dirty`.
        let _flush = FlushOnDrop(self);

        for name in live {
            if !Self::ships(&config, &name) {
                continue;
            }
            let Ok(index) = engine.get_index(&name) else {
                continue;
            };
            let wal_root = index.wal_dir();
            // `current_seq_no` is the NEXT seq to be handed out, so the highest
            // reserved one is that minus 1.
            let head_seq = index.current_seq_no().saturating_sub(1);
            // Keep draining an index that is behind, but bounded: at most a
            // few batches per tick so one busy index cannot starve the others.
            for _ in 0..4 {
                if !self
                    .poll_index(&config, &name, wal_root.clone(), head_seq)
                    .await
                {
                    break;
                }
            }
            if self.in_backoff() {
                break;
            }
        }
    }
}

/// Flushes the tap's cursor state when a tick ends, however it ends.
///
/// A guard rather than a call at the bottom of `tick`, because `tick` returns
/// early from several places (backoff armed mid-loop, a send failure) and a
/// missed flush means the *next* boot re-ships from an older cursor.
struct FlushOnDrop<'a>(&'a WalTap);

impl Drop for FlushOnDrop<'_> {
    fn drop(&mut self) {
        self.0.persist_if_dirty();
    }
}

/// Drive the tap until the process exits.
pub async fn run(tap: Arc<WalTap>, engine: Arc<Engine>) {
    info!("WAL tap loop started (disabled until wal_tap.enabled and a target are set)");
    loop {
        let interval = Duration::from_millis(tap.config().poll_interval_ms.clamp(50, 60_000));
        tokio::time::sleep(interval).await;
        tap.tick(&engine).await;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg(indices: &[&str]) -> WalTapConfig {
        WalTapConfig {
            enabled: true,
            target_url: "http://localhost:1".into(),
            indices: indices.iter().map(|s| s.to_string()).collect(),
            ..Default::default()
        }
    }

    #[test]
    fn allowlist_matches_globs() {
        let c = cfg(&["edge-*", "metrics"]);
        assert!(WalTap::ships(&c, "edge-logs"));
        assert!(WalTap::ships(&c, "metrics"));
        assert!(!WalTap::ships(&c, "orders"));
    }

    #[test]
    fn system_indices_are_never_shipped_even_by_a_star_allowlist() {
        let c = cfg(&["*"]);
        assert!(WalTap::ships(&c, "edge-logs"));
        assert!(!WalTap::ships(&c, ".xerj-memory-alice"));
        assert!(!WalTap::ships(&c, ".xerj_users"));
        assert!(!WalTap::ships(&c, ".xerj_api_tokens"));
        // …and naming one outright does not get round it either.
        assert!(!WalTap::ships(&cfg(&[".xerj_users"]), ".xerj_users"));
        assert!(!WalTap::ships(&cfg(&[".xerj*"]), ".xerj_sessions"));
    }

    /// A wildcard means "every ordinary index", not "also the hidden ones" —
    /// the same rule ES's `expand_wildcards` uses. An explicitly dotted
    /// pattern still reaches them.
    #[test]
    fn a_wildcard_does_not_expand_to_hidden_indices() {
        assert!(!WalTap::ships(&cfg(&["*"]), ".kibana"));
        assert!(WalTap::ships(&cfg(&[".kibana"]), ".kibana"));
        assert!(WalTap::ships(&cfg(&[".kib*"]), ".kibana"));
    }

    #[test]
    fn an_empty_allowlist_ships_nothing() {
        let c = cfg(&[]);
        assert!(!WalTap::ships(&c, "edge-logs"));
    }

    #[test]
    fn actions_carry_external_versioning_so_redelivery_is_idempotent() {
        let mut out = String::new();
        let entry = WalEntry::Index {
            doc_id: "d1".into(),
            source: json!({"a": 1}),
        };
        assert_eq!(
            render_action("edge-logs", 42, &entry, &mut out),
            Some(false)
        );
        let meta: Value = serde_json::from_str(out.lines().next().unwrap()).unwrap();
        assert_eq!(meta["index"]["_id"], "d1");
        assert_eq!(meta["index"]["_index"], "edge-logs");
        assert_eq!(meta["index"]["version"], 42);
        assert_eq!(meta["index"]["version_type"], "external");
        assert_eq!(out.lines().nth(1).unwrap(), r#"{"a":1}"#);

        let mut out = String::new();
        let del = WalEntry::Delete {
            doc_id: "d1".into(),
        };
        assert_eq!(render_action("edge-logs", 43, &del, &mut out), Some(true));
        let meta: Value = serde_json::from_str(out.lines().next().unwrap()).unwrap();
        assert_eq!(meta["delete"]["version"], 43);
        assert_eq!(out.lines().count(), 1);
    }

    #[test]
    fn mapping_updates_render_nothing() {
        let mut out = String::new();
        let entry = WalEntry::UpdateMapping { schema: json!({}) };
        assert_eq!(render_action("i", 1, &entry, &mut out), None);
        assert!(out.is_empty());
    }

    #[test]
    fn unreadable_state_file_starts_from_now_rather_than_from_garbage() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join(STATE_FILE), b"{not json").unwrap();
        let tap = WalTap::new(dir.path(), WalTapConfig::default());
        assert!(tap.cursors().is_empty());
    }

    #[test]
    fn backoff_is_capped_and_jittered() {
        let dir = tempfile::tempdir().unwrap();
        let config = WalTapConfig {
            poll_interval_ms: 500,
            max_retry_backoff_secs: 10,
            ..Default::default()
        };
        let tap = WalTap::new(dir.path(), config.clone());
        tap.arm_backoff(&config, 30);
        let armed = tap.retry_not_before_ms.load(Ordering::Relaxed);
        let delay = armed.saturating_sub(tap.now_ms());
        assert!(
            delay <= 10_000,
            "backoff must respect the cap, got {delay}ms"
        );
        assert!(
            delay >= 4_000,
            "backoff must still be substantial, got {delay}ms"
        );
    }

    /// `max_retry_backoff_secs` reaches [`WalTap::arm_backoff`] from the config
    /// file as well as from `PUT /_xerj/wal_tap`, and `Config::validate` does
    /// not range-check it — so any `u64` in `xerj.toml` gets here.
    ///
    /// The value below is chosen so the OLD `secs.max(1) * 1000` fails in both
    /// profiles rather than only one: `18_446_744_073_709_552 * 1000` is
    /// `18_446_744_073_709_552_000`, which is `2^64 + 384`, so it panics under
    /// `cargo test`'s overflow-checks (killing the spawned tap task with
    /// nothing in `_stats` to say why) and **wraps to a 384 ms cap** under
    /// `--profile ci-test` — a retry storm aimed at a target that is already
    /// failing. Saturating leaves the exponential backoff itself in charge.
    #[test]
    fn an_unbounded_retry_cap_saturates_instead_of_wrapping() {
        let dir = tempfile::tempdir().unwrap();
        let config = WalTapConfig {
            poll_interval_ms: 500,
            max_retry_backoff_secs: 18_446_744_073_709_552,
            ..Default::default()
        };
        let tap = WalTap::new(dir.path(), config.clone());
        // failures = 3 → shift 2 → uncapped = 500 * 4 = 2_000 ms, then jitter
        // in [50%, 100%].
        tap.arm_backoff(&config, 3);
        let armed = tap.retry_not_before_ms.load(Ordering::Relaxed);
        let delay = armed.saturating_sub(tap.now_ms());
        assert!(
            (900..=2_000).contains(&delay),
            "a cap too large to express in ms must not become a SMALL cap; the wrapped \
             value gives at most 384ms. got {delay}ms"
        );
    }
}

//! Exact keyed ordering for document publication.
//!
//! A key exists in the registry only while a holder or waiter owns a strong
//! reference to its mutex. The registry keeps a `Weak`, so idle document IDs
//! do not accumulate forever.

use std::sync::{Arc, Weak};

use dashmap::mapref::entry::Entry;
use dashmap::DashMap;
use tokio::sync::{Mutex, OwnedMutexGuard};

pub(crate) struct WritePublicationCoordinator {
    locks: DashMap<String, Weak<Mutex<()>>>,
    #[cfg(test)]
    before_mutex_await: parking_lot::RwLock<Option<Arc<dyn Fn(&str) + Send + Sync + 'static>>>,
}

impl Default for WritePublicationCoordinator {
    fn default() -> Self {
        Self {
            // #873 — one coordinator per index; dashmap's core-count-derived
            // default shard array is resident from construction, so it is
            // capped like every other per-index map.
            locks: DashMap::with_shard_amount(xerj_common::resource::per_index_map_shards()),
            #[cfg(test)]
            before_mutex_await: parking_lot::RwLock::new(None),
        }
    }
}

pub(crate) struct WritePublicationGuard {
    coordinator: Arc<WritePublicationCoordinator>,
    key: String,
    lock: Arc<Mutex<()>>,
    guard: Option<OwnedMutexGuard<()>>,
}

/// Owns the registry's strong reference while `lock_owned()` is pending.
///
/// This is deliberately separate from [`WritePublicationGuard`]: cancelling
/// the acquire future never constructs a guard, so cleanup must live in a
/// value that already exists before the `.await`.
struct PendingLock {
    coordinator: Arc<WritePublicationCoordinator>,
    key: String,
    lock: Option<Arc<Mutex<()>>>,
}

impl WritePublicationCoordinator {
    pub(crate) fn new() -> Arc<Self> {
        Arc::new(Self::default())
    }

    pub(crate) async fn lock(self: &Arc<Self>, key: impl Into<String>) -> WritePublicationGuard {
        self.lock_inner(key.into(), None).await
    }

    async fn lock_inner(
        self: &Arc<Self>,
        key: String,
        before_await: Option<Box<dyn FnOnce() + Send>>,
    ) -> WritePublicationGuard {
        let lock = match self.locks.entry(key.clone()) {
            Entry::Occupied(mut occupied) => match occupied.get().upgrade() {
                Some(lock) => lock,
                None => {
                    let lock = Arc::new(Mutex::new(()));
                    occupied.insert(Arc::downgrade(&lock));
                    lock
                }
            },
            Entry::Vacant(vacant) => {
                let lock = Arc::new(Mutex::new(()));
                vacant.insert(Arc::downgrade(&lock));
                lock
            }
        };
        // Runs after the registry entry guard is gone and immediately before
        // queueing. Tests use this handshake to cancel a known waiter without
        // sleeps or scheduler guesses.
        if let Some(before_await) = before_await {
            before_await();
        }
        #[cfg(test)]
        {
            let hook = self.before_mutex_await.read().clone();
            if let Some(hook) = hook {
                hook(&key);
            }
        }
        let mut pending = PendingLock {
            coordinator: Arc::clone(self),
            key: key.clone(),
            lock: Some(lock),
        };
        let guard = Arc::clone(pending.lock.as_ref().expect("pending lock present"))
            .lock_owned()
            .await;
        let lock = pending.lock.take().expect("pending lock present");
        WritePublicationGuard {
            coordinator: Arc::clone(self),
            key,
            lock,
            guard: Some(guard),
        }
    }

    #[cfg(test)]
    async fn lock_with_before_await(
        self: &Arc<Self>,
        key: impl Into<String>,
        before_await: impl FnOnce() + Send + 'static,
    ) -> WritePublicationGuard {
        self.lock_inner(key.into(), Some(Box::new(before_await)))
            .await
    }

    /// Acquire a deadlock-free set of exact document keys.
    ///
    /// Sorting gives every caller one global acquisition order; deduplication
    /// prevents a request from waiting on its own non-reentrant key.
    #[allow(dead_code)]
    pub(crate) async fn lock_many<I, S>(self: &Arc<Self>, keys: I) -> Vec<WritePublicationGuard>
    where
        I: IntoIterator<Item = S>,
        S: Into<String>,
    {
        let mut keys: Vec<String> = keys.into_iter().map(Into::into).collect();
        keys.sort_unstable();
        keys.dedup();

        let mut guards = Vec::with_capacity(keys.len());
        for key in keys {
            guards.push(self.lock(key).await);
        }
        guards
    }

    #[cfg(test)]
    fn registry_len(&self) -> usize {
        self.locks.len()
    }

    #[cfg(test)]
    pub(crate) fn set_before_mutex_await_hook(
        &self,
        hook: Option<Arc<dyn Fn(&str) + Send + Sync + 'static>>,
    ) {
        *self.before_mutex_await.write() = hook;
    }
}

fn remove_if_idle(coordinator: &WritePublicationCoordinator, key: &str, lock: &Arc<Mutex<()>>) {
    if let Entry::Occupied(occupied) = coordinator.locks.entry(key.to_string()) {
        let is_same = occupied
            .get()
            .upgrade()
            .map(|registered| Arc::ptr_eq(&registered, lock))
            .unwrap_or(false);
        if is_same && Arc::strong_count(lock) == 1 {
            occupied.remove();
        }
    }
}

impl Drop for PendingLock {
    fn drop(&mut self) {
        if let Some(lock) = self.lock.as_ref() {
            remove_if_idle(&self.coordinator, &self.key, lock);
        }
    }
}

impl Drop for WritePublicationGuard {
    fn drop(&mut self) {
        // Release the mutex before attempting registry cleanup. Any queued
        // waiter already owns another strong Arc and therefore prevents
        // removal below.
        self.guard.take();

        remove_if_idle(&self.coordinator, &self.key, &self.lock);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[tokio::test]
    async fn same_key_is_strictly_ordered_and_cleans_up() {
        let coordinator = WritePublicationCoordinator::new();
        let first = coordinator.lock("same").await;
        let (attempt_tx, attempt_rx) = tokio::sync::oneshot::channel();
        let (acquired_tx, mut acquired_rx) = tokio::sync::oneshot::channel();

        let task = {
            let coordinator = Arc::clone(&coordinator);
            tokio::spawn(async move {
                attempt_tx.send(()).unwrap();
                let _second = coordinator.lock("same").await;
                acquired_tx.send(()).unwrap();
            })
        };
        attempt_rx.await.unwrap();
        assert!(
            acquired_rx.try_recv().is_err(),
            "same key entered before the first guard was released"
        );
        assert_eq!(coordinator.registry_len(), 1);

        drop(first);
        acquired_rx.await.unwrap();
        task.await.unwrap();
        assert_eq!(coordinator.registry_len(), 0);
    }

    #[tokio::test]
    async fn disjoint_keys_do_not_block_each_other() {
        let coordinator = WritePublicationCoordinator::new();
        let _a = coordinator.lock("a").await;
        tokio::time::timeout(Duration::from_millis(100), coordinator.lock("b"))
            .await
            .expect("unrelated key must not wait");
    }

    #[tokio::test]
    async fn lock_many_sorts_deduplicates_and_cleans_up() {
        let coordinator = WritePublicationCoordinator::new();
        let guards = coordinator.lock_many(["c", "a", "b", "a"]).await;
        assert_eq!(guards.len(), 3);
        assert_eq!(coordinator.registry_len(), 3);
        drop(guards);
        assert_eq!(coordinator.registry_len(), 0);
    }

    #[tokio::test]
    async fn registry_is_bounded_by_live_keys_not_historical_keys() {
        let coordinator = WritePublicationCoordinator::new();
        for i in 0..10_000 {
            let guard = coordinator.lock(format!("historical-{i}")).await;
            drop(guard);
        }
        assert_eq!(
            coordinator.registry_len(),
            0,
            "idle document IDs must not remain in the registry"
        );
    }

    #[tokio::test]
    async fn cancellation_and_failure_style_early_return_release_key() {
        async fn fail_after_lock(
            coordinator: Arc<WritePublicationCoordinator>,
        ) -> Result<(), &'static str> {
            let _guard = coordinator.lock("wal-failure").await;
            Err("injected WAL failure")
        }

        let coordinator = WritePublicationCoordinator::new();
        assert_eq!(
            fail_after_lock(Arc::clone(&coordinator)).await,
            Err("injected WAL failure")
        );
        assert_eq!(coordinator.registry_len(), 0);
        tokio::time::timeout(Duration::from_millis(100), coordinator.lock("wal-failure"))
            .await
            .expect("key leaked after early error");
    }

    #[tokio::test]
    async fn cancelling_a_queued_waiter_does_not_leak_or_wedge_the_key() {
        let coordinator = WritePublicationCoordinator::new();
        let first = coordinator.lock("cancelled").await;
        let (attempt_tx, attempt_rx) = tokio::sync::oneshot::channel();
        let waiter = {
            let coordinator = Arc::clone(&coordinator);
            tokio::spawn(async move {
                let _guard = coordinator
                    .lock_with_before_await("cancelled", move || {
                        attempt_tx.send(()).unwrap();
                    })
                    .await;
            })
        };
        attempt_rx.await.unwrap();
        waiter.abort();
        assert!(waiter.await.unwrap_err().is_cancelled());
        drop(first);

        assert_eq!(coordinator.registry_len(), 0);
        let guard = coordinator.lock("cancelled").await;
        drop(guard);
    }

    #[tokio::test]
    async fn reversed_multi_key_requests_complete_without_deadlock() {
        let coordinator = WritePublicationCoordinator::new();
        let start = Arc::new(tokio::sync::Barrier::new(3));
        let left = {
            let coordinator = Arc::clone(&coordinator);
            let start = Arc::clone(&start);
            tokio::spawn(async move {
                start.wait().await;
                let guards = coordinator.lock_many(["b", "a"]).await;
                tokio::task::yield_now().await;
                drop(guards);
            })
        };
        let right = {
            let coordinator = Arc::clone(&coordinator);
            let start = Arc::clone(&start);
            tokio::spawn(async move {
                start.wait().await;
                let guards = coordinator.lock_many(["a", "b"]).await;
                tokio::task::yield_now().await;
                drop(guards);
            })
        };
        start.wait().await;

        tokio::time::timeout(Duration::from_secs(1), left)
            .await
            .expect("sorted acquisition deadlocked")
            .unwrap();
        tokio::time::timeout(Duration::from_secs(1), right)
            .await
            .expect("second sorted acquisition stayed wedged")
            .unwrap();
        assert_eq!(coordinator.registry_len(), 0);
    }
}

//! `config.limits.max_buckets` must bind the columnar fast path exactly as it
//! binds the brute path (issue #121).
//!
//! `fast_aggs.rs` used to carry its own `const MAX_BUCKETS: i64 = 65_536` in
//! `exec_date_histogram` and `exec_histogram`, so an operator who lowered the
//! cap to protect memory got that protection only on queries that happened to
//! miss the columnar path — and the discrepancy was invisible, because the two
//! executors otherwise return byte-identical results.
//!
//! Which executor answered is read from `aggs::fast_path_aggs_served`; the
//! brute half of each pair is forced by keeping that index under the columnar
//! path's own size gate (`fast_aggs::FAST_AGG_MIN_DOCS`, 10 000 docs) — same
//! agg, same bucket span, different executor.
//!
//! This suite gets its own test binary on purpose: `Engine::new` installs the
//! cap in a process-wide static (`aggs::set_max_buckets`), so every engine in
//! the file must agree on one value and no other suite may observe it. For the
//! same reason it is deliberately ONE test function — parallel tests in one
//! binary would race on both the cap and the fast-path counter.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::aggs::fast_path_aggs_served;
use xerj_engine::bulk::process_bulk;
use xerj_engine::Engine;
use xerj_query::parse_request;

/// Lowered far below the stock 65 536 so a corpus that trips it is still
/// small enough to index inside a test.
const CAP: usize = 64;

/// Docs in an index that must take the columnar path — `fast_aggs` refuses to
/// serve an index below its own `FAST_AGG_MIN_DOCS` (10 000).
const BIG_DOCS: usize = 10_050;

/// Docs in an index that must NOT take the columnar path: same shape, same
/// bucket spans, on the other side of that gate.
const SMALL_DOCS: usize = 900;

const HOUR_MS: i64 = 3_600_000;
/// Hour-aligned epoch-ms, so one distinct `hour` offset == one `1h` bucket.
const BASE_MS: i64 = 1_699_999_200_000;

/// A corpus shape: how many distinct `ts` hours and how many distinct `n`
/// values its docs cycle through — i.e. how many buckets a gap-filled
/// histogram over the whole corpus has to materialise.
#[derive(Clone, Copy)]
struct Shape {
    hours: usize,
    nvals: usize,
}

/// Exactly at the cap. `date_histogram` counts buckets, `histogram` compares
/// `max_key - min_key` (a difference, not a count — pre-existing, and the
/// same on both paths), so "at the cap" is `CAP` hours and `CAP + 1` values.
const AT_CAP: Shape = Shape {
    hours: CAP,
    nvals: CAP + 1,
};
/// One bucket past the cap on both aggs.
const OVER_CAP: Shape = Shape {
    hours: CAP + 1,
    nvals: CAP + 2,
};

fn ndjson_batch(index: &str, shape: Shape, ids: std::ops::Range<usize>) -> String {
    let mut out = String::with_capacity(ids.len() * 96);
    for i in ids {
        out.push_str(&format!(
            "{{\"index\":{{\"_index\":\"{index}\",\"_id\":\"{i}\"}}}}\n"
        ));
        let ts = BASE_MS + (i % shape.hours) as i64 * HOUR_MS;
        let n = (i % shape.nvals) as i64;
        out.push_str(&format!("{{\"ts\":{ts},\"n\":{n}}}\n"));
    }
    out
}

async fn build_index(engine: &Engine, name: &str, docs: usize, shape: Shape) {
    engine.create_index(name, Schema::empty()).unwrap();
    for start in (0..docs).step_by(1_000) {
        let end = (start + 1_000).min(docs);
        let body = ndjson_batch(name, shape, start..end);
        let res = process_bulk(engine, Some(name), &body).await;
        assert!(!res.errors, "bulk errors while seeding {name}");
    }
    // Flush to segments: the columnar path reads `.dv` sidecars, and
    // `exec_histogram` only runs when the field has a real numeric column.
    engine.get_index(name).unwrap().refresh().await.unwrap();
}

/// Run one `size:0 + match_all` agg request and report both the agg body and
/// whether the columnar fast path served it.
async fn run_agg(engine: &Engine, index: &str, agg: Value) -> (Value, u64) {
    let idx = engine.get_index(index).unwrap();
    let req = parse_request(&json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": { "a": agg },
    }))
    .unwrap();
    let before = fast_path_aggs_served();
    let res = idx.search(&req).await.unwrap();
    let served = fast_path_aggs_served() - before;
    let aggs = res.aggs.clone().expect("aggs present");
    (aggs["a"].clone(), served)
}

/// The too_many_buckets marker the agg runners embed, if present. It carries
/// the cap that was actually enforced — `[64]` here, `[65536]` before the fix.
fn too_many_buckets(agg: &Value) -> Option<String> {
    let msg = agg.get("error")?.as_str()?;
    assert_eq!(agg.get("__error_status__"), Some(&json!(400)));
    assert!(
        msg.contains("Trying to create too many buckets"),
        "unexpected agg error: {msg}"
    );
    Some(msg.to_string())
}

fn bucket_count(agg: &Value) -> usize {
    agg["buckets"]
        .as_array()
        .unwrap_or_else(|| panic!("expected buckets, got {agg}"))
        .len()
}

#[tokio::test]
async fn lowered_max_buckets_binds_the_columnar_fast_path_and_the_brute_path_alike() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config.limits.max_buckets = CAP;
    let engine = Engine::new(config).expect("engine::new");

    build_index(&engine, "big-over", BIG_DOCS, OVER_CAP).await;
    build_index(&engine, "big-at", BIG_DOCS, AT_CAP).await;
    build_index(&engine, "small-over", SMALL_DOCS, OVER_CAP).await;
    build_index(&engine, "small-at", SMALL_DOCS, AT_CAP).await;

    let date_hist = json!({"date_histogram": {"field": "ts", "fixed_interval": "1h"}});
    let num_hist = json!({"histogram": {"field": "n", "interval": 1}});

    // ── Fast path: the lowered cap must trip it ──────────────────────────
    let (agg, served) = run_agg(&engine, "big-over", date_hist.clone()).await;
    assert_eq!(served, 1, "date_histogram did not take the columnar path");
    let fast_date_err = too_many_buckets(&agg).unwrap_or_else(|| {
        panic!(
            "fast path ignored max_buckets={CAP} and returned {} buckets: {agg}",
            bucket_count(&agg)
        )
    });
    assert!(
        fast_date_err.contains(&format!("[{CAP}]")),
        "fast path reported a cap it did not enforce: {fast_date_err}"
    );

    let (agg, served) = run_agg(&engine, "big-over", num_hist.clone()).await;
    assert_eq!(served, 1, "histogram did not take the columnar path");
    let fast_num_err = too_many_buckets(&agg).unwrap_or_else(|| {
        panic!(
            "fast path ignored max_buckets={CAP} and returned {} buckets: {agg}",
            bucket_count(&agg)
        )
    });
    assert!(
        fast_num_err.contains(&format!("[{CAP}]")),
        "fast path reported a cap it did not enforce: {fast_num_err}"
    );

    // ── Fast path: a span exactly at the cap must still be answered ──────
    let (agg, served) = run_agg(&engine, "big-at", date_hist.clone()).await;
    assert_eq!(served, 1, "date_histogram did not take the columnar path");
    assert_eq!(bucket_count(&agg), CAP, "cap-sized span must be served");

    let (agg, served) = run_agg(&engine, "big-at", num_hist.clone()).await;
    assert_eq!(served, 1, "histogram did not take the columnar path");
    assert_eq!(bucket_count(&agg), CAP + 1, "cap-sized span must be served");

    // ── Brute path: same shapes, below the columnar path's size gate ─────
    // Same trip point, same message, same bucket counts.
    let (agg, served) = run_agg(&engine, "small-over", date_hist.clone()).await;
    assert_eq!(served, 0, "the small index must not take the fast path");
    assert_eq!(
        too_many_buckets(&agg),
        Some(fast_date_err),
        "brute and fast date_histogram disagree about the cap"
    );

    let (agg, served) = run_agg(&engine, "small-over", num_hist.clone()).await;
    assert_eq!(served, 0, "the small index must not take the fast path");
    assert_eq!(
        too_many_buckets(&agg),
        Some(fast_num_err),
        "brute and fast histogram disagree about the cap"
    );

    let (agg, served) = run_agg(&engine, "small-at", date_hist).await;
    assert_eq!(served, 0, "the small index must not take the fast path");
    assert_eq!(bucket_count(&agg), CAP, "brute dropped a cap-sized span");

    let (agg, served) = run_agg(&engine, "small-at", num_hist).await;
    assert_eq!(served, 0, "the small index must not take the fast path");
    assert_eq!(
        bucket_count(&agg),
        CAP + 1,
        "brute dropped a cap-sized span"
    );
}

//! `config.limits.max_buckets` must bind the columnar `terms` fast path
//! (`fast_aggs::exec_terms`) exactly as it binds the brute `run_terms` — the
//! half of issue #121 left open by PR #125 (which fixed the histogram paths).
//!
//! `exec_terms` built its term map with NO bucket cap of any kind — only a
//! `size`-derived OUTPUT cap. Measured at `max_buckets = 37` over 200 distinct
//! terms, the fast path (a 12 000-doc index) materialised every one of the 200
//! terms while the brute path (a 600-doc index of identical shape) stopped at
//! 37. That is the OOM vector the cap exists to close, honoured on brute and
//! ignored on the columnar path.
//!
//! ## Why the fix BAILS rather than errors or truncates
//!
//! The two executors must AGREE past the cap. Brute `run_terms` does not error
//! there: it keeps the first `max_buckets` distinct terms in doc-iteration
//! order, drops the rest, and reports a `sum_other_doc_count` computed only
//! over the terms it kept — so the dropped terms vanish silently and the total
//! conceals them (order-dependent, and a bug in its own right). Reproducing
//! that on the fast path would copy the bug, not the contract; erroring would
//! make the fast path disagree with a brute path that still returns a body.
//!
//! So `exec_terms` bails to brute the instant its distinct-term count would
//! exceed the cap. After the bail the request is answered by the very
//! `run_terms` the fast path would be measured against, so the two AGREE past
//! the cap by construction. What this test pins is that agreement plus the two
//! observable consequences of the bail: the fast path stops SERVING the
//! over-cap agg (`fast_path_aggs_served` no longer ticks) and the answer honours
//! the cap (exactly `CAP` distinct buckets, not all `NTERMS`).
//!
//! Which executor answered is read from `aggs::fast_path_aggs_served`; the brute
//! leg is forced by keeping an index under the columnar path's own size gate
//! (`fast_aggs::FAST_AGG_MIN_DOCS`, 10 000 docs).
//!
//! Its own test binary, one test function: `Engine::new` installs the cap in a
//! process-wide static (`aggs::set_max_buckets`) and the fast-path counter is a
//! process-wide atomic, so every engine here must agree on one value and no
//! parallel test may race them — the same reason `agg_bucket_cap.rs` is one
//! function in its own binary.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::aggs::fast_path_aggs_served;
use xerj_engine::bulk::process_bulk;
use xerj_engine::Engine;
use xerj_query::parse_request;

/// The measured cap from the issue: far below the stock 65 536.
const CAP: usize = 37;

/// Distinct `tag` values in an over-cap corpus — the issue's 200.
const NTERMS: usize = 200;

/// Docs in an index that must take the columnar path — `fast_aggs` refuses to
/// serve an index below its own `FAST_AGG_MIN_DOCS` (10 000).
const BIG_DOCS: usize = 10_050;

/// Docs in an index that must NOT take the columnar path: same shape, on the
/// other side of that gate. 600 ≥ NTERMS, so every distinct term is present.
const SMALL_DOCS: usize = 600;

fn ndjson_batch(index: &str, nterms: usize, ids: std::ops::Range<usize>) -> String {
    let mut out = String::with_capacity(ids.len() * 72);
    for i in ids {
        out.push_str(&format!(
            "{{\"index\":{{\"_index\":\"{index}\",\"_id\":\"{i}\"}}}}\n"
        ));
        // `tag` is a DECLARED keyword field (see `build_index`) → a keyword
        // doc-values column stored under the unsuffixed name, which
        // `terms: {field: "tag"}` reads on the fast path. It is declared rather
        // than inferred because #1329 made a *dynamically* mapped string a
        // `text` parent with NO doc-values (only its `.keyword` sub-field keeps
        // them, matching ES), so an inferred `tag` would have no unsuffixed
        // column for the fast path to read and every leg would bail to brute —
        // which would silently defeat this test's whole point (that the cap
        // binds the *fast* path). `i % nterms` gives exactly `nterms` distinct
        // keys.
        let tag = i % nterms;
        out.push_str(&format!("{{\"tag\":\"t{tag}\"}}\n"));
    }
    out
}

async fn build_index(engine: &Engine, name: &str, docs: usize, nterms: usize) {
    // Declare `tag` as keyword so it owns a doc-values column under its own
    // unsuffixed name — the column the columnar `exec_terms` fast path reads.
    // A declared keyword keeps `doc_values = true` (unaffected by #1329, which
    // only flipped the default for INFERRED `text` parents), so the fast path
    // engages here exactly as issue #121 requires.
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("tag", FieldType::Keyword));
    engine.create_index(name, schema).unwrap();
    for start in (0..docs).step_by(1_000) {
        let end = (start + 1_000).min(docs);
        let body = ndjson_batch(name, nterms, start..end);
        let res = process_bulk(engine, Some(name), &body).await;
        assert!(!res.errors, "bulk errors while seeding {name}");
    }
    // Flush to segments: the columnar path reads `.dv` sidecars.
    engine.get_index(name).unwrap().refresh().await.unwrap();
}

/// Run one `size:0 + match_all` terms agg (with `size:0` on the agg too, so the
/// OUTPUT is uncapped and the bucket count equals the distinct terms KEPT) and
/// report both the agg body and whether the columnar fast path served it.
async fn run_terms(engine: &Engine, index: &str) -> (Value, u64) {
    let idx = engine.get_index(index).unwrap();
    let req = parse_request(&json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": { "by_tag": { "terms": { "field": "tag", "size": 0 } } },
    }))
    .unwrap();
    let before = fast_path_aggs_served();
    let res = idx.search(&req).await.unwrap();
    let served = fast_path_aggs_served() - before;
    let aggs = res.aggs.clone().expect("aggs present");
    (aggs["by_tag"].clone(), served)
}

fn bucket_count(agg: &Value) -> usize {
    agg["buckets"]
        .as_array()
        .unwrap_or_else(|| panic!("expected buckets, got {agg}"))
        .len()
}

#[tokio::test]
async fn lowered_max_buckets_binds_the_columnar_terms_path_and_the_brute_path_alike() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config.limits.max_buckets = CAP;
    let engine = Engine::new(config).expect("engine::new");

    build_index(&engine, "big-over", BIG_DOCS, NTERMS).await;
    build_index(&engine, "big-at", BIG_DOCS, CAP).await;
    build_index(&engine, "small-over", SMALL_DOCS, NTERMS).await;

    // ── Fast path, cardinality PAST the cap ──────────────────────────────
    // The regression: before the fix this was served columnarly (served == 1)
    // and returned all NTERMS buckets. The fix bails to brute, so the fast path
    // no longer serves it and the brute cap (exactly CAP distinct terms) binds.
    let (agg, served) = run_terms(&engine, "big-over").await;
    assert_eq!(
        served,
        0,
        "exec_terms served an over-cap agg columnarly instead of bailing; it \
         returned {} buckets against max_buckets={CAP}",
        bucket_count(&agg)
    );
    assert_eq!(
        bucket_count(&agg),
        CAP,
        "over-cap terms agg did not honour max_buckets={CAP}: {}",
        bucket_count(&agg)
    );

    // ── Brute path, same over-cap shape below the size gate ──────────────
    // The path the fast leg bails INTO. It agrees on the cap: exactly CAP
    // distinct buckets. (The kept terms are order-dependent and the doc counts
    // differ from the big index, so agreement is on the count, per the issue.)
    let (agg, served) = run_terms(&engine, "small-over").await;
    assert_eq!(served, 0, "the small index must not take the fast path");
    assert_eq!(
        bucket_count(&agg),
        CAP,
        "brute run_terms disagrees with the fast path on the cap"
    );

    // ── Fast path, cardinality exactly AT the cap ────────────────────────
    // The fix must bail only when the count would EXCEED the cap: an at-cap
    // agg is still served columnarly and returns all CAP buckets. (This guards
    // against over-bailing; it is not a regression detector — the pre-fix code
    // also served this case.)
    let (agg, served) = run_terms(&engine, "big-at").await;
    assert_eq!(
        served, 1,
        "exec_terms bailed on an at-cap agg it should still serve"
    );
    assert_eq!(
        bucket_count(&agg),
        CAP,
        "at-cap terms agg dropped or invented a bucket"
    );
}

//! Regression test for issue #751 — the CI hang.
//!
//! `Index::search` runs the whole search body inside
//! `block_in_place(|| Handle::current().block_on(search_fut))` on a
//! multi-thread runtime (the M5.21 read-throughput fix). `block_in_place`
//! hands the worker's core to a **tokio blocking-pool** thread and keeps the
//! calling thread parked for the entire search — await points included.
//!
//! An aggregation that has no columnar fast path then assembles the full
//! corpus, and a cold flushed segment is hydrated by
//! `Index::stored_values_for_async`. Before the fix that hydration queued its
//! decode with `tokio::task::spawn_blocking` — i.e. **onto the same blocking
//! pool the search is already holding a thread of**. tokio only grows that
//! pool when it observes zero idle threads at push time; when it cannot grow
//! (or when the core hand-off has just consumed the one thread it thought was
//! idle) the decode task is queued behind threads that are all running worker
//! cores and never return to the pool. The search then waits for a task that
//! can never be scheduled — forever. That is the CI hang: `cargo test` at
//! default parallelism sat in
//! `script_bucketed_agg_past_the_call_depth_limit_is_an_error_not_empty_buckets`
//! until the 12-minute step timeout killed the job.
//!
//! The runtime below makes the starvation deterministic rather than a race:
//! one worker, and a blocking pool that may hold exactly one extra thread —
//! which `block_in_place`'s core hand-off takes. On the unfixed engine the
//! search never returns; the watchdog turns that into a named failure instead
//! of a hang, because a regression test for a hang must never hang.

use serde_json::json;
use std::time::Duration;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

/// Long enough that a slow machine is never mistaken for the deadlock (the
/// search itself is single-digit milliseconds), short enough that a regression
/// fails a CI step instead of hanging it.
const WATCHDOG: Duration = Duration::from_secs(60);

fn test_config(dir: &TempDir) -> Config {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    // Keep every flush explicit: this test is about the *cold read* of an
    // already-published segment, not about flush scheduling.
    config.storage.flush_size_mb = 4096;
    config.storage.flush_interval_secs = 3600;
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config
}

/// A `terms` agg keyed by a Painless script. Scripts carry no field mapping,
/// so no columnar/doc-values fast path can serve this — it forces the
/// full-corpus assembly that hydrates every flushed segment's stored section,
/// which is the path that deadlocked.
fn scripted_terms_agg() -> xerj_query::ast::SearchRequest {
    parse_request(&json!({
        "size": 0,
        "query": { "match_all": {} },
        "aggs": {
            "by_script": { "terms": { "script": { "source": "return doc['rank'];" } } }
        }
    }))
    .expect("parse_request")
}

#[test]
fn agg_corpus_hydration_completes_when_the_blocking_pool_cannot_grow() {
    let (tx, rx) = std::sync::mpsc::channel::<()>();
    let worker = std::thread::Builder::new()
        .stack_size(8 * 1024 * 1024)
        .spawn(move || {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                // One worker + one spare blocking thread. `block_in_place`
                // inside `Index::search` hands the worker's core to that one
                // spare, so any *further* `spawn_blocking` submitted while the
                // search is in flight has no thread that will ever run it.
                .worker_threads(1)
                .max_blocking_threads(1)
                .enable_all()
                .build()
                .expect("build test runtime");
            runtime.block_on(async move {
                let dir = TempDir::new().expect("tempdir");
                let engine = Engine::new(test_config(&dir)).expect("engine::new");
                engine
                    .create_index("aggs", Schema::empty())
                    .expect("create");
                let idx = engine.get_index("aggs").expect("get_index");
                idx.index_document(Some("1".into()), json!({ "rank": 7 }))
                    .await
                    .expect("index_document");
                // Publishes a segment; the stored section stays cold, so the
                // agg corpus below has to hydrate it.
                idx.refresh().await.expect("refresh");

                // The search must run ON A WORKER for `block_in_place` to take
                // its core — `Runtime::block_on`'s own thread holds no core and
                // would run the closure inline, hiding the bug.
                let searcher = std::sync::Arc::clone(&idx);
                tokio::spawn(async move { searcher.search(&scripted_terms_agg()).await })
                    .await
                    .expect("search task")
                    .expect("search");
                // Keep the data dir alive until the search is done.
                drop(dir);
            });
            let _ = tx.send(());
        })
        .expect("spawn test thread");

    match rx.recv_timeout(WATCHDOG) {
        Ok(()) => {
            worker.join().expect("test thread panicked");
        }
        Err(_) => panic!(
            "issue #751: the aggregation-corpus segment hydration never completed in {WATCHDOG:?}. \
             The cold-segment decode is waiting on the tokio blocking pool while the search that \
             needs it is itself parked on a blocking-pool thread inside `block_in_place` — a \
             self-deadlock, not a slow test."
        ),
    }
}

//! Issue #464: `max_query_memory_mb` does not cover aggregation memory.
//!
//! The per-query memory guard (`governor::check_query_alloc`) is called only for
//! the search result window (`from + size` hits). An aggregation request runs
//! with `size: 0`, so that estimate is 0 and the guard passes — yet the brute
//! full-corpus agg path deep-clones EVERY memtable (and segment) source into an
//! owned `Value` to feed `run_aggs_with_all`. Under a bulk writer the memtable
//! holds 10^4-10^5 docs, so a single agg allocated multiples of the configured
//! limit with the guard none the wiser.
//!
//! This path is reached by ANY agg that bails the columnar fast path: a
//! meta-observing `top_hits` (which needs `_id`/source per bucket), and equally
//! the no-meta families with no columnar path at all — `percentiles`,
//! `date_histogram`, `cardinality`. The fix estimates the corpus materialisation
//! (memtable + flushed-segment docs) up front and rejects before the clone.
//!
//! This test installs a low `max_query_memory_mb`, fills the memtable with more
//! documents than that budget can materialise, and asserts BOTH a `top_hits`
//! agg (meta-observing) and a `percentiles` agg (no meta fields) are REJECTED —
//! the single corpus guard must bind the whole family, not just meta aggs.
//! Fail-before: without the guard either request returns 200 — the point of #464.
//!
//! Own test binary on purpose: `Engine::new` installs `max_query_memory_mb` in
//! the process-wide governor static, so no other suite may observe this budget.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

/// 1 MiB budget. The corpus estimate is `corpus_docs * per-doc bytes`; well
/// under a thousand buffered docs already exceeds this.
const BUDGET_MB: u64 = 1;
/// Enough buffered docs that the corpus materialisation estimate clears the
/// 1 MiB budget, but few enough to stay in the memtable (no flush) and below
/// `FAST_AGG_MIN_DOCS` — so every agg here takes the brute full-corpus path the
/// guard protects.
const DOCS: usize = 900;

fn low_budget_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config.limits.max_query_memory_mb = BUDGET_MB;
    Engine::new(config).expect("engine::new installs the governor from config")
}

#[tokio::test]
async fn aggregation_corpus_is_bound_by_max_query_memory_mb() {
    let dir = TempDir::new().unwrap();
    let engine = low_budget_engine(&dir);
    engine.create_index("aggmem", Schema::empty()).unwrap();
    let idx = engine.get_index("aggmem").unwrap();

    for i in 0..DOCS {
        idx.index_document(
            Some(format!("d{i:05}")),
            json!({
                "cat": if i % 2 == 0 { "A" } else { "B" },
                "title": format!("doc number {i}"),
                "n": i as i64,
            }),
        )
        .await
        .unwrap();
    }

    // A control search WITHOUT aggs (size:0) must still pass — its window
    // estimate is 0, so this isolates the failure to the aggregation path.
    let control = parse_request(&json!({ "query": { "match_all": {} }, "size": 0 })).unwrap();
    assert!(
        idx.search(&control).await.is_ok(),
        "a plain size:0 search must not be blocked by the query-memory budget (#464)"
    );

    // A `size:0` `top_hits` agg (meta-observing) bails the fast path to the
    // brute full-corpus assembly, which deep-clones all DOCS memtable sources —
    // an estimate that exceeds the 1 MiB budget.
    let top_hits = parse_request(&json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": {
            "by_cat": {
                "terms": { "field": "cat", "size": 10 },
                "aggs": { "top": { "top_hits": { "size": 2, "_source": ["title"] } } }
            }
        }
    }))
    .unwrap();
    assert!(
        idx.search(&top_hits).await.is_err(),
        "a top_hits agg over {DOCS} buffered docs must be rejected by \
         max_query_memory_mb={BUDGET_MB}MB — the full-corpus deep-clone allocates \
         far beyond the budget (#464). Got Ok, so the agg path bypassed the guard."
    );

    // A `percentiles` agg has NO columnar fast path and mentions NO meta field —
    // it bails to the SAME brute full-corpus assembly. It proves the guard binds
    // the whole agg family, not just meta-observing aggs (#464).
    let percentiles = parse_request(&json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": { "p": { "percentiles": { "field": "n" } } }
    }))
    .unwrap();
    assert!(
        idx.search(&percentiles).await.is_err(),
        "a percentiles agg (brute full-corpus deep-clone, no meta fields) must \
         ALSO be bound by max_query_memory_mb — not just meta-observing aggs (#464)"
    );
}

//! The aggregation script tokenisers must be total on any `_search` body.
//!
//! Issue #207. `painless::tokenize` was not the only Painless-subset scanner
//! walking bytes and slicing `&str`. `aggs.rs` holds two more, reached from an
//! ordinary aggregation body and from nowhere else:
//!
//! * `aggs::lex_script`      — `scripted_metric`
//! * `aggs::tokenize_script` — `bucket_script` / `bucket_selector`
//!
//! Both took `&src[i..i + 2]` to test for a two-character operator. Every arm
//! above that point is ASCII-only, so the lead byte of a multi-byte character
//! fell straight through and `i + 2` landed inside it:
//! `end byte index 2 is not a char boundary`. Both also skipped whitespace with
//! `is_whitespace()` on `bytes[i] as char`, which is true for Latin-1 NEL and
//! NBSP — bytes that in valid UTF-8 are only ever *continuation* bytes, so the
//! scanner could step into the middle of a character on its own.
//!
//! The release profile sets `panic = "abort"`, so this was not a 400 on a bad
//! script: it was the process, from an unauthenticated `_search`.

use serde_json::json;
use std::panic;

fn run(label: String, aggs: serde_json::Value, docs: Vec<serde_json::Value>) -> Option<String> {
    let prev = panic::take_hook();
    panic::set_hook(Box::new(|_| {}));
    let out = panic::catch_unwind(move || xerj_engine::aggs::run_aggs(&aggs, &docs));
    panic::set_hook(prev);
    out.err().map(|e| {
        format!(
            "{label}: {}",
            e.downcast_ref::<String>()
                .cloned()
                .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
                .unwrap_or_else(|| "<non-string panic>".into())
        )
    })
}

fn docs() -> Vec<serde_json::Value> {
    vec![
        json!({ "k": "a", "v": 1.0 }),
        json!({ "k": "a", "v": 2.0 }),
        json!({ "k": "b", "v": 3.0 }),
    ]
}

/// Before the fix each of these aborts the test process.
#[test]
fn a_non_ascii_aggregation_script_is_an_error_not_a_panic() {
    let mut bad = Vec::new();

    for src in [
        // Bare multi-byte character: the lead byte reaches the two-char slice.
        "\u{4e2d}",
        // Multi-byte between two operands, and after an operator.
        "1 \u{4e2d} 2",
        "params.x \u{4e2d}",
        "params.x > \u{4e2d}",
        // Four-byte character, so `i + 2` is two bytes short of the end.
        "params.x \u{1f600}",
        // NBSP: `is_whitespace()` on the 0xA0 continuation byte used to
        // advance `i` into the middle of the character.
        "params.x \u{a0}> 1",
        "\u{a0}\u{a0}\u{a0}",
        // NEL (U+0085), the other byte `is_whitespace()` accepted.
        "params.x \u{85}> 1",
        // Multi-byte at the very end, where the two-char probe runs off.
        "1 +\u{e9}",
        "\u{e9}",
    ] {
        for (label, aggs) in [
            (
                "scripted_metric",
                json!({ "m": { "scripted_metric": { "map_script": src } } }),
            ),
            (
                "bucket_script",
                json!({
                    "s": { "sum": { "field": "v" } },
                    "bs": { "bucket_script": { "buckets_path": { "x": "s" }, "script": src } },
                }),
            ),
            (
                "bucket_selector",
                json!({ "by": {
                    "terms": { "field": "k" },
                    "aggs": {
                        "s": { "sum": { "field": "v" } },
                        "sel": { "bucket_selector": {
                            "buckets_path": { "x": "s" }, "script": src } },
                    },
                }}),
            ),
        ] {
            if let Some(msg) = run(format!("{label} script={src:?}"), aggs, docs()) {
                bad.push(msg);
            }
        }
    }

    assert!(
        bad.is_empty(),
        "aggregation scripts that panic run_aggs. `panic = \"abort\"` is set in \
         the release profile, so each of these is process death from a _search \
         body:\n  {}",
        bad.join("\n  ")
    );
}

/// The narrowed scan must not have narrowed the language: ASCII scripts,
/// including the two-character operators the guard now gates, still evaluate.
#[test]
fn ascii_aggregation_scripts_still_evaluate() {
    // bucket_script over a sibling sum, using a two-character operator path
    // (`>=` is tokenised by the same guarded branch).
    let out = xerj_engine::aggs::run_aggs(
        &json!({
            "s": { "sum": { "field": "v" } },
            "bs": { "bucket_script": {
                "buckets_path": { "x": "s" },
                "script": "params.x >= 6 ? params.x * 2 : params.x",
            }},
        }),
        &docs(),
    );
    assert_eq!(
        out["bs"]["value"].as_f64(),
        Some(12.0),
        "bucket_script over sum(v)=6 with `>=` and a ternary: {out}"
    );

    // bucket_selector keeps the bucket whose sum passes the predicate and
    // drops the other one.
    let out = xerj_engine::aggs::run_aggs(
        &json!({ "by": {
            "terms": { "field": "k" },
            "aggs": {
                "s": { "sum": { "field": "v" } },
                "sel": { "bucket_selector": {
                    "buckets_path": { "x": "s" },
                    "script": "params.x >= 3 && params.x != 99",
                }},
            },
        }}),
        &docs(),
    );
    let buckets = out["by"]["buckets"].as_array().expect("buckets");
    assert_eq!(buckets.len(), 2, "both buckets sum to >= 3: {out}");

    let out = xerj_engine::aggs::run_aggs(
        &json!({ "by": {
            "terms": { "field": "k" },
            "aggs": {
                "s": { "sum": { "field": "v" } },
                "sel": { "bucket_selector": {
                    "buckets_path": { "x": "s" },
                    "script": "params.x > 3",
                }},
            },
        }}),
        &docs(),
    );
    let buckets = out["by"]["buckets"].as_array().expect("buckets");
    assert_eq!(buckets.len(), 0, "neither bucket sums above 3: {out}");
}

//! #1745: `filter` / `filters` aggregations must count exactly what the same
//! clause counts as a query.
//!
//! Those aggs evaluate their clause per document through `doc_matches_filter`,
//! a separate matcher over `_source` that had no mapping or analyzer: `match`
//! was a lowercase `contains` per word (so `dog` matched "dogs"), a multi-word
//! `match` required EVERY word (ES defaults to OR), and `match_phrase` never
//! checked adjacency. The same five clauses counted as
//! `m=3, t=0, or=0, phr=1` in an agg while `_count` answered
//! `2, 0, 2, 0` (and ES 8.13 answers `2, 2, 2, 0`).
//!
//! The aggregation now runs with the index schema in scope, so
//! `run_filter`/`run_filters` evaluate the parsed clause with
//! `doc_matches_query_typed` — the matcher `_search`/`_count` use. This test
//! pins parity clause-by-clause (the issue's actual invariant) plus the
//! ES-pinned counts for the clauses where XERJ's query path already matches
//! ES.
//!
//! `term` on a `text` field is deliberately asserted for PARITY only:
//! XERJ's query path answers it by whole value (0 here) — a pre-existing
//! contract this PR does not change — so the agg must join it rather than
//! keep a second opinion. ES answers 2 by matching the analyzed token; that
//! difference belongs to the query path, not to this aggregation fix.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn books_schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("title", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("kw", FieldType::Keyword));
    schema
}

/// The issue's three documents, plus a keyword column so the exact-field
/// control surface is covered too.
async fn seed(engine: &Engine) -> std::sync::Arc<Index> {
    engine.create_index("books", books_schema()).unwrap();
    let idx = engine.get_index("books").unwrap();
    for (id, title, kw) in [
        ("1", "lazy dog sleeps", "alpha"),
        ("2", "Quick dogs run", "beta"),
        ("3", "the fox and the dog", "alpha"),
    ] {
        idx.index_document(Some(id.into()), json!({"title": title, "kw": kw}))
            .await
            .unwrap();
    }
    idx.refresh().await.unwrap();
    idx
}

async fn count(idx: &Index, clause: &Value) -> u64 {
    let req = parse_request(&json!({ "query": clause, "size": 0 })).expect("parse_request");
    idx.search(&req).await.unwrap().total.value
}

async fn run_aggs(idx: &Index, aggs: Value) -> Value {
    let req = parse_request(&json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": aggs,
    }))
    .expect("parse_request");
    idx.search(&req)
        .await
        .unwrap()
        .aggs
        .expect("aggs in the response")
}

/// The issue's clauses, plus exact-field controls.
fn clauses() -> Vec<(&'static str, Value)> {
    vec![
        ("match_dog", json!({"match": {"title": "dog"}})),
        ("term_dog", json!({"term": {"title": "dog"}})),
        ("match_or", json!({"match": {"title": "quick fox"}})),
        (
            "phrase_adjacent",
            json!({"match_phrase": {"title": "fox and"}}),
        ),
        ("phrase_gap", json!({"match_phrase": {"title": "fox dog"}})),
        ("term_kw", json!({"term": {"kw": "alpha"}})),
        (
            "bool_kw",
            json!({"bool": {"should": [{"term": {"kw": "beta"}}], "minimum_should_match": 1}}),
        ),
    ]
}

#[tokio::test]
async fn filter_and_filters_aggs_count_what_the_same_clause_counts_as_a_query() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine).await;

    for (name, clause) in clauses() {
        let expected = count(&idx, &clause).await;
        let body = run_aggs(
            &idx,
            json!({
                "one": { "filter": clause },
                "multi": { "filters": { "filters": { name: clause } } },
            }),
        )
        .await;
        assert_eq!(
            body["one"]["doc_count"].as_u64(),
            Some(expected),
            "filter agg `{name}` must equal _count({clause}): {body}"
        );
        assert_eq!(
            body["multi"]["buckets"][name]["doc_count"].as_u64(),
            Some(expected),
            "filters agg `{name}` must equal _count({clause}): {body}"
        );
    }

    // ES-pinned counts for the clauses the query path itself already answers
    // like ES 8.13 (`_count` was 2 / 2 / 0 before this change; only the agg
    // disagreed).
    let body = run_aggs(
        &idx,
        json!({
            "m":   { "filter": { "match": { "title": "dog" } } },
            "t":   { "filter": { "term": { "title": "dog" } } },
            "or":  { "filter": { "match": { "title": "quick fox" } } },
            "phr": { "filter": { "match_phrase": { "title": "fox dog" } } },
            "ok":  { "filter": { "match_phrase": { "title": "fox and" } } },
        }),
    )
    .await;
    assert_eq!(body["m"]["doc_count"], json!(2), "match(dog) != ES: {body}");
    assert_eq!(
        body["or"]["doc_count"],
        json!(2),
        "match(quick fox) != ES: {body}"
    );
    assert_eq!(
        body["phr"]["doc_count"],
        json!(0),
        "match_phrase(fox dog) != ES: {body}"
    );
    assert_eq!(
        body["ok"]["doc_count"],
        json!(1),
        "match_phrase(fox and) != ES: {body}"
    );
    // Whole-value `term` on text: the query path's answer, not ES's (see the
    // module comment). The point is that the agg no longer has its own answer.
    assert_eq!(
        body["t"]["doc_count"],
        json!(0),
        "term(dog) must match _count: {body}"
    );
}

/// The schema scope must survive the bucket boundary: a `filter` nested under
/// a `terms` bucket runs through `run_aggs_in_bucket`.
#[tokio::test]
async fn filter_aggs_inside_bucket_subaggs_use_the_same_matcher() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine).await;

    let body = run_aggs(
        &idx,
        json!({
            "by_kw": {
                "terms": { "field": "kw" },
                "aggs": {
                    "dog": { "filter": { "match": { "title": "dog" } } },
                    "fox": { "filter": { "match": { "title": "quick fox" } } },
                }
            }
        }),
    )
    .await;

    let mut by_key = std::collections::HashMap::new();
    for b in body["by_kw"]["buckets"].as_array().expect("buckets") {
        by_key.insert(b["key"].as_str().unwrap().to_string(), b.clone());
    }

    // alpha: docs 1 ("lazy dog sleeps") and 3 ("the fox and the dog").
    // beta:  doc 2 ("Quick dogs run") — token `dogs`, not `dog`.
    assert_eq!(by_key["alpha"]["dog"]["doc_count"], json!(2));
    assert_eq!(by_key["alpha"]["fox"]["doc_count"], json!(1));
    assert_eq!(by_key["beta"]["dog"]["doc_count"], json!(0));
    assert_eq!(by_key["beta"]["fox"]["doc_count"], json!(1));
}

//! Range bucket aggregations must look at every value of a multi-valued
//! field, not just the first one.
//!
//! Found while verifying #1750 (`range` query on arrays): the query side is
//! fixed separately (PR #1776), but the three range **aggregation** types had
//! the same blind spot on the aggregation path:
//!
//! * `range` read `extract_numeric(doc, field)` — the first numeric element —
//!   so `[7, 8080]` counted in `[.., 10)` and vanished from `[8000, 9000)`;
//! * `date_range` handed the whole array to the per-value date parser, which
//!   returned `None` for an array, so every array-valued date document was
//!   missed entirely;
//! * `ip_range` read `Value::as_str()`, which is `None` for an array, so every
//!   array-valued address was missed.
//!
//! ES buckets a document into every range that ANY of its values falls into,
//! and counts it once per bucket (a document is one document). That is the
//! contract asserted here; the `[5, 7]` document pins the once-per-bucket
//! half.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn events_schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("ports", FieldType::Long));
    schema
        .fields
        .push(FieldConfig::new("seen", FieldType::Date));
    schema.fields.push(FieldConfig::new("ipf", FieldType::Ip));
    schema
}

async fn seed(engine: &Engine) -> std::sync::Arc<xerj_engine::Index> {
    engine.create_index("events", events_schema()).unwrap();
    let idx = engine.get_index("events").unwrap();
    for (id, doc) in [
        (
            "1",
            json!({
                "ports": [7, 8080],
                "seen": ["2019-01-01", "2022-06-01"],
                "ipf": ["192.168.0.1", "10.0.0.3"],
            }),
        ),
        (
            "2",
            json!({
                "ports": 443,
                "seen": "2024-01-01",
                "ipf": "172.16.0.1",
            }),
        ),
        (
            "3",
            json!({
                "ports": [5, 7],
                "seen": ["2021-06-01", "2030-01-01"],
                "ipf": ["10.0.0.9", "10.0.0.4"],
            }),
        ),
        // No value for any of the three fields: exercises `missing`.
        ("4", json!({"note": "no values"})),
    ] {
        idx.index_document(Some(id.into()), doc).await.unwrap();
    }
    idx.refresh().await.unwrap();
    idx
}

async fn aggs(idx: &xerj_engine::Index, aggs: Value) -> Value {
    let req = parse_request(&json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": aggs,
    }))
    .expect("parse_request");
    idx.search(&req)
        .await
        .unwrap()
        .aggs
        .expect("aggs in the response")
}

fn counts(bucket: &Value) -> Vec<u64> {
    bucket["buckets"]
        .as_array()
        .unwrap_or_else(|| panic!("expected buckets, got {bucket}"))
        .iter()
        .map(|b| {
            b["doc_count"]
                .as_u64()
                .unwrap_or_else(|| panic!("no doc_count: {b}"))
        })
        .collect()
}

#[tokio::test]
async fn range_aggregations_bucket_every_value_of_a_multi_valued_field() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine).await;

    let body = aggs(
        &idx,
        json!({
            "ports": {
                "range": {
                    "field": "ports",
                    "ranges": [
                        { "from": 8000, "to": 9000 },
                        { "to": 10 },
                        { "from": 8000 }
                    ]
                }
            },
            "dates": {
                "date_range": {
                    "field": "seen",
                    "ranges": [{ "from": "2021-01-01", "to": "2023-01-01" }]
                }
            },
            "dates_via_range": {
                "range": {
                    "field": "seen",
                    "ranges": [{ "from": "2021-01-01", "to": "2023-01-01" }]
                }
            },
            "ips": {
                "ip_range": {
                    "field": "ipf",
                    "ranges": [{ "from": "10.0.0.1", "to": "10.0.0.5" }]
                }
            },
            "ips_mask": {
                "ip_range": {
                    "field": "ipf",
                    "ranges": [{ "mask": "10.0.0.0/24" }]
                }
            },
            "ports_missing": {
                "range": {
                    "field": "ports",
                    "missing": 6,
                    "ranges": [{ "to": 10 }]
                }
            }
        }),
    )
    .await;

    // d1's 8080 is its SECOND value; d3's 9000 is excluded by `to`.
    assert_eq!(
        counts(&body["ports"]),
        vec![1, 2, 1],
        "ports range must bucket every value: {body}"
    );
    // d1's 2022-06-01 and d3's 2021-06-01 are both second values.
    assert_eq!(counts(&body["dates"]), vec![2], "date_range: {body}");
    // Same data through `range` (string bounds select its date branch).
    assert_eq!(
        counts(&body["dates_via_range"]),
        vec![2],
        "range on dates: {body}"
    );
    // d1's 10.0.0.3 and d3's 10.0.0.4.
    assert_eq!(counts(&body["ips"]), vec![2], "ip_range: {body}");
    assert_eq!(counts(&body["ips_mask"]), vec![2], "ip_range mask: {body}");
    // `missing` applies only to d4 (no value at all), never to a doc whose
    // array merely has no element in range.
    assert_eq!(
        counts(&body["ports_missing"]),
        vec![3],
        "missing applies once, only to docs without a value: {body}"
    );
}

/// The same three aggregations must agree before and after a flush: the
/// aggregation path reads `_source` on both sides, so a value-drop here is a
/// data bug, not a timing one.
#[tokio::test]
async fn range_aggregations_are_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine).await;
    let aggs_def = json!({
        "ports": { "range": { "field": "ports", "ranges": [{ "from": 8000, "to": 9000 }] } },
        "dates": { "date_range": { "field": "seen", "ranges": [{ "from": "2021-01-01", "to": "2023-01-01" }] } },
        "ips": { "ip_range": { "field": "ipf", "ranges": [{ "from": "10.0.0.1", "to": "10.0.0.5" }] } }
    });
    let before = aggs(&idx, aggs_def.clone()).await;
    idx.flush().await.unwrap();
    let after = aggs(&idx, aggs_def).await;
    assert_eq!(before, after, "range aggs must not change at a flush");
}

//! xerj Battle Test — comprehensive real-world benchmark suite.
//!
//! Loads four realistic datasets (web logs, products, error logs, articles)
//! and runs representative search, aggregation, and ingest scenarios.
//! Each scenario measures p50/p95/p99 latency and reports a formatted table.
//!
//! All tests are `#[ignore]` so they don't run in ordinary `cargo test`.
//!
//! # Quick start
//!
//! ```bash
//! # Generate datasets first (one-time, ~36 K docs)
//! bash tests/datasets/generate_datasets.sh
//!
//! # Run the full battle test suite
//! cargo test -p xerj-engine --test battle_test -- --ignored --nocapture
//!
//! # Run a single scenario
//! cargo test -p xerj-engine --test battle_test battle_log_error_search -- --ignored --nocapture
//! ```
//!
//! # Dataset paths
//!
//! The tests look for NDJSON files under `<workspace_root>/tests/datasets/`.
//! Run `bash tests/datasets/generate_datasets.sh` from the workspace root to
//! create them, or set the `XERJ_DATASET_DIR` environment variable to point
//! to an existing directory of NDJSON files.

use serde_json::{json, Value};
use std::path::PathBuf;
use std::time::{Duration, Instant};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::bulk::process_bulk;
use xerj_engine::Engine;
use xerj_query::parse_request;

// ─────────────────────────────────────────────────────────────────────────────
// Infrastructure helpers
// ─────────────────────────────────────────────────────────────────────────────

/// Build a battle-grade engine: very large flush thresholds so the entire
/// dataset stays in the memtable (no segment merges mid-benchmark).
fn battle_engine() -> (Engine, TempDir) {
    let dir = TempDir::new().expect("tempdir");
    let mut cfg = Config::default();
    cfg.server.data_dir = dir.path().to_str().unwrap().to_string();
    cfg.storage.flush_size_mb = 8192;
    cfg.storage.flush_interval_secs = 86400;
    let engine = Engine::new(cfg).expect("engine::new");
    (engine, dir)
}

/// Locate the datasets directory.
///
/// Priority:
///   1. `XERJ_DATASET_DIR` environment variable
///   2. `<workspace_root>/tests/datasets/` — detected by walking up from
///      `CARGO_MANIFEST_DIR` (`crates/xerj-engine`) until we find the
///      directory containing `Cargo.lock` (workspace root).
fn dataset_dir() -> PathBuf {
    if let Ok(val) = std::env::var("XERJ_DATASET_DIR") {
        return PathBuf::from(val);
    }
    // CARGO_MANIFEST_DIR points to crates/xerj-engine.
    // Walk up until we hit the workspace root (has Cargo.lock).
    let manifest = std::env::var("CARGO_MANIFEST_DIR").unwrap_or_else(|_| ".".into());
    let mut dir = PathBuf::from(manifest);
    loop {
        if dir.join("Cargo.lock").exists() {
            return dir.join("tests").join("datasets");
        }
        match dir.parent() {
            Some(p) => dir = p.to_path_buf(),
            None => break,
        }
    }
    // Fallback: relative to crate root (works if run from workspace root)
    PathBuf::from("tests").join("datasets")
}

/// Load an NDJSON file from the dataset dir.  Returns an error string if the
/// file does not exist (we'll skip gracefully rather than panic).
fn load_ndjson(filename: &str) -> Result<Vec<Value>, String> {
    let path = dataset_dir().join(filename);
    if !path.exists() {
        return Err(format!(
            "Dataset not found: {}\nRun `bash tests/datasets/generate_datasets.sh` first.",
            path.display()
        ));
    }
    let content = std::fs::read_to_string(&path)
        .map_err(|e| format!("Failed to read {}: {}", path.display(), e))?;
    let mut docs = Vec::new();
    for (lineno, line) in content.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let val: Value = serde_json::from_str(trimmed).map_err(|e| {
            format!(
                "JSON parse error in {} line {}: {}",
                filename,
                lineno + 1,
                e
            )
        })?;
        docs.push(val);
    }
    Ok(docs)
}

/// Bulk-index a slice of documents into `index_name`.
///
/// Returns (total_docs_indexed, elapsed).
async fn bulk_index(engine: &Engine, index_name: &str, docs: &[Value]) -> (usize, Duration) {
    const BATCH: usize = 500;
    let mut total = 0usize;
    let start = Instant::now();

    for chunk in docs.chunks(BATCH) {
        let mut ndjson = String::with_capacity(chunk.len() * 300);
        for (j, doc) in chunk.iter().enumerate() {
            let id = doc
                .get("id")
                .and_then(|v| v.as_u64())
                .map(|n| n.to_string())
                .unwrap_or_else(|| format!("{}", total + j));
            ndjson.push_str(&format!(
                "{{\"index\":{{\"_index\":\"{}\",\"_id\":\"{}\"}}}}\n",
                index_name, id
            ));
            ndjson.push_str(&serde_json::to_string(doc).unwrap());
            ndjson.push('\n');
        }
        let result = process_bulk(engine, Some(index_name), &ndjson).await;
        assert!(!result.errors, "bulk had errors in index '{}'", index_name);
        total += result.items.len();
    }

    (total, start.elapsed())
}

/// Compute percentiles from a sorted Vec<Duration>.
fn percentiles(sorted: &[Duration], ps: &[u32]) -> Vec<Duration> {
    ps.iter()
        .map(|&p| {
            if sorted.is_empty() {
                Duration::ZERO
            } else {
                let idx = ((p as usize) * sorted.len()).saturating_sub(1) / 100;
                sorted[idx.min(sorted.len() - 1)]
            }
        })
        .collect()
}

/// Run a single search query `n` times (after one warm-up) and return sorted latencies.
macro_rules! measure_search {
    ($idx:expr, $req:expr, $n:expr) => {{
        // warm-up
        let _ = $idx.search(&$req).await.unwrap();
        let mut lats: Vec<Duration> = Vec::with_capacity($n);
        for _ in 0..$n {
            let t0 = Instant::now();
            let _ = $idx.search(&$req).await.unwrap();
            lats.push(t0.elapsed());
        }
        lats.sort();
        lats
    }};
}

// ─────────────────────────────────────────────────────────────────────────────
// Report formatting
// ─────────────────────────────────────────────────────────────────────────────

fn banner(title: &str) {
    println!("\n{}", "═".repeat(70));
    println!("  {}", title);
    println!("{}", "═".repeat(70));
}

fn row(label: &str, value: &str) {
    println!("  {:<38} {}", label, value);
}

fn separator() {
    println!("  {}", "─".repeat(68));
}

fn lat_rows(label: &str, lats: &[Duration]) {
    if lats.is_empty() {
        row(label, "no data");
        return;
    }
    let ps = percentiles(lats, &[50, 95, 99]);
    let avg = lats.iter().sum::<Duration>() / lats.len() as u32;
    row(&format!("{} (avg)", label), &format!("{:.2?}", avg));
    row(&format!("{} p50", label), &format!("{:.2?}", ps[0]));
    row(&format!("{} p95", label), &format!("{:.2?}", ps[1]));
    row(&format!("{} p99", label), &format!("{:.2?}", ps[2]));
    row(
        &format!("{} min/max", label),
        &format!("{:.2?} / {:.2?}", lats[0], lats[lats.len() - 1]),
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Scenario 1 — Bulk ingest all 36 K documents
// ─────────────────────────────────────────────────────────────────────────────

/// Measures: total time and per-doc latency for ingesting all four datasets.
#[tokio::test]
#[ignore]
async fn battle_bulk_ingest_all() {
    banner("BATTLE: Bulk Ingest — all four datasets (~36 K docs)");

    // Load datasets
    let access_docs = match load_ndjson("access_logs.ndjson") {
        Ok(d) => d,
        Err(e) => {
            println!("SKIP: {}", e);
            return;
        }
    };
    let product_docs = match load_ndjson("products.ndjson") {
        Ok(d) => d,
        Err(e) => {
            println!("SKIP: {}", e);
            return;
