#[tokio::test]
#[ignore]
async fn battle_correctness_spot_checks() {
    banner("BATTLE: Correctness Spot Checks — all four datasets");

    let access_docs = match load_ndjson("access_logs.ndjson") {
        Ok(d) => d,
        Err(e) => {
            println!("SKIP: {}", e);
            return;
        }
    };
