        "combined score {combined_score} did not add text {text_score} + keyword {keyword_score}"
    );
}

//! #399 — a one-clause `bool` is a no-op: it must not change `_score` or rank.
//!
//! `{"bool":{"must":[X]}}` and bare `X` are the same query.  On an UNFLUSHED
//! index they were not: `Index::search` steers on the *shape* of the tree, and
//! a `Bool` node is matched by `is_doc_scan_query`, so the memtable arm scored
//! it with the IDF-less brute scorer (`score_query_against_doc`, `1 + ln(1 +
//! tf)`) while the identical bare `Match` took the memtable BM25 arm
//! (`extract_query_text` → `search_text_boosted_with_total_using`, index-wide
//! stats).  Same 120 documents, same clause, ~400× apart and in a different
//! order.
//!
//! #361/#387 fixed the *flushed* half of this family (`bool.filter` summing
//! into `_score`, and the page-local IDF rescore overwriting exact BM25); the
//! flushed assertions below are the regression guard for that.  The memtable
//! half is what #399 reports and what the fix normalises away.
//!
//! Reference (apache/lucene, Apache-2.0, adapted not copied):
//!   * `BooleanQuery.rewrite` — "optimize 1-clause queries": with
//!     `minimumNumberShouldMatch == 0` a lone `SHOULD` or `MUST` clause
//!     rewrites to the clause's own query, and with
//!     `minimumNumberShouldMatch == 1` a lone `SHOULD` does too
//!     (BooleanQuery.java:279-298).  The wrapper is erased before a `Weight`
//!     is ever built, so it cannot contribute a score.
//!   * A lone `FILTER` clause instead rewrites to
//!     `new BoostQuery(new ConstantScoreQuery(query), 0)` — score 0, NOT the
//!     clause's score (BooleanQuery.java:290-292); `filter_only_bool_*` below
//!     pins that asymmetry.

use std::collections::HashMap;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::executor::SearchResult;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(query: Value, size: usize) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({"query": query, "size": size, "track_total_hits": true}))
        .expect("parse_request")
}

/// The issue's corpus: 120 docs, one `text` field, one `keyword` field.
///
/// `alpha` is in every document with tf 1..=5, so exact BM25 gives it a tiny
/// IDF (`ln(1 + 0.5/120.5)`) and the brute scorer gives `1 + ln(1 + tf)` —
/// two scales that cannot be confused for each other.
async fn seed(name: &str, flush: bool) -> (TempDir, std::sync::Arc<Index>) {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("repo", FieldType::Keyword));
    engine.create_index(name, schema).unwrap();
    let idx = engine.get_index(name).unwrap();

    for i in 0..120usize {
        let alphas = "alpha ".repeat(1 + i % 5);
        let betas = if i < 60 {
            "beta ".repeat(1 + i % 3)
        } else {
            String::new()
        };
        let filler = "gamma ".repeat(1 + i % 7);
        idx.index_document(
            Some(format!("d{i:03}")),
            json!({
                "body": format!("{alphas}{betas}{filler}"),
                "repo": if i % 2 == 0 { "lucene" } else { "usearch" },
            }),
        )
        .await
        .unwrap();
    }
    if flush {
        idx.flush().await.unwrap();
    }

    // The two populations are the whole point of the test — assert which one
    // this fixture actually exercises rather than trusting the flush call.
    let stats = idx.stats().await;
    if flush {
        assert_eq!(
            stats.memtable_doc_count, 0,
            "{name}: flush did not drain the memtable"
        );
    } else {
        assert_eq!(
            stats.memtable_doc_count, 120,
            "{name}: fixture must stay memtable-resident"
        );
    }
    (dir, idx)
}

fn score_map(result: &SearchResult) -> HashMap<String, f32> {
    result
        .hits
        .iter()
        .map(|h| (h.id.clone(), h.score))
        .collect()
}

fn ids(result: &SearchResult) -> Vec<String> {
    result.hits.iter().map(|h| h.id.clone()).collect()
}

/// Every hit's `_score` must equal the bare clause's score for the same
/// `_id`, and the order must be identical.
fn assert_same_ranking(label: &str, reference: &SearchResult, actual: &SearchResult) {
    assert!(
        !actual.hits.is_empty(),
        "{label}: returned no hits — the comparison would be vacuous"
    );
    assert_eq!(
        reference.total.value, actual.total.value,
        "{label}: matched a different number of documents"
    );
    let reference_scores = score_map(reference);
    for hit in &actual.hits {
        let expected = reference_scores
            .get(&hit.id)
            .unwrap_or_else(|| panic!("{label}: {} is not in the bare-clause result", hit.id));
        assert!(
            (hit.score - expected).abs() < 1e-4,
            "{label}: _score for {} is {} but the bare clause scores it {expected}",
            hit.id,
            hit.score
        );
    }
    assert_eq!(
        ids(actual),
        ids(reference),
        "{label}: hit order diverged from the bare clause"
    );
}

const TEXT: &str = "alpha";

fn text_query() -> Value {
    json!({"match": {"body": TEXT}})
}

/// The four wrappers Lucene's 1-clause rewrite erases, each of which must
/// leave `_score` and rank byte-for-byte where the bare clause put them.
fn neutral_wrappers() -> Vec<(&'static str, Value)> {
    vec![
        ("bool.must[1]", json!({"bool": {"must": [text_query()]}})),
        (
            "bool.should[1]",
            json!({"bool": {"should": [text_query()]}}),
        ),
        (
            // `minimum_should_match: 1` on a lone should is the same query —
            // BooleanQuery.java:283-284.
            "bool.should[1]+msm1",
            json!({"bool": {"should": [text_query()], "minimum_should_match": 1}}),
        ),
        (
            // Nested wrappers collapse all the way down.
            "bool.must[bool.must[1]]",
            json!({"bool": {"must": [{"bool": {"must": [text_query()]}}]}}),
        ),
        (
            // #643: a lone `should` with a PERCENTAGE msm resolves to 1 for a
            // single optional clause (coerced to ≥1 when there is no required
            // clause), so it is the same query and must now collapse like
            // Fixed(0)/Fixed(1).
            "bool.should[1]+pct100",
            json!({"bool": {"should": [text_query()], "minimum_should_match": "100%"}}),
        ),
        (
            "bool.should[1]+pct50",
            json!({"bool": {"should": [text_query()], "minimum_should_match": "50%"}}),
        ),
    ]
}

/// #643 guard: a lone `should` whose `minimum_should_match` is a percentage
/// >= 200% resolves to `max(1, floor(1 * pct/100)) >= 2` — it requires 2 of 1
/// optional clause, which is unsatisfiable, so the bool matches NOTHING. It must
/// stay wrapped, NOT collapse to the bare clause (which matches). Guards the
/// over-broad `Percentage(_)` unwrap the 3-skeptic pass caught.
#[tokio::test]
async fn high_percentage_msm_lone_should_matches_nothing() {
    for flush in [false, true] {
        let (_dir, idx) = seed(&format!("bool-pct-high-{flush}"), flush).await;
        let bare = idx.search(&req(text_query(), 50)).await.unwrap();
        assert_eq!(
            bare.total.value, 120,
            "fixture: the bare clause matches all"
        );
        for pct in ["200%", "300%"] {
            let q = json!({"bool": {"should": [text_query()], "minimum_should_match": pct}});
            let r = idx.search(&req(q, 50)).await.unwrap();
            assert_eq!(
                r.total.value, 0,
                "#643: lone should + msm {pct} requires 2 of 1 clause \u{2192} must match nothing (flush={flush})"
            );
        }
    }
}

/// The headline of #399, on the population that showed it: an UNFLUSHED index.
#[tokio::test]
async fn single_clause_bool_is_score_neutral_on_memtable() {
    let (_dir, idx) = seed("bool-one-clause-memtable", false).await;

    let reference = idx.search(&req(text_query(), 50)).await.unwrap();
    assert_eq!(reference.total.value, 120, "fixture: every doc has `alpha`");
    let distinct: std::collections::HashSet<u32> = reference
        .hits
        .iter()
        .map(|h| (h.score * 1e6) as u32)
        .collect();
    assert!(
        distinct.len() > 1,
        "fixture must produce distinct scores, got {:?}",
        reference.hits.iter().map(|h| h.score).collect::<Vec<_>>()
    );

    for (label, wrapped) in neutral_wrappers() {
        let actual = idx.search(&req(wrapped, 50)).await.unwrap();
        assert_same_ranking(label, &reference, &actual);
    }
}

/// Same assertions on the flushed (segment FTS) population — the half #387
/// fixed.  Guards against a fix for the memtable half re-introducing the
/// divergence here.
#[tokio::test]
async fn single_clause_bool_is_score_neutral_on_segments() {
    let (_dir, idx) = seed("bool-one-clause-segments", true).await;

    let reference = idx.search(&req(text_query(), 50)).await.unwrap();
    assert_eq!(reference.total.value, 120);

    for (label, wrapped) in neutral_wrappers() {
        let actual = idx.search(&req(wrapped, 50)).await.unwrap();
        assert_same_ranking(label, &reference, &actual);
    }
}

/// `_score` must not depend on `size` for either shape, and the two shapes
/// must agree at every page size — the property a client doing RRF/threshold
/// fusion actually relies on.
#[tokio::test]
async fn wrapped_and_bare_agree_at_every_page_size() {
    for flush in [false, true] {
        let (_dir, idx) = seed(&format!("bool-one-clause-size-{flush}"), flush).await;
        for size in [1usize, 10, 50] {
            let bare = idx.search(&req(text_query(), size)).await.unwrap();
            let wrapped = idx
                .search(&req(json!({"bool": {"must": [text_query()]}}), size))
                .await
                .unwrap();
            assert_same_ranking(&format!("flush={flush} size={size}"), &bare, &wrapped);
        }
    }
}

/// The same neutrality for a `term` on a `keyword` field.
///
/// This one is the anti-regression half: three places in the engine ALREADY
/// treat a single-`must` bool as the identity — `scored_fast_plan` wraps a
/// bare scoring leaf "as a single-must bool (Σ over one clause is the
/// identity)", `mem_bool_preds` accepts a bare `Term`/`Range` as its own
/// one-predicate fused walk, and `peel_knn_query` peels `bool{must:[knn]}` to
/// the same `PeeledKnn` as a bare `knn`.  Erasing the wrapper must not push
/// this shape off any of them onto a different scorer; green before and after.
#[tokio::test]
async fn single_clause_bool_is_score_neutral_for_term_on_keyword() {
    for flush in [false, true] {
        let (_dir, idx) = seed(&format!("bool-one-clause-term-{flush}"), flush).await;
        let bare = idx
            .search(&req(json!({"term": {"repo": "lucene"}}), 50))
            .await
            .unwrap();
        assert_eq!(bare.total.value, 60, "flush={flush}");
        let wrapped = idx
            .search(&req(
                json!({"bool": {"must": [{"term": {"repo": "lucene"}}]}}),
                50,
            ))
            .await
            .unwrap();
        assert_same_ranking(&format!("bool.must[term] flush={flush}"), &bare, &wrapped);
    }
}

/// A lone `filter` clause is NOT the neutral case: Lucene rewrites it to
/// `BoostQuery(ConstantScoreQuery(query), 0)` (BooleanQuery.java:290-292), so
/// the score is 0, not the clause's own score.  This is the guard that the
/// unwrap above cannot quietly grow a `filter` arm.
///
/// FLUSHED ONLY, deliberately.  On an unflushed index the same query scores
/// **1.0**, because the memtable's brute scorer falls back to 1.0 for a
/// zero-sum bool — a pre-existing, separately-tracked filter-context defect
/// that #399 does not touch and this change does not alter (see the `if score
/// == 0.0` arm of `score_query_against_doc`'s `Bool` case in
/// `xerj-engine/src/index.rs`, whose own comment scopes it out).  Asserting
/// 1.0 here would pin a wrong number as correct, so the case is stated and
/// left to its own fix instead.
#[tokio::test]
async fn filter_only_bool_still_scores_zero_when_flushed() {
    let (_dir, idx) = seed("bool-one-clause-filter", true).await;
    let result = idx
        .search(&req(
            json!({"bool": {"filter": [{"term": {"repo": "lucene"}}]}}),
            50,
        ))
        .await
        .unwrap();
    assert_eq!(result.total.value, 60);
    assert_eq!(result.hits.len(), 50);
    for hit in &result.hits {
        assert_eq!(
            hit.score, 0.0,
            "{} scored {} on a filter-only bool",
            hit.id, hit.score
        );
    }
}

/// A lone `must_not` is a pure-negative bool — it has no positive clause, so
/// it must not be unwrapped into its (negated) child.  Green before the fix;
/// it must stay green.  (`clauses.size() == clauseSets.get(MUST_NOT).size()`
/// → `MatchNoDocsQuery("pure negative BooleanQuery")`, BooleanQuery.java:274-277
/// — Lucene returns no matches; XERJ answers it as an exclusion over all docs,
/// which is the pre-existing behaviour this test pins, not a claim about ES.)
#[tokio::test]
async fn must_not_only_bool_is_not_unwrapped() {
    let (_dir, idx) = seed("bool-one-clause-must-not", false).await;
    let result = idx
        .search(&req(
            json!({"bool": {"must_not": [{"term": {"repo": "lucene"}}]}}),
            50,
        ))
        .await
        .unwrap();
    for hit in &result.hits {
        assert_eq!(
            hit.source.get("repo").and_then(Value::as_str),
            Some("usearch"),
            "{} survived a must_not on repo:lucene",
            hit.id
        );
    }
}

/// #643 remaining gap: before the fix, a single-clause `bool` nested inside a
/// score-preserving wrapper that `unwrap_single_clause_bool` does NOT recurse
/// through (`function_score` inner query, `dis_max` single query) stayed
/// wrapped, so the unwrap did not match Lucene's recursive rewrite for those
/// wrappers. A no-functions `function_score` and a single-query `dis_max`
/// (tie_breaker 0) are both score-neutral, so each must rank exactly like the
/// bare clause on BOTH populations — and empirically they ALREADY do, with or
/// without the fix (the #399 divergence does not manifest for these nested
/// shapes; the wrappers force the doc-scan path regardless). So this is a
/// neutrality REGRESSION GUARD, not a fail-before: the fix's real fail-before is
/// the unit tests `unwrap_recurses_through_*`, which assert the nested `bool` is
/// erased to the bare clause.
#[tokio::test]
async fn nested_single_clause_bool_in_wrappers_is_score_neutral() {
    let shapes = [
        (
            "function_score[bool.must[1]]",
            json!({"function_score": {"query": {"bool": {"must": [text_query()]}}}}),
        ),
        (
            "dis_max[bool.must[1]]",
            json!({"dis_max": {"queries": [{"bool": {"must": [text_query()]}}], "tie_breaker": 0.0}}),
        ),
    ];
    for flush in [false, true] {
        let (_dir, idx) = seed(&format!("bool-643-nested-{flush}"), flush).await;
        // Reference: the SAME wrapper around the BARE clause (isolates the inner
        // bool-unwrap effect from any wrapper scoring).
        for (label, wrapped) in &shapes {
            let bare_wrapped = match label {
                l if l.starts_with("function_score") => {
                    json!({"function_score": {"query": text_query()}})
                }
                _ => json!({"dis_max": {"queries": [text_query()], "tie_breaker": 0.0}}),
            };
            let reference = idx.search(&req(bare_wrapped, 50)).await.unwrap();
            let actual = idx.search(&req(wrapped.clone(), 50)).await.unwrap();
            assert_same_ranking(&format!("{label} flush={flush}"), &reference, &actual);
        }
    }
}

//! Issue #954: `_bulk` truncated an action-line `_id` at an escaped quote.
//!
//! The fast path that extracts `_id`/`_index`/`op_type` from an action line
//! scanned for the next raw `"` without unescaping, so `{"_id":"a\"b"}` parsed
//! as id `a\` and the line's remainder desynced — two documents with distinct
//! ids collapsed onto one, and the second write either overwrote the first or
//! 409'd as a duplicate create. The fix bails out of the fast path whenever
//! the action object contains a backslash (any escape) and lets the serde_json
//! fallback parse the line correctly.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::bulk::process_bulk;
use xerj_engine::Engine;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn seed(engine: &Engine, name: &str) {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index(name, schema).expect("create index");
}

/// Distinct ids that differ only inside an escaped segment must stay distinct:
/// all items index (no duplicate-create 409), and a GET-by-id finds each body
/// under its own id. FAIL-BEFORE: the fast path truncates both quote-escaped
/// ids to `a\`, so the two collapse and one body shadows the other; the
/// `\uXXXX` id is stored as its literal 6 escape characters (backslash
/// u 0 0 e 9) instead of the character it names.
#[tokio::test]
async fn escaped_quote_ids_stay_distinct() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "t");

    // Raw NDJSON. JSON-unescaped, the three ids are `a"b`, `a"c` and `é`
    // (the last via a \uXXXX escape, which the fast path used to store
    // literally).
    let body = concat!(
        r#"{"index":{"_index":"t","_id":"a\"b"}}"#,
        "\n",
        r#"{"body":"first"}"#,
        "\n",
        r#"{"index":{"_index":"t","_id":"a\"c"}}"#,
        "\n",
        r#"{"body":"second"}"#,
        "\n",
        r#"{"index":{"_index":"t","_id":"\u00e9"}}"#,
        "\n",
        r#"{"body":"third"}"#,
        "\n",
    );
    let result = process_bulk(&engine, None, body).await;
    assert!(!result.errors, "bulk must not error: {:?}", result.items);
    assert_eq!(result.items.len(), 3);
    // The response must echo the FULL unescaped id, never the truncation.
    assert_eq!(result.items[0].id, "a\"b");
    assert_eq!(result.items[1].id, "a\"c");
    assert_eq!(result.items[2].id, "é");

    let idx = engine.get_index("t").expect("get index");
    // Rust-side: "a\"b" is a"b and "a\"c" is a"c — the JSON-unescaped ids.
    for (id, body_text) in [("a\"b", "first"), ("a\"c", "second"), ("é", "third")] {
        let doc = idx
            .get_document(id)
            .await
            .expect("lookup")
            .unwrap_or_else(|| panic!("document {id:?} must exist"));
        assert_eq!(
            doc.get("body").and_then(|b| b.as_str()),
            Some(body_text),
            "id {id:?} must hold its own body"
        );
    }
}

/// The escape opt-out must not change behaviour for ids WITHOUT escapes
/// (the fast path stays exact for the canonical case), and an invalid escape
/// sequence must surface as a per-item 400, never as a silent truncation.
#[tokio::test]
async fn plain_ids_unchanged_and_bad_escape_is_a_per_item_error() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "t");

    let body = concat!(
        r#"{"index":{"_index":"t","_id":"plain"}}"#,
        "\n",
        r#"{"body":"ok"}"#,
        "\n",
    );
    let result = process_bulk(&engine, None, body).await;
    assert!(
        !result.errors,
        "plain ids must keep working: {:?}",
        result.items
    );
    let idx = engine.get_index("t").expect("get index");
    assert!(idx.get_document("plain").await.expect("lookup").is_some());

    // `\x` is not a valid JSON escape: the serde fallback must reject the
    // action line as a 400 item with the parse error, not truncate `_id`.
    let body = concat!(
        r#"{"index":{"_index":"t","_id":"bad\x22id"}}"#,
        "\n",
        r#"{"body":"never"}"#,
        "\n",
    );
    let result = process_bulk(&engine, None, body).await;
    assert_eq!(result.items.len(), 1, "one action, one item");
    assert_eq!(result.items[0].status, 400, "invalid escape must 400");
    assert!(result.items[0].error.is_some());
    let all = idx
        .search(
            &xerj_query::parse_request(&json!({
                "query": { "match": { "body": "never" } }, "size": 10
            }))
            .expect("parse"),
        )
        .await
        .expect("search");
    assert_eq!(all.total.value, 0, "the rejected item must not be indexed");
}

//! # xerj Chaos Test Suite — SLA & Durability
//!
//! Simulates real production failures: crash recovery, WAL corruption, restart
//! loops, concurrent stress, large documents, flush under load, schema evolution,
//! and data integrity.
//!
//! Every test prints timestamped headers, per-iteration results, and contributes
//! to a final summary table printed at the end of the suite run.
//!
//! Run with:
//! ```bash
//! cargo test -p xerj-engine --test chaos_tests -- --nocapture
//! ```

use serde_json::{json, Value};
use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

// ── Test result tracking ──────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct TestResult {
    name: String,
    iterations: u64,
    pass: u64,
    fail: u64,
    duration: Duration,
}

/// Global accumulator for cross-test summary.
fn chaos_results() -> &'static Mutex<Vec<TestResult>> {
    static RESULTS: OnceLock<Mutex<Vec<TestResult>>> = OnceLock::new();
    RESULTS.get_or_init(|| Mutex::new(Vec::new()))
}

fn push_result(r: TestResult) {
    chaos_results().lock().unwrap().push(r);
}

fn now_ts() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let h = (secs / 3600) % 24;
    let m = (secs / 60) % 60;
    let s = secs % 60;
    format!("{:02}:{:02}:{:02}Z", h, m, s)
}

fn print_header(test_name: &str) {
    println!();
    println!("┌─────────────────────────────────────────────────────────────────┐");
    println!("│  [{ts}]  {name:<52}│", ts = now_ts(), name = test_name);
    println!("└─────────────────────────────────────────────────────────────────┘");
}

fn print_summary(results: &[TestResult]) {
    println!();
    println!("╔══════════════════════════════════════════════════════════════════╗");
    println!("║  CHAOS TEST RESULTS — xerj SLA & Durability                   ║");
    println!("╠══════════════════════════════════════════════════════════════════╣");
    println!(
        "║  {:<24} │ {:>10} │ {:>4} │ {:>4} │ {:<9} ║",
        "Test", "Iterations", "Pass", "Fail", "Duration"
    );
    println!(
        "║  {:<24} │ {:>10} │ {:>4} │ {:>4} │ {:<9} ║",
        "─".repeat(24),
        "─".repeat(10),
        "─".repeat(4),
        "─".repeat(4),
        "─".repeat(9)
    );
    for r in results {
        println!(
            "║  {:<24} │ {:>10} │ {:>4} │ {:>4} │ {:<9} ║",
            trunc24(&r.name),
            r.iterations,
            r.pass,
            r.fail,
            format!("{:.1}s", r.duration.as_secs_f64()),
        );
    }
    println!("╚══════════════════════════════════════════════════════════════════╝");

    let total_pass: u64 = results.iter().map(|r| r.pass).sum();
    let total_fail: u64 = results.iter().map(|r| r.fail).sum();
    let total_iters: u64 = results.iter().map(|r| r.iterations).sum();
    println!(
        "  TOTAL: {}/{} iterations passed  ({} failed)",
        total_pass, total_iters, total_fail
    );
    if total_fail == 0 {
        println!("  ALL CHAOS TESTS PASSED");
    } else {
        println!("  FAILURES DETECTED — see above for details");
    }
    println!();
}

fn trunc24(s: &str) -> String {
    if s.len() <= 24 {
        s.to_string()
    } else {
        format!("{}…", &s[..23])
    }
}

// ── Engine helpers ────────────────────────────────────────────────────────────

fn make_engine(dir: &TempDir) -> Engine {
    make_engine_at(dir.path())
}

fn make_engine_at(path: &std::path::Path) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = path.to_str().unwrap().to_string();
    // High flush thresholds — tests that care will flush explicitly.
    config.storage.flush_size_mb = 4096;
    config.storage.flush_interval_secs = 86400;
    Engine::new(config).expect("engine::new")
}

async fn count_all(idx: &Arc<xerj_engine::Index>) -> u64 {
    let req =
        parse_request(&json!({ "query": { "match_all": {} }, "size": 0 })).expect("parse_request");
    idx.search(&req).await.map(|r| r.total.value).unwrap_or(0)
}

// ── FNV-1a 64-bit hash for checksums ─────────────────────────────────────────

fn fnv64(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in data {
        h ^= b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

// ══════════════════════════════════════════════════════════════════════════════
// Test 1 — SIGKILL During Active Writes (crash resilience)
// ══════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn chaos_crash_during_writes() {
    print_header("Test 1: SIGKILL During Active Writes (crash resilience)");

    let test_start = Instant::now();
    let crash_points = [100u64, 500, 1000, 5000];
    let rounds_per_point: usize = 2; // 2 × 4 = 8, plus 2 bonus = 10 total
    let mut iterations = 0u64;
    let mut pass = 0u64;
    let mut fail = 0u64;

    for &crash_after in &crash_points {
        for round in 0..rounds_per_point {
            iterations += 1;
            let dir = TempDir::new().unwrap();
            let iter_start = Instant::now();

            // Phase 1: index N docs then "crash" (drop without flush).
            {
                let engine = make_engine(&dir);
                engine.create_index("crash_idx", Schema::empty()).unwrap();
                let idx = engine.get_index("crash_idx").unwrap();
                for i in 0..crash_after {
                    idx.index_document(
                        Some(format!("doc-{}", i)),
                        json!({ "body": format!("document number {}", i), "seq": i }),
                    )
                    .await
                    .unwrap();
                }
                // Drop without flush — simulate power loss / SIGKILL.
                drop(idx);
                drop(engine);
            }

            // Phase 2: reopen and replay WAL.
            let engine2 = make_engine_at(dir.path());
            let idx2 = engine2
                .get_index("crash_idx")
                .expect("index must reopen from WAL");
            let recovered = count_all(&idx2).await;
            let elapsed_ms = iter_start.elapsed().as_millis();

            // Allow up to 0.5% loss for batched WAL sync (same as ES translog batched mode)
            let min_recovered = (crash_after as f64 * 0.995) as u64;
            let ok = recovered >= min_recovered;
            if ok {
                pass += 1;
            } else {
                fail += 1;
            }

            let rate = (recovered as f64 / crash_after as f64) * 100.0;
            println!(
                "  [{ts}] iter={it:>2}  crash_after={n:>5}  round={r}  \
                 recovered={rec}  rate={rate:.1}%  elapsed={ms}ms  {status}",
                ts = now_ts(),
                it = iterations,
                n = crash_after,
                r = round,
                rec = recovered,
                rate = rate,
                ms = elapsed_ms,
                status = if ok {
                    "PASS"
                } else {
                    "FAIL ← data loss detected"
                },
            );
        }
    }

    // Two additional iterations at extreme points.
    for &crash_after in &[50u64, 10_000u64] {
        iterations += 1;
        let dir = TempDir::new().unwrap();
        let iter_start = Instant::now();
        {
            let engine = make_engine(&dir);
            engine.create_index("crash_idx", Schema::empty()).unwrap();
            let idx = engine.get_index("crash_idx").unwrap();
            for i in 0..crash_after {
                idx.index_document(
                    Some(format!("doc-{}", i)),
                    json!({ "body": format!("doc {}", i) }),
                )
                .await
                .unwrap();
            }
            drop(idx);
            drop(engine);
        }
        let engine2 = make_engine_at(dir.path());
        let idx2 = engine2.get_index("crash_idx").expect("index must reopen");
        let recovered = count_all(&idx2).await;
        // Allow up to 0.5% loss for batched WAL sync (same as ES translog batched mode)
        let min_recovered = (crash_after as f64 * 0.995) as u64;
        let ok = recovered >= min_recovered;
        if ok {
            pass += 1;
        } else {
            fail += 1;
        }
        println!(
            "  [{ts}] iter={it:>2}  crash_after={n:>6}  recovered={rec}  \
             elapsed={ms}ms  {status}",
            ts = now_ts(),
            it = iterations,
            n = crash_after,
            rec = recovered,
            ms = iter_start.elapsed().as_millis(),
            status = if ok { "PASS" } else { "FAIL" },
        );
    }

    let duration = test_start.elapsed();
    println!(
        "\n  RESULT: {pass}/{iterations} passed  duration={d:.1}s",
        d = duration.as_secs_f64()
    );
    push_result(TestResult {
        name: "Crash recovery".into(),
        iterations,
        pass,
        fail,
        duration,
    });
    assert_eq!(fail, 0, "crash recovery failed on {} iterations", fail);
}

// ══════════════════════════════════════════════════════════════════════════════
// Test 2 — WAL Corruption Recovery
// ══════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn chaos_wal_corruption() {
    print_header("Test 2: WAL Corruption Recovery");

    let test_start = Instant::now();
    let mut iterations = 0u64;
    let mut pass = 0u64;
    let mut fail = 0u64;
    let doc_count = 200u64;

    struct CorruptCase {
        name: &'static str,
        apply: fn(&mut Vec<u8>),
    }

    // ptr_arg: signature must stay `fn(&mut Vec<u8>)` to match the CorruptCase.apply
    // field type shared with corrupt_truncate50, which needs Vec::truncate.
    #[allow(clippy::ptr_arg)]
    fn corrupt_last10(data: &mut Vec<u8>) {
        let len = data.len();
        if len >= 10 {
            for b in &mut data[len - 10..] {
                *b = 0xFF;
            }
        }
    }
    // ptr_arg: signature must stay `fn(&mut Vec<u8>)` to match the CorruptCase.apply
    // field type shared with corrupt_truncate50, which needs Vec::truncate.
    #[allow(clippy::ptr_arg)]
    fn corrupt_middle(data: &mut Vec<u8>) {
        let mid = data.len() / 2;
        let end = (mid + 64).min(data.len());
        for b in &mut data[mid..end] {
            *b ^= 0xAA;
        }
    }
    // ptr_arg: signature must stay `fn(&mut Vec<u8>)` to match the CorruptCase.apply
    // field type shared with corrupt_truncate50, which needs Vec::truncate.
    #[allow(clippy::ptr_arg)]
    fn corrupt_header(data: &mut Vec<u8>) {
        // Overwrite the 4-byte "ZWAL" magic at offset 0.
        if data.len() >= 4 {
            data[0] = 0x00;
            data[1] = 0x00;
            data[2] = 0x00;
            data[3] = 0x00;
        }
    }
    fn corrupt_truncate50(data: &mut Vec<u8>) {
        let half = data.len() / 2;
        data.truncate(half);
    }
    // ptr_arg: signature must stay `fn(&mut Vec<u8>)` to match the CorruptCase.apply
    // field type shared with corrupt_truncate50, which needs Vec::truncate.
    #[allow(clippy::ptr_arg)]
    fn corrupt_zero4kb(data: &mut Vec<u8>) {
        let start = (data.len() / 4).min(data.len().saturating_sub(4096));
        let end = (start + 4096).min(data.len());
        for b in &mut data[start..end] {
            *b = 0x00;
        }
    }

    let cases: &[CorruptCase] = &[
        CorruptCase {
            name: "last-10-bytes",
            apply: corrupt_last10,
        },
        CorruptCase {
            name: "middle-64-bytes",
            apply: corrupt_middle,
        },
        CorruptCase {
            name: "header-magic",
            apply: corrupt_header,
        },
        CorruptCase {
            name: "truncate-50pct",
            apply: corrupt_truncate50,
        },
        CorruptCase {
            name: "zero-4kb-block",
            apply: corrupt_zero4kb,
        },
    ];

    for case in cases {
        iterations += 1;
        let dir = TempDir::new().unwrap();
        let iter_start = Instant::now();

        // Phase 1: index docs and close engine cleanly (WAL is written, no flush).
        {
            let engine = make_engine(&dir);
            engine.create_index("wal_idx", Schema::empty()).unwrap();
            let idx = engine.get_index("wal_idx").unwrap();
            for i in 0..doc_count {
                idx.index_document(
                    Some(format!("d{}", i)),
                    json!({ "n": i, "msg": format!("entry {}", i) }),
                )
                .await
                .unwrap();
            }
            drop(idx);
            drop(engine);
        }

        // Phase 2: find WAL file and corrupt it.
        let wal_dir = dir.path().join("wal_idx").join("wal");
        let wal_file = std::fs::read_dir(&wal_dir)
            .ok()
            .and_then(|rd| {
                rd.flatten()
                    .find(|e| e.path().extension().map(|x| x == "wal").unwrap_or(false))
            })
            .map(|e| e.path());

        let mut recovered = 0u64;
        let engine_opened;

        if let Some(ref wf) = wal_file {
            let mut data = std::fs::read(wf).unwrap_or_default();
            (case.apply)(&mut data);
            let _ = std::fs::write(wf, &data);

            // Phase 3: reopen — must NOT panic.
            let engine_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                make_engine_at(dir.path())
            }));

            match engine_result {
                Ok(engine2) => {
                    engine_opened = true;
                    if let Ok(idx2) = engine2.get_index("wal_idx") {
                        recovered = count_all(&idx2).await;
                    }
                    // Header corruption means no docs can be read; that's acceptable.
                }
                Err(_) => {
                    engine_opened = false;
                }
            }
        } else {
            // No WAL file found — engine may have flushed, which is also fine.
            engine_opened = true;
            let engine2 = make_engine_at(dir.path());
            if let Ok(idx2) = engine2.get_index("wal_idx") {
                recovered = count_all(&idx2).await;
            }
        }

        let loss_pct = if doc_count > 0 {
            (doc_count.saturating_sub(recovered)) as f64 / doc_count as f64 * 100.0
        } else {
            0.0
        };

        // Pass = engine opened without panic (data loss is acceptable for some corruption types).
        let ok = engine_opened;
        if ok {
            pass += 1;
        } else {
            fail += 1;
        }

        println!(
            "  [{ts}] iter={it}  corruption={name:<20}  opened={op}  \
             recovered={rec}/{total}  loss={loss:.1}%  elapsed={ms}ms  {status}",
            ts = now_ts(),
            it = iterations,
            name = case.name,
            op = engine_opened,
            rec = recovered,
            total = doc_count,
            loss = loss_pct,
            ms = iter_start.elapsed().as_millis(),
            status = if ok {
                "PASS"
            } else {
                "FAIL ← engine crashed/panicked"
            },
        );
    }

    let duration = test_start.elapsed();
    println!(
        "\n  RESULT: {pass}/{iterations} passed  duration={d:.1}s",
        d = duration.as_secs_f64()
    );
    push_result(TestResult {
        name: "WAL corruption".into(),
        iterations,
        pass,
        fail,
        duration,
    });
    assert_eq!(fail, 0, "WAL corruption caused {} engine crash(es)", fail);
}

