// Test 10 — Data Integrity Verification
// ══════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn chaos_data_integrity() {
    print_header("Test 10: Data Integrity Verification (checksum round-trip + WAL replay)");

    let test_start = Instant::now();
    let doc_count = 1000u64;

    // Pre-compute docs and their expected checksums.
    let docs: Vec<(String, Value)> = (0..doc_count)
        .map(|i| {
            let id = format!("integrity-{}", i);
            let src = json!({
                "index": i,
                "payload": format!("integrity-payload-{:010}", i),
                "anchor":  format!("doc-{}-checksum-anchor", i),
            });
            (id, src)
        })
        .collect();

    // Expected checksum: hash of the canonical JSON we wrote.
    let _expected_checksums: HashMap<String, u64> = docs
        .iter()
        .map(|(id, src)| (id.clone(), fnv64(src.to_string().as_bytes())))
        .collect();

    let dir = TempDir::new().unwrap();

    // ── Phase 1: index and verify before restart ──────────────────────────────
    println!(
        "  Phase 1: indexing {} docs and verifying checksums pre-restart…",
        doc_count
    );
    let (pre_verified, pre_mismatches) = {
        let engine = make_engine(&dir);
        engine
            .create_index("integrity_idx", Schema::empty())
            .unwrap();
        let idx = engine.get_index("integrity_idx").unwrap();

        for (id, src) in &docs {
            idx.index_document(Some(id.clone()), src.clone())
                .await
                .unwrap();
        }

        let mut v = 0u64;
        let mut m = 0u64;
        for (id, src) in &docs {
            match idx.get_document(id).await {
                Ok(Some(got)) => {
                    if fnv64(got.to_string().as_bytes()) == fnv64(src.to_string().as_bytes()) {
                        v += 1;
                    } else {
                        m += 1;
                    }
                }
                _ => m += 1,
            }
        }
        drop(idx);
        drop(engine);
        (v, m)
    };

    println!(
        "  [{ts}] pre-restart: verified={v}/{total}  mismatches={m}",
        ts = now_ts(),
        v = pre_verified,
        total = doc_count,
        m = pre_mismatches,
    );
    assert_eq!(
        pre_mismatches, 0,
        "pre-restart checksum failures: {}",
        pre_mismatches
    );

    // ── Phase 2: reopen via WAL replay and re-verify ──────────────────────────
    println!("  Phase 2: reopening engine (WAL replay) and re-verifying checksums…");
    let engine2 = make_engine_at(dir.path());
    let idx2 = engine2
        .get_index("integrity_idx")
        .expect("integrity_idx must reopen after WAL replay");

    let mut post_verified = 0u64;
    let mut post_mismatches = 0u64;
    let mut post_missing = 0u64;

    for (id, src) in &docs {
        match idx2.get_document(id).await {
            Ok(Some(got)) => {
                if fnv64(got.to_string().as_bytes()) == fnv64(src.to_string().as_bytes()) {
                    post_verified += 1;
                } else {
                    post_mismatches += 1;
                }
            }
            _ => post_missing += 1,
        }
    }

    let duration = test_start.elapsed();

    println!(
        "\n  [{ts}] post-restart: verified={v}/{total}  mismatches={m}  missing={miss}",
        ts = now_ts(),
        v = post_verified,
        total = doc_count,
        m = post_mismatches,
        miss = post_missing,
    );

    let all_ok = post_mismatches == 0 && post_missing == 0 && post_verified == doc_count;
    println!(
        "  RESULT: {}  duration={d:.1}s",
        if all_ok { "PASS" } else { "FAIL" },
        d = duration.as_secs_f64()
    );

    push_result(TestResult {
        name: "Data integrity".into(),
        iterations: doc_count,
        pass: post_verified,
        fail: post_mismatches + post_missing,
        duration,
    });

    // ── Final summary — printed by whichever test runs last ───────────────────
    // Because tests may run in parallel the summary might be incomplete; add a
    // deliberate delay-free fence: we only have 10 tests so just print all
    // results currently in the accumulator.
    {
        let results = chaos_results().lock().unwrap().clone();
        print_summary(&results);
    }

    assert_eq!(
        post_mismatches, 0,
        "checksum mismatches after WAL replay: {}",
        post_mismatches
    );
    assert_eq!(
        post_missing, 0,
        "docs missing after WAL replay: {}",
        post_missing
    );
    assert_eq!(
        post_verified, doc_count,
        "not all docs verified after restart"
    );
}

//! Issue #463: `_close` must actually reclaim RAM, not just flip a flag.
//!
//! Before the fix, `close_index` only set the `closed_indices` gate; the
//! `Arc<Index>`'s per-segment caches stayed resident, so `_close` freed ~0.03%
//! of an index's memory. The fix flushes the memtable then frees the index's
//! rebuildable caches while KEEPING the `Arc<Index>` loaded (so `_cat`/`_cluster`
//! views are unchanged); the next read re-hydrates from disk.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn count_all(engine: &Engine, name: &str) -> u64 {
    let idx = engine.get_index(name).expect("get index");
    let req = parse_request(&json!({ "query": { "match_all": {} }, "size": 0, "from": 0 }))
        .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

async fn seed(engine: &Engine, name: &str, n: usize) {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index(name, schema).expect("create");
    let idx = engine.get_index(name).expect("get");
    for i in 0..n {
        idx.index_document(
            Some(format!("d{i}")),
            json!({ "body": format!("document number {i}") }),
        )
        .await
        .expect("index");
    }
}

/// Run a size>0 search so the per-segment caches actually hydrate.
async fn hydrate(engine: &Engine, name: &str) -> u64 {
    let idx = engine.get_index(name).expect("get index");
    let req = parse_request(&json!({ "query": { "match": { "body": "document" } }, "size": 25 }))
        .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// `close_index` releases the resident caches while keeping the `Arc<Index>`
/// shell loaded (so `_cat`/`_cluster` views are unchanged); reads re-hydrate on
/// reopen with no data loss. FAIL-BEFORE: with the `idx.release_memory()` call
/// reverted, the caches stay populated so `total_cache_entries == 0` fails.
#[tokio::test]
async fn close_releases_caches_and_reopen_is_lossless() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "docs", 50).await;
    engine.get_index("docs").unwrap().refresh().await.unwrap();

    assert!(engine.is_index_loaded("docs"), "loaded before close");
    hydrate(&engine, "docs").await;
    let cached_before = engine.get_index("docs").unwrap().total_cache_entries();
    assert!(
        cached_before > 0,
        "a query should have hydrated the caches, got {cached_before}"
    );

    engine.close_index("docs").await.expect("close");
    // The shell stays loaded (loaded-index views unchanged), but caches are freed.
    assert!(
        engine.is_index_loaded("docs"),
        "a closed index stays loaded (shell) — matches _cat/_cluster's model"
    );
    assert!(
        engine.closed_indices.contains_key("docs"),
        "close marks the index closed"
    );
    let cached_after = engine.get_index("docs").unwrap().total_cache_entries();
    assert_eq!(
        cached_after, 0,
        "#463: _close must release the resident caches (was {cached_before}, now {cached_after})"
    );

    engine.reopen_index("docs").expect("reopen");
    assert!(
        !engine.closed_indices.contains_key("docs"),
        "reopen clears the closed flag"
    );
    assert_eq!(
        count_all(&engine, "docs").await,
        50,
        "#463: reopen re-hydrates losslessly"
    );
}

/// Data-safety: documents indexed but NOT refreshed/flushed before close must
/// survive close→reopen (close flushes the memtable BEFORE releasing caches).
/// Guards against a memory win that silently drops the memtable.
#[tokio::test]
async fn close_flushes_so_unrefreshed_docs_survive_reopen() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "docs", 30).await; // NO refresh — docs sit in the memtable/WAL

    engine.close_index("docs").await.expect("close");
    engine.reopen_index("docs").expect("reopen");
    assert_eq!(
        count_all(&engine, "docs").await,
        30,
        "#463: close must flush before releasing — no doc may be lost"
    );
}

use sha2::{Digest, Sha256};
use xerj_common::config::{Config, WalSync};
use xerj_common::types::Schema;
use xerj_common::XerjError;
use xerj_engine::{ClusterStateBlockKind, ClusterStateBootStatus, Engine};

/// Byte-level storage snapshot. Directory and symlink topology is included,
/// and every regular file is represented by its length and SHA-256. This is
/// intentionally stronger than an index-count assertion: WAL replay can rotate
/// one file into another while leaving both the document count and directory
/// count unchanged.
fn recursive_storage_snapshot(root: &std::path::Path) -> Vec<String> {
    fn walk(root: &std::path::Path, path: &std::path::Path, out: &mut Vec<String>) {
        let mut entries: Vec<_> = std::fs::read_dir(path)
            .expect("read snapshot directory")
            .map(|entry| entry.expect("read snapshot entry"))
            .collect();
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries {
            let entry_path = entry.path();
            let relative = entry_path
                .strip_prefix(root)
                .expect("snapshot path under root")
                .to_string_lossy();
            let kind = entry.file_type().expect("snapshot file type");
            if kind.is_dir() {
                out.push(format!("d:{relative}"));
                walk(root, &entry_path, out);
            } else if kind.is_symlink() {
                out.push(format!(
                    "l:{relative}->{}",
                    std::fs::read_link(&entry_path)
                        .expect("read snapshot symlink")
                        .to_string_lossy()
                ));
            } else {
                let bytes = std::fs::read(&entry_path).expect("read snapshot file");
                out.push(format!(
                    "f:{relative}:{}:{}",
                    bytes.len(),
                    hex_digest(&bytes)
                ));
            }
        }
    }

    let mut out = Vec::new();
    walk(root, root, &mut out);
    out
}

fn config_for(path: &std::path::Path) -> Config {
    let mut config = Config::default();
    config.server.data_dir = path.to_string_lossy().into_owned();
    config.storage.wal_sync = WalSync::Async;
    config
}

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/cluster_state")
            .join(name),
    )
    .expect("read fixture")
}

fn write_fixture(path: &std::path::Path, name: &str) -> Vec<u8> {
    let bytes = fixture(name);
    std::fs::write(path.join("cluster_state.json"), &bytes).expect("write fixture");
    bytes
}

fn hex_digest(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

