// ── es_mapping.json ───────────────────────────────────────────────────────────

/// The raw ES mapping blob (analyzers, date formats, `dense_vector` dims) is
/// the mapping users actually see through `GET /{index}/_mapping`. A corrupt
/// one used to be logged and ignored, leaving the index serving with a
/// silently emptier mapping than the one on disk.
#[tokio::test]
async fn unparseable_es_mapping_json_fails_the_index_on_startup() {
    let dir = TempDir::new().unwrap();
    create_mapped_index(&dir, "torn_es_mapping").await;
    std::fs::write(
        dir.path().join("torn_es_mapping").join("es_mapping.json"),
        b"{\"properties\": ",
    )
    .unwrap();

    let engine = Engine::new(config_for(&dir)).expect("engine::new");
    assert!(
        engine.get_index("torn_es_mapping").is_err(),
        "an index with a corrupt es_mapping.json must not be served"
    );
    assert!(
        engine.failed_indices.contains_key("torn_es_mapping"),
        "the failure must be recorded so cluster health goes red"
    );
    assert_eq!(engine.health().await.status, "red");
}

// ── the user-visible signal ───────────────────────────────────────────────────

/// End to end: a node booting over a corrupt `schema.json` must come up red
/// with the index unserved, not green with an empty mapping.
#[tokio::test]
async fn engine_startup_reports_red_for_a_corrupt_schema() {
    let dir = TempDir::new().unwrap();
    create_mapped_index(&dir, "torn_boot").await;
    let path = dir.path().join("torn_boot").join("schema.json");
    let good = std::fs::read(&path).unwrap();
    std::fs::write(&path, &good[..good.len() / 2]).unwrap();

    let engine = Engine::new(config_for(&dir)).expect("engine::new");
    assert!(
        engine.get_index("torn_boot").is_err(),
        "a corrupt index must not be served with a re-inferred mapping"
    );
    let reason = engine
        .failed_indices
        .get("torn_boot")
        .map(|r| r.value().reason.clone())
        .expect("the failure must be recorded in failed_indices");
    assert!(
        reason.contains("schema.json"),
        "the recorded reason must name the file, got: {reason}"
    );
    assert_eq!(engine.health().await.status, "red");
}

/// Refusing the open is only half the fix: a failed index is absent from
/// `indices`, so `PUT /{index}` and bulk auto-create used to sail straight past
/// the "already exists" check and run `Index::create` over the corrupt
/// directory — overwriting `schema.json` with an empty mapping and destroying
/// the evidence. That door has to be shut too.
#[tokio::test]
async fn create_over_a_failed_index_is_refused() {
    let dir = TempDir::new().unwrap();
    create_mapped_index(&dir, "no_recreate").await;
    let path = dir.path().join("no_recreate").join("schema.json");
    let good = std::fs::read(&path).unwrap();
    std::fs::write(&path, &good[..good.len() / 2]).unwrap();

    let engine = Engine::new(config_for(&dir)).expect("engine::new");
    let err = engine
        .create_index("no_recreate", Schema::empty())
        .expect_err("re-creating a failed index must not silently succeed")
        .to_string();
    assert!(
        err.contains("failed to open") && err.contains("DELETE"),
        "the error must explain the state and the way out, got: {err}"
    );
    // Auto-create (the bulk/index-a-document door) goes through the same gate.
    assert!(engine.get_or_create_index("no_recreate").is_err());
    // And the corrupt file is still there, untouched, for the operator.
    assert_eq!(
        std::fs::read(&path).unwrap().len(),
        good.len() / 2,
        "a refused create must not have rewritten schema.json"
    );
}

/// …and refusing to create must not brick the name. Delete is the operator's
/// recovery path (restore from backup afterwards), so it has to work on an
/// index that never opened.
#[tokio::test]
async fn a_failed_index_can_still_be_deleted() {
    let dir = TempDir::new().unwrap();
    create_mapped_index(&dir, "removable").await;
    let path = dir.path().join("removable").join("schema.json");
    let good = std::fs::read(&path).unwrap();
    std::fs::write(&path, &good[..good.len() / 2]).unwrap();

    let engine = Engine::new(config_for(&dir)).expect("engine::new");
    assert_eq!(engine.health().await.status, "red");

    engine
        .delete_index("removable")
        .await
        .expect("a failed index must be deletable — otherwise the name is bricked");
    assert!(
        !dir.path().join("removable").exists(),
        "the data directory must be gone"
    );
    assert!(!engine.failed_indices.contains_key("removable"));
    assert_eq!(
        engine.health().await.status,
        "green",
        "health must recover once the corrupt index is gone"
    );

    // The name is usable again.
    engine.create_index("removable", Schema::empty()).unwrap();
    assert!(engine.get_index("removable").is_ok());
}

/// The third recovery door, and the only one where #202 had to change the
/// engine: restoring the index from a snapshot must also *clear* the recorded
/// failure.
///
/// The restore loop reopens the index and puts it back in `indices`, but the
/// entry this change writes into `failed_indices` at boot is what cluster
/// health reads. Leave it behind and the repair works while `/_cluster/health`
/// stays red and `/health/ready` keeps reporting a failed index — a node that
/// is fine but says it is not, with no way to correct it short of a restart.
#[tokio::test]
async fn restoring_from_a_snapshot_clears_the_recorded_failure() {
    let dir = TempDir::new().unwrap();
    // The repository has to live under `data_dir` — an external snapshot root
    // is refused unless it is in `limits.snapshot_repo_allowlist`. It has no
    // `wal/` child, so the boot scan skips it rather than reading it as an
    // index.
    let repo_path = dir.path().join("snap_repo").to_str().unwrap().to_string();
    create_mapped_index(&dir, "snap_back").await;

    // Snapshot the index while it is still intact.
    {
        let engine = Engine::new(config_for(&dir)).expect("engine::new");
        engine
            .create_snapshot(&repo_path, "s1", Some(vec!["snap_back".to_string()]))
            .await
            .expect("create_snapshot");
    }

    // Now tear the sidecar: the node boots red with the index unserved.
    let path = dir.path().join("snap_back").join("schema.json");
    let good = std::fs::read(&path).unwrap();
    std::fs::write(&path, &good[..good.len() / 2]).unwrap();

    let engine = Engine::new(config_for(&dir)).expect("engine::new");
    assert_eq!(engine.health().await.status, "red");
    assert!(engine.failed_indices.contains_key("snap_back"));

    engine
        .restore_snapshot(&repo_path, "s1", Some(vec!["snap_back".to_string()]))
        .await
        .expect("restoring over a failed index must succeed — it is the repair");

    assert!(
        !engine.failed_indices.contains_key("snap_back"),
        "a successful restore must clear the recorded failure, or health stays \
         red after the repair actually worked"
    );
    assert_eq!(
        engine.health().await.status,
        "green",
        "health must follow the repair"
    );

    // And it is the snapshot's mapping that is being served, not a re-inferred
    // one — restoring must not be a second route to the #202 mapping loss.
    let index = engine
        .get_index("snap_back")
        .expect("the restored index must serve");
    assert_eq!(
        index.schema().await.field("code").map(|f| f.field_type),
        Some(FieldType::Keyword),
        "the restored index must carry the mapping the snapshot was taken with"
    );
}

// ── the writer must not manufacture what the reader now refuses ───────────────

/// Refusing a torn sidecar is only safe if our own writer cannot produce one.
///
/// `write_file_atomic` staged every write in `<file>.tmp` — one shared name for
/// all writers of that path. Two concurrent settings writes (`PUT /_settings`
/// racing another `PUT /_settings`, or an `index.blocks` update) therefore both
/// opened it `O_TRUNC` and interleaved their bytes before either renamed, so
/// the *complete* file that landed was a mix of two bodies. Run against the old
/// shared name (four runs, two boxes) this loop reports 86–294 of 800 writes
/// failing with ENOENT — the loser renaming a file the winner had already moved
/// — and, with those errors swallowed as the callers do, 1–16 of 200 rounds
/// leaving an unparseable file. The counts are race-dependent; both being
/// non-zero is not. After the fix: no failed writes, no torn file, no debris,
/// which is what the assertions below pin.
///
/// Before #202 that torn file was "only" silently swapped for an empty mapping.
/// Now it refuses the open, so a lost race would brick the index — which is why
/// this test lives here and not in a general-hygiene file.
#[test]
fn concurrent_atomic_writes_never_leave_a_torn_sidecar() {
    let dir = TempDir::new().unwrap();
    let path = dir.path().join("settings.json");

    // Two bodies of very different length: a short write landing inside a long
    // one is what leaves trailing garbage behind valid-looking JSON.
    let small = serde_json::to_vec_pretty(&json!({"index": {"refresh_interval": "1s"}})).unwrap();
    let big = serde_json::to_vec_pretty(&json!({
        "index": {"analysis": (0..400).map(|i| format!("filter-{i}")).collect::<Vec<_>>()}
    }))
    .unwrap();

    let mut torn = 0usize;
    let mut write_errors: Vec<String> = Vec::new();
    for _ in 0..200 {
        std::thread::scope(|s| {
            let handles: Vec<_> = [&small, &big, &small, &big]
                .into_iter()
                .map(|payload| {
                    let p = path.clone();
                    s.spawn(move || xerj_engine::index::write_file_atomic(&p, payload))
                })
                .collect();
            for h in handles {
                // A shared staging name also made writes fail spuriously: the
                // loser of the race renamed a file the winner had already moved
                // (ENOENT). Record it rather than panicking, so a failure names
                // the defect instead of "a scoped thread panicked".
                if let Err(e) = h.join().expect("writer thread") {
                    write_errors.push(e.to_string());
                }
            }
        });
        let bytes = std::fs::read(&path).unwrap();
        if serde_json::from_slice::<serde_json::Value>(&bytes).is_err() {
            torn += 1;
        }
    }
    assert!(
        write_errors.is_empty(),
        "{} concurrent writes failed, first: {} — writers must not collide on a staging file",
        write_errors.len(),
        write_errors[0]
    );
    assert_eq!(
        torn, 0,
        "{torn}/200 rounds of concurrent writes left a settings.json that does not parse — \
         the write path can manufacture the corruption the read path now refuses"
    );

    // And no staging debris is left behind for a successful write.
    let leftovers: Vec<_> = std::fs::read_dir(dir.path())
        .unwrap()
        .filter_map(|e| e.ok())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .filter(|n| n != "settings.json")
        .collect();
    assert!(
        leftovers.is_empty(),
        "staging files left behind: {leftovers:?}"
    );
}

//! Regression tests for issue #362: `_count` must answer the same question
//! `_search` answers.
//!
//! `POST /{index}/_count` is `search({query, size: 0}).total`, so a `size: 0`
//! total that disagrees with the `size > 0` hit set is the HTTP-visible bug:
//! a count describing documents nobody can retrieve.
//!
//! Pre-fix, `try_shortcut_count`'s Term arm fell back to the segment FTS term
//! dictionary whenever the field had no doc-values column — which is exactly
//! what an analyzed `text` field is. The dictionary holds ANALYZED tokens
//! (standard analyzer: tokenised, lowercased), while `_search` resolves a
//! `term` on such a field against the whole `_source` value. Two documents,
//! two spellings, both counted and neither retrievable.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// What `POST /_count` runs: `size: 0`, total only (`es_compat::count_docs`).
async fn count_total(idx: &Index, q: &Value) -> u64 {
    let req = parse_request(&json!({ "query": q, "size": 0, "from": 0 })).expect("parse_request");
    idx.search(&req).await.expect("count search").total.value
}

/// What `POST /_search` runs: a real page of hits.
async fn search_hits(idx: &Index, q: &Value) -> (u64, usize) {
    let req = parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request");
    let r = idx.search(&req).await.expect("search");
    (r.total.value, r.hits.len())
}

async fn seed() -> (TempDir, std::sync::Arc<Index>) {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let mut schema = Schema::empty();
    // `"type": "text"` from an ES mapping lands here with `doc_values: false`
    // (`es_compat::es_properties_to_fields`), which is precisely what sends a
    // term count for this field into the FTS term-dictionary fallback.
    let mut title = FieldConfig::new("title", FieldType::Text);
    title.options.doc_values = false;
    schema.fields.push(title);
    schema
        .fields
        .push(FieldConfig::new("path", FieldType::Keyword));
    // A keyword field with `doc_values: false` reaches the same
    // no-column branch as `title`, so the abandon must not cost it its
    // exact count — it is the shape that would turn an overcount into an
    // undercount if the branch were narrowed the other way.
    let mut code = FieldConfig::new("code", FieldType::Keyword);
    code.options.doc_values = false;
    schema.fields.push(code);
    engine.create_index("count-parity", schema).unwrap();
    let idx = engine.get_index("count-parity").unwrap();

    idx.index_document(
        Some("java".into()),
        json!({
            "title": "TestSegmentReader.java",
            "path": "lucene/TestSegmentReader.java",
            "code": "AB-1234"
        }),
    )
    .await
    .unwrap();
    idx.index_document(
        Some("fox".into()),
        json!({"title": "the quick brown fox", "path": "docs/fox.txt", "code": "ab-1234"}),
    )
    .await
    .unwrap();
    // The count shortcut only runs against flushed segments; the memtable
    // arm is a different code path and already agrees with the scan.
    idx.flush().await.unwrap();
    (dir, idx)
}

/// The `_count` / `_search` disagreement, one query per row.
async fn assert_count_agrees_with_search(idx: &Index, q: Value, label: &str) {
    let count = count_total(idx, &q).await;
    let (total, hits) = search_hits(idx, &q).await;
    assert_eq!(
        count, total,
        "{label}: _count total {count} != _search total {total} for {q}"
    );
    assert_eq!(
        count, hits as u64,
        "{label}: _count says {count} but _search can materialise only {hits} document(s) for {q}"
    );
}

/// Issue #362's own repro: a term whose spelling differs from `_source`
/// only in case. The dictionary retry made `_count` find it; `_search`
/// compares against the raw `_source` value and cannot.
#[tokio::test]
async fn count_does_not_overreport_lowercased_term_on_text_field() {
    let (_dir, idx) = seed().await;
    assert_count_agrees_with_search(
        &idx,
        json!({"term": {"title": "testsegmentreader.java"}}),
        "lowercased spelling",
    )
    .await;
}

/// The half with no case component at all: an ANALYZED token of a
/// multi-word text value. The dictionary hit here is genuine, which is why
/// deleting the lowercase retry alone would not have fixed it.
#[tokio::test]
async fn count_does_not_overreport_analyzed_token_on_text_field() {
    let (_dir, idx) = seed().await;
    assert_count_agrees_with_search(
        &idx,
        json!({"term": {"title": "quick"}}),
        "analyzed token of a multi-word value",
    )
    .await;
}

/// The exact spelling still counts, and still returns its document — the
/// fix must not trade the overcount for an undercount.
#[tokio::test]
async fn count_still_finds_the_exact_text_term() {
    let (_dir, idx) = seed().await;
    let q = json!({"term": {"title": "TestSegmentReader.java"}});
    assert_count_agrees_with_search(&idx, q.clone(), "exact spelling").await;
    assert_eq!(
        count_total(&idx, &q).await,
        1,
        "exact-spelling term must still count its document"
    );
}

/// A `keyword` field keeps its exact, byte-comparing count: that field has
/// a doc-values column and never took the FTS fallback.
#[tokio::test]
async fn keyword_term_count_is_unchanged() {
    let (_dir, idx) = seed().await;
    let q = json!({"term": {"path": "lucene/TestSegmentReader.java"}});
    assert_count_agrees_with_search(&idx, q.clone(), "keyword field").await;
    assert_eq!(count_total(&idx, &q).await, 1, "keyword term must count 1");
    assert_eq!(
        count_total(
            &idx,
            &json!({"term": {"path": "LUCENE/TestSegmentReader.java"}})
        )
        .await,
        0,
        "keyword term must stay case-sensitive"
    );
}

/// The abandon is not a licence to undercount: a `keyword` field with
/// `doc_values: false` takes the very same no-column branch and must still
/// count exactly one document per spelling, case-sensitively.
#[tokio::test]
async fn keyword_without_doc_values_still_counts_exactly() {
    let (_dir, idx) = seed().await;
    for (spelling, expected) in [("AB-1234", 1), ("ab-1234", 1), ("zz-9", 0)] {
        let q = json!({"term": {"code": spelling}});
        assert_count_agrees_with_search(&idx, q.clone(), "keyword, doc_values:false").await;
        assert_eq!(
            count_total(&idx, &q).await,
            expected,
            "keyword without doc-values: wrong count for {spelling}"
        );
    }
}

//! Issue #834: `dis_max` scored every buffered match a flat 1.0 on the
//! memtable — the stored-doc scorer had no DisMax arm, so its catch-all
//! fired — while the segment path applies the real
//! `max(sub_scores) + tie_breaker × Σ(rest)` combination. A doc matching
//! MORE disjuncts (which must rank highest) tied with single-disjunct
//! docs pre-flush, and the ranking changed at `_flush`.
//!
//! The fix scores each single-field `match` sub through the SAME memtable
//! BM25 path a standalone `match` takes (`search_text_boosted`, per
//! (field, query) sub) and combines per doc exactly like the segment's
//! `execute_dis_max`. These tests pin both properties in BOTH phases:
//!
//! * the two-disjunct doc ranks strictly first;
//! * per doc, the `dis_max` score equals
//!   `max + tie_breaker × (Σ − max)` over the scores the SAME standalone
//!   sub-queries return in the SAME phase — the invariant that kept the
//!   reverted stored-doc-scorer attempt (PR #835) out (#572: sub scores
//!   inside the compound must equal the standalone sub scores).
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is here.

use serde_json::{json, Value};
use std::collections::BTreeSet;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

/// Score of `id` under `q`, or 0.0 when the doc is not a hit — the
/// contribution a non-matching `dis_max` sub makes.
async fn score_or_zero(idx: &Index, q: &Value, id: &str) -> f32 {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .find(|h| h.id == id)
        .map(|h| h.score)
        .unwrap_or(0.0)
}

async fn hit_ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

fn expect(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

/// Per-doc dis_max contract: the compound's score equals
/// `max + tie·(Σ − max)` over the SAME standalone sub scores.
async fn assert_dis_max_contract(
    idx: &Index,
    dm: &Value,
    sub_x: &Value,
    sub_y: &Value,
    tie: f32,
    id: &str,
    phase: &str,
) {
    let s_dm = score_or_zero(idx, dm, id).await;
    let s_x = score_or_zero(idx, sub_x, id).await;
    let s_y = score_or_zero(idx, sub_y, id).await;
    let max = s_x.max(s_y);
    let want = max + tie * (s_x + s_y - max);
    assert!(
        (s_dm - want).abs() < 1e-4,
        "{phase}: dis_max({id}) = {s_dm}, want max + tie·(Σ−max) = \
         {want} from standalone subs x={s_x} y={s_y} (#834)"
    );
}

async fn assert_phase(
    idx: &Index,
    dm: &Value,
    sub_x: &Value,
    sub_y: &Value,
    tie: f32,
    phase: &str,
) {
    let res = idx.search(&req(dm.clone())).await.unwrap();
    let ids: BTreeSet<String> = res.hits.iter().map(|h| h.id.clone()).collect();
    assert_eq!(
        ids,
        expect(&["a", "b", "ab"]),
        "{phase}: docs matching ANY disjunct are hits (#834)"
    );
    assert_eq!(
        res.hits.first().map(|h| h.id.as_str()),
        Some("ab"),
        "{phase}: the two-disjunct doc must rank first (#834)"
    );

    assert_dis_max_contract(idx, dm, sub_x, sub_y, tie, "a", phase).await;
    assert_dis_max_contract(idx, dm, sub_x, sub_y, tie, "b", phase).await;
    assert_dis_max_contract(idx, dm, sub_x, sub_y, tie, "ab", phase).await;

    let s_ab = score_or_zero(idx, dm, "ab").await;
    let s_a = score_or_zero(idx, dm, "a").await;
    let s_b = score_or_zero(idx, dm, "b").await;
    assert!(
        s_ab > s_a + 1e-4 && s_ab > s_b + 1e-4,
        "{phase}: ab={s_ab} must score strictly above a={s_a} and b={s_b} (#834)"
    );
}

#[tokio::test]
async fn dis_max_ranks_multi_disjunct_doc_first_and_combines_like_the_segment() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema.fields.push(FieldConfig::new("x", FieldType::Text));
    schema.fields.push(FieldConfig::new("y", FieldType::Text));
    engine.create_index("dmscore", schema).unwrap();
    let idx = engine.get_index("dmscore").unwrap();

    // `a` matches only the x-disjunct, `b` only the y-disjunct, `ab` both —
    // so `ab` must score max + tie_breaker·min and rank strictly first.
    idx.index_document(Some("a".into()), json!({ "x": "quick", "y": "other" }))
        .await
        .unwrap();
    idx.index_document(Some("b".into()), json!({ "x": "other", "y": "quick" }))
        .await
        .unwrap();
    idx.index_document(Some("ab".into()), json!({ "x": "quick", "y": "quick" }))
        .await
        .unwrap();

    let tie = 0.3_f32;
    let dm = json!({ "dis_max": {
        "queries": [ { "match": { "x": "quick" } }, { "match": { "y": "quick" } } ],
        "tie_breaker": tie,
    }});
    let sub_x = json!({ "match": { "x": "quick" } });
    let sub_y = json!({ "match": { "y": "quick" } });

    assert_phase(&idx, &dm, &sub_x, &sub_y, tie, "pre-flush").await;
    idx.flush().await.unwrap();
    assert_phase(&idx, &dm, &sub_x, &sub_y, tie, "post-flush").await;
}

