//! Docs-vs-source drift guard for the published capability lists (issue #211).
//!
//! A source review concluded XERJ had no pipeline aggregations. It has fifteen.
//! The reviewer had read a hand-maintained list that stopped at `composite`,
//! and nearly opened a roadmap item to build a feature that already shipped.
//! The same lists advertised `has_child` / `has_parent`, which the parser
//! rejects with a 400.
//!
//! The root cause is that "what XERJ supports" was written down in prose in
//! several places and derived from the code in none of them. It is now derived
//! in exactly one place per subsystem —
//! [`xerj_query::parser::SUPPORTED_QUERY_TYPES`] and
//! [`xerj_engine::aggs::SUPPORTED_AGG_TYPES`], each pinned to its own dispatch
//! table by a unit test — and every published list is a marked region checked
//! against those constants here.
//!
//! Adding a query type or an aggregation now fails this test until the docs
//! are updated. That is the point: the failure is cheap, and the wrong
//! conclusion it prevents is not.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

/// Repository root, derived from this crate's manifest directory
/// (`<repo>/engine/crates/xerj-engine`).
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("crate manifest dir must be <repo>/engine/crates/xerj-engine")
        .to_path_buf()
}

/// Read a directory, or fail the test naming it.
///
/// The walkers below used `let Ok(entries) = read_dir(dir) else { return }` and
/// `entries.flatten()`, so an unreadable directory removed its whole subtree
/// from the scan and the test still reported success. The `> 20` floors on the
/// collected file counts do not catch it: `landing/docs/playbooks/` going
/// unreadable drops those pages while sixty others keep the total above the
/// floor. A guard that silently checks less than it was asked to is the
/// accepted-and-ignored pattern (#204) this file exists to prevent, so both
/// the directory and each entry inside it are now hard failures.
fn read_dir_or_panic(dir: &Path) -> Vec<std::fs::DirEntry> {
    let entries = std::fs::read_dir(dir)
        .unwrap_or_else(|e| panic!("cannot list {}: {e} — this walk feeds the published-surface checks; a directory that cannot be read must fail the test, not shrink its scope", dir.display()));
    entries
        .map(|e| {
            e.unwrap_or_else(|err| {
                panic!(
                    "cannot read an entry of {}: {err} — see above; entries are not skipped",
                    dir.display()
                )
            })
        })
        .collect()
}

/// Read a published surface, or fail the test naming it.
///
/// `read_to_string(..).unwrap_or_default()` turned an unreadable or non-UTF-8
/// page into an empty string, which passes every check below by finding
/// nothing — a confidently wrong "no phantom query type here". Every one of
/// these paths came from a directory walk moments earlier, so a read failure
/// is a real fault and belongs in the failure output.
fn read_surface_or_panic(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| {
        panic!(
            "cannot read published surface {}: {e} — an unreadable page must fail \
             this test; treating it as empty would silently pass every check",
            path.display()
        )
    })
}

/// Documentation files that publish the **query**-type lists.
///
/// Paths are repo-relative. A file listed here that has lost its markers is a
/// hard failure, not a skip — a silently unchecked doc is the state this test
/// exists to end.
const QUERY_TYPE_DOCS: &[&str] = &[
    "engine/README.md",
    "landing/llms-full.txt",
    "landing/docs/queries.html",
];

/// Documentation files that publish the **aggregation**-type list.
const AGG_TYPE_DOCS: &[&str] = &[
    "engine/README.md",
    "landing/llms-full.txt",
    "landing/docs/aggregations.html",
];

/// Slice one `<!-- generated:<section> -->` … `<!-- /generated:<section> -->`
/// region out of a document.
fn region<'a>(doc: &'a str, path: &str, section: &str) -> &'a str {
    let open = format!("<!-- generated:{section} -->");
    let close = format!("<!-- /generated:{section} -->");

    let start = doc.find(&open).unwrap_or_else(|| {
        panic!(
            "{path} has no `{open}` marker. Every capability list is generated \
             from the source constants and delimited by these markers; if the \
             section was renamed or removed, update the *_DOCS lists in \
             this test rather than leaving the list unchecked."
        )
    }) + open.len();
    let end = doc[start..]
        .find(&close)
        .unwrap_or_else(|| panic!("{path} opens `{open}` but never closes it with `{close}`"))
        + start;
    &doc[start..end]
}

/// Reject anything inside a checked region that is not a bare ES type name.
///
/// Loudly, because a mis-parsed entry would silently satisfy neither side of
/// the comparison and re-open exactly the drift this file exists to close
/// (the accepted-and-ignored pattern tracked in #204).
fn bare_name(token: &str, path: &str, section: &str) -> String {
    assert!(
        !token.is_empty()
            && token
                .chars()
                .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '_'),
        "{path} section `{section}` contains `{token}`, which is not a bare type name. \
         The region is machine-checked and may hold only type names plus plain-text \
         family labels — put prose outside the markers."
    );
    token.to_string()
}

/// Markdown / plain-text regions: only backtick-delimited tokens count, so the
/// region can carry readable family labels ("Full-text:", "Pipeline:") without
/// them being mistaken for capability names.
fn documented_md(doc: &str, path: &str, section: &str) -> BTreeSet<String> {
    let mut names = BTreeSet::new();
    let mut rest = region(doc, path, section);
    while let Some(o) = rest.find('`') {
        let after = &rest[o + 1..];
        let Some(c) = after.find('`') else {
            panic!("{path} section `{section}` has an unclosed backtick");
        };
        names.insert(bare_name(after[..c].trim(), path, section));
        rest = &after[c + 1..];
    }
    names
}

/// HTML regions on the docs site: one name per `<div class="item">` card, read
/// up to the card's optional `<span class="dsc">` description.
///
/// Descriptions and headings are prose and are deliberately not scanned — only
/// the card's own name is a capability claim.
fn documented_html(doc: &str, path: &str, section: &str) -> BTreeSet<String> {
    const CARD: &str = "<div class=\"item\"";
    let reg = region(doc, path, section);
    let mut names = BTreeSet::new();
    let mut rest = reg;
    while let Some(o) = rest.find(CARD) {
        let after = &rest[o + CARD.len()..];
        let Some(gt) = after.find('>') else {
            panic!("{path} section `{section}` has an unterminated `{CARD}` tag");
        };
        let body = &after[gt + 1..];
        // The name runs to the description span, or to the closing tag.
        let cut = body.find('<').unwrap_or_else(|| {
            panic!("{path} section `{section}` has a card that is never closed")
        });
        names.insert(bare_name(body[..cut].trim(), path, section));
        rest = &body[cut..];
    }
    assert!(
        !names.is_empty(),
        "{path} section `{section}` contains no `{CARD}` cards — the markup changed \
         and this check is reading nothing"
    );
    names
}

fn documented(doc: &str, path: &str, section: &str) -> BTreeSet<String> {
    if path.ends_with(".html") {
        documented_html(doc, path, section)
    } else {
        documented_md(doc, path, section)
    }
}

fn assert_section(section: &str, docs: &[&str], expected: &[&str]) {
    let root = repo_root();
    let expected: BTreeSet<String> = expected.iter().map(|s| s.to_string()).collect();

    for rel in docs {
        let path = root.join(rel);
        let doc = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        let listed = documented(&doc, rel, section);

        let missing: Vec<_> = expected.difference(&listed).collect();
        let extra: Vec<_> = listed.difference(&expected).collect();
        assert!(
            missing.is_empty() && extra.is_empty(),
            "{rel} section `{section}` has drifted from the source of truth.\n  \
             implemented but undocumented: {missing:?}\n  \
             documented but not implemented: {extra:?}\n  \
             The lists are generated: copy them from the constants in \
             xerj-query/src/parser.rs and xerj-engine/src/aggs.rs."
        );
    }
}

#[test]
fn documented_query_types_match_the_parser() {
    assert_section(
        "query-types",
        QUERY_TYPE_DOCS,
        xerj_query::parser::SUPPORTED_QUERY_TYPES,
    );
}

/// The other direction of the same defect: types the docs must show as
/// *rejected*, so nobody plans around a `has_child` that answers 400.
#[test]
fn documented_rejected_query_types_match_the_parser() {
    assert_section(
        "rejected-query-types",
        QUERY_TYPE_DOCS,
        xerj_query::parser::REJECTED_QUERY_TYPES,
    );
}

#[test]
fn documented_agg_types_match_the_engine() {
    assert_section(
        "agg-types",
        AGG_TYPE_DOCS,
        xerj_engine::aggs::SUPPORTED_AGG_TYPES,
    );
}

/// The markers are load-bearing, so prove the extractor actually rejects a
/// drifted list rather than passing on an empty or unparsed region.
#[test]
fn the_extractor_notices_drift() {
    let doc = "<!-- generated:query-types -->\n`match`, `term`\n<!-- /generated:query-types -->";
    let listed = documented(doc, "synthetic", "query-types");
    assert_eq!(
        listed,
        ["match", "term"]
            .iter()
            .map(|s| s.to_string())
            .collect::<BTreeSet<_>>()
    );
    assert!(!listed.contains("bucket_script"));
}

/// Same proof for the HTML card grids on the docs site, which is where the
/// second half of #211 was hiding: `landing/docs/queries.html` shipped cards
/// for `boosted` and `semantic_search`, neither of which the parser has ever
/// dispatched, and `landing/docs/aggregations.html` showed fifteen of
/// sixty-two aggregations with the whole pipeline family absent.
#[test]
fn the_html_extractor_reads_card_names_and_ignores_prose() {
    let doc = "<!-- generated:query-types -->\n\
               <h2>Structural</h2>\n\
               <div class=\"enum-list\">\n\
               <div class=\"item\" id=\"match-all\">match_all<span class=\"dsc\">Everything, \
               unlike match_none.</span></div>\n\
               <div class=\"item\">term</div>\n\
               </div>\n\
               <!-- /generated:query-types -->";
    let listed = documented(doc, "synthetic.html", "query-types");
    assert_eq!(
        listed,
        ["match_all", "term"]
            .iter()
            .map(|s| s.to_string())
            .collect::<BTreeSet<_>>(),
        "a name mentioned only in a card description must not count as a capability"
    );
}

/// A card whose name is prose rather than a bare type name must fail loudly,
/// for the same reason the markdown extractor refuses a backticked qualifier:
/// a mis-read entry would satisfy neither side of the comparison and quietly
/// stop checking anything.
#[test]
#[should_panic(expected = "is not a bare type name")]
fn an_html_card_that_is_not_a_type_name_is_refused() {
    let doc = "<!-- generated:query-types -->\n\
               <div class=\"item\">knn (HNSW-served)</div>\n\
               <!-- /generated:query-types -->";
    documented(doc, "synthetic.html", "query-types");
}

/// Every `engine/crates/<path>` the docs site cites must exist.
///
/// The docs pages footer each section with a `Source · …` pointer, and twenty-one
/// of them named crates that have not existed under those paths for as long as
/// the workspace has been `xerj-*`-prefixed (`engine/crates/logs/src/parse.rs`,
/// `engine/crates/api/src/es_compat.rs`, `engine/crates/otlp/src/lib.rs`, …).
/// A reader following one lands nowhere, which is the same failure as a list
/// naming a query type that does not exist.
#[test]
fn every_source_pointer_in_the_docs_site_resolves() {
    fn html_files(dir: &Path, out: &mut Vec<PathBuf>) {
        for e in read_dir_or_panic(dir) {
            let p = e.path();
            if p.is_dir() {
                html_files(&p, out);
            } else if p.extension().is_some_and(|x| x == "html") {
                out.push(p);
            }
        }
    }

    let root = repo_root();
    let mut pages = Vec::new();
    html_files(&root.join("landing"), &mut pages);
    assert!(
        pages.len() > 20,
        "only {} pages found under landing/ — this check is reading nothing",
        pages.len()
    );

    let mut broken = Vec::new();
    for page in &pages {
        let text = read_surface_or_panic(page);
        for (idx, _) in text.match_indices("engine/crates/") {
            let tail: String = text[idx..]
                .chars()
                .take_while(|c| {
                    c.is_ascii_alphanumeric() || matches!(c, '/' | '.' | '_' | '-' | '*')
                })
                .collect();
            let cited = tail.trim_end_matches('.').to_string();
            // `engine/crates/*` and a bare `engine/crates/` are prose, not pointers.
            if cited.ends_with('*') || cited == "engine/crates/" {
                continue;
            }
            if !root.join(&cited).exists() {
                broken.push(format!(
                    "{} → {cited}",
                    page.strip_prefix(&root).unwrap_or(page).display()
                ));
            }
        }
    }
    broken.sort();
    broken.dedup();
    assert!(
        broken.is_empty(),
        "the docs site cites source paths that do not exist:\n  {}",
        broken.join("\n  ")
    );
}

/// The crate map is the same defect in a different list: it named eleven of the
/// sixteen crates, so an agent orienting from it never learned that
/// `xerj-autoindex` — the flagship feature — exists.
///
/// Checked by containment rather than by markers, because the map is a table
/// with a prose column: every `crates/*` workspace member must be named in it,
/// and every crate it names must still be a member.
#[test]
fn the_readme_crate_map_lists_every_workspace_crate() {
    let root = repo_root();
    let manifest =
        std::fs::read_to_string(root.join("engine/Cargo.toml")).expect("engine manifest");
    let readme_path = root.join("engine/README.md");
    let readme = std::fs::read_to_string(&readme_path).expect("engine README");

    let members: BTreeSet<String> = manifest
        .lines()
        .filter_map(|l| l.trim().strip_prefix("\"crates/"))
        .filter_map(|l| l.split('"').next())
        .map(str::to_string)
        .collect();
    assert!(
        members.len() > 10,
        "only {} workspace members parsed out of engine/Cargo.toml — the manifest \
         layout changed and this check is reading nothing",
        members.len()
    );

    let map_start = readme
        .find("### Crate Map")
        .expect("engine/README.md lost its `### Crate Map` heading");
    let map = &readme[map_start..];
    let map = &map[..map.find("\n### ").unwrap_or(map.len())];

    // Only the first cell of a table row counts. A crate merely *mentioned* in
    // the surrounding prose is not documented, and an earlier draft of this
    // test accepted exactly that — the guard has to be harder to satisfy than
    // the thing it guards.
    let rows: BTreeSet<String> = map
        .lines()
        .filter_map(|l| l.trim().strip_prefix("| `"))
        .filter_map(|l| l.split('`').next())
        .map(str::to_string)
        .collect();

    let undocumented: Vec<_> = members.difference(&rows).collect();
    assert!(
        undocumented.is_empty(),
        "engine/README.md's crate map has no row for {undocumented:?} — every crate \
         under engine/crates/ needs its own `| `<crate>` | purpose |` row"
    );

    let phantom: Vec<_> = rows
        .iter()
        .filter(|r| r.starts_with("xerj-") && !members.contains(*r))
        .collect();
    assert!(
        phantom.is_empty(),
        "engine/README.md's crate map has a row for {phantom:?}, which is not a workspace member"
    );
}

/// A backticked qualifier — the shape the old prose lists used, e.g.
/// `knn (HNSW-served unfiltered / exact filtered)` — must fail loudly rather
/// than be absorbed as a capability name that then never matches anything.
/// Accepted-and-ignored input is the failure mode this repo tracks in issue
/// #204; the docs guard must not add a documentation-flavoured instance of it.
#[test]
#[should_panic(expected = "is not a bare type name")]
fn a_backticked_qualifier_inside_a_region_is_refused() {
    let doc =
        "<!-- generated:query-types -->\n`knn (HNSW-served)`\n<!-- /generated:query-types -->";
    documented(doc, "synthetic", "query-types");
}

// ---------------------------------------------------------------------------
// Beyond the marked regions: the *examples*.
//
// The marked-region checks above only see a list that opted in. That left a
// hole big enough for the original defect to survive the first fix: while
// `landing/docs/queries.html` stopped advertising a `semantic_search` card,
// `landing/docs/playbooks/vector-search.html` went on publishing
// `{"semantic_search": {"field": …, "text": …}}` as *the* worked example for
// the flagship AI-native feature, and `landing/docs/migration-from-es.html`
// went on naming it in the migrator's "what works day one" list. Sent to a
// live instance, that body answers
// `unknown query type `semantic_search`` with a 400.
//
// So the guard now also reads the prose and the samples, over every published
// surface rather than the three files that carry markers.
// ---------------------------------------------------------------------------

/// Every published surface whose text is scanned for capability *claims*
/// (as opposed to the marked lists): the whole docs site, the agent-facing
/// text files, and the two repository documents an evaluator reads first.
fn doc_surfaces() -> Vec<PathBuf> {
    fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
        for e in read_dir_or_panic(dir) {
            let p = e.path();
            if p.is_dir() {
                walk(&p, out);
            } else {
                let keep = p.extension().is_some_and(|x| x == "html")
                    || p.file_name()
                        .and_then(|n| n.to_str())
                        .is_some_and(|n| n.starts_with("llms") && n.ends_with(".txt"));
                if keep {
                    out.push(p);
                }
            }
        }
    }

    let root = repo_root();
    let mut files = Vec::new();
    walk(&root.join("landing"), &mut files);
    files.push(root.join("engine/README.md"));
    files.push(root.join("ROADMAP.md"));
    files.sort();
    assert!(
        files.len() > 20,
        "only {} published surfaces found — this check is reading nothing",
        files.len()
    );
    files
}

fn known_query_types() -> BTreeSet<String> {
    xerj_query::parser::SUPPORTED_QUERY_TYPES
        .iter()
        .chain(xerj_query::parser::REJECTED_QUERY_TYPES)
        .map(|s| s.to_string())
        .collect()
}

/// `true` when the byte at `at` starts a token — i.e. it is not preceded by a
/// character that would make it part of a longer identifier. Keeps
/// `xerj_semantic_search` (a real MCP tool) from reading as `semantic_search`
/// (a query type that has never existed).
fn at_token_start(text: &str, at: usize) -> bool {
    text[..at]
        .chars()
        .next_back()
        .is_none_or(|c| !c.is_ascii_alphanumeric() && c != '_')
}

fn token_ends_at(text: &str, end: usize) -> bool {
    text[end..]
        .chars()
        .next()
        .is_none_or(|c| !c.is_ascii_alphanumeric() && c != '_')
}

fn line_of(text: &str, byte: usize) -> usize {
    text[..byte].matches('\n').count() + 1
}

/// Walk `text` from `from`, skipping whitespace, and require it to spell out
/// `wanted` in order. Returns the byte offset just past the last character, or
/// `None` the moment the text diverges.
fn expect_seq(text: &str, from: usize, wanted: &[char]) -> Option<usize> {
    let mut want = wanted.iter();
    let mut next = want.next()?;
    for (off, ch) in text[from..].char_indices() {
        if ch.is_whitespace() {
            continue;
        }
        if ch != *next {
            return None;
        }
        match want.next() {
            Some(n) => next = n,
            None => return Some(from + off + ch.len_utf8()),
        }
    }
    None
}

/// Query-type names the docs have published that the parser has never
/// dispatched. `semantic_search` (the real clause is `semantic`) and `boosted`
/// (the real clause is `boosting`) both shipped on the docs site; a reader who
/// copied either got a 400.
///
/// This is a denylist rather than a general rule because prose is prose: there
/// is no position in an English sentence that reliably marks a word as a
/// capability claim. It is kept honest by
/// [`the_phantom_list_only_holds_names_the_parser_really_lacks`], which retires
/// an entry the moment the parser grows it.
const PHANTOM_QUERY_TYPES: &[&str] = &["boosted", "semantic_search"];

/// If XERJ ever implements one of these, the denylist must shrink, not silently
/// forbid documenting a real feature.
#[test]
fn the_phantom_list_only_holds_names_the_parser_really_lacks() {
    let known = known_query_types();
    let wrong: Vec<_> = PHANTOM_QUERY_TYPES
        .iter()
        .filter(|p| known.contains(**p))
        .collect();
    assert!(
        wrong.is_empty(),
        "{wrong:?} are now dispatched by the parser — remove them from \
         PHANTOM_QUERY_TYPES and document them instead of banning them"
    );
}

/// No published surface may name a query type that does not exist — not in a
/// list, not in a sentence, not in a copy-pasteable example.
#[test]
fn no_published_surface_names_a_phantom_query_type() {
    let root = repo_root();
    let mut hits = Vec::new();

    for file in doc_surfaces() {
        let text = read_surface_or_panic(&file);
        for phantom in PHANTOM_QUERY_TYPES {
            for (at, _) in text.match_indices(phantom) {
                if at_token_start(&text, at) && token_ends_at(&text, at + phantom.len()) {
                    hits.push(format!(
                        "{}:{} names `{phantom}`",
                        file.strip_prefix(&root).unwrap_or(&file).display(),
                        line_of(&text, at)
                    ));
                }
            }
        }
    }

    hits.sort();
    assert!(
        hits.is_empty(),
        "the published docs name query types the parser has never had:\n  {}\n\
         The real clauses are `semantic` (field + query, k defaults to 10) and \
         `boosting`. A reader who copies a phantom gets `unknown query type`.",
        hits.join("\n  ")
    );
}

/// Anything in *query position* in a published sample must be a real query
/// type. A clause sitting directly under a `"query": { … }` object is a query
/// type by construction — that is the one place in an ES request body where the
/// key's meaning is unambiguous — so it can be checked without a denylist.
#[test]
fn every_query_clause_in_a_published_sample_is_a_real_query_type() {
    let root = repo_root();
    let known = known_query_types();
    let mut bad = Vec::new();
    let mut checked = 0usize;

    for file in doc_surfaces() {
        let text = read_surface_or_panic(&file);
        for (at, _) in text.match_indices("\"query\"") {
            // `"query"` `:` `{` `"<name>"` — anything else (a string value, as
            // in `match` / `query_string` / `semantic`, or an array) is not a
            // clause position and is skipped.
            let Some(from) = expect_seq(&text, at + "\"query\"".len(), &[':', '{', '"']) else {
                continue;
            };
            let Some(len) = text[from..].find('"') else {
                continue;
            };
            let name = &text[from..from + len];
            if name.is_empty()
                || !name
                    .chars()
                    .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
            {
                continue; // not an ES type name — a doc field, a label, prose
            }
            checked += 1;
            if !known.contains(name) {
                bad.push(format!(
                    "{}:{} uses `{name}` in query position",
                    file.strip_prefix(&root).unwrap_or(&file).display(),
                    line_of(&text, at)
                ));
            }
        }
    }

    assert!(
        checked > 20,
        "only {checked} query clauses found across the docs — this check is reading nothing"
    );
    bad.sort();
    bad.dedup();
    assert!(
        bad.is_empty(),
        "published request samples put a name in query position that \
         `parse_query` does not dispatch:\n  {}",
        bad.join("\n  ")
    );
}

/// Published *counts* drift exactly like published lists, and were drifting in
/// three different directions at once: `landing/docs/migration-from-es.html`
/// said 32 query types, `landing/pricing/index.html` and
/// `landing/demo/index.html` said 38, and the parser dispatches 50. So a number
/// a reader is expected to trust now lives in a marked region too.
///
/// Unlike the list regions, a file may carry the same count section more than
/// once (the pricing page prints the figure in a plan bullet and again in the
/// comparison table); every occurrence is checked.
///
/// `ROADMAP.md` is markdown rather than HTML, and was originally left out —
/// which re-created the defect inside its own fix: it published `50 query
/// types` and `62 aggregation types` as hand-typed literals, so adding query
/// type 51 would have left it silently saying 50 with every test green.
/// HTML comments are invisible in rendered markdown, so the same marker works
/// there unchanged.
const COUNT_DOCS: &[&str] = &[
    "landing/docs/migration-from-es.html",
    "landing/pricing/index.html",
    "landing/demo/index.html",
    "ROADMAP.md",
];

/// The count sections and where each number comes from.
fn count_source_of_truth(section: &str) -> usize {
    match section {
        "query-type-count" => xerj_query::parser::SUPPORTED_QUERY_TYPES.len(),
        "rejected-query-type-count" => xerj_query::parser::REJECTED_QUERY_TYPES.len(),
        "agg-type-count" => xerj_engine::aggs::SUPPORTED_AGG_TYPES.len(),
        other => panic!("no source of truth wired up for count section `{other}`"),
    }
}

const COUNT_SECTIONS: &[&str] = &[
    "query-type-count",
    "rejected-query-type-count",
    "agg-type-count",
];

#[test]
fn published_capability_counts_match_the_constants() {
    let root = repo_root();
    let mut seen = 0usize;

    for rel in COUNT_DOCS {
        let doc = std::fs::read_to_string(root.join(rel))
            .unwrap_or_else(|e| panic!("cannot read {rel}: {e}"));

        for section in COUNT_SECTIONS {
            let open = format!("<!-- generated:{section} -->");
            let close = format!("<!-- /generated:{section} -->");
            for (at, _) in doc.match_indices(&open) {
                let from = at + open.len();
                let len = doc[from..].find(&close).unwrap_or_else(|| {
                    panic!(
                        "{rel} opens `{open}` at line {} but never closes it",
                        line_of(&doc, at)
                    )
                });
                let raw = doc[from..from + len].trim();
                let published: usize = raw.parse().unwrap_or_else(|_| {
                    panic!(
                        "{rel} section `{section}` holds `{raw}`, which is not a number. \
                         The region is machine-checked and may hold only the count."
                    )
                });
                assert_eq!(
                    published,
                    count_source_of_truth(section),
                    "{rel}:{} publishes {published} for `{section}`; the source has {}",
                    line_of(&doc, at),
                    count_source_of_truth(section)
                );
                seen += 1;
            }
        }
    }

    assert!(
        seen >= 9,
        "only {seen} marked counts found across {COUNT_DOCS:?} — a page dropped its \
         markers and its number is now unchecked"
    );
}

// ---------------------------------------------------------------------------
// Release freshness (issue #298).
//
// Issue #298 pins ROADMAP.md as the authoritative "where the project is
// going" document and advertises that parts of it are machine-checked. The
// checks above pin the capability *counts* — none of them noticed that the
// `release: cut 1.0.0-rc.16` commit moved CHANGELOG.md's `[Unreleased]`
// section under a 1.0.0-rc.16 heading while ROADMAP.md went on describing
// rc.16 as the *next* release: five merged PRs listed as "in flight", four
// closed issues listed as open gate items, and a review line naming rc.15 as
// the release the statuses were verified against. Every test in this file was
// green the whole time.
//
// So the release cut itself is now inside the checked surface: cutting a
// release (the CHANGELOG heading) without rolling ROADMAP.md forward fails
// the build, exactly like adding a query type without updating the lists.
// ---------------------------------------------------------------------------

/// A release version as XERJ writes them (`1.0.0-rc.16`, one day `1.0.0`),
/// as a totally ordered tuple. An `-rc.N` sorts before the bare release it
/// leads up to, so the final component is the rc number or `u64::MAX`.
///
/// Trailing decorations after whitespace (`v1.0.0 (GA)`) are ignored; a
/// leading `v` is stripped. Returns `None` for anything that is not a
/// three-part version, so callers can keep scanning past prose.
fn parse_release_version(text: &str) -> Option<(u64, u64, u64, u64)> {
    let token = text
        .trim()
        .trim_start_matches('v')
        .split_whitespace()
        .next()?;
    let (core, rc) = match token.split_once("-rc.") {
        Some((core, n)) => (core, n.parse().ok()?),
        None => (token, u64::MAX),
    };
    let mut parts = core.split('.').map(str::parse::<u64>);
    let (maj, min, pat) = (
        parts.next()?.ok()?,
        parts.next()?.ok()?,
        parts.next()?.ok()?,
    );
    if parts.next().is_some() {
        return None;
    }
    Some((maj, min, pat, rc))
}

/// The most recently cut release: the first `## [<version>]` heading in
/// CHANGELOG.md whose bracket content parses as a version. `[Unreleased]`
/// and prose headings are skipped, so the changelog may carry a pending
/// section above the latest cut.
fn latest_cut_release(changelog: &str) -> (String, (u64, u64, u64, u64)) {
    for line in changelog.lines() {
        let Some(rest) = line.strip_prefix("## [") else {
            continue;
        };
        let Some(name) = rest.split(']').next() else {
            continue;
        };
        if let Some(version) = parse_release_version(name) {
            return (name.to_string(), version);
        }
    }
    panic!(
        "CHANGELOG.md has no `## [<version>]` release heading — the release \
         history is the reference the roadmap-freshness checks compare \
         against, and it cannot be empty"
    );
}

/// The heading that opens ROADMAP.md's next-release section. The link text is
/// the version; the link target is the milestone.
const NEXT_RELEASE_MARKER: &str = "## Next release — [";

#[test]
fn the_roadmap_next_release_has_not_already_been_cut() {
    let root = repo_root();
    let changelog = read_surface_or_panic(&root.join("CHANGELOG.md"));
    let roadmap = read_surface_or_panic(&root.join("ROADMAP.md"));
    let (cut_name, cut) = latest_cut_release(&changelog);

    let at = roadmap.find(NEXT_RELEASE_MARKER).unwrap_or_else(|| {
        panic!(
            "ROADMAP.md has no `{NEXT_RELEASE_MARKER}…]` heading. Issue #298 \
             points readers at that section for the short-term roadmap; if the \
             section was renamed (say, after 1.0.0 ships), update this test \
             rather than leaving release freshness unchecked."
        )
    });
    let link_text = roadmap[at + NEXT_RELEASE_MARKER.len()..]
        .split(']')
        .next()
        .expect("split always yields a first piece");
    let next = parse_release_version(link_text).unwrap_or_else(|| {
        panic!(
            "ROADMAP.md line {} names `{link_text}` as the next release, which \
             does not parse as a version",
            line_of(&roadmap, at)
        )
    });

    assert!(
        next > cut,
        "ROADMAP.md line {} still advertises `{link_text}` as the next \
         release, but CHANGELOG.md records `{cut_name}` as already cut. The \
         release cut did not roll the roadmap forward, so the section issue \
         #298 calls the short-term roadmap describes the past: its \"in \
         flight\" PRs have merged and its open defects belong to the next \
         milestone. Re-review ROADMAP.md against the new release and point \
         the heading at the next milestone.",
        line_of(&roadmap, at)
    );
}

#[test]
fn the_roadmap_review_line_names_the_latest_cut_release() {
    let root = repo_root();
    let changelog = read_surface_or_panic(&root.join("CHANGELOG.md"));
    let roadmap = read_surface_or_panic(&root.join("ROADMAP.md"));
    let (cut_name, _) = latest_cut_release(&changelog);

    let marker = "Last reviewed:";
    let at = roadmap.find(marker).unwrap_or_else(|| {
        panic!(
            "ROADMAP.md has no `{marker}` line — the review line is what lets \
             a reader date the statuses; removing it removes the honesty \
             anchor issue #298 promises"
        )
    });
    let line_end = roadmap[at..].find('\n').map_or(roadmap.len(), |n| at + n);
    let review_line = &roadmap[at..line_end];

    let against = "(against `";
    let from = review_line.find(against).unwrap_or_else(|| {
        panic!(
            "ROADMAP.md's review line does not say which release the statuses \
             were verified against — expected `{against}v…\\`` on line {}",
            line_of(&roadmap, at)
        )
    }) + against.len();
    let reviewed = review_line[from..]
        .split('`')
        .next()
        .expect("split always yields a first piece");

    assert_eq!(
        reviewed.trim_start_matches('v'),
        cut_name,
        "ROADMAP.md line {} says the statuses were last verified against \
         `{reviewed}`, but the latest cut release in CHANGELOG.md is \
         `{cut_name}`. A cut release the roadmap has not been re-reviewed \
         against is exactly the drift issue #298 says cannot happen — \
         re-verify the statuses and update the review line.",
        line_of(&roadmap, at)
    );
}

//! Release-notes drift guard: a shipped doc may not advertise unshipped things
//! (issue #474).
//!
//! A file that ships inside the release tag may not describe a capability as
//! arriving in a future release. Such a sentence cannot be checked at review
//! time and is wrong by construction afterwards: either the feature has not
//! landed, and a reader of the tag is told to run something that does not
//! exist, or it has landed, and the text is stale.
//!
//! Both of these were published — the second in a tagged release, the first
//! on `main` — which is why this exists:
//!
//! - `README.md` and `landing/llms.txt` documented `xerj feedback` as "on
//!   `main` now; ships in the next release" while it sat in an unmerged PR, so
//!   the release's own community CTA opened with a command that exits
//!   `unknown argument` — aimed at exactly the agents the page recruits.
//!
//! - `landing/llms.txt` and `landing/llms-full.txt` said `--port` "is on
//!   `main` and ships in the next release", and `llms.txt` that `xerj --help`
//!   lists it "on a `main` build only". It had shipped in v1.0.0-rc.17. An
//!   agent hitting a port collision — the scenario that paragraph exists for —
//!   was told to hand-write a three-key TOML file while holding a binary that
//!   takes `--port 9300`.
//!
//! Write instead what is true of *this* binary, anchored to a version rather
//! than to the moment of reading — "since v1.0.0-rc.17", or "v1.0.0-rc.17 does
//! not have it". "yet", "now", "today", "currently" and "in review" all
//! expire; a version number does not.
//!
//! `CHANGELOG.md` is exempt: an `[Unreleased]` section is exactly where
//! forward-looking statements belong.
//!
//! This narrows the class rather than closing it — it is a list of known
//! phrasings, not a rule about meaning. Issue #474 tracks the API-backed
//! checks that would do more.

use std::path::{Path, PathBuf};

/// Repository root, derived from this crate's manifest directory
/// (`<repo>/engine/crates/xerj-engine`).
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("crate manifest dir must be <repo>/engine/crates/xerj-engine")
        .to_path_buf()
}

/// The user-facing files that ship inside the release tag and are read by
/// someone holding a released binary.
///
/// `CHANGELOG.md` is deliberately absent — see the module docs.
const SHIPPED_DOCS: &[&str] = &[
    "README.md",
    "landing/llms.txt",
    "landing/llms-full.txt",
    "ROADMAP.md",
];

/// Phrases that promise a future release.
///
/// Matched case-insensitively against the whole line. Kept literal and short:
/// this gate is worth having only if a contributor can read a failure and know
/// immediately what to write instead, and only if it does not fire on prose
/// that merely mentions a version.
const FUTURE_RELEASE_PHRASES: &[&str] = &[
    "ships in the next release",
    "ships next release",
    "in the next release",
    "on `main` now",
    "on main now",
    "is on `main` and ships",
    "is on main and ships",
    "not yet in a tagged release",
    "on a `main` build only",
    "on a main build only",
];

/// Read a file under the repo root, or fail the test naming it.
fn read(root: &Path, rel: &str) -> String {
    let path = root.join(rel);
    std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read {} for the docs drift gate: {e}",
            path.display()
        )
    })
}

/// A shipped doc must not tell the reader that something arrives later.
///
/// This is the assertion that would have caught both `xerj feedback` and
/// `--port`, on the commit that introduced each.
#[test]
fn no_shipped_doc_promises_a_future_release() {
    let root = repo_root();
    let mut offences: Vec<String> = Vec::new();

    for rel in SHIPPED_DOCS {
        let body = read(&root, rel);
        for (i, line) in body.lines().enumerate() {
            let lowered = line.to_lowercase();
            for phrase in FUTURE_RELEASE_PHRASES {
                if lowered.contains(phrase) {
                    offences.push(format!(
                        "{rel}:{} promises a future release ({phrase:?}):\n    {}",
                        i + 1,
                        line.trim()
                    ));
                }
            }
        }
    }

    assert!(
        offences.is_empty(),
        "A file that ships inside the release tag describes a capability as arriving \
         in a future release. That sentence is wrong by construction the moment the tag \
         is cut: either the feature has not landed and a reader of this tag is told to \
         run something that does not exist, or it has landed and this text is stale. \
         Both shipped in the rc.18 cycle (issue #474).\n\n\
         Write what is true of THIS binary instead, anchored to a version rather than \
         to the moment of reading — \"since v1.0.0-rc.17\", or \"v1.0.0-rc.17 does not \
         have it\". \"yet\", \"now\", \"today\" and \"in review\" all expire; a version \
         number does not. \
         Forward-looking notes belong in CHANGELOG's [Unreleased] section, which this \
         gate does not check.\n\n{}",
        offences.join("\n")
    );
}

/// The phrase list has to actually match the text that shipped, or this gate
/// is decoration.
///
/// Each sentence below really was published, and the list must keep catching
/// every one of them. Gutting the list fails here.
///
/// What this does NOT do, measured rather than assumed: it does not make every
/// individual entry unremovable. The entries overlap — `"in the next release"`
/// subsumes `"ships in the next release"` — and these pins are sentences,
/// while the sweep matches per line, so a sentence can stay caught by one
/// entry after another that covered a different *line* of it is deleted.
/// Pruning each entry in turn, **8 of the 10 pass silently**; only
/// `"not yet in a tagged release"` and ``"on a `main` build only"`` are the
/// sole cover for something pinned. So this test stops the list being emptied,
/// not the list being thinned, and someone who deletes a redundant entry can
/// reopen the exact wording of a past defect with CI green.
///
/// Making it stronger means pinning the real pre-fix *lines* rather than
/// reconstructed sentences, so entry necessity can be checked at the
/// granularity the sweep actually uses. That is worth doing and is not done
/// here; #474 carries it with the other gaps.
#[test]
fn the_phrase_list_catches_the_sentences_that_caused_this_gate() {
    // `landing/llms.txt`, before the fix — the `--port` claim, false for a
    // full release by the time it was found.
    let port_claim = "A `--port <PORT>` flag (which also claims `PORT+1` for native REST \
                      and `PORT+2` for gRPC) is on `main` and ships in the next release \
                      — `xerj --help` tells you which binary you have";
    // `README.md`, before the fix — the community CTA's headline command.
    let feedback_claim = "# The one-command path (on `main` now; ships in the next release):";
    // `landing/llms.txt`, before the fix — the `--help` availability claim.
    let help_claim = "That block works on every released binary. On a `main` build only, \
                      `xerj --help` also lists a `--port` flag";
    // `README.md`, before the fix — the same CTA in the contributing section.
    let contributing_claim = "The baseline contribution is one short field report: \
                              `xerj feedback --open-pr` (on `main` now, ships next release) \
                              or, today, a plain `gh pr create` adding one markdown file";
    // `landing/llms-full.txt`, before the fix — the same `--port` availability
    // claim as `port_claim`, published with `main` unbackticked. This is why the
    // list carries backtick-free twins: the sentence really did go out both ways.
    let full_port_claim =
        "each other), is on main and ships in the next release; `xerj --help` tells you";
    // `landing/llms.txt`, before the fix — the defence-by-analogy that pointed
    // at the `--port` paragraph as the model, and so seeded the second defect.
    let analogy_claim = "documented here the way the `--port` flag is: available on `main`, \
                         not yet in a tagged release; `xerj --help` is the authority for the \
                         binary in front of you";

    for (label, text) in [
        ("--port availability", port_claim),
        ("xerj feedback CTA", feedback_claim),
        ("--help availability", help_claim),
        ("contributing-section CTA", contributing_claim),
        ("defence-by-analogy", analogy_claim),
        ("--port availability, no backticks", full_port_claim),
    ] {
        let lowered = text.to_lowercase();
        assert!(
            FUTURE_RELEASE_PHRASES.iter().any(|p| lowered.contains(p)),
            "FUTURE_RELEASE_PHRASES no longer catches the {label} sentence that caused \
             issue #474. Pruning this list re-opens the defect it exists to close:\n    {text}"
        );
    }

    // "Some phrase still matches" is too weak on its own: the pinned sentences
    // overlap, so a subset of the list can still satisfy every pin while the
    // rest become free to delete — and with them, free to reintroduce. Every
    // entry must therefore at least still match something: it has to catch at
    // least one pinned sentence. (That is a floor, not a lock — this assert
    // cannot fire on a deletion, only on an entry that matches nothing.) An entry that catches nothing is either dead weight or a
    // phrasing whose example sentence went missing, and both are worth a
    // failure rather than silent rot.
    let corpus: String = [
        port_claim,
        feedback_claim,
        help_claim,
        contributing_claim,
        analogy_claim,
        full_port_claim,
    ]
    .join("\n")
    .to_lowercase();
    // The list carries a backtick-free twin of each phrase that shipped with
    // backticks, because the same sentence really did get published both ways —
    // `full_port_claim` above is the unbackticked form, pinned like any other.
    // The remaining twins have no separately published sentence of their own,
    // so they are justified against the corpus with backticks stripped rather
    // than by inventing prose nobody wrote.
    let corpus_plain = corpus.replace('`', "");
    let idle: Vec<&str> = FUTURE_RELEASE_PHRASES
        .iter()
        .copied()
        .filter(|p| !corpus.contains(p) && !corpus_plain.contains(p))
        .collect();
    assert!(
        idle.is_empty(),
        "these entries in FUTURE_RELEASE_PHRASES match none of the sentences pinned above, \
         so nothing proves they still work: {idle:?}\n\n\
         Either add the real sentence each one came from to the pins, or drop the entry. \
         A phrase with no example behind it is how this list rots back into a shape that \
         lets the rc.18 wording through again (issue #474)."
    );
}

/// The file list has to stay covered, or the gate is one deleted line from
/// inert.
///
/// Without this test, deleting the single line `"README.md",` makes the whole
/// pre-fix README pass the sweep — every offence in it, including the
/// `xerj feedback` block that opened the release's own community CTA, stops
/// being seen.
#[test]
fn the_file_list_still_covers_every_doc_that_ships_in_the_tag() {
    for required in [
        "README.md",
        "landing/llms.txt",
        "landing/llms-full.txt",
        "ROADMAP.md",
    ] {
        assert!(
            SHIPPED_DOCS.contains(&required),
            "{required} was dropped from SHIPPED_DOCS. Every file here ships inside the \
             release tag and is read by someone holding a released binary, so removing one \
             silently disables this gate for it — which is how a reader ends up back at a \
             command that does not exist (issue #474). Widening the list is welcome; \
             narrowing it is the defect."
        );
    }
}

// A phrase broad enough to hit ordinary prose is caught by the sweep itself,
// not by a separate canary.
//
// There was once an `ordinary_version_prose_is_not_an_offence` test here,
// holding hand-written example sentences the phrase list had to leave alone.
// It was redundant: adding `"release"` to `FUTURE_RELEASE_PHRASES` fails
// `no_shipped_doc_promises_a_future_release`, because that test reads the four
// real documents; the canary, holding a handful of hand-picked sentences,
// passed the same change. The sweep is the stronger false-positive detector
// and it comes for free — it measures the actual corpus rather than a sample
// somebody has to keep honest.
//
// Kept as a comment because the lesson is about what not to add back.

//! Issue #948: a memory-pressure drain must flush every loaded index and
//! release its rebuildable caches WITHOUT closing anything — the parent RSS
//! breaker now requests this drain when it engages, because a breaker that
//! only rejects (429) frees nothing and a cache-heavy ingest never finishes
//! under a memory cap.
//!
//! The drain is the `close_index` (#463) flush+release pair applied to every
//! loaded index at once, minus the closed flag. These tests pin the two
//! properties that pair must keep: data safety (flush-first, so
//! memtable-resident docs survive) and service continuity (the index stays
//! loaded and queryable, reads re-hydrate from disk).

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn count_all(engine: &Engine, name: &str) -> u64 {
    let idx = engine.get_index(name).expect("get index");
    let req = parse_request(&json!({ "query": { "match_all": {} }, "size": 0, "from": 0 }))
        .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

async fn seed(engine: &Engine, name: &str, n: usize) {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index(name, schema).expect("create");
    let idx = engine.get_index(name).expect("get");
    for i in 0..n {
        idx.index_document(
            Some(format!("d{i}")),
            json!({ "body": format!("document number {i}") }),
        )
        .await
        .expect("index");
    }
}

/// Run a size>0 search so the per-segment caches actually hydrate.
async fn hydrate(engine: &Engine, name: &str) -> u64 {
    let idx = engine.get_index(name).expect("get index");
    let req = parse_request(&json!({ "query": { "match": { "body": "document" } }, "size": 25 }))
        .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// The drain releases every loaded index's caches and keeps the index in
/// service: loaded, not closed, queryable, lossless. FAIL-BEFORE: with the
/// `idx.release_memory()` call inside `drain_rebuildable_memory` reverted,
/// `total_cache_entries == 0` fails.
#[tokio::test]
async fn drain_releases_caches_and_keeps_indexes_in_service() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "docs", 50).await;
    engine.get_index("docs").unwrap().refresh().await.unwrap();

    hydrate(&engine, "docs").await;
    let cached_before = engine.get_index("docs").unwrap().total_cache_entries();
    assert!(
        cached_before > 0,
        "a query should have hydrated the caches, got {cached_before}"
    );

    let drained = engine.drain_rebuildable_memory().await;
    assert_eq!(drained, 1, "one loaded index must be drained");
    assert!(
        engine.is_index_loaded("docs"),
        "a drain never closes or unloads an index"
    );
    assert!(
        !engine.closed_indices.contains_key("docs"),
        "a drain must not mark the index closed"
    );
    let cached_after = engine.get_index("docs").unwrap().total_cache_entries();
    assert_eq!(
        cached_after, 0,
        "#948: the drain must release resident caches (was {cached_before}, now {cached_after})"
    );
    // Reads still work — caches re-hydrate from disk on demand.
    assert_eq!(count_all(&engine, "docs").await, 50);
}

/// Data-safety: documents still in the memtable (never refreshed/flushed)
/// must survive the drain — it flushes FIRST, exactly like `close_index`
/// (#463). Guards against a memory win that silently drops unflushed writes.
#[tokio::test]
async fn drain_flushes_so_unrefreshed_docs_survive() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "docs", 30).await; // NO refresh — docs sit in the memtable/WAL

    let drained = engine.drain_rebuildable_memory().await;
    assert_eq!(drained, 1);
    assert_eq!(
        engine.get_index("docs").unwrap().memtable_bytes(),
        0,
        "the drain must leave the memtable empty"
    );
    assert_eq!(
        count_all(&engine, "docs").await,
        30,
        "#948: drain must flush before releasing — no doc may be lost"
    );
}

/// A closed index is skipped (its caches were already released by
/// `close_index`), and its existence must not abort the drain for the rest.
#[tokio::test]
async fn drain_skips_closed_indexes_and_drains_the_rest() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine, "open-docs", 10).await;
    seed(&engine, "closed-docs", 10).await;
    engine.close_index("closed-docs").await.expect("close");

    let drained = engine.drain_rebuildable_memory().await;
    assert_eq!(
        drained, 1,
        "only the loaded-and-open index counts; closed caches were freed at close"
    );
    assert_eq!(count_all(&engine, "open-docs").await, 10);
}

/// #948 — the storage memtable must not retain one parsed `Arc<Value>` per
/// explicit-id write forever.
///
/// The engine flush path drains the FTS memtable and builds its
/// `DrainedMemtable` from THAT; `IndexStore::memtable_shards` (pushed by
/// every `store.index()` / `index_batch()` — the per-doc route explicit-id
/// bulk takes) was never drained on that path, so every flush left the full
/// parsed document trees resident for the life of the process.  Measured as
/// the dominant un-attributed at-rest RSS on mailbox-shaped bulk loads
/// (~2.4-3.1x source bytes).  `prune_published_memtable`, run at the end of
/// every successful `finalize_flush_with_publisher`, drops them once the
/// version map repoints at the published segment.
///
/// FAIL-BEFORE: with the `prune_published_memtable()` call in
/// `finalize_flush_with_publisher` reverted (but this test and the accessor
/// kept), `resident == 0` fails — entries survive the flush.
#[tokio::test]
async fn flush_prunes_published_storage_memtable_entries() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    // seed() writes with an explicit id → the per-doc `store.index()` path
    // that pushes a MemEntry per doc.
    seed(&engine, "docs", 40).await;
    let idx = engine.get_index("docs").unwrap();
    let before = idx.resident_memtable_entries();
    assert!(
        before >= 40,
        "explicit-id writes must land in the storage memtable, got {before}"
    );

    idx.refresh().await.expect("refresh");

    // refresh → flush is async (spawned finalize); poll for completion.
    let mut resident = before;
    for _ in 0..200 {
        resident = idx.resident_memtable_entries();
        if resident == 0 {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(25)).await;
    }
    assert_eq!(
        resident, 0,
        "#948: a completed flush must prune the storage memtable entries it \
         published (started at {before})"
    );

    // And the prune dropped nothing the index still needs: all docs
    // readable, all durable.
    assert_eq!(count_all(&engine, "docs").await, 40);
}

//! Regression tests for the dynamic-mapping `doc_values` default.
//!
//! ES's dynamic mapping gives an inferred string field a `text` parent with a
//! `keyword` sub-field, and only the sub-field carries doc-values. The
//! engine's `es_properties_to_fields` already applies that default to a
//! DECLARED `text` mapping, but the dynamic-discovery path builds the parent
//! through `FieldConfig::new`, whose `FieldOptions` default the flag to
//! `true`. With the column present, the flushed segment answered a `terms`
//! query from the column's whole raw values while the memtable scan answered
//! per analyzed token — so the same query matched before `_refresh` and
//! returned nothing after it.

use std::collections::BTreeSet;
use std::sync::Arc;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// What `POST /_search` runs: a real page of hits.
async fn search(idx: &Index, q: &Value) -> (u64, BTreeSet<String>) {
    let req = parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request");
    let r = idx.search(&req).await.unwrap();
    (r.total.value, r.hits.iter().map(|h| h.id.clone()).collect())
}

/// What `POST /_count` runs: `size: 0`, total only.
async fn count_total(idx: &Index, q: &Value) -> u64 {
    let req = parse_request(&json!({ "query": q, "size": 0, "from": 0 })).expect("parse_request");
    idx.search(&req).await.unwrap().total.value
}

/// `_count` must answer the same question `_search` answers — the count lane
/// takes a different shortcut on both sides of the flush.
async fn assert_count_agrees_with_search(idx: &Index, q: &Value) {
    let count = count_total(idx, q).await;
    let (total, hits) = search(idx, q).await;
    assert_eq!(
        count, total,
        "_count total {count} != _search total {total}"
    );
    assert_eq!(
        count,
        hits.len() as u64,
        "_count says {count} but _search materialises {} document(s)",
        hits.len()
    );
}

fn set(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

/// The inferred schema mirrors ES's dynamic mapping: `text` parent with the
/// flag OFF, `keyword` sub-field with its own doc-values, and a numeric
/// sibling keeping theirs.
#[tokio::test]
async fn inferred_text_has_no_doc_values_but_its_keyword_subfield_and_numerics_do() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("dyn_schema", Schema::empty()).unwrap();
    let idx = engine.get_index("dyn_schema").unwrap();
    idx.index_document(
        Some("d1".into()),
        json!({"text": "quick brown fox", "n": 42}),
    )
    .await
    .unwrap();

    let schema = idx.schema().await;
    let text = schema
        .fields
        .iter()
        .find(|f| f.name == "text")
        .expect("text field");
    assert!(matches!(text.field_type, FieldType::Text));
    assert!(
        !text.options.doc_values,
        "ES dynamic mapping puts doc-values on the keyword sub-field, \
         not on the text parent"
    );
    let kw = text
        .fields
        .iter()
        .find(|f| f.name == "keyword")
        .expect("keyword sub-field");
    assert!(matches!(kw.field_type, FieldType::Keyword));
    assert!(kw.options.doc_values);
    assert_eq!(kw.options.ignore_above, Some(256));
    let n = schema
        .fields
        .iter()
        .find(|f| f.name == "n")
        .expect("n field");
    assert!(
        n.options.doc_values,
        "numeric doc-values default is unchanged"
    );
}

/// A `terms` query on a dynamically mapped text field answers the analyzed
/// tokens before and after the flush, with `_count` agreeing at both ends,
/// and the `.keyword` sub-field keeps answering the whole value.
#[tokio::test]
async fn dynamic_text_terms_matches_tokens_flush_invariantly() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("dyn_terms", Schema::empty()).unwrap();
    let idx: Arc<Index> = engine.get_index("dyn_terms").unwrap();
    for (id, text) in [("d1", "quick brown fox"), ("d2", "lazy dog")] {
        idx.index_document(Some(id.into()), json!({"text": text}))
            .await
            .unwrap();
    }

    let token_query = json!({"terms": {"text": ["brown"]}});
    let (pre_total, pre_hits) = search(&idx, &token_query).await;
    assert_eq!(pre_hits, set(&["d1"]), "pre-flush (memtable) token match");
    assert_eq!(pre_total, 1);
    assert_count_agrees_with_search(&idx, &token_query).await;

    idx.flush().await.unwrap();

    let (post_total, post_hits) = search(&idx, &token_query).await;
    assert_eq!(
        post_hits, pre_hits,
        "terms on a dynamically mapped text field changed at flush"
    );
    assert_eq!(post_total, pre_total, "hit total changed at flush");
    assert_count_agrees_with_search(&idx, &token_query).await;

    let keyword_query = json!({"term": {"text.keyword": "quick brown fox"}});
    assert_eq!(search(&idx, &keyword_query).await.1, set(&["d1"]));
}

//! `engine.{flush,merge,search}_workers` must reach the pools they name.
//!
//! Before #240 all three were declared, defaulted, documented and validated in
//! `xerj-common::config` and read by **nothing**. Setting
//! `engine.search_workers = 2` to keep XERJ off a laptop's cores changed no
//! pool and produced no warning — the accepted-and-ignored class from #204.
//!
//! Search segment fan-out runs on rayon's *global* pool, which rayon sizes to
//! every core on first use unless something builds it first. That makes the
//! global pool's width the observable for `search_workers`, and it is
//! process-global state — hence a test file of its own, since each Rust
//! integration-test file is its own binary.

use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_engine::pools;
use xerj_engine::Engine;

#[tokio::test]
async fn search_workers_sizes_the_pool_search_actually_runs_on() {
    let requested = 2;
    let machine = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap();
    assert!(
        machine > requested,
        "this assertion is only meaningful on a machine with more cores than we ask for \
         (machine={machine})"
    );

    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config.engine.search_workers = requested;
    config.engine.merge_workers = 3;
    config.engine.flush_workers = 5;
    let _engine = Engine::new(config).expect("engine::new");

    // Pre-fix this reported `machine` (32 on the dev box): the config value was
    // never read, so search fan-out took every core no matter what was asked.
    assert_eq!(
        rayon::current_num_threads(),
        requested,
        "engine.search_workers must size the global pool that search fans out on"
    );

    let sizing = pools::sizing();
    assert_eq!(sizing.search, requested);
    assert_eq!(
        sizing.merge, 3,
        "engine.merge_workers must reach merge_pool"
    );
    assert_eq!(
        sizing.flush_finalize, 5,
        "engine.flush_workers must reach the flush finalize gate"
    );
}

#[test]
fn out_of_range_worker_counts_are_refused_not_clamped() {
    for name in [
        "engine.flush_workers",
        "engine.merge_workers",
        "engine.search_workers",
    ] {
        for bad in [0usize, usize::MAX] {
            let mut engine = Config::default().engine;
            match name {
                "engine.flush_workers" => engine.flush_workers = bad,
                "engine.merge_workers" => engine.merge_workers = bad,
                _ => engine.search_workers = bad,
            }
            let err = engine
                .validate()
                .expect_err("an unusable worker count must be refused, never clamped");
            assert!(
                err.to_string().contains(name),
                "the error must name the setting, got: {err}"
            );
        }
    }
    // merge_workers = 0 used to pass validation entirely: only flush_workers
    // was checked, and nothing read any of the three anyway.
    assert!(Config::default().engine.validate().is_ok());
}

//! ES compatibility test suite for xerj.
//!
//! Validates that the Engine API matches ES REST API contract semantics,
//! translated from the official ES YAML test suite into direct Rust calls.
//!
//! Tests are grouped by API surface:
//!   - Index API (PUT/GET/POST/DELETE document)
//!   - Search API (queries, source filtering, sorting, pagination, highlight, aggs)
//!   - Bulk API
//!   - Delete API
//!   - Count API
//!   - Cluster/health API

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::bulk::process_bulk;
use xerj_engine::Engine;
use xerj_query::parse_request;

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Build a throwaway engine backed by a temp directory.
fn test_engine() -> (Engine, TempDir) {
    let dir = TempDir::new().expect("tempdir");
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    // Large flush thresholds so we never auto-flush mid-test.
    config.storage.flush_size_mb = 4096;
    config.storage.flush_interval_secs = 3600;
    let engine = Engine::new(config).expect("engine::new");
    (engine, dir)
}

/// Convenience: parse a search request from a JSON body.
fn search_req(body: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&body).expect("parse_request")
}

// ═════════════════════════════════════════════════════════════════════════════
// Index API
// ═════════════════════════════════════════════════════════════════════════════

/// ES YAML test: index/10_with_id.yml — PUT /{index}/_doc/{id}
///
/// Verifies that `result` == "created" on first write and that `_version`
/// starts at 1 (ES semantics: seq_no == version for single-shard engines).
#[tokio::test]
async fn test_es_index_with_id() {
    let (engine, _dir) = test_engine();
    engine.create_index("test", Schema::empty()).unwrap();
    let idx = engine.get_index("test").unwrap();

    let resp = idx
        .index_document(
            Some("1".into()),
            json!({ "user": "kimchy", "post_date": "2009-11-15", "message": "trying out Elasticsearch" }),
        )
        .await
        .unwrap();

    // ES contract: _index, _id, result, _version
    assert_eq!(resp.id, "1", "_id should match the supplied ID");
    assert_eq!(
        resp.result, "created",
        "first write result should be 'created'"
    );
    assert_eq!(resp.version, 1, "_version should be 1 on first write");
}

/// ES YAML test: index/10_with_id.yml — GET /{index}/_doc/{id} round-trip
///
/// After indexing, GET must return found=true and _source matching the doc.
#[tokio::test]
async fn test_es_get_document() {
    let (engine, _dir) = test_engine();
    engine.create_index("test", Schema::empty()).unwrap();
    let idx = engine.get_index("test").unwrap();

    let source = json!({ "title": "Hello World", "count": 42 });
    idx.index_document(Some("doc1".into()), source.clone())
        .await
        .unwrap();

    // GET must succeed and return the original source
    let got = idx.get_document("doc1").await.unwrap();
    assert!(got.is_some(), "found should be true");

    let doc = got.unwrap();
    assert_eq!(doc["title"], "Hello World", "_source.title mismatch");
    assert_eq!(doc["count"], 42, "_source.count mismatch");
}

/// ES YAML test: index/15_without_id.yml — POST /{index}/_doc (auto-ID)
///
/// When no ID is supplied, the engine must assign a non-empty UUID-like string.
#[tokio::test]
async fn test_es_index_without_id() {
    let (engine, _dir) = test_engine();
    engine.create_index("test", Schema::empty()).unwrap();
    let idx = engine.get_index("test").unwrap();

    let resp = idx
        .index_document(None, json!({ "message": "auto-id document" }))
        .await
        .unwrap();

    assert!(
        !resp.id.is_empty(),
        "_id should be a non-empty auto-generated string"
    );
    // Auto-generated IDs in ES are URL-safe base64 encoded UUIDs (22 chars).
    // xerj uses UUIDs (36 chars with hyphens) — just check it's non-empty and
    // looks plausible.
    assert!(resp.id.len() >= 10, "_id looks too short: {}", resp.id);
    assert_eq!(resp.result, "created");
}

/// ES YAML test: index/10_with_id.yml — re-index with same ID increments version
///
/// On second write with the same ID, _version must increment and the new source
/// must be visible.
///
/// NOTE: The ES contract says `result` should be `"updated"` on the second write.
/// xerj currently always returns `"created"` (single-shard, no update-vs-create
/// distinction at the response level).  The version increment and source
/// replacement are correctly implemented; only the `result` field diverges.
#[tokio::test]
async fn test_es_index_version_increments() {
    let (engine, _dir) = test_engine();
    engine.create_index("test", Schema::empty()).unwrap();
    let idx = engine.get_index("test").unwrap();

    let r1 = idx
        .index_document(Some("v1".into()), json!({ "val": "first" }))
        .await
        .unwrap();
    assert_eq!(r1.version, 1);

    let r2 = idx
        .index_document(Some("v1".into()), json!({ "val": "second" }))
        .await
        .unwrap();

    // Version must be strictly greater after re-indexing the same ID.
    assert!(
        r2.version > 1,
        "_version should increment on update; got {}",
        r2.version
    );

    // The source must reflect the new document.
    let doc = idx.get_document("v1").await.unwrap().unwrap();
    assert_eq!(
        doc["val"], "second",
        "source must reflect the updated value"
    );
}

/// ES YAML test: index/40_missing.yml — GET on missing document returns None
#[tokio::test]
async fn test_es_get_missing_document() {
    let (engine, _dir) = test_engine();
    engine.create_index("test", Schema::empty()).unwrap();
    let idx = engine.get_index("test").unwrap();

    let result = idx.get_document("does_not_exist").await.unwrap();
    assert!(
        result.is_none(),
        "missing document should return None / found=false"
    );
}

