/// ES YAML: search/30_bool.yml — bool with only filter: all docs match
///
/// A bool query with only filter clauses (no must/should) must return all
/// documents that satisfy the filter.  Filter clauses do not affect scoring
/// in ES (score=0); xerj may assign a small positive score — we only check
/// that the correct docs are returned.
#[tokio::test]
async fn test_es_bool_filter_only() {
    let (engine, _dir) = test_engine();
    engine.create_index("bfo", Schema::empty()).unwrap();
    let idx = engine.get_index("bfo").unwrap();

    idx.index_document(
        Some("q1".into()),
        json!({ "status": "active", "tag": "rust" }),
    )
    .await
    .unwrap();
    idx.index_document(
        Some("q2".into()),
        json!({ "status": "active", "tag": "python" }),
    )
    .await
    .unwrap();
    idx.index_document(
        Some("q3".into()),
        json!({ "status": "inactive", "tag": "rust" }),
    )
    .await
    .unwrap();

    // Only filter clause: no must, no should.
    let req = search_req(json!({
        "query": {
            "bool": {
                "filter": [{ "term": { "status": "active" } }]
            }
        },
        "size": 10
    }));
    let result = idx.search(&req).await.unwrap();

    let ids: Vec<&str> = result.hits.iter().map(|h| h.id.as_str()).collect();
    assert!(ids.contains(&"q1"), "q1 (active) must match");
    assert!(ids.contains(&"q2"), "q2 (active) must match");
    assert!(!ids.contains(&"q3"), "q3 (inactive) must NOT match");
    assert_eq!(result.total.value, 2, "exactly 2 active docs");

    // In ES, filter-only bool gives score=0.  xerj assigns a small score.
    // We verify scores are non-negative.
    for hit in &result.hits {
        assert!(hit.score >= 0.0, "score must be non-negative");
    }
}

/// ES YAML: search/30_bool.yml — bool with minimum_should_match=2 and 3 should clauses
///
/// With `minimum_should_match: 2`, a document must satisfy at least 2 of the
/// 3 should clauses to be included in the results.
#[tokio::test]
async fn test_es_bool_minimum_should_match() {
    let (engine, _dir) = test_engine();
    engine.create_index("bms", Schema::empty()).unwrap();
    let idx = engine.get_index("bms").unwrap();

    // p_abc matches all 3 should clauses.
    idx.index_document(
        Some("p_abc".into()),
        json!({ "a": "yes", "b": "yes", "c": "yes" }),
    )
    .await
    .unwrap();
    // p_ab matches 2 clauses (a and b).
    idx.index_document(
        Some("p_ab".into()),
        json!({ "a": "yes", "b": "yes", "c": "no" }),
    )
    .await
    .unwrap();
    // p_a matches only 1 clause.
    idx.index_document(
        Some("p_a".into()),
        json!({ "a": "yes", "b": "no", "c": "no" }),
    )
    .await
    .unwrap();
    // p_none matches none.
    idx.index_document(
        Some("p_none".into()),
        json!({ "a": "no", "b": "no", "c": "no" }),
    )
    .await
    .unwrap();

    let req = search_req(json!({
        "query": {
            "bool": {
                "should": [
                    { "term": { "a": "yes" } },
                    { "term": { "b": "yes" } },
                    { "term": { "c": "yes" } }
                ],
                "minimum_should_match": 2
            }
        },
        "size": 10
    }));
    let result = idx.search(&req).await.unwrap();

    let ids: Vec<&str> = result.hits.iter().map(|h| h.id.as_str()).collect();
    assert!(
        ids.contains(&"p_abc"),
        "p_abc (3 matches) must satisfy min_should_match=2"
    );
    assert!(
        ids.contains(&"p_ab"),
        "p_ab (2 matches) must satisfy min_should_match=2"
    );
    assert!(
        !ids.contains(&"p_a"),
        "p_a (1 match) must NOT satisfy min_should_match=2"
    );
    assert!(
        !ids.contains(&"p_none"),
        "p_none (0 matches) must NOT match"
    );
}

/// ES YAML: search/30_bool.yml — deeply nested bool (3 levels)
///
/// Bool queries may be nested arbitrarily deep.  A 3-level nesting must
/// correctly filter documents.
#[tokio::test]
async fn test_es_bool_deeply_nested() {
    let (engine, _dir) = test_engine();
    engine.create_index("bdn", Schema::empty()).unwrap();
    let idx = engine.get_index("bdn").unwrap();

    idx.index_document(Some("d1".into()), json!({ "x": 1, "y": 1, "z": 1 }))
        .await
        .unwrap();
    idx.index_document(Some("d2".into()), json!({ "x": 1, "y": 1, "z": 0 }))
        .await
        .unwrap();
    idx.index_document(Some("d3".into()), json!({ "x": 1, "y": 0, "z": 1 }))
        .await
        .unwrap();
    idx.index_document(Some("d4".into()), json!({ "x": 0, "y": 1, "z": 1 }))
        .await
        .unwrap();

    // 3-level nested: must( must( must(x=1) AND must(y=1) ) AND must(z=1) )
    // Only d1 satisfies all three.
    let req = search_req(json!({
        "query": {
            "bool": {
                "must": [{
                    "bool": {
                        "must": [{
                            "bool": {
                                "must": [{ "term": { "x": 1 } }]
                            }
                        }, {
                            "term": { "y": 1 }
                        }]
                    }
                }, {
                    "term": { "z": 1 }
                }]
            }
        },
        "size": 10
    }));
    let result = idx.search(&req).await.unwrap();

    let ids: Vec<&str> = result.hits.iter().map(|h| h.id.as_str()).collect();
    assert!(ids.contains(&"d1"), "d1 (x=1,y=1,z=1) must match");
    assert!(!ids.contains(&"d2"), "d2 (z=0) must NOT match");
    assert!(!ids.contains(&"d3"), "d3 (y=0) must NOT match");
    assert!(!ids.contains(&"d4"), "d4 (x=0) must NOT match");
    assert_eq!(result.total.value, 1, "only d1 satisfies all three levels");
}

//! `exists` inside a filter-context `bool` conjunction must answer from the
//! columnar filter executor — not by source-scanning every row.
//!
//! #1183's finalize-verify issues one `bool: [term: ax_file, exists: <field>]`
//! count per changed group. In scoring context (`must`) that query fell to
//! the brute path and source-scanned the whole index per call: measured
//! took=9638ms for 0 hits on a 91k-doc segment of the standing xerj-search
//! rebuild. The fix lowers filter-context `exists` to the columnar path —
//! keyword fields via the empty-prefix dictionary range, numeric/boolean via
//! the unbounded window, and column-less fields (text / semantic_text) via a
//! source-backed leaf that runs AFTER the cheap conjuncts in the same row
//! walk (so the term narrows first).
//!
//! Every count below is asserted against a hand-computed expectation from
//! the seed (not against the brute path), and the scoring-context `must`
//! variant — still served by the brute path — must report the SAME total:
//! cross-path agreement is the regression guard for drift between the
//! columnar leaf and `doc_matches_query`'s `exists` arm.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// 90 docs over three `ax_file` groups, exercising every `exists` edge in
/// `value_present`: absent key, explicit null, empty string (PRESENT), and
/// an array with a non-null element (PRESENT).  `note` is a second
/// column-less (text) field with a different presence pattern so a
/// conjunction can discriminate; `tag` (keyword) and `num` (long) carry
/// nulls to pin the column-backed lowers.
///
/// Flushed: the columnar executor serves fully-flushed data only — an
/// unflushed population is covered by `memtable_resident_docs_match`.
async fn seed(name: &str) -> (TempDir, std::sync::Arc<Index>) {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("ax_file", FieldType::Keyword));
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("note", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("tag", FieldType::Keyword));
    schema.fields.push(FieldConfig::new("num", FieldType::Long));
    engine.create_index(name, schema).unwrap();
    let idx = engine.get_index(name).unwrap();

    let doc = |id: &str,
               body: Option<Value>,
               note: Option<Value>,
               tag: Option<&str>,
               num: Option<i64>| {
        let mut v = json!({ "ax_file": if id < "d030" { "f1" } else if id < "d064" { "f2" } else { "f3" } });
        if let Some(b) = body {
            v["body"] = b;
        }
        if let Some(n) = note {
            v["note"] = n;
        }
        if let Some(t) = tag {
            v["tag"] = json!(t);
        }
        if let Some(n) = num {
            v["num"] = json!(n);
        }
        v
    };

    // f1: d000..d029 — body everywhere, note nowhere; tag null on odd,
    // num null on every third doc.
    for i in 0..30 {
        idx.index_document(
            Some(format!("d{i:03}")),
            doc(
                &format!("d{i:03}"),
                Some(json!(format!("body text {i}"))),
                None,
                if i % 2 == 0 { Some("a") } else { None },
                if i % 3 == 0 { None } else { Some(i as i64) },
            ),
        )
        .await
        .unwrap();
    }
    // f2: d030..d063 — the edge-case population.
    for i in 30..45 {
        idx.index_document(
            Some(format!("d{i:03}")),
            doc(
                &format!("d{i:03}"),
                Some(json!(format!("body text {i}"))),
                Some(json!(format!("note {i}"))),
                None,
                None,
            ),
        )
        .await
        .unwrap();
    }
    for i in 45..60 {
        idx.index_document(
            Some(format!("d{i:03}")),
            doc(
                &format!("d{i:03}"),
                None,
                Some(json!(format!("note {i}"))),
                None,
                None,
            ),
        )
        .await
        .unwrap();
    }
    idx.index_document(
        Some("d060".to_string()),
        doc("d060", Some(json!("")), None, None, None),
    )
    .await
    .unwrap(); // empty string: PRESENT
    idx.index_document(
        Some("d061".to_string()),
        doc(
            "d061",
            Some(Value::Null),
            Some(json!("note 61")),
            None,
            None,
        ),
    )
    .await
    .unwrap(); // explicit null: ABSENT
    idx.index_document(
        Some("d062".to_string()),
        doc("d062", None, None, None, None),
    )
    .await
    .unwrap(); // key omitted: ABSENT
    idx.index_document(
        Some("d063".to_string()),
        doc("d063", Some(json!(["array body"])), None, None, None),
    )
    .await
    .unwrap(); // array w/ non-null element: PRESENT
               // f3: d064..d089 — no body, note on the first ten only.
    for i in 64..90 {
        idx.index_document(
            Some(format!("d{i:03}")),
            doc(
                &format!("d{i:03}"),
                None,
                if i < 74 {
                    Some(json!(format!("note {i}")))
                } else {
                    None
                },
                None,
                None,
            ),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    (dir, idx)
}

async fn total(idx: &Index, query: Value, size: usize) -> u64 {
    let req = parse_request(&json!({"query": query, "size": size, "track_total_hits": true}))
        .expect("parse_request");
    let res = idx.search(&req).await.expect("search");
    res.total.value
}

/// The production shape (#1183 finalize-verify): term + exists on a
/// column-less text field, filter context, count-only.
#[tokio::test]
async fn term_and_text_exists_count_matches_expectation() {
    let (_dir, idx) = seed("exists-term-text").await;
    // f2 body-present: d030..d044 (15) + d060 (empty string) + d063 (array)
    // = 17; the null (d061) and omitted (d062) bodies count ABSENT.
    assert_eq!(
        total(
            &idx,
            json!({"bool": {"filter": [
                {"term": {"ax_file": "f2"}},
                {"exists": {"field": "body"}}
            ]}}),
            0
        )
        .await,
        17
    );
    // Cross-path agreement: the scoring-context shape still rides the
    // brute path and must report the same total.
    assert_eq!(
        total(
            &idx,
            json!({"bool": {"must": [
                {"term": {"ax_file": "f2"}},
                {"exists": {"field": "body"}}
            ]}}),
            0
        )
        .await,
        17
    );
    assert_eq!(
        total(
            &idx,
            json!({"bool": {"filter": [
                {"term": {"ax_file": "f1"}},
                {"exists": {"field": "body"}}
            ]}}),
            0
        )
        .await,
        30
    );
    assert_eq!(
        total(
            &idx,
            json!({"bool": {"filter": [
                {"term": {"ax_file": "f3"}},
                {"exists": {"field": "body"}}
            ]}}),
            0
        )
        .await,
        0
    );
}

