/// size>0 must return the right ids at score 0.0 (ES filter context).
#[tokio::test]
async fn paged_hits_are_the_matching_ids_at_zero_score() {
    let (_dir, idx) = seed("exists-page").await;
    let req = parse_request(&json!({
        "query": {"bool": {"filter": [
            {"term": {"ax_file": "f2"}},
            {"exists": {"field": "body"}}
        ]}},
        "size": 100,
        "track_total_hits": true
    }))
    .expect("parse_request");
    let res = idx.search(&req).await.unwrap();
    assert_eq!(res.total.value, 17);
    let mut ids: Vec<String> = res.hits.iter().map(|h| h.id.clone()).collect();
    ids.sort_unstable();
    let mut expected: Vec<String> = (30..45).map(|i| format!("d{i:03}")).collect();
    expected.push("d060".to_string());
    expected.push("d063".to_string());
    expected.sort_unstable();
    assert_eq!(ids, expected);
    assert!(
        res.hits.iter().all(|h| h.score == 0.0),
        "filter-context scores must be 0.0, got {:?}",
        res.hits.iter().map(|h| h.score).collect::<Vec<_>>()
    );
}

/// The columnar executor bails on memtable-resident data by design; the
/// brute path answers instead and must agree on the same edges.
#[tokio::test]
async fn memtable_resident_docs_match() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("ax_file", FieldType::Keyword));
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index("exists-memtable", schema).unwrap();
    let idx = engine.get_index("exists-memtable").unwrap();
    idx.index_document(
        Some("m1".to_string()),
        json!({"ax_file": "g", "body": "present"}),
    )
    .await
    .unwrap();
    idx.index_document(
        Some("m2".to_string()),
        json!({"ax_file": "g", "body": Value::Null}),
    )
    .await
    .unwrap();
    idx.index_document(Some("m3".to_string()), json!({"ax_file": "g"}))
        .await
        .unwrap();
    // No flush: memtable-resident.
    assert_eq!(
        total(
            &idx,
            json!({"bool": {"filter": [
                {"term": {"ax_file": "g"}},
                {"exists": {"field": "body"}}
            ]}}),
            0
        )
        .await,
        1
    );
}

//! Issue #206: a failed index is a **state**, not a dead entry.
//!
//! Before this, an index whose directory refused to open at boot was recorded
//! in a private map that only `Engine::health` ever read. Live-reproduced at
//! `12d5cc32` with a corrupt `snapshot.json` (the storage layer's documented
//! "present but unparseable manifest" refusal):
//!
//! ```text
//! failed_indices = [("broken", "storage error: … could not be parsed …")]
//! indices        = []                                   ← invisible
//! health         = "red"
//! delete         = Some(IndexNotFound { name: "broken" }) ← undeletable
//! ```
//!
//! So the index could not be listed, could not be deleted, and could not be
//! retried: the only lever was stopping the server and editing the data
//! directory by hand. Every assertion below fails on that build.
//!
//! The corruption used here is deliberate and realistic — `IndexStore::open`
//! refuses a manifest it cannot parse rather than treating it as empty,
//! because treating it as empty would orphan and then delete every segment.
//! That refusal is correct; having no way to act on it afterwards was not.

use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_common::XerjError;
use xerj_engine::{Engine, EngineError};

fn config_for(dir: &TempDir) -> Config {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config
}

/// Build a data dir holding `names`, each with one flushed document, then
/// corrupt `break_me`'s manifest so the next boot refuses to open it.
/// Returns the good manifest bytes so a test can "fix the cause" and retry.
async fn data_dir_with_one_broken_index(names: &[&str], break_me: &str) -> (TempDir, Vec<u8>) {
    let dir = TempDir::new().unwrap();
    {
        let engine = Engine::new(config_for(&dir)).expect("first boot");
        for name in names {
            engine.create_index(name, Schema::empty()).unwrap();
            let idx = engine.get_index(name).unwrap();
            idx.index_document(Some("1".to_string()), serde_json::json!({"t": "hello"}))
                .await
                .unwrap();
            engine.flush_index(name).await.unwrap();
        }
    }
    let manifest = dir.path().join(break_me).join("snapshot.json");
    let good = std::fs::read(&manifest).expect("a flushed index must have a manifest");
    std::fs::write(&manifest, b"{not json").unwrap();
    (dir, good)
}

fn xerj_error(e: EngineError) -> XerjError {
    e.into()
}

/// `Index` is not `Debug`, so `unwrap_err()` is unavailable on the
/// index-returning calls. Take the error explicitly instead.
fn err_of<T>(r: Result<T, EngineError>, what: &str) -> XerjError {
    match r {
        Ok(_) => panic!("{what} must not succeed"),
        Err(e) => xerj_error(e),
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_failed_index_is_listed_with_its_reason() {
    let (dir, _good) = data_dir_with_one_broken_index(&["broken", "healthy"], "broken").await;
    let engine = Engine::new(config_for(&dir)).expect("boot with one broken index");

    let failed = engine.list_failed_indices();
    assert_eq!(
        failed.len(),
        1,
        "expected exactly one failed index: {failed:?}"
    );
    let f = &failed[0];
    assert_eq!(f.name, "broken");
    assert!(
        f.reason.contains("snapshot.json") && f.reason.contains("could not be parsed"),
        "the reason must be the verbatim open error, not a summary: {}",
        f.reason
    );
    assert!(f.failed_at_ms > 0, "a failed index records when it failed");
    assert_eq!(f.retries, 0, "no retry has been attempted yet");

    // The healthy index in the same data dir is unaffected — one broken index
    // must not cost the node the others.
    assert_eq!(engine.list_indices().await.len(), 1);
    assert!(engine.get_index("healthy").is_ok());
    assert_eq!(engine.health().await.status, "red");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn reads_and_writes_to_a_failed_index_say_unavailable_not_not_found() {
    let (dir, _good) = data_dir_with_one_broken_index(&["broken"], "broken").await;
    let engine = Engine::new(config_for(&dir)).expect("boot");

    // `index_not_found` (404) was a lie: the name is taken and the bytes are
    // on disk. It is now 503 `no_shard_available_action_exception` carrying
    // the open error.
    let e = err_of(engine.get_index("broken"), "get_index on a failed index");
    assert!(
        matches!(e, XerjError::IndexUnavailable { .. }),
        "get_index on a failed index must not report not-found: {e:?}"
    );
    assert_eq!(e.http_status(), 503);
    assert!(e.to_string().contains("snapshot.json"), "{e}");

    // Auto-create must not run over a failed index — that would either destroy
    // recoverable segments or fail deep in the store with an opaque message.
    let e = err_of(
        engine.get_or_create_index("broken"),
        "auto-create over a failed index",
    );
    assert!(
        matches!(e, XerjError::IndexUnavailable { .. }),
        "auto-create must refuse a failed index: {e:?}"
    );
    // …and the refusal must not have created anything.
    assert!(engine.list_indices().await.is_empty());
    assert_eq!(engine.list_failed_indices().len(), 1);

    // Explicit create is refused for the same reason, with the same message.
    let e = xerj_error(engine.create_index("broken", Schema::empty()).unwrap_err());
    assert!(
        matches!(e, XerjError::IndexUnavailable { .. }),
        "create over a failed index must name the real cause: {e:?}"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_failed_index_can_be_deleted_without_a_restart() {
    let (dir, _good) = data_dir_with_one_broken_index(&["broken", "healthy"], "broken").await;
    let engine = Engine::new(config_for(&dir)).expect("boot");
    let index_dir = dir.path().join("broken");
    assert!(index_dir.exists());

    engine
        .delete_index("broken")
        .await
        .expect("a failed index must be deletable");

    assert!(!index_dir.exists(), "delete must remove the bytes on disk");
    assert!(engine.list_failed_indices().is_empty());
    // Health recovers without a restart, and the name is reusable.
    assert_ne!(engine.health().await.status, "red");
    engine
        .create_index("broken", Schema::empty())
        .expect("the freed name must be reusable");

    // A name that was never an index is still a plain 404.
    let e = xerj_error(engine.delete_index("never-existed").await.unwrap_err());
    assert!(matches!(e, XerjError::IndexNotFound { .. }), "{e:?}");
}

/// The failed-index arm of `delete_index` drops its bookkeeping only after the
/// bytes are gone. The **open**-index arm did the opposite: the handle was
/// pulled out of `Engine::indices` before `delete_all_data`, so a removal that
/// failed left the name freed and the directory alive — no handle, no
/// `failed_indices` entry, nothing on `_cat/indices`, `DELETE` answering 404
/// and none of the three recovery levers able to name it. That is issue #206's
/// stuck state reached from the other side, and it only became
/// operator-visible once `DELETE` started propagating the error instead of
/// dropping it.
#[cfg(unix)]
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_delete_that_failed_leaves_the_index_addressable() {
    use std::os::unix::fs::PermissionsExt;

    let (dir, good) = data_dir_with_one_broken_index(&["keeper"], "keeper").await;
    // Undo the corruption — this test is about a healthy, open index whose
    // *bytes* refuse to go away, not about a failed one.
    std::fs::write(dir.path().join("keeper").join("snapshot.json"), &good).unwrap();
    let engine = Engine::new(config_for(&dir)).expect("boot");
    assert!(engine.get_index("keeper").is_ok());

    // Make the removal fail: with the index directory read-only its entries
    // cannot be unlinked, so `remove_dir_all` returns EACCES.
    let index_dir = dir.path().join("keeper");
    let original = std::fs::metadata(&index_dir).unwrap().permissions();
    std::fs::set_permissions(&index_dir, std::fs::Permissions::from_mode(0o555)).unwrap();

    // Skip rather than lie if the platform/user does not enforce the mode
    // (running as root, or an fs that ignores it) — the assertion below would
    // be vacuous there.
    let enforced = std::fs::write(index_dir.join(".perm-probe"), b"x").is_err();
    if !enforced {
        let _ = std::fs::remove_file(index_dir.join(".perm-probe"));
        std::fs::set_permissions(&index_dir, original).unwrap();
        eprintln!("skipping: directory permissions are not enforced for this user");
        return;
    }

    let err = engine
        .delete_index("keeper")
        .await
        .expect_err("a delete whose bytes cannot be removed must fail");
    assert!(
        index_dir.exists(),
        "the directory survived the failed delete"
    );

    // The point of the test: the name did not become a dead end.
    assert!(
        engine.get_index("keeper").is_ok(),
        "a delete that did not happen must leave the index addressable ({err})"
    );
    assert!(
        engine
            .list_indices()
            .await
            .iter()
            .any(|i| i.name == "keeper"),
        "and still enumerable, or no surface can show it"
    );

    // Once the cause is fixed the operator's retry works — no restart.
    std::fs::set_permissions(&index_dir, original).unwrap();
    engine
        .delete_index("keeper")
        .await
        .expect("retrying the delete after fixing the cause must work");
    assert!(!index_dir.exists());
    assert!(engine.list_indices().await.is_empty());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn retry_reports_the_live_reason_and_succeeds_once_the_cause_is_fixed() {
    let (dir, good) = data_dir_with_one_broken_index(&["broken"], "broken").await;
    let engine = Engine::new(config_for(&dir)).expect("boot");

    // Retry while still broken: the error is returned, not swallowed, and the
    // attempt is counted so a flapping directory is visible as one.
    let e = xerj_error(engine.retry_failed_index("broken").unwrap_err());
    assert!(
        matches!(e, XerjError::IndexUnavailable { .. }),
        "a retry that did not work must fail loudly: {e:?}"
    );
    let after = engine.list_failed_indices();
    assert_eq!(after.len(), 1);
    assert_eq!(after[0].retries, 1, "the retry must be counted");

    // Operator fixes the cause (here: restores the manifest from the backup
    // the storage error told them to look for) and retries again.
    std::fs::write(dir.path().join("broken").join("snapshot.json"), &good).unwrap();
    engine
        .retry_failed_index("broken")
        .expect("retry after the fix must reopen the index");

    assert!(engine.list_failed_indices().is_empty());
    assert_eq!(engine.list_indices().await.len(), 1);
    assert_ne!(engine.health().await.status, "red");
    // The index actually serves: the document survived the whole round trip.
    let idx = engine.get_index("broken").expect("reopened index");
    assert_eq!(idx.stats().await.doc_count, 1);

    // Retrying a name that is not a failed index is a 404, not a silent ok.
    let e = xerj_error(engine.retry_failed_index("broken").unwrap_err());
    assert!(matches!(e, XerjError::IndexNotFound { .. }), "{e:?}");
}

//! #1260 — two walls between the finalize-verify query shape and the
//! columnar fast path, both measured live on the 402,814-doc
//! autoindex-catalog:
//!
//! 1. `exists` had no arm in `compile_pred`, so the verify window
//!    (`bool.filter [terms …, exists text]` + a terms agg) fell off the
//!    fast path to the brute `_source` path (15.9 s vs 63 ms cold for the
//!    exists-free twin).
//! 2. The `deletes_present` bail keyed on the MONOTONIC `ghost_events`
//!    counter, so an index that has EVER seen an overwrite — the catalog
//!    is rewritten by every finalize-catalog — never re-qualified, even
//!    after merges compacted every ghost away.  Admission is now
//!    per-segment via the ghost-position bitmap: empty bitmaps proceed
//!    (live == physical), dirty ones still bail.
//!
//! The invariant under test is fast-path/brute-path agreement, plus the
//! served/bailed signal from `aggs::fast_path_aggs_served` for the cases
//! where which executor answered IS the regression.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::aggs::fast_path_aggs_served;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

/// The served/bailed assertions read the PROCESS-GLOBAL
/// `fast_path_aggs_served()` counter as a before/after delta, so two of
/// these tests running concurrently count each other's serves (CI caught
/// exactly that: run 37816544794 failed `exists_on_meta_field_bails_to_brute`
/// with delta 1 while a sibling test's fast-path serve landed inside the
/// window).  The whole file is ~1 s, so serialize it rather than inventing
/// a per-index counter only the tests would use.
static ONE_AT_A_TIME: std::sync::LazyLock<tokio::sync::Mutex<()>> =
    std::sync::LazyLock::new(|| tokio::sync::Mutex::new(()));

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// A schema that DECLARES the given string fields as `keyword`, mirroring the
/// real autoindex catalog mapping (`catalog.rs::catalog_mapping` declares
/// `format`/`path`/`status`/`file_key` as keyword).
///
/// These tests stand in for that catalog but used `Schema::empty()`, letting
/// their string fields (`extension`, `text`, `group`) be dynamically mapped.
/// Since #1329 a dynamically mapped string is a `text` parent with NO
/// doc-values (only its `.keyword` sub-field carries them, matching ES), and a
/// `text` field never gets a doc-values column regardless of the flag
/// (`FieldConfig::stored_doc_values` excludes `Text`). The columnar fast path
/// — the terms executor and the `KwExists` arm alike — reads that doc-values
/// column, so an inferred stand-in makes every "must serve columnarly"
/// assertion bail to brute. Declaring the stand-ins keyword restores the
/// column the catalog's real keyword fields have. Numeric fields (`v`, `i`)
/// are unaffected and stay inferred.
fn kw_schema(fields: &[&str]) -> Schema {
    let mut s = Schema::empty();
    for f in fields {
        s.fields.push(FieldConfig::new(*f, FieldType::Keyword));
    }
    s
}

async fn run(idx: &std::sync::Arc<Index>, body: serde_json::Value) -> serde_json::Value {
    let req = parse_request(&body).unwrap();
    let res = idx.search(&req).await.unwrap();
    json!({
        "total": res.total.value,
        "aggs": res.aggs.clone().unwrap_or(json!(null)),
    })
}

/// 12,000 flushed docs — past `FAST_AGG_MIN_DOCS` (10,000) — cycling the
/// `text` field through present / JSON-null / absent / empty-string, so a
/// single segment's keyword column carries non-null rows, null rows for
/// both missing shapes, and the ES-visible `""` (which counts as present).
async fn seed_exists_shapes(idx: &std::sync::Arc<Index>) {
    for i in 0..12_000u32 {
        let text = match i % 4 {
            0 => json!("present"), // column row, value ""
            1 => json!(null),      // column row = null
            2 => json!(null),      // key omitted entirely below
            _ => json!(""),        // column row, empty string — PRESENT
        };
        let mut doc = json!({ "extension": if i % 3 == 0 { "css" } else { "gz" }, "i": i });
        if i % 4 != 2 {
            doc["text"] = text;
        }
        idx.index_document(Some(i.to_string()), doc).await.unwrap();
    }
    idx.flush().await.unwrap();
}

fn exists_terms_query() -> serde_json::Value {
    // The finalize-verify window shape: a terms-set filter conjoined with
    // exists, answering a terms agg.  Before #1260 the exists leaf alone
    // pushed this whole request to the brute path.
    json!({
        "query": {
            "bool": {
                "filter": [
                    { "terms": { "extension": ["css", "gz"] } },
                    { "exists": { "field": "text" } }
                ]
            }
        },
        "size": 0,
        "aggs": { "by_ext": { "terms": { "field": "extension" } } }
    })
}

#[tokio::test]
async fn exists_in_top_filter_matches_brute() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("existsq", kw_schema(&["extension", "text"]))
        .unwrap();
    let idx = engine.get_index("existsq").unwrap();
    seed_exists_shapes(&idx).await;

    let before = fast_path_aggs_served();
    let fast = run(&idx, exists_terms_query()).await;
    let served = fast_path_aggs_served() - before;
    assert_eq!(
        served, 1,
        "the terms+exists conjunction must serve columnarly"
    );

    // ES semantics pinned on the reference too: `""` is present, JSON null
    // and absent are not — 2 of the 4 cycle positions match (3,000 + 3,000).
    // css among them: i%4 ∈ {0,3} ∧ i%3 == 0 → 2 per period-12 → 2,000;
    // gz gets the other 4,000.
    assert_eq!(fast["total"], 6_000);
    assert_eq!(fast["aggs"]["by_ext"]["buckets"][0]["key"], "gz");
    assert_eq!(fast["aggs"]["by_ext"]["buckets"][0]["doc_count"], 4_000);
    assert_eq!(fast["aggs"]["by_ext"]["buckets"][1]["key"], "css");
    assert_eq!(fast["aggs"]["by_ext"]["buckets"][1]["doc_count"], 2_000);

    // Brute reference via an overwrite (records a ghost, trips admission).
    idx.index_document(
        Some("0".to_string()),
        json!({ "extension": "css", "i": 0, "text": "present" }),
    )
    .await
    .unwrap();
    let brute = run(&idx, exists_terms_query()).await;
    assert_eq!(
        fast, brute,
        "columnar exists disagrees with the brute reference"
    );
}

/// `exists` over a NUMERIC column (the `NumExists` arm) — parity with
/// `value_present` on the brute path.
#[tokio::test]
async fn exists_on_numeric_field_matches_brute() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("existsn", kw_schema(&["group"]))
        .unwrap();
    let idx = engine.get_index("existsn").unwrap();
    for i in 0..12_000u32 {
        let mut doc = json!({ "group": if i % 2 == 0 { "a" } else { "b" } });
        if i % 3 != 0 {
            doc["v"] = serde_json::Value::from(i as f64); // absent for every third doc
        }
        idx.index_document(Some(i.to_string()), doc).await.unwrap();
    }
    idx.flush().await.unwrap();

    let q = json!({
        "query": { "exists": { "field": "v" } },
        "size": 0,
        "aggs": {
            "n": { "value_count": { "field": "v" } },
            "by_group": { "terms": { "field": "group" } }
        }
    });
    let before = fast_path_aggs_served();
    let fast = run(&idx, q.clone()).await;
    assert_eq!(fast_path_aggs_served() - before, 1);
    assert_eq!(fast["total"], 8_000);
    assert_eq!(fast["aggs"]["n"]["value"], 8_000);

    // Byte-identical overwrite of id 0 — whose `v` is ABSENT (0 % 3 == 0),
    // so the body must omit it too, or the reference corpus changes.
    idx.index_document(Some("0".to_string()), json!({ "group": "a" }))
        .await
        .unwrap();
    let brute = run(&idx, q).await;
    assert_eq!(
        fast, brute,
        "numeric exists disagrees with the brute reference"
    );
}

/// Meta-field `exists` has no columnar form (brute answers it from
/// bookkeeping) — the fast path must BAIL, not answer it empty.
#[tokio::test]
async fn exists_on_meta_field_bails_to_brute() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("existsmeta", Schema::empty()).unwrap();
    let idx = engine.get_index("existsmeta").unwrap();
    for i in 0..12_000u32 {
        idx.index_document(Some(i.to_string()), json!({ "i": i }))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    let q = json!({
        "query": { "exists": { "field": "_id" } },
        "size": 0,
        "aggs": { "n": { "value_count": { "field": "i" } } }
    });
    let before = fast_path_aggs_served();
    let out = run(&idx, q).await;
    assert_eq!(
        fast_path_aggs_served() - before,
        0,
        "meta-field exists must bail"
    );
    assert_eq!(out["total"], 12_000, "every doc has an _id");
}

/// The admission gate's safety half: an overwrite whose superseded row is
/// still resident (no merge yet) keeps the fast path OFF, and the live
/// corpus answer is unchanged by a byte-identical overwrite.
#[tokio::test]
async fn unmerged_ghosts_still_bail() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("ghosts", kw_schema(&["group"]))
        .unwrap();
    let idx = engine.get_index("ghosts").unwrap();
    for i in 0..12_000u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "group": if i % 2 == 0 { "a" } else { "b" }, "v": i as f64 }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    let q = json!({
        "query": { "term": { "group": "a" } },
        "size": 0,
        "aggs": { "total_v": { "sum": { "field": "v" } } }
    });
    let clean = run(&idx, q.clone()).await;
    let served_clean = fast_path_aggs_served();

    // Overwrite + delete WITHOUT merging: the flushed segment still holds
    // the superseded rows — bitmaps are dirty.
    idx.index_document(Some("0".to_string()), json!({ "group": "a", "v": 0.0 }))
        .await
        .unwrap();
    idx.delete_document("2").await.unwrap();

    let dirty = run(&idx, q).await;
    assert_eq!(
        fast_path_aggs_served(),
        served_clean,
        "a segment with resident ghosts must not serve columnarly"
    );
    // Live corpus: doc 0 byte-identical, doc 2 deleted (was group a, v=2).
    assert_eq!(clean["total"], 6_000);
    assert_eq!(dirty["total"], 5_999);
    assert_eq!(
        clean["aggs"]["total_v"]["value"].as_f64().unwrap()
            - dirty["aggs"]["total_v"]["value"].as_f64().unwrap(),
        2.0
    );
}

/// The #1260 headline: after merges compact the ghosts away the index
/// RE-QUALIFIES for the fast path even though `ghost_events` (monotonic)
/// never resets — with a live memtable on top, the production shape of the
/// autoindex-catalog (rewritten continuously, merged in the background).
#[tokio::test]
async fn merged_delete_history_re_qualifies_for_fast_path() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("readmit", kw_schema(&["extension"]))
        .unwrap();
    let idx = engine.get_index("readmit").unwrap();
    for i in 0..12_000u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": if i % 3 == 0 { "css" } else { "gz" }, "i": i }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    // Delete history: 100 overwrites (changed bodies) + 50 deletes.
    for i in 0..100u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": "css", "i": i, "rewritten": true }),
        )
        .await
        .unwrap();
    }
    for i in 100..150u32 {
        idx.delete_document(&i.to_string()).await.unwrap();
    }
    idx.flush().await.unwrap();
    idx.force_merge(1).await.unwrap();

    // A live memtable on top of the merged index (the catalog's steady
    // state): fresh ids only, so every entry is in-memory-live.
    for i in 12_000..12_200u32 {
        idx.index_document(Some(i.to_string()), json!({ "extension": "css", "i": i }))
            .await
            .unwrap();
    }

    let q = json!({
        "query": {
            "bool": {
                // A one-element `terms` SET, not a singular `term`: on a
                // declared keyword field a singular `term` is deliberately
                // kept in the FTS scoring tree (index.rs
                // `query_node_to_fts_projected`, so a mixed bool can add its
                // BM25 score), which makes `query_needs_fts` true and routes a
                // size:0 agg to the brute path — never the columnar fast path
                // this test asserts. The real finalize-verify window
                // (`sync_executor::windowed_value_counts`) filters with a
                // `terms` set over a digest window, so `terms` is also the
                // production-faithful shape. A one-element set matches exactly
                // the same docs as `term`. (Before #1329 `extension` was an
                // inferred `text` field, classified differently, so the
                // singular `term` happened to take the fast path.)
                "filter": [
                    { "terms": { "extension": ["css"] } },
                    { "exists": { "field": "i" } }
                ]
            }
        },
        "size": 0,
        "aggs": { "by_ext": { "terms": { "field": "extension" } } }
    });
    let before = fast_path_aggs_served();
    let fast = run(&idx, q.clone()).await;
    assert_eq!(
        fast_path_aggs_served() - before,
        1,
        "a merged index with clean bitmaps must serve columnarly despite \
         its monotonic ghost history"
    );

    // Brute reference: overwrite one merged doc byte-identically (trips
    // admission without changing the live corpus).
    idx.index_document(
        Some("0".to_string()),
        json!({ "extension": "css", "i": 0, "rewritten": true }),
    )
    .await
    .unwrap();
    let brute = run(&idx, q).await;
    assert_eq!(fast, brute, "admitted fast path disagrees with brute");

    // Arithmetic: originals css = |{i < 12_000 : i % 3 == 0}| = 4_000;
    // overwrites 0..99 moved ALL 100 to css, of which 34 were css before
    // (i%3==0 for i<100) → 4_000 + 100 − 34 = 4_066; deletes 100..149
    // removed 16 css (multiples of 3 in [100,150): 102..147) → 4_050;
    // memtable +200 css → 4_250.
    assert_eq!(fast["total"], 4_250);
}

/// A memtable doc whose value for the exists field is a JSON OBJECT (the
/// field is scalar in every segment) — `value_present` says present on the
/// brute query path; `doc_matches_filter` flattened objects to `[]` and
/// disagreed.  The alignment is pinned here.
#[tokio::test]
async fn object_valued_memtable_doc_counts_as_exists() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("objmem", kw_schema(&["extension", "text"]))
        .unwrap();
    let idx = engine.get_index("objmem").unwrap();
    for i in 0..12_000u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": "seg", "text": "scalar" }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    // Buffered (un-flushed) docs with an object under the columned field.
    for i in 12_000..12_100u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": "mem", "text": { "nested": true } }),
        )
        .await
        .unwrap();
    }

    let q = json!({
        "query": { "exists": { "field": "text" } },
        "size": 0,
        "aggs": { "by_ext": { "terms": { "field": "extension" } } }
    });
    let before = fast_path_aggs_served();
    let fast = run(&idx, q.clone()).await;
    assert_eq!(fast_path_aggs_served() - before, 1);
    assert_eq!(
        fast["total"], 12_100,
        "objects count as present on both paths"
    );

    idx.index_document(
        Some("0".to_string()),
        json!({ "extension": "seg", "text": "scalar" }),
    )
    .await
    .unwrap();
    let brute = run(&idx, q).await;
    assert_eq!(fast, brute, "memtable object exists disagrees with brute");
}

//! Regression: `<field>.keyword` predicates on the columnar fast path.
//!
//! A text field's auto-created `.keyword` multi-field shares the *same*
//! physical doc-values column, stored under the parent's unsuffixed name.
//! Aggregation *targets* learned to fall back from `x.keyword` to `x`, but
//! the predicate resolver did not: it looked the exact name up in the
//! column map and, on a miss, resolved the whole predicate to "matches
//! nothing in this segment".  Failing closed like that is invisible — the
//! memtable arm resolves `.keyword` correctly, so a filtered panel returns
//! a small, plausible, wrong number instead of an error.
//!
//! The invariant under test is fast-path/brute-path agreement, not any
//! particular hardcoded count: the brute `_source` path is the reference
//! implementation for every agg shape.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// 12 000 flushed docs + 200 still in the memtable — past
/// `FAST_AGG_MIN_DOCS` (10 000), so the columnar path is the one under
/// test, and split across both arms so a segment-only defect cannot hide
/// behind a correct memtable answer.
///
/// Flushed: `extension` cycles css/gz/zip/php (3 000 each), `group`
/// alternates a/b (6 000 each), `v` is 1.0 for a and 100.0 for b.
/// Memtable: 200 more css/a/1.0 docs, so the two arms disagree on every
/// bucket and any arm that silently contributes zero is visible.
async fn seed(idx: &std::sync::Arc<xerj_engine::Index>) {
    const EXTS: [&str; 4] = ["css", "gz", "zip", "php"];
    for i in 0..12_000u32 {
        let group = if i % 2 == 0 { "a" } else { "b" };
        let v = if i % 2 == 0 { 1.0 } else { 100.0 };
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": EXTS[(i % 4) as usize], "group": group, "v": v, "i": i }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    for i in 12_000..12_200u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": "css", "group": "a", "v": 1.0, "i": i }),
        )
        .await
        .unwrap();
    }
}

/// Force every subsequent agg request onto the brute `_source` path
/// WITHOUT changing a single live value: re-index one existing doc with a
/// byte-identical body.  That records an overwrite in the version map, and
/// `ghost_events() > 0` is exactly the gate `try_fast_aggs` bails on.  The
/// live corpus is unchanged, so the brute answer is the reference answer
/// for the same data the fast path just aggregated.
///
/// (The `XERJ_DISABLE_FAST_AGGS=1` kill switch is memoised in a process-wide
/// `OnceLock`, so it cannot be flipped mid-process to get the same effect.)
async fn force_brute(idx: &std::sync::Arc<xerj_engine::Index>) {
    idx.index_document(
        Some("0".to_string()),
        json!({ "extension": "css", "group": "a", "v": 1.0, "i": 0 }),
    )
    .await
    .unwrap();
}

async fn run(
    idx: &std::sync::Arc<xerj_engine::Index>,
    body: serde_json::Value,
) -> serde_json::Value {
    let req = parse_request(&body).unwrap();
    let res = idx.search(&req).await.unwrap();
    json!({
        "total": res.total.value,
        "aggs": res.aggs.clone().unwrap_or(json!(null)),
    })
}

fn filters_on_keyword() -> serde_json::Value {
    json!({
        "query": { "match_all": {} },
        "size": 0,
        "aggs": {
            "by_ext": {
                "filters": {
                    "filters": {
                        "css": { "term": { "extension.keyword": "css" } },
                        "gz":  { "term": { "extension.keyword": "gz" } }
                    }
                }
            }
        }
    })
}

fn query_term_on_keyword() -> serde_json::Value {
    json!({
        "query": { "term": { "group.keyword": "b" } },
        "size": 0,
        "aggs": { "total_v": { "sum": { "field": "v" } } }
    })
}

#[tokio::test]
async fn fast_and_brute_agree_on_keyword_filters_agg() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("kwfilters", Schema::empty()).unwrap();
    let idx = engine.get_index("kwfilters").unwrap();
    seed(&idx).await;

    let fast = run(&idx, filters_on_keyword()).await;
    force_brute(&idx).await;
    let brute = run(&idx, filters_on_keyword()).await;

    assert_eq!(
        fast, brute,
        "columnar fast path disagrees with the brute reference on a \
         `filters` agg keyed by `<field>.keyword`"
    );
    // Sanity: the fixture must actually exercise both arms, so a future
    // change that makes BOTH paths return zero cannot pass this test.
    assert_eq!(
        brute["aggs"]["by_ext"]["buckets"]["css"]["doc_count"],
        3_200
    );
    assert_eq!(brute["aggs"]["by_ext"]["buckets"]["gz"]["doc_count"], 3_000);
}

#[tokio::test]
async fn fast_and_brute_agree_on_keyword_query_filter() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("kwquery", Schema::empty()).unwrap();
    let idx = engine.get_index("kwquery").unwrap();
