        "columnar fast path disagrees with the brute reference on a `filters` \
         agg leaf hitting only the suppressed segment's rows",
    )
    .await;
    assert_eq!(brute["aggs"]["split"]["buckets"]["b"]["doc_count"], 1_000);
    assert_eq!(brute["aggs"]["split"]["buckets"]["a"]["doc_count"], 11_000);
}

/// Numeric metrics TARGETING the mixed-suppression field: the fold skipped
/// the suppressed segment, so avg/sum/value_count reported the scalar
/// segment's statistics as the whole index's.
#[tokio::test]
async fn fast_and_brute_agree_on_mixed_segment_numeric_metrics() {
    let brute = agree(
        "mixmetrics",
        || {
            json!({
                "query": { "match_all": {} },
                "size": 0,
                "aggs": {
                    "s": { "sum": { "field": "score" } },
                    "a": { "avg": { "field": "score" } },
                    "n": { "value_count": { "field": "score" } }
                }
            })
        },
        "columnar fast path disagrees with the brute reference on numeric \
         metrics over a field whose column is suppressed in ONE segment only",
    )
    .await;
    // The reference is the BRUTE path. Metric aggs now fold EVERY value of a
    // multi-valued field (ES semantics — #839-family fix), so sum is
    // 11 000 × 5 + 1 000 × (1 + 2) = 58 000, value_count sees all 13 000
    // values, and avg divides the sum by the 13 000 values (not the 12 000
    // docs). What this test pins is the fast/brute AGREEMENT above; both paths
    // resolve `score` through brute here (its column is suppressed in seg 2).
    assert_eq!(brute["aggs"]["s"]["value"], 58_000.0);
    assert_eq!(brute["aggs"]["n"]["value"], 13_000);
    assert_eq!(brute["aggs"]["a"]["value"], 58_000.0 / 13_000.0);
}

/// The same metric as a SUB-agg under a fully-covered `terms` parent:
/// sub-metric fields are planned in `plan_subs` via `seg_field_kind`, a
/// different gate from the top-level `exec_agg` one, and the per-row fold
/// skipped the suppressed segment the same way.
#[tokio::test]
async fn fast_and_brute_agree_on_mixed_segment_sub_metric() {
    let brute = agree(
        "mixsubmetric",
        || {
            json!({
                "query": { "match_all": {} },
                "size": 0,
                "aggs": {
                    "by_group": {
                        "terms": { "field": "group", "size": 10 },
                        "aggs": { "s": { "sum": { "field": "score" } } }
                    }
                }
            })
        },
        "columnar fast path disagrees with the brute reference on a SUB-agg \
         `sum` over a field whose column is suppressed in ONE segment only",
    )
    .await;
    let buckets = brute["aggs"]["by_group"]["buckets"].as_array().unwrap();
    assert_eq!(buckets.len(), 2);
    for b in buckets {
        // Each group: 5 500 scalar docs × 5 + 500 array docs × (1 + 2) — the
        // sub-metric sum folds every value of the multi-valued field (ES).
        assert_eq!(b["doc_count"], 6_000);
        assert_eq!(b["s"]["value"], 29_000.0);
    }
}

//! Regression: multi-field suffixes OTHER than `.keyword` on the columnar
//! fast path (`<field>.raw`, the classic Logstash multi-field) — at EVERY
//! depth of suffixing, not just one.
//!
//! There is no single "the brute path".  Which resolver a name is measured
//! against depends on where in the request it appears, and they disagree:
//!
//! * a top-level query filter runs through `index.rs::get_field_value`,
//!   whose multi-field fallback is RECURSIVE
//!   (`get_field_value(source, &field[..idx])`), so it strips an unbounded
//!   number of trailing segments — `extension.raw.raw`,
//!   `extension.keyword.raw` and `extension.raw.raw.raw` all read
//!   `extension`'s string;
//! * an agg TARGET and a `filters`/`filter` leaf run through
//!   `aggs::get_nested_field`, which strips exactly ONE segment, so it reads
//!   `extension.raw` but genuinely finds nothing for `extension.raw.raw`.
//!
//! Both facts are asserted below against the brute leg itself, not read off
//! the source.  `fast_aggs::dv_col` strips only `.keyword`, so every one of
//! these names found no column and the columnar path treated the segment as
//! holding no such data.  That is invisible in the response: predicates
//! resolved to "this segment matches nothing" and aggregation targets simply
//! skipped the segment, so a panel returned a small plausible number built
//! from the memtable alone.
//!
//! The fix keeps resolution narrow — widening it would make the fast path
//! claim shapes it cannot prove byte-identical, and per the above there is
//! no single behaviour to widen TO — and instead BAILS to the brute path
//! whenever a dotted name misses while ANY ancestor of it has a column.
//! After a bail the request is answered by whichever resolver it would have
//! been measured against, so bailing is right against all of them.
//!
//! The invariant under test is fast-path/brute-path agreement, not any
//! particular hardcoded count; the absolute assertions exist only so a
//! future change that makes BOTH paths return nothing cannot pass.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

