            json!({
                "extension": EXTS[(i % 4) as usize],
                "group": group,
                "v": v,
                "ok": a,
                "i": i,
            }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    for i in 12_000..12_200u32 {
        idx.index_document(
            Some(i.to_string()),
            json!({ "extension": "css", "group": "a", "v": 1.0, "ok": true, "i": i }),
