/// The edges index with its §2.2 mapping DECLARED.
///
/// Both production writers declare it (`graph_api::edge_index_mapping`,
/// `detect::edge_index_mapping`): keyword for the ids/type/detector/src_file,
/// numeric/date for the rest. `Index::graph_expand` reads `src`/`dst`/
/// `edge_id`/`type`/`weight`/`valid_at` exclusively from doc-values columns —
/// a segment without them is SKIPPED and reported (`segments_without_columns`,
/// graph.rs module docs: the hop never hydrates). This fixture used to pass
/// `Schema::empty()` and let dynamic mapping stand in; since #1329 a
/// dynamically inferred string is a `text` parent with NO doc-values (the ES
/// default), so the stand-in lost its keyword columns and every expansion
/// returned empty. Declare the mapping the contract actually specifies.
fn edges_schema() -> Schema {
    let mut schema = Schema::empty();
    for name in ["edge_id", "src", "dst", "type", "detector", "src_file"] {
        schema
            .fields
            .push(FieldConfig::new(name, FieldType::Keyword));
    }
    for name in ["weight", "confidence"] {
        schema
            .fields
            .push(FieldConfig::new(name, FieldType::Double));
    }
    for name in ["valid_at", "invalid_at", "created_at", "expired_at"] {
        schema.fields.push(FieldConfig::new(name, FieldType::Date));
    }
    schema
        .fields
        .push(FieldConfig::new("schema_version", FieldType::Long));
    schema
}

async fn fixture_index(engine: &Engine) -> std::sync::Arc<Index> {
    engine
        .create_index(EDGES_INDEX, edges_schema())
        .expect("create edges index");
    let idx = engine.get_index(EDGES_INDEX).expect("get edges index");
    for doc in fixture_edges() {
        let id = doc["edge_id"].as_str().unwrap().to_string();
        idx.index_document(Some(id), doc).await.expect("index edge");
    }
    idx
}

fn expand_req(frontier: &[&str], hops: u8) -> GraphExpandRequest {
    GraphExpandRequest {
        frontier: frontier.iter().map(|s| s.to_string()).collect(),
        hops,
        direction: GraphDirection::Both,
        types: None,
        as_of_ms: AS_OF,
        include_expired: false,
        max_result_edges: 1000,
    }
}

/// (edge_id, src, dst, type, weight, hop) tuples — the §8.4 comparison shape.
fn tuples(res: &GraphExpandResult) -> Vec<(String, String, String, String, f64, u8)> {
    res.edges
        .iter()
        .map(|e| {
            (
                e.edge_id.clone(),
                e.src.clone(),
                e.dst.clone(),
                e.edge_type.clone(),
                e.weight,
                e.hop,
            )
        })
        .collect()
}

fn assert_hop1_fixture(res: &GraphExpandResult) {
    // §8.4: EXACTLY this order (hop asc, weight desc, edge_id asc).
    let got = tuples(res);
    let want = vec![
        (
            E_ALPHA_GAMMA_WIKI.into(),
            "note-alpha".into(),
            "note-gamma".into(),
            "wikilink".into(),
            1.0,
            1u8,
        ),
        (
            E_ALPHA_BETA_WIKI.into(),
            "note-alpha".into(),
            "note-beta".into(),
            "wikilink".into(),
            1.0,
            1u8,
        ),
        (
            E_DELTA_ALPHA_WIKI.into(),
            "note-delta".into(),
            "note-alpha".into(),
            "wikilink".into(),
            1.0,
            1u8,
        ),
        (
            E_ALPHA_BETA_DIR.into(),
            "note-alpha".into(),
            "note-beta".into(),
            "same_dir".into(),
            0.3,
            1u8,
        ),
    ];
    assert_eq!(got, want, "hop-1 edge list must match §8.4 exactly");
    assert_eq!(
        res.reachable,
        vec!["note-alpha", "note-gamma", "note-beta", "note-delta"],
        "§8.4 reachable order: frontier first, then first-discovery over sorted edges"
    );
    // Every stats field except the two flush-state cost counters is exact.
    assert_eq!(res.stats.frontier_clipped, 0);
    assert_eq!(res.stats.edges_clipped, 0);
    assert_eq!(res.stats.expired_excluded, 0);
    assert_eq!(res.stats.type_filtered, 0);
    assert_eq!(res.stats.segments_without_columns, 0);
}

/// §3.6 (a) + (b): the §8.4 hop-1 expansion is exact on the memtable path and
/// identical after `flush()` on the columnar path.
#[tokio::test]
async fn graph_expand_fixture_hop1_pre_and_post_flush() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = fixture_index(&engine).await;
    let req = expand_req(&["note-alpha"], 1);

    // Pre-flush: everything comes from the memtable walk.
    let pre = idx.graph_expand(&req).expect("pre-flush expand");
    assert_hop1_fixture(&pre);
    assert_eq!(pre.stats.segments_scanned, 0, "no segments exist pre-flush");
    assert!(pre.stats.memtable_docs_scanned >= 8);

    // Post-flush: everything comes from doc-values columns.
    idx.flush().await.expect("flush");
    let post = idx.graph_expand(&req).expect("post-flush expand");
    assert_hop1_fixture(&post);
    assert!(post.stats.segments_scanned >= 1, "columnar path must run");
    assert_eq!(
        post.stats.memtable_docs_scanned, 0,
        "flush drained the memtable"
    );
    assert_eq!(tuples(&pre), tuples(&post), "flush must not change results");
    assert_eq!(pre.reachable, post.reachable);
}

/// §8.4 hop-2: the hop-2 block (frontier = gamma, beta, delta) appends the
/// remaining four edges in (weight desc, edge_id asc) order and reachable
/// gains note-epsilon.
#[tokio::test]
async fn graph_expand_fixture_hop2_block_order() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = fixture_index(&engine).await;
    let req = expand_req(&["note-alpha"], 2);

    for flushed in [false, true] {
        if flushed {
            idx.flush().await.expect("flush");
        }
        let res = idx.graph_expand(&req).expect("expand hops=2");
        let ids: Vec<&str> = res.edges.iter().map(|e| e.edge_id.as_str()).collect();
        assert_eq!(
            ids,
            vec![
                // hop-1 block (§8.4)
                E_ALPHA_GAMMA_WIKI,
                E_ALPHA_BETA_WIKI,
                E_DELTA_ALPHA_WIKI,
                E_ALPHA_BETA_DIR,
                // hop-2 block: 9bbf (w 1.0), then w-0.3 ties by edge_id asc
                E_BETA_GAMMA_WIKI,
                E_DELTA_EPSILON_DIR,
                E_EPSILON_GAMMA_DIR,
                E_BETA_DELTA_DIR,
            ],
            "hop-2 block order (flushed={flushed})"
        );
        assert!(res.edges[..4].iter().all(|e| e.hop == 1));
        assert!(res.edges[4..].iter().all(|e| e.hop == 2));
        assert_eq!(
            res.reachable,
            vec![
                "note-alpha",
                "note-gamma",
                "note-beta",
                "note-delta",
                "note-epsilon"
            ],
            "hop 2 reaches epsilon (flushed={flushed})"
        );
    }
}

/// §3.6 (c) + §8.6: soft invalidation is a re-index under the same `_id` with
/// `invalid_at`/`expired_at` added. Expanding at `as_of < invalid_at` still
/// sees the edge (belief last Tuesday intact); at `as_of >= invalid_at` it is
/// gone with `expired_excluded == 1`; `include_expired` brings it back.
///
/// The first round runs with the STALE row in a flushed segment and the
/// invalidated row in the memtable — the mixed state that only works when the
/// ghost-bitmap machinery suppresses the superseded segment row.
#[tokio::test]
async fn graph_expand_soft_invalidate_time_travel() {
    const INVALID_AT: i64 = 1_753_650_000_000;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = fixture_index(&engine).await;
    idx.flush().await.expect("flush fixture");

    // Soft-invalidate alpha→beta wikilink: same doc, same `_id`, two added
    // fields — exactly what `DELETE /_graph/{brain}/link/{edge_id}` re-indexes.
    let mut invalidated = fixture_edges()[0].clone();
    invalidated["invalid_at"] = json!(INVALID_AT);
    invalidated["expired_at"] = json!(INVALID_AT);
    idx.index_document(Some(E_ALPHA_BETA_WIKI.to_string()), invalidated)
        .await
        .expect("re-index invalidated edge");

    for (round, flushed) in [(1, false), (2, true)] {
        if flushed {
            idx.flush().await.expect("flush invalidated version");
        }

        // Belief BEFORE the invalidation instant: all four §8.4 edges.
        let mut req = expand_req(&["note-alpha"], 1);
        req.as_of_ms = 1_753_640_000_000;
        let before = idx.graph_expand(&req).expect("expand before invalid_at");
        assert_hop1_fixture(&before);

        // Belief AFTER: the invalidated edge is excluded and counted.
        req.as_of_ms = AS_OF;
        let after = idx.graph_expand(&req).expect("expand after invalid_at");
        let ids: Vec<&str> = after.edges.iter().map(|e| e.edge_id.as_str()).collect();
        assert_eq!(
            ids,
            vec![E_ALPHA_GAMMA_WIKI, E_DELTA_ALPHA_WIKI, E_ALPHA_BETA_DIR],
            "round {round}: invalidated edge must disappear at as_of >= invalid_at"
        );
        assert_eq!(
            after.stats.expired_excluded, 1,
            "round {round}: the exclusion is counted, not silent"
        );

        // include_expired=true: the edge returns, carrying its invalid_at.
        req.include_expired = true;
        let all = idx.graph_expand(&req).expect("expand include_expired");
        let inv = all
            .edges
            .iter()
            .find(|e| e.edge_id == E_ALPHA_BETA_WIKI)
            .expect("include_expired returns the invalidated edge");
        assert_eq!(inv.invalid_at_ms, Some(INVALID_AT));
        assert_eq!(all.edges.len(), 4);
    }
}

/// §3.6 (d) + §3.5: result cap reports clipping; hops out of bounds and an
/// empty frontier are loud `InvalidQuery` errors carrying the §4.6 sentence.
#[tokio::test]
async fn graph_expand_caps_and_bounds() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = fixture_index(&engine).await;

    for flushed in [false, true] {
        if flushed {
            idx.flush().await.expect("flush");
        }
        let mut req = expand_req(&["note-alpha"], 2);
        req.max_result_edges = 2;
        let res = idx.graph_expand(&req).expect("capped expand");
        assert_eq!(
            res.edges.len(),
            2,
            "cap bounds the result (flushed={flushed})"
        );
        assert!(
            res.stats.edges_clipped > 0,
            "overflow must be counted, never silent (flushed={flushed})"
        );
    }

    for bad_hops in [0u8, 3] {
        let err = idx
            .graph_expand(&expand_req(&["note-alpha"], bad_hops))
            .expect_err("hops out of bounds must fail loud");
        let msg = err.to_string();
        assert!(
            msg.contains(GRAPH_HOPS_CAP_REASON),
            "hops={bad_hops} error must carry the §4.6 sentence, got: {msg}"
        );
    }

    let err = idx
        .graph_expand(&expand_req(&[], 1))
        .expect_err("empty frontier must fail loud");
    assert!(err.to_string().contains("non-empty frontier"));
}

/// Direction and type filters: `Out`/`In` scan a single column; the `types`
/// allowlist counts what it drops.
#[tokio::test]
async fn graph_expand_direction_and_type_filter() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = fixture_index(&engine).await;
    idx.flush().await.expect("flush");

    let mut req = expand_req(&["note-alpha"], 1);
    req.direction = GraphDirection::Out;
    let out = idx.graph_expand(&req).expect("out expand");
    let ids: Vec<&str> = out.edges.iter().map(|e| e.edge_id.as_str()).collect();
    assert_eq!(
        ids,
        vec![E_ALPHA_GAMMA_WIKI, E_ALPHA_BETA_WIKI, E_ALPHA_BETA_DIR],
        "direction=out follows src → dst only"
    );

    req.direction = GraphDirection::In;
    let inn = idx.graph_expand(&req).expect("in expand");
    let ids: Vec<&str> = inn.edges.iter().map(|e| e.edge_id.as_str()).collect();
    assert_eq!(
        ids,
        vec![E_DELTA_ALPHA_WIKI],
        "direction=in follows dst → src only"
    );

    req.direction = GraphDirection::Both;
    req.types = Some(vec!["wikilink".to_string()]);
    let typed = idx.graph_expand(&req).expect("typed expand");
    let ids: Vec<&str> = typed.edges.iter().map(|e| e.edge_id.as_str()).collect();
    assert_eq!(
        ids,
        vec![E_ALPHA_GAMMA_WIKI, E_ALPHA_BETA_WIKI, E_DELTA_ALPHA_WIKI],
        "types allowlist keeps only wikilink edges"
    );
    assert_eq!(
        typed.stats.type_filtered, 1,
        "the dropped same_dir edge is counted"
    );
}

//! Regression test for #177 — a `highlight` block must not change `_score`
//! or hit order.
//!
//! `highlight` is a presentation concern: it is applied by `apply_highlight`
//! as a post-pass over the already-selected, already-scored page.  On the
//! pre-fix build its mere presence widened the executor's `materialisation_limit`
//! (the arrival-order cap on the bounded hit collector), and because the
//! cross-segment merge admitted hits FIFO rather than by score, a wider cap
//! produced a *different* page.  Adding `"highlight"` therefore changed every
//! `_score` and reordered — indeed replaced — the hits.
//!
//! The test builds two segments where the second holds the genuinely
//! top-scoring documents and the first holds enough matches to fill a small
//! page on its own, then asserts:
//!   1. the page is the same with and without `highlight` (ids + scores), and
//!   2. that page is the true global top-k (matches a full-materialisation
//!      run at `size` >= total matches), and
//!   3. highlighting still produces fragments containing the matched term.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn body(size: usize, highlight: bool) -> xerj_query::ast::SearchRequest {
    let mut b = json!({
        "size": size,
        "query": {"match": {"body": "quicklist"}}
    });
    if highlight {
        b.as_object_mut()
            .unwrap()
            .insert("highlight".into(), json!({"fields": {"body": {}}}));
    }
    parse_request(&b).expect("parse_request")
}

/// `(id, score)` page fingerprint.
fn page(hits: &[xerj_query::Hit]) -> Vec<(String, f32)> {
    hits.iter().map(|h| (h.id.clone(), h.score)).collect()
}

#[tokio::test]
async fn highlight_block_does_not_change_scores_or_order() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("hl", Schema::empty()).unwrap();
    let idx = engine.get_index("hl").unwrap();

    // ── Segment 0: 60 long, weakly-matching docs ─────────────────────────
    // One occurrence of the term buried in a long body → low BM25 (long
    // field norm).  60 of them is more than enough to fill a size:5 page on
    // its own, which is exactly what the pre-fix FIFO merge did.
    let filler =
        "the server allocates a buffer and appends the reply object to the client output list "
            .repeat(12);
    for i in 0..60 {
        idx.index_document(
            Some(format!("weak{i:02}")),
            json!({"body": format!("{filler} quicklist {filler}")}),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    // ── Segment 1: 5 short, strongly-matching docs ───────────────────────
    // Short field + repeated term → high BM25.  These are the true top-5.
    // Strictly decreasing term frequency keeps the ranking tie-free, so
    // "the top-5" has exactly one right answer.
    for i in 0..5 {
        let body = "quicklist ".repeat(10 - i) + &"filler ".repeat(i * 4);
        idx.index_document(Some(format!("strong{i}")), json!({"body": body}))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    // Ground truth: materialise every match, then take the top 5.
    let full = idx.search(&body(200, false)).await.unwrap();
    assert_eq!(full.total.value, 65, "all 65 docs match");
    let mut truth = page(&full.hits);
    truth.truncate(5);
    assert!(
        truth.iter().all(|(id, _)| id.starts_with("strong")),
        "sanity: the 5 short docs must be the global top-5, got {truth:?}"
    );

    // ── The invariant under test ─────────────────────────────────────────
    let plain = idx.search(&body(5, false)).await.unwrap();
    let lit = idx.search(&body(5, true)).await.unwrap();

    assert_eq!(
        page(&plain.hits),
        page(&lit.hits),
        "adding a `highlight` block changed the page: without={:?} with={:?}",
        page(&plain.hits),
        page(&lit.hits)
    );
    assert_eq!(
        page(&plain.hits),
        truth,
        "size:5 page is not the global top-5"
    );
    assert_eq!(
        plain.total.value, lit.total.value,
        "`highlight` changed hits.total"
    );

    // ── ...and highlighting still highlights ─────────────────────────────
    for h in &lit.hits {
        let frags = h
            .highlight
            .as_ref()
            .and_then(|m| m.get("body"))
            .unwrap_or_else(|| panic!("hit {} has no `body` highlight", h.id));
        assert!(!frags.is_empty(), "hit {} has zero fragments", h.id);
        assert!(
            frags.iter().any(|f| f.contains("<em>quicklist</em>")),
            "hit {} fragments do not mark the matched term: {frags:?}",
            h.id
        );
    }
    assert!(
        plain.hits.iter().all(|h| h.highlight.is_none()),
        "hits carried a `highlight` key without a highlight block"
    );
}

/// The same invariant one level up, through the ES `_search` request shape
/// used in the issue: `multi_match` over several fields, with the highlight
/// block naming a concrete field.
#[tokio::test]
async fn highlight_block_does_not_change_multi_match_ranking() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("hl2", Schema::empty()).unwrap();
    let idx = engine.get_index("hl2").unwrap();

    let filler =
        "generic prose about clients connections buffers and replies that dilutes the term "
            .repeat(10);
    for i in 0..40 {
        idx.index_document(
            Some(format!("weak{i:02}")),
            json!({"title": format!("file {i}"), "body": format!("{filler} listpack {filler}")}),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    // Strictly decreasing term frequency → strictly decreasing scores, so the
    // top-3 is unambiguous (a tie straddling the page boundary is a different
    // question — which of several equal-scoring docs to keep — and not what
    // this test is about).
    //
    // The tf must decrease in BOTH fields, not just `body`.  `multi_match`
    // defaults to `best_fields`, i.e. the MAX over the per-field scores, and
    // since #188 made BM25 statistics index-wide the winning field here is
    // `title`: every one of the 44 documents has "listpack" in its body, so
    // the body IDF collapses to ln(1 + 0.5/44.5) = 0.0112, while only the 4
    // strong docs have it in the title (IDF = ln(10) = 2.303).  A constant
    // `"title": "listpack"` therefore gave all four strong docs the SAME
    // 2.859662 and put a 4-way tie across the size:3 page boundary.  (Before
    // #188 the strong docs were alone in their own segment, where both fields
    // had df == N == 4 and the longer body won the max — which is exactly the
    // per-segment-statistics artefact #188 removed.)
    for i in 0..4 {
        let body = "listpack ".repeat(8 - i) + &"filler ".repeat(i * 6);
        idx.index_document(
            Some(format!("strong{i}")),
            json!({"title": "listpack ".repeat(4 - i), "body": body}),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    let mk = |size: usize, highlight: bool| {
        let mut b = json!({
            "size": size,
            "query": {"multi_match": {"query": "listpack", "fields": ["body", "title"]}}
        });
        if highlight {
            b.as_object_mut()
                .unwrap()
                .insert("highlight".into(), json!({"fields": {"body": {}}}));
        }
        parse_request(&b).expect("parse_request")
    };

    let full = idx.search(&mk(200, false)).await.unwrap();
    let mut truth = page(&full.hits);
    truth.truncate(3);

    let plain = idx.search(&mk(3, false)).await.unwrap();
    let lit = idx.search(&mk(3, true)).await.unwrap();

    assert_eq!(
        page(&plain.hits),
        page(&lit.hits),
        "multi_match: `highlight` changed the page"
    );
    assert_eq!(page(&plain.hits), truth, "multi_match: page is not top-3");
}

/// Selection must not depend on the page size either: the top-1 of a
/// `size:1` request is the top-1 of a `size:200` request.  This is the same
/// arrival-order-cap defect seen from the other side, and it is what made
/// `highlight` (which only widened the cap) look like a scoring knob.
#[tokio::test]
async fn top_hit_is_stable_across_page_sizes() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("hl3", Schema::empty()).unwrap();
    let idx = engine.get_index("hl3").unwrap();

    let filler = "padding words that make the field long and the norm large ".repeat(10);
    for i in 0..80 {
        idx.index_document(
            Some(format!("weak{i:02}")),
            json!({"body": format!("{filler} ziplist")}),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    idx.index_document(Some("best".into()), json!({"body": "ziplist ziplist"}))
        .await
        .unwrap();
    idx.flush().await.unwrap();

    let q = |size: usize| -> xerj_query::ast::SearchRequest {
        parse_request(&json!({"size": size, "query": {"match": {"body": "ziplist"}}}))
            .expect("parse_request")
    };

    let deep = idx.search(&q(200)).await.unwrap();
    let expected: Value = json!([deep.hits[0].id.clone(), deep.hits[0].score]);
    assert_eq!(deep.hits[0].id, "best", "sanity: `best` is the top hit");

    for size in [1usize, 2, 5, 10, 50] {
        let r = idx.search(&q(size)).await.unwrap();
        let got: Value = json!([r.hits[0].id.clone(), r.hits[0].score]);
        assert_eq!(got, expected, "size:{size} returned a different top hit");
    }
}

//! Issue #1819: `histogram` `extended_bounds` must only ADD empty buckets.
//! Buckets holding data outside the bounds stay, as in Elasticsearch 8.13.4;
//! only `hard_bounds` drops them.
//!
//! ROOT CAUSE: both executors picked the gap-fill range as
//! `extended_min.or(data_min)` / `extended_max.or(data_max)` — the bound
//! *instead of* the wider of the bound and the data — so a bound inside the
//! data range clipped the buckets on either side of it, the same as
//! `hard_bounds`. The brute runner (`aggs::run_histogram`) and its columnar
//! mirror (`fast_aggs::exec_histogram`) carried the same two lines.
//! `date_histogram` already widened (`range_min.min(key)` /
//! `range_max.max(key)`), which is why it matched ES.
//!
//! Both executors are pinned: the columnar path only serves an index at or
//! above `fast_aggs::FAST_AGG_MIN_DOCS` (10 000 docs), so the same values are
//! indexed once below that gate and once above it, and
//! `aggs::fast_path_aggs_served` says which executor answered. That counter
//! is process-global, so this is deliberately ONE test function.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::aggs::fast_path_aggs_served;
use xerj_engine::bulk::process_bulk;
use xerj_engine::Engine;
use xerj_query::parse_request;

/// One case: the histogram agg, the expected (key, doc_count) buckets, and a label.
type HistogramCase = (Value, Vec<(i64, u64)>, &'static str);

/// The #1819 reproduction's values. ES 8.13.4, `interval: 5`,
/// `extended_bounds: {min: 0, max: 10}`:
/// `-5:1, 0:2, 5:0, 10:1, 15:0, 20:0, 25:1`.
const VALUES: [f64; 5] = [-2.0, 1.0, 3.0, 12.0, 27.0];

/// Below the columnar gate: one copy of the values.
const SMALL_DOCS: usize = VALUES.len();
/// Above the columnar gate: 2 010 copies of the values (10 050 docs), so
/// every expected count is the ES count times `BIG_REPEAT`.
const BIG_REPEAT: usize = 2_010;

async fn build_index(engine: &Engine, name: &str, docs: usize) {
    engine.create_index(name, Schema::empty()).unwrap();
    for start in (0..docs).step_by(1_000) {
        let end = (start + 1_000).min(docs);
        let mut body = String::new();
        for i in start..end {
            body.push_str(&format!(
                "{{\"index\":{{\"_index\":\"{name}\",\"_id\":\"{i}\"}}}}\n"
            ));
            body.push_str(&format!("{{\"v\":{}}}\n", VALUES[i % VALUES.len()]));
        }
        let res = process_bulk(engine, Some(name), &body).await;
        assert!(!res.errors, "bulk errors while seeding {name}");
    }
    // The columnar path reads segment `.dv` sidecars; flush both indices so
    // the only difference between them is the size gate.
    engine.get_index(name).unwrap().refresh().await.unwrap();
}

/// `(key, doc_count)` pairs of one `size:0` histogram, and whether the
/// columnar fast path served it.
async fn histogram(engine: &Engine, index: &str, agg: Value) -> (Vec<(i64, u64)>, u64) {
    let idx = engine.get_index(index).unwrap();
    let req = parse_request(&json!({
        "query": {"match_all": {}},
        "size": 0,
        "aggs": {"h": agg},
    }))
    .unwrap();
    let before = fast_path_aggs_served();
    let res = idx.search(&req).await.unwrap();
    let served = fast_path_aggs_served() - before;
    let aggs = res.aggs.clone().expect("aggs present");
    let buckets = aggs["h"]["buckets"]
        .as_array()
        .unwrap_or_else(|| panic!("expected buckets, got {aggs}"))
        .iter()
        .map(|b| {
            (
                b["key"].as_f64().expect("numeric key") as i64,
                b["doc_count"].as_u64().expect("doc_count"),
            )
        })
        .collect();
    (buckets, served)
}

fn scaled(expected: &[(i64, u64)], by: usize) -> Vec<(i64, u64)> {
    expected.iter().map(|&(k, n)| (k, n * by as u64)).collect()
}

#[tokio::test]
async fn extended_bounds_keeps_data_buckets_outside_the_bounds_on_both_executors() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine::new");

    build_index(&engine, "small", SMALL_DOCS).await;
    build_index(&engine, "big", VALUES.len() * BIG_REPEAT).await;

    // (agg, expected buckets for ONE copy of VALUES, what the case pins)
    let cases: Vec<HistogramCase> = vec![
        (
            json!({"histogram": {"field": "v", "interval": 5,
                                 "extended_bounds": {"min": 0, "max": 10}}}),
            vec![(-5, 1), (0, 2), (5, 0), (10, 1), (15, 0), (20, 0), (25, 1)],
            "#1819: bounds inside the data keep the data on both sides",
        ),
        (
            json!({"histogram": {"field": "v", "interval": 5,
                                 "extended_bounds": {"min": -20, "max": 40}}}),
            vec![
                (-20, 0),
                (-15, 0),
                (-10, 0),
                (-5, 1),
                (0, 2),
                (5, 0),
                (10, 1),
                (15, 0),
                (20, 0),
                (25, 1),
                (30, 0),
                (35, 0),
                (40, 0),
            ],
            "bounds wider than the data still add empty buckets",
        ),
        (
            json!({"histogram": {"field": "v", "interval": 5,
                                 "extended_bounds": {"min": 10}}}),
            vec![(-5, 1), (0, 2), (5, 0), (10, 1), (15, 0), (20, 0), (25, 1)],
            "a min-only bound above the data min drops nothing",
        ),
        (
            json!({"histogram": {"field": "v", "interval": 5,
                                 "hard_bounds": {"min": 0, "max": 10}}}),
            vec![(0, 2), (5, 0), (10, 1)],
            "hard_bounds still drops buckets outside it (unchanged)",
        ),
    ];

    for (agg, expected, what) in cases {
        let (got, served) = histogram(&engine, "small", agg.clone()).await;
        assert_eq!(served, 0, "the small index must take the brute path");
        assert_eq!(got, expected, "brute path: {what}: {agg}");

        let (got, served) = histogram(&engine, "big", agg.clone()).await;
        assert_eq!(served, 1, "the big index must take the columnar path");
        assert_eq!(
            got,
            scaled(&expected, BIG_REPEAT),
            "columnar path: {what}: {agg}"
        );
    }
}

//! Regression test for #940 — a `hybrid` page must be a function of the index,
//! not of the process that served it.
//!
//! Tied fused scores are structural under RRF, not an edge case: a document
//! found only by leg A at rank r and one found only by leg B at rank r both
//! score exactly `w/(k+r)`. `fuse_rrf`/`fuse_linear` used to accumulate into a
//! `HashMap` and drain it into a score-only stable sort, so every such tie
//! came out in hash-iteration order, and `std`'s `RandomState` is seeded per
//! process. Measured on BEIR SciFact (issue #940): after a restart on
//! unchanged data 32 of 40 queries changed order and 21 of 40 changed their
//! top 10, with identical hit sets.
//!
//! The order asserted here is the ONE total order every score-ranked page
//! uses (#270): `score DESC, seq_no ASC (arrival), _id ASC`.
//!
//! Two things this test is careful about:
//!
//!   * **The result cache.** `Index::query_cache` is keyed by
//!     `(query hash, dataset version)`, so a repeated request is served from
//!     it without re-running fusion — which is why the issue's own in-process
//!     repeats looked stable. It is cleared before every search below; a test
//!     that did not would pass against the broken code.
//!   * **`_id` order is not arrival order.** Documents are written in a
//!     scrambled order, so a fix that tied on `_id` alone — or any order that
//!     merely happened to be repeatable — fails the arrival assertion.

use std::collections::HashMap;
use std::sync::Arc;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::index::Index;
use xerj_engine::Engine;
use xerj_query::parse_request;

const INDEX: &str = "hy940";
/// Documents per leg. Each rank r in 0..PER_LEG yields one exact tie pair.
const PER_LEG: usize = 12;
/// Tokens per document — constant, so BM25's length normalisation is the
/// same for every document and the score is a function of `tf` alone.
const DOC_LEN: usize = 16;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn hybrid(fusion: Value) -> Value {
    json!({
        "hybrid": {
            "queries": [
                { "query": { "match": { "body": "alpha" } }, "weight": 1.0 },
                { "query": { "match": { "body": "beta"  } }, "weight": 1.0 }
            ],
            "fusion": fusion
        }
    })
}

fn rrf() -> Value {
    hybrid(json!({ "type": "rrf", "k": 60 }))
}

fn linear() -> Value {
    hybrid(json!("linear"))
}

/// `word` repeated `tf` times, padded with a filler token to `DOC_LEN`.
fn body(word: &str, tf: usize) -> String {
    let mut tokens = vec![word; tf];
    tokens.resize(DOC_LEN, "filler");
    tokens.join(" ")
}

/// A symmetric two-leg corpus: `a-<r>` holds "alpha" `PER_LEG - r` times and
/// `b-<r>` holds "beta" the same number of times, so inside each leg the
/// scores are DISTINCT and strictly decreasing in r (the leg's rank order
/// owes nothing to any tie-break), while across legs `a-<r>` and `b-<r>`
/// sit at the same rank and tie exactly after fusion.
///
/// Written in a scrambled order. Returns id → arrival position.
async fn symmetric_corpus(idx: &Arc<Index>) -> HashMap<String, usize> {
    let mut ids: Vec<(String, String)> = Vec::new();
    for r in 0..PER_LEG {
        ids.push((format!("a-{r:02}"), body("alpha", PER_LEG - r)));
        ids.push((format!("b-{r:02}"), body("beta", PER_LEG - r)));
    }
    // A fixed permutation (multiplication by 7 is a bijection mod 24), so
    // arrival order agrees with neither `_id` order nor rank order — and
    // within a tie pair it is `a` first for some ranks and `b` first for
    // others.
    let n = ids.len();
    let mut arrival = HashMap::new();
    for pos in 0..n {
        let (id, text) = ids[(pos * 7 + 5) % n].clone();
        idx.index_document(Some(id.clone()), json!({ "body": text }))
            .await
            .unwrap();
        arrival.insert(id, pos);
    }
    assert_eq!(
        arrival.len(),
        n,
        "the permutation must visit every document"
    );
    arrival
}

/// One uncached hybrid search → `(id, score bits)` per hit.
async fn page(idx: &Arc<Index>, from: usize, size: usize, q: &Value) -> Vec<(String, u32)> {
    idx.query_cache.clear();
    let req = parse_request(&json!({ "from": from, "size": size, "query": q })).unwrap();
    let res = idx.search(&req).await.unwrap();
    res.hits
        .into_iter()
        .map(|h| (h.id, h.score.to_bits()))
        .collect()
}

/// Inside every run of bit-identical scores, hits must be in arrival order.
fn assert_ties_are_in_arrival_order(
    label: &str,
    hits: &[(String, u32)],
    arrival: &HashMap<String, usize>,
) {
    for w in hits.windows(2) {
        if w[0].1 == w[1].1 {
            assert!(
                arrival[&w[0].0] < arrival[&w[1].0],
                "{label}: {} and {} tie on score but are not in arrival order \
                 (arrived {} and {}) — full page: {hits:?}",
                w[0].0,
                w[1].0,
                arrival[&w[0].0],
                arrival[&w[1].0],
            );
        }
    }
}

/// The page RRF must return for `symmetric_corpus`: rank by rank, and inside
/// each rank's tie pair the document that arrived first.
fn expected_rrf_order(arrival: &HashMap<String, usize>) -> Vec<String> {
    let mut out = Vec::new();
    for r in 0..PER_LEG {
        let mut pair = [format!("a-{r:02}"), format!("b-{r:02}")];
        pair.sort_by_key(|id| arrival[id]);
        out.extend(pair);
    }
    out
}

fn ids_of(hits: &[(String, u32)]) -> Vec<String> {
    hits.iter().map(|(id, _)| id.clone()).collect()
}

/// Everything a paginating client relies on, checked against one open index.
async fn assert_fused_pages(label: &str, idx: &Arc<Index>, arrival: &HashMap<String, usize>) {
    let n = 2 * PER_LEG;
    let expected = expected_rrf_order(arrival);

    // ── RRF ──────────────────────────────────────────────────────────────
    let full = page(idx, 0, n, &rrf()).await;
    assert_eq!(full.len(), n, "{label}: both legs fully retrieved");
    // The fixture really does tie at every rank — otherwise this test would
    // pass against the broken code and prove nothing.
    for (r, pair) in full.chunks(2).enumerate() {
        assert_eq!(
            pair[0].1, pair[1].1,
            "{label}: rank {r} must be an EXACT fused tie, got {pair:?}"
        );
    }
    assert_eq!(
        ids_of(&full),
        expected,
        "{label}: tied fused scores must resolve by arrival order"
    );

    // Re-running fusion must reproduce the page. 32 uncached repeats: under
    // the old per-map `RandomState` the 12 tie pairs agreed between two runs
    // with probability 2^-12.
    for run in 0..32 {
        assert_eq!(
            page(idx, 0, n, &rrf()).await,
            full,
            "{label}: uncached repeat {run} returned a different page"
        );
    }

    // Every bounded page is a prefix of the full page …
    for size in 1..=n {
        assert_eq!(
            page(idx, 0, size, &rrf()).await,
            full[..size],
            "{label}: size:{size} disagrees with the full page"
        );
    }
    // … and walking it with `from` reproduces it, including the pages whose
    // boundary falls INSIDE a tie pair (every odd `from`). `from + size`
    // stays under the 50-deep leg window, so every page fuses the same legs.
    for size in [1usize, 3, 5] {
        let mut walked = Vec::new();
        let mut from = 0;
        while from < n {
            walked.extend(page(idx, from, size, &rrf()).await);
            from += size;
        }
        assert_eq!(
            walked, full,
            "{label}: paging by {size} reorders the corpus"
        );
    }

    // ── Linear ───────────────────────────────────────────────────────────
    // Same accumulator, same defect. The legs are symmetric, so min-max
    // normalisation maps `a-<r>` and `b-<r>` to the same value and they tie
    // here too; the assertion is the general one so it does not depend on
    // that.
    let lin = page(idx, 0, n, &linear()).await;
    assert_eq!(lin.len(), n, "{label}: linear retrieves both legs");
    assert_ties_are_in_arrival_order(&format!("{label}/linear"), &lin, arrival);
    assert!(
        lin.windows(2).any(|w| w[0].1 == w[1].1),
        "{label}: the linear fixture is expected to tie somewhere, got {lin:?}"
    );
    for run in 0..32 {
        assert_eq!(
            page(idx, 0, n, &linear()).await,
            lin,
            "{label}: linear uncached repeat {run} returned a different page"
        );
    }
}

/// Flushed data: the page is the same before the restart, after it, and after
/// the one after that.
#[tokio::test]
async fn hybrid_page_survives_restarts_on_flushed_data() {
    let dir = TempDir::new().unwrap();
    let arrival;
    let before;
    {
        let engine = make_engine(&dir);
        engine.create_index(INDEX, Schema::empty()).unwrap();
        let idx = engine.get_index(INDEX).unwrap();
        arrival = symmetric_corpus(&idx).await;
        idx.flush().await.unwrap();
        assert_fused_pages("flushed", &idx, &arrival).await;
        before = (
            page(&idx, 0, 2 * PER_LEG, &rrf()).await,
            page(&idx, 0, 2 * PER_LEG, &linear()).await,
        );
        drop(idx);
        drop(engine);
    }
    for restart in 1..=3 {
        let engine = make_engine(&dir);
        let idx = engine.get_index(INDEX).unwrap();
        let label = format!("flushed/restart-{restart}");
        assert_fused_pages(&label, &idx, &arrival).await;
        let after = (
            page(&idx, 0, 2 * PER_LEG, &rrf()).await,
            page(&idx, 0, 2 * PER_LEG, &linear()).await,
        );
        assert_eq!(after, before, "{label}: page changed across a restart");
        drop(idx);
        drop(engine);
    }
}

/// Unflushed data: after the restart the documents come back through WAL
/// replay into the memtable, a different read path from the segments above.
#[tokio::test]
async fn hybrid_page_survives_restarts_on_unflushed_data() {
    let dir = TempDir::new().unwrap();
    let arrival;
    let before;
    {
        let engine = make_engine(&dir);
        engine.create_index(INDEX, Schema::empty()).unwrap();
        let idx = engine.get_index(INDEX).unwrap();
        arrival = symmetric_corpus(&idx).await;
        assert_fused_pages("memtable", &idx, &arrival).await;
        before = page(&idx, 0, 2 * PER_LEG, &rrf()).await;
        drop(idx);
        drop(engine);
    }
    for restart in 1..=2 {
        let engine = make_engine(&dir);
        let idx = engine.get_index(INDEX).unwrap();
        let label = format!("memtable/restart-{restart}");
        assert_fused_pages(&label, &idx, &arrival).await;
        assert_eq!(
            page(&idx, 0, 2 * PER_LEG, &rrf()).await,
            before,
            "{label}: page changed across a restart"
        );
        drop(idx);
        drop(engine);
    }
}

/// A flush in the middle moves half the corpus to segments. Arrival order is
/// a property of the documents, not of where they are stored, so the page
/// must not notice.
#[tokio::test]
async fn hybrid_page_does_not_depend_on_where_the_documents_are_stored() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index(INDEX, Schema::empty()).unwrap();
    let idx = engine.get_index(INDEX).unwrap();
    let arrival = symmetric_corpus(&idx).await;

    let in_memtable = page(&idx, 0, 2 * PER_LEG, &rrf()).await;
    idx.flush().await.unwrap();
    let in_segments = page(&idx, 0, 2 * PER_LEG, &rrf()).await;

    assert_eq!(ids_of(&in_memtable), expected_rrf_order(&arrival));
    assert_eq!(
        ids_of(&in_segments),
        ids_of(&in_memtable),
        "a flush reordered a hybrid page"
    );
}

//! Regression test for #1303 — a request carrying BOTH a `query` and a `knn`
//! clause must keep returning the documented Elasticsearch hybrid ranking
//! (per-hit SUM of the two scores) EVEN on an index that has seen an
//! overwrite/delete.
//!
//! ## The bug
//!
//! The ES-compat layer folds a top-level `knn` beside a `query` into
//! `bool{should:[query, knn]}`, and the engine pre-executes the knn leg and
//! splices its top-k back as a `Bool{should:[Constant{score, Ids}…],
//! filter:[Ids]}` sub-tree (#825). #892 then made that sub-tree project to an
//! inverted-index `DocScores` leaf so the whole compound serves the union
//! through the normal FTS path with exact BM25 on the lexical half and the
//! vector scores summed in — BUT it gated that projection on
//! `!deletes_present`. On any index that had ever taken an overwrite or
//! delete (`ghost_events() > 0`, monotonic and global — the common case for a
//! re-indexed corpus) the pinned `Ids` sub-tree could not project, the WHOLE
//! hybrid query `?`-aborted the projection, and every segment fell to the
//! stored-doc scan. That scan scores a `multi_match` with a crude
//! page/heuristic score, not index-wide BM25, so the hybrid returned a flat,
//! id-ordered ranking that belonged to NEITHER half — exactly #1303's
//! "`_score` ~4.4 matching neither the BM25 range nor the cosine range, with
//! unrelated documents at the top".
//!
//! The bug is INVISIBLE on a 3-document probe (the reporter's note): with a
//! handful of docs every lexical match shares the same page-local score, so
//! the flat heuristic happens to agree with BM25. It only shows once the
//! corpus is large enough that index-wide BM25 differs from the page. This
//! test therefore uses a few thousand documents.
//!
//! ## What is asserted
//!
//! On a 3000-doc index that has been overwritten (so `deletes_present`):
//!   1. the lexical half keeps EXACT index-wide BM25 — every lexical-only hit
//!      in the hybrid carries the same `_score` it has in the pure-lexical
//!      query, not a flat constant;
//!   2. the one document reached by BOTH halves scores the SUM
//!      (`bm25 + knn`) and leads the page;
//!   3. the live (post-overwrite) `_source` is served, never a stale ghost.
//!
//! FAIL-BEFORE: with the `!deletes_present` gate on `pinned_probe` restored,
//! the hybrid page is flat ~1.0 id-ordered and assertion (1) reports the
//! lexical hits scored ~1.0 instead of their BM25 value.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

const N: usize = 3000;
/// The top vector neighbour, also made a lexical match → reached by BOTH halves.
const BOTH: usize = 2999;

fn body(i: usize) -> String {
    // The lexical probe "zebra" lands on every 50th doc AND on the top vector
    // neighbour. Identical text everywhere → identical (tied) BM25, so the
    // ordering is deterministic regardless of shard/segment topology (#188).
    if i.is_multiple_of(50) || i == BOTH {
        "zebra lexical probe".to_string()
    } else {
        "common filler text".to_string()
    }
}

fn vec_for(i: usize) -> Vec<f32> {
    // Smooth distinct fan [t, 1-t]; query [1,0] → the highest index is the
    // nearest neighbour.
    let t = i as f32 / N as f32;
    vec![t, 1.0 - t]
}

async fn page(idx: &std::sync::Arc<Index>, b: &serde_json::Value) -> Vec<(String, f32)> {
    let req = parse_request(b).unwrap();
    let res = idx.search(&req).await.unwrap();
    res.hits.iter().map(|h| (h.id.clone(), h.score)).collect()
}

#[tokio::test]
async fn hybrid_knn_query_keeps_bm25_scoring_under_deletes() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).unwrap();

    let mut schema = Schema::empty();
    schema
        .add_field(FieldConfig::new("body", FieldType::Text))
        .unwrap();
    let mut v = FieldConfig::new("vec", FieldType::Vector);
    v.options.dimensions = Some(2);
    schema.add_field(v).unwrap();
    engine.create_index("hy1303", schema).unwrap();
    let idx = engine.get_index("hy1303").unwrap();

    for i in 0..N {
        idx.index_document(
            Some(format!("d{i}")),
            json!({ "body": body(i), "vec": vec_for(i) }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    // Overwrite a handful of documents (including the both-halves neighbour,
    // tagged with a stored marker) so `ghost_events() > 0` and the index is
    // `deletes_present` — the condition under which #1303 bit. The overwrite
    // keeps `body` byte-identical, so BM25 is unchanged.
    for i in [50usize, 100, 150, 200] {
        idx.index_document(
            Some(format!("d{i}")),
            json!({ "body": body(i), "vec": vec_for(i) }),
        )
        .await
        .unwrap();
    }
    idx.index_document(
        Some(format!("d{BOTH}")),
        json!({ "body": body(BOTH), "vec": vec_for(BOTH), "marker": "live" }),
    )
    .await
    .unwrap();
    idx.flush().await.unwrap();

    // Pure-lexical reference: every "zebra" doc shares one tied BM25 score.
    let lex = json!({
        "size": 10, "track_total_hits": true,
        "query": {"bool": {"should": [
            {"multi_match": {"query": "zebra", "fields": ["body"]}}
        ]}}
    });
    // kNN leg alone (lexical clause matches nothing) → the vector score of the
    // top neighbour.
    let knn_only = json!({
        "size": 10, "track_total_hits": true,
        "query": {"bool": {"should": [
            {"multi_match": {"query": "zzzznomatch", "fields": ["body"]}},
            {"knn": {"field": "vec", "query_vector": [1.0, 0.0], "k": 5, "num_candidates": 500}}
        ]}}
    });
    // The hybrid: the folded shape the ES-compat layer produces for
    // `query` + `knn`.
    let hybrid = json!({
        "size": 10, "track_total_hits": true,
        "query": {"bool": {"should": [
            {"multi_match": {"query": "zebra", "fields": ["body"]}},
            {"knn": {"field": "vec", "query_vector": [1.0, 0.0], "k": 5, "num_candidates": 500}}
        ]}}
    });

    let lex_page = page(&idx, &lex).await;
    let knn_page = page(&idx, &knn_only).await;
    let hybrid_page = page(&idx, &hybrid).await;

    // The tied BM25 score of a "zebra" document (all equal — identical text).
    let bm25 = lex_page[0].1;
    assert!(
        bm25 > 3.0,
        "sanity: index-wide BM25 for the probe term should be well above the \
         ~1.0 knn constant, got {bm25} (lex={lex_page:?})"
    );
    assert!(
        lex_page.iter().all(|(_, s)| (*s - bm25).abs() < 1e-4),
        "sanity: the identical-text lexical matches must all tie: {lex_page:?}"
    );

    // The top vector neighbour and its score.
    assert_eq!(
        knn_page[0].0,
        format!("d{BOTH}"),
        "sanity: d{BOTH} must be the nearest neighbour: {knn_page:?}"
    );
    let knn_score = knn_page[0].1;
    assert!(
        (0.9..=1.0001).contains(&knn_score),
        "sanity: cosine of the nearest neighbour should be ~1.0, got {knn_score}"
    );

    // ── (2) the both-halves document leads with the SUMMED score ───────────
    assert_eq!(
        hybrid_page[0].0,
        format!("d{BOTH}"),
        "#1303: the document reached by BOTH halves must lead the hybrid page; \
         got {hybrid_page:?}"
    );
    let both_score = hybrid_page[0].1;
    assert!(
        (both_score - (bm25 + knn_score)).abs() < 1e-3,
        "#1303: the both-halves document must score the SUM bm25 ({bm25}) + knn \
         ({knn_score}) = {}, got {both_score} (hybrid={hybrid_page:?})",
        bm25 + knn_score
    );

    // ── (1) the lexical half keeps EXACT index-wide BM25 ───────────────────
    // Every lexical-only hit in the hybrid page (everything after the
    // both-halves leader) must carry the SAME BM25 score as the pure-lexical
    // query — NOT the flat ~1.0 stored-scan heuristic the bug produced.
    let lexical_tail: Vec<&(String, f32)> = hybrid_page
        .iter()
        .filter(|(id, _)| *id != format!("d{BOTH}"))
        .collect();
    assert!(
        lexical_tail.len() >= 5,
        "expected several lexical-only hits in the hybrid page: {hybrid_page:?}"
    );
    for (id, score) in &lexical_tail {
        assert!(
            (*score - bm25).abs() < 1e-4,
            "#1303: lexical hit {id} in the hybrid scored {score}, but its \
             index-wide BM25 is {bm25}; the knn clause must not rewrite the \
             lexical half (this is the flat-heuristic regression — the hybrid \
             fell to the stored-doc scan). hybrid={hybrid_page:?}"
        );
    }

    // ── (3) the LIVE (post-overwrite) source is served, never a ghost ──────
    let req = parse_request(&hybrid).unwrap();
    let res = idx.search(&req).await.unwrap();
    let leader = &res.hits[0];
    assert_eq!(leader.id, format!("d{BOTH}"));
    assert_eq!(
        leader.source.get("marker").and_then(|m| m.as_str()),
        Some("live"),
        "#1303: the pinned-knn route under deletes must serve the LIVE copy of \
         d{BOTH}, not a superseded segment ghost; source={:?}",
        leader.source
    );
}

//! Integration tests for xerj-engine.
//!
//! These tests exercise the full stack: Engine -> Index -> Storage + FTS.
//! Each test gets its own temporary directory so they can run in parallel.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{detect_log_format, Engine, LogFormat};
use xerj_query::ast::{QueryNode, SearchRequest};
use xerj_query::parse_request;

// ── Helpers ───────────────────────────────────────────────────────────────────

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

#[tokio::test]
async fn test_semantic_vectors_stay_stored_but_not_fts_indexed_after_merge_and_reopen() {
    fn collect_names(dir: &std::path::Path, out: &mut Vec<String>) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            if entry.file_type().unwrap().is_dir() {
                collect_names(&entry.path(), out);
            } else {
                out.push(entry.file_name().to_string_lossy().into_owned());
            }
        }
    }

    async fn assert_queries(idx: &xerj_engine::Index) {
        let semantic = idx
            .search(&make_search_with_source(
                json!({
                    "semantic": {"field": "content", "query": "quarterly liquidity", "k": 10}
                }),
                json!(true),
            ))
            .await
            .unwrap();
        assert_eq!(semantic.total.value, 2);
        assert!(semantic.hits.iter().all(|hit| {
            hit.source.get("custom_embedding").is_some()
                && hit.source.get("custom_embedding_chunks").is_some()
                && hit.passage.is_none()
                && hit.source.as_object().is_some_and(|source| {
                    source
                        .keys()
                        .all(|name| !name.starts_with("__xerj_passage_meta__"))
                })
        }));

        let lexical = idx
            .search(&make_search(json!({
                "match": {"content": "working capital"}
            })))
            .await
            .unwrap();
        assert_eq!(lexical.total.value, 2);

        let page = idx
            .search(&make_search(json!({
                "term": {"page": 7}
            })))
            .await
            .unwrap();
        assert_eq!(page.total.value, 1);
    }

    let dir = TempDir::new().unwrap();
    let mut schema = Schema::empty();
    let mut content = FieldConfig::new("content", FieldType::Text);
    content.options.dimensions = Some(16);
    content.options.similarity = Some("cosine".to_string());
    content.embedding = Some(xerj_common::types::EmbeddingConfig {
        endpoint: None,
        model: None,
        target_field: Some("custom_embedding".to_string()),
    });
    schema.fields.push(content);
    schema
        .fields
        .push(FieldConfig::new("page", FieldType::Long));

    {
        let engine = make_engine(&dir);
        engine.create_index("sem-fts-exclusion", schema).unwrap();
        let idx = engine.get_index("sem-fts-exclusion").unwrap();
        let long_body = format!(
            "quarterly liquidity evidence {}",
            "cash assets liabilities working capital ".repeat(80)
        );

        idx.index_document(Some("a".into()), json!({"content": long_body, "page": 7}))
            .await
            .unwrap();
        idx.refresh().await.unwrap();
        idx.index_document(Some("b".into()), json!({"content": long_body, "page": 8}))
            .await
            .unwrap();
        idx.refresh().await.unwrap();
        idx.force_merge(1).await.unwrap();

        assert_queries(&idx).await;
    }

    let mut names = Vec::new();
    collect_names(dir.path(), &mut names);
    assert!(names.iter().any(|name| name.ends_with(".content.fst")));
    assert!(names.iter().any(|name| name.ends_with(".page.fst")));
    assert!(!names
        .iter()
        .any(|name| name.ends_with(".custom_embedding.fst")));
    assert!(!names
        .iter()
        .any(|name| name.ends_with(".custom_embedding_chunks.fst")));
    assert!(!names
        .iter()
        .any(|name| name.contains("__xerj_passage_meta__")));

    let reopened = make_engine(&dir);
    let idx = reopened.get_index("sem-fts-exclusion").unwrap();
    assert_queries(&idx).await;
}

/// #328 — a USER-MAPPED `dense_vector` must contribute no lexical artifacts.
///
/// The `#12` fix above covers the vectors XERJ *generates* from a semantic
/// mapping. A field the user maps as `dense_vector` took a different route:
/// it is `indexed == true` (kNN needs the HNSW graph), so the `index: false`
/// arm of `memtable::fts_excluded_fields` never fired and the field's 128
/// floats were flattened to decimal strings and tokenised into a term
/// dictionary that no query path reads.
///
/// This pins all four halves of the fix:
///   * no `<seg>.emb.{fst,post,norms}` is written, at flush or after merge —
///     AND none for the `<field>_chunks` companion either. A `dense_vector`
///     never arrives alone: `passage_scored_vector_fields` gives every one of
///     them a `_chunks` multi-vector and a `__xerj_passage_meta__` sidecar, and
///     the companion is the bigger artifact of the two on a chunked corpus;
///   * kNN, `exists` and the lexical fields keep answering exactly as before;
///   * EVERY lexical leaf on the vector field answers 0, which is a BEHAVIOUR
///     CHANGE for a whole class of shapes rather than for one row. `main` sends
///     these to the stored-doc scan, which renders the float array back to
///     decimal text and matches against it, so `wildcard {emb:"0*"}` and
///     `fuzzy {emb:"0"~2}` answered ALL 300 documents, `prefix {emb:"0"}` 146,
///     `match_phrase_prefix {emb:"0"}` 50 and numeric `term`/`terms` 1 each.
///     None of that is a retrieval semantic anyone asked for and all of it is
///     now 0 — see the table in the (d) loop for the measured before/after;
///   * and neither does an EXPLICITLY-FIELDED lexical query. This is the one
///     the writer-side change cannot cover on its own and the one that fails
///     loudly: with the postings gone but no plan-time lowering,
///     `{"multi_match":{"query":"0","fields":["emb"]}}` returns EVERY document
///     instead of none, because the scan renders the float array to text and
///     every component contains a `0`. Measured on a 5,000-doc × 128-dim
///     corpus, post-`force_merge`, three source states (first call each, before
///     the result cache): `main` 0 hits / 0.409 ms, postings-removed-only
///     **5,000 hits** / 123.5 ms, this branch 0 hits / 0.012 ms. The same run
///     puts `{"term":{"emb":"<component>"}}` at 89.2 → 186.8 → 0.061 ms, all
///     three answering 0.
#[tokio::test]
async fn user_mapped_dense_vector_builds_no_fts_term_dictionary() {
    fn segment_files(dir: &std::path::Path) -> Vec<(String, u64)> {
        fn walk(dir: &std::path::Path, out: &mut Vec<(String, u64)>) {
            for entry in std::fs::read_dir(dir).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    walk(&entry.path(), out);
                } else {
                    out.push((
                        entry.file_name().to_string_lossy().into_owned(),
                        entry.metadata().unwrap().len(),
                    ));
                }
            }
        }
        let mut out = Vec::new();
        walk(dir, &mut out);
        out
    }

    const DIMS: usize = 128;
    const DOCS: usize = 300;

    let dir = TempDir::new().unwrap();
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("cat", FieldType::Keyword));
    schema.fields.push(FieldConfig::new("n", FieldType::Long));
    let mut emb = FieldConfig::new("emb", FieldType::Vector);
    emb.options.dimensions = Some(DIMS);
    emb.options.similarity = Some("cosine".to_string());
    schema.fields.push(emb);

    let engine = make_engine(&dir);
    engine.create_index("duprobe", schema).unwrap();
    let idx = engine.get_index("duprobe").unwrap();

    // Deterministic pseudo-random components with enough decimal digits that
    // each one is a distinct term — the shape that made the FST large.
    let component = |doc: usize, dim: usize| -> f64 {
        let h = (doc as u64)
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add((dim as u64).wrapping_mul(1_442_695_040_888_963_407));
        ((h >> 11) as f64 / (1u64 << 53) as f64 * 2.0) - 1.0
    };
    let mut first_vector = Vec::new();
    for d in 0..DOCS {
        let v: Vec<f64> = (0..DIMS).map(|dim| component(d, dim)).collect();
        if d == 0 {
            first_vector = v.clone();
        }
        idx.index_document(
            Some(format!("d{d}")),
            json!({
                "body": format!("quarterly liquidity evidence document number {d}"),
                "cat": if d % 2 == 0 { "even" } else { "odd" },
                "n": d,
                "emb": v,
                // The `_chunks` companion, i.e. the per-document MULTI-vector.
                // Present in the fixture because a chunked corpus is the shape
                // RFC #148 reports, and excluding only `emb` leaves this one
                // fully tokenised.
                "emb_chunks": [v, v],
            }),
        )
        .await
        .unwrap();
    }
    idx.refresh().await.unwrap();
    idx.force_merge(1).await.unwrap();

    let files = segment_files(dir.path());
    let bytes_of = |suffix: &str| -> u64 {
        files
            .iter()
            .filter(|(name, _)| name.ends_with(suffix))
            .map(|(_, len)| *len)
            .sum()
    };
    // Reported so the saving is a measured number in the log, not a claim.
    //
    // TWO totals, and only the second one is quotable. The whole data dir
    // includes the write-ahead log, whose tail is reclaimed asynchronously, so
    // it is NOT reproducible: the eight runs below printed a whole-dir total
    // between 1,069,604 B and 1,104,599 B, and earlier revisions of this test
    // have printed as little as 858,147 B, entirely because the surviving
    // `.wal` files vary by megabytes while the segment bytes do not move at
    // all. `durable-index` excludes `.wal` and is reproducible to ~500 B (the
    // run-to-run jitter in the HNSW `graph.bin`): eight runs on THIS revision
    // printed 857,265 / 857,529 / 857,533 / 857,545 / 857,549 / 857,657 /
    // 857,657 / 857,769 B — a 504 B spread. That range is what the CHANGELOG
    // quotes and the one the ceiling below pins. Re-measure all three places
    // together (here, `memtable.rs`'s table, `CHANGELOG.md`) if it moves.
    let whole_dir: u64 = files.iter().map(|(_, len)| *len).sum();
    let durable: u64 = files
        .iter()
        .filter(|(name, _)| !name.ends_with(".wal"))
        .map(|(_, len)| *len)
        .sum();
    eprintln!(
        "#328 lexical bytes: emb.fst={} emb.post={} emb.norms={} emb_chunks.fst={} | \
         body.fst={} body.post={} cat.fst={} n.fst={} | durable-index={durable} \
         whole-dir={whole_dir}",
        bytes_of(".emb.fst"),
        bytes_of(".emb.post"),
        bytes_of(".emb.norms"),
        bytes_of(".emb_chunks.fst"),
        bytes_of(".body.fst"),
        bytes_of(".body.post"),
        bytes_of(".cat.fst"),
        bytes_of(".n.fst"),
    );
    // The published saving, enforced. `origin/main` writes 3,249,323 B of
    // durable index for this fixture and this branch writes ~858 KB; the ceiling
    // sits three orders of magnitude clear of the jitter and still 2.2 MB below
    // `main`, so it is a real fail-before and not a golden-file trap. Watched
    // fail at exactly 3,249,323 with both source files reverted to `origin/main`.
    assert!(
        durable < 1_500_000,
        "durable index must lose the vector term dictionaries; got {durable} B \
         (`origin/main` writes 3,249,323 B for this fixture, this branch ~858 KB)"
    );

    for suffix in [
        ".emb.fst",
        ".emb.post",
        ".emb.norms",
        // The companion, and it is the BIGGER half. On this 300-doc fixture,
        // `main` writes `.emb.fst` = 796,274 B and `.emb_chunks.fst` =
        // 1,592,118 B; at 5,000 × 128 it is 13,256,659 B against 26,518,005 B.
        // Excluding the base name alone would leave more behind than it
        // removes.
        ".emb_chunks.fst",
        ".emb_chunks.post",
        ".emb_chunks.norms",
    ] {
        assert!(
            !files.iter().any(|(name, _)| name.ends_with(suffix)),
            "a dense_vector field must contribute no `{suffix}` artifact; got {:?}",
            files
                .iter()
                .filter(|(name, _)| name.contains(".emb"))
                .collect::<Vec<_>>()
        );
    }
    // The lexical fields are untouched — this is a per-type exclusion, not a
    // blanket one.
    for suffix in [".body.fst", ".cat.fst", ".n.fst"] {
        assert!(
            files.iter().any(|(name, _)| name.ends_with(suffix)),
            "lexical fields must keep their term dictionaries; missing {suffix}"
        );
    }

    // (a) kNN still answers from the HNSW graph.
    let knn = idx
        .search(
            &parse_request(&json!({
                "query": {"knn": {"field": "emb", "query_vector": first_vector, "k": 3}},
                "size": 10
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(knn.hits.len(), 3, "kNN must still retrieve neighbours");
    assert_eq!(
        knn.hits[0].id, "d0",
        "nearest neighbour must be the probe doc"
    );

    // (b) `exists` is answered from `_source` / doc values, never the postings.
    let exists = idx
        .search(&make_search(json!({"exists": {"field": "emb"}})))
        .await
        .unwrap();
    assert_eq!(exists.total.value, DOCS as u64);

    // (c) the lexical fields still match.
    let lexical = idx
        .search(&make_search(json!({"match": {"body": "liquidity"}})))
        .await
        .unwrap();
    assert_eq!(lexical.total.value, DOCS as u64);
    let kw = idx
        .search(&make_search(json!({"term": {"cat": "even"}})))
        .await
        .unwrap();
    assert_eq!(kw.total.value, (DOCS / 2) as u64);

    // (d) EVERY lexical leaf that names the vector field answers 0.
    //
    // This is a CLASS, not a list of individually interesting queries, and the
    // class is the behaviour change this fix ships. On `main` a lexical clause
    // on `emb` falls through the missing/oversized term dictionary onto the
    // stored-doc scan, which renders the float array back to decimal text and
    // matches against that text — so whether a shape answered 0 or answered
    // most of the corpus on `main` depended entirely on whether the rendered
    // decimals happened to contain the probe. Measured on THIS fixture with
    // both source files reverted to `origin/main` (300 docs × 128 dim, after
    // `force_merge(1)`), `main` → this branch:
    //
    //   term    {emb: <component>}   numeric  ..  1 →   0
    //   terms   {emb: [<component>]} numeric  ..  1 →   0
    //   prefix  {emb: "0"}                    .. 146 →   0
    //   wildcard{emb: "0*"}                   .. 300 →   0   (every document)
    //   fuzzy   {emb: {value:"0", fuzziness:2}} 300 →   0   (every document)
    //   match_phrase_prefix {emb: "0"}        ..  50 →   0
    //   prefix  {emb_chunks: "0"}             .. 146 →   0
    //   wildcard{emb_chunks: "0*"}            .. 300 →   0   (every document)
    //   fuzzy   {emb_chunks: {value:"0", …}}  .. 300 →   0   (every document)
    //
    // …and the shapes whose probe text simply never appeared in a rendered
    // float answered 0 on both sides. All of them are pinned below at 0, so
    // the class is closed rather than sampled: a `dense_vector` and its
    // `_chunks` companion have no lexical surface at all.
    //
    // The two halves of the fix cover DIFFERENT rows of that table, which is why
    // both are needed. Running the same loop with the write-side exclusion alone
    // (the plan-time lowering disabled in `search_inner`) leaves exactly four
    // shapes non-zero — numeric `term`/`terms` at 1 each and the two
    // `multi_match`es at 300 — while `prefix`/`wildcard`/`fuzzy`/
    // `match_phrase_prefix` are already 0, because a multi-term query has no
    // term dictionary left to enumerate. Reverting both files to `origin/main`
    // leaves nine non-zero. Both counts were watched.
    //
    // A POSITIVE component: a leading `-` is `query_string`'s NOT operator,
    // which would make the probe measure the parser rather than the field.
    let probe_num = first_vector
        .iter()
        .copied()
        .find(|v| *v > 0.0)
        .expect("fixture vector has a positive component");
    let probe = format!("{probe_num}");
    let mut lexical_leaks: Vec<String> = Vec::new();
    for q in [
        json!({"term": {"emb": probe}}),
        json!({"match": {"emb": probe}}),
        json!({"match": {"emb": "0.5"}}),
        json!({"query_string": {"query": probe}}),
        json!({"multi_match": {"query": probe, "fields": ["*"]}}),
        // Numeric `term` / `terms` / `range`.
        //
        // The first two answered 1 on `main`: the stored-doc scan's `Term` arm
        // matches any ELEMENT of a JSON array — "this document's vector happens
        // to contain this float". ES rejects `term` on a `dense_vector`
        // outright and Lucene gives a field with no terms an empty scorer, so 0
        // is the answer this pins.
        json!({"term": {"emb": probe_num}}),
        json!({"terms": {"emb": [probe_num]}}),
        json!({"terms": {"emb": [probe]}}),
        json!({"range": {"emb": {"gte": -2.0, "lte": 2.0}}}),
        // The MULTI-TERM leaves, and the loudest half of the class. A rendered
        // float almost always contains a `0` somewhere, so on `main` these
        // matched a large fraction of the corpus — `wildcard` and `fuzzy`
        // matched ALL 300 documents — purely as an artifact of decimal
        // rendering. Every one of them is a `field`-naming leaf in
        // `lower_lexically_typeless_clauses`'s first arm.
        json!({"prefix": {"emb": "0"}}),
        json!({"wildcard": {"emb": "0*"}}),
        json!({"fuzzy": {"emb": {"value": "0", "fuzziness": 2}}}),
        json!({"regexp": {"emb": "0.*"}}),
        json!({"match_phrase": {"emb": probe}}),
        json!({"match_phrase_prefix": {"emb": "0"}}),
        // EXPLICITLY-FIELDED forms — the half the writer-side change cannot
        // reach. Each of these names `emb` outright rather than expanding onto
        // it, so no `*`-expansion filter helps; without a plan-time lowering
        // they land on the stored-doc scan. The `multi_match` one is the
        // correctness failure, not merely a slow one: postings-removed-only,
        // it answers DOCS instead of 0.
        json!({"multi_match": {"query": "0", "fields": ["emb"]}}),
        json!({"simple_query_string": {"query": "0", "fields": ["emb"]}}),
        json!({"query_string": {"query": "0", "default_field": "emb"}}),
        // …and the `_chunks` companion, which is in the exclusion set for the
        // same reason and therefore needs the same lowering — including the
        // multi-term leaves, which matched 146 and 300 documents on `main`.
        json!({"term": {"emb_chunks": probe}}),
        json!({"prefix": {"emb_chunks": "0"}}),
        json!({"wildcard": {"emb_chunks": "0*"}}),
        json!({"fuzzy": {"emb_chunks": {"value": "0", "fuzziness": 2}}}),
        json!({"multi_match": {"query": "0", "fields": ["emb_chunks"]}}),
    ] {
        let hits = idx.search(&make_search(q.clone())).await.unwrap();
        // Accumulated rather than asserted per row, deliberately: this loop is
        // pinning a CLASS, so a regression report that names every shape that
        // came back non-zero is worth far more than one that stops at the first.
        if hits.total.value != 0 {
            lexical_leaks.push(format!("{q} → {} hits", hits.total.value));
        }
    }
    assert!(
        lexical_leaks.is_empty(),
        "a lexical query on a dense_vector (or its `_chunks` companion) must \
         match nothing; {} of the shapes above did not:\n  {}",
        lexical_leaks.len(),
        lexical_leaks.join("\n  ")
    );

    // (d2) a MIXED field list keeps its lexical members. Only the vector entry
    // is dropped, so this is `{"multi_match":{"query":"liquidity","fields":
    // ["body"]}}` in effect — the whole corpus, not nothing. The empty-list
    // lowering must not swallow a list that still has a real field in it.
    let mixed = idx
        .search(&make_search(
            json!({"multi_match": {"query": "liquidity", "fields": ["emb", "body"]}}),
        ))
        .await
        .unwrap();
    assert_eq!(
        mixed.total.value, DOCS as u64,
        "dropping the vector entry must leave the rest of a `fields` list intact"
    );

    // (d2b) COMPOSITES. Lowering a leaf to `match_none` is only half a rewrite:
    // the enclosing `bool` then has to fold it the way the EVALUATOR reads it,
    // and `doc_matches_query`'s Bool arm makes `should` required whenever `must`
    // and `filter` are empty — `must_not` does NOT relax it. The first cut of
    // this fix skipped the "every optional clause is dead" fold whenever a
    // `must_not` was present and then dropped the dead clause anyway, which
    // turned the first row below from 0 hits into 150.
    //
    // Every expected value here is `main`'s answer for the same request: a
    // lexical clause on `emb` matched nothing before the postings went away and
    // must match nothing after.
    for (q, want) in [
        // The regression. `should` is required, its only clause is dead.
        (
            json!({"bool": {
                "should": [{"term": {"emb": probe}}],
                "must_not": [{"term": {"cat": "odd"}}]
            }}),
            0u64,
        ),
        // Should-only, no `must_not` — the shape a `simple_query_string` lowers
        // to.
        (json!({"bool": {"should": [{"term": {"emb": probe}}]}}), 0),
        // A live `should` beside the dead one still matches on its own.
        (
            json!({"bool": {"should": [
                {"term": {"emb": probe}},
                {"term": {"cat": "even"}}
            ]}}),
            (DOCS / 2) as u64,
        ),
        // `must` / `filter`: an unsatisfiable REQUIRED clause sinks the bool.
        (
            json!({"bool": {
                "must": [{"term": {"emb": probe}}, {"match": {"body": "liquidity"}}]
            }}),
            0,
        ),
        (json!({"bool": {"filter": [{"term": {"emb": probe}}]}}), 0),
        // `must_not`: a clause that matches nothing EXCLUDES nothing. Same
        // answer as `main`; what changes is the route — a `match_none` left
        // sitting in `must_not` un-projects the whole bool in
        // `query_node_to_fts_with_keyword_fields` and sends a query that used
        // to run on the inverted index to the stored-doc scan.
        (
            json!({"bool": {"must_not": [{"term": {"emb": probe}}]}}),
            DOCS as u64,
        ),
        (
            json!({"bool": {
                "must": [{"match": {"body": "liquidity"}}],
                "must_not": [{"term": {"emb": probe}}]
            }}),
            DOCS as u64,
        ),
        // `constant_score` is the only wrapper with an arm in the FTS
        // projection, so it is the only one where failing to bubble up the
        // `match_none` costs an inverted-index lookup.
        (
            json!({"constant_score": {"filter": {"term": {"emb": probe}}}}),
            0,
        ),
    ] {
        let hits = idx.search(&make_search(q.clone())).await.unwrap();
        assert_eq!(
            hits.total.value, want,
            "composite over a dense_vector clause: expected {want}, got {} for {q}",
            hits.total.value
        );
    }

    // (d2c) …and the composites that keep their HIT COUNT still change their
    // `_score`, which is wire-visible and therefore has to be pinned here
    // rather than discovered by a user.
    //
    // Cause: `lower_lexically_typeless_clauses` drops the dead clause out of
    // `should`, which makes the surviving bool PROJECTABLE through
    // `query_node_to_fts_with_keyword_fields`. On `main` the same bool contains
    // a clause that cannot be projected, so the whole query runs on the
    // stored-doc scan and is scored by `score_query_against_doc` instead of
    // BM25. Isolated to the fold: with the write-side exclusion alone and the
    // lowering disabled, both scores below are byte-identical to `main`.
    //
    // Measured on this fixture, `origin/main` → this branch:
    //
    //   bool{should:[term emb, term cat:even]}
    //       hits    150 → 150          (unchanged)
    //       _score  0.008402659 → 0.6931471
    //       max_score 1.6931472 → 0.6931471
    //   bool{must:[match body], must_not:[term emb]}
    //       hits    300 → 300          (unchanged)
    //       _score  0.008402659 → 0.008402659   (unchanged)
    //       max_score 1.6931472 → 0.008402659
    //
    // The assertions are properties rather than golden floats, so they survive
    // a BM25 tuning change but still fail on `main`:
    //
    //  1. `max_score` equals the top hit's `_score`. On `main` it does NOT for
    //     either shape — the scan path reports a `max_score` of 1.6931472 that
    //     no returned hit carries. That inconsistency is what goes away.
    //  2. a bool whose only surviving `should` is `{"term":{"cat":"even"}}`
    //     scores exactly like that term query on its own. On `main` it scores
    //     0.008402659 against the term query's 0.6931471.
    let cat_alone = idx
        .search(&make_search(json!({"term": {"cat": "even"}})))
        .await
        .unwrap();
    let should_mixed = idx
        .search(&make_search(json!({"bool": {"should": [
            {"term": {"emb": probe}},
            {"term": {"cat": "even"}}
        ]}})))
        .await
        .unwrap();
    let mustnot_bool = idx
        .search(&make_search(json!({"bool": {
            "must": [{"match": {"body": "liquidity"}}],
            "must_not": [{"term": {"emb": probe}}]
        }})))
        .await
        .unwrap();
    // Hit counts first, so a regression that empties one of these reports
    // "expected 150 hits" rather than panicking on `hits[0]` below.
    for (label, res, want) in [
        ("term {cat:even}", &cat_alone, (DOCS / 2) as u64),
        (
            "bool{should:[dead, term cat]}",
            &should_mixed,
            (DOCS / 2) as u64,
        ),
        (
            "bool{must:[match], must_not:[dead]}",
            &mustnot_bool,
            DOCS as u64,
        ),
    ] {
        assert_eq!(
            res.total.value, want,
            "{label}: the score probes must keep `main`'s hit count"
        );
        assert!(!res.hits.is_empty(), "{label}: expected a scored top hit");
    }
    eprintln!(
        "#328 scores: term{{cat}}={:?}/{:?} should-mixed={:?}/{:?} must-not={:?}/{:?} \
         (top/max)",
        cat_alone.hits[0].score,
        cat_alone.max_score,
        should_mixed.hits[0].score,
        should_mixed.max_score,
        mustnot_bool.hits[0].score,
        mustnot_bool.max_score,
    );
    for (label, res) in [
        ("bool{should:[dead, term cat]}", &should_mixed),
        ("bool{must:[match], must_not:[dead]}", &mustnot_bool),
    ] {
        assert_eq!(
            res.max_score,
            Some(res.hits[0].score),
            "{label}: max_score must be the top hit's _score, got max={:?} top={:?}",
            res.max_score,
            res.hits[0].score
        );
    }
    assert_eq!(
        should_mixed.hits[0].score, cat_alone.hits[0].score,
        "a bool whose only live `should` is `term cat:even` must score exactly \
         like that term query alone; got {:?} against {:?}",
        should_mixed.hits[0].score, cat_alone.hits[0].score
    );

    // (d3) the mapping still describes the field — the exclusion is about
    // lexical BYTES, not about the field's existence. This is the leaf of the
    // `_field_caps` guarantee reachable from the engine crate: `_field_caps`
    // is served by the API layer from exactly this schema and never opens a
    // term dictionary, so a field that reports `dense_vector` here reports
    // `dense_vector` there.
    let mapped = idx.schema().await;
    let emb_field = mapped
        .fields
        .iter()
        .find(|f| f.name == "emb")
        .expect("`emb` must still be a mapped field");
    assert!(matches!(emb_field.field_type, FieldType::Vector));
    assert_eq!(emb_field.options.dimensions, Some(DIMS));

    // (d4) highlighting a vector field yields no fragments and no panic, while
    // a real text field in the same request still highlights. Highlighting
    // resolves against the stored document and never opens the field's FST,
    // so removing the FST cannot change it.
    let hl = idx
        .search(
            &parse_request(&json!({
                "query": {"match": {"body": "liquidity"}},
                "size": 1,
                "highlight": {"fields": {"body": {}, "emb": {}}}
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    let frags = hl.hits[0]
        .highlight
        .as_ref()
        .expect("highlight must be present");
    assert!(
        frags.get("body").is_some_and(|f| !f.is_empty()),
        "a text field must still highlight"
    );
    assert!(
        frags.get("emb").is_none_or(|f| f.is_empty()),
        "a dense_vector must produce no highlight fragments, got {:?}",
        frags.get("emb")
    );

    // (e) the index reopens and searches after a restart. The exclusion is a
    // WRITE-side rule and no reader requires the field's sidecar to exist, so
    // a segment written without one loads exactly like one written with it.
    // (This does not, and cannot from inside one test binary, exercise a
    // segment produced by the previous release: those keep their `.emb.*`
    // files until a merge rewrites them, and the per-segment `fts_has_field`
    // gate reads whichever shape it finds.)
    drop(idx);
    drop(engine); // release the data dir's `node.lock` before reopening it
    let reopened = make_engine(&dir);
    let idx = reopened.get_index("duprobe").unwrap();
    let after = idx
        .search(&make_search(json!({"match": {"body": "liquidity"}})))
        .await
        .unwrap();
    assert_eq!(after.total.value, DOCS as u64);
}

/// #328, nested half — a `dense_vector` under an OBJECT mapping.
///
/// Excluding the leaf path alone moves no bytes here, and that is the trap the
/// first cut of this fix fell into: the segment builder never writes a
/// `passages.vec` field at all. It flattens the whole `passages` object into
/// ONE text field, so the vector's 64 decimal components land in
/// `<seg>.passages.fst` under the parent's name. The size of that file is
/// reported below rather than asserted to a golden number, and the ceiling is
/// deliberately generous: the point is that the fixture's 19,200 vector
/// components are gone, and they cannot fit in 4 KiB.
///
/// Both mapping shapes that reach `FieldType::Vector` are pinned, because they
/// take different routes into the schema and only one of them was covered by
/// the walk: a dotted top-level name (`"passages.vec"`, what `put_mapping`
/// produces) and a `vec` sub-mapping under a `passages` object (what
/// `es_properties_to_fields` produces from nested `properties`).
#[tokio::test]
async fn nested_dense_vector_is_excluded_from_its_parent_objects_term_dictionary() {
    const DIMS: usize = 64;
    const DOCS: usize = 300;

    let component = |doc: usize, dim: usize| -> f64 {
        let h = (doc as u64)
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add((dim as u64).wrapping_mul(1_442_695_040_888_963_407));
        ((h >> 11) as f64 / (1u64 << 53) as f64 * 2.0) - 1.0
    };

    for shape in ["dotted-name", "sub-mapping"] {
        let dir = TempDir::new().unwrap();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("body", FieldType::Text));
        let mut vec_field = FieldConfig::new(
            if shape == "dotted-name" {
                "passages.vec"
            } else {
                "vec"
            },
            FieldType::Vector,
        );
        vec_field.options.dimensions = Some(DIMS);
        vec_field.options.similarity = Some("cosine".to_string());
        if shape == "dotted-name" {
            schema.fields.push(vec_field);
        } else {
            let mut parent = FieldConfig::new("passages", FieldType::Object);
            parent.fields.push(vec_field);
            schema.fields.push(parent);
        }

        let engine = make_engine(&dir);
        engine.create_index("nested-vec", schema).unwrap();
        let idx = engine.get_index("nested-vec").unwrap();

        let mut first_vector = Vec::new();
        for d in 0..DOCS {
            let v: Vec<f64> = (0..DIMS).map(|dim| component(d, dim)).collect();
            if d == 0 {
                first_vector = v.clone();
            }
            idx.index_document(
                Some(format!("d{d}")),
                json!({
                    "body": format!("quarterly liquidity evidence {d}"),
                    "passages": {"vec": v},
                }),
            )
            .await
            .unwrap();
        }
        idx.refresh().await.unwrap();
        idx.force_merge(1).await.unwrap();

        let mut files: Vec<(String, u64)> = Vec::new();
        fn walk(dir: &std::path::Path, out: &mut Vec<(String, u64)>) {
            for entry in std::fs::read_dir(dir).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    walk(&entry.path(), out);
                } else {
                    out.push((
                        entry.file_name().to_string_lossy().into_owned(),
                        entry.metadata().unwrap().len(),
                    ));
                }
            }
        }
        walk(dir.path(), &mut files);

        let parent_fst: u64 = files
            .iter()
            .filter(|(name, _)| name.ends_with(".passages.fst"))
            .map(|(_, len)| *len)
            .sum();
        // Reported so the saving is a measured number in the log, not a claim.
        // `passages.fst` is the load-bearing figure and it is exact — 398,558 B
        // on `origin/main`, 45 B here, for both mapping shapes. `durable-index`
        // is diagnostic only and `whole-dir` is not reproducible at all: it
        // carries the write-ahead log, whose tail is reclaimed asynchronously.
        // Nothing quotes either of them; see the sibling test for the numbers
        // the CHANGELOG does quote.
        let whole_dir: u64 = files.iter().map(|(_, len)| *len).sum();
        let durable: u64 = files
            .iter()
            .filter(|(name, _)| !name.ends_with(".wal"))
            .map(|(_, len)| *len)
            .sum();
        eprintln!(
            "#328 nested [{shape}]: passages.fst={parent_fst} \
             durable-index={durable} whole-dir={whole_dir}"
        );
        // A generous ceiling, not a golden number: the point is that the
        // 19,200 vector components are gone, and they cannot fit in 4 KiB.
        assert!(
            parent_fst < 4096,
            "[{shape}] the parent object's term dictionary must not carry the \
             nested vector's components; `.passages.fst` = {parent_fst} B"
        );
        assert!(
            !files
                .iter()
                .any(|(name, _)| name.ends_with(".passages.vec.fst")),
            "[{shape}] the nested vector leaf must have no term dictionary either"
        );

        // The parent is still a real field, just without the vector in it.
        let lexical = idx
            .search(&make_search(json!({"match": {"body": "liquidity"}})))
            .await
            .unwrap();
        assert_eq!(lexical.total.value, DOCS as u64, "[{shape}]");

        // A component of the vector must not be findable through the parent.
        let probe = format!(
            "{}",
            first_vector
                .iter()
                .copied()
                .find(|v| *v > 0.0)
                .expect("fixture vector has a positive component")
        );
        for q in [
            json!({"match": {"passages": probe}}),
            json!({"term": {"passages": probe}}),
        ] {
            let hits = idx.search(&make_search(q.clone())).await.unwrap();
            assert_eq!(
                hits.total.value, 0,
                "[{shape}] a vector component must not be lexically findable \
                 through its parent object, got {} for {q}",
                hits.total.value
            );
        }

        // kNN on the nested field still answers from the HNSW graph.
        let knn = idx
            .search(
                &parse_request(&json!({
                    "query": {"knn": {
                        "field": "passages.vec", "query_vector": first_vector, "k": 3
                    }},
                    "size": 10
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(knn.hits.len(), 3, "[{shape}] kNN must still retrieve");
        assert_eq!(
            knn.hits[0].id, "d0",
            "[{shape}] nearest must be the probe doc"
        );
    }
}

/// #328, collision half — a field the user DECLARES under a companion's name
/// must keep its whole lexical surface.
///
/// `memtable::lexically_typeless_fields` synthesises `<field>_chunks` and
/// `__xerj_passage_meta__<field>` from the base name, because the passage
/// pipeline writes them into `_source` with no `FieldConfig` behind them. The
/// first revision of that rule fired UNCONDITIONALLY, so a user who mapped
/// `emb_chunks` beside a `dense_vector emb` lost the postings for a field the
/// schema declares — and then `lower_lexically_typeless_clauses` lowered every
/// lexical clause naming it to `match_none`. Measured on this fixture, merge
/// base `ca4d75a` → the name-only rule → here:
///
///   term      {emb_chunks:"tenant-a"}          25 →  0 → 25
///   terms     {emb_chunks:["tenant-a"]}        25 →  0 → 25
///   bool{filter:[term emb_chunks]}             25 →  0 → 25
///   bool{must:[match body],filter:[term …]}    25 →  0 → 25
///   bool{must_not:[term emb_chunks]}           25 → 50 → 25
///   terms agg on emb_chunks                 25/25 → 25/25 → 25/25
///
/// The `must_not` row is the severe one and the reason this is a correctness
/// test rather than a footprint one: the query RETURNED the 25 documents the
/// exclusion was written to remove. The aggregation row proves the data was
/// present and correctly populated the whole time — the planner had declared a
/// live user field unqueryable, with no error and no mapping change. If
/// `<vector>_chunks` is a tenant or ACL discriminator that is a silent
/// data-exposure failure mode.
///
/// Lucene reads "does this field get a term dictionary" off the field's own
/// `IndexableFieldType` and never off its name
/// (`lucene/core/src/java/org/apache/lucene/index/IndexingChain.java:1416`),
/// and one name carrying two different sets of index options is an outright
/// error rather than a silent downgrade (`IndexingChain.FieldSchema
/// .setIndexOptions` → `assertSame` → `raiseNotSame`, `:2213` / `:2193`).
///
/// FOUR ARMS AND THEY ALL YIELD, including the two numeric ones. An earlier
/// revision of this test asserted the OPPOSITE for `long`: the name rule could
/// not yield to `long`/`double` because that is what `infer_field_type` derives
/// from an array of float arrays, so the declaration was indistinguishable from
/// the multi-vector's own. That residual is closed at its source —
/// `index::is_undeclared_multi_vector_companion` stops dynamic mapping
/// inventing the numeric `FieldConfig` in the first place, so the only `long`
/// or `double` under this name is one a user actually wrote, and
/// `declares_non_vector_shaped_field` now yields to every declared type except
/// `dense_vector`. Measured here: the `[long]` arm keeps `.emb_chunks.fst` at
/// 44 B and answers 25 on every row, while the 300-doc fixture in
/// `user_mapped_dense_vector_builds_no_fts_term_dictionary` still reports
/// `emb_chunks.fst=0` — the saving is not paid for with the collision.
///
/// The aggregation is checked on all four arms and buckets 25/25 on all four.
#[tokio::test]
async fn declared_chunks_sibling_of_a_dense_vector_stays_queryable_unless_it_looks_like_one() {
    const DIMS: usize = 16;
    const DOCS: usize = 50;

    let component = |doc: usize, dim: usize| -> f64 {
        let h = (doc as u64)
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add((dim as u64).wrapping_mul(1_442_695_040_888_963_407));
        ((h >> 11) as f64 / (1u64 << 53) as f64 * 2.0) - 1.0
    };

    for declared in [
        FieldType::Keyword,
        FieldType::Text,
        FieldType::Long,
        FieldType::Double,
    ] {
        let label = match declared {
            FieldType::Keyword => "keyword",
            FieldType::Text => "text",
            FieldType::Long => "long",
            _ => "double",
        };
        let dir = TempDir::new().unwrap();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("body", FieldType::Text));
        // The collision: a user field named exactly like the companion the
        // vector below would otherwise synthesise.
        schema.fields.push(FieldConfig::new("emb_chunks", declared));
        let mut emb = FieldConfig::new("emb", FieldType::Vector);
        emb.options.dimensions = Some(DIMS);
        emb.options.similarity = Some("cosine".to_string());
        schema.fields.push(emb);

        let engine = make_engine(&dir);
        engine.create_index("collide", schema).unwrap();
        let idx = engine.get_index("collide").unwrap();

        let mut first_vector = Vec::new();
        for d in 0..DOCS {
            let v: Vec<f64> = (0..DIMS).map(|dim| component(d, dim)).collect();
            if d == 0 {
                first_vector = v.clone();
            }
            // A keyword mapping gets the bare discriminator; a text mapping gets
            // it plus a token that is unique to the half, because `match` on
            // "tenant-a" analyses to [tenant, a] and would match both halves.
            let tenant = if d % 2 == 0 { "tenant-a" } else { "tenant-b" };
            let chunks_value: Value = match declared {
                FieldType::Keyword => json!(tenant),
                FieldType::Text => json!(format!(
                    "{tenant} {}",
                    if d % 2 == 0 { "widgets" } else { "gadgets" }
                )),
                // The two numeric arms. A SCALAR, which is what a user's own
                // `long`/`double` field looks like — and, decisively, not the
                // rectangular array-of-numeric-arrays `looks_like_multi_vector`
                // recognises, so nothing about this value is companion-shaped
                // either.
                FieldType::Long => json!(if d % 2 == 0 { 7 } else { 9 }),
                _ => json!(if d % 2 == 0 { 7.5 } else { 9.5 }),
            };
            idx.index_document(
                Some(format!("d{d}")),
                json!({
                    "body": format!("quarterly liquidity evidence {d}"),
                    "emb_chunks": chunks_value,
                    "emb": v,
                }),
            )
            .await
            .unwrap();
        }
        idx.refresh().await.unwrap();
        idx.force_merge(1).await.unwrap();

        let mut files: Vec<(String, u64)> = Vec::new();
        fn walk(dir: &std::path::Path, out: &mut Vec<(String, u64)>) {
            for entry in std::fs::read_dir(dir).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    walk(&entry.path(), out);
                } else {
                    out.push((
                        entry.file_name().to_string_lossy().into_owned(),
                        entry.metadata().unwrap().len(),
                    ));
                }
            }
        }
        walk(dir.path(), &mut files);
        let bytes_of = |suffix: &str| -> u64 {
            files
                .iter()
                .filter(|(name, _)| name.ends_with(suffix))
                .map(|(_, len)| *len)
                .sum()
        };
        eprintln!(
            "#328 collision [{label}]: emb_chunks.fst={} emb.fst={} body.fst={}",
            bytes_of(".emb_chunks.fst"),
            bytes_of(".emb.fst"),
            bytes_of(".body.fst"),
        );
        // The DECLARED sibling keeps its term dictionary. On ALL FOUR arms —
        // this is the assertion that fails if the numeric carve-out ever comes
        // back.
        assert!(
            files
                .iter()
                .any(|(name, _)| name.ends_with(".emb_chunks.fst")),
            "[{label}] a declared sibling must keep `.emb_chunks.fst`; got {:?}",
            files
                .iter()
                .filter(|(name, _)| name.contains(".emb"))
                .collect::<Vec<_>>()
        );
        // … and the `dense_vector` beside it still loses its own.
        assert!(
            !files.iter().any(|(name, _)| name.ends_with(".emb.fst")),
            "[{label}] the dense_vector must still have no term dictionary"
        );

        // ── The answers. Every row here is 25 on the merge base `ca4d75a`; the
        // unconditional name-only rule answered 0 for all of them, and 50 for
        // the `must_not` shape below. All four arms require 25 — the merge
        // base's own answer.
        let want = (DOCS / 2) as u64;
        let probes: Vec<(&str, Value)> = if matches!(declared, FieldType::Keyword) {
            vec![
                ("term", json!({"term": {"emb_chunks": "tenant-a"}})),
                ("terms", json!({"terms": {"emb_chunks": ["tenant-a"]}})),
                (
                    "bool-filter",
                    json!({"bool": {"filter": [{"term": {"emb_chunks": "tenant-a"}}]}}),
                ),
                (
                    "bool-must-plus-filter",
                    json!({"bool": {
                        "must": [{"match": {"body": "liquidity"}}],
                        "filter": [{"term": {"emb_chunks": "tenant-a"}}]
                    }}),
                ),
                (
                    "constant-score",
                    json!({"constant_score": {"filter": {"term": {"emb_chunks": "tenant-a"}}}}),
                ),
            ]
        } else if matches!(declared, FieldType::Long) {
            vec![
                ("term", json!({"term": {"emb_chunks": 7}})),
                ("terms", json!({"terms": {"emb_chunks": [7]}})),
                ("range", json!({"range": {"emb_chunks": {"gte": 8}}})),
                (
                    "bool-filter",
                    json!({"bool": {"filter": [{"term": {"emb_chunks": 7}}]}}),
                ),
            ]
        } else if matches!(declared, FieldType::Double) {
            vec![
                ("term", json!({"term": {"emb_chunks": 7.5}})),
                ("terms", json!({"terms": {"emb_chunks": [7.5]}})),
                ("range", json!({"range": {"emb_chunks": {"gte": 8}}})),
                (
                    "bool-filter",
                    json!({"bool": {"filter": [{"term": {"emb_chunks": 7.5}}]}}),
                ),
            ]
        } else {
            vec![
                ("match", json!({"match": {"emb_chunks": "widgets"}})),
                (
                    "match-phrase",
                    json!({"match_phrase": {"emb_chunks": "tenant-a widgets"}}),
                ),
                (
                    "multi-match",
                    json!({"multi_match": {"query": "widgets", "fields": ["emb_chunks"]}}),
                ),
                (
                    "simple-query-string",
                    json!({"simple_query_string": {"query": "widgets", "fields": ["emb_chunks"]}}),
                ),
                ("prefix", json!({"prefix": {"emb_chunks": "widget"}})),
            ]
        };
        for (name, q) in &probes {
            let hits = idx.search(&make_search(q.clone())).await.unwrap();
            assert_eq!(
                hits.total.value, want,
                "[{label}] {name}: expected {want}, got {} for {q}",
                hits.total.value
            );
        }

        // The severe one, isolated: `must_not` on the declared sibling must
        // still EXCLUDE. Under the name-only rule the clause lowered to
        // `match_none`, the Bool fold dropped it as "excludes nothing", and the
        // query returned all 50 — the 25 it was written to remove included.
        //
        // The text half is anchored with an explicit `match_all` `must`,
        // because bare `bool{must_not:[match …]}` answers 0 on `origin/main`
        // too — a PRE-EXISTING quirk with nothing to do with #328 (a control
        // index carrying no vector field at all reproduces it: `{text body,
        // text tags}`, `bool{must_not:[match tags:"widgets"]}` = 0 while
        // `bool{must:[match_all],must_not:[match tags:"widgets"]}` = 25). This
        // test pins the shape that is correct on `main` to begin with, so a
        // failure here is this change's doing and nobody else's.
        let must_not_probe = if matches!(declared, FieldType::Keyword) {
            json!({"bool": {"must_not": [{"term": {"emb_chunks": "tenant-a"}}]}})
        } else if matches!(declared, FieldType::Long) {
            json!({"bool": {
                "must": [{"match_all": {}}],
                "must_not": [{"term": {"emb_chunks": 7}}]
            }})
        } else if matches!(declared, FieldType::Double) {
            json!({"bool": {
                "must": [{"match_all": {}}],
                "must_not": [{"term": {"emb_chunks": 7.5}}]
            }})
        } else {
            json!({"bool": {
                "must": [{"match_all": {}}],
                "must_not": [{"match": {"emb_chunks": "widgets"}}]
            }})
        };
        let excluded = idx
            .search(&make_search(must_not_probe.clone()))
            .await
            .unwrap();
        // The exclusion returns exactly the other half on all four arms. Under
        // the name-only rule the numeric arms returned all 50 — the 25 the
        // exclusion was written to remove included; that is the shape this
        // assertion exists to keep out.
        assert_eq!(
            excluded.total.value,
            (DOCS / 2) as u64,
            "[{label}] must_not: got {} for {must_not_probe}",
            excluded.total.value
        );
        for hit in &excluded.hits {
            let n: usize = hit.id.trim_start_matches('d').parse().unwrap();
            assert_eq!(
                n % 2,
                1,
                "[{label}] must_not returned an excluded document: {}",
                hit.id
            );
        }

        // Doc values were never in question — this row answers 25/25 on all
        // four arms. It answered 25/25 under the name-only rule too, which is
        // what proved the data was present and correctly populated while every
        // lexical clause on it said 0: it was the planner, not the storage.
        let agg = idx
            .search(
                &parse_request(&json!({
                    "size": 0,
                    "aggs": {"by_tenant": {"terms": {"field": "emb_chunks", "size": 10}}}
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        let buckets = agg.aggs.as_ref().expect("aggs present")["by_tenant"]["buckets"]
            .as_array()
            .unwrap()
            .clone();
        assert!(
            buckets.iter().any(|b| b["doc_count"] == 25),
            "[{label}] terms agg on the declared sibling must still bucket it, \
             got {buckets:?}"
        );

        // The vector itself is unchanged by the yield: every lexical leaf
        // naming it still answers 0, and kNN still answers from the graph.
        for q in [
            json!({"term": {"emb": "0"}}),
            json!({"wildcard": {"emb": "0*"}}),
            json!({"multi_match": {"query": "0", "fields": ["emb"]}}),
        ] {
            let hits = idx.search(&make_search(q.clone())).await.unwrap();
            assert_eq!(
                hits.total.value, 0,
                "[{label}] a lexical clause on the dense_vector must answer 0, \
                 got {} for {q}",
                hits.total.value
            );
        }
        let knn = idx
            .search(
                &parse_request(&json!({
                    "query": {"knn": {"field": "emb", "query_vector": first_vector, "k": 3}},
                    "size": 10
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(knn.hits.len(), 3, "[{label}] kNN must still retrieve");
        assert_eq!(knn.hits[0].id, "d0", "[{label}] nearest must be the probe");
    }
}

/// #328, the other half of the same rule: what dynamic mapping is allowed to do
/// with an UNDECLARED `<vector>_chunks` key, which is what decides whether the
/// collision test above can be true at the same time as the saving.
///
/// Three arms, one index each, all with `emb` declared `dense_vector` and
/// `emb_chunks` absent from the mapping. What differs is only the VALUE, and
/// the value is the whole rule
/// (`memtable::looks_like_multi_vector` →
/// `index::is_undeclared_multi_vector_companion`):
///
///   * `[[…],[…]]` rectangular numeric — a real RFC #148 multi-vector.
///     Dynamic mapping must not register it, it must acquire no `FieldConfig`,
///     it must have no `.emb_chunks.fst`, and lexical clauses on it answer 0.
///     This is where the 26,518,005 B / 67% of #328's saving comes from.
///   * a SCALAR string — somebody's own field that happens to sit under the
///     name. Registered as `text` and fully lexical. This one was already safe
///     before the fix.
///   * a SCALAR number — somebody's own field, registered as `long`, and fully
///     lexical. THIS is the arm that was silently broken: dynamic mapping wrote
///     a `long` config, `declares_non_vector_shaped_field` carved `long` out of
///     its yield set precisely because it could not tell that config from the
///     multi-vector's, and every lexical clause on a live user field lowered to
///     `match_none`. Nothing about the mapping changed and no error was raised.
///
/// The value-shape test is why all three can hold at once, and it is the same
/// place Lucene puts the distinction: a per-document multi-vector is
/// `LateInteractionField extends BinaryDocValuesField`
/// (`lucene/core/src/java/org/apache/lucene/document/LateInteractionField.java:36`,
/// `:44`, `:45`) — its own field type, never a numeric one arrived at by
/// inference.
#[tokio::test]
async fn an_undeclared_chunks_key_is_unmapped_only_when_its_value_is_a_multi_vector() {
    const DIMS: usize = 16;
    const DOCS: usize = 50;

    let component = |doc: usize, dim: usize| -> f64 {
        let h = (doc as u64)
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add((dim as u64).wrapping_mul(1_442_695_040_888_963_407));
        ((h >> 11) as f64 / (1u64 << 53) as f64 * 2.0) - 1.0
    };

    // (label, value builder, expected-to-stay-lexical, probe)
    #[allow(clippy::type_complexity)]
    let arms: Vec<(&str, Box<dyn Fn(usize, &[f64]) -> Value>, bool, Value)> = vec![
        (
            "multi-vector",
            Box::new(|_d, v: &[f64]| json!([v, v])),
            false,
            json!({"term": {"emb_chunks": "0"}}),
        ),
        (
            "scalar-string",
            Box::new(|d, _v: &[f64]| json!(if d % 2 == 0 { "tenant-a" } else { "tenant-b" })),
            true,
            json!({"term": {"emb_chunks": "tenant-a"}}),
        ),
        (
            "scalar-number",
            Box::new(|d, _v: &[f64]| json!(if d % 2 == 0 { 7 } else { 9 })),
            true,
            json!({"term": {"emb_chunks": 7}}),
        ),
    ];

    for (label, value_of, stays_lexical, probe) in arms {
        let dir = TempDir::new().unwrap();
        let mut schema = Schema::empty();
        schema
            .fields
            .push(FieldConfig::new("body", FieldType::Text));
        let mut emb = FieldConfig::new("emb", FieldType::Vector);
        emb.options.dimensions = Some(DIMS);
        emb.options.similarity = Some("cosine".to_string());
        schema.fields.push(emb);
        // NOTE: no `emb_chunks` here. Whatever config it ends up with is one
        // dynamic mapping decided, which is exactly what is under test.

        let engine = make_engine(&dir);
        engine.create_index("dyn", schema).unwrap();
        let idx = engine.get_index("dyn").unwrap();

        for d in 0..DOCS {
            let v: Vec<f64> = (0..DIMS).map(|dim| component(d, dim)).collect();
            idx.index_document(
                Some(format!("d{d}")),
                json!({
                    "body": format!("quarterly liquidity evidence {d}"),
                    "emb_chunks": value_of(d, &v),
                    "emb": v,
                }),
            )
            .await
            .unwrap();
        }
        idx.refresh().await.unwrap();
        idx.force_merge(1).await.unwrap();

        let live = idx.schema().await;
        let mapped = live.fields.iter().find(|f| f.name == "emb_chunks");

        let mut files: Vec<(String, u64)> = Vec::new();
        fn walk(dir: &std::path::Path, out: &mut Vec<(String, u64)>) {
            for entry in std::fs::read_dir(dir).unwrap() {
                let entry = entry.unwrap();
                if entry.file_type().unwrap().is_dir() {
                    walk(&entry.path(), out);
                } else {
                    out.push((
                        entry.file_name().to_string_lossy().into_owned(),
                        entry.metadata().unwrap().len(),
                    ));
                }
            }
        }
        walk(dir.path(), &mut files);
        let fst: u64 = files
            .iter()
            .filter(|(name, _)| name.ends_with(".emb_chunks.fst"))
            .map(|(_, len)| *len)
            .sum();
        let hits = idx.search(&make_search(probe.clone())).await.unwrap();
        eprintln!(
            "#328 dynamic [{label}]: mapped={:?} emb_chunks.fst={fst} hits={}",
            mapped.map(|f| f.field_type),
            hits.total.value
        );

        if stays_lexical {
            assert!(
                mapped.is_some(),
                "[{label}] dynamic mapping must still register an ordinary field \
                 under this name"
            );
            assert!(
                fst > 0,
                "[{label}] a dynamically mapped field of the user's own must keep \
                 its term dictionary"
            );
            assert_eq!(
                hits.total.value,
                (DOCS / 2) as u64,
                "[{label}] a dynamically mapped field of the user's own must stay \
                 queryable, got {} for {probe}",
                hits.total.value
            );
        } else {
            assert!(
                mapped.is_none(),
                "[{label}] a real multi-vector must not acquire a FieldConfig; got {mapped:?}"
            );
            assert_eq!(fst, 0, "[{label}] a real multi-vector must have no `.fst`");
            assert_eq!(
                hits.total.value, 0,
                "[{label}] a lexical clause on a real multi-vector must answer 0"
            );
        }
        // The `dense_vector` itself is unaffected on every arm.
        assert!(
            !files.iter().any(|(name, _)| name.ends_with(".emb.fst")),
            "[{label}] the dense_vector must still have no term dictionary"
        );
    }
}

/// #328, the documented LIMIT of the rule above, asserted rather than assumed.
///
/// `is_undeclared_multi_vector_companion` can only refuse to map a companion it
/// can recognise, and recognising one needs the `dense_vector` to be declared
/// ALREADY. Index the documents first and map `emb` afterwards and dynamic
/// mapping has already written a `double` config for `emb_chunks` — which
/// `declares_non_vector_shaped_field` then yields to, exactly as it would to a
/// user's own declaration, because on the information in the schema the two are
/// the same thing.
///
/// The consequence is bytes, not answers: `<seg>.emb_chunks.fst` survives. That
/// is the safe direction of the trade and the reason this limit is acceptable,
/// so the test asserts BOTH halves — the dictionary is there AND the field
/// still answers — so that a future change cannot quietly convert it into the
/// silent-zero direction.
#[tokio::test]
async fn a_companion_mapped_before_its_vector_keeps_its_dictionary_and_its_answers() {
    const DIMS: usize = 16;
    const DOCS: usize = 50;

    let dir = TempDir::new().unwrap();
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    let engine = make_engine(&dir);
    engine.create_index("late", schema).unwrap();
    let idx = engine.get_index("late").unwrap();

    // Documents FIRST — no `emb` in the mapping yet, so `emb_chunks` is just an
    // array of numeric arrays and dynamic mapping registers it as `double`.
    for d in 0..DOCS {
        let v: Vec<f64> = (0..DIMS).map(|dim| (d + dim) as f64 * 0.25).collect();
        idx.index_document(
            Some(format!("d{d}")),
            json!({
                "body": format!("quarterly liquidity evidence {d}"),
                "emb_chunks": [v.clone(), v.clone()],
            }),
        )
        .await
        .unwrap();
    }
    idx.refresh().await.unwrap();

    let before = idx.schema().await;
    let inferred = before
        .fields
        .iter()
        .find(|f| f.name == "emb_chunks")
        .map(|f| f.field_type);
    assert_eq!(
        inferred,
        Some(FieldType::Double),
        "with no `dense_vector` declared, the companion is an ordinary numeric \
         field and must be mapped like one"
    );

    // …and only NOW is the vector declared. From this point on
    // `lexically_typeless_fields` synthesises `emb_chunks` as a companion
    // candidate — and finds the `double` config dynamic mapping already wrote.
    let mut emb = FieldConfig::new("emb", FieldType::Vector);
    emb.options.dimensions = Some(DIMS);
    emb.options.similarity = Some("cosine".to_string());
    idx.add_field(emb).await.unwrap();
    idx.force_merge(1).await.unwrap();

    let mut files: Vec<(String, u64)> = Vec::new();
    fn walk(dir: &std::path::Path, out: &mut Vec<(String, u64)>) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            if entry.file_type().unwrap().is_dir() {
                walk(&entry.path(), out);
            } else {
                out.push((
                    entry.file_name().to_string_lossy().into_owned(),
                    entry.metadata().unwrap().len(),
                ));
            }
        }
    }
    walk(dir.path(), &mut files);
    let fst: u64 = files
        .iter()
        .filter(|(name, _)| name.ends_with(".emb_chunks.fst"))
        .map(|(_, len)| *len)
        .sum();
    let hits = idx
        .search(&make_search(json!({"exists": {"field": "emb_chunks"}})))
        .await
        .unwrap();
    eprintln!(
        "#328 mapping-after-data: emb_chunks.fst={fst} exists={}",
        hits.total.value
    );

    // The cost of the limit: the companion's dictionary survives.
    assert!(
        fst > 0,
        "mapping the vector after the data leaves the companion's dictionary in \
         place — that is the documented cost, and it is bytes"
    );
    // The thing that must NOT happen: it is still a live, answering field.
    assert_eq!(
        hits.total.value, DOCS as u64,
        "the companion must stay queryable when the schema says it is an \
         ordinary numeric field"
    );
}

#[tokio::test]
async fn semantic_passage_provenance_survives_update_merge_restart_and_source_filter() {
    let dir = TempDir::new().unwrap();
    let mut schema = Schema::empty();
    let mut content = FieldConfig::new("content", FieldType::Text);
    content.options.dimensions = Some(64);
    content.options.similarity = Some("cosine".to_string());
    content.embedding = Some(xerj_common::types::EmbeddingConfig {
        endpoint: None,
        model: None,
        target_field: Some("custom_embedding".to_string()),
    });
    schema.fields.push(content);
    schema
        .fields
        .push(FieldConfig::new("page", FieldType::Long));

    let initial = format!(
        "{} Résumé 📄 quarterly zephyr liquidity evidence. {}",
        "unrelated operating narrative. ".repeat(40),
        "unrelated tax footnote. ".repeat(40)
    );
    {
        let engine = make_engine(&dir);
        engine.create_index("passage-provenance", schema).unwrap();
        let idx = engine.get_index("passage-provenance").unwrap();
        idx.index_document(
            Some("report-page".into()),
            json!({"content": initial, "page": 17, "company": "ACME"}),
        )
        .await
        .unwrap();
        idx.refresh().await.unwrap();
        idx.force_merge(1).await.unwrap();

        let request = parse_request(&json!({
            "query": {"semantic": {
                "field": "content",
                "query": "Résumé 📄 quarterly zephyr liquidity evidence",
                "k": 10
            }},
            "fields": ["_passage"],
            "_source": {"includes": ["company"]},
            "size": 1
        }))
        .unwrap();
        let result = idx.search(&request).await.unwrap();
        let hit = &result.hits[0];
        assert_eq!(hit.source, json!({"company": "ACME"}));
        let passage = hit.passage.as_ref().expect("opt-in passage");
        assert_eq!(passage.field, "content");
        assert_eq!(passage.page, Some(17));
        assert!(passage.text.contains("Résumé 📄 quarterly zephyr"));
        assert!(initial.is_char_boundary(passage.start_offset as usize));
        assert!(initial.is_char_boundary(passage.end_offset as usize));
        assert_eq!(
            &initial[passage.start_offset as usize..passage.end_offset as usize],
            passage.text
        );

        let ordinary = idx
            .search(
                &parse_request(&json!({
                    "query": {"semantic": {
                        "field": "content",
                        "query": "quarterly zephyr liquidity",
                        "k": 10
                    }},
                    "size": 1
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        assert!(ordinary.hits[0].passage.is_none());
        assert!(ordinary.hits[0]
            .source
            .as_object()
            .unwrap()
            .keys()
            .all(|name| !name.starts_with("__xerj_passage_meta__")));

        // Re-indexing regenerates offsets from the new authoritative text.
        let updated = format!(
            "{} deferred tax aurora covenant disclosure. {}",
            "replacement narrative. ".repeat(36),
            "replacement appendix. ".repeat(36)
        );
        idx.index_document(
            Some("report-page".into()),
            json!({"content": updated, "page": 18, "company": "ACME"}),
        )
        .await
        .unwrap();
        idx.refresh().await.unwrap();
        idx.force_merge(1).await.unwrap();
        let updated_result = idx
            .search(
                &parse_request(&json!({
                    "query": {"semantic": {
                        "field": "content",
                        "query": "deferred tax aurora covenant disclosure",
                        "k": 10
                    }},
                    "fields": ["_passage"],
                    "size": 1
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        let updated_passage = updated_result.hits[0].passage.as_ref().unwrap();
        assert_eq!(updated_passage.page, Some(18));
        assert!(updated_passage.text.contains("aurora covenant"));
        assert_eq!(
            &updated[updated_passage.start_offset as usize..updated_passage.end_offset as usize],
            updated_passage.text
        );
    }

    let reopened = make_engine(&dir);
    let idx = reopened.get_index("passage-provenance").unwrap();
    let reopened_result = idx
        .search(
            &parse_request(&json!({
                "query": {"semantic": {
                    "field": "content",
                    "query": "deferred tax aurora covenant disclosure",
                    "k": 10
                }},
                "fields": ["_passage"],
                "size": 1
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    assert!(reopened_result.hits[0]
        .passage
        .as_ref()
        .unwrap()
        .text
        .contains("aurora covenant"));

    idx.delete_document("report-page").await.unwrap();
    let after_delete = idx
        .search(
            &parse_request(&json!({
                "query": {"semantic": {
                    "field": "content",
                    "query": "deferred tax aurora covenant disclosure",
                    "k": 10
                }},
                "fields": ["_passage"]
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    assert!(after_delete.hits.is_empty());
}

