    use xerj_engine::index::haversine_distance;

    // NYC to London (approx 5570 km)
    let d = haversine_distance(40.7128, -74.0060, 51.5074, -0.1278);
    assert!(
        (d - 5570.0).abs() < 50.0,
        "NYC-London distance should be ~5570 km, got {d:.1}"
