                }
            }
        }
    }))
    .unwrap();

    let result = idx.search(&req).await.unwrap();
    let aggs = result.aggs.as_ref().expect("aggs present");
    let buckets = aggs["price_ranges"]["buckets"].as_array().unwrap();
