    assert_eq!(r2.hits.len(), 5, "page 2 should have 5 hits");

    let ids1: std::collections::HashSet<&str> = r1.hits.iter().map(|h| h.id.as_str()).collect();
    let ids2: std::collections::HashSet<&str> = r2.hits.iter().map(|h| h.id.as_str()).collect();

