                        "default": {
                            "type": "custom",
                            "tokenizer": "standard",
                            "filter": ["lowercse"]
                        }
                    }
                }
            }),
        )
        .expect_err("an unresolvable token filter must fail index creation");
    assert!(err.to_string().contains("lowercse"), "{err}");
}

