//! Issue #354: `match` / `multi_match` on a **keyword** field is mapping-aware
//! in a flushed segment but NOT in the memtable, so a multi-token query changes
//! its answer at `_flush`. No arrays are involved (independent of #332).
//!
//! `doc_matches_query` / `score_query_against_doc` (xerj-engine/src/index.rs)
//! evaluate the `Match` / `MultiMatch` arms by whitespace-tokenising the query
//! and OR-ing the tokens against the stored `_source`, never consulting the
//! mapping — so a `keyword` field is treated like an analyzed `text` field. The
//! segment side DOES consult the mapping (keyword analyzer), so the answer
//! diverges at flush.
//!
//! One doc, `tags` mapped `keyword`, scalar value `"red"`:
//! ```text
//! BEFORE flush | multi_match 'red blue' -> 1 hit  (WRONG: tokenised + OR-ed)
//! AFTER  flush | multi_match 'red blue' -> 0 hits (correct: "red" != "red blue")
//! ```
//! Elasticsearch takes the query text whole under the keyword analyzer, so
//! `"red blue"` is one term, does not equal `"red"`, and the doc matches in
//! NEITHER phase. This test asserts the correct (0-hit) answer in both phases.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is here.

use std::collections::BTreeSet;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

async fn ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

fn expect(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

async fn score_of(idx: &Index, q: &Value, id: &str) -> f32 {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .find(|h| h.id == id)
        .unwrap_or_else(|| panic!("doc {id} not in hits for {q}"))
        .score
}

/// A multi-token `match`/`multi_match` over a scalar `keyword` field must match
/// the value WHOLE (keyword analyzer) — so `"red blue"` never matches `"red"` —
/// identically before and after `flush()`. Fixed by rewriting keyword-targeted
/// `Match`/`MultiMatch` clauses to whole-value `Term`s at the search entry
/// (`rewrite_keyword_full_text_to_term`), so the memtable agrees with the
/// segment. Proven fail-before on main (8831d85c): PRE-flush `multi_match
/// 'red blue'` returned {"2"} instead of {}.
#[tokio::test]
async fn keyword_match_takes_the_query_whole_in_both_phases() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    engine.create_index("kw", schema).unwrap();
    let idx = engine.get_index("kw").unwrap();
    idx.index_document(Some("2".into()), json!({ "tags": "red" }))
        .await
        .unwrap();

    // (query, expected-ids, label). Same hit set required PRE- and POST-flush.
    let cases: &[(Value, &[&str], &str)] = &[
        (
            json!({ "multi_match": { "query": "red blue", "fields": ["tags"] } }),
            &[],
            "multi_match 'red blue' on scalar keyword",
        ),
        // A field spec carrying a `^boost` ("tags^2") must be recognised as
        // keyword too — the boost suffix is stripped before consulting the
        // mapping — so it takes the query whole and flips NEITHER phase.
        (
            json!({ "multi_match": { "query": "red blue", "fields": ["tags^2"] } }),
            &[],
            "multi_match 'red blue' on BOOSTED scalar keyword (tags^2)",
        ),
        // Positive control for the boosted spec: the whole value still matches.
        (
            json!({ "multi_match": { "query": "red", "fields": ["tags^2"] } }),
            &["2"],
            "multi_match 'red' on BOOSTED scalar keyword matches whole value",
        ),
        (
            json!({ "match": { "tags": "red blue" } }),
            &[],
            "match 'red blue' on scalar keyword",
        ),
        // Control: the whole value DOES match, in both phases.
        (
            json!({ "term": { "tags": "red" } }),
            &["2"],
            "term tags=red (control)",
        ),
    ];

    for (q, exp, label) in cases {
        assert_eq!(
            ids(&idx, q).await,
            expect(exp),
            "{label}: PRE-flush (memtable) hit set wrong for {q} — a keyword field \
             must take the query text whole, not whitespace-tokenise + OR it (#354)"
        );
    }
    idx.flush().await.unwrap();
    for (q, exp, label) in cases {
        assert_eq!(
            ids(&idx, q).await,
            expect(exp),
            "{label}: POST-flush (segment) hit set wrong for {q}"
        );
    }
}

/// A `multi_match` spanning BOTH a keyword and a text field must split: the
/// keyword field takes the query WHOLE (so `"red blue"` misses `"red"`), while
/// the text field stays analyzed (so a shared token still matches) — identically
/// before and after flush.
#[tokio::test]
async fn mixed_multi_match_splits_keyword_and_text() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index("mm", schema).unwrap();
    let idx = engine.get_index("mm").unwrap();
    // "1": keyword "red" (whole), text "blue sky" (analyzed → tokens blue, sky).
    idx.index_document(
        Some("1".into()),
        json!({ "tags": "red", "body": "blue sky" }),
    )
    .await
    .unwrap();
    // "2": keyword "green", text "hello world" — matches neither half of "red blue".
    idx.index_document(
        Some("2".into()),
        json!({ "tags": "green", "body": "hello world" }),
    )
    .await
    .unwrap();

    // multi_match "red blue" over [tags(keyword), body(text)]:
    //   tags whole "red blue" != "red"  -> no keyword match on "1"
    //   body analyzed has token "blue"  -> text match on "1"
    // So only "1" matches (via the text half); "2" matches neither.
    let q = json!({ "multi_match": { "query": "red blue", "fields": ["tags", "body"] } });
    let cases: &[(Value, &[&str], &str)] = &[(q, &["1"], "mixed multi_match 'red blue'")];
    for (q, exp, label) in cases {
        assert_eq!(
            ids(&idx, q).await,
            expect(exp),
            "{label}: PRE-flush hit set wrong for {q} — keyword half must be whole-value, \
             text half analyzed (#354)"
        );
    }
    idx.flush().await.unwrap();
    for (q, exp, label) in cases {
        assert_eq!(
            ids(&idx, q).await,
            expect(exp),
            "{label}: POST-flush hit set wrong for {q}"
        );
    }
}

/// #572: a `best_fields` multi_match spanning BOTH a keyword and a text field
/// must combine the two halves by **dis_max** (MAX + tie_breaker), exactly as ES
/// does — not the **SUM** a `Bool.should` gives. Hit sets are unchanged (pinned
/// by `mixed_multi_match_splits_keyword_and_text`); this pins the `_score` in
/// both the memtable and segment phases. Fail-before (the pre-fix `Bool.should`):
/// the combined score equals `kw + text`, so both asserts below trip.
#[tokio::test]
async fn best_fields_multi_match_scores_keyword_and_text_by_max_not_sum() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index("mmscore", schema).unwrap();
    let idx = engine.get_index("mmscore").unwrap();
    // "1" matches BOTH halves of query "vip": keyword `tags == "vip"` (whole)
    // AND text `body` contains "vip".
    idx.index_document(
        Some("1".into()),
        json!({ "tags": "vip", "body": "vip lounge access" }),
    )
    .await
    .unwrap();
    // Extra docs skew each field's BM25 stats so the two half-scores differ,
    // making MAX vs SUM unambiguous, and so both halves have matching peers.
    idx.index_document(
        Some("2".into()),
        json!({ "tags": "guest", "body": "vip vip vip vip vip" }),
    )
    .await
    .unwrap();
    idx.index_document(
        Some("3".into()),
        json!({ "tags": "vip", "body": "nothing relevant here at all" }),
    )
    .await
    .unwrap();

    let both = json!({ "multi_match": { "query": "vip", "fields": ["tags", "body"] } });
    let kw_only = json!({ "multi_match": { "query": "vip", "fields": ["tags"] } });
    let text_only = json!({ "multi_match": { "query": "vip", "fields": ["body"] } });

    for phase in ["pre-flush", "post-flush"] {
        let s_both = score_of(&idx, &both, "1").await;
        let s_kw = score_of(&idx, &kw_only, "1").await;
        let s_text = score_of(&idx, &text_only, "1").await;
        let max = s_kw.max(s_text);
        let sum = s_kw + s_text;
        assert!(
            (s_both - max).abs() < 1e-3,
            "{phase}: best_fields multi_match over [keyword, text] must score \
             max(kw={s_kw}, text={s_text})={max} (dis_max), got {s_both} (#572)"
        );
        assert!(
            s_both + 1e-3 < sum,
            "{phase}: combined score {s_both} must be MAX, not the SUM \
             kw+text={sum} a Bool.should gives (#572)"
        );
        if phase == "pre-flush" {
            idx.flush().await.unwrap();
        }
    }
}

//! Issue #354 (follow-up): a keyword `match`/`multi_match` nested inside a
//! wrapper/compound query — `constant_score`, `function_score`, `boosting`,
//! `dis_max`, `nested`, `hybrid`, `pinned`, `named` — must be mapping-aware in
//! BOTH the memtable and a flushed segment, exactly like a top-level clause.
//!
//! PR #571 rewrote top-level keyword `Match`/`MultiMatch` to whole-value `Term`s
//! but recursed only into `Bool`, so a keyword match wrapped in e.g.
//! `constant_score` fell through unchanged and kept flipping its hit set at
//! `_flush` (the #354 defect, live for wrappers). This extends the rewrite's
//! recursion to the sub-query-carrying wrappers.
//!
//! One doc, `tags` mapped `keyword`, scalar value `"red"`. A wrapped
//! `match {tags: "red blue"}` must take the value WHOLE — `"red blue" != "red"`
//! — so the doc matches in NEITHER phase.
//!
//! Elasticsearch is referenced for wire semantics only; no ES code is here.

use std::collections::BTreeSet;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

async fn ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

fn expect(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

/// A keyword `match`/`multi_match` nested inside a wrapper query takes the
/// query text WHOLE — so `"red blue"` never matches `"red"` — identically
/// before and after `flush()`.
#[tokio::test]
async fn keyword_match_in_wrappers_takes_the_query_whole_in_both_phases() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    engine.create_index("kw", schema).unwrap();
    let idx = engine.get_index("kw").unwrap();
    idx.index_document(Some("2".into()), json!({ "tags": "red" }))
        .await
        .unwrap();

    // Each wrapper embeds `match {tags: "red blue"}`; the keyword field takes
    // the query whole, so none match in either phase. (query, expected, label)
    let miss: &[(Value, &[&str], &str)] = &[
        (
            json!({ "constant_score": { "filter": { "match": { "tags": "red blue" } } } }),
            &[],
            "constant_score > match",
        ),
        (
            json!({ "function_score": { "query": { "match": { "tags": "red blue" } } } }),
            &[],
            "function_score > match",
        ),
        (
            json!({ "boosting": {
                "positive": { "match": { "tags": "red blue" } },
                "negative": { "match": { "tags": "zzz" } },
                "negative_boost": 0.5
            } }),
            &[],
            "boosting > positive match",
        ),
        (
            json!({ "dis_max": { "queries": [ { "match": { "tags": "red blue" } } ] } }),
            &[],
            "dis_max > match",
        ),
        (
            json!({ "dis_max": { "queries": [
                { "multi_match": { "query": "red blue", "fields": ["tags^2"] } }
            ] } }),
            &[],
            "dis_max > boosted multi_match",
        ),
    ];

    // Positive control: the whole value DOES match, wrapped, in both phases.
    let hit: &[(Value, &[&str], &str)] = &[(
        json!({ "constant_score": { "filter": { "match": { "tags": "red" } } } }),
        &["2"],
        "constant_score > match (whole value, control)",
    )];

    let all: Vec<(Value, &[&str], &str)> = miss.iter().chain(hit.iter()).cloned().collect();

    for (q, exp, label) in &all {
        assert_eq!(
            ids(&idx, q).await,
            expect(exp),
            "{label}: PRE-flush (memtable) hit set wrong for {q} — a keyword field \
             wrapped in a compound query must take the query text whole (#354)"
        );
    }
    idx.flush().await.unwrap();
    for (q, exp, label) in &all {
        assert_eq!(
            ids(&idx, q).await,
            expect(exp),
            "{label}: POST-flush (segment) hit set wrong for {q}"
        );
    }
}

//! Regression tests for issue #1280: a `match` / `match_phrase` that the
//! memtable answers by scanning documents must tokenize with the analyzer the
//! segment uses, so the hit set does not change at `flush()`.
//!
//! Pre-fix the scan split text on `!char::is_alphanumeric()`. That is not the
//! standard tokenizer (UAX#29): a run of Han ideographs stayed ONE token where
//! the analyzer emits one per character, so a Chinese `match` inside a
//! filtered `bool` (which is scan-routed) found nothing until `_refresh`; and
//! `foo_bar`, `don't` and `3.14` were split, so `foo`, `don` and `3` matched
//! before the flush and not after. `match_phrase` already analyzed the field
//! side (#230) but still split the query side.
//!
//! Each test runs every case against the memtable, flushes once, re-runs it
//! against the segment, and asserts the expected hit set in both states.

use std::collections::BTreeSet;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    let req = parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request");
    idx.search(&req)
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

async fn assert_flush_parity(idx: &std::sync::Arc<Index>, cases: &[(Value, &[&str], &str)]) {
    let expected: Vec<BTreeSet<String>> = cases
        .iter()
        .map(|(_, exp, _)| exp.iter().map(|s| s.to_string()).collect())
        .collect();
    for ((q, _, label), exp) in cases.iter().zip(&expected) {
        let pre = ids(idx, q).await;
        assert_eq!(
            &pre, exp,
            "{label}: PRE-flush (memtable) hit set wrong for {q}"
        );
    }
    idx.flush().await.unwrap();
    for ((q, _, label), exp) in cases.iter().zip(&expected) {
        let post = ids(idx, q).await;
        assert_eq!(
            &post, exp,
            "{label}: POST-flush (segment) hit set wrong for {q}"
        );
    }
}

async fn seed(engine: &Engine, name: &str) -> std::sync::Arc<Index> {
    engine.create_index(name, Schema::empty()).unwrap();
    let idx = engine.get_index(name).unwrap();
    for (id, text) in [
        ("zh", "普通报表保留七日。"),
        ("ascii", "ERR_SCOPE_MISMATCH means outside scope."),
        ("us", "the foo_bar baz"),
        ("apos", "we don't stop now"),
        ("dot", "notes 3.14 here"),
    ] {
        idx.index_document(Some(id.into()), json!({"text": text, "scope": "synthetic"}))
            .await
            .unwrap();
    }
    idx
}

/// `bool` with a `filter` keeps the clause out of the single-clause unwrap,
/// so the memtable answers it by scanning documents.
fn filtered(clause: Value) -> Value {
    json!({"bool": {"must": [clause], "filter": [{"term": {"scope": "synthetic"}}]}})
}

/// Issue #1280's reproducer and its narrowing: CJK text through the scan.
#[tokio::test]
async fn cjk_match_hit_set_stable_across_flush() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "cjk_parity").await;

    assert_flush_parity(
        &idx,
        &[
            (
                filtered(
                    json!({"match": {"text": {"query": "普通报表保留多久？", "operator": "or"}}}),
                ),
                &["zh"],
                "issue #1280 filtered bool",
            ),
            (
                filtered(json!({"match": {"text": "报"}})),
                &["zh"],
                "one ideograph",
            ),
            (
                json!({"match": {"text": {"query": "普通报表", "operator": "and"}}}),
                &["zh"],
                "operator:and (scan-routed without a bool)",
            ),
            (
                json!({"match": {"text": {"query": "普通报表多久", "operator": "and"}}}),
                &[],
                "operator:and with an absent ideograph",
            ),
            (
                filtered(json!({"match_phrase": {"text": "报表"}})),
                &["zh"],
                "phrase, adjacent",
            ),
            (
                filtered(json!({"match_phrase": {"text": "报保"}})),
                &[],
                "phrase, not adjacent",
            ),
            (
                filtered(json!({"match": {"text": "ERR_SCOPE_MISMATCH"}})),
                &["ascii"],
                "ASCII control",
            ),
        ],
    )
    .await;
}

/// The same split also over-matched ASCII: UAX#29 keeps `_`, `'` and an
/// intra-number `.` inside one word.
#[tokio::test]
async fn word_boundary_match_hit_set_stable_across_flush() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "uax29_parity").await;

    assert_flush_parity(
        &idx,
        &[
            (
                filtered(json!({"match": {"text": "foo"}})),
                &[],
                "foo vs foo_bar",
            ),
            (
                filtered(json!({"match": {"text": "foo_bar"}})),
                &["us"],
                "foo_bar",
            ),
            (
                filtered(json!({"match": {"text": "don"}})),
                &[],
                "don vs don't",
            ),
            (
                filtered(json!({"match": {"text": "don't"}})),
                &["apos"],
                "don't",
            ),
            (
                filtered(json!({"match": {"text": "release 3"}})),
                &[],
                "3 vs 3.14",
            ),
            (
                filtered(json!({"match": {"text": "3.14"}})),
                &["dot"],
                "3.14",
            ),
            (
                filtered(json!({"match_phrase": {"text": "notes 3.14"}})),
                &["dot"],
                "phrase 3.14",
            ),
        ],
    )
    .await;
}

//! Regression tests for issue #830: `match_phrase` `slop` must follow
//! Lucene `SloppyPhraseMatcher` move-distance semantics — a transposed
//! (reordered) pair costs 2 — instead of the old in-order-only gap walk,
//! under which a reordering never matched at ANY slop.
//!
//! Lucene's own class javadoc: for query `"a b"~2`, a document `x a b a y`
//! matches once as `a b` (distance 0) and once as `b a` (distance 2), so
//! ES answers `{"match_phrase": {"t": {"query": "quick brown", "slop": 2}}}`
//! on a document reading `brown quick` — and pre-fix XERJ answered it with
//! zero hits at slop 2, 3, 4, ….
//!
//! Every case is asserted BOTH pre-flush and post-flush, which pins
//! flush-invariance (#218/#222/#230 regression class) as well as the
//! semantics.  Note what the post-flush half does and does not exercise:
//! the planner keeps single-field `match_phrase`/`match_phrase_prefix` with
//! `slop > 0` on the STORED SCAN ("slop>0 and non-standard analyzers keep
//! the stored scan", index.rs), so those rows re-run `phrase_walk` after the
//! flush rather than the segment positional clause.  The segment arm is
//! covered directly by the xerj-fts unit tests
//! (`sloppy_phrase_*` in `search.rs`) and by the `multi_match` case here.
//! Both arms call the one evaluator, `phrase_positions_match`.

use std::collections::BTreeSet;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

async fn ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

fn set(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

/// Run every case against the memtable, flush once, run every case again
/// against the segment, and assert the hit set is the expected one in both
/// states — semantics AND flush-invariance in one assertion.
async fn assert_both_states(idx: &std::sync::Arc<Index>, cases: &[(Value, &[&str], &str)]) {
    for (q, exp, label) in cases {
        let pre = ids(idx, q).await;
        assert_eq!(
            pre,
            set(exp),
            "{label}: PRE-flush (memtable) hit set for {q}"
        );
    }
    idx.flush().await.unwrap();
    for (q, exp, label) in cases {
        let post = ids(idx, q).await;
        assert_eq!(
            post,
            set(exp),
            "{label}: POST-flush (segment) hit set for {q}"
        );
    }
}

/// Doc "adj" holds the phrase in order and adjacent; "rev" holds it
/// TRANSPOSED (the #830 case); "gap" holds it in order with one intervening
/// token; "ctrl" must never match.
async fn seed(engine: &Engine, name: &str) -> std::sync::Arc<Index> {
    engine.create_index(name, Schema::empty()).unwrap();
    let idx = engine.get_index(name).unwrap();
    for (id, text) in [
        ("adj", "quick brown fox"),
        ("rev", "brown quick fox"),
        ("gap", "quick lazy brown"),
        ("ctrl", "the lazy dog"),
    ] {
        idx.index_document(Some(id.into()), json!({ "t": text }))
            .await
            .unwrap();
    }
    idx
}

/// `match_phrase` "quick brown": slop 0 → adjacency only; slop 1 → the
/// forward gap joins; slop 2+ → the transposition joins (cost 2).  The
/// slop-1 rows double as the negative case: the transposition must NOT be
/// admitted below 2, and `ctrl` never matches.
#[tokio::test]
async fn match_phrase_slop_admits_transposition_at_two() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "phrase_transposition").await;

    let q =
        |slop: u32| json!({ "match_phrase": { "t": { "query": "quick brown", "slop": slop } } });
    let cases: Vec<(Value, &[&str], &str)> = vec![
        (q(0), &["adj"], "slop 0: adjacency only"),
        (
            q(1),
            &["adj", "gap"],
            "slop 1: forward gap yes, transposition no",
        ),
        (
            q(2),
            &["adj", "gap", "rev"],
            "slop 2: transposition matches",
        ),
        (
            q(3),
            &["adj", "gap", "rev"],
            "slop 3: superset stays stable",
        ),
    ];
    assert_both_states(&idx, &cases).await;
}

/// Same semantics through `match_phrase_prefix` (the `last_is_prefix` arm of
/// the shared walk; the segment side evaluates it via per-expansion sloppy
/// phrase queries): "quick bro" finds `bro*` transposed against "quick" at
/// slop 2 and not below.
#[tokio::test]
async fn match_phrase_prefix_slop_admits_transposition_at_two() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "phrase_prefix_transposition").await;

    let q = |slop: u32| json!({ "match_phrase_prefix": { "t": { "query": "quick bro", "slop": slop } } });
    let cases: Vec<(Value, &[&str], &str)> = vec![
        (q(0), &["adj"], "prefix slop 0: adjacency only"),
        (
            q(1),
            &["adj", "gap"],
            "prefix slop 1: forward gap yes, transposition no",
        ),
        (
            q(2),
            &["adj", "gap", "rev"],
            "prefix slop 2: transposition matches",
        ),
    ];
    assert_both_states(&idx, &cases).await;
}

/// The `multi_match` phrase type lowers to the same per-field phrase
/// predicate — one case pins that arm too.
#[tokio::test]
async fn multi_match_phrase_slop_admits_transposition_at_two() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "multi_match_transposition").await;

    let q = |slop: u32| json!({ "multi_match": { "query": "quick brown", "fields": ["t"], "type": "phrase", "slop": slop } });
    let cases: Vec<(Value, &[&str], &str)> = vec![
        (
            q(1),
            &["adj", "gap"],
            "multi_match phrase slop 1: no transposition",
        ),
        (
            q(2),
            &["adj", "gap", "rev"],
            "multi_match phrase slop 2: transposition matches",
        ),
    ];
    assert_both_states(&idx, &cases).await;
}

/// Doc "twin" repeats a phrase term; "single" holds it only once.  The
/// review of #882 found that the first minimal-window sweep lost repeated
/// terms: `"i said no no"~1` stopped matching `i said uh no no` at every
/// slop, because on a collision it advanced the pointer at the minimum
/// adjusted position (a non-colliding, single-occurrence slot) and exhausted
/// it before ever trying the assignment that separates the two `no`s.
async fn seed_repeats(engine: &Engine, name: &str) -> std::sync::Arc<Index> {
    engine.create_index(name, Schema::empty()).unwrap();
    let idx = engine.get_index(name).unwrap();
    for (id, text) in [
        ("twin", "i said uh no no"),
        ("single", "i said no thanks"),
        ("noway", "no way no no"),
        ("ctrl", "the lazy dog"),
    ] {
        idx.index_document(Some(id.into()), json!({ "t": text }))
            .await
            .unwrap();
    }
    idx
}

/// A repeated phrase term must not cost a document its match.  `"i said no
/// no"` needs two DISTINCT `no` tokens: "twin" has them (adjusted 0,0,1,1 —
/// span 1), "single" has one `no` and must never match at any slop.
#[tokio::test]
async fn match_phrase_slop_repeated_term_still_matches() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed_repeats(&engine, "phrase_repeats").await;

    let q =
        |slop: u32| json!({ "match_phrase": { "t": { "query": "i said no no", "slop": slop } } });
    let cases: Vec<(Value, &[&str], &str)> = vec![
        (
            q(1),
            &["twin"],
            "slop 1: one intervening token, two distinct 'no' tokens",
        ),
        (q(2), &["twin"], "slop 2: still just the doc with two 'no's"),
        (
            q(3),
            &["twin"],
            "slop 3: 'single' has only one 'no' — never",
        ),
        (q(10), &["twin"], "slop 10: a repeat needs a second token"),
    ];
    assert_both_states(&idx, &cases).await;
}

/// Every slot the same term: `"no no no"~1` on "no way no no"
/// (no@[0,2,3] — pick 0,2,3, adjusted 0,1,1, span 1).
#[tokio::test]
async fn match_phrase_slop_all_slots_repeated() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed_repeats(&engine, "phrase_repeats_all").await;

    let q = |slop: u32| json!({ "match_phrase": { "t": { "query": "no no no", "slop": slop } } });
    let cases: Vec<(Value, &[&str], &str)> = vec![
        (q(1), &["noway"], "slop 1: three distinct 'no' positions"),
        (q(3), &["noway"], "slop 3: superset stays stable"),
    ];
    assert_both_states(&idx, &cases).await;
}

/// The same defect through `multi_match` — the arm that DOES reach the
/// segment positional clause after a flush.
#[tokio::test]
async fn multi_match_phrase_slop_repeated_term_still_matches() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed_repeats(&engine, "multi_match_repeats").await;

    let q = |slop: u32| json!({ "multi_match": { "query": "i said no no", "fields": ["t"], "type": "phrase", "slop": slop } });
    let cases: Vec<(Value, &[&str], &str)> = vec![
        (q(1), &["twin"], "multi_match phrase slop 1: repeat matches"),
        (q(3), &["twin"], "multi_match phrase slop 3: repeat matches"),
    ];
    assert_both_states(&idx, &cases).await;
}

//! Issue #669 (follow-up to #396/#667): the `matched_queries` (`_name`) channel
//! must decide a named clause with the SAME schema-aware matcher hit-SELECTION
//! uses. `collect_matched_queries_inner` called the 2-arg schemaless
//! `doc_matches_query` shim (fold-both), so a named keyword `prefix`/`term`
//! clause could report a `_name` the hit set never granted, and disagree
//! pre- vs post-flush. The fix threads the index schema through so the `_name`
//! annotation matches selection.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn matched(engine: &Engine, q: serde_json::Value) -> Vec<Vec<String>> {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 10 })).expect("parse_request");
    idx.search(&req)
        .await
        .expect("search")
        .hits
        .iter()
        .map(|h| h.matched_queries.clone())
        .collect()
}

#[tokio::test]
async fn matched_queries_name_is_schema_aware_and_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("name", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "name": "Hello" }))
        .await
        .expect("index");

    // A `function_score` whose function carries `_name` and a keyword-`prefix`
    // FILTER. `match_all` makes the doc a hit; the function's `_name` "fp" is
    // reported only if its filter matches. Keyword prefix is case-SENSITIVE, so
    // "Hello" does not start with "hel" — the filter must NOT match and "fp"
    // must NOT appear (the schemaless fold-shim wrongly folded and reported it).
    let q = json!({
        "function_score": {
            "query": { "match_all": {} },
            "functions": [
                { "filter": { "prefix": { "name": "hel" } }, "weight": 2.0, "_name": "fp" }
            ]
        }
    });

    let pre = matched(&engine, q.clone()).await;
    idx.refresh().await.expect("refresh");
    let post = matched(&engine, q.clone()).await;

    assert_eq!(pre, post, "#669: matched_queries must be flush-invariant");
    assert_eq!(pre.len(), 1, "one hit (match_all)");
    assert!(
        !pre[0].contains(&"fp".to_string()),
        "#669: keyword-prefix filter is case-sensitive; the function `_name` must agree with hit selection (no 'fp'): {:?}",
        pre[0]
    );
}

//! Issue #2238: on the 8 GiB auto memory tier the summed-memtable budget is
//! 2 GiB while each index flushes at `storage.flush_size_mb` (512 MiB). A
//! corpus spread across dozens of indices crosses the process budget with
//! every index still under its own flush line. The parent breaker then
//! answers every write HTTP 429, and until this change that latch did not
//! request a drain — so nothing flushed, the client retried, and the indexed
//! count stayed at 0.
//!
//! This test is its own binary so `governor::init` sees this config (the
//! first `Engine::new` in a process wins). One test, so a second engine
//! cannot install a different governor first.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::governor;
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    // 1 MiB process budget. The auto tier's 2 GiB is the same shape at a
    // size a test can fill. RSS watermark off, so only the memtable latch
    // can reject.
    config.limits.max_total_memtable_mb = 1;
    config.limits.memory_watermark_percent = 0;
    // Keep every index under its own flush line. Idle flush disabled, and
    // the periodic flusher pushed far past this test.
    config.storage.flush_size_mb = 64;
    config.storage.flush_idle_secs = 0;
    config.storage.flush_interval_secs = 3600;
    Engine::new(config).expect("engine::new")
}

fn text_schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
}

async fn count_all(engine: &Engine, name: &str) -> u64 {
    let idx = engine.get_index(name).expect("get index");
    let req = parse_request(&json!({ "query": { "match_all": {} }, "size": 0, "from": 0 }))
        .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// Fill four indices past the 1 MiB summed budget without any one of them
/// reaching its flush threshold, watch the next writes get rejected with the
/// indexed bytes unchanged, then drain — the request the sampler now makes
/// on this latch — and accept one more document.
#[tokio::test]
async fn summed_memtable_pressure_rejects_until_a_drain_frees_the_budget() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let names = ["a", "b", "c", "d"];
    for name in names {
        engine
            .create_index(name, text_schema())
            .expect("create index");
    }
    // One long token. The memtable charges ~3× the source bytes, so a few
    // dozen of these cross 1 MiB without a per-index flush.
    let body = format!("n{}", "a".repeat(4096));
    let mut accepted = 0usize;
    for n in 0..400 {
        let name = names[n % names.len()];
        let idx = engine.get_index(name).unwrap();
        idx.index_document(Some(format!("{name}-{n}")), json!({ "body": body }))
            .await
            .unwrap_or_else(|error| panic!("write {n} before the budget: {error}"));
        accepted += 1;
        if engine.total_memtable_bytes() >= 1024 * 1024 {
            break;
        }
    }
    let summed = engine.total_memtable_bytes();
    assert!(
        summed >= 1024 * 1024,
        "the four indices must cross the 1 MiB budget (accepted {accepted}, summed {summed} bytes)"
    );
    for name in names {
        let idx = engine.get_index(name).unwrap();
        let held = idx.memtable_bytes();
        let line = idx.flush_threshold();
        assert!(
            held < line,
            "index {name} holds {held} bytes, flush line is {line}: this must be the multi-index shape, not a per-index flush"
        );
        assert!(held > 0, "index {name} took none of the writes");
    }

    let governor = governor::global().expect("Engine::new installs the governor");
    governor.refresh_memtable(summed);
    assert!(
        !governor.memory_breaker_engaged(),
        "RSS watermark is off; only the memtable latch may engage"
    );
    assert!(governor.memtable_breaker_engaged());
    assert!(
        governor.ingest_pressure_needs_drain(),
        "memtable pressure must request the drain the sampler was not asking for"
    );
    let admission = governor.check_ingest_admission().unwrap_err().to_string();
    assert!(
        admission.contains("limits.max_process_memory_mb"),
        "{admission}"
    );

    let stuck = engine.total_memtable_bytes();
    for attempt in 0..2 {
        let err = engine
            .get_index("a")
            .unwrap()
            .index_document(Some(format!("rejected-{attempt}")), json!({ "body": "no" }))
            .await
            .expect_err("a write over the summed budget must be rejected");
        let rendered = err.to_string();
        assert!(
            rendered.contains("limits.max_process_memory_mb"),
            "attempt {attempt}: {rendered}"
        );
        assert_eq!(
            engine.total_memtable_bytes(),
            stuck,
            "attempt {attempt}: a rejected write must not move the indexed bytes"
        );
    }
    let visible_while_stuck: u64 = {
        let mut total = 0;
        for name in names {
            total += count_all(&engine, name).await;
        }
        total
    };
    assert_eq!(
        visible_while_stuck, accepted as u64,
        "the two rejected writes must not increase the searchable count (the no-progress loop)"
    );

    let drained = engine.drain_rebuildable_memory().await;
    assert_eq!(drained, names.len(), "every loaded index is drained");
    let after = engine.total_memtable_bytes();
    assert!(
        after < 1024 * 1024,
        "the drain must flush the memtables that were holding the budget (still {after} bytes)"
    );
    governor.refresh_memtable(after);
    assert!(!governor.memtable_breaker_engaged());
    assert!(!governor.ingest_pressure_needs_drain());
    assert!(governor.check_ingest_admission().is_ok());

    engine
        .get_index("a")
        .unwrap()
        .index_document(Some("after-drain".into()), json!({ "body": "progress" }))
        .await
        .expect("a write after the drain must be accepted");
    engine
        .get_index("a")
        .unwrap()
        .refresh()
        .await
        .expect("refresh");
    let mut visible = 0u64;
    for name in names {
        visible += count_all(&engine, name).await;
    }
    assert_eq!(
        visible,
        (accepted + 1) as u64,
        "the docs the breaker was sitting on, plus the one write the drain made possible"
    );
}

//! Issue #2321: a summed memtable at the process budget must flush and then
//! accept writes, and a search after that must not scan the full buffer.
//!
//! rc.98 rejected those writes with HTTP 429 and did not flush, so a client
//! that retried crawled and then gave up. Searching the unflushed memtable
//! took about a minute; a restart (flush to segments) did not.
//!
//! This binary owns the process governor. One test, so a second engine cannot
//! install a different budget first.

use std::sync::Arc;
use std::time::{Duration, Instant};

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::governor;
use xerj_engine::Engine;
use xerj_query::parse_request;

const BUDGET: u64 = 1024 * 1024;

fn make_engine(dir: &TempDir) -> Arc<Engine> {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    // 1 MiB stands in for the auto tier's 2 GiB. RSS watermark off, so only
    // the memtable latch can reject. Each index's own flush line is far
    // above what this test writes.
    config.limits.max_total_memtable_mb = 1;
    config.limits.memory_watermark_percent = 0;
    config.storage.flush_size_mb = 64;
    config.storage.flush_idle_secs = 0;
    config.storage.flush_interval_secs = 3600;
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    Arc::new(Engine::new(config).expect("engine"))
}

fn text_schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
}

async fn fill_until_budget(engine: &Engine, names: &[&str], body: &str, tag: &str) -> usize {
    let mut accepted = 0usize;
    for n in 0..800 {
        let name = names[n % names.len()];
        engine
            .get_index(name)
            .unwrap()
            .index_document(Some(format!("{tag}-{name}-{n}")), json!({ "body": body }))
            .await
            .unwrap_or_else(|error| panic!("{tag} write {n} before the budget: {error}"));
        accepted += 1;
        if engine.total_memtable_bytes() >= BUDGET {
            break;
        }
    }
    accepted
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn writes_resume_after_the_memtable_budget_fills_and_search_is_bounded() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    // The sampler stays off during the fill. Thread B would otherwise flush
    // as soon as the sum crossed the budget, and the rejection below would
    // depend on winning that race.
    let names = ["a", "b", "c", "d"];
    for name in names {
        engine
            .create_index(name, text_schema())
            .expect("create index");
    }
    let body = format!("budgettoken {}", "a".repeat(4096));
    let accepted = fill_until_budget(&engine, &names, &body, "fill").await;
    let summed = engine.total_memtable_bytes();
    assert!(
        summed >= BUDGET,
        "four indices must cross the 1 MiB budget (accepted {accepted}, summed {summed})"
    );
    for name in names {
        let idx = engine.get_index(name).unwrap();
        assert!(
            idx.memtable_bytes() < idx.flush_threshold(),
            "index {name} must still be under its own flush line"
        );
    }

    let gov = governor::global().expect("governor");
    gov.refresh_memtable(summed);
    assert!(
        gov.memtable_breaker_engaged(),
        "crossing the budget must engage the memtable breaker"
    );
    let rejected = engine
        .get_index("a")
        .unwrap()
        .index_document(Some("rejected".into()), json!({ "body": "no" }))
        .await
        .expect_err("a write at the budget must be rejected");
    let rejected = rejected.to_string();
    assert!(rejected.contains("memtable byte budget"), "{rejected}");

    // What `search_impl` does before it scans: publish while the breaker is
    // on. No sampler yet, so this is the only flush that can free the budget.
    let published = engine.publish_memtables_if_budget_engaged().await;
    assert!(published > 0, "the engaged breaker must flush a memtable");
    gov.refresh_memtable(engine.total_memtable_bytes());
    assert!(
        engine.total_memtable_bytes() < BUDGET,
        "publishing must leave the summed memtable under the budget"
    );
    assert!(!gov.memtable_breaker_engaged());

    let infos = engine.list_indices().await;
    let segments: usize = infos.iter().map(|info| info.segment_count).sum();
    assert!(
        segments > 0,
        "the pressure flush must publish a segment: {infos:?}"
    );

    let started = Instant::now();
    let req = parse_request(&json!({
        "query": { "match": { "body": "budgettoken" } },
        "size": 5,
        "from": 0
    }))
    .expect("parse");
    let mut hits = 0u64;
    for name in names {
        let page = engine
            .get_index(name)
            .unwrap()
            .search(&req)
            .await
            .expect("search");
        hits += page.total.value;
    }
    let elapsed = started.elapsed();
    assert!(
        elapsed < Duration::from_secs(5),
        "search after the flush took {elapsed:?} (the unflushed-memtable stall)"
    );
    assert!(hits > 0, "budgettoken must be searchable after the flush");
    assert!(
        hits as usize <= accepted,
        "search total {hits} exceeds accepted writes {accepted}"
    );

    // Second crossing, with the sampler running. Writes are rejected until
    // its drain publishes; the test does not call flush itself.
    engine.spawn_resource_sampler();
    let mut resumed = 0usize;
    let deadline = Instant::now() + Duration::from_secs(30);
    while resumed < accepted && Instant::now() < deadline {
        let name = names[resumed % names.len()];
        match engine
            .get_index(name)
            .unwrap()
            .index_document(
                Some(format!("again-{name}-{resumed}")),
                json!({ "body": body }),
            )
            .await
        {
            Ok(_) => resumed += 1,
            Err(error) => {
                let rendered = error.to_string();
                assert!(
                    rendered.contains("memtable byte budget"),
                    "while waiting for the sampler drain: {rendered}"
                );
                tokio::time::sleep(Duration::from_millis(50)).await;
            }
        }
    }
    assert!(
        resumed == accepted,
        "the sampler drain must admit another {accepted} writes (got {resumed}, memtable {} bytes)",
        engine.total_memtable_bytes()
    );
    // The last admitted writes can sit over the budget until the sampler's
    // next drain. That interval is 2 s; give it a few windows.
    let settle = Instant::now() + Duration::from_secs(10);
    while engine.total_memtable_bytes() >= BUDGET && Instant::now() < settle {
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    gov.refresh_memtable(engine.total_memtable_bytes());
    assert!(
        engine.total_memtable_bytes() < BUDGET,
        "the sampler drain must leave the summed memtable under the budget"
    );
    assert!(!gov.memtable_breaker_engaged());
}

//! #876 — a merge must not re-analyse the documents it merges, and the index
//! it produces must be indistinguishable from the one that did.
//!
//! The merge path used to rebuild every merged segment's FTS side-car by
//! walking back to each surviving document's stored `_source`, re-extracting
//! its field values, and re-running the analyzer chain — recomputing postings
//! that were already on disk and already correct. Under size-tiered levelling
//! that happens to every document once per level, which is why the post-index
//! merge tail rivalled the index itself.
//!
//! Two claims are tested here, and they only mean something together:
//!
//! 1. `Index::merge_reanalysed_document_count()` stays at zero across a
//!    forcemerge — the merge really did replay postings. Without this a
//!    silently-always-falling-back preflight would look perfect.
//! 2. Every hit and every `_score` is bit-for-bit what the re-analysing merge
//!    produces, which the `XERJ_MERGE_FTS_REANALYZE` arm computes in the same
//!    process from the same corpus.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// `(id, score bits)` per hit: "the same score" has to mean identical, not
/// close, or a merge that quietly moved `avgdl` would slip through.
async fn hits(idx: &Index, query: Value) -> Vec<(String, u32)> {
    let request = parse_request(&json!({ "query": query, "size": 200 })).expect("parse_request");
    idx.search(&request)
        .await
        .unwrap()
        .hits
        .iter()
        .map(|hit| (hit.id.clone(), hit.score.to_bits()))
        .collect()
}

fn queries() -> Vec<Value> {
    vec![
        // Scored text: BM25 over doc_freq, term freq, field length and avgdl
        // — every statistic the merge has to carry.
        json!({"match": {"body": "quick"}}),
        json!({"match": {"body": "otter"}}),
        json!({"match": {"body": "quick otter settled"}}),
        // Positions.
        json!({"match_phrase": {"body": "quick brown"}}),
        // Must NOT match: the two values of a multi-valued field are held
        // apart by the position-increment gap.
        json!({"match_phrase": {"body": "cobalt second"}}),
        // Docs-only (keyword) posting lists.
        json!({"term": {"tags": "tag-3"}}),
        json!({"term": {"colour": "cobalt"}}),
        json!({"match_all": {}}),
    ]
}

const DOC_COUNT: usize = 400;

fn document(index: usize) -> Value {
    const NOUNS: [&str; 6] = ["fox", "hound", "otter", "falcon", "badger", "heron"];
    const COLOURS: [&str; 4] = ["amber", "cobalt", "russet", "verdant"];
    let noun = NOUNS[index % NOUNS.len()];
    json!({
        "body": if index.is_multiple_of(7) {
            json!([
                format!("quick brown {noun} leapt past a quick {noun} and settled at {index}"),
                format!("a second value about {index}"),
            ])
        } else {
            json!(format!(
                "quick brown {noun} leapt past a quick {noun} and settled at {index}"
            ))
        },
        "tags": [format!("tag-{}", index % 11), format!("group-{}", index % 3)],
        "colour": COLOURS[index % COLOURS.len()],
        "rank": index,
    })
}

fn schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    schema
        .fields
        .push(FieldConfig::new("colour", FieldType::Keyword));
    schema
        .fields
        .push(FieldConfig::new("rank", FieldType::Long));
    schema
}

/// Ingest the corpus in eight flushes (so the merge has eight inputs), delete
/// and overwrite a slice of it (so the merge has documents to drop and stale
/// copies to skip), then forcemerge to one segment.
async fn seed_and_merge(engine: &Engine, name: &str) -> std::sync::Arc<Index> {
    engine.create_index(name, schema()).unwrap();
    let idx = engine.get_index(name).unwrap();

    for index in 0..DOC_COUNT {
        idx.index_document(Some(index.to_string()), document(index))
            .await
            .unwrap();
        if (index + 1).is_multiple_of(50) {
            idx.flush().await.unwrap();
        }
    }
    // Deleted documents leave tombstones the merge has to honour.
    for index in (0..DOC_COUNT).step_by(11) {
        idx.delete_document(&index.to_string()).await.unwrap();
    }
    // Overwritten documents leave a stale copy in an older segment that the
    // merge has to skip while keeping the new one.
    for index in (3..DOC_COUNT).step_by(37) {
        let mut updated = document(index);
        updated["body"] = json!(format!("revised heron notes for {index}"));
        idx.index_document(Some(index.to_string()), updated)
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    let merged = idx.force_merge(1).await.unwrap();
    assert!(merged >= 1, "forcemerge must actually merge something");
    idx
}

#[tokio::test(flavor = "multi_thread")]
async fn a_forcemerge_replays_postings_and_changes_no_hit_or_score() {
    // Arm A: the postings merge (the default).
    let replay_dir = TempDir::new().unwrap();
    let replay_engine = make_engine(&replay_dir);
    let replayed = seed_and_merge(&replay_engine, "replayed").await;
    assert_eq!(
        replayed.merge_reanalysed_document_count(),
        0,
        "the forcemerge fell back to re-analysing documents, so this test would \
         be comparing the old path against itself"
    );
    let mut replay_hits = Vec::new();
    for query in queries() {
        replay_hits.push(hits(&replayed, query).await);
    }

    // Arm B: the same corpus, merged the old way. The escape hatch is a
    // process-wide env var, so this arm runs after arm A has finished
    // reading, and this test owns its binary.
    std::env::set_var("XERJ_MERGE_FTS_REANALYZE", "1");
    let rebuild_dir = TempDir::new().unwrap();
    let rebuild_engine = make_engine(&rebuild_dir);
    let rebuilt = seed_and_merge(&rebuild_engine, "rebuilt").await;
    std::env::remove_var("XERJ_MERGE_FTS_REANALYZE");
    assert!(
        rebuilt.merge_reanalysed_document_count() > 0,
        "the escape hatch did not put the merge back on the re-analysing path, \
         so the comparison arm is not the old behaviour"
    );

    for (query, expected) in queries().into_iter().zip(replay_hits) {
        let actual = hits(&rebuilt, query.clone()).await;
        assert_eq!(
            actual, expected,
            "a merge that replayed postings returned different hits or scores than \
             one that re-analysed the same documents, for {query}"
        );
    }
}

// ── Measurement ──────────────────────────────────────────────────────────────

/// Peak resident set of this process so far, in MiB (`VmHWM`).
#[cfg(target_os = "linux")]
fn peak_rss_mib() -> u64 {
    std::fs::read_to_string("/proc/self/status")
        .ok()
        .and_then(|status| {
            status
                .lines()
                .find(|line| line.starts_with("VmHWM:"))
                .and_then(|line| line.split_whitespace().nth(1)?.parse::<u64>().ok())
        })
        .map(|kib| kib / 1024)
        .unwrap_or(0)
}
#[cfg(not(target_os = "linux"))]
fn peak_rss_mib() -> u64 {
    0
}

/// The #876 A/B, as a rerunnable measurement rather than an assertion.
///
/// Run each arm in its OWN process — the peak-RSS figure is a process-wide
/// high-water mark, so two arms in one process would report the larger of
/// them twice:
///
/// ```sh
/// cargo test --release -p xerj-engine --test merge_replays_postings -- \
///     --ignored --nocapture measure_forcemerge_cost
/// XERJ_MERGE_FTS_REANALYZE=1 cargo test --release -p xerj-engine \
///     --test merge_replays_postings -- --ignored --nocapture measure_forcemerge_cost
/// ```
#[tokio::test(flavor = "multi_thread")]
#[ignore = "measurement, not an assertion — see the doc comment for the two commands"]
async fn measure_forcemerge_cost() {
    // Shaped after the corpus in the issue: a few thousand large text
    // documents (~150 MB of source and prose across ~4 700 files), not many
    // small ones. The merge's old cost was proportional to the TEXT, so the
    // document size is the part that has to be realistic.
    let docs: usize = std::env::var("XERJ_876_DOCS")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(2_000);
    let words_per_doc: usize = std::env::var("XERJ_876_WORDS")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(4_000);
    const WORDS: [&str; 16] = [
        "retrieval",
        "segment",
        "posting",
        "analyzer",
        "tokenizer",
        "merge",
        "compaction",
        "throughput",
        "latency",
        "vector",
        "dictionary",
        "quantised",
        "checkpoint",
        "tombstone",
        "ordinal",
        "normalisation",
    ];

    let arm = if std::env::var("XERJ_MERGE_FTS_REANALYZE").is_ok() {
        "re-analysing merge (old path)"
    } else {
        "postings merge (#876)"
    };

    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("measure", schema()).unwrap();
    let idx = engine.get_index("measure").unwrap();

    let ingest = std::time::Instant::now();
    let mut bytes: u64 = 0;
    for index in 0..docs {
        // A wide vocabulary with a skewed reuse pattern, so the term
        // dictionary is the shape real text produces rather than sixteen
        // words repeated — the postings replay pays for distinct terms and
        // the analyzer pays for tokens, and both have to be represented.
        let body: String = (0..words_per_doc)
            .map(|word| {
                let seed = index * 7919 + word * 104_729;
                format!("{}{}", WORDS[seed % WORDS.len()], seed % 4_096)
            })
            .collect::<Vec<_>>()
            .join(" ");
        bytes += body.len() as u64;
        idx.index_document(
            Some(index.to_string()),
            json!({
                "body": body,
                "tags": [format!("tag-{}", index % 97), format!("group-{}", index % 7)],
                "colour": WORDS[index % WORDS.len()],
                "rank": index,
            }),
        )
        .await
        .unwrap();
        if (index + 1).is_multiple_of(250) {
            idx.flush().await.unwrap();
        }
    }
    idx.flush().await.unwrap();
    let ingest = ingest.elapsed();
    let rss_after_ingest = peak_rss_mib();

    let merge = std::time::Instant::now();
    let merged = idx.force_merge(1).await.unwrap();
    let merge = merge.elapsed();

    eprintln!(
        "#876 {arm}\n  docs={docs} text={}MiB ingest={:.2}s batches_merged={merged}\n  \
         FORCEMERGE={:.2}s  re-analysed_docs={}  peak_rss={}MiB (was {}MiB after ingest)",
        bytes / (1024 * 1024),
        ingest.as_secs_f64(),
        merge.as_secs_f64(),
        idx.merge_reanalysed_document_count(),
        peak_rss_mib(),
        rss_after_ingest,
    );
}

//! Issue #846: bool `minimum_should_match` must honor NEGATIVE integers
//! (`-1` = all-but-one), negative percentages, and COMBINATION specs
//! (`"3<90%"`). These previously failed to parse and dropped to `None`, so the
//! bool silently behaved as a plain OR (default msm 1) — more hits than ES.
//!
//! Asserted flush-invariant (buffered memtable AND flushed segment) because the
//! FTS/columnar fast paths decline these specs and route to the stored-doc
//! scan; both must agree.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn hits(engine: &Engine, q: &serde_json::Value) -> u64 {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 0 })).expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

#[tokio::test]
async fn bool_min_should_match_honors_negative_and_combination() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    // Single-valued fields (one per should-clause) so "how many should clauses
    // match" is unambiguous — avoids multi-valued-array term counting.
    let mut schema = Schema::empty();
    for f in ["fa", "fb", "fc"] {
        schema.fields.push(FieldConfig::new(f, FieldType::Keyword));
    }
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    // How many of the three should-clauses each doc satisfies:
    for (id, doc) in [
        ("d0", json!({ "fa": "y", "fb": "y", "fc": "y" })), // 3
        ("d1", json!({ "fa": "y", "fb": "y" })),            // 2
        ("d2", json!({ "fa": "y" })),                       // 1
        ("d3", json!({ "fa": "n" })),                       // 0
    ] {
        idx.index_document(Some(id.to_string()), doc)
            .await
            .expect("index");
    }

    // Three should clauses on distinct fields. `required` varies by the msm spec.
    let boolq = |msm: serde_json::Value| {
        json!({ "bool": {
            "should": [
                {"term": {"fa": "y"}}, {"term": {"fb": "y"}}, {"term": {"fc": "y"}}
            ],
            "minimum_should_match": msm
        }})
    };

    // (spec, expected_hits, label). should_count = 3.
    let cases = [
        (json!(-1), 2, "negative -1: required 2 → d0,d1"),
        (json!("-1"), 2, "string -1: required 2 → d0,d1"),
        (json!(-2), 3, "negative -2: required 1 → d0,d1,d2"),
        (json!("2<-1"), 2, "combination 2<-1: 3>2 → -1 → required 2"),
        (
            json!("3<90%"),
            1,
            "combination 3<90%: 3<=3 → all required → d0",
        ),
    ];

    // Answer every case buffered, flush once, answer again — assert agreement
    // AND the ES-correct count.
    let mut pre = Vec::new();
    for (msm, _, _) in &cases {
        pre.push(hits(&engine, &boolq(msm.clone())).await);
    }
    idx.refresh().await.expect("refresh");
    for (i, (msm, expected, label)) in cases.iter().enumerate() {
        let post = hits(&engine, &boolq(msm.clone())).await;
        assert_eq!(pre[i], post, "#846: msm must be flush-invariant — {label}");
        assert_eq!(post, *expected, "#846: {label}");
    }
}

//! #860 / #846: semantically different `minimum_should_match` specs on an
//! otherwise identical query must NOT collide in the query-result cache.
//!
//! The cache key hashes the serialized request. `MinShouldMatch` is an untagged
//! enum, so a derived `Serialize` emitted `Negative(2)` and `Percentage(2)` as
//! the bare number `2` — identical to `Fixed(2)` — so a `msm:-2` query and a
//! `msm:2` query hashed the same and the second returned the first's cached
//! count. A hand-written `Serialize` gives every spec a distinct wire form.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn hits(engine: &Engine, q: &serde_json::Value) -> u64 {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 0 })).expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

#[tokio::test]
async fn msm_specs_do_not_collide_in_the_query_cache() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    for f in ["fa", "fb", "fc"] {
        schema.fields.push(FieldConfig::new(f, FieldType::Keyword));
    }
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    for (id, doc) in [
        ("d0", json!({ "fa": "y", "fb": "y", "fc": "y" })), // 3 should match
        ("d1", json!({ "fa": "y", "fb": "y" })),            // 2
        ("d2", json!({ "fa": "y" })),                       // 1
    ] {
        idx.index_document(Some(id.to_string()), doc)
            .await
            .expect("index");
    }

    let boolq = |msm: serde_json::Value| {
        json!({ "bool": {
            "should": [
                {"term": {"fa": "y"}}, {"term": {"fb": "y"}}, {"term": {"fc": "y"}}
            ],
            "minimum_should_match": msm
        }})
    };

    // Run the LOW-required spec first so it would poison the cache for the
    // high-required spec if their keys collided.
    // Negative(2): required 3-2 = 1 → d0,d1,d2 = 3.
    assert_eq!(
        hits(&engine, &boolq(json!(-2))).await,
        3,
        "msm:-2 → required 1"
    );
    // Fixed(2): required 2 → d0,d1 = 2. MUST NOT read the msm:-2 entry.
    assert_eq!(
        hits(&engine, &boolq(json!(2))).await,
        2,
        "#860: Fixed msm:2 must not collide with the earlier Negative(2) cache entry"
    );

    // Percentage(2) required floor(3*.02).max(1) = 1 → 3 hits; must also not
    // collide with Fixed(2) (the pre-existing bare-number collision).
    assert_eq!(
        hits(&engine, &boolq(json!("2%"))).await,
        3,
        "msm:2% → required 1"
    );
    assert_eq!(
        hits(&engine, &boolq(json!(2))).await,
        2,
        "#860: Fixed msm:2 must not collide with Percentage(2) either"
    );
}

//! Regression tests for issue #218: the matched SET of a multi-token
//! `match`/`multi_match` must be identical before and after `flush()`.
//!
//! Pre-fix, the memtable membership test for `multi_match` (best_fields /
//! most_fields, default operator) was `field_text.contains(whole_query)` —
//! whole-query substring containment, i.e. every token adjacent and in
//! order — while the segment path lowered the same query to a per-field
//! OR-bool over tokens (ES default `operator: or`). A doc containing only
//! SOME of the query tokens was therefore invisible until `_flush`, and
//! the hit set changed with flush timing. The reverse divergence existed
//! for `operator: and` and the phrase types: the segment FTS projection
//! ignored them and OR'd the tokens, so post-flush over-matched.
//!
//! Every test seeds one index, runs ALL its queries against the memtable
//! (pre-flush), flushes ONCE, re-runs the same queries against the segment
//! (post-flush), and asserts each query's matched id set is the expected
//! one in BOTH states — i.e. flush timing never changes the hit set.

use std::collections::BTreeSet;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

async fn ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

/// Run every (query, expected-ids, label) case against the memtable,
/// flush once, run every case again against the segment, and assert the
/// hit set is the expected one in both states.
async fn assert_flush_parity(idx: &std::sync::Arc<Index>, cases: &[(Value, &[&str], &str)]) {
    let expected: Vec<BTreeSet<String>> = cases
        .iter()
        .map(|(_, exp, _)| exp.iter().map(|s| s.to_string()).collect())
        .collect();
    for ((q, _, label), exp) in cases.iter().zip(&expected) {
        let pre = ids(idx, q).await;
        assert_eq!(
            &pre, exp,
            "{label}: PRE-flush (memtable) hit set wrong for {q}"
        );
    }
    idx.flush().await.unwrap();
    for ((q, _, label), exp) in cases.iter().zip(&expected) {
        let post = ids(idx, q).await;
        assert_eq!(
            &post, exp,
            "{label}: POST-flush (segment) hit set wrong for {q}"
        );
    }
}

/// One index, two docs. Doc 1 is the reproducer from issue #218; doc 2 is
