}

/// `slop` on a `phrase_prefix` is HONOURED, at both entry points and in
/// both states. ES honours it (`TextFieldMapper.createPhrasePrefixQuery`
/// builds a `MultiPhrasePrefixQuery` and calls `setSlop`), so refusing it
/// would break clients, and dropping it — which `parse_match_phrase_prefix`
/// did — is the accept-and-ignore defect class of #204: the `multi_match`
/// and `match_phrase_prefix` spellings of the same query must not disagree.
///
/// Doc 1's `body` analyses to [the, log, merge, policy, …]: the phrase
/// `log poli*` needs one intervening position, so slop 0 misses and slop 1
/// hits.
#[tokio::test]
async fn phrase_prefix_slop_is_honoured_at_both_entry_points() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mmpp_prefix_slop").await;

    assert_both_states(
        &idx,
        &[
            (
                json!({"multi_match": {"query": "log poli", "fields": ["body"],
                                       "type": "phrase_prefix"}}),
                &[],
                "phrase_prefix slop 0 (default): one intervening token → no match",
            ),
            (
                json!({"multi_match": {"query": "log poli", "fields": ["body"],
                                       "type": "phrase_prefix", "slop": 1}}),
                &["1"],
                "phrase_prefix slop 1: one intervening token → match",
            ),
            (
                json!({"match_phrase_prefix": {"body": {"query": "log poli", "slop": 1}}}),
                &["1"],
                "oracle match_phrase_prefix slop 1 answers the same query",
            ),
            (
                json!({"match_phrase_prefix": {"body": {"query": "log poli"}}}),
                &[],
                "oracle match_phrase_prefix slop 0",
            ),
        ],
    )
    .await;
}

/// A negative `slop` is a client error in ES from all three *phrase* builders
/// (`MatchPhraseQueryBuilder` / `MatchPhrasePrefixQueryBuilder:103` /
/// `MultiMatchQueryBuilder:350`, all "No negative slop allowed"), so all three
/// must answer alike here — a 400 from one spelling and a silently coerced 0
/// from the other is the same accept-and-ignore defect wearing a different hat.
///
/// SCOPE, stated so the name cannot be read as more than it is: these three
/// query types are the whole of it. `span_near` also takes a `slop` and is
/// **not** covered — it keeps `as_u64().unwrap_or(0)`, so `span_near` with
/// `slop: -1` returns 200 with the value silently 0. That is a pre-existing
/// gap, recorded at `parse_span_near`, and it is left alone because ES applies
/// no validation to `span_near.slop` either
/// (`SpanNearQueryBuilder.java:62`) — rejecting it would break a query ES
/// answers.
#[test]
fn negative_slop_is_rejected_at_the_three_phrase_entry_points() {
    for bad in [
        json!({"multi_match": {"query": "merge policy", "fields": ["body"],
                               "type": "phrase", "slop": -1}}),
        json!({"match_phrase": {"body": {"query": "merge policy", "slop": -1}}}),
        json!({"match_phrase_prefix": {"body": {"query": "merge poli", "slop": -1}}}),
    ] {
        let err = parse_request(&json!({"query": bad}))
            .expect_err("negative slop must be rejected, not coerced to 0");
        assert!(
            err.to_string().contains("slop"),
            "error should name the offending parameter, got: {err}"
        );
    }
}

/// A float-encoded `slop` (`2.0`) must be honoured as 2, not refused and not
/// dropped. ES reads slop with `XContentParser.intValue()` under its default
/// coercing policy, which truncates a float token and narrows a numeric string
/// (`AbstractXContentParser.java:171` `intValue(coerce)` → `:162` `parseInt`,
/// with the truncation note at `:70`), so `{"slop": 2.0}` is a
/// query ES answers with slop 2.
///
/// This test exists because an earlier revision of this branch tightened the
/// parse to `as_i64()` and turned `2.0` into a 400 — a new refusal on a
/// request `main` answered, which is exactly the wire break this PR declined
/// to make elsewhere. The two wrong answers are symmetrical: refusing the
/// value, or silently substituting 0 as `main` did.
#[test]
fn float_and_string_encoded_slop_are_coerced_like_es() {
    for (body, want) in [
        (json!({"query": "merge policy", "slop": 2.0}), 2u32),
        (json!({"query": "merge policy", "slop": 2.7}), 2),
        (json!({"query": "merge policy", "slop": "2"}), 2),
    ] {
        let q = json!({"match_phrase": {"body": body.clone()}});
        let parsed = parse_request(&json!({ "query": q }))
            .unwrap_or_else(|e| panic!("ES coerces this slop, so it must parse: {body} -> {e}"));
        match parsed.query {
            QueryNode::MatchPhrase { slop, .. } => {
                assert_eq!(slop, want, "expected slop {want} from {body}, got {slop}")
            }
            other => panic!("expected a MatchPhrase node, got {other:?}"),
        }
    }

    // The same coercion, and the same refusal to ignore, on `max_expansions`:
    // a float is read, and a value that cannot be read is a 400 rather than
    // a silent fall back to 50 (which is what `main` did here).
    let parsed = parse_request(&json!({"query": {"match_phrase_prefix": {
        "body": {"query": "merge poli", "max_expansions": 7.0}}}}))
    .expect("float max_expansions is coerced, not refused");
    match parsed.query {
        QueryNode::MatchPhrasePrefix { max_expansions, .. } => assert_eq!(max_expansions, 7),
        other => panic!("expected a MatchPhrasePrefix node, got {other:?}"),
    }
    for bad in [
        json!({"match_phrase_prefix": {"body": {"query": "merge poli", "max_expansions": -1}}}),
        json!({"match_phrase_prefix": {"body": {"query": "merge poli",
                                                "max_expansions": "seven"}}}),
    ] {
        parse_request(&json!({ "query": bad.clone() })).unwrap_err();
    }
}

/// The stored-scan/memtable evaluator and the positional segment clause
/// must tokenize with the SAME analyzer, or they answer different queries
/// and the hit set changes at `_flush` — the regression class #218/#222
/// removed and that #230 names as the standing invariant.
///
/// An earlier revision of this fix tokenized the memtable side by splitting
/// on `!char::is_alphanumeric()` while the segment clause was built from the
/// `standard` analyzer (UAX#29 `unicode_words()`). The two disagree on
/// intra-word `.`, `'` and `_`: `3.14`, `don't` and `foo_bar` are ONE
/// analyzed term each and two-or-three split ones. Each case below returned
/// a hit pre-flush and none post-flush at that revision; the analyzed answer
/// (no hit — the terms never line up) is also the one ES gives.
#[tokio::test]
async fn phrase_tokenizer_matches_the_segment_analyzer() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("mmpp_tok", Schema::empty()).unwrap();
    let idx = engine.get_index("mmpp_tok").unwrap();
    for (id, body) in [
        ("n1", "release 3.14 notes here"),
        ("d1", "we don't stop now"),
        ("u1", "the foo_bar baz"),
    ] {
        idx.index_document(Some(id.into()), json!({ "body": body }))
            .await
            .unwrap();
    }

    assert_both_states(
        &idx,
        &[
            (
                json!({"multi_match": {"query": "release 3", "fields": ["body"],
                                       "type": "phrase"}}),
                &[],
                "`3.14` is ONE analyzed term, so `release 3` is not a phrase in it",
            ),
            (
                json!({"match_phrase": {"body": "release 3"}}),
                &[],
                "oracle match_phrase agrees",
            ),
            (
                json!({"multi_match": {"query": "don t", "fields": ["body"],
                                       "type": "phrase"}}),
                &[],
                "`don't` is ONE analyzed term, so `don t` is not a phrase in it",
            ),
            (
                json!({"multi_match": {"query": "foo bar", "fields": ["body"],
                                       "type": "phrase"}}),
                &[],
                "`foo_bar` is ONE analyzed term, so `foo bar` is not a phrase in it",
            ),
            // The whole analyzed term still matches, in both states.
            (
                json!({"multi_match": {"query": "release 3.14", "fields": ["body"],
                                       "type": "phrase"}}),
                &["n1"],
                "the analyzed term itself matches",
            ),
            (
                json!({"multi_match": {"query": "we don't", "fields": ["body"],
                                       "type": "phrase"}}),
                &["d1"],
                "the analyzed term itself matches (apostrophe)",
            ),
        ],
    )
    .await;
}

/// `max_expansions` is why `phrase_prefix` keeps the declined/stored-scan
/// routing on `multi_match`: the segment clause bounds the trailing prefix
/// to `max_expansions` terms from the field's term dictionary, and the
/// stored-doc walk — which has no term dictionary — cannot. Projecting it
/// made the hit set shrink at `_flush`.
///
/// This asserts the INVARIANT (same answer either side of the flush), not
/// ES parity: XERJ does not bind `max_expansions` on `multi_match`, so both
/// states return the unbounded answer. Stated plainly rather than papered
/// over — flush invariance is the property #230 asks for.
///
/// HONEST LIMIT of this test: it also passes against the revision that DID
/// project `phrase_prefix` (checked out and run — 7 passed, 3 failed, and
/// this was not one of the three), so it is an invariant assertion, not a
/// regression catcher. This in-process fixture does not reliably route the
/// query through the bounded segment clause the way a mapped index on a
/// live server does, which is where the review measured the shrink
/// (pre {p1,p2,p3,p4,s1} / post {p1,p2,p3,p4}). The discriminating guard
/// for the routing decision is the unit test
/// `index::fts_projection_tests::multi_match_phrase_projects_positional_dis_max`,
/// which asserts `query_node_to_fts` returns `None` for `phrase_prefix`.
#[tokio::test]
async fn phrase_prefix_max_expansions_does_not_change_the_hit_set_at_flush() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("mmpp_maxexp", Schema::empty()).unwrap();
    let idx = engine.get_index("mmpp_maxexp").unwrap();
    // `pol*` expands to two dictionary terms — `polar` sorts first, so a
    // max_expansions of 1 would keep only it on a bounded segment clause.
    for (id, body) in [
        ("p1", "a tiered merge policy compacts segments"),
        ("p2", "the merge polar route"),
    ] {
        idx.index_document(Some(id.into()), json!({ "body": body }))
            .await
            .unwrap();
    }

    assert_both_states(
        &idx,
        &[(
            json!({"multi_match": {"query": "merge pol", "fields": ["body"],
                                   "type": "phrase_prefix", "max_expansions": 1}}),
            &["p1", "p2"],
            "multi_match phrase_prefix hit set is the same before and after _flush",
        )],
    )
    .await;
}

//! Regression tests: `multi_match` must return non-zero, ES-shaped scores.
//!
//! Bug: every multi_match hit came back with `_score: 0.0` on the segment
//! FTS path because `BoolQuery::new()` defaulted `boost` to 0.0 and
//! `execute_bool` multiplies the combined score by it.  ES 8.x semantics:
//! `best_fields` (the default type) is a dis_max over per-field match
//! queries — the hit score is the MAX of the per-field scores; a
//! single-field multi_match scores identically to the equivalent `match`.

use std::collections::HashMap;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

#[tokio::test]
async fn multi_match_scores_nonzero_and_best_fields_takes_field_max() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("mm", Schema::empty()).unwrap();
    let idx = engine.get_index("mm").unwrap();

    // 20 docs: "golf" in msg for i % 3 == 0, in note for i % 5 == 0, so the
    // multi_match union (9 docs: i%3==0 or i%5==0) differs from either
    // single-field result (7 via msg, 4 via note, 2 overlap).
    for i in 0..20 {
        let msg = if i % 3 == 0 {
            format!("user played golf round {i}")
        } else {
            format!("user played tennis {i}")
        };
        let note = if i % 5 == 0 { "golf note" } else { "misc" };
        idx.index_document(Some(format!("d{i}")), json!({"msg": msg, "note": note}))
            .await
            .unwrap();
    }

    // ── Memtable state: scores must not be zero ──────────────────────────
    let r = idx
        .search(&req(
            json!({"multi_match": {"query": "golf", "fields": ["msg", "note"]}}),
        ))
        .await
        .unwrap();
    assert_eq!(r.total.value, 9, "memtable multi_match union");
    for h in &r.hits {
        assert!(
            h.score > 0.0,
            "memtable multi_match hit {} scored 0.0",
            h.id
        );
    }

    // ── Segment state: BM25 scores, ES best_fields semantics ─────────────
    idx.flush().await.unwrap();

    let match_msg = idx
        .search(&req(json!({"match": {"msg": "golf"}})))
        .await
        .unwrap();
    let match_note = idx
        .search(&req(json!({"match": {"note": "golf"}})))
        .await
        .unwrap();
    let msg_scores: HashMap<&str, f32> = match_msg
        .hits
        .iter()
        .map(|h| (h.id.as_str(), h.score))
        .collect();
    let note_scores: HashMap<&str, f32> = match_note
        .hits
        .iter()
        .map(|h| (h.id.as_str(), h.score))
        .collect();
    assert!(match_msg.hits.iter().all(|h| h.score > 0.0));

    // Single-field multi_match must score IDENTICALLY to the match query.
    let mm_single = idx
        .search(&req(
            json!({"multi_match": {"query": "golf", "fields": ["msg"]}}),
        ))
        .await
        .unwrap();
    assert_eq!(mm_single.total.value, match_msg.total.value);
    for h in &mm_single.hits {
        let expected = msg_scores.get(h.id.as_str()).copied().unwrap_or(0.0);
        assert!(
            h.score > 0.0,
            "single-field multi_match hit {} scored 0.0",
            h.id
        );
        assert!(
            (h.score - expected).abs() < 1e-5,
            "hit {}: multi_match(msg) score {} != match(msg) score {}",
            h.id,
            h.score,
            expected
        );
    }

    // Multi-field best_fields: score = max(per-field match scores).
    let mm = idx
        .search(&req(
            json!({"multi_match": {"query": "golf", "fields": ["msg", "note"]}}),
        ))
        .await
        .unwrap();
    assert_eq!(mm.total.value, 9, "segment multi_match union");
    for h in &mm.hits {
        let ms = msg_scores.get(h.id.as_str()).copied().unwrap_or(0.0);
        let ns = note_scores.get(h.id.as_str()).copied().unwrap_or(0.0);
        let expected = ms.max(ns);
        assert!(
            h.score > 0.0,
            "multi-field multi_match hit {} scored 0.0",
            h.id
        );
        assert!(
            (h.score - expected).abs() < 1e-5,
            "hit {}: best_fields score {} != max(msg {}, note {})",
            h.id,
            h.score,
            ms,
            ns
        );
    }

    // most_fields: score = sum of the per-field scores.
    let mm_most = idx
        .search(&req(json!({
            "multi_match": {"query": "golf", "fields": ["msg", "note"], "type": "most_fields"}
        })))
        .await
        .unwrap();
    assert_eq!(mm_most.total.value, 9);
    for h in &mm_most.hits {
        let ms = msg_scores.get(h.id.as_str()).copied().unwrap_or(0.0);
        let ns = note_scores.get(h.id.as_str()).copied().unwrap_or(0.0);
        let expected = ms + ns;
        assert!(
            (h.score - expected).abs() < 1e-5,
            "hit {}: most_fields score {} != sum(msg {}, note {})",
            h.id,
            h.score,
            ms,
            ns
        );
    }
}

//! Regression tests for #217 — `multi_match` naming an UNMAPPED field.
//!
//! ES ignores unmapped fields in `multi_match`: the query runs over the
//! mapped subset, and only when EVERY field is unmapped does it match
//! nothing (no error either way). XERJ instead built an FTS clause for the
//! unmapped field; the per-segment "reader has every queried field" gate
//! then refused the postings path for the WHOLE query, and the stored-doc
//! fallback — whose default multi_match arm requires the entire query
//! string as one contiguous substring — silently zeroed every multi-token
//! query. Single-token queries survived because the one token IS the whole
//! string, which is what kept the bug invisible to the ES-YAML suite.
//!
//! Every search here runs AFTER a flush: the memtable path has a separate,
//! still-open multi-token divergence (MULTIMATCH_DEFECT.md, defect 2) that
//! these tests deliberately do not encode expectations for.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

/// One flushed doc with two mapped text fields (`body`, `title`); `ghost`
/// never appears anywhere, so dynamic mapping never creates it.
async fn seed(engine: &Engine, name: &str) -> std::sync::Arc<xerj_engine::Index> {
    engine.create_index(name, Schema::empty()).unwrap();
    let idx = engine.get_index(name).unwrap();
    idx.index_document(
        Some("1".to_string()),
        json!({
            "body": "the log merge policy groups segments into size buckets",
            "title": "merge policy"
        }),
    )
    .await
    .unwrap();
    idx.flush().await.unwrap();
    idx
}

/// #217 headline: an unmapped field must not change the result of a
/// multi-token query — same hits as the identical query without it.
#[tokio::test]
async fn unmapped_field_must_not_zero_a_multi_token_multi_match() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mm217").await;

    let control = idx
        .search(&req(json!({"multi_match": {
            "query": "merge zzzznotpresent", "fields": ["body"]}})))
        .await
        .unwrap();
    assert_eq!(control.total.value, 1, "control: one token present in body");

    let with_ghost = idx
        .search(&req(json!({"multi_match": {
            "query": "merge zzzznotpresent", "fields": ["body", "ghost"]}})))
        .await
        .unwrap();
    assert_eq!(
        with_ghost.total.value, 1,
        "an unmapped field removed a document the mapped subset matches (#217)"
    );
    assert_eq!(
        control.hits[0].id, with_ghost.hits[0].id,
        "same document either way"
    );
}

/// Single-token shape with the same unmapped field — the case that already
/// worked (via the stored scan) and must keep working on the postings path.
#[tokio::test]
async fn unmapped_field_single_token_still_matches() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mm217_single").await;

    let r = idx
        .search(&req(json!({"multi_match": {
            "query": "merge", "fields": ["body", "ghost"]}})))
        .await
        .unwrap();
    assert_eq!(r.total.value, 1);
}

/// EVERY named field unmapped: ES semantics — match nothing, no error.
#[tokio::test]
async fn all_fields_unmapped_matches_nothing_without_error() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mm217_allghost").await;

    for query in ["merge zzzznotpresent", "merge"] {
        let r = idx
            .search(&req(json!({"multi_match": {
                "query": query, "fields": ["ghost1", "ghost2"]}})))
            .await
            .unwrap();
        assert_eq!(
            r.total.value, 0,
            "query {query:?} over only unmapped fields"
        );
    }
}

/// The same zeroing hit every field-centric type through the shared
/// lowering; `most_fields` is the non-dis_max shape.
#[tokio::test]
async fn most_fields_multi_token_with_unmapped_field() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mm217_most").await;

    let r = idx
        .search(&req(json!({"multi_match": {
            "query": "merge zzzznotpresent",
            "fields": ["body", "ghost"],
            "type": "most_fields"}})))
        .await
        .unwrap();
    assert_eq!(r.total.value, 1, "most_fields shares the lowering (#217)");
}

/// `operator: and` binds PER FIELD (ES best_fields/most_fields build one
/// match query per field with the operator): a document matches only when
/// ONE field holds every token. The pre-fix FTS lowering ignored the
/// operator and OR'd the tokens, over-matching whenever every named field
/// was mapped.
#[tokio::test]
async fn operator_and_requires_every_token_in_one_field() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mm217_and").await;

    // No single field holds both "merge" and "zzzznotpresent" → 0 hits.
    let r = idx
        .search(&req(json!({"multi_match": {
            "query": "merge zzzznotpresent",
            "fields": ["body", "title"],
            "operator": "and"}})))
        .await
        .unwrap();
    assert_eq!(
        r.total.value, 0,
        "operator:and must not degrade to OR over tokens"
    );

    // `body` holds both tokens; the unmapped field must not change that —
    // and in particular must not flip the query from AND onto an OR path.
    let r = idx
        .search(&req(json!({"multi_match": {
            "query": "merge policy",
            "fields": ["body", "ghost"],
            "operator": "and"}})))
        .await
        .unwrap();
    assert_eq!(r.total.value, 1, "mapped subset satisfies per-field AND");
}

/// `cross_fields` + `operator: and` is term-centric — every token must
/// appear in at least ONE of the (mapped) fields, NOT all in the same one.
/// Here `bravo` lives only in `alpha` and `charlie` only in `beta`, so a
/// per-field AND would find nothing while the combined view matches — with
/// or without an unmapped field in the list.
#[tokio::test]
async fn cross_fields_and_matches_across_fields() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("mm217_cross", Schema::empty()).unwrap();
    let idx = engine.get_index("mm217_cross").unwrap();
    idx.index_document(
        Some("1".to_string()),
        json!({ "alpha": "delta bravo", "beta": "charlie echo" }),
    )
    .await
    .unwrap();
    idx.flush().await.unwrap();

    for fields in [json!(["alpha", "beta"]), json!(["alpha", "beta", "ghost"])] {
        let r = idx
            .search(&req(json!({"multi_match": {
                "query": "bravo charlie",
                "fields": fields,
                "type": "cross_fields",
                "operator": "and"}})))
            .await
            .unwrap();
        assert_eq!(
            r.total.value, 1,
            "combined-text AND across mapped fields ({fields})"
        );
    }
}

//! Regression tests for issue #332: a multi-valued keyword field was
//! flattened into ONE FTS token.
//!
//! `{"tags": ["red", "blue"]}` on a `keyword` field used to be joined into the
//! single string `"red blue"` before the FTS layer saw it
//! (`memtable::extract_text_value` / `index::extract_field_text`, both doing
//! `arr.join(" ")`).  The keyword analyzer emits its whole input as one token,
//! so the segment carried the term `"red blue"` and neither `"red"` nor
//! `"blue"` existed as a posting.  Every clause that projects to a whole-value
//! `FtsQuery::Term` therefore missed the document once it was flushed.
//!
//! Measured on `main` at d8be09cf, one doc `{"tags": ["red","blue"]}`, `tags`
//! mapped `keyword` — the exact inverse of Elasticsearch, and the hit set
//! CHANGES at `_flush`:
//!
//! ```text
//! BEFORE flush | term tags=red   (first value)              -> 1 hit(s)
//! BEFORE flush | term tags=blue  (non-first value)          -> 0 hit(s)
//! BEFORE flush | term tags='red blue' (joined artefact)     -> 0 hit(s)
//! AFTER  flush | term tags=red   (first value)              -> 0 hit(s)
//! AFTER  flush | term tags=blue  (non-first value)          -> 0 hit(s)
//! AFTER  flush | term tags='red blue' (joined artefact)     -> 1 hit(s)
//! ```
//!
//! The pre-flush half had a second, independent cause: the memtable's
//! single-valued doc-values columns keep only an array's FIRST element, and
//! the fused columnar walk that serves a bare `term` never bailed out on such
//! a field the way its three sibling paths did.
//!
//! Nearly every case below asserts the hit set is the same BEFORE and AFTER
//! `flush()`: this class of defect is flush-dependent, and a post-flush-only
//! assertion would pass on a build that had simply stopped indexing the field.
//! The one deliberate exception is documented at its assertion.

use std::collections::BTreeSet;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

async fn ids(idx: &Index, q: &Value) -> BTreeSet<String> {
    idx.search(&req(q.clone()))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

fn expect(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

/// Two docs, one index:
/// * `1` — multi-valued keyword `tags: ["red","blue"]`, multi-valued text
///   `notes: ["alpha bravo","charlie delta"]`
/// * `2` — the single-valued control, `tags: "red"`, `notes: "alpha bravo"`
async fn seed(engine: &Engine, name: &str) -> std::sync::Arc<Index> {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("notes", FieldType::Text));
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    engine.create_index(name, schema).unwrap();
    let idx = engine.get_index(name).unwrap();
    idx.index_document(
        Some("1".into()),
        json!({
            "body": "hello",
            "tags": ["red", "blue"],
            "notes": ["alpha bravo", "charlie delta"]
        }),
    )
    .await
    .unwrap();
    idx.index_document(
        Some("2".into()),
        json!({"body": "hello", "tags": "red", "notes": "alpha bravo"}),
    )
    .await
    .unwrap();
    idx
}

/// Run every case pre-flush and post-flush and require the same hit set.
async fn assert_flush_parity(idx: &std::sync::Arc<Index>, cases: &[(Value, &[&str], &str)]) {
    for (q, exp, label) in cases {
        assert_eq!(
            ids(idx, q).await,
            expect(exp),
            "{label}: PRE-flush (memtable) hit set wrong for {q}"
        );
    }
    idx.flush().await.unwrap();
    for (q, exp, label) in cases {
        assert_eq!(
            ids(idx, q).await,
            expect(exp),
            "{label}: POST-flush (segment) hit set wrong for {q}"
        );
    }
}

#[tokio::test]
async fn term_match_multi_match_see_every_keyword_array_element() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mvk_terms").await;

    assert_flush_parity(
        &idx,
        &[
            // The headline: an exact `term` for one element of the array.
            (json!({"term": {"tags": "red"}}), &["1", "2"], "term red"),
            (json!({"term": {"tags": "blue"}}), &["1"], "term blue"),
            // `match` on a keyword field lowers to the same whole-value term.
            (json!({"match": {"tags": "red"}}), &["1", "2"], "match red"),
            (json!({"match": {"tags": "blue"}}), &["1"], "match blue"),
            // `multi_match` — the clause that visibly missed doc 1 on `main`.
            (
                json!({"multi_match": {"query": "red", "fields": ["tags", "body"]}}),
                &["1", "2"],
                "multi_match red",
            ),
            (
                json!({"multi_match": {"query": "blue", "fields": ["tags", "body"]}}),
                &["1"],
                "multi_match blue",
            ),
            // `terms` takes the stored-scan route and always agreed with ES;
            // keep it as the in-binary control that the two routes now match.
            (
                json!({"terms": {"tags": ["blue"]}}),
                &["1"],
                "terms control",
            ),
            (
                json!({"bool": {"must": [{"match": {"body": "hello"}}],
                                "filter": [{"terms": {"tags": ["red"]}}]}}),
                &["1", "2"],
                "bool must+filter control",
            ),
        ],
    )
    .await;
}

/// The joined string must NOT survive as a term. Pre-fix `"red blue"` was
/// the ONLY term the segment held for doc 1, so this query matched it —
/// exactly backwards from Elasticsearch, where no keyword value equals
/// `"red blue"`.
#[tokio::test]
async fn joined_array_is_not_a_term() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mvk_joined").await;

    assert_flush_parity(
        &idx,
        &[(json!({"term": {"tags": "red blue"}}), &[], "term joined")],
    )
    .await;

    // `multi_match` for the joined string is asserted POST-flush only, and
    // deliberately so.  The segment is the side this fix owns, and it is now
    // right: no keyword value equals `"red blue"`, so nothing matches.  The
    // memtable answers `{"1","2"}` instead — but NOT because of arrays.  The
    // stored-source scan that serves a memtable-resident `multi_match` /
    // `match` whitespace-splits the query and ORs the tokens without ever
    // consulting the mapping, so it treats a `keyword` field as analyzed
    // `text`.  Doc 2 carries the SCALAR `tags: "red"` and diverges the same
    // way with no array anywhere in the index, which is what makes this a
    // separate defect rather than an unfinished corner of #332 — filed as
    // #354, whose fix wants its own ES-YAML run.
    idx.flush().await.unwrap();
    assert_eq!(
        ids(
            &idx,
            &json!({"multi_match": {"query": "red blue", "fields": ["tags"]}})
        )
        .await,
        expect(&[]),
        "POST-flush: the joined array must not be reachable as a multi_match term"
    );
}

/// A phrase must not span two elements of an array — Lucene separates them by
/// `position_increment_gap` (100), and so does the segment writer now.
/// Pre-fix BOTH sides said 1 hit for `"bravo charlie"` (measured on d8be09cf):
/// the joined string put `bravo` and `charlie` at adjacent positions in the
/// segment, and the stored-source scan matched the same joined text.
#[tokio::test]
async fn phrase_does_not_span_array_elements() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mvk_phrase").await;

    assert_flush_parity(
        &idx,
        &[
            (
                json!({"match_phrase": {"notes": "bravo charlie"}}),
                &[],
                "match_phrase across the boundary",
            ),
            (
                json!({"multi_match": {"query": "bravo charlie",
                                       "fields": ["notes"], "type": "phrase"}}),
                &[],
                "multi_match phrase across the boundary",
            ),
            // ... but a phrase WITHIN one element still matches, in both docs
            // for the first element and only doc 1 for the second.
            (
                json!({"match_phrase": {"notes": "alpha bravo"}}),
                &["1", "2"],
                "match_phrase inside element 0",
            ),
            (
                json!({"multi_match": {"query": "charlie delta",
                                       "fields": ["notes"], "type": "phrase"}}),
                &["1"],
                "multi_match phrase inside element 1",
            ),
        ],
    )
    .await;
}

/// A `terms` aggregation over a multi-valued keyword field buckets EVERY
/// value, and the answer does not change at flush.
#[tokio::test]
async fn terms_agg_buckets_every_array_element() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mvk_agg").await;

    let body = json!({
        "query": {"match_all": {}},
        "size": 0,
        "aggs": {"t": {"terms": {"field": "tags"}}}
    });
    let expected = json!([
        {"key": "red", "doc_count": 2},
        {"key": "blue", "doc_count": 1}
    ]);

    for state in ["PRE-flush", "POST-flush"] {
        if state == "POST-flush" {
            idx.flush().await.unwrap();
        }
        let res = idx.search(&parse_request(&body).unwrap()).await.unwrap();
        let buckets = res
            .aggs
            .as_ref()
            .and_then(|a| a["t"]["buckets"].as_array())
            .cloned()
            .unwrap_or_default();
        let trimmed: Vec<Value> = buckets
            .iter()
            .map(|b| json!({"key": b["key"], "doc_count": b["doc_count"]}))
            .collect();
        assert_eq!(
            Value::Array(trimmed),
            expected,
            "{state}: terms agg over a multi-valued keyword field"
        );
    }
}

/// `_source` is stored verbatim and must come back as the array it went in
/// as — the fix touches the inverted index, never the stored document.
#[tokio::test]
async fn source_round_trips_unchanged() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mvk_source").await;

    for state in ["PRE-flush", "POST-flush"] {
        if state == "POST-flush" {
            idx.flush().await.unwrap();
        }
        let res = idx
            .search(&req(json!({"term": {"tags": "blue"}})))
            .await
            .unwrap();
        assert_eq!(res.hits.len(), 1, "{state}: expected exactly doc 1");
        assert_eq!(
            res.hits[0].source["tags"],
            json!(["red", "blue"]),
            "{state}: _source must keep the original array"
        );
    }
}

/// The MERGE path must index arrays the same way the flush path does.
///
/// It used to carry its own copy of the extraction walk
/// (`index::extract_field_text`, joining with `" "`), so a merged segment
/// reproduced the bug even once a freshly flushed one had stopped having it —
/// a defect that only appears after a second flush plus a merge, which no
/// flush-only test can see. `extract_fts_fields_excluding` now delegates to
/// `memtable::extract_field_values_excluding`, the flush path's own walker.
#[tokio::test]
async fn merged_segments_keep_every_array_element() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = seed(&engine, "mvk_merge").await;

    // Segment 1: docs 1 and 2.
    idx.flush().await.unwrap();
    // Segment 2: a third doc, so the merge has something to merge.
    idx.index_document(
        Some("3".into()),
        json!({"body": "hello", "tags": ["green", "blue"], "notes": "alpha bravo"}),
    )
    .await
    .unwrap();
    idx.flush().await.unwrap();

    let merged = idx.force_merge(1).await.unwrap();
    assert!(merged >= 1, "force_merge should have merged something");

    assert_eq!(
        ids(&idx, &json!({"term": {"tags": "blue"}})).await,
        expect(&["1", "3"]),
        "MERGED: a non-first array element must still be its own term"
    );
    assert_eq!(
        ids(&idx, &json!({"term": {"tags": "red"}})).await,
        expect(&["1", "2"]),
        "MERGED: the first array element and the scalar control"
    );
    assert_eq!(
        ids(&idx, &json!({"term": {"tags": "red blue"}})).await,
        expect(&[]),
        "MERGED: the joined string must not survive the merge as a term"
    );
    assert_eq!(
        ids(&idx, &json!({"match_phrase": {"notes": "bravo charlie"}})).await,
        expect(&[]),
        "MERGED: the position gap between array elements must survive the merge"
    );
}

//! Issue #681 (bool half): `_name` on a `bool` clause (a top-level sibling of
//! `must`/`should`/…) was silently dropped by `parse_bool` (it never read
//! `_name` or wrapped the node), so a named bool never surfaced in
//! `matched_queries`. The fix reads `_name` and wraps via `maybe_named`.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn matched(engine: &Engine, q: serde_json::Value) -> Vec<Vec<String>> {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 10 })).expect("parse_request");
    idx.search(&req)
        .await
        .expect("search")
        .hits
        .iter()
        .map(|h| h.matched_queries.clone())
        .collect()
}

#[tokio::test]
async fn name_on_bool_surfaces_in_matched_queries() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("name", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "name": "Hello" }))
        .await
        .expect("index");

    // A named `bool` that matches (via match_all) must report "b".
    let m = matched(
        &engine,
        json!({ "bool": { "should": [{ "match_all": {} }], "_name": "b" } }),
    )
    .await;
    assert_eq!(m.len(), 1, "the bool matches -> one hit");
    assert!(
        m[0].contains(&"b".to_string()),
        "#681: a named bool must surface its `_name` in matched_queries: {:?}",
        m[0]
    );
}

//! Issue #681: `_name` on the expanded form of a `prefix`/`wildcard` clause
//! (e.g. `{"prefix":{"name":{"value":"Hel","_name":"p"}}}`) was dropped by the
//! parser (`parse_prefix`/`parse_wildcard` never called `maybe_named`), so a
//! named prefix/wildcard clause never surfaced in `matched_queries`. The fix
//! extracts `_name` and wraps the node, mirroring `parse_term`.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn matched(engine: &Engine, q: serde_json::Value) -> Vec<Vec<String>> {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 10 })).expect("parse_request");
    idx.search(&req)
        .await
        .expect("search")
        .hits
        .iter()
        .map(|h| h.matched_queries.clone())
        .collect()
}

#[tokio::test]
async fn name_on_prefix_and_wildcard_surfaces_in_matched_queries() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("name", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "name": "Hello" }))
        .await
        .expect("index");

    // A named `prefix` that matches ("Hel" prefixes "Hello") must report "p".
    let pre = matched(
        &engine,
        json!({ "prefix": { "name": { "value": "Hel", "_name": "p" } } }),
    )
    .await;
    assert_eq!(pre.len(), 1, "the prefix matches -> one hit");
    assert!(
        pre[0].contains(&"p".to_string()),
        "#681: a named prefix must surface its `_name` in matched_queries: {:?}",
        pre[0]
    );

    // A named `wildcard` that matches ("Hel*") must report "w".
    let wc = matched(
        &engine,
        json!({ "wildcard": { "name": { "value": "Hel*", "_name": "w" } } }),
    )
    .await;
    assert_eq!(wc.len(), 1, "the wildcard matches -> one hit");
    assert!(
        wc[0].contains(&"w".to_string()),
        "#681: a named wildcard must surface its `_name` in matched_queries: {:?}",
        wc[0]
    );
}

//! #836: a (lexical) `nested` query must roll the matching children's scores
//! into the parent score per `score_mode` (avg/max/sum/min), not score every
//! matching parent a flat 1.0. The child that matches "expert" with a higher
//! term frequency scores higher, so its parent must rank first. Asserted on the
//! memtable AND after flush (the issue reports the flat score on both paths).

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn top_ids_and_scores(engine: &Engine, q: serde_json::Value) -> Vec<(String, f32)> {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({
        "query": q,
        "sort": [{ "_score": "desc" }],
        "size": 10
    }))
    .expect("parse_request");
    idx.search(&req)
        .await
        .expect("search")
        .hits
        .into_iter()
        .map(|h| (h.id, h.score))
        .collect()
}

#[tokio::test]
async fn nested_query_ranks_parents_by_child_score() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    // Schemaless: `users` is a nested array of objects with a `bio` text field.
    engine
        .create_index("docs", xerj_common::types::Schema::empty())
        .expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(
        Some("p1".to_string()),
        json!({ "users": [{ "bio": "expert" }] }),
    )
    .await
    .expect("index p1");
    idx.index_document(
        Some("p2".to_string()),
        json!({ "users": [{ "bio": "expert expert expert" }] }),
    )
    .await
    .expect("index p2");

    let q = json!({ "nested": {
        "path": "users",
        "query": { "match": { "users.bio": "expert" } },
        "score_mode": "max"
    }});

    // Both parents match; p2's child matches "expert" with a higher TF, so under
    // score_mode:max p2 must outrank p1 — on the memtable and after flush.
    let pre = top_ids_and_scores(&engine, q.clone()).await;
    idx.refresh().await.expect("refresh");
    let post = top_ids_and_scores(&engine, q.clone()).await;

    for (label, hits) in [("memtable", &pre), ("segment", &post)] {
        assert_eq!(hits.len(), 2, "{label}: both parents match");
        assert_eq!(hits[0].0, "p2", "{label}: p2 (higher child TF) ranks first");
        assert_eq!(hits[1].0, "p1", "{label}: p1 second");
        assert!(
            hits[0].1 > hits[1].1,
            "{label}: p2 score {} must exceed p1 score {} (not a flat 1.0)",
            hits[0].1,
            hits[1].1
        );
    }
}

//! RC4 blocker 13 regression: data-dir exclusivity via `<data_dir>/node.lock`.
//!
//! Before the fix a second xerj process pointed at a live data dir booted
//! happily: it re-opened every index, replayed the WAL, and flushed
//! duplicate segments into the directory the first process was still
//! serving (live-reproduced: duplicate `min_seq=1/max_seq=1` segments from
//! the second boot). The engine now takes an exclusive OS-level lock on
//! `<data_dir>/node.lock` before any index open / WAL replay, and fails
//! fast with the holder's pid.

use std::sync::{Mutex, OnceLock};

use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_engine::Engine;

fn config_for(dir: &TempDir) -> Config {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config
}

/// `Engine::new` installs process-wide governor and pool state, and the
/// stale-lock test rebuilds the tracing interest cache. The two tests in
/// this binary have to take turns.
fn serialize_tests() -> std::sync::MutexGuard<'static, ()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
        .lock()
        .unwrap_or_else(|poison| poison.into_inner())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn second_engine_on_same_data_dir_fails_fast_with_holder_pid() {
    let _guard = serialize_tests();
    let dir = TempDir::new().unwrap();
    let engine = Engine::new(config_for(&dir)).expect("first engine must boot");

    // Second engine on the SAME live dir must refuse to start…
    let err = match Engine::new(config_for(&dir)) {
        Ok(_) => panic!("second engine on a live data dir must fail fast"),
        Err(e) => e.to_string(),
    };
    // …with a self-explanatory message carrying the holder's pid.
    assert!(
        err.contains("already in use"),
        "unexpected lock error: {err}"
    );
    assert!(
        err.contains(&std::process::id().to_string()),
        "lock error should name the holding pid: {err}"
    );

    // Dropping the holder releases the OS lock; the stale node.lock FILE
    // left behind (as after kill -9) must never block the next boot.
    drop(engine);
    let reopened = reopen_after_drop(&dir);
    assert!(
        reopened.is_ok(),
        "reopen after the holder exits must succeed: {:?} (open node.lock fds: {})",
        reopened.err(),
        node_lock_fds()
    );
}

/// The OS lock is released when the holder's file is closed. Full-workspace
/// CI has still observed `WouldBlock` from this process immediately after
/// `drop` (this branch's run 40152941822, and `main` run 40145228672) and
/// a pass of the same test on run 40148648744. Wait briefly for that close
/// to become visible. A lock that stays held still fails.
fn reopen_after_drop(dir: &TempDir) -> Result<Engine, xerj_engine::EngineError> {
    let mut last = Engine::new(config_for(dir));
    for _ in 0..20 {
        if last.is_ok() {
            return last;
        }
        let still_ours = last
            .as_ref()
            .err()
            .map(|err| err.to_string())
            .is_some_and(|text| text.contains("already in use") && text.contains("node.lock"));
        if !still_ours {
            return last;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
        last = Engine::new(config_for(dir));
    }
    last
}

fn node_lock_fds() -> String {
    let Ok(dir) = std::fs::read_dir("/proc/self/fd") else {
        return "unavailable".to_string();
    };
    let mut hits = Vec::new();
    for entry in dir.flatten() {
        if let Ok(target) = std::fs::read_link(entry.path()) {
            let text = target.to_string_lossy();
            if text.contains("node.lock") {
                hits.push(text.into_owned());
            }
        }
    }
    if hits.is_empty() {
        "none".to_string()
    } else {
        hits.join(", ")
    }
}

/// A `node.lock` left by a process that has exited must not block the next
/// boot, and the reclaim is logged. This is the file `kill -9` leaves once
/// the kernel has dropped `flock`, and the file a crashed Windows process
/// leaves behind when `LockFileEx` does not.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn stale_node_lock_from_a_dead_pid_is_reclaimed_on_start() {
    let _guard = serialize_tests();
    let dir = TempDir::new().unwrap();
    let dead = reaped_pid();
    std::fs::write(dir.path().join("node.lock"), format!("{dead}\n")).unwrap();

    let logs = capture_warns(|| {
        let engine = Engine::new(config_for(&dir)).expect("dead pid lock file must be reclaimed");
        let stamped = std::fs::read_to_string(dir.path().join("node.lock")).unwrap();
        assert_eq!(
            stamped.trim().parse::<u32>().ok(),
            Some(std::process::id()),
            "the live process stamps node.lock, got {stamped:?}"
        );

        // The reclaimed lock is the real exclusive lock: a second start blocks.
        let err = match Engine::new(config_for(&dir)) {
            Ok(_) => panic!("second engine on the reclaimed data dir must fail fast"),
            Err(e) => e.to_string(),
        };
        assert!(err.contains("already in use"), "{err}");
        assert!(
            err.contains(&std::process::id().to_string()),
            "lock error should name the holding pid: {err}"
        );
        drop(engine);
    });
    assert!(
        logs.contains(&format!(
            "reclaimed stale node.lock left by pid {dead} (process is not running)"
        )),
        "reclaim must be logged: {logs}"
    );
}

fn reaped_pid() -> u32 {
    for _ in 0..20 {
        let mut cmd = if cfg!(windows) {
            let mut cmd = std::process::Command::new("cmd");
            cmd.args(["/C", "exit", "0"]);
            cmd
        } else {
            std::process::Command::new("true")
        };
        let mut child = cmd.spawn().expect("spawn a process that exits");
        let pid = child.id();
        let status = child.wait().unwrap();
        assert!(status.success());
        // The child has been waited on, so it is not a zombie. `ps` exiting
        // non-zero is "no such process". A recycled pid is still running;
        // try another one. `ps` missing (Windows) skips the probe.
        if !pid_still_listed(pid) {
            return pid;
        }
    }
    panic!("could not observe a reaped pid");
}

fn pid_still_listed(pid: u32) -> bool {
    std::process::Command::new("ps")
        .args(["-p", &pid.to_string()])
        .output()
        .map(|out| out.status.success())
        .unwrap_or(false)
}

#[derive(Clone)]
struct LogBuffer(std::sync::Arc<std::sync::Mutex<Vec<u8>>>);

struct LogWriter(std::sync::Arc<std::sync::Mutex<Vec<u8>>>);

impl std::io::Write for LogWriter {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        self.0.lock().unwrap().extend_from_slice(bytes);
        Ok(bytes.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for LogBuffer {
    type Writer = LogWriter;

    fn make_writer(&'a self) -> Self::Writer {
        LogWriter(self.0.clone())
    }
}

fn capture_warns(body: impl FnOnce()) -> String {
    let buffer = LogBuffer(std::sync::Arc::new(std::sync::Mutex::new(Vec::new())));
    let subscriber = tracing_subscriber::fmt()
        .without_time()
        .with_ansi(false)
        .with_target(false)
        .with_max_level(tracing::Level::WARN)
        .with_writer(buffer.clone())
        .finish();
    let _guard = tracing::subscriber::set_default(subscriber);
    tracing::callsite::rebuild_interest_cache();
    body();
    let bytes = buffer.0.lock().unwrap().clone();
    String::from_utf8(bytes).unwrap()
}

//! Issue #413 (an #423 symptom): a root-level object-mapped field is indexed on
//! flush as ONE whole, untokenised, case-preserved keyword-style blob (the pruned
//! `serde_json::to_string` emitted by `collect_text_fields`). The memtable
//! `doc_matches_query` path declined `Value::Object`, so `prefix`/`wildcard` on
//! such a field answered 0 before a flush and 1 after — a flush-divergence. The
//! fix mirrors the blob in the memtable Prefix/Wildcard arms (raw, case-
//! sensitive, root-level only), so every answer is flush-invariant.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn hits(engine: &Engine, q: serde_json::Value) -> u64 {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 0 })).expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

#[tokio::test]
async fn object_field_prefix_wildcard_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("meta", FieldType::Object));
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Object));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(
        Some("d0".to_string()),
        json!({ "meta": {"owner":"Alpha"}, "tags": [{"owner":"Alpha"},{"owner":"Beta"}] }),
    )
    .await
    .expect("index");

    // (query, expected hit count) — the segment stores the blob
    // `{"owner":"Alpha"}` whole, untokenised, and case-preserved. For the
    // `tags` ARRAY of objects the write path joins the elements into one blob
    // (`{"owner":"Alpha"} {"owner":"Beta"}`); the memtable arms mirror the same
    // joined string, so both are flush-invariant.
    let cases = vec![
        (json!({"prefix":{"meta":"{"}}), 1u64), // blob starts with `{`
        (json!({"prefix":{"meta":"{\"owner"}}), 1), // deeper raw prefix
        (json!({"prefix":{"meta":"owner"}}), 0), // not tokenised: no `owner` token
        (json!({"prefix":{"meta":"alpha"}}), 0),
        (json!({"wildcard":{"meta":"*Alpha*"}}), 1), // contains `Alpha`
        (json!({"wildcard":{"meta":"*alpha*"}}), 0), // case-preserved: lower-case misses
        (json!({"wildcard":{"meta":"*owner*"}}), 1),
        // array-of-objects (`tags`):
        (json!({"prefix":{"tags":"{"}}), 1),
        (json!({"wildcard":{"tags":"*Alpha*"}}), 1),
        (json!({"wildcard":{"tags":"*Beta*"}}), 1),
        (json!({"wildcard":{"tags":"*alpha*"}}), 0), // case-preserved
    ];

    // Buffered (memtable) answers, then flush and re-query — each pair must agree.
    let mut pre = Vec::new();
    for (q, _) in &cases {
        pre.push(hits(&engine, q.clone()).await);
    }
    idx.refresh().await.expect("refresh");
    for ((q, expected), pre_hit) in cases.iter().zip(pre.iter()) {
        let post = hits(&engine, q.clone()).await;
        assert_eq!(
            *pre_hit, post,
            "#413: `{q}` must be flush-invariant (pre={pre_hit}, post={post})"
        );
        assert_eq!(
            post, *expected,
            "#413: `{q}` expected {expected}, got {post}"
        );
    }
}

//! #965 — engine-level end-to-end for the object-storage backend.
//!
//! The storage crate's own tests pin the bundle/catalog mechanics
//! (`xerj-storage` object-store suite). What only the ENGINE can prove is the
//! composition: `storage_mode_from_config` turning `storage.backend = "s3"`
//! into a per-index object namespace, the flush path uploading through the
//! real Index wiring, the per-index meta objects (settings/schema/mapping)
//! riding the same bucket, and a FRESH node — an empty data directory whose
//! only local knowledge is which indices exist — booting from the bucket and
//! serving full-text search over hydrated families.
//!
//! The object store is the in-process filesystem simulation
//! (`XERJ_TEST_OBJECT_STORE_DIR`), never a network endpoint: local testing
//! only, no credentials, no cloud.
//!
//! ```bash
//! cargo test -p xerj-engine --test object_storage_e2e -- --nocapture
//! ```

use serde_json::json;
use std::path::{Path, PathBuf};
use tempfile::TempDir;
use xerj_common::config::{Config, StorageBackendType};
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::parse_request;

/// Point the object-store simulation at `root` for the lifetime of the guard.
///
/// `Drop` (not a trailing `remove_var`) clears it so a panicked assertion
/// cannot leak the override into anything that runs after this test in the
/// same process. The variable is read ONLY in the `backend = "s3"` arm of
/// `storage_mode_from_config`, so local-mode tests never see it either way.
struct ObjectStoreDir;

impl ObjectStoreDir {
    fn set(root: &Path) -> Self {
        std::env::set_var("XERJ_TEST_OBJECT_STORE_DIR", root);
        Self
    }
}

impl Drop for ObjectStoreDir {
    fn drop(&mut self) {
        std::env::remove_var("XERJ_TEST_OBJECT_STORE_DIR");
    }
}

/// An engine in object-storage mode over `data_dir`, sharing whatever bucket
/// `XERJ_TEST_OBJECT_STORE_DIR` names. Local defaults otherwise.
fn object_engine(data_dir: &Path) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = data_dir.to_str().unwrap().to_string();
    config.storage.backend = StorageBackendType::S3;
    config.storage.s3_bucket = "e2e-bucket".to_string();
    Engine::new(config).expect("engine::new in object-store mode")
}

/// Every file under `root`, recursively, as `/`-separated paths relative to it.
fn bucket_objects(root: &Path) -> Vec<String> {
    fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
        for entry in std::fs::read_dir(dir).unwrap().flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, out);
            } else {
                out.push(path);
            }
        }
    }
    let mut files = Vec::new();
    walk(root, &mut files);
    files
        .iter()
        .map(|p| {
            p.strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/")
        })
        .collect()
}

// Multi-threaded runtime: the object-store bridges use
// `tokio::task::block_in_place`, which panics on the current-thread flavour
// `#[tokio::test]` defaults to.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn an_s3_index_round_trips_to_a_fresh_node() {
    let bucket = TempDir::new().unwrap();
    let _object_store = ObjectStoreDir::set(bucket.path());

    // ── Node A: create the index, write, flush. ────────────────────────────
    // The flush is the moment the segment becomes a bucket object, so this
    // block owns the node until then; dropping the engine simulates the
    // process dying right after (no clean shutdown, no lingering tasks).
    let node_a = TempDir::new().unwrap();
    {
        let engine = object_engine(node_a.path());
        engine.create_index("objs", Schema::empty()).unwrap();
        let idx = engine.get_index("objs").unwrap();
        for i in 0..3u32 {
            idx.index_document(
                Some(format!("doc-{i}")),
                json!({
                    "seq": i,
                    "body": format!("zebrula payload number {i} of the object-storage round trip"),
                }),
            )
            .await
            .unwrap();
        }
        engine.flush_index("objs").await.unwrap();
    }

    // The bucket — and nothing but the bucket — now describes the index:
    // one immutable bundle per segment (two here: the very first document
    // triggers a dynamic-mapping flush before the rest accumulate — engine
    // behaviour in local mode too, not an object-store artefact), the
    // snapshot catalogue, and the per-index meta objects that make a fresh
    // node recreate the SAME index rather than a dynamically re-mapped
    // lookalike.
    let objects = bucket_objects(bucket.path());
    assert!(
        objects.iter().all(|o| o.starts_with("xerj/indices/objs/")),
        "the per-index namespace must be <s3_prefix>/indices/<name>/, got {objects:?}"
    );
    let catalog_path = objects
        .iter()
        .find(|o| o.ends_with("/snapshot.json"))
        .expect("the flush must publish the snapshot catalogue");
    let catalog: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(bucket.path().join(catalog_path)).unwrap())
            .unwrap();
    let segment_ids: Vec<&str> = catalog["segments"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| s["id"].as_str().unwrap())
        .collect();
    assert!(
        !segment_ids.is_empty(),
        "the catalogue must name the flushed segments: {catalog}"
    );
    for id in &segment_ids {
        assert!(
            objects
                .iter()
                .any(|o| o == &format!("xerj/indices/objs/segments/{id}.bundle")),
            "every catalogued segment must be exactly one bundle object ({id}), got {objects:?}"
        );
    }
    // settings.json is only persisted when the create carried settings, so
    // what this index must publish is the schema and the analysis binding.
    for expected in [
        "xerj/indices/objs/meta/schema.json",
        "xerj/indices/objs/meta/analysis-binding.json",
    ] {
        assert!(
            objects.iter().any(|o| o == expected),
            "bucket must hold {expected} after the flush, got {objects:?}"
        );
    }

    // ── Node B: a fresh process with an empty data directory. ──────────────
    // Index EXISTENCE stays local in v1 (engine boot scans data_dir for
    // directories with a WAL subdir — a deployment manifest, effectively);
    // everything else — settings, schema, mapping, every segment family —
    // comes from the bucket on open.
    let node_b = TempDir::new().unwrap();
    std::fs::create_dir_all(node_b.path().join("objs").join("wal")).unwrap();
    let engine_b = object_engine(node_b.path());
    let idx = engine_b.get_index("objs").unwrap();

    // Full-text search over a hydrated family: the bundle unpacked into the
    // local segments dir, postings and all.
    let hits = idx
        .search(
            &parse_request(&json!({
                "query": { "match": { "body": "zebrula" } }
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        hits.total.value, 3,
        "the fresh node must serve the flushed documents, got {}",
        hits.total.value
    );

    let hydrated = file_count(&node_b.path().join("objs").join("segments"));
    assert!(
        hydrated >= 2,
        "the family must have been hydrated locally (postings + stored at \
         minimum), found {hydrated} files"
    );

    // ── Node B becomes the writer: the catalog advances, coherently. ───────
    idx.index_document(
        Some("doc-3".into()),
        json!({"seq": 3, "body": "zebrula payload number 3 written by the fresh node"}),
    )
    .await
    .unwrap();
    engine_b.flush_index("objs").await.unwrap();

    let after = idx
        .search(
            &parse_request(&json!({
                "query": { "match": { "body": "zebrula" } },
                "size": 0
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(after.total.value, 4, "post-flush catalog must count 4 docs");

    let objects_after = bucket_objects(bucket.path());
    let bundles_after: Vec<&String> = objects_after
        .iter()
        .filter(|o| o.starts_with("xerj/indices/objs/segments/") && o.ends_with(".bundle"))
        .collect();
    assert_eq!(
        bundles_after.len(),
        segment_ids.len() + 1,
        "node B's flush must add exactly one bundle on top of the ones it \
         booted from, got {objects_after:?}"
    );
    assert!(
        objects_after
            .iter()
            .any(|o| o.ends_with("indices/objs/snapshot.json")),
        "the catalogue object must still be there after node B published"
    );
}

/// Files in `dir` (0 when the dir does not exist yet).
fn file_count(dir: &Path) -> usize {
    std::fs::read_dir(dir)
        .map(|d| d.flatten().count())
        .unwrap_or(0)
}

//! Issue #677 (an #423 sibling of #413): `term` on an object **sub-field**
//! changes its answer at flush. Field `meta` mapped `object`, document
//! `{"meta":{"owner":"Alpha"}}`:
//!
//! | query | before flush | after flush |
//! |---|---|---|
//! | `{"term":{"meta.owner":"Alpha"}}` | 0 | 1 |
//!
//! The segment indexes `meta.owner` as its own term (via `collect_text_fields`
//! recursion), so post-flush answers 1; the memtable's `term` path returns 0
//! for the dotted sub-field. ES answers 1 consistently. Ignored until the fix
//! makes the memtable term path resolve object sub-fields; the fix un-ignores it.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn hits(engine: &Engine, q: serde_json::Value) -> u64 {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": q, "size": 0 })).expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

#[tokio::test]
async fn term_on_object_subfield_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("meta", FieldType::Object));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "meta": {"owner":"Alpha"} }))
        .await
        .expect("index");

    let q = json!({"term":{"meta.owner":"Alpha"}});
    let pre = hits(&engine, q.clone()).await;
    idx.refresh().await.expect("refresh");
    let post = hits(&engine, q.clone()).await;

    assert_eq!(
        pre, post,
        "#677: term on an object sub-field must be flush-invariant"
    );
    assert_eq!(
        post, 1,
        "#677: meta.owner is an indexed keyword sub-field (ES matches)"
    );
}

//! Issue #122: Painless had no per-evaluation CPU budget.
//!
//! Every pre-existing limit bounds a *structural* property of a script — how
//! deep it nests (`MAX_PARSE_DEPTH`, `MAX_EVAL_DEPTH`), how many closure calls
//! it makes (`MAX_CALL_DEPTH`, `MAX_CALL_COUNT`), how many bytes of source it
//! is (`MAX_SCRIPT_LEN`). None of them bounds *work*, so a script can be flat,
//! shallow, closure-free and comfortably under 64 KiB while costing over a
//! second of CPU on a single document. The doc-scan cooperative timeout poll
//! cannot help: it only decides how often a document *boundary* is checked.
//!
//! The measurement entry points below are `#[ignore]`d — they are stopwatches,
//! not assertions, and are the numbers quoted in the fix's commit message. The
//! non-ignored tests are the regression: they fail on the pre-fix tree by
//! running to completion (or by taking a wall-clock eternity) instead of being
//! refused.

use serde_json::{json, Value};
use xerj_engine::painless::{eval_painless, is_resource_limit_error, PainlessCtx};

/// Bytes of string literal the adversarial script starts from.
const CHUNK: usize = 1024;

/// A flat, closure-free, legal-size script whose cost is quadratic in its own
/// statement count: statement *i* concatenates a 1 KiB chunk onto an
/// accumulator that is already `i` KiB long, so `n` statements copy
/// `~n²/2 KiB`. Nothing about it is deep, recursive or oversized — it is the
/// counter-example to every structural limit at once.
fn quadratic_concat_script(statements: usize) -> String {
    let mut src = String::with_capacity(CHUNK + statements * 10 + 64);
    src.push_str("def c = \"");
    src.push_str(&"x".repeat(CHUNK));
    src.push_str("\";\ndef s = c;\n");
    for _ in 0..statements {
        src.push_str("s = s + c;\n");
    }
    src.push_str("return s.length();");
    src
}

/// The benign comparison point: a legal script of comparable *size* that does
/// only cheap arithmetic, so any per-op overhead the budget adds shows up here
/// undiluted.
fn benign_arithmetic_script(terms: usize) -> String {
    let mut src = String::with_capacity(terms * 24 + 32);
    src.push_str("double t = 0;\n");
    for i in 0..terms {
        src.push_str(&format!("t = t + {}.5;\n", i % 97));
    }
    src.push_str("return t;");
    src
}

fn doc() -> Value {
    json!({ "rank": 7, "tags": ["a", "b"] })
}

fn params() -> Value {
    json!({ "factor": 2.0 })
}

/// One evaluation of `src`, returning the elapsed wall time and the outcome.
fn timed_eval(src: &str) -> (std::time::Duration, Result<(), String>) {
    let doc = doc();
    let params = params();
    let ctx = PainlessCtx::new(&doc, &params, 1.0);
    let start = std::time::Instant::now();
    let out = eval_painless(src, &ctx);
    let elapsed = start.elapsed();
    (elapsed, out.map(|_| ()))
}

/// Stopwatch (issue evidence #1 and #2): how long ONE document's evaluation of
/// the adversarial script takes. On the pre-fix tree this runs to completion
/// and prints the unbounded cost; with the budget in place it is refused.
///
/// `cargo test --release -p xerj-engine --test painless_cpu_budget -- \
///  --ignored --nocapture measure_adversarial`
#[test]
#[ignore = "stopwatch, not an assertion"]
fn measure_adversarial_cost_per_document() {
    // 5,700 statements is the largest this shape fits under the 64 KiB
    // `MAX_SCRIPT_LEN`, i.e. the worst case a caller is allowed to submit.
    for statements in [1000, 2000, 4000, 5700] {
        let src = quadratic_concat_script(statements);
        let (elapsed, outcome) = timed_eval(&src);
        println!(
            "adversarial statements={statements} source={} bytes ({:.1} KiB) \
             elapsed={:?} outcome={}",
            src.len(),
            src.len() as f64 / 1024.0,
            elapsed,
            match &outcome {
                Ok(()) => "COMPLETED (unbounded)".to_string(),
                Err(e) => format!("refused: {e}"),
            }
        );
    }
}

/// Stopwatch (issue evidence #3): per-evaluation cost of an ordinary small
/// script, reported as ns per evaluation. Run pinned:
///
/// `taskset -c 3 cargo test --release -p xerj-engine --test painless_cpu_budget \
///  -- --ignored --nocapture measure_ordinary`
#[test]
#[ignore = "stopwatch, not an assertion"]
fn measure_ordinary_script_ns_per_eval() {
    let doc = doc();
    let params = params();
    for (label, src) in [
        (
            "tiny",
            "doc['rank'].value * params.factor + _score".to_string(),
        ),
        ("small-arith", benign_arithmetic_script(16)),
        ("64KiB-benign", benign_arithmetic_script(4300)),
    ] {
        // Warm-up.
        for _ in 0..64 {
            let ctx = PainlessCtx::new(&doc, &params, 1.0);
            let _ = eval_painless(&src, &ctx);
        }
        // Report the MINIMUM over many short trials, not the mean over one
        // long run. This host is shared, and a mean absorbs every scheduling
        // interruption that lands in the run — the before/after difference
        // being measured here is a few ns per work unit and disappears under
        // that. The minimum is the trial that ran least interrupted.
        let iterations = if src.len() > 4096 { 20 } else { 2_000 };
        let trials = 40;
        let mut best = f64::MAX;
        for _ in 0..trials {
            let start = std::time::Instant::now();
            for _ in 0..iterations {
                let ctx = PainlessCtx::new(&doc, &params, 1.0);
                let out = eval_painless(&src, &ctx);
                assert!(out.is_ok(), "{label} must evaluate: {out:?}");
            }
            let per_eval = start.elapsed().as_nanos() as f64 / iterations as f64;
            best = best.min(per_eval);
        }
        println!(
            "ordinary {label:<13} source={:>6} bytes best-of-{trials} \
             {best:>10.1} ns/eval",
            src.len(),
        );
    }
}

/// A flat 44.0 KiB script that trips no structural limit must be refused as a
/// resource-limit failure instead of being run to completion.
///
/// Its *result size* is separately capped at 1 MiB by the
/// `MAX_PAINLESS_STRING_LEN` limit that arrived with #87, so on this base it no
/// longer runs for seconds — but the work budget is what prices the copying,
/// and it is the budget that must be named in the refusal.
#[test]
fn quadratic_string_growth_is_refused_as_a_resource_limit() {
    let src = quadratic_concat_script(4000);
    assert!(
        src.len() < 64 * 1024,
        "the repro must stay under the 64 KiB source limit, got {}",
        src.len()
    );
    let (elapsed, outcome) = timed_eval(&src);
    let err = outcome.expect_err(
        "a flat, closure-free, legal-size script ran to completion with no \
         work budget — this is issue #122",
    );
    assert!(
        is_resource_limit_error(&err),
        "the work budget must classify as a resource limit so the API layer \
         answers 400 instead of degrading to a wrong score, got {err:?}"
    );
    assert!(
        err.contains("work budget"),
        "the budget must price the copying before the 1 MiB string-size cap \
         notices the result, got {err:?}"
    );
    assert!(
        elapsed < std::time::Duration::from_secs(1),
        "the budget must abandon the evaluation part-way through ONE document, \
         took {elapsed:?}"
    );
}

/// The same shape reached through repeated whole-document clones rather than
/// string growth: `doc['x'].value` copies the entire source document on every
/// access, so a flat script with thousands of accesses is linear in
/// `statements × document size` with no structural limit in the way.
#[test]
fn repeated_whole_document_clones_are_refused_as_a_resource_limit() {
    let big: Vec<Value> = (0..20_000).map(|i| json!(format!("value-{i}"))).collect();
    let doc = json!({ "rank": 7, "blob": big });
    let params = params();
    let mut src = String::from("double t = 0;\n");
    for _ in 0..2000 {
        src.push_str("t = t + doc['rank'].value;\n");
    }
    src.push_str("return t;");
    assert!(src.len() < 64 * 1024, "repro must stay legal-size");

    let ctx = PainlessCtx::new(&doc, &params, 1.0);
    let err = eval_painless(&src, &ctx)
        .expect_err("2000 whole-document clones ran unbudgeted — issue #122");
    assert!(
        is_resource_limit_error(&err),
        "expected a resource-limit classification, got {err:?}"
    );
}

// ── The `params` root (issue #122, round 2) ──────────────────────────────────
//
// `eval_access_chain` resolves `params.x`, `params['x']` and `params['_source']`
// itself, without a preceding value, in a fast path at chain position 0. The
// first revision of this budget ended each of those fast paths in `continue`,
// jumping past the charge at the bottom of the loop — so every one of them ran
// `PainlessValue::from_json` over a caller-supplied subtree (or, for
// `_source`, over a clone of the whole document) for a flat two work units.
// The budget had a hole of exactly the shape it was built to close.

/// `params` whose single member `blob` is an array of `nodes` short strings.
/// Short on purpose: under 64 bytes each contributes nothing beyond its one
/// node to the work count, so the weight here is honestly `nodes`, not a
/// string-length artefact.
fn params_with_blob(nodes: usize) -> Value {
    let blob: Vec<Value> = (0..nodes).map(|i| json!(format!("v{i}"))).collect();
    json!({ "blob": blob })
}

/// A flat, closure-free script of bare `params.blob;` statements. It nests
/// nothing, calls nothing, and at 3,000 statements is 36 KB — inside every
/// structural limit the interpreter has.
fn bare_params_read_script(statements: usize) -> String {
    let mut src = String::with_capacity(statements * 13 + 16);
    for _ in 0..statements {
        src.push_str("params.blob;\n");
    }
    src.push_str("return 1;");
    src
}

/// Stopwatch: cost of one document's evaluation of the bare-`params` script.
/// On the pre-fix tree this completes, and the two `nodes` rows show the cost
/// scaling linearly with the size of the caller's own `params`.
///
/// `taskset -c 3 cargo test --release -p xerj-engine --test painless_cpu_budget \
///  -- --ignored --nocapture measure_bare_params`
#[test]
#[ignore = "stopwatch, not an assertion"]
fn measure_bare_params_read_cost() {
    for nodes in [50_000, 200_000] {
        let params = params_with_blob(nodes);
        let doc = doc();
        let src = bare_params_read_script(3_000);
        let ctx = PainlessCtx::new(&doc, &params, 1.0);
        let start = std::time::Instant::now();
        let outcome = eval_painless(&src, &ctx);
        let elapsed = start.elapsed();
        println!(
            "bare-params nodes={nodes} source={} bytes elapsed={:?} units={} outcome={}",
            src.len(),
            elapsed,
            ctx.work_units(),
            match &outcome {
                Ok(_) => "COMPLETED (unbounded)".to_string(),
                Err(e) => format!("refused: {e}"),
            }
        );
    }
}

/// THE round-2 regression. 3,000 bare `params.blob;` statements against a
/// 200,000-node `params` — measured at 12.1 s per document with the fast path
/// uncharged — must be refused.
///
/// Reverting only `painless.rs` and keeping this file makes it fail by
/// completing the evaluation, which is the defect.
#[test]
fn bare_params_reads_are_charged_for_what_they_materialise() {
    let params = params_with_blob(200_000);
    let doc = doc();
    let src = bare_params_read_script(3_000);
    assert!(src.len() < 64 * 1024, "the repro must stay legal-size");

    let ctx = PainlessCtx::new(&doc, &params, 1.0);
    let start = std::time::Instant::now();
    let err = eval_painless(&src, &ctx).expect_err(
        "3,000 reads of a 200,000-node `params` member ran to completion — the \
         position-0 fast path is materialising an unbounded value for two work \
         units",
    );
    let elapsed = start.elapsed();
    assert!(
        is_resource_limit_error(&err),
        "expected a resource-limit classification, got {err:?}"
    );
    // Deterministic half: the reads must have been PRICED. Uncharged, this
    // whole script costs 2,048 work units.
    assert!(
        ctx.work_units() > 1_000_000,
        "3,000 reads of a 200,000-node value were charged {} work units",
        ctx.work_units()
    );
    assert!(
        elapsed < std::time::Duration::from_secs(1),
        "the budget must abandon this part-way through ONE document, took {elapsed:?}"
    );
}

/// The `params['x']` spelling reaches a different fast-path arm than
/// `params.x`, and both used to `continue` past the charge.
///
/// The assertion is on the WORK COUNT, not on wall time. Left uncharged these
/// reads are still eventually caught by the wall-clock half of the budget —
/// after 15 s — so a test that only asserts "some resource limit tripped"
/// passes on the broken tree. What has to be true is that the materialisation
/// was *priced*: on the pre-fix tree this whole script is charged 2,048 units,
/// which is the hole.
#[test]
fn subscripted_params_reads_are_charged_too() {
