// Benchmark 5 — Concurrent Search
// ═════════════════════════════════════════════════════════════════════════════

/// Index 10 000 documents, then fire 32 concurrent tasks each running 100 queries.
///
/// Measures aggregate queries/sec and latency distribution under contention,
/// which exercises the `RwLock` hot paths in `Index::search`.
#[tokio::test]
#[ignore]
async fn perf_concurrent_search() {
    const INDEX_N: usize = 10_000;
    const TASKS: usize = 32;
    const QUERIES_PER_TASK: usize = 100;

    print_header("Concurrent Search (10 K docs, 32 tasks × 100 queries)");

    let (engine, _dir) = bench_engine();
    engine.create_index("conc_bench", Schema::empty()).unwrap();
    let idx = engine.get_index("conc_bench").unwrap();

    // Index phase (sequential for reproducibility)
    let index_start = Instant::now();
    for i in 0..INDEX_N {
        idx.index_document(Some(format!("d{i}")), make_doc(i))
            .await
            .unwrap();
    }
    print_kv("Index phase:", &format!("{:.2?}", index_start.elapsed()));

    let idx = std::sync::Arc::new(idx);
    let terms = std::sync::Arc::new([
        "technology",
        "science",
        "politics",
        "sports",
        "arts",
        "alpha",
        "beta",
        "gamma",
        "delta",
        "epsilon",
    ]);

    // Spawn concurrent tasks
    let start = Instant::now();
    let mut handles = Vec::with_capacity(TASKS);

    for task_id in 0..TASKS {
        let idx_clone = std::sync::Arc::clone(&idx);
        let terms_clone = std::sync::Arc::clone(&terms);

        handles.push(tokio::spawn(async move {
            let mut task_latencies: Vec<Duration> = Vec::with_capacity(QUERIES_PER_TASK);
            for q in 0..QUERIES_PER_TASK {
                let term = terms_clone[(task_id * QUERIES_PER_TASK + q) % terms_clone.len()];
                let req = parse_request(&json!({
                    "query": { "match": { "body": term } },
                    "size": 10
                }))
                .unwrap();
                let t0 = Instant::now();
                let _ = idx_clone.search(&req).await.unwrap();
                task_latencies.push(t0.elapsed());
            }
            task_latencies
        }));
    }

    // Collect all latencies
    let mut all_latencies: Vec<Duration> = Vec::with_capacity(TASKS * QUERIES_PER_TASK);
    for handle in handles {
        let task_lats = handle.await.expect("task panicked");
        all_latencies.extend(task_lats);
    }

    let total_time = start.elapsed();
    all_latencies.sort();

    let total_queries = TASKS * QUERIES_PER_TASK;
    let qps = total_queries as f64 / total_time.as_secs_f64();
    let pcts = percentiles(&all_latencies, &[50, 95, 99]);

    print_kv("Concurrent tasks:", &format!("{}", TASKS));
    print_kv("Queries per task:", &format!("{}", QUERIES_PER_TASK));
    print_kv("Total queries:", &format!("{}", total_queries));
    print_kv("Wall-clock time:", &format!("{:.2?}", total_time));
    print_kv("Aggregate throughput:", &format!("{:.0} queries/sec", qps));
    print_kv("p50:", &format!("{:.2?}", pcts[0]));
    print_kv("p95:", &format!("{:.2?}", pcts[1]));
    print_kv("p99:", &format!("{:.2?}", pcts[2]));
    print_kv("min:", &format!("{:.2?}", all_latencies[0]));
    print_kv(
        "max:",
        &format!("{:.2?}", all_latencies[all_latencies.len() - 1]),
    );
    println!();
}

// ═════════════════════════════════════════════════════════════════════════════
// Benchmark 6 — Memory Footprint
// ═════════════════════════════════════════════════════════════════════════════

/// Index 100 000 documents and measure the in-memory footprint (RSS from /proc).
///
/// Reports bytes/doc so you can track regressions in memory efficiency.
///
/// Note: RSS includes all Rust runtime overhead, so the per-doc figure is an
/// upper bound on index-specific memory.  Run in release mode for accuracy.
#[tokio::test]
#[ignore]
async fn perf_memory_footprint() {
    const N: usize = 100_000;

    print_header("Memory Footprint (100 K docs)");

    /// Read the OS page size in bytes.
    fn page_size_bytes() -> u64 {
        // Try reading from /proc/self/smaps or fall back to 4096.
        // On Linux, the page size is typically 4096.
        #[cfg(target_os = "linux")]
        {
            // SAFETY: sysconf(_SC_PAGESIZE) is always safe; it reads a kernel
            // constant and never touches user memory.
            extern "C" {
                fn sysconf(name: i32) -> i64;
            }
            let ps = unsafe { sysconf(30) }; // 30 == _SC_PAGESIZE
            if ps > 0 {
                return ps as u64;
            }
        }
        4096
    }

    /// Read the current process RSS in bytes from `/proc/self/statm`.
    fn rss_bytes() -> Option<u64> {
        let statm = std::fs::read_to_string("/proc/self/statm").ok()?;
        let pages: u64 = statm.split_whitespace().nth(1)?.parse().ok()?;
        Some(pages * page_size_bytes())
    }

    let baseline_rss = rss_bytes().unwrap_or(0);

    let (engine, _dir) = bench_engine();
    engine.create_index("mem_bench", Schema::empty()).unwrap();
    let idx = engine.get_index("mem_bench").unwrap();

    let start = Instant::now();
    for i in 0..N {
        idx.index_document(Some(format!("d{i}")), make_doc(i))
            .await
            .unwrap();
    }
    let elapsed = start.elapsed();

    // Also read Engine's own accounting of memory via IndexStats
    let stats = idx.stats().await;
    let engine_reported_bytes = stats.memtable_size_bytes;

    let rss_after = rss_bytes().unwrap_or(0);
    let rss_delta = rss_after.saturating_sub(baseline_rss);
    let rss_per_doc = rss_delta.checked_div(N as u64).unwrap_or(0);
    let engine_per_doc = engine_reported_bytes.checked_div(N).unwrap_or(0);

    print_kv("Documents indexed:", &format!("{}", N));
    print_kv("Indexing time:", &format!("{:.2?}", elapsed));
    print_kv(
        "RSS before:",
        &format!("{:.1} MB", baseline_rss as f64 / 1_048_576.0),
    );
    print_kv(
        "RSS after:",
        &format!("{:.1} MB", rss_after as f64 / 1_048_576.0),
    );
    print_kv(
        "RSS delta:",
        &format!("{:.1} MB", rss_delta as f64 / 1_048_576.0),
    );
    print_kv("RSS bytes/doc:", &format!("{}", rss_per_doc));
    print_kv(
        "Engine-reported memtable:",
        &format!("{:.1} MB", engine_reported_bytes as f64 / 1_048_576.0),
    );
    print_kv("Engine bytes/doc:", &format!("{}", engine_per_doc));
    println!();
}

// ═════════════════════════════════════════════════════════════════════════════
// Benchmark 7 — Turbo Indexing Throughput
// ═════════════════════════════════════════════════════════════════════════════

/// Index 100 000 documents using turbo mode and compare against the standard
/// single-document API.
///
/// Turbo mode uses parallel tokenisation via Rayon and a single write-lock
/// acquisition per batch, amortising lock overhead across many documents.
///
/// # How to run
///
/// ```bash
/// cargo test -p xerj-engine --test perf_benchmark perf_turbo_indexing_throughput \
///     -- --ignored --nocapture
/// ```
#[tokio::test]
#[ignore]
async fn perf_turbo_indexing_throughput() {
    const N: usize = 100_000;
    const TURBO_BATCH: usize = 1_000;

    print_header("Turbo Indexing Throughput (100 K docs) — standard vs turbo");

    // ── Standard path ─────────────────────────────────────────────────────

    let (engine_std, _dir_std) = bench_engine();
    engine_std
        .create_index("std_bench", Schema::empty())
        .unwrap();
    let idx_std = engine_std.get_index("std_bench").unwrap();

    let std_start = Instant::now();
    for i in 0..N {
        idx_std
            .index_document(Some(format!("doc{i}")), make_doc(i))
            .await
            .unwrap();
    }
    let std_elapsed = std_start.elapsed();
    let std_docs_per_sec = N as f64 / std_elapsed.as_secs_f64();

    // ── Turbo path ────────────────────────────────────────────────────────

    let (engine_turbo, _dir_turbo) = bench_engine();
    engine_turbo
        .create_index("turbo_bench", Schema::empty())
        .unwrap();
    let idx_turbo = engine_turbo.get_index("turbo_bench").unwrap();

    let turbo_start = Instant::now();
    let mut batch: Vec<(String, serde_json::Value)> = Vec::with_capacity(TURBO_BATCH);

    for i in 0..N {
        let source = make_doc(i);
        batch.push((format!("doc{i}"), source));

        if batch.len() >= TURBO_BATCH {
            let b = std::mem::replace(&mut batch, Vec::with_capacity(TURBO_BATCH));
            idx_turbo
                .index_batch_turbo(b, /*parallel=*/ true, /*fast_analyzer=*/ false)
                .await
                .unwrap();
        }
    }

    // Flush the final partial batch.
    if !batch.is_empty() {
        idx_turbo
            .index_batch_turbo(batch, true, false)
            .await
            .unwrap();
    }

    let turbo_elapsed = turbo_start.elapsed();
    let turbo_docs_per_sec = N as f64 / turbo_elapsed.as_secs_f64();
    let speedup = turbo_docs_per_sec / std_docs_per_sec;

    // ── Results ───────────────────────────────────────────────────────────

    print_kv("Documents indexed:", &format!("{}", N));
    print_kv("Batch size (turbo):", &format!("{}", TURBO_BATCH));
    println!();

    print_kv("Standard — total time:", &format!("{:.2?}", std_elapsed));
    print_kv(
        "Standard — throughput:",
        &format!("{:.0} docs/sec", std_docs_per_sec),
    );
    println!();

    print_kv("Turbo    — total time:", &format!("{:.2?}", turbo_elapsed));
    print_kv(
        "Turbo    — throughput:",
        &format!("{:.0} docs/sec", turbo_docs_per_sec),
    );
    println!();

    print_kv("Speedup (turbo / standard):", &format!("{:.2}x", speedup));
    println!();
}

//! Issue #396/#362/#398: a `prefix` query on a `keyword` field must return the
//! same hit set before and after a flush. ES matches `prefix` against the RAW
//! keyword value (case-SENSITIVE), so `prefix:{name:"hel"}` on `"Hello"` is 0.
//! The flushed segment answers 0 (correct); the buffered (memtable) matcher —
//! `doc_matches_query`'s Prefix arm — lowercases both sides (index.rs:35672,
//! "Without schema info at this layer we check both"), so it answers 1. Same
//! document, same query, two answers across a background flush.
//!
//! This is a #423-core manifestation (schemaless `doc_matches_query`): the fix
//! makes the Prefix arm schema-aware (keyword => case-sensitive raw compare,
//! matching the segment; text => analyzed-token semantics). A blanket
//! case-sensitive memtable prefix would break TEXT prefix (segment matches the
//! lowercased token stream), so schema is required. IGNORED until that fix.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn prefix_hits(engine: &Engine, p: &str) -> u64 {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({ "query": { "prefix": { "name": p } }, "size": 0 }))
        .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// `prefix` on a `keyword` field is flush-invariant. FAIL-BEFORE: the buffered
/// matcher folds case so `prefix:hel` on `"Hello"` is 1 pre-flush but 0 after
/// flush (the segment is case-sensitive, which is ES-correct for `keyword`).
#[tokio::test]
async fn prefix_keyword_case_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("name", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "name": "Hello" }))
        .await
        .expect("index");

    // Lowercase prefix against a capitalized keyword, document still buffered.
    let pre = prefix_hits(&engine, "hel").await;
    idx.refresh().await.expect("refresh");
    let post = prefix_hits(&engine, "hel").await;

    assert_eq!(
        pre, post,
        "#396: `prefix:hel` on keyword \"Hello\" must be flush-invariant \
         (pre-flush={pre}, post-flush={post}); the memtable Prefix arm folds \
         case while the segment is case-sensitive"
    );
    assert_eq!(
        post, 0,
        "ES: keyword prefix is case-sensitive, so `hel` != `Hello`"
    );
}

/// Companion: `prefix` on a `text` field is also flush-invariant. The segment
/// matches the LOWERCASED token with a RAW (un-lowercased) query, so an
/// uppercase prefix `"Hel"` on `"Hello World"` is 0; the memtable folds both
/// sides and answers 1. FAIL-BEFORE: pre-flush=1, post-flush=0.
#[tokio::test]
async fn prefix_text_case_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "body": "Hello World" }))
        .await
        .expect("index");

    // Uppercase prefix: the segment token is lowercased but the query is not,
    // so `"Hel"` does not prefix `"hello"`.
    let req = |p: &str| {
        parse_request(&json!({ "query": { "prefix": { "body": p } }, "size": 0 })).unwrap()
    };
    let pre = idx.search(&req("Hel")).await.unwrap().total.value;
    idx.refresh().await.expect("refresh");
    let post = idx.search(&req("Hel")).await.unwrap().total.value;

    assert_eq!(
        pre, post,
        "#396: `prefix:Hel` on text \"Hello World\" must be flush-invariant \
         (pre-flush={pre}, post-flush={post})"
    );
    assert_eq!(
        post, 0,
        "segment lowercases the token but not the query: `Hel` !prefix `hello`"
    );
}

/// #396 guard: `wildcard` on a keyword field stays flush-invariant. Unlike
/// `prefix`, the memtable and the segment BOTH fold case for wildcard, so a
/// lower-case pattern matches a capitalized keyword the same way before and
/// after flush. Making only the memtable case-sensitive split-brained it (a
/// regression caught in review); ES-correct keyword-wildcard case-sensitivity
/// is a separate change that must also touch the segment doc-values path.
#[tokio::test]
async fn wildcard_keyword_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("name", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "name": "Hello" }))
        .await
        .expect("index");

    let req = |p: &str| {
        parse_request(&json!({ "query": { "wildcard": { "name": p } }, "size": 0 })).unwrap()
    };
    let pre = idx.search(&req("hel*")).await.unwrap().total.value;
    idx.refresh().await.expect("refresh");
    let post = idx.search(&req("hel*")).await.unwrap().total.value;

    assert_eq!(
        pre, post,
        "#396: wildcard on a keyword field must be flush-invariant (pre={pre}, post={post})"
    );
}

/// #396 guard: `wildcard` on a TEXT field is flush-invariant. The segment
/// matches the RAW pattern against the lower-cased token stream (case-sensitive
/// on the pattern), so an uppercase `"Hel*"` matches nothing after flush — the
/// memtable must agree (it previously folded and answered 1, a divergence
/// caught in review). Lower-case `"hel*"` matches the token `hello` both sides.
#[tokio::test]
async fn wildcard_text_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("body", FieldType::Text));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d0".to_string()), json!({ "body": "Hello World" }))
        .await
        .expect("index");

    let req = |p: &str| {
        parse_request(&json!({ "query": { "wildcard": { "body": p } }, "size": 0 })).unwrap()
    };
    // Uppercase pattern: case-sensitive against the lower-cased token => 0.
    let pre_u = idx.search(&req("Hel*")).await.unwrap().total.value;
    // Lower-case pattern: matches token "hello" => 1.
    let pre_l = idx.search(&req("hel*")).await.unwrap().total.value;
    idx.refresh().await.expect("refresh");
    let post_u = idx.search(&req("Hel*")).await.unwrap().total.value;
    let post_l = idx.search(&req("hel*")).await.unwrap().total.value;

    assert_eq!(
        pre_u, post_u,
        "#396: wildcard text `Hel*` must be flush-invariant (pre={pre_u}, post={post_u})"
    );
    assert_eq!(
        pre_l, post_l,
        "#396: wildcard text `hel*` must be flush-invariant (pre={pre_l}, post={post_l})"
    );
    assert_eq!(
        post_u, 0,
        "uppercase pattern is case-sensitive against the lowercased token"
    );
    assert_eq!(post_l, 1, "lowercase pattern matches the token");
}

//! #1812: `prefix` on a `keyword` field must honor `case_insensitive`.
//!
//! ES matches `prefix` against the RAW keyword value (case-SENSITIVE by
//! default); `case_insensitive: true` folds both sides instead.  XERJ's
//! `Prefix` AST node dropped the flag entirely, so
//! `prefix:{k:{value:"HELLO",case_insensitive:true}}` on `"Hello World"`
//! returned 0 (wrong — ES returns the doc).
//!
//! Both the buffered (memtable) and flushed (segment) paths are asserted
//! pre- and post-`refresh`, mirroring `prefix_keyword_case_flush_parity.rs`:
//! a fix applied to only one path split-brains across a background flush,
//! which this repo treats as a regression class of its own.

use std::sync::Arc;

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// Index two keyword docs (capitalized + lowercase) and return the index.
async fn setup_docs(engine: &Engine) -> Arc<Index> {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("k", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d1".to_string()), json!({ "k": "Hello World" }))
        .await
        .expect("index");
    idx.index_document(Some("d2".to_string()), json!({ "k": "hello there" }))
        .await
        .expect("index");
    idx
}

async fn hits(idx: &Index, query: serde_json::Value) -> u64 {
    let req = parse_request(&json!({ "query": query, "size": 0 })).expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// FAIL-BEFORE (#1812): the flag was dropped at parse time, so this matched
/// 0 docs.  ES returns 2 (both keyword values start with "hello", folded).
#[tokio::test]
async fn prefix_case_insensitive_true_folds_both_paths() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    let q = json!({ "prefix": { "k": { "value": "HELLO", "case_insensitive": true } } });

    // Buffered (memtable) path.
    let pre = hits(&idx, q.clone()).await;
    // Flushed (segment) path.
    idx.refresh().await.expect("refresh");
    let post = hits(&idx, q).await;

    assert_eq!(
        pre, 2,
        "memtable: case_insensitive prefix must match both docs"
    );
    assert_eq!(
        pre, post,
        "flush-invariant: memtable={pre} vs segment={post} disagree"
    );
    assert_eq!(
        post, 2,
        "segment: case_insensitive prefix must match both docs"
    );
}

/// Explicit `case_insensitive: false` stays ES-correct case-SENSITIVE.
#[tokio::test]
async fn prefix_case_insensitive_false_is_case_sensitive() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    // "HELLO" prefixes neither "Hello World" nor "hello there" byte-wise.
    let q_upper = json!({ "prefix": { "k": { "value": "HELLO", "case_insensitive": false } } });
    // "hello" prefixes only the lowercase doc byte-wise.
    let q_lower = json!({ "prefix": { "k": { "value": "hello", "case_insensitive": false } } });

    let pre_upper = hits(&idx, q_upper.clone()).await;
    let pre_lower = hits(&idx, q_lower.clone()).await;
    idx.refresh().await.expect("refresh");
    let post_upper = hits(&idx, q_upper).await;
    let post_lower = hits(&idx, q_lower).await;

    assert_eq!(
        pre_upper, 0,
        "memtable: HELLO must not match capitalized values"
    );
    assert_eq!(
        pre_lower, 1,
        "memtable: hello must match only the lowercase doc"
    );
    assert_eq!(pre_upper, post_upper, "flush-invariant (upper)");
    assert_eq!(pre_lower, post_lower, "flush-invariant (lower)");
    assert_eq!(
        post_upper, 0,
        "segment: HELLO must not match capitalized values"
    );
    assert_eq!(
        post_lower, 1,
        "segment: hello must match only the lowercase doc"
    );
}

/// Omitted parameter defaults to `false` (shorthand and expanded forms).
#[tokio::test]
async fn prefix_omitted_case_insensitive_defaults_false() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    let q_upper = json!({ "prefix": { "k": "HELLO" } });
    let q_lower = json!({ "prefix": { "k": "hello" } });

    let pre_upper = hits(&idx, q_upper.clone()).await;
    let pre_lower = hits(&idx, q_lower.clone()).await;
    idx.refresh().await.expect("refresh");
    let post_upper = hits(&idx, q_upper).await;
    let post_lower = hits(&idx, q_lower).await;

    assert_eq!(pre_upper, 0, "shorthand HELLO defaults to case-sensitive");
    assert_eq!(
        pre_lower, 1,
        "shorthand hello matches only the lowercase doc"
    );
    assert_eq!(pre_upper, post_upper, "flush-invariant (upper)");
    assert_eq!(pre_lower, post_lower, "flush-invariant (lower)");
}

/// TEXT-field semantics are UNCHANGED by the flag: prefix runs against the
/// analyzed (lowercased) token stream, so a lowercase pattern matches and an
/// uppercase one does not — with or without `case_insensitive: true`.
#[tokio::test]
async fn prefix_case_insensitive_does_not_change_text_semantics() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema.fields.push(FieldConfig::new("t", FieldType::Text));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d1".to_string()), json!({ "t": "Hello World" }))
        .await
        .expect("index");
    idx.refresh().await.expect("refresh");

    let q_lower = json!({ "prefix": { "t": { "value": "hel", "case_insensitive": false } } });
    let q_lower_ci = json!({ "prefix": { "t": { "value": "hel", "case_insensitive": true } } });
    let q_upper = json!({ "prefix": { "t": { "value": "HEL", "case_insensitive": true } } });

    assert_eq!(
        hits(&idx, q_lower).await,
        1,
        "text: lowercase prefix matches the analyzed token"
    );
    assert_eq!(
        hits(&idx, q_lower_ci).await,
        1,
        "text: case_insensitive must not change analyzed-token matching"
    );
    assert_eq!(
        hits(&idx, q_upper).await,
        0,
        "text: uppercase prefix does not match the lowercased token (ES analyzes the doc, not the pattern)"
    );
}

//! # xerj Product Experience Tests
//!
//! These are USER JOURNEY tests, not performance benchmarks.
//! Each test simulates a real person trying to accomplish a real task,
//! and measures what matters to a PRODUCT user:
//!   - Time to first value
//!   - Data safety guarantees
//!   - Simplicity of the experience
//!   - Correctness of results
//!
//! Compare every journey against Elasticsearch to show why xerj exists.
//!
//! # Running
//!
//! ```bash
//! cargo test -p xerj-engine --test product_experience -- --nocapture
//! ```

use serde_json::json;
use std::time::{Duration, Instant};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::bulk::process_bulk;
use xerj_engine::sql::parse_sql;
use xerj_engine::Engine;
use xerj_query::ast::{SearchRequest, SourceFilter};
use xerj_query::parse_request;

// ── Helpers ───────────────────────────────────────────────────────────────────

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn make_engine_with_config(dir: &TempDir, configure: impl FnOnce(&mut Config)) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    configure(&mut config);
    Engine::new(config).expect("engine::new")
}

fn print_result(journey: &str, xerj_desc: &str, es_desc: &str, winner_line: &str) {
    let width = 52usize;
    let border = "=".repeat(width);
    let pad = |s: &str| {
        let content = format!("  {}", s);
        let spaces = width.saturating_sub(content.chars().count() + 2);
        format!("\u{2551}{}{}\u{2551}", content, " ".repeat(spaces))
    };
    println!("\u{2554}{}\u{2557}", border);
    println!("{}", pad(&format!("JOURNEY: {}", journey)));
    println!("\u{2560}{}\u{2563}", border);
    println!("{}", pad(&format!("xerj: {}", xerj_desc)));
    println!("{}", pad(&format!("ES:    {}", es_desc)));
    println!("{}", pad(&format!("Winner: {}", winner_line)));
    println!("\u{255a}{}\u{255d}", border);
    println!();
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 1: "I just want to search my docs"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_first_time_user() {
    // Simulate: download xerj, start it, index 100 docs, search.
    // Measure: time from zero to first search result.
    // Compare: ES needs 60+ seconds just to start (JVM + heap warm-up).

    let dir = TempDir::new().unwrap();
    let start = Instant::now();

    let engine = make_engine(&dir);
    engine.create_index("my-data", Schema::empty()).unwrap();
    let idx = engine.get_index("my-data").unwrap();

    // Index 100 documents — a small personal document collection.
    for i in 0..100 {
        idx.index_document(
            Some(format!("doc-{i}")),
            json!({
                "title": format!("Document {i}"),
                "body": format!("This is document number {i} about various topics")
            }),
        )
        .await
        .unwrap();
    }

    // First search — the moment the user gets value.
    let result = idx
        .search(
            &parse_request(&json!({
                "query": { "match": { "body": "various topics" } }
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    let total_time = start.elapsed();

    print_result(
        "First-Time User",
        &format!("{:.2?} from zero to search results", total_time),
        "60+ seconds (JVM startup alone)",
        &format!(
            "xerj ({:.0}x faster to first value)",
            60_000.0 / total_time.as_millis().max(1) as f64
        ),
    );

    assert!(
        total_time < Duration::from_secs(5),
        "Must reach first search result in under 5 seconds, took {:?}",
        total_time
    );
    assert!(result.total.value > 0, "Must find at least one document");
    assert_eq!(
        result.total.value, 100,
        "All 100 docs should match 'various topics'"
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 2: "My app crashed, is my data safe?"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_crash_recovery() {
    // THE #1 fear from ES users: data loss on crash.
    // Elasticsearch requires careful JVM heap tuning and can lose data
    // when a node crashes before the translog is flushed.
    //
    // xerj writes to a WAL before acknowledging every write.
    // On restart the WAL is replayed — no data loss.

    let dir = TempDir::new().unwrap();
    let data_path = dir.path().to_str().unwrap().to_string();

    // Phase 1: index 1000 docs, then "crash" (drop the engine).
    let doc_count = 1_000usize;
    {
        let mut config = Config::default();
        config.server.data_dir = data_path.clone();
        let engine = Engine::new(config).unwrap();

        engine
            .create_index("critical-data", Schema::empty())
            .unwrap();
        let idx = engine.get_index("critical-data").unwrap();

        for i in 0..doc_count {
            idx.index_document(
                Some(format!("doc-{i}")),
                json!({
                    "id": i,
                    "payload": format!("mission-critical record number {i}"),
                    "important": true
                }),
            )
            .await
            .unwrap();
        }

        // Simulate crash: engine is dropped without a clean shutdown.
        // The WAL on disk is the only record of these writes.
        drop(engine);
    }

    // Phase 2: "restart" — open the same data directory.
    let recovery_start = Instant::now();
    {
        let mut config = Config::default();
        config.server.data_dir = data_path.clone();
        let engine = Engine::new(config).unwrap();
        let recovery_time = recovery_start.elapsed();

        // All data must survive.
        let idx = engine.get_index("critical-data").unwrap();
        let result = idx
            .search(
                &parse_request(&json!({
                    "query": { "match_all": {} },
                    "size": 0
                }))
                .unwrap(),
            )
            .await
            .unwrap();

        print_result(
            "Crash Recovery",
            &format!("all {} docs recovered in {:.2?}", doc_count, recovery_time),
            "possible data loss; recovery requires manual translog ops",
            "xerj (WAL guarantees zero data loss)",
        );

        assert_eq!(
            result.total.value, doc_count as u64,
            "All {} documents must survive a crash and restart, found {}",
            doc_count, result.total.value
        );
        assert!(
            recovery_time < Duration::from_secs(10),
            "Recovery must complete in under 10 seconds, took {:?}",
            recovery_time
        );
    }
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 3: "Can I just use SQL?"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_sql_user() {
    // User who knows SQL, doesn't want to learn the ES query DSL.
    // xerj supports a SQL subset out of the box.
    // ES requires the X-Pack SQL plugin (paid tier).

    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    engine.create_index("products", Schema::empty()).unwrap();
    let idx = engine.get_index("products").unwrap();

    // A product catalogue any developer would recognise.
    idx.index_document(Some("1".into()), json!({"name": "Laptop Pro",   "price": 1299.0, "category": "electronics", "in_stock": true})).await.unwrap();
    idx.index_document(Some("2".into()), json!({"name": "Coffee Mug",   "price": 12.0,   "category": "kitchen",     "in_stock": true})).await.unwrap();
    idx.index_document(Some("3".into()), json!({"name": "Standing Desk","price": 599.0,  "category": "furniture",   "in_stock": false})).await.unwrap();
    idx.index_document(Some("4".into()), json!({"name": "Mechanical KB","price": 149.0,  "category": "electronics", "in_stock": true})).await.unwrap();
    idx.index_document(Some("5".into()), json!({"name": "USB-C Hub",    "price": 49.0,   "category": "electronics", "in_stock": true})).await.unwrap();

    // SQL query — exactly what a developer comfortable with databases would write.
    let sql = "SELECT name, price FROM products WHERE price > 100 ORDER BY price DESC LIMIT 3";
    let parsed = parse_sql(sql).unwrap();

    assert_eq!(parsed.index, "products");

    let req = SearchRequest {
        query: parsed.query,
        size: parsed.limit.unwrap_or(10),
        sort: parsed.sort,
        source: SourceFilter::Includes(parsed.fields),
        ..Default::default()
    };

    let result = idx.search(&req).await.unwrap();

    // Should find: Laptop Pro (1299), Standing Desk (599), Mechanical KB (149)
    assert_eq!(
        result.total.value, 3,
        "SQL WHERE price > 100 should return 3 products, got {}",
        result.total.value
    );

    // Verify ORDER BY price DESC worked — most expensive first.
    let prices: Vec<f64> = result
        .hits
        .iter()
        .filter_map(|h| h.source.get("price").and_then(|v| v.as_f64()))
        .collect();
    assert!(
        prices.windows(2).all(|w| w[0] >= w[1]),
        "Results must be sorted by price DESC, got: {:?}",
        prices
    );

    // Simple SQL — no need to learn query DSL at all.
    let count_sql = "SELECT name FROM products WHERE category = 'electronics'";
    let parsed_count = parse_sql(count_sql).unwrap();
    let count_req = SearchRequest {
        query: parsed_count.query,
        size: parsed_count.limit.unwrap_or(100),
        ..Default::default()
    };
    let count_result = idx.search(&count_req).await.unwrap();
    assert_eq!(count_result.total.value, 3, "3 electronics products");

    print_result(
        "SQL User",
        "standard SQL works; zero query DSL learning curve",
        "requires X-Pack SQL plugin (paid); non-standard syntax",
        "xerj (SQL built-in, free, no plugin needed)",
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 4: "I need log analytics"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_log_analytics() {
    // SRE needs to find errors in logs, count by service, spot spikes.
    // ES needs the full ELK stack: 4 separate tools to install and operate.
    // xerj needs 1 binary.

    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    engine.create_index("app-logs", Schema::empty()).unwrap();
    let idx = engine.get_index("app-logs").unwrap();

    let services = [
        "auth-service",
        "payment-service",
        "user-service",
        "api-gateway",
    ];
    let levels = ["INFO", "WARN", "ERROR", "DEBUG"];
    let messages = [
        "request processed successfully",
        "connection timeout, retrying",
        "database query failed: connection refused",
        "cache miss for key user:12345",
        "authentication token expired",
        "payment declined: insufficient funds",
        "rate limit exceeded for IP 192.168.1.1",
        "health check passed",
    ];

    // Index 5000 log entries — a realistic log volume for a small app.
    let ingest_start = Instant::now();
    for i in 0..5_000usize {
        let service = services[i % services.len()];
        // Skew: errors cluster in payment-service and api-gateway.
        let level = if (service == "payment-service" && i % 5 == 0)
            || (service == "api-gateway" && i % 8 == 0)
        {
            "ERROR"
        } else {
            levels[i % 3] // INFO/WARN/ERROR cycling but less ERROR
        };
        let msg = messages[i % messages.len()];

        idx.index_document(
            Some(format!("log-{i}")),
            json!({
                "@timestamp": format!("2024-01-15T{:02}:{:02}:{:02}Z", (i/3600)%24, (i/60)%60, i%60),
                "level": level,
                "service": service,
                "message": msg,
                "duration_ms": (i % 500) as u64,
                "status_code": if level == "ERROR" { 500 } else { 200 }
            }),
        )
        .await
        .unwrap();
    }
    let ingest_time = ingest_start.elapsed();

    // Query 1: Find all ERROR logs.
    let search_start = Instant::now();
    let errors = idx
        .search(
            &parse_request(&json!({
                "query": { "term": { "level": "ERROR" } },
                "size": 0
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    let search_time = search_start.elapsed();

    assert!(errors.total.value > 0, "Must find ERROR logs");

    // Query 2: Find errors in payment-service specifically.
    let payment_errors = idx
        .search(
            &parse_request(&json!({
                "query": {
                    "bool": {
                        "must": [
                            { "term": { "level": "ERROR" } },
                            { "term": { "service": "payment-service" } }
                        ]
                    }
                },
                "size": 0
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    assert!(
        payment_errors.total.value > 0,
        "Must find payment-service errors"
    );

    // Query 3: Full-text search across log messages — find connection issues.
    let connection_issues = idx
        .search(
            &parse_request(&json!({
                "query": { "match": { "message": "connection" } },
                "size": 10
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    assert!(
        connection_issues.total.value > 0,
        "Must find logs mentioning 'connection'"
    );

    print_result(
        "Log Analytics (SRE)",
        &format!(
            "5,000 logs indexed in {:.2?}, searched in {:.2?}",
            ingest_time, search_time
        ),
        "requires ELK stack: 4 tools, 3 JVMs, 16GB+ RAM minimum",
        "xerj (1 binary, single config, works on a laptop)",
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 5: "I need to migrate from Elasticsearch"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_es_migration() {
    // Verify that the ES-shaped *response bodies* the migration story depends on
    // are produced: `_index`/`_id`/`result`/`_shards` on a write, `hits.total`
    // as an object on a search, per-item results on a bulk.
    //
    // Scope, stated honestly because this test used to claim more than it does
    // (#207): it drives the Rust engine API directly — `create_index`,
    // `index_document`, `process_bulk` — and never makes an HTTP request. It is
    // NOT evidence that "the same curl commands" work; nothing here exercises
    // routing, URI parameters, headers, status codes or content negotiation.
    // The HTTP wire contract is covered by the ES-compat YAML conformance suite
    // (`engine/tests/es-compat-yaml`, run by the `conformance` CI job), which
    // replays real Elasticsearch REST test cases over the network.

    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    // PUT /{index} — create an index (ES: same JSON body format).
    engine.create_index("my-index", Schema::empty()).unwrap();

    // PUT /{index}/_doc/{id} — index a document (ES semantics).
    let idx = engine.get_index("my-index").unwrap();
    let resp = idx
        .index_document(
            Some("1".into()),
            json!({
                "user": "kimchy",
                "post_date": "2009-11-15",
                "message": "trying out xerj"
            }),
        )
        .await
        .unwrap();

    // ES contract: _id, result, _version fields in response.
    assert_eq!(resp.id, "1", "response._id must match supplied ID");
    assert_eq!(
        resp.result, "created",
        "result must be 'created' on first write"
    );
    assert_eq!(resp.version, 1, "_version must start at 1");

    // POST /{index}/_search — same query DSL as ES.
    let result = idx
        .search(
            &parse_request(&json!({
                "query": {
                    "match": { "message": "xerj" }
                }
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(
        result.total.value, 1,
        "Search must find the indexed document"
    );
    // ES response format: hits.total.value and hits.hits[].
    let hit = &result.hits[0];
    assert_eq!(hit.id, "1");
    assert!(
        hit.source.get("user").is_some(),
        "Source fields must be returned"
    );

    // POST /_bulk — NDJSON bulk format (identical to ES).
    let bulk_body = r#"{"index":{"_index":"my-index","_id":"2"}}
{"user":"alice","post_date":"2024-01-01","message":"bulk insert works"}
{"index":{"_index":"my-index","_id":"3"}}
{"user":"bob","post_date":"2024-01-02","message":"migration is easy"}
{"create":{"_index":"my-index","_id":"4"}}
{"user":"carol","post_date":"2024-01-03","message":"no reindex needed"}
"#;

    let bulk_result = process_bulk(&engine, Some("my-index"), bulk_body).await;
    assert!(
        !bulk_result.errors,
        "Bulk operation must succeed without errors"
    );
    assert_eq!(
        bulk_result.items.len(),
        3,
        "All 3 bulk items must be processed"
    );
    for item in &bulk_result.items {
        assert!(
            item.status == 200 || item.status == 201,
            "Each bulk item must return HTTP 200 or 201"
        );
    }

    // Verify all docs are searchable immediately after bulk.
    let all_docs = idx
        .search(
            &parse_request(&json!({
                "query": { "match_all": {} },
                "size": 100
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(
        all_docs.total.value, 4,
        "All 4 documents (1 direct + 3 bulk) must be searchable"
    );

    // Range query — ES syntax unchanged.
    let recent = idx
        .search(
            &parse_request(&json!({
                "query": {
                    "range": {
                        "post_date": { "gte": "2024-01-01" }
                    }
                }
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(
        recent.total.value, 3,
        "Range query must find 3 docs from 2024"
    );

    print_result(
        "ES Migration",
        "same curl commands work; zero code changes required",
        "migration requires reindex + downtime + mapping changes",
        "xerj (drop-in ES replacement; same REST API)",
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 6: "Is it actually secure?"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_security_by_default() {
    // ES was open to the internet by default for years — no auth required.
    // This caused thousands of data breaches (MongoDB, Elastic, etc.).
    //
    // xerj has auth ENABLED by default.
    // The admin API key is auto-generated on first run.

    // Default config — auth should be ON without any setup.
    let config = Config::default();
    assert!(
        config.auth.enabled,
        "Auth must be ENABLED in the default configuration"
    );

    // Admin key starts empty — it's auto-generated at server startup time.
    // (In tests we verify the flag, not the runtime key generation.)
    // The point: you can't accidentally run an open cluster.
    let config_with_auth = Config::from_toml_str(
        r#"
        [auth]
        enabled = true
        admin_api_key = "test-key-abc123"
        "#,
    )
    .unwrap();
    assert!(config_with_auth.auth.enabled);
    assert_eq!(config_with_auth.auth.admin_api_key, "test-key-abc123");

    // Verify: disabling auth is a deliberate choice, not the default.
    let insecure_config = Config::from_toml_str(
        r#"
        [auth]
        enabled = false
        "#,
    )
    .unwrap();
    assert!(
        !insecure_config.auth.enabled,
        "Auth can be disabled explicitly for dev/testing"
    );

    // Verify: the default config is valid (usable out of the box).
    Config::default()
        .validate()
        .expect("Default config must be valid");

    print_result(
        "Security by Default",
        "auth enabled by default; API key auto-generated on first run",
        "open to the world by default for years (CVE-2014-3120, etc.)",
        "xerj (secure by default, no config required)",
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 7: "Can I upgrade without downtime?"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_upgrade() {
    // Index data, "upgrade" (restart the engine), verify no data loss.
    // No reindex. No rolling restart. No cluster coordination.
    // Compare: ES upgrades take weeks; require reindex across major versions.

    let dir = TempDir::new().unwrap();
    let data_path = dir.path().to_str().unwrap().to_string();

    let doc_count = 500usize;

    // Phase 1: pre-upgrade state — data in place.
    {
        let mut config = Config::default();
        config.server.data_dir = data_path.clone();
        let engine = Engine::new(config).unwrap();

        engine
            .create_index("user-profiles", Schema::empty())
            .unwrap();
        let idx = engine.get_index("user-profiles").unwrap();

        for i in 0..doc_count {
            idx.index_document(
                Some(format!("user-{i}")),
                json!({
                    "id": i,
                    "name": format!("User {i}"),
                    "email": format!("user{}@example.com", i),
                    "plan": if i % 3 == 0 { "enterprise" } else { "free" }
                }),
            )
            .await
            .unwrap();
        }

        // Flush to durable segments before "upgrading".
        engine.flush_index("user-profiles").await.unwrap();
    }

    // Phase 2: "upgrade" — restart with new binary (same data directory).
    let upgrade_start = Instant::now();
    {
        let mut config = Config::default();
        config.server.data_dir = data_path.clone();
        let engine = Engine::new(config).unwrap();
        let startup_time = upgrade_start.elapsed();

        let idx = engine.get_index("user-profiles").unwrap();

        // All data must be immediately available — no reindex.
        let all = idx
            .search(
                &parse_request(&json!({
                    "query": { "match_all": {} },
                    "size": 0
                }))
                .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(
            all.total.value, doc_count as u64,
            "All {} user profiles must survive an upgrade, found {}",
            doc_count, all.total.value
        );

        // Queries still work — no schema migration needed.
        // Verify specific queries work after restart
        let enterprise = idx
            .search(
                &parse_request(&json!({
                    "query": { "match_all": {} },
                    "size": 3
                }))
                .unwrap(),
            )
            .await
            .unwrap();
        println!(
            "  After upgrade: {} docs found, first 3: {:?}",
            enterprise.total.value,
            enterprise.hits.iter().map(|h| &h.id).collect::<Vec<_>>()
        );
        assert!(
            enterprise.total.value >= doc_count as u64 / 2,
            "Most docs must survive upgrade, found {}",
            enterprise.total.value
        );

        print_result(
            "Zero-Downtime Upgrade",
            &format!(
                "restart in {:.2?}; all {} docs immediately available",
                startup_time, doc_count
            ),
            "major version upgrades require reindex (days/weeks); rolling restarts",
            "xerj (restart and go; no reindex ever)",
        );

        assert!(
            startup_time < Duration::from_secs(5),
            "Engine must restart in under 5 seconds, took {:?}",
            startup_time
        );
    }
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 8: "How many settings do I need to configure?"
// ═════════════════════════════════════════════════════════════════════════════

/// Leaf keys in a serialised config — one per setting a user can set.
///
/// Sub-configs are grouping, not settings, so only leaves count. An empty map
/// contributes nothing, which is correct: a map-valued setting with no entries
/// is not a knob anybody has turned.
fn count_settings(value: &serde_json::Value) -> usize {
    match value {
        serde_json::Value::Object(fields) => fields.values().map(count_settings).sum(),
        _ => 1,
    }
}

/// Settings in a default `Config`, measured by `count_settings`. Quoted in
/// `xerj-common/src/config.rs`; keep the two in step.
const EXPECTED_SETTINGS: usize = 137;

#[tokio::test]
async fn journey_zero_config() {
    // Start with ZERO configuration.
    // Everything works with defaults — including indexing and searching.
    // Compare: ES has 3,000+ settings; requires JVM heap, cluster name,
    // network host, discovery seeds, initial master nodes, etc.

    let dir = TempDir::new().unwrap();

    // Zero-config: just point at a data dir and go.
    let engine = make_engine_with_config(&dir, |_| {
        // No changes — pure defaults.
    });

    // Verify auth is on (secure default).
    let config = Config::default();
    assert!(config.auth.enabled, "auth.enabled must default to true");

    // Verify the engine works end-to-end with defaults.
    engine.create_index("notes", Schema::empty()).unwrap();
    let idx = engine.get_index("notes").unwrap();

    idx.index_document(
        Some("1".into()),
        json!({"title": "Zero config", "body": "Just works out of the box"}),
    )
    .await
    .unwrap();

    let result = idx
        .search(
            &parse_request(&json!({
                "query": { "match": { "body": "just works" } }
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    assert_eq!(
        result.total.value, 1,
        "Search must work with zero configuration"
    );

    // Count user-facing settings — by *counting them*, not by re-adding a
    // hardcoded sum. This assertion used to read
    //   let xerj_settings = 5 + 2 + 3 + 5 + 5 + 3 + 1 + 6 + 2 + 4 + 3 - 1;
    //   assert_eq!(xerj_settings, 38);
    // which is the identity 38 == 38: it could not fail whatever `Config`
    // actually held, and by the time #207 was filed the real number was nowhere
    // near 38 while three places in the tree quoted three different figures.
    //
    // `Config` is `Serialize` and every field defaults, so the honest count is
    // the number of leaf keys in a default config. (`xerj.default.toml` sets
    // the commonly tuned 53 of them and describes the rest in comments; its own
    // agreement with `Config::default()` is pinned by
    // `shipped_default_config_documents_the_real_defaults` in xerj-common.)
    let xerj_settings = count_settings(&serde_json::to_value(Config::default()).unwrap());
    assert_eq!(
        xerj_settings, EXPECTED_SETTINGS,
        "the settings count changed. That is fine — but it is quoted in prose, \
         so update xerj-common/src/config.rs (module header and the total under \
         `struct Config`) and EXPECTED_SETTINGS together, and re-check any doc \
         that cites a number"
    );

    print_result(
        "Zero Configuration",
        &format!(
            "{} settings total; works out of the box with defaults",
            xerj_settings
        ),
        "3,000+ settings; requires JVM tuning, cluster config, network setup",
        &format!(
            "xerj ({:.0}x fewer settings to learn)",
            3000.0 / xerj_settings as f64
        ),
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 9: "I need real-time search"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_realtime_search() {
    // Index a document.
    // Immediately search for it — no refresh delay, no waiting.
    // Compare: ES has a 1-second refresh interval by default.
    // New docs are invisible until the next refresh cycle.
    // This breaks real-time use cases (chat, feeds, live dashboards).

    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    engine.create_index("feed", Schema::empty()).unwrap();
    let idx = engine.get_index("feed").unwrap();

    // Index a document.
    let write_time = Instant::now();
    idx.index_document(
        Some("post-1".into()),
        json!({
            "author": "alice",
            "content": "Just published: real-time search without refresh intervals",
            "likes": 0
        }),
    )
    .await
    .unwrap();
    let write_elapsed = write_time.elapsed();

    // Immediately search — no sleep, no refresh call.
    let search_time = Instant::now();
    let result = idx
        .search(
            &parse_request(&json!({
                "query": { "match": { "content": "real-time" } }
            }))
            .unwrap(),
        )
        .await
        .unwrap();
    let search_elapsed = search_time.elapsed();

    // The document must be found immediately.
    assert_eq!(
        result.total.value, 1,
        "Document must be searchable immediately after indexing (no refresh delay)"
    );
    assert_eq!(result.hits[0].id, "post-1");

    // Verify the source is correct.
    let source = &result.hits[0].source;
    assert_eq!(source["author"], "alice");

    // Index 10 more documents and immediately search.
    for i in 2..=10 {
        idx.index_document(
            Some(format!("post-{i}")),
            json!({"author": format!("user{i}"), "content": format!("post {i} content here")}),
        )
        .await
        .unwrap();
    }

    let all = idx
        .search(&parse_request(&json!({ "query": { "match_all": {} }, "size": 0 })).unwrap())
        .await
        .unwrap();
    assert_eq!(
        all.total.value, 10,
        "All 10 documents must be searchable immediately"
    );

    print_result(
        "Real-Time Search",
        &format!(
            "write in {:.2?}, searchable in {:.2?} (no refresh needed)",
            write_elapsed, search_elapsed
        ),
        "1-second refresh interval by default; new docs invisible until next refresh",
        "xerj (true real-time; writes are instantly searchable)",
    );
}

// ═════════════════════════════════════════════════════════════════════════════
// Journey 10: "I need geo search"
// ═════════════════════════════════════════════════════════════════════════════

#[tokio::test]
async fn journey_geo_search() {
    // Index locations (restaurants) with GPS coordinates.
    // Find the ones nearest to a user within a radius.
    // Verify: correct results, right count, plausible distances.

    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    engine.create_index("restaurants", Schema::empty()).unwrap();
    let idx = engine.get_index("restaurants").unwrap();

    // Manhattan restaurant cluster (within ~2 km of Times Square).
    let times_square = (40.7580, -73.9855_f64);

    idx.index_document(
        Some("r1".into()),
        json!({
            "name": "Joe's Pizza",
            "cuisine": "italian",
            "location": { "lat": 40.7575, "lon": -73.9875 },  // 0.3 km
            "rating": 4.5
        }),
    )
    .await
    .unwrap();

    idx.index_document(
        Some("r2".into()),
        json!({
            "name": "Corner Deli",
            "cuisine": "american",
            "location": { "lat": 40.7590, "lon": -73.9840 },  // 0.2 km
            "rating": 3.8
        }),
    )
    .await
    .unwrap();

    idx.index_document(
        Some("r3".into()),
        json!({
            "name": "Sushi Palace",
            "cuisine": "japanese",
            "location": { "lat": 40.7560, "lon": -73.9900 },  // 0.5 km
            "rating": 4.2
        }),
    )
    .await
    .unwrap();

    // Brooklyn — 8 km away, outside the search radius.
    idx.index_document(
        Some("r4".into()),
        json!({
            "name": "Brooklyn Burger",
            "cuisine": "american",
            "location": { "lat": 40.6782, "lon": -73.9442 },  // ~8.5 km
            "rating": 4.7
        }),
    )
    .await
    .unwrap();

    // Central Park area — 2.5 km away.
    idx.index_document(
        Some("r5".into()),
        json!({
            "name": "Park Bistro",
            "cuisine": "french",
            "location": { "lat": 40.7812, "lon": -73.9665 },  // ~2.7 km
            "rating": 4.0
        }),
    )
    .await
    .unwrap();

    // Search: restaurants within 1 km of Times Square.
    let nearby = idx
        .search(
            &parse_request(&json!({
                "query": {
                    "geo_distance": {
                        "distance": "1km",
                        "location": { "lat": times_square.0, "lon": times_square.1 }
                    }
                },
                "size": 10
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    // Joe's Pizza, Corner Deli, and Sushi Palace are within 1km.
    // Brooklyn Burger is ~8.5km away — must be excluded.
    // Park Bistro is ~2.7km away — must be excluded.
    assert!(
        nearby.total.value >= 2,
        "At least 2 restaurants must be within 1km of Times Square, found {}",
        nearby.total.value
    );
    let nearby_ids: Vec<&str> = nearby.hits.iter().map(|h| h.id.as_str()).collect();
    assert!(
        !nearby_ids.contains(&"r4"),
        "Brooklyn Burger (8.5km away) must NOT appear in 1km radius search"
    );

    // Wider search: 5 km radius — still excludes Brooklyn.
    let wider = idx
        .search(
            &parse_request(&json!({
                "query": {
                    "geo_distance": {
                        "distance": "5km",
                        "location": { "lat": times_square.0, "lon": times_square.1 }
                    }
                }
            }))
            .unwrap(),
        )
        .await
        .unwrap();

    assert!(
        wider.total.value >= 3,
        "At least 3 restaurants within 5km, found {}",
        wider.total.value
    );
    let wider_ids: Vec<&str> = wider.hits.iter().map(|h| h.id.as_str()).collect();
    assert!(
        !wider_ids.contains(&"r4"),
        "Brooklyn Burger (8.5km) must NOT appear in 5km search"
    );

    print_result(
        "Geo Search",
        "geo_distance query works; correct radius filtering",
        "same geo_distance API; requires careful geo_point mapping setup",
        "xerj (geo search built-in; no mapping ceremony needed)",
    );
}

//! Regression tests for the field-less `query_string` projection.
//!
//! `query_string` with no `default_field` searches EVERY mapped text field
//! (ES/OpenSearch `index.query.default_field` defaults to `"*"`). Two hazards
//! come with that widening, and both are covered here:
//!
//!  1. HETEROGENEOUS SEGMENTS. Segments flushed before a field first appeared
//!     carry no FTS side-car for it. The per-segment "does the reader have
//!     every queried field?" gate then rejects the whole segment and the
//!     stored-doc fallback had no `query_string` matcher at all — so those
//!     segments silently contributed ZERO hits. Under-matching on a search
//!     path surfaces nowhere, which is worse than the single-field bug it
//!     replaced.
//!
//!  2. `tokens × fields` CROSS-PRODUCT. One `should` clause is built per
//!     (token, field) pair and the bool executor materialises a full hit
//!     vector per clause, so a wide mapping plus a long query string is an
//!     unbounded, uninterruptible unit of work inside the search hot path.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::ast::{QueryNode, SearchRequest};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// One ingest shard and a flush threshold nothing in these tests can reach, so
/// an explicit `flush()` yields exactly ONE segment. The between-segment
/// deadline check is what bounds a multi-segment scan; a single segment is the
/// shape where the only thing standing between a clause storm and an
/// indefinitely-held worker is a poll *inside* the clause loop.
fn make_single_segment_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    config.storage.flush_size_mb = 8_192;
    config.engine.ingest_shards = 1;
    Engine::new(config).expect("engine::new")
}

fn search(query_json: Value) -> SearchRequest {
    parse_request(&json!({ "query": query_json, "size": 100 })).expect("parse_request")
}

/// A `query_string` whose text the Lucene lowerer cannot parse (here: an
/// unterminated quote) stays an opaque `QueryNode::QueryString` — the node
/// whose projection this PR changes. Anything that lowers becomes a
/// `Match`/`Bool` tree and never reaches that arm.
fn opaque_qs(text: &str) -> Value {
    json!({ "query_string": { "query": format!("\"{text}") } })
}

/// HIGH: heterogeneous segments must contribute the same hits as a
/// homogeneous corpus with the same documents.
///
/// `hetero` flushes a segment holding only `alpha` BEFORE any document
/// introduces `beta`, so that segment's FTS side-car has no `beta` field.
/// `homo` indexes the identical documents but flushes once, after `beta`
/// exists, so every segment carries both fields. The two must agree.
#[tokio::test]
async fn field_less_query_string_matches_equally_across_heterogeneous_segments() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    // Documents 0..5 only ever have `alpha`; 5..10 have `alpha` + `beta`.
    let docs: Vec<Value> = (0..10)
        .map(|i| {
            if i < 5 {
                json!({ "alpha": format!("needle alpha body {i}") })
            } else {
                json!({ "alpha": format!("filler body {i}"), "beta": "needle beta body" })
            }
        })
        .collect();

    engine.create_index("hetero", Schema::empty()).unwrap();
    let hetero = engine.get_index("hetero").unwrap();
    for (i, d) in docs.iter().enumerate() {
        hetero
            .index_document(Some(format!("d{i}")), d.clone())
            .await
            .unwrap();
        // Flush right after the alpha-only prefix: that segment is written
        // before `beta` is ever seen, so it has no `beta` FTS side-car.
        if i == 4 {
            hetero.flush().await.unwrap();
        }
    }
    hetero.flush().await.unwrap();

    engine.create_index("homo", Schema::empty()).unwrap();
    let homo = engine.get_index("homo").unwrap();
    // Seed `beta` first so the very first segment carries both fields.
    homo.index_document(
        Some("seed".to_string()),
        json!({ "alpha": "seed body", "beta": "seed body" }),
    )
    .await
    .unwrap();
    homo.flush().await.unwrap();
    for (i, d) in docs.iter().enumerate() {
        homo.index_document(Some(format!("d{i}")), d.clone())
            .await
            .unwrap();
    }
    homo.flush().await.unwrap();

    let q = opaque_qs("needle");
    let h = hetero.search(&search(q.clone())).await.unwrap();
    let m = homo.search(&search(q)).await.unwrap();

    assert_eq!(
        h.total.value,
        10,
        "every document holds `needle` in some text field; heterogeneous \
         segments dropped {} of them",
        10 - h.total.value
    );
    assert_eq!(
        h.total.value, m.total.value,
        "heterogeneous segments must match the same documents as a \
         homogeneous corpus (hetero={} homo={})",
        h.total.value, m.total.value
    );
}

/// HIGH, narrower: the same corpus queried for a token that lives ONLY in the
/// field the older segment lacks. The older segment legitimately contributes
/// nothing, but the newer one must still answer.
#[tokio::test]
async fn field_less_query_string_finds_new_field_added_after_a_flush() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("late_field", Schema::empty()).unwrap();
    let idx = engine.get_index("late_field").unwrap();

    for i in 0..5 {
        idx.index_document(Some(format!("old{i}")), json!({ "alpha": "old body" }))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();
    for i in 0..3 {
        idx.index_document(
            Some(format!("new{i}")),
            json!({ "alpha": "new body", "beta": "zebrafish" }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    let r = idx.search(&search(opaque_qs("zebrafish"))).await.unwrap();
    assert_eq!(
        r.total.value, 3,
        "`zebrafish` lives only in `beta`, present in 3 documents"
    );
}

/// BLOCKER: a wide mapping crossed with a long query string must not turn one
/// request into an unbounded unit of work. The request carries a short
/// timeout; it must come back inside a small multiple of that budget rather
/// than grinding through `tokens × fields` clauses.
#[tokio::test]
async fn field_less_query_string_cross_product_respects_the_request_deadline() {
    let dir = TempDir::new().unwrap();
    let engine = make_single_segment_engine(&dir);
    engine.create_index("wide", Schema::empty()).unwrap();
    let idx = engine.get_index("wide").unwrap();

    // Every field of every document carries the SAME vocabulary, so every
    // (token, field) clause the projection can build is a clause that
    // actually returns the whole corpus — the worst case, and the one an
    // attacker picks.
    const FIELDS: usize = 120;
    const TOKENS: usize = 300;
    const DOCS: usize = 600;
    let body: String = (0..TOKENS).map(|t| format!("tok{t} ")).collect::<String>();
    for d in 0..DOCS {
        let mut doc = serde_json::Map::new();
        for f in 0..FIELDS {
            doc.insert(format!("f{f}"), json!(body.clone()));
        }
        idx.index_document(Some(format!("d{d}")), Value::Object(doc))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    // 300 tokens × 120 fields = 36 000 `should` clauses, each matching all
    // 600 documents — 21.6 M materialised hits before a single result is
    // returned, with nothing polling the request deadline in between.
    let req = parse_request(&json!({
        "query": { "query_string": { "query": format!("\"{body}") } },
        "size": 10,
        "timeout": "150ms",
    }))
    .expect("parse_request");

    let stats = idx.stats().await;
    assert_eq!(
        stats.segment_count, 1,
        "the test needs ONE segment: with several, the between-segment \
         deadline check masks an uninterruptible clause loop"
    );

    let t0 = std::time::Instant::now();
    let res = idx.search(&req).await.unwrap();
    let elapsed = t0.elapsed();
    eprintln!(
        "cross-product query: {elapsed:?}, total={} timed_out={}",
        res.total.value, res.timed_out
    );

    // Generous multiple of the 150ms budget so a loaded 2-core CI runner has
    // room, but far below the seconds an unbounded clause storm takes.
    assert!(
        elapsed < std::time::Duration::from_secs(3),
        "field-less query_string cross-product ran {elapsed:?} against a \
         150ms deadline — the projection is unbounded and the clause loop \
         never polls the deadline"
    );
    // Whatever comes back must be self-consistent: either it finished inside
    // the budget, or it says it did not. This assertion is load-normalising —
    // a slow machine trips the deadline poll and reports `timed_out`, so only
    // a run with NO poll at all can overshoot while claiming success.
    assert!(
        res.timed_out || elapsed < std::time::Duration::from_millis(1_500),
        "a run that overran its deadline must report timed_out"
    );

    // Load-independent restatement: a budget the work provably cannot meet
    // must come back saying so.
    let impossible = parse_request(&json!({
        "query": { "query_string": { "query": format!("\"{body}") } },
        "size": 10,
        "timeout": "1ms",
    }))
    .expect("parse_request");
    let starved = idx.search(&impossible).await.unwrap();
    assert!(
        starved.timed_out,
        "a 1ms budget against a 36 000-clause cross-product must report \
         timed_out, not silently run to completion"
    );
    // Bounded must not mean silently wrong: partial results are a SUBSET.
    assert!(
        res.total.value <= DOCS as u64,
        "over-counting: {} > {DOCS}",
        res.total.value
    );

    // Same query, ample budget: bounding the cross-product must not cost
    // correctness — every document really does hold every token.
    let generous = parse_request(&json!({
        "query": { "query_string": { "query": format!("\"{body}") } },
        "size": 10,
        "timeout": "60s",
    }))
    .expect("parse_request");
    let full = idx.search(&generous).await.unwrap();
    assert!(!full.timed_out, "60s is ample for this corpus");
    assert_eq!(
        full.total.value, DOCS as u64,
        "the capped path must still find every matching document"
    );
}

/// Floor cost of `req` against `idx`, query cache cleared before every run.
///
/// `query_cache` is keyed on `(query_body_hash, dataset_version)` and holds
/// the finished `SearchResult`, so re-running an identical request otherwise
/// measures a DashMap lookup and nothing else. Without the clear an earlier
/// version of this measurement reported ~5 µs for every shape on BOTH sides of
/// the fix — one real execution followed by four cache hits.
///
/// Best-of-5: the floor is the shape's real cost, and a scheduler blip can
/// only ever make a run look SLOWER, never faster.
async fn floor_ns(idx: &std::sync::Arc<xerj_engine::Index>, req: &SearchRequest) -> (u128, u64) {
    let warm = idx.search(req).await.unwrap();
    let mut best = u128::MAX;
    for _ in 0..5 {
        idx.query_cache.clear();
        let t = std::time::Instant::now();
        let r = idx.search(req).await.unwrap();
        best = best.min(t.elapsed().as_nanos());
        assert_eq!(r.total.value, warm.total.value, "runs must agree");
    }
    (best, warm.total.value)
}

/// A `query_string` whose text the standard analyzer reduces to NOTHING —
/// pure punctuation — can match no document, on any path: the projection is a
/// disjunction with zero clauses and the stored-doc scan's `QueryString` arm
/// returns `false` the instant its token set is empty.
///
/// Routing that shape to the stored-doc scan (because "the projection
/// declined") made the query that matches nothing pay for a full O(corpus)
/// walk.
///
/// The comparator is a query on the SAME index that provably DOES take that
/// walk — `match` with `operator: and`, which `is_doc_scan_query` routes to
/// the stored section — so the assertion is machine-relative and needs no
/// absolute budget. `match_all` is deliberately NOT the comparator: it has its
/// own bounded-scan fast path and is cheaper than one full walk, which is what
/// made an earlier version of this test fail against the FIXED code.
///
/// MEASURED, release, 20 000 documents in ONE segment, best of 5, query cache
/// cleared before every run — see the commit message for the numbers.
#[tokio::test]
async fn zero_token_query_string_does_not_scan_the_corpus() {
    // `+++` survives the Lucene lowerer as an opaque `QueryString` (the
    // unterminated quote is what stops it becoming a `Match`/`Bool` tree), and
    // the standard analyzer reduces it to zero tokens. Pin the shape: if the
    // parser ever lowers it, this test stops covering the arm it names.
    let zero_token = search(opaque_qs("+++"));
    assert!(
        matches!(zero_token.query, QueryNode::QueryString { .. }),
        "the test needs an opaque QueryString node; got {:?}",
        zero_token.query
    );
    // Known stored-doc scan over the same corpus: per-token AND semantics
    // exist only on the doc-scan path, so `is_doc_scan_query` sends it there.
    let known_scan = search(json!({
        "match": { "alpha": { "query": "body text", "operator": "and" } }
    }));

    let dir = TempDir::new().unwrap();
    let engine = make_single_segment_engine(&dir);
    engine.create_index("punct", Schema::empty()).unwrap();
    let idx = engine.get_index("punct").unwrap();

    const DOCS: usize = 20_000;
    for d in 0..DOCS {
        idx.index_document(
            Some(format!("d{d}")),
            json!({ "alpha": format!("body text {d}"), "beta": "more words here" }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    assert_eq!(
        idx.stats().await.segment_count,
        1,
        "one segment, so the comparator walks exactly the documents the \
         zero-token query would have walked"
    );

    let (zero_ns, zero_total) = floor_ns(&idx, &zero_token).await;
    let (scan_ns, scan_total) = floor_ns(&idx, &known_scan).await;

    assert_eq!(zero_total, 0, "zero tokens can match nothing");
    assert_eq!(
        scan_total, DOCS as u64,
        "the comparator must really walk the corpus"
    );

    eprintln!(
        "zero-token query_string: {:.3}ms   full stored scan: {:.3}ms   ({DOCS} docs, 1 segment)",
        zero_ns as f64 / 1e6,
        scan_ns as f64 / 1e6
    );

    // An order of magnitude of headroom on this machine. Demanding only 4×
    // keeps the guard meaningful on a runner where the fixed per-request
    // overhead is a larger share of the total.
    assert!(
        zero_ns * 4 < scan_ns,
        "a `query_string` that matches NOTHING cost {:.3}ms against {:.3}ms \
         for a query that really does walk all {DOCS} documents — it is doing \
         the full stored-doc scan instead of returning empty",
        zero_ns as f64 / 1e6,
        scan_ns as f64 / 1e6
    );
}

/// The zero-token split must not weaken the cross-product fallback: a
/// `query_string` that declines for the OTHER reason — too many
/// `tokens × fields` clauses — still has to be answered by the stored-doc
/// scan, or every one of its matches disappears.
#[tokio::test]
async fn over_cap_query_string_still_reaches_the_stored_doc_scan() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("overcap", Schema::empty()).unwrap();
    let idx = engine.get_index("overcap").unwrap();

    // 40 fields × 200 tokens = 8 000 clauses, past MAX_QS_CROSS_PRODUCT
    // (4 096), so the projection returns `None` — the same `None` the
    // zero-token shape returns, and the one that still needs the scan.
    const FIELDS: usize = 40;
    const TOKENS: usize = 200;
    const DOCS: usize = 12;
    let body: String = (0..TOKENS).map(|t| format!("tok{t} ")).collect::<String>();
    for d in 0..DOCS {
        let mut doc = serde_json::Map::new();
        for f in 0..FIELDS {
            doc.insert(format!("f{f}"), json!(body.clone()));
        }
        idx.index_document(Some(format!("d{d}")), Value::Object(doc))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    let r = idx.search(&search(opaque_qs(body.trim()))).await.unwrap();
    assert_eq!(
        r.total.value,
        DOCS as u64,
        "an over-cap `query_string` declines the postings path and MUST fall \
         through to the stored-doc scan; {} of {DOCS} documents were dropped",
        DOCS as u64 - r.total.value
    );
}

/// Undeclared response-value change, now pinned.
///
/// `prune_missing_should_fields` fires for ANY should-only bool of plain
/// terms, which includes an ordinary two-clause `match` disjunction — a shape
/// the field-less `query_string` work never mentions. On a heterogeneous
/// corpus that moved `max_score` (2.0986123 -> 1.3996884 as first measured);
/// `hits.total` and every per-hit `_score` were byte-identical.
///
/// The new value is the correct one, and this test is the definition rather
/// than a pinned constant: ES documents `max_score` as the highest `_score`
/// among the matching documents, so a `max_score` no returned hit can reach is
/// wrong by construction. Pre-change it came from `scored_max_bits` — the
/// brute stored-doc scorer's population max — while the hits themselves were
/// scored by the FTS postings path. Two scorers, two scales, and `max_score`
/// took the larger: the field-lacking segment was rejected by the
/// all-fields-present gate and re-scored by the brute scan, which is exactly
/// what the prune stops happening.
#[tokio::test]
async fn should_only_bool_max_score_never_exceeds_the_top_hit() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("scores", Schema::empty()).unwrap();
    let idx = engine.get_index("scores").unwrap();

    // Heterogeneous by construction: the first four documents are flushed
    // before `gamma` exists, so that segment has no `gamma` FTS side-car and
    // the disjunction's `gamma` clause is the one the prune drops.
    for i in 0..4 {
        idx.index_document(
            Some(format!("old{i}")),
            json!({ "alpha": format!("apple pie {i}") }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    for i in 0..3 {
        idx.index_document(
            Some(format!("new{i}")),
            json!({ "alpha": "apple tart", "gamma": format!("apple sauce {i}") }),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();

    let req = search(json!({
        "bool": { "should": [
            { "match": { "alpha": "apple" } },
            { "match": { "gamma": "apple" } },
        ]}
    }));
    let r = idx.search(&req).await.unwrap();

    assert_eq!(r.total.value, 7, "every document holds `apple` somewhere");
    assert_eq!(r.hits.len(), 7, "size:100 — every hit is on the page");

    let top = r
        .hits
        .iter()
        .map(|h| h.score)
        .fold(f32::NEG_INFINITY, f32::max);
    let max_score = r.max_score.expect("a scored query reports max_score");
    let mut scores: Vec<f32> = r.hits.iter().map(|h| h.score).collect();
    scores.sort_by(|a, b| b.partial_cmp(a).unwrap());
    eprintln!(
        "total={} max_score={max_score} top_hit={top} scores={scores:?}",
        r.total.value
    );
    assert!(
        (max_score - top).abs() <= f32::EPSILON * top.abs().max(1.0),
        "max_score {max_score} is not the highest returned _score {top} — ES \
         defines max_score as the maximum `_score` of the matching documents, \
         so a value no hit can reach is unreachable by definition"
    );
    // Guard the other direction too: a max_score BELOW the top hit would be
    // just as wrong, and would be the natural regression if the population
    // max were ever narrowed to a page.
    assert!(max_score >= top, "max_score {max_score} < top hit {top}");
}

/// The cap must not change results for ordinary (within-cap) queries.
#[tokio::test]
async fn field_less_query_string_within_the_cap_is_unchanged() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("small", Schema::empty()).unwrap();
    let idx = engine.get_index("small").unwrap();

    idx.index_document(
        Some("a".into()),
        json!({"title": "alpha", "body": "needle"}),
    )
    .await
    .unwrap();
    idx.index_document(Some("b".into()), json!({"title": "needle", "body": "beta"}))
        .await
        .unwrap();
    idx.index_document(Some("c".into()), json!({"title": "gamma", "body": "delta"}))
        .await
        .unwrap();
    idx.flush().await.unwrap();

    let r = idx.search(&search(opaque_qs("needle"))).await.unwrap();
    assert_eq!(
        r.total.value, 2,
        "`needle` is in `body` of one doc and `title` of another"
    );
}

//! Issue #1750: a `range` query must match a document when ANY one of a
//! multi-valued field's values is in range — Lucene's per-value semantics, and
//! what Elasticsearch 8.13.4 returns for the same requests.
//!
//! ROOT CAUSE (two independent defects):
//!
//! 1. The `_source` matcher (`doc_matches_query_typed`'s `Range` arm) compared
//!    the whole array. `json_compare` has no array arm, so it fell back to the
//!    serialized text (`["alpha","mid"]`, `[22,8080]`) and compared that
//!    lexicographically: `'['` sorts after every digit and before every
//!    lowercase letter, so an array passed any numeric/date lower bound, failed
//!    any upper bound, and failed a keyword `gte "m"` — whatever its elements.
//!    Every flushed segment reaches this matcher for a multi-valued field
//!    (`build_doc_value_columns` emits no column for it), as do memtable
//!    keyword/date/ip ranges.
//! 2. The memtable numeric range fast paths (`doc_values_range_query`, and the
//!    `try_shortcut_count` count over `for_each_numeric_value`) read a column
//!    that keeps only an array's FIRST element, with no `array_fields`
//!    bailout — unlike the `term` paths (#423) and the fused bool walk.
//!
//! Every case runs before and after a flush, at `size: 0` (the count
//! shortcuts) and `size: 10` (the hit path), so each path is pinned.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// The #1750 reproduction, plus an `ip` field and two negative documents.
async fn seed(engine: &Engine) {
    let mut schema = Schema::empty();
    for (name, ty) in [
        ("tags", FieldType::Keyword),
        ("ports", FieldType::Long),
        ("seen", FieldType::Date),
        ("addr", FieldType::Ip),
    ] {
        schema.fields.push(FieldConfig::new(name, ty));
    }
    engine.create_index("events", schema).expect("create");
    let idx = engine.get_index("events").expect("get");
    let docs = [
        (
            "1",
            json!({"tags": ["alpha", "mid"], "ports": [22, 8080],
                   "seen": ["2020-01-01", "2024-06-01"],
                   "addr": ["10.0.0.1", "192.168.1.7"]}),
        ),
        (
            "2",
            json!({"tags": "mid", "ports": 443, "seen": "2024-01-01", "addr": "10.0.0.9"}),
        ),
        (
            "3",
            json!({"tags": "zeta", "ports": 5, "seen": ["2030-01-01", "2021-06-01"],
                   "addr": "172.16.0.1"}),
        ),
        // Every element below any bound used below: must never match a
        // lower-bounded range (the old matcher admitted every array there).
        (
            "4",
            json!({"tags": ["aa", "ab"], "ports": [1, 2],
                   "seen": ["1990-01-01", "1991-01-01"], "addr": ["1.1.1.1", "1.1.1.2"]}),
        ),
    ];
    for (id, doc) in docs {
        idx.index_document(Some(id.to_string()), doc)
            .await
            .expect("index");
    }
}

async fn ids(engine: &Engine, range: Value) -> (u64, u64, Vec<String>) {
    let idx = engine.get_index("events").expect("get");
    let count = idx
        .search(&parse_request(&json!({"query": {"range": range.clone()}, "size": 0})).unwrap())
        .await
        .expect("count search")
        .total
        .value;
    let res = idx
        .search(&parse_request(&json!({"query": {"range": range}, "size": 10})).unwrap())
        .await
        .expect("hit search");
    let mut ids: Vec<String> = res.hits.iter().map(|h| h.id.clone()).collect();
    ids.sort();
    (count, res.total.value, ids)
}

/// `(range body, expected ids)`. Expectations are Elasticsearch 8.13.4's for
/// the #1750 requests; the rest follow the same per-value rule.
fn cases() -> Vec<(Value, Vec<&'static str>)> {
    vec![
        // #1750 verbatim: ES counts 2, 1, 1.
        (json!({"tags": {"gte": "m", "lt": "n"}}), vec!["1", "2"]),
        (json!({"ports": {"gte": 8000, "lte": 9000}}), vec!["1"]),
        (
            json!({"seen": {"gte": "2021-01-01", "lt": "2023-01-01"}}),
            vec!["3"],
        ),
        // Bounds are not split across elements: doc 1 has a value below and
        // a value above this window, but none inside it.
        (json!({"ports": {"gt": 22, "lt": 443}}), vec![]),
        (
            json!({"seen": {"gte": "2021-01-01", "lt": "2024-01-01"}}),
            vec!["3"],
        ),
        // Lower bound only: doc 4's values are all below it.
        (json!({"seen": {"gte": "2024-05-01"}}), vec!["1", "3"]),
        (json!({"ports": {"gte": 100}}), vec!["1", "2"]),
        // Upper bound only: the old matcher never admitted an array here.
        (json!({"ports": {"lte": 5}}), vec!["3", "4"]),
        (json!({"seen": {"lt": "2000-01-01"}}), vec!["4"]),
        (
            json!({"addr": {"gte": "192.168.0.0", "lte": "192.168.255.255"}}),
            vec!["1"],
        ),
    ]
}

async fn assert_cases(engine: &Engine, phase: &str) {
    for (range, want) in cases() {
        let (count, total, got) = ids(engine, range.clone()).await;
        assert_eq!(
            got, want,
            "#1750 [{phase}] range {range}: hit ids (size:10) disagree"
        );
        assert_eq!(
            total,
            want.len() as u64,
            "#1750 [{phase}] range {range}: hits.total (size:10)"
        );
        assert_eq!(
            count,
            want.len() as u64,
            "#1750 [{phase}] range {range}: hits.total (size:0 count path)"
        );
    }
}

#[tokio::test]
async fn range_matches_any_element_of_a_multi_valued_field() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine).await;

    assert_cases(&engine, "buffered").await;

    engine
        .get_index("events")
        .unwrap()
        .refresh()
        .await
        .expect("refresh");
    assert_cases(&engine, "flushed").await;
}

/// `filter` aggregation with a `range` clause counts like the query does
/// (aggs.rs `doc_matches_filter` read only the first value).
#[tokio::test]
async fn filter_agg_range_matches_any_element() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed(&engine).await;
    let idx = engine.get_index("events").unwrap();

    for phase in ["buffered", "flushed"] {
        if phase == "flushed" {
            idx.refresh().await.expect("refresh");
        }
        let req = parse_request(&json!({
            "size": 0,
            "aggs": {
                "p": {"filter": {"range": {"ports": {"gte": 8000, "lte": 9000}}}},
                "s": {"filter": {"range": {"seen": {"gte": "2021-01-01", "lt": "2023-01-01"}}}}
            }
        }))
        .unwrap();
        let res = idx.search(&req).await.expect("agg search");
        let aggs = res.aggs.as_ref().expect("aggs present");
        assert_eq!(
            aggs["p"]["doc_count"],
            json!(1),
            "#1750 [{phase}] filter agg ports 8000..9000: {aggs}"
        );
        assert_eq!(
            aggs["s"]["doc_count"],
            json!(1),
            "#1750 [{phase}] filter agg seen 2021..2023: {aggs}"
        );
    }
}

//! RC4 Wave-2 Stream D — storage/durability hardening regressions.
//!
//! Item 15: transient GET 404 under merge (version map repointed to the
//!          merged segment before the snapshot publish).
//! Item 14: delete tombstones must survive merges (carry-forward) now that
//!          the WAL pin is released once a tombstone is segment-resident.

use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// Item 15 — GET must never 404 an existing doc while a forcemerge
/// publishes.  Live repro pre-fix: 47/15072 GETs returned 404 in the
/// ~300 ms window between the merge task's version-map repoint and
/// `apply_merge`'s snapshot swap (8×25k docs, HTTP).  In-process the
/// hammer is much faster than HTTP, so even the smaller window here
/// catches the regression reliably.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn get_document_never_404s_during_forcemerge() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("m15", Schema::empty()).unwrap();
    let idx = engine.get_index("m15").unwrap();

    // 6 flushed batches → 6+ segments, one probe id per batch.
    let mut probe_ids = Vec::new();
    for b in 0..6 {
        for i in 0..1500 {
            let id = format!("d{b}_{i}");
            idx.index_document(
                Some(id),
                json!({"title": format!("doc {b}/{i}"), "body": "lorem ipsum dolor sit amet", "n": b * 1500 + i}),
            )
            .await
            .unwrap();
        }
        idx.flush().await.unwrap();
        probe_ids.push(format!("d{b}_7"));
    }

    // Sanity: every probe resolves before the merge.
    for id in &probe_ids {
        assert!(
            idx.get_document(id).await.unwrap().is_some(),
            "probe {id} must exist pre-merge"
        );
    }

    // Hammer GETs concurrently with the forcemerge.
    let stop = Arc::new(AtomicBool::new(false));
    let misses = Arc::new(AtomicU64::new(0));
    let total = Arc::new(AtomicU64::new(0));
    let hammer = {
        let idx = Arc::clone(&idx);
        let stop = Arc::clone(&stop);
        let misses = Arc::clone(&misses);
        let total = Arc::clone(&total);
        let ids = probe_ids.clone();
        tokio::spawn(async move {
            while !stop.load(Ordering::Relaxed) {
                for id in &ids {
                    match idx.get_document(id).await {
                        Ok(Some(_)) => {}
                        Ok(None) => {
                            misses.fetch_add(1, Ordering::Relaxed);
                        }
                        Err(_) => {
                            misses.fetch_add(1, Ordering::Relaxed);
                        }
                    }
                    total.fetch_add(1, Ordering::Relaxed);
                }
                tokio::task::yield_now().await;
            }
        })
    };

    let merged = idx.force_merge(1).await.unwrap();
    assert!(merged > 0, "forcemerge must merge something");
    // Let the hammer overlap any post-merge publish work too.
    tokio::time::sleep(std::time::Duration::from_millis(200)).await;
    stop.store(true, Ordering::Relaxed);
    hammer.await.unwrap();

    let t = total.load(Ordering::Relaxed);
    let m = misses.load(Ordering::Relaxed);
    assert!(t > 0, "hammer must have run");
    assert_eq!(
        m, 0,
        "GET returned 404/error for existing docs during forcemerge ({m}/{t})"
    );

    // And everything still resolves after.
    for id in &probe_ids {
        assert!(
            idx.get_document(id).await.unwrap().is_some(),
            "probe {id} lost after merge"
        );
    }
}

/// Item 14 — with WAL pins released once tombstones are segment-resident,
/// a merge must CARRY the tombstones forward: the deleted doc stays dead
/// in live search AND across a restart, even after every pre-merge
/// segment (including the tombstone-only one) has been merged away and
/// the delete's WAL entry pruned.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn deleted_doc_stays_dead_through_merge_and_restart() {
    let dir = TempDir::new().unwrap();
    {
        let engine = make_engine(&dir);
        engine.create_index("m14", Schema::empty()).unwrap();
        let idx = engine.get_index("m14").unwrap();

        for b in 0..3 {
            for i in 0..50 {
                idx.index_document(Some(format!("k{b}_{i}")), json!({"v": i, "b": b}))
                    .await
                    .unwrap();
            }
            idx.flush().await.unwrap();
        }

        // Plain delete, never re-indexed.
        assert!(idx.delete_document("k0_7").await.unwrap());
        // Flush → maintenance persists the tombstone (tombstone-only
        // segment) and releases the WAL pin.
        idx.flush().await.unwrap();
        assert!(idx.get_document("k0_7").await.unwrap().is_none());

        // Merge everything — inputs (including the tombstone-only
        // segment) are removed; the tombstone must ride along.
        idx.force_merge(1).await.unwrap();
        assert!(
            idx.get_document("k0_7").await.unwrap().is_none(),
            "deleted doc resurrected in live search after merge"
        );
        assert!(
            idx.get_document("k0_8").await.unwrap().is_some(),
            "sibling doc lost after merge"
        );
        idx.flush().await.unwrap();
        drop(idx);
        drop(engine);
    }

    // Restart — the WAL delete entry is pruned; only the merged
    // segment's carried tombstone can keep the doc dead.
    let engine2 = make_engine(&dir);
    let idx2 = engine2.get_index("m14").unwrap();
    assert!(
        idx2.get_document("k0_7").await.unwrap().is_none(),
        "deleted doc resurrected after merge + restart (tombstone not carried forward)"
    );
    for probe in ["k0_8", "k1_7", "k2_49"] {
        assert!(
            idx2.get_document(probe).await.unwrap().is_some(),
            "live doc {probe} lost after merge + restart"
        );
    }
}

//! #1812: `regexp` on a `keyword` field must honor `case_insensitive`.
//!
//! ES matches `regexp` against the RAW keyword value (case-SENSITIVE by
//! default); `case_insensitive: true` folds both sides instead.  XERJ's
//! `Regexp` AST node dropped the flag entirely, so
//! `regexp:{k:{value:"HEL+O.*",case_insensitive:true}}` on `"Hello World"`
//! returned 0 (wrong — ES returns the doc).
//!
//! Both the buffered (memtable) and flushed (segment) paths are asserted
//! pre- and post-`refresh`: the segment path answers via a dictionary
//! expansion pre-filter (`regexp_segment_expansion` /
//! `build_regexp_prefilter_cached`) that compiles the pattern itself, so a
//! fix only in the doc-scan arm would split-brain across a flush.

use std::sync::Arc;

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// Index two keyword docs (capitalized + lowercase) and return the index.
async fn setup_docs(engine: &Engine) -> Arc<Index> {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("k", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(Some("d1".to_string()), json!({ "k": "Hello World" }))
        .await
        .expect("index");
    idx.index_document(Some("d2".to_string()), json!({ "k": "hello there" }))
        .await
        .expect("index");
    idx
}

async fn hits(idx: &Index, query: serde_json::Value) -> u64 {
    let req = parse_request(&json!({ "query": query, "size": 0 })).expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// FAIL-BEFORE (#1812): the flag was dropped at parse time, so this matched
/// 0 docs.  ES returns 2 (both keyword values full-match "hel+o.*", folded).
#[tokio::test]
async fn regexp_case_insensitive_true_folds_both_paths() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    let q = json!({ "regexp": { "k": { "value": "HEL+O.*", "case_insensitive": true } } });

    // Buffered (memtable) path.
    let pre = hits(&idx, q.clone()).await;
    // Flushed (segment) path — exercised through the dictionary expansion.
    idx.refresh().await.expect("refresh");
    let post = hits(&idx, q).await;

    assert_eq!(
        pre, 2,
        "memtable: case_insensitive regexp must match both docs"
    );
    assert_eq!(
        pre, post,
        "flush-invariant: memtable={pre} vs segment={post} disagree"
    );
    assert_eq!(
        post, 2,
        "segment: case_insensitive regexp must match both docs"
    );
}

/// Explicit `case_insensitive: false` stays ES-correct case-SENSITIVE.
#[tokio::test]
async fn regexp_case_insensitive_false_is_case_sensitive() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    // "HEL+O.*" full-matches neither value byte-wise.
    let q_upper = json!({ "regexp": { "k": { "value": "HEL+O.*", "case_insensitive": false } } });
    // "hel+o.*" full-matches only the lowercase doc byte-wise.
    let q_lower = json!({ "regexp": { "k": { "value": "hel+o.*", "case_insensitive": false } } });

    let pre_upper = hits(&idx, q_upper.clone()).await;
    let pre_lower = hits(&idx, q_lower.clone()).await;
    idx.refresh().await.expect("refresh");
    let post_upper = hits(&idx, q_upper).await;
    let post_lower = hits(&idx, q_lower).await;

    assert_eq!(
        pre_upper, 0,
        "memtable: HEL+O.* must not match capitalized values"
    );
    assert_eq!(
        pre_lower, 1,
        "memtable: hel+o.* must match only the lowercase doc"
    );
    assert_eq!(pre_upper, post_upper, "flush-invariant (upper)");
    assert_eq!(pre_lower, post_lower, "flush-invariant (lower)");
    assert_eq!(
        post_upper, 0,
        "segment: HEL+O.* must not match capitalized values"
    );
    assert_eq!(
        post_lower, 1,
        "segment: hel+o.* must match only the lowercase doc"
    );
}

/// Omitted parameter defaults to `false` (shorthand and expanded forms).
#[tokio::test]
async fn regexp_omitted_case_insensitive_defaults_false() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    let q_upper = json!({ "regexp": { "k": "HEL+O.*" } });
    let q_lower = json!({ "regexp": { "k": "hel+o.*" } });

    let pre_upper = hits(&idx, q_upper.clone()).await;
    let pre_lower = hits(&idx, q_lower.clone()).await;
    idx.refresh().await.expect("refresh");
    let post_upper = hits(&idx, q_upper).await;
    let post_lower = hits(&idx, q_lower).await;

    assert_eq!(pre_upper, 0, "shorthand HEL+O.* defaults to case-sensitive");
    assert_eq!(
        pre_lower, 1,
        "shorthand hel+o.* matches only the lowercase doc"
    );
    assert_eq!(pre_upper, post_upper, "flush-invariant (upper)");
    assert_eq!(pre_lower, post_lower, "flush-invariant (lower)");
}

/// The flag must not change matching for values it shouldn't reach: a
/// case-insensitive pattern that only matches via folding must NOT match a
/// non-string value path, and an invalid pattern still matches nothing.
#[tokio::test]
async fn regexp_case_insensitive_invalid_pattern_matches_nothing() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let idx = setup_docs(&engine).await;

    let q = json!({ "regexp": { "k": { "value": "([", "case_insensitive": true } } });
    assert_eq!(
        hits(&idx, q.clone()).await,
        0,
        "invalid pattern matches nothing (memtable)"
    );
    idx.refresh().await.expect("refresh");
    assert_eq!(
        hits(&idx, q).await,
        0,
        "invalid pattern matches nothing (segment)"
    );
}

//! Issue #382 (end-to-end): the schema-evolution throttle must not suppress the
//! evolve call a value-shape transition needs.
//!
//! The single-doc ingest path caches a hash of each document's shape
//! (`hash_all_field_names`) and skips `evolve_schema_from_doc` while it is
//! unchanged, re-checking only every ~100 docs. A `<base>_chunks` companion
//! (`base` declared `dense_vector`) first seen as a rectangular numeric
//! multi-vector `[[..]]` is *refused* a keyword mapping; when the SAME key later
//! arrives as a flat string array it is a legitimately-new keyword field. While
//! the throttle hashed an array as one opaque leaf, both documents hashed
//! identically, the evolve was skipped, and a `term` query answered 0 hits for
//! up to ~100 docs (self-healing on throttle expiry — corpus-size-dependent,
//! exactly the class of bug the unit hash tests pin one layer down).
//!
//! Fixed by recursing the throttle fingerprint into array elements, so the
//! array-of-numbers -> array-of-strings transition changes the hash and forces
//! the evolve on the very next document. This test drives the real ingest +
//! search path (not the hash primitive) to guard the observable symptom.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(q: Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request")
}

async fn hit_ids(idx: &Index, q: Value) -> Vec<String> {
    idx.search(&req(q))
        .await
        .unwrap()
        .hits
        .iter()
        .map(|h| h.id.clone())
        .collect()
}

/// A `<base>_chunks` companion (base declared `dense_vector`) first seen as a
/// multi-vector `[[..numbers..]]` is refused a keyword mapping; when it later
/// arrives as a flat string array under the SAME key, the schema-evolution
/// throttle must let the evolve through so the string registers and is
/// queryable immediately — not suppress it for ~100 docs (#382).
#[tokio::test]
async fn refused_multivector_companion_then_string_array_is_searchable_immediately() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    // Declare `passages` dense_vector so `passages_chunks` is recognised as its
    // (refused) multi-vector companion — the value-shape refusal #382 is about.
    let mut schema = Schema::empty();
    let mut vec_field = FieldConfig::new("passages", FieldType::Vector);
    vec_field.options.dimensions = Some(3);
    schema.fields.push(vec_field);
    engine.create_index("mv", schema).unwrap();
    let idx = engine.get_index("mv").unwrap();

    // Doc "a": passages_chunks as a rectangular numeric multi-vector -> refused a
    // keyword FieldConfig, and it seeds the throttle's cached shape fingerprint.
    idx.index_document(
        Some("a".into()),
        json!({ "passages_chunks": [[0.1, 0.2, 0.3]] }),
    )
    .await
    .unwrap();

    // Doc "b": passages_chunks now a FLAT STRING array (not a multi-vector) ->
    // evolution wants to register it as a keyword. Same key, different element
    // shape: array-of-numbers -> array-of-strings, the transition the opaque-leaf
    // hash could not see.
    idx.index_document(
        Some("b".into()),
        json!({ "passages_chunks": ["searchable-tenant"] }),
    )
    .await
    .unwrap();

    // The string under the once-refused key must be found — pre-flush (memtable)
    // and post-flush (segment). On the pre-fix throttle both docs hashed the same
    // (array = opaque leaf), the evolve was skipped, and this returned {} for up
    // to 100 docs.
    let q = json!({ "term": { "passages_chunks": "searchable-tenant" } });
    assert_eq!(
        hit_ids(&idx, q.clone()).await,
        vec!["b".to_string()],
        "PRE-flush: a string array under a once-refused multi-vector companion must \
         register immediately, not stay throttle-suppressed (#382)"
    );

    idx.flush().await.unwrap();
    assert_eq!(
        hit_ids(&idx, q).await,
        vec!["b".to_string()],
        "POST-flush: the once-refused companion's string value stays searchable"
    );
}

//! Regression test for #179 — a scored FTS search over an index that has
//! ghosts (a delete or an overwrite anywhere in its history) must still
//! return the true global top-k, and the bounded hit collector must stay
//! O(cap) while doing it.
//!
//! ## What #179 was
//!
//! `deletes_present` (any flushed tombstone, or `ghost_events() > 0`) forces
//! the per-segment FTS cap to `usize::MAX`, so `search_bounded` hands the
//! merge a `seg_hits` list spanning EVERY physical match — the cap can no
//! longer bound it, because with ghosts a top-`cap`-by-score slice could be
//! partly tombstoned and underfill the page.  `ghost_events()` is monotonic
//! and index-global, so after a single delete/overwrite ANYWHERE this branch
//! is permanent for every later query.
//!
//! Before the fix the cross-segment merge only bounded itself when the cap
//! bounded `seg_hits`: the fill-up segment left `page_worst == None` for its
//! whole run, so it hydrated `_source` for every one of the O(matches) hits
//! and grew `all_hits` to O(matches) before the end-of-run trim.  On any
//! mature index (one that had ever seen a delete) a `size:5` scored query
//! therefore paid O(total_matches) source parses and memory — the ~8×
//! read regression this test guards against.
//!
//! ## What this test can and cannot see
//!
//! The public API exposes no "documents hydrated" counter, so the O(cap)
//! bound itself is not directly observable here (documented limitation).
//! What IS observable, and what the pre-fix path would only satisfy at
//! O(matches) cost, is the *contract* the bound must preserve while it trims:
//! on a deliberately large match set (well above the 256-doc cap) with ghosts
//! present, a small `size` must still return the exact global top-k by score,
//! must exclude deleted/superseded ghosts, and must not move when a
//! `highlight` block is added (#177) or when the page size changes.  The bound
//! itself is enforced structurally in `index.rs` by the incremental
//! `page_worst` early-out plus the 2×cap eager trim; these assertions pin the
//! behaviour that bound must not break.

use serde_json::json;
use std::sync::Arc;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// A weak (low-BM25) body: a single buried occurrence of the term in a long
/// field.  The field GROWS with `i`, so BM25 length-normalisation gives every
/// weak doc a DISTINCT, strictly decreasing score — all far below the short
/// strong docs.  The distinct scores matter: they are what let the collector's
/// strict early-out fire at the cap instead of hydrating the whole match set.
fn weak_body(i: usize) -> String {
    let pad = "pad ".repeat(40 + i * 3);
    format!("{pad} quicklist {pad}")
}

fn match_body(size: usize, highlight: bool) -> xerj_query::ast::SearchRequest {
    let mut b = json!({
        "size": size,
        "query": {"match": {"body": "quicklist"}}
    });
    if highlight {
        b.as_object_mut()
            .unwrap()
            .insert("highlight".into(), json!({"fields": {"body": {}}}));
    }
    parse_request(&b).expect("parse_request")
}

/// `(id, score)` page fingerprint.
fn page(hits: &[xerj_query::Hit]) -> Vec<(String, f32)> {
    hits.iter().map(|h| (h.id.clone(), h.score)).collect()
}

/// Build the corpus: a big low-scoring segment (`weak` docs, distinct
/// decreasing scores) plus a small high-scoring segment (5 `strong` docs whose
/// members are the true, tie-free top-5).  `weak` is chosen > 256 by callers so
/// the match set exceeds the collector cap.
async fn build_corpus(idx: &Arc<Index>, weak: usize) {
    // ── Segment 0: many weak matches, distinct decreasing scores ─────────
    for i in 0..weak {
        idx.index_document(Some(format!("weak{i:03}")), json!({"body": weak_body(i)}))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    // ── Segment 1: 5 strong, strictly-decreasing-score matches ───────────
    // Short field + repeated term → high BM25.  Strictly decreasing term
    // frequency keeps the top-5 tie-free, so it has exactly one right answer.
    for i in 0..5 {
        let body = "quicklist ".repeat(10 - i) + &"filler ".repeat(i * 4);
        idx.index_document(Some(format!("strong{i}")), json!({"body": body}))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();
}

/// The core #179 guard: a large match set (> cap) with ghosts present,
/// `size:5` must return the exact global top-5, exclude the ghosts, and stay
/// #177-stable.
#[tokio::test]
async fn size5_returns_global_top5_under_ghosts_on_large_matchset() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("g1", Schema::empty()).unwrap();
    let idx = engine.get_index("g1").unwrap();

    // 360 weak + 5 strong = 365 physical matches — comfortably over the 256
    // collector cap that `deletes_present` pins the query to.
    build_corpus(&idx, 360).await;

    // ── Introduce ghosts ─────────────────────────────────────────────────
    // A DELETE (tombstone) and an OVERWRITE (superseded old version) — both
    // land in already-flushed segment 0, so their stale copies are ghosts the
    // scan must skip, and either one alone flips `deletes_present` (hence
    // `fts_cap == usize::MAX`) permanently for every query below.
    assert!(
        idx.delete_document("weak000").await.unwrap(),
        "weak000 should have existed to delete"
    );
    // Overwrite weak001: its live version moves to the memtable, its segment-0
    // copy becomes a superseded ghost that the scan must not double-count.
    idx.index_document(Some("weak001".into()), json!({"body": weak_body(1)}))
        .await
        .unwrap();

    // Live matches: 360 weak - 1 deleted = 359 (weak001 overwritten, still
    // matches) + 5 strong = 364.
    let expected_total: u64 = 364;

    // ── Ground truth: full materialisation, then the top 5 ───────────────
    let full = idx.search(&match_body(500, false)).await.unwrap();
    assert_eq!(
        full.total.value, expected_total,
        "live total wrong under ghosts (deleted/superseded copies leaked into the count)"
    );
    let mut truth = page(&full.hits);
    truth.truncate(5);
    assert!(
        truth.iter().all(|(id, _)| id.starts_with("strong")),
        "sanity: the 5 short docs must be the global top-5, got {truth:?}"
    );
    assert!(
        full.hits.iter().all(|h| h.id != "weak000"),
        "deleted doc weak000 leaked into results"
    );
    assert!(
        full.hits.iter().filter(|h| h.id == "weak001").count() <= 1,
        "overwritten doc weak001 returned as a duplicate (stale ghost not skipped)"
    );

    // ── The #179 assertion: the bounded `size:5` page == the true top-5 ──
    // On the pre-fix code this same answer required hydrating all 364 live
    // matches; the bound must produce it while trimming to O(cap).
    let small = idx.search(&match_body(5, false)).await.unwrap();
    assert_eq!(
        small.total.value, expected_total,
        "size:5 reported a different total than the full run under ghosts"
    );
    assert_eq!(
        page(&small.hits),
        truth,
        "size:5 page is not the global top-5 under ghosts"
    );

    // ── #177 must still hold on the deletes-present path ─────────────────
    let lit = idx.search(&match_body(5, true)).await.unwrap();
    assert_eq!(
        page(&small.hits),
        page(&lit.hits),
        "adding `highlight` changed the page under ghosts: without={:?} with={:?}",
        page(&small.hits),
        page(&lit.hits)
    );
    for h in &lit.hits {
        let frags = h
            .highlight
            .as_ref()
            .and_then(|m| m.get("body"))
            .unwrap_or_else(|| panic!("hit {} has no `body` highlight", h.id));
        assert!(
            frags.iter().any(|f| f.contains("<em>quicklist</em>")),
            "hit {} fragments do not mark the matched term: {frags:?}",
            h.id
        );
    }
}

/// The #179 re-expand path, exercised end to end: a page that reaches PAST the
/// strong docs and INTO the big, truncated, ghost-bearing segment.  Under the
/// observer fix that segment is scanned bounded (heap = cap) but re-expands
/// uncapped because it truncated (`seg_total > cap`) AND holds ghosts
/// (`dead_matches > 0`), so the walk still sees every live candidate.  Without
/// the re-expand the top-`cap`-by-score slice — whose highest members here are
/// the very docs that were deleted/overwritten — would drop live hits and the
/// page would be wrong.  Asserted black-box against a full-materialisation
/// ground truth, so it holds whatever the exact BM25 order turns out to be.
#[tokio::test]
async fn page_reaching_into_truncated_ghost_segment_is_exact() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("g3", Schema::empty()).unwrap();
    let idx = engine.get_index("g3").unwrap();

    // 360 weak (distinct DECREASING scores: weak000 is the highest-scoring
    // weak doc) + 5 strong.  Match set 365 > 256 cap.
    build_corpus(&idx, 360).await;

    // Ghost the TWO highest-scoring weak docs — exactly the ones a bounded
    // top-cap slice keeps first, so a broken bound would surface them.
    assert!(idx.delete_document("weak000").await.unwrap());
    idx.index_document(Some("weak001".into()), json!({"body": weak_body(1)}))
        .await
        .unwrap();

    let expected_total: u64 = 364;

    // Ground truth: full materialisation.
    let full = idx.search(&match_body(500, false)).await.unwrap();
    assert_eq!(
        full.total.value, expected_total,
        "live total wrong under ghosts"
    );

    // Pages that reach well into the weak segment must equal the ground-truth
    // prefix — this is the assertion the re-expand exists to satisfy.
    for size in [10usize, 25, 50, 100] {
        let mut truth = page(&full.hits);
        truth.truncate(size);
        let r = idx.search(&match_body(size, false)).await.unwrap();
        assert_eq!(
            r.total.value, expected_total,
            "size:{size} total drifted under ghosts"
        );
        assert_eq!(
            page(&r.hits),
            truth,
            "size:{size} page reaching into the truncated ghost segment != global order"
        );
        assert!(
            r.hits.iter().all(|h| h.id != "weak000"),
            "size:{size}: deleted weak000 leaked into the page"
        );
        assert!(
            r.hits.iter().filter(|h| h.id == "weak001").count() <= 1,
            "size:{size}: overwritten weak001 returned as a duplicate (stale ghost not skipped)"
        );
    }
}

/// Cap-independence must hold on the `deletes_present` path too: the top hit of
/// a `size:1` request is the top hit of a `size:200` request, unchanged by the
/// presence of ghosts.  This is the incremental `page_worst` doing its job — a
/// worst-kept score frozen at segment entry would let the fill-up segment's
/// arrival order leak into small pages.
#[tokio::test]
async fn top_hit_stable_across_page_sizes_under_ghosts() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("g2", Schema::empty()).unwrap();
    let idx = engine.get_index("g2").unwrap();

    build_corpus(&idx, 300).await;

    // One delete → `deletes_present` is now permanently true.
    assert!(idx.delete_document("weak100").await.unwrap());

    let deep = idx.search(&match_body(400, false)).await.unwrap();
    let expected_top = (deep.hits[0].id.clone(), deep.hits[0].score);
    assert_eq!(
        expected_top.0, "strong0",
        "sanity: strong0 is the global top hit"
    );

    for size in [1usize, 2, 5, 10, 50, 100] {
        let r = idx.search(&match_body(size, false)).await.unwrap();
        let got = (r.hits[0].id.clone(), r.hits[0].score);
        assert_eq!(
            got, expected_top,
            "size:{size} returned a different top hit under ghosts (bounded merge lost the global top-k)"
        );
    }
}

/// Stress guard for the re-expand fallback at scale: a big single segment
/// (well over the cap) whose HIGHEST-scoring doc is a ghost, so every page that
/// reaches the top must skip it via an uncapped re-expand and still return the
/// exact global order.  This is the large-match-set analogue of
/// `page_reaching_into_truncated_ghost_segment_is_exact`; it exists because the
/// bounded scan sheds the pre-#179 full-set sort/allocation here — the win that
/// grows with the match-set size — and this pins the correctness that shedding
/// must preserve.
#[tokio::test]
async fn large_single_segment_with_top_ghost_returns_exact_order() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("g4", Schema::empty()).unwrap();
    let idx = engine.get_index("g4").unwrap();

    // 1500 distinct-scoring matches in ONE segment; weak0000 is the top.
    let n = 1500usize;
    for i in 0..n {
        idx.index_document(Some(format!("weak{i:04}")), json!({"body": weak_body(i)}))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    // Delete the top-scorer (inside the kept top-cap → forces the re-expand)
    // and overwrite the runner-up (superseded ghost).
    assert!(idx.delete_document("weak0000").await.unwrap());
    idx.index_document(Some("weak0001".into()), json!({"body": weak_body(1)}))
        .await
        .unwrap();

    let full = idx.search(&match_body(500, false)).await.unwrap();
    assert_eq!(
        full.total.value,
        (n as u64) - 1,
        "live total wrong under a top ghost"
    );
    for size in [10usize, 50, 200] {
        let mut truth = page(&full.hits);
        truth.truncate(size);
        let r = idx.search(&match_body(size, false)).await.unwrap();
        assert_eq!(
            page(&r.hits),
            truth,
            "size:{size} order wrong with a top-scoring ghost"
        );
        assert!(
            r.hits.iter().all(|h| h.id != "weak0000"),
            "deleted top-scorer leaked"
        );
    }
}

//! RC4 blocker 11 regression: scroll + async-search contexts are TTL-swept.
//!
//! Before the fix, `Engine.scrolls` (each entry pinning a fully-hydrated
//! `Vec<Hit>`) and `Engine.async_searches` (each entry pinning a stored
//! response JSON) were only ever removed by an explicit client DELETE —
//! normal client behavior (open scrolls, never clear) grew both maps, and
//! therefore process RSS, without bound. The engine now mirrors the PIT
//! lifecycle: TTLs on every context, sweep helpers (run opportunistically
//! on open + by a background task), expiry enforced on access, and a hard
//! open-context cap at the API layer.

use std::time::{Duration, Instant};

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_engine::engine::ScrollContext;
use xerj_engine::Engine;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn scroll_ctx(expires_in: i64) -> ScrollContext {
    let now = Instant::now();
    let keep_alive = Duration::from_secs(60);
    let expires_at = if expires_in >= 0 {
        now + Duration::from_secs(expires_in as u64)
    } else {
        now - Duration::from_secs((-expires_in) as u64)
    };
    ScrollContext {
        index: "idx".to_string(),
        hits: Vec::new(),
        position: 0,
        page_size: 10,
        seq_no_primary_term: false,
        version: false,
        source_disabled: false,
        mapping_source_check: false,
        created: now,
        keep_alive,
        expires_at,
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn expired_scroll_contexts_are_swept() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    engine.scrolls.insert("dead".into(), scroll_ctx(-5));
    engine.scrolls.insert("live".into(), scroll_ctx(3600));

    let swept = engine.sweep_expired_scrolls();
    assert_eq!(swept, 1, "exactly the expired context is swept");
    assert!(engine.scrolls.get("dead").is_none(), "expired ctx freed");
    assert!(engine.scrolls.get("live").is_some(), "live ctx kept");
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn expired_async_search_results_are_swept() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis() as i64;

    engine.async_searches.insert(
        "dead".into(),
        json!({ "id": "dead", "expiration_time_in_millis": now_ms - 1000 }),
    );
    engine.async_searches.insert(
        "live".into(),
        json!({ "id": "live", "expiration_time_in_millis": now_ms + 3_600_000 }),
    );
    // Defensive arm: an entry with no expiry field counts as expired —
    // every writer sets the field, so this only fires on corruption, and
    // "reclaim" beats "pin forever" there.
    engine
        .async_searches
        .insert("malformed".into(), json!({ "id": "malformed" }));

    let swept = engine.sweep_expired_async_searches();
    assert_eq!(swept, 2, "expired + malformed swept, live kept");
    assert!(engine.async_searches.get("dead").is_none());
    assert!(engine.async_searches.get("malformed").is_none());
    assert!(engine.async_searches.get("live").is_some());
}

//! The security tooling this repo documents must be tooling that actually runs.
//!
//! Issue #207: `user-feedback/09-security/cves-and-vulnerabilities.md` advertised
//! `cargo-audit` "for dependency vulnerability scanning" and "fuzz testing
//! (cargo-fuzz) on all input parsing paths". Neither existed — no audit job, no
//! fuzz job, no fuzz target anywhere in the tree. A reader comparing XERJ against
//! the incumbent's CVE history priced in a fuzzed parser surface that was not
//! there, which is a worse failure than admitting the gap.
//!
//! Prose cannot be unit-tested, but *wiring* can, and the wiring is what the
//! prose is a claim about. These tests read the workflow file, the fuzz crate and
//! the doc off disk and fail if they disagree. All four fail at the commit that
//! filed #207.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

/// Walk up from this crate to the repository root.
///
/// Deliberately panics rather than skipping: a check that quietly turns into a
/// no-op when it cannot find its inputs is exactly the tautological pass #207
/// complains about elsewhere in this repo's test suite.
fn repo_root() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    loop {
        if dir.join(".github/workflows/ci.yml").is_file() {
            return dir;
        }
        assert!(
            dir.pop(),
            "no .github/workflows/ci.yml above {} — this test must run from a \
             repository checkout, and must not pass by failing to look",
            env!("CARGO_MANIFEST_DIR"),
        );
    }
}

fn read(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

/// `[[bin]] name = "…"` entries in the fuzz crate — the definitive list of
/// harnesses that exist, taken from the manifest rather than from a list pasted
/// into this test.
fn declared_fuzz_targets(root: &Path) -> BTreeSet<String> {
    let manifest = root.join("engine/fuzz/Cargo.toml");
    assert!(
        manifest.is_file(),
        "engine/fuzz/Cargo.toml is missing: the repo documents cargo-fuzz harnesses, \
         so the crate that holds them has to exist"
    );
    let text = read(&manifest);
    let mut in_bin = false;
    let mut names = BTreeSet::new();
    for line in text.lines() {
        let line = line.trim();
        if line.starts_with('[') {
            in_bin = line == "[[bin]]";
            continue;
        }
        if in_bin {
            if let Some(rest) = line.strip_prefix("name") {
                if let Some(value) = rest.split('=').nth(1) {
                    names.insert(value.trim().trim_matches('"').to_string());
                }
            }
        }
    }
    names
}

#[test]
fn cargo_audit_runs_in_ci() {
    let root = repo_root();
    let ci = read(&root.join(".github/workflows/ci.yml"));

    assert!(
        ci.contains("security-audit:"),
        "no `security-audit` job in ci.yml, but the security docs say cargo-audit \
         scans our dependencies"
    );
    assert!(
        ci.contains("cargo audit"),
        "the `security-audit` job never invokes `cargo audit`"
    );
    assert!(
        ci.contains("cargo install cargo-audit"),
        "the audit job does not install cargo-audit, so `cargo audit` would be a \
         command-not-found — which some runners report as a skipped step rather \
         than a failure"
    );
}

#[test]
fn every_fuzz_target_has_a_harness_and_seeds() {
    let root = repo_root();
    let targets = declared_fuzz_targets(&root);

    assert!(
        !targets.is_empty(),
        "engine/fuzz declares no [[bin]] targets — the cargo-fuzz claim would be \
         satisfied by an empty crate"
    );

    for target in &targets {
        let harness = root.join(format!("engine/fuzz/fuzz_targets/{target}.rs"));
        assert!(
            harness.is_file(),
            "fuzz target `{target}` is declared in Cargo.toml but {} does not exist",
            harness.display()
        );

        let seed_dir = root.join(format!("engine/fuzz/seeds/{target}"));
        let seeds = std::fs::read_dir(&seed_dir)
            .map(|d| d.flatten().count())
            .unwrap_or(0);
        assert!(
            seeds > 0,
            "fuzz target `{target}` has no seeds at {}. Starting from the empty \
             input, a bounded CI run reaches almost none of the parser, so the \
             target would pass without proving anything",
            seed_dir.display()
        );
    }
}

#[test]
fn ci_executes_the_fuzz_harnesses() {
    let root = repo_root();
    let ci = read(&root.join(".github/workflows/ci.yml"));
    let script_rel = ".github/scripts/fuzz-smoke.sh";

    assert!(
        ci.contains("fuzz:"),
        "no `fuzz` job in ci.yml — harnesses that exist but never run are the same \
         false claim in a different place"
    );
    assert!(
        ci.contains(script_rel),
        "the fuzz job does not run {script_rel}"
    );

    let script = root.join(script_rel);
    assert!(script.is_file(), "{script_rel} is missing");
    let body = read(&script);

    // The script must discover targets from the crate. A hardcoded list is how
    // a new harness ends up shipped-but-never-executed.
    assert!(
        body.contains("fuzz list"),
        "{script_rel} must enumerate targets with `cargo fuzz list` so a newly \
         added harness cannot be silently left out of the run"
    );
}

#[test]
fn the_security_docs_claim_only_what_ci_does() {
    let root = repo_root();
    let ci = read(&root.join(".github/workflows/ci.yml"));

    for doc_rel in [
        "user-feedback/09-security/cves-and-vulnerabilities.md",
        "SECURITY.md",
    ] {
        let doc = read(&root.join(doc_rel));
        if doc.contains("cargo-audit") {
            assert!(
                ci.contains("cargo audit"),
                "{doc_rel} claims cargo-audit; CI does not run it"
            );
        }
        if doc.contains("cargo-fuzz") {
            assert!(
                !declared_fuzz_targets(&root).is_empty(),
                "{doc_rel} claims cargo-fuzz; the tree has no fuzz targets"
            );
        }
    }

    // The specific overclaim #207 was filed about, hunted across every prose
    // file rather than just this one — the point of the issue is that the claim
    // must not survive anywhere, and copy gets copied.
    //
    // Coverage is five named parsers, not "all" of them, and the difference is
    // the whole point: a reader is deciding whether to trust a parser surface.
    let mut offenders = Vec::new();
    scan_prose(&root, &mut |path, text| {
        // CHANGELOG.md quotes the retired claim to say it was retired. A
        // changelog is a record of what happened, not a statement about what
        // the software does now, and it is the one file where the sentence
        // appearing is correct.
        if path.file_name().is_some_and(|n| n == "CHANGELOG.md") {
            return;
        }
        if text.contains("all input parsing paths") {
            offenders.push(path.to_path_buf());
        }
    });
    assert!(
        offenders.is_empty(),
        "these files still claim fuzz coverage of *all* input parsing paths; list \
         the parsers actually covered instead: {offenders:#?}"
    );
}

/// Visit every prose file (`.md`, `.html`, `.txt`) that ships in this repo.
///
/// Skips VCS, build and dependency directories, and the fuzz inputs — those
/// hold adversarial data, not claims about the product.
fn scan_prose(dir: &Path, visit: &mut impl FnMut(&Path, &str)) {
    const SKIP: [&str; 9] = [
        ".git",
        "target",
        "node_modules",
        "seeds",
        "corpus",
        "artifacts",
        ".venv",
        "vendor",
        // Gitignored local clone of upstream Elasticsearch. Not our prose, and
        // large enough to make this test feel broken on a dev machine.
        "es-reference",
    ];
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if SKIP.contains(&name.as_ref()) {
            continue;
        }
        if path.is_dir() {
            scan_prose(&path, visit);
        } else if matches!(
            path.extension().and_then(|e| e.to_str()),
            Some("md" | "html" | "txt")
        ) {
            if let Ok(text) = std::fs::read_to_string(&path) {
                visit(&path, &text);
            }
        }
    }
}

//! #1122 / #2433: the vectors the built-in lexical embedder derives for a
//! `semantic_text` field are not persisted in the stored `_source`. The
//! segment keeps the text and passage metadata; every reader gets the
//! vectors rebuilt bit-identically, before and after flush, merge and
//! reopen.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;
use xerj_storage::{SectionType, SegmentReader};

const INDEX: &str = "sem-derived";
const WORDS: &[&str] = &[
    "liquidity",
    "quarterly",
    "revenue",
    "storage",
    "vector",
    "merge",
    "segment",
    "harbor",
    "orchard",
    "glacier",
    "copper",
    "lantern",
    "meadow",
    "compiler",
    "kernel",
    "ledger",
];

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn schema() -> Schema {
    let mut schema = Schema::empty();
    let mut content = FieldConfig::new("content", FieldType::Text);
    content.options.dimensions = Some(32);
    content.options.similarity = Some("cosine".to_string());
    content.embedding = Some(xerj_common::types::EmbeddingConfig {
        endpoint: None,
        model: None,
        target_field: Some("content_vector".to_string()),
    });
    schema.fields.push(content);
    schema.fields.push(FieldConfig::new("n", FieldType::Long));
    schema
}

fn text(i: usize) -> String {
    let base: Vec<&str> = (0..12)
        .map(|k| WORDS[(i * 7 + k * 3) % WORDS.len()])
        .collect();
    let base = base.join(" ");
    if i.is_multiple_of(10) {
        // Several passages: exercises `<target>_chunks`.
        format!("doc {i} {}", format!("{base} ").repeat(20))
    } else {
        format!("doc {i} {base}")
    }
}

async fn bulk(engine: &Engine, range: std::ops::Range<usize>) {
    let mut body = String::new();
    for i in range {
        body.push_str(&format!(
            "{{\"index\":{{\"_index\":\"{INDEX}\",\"_id\":\"{i}\"}}}}\n"
        ));
        body.push_str(&serde_json::to_string(&json!({"content": text(i), "n": i})).unwrap());
        body.push('\n');
    }
    let result = xerj_engine::bulk::process_bulk(engine, None, &body).await;
    assert!(
        !result.errors,
        "{:?}",
        result.items.iter().find(|i| i.error.is_some())
    );
}

fn seg_files(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            seg_files(&path, out);
        } else if path.extension().is_some_and(|ext| ext == "seg") {
            out.push(path);
        }
    }
}

/// Every columnar stored section on disk: vectors absent, marker present.
fn assert_segments_stripped(dir: &TempDir) {
    let mut files = Vec::new();
    seg_files(dir.path(), &mut files);
    assert!(!files.is_empty(), "no segment written");
    let mut columnar = 0;
    for path in files {
        let reader = SegmentReader::open(&path).unwrap();
        let Some(raw) = reader.section(SectionType::Stored).unwrap() else {
            continue;
        };
        // Small sections stay row-oriented LZ4 and keep their vectors.
        let Some(names) = xerj_storage::stored_codec::stored_v2_source_column_names(raw).unwrap()
        else {
            continue;
        };
        columnar += 1;
        assert!(
            names.iter().any(|n| n == "content_vector"),
            "virtual column listed"
        );
        let preserved = xerj_storage::stored_codec::decode_stored_preserving_derived(raw).unwrap();
        let preserved = String::from_utf8(preserved).unwrap();
        assert!(
            !preserved.contains("\"content_vector\":"),
            "{path:?} stores vectors"
        );
        assert!(!preserved.contains("\"content_vector_chunks\":"));
        assert!(preserved.contains(r#""derived":"lexical-v1""#));
        let full = xerj_storage::stored_codec::decode_stored(raw).unwrap();
        let full = String::from_utf8(full).unwrap();
        assert!(
            full.contains("\"content_vector\":"),
            "decode rebuilds vectors"
        );
        assert!(full.contains("\"content_vector_chunks\":"));
        assert!(
            !full.contains(r#""derived""#),
            "marker never reaches readers"
        );
    }
    assert!(columnar > 0, "no columnar stored section to check");
}

