//! Issue #423 (symptom #408): a `term` query on a `keyword` ARRAY field must
//! return the same hit set before and after a flush. A document with
//! `"tags": ["red", "green", "blue"]` answers `term: {tags: "green"}` with 1
//! hit once flushed, but 0 hits while still buffered — only the FIRST array
//! element ("red") matches pre-flush. Same document, same query, two answers,
//! decided by a background flush the caller cannot see.
//!
//! ROOT CAUSE (confirmed): NOT `doc_matches_query` — `json_values_equal` already
//! matches any array element, and `size:5` returned the doc correctly. The miss
//! was in the size:0 COUNT path: `try_shortcut_count`'s bare-`term` keyword
//! shortcut counted the memtable via `doc_values_keyword_count`, whose
//! single-valued column stores only the FIRST array element (see `push_field`),
//! and — unlike `doc_values_term_query` / `doc_values_bool_hits` — it lacked the
//! array bailout. It returned a confident `Some(0)` that overwrote the correct
//! scan count. The fix adds that bailout (`term_count_needs_source_scan`) so the
//! shortcut abandons to the stored-source scan for array/whitespace fields.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn term_tag_hits(engine: &Engine, tag: &str) -> u64 {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({
        "query": { "term": { "tags": tag } },
        "size": 0,
        "from": 0
    }))
    .expect("parse_request");
    idx.search(&req).await.expect("search").total.value
}

/// `term` on a `keyword` array is flush-invariant: every element is matchable
/// whether the document is buffered or flushed. FAIL-BEFORE: the second array
/// element ("green") matches only after flush, so pre-flush=0, post-flush=1.
#[tokio::test]
async fn term_on_keyword_array_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("tags", FieldType::Keyword));
    engine.create_index("docs", schema).expect("create");

    let idx = engine.get_index("docs").expect("get");
    idx.index_document(
        Some("d0".to_string()),
        json!({ "tags": ["red", "green", "blue"] }),
    )
    .await
    .expect("index");

    // Second element, document still buffered (no refresh): pre-flush answer.
    let pre = term_tag_hits(&engine, "green").await;

    // Flush to segments: post-flush answer.
    idx.refresh().await.expect("refresh");
    let post = term_tag_hits(&engine, "green").await;

    assert_eq!(
        pre, post,
        "#423/#408: `term: green` on `[\"red\",\"green\",\"blue\"]` must be \
         flush-invariant (pre-flush={pre}, post-flush={post}); the memtable term \
         path is matching only the first array element"
    );
    assert_eq!(
        post, 1,
        "sanity: the flushed segment matches the array element"
    );
}

//! #864: a terms-agg bucket key is typed by the field's SOURCE shape. A keyword
//! value that looks numeric ("007") must stay the string "007" (ES keys a
//! keyword bucket by the string); a genuine numeric field still keys by number.
//! Asserted on the memtable (brute `run_terms`) AND after flush (columnar
//! `fast_aggs`) so the two paths agree.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

async fn bucket_keys(engine: &Engine, field: &str) -> Vec<Value> {
    let idx = engine.get_index("docs").expect("get index");
    let req = parse_request(&json!({
        "size": 0,
        "aggs": { "by": { "terms": { "field": field } } }
    }))
    .expect("parse_request");
    let res = idx.search(&req).await.expect("search");
    res.aggs.expect("aggs")["by"]["buckets"]
        .as_array()
        .expect("buckets")
        .iter()
        .map(|b| b["key"].clone())
        .collect()
}

#[tokio::test]
async fn terms_keyword_key_stays_string_numeric_stays_number() {
    let dir = TempDir::new().unwrap();
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    let engine = Engine::new(config).expect("engine");

    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("code", FieldType::Keyword));
    schema.fields.push(FieldConfig::new("qty", FieldType::Long));
    engine.create_index("docs", schema).expect("create");
    let idx = engine.get_index("docs").expect("get");
    for (id, code, qty) in [("d0", "007", 5), ("d1", "007", 5), ("d2", "042", 9)] {
        idx.index_document(Some(id.to_string()), json!({ "code": code, "qty": qty }))
            .await
            .expect("index");
    }

    // Assert buffered (memtable) and flushed (segment) agree AND are ES-correct.
    let kw_pre = bucket_keys(&engine, "code").await;
    let num_pre = bucket_keys(&engine, "qty").await;
    idx.refresh().await.expect("refresh");
    let kw_post = bucket_keys(&engine, "code").await;
    let num_post = bucket_keys(&engine, "qty").await;

    assert_eq!(
        kw_pre, kw_post,
        "#864: keyword key typing must be flush-invariant"
    );
    assert_eq!(
        num_pre, num_post,
        "numeric key typing must be flush-invariant"
    );

    // Keyword: string keys with leading zero intact.
    assert!(
        kw_post.contains(&json!("007")) && kw_post.contains(&json!("042")),
        "keyword keys must stay strings, got {kw_post:?}"
    );
    assert!(
        !kw_post.contains(&json!(7)) && !kw_post.contains(&json!(42)),
        "keyword keys must NOT be coerced to numbers, got {kw_post:?}"
    );
    // Numeric field: number keys (control — coercion still applies).
    assert!(
        num_post.contains(&json!(5)) && num_post.contains(&json!(9)),
        "numeric keys must stay numbers, got {num_post:?}"
    );
}

//! Regression tests: `term`/`terms` on an analyzed `text` field whose mapping
//! asks for doc-values (the ES `mapper.text.doc_values` shape) must answer the
//! same question before and after the flush.
//!
//! The memtable scan matches the analyzed token stream
//! (`doc_matches_query_typed`'s `tokens_contain`): `terms {text: ["brown"]}`
//! over "quick brown fox" matches. The flushed segment used to read the
//! doc-values column — which stores the RAW "quick brown fox" — through the
//! term/terms prefilters and the doc-values count shortcut, so the same query
//! returned nothing after `_refresh`, and the count agreed with the wrong
//! answer. A column-derived set is not a superset of token matching, so those
//! paths now decline for analyzed text fields (`field_is_analyzed_text`) and
//! the stored scan answers on both sides.

use std::collections::BTreeSet;
use std::sync::Arc;

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn search(idx: &Index, q: &Value) -> (u64, BTreeSet<String>) {
    let req = parse_request(&json!({ "query": q, "size": 50 })).expect("parse_request");
    let r = idx.search(&req).await.unwrap();
    (r.total.value, r.hits.iter().map(|h| h.id.clone()).collect())
}

async fn count_total(idx: &Index, q: &Value) -> u64 {
    let req = parse_request(&json!({ "query": q, "size": 0, "from": 0 })).expect("parse_request");
    idx.search(&req).await.unwrap().total.value
}

fn set(ids: &[&str]) -> BTreeSet<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

/// The shape the ES `mapper.text.doc_values` preview maps: an analyzed field
/// that also carries doc-values.
fn doc_values_text_schema() -> Schema {
    let mut schema = Schema::empty();
    let mut text = FieldConfig::new("text", FieldType::Text);
    text.options.doc_values = true;
    schema.fields.push(text);
    schema
}

#[tokio::test]
async fn terms_on_text_with_doc_values_is_flush_invariant() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("dvt", doc_values_text_schema())
        .unwrap();
    let idx: Arc<Index> = engine.get_index("dvt").unwrap();
    for (id, t) in [
        ("d1", "quick brown fox"),
        ("d2", "quick brown fox"),
        ("d3", "lazy dog"),
    ] {
        idx.index_document(Some(id.into()), json!({"text": t}))
            .await
            .unwrap();
    }

    // The token query the memtable answers.
    let token_q = json!({"terms": {"text": ["brown"]}});
    let (pre_total, pre_hits) = search(&idx, &token_q).await;
    assert_eq!(
        pre_hits,
        set(&["d1", "d2"]),
        "pre-flush (memtable) token match"
    );
    assert_eq!(pre_total, 2);
    assert_eq!(count_total(&idx, &token_q).await, 2, "count before flush");

    // The whole-value query both sides agree on. NOTE: this pins flush
    // invariance of XERJ's current answer, not ES semantics — ES's term-level
    // `terms` on indexed text would match no token "quick brown fox" (0 hits).
    let whole_q = json!({"terms": {"text": ["quick brown fox"]}});
    assert_eq!(search(&idx, &whole_q).await.1, set(&["d1", "d2"]));

    idx.flush().await.unwrap();

    // The segment really carries the doc-values column this test is about.
    let seg_dir = dir.path().join("dvt").join("segments");
    let dv_files = std::fs::read_dir(&seg_dir)
        .unwrap()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().is_some_and(|x| x == "dv"))
        .count();
    assert!(
        dv_files >= 1,
        "the mapping must have produced a .dv sidecar for the field"
    );

    let (post_total, post_hits) = search(&idx, &token_q).await;
    assert_eq!(
        post_hits,
        set(&["d1", "d2"]),
        "token match must survive the flush"
    );
    assert_eq!(post_total, pre_total, "hit total changed at flush");
    assert_eq!(
        count_total(&idx, &token_q).await,
        2,
        "count must not change at flush"
    );
    assert_eq!(
        search(&idx, &whole_q).await,
        (2, set(&["d1", "d2"])),
        "whole-value match must stay"
    );

    // The conjunction lane (bool prefilter) and the `term` shape, which
    // answers by whole value on both sides by design.
    let filtered = json!({"bool": {
        "must": [{"terms": {"text": ["brown"]}}],
        "filter": [{"term": {"text": "quick brown fox"}}],
    }});
    assert_eq!(search(&idx, &filtered).await.1, set(&["d1", "d2"]));
    assert_eq!(count_total(&idx, &filtered).await, 2);
    let term_q = json!({"term": {"text": "brown"}});
    assert_eq!(
        search(&idx, &term_q).await,
        (0, set(&[])),
        "term on text stays whole-value"
    );
}

/// `"index": false` + doc-values text (the ES `mapper.text.doc_values` preview
/// pinned by `aggregations/terms_text_docvalues.yml`): there are no postings,
/// so ES answers `term`/`terms` from the doc-values column — WHOLE values only.
/// A token-only value must not match once the segment answers.
#[tokio::test]
async fn terms_on_unindexed_text_with_doc_values_stays_whole_value() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    let mut schema = Schema::empty();
    let mut text = FieldConfig::new("text", FieldType::Text);
    text.options.doc_values = true;
    text.options.indexed = false;
    schema.fields.push(text);
    engine.create_index("dvn", schema).unwrap();
    let idx: Arc<Index> = engine.get_index("dvn").unwrap();
    for (id, value) in [
        ("d1", json!("quick brown fox")),
        ("d2", json!("lazy dog")),
        ("d3", json!("fox")),
        ("d4", json!("Fox")),
        ("d5", json!(["fox", "lazy dog"])),
    ] {
        idx.index_document(Some(id.into()), json!({ "text": value }))
            .await
            .unwrap();
    }

    let cases = [
        (
            "match token absent",
            json!({"match": {"text": "quick"}}),
            set(&[]),
        ),
        (
            "match whole token",
            json!({"match": {"text": "fox"}}),
            set(&["d3", "d5"]),
        ),
        (
            "match default or",
            json!({"match": {"text": "quick brown fox"}}),
            set(&["d3", "d5"]),
        ),
        (
            "match and",
            json!({"match": {"text": {"query": "quick brown fox", "operator": "and"}}}),
            set(&[]),
        ),
        (
            "match keyword",
            json!({"match": {"text": {"query": "quick brown fox", "analyzer": "keyword"}}}),
            set(&["d1"]),
        ),
        (
            "match uppercase",
            json!({"match": {"text": "FOX"}}),
            set(&["d3", "d5"]),
        ),
        (
            "match whitespace",
            json!({"match": {"text": {"query": "Fox", "analyzer": "whitespace"}}}),
            set(&["d4"]),
        ),
        (
            "match msm",
            json!({"match": {"text": {"query": "fox lazy", "minimum_should_match": 2}}}),
            set(&[]),
        ),
        (
            "terms token absent",
            json!({"terms": {"text": ["quick"]}}),
            set(&[]),
        ),
        (
            "terms whole",
            json!({"terms": {"text": ["quick brown fox"]}}),
            set(&["d1"]),
        ),
        (
            "term whole",
            json!({"term": {"text": "fox"}}),
            set(&["d3", "d5"]),
        ),
        (
            "bool filter",
            json!({"bool": {"filter": [{"terms": {"text": ["quick"]}}]}}),
            set(&[]),
        ),
        (
            "bool must",
            json!({"bool": {"must": [{"match": {"text": "fox"}}]}}),
            set(&["d3", "d5"]),
        ),
        (
            "constant score",
            json!({"constant_score": {"filter": {"match": {"text": "fox"}}}}),
            set(&["d3", "d5"]),
        ),
        (
            "dis max",
            json!({"dis_max": {"queries": [{"match": {"text": "fox"}}]}}),
            set(&["d3", "d5"]),
        ),
    ];

    for phase in ["before", "after"] {
        for (name, query, expected) in &cases {
            let (total, hits) = search(&idx, query).await;
            assert_eq!(&hits, expected, "{phase} flush: {name}");
            assert_eq!(total, expected.len() as u64, "{phase} flush total: {name}");
            assert_eq!(
                count_total(&idx, query).await,
                expected.len() as u64,
                "{phase} flush size:0 total: {name}"
            );
        }
        if phase == "before" {
            idx.flush().await.unwrap();
        }
    }
}

//! Finalize-verify (`size:0` + `terms` agg + `exists` on a
//! `doc_values: false` text field) must not materialise the stored corpus.
//!
//! Issue #1940: `exists` on `semantic_text` / `text` had no doc-values
//! column, so the filtered fast path refused the request and the brute
//! corpus cloned every stored document. A 10k-document window then grew
//! RSS with the corpus. The presence bitmap answers the same
//! `value_present` predicate from the `.dv` sidecar.
//!
//! The counters are the bound. They do not move with document count:
//! `corpus_docs_hydrated` counts stored documents cloned into the brute
//! aggregation corpus, and `stored_sections_cached` counts decoded stored
//! sections. Both stay flat across a full window, a one-digest window, and
//! a zero-hit digest.

use serde_json::{json, Value};
use std::collections::HashMap;
use std::sync::Arc;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::aggs::{corpus_docs_hydrated, fast_path_aggs_served};
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

/// Clears `FAST_AGG_MIN_DOCS` (10_000). 100 groups × 100 docs.
const GROUPS: usize = 100;
const DOCS_PER_GROUP: usize = 100;
const DOCS: usize = GROUPS * DOCS_PER_GROUP;

static ONE_AT_A_TIME: std::sync::LazyLock<tokio::sync::Mutex<()>> =
    std::sync::LazyLock::new(|| tokio::sync::Mutex::new(()));

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn schema() -> Schema {
    let mut s = Schema::empty();
    s.fields
        .push(FieldConfig::new("ax_file", FieldType::Keyword));
    let mut msg = FieldConfig::new("msg", FieldType::Text);
    msg.options.doc_values = false;
    s.fields.push(msg);
    s
}

fn digest(g: usize) -> String {
    format!("axf-{g:04}")
}

/// Variant `i % 10`. Present (exists = true) for `""` and any non-null
/// string, including a non-null element inside an array. Absent for a
/// missing key, JSON null, `[]`, and `[null]`.
fn msg_value(i: usize) -> Option<Value> {
    match i % 10 {
        0 => None,
        1 => Some(Value::Null),
        2 => Some(json!([])),
        3 => Some(json!("")),
        4 => Some(json!([null])),
        _ => Some(json!(format!("record {i} {}", "x".repeat(1024)))),
    }
}

fn exists_variant(i: usize) -> bool {
    matches!(i % 10, 3 | 5 | 6 | 7 | 8 | 9)
}

async fn seed(idx: &Arc<Index>) {
    for i in 0..DOCS {
        let g = i / DOCS_PER_GROUP;
        let mut doc = serde_json::Map::new();
        doc.insert("ax_file".to_string(), json!(digest(g)));
        if let Some(msg) = msg_value(i) {
            doc.insert("msg".to_string(), msg);
        }
        idx.index_document(Some(format!("doc-{i}")), Value::Object(doc))
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();
}

fn verify_query(digests: &[String]) -> Value {
    json!({
        "size": 0,
        "query": {
            "bool": {
                "filter": [
                    { "terms": { "ax_file": digests } },
                    { "exists": { "field": "msg" } }
                ]
            }
        },
        "aggs": {
            "values": {
                "terms": { "field": "ax_file", "size": digests.len().max(1) }
            }
        }
    })
}

async fn search(idx: &Arc<Index>, body: Value) -> xerj_query::executor::SearchResult {
    let req = parse_request(&body).unwrap();
    idx.search(&req).await.unwrap()
}

fn buckets(aggs: &Value) -> HashMap<String, u64> {
    aggs["values"]["buckets"]
        .as_array()
        .unwrap()
        .iter()
        .map(|b| {
            (
                b["key"].as_str().unwrap().to_string(),
                b["doc_count"].as_u64().unwrap(),
            )
        })
        .collect()
}

#[tokio::test]
async fn text_exists_verify_does_not_hydrate() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("verify", schema()).unwrap();
    let idx = engine.get_index("verify").unwrap();
    seed(&idx).await;

    let expected_per_group = (0..DOCS_PER_GROUP).filter(|r| exists_variant(*r)).count() as u64;
    assert_eq!(expected_per_group, 60);
    let all: Vec<String> = (0..GROUPS).map(digest).collect();

    let cached_before = idx.stored_sections_cached();
    let hydrated_before = corpus_docs_hydrated();
    let served_before = fast_path_aggs_served();

    let full = search(&idx, verify_query(&all)).await;
    assert_eq!(full.total.value, expected_per_group * GROUPS as u64);
    let full_buckets = buckets(full.aggs.as_ref().unwrap());
    assert_eq!(full_buckets.len(), GROUPS);
    for g in 0..GROUPS {
        assert_eq!(full_buckets[&digest(g)], expected_per_group);
    }

    let one = search(&idx, verify_query(&[digest(3)])).await;
    assert_eq!(one.total.value, expected_per_group);
    let one_buckets = buckets(one.aggs.as_ref().unwrap());
    assert_eq!(one_buckets.len(), 1);
    assert_eq!(one_buckets[&digest(3)], expected_per_group);

    let miss = search(&idx, verify_query(&["no-such-digest".to_string()])).await;
    assert_eq!(miss.total.value, 0);
    assert!(buckets(miss.aggs.as_ref().unwrap()).is_empty());

    // size:1 zero-hit, no aggs. The scored path must answer `exists` from
    // the bitmap rather than decoding the stored section up front.
    let page = search(
        &idx,
        json!({
            "size": 1,
            "query": {
                "bool": {
                    "filter": [
                        { "terms": { "ax_file": ["no-such-digest"] } },
                        { "exists": { "field": "msg" } }
                    ]
                }
            }
        }),
    )
    .await;
    assert_eq!(page.total.value, 0);
    assert!(page.hits.is_empty());

    assert_eq!(
        corpus_docs_hydrated() - hydrated_before,
        0,
        "verify/exists cloned stored documents into the aggregation corpus"
    );
    assert_eq!(
        idx.stored_sections_cached(),
        cached_before,
        "verify/exists decoded a stored section"
    );
    assert!(
        fast_path_aggs_served() - served_before >= 3,
        "the three size:0 windows must be served by the columnar fast path"
    );

    // Brute reference. `missing` is not a fast-path terms parameter, so the
    // executor refuses and the source scan answers. Every document has
    // `ax_file`, so the placeholder bucket stays empty and the live buckets
    // match the columnar result.
    let mut reference = verify_query(&all);
    reference["aggs"]["values"]["terms"]["missing"] = json!("__absent__");
    let ref_served = fast_path_aggs_served();
    let brute = search(&idx, reference).await;
    assert_eq!(
        fast_path_aggs_served() - ref_served,
        0,
        "the missing parameter must force the brute executor"
    );
    assert_eq!(brute.total.value, full.total.value);
    assert_eq!(buckets(brute.aggs.as_ref().unwrap()), full_buckets);
}

//! Regression test for #191 — tied `_score`s must resolve to ONE total order,
//! and every bounded page must be a prefix of the full materialisation.
//!
//! ES/Lucene make the top-k comparator total: `HitQueue.lessThan` breaks an
//! equal-score tie by the smaller `doc` id, and leaves are visited in
//! ascending global doc-id order, so the same document wins the tie no matter
//! how many hits were collected
//! (`lucene/core/src/java/org/apache/lucene/search/HitQueue.java:76-82` and
//! `TopScoreDocCollector.java:122-124`).
//!
//! XERJ ties by `seq_no` (arrival order — its `_doc` analogue) but does NOT
//! walk documents in `seq_no` order: `IndexSnapshot::segments` is in
//! flush/merge COMPLETION order (a flush drains each memtable shard into its
//! own segment; a merge appends its output at the end), and an FTS segment
//! returns its hits in stored-layout order.  Both bounded collectors therefore
//! used to resolve ties by *where the walk happened to reach the cap*:
//!
//!   * the scored FTS collector rejected a later segment whose best score only
//!     TIED the worst kept hit (`>` instead of a full-key comparison), and
//!   * the count-authoritative stored scan simply `break`ed once the collector
//!     was full, keeping the first `cap` matches in segment-list order.
//!
//! Measured pre-fix on the corpus below (12 byte-identical documents, one
//! exact score): `size:1000` returns doc00…doc23 in arrival order, while
//! `size:1` returned `doc02` on one release run and `doc01` on the next —
//! the answer is not merely wrong, it is not even STABLE, because the losing
//! tie-break is the racy segment-list order.  The partial-tie fixture below
//! returned `[top0, top1, tie03]` at `size:3` against `[top0, top1, tie00]`
//! at `size:500`.
//!
//! The properties asserted here are the ones a paginating client relies on:
//!   1. every `size:k` page equals the first `k` of the full page,
//!   2. walking the corpus one hit at a time with `from` reproduces it, and
//!   3. the answer does not depend on how many hits were requested.

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::Engine;
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// `kw` is an explicit `FieldType::Keyword` (`doc_values: true`); `body` and
/// `kind` remain dynamically mapped as `FieldType::Text` (`doc_values: false`
/// since #1329), so `term` on `kind` exercises the non-authoritative stored
/// scan while `term` on `kw` exercises the keyword doc-values / columnar routes
/// (#1359).
fn tied_schema() -> Schema {
    let mut schema = Schema::empty();
    schema
        .fields
        .push(FieldConfig::new("kw", FieldType::Keyword));
    schema
}

fn req(from: usize, size: usize, q: &Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({"from": from, "size": size, "query": q})).expect("parse_request")
}

/// 12 byte-identical documents over three flushes.  Identical text means an
/// exact BM25 tie on every scored path and an exact constant on every
/// filter path — the shape #191 is about.
async fn tied_corpus(idx: &std::sync::Arc<xerj_engine::index::Index>) -> Vec<String> {
    let mut ids = Vec::new();
    for batch in 0..3 {
        for i in 0..4 {
            let id = format!("doc{batch}{i}");
            idx.index_document(
                Some(id.clone()),
                json!({
                    "body": "listpack encoding for small collections",
                    "kind": "same",
                    "kw": "same",
                }),
            )
            .await
            .unwrap();
            ids.push(id);
        }
        idx.flush().await.unwrap();
    }
    ids
}

fn page_ids(hits: &[xerj_query::Hit]) -> Vec<String> {
    hits.iter().map(|h| h.id.clone()).collect()
}

#[tokio::test]
async fn tied_scores_bounded_pages_are_prefixes_of_the_full_page() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("tie", tied_schema()).unwrap();
    let idx = engine.get_index("tie").unwrap();
    let inserted = tied_corpus(&idx).await;

    // Each shape exercises a different collector:
    //   match           → scored FTS admission walk (`page_worst`)
    //   term            → non-authoritative dynamic-text stored scan (#1359)
    //   term_keyword    → keyword columnar / doc-values prefiltered scan (#1359)
    //   match_all       → columnar top-k
    //   constant_score  → columnar top-k with the wrapper's constant score
    for (label, q) in [
        ("match", json!({"match": {"body": "listpack"}})),
        ("term", json!({"term": {"kind": "same"}})),
        ("term_keyword", json!({"term": {"kw": "same"}})),
        ("match_all", json!({"match_all": {}})),
        (
            "constant_score",
            json!({"constant_score": {"filter": {"match_all": {}}}}),
        ),
    ] {
        let full = idx.search(&req(0, 1000, &q)).await.unwrap();
        assert_eq!(full.total.value, 12, "{label}: every doc matches");
        let full_ids = page_ids(&full.hits);
        assert_eq!(
            full_ids.len(),
            12,
            "{label}: full materialisation returns all 12"
        );

        // The tie really is exact — otherwise the test proves nothing.
        let scores: Vec<f32> = full.hits.iter().map(|h| h.score).collect();
        assert!(
            scores.windows(2).all(|w| w[0].to_bits() == w[1].to_bits()),
            "{label}: fixture must produce an EXACT tie, got {scores:?}"
        );

        // Property 1 — the tie-break is arrival order (`_doc`), matching the
        // `(score DESC, seq_no ASC, _id ASC)` order the final page sort uses.
        assert_eq!(
            full_ids, inserted,
            "{label}: an all-tied page must come back in arrival order"
        );

        // Property 2 — every bounded page is a prefix of the full page.
        for size in 1..=12usize {
            let p = idx.search(&req(0, size, &q)).await.unwrap();
            assert_eq!(
                page_ids(&p.hits),
                full_ids[..size],
                "{label}: size:{size} page disagrees with the full materialisation"
            );
            assert_eq!(
                p.total.value, 12,
                "{label}: size:{size} total must stay exact"
            );
        }

        // Property 3 — paging one hit at a time reproduces the same order.
        let walked: Vec<String> = {
            let mut acc = Vec::new();
            for from in 0..12usize {
                let p = idx.search(&req(from, 1, &q)).await.unwrap();
                acc.extend(page_ids(&p.hits));
            }
            acc
        };
        assert_eq!(
            walked, full_ids,
            "{label}: from/size walk disagrees with the full materialisation"
        );
    }
}

/// The same property when the tie is only PARTIAL: a handful of documents
/// outscore the rest, and the tied block straddles the page boundary.  This is
/// the `multi_match` / `best_fields` shape from the issue report, where four
/// documents landed on exactly 2.859662 across a `size:3` boundary.
#[tokio::test]
async fn tie_straddling_a_page_boundary_resolves_the_same_way_at_every_size() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("straddle", Schema::empty()).unwrap();
    let idx = engine.get_index("straddle").unwrap();

    // Two clear winners (the term twice in a short body), then eight
    // documents that tie each other exactly.
    for i in 0..2 {
        idx.index_document(
            Some(format!("top{i}")),
            json!({"body": "quicklist quicklist"}),
        )
        .await
        .unwrap();
    }
    idx.flush().await.unwrap();
    for batch in 0..2 {
        for i in 0..4 {
            idx.index_document(
                Some(format!("tie{batch}{i}")),
                json!({"body": "quicklist entry"}),
            )
            .await
            .unwrap();
        }
        idx.flush().await.unwrap();
    }

    let q = json!({"match": {"body": "quicklist"}});
    let full = idx.search(&req(0, 500, &q)).await.unwrap();
    let full_ids = page_ids(&full.hits);
    assert_eq!(full.total.value, 10);

    // The tied block is real: the last eight hits share one score.
    let scores: Vec<f32> = full.hits.iter().map(|h| h.score).collect();
    assert!(
        scores[2..]
            .windows(2)
            .all(|w| w[0].to_bits() == w[1].to_bits()),
        "fixture must tie the trailing block, got {scores:?}"
    );

    for size in 1..=10usize {
        let p = idx.search(&req(0, size, &q)).await.unwrap();
        assert_eq!(
            page_ids(&p.hits),
            full_ids[..size],
            "size:{size} page disagrees with the full materialisation"
        );
    }
}

/// The same property with an UNFLUSHED tail — the shape a live index is in
/// between flushes, and the one a paginating client hits most often.
///
/// Sizing this fixture takes two conditions at once, and an earlier revision
/// of this test met neither.  With `materialisation_limit = (from + size +
/// 100).max(256)` and the flushed documents arriving FIRST (so they own the
/// low `seq_no`s and the head of every page):
///
///   1. the UNFLUSHED batch must be larger than the cap, or the memtable hands
///      up every buffered hit and its bound is never exercised; and
///   2. some asserted page position must actually LAND on a memtable
///      document — i.e. `size` must exceed the flushed count — while (1) still
///      holds, which bounds `flushed < size < unflushed - 100`.
///
/// 40 flushed + 300 unflushed satisfies both across `size` 41…199.  The
/// original 320 flushed + 40 unflushed satisfied neither: 40 buffered hits
/// never reached a 256-hit cap, so the memtable collector could not truncate,
/// and every page position asserted (`size` ≤ 359, against 320 flushed
/// documents) was answered from segments.  That test passed before the fix and
/// after it, and would have kept passing however broken the memtable path
/// became.  Measured on this fixture at the pre-repair commit, `size` 60, 100
/// and 150 each returned a non-prefix page for all three shapes below.
///
/// `constant_score` was originally NOT one of the shapes here: on a MIXED
/// corpus its bounded page contained only memtable documents (`size:1`
/// returned `mem000` where the full page starts `seg0000`) — the
/// segment-side counterpart (#270) of the memtable bound this test was
/// written for.  The wrapper defeated the `is_match_all` flag, no
/// `try_shortcut_count` arm resolves a bare MatchAll, so the scan ran with
/// `count_authoritative == false`: it tallied segment matches past the full
/// collector but never materialised them, and the memtable (walked first)
/// owned the whole page.  Asserted since `is_match_all_effective` peels
/// `constant_score`/`boosted` chains for the count/bounds decisions, putting
/// the wrapped query on the same bounded-scan + cross-segment re-merge path
/// as bare `match_all`.
#[tokio::test]
async fn tied_scores_page_the_same_way_with_an_unflushed_memtable() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("mixed", tied_schema()).unwrap();
    let idx = engine.get_index("mixed").unwrap();

    let mut inserted = Vec::new();
    for batch in 0..2 {
        for i in 0..20u32 {
            let id = format!("seg{batch}{i:03}");
            idx.index_document(
                Some(id.clone()),
                json!({"body": "listpack encoding", "kind": "same", "kw": "same"}),
            )
            .await
            .unwrap();
            inserted.push(id);
        }
        idx.flush().await.unwrap();
    }
    // Deliberately NOT flushed — these stay in the memtable, and there are
    // more of them than any cap the sizes below imply, so the memtable-side
    // bound is the thing under test.
    for i in 0..300 {
        let id = format!("mem{i:03}");
        idx.index_document(
            Some(id.clone()),
            json!({"body": "listpack encoding", "kind": "same", "kw": "same"}),
        )
        .await
        .unwrap();
        inserted.push(id);
    }
    let total = inserted.len() as u64; // 340: 40 flushed + 300 unflushed

    for (label, q) in [
        ("match", json!({"match": {"body": "listpack"}})),
        ("term", json!({"term": {"kind": "same"}})),
        ("term_keyword", json!({"term": {"kw": "same"}})),
        ("match_all", json!({"match_all": {}})),
        (
            "constant_score",
            json!({"constant_score": {"filter": {"match_all": {}}}}),
        ),
    ] {
        let full = idx.search(&req(0, 1000, &q)).await.unwrap();
        let full_ids = page_ids(&full.hits);
        assert_eq!(full.total.value, total, "{label}: every doc matches");
        assert_eq!(
            full_ids, inserted,
            "{label}: an all-tied page must come back in arrival order, \
             segment documents before memtable ones"
        );
        // Every one of these implies a cap below 300, so the memtable is
        // always truncating; the ones past 40 are the ones whose page actually
        // contains buffered documents.
        for size in [1usize, 5, 41, 60, 100, 150, 199] {
            let p = idx.search(&req(0, size, &q)).await.unwrap();
            assert_eq!(
                page_ids(&p.hits),
                full_ids[..size],
                "{label}: size:{size} page disagrees with the full materialisation"
            );
        }
    }
}

/// #191's most natural reproduction, and the one the PR originally shipped
/// without: index N identical documents and page them BEFORE the flush.
///
/// Nothing here has been written to a segment, so every collector decision is
/// made on the memtable side.  That side bounds its materialisation twice over
/// — the sharded memtable caps each shard's contribution, and `admit_hit!`
/// caps the merged result — and neither bound used to rank candidates by the
/// page key.  A `ShardedFtsMemtable` holds 16 independent shards, a document
/// lands in one by id hash (a whole bulk batch by its FIRST id's hash), and
/// the query path walks them in INDEX order while filling a global budget.
/// So the page was "the tied documents that happen to live in the
/// lowest-numbered shards", which is neither arrival order nor stable.
///
/// Measured pre-fix, release, 600 byte-identical documents (every score bit
/// pattern `1065353216`, an exact tie), for `match`, `term`, `match_all` AND
/// `constant_score` alike:
///
/// ```text
/// size:5    → ["m0000", "m0001", "m0004", "m0005", "m0008"]
/// size:1000 → ["m0000", "m0001", "m0002", "m0003", "m0004"], …
/// ```
///
/// Each shape reaches a different memtable collector, which is why all four
/// are asserted: `match` takes the scored FTS merge, `term` the columnar
/// doc-values walk, `match_all` the bounded id list, and `constant_score` the
/// brute per-document scan.
#[tokio::test]
async fn tied_scores_page_the_same_way_with_no_flush_at_all() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("memonly", tied_schema()).unwrap();
    let idx = engine.get_index("memonly").unwrap();

    // Comfortably past the 256-hit floor.  `size:300` implies a 400-hit cap
    // and so still truncates; `size:599` implies 699 and does not, which is
    // why the full page below is a complete materialisation to compare
    // against.
    let mut inserted = Vec::new();
    for i in 0..600 {
        let id = format!("m{i:04}");
        idx.index_document(
            Some(id.clone()),
            json!({"body": "listpack encoding", "kind": "same", "kw": "same"}),
        )
        .await
        .unwrap();
        inserted.push(id);
    }

    for (label, q) in [
        ("match", json!({"match": {"body": "listpack"}})),
        ("term", json!({"term": {"kind": "same"}})),
        ("term_keyword", json!({"term": {"kw": "same"}})),
        ("match_all", json!({"match_all": {}})),
        (
            "constant_score",
            json!({"constant_score": {"filter": {"match_all": {}}}}),
        ),
    ] {
        let full = idx.search(&req(0, 1000, &q)).await.unwrap();
        let full_ids = page_ids(&full.hits);
        assert_eq!(full.total.value, 600, "{label}: every doc matches");

        // The tie really is exact — otherwise the test proves nothing.
        let scores: Vec<f32> = full.hits.iter().map(|h| h.score).collect();
        assert!(
            scores.windows(2).all(|w| w[0].to_bits() == w[1].to_bits()),
            "{label}: fixture must produce an EXACT tie, got {:?}",
            &scores[..5]
        );
        assert_eq!(
            full_ids, inserted,
            "{label}: an all-tied memtable page must come back in arrival order"
        );

        // Sizes on both sides of the 256 floor.  Measured pre-fix, `size` 5,
        // 50 and 300 each returned a page drawn from the low-numbered shards
        // for all four shapes; `size:1` happened to survive, because the
        // globally-first document also lived in a shard the truncated walk
        // reached.
        for size in [1usize, 2, 5, 50, 255, 256, 257, 300, 599] {
            let p = idx.search(&req(0, size, &q)).await.unwrap();
            assert_eq!(
                page_ids(&p.hits),
                full_ids[..size],
                "{label}: size:{size} page disagrees with the full materialisation"
            );
            assert_eq!(
                p.total.value, 600,
                "{label}: size:{size} total must stay exact"
            );
        }

        // Paging one hit at a time reproduces the same order.
        for from in [0usize, 1, 254, 255, 256, 300] {
            let p = idx.search(&req(from, 1, &q)).await.unwrap();
            assert_eq!(
                page_ids(&p.hits),
                full_ids[from..from + 1],
                "{label}: from:{from} size:1 disagrees with the full materialisation"
            );
        }
    }
}

//! Regression tests for #270 (part 2) — every post-sort re-sort in
//! `Index::search` must break score ties with the SAME total order as the
//! main page sort: `(score DESC, seq_no ASC, _id ASC)`.
//!
//! The main sort decorates each hit with its `seq_no` (arrival order — the
//! `_doc` analogue, see `HitQueue.lessThan` breaking equal scores by the
//! smaller doc id in `lucene/core/src/java/org/apache/lucene/search/
//! HitQueue.java:76-82`) so an all-tied page comes back in arrival order.
//! Five later re-sorts used to tie by `_id` ALONE — the IDF-weighted rescore
//! for bool-text queries, the TF-IDF fallback for near-zero BM25 scores, and
//! three in the `request.rescore` path — so any of them firing on a tied hit
//! set silently reordered the page into `_id` ASC, which for UUID-shaped ids
//! is exactly the "essentially random" ordering the main sort comment says
//! was replaced.
//!
//! The fixtures below make the misordering visible with readable ids: the
//! flushed documents are named `seg…` and the unflushed ones `mem…`, so `_id`
//! ASC ("m" < "s") puts every LATER memtable document ahead of every segment
//! document — the exact inversion measured in #270 (`mem0000…mem0599` before
//! `seg0000…seg0039`).

use serde_json::{json, Value};
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::Engine;
use xerj_query::ast::{RescoreQuery, RescoreQueryInner};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

fn req(from: usize, size: usize, q: &Value) -> xerj_query::ast::SearchRequest {
    parse_request(&json!({"from": from, "size": size, "query": q})).expect("parse_request")
}

fn page_ids(hits: &[xerj_query::Hit]) -> Vec<String> {
    hits.iter().map(|h| h.id.clone()).collect()
}

/// `flushed` byte-identical documents flushed to segments, then `unflushed`
/// more left in the memtable.  Segment ids sort AFTER memtable ids in `_id`
/// order but arrived first, so any `_id`-only tie-break inverts the page.
async fn mixed_corpus(
    idx: &std::sync::Arc<xerj_engine::index::Index>,
    flushed: usize,
    unflushed: usize,
) -> Vec<String> {
    let mut inserted = Vec::new();
    for i in 0..flushed {
        let id = format!("seg{i:04}");
        idx.index_document(
            Some(id.clone()),
            json!({"body": "listpack encoding", "kind": "same"}),
        )
        .await
        .unwrap();
        inserted.push(id);
    }
    idx.flush().await.unwrap();
    for i in 0..unflushed {
        let id = format!("mem{i:04}");
        idx.index_document(
            Some(id.clone()),
            json!({"body": "listpack encoding", "kind": "same"}),
        )
        .await
        .unwrap();
        inserted.push(id);
    }
    inserted
}

fn assert_tied_and_in_arrival_order(
    label: &str,
    hits: &[xerj_query::Hit],
    inserted: &[String],
    total: u64,
    reported_total: u64,
) {
    assert_eq!(reported_total, total, "{label}: every doc matches");
    let scores: Vec<f32> = hits.iter().map(|h| h.score).collect();
    assert!(
        scores.windows(2).all(|w| w[0].to_bits() == w[1].to_bits()),
        "{label}: fixture must produce an EXACT tie, got {:?}…",
        &scores[..scores.len().min(5)]
    );
    assert_eq!(
        page_ids(hits),
        inserted,
        "{label}: an all-tied page must come back in arrival order \
         (segment documents before the later memtable ones), not `_id` ASC"
    );
}

/// #270's own reproduction: 40 flushed + 600 unflushed identical documents,
/// plain `match`.  With ~640 identical documents the BM25 IDF collapses to
/// `ln(1 + 0.5/(N+0.5))` ≈ 0.0008, the max page score drops under the 0.001
/// threshold, and the TF-IDF fallback fires — its recomputed score is
/// `tf.sqrt() * (1 + ln(N/df))` = exactly 1.0 for identical docs (the
/// measured bit pattern 1065353216), and its re-sort used to tie by `_id`
/// alone, returning `mem0000…mem0599` before `seg0000…seg0039`.
#[tokio::test]
async fn tfidf_fallback_resort_keeps_arrival_order() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("tfidf", Schema::empty()).unwrap();
    let idx = engine.get_index("tfidf").unwrap();
    let inserted = mixed_corpus(&idx, 40, 600).await;

    let q = json!({"match": {"body": "listpack"}});
    let full = idx.search(&req(0, 1000, &q)).await.unwrap();
    assert_tied_and_in_arrival_order("match/tfidf", &full.hits, &inserted, 640, full.total.value);

    // Bounded pages must stay prefixes of the full page through the re-sort.
    for size in [1usize, 5, 41, 100] {
        let p = idx.search(&req(0, size, &q)).await.unwrap();
        assert_eq!(
            page_ids(&p.hits),
            inserted[..size],
            "match/tfidf: size:{size} page disagrees with the full materialisation"
        );
    }
}

/// The IDF-weighted rescore for bool-text queries (a Bool with ≥2 text
/// clauses).  On identical documents every clause has df == N, the rescored
/// score is uniform, and the pass's re-sort used to tie by `_id` alone.  The
/// corpus stays SMALL enough (340 docs → rescored score ≈ 0.005 > 0.001)
/// that the TF-IDF fallback does not also fire — this isolates the bool-text
/// re-sort.
///
/// Only the FULL materialisation is asserted, and that is a known residual
/// rather than an oversight: bounded pages for a multi-clause bool on a
/// MIXED corpus are selected under the FIRST-PASS scores, where the
/// memtable's uniform tf-sum (no IDF — the divergence this rescore pass
/// exists to repair, see the comment above the pass) does not equal the
/// segment BM25 score, so segment documents lose ADMISSION before the
/// rescore ever ties them.  That is a first-pass scoring divergence between
/// the memtable and segment scorers (#188's remit), not the `_id`-only
/// tie-break #270 is about — admission runs before any re-sort, so no
/// re-sort change can affect it — and it needs a scoring fix, not a sort
/// fix.
#[tokio::test]
async fn bool_text_idf_rescore_keeps_arrival_order() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("booltext", Schema::empty()).unwrap();
    let idx = engine.get_index("booltext").unwrap();
    let inserted = mixed_corpus(&idx, 40, 300).await;

    let q = json!({"bool": {"should": [
        {"match": {"body": "listpack"}},
        {"match": {"body": "encoding"}}
    ]}});
    let full = idx.search(&req(0, 1000, &q)).await.unwrap();
    assert_tied_and_in_arrival_order("bool-text", &full.hits, &inserted, 340, full.total.value);
}

/// The three re-sorts in the `request.rescore` path (before the first stage,
/// between chained stages, and after the last).  A `match_all` primary with a
/// uniform rescore query keeps every score tied through every stage, so all
/// three sorts see an all-tied hit set; each used to tie by `_id` alone.
/// Two chained stages make sure the between-stages sort runs too.
#[tokio::test]
async fn rescore_path_resorts_keep_arrival_order() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine.create_index("rescore", Schema::empty()).unwrap();
    let idx = engine.get_index("rescore").unwrap();
    let inserted = mixed_corpus(&idx, 40, 300).await;

    let stage = RescoreQuery {
        window_size: 1000,
        query: Some(RescoreQueryInner {
            rescore_query: xerj_query::parse_query(&json!({"term": {"kind": "same"}}))
                .expect("parse rescore query"),
            query_weight: 1.0,
            rescore_query_weight: 1.0,
        }),
        script: None,
    };
    let mut request = req(0, 1000, &json!({"match_all": {}}));
    request.rescore = vec![stage.clone(), stage];

    let full = idx.search(&request).await.unwrap();
    assert_tied_and_in_arrival_order("rescore", &full.hits, &inserted, 340, full.total.value);

    for size in [1usize, 5, 41, 100] {
        let mut bounded = req(0, size, &json!({"match_all": {}}));
        bounded.rescore = request.rescore.clone();
        let p = idx.search(&bounded).await.unwrap();
        assert_eq!(
            page_ids(&p.hits),
            inserted[..size],
            "rescore: size:{size} page disagrees with the full materialisation"
        );
    }
}

//! Search regressions for delete-only (`doc_count == 0`) segments.
//!
//! A persisted delete has no stored documents. Its segment intentionally
//! contains only the tombstone section, so query paths must not try to hydrate
//! a `Stored` section from it.

use serde_json::json;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::Schema;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

async fn seed_delete_only_segment(engine: &Engine, name: &str) {
    engine.create_index(name, Schema::empty()).unwrap();
    let index = engine.get_index(name).unwrap();

    index
        .index_document(Some("live".into()), json!({"group": "kept", "amount": 10}))
        .await
        .unwrap();
    index
        .index_document(
            Some("deleted".into()),
            json!({"group": "kept", "amount": 999}),
        )
        .await
        .unwrap();
    index.flush().await.unwrap();

    assert!(index.delete_document("deleted").await.unwrap());
    index.flush().await.unwrap();

    assert!(
        index
            .store_snapshot()
            .segments
            .iter()
            .any(|segment| segment.doc_count == 0 && segment.has_tombstones),
        "test setup must publish a tombstone-only segment"
    );
}

async fn assert_filtered_aggregation_works(index: &Index) {
    let unfiltered = parse_request(&json!({
        "query": {"match_all": {}},
        "track_total_hits": true
    }))
    .unwrap();
    let result = index
        .search(&unfiltered)
        .await
        .expect("unfiltered search must succeed");
    assert_eq!(result.total.value, 1);
    assert_eq!(result.hits.len(), 1);
    assert_eq!(result.hits[0].id, "live");

    // A filtered aggregation enters the JSON full-corpus fallback before the
    // later doc-values fallback can answer. Before the fix that corpus walk
    // attempted to hydrate the tombstone-only segment and returned
    // `segment ... unreadable during corpus assembly`.
    let request = parse_request(&json!({
        "size": 0,
        "track_total_hits": true,
        "query": {"terms": {"group": ["kept"]}},
        "aggs": {
            "amount_min": {"min": {"field": "amount"}},
            "amount_max": {"max": {"field": "amount"}}
        }
    }))
    .unwrap();

    let result = index.search(&request).await.expect("search must succeed");
    assert_eq!(result.total.value, 1);
    let aggs = result.aggs.expect("aggregations");
    assert_eq!(aggs["amount_min"]["value"], json!(10.0));
    assert_eq!(aggs["amount_max"]["value"], json!(10.0));
}

#[tokio::test]
async fn filtered_aggregation_skips_live_tombstone_only_segment() {
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    seed_delete_only_segment(&engine, "live-delete").await;

    let index = engine.get_index("live-delete").unwrap();
    assert_filtered_aggregation_works(&index).await;
}

#[tokio::test]
async fn filtered_aggregation_skips_reopened_tombstone_only_segment() {
    let dir = TempDir::new().unwrap();
    {
        let engine = make_engine(&dir);
        seed_delete_only_segment(&engine, "reopened-delete").await;
    }

    let reopened = make_engine(&dir);
    let index = reopened.get_index("reopened-delete").unwrap();
    assert!(
        index
            .store_snapshot()
            .segments
            .iter()
            .any(|segment| segment.doc_count == 0 && segment.has_tombstones),
        "restart must retain the tombstone-only segment"
    );
    assert_filtered_aggregation_works(&index).await;
}

//! #1267 — the batched finalize-verify windows against a data index whose
//! every record shares one of the window's digests (the cve-records resume
//! shape: ~52 records per source file, so a 1,024-digest `terms` window
//! covers an entire shard).  Two lanes, two questions:
//!
//! 1. COUNT lane — `bool.filter [terms ax_file ×1024]` (+ the semantic
//!    leg's `exists`) answering a `terms` agg at `size: window.len()`
//!    (1,024 buckets).  On the live crawl node one such window against
//!    the 53,153-doc `cves-28` shard ran 803,735 ms in `segment_loop`
//!    with `shortcut=None` — the brute agg corpus materialising the whole
//!    index per window.  The #1260 test (`fast_aggs_exists_and_deletes`)
//!    pins the same filter shape at TWO values; this file pins it at the
//!    client's real `VERIFY_WINDOW` (1,024) and at full-shard coverage,
//!    both on clean segments AND — the #1267 residual — on a shard whose
//!    flushed segment carries RESIDENT GHOSTS (a resume's overwrites and
//!    deletes), which is what had every window bailed to the brute corpus.
//! 2. DOC lane — the catalog read-back shape (`size: 8192`,
//!    `_source: ["file_key"]`, `terms file_key ×1024` + `term run_id`),
//!    measured for wall time only: this is the #1267 "verify windows
//!    with size > 0" residual, pinned clean and under tombstones.
//!
//! Both lanes assert fast-path/brute-path agreement, not just timing.

use serde_json::json;
use std::time::Instant;
use tempfile::TempDir;
use xerj_common::config::Config;
use xerj_common::types::{FieldConfig, FieldType, Schema};
use xerj_engine::aggs::fast_path_aggs_served;
use xerj_engine::{Engine, Index};
use xerj_query::parse_request;

/// The client's window size (`SyncExecutor::VERIFY_WINDOW`).
const WINDOW: usize = 1024;
/// Groups (distinct digests); at `DOCS_PER_GROUP` records each the index
/// clears `FAST_AGG_MIN_DOCS` (10,000) and a full window covers the whole
/// index — the cve-records resume shape.
const GROUPS: usize = 1024;
const DOCS_PER_GROUP: usize = 60;

static ONE_AT_A_TIME: std::sync::LazyLock<tokio::sync::Mutex<()>> =
    std::sync::LazyLock::new(|| tokio::sync::Mutex::new(()));

fn make_engine(dir: &TempDir) -> Engine {
    let mut config = Config::default();
    config.server.data_dir = dir.path().to_str().unwrap().to_string();
    Engine::new(config).expect("engine::new")
}

/// Declare the exact-match fields this verify-shape reads as `keyword`, the
/// way the real crawl's data index and the autoindex catalog declare theirs
/// (`ax_file` is a content digest, `ax_dataset` a dataset name, `cve_id` an
/// identifier — all keyword, never analysed text). These tests used
/// `Schema::empty()`, so since #1329 those fields became `text` parents with
/// NO doc-values column; the columnar count-lane (terms on `ax_file`) and the
/// `KwExists` arm both read that column, so the window fell to the brute path
/// and the "served columnar" assertions failed. `text` is declared keyword
/// too so the `exists` arm has a column to read — a declared keyword carries
/// no `ignore_above` by default, so the ~1 KB record body is still stored
/// whole (presence is all `exists` reads).
fn kw_schema(fields: &[&str]) -> Schema {
    let mut s = Schema::empty();
    for f in fields {
        s.fields.push(FieldConfig::new(*f, FieldType::Keyword));
    }
    s
}

async fn run(idx: &std::sync::Arc<Index>, body: serde_json::Value) -> serde_json::Value {
    let req = parse_request(&body).unwrap();
    let res = idx.search(&req).await.unwrap();
    json!({
        "total": res.total.value,
        "hits": res.hits.len(),
        "aggs": res.aggs.clone().unwrap_or(json!(null)),
    })
}

/// The record body of group `g`, record `r` — shared by the seed and the
/// byte-identical rewrite (whose ghost must be counted out while its
/// memtable replacement is counted in, live corpus unchanged).
fn doc_body(g: usize, r: usize) -> serde_json::Value {
    json!({
        "ax_file": format!("axf2-{:032x}-{:04x}", g * 7, g),
        "ax_dataset": "cvelistv5-cves-28",
        "cve_id": format!("CVE-2026-{g:04}"),
        "text": format!(
            "A heap-based buffer overflow was found in record {r} of group {g}. {}",
            "The parser reads a length prefix without validating it against the allocation. ".repeat(14),
        ),
    })
}

/// `GROUPS × DOCS_PER_GROUP` flushed docs shaped like the crawl's data
/// records: every doc of a group carries the group's `ax_file` content
/// digest, ~1 KB of prose (a real CVE record's description block), and the
/// dataset keyword the exact-dataset read-back filters on.
async fn seed(idx: &std::sync::Arc<Index>) -> Vec<String> {
    let mut digests = Vec::with_capacity(GROUPS);
    for g in 0..GROUPS {
        digests.push(format!("axf2-{:032x}-{:04x}", g * 7, g));
        for r in 0..DOCS_PER_GROUP {
            idx.index_document(
                Some(format!("doc-{}", g * DOCS_PER_GROUP + r)),
                doc_body(g, r),
            )
            .await
            .unwrap();
        }
    }
    idx.flush().await.unwrap();
    digests
}

fn count_lane(digests: &[String], exists: bool) -> serde_json::Value {
    let mut filter = vec![json!({ "terms": { "ax_file": digests } })];
    if exists {
        filter.push(json!({ "exists": { "field": "text" } }));
    }
    json!({
        "size": 0,
        "query": { "bool": { "filter": filter } },
        "aggs": { "values": { "terms": { "field": "ax_file", "size": digests.len() } } }
    })
}

/// `key → doc_count` for a terms bucket array (order varies with counts).
fn bucket_counts(buckets: &serde_json::Value) -> std::collections::HashMap<String, u64> {
    buckets
        .as_array()
        .unwrap()
        .iter()
        .map(|b| {
            (
                b["key"].as_str().unwrap().to_string(),
                b["doc_count"].as_u64().unwrap(),
            )
        })
        .collect()
}

/// The count-lane window must be served by the columnar fast path even at
/// the client's full window size with whole-index coverage, and its buckets
/// must agree with the brute path (same request under
/// `XERJ_DISABLE_FAST_AGGS`-equivalent… which cannot be flipped per-test in
/// one process — so agreement is pinned against the per-digest expectation:
/// every bucket holds exactly `DOCS_PER_GROUP`).
#[tokio::test]
async fn count_lane_full_window_is_served_columnar() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index(
            "cves28",
            kw_schema(&["ax_file", "ax_dataset", "cve_id", "text"]),
        )
        .unwrap();
    let idx = engine.get_index("cves28").unwrap();
    let digests = seed(&idx).await;

    for exists in [false, true] {
        let before = fast_path_aggs_served();
        let t0 = Instant::now();
        let res = run(&idx, count_lane(&digests, exists)).await;
        let elapsed = t0.elapsed();
        let served = fast_path_aggs_served() - before;

        assert_eq!(
            res["total"].as_u64().unwrap(),
            (GROUPS * DOCS_PER_GROUP) as u64,
            "exists={exists} total"
        );
        let buckets = res["aggs"]["values"]["buckets"].as_array().unwrap();
        assert_eq!(buckets.len(), WINDOW, "exists={exists} bucket count");
        for b in buckets {
            assert_eq!(b["doc_count"].as_u64().unwrap(), DOCS_PER_GROUP as u64);
        }
        // THE regression signal: the live crawl node answered this shape from
        // the brute agg corpus (803,735 ms segment_loop).  If the fast path
        // refuses it again, fail loudly rather than ship the slow answer.
        assert!(
            served >= 1,
            "exists={exists}: columnar fast path did not serve the full-window verify shape ({} ms)",
            elapsed.as_millis()
        );
    }
}

/// THE #1267 repro: a resumed crawl shard carries tombstones — the resume
/// overwrites/deletes rows whose superseded copies are still resident in a
/// flushed segment — and until this fix ANY dirty ghost bitmap bailed the
/// whole fast-agg request, so every verify window paid the brute agg corpus
/// (803,735 ms measured on the live 53,153-doc `cves-28`).  The admission
/// gate now admits the verify shape (filter + single plain terms agg) with
/// dirty bitmaps: the row pass skips ghosted rows, the filtered total
/// row-scans dirty segments, and the memtable replacement copies are
/// counted live.  Exactness is pinned by arithmetic (known deletes, known
/// byte-identical rewrites) AND by agreement with the brute reference —
/// the same terms agg plus a sibling `value_count`, which makes the aggs
/// tree non-row-exact and so falls to the brute executor.
#[tokio::test]
async fn count_lane_with_resident_ghosts_is_served_and_exact() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index(
            "cves28g",
            kw_schema(&["ax_file", "ax_dataset", "cve_id", "text"]),
        )
        .unwrap();
    let idx = engine.get_index("cves28g").unwrap();
    let digests = seed(&idx).await;

    // Group 0 loses its first DELETED rows (ghosts that MATCH the window
    // filter — their `ax_file` is `digests[0]`, in-window).
    const DELETED: usize = 10;
    // Group 1's first REWRITTEN rows are overwritten byte-identically:
    // ghosts in the segment, fresh live copies in the memtable, live
    // corpus and every bucket count unchanged.
    const REWRITTEN: usize = 25;
    for i in 0..DELETED {
        idx.delete_document(&format!("doc-{i}")).await.unwrap();
    }
    for r in 0..REWRITTEN {
        idx.index_document(Some(format!("doc-{}", DOCS_PER_GROUP + r)), doc_body(1, r))
            .await
            .unwrap();
    }

    let before = fast_path_aggs_served();
    let t0 = Instant::now();
    let fast = run(&idx, count_lane(&digests, false)).await;
    let elapsed = t0.elapsed();
    assert_eq!(
        fast_path_aggs_served() - before,
        1,
        "a dirty-but-admitted segment must serve the verify shape columnarly ({} ms)",
        elapsed.as_millis()
    );

    assert_eq!(
        fast["total"].as_u64().unwrap(),
        (GROUPS * DOCS_PER_GROUP - DELETED) as u64,
        "ghosted rows must leave the filtered total"
    );
    let counts = bucket_counts(&fast["aggs"]["values"]["buckets"]);
    assert_eq!(counts.len(), WINDOW, "every digest still has live docs");
    assert_eq!(
        counts[&digests[0]],
        (DOCS_PER_GROUP - DELETED) as u64,
        "deleted rows must leave their bucket"
    );
    assert_eq!(
        counts[&digests[1]], DOCS_PER_GROUP as u64,
        "byte-identical rewrites: ghost out, memtable copy in — net zero"
    );
    for (d, c) in &counts {
        if *d != digests[0] {
            assert_eq!(*c, DOCS_PER_GROUP as u64, "untouched group {d}");
        }
    }

    // Brute reference: the sibling agg makes the tree non-row-exact, so
    // the dirty segments bail admission and the brute executor answers.
    // Its terms buckets and total are the reference the fast path must
    // reproduce.
    let mut reference = count_lane(&digests, false);
    reference["aggs"]["n"] = json!({ "value_count": { "field": "cve_id" } });
    let ref_before = fast_path_aggs_served();
    let brute = run(&idx, reference).await;
    assert_eq!(
        fast_path_aggs_served() - ref_before,
        0,
        "the sibling agg must force the brute executor"
    );
    assert_eq!(fast["total"], brute["total"], "total disagrees with brute");
    assert_eq!(
        fast["aggs"]["values"]["buckets"], brute["aggs"]["values"]["buckets"],
        "columnar buckets disagree with the brute reference under ghosts"
    );

    // Wall-time guard: the row pass over one dirty segment + 1,024-bucket
    // build is milliseconds-scale work; the brute corpus this replaced
    // materialised every matched doc.
    assert!(
        elapsed.as_millis() < 5_000,
        "dirty-segment verify window took {} ms",
        elapsed.as_millis()
    );
}

/// The catalog read-back shape: a fetching search, no aggs.  Wall-time
/// regression guard for the #1267 doc lane — a 1,024-digest window over a
/// fully-matching index must answer in seconds, not minutes, and return
/// exactly the window's documents — clean AND with tombstones resident
/// (the resume state of the live catalog).
#[tokio::test]
async fn doc_lane_window_fetch_is_bounded() {
    let _sequential = ONE_AT_A_TIME.lock().await;
    let dir = TempDir::new().unwrap();
    let engine = make_engine(&dir);
    engine
        .create_index("catalog", kw_schema(&["file_key", "run_id", "ax_path"]))
        .unwrap();
    let idx = engine.get_index("catalog").unwrap();
    // The catalog holds ONE doc per (digest, alias) — seed the same digests
    // plus a run_id that matches everything (the resume-rewrote-everything
    // case) and a second run's docs that the run_id term must exclude.
    let mut digests = Vec::with_capacity(GROUPS);
    let mut run_this_ids = Vec::with_capacity(GROUPS);
    let mut run_other_ids = Vec::new();
    let mut docs = Vec::new();
    for g in 0..GROUPS {
        let digest = format!("axf2-{:032x}-{:04x}", g * 7, g);
        digests.push(digest.clone());
        docs.push(json!({
            "file_key": digest,
            "run_id": "run-this",
            "ax_path": format!("CVE-2026-{g:04}.json"),
        }));
        if g % 3 == 0 {
            docs.push(json!({
                "file_key": digest,
                "run_id": "run-other",
                "ax_path": format!("CVE-2026-{g:04}.json"),
            }));
        }
    }
    for (i, doc) in docs.into_iter().enumerate() {
        if doc["run_id"] == json!("run-this") {
            run_this_ids.push(format!("cat-{i}"));
        } else {
            run_other_ids.push(format!("cat-{i}"));
        }
        idx.index_document(Some(format!("cat-{i}")), doc)
            .await
            .unwrap();
    }
    idx.flush().await.unwrap();

    let body = json!({
        "size": 8192,
        "from": 0,
        "track_total_hits": true,
        "_source": ["file_key"],
        "query": { "bool": { "filter": [
            { "terms": { "file_key": digests } },
            { "term": { "run_id": "run-this" } }
        ]}}
    });
    let t0 = Instant::now();
    let res = run(&idx, body.clone()).await;
    let elapsed = t0.elapsed();

    assert_eq!(res["total"].as_u64().unwrap(), GROUPS as u64);
    assert_eq!(res["hits"].as_u64().unwrap(), GROUPS as u64);
    // The live catalog leg measured 31 ms cold / 14 ms warm per window on
    // 402,814 docs; a full second here means the fetch path regressed to
    // parsing the whole index per window.
    assert!(
        elapsed.as_millis() < 1_000,
        "catalog window fetch took {} ms",
        elapsed.as_millis()
    );

    // Dirty phase (#1267): the resume state — deletes on run-this rows
    // (ghosts that MATCH the window) and byte-identical rewrites of
    // run-other rows (ghosts the run_id term excludes anyway).  The fetch
    // must count exactly the live run-this docs.
    let mut deleted = 0usize;
    for (g, id) in run_this_ids.iter().enumerate() {
        if g % 10 == 0 {
            idx.delete_document(id).await.unwrap();
            deleted += 1;
        }
    }
    for id in run_other_ids.iter().take(40) {
        let doc = idx.get_document(id).await.unwrap().unwrap();
        idx.index_document(Some(id.clone()), doc).await.unwrap();
    }

    let t0 = Instant::now();
    let res = run(&idx, body.clone()).await;
    let elapsed = t0.elapsed();

    assert_eq!(
        res["total"].as_u64().unwrap(),
        (GROUPS - deleted) as u64,
        "tombstoned catalog rows must leave the fetch total"
    );
    assert_eq!(res["hits"].as_u64().unwrap(), (GROUPS - deleted) as u64);
    assert!(
        elapsed.as_millis() < 1_000,
        "catalog window fetch under tombstones took {} ms",
        elapsed.as_millis()
    );
}

//! Issue #320 — push a filtered subset of indices to an external
//! ES-compatible target (single-node WAL tap).
//!
//! Every test here fails on the pre-#320 tree for the same reason: nothing
//! pushed data out of the engine at all. `_ccr/*` answered `501`,
//! reindex-from-remote was refused up front, and snapshot/restore was the only
//! export path — scheduled, whole-index, not near-real-time.
//!
//! The target is a stub HTTP server that speaks just enough `_bulk` to record
//! what it was sent, which is also the point of the feature: the wire format
//! is `_bulk` and nothing else, so an Elasticsearch cluster, an OpenSearch
//! cluster or another xerj node are all the same to the tap.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use serde_json::{json, Value};
use tempfile::TempDir;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};

use xerj_common::config::{Config, WalTapConfig};
use xerj_common::types::Schema;
use xerj_engine::Engine;

// ─────────────────────────────────────────────────────────────────────────────
// A stub `_bulk` target
// ─────────────────────────────────────────────────────────────────────────────

#[derive(Default)]
struct Received {
    /// Every NDJSON body the target was POSTed, in order.
    bodies: Vec<String>,
    /// `Authorization` header of the last request, if any.
    last_auth: Option<String>,
    /// `_id` → highest `version` this target currently holds, maintained only
    /// in [`TargetSemantics::ExternalVersioning`].
    versions: HashMap<String, u64>,
}

/// How the stub answers a `_bulk`.
#[derive(Clone, Copy, PartialEq, Eq)]
enum TargetSemantics {
    /// `{"took":1,"errors":false,"items":[]}` — everything is accepted.
    ///
    /// Fine for "did the bytes arrive", useless for the design's central
    /// safety claim, because it makes the whole `errors == true` branch of
    /// `send_bulk` dead code.
    AlwaysAccept,
    /// Elasticsearch's `version_type: external` rule, which is what the tap's
    /// at-least-once story rests on: an action applies only if its `version`
    /// is **strictly greater** than the one the target holds for that `_id`;
    /// otherwise the item comes back `version_conflict_engine_exception` and
    /// the stored document is untouched.
    ///
    /// This is the target the feature is designed against, and until now
    /// nothing in the tree implemented it —
    /// `scripts/verify-wal-tap.sh` runs two real xerj nodes, and xerj's own
    /// `_bulk` ignores per-action `version` / `version_type` (only the
    /// single-doc path honours them, `es_compat.rs:2990`), so even the
    /// end-to-end script exercised precisely the target that ignores the
    /// mechanism.
    ExternalVersioning,
    /// External versioning against a target that already holds a *higher*
    /// version for every `_id` — a second writer got there first. Every action
    /// is a rejected no-op, and the tap must say so rather than report a
    /// healthy zero-lag stream.
    ExternalVersioningAheadBy(u64),
    /// `200` with `errors: true` and a **non-conflict** rejection on every
    /// item — the shape a target with an incompatible mapping produces.
    ///
    /// Operationally identical to `ExternalVersioningAheadBy`: not one
    /// document is at the target. It exists separately because the health
    /// signal used to count only the conflict case, so this — every document
    /// dropped, permanently, with the cursor advancing past them — read as
    /// `healthy: true`, `last_error: null`.
    RejectsEveryItem,
}

/// Answer a `_bulk` the way a target with an incompatible mapping does:
/// `200 OK`, `errors: true`, and a `mapper_parsing_exception` per item.
///
/// Note the status: the request succeeded. `send_bulk`'s whole-request failure
/// path is not involved, the cursor advances past every one of these documents
/// (deliberately — see `WalTap::send_bulk`), and they are gone.
fn reject_every_item(body: &str) -> String {
    let mut items = Vec::new();
    let mut lines = body.lines();
    while let Some(meta_line) = lines.next() {
        if meta_line.trim().is_empty() {
            continue;
        }
        let meta: Value = serde_json::from_str(meta_line).expect("action line");
        let (action, spec) = meta
            .as_object()
            .and_then(|o| o.iter().next())
            .map(|(k, v)| (k.clone(), v.clone()))
            .expect("action object");
        if action != "delete" {
            let _ = lines.next().expect("source line");
        }
        items.push(json!({action: {
            "_index": spec["_index"], "_id": spec["_id"], "status": 400,
            "error": {
                "type": "mapper_parsing_exception",
                "reason": "failed to parse field [v] of type [long]",
            },
        }}));
    }
    json!({"took": 1, "errors": true, "items": items}).to_string()
}

struct StubTarget {
    url: String,
    received: Arc<Mutex<Received>>,
    _task: tokio::task::JoinHandle<()>,
}

impl StubTarget {
    async fn start() -> Self {
        Self::start_with(TargetSemantics::AlwaysAccept).await
    }

    async fn start_with(semantics: TargetSemantics) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        let received = Arc::new(Mutex::new(Received::default()));
        let sink = received.clone();
        let task = tokio::spawn(async move {
            loop {
                let Ok((stream, _)) = listener.accept().await else {
                    return;
                };
                let sink = sink.clone();
                tokio::spawn(async move {
                    let _ = serve_one(stream, sink, semantics).await;
                });
            }
        });
        Self {
            url,
            received,
            _task: task,
        }
    }

    /// The document set the target actually holds, `_id` → version. Only
    /// meaningful for the external-versioning semantics.
    fn stored_versions(&self) -> HashMap<String, u64> {
        self.received.lock().unwrap().versions.clone()
    }

    /// Every `_bulk` action line the target has seen, paired with the source
    /// line that followed it (`None` for a delete).
    fn actions(&self) -> Vec<(Value, Option<Value>)> {
        let bodies = self.received.lock().unwrap().bodies.clone();
        let mut out = Vec::new();
        for body in bodies {
            let mut lines = body.lines();
            while let Some(meta) = lines.next() {
                if meta.trim().is_empty() {
                    continue;
                }
                let meta: Value = serde_json::from_str(meta)
                    .unwrap_or_else(|e| panic!("bad action line {meta:?}: {e}"));
                let is_delete = meta.get("delete").is_some();
                let source = if is_delete {
                    None
                } else {
                    Some(serde_json::from_str(lines.next().expect("source line")).unwrap())
                };
                out.push((meta, source));
            }
        }
        out
    }

    fn indexed_ids(&self, index: &str) -> Vec<String> {
        self.actions()
            .iter()
            .filter_map(|(meta, _)| meta.get("index"))
            .filter(|a| a["_index"] == index)
            .map(|a| a["_id"].as_str().unwrap_or_default().to_string())
            .collect()
    }

    fn request_count(&self) -> usize {
        self.received.lock().unwrap().bodies.len()
    }
}

/// Apply one `_bulk` NDJSON body under [`TargetSemantics::ExternalVersioning`]
/// and return the ES-shaped response body.
///
/// Deliberately implements the ES rule and not a friendlier one:
///
/// * an `_id` the target does **not** hold is CREATED, at whatever external
///   version was supplied — external versioning exists to let an outside
///   system own the version line, so there is no floor to clear;
/// * an `_id` it does hold is overwritten iff `version > stored`;
/// * otherwise the item comes back
///   `{"status":409,"error":{"type":"version_conflict_engine_exception", …}}`
///   with the stored document left alone.
///
/// The create case is load-bearing. Seeding `stored = incoming` on first
/// sight — which `held.entry(id).or_insert(incoming + ahead_by)` did whenever
/// `ahead_by == 0` — made `incoming > stored` false for the FIRST delivery of
/// every document, so the tap's first send was answered `409` and the
/// convergence test never observed a single accepted item. It passed anyway,
/// because "the redelivery changed nothing" is trivially true when the first
/// delivery changed nothing either.
fn apply_external_versioning(body: &str, held: &mut HashMap<String, u64>, ahead_by: u64) -> String {
    let mut items = Vec::new();
    let mut errors = false;
    let mut lines = body.lines();
    while let Some(meta_line) = lines.next() {
        if meta_line.trim().is_empty() {
            continue;
        }
        let meta: Value = serde_json::from_str(meta_line).expect("action line");
        let (action, spec) = meta
            .as_object()
            .and_then(|o| o.iter().next())
            .map(|(k, v)| (k.clone(), v.clone()))
            .expect("action object");
        if action != "delete" {
            // Consume the source line.
            let _ = lines.next().expect("source line");
        }
        let id = spec["_id"].as_str().unwrap_or_default().to_string();
        let index = spec["_index"].as_str().unwrap_or_default().to_string();
        let incoming = spec["version"].as_u64().unwrap_or(0);
        assert_eq!(
            spec["version_type"], "external",
            "the tap must send external versioning or none of this applies"
        );

        // What the target holds for this `_id`, if anything. `ahead_by > 0`
        // models a second writer that got to this target first, so the very
        // first sight of an `_id` is already occupied by a version the tap can
        // never beat; `ahead_by == 0` means the tap is the only writer and an
        // unseen `_id` is genuinely absent.
        let stored = match held.get(&id).copied() {
            Some(v) => Some(v),
            None if ahead_by > 0 => {
                let seeded = incoming + ahead_by;
                held.insert(id.clone(), seeded);
                Some(seeded)
            }
            None => None,
        };
        // Absent → create. Present → strictly-greater wins. This is the ES
        // rule; anything stricter makes the first delivery a conflict and the
        // whole at-least-once story untestable.
        let applies = match stored {
            None => true,
            Some(s) => incoming > s,
        };
        if applies {
            let result = match (action.as_str(), stored) {
                ("delete", None) => "not_found",
                ("delete", Some(_)) => "deleted",
                (_, None) => "created",
                (_, Some(_)) => "updated",
            };
            // A delete leaves a tombstone AT the external version, exactly as
            // ES does — dropping the entry instead would let a redelivered
            // `index` at a lower version resurrect the document, which is the
            // failure this whole mechanism exists to prevent.
            held.insert(id.clone(), incoming);
            items.push(json!({action: {
                "_index": index, "_id": id, "_version": incoming,
                "result": result,
                "status": if result == "created" { 201 } else { 200 },
            }}));
        } else {
            let stored =
                stored.expect("the conflict branch is only reachable with a stored version");
            errors = true;
            items.push(json!({action: {
                "_index": index, "_id": id, "_version": stored, "status": 409,
                "error": {
                    "type": "version_conflict_engine_exception",
                    "reason": format!(
                        "[{id}]: version conflict, current version [{stored}] is higher \
                         or equal to the one provided [{incoming}]"),
                },
            }}));
        }
    }
    json!({"took": 1, "errors": errors, "items": items}).to_string()
}

/// Read one HTTP request, record the body, answer with an ES-shaped `_bulk`
/// response.
async fn serve_one(
    mut stream: TcpStream,
    sink: Arc<Mutex<Received>>,
    semantics: TargetSemantics,
) -> std::io::Result<()> {
    let mut raw = Vec::new();
    let mut buf = [0u8; 8192];
    loop {
        let n = stream.read(&mut buf).await?;
        if n == 0 {
            break;
        }
        raw.extend_from_slice(&buf[..n]);
        let text = String::from_utf8_lossy(&raw).into_owned();
        let Some(head_end) = text.find("\r\n\r\n") else {
            continue;
        };
        let head = &text[..head_end];
        let len: usize = head
            .lines()
            .find_map(|l| {
                let (k, v) = l.split_once(':')?;
                k.eq_ignore_ascii_case("content-length")
                    .then(|| v.trim().parse().ok())?
            })
            .unwrap_or(0);
        if raw.len() < head_end + 4 + len {
            continue;
        }
        let body = text[head_end + 4..head_end + 4 + len].to_string();
        let auth = head.lines().find_map(|l| {
            let (k, v) = l.split_once(':')?;
            k.eq_ignore_ascii_case("authorization")
                .then(|| v.trim().to_string())
        });
        let payload = {
            let mut guard = sink.lock().unwrap();
            guard.last_auth = auth;
            let response = match semantics {
                TargetSemantics::AlwaysAccept => {
                    r#"{"took":1,"errors":false,"items":[]}"#.to_string()
                }
                TargetSemantics::ExternalVersioning => {
                    let mut held = std::mem::take(&mut guard.versions);
                    let out = apply_external_versioning(&body, &mut held, 0);
                    guard.versions = held;
                    out
                }
                TargetSemantics::ExternalVersioningAheadBy(n) => {
                    let mut held = std::mem::take(&mut guard.versions);
                    let out = apply_external_versioning(&body, &mut held, n);
                    guard.versions = held;
                    out
                }
                TargetSemantics::RejectsEveryItem => reject_every_item(&body),
            };
            guard.bodies.push(body);
            response
        };
        let resp = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
            payload.len()
        );
        stream.write_all(resp.as_bytes()).await?;
        stream.write_all(payload.as_bytes()).await?;
        stream.flush().await?;
        break;
    }
    Ok(())
}

