    #[test]
    fn hits_sorted_by_descending_score() {
        let dir = TempDir::new().unwrap();
        let searcher = setup_searcher(dir.path());

        let q = Query::Term(TermQuery::new("body", "fox"));
        let hits = searcher.search(&q, 10, false).unwrap();

        let scores: Vec<f32> = hits.iter().map(|h| h.score).collect();
        for window in scores.windows(2) {
            assert!(
                window[0] >= window[1],
                "hits must be in descending score order: {:?}",
                scores
            );
        }
    }

    /// `search_bounded(cap)` must return EXACTLY the same top-`cap` hits (same
    /// order, same scores) as the legacy `execute() + sort_unstable() +
    /// truncate(cap)`, and its reported `total` must equal the full match count
    /// regardless of `cap`.  Exercises both the streaming leaf-`Term` path and
    /// the `execute()`-then-drain compound (`Bool`) path.
    #[test]
    fn search_bounded_matches_legacy_topk_and_total() {
        let dir = TempDir::new().unwrap();
        let searcher = setup_searcher(dir.path());

        // Two query shapes with a MULTI-score match set:
        //  - Term "fox": docs 0,1,4 with distinct BM25 (doc 4 TF=4 ranks top).
        //  - Bool should(fox|quick|lazy): a wider, differently-scored set that
        //    routes through execute()-then-drain, not the streaming leaf.
        let term_q = Query::Term(TermQuery::new("body", "fox"));
        let bool_q = Query::Bool(Box::new(
            BoolQuery::new()
                .should(Query::Term(TermQuery::new("body", "fox")))
                .should(Query::Term(TermQuery::new("body", "quick")))
                .should(Query::Term(TermQuery::new("body", "lazy"))),
        ));

        for q in [&term_q, &bool_q] {
            // Legacy reference: usize::MAX keeps the full-set sort path.
            let full = searcher.search(q, usize::MAX, false).unwrap();
            let total_full = full.len() as u64;
            assert!(total_full >= 3, "query should match several docs");

            // Order must already be strictly non-increasing by score.
            for w in full.windows(2) {
                assert!(w[0].score >= w[1].score);
            }

            for cap in [
                0usize,
                1,
                2,
                3,
                total_full as usize,
                total_full as usize + 5,
            ] {
                let (bounded, total) = searcher.search_bounded(q, cap, false).unwrap();

                // (1) Exact total is independent of the page cap.
                assert_eq!(
                    total, total_full,
                    "bounded total must equal full match count at cap={cap}"
                );

                // (2) Top-`cap` is byte-identical to legacy sort+truncate.
                let expected: Vec<(u32, u32)> = full
                    .iter()
                    .take(cap)
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                let got: Vec<(u32, u32)> = bounded
                    .iter()
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                assert_eq!(
                    got, expected,
                    "bounded top-{cap} must match legacy sort+truncate (doc_id+score)"
                );
            }
        }
    }

    /// Corpus sized to make the WAND bound actually bite: one term in every
    /// document (low idf → a tiny score upper bound) beside one term in three
    /// documents (high idf → the only scores that can fill a page).
    ///
    /// Returns the searcher.
    fn wand_fixture(dir: &std::path::Path) -> FtsSearcher {
        let registry = Arc::new(AnalyzerRegistry::default());
        let mut writer = FtsIndexWriter::new(dir, "seg0", Arc::clone(&registry));
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                ..Default::default()
            },
        );
        for i in 0..300u32 {
            // Docs 0..3 carry "needle"; every doc carries "the". Lengths vary
            // so `field_length` lookups differ across the walk.
            let text = if i < 3 {
                format!("the needle pad{i}")
            } else {
                format!("the pad{i} filler{}", i % 7)
            };
            let fields: HashMap<String, FieldValues> =
                [("body".to_owned(), FieldValues::from(text))]
                    .into_iter()
                    .collect();
            writer.add_document(i, &fields);
        }
        writer.finish().unwrap();
        let reader = Arc::new(FtsIndexReader::open(dir, "seg0", &["body"]).unwrap());
        FtsSearcher::new(reader, registry)
    }

    /// The WAND path (`search_bounded` on a should-only bool of terms) must be
    /// indistinguishable from the generic path — same hits, same order,
    /// **bit-identical scores**, same exact total — on a corpus where the
    /// pruning branch genuinely fires, and it must fire by construction, not
    /// by luck.
    ///
    /// The pruning precondition is ASSERTED, not assumed (the lesson of
    /// `bool_deadline_never_broadens_a_must_not`): once the page holds the
    /// three needle docs, a "the"-only doc can enter only if
    /// `idf(the)·(k1+1) ≥ worst-retained-score` — and this test fails loudly
    /// if that ever stops holding, because then the 297 pruning decisions it
    /// relies on would not have happened and the equivalence above would be
    /// passing vacuously over the same docs the legacy test already covers.
    #[test]
    fn wand_should_bool_matches_generic_path_when_pruning_fires() {
        let dir = TempDir::new().unwrap();
        let searcher = wand_fixture(dir.path());

        let q = Query::Bool(Box::new(
            BoolQuery::new()
                .should(Query::Term(TermQuery::new("body", "the")))
                .should(Query::Term(TermQuery::new("body", "needle"))),
        ));

        // Reference: usize::MAX never takes the WAND path, so this is the
        // generic walk's answer in full.
        let full = searcher.search(&q, usize::MAX, false).unwrap();
        assert_eq!(full.len(), 300, "every doc matches 'the'");
        for w in full.windows(2) {
            assert!(w[0].score >= w[1].score);
        }

        // --- the non-vacuity precondition ---
        // The three needle docs must be the page at cap=3, and the common
        // term's score supremum must sit strictly below that page's worst —
        // exactly the comparison the walk makes for each of the 297
        // "the"-only docs.
        assert_eq!(
            full[..3].iter().map(|h| h.doc_id).collect::<Vec<_>>(),
            vec![0, 1, 2],
            "the three needle docs must lead the ranking"
        );
        let bm25 = searcher.make_scorer("body");
        let the_df = searcher.scoring_df("body", "the", 300);
        let the_ubound = bm25.idf(the_df) * (bm25.k1 + 1.0);
        assert!(
            the_ubound < full[2].score,
            "precondition: 'the'-only docs (bound {the_ubound:.4}) must be prunable \
             against the cap-3 page (worst {:.4}) — otherwise this test exercises \
             no pruning",
            full[2].score
        );

        for cap in [0usize, 1, 2, 3, 5, 300, 305] {
            let (bounded, total) = searcher.search_bounded(&q, cap, false).unwrap();
            assert_eq!(total, 300, "exact total must survive pruning at cap={cap}");
            let expected: Vec<(u32, u32)> = full
                .iter()
                .take(cap)
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            let got: Vec<(u32, u32)> = bounded
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            assert_eq!(
                got, expected,
                "WAND top-{cap} must be byte-identical to the generic path"
            );
        }
    }

    /// Clause shapes that must NOT take the WAND path (`min_should_match > 1`,
    /// `must` beside `should`, a non-`Term` should clause) still get correct
    /// bounded answers — the shape guard falls them through to the generic
    /// walk, and this pins that the fallthrough, not just the guard, is right.
    #[test]
    fn wand_should_bool_falls_back_for_richer_shapes() {
        let dir = TempDir::new().unwrap();
        let searcher = wand_fixture(dir.path());

        let shapes: Vec<(&str, Query)> = vec![
            (
                "min_should_match=2",
                Query::Bool(Box::new(
                    BoolQuery::new()
                        .should(Query::Term(TermQuery::new("body", "the")))
                        .should(Query::Term(TermQuery::new("body", "needle")))
                        .min_should_match(2),
                )),
            ),
            (
                "must + should",
                Query::Bool(Box::new(
                    BoolQuery::new()
                        .must(Query::Term(TermQuery::new("body", "needle")))
                        .should(Query::Term(TermQuery::new("body", "the"))),
                )),
            ),
            (
                "non-Term should clause",
                Query::Bool(Box::new(
                    BoolQuery::new()
                        .should(Query::Term(TermQuery::new("body", "the")))
                        .should(Query::Prefix(PrefixQuery::new("body", "needl"))),
                )),
            ),
        ];

        for (name, q) in &shapes {
            let full = searcher.search(q, usize::MAX, false).unwrap();
            assert!(!full.is_empty(), "{name}: fixture must match something");
            for cap in [0usize, 1, 2, 3, 10, full.len(), full.len() + 5] {
                let (bounded, total) = searcher.search_bounded(q, cap, false).unwrap();
                assert_eq!(total, full.len() as u64, "{name}: total at cap={cap}");
                let expected: Vec<(u32, u32)> = full
                    .iter()
                    .take(cap)
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                let got: Vec<(u32, u32)> = bounded
                    .iter()
                    .map(|h| (h.doc_id, h.score.to_bits()))
                    .collect();
                assert_eq!(got, expected, "{name}: top-{cap}");
            }
        }
    }

    /// The WAND path's own clause bookkeeping on the awkward-but-legal edges:
    /// a DUPLICATE term (two cursors over the same postings, both must land in
    /// the clause-order sum), a boosted term (the bound must carry the boost
    /// or pruning would over-prune), an absent term (dropped like the generic
    /// path's empty per-clause vec), and a bool-level boost (applied exactly
    /// where the generic path applies it).
    #[test]
    fn wand_should_bool_duplicate_boosted_absent_and_bool_boost() {
        let dir = TempDir::new().unwrap();
        let searcher = wand_fixture(dir.path());

        let mut tq_dup = TermQuery::new("body", "needle");
        tq_dup.boost = 2.0;
        let q = Query::Bool(Box::new(
            BoolQuery::new()
                .should(Query::Term(tq_dup))
                // duplicate clause over the same postings, default boost
                .should(Query::Term(TermQuery::new("body", "needle")))
                .should(Query::Term(TermQuery::new("body", "the")))
                // absent from every doc
                .should(Query::Term(TermQuery::new("body", "absentterm")))
                .boost(1.5),
        ));

        let full = searcher.search(&q, usize::MAX, false).unwrap();
        assert_eq!(full.len(), 300, "the still matches everything");
        // The duplicate must actually double-count: each needle doc's score
        // here exceeds the same doc's single-needle score by roughly the
        // single contribution (boost 2.0 + 1.0 = 3× vs 1×).
        let single = Query::Bool(Box::new(
            BoolQuery::new().should(Query::Term(TermQuery::new("body", "needle"))),
        ));
        let single_hits = searcher.search(&single, usize::MAX, false).unwrap();
        let s0 = single_hits.iter().find(|h| h.doc_id == 0).unwrap().score;
        let d0 = full.iter().find(|h| h.doc_id == 0).unwrap().score;
        assert!(
            d0 > s0 * 4.0,
            "duplicate + 2.0 boost + 1.5 bool boost must compound: {d0:.4} vs {s0:.4}"
        );

        for cap in [0usize, 1, 2, 3, 7, 300] {
            let (bounded, total) = searcher.search_bounded(&q, cap, false).unwrap();
            assert_eq!(total, 300, "total at cap={cap}");
            let expected: Vec<(u32, u32)> = full
                .iter()
                .take(cap)
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            let got: Vec<(u32, u32)> = bounded
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect();
            assert_eq!(
                got, expected,
                "top-{cap} with duplicate/boosted/absent clauses"
            );
        }
    }

    /// Micro-bench (ignored by default; run with `--ignored`): the WAND path
    /// vs the generic bounded walk on a stopword-heavy disjunction over a
    /// 200k-doc synthetic index — the shape that motivated the fast path.
    /// `WAND_BENCH="clauses,cap"` (default "3,10") selects the clause count
    /// and page size; `WAND_BENCH="1,0"` measures the pure walk (nothing ever
    /// scored).  Asserts result equivalence once so the timing cannot silently
    /// drift onto unequal answers.
    #[test]
    #[ignore]
    fn bench_wand_vs_generic_stopword_disjunction() {
        let cfg = std::env::var("WAND_BENCH").unwrap_or_else(|_| "3,10".to_owned());
        let (nclauses, cap): (usize, usize) = {
            let mut it = cfg.split(',');
            (
                it.next().unwrap_or("3").parse().unwrap(),
                it.next().unwrap_or("10").parse().unwrap(),
            )
        };
        let dir = tempfile::TempDir::new().unwrap();
        let registry = Arc::new(AnalyzerRegistry::default());
        let mut writer = FtsIndexWriter::new(dir.path(), "seg0", Arc::clone(&registry));
        writer.configure_field(
            "body",
            FieldIndexConfig {
                analyzer: "whitespace".to_owned(),
                ..Default::default()
            },
        );
        const N: u32 = 200_000;
        let stops = ["the", "of", "and", "to", "in", "is"];
        for i in 0..N {
            // Terms of full df (the "stopwords"), a graded mid-df term, and
            // unique padding for realistic lengths.
            let mid = if i % 4 == 0 { "mid" } else { "pad" };
            let text = format!(
                "{} {mid} u{i}",
                stops[..nclauses.min(stops.len())].join(" ")
            );
            let fields: HashMap<String, FieldValues> =
                [("body".to_owned(), FieldValues::from(text))]
                    .into_iter()
                    .collect();
            writer.add_document(i, &fields);
        }
        writer.finish().unwrap();
        let reader = Arc::new(FtsIndexReader::open(dir.path(), "seg0", &["body"]).unwrap());
        let searcher = FtsSearcher::new(reader, registry);

        let mut bq = BoolQuery::new();
        for t in &stops[..nclauses.min(stops.len())] {
            bq = bq.should(Query::Term(TermQuery::new("body", *t)));
        }
        let q = Query::Bool(Box::new(bq));
        const REPS: u32 = 20;
        let _ = searcher.search_bounded(&q, cap, false).unwrap(); // warm
        let mut wand_us = 0f64;
        for _ in 0..REPS {
            let t0 = std::time::Instant::now();
            let _ = searcher.search_bounded(&q, cap, false).unwrap();
            wand_us += t0.elapsed().as_secs_f64() * 1e6;
        }
        let (g_hits, g_total) = searcher
            .search_bounded_observed(&q, cap, false, |_| {})
            .unwrap();
        let mut gen_us = 0f64;
        for _ in 0..REPS {
            let t0 = std::time::Instant::now();
            let _ = searcher
                .search_bounded_observed(&q, cap, false, |_| {})
                .unwrap();
            gen_us += t0.elapsed().as_secs_f64() * 1e6;
        }
        let (w_hits, w_total) = searcher.search_bounded(&q, cap, false).unwrap();
        assert_eq!(w_total, g_total);
        assert_eq!(
            w_hits
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect::<Vec<_>>(),
            g_hits
                .iter()
                .map(|h| (h.doc_id, h.score.to_bits()))
                .collect::<Vec<_>>(),
        );
        println!(
            "{nclauses}-stopword disjunction over {N} docs (df={N} each), cap={cap}: \
             generic {gen_us:.0} µs vs WAND {wand_us:.0} µs ({:.1}×), total={w_total}",
            gen_us / wand_us
        );
    }
}

//! A segment's FTS side-cars must not cost a full device flush per file.
//!
//! `File::sync_all` is `fcntl(F_FULLFSYNC)` on Apple targets, which drains the
//! whole device write cache and costs milliseconds per call. Writing each of a
//! segment's side-cars as its own durable write (sync the temp file, rename,
//! sync the directory) paid two of those per file: about 250 for a 31-field
//! segment, and on a Mac those flushes were most of the indexing time.
//!
//! One device flush after the temp files are written, and one after they are
//! renamed into place (Apple targets; elsewhere `fsync` stays per file, and
//! only the per-file directory sync goes), give the segment the same guarantee at the moment
//! `finish` returns: every side-car's bytes are on stable storage before its
//! name points at them, and every name is on stable storage before the caller
//! publishes the segment.
//!
//! This file holds one test on purpose: the flush counter is process-wide, and
//! a test binary of its own is the only way no other test writes alongside it.

use std::collections::HashMap;
use std::sync::Arc;

use xerj_fts::analyzer::AnalyzerRegistry;
use xerj_fts::index::{FieldValues, FtsIndexReader, FtsIndexWriter};

const FIELDS: usize = 31;
const DOCS: u32 = 50;

fn field(i: usize) -> String {
    format!("field_{i:02}")
}

#[test]
fn finishing_a_wide_segment_costs_a_bounded_number_of_full_flushes() {
    let dir = tempfile::tempdir().expect("tempdir");
    let mut writer =
        FtsIndexWriter::new(dir.path(), "seg_1", Arc::new(AnalyzerRegistry::default()));
    for doc in 0..DOCS {
        let fields: HashMap<String, FieldValues> = (0..FIELDS)
            .map(|i| {
                (
                    field(i),
                    FieldValues::One(format!("alpha beta value{} doc{doc}", i % 5)),
                )
            })
            .collect();
        writer.add_document(doc, &fields);
    }
    writer
        .publish_encoded_filename_layout()
        .expect("layout marker");

    let before = xerj_common::fsio::full_flush_count();
    let stats = writer.finish().expect("finish");
    let flushes = xerj_common::fsio::full_flush_count() - before;
    assert_eq!(stats.len(), FIELDS);

    // The old per-file shape issued 2 per side-car (temp file, then the
    // directory after its rename): 8 per field, 248 here.
    //
    // Apple targets: one device flush before the renames and one after.
    // Elsewhere `fsync` is the per-file barrier and stays per file, so the
    // saving is the per-file directory sync: one per side-car plus one.
    let side_cars = (FIELDS * 4) as u64;
    let bound = if cfg!(target_vendor = "apple") {
        2
    } else {
        side_cars + 1
    };
    assert!(
        flushes <= bound,
        "finish issued {flushes} full flushes for {FIELDS} fields; expected at most {bound}"
    );

    // Same segment, still readable: every field opens and answers.
    let names: Vec<String> = (0..FIELDS).map(field).collect();
    let refs: Vec<&str> = names.iter().map(String::as_str).collect();
    let reader = FtsIndexReader::open(dir.path(), "seg_1", &refs).expect("open");
    for name in &names {
        assert!(reader.field_stats(name).is_some(), "{name} has no stats");
        assert_eq!(reader.term_doc_freq(name, "alpha"), Some(DOCS), "{name}");
    }

    // No temp file survives a successful finish.
    let leftovers: Vec<String> = std::fs::read_dir(dir.path())
        .expect("read_dir")
        .map(|e| e.expect("entry").file_name().to_string_lossy().into_owned())
        .filter(|n| n.contains(".tmp"))
        .collect();
    assert!(leftovers.is_empty(), "temp files left: {leftovers:?}");
}

//! #876 — merging postings must produce the segment a re-analysing merge
//! would have produced.
//!
//! The merge path used to walk back to every surviving document's source
//! text and re-run the analyzer chain over it.  `FtsIndexWriter::
//! merge_from_segments` instead replays the source segments' already-built
//! posting lists.  That is only allowed to be faster — never different — so
//! every test here builds the SAME merged segment twice, once each way, and
//! compares the two.
//!
//! The comparison is deliberately at the byte level of the side-car files.
//! Hits and BM25 scores are a pure function of those bytes, so equal files are
//! a strictly stronger claim than equal search results; the search comparison
//! is kept anyway because it is the claim the issue actually makes.
//!
//! `.fst`, `.post` and `.meta` are compared byte for byte.  (`.meta` holds
//! `total_term_frequency`, which a docs-only field DOES diverge on when a
//! document repeats the same value — no fixture document does, so the byte
//! comparison is sound here, and that divergence has its own test:
//! `a_docs_only_field_carries_its_length_but_not_its_term_frequency`.)
//!
//! `.norms` is compared for the content a reader can observe, because it is
//! knowingly NOT byte-identical: byte 0 spells both "field absent" and "field
//! length <= 1", `load_norms` drops byte-0 entries on read, so a replayed
//! merge cannot reproduce a trailing run of them and writes a SHORTER dense
//! array.  The `colour` field in the fixture below is single-token precisely
//! so that case is exercised on every run instead of being accidentally
//! avoided; the exact divergence, and the fact that nothing a query reads
//! moves with it, are pinned by
//! `a_single_token_field_replays_an_equivalent_shorter_norms_array`.

use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

use xerj_fts::analyzer::AnalyzerRegistry;
use xerj_fts::index::{
    segment_indexed_field_names, FieldIndexConfig, FieldValues, FtsIndexReader, FtsIndexWriter,
    FtsMergeSource,
};
use xerj_fts::search::{FtsSearcher, PhraseQuery, Query, TermQuery};

const FIELDS: [&str; 4] = ["body", "colour", "tags", "title"];
/// The side-cars a replayed merge must reproduce byte for byte.  `.norms` is
/// excluded on purpose and checked by `assert_norms_equivalent` instead — see
/// the module comment.
const EXTENSIONS: [&str; 3] = ["fst", "post", "meta"];

fn registry() -> Arc<AnalyzerRegistry> {
    Arc::new(AnalyzerRegistry::default())
}

fn configure(writer: &mut FtsIndexWriter) {
    writer.configure_field(
        "body",
        FieldIndexConfig {
            analyzer: "standard".to_owned(),
            store_positions: true,
            store_term_vectors: false,
        },
    );
    writer.configure_field(
        "title",
        FieldIndexConfig {
            analyzer: "standard".to_owned(),
            store_positions: true,
            store_term_vectors: false,
        },
    );
    // Keyword fields are docs-only: their posting lists carry neither a
    // frequency nor a position, which is the shape the merge has to preserve.
    writer.configure_field(
        "tags",
        FieldIndexConfig {
            analyzer: "keyword".to_owned(),
            store_positions: false,
            store_term_vectors: false,
        },
    );
    // A SINGLE-TOKEN keyword field.  `norm_u16_to_u8` maps length 1 to byte 0,
    // the same byte it uses for "field absent", and the reader drops byte-0
    // entries — so every document's norm here is unrecoverable by a replay and
    // this field's `.norms` is the one side-car the merge cannot reproduce byte
    // for byte.  It is in the fixture so that gap is measured, not dodged.
    writer.configure_field(
        "colour",
        FieldIndexConfig {
            analyzer: "keyword".to_owned(),
            store_positions: false,
            store_term_vectors: false,
        },
    );
}

/// 300 documents, wide enough that the hottest terms cross the 128-doc PFOR
/// block boundary (so the merged segment exercises the full-block encoder and
/// its cross-block delta chain, not just the vbyte residual).
const DOC_COUNT: usize = 300;

fn document(index: usize) -> HashMap<String, FieldValues> {
    const NOUNS: [&str; 6] = ["fox", "hound", "otter", "falcon", "badger", "heron"];
    const COLOURS: [&str; 4] = ["amber", "cobalt", "russet", "verdant"];

    let mut fields: HashMap<String, FieldValues> = HashMap::new();

    // `quick` and `brown` land in every document (a >128-posting term);
    // `NOUNS[..]` repeats twice in the same value so term frequencies and
    // position lists are both non-trivial.
    let body = format!(
        "quick brown {noun} leapt past a quick {noun} and settled at {index}",
        noun = NOUNS[index % NOUNS.len()],
    );
    if index.is_multiple_of(7) {
        // Multi-valued text: the second value's positions start after
        // POSITION_INCREMENT_GAP, which a merge must carry through untouched.
        fields.insert(
            "body".to_owned(),
            FieldValues::from_values(vec![body, format!("a second value about {index}")]),
        );
    } else {
        fields.insert("body".to_owned(), FieldValues::One(body));
    }

    fields.insert(
        "tags".to_owned(),
        FieldValues::from_values(vec![
            format!("tag-{}", index % 11),
            format!("colour-{}", COLOURS[index % COLOURS.len()]),
        ]),
    );

    // Exactly one keyword token, on EVERY document — so this field's norm is
    // byte 0 for the highest merged ordinal, which is what makes the replayed
    // `.norms` shorter than the re-analysed one.
    fields.insert(
        "colour".to_owned(),
        FieldValues::One(COLOURS[index % COLOURS.len()].to_owned()),
    );

    // Present on only a third of the documents, so the merged segment has a
    // field whose document set is sparse in the merged ordinal space.
    if index.is_multiple_of(3) {
        fields.insert(
            "title".to_owned(),
            FieldValues::One(format!("Report {index} of the survey")),
        );
    }

    fields
}

/// Deterministic pseudo-shuffle standing in for `_seq_no` order: the engine
/// sorts every batch's survivors by sequence number, so documents from
/// different input segments INTERLEAVE in the merged ordinal space.  That is
/// what forces the merge to re-sort each term's posting list.
fn sequence_number(index: usize) -> usize {
    (index * 97) % DOC_COUNT
}

struct Fixture {
    dir: tempfile::TempDir,
    /// Per source segment: the documents it holds, in its own ordinal order.
    segments: Vec<Vec<usize>>,
}

impl Fixture {
    /// Three source segments, round-robin over the document set.
    fn build(survives: impl Fn(usize) -> bool) -> (Self, Vec<usize>) {
        let dir = tempfile::TempDir::new().unwrap();
        let mut segments: Vec<Vec<usize>> = vec![Vec::new(); 3];
        for index in 0..DOC_COUNT {
            segments[index % 3].push(index);
        }

        for (segment, documents) in segments.iter().enumerate() {
            let mut writer = FtsIndexWriter::new(dir.path(), format!("seg-{segment}"), registry());
            configure(&mut writer);
            let batch: Vec<(String, HashMap<String, FieldValues>, ())> = documents
                .iter()
                .map(|index| (index.to_string(), document(*index), ()))
                .collect();
            writer.add_documents_parallel(&batch);
            writer.finish().unwrap();
        }

        // Survivors, in merged (sequence-number) order.
        let mut survivors: Vec<usize> = (0..DOC_COUNT).filter(|index| survives(*index)).collect();
        survivors.sort_by_key(|index| sequence_number(*index));

        (Fixture { dir, segments }, survivors)
    }

    fn path(&self) -> &Path {
        self.dir.path()
    }

    /// The merged segment a RE-ANALYSING merge writes: every surviving
    /// document's field values, fed through the analyzer again.
    fn reanalysed(&self, survivors: &[usize], segment_id: &str) {
        let mut writer = FtsIndexWriter::new(self.path(), segment_id, registry());
        configure(&mut writer);
        let batch: Vec<(String, HashMap<String, FieldValues>, ())> = survivors
            .iter()
            .map(|index| (index.to_string(), document(*index), ()))
            .collect();
        writer.add_documents_parallel(&batch);
        writer.finish().unwrap();
    }

    /// The merged segment a POSTINGS merge writes: no documents, no analyzer,
    /// just the source segments' side-cars and a doc-id remap.
    fn replayed(&self, survivors: &[usize], segment_id: &str) {
        let merged_ordinal: HashMap<usize, u32> = survivors
            .iter()
            .enumerate()
            .map(|(ordinal, index)| (*index, ordinal as u32))
            .collect();

        let readers: Vec<FtsIndexReader> = (0..self.segments.len())
            .map(|segment| {
                FtsIndexReader::open(self.path(), format!("seg-{segment}"), &FIELDS).unwrap()
            })
            .collect();
        let doc_maps: Vec<Vec<Option<u32>>> = self
            .segments
            .iter()
            .map(|documents| {
                documents
                    .iter()
                    .map(|index| merged_ordinal.get(index).copied())
                    .collect()
            })
            .collect();
        let sources: Vec<FtsMergeSource<'_>> = readers
            .iter()
            .zip(doc_maps.iter())
            .map(|(reader, doc_map)| FtsMergeSource {
                reader,
                doc_map: doc_map.as_slice(),
            })
            .collect();

        let mut writer = FtsIndexWriter::new(self.path(), segment_id, registry());
        configure(&mut writer);
        writer.merge_from_segments(&sources).unwrap();
        writer.finish().unwrap();
    }
}

fn sidecar(dir: &Path, segment_id: &str, field: &str, extension: &str) -> Vec<u8> {
    std::fs::read(dir.join(format!("{segment_id}.{field}.{extension}")))
        .unwrap_or_else(|error| panic!("reading {segment_id}.{field}.{extension}: {error}"))
}

fn assert_sidecars_identical(dir: &Path, expected: &str, actual: &str, extensions: &[&str]) {
    for field in FIELDS {
        for extension in extensions {
            let want = sidecar(dir, expected, field, extension);
            let got = sidecar(dir, actual, field, extension);
            assert_eq!(
                want,
                got,
                "field '{field}' side-car .{extension} differs between the re-analysed \
                 merge and the replayed merge ({} vs {} bytes)",
                want.len(),
                got.len()
            );
        }
    }
}

/// The declared length of a `.norms` dense array, straight out of the ZNM1
/// header (`"ZNM1"`, u8 encoding, u32 dense_len, u32 payload_len).
fn norms_dense_len(dir: &Path, segment_id: &str, field: &str) -> u32 {
    let bytes = sidecar(dir, segment_id, field, "norms");
    assert!(
        bytes.len() >= 13 && &bytes[..4] == b"ZNM1",
        "{segment_id}.{field}.norms is not in the ZNM1 format this test reads"
    );
    u32::from_le_bytes(bytes[5..9].try_into().unwrap())
}

/// `.norms` is the one side-car a replay cannot reproduce byte for byte, so it
/// is compared for what a reader can actually see instead.
///
/// The replayed array is allowed to be SHORTER — byte 0 means both "absent"
/// and "length <= 1", `load_norms` drops those entries, so the replay stops at
/// the last non-zero document — but every norm byte, every dequantised
/// `field_length` and the field statistics behind `avgdl` must match exactly.
/// A shorter array with an identical live table differs only in trailing
/// zeros, which is precisely what no query can observe.
fn assert_norms_equivalent(dir: &Path, expected: &str, actual: &str, doc_count: u32) {
    let want_reader = FtsIndexReader::open(dir, expected, &FIELDS).unwrap();
    let got_reader = FtsIndexReader::open(dir, actual, &FIELDS).unwrap();
    for field in FIELDS {
        let want: Vec<(u32, u8)> = want_reader.field_norm_bytes(field).collect();
        let got: Vec<(u32, u8)> = got_reader.field_norm_bytes(field).collect();
        assert_eq!(
            want, got,
            "field '{field}': the norm bytes a reader loads differ between the \
             re-analysed merge and the replayed merge"
        );
        for doc_id in 0..doc_count {
            assert_eq!(
                want_reader.field_length(field, doc_id),
                got_reader.field_length(field, doc_id),
                "field '{field}': length of merged doc {doc_id} differs"
            );
        }
        let want_len = norms_dense_len(dir, expected, field);
        let got_len = norms_dense_len(dir, actual, field);
        assert!(
            got_len <= want_len,
            "field '{field}': the replayed .norms dense array ({got_len}) may be \
             shorter than the re-analysed one ({want_len}) but never longer — \
             a longer one would mean the replay invented a document"
        );
    }
}

fn hits(dir: &Path, segment_id: &str, query: &Query) -> Vec<(u32, u32)> {
    let reader = Arc::new(FtsIndexReader::open(dir, segment_id, &FIELDS).unwrap());
    let searcher = FtsSearcher::new(reader, registry());
    searcher
        .search(query, 500, false)
        .unwrap()
        .into_iter()
        // Compare the score's exact bit pattern: "same BM25 score" means
        // identical, not close.
        .map(|hit| (hit.doc_id, hit.score.to_bits()))
        .collect()
}

fn queries() -> Vec<Query> {
    vec![
        Query::Term(TermQuery::new("body", "quick")),
        Query::Term(TermQuery::new("body", "otter")),
        Query::Phrase(PhraseQuery::new(
            "body",
            vec!["quick".to_owned(), "brown".to_owned()],
        )),
        // Spans the position-increment gap between two values of the same
        // multi-valued field: it must match NOTHING, before and after.
        Query::Phrase(PhraseQuery::new(
            "body",
            vec!["17".to_owned(), "a".to_owned()],
        )),
        Query::Term(TermQuery::new("tags", "tag-3")),
        Query::Term(TermQuery::new("tags", "colour-cobalt")),
        // The single-token field whose `.norms` the replay cannot reproduce:
        // its hits and its BM25 scores must be identical anyway.
        Query::Term(TermQuery::new("colour", "cobalt")),
        Query::Term(TermQuery::new("title", "survey")),
        Query::MatchAll,
    ]
}

fn assert_searches_identical(dir: &Path, expected: &str, actual: &str) {
    for query in queries() {
        let want = hits(dir, expected, &query);
        let got = hits(dir, actual, &query);
        assert_eq!(
            want, got,
            "hit list / scores differ for {query:?} between the re-analysed merge and \
             the replayed merge"
        );
    }
}

/// `.fst`, `.post` and `.meta` byte for byte; `.norms` for everything a
/// reader can observe (see `assert_norms_equivalent`).
#[test]
fn a_merge_with_no_deletes_reproduces_the_re_analysed_segment() {
    let (fixture, survivors) = Fixture::build(|_| true);
    assert_eq!(survivors.len(), DOC_COUNT);

    fixture.reanalysed(&survivors, "merged-reanalysed");
    fixture.replayed(&survivors, "merged-replayed");

    assert_sidecars_identical(
