            Routing::Confident("b".to_string())
        );
        assert_eq!(
            with_symbol_evidence(
                Routing::Ambiguous(both.clone()),
                &["b".to_string(), "c".to_string()]
            ),
            Routing::Ambiguous(vec!["b".to_string(), "c".to_string()])
