    let one_pack = dir_size(&newest);

    let (pruned, left) = prune_to_budget(hub, one_pack + 1, &BTreeSet::new());

    assert_eq!(
        pruned.iter().map(|p| p.slug.as_str()).collect::<Vec<_>>(),
        vec!["alpha", "beta"],
        "oldest first"
    );
    assert!(left <= one_pack + 1);
    assert!(newest.is_dir());
}

