    assert!(systemd_exec_token(Path::new("/opt/a\nb")).is_err());

    let service = render_systemd_service(Path::new("/opt/my tools/xerj")).unwrap();
    assert!(service.contains("ExecStart=\"/opt/my tools/xerj\" hub sync"));
}

