// The process environment is global: this must stay the only test here that sets it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn ask_end_to_end() {
    let work_tmp = tempfile::tempdir().unwrap();
    let work = std::fs::canonicalize(work_tmp.path()).unwrap();
    let allowlist = vec![work.to_string_lossy().into_owned()];
    let scratch_home = work.join("home");
    std::fs::create_dir_all(&scratch_home).unwrap();
    let cwd = work.join("cwd");
    std::fs::create_dir_all(&cwd).unwrap();
    let (seed, public) = generate_keypair().unwrap();

    // Build the pack once, on a builder node.
    let out = work.join("out");
    std::fs::create_dir_all(&out).unwrap();
    let url_a = spawn_node(&work.join("data-a"), allowlist.clone()).await;
    let location = out.join("mini-c").join("snapshot");
    {
        let (url_a, location) = (url_a.clone(), location.clone());
        tokio::task::spawn_blocking(move || seed_and_snapshot(&url_a, &location))
            .await
            .unwrap();
    }
    let archive = out.join(format!("mini-c-{PIN8}.hubpack.tar.zst"));
    {
        let files = vec![
            PackFileEntry {
                path: "limits.h".into(),
                lang: "c".into(),
                bytes: 300,
                licence: "MIT".into(),
            },
            PackFileEntry {
                path: "hash.c".into(),
                lang: "c".into(),
                bytes: 200,
                licence: "MIT".into(),
            },
        ];
        let (archive, location, seed) = (archive.clone(), location.clone(), seed.clone());
        tokio::task::spawn_blocking(move || {
            pack::write_pack(
                &archive,
                &manifest(),
                &sample_defs(),
                &files,
                &location,
                &seed,
            )
            .unwrap();
        })
        .await
        .unwrap();
    }
    let sig = out.join(format!("mini-c-{PIN8}.hubpack.tar.zst.sig"));
    assert!(
        archive.exists() && sig.exists(),
        "pack and signature written"
    );

    // ── A. no hosted hub: pull on first use, then answer from the cache ──────
    {
        let hub = work.join("hub-a");
        let code = work.join("code-a");
        let published = publish(&archive, &sig, &work.join("net-a"), &hub);
        set_env(&hub, &code, &scratch_home, &public);
        let url_b = spawn_node(&work.join("data-b"), allowlist.clone()).await;
        let case = |hosted, args| Case {
            hub: hub.clone(),
            cwd: cwd.clone(),
            url: Some(url_b.clone()),
            launcher: forbidden_launcher(),
            hosted,
            args,
        };

        let first = run(case(HostedKind::None, def_args())).await;
        assert_eq!(first.exit, EXIT_OK, "stderr: {:?}", first.stderr);
        assert!(first.stdout.contains("value: 128"), "{}", first.stdout);
        assert!(
            first.stdout.contains("answered from: local pack"),
            "{}",
            first.stdout
        );
        assert!(
            first.stdout.starts_with("mini-c  pin 2026-10-02 ("),
            "{}",
            first.stdout
        );
        let pack_dir = hub.join("packs").join("mini-c").join(PIN8);
        assert!(pack_dir.join("pack.json").is_file(), "the pack is cached");
        assert!(
            pack_dir.join("last_used").is_file(),
            "every answer touches last_used"
        );
        assert!(
            code.join("state").join("mini-c.json").is_file(),
            "the ledger is written"
        );

        // The "network" goes away: a second question cannot be pulling anything,
        // and the hosted hub must not be asked either.
        std::fs::remove_file(&published.archive).unwrap();
        std::fs::remove_file(&published.sig).unwrap();
        let again = run(case(HostedKind::Forbidden, def_args())).await;
        assert_eq!(again.exit, EXIT_OK, "stderr: {:?}", again.stderr);
        assert_eq!(
            again.answer.as_ref().unwrap().answered_from,
            AnsweredFrom::LocalPack
        );
        assert!(again.stdout.contains("value: 128"));

        // A how-does-it-work question and a file listing come off the same pack.
        let mut how = AskArgs::new("MINI_LIMIT clamp ceiling");
        how.corpus = Some("mini-c".to_string());
        how.mode = ModeRequest::How;
        let how = run(case(HostedKind::Forbidden, how)).await;
        assert_eq!(
            how.exit, EXIT_OK,
            "stderr: {:?}\nstdout: {}",
            how.stderr, how.stdout
        );
        let ans = how.answer.unwrap();
        assert_eq!(ans.mode, AnswerMode::How);
        assert_eq!(ans.hits[0].file, "mini-c/limits.h");
        assert_eq!(ans.hits[0].kind, "define", "the matching definition");
        assert_eq!(ans.hits[0].line, 2, "the definition's line in the record");
        assert!(ans.hits[0].text.contains("MINI_LIMIT"));

        let mut files = AskArgs::new("unsigned return");
        files.corpus = Some("mini-c".to_string());
        files.mode = ModeRequest::Files;
        let files = run(case(HostedKind::Forbidden, files)).await;
        assert_eq!(files.exit, EXIT_OK, "stderr: {:?}", files.stderr);
        let ans = files.answer.unwrap();
        assert_eq!(ans.mode, AnswerMode::Files);
        assert!(ans
            .hits
            .iter()
            .all(|h| h.kind == "file" && h.text == "licence: MIT"));
        assert!(
            ans.hits.iter().any(|h| h.file == "mini-c/hash.c"),
            "{:?}",
            ans.hits
        );

        // `--max-tokens` is honoured on a real answer: the first hit is kept,
        // its text shortened, and the answer says it was cut.
        let mut capped = def_args();
        capped.max_tokens = Some(10);
        let capped = run(case(HostedKind::None, capped)).await;
        assert_eq!(capped.exit, EXIT_OK, "stderr: {:?}", capped.stderr);
        let ans = capped.answer.unwrap();
        assert!(ans.truncated, "{ans:?}");
        assert!(ans.hits[0].text.ends_with('…'), "{:?}", ans.hits[0].text);
    }

    // ── B. hosted answers now, a detached pull completes behind it ───────────
    {
        let hub = work.join("hub-b");
        let code = work.join("code-b");
        publish(&archive, &sig, &work.join("net-b"), &hub);
        set_env(&hub, &code, &scratch_home, &public);
        let url = spawn_node(&work.join("data-b2"), allowlist.clone()).await;
        let case = |hosted, launcher| Case {
            hub: hub.clone(),
            cwd: cwd.clone(),
            url: Some(url.clone()),
            launcher,
            hosted,
            args: def_args(),
        };

        let first = run(case(HostedKind::Canned, test_exe_launcher())).await;
        assert_eq!(first.exit, EXIT_OK, "stderr: {:?}", first.stderr);
        assert_eq!(
            first.answer.as_ref().unwrap().answered_from,
            AnsweredFrom::Hosted
        );
        assert!(
            first.stdout.contains("answered from: hosted hub"),
            "{}",
            first.stdout
        );
        assert!(
            first.stderr.iter().any(|l| l.contains("background")),
            "{:?}",
            first.stderr
        );
        assert!(
            hub.join("pulls").join("mini-c.pid").is_file(),
            "the pull's PID is recorded"
        );
        // The pull finishes on its own: the ledger is written last.
        let ledger = code.join("state").join("mini-c.json");
        wait_for("the background pull", Duration::from_secs(90), || {
            ledger.is_file()
        })
        .await;
        assert!(
            hub.join("packs")
                .join("mini-c")
                .join(PIN8)
                .join("pack.json")
                .is_file(),
            "log: {}",
            std::fs::read_to_string(hub.join("pulls").join("mini-c.log")).unwrap_or_default()
        );

        let second = run(case(HostedKind::Forbidden, forbidden_launcher())).await;
        assert_eq!(second.exit, EXIT_OK, "stderr: {:?}", second.stderr);
        assert_eq!(
            second.answer.unwrap().answered_from,
            AnsweredFrom::LocalPack
        );
    }

    // ── C. the automatic node: start, pull into it, answer, stop exactly it ──
    #[cfg(unix)]
    {
        let hub = work.join("hub-c");
        let code = work.join("code-c");
        publish(&archive, &sig, &work.join("net-c"), &hub);
        set_env(&hub, &code, &scratch_home, &public);
        // A loopback port with nothing on it: the requested node is "down".
        let silent = std::net::TcpListener::bind("127.0.0.1:0")
            .unwrap()
            .local_addr()
            .unwrap()
            .port();
        let silent_url = format!("http://127.0.0.1:{silent}");
        // A second process of the same executable that is NOT the node.
        let decoy = Command::new(std::env::current_exe().unwrap())
            .args([
                "--ignored",
                "--exact",
                "child_main",
                "--nocapture",
                "--",
                "decoy",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .unwrap();
        let decoy_pid = decoy.id();
        let mut reaper = Reaper {
            hub: hub.clone(),
            decoy: Some(decoy),
        };

        let out = run(Case {
            hub: hub.clone(),
            cwd: cwd.clone(),
            url: Some(silent_url.clone()),
            launcher: test_exe_launcher(),
            hosted: HostedKind::None,
            args: def_args(),
        })
        .await;
        assert_eq!(out.exit, EXIT_OK, "stderr: {:?}", out.stderr);
        assert!(out.stdout.contains("value: 128"), "{}", out.stdout);

        let pid: u32 = std::fs::read_to_string(hub.join("node.pid"))
            .expect("node.pid is recorded")
            .trim()
            .parse()
            .unwrap();
        let port: u16 = std::fs::read_to_string(hub.join("node.port"))
            .expect("node.port is recorded")
            .trim()
            .parse()
            .unwrap();
        assert!(port >= 9300, "auto node port {port} must be >= 9300");
        assert_ne!(pid, decoy_pid);
        assert!(
            probe(format!("http://127.0.0.1:{port}"), Duration::from_secs(2))
                .await
                .is_some(),
            "the recorded node answers"
        );
        // Its flags and config are what `ask` promised.
        let cfg = std::fs::read_to_string(hub.join("node.toml")).unwrap();
        assert!(cfg.contains("snapshot_repo_allowlist"), "{cfg}");
        assert!(
            cfg.contains(&hub.join("packs").to_string_lossy().into_owned()),
            "{cfg}"
        );

        // A second question finds the recorded node and starts nothing.
        let again = run(Case {
            hub: hub.clone(),
            cwd: cwd.clone(),
            url: Some(silent_url),
            launcher: forbidden_launcher(),
            hosted: HostedKind::Forbidden,
            args: def_args(),
        })
        .await;
        assert_eq!(again.exit, EXIT_OK, "stderr: {:?}", again.stderr);
        assert_eq!(
            std::fs::read_to_string(hub.join("node.pid"))
                .unwrap()
                .trim(),
            pid.to_string(),
            "the same node, not a new one"
        );

        // `hub stop` stops exactly the recorded PID.
        let hub_stop = hub.clone();
        let outcome = tokio::task::spawn_blocking(move || node::stop_node(&hub_stop))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(outcome, StopOutcome::Stopped { pid });
        assert!(
            probe(format!("http://127.0.0.1:{port}"), Duration::from_secs(1))
                .await
                .is_none(),
            "the node is gone"
        );
        let decoy = reaper.decoy.as_mut().unwrap();
        assert!(
            decoy.try_wait().unwrap().is_none(),
            "the look-alike process survives"
        );
        assert!(!hub.join("node.pid").exists() && !hub.join("node.port").exists());
    }

    // ── D. a pull evicts the least recently used pack that busts the budget ──
    #[cfg(unix)]
    {
        let hub = work.join("hub-d");
        let code = work.join("code-d");
        publish(&archive, &sig, &work.join("net-d"), &hub);
        set_env(&hub, &code, &scratch_home, &public);
        // Two other packs, each a 3 GiB sparse file (no disk is written): over the
        // 4 GiB budget together. "stale" was used longest ago.
        for (slug, used_ago) in [("stale", 90_000u64), ("recent", 60)] {
            let dir = hub.join("packs").join(slug).join("eeee0001");
            std::fs::create_dir_all(&dir).unwrap();
            std::fs::write(dir.join("pack.json"), "{}").unwrap();
            let big = std::fs::File::create(dir.join("big")).unwrap();
            big.set_len(3 * 1024 * 1024 * 1024).unwrap();
            let used = dir.join("last_used");
            std::fs::write(&used, "x").unwrap();
            std::fs::File::options()
                .write(true)
                .open(&used)
                .unwrap()
                .set_modified(std::time::SystemTime::now() - Duration::from_secs(used_ago))
                .unwrap();
        }
        let url = spawn_node(&work.join("data-d"), allowlist.clone()).await;
        let out = run(Case {
            hub: hub.clone(),
            cwd: cwd.clone(),
            url: Some(url),
            launcher: forbidden_launcher(),
            hosted: HostedKind::None,
            args: def_args(),
        })
        .await;
        assert_eq!(out.exit, EXIT_OK, "stderr: {:?}", out.stderr);
        assert!(
            !hub.join("packs").join("stale").exists(),
            "the least recently used pack is evicted"
        );
        assert!(
            hub.join("packs").join("recent").join("eeee0001").exists(),
            "the more recently used pack stays: evicting one was enough"
        );
        assert!(hub
            .join("packs")
            .join("mini-c")
            .join(PIN8)
            .join("pack.json")
            .is_file());
    }

    // ── E. offline, nothing cached: exit 1, and no node is started to say so ─
    {
        let hub = work.join("hub-e");
        let code = work.join("code-e");
        publish(&archive, &sig, &work.join("net-e"), &hub);
        set_env(&hub, &code, &scratch_home, &public);
        let mut args = def_args();
        args.offline = true;
        let out = run(Case {
            hub: hub.clone(),
            cwd: cwd.clone(),
            url: Some("http://127.0.0.1:1".to_string()),
            launcher: forbidden_launcher(),
            hosted: HostedKind::Forbidden,
            args,
        })
        .await;
        assert_eq!(out.exit, EXIT_NO_ANSWER);
        let msg = out.stderr.join("\n");
        assert!(msg.contains("--offline"), "{msg}");
        assert!(msg.contains("run: xerj hub pull mini-c"), "{msg}");
        assert!(!hub.join("node.pid").exists(), "no node was started");
        assert!(!hub.join("packs").exists(), "nothing was downloaded");
    }

    // ── G. an EXCLUDED corpus: no pull, and no hint to pull it, offline or not ─
    {
        let hub = work.join("hub-g");
        let code = work.join("code-g");
        publish(&archive, &sig, &work.join("net-g"), &hub);
        set_catalogue_field(&hub, "licence_class", json!("excluded"));
        set_env(&hub, &code, &scratch_home, &public);
        for flag in ["--offline", "--no-fetch", "(neither)"] {
            let mut args = def_args();
            match flag {
                "--offline" => args.offline = true,
                "--no-fetch" => args.no_fetch = true,
                _ => {}
            }
            let out = run(Case {
                hub: hub.clone(),
                cwd: cwd.clone(),
                url: Some("http://127.0.0.1:1".to_string()),
                launcher: forbidden_launcher(),
                hosted: HostedKind::None,
                args,
            })
            .await;
            assert_eq!(out.exit, EXIT_NO_ANSWER, "{flag}");
            let msg = out.stderr.join("\n");
            assert!(msg.contains("excluded licence class"), "{flag}: {msg}");
            assert!(
                !msg.contains("xerj hub pull") && !msg.contains("run:"),
                "{flag}: a hint to pull an excluded corpus is a way round the policy: {msg}"
            );
            assert!(!hub.join("packs").exists(), "{flag}: nothing downloaded");
            assert!(!hub.join("node.pid").exists(), "{flag}: no node started");
        }
        // The command the old hint named refuses it too.
        let rc = tokio::task::spawn_blocking({
            let url = "http://127.0.0.1:1".to_string();
            move || {
                xerj_hub::cli::run_hub_cli(&[
                    "pull".into(),
                    "mini-c".into(),
                    "--url".into(),
                    url,
                    "--quiet".into(),
                ])
            }
        })
        .await
        .unwrap();
        assert_eq!(rc, 1, "`xerj hub pull` itself refuses an excluded corpus");
        assert!(!hub.join("packs").exists());
    }

    // ── F. a pull killed mid-run does not wedge its corpus ───────────────────
    // The old pull lock was a directory removed only by the pull's own destructor:
    // SIGKILL, an OOM kill or an agent's tool timeout left the corpus un-pullable
    // for half an hour, with no owner recorded. It is an OS lock now.
    #[cfg(unix)]
    {
        let hub = work.join("hub-f");
        let code = work.join("code-f");
        publish(&archive, &sig, &work.join("net-f"), &hub);
        let real_catalogue = std::fs::read(hub.join("catalogue.json")).unwrap();
        set_env(&hub, &code, &scratch_home, &public);
        let url = spawn_node(&work.join("data-f"), allowlist.clone()).await;

        // A pack URL that never delivers a byte: a listener that is never
        // accepted. The kernel completes the handshake, the request is sent, and
        // no response comes, so the pull takes its lock, starts "downloading" and
        // blocks reading the reply. (A FIFO no longer works: since #1733 a
        // file:// pack must be a regular file, so the pull fails before it blocks.)
        let silent = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        set_catalogue_field(
            &hub,
            "pack_url",
            json!(format!(
                "http://{}/never.hubpack.tar.zst",
                silent.local_addr().unwrap()
            )),
        );

        // The victim is a separate process running `xerj hub pull` (this binary).
        let mut victim = Command::new(std::env::current_exe().unwrap())
            .args([
                "--ignored",
                "--exact",
                "child_main",
                "--nocapture",
                "--",
                "hub",
                "pull",
                "mini-c",
                "--url",
                &url,
                "--quiet",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()
            .unwrap();
        let lock_path = hub
            .join("packs")
            .join("mini-c")
            .join(format!("{PIN8}.lock"));
        wait_for(
            "the victim to take the pull lock",
            Duration::from_secs(90),
            || lock_is_held(&lock_path),
        )
        .await;
        assert!(
            hub.join("packs")
                .join("mini-c")
                .join(format!("{PIN8}.tmp"))
                .is_dir(),
            "it is mid-pull: past the lock, into its temp dir"
        );
        assert!(
            victim.try_wait().unwrap().is_none(),
            "still blocked in the download"
        );

        // SIGKILL: no destructor runs. (The kernel closes its descriptors.)
        victim.kill().unwrap();
        victim.wait().unwrap();
        assert!(!lock_is_held(&lock_path), "the dead process holds nothing");

        // The retry is NOT blocked — and, pointed at the real pack, it completes.
        std::fs::write(hub.join("catalogue.json"), &real_catalogue).unwrap();
        let t0 = Instant::now();
        let rc = tokio::task::spawn_blocking({
            let url = url.clone();
            move || {
                xerj_hub::cli::run_hub_cli(&[
                    "pull".into(),
                    "mini-c".into(),
                    "--url".into(),
                    url,
                    "--quiet".into(),
                ])
            }
        })
        .await
        .unwrap();
        assert_eq!(rc, 0, "the retry after a killed pull succeeds");
        assert!(
            t0.elapsed() < Duration::from_secs(45),
            "and does not sit out a 30-minute lock: {:?}",
            t0.elapsed()
        );
        assert!(hub
            .join("packs")
            .join("mini-c")
            .join(PIN8)
            .join("pack.json")
            .is_file());
        drop(silent);
    }
}

/// Set one field of the first catalogue entry in `<hub>/catalogue.json`.
fn set_catalogue_field(hub: &Path, field: &str, value: serde_json::Value) {
    let path = hub.join("catalogue.json");
    let mut cat: serde_json::Value =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    cat["corpora"][0][field] = value;
    std::fs::write(&path, serde_json::to_vec(&cat).unwrap()).unwrap();
}

/// Is somebody holding the lock file `path`? (Tries it, and lets go again.)
#[cfg(unix)]
fn lock_is_held(path: &Path) -> bool {
    let Ok(f) = std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .create(false)
        .open(path)
    else {
        return false;
    };
    match f.try_lock() {
        Ok(()) => {
            let _ = f.unlock();
            false
        }
        Err(std::fs::TryLockError::WouldBlock) => true,
        Err(std::fs::TryLockError::Error(e)) => panic!("cannot probe {}: {e}", path.display()),
    }
}

//! The CI-side verifier (`tools/hub-packs/ed25519.sh`, openssl) and the client
//! (`verify_bytes`, ring) must agree on the key and signature formats, or the
//! workflows could prove a signature no client accepts (or refuse one every
//! client accepts). Checked with a throwaway keypair: the real seed lives only in
//! the `HUB_SIGNING_SEED` secret.
//!
//! Skipped (with a note) where `bash`, `openssl` or `xxd` is missing — the
//! workflows that use the script run on ubuntu, where all three are present.
#![cfg(unix)]

use std::path::{Path, PathBuf};
use std::process::Command;

use xerj_autoindex::harvest::sign::{generate_keypair, sign_bytes, verify_bytes};
use xerj_hub::HUB_PUBKEY_HEX;

fn script() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../tools/hub-packs/ed25519.sh")
}

fn have(tool: &str) -> bool {
    Command::new("sh")
        .args(["-c", &format!("command -v {tool}")])
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

fn sh(args: &[&str]) -> (bool, String) {
    let out = Command::new("bash")
        .arg(script())
        .args(args)
        .output()
        .unwrap();
    (
        out.status.success(),
        String::from_utf8_lossy(&out.stdout).trim().to_string(),
    )
}

#[test]
fn ed25519_sh_and_verify_bytes_agree() {
    if !["bash", "openssl", "xxd"].iter().all(|t| have(t)) {
        eprintln!("skipped: needs bash, openssl and xxd");
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let (seed, public) = generate_keypair().unwrap();
    let seed_file = dir.path().join("hub.key");
    std::fs::write(&seed_file, &seed).unwrap();

    // derive: the script gets the same public half from the seed as ring does.
    let (ok, derived) = sh(&["derive", seed_file.to_str().unwrap()]);
    assert!(ok, "derive failed");
    assert_eq!(
        derived, public,
        "openssl and ring derive different public keys"
    );

    // A signature from the client's signer verifies in the script…
    let msg = dir.path().join("catalogue.json");
    std::fs::write(&msg, br#"{"format_version":1}"#).unwrap();
    let sig = sign_bytes(&std::fs::read(&msg).unwrap(), &seed).unwrap();
    let sig_file = dir.path().join("catalogue.json.sig");
    std::fs::write(&sig_file, format!("{sig}\n")).unwrap();
    let (m, s) = (msg.to_str().unwrap(), sig_file.to_str().unwrap());
    assert!(
        sh(&["verify", &public, m, s]).0,
        "script rejects a good sig"
    );
    verify_bytes(&std::fs::read(&msg).unwrap(), &sig, &public).unwrap();

    // …and both refuse it under the compiled-in hub key and after a flipped byte.
    assert!(
        !sh(&["verify", HUB_PUBKEY_HEX, m, s]).0,
        "script accepts a test-key signature under HUB_PUBKEY_HEX"
    );
    let err = verify_bytes(&std::fs::read(&msg).unwrap(), &sig, HUB_PUBKEY_HEX).unwrap_err();
    assert!(
        format!("{err:#}").contains("does not verify"),
        "HUB_PUBKEY_HEX must parse as a key and fail only the signature check: {err:#}"
    );
    std::fs::write(&msg, br#"{"format_version":2}"#).unwrap();
    assert!(
        !sh(&["verify", &public, m, s]).0,
        "script accepts a flipped byte"
    );
    assert!(verify_bytes(&std::fs::read(&msg).unwrap(), &sig, &public).is_err());
}

//! Regression for zero-config routing against a catalogue the shape of the live
//! hub (468 corpora on 2026-10-21, `https://hub.xerj.org/api/v1/catalogue.json`).
//!
//! The fixture keeps each corpus's slug, topics, description and licence class.
//! Sketches are rebuilt here so that every corpus reports every token of the
//! two Swift questions: that is the saturated-Bloom failure, where `qwik` and
//! `docker-docs` tie with `swift-book`. Routing has to ignore that and follow
//! the name.

use std::fs;
use std::path::Path;

use xerj_hub::router::{route, Routing};
use xerj_hub::{Catalogue, CatalogueEntry, LicenceClass};

/// Tokens both failing questions tokenize to. Inserted into every sketch.
const POISON: &[&str] = &[
    "how", "use", "async", "let", "swift", "Swift", "result", "Result", "type", "map",
];

fn licence(class: &str) -> LicenceClass {
    match class {
        "approach-only" => LicenceClass::ApproachOnly,
        "excluded" => LicenceClass::Excluded,
        _ => LicenceClass::AdaptWithAttribution,
    }
}

fn catalogue() -> Catalogue {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/hub-catalogue-identity.jsonl");
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    let corpora = text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            let row: serde_json::Value = serde_json::from_str(line).expect("fixture row");
            let ask_for = row["ask_for"].as_str().unwrap_or("").to_string();
            let mut terms: Vec<String> = ask_for
                .split(|c: char| !c.is_ascii_alphanumeric())
                .filter(|w| w.len() >= 3)
                .map(|w| w.to_ascii_lowercase())
                .collect();
            terms.extend(POISON.iter().map(|s| (*s).to_string()));
            let topics = row["topics"]
                .as_array()
                .map(|a| {
                    a.iter()
                        .filter_map(|v| v.as_str().map(str::to_string))
                        .collect()
                })
                .unwrap_or_default();
            CatalogueEntry {
                slug: row["slug"].as_str().unwrap_or("").to_string(),
                domain: row["domain"].as_str().unwrap_or("").to_string(),
                topics,
                ask_for,
                upstream: String::new(),
                pin_sha: "0".repeat(40),
                pin_date: "2026-10-21".to_string(),
                refresh_cadence_days: 7,
                licence_spdx: "Apache-2.0".to_string(),
                licence_class: licence(row["licence_class"].as_str().unwrap_or("")),
                pack_bytes: 0,
                pack_url: String::new(),
                pack_sha256: String::new(),
                sig_url: String::new(),
                dependency_names: Vec::new(),
                quality_grade: None,
                term_sketch: xerj_hub::sketch::build(terms),
            }
        })
        .collect();
    Catalogue {
        format_version: 1,
        generated_at: "2026-10-21T16:40:13Z".to_string(),
        corpora,
    }
}

fn picked(routing: &Routing) -> Vec<String> {
    match routing {
        Routing::Confident(slug) => vec![slug.clone()],
        Routing::Group(slugs) | Routing::Ambiguous(slugs) => slugs.clone(),
        Routing::NoCorpus | Routing::NoCoverage => Vec::new(),
    }
}

fn route_q(cat: &Catalogue, q: &str) -> Routing {
    let dir = tempfile::tempdir().unwrap();
    fs::create_dir(dir.path().join(".git")).unwrap();
    route(q, dir.path(), cat, None, &[])
}

#[test]
fn swift_questions_route_to_the_swift_corpora_on_the_live_catalogue_shape() {
    let cat = catalogue();
    assert!(
        cat.corpora.len() >= 400,
        "fixture should mirror the live hub, got {} corpora",
        cat.corpora.len()
    );

    let async_let = route_q(&cat, "how do I use async let in Swift");
    assert_eq!(
        picked(&async_let),
        vec!["swift-book".to_string(), "swift-evolution".to_string()],
        "async let: {async_let:?}"
    );
    assert!(
        matches!(async_let, Routing::Group(_)),
        "a tie between the two Swift corpora is a group, not exit 4: {async_let:?}"
    );

    let result_map = route_q(&cat, "Swift Result type map");
    assert_eq!(
        picked(&result_map),
        vec!["swift-evolution".to_string(), "swift-book".to_string()],
        "Result map: {result_map:?}"
    );
    for unrelated in ["qwik", "docker-docs", "harper", "oss-review-toolkit"] {
        assert!(
            !picked(&async_let).iter().any(|s| s == unrelated),
            "{unrelated} tied with swift-book"
        );
        assert!(
            !picked(&result_map).iter().any(|s| s == unrelated),
            "{unrelated} tied on the Result query"
        );
    }
}

#[test]
fn a_broad_language_with_many_corpora_stays_ambiguous_and_short() {
    let cat = catalogue();
    let routing = route_q(&cat, "python");
    match routing {
        Routing::Ambiguous(slugs) => {
            assert!(
                (2..=5).contains(&slugs.len()),
                "a few ranked candidates, not the whole catalogue: {slugs:?}"
            );
            for slug in &slugs {
                let entry = cat
                    .corpora
                    .iter()
                    .find(|e| &e.slug == slug)
                    .unwrap_or_else(|| panic!("missing {slug}"));
                let blob = format!("{} {}", entry.slug, entry.ask_for).to_ascii_lowercase();
                assert!(
                    blob.split(|c: char| !c.is_ascii_alphanumeric())
                        .any(|w| w == "python"),
                    "{slug} is not a Python corpus: {}",
                    entry.ask_for
                );
            }
        }
        other => panic!("expected Ambiguous, got {other:?}"),
    }
}

//! A build with no hub signing key can verify no catalogue and no pack. A real
//! key is compiled in now, so the test asks for that state explicitly with
//! `XERJ_HUB_PUBKEY=none` (`HUB_PUBKEY_NONE`). Every hub surface must say so
//! plainly with exit 5 — not fail on whatever the hub URL serves (a 200 HTML
//! page made `xerj ask` print "parse catalogue JSON: expected value at line 1
//! column 1", exit 1) and not send an MCP agent to `xerj hub sync`, which
//! cannot help.
//!
//! One test in its own binary: it owns the process environment.

use xerj_hub::ask::{self, EXIT_NO_KEY};
use xerj_hub::cli::{run_ask, run_hub_cli};

#[test]
fn every_hub_surface_says_the_build_has_no_key() {
    std::env::set_var("XERJ_HUB_PUBKEY", xerj_common::hub::HUB_PUBKEY_NONE);
    assert!(
        !xerj_common::hub::hub_key_configured(),
        "precondition: the override takes the key away"
    );
    let home = tempfile::tempdir().unwrap();
    std::env::set_var("XERJ_HUB_HOME", home.path());
    // A hub that serves a 200 HTML page for every path, like hub.xerj.org's
    // site fallback does for the unpublished API — the case that misled.
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let hub_url = format!("http://{}", listener.local_addr().unwrap());
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        for conn in listener.incoming() {
            let Ok(mut c) = conn else { continue };
            let mut buf = [0u8; 4096];
            let _ = c.read(&mut buf);
            let body = "<!doctype html><html><body>hub</body></html>";
            let _ = write!(
                c,
                "HTTP/1.1 200 OK\r\ncontent-type: text/html\r\ncontent-length: {}\r\nconnection: close\r\n\r\n{body}",
                body.len()
            );
        }
    });
    std::env::set_var("XERJ_HUB_URL", &hub_url);

    let s = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<_>>();

    assert_eq!(
        run_ask(&s(&["how does lz4 frame work"])),
        EXIT_NO_KEY,
        "xerj ask"
    );
    assert_eq!(run_hub_cli(&s(&["sync"])), EXIT_NO_KEY, "xerj hub sync");
    assert_eq!(
        run_hub_cli(&s(&["pull", "lz4"])),
        EXIT_NO_KEY,
        "xerj hub pull"
    );

    // The MCP `xerj_hub_find` path: the no-key message, not "run xerj hub sync".
    let err = ask::run_find("how does lz4 frame work", 5).unwrap_err();
    assert!(err.contains("not available in this build"), "{err}");
    assert!(!err.contains("xerj hub sync"), "{err}");

    // Usage errors are still usage errors.
    assert_eq!(run_hub_cli(&s(&["sync", "--bogus"])), 2);
    assert_eq!(run_ask(&s(&["--hosted", "maybe", "q x"])), ask::EXIT_USAGE);
}

//! A loopback node is never reached through a proxy (review finding E8).
//!
//! `HTTP_PROXY` is how a corporate machine gets *out*. The health probe used a
//! default `reqwest` client, which honours it for `127.0.0.1` too: the probe of the
//! silent loopback URL went to the proxy, the proxy's `502 Bad Gateway` page counted
//! as "an HTTP answer, so a node is running", and `xerj ask` declined to start the
//! node it needed — or, with a healthy node, talked to the proxy instead of it.
//!
//! This is its own test binary because `HTTP_PROXY` is process-global: set in the
//! unit-test binary it would redirect every other test's HTTP client.

use std::io::{Read, Write};
use std::net::TcpListener;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::Duration;

use xerj_hub::node::{self, HubNode};

/// A server on an ephemeral loopback port that answers every request with
/// `status`/`body` and counts the requests it received.
fn serve(status: &'static str, body: &'static str, hits: Arc<AtomicUsize>) -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    std::thread::spawn(move || {
        for conn in listener.incoming() {
            let Ok(mut conn) = conn else { continue };
            let hits = hits.clone();
            std::thread::spawn(move || {
                let mut buf = [0u8; 4096];
                if conn.read(&mut buf).unwrap_or(0) == 0 {
                    return; // a connect with no request (a port probe)
                }
                hits.fetch_add(1, Ordering::SeqCst);
                let reply = format!(
                    "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                let _ = conn.write_all(reply.as_bytes());
            });
        }
    });
    port
}

#[test]
fn a_loopback_node_is_reached_directly_and_a_remote_one_still_goes_through_the_proxy() {
    let proxy_hits = Arc::new(AtomicUsize::new(0));
    let node_hits = Arc::new(AtomicUsize::new(0));
    let proxy = serve(
        "502 Bad Gateway",
        r#"{"error":"bad gateway from the corporate proxy"}"#,
        proxy_hits.clone(),
    );
    let node_port = serve("200 OK", r#"{"status":"green"}"#, node_hits.clone());

    // A corporate box: a proxy for everything, and no NO_PROXY that covers loopback.
    for var in ["NO_PROXY", "no_proxy"] {
        std::env::remove_var(var);
    }
    for var in ["HTTP_PROXY", "http_proxy", "ALL_PROXY", "all_proxy"] {
        std::env::set_var(var, format!("http://127.0.0.1:{proxy}"));
    }

    // The node is probed directly.
    let url = format!("http://127.0.0.1:{node_port}");
    let health = node::probe(&url, Duration::from_secs(3)).expect("the node answers");
    assert_eq!(health.http_status, 200);
    assert_eq!(health.status.as_deref(), Some("green"));
    assert_eq!(
        proxy_hits.load(Ordering::SeqCst),
        0,
        "the proxy must never be asked about a loopback node"
    );
    assert!(node_hits.load(Ordering::SeqCst) >= 1);

    // So is every request the client makes to it.
    let client = HubNode::connect_insecure(&url).unwrap();
    client
        .wait_until_reachable(Duration::from_secs(3))
        .expect("reachable");
    client.request_ok("GET", "/_cluster/health", None).unwrap();
    assert_eq!(proxy_hits.load(Ordering::SeqCst), 0);

    // A loopback port with NOTHING on it is silent — it is not "the proxy said 502
    // so a node answers", which is what made the hub decline to start its own.
    let silent = TcpListener::bind("127.0.0.1:0")
        .unwrap()
        .local_addr()
        .unwrap()
        .port();
    assert!(
        node::probe(
            &format!("http://127.0.0.1:{silent}"),
            Duration::from_secs(2)
        )
        .is_none(),
        "nothing listens there, so nothing answers"
    );
    assert_eq!(proxy_hits.load(Ordering::SeqCst), 0);

    // A remote node keeps the system proxy settings: someone behind a corporate
    // proxy reaching a node elsewhere still works.
    let remote = node::probe("http://node.example.invalid:9200", Duration::from_secs(3))
        .expect("the proxy answered for it");
    assert_eq!(remote.http_status, 502);
    assert!(proxy_hits.load(Ordering::SeqCst) >= 1);
}

//! Corpus Hub v2 — the pack build → pull → `def` roundtrip (plan §2/§3 "Tests").
//!
//! This boots REAL nodes in-process (an ephemeral TCP port each, the way
//! `xerj-api`'s endpoint tests build a router) so the snapshot/restore HTTP
//! calls run end to end:
//!
//! - build a mini-c pack on node A (create a `-defs` index, bulk the defs,
//!   snapshot it, [`pack::write_pack`] + a test keypair);
//! - pull it into node B's empty data dir through the real `xerj hub pull` CLI,
//!   verifying sha256 THEN signature before extracting;
//! - assert `def::lookup` answers `MINI_LIMIT = 128` and the state ledger says
//!   `source: hubpack`;
//! - a flipped archive byte makes `pull` exit 3 and extract nothing;
//! - a second pull of the same pin says "already present";
//! - a `format_version: 2` pack is refused (exit 3).
//!
//! The archive-level guarantees (verify-before-extract, SHA256SUMS coverage,
//! format-version refusal) are also covered by `pack.rs`'s unit tests; this file
//! adds the parts that need a live node: restore and the `def` query over it.
//!
//! One `#[tokio::test]` holds the whole flow because it mutates process-global
//! env (`XERJ_CODE_HOME`, `XERJ_HUB_HOME`, `XERJ_HUB_PUBKEY`) between scenarios.

use std::path::{Path, PathBuf};
use std::time::Duration;

use serde_json::json;
use sha2::{Digest, Sha256};

use xerj_autoindex::harvest::sign::generate_keypair;
use xerj_hub::node::HubNode;
use xerj_hub::pack::{self, PackFileEntry};
use xerj_hub::{
    Catalogue, CatalogueEntry, DefRecord, LicenceClass, PackIndex, PackManifest, PackSource,
    Sketch, AUTO_PULL_MAX_BYTES, CATALOGUE_FORMAT_VERSION, DISK_BUDGET_BYTES, PACK_FORMAT_VERSION,
};

const PIN_SHA: &str = "0774d05537f9762f838f7ab541b7765f1a729cb5";
const PIN8: &str = "0774d055";
const PIN_DATE: &str = "2026-10-02";
const PREFIX: &str = "xc-mini-c-b1";

/// Boot an es-compat node on an ephemeral port with `data_dir` and the given
/// snapshot-repo allowlist, and wait until it answers.
async fn spawn_node(data_dir: &Path, allowlist: Vec<String>) -> String {
    std::fs::create_dir_all(data_dir).unwrap();
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = data_dir.to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.limits.snapshot_repo_allowlist = allowlist;
    let metrics = xerj_common::metrics::Metrics::new().unwrap();
    let engine = xerj_engine::Engine::new(config.clone()).unwrap();
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    let app = xerj_api::router::build_es_compat_router(state);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    tokio::spawn(async move {
        let _ = axum::serve(listener, app.into_make_service()).await;
    });
    let url = format!("http://127.0.0.1:{port}");
    let probe = url.clone();
    tokio::task::spawn_blocking(move || {
        HubNode::connect(&probe)
            .unwrap()
            .wait_until_reachable(Duration::from_secs(30))
            .unwrap();
    })
    .await
    .unwrap();
    url
}

/// The defs the test indexes and packs. `MINI_LIMIT` is the §3 lookup target.
fn sample_defs() -> Vec<DefRecord> {
    vec![
        DefRecord {
            symbol: "MINI_LIMIT".into(),
            kind: "define".into(),
            lang: "c".into(),
            file: "limits.h".into(),
            line: 5,
            text: "#define MINI_LIMIT 128".into(),
            value: Some("128".into()),
        },
