/// The signed bytes of a one-corpus catalogue: `(catalogue.json, signature)`.
fn signed_catalogue(entry: CatalogueEntry, seed: &str) -> (Vec<u8>, String) {
    let cat = Catalogue {
        format_version: CATALOGUE_FORMAT_VERSION,
        generated_at: "2026-10-14T00:00:00Z".into(),
        corpora: vec![entry],
    };
    let bytes = canonical_json(&cat).unwrap();
    let sig = sign_bytes(&bytes, seed).unwrap();
    (bytes, sig)
}

/// A throwaway local "hub": serves whatever catalogue it currently holds at
/// `/api/v1/catalogue.json` and its signature at `….sig`, for as many requests as
/// come.
struct TinyHub {
    url: String,
    addr: std::net::SocketAddr,
    body: Arc<Mutex<(Vec<u8>, String)>>,
    stop: Arc<AtomicBool>,
    handle: Option<std::thread::JoinHandle<()>>,
}

impl TinyHub {
    fn start(initial: (Vec<u8>, String)) -> TinyHub {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let body = Arc::new(Mutex::new(initial));
        let stop = Arc::new(AtomicBool::new(false));
        let (b, s) = (body.clone(), stop.clone());
        let handle = std::thread::spawn(move || {
            while let Ok((mut stream, _)) = listener.accept() {
                if s.load(Ordering::SeqCst) {
                    break;
                }
                let mut buf = [0u8; 4096];
                let n = stream.read(&mut buf).unwrap_or(0);
                let req = String::from_utf8_lossy(&buf[..n]).into_owned();
                let first = req.lines().next().unwrap_or("");
                let (cat, sig) = b.lock().unwrap().clone();
                let payload: Vec<u8> = if first.contains(".sig") {
                    sig.into_bytes()
                } else {
                    cat
                };
                let head = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\n\
                     Content-Length: {}\r\nConnection: close\r\n\r\n",
                    payload.len()
                );
                let _ = stream.write_all(head.as_bytes());
                let _ = stream.write_all(&payload);
                let _ = stream.flush();
            }
        });
        TinyHub {
            url: format!("http://{addr}"),
            addr,
            body,
            stop,
            handle: Some(handle),
        }
    }

    fn serve(&self, bytes: Vec<u8>, sig: String) {
        *self.body.lock().unwrap() = (bytes, sig);
    }

    fn shutdown(mut self) {
        self.stop.store(true, Ordering::SeqCst);
        let _ = TcpStream::connect(self.addr); // wake the accept loop
        if let Some(h) = self.handle.take() {
            h.join().unwrap();
        }
    }
}

/// Drives the real `hub pull` in-process and reads the real ledger, counting the
/// pulls and noting what was on disk around each one.
struct InProcessOps {
    node_url: String,
    hub_home: PathBuf,
    code_home: PathBuf,
    pulls: Arc<AtomicUsize>,
    /// For each pull: was the OLD pin's directory present before it, and were
    /// BOTH directories present when it returned (i.e. sync had not yet removed
    /// the old one).
    around_pull: Arc<Mutex<Vec<(bool, bool)>>>,
}

impl SyncOps for InProcessOps {
    fn pull(&self, slug: &str) -> PullOutcome {
        self.pulls.fetch_add(1, Ordering::SeqCst);
        let old = self.hub_home.join("packs").join(slug).join(OLD.pin8());
        let new = self.hub_home.join("packs").join(slug).join(NEW.pin8());
        let old_before = old.is_dir();
        let rc = xerj_hub::cli::run_hub_cli(&[
            "pull".into(),
            slug.into(),
            "--url".into(),
            self.node_url.clone(),
            "--quiet".into(),
        ]);
        self.around_pull
            .lock()
            .unwrap()
            .push((old_before, old.is_dir() && new.is_dir()));
        if rc == 0 {
            PullOutcome::Done
        } else {
            PullOutcome::Failed {
                code: rc,
                message: format!("hub pull exited {rc}"),
            }
        }
    }

    fn ledger(&self, slug: &str) -> Ledger {
        // The real ledger reader, pointed at this test's code root.
        CliOps::with_program("unused", vec![], None, self.code_home.clone()).ledger(slug)
    }
}

fn age_file(path: &Path, secs: u64) {
    let when = SystemTime::now() - Duration::from_secs(secs);
    std::fs::OpenOptions::new()
        .write(true)
        .open(path)
        .unwrap()
        .set_modified(when)
        .unwrap();
}

/// Every DIRECTORY under the corpus's pack dir: installed pins, plus any
/// half-extracted `<pin8>.tmp` scratch dir a broken pull or sync would leave
/// (which must show up and fail the assertion). The `<pin8>.lock` files are
/// left out on purpose: they are flock files that `crate::flock` never deletes
/// by design (unlinking one lets a waiter lock a dead inode), so they are not
/// state a pull or a sync is responsible for removing.
fn pin_dirs(hub_home: &Path) -> Vec<String> {
    let mut v: Vec<String> = std::fs::read_dir(hub_home.join("packs/mini-c"))
        .map(|rd| {
            rd.flatten()
                .filter(|e| e.file_type().is_ok_and(|t| t.is_dir()))
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .collect()
        })
        .unwrap_or_default();
    v.sort();
    v
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn sync_replaces_the_pack_with_a_newer_pin_and_the_old_dir_is_gone() {
    // One canonical work root so every snapshot location is inside the nodes'
    // allowlist (the engine refuses a repo location outside data_dir or the
    // allowlist; we configure the root, never weaken the check).
    let work_tmp = tempfile::tempdir().unwrap();
    let work = std::fs::canonicalize(work_tmp.path()).unwrap();
    let out = work.join("out");
    std::fs::create_dir_all(&out).unwrap();
    let allowlist = vec![work.to_string_lossy().into_owned()];
    let (seed, public) = generate_keypair().unwrap();

    // ── 1. Build + sign both pins on the builder node ─────────────────────
    let builder = spawn_node(&work.join("data-builder"), allowlist.clone()).await;
    let (old_archive, old_sha, new_archive, new_sha) = {
        let (builder, out, seed) = (builder.clone(), out.clone(), seed.clone());
        tokio::task::spawn_blocking(move || {
            let (oa, os) = build_pack(&builder, &OLD, &out, &seed);
            let (na, ns) = build_pack(&builder, &NEW, &out, &seed);
            (oa, os, na, ns)
        })
        .await
        .unwrap()
    };

    // A corrupted copy of the NEW archive, advertised under a third pin with the
    // original (now mismatching) sha256 — the way a tampered download looks.
    let bad_archive = out.join("mini-c-c0ffee00.hubpack.tar.zst");
    std::fs::copy(&new_archive, &bad_archive).unwrap();
    std::fs::copy(sig_of(&new_archive), sig_of(&bad_archive)).unwrap();
    let mut bytes = std::fs::read(&bad_archive).unwrap();
    let mid = bytes.len() / 2;
    bytes[mid] ^= 0xff;
    std::fs::write(&bad_archive, &bytes).unwrap();

    // ── 2. The local hub starts out advertising the OLD pin ───────────────
    let hub = TinyHub::start(signed_catalogue(
        catalogue_entry(OLD.pin_sha, OLD.pin_date, &old_archive, &old_sha),
        &seed,
    ));
    let client = spawn_node(&work.join("data-client"), allowlist).await;
    let hub_home = work.join("hub-home");
    let code_home = work.join("code-home");
    std::fs::create_dir_all(&hub_home).unwrap();
    std::env::set_var("XERJ_CODE_HOME", &code_home);
    std::env::set_var("XERJ_HUB_HOME", &hub_home);
    std::env::set_var("XERJ_HUB_PUBKEY", &public);
    std::env::set_var("XERJ_HUB_URL", &hub.url);

    // The first pull is the ordinary one: nothing cached yet, so sync has no
    // part in it. Seed the catalogue cache the way a first `ask` would.
    {
        let (bytes, _) = signed_catalogue(
            catalogue_entry(OLD.pin_sha, OLD.pin_date, &old_archive, &old_sha),
            &seed,
        );
        std::fs::write(hub_home.join("catalogue.json"), bytes).unwrap();
    }
    let rc = {
        let client = client.clone();
        tokio::task::spawn_blocking(move || {
            xerj_hub::cli::run_hub_cli(&[
                "pull".into(),
                "mini-c".into(),
                "--url".into(),
                client,
                "--quiet".into(),
            ])
        })
        .await
        .unwrap()
    };
    assert_eq!(rc, 0, "the older pin pulls cleanly");
    assert_eq!(pin_dirs(&hub_home), vec![OLD.pin8()]);
    let limit = |client: String| {
        tokio::task::spawn_blocking(move || {
            let node = HubNode::connect(&client).unwrap();
            let a = xerj_hub::def::lookup(&node, "mini-c", "MINI_LIMIT", 5);
            (
                a.hits.first().and_then(|h| h.value.clone()),
                a.pin_date.clone(),
            )
        })
    };
    assert_eq!(
        limit(client.clone()).await.unwrap(),
        (Some("128".to_string()), OLD.pin_date.to_string()),
        "the old pin answers 128"
    );

    // The shared ops factory: every sync below goes through the real command.
    let pulls = Arc::new(AtomicUsize::new(0));
    let around_pull = Arc::new(Mutex::new(Vec::new()));
    let run = {
        let (client, hub_home, code_home) = (client.clone(), hub_home.clone(), code_home.clone());
        let (pulls, around_pull) = (pulls.clone(), around_pull.clone());
        move || {
            let (client, hub_home, code_home) =
                (client.clone(), hub_home.clone(), code_home.clone());
            let (pulls, around_pull) = (pulls.clone(), around_pull.clone());
            tokio::task::spawn_blocking(move || {
                run_sync_using(&[], &move |_url| {
                    Ok(Box::new(InProcessOps {
                        node_url: client.clone(),
                        hub_home: hub_home.clone(),
                        code_home: code_home.clone(),
                        pulls: pulls.clone(),
                        around_pull: around_pull.clone(),
                    }) as Box<dyn SyncOps>)
                })
            })
        }
    };

    // ── 3. The hub moves to the NEW pin; sync replaces the pack ───────────
    let (bytes, sig) = signed_catalogue(
        catalogue_entry(NEW.pin_sha, NEW.pin_date, &new_archive, &new_sha),
        &seed,
    );
    hub.serve(bytes, sig);
    assert!(
        !hub_home.join("last_sync").exists(),
        "precondition: sync has never run"
    );

    assert_eq!(run().await.unwrap(), 0, "a sync with a newer pin succeeds");

    assert_eq!(
        pin_dirs(&hub_home),
        vec![NEW.pin8()],
        "the new pin replaced the old one and the old directory is gone"
    );
    assert!(hub_home
        .join("packs/mini-c")
        .join(NEW.pin8())
        .join("pack.json")
        .is_file());
    assert_eq!(pulls.load(Ordering::SeqCst), 1, "exactly one pull");
    assert_eq!(
        *around_pull.lock().unwrap(),
        vec![(true, true)],
        "the old pin was on disk before the pull and STILL on disk when it returned: \
         it is removed only after the new pin has restored"
    );
    let ledger: serde_json::Value = serde_json::from_slice(
        &std::fs::read(code_home.join("state").join("mini-c.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(ledger["source"], json!("hubpack"));
    assert_eq!(ledger["pin_sha"], json!(NEW.pin_sha));
    assert_eq!(ledger["index_prefix"], json!(NEW.prefix));
    assert_eq!(
        limit(client.clone()).await.unwrap(),
        (Some("256".to_string()), NEW.pin_date.to_string()),
        "the new pin is the one answering: the restore really ran"
    );
    let stamp = std::fs::read_to_string(hub_home.join("last_sync")).unwrap();
    chrono::DateTime::parse_from_rfc3339(stamp.trim()).expect("last_sync is RFC 3339");
    assert!(
        hub_home.join("catalogue.json").is_file(),
        "the refreshed catalogue was cached"
    );

    // ── 4. Nothing moved: a second sync pulls nothing ─────────────────────
    assert_eq!(run().await.unwrap(), 0);
    assert_eq!(
        pulls.load(Ordering::SeqCst),
        1,
        "a pack already at the catalogue's pin costs no download"
    );
    assert_eq!(pin_dirs(&hub_home), vec![NEW.pin8()]);

    // ── 5. The hub advertises a pin whose archive is corrupt ──────────────
    age_file(&hub_home.join("last_sync"), 3 * 86_400);
    let before = std::fs::metadata(hub_home.join("last_sync"))
        .unwrap()
        .modified()
        .unwrap();
    let (bytes, sig) = signed_catalogue(
        catalogue_entry(BAD_SHA, "2026-10-16", &bad_archive, &new_sha),
        &seed,
    );
    hub.serve(bytes, sig);

    assert_eq!(
        run().await.unwrap(),
        3,
        "a pack that fails verification is exit 3"
    );
    assert_eq!(
        pin_dirs(&hub_home),
        vec![NEW.pin8()],
        "nothing was extracted for the bad pin and the working pin was not touched"
    );
    assert!(!hub_home.join("packs/mini-c/c0ffee00.tmp").exists());
    assert_eq!(
        limit(client.clone()).await.unwrap().0,
        Some("256".to_string()),
        "the pin that works keeps answering"
    );
    assert_eq!(
        std::fs::metadata(hub_home.join("last_sync"))
            .unwrap()
            .modified()
            .unwrap(),
        before,
        "a failed sync does not claim to have synced"
    );

    // ── 6. A catalogue that does not verify is refused, and changes nothing ─
    let (good, good_sig) = signed_catalogue(
        catalogue_entry(OLD.pin_sha, OLD.pin_date, &old_archive, &old_sha),
        &seed,
    );
    let mut tampered = good.clone();
    let mid = tampered.len() / 2;
    tampered[mid] ^= 0x01;
    hub.serve(tampered, good_sig);
    let pulls_before = pulls.load(Ordering::SeqCst);

    assert_eq!(
        run().await.unwrap(),
        1,
        "a catalogue whose signature fails is a refresh failure, exit 1"
    );
    assert_eq!(
        pulls.load(Ordering::SeqCst),
        pulls_before,
        "nothing was pulled"
    );
    assert_eq!(pin_dirs(&hub_home), vec![NEW.pin8()]);

    // Clean up so the env does not leak and the local hub thread ends.
    hub.shutdown();
    for k in [
        "XERJ_CODE_HOME",
        "XERJ_HUB_HOME",
        "XERJ_HUB_PUBKEY",
        "XERJ_HUB_URL",
    ] {
        std::env::remove_var(k);
    }
}

//! Column-oriented storage for log data.
//!
//! Each field of a log record is stored in its own typed column. This allows:
//! - Selective decompression (only load the columns you need)
//! - Type-specific encoding (delta-of-delta for timestamps, dictionary for strings)
//! - SIMD-friendly tight packing of numeric arrays

use byteorder::{LittleEndian, ReadBytesExt, WriteBytesExt};
use serde::{Deserialize, Serialize};
use std::io::{Cursor, Read};
use xerj_common::XerjError;
use xerj_compress::{
    codec::{get_codec, CompressionLevel},
    dictionary::{DictionaryDecoder, DictionaryEncoder},
};

/// Result alias.
pub type Result<T> = std::result::Result<T, XerjError>;

// ─────────────────────────────────────────────────────────────────────────────
// ColumnType
// ─────────────────────────────────────────────────────────────────────────────

/// The data type of a column.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ColumnType {
    /// Unix epoch in nanoseconds, stored with delta-of-delta encoding.
    Timestamp,
    /// 64-bit signed integer.
    I64,
    /// 64-bit float.
    F64,
    /// UTF-8 string — dictionary encoded if cardinality is low.
    String,
    /// Boolean.
    Bool,
    /// Raw binary.
    Binary,
}

// ─────────────────────────────────────────────────────────────────────────────
// Column value
// ─────────────────────────────────────────────────────────────────────────────

/// A typed value that can be stored in a column.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ColumnValue {
    Timestamp(i64),
    I64(i64),
    F64(f64),
    String(String),
    Bool(bool),
    Binary(Vec<u8>),
    Null,
}

// ─────────────────────────────────────────────────────────────────────────────
// Column metadata
// ─────────────────────────────────────────────────────────────────────────────

/// Metadata about a column's contents (used for block skipping).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ColumnStats {
    pub row_count: u64,
    pub null_count: u64,
    pub min_i64: Option<i64>,
    pub max_i64: Option<i64>,
    pub min_f64: Option<f64>,
    pub max_f64: Option<f64>,
}

impl ColumnStats {
    pub fn new() -> Self {
        Self {
            row_count: 0,
            null_count: 0,
            min_i64: None,
            max_i64: None,
            min_f64: None,
            max_f64: None,
        }
    }

    pub fn update(&mut self, value: &ColumnValue) {
        self.row_count += 1;
        match value {
            ColumnValue::Null => self.null_count += 1,
            ColumnValue::Timestamp(v) | ColumnValue::I64(v) => {
                self.min_i64 = Some(self.min_i64.map_or(*v, |m| m.min(*v)));
                self.max_i64 = Some(self.max_i64.map_or(*v, |m| m.max(*v)));
            }
            ColumnValue::F64(v) => {
                self.min_f64 = Some(self.min_f64.map_or(*v, |m| m.min(*v)));
                self.max_f64 = Some(self.max_f64.map_or(*v, |m| m.max(*v)));
            }
            _ => {}
        }
    }
}

impl Default for ColumnStats {
    fn default() -> Self {
        Self::new()
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Column
// ─────────────────────────────────────────────────────────────────────────────

/// An in-memory column holding typed values.
#[derive(Debug, Clone)]
pub struct Column {
    pub name: String,
    pub column_type: ColumnType,
    pub values: Vec<ColumnValue>,
    pub stats: ColumnStats,
}

impl Column {
    pub fn new(name: impl Into<String>, column_type: ColumnType) -> Self {
        Self {
            name: name.into(),
            column_type,
            values: Vec::new(),
            stats: ColumnStats::new(),
        }
    }

    pub fn push(&mut self, value: ColumnValue) {
        self.stats.update(&value);
        self.values.push(value);
    }

    pub fn len(&self) -> usize {
        self.values.len()
    }

    pub fn is_empty(&self) -> bool {
        self.values.is_empty()
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// ColumnWriter
// ─────────────────────────────────────────────────────────────────────────────

/// Encodes and compresses a column for on-disk storage.
///
/// Encoding strategies by type:
/// - Timestamp: delta-of-delta (exploits monotonic increase in log timestamps)
/// - I64: delta encoding
/// - F64: raw bytes (no general-purpose float compression applied here)
/// - String: dictionary encoding if ≤ 256 distinct values, else raw
/// - Bool: bit-packed
/// - Binary: raw, length-prefixed
pub struct ColumnWriter {
    column: Column,
    compression: CompressionLevel,
}

impl ColumnWriter {
    pub fn new(column: Column, compression: CompressionLevel) -> Self {
        Self {
            column,
            compression,
        }
    }

    /// Serialize and compress the column, returning the encoded bytes.
    pub fn encode(&self) -> Result<Vec<u8>> {
        match self.column.column_type {
            ColumnType::Timestamp => self.encode_timestamps(),
            ColumnType::I64 => self.encode_i64s(),
            ColumnType::F64 => self.encode_f64s(),
            ColumnType::String => self.encode_strings(),
            ColumnType::Bool => self.encode_bools(),
            ColumnType::Binary => self.encode_binary(),
        }
    }

    fn encode_timestamps(&self) -> Result<Vec<u8>> {
        let vals: Vec<i64> = self
            .column
            .values
            .iter()
            .map(|v| match v {
                ColumnValue::Timestamp(t) => *t,
                _ => 0,
            })
            .collect();

        let first = vals.first().copied().unwrap_or(0);

        // Delta-of-delta encoding — skip the first element (stored verbatim)
        let mut deltas = Vec::with_capacity(vals.len().saturating_sub(1));
        let mut prev_delta = 0i64;
        let mut prev = first;
        for &v in vals.iter().skip(1) {
            let delta = v - prev;
            deltas.push(delta - prev_delta);
            prev_delta = delta;
            prev = v;
        }

        let mut buf = Vec::with_capacity(vals.len() * 8 + 8);
        buf.write_u64::<LittleEndian>(first as u64)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        // total count (including first element)
        buf.write_u32::<LittleEndian>(vals.len() as u32)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        for d in &deltas {
            buf.write_i64::<LittleEndian>(*d)
                .map_err(|e| XerjError::internal(e.to_string()))?;
        }

        get_codec(self.compression).compress(&buf)
    }

    fn encode_i64s(&self) -> Result<Vec<u8>> {
        let vals: Vec<i64> = self
            .column
            .values
            .iter()
            .map(|v| match v {
                ColumnValue::I64(n) => *n,
                _ => 0,
            })
            .collect();

        let mut buf = Vec::with_capacity(vals.len() * 8 + 4);
        buf.write_u32::<LittleEndian>(vals.len() as u32)
            .map_err(|e| XerjError::internal(e.to_string()))?;

        let mut prev = 0i64;
        for &v in &vals {
            let delta = v - prev;
            buf.write_i64::<LittleEndian>(delta)
                .map_err(|e| XerjError::internal(e.to_string()))?;
            prev = v;
        }

        get_codec(self.compression).compress(&buf)
    }

    fn encode_f64s(&self) -> Result<Vec<u8>> {
        let vals: Vec<f64> = self
            .column
            .values
            .iter()
            .map(|v| match v {
                ColumnValue::F64(f) => *f,
                _ => 0.0,
            })
            .collect();

        let mut buf = Vec::with_capacity(vals.len() * 8 + 4);
        buf.write_u32::<LittleEndian>(vals.len() as u32)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        for &v in &vals {
            buf.write_f64::<LittleEndian>(v)
                .map_err(|e| XerjError::internal(e.to_string()))?;
        }

        get_codec(self.compression).compress(&buf)
    }

    fn encode_strings(&self) -> Result<Vec<u8>> {
        let strs: Vec<&str> = self
            .column
            .values
            .iter()
            .map(|v| match v {
                ColumnValue::String(s) => s.as_str(),
                _ => "",
            })
            .collect();

        // Try dictionary encoding if cardinality is low
        let distinct: std::collections::HashSet<&str> = strs.iter().copied().collect();
        let use_dict = distinct.len() <= 256;

        let mut buf = Vec::new();
        buf.push(if use_dict { 1u8 } else { 0u8 });

        if use_dict {
            let mut encoder = DictionaryEncoder::new();
            encoder.build_from_sample(strs.iter().copied());
            let dict_bytes = encoder.serialize();

            buf.write_u32::<LittleEndian>(dict_bytes.len() as u32)
                .map_err(|e| XerjError::internal(e.to_string()))?;
            buf.extend_from_slice(&dict_bytes);
            buf.write_u32::<LittleEndian>(strs.len() as u32)
                .map_err(|e| XerjError::internal(e.to_string()))?;

            for s in &strs {
                let id = encoder.encode(s).unwrap_or(0);
                buf.write_u16::<LittleEndian>(id)
                    .map_err(|e| XerjError::internal(e.to_string()))?;
            }
        } else {
            buf.write_u32::<LittleEndian>(strs.len() as u32)
                .map_err(|e| XerjError::internal(e.to_string()))?;
            for s in &strs {
                let bytes = s.as_bytes();
                buf.write_u32::<LittleEndian>(bytes.len() as u32)
                    .map_err(|e| XerjError::internal(e.to_string()))?;
                buf.extend_from_slice(bytes);
            }
        }

        get_codec(self.compression).compress(&buf)
    }

    fn encode_bools(&self) -> Result<Vec<u8>> {
        let vals: Vec<bool> = self
            .column
            .values
            .iter()
            .map(|v| match v {
                ColumnValue::Bool(b) => *b,
                _ => false,
            })
            .collect();

        // Pack 8 bools per byte
        let byte_count = vals.len().div_ceil(8);
        let mut packed = vec![0u8; byte_count];
        for (i, &b) in vals.iter().enumerate() {
            if b {
                packed[i / 8] |= 1 << (i % 8);
            }
        }

        let mut buf = Vec::new();
        buf.write_u32::<LittleEndian>(vals.len() as u32)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        buf.extend_from_slice(&packed);
        get_codec(self.compression).compress(&buf)
    }

    fn encode_binary(&self) -> Result<Vec<u8>> {
        let mut buf = Vec::new();
        let count = self.column.values.len();
        buf.write_u32::<LittleEndian>(count as u32)
            .map_err(|e| XerjError::internal(e.to_string()))?;
        for v in &self.column.values {
            let bytes = match v {
                ColumnValue::Binary(b) => b.as_slice(),
                _ => &[],
            };
            buf.write_u32::<LittleEndian>(bytes.len() as u32)
                .map_err(|e| XerjError::internal(e.to_string()))?;
            buf.extend_from_slice(bytes);
        }
        get_codec(self.compression).compress(&buf)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// ColumnReader
// ─────────────────────────────────────────────────────────────────────────────

/// Decompresses and decodes columns on demand.
pub struct ColumnReader {
    pub name: String,
    pub column_type: ColumnType,
    /// Compressed column bytes.
    encoded: Vec<u8>,
    /// Uncompressed length hint (for decompressors that need it).
    uncompressed_len: usize,
}

impl ColumnReader {
    pub fn new(
        name: impl Into<String>,
        column_type: ColumnType,
        encoded: Vec<u8>,
        uncompressed_len: usize,
    ) -> Self {
        Self {
            name: name.into(),
            column_type,
            encoded,
            uncompressed_len,
        }
    }

    /// Decompress and decode all values in the column.
    pub fn decode(&self, compression: CompressionLevel) -> Result<Vec<ColumnValue>> {
        let raw = get_codec(compression).decompress(&self.encoded, self.uncompressed_len)?;
        match self.column_type {
            ColumnType::Timestamp => self.decode_timestamps(&raw),
            ColumnType::I64 => self.decode_i64s(&raw),
            ColumnType::F64 => self.decode_f64s(&raw),
            ColumnType::String => self.decode_strings(&raw),
            ColumnType::Bool => self.decode_bools(&raw),
            ColumnType::Binary => self.decode_binary(&raw),
        }
    }

    fn decode_timestamps(&self, raw: &[u8]) -> Result<Vec<ColumnValue>> {
        let mut cur = Cursor::new(raw);
        let first = cur
            .read_u64::<LittleEndian>()
            .map_err(|e| XerjError::internal(e.to_string()))? as i64;
        let count = cur
            .read_u32::<LittleEndian>()
            .map_err(|e| XerjError::internal(e.to_string()))? as usize;

        let mut result = Vec::with_capacity(count);
        let mut prev = first;
        let mut prev_delta = 0i64;

        result.push(ColumnValue::Timestamp(first));
        for _ in 1..count {
            let dod = cur
                .read_i64::<LittleEndian>()
                .map_err(|e| XerjError::internal(e.to_string()))?;
            let delta = prev_delta + dod;
            let v = prev + delta;
            result.push(ColumnValue::Timestamp(v));
            prev_delta = delta;
            prev = v;
        }
        Ok(result)
    }

    fn decode_i64s(&self, raw: &[u8]) -> Result<Vec<ColumnValue>> {
        let mut cur = Cursor::new(raw);
        let count = cur
            .read_u32::<LittleEndian>()
            .map_err(|e| XerjError::internal(e.to_string()))? as usize;
        let mut result = Vec::with_capacity(count);
        let mut prev = 0i64;
        for _ in 0..count {
            let delta = cur
                .read_i64::<LittleEndian>()
                .map_err(|e| XerjError::internal(e.to_string()))?;
            let v = prev + delta;
            result.push(ColumnValue::I64(v));
            prev = v;
        }
        Ok(result)
    }

    fn decode_f64s(&self, raw: &[u8]) -> Result<Vec<ColumnValue>> {
        let mut cur = Cursor::new(raw);
        let count = cur
            .read_u32::<LittleEndian>()
            .map_err(|e| XerjError::internal(e.to_string()))? as usize;
        let mut result = Vec::with_capacity(count);
        for _ in 0..count {
            let v = cur
                .read_f64::<LittleEndian>()
                .map_err(|e| XerjError::internal(e.to_string()))?;
            result.push(ColumnValue::F64(v));
        }
        Ok(result)
    }

    fn decode_strings(&self, raw: &[u8]) -> Result<Vec<ColumnValue>> {
        let use_dict = raw[0] == 1;
        let mut cur = Cursor::new(&raw[1..]);

        if use_dict {
            let dict_len =
                cur.read_u32::<LittleEndian>()
                    .map_err(|e| XerjError::internal(e.to_string()))? as usize;
            let mut dict_bytes = vec![0u8; dict_len];
            cur.read_exact(&mut dict_bytes)
                .map_err(|e| XerjError::internal(e.to_string()))?;
            let decoder = DictionaryDecoder::deserialize(&dict_bytes)?;

            let count = cur
                .read_u32::<LittleEndian>()
                .map_err(|e| XerjError::internal(e.to_string()))? as usize;
            let mut result = Vec::with_capacity(count);
            for _ in 0..count {
                let id = cur
                    .read_u16::<LittleEndian>()
                    .map_err(|e| XerjError::internal(e.to_string()))?;
                let s = decoder.decode(id).unwrap_or("").to_owned();
                result.push(ColumnValue::String(s));
            }
            Ok(result)
        } else {
            let count = cur
                .read_u32::<LittleEndian>()
                .map_err(|e| XerjError::internal(e.to_string()))? as usize;
            let mut result = Vec::with_capacity(count);
            for _ in 0..count {
                let slen = cur
                    .read_u32::<LittleEndian>()
                    .map_err(|e| XerjError::internal(e.to_string()))?
                    as usize;
                let mut sbytes = vec![0u8; slen];
                cur.read_exact(&mut sbytes)
                    .map_err(|e| XerjError::internal(e.to_string()))?;
                let s = String::from_utf8(sbytes)
                    .map_err(|e| XerjError::internal(format!("utf8: {e}")))?;
                result.push(ColumnValue::String(s));
            }
            Ok(result)
        }
    }

    fn decode_bools(&self, raw: &[u8]) -> Result<Vec<ColumnValue>> {
        let mut cur = Cursor::new(raw);
        let count = cur
            .read_u32::<LittleEndian>()
            .map_err(|e| XerjError::internal(e.to_string()))? as usize;
        let byte_count = count.div_ceil(8);
        let mut packed = vec![0u8; byte_count];
        cur.read_exact(&mut packed)
            .map_err(|e| XerjError::internal(e.to_string()))?;

        let mut result = Vec::with_capacity(count);
        for i in 0..count {
            let b = (packed[i / 8] >> (i % 8)) & 1 == 1;
            result.push(ColumnValue::Bool(b));
        }
        Ok(result)
    }

    fn decode_binary(&self, raw: &[u8]) -> Result<Vec<ColumnValue>> {
        let mut cur = Cursor::new(raw);
        let count = cur
            .read_u32::<LittleEndian>()
            .map_err(|e| XerjError::internal(e.to_string()))? as usize;
        let mut result = Vec::with_capacity(count);
        for _ in 0..count {
            let blen = cur
                .read_u32::<LittleEndian>()
                .map_err(|e| XerjError::internal(e.to_string()))? as usize;
            let mut bytes = vec![0u8; blen];
            cur.read_exact(&mut bytes)
                .map_err(|e| XerjError::internal(e.to_string()))?;
            result.push(ColumnValue::Binary(bytes));
        }
        Ok(result)
    }
}

