#[cfg(test)]
mod tests {
    use super::*;

    fn ts(offset_secs: i64) -> i64 {
        // Base timestamp: 2023-11-14 00:00:00 UTC in nanoseconds
        1_699_920_000_000_000_000i64 + offset_secs * 1_000_000_000
    }

    fn setup_ingester() -> LogIngester {
        let ingester = LogIngester::new();
        let records = vec![
            LogRecord {
                timestamp: ts(0),
                level: Some("INFO".into()),
                message: Some("start".into()),
                fields: HashMap::new(),
            },
            LogRecord {
                timestamp: ts(10),
                level: Some("WARN".into()),
                message: Some("slow".into()),
                fields: {
                    let mut m = HashMap::new();
                    m.insert("latency_ms".into(), Value::from(150.0));
                    m
                },
            },
            LogRecord {
                timestamp: ts(20),
                level: Some("ERROR".into()),
                message: Some("fail".into()),
                fields: {
                    let mut m = HashMap::new();
                    m.insert("latency_ms".into(), Value::from(5000.0));
                    m
                },
            },
            LogRecord {
                timestamp: ts(30),
                level: Some("INFO".into()),
                message: Some("done".into()),
                fields: HashMap::new(),
            },
        ];
        for r in records {
            ingester.ingest(r).unwrap();
        }
        ingester
    }

    #[test]
    fn count_all() {
        let ingester = setup_ingester();
        let exec = LogQueryExecutor::new(&ingester);
        let q = LogQuery::new(ts(-1), ts(60)).with_aggregation(Aggregation::Count);
        let result = exec.execute(&q).unwrap();
        assert_eq!(result.aggregations["result"].value, Some(4.0));
    }

    #[test]
    fn filter_by_level() {
        let ingester = setup_ingester();
        let exec = LogQueryExecutor::new(&ingester);
        let q = LogQuery::new(ts(-1), ts(60)).with_level("INFO");
        let result = exec.execute(&q).unwrap();
        assert_eq!(result.total, 2);
    }

    #[test]
    fn sum_aggregation() {
        let ingester = setup_ingester();
        let exec = LogQueryExecutor::new(&ingester);
        let q = LogQuery::new(ts(-1), ts(60)).with_aggregation(Aggregation::Sum {
            field: "latency_ms".into(),
        });
        let result = exec.execute(&q).unwrap();
        assert_eq!(result.aggregations["result"].value, Some(5150.0));
    }

    #[test]
    fn max_aggregation() {
        let ingester = setup_ingester();
        let exec = LogQueryExecutor::new(&ingester);
        let q = LogQuery::new(ts(-1), ts(60)).with_aggregation(Aggregation::Max {
            field: "latency_ms".into(),
        });
        let result = exec.execute(&q).unwrap();
        assert_eq!(result.aggregations["result"].value, Some(5000.0));
    }

    #[test]
    fn terms_aggregation() {
        let ingester = setup_ingester();
        let exec = LogQueryExecutor::new(&ingester);
        let q = LogQuery::new(ts(-1), ts(60)).with_aggregation(Aggregation::Terms {
            field: "level".into(),
            size: 5,
        });
        let result = exec.execute(&q).unwrap();
        let buckets = &result.aggregations["result"].buckets;
        // INFO appears twice, should be first
        assert_eq!(buckets[0].key, "INFO");
        assert_eq!(buckets[0].doc_count, 2);
    }

    #[test]
    fn invalid_time_range() {
        let ingester = LogIngester::new();
        let exec = LogQueryExecutor::new(&ingester);
        let q = LogQuery::new(ts(100), ts(0)); // from > to
        assert!(exec.execute(&q).is_err());
    }
}

//! Retention policy and background data cleanup.
//!
//! Partitions older than `retention_days` are eligible for deletion.
//! The background task runs periodically and removes expired data.

use chrono::Utc;
use serde::{Deserialize, Serialize};
use tracing::{info, warn};
use xerj_common::XerjError;

use crate::ingest::HourBucket;

/// Result alias.
pub type Result<T> = std::result::Result<T, XerjError>;

// ─────────────────────────────────────────────────────────────────────────────
// RetentionPolicy
// ─────────────────────────────────────────────────────────────────────────────

/// Controls how long log data is retained.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RetentionPolicy {
    /// Delete partitions older than this many days.
    /// `None` means retain indefinitely.
    pub retention_days: Option<u32>,
    /// How often to run the cleanup task (in seconds).
    #[serde(default = "default_check_interval_secs")]
    pub check_interval_secs: u64,
}

fn default_check_interval_secs() -> u64 {
    3600 // hourly
}

impl RetentionPolicy {
    /// Create a policy retaining data for `days` days.
    pub fn retain_days(days: u32) -> Self {
        Self {
            retention_days: Some(days),
            check_interval_secs: default_check_interval_secs(),
        }
    }

    /// Create a policy retaining data indefinitely.
    pub fn retain_forever() -> Self {
        Self {
            retention_days: None,
            check_interval_secs: default_check_interval_secs(),
        }
    }

    /// Returns `true` if the given hour bucket has expired under this policy.
    pub fn is_expired(&self, bucket: &HourBucket) -> bool {
        let retention_days = match self.retention_days {
            Some(d) => d,
            None => return false, // retain forever
        };

        let now = Utc::now();
        let cutoff = now - chrono::Duration::days(retention_days as i64);

        // Build an approximate timestamp from the bucket
        let bucket_year = bucket.year as i32;
        let bucket_month = bucket.month as u32;
        let bucket_day = bucket.day as u32;
        let bucket_hour = bucket.hour as u32;

        match chrono::NaiveDate::from_ymd_opt(bucket_year, bucket_month, bucket_day)
            .and_then(|d| d.and_hms_opt(bucket_hour, 0, 0))
            .map(|dt| chrono::DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc))
        {
            Some(bucket_dt) => bucket_dt < cutoff,
            None => {
                warn!("could not parse bucket timestamp: {:?}", bucket);
                false
            }
        }
    }

    /// Identify expired buckets from a list of active buckets.
    pub fn expired_buckets(&self, buckets: &[HourBucket]) -> Vec<HourBucket> {
        buckets
            .iter()
            .filter(|b| self.is_expired(b))
            .copied()
            .collect()
    }
}

impl Default for RetentionPolicy {
    /// Default: retain 30 days.
    fn default() -> Self {
        Self::retain_days(30)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// RetentionManager
// ─────────────────────────────────────────────────────────────────────────────

/// Applies a retention policy to a set of buckets.
///
/// In production, this would be driven by a background tokio task that
/// periodically calls [`apply`] and deletes the returned bucket paths from
/// object storage.
pub struct RetentionManager {
    policy: RetentionPolicy,
}

impl RetentionManager {
    pub fn new(policy: RetentionPolicy) -> Self {
        Self { policy }
    }

    /// Determine which buckets should be deleted, logging actions taken.
    ///
    /// Returns the list of buckets that should be removed from storage.
    pub fn apply(&self, active_buckets: &[HourBucket]) -> Vec<HourBucket> {
        let expired = self.policy.expired_buckets(active_buckets);

        if expired.is_empty() {
            info!("retention check: no expired partitions");
        } else {
            info!(
                "retention check: {} expired partition(s) to delete",
                expired.len()
            );
            for b in &expired {
                info!("  deleting partition: {}", b);
            }
        }

        expired
    }

    pub fn policy(&self) -> &RetentionPolicy {
        &self.policy
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::Utc;

    fn old_bucket(days_ago: i64) -> HourBucket {
        let dt = Utc::now() - chrono::Duration::days(days_ago);
        HourBucket {
            year: dt.year() as u16,
            month: dt.month() as u8,
            day: dt.day() as u8,
            hour: dt.hour() as u8,
        }
    }

    use chrono::{Datelike, Timelike};

    #[test]
    fn recent_bucket_not_expired() {
        let policy = RetentionPolicy::retain_days(30);
        let bucket = old_bucket(5); // 5 days ago
        assert!(!policy.is_expired(&bucket));
    }

    #[test]
    fn old_bucket_is_expired() {
        let policy = RetentionPolicy::retain_days(30);
        let bucket = old_bucket(40); // 40 days ago
        assert!(policy.is_expired(&bucket));
    }

    #[test]
    fn retain_forever_never_expires() {
        let policy = RetentionPolicy::retain_forever();
        let bucket = old_bucket(3650); // 10 years ago
        assert!(!policy.is_expired(&bucket));
    }

    #[test]
    fn expired_buckets_returns_correct_subset() {
        let policy = RetentionPolicy::retain_days(30);
        let buckets = vec![
            old_bucket(5),  // recent
            old_bucket(40), // expired
            old_bucket(60), // expired
            old_bucket(10), // recent
        ];
        let expired = policy.expired_buckets(&buckets);
        assert_eq!(expired.len(), 2);
    }

    #[test]
    fn manager_apply_returns_expired() {
        let policy = RetentionPolicy::retain_days(30);
        let manager = RetentionManager::new(policy);
        let buckets = vec![old_bucket(5), old_bucket(45)];
        let to_delete = manager.apply(&buckets);
        assert_eq!(to_delete.len(), 1);
    }
}

//! Ordered, read-only batch retrieval over the existing `_msearch` endpoint.
//! No answer generation or confidence threshold is inferred from a BM25 score.
use serde_json::{json, Value};

use crate::{build_search_with_mapping, fetch_mapping, search_index, token_budget, tool_text, Ctx};

pub const MAX_INPUT_BYTES: usize = 1024 * 1024;
const MAX_RESPONSE_BYTES: usize = 32 * 1024 * 1024;

pub(crate) fn spec() -> Value {
    json!({
        "name":"xerj_batch_search",
        "description": "Search 1..50 IDs or questions in one call, in input order. Shares the CLI xerj batch-search adapter. Each result has its zero-based position, optional caller key, and status hits, abstain (only a complete empty search), or error. Hits carry citations: index/id plus file/line or record locator when available. This retrieves evidence, not generated answers or calibrated confidence. Use identifier plus an explicitly keyword-mapped field for exact IDs; query takes plain text or an ES query clause. One bad item never discards its siblings; identical inputs remain separate. Uses one _msearch request, plus at most one mapping read. Optional max_tokens caps the entire successful JSON response using StandardTokenizer UAX #29 words, not BPE. Budgeting removes raw hit bodies, then extra hits, retaining each item's status and at least one citation per matched item. If that minimum cannot fit, returns an actionable tool error, never truncated JSON or a false abstention. Errors are not truncated.",
        "inputSchema":{
            "type":"object", "additionalProperties":false,
            "properties":{
                "queries":{"type":"array","minItems":1,"maxItems":50,
                    "description":"Ordered queries. Duplicate keys are allowed; position is authoritative. Entire input is limited to 1 MiB.",
                    "items":{"type":"object","additionalProperties":false,"properties":{
                        "key":{"type":"string","description":"Optional correlation key, at most 256 UTF-8 bytes."},
                        "query":{"oneOf":[{"type":"string","minLength":1},{"type":"object"}],
                            "description":"Plain text or ES query clause. Cannot be combined with identifier/field."},
                        "identifier":{"type":"string","minLength":1,"description":"Exact value, used verbatim in a term query; requires field."},
                        "field":{"type":"string","minLength":1,"description":"Flat keyword field for identifier. Must be mapped as keyword wherever present; unreadable, absent or conflicting mappings fail this item."}
                    }, "oneOf":[{"required":["query"]},{"required":["identifier","field"]}]}},
                "index":{"type":"string","description":"Index or pattern; alternative to prefix. Defaults to ax-*."},
                "prefix":{"type":"string","description":"Autoindex prefix, e.g. project searches project-*. Cannot combine with index."},
                "size":{"type":"integer","minimum":1,"maximum":50,"default":3,"description":"Maximum hits per item."},
                "max_tokens":{"type":"integer","minimum":32,"description":format!("Whole-response budget counted with {} (not BPE); minimum 32. A successful response NEVER exceeds it. Preserves ordered item outcomes and at least one citation per matched item, removing raw bodies first. Refuses if that minimum cannot fit; split the batch or increase the budget. Errors are outside this budget.", token_budget::TOKENIZER_NAME)}
            },"required":["queries"]
        }
    })
}

fn known_keys(value: &Value, allowed: &[&str]) -> Result<(), String> {
    let obj = value.as_object().ok_or("arguments must be a JSON object")?;
    if let Some(key) = obj.keys().find(|k| !allowed.contains(&k.as_str())) {
        return Err(format!("unsupported argument `{key}`"));
    }
    Ok(())
}

fn text<'a>(value: &'a Value, key: &str) -> Result<&'a str, String> {
    value
        .get(key)
        .and_then(Value::as_str)
        .filter(|s| !s.trim().is_empty())
        .ok_or_else(|| format!("`{key}` must be a non-blank string"))
}

pub(super) struct Batch<'a> {
    index: String,
    size: usize,
    limit: Option<usize>,
    items: &'a [Value],
}

pub(super) fn envelope(args: &Value) -> Result<Batch<'_>, String> {
    known_keys(args, &["queries", "index", "prefix", "size", "max_tokens"])?;
    if args.to_string().len() > MAX_INPUT_BYTES {
        return Err("batch input exceeds 1 MiB; split it into smaller batches".into());
    }
    if args
        .get("index")
        .is_some_and(|v| !v.is_string() && !v.is_null())
    {
        return Err("`index` must be a string".into());
    }
    let index = search_index(args)?;
    let queries = args
        .get("queries")
        .and_then(Value::as_array)
        .filter(|a| (1..=50).contains(&a.len()))
        .ok_or("`queries` must be an array of 1..50 items")?;
    let size = match args.get("size") {
        None => 3,
        Some(v) => v
            .as_u64()
            .filter(|n| (1..=50).contains(n))
            .ok_or("`size` must be an integer from 1 to 50")? as usize,
    };
    let budget = token_budget::opt_max_tokens(args)?;
    Ok(Batch {
        index,
        size,
        limit: budget,
        items: queries,
    })
}

fn validate_item(item: &Value) -> Result<(), String> {
    known_keys(item, &["key", "query", "identifier", "field"])?;
    if item
        .get("key")
        .is_some_and(|v| v.as_str().is_none_or(|s| s.len() > 256))
    {
        return Err("`key` must be a string of at most 256 UTF-8 bytes".into());
    }
    if let Some(query) = item.get("query") {
        if item.get("identifier").is_some() || item.get("field").is_some() {
            return Err("use either query or identifier plus field, not both".into());
        }
        if !(query.as_str().is_some_and(|s| !s.trim().is_empty())
            || query.as_object().is_some_and(|o| !o.is_empty()))
        {
            return Err("`query` must be non-blank text or a nonempty ES query object".into());
        }
    } else {
        text(item, "identifier")?;
        let field = text(item, "field")?;
        if field.contains('.') {
            return Err(
                "`field` must name a flat keyword field; nested fields are not supported".into(),
            );
        }
    }
    Ok(())
}

fn item_body(
    item: &Value,
    index: &str,
    size: usize,
    mapping: Option<&Value>,
) -> Result<Value, String> {
    if item.get("identifier").is_some() {
        let field = text(item, "field")?;
        let mappings = mapping
            .and_then(Value::as_object)
            .ok_or("cannot verify exact identifier field: mapping unavailable")?;
        let mut present = false;
        for m in mappings.values() {
            if let Some(spec) = m.pointer("/mappings/properties").and_then(|p| p.get(field)) {
                present = true;
                if spec["type"] != "keyword" || spec["index"] == false {
                    return Err(format!("exact identifier field `{field}` must be indexed keyword in every mapping where present"));
                }
            }
        }
        if !present {
            return Err(format!("exact identifier field `{field}` is not mapped"));
        }
        return Ok(json!({"query":{"term":{(field):item["identifier"]}},"size":size}));
    }
    let args = json!({"index":index,"query":item["query"],"size":size,"_source":true});
    let (_, _, body) = build_search_with_mapping(&args, mapping)?;
    let mut body = body.expect("search builder always supplies a body");
    if crate::plain_search_demotes_test_paths(&args, mapping) {
        body["size"] = json!(xerj_autoindex::search::search_fetch_size(size));
    }
    Ok(body)
}

fn item_base(position: usize, item: &Value) -> Value {
    let mut out = json!({"position":position});
    if let Some(key) = item
        .get("key")
        .and_then(Value::as_str)
        .filter(|s| s.len() <= 256)
    {
        out["key"] = json!(key);
    }
    out
}

fn failed(mut base: Value, error: Value) -> Value {
    base["status"] = json!("error");
    base["error"] = error;
    base
}

fn citation(hit: &Value) -> Result<Value, String> {
    let mut out = serde_json::Map::new();
    for key in ["_index", "_id"] {
        out.insert(key.into(), json!(text(hit, key)?));
    }
    if let Some(source) = hit.get("_source") {
        for key in [
            "ax_path",
            "path",
            "ax_file",
            "ax_locator",
            "line",
            "start_line",
            "page",
            "cell",
        ] {
            if let Some(v) = source.get(key).filter(|v| v.is_string() || v.is_number()) {
                out.insert(key.into(), v.clone());
            }
        }
    }
    for key in ["match_line", "match_lines"] {
        if let Some(v) = hit.get(key) {
            out.insert(key.into(), v.clone());
        }
    }
    Ok(Value::Object(out))
}

fn item_result(
    mut base: Value,
    mut response: Value,
    item: &Value,
    size: usize,
    mapping: Option<&Value>,
) -> Value {
    if response.get("error").is_some_and(|v| !v.is_null())
        || response["status"].as_u64().is_some_and(|s| s >= 400)
    {
        return failed(base, response);
    }
    if response["timed_out"] == true
        || response
            .pointer("/_shards/failed")
            .and_then(Value::as_u64)
            .unwrap_or(0)
            > 0
    {
        return failed(
            base,
            json!({"reason":"search_incomplete","response":response}),
        );
    }
    let query = item.get("query").map(|v| {
        v.as_str()
            .map(str::to_string)
            .unwrap_or_else(|| v.to_string())
    });
    if let Some(query) = query {
        xerj_common::xccode::passage::annotate_search_match_lines(&mut response, &query);
    }
    if crate::plain_search_demotes_test_paths(&json!({"query":item["query"]}), mapping) {
        if let Some(hits) = response
            .pointer_mut("/hits/hits")
            .and_then(Value::as_array_mut)
        {
            xerj_autoindex::def::penalize_demoted_paths(hits);
            hits.truncate(size);
        }
    }
    let Some(hits) = response.pointer("/hits/hits").and_then(Value::as_array) else {
        return failed(
            base,
            json!({"reason":"invalid_search_response","message":"missing hits.hits"}),
        );
    };
    if hits.is_empty() {
        let total = response
            .pointer("/hits/total/value")
            .and_then(Value::as_u64)
            .or_else(|| response.pointer("/hits/total").and_then(Value::as_u64));
        if total.is_some_and(|n| n > 0) {
            return failed(
                base,
                json!({"reason":"invalid_search_response","message":"empty page despite a positive total"}),
            );
        }
        base["status"] = json!("abstain");
        base["abstain"] = json!(true);
        base["reason"] = json!("no_hits");
        return base;
    }
    let mut cited = Vec::new();
    for hit in hits.iter().take(size) {
        let citation = match citation(hit) {
            Ok(c) => c,
            Err(e) => {
                return failed(
                    base,
                    json!({"reason":"invalid_search_response","message":e}),
                )
            }
        };
        cited.push(json!({"citation":citation,"hit":hit}));
    }
    base["status"] = json!("hits");
    base["abstain"] = json!(false);
    base["hits"] = json!(cited);
    base["hits_omitted"] = json!(hits.len().saturating_sub(cited.len()));
    base
}

async fn msearch(ctx: &Ctx, ndjson: String) -> Result<Vec<Value>, String> {
    let url = format!("{}/_msearch", ctx.base_url);
    let mut req = ctx
        .client
        .post(&url)
        .header("Content-Type", "application/x-ndjson")
        .body(ndjson);
    if let Some(auth) = &ctx.auth {
        req = req.header("Authorization", auth);
    }
    let mut resp = req
        .send()
        .await
        .map_err(|e| crate::transport_failure_text(&ctx.base_url, &url, &e))?;
    let status = resp.status();
    let mut bytes = Vec::new();
    while let Some(chunk) = resp.chunk().await.map_err(|e| crate::error_detail(&e))? {
        if bytes.len().saturating_add(chunk.len()) > MAX_RESPONSE_BYTES {
            return Err("batch response exceeds 32 MiB; reduce size or split the batch".into());
        }
        bytes.extend_from_slice(&chunk);
    }
    if !status.is_success() {
        let body = String::from_utf8_lossy(&bytes);
        if let Some(proxied) =
            crate::proxy_status_failure(&ctx.base_url, &url, status.as_u16(), &body)
        {
            return Err(proxied);
        }
        return Err(format!("batch endpoint returned HTTP {status}: {body}"));
    }
    let response: Value =
        serde_json::from_slice(&bytes).map_err(|_| "batch endpoint returned invalid JSON")?;
    response
        .get("responses")
        .and_then(Value::as_array)
        .cloned()
        .ok_or_else(|| "batch endpoint returned no responses array".into())
}

/// Never discard an item's outcome to meet a budget. At least one citation
/// survives each matched item; errors and abstentions retain their meanings.
fn budget(mut response: Value, limit: Option<usize>) -> Result<String, String> {
    let Some(limit) = limit else {
        return Ok(response.to_string());
    };
    let count = |v: &Value| token_budget::count_tokens(&v.to_string());
    if count(&response) <= limit {
        return Ok(response.to_string());
    }
    response["_token_budget"] = json!({"tokenizer":token_budget::TOKENIZER_ID,"max_tokens":limit});
    let mut used = count(&response);
    // Lower ranked items lose raw bodies first, but never their citations.
    let n = response["results"].as_array().unwrap().len();
    for i in (0..n).rev() {
        let len = response["results"][i]["hits"]
            .as_array()
            .map_or(0, Vec::len);
        for j in (0..len).rev() {
            if let Some(hit) = response["results"][i]["hits"][j]
                .as_object_mut()
                .unwrap()
                .remove("hit")
            {
                // JSON punctuation separates fields into word boundaries. Count
                // just the removed subtree rather than serializing a 32 MiB
                // response once for every hit. Final serialization is checked.
                used = used.saturating_sub(count(&json!({"hit":hit})));
            }
            if used <= limit {
                return checked_budget(&response, limit);
            }
        }
    }
    for i in (0..n).rev() {
        while response["results"][i]["hits"]
            .as_array()
            .is_some_and(|a| a.len() > 1)
        {
            let hit = response["results"][i]["hits"]
                .as_array_mut()
                .unwrap()
                .pop()
                .unwrap();
            used = used.saturating_sub(count(&hit));
            let omitted = response["results"][i]["hits_omitted"].as_u64().unwrap_or(0);
            response["results"][i]["hits_omitted"] = json!(omitted + 1);
            if used <= limit {
                return checked_budget(&response, limit);
            }
        }
    }
    let minimum = token_budget::count_tokens(&response.to_string());
    Err(format!("max_tokens {limit} cannot preserve every item outcome and one citation per matched item; this response needs at least {minimum} UAX #29 words. Increase max_tokens or split the batch. Nothing was written."))
}

fn checked_budget(response: &Value, limit: usize) -> Result<String, String> {
    let text = response.to_string();
    if token_budget::count_tokens(&text) <= limit {
        Ok(text)
    } else {
        Err("batch budget accounting could not preserve valid JSON; increase max_tokens or split the batch".into())
    }
}

pub(crate) async fn execute(ctx: &Ctx, args: &Value) -> Result<String, String> {
    let Batch {
        index,
        size,
        limit,
        items,
    } = envelope(args)?;
    // Validate locally before any I/O; invalid items do not sink siblings.
    let validation: Vec<_> = items.iter().map(validate_item).collect();
    let needs_mapping = items.iter().zip(&validation).any(|(item, valid)| {
        valid.is_ok() && (item.get("identifier").is_some() || item["query"].is_string())
    });
    let mapping = if needs_mapping {
        fetch_mapping(ctx, &index).await
    } else {
        None
    };
    let mut results: Vec<Value> = items
        .iter()
        .enumerate()
        .map(|(i, item)| item_base(i, item))
        .collect();
    let mut pending = Vec::new();
    let mut batch_error = None;
    let mut ndjson = String::new();
    for (i, item) in items.iter().enumerate() {
        let built = validation[i]
            .clone()
            .and_then(|()| item_body(item, &index, size, mapping.as_ref()));
        match built {
            Ok(body) => {
                ndjson.push_str(&json!({"index":index}).to_string());
                ndjson.push('\n');
                ndjson.push_str(&body.to_string());
                ndjson.push('\n');
                pending.push(i);
            }
            Err(message) => {
                results[i] = failed(
                    results[i].clone(),
                    json!({"reason":"invalid_item","message":message}),
                )
            }
        }
    }
    if !pending.is_empty() {
        match msearch(ctx, ndjson).await {
            Ok(responses) if responses.len() == pending.len() => {
                for (i, response) in pending.into_iter().zip(responses) {
                    results[i] = item_result(
                        results[i].clone(),
                        response,
                        &items[i],
                        size,
                        mapping.as_ref(),
                    );
                }
            }
            other => {
                let message = match other {
                    Ok(_) => "batch endpoint returned the wrong number of responses; item correspondence cannot be trusted".to_string(),
                    Err(e) => e,
                };
                for i in pending {
                    results[i] = failed(
                        results[i].clone(),
                        json!({"reason":"batch_request_failed","details":"see batch_error"}),
                    );
                }
                // Preserve the complete transport error once, rather than
                // multiplying a large HTTP error body by up to 50 items.
                batch_error = Some(message);
            }
        }
    }
    let mut response = json!({"results":results});
    if let Some(error) = batch_error {
        response["batch_error"] = json!(error);
    }
    budget(response, limit)
}

pub(crate) async fn run(ctx: &Ctx, args: &Value) -> Value {
    match execute(ctx, args).await {
        Ok(text) => tool_text(text, false),
        Err(error) => tool_text(error, true),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn batch_budget_keeps_outcomes_and_citations_or_refuses() {
        let response = json!({"results":[
            {"position":0,"status":"hits","abstain":false,"hits_omitted":0,
             "hits":[{"citation":{"_index":"docs","_id":"one"},"hit":{"body":"word ".repeat(1000)}},
                     {"citation":{"_index":"docs","_id":"two"},"hit":{"body":"other ".repeat(1000)}}]},
            {"position":1,"status":"abstain","abstain":true,"reason":"no_hits"},
            {"position":2,"status":"error","error":{"reason":"backend_failed"}}
        ]});
        assert_eq!(
            budget(response.clone(), Some(10000)).unwrap(),
            response.to_string()
        );
        for limit in [32, 64, 80, 120, 300, 3000] {
            match budget(response.clone(), Some(limit)) {
                Ok(text) => {
                    assert!(token_budget::count_tokens(&text) <= limit);
                    let v: Value = serde_json::from_str(&text).unwrap();
                    assert_eq!(v["results"].as_array().unwrap().len(), 3);
                    assert_eq!(v["results"][0]["hits"][0]["citation"]["_id"], "one");
                    assert_eq!(v["results"][1]["status"], "abstain");
                    assert_eq!(v["results"][2]["status"], "error");
                }
                Err(e) => assert!(e.contains("needs at least"), "{e}"),
            }
        }
    }
}

//! JSON-in/JSON-out CLI for the same batch adapter MCP calls.
use std::io::Read;
use std::time::Duration;

use crate::{batch, node_http_builder, resolve_auth, Ctx, DEFAULT_XERJ_URL};

const HELP: &str = "xerj batch-search — ordered batch retrieval (#1801)

USAGE: xerj batch-search --input <file|-> [--url URL] [--auth VALUE]

Read one JSON object (at most 1 MiB) using the xerj_batch_search schema:
  {\"prefix\":\"project\",\"size\":3,\"queries\":[
    {\"key\":\"question\",\"query\":\"rotate the WAL\"},
    {\"key\":\"advisory\",\"identifier\":\"CVE-2026-12345\",\"field\":\"id\"}
  ]}

queries: 1..50 objects, each query (text or ES query clause) OR identifier+field.
Exact identifiers require a flat indexed keyword field. index/prefix, size
(1..50, default 3) and optional max_tokens are shared by all items.
Output is one JSON object with ordered results; position is zero-based and
authoritative even for duplicate keys. status is hits, abstain (complete empty
search only), or error. Hits contain citations and raw evidence, not generated
answers or calibrated confidence. A miss does not discard its siblings.
max_tokens counts the entire JSON as UAX #29 words, not model/BPE tokens.
It removes raw bodies and then extra hits, retaining every item outcome and
one citation per matched item; an insufficient budget is an error, not truncation.

--url / --auth override XERJ_URL / XERJ_AUTH. Default URL: http://localhost:9200.
Local loopback admin-key discovery is the same as xerj mcp. A node must already
be running. This command writes no data and does not download any corpus.
Exit: 0 all items completed (including abstentions), 3 per-item errors,
      2 invalid CLI/input, 1 a batch-wide execution/budget error.
";

struct Options {
    input: String,
    url: Option<String>,
    auth: Option<String>,
}

fn options(args: &[String]) -> Result<Options, String> {
    let mut out = Options {
        input: String::new(),
        url: None,
        auth: None,
    };
    let mut it = args.iter();
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--input" | "--url" | "--auth" => {
                let value = it.next().ok_or_else(|| format!("{arg} requires a value"))?;
                match arg.as_str() {
                    "--input" => out.input = value.clone(),
                    "--url" => out.url = Some(value.clone()),
                    _ => out.auth = Some(value.clone()),
                }
            }
            xerj_common::feedback::DISABLE_FLAG => {}
            _ => {
                return Err(format!(
                    "unknown argument `{arg}`; see xerj batch-search --help"
                ))
            }
        }
    }
    if out.input.is_empty() {
        return Err("--input <file|-> is required; see xerj batch-search --help".into());
    }
    Ok(out)
}

fn read_input(path: &str) -> Result<serde_json::Value, String> {
    let reader: Box<dyn Read> = if path == "-" {
        Box::new(std::io::stdin())
    } else {
        Box::new(std::fs::File::open(path).map_err(|e| format!("cannot open input: {e}"))?)
    };
    let mut bytes = Vec::new();
    reader
        .take(batch::MAX_INPUT_BYTES as u64 + 1)
        .read_to_end(&mut bytes)
        .map_err(|e| format!("cannot read input: {e}"))?;
    if bytes.len() > batch::MAX_INPUT_BYTES {
        return Err("batch input exceeds 1 MiB; split it".into());
    }
    serde_json::from_slice(&bytes).map_err(|e| format!("invalid batch JSON: {e}"))
}

/// Called before node startup by the main binary; never starts a node.
pub async fn run_batch_cli(args: &[String]) -> i32 {
    if args.iter().any(|s| s == "--help" || s == "-h") {
        print!("{HELP}");
        return 0;
    }
    let opts = match options(args) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("error: {e}");
            return 2;
        }
    };
    let input = match read_input(&opts.input) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("error: {e}");
            return 2;
        }
    };
    if let Err(e) = batch::envelope(&input) {
        eprintln!("error: {e}");
        return 2;
    }
    let base_url = opts
        .url
        .or_else(|| std::env::var("XERJ_URL").ok())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| DEFAULT_XERJ_URL.into())
        .trim_end_matches('/')
        .to_string();
    let (auth, path) = resolve_auth(opts.auth, std::env::var("XERJ_AUTH").ok(), &base_url);
    if let Some(path) = path {
        eprintln!(
            "xerj batch-search: using local admin key at {}",
            path.display()
        );
    }
    let client = match node_http_builder(&base_url)
        .timeout(Duration::from_secs(30))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            eprintln!("error: {e}");
            return 1;
        }
    };
    match batch::execute(
        &Ctx {
            client,
            base_url,
            auth,
        },
        &input,
    )
    .await
    {
        Ok(text) => {
            let result: serde_json::Value =
                serde_json::from_str(&text).expect("batch returns JSON");
            let errors = result["results"]
                .as_array()
                .unwrap()
                .iter()
                .any(|r| r["status"] == "error");
            println!("{text}");
            if errors {
                3
            } else {
                0
            }
        }
        Err(e) => {
            eprintln!("error: {e}");
            1
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn cli_requires_explicit_input_and_rejects_typos() {
        assert!(options(&[]).is_err());
        assert!(options(&["--input".into()]).is_err());
        assert!(options(&["--input".into(), "-".into(), "--urll".into()]).is_err());
        let parsed = options(&[
            "--input".into(),
            "-".into(),
            "--url".into(),
            "http://localhost:9201".into(),
        ])
        .unwrap();
        assert_eq!(parsed.input, "-");
        assert_eq!(parsed.url.as_deref(), Some("http://localhost:9201"));
    }
}

//! Local `xerj def` adapter. The CLI owns the query and result ordering;
//! this module validates MCP arguments and uses the configured node/auth.
use serde_json::{json, Value};
use xerj_autoindex::def::{definition_query, finalize_definition_response};

use crate::{
    engine_request, fetch_mapping, opt_u64, search_index, token_budget, tool_text, Ctx, Method,
};

pub(crate) fn spec() -> Value {
    json!({
        "name": "xerj_def",
        "description": concat!(
            "Find a symbol's definition in local autoindexed data, like `xerj def --json`. ",
            "Lexical ranking, not neural: shares the CLI's mapping-aware query, preferred-kind ",
            "and public-declaration ranking, location deduplication and bounded candidate window. ",
            "Returns ES JSON with declarations in hits.hits[]._source.code and locations in ",
            "ax_path/path plus line/start_line (page/cell for documents); older file-level hits ",
            "may carry fields._passage instead. hits.total counts engine matches before deduplication. ",
            "No match is a successful empty hits list. Unlike xerj_hub_def, this queries the ",
            "configured node, not a Hub pack. Optional max_tokens caps the response; see its ",
            "tokenizer and locator-only rule."
        ),
        "inputSchema": {
            "type": "object",
            "properties": {
                "symbol": {"type":"string", "minLength":1,
                    "description":"Symbol name or capability phrase, as in `xerj def Cache`. Must not be blank."},
                "prefix": {"type":"string",
                    "description":"Autoindex prefix: project searches project-*. Trimmed, must not be empty. Cannot be combined with a non-empty index. Defaults to ax when neither scope is given."},
                "index": {"type":"string",
                    "description":"Explicit index name or pattern instead of prefix, as in xerj_search. A blank string is treated as absent."},
                "kind": {"type":"string",
                    "description":"Symbol kind, e.g. function, struct or class. Like the CLI, ignored when no index maps kind or any maps it as numeric."},
                "lang": {"type":"string",
                    "description":"Language, e.g. rust or python. Like the CLI, ignored when no index maps language or any maps it as numeric."},
                "k": {"type":"integer", "minimum":1, "maximum":50, "default":5,
                    "description":"Maximum unique definitions to return (1..=50, default 5)."},
                "max_tokens": crate::max_tokens_arg_schema()
            },
            "required":["symbol"]
        }
    })
}

fn optional_text<'a>(args: &'a Value, key: &str) -> Result<Option<&'a str>, String> {
    match args.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(Value::String(s)) if !s.trim().is_empty() => Ok(Some(s)),
        _ => Err(format!("`{key}` must be a non-empty string")),
    }
}

pub(crate) async fn run(ctx: &Ctx, args: &Value) -> Value {
    // Validate all locally knowable inputs before the first mapping request.
    let validated = (|| {
        let symbol = optional_text(args, "symbol")?
            .ok_or("`symbol` is required, for example {\"symbol\":\"Cache\"}")?;
        if args
            .get("index")
            .is_some_and(|v| !v.is_null() && !v.is_string())
        {
            return Err("`index` must be a string".to_string());
        }
        let index = search_index(args)?;
        let kind = optional_text(args, "kind")?;
        let lang = optional_text(args, "lang")?;
        let k = opt_u64(args, "k")?.unwrap_or(5);
        if !(1..=50).contains(&k) {
            return Err("`k` must be an integer from 1 to 50".into());
        }
        let budget = token_budget::opt_max_tokens(args)?;
        Ok((symbol, index, kind, lang, k as usize, budget))
    })();
    let (symbol, index, kind, lang, k, budget) = match validated {
        Ok(args) => args,
        Err(error) => return tool_text(error, true),
    };
    let mapping = fetch_mapping(ctx, &index).await;
    let body = definition_query(symbol, kind, lang, k, mapping.as_ref());
    let result = engine_request(
        ctx,
        Method::Post,
        &format!("/{index}/_search"),
        Some(body),
        None,
        None,
        None,
    )
    .await;
    if result["isError"] == true {
        return result;
    }
    let text = result["content"][0]["text"].as_str().unwrap_or_default();
    let mut response: Value = match serde_json::from_str(text) {
        Ok(value) => value,
        Err(_) => return tool_text("XERJ returned invalid JSON for definition lookup", true),
    };
    if !response.pointer("/hits/hits").is_some_and(Value::is_array) {
        return tool_text(
            "XERJ returned a definition response without hits.hits",
            true,
        );
    }
    finalize_definition_response(&mut response, symbol, k);
    let text = response.to_string();
    tool_text(
        match budget {
            Some(max_tokens) => token_budget::budget_json_response(&text, max_tokens),
            None => text,
        },
        false,
    )
}

//! Corpus Hub v2 — the `xerj_hub_*` MCP tools (plan §7,
//! `docs/CORPUS_HUB_V2_IMPLEMENTATION.md`; specs in
//! `docs/hub-v2-grpc-mcp-notes.md`).
//!
//! Thin adapters over the code the CLI runs — no hub logic lives here:
//!
//! | tool | runs | which is also |
//! |---|---|---|
//! | `xerj_hub_ask` | [`xerj_hub::ask::run_ask_with`] | `xerj ask "<q>" [--corpus] [--def\|--how\|--files] [--max-tokens]` |
//! | `xerj_hub_def` | [`xerj_hub::ask::run_ask_with`] with `--corpus <slug> --def <SYMBOL>` | `xerj ask --corpus <slug> --def <SYMBOL>` |
//! | `xerj_hub_find` | [`xerj_hub::ask::run_find`] | the routing half of `xerj ask` (what it would pick, and the runners-up) |
//!
//! The answer flow is the CLI's: local packs first, hosted second (this build
//! has no hosted client, so "hosted" is unavailable exactly as it is for the
//! CLI), the catalogue is the cached copy (below), and the node is the
//! one this server proxies to (`--url` / `XERJ_URL`), or the automatic hub node.
//! The tool result text is the §1 rendering with the flow's notices on top (MCP
//! has no stderr); the structured content is the [`xerj_hub::Answer`] JSON.
//!
//! One difference, on purpose: a tool call never downloads a pack. The flow
//! runs with `no_fetch`, so a corpus that is not on this machine is answered
//! with the `xerj hub pull <slug>` line instead — a tool call cannot start a
//! download, and so cannot trigger the pull's least-recently-used eviction (a
//! delete) behind an agent's back. Excluded corpora are never pulled or served
//! by the flow itself; approach-only answers carry the licence warning on every
//! hit.
//!
//! Nor does a tool call fetch the catalogue: the tools read the copy `xerj hub
//! sync` (or any CLI `xerj ask` / `xerj hub pull`) cached, however old, and
//! never block on the hub's 10 s/30 s fetch timeouts inside an agent's turn.
//! With no cached copy the tool says to run `xerj hub sync`.

use serde_json::{json, Value};
use xerj_hub::ask::{
    self, AskArgs, AskOutcome, ModeRequest, EXIT_NEEDS_DECISION, FIND_DEFAULT_K, FIND_MAX_K,
};
use xerj_hub::node::NodeLauncher;

use crate::{tool_text, Ctx};

/// The longest question or symbol a tool takes — the hosted routes' limit.
pub const MAX_INPUT_BYTES: usize = 512;
/// `k` for `xerj_hub_def` is clamped to this (the `def` maximum).
const MAX_K: u64 = 50;
/// The largest `max_tokens` accepted (the hosted `code` route's cap).
const MAX_TOKENS_CAP: u64 = 8192;

/// The three tool specs, in the order `tools/list` serves them.
pub fn specs() -> Vec<Value> {
    vec![
        json!({
            "name": "xerj_hub_find",
            "description": concat!(
                "Discover which hub corpora can answer a question. Each candidate names the ",
                "upstream repo (owner/name) and a one-line description of what that pack is, plus ",
                "its pin, licence and whether the pack is already on this machine — not passages; ",
                "ask one with xerj_hub_ask. A query that names a different project of the same slug ",
                "(fabric.js vs the pack's repo) is reported as a different project instead of a ",
                "silent match. A question that names a project no corpus covers is no_coverage \
                 (index it locally with xerj autoindex, then xerj code or xerj search); that is not \
                 an ambiguous tie. Routed exactly as `xerj ask` routes: your project's dependencies, ",
                "the signed catalogue's term sketches, and the exact symbol a definition question ",
                "names (offline: reads the catalogue `xerj hub sync` cached and never fetches it; ",
                "this build has no hosted search). Excluded-licence corpora are never listed."),
            "inputSchema": {
                "type": "object",
                "properties": {
                    "question": {
                        "type": "string",
                        "description": "What the agent is working on; a corpus name is never required here."
                    },
                    "k": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": FIND_MAX_K,
                        "description": format!(
                            "Max candidate corpora to return (default {FIND_DEFAULT_K}, at most {FIND_MAX_K})."
                        )
                    }
                },
                "required": ["question"]
            }
        }),
        json!({
            "name": "xerj_hub_def",
            "description": concat!(
                "Look up one definition in a named hub corpus: its kind, signature, file:line, and ",
                "the literal value for a const/macro/define. Returns an Answer in def mode (no ",
                "passages). Same as `xerj ask --corpus <slug> --def <SYMBOL>`: answered from the ",
                "local pack; a corpus not on this machine is never downloaded by this tool — the ",
                "answer says which `xerj hub pull` line fetches it. Approach-only corpora carry a ",
                "read-do-not-copy warning on every hit."),
            "inputSchema": {
                "type": "object",
                "properties": {
                    "slug": { "type": "string", "description": "Corpus slug to resolve the symbol in." },
                    "symbol": { "type": "string", "description": "Exact definition name." },
                    "k": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": MAX_K,
                        "description": "Max hits to return (default 5)."
                    }
                },
                "required": ["slug", "symbol"]
            }
        }),
        json!({
            "name": "xerj_hub_ask",
            "description": concat!(
                "Ask a hub corpus a question in one turn — no clone, no local indexing. Local packs ",
                "first, hosted second, exactly like `xerj ask`. The corpus is optional (routed by ",
                "the offline sketch when omitted) and is always named in the answer; when more than ",
                "one corpus fits, the candidates come back and you re-ask with `corpus`. When no \
                 corpus covers the topic, the result says so and points at local indexing instead of \
                 asking you to pick a corpus. Never ",
                "downloads a pack: a corpus not on this machine is answered with the `xerj hub ",
                "pull` line to run, and never fetches the catalogue: with none cached it says to run ",
                "`xerj hub sync`. Result text is the hub rendering (corpus, pin date, licence, ",
                "file:line); structured content is the Answer JSON."),
            "inputSchema": {
                "type": "object",
                "properties": {
                    "question": { "type": "string", "description": "Natural-language question." },
                    "corpus": { "type": "string", "description": "Optional explicit corpus slug; omit to route by sketch." },
                    "mode": {
                        "type": "string",
                        "enum": ["def", "how", "files"],
                        "description": "Answer shape; omit for auto (a lone identifier or 'what is the value of X' is def)."
                    },
                    "max_tokens": {
                        "type": "integer",
                        "minimum": 1,
                        "maximum": MAX_TOKENS_CAP,
                        "description": "Soft output budget for the rendered answer (about 4 characters a token)."
                    }
                },
                "required": ["question"]
            }
        }),
    ]
}

/// Dispatch one `xerj_hub_*` call; `None` when `name` is not a hub tool.
pub async fn call(ctx: &Ctx, name: &str, args: &Value) -> Option<Value> {
    let result = match name {
        "xerj_hub_find" => find(args).await,
        "xerj_hub_def" => def(ctx, args).await,
        "xerj_hub_ask" => ask_tool(ctx, args).await,
        _ => return None,
    };
    Some(result.unwrap_or_else(|msg| tool_text(format!("{name}: {msg}"), true)))
}

// ── argument checks ──────────────────────────────────────────────────────────

/// A required, non-blank string of at most [`MAX_INPUT_BYTES`].
fn text_arg(args: &Value, key: &str) -> Result<String, String> {
    let raw = match args.get(key) {
        Some(Value::String(s)) => s,
        Some(_) => return Err(format!("`{key}` must be a string")),
        None => return Err(format!("`{key}` is required")),
    };
    if raw.len() > MAX_INPUT_BYTES {
        return Err(format!(
            "`{key}` is limited to {MAX_INPUT_BYTES} bytes, got {}",
            raw.len()
        ));
    }
    let t = raw.trim();
    if t.is_empty() {
        return Err(format!("`{key}` must not be blank"));
    }
    Ok(t.to_string())
}

/// The longest corpus slug a tool accepts — the server's `valid_slug` cap.
const MAX_SLUG_BYTES: usize = 64;

/// A corpus slug, checked before anything is looked up or built from it.
fn slug_arg(args: &Value, key: &str, required: bool) -> Result<Option<String>, String> {
    match args.get(key) {
        None | Some(Value::Null) if !required => Ok(None),
        None | Some(Value::Null) => Err(format!("`{key}` is required")),
        Some(Value::String(s)) if s.len() <= MAX_SLUG_BYTES && xerj_hub::cli::valid_slug(s) => {
            Ok(Some(s.clone()))
        }
        Some(Value::String(s)) if s.is_empty() && !required => Ok(None),
        Some(_) => Err(format!(
            "`{key}` must be a corpus slug (lower-case letters, digits, '.', '_', '-'; at most \
             {MAX_SLUG_BYTES} bytes)"
        )),
    }
}

/// An optional integer in `1..=max`.
fn int_arg(args: &Value, key: &str, max: u64) -> Result<Option<u64>, String> {
    match args.get(key) {
        None | Some(Value::Null) => Ok(None),
        Some(v) => match v.as_u64().filter(|n| (1..=max).contains(n)) {
            Some(n) => Ok(Some(n)),
            None => Err(format!("`{key}` must be an integer from 1 to {max}")),
        },
    }
}

// ── the tools ────────────────────────────────────────────────────────────────

async fn find(args: &Value) -> Result<Value, String> {
    let question = text_arg(args, "question")?;
    let k = int_arg(args, "k", FIND_MAX_K as u64)?.map_or(FIND_DEFAULT_K, |n| n as usize);
    let found = tokio::task::spawn_blocking(move || ask::run_find(&question, k))
        .await
        .map_err(|e| format!("join error: {e}"))??;
    Ok(json!({
        "content": [ { "type": "text", "text": ask::render_find(&found) } ],
        "structuredContent": found,
        "isError": false,
    }))
}

async fn def(ctx: &Ctx, args: &Value) -> Result<Value, String> {
    let slug = slug_arg(args, "slug", true)?.unwrap_or_default();
    let symbol = text_arg(args, "symbol")?;
    let k = int_arg(args, "k", MAX_K)?;
    let mut a = AskArgs::new(symbol.clone());
    a.corpus = Some(slug);
    a.mode = ModeRequest::Def(symbol);
    a.k = k.map(|n| n as usize);
    Ok(run(ctx, a).await)
}

async fn ask_tool(ctx: &Ctx, args: &Value) -> Result<Value, String> {
    let question = text_arg(args, "question")?;
    let corpus = slug_arg(args, "corpus", false)?;
    let mode = match args.get("mode") {
        None | Some(Value::Null) => ModeRequest::Auto,
        Some(Value::String(m)) => match m.as_str() {
            "how" => ModeRequest::How,
            "files" => ModeRequest::Files,
            // `def` names no symbol of its own: the one the question names
            // (`what is the value of X`), else the whole question — what
            // `xerj ask --def` would be given.
            "def" => ModeRequest::Def(
                ask::detect_mode(&question, &ModeRequest::Auto)
                    .1
                    .unwrap_or_else(|| question.clone()),
            ),
            other => return Err(format!("`mode` must be def, how or files, not '{other}'")),
        },
        Some(_) => return Err("`mode` must be a string".to_string()),
    };
    let max_tokens = int_arg(args, "max_tokens", MAX_TOKENS_CAP)?;
    let mut a = AskArgs::new(question);
    a.corpus = corpus;
    a.mode = mode;
    a.max_tokens = max_tokens.map(|n| n as usize);
    Ok(run(ctx, a).await)
}

/// Run the CLI's flow for `a` (never fetching a pack or the catalogue) against
/// this server's node and turn the outcome into a tool result.
async fn run(ctx: &Ctx, mut a: AskArgs) -> Value {
    a.no_fetch = true;
    a.cached_catalogue_only = true;
    a.json = false;
    a.url = Some(ctx.base_url.clone());
    let launcher = match launcher() {
        Ok(l) => l,
        Err(e) => return tool_text(e, true),
    };
    let question = a.question.clone();
    match tokio::task::spawn_blocking(move || ask::run_ask_with(&a, None, launcher)).await {
        Ok(outcome) => {
            if let Some(answer) = &outcome.answer {
                auto_review(answer, &question);
            }
            outcome_result(outcome)
        }
        Err(e) => tool_text(format!("join error: {e}"), true),
    }
}

/// One automatic review per corpus per week after a hub answer
/// ([`xerj_hub::feedback::auto_review_for_answer`]: hits or not, the pack's age,
/// the question's shape only). Sent in the background, so the tool result is
/// never held; failures are silent. Off with the feedback opt-out. The agent's
/// own `xerj_corpus_feedback` replaces it on the server.
fn auto_review(answer: &xerj_common::hub::Answer, question: &str) {
    let (family, version) = crate::client_family();
    let Some(review) =
        xerj_hub::feedback::auto_review_for_answer(answer, question, &family, &version)
    else {
        return;
    };
    tokio::task::spawn_blocking(move || {
        let path = xerj_hub::feedback::state_path();
        if let Some(r) = xerj_hub::feedback::claim_auto(&path, "mcp", review) {
            let _ = xerj_hub::feedback::send_blocking(
                &r,
                &xerj_common::corpus_feedback::endpoint_from_env(),
                xerj_hub::feedback::AUTO_TIMEOUT,
            );
        }
    });
}

/// The re-ask hint as the CLI words it, and as a tool caller needs it.
const CLI_CORPUS_HINT: &str = "re-run with --corpus <slug>";
const MCP_CORPUS_HINT: &str = "call xerj_hub_ask again with the `corpus` argument";

/// An [`AskOutcome`] as a tool result. An answer — including one with no hits
/// (a miss is an answer, not an error) — carries the Answer JSON as structured
/// content. More than one candidate corpus is not an error either: the text
/// lists them for a re-ask with `corpus`. Anything else is `isError`.
fn outcome_result(o: AskOutcome) -> Value {
    let mut text = String::new();
    for line in &o.stderr {
        // The flow's hints name the CLI flag; a tool caller sets an argument.
        text.push_str(&line.replace(CLI_CORPUS_HINT, MCP_CORPUS_HINT));
        text.push('\n');
    }
    text.push_str(&o.stdout);
    match o.answer {
        Some(answer) => json!({
            "content": [ { "type": "text", "text": text } ],
            "structuredContent": answer,
            "isError": false,
        }),
        None => tool_text(text, o.exit != EXIT_NEEDS_DECISION),
    }
}

/// What starts the automatic hub node: this executable when it is `xerj`
/// (`xerj mcp`); for the standalone `xerj-mcp` binary — which takes no node
/// flags — the `xerj` beside it, else `xerj` on `PATH`.
fn launcher() -> Result<NodeLauncher, String> {
    let current = NodeLauncher::current().map_err(|e| format!("{e:#}"))?;
    let standalone = current
        .exe
        .file_stem()
        .is_some_and(|s| s.to_string_lossy() == "xerj-mcp");
    if !standalone {
        return Ok(current);
    }
    let sibling = current
        .exe
        .with_file_name(format!("xerj{}", std::env::consts::EXE_SUFFIX));
    Ok(NodeLauncher {
        exe: if sibling.is_file() {
            sibling
        } else {
            std::path::PathBuf::from("xerj")
        },
        pre_args: Vec::new(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn arguments_are_refused_before_anything_runs() {
        let long = "x".repeat(MAX_INPUT_BYTES + 1);
        assert!(text_arg(&json!({ "question": long }), "question").is_err());
        assert!(text_arg(&json!({ "question": "  " }), "question").is_err());
        assert!(text_arg(&json!({ "question": 7 }), "question").is_err());
        assert_eq!(
            text_arg(&json!({ "question": " q " }), "question").unwrap(),
            "q"
        );
        for bad in ["../etc", "a/b", "", "UPPER", "-lead"] {
            assert!(
                slug_arg(&json!({ "slug": bad }), "slug", true).is_err(),
                "{bad:?}"
            );
        }
        assert_eq!(
            slug_arg(&json!({ "slug": "mini-c" }), "slug", true).unwrap(),
            Some("mini-c".into())
        );
        assert_eq!(slug_arg(&json!({}), "corpus", false).unwrap(), None);
        assert!(int_arg(&json!({ "k": 0 }), "k", 50).is_err());
        assert!(int_arg(&json!({ "k": 51 }), "k", 50).is_err());
        assert!(int_arg(&json!({ "k": "5" }), "k", 50).is_err());
        assert_eq!(int_arg(&json!({ "k": 50 }), "k", 50).unwrap(), Some(50));
    }

    /// Review finding (rev7): `slug_arg` took a slug of any length (a 200 KB
    /// one was accepted and echoed back in "unknown corpus '…'"). The server's
    /// own `valid_slug` caps a slug at 64 bytes; the tool arguments do too.
    #[test]
    fn a_slug_longer_than_the_servers_cap_is_refused_and_never_echoed() {
        let at_cap = "a".repeat(MAX_SLUG_BYTES);
        assert_eq!(
            slug_arg(&json!({ "slug": at_cap }), "slug", true).unwrap(),
            Some(at_cap.clone())
        );
        for len in [MAX_SLUG_BYTES + 1, 200 * 1024] {
            let long = "a".repeat(len);
            for (key, required) in [("slug", true), ("corpus", false)] {
                let err = slug_arg(&json!({ key: long }), key, required)
                    .expect_err("over the cap is refused");
                assert!(
                    err.len() < 200,
                    "the slug is not echoed back: {}",
                    err.len()
                );
            }
        }
    }

    #[test]
    fn an_ambiguous_route_is_not_an_error_and_a_failure_is() {
        let ambiguous = AskOutcome {
            exit: EXIT_NEEDS_DECISION,
            stdout: "a — x\nb — y".into(),
            stderr: vec!["more than one corpus matches; re-run with --corpus <slug>".into()],
            answer: None,
        };
        let r = outcome_result(ambiguous);
        assert_eq!(r["isError"], false);
        assert!(r["content"][0]["text"].as_str().unwrap().contains("a — x"));
        let failed = AskOutcome {
            exit: 1,
            stdout: String::new(),
            stderr: vec!["no hub corpus matches; see xerj.org/llms.txt".into()],
            answer: None,
        };
        assert_eq!(outcome_result(failed)["isError"], true);
    }

    /// FTX shell-less trial (2026-10-17): the "nothing matches" and "more than one
    /// corpus" hints told a tool caller to "re-run with --corpus <slug>", a CLI
    /// flag it has no way to pass. The tool result names the argument instead.
    #[test]
    fn the_reask_hint_names_the_tool_argument_not_the_cli_flag() {
        for (exit, line) in [
            (
                1,
                "closest corpora: lz4, snappy; re-run with --corpus <slug> to ask one of them",
            ),
            (
                EXIT_NEEDS_DECISION,
                "more than one corpus matches; re-run with --corpus <slug>",
            ),
        ] {
            let r = outcome_result(AskOutcome {
                exit,
                stdout: String::new(),
                stderr: vec![line.into()],
                answer: None,
            });
            let text = r["content"][0]["text"].as_str().unwrap();
            assert!(!text.contains("--corpus"), "{text}");
            assert!(
                text.contains("xerj_hub_ask again with the `corpus` argument"),
                "{text}"
            );
        }
    }
}

//! `xerj-mcp` — a Model Context Protocol (MCP) server for XERJ.
//!
//! This crate is both a **library** and a standalone binary. The library entry
//! point is [`run`], which the main `xerj` binary calls for its `xerj mcp`
//! subcommand — so a user who installed the single `xerj` binary already has
//! the MCP server, with nothing to clone and nothing to compile. The
//! standalone `xerj-mcp` binary is a thin wrapper over the same [`run`] and
//! stays available for CI and for embedding without the engine.
//!
//! It speaks the MCP **stdio transport**: newline-delimited
//! JSON-RPC 2.0 messages on stdin/stdout. It exposes XERJ to any MCP-capable
//! agent host (Claude Desktop, IDE agents, custom orchestrators) as twenty-two
//! tools: nineteen without a hub key, and three Corpus Hub tools
//! (`xerj_hub_*`) that run the `xerj ask` flow itself. Thirteen of those
//! nineteen construct exactly the request the running engine already accepts
//! and forward it to a configurable base URL. `xerj_index_budget` counts a
//! folder and returns the budget plans; it does not index. `xerj_autoindex_remove`
//! deletes one autoindexed folder after listing what that folder owns, and only
//! when the caller passes `confirm: true`. `xerj_corpus_feedback` posts an
//! agent's review of a hub corpus to hub.xerj.org. `xerj_field_report` does not:
//! it files a field report, not to the node: a GitHub PR first (through
//! `xerj feedback --submit --github-only`), and a POST to the web endpoint only
//! when GitHub is unavailable. It sends by default; `confirm: false` previews,
//! and `--disable-feedback` / `XERJ_DISABLE_FEEDBACK=true` turn sending off.
//!
//! ## Canonical agent operations
//!
//! | MCP tool               | XERJ endpoint                         | Real capability |
//! |------------------------|---------------------------------------|-----------------|
//! | `xerj_def` | `GET /{index}/_mapping` + `POST /{index}/_search` | local definition lookup with CLI ranking and deduplication |
//! | `xerj_search`          | `POST /{index}/_search`               | ES query-DSL search (full-text / keyword / structured) |
//! | `xerj_batch_search` | `GET /{index}/_mapping` + `POST /_msearch` | ordered per-item evidence, abstention or error; shared with `xerj batch-search` |
//! | `xerj_semantic_search` | `POST /{index}/_search` (`semantic`)  | server-side lexical embedding, no external key |
//! | `xerj_vector_search`   | `POST /{index}/_search` (`knn`)       | kNN over a `dense_vector` field (HNSW-served unfiltered, exact filtered) |
//! | `xerj_hybrid_search`   | `POST /{index}/_search` (`hybrid`)    | RRF or linear fusion of sub-queries |
//! | `xerj_memory_store`    | `POST /_memory/{ns}`                  | namespaced agent-memory write |
//! | `xerj_memory_recall`   | `POST /_memory/{ns}/_recall`          | recall by meaning (BM25 / semantic / vector), optionally graph-coupled |
//! | `xerj_brain_ego`       | `GET /_graph/{brain}/ego`             | one node's evidence-backed, bi-temporal link neighborhood |
//! | `xerj_brain_link`      | `POST /_graph/{brain}/link`           | assert a link (idempotent, deterministic edge_id) |
//! | `xerj_brain_unlink`    | `DELETE /_graph/{brain}/link/{id}`    | retire a link (soft-invalidate; never deletes) |
//! | `xerj_brain_overview`  | `GET /_graph/{brain}/overview`        | whole-brain orientation: counts, hubs, detectors, timeline |
//! | `xerj_plan`            | `POST /_ask`                          | natural-language prompt in, VALIDATED query DSL out (deterministic planner, not an LLM) |
//! | `xerj_field_report`    | `POST /api/field-report` (xerj.org)   | file an agent field report: GitHub PR first, this endpoint when GitHub is unavailable; sends by default |
//! | `xerj_corpus_feedback` | `POST /api/corpus-feedback` (hub.xerj.org) | rate a hub corpus after using it (its Agent score); sends by default; `xerj_hub_ask` / `xerj_hub_def` also send an automatic review |
//! | `xerj_map`             | `POST /autoindex-catalog/_search`     | per-index field map from the autoindex catalog (#1055) |
//! | `xerj_hub_find` / `xerj_hub_def` / `xerj_hub_ask` | the `xerj ask` flow (`src/hub.rs`) | which hub corpus answers; one definition; one question — from local packs, never downloading |
//!
//! ## Honesty notes (must match the engine, never oversell)
//!
//! * Unfiltered kNN is **HNSW-served with exact rescoring** (measured recall@10
//!   1.00 on the official bench query); filtered kNN and other ineligible shapes
//!   (non-cosine, SQ8, small indexes) run the exact brute-force scan. The tool
//!   description says so.
//! * `rerank` on `xerj_search` / `xerj_hybrid_search` is **opt-in and needs a
//!   provider the node's operator configured**; this server cannot supply the
//!   key. It is also the one argument that makes the node send document text to
//!   a third party, and the tool description says so in those words. Ranking
//!   quality with the real provider model has **not been verified by this
//!   project** — the description promises the mechanism (a calibrated
//!   probability replaces `_score`), never an accuracy figure.
//! * `hybrid` supports `fusion: "rrf"` and `"linear"` only. `"learned"` is
//!   forwarded verbatim and the engine rejects it loudly; the schema therefore
//!   advertises only `rrf`/`linear`.
//! * The `xerj_brain_*` tools work a **link index, not a graph database**:
//!   deterministic lexical detection plus explicit assertions — no neural
//!   understanding, no query language, no unbounded traversal. Every brain
//!   tool description says both things, and engine refusals (e.g. the hops
//!   cap) are passed back to the agent verbatim.
//! * `xerj_def` shares the CLI definition query and local result ranking;
//!   engine errors are passed back unchanged.
//!
//! ## Configuration (environment)
//!
//! * `XERJ_URL`  — base URL of the XERJ ES-compatible listener. Default
//!   `http://localhost:9200`.
//! * `XERJ_AUTH` — optional; if set, sent verbatim as the `Authorization`
//!   header on every proxied request (e.g. `ApiKey <token>`).
//!
//! When neither `XERJ_AUTH` nor `--auth` is given **and** the target is
//! loopback, the server falls back to the admin key a local node wrote for
//! itself (`<data_dir>/admin.key` — the same discovery `xerj autoindex`
//! uses) and announces the file it used on stderr. Auth is on by default, so
//! this fallback is what makes the documented `xerj init` one-command setup
//! work against a default node instead of 401-ing on every tool call (#961).
//! It never fires for a non-loopback URL: a locally readable key sent to
//! another host is a credential leak, not a convenience.
//!
//! Both have a flag form — `--url` and `--auth` — which wins over the
//! environment. MCP client configs usually set the `env` block, so the
//! environment stays the documented path; the flags exist for hosts that only
//! let you supply `args`.
//!
//! Diagnostics go to **stderr**; stdout is reserved exclusively for the
//! JSON-RPC stream.
//!
//! ## Token budgets (#1058)
//!
//! The six search tools accept `max_tokens` and are held to it: the response
//! text NEVER exceeds the budget. Enforcement lives in [`token_budget`],
//! counted with one named tokenizer (XERJ's `StandardTokenizer`, UAX #29
//! words), with duplicate passages removed before budgeting and
//! over-budget hits reduced to locators.

