            "judge": { "min_p": 0.4 }
        })));
        assert_eq!(body["rerank"]["window"], 20);
        assert_eq!(body["judge"]["min_p"], 0.4);
        assert_eq!(body["judge"]["query"], "how do refunds work");
    }

