                } }
            }),
        ));
        let request = server.join().expect("fake node thread");
        assert_eq!(res["isError"], false, "{res}");
        assert!(
            request.contains("\"from\":3"),
            "the caller's offset is forwarded: {request}"
        );
        assert!(
            request.contains("\"size\":3") && !request.contains("\"size\":43"),
