                .as_array()
                .unwrap()
                .iter()
                .map(|t| t["name"].as_str().unwrap().to_string())
                .collect()
        };
        let without = names(false);
        assert_eq!(without.len(), 19, "{without:?}");
        assert!(
            without.iter().all(|n| !n.starts_with("xerj_hub_")),
