    // ── loopback admin-key fallback (#961) ──────────────────────────────

    /// Serialises the tests that move process-global state. Discovery reads
    /// the working directory and `HOME`, both per-process.
    static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    /// A temporary working directory and `HOME`, restored on drop (including
    /// on panic) so the discovery tests see only the key files they wrote —
    /// the same sandbox shape as `xerj-autoindex`'s cli tests, where the
    /// helper this exercises was born.
    struct Sandbox {
        _lock: std::sync::MutexGuard<'static, ()>,
        dir: tempfile::TempDir,
        previous_dir: std::path::PathBuf,
        previous_home: Option<std::ffi::OsString>,
    }

    impl Sandbox {
        fn new() -> Self {
            let lock = ENV_LOCK.lock().unwrap_or_else(|poison| poison.into_inner());
            let dir = tempfile::tempdir().unwrap();
            let previous_dir = std::env::current_dir().unwrap();
            let previous_home = std::env::var_os("HOME");
            std::env::set_current_dir(dir.path()).unwrap();
            std::env::set_var("HOME", dir.path().join("home"));
            Self {
                _lock: lock,
                dir,
                previous_dir,
                previous_home,
            }
        }

        fn write(&self, relative: &str, contents: &str) {
            let path = self.dir.path().join(relative);
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            std::fs::write(path, contents).unwrap();
        }
    }

    impl Drop for Sandbox {
        fn drop(&mut self) {
            std::env::set_current_dir(&self.previous_dir).unwrap();
            match &self.previous_home {
                Some(home) => std::env::set_var("HOME", home),
                None => std::env::remove_var("HOME"),
            }
        }
    }

    /// The gap #961 is about: `xerj init` writes only XERJ_URL, auth is on by
    /// default, and the documented setup 401'd on every tool call. With a
    /// loopback URL and a key on disk, discovery closes that gap.
    #[test]
    fn loopback_url_with_no_auth_picks_up_the_local_admin_key() {
        let sandbox = Sandbox::new();
        sandbox.write("data/admin.key", "local-admin-key\n");
        let (auth, from) = resolve_auth(None, None, "http://localhost:9200");
        assert_eq!(auth.as_deref(), Some("ApiKey local-admin-key"));
        assert_eq!(
            from,
            Some(sandbox.dir.path().join("data/admin.key")),
            "the announced path is the file actually used"
        );

        // The no-configuration shape: XERJ_URL unset means the loopback
        // default, which is exactly the `xerj init` entry.
        let (auth, _) = resolve_auth(None, None, DEFAULT_XERJ_URL);
        assert_eq!(auth.as_deref(), Some("ApiKey local-admin-key"));
    }

    /// Discovery is loopback-only. A locally readable admin key sent to a
    /// host that did not write it is a credential leak — including via the
    /// userinfo trick, where everything before `@` is credentials and the
    /// host is `evil.com`.
    #[test]
    fn non_loopback_urls_never_receive_a_discovered_key() {
        let sandbox = Sandbox::new();
        sandbox.write("data/admin.key", "local-admin-key\n");
        for url in [
            "http://search.example.com:9200",
            "http://192.168.1.5:9200",
            "https://localhost.evil.com:9200",
            "http://localhost:9200@evil.com/",
            "http://127.0.0.1:80@evil.com/",
            "localhost:9200@evil.com",
        ] {
            let (auth, from) = resolve_auth(None, None, url);
            assert!(
                auth.is_none() && from.is_none(),
                "{url} must never be sent a key found on this disk"
            );
        }
    }

    /// A credential the user supplied is never overwritten by one found on
    /// disk — and an *empty* value is unset, not a credential: shadowing
    /// discovery with `Authorization: ` would reproduce the silent 401.
    #[test]
    fn explicit_auth_wins_over_loopback_discovery() {
        let sandbox = Sandbox::new();
        sandbox.write("data/admin.key", "local-admin-key\n");

        let (auth, from) = resolve_auth(
            Some("Bearer token".into()),
            Some("ApiKey env".into()),
            "http://localhost:9200",
        );
        assert_eq!(auth.as_deref(), Some("Bearer token"));
        assert!(
            from.is_none(),
            "an explicit --auth is never re-sourced from disk"
        );

        let (auth, from) = resolve_auth(None, Some("ApiKey env".into()), "http://localhost:9200");
        assert_eq!(auth.as_deref(), Some("ApiKey env"));
        assert!(from.is_none(), "XERJ_AUTH also wins over discovery");

        let (auth, _) = resolve_auth(Some(String::new()), None, "http://localhost:9200");
        assert_eq!(
            auth.as_deref(),
            Some("ApiKey local-admin-key"),
            "an empty --auth/XERJ_AUTH must fall through to discovery"
        );
    }

    /// A server that has not finished writing its key, or a file truncated
    /// by hand, must not become `Authorization: ApiKey ` — the same 401 with
    /// none of the diagnosis.
    #[test]
    fn empty_key_files_are_skipped_not_turned_into_empty_headers() {
        let sandbox = Sandbox::new();
        sandbox.write("data/admin.key", "  \n\t\n");
        sandbox.write("xerj-data/admin.key", "");
        let (auth, from) = resolve_auth(None, None, "http://localhost:9200");
        assert!(
            auth.is_none() && from.is_none(),
            "whitespace-only and zero-byte files are not credentials"
        );

        sandbox.write("home/.xerj/admin.key", "real-key\n");
        let (auth, _) = resolve_auth(None, None, "http://localhost:9200");
        assert_eq!(
            auth.as_deref(),
            Some("ApiKey real-key"),
            "an empty candidate must be skipped over, not stop the search"
        );
    }

    /// #2339: MCP `xerj_code_search` is the same renderer as `xerj code`.
    /// An own corpus keeps UNKNOWN in the header and drops the do-not-copy
    /// banner. The same passage from a corpus that is not marked own still
    /// carries the banner.
    #[test]
    fn code_search_own_corpus_omits_the_unidentified_copy_banner() {
        let home = tempfile::tempdir().unwrap();
        let previous = std::env::var("XERJ_CODE_HOME").ok();
        std::env::set_var("XERJ_CODE_HOME", home.path());
        struct Restore(Option<String>);
        impl Drop for Restore {
            fn drop(&mut self) {
                match &self.0 {
                    Some(value) => std::env::set_var("XERJ_CODE_HOME", value),
                    None => std::env::remove_var("XERJ_CODE_HOME"),
                }
            }
        }
        let _restore = Restore(previous);

        let write_corpus = |name: &str, own: bool| {
            let dir = home.path().join("corpora").join(name);
            std::fs::create_dir_all(dir.join("myrepo")).unwrap();
            let own_json = if own { ",\"own\":true" } else { "" };
            std::fs::write(
                dir.join("corpus.json"),
                format!(
                    "{{\"corpus\":\"{name}\"{own_json},\"repos\":[{{\"repo\":\"myrepo\",\"url\":\"u\",\"licence\":\"UNKNOWN\"}}]}}"
                ),
            )
            .unwrap();
            std::fs::create_dir_all(home.path().join("state")).unwrap();
            // An unparsable stamp disables the age refusal; this test is
            // about the banner, not the clock.
            std::fs::write(
                home.path().join("state").join(format!("{name}.json")),
                format!(
                    "{{\"corpus\":\"{name}\",\"indexed_at\":\"fresh\",\"prefix\":\"xc-{name}\",\"url\":\"u\",\"autoindex_exit\":0,\"salvaged\":false,\"build\":\"b1\",\"index_prefix\":\"xc-{name}-b1\",\"state_dir\":\"/tmp/s\"}}"
                ),
            )
            .unwrap();
        };
        write_corpus("owned", true);
        write_corpus("other", false);

        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let address = listener.local_addr().unwrap();
        let server = std::thread::spawn(move || {
            let mapping = r#"{"idx":{"mappings":{"properties":{"body":{"type":"text"}}}}}"#;
            let hit = r#"{"hits":{"hits":[{"_score":4.0,"_source":{"ax_path":"myrepo/src/lib.rs","line":1,"body":"fn mine() {}\n"}}]}}"#;
            let cat = r#"[{"index":"xc-owned-b1-000"}]"#;
            let started = std::time::Instant::now();
            let mut served = 0;
            while served < 6 && started.elapsed() < std::time::Duration::from_secs(20) {
                let (mut sock, _) = match listener.accept() {
                    Ok(pair) => pair,
                    Err(err) if err.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(20));
                        continue;
                    }
                    Err(_) => break,
                };
                sock.set_nonblocking(false).unwrap();
                served += 1;
                sock.set_read_timeout(Some(std::time::Duration::from_secs(5)))
                    .unwrap();
                let mut buf = Vec::new();
                let mut tmp = [0u8; 4096];
                loop {
                    match std::io::Read::read(&mut sock, &mut tmp) {
                        Ok(0) => break,
                        Ok(n) => {
                            buf.extend_from_slice(&tmp[..n]);
                            if let Some(header_end) = buf.windows(4).position(|w| w == b"\r\n\r\n")
                            {
                                let headers = String::from_utf8_lossy(&buf[..header_end]);
                                let length = headers.lines().find_map(|line| {
                                    let rest = line
                                        .split_once(':')
                                        .filter(|(name, _)| {
                                            name.eq_ignore_ascii_case("content-length")
                                        })?
                                        .1;
                                    rest.trim().parse::<usize>().ok()
                                });
                                let body_at = header_end + 4;
                                if let Some(length) = length {
                                    while buf.len() < body_at + length {
                                        match std::io::Read::read(&mut sock, &mut tmp) {
                                            Ok(0) | Err(_) => break,
                                            Ok(n) => buf.extend_from_slice(&tmp[..n]),
                                        }
                                    }
                                }
                                break;
                            }
                        }
                        Err(_) => break,
                    }
                }
                let head = String::from_utf8_lossy(&buf);
                let body = if head.contains("_cat/indices") {
                    cat
                } else if head.contains("_mapping") {
                    mapping
                } else {
                    hit
                };
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                let _ = std::io::Write::write_all(&mut sock, response.as_bytes());
            }
        });

        let ctx = Ctx {
            client: reqwest::Client::new(),
            base_url: format!("http://{address}"),
            auth: None,
        };
        let owned = block_on(call_tool(
            &ctx,
            &json!({"params": {"name": "xerj_code_search", "arguments": {
                "corpus": "owned", "query": "fn mine"
            }}}),
        ));
        let other = block_on(call_tool(
            &ctx,
            &json!({"params": {"name": "xerj_code_search", "arguments": {
                "corpus": "other", "query": "fn mine"
            }}}),
        ));
        server.join().unwrap();

        let owned_text = tool_body(&owned);
        let other_text = tool_body(&other);
        assert_eq!(owned["isError"], false, "{owned_text}");
        assert_eq!(other["isError"], false, "{other_text}");
        assert!(owned_text.contains(", UNKNOWN)"), "{owned_text}");
        assert!(owned_text.contains("fn mine()"), "{owned_text}");
        assert!(!owned_text.contains("!!"), "{owned_text}");
        assert!(!owned_text.contains("do not copy"), "{owned_text}");
        assert!(
            other_text.contains("!! UNKNOWN: adapt the APPROACH, do not copy the code"),
            "{other_text}"
        );
        assert!(other_text.contains(", UNKNOWN)"), "{other_text}");
    }
}

//! Standalone `xerj-mcp` binary — a thin wrapper over [`xerj_mcp::run`].
//!
//! The same entry point is reachable as `xerj mcp` on the main binary, which
//! is the path a user who ran the published installer has. This binary stays
//! because CI builds and smoke-tests it, and because embedding the MCP proxy
//! without the engine is occasionally useful.

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    xerj_mcp::run(&args).await
}

//! `xerj_map` — the per-index field map from the autoindex catalog (#1055).
//!
//! The catalog index (`autoindex-catalog`) holds one `doc_kind: dataset`
//! document per dataset `xerj autoindex` indexed, and inside each of those,
//! `fields_json` carries the `FieldSpec` list the profiler inferred: name,
//! es_type, cardinality estimate, coverage, examples, and — since #1055 — the
//! sampled date/numeric min-max. The CLI renders that as `xerj autoindex
//! map`; an MCP agent had no way to reach it, which is why agents guessed
//! field names and ate unknown-field 400s on the DSL they then sent.
//!
//! This module is the READ side only and re-derives nothing: every fact in
//! the response comes from the catalog document verbatim. The catalog index
//! name is repeated here (a string constant in `xerj-autoindex/src/catalog.rs`)
//! because depending on that crate would drag the tree-sitter/SQLite/AWS
//! stack into this thin proxy; the name is a frozen on-disk contract there
//! (hashed into `index_identity`), which is what makes the copy safe — it
//! cannot be renamed in place.
//!
//! ## The per-index byte cap
//!
//! A response renders at most [`DEFAULT_MAX_BYTES`] of JSON per index entry.
//! The trim ladder, applied per entry until it fits and reported in the
//! entry's `trimmed` array (a stage that changes nothing is not reported):
//!
//! 1. per-field `examples` cut to the first example;
//! 2. `examples` dropped entirely;
//! 3. per-field `notes` dropped;
//! 4. fields dropped from the end of the list — it is sorted coverage
//!    descending, so the lowest-coverage fields go first — each counted in
//!    `fields_omitted`. A single field that alone exceeds the cap is dropped
//!    whole, which is what guarantees the ladder terminates.

use std::collections::BTreeMap;

use serde_json::{json, Map, Value};

use crate::{tool_text, Ctx};

/// The catalog index, written by `xerj autoindex`. See the module docs for
/// why this is a copy and not a dependency.
pub const CATALOG_INDEX: &str = "autoindex-catalog";

/// Default per-index byte budget for the rendered entry (#1055 acceptance:
/// "default response ≤ 4 KB per index").
pub const DEFAULT_MAX_BYTES: usize = 4096;
/// Floor for a caller-supplied budget: below this not even one field entry
/// plus the index header renders, and the ladder would drop everything.
pub const MIN_MAX_BYTES: usize = 1024;
/// Datasets fetched (and rendered) per call. Each catalog doc carries the
/// whole `fields_json`, so this bounds the transfer; datasets past it are
/// reported in `indexes_omitted`.
pub const MAX_INDEXES: usize = 100;
/// Examples kept per field. The profiler caps at 3 today; this cap is the
/// published contract if that ever grows.
pub const MAX_EXAMPLES: usize = 5;

/// Past this many datasets, the default `xerj_map` answer is a summary page
/// (index, records, field names) instead of a full field entry per index.
/// A hundred 4 KB entries is what truncated the tool result.
pub const SUMMARY_AT: usize = 8;
/// Datasets in one default summary page.
pub const SUMMARY_PAGE: usize = 25;

/// Parsed, validated `xerj_map` arguments.
#[derive(Debug, Clone)]
pub(crate) struct MapArgs {
    /// Index name or `*`-glob; `None` = every catalogued index.
    pub index: Option<String>,
    /// Per-index byte budget for the rendered entry.
    pub max_bytes: usize,
    /// Skip this many datasets (record-count order) before rendering.
    pub offset: usize,
    /// How many datasets to return. `None` is the summary page when the
    /// catalog is large, and every fetched dataset otherwise.
    pub limit: Option<usize>,
    /// `Some(true)` forces full field entries. `Some(false)` forces the
    /// summary. `None` summarizes when no index filter is set and more than
    /// [`SUMMARY_AT`] datasets matched.
    pub detail: Option<bool>,
}

/// Parse and validate the tool arguments. Present-but-mistyped is an error,
/// never a silent drop (the `opt_typed` policy the rest of this crate holds).
pub(crate) fn parse_args(args: &Value) -> Result<MapArgs, String> {
    let index = match args.get("index") {
        None | Some(Value::Null) => None,
        Some(Value::String(s)) => {
            let t = s.trim();
            (!t.is_empty()).then(|| t.to_string())
        }
        Some(_) => return Err("`index` must be a string (index name or glob)".into()),
    };
    let max_bytes = match args.get("max_bytes") {
        None | Some(Value::Null) => DEFAULT_MAX_BYTES,
        Some(v) => v
            .as_u64()
            .and_then(|n| usize::try_from(n).ok())
            .filter(|n| *n >= MIN_MAX_BYTES)
            .ok_or_else(|| {
                format!(
                    "`max_bytes` must be an integer >= {MIN_MAX_BYTES} (default \
                     {DEFAULT_MAX_BYTES})"
                )
            })?,
    };
    let offset = match args.get("offset") {
        None | Some(Value::Null) => 0,
        Some(v) => v
            .as_u64()
            .and_then(|n| usize::try_from(n).ok())
            .ok_or_else(|| "`offset` must be an integer >= 0".to_string())?,
    };
    let limit = match args.get("limit") {
        None | Some(Value::Null) => None,
        Some(v) => Some(
            v.as_u64()
                .and_then(|n| usize::try_from(n).ok())
                .filter(|n| (1..=MAX_INDEXES).contains(n))
                .ok_or_else(|| format!("`limit` must be an integer from 1 to {MAX_INDEXES}"))?,
        ),
    };
    let detail = match args.get("detail") {
        None | Some(Value::Null) => None,
        Some(Value::Bool(b)) => Some(*b),
        Some(_) => return Err("`detail` must be a boolean".into()),
    };
    Ok(MapArgs {
        index,
        max_bytes,
        offset,
        limit,
        detail,
    })
}

/// The `_search` body for the catalog read. Filter exact names with `term`
/// and globs with `wildcard` before the 100-result cap. Filtering a glob only
/// after the fetch could hide a matching dataset behind 100 larger ones.
pub(crate) fn catalog_body(args: &MapArgs) -> Value {
    let mut must = vec![json!({ "term": { "doc_kind": "dataset" } })];
    if let Some(name) = args.index.as_deref() {
        if name.contains('*') {
            must.push(json!({ "wildcard": { "index_name": name } }));
        } else {
            must.push(json!({ "term": { "index_name": name } }));
        }
    }
    let size = args.limit.unwrap_or(MAX_INDEXES).clamp(1, MAX_INDEXES);
    json!({
        "query": { "bool": { "must": must } },
        "from": args.offset,
        "size": size,
        "sort": [{ "record_count": "desc" }],
        // The dataset doc also carries sample_queries_json (by far its
        // largest field); project it out rather than transfer it to drop it.
        "_source": { "includes": [
            "index_name", "slug", "record_count", "time_field", "time_min",
            "time_max", "semantic_field", "fields_json", "notes",
        ] },
    })
}

/// `*`-glob match — the only wildcard the tool documents. The first and last
/// segments are anchored at the ends of `s`; inner segments may sit
/// anywhere, in order. (So `ax-*` matches `ax-logs` but not `tax-logs`.)
fn glob_match(pattern: &str, s: &str) -> bool {
    match pattern.split_once('*') {
        None => pattern == s,
        Some((head, tail)) => {
            let Some(rest) = s.strip_prefix(head) else {
                return false;
            };
            if tail.is_empty() {
                return true; // trailing star: everything left matches
            }
            (0..=rest.len())
                .filter(|i| rest.is_char_boundary(*i))
                .any(|i| glob_match(tail, &rest[i..]))
        }
    }
}

/// Normalise one raw `FieldSpec` JSON object into the field entry the tool
/// returns: the FieldSpec keys an agent acts on, examples capped, absent
/// keys omitted. Unknown keys in the catalog's `fields_json` pass through —
/// this is a projection, not a re-derivation.
fn project_field(f: &Value) -> Value {
    let Some(obj) = f.as_object() else {
        return f.clone();
    };
    let mut out = Map::new();
    for (k, v) in obj {
        match k.as_str() {
            // `null_ratio` is 1−coverage and `avg_len` drove the semantic
            // election; neither changes a query an agent writes, and
            // `date_evidence` is restated more compactly by `date_enc`.
            "null_ratio" | "avg_len" | "date_evidence" => {}
            "examples" => {
                let capped: Vec<Value> = v
                    .as_array()
                    .map(|a| a.iter().take(MAX_EXAMPLES).cloned().collect())
                    .unwrap_or_default();
                if !capped.is_empty() {
                    out.insert(k.clone(), Value::Array(capped));
                }
            }
            // Only the overflow is information: an absent key already means
            // "counted, not capped", so `false` is noise on every field.
            "cardinality_overflow" => {
                if v.as_bool().unwrap_or(false) {
                    out.insert(k.clone(), v.clone());
                }
            }
            "coverage" => {
                // 3 decimals: byte-lean, and beyond the sample's precision
                // anyway.
                if let Some(c) = v.as_f64() {
                    out.insert(k.clone(), json!((c * 1000.0).round() / 1000.0));
                }
            }
            _ => {
                if !(v.is_null() || v.as_array().is_some_and(Vec::is_empty)) {
                    out.insert(k.clone(), v.clone());
                }
            }
        }
    }
    Value::Object(out)
}

/// Build the full index entry from the dataset doc and the (possibly
/// trimmed) field list.
fn assemble_entry(
    doc: &Value,
    kept: &[Value],
    field_count: usize,
    trimmed: &[&'static str],
) -> Value {
    let mut entry = Map::new();
    entry.insert(
        "index".into(),
        doc.get("index_name").cloned().unwrap_or(Value::Null),
    );
    if let Some(n) = doc.get("record_count").filter(|v| v.is_number()) {
        entry.insert("records".into(), n.clone());
    }
    for key in [
        "time_field",
        "time_min",
        "time_max",
        "semantic_field",
        "notes",
    ] {
        if let Some(v) = doc
            .get(key)
            .filter(|v| !v.is_null() && !v.as_array().is_some_and(Vec::is_empty))
        {
            entry.insert(key.into(), v.clone());
        }
    }
    entry.insert("field_count".into(), json!(field_count));
    entry.insert("fields".into(), Value::Array(kept.to_vec()));
    let omitted = field_count.saturating_sub(kept.len());
    if omitted > 0 {
        entry.insert("fields_omitted".into(), json!(omitted));
    }
    if !trimmed.is_empty() {
        entry.insert(
            "trimmed".into(),
            json!(trimmed.iter().map(|s| s.to_string()).collect::<Vec<_>>()),
        );
    }
    Value::Object(entry)
}

/// Render one index entry under the byte budget. `fields` arrive already
/// projected and sorted (coverage desc, name asc) — the order the ladder's
/// "drop from the end" relies on.
fn render_entry(doc: &Value, mut kept: Vec<Value>, max_bytes: usize) -> Value {
    let field_count = kept.len();
    let mut trimmed: Vec<&'static str> = Vec::new();
    let fits = |entry: &Value| {
        serde_json::to_string(entry)
            .map(|s| s.len())
            .unwrap_or(usize::MAX)
            <= max_bytes
    };
    let mut entry = assemble_entry(doc, &kept, field_count, &trimmed);
    if fits(&entry) {
        return entry;
    }

    // Stage 1: examples cut to the first. Recorded only when it actually
    // cut something — an honest accounting, not a ritual label.
    let cut = kept.iter_mut().filter_map(|f| f.as_object_mut()).any(|o| {
        o.get("examples")
            .and_then(Value::as_array)
            .is_some_and(|ex| ex.len() > 1)
    });
    if cut {
        for f in &mut kept {
            if let Some(ex) = f.get("examples").and_then(Value::as_array) {
                if ex.len() > 1 {
                    let first = ex[..1].to_vec();
                    if let Some(o) = f.as_object_mut() {
                        o.insert("examples".into(), Value::Array(first));
                    }
                }
            }
        }
        trimmed.push("examples-cut-to-1");
        entry = assemble_entry(doc, &kept, field_count, &trimmed);
        if fits(&entry) {
            return entry;
        }
    }

    // Stage 2: examples dropped entirely.
    for f in &mut kept {
        if let Some(o) = f.as_object_mut() {
            o.remove("examples");
        }
    }
    trimmed.push("examples-dropped");
    entry = assemble_entry(doc, &kept, field_count, &trimmed);
    if fits(&entry) {
        return entry;
    }

    // Stage 3: per-field notes dropped.
    for f in &mut kept {
        if let Some(o) = f.as_object_mut() {
            o.remove("notes");
        }
    }
    trimmed.push("notes-dropped");
    entry = assemble_entry(doc, &kept, field_count, &trimmed);
    if fits(&entry) {
        return entry;
    }

    // Stage 4: drop fields from the end (lowest coverage first). A field
    // that alone exceeds the budget goes too — `kept` can reach empty, and
    // an entry with zero fields (but a truthful `field_count`) still
    // renders, which is what terminates this loop.
    trimmed.push("fields-dropped");
    while !kept.is_empty() {
        kept.pop();
        entry = assemble_entry(doc, &kept, field_count, &trimmed);
        if fits(&entry) {
            return entry;
        }
    }
    entry
}

/// Render the whole tool response from a catalog `_search` response.
/// Pure — every unit test below drives this with a hand-built catalog
/// response, no node required.
pub(crate) fn render_response(resp: &Value, args: &MapArgs) -> String {
    let hits = resp
        .pointer("/hits/hits")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    let total: u64 = resp
        .pointer("/hits/total/value")
        .and_then(Value::as_u64)
        .unwrap_or(hits.len() as u64);

    // Keep the local glob check so only the tool's documented `*` syntax
    // reaches the response even if the engine supports more wildcard syntax.
    let docs: Vec<Value> = hits
        .iter()
        .filter_map(|h| h.get("_source").cloned())
        .filter(|src| {
            args.index.as_deref().is_none_or(|p| {
                !p.contains('*')
                    || glob_match(
                        p,
                        src.get("index_name").and_then(Value::as_str).unwrap_or(""),
                    )
            })
        })
        .collect();

    let mut indexes: Vec<Value> = docs
        .iter()
        .map(|src| {
            let mut fields: Vec<Value> = src
                .get("fields_json")
                .and_then(Value::as_str)
                .and_then(|raw| serde_json::from_str::<Value>(raw).ok())
                .and_then(|v| v.as_array().cloned())
                .unwrap_or_default()
                .iter()
                .map(project_field)
                .collect();
            // Coverage desc, then name — the CLI map's order, and the order
            // the trim ladder's "drop from the end" relies on.
            fn cov_of(f: &Value) -> f64 {
                f.get("coverage").and_then(Value::as_f64).unwrap_or(0.0)
            }
            fn name_of(f: &Value) -> &str {
                f.get("name").and_then(Value::as_str).unwrap_or("")
            }
            fields.sort_by(|a, b| {
                cov_of(b)
                    .partial_cmp(&cov_of(a))
                    .unwrap()
                    .then_with(|| name_of(a).cmp(name_of(b)))
            });
            render_entry(src, fields, args.max_bytes)
        })
        .collect();
    // The engine already sorted by record_count desc; make the order total
    // so tied counts (and cap-truncated result sets) render deterministically.
    indexes.sort_by(|a, b| {
        let rc = |v: &Value| v.get("records").and_then(Value::as_u64).unwrap_or(0);
        rc(b).cmp(&rc(a)).then_with(|| {
            a.get("index")
                .and_then(Value::as_str)
                .unwrap_or("")
                .cmp(b.get("index").and_then(Value::as_str).unwrap_or(""))
        })
    });

    let summarize = match args.detail {
        Some(true) => false,
        Some(false) => true,
        None => args.index.is_none() && indexes.len() > SUMMARY_AT,
    };
    let page_limit = if summarize {
        args.limit.unwrap_or(SUMMARY_PAGE)
    } else {
        args.limit.unwrap_or(indexes.len())
    };
    let shown: Vec<Value> = if summarize {
        indexes.iter().take(page_limit).map(summary_entry).collect()
    } else {
        indexes.into_iter().take(page_limit).collect()
    };
    let mut out = Map::new();
    out.insert("matched".into(), json!(shown.len()));
    if summarize {
        out.insert("summary".into(), json!(true));
        out.insert(
            "hint".into(),
            json!(
                "summary page — pass `index` (name or glob) or `detail: true` with \
                 `offset`/`limit` for full field entries"
            ),
        );
    }
    if let Some(p) = &args.index {
        out.insert("pattern".into(), json!(p));
    }
    out.insert("indexes".into(), Value::Array(shown.clone()));
    // `from` already applied `offset` on a live fetch. Counting from the
    // rendered page (not the fetched page) is what makes a summary of 25
    // out of 161 say so, and it matches the old `total - hits` figure when
    // the whole fetch is rendered.
    let omitted = if summarize || args.limit.is_some() || args.offset > 0 {
        total.saturating_sub(args.offset as u64 + shown.len() as u64)
    } else {
        total.saturating_sub(hits.len() as u64)
    };
    if omitted > 0 {
        out.insert("indexes_omitted".into(), json!(omitted));
    }
    if docs.is_empty() {
        out.insert(
            "hint".into(),
            json!(format!(
                "no datasets in {CATALOG_INDEX} match — the catalog is written by `xerj \
                 autoindex <folder>`; never-autoindexed indexes are not listed (ask the \
                 node's _cat/indices for those)"
            )),
        );
    }
    // #2351: top-level, so a per-index byte trim cannot drop it. Indexes
    // written before the aliases still need `ax_path` and `line`.
    out.insert(
        "locator_hint".into(),
        json!(xerj_autoindex::HIT_LOCATOR_HINT),
    );
    Value::Object(out).to_string()
}

/// One summary row: enough to pick an index, not the field tables that
/// overflow the tool result.
fn summary_entry(entry: &Value) -> Value {
    let names: Vec<Value> = entry
        .get("fields")
        .and_then(Value::as_array)
        .map(|fs| {
            fs.iter()
                .filter_map(|f| f.get("name").cloned())
                .take(40)
                .collect()
        })
        .unwrap_or_default();
    json!({
        "index": entry.get("index").cloned().unwrap_or(Value::Null),
        "records": entry.get("records").cloned().unwrap_or(Value::Null),
        "field_count": entry.get("field_count").cloned().unwrap_or(json!(0)),
        "field_names": names,
    })
}

/// Locator fields autoindex stamps on every record and maps as keyword
/// (`xerj_autoindex::PROVENANCE_FIELDS`). Copied here so this proxy does not
/// depend on that crate. The profiler never sees them, so a catalog written
/// before #2120 omits them from `fields_json` even though they are queryable.
const PROVENANCE_FIELDS: &[&str] = &[
    "ax_path",
    "ax_paths",
    "ax_file",
    "ax_locator",
    "ax_dataset",
    "ax_run",
    "ax_format",
];

fn provenance_field(name: &str) -> Value {
    json!({
        "name": name,
        "es_type": "keyword",
        "coverage": 1.0,
        "cardinality_est": 0,
        "notes": [
            "autoindex provenance locator, mapped keyword and stamped on every record; \
             not sampled, so cardinality_est 0 means unmeasured"
        ],
    })
}

fn mapped_only_field(name: &str, spec: &Value) -> Value {
    let es_type = spec.get("type").and_then(Value::as_str).unwrap_or("object");
    if PROVENANCE_FIELDS.contains(&name) {
        let mut field = provenance_field(name);
        if let Some(obj) = field.as_object_mut() {
            obj.insert("es_type".into(), json!(es_type));
        }
        field
    } else {
        json!({
            "name": name,
            "es_type": es_type,
            "notes": ["mapped on the index but absent from the profiled catalog"],
        })
    }
}

/// Union each dataset's `fields_json` with the index mapping's top-level
/// properties (or, when `mapping` is `None` because the mapping read failed,
/// with [`PROVENANCE_FIELDS`]).
///
/// A corrupt `fields_json` is left alone: the renderer already turns that
/// into an empty field list rather than an error, and inventing locators on
/// top of a parse failure would hide the corruption.
///
/// Names are appended in sorted order. `render_response` re-sorts by
/// coverage, so this order only matters for the bytes stored back into the
/// hit, which nothing else reads.
pub(crate) fn merge_mapped_fields(resp: &mut Value, mapping: Option<&Value>) {
    let Some(hits) = resp.pointer_mut("/hits/hits").and_then(Value::as_array_mut) else {
        return;
    };
    for hit in hits.iter_mut() {
        let Some(src) = hit.get_mut("_source").and_then(Value::as_object_mut) else {
            continue;
        };
        let index = src
            .get("index_name")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let raw = src
            .get("fields_json")
            .and_then(Value::as_str)
            .unwrap_or("[]");
        let Ok(mut fields) = serde_json::from_str::<Vec<Value>>(raw) else {
            continue;
        };
        if fields.iter().any(|f| !f.is_object()) {
            continue;
        }
        let present: std::collections::HashSet<String> = fields
            .iter()
            .filter_map(|f| f.get("name").and_then(Value::as_str).map(str::to_string))
            .collect();
        let properties = mapping.and_then(|m| {
            m.get(&index)
                .and_then(|v| v.pointer("/mappings/properties"))
                .and_then(Value::as_object)
        });
        if let Some(props) = properties {
            let mut names: Vec<&String> = props.keys().collect();
            names.sort();
            for name in names {
                if name.starts_with('_') || present.contains(name.as_str()) {
                    continue;
                }
                fields.push(mapped_only_field(name, &props[name]));
            }
        } else if mapping.is_none() {
            for name in PROVENANCE_FIELDS {
                if present.contains(*name) {
                    continue;
                }
                fields.push(provenance_field(name));
            }
        }
        if let Ok(encoded) = serde_json::to_string(&fields) {
            src.insert("fields_json".into(), Value::String(encoded));
        }
    }
}

fn field_count_means(mapping_read: bool) -> &'static str {
    if mapping_read {
        "each indexes[].field_count is the catalog's profiled fields union that index's \
         top-level mapping fields, the same set xerj_plan counts as top-level mapping fields. \
         ax_* locators the profiler did not sample are included"
    } else {
        "each indexes[].field_count is the catalog's profiled fields plus the ax_* provenance \
         locators autoindex maps as keyword. The live mapping could not be read, so other \
         mapped-but-unprofiled fields are not listed. xerj_plan's field count is top-level \
         mapping fields"
    }
}

/// Note attached to a map that has family warnings. The array itself is the
/// same objects the autoindex run summary stores on the catalog run document.
const FAMILY_JUNK_NOTE: &str = "Each entry is a file family where every file, or a strict \
     majority of its files, was junked during autoindex and not indexed. `top_reason` is the \
     most common junk reason (ties break by Unicode code-point order). Clean families and \
     minority junk are omitted. Exit codes are unchanged.";

/// Latest run per `prefix`, then that run's `family_junk_warnings`, if any.
///
/// An older run's warnings are not reported once a newer run of the same
/// prefix exists: the latest run is the summary. `started` is compared as a
/// string (RFC3339 sorts chronologically). Equal `started` values break by
/// `run_id`, code-point order, greater first — not by search hit order.
pub(crate) fn family_warnings_from_runs(runs: &[Value]) -> Vec<Value> {
    let mut latest: BTreeMap<&str, &Value> = BTreeMap::new();
    for run in runs {
        let prefix = run.get("prefix").and_then(Value::as_str).unwrap_or("");
        match latest.get(prefix) {
            Some(prev) if !run_is_newer(run, prev) => {}
            _ => {
                latest.insert(prefix, run);
            }
        }
    }
    let mut out = Vec::new();
    for (prefix, run) in latest {
        let Some(warnings) = run.get("family_junk_warnings").and_then(Value::as_array) else {
            continue;
        };
        for warning in warnings {
            let mut copy = warning.clone();
            if let Some(obj) = copy.as_object_mut() {
                if !prefix.is_empty() && !obj.contains_key("prefix") {
                    obj.insert("prefix".into(), json!(prefix));
                }
                if let Some(id) = run.get("run_id").filter(|_| !obj.contains_key("run_id")) {
                    obj.insert("run_id".into(), id.clone());
                }
            }
            out.push(copy);
        }
    }
    out.sort_by(|left, right| {
        let key = |value: &Value, field: &str| {
            value
                .get(field)
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string()
        };
        key(left, "prefix")
            .cmp(&key(right, "prefix"))
            .then(key(left, "family").cmp(&key(right, "family")))
    });
    out
}

fn run_field<'a>(value: &'a Value, field: &str) -> &'a str {
    value.get(field).and_then(Value::as_str).unwrap_or("")
}

fn run_is_newer(candidate: &Value, current: &Value) -> bool {
    match run_field(candidate, "started").cmp(run_field(current, "started")) {
        std::cmp::Ordering::Greater => true,
        std::cmp::Ordering::Less => false,
        std::cmp::Ordering::Equal => run_field(candidate, "run_id") > run_field(current, "run_id"),
    }
}

/// Add `family_junk_warnings` to a rendered map. A map with nothing to warn
/// about is returned unchanged, so a clean catalog keeps the response it had.
pub(crate) fn attach_family_junk_warnings(rendered: &str, runs: &[Value]) -> String {
    let warnings = family_warnings_from_runs(runs);
    if warnings.is_empty() {
        return rendered.to_string();
    }
    let Ok(mut value) = serde_json::from_str::<Value>(rendered) else {
        return rendered.to_string();
    };
    let Some(obj) = value.as_object_mut() else {
        return rendered.to_string();
    };
    obj.insert("family_junk_warnings".into(), Value::Array(warnings));
    obj.insert("family_junk_warnings_note".into(), json!(FAMILY_JUNK_NOTE));
    value.to_string()
}

/// Run documents from the catalog. Failure is an empty list: the field map
/// is still returned. No server-side sort — `started` is not a date on every
/// catalog this binary still reads.
async fn fetch_run_sources(ctx: &Ctx) -> Vec<Value> {
    let body = json!({
        "size": 500,
        "query": {"term": {"doc_kind": "run"}},
        "_source": ["prefix", "run_id", "started", "family_junk_warnings"]
    });
    let url = format!("{}/{CATALOG_INDEX}/_search", ctx.base_url);
    let mut req = ctx.client.post(&url).json(&body);
    if let Some(auth) = &ctx.auth {
        req = req.header("Authorization", auth);
    }
    let Ok(resp) = req.send().await else {
        return Vec::new();
    };
    if !resp.status().is_success() {
        return Vec::new();
    }
    let Ok(text) = resp.text().await else {
        return Vec::new();
    };
    let Ok(value) = serde_json::from_str::<Value>(&text) else {
        return Vec::new();
    };
    value
        .pointer("/hits/hits")
        .and_then(Value::as_array)
        .map(|hits| {
            hits.iter()
                .filter_map(|hit| hit.get("_source").cloned())
                .collect()
        })
        .unwrap_or_default()
}

fn annotate_field_count(rendered: &str, mapping_read: bool) -> String {
    let Ok(mut value) = serde_json::from_str::<Value>(rendered) else {
        return rendered.to_string();
    };
    if let Some(obj) = value.as_object_mut() {
        obj.insert(
            "field_count_means".into(),
            json!(field_count_means(mapping_read)),
        );
    }
    value.to_string()
}

async fn fetch_mappings(ctx: &Ctx, indexes: &[String]) -> Option<Value> {
    if indexes.is_empty() {
        return Some(json!({}));
    }
    let path = indexes
        .iter()
        .map(|name| super::enc(name))
        .collect::<Vec<_>>()
        .join(",");
    let url = format!("{}/{path}/_mapping", ctx.base_url);
    let mut req = ctx.client.get(&url);
    if let Some(auth) = &ctx.auth {
        req = req.header("Authorization", auth);
    }
    let resp = req.send().await.ok()?;
    if !resp.status().is_success() {
        return None;
    }
    let text = resp.text().await.ok()?;
    serde_json::from_str(&text).ok()
}

fn index_names(resp: &Value) -> Vec<String> {
    resp.pointer("/hits/hits")
        .and_then(Value::as_array)
        .map(|hits| {
            let mut names: Vec<String> = hits
                .iter()
                .filter_map(|h| {
                    h.pointer("/_source/index_name")
                        .and_then(Value::as_str)
                        .map(str::to_string)
                })
                .collect();
            names.sort();
            names.dedup();
            names
        })
        .unwrap_or_default()
}

/// `xerj_map` dispatch: read the catalog, union each index's live mapping so
/// `ax_*` locators and any other mapped-but-unprofiled field are listed, then
/// render. A missing catalog (the node never ran autoindex) is an error with
/// the fix named — the response an agent can act on — while an empty-but-present
/// catalog is a normal empty result, not an error.
pub(crate) async fn run(ctx: &Ctx, args: &Value) -> Value {
    let parsed = match parse_args(args) {
        Ok(a) => a,
        Err(msg) => return tool_text(format!("xerj_map: {msg}"), true),
    };
    let body = catalog_body(&parsed);
    let url = format!("{}/{CATALOG_INDEX}/_search", ctx.base_url);
    let mut req = ctx.client.post(&url).json(&body);
    if let Some(auth) = &ctx.auth {
        req = req.header("Authorization", auth);
    }
    match req.send().await {
        Ok(resp) => {
            let status = resp.status();
            let text = resp.text().await.unwrap_or_default();
            if status.is_success() {
                match serde_json::from_str::<Value>(&text) {
                    Ok(mut v) => {
                        let mapping = fetch_mappings(ctx, &index_names(&v)).await;
                        let mapping_read = mapping.is_some();
                        merge_mapped_fields(&mut v, mapping.as_ref());
                        let rendered =
                            annotate_field_count(&render_response(&v, &parsed), mapping_read);
                        // #2370: the field map lists datasets that were indexed.
                        // A family that was entirely junked never becomes one,
                        // so the map used to look complete. The run document
                        // carries `family_junk_warnings` when that happened.
                        // A failed read leaves the map as it was — the field
                        // list is still the answer to "what can I query".
                        let runs = fetch_run_sources(ctx).await;
                        tool_text(attach_family_junk_warnings(&rendered, &runs), false)
                    }
                    Err(e) => tool_text(
                        format!("xerj_map: catalog reply was not JSON ({e}): {text}"),
                        true,
                    ),
                }
            } else if status.as_u16() == 404 {
                tool_text(
                    format!(
                        "xerj_map: no autoindex catalog on this node (index \
                         `{CATALOG_INDEX}` not found, HTTP 404) — run `xerj autoindex \
                         <folder>` first. Engine said: {text}"
                    ),
                    true,
                )
            } else if let Some(proxied) =
                crate::proxy_status_failure(&ctx.base_url, &url, status.as_u16(), &text)
            {
                tool_text(proxied, true)
            } else {
                tool_text(
                    format!("XERJ returned HTTP {status} from {CATALOG_INDEX}: {text}"),
                    true,
                )
            }
        }
        Err(e) => tool_text(crate::transport_failure_text(&ctx.base_url, &url, &e), true),
    }
}

