#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn local_def_returns_ranked_unique_declarations_in_the_requested_scope() {
    let tmp = tempfile::tempdir().unwrap();
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = tmp.path().join("data").to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.auth.enabled = false;
    let metrics = xerj_common::metrics::Metrics::new().unwrap();
    let engine = xerj_engine::Engine::new(config.clone()).unwrap();
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    let app = xerj_api::router::build_es_compat_router(state);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("http://{}", listener.local_addr().unwrap());
    let server = tokio::spawn(async move {
        axum::serve(listener, app.into_make_service())
            .await
            .unwrap();
    });
    let client = reqwest::Client::new();
    for index in ["project-code", "ax-code"] {
        let response = client
            .put(format!("{url}/{index}"))
            .json(&json!({
                "settings":{"index":{"strict_unknown_fields":true}},
                "mappings":{"properties":{
                    "name":{"type":"keyword"}, "kind":{"type":"keyword"},
                    "language":{"type":"keyword"}, "code":{"type":"text"},
                    "ax_path":{"type":"keyword"}, "line":{"type":"integer"}
                }}
            }))
            .send()
            .await
            .unwrap();
        assert!(
            response.status().is_success(),
            "{}",
            response.text().await.unwrap()
        );
        for (id, path, kind, language, code) in [
            ("test", "tests/cache.rs", "struct", "rust", "struct Cache"),
            (
                "alias",
                "src/alias.rs",
                "type",
                "rust",
                "type Cache = Store;",
            ),
            ("real", "src/cache.rs", "struct", "rust", "pub struct Cache"),
            (
                "duplicate",
                "src/cache.rs",
                "struct",
                "rust",
                "pub struct Cache",
            ),
            ("python", "src/cache.py", "class", "python", "class Cache:"),
        ] {
            let response = client
                .put(format!("{url}/{index}/_doc/{id}?refresh=true"))
                .json(&json!({"name":"Cache","kind":kind,"language":language,
                    "code":code,"ax_path":path,"line":7}))
                .send()
                .await
                .unwrap();
            assert!(
                response.status().is_success(),
                "{}",
                response.text().await.unwrap()
            );
        }
    }
    for (scope, index) in [
        (json!({"prefix":"project"}), "project-code"),
        (json!({"index":"project-code"}), "project-code"),
        (json!({}), "ax-code"),
    ] {
        let mut args = scope;
        args["symbol"] = json!("Cache");
        let result = lookup(&url, args.clone()).await;
        let hits = result["hits"]["hits"].as_array().unwrap();
        assert_eq!(hits.len(), 4, "{result}");
        assert!(hits.iter().all(|h| h["_index"] == index), "{result}");
        assert_eq!(hits[0]["_source"]["ax_path"], "src/cache.rs");
        assert_eq!(hits[0]["_source"]["line"], 7);
        assert_eq!(hits[0]["_source"]["code"], "pub struct Cache");
        args["k"] = json!(1);
        assert_eq!(
            lookup(&url, args.clone()).await["hits"]["hits"],
            json!([hits[0]])
        );
        args["kind"] = json!("class");
        args["lang"] = json!("python");
        let filtered = lookup(&url, args.clone()).await;
        assert_eq!(
            filtered["hits"]["hits"][0]["_source"]["ax_path"],
            "src/cache.py"
        );
        args["symbol"] = json!("MissingIdentifier");
        assert_eq!(lookup(&url, args).await["hits"]["hits"], json!([]));
    }
    // Numeric homonyms in another dataset must not poison a wildcard lookup.
    let response = client
        .put(format!("{url}/project-metrics"))
        .json(&json!({
            "settings":{"index":{"strict_unknown_fields":true}},
            "mappings":{"properties":{
                "name":{"type":"long"},"kind":{"type":"integer"},
                "language":{"type":"long"},"body":{"type":"text"}
            }}
        }))
        .send()
        .await
        .unwrap();
    assert!(
        response.status().is_success(),
        "{}",
        response.text().await.unwrap()
    );
    let response = lookup(
        &url,
        json!({"symbol":"Cache", "prefix":"project",
        "kind":"struct", "lang":"rust"}),
    )
    .await;
    let hits = response["hits"]["hits"].as_array().unwrap();
    assert_eq!(
        hits.len(),
        4,
        "numeric kind/language filters are ignored: {response}"
    );
    assert_eq!(hits[0]["_source"]["ax_path"], "src/cache.rs");
    server.abort();
    let _ = server.await;
}

//! Loopback MCP calls ignore `ALL_PROXY` / `HTTP_PROXY` / `HTTPS_PROXY` (#2379).
//!
//! reqwest honours those variables for `127.0.0.1`. A socks or HTTP proxy then
//! answers 503 (or refuses the connection) while the node is healthy, and the
//! tool used to report that as `XERJ returned HTTP 503`. `curl --noproxy`
//! reached the same node.
//!
//! This is its own test binary because the proxy variables are process-global:
//! set inside the library tests they would redirect every other HTTP client.

use std::io::{Read, Write};
use std::net::TcpListener;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use serde_json::{json, Value};

const PROXY_VARS: &[&str] = &[
    "ALL_PROXY",
    "all_proxy",
    "HTTP_PROXY",
    "http_proxy",
    "HTTPS_PROXY",
    "https_proxy",
    "NO_PROXY",
    "no_proxy",
];

struct EnvGuard(Vec<(String, Option<std::ffi::OsString>)>);

impl EnvGuard {
    fn capture() -> Self {
        let saved = PROXY_VARS
            .iter()
            .map(|key| ((*key).to_string(), std::env::var_os(key)))
            .collect();
        Self(saved)
    }
}

impl Drop for EnvGuard {
    fn drop(&mut self) {
        for key in PROXY_VARS {
            std::env::remove_var(key);
        }
        for (key, value) in &self.0 {
            if let Some(value) = value {
                std::env::set_var(key, value);
            }
        }
    }
}

fn clear_proxy_env() {
    for key in PROXY_VARS {
        std::env::remove_var(key);
    }
}

fn set_proxy(value: &str) {
    clear_proxy_env();
    for key in [
        "ALL_PROXY",
        "all_proxy",
        "HTTP_PROXY",
        "http_proxy",
        "HTTPS_PROXY",
        "https_proxy",
    ] {
        std::env::set_var(key, value);
    }
}

/// A server on an ephemeral port that answers every request with `status`/`body`
/// and counts the requests it received. `bind` is `127.0.0.1:0` or `[::1]:0`.
/// `None` when that address family is not available.
fn serve(
    bind: &str,
    status: &'static str,
    body: &'static str,
    hits: Arc<AtomicUsize>,
) -> Option<u16> {
    let listener = TcpListener::bind(bind).ok()?;
    let port = listener.local_addr().ok()?.port();
    std::thread::spawn(move || {
        for conn in listener.incoming() {
            let Ok(mut conn) = conn else { continue };
            let hits = hits.clone();
            std::thread::spawn(move || {
                let mut buf = [0u8; 8192];
                if conn.read(&mut buf).unwrap_or(0) == 0 {
                    return;
                }
                hits.fetch_add(1, Ordering::SeqCst);
                let reply = format!(
                    "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                let _ = conn.write_all(reply.as_bytes());
            });
        }
    });
    Some(port)
}

fn closed_port() -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    port
}

fn search_call() -> Value {
    json!({
        "jsonrpc": "2.0",
        "id": 1,
        "method": "tools/call",
        "params": {
            "name": "xerj_search",
            "arguments": { "index": "docs", "query": { "match_all": {} } }
        }
    })
}

fn map_call() -> Value {
    json!({
        "jsonrpc": "2.0",
        "id": 2,
        "method": "tools/call",
        "params": { "name": "xerj_map", "arguments": {} }
    })
}

async fn tool(url: &str, msg: Value) -> (bool, String) {
    let resp = xerj_mcp::handle_message_for_test(url, None, msg)
        .await
        .expect("tools/call returns a response");
    let is_error = resp["result"]["isError"].as_bool().unwrap();
    let text = resp["result"]["content"][0]["text"]
        .as_str()
        .unwrap_or("")
        .to_string();
    (is_error, text)
}

#[tokio::test]
async fn loopback_ignores_an_unreachable_proxy_and_a_proxied_503_names_the_proxy() {
    let _guard = EnvGuard::capture();

    let node_hits = Arc::new(AtomicUsize::new(0));
    let node_body = r#"{"took":1,"hits":{"total":{"value":0,"relation":"eq"},"hits":[]}}"#;
    let node_port =
        serve("127.0.0.1:0", "200 OK", node_body, node_hits.clone()).expect("bind 127.0.0.1");
    let v6_port = serve("[::1]:0", "200 OK", node_body, node_hits.clone());

    // Phase 1: ALL_PROXY is an unreachable socks5 proxy, and the HTTP(S) proxy
    // variables point at a closed port. A loopback tool call still succeeds.
    let closed = closed_port();
    set_proxy(&format!("socks5://127.0.0.1:{closed}"));
    std::env::set_var("HTTP_PROXY", format!("http://127.0.0.1:{closed}"));
    std::env::set_var("http_proxy", format!("http://127.0.0.1:{closed}"));
    std::env::set_var("HTTPS_PROXY", format!("http://127.0.0.1:{closed}"));
    std::env::set_var("https_proxy", format!("http://127.0.0.1:{closed}"));

    let node = format!("http://127.0.0.1:{node_port}");
    let (err, text) = tool(&node, search_call()).await;
    assert!(!err, "loopback search went through the proxy: {text}");
    let (err, text) = tool(&node, map_call()).await;
    assert!(!err, "loopback map went through the proxy: {text}");
    assert!(
        node_hits.load(Ordering::SeqCst) >= 2,
        "the node itself must have answered"
    );
    if let Some(port) = v6_port {
        let (err, text) = tool(&format!("http://[::1]:{port}"), search_call()).await;
        assert!(!err, "::1 search went through the proxy: {text}");
    }

    // Phase 2: a live HTTP proxy returns 503. Loopback still skips it. A
    // non-loopback host is sent there, and the tool error names the proxy
    // instead of `XERJ returned HTTP 503`.
    let proxy_hits = Arc::new(AtomicUsize::new(0));
    let proxy_port = serve(
        "127.0.0.1:0",
        "503 Service Unavailable",
        r#"{"error":"bad gateway from the corporate proxy"}"#,
        proxy_hits.clone(),
    )
    .expect("bind proxy");
    let proxy_url = format!("http://127.0.0.1:{proxy_port}");
    set_proxy(&proxy_url);

    let before = node_hits.load(Ordering::SeqCst);
    let (err, text) = tool(&node, search_call()).await;
    assert!(!err, "loopback search used the live proxy: {text}");
    let (err, text) = tool(&node, map_call()).await;
    assert!(!err, "loopback map used the live proxy: {text}");
    assert!(node_hits.load(Ordering::SeqCst) > before);
    assert_eq!(
        proxy_hits.load(Ordering::SeqCst),
        0,
        "the proxy must not see a loopback node"
    );

    // 127.0.0.2 is this machine's loopback range, but it is not one of the
    // hosts `url_is_loopback` treats as the local node, so the proxy applies.
    let remote = "http://127.0.0.2:9";
    let (err, text) = tool(remote, search_call()).await;
    assert!(err, "{text}");
    assert!(
        text.contains(&proxy_url),
        "the 503 must name the proxy: {text}"
    );
    assert!(text.contains("HTTP 503"), "{text}");
    assert!(text.contains("went through proxy"), "{text}");
    assert!(
        !text.contains("XERJ returned HTTP"),
        "a proxy 503 is not the node's status: {text}"
    );
    let (err, text) = tool(remote, map_call()).await;
    assert!(err, "{text}");
    assert!(text.contains(&proxy_url), "{text}");
    assert!(text.contains("went through proxy"), "{text}");
    assert!(
        proxy_hits.load(Ordering::SeqCst) >= 2,
        "the non-loopback calls must have reached the proxy"
    );

    // Phase 3: NO_PROXY still excludes a non-loopback host. The closed port
    // refuses immediately, and the error is the node-down sentence, not the proxy.
    let proxy_before = proxy_hits.load(Ordering::SeqCst);
    std::env::set_var("NO_PROXY", "127.0.0.2");
    std::env::set_var("no_proxy", "127.0.0.2");
    let (err, text) = tool(remote, search_call()).await;
    assert!(err, "{text}");
    assert!(
        !text.contains("went through proxy"),
        "NO_PROXY must bypass the proxy: {text}"
    );
    assert!(
        text.contains("no XERJ node is listening") || text.contains("Connection refused"),
        "{text}"
    );
    assert_eq!(
        proxy_hits.load(Ordering::SeqCst),
        proxy_before,
        "NO_PROXY must not contact the proxy"
    );

    // Phase 4: a proxy that is not listening is named on the transport error,
    // rather than reported as the node being down.
    clear_proxy_env();
    let dead = closed_port();
    let dead_url = format!("http://127.0.0.1:{dead}");
    set_proxy(&dead_url);
    let (err, text) = tool(remote, search_call()).await;
    assert!(err, "{text}");
    assert!(
        text.contains(&dead_url),
        "a refused proxy connection must name the proxy: {text}"
    );
    assert!(text.contains("via proxy"), "{text}");
    assert!(
        !text.contains("no XERJ node is listening"),
        "the node was not the thing that refused: {text}"
    );
}

//! Drift guard: the published MCP tool schema vs the tools the server serves.
//!
//! `landing/docs/agents/schemas/mcp-tools.json` is what an agent reads to find
//! out what XERJ's MCP server can do. It was hand-written, and it drifted: it
//! advertised **six** tools while the binary served **ten**, missing every
//! `xerj_brain_*` tool. Nothing compared the two, so nothing failed — the file
//! simply told agents a smaller, wrong story for as long as it existed.
//!
//! The file is now generated from a live `tools/list` response
//! (`scripts/mcp-schema-check.sh --write`), and this test pins it to
//! [`xerj_mcp::tool_specs`], the function that response is built from. Adding,
//! renaming, or re-describing a tool fails here until the published schema is
//! regenerated. That is the point: the failure is cheap, and the silent
//! divergence it prevents is not.
//!
//! Scope note: this test covers the library that both binaries serve from. The
//! end-to-end path — build the real binary, speak JSON-RPC over stdio, diff the
//! wire response against the file — is `scripts/mcp-schema-check.sh`, wired
//! into CI next to the MCP smoke test.

use std::path::{Path, PathBuf};

use serde_json::Value;

/// Repository root, derived from this crate's manifest directory
/// (`<repo>/engine/crates/xerj-mcp`).
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .expect("crate manifest dir must be <repo>/engine/crates/xerj-mcp")
        .to_path_buf()
}

fn published_path() -> PathBuf {
    repo_root().join("landing/docs/agents/schemas/mcp-tools.json")
}

/// Load the published schema. A missing or unparseable file is a hard failure,
/// never a skip: a guard that quietly checks nothing is the exact failure mode
/// this file exists to prevent.
fn published() -> Value {
    let path = published_path();
    let raw = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read the published MCP schema at {}: {e}\n\
             It is the agent-facing contract for this crate's tools. If it moved, \
             update this test and scripts/mcp-schema-check.sh together.",
            path.display()
        )
    });
    serde_json::from_str(&raw)
        .unwrap_or_else(|e| panic!("{} is not valid JSON: {e}", path.display()))
}

fn names(tools: &Value) -> Vec<String> {
    tools
        .as_array()
        .expect("`tools` must be an array")
        .iter()
        .map(|t| {
            t["name"]
                .as_str()
                .expect("every tool needs a string `name`")
                .to_string()
        })
        .collect()
}

/// The headline check: same tools, same order.
#[test]
fn published_tool_names_match_the_server() {
    // The published file is the with-key tool list. A process with
    // `XERJ_HUB_PUBKEY=none` omits the three hub tools from `tool_specs()`;
    // that omission is covered in the library tests, and must not look like
    // the committed schema drifted.
    let served = names(&xerj_mcp::tool_specs_with(true));
    let doc = names(&published()["tools"]);
    assert_eq!(
        doc, served,
        "\nlanding/docs/agents/schemas/mcp-tools.json advertises a different tool set \
         than the MCP server serves.\n  published: {doc:?}\n  served:    {served:?}\n\
         Regenerate it from the real binary:\n    \
         scripts/mcp-schema-check.sh --write\n"
    );
}

/// The full check: every field of every tool, byte-for-byte after JSON
/// normalisation. Descriptions are what an agent reads to decide whether to
/// call a tool at all, so a stale description is a real defect, not cosmetics —
/// the brain tools' honesty sentences live there.
#[test]
fn published_schemas_match_the_server_exactly() {
    let served = xerj_mcp::tool_specs_with(true);
    let doc = published()["tools"].clone();

    let served_by_name: std::collections::BTreeMap<String, &Value> = served
        .as_array()
        .unwrap()
        .iter()
        .map(|t| (t["name"].as_str().unwrap().to_string(), t))
        .collect();

    for tool in doc.as_array().expect("`tools` must be an array") {
        let name = tool["name"].as_str().expect("tool needs a name");
        let Some(want) = served_by_name.get(name) else {
            continue; // name-set mismatch is reported by the test above
        };
        assert_eq!(
            &tool, want,
            "\npublished schema for `{name}` differs from what the server serves.\n\
             Regenerate: scripts/mcp-schema-check.sh --write\n"
        );
    }
}

/// The published file must keep the envelope agents already fetch: a top-level
/// object with a `tools` array. Reshaping it silently breaks every consumer.
#[test]
fn published_envelope_is_preserved() {
    let doc = published();
    assert!(doc.is_object(), "top level must be a JSON object");
    assert!(
        doc.get("tools").map(Value::is_array).unwrap_or(false),
        "top level must carry a `tools` array"
    );
}

/// The `xerj mcp` subcommand is the only way most users can reach this server —
/// they installed one binary. If the dispatch arm is deleted, the crate still
/// builds and every other test still passes, so pin the wiring itself.
#[test]
fn main_binary_dispatches_the_mcp_subcommand() {
    let main_rs = repo_root().join("engine/crates/xerj-server/src/main.rs");
    let src = std::fs::read_to_string(&main_rs)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", main_rs.display()));
    assert!(
        src.contains("xerj_mcp::run"),
        "{} no longer calls xerj_mcp::run — `xerj mcp` would be unreachable, and \
         with it the only MCP server an installed user can start",
        main_rs.display()
    );
    assert!(
        src.contains("Some(\"mcp\")"),
        "{} no longer dispatches on argv[1] == \"mcp\"",
        main_rs.display()
    );
}

//! A plain-string `xerj_search` for an exact error message ranks the file
//! that contains it, end to end against a real in-process node.
//!
//! The corpus is the autoindex shape in miniature: per-file docs with a
//! `body` and a `defs` symbol list, plus a per-symbol doc. One short file's
//! `defs` (`Memory`, `MemoryCandidate`) shares two words of the query; one
//! long file holds the whole message in order. Without an exact-phrase leg
//! the `most_fields` sum puts the short `defs` list first, because a 400-line
//! body scores low on BM25 length normalisation however many query terms it
//! holds.

use serde_json::{json, Value};

const PHRASE: &str = "Memory candidate capacity exceeded";

fn long_module() -> String {
    let mut out = String::from("class BackendError(Exception):\n    pass\n\n");
    for i in 0..40 {
        if i == 20 {
            out.push_str(&format!(
                "def load_candidates(rows):\n    picked = []\n    for row in rows:\n        \
                 picked.append(row)\n        if len(picked) > 1000:\n            \
                 raise BackendError(\"{PHRASE}\")\n    return picked\n\n"
            ));
        }
        out.push_str(&format!(
            "def helper_{i}(rows, limit):\n    \"\"\"Normalise batch {i} of loaded rows.\"\"\"\n    \
             out = []\n    for row in rows:\n        if not isinstance(row, dict):\n            \
             raise ValueError(\"row {i} is not an object\")\n        out.append(row)\n    \
             return out[:limit]\n\n"
        ));
    }
    out
}

async fn seed(client: &reqwest::Client, url: &str) {
    let index = format!("{url}/ax-docs");
    let r = client
        .put(&index)
        .json(&json!({ "mappings": { "properties": {
            "ax_path": {"type": "keyword"}, "title": {"type": "keyword"},
            "name": {"type": "keyword"}, "code": {"type": "keyword"},
            "kind": {"type": "keyword"}, "line": {"type": "long"},
            "defs": {"type": "text"}, "body": {"type": "text"}
        }}}))
        .send()
        .await
        .unwrap();
    assert!(r.status().is_success(), "create {index}");
    let mut defs = vec!["class BackendError".to_string()];
    defs.extend((0..40).map(|i| format!("function helper_{i}")));
    defs.insert(21, "function load_candidates".into());
    let docs = [
        json!({"ax_path": "memory_view.tsx", "title": "memory_view.tsx",
               "defs": "function Memory\nconst MemoryCandidate\nfunction MemoryCandidate",
               "body": "export function Memory({ items }) {\n  const memory = items.filter(Boolean);\n  \
                        // Memory panel: each memory candidate the user saved.\n}\n\
                        export const MemoryCandidate = (props) => props.text;\n"}),
        json!({"ax_path": "memory_view.tsx", "title": "Memory", "name": "Memory",
               "kind": "function", "line": 1, "code": "export function Memory({ items })"}),
        json!({"ax_path": "bridge.py", "title": "bridge.py", "defs": defs.join("\n"),
               "body": long_module()}),
        json!({"ax_path": "bridge.py", "title": "load_candidates", "name": "load_candidates",
               "kind": "function", "line": 23, "code": "def load_candidates(rows):"}),
        json!({"ax_path": "notes.md", "title": "notes.md",
               "body": "# Memory\n\nMemory records are saved per project. A memory candidate \
                        is reviewed before it is shared.\n"}),
    ];
    let mut bulk = String::new();
    for d in docs {
        bulk.push_str(&format!("{{\"index\":{{}}}}\n{d}\n"));
    }
    let r = client
        .post(format!("{index}/_bulk?refresh=true"))
        .header("content-type", "application/x-ndjson")
        .body(bulk)
        .send()
        .await
        .unwrap();
    assert!(r.status().is_success(), "bulk {index}");
    // Autoindex leaves its corpus flushed into segments; rank against that,
    // not the memtable.
    let r = client.post(format!("{index}/_flush")).send().await.unwrap();
    assert!(r.status().is_success(), "flush {index}");
}

async fn ranked_paths(url: &str, query: &str) -> Vec<String> {
    let msg = json!({"jsonrpc": "2.0", "id": 1, "method": "tools/call",
                     "params": {"name": "xerj_search", "arguments": {"query": query}}});
    let resp = xerj_mcp::handle_message_for_test(url, None, msg)
        .await
        .expect("a request gets a response");
    let text = resp["result"]["content"][0]["text"]
        .as_str()
        .unwrap_or_else(|| panic!("no text content: {resp}"));
    let body: Value =
        serde_json::from_str(text).unwrap_or_else(|e| panic!("{e}: not JSON: {text}"));
    body["hits"]["hits"]
        .as_array()
        .unwrap_or_else(|| panic!("no hits array: {body}"))
        .iter()
        .filter_map(|h| h.pointer("/_source/ax_path").and_then(Value::as_str))
        .map(str::to_string)
        .collect()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn an_exact_error_message_ranks_the_file_that_contains_it() {
    let tmp = tempfile::tempdir().unwrap();
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = tmp.path().join("data").to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.auth.enabled = false;
    let metrics = xerj_common::metrics::Metrics::new().unwrap();
    let engine = xerj_engine::Engine::new(config.clone()).unwrap();
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    let app = xerj_api::router::build_es_compat_router(state);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("http://{}", listener.local_addr().unwrap());
    tokio::spawn(async move { axum::serve(listener, app.into_make_service()).await });
    seed(&reqwest::Client::new(), &url).await;

    let paths = ranked_paths(&url, PHRASE).await;
    assert_eq!(
        paths.first().map(String::as_str),
        Some("bridge.py"),
        "the file holding \"{PHRASE}\" must rank first: {paths:?}"
    );

    // The definition-first shape is untouched: an identifier still lands on
    // its symbol doc through the `name` term leg.
    let paths = ranked_paths(&url, "load_candidates").await;
    assert_eq!(
        paths.first().map(String::as_str),
        Some("bridge.py"),
        "{paths:?}"
    );
    let paths = ranked_paths(&url, "Memory").await;
    assert_eq!(
        paths.first().map(String::as_str),
        Some("memory_view.tsx"),
        "{paths:?}"
    );
}

//! A custom autoindex prefix must not fall back to the default corpus.
use serde_json::{json, Value};

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn prefix_search_returns_only_its_corpus_for_plain_and_dsl_queries() {
    let tmp = tempfile::tempdir().unwrap();
    let mut config = xerj_common::config::Config::default();
    config.server.data_dir = tmp.path().join("data").to_string_lossy().into_owned();
    config.storage.wal_sync = xerj_common::config::WalSync::Async;
    config.auth.enabled = false;
    let metrics = xerj_common::metrics::Metrics::new().unwrap();
    let engine = xerj_engine::Engine::new(config.clone()).unwrap();
    let state = xerj_api::state::AppState::new(config, engine, metrics);
    let app = xerj_api::router::build_es_compat_router(state);
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("http://{}", listener.local_addr().unwrap());
    let server = tokio::spawn(async move {
        axum::serve(listener, app.into_make_service())
            .await
            .unwrap();
    });
    let client = reqwest::Client::new();
    for index in ["project-docs", "ax-other", "my-proj-docs"] {
        let response = client
            .put(format!("{url}/{index}"))
            .json(
                &json!({"settings": {"index": {"strict_unknown_fields": true}},
                "mappings": {"properties": {"text": {"type": "text"}}}}),
            )
            .send()
            .await
            .unwrap();
        assert!(
            response.status().is_success(),
            "{}",
            response.text().await.unwrap()
        );
        let response = client
            .put(format!("{url}/{index}/_doc/1?refresh=true"))
            .json(&json!({"text": "retry policy"}))
            .send()
            .await
            .unwrap();
        assert!(
            response.status().is_success(),
            "{}",
            response.text().await.unwrap()
        );
    }
    for query in [json!("retry policy"), json!({"match": {"text": "retry"}})] {
        for (scope, expected_index) in [
            (json!({"prefix": "project"}), "project-docs"),
            (json!({"prefix": "My_Proj"}), "my-proj-docs"),
            (json!({"prefix": "project-*"}), "project-docs"),
            (json!({}), "ax-other"),
            (json!({"index": "project-docs"}), "project-docs"),
        ] {
            let mut arguments = scope;
            arguments["query"] = query.clone();
            let response = xerj_mcp::handle_message_for_test(
                &url,
                None,
                json!({
                    "jsonrpc": "2.0", "id": 1, "method": "tools/call",
                    "params": {"name": "xerj_search", "arguments": arguments}
                }),
            )
            .await
            .unwrap();
            assert_eq!(response["result"]["isError"], false, "{response}");
            let body: Value =
                serde_json::from_str(response["result"]["content"][0]["text"].as_str().unwrap())
                    .unwrap();
            assert_eq!(body["hits"]["total"]["value"], 1, "{body}");
            assert_eq!(body["hits"]["hits"][0]["_index"], expected_index, "{body}");
        }
    }
    server.abort();
    let _ = server.await;
}

//! Budgeting must not collapse independent records that share a relative path.
use std::sync::{Arc, Mutex};

use axum::{routing::get, Json, Router};
use serde_json::{json, Value};

#[tokio::test]
async fn json_budget_identity_survives_http_dispatch_and_source_projection() {
    for different_indices in [false, true] {
        let hits: Vec<Value> = (0..2)
            .map(|i| {
                json!({
                    "_index": if different_indices { format!("repo-{i}-code") } else { "ax-data".into() },
                    "_id": i.to_string(),
                    "_source": {
                        "ax_path": "shared.txt", "ax_file": "content-hash",
                        "ax_locator": if different_indices { "file".into() } else { format!("b{}", i * 100) }
                    },
                    "fields": {"_passage": [{"field":"body", "ordinal":0, "text":"independent evidence"}]}
                })
            })
            .collect();
        let requests = Arc::new(Mutex::new(Vec::<Value>::new()));
        let seen = requests.clone();
        // `xerj_search` also POSTs `/autoindex-catalog/_search` after the
        // query (#2345). That probe is not the engine request the budget
        // must leave alone, and recording it in the same list pairs a search
        // body with a catalog body.
        let catalog = Arc::new(Mutex::new(Vec::<Value>::new()));
        let seen_catalog = catalog.clone();
        let app = Router::new()
            .route(
                "/:index/_mapping",
                get(|| async {
                    Json(json!({"ax-data":{"mappings":{"properties":{"body":{"type":"text"}}}}}))
                }),
            )
            .route(
                "/:index/_search",
                axum::routing::post(
                    move |axum::extract::Path(index): axum::extract::Path<String>,
                          Json(body): Json<Value>| {
                        let mut hits = hits.clone();
                        let catalog_probe = index == "autoindex-catalog";
                        if catalog_probe {
                            seen_catalog.lock().unwrap().push(body.clone());
                        } else {
                            seen.lock().unwrap().push(body.clone());
                        }
                        async move {
                            if catalog_probe {
                                return Json(json!({"hits":{"hits":[]}}));
                            }
                            // Model the engine's projection: the plain-query default
                            // must actually request identity fields, not just consume
                            // fixtures that always return them.
                            if let Some(fields) = body.get("_source").and_then(Value::as_array) {
                                for hit in &mut hits {
                                    hit["_source"].as_object_mut().unwrap().retain(|key, _| {
                                        fields.iter().any(|v| v.as_str() == Some(key.as_str()))
                                    });
                                }
                            }
                            Json(json!({"hits":{"total":{"value":2,"relation":"eq"},"hits":hits}}))
                        }
                    },
                ),
            );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let url = format!("http://{}", listener.local_addr().unwrap());
        let server = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
        for (name, arguments) in [
            ("xerj_search", json!({"index":"ax-*","query":"independent"})),
            (
                "xerj_search",
                json!({"index":"ax-*","query":{"match_all":{}}}),
            ),
            (
                "xerj_semantic_search",
                json!({"index":"ax-*","field":"body","query":"independent"}),
            ),
            (
                "xerj_vector_search",
                json!({"index":"ax-*","field":"embedding","query_vector":[0.1]}),
            ),
            (
                "xerj_hybrid_search",
                json!({"index":"ax-*","queries":[{"query":{"match_all":{}}}]}),
            ),
        ] {
            let mut baseline = None;
            for budget in [None, Some(10_000)] {
                let mut args = arguments.clone();
                if let Some(budget) = budget {
                    args["max_tokens"] = json!(budget);
                }
                let response = xerj_mcp::handle_message_for_test(
                    &url,
                    None,
                    json!({
                        "jsonrpc":"2.0", "id":1, "method":"tools/call",
                        "params":{"name":name,"arguments":args}
                    }),
                )
                .await
                .unwrap();
                assert_eq!(response["result"]["isError"], false, "{response}");
                let text = response["result"]["content"][0]["text"].as_str().unwrap();
                let body: Value = serde_json::from_str(text).unwrap();
                assert_eq!(
                    body["hits"]["hits"].as_array().unwrap().len(),
                    2,
                    "{name}, different_indices={different_indices}, budget={budget:?}: {body}"
                );
                if let Some(baseline) = &baseline {
                    assert_eq!(
                        text, baseline,
                        "nonbinding budget preserves the exact response"
                    );
                } else {
                    baseline = Some(text.to_string());
                }
            }
        }
        {
            let requests = requests.lock().unwrap();
            assert!(
                requests.len() >= 2 && requests.len().is_multiple_of(2),
                "each call is made with and without a budget: {}",
                requests.len()
            );
            for pair in requests.chunks_exact(2) {
                assert_eq!(
                    pair[0], pair[1],
                    "the budget must not change the engine request"
                );
            }
        }
        {
            // Two `xerj_search` calls, each with and without a budget.
            let catalog = catalog.lock().unwrap();
            assert_eq!(catalog.len(), 4, "{catalog:?}");
            for body in catalog.iter() {
                assert_eq!(body["query"]["bool"]["must"][0]["term"]["doc_kind"], "run");
                assert_eq!(
                    body["query"]["bool"]["must"][1]["bool"]["should"][0]["term"]["prefix"],
                    "ax"
                );
            }
        }
        server.abort();
        let _ = server.await;
    }
}

//! Query AST — the central data type for xerj query processing.
//!
//! The entire ES query DSL maps to a single `QueryNode` enum.  This is the
//! polar opposite of Elasticsearch's ~60 Java `Query` classes, each with their
//! own visitor / rewriter interface.  A flat enum means:
//!
//! - Pattern matching is exhaustive and compiler-checked.
//! - Rewriters are plain recursive functions — no visitor boilerplate.
//! - Adding a new query type is a single enum variant (the compiler tells you
//!   what to update elsewhere).
//!
//! ## Variant groups
//!
//! | Group | Variants |
//! |---|---|
//! | Structural | `MatchAll`, `MatchNone`, `Bool`, `Constant`, `Boosted` |
//! | Term-level | `Term`, `Terms`, `Range`, `Prefix`, `Wildcard`, `Exists`, `Ids` |
//! | Full-text | `Match`, `MatchPhrase`, `MultiMatch`, `QueryString` |
//! | AI-native | `SemanticSearch`, `Knn`, `Hybrid` |

use serde::{Deserialize, Serialize};

// ─────────────────────────────────────────────────────────────────────────────
// Supporting enums
// ─────────────────────────────────────────────────────────────────────────────

/// Boolean operator used in `Match` queries when multiple tokens are produced.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "UPPERCASE")]
pub enum BoolOperator {
    /// Any token must match (default, same as ES).
    #[default]
    Or,
    /// All tokens must match.
    And,
    /// The request did not name an operator. Execution treats this as [`Or`]
    /// unless the index sets `index.query.default_match_operator` to `and`
    /// (#1504, log datasets). Not a wire value: the parser produces it only
    /// when the `operator` key is absent, and [`crate::apply_default_match_operator`]
    /// resolves it before a log index runs the query. An explicit `"or"` stays
    /// [`Or`], so a caller can still ask for the ES default on a log index.
    ///
    /// Serde's missing-field default stays [`Or`]. A deserialized AST that
    /// never went through the parser must not grow this variant.
    Omitted,
}

/// Determines how scores are combined for `MultiMatch` queries.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum MultiMatchType {
    /// Takes the best score across all fields (default).
    #[default]
    BestFields,
    /// Sum of scores across all matching fields.
    MostFields,
    /// Treats all fields as if they were concatenated into one.
    CrossFields,
    /// Exact phrase match.
    Phrase,
    /// Prefix on the last token; phrase on the rest.
    PhrasePrefix,
}

/// Fusion strategy for `Hybrid` queries combining multiple sub-queries.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "type")]
pub enum FusionStrategy {
    /// Reciprocal Rank Fusion — robust, parameter-free combination.
    Rrf {
        /// Smoothing constant (default 60, same as ES / OpenSearch).
        k: u32,
    },
    /// Weighted linear combination of normalised scores.
    Linear,
    /// Learned combiner (weights stored in the index metadata).
    Learned,
}

impl Default for FusionStrategy {
    fn default() -> Self {
        Self::Rrf { k: 60 }
    }
}

/// Controls how many edit operations are allowed in a fuzzy query.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
#[derive(Default)]
pub enum Fuzziness {
    /// AUTO fuzziness: 0 edits for 1-2 chars, 1 edit for 3-5 chars, 2 edits for 6+ chars.
    #[default]
    Auto,
    /// Fixed maximum number of edit operations.
    Fixed(u32),
}

/// `minimum_should_match` — an absolute count, a percentage, or (for
/// `terms_set`) a per-document count sourced from a field or a script.
///
/// Not `Copy`/`Eq` because the `Script` variant carries an owned source
/// string and a free-form params object (`serde_json::Value` is not `Eq`).
// NOTE: `Serialize` is HAND-WRITTEN below (not derived). The query cache hashes
// the serialized request (index.rs `body_hash`), and an untagged derive would
// serialize `Negative(2)`/`Percentage(2)` as the bare number `2` — identical to
// `Fixed(2)` — conflating semantically different specs into one cache entry
// (#860). The manual impl gives every spec a distinct wire form.
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(untagged)]
pub enum MinShouldMatch {
    /// Exact number of `should` clauses that must match.
    Fixed(u32),
    /// Percentage of `should` clauses that must match. Values may exceed 100:
    /// `>100` requires more matches than there are clauses, so the clause set
    /// is unsatisfiable (the parser applies no upper cap).
    Percentage(u32),
    /// #846: negative integer `-N` — `required = should_count - N` (floored at
    /// 0). Stores the absolute value `N`. e.g. `-1` requires all-but-one.
    Negative(u32),
    /// #846: negative percentage `-P%` — `required = should_count -
    /// floor(should_count * P/100)`. Stores `P`. Distinct from `Percentage`
    /// because the two round differently (ES treats "at most P% may be
    /// missing", not "P% must match").
    NegativePercentage(u32),
    /// #846: combination spec `pivot<spec [pivot<spec ...]` — the spec of the
    /// highest pivot strictly below `should_count` applies; if `should_count`
    /// is `<=` every pivot, all clauses are required.
    Combination(Vec<CombCond>),
    /// `terms_set.minimum_should_match_field`: the required count is read
    /// per-document from this numeric field.
    Field(String),
    /// `terms_set.minimum_should_match_script`: the required count is the
    /// result of a Painless script (with `params.num_terms` injected).
    Script {
        source: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        params: Option<serde_json::Value>,
    },
}

/// One `pivot<spec` condition of a [`MinShouldMatch::Combination`] spec.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CombCond {
    /// If `should_count > pivot`, this condition's `spec` is a candidate.
    pub pivot: u32,
    /// The spec to apply (a `Fixed`, `Percentage`, `Negative`, or
    /// `NegativePercentage` — never nested `Combination`/`Field`/`Script`).
    pub spec: Box<MinShouldMatch>,
}

impl MinShouldMatch {
    /// Resolve the concrete required `should`-clause count against the number of
    /// `should` clauses (`should_count`), applying ES `minimum_should_match`
    /// semantics. Returns `None` for the per-document `Field`/`Script` variants,
    /// which the caller must resolve against each document.
    pub fn required(&self, should_count: usize) -> Option<usize> {
        let n = should_count;
        match self {
            MinShouldMatch::Fixed(k) => Some(*k as usize),
            // floor(n * pct/100), min 1 — matches the legacy resolver.
            MinShouldMatch::Percentage(pct) => {
                Some(((n as f32) * (*pct as f32 / 100.0)).floor().max(1.0) as usize)
            }
            // required = n - k, floored at 0.
            MinShouldMatch::Negative(k) => Some(n.saturating_sub(*k as usize)),
            // required = n - floor(n * pct/100).
            MinShouldMatch::NegativePercentage(pct) => {
                let missing = ((n as f32) * (*pct as f32 / 100.0)).floor() as usize;
                Some(n.saturating_sub(missing))
            }
            // The applicable condition is the one with the HIGHEST pivot that is
            // still strictly below `n`; if `n <= every pivot`, all are required.
            MinShouldMatch::Combination(conds) => {
                let applicable = conds
                    .iter()
                    .filter(|c| (c.pivot as usize) < n)
                    .max_by_key(|c| c.pivot)
                    .map(|c| c.spec.as_ref());
                match applicable {
                    Some(spec) => spec.required(n),
                    None => Some(n),
                }
            }
            MinShouldMatch::Field(_) | MinShouldMatch::Script { .. } => None,
        }
    }

    /// The canonical ES string spelling of a SCALAR spec (`Fixed`/`Percentage`/
    /// `Negative`/`NegativePercentage`). Used inside `Combination` and by the
    /// custom `Serialize` so distinct specs never share a wire form. `None` for
    /// the non-scalar `Combination`/`Field`/`Script`.
    fn spec_token(&self) -> Option<String> {
        match self {
            MinShouldMatch::Fixed(n) => Some(n.to_string()),
            MinShouldMatch::Percentage(p) => Some(format!("{p}%")),
            MinShouldMatch::Negative(n) => Some(format!("-{n}")),
            MinShouldMatch::NegativePercentage(p) => Some(format!("-{p}%")),
            _ => None,
        }
    }
}

impl Serialize for MinShouldMatch {
    // Distinct wire form per spec so the request hash (query cache) never
    // conflates two specs (#860). Only feeds the opaque cache hash — no client
    // response echoes this — so the exact spelling is free to choose.
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        match self {
            // A plain count stays a JSON number.
            MinShouldMatch::Fixed(n) => serializer.serialize_u32(*n),
            // Percentage / negative / negative-% serialize as their distinct ES
            // string spelling ("50%", "-1", "-25%") — NOT bare numbers.
            MinShouldMatch::Percentage(_)
            | MinShouldMatch::Negative(_)
            | MinShouldMatch::NegativePercentage(_) => {
                serializer.serialize_str(&self.spec_token().expect("scalar spec has a token"))
            }
            // Combination as its "pivot<spec ..." spelling.
            MinShouldMatch::Combination(conds) => {
                let s = conds
                    .iter()
                    .map(|c| format!("{}<{}", c.pivot, c.spec.spec_token().unwrap_or_default()))
                    .collect::<Vec<_>>()
                    .join(" ");
                serializer.serialize_str(&s)
            }
            MinShouldMatch::Field(f) => serializer.serialize_str(f),
            MinShouldMatch::Script { source, params } => {
                use serde::ser::SerializeMap;
                let mut m = serializer.serialize_map(None)?;
                m.serialize_entry("source", source)?;
                if let Some(p) = params {
                    m.serialize_entry("params", p)?;
                }
                m.end()
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// QueryNode — the core type
// ─────────────────────────────────────────────────────────────────────────────

// ─────────────────────────────────────────────────────────────────────────────
// FunctionScore supporting types
// ─────────────────────────────────────────────────────────────────────────────

/// How multiple function scores are combined into one function score.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum ScoreMode {
    #[default]
    Multiply,
    Sum,
    Avg,
    First,
    Max,
    Min,
}

/// How the combined function score is merged with the query score.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum BoostMode {
    #[default]
    Multiply,
    Replace,
    Sum,
    Avg,
    Max,
    Min,
}

/// Math modifier applied to a field value before multiplying by `factor`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum Modifier {
    #[default]
    None,
    Log,
    Log1p,
    Log2p,
    Ln,
    Ln1p,
    Ln2p,
    Square,
    Sqrt,
    Reciprocal,
}

/// Field-value-factor function: score = modifier(field_value) * factor.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FieldValueFactor {
    pub field: String,
    #[serde(default = "default_factor")]
    pub factor: f32,
    #[serde(default)]
    pub modifier: Modifier,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub missing: Option<f64>,
}

fn default_factor() -> f32 {
    1.0
}

/// Random score function — deterministic hash of (doc_id, seed).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct RandomScore {
    #[serde(skip_serializing_if = "Option::is_none")]
    pub seed: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub field: Option<String>,
}

/// A single function inside a `function_score` query.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct ScoreFunction {
    /// Optional filter — function only applies to matching documents.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub filter: Option<QueryNode>,
    /// Constant weight multiplier.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub weight: Option<f32>,
    /// Field-value-based scoring function.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub field_value_factor: Option<FieldValueFactor>,
    /// Randomised score (deterministic per doc+seed).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub random_score: Option<RandomScore>,
    /// Literal numeric script_score source (e.g. `{"source": "3"}`).
    /// Used as a fast-path for the constant-score case so the engine
    /// doesn't have to spin up the Painless interpreter.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub script_score: Option<f32>,
    /// Full Painless `script_score` source. When set, the engine invokes
    /// the `xerj_engine::painless` interpreter per matched doc with
    /// `_score` bound to the query's BM25 score and `params` bound to
    /// `script_score_params`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub script_source: Option<String>,
    /// Free-form params object passed to the script.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub script_params: Option<serde_json::Value>,
    /// ES 8.9+: a named function entry can carry `_name` at the
    /// function level. Its score in `matched_queries` is the function's
    /// own contribution (weight/script_score/factor).
    #[serde(rename = "_name", skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    /// `distance_feature` scoring — pivot / (pivot + distance(origin, field)).
    /// The origin can be an ISO-8601 date string or a [lon, lat] geo point;
    /// the pivot is a duration (for date fields) or distance (for geo_point).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub distance_feature: Option<DistanceFeature>,
    /// `rank_feature` scoring — saturation / log / sigmoid / linear proximity
    /// scoring over a numeric `rank_feature` field.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub rank_feature: Option<RankFeature>,
}

/// Payload for a `rank_feature` function.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RankFeature {
    /// The rank_feature field to score on.
    pub field: String,
    /// Which of the four ES functions to apply.
    pub function: RankFeatureFn,
}

/// The four Elasticsearch `rank_feature` scoring functions.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RankFeatureFn {
    /// `v / (v + pivot)`. When `pivot` is omitted ES uses the field's
    /// approximate value distribution; we default it to 1.0.
    Saturation {
        #[serde(skip_serializing_if = "Option::is_none")]
        pivot: Option<f64>,
    },
    /// `log10(scaling_factor + v)`.
    Log { scaling_factor: f64 },
    /// `v^exponent / (v^exponent + pivot^exponent)`.
    Sigmoid { pivot: f64, exponent: f64 },
    /// `v` (identity).
    Linear,
}

/// Payload for a `distance_feature` function.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct DistanceFeature {
    pub field: String,
    pub pivot: String,
    pub origin: serde_json::Value,
}

/// serde `skip_serializing_if` helper: omit a `bool` field when it is `false`
/// so query round-trips stay byte-identical to their pre-`constant_score` form.
#[inline]
fn is_false(b: &bool) -> bool {
    !*b
}

/// serde `skip_serializing_if` helper: omit a `usize` field when it is `0`
/// (the ES default for `prefix_length`) so query round-trips stay byte-identical.
#[inline]
fn is_zero(n: &usize) -> bool {
    *n == 0
}

/// A single node in the query tree.
///
/// All query types — leaf and compound — are variants of this one enum.
/// Rewriters and planners traverse it with ordinary recursive functions.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "type")]
pub enum QueryNode {
    // ── Structural ────────────────────────────────────────────────────────────
    /// Matches every document in the index.
    MatchAll,

    /// Matches no documents; useful as a sentinel / after constant folding.
    MatchNone,

    /// Compound boolean query.
    Bool {
        /// All clauses must match; scores are summed.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        must: Vec<QueryNode>,
        /// At least `minimum_should_match` clauses must match; scores summed.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        should: Vec<QueryNode>,
        /// No clause may match; does not affect scoring.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        must_not: Vec<QueryNode>,
        /// All must match; scores are *not* summed (zero contribution).
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        filter: Vec<QueryNode>,
        /// Minimum number (or %) of `should` clauses required.
        #[serde(skip_serializing_if = "Option::is_none")]
        minimum_should_match: Option<MinShouldMatch>,
    },

    /// Wraps a query, replacing its score with a fixed constant.
    Constant { score: f32, query: Box<QueryNode> },

    /// Multiplies the wrapped query's score by `boost`.
    Boosted { boost: f32, query: Box<QueryNode> },

    // ── Term-level ────────────────────────────────────────────────────────────
    /// Exact-value match on a single field.
    Term {
        field: String,
        value: serde_json::Value,
        /// Optional boost for this leaf (>1.0 increases score).
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
    },

    /// Exact-value match against any of several values (OR semantics).
    Terms {
        field: String,
        values: Vec<serde_json::Value>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
    },

    /// Numeric / date / keyword range query.
    Range {
        field: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        gte: Option<serde_json::Value>,
        #[serde(skip_serializing_if = "Option::is_none")]
        gt: Option<serde_json::Value>,
        #[serde(skip_serializing_if = "Option::is_none")]
        lte: Option<serde_json::Value>,
        #[serde(skip_serializing_if = "Option::is_none")]
        lt: Option<serde_json::Value>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        /// #1284: true only for a range lowered from a `query_string` that is
        /// effectively lenient (see `Match::lenient`). The `range` DSL clause
        /// has no `lenient` option in ES, so a parsed `range` is always strict.
        #[serde(default, skip_serializing_if = "is_false")]
        lenient: bool,
    },

    /// Prefix match on a keyword field.
    Prefix {
        field: String,
        value: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        /// True when this node came from a *standalone* `{prefix:{…}}` query,
        /// which ES rewrites to a `constant_score` (every match scores `boost`,
        /// no BM25).  False for internally-generated prefixes (query_string,
        /// match_bool_prefix) that keep BM25 scoring.
        #[serde(default, skip_serializing_if = "is_false")]
        constant_score: bool,
        /// #1812: fold case on both sides when matching a KEYWORD field.
        /// `false` (default) = ES-correct case-sensitive keyword prefix.
        /// `true` is set for `prefix{case_insensitive:true}`.
        /// Ignored for `text` fields.
        #[serde(default, skip_serializing_if = "is_false")]
        case_insensitive: bool,
    },

    /// Wildcard pattern match (`?` = any char, `*` = zero-or-more chars).
    Wildcard {
        field: String,
        value: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        /// True when this node came from a *standalone* `{wildcard:{…}}` query,
        /// which ES rewrites to a `constant_score`.  False for the shared
        /// `term{case_insensitive}` / query_string lowerings that keep BM25.
        #[serde(default, skip_serializing_if = "is_false")]
        constant_score: bool,
        /// #668: fold case on both sides when matching a KEYWORD field. `false`
        /// (default) = ES-correct case-sensitive keyword wildcard. `true` is set
        /// only for the `term{case_insensitive:true}` → Wildcard rewrite (and
        /// query_string lowerings), which rely on the matcher folding case.
        /// Ignored for `text` fields (analysed-token semantics apply regardless).
        #[serde(default, skip_serializing_if = "is_false")]
        case_insensitive: bool,
    },

    /// Matches documents where the field has any non-null value.
    Exists { field: String },

    /// Matches documents whose `_id` is in the given list.
    Ids { values: Vec<String> },

    /// A standalone Painless `script` query — matches when the script
    /// (given the doc's `_source` via `doc`/`params`) evaluates truthy.
    /// Distinct from `script_score` (a `function_score` scoring function):
    /// this one is a boolean filter, no scoring involved. Used e.g. by
    /// OpenSearch's UBI sample dashboards ("Top Searches Without Results")
    /// to filter on a computed field via a boolean Supplier-lambda script.
    Script {
        source: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        params: Option<serde_json::Value>,
    },

    // ── Full-text ─────────────────────────────────────────────────────────────
    /// Analysed text query against a single field.
    Match {
        field: String,
        query: String,
        #[serde(default)]
        operator: BoolOperator,
        #[serde(skip_serializing_if = "Option::is_none")]
        analyzer: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        #[serde(skip_serializing_if = "Option::is_none")]
        minimum_should_match: Option<MinShouldMatch>,
        /// ES `lenient` (#1284): when true, a value this field's type cannot
        /// parse (`"abc"` on a `long`) matches nothing instead of failing the
        /// query. The parser sets the *effective* value: explicit `lenient`, or
        /// `true` when the clause targeted every field (`*`), as ES defaults it.
        #[serde(default, skip_serializing_if = "is_false")]
        lenient: bool,
    },

    /// Ordered phrase match with optional slop. `slop` is Lucene
    /// SloppyPhraseMatcher move-distance: forward gaps cost their width and
    /// transpositions (reorderings) cost 2 — `"a b"~2` matches a doc reading
    /// `b a` (#830; evaluator: `xerj_fts::search::phrase_positions_match`).
    MatchPhrase {
        field: String,
        query: String,
        #[serde(default)]
        slop: u32,
        #[serde(skip_serializing_if = "Option::is_none")]
        analyzer: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        /// ES `lenient` (#1284): when true, a value this field's type cannot
        /// parse (`"abc"` on a `long`) matches nothing instead of failing the
        /// query. The parser sets the *effective* value: explicit `lenient`, or
        /// `true` when the clause targeted every field (`*`), as ES defaults it.
        #[serde(default, skip_serializing_if = "is_false")]
        lenient: bool,
    },

    /// Full-text query across multiple fields simultaneously.
    MultiMatch {
        fields: Vec<String>,
        query: String,
        #[serde(default)]
        match_type: MultiMatchType,
        #[serde(skip_serializing_if = "Option::is_none")]
        operator: Option<BoolOperator>,
        #[serde(skip_serializing_if = "Option::is_none")]
        analyzer: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        /// Phrase slop — the number of intervening positions tolerated
        /// between adjacent phrase terms. Applies to `match_type: Phrase`
        /// only (ES: `slop` is a phrase parameter; the field-centric and
        /// term-centric types ignore it). Default 0 = exact adjacency.
        #[serde(default)]
        slop: u32,
        /// Prefix-expansion cap for `match_type: PhrasePrefix` — how many
        /// terms the trailing prefix may expand to (ES default 50).
        #[serde(default = "default_max_expansions")]
        max_expansions: u32,
        /// ES `lenient` (#1284): when true, a value this field's type cannot
        /// parse (`"abc"` on a `long`) matches nothing instead of failing the
        /// query. The parser sets the *effective* value: explicit `lenient`, or
        /// `true` when the clause targeted every field (`*`), as ES defaults it.
        #[serde(default, skip_serializing_if = "is_false")]
        lenient: bool,
    },

    /// Lucene query-string syntax (e.g. `"title:(foo AND bar) OR body:baz"`).
    QueryString {
        query: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        default_field: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        default_operator: Option<BoolOperator>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
    },

    // ── AI-native extensions ──────────────────────────────────────────────────
    /// Dense vector k-NN search (exact or approximate).
    Knn {
        field: String,
        vector: Vec<f32>,
        k: usize,
        /// Approximate-search fan-out: how many candidate neighbours the
        /// ANN index gathers before selecting the top `k`. `None` lets the
        /// executor default it to `k`; ES clamps it to `>= k`.
        #[serde(skip_serializing_if = "Option::is_none")]
        num_candidates: Option<usize>,
        #[serde(skip_serializing_if = "Option::is_none")]
        filter: Option<Box<QueryNode>>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
        /// ES `knn.similarity`: the minimum RAW similarity (in the field's
        /// metric space — cosine value, dot product, or l2 distance) a
        /// vector must reach to count as a match. Docs below the cutoff
        /// are excluded from hits AND from `hits.total`. `None` = no cutoff.
        #[serde(skip_serializing_if = "Option::is_none")]
        similarity: Option<f32>,
    },

    /// Natural-language semantic search — text is embedded at query time.
    SemanticSearch {
        field: String,
        /// The natural-language query text to embed.
        text: String,
        k: usize,
        #[serde(skip_serializing_if = "Option::is_none")]
        filter: Option<Box<QueryNode>>,
        #[serde(skip_serializing_if = "Option::is_none")]
        boost: Option<f32>,
    },

    /// Combine multiple sub-queries with a score-fusion strategy.
    Hybrid {
        /// Each sub-query paired with its relative weight.
        queries: Vec<WeightedQuery>,
        #[serde(default)]
        fusion: FusionStrategy,
    },

    /// Function score — modifies document scores using one or more scoring functions.
    FunctionScore {
        /// The base query whose hits are scored.
        query: Box<QueryNode>,
        /// Scoring functions applied to each hit.
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        functions: Vec<ScoreFunction>,
        /// How multiple function scores are combined.
        #[serde(default)]
        score_mode: ScoreMode,
        /// How the combined function score is merged with the query score.
        #[serde(default)]
        boost_mode: BoostMode,
        /// Upper bound on the combined score (None = no cap).
        #[serde(skip_serializing_if = "Option::is_none")]
        max_boost: Option<f32>,
    },

    /// Boosting query: matches positive, penalises docs that also match negative.
    Boosting {
        /// Docs must match this query.
        positive: Box<QueryNode>,
        /// Docs that also match this query have their score multiplied by `negative_boost`.
        negative: Box<QueryNode>,
        /// Score multiplier for docs that match the negative query (0.0–1.0).
        negative_boost: f32,
    },

    /// Disjunction-Max query: score = max(sub-scores) + tie_breaker * Σ(other scores).
    DisMax {
        queries: Vec<QueryNode>,
        /// Tie-breaker added to the sum of non-winning sub-scores (default 0.0).
        #[serde(default)]
        tie_breaker: f32,
    },

    // ── Extended query types ───────────────────────────────────────────────────
    /// Fuzzy match — allows typo tolerance via Levenshtein edit distance.
    Fuzzy {
        field: String,
        value: String,
        #[serde(default)]
        fuzziness: Fuzziness,
        /// #423/#406: fold case on both sides when true. `false` (default) =
        /// ES-correct case-sensitive keyword fuzzy (the value is matched raw
        /// against the term dictionary). Ignored for `text` fields.
        #[serde(default, skip_serializing_if = "is_false")]
        case_insensitive: bool,
        /// #848: the number of leading characters that must match EXACTLY
        /// (not subject to edits) before Levenshtein applies. ES default `0`
        /// (no constraint). `N > 0` requires the query and each candidate term
        /// to share their first `N` characters — pruning fuzzy expansions that
        /// differ in the prefix.
        #[serde(default, skip_serializing_if = "is_zero")]
        prefix_length: usize,
    },

    /// Regular expression match against a field value.
    Regexp {
        field: String,
        pattern: String,
        /// #1812: fold case on both sides when matching a KEYWORD field.
        /// `false` (default) = ES-correct case-sensitive keyword regexp.
        /// Ignored for `text` fields.
        #[serde(default, skip_serializing_if = "is_false")]
        case_insensitive: bool,
    },

    /// Position-aware text match (ES `intervals` query). The `rule` is the
    /// raw rule JSON (one of match/all_of/any_of/prefix/wildcard/fuzzy,
    /// optionally with `filter:` clauses) — the executor tokenises the
    /// field at query time and evaluates the rule against the token
    /// positions, which is why it stays as an untyped JSON subtree here.
    Intervals {
        field: String,
        rule: serde_json::Value,
    },

    /// Match phrase with a prefix match on the last token.
    MatchPhrasePrefix {
        field: String,
        query: String,
        #[serde(default = "default_max_expansions")]
        max_expansions: u32,
        /// Allowed intervening positions across the whole phrase, trailing
        /// prefix term included.  ES accepts and honours `slop` here
        /// (`MatchPhrasePrefixQueryBuilder` parses it and passes it to
        /// `MatchQueryParser.setPhraseSlop`), so dropping it would be
        /// accept-and-ignore (#204 class).
        #[serde(default)]
        slop: u32,
    },

    /// Simple query string — splits on `+`/`|`/`-` operators, converted to a Bool query.
    SimpleQueryString {
        query: String,
        #[serde(default)]
        fields: Vec<String>,
    },

    /// Geo distance query — matches documents within `distance_km` of the given lat/lon.
    GeoDistance {
        /// The geo_point field name.
        field: String,
        /// Latitude of the query origin.
        lat: f64,
        /// Longitude of the query origin.
        lon: f64,
        /// Maximum distance in kilometres.
        distance_km: f64,
    },

    /// Geo bounding box query — matches documents whose geo_point falls within the box.
    GeoBoundingBox {
        /// The geo_point field name.
        field: String,
        /// Top-left corner (lat, lon).
        top_left: (f64, f64),
        /// Bottom-right corner (lat, lon).
        bottom_right: (f64, f64),
    },

    // ── Nested / join / specialised queries ───────────────────────────────────
    /// Nested query — runs an inner query against each element of a nested array.
    ///
    /// If any element matches the inner query, the document matches.
    Nested {
        /// Dot-path to the nested array field (e.g. `"comments"`).
        path: String,
        /// The query to run against each nested element.
        query: Box<QueryNode>,
        /// How scores from matching elements are combined (ignored in filtering).
        #[serde(skip_serializing_if = "Option::is_none")]
        score_mode: Option<String>,
    },

    /// More-like-this query — finds documents similar to example text.
    MoreLikeThis {
        /// Fields to compare (default: all text fields).
        fields: Vec<String>,
        /// One or more example text strings to find similar documents for.
        like: Vec<String>,
        /// Minimum number of times a term must appear in the input text.
        #[serde(default = "default_min_term_freq")]
        min_term_freq: u32,
        /// Maximum number of query terms to use.
        #[serde(default = "default_max_query_terms")]
        max_query_terms: u32,
    },

    /// Percolate query — reverse search. Each document stored in the index
    /// holds a serialized query in its `field` (a `percolator`-typed field);
    /// this query matches those stored documents whose stored query matches
    /// one of the supplied inline `documents`.
    Percolate {
        /// Name of the percolator field holding the stored query object.
        field: String,
        /// One or more inline documents to test the stored queries against.
        documents: Vec<serde_json::Value>,
    },

    /// Pinned query — ensures specific document IDs appear first in results.
    Pinned {
        /// IDs to pin to the top of results.
        ids: Vec<String>,
        /// The fallback query whose results follow the pinned IDs.
        organic: Box<QueryNode>,
    },

    /// Named query wrapper — attaches a logical name to any query.
    ///
    /// When a document matches, the name appears in `matched_queries` in the hit response.
    Named {
        /// The human-readable name for this query clause.
        name: String,
        /// The wrapped query.
        query: Box<QueryNode>,
    },

    // ── Span queries ──────────────────────────────────────────────────────────
    /// Span term — exact value match within span context.
    SpanTerm { field: String, value: String },

    /// Span near — span terms that appear within `slop` positions of each other.
    SpanNear {
        clauses: Vec<QueryNode>,
        slop: u32,
        in_order: bool,
    },

    /// Span or — matches if any of the span clauses match.
    SpanOr { clauses: Vec<QueryNode> },

    /// Span not — matches the include span but not the exclude span.
    SpanNot {
        include: Box<QueryNode>,
        exclude: Box<QueryNode>,
    },

    /// Span first — matches if the span term appears in the first `end` positions.
    SpanFirst {
        match_query: Box<QueryNode>,
        end: u32,
    },

    /// Span containing — matches spans of `big` that enclose a span of `little`.
    SpanContaining {
        little: Box<QueryNode>,
        big: Box<QueryNode>,
    },

    /// Span within — matches spans of `little` that are enclosed by a span of `big`.
    SpanWithin {
        little: Box<QueryNode>,
        big: Box<QueryNode>,
    },

    // NOTE: there are deliberately NO join-query variants (has_child /
    // has_parent). XERJ never materializes a parent/child join, so an AST
    // variant here would only exist to be flat-matched — silently wrong
    // results — if anyone re-enabled parsing. The parser rejects both with a
    // 400 (parser.rs::parse_has_child / parse_has_parent); the corpse variants
    // and their dead planner/executor arms were removed.

    // ── Geo shape queries ─────────────────────────────────────────────────────
    /// Geo polygon — matches documents whose geo_point falls within the polygon.
    GeoPolygon {
        field: String,
        points: Vec<(f64, f64)>,
    },

    /// Geo shape — matches documents whose geo field matches the given shape.
    GeoShape { field: String, shape: GeoShapeType },
}

/// Shape type for geo_shape queries.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum GeoShapeType {
    /// A single point (lat, lon).
    Point { lat: f64, lon: f64 },
    /// An envelope (bounding box) given by top-left and bottom-right corners (lat, lon).
    Envelope {
        top_left: (f64, f64),
        bottom_right: (f64, f64),
    },
    /// A polygon defined by a list of (lat, lon) points.
    Polygon { points: Vec<(f64, f64)> },
    /// A circle defined by a center point and a radius in kilometres.
    Circle { center: (f64, f64), radius_km: f64 },
}

// ─────────────────────────────────────────────────────────────────────────────
// Rescore types
// ─────────────────────────────────────────────────────────────────────────────

/// The inner parameters for a rescore query.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RescoreQueryInner {
    /// The query used to re-score the top-N hits.
    pub rescore_query: QueryNode,
    /// Weight applied to the original query score (default 1.0).
    #[serde(default = "default_weight_1")]
    pub query_weight: f32,
    /// Weight applied to the rescore query score (default 1.0).
    #[serde(default = "default_weight_1")]
    pub rescore_query_weight: f32,
}

fn default_weight_1() -> f32 {
    1.0
}

/// A single rescore window: re-scores the top `window_size` hits using a secondary query.
///
/// Final score = `original_score * query_weight + rescore_score * rescore_query_weight`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RescoreQuery {
    /// Number of top hits to re-score (default 100).
    #[serde(default = "default_rescore_window")]
    pub window_size: usize,
    /// The secondary query and its weighting parameters.
    /// At least one of `query` or `script` must be set; when both are
    /// present the engine applies them in declaration order (matching ES).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub query: Option<RescoreQueryInner>,
    /// Optional Painless script-based rescore. When set, the rescore
    /// score for each hit is the `script.source` evaluated with
    /// `script.params` and `_score` bound to the hit's current score.
    /// Independent of `query` (you can have one or both).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub script: Option<ScriptRescore>,
}

/// Painless script rescorer. Mirrors the
/// `rescore.script.script: { source, params }` body shape.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct ScriptRescore {
    /// Painless source.
    pub source: String,
    /// Free-form params object passed to the script.
    #[serde(default)]
    pub params: serde_json::Value,
    /// Weight applied to the original `_score` after script evaluation
    /// (default 1.0). ES `script_score.script_score` rescore semantics.
    #[serde(default = "default_weight_1")]
    pub query_weight: f32,
    /// Weight applied to the script's returned score (default 1.0).
    #[serde(default = "default_weight_1")]
    pub rescore_query_weight: f32,
    /// Combine mode: "total" (default), "multiply", "min", "max", "avg",
    /// "replace". ES rescore default is "total" (sum of weighted scores).
    #[serde(default)]
    pub score_mode: Option<String>,
}

fn default_rescore_window() -> usize {
    100
}

fn default_min_term_freq() -> u32 {
    2
}

fn default_max_query_terms() -> u32 {
    25
}

fn default_max_expansions() -> u32 {
    50
}

/// A sub-query with an associated weight for `Hybrid` fusion.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WeightedQuery {
    pub query: QueryNode,
    pub weight: f32,
}

impl QueryNode {
    /// Returns `true` if this node is `MatchAll`.
    pub fn is_match_all(&self) -> bool {
        matches!(self, QueryNode::MatchAll)
    }

    /// Returns `true` if this node is `MatchNone`.
    pub fn is_match_none(&self) -> bool {
        matches!(self, QueryNode::MatchNone)
    }

    /// Returns `true` if this node is a `Bool` with only filter clauses
    /// (no scoring contribution from sub-queries).
    pub fn is_filter_only(&self) -> bool {
        match self {
            QueryNode::Bool {
                must,
                should,
                filter,
                must_not,
                ..
            } => must.is_empty() && should.is_empty() && !filter.is_empty() || !must_not.is_empty(),
            QueryNode::Exists { .. }
            | QueryNode::Term { .. }
            | QueryNode::Terms { .. }
            | QueryNode::Range { .. }
            | QueryNode::Ids { .. } => false,
            _ => false,
        }
    }

    /// Returns `true` if a `Hybrid` node appears anywhere in this subtree,
    /// including inside every wrapper (bool clauses, boost/name/constant
    /// decorators, knn/semantic filters, boosting/dis_max/pinned, span
    /// clauses) and inside `hybrid.queries[].query` itself.
    ///
    /// #943: the engine executes a hybrid ONLY from the short-circuit ladder
    /// in `search_inner` (root node, or a `bool{must:[hybrid], filter:[…]}`
    /// wrapper); anywhere else the doc matcher's catch-all silently matches
    /// nothing. Callers use this to fail loud (400) instead of answering with
    /// the wrong hit set — the engine for unpeelable shapes, the API layer
    /// for `post_filter` beside a hybrid (post_filter never reaches the
    /// engine, so the filter was silently ignored).
    pub fn contains_hybrid(&self) -> bool {
        fn walk(q: &QueryNode) -> bool {
            match q {
                QueryNode::Hybrid { .. } => true,
                QueryNode::MatchAll
                | QueryNode::MatchNone
                | QueryNode::Term { .. }
                | QueryNode::Terms { .. }
                | QueryNode::Range { .. }
                | QueryNode::Prefix { .. }
                | QueryNode::Wildcard { .. }
                | QueryNode::Exists { .. }
                | QueryNode::Ids { .. }
                | QueryNode::Script { .. }
                | QueryNode::Match { .. }
                | QueryNode::MatchPhrase { .. }
                | QueryNode::MultiMatch { .. }
                | QueryNode::QueryString { .. }
                | QueryNode::Fuzzy { .. }
                | QueryNode::Regexp { .. }
                | QueryNode::Intervals { .. }
                | QueryNode::MatchPhrasePrefix { .. }
                | QueryNode::SimpleQueryString { .. }
                | QueryNode::GeoDistance { .. }
                | QueryNode::GeoBoundingBox { .. }
                | QueryNode::GeoPolygon { .. }
                | QueryNode::GeoShape { .. }
                | QueryNode::SpanTerm { .. }
                | QueryNode::MoreLikeThis { .. }
                | QueryNode::Percolate { .. } => false,
                QueryNode::Bool {
                    must,
                    should,
                    must_not,
                    filter,
                    ..
                } => must
                    .iter()
                    .chain(should)
                    .chain(must_not)
                    .chain(filter)
                    .any(walk),
                QueryNode::Constant { query, .. }
                | QueryNode::Boosted { query, .. }
                | QueryNode::Named { query, .. }
                | QueryNode::FunctionScore { query, .. }
                | QueryNode::Nested { query, .. } => walk(query),
                QueryNode::Boosting {
                    positive, negative, ..
                } => walk(positive) || walk(negative),
                QueryNode::DisMax { queries, .. } => queries.iter().any(walk),
                QueryNode::Pinned { organic, .. } => walk(organic),
                QueryNode::Knn { filter, .. } | QueryNode::SemanticSearch { filter, .. } => {
                    filter.as_deref().is_some_and(walk)
                }
                QueryNode::SpanNear { clauses, .. } | QueryNode::SpanOr { clauses } => {
                    clauses.iter().any(walk)
                }
                QueryNode::SpanNot { include, exclude } => walk(include) || walk(exclude),
                QueryNode::SpanFirst { match_query, .. } => walk(match_query),
                QueryNode::SpanContaining { little, big }
                | QueryNode::SpanWithin { little, big } => walk(little) || walk(big),
            }
        }
        walk(self)
    }

    /// Rough structural depth — used by the planner for cost estimation.
    pub fn depth(&self) -> usize {
        match self {
            QueryNode::Bool {
                must,
                should,
                must_not,
                filter,
                ..
            } => {
                let max_child = must
                    .iter()
                    .chain(should.iter())
                    .chain(must_not.iter())
                    .chain(filter.iter())
                    .map(|q| q.depth())
                    .max()
                    .unwrap_or(0);
                1 + max_child
            }
            QueryNode::Constant { query, .. } | QueryNode::Boosted { query, .. } => {
                1 + query.depth()
            }
            QueryNode::Knn { filter, .. } | QueryNode::SemanticSearch { filter, .. } => {
                1 + filter.as_ref().map(|f| f.depth()).unwrap_or(0)
            }
            QueryNode::Hybrid { queries, .. } => {
                let max_child = queries.iter().map(|wq| wq.query.depth()).max().unwrap_or(0);
                1 + max_child
            }
            QueryNode::FunctionScore { query, .. } => 1 + query.depth(),
            QueryNode::Boosting {
                positive, negative, ..
            } => 1 + positive.depth().max(negative.depth()),
            QueryNode::DisMax { queries, .. } => {
                let max_child = queries.iter().map(|q| q.depth()).max().unwrap_or(0);
                1 + max_child
            }
            QueryNode::Fuzzy { .. }
            | QueryNode::Regexp { .. }
            | QueryNode::MatchPhrasePrefix { .. }
            | QueryNode::SimpleQueryString { .. }
            | QueryNode::GeoDistance { .. }
            | QueryNode::GeoBoundingBox { .. }
            | QueryNode::MoreLikeThis { .. } => 1,
            QueryNode::Nested { query, .. } => 1 + query.depth(),
            QueryNode::Pinned { organic, .. } => 1 + organic.depth(),
            QueryNode::Named { query, .. } => 1 + query.depth(),
            _ => 1,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// SearchRequest — the top-level request envelope
// ─────────────────────────────────────────────────────────────────────────────

/// Controls how total hits are tracked.
///
/// - `True`     — always count all matching docs (default, ES behaviour).
/// - `False`    — stop counting once `size` hits are found.
/// - `Limit(N)` — stop counting after N docs; return `Gte` relation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
#[derive(Default)]
pub enum TrackTotalHits {
    /// Count all matching documents (default).
    #[serde(rename = "true")]
    #[default]
    True,
    /// Do not count beyond `size` hits.
    #[serde(rename = "false")]
    False,
    /// Count up to `N` documents; relation becomes `gte` when capped.
    Limit(u64),
}

/// The fully-parsed search request.
///
/// This is what the REST layer hands to the query engine after deserialising
/// the request body.  All ES-level options are included.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SearchRequest {
    /// The root query node.
    #[serde(default = "default_query")]
    pub query: QueryNode,

    /// First result offset (default 0).
    #[serde(default)]
    pub from: usize,

    /// Maximum number of hits to return (default 10).
    #[serde(default = "default_size")]
    pub size: usize,

    /// Sort specification (empty = sort by `_score` descending).
    #[serde(default)]
    pub sort: Vec<crate::sort::SortField>,

    /// Cursor value for keyset pagination (ES `search_after`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub search_after: Option<Vec<serde_json::Value>>,

    /// Aggregation definitions (passed through as opaque JSON for now).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub aggs: Option<serde_json::Value>,

    /// Whether to include per-hit scoring explanation.
    #[serde(default)]
    pub explain: bool,

    /// `_source` inclusion / exclusion filter.
    #[serde(default, rename = "_source")]
    pub source: SourceFilter,

    /// Hard timeout in milliseconds; query is cancelled if exceeded.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub timeout_ms: Option<u64>,

    /// Highlight configuration — which fields to highlight and how.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub highlight: Option<HighlightRequest>,

    /// Controls total hit counting behaviour.
    #[serde(default)]
    pub track_total_hits: TrackTotalHits,

    /// Script fields — computed fields returned alongside hits (currently no-op).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub script_fields: Option<serde_json::Value>,

    /// Stored/doc-value fields to return alongside hits (different from `_source`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub fields: Vec<String>,

    /// When true, include execution timing breakdown in the response.
    #[serde(default)]
    pub profile: bool,

    /// Field collapsing — deduplicate hits by the given field, keeping the top hit per value.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub collapse: Option<CollapseField>,

    /// Rescore specification — re-scores top hits using a secondary query.
    ///
    /// Each entry in the list is applied in order: the first rescorer re-scores
    /// the top `window_size` hits from the primary query; the second rescorer
    /// re-scores the top `window_size` hits from the first rescorer; and so on.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub rescore: Vec<RescoreQuery>,

    /// Minimum score threshold — hits with `_score < min_score` are
    /// dropped before pagination, aggregations, and total counting.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min_score: Option<f64>,

    /// INTERNAL (never on the wire — `serde(skip)`): iterate segments in
    /// per-segment-max-of-this-date-field DESC order for sortless
    /// match_all-shaped requests.  This is ES 7.16's "sort segments on
    /// timestamp" LEAF ordering for indices that map `@timestamp` at
    /// create time: segments are read newest-first while docs inside each
    /// segment keep arrival order and hits keep `_score` 1.0 / max_score
    /// 1.0.  Set by the ES-compat layer; replaces the old injected per-doc
    /// `@timestamp desc` sort, which diverged from real ES on settled
    /// indices (wrong page windows + `max_score: null`).
    #[serde(skip)]
    pub leaf_ts_field: Option<String>,

    /// INTERNAL (never on the wire — `serde(skip)`): whether, and how, to
    /// measure the `_source` payload this request did NOT have to send.
    ///
    /// The ES-compat `_search` handler sets [`SavingsMode::Sampled`] unless
    /// `?savings=` says otherwise, so the statistic is on by default for
    /// user-facing searches. The AST default is [`SavingsMode::Off`] so that
    /// the many internal engine searches (reindex, update-by-query, terms
    /// lookups, suggesters) never pay for a number nobody will read.
    #[serde(skip)]
    pub savings: SavingsMode,

    /// INTERNAL (never on the wire — `serde(skip)`): the caller reads nothing
    /// from the hits except their `id`s (`_delete_by_query` pages, the
    /// engine-level purge loop). When the request shape needs nothing beyond
    /// ids — sort keys confined to `_id`/`_doc`, no `fields` /
    /// `script_fields` / `highlight` / `explain` / `collapse` / `rescore` /
    /// `aggs` / `min_score` — the executor's hydration sites extract the
    /// stored `_id` without building the `_source` `Value` tree and the
    /// returned hits carry `source: Value::Null` (#1019). Any shape the
    /// engine's eligibility gate rejects runs exactly as a full request.
    ///
    /// Set ONLY by engine-controlled callers; `parse_request` never sets it,
    /// so it can never arrive from the wire (same contract as `savings`).
    #[serde(skip)]
    pub ids_only: bool,
}

/// Whether — and how precisely — to measure withheld `_source` bytes.
///
/// Measurement is not free: it has to look at the values being discarded.
/// `Sampled` bounds that work by extrapolating long arrays from a sample,
/// which is what makes the statistic affordable on every search; `Exact`
/// serializes every omitted byte for callers who need the precise figure.
/// The choice is reported on the wire as `_savings.measured`.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
pub enum SavingsMode {
    /// Do not measure. The engine's internal searches, and any caller that
    /// passes `?savings=false`.
    #[default]
    Off,
    /// Bounded, stratified sampling of long arrays; everything else exact.
    Sampled,
    /// Serialize and count every omitted byte.
    Exact,
}

fn default_query() -> QueryNode {
    QueryNode::MatchAll
}

fn default_size() -> usize {
    10
}

impl Default for SearchRequest {
    fn default() -> Self {
        Self {
            query: QueryNode::MatchAll,
            from: 0,
            size: 10,
            sort: Vec::new(),
            search_after: None,
            aggs: None,
            explain: false,
            source: SourceFilter::default(),
            timeout_ms: None,
            highlight: None,
            track_total_hits: TrackTotalHits::default(),
            script_fields: None,
            fields: Vec::new(),
            profile: false,
            collapse: None,
            rescore: Vec::new(),
            min_score: None,
            leaf_ts_field: None,
            savings: SavingsMode::Off,
            ids_only: false,
        }
    }
}

/// Controls which source fields are returned with each hit.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum SourceFilter {
    /// `_source` was omitted; the engine applies its default source projection.
    ///
    /// This is intentionally a unit variant.  With an untagged enum serde
    /// serialises it as `null`, so it must stay before the value-carrying
    /// variants for the corresponding round-trip to deserialize correctly.
    #[default]
    Default,
    /// `true` → return all source fields; `false` → return none.
    Enabled(bool),
    /// Return only the listed fields.
    Includes(Vec<String>),
    /// Fine-grained include / exclude lists.
    Fields {
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        includes: Vec<String>,
        #[serde(default, skip_serializing_if = "Vec::is_empty")]
        excludes: Vec<String>,
    },
}

// ─────────────────────────────────────────────────────────────────────────────
// HighlightRequest — per-field highlighting configuration
// ─────────────────────────────────────────────────────────────────────────────

/// Highlight configuration for a search request.
///
/// Mirrors ES highlight syntax:
/// ```json
/// "highlight": {
///   "pre_tag": "<em>",
///   "post_tag": "</em>",
///   "fragment_size": 150,
///   "fields": { "content": {}, "title": { "fragment_size": 50 } }
/// }
/// ```
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct HighlightRequest {
    /// Fields to highlight. Keys are field names; values are per-field options.
    #[serde(default)]
    pub fields: std::collections::HashMap<String, HighlightFieldOptions>,

    /// Opening tag around each highlighted term (default `"<em>"`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pre_tag: Option<String>,

    /// Closing tag around each highlighted term (default `"</em>"`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub post_tag: Option<String>,

    /// Maximum length (in chars) of each returned fragment (default 150).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fragment_size: Option<usize>,

    /// Number of fragments to return per field (default 5).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub number_of_fragments: Option<usize>,

    /// ES `require_field_match` (default `true`): when a field PATTERN such
    /// as `"*"` is expanded, keep only the fields the query actually targets.
    /// `false` keeps every matching text/keyword field.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub require_field_match: Option<bool>,

    /// Highlighter implementation (`unified`, `plain`, `fvh`, `semantic`).
    /// Absent means the field type's default: `semantic` for `semantic_text`
    /// on a semantic query, the lexical term highlighter otherwise.
    #[serde(default, rename = "type", skip_serializing_if = "Option::is_none")]
    pub highlighter_type: Option<String>,

    /// `score` (semantic default here) or `none` (document order). A field
    /// that sets its own `order` wins.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub order: Option<String>,
}

/// Per-field highlight options (can override the top-level defaults).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
pub struct HighlightFieldOptions {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pre_tag: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub post_tag: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fragment_size: Option<usize>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub number_of_fragments: Option<usize>,
    /// Overrides [`HighlightRequest::highlighter_type`] for this field.
    #[serde(default, rename = "type", skip_serializing_if = "Option::is_none")]
    pub highlighter_type: Option<String>,
    /// Overrides [`HighlightRequest::order`] for this field.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub order: Option<String>,
}

// ─────────────────────────────────────────────────────────────────────────────
// CollapseField — field collapsing (deduplication by field value)
// ─────────────────────────────────────────────────────────────────────────────

/// Field collapsing: keep only the top-scoring hit per unique value of `field`.
///
/// Mirrors ES `collapse` parameter:
/// ```json
/// "collapse": { "field": "category" }
/// ```
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CollapseField {
    /// The field to collapse on (keyword / numeric).
    pub field: String,
    /// Optional inner_hits — return additional hits per group (opaque JSON for now).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub inner_hits: Option<serde_json::Value>,
}

#[cfg(test)]
mod source_filter_tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn source_filter_shapes_round_trip_through_serde() {
        let cases = [
            (SourceFilter::Default, json!(null)),
            (SourceFilter::Enabled(true), json!(true)),
            (SourceFilter::Enabled(false), json!(false)),
            (
                SourceFilter::Includes(vec!["field".to_string()]),
                json!(["field"]),
            ),
        ];

        for (filter, expected_wire) in cases {
            let wire = serde_json::to_value(&filter).unwrap();
            assert_eq!(wire, expected_wire);
            let round_tripped: SourceFilter = serde_json::from_value(wire).unwrap();
            assert_eq!(round_tripped, filter);
        }
    }

    #[test]
    fn omitted_source_and_explicit_booleans_keep_distinct_variants() {
        let omitted = crate::parser::parse_request(&json!({})).unwrap();
        assert_eq!(omitted.source, SourceFilter::Default);

        let explicitly_enabled = crate::parser::parse_request(&json!({
            "_source": true
        }))
        .unwrap();
        assert_eq!(explicitly_enabled.source, SourceFilter::Enabled(true));

        let explicitly_disabled = crate::parser::parse_request(&json!({
            "_source": false
        }))
        .unwrap();
        assert_eq!(explicitly_disabled.source, SourceFilter::Enabled(false));
    }

    #[test]
    fn search_request_source_shapes_round_trip_after_parsing() {
        let cases = [
            (json!({}), SourceFilter::Default),
            (json!({"_source": true}), SourceFilter::Enabled(true)),
            (json!({"_source": false}), SourceFilter::Enabled(false)),
            (
                json!({"_source": ["field"]}),
                SourceFilter::Includes(vec!["field".to_string()]),
            ),
        ];

        for (body, expected_source) in cases {
            let request = crate::parser::parse_request(&body).unwrap();
            assert_eq!(request.source, expected_source);
            let serialized = serde_json::to_value(&request).unwrap();
            let round_tripped: SearchRequest = serde_json::from_value(serialized).unwrap();
            assert_eq!(round_tripped.source, expected_source);
        }
    }
}

//! Error types for the query crate.

use thiserror::Error;

/// The query crate's error type.
#[derive(Debug, Error)]
pub enum QueryError {
    /// The query DSL JSON was syntactically invalid or semantically rejected.
    #[error("parse error: {0}")]
    Parse(#[from] ParseError),

    /// The query references a field that does not exist in the schema.
    #[error("unknown field `{field}` in {context}")]
    UnknownField { field: String, context: String },

    /// The rewriter hit its pass limit without converging — indicates a bug.
    #[error("query rewriter did not converge after {max_passes} passes")]
    RewriterNotConverged { max_passes: usize },

    /// The executor was given an unsupported execution plan variant.
    #[error("unsupported execution plan: {0}")]
    UnsupportedPlan(String),

    /// A timeout was configured and the query exceeded it.
    #[error("query timed out after {elapsed_ms}ms (limit {limit_ms}ms)")]
    Timeout { elapsed_ms: u64, limit_ms: u64 },

    /// An underlying I/O or segment error.
    #[error("storage error: {0}")]
    Storage(String),

    /// Propagated from `anyhow`.
    #[error(transparent)]
    Other(#[from] anyhow::Error),
}

/// A parse-level error with a human-readable message.
///
/// Prefer `ParseError::invalid(…)` for straightforward "bad input" cases
/// rather than constructing the struct directly.
#[derive(Debug, Error)]
pub enum ParseError {
    #[error("{0}")]
    Invalid(String),
    #[error("unknown query type `{0}` — see https://xerj.org/docs/queries for supported types")]
    UnknownQueryType(String),
}

impl ParseError {
    pub fn invalid(msg: impl Into<String>) -> Self {
        ParseError::Invalid(msg.into())
    }

    pub fn unknown_query_type(name: impl Into<String>) -> Self {
        ParseError::UnknownQueryType(name.into())
    }

    /// Shorthand for `Err(QueryError::Parse(ParseError::invalid(msg)))`.
    pub fn err<T>(msg: impl Into<String>) -> Result<T> {
        Err(QueryError::Parse(ParseError::Invalid(msg.into())))
    }

    /// Shorthand for `Err(QueryError::Parse(ParseError::UnknownQueryType(name)))`.
    pub fn err_unknown<T>(name: impl Into<String>) -> Result<T> {
        Err(QueryError::Parse(ParseError::UnknownQueryType(name.into())))
    }
}

/// Convenience alias — every public function in this crate returns this.
pub type Result<T> = std::result::Result<T, QueryError>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unknown_query_type_points_at_the_live_query_list() {
        let msg = ParseError::unknown_query_type("nope").to_string();
        assert!(msg.contains("https://xerj.org/docs/queries"), "{msg}");
        assert!(
            !msg.contains("xerj.io"),
            "the error must not link a host that does not resolve: {msg}"
        );
    }
}

//! Query executor — runs an [`ExecutionPlan`] and produces [`SearchResult`].
//!
//! ## Design
//!
//! Unlike Elasticsearch's two-phase query+fetch model (first collect doc IDs
//! and scores, then fetch source), xerj uses a **single-pass** model:
//!
//! 1. Each segment engine implements the [`SegmentExecutor`] trait.
//! 2. The top-level executor fans out to all segments in parallel (via rayon).
//! 3. Results from all segments are merged into a single top-K heap.
//! 4. Source is fetched as hits are produced — no second network round-trip.
//!
//! ## Pagination
//!
//! `from`/`size` pagination is supported for small offsets.  For deep
//! pagination, use `search_after` (keyset pagination), which avoids the
//! O(from + size) cost of the heap.

use std::cmp::Reverse;
use std::collections::BinaryHeap;

use serde::{Deserialize, Serialize};

use crate::error::Result;
use crate::planner::ExecutionPlan;
use crate::sort::{compare_sort_keys, SortField};

pub const PASSAGE_METADATA_PREFIX: &str = "__xerj_passage_meta__";
pub const PASSAGE_RESPONSE_FIELD: &str = "_passage";

/// Remove engine-owned passage-offset companions before `_source` reaches a
/// client. The metadata remains in stored source for restart/merge correctness.
pub fn strip_internal_passage_metadata(source: &mut serde_json::Value) {
    if let Some(object) = source.as_object_mut() {
        object.retain(|name, _| !name.starts_with(PASSAGE_METADATA_PREFIX));
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Result types
// ─────────────────────────────────────────────────────────────────────────────

/// A single matched document.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Hit {
    /// The document's external string ID (the ES `_id`).
    pub id: String,
    /// BM25 / vector / fusion score.
    pub score: f32,
    /// The document source fields (filtered per `_source`).
    #[serde(rename = "_source")]
    pub source: serde_json::Value,
    /// ES-wire (0-based) sequence number, read from the SAME version-map
    /// entry `source` was resolved from — never re-resolved later, so a
    /// concurrent write can't pair a stale `source` with a live `seq_no`
    /// (#440). `None` for a doc that is unknown/tombstoned at read time, or
    /// when the deferred-hydration path hasn't reached this hit yet
    /// (resolved in that case by whatever later fills `source`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub seq_no: Option<u64>,
    /// Document version, from the same read as `seq_no`/`source`. Same
    /// `None` semantics as `seq_no`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub version: Option<u64>,
    /// The sort key values for this hit (used by `search_after`).
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub sort: Vec<serde_json::Value>,
    /// Per-field scoring explanation (only when `explain: true`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub explain: Option<Explanation>,
    /// Highlight fragments per field (only when `highlight` was in the request).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub highlight: Option<std::collections::HashMap<String, Vec<String>>>,
    /// Names of named queries that matched this document (only present when `_name` was used).
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub matched_queries: Vec<String>,
    /// Winning passage, populated only when the caller explicitly requests
    /// the `_passage` pseudo-field.
    ///
    /// Semantic/kNN hits derive it from compact ingest-time byte offsets;
    /// lexical hits compute the query-term-densest line-snapped window over
    /// the returned page at query time. Either way it is not persisted as a
    /// second text copy and is absent from ordinary responses.
    #[serde(rename = "_passage", skip_serializing_if = "Option::is_none", default)]
    pub passage: Option<PassageMatch>,
}

/// Provenance for the passage that made a hit relevant: the chunk that
/// supplied a semantic hit's max score, or the query-term-densest window of
/// a lexical hit.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PassageMatch {
    /// Original `semantic_text` field, rather than its derived vector field.
    /// For lexical passages: the queried text field the window came from.
    pub field: String,
    /// Semantic hits: zero-based ordinal in the deterministic ingest-time
    /// chunk sequence. Lexical hits have no chunk sequence; here this is the
    /// zero-based LINE index where the passage starts — the "which line of
    /// the file" a caller slicing a large document needs.
    pub ordinal: u32,
    /// UTF-8 byte offsets into `field`.
    pub start_offset: u64,
    pub end_offset: u64,
    /// Winning text slice materialized only for the returned page.
    pub text: String,
    /// Autoindex PDF page identity when the source carries a numeric `page`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub page: Option<u64>,
}

/// Total hits information (mirrors ES semantics exactly).
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TotalHits {
    /// The number of matching documents.
    pub value: u64,
    /// Whether `value` is exact (`eq`) or a lower bound (`gte`).
    pub relation: TotalHitsRelation,
}

/// Indicates whether the total hit count is exact or a lower bound.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TotalHitsRelation {
    /// `value` is the exact count.
    Eq,
    /// `value` is a lower bound (e.g. when `track_total_hits: false` or a
    /// timeout occurred before all segments were scanned).
    Gte,
}

/// A scoring explanation node (mirrors ES `_explanation`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Explanation {
    pub value: f32,
    pub description: String,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub details: Vec<Explanation>,
}

impl Explanation {
    pub fn leaf(value: f32, description: impl Into<String>) -> Self {
        Self {
            value,
            description: description.into(),
            details: vec![],
        }
    }

    pub fn compound(value: f32, description: impl Into<String>, details: Vec<Explanation>) -> Self {
        Self {
            value,
            description: description.into(),
            details,
        }
    }
}

/// What this response did **not** have to send, because of a choice **the
/// caller made** on **this** request.
///
/// The honesty invariants this type exists to enforce (see
/// `SAVINGS-STATS-REPORT.md` for the full rationale):
///
/// * **The baseline is the response the caller would otherwise have
///   received** — same query, same page, no `_source` clause. It is NOT a
///   response containing raw embedding vectors: this engine has not returned
///   those by default since #309, so measuring against them would credit the
///   caller for the engine's own default and overstate the realised saving by
///   ~9x. A blind UX dogfood caught exactly that; the counterfactual is now
///   the only one a reader would recognise.
/// * `bytes` counts only values that were materialised on this request and
///   then left out of this response. Never a hypothetical, never a running
///   total across requests.
/// * The whole struct is `None` when nothing was saved, and the rendered
///   block is `None` when the saving was too small to be worth the bytes
///   spent reporting it — see [`PayloadSavings::rescoped`].
/// * `bytes` is the measured quantity and the only number on the wire. There
///   is deliberately no token conversion: dividing a byte count by a constant
///   produces a bigger number, not more information, and printing
///   "14,008,655 tokens" beside a 22 KB response is what cost an earlier
///   revision its credibility with a real reader.
/// * `measured: "sampled"` appears when long arrays were extrapolated rather
///   than counted. Its **absence means the figure is exact** — an estimate is
///   always labelled, a precise number never needs to be.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PayloadSavings {
    /// Bytes of JSON omitted from this response, relative to the same
    /// response with no `_source` clause.
    pub bytes: u64,
    /// How `bytes` was obtained. Serialized only when `Sampled`.
    pub measured: SavingsMethod,
    /// Short sentence naming the mechanism the caller used. Deliberately
    /// factual rather than congratulatory: obeying a `_source` clause is not
    /// a favour, and a reader told "you asked for 2 fields" learns nothing
    /// they did not just type.
    pub note: String,
    /// Whether the response layer may still re-materialise some of these
    /// bytes through `fields` / `docvalue_fields` / `script_fields`, in which
    /// case it must subtract what it emitted before claiming anything.
    #[serde(skip)]
    pub substitutable: bool,
    /// Per-hit attribution, `(hit id, omitted bytes)`.
    ///
    /// Never serialized: the ES-compat layer re-paginates, de-duplicates and
    /// caps the merged hit set *after* the engine has run, so it re-sums this
    /// over the hits it actually emits. Summing the engine-side total instead
    /// would over-report on multi-index, PIT, kNN-capped and collapsed
    /// searches — i.e. it would inflate.
    #[serde(skip)]
    pub per_hit: Vec<(String, u64)>,
}

/// Which method produced a [`PayloadSavings::bytes`] figure.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum SavingsMethod {
    /// Long arrays were extrapolated from a bounded, stratified sample.
    /// Everything else — including every array short enough to be cheap —
    /// was counted exactly. Observed error is reported in
    /// `SAVINGS-STATS-REPORT.md`.
    Sampled,
    /// Every omitted byte was serialized and counted. Requested with
    /// `?savings=exact`.
    Exact,
}

/// How many times its own size a saving must be before it is worth printing.
///
/// A block that spends 135 bytes to announce a 19-byte saving is a net loss
/// to the very budget it claims to protect, and the dogfood found that shape
/// on ordinary single-document lookups. Silence is already correct when
/// nothing was saved; this is the same principle applied to "saved so little
/// that telling you costs more than it saved".
pub const SAVINGS_REPORT_FLOOR_RATIO: u64 = 10;

impl PayloadSavings {
    /// Build a savings record, or `None` when nothing was actually saved.
    ///
    /// The `None`-on-zero rule lives here so no call site can accidentally
    /// emit a `"bytes": 0` block.
    pub fn new(
        method: SavingsMethod,
        note: impl Into<String>,
        substitutable: bool,
        per_hit: Vec<(String, u64)>,
    ) -> Option<Self> {
        let bytes: u64 = per_hit.iter().map(|(_, b)| *b).sum();
        if bytes == 0 {
            return None;
        }
        Some(Self {
            bytes,
            measured: method,
            note: note.into(),
            substitutable,
            per_hit,
        })
    }

    /// Render the wire block for a byte total computed over a *different* hit
    /// set (the ES-compat layer's post-merge page).
    ///
    /// Returns `None` when the total is zero, and also when the saving is
    /// less than [`SAVINGS_REPORT_FLOOR_RATIO`] times what the block itself
    /// would add to the response. The floor is measured against the rendered
    /// block, not guessed, so it stays true if the wording changes.
    pub fn rescoped(&self, bytes: u64) -> Option<serde_json::Value> {
        if bytes == 0 {
            return None;
        }
        let mut block = serde_json::Map::new();
        block.insert("bytes".to_string(), bytes.into());
        // Absence means exact; only the estimate carries a label.
        if self.measured == SavingsMethod::Sampled {
            block.insert(
                "measured".to_string(),
                serde_json::to_value(self.measured).ok()?,
            );
        }
        block.insert("note".to_string(), self.note.clone().into());
        let block = serde_json::Value::Object(block);
        // `"_savings":` plus the block is what this costs the response.
        let cost = serde_json::to_vec(&block).ok()?.len() as u64 + 11;
        if bytes < cost.saturating_mul(SAVINGS_REPORT_FLOOR_RATIO) {
            return None;
        }
        Some(block)
    }
}

/// The complete search response.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SearchResult {
    /// The hits returned for this page.
    pub hits: Vec<Hit>,
    /// Total matching documents (may be approximate).
    pub total: TotalHits,
    /// Wall-clock time from request receipt to response.
    pub took_ms: u64,
    /// Aggregation results (opaque JSON blob, shaped by the `aggs` request).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub aggs: Option<serde_json::Value>,
    /// Whether the query was cut short by a timeout (partial results).
    #[serde(default)]
    pub timed_out: bool,
    /// Profile data — timing breakdown for query execution phases.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub profile: Option<serde_json::Value>,
    /// Highest score across ALL matched docs, before collapse/pagination.
    /// Used for ES `max_score` with collapse + track_scores (search/111).
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub max_score: Option<f32>,
    /// A Painless **resource-limit** trip (call depth, eval depth, invocation
    /// count, source size) hit while scoring or aggregating this request.
    ///
    /// The scoring paths have no error channel — `apply_function_score` and
    /// friends return a bare `f32` — so before this field a script that blew
    /// the closure call-depth limit silently scored the document `0.0` and
    /// the caller got a wrong number with no indication anything failed.
    /// Populated from the interpreter's fault sink; the API layer turns it
    /// into an error response rather than serving the degraded scores.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub script_failure: Option<String>,
    /// Measured payload the response did not have to carry, populated only
    /// when the caller opted in (`?savings=true`) **and** something was
    /// genuinely omitted. `None` is the correct value for a query that saved
    /// nothing — there is deliberately no zero-valued variant.
    #[serde(skip_serializing_if = "Option::is_none", default)]
    pub savings: Option<PayloadSavings>,
}

impl SearchResult {
    /// Construct an empty result (used for `MatchNone` and error recovery).
    pub fn empty(took_ms: u64) -> Self {
        Self {
            hits: vec![],
            total: TotalHits {
                value: 0,
                relation: TotalHitsRelation::Eq,
            },
            took_ms,
            aggs: None,
            timed_out: false,
            profile: None,
            max_score: None,
            script_failure: None,
            savings: None,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// SegmentExecutor trait
// ─────────────────────────────────────────────────────────────────────────────

/// The interface that each segment engine must implement.
///
/// The query executor calls `execute` on every live segment and then merges
/// the results.  Each segment returns the top-`limit` hits it found, which the
/// top-level executor merges into the global top-K.
///
/// # Thread safety
///
/// Segments are executed in parallel via rayon, so implementations must be
/// `Send + Sync`.  In practice this means holding segment data behind an
/// `Arc<RwLock<…>>` or using memory-mapped read-only slices.
pub trait SegmentExecutor: Send + Sync {
    /// Execute `plan` within this segment and return up to `limit` hits.
    ///
    /// * `limit`        — how many hits to return (at most `from + size`).
    /// * `sort_fields`  — determines hit ordering within the segment.
    /// * `search_after` — keyset cursor; skip hits that sort ≤ cursor.
    /// * `explain`      — populate `Hit::explain` if `true`.
    fn execute(
        &self,
        plan: &ExecutionPlan,
        limit: usize,
        sort_fields: &[SortField],
        search_after: Option<&[serde_json::Value]>,
        explain: bool,
    ) -> Result<Vec<Hit>>;

    /// Count matching documents without returning source or scores.
    ///
    /// May be much cheaper than `execute` when only the total count is needed.
    fn count(&self, plan: &ExecutionPlan) -> Result<u64>;

    /// A human-readable identifier for this segment (for logging/tracing).
    fn segment_id(&self) -> &str;
}

// ─────────────────────────────────────────────────────────────────────────────
// Top-level merge
// ─────────────────────────────────────────────────────────────────────────────

/// Merge hits from multiple segments into a single sorted top-K result.
///
/// # Parameters
///
/// * `segment_hits`  — Per-segment hit lists (each already locally sorted).
/// * `from`          — Skip this many hits from the merged result.
/// * `size`          — Return at most this many hits after `from`.
/// * `sort_fields`   — The sort specification used to compare hits.
///
/// This function runs in O((N·log·k)) time where N is total hits across all
/// segments and k = `from + size`.
pub fn merge_hits(
    segment_hits: Vec<Vec<Hit>>,
    from: usize,
    size: usize,
    sort_fields: &[SortField],
) -> Vec<Hit> {
    let limit = from + size;
    if limit == 0 {
        return vec![];
    }

    // We use a max-heap keyed by (score, id) for the default _score sort,
    // or a general comparator for field sorts.
    //
    // For simplicity we flatten all hits and sort.  For production we would
    // use a k-way merge with per-segment cursors.
    let mut all: Vec<Hit> = segment_hits.into_iter().flatten().collect();

    if sort_fields.is_empty() || (sort_fields.len() == 1 && sort_fields[0].is_score()) {
        // Default: sort by score descending, then id ascending as tiebreaker.
        all.sort_unstable_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| a.id.cmp(&b.id))
        });
    } else {
        all.sort_unstable_by(|a, b| {
            compare_sort_keys(&a.sort, &b.sort, sort_fields).then_with(|| a.id.cmp(&b.id))
        });
    }

    all.into_iter().skip(from).take(size).collect()
}

/// Merge per-segment total-hit counts.
///
/// If any segment returned `Gte`, the merged relation is also `Gte`.
pub fn merge_totals(segment_totals: &[(u64, TotalHitsRelation)]) -> TotalHits {
    let mut total = 0u64;
    let mut relation = TotalHitsRelation::Eq;
    for (count, rel) in segment_totals {
        total = total.saturating_add(*count);
        if *rel == TotalHitsRelation::Gte {
            relation = TotalHitsRelation::Gte;
        }
    }
    TotalHits {
        value: total,
        relation,
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// score-based Top-K heap  (used by segment implementations)
// ─────────────────────────────────────────────────────────────────────────────

/// A fixed-capacity max-heap for collecting top-K hits by score.
///
/// Segment executors should use this to bound memory during scan.
pub struct TopKHeap {
    capacity: usize,
    /// `Reverse` so the heap is a min-heap (we drop the lowest scorer).
    inner: BinaryHeap<Reverse<ScoredHit>>,
}

#[derive(Debug, PartialEq)]
struct ScoredHit {
    score: f32,
    id: String,
    hit: Hit,
}

impl Eq for ScoredHit {}
impl PartialOrd for ScoredHit {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for ScoredHit {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.score
            .partial_cmp(&other.score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| self.id.cmp(&other.id).reverse())
    }
}

impl TopKHeap {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            inner: BinaryHeap::with_capacity(capacity + 1),
        }
    }

    /// Push a hit, evicting the lowest scorer if over capacity.
    pub fn push(&mut self, hit: Hit) {
        let sh = ScoredHit {
            score: hit.score,
            id: hit.id.clone(),
            hit,
        };
        self.inner.push(Reverse(sh));
        if self.inner.len() > self.capacity {
            self.inner.pop(); // evict the lowest scorer
        }
    }

    /// Drain the heap in score-descending order.
    pub fn into_sorted_hits(self) -> Vec<Hit> {
        let mut hits: Vec<Hit> = self.inner.into_iter().map(|Reverse(sh)| sh.hit).collect();
        hits.sort_unstable_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        hits
    }

    /// Current number of hits in the heap.
    pub fn len(&self) -> usize {
        self.inner.len()
    }

    /// Whether the heap currently holds no hits.
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Minimum score currently in the heap (used for early termination).
    pub fn min_score(&self) -> Option<f32> {
        self.inner.peek().map(|Reverse(sh)| sh.score)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use crate::sort::{SortMissing, SortMode, SortOrder};

    fn hit(id: &str, score: f32) -> Hit {
        Hit {
            id: id.to_string(),
            score,
            source: serde_json::Value::Null,
            seq_no: None,
            version: None,
            sort: vec![],
            explain: None,
            highlight: None,
            matched_queries: vec![],
            passage: None,
        }
    }

    // ── TopKHeap ──────────────────────────────────────────────────────────────

    #[test]
    fn test_topk_heap_basic() {
        let mut heap = TopKHeap::new(3);
        heap.push(hit("a", 0.5));
        heap.push(hit("b", 0.9));
        heap.push(hit("c", 0.3));
        heap.push(hit("d", 0.7)); // evicts "c" (lowest)

        let hits = heap.into_sorted_hits();
        assert_eq!(hits.len(), 3);
        assert_eq!(hits[0].id, "b"); // 0.9
        assert_eq!(hits[1].id, "d"); // 0.7
        assert_eq!(hits[2].id, "a"); // 0.5
    }

    #[test]
    fn test_topk_heap_capacity() {
        let mut heap = TopKHeap::new(2);
        for i in 0..10 {
            heap.push(hit(&i.to_string(), i as f32 * 0.1));
        }
        assert_eq!(heap.len(), 2);
        let hits = heap.into_sorted_hits();
        // Should keep the two highest: 9 (0.9) and 8 (0.8)
        assert_eq!(hits[0].id, "9");
        assert_eq!(hits[1].id, "8");
    }

    // ── merge_hits ────────────────────────────────────────────────────────────

    #[test]
    fn test_merge_hits_by_score() {
        let seg1 = vec![hit("a", 0.9), hit("b", 0.5)];
        let seg2 = vec![hit("c", 0.8), hit("d", 0.3)];

        let merged = merge_hits(vec![seg1, seg2], 0, 3, &[]);
        assert_eq!(merged.len(), 3);
        assert_eq!(merged[0].id, "a");
        assert_eq!(merged[1].id, "c");
        assert_eq!(merged[2].id, "b");
    }

    #[test]
    fn test_merge_hits_from_offset() {
        let seg = vec![hit("a", 0.9), hit("b", 0.8), hit("c", 0.7), hit("d", 0.6)];
        let merged = merge_hits(vec![seg], 2, 2, &[]);
        assert_eq!(merged.len(), 2);
        assert_eq!(merged[0].id, "c");
        assert_eq!(merged[1].id, "d");
    }

    #[test]
    fn test_merge_hits_field_sort() {
        let mut h1 = hit("a", 0.5);
        h1.sort = vec![serde_json::json!(1)];
        let mut h2 = hit("b", 0.9);
        h2.sort = vec![serde_json::json!(3)];
        let mut h3 = hit("c", 0.1);
        h3.sort = vec![serde_json::json!(2)];

        let sort_fields = vec![SortField {
            field: "num".to_string(),
            order: SortOrder::Asc,
            mode: SortMode::default(),
            missing: SortMissing::Last,
            format: None,
            unmapped_type: None,
            numeric_type: None,
        }];

        let merged = merge_hits(vec![vec![h1, h2, h3]], 0, 10, &sort_fields);
        // Should be sorted by num ascending: 1, 2, 3
        assert_eq!(merged[0].id, "a");
        assert_eq!(merged[1].id, "c");
        assert_eq!(merged[2].id, "b");
    }

    // ── merge_totals ──────────────────────────────────────────────────────────

    #[test]
    fn test_merge_totals_exact() {
        let totals = vec![
            (100u64, TotalHitsRelation::Eq),
            (50u64, TotalHitsRelation::Eq),
        ];
        let result = merge_totals(&totals);
        assert_eq!(result.value, 150);
        assert_eq!(result.relation, TotalHitsRelation::Eq);
    }

    #[test]
    fn test_merge_totals_approximate() {
        let totals = vec![
            (100u64, TotalHitsRelation::Eq),
            (50u64, TotalHitsRelation::Gte), // one segment was approximate
        ];
        let result = merge_totals(&totals);
        assert_eq!(result.value, 150);
        assert_eq!(result.relation, TotalHitsRelation::Gte);
    }

    // ── SearchResult ──────────────────────────────────────────────────────────

    #[test]
    fn test_empty_result() {
        let r = SearchResult::empty(5);
        assert!(r.hits.is_empty());
        assert_eq!(r.total.value, 0);
        assert_eq!(r.total.relation, TotalHitsRelation::Eq);
        assert_eq!(r.took_ms, 5);
    }
}

//! # xerj-query
//!
//! Query parser, rewriter, planner, and executor for the xerj search engine.
//!
//! ## Architecture overview
//!
//! ```text
//! HTTP body (JSON)
//!      │
//!      ▼
//!  parser::parse_request()   ← ES-compatible query DSL
//!      │
//!      ▼ SearchRequest { query: QueryNode, … }
//!      │
//!  rewriter::rewrite()        ← up to 16 optimisation passes
//!      │
//!      ▼ QueryNode (canonical form)
//!      │
//!  planner::plan_query()     ← QueryNode → ExecutionPlan
//!      │
//!      ▼ ExecutionPlan
//!      │
//!  SegmentExecutor::execute() (per segment, in parallel)
//!      │
//!      ▼ Vec<Hit>  (per segment)
//!      │
//!  executor::merge_hits()    ← global top-K
//!      │
//!      ▼ SearchResult { hits, total, took_ms, aggs }
//! ```
//!
//! ## Why one enum?
//!
//! Elasticsearch's query layer has ~60 Java `Query` classes, each with its own
//! visitor, rewriter, and weight.  xerj collapses this into a single
//! [`QueryNode`] enum.  Rewriters and planners are plain recursive functions —
//! no visitor boilerplate, no dynamic dispatch, no allocation per node type.
//!
//! ## Supported query types
//!
//! All standard Elasticsearch query types are supported:
//!
//! | Category | Types |
//! |---|---|
//! | Full-text | `match`, `match_phrase`, `multi_match`, `query_string` |
//! | Term-level | `term`, `terms`, `range`, `prefix`, `wildcard`, `exists`, `ids` |
//! | Compound | `bool`, `constant_score`, `boosting` |
//! | Special | `match_all`, `match_none` |
//! | AI-native | `knn`, `semantic`, `hybrid` |

pub mod ast;
pub mod dates;
pub mod error;
pub mod executor;
pub mod parser;
pub mod planner;
pub mod rewriter;
pub mod sort;

