use xerj_common::types::Schema;

/// Parse, rewrite, and plan a query in one call.
///
/// This is the standard entry point used by the REST layer.
///
/// ```rust,ignore
/// let plan = xerj_query::prepare_query(&body, &schema)?;
/// ```
pub fn prepare_query(
    body: &serde_json::Value,
    schema: &Schema,
) -> Result<(SearchRequest, ExecutionPlan)> {
    let req = parse_request(body)?;
    let optimised = rewrite(req.query.clone());
    let plan = plan_query(optimised, schema)?;
    Ok((req, plan))
}

//! ES-compatible query DSL parser.
//!
//! Converts raw `serde_json::Value` (from the HTTP request body) into a
//! [`QueryNode`] tree.  The parser is intentionally lenient in the same places
//! ES is lenient (e.g. a missing `query` field defaults to `match_all`) and
//! strict — with **readable** error messages — where ES gives cryptic Java
//! stack traces.
//!
//! ## Entry points
//!
//! | Function | Description |
//! |---|---|
//! | [`parse_request`] | Parse a full `{ "query": …, "from": …, … }` body. |
//! | [`parse_query`] | Parse just the `query` object. |

use base64::Engine as _;
use serde_json::Value;
use std::cell::Cell;
use tracing::trace;

use crate::ast::{
    BoolOperator, BoostMode, FieldValueFactor, FusionStrategy, Fuzziness, GeoShapeType,
    MinShouldMatch, Modifier, MultiMatchType, QueryNode, RandomScore, SavingsMode, ScoreFunction,
    ScoreMode, SearchRequest, SourceFilter, TrackTotalHits, WeightedQuery,
};
use crate::dates;
use crate::error::{ParseError, QueryError, Result};
use crate::sort::{SortField, SortMissing, SortMode, SortOrder};

// ── Recursion depth limit ──────────────────────────────────────────────────────
//
// Bool, dis_max, boosting and constant_score recurse into parse_query for every
// nested clause. Without a cap, a `{"bool":{"filter":[{"bool":{"filter":[…]}}]}}`
// payload of arbitrary depth blows the stack — a trivial unauthenticated DOS.
//
// ES uses a default of 20. We allow 64 (Rust frames are small relative to JVM
// frames). The counter is thread-local because parse_query is sync and runs on
// whichever tokio worker handles the request; parallel requests on different
// workers each get their own counter.
const MAX_QUERY_DEPTH: usize = 64;

/// Parse-time ceiling on `from + size`: the largest value ES's
/// `index.max_result_window` can take (a Java `int`). The real limit is the
/// index's `index.max_result_window`, else the node's
/// `limits.max_result_window` (default 10,000), and the engine enforces it
/// before anything is materialised. This bound only keeps the arithmetic
/// sane; it used to be a hardcoded 10,000, which silently overrode a larger
/// per-index setting. Deep pagination should use `search_after`/PIT.
pub const MAX_RESULT_WINDOW: usize = i32::MAX as usize;

// ── Boolean clause limit ──────────────────────────────────────────────────────
//
// Issue #122, second half. `MAX_QUERY_DEPTH` bounds how deeply a query nests;
// nothing bounded how WIDE it is, so a single `bool` could carry an unbounded
// number of clauses. That is not merely a big query: there is no compiled-script
// cache in this engine, so every `script` clause is re-tokenised and re-parsed
// for every document it is evaluated against, and the cost of a `bool` with N
// script clauses over D documents is N x D full script parses. The clause count
// is the only place that product can be bounded before any work starts.
//
// 1,024 is Elasticsearch's documented `indices.query.bool.max_clause_count`
// default, and ES answers `too_many_clauses` above it — so a query this
// rejects is a query that was already rejected by the system being emulated.
const MAX_CLAUSE_COUNT: usize = 1_024;

thread_local! {
    static QUERY_DEPTH: Cell<usize> = const { Cell::new(0) };
    /// Boolean clauses parsed so far in the current top-level query. Reset by
    /// the outermost [`parse_query`] rather than by an RAII guard: the limit
    /// is on the whole query's total width, so it must accumulate across
    /// sibling `bool`s instead of unwinding with each one.
    static CLAUSE_COUNT: Cell<usize> = const { Cell::new(0) };
}

/// Charge one boolean clause against [`MAX_CLAUSE_COUNT`].
fn charge_clause() -> Result<()> {
    let exceeded = CLAUSE_COUNT.with(|c| {
        let next = c.get() + 1;
        c.set(next);
        next > MAX_CLAUSE_COUNT
    });
    if exceeded {
        return Err(QueryError::Parse(ParseError::Invalid(format!(
            "too_many_clauses: maxClauseCount is set to {MAX_CLAUSE_COUNT}"
        ))));
    }
    Ok(())
}

/// RAII guard that increments the thread-local query-depth counter on
/// construction and decrements it on drop. Returns an error if the depth
/// exceeds `MAX_QUERY_DEPTH` so callers can `?` straight through.
struct DepthGuard;

impl DepthGuard {
    fn enter() -> Result<Self> {
        let exceeded = QUERY_DEPTH.with(|d| {
            let next = d.get() + 1;
            d.set(next);
            next > MAX_QUERY_DEPTH
        });
        if exceeded {
            QUERY_DEPTH.with(|d| d.set(d.get().saturating_sub(1)));
            return Err(QueryError::Parse(ParseError::Invalid(format!(
                "query nesting exceeds max depth of {MAX_QUERY_DEPTH}"
            ))));
        }
        Ok(DepthGuard)
    }
}

impl Drop for DepthGuard {
    fn drop(&mut self) {
        QUERY_DEPTH.with(|d| d.set(d.get().saturating_sub(1)));
    }
}

// ── Error helpers ──────────────────────────────────────────────────────────────

/// Construct `Err(QueryError::Parse(ParseError::Invalid(msg)))`.
#[inline(always)]
fn invalid<T>(msg: impl Into<String>) -> Result<T> {
    Err(QueryError::Parse(ParseError::Invalid(msg.into())))
}

/// Wrap a `QueryNode` in a `Named` node if `name` is `Some`, otherwise return it as-is.
#[inline(always)]
fn maybe_named(node: QueryNode, name: Option<String>) -> QueryNode {
    match name {
        Some(n) => QueryNode::Named {
            name: n,
            query: Box::new(node),
        },
        None => node,
    }
}

/// Construct `Err(QueryError::Parse(ParseError::UnknownQueryType(name)))`.
#[inline(always)]
fn unknown_type<T>(name: impl Into<String>) -> Result<T> {
    Err(QueryError::Parse(ParseError::UnknownQueryType(name.into())))
}

