        ], "minimum_should_match": -1}}))
        {
            QueryNode::Bool {
                minimum_should_match,
                ..
            } => assert_eq!(minimum_should_match, Some(MinShouldMatch::Negative(1))),
            other => panic!("expected Bool, got {other:?}"),
        }
    }

