        let QueryNode::Bool {
            must,
            must_not,
            should,
            ..
        } = node
        else {
            panic!("expected Bool");
        };
        assert!(must_not.is_empty() && should.is_empty());
        assert_eq!(must.len(), 2);
        assert!(matches!(&must[0], QueryNode::Match { field, .. } if field == "msg"));
        let (field, gt, ..) = expect_range(must[1].clone());
        assert_eq!(field, "n");
        assert_eq!(gt, Some(json!(1)));
    }

