    // ── bool clause count (issue #122) ────────────────────────────────────

    fn bool_with_clauses(n: usize) -> serde_json::Value {
        let clauses: Vec<serde_json::Value> = (0..n)
            .map(|i| json!({ "term": { format!("f{i}"): format!("v{i}") } }))
            .collect();
        json!({ "bool": { "should": clauses } })
    }

    /// `MAX_QUERY_DEPTH` bounds how deep a query nests; nothing bounded how
    /// wide it is. Width is what multiplies per-document work: with no
    /// compiled-script cache in the engine, N script clauses over D documents
    /// is N x D full script parses, and the clause count is the only place
    /// that product can be bounded before any of it happens.
    #[test]
    fn a_bool_query_may_not_carry_unbounded_clauses() {
        let err = parse_query(&bool_with_clauses(MAX_CLAUSE_COUNT + 1))
            .expect_err("an over-wide bool must be refused");
        assert!(
            err.to_string().contains("too_many_clauses"),
            "the error must be ES's own, got {err}"
        );
    }

    /// Exactly at the cap still parses — the limit is a cap, not an off-by-one
    /// haircut on legitimate queries.
    #[test]
    fn a_bool_query_at_the_clause_cap_still_parses() {
        parse_query(&bool_with_clauses(MAX_CLAUSE_COUNT))
            .expect("a query at exactly the cap must parse");
    }

    /// The width is the whole query's, not one `bool`'s: two sibling bools of
    /// 600 clauses each are 1,200 clauses of work however they are spelled.
    #[test]
    fn the_clause_cap_is_summed_across_sibling_bools() {
        let query = json!({
            "bool": {
                "must": [ bool_with_clauses(600), bool_with_clauses(600) ]
            }
        });
        let err = parse_query(&query).expect_err("1,200 clauses must be refused");
        assert!(err.to_string().contains("too_many_clauses"), "got {err}");
    }

    /// The counter is a thread-local, so a rejected query must not poison the
    /// next request that happens to land on the same worker.
    #[test]
    fn a_rejected_query_does_not_poison_the_next_one() {
        let _ = parse_query(&bool_with_clauses(MAX_CLAUSE_COUNT + 1));
        parse_query(&bool_with_clauses(8))
            .expect("an ordinary query after a rejected one must still parse");
    }

    /// Span clause lists, `dis_max.queries` and an array `knn.filter` are all
    /// clause lists under other names, and all count towards the same width.
    /// The cap is exercised through each of them — together with the refusal
    /// semantics that go with it — in `tests/span_clause_refusal.rs`, which
    /// survives a revert of this file and so can show what the fix is worth.
    #[test]
    fn the_cap_is_reachable_through_every_clause_list_shape() {
        let wide: Vec<serde_json::Value> = (0..MAX_CLAUSE_COUNT + 1)
            .map(|i| json!({ "term": { "f": format!("v{i}") } }))
            .collect();
        for query in [
            json!({ "span_or": { "clauses": wide } }),
            json!({ "dis_max": { "queries": wide } }),
            json!({ "knn": {
                "field": "vec", "query_vector": [0.1, 0.2], "k": 3, "filter": wide
            }}),
        ] {
            let err = parse_query(&query).expect_err("an over-wide clause list must be refused");
            assert!(err.to_string().contains("too_many_clauses"), "got {err}");
        }
    }

    /// Regression for the crash the `query_string` fuzz target found (#207).
    ///
    /// The tokeniser walks bytes and slices `&q[start..i]` as a `&str`, and it
    /// used to break on `is_whitespace()` — which is true for Latin-1 NBSP
    /// (0xA0). In valid UTF-8 that byte is only ever a *continuation* byte, so
    /// `_٠` (U+0660, encoded D9 A0) stopped the scan between the two bytes and
    /// the slice panicked on a character boundary. `query_string` is reachable
    /// unauthenticated from a request body and from `?q=`, and the release
    /// profile sets `panic = "abort"` — so this was the process, not a 400.
    ///
    /// Before the fix these abort the test process rather than failing.
    #[test]
    fn a_non_ascii_query_string_is_parsed_or_refused_but_never_panics() {
        // The character libFuzzer landed on, plus other multi-byte widths and
        // the two bytes `is_whitespace()` used to accept (0x85, 0xA0).
        for query in [
            "?:\"i(`:\"||+(l0O)_\u{660}\u{556}_ti(?:\"kk:))",
            "_\u{660}",
            "\u{660}",
            "a\u{660}b c",
            "field:\u{660}",
            "field:>\u{660}",
            "field:[\u{660} TO \u{661}]",
            "\u{4e2d}\u{6587} AND \u{e9}t\u{e9}",
            "caf\u{e9}\u{85}bar",
            "caf\u{e9}\u{a0}bar",
            "\u{1f600}",
        ] {
            for body in [
                json!({ "query_string": { "query": query, "default_field": "body" } }),
                json!({ "query_string": { "query": query } }),
                json!({ "simple_query_string": { "query": query } }),
            ] {
                // Parsing may fail. It may not take the process with it.
                let _ = parse_query(&body);
            }
        }

        // ASCII query strings still parse to the same shapes.
        let node = q(json!({
            "query_string": { "query": "title:quick AND body:fox", "default_field": "body" }
        }));
        assert!(
            matches!(node, QueryNode::Bool { .. }),
            "an ordinary fielded query_string must still lower to a bool: {node:?}"
        );
    }

    // ── Capability manifest (issue #211) ─────────────────────────────────────

    /// Names in `parse_query`'s dispatch table, read out of this file's own
    /// source at compile time.
    ///
    /// A pattern line is one whose text before `=>` is nothing but quoted
    /// string literals, `|` and whitespace — which is true of every match arm
    /// head and of no arm body, so no marker comments are needed and nothing
    /// has to be kept in sync by hand. The scan is bounded by the `match` head
    /// and the catch-all arm that closes it.
    fn dispatch_table_names() -> Vec<String> {
        const SRC: &str = include_str!("parser.rs");
        const START: &str = "match query_type.as_str() {";
        const END: &str = "unknown => unknown_type(unknown),";

        let start = SRC.find(START).expect("parse_query dispatch head moved") + START.len();
        let end = SRC[start..]
            .find(END)
            .expect("parse_query catch-all arm moved")
            + start;

        let mut names = Vec::new();
        for line in SRC[start..end].lines() {
            let code = line.split("//").next().unwrap_or("");
            let head = code.split("=>").next().unwrap_or("");
            if !head.contains('"') {
                continue;
            }
            // Everything that is not a string literal must be `|`/whitespace,
            // otherwise this is an arm body that merely mentions a literal.
            let mut literals = Vec::new();
            let mut rest = String::new();
            let mut in_str = false;
            let mut current = String::new();
            for ch in head.chars() {
                match (ch, in_str) {
                    ('"', false) => in_str = true,
                    ('"', true) => {
                        in_str = false;
                        literals.push(std::mem::take(&mut current));
                    }
                    (c, true) => current.push(c),
                    (c, false) => rest.push(c),
                }
            }
            if in_str || rest.chars().any(|c| c != '|' && !c.is_whitespace()) {
                continue;
            }
            names.extend(literals);
        }
        names
    }

    /// The drift guard. `SUPPORTED_QUERY_TYPES` + `REJECTED_QUERY_TYPES` must
    /// be exactly the dispatch table — no more, no less.
    ///
    /// Without this, adding a `parse_query` arm leaves every published list
    /// silently short (the pipeline-aggregation half of issue #211) and
    /// deleting one leaves them advertising a query that 400s.
    #[test]
    fn dispatch_table_matches_capability_manifest() {
        use std::collections::BTreeSet;

        let dispatched: BTreeSet<String> = dispatch_table_names().into_iter().collect();
        assert!(
            dispatched.len() > 40,
            "scraper found only {} arms — the dispatch table shape changed and the \
             scan is silently under-reading it",
            dispatched.len()
        );

        let supported: BTreeSet<String> = SUPPORTED_QUERY_TYPES
            .iter()
            .map(|s| s.to_string())
            .collect();
        let rejected: BTreeSet<String> =
            REJECTED_QUERY_TYPES.iter().map(|s| s.to_string()).collect();
        assert_eq!(
            supported.len(),
            SUPPORTED_QUERY_TYPES.len(),
            "SUPPORTED_QUERY_TYPES contains duplicates"
        );
        assert!(
            supported.is_disjoint(&rejected),
            "a query type cannot be both supported and rejected: {:?}",
            supported.intersection(&rejected).collect::<Vec<_>>()
        );

        let manifest: BTreeSet<String> = supported.union(&rejected).cloned().collect();
        let missing: Vec<_> = dispatched.difference(&manifest).collect();
        let extra: Vec<_> = manifest.difference(&dispatched).collect();
        assert!(
            missing.is_empty() && extra.is_empty(),
            "capability manifest has drifted from parse_query's dispatch table.\n  \
             dispatched but not in the manifest: {missing:?}\n  \
             in the manifest but not dispatched: {extra:?}\n  \
             Fix SUPPORTED_QUERY_TYPES / REJECTED_QUERY_TYPES in this file; the \
             docs are checked against them by xerj-engine/tests/docs_capability_lists.rs."
        );
    }

    /// Behavioural half: the manifest's two halves must actually behave the
    /// way they are labelled — in **both** directions. A supported type must
    /// neither answer `unknown query type` nor refuse with a `not supported`
    /// message, and a rejected type must refuse with exactly that message.
    /// Checking only the first of those let a recognised-and-refused type be
    /// relabelled supported with the whole manifest suite green.
    #[test]
    fn manifest_labels_match_observed_behaviour() {
        // `{ "<type>": {} }` — the minimal body that reaches the dispatch arm.
        // Most arms then reject it for missing parameters; what matters here is
        // only whether the *type* was recognised.
        fn bare(name: &str) -> Value {
            let mut obj = serde_json::Map::new();
            obj.insert(name.to_string(), json!({}));
            Value::Object(obj)
        }

        for name in SUPPORTED_QUERY_TYPES {
            let err = parse_query(&bare(name)).err();
            if let Some(QueryError::Parse(ParseError::UnknownQueryType(t))) = &err {
                panic!(
                    "`{name}` is listed as supported but parse_query rejects it as unknown: {t}"
                );
            }
            // The unknown-query-type check alone does not prove the *supported*
            // label: a type that is recognised and then refused with a 400 —
            // exactly what `has_child` does — never produces
            // `UnknownQueryType`, so moving it into SUPPORTED_QUERY_TYPES used
            // to pass here and then oblige the docs guard to publish it as a
            // capability. That is the #211 defect in the direction this test
            // exists to catch, so the refusal wording is checked too: the
            // phrase REJECTED_QUERY_TYPES is required to carry is the phrase
            // SUPPORTED_QUERY_TYPES is forbidden to carry.
            if let Some(e) = &err {
                let msg = e.to_string();
                assert!(
                    !msg.contains("not supported"),
                    "`{name}` is listed as supported but refuses with a not-supported \
                     message: {msg}\n  A recognised-and-refused type belongs in \
                     REJECTED_QUERY_TYPES, or the docs will advertise a query that 400s."
                );
            }
        }
        for name in REJECTED_QUERY_TYPES {
            let err = parse_query(&bare(name))
                .err()
                .unwrap_or_else(|| panic!("`{name}` is listed as rejected but parsed cleanly"));
            assert!(
                err.to_string().contains("not supported"),
                "`{name}` must refuse with an explanatory message, got: {err}"
            );
        }
    }

    // ── #1751: simple_query_string standalone and infix operators ──────────────

    #[test]
    fn simple_query_string_honors_operators_grouping_and_phrases() {
        // `fox | bear` under `default_operator: and` must be OR (should clauses).
        let node = q(json!({
            "simple_query_string": {
                "query": "fox | bear",
                "fields": ["title"],
                "default_operator": "and"
            }
        }));
        match node {
            QueryNode::Bool {
                should,
                must,
                minimum_should_match,
                ..
            } => {
                assert!(
                    must.is_empty(),
                    "must be empty under OR conjunction: {must:?}"
                );
                assert_eq!(should.len(), 2);
                assert_eq!(minimum_should_match, Some(MinShouldMatch::Fixed(1)));
            }
            other => panic!("expected Bool, got {other:?}"),
        }

        // `fox + lazy` under default operator must be AND (must clauses).
        let node = q(json!({
            "simple_query_string": {
                "query": "fox + lazy",
                "fields": ["title"]
            }
        }));
        match node {
            QueryNode::Bool { must, should, .. } => {
                assert_eq!(must.len(), 2, "both terms must be required: {must:?}");
                assert!(should.is_empty());
            }
            other => panic!("expected Bool, got {other:?}"),
        }

        // `"quick brown" | bear` under `default_operator: and` must produce MatchPhrase and Match in should.
        let node = q(json!({
            "simple_query_string": {
                "query": "\"quick brown\" | bear",
                "fields": ["title"],
                "default_operator": "and"
            }
        }));
        match node {
            QueryNode::Bool { should, must, .. } => {
                assert!(must.is_empty());
                assert_eq!(should.len(), 2);
                assert!(
                    matches!(&should[0], QueryNode::MatchPhrase { ref query, .. } if query == "quick brown")
                );
                assert!(
                    matches!(&should[1], QueryNode::Match { ref query, .. } if query == "bear")
                );
            }
            other => panic!("expected Bool, got {other:?}"),
        }

        // `(fox | bear) + brown` under `default_operator: and` must group (fox | bear) and require brown.
        let node = q(json!({
            "simple_query_string": {
                "query": "(fox | bear) + brown",
                "fields": ["title"],
                "default_operator": "and"
            }
        }));
        match node {
            QueryNode::Bool { must, .. } => {
                assert_eq!(must.len(), 2);
                assert!(
                    matches!(&must[0], QueryNode::Bool { ref should, .. } if should.len() == 2)
                );
                assert!(matches!(&must[1], QueryNode::Match { ref query, .. } if query == "brown"));
            }
            other => panic!("expected Bool, got {other:?}"),
        }

        // Negation with `-`
        let node = q(json!({
            "simple_query_string": {
                "query": "+fox -dog",
                "fields": ["title"]
            }
        }));
        match node {
            QueryNode::Bool { must, must_not, .. } => {
                assert_eq!(must.len(), 1);
                assert_eq!(must_not.len(), 1);
            }
            other => panic!("expected Bool, got {other:?}"),
        }

        // Resilient to trailing/standalone operators and unclosed quotes/parens
        let _ = q(json!({ "simple_query_string": { "query": "fox |" } }));
        let _ = q(json!({ "simple_query_string": { "query": "(fox | bear" } }));
        let _ = q(json!({ "simple_query_string": { "query": "\"unclosed phrase" } }));
        let _ = q(json!({ "simple_query_string": { "query": "++ -- ||" } }));
    }
}

//! Query planner — converts a [`QueryNode`] into an [`ExecutionPlan`].
//!
//! The planner answers: *given this query and the index schema, what is the
//! most efficient way to execute it?*
//!
//! ## Cost model (rough, unitless)
//!
//! | Operation | Estimated cost |
//! |---|---|
//! | `MatchAll` / doc scan | 1000 |
//! | `Term` / `Terms` | 1 |
//! | `Ids` | 0.5 |
//! | `Exists` | 2 |
//! | `Prefix` / `Wildcard` | 5 |
//! | `Range` | 3 |
//! | `Match` (FTS) | 5 × tokens |
//! | `MatchPhrase` | 8 |
//! | `MultiMatch` | 5 × fields × tokens |
//! | `QueryString` | 15 |
//! | `Knn` / `SemanticSearch` | 50 × k |
//! | `Bool` | sum of clause costs |
//! | `Constant` / `Boosted` | inner cost |
//! | `Hybrid` | sum of sub-query costs |
//!
//! These are intentionally approximate.  The real optimisation budget is in
//! the rewriter (constant folding, filter push-down) which runs before the
//! planner.

use tracing::trace;
use xerj_common::types::Schema;

use crate::ast::{MultiMatchType, QueryNode};
use crate::error::Result;

// ─────────────────────────────────────────────────────────────────────────────
// ExecutionPlan
// ─────────────────────────────────────────────────────────────────────────────

/// A physical execution plan node.
///
/// The planner maps each `QueryNode` variant to an appropriate plan node.
/// The executor then walks the plan tree to produce hits.
#[derive(Debug, Clone)]
pub enum ExecutionPlan {
    /// Return all documents in segment order (full scan).
    MatchAll,

    /// Return no documents.
    MatchNone,

    /// Term-level lookup via the inverted index.
    FtsScan {
        field: String,
        /// The term(s) to look up.  Single-element vec for `Term`; multi for `Terms`.
        terms: Vec<serde_json::Value>,
        /// Rough cost estimate.
        cost: f64,
    },

    /// Full-text search through the FTS engine (tokenised).
    FtsSearch {
        field: String,
        tokens: Vec<String>,
        require_all: bool,
        /// Phrase mode — tokens must appear within `slop` under Lucene
        /// move-distance semantics: forward gaps cost their width,
        /// transpositions/reorderings cost 2 (#830).
        phrase: bool,
        slop: u32,
        cost: f64,
    },

    /// Range query on a numeric / date / keyword field.
    RangeScan {
        field: String,
        gte: Option<serde_json::Value>,
        gt: Option<serde_json::Value>,
        lte: Option<serde_json::Value>,
        lt: Option<serde_json::Value>,
        cost: f64,
    },

    /// Prefix / wildcard scan via the FST.
    PrefixScan {
        field: String,
        prefix: String,
        wildcard: bool,
        cost: f64,
    },

    /// Existence filter — checks the null-bitmap.
    ExistsScan { field: String },

    /// Fetch by document IDs — direct random access.
    IdLookup { ids: Vec<String> },

    /// Dense-vector k-NN via the HNSW index.
    VectorScan {
        field: String,
        vector: Vec<f32>,
        k: usize,
        filter: Option<Box<ExecutionPlan>>,
        cost: f64,
    },

    /// Semantic (text → embedding → k-NN) search.
    SemanticScan {
        field: String,
        text: String,
        k: usize,
        filter: Option<Box<ExecutionPlan>>,
        cost: f64,
    },

    /// Boolean combination of sub-plans.
    BoolCombine {
        must: Vec<ExecutionPlan>,
        should: Vec<ExecutionPlan>,
        must_not: Vec<ExecutionPlan>,
        filter: Vec<ExecutionPlan>,
        minimum_should_match: Option<crate::ast::MinShouldMatch>,
        cost: f64,
    },

    /// Apply a fixed score to all hits from the inner plan.
    ConstantScore {
        score: f32,
        inner: Box<ExecutionPlan>,
        cost: f64,
    },

    /// Multiply hit scores by `boost`.
    Boost {
        boost: f32,
        inner: Box<ExecutionPlan>,
        cost: f64,
    },

    /// Merge results from multiple plans using a score-fusion strategy.
    HybridMerge {
        plans: Vec<(ExecutionPlan, f32)>,
        fusion: crate::ast::FusionStrategy,
        cost: f64,
    },
}

impl ExecutionPlan {
    /// Return the estimated cost of this plan node.
    pub fn cost(&self) -> f64 {
        match self {
            ExecutionPlan::MatchAll => 1000.0,
            ExecutionPlan::MatchNone => 0.0,
            ExecutionPlan::FtsScan { cost, .. } => *cost,
            ExecutionPlan::FtsSearch { cost, .. } => *cost,
            ExecutionPlan::RangeScan { cost, .. } => *cost,
            ExecutionPlan::PrefixScan { cost, .. } => *cost,
            ExecutionPlan::ExistsScan { .. } => 2.0,
            ExecutionPlan::IdLookup { ids } => ids.len() as f64 * 0.5,
            ExecutionPlan::VectorScan { cost, .. } => *cost,
            ExecutionPlan::SemanticScan { cost, .. } => *cost,
            ExecutionPlan::BoolCombine { cost, .. } => *cost,
            ExecutionPlan::ConstantScore { cost, .. } => *cost,
            ExecutionPlan::Boost { cost, .. } => *cost,
            ExecutionPlan::HybridMerge { cost, .. } => *cost,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Planner entry point
// ─────────────────────────────────────────────────────────────────────────────

/// Plan a (already-rewritten) query against the given schema.
///
/// The schema is used to pick the right scan strategy (e.g. use the BKD tree
/// for numeric ranges, use the vector index for `knn` fields).
pub fn plan_query(query: QueryNode, schema: &Schema) -> Result<ExecutionPlan> {
    let plan = plan_node(query, schema);
    trace!(cost = plan.cost(), "query plan created");
    Ok(plan)
}

// `schema` is threaded through only so recursive sub-plans can consult it;
// the current arms don't read it directly, so silence the recursion lint.
#[allow(clippy::only_used_in_recursion)]
fn plan_node(query: QueryNode, schema: &Schema) -> ExecutionPlan {
    match query {
        QueryNode::MatchAll => ExecutionPlan::MatchAll,
        QueryNode::MatchNone => ExecutionPlan::MatchNone,

        QueryNode::Term { field, value, .. } => ExecutionPlan::FtsScan {
            cost: 1.0,
            terms: vec![value],
            field,
        },

        QueryNode::Terms { field, values, .. } => {
            let cost = values.len() as f64;
            ExecutionPlan::FtsScan {
                field,
                terms: values,
                cost,
            }
        }

        QueryNode::Ids { values } => ExecutionPlan::IdLookup { ids: values },

        QueryNode::Exists { field } => ExecutionPlan::ExistsScan { field },

        QueryNode::Range {
            field,
            gte,
            gt,
            lte,
            lt,
            ..
        } => ExecutionPlan::RangeScan {
            field,
            gte,
            gt,
            lte,
            lt,
            cost: 3.0,
        },

        QueryNode::Prefix { field, value, .. } => ExecutionPlan::PrefixScan {
            field,
            prefix: value,
            wildcard: false,
            cost: 5.0,
        },

        QueryNode::Wildcard { field, value, .. } => ExecutionPlan::PrefixScan {
            field,
            prefix: value,
            wildcard: true,
            cost: 5.0,
        },

        QueryNode::Match {
            field,
            query,
            operator,
            ..
        } => {
            // Simple whitespace tokenisation for cost estimation.
            // Actual tokenisation happens in the FTS engine.
            let tokens: Vec<String> = query.split_whitespace().map(str::to_string).collect();
            let n = tokens.len().max(1);
            let require_all = matches!(operator, crate::ast::BoolOperator::And);
            ExecutionPlan::FtsSearch {
                field,
                tokens,
                require_all,
                phrase: false,
                slop: 0,
                cost: 5.0 * n as f64,
            }
        }

        QueryNode::MatchPhrase {
            field, query, slop, ..
        } => {
            let tokens: Vec<String> = query.split_whitespace().map(str::to_string).collect();
            ExecutionPlan::FtsSearch {
                cost: 8.0,
                field,
                tokens,
                require_all: true,
                phrase: true,
                slop,
            }
        }

        QueryNode::MultiMatch {
            fields,
            query,
            match_type,
            slop,
            ..
        } => {
            // Expand to a Bool(should=[ Match(field, query) for field in fields ])
            // and plan that.
            let tokens: Vec<String> = query.split_whitespace().map(str::to_string).collect();
            let n = tokens.len().max(1);
            let phrase = matches!(
                match_type,
                MultiMatchType::Phrase | MultiMatchType::PhrasePrefix
            );
            let cost = 5.0 * fields.len() as f64 * n as f64;

            // `slop` only means anything for a phrase (issue #230); the
            // field-centric types ignore it, as ES does.
            let plan_slop = if phrase { slop } else { 0 };
            let sub_plans: Vec<ExecutionPlan> = fields
                .into_iter()
                .map(|field| ExecutionPlan::FtsSearch {
                    field,
                    tokens: tokens.clone(),
                    require_all: false,
                    phrase,
                    slop: plan_slop,
                    cost: 5.0 * n as f64,
                })
                .collect();

            ExecutionPlan::BoolCombine {
                must: vec![],
                should: sub_plans,
                must_not: vec![],
                filter: vec![],
                minimum_should_match: None,
                cost,
            }
        }

        QueryNode::QueryString { query, .. } => {
            // Fallback only: the common case is lowered into a Bool tree by
            // try_lower_query_string (parser.rs), so this branch is reached
            // only for inputs that could not be translated. Split the raw
            // query on whitespace and OR the tokens across `_all` rather than
            // searching for the entire raw string as one opaque token (which
            // would never match). This is an approximation — operators
            // (AND/OR/NOT, +/-, parens, phrases, field:value) are not honored
            // on this path — but it yields sensible hits instead of none.
            let tokens: Vec<String> = query.split_whitespace().map(str::to_string).collect();
            let cost = 15.0 * tokens.len().max(1) as f64;
            ExecutionPlan::FtsSearch {
                field: "_all".to_string(),
                tokens,
                require_all: false,
                phrase: false,
                slop: 0,
                cost,
            }
        }

        QueryNode::Bool {
            must,
            should,
            must_not,
            filter,
            minimum_should_match,
        } => {
            // Plan each clause, then sort must/should by cost (cheapest first).
            let plan_list = |clauses: Vec<QueryNode>| {
                let mut plans: Vec<ExecutionPlan> =
                    clauses.into_iter().map(|q| plan_node(q, schema)).collect();
                plans.sort_by(|a, b| a.cost().partial_cmp(&b.cost()).unwrap());
                plans
            };

            let must_plans = plan_list(must);
            let should_plans = plan_list(should);
            let must_not_plans = plan_list(must_not);
            let filter_plans = plan_list(filter);

            let cost = must_plans.iter().map(|p| p.cost()).sum::<f64>()
                + should_plans.iter().map(|p| p.cost()).sum::<f64>()
                + filter_plans.iter().map(|p| p.cost()).sum::<f64>();

            ExecutionPlan::BoolCombine {
                must: must_plans,
                should: should_plans,
                must_not: must_not_plans,
                filter: filter_plans,
                minimum_should_match,
                cost,
            }
        }

        QueryNode::Constant { score, query } => {
            let inner = plan_node(*query, schema);
            let cost = inner.cost();
            ExecutionPlan::ConstantScore {
                score,
                inner: Box::new(inner),
                cost,
            }
        }

        QueryNode::Boosted { boost, query } => {
            let inner = plan_node(*query, schema);
            let cost = inner.cost();
            ExecutionPlan::Boost {
                boost,
                inner: Box::new(inner),
                cost,
            }
        }

        QueryNode::Knn {
            field,
            vector,
            k,
            filter,
            ..
        } => {
            let filter_plan = filter.map(|f| Box::new(plan_node(*f, schema)));
            let cost = 50.0 * k as f64;
            ExecutionPlan::VectorScan {
                field,
                vector,
                k,
                filter: filter_plan,
                cost,
            }
        }

        QueryNode::SemanticSearch {
            field,
            text,
            k,
            filter,
            ..
        } => {
            let filter_plan = filter.map(|f| Box::new(plan_node(*f, schema)));
            let cost = 50.0 * k as f64 + 20.0; // +20 for embedding inference
            ExecutionPlan::SemanticScan {
                field,
                text,
                k,
                filter: filter_plan,
                cost,
            }
        }

        QueryNode::Hybrid { queries, fusion } => {
            let mut total_cost = 0.0;
            let plans: Vec<(ExecutionPlan, f32)> = queries
                .into_iter()
                .map(|wq| {
                    let p = plan_node(wq.query, schema);
                    total_cost += p.cost();
                    (p, wq.weight)
                })
                .collect();
            ExecutionPlan::HybridMerge {
                plans,
                fusion,
                cost: total_cost,
            }
        }

        // Boosting: plan the positive sub-query; negative is evaluated at score time.
        QueryNode::Boosting {
            positive,
            negative,
            negative_boost,
        } => {
            let pos_plan = plan_node(*positive, schema);
            let neg_plan = plan_node(*negative, schema);
            let cost = pos_plan.cost() + neg_plan.cost();
            // Represent as a Bool must + boosted should for the planner.
            ExecutionPlan::BoolCombine {
                must: vec![pos_plan],
                should: vec![ExecutionPlan::Boost {
                    boost: negative_boost,
                    inner: Box::new(neg_plan),
                    cost: 0.0,
                }],
                must_not: vec![],
                filter: vec![],
                minimum_should_match: None,
                cost,
            }
        }

        // DisMax: plan all sub-queries; execution picks the max score.
        QueryNode::DisMax { queries, .. } => {
            let mut total_cost = 0.0;
            let sub_plans: Vec<ExecutionPlan> = queries
                .into_iter()
                .map(|q| {
                    let p = plan_node(q, schema);
                    total_cost += p.cost();
                    p
                })
                .collect();
            // Treat like a Bool-should for planning purposes.
            ExecutionPlan::BoolCombine {
                must: vec![],
                should: sub_plans,
                must_not: vec![],
                filter: vec![],
                minimum_should_match: Some(crate::ast::MinShouldMatch::Fixed(1)),
                cost: total_cost,
            }
        }

        // Fuzzy: treat as a term scan with higher cost due to edit-distance computation.
        QueryNode::Fuzzy { field, value, .. } => ExecutionPlan::FtsScan {
            field,
            terms: vec![serde_json::Value::String(value)],
            cost: 10.0,
        },

        // Regexp: full scan cost since we must evaluate each doc.
        QueryNode::Regexp { field, pattern, .. } => ExecutionPlan::FtsScan {
            field,
            terms: vec![serde_json::Value::String(pattern)],
            cost: 20.0,
        },

        // Intervals: position-aware text match. Plan as an exists-scan
        // on the field — the doc-scan executor evaluates the rule
        // directly against tokens (see engine::doc_matches_query).
        QueryNode::Intervals { field, .. } => ExecutionPlan::ExistsScan { field },

        // MatchPhrasePrefix: treat as a phrase search on the given field.
        QueryNode::MatchPhrasePrefix {
            field, query, slop, ..
        } => {
            let tokens: Vec<String> = query.split_whitespace().map(str::to_string).collect();
            ExecutionPlan::FtsSearch {
                field,
                tokens,
                require_all: true,
                phrase: true,
                slop,
                cost: 10.0,
            }
        }

        // SimpleQueryString: resolved to Bool at parse time; fallback to full scan.
        QueryNode::SimpleQueryString { query, .. } => ExecutionPlan::FtsSearch {
            field: "_all".to_string(),
            tokens: vec![query],
            require_all: false,
            phrase: false,
            slop: 0,
            cost: 15.0,
        },

        // GeoDistance: full doc-scan with per-doc haversine computation.
        QueryNode::GeoDistance { field, .. } => ExecutionPlan::ExistsScan { field },

        // GeoBoundingBox: full doc-scan with per-doc bounding box check.
        QueryNode::GeoBoundingBox { field, .. } => ExecutionPlan::ExistsScan { field },

        // FunctionScore: plan the inner query; function application happens at score time.
        QueryNode::FunctionScore { query, .. } => {
            let inner = plan_node(*query, schema);
            let cost = inner.cost() + 5.0; // small overhead for function application
            ExecutionPlan::Boost {
                boost: 1.0,
                inner: Box::new(inner),
                cost,
            }
        }

        // Nested: plan the inner query with a doc-scan cost.
        QueryNode::Nested { query, .. } => {
            let inner = plan_node(*query, schema);
            let cost = inner.cost() + 10.0; // array traversal overhead
            ExecutionPlan::Boost {
                boost: 1.0,
                inner: Box::new(inner),
                cost,
            }
        }

        // MoreLikeThis: treat as a multi-term FTS search.
        QueryNode::MoreLikeThis { like, .. } => {
            let all_text = like.join(" ");
            let tokens: Vec<String> = all_text.split_whitespace().map(str::to_string).collect();
            let cost = 5.0 * tokens.len().max(1) as f64;
            ExecutionPlan::FtsSearch {
                field: "_all".to_string(),
                tokens,
                require_all: false,
                phrase: false,
                slop: 0,
                cost,
            }
        }

        // Pinned: plan the organic query; pinned ID boosting happens at score time.
        QueryNode::Pinned { organic, ids } => {
            // Include the organic plan plus an id-lookup for the pinned IDs.
            let organic_plan = plan_node(*organic, schema);
            let pin_cost = ids.len() as f64 * 0.5;
            let total_cost = organic_plan.cost() + pin_cost;
            ExecutionPlan::BoolCombine {
                must: vec![],
                should: vec![organic_plan, ExecutionPlan::IdLookup { ids }],
                must_not: vec![],
                filter: vec![],
                minimum_should_match: None,
                cost: total_cost,
            }
        }

        // Named: plan the inner query; name annotation has no effect on planning.
        QueryNode::Named { query, .. } => plan_node(*query, schema),

        // Percolate: pure doc-scan (reverse match). The plan is ignored by the
        // engine's doc-scan path; MatchAll satisfies exhaustiveness here.
        QueryNode::Percolate { .. } => ExecutionPlan::MatchAll,

        // Script: no index can back an arbitrary Painless predicate — pure
        // doc-scan, same as Percolate above.
        QueryNode::Script { .. } => ExecutionPlan::MatchAll,

        // ── Span queries — treat as doc-scans ────────────────────────────────
        QueryNode::SpanTerm { field, value } => ExecutionPlan::FtsScan {
            field,
            terms: vec![serde_json::Value::String(value)],
            cost: 2.0,
        },

        QueryNode::SpanNear { clauses, .. } => {
            let sub_plans: Vec<ExecutionPlan> =
                clauses.into_iter().map(|q| plan_node(q, schema)).collect();
            let cost = sub_plans.iter().map(|p| p.cost()).sum::<f64>() + 5.0;
            ExecutionPlan::BoolCombine {
                must: sub_plans,
                should: vec![],
                must_not: vec![],
                filter: vec![],
                minimum_should_match: None,
                cost,
            }
        }

        QueryNode::SpanOr { clauses } => {
            let sub_plans: Vec<ExecutionPlan> =
                clauses.into_iter().map(|q| plan_node(q, schema)).collect();
            let cost = sub_plans.iter().map(|p| p.cost()).sum::<f64>();
            ExecutionPlan::BoolCombine {
                must: vec![],
                should: sub_plans,
                must_not: vec![],
                filter: vec![],
                minimum_should_match: Some(crate::ast::MinShouldMatch::Fixed(1)),
                cost,
            }
        }

        QueryNode::SpanNot { include, exclude } => {
            let inc = plan_node(*include, schema);
            let exc = plan_node(*exclude, schema);
            let cost = inc.cost() + exc.cost();
            ExecutionPlan::BoolCombine {
                must: vec![inc],
                should: vec![],
                must_not: vec![exc],
                filter: vec![],
                minimum_should_match: None,
                cost,
            }
        }

        QueryNode::SpanFirst { match_query, .. } => plan_node(*match_query, schema),

        // span_containing / span_within are pure doc-scans (enclosure test);
        // the plan is ignored by the doc-scan path. Plan the `big` clause so
        // any field annotation is preserved for cost estimation.
        QueryNode::SpanContaining { big, .. } | QueryNode::SpanWithin { big, .. } => {
            plan_node(*big, schema)
        }

        // ── Geo shape queries — treat as doc-scans ────────────────────────────
        QueryNode::GeoPolygon { field, .. } => ExecutionPlan::ExistsScan { field },
        QueryNode::GeoShape { field, .. } => ExecutionPlan::ExistsScan { field },
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use xerj_common::types::Schema;

    fn empty_schema() -> Schema {
        Schema::empty()
    }

    fn term_node(field: &str, val: &str) -> QueryNode {
        QueryNode::Term {
            field: field.to_string(),
            value: serde_json::json!(val),
            boost: None,
        }
    }

    #[test]
    fn test_plan_match_all() {
        let plan = plan_query(QueryNode::MatchAll, &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::MatchAll));
    }

    #[test]
    fn test_plan_match_none() {
        let plan = plan_query(QueryNode::MatchNone, &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::MatchNone));
    }

    #[test]
    fn test_plan_term() {
        let plan = plan_query(term_node("status", "active"), &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::FtsScan { cost, .. } if cost == 1.0));
    }

    #[test]
    fn test_plan_terms() {
        let q = QueryNode::Terms {
            field: "tag".to_string(),
            values: vec![
                serde_json::json!("rust"),
                serde_json::json!("go"),
                serde_json::json!("zig"),
            ],
            boost: None,
        };
        let plan = plan_query(q, &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::FtsScan { cost, .. } if cost == 3.0));
    }

    #[test]
    fn test_plan_range() {
        let q = QueryNode::Range {
            field: "age".to_string(),
            gte: Some(serde_json::json!(18)),
            gt: None,
            lte: None,
            lt: Some(serde_json::json!(65)),
            boost: None,
            lenient: false,
        };
        let plan = plan_query(q, &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::RangeScan { .. }));
    }

    #[test]
    fn test_plan_bool_orders_by_cost() {
        // must=[knn(cost=500), term(cost=1)] → term should come first
        let q = QueryNode::Bool {
            must: vec![
                QueryNode::Knn {
                    field: "vec".to_string(),
                    vector: vec![0.1],
                    k: 10,
                    num_candidates: None,
                    filter: None,
                    boost: None,
                    similarity: None,
                },
                term_node("status", "ok"),
            ],
            should: vec![],
            must_not: vec![],
            filter: vec![],
            minimum_should_match: None,
        };
        let plan = plan_query(q, &empty_schema()).unwrap();
        if let ExecutionPlan::BoolCombine { must, .. } = plan {
            assert_eq!(must.len(), 2);
            // term (cost=1) should be cheaper than knn (cost=500)
            assert!(must[0].cost() < must[1].cost());
        } else {
            panic!("expected BoolCombine");
        }
    }

    #[test]
    fn test_plan_constant_score() {
        let q = QueryNode::Constant {
            score: 1.5,
            query: Box::new(term_node("status", "active")),
        };
        let plan = plan_query(q, &empty_schema()).unwrap();
        assert!(
            matches!(plan, ExecutionPlan::ConstantScore { score, .. } if (score - 1.5).abs() < 0.001)
        );
    }

    #[test]
    fn test_plan_knn() {
        let q = QueryNode::Knn {
            field: "embedding".to_string(),
            vector: vec![0.1, 0.2, 0.3],
            k: 20,
            num_candidates: None,
            filter: None,
            boost: None,
            similarity: None,
        };
        let plan = plan_query(q, &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::VectorScan { k: 20, .. }));
    }

    #[test]
    fn test_plan_hybrid() {
        let q = QueryNode::Hybrid {
            queries: vec![
                crate::ast::WeightedQuery {
                    query: term_node("x", "y"),
                    weight: 0.5,
                },
                crate::ast::WeightedQuery {
                    query: QueryNode::Knn {
                        field: "vec".to_string(),
                        vector: vec![1.0],
                        k: 5,
                        num_candidates: None,
                        filter: None,
                        boost: None,
                        similarity: None,
                    },
                    weight: 0.5,
                },
            ],
            fusion: crate::ast::FusionStrategy::Rrf { k: 60 },
        };
        let plan = plan_query(q, &empty_schema()).unwrap();
        assert!(matches!(plan, ExecutionPlan::HybridMerge { .. }));
    }
}

//! Sort field representation and comparison utilities.
//!
//! xerj supports the same sort syntax as Elasticsearch:
//!
//! ```json
//! "sort": [
//!   { "date": "desc" },
//!   { "price": { "order": "asc", "mode": "avg", "missing": "_last" } },
//!   "_score"
//! ]
//! ```
//!
//! A missing `sort` defaults to `_score` descending.

use serde::{Deserialize, Serialize};

// ─────────────────────────────────────────────────────────────────────────────
// SortField
// ─────────────────────────────────────────────────────────────────────────────

/// A single sort criterion.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SortField {
    /// The field name, or `_score` / `_doc` for the built-in sort keys.
    pub field: String,
    /// Ascending or descending.
    pub order: SortOrder,
    /// How to pick a value when a document has multiple values for the field.
    pub mode: SortMode,
    /// What to do with documents that are missing the field.
    pub missing: SortMissing,
    /// Optional ES sort-value format override (e.g. `strict_date_optional_time_nanos`).
    /// When set, the emitted `sort` array uses the formatted string rather
    /// than the raw numeric epoch that the engine produces by default.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub format: Option<String>,
    /// ES `unmapped_type`: when set, sorting a field that has no mapping is not
    /// an error — every document is treated as missing (ES semantics). The
    /// unresolvable-field guard skips a field carrying this, so a client that
    /// asks for `unmapped_type` (e.g. a cross-index sort, or a query written to
    /// survive a schema that predates the field) is not rejected.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub unmapped_type: Option<String>,
    /// ES `numeric_type`: force the numeric type the sort VALUES are produced
    /// in, independently of how the field is mapped in each index.
    ///
    /// This is what makes a cross-index sort over a field mapped `date` in one
    /// index and `date_nanos` in another comparable at all: without it ES (and
    /// xerj) compares the raw longs, so an epoch-nanosecond key always sorts
    /// above every epoch-millisecond key rather than interleaving with it
    /// (`search/240_date_nanos.yml` pins exactly that default). xerj implements
    /// the two date values — `date` pins the sort to epoch-MILLISECONDS,
    /// `date_nanos` to epoch-NANOSECONDS, for every participating index (#889).
    ///
    /// `long` / `double` are parsed and then ignored: xerj already compares
    /// numeric sort keys as `f64`, so there is nothing to convert. Unlike ES,
    /// xerj does not reject `numeric_type` on a non-numeric field.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub numeric_type: Option<String>,
}

impl SortField {
    /// The default sort: `_score` descending.
    pub fn score_desc() -> Self {
        Self {
            field: "_score".to_string(),
            order: SortOrder::Desc,
            mode: SortMode::default(),
            missing: SortMissing::default(),
            format: None,
            unmapped_type: None,
            numeric_type: None,
        }
    }

    /// Physical document order — cheapest possible sort for scroll / scan.
    pub fn doc_asc() -> Self {
        Self {
            field: "_doc".to_string(),
            order: SortOrder::Asc,
            mode: SortMode::default(),
            missing: SortMissing::default(),
            format: None,
            unmapped_type: None,
            numeric_type: None,
        }
    }

    /// Returns `true` if this sort field is the relevance score.
    pub fn is_score(&self) -> bool {
        self.field == "_score"
    }

    /// Returns `true` if this sorts by internal document order.
    pub fn is_doc_order(&self) -> bool {
        self.field == "_doc"
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// SortOrder
// ─────────────────────────────────────────────────────────────────────────────

/// Sort direction.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum SortOrder {
    /// Smallest first (natural order for numbers, lexicographic for strings).
    Asc,
    /// Largest first.  Default for `_score`.
    #[default]
    Desc,
}

impl SortOrder {
    /// Flip the direction.
    pub fn reverse(self) -> Self {
        match self {
            SortOrder::Asc => SortOrder::Desc,
            SortOrder::Desc => SortOrder::Asc,
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// SortMode
// ─────────────────────────────────────────────────────────────────────────────

/// How to handle multi-valued fields in sort comparisons.
///
/// ES documentation: when a document has multiple values for the sort field,
/// the engine picks one representative value for the comparison according to
/// this mode.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum SortMode {
    /// No explicit `mode` was requested. ES then picks the `min` value for an
    /// ascending sort and the `max` value for a descending one — see
    /// `effective(order)`. Kept distinct from an explicit `min`/`max` so that
    /// `{"order":"desc"}` (no mode) resolves to `max`, not the enum default.
    #[default]
    Default,
    /// Use the minimum value across all field values.
    Min,
    /// Use the maximum value across all field values.
    Max,
    /// Use the arithmetic mean.
    Avg,
    /// Use the sum (only meaningful for numeric fields).
    Sum,
    /// Use the median.
    Median,
}

impl SortMode {
    /// Resolve the effective reduction for a multi-valued field, applying ES's
    /// order-based default (`asc` -> min, `desc` -> max) when no explicit mode
    /// was given. An explicit mode is honoured regardless of order.
    pub fn effective(self, order: SortOrder) -> SortMode {
        match self {
            SortMode::Default => match order {
                SortOrder::Asc => SortMode::Min,
                SortOrder::Desc => SortMode::Max,
            },
            other => other,
        }
    }
}

/// Reduce a (possibly multi-valued) sort field value to the single
/// representative value ES would compare, per the sort `mode` and `order`.
///
/// A non-array value is returned unchanged. `null` array entries are ignored
/// (ES skips them when selecting the representative); an array that is empty or
/// all-null reduces to `Null`, so the request's `missing` policy governs it.
/// `min`/`max` use the same numbers-then-strings ordering as the sort
/// comparator; `avg`/`sum`/`median` are numeric-only (non-numeric entries are
/// ignored, matching ES, which rejects them at mapping time).
pub fn reduce_sort_value(
    raw: &serde_json::Value,
    order: SortOrder,
    mode: SortMode,
) -> serde_json::Value {
    use serde_json::Value;
    let arr = match raw {
        Value::Array(a) => a,
        other => return other.clone(),
    };
    let vals: Vec<&Value> = arr.iter().filter(|v| !v.is_null()).collect();
    if vals.is_empty() {
        return Value::Null;
    }
    match mode.effective(order) {
        SortMode::Min => vals
            .iter()
            .copied()
            .min_by(|a, b| compare_values(a, b, &SortMissing::Last))
            .cloned()
            .unwrap_or(Value::Null),
        SortMode::Max => vals
            .iter()
            .copied()
            .max_by(|a, b| compare_values(a, b, &SortMissing::Last))
            .cloned()
            .unwrap_or(Value::Null),
        SortMode::Avg | SortMode::Sum | SortMode::Median => {
            let mut nums: Vec<f64> = vals.iter().filter_map(|v| v.as_f64()).collect();
            if nums.is_empty() {
                return Value::Null;
            }
            let out = match mode.effective(order) {
                SortMode::Sum => nums.iter().sum(),
                SortMode::Avg => nums.iter().sum::<f64>() / nums.len() as f64,
                SortMode::Median => {
                    nums.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                    let m = nums.len() / 2;
                    if nums.len() % 2 == 1 {
                        nums[m]
                    } else {
                        (nums[m - 1] + nums[m]) / 2.0
                    }
                }
                _ => unreachable!(),
            };
            serde_json::Number::from_f64(out)
                .map(Value::Number)
                .unwrap_or(Value::Null)
        }
        // `effective` never returns `Default`.
        SortMode::Default => Value::Null,
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// SortMissing
// ─────────────────────────────────────────────────────────────────────────────

/// Where to place documents that are missing the sort field.
///
/// Hand-rolled serialization: the default `#[serde(untagged)]` treatment
/// collapses the two unit variants (`Last` / `First`) to `null` on the
/// wire, which made the query cache hash the same bytes for
/// `missing:"_last"` and `missing:"_first"`. That caused
/// `search/630_format_sort_missing_dates.yml` to serve a stale
/// missing-Last result to a subsequent missing-First request.
#[derive(Debug, Clone, PartialEq, Default)]
pub enum SortMissing {
    /// Documents missing the field sort last (default).
    #[default]
    Last,
    /// Documents missing the field sort first.
    First,
    /// Use a concrete substitute value for comparison.
    Value(serde_json::Value),
}

impl Serialize for SortMissing {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        match self {
            SortMissing::Last => s.serialize_str("_last"),
            SortMissing::First => s.serialize_str("_first"),
            SortMissing::Value(v) => v.serialize(s),
        }
    }
}

impl<'de> Deserialize<'de> for SortMissing {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let v = serde_json::Value::deserialize(d)?;
        match v {
            serde_json::Value::String(s) if s == "_last" => Ok(SortMissing::Last),
            serde_json::Value::String(s) if s == "_first" => Ok(SortMissing::First),
            other => Ok(SortMissing::Value(other)),
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Sort key extraction helpers (used by executor)
// ─────────────────────────────────────────────────────────────────────────────

/// Compare two sort-key arrays lexicographically, respecting each field's
/// `SortOrder`.
///
/// Used by the executor's top-K heap to determine document ranking.
///
/// Returns `std::cmp::Ordering` — the caller decides whether to keep or
/// discard the candidate document based on its heap position.
pub fn compare_sort_keys(
    a: &[serde_json::Value],
    b: &[serde_json::Value],
    fields: &[SortField],
) -> std::cmp::Ordering {
    for (i, field) in fields.iter().enumerate() {
        let av = a.get(i).unwrap_or(&serde_json::Value::Null);
        let bv = b.get(i).unwrap_or(&serde_json::Value::Null);
        // ES `missing: _last` / `_first` is direction-stable: missing
        // values stay at the end (or start) regardless of asc/desc on
        // non-null values. Compute the directional comparison only on
        // non-null pairs and let the missing-policy short-circuit drive
        // null placement directly.
        let cmp = match (av, bv) {
            (serde_json::Value::Null, serde_json::Value::Null) => std::cmp::Ordering::Equal,
            (serde_json::Value::Null, _) => match field.missing {
                SortMissing::First => std::cmp::Ordering::Less,
                SortMissing::Last => std::cmp::Ordering::Greater,
                SortMissing::Value(_) => {
                    let raw = compare_values(av, bv, &field.missing);
                    if field.order == SortOrder::Desc {
                        raw.reverse()
                    } else {
                        raw
                    }
                }
            },
            (_, serde_json::Value::Null) => match field.missing {
                SortMissing::First => std::cmp::Ordering::Greater,
                SortMissing::Last => std::cmp::Ordering::Less,
                SortMissing::Value(_) => {
                    let raw = compare_values(av, bv, &field.missing);
                    if field.order == SortOrder::Desc {
                        raw.reverse()
                    } else {
                        raw
                    }
                }
            },
            (_, _) => {
                let raw = compare_values(av, bv, &field.missing);
                if field.order == SortOrder::Desc {
                    raw.reverse()
                } else {
                    raw
                }
            }
        };
        if cmp != std::cmp::Ordering::Equal {
            return cmp;
        }
    }
    std::cmp::Ordering::Equal
}

/// Compare two JSON values for sort purposes.
///
/// Null / missing values are handled per `missing` policy; non-null values
/// follow a consistent total order: numbers < strings < everything else.
fn compare_values(
    a: &serde_json::Value,
    b: &serde_json::Value,
    missing: &SortMissing,
) -> std::cmp::Ordering {
    use serde_json::Value::*;
    use std::cmp::Ordering::*;

    match (a, b) {
        (Null, Null) => Equal,
        (Null, _) => match missing {
            SortMissing::First => Less,
            SortMissing::Last => Greater,
            SortMissing::Value(v) => compare_values(v, b, &SortMissing::Last),
        },
        (_, Null) => match missing {
            SortMissing::First => Greater,
            SortMissing::Last => Less,
            SortMissing::Value(v) => compare_values(a, v, &SortMissing::Last),
        },
        (Number(an), Number(bn)) => {
            let af = an.as_f64().unwrap_or(f64::NAN);
            let bf = bn.as_f64().unwrap_or(f64::NAN);
            af.partial_cmp(&bf).unwrap_or(Equal)
        }
        (String(as_), String(bs)) => as_.cmp(bs),
        (Bool(ab), Bool(bb)) => ab.cmp(bb),
        // Fallback: stringify and compare lexicographically
        _ => a.to_string().cmp(&b.to_string()),
    }
}

