    fn rt() -> tokio::runtime::Runtime {
        tokio::runtime::Builder::new_current_thread()
            .enable_time()
            .enable_io()
            .build()
            .unwrap()
    }

    /// Unroutable on purpose — port 1 refuses immediately.
    fn dead_provider() -> JevProvider {
        JevProvider::new(
            "k".into(),
            "http://127.0.0.1:1/never".into(),
            Duration::from_millis(50),
        )
    }

