    #[test]
    fn journal_server_disagreement_refuses_reset_with_executable_recovery() {
        let cfg = BrainCfg {
            root: PathBuf::from("/corpus/notes"),
            brain: Some("team-notes".into()),
            url: "http://localhost:9200".into(),
            data_dir: None,
            api_key: None,
