use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{mpsc, Arc, Condvar, Mutex, Weak};
use std::time::Duration;
use xerj_common::thread_spawn::SpawnedThread;

use xerj_engine::ingest_memory::{
    self, AllocatorSnapshot, EventKind, ProcessSnapshot, TraceMode, LEDGER,
};
use xerj_engine::Engine;

const CHANNEL_CAPACITY: usize = 256;

pub struct TraceRuntime {
    stop: Arc<AtomicBool>,
    wake: Arc<(Mutex<()>, Condvar)>,
    sampler: Option<SpawnedThread>,
    writer: Option<SpawnedThread>,
    dropped: Arc<AtomicU64>,
}

impl Drop for TraceRuntime {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        self.wake.1.notify_all();
        if let Some(handle) = self.sampler.take() {
            let _ = handle.join();
        }
        if let Some(handle) = self.writer.take() {
            let _ = handle.join();
        }
        let dropped = self.dropped.load(Ordering::Relaxed);
        if dropped != 0 {
            tracing::warn!(
                target: "xerj::ingest_memory",
                dropped,
                "ingest-memory trace events dropped by bounded sink"
            );
        }
    }
}

/// A trace thread that could not start (#1122). The trace is diagnostics
/// only, so the node runs on without it — but say so, rather than leaving an
/// operator who asked for a trace with an empty file and no reason.
fn trace_spawn_failed(thread: &str, error: &std::io::Error) {
    tracing::warn!(
        target: "xerj::ingest_memory",
        thread,
        %error,
        "ingest-memory trace disabled: could not start its {thread} thread"
    );
}

pub fn spawn(engine: &Arc<Engine>) -> Option<TraceRuntime> {
    let config = ingest_memory::config();
    if config.mode == TraceMode::Off {
        return None;
    }

    let (tx, rx) = mpsc::sync_channel::<String>(CHANNEL_CAPACITY);
    let stop = Arc::new(AtomicBool::new(false));
    let dropped = Arc::new(AtomicU64::new(0));
    let writer_dropped = Arc::clone(&dropped);
    // #1122: Builder::spawn panics in the child when the alternate signal
    // stack cannot be mapped. This trace is diagnostics; a failed spawn
    // disables it instead of aborting the node (`panic = "abort"`).
    let writer = match xerj_common::thread_spawn::try_spawn_unguarded(
        "xerj-ingest-memory-writer",
        move || writer_loop(rx, writer_dropped),
    ) {
        Ok(handle) => handle,
        Err(failure) => {
            trace_spawn_failed("writer", &failure.error);
            drop(failure.job);
            return None;
        }
    };

    let weak = Arc::downgrade(engine);
    let sampler_stop = Arc::clone(&stop);
    let wake = Arc::new((Mutex::new(()), Condvar::new()));
    let sampler_wake = Arc::clone(&wake);
    let sampler_dropped = Arc::clone(&dropped);
    let sampler = match xerj_common::thread_spawn::try_spawn_unguarded(
        "xerj-ingest-memory-sampler",
        move || {
            send_snapshot(&tx, &sampler_dropped, EventKind::TraceStart, false);
            sample_loop(
                weak,
                tx,
                sampler_stop,
                sampler_wake,
                sampler_dropped,
                Duration::from_millis(config.sample_ms),
            );
        },
    ) {
        Ok(handle) => handle,
        // The writer exits on its own: the sender it reads from was moved
        // into the closure the failed spawn just dropped.
        Err(failure) => {
            trace_spawn_failed("sampler", &failure.error);
            drop(failure.job);
            return None;
        }
    };

    Some(TraceRuntime {
        stop,
        wake,
        sampler: Some(sampler),
        writer: Some(writer),
        dropped,
    })
}

fn sample_loop(
    engine: Weak<Engine>,
    tx: mpsc::SyncSender<String>,
    stop: Arc<AtomicBool>,
    wake: Arc<(Mutex<()>, Condvar)>,
    dropped: Arc<AtomicU64>,
    period: Duration,
) {
    while !stop.load(Ordering::Acquire) {
        let Some(engine) = engine.upgrade() else {
            break;
        };
        refresh_snapshot_state(&engine);
        send_snapshot(&tx, &dropped, EventKind::TraceSnapshot, true);
        wait_for_stop_or_period(&stop, &wake, period);
    }

    // The shutdown path force-flushes every index before dropping
    // `TraceRuntime`. That can change the sampled memtable gauge after the
    // final periodic snapshot. Refresh synchronously here so `trace_stop`
    // describes the post-flush state even when shutdown happens immediately
    // after ingest, without waiting for another sampler period.
    if let Some(engine) = engine.upgrade() {
        refresh_snapshot_state(&engine);
    }
    send_snapshot(&tx, &dropped, EventKind::TraceStop, false);
}

fn refresh_snapshot_state(engine: &Engine) {
    refresh_snapshot_state_with(
        engine.total_memtable_bytes(),
        allocator_snapshot(),
        xerj_engine::governor::current_rss_bytes(),
        process_cpu_time_ns(),
    );
}

fn refresh_snapshot_state_with(
    memtable_bytes: u64,
    allocator: AllocatorSnapshot,
    rss: u64,
    cpu_time_ns: Option<u64>,
) {
    LEDGER.observe(
        ingest_memory::Category::MemtableActive,
        memtable_bytes as usize,
    );
    let process = ProcessSnapshot {
        rss: (rss != 0).then_some(rss),
        rss_ok: rss != 0,
        cpu_time_ns,
        cpu_time_ok: cpu_time_ns.is_some(),
    };
    LEDGER.update_physical(allocator, process);
}

fn wait_for_stop_or_period(stop: &AtomicBool, wake: &(Mutex<()>, Condvar), period: Duration) {
    let guard = wake.0.lock().unwrap_or_else(|e| e.into_inner());
    let _ = wake
        .1
        .wait_timeout_while(guard, period, |_| !stop.load(Ordering::Acquire));
}

fn send_snapshot(
    tx: &mpsc::SyncSender<String>,
    dropped: &AtomicU64,
    kind: EventKind,
    sampled: bool,
) {
    let Some(event) = ingest_memory::snapshot_event(kind, sampled) else {
        return;
    };
    match serde_json::to_string(&event) {
        Ok(line) => {
            if tx.try_send(line).is_err() {
                dropped.fetch_add(1, Ordering::Relaxed);
                LEDGER.record_dropped_event();
            }
        }
        Err(_) => {
            dropped.fetch_add(1, Ordering::Relaxed);
            LEDGER.record_dropped_event();
        }
    }
}

#[cfg(unix)]
fn process_cpu_time_ns() -> Option<u64> {
    let mut time = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: `time` is a valid writable timespec and the process CPU clock
    // requires no caller-managed lifetime.
    if unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &mut time) } != 0 {
        return None;
    }
    let seconds = u64::try_from(time.tv_sec).ok()?;
    let nanos = u64::try_from(time.tv_nsec).ok()?;
    seconds.checked_mul(1_000_000_000)?.checked_add(nanos)
}

#[cfg(not(unix))]
fn process_cpu_time_ns() -> Option<u64> {
    None
}

fn writer_loop(rx: mpsc::Receiver<String>, dropped: Arc<AtomicU64>) {
    let output =
        std::env::var("XERJ_INGEST_MEMORY_OUTPUT").unwrap_or_else(|_| "tracing".to_string());
    if output == "tracing" {
        while let Ok(line) = rx.recv() {
            tracing::info!(target: "xerj::ingest_memory", "{line}");
        }
        while let Ok(line) = rx.try_recv() {
            tracing::info!(target: "xerj::ingest_memory", "{line}");
        }
        return;
    }

    let mut file = match open_output(&output) {
        Ok(file) => file,
        Err(error) => {
            tracing::warn!(
                target: "xerj::ingest_memory",
                %error,
                path = %output,
                "could not open ingest-memory NDJSON output"
            );
            return;
        }
    };
    while let Ok(line) = rx.recv() {
        if let Err(error) = writeln!(file, "{line}") {
            record_sink_error(&dropped, &output, &error);
            break;
        }
    }
    while let Ok(line) = rx.try_recv() {
        if let Err(error) = writeln!(file, "{line}") {
            record_sink_error(&dropped, &output, &error);
            break;
        }
    }
}

fn open_output(path: &str) -> std::io::Result<std::fs::File> {
    let mut options = std::fs::OpenOptions::new();
    options.create(true).append(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        // `mode` applies only when this call creates the file. An existing
        // operator-managed file keeps its permissions and append semantics.
        options.mode(0o600);
    }
    options.open(path)
}

fn record_sink_error(dropped: &AtomicU64, path: &str, error: &std::io::Error) {
    dropped.fetch_add(1, Ordering::Relaxed);
    LEDGER.record_dropped_event();
    tracing::warn!(
        target: "xerj::ingest_memory",
        %error,
        path,
        "could not write ingest-memory NDJSON output; stopping file sink"
    );
}

#[cfg(not(target_env = "msvc"))]
fn allocator_snapshot() -> AllocatorSnapshot {
    use tikv_jemalloc_ctl::{epoch, stats};
    if epoch::advance().is_err() {
        return AllocatorSnapshot::default();
    }
    match (
        stats::allocated::read(),
        stats::active::read(),
        stats::resident::read(),
    ) {
        (Ok(allocated), Ok(active), Ok(resident)) => AllocatorSnapshot {
            allocated: Some(allocated as u64),
            active: Some(active as u64),
            resident: Some(resident as u64),
            epoch_ok: true,
        },
        _ => AllocatorSnapshot::default(),
    }
}

#[cfg(target_env = "msvc")]
fn allocator_snapshot() -> AllocatorSnapshot {
    AllocatorSnapshot::default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bounded_sink_reports_overflow_without_blocking() {
        let (tx, _rx) = mpsc::sync_channel(1);
        let dropped = AtomicU64::new(0);
        let line = r#"{"schema":"xerj.ingest_memory.v1"}"#.to_string();
        assert!(tx.try_send(line.clone()).is_ok());
        if tx.try_send(line).is_err() {
            dropped.fetch_add(1, Ordering::Relaxed);
        }
        assert_eq!(dropped.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn allocator_probe_is_explicitly_available_or_null() {
        let snapshot = allocator_snapshot();
        if snapshot.epoch_ok {
            assert!(snapshot.allocated.is_some());
            assert!(snapshot.active.is_some());
            assert!(snapshot.resident.is_some());
        } else {
            assert_eq!(snapshot.allocated, None);
            assert_eq!(snapshot.active, None);
            assert_eq!(snapshot.resident, None);
        }
    }

    #[test]
    fn process_cpu_probe_is_explicitly_available_or_null() {
        let first = process_cpu_time_ns();
        let second = process_cpu_time_ns();
        match (first, second) {
            (Some(first), Some(second)) => assert!(second >= first),
            (None, None) => {}
            _ => panic!("CPU-time probe support changed within one process"),
        }
    }

    #[test]
    fn sampler_wait_is_interruptible_even_at_max_period() {
        let stop = Arc::new(AtomicBool::new(false));
        let wake = Arc::new((Mutex::new(()), Condvar::new()));
        let thread_stop = Arc::clone(&stop);
        let thread_wake = Arc::clone(&wake);
        let started = std::time::Instant::now();
        let handle = std::thread::spawn(move || {
            wait_for_stop_or_period(&thread_stop, &thread_wake, Duration::from_secs(60));
        });
        stop.store(true, Ordering::Release);
        wake.1.notify_all();
        handle.join().unwrap();
        assert!(started.elapsed() < Duration::from_secs(1));
    }

    #[test]
    fn stop_refresh_observes_changed_gauge_without_waiting_for_period() {
        LEDGER.observe(ingest_memory::Category::MemtableActive, 8192);

        let started = std::time::Instant::now();
        refresh_snapshot_state_with(
            0,
            AllocatorSnapshot {
                allocated: Some(11),
                active: Some(12),
                resident: Some(13),
                epoch_ok: true,
            },
            14,
            Some(15),
        );

        assert!(started.elapsed() < Duration::from_secs(1));
        let memtable = LEDGER.gauge(
            ingest_memory::Category::MemtableActive,
            ingest_memory::Measurement::Estimated,
        );
        assert_eq!(memtable.current, 0);
    }

    #[cfg(unix)]
    #[test]
    fn output_file_is_private_when_created_and_preserves_existing_mode() {
        use std::os::unix::fs::PermissionsExt;

        let dir = tempfile::tempdir().unwrap();
        let created = dir.path().join("created.ndjson");
        drop(open_output(created.to_str().unwrap()).unwrap());
        assert_eq!(
            std::fs::metadata(&created).unwrap().permissions().mode() & 0o777,
            0o600
        );

        let existing = dir.path().join("existing.ndjson");
        std::fs::write(&existing, b"existing\n").unwrap();
        std::fs::set_permissions(&existing, std::fs::Permissions::from_mode(0o640)).unwrap();
        let mut file = open_output(existing.to_str().unwrap()).unwrap();
        writeln!(file, "appended").unwrap();
        drop(file);
        assert_eq!(
            std::fs::metadata(&existing).unwrap().permissions().mode() & 0o777,
            0o640
        );
        assert_eq!(
            std::fs::read_to_string(existing).unwrap(),
            "existing\nappended\n"
        );
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn output_write_failure_is_accounted() {
        let mut file = open_output("/dev/full").unwrap();
        let dropped = AtomicU64::new(0);
        let error = writeln!(file, "cannot fit").unwrap_err();
        record_sink_error(&dropped, "/dev/full", &error);
        assert_eq!(dropped.load(Ordering::Relaxed), 1);
    }
}

//! # XERJ server entry point
//!
//! Parses CLI arguments, loads configuration, initialises observability,
//! auto-generates secrets and TLS credentials on first run, then starts
//! three concurrent TCP listeners:
//!
//! - Native REST  — default :8080
//! - ES-compat    — default :9200
//! - gRPC         — default :8081 (XerjSearch service, plaintext h2c)
//!
//! Shuts down gracefully on SIGTERM or SIGINT.
//!
//! ## Subcommands
//!
//! The binary also supports a `index` subcommand that ingests an NDJSON
//! file directly into the engine without going through HTTP.  This is the
//! fastest possible ingest path — it bypasses axum, hyper, tokio request
//! scheduling, and the bulk response serialiser entirely.
//!
//! ```text
//! xerj index --index <name> --file <path.ndjson> [--batch 5000] [--workers N]
//! ```

// ── Global allocator ─────────────────────────────────────────────────────────
// Use jemalloc instead of the system (glibc) malloc.  Under the heavy
// ingest-flush churn produced by log workloads, glibc malloc retains freed
// heap pages and never returns them to the OS, which causes RSS to grow
// monotonically until the cgroup OOM-kills the process.  jemalloc handles
// fragmentation actively and madvise()'s freed regions back.
#[cfg(not(target_env = "msvc"))]
#[global_allocator]
static ALLOC: ReportingJemalloc = ReportingJemalloc;

/// Jemalloc plus a FATAL line when an allocation returns null.
///
/// `handle_alloc_error` still runs afterwards and aborts, which raises
/// SIGABRT. The line is written first, with `write(2)`, because the heap
/// is the thing that just failed. SIGKILL cannot be reported.
#[cfg(not(target_env = "msvc"))]
struct ReportingJemalloc;

#[cfg(not(target_env = "msvc"))]
unsafe impl std::alloc::GlobalAlloc for ReportingJemalloc {
    unsafe fn alloc(&self, layout: std::alloc::Layout) -> *mut u8 {
        let ptr = tikv_jemallocator::Jemalloc.alloc(layout);
        if ptr.is_null() {
            note_alloc_failure(layout.size(), layout.align());
        }
        ptr
    }

    unsafe fn alloc_zeroed(&self, layout: std::alloc::Layout) -> *mut u8 {
        let ptr = tikv_jemallocator::Jemalloc.alloc_zeroed(layout);
        if ptr.is_null() {
            note_alloc_failure(layout.size(), layout.align());
        }
        ptr
    }

    unsafe fn dealloc(&self, ptr: *mut u8, layout: std::alloc::Layout) {
        tikv_jemallocator::Jemalloc.dealloc(ptr, layout);
    }

    unsafe fn realloc(&self, ptr: *mut u8, layout: std::alloc::Layout, new_size: usize) -> *mut u8 {
        let ptr = tikv_jemallocator::Jemalloc.realloc(ptr, layout, new_size);
        if ptr.is_null() {
            note_alloc_failure(new_size, layout.align());
        }
        ptr
    }
}

// jemalloc runtime config (read at process start via the `_rjem_malloc_conf`
// symbol — tikv-jemalloc is built with the `_rjem_` prefix, so plain
// `MALLOC_CONF` is IGNORED; only `_RJEM_MALLOC_CONF` or this symbol work).
//
// Why this is load-bearing: jemalloc's decay-based purging only runs inside
// allocator ticks and, without background threads, effectively never returns
// dirty pages under sustained multi-arena ingest churn.  Measured on a
// 62M-record bulk load: anon RSS grew ~4-5 KB per ingested doc (~15x the raw
// corpus, 83 GB at 15.5M docs) until the kernel OOM-killed the server, while
// live heap was a fraction of that.  `background_thread:true` +
// 1 s dirty/muzzy decay purges freed pages continuously; the same load then
// holds a flat working-set RSS.  Ingest throughput cost measured: none
// (within noise, ~36k docs/s single-index bulk either way).
#[cfg(all(
    not(target_env = "msvc"),
    not(feature = "debug-profiling"),
    target_os = "linux"
))]
#[allow(non_upper_case_globals)]
#[export_name = "_rjem_malloc_conf"]
pub static malloc_conf: &[u8] = b"background_thread:true,dirty_decay_ms:1000,muzzy_decay_ms:1000\0";

// macOS (and other non-Linux unix) jemalloc has no pthread background_thread
// support, so `background_thread:true` only prints `<jemalloc>: option
// background_thread currently supports pthread only` on every launch (reported
// by users running `xerj autoindex` on macOS). Keep the aggressive decay policy
// — it still purges freed pages on allocator ticks — without the unsupported knob.
#[cfg(all(
    not(target_env = "msvc"),
    not(feature = "debug-profiling"),
    not(target_os = "linux")
))]
#[allow(non_upper_case_globals)]
#[export_name = "_rjem_malloc_conf"]
pub static malloc_conf: &[u8] = b"dirty_decay_ms:1000,muzzy_decay_ms:1000\0";

// Preserve the production decay policy. Merely compiling this feature enables
// jemalloc's profiler; sampling remains inactive until the local controller
// starts a bounded capture.
#[cfg(all(not(target_env = "msvc"), feature = "debug-profiling"))]
#[allow(non_upper_case_globals)]
#[export_name = "_rjem_malloc_conf"]
pub static malloc_conf: &[u8] = b"background_thread:true,dirty_decay_ms:1000,muzzy_decay_ms:1000,prof:true,prof_active:false,lg_prof_sample:19\0";

