#[derive(Debug)]
struct CliArgs {
    config: Option<PathBuf>,
    data_dir: Option<String>,
    bind: Option<String>,
    port: Option<String>,
    auto_port: Option<bool>,
    insecure: bool,
    embed_mode: Option<String>,
