//! #1586: a usage error is the error plus one line pointing at `--help`,
//! never the help page itself.
//!
//! Before this, any `xerj autoindex` usage error wrote one throwaway line to
//! stderr and the 390-line help page to stdout. An agent that reads stdout, or
//! the tail of combined output, saw only help — nothing said the run had done
//! nothing, and the field report's agent concluded the first folder had been
//! indexed.
//!
//! This test drives the real binary: the exit code, the empty stdout, and the
//! two-line stderr are the contract. It uses `--approve full` (a value error)
//! so it does not depend on the second-folder message from the sibling PR.

use std::process::Command;

#[test]
fn autoindex_usage_error_prints_the_error_and_one_help_pointer() {
    let out = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .args(["autoindex", "--approve", "full"])
        .output()
        .expect("run the xerj binary");

    assert_eq!(out.status.code(), Some(2), "usage errors exit 2");

    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.is_empty(),
        "a usage error must not write the help page to stdout:\n{stdout}"
    );

    let stderr = String::from_utf8_lossy(&out.stderr);
    let lines: Vec<&str> = stderr.lines().collect();
    assert_eq!(
        lines.len(),
        2,
        "the whole stderr is the error and one pointer, got:\n{stderr}"
    );
    assert!(
        lines[0].starts_with("error: "),
        "first line must be the error: {stderr}"
    );
    assert!(
        lines[0].contains("--approve full is not one of"),
        "the actual usage error must survive: {stderr}"
    );
    assert!(
        lines[1].contains("xerj autoindex --help"),
        "second line must point at the full help: {stderr}"
    );
}

//! Real installed-shape CLI and MCP must return the same batch contract.
use std::process::Stdio;

use axum::{routing::post, Json, Router};
use serde_json::{json, Value};
use tokio::io::AsyncWriteExt;

#[tokio::test]
async fn cli_stdin_file_and_mcp_agree_and_item_errors_have_exit_three() {
    let app = Router::new().route(
        "/_msearch",
        post(|| async {
            Json(json!({"responses":[
                {"hits":{"hits":[{"_index":"docs","_id":"1","_source":{"body":"evidence"}}]}},
                {"error":{"reason":"bad query"},"status":400}
            ]}))
        }),
    );
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let url = format!("http://{}", listener.local_addr().unwrap());
    let server = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
    let input = json!({"index":"docs","queries":[{"query":{"match_all":{}}},{"query":{"bad":{}}}]});
    let mcp = xerj_mcp::handle_message_for_test(
        &url,
        None,
        json!({"jsonrpc":"2.0","id":1,"method":"tools/call",
            "params":{"name":"xerj_batch_search","arguments":input}}),
    )
    .await
    .unwrap();
    let expected: Value =
        serde_json::from_str(mcp["result"]["content"][0]["text"].as_str().unwrap()).unwrap();
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("queries.json");
    std::fs::write(&path, input.to_string()).unwrap();
    for file in ["-".to_string(), path.to_string_lossy().into_owned()] {
        let mut child = tokio::process::Command::new(env!("CARGO_BIN_EXE_xerj"))
            .args([
                "--url",
                &url,
                "batch-search",
                "--input",
                &file,
                "--disable-feedback",
            ])
            .env("XERJ_DISABLE_FEEDBACK", "true")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap();
        let mut stdin = child.stdin.take().unwrap();
        if file == "-" {
            stdin.write_all(input.to_string().as_bytes()).await.unwrap();
        }
        drop(stdin);
        let out = child.wait_with_output().await.unwrap();
        assert_eq!(
            out.status.code(),
            Some(3),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        assert_eq!(
            serde_json::from_slice::<Value>(&out.stdout).unwrap(),
            expected
        );
    }
    server.abort();
    let _ = server.await;
}

#[test]
fn cli_help_and_malformed_input_never_start_a_node() {
    let help = std::process::Command::new(env!("CARGO_BIN_EXE_xerj"))
