/// `--bind` exists only because the default is loopback: without it there is
/// no way to expose the node other than writing a TOML file. If the flag were
/// parsed but not applied, the default change would look like a hard
/// regression to anyone who reached for the obvious flag.
#[test]
fn bind_flag_is_honoured_and_still_gated() {
    let dir = tempfile::tempdir().unwrap();
    let (rest, grpc, es) = three_free_ports();
    let config_path = dir.path().join("xerj.toml");
    std::fs::write(
        &config_path,
        format!(
            r#"
[server]
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"
"#,
            data = toml_path(&dir.path().join("data")),
        ),
    )
    .unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .arg("--bind")
        .arg("10.0.0.7")
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    let deadline = Instant::now() + Duration::from_secs(60);
    let status = loop {
        match child.try_wait().expect("poll child") {
            Some(status) => break status,
            None if Instant::now() > deadline => {
                child.kill().ok();
                child.wait().ok();
                panic!(
                    "--bind 10.0.0.7 was accepted but not applied — the config file's \
                        loopback default survived, so the flag is inert"
                );
            }
            None => std::thread::sleep(Duration::from_millis(100)),
        }
    };
    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");

    assert!(!status.success(), "must exit non-zero; stderr:\n{stderr}");
    assert!(
        stderr.contains("10.0.0.7"),
        "the refusal must quote the address --bind supplied, proving the flag \
         reached the config; stderr:\n{stderr}"
    );
}

/// The cluster transport must be reachable by the same IPv6 loopback spelling
/// the data listeners accept.
///
/// `bind_address = "::1"` is a spelling operators reach for now that the
/// default is loopback (#228), and the cluster listen address was the last
/// place composing one by `format!("{bind}:{port}")` — `"::1:9300"` is not a
/// socket address. The failure was worse than the data listeners': it lands at
/// step 8b, *after* the data directory exists and a first-run admin key has
/// been minted and printed, so the node leaves state behind and still cannot
/// start.
///
/// Alive is the assertion. A regressed binary exits with
/// `Error: parse cluster listen address`; the fixed one keeps running. If the
/// environment has no usable IPv6 transport the binary logs the degraded
/// single-node fallback and stays up — which still proves the address parsed,
/// the only thing under test here.
#[test]
fn ipv6_loopback_bind_starts_the_cluster_transport() {
    let dir = tempfile::tempdir().unwrap();
    let (rest, grpc, es, cluster) = four_free_ports();
    let config_path = dir.path().join("xerj.toml");
    std::fs::write(
        &config_path,
        format!(
            r#"
[server]
bind_address = "::1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[cluster]
enabled = true
port = {cluster}
auth_secret = "0123456789abcdef0123456789abcdef"
"#,
            data = toml_path(&dir.path().join("data")),
        ),
    )
    .unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .env("XERJ_LOG", "info")
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    // Long enough for engine init plus step 8b on a slow runner; the regressed
    // binary dies well before this and the loop breaks out early.
    let alive_until = Instant::now() + Duration::from_secs(20);
    let mut exited = None;
    while Instant::now() < alive_until {
        if let Some(status) = child.try_wait().expect("poll child") {
            exited = Some(status);
            break;
        }
        std::thread::sleep(Duration::from_millis(200));
    }
    child.kill().ok();
    child.wait().ok();

    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");

    assert!(
        !stderr.contains("parse cluster listen address"),
        "the cluster listen address must be composed from the parsed bind IP, \
         not from \"{{bind}}:{{port}}\"; stderr:\n{stderr}"
    );
    assert!(
        exited.is_none(),
        "bind_address = \"::1\" with cluster mode on must start; it exited \
         with {exited:?}. stderr:\n{stderr}"
    );
}

/// A `bind_address` that is not an IP literal must be told the truth about
/// itself, and must be told it before anything is created.
///
/// `Config::bind_address_is_loopback` fails closed on a value it cannot parse
/// — correct for a predicate guarding an exposure, and the reason `localhost`
/// used to be refused by step 3c with a message asserting that localhost "is
/// not loopback" and "would serve plain HTTP on a network-reachable
/// interface". Both false. Worse, the remedy that refusal named
/// (`allow_insecure_network_bind = true`) fixed nothing: it silenced 3c and
/// let the boot run to the bind at step 11, so the operator following the
/// instructions got a data directory, `.xerj_*` system indices, a master key,
/// a printed first-run `admin.key` — and then the same failure anyway.
///
/// Both halves are asserted here: the message is the true one, and the
/// declared-exposure path (the one the old message pointed at) refuses in the
/// same place rather than deferring.
#[test]
fn non_ip_bind_address_is_refused_early_and_truthfully() {
    for opt_out in [false, true] {
        let dir = tempfile::tempdir().unwrap();
        let data_dir = dir.path().join("data");
        let (rest, grpc, es) = three_free_ports();
        let opt_out_line = if opt_out {
            "allow_insecure_network_bind = true\n"
        } else {
            ""
        };
        let body = format!(
            r#"
[server]
bind_address = "localhost"
{opt_out_line}rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"
"#,
            data = toml_path(&data_dir),
        );

        let (ok, stderr) = run_until_exit(&body, dir.path(), &[]);

        assert!(
            !ok,
            "a bind_address that is not an IP literal must exit non-zero \
             (allow_insecure_network_bind = {opt_out}); stderr:\n{stderr}"
        );
        assert!(
            stderr.contains("is not an IP address") && stderr.contains("localhost"),
            "the exit reason must name the real fault and quote the value \
             (allow_insecure_network_bind = {opt_out}); stderr:\n{stderr}"
        );
        assert!(
            !stderr.contains("is not loopback"),
            "localhost IS loopback — the refusal must not assert otherwise; \
             stderr:\n{stderr}"
        );
        assert!(
            !stderr.contains("allow_insecure_network_bind"),
            "the refusal must not prescribe an opt-out that does not fix the \
             fault and only defers the failure past the data directory; \
             stderr:\n{stderr}"
        );
        // The point of moving this to step 3a: with the opt-out set, the old
        // code reached step 11 and died there, leaving the data dir, the
        // system indices and a first-run admin key behind.
        assert!(
            !data_dir.exists(),
            "a rejected boot must create nothing (allow_insecure_network_bind \
             = {opt_out}); found {}. stderr:\n{stderr}",
            data_dir.display()
        );
    }
}

/// The same guard, reached through `--bind`. The flag is applied after the
/// config file is validated, so a check that lived in `Config::validate`
/// would never see it — this pins that the rejection is on the boot path both
/// sources funnel through.
#[test]
fn non_ip_bind_flag_is_refused_before_the_data_dir() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    let (rest, grpc, es) = three_free_ports();
    let config_path = dir.path().join("xerj.toml");
    std::fs::write(
        &config_path,
        format!(
            r#"
[server]
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"
"#,
            data = toml_path(&data_dir),
        ),
    )
    .unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .arg("--bind")
        .arg("db.internal.example")
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    let deadline = Instant::now() + Duration::from_secs(60);
    let status = loop {
        match child.try_wait().expect("poll child") {
            Some(status) => break status,
            None if Instant::now() > deadline => {
                child.kill().ok();
                child.wait().ok();
                panic!("--bind db.internal.example must be refused, not served");
            }
            None => std::thread::sleep(Duration::from_millis(100)),
        }
    };
    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");

    assert!(!status.success(), "must exit non-zero; stderr:\n{stderr}");
    assert!(
        stderr.contains("is not an IP address") && stderr.contains("db.internal.example"),
        "host names are not resolved, and the refusal must say so while \
         quoting the value; stderr:\n{stderr}"
    );
    assert!(
        !data_dir.exists(),
        "a rejected boot must create nothing; found {}. stderr:\n{stderr}",
        data_dir.display()
    );
}

//! Issue #203, against the real binary and a real `SIGKILL`.
//!
//! The in-process test (`xerj-api/tests/cluster_metadata_survives_restart.rs`)
//! proves the reload path. This one proves the *durability* half: the state
//! has to be on disk at the moment the PUT is acknowledged, not at some later
//! shutdown hook, because the restart that matters is the one nobody planned.
//! `kill -9` gives the process no chance to flush anything, so anything that
//! comes back was already committed by `write_file_atomic` (write → fsync →
//! rename → fsync parent).
//!
//! The write also has to be *atomic*, not merely eventual: this test hard-kills
//! the node while it is answering, so a rewrite that truncated the file in
//! place could leave a half-document that takes every template with it.
//!
//! Linux/macOS only — `SIGKILL` has no Windows equivalent, and
//! `Child::kill()` there is a `TerminateProcess` that Windows may let the
//! runtime observe. The property under test is platform-independent, but the
//! way to provoke it is not.

#![cfg(unix)]

use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpListener, TcpStream};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

/// Three distinct free ports — `Config::validate` requires all three listener
/// ports to differ.
fn three_free_ports() -> (u16, u16, u16) {
    let l1 = TcpListener::bind("127.0.0.1:0").unwrap();
    let l2 = TcpListener::bind("127.0.0.1:0").unwrap();
    let l3 = TcpListener::bind("127.0.0.1:0").unwrap();
    (
        l1.local_addr().unwrap().port(),
        l2.local_addr().unwrap().port(),
        l3.local_addr().unwrap().port(),
    )
}

fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

/// One HTTP/1.1 request over a fresh connection, returning `(status, body)`.
///
/// Hand-rolled rather than pulled from a client crate so the test has no
/// runtime of its own: it must stay a plain `#[test]`, since the thing it
/// kills is a separate process and any async machinery here would only be
/// another thing that can hang.
fn request(
    port: u16,
    method: &str,
    path: &str,
    body: Option<&str>,
) -> std::io::Result<(u16, String)> {
    let mut stream = TcpStream::connect(("127.0.0.1", port))?;
    stream.set_read_timeout(Some(Duration::from_secs(30)))?;
    stream.set_write_timeout(Some(Duration::from_secs(30)))?;

    let payload = body.unwrap_or("");
    let request = format!(
        "{method} {path} HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\
         Content-Type: application/json\r\nContent-Length: {}\r\n\r\n{payload}",
        payload.len()
    );
    stream.write_all(request.as_bytes())?;
    stream.flush()?;

    let mut reader = BufReader::new(stream);
    let mut status_line = String::new();
    reader.read_line(&mut status_line)?;
    let status: u16 = status_line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);

    // Drain headers, then everything else — `Connection: close` means the
    // body ends at EOF, so no chunk/length parsing is needed.
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line)? == 0 || line == "\r\n" {
            break;
        }
    }
    let mut body = String::new();
    reader.read_to_string(&mut body)?;
    Ok((status, body))
}

/// Spawn the real binary on `data_dir` and wait until it answers.
fn boot(
    data_dir: &std::path::Path,
    cfg_dir: &std::path::Path,
    es_port: u16,
    rest: u16,
    grpc: u16,
) -> Child {
    let config = format!(
        r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es_port}
data_dir = "{data}"
"#,
        data = toml_path(data_dir),
    );
    let config_path = cfg_dir.join(format!("xerj-{es_port}.toml"));
    std::fs::write(&config_path, config).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .arg("--insecure")
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn xerj");

    let deadline = Instant::now() + Duration::from_secs(120);
    loop {
        if let Ok((200, _)) = request(es_port, "GET", "/_cluster/health", None) {
            return child;
        }
        if Instant::now() >= deadline {
            break;
        }
        std::thread::sleep(Duration::from_millis(200));
    }
    // Never leave a half-booted node behind for the rest of the suite to
    // trip over — reap it, then fail.
    let _ = child.kill();
    let _ = child.wait();
    panic!("xerj did not become ready on port {es_port}");
}

/// `kill -9` and reap. No graceful shutdown, no flush hook, no chance to
/// write anything the acknowledged PUTs did not already write.
fn sigkill(mut child: Child) {
    unsafe {
        libc::kill(child.id() as libc::pid_t, libc::SIGKILL);
    }
    let status = child.wait().expect("reap child");
    assert!(
        !status.success(),
        "the node was supposed to be hard-killed, but it exited cleanly ({status:?}) — \
         a graceful exit could have flushed state that a real crash never would"
    );
}

#[test]
fn cluster_metadata_survives_kill_dash_nine() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    std::fs::create_dir_all(&data_dir).unwrap();

    let (rest, grpc, es) = three_free_ports();
    let child = boot(&data_dir, dir.path(), es, rest, grpc);

    let (st, b) = request(
        es,
        "PUT",
        "/_index_template/logs",
        Some(r#"{"index_patterns":["logs-*"],"priority":200,"template":{"mappings":{"properties":{"host":{"type":"keyword"}}}}}"#),
    )
    .unwrap();
    assert_eq!(st, 200, "PUT _index_template: {b}");

    let (st, b) = request(
        es,
        "PUT",
        "/_ingest/pipeline/tagger",
        Some(r#"{"description":"tag","processors":[{"set":{"field":"tagged","value":"yes"}}]}"#),
    )
    .unwrap();
    assert_eq!(st, 200, "PUT _ingest/pipeline: {b}");

    let (st, b) = request(
        es,
        "PUT",
        "/_ilm/policy/hot-warm",
        Some(r#"{"policy":{"phases":{"hot":{"actions":{}}}}}"#),
    )
    .unwrap();
    assert_eq!(st, 200, "PUT _ilm/policy: {b}");

    let (st, b) = request(es, "PUT", "/_data_stream/metrics-app", Some("{}")).unwrap();
    assert_eq!(st, 200, "PUT _data_stream: {b}");

    // Roll the stream forward so the restored generation counter has to be
    // 2, not the 1 a re-create would produce.
    let (st, b) = request(es, "POST", "/metrics-app/_rollover", Some("{}")).unwrap();
    assert_eq!(st, 200, "POST _rollover: {b}");
    assert!(
        b.contains(".ds-metrics-app-000002"),
        "rollover should mint generation 2: {b}"
    );

    sigkill(child);

    // Same data dir, brand-new process. Everything above was acknowledged,
    // so everything above must still be here.
    let child = boot(&data_dir, dir.path(), es, rest, grpc);

    let (st, b) = request(es, "GET", "/_index_template/logs", None).unwrap();
    assert_eq!(st, 200, "index template lost across kill -9: {b}");
    assert!(
        b.contains("logs-*") && b.contains("keyword"),
        "partial template restore: {b}"
    );

    let (st, b) = request(es, "GET", "/_ingest/pipeline/tagger", None).unwrap();
    assert_eq!(st, 200, "ingest pipeline lost across kill -9: {b}");

    let (st, b) = request(es, "GET", "/_ilm/policy/hot-warm", None).unwrap();
    assert_eq!(st, 200, "ILM policy lost across kill -9: {b}");

    let (st, b) = request(es, "GET", "/_data_stream/metrics-app", None).unwrap();
    assert_eq!(st, 200, "data stream lost across kill -9: {b}");
    assert!(
        b.contains("\"generation\":2") && b.contains(".ds-metrics-app-000002"),
        "the rollover must survive too, or the next rollover reissues a \
         backing index that already holds data: {b}"
    );

    // The restored pipeline must still *run*, not just be readable.
    let (st, b) = request(
        es,
        "POST",
        "/_ingest/pipeline/tagger/_simulate",
        Some(r#"{"docs":[{"_source":{"host":"a"}}]}"#),
    )
    .unwrap();
    assert_eq!(st, 200, "simulate after restart: {b}");
    assert!(
        b.contains("\"tagged\":\"yes\""),
        "a restored pipeline that no longer transforms is accepted-and-ignored: {b}"
    );

    sigkill(child);
}

//! Observe the real startup banner without touching any existing node or data.
use std::fs::File;
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

struct Node(Child);
impl Drop for Node {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

fn startup(work: &std::path::Path, extra: &[&str], env_config: Option<&str>) -> String {
    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"));
    child
        .current_dir(work)
        .env_clear()
        .env("XERJ_DISABLE_FEEDBACK", "true")
        .env("XERJ_NUM_CPUS", "2")
        .args(["--insecure"])
        .args(extra)
        .stdout(Stdio::from(File::create(work.join("stdout")).unwrap()))
        .stderr(Stdio::from(File::create(work.join("stderr")).unwrap()));
    if let Some(path) = env_config {
        child.env("XERJ_CONFIG", path);
    }
    let mut node = Node(child.spawn().unwrap());
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        let output = std::fs::read_to_string(work.join("stdout")).unwrap();
        if output.contains(" Started in ") {
            return output;
        }
        if let Some(status) = node.0.try_wait().unwrap() {
            panic!(
                "node exited {status}: {}",
                std::fs::read_to_string(work.join("stderr")).unwrap()
            );
        }
        assert!(Instant::now() < deadline, "startup timed out");
        std::thread::sleep(Duration::from_millis(20));
    }
}

fn config(work: &std::path::Path, data: Option<&str>) {
    let first = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let second = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let mut text = format!(
        "[server]\nes_compat_port={}\nrest_port={}\ngrpc_port=0\n",
        first.local_addr().unwrap().port(),
        second.local_addr().unwrap().port()
    );
    if let Some(data) = data {
        text.push_str(&format!(
            "data_dir={}\n",
            serde_json::to_string(data).unwrap()
        ));
    }
    std::fs::write(work.join("node.toml"), text).unwrap();
}

#[test]
fn startup_names_the_actual_data_directory_source_and_creation_state() {
    for (kind, setting, flags, env, expected_dir, source) in [
        (
            "config",
            Some("persistent"),
            vec!["-c", "node.toml"],
            Some("missing.toml"),
            "persistent",
            "config file (--config)",
        ),
        (
            "env",
            Some("persistent"),
            vec![],
            Some("node.toml"),
            "persistent",
            "config file (XERJ_CONFIG)",
        ),
        (
            "flag",
            Some("unused"),
            vec!["-c", "node.toml", "--data-dir", "selected"],
            None,
            "selected",
            "--data-dir",
        ),
        (
            "default",
            None,
            vec!["-c", "node.toml"],
            None,
            "data",
            "default ./data",
        ),
    ] {
        let temp = tempfile::tempdir().unwrap();
        let work = temp.path();
        config(work, setting);
        let output = startup(work, &flags, env);
        assert!(output.contains(" Data source  "), "{kind}: {output}");
        assert!(output.contains(source), "{kind}: {output}");
        assert!(output.contains("created this launch"), "{kind}: {output}");
        let actual = std::fs::canonicalize(work.join(expected_dir)).unwrap();
        assert!(
            output.contains(&actual.display().to_string().escape_debug().to_string()),
            "{kind}: {output}"
        );
        assert!(
            output.contains("previous --data-dir or --config"),
            "{kind}: {output}"
        );
        if kind == "flag" {
            assert!(!work.join("unused").exists());
        }
        std::fs::write(work.join(expected_dir).join("operator-sentinel"), "keep").unwrap();
        let repeated = startup(work, &flags, env);
        assert!(
            repeated.contains("existing directory"),
            "{kind}: {repeated}"
        );
        assert!(
            !repeated.contains("created this launch"),
            "{kind}: {repeated}"
        );
        assert_eq!(
            std::fs::read_to_string(work.join(expected_dir).join("operator-sentinel")).unwrap(),
            "keep"
        );
    }
}

//! Issue #469: the first-launch console setup link must name a port the node
//! actually holds, not the one it was asked for.
//!
//! The link used to be built from `cfg.server.es_compat_port` — the
//! *requested* port — and printed at the old step 9, before any listener was
//! bound (binding happened at the old step 10a). With an ephemeral port
//! (`es_compat_port = 0`) that produced a link like
//! `http://127.0.0.1:0/_xerj-console/setup#token=…`: `:0` is never a
//! reachable address, so the single action a first-run operator is told to
//! take could not be followed. #466 fixed the same class of problem for the
//! startup banner by binding every listener first and printing from
//! `local_addr()`; this is that same treatment applied to the console link.
//!
//! This is a process-level test, like `taken_port_fails_startup.rs`: the
//! defect is in how `main.rs` sequences the bind against the console
//! bootstrap, which is invisible from inside `xerj-console-api` (its own unit
//! tests pass a `bind_url` the caller already built correctly).

use std::io::Read;
use std::net::TcpListener;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

/// `rest_port`/`grpc_port` pinned to two free ports; `es_compat_port = 0` so
/// the kernel assigns the ES-compat listener whatever it has free — the
/// ephemeral-port case the issue reports against.
fn config_with_ephemeral_es_port(dir: &std::path::Path, rest: u16, grpc: u16) -> String {
    format!(
        r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = 0
data_dir = "{data}"

[limits]
disk_flood_stage_percent = 0
"#,
        data = toml_path(&dir.join("data")),
    )
}

fn two_free_ports() -> (u16, u16) {
    let held: Vec<TcpListener> = (0..2)
        .map(|_| TcpListener::bind("127.0.0.1:0").unwrap())
        .collect();
    let p: Vec<u16> = held
        .iter()
        .map(|l| l.local_addr().unwrap().port())
        .collect();
    (p[0], p[1])
}

struct Outcome {
    stdout: String,
    stderr: String,
}

/// Read `r` a chunk at a time, appending everything into `buf`, until EOF —
/// meant to run on its own thread against a still-live child pipe, since a
/// blocking `read` only returns once the child writes or closes it.
fn drain_into(mut r: impl Read, buf: Arc<Mutex<String>>) {
    let mut chunk = [0u8; 4096];
    loop {
        match r.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => buf
                .lock()
                .unwrap()
                .push_str(&String::from_utf8_lossy(&chunk[..n])),
            Err(_) => break,
        }
    }
}

/// Spawn the real binary and poll its stdout/stderr for `until` to become
/// true, up to `timeout`, then kill it — this is a first-launch boot with no
/// active user yet, so it never exits on its own. Two reader threads drain
/// the pipes concurrently so a quiet stdout (still building system indices)
/// never blocks us from seeing what stderr already has, or vice versa.
fn boot_until(
    config_body: &str,
    dir: &std::path::Path,
    timeout: Duration,
    until: impl Fn(&str, &str) -> bool,
) -> Outcome {
    let config_path = dir.join("xerj.toml");
    std::fs::write(&config_path, config_body).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .arg("--insecure")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    let stdout_buf = Arc::new(Mutex::new(String::new()));
    let stderr_buf = Arc::new(Mutex::new(String::new()));
    let out_r = child.stdout.take().expect("stdout piped");
    let err_r = child.stderr.take().expect("stderr piped");
    let out_buf_t = stdout_buf.clone();
    let err_buf_t = stderr_buf.clone();
    let out_thread = std::thread::spawn(move || drain_into(out_r, out_buf_t));
    let err_thread = std::thread::spawn(move || drain_into(err_r, err_buf_t));

    let deadline = Instant::now() + timeout;
    loop {
        {
            let so = stdout_buf.lock().unwrap();
            let se = stderr_buf.lock().unwrap();
            if until(&so, &se) || Instant::now() > deadline {
                break;
            }
        }
        std::thread::sleep(Duration::from_millis(50));
    }

    child.kill().ok();
    child.wait().ok();
    out_thread.join().ok();
    err_thread.join().ok();

    Outcome {
        stdout: Arc::try_unwrap(stdout_buf).unwrap().into_inner().unwrap(),
        stderr: Arc::try_unwrap(stderr_buf).unwrap().into_inner().unwrap(),
    }
}

/// Pull the port out of `…http://host:PORT/_xerj-console/setup#token=…`.
fn port_from_setup_link(stderr: &str) -> Option<u16> {
    let marker = "/_xerj-console/setup#token=";
    let end = stderr.find(marker)?;
    let authority_end = &stderr[..end];
    let start = authority_end.rfind("http://")?;
    let authority = &authority_end[start + "http://".len()..end];
    let port_str = authority.rsplit(':').next()?;
    port_str.parse().ok()
}

/// Pull the host out of the same `…http://HOST:port/_xerj-console/setup#token=…`.
fn host_from_setup_link(stderr: &str) -> Option<String> {
    let marker = "/_xerj-console/setup#token=";
    let end = stderr.find(marker)?;
    let authority_end = &stderr[..end];
    let start = authority_end.rfind("http://")?;
    let authority = &authority_end[start + "http://".len()..end];
    let (host, port_str) = authority.rsplit_once(':').unwrap_or((authority, ""));
    // Guard against a future authority shape confusing the split: whatever
    // follows the colon must be the port for the host to mean anything.
    if port_str.is_empty() || port_str.chars().all(|c| c.is_ascii_digit()) {
        Some(host.to_string())
    } else {
        None
    }
}

/// Pull the port out of the banner's `ES-compat    127.0.0.1:PORT [...]` line.
fn port_from_banner(stdout: &str) -> Option<u16> {
    let line = stdout
        .lines()
        .find(|l| l.trim_start().starts_with("ES-compat"))?;
    let after_colon = line.rsplit_once(':')?.1;
    let digits: String = after_colon
        .chars()
        .take_while(|c| c.is_ascii_digit())
        .collect();
    digits.parse().ok()
}

/// The whole defect in one assertion: with `es_compat_port = 0`, the port
/// named in the first-launch setup link must be a real, non-zero port — and
/// specifically the one the banner (already fixed by #466, from
/// `local_addr()`) reports the node actually bound.
#[test]
fn ephemeral_es_port_console_link_names_the_bound_port() {
    let dir = tempfile::tempdir().unwrap();
    let (rest, grpc) = two_free_ports();

    let out = boot_until(
        &config_with_ephemeral_es_port(dir.path(), rest, grpc),
        dir.path(),
        Duration::from_secs(60),
        |stdout, stderr| {
            stdout.contains("ES-compat") && stderr.contains("/_xerj-console/setup#token=")
        },
    );

    let link_port = port_from_setup_link(&out.stderr).unwrap_or_else(|| {
        panic!(
            "no first-launch setup link found on stderr within the boot window\n\
             --- stdout ---\n{}\n--- stderr ---\n{}",
            out.stdout, out.stderr
        )
    });
    let banner_port = port_from_banner(&out.stdout).unwrap_or_else(|| {
        panic!(
            "no ES-compat banner line found on stdout within the boot window\n\
             --- stdout ---\n{}\n--- stderr ---\n{}",
            out.stdout, out.stderr
        )
    });

    assert_ne!(
        link_port, 0,
        "the setup link named port 0 — unreachable, and the exact bug \
         (issue #469): `es_compat_port = 0` leaked into the link instead of \
         the port the kernel actually bound\n--- stderr ---\n{}",
        out.stderr
    );
    assert_eq!(
        link_port, banner_port,
        "the setup link named a different port than the banner — the node \
         is telling the operator to open a URL it is not listening \
         on\n--- stdout ---\n{}\n--- stderr ---\n{}",
        out.stdout, out.stderr
    );
}

/// Issue #935: the first-launch link must be *usable*. A browser treats
/// `http://127.0.0.1:<port>` as an IP-literal origin, and WebAuthn refuses
/// IP-literal origins outright — so a setup link printed with the bind
/// address could never complete passkey enrolment, whatever the relying
/// party is configured as. Every loopback bind is therefore printed (and
/// its relying party derived) as `localhost`.
#[test]
fn loopback_bind_prints_the_setup_link_as_localhost() {
    let dir = tempfile::tempdir().unwrap();
    let (rest, grpc) = two_free_ports();

    let out = boot_until(
        &config_with_ephemeral_es_port(dir.path(), rest, grpc),
        dir.path(),
        Duration::from_secs(60),
        |stdout, stderr| {
            stdout.contains("ES-compat") && stderr.contains("/_xerj-console/setup#token=")
        },
    );

    let host = host_from_setup_link(&out.stderr).unwrap_or_else(|| {
        panic!(
            "no parsable first-launch setup link found on stderr within the boot window\n\
             --- stdout ---\n{}\n--- stderr ---\n{}",
            out.stdout, out.stderr
        )
    });

    assert_eq!(
        host, "localhost",
        "a loopback bind (127.0.0.1) must be printed as localhost in the \
         setup link: an IP-literal origin cannot complete WebAuthn enrolment \
         (#935)\n--- stderr ---\n{}",
        out.stderr
    );
}

//! The feedback invitation, checked on the real binary.
//!
//! Every help surface a caller actually meets — `xerj --help`,
//! `xerj index --help`, `xerj autoindex --help`, `xerj brain --help` — must
//! carry the bug/confusing-UX invitation by default, near the top, and must
//! drop it when `--disable-feedback` is given in *either* position or when
//! `XERJ_DISABLE_FEEDBACK` is set.
//!
//! These drive the built binary rather than the library functions on purpose:
//! `--help` is dispatched from inside each argument loop and exits there, so
//! only a real process proves that a flag written *after* `--help` still
//! counts.

use std::process::Command;

/// The first words of the invitation. One needle, so a reworded second or
/// third line does not fail the position check.
const NEEDLE: &str = "Hit a bug, or a flow that confused you?";

/// The issues URL is the load-bearing part: an invitation without a
/// destination is decoration.
const ISSUES_URL: &str = "https://github.com/xerj-org/xerj/issues";

/// "Near the top" is the requirement, not "somewhere in the file" — at the
/// bottom of a 200-line help body nothing would ever read it.
const MAX_LINE: usize = 10;

/// Every surface, as the argv a caller would type.
const SURFACES: [&[&str]; 5] = [
    &["--help"],
    &["index", "--help"],
    &["autoindex", "--help"],
    &["brain", "--help"],
    // Added after #337 introduced this surface: the top-level help advertises
    // `xerj mcp`, so by this feature's own rule it must ask too, and it would
    // otherwise have been the one screen that never does.
    &["mcp", "--help"],
];

fn help(args: &[&str], env: Option<&str>) -> String {
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_xerj"));
    cmd.args(args);
    match env {
        Some(v) => cmd.env("XERJ_DISABLE_FEEDBACK", v),
        // The developer's own shell must not decide the default case.
        None => cmd.env_remove("XERJ_DISABLE_FEEDBACK"),
    };
    let out = cmd.output().expect("run xerj");
    assert!(
        out.status.success(),
        "xerj {args:?} exited {:?}: {}",
        out.status.code(),
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8(out.stdout).expect("help is utf-8")
}

/// 1-based line number of the invitation, or `None` if it is not there.
fn invite_line(help: &str) -> Option<usize> {
    help.lines().position(|l| l.contains(NEEDLE)).map(|i| i + 1)
}

#[test]
fn every_help_surface_invites_a_report_by_default() {
    for args in SURFACES {
        let text = help(args, None);
        let line = invite_line(&text)
            .unwrap_or_else(|| panic!("xerj {args:?} printed no invitation:\n{text}"));
        assert!(
            line <= MAX_LINE,
            "xerj {args:?} put the invitation on line {line}; it has to be within the \
             first {MAX_LINE} lines or nobody reads it:\n{text}"
        );
        assert!(
            text.contains(ISSUES_URL),
            "xerj {args:?} invites a report without saying where:\n{text}"
        );
        // Bugs AND confusing flows; file it yourself if you can; a Discussion
        // when unsure; and never paste secrets into either.
        for needle in [
            "confused you",
            "GitHub tool",
            "Discussion",
            "secrets, API keys and private data",
        ] {
            assert!(
                text.contains(needle),
                "xerj {args:?} help is missing {needle:?}:\n{text}"
            );
        }
        // The way out has to be discoverable from the same screen.
        assert!(
            text.contains("--disable-feedback"),
            "xerj {args:?} never documents the off-switch:\n{text}"
        );
    }
}

/// `--help` is handled inside the argument loop and exits there, so a naive
/// implementation would never see a flag typed after it. Both orders, every
/// surface.
#[test]
fn disable_feedback_works_in_either_argument_order() {
    for args in SURFACES {
        let mut after: Vec<&str> = args.to_vec();
        after.push("--disable-feedback");

        // Before `--help`, but after any subcommand — argv[1] is the
        // subcommand selector for `index`/`autoindex`/`brain`.
        let mut before: Vec<&str> = args.to_vec();
        before.insert(before.len() - 1, "--disable-feedback");

        for variant in [after, before] {
            let text = help(&variant, None);
            assert_eq!(
                invite_line(&text),
                None,
                "xerj {variant:?} still printed the invitation:\n{text}"
            );
            // Silencing it must not leave a hole where it stood.
            assert!(
                !text.contains("\n\n\n"),
                "xerj {variant:?} left a blank gap behind:\n{text}"
            );
        }
    }
}

/// CI and agent harnesses often cannot change argv, only the environment.
#[test]
fn the_env_var_silences_every_surface() {
    for args in SURFACES {
        for value in ["1", "true", "yes", "on"] {
            let text = help(args, Some(value));
            assert_eq!(
                invite_line(&text),
                None,
                "XERJ_DISABLE_FEEDBACK={value} left the invitation on xerj {args:?}:\n{text}"
            );
        }
        // A false-y value is not an off-switch, and a value nobody can read
        // must not silently hide it either.
        for value in ["0", "false", "off", "maybe", ""] {
            let text = help(args, Some(value));
            assert!(
                invite_line(&text).is_some(),
                "XERJ_DISABLE_FEEDBACK={value:?} hid the invitation on xerj {args:?}:\n{text}"
            );
        }
    }
}

/// An unreadable value is reported on stderr — never on stdout, which is the
/// help text itself — and never by refusing to print the help.
#[test]
fn an_unreadable_env_value_is_reported_on_stderr_only() {
    let out = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .args(["--help"])
        .env("XERJ_DISABLE_FEEDBACK", "maybe")
        .output()
        .expect("run xerj");
    assert!(out.status.success());
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(
        stderr.contains("XERJ_DISABLE_FEEDBACK") && stderr.contains("not a boolean"),
        "an unreadable value was swallowed; stderr was: {stderr}"
    );
    assert!(!String::from_utf8_lossy(&out.stdout).contains("not a boolean"));
}

/// The help bodies are `println!`/`format!` format strings, so a literal brace
/// has to be doubled — get that wrong and either the build breaks or the JSON
/// example in the help stops being JSON. Every balanced brace group in every
/// help surface must still parse.
#[test]
fn json_examples_in_help_still_parse() {
    for args in SURFACES {
        for text in [help(args, None), help(args, Some("true"))] {
            for candidate in brace_groups(&text) {
                serde_json::from_str::<serde_json::Value>(&candidate).unwrap_or_else(|e| {
                    panic!("xerj {args:?} help contains unparseable JSON {candidate:?}: {e}")
                });
            }
        }
    }
}

/// Balanced `{…}` groups, and a hard failure on an unbalanced one — a stray
/// brace is exactly what a mis-escaped format string leaves behind.
fn brace_groups(text: &str) -> Vec<String> {
    let mut groups = Vec::new();
    let mut depth = 0usize;
    let mut start = 0usize;
    for (i, c) in text.char_indices() {
        match c {
            '{' => {
                if depth == 0 {
                    start = i;
                }
                depth += 1;
            }
            '}' => {
                depth = depth
                    .checked_sub(1)
                    .unwrap_or_else(|| panic!("unbalanced '}}' in help at byte {i}"));
                if depth == 0 {
                    groups.push(text[start..=i].to_string());
                }
            }
            _ => {}
        }
    }
    assert_eq!(depth, 0, "unclosed '{{' in help text");
    groups
}

//! Issue #229: the cleartext gRPC listener must fail closed off-loopback.
//!
//! `xerj-server/src/grpc.rs` builds tonic without its `tls` feature, so
//! `server.grpc_port` speaks h2c whatever `[tls]` says. With `tls.enabled =
//! true` and a non-loopback `bind_address`, the REAL binary must exit non-zero
//! before binding anything rather than encrypt two listeners and put the third
//! in the clear on the same public interface.
//!
//! Why this is worth a process-level test rather than only the unit tests on
//! `Config::grpc_h2c_exposed_off_loopback`: the pre-fix binary starts happily
//! and serves all three ports forever, so the defect is invisible from inside
//! the config crate. Against a regressed binary this test hits its deadline
//! and fails instead of hanging.
//!
//! Nothing here binds `0.0.0.0` on purpose — the fixed binary refuses before
//! any listener exists, and the ports handed to it are free either way.

use std::io::Read;
use std::net::TcpListener;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

/// Three distinct free ports, held simultaneously so they cannot collide,
/// then released for the child. `Config::validate` requires all three listener
/// ports to differ; free ports also mean a regressed (serving) binary binds
/// cleanly and keeps running instead of dying on an unrelated bind error,
/// which would masquerade as a pass.
fn three_free_ports() -> (u16, u16, u16) {
    let l1 = TcpListener::bind("127.0.0.1:0").unwrap();
    let l2 = TcpListener::bind("127.0.0.1:0").unwrap();
    let l3 = TcpListener::bind("127.0.0.1:0").unwrap();
    (
        l1.local_addr().unwrap().port(),
        l2.local_addr().unwrap().port(),
        l3.local_addr().unwrap().port(),
    )
}

/// TOML-safe rendering of a temp path (Windows backslashes would be escape
/// sequences inside a basic string; forward slashes work on every platform).
fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

/// Run the real binary against `config_body` and return `(success, stderr)`.
///
/// The fixed binary rejects at step 5b of startup — before metrics, engine
/// replay, certificate generation, or any listener — so well under a second
/// even on a 2-core CI runner; 60 s is pure headroom.
fn run_until_exit(config_body: &str, dir: &std::path::Path) -> (bool, String) {
    let config_path = dir.join("xerj.toml");
    std::fs::write(&config_path, config_body).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    let deadline = Instant::now() + Duration::from_secs(60);
    let status = loop {
        match child.try_wait().expect("poll child") {
            Some(status) => break status,
            None if Instant::now() > deadline => {
                child.kill().ok();
                child.wait().ok();
                panic!(
                    "xerj kept running with tls.enabled = true and a non-loopback \
                     bind_address — it is serving cleartext h2c gRPC on a public \
                     interface while reporting itself as TLS-enabled"
                );
            }
            None => std::thread::sleep(Duration::from_millis(100)),
        }
    };

    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");
    (status.success(), stderr)
}

/// `0.0.0.0` is the shipped default and binds every interface the host has,
/// so "turn TLS on, change nothing else" is the exact case that must be
/// refused. This is the assertion that fails without the fix.
#[test]
fn tls_with_non_loopback_bind_refuses_to_start() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    let (rest, grpc, es) = three_free_ports();

    let (ok, stderr) = run_until_exit(
        &format!(
            r#"
[server]
bind_address = "0.0.0.0"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[tls]
enabled = true
cert_path = "{root}/xerj.crt"
key_path = "{root}/xerj.key"
"#,
            data = toml_path(&data_dir),
            root = toml_path(dir.path()),
        ),
        dir.path(),
    );

    assert!(
        !ok,
        "cleartext gRPC on a non-loopback bind under tls.enabled must exit \
         non-zero; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("h2c") && stderr.contains("Refusing to start"),
        "the exit reason must name the cleartext transport and the refusal; \
         stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("tls.allow_insecure_grpc_h2c"),
        "the operator must be told the setting that unblocks the boot, or the \
         refusal is a dead end; stderr:\n{stderr}"
    );
    // Refused at step 3b, before anything is created: no data directory, no
    // first-run admin key minted and printed, no certificate. A rejected boot
    // that still seeds credentials leaves state the operator has to clean up
    // — and an admin key on stdout that was never actually used.
    assert!(
        !dir.path().join("xerj.crt").exists(),
        "the check must run before certificate generation; stderr:\n{stderr}"
    );
    assert!(
        !data_dir.exists(),
        "a rejected boot must not create the data dir; stderr:\n{stderr}"
    );
}

/// The refusal must not fire on a loopback bind — that would break every
/// developer running `tls.enabled = true` locally, and a fail-closed check
/// nobody can satisfy gets disabled wholesale.
///
/// A clean start has no exit to wait for, so this asserts the negative that
/// is observable without one: the process is still alive after the point the
/// refusal would have killed it, and never printed the refusal.
#[test]
fn tls_on_loopback_starts_normally() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    let (rest, grpc, es) = three_free_ports();
    let config_path = dir.path().join("xerj.toml");
    std::fs::write(
        &config_path,
        format!(
            r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[tls]
enabled = true
cert_path = "{root}/xerj.crt"
key_path = "{root}/xerj.key"
"#,
            data = toml_path(&data_dir),
            root = toml_path(dir.path()),
        ),
    )
    .unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    // Generous enough for engine init on a slow runner, and far past step 5b.
    std::thread::sleep(Duration::from_secs(5));
    let alive = child.try_wait().expect("poll child").is_none();
    child.kill().ok();
    child.wait().ok();

    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");

    assert!(
        alive,
        "a loopback bind with TLS must start; it exited instead. stderr:\n{stderr}"
    );
    assert!(
        !stderr.contains("Refusing to start"),
        "the h2c check must not fire on loopback; stderr:\n{stderr}"
    );
}

/// The documented escape hatch has to actually work, or operators will reach
/// for `--insecure` (which also drops auth) to get past the refusal.
#[test]
fn explicit_opt_out_allows_a_non_loopback_bind() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    let (rest, grpc, es) = three_free_ports();
    let config_path = dir.path().join("xerj.toml");
    // Bind loopback so the test starts no publicly reachable listener; the
    // opt-out is what is under test, and `allow_insecure_grpc_h2c` is read
    // before the bind address is even consulted. The non-loopback half of the
    // matrix is covered by the unit tests in `xerj-common::config`.
    std::fs::write(
        &config_path,
        format!(
            r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[tls]
enabled = true
cert_path = "{root}/xerj.crt"
key_path = "{root}/xerj.key"
allow_insecure_grpc_h2c = true
"#,
            data = toml_path(&data_dir),
            root = toml_path(dir.path()),
        ),
    )
    .unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    std::thread::sleep(Duration::from_secs(5));
    let alive = child.try_wait().expect("poll child").is_none();
    child.kill().ok();
    child.wait().ok();

    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");

    assert!(
        alive,
        "tls.allow_insecure_grpc_h2c = true must be accepted as a config key \
         and must not block startup. stderr:\n{stderr}"
    );
}

//! Issue #485: a legitimate, authenticated request whose body arrives in small
//! HTTP/2 DATA frames must not be answered `GOAWAY ENHANCE_YOUR_CALM`.
//!
//! `h2` 0.4.16 shipped the RUSTSEC-2026-0258 mitigation as a per-connection
//! byte budget: a DATA frame under 256 bytes consumes `256 - payload_len` of
//! it, a frame of 256 or more replenishes, and the budget is a fixed 25,600
//! bytes (`DEFAULT_DATA_FRAME_OVERHEAD_THRESHOLD * 100`). The charge lands when
//! the frame arrives and the refund only when the application reads it, so a
//! client that chunks small — a streaming JSON encoder, a per-document flush, a
//! gRPC stream of small messages — drains the whole budget before the handler
//! is scheduled and has its *connection* closed. Run against the pre-fix
//! dependency, the first test below is answered `GOAWAY ENHANCE_YOUR_CALM
//! (too_many_data_frames)` part-way through a 40 KB body.
//!
//! Two things make this a process-level test rather than a unit test:
//!
//! 1. The budget is enforced inside `h2`, below hyper, below axum. Nothing in
//!    XERJ's own code can be called to observe it — only a real HTTP/2 peer
//!    sending real DATA frames at a real listener can.
//! 2. The frame size is what matters, and no ordinary HTTP client lets you
//!    choose it. These tests therefore speak HTTP/2 directly (`h2` as a client,
//!    prior-knowledge h2c against the ES-compat listener) so every `send_data`
//!    is exactly one DATA frame of exactly the size asked for.
//!
//! The pair is deliberate. The first test is the regression — the traffic that
//! must work. The second is the guard on the fix: the empty-DATA-frame flood
//! the advisory was actually filed about must still be cut off, so raising the
//! headroom for legitimate clients cannot be mistaken for switching the
//! protection off.

use std::io::Read;
use std::net::TcpListener;
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use axum::body::Bytes;
use axum::http::Request;
use tokio::net::TcpStream;

/// Fixed key so the request below is unambiguously *authenticated*: the issue
/// is about traffic that would otherwise have succeeded, not about a 401 path.
const ADMIN_KEY: &str = "issue485-admin-key-not-a-secret";

/// 100 bytes — the size named in the issue, and well inside the band that the
/// fixed 25,600-byte budget rejects (`256 - 100 = 156` charged per frame).
const CHUNK: usize = 100;

/// TOML-safe rendering of a temp path (Windows backslashes would be escape
/// sequences inside a basic string; forward slashes work everywhere).
fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

/// Three distinct free ports, held simultaneously so they cannot collide, then
/// released for the child. `Config::validate` requires all three to differ.
fn three_free_ports() -> (u16, u16, u16) {
    let held: Vec<TcpListener> = (0..3)
        .map(|_| TcpListener::bind("127.0.0.1:0").unwrap())
        .collect();
    let p: Vec<u16> = held
        .iter()
        .map(|l| l.local_addr().unwrap().port())
        .collect();
    (p[0], p[1], p[2])
}

/// Kills the child on the way out, including when a test panics — a leaked
/// server would hold its data dir and its ports for the rest of the run.
struct Server {
    child: Child,
    es_port: u16,
    _dir: tempfile::TempDir,
    output: Arc<Mutex<String>>,
}

impl Drop for Server {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn drain_into(mut r: impl Read + Send + 'static, buf: Arc<Mutex<String>>) {
    std::thread::spawn(move || {
        let mut chunk = [0u8; 4096];
        while let Ok(n) = r.read(&mut chunk) {
            if n == 0 {
                break;
            }
            buf.lock()
                .unwrap()
                .push_str(&String::from_utf8_lossy(&chunk[..n]));
        }
    });
}

/// Boot the real binary with authentication ON and wait until the ES-compat
/// listener answers its readiness probe.
async fn boot() -> Server {
    let dir = tempfile::tempdir().unwrap();
    let (rest, grpc, es) = three_free_ports();
    let config = format!(
        r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[auth]
enabled = true
admin_api_key = "{ADMIN_KEY}"

[limits]
disk_flood_stage_percent = 0
"#,
        data = toml_path(&dir.path().join("data")),
    );
    let config_path = dir.path().join("xerj.toml");
    std::fs::write(&config_path, config).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    let output = Arc::new(Mutex::new(String::new()));
    drain_into(child.stdout.take().unwrap(), output.clone());
    drain_into(child.stderr.take().unwrap(), output.clone());

    let server = Server {
        child,
        es_port: es,
        _dir: dir,
        output,
    };

    // `/health/ready` is auth-exempt and mounted on the ES-compat router.
    let client = reqwest::Client::new();
    let url = format!("http://127.0.0.1:{es}/health/ready");
    let deadline = Instant::now() + Duration::from_secs(180);
    loop {
        if let Ok(r) = client.get(&url).send().await {
            if r.status().is_success() {
                return server;
            }
        }
        assert!(
            Instant::now() < deadline,
            "xerj never became ready on :{es}\n{}",
            server.output.lock().unwrap()
        );
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

/// Prior-knowledge h2c handshake against the ES-compat listener, plus a handle
/// that resolves to the connection-level error (the `GOAWAY`, when there is
/// one) once the connection ends.
async fn connect(
    port: u16,
) -> (
    h2::client::SendRequest<Bytes>,
    tokio::sync::oneshot::Receiver<Option<String>>,
) {
    let tcp = TcpStream::connect(("127.0.0.1", port))
        .await
        .expect("connect to the ES-compat listener");
    tcp.set_nodelay(true).unwrap();
    let (client, connection) = h2::client::handshake(tcp)
        .await
        .expect("HTTP/2 handshake — the listener must speak prior-knowledge h2c");
    let (tx, rx) = tokio::sync::oneshot::channel();
    tokio::spawn(async move {
        let _ = tx.send(match connection.await {
            Ok(()) => None,
            Err(e) => Some(format!("{e} (reason: {:?})", e.reason())),
        });
    });
    (client.ready().await.expect("connection ready"), rx)
}

/// The connection-level error, or a note that the connection outlived the
/// wait. Bounded so a server that resets the *stream* without ending the
/// connection reports that instead of hanging the test.
async fn connection_error(rx: tokio::sync::oneshot::Receiver<Option<String>>) -> String {
    match tokio::time::timeout(Duration::from_secs(30), rx).await {
        Ok(Ok(Some(e))) => e,
        Ok(Ok(None)) => "the connection closed cleanly".into(),
        Ok(Err(_)) => "the connection task vanished".into(),
        Err(_) => "the connection was still open 30s later".into(),
    }
}

/// An authenticated `_bulk` whose body is chunked at 100 bytes across ~400 DATA
/// frames must return 200.
///
/// Sizing, both ways. The pre-fix budget is a fixed 25,600 bytes and a 100-byte
/// frame charges 156, so it is spent by frame 165: against `h2` 0.4.16 this
/// exact request is answered `GOAWAY ENHANCE_YOUR_CALM` mid-body, which is what
/// was watched happen before the fix went in. The post-fix budget is half the
/// 1 MiB connection window, 524,288 bytes, and ~400 frames charge at most
/// 62,556 — an eighth of it, so the pass has real margin rather than sitting on
/// a boundary. 40 KB is meanwhile an unremarkable `_bulk` by any other measure.
#[tokio::test]
async fn authenticated_bulk_chunked_at_100_bytes_completes() {
    let server = boot().await;

    let mut body = String::new();
    let mut docs = 0;
    while body.len() < 40_000 {
        body.push_str("{\"index\":{\"_index\":\"issue485\"}}\n");
        body.push_str(&format!(
            "{{\"n\":{docs},\"text\":\"a legitimate document that the client happens to stream\"}}\n"
        ));
        docs += 1;
    }
    let body = Bytes::from(body);
    let frames = body.len().div_ceil(CHUNK);

    let (mut client, conn_err) = connect(server.es_port).await;
    let request = Request::builder()
        .method("POST")
        .uri(format!("http://127.0.0.1:{}/_bulk", server.es_port))
        .header("content-type", "application/x-ndjson")
        .header("authorization", format!("ApiKey {ADMIN_KEY}"))
        .body(())
        .unwrap();
    let (response, mut send) = client.send_request(request, false).unwrap();
    send.reserve_capacity(body.len() + 1);

    // One `send_data` per DATA frame, queued back-to-back with nothing awaited
    // in between: the whole body is handed to the connection before it is
    // driven, so it goes out as one burst of ~400 small DATA frames. That is
    // the shape the issue reports — "ordinary socket writes and no artificial
    // pauses" — and it is load-bearing here. Awaiting between frames (a
    // `yield_now`, a sleep, a round trip) hands the server time to read and
    // refund each frame, and the budget is then never exhausted: with a yield
    // per frame this exact request passes on the *unfixed* stack too. A test
    // written that way proves nothing, so do not add one back.
    for (i, chunk) in body.chunks(CHUNK).enumerate() {
        if send
            .send_data(Bytes::copy_from_slice(chunk), false)
            .is_err()
        {
            let goaway = connection_error(conn_err).await;
            panic!(
                "the server cut off an authenticated {}-byte _bulk at frame {i}/{frames} \
                 (chunked at {CHUNK} bytes): {goaway}",
                body.len()
            );
        }
    }
    send.send_data(Bytes::new(), true).expect("end of stream");

    let response = match response.await {
        Ok(r) => r,
        Err(e) => {
            let goaway = connection_error(conn_err).await;
            panic!(
                "no response to an authenticated {}-byte _bulk chunked at {CHUNK} bytes \
                 ({frames} DATA frames): {e}; connection: {goaway}",
                body.len()
            );
        }
    };
    assert_eq!(
        response.status(),
        200,
        "authenticated _bulk chunked at {CHUNK} bytes answered {}",
        response.status()
    );

    let mut payload = Vec::new();
    let mut stream = response.into_body();
    while let Some(chunk) = stream.data().await {
        let chunk = chunk.expect("read the response body");
        stream.flow_control().release_capacity(chunk.len()).ok();
        payload.extend_from_slice(&chunk);
    }
    let json: serde_json::Value = serde_json::from_slice(&payload).expect("bulk response is JSON");
    assert_eq!(json["errors"], false, "{json}");
    assert_eq!(
        json["items"].as_array().map(|a| a.len()),
        Some(docs),
        "every document in the chunked body must have been indexed: {json}"
    );
}

/// The guard on the fix: the flood RUSTSEC-2026-0258 was filed about — DATA
/// frames with an empty payload, which cost the server memory and buy the
/// client nothing — must still end in `GOAWAY ENHANCE_YOUR_CALM`.
///
/// Upstream caps these with a separate counter (100 frames) rather than out of
/// the byte budget, which is why the budget could be raised for real traffic
/// without reopening this. A failure here means the protection is gone, not
/// that the fix is incomplete.
#[tokio::test]
async fn empty_data_frame_flood_is_still_refused() {
    let server = boot().await;

    let (mut client, conn_err) = connect(server.es_port).await;
    let request = Request::builder()
        .method("POST")
        .uri(format!("http://127.0.0.1:{}/_bulk", server.es_port))
        .header("content-type", "application/x-ndjson")
        .header("authorization", format!("ApiKey {ADMIN_KEY}"))
        .body(())
        .unwrap();
    let (_response, mut send) = client.send_request(request, false).unwrap();
    send.reserve_capacity(1);

    // Upstream's cap is 100 such frames. Yielding after each one lets the
    // connection task write it and read what comes back, so the client learns
    // it has been cut off soon after the server decides; without that it would
    // simply queue every frame and find out at the end.
    //
    // HOW SOON is a scheduling fact about the client, not a property of the
    // server: on a loaded 2-core CI runner the client has reached frame 538
    // before reading the GOAWAY (main 5f6fde98, PR #966), which is why this
    // test once asserted `i < 500` and flaked. The server's cap is proven by
    // the connection being torn down at all (below); the loop bound only has
    // to be far enough past 100 that "never cut off" cannot be a slow client.
    const FRAMES: usize = 20_000;
    let mut cut_off_at = None;
    for i in 0..FRAMES {
        if send.send_data(Bytes::new(), false).is_err() {
            cut_off_at = Some(i);
            break;
        }
        tokio::task::yield_now().await;
    }
    let i = cut_off_at.unwrap_or_else(|| {
        panic!("{FRAMES} empty DATA frames were accepted — the flood guard is gone")
    });
    eprintln!("empty-frame flood: client learned of the cut-off at frame {i} (server cap 100)");

    // The teardown itself is the assertion. Which *description* of it the
    // client gets is a race — the server sends `GOAWAY ENHANCE_YOUR_CALM` and
    // then closes, and a client still writing into that socket often takes the
    // `EPIPE` first — so the reason is only checked when the client managed to
    // read it. What must never happen is a clean close or no close at all.
    let goaway = connection_error(conn_err).await;
    assert!(
        !goaway.contains("closed cleanly") && !goaway.contains("still open"),
        "the empty-frame flood ended without the connection being torn down: {goaway}"
    );
    if goaway.contains("reason: Some(") {
        assert!(
            goaway.contains("ENHANCE_YOUR_CALM"),
            "empty-frame flood was stopped at frame {i} for the wrong reason: {goaway}"
        );
    }
}

use std::process::Command;

#[test]
fn xerj_index_refuses_a_directory_before_touching_disk() {
    let file_target = tempfile::tempdir().expect("tempdir for --file");
    let scratch = tempfile::tempdir().expect("tempdir for --data-dir");
    let data_dir = scratch.path().join("data");

    let out = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .args(["index", "--index", "probe", "--file"])
        .arg(file_target.path())
        .arg("--data-dir")
        .arg(&data_dir)
        .output()
        .expect("run the xerj binary");

    assert_eq!(
        out.status.code(),
        Some(2),
        "expected exit 2 for a usage error, got {:?}\nstderr:\n{}",
        out.status.code(),
        String::from_utf8_lossy(&out.stderr),
    );

    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.is_empty(), "stdout must be empty, got:\n{stdout}");

    let stderr = String::from_utf8_lossy(&out.stderr);
    let lines: Vec<&str> = stderr.lines().collect();
    assert_eq!(lines.len(), 2, "stderr must be two lines, got:\n{stderr}");
    assert!(lines[0].starts_with("error: "), "{stderr}");
    assert!(lines[0].contains("is a directory"), "{stderr}");
    assert!(lines[0].contains("xerj autoindex"), "{stderr}");
    assert!(lines[1].contains("xerj index --help"), "{stderr}");

    assert!(
        !data_dir.exists(),
        "a refused --file must not create the data dir: {}",
        data_dir.display()
    );
}

use serde_json::Value;
use std::fmt::Write as _;
use std::fs;
use std::process::Command;
use std::time::{Duration, Instant};

// XERJ_PDF_WORKER_BIN is process-global and inherited by the worker child.
// cargo runs these tests on parallel threads, so one test's set_var/remove_var
// races another's run_worker spawn (and trips std's set_var concurrency abort).
// Every test that reads or writes that env var holds this lock for its body.
// Poison-tolerant: these tests assert and may panic while holding it.
static ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

fn env_guard() -> std::sync::MutexGuard<'static, ()> {
    ENV_LOCK.lock().unwrap_or_else(|p| p.into_inner())
}

fn write_prose_pdf(path: &std::path::Path) {
    let prose = "Quarterly financial results show revenue increased twelve percent while operating margin improved. International customers and subscription renewals drove durable growth across the reporting period.";
    let stream = format!("BT /F1 12 Tf 72 720 Td ({prose}) Tj ET");
    let objects = [
        "<< /Type /Catalog /Pages 2 0 R >>".to_string(),
        "<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_string(),
        "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>".to_string(),
        format!("<< /Length {} >>\nstream\n{stream}\nendstream", stream.len()),
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>".to_string(),
    ];

    let mut pdf = String::from("%PDF-1.4\n");
    let mut offsets = Vec::new();
    for (index, object) in objects.iter().enumerate() {
        offsets.push(pdf.len());
        writeln!(pdf, "{} 0 obj\n{}\nendobj", index + 1, object).unwrap();
    }
    let xref = pdf.len();
    write!(pdf, "xref\n0 {}\n0000000000 65535 f \n", objects.len() + 1).unwrap();
    for offset in offsets {
        writeln!(pdf, "{offset:010} 00000 n ").unwrap();
    }
    write!(
        pdf,
        "trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n",
        objects.len() + 1
    )
    .unwrap();
    fs::write(path, pdf).unwrap();
}

fn write_mixed_text_blank_pdf(path: &std::path::Path) {
    let prose =
        "Financial statement prose appears on this page while the next page is intentionally blank.";
    let stream = format!("BT /F1 12 Tf 72 720 Td ({prose}) Tj ET");
    let objects = [
        "<< /Type /Catalog /Pages 2 0 R >>".to_string(),
        "<< /Type /Pages /Kids [3 0 R 6 0 R] /Count 2 >>".to_string(),
        "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>".to_string(),
        format!("<< /Length {} >>\nstream\n{stream}\nendstream", stream.len()),
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>".to_string(),
        "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << >> >>".to_string(),
    ];
    let mut pdf = String::from("%PDF-1.4\n");
    let mut offsets = Vec::new();
    for (index, object) in objects.iter().enumerate() {
        offsets.push(pdf.len());
        writeln!(pdf, "{} 0 obj\n{}\nendobj", index + 1, object).unwrap();
    }
    let xref = pdf.len();
    write!(pdf, "xref\n0 {}\n0000000000 65535 f \n", objects.len() + 1).unwrap();
    for offset in offsets {
        writeln!(pdf, "{offset:010} 00000 n ").unwrap();
    }
    write!(
        pdf,
        "trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n",
        objects.len() + 1
    )
    .unwrap();
    fs::write(path, pdf).unwrap();
}

fn run_worker(path: &std::path::Path) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("__extract-pdf")
        .arg(path)
        .output()
        .expect("start PDF worker")
}

#[test]
fn pdf_worker_is_fresh_process_deterministic_and_preserves_page_provenance() {
    let _env = env_guard();
    let temp = tempfile::tempdir().unwrap();
    let pdf = temp.path().join("quarterly-report.pdf");
    write_prose_pdf(&pdf);

    let first = run_worker(&pdf);
    let second = run_worker(&pdf);
    assert!(
        first.status.success(),
        "{}",
        String::from_utf8_lossy(&first.stderr)
    );
    assert!(
        second.status.success(),
        "{}",
        String::from_utf8_lossy(&second.stderr)
    );
    assert_eq!(first.stdout, second.stdout);

    let response: Value = serde_json::from_slice(&first.stdout).unwrap();
    assert_eq!(
        response["extractor"],
        format!("xerj-autoindex/{}", env!("CARGO_PKG_VERSION"))
    );
    assert_eq!(response["parser"], "pdf_oxide/0.3.75");
    assert!(response["containment"]
        .as_str()
        .unwrap()
        .contains("not a security sandbox"));
    let record = &response["records"][0];
    assert_eq!(record["fields"]["page"], 1);
    assert_eq!(record["locator"], "p1-s0");
    assert!(record["fields"]["body"]
        .as_str()
        .unwrap()
        .contains("operating margin improved"));
    assert_eq!(record["fields"]["pdf_pages_total"], 1);
    assert_eq!(record["fields"]["pdf_pages_with_text"], 1);
    assert_eq!(record["fields"]["pdf_pages_omitted"], 0);
}

#[test]
fn corrupt_pdf_failure_is_actionable_and_emits_no_records() {
    let _env = env_guard();
    let temp = tempfile::tempdir().unwrap();
    let pdf = temp.path().join("corrupt.pdf");
    fs::write(&pdf, b"%PDF-1.4\nnot a PDF").unwrap();

    let output = run_worker(&pdf);
    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("damaged"), "{stderr}");
    assert!(stderr.contains("password"), "{stderr}");
    assert!(stderr.contains("OCR"), "{stderr}");
}

#[test]
fn mixed_text_and_empty_pages_disclose_ocr_coverage_without_dropping_good_text() {
    let _env = env_guard();
    let temp = tempfile::tempdir().unwrap();
    let pdf = temp.path().join("mixed.pdf");
    write_mixed_text_blank_pdf(&pdf);
    let output = run_worker(&pdf);
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let response: Value = serde_json::from_slice(&output.stdout).unwrap();
    let fields = &response["records"][0]["fields"];
    assert_eq!(fields["pdf_pages_total"], 2);
    assert_eq!(fields["pdf_pages_with_text"], 1);
    assert_eq!(fields["pdf_pages_omitted"], 1);
    assert!(fields["pdf_ocr_warning"]
        .as_str()
        .unwrap()
        .contains("may need OCR"));
}

#[cfg(unix)]
#[test]
fn parent_drains_overflow_and_timeout_kills_worker_process_group() {
    let _env = env_guard();
    use std::os::unix::fs::PermissionsExt;

    let temp = tempfile::tempdir().unwrap();
    let input = temp.path().join("input.pdf");
    fs::write(&input, b"unused by fake worker").unwrap();

    let overflow = temp.path().join("overflow-worker");
    fs::write(
        &overflow,
        b"#!/bin/sh\nhead -c 34603008 /dev/zero\nexit 0\n",
    )
    .unwrap();
    fs::set_permissions(&overflow, fs::Permissions::from_mode(0o700)).unwrap();
    std::env::set_var("XERJ_PDF_WORKER_BIN", &overflow);
    let started = Instant::now();
    let mut sink = |_record| true;
    let error = xerj_autoindex::extract::pdf::extract(&input, &mut sink).unwrap_err();
    assert!(started.elapsed() < Duration::from_secs(10));
    assert!(error.to_string().contains("exceeded"), "{error:#}");

    let stderr_overflow = temp.path().join("stderr-overflow-worker");
    fs::write(
        &stderr_overflow,
        b"#!/bin/sh\nhead -c 131072 /dev/zero >&2\nexit 1\n",
    )
    .unwrap();
    fs::set_permissions(&stderr_overflow, fs::Permissions::from_mode(0o700)).unwrap();
    std::env::set_var("XERJ_PDF_WORKER_BIN", &stderr_overflow);
    let started = Instant::now();
    let error = xerj_autoindex::extract::pdf::extract(&input, &mut sink).unwrap_err();
    assert!(started.elapsed() < Duration::from_secs(10));
    assert!(
        error.to_string().contains("error output exceeded"),
        "{error:#}"
    );

    let timeout = temp.path().join("timeout-worker");
    fs::write(
        &timeout,
        b"#!/bin/sh\nsleep 60 &\necho $! > \"$2.pid\"\nwait\n",
    )
    .unwrap();
    fs::set_permissions(&timeout, fs::Permissions::from_mode(0o700)).unwrap();
    std::env::set_var("XERJ_PDF_WORKER_BIN", &timeout);
    xerj_autoindex::extract::pdf::configure_timeout(1);
    let error = xerj_autoindex::extract::pdf::extract(&input, &mut sink).unwrap_err();
    xerj_autoindex::extract::pdf::configure_timeout(120);
    std::env::remove_var("XERJ_PDF_WORKER_BIN");
    assert!(error.to_string().contains("timed out"), "{error:#}");

    let descendant = fs::read_to_string(format!("{}.pid", input.display())).unwrap();
    let proc_entry = std::path::PathBuf::from("/proc").join(descendant.trim());
    for _ in 0..50 {
        if !proc_entry.exists() {
            return;
        }
        std::thread::sleep(Duration::from_millis(20));
    }
    panic!("worker descendant {} survived timeout", descendant.trim());
}

#[cfg(unix)]
#[test]
fn pdf_worker_accepts_non_utf8_unix_paths() {
    let _env = env_guard();
    use std::os::unix::ffi::OsStringExt;

    let temp = tempfile::tempdir().unwrap();
    let name = std::ffi::OsString::from_vec(b"quarterly-\xff.pdf".to_vec());
    let pdf = temp.path().join(name);
    write_prose_pdf(&pdf);

    let output = run_worker(&pdf);
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let response: Value = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(response["records"][0]["fields"]["page"], 1);
}

/// The parent spawn path (`extract` → `pre_exec`) is what #2336 broke: a
/// refused `RLIMIT_AS` failed `Command::spawn` before `exec`, so
/// `XERJ_PDF_WORKER_BIN` never ran. This calls that path with the real
/// worker. On Linux the 1536 MiB cap is applied; on a kernel that returns
/// `EINVAL` or `EPERM` the worker still starts.
#[cfg(unix)]
#[test]
fn parent_spawn_extracts_a_small_pdf_when_the_address_space_cap_is_refused_or_applied() {
    let _env = env_guard();
    let previous = std::env::var_os("XERJ_PDF_WORKER_BIN");
    std::env::set_var("XERJ_PDF_WORKER_BIN", env!("CARGO_BIN_EXE_xerj"));
    struct Restore(Option<std::ffi::OsString>);
    impl Drop for Restore {
        fn drop(&mut self) {
            match self.0.take() {
                Some(value) => std::env::set_var("XERJ_PDF_WORKER_BIN", value),
                None => std::env::remove_var("XERJ_PDF_WORKER_BIN"),
            }
        }
    }
    let _restore = Restore(previous);

    let temp = tempfile::tempdir().unwrap();
    let pdf = temp.path().join("quarterly-report.pdf");
    write_prose_pdf(&pdf);

    let mut bodies = Vec::new();
    let mut sink = |record: xerj_autoindex::extract::RawRecord| {
        if let Some(body) = record.fields.get("body").and_then(|value| value.as_str()) {
            bodies.push(body.to_string());
        }
        true
    };
    let stats = xerj_autoindex::extract::pdf::extract(&pdf, &mut sink)
        .expect("isolated PDF parser starts even if RLIMIT_AS is refused");
    assert!(stats.records >= 1, "records={}", stats.records);
    assert!(
        bodies
            .iter()
            .any(|body| body.contains("operating margin improved")),
        "{bodies:?}"
    );
}

//! `docs/RERANK.md` says a `rerank.endpoint` with `user:password@` in it, or
//! without an `http(s)://` scheme, stops the node from starting — and that the
//! rule holds whichever place the value came from. The first draft validated
//! the config file only: `TYPESAFE_ENDPOINT='http://user:pw@…'` booted fine,
//! `GET /_xerj/rerank` showed the stripped URL, and `reqwest` would have sent
//! the userinfo as Basic auth beside the bearer key. This drives the real
//! binary with the variable set and checks it refuses, and that a clean value
//! still boots.

use std::io::Read;
use std::net::{TcpListener, TcpStream};
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

fn three_free_ports() -> (u16, u16, u16) {
    let held: Vec<TcpListener> = (0..3)
        .map(|_| TcpListener::bind("127.0.0.1:0").unwrap())
        .collect();
    let p: Vec<u16> = held
        .iter()
        .map(|l| l.local_addr().unwrap().port())
        .collect();
    (p[0], p[1], p[2])
}

fn config(dir: &std::path::Path, rest: u16, grpc: u16, es: u16) -> String {
    format!(
        r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[limits]
disk_flood_stage_percent = 0
"#,
        data = toml_path(&dir.join("data")),
    )
}

fn drain_into(mut r: impl Read, buf: Arc<Mutex<String>>) {
    let mut chunk = [0u8; 4096];
    loop {
        match r.read(&mut chunk) {
            Ok(0) => break,
            Ok(n) => buf
                .lock()
                .unwrap()
                .push_str(&String::from_utf8_lossy(&chunk[..n])),
            Err(_) => break,
        }
    }
}

struct Boot {
    exited: Option<i32>,
    es_port_open: bool,
    stderr: String,
}

/// Spawn the binary with `TYPESAFE_ENDPOINT` set and no `rerank.endpoint` in
/// the file, and wait until it exits or its ES-compat port accepts a
/// connection — whichever comes first — up to `timeout`.
fn boot_with_env_endpoint(dir: &std::path::Path, endpoint: &str, timeout: Duration) -> Boot {
    let (rest, grpc, es) = three_free_ports();
    let config_path = dir.join("xerj.toml");
    std::fs::write(&config_path, config(dir, rest, grpc, es)).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .arg("--insecure")
        .env("TYPESAFE_ENDPOINT", endpoint)
        .env_remove("TYPESAFE_API_KEY")
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");
    let stderr_buf = Arc::new(Mutex::new(String::new()));
    let err_r = child.stderr.take().expect("stderr piped");
    let err_buf_t = stderr_buf.clone();
    let err_thread = std::thread::spawn(move || drain_into(err_r, err_buf_t));

    let deadline = Instant::now() + timeout;
    let mut exited = None;
    let mut es_port_open = false;
    loop {
        if let Ok(Some(status)) = child.try_wait() {
            exited = status.code();
            break;
        }
        if TcpStream::connect(("127.0.0.1", es)).is_ok() {
            es_port_open = true;
            break;
        }
        if Instant::now() > deadline {
            break;
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    child.kill().ok();
    child.wait().ok();
    err_thread.join().ok();
    let stderr = stderr_buf.lock().unwrap().clone();
    Boot {
        exited,
        es_port_open,
        stderr,
    }
}

#[test]
fn a_credentialed_typesafe_endpoint_in_the_environment_stops_the_node() {
    let dir = tempfile::tempdir().unwrap();
    let boot = boot_with_env_endpoint(
        dir.path(),
        "http://user:pw@127.0.0.1:9/v1/systemone",
        Duration::from_secs(60),
    );
    assert!(
        !boot.es_port_open,
        "the node came up with a credentialed TYPESAFE_ENDPOINT; stderr:\n{}",
        boot.stderr
    );
    assert_ne!(
        boot.exited,
        Some(0),
        "exit status must be a failure; stderr:\n{}",
        boot.stderr
    );
    assert!(
        boot.exited.is_some(),
        "the node neither exited nor listened within the timeout; stderr:\n{}",
        boot.stderr
    );
    assert!(
        boot.stderr.contains("TYPESAFE_ENDPOINT")
            && boot.stderr.contains("must not carry credentials"),
        "the refusal names the variable and the rule; stderr:\n{}",
        boot.stderr
    );
    assert!(
        !boot.stderr.contains("user:pw@"),
        "the credential must not be echoed; stderr:\n{}",
        boot.stderr
    );
}

#[test]
fn a_non_http_typesafe_endpoint_in_the_environment_stops_the_node() {
    let dir = tempfile::tempdir().unwrap();
    let boot = boot_with_env_endpoint(
        dir.path(),
        "judge.example/v1/systemone",
        Duration::from_secs(60),
    );
    assert!(!boot.es_port_open, "stderr:\n{}", boot.stderr);
    assert!(
        boot.exited.is_some() && boot.exited != Some(0),
        "stderr:\n{}",
        boot.stderr
    );
    assert!(
        boot.stderr.contains("TYPESAFE_ENDPOINT")
            && boot.stderr.contains("absolute http:// or https:// URL"),
        "stderr:\n{}",
        boot.stderr
    );
}

/// The check must not refuse a well-formed value: the same boot with a clean
/// endpoint gets past config loading and starts listening.
#[test]
fn a_clean_typesafe_endpoint_in_the_environment_boots() {
    let dir = tempfile::tempdir().unwrap();
    let boot = boot_with_env_endpoint(
        dir.path(),
        "http://127.0.0.1:9/v1/systemone",
        Duration::from_secs(120),
    );
    assert!(
        boot.es_port_open,
        "the node did not start listening (exit {:?}); stderr:\n{}",
        boot.exited, boot.stderr
    );
}

//! Offline CLI export: success, redaction and failure publication boundaries.
use serde_json::Value;
use std::path::Path;
use std::process::{Command, Output};

fn import(input: &Path, output: &Path) -> Output {
    Command::new(env!("CARGO_BIN_EXE_xerj"))
        .args(["sessions", "import", "--format", "claude-code", "--input"])
        .arg(input)
        .arg("--output")
        .arg(output)
        .env("XERJ_DISABLE_FEEDBACK", "true")
        .output()
        .unwrap()
}

#[test]
fn sessions_cli_exports_only_redacted_conversation_and_refuses_overwrite() {
    let work = tempfile::tempdir().unwrap();
    let input = work.path().join("session.jsonl");
    std::fs::write(
        &input,
        include_str!("../../xerj-autoindex/tests/fixtures/claude-session.jsonl"),
    )
    .unwrap();
    let output = work.path().join("records.jsonl");
    let result = import(&input, &output);
    assert!(
        result.status.success(),
        "{}",
        String::from_utf8_lossy(&result.stderr)
    );
    let report: Value = serde_json::from_slice(&result.stdout).unwrap();
    assert_eq!(report["schema_version"], 1);
    assert_eq!(report["records"], 2);
    assert_eq!(report["source_lines"], 4);
    assert_eq!(report["skipped_records"], 2);
    assert_eq!(report["skipped_blocks"], 3);
    let bytes = std::fs::read(&output).unwrap();
    let text = std::str::from_utf8(&bytes).unwrap();
    assert!(text.contains("[REDACTED_EMAIL]"));
    assert!(!text.contains("owner@example.com"));
    assert!(!text.contains("DO_NOT_EXPORT"));
    let denied = import(&input, &output);
    assert_eq!(denied.status.code(), Some(1));
    assert_eq!(std::fs::read(output).unwrap(), bytes);
}

#[test]
fn sessions_cli_bad_format_is_usage_error_without_output() {
    let work = tempfile::tempdir().unwrap();
    let output = work.path().join("safe.jsonl");
    let result = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .args([
            "sessions", "import", "--format", "unknown", "--input", "unused", "--output",
        ])
        .arg(&output)
        .output()
        .unwrap();
    assert_eq!(result.status.code(), Some(2));
    assert!(!output.exists());
}

#[test]
fn sessions_cli_malformed_tail_keeps_input_and_publishes_no_partial_export() {
    let work = tempfile::tempdir().unwrap();
    let input = work.path().join("session.jsonl");
    let output = work.path().join("records.jsonl");
    let mut bytes =
        include_bytes!("../../xerj-autoindex/tests/fixtures/claude-session.jsonl").to_vec();
    bytes.extend_from_slice(b"{\"private\":\"NEVER_ECHO_PRIVATE_PAYLOAD\"");
    std::fs::write(&input, &bytes).unwrap();
    let result = import(&input, &output);
    assert_eq!(result.status.code(), Some(1));
    assert!(result.stdout.is_empty());
    let error = String::from_utf8_lossy(&result.stderr);
    assert!(error.contains("invalid JSON"), "{error}");
    assert!(!error.contains("NEVER_ECHO_PRIVATE_PAYLOAD"));
    assert!(!output.exists());
    assert_eq!(std::fs::read(input).unwrap(), bytes);
    assert_eq!(std::fs::read_dir(work.path()).unwrap().count(), 1);
}

//! `xerj … | head` must not dump core.
//!
//! The Rust runtime installs `SIG_IGN` for SIGPIPE before `main`, so a write to
//! a pipe whose reader has left returns `EPIPE`, `println!` panics on it
//! ("failed printing to stdout"), and the release profile's `panic = "abort"`
//! turns that panic into a core dump — the reported `xerj autoindex map |
//! head -80` failure, which also swallowed the command's real exit status.
//! `main` restores `SIG_DFL` so the kernel terminates us on the signal instead.
//!
//! Both tests drive `--help`: it is the only long stdout-only path that needs
//! neither a running server nor a fixture, and it prints through the same
//! `println!` that panicked.

#![cfg(unix)]

use std::io::Read;
use std::os::fd::AsRawFd;
use std::os::unix::process::ExitStatusExt;
use std::process::{Command, ExitStatus, Stdio};

fn assert_died_quietly_on_sigpipe(status: ExitStatus, stderr: &[u8]) {
    let stderr = String::from_utf8_lossy(stderr);
    assert!(
        !stderr.contains("panicked"),
        "a closed stdout must not panic; stderr was: {stderr}"
    );
    assert!(
        !status.core_dumped(),
        "a closed stdout must not dump core; status was {status:?}"
    );
    assert_eq!(
        status.signal(),
        Some(libc::SIGPIPE),
        "expected termination by SIGPIPE (shell status 141), got {status:?}; stderr: {stderr}"
    );
}

/// The reader is dropped *before* the child is spawned, so there is no window
/// in which the write could have succeeded and no timing assumption at all.
#[test]
fn stdout_pipe_without_a_reader_dies_on_sigpipe_instead_of_aborting() {
    let (reader, writer) = std::io::pipe().expect("create pipe");
    drop(reader);

    let child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--help")
        .stdout(Stdio::from(writer))
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj --help");
    let out = child.wait_with_output().expect("wait for xerj --help");

    assert_died_quietly_on_sigpipe(out.status, &out.stderr);
}

/// The reported shape: a reader that consumes a prefix and then leaves, as
/// `head -80` does. Linux-only because it needs `F_SETPIPE_SZ` to shrink the
/// pipe below the help text — that is what guarantees the child is still
/// mid-write when the reader goes, rather than having already buffered
/// everything into a 64 KiB pipe and exited 0.
#[cfg(target_os = "linux")]
#[test]
fn reader_leaving_mid_stream_dies_on_sigpipe_instead_of_aborting() {
    const PEEK: usize = 8;

    let full = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--help")
        .output()
        .expect("run xerj --help");
    let (mut reader, writer) = std::io::pipe().expect("create pipe");
    // Shrinking bottoms out at one page; the kernel reports what it did set.
    let capacity = unsafe { libc::fcntl(writer.as_raw_fd(), libc::F_SETPIPE_SZ, 4096) };
    assert!(
        capacity > 0,
        "F_SETPIPE_SZ failed: {}",
        std::io::Error::last_os_error()
    );
    // Not a flake when it trips: the child must still owe bytes after we have
    // read PEEK of them, or it finishes cleanly and proves nothing.
    assert!(
        full.stdout.len() > capacity as usize + PEEK,
        "`xerj --help` is {} bytes, which no longer exceeds the {capacity}-byte pipe — \
         drive this test with a longer-output subcommand",
        full.stdout.len()
    );

    let child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--help")
        .stdout(Stdio::from(writer))
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj --help");
    let mut prefix = [0u8; PEEK];
    reader
        .read_exact(&mut prefix)
        .expect("read the head of the stream");
    drop(reader);

    let out = child.wait_with_output().expect("wait for xerj --help");

    assert_died_quietly_on_sigpipe(out.status, &out.stderr);
}

//! Issue #465: a node that could not bind a listener must not claim it did.
//!
//! Before the fix the three listeners were bound inside `tokio::spawn`s that
//! ran *after* the banner, and a bind error there was `error!`-logged and
//! explicitly non-fatal. A node whose ES-compat port was already held by
//! another process therefore printed the full success banner — that port, this
//! data directory, `Started in {ms}` — and then stayed up serving nothing on
//! it, because `tokio::join!` returns only once all three tasks end.
//!
//! The consequence is not cosmetic. The process that *does* own the port
//! answers `GET /_cluster/health` with `green`, which is the readiness probe
//! the docs prescribe, so `xerj autoindex` proceeds and streams the user's
//! corpus into a datastore they have never heard of and cannot name. Three
//! agents hit this independently in a field study; one wrote 905 files —
//! contracts, invoices, a bank export — into a stranger's data directory and
//! got `ok=true exit=0` for it.
//!
//! These are process-level tests because the defect is invisible from inside
//! the config crate: every value was valid, the machine simply said no. The
//! first two hold a port for real and assert the binary dies; the third holds
//! nothing and asserts it still lives, so a binary that refused to start for
//! any unrelated reason cannot pass this file.

use std::io::Read;
use std::net::TcpListener;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

/// The foreign process that already owns the ES-compat port, plus two more
/// free ports for the listeners the node must still get.
///
/// The squatter is bound on `:0` and **never released** — the port number is
/// read off a listener this test still holds. Deriving it the other way round
/// (pick a free port, drop it, re-bind it) is what the first version did, and
/// it lost the race constantly: the two `#[test]`s in this file run on
/// separate threads, both drew from the same just-released ephemeral pool, and
/// whichever re-bound second got `AddrInUse` from the *other test* rather than
/// from the node under test.
///
/// `rest` and `grpc` still go through hold-then-release, which is unavoidable
/// — the child has to be the one to bind them. `Config::validate` requires all
/// three to differ, which holding them simultaneously guarantees.
fn squatter_and_two_free_ports() -> (TcpListener, u16, u16) {
    let squatter = TcpListener::bind("127.0.0.1:0").expect("hold a port for the foreign process");
    let held: Vec<TcpListener> = (0..2)
        .map(|_| TcpListener::bind("127.0.0.1:0").unwrap())
        .collect();
    let p: Vec<u16> = held
        .iter()
        .map(|l| l.local_addr().unwrap().port())
        .collect();
    (squatter, p[0], p[1])
}

/// Three distinct free ports for the control, which needs every one of them to
/// still be free when the child starts.
fn three_free_ports() -> (u16, u16, u16) {
    let held: Vec<TcpListener> = (0..3)
        .map(|_| TcpListener::bind("127.0.0.1:0").unwrap())
        .collect();
    let p: Vec<u16> = held
        .iter()
        .map(|l| l.local_addr().unwrap().port())
        .collect();
    (p[0], p[1], p[2])
}

/// TOML-safe rendering of a temp path.
fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

fn config_for(dir: &std::path::Path, rest: u16, grpc: u16, es: u16) -> String {
    format!(
        r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[limits]
disk_flood_stage_percent = 0
"#,
        data = toml_path(&dir.join("data")),
    )
}

struct Outcome {
    exited: bool,
    success: bool,
    stdout: String,
    stderr: String,
}

/// Spawn the real binary and watch it for `wait` seconds.
///
/// Returns as soon as it exits. A binary that is still running when the window
/// closes is reported as `exited: false` with whatever it has written so far —
/// the pre-fix behaviour every test here is written against.
fn run(config_body: &str, dir: &std::path::Path, wait: Duration) -> Outcome {
    let config_path = dir.join("xerj.toml");
    std::fs::write(&config_path, config_body).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .arg("--insecure")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    let deadline = Instant::now() + wait;
    let mut exited = false;
    let mut success = false;
    loop {
        match child.try_wait().expect("poll child") {
            Some(status) => {
                exited = true;
                success = status.success();
                break;
            }
            None if Instant::now() > deadline => {
                // Read the pipes BEFORE killing: the child holds the write
                // ends, and on a kill we still want everything it printed.
                break;
            }
            None => std::thread::sleep(Duration::from_millis(100)),
        }
    }

    let mut stdout = String::new();
    let mut stderr = String::new();
    if exited {
        child
            .stdout
            .take()
            .expect("stdout piped")
            .read_to_string(&mut stdout)
            .expect("read child stdout");
        child
            .stderr
            .take()
            .expect("stderr piped")
            .read_to_string(&mut stderr)
            .expect("read child stderr");
    } else {
        child.kill().ok();
        child.wait().ok();
        // The pipes are drained after the kill so `read_to_string` sees EOF.
        child
            .stdout
            .take()
            .map(|mut s| s.read_to_string(&mut stdout));
        child
            .stderr
            .take()
            .map(|mut s| s.read_to_string(&mut stderr));
    }

    Outcome {
        exited,
        success,
        stdout,
        stderr,
    }
}

/// The whole defect in one assertion: someone else owns the ES-compat port, so
/// this process must not run.
#[test]
fn a_taken_es_compat_port_ends_the_process() {
    let dir = tempfile::tempdir().unwrap();
    // A foreign process — in the field, another XERJ node, a Docker publish,
    // or a real Elasticsearch — already holds it, for the whole test.
    let (squatter, rest, grpc) = squatter_and_two_free_ports();
    let es = squatter.local_addr().unwrap().port();

    let out = run(
        &config_for(dir.path(), rest, grpc, es),
        dir.path(),
        Duration::from_secs(60),
    );

    assert!(
        out.exited,
        "xerj kept running without the ES-compat port it was configured for. \
         Whoever holds :{es} now answers the readiness probe the docs \
         prescribe, so `xerj autoindex` will write this user's corpus into \
         that node's data directory instead of theirs.\n--- stdout ---\n{}\n--- stderr ---\n{}",
        out.stdout, out.stderr
    );
    assert!(
        !out.success,
        "xerj exited 0 after failing to bind :{es}; a supervisor or a script \
         reading the exit code learns nothing.\n--- stderr ---\n{}",
        out.stderr
    );
    // Deliberately matched against the bind error and not the bare port number:
    // the first-launch console link (`http://127.0.0.1:{es}/_xerj-console/setup`)
    // also reaches stderr, and before the fix, so `stderr.contains(port)` was
    // satisfied whether or not the failure was ever reported. Verified by
    // dropping `{addr}` from `bind_listener`'s context and watching the weaker
    // form still pass.
    assert!(
        out.stderr.contains(&format!("bind 127.0.0.1:{es}")),
        "the failure must name the port that was taken, so the operator can \
         act on it without reading the log\n--- stderr ---\n{}",
        out.stderr
    );
    assert!(
        out.stderr.contains("Address already in use"),
        "the failure must say why the port could not be taken\n--- stderr ---\n{}",
        out.stderr
    );

    drop(squatter);
}

/// #1723 / #1738: the field reports hit a taken *native REST* port (8080), and
/// the error gave no route out. It must name that listener and its address,
/// keep the OS reason, say how `--port` moves it (`--port` is the ES-compat
/// port; native REST follows at BASE+1), and name the one config key that
/// moves only this listener.
#[test]
fn a_taken_native_rest_port_says_how_to_move_it() {
    let dir = tempfile::tempdir().unwrap();
    let (squatter, es, grpc) = squatter_and_two_free_ports();
    let rest = squatter.local_addr().unwrap().port();

    let out = run(
        &config_for(dir.path(), rest, grpc, es),
        dir.path(),
        Duration::from_secs(60),
    );

    assert!(
        out.exited && !out.success,
        "xerj must exit non-zero without its native REST port\n--- stderr ---\n{}",
        out.stderr
    );
    for needle in [
        format!("native REST: bind 127.0.0.1:{rest}: "),
        "Address already in use".to_string(),
        "native REST BASE+1".to_string(),
        "`rest_port`".to_string(),
        "--auto-port".to_string(),
    ] {
        assert!(
            out.stderr.contains(&needle),
            "the failure must contain {needle:?}\n--- stderr ---\n{}",
            out.stderr
        );
    }

    drop(squatter);
}

/// The banner is the lie the user acts on, so it gets its own assertion:
/// nothing that reads as success may reach stdout when a listener was lost.
#[test]
fn no_success_banner_is_printed_when_a_port_is_taken() {
    let dir = tempfile::tempdir().unwrap();
    let (squatter, rest, grpc) = squatter_and_two_free_ports();
    let es = squatter.local_addr().unwrap().port();

    let out = run(
        &config_for(dir.path(), rest, grpc, es),
        dir.path(),
        Duration::from_secs(60),
    );

    for claim in ["Started in", "Xerj Console UI", "Data dir"] {
        assert!(
            !out.stdout.contains(claim),
            "the banner printed {claim:?} for a node that never got :{es}. \
             That line is what a user checks before pointing their documents \
             at it.\n--- stdout ---\n{}",
            out.stdout
        );
    }
    assert!(
        !out.stdout.contains(&format!("ES-compat    127.0.0.1:{es}")),
        "the banner advertised an ES-compat port this process does not \
         own\n--- stdout ---\n{}",
        out.stdout
    );

    drop(squatter);
}

/// Control. With every port free the same invocation must start and stay up —
/// otherwise the two assertions above would pass against a binary that simply
/// never starts, which is not the fix.
///
/// Retried, unlike the other two: the three ports have to be released before
/// the child can bind them, so on a busy machine an unrelated process can take
/// one in between and the node would then be *correctly* refusing to start.
/// Three losses in a row is not that race any more.
#[test]
fn with_the_ports_free_it_starts_and_stays_up() {
    let dir = tempfile::tempdir().unwrap();
    let mut out = None;
    let mut es = 0;
    for _ in 0..3 {
        let (rest, grpc, port) = three_free_ports();
        es = port;
        let attempt = run(
            &config_for(dir.path(), rest, grpc, es),
            dir.path(),
            Duration::from_secs(20),
        );
        let lost_a_port = attempt.exited && attempt.stderr.contains("Address already in use");
        out = Some(attempt);
        if !lost_a_port {
            break;
        }
    }
    let out = out.expect("at least one attempt");

    assert!(
        !out.exited,
        "xerj exited on its own with all three ports free\n--- stdout ---\n{}\n--- stderr ---\n{}",
        out.stdout, out.stderr
    );
    assert!(
        out.stdout.contains("Started in"),
        "a node that bound everything must still print its banner\n--- stdout ---\n{}",
        out.stdout
    );
    assert!(
        out.stdout.contains(&format!("ES-compat    127.0.0.1:{es}")),
        "the banner must name the ES-compat port it actually holds\n--- stdout ---\n{}",
        out.stdout
    );
}

//! Issue #200: TLS must fail closed at startup.
//!
//! With `tls.enabled = true` and a certificate step that cannot deliver, the
//! REAL binary must exit non-zero before binding anything — never log the
//! failure and serve the same ports as cleartext HTTP. The pre-fix behavior
//! (downgrade + serve forever) makes every client keep working, which is
//! exactly why nobody notices; this test would then hit its deadline and
//! fail rather than hang.
//!
//! Failure shape: `Config::validate` rejects empty cert/key paths at load
//! time, so the reachable in-production failure is non-empty paths whose
//! files are missing — that routes `ensure_tls_cert` into self-signed
//! auto-generation targeting `<data_dir>/xerj.crt`, which a squatting
//! directory makes fail deterministically on every platform, for root too.

use std::io::Read;
use std::net::TcpListener;
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

/// Three distinct free ports, held simultaneously so they cannot collide,
/// then released for the child. `Config::validate` requires all three
/// listener ports to differ; free ports also mean that a regressed
/// (downgrading) binary binds cleanly and keeps serving instead of dying on
/// an unrelated bind error — which would masquerade as a pass.
fn three_free_ports() -> (u16, u16, u16) {
    let l1 = TcpListener::bind("127.0.0.1:0").unwrap();
    let l2 = TcpListener::bind("127.0.0.1:0").unwrap();
    let l3 = TcpListener::bind("127.0.0.1:0").unwrap();
    (
        l1.local_addr().unwrap().port(),
        l2.local_addr().unwrap().port(),
        l3.local_addr().unwrap().port(),
    )
}

/// TOML-safe rendering of a temp path (Windows backslashes would be escape
/// sequences inside a basic string; forward slashes work on every platform).
fn toml_path(p: &std::path::Path) -> String {
    p.to_string_lossy().replace('\\', "/")
}

#[test]
fn tls_failure_refuses_to_start_instead_of_downgrading() {
    let dir = tempfile::tempdir().unwrap();
    let data_dir = dir.path().join("data");
    // Obstruct the auto-generation target: `<data_dir>/xerj.crt` is a
    // directory, so writing the generated certificate must fail.
    std::fs::create_dir_all(data_dir.join("xerj.crt")).unwrap();

    let (rest, grpc, es) = three_free_ports();
    let config = format!(
        r#"
[server]
bind_address = "127.0.0.1"
rest_port = {rest}
grpc_port = {grpc}
es_compat_port = {es}
data_dir = "{data}"

[tls]
enabled = true
cert_path = "{root}/missing.crt"
key_path = "{root}/missing.key"
"#,
        data = toml_path(&data_dir),
        root = toml_path(dir.path()),
    );
    let config_path = dir.path().join("xerj.toml");
    std::fs::write(&config_path, config).unwrap();

    let mut child = Command::new(env!("CARGO_BIN_EXE_xerj"))
        .arg("--config")
        .arg(&config_path)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn xerj");

    // The fixed binary aborts at step 6 of startup, before metrics, engine
    // replay, or any listener — well under a second even on a 2-core CI
    // runner; 60 s is pure headroom. A regressed binary serves forever, so
    // bound the wait and treat "still running" as the downgrade it is.
    let deadline = Instant::now() + Duration::from_secs(60);
    let status = loop {
        match child.try_wait().expect("poll child") {
            Some(status) => break status,
            None if Instant::now() > deadline => {
                child.kill().ok();
                child.wait().ok();
                panic!(
                    "xerj kept running although TLS could not be established — \
                     it downgraded to plain HTTP instead of failing closed"
                );
            }
            None => std::thread::sleep(Duration::from_millis(100)),
        }
    };

    let mut stderr = String::new();
    child
        .stderr
        .take()
        .expect("stderr piped")
        .read_to_string(&mut stderr)
        .expect("read child stderr");

    assert!(
        !status.success(),
        "a TLS setup failure must exit non-zero, got {status:?}; stderr:\n{stderr}"
    );
    assert!(
        stderr.contains("TLS") && stderr.contains("refusing to start"),
        "the exit reason must name TLS and the refusal, so the operator \
         learns why the server would not come up; stderr:\n{stderr}"
    );
}

