//! Reproducible probe for selective ZBS2 row hydration.
//!
//! This is intentionally a small executable rather than a Criterion benchmark:
//! each measured decode runs in a fresh process, and canonical output is written
//! to a file so `sha256sum` can verify full/selective equality.

use serde_json::{json, Value};
use std::fs;
use std::io::Cursor;
use std::time::Instant;
use xerj_storage::stored_codec::{
    decode_stored, decode_stored_v2_rows, decode_stored_v2_rows_projected, encode_stored_v2,
    StoredV2RowHydrationResult,
};

fn process_cpu_ticks() -> u64 {
    fs::read_to_string("/proc/self/stat")
        .ok()
        .and_then(|stat| {
            // comm is parenthesized and may contain spaces, so split after its
            // final ')'. Fields 14 and 15 are then offsets 11 and 12.
            let fields = stat
                .rsplit_once(')')?
                .1
                .split_whitespace()
                .collect::<Vec<_>>();
            Some(fields.get(11)?.parse::<u64>().ok()? + fields.get(12)?.parse::<u64>().ok()?)
        })
        .unwrap_or(0)
}

fn peak_rss_bytes() -> u64 {
    fs::read_to_string("/proc/self/status")
        .ok()
        .and_then(|status| {
            status.lines().find_map(|line| {
                line.strip_prefix("VmHWM:")
                    .and_then(|tail| tail.split_whitespace().next())
                    .and_then(|kb| kb.parse::<u64>().ok())
                    .map(|kb| kb * 1024)
            })
        })
        .unwrap_or(0)
}

fn target_json(id: Value, seq_no: Value, source: Value) -> Vec<u8> {
    serde_json::to_vec(&json!({"_id": id, "_seq_no": seq_no, "_source": source})).unwrap()
}

fn measured<T>(operation: impl FnOnce() -> T) -> (T, u128, u64) {
    let cpu_before = process_cpu_ticks();
    let started = Instant::now();
    let value = operation();
    (
        value,
        started.elapsed().as_micros(),
        process_cpu_ticks().saturating_sub(cpu_before),
    )
}

fn generate(path: &str, rows: usize) {
    let body = "finance evidence sentence ".repeat(160);
    let docs: Vec<Value> = (0..rows)
        .map(|row| {
            json!({
                "_id": format!("filing-{row}"),
                "_seq_no": row,
                "_source": {
                    "company": if row % 3 == 0 { "Acme" } else { "Globex" },
                    "year": 2015 + row % 10,
                    "quarter": row % 4 + 1,
                    "page": row % 140,
                    "body": format!("{body}{row}"),
                    "nested": {"amount": row as f64 / 7.0, "tags": ["finance", "report"]}
                }
            })
        })
        .collect();
    let raw = serde_json::to_vec(&docs).unwrap();
    let encoded = encode_stored_v2(&raw);
    fs::write(path, &encoded).unwrap();
    println!(
        "rows={rows} decoded_bytes={} encoded_bytes={}",
        raw.len(),
        encoded.len()
    );
}

fn full(path: &str, output: &str) {
    let encoded = fs::read(path).unwrap();
    let (decoded, wall_us, cpu_ticks) = measured(|| decode_stored(&encoded).unwrap());
    let docs: Vec<Value> = serde_json::from_slice(&decoded).unwrap();
    let row = &docs[docs.len() - 1];
    let target = target_json(
        row["_id"].clone(),
        row["_seq_no"].clone(),
        json!({"body": row["_source"]["body"]}),
    );
    fs::write(output, &target).unwrap();
    println!(
        "mode=full rows={} decoded_bytes={} output_bytes={} wall_us={wall_us} cpu_ticks={cpu_ticks} peak_rss_bytes={}",
        docs.len(),
        decoded.len(),
        target.len(),
        peak_rss_bytes()
    );
}

fn selective(path: &str, output: &str, projected: bool) {
    let encoded = fs::read(path).unwrap();
    let ordinal = 19_999;
    let (result, wall_us, cpu_ticks) = measured(|| {
        if projected {
            decode_stored_v2_rows_projected(&encoded, &[ordinal], &["body"]).unwrap()
        } else {
            decode_stored_v2_rows(&encoded, &[ordinal]).unwrap()
        }
    });
    let StoredV2RowHydrationResult::Hydrated { rows, stats } = result else {
        panic!("fixture was not selectively hydrated")
    };
    let row = rows.into_iter().next().unwrap();
    let source = if projected {
        Value::Object(row.source)
    } else {
        json!({"body": row.source["body"]})
    };
    let target = target_json(row.id, row.seq_no, source);
    fs::write(output, &target).unwrap();
    println!(
        "mode={} rows=1 output_bytes={} visited={} selected_values={} decompressed_bytes={} wall_us={wall_us} cpu_ticks={cpu_ticks} peak_rss_bytes={}",
        if projected { "projected" } else { "row" },
        target.len(),
        stats.encoded_rows_visited,
        stats.selected_json_values,
        stats.decompressed_buffer_bytes,
        peak_rss_bytes()
    );
}

fn zstd_compare(iterations: usize) {
    let shapes = [
        (
            "repeated_text",
            b"finance evidence sentence ".repeat(160_000),
        ),
        (
            "json_numbers",
            serde_json::to_vec(&(0..200_000).map(|n| n % 4096).collect::<Vec<_>>()).unwrap(),
        ),
        (
            "packed_ids",
            (0_u32..500_000).flat_map(u32::to_le_bytes).collect(),
        ),
    ];
    for (name, bytes) in shapes {
        for implementation in ["stream", "bulk"] {
            let started = Instant::now();
            let mut size = 0;
            for _ in 0..iterations {
                let encoded = if implementation == "stream" {
                    zstd::encode_all(Cursor::new(&bytes), 3).unwrap()
                } else {
                    zstd::bulk::compress(&bytes, 3).unwrap()
                };
                size = encoded.len();
                assert_eq!(zstd::decode_all(encoded.as_slice()).unwrap(), bytes);
            }
            println!(
                "shape={name} input_bytes={} implementation={implementation} encoded_bytes={size} iterations={iterations} wall_us={}",
                bytes.len(),
                started.elapsed().as_micros()
            );
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args.get(1).map(String::as_str) {
        Some("generate") => generate(&args[2], args[3].parse().unwrap()),
        Some("full") => full(&args[2], &args[3]),
        Some("row") => selective(&args[2], &args[3], false),
        Some("projected") => selective(&args[2], &args[3], true),
        Some("zstd-compare") => zstd_compare(args[2].parse().unwrap()),
        _ => panic!(
            "generate <fixture> <rows> | full|row|projected <fixture> <output> | zstd-compare <iterations>"
        ),
    }
}

use std::time::Instant;
use xerj_storage::segment::{SectionType, SegmentReader};
use xerj_storage::stored_codec::*;
fn main() {
    let path = std::env::args().nth(1).unwrap();
    let r = SegmentReader::open(&path).unwrap();
    let raw = r.section(SectionType::Stored).unwrap().unwrap();
    println!("stored section {} bytes", raw.len());
    let t = Instant::now();
    let full = decode_stored(raw).unwrap();
    println!("decode_stored {:?} -> {} bytes", t.elapsed(), full.len());
    let n: usize = std::env::args()
        .nth(2)
        .map(|s| s.parse().unwrap())
        .unwrap_or(30000);
    let all: Vec<usize> = (0..n).collect();
    let t = Instant::now();
    let res = decode_stored_v2_rows_projected(raw, &all, &[]);
    match res {
        Ok(StoredV2RowHydrationResult::Hydrated { rows, .. }) => {
            println!("identity rows {} {:?}", rows.len(), t.elapsed())
        }
        Ok(_) => println!("other"),
        Err(e) => println!("err {e}"),
    }
    let five: Vec<usize> = vec![1, 100, 2000, 7000, n - 1];
    let t = Instant::now();
    let res = decode_stored_v2_rows(raw, &five);
    match res {
        Ok(StoredV2RowHydrationResult::Hydrated { rows, .. }) => {
            println!("5 full rows {} {:?}", rows.len(), t.elapsed())
        }
        Ok(_) => println!("other"),
        Err(e) => println!("err {e}"),
    }
    let t = Instant::now();
    let res = decode_stored_v2_rows_projected_parallel(raw, &five, None);
    match res {
        Ok(StoredV2RowHydrationResult::Hydrated { rows, .. }) => {
            println!("5 full rows PAR {} {:?}", rows.len(), t.elapsed())
        }
        Ok(_) => println!("other"),
        Err(e) => println!("err {e}"),
    }
    if let Ok(Some(names)) = stored_v2_source_column_names(raw) {
        for nm in &names {
            let t = Instant::now();
            let _ = decode_stored_v2_rows_projected(raw, &five, &[nm.as_str()]);
            let el = t.elapsed();
            if el.as_millis() > 5 {
                println!("col {nm} {:?}", el);
            }
        }
        println!("ncols {}", names.len());
    }
}

//! Pluggable storage backends.
//!
//! Every storage operation goes through [`StorageBackend`]. Two
//! implementations live here:
//!
//! - [`LocalFsBackend`] — the production local-filesystem backend.
//! - [`SimulatedObjectStore`] — a **test double**. It mirrors an object
//!   store's key hierarchy onto a local directory so the object-store code
//!   paths can be exercised in unit tests with no network and no credentials.
//!   It is not, and never was, a real object store.
//!
//! The real S3-compatible backend (Cloudflare R2, MinIO, AWS S3) lives in
//! [`crate::s3`] and talks to the service over HTTP via `aws-sdk-s3`.
//!
//! ## Operation accounting
//!
//! Object stores bill per request, and the tightest budget XERJ is expected
//! to run inside — Cloudflare R2's free tier — allows 1,000,000 Class A and
//! 10,000,000 Class B operations *per account, per month*. A backend that
//! cannot say how many requests it made cannot be operated safely inside that
//! allowance, so [`ObjectStoreOps`] counts every billed attempt and
//! [`OpBudget`] can refuse to make more. See `docs/OBJECT_STORAGE.md` for the
//! arithmetic.

use async_trait::async_trait;
use bytes::Bytes;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::SystemTime;
use tokio::io::{AsyncReadExt, AsyncSeekExt, AsyncWriteExt};
use tracing::{debug, instrument};

use crate::{Result, StorageError};

// ── FileMetadata ─────────────────────────────────────────────────────────────

/// Lightweight metadata about a stored object.
#[derive(Debug, Clone)]
pub struct FileMetadata {
    pub size: u64,
    pub modified: SystemTime,
    pub created: Option<SystemTime>,
    /// Entity tag, when the backend has one. Object stores return an ETag from
    /// `HeadObject`; local filesystems have no equivalent, so the local
    /// backends leave this `None`. Never parse it — S3 only guarantees an
    /// opaque, comparable string (it is an MD5 for single-part uploads and
    /// something else entirely for multipart ones).
    pub etag: Option<String>,
}

// ── Billing-relevant operation accounting ────────────────────────────────────

/// Which billing class an object-store request falls into.
///
/// The class names are Cloudflare R2's, because R2's free tier is the tightest
/// budget XERJ is expected to run inside. AWS S3 and MinIO price differently
/// (S3 charges per 1,000 requests; MinIO charges nothing) but the shape is the
/// same everywhere: mutating and listing calls cost several times a read.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OpClass {
    /// `PutObject`, `ListObjectsV2`, `CopyObject`, `CreateMultipartUpload`,
    /// `UploadPart`, `CompleteMultipartUpload`. The scarce one: 1,000,000 per
    /// month on R2's free tier, which is ~23 per minute for a whole account.
    ClassA,
    /// `GetObject`, `HeadObject`. 10,000,000 per month on R2's free tier.
    ClassB,
    /// `DeleteObject`, `AbortMultipartUpload` — free on R2.
    Free,
}

/// Live counters for the requests a backend has actually sent.
///
/// Counted per **billed attempt**, not per logical call: a `PutObject` that
/// fails once and succeeds on retry is billed twice by the provider and
/// counted twice here. That is why [`crate::s3::S3Backend`] disables the AWS
/// SDK's own retry layer and retries in its own code — an SDK-internal retry
/// is invisible to a counter wrapped around the call, and an undercount is
/// exactly the kind of number that produces a surprise bill.
#[derive(Debug, Default)]
pub struct ObjectStoreOps {
    class_a: AtomicU64,
    class_b: AtomicU64,
    free: AtomicU64,
    retried: AtomicU64,
    refused: AtomicU64,
    bytes_read: AtomicU64,
    bytes_written: AtomicU64,
}

/// A point-in-time copy of [`ObjectStoreOps`], safe to log or serialise.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct ObjectStoreOpsSnapshot {
    /// Billed Class A attempts (put / list / copy / multipart).
    pub class_a: u64,
    /// Billed Class B attempts (get / head).
    pub class_b: u64,
    /// Free attempts (delete / abort-multipart).
    pub free: u64,
    /// Attempts that were retries of an earlier failed attempt. Already
    /// included in the class counters above — this is how many of them were
    /// paid for twice.
    pub retried: u64,
    /// Requests the [`OpBudget`] refused to send.
    pub refused: u64,
    /// Object bytes actually transferred in (response bodies).
    pub bytes_read: u64,
    /// Object bytes actually transferred out (request bodies).
    pub bytes_written: u64,
}

impl ObjectStoreOps {
    /// Record one billed attempt of `class`, or refuse it when `budget` is
    /// already spent.
    ///
    /// The check is "increment, then compare, then roll back if over", so two
    /// threads racing on the last unit of budget can both be allowed through.
    /// That is deliberate: this is a circuit breaker, not a ledger, and a
    /// mutex on the hot path would cost more than the one extra request.
    pub fn charge(&self, class: OpClass, budget: &OpBudget) -> Result<()> {
        let (counter, cap, label) = match class {
            OpClass::ClassA => (&self.class_a, budget.max_class_a, "Class A"),
            OpClass::ClassB => (&self.class_b, budget.max_class_b, "Class B"),
            OpClass::Free => (&self.free, None, "free"),
        };
        let used = counter.fetch_add(1, Ordering::Relaxed) + 1;
        if let Some(cap) = cap {
            if used > cap {
                counter.fetch_sub(1, Ordering::Relaxed);
                self.refused.fetch_add(1, Ordering::Relaxed);
                return Err(StorageError::Backend(format!(
                    "object-store {label} operation budget exhausted: {cap} allowed, \
                     {cap} already sent by this process. Raise the budget or reduce the \
                     request rate; see docs/OBJECT_STORAGE.md for the free-tier arithmetic"
                )));
            }
        }
        Ok(())
    }

    /// Note that the attempt about to be charged is a retry of a failed one.
    pub fn note_retry(&self) {
        self.retried.fetch_add(1, Ordering::Relaxed);
    }

    /// Add to the inbound object-byte total.
    pub fn add_bytes_read(&self, n: u64) {
        self.bytes_read.fetch_add(n, Ordering::Relaxed);
    }

    /// Add to the outbound object-byte total.
    pub fn add_bytes_written(&self, n: u64) {
        self.bytes_written.fetch_add(n, Ordering::Relaxed);
    }

    /// Copy the current counters.
    pub fn snapshot(&self) -> ObjectStoreOpsSnapshot {
        ObjectStoreOpsSnapshot {
            class_a: self.class_a.load(Ordering::Relaxed),
            class_b: self.class_b.load(Ordering::Relaxed),
            free: self.free.load(Ordering::Relaxed),
            retried: self.retried.load(Ordering::Relaxed),
            refused: self.refused.load(Ordering::Relaxed),
            bytes_read: self.bytes_read.load(Ordering::Relaxed),
            bytes_written: self.bytes_written.load(Ordering::Relaxed),
        }
    }
}

/// A ceiling on how many billed requests a backend may send.
///
/// **What this is not:** a monthly quota. The counters live in one process and
/// reset when it restarts, and they know nothing about the other clients on
/// the same bucket. It is a circuit breaker that stops one runaway loop — a
/// poller wedged at 5 ms, a retry storm — from spending a month's allowance in
/// an afternoon. Staying inside a monthly free tier is an operator's
/// arithmetic (see `docs/OBJECT_STORAGE.md`); this only bounds the blast
/// radius of a bug.
#[derive(Debug, Clone, Copy, Default)]
pub struct OpBudget {
    /// Maximum Class A attempts for this process's lifetime. `None` = no cap.
    pub max_class_a: Option<u64>,
    /// Maximum Class B attempts for this process's lifetime. `None` = no cap.
    pub max_class_b: Option<u64>,
}

impl OpBudget {
    /// No ceiling. The default, because a ceiling that fires in the middle of
    /// a legitimate bulk ingest is worse than no ceiling at all — the operator
    /// has to choose the number that matches their own traffic.
    pub const fn unlimited() -> Self {
        Self {
            max_class_a: None,
            max_class_b: None,
        }
    }

    /// A ceiling of `class_a` Class A and `class_b` Class B attempts.
    pub const fn new(class_a: u64, class_b: u64) -> Self {
        Self {
            max_class_a: Some(class_a),
            max_class_b: Some(class_b),
        }
    }

    /// A fifth of Cloudflare R2's monthly free allowance: 200,000 Class A and
    /// 2,000,000 Class B.
    ///
    /// The arithmetic: R2's free tier is 1,000,000 Class A and 10,000,000
    /// Class B per month per *account*, and an account normally serves more
    /// than one process — other buckets, release downloads, other nodes. A
    /// fifth leaves four fifths for everything else, which is the point: a
    /// ceiling sized to the whole tier would let one process spend the account
    /// dry and still call itself compliant.
    ///
    /// **Read this before using it.** The counters are process-lifetime, not
    /// monthly, so this bound only approximates a monthly one for a process
    /// that lives about a month — a long-running server. For a CLI run that
    /// exits in a minute it will never fire, and for a server restarted daily
    /// it permits thirty times as much as its name suggests. It is a sane
    /// default for an operator-facing feature that would otherwise have no
    /// ceiling at all, not an accountant. The monthly arithmetic an operator
    /// actually needs is the table in `docs/OBJECT_STORAGE.md`.
    pub const fn r2_free_tier_slice() -> Self {
        Self::new(200_000, 2_000_000)
    }
}

// ── StorageBackend trait ─────────────────────────────────────────────────────

/// Abstraction over any byte-addressable storage medium.
///
/// All methods are async so they compose naturally with Tokio.  Implementations
/// **must** be `Send + Sync` so they can be shared across threads behind an
/// `Arc`.
///
/// ## Range reads
///
/// [`read_range`] is the hot path for segment access.  Local-FS reads use
/// `seek + read_exact`; S3 reads use HTTP Range headers so only the needed
/// bytes cross the network.
#[async_trait]
pub trait StorageBackend: Send + Sync + 'static {
    /// Read `length` bytes from `path` starting at `offset`.
    async fn read_range(&self, path: &str, offset: u64, length: u64) -> Result<Bytes>;

    /// Atomically write `data` to `path` (tmp-file + rename).
    async fn write(&self, path: &str, data: &[u8]) -> Result<()>;

    /// Delete the file at `path`.  Not an error if the file does not exist.
    async fn delete(&self, path: &str) -> Result<()>;

    /// Return `true` if `path` exists.
    async fn exists(&self, path: &str) -> Result<bool>;

    /// List all paths with the given `prefix`.
    async fn list(&self, prefix: &str) -> Result<Vec<String>>;

    /// Return metadata for `path`.
    async fn metadata(&self, path: &str) -> Result<FileMetadata>;

    /// Billed-request counters, for backends that send billed requests.
    ///
    /// Local-filesystem backends return `None` — there is nothing to bill.
    /// Operators reading this for a remote backend get the number that
    /// matters: how many Class A operations this process has actually spent.
    fn ops(&self) -> Option<ObjectStoreOpsSnapshot> {
        None
    }
}

// ── LocalFsBackend ───────────────────────────────────────────────────────────

/// Production-ready local-filesystem backend.
///
/// Writes are atomic: data is written to a `.tmp` file in the same directory,
/// then `rename`d into place so a crash never leaves a partial file.
#[derive(Debug, Clone)]
pub struct LocalFsBackend {
    root: PathBuf,
}

impl LocalFsBackend {
    /// Create a backend rooted at `root`.  The directory is created if absent.
    pub fn new(root: impl Into<PathBuf>) -> Result<Self> {
        let root = root.into();
        std::fs::create_dir_all(&root)?;
        Ok(Self { root })
    }

    fn abs(&self, path: &str) -> PathBuf {
        // Strip any leading slash so join works correctly
        self.root.join(path.trim_start_matches('/'))
    }
}

#[async_trait]
impl StorageBackend for LocalFsBackend {
    #[instrument(skip(self), fields(path, offset, length))]
    async fn read_range(&self, path: &str, offset: u64, length: u64) -> Result<Bytes> {
        let abs = self.abs(path);
        debug!(?abs, offset, length, "read_range");
        let mut file = tokio::fs::File::open(&abs).await?;
        if offset > 0 {
            file.seek(std::io::SeekFrom::Start(offset)).await?;
        }
        if length == u64::MAX {
            // Read to end of file.
            let mut buf = Vec::new();
            tokio::io::AsyncReadExt::read_to_end(&mut file, &mut buf).await?;
            Ok(Bytes::from(buf))
        } else {
            let mut buf = vec![0u8; length as usize];
            file.read_exact(&mut buf).await?;
            Ok(Bytes::from(buf))
        }
    }

    #[instrument(skip(self, data), fields(path, bytes = data.len()))]
    async fn write(&self, path: &str, data: &[u8]) -> Result<()> {
        let abs = self.abs(path);
        // Ensure parent directory exists
        if let Some(parent) = abs.parent() {
            tokio::fs::create_dir_all(parent).await?;
        }
        let tmp = abs.with_extension("tmp");
        {
            let mut file = tokio::fs::File::create(&tmp).await?;
            file.write_all(data).await?;
            file.flush().await?;
            file.sync_all().await?;
        }
        tokio::fs::rename(&tmp, &abs).await?;
        debug!(?abs, bytes = data.len(), "write complete");
        Ok(())
    }

    async fn delete(&self, path: &str) -> Result<()> {
        let abs = self.abs(path);
        match tokio::fs::remove_file(&abs).await {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e.into()),
        }
    }

    async fn exists(&self, path: &str) -> Result<bool> {
        let abs = self.abs(path);
        Ok(tokio::fs::try_exists(&abs).await?)
    }

    async fn list(&self, prefix: &str) -> Result<Vec<String>> {
        let abs = self.abs(prefix);
        // Walk the directory; return paths relative to self.root
        let root = self.root.clone();
        let entries = tokio::task::spawn_blocking(move || {
            let search_dir = if abs.is_dir() {
                abs
            } else {
                abs.parent()
                    .map(|p| p.to_path_buf())
                    .unwrap_or_else(|| root.clone())
            };
            let mut results = Vec::new();
            if search_dir.exists() {
                for entry in walkdir::WalkDir::new(&search_dir)
                    .min_depth(1)
                    .into_iter()
                    .flatten()
                {
                    if entry.file_type().is_file() {
                        if let Ok(rel) = entry.path().strip_prefix(&root) {
                            results.push(rel.to_string_lossy().into_owned());
                        }
                    }
                }
            }
            results
        })
        .await
        .map_err(|e| StorageError::Backend(e.to_string()))?;

        Ok(entries)
    }

    async fn metadata(&self, path: &str) -> Result<FileMetadata> {
        let abs = self.abs(path);
        let meta = tokio::fs::metadata(&abs).await?;
        Ok(FileMetadata {
            size: meta.len(),
            modified: meta.modified()?,
            created: meta.created().ok(),
            etag: None,
        })
    }
}

// ── SimulatedObjectStore (test double) ───────────────────────────────────────

/// **Test double.** An object store simulated on the local filesystem.
///
/// This is not a backend to point production data at, and it is not the S3
/// client — that is [`crate::s3::S3Backend`]. What it is: a stand-in that
/// mirrors an object store's flat key hierarchy onto a local directory, so
/// every code path that talks to [`StorageBackend`] can be unit tested with no
/// network, no credentials, no container and no cost. It was itself called
/// `S3Backend` until the real client existed, which is the whole reason for
/// the rename.
///
/// It reproduces the parts of the object-store contract the engine relies on:
///
/// - keys are flat strings with the configured prefix prepended
///   ([`object_key`](Self::object_key));
/// - [`list`](StorageBackend::list) returns keys **without** the configured
///   prefix, so its output feeds straight back into `read_range`;
/// - writes are whole-object and atomic (tmp file + rename, matching S3's
///   atomic `PutObject`);
/// - `read_range` serves a byte range, as a ranged `GetObject` would.
///
/// It deliberately does **not** reproduce: request billing, eventual
/// consistency, network errors, throttling, multipart uploads, or the
/// 1,000-key page limit on `ListObjectsV2`. A test that needs any of those
/// needs a real endpoint — MinIO locally, R2 by hand.
#[derive(Debug, Clone)]
pub struct SimulatedObjectStore {
    /// Stand-in bucket: local directory mirroring the object key hierarchy.
    base_dir: PathBuf,
    /// Bucket name. Informational only — it appears in logs, nothing else.
    pub bucket: String,
    /// Key prefix prepended to every object path.
    pub prefix: String,
}

impl SimulatedObjectStore {
    /// Create a simulated object store rooted at `base_dir`.
    ///
    /// `base_dir` plays the part of the bucket root and is created if absent.
    /// `bucket` is informational; `prefix` is applied to every key exactly as
    /// the real backend applies it.
    pub fn new(
        base_dir: impl Into<PathBuf>,
        bucket: impl Into<String>,
        prefix: impl Into<String>,
    ) -> Self {
        let dir = base_dir.into();
        std::fs::create_dir_all(&dir).ok();
        Self {
            base_dir: dir,
            bucket: bucket.into(),
            prefix: prefix.into(),
        }
    }

    /// Build the full local path for a given object `path`, applying the
    /// configured prefix so key layout mirrors what a real S3 bucket would have.
    fn abs(&self, path: &str) -> PathBuf {
        let key = self.object_key(path);
        self.base_dir.join(key.trim_start_matches('/'))
    }

    /// The configured prefix in the form it appears at the head of a key
    /// (`"xerj/"`), or `None` when no prefix is configured.
    fn key_prefix(&self) -> Option<String> {
        if self.prefix.is_empty() {
            None
        } else {
            Some(format!("{}/", self.prefix.trim_end_matches('/')))
        }
    }

    /// Prepend `self.prefix` to `path` to form the full object key.
    pub fn object_key(&self, path: &str) -> String {
        if self.prefix.is_empty() {
            path.trim_start_matches('/').to_owned()
        } else {
            format!(
                "{}/{}",
                self.prefix.trim_end_matches('/'),
                path.trim_start_matches('/')
            )
        }
    }
}

#[async_trait]
impl StorageBackend for SimulatedObjectStore {
    /// Read `length` bytes from `path` starting at `offset`.
    ///
    /// When `length == u64::MAX` the entire file is returned (equivalent to
    /// an S3 `GetObject` without a Range header).
    #[instrument(skip(self), fields(path, offset, length))]
    async fn read_range(&self, path: &str, offset: u64, length: u64) -> Result<Bytes> {
        let abs = self.abs(path);
        debug!(?abs, offset, length, "s3_sim read_range");
        let mut file = tokio::fs::File::open(&abs).await?;
        if offset > 0 {
            file.seek(std::io::SeekFrom::Start(offset)).await?;
        }
        if length == u64::MAX {
            // Read to end of file — mirrors S3 GetObject without Range header.
            let mut buf = Vec::new();
            tokio::io::AsyncReadExt::read_to_end(&mut file, &mut buf).await?;
            Ok(Bytes::from(buf))
        } else {
            let mut buf = vec![0u8; length as usize];
            file.read_exact(&mut buf).await?;
            Ok(Bytes::from(buf))
        }
    }

    /// Write `data` to `path`.
    ///
    /// Uses a tmp-file + rename for atomicity, mirroring S3's atomic PutObject
    /// semantics (S3 PUT is atomic at the object level).
    #[instrument(skip(self, data), fields(path, bytes = data.len()))]
    async fn write(&self, path: &str, data: &[u8]) -> Result<()> {
        let abs = self.abs(path);
        if let Some(parent) = abs.parent() {
            tokio::fs::create_dir_all(parent).await?;
        }
        let tmp = abs.with_extension("s3tmp");
        {
            let mut file = tokio::fs::File::create(&tmp).await?;
            file.write_all(data).await?;
            file.flush().await?;
            file.sync_all().await?;
        }
        tokio::fs::rename(&tmp, &abs).await?;
        debug!(?abs, bytes = data.len(), "s3_sim write complete");
        Ok(())
    }

    /// Delete the object at `path`.  Not an error if the object does not exist.
    async fn delete(&self, path: &str) -> Result<()> {
        let abs = self.abs(path);
        match tokio::fs::remove_file(&abs).await {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e.into()),
        }
    }

    /// Return `true` if the object at `path` exists.
    async fn exists(&self, path: &str) -> Result<bool> {
        let abs = self.abs(path);
        Ok(tokio::fs::try_exists(&abs).await?)
    }

    /// List all object keys that share the given `prefix`.
    ///
    /// Returns keys with the configured object prefix **removed**, i.e. in
    /// exactly the form `read_range` / `write` / `delete` accept. Before this
    /// was fixed the simulation returned prefixed keys, so feeding `list`
    /// output back into `read_range` double-applied the prefix and went looking
    /// for `xerj/xerj/segments/...`. The real backend has the same contract and
    /// a shared test asserts the round-trip on both.
    async fn list(&self, prefix: &str) -> Result<Vec<String>> {
        let abs = self.abs(prefix);
        let base = self.base_dir.clone();
        let strip = self.key_prefix();
        let entries = tokio::task::spawn_blocking(move || {
            let search_dir = if abs.is_dir() {
                abs
            } else {
                abs.parent()
                    .map(|p| p.to_path_buf())
                    .unwrap_or_else(|| base.clone())
            };
            let mut results = Vec::new();
            if search_dir.exists() {
                for entry in walkdir::WalkDir::new(&search_dir)
                    .min_depth(1)
                    .into_iter()
                    .flatten()
                {
                    if entry.file_type().is_file() {
                        if let Ok(rel) = entry.path().strip_prefix(&base) {
                            let key = rel.to_string_lossy().into_owned();
                            match strip.as_deref() {
                                Some(p) => {
                                    if let Some(k) = key.strip_prefix(p) {
                                        results.push(k.to_owned());
                                    }
                                }
                                None => results.push(key),
                            }
                        }
                    }
                }
            }
            results
        })
        .await
        .map_err(|e| StorageError::Backend(e.to_string()))?;

        Ok(entries)
    }

    /// Return metadata for the object at `path`.
    async fn metadata(&self, path: &str) -> Result<FileMetadata> {
        let abs = self.abs(path);
        let meta = tokio::fs::metadata(&abs).await?;
        Ok(FileMetadata {
            size: meta.len(),
            modified: meta.modified()?,
            created: meta.created().ok(),
            etag: None,
        })
    }
}

// ── walkdir (needed by list()) ────────────────────────────────────────────────
// We declare walkdir as an inline dependency; add it to Cargo.toml if not present.
// For now provide a fallback that uses std::fs::read_dir recursively.
mod walkdir {
    use std::path::{Path, PathBuf};

    pub struct WalkDir {
        root: PathBuf,
        min_depth: usize,
    }

    pub struct Entry {
        path: PathBuf,
        file_type: std::fs::FileType,
        // Recorded during the walk but not currently read by any consumer;
        // kept to mirror the real walkdir::DirEntry shape.
        #[allow(dead_code)]
        depth: usize,
    }

    impl Entry {
        pub fn path(&self) -> &Path {
            &self.path
        }
        pub fn file_type(&self) -> &std::fs::FileType {
            &self.file_type
        }
    }

    impl WalkDir {
        pub fn new(root: impl Into<PathBuf>) -> Self {
            Self {
                root: root.into(),
                min_depth: 0,
            }
        }
        pub fn min_depth(mut self, d: usize) -> Self {
            self.min_depth = d;
            self
        }
    }

    impl IntoIterator for WalkDir {
        type Item = Result<Entry, std::io::Error>;
        type IntoIter = Box<dyn Iterator<Item = Self::Item>>;

        fn into_iter(self) -> Self::IntoIter {
            let mut entries = Vec::new();
            collect(&self.root, &self.root, self.min_depth, 0, &mut entries);
            Box::new(entries.into_iter())
        }
    }

    // `root` is threaded through the recursion to mirror walkdir's API but is
    // only forwarded to nested calls, never read directly in this body.
    #[allow(clippy::only_used_in_recursion)]
    fn collect(
        root: &Path,
        dir: &Path,
        min_depth: usize,
        depth: usize,
        out: &mut Vec<Result<Entry, std::io::Error>>,
    ) {
        let rd = match std::fs::read_dir(dir) {
            Ok(r) => r,
            Err(e) => {
                out.push(Err(e));
                return;
            }
        };
        for entry in rd.flatten() {
            let path = entry.path();
            let ft = match entry.file_type() {
                Ok(t) => t,
                Err(e) => {
                    out.push(Err(e));
                    continue;
                }
            };
            if depth + 1 >= min_depth {
                out.push(Ok(Entry {
                    path: path.clone(),
                    file_type: ft,
                    depth: depth + 1,
                }));
            }
            if ft.is_dir() {
                collect(root, &path, min_depth, depth + 1, out);
            }
        }
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn local_fs_round_trip() {
        let dir = tempfile::tempdir().unwrap();
        let backend = LocalFsBackend::new(dir.path()).unwrap();

        let data = b"hello xerj storage";
        backend.write("test/hello.bin", data).await.unwrap();

        assert!(backend.exists("test/hello.bin").await.unwrap());

        let got = backend.read_range("test/hello.bin", 6, 4).await.unwrap();
        assert_eq!(&got[..], b"xerj");

        let meta = backend.metadata("test/hello.bin").await.unwrap();
        assert_eq!(meta.size, data.len() as u64);

        backend.delete("test/hello.bin").await.unwrap();
        assert!(!backend.exists("test/hello.bin").await.unwrap());
    }

    #[tokio::test]
    async fn local_fs_list() {
        let dir = tempfile::tempdir().unwrap();
        let backend = LocalFsBackend::new(dir.path()).unwrap();

        backend.write("idx/a.seg", b"A").await.unwrap();
        backend.write("idx/b.seg", b"B").await.unwrap();

        let mut paths = backend.list("idx/").await.unwrap();
        paths.sort();
        assert_eq!(paths.len(), 2);
        assert!(paths[0].contains("a.seg"));
        assert!(paths[1].contains("b.seg"));
    }

    #[tokio::test]
    async fn delete_nonexistent_is_ok() {
        let dir = tempfile::tempdir().unwrap();
        let backend = LocalFsBackend::new(dir.path()).unwrap();
        backend.delete("no/such/file.seg").await.unwrap();
    }

    // ── SimulatedObjectStore (test-double) tests ──────────────────────────────

    #[tokio::test]
    async fn simulated_object_store_round_trip() {
        let dir = tempfile::tempdir().unwrap();
        let backend = SimulatedObjectStore::new(dir.path(), "test-bucket", "xerj/");

        let data = b"hello s3 simulated storage";
        backend.write("segments/seg-001.seg", data).await.unwrap();

        assert!(backend.exists("segments/seg-001.seg").await.unwrap());

        // Range read: "s3 si" starting at offset 6
        let got = backend
            .read_range("segments/seg-001.seg", 6, 5)
            .await
            .unwrap();
        assert_eq!(&got[..], b"s3 si");

        let meta = backend.metadata("segments/seg-001.seg").await.unwrap();
        assert_eq!(meta.size, data.len() as u64);

        backend.delete("segments/seg-001.seg").await.unwrap();
        assert!(!backend.exists("segments/seg-001.seg").await.unwrap());
    }

    #[tokio::test]
    async fn simulated_object_store_full_read() {
        let dir = tempfile::tempdir().unwrap();
        let backend = SimulatedObjectStore::new(dir.path(), "test-bucket", "");

        let data = b"full read test data";
        backend.write("full.bin", data).await.unwrap();

        // read_range with u64::MAX reads the whole file
        let got = backend.read_range("full.bin", 0, u64::MAX).await.unwrap();
        assert_eq!(&got[..], data);
    }

    #[tokio::test]
    async fn simulated_object_store_list() {
        let dir = tempfile::tempdir().unwrap();
        let backend = SimulatedObjectStore::new(dir.path(), "test-bucket", "xerj/");

        backend.write("segments/a.seg", b"A").await.unwrap();
        backend.write("segments/b.seg", b"B").await.unwrap();

        let mut paths = backend.list("segments/").await.unwrap();
        paths.sort();
        // Keys come back WITHOUT the configured prefix, so list() output is
        // directly usable. The old behaviour returned "xerj/segments/a.seg",
        // which read_range() then resolved as "xerj/xerj/segments/a.seg".
        assert_eq!(paths, vec!["segments/a.seg", "segments/b.seg"]);
        for key in &paths {
            let got = backend
                .read_range(key, 0, u64::MAX)
                .await
                .unwrap_or_else(|e| {
                    panic!("list() output must feed straight into read_range(): {key}: {e}")
                });
            assert_eq!(got.len(), 1, "one byte per object");
        }
    }

    /// The same contract the real backend is held to in
    /// `tests/s3_object_store.rs::list_strips_the_prefix_so_its_output_round_trips`.
    /// Keeping it here too means the test double cannot drift away from the
    /// thing it stands in for without a test noticing.
    #[tokio::test]
    async fn simulated_object_store_list_is_scoped_to_the_prefix() {
        let dir = tempfile::tempdir().unwrap();
        let backend = SimulatedObjectStore::new(dir.path(), "test-bucket", "tenant-a/");

        backend.write("segments/a.seg", b"A").await.unwrap();
        backend.write("other/c.seg", b"C").await.unwrap();

        assert_eq!(
            backend.list("segments/").await.unwrap(),
            vec!["segments/a.seg"]
        );
        let mut all = backend.list("").await.unwrap();
        all.sort();
        assert_eq!(all, vec!["other/c.seg", "segments/a.seg"]);

        // A second tenant sharing the same bucket must see nothing of the first.
        let other = SimulatedObjectStore::new(dir.path(), "test-bucket", "tenant-b/");
        assert!(other.list("").await.unwrap().is_empty());
    }

    #[tokio::test]
    async fn simulated_object_store_delete_nonexistent_is_ok() {
        let dir = tempfile::tempdir().unwrap();
        let backend = SimulatedObjectStore::new(dir.path(), "test-bucket", "xerj/");
        backend.delete("no/such/object.seg").await.unwrap();
    }

    #[tokio::test]
    async fn simulated_object_store_object_key_prefix() {
        let backend = SimulatedObjectStore::new("/tmp", "my-bucket", "xerj/v1");
        assert_eq!(
            backend.object_key("segments/foo.seg"),
            "xerj/v1/segments/foo.seg"
        );
        // No double-slash
        assert!(!backend.object_key("/segments/foo.seg").contains("//"));
    }

    #[tokio::test]
    async fn simulated_object_store_empty_prefix() {
        let dir = tempfile::tempdir().unwrap();
        let backend = SimulatedObjectStore::new(dir.path(), "test-bucket", "");

        backend.write("plain/key.seg", b"data").await.unwrap();
        assert!(backend.exists("plain/key.seg").await.unwrap());

        let key = backend.object_key("plain/key.seg");
        assert_eq!(key, "plain/key.seg");
    }
}

//! One immutable object per segment — the ZBM1 bundle format (issue #965).
//!
//! A flushed segment is not one file: it is a FAMILY of files (`.seg`,
//! `.sidx`, `.ids`, `.dv`, the per-field FTS side-cars, ...). A hand count of
//! one real 25-field segment came to 104 files. Object stores bill per
//! request, so uploading a family one file at a time would be ~104
//! `PutObject`s per flush — 899% of Cloudflare R2's free Class-A tier at a
//! 30-second flush interval, against ~18% for one object per segment plus
//! the catalog PUT (docs/OBJECT_STORAGE.md). This module packs the whole
//! family into exactly one object.
//!
//! ## Layout
//!
//! ```text
//! [body: family file bytes, name-sorted, incl. a synthesized .complete]
//! [footer "ZBM1": id_len u16 | id | doc_count u64 | min_seq_no u64 |
//!  max_seq_no u64 | file_count u32 | per file: name_len u16 | name |
//!  offset u64 | len u64 | crc32 u32 | envelope_crc32 over preceding bytes]
//! [footer_len u32]
//! [trailer, fixed 16 bytes: footer_start u64 | format_version u32 | b"XBB1"]
//! ```
//!
//! All integers little-endian, matching the ZCM1 manifest and the `.seg`
//! container. The trailer shape and size mirror quickwit's split-footer
//! trailer (`footer_start u64` + version `u32` + 4-byte magic,
//! `quickwit-storage/src/bundle_storage.rs:156-195`, Apache-2.0 — approach
//! adapted, no code taken): a reader locates the footer from the object's
//! last 16 bytes, so a future two-range-GET cold open (trailer, then footer)
//! needs no format change. v1 always fetches the whole object.
//!
//! The footer is the existing ZCM1 flush-completion manifest
//! (`IndexStore::write_flush_completion_manifest`) EXTENDED with absolute
//! offsets: same field order, same per-file CRC-32 scheme, same envelope
//! CRC — so family naming, roles and checksum validation stay on ONE code
//! path, reused rather than reinvented. The bundle always carries a
//! `.complete` entry: it is synthesized deterministically from the family
//! (the ZCM1 bytes are a pure function of the file set), which is why a
//! merged family — which gets no ZCM1 manifest on local disk today — packs
//! identically to a post-flush one, and why a hydrated directory is
//! byte-identical to a post-flush directory (every existing recovery path
//! works on it with zero special cases).

use std::path::Path;

use crate::segment::{SegmentId, SegmentMeta};
use crate::{Result, StorageError};

/// Bundle trailer magic.
pub const BUNDLE_MAGIC: &[u8; 4] = b"XBB1";

/// Bundle format version written in the trailer. Unknown versions are a
/// typed error, never a best-effort parse (the `IncompatibleDataDir`
/// discipline: refuse, keep the data, let an operator investigate).
pub const BUNDLE_FORMAT_VERSION: u32 = 1;

/// Fixed size of the trailer: `footer_start u64` + `format_version u32` +
/// magic.
pub const BUNDLE_TRAILER_LEN: usize = 16;

/// Object key for a segment's bundle, under the backend's prefix.
pub fn bundle_key(segment_id: &str) -> String {
    format!("segments/{segment_id}.bundle")
}

/// Object key for the bucket catalog (the serialized [`IndexSnapshot`]).
pub const CATALOG_KEY: &str = "snapshot.json";

/// Object key for an auxiliary index meta file (settings, schema).
pub fn aux_key(name: &str) -> String {
    format!("meta/{name}")
}

/// Upper bound on files in one bundle — same order as ZCM1's artifact cap.
const MAX_BUNDLE_FILES: u32 = 4096;

/// One file's entry in the bundle footer.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BundleFileEntry {
    pub name: String,
    /// Absolute byte offset of the file's bytes within the bundle.
    pub offset: u64,
    pub len: u64,
    /// IEEE CRC-32 of the file's bytes (same scheme as ZCM1).
    pub crc32: u32,
}

/// Parsed bundle footer.
#[derive(Debug, Clone)]
pub struct BundleFooter {
    pub segment_id: SegmentId,
    pub doc_count: u64,
    pub min_seq_no: u64,
    pub max_seq_no: u64,
    pub files: Vec<BundleFileEntry>,
}

impl BundleFooter {
    /// The footer's file table as ZCM1 `(name, size, crc)` tuples, excluding
    /// the `.complete` entry (ZCM1 never lists itself).
    pub fn artifact_set(&self) -> Vec<(String, u64, u32)> {
        self.files
            .iter()
            .filter(|f| f.name != format!("{}.complete", self.segment_id))
            .map(|f| (f.name.clone(), f.len, f.crc32))
            .collect()
    }
}

/// ZCM1 flush-completion manifest bytes for `meta` over `artifacts`.
///
/// Shared by the on-disk writer (`write_flush_completion_manifest`) and the
/// bundle packer so the two can never diverge. `artifacts` is the family
/// EXCLUDING the `.complete` file itself, in any order.
pub fn complete_manifest_bytes(meta: &SegmentMeta, artifacts: &[(String, u64, u32)]) -> Vec<u8> {
    let mut sorted: Vec<&(String, u64, u32)> = artifacts.iter().collect();
    sorted.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    let mut body = Vec::new();
    body.extend_from_slice(b"ZCM1");
    body.extend_from_slice(&(meta.id.len() as u16).to_le_bytes());
    body.extend_from_slice(meta.id.as_bytes());
    body.extend_from_slice(&meta.doc_count.to_le_bytes());
    body.extend_from_slice(&meta.min_seq_no.to_le_bytes());
    body.extend_from_slice(&meta.max_seq_no.to_le_bytes());
    body.extend_from_slice(&(sorted.len() as u32).to_le_bytes());
    for (name, size, crc) in sorted {
        body.extend_from_slice(&(name.len() as u16).to_le_bytes());
        body.extend_from_slice(name.as_bytes());
        body.extend_from_slice(&size.to_le_bytes());
        body.extend_from_slice(&crc.to_le_bytes());
    }
    let envelope_crc = crc32fast::hash(&body);
    body.extend_from_slice(&envelope_crc.to_le_bytes());
    body
}

/// The exact set of file roles a complete segment family must cover.
///
/// Moved verbatim from `IndexStore` (issue #965: reused, not reinvented) so
/// the flush path, the manifest validator and the bundle packer/unpacker all
/// answer the same question. `artifacts` excludes any `.complete` manifest.
pub fn valid_flush_artifact_set(segment_id: &str, artifacts: &[(String, u64, u32)]) -> bool {
    let prefix = format!("{segment_id}.");
    let mut roles = std::collections::HashSet::new();
    let mut fts: std::collections::HashMap<&str, std::collections::HashSet<&str>> =
        std::collections::HashMap::new();
    for (name, _, _) in artifacts {
        if !name.starts_with(&prefix) || name.contains('/') || name.contains('\\') {
            return false;
        }
        let rest = &name[prefix.len()..];
        if matches!(
            rest,
            "seg" | "sidx" | "ids" | "dv" | "fts-layout-v2" | "fts-layout-v3" | "ftsan"
        ) {
            if !roles.insert(rest) {
                return false;
            }
            continue;
        }
        let Some((field, extension)) = rest.rsplit_once('.') else {
            return false;
        };
        if field.is_empty()
            || field.contains("..")
            || !matches!(extension, "fst" | "post" | "meta" | "norms")
            || !fts.entry(field).or_default().insert(extension)
        {
            return false;
        }
    }
    roles.contains("seg")
        && roles.contains("sidx")
        && roles.contains("ids")
        && fts.values().all(|extensions| {
            ["fst", "post", "meta", "norms"]
                .iter()
                .all(|extension| extensions.contains(extension))
        })
}

/// Streaming IEEE CRC-32 (ZCM1's checksum scheme) over a reader.
pub(crate) fn stream_crc32_from_reader(mut reader: impl std::io::Read) -> std::io::Result<u32> {
    let mut hasher = crc32fast::Hasher::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let read = reader.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(hasher.finalize())
}

fn file_crc32(path: &Path) -> std::io::Result<u32> {
    stream_crc32_from_reader(std::fs::File::open(path)?)
}

/// Pack the complete segment family living in `segments_dir` into one bundle.
///
/// The `.complete` manifest is synthesized (see the module docs) — a family
/// on disk with or without one packs to the same bytes. Known limit: the
/// bundle is built in memory (peak RSS ~ family size); a streaming build is
/// the recorded follow-up.
pub fn pack(segments_dir: &Path, meta: &SegmentMeta) -> Result<Vec<u8>> {
    let prefix = format!("{}.", meta.id);
    let mut artifacts: Vec<(String, u64, u32)> = Vec::new();
    for entry in std::fs::read_dir(segments_dir)? {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if !name.starts_with(&prefix) || name.ends_with(".complete") {
            continue;
        }
        let metadata = entry.metadata()?;
        let crc = file_crc32(&entry.path())?;
        artifacts.push((name, metadata.len(), crc));
    }
    artifacts.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    if !valid_flush_artifact_set(&meta.id, &artifacts) {
        return Err(StorageError::Backend(format!(
            "cannot pack segment {}: artifact set is incomplete or contains an unknown role",
            meta.id
        )));
    }
    // Synthesize the ZCM1 manifest and add it to the file table; a hydrated
    // directory then carries the same recovery evidence a post-flush one does.
    let complete_name = format!("{}.complete", meta.id);
    let complete_bytes = complete_manifest_bytes(meta, &artifacts);
    let complete_crc = crc32fast::hash(&complete_bytes);

    let total_body: u64 =
        artifacts.iter().map(|(_, len, _)| *len).sum::<u64>() + complete_bytes.len() as u64;
    let mut out = Vec::with_capacity(total_body as usize + 512);
    let mut entries: Vec<BundleFileEntry> = Vec::with_capacity(artifacts.len() + 1);
    // Emit files in name-sorted order — the exact sort ZCM1 uses — with the
    // synthesized `.complete` spliced in at its sorted position.
    let mut merged = artifacts
        .iter()
        .map(|(name, len, crc)| (name.clone(), *len, *crc))
        .collect::<Vec<_>>();
    merged.push((
        complete_name.clone(),
        complete_bytes.len() as u64,
        complete_crc,
    ));
    merged.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    let mut offset: u64 = 0;
    for (name, len, crc) in &merged {
        let is_complete = *name == complete_name;
        let bytes: Vec<u8> = if is_complete {
            complete_bytes.clone()
        } else {
            let path = segments_dir.join(name);
            std::fs::read(&path)?
        };
        debug_assert_eq!(bytes.len() as u64, *len, "file changed under the packer");
        out.extend_from_slice(&bytes);
        entries.push(BundleFileEntry {
            name: name.clone(),
            offset,
            len: *len,
            crc32: *crc,
        });
        offset += *len;
    }

    let footer_start = out.len() as u64;
    let mut footer = Vec::with_capacity(64 + entries.len() * 32);
    footer.extend_from_slice(b"ZBM1");
    footer.extend_from_slice(&(meta.id.len() as u16).to_le_bytes());
    footer.extend_from_slice(meta.id.as_bytes());
    footer.extend_from_slice(&meta.doc_count.to_le_bytes());
    footer.extend_from_slice(&meta.min_seq_no.to_le_bytes());
    footer.extend_from_slice(&meta.max_seq_no.to_le_bytes());
    footer.extend_from_slice(&(entries.len() as u32).to_le_bytes());
    for entry in &entries {
        footer.extend_from_slice(&(entry.name.len() as u16).to_le_bytes());
        footer.extend_from_slice(entry.name.as_bytes());
        footer.extend_from_slice(&entry.offset.to_le_bytes());
        footer.extend_from_slice(&entry.len.to_le_bytes());
        footer.extend_from_slice(&entry.crc32.to_le_bytes());
    }
    let envelope_crc = crc32fast::hash(&footer);
    footer.extend_from_slice(&envelope_crc.to_le_bytes());
    let footer_len = footer.len() as u32;
    out.extend_from_slice(&footer);
    out.extend_from_slice(&footer_len.to_le_bytes());
    out.extend_from_slice(&footer_start.to_le_bytes());
    out.extend_from_slice(&BUNDLE_FORMAT_VERSION.to_le_bytes());
    out.extend_from_slice(BUNDLE_MAGIC);
    Ok(out)
}

/// Parse and structurally validate a bundle's footer + trailer.
///
/// Returns the footer and the byte offset the footer starts at. Does NOT
/// recompute per-file CRCs — [`unpack`] does, on the write path, where a
/// mismatch must abort before any file lands.
pub fn parse_footer(bytes: &[u8]) -> Result<(BundleFooter, usize)> {
    let total = bytes.len();
    if total < BUNDLE_TRAILER_LEN + 4 {
        return Err(StorageError::Backend(format!(
            "bundle too short ({total} bytes) to carry a footer"
        )));
    }
    let trailer = &bytes[total - BUNDLE_TRAILER_LEN..];
    if &trailer[12..] != BUNDLE_MAGIC {
        return Err(StorageError::InvalidMagic {
            expected: BUNDLE_MAGIC,
            actual: trailer[12..].to_vec(),
        });
    }
    let version = u32::from_le_bytes(trailer[8..12].try_into().unwrap());
    if version != BUNDLE_FORMAT_VERSION {
        return Err(StorageError::UnsupportedVersion(version as u16));
    }
    let footer_start = u64::from_le_bytes(trailer[..8].try_into().unwrap()) as usize;
    let footer_len = u32::from_le_bytes(
        bytes[total - BUNDLE_TRAILER_LEN - 4..total - BUNDLE_TRAILER_LEN]
            .try_into()
            .unwrap(),
    ) as usize;
    let footer_end = total - BUNDLE_TRAILER_LEN - 4;
    if footer_start >= footer_end
        || footer_len != footer_end - footer_start
        || footer_end.checked_sub(footer_start).is_none()
    {
        return Err(StorageError::Backend(format!(
            "bundle trailer is inconsistent: footer_start={footer_start}, \
             footer_len={footer_len}, object_len={total}"
        )));
    }
    let footer = &mut &bytes[footer_start..footer_end];
    if footer.len() < 4 + 2 + 8 * 3 + 4 + 4 || footer[..4] != *b"ZBM1" {
        return Err(StorageError::InvalidMagic {
            expected: b"ZBM1",
            actual: footer[..4.min(footer.len())].to_vec(),
        });
    }
    // Envelope CRC covers the whole footer INCLUDING the magic — the same
    // discipline as ZCM1's validator (magic-inclusive payload).
    let envelope_crc = u32::from_le_bytes(footer[footer.len() - 4..].try_into().unwrap());
    let payload_len = footer.len() - 4;
    if crc32fast::hash(&footer[..payload_len]) != envelope_crc {
        return Err(StorageError::ChecksumMismatch {
            expected: envelope_crc,
            actual: crc32fast::hash(&footer[..payload_len]),
        });
    }
    *footer = &footer[4..payload_len];

    let take_u16 = |buf: &mut &[u8]| -> Option<u16> {
        let value = u16::from_le_bytes(buf.get(..2)?.try_into().ok()?);
        *buf = &buf[2..];
        Some(value)
    };
    let take_u32 = |buf: &mut &[u8]| -> Option<u32> {
        let value = u32::from_le_bytes(buf.get(..4)?.try_into().ok()?);
        *buf = &buf[4..];
        Some(value)
    };
    let take_u64 = |buf: &mut &[u8]| -> Option<u64> {
        let value = u64::from_le_bytes(buf.get(..8)?.try_into().ok()?);
        *buf = &buf[8..];
        Some(value)
    };

    let id_len = take_u16(footer).map(usize::from).ok_or_else(|| {
        StorageError::Backend("bundle footer truncated at segment id length".into())
    })?;
    if id_len == 0 || id_len > 128 {
        return Err(StorageError::Backend(format!(
            "bundle footer segment id length out of range: {id_len}"
        )));
    }
    let id_bytes = footer
        .get(..id_len)
        .ok_or_else(|| StorageError::Backend("bundle footer truncated at segment id".into()))?;
    *footer = &footer[id_len..];
    let segment_id = std::str::from_utf8(id_bytes)
        .map_err(|_| StorageError::Backend("bundle segment id is not UTF-8".into()))?
        .to_owned();
    let doc_count = take_u64(footer).ok_or_else(missing("doc_count"))?;
    let min_seq_no = take_u64(footer).ok_or_else(missing("min_seq_no"))?;
    let max_seq_no = take_u64(footer).ok_or_else(missing("max_seq_no"))?;
    let file_count = take_u32(footer).ok_or_else(missing("file_count"))?;
    if file_count == 0 || file_count > MAX_BUNDLE_FILES {
        return Err(StorageError::Backend(format!(
            "bundle file count out of range: {file_count}"
        )));
    }
    let mut files = Vec::with_capacity(file_count as usize);
    for _ in 0..file_count {
        let name_len = take_u16(footer)
            .map(usize::from)
            .ok_or_else(missing("name_len"))?;
        if name_len == 0 || name_len > 512 {
            return Err(StorageError::Backend(format!(
                "bundle file name length out of range: {name_len}"
            )));
        }
        let name = footer.get(..name_len).ok_or_else(missing("name"))?;
        *footer = &footer[name_len..];
        let name = std::str::from_utf8(name)
            .map_err(|_| StorageError::Backend("bundle file name is not UTF-8".into()))?
            .to_owned();
        let offset = take_u64(footer).ok_or_else(missing("offset"))?;
        let len = take_u64(footer).ok_or_else(missing("len"))?;
        let crc32 = take_u32(footer).ok_or_else(missing("crc32"))?;
        // Every file's bytes must live inside the body region, before the
        // footer — a table claiming to reach into the footer or past the
        // object end is corruption, not data.
        let end = offset.checked_add(len).ok_or_else(|| {
            StorageError::Backend(format!("bundle file {name} overflows the object size"))
        })?;
        if end > footer_start as u64 {
            return Err(StorageError::Backend(format!(
                "bundle file {name} claims bytes [{offset}, {end}) past the body region \
                 ({footer_start})"
            )));
        }
        files.push(BundleFileEntry {
            name,
            offset,
            len,
            crc32,
        });
    }
    if !footer.is_empty() {
        return Err(StorageError::Backend(format!(
            "bundle footer has {} trailing bytes after the file table",
            footer.len()
        )));
    }
    let complete_name = format!("{segment_id}.complete");
    if !files.iter().any(|f| f.name == complete_name) {
        return Err(StorageError::Backend(format!(
            "bundle for {segment_id} carries no {complete_name} manifest"
        )));
    }
    let artifact_set: Vec<(String, u64, u32)> = files
        .iter()
        .filter(|f| f.name != complete_name)
        .map(|f| (f.name.clone(), f.len, f.crc32))
        .collect();
    if !valid_flush_artifact_set(&segment_id, &artifact_set) {
        return Err(StorageError::Backend(format!(
            "bundle for {segment_id} has an incomplete artifact set or an unknown role"
        )));
    }
    Ok((
        BundleFooter {
            segment_id,
            doc_count,
            min_seq_no,
            max_seq_no,
            files,
        },
        footer_start,
    ))
}

fn missing(field: &'static str) -> impl Fn() -> StorageError {
    move || StorageError::Backend(format!("bundle footer truncated at {field}"))
}

/// Validate every per-file CRC and materialize the family into `into_dir`.
///
/// A flipped body byte surfaces as [`StorageError::ChecksumMismatch`] BEFORE
/// any file is written — never silently wrong data, never a partial family
/// visible to a later reader. Files land via `fsio::write_file_durable`
/// (unique tmp name + fsync + rename), the same discipline as every other
/// segment-side write.
pub fn unpack(bytes: &[u8], into_dir: &Path) -> Result<BundleFooter> {
    let (footer, _footer_start) = parse_footer(bytes)?;
    std::fs::create_dir_all(into_dir)?;
    // Verify EVERY file's checksum first; only then write.
    for entry in &footer.files {
        let start = entry.offset as usize;
        let end = start + entry.len as usize;
        let actual = crc32fast::hash(&bytes[start..end]);
        if actual != entry.crc32 {
            return Err(StorageError::ChecksumMismatch {
                expected: entry.crc32,
                actual,
            });
        }
    }
    for entry in &footer.files {
        let start = entry.offset as usize;
        let end = start + entry.len as usize;
        // Path safety: valid_flush_artifact_set already rejected '/', '\'
        // and anything outside the `{id}.` prefix in parse_footer.
        let path = into_dir.join(&entry.name);
        xerj_common::fsio::write_file_durable(&path, &bytes[start..end])?;
    }
    Ok(footer)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A minimal but role-complete family: seg + sidx + ids (+ synthesized
    /// .complete). Field side-cars would follow the same path.
    fn synthetic_family(dir: &Path, id: &str, doc_count: u64) -> SegmentMeta {
        std::fs::create_dir_all(dir).unwrap();
        std::fs::write(dir.join(format!("{id}.seg")), b"seg-bytes").unwrap();
        std::fs::write(dir.join(format!("{id}.sidx")), b"sidx-bytes").unwrap();
        std::fs::write(dir.join(format!("{id}.ids")), b"ids-bytes").unwrap();
        SegmentMeta {
            id: id.to_string(),
            doc_count,
            size_bytes: 24,
            min_seq_no: 1,
            max_seq_no: doc_count,
            created_at_ms: 0,
            has_tombstones: false,
            seg_path: format!("{id}.seg"),
            sidx_path: format!("{id}.sidx"),
        }
    }

    #[test]
    fn pack_unpack_round_trip_is_byte_identical() {
        let dir = tempfile::tempdir().unwrap();
        let meta = synthetic_family(dir.path(), "aaaaaaaa-bbbb-cccc-dddd-eeeeffff0001", 7);
        let bundle = pack(dir.path(), &meta).unwrap();
        let out = tempfile::tempdir().unwrap();
        let footer = unpack(&bundle, out.path()).unwrap();
        assert_eq!(footer.segment_id, meta.id);
        assert_eq!(footer.doc_count, 7);
        for name in ["seg", "sidx", "ids"] {
            let file = format!("{}.{}", meta.id, name);
            let orig = std::fs::read(dir.path().join(&file)).unwrap();
            let hydrated = std::fs::read(out.path().join(&file)).unwrap();
            assert_eq!(orig, hydrated, "{file} must round-trip byte-identical");
        }
        // The synthesized `.complete` lands too, and is a valid ZCM1
        // manifest: magic + envelope CRC over the magic-inclusive payload.
        let complete = std::fs::read(out.path().join(format!("{}.complete", meta.id))).unwrap();
        assert_eq!(&complete[..4], b"ZCM1");
        let payload_len = complete.len() - 4;
        let expected = u32::from_le_bytes(complete[payload_len..].try_into().unwrap());
        assert_eq!(crc32fast::hash(&complete[..payload_len]), expected);
        // Offsets are self-consistent: concatenating the ranges rebuilds the body.
        let mut rebuilt = Vec::new();
        let mut entries = footer.files.clone();
        entries.sort_by_key(|e| e.offset);
        for e in &entries {
            rebuilt.extend_from_slice(&bundle[e.offset as usize..(e.offset + e.len) as usize]);
        }
        let footer_start = bundle.len()
            - BUNDLE_TRAILER_LEN
            - 4
            - u32::from_le_bytes(
                bundle[bundle.len() - BUNDLE_TRAILER_LEN - 4..bundle.len() - BUNDLE_TRAILER_LEN]
                    .try_into()
                    .unwrap(),
            ) as usize;
        assert_eq!(rebuilt.len(), footer_start);
    }

    #[test]
    fn wrong_magic_is_a_typed_error() {
        let dir = tempfile::tempdir().unwrap();
        let meta = synthetic_family(dir.path(), "aaaaaaaa-bbbb-cccc-dddd-eeeeffff0002", 1);
        let mut bundle = pack(dir.path(), &meta).unwrap();
        let last = bundle.len() - 1;
        bundle[last] ^= 0xFF;
        assert!(matches!(
            parse_footer(&bundle),
            Err(StorageError::InvalidMagic { .. })
        ));
    }

    #[test]
    fn unknown_version_is_a_typed_error() {
        let dir = tempfile::tempdir().unwrap();
        let meta = synthetic_family(dir.path(), "aaaaaaaa-bbbb-cccc-dddd-eeeeffff0003", 1);
        let mut bundle = pack(dir.path(), &meta).unwrap();
        let at = bundle.len() - BUNDLE_TRAILER_LEN + 8;
        bundle[at..at + 4].copy_from_slice(&99u32.to_le_bytes());
        assert!(matches!(
            parse_footer(&bundle),
            Err(StorageError::UnsupportedVersion(v)) if v == 99
        ));
    }

    #[test]
    fn flipped_body_byte_is_a_checksum_error_and_writes_nothing() {
        let dir = tempfile::tempdir().unwrap();
        let meta = synthetic_family(dir.path(), "aaaaaaaa-bbbb-cccc-dddd-eeeeffff0004", 3);
        let mut bundle = pack(dir.path(), &meta).unwrap();
        // Flip one byte inside the first file's body region.
        bundle[3] ^= 0xFF;
        let out = tempfile::tempdir().unwrap();
        let err = unpack(&bundle, out.path()).unwrap_err();
        assert!(
            matches!(err, StorageError::ChecksumMismatch { .. }),
            "expected ChecksumMismatch, got {err:?}"
        );
        // No partial family may be visible.
        assert_eq!(std::fs::read_dir(out.path()).unwrap().count(), 0);
    }

    #[test]
    fn incomplete_family_is_refused_at_pack() {
        let dir = tempfile::tempdir().unwrap();
        let meta = synthetic_family(dir.path(), "aaaaaaaa-bbbb-cccc-dddd-eeeeffff0005", 1);
        std::fs::remove_file(dir.path().join(format!("{}.ids", meta.id))).unwrap();
        let err = pack(dir.path(), &meta).unwrap_err();
        assert!(err.to_string().contains("artifact set"), "{err}");
    }
}

//! Segment read-through cache for object-store backends.
//!
//! [`SegmentCache`] sits between the engine's segment readers and a remote
//! [`StorageBackend`] — in production [`crate::s3::S3Backend`], in tests
//! [`crate::backend::SimulatedObjectStore`]. It keeps a local copy of
//! frequently-accessed segments on NVMe so subsequent reads are served at
//! local-disk speed without a network round-trip, and without a billed request.
//!
//! ## Why the counters matter
//!
//! On a per-request-billed store the cache hit rate *is* the cost model: every
//! miss is a `GetObject`. [`SegmentCache::stats`] reports hits, misses, bytes
//! fetched and bytes served locally so that number is observable rather than
//! assumed. See `docs/OBJECT_STORAGE.md` for measured figures.
//!
//! ## Cache policy
//!
//! - **Read-through**: on a cache miss the full segment is fetched from the
//!   backend and written to the cache directory before being returned to the
//!   caller.
//! - **Write-through**: the cache is populated by [`IndexStore::flush`] at
//!   write time so that the first read after a flush is always a cache hit.
//! - **LRU eviction**: [`SegmentCache::maybe_evict`] scans the cache directory
//!   and removes the oldest files (by `mtime`) until the total size is below
//!   `max_size_bytes`.
//! - **Whole-object granularity**: a miss fetches the whole object, so a
//!   4 KiB range read of an uncached 40 MiB segment transfers 40 MiB. That is
//!   the right trade when the next read of the same segment is likely (the
//!   engine's reads are `mmap` over a whole segment) and the wrong one for a
//!   single cold probe. [`SegmentCache::get_range_uncached`] exists for the
//!   latter: it fetches just the range and caches nothing.

use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Arc;

use bytes::Bytes;
use tracing::{debug, info, warn};

use crate::backend::StorageBackend;
use crate::{Result, StorageError};

// ── SegmentCache ──────────────────────────────────────────────────────────────

/// Counters describing how much of the read traffic the cache absorbed.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct CacheStats {
    /// Reads served from the local cache directory. No billed request.
    pub hits: u64,
    /// Reads that had to go to the backend.
    pub misses: u64,
    /// Bytes fetched from the backend (what egress and request billing see).
    pub bytes_fetched: u64,
    /// Bytes served out of the local cache.
    pub bytes_served_local: u64,
    /// Fetches whose local write failed, so the next read will miss again.
    pub cache_write_failures: u64,
}

impl CacheStats {
    /// Hit rate over hits + misses, or `None` before the first read.
    pub fn hit_rate(&self) -> Option<f64> {
        let total = self.hits + self.misses;
        (total > 0).then(|| self.hits as f64 / total as f64)
    }
}

#[derive(Debug, Default)]
struct Counters {
    hits: AtomicU64,
    misses: AtomicU64,
    bytes_fetched: AtomicU64,
    bytes_served_local: AtomicU64,
    cache_write_failures: AtomicU64,
}

/// Local NVMe read-through cache for segments stored in an object-store backend.
pub struct SegmentCache {
    /// Directory where cached segment files are stored.
    cache_dir: PathBuf,
    /// Maximum total byte size of the cache before eviction triggers.
    max_size_bytes: u64,
    /// Remote backend to fetch segments from on a cache miss.
    backend: Arc<dyn StorageBackend>,
    /// Hit/miss accounting — see [`CacheStats`].
    counters: Counters,
}

impl SegmentCache {
    /// Create a new [`SegmentCache`].
    ///
    /// - `cache_dir`: local directory for cached segments (created if absent).
    /// - `max_size_bytes`: eviction threshold.
    /// - `backend`: object-store to fetch from on cache misses.
    pub fn new(
        cache_dir: impl Into<PathBuf>,
        max_size_bytes: u64,
        backend: Arc<dyn StorageBackend>,
    ) -> Self {
        let cache_dir = cache_dir.into();
        std::fs::create_dir_all(&cache_dir).ok();
        Self {
            cache_dir,
            max_size_bytes,
            backend,
            counters: Counters::default(),
        }
    }

    /// A snapshot of the hit/miss counters.
    pub fn stats(&self) -> CacheStats {
        CacheStats {
            hits: self.counters.hits.load(Ordering::Relaxed),
            misses: self.counters.misses.load(Ordering::Relaxed),
            bytes_fetched: self.counters.bytes_fetched.load(Ordering::Relaxed),
            bytes_served_local: self.counters.bytes_served_local.load(Ordering::Relaxed),
            cache_write_failures: self.counters.cache_write_failures.load(Ordering::Relaxed),
        }
    }

    /// Billed-request counters of the backend underneath, when it has any.
    pub fn backend_ops(&self) -> Option<crate::backend::ObjectStoreOpsSnapshot> {
        self.backend.ops()
    }

    /// The local path a cached object occupies.
    ///
    /// `path` is a flat object key, so a key containing `..` would otherwise
    /// escape the cache directory. Each component is checked and a traversal
    /// attempt is refused rather than normalised away.
    ///
    /// A backslash anywhere in the key is refused outright, not split on.
    /// `PathBuf::join` treats `\` as a separator on Windows, so a key like
    /// `a..\..\..\etc\x` has no `/`-delimited `..` component and would escape
    /// there while looking like one harmless filename on Linux — a guard that
    /// holds on the developer's machine and not on the shipped Windows binary
    /// is the worst kind. `xerj-autoindex`'s key classifier takes the same
    /// position (`source.rs`, `classify_key`).
    fn cache_path(&self, path: &str) -> Result<PathBuf> {
        let rel = path.trim_start_matches('/');
        if rel.is_empty() {
            return Err(StorageError::Backend("empty object key".into()));
        }
        if rel.contains('\\') {
            return Err(StorageError::Backend(format!(
                "object key contains a backslash, which is a path separator on Windows: {path}"
            )));
        }
        for component in rel.split('/') {
            if component == ".." {
                return Err(StorageError::Backend(format!(
                    "object key escapes the cache directory: {path}"
                )));
            }
        }
        Ok(self.cache_dir.join(rel))
    }

    /// Read `length` bytes at `offset`, serving from the cache when the object
    /// is already local and fetching the whole object when it is not.
    ///
    /// This is the read-through path a segment reader wants: the first range
    /// read of a segment pays one `GetObject` for the whole segment, and every
    /// later range read of it is local. Use
    /// [`get_range_uncached`](Self::get_range_uncached) when the object will not
    /// be read again and the transfer, not the round-trip, is the cost.
    pub async fn get_range(&self, path: &str, offset: u64, length: u64) -> Result<Bytes> {
        let local_path = self.cache_path(path)?;

        if local_path.exists() {
            let bytes = read_local_range(&local_path, offset, length).await?;
            self.counters.hits.fetch_add(1, Ordering::Relaxed);
            self.counters
                .bytes_served_local
                .fetch_add(bytes.len() as u64, Ordering::Relaxed);
            debug!(?local_path, offset, bytes = bytes.len(), "range cache hit");
            return Ok(bytes);
        }

        // Miss: populate the cache with the whole object, then slice it.
        let whole = self.get(path).await?;
        Ok(slice_range(&whole, offset, length))
    }

    /// Fetch one byte range straight from the backend, caching nothing.
    ///
    /// For a cold probe of a large object — a footer, a header, one skip-list
    /// block — this transfers kilobytes where [`get_range`](Self::get_range)
    /// would transfer the whole object. It costs the same single billed request
    /// either way, so the saving is bandwidth and latency, not operations.
    /// Counted as a miss, because it is one.
    pub async fn get_range_uncached(&self, path: &str, offset: u64, length: u64) -> Result<Bytes> {
        let bytes = self.backend.read_range(path, offset, length).await?;
        self.counters.misses.fetch_add(1, Ordering::Relaxed);
        self.counters
            .bytes_fetched
            .fetch_add(bytes.len() as u64, Ordering::Relaxed);
        Ok(bytes)
    }

    /// Return the data for `path`.
    ///
    /// Checks the local cache first.  On a miss, fetches from the backend,
    /// writes the result to the cache, and returns the data.
    pub async fn get(&self, path: &str) -> Result<Bytes> {
        let local_path = self.cache_path(path)?;

        if local_path.exists() {
            debug!(?local_path, "cache hit");
            let data = tokio::fs::read(&local_path).await?;
            self.counters.hits.fetch_add(1, Ordering::Relaxed);
            self.counters
                .bytes_served_local
                .fetch_add(data.len() as u64, Ordering::Relaxed);
            return Ok(Bytes::from(data));
        }

        // Cache miss — fetch from backend. One billed GetObject.
        debug!(?local_path, path, "cache miss, fetching from backend");
        let data = self.backend.read_range(path, 0, u64::MAX).await?;
        self.counters.misses.fetch_add(1, Ordering::Relaxed);
        self.counters
            .bytes_fetched
            .fetch_add(data.len() as u64, Ordering::Relaxed);

        // Cache locally. Best-effort: a cache that cannot be written is a
        // performance problem, not a correctness one, so the caller still gets
        // its bytes — but the failure is counted, because a cache silently
        // missing every time looks exactly like a cold cache.
        if let Some(parent) = local_path.parent() {
            tokio::fs::create_dir_all(parent).await.ok();
        }
        if let Err(e) = write_atomically(&local_path, &data).await {
            warn!(?local_path, error = %e, "failed to cache segment locally");
            self.counters
                .cache_write_failures
                .fetch_add(1, Ordering::Relaxed);
        } else {
            debug!(?local_path, bytes = data.len(), "segment cached");
        }

        Ok(data)
    }

    /// Remove the cached copy of `path`, if present.
    pub async fn invalidate(&self, path: &str) -> Result<()> {
        let local_path = self.cache_path(path)?;
        match tokio::fs::remove_file(&local_path).await {
            Ok(()) => Ok(()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(e) => Err(e.into()),
        }
    }

    /// Evict the oldest cached segments when the total cache size exceeds
    /// `max_size_bytes`.
    ///
    /// Files are sorted by `mtime` (oldest first) and removed until the cache
    /// is below the threshold.  This is a simple LRU approximation — a
    /// production implementation would maintain an in-memory access log.
    pub async fn maybe_evict(&self) -> Result<()> {
        let cache_dir = self.cache_dir.clone();
        let max_size = self.max_size_bytes;

        // Walk the cache directory in a blocking task (synchronous FS calls).
        let mut entries: Vec<(PathBuf, u64, std::time::SystemTime)> =
            tokio::task::spawn_blocking(move || {
                let mut out = Vec::new();
                collect_files(&cache_dir, &mut out);
                out
            })
            .await
            .map_err(|e| StorageError::Backend(e.to_string()))?;

        let total_bytes: u64 = entries.iter().map(|(_, sz, _)| sz).sum();
        if total_bytes <= max_size {
            return Ok(()); // Nothing to evict.
        }

        // Sort oldest-first.
        entries.sort_by_key(|(_, _, mtime)| *mtime);

        let mut reclaimed = 0u64;
        let target = total_bytes.saturating_sub(max_size);

        for (path, size, _) in &entries {
            if reclaimed >= target {
                break;
            }
            match tokio::fs::remove_file(path).await {
                Ok(()) => {
                    reclaimed += size;
                    info!(?path, size, "evicted cached segment");
                }
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                Err(e) => {
                    warn!(?path, error = %e, "failed to evict cached segment");
                }
            }
        }

        Ok(())
    }

    /// Return the total number of bytes currently in the cache.
    pub async fn cache_size_bytes(&self) -> Result<u64> {
        let cache_dir = self.cache_dir.clone();
        let total = tokio::task::spawn_blocking(move || {
            let mut entries = Vec::new();
            collect_files(&cache_dir, &mut entries);
            entries.iter().map(|(_, sz, _)| sz).sum::<u64>()
        })
        .await
        .map_err(|e| StorageError::Backend(e.to_string()))?;
        Ok(total)
    }
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/// Write `data` to `path` via a temp file + rename.
///
/// A plain `fs::write` leaves a half-written cache entry behind if the process
/// dies mid-write, and the next read finds a file that `exists()` and is
/// corrupt — a cache that serves short segments is worse than no cache. The
/// temp name carries the process id so two processes sharing a cache directory
/// cannot collide on it.
async fn write_atomically(path: &PathBuf, data: &[u8]) -> std::io::Result<()> {
    let tmp = path.with_extension(format!("tmp{}", std::process::id()));
    tokio::fs::write(&tmp, data).await?;
    match tokio::fs::rename(&tmp, path).await {
        Ok(()) => Ok(()),
        Err(e) => {
            let _ = tokio::fs::remove_file(&tmp).await;
            Err(e)
        }
    }
}

/// Read `length` bytes at `offset` from a local file, `u64::MAX` meaning
/// "to the end".
async fn read_local_range(path: &PathBuf, offset: u64, length: u64) -> Result<Bytes> {
    use tokio::io::{AsyncReadExt, AsyncSeekExt};
    if length == 0 {
        return Ok(Bytes::new());
    }
    let mut file = tokio::fs::File::open(path).await?;
    if offset > 0 {
        file.seek(std::io::SeekFrom::Start(offset)).await?;
    }
    if length == u64::MAX {
        let mut buf = Vec::new();
        file.read_to_end(&mut buf).await?;
        Ok(Bytes::from(buf))
    } else {
        let mut buf = vec![0u8; length as usize];
        file.read_exact(&mut buf).await?;
        Ok(Bytes::from(buf))
    }
}

/// Slice `[offset, offset+length)` out of an already-fetched object.
fn slice_range(whole: &Bytes, offset: u64, length: u64) -> Bytes {
    let start = (offset as usize).min(whole.len());
    let end = if length == u64::MAX {
        whole.len()
    } else {
        start.saturating_add(length as usize).min(whole.len())
    };
    whole.slice(start..end)
}

/// Recursively collect (path, size, mtime) for all regular files under `dir`.
fn collect_files(dir: &PathBuf, out: &mut Vec<(PathBuf, u64, std::time::SystemTime)>) {
    let rd = match std::fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return,
    };
    for entry in rd.flatten() {
        let path = entry.path();
        if let Ok(meta) = entry.metadata() {
            if meta.is_dir() {
                collect_files(&path, out);
            } else if meta.is_file() {
                let mtime = meta.modified().unwrap_or(std::time::UNIX_EPOCH);
                out.push((path, meta.len(), mtime));
            }
        }
    }
}

