    #[test]
    fn lz4_roundtrip() {
        let raw = br#"[{"_id":"a","_source":{"msg":"hello world"}}]"#;
        let encoded = encode_stored_lz4(raw);
        assert_eq!(&encoded[..4], STORED_LZ4_MAGIC);
