        let values = serde_json::to_vec(&json!(["a", "b"])).unwrap();
        let mut encoder = zstd::stream::Encoder::new(Vec::new(), STORED_ZSTD_LEVEL).unwrap();
        encoder.include_contentsize(false).unwrap();
        encoder.write_all(&values).unwrap();
