                        if point.column_index == cancel_column
                            && point.phase == StoredDecodePhase::Rows
                            && point.rows_processed == 128
                        {
                            std::ops::ControlFlow::Break(())
                        } else {
                            std::ops::ControlFlow::Continue(())
                        }
                    }
                )
                .unwrap(),
                StoredDecodeRun::Cancelled
            );
        }
    }

