    #[test]
    fn large_random_build_recall_regression() {
        // Regression for two 2026-07-12 defects that only show at scale:
        //  1. back-link pruning dropped the new node (map-miss), leaving
        //     the graph disconnected — recall@10 was 0.000 at 50k;
        //  2. closest-M neighbor selection (no diversity heuristic) gave a
        //     much flatter recall/ef curve.
        // 5k × 32-d keeps the test fast while still exercising saturated
        // back-link pruning (>> M² nodes). At ef=400 over 5k random
        // vectors, a healthy graph is essentially exact.
        struct Rng(u64);
        impl Rng {
            fn next(&mut self) -> f32 {
                // xorshift64*
                self.0 ^= self.0 >> 12;
                self.0 ^= self.0 << 25;
                self.0 ^= self.0 >> 27;
                ((self.0.wrapping_mul(0x2545F4914F6CDD1D) >> 33) as f64 / 2147483648.0) as f32 - 1.0
            }
        }
        let (n, dim, k) = (5000usize, 32usize, 10usize);
        let mut rng = Rng(0xC0FFEE);
        let vecs: Vec<Vec<f32>> = (0..n)
            .map(|_| (0..dim).map(|_| rng.next()).collect())
            .collect();
        let idx = make_index(dim);
        for (i, v) in vecs.iter().enumerate() {
            idx.insert(i as u64, v.clone()).unwrap();
        }
        // Layer-0 BFS from the entry must reach (almost) every node.
        let (_, _, _, _, reach) = idx.debug_structure();
        assert!(
            reach as f64 >= 0.99 * n as f64,
            "layer-0 graph disconnected: BFS reached {reach}/{n}"
        );

        let cos = |a: &[f32], b: &[f32]| -> f32 {
            let (mut d, mut na, mut nb) = (0f32, 0f32, 0f32);
            for i in 0..a.len() {
                d += a[i] * b[i];
                na += a[i] * a[i];
                nb += b[i] * b[i];
            }
            d / (na.sqrt() * nb.sqrt()).max(1e-12)
        };
        let mut total_hits = 0usize;
        let queries = 20usize;
        for qi in 0..queries {
            let q: Vec<f32> = (0..dim).map(|_| rng.next()).collect();
            let mut scored: Vec<(u64, f32)> = vecs
                .iter()
                .enumerate()
                .map(|(i, v)| (i as u64, cos(&q, v)))
                .collect();
            scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
            let exact: std::collections::HashSet<u64> =
                scored[..k].iter().map(|&(i, _)| i).collect();
            let got = idx.search(&q, k, 400).unwrap();
            total_hits += got.iter().filter(|(id, _)| exact.contains(id)).count();
            let _ = qi;
        }
        let recall = total_hits as f64 / (queries * k) as f64;
        assert!(
            recall >= 0.9,
            "recall@10 regression: got {recall:.3}, expected >= 0.9"
        );
    }

    /// The AVX2 compilation of the beam-search dot product must return the
    /// same bits as the scalar compilation. Lengths cover the 8-wide chunk,
    /// the remainder, and an unaligned window.
    #[test]
    fn avx2_dot_matches_scalar_bits() {
        #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
        {
            if !std::is_x86_feature_detected!("avx2") || !std::is_x86_feature_detected!("fma") {
                return;
            }
            let mut state = 0xC0FFEE_u64;
            let mut next = || {
                state = state.wrapping_mul(6364136223846793005).wrapping_add(1);
                let unit = ((state >> 33) as u32 as f32) / 2147483648.0;
                unit * 4.0 - 2.0
            };
            let mut data = Vec::with_capacity(2048);
            for _ in 0..2048 {
                data.push(next());
            }
            data[3] = 0.0;
            data[4] = -0.0;
            data[10] = 1.0e20;
            data[11] = -1.0e-20;
            for &len in &[0usize, 1, 7, 8, 9, 15, 16, 17, 31, 32, 63, 64, 768] {
                for &off in &[0usize, 1] {
                    if off + len * 2 > data.len() {
                        continue;
                    }
                    let a = &data[off..off + len];
                    let b = &data[off + len..off + len * 2];
                    let scalar = dot_scalar(a, b);
                    // SAFETY: the feature check above succeeded.
                    let avx = unsafe { dot_avx2(a, b) };
                    assert_eq!(
                        scalar.to_bits(),
                        avx.to_bits(),
                        "len {len} off {off}: scalar {scalar} avx2 {avx}"
                    );
                }
            }
        }
    }

    /// Production search (AVX2 kernel on this host, scalar otherwise) must
    /// agree bit-for-bit with the scalar eight-accumulator formula.
    #[test]
    fn search_cosine_distance_matches_scalar_dot() {
        let dim = 32usize;
        let idx = make_index(dim);
        let mut state = 0xA11CE_u64;
        let mut next = || {
            state = state.wrapping_mul(6364136223846793005).wrapping_add(1);
            (((state >> 33) as u32) as f32) / 2147483648.0 * 2.0 - 1.0
        };
        let mut vecs = Vec::new();
        for i in 0..40u64 {
            let v: Vec<f32> = (0..dim).map(|_| next()).collect();
            idx.insert(i, v.clone()).unwrap();
            vecs.push(v);
        }
        let q = vecs[0].clone();
        let q_norm = q.iter().map(|x| x * x).sum::<f32>().sqrt();
        let q_inv = if q_norm > 0.0 { 1.0 / q_norm } else { 0.0 };
        let hits = idx.search(&q, 8, 64).unwrap();
        assert!(!hits.is_empty());
        for (id, dist) in hits {
            let v = &vecs[id as usize];
            let n = v.iter().map(|x| x * x).sum::<f32>().sqrt();
            let inv = if n > 0.0 { 1.0 / n } else { 0.0 };
            let expect = 1.0 - dot_scalar(&q, v) * q_inv * inv;
            assert_eq!(
                dist.to_bits(),
                expect.to_bits(),
                "id {id}: search {dist} scalar {expect}"
            );
        }
    }
}

//! # xerj-vector
//!
//! Vector search engine for the xerj search engine.
//!
//! Provides:
//! - [`distance`] — Distance metrics (Cosine, L2, DotProduct)
//! - [`hnsw`]     — Hierarchical Navigable Small World graph index
//! - [`quantizer`]— Scalar quantization for memory-efficient storage
//! - [`search`]   — High-level KNN search interface

pub mod distance;
pub mod hnsw;
pub mod quantizer;
pub mod search;
pub mod sq8_codes;

pub use distance::{compute_distance, cosine, dot_product, l2_squared, DistanceMetric};
pub use hnsw::{HnswIndex, HnswParams};
pub use quantizer::{
    NoneQuantizer, QuantizedData, QuantizedVectors, Quantizer, Scalar8Quantizer, Sq8Params,
};
pub use search::{SearchResult, VectorSearcher};
pub use sq8_codes::Sq8CodeStore;

pub use xerj_common::Result;

//! Vector quantization for memory-efficient storage.
//!
//! Quantization trades a small accuracy loss for 4–32x memory savings.
//! The HNSW index stores quantized vectors and uses approximate distances
//! during graph traversal, with optional re-ranking using full-precision
//! vectors for the final top-K.

use serde::{Deserialize, Serialize};
use xerj_common::XerjError;

/// Result alias.
pub type Result<T> = std::result::Result<T, XerjError>;

// ─────────────────────────────────────────────────────────────────────────────
// Quantized data containers
// ─────────────────────────────────────────────────────────────────────────────

/// The result of quantizing a batch of vectors.
#[derive(Debug, Clone)]
pub struct QuantizedVectors {
    /// Number of vectors.
    pub count: usize,
    /// Vector dimensionality.
    pub dim: usize,
    /// Quantized byte data for all vectors, packed contiguously.
    pub data: QuantizedData,
}

/// The actual quantized data, parameterized by the quantization scheme.
#[derive(Debug, Clone)]
pub enum QuantizedData {
    /// Raw f32 (no quantization).
    F32(Vec<f32>),
    /// Scalar-quantized u8 values (8-bit, 4× compression).
    U8 {
        bytes: Vec<u8>,
        /// Per-dimension min values for dequantization.
        mins: Vec<f32>,
        /// Per-dimension scales for dequantization.
        scales: Vec<f32>,
    },
    /// Scalar-quantized 4-bit nibble values packed two-per-byte (8× compression).
    ///
    /// Two consecutive dimensions are packed into a single byte:
    /// - high nibble (bits 7–4) → even dimension `d`
    /// - low  nibble (bits 3–0) → odd  dimension `d+1`
    ///
    /// For odd-dimensional vectors the last dimension is stored in the high
    /// nibble of the final byte with the low nibble set to 0.
    Nibble {
        /// Packed nibble bytes; `ceil(dim/2)` bytes per vector.
        bytes: Vec<u8>,
        /// Per-dimension min values for dequantization.
        mins: Vec<f32>,
        /// Per-dimension scales for dequantization.
        scales: Vec<f32>,
    },
}

impl QuantizedData {
    /// Get the raw f32 vector for a specific index.
    pub fn get_f32(&self, idx: usize, dim: usize) -> Option<Vec<f32>> {
        match self {
            QuantizedData::F32(data) => {
                let start = idx * dim;
                let end = start + dim;
                if end <= data.len() {
                    Some(data[start..end].to_vec())
                } else {
                    None
                }
            }
            QuantizedData::U8 {
                bytes,
                mins,
                scales,
            } => {
                let start = idx * dim;
                let end = start + dim;
                if end <= bytes.len() {
                    let vec: Vec<f32> = bytes[start..end]
                        .iter()
                        .enumerate()
                        .map(|(d, &b)| mins[d] + (b as f32 / 255.0) * scales[d])
                        .collect();
                    Some(vec)
                } else {
                    None
                }
            }
            QuantizedData::Nibble {
                bytes,
                mins,
                scales,
            } => {
                // Each vector uses `ceil(dim/2)` bytes.
                let bytes_per_vec = dim.div_ceil(2);
                let byte_start = idx * bytes_per_vec;
                let byte_end = byte_start + bytes_per_vec;
                if byte_end > bytes.len() {
                    return None;
                }
                let mut vec = Vec::with_capacity(dim);
                for d in 0..dim {
                    let byte_idx = byte_start + d / 2;
                    let nibble = if d % 2 == 0 {
                        (bytes[byte_idx] >> 4) & 0x0F
                    } else {
                        bytes[byte_idx] & 0x0F
                    };
                    vec.push(mins[d] + (nibble as f32 / 15.0) * scales[d]);
                }
                Some(vec)
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Trait
// ─────────────────────────────────────────────────────────────────────────────

/// A vector quantizer that compresses f32 vectors for space-efficient storage.
pub trait Quantizer: Send + Sync {
    /// Quantize a batch of vectors.
    fn quantize(&self, vectors: &[Vec<f32>]) -> Result<QuantizedVectors>;

    /// Compute an approximate distance from a full-precision query to a
    /// quantized stored vector by index.
    fn distance(&self, query: &[f32], quantized: &QuantizedData, id: usize) -> Result<f32>;

    /// Human-readable name.
    fn name(&self) -> &'static str;
}

// ─────────────────────────────────────────────────────────────────────────────
// NoneQuantizer
// ─────────────────────────────────────────────────────────────────────────────

/// Passthrough — stores raw f32 vectors without compression.
#[derive(Debug, Default, Clone)]
pub struct NoneQuantizer;

impl Quantizer for NoneQuantizer {
    fn quantize(&self, vectors: &[Vec<f32>]) -> Result<QuantizedVectors> {
        let dim = vectors.first().map(|v| v.len()).unwrap_or(0);
        let flat: Vec<f32> = vectors.iter().flat_map(|v| v.iter().copied()).collect();
        Ok(QuantizedVectors {
            count: vectors.len(),
            dim,
            data: QuantizedData::F32(flat),
        })
    }

    fn distance(&self, query: &[f32], quantized: &QuantizedData, id: usize) -> Result<f32> {
        let dim = query.len();
        let stored = quantized
            .get_f32(id, dim)
            .ok_or_else(|| XerjError::internal(format!("NoneQuantizer: id {id} out of range")))?;

        let dist: f32 = query
            .iter()
            .zip(stored.iter())
            .map(|(&a, &b)| {
                let d = a - b;
                d * d
            })
            .sum();
        Ok(dist)
    }

    fn name(&self) -> &'static str {
        "none"
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Scalar8Quantizer
// ─────────────────────────────────────────────────────────────────────────────

/// Scalar quantization: maps each f32 dimension linearly to a u8.
///
/// Each dimension gets its own `min` and `scale` computed from the training
/// set, so the quantization is adaptive to the actual data distribution.
///
/// Encoding size: 1 byte per dimension vs. 4 bytes for f32 — 4x. On the kNN
/// serving path that ratio is realized by [`crate::sq8_codes::Sq8CodeStore`]
/// (issue #392): codes are written at ingest into a flat, slot-addressed u8
/// array with a codebook fitted from the ingested vectors, and queries score
/// against those codes instead of re-quantizing each candidate's f32 vector.
#[derive(Debug, Default, Clone)]
pub struct Scalar8Quantizer;

impl Scalar8Quantizer {
    /// Encode a single f32 dimension value to u8.
    #[inline]
    fn encode_dim(value: f32, min: f32, scale: f32) -> u8 {
        if scale == 0.0 {
            return 0;
        }
        let normalized = (value - min) / scale;
        (normalized * 255.0).round().clamp(0.0, 255.0) as u8
    }

    /// Decode a u8 back to an approximate f32.
    #[inline]
    fn decode_dim(byte: u8, min: f32, scale: f32) -> f32 {
        min + (byte as f32 / 255.0) * scale
    }
}

impl Quantizer for Scalar8Quantizer {
    fn quantize(&self, vectors: &[Vec<f32>]) -> Result<QuantizedVectors> {
        if vectors.is_empty() {
            return Ok(QuantizedVectors {
                count: 0,
                dim: 0,
                data: QuantizedData::U8 {
                    bytes: vec![],
                    mins: vec![],
                    scales: vec![],
                },
            });
        }

        let dim = vectors[0].len();

        // Compute per-dimension min and max
        let mut mins = vec![f32::MAX; dim];
        let mut maxs = vec![f32::MIN; dim];

        for vec in vectors {
            if vec.len() != dim {
                return Err(XerjError::invalid_mapping(
                    "Scalar8Quantizer: inconsistent vector dimensions",
                ));
            }
            for (d, &v) in vec.iter().enumerate() {
                if v < mins[d] {
                    mins[d] = v;
                }
                if v > maxs[d] {
                    maxs[d] = v;
                }
            }
        }

        let scales: Vec<f32> = mins
            .iter()
            .zip(maxs.iter())
            .map(|(&mn, &mx)| mx - mn)
            .collect();

        // Encode all vectors
        let mut bytes = Vec::with_capacity(vectors.len() * dim);
        for vec in vectors {
            for (d, &v) in vec.iter().enumerate() {
                bytes.push(Self::encode_dim(v, mins[d], scales[d]));
            }
        }

        Ok(QuantizedVectors {
            count: vectors.len(),
            dim,
            data: QuantizedData::U8 {
                bytes,
                mins,
                scales,
            },
        })
    }

    fn distance(&self, query: &[f32], quantized: &QuantizedData, id: usize) -> Result<f32> {
        let (bytes, mins, scales) = match quantized {
            QuantizedData::U8 {
                bytes,
                mins,
                scales,
            } => (bytes, mins, scales),
            _ => {
                return Err(XerjError::internal(
                    "Scalar8Quantizer: wrong QuantizedData variant",
                ))
            }
        };

        let dim = query.len();
        let start = id * dim;
        let end = start + dim;

        if end > bytes.len() {
            return Err(XerjError::internal(format!(
                "Scalar8Quantizer: id {id} out of range"
            )));
        }

        let dist: f32 = query
            .iter()
            .enumerate()
            .map(|(d, &q)| {
                let stored = Self::decode_dim(bytes[start + d], mins[d], scales[d]);
                let diff = q - stored;
                diff * diff
            })
            .sum();

        Ok(dist)
    }

    fn name(&self) -> &'static str {
        "scalar8"
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Sq8Params — serializable serving-path scalar8 codec
// ─────────────────────────────────────────────────────────────────────────────

/// Serializable per-dimension scalar-quantization (SQ8) parameters.
///
/// This is the serving-path counterpart to [`Scalar8Quantizer`]: instead of
/// packing a whole batch into one blob, it exposes a fitted codec cheap enough
/// to build per query.
///
/// Since issue #392 the PRIMARY serving path no longer builds one of these at
/// all: [`crate::sq8_codes::Sq8CodeStore`] holds the codes and the codebook at
/// ingest time (one flat u8 array, slot-addressed, widened and re-encoded when
/// a vector lands outside the fitted range), and kNN queries score by decoding
/// those codes. A document's score is therefore a function of the index state
/// alone, not of the candidate set the query happens to scan — the property
/// Lucene has and the per-query fit lacked.
///
/// `fit_borrowed` remains as the FALLBACK codec for the windows where the
/// store cannot serve — the open-time walk has not converged yet, a
/// publication is racing source visibility, or coverage is broken by a
/// wrong-dimension write. There the brute-force scan fits one of these over
/// exactly the candidate vectors it is about to score, quantizes each
/// candidate's current vector through it, dequantizes straight back, and drops
/// it. That keeps the #371 guarantee — **no SQ8 state outlives the query**, so
/// an updated document can never be scored on a stale code — at the cost that
/// scores in that fallback window depend on the candidate set (each by at most
/// SQ8's own 1/255 quantization step).
///
/// History (#371): both a per-document `doc_id -> Vec<u8>` code map and a
/// per-field cached codebook were tried before this type existed, and both
/// were write-once in practice: the map never recomputed a document's codes
/// after an update, and the codebook, fitted from the first ~1000 vectors a
/// field was ever scanned with, silently *clamped* every later vector into
/// that range — so a document overwritten with its own negation decoded
/// straight back to its old value and kept ranking first at cosine 1.000000.
/// The ingest-time store does not repeat that defect class structurally: an
/// out-of-range value extends the range and every live code is re-encoded
/// through a decode/encode round trip (each stored value moves by at most the
/// new quantization step), so clamping cannot occur.
///
/// `mins[d]`/`scales[d]` are the per-dimension minimum and range (`max-min`)
/// observed in the fitting sample. `encode` maps `v[d]` linearly to a u8 in
/// `[0,255]`; `decode` reverses it. A zero scale (constant dimension) encodes
/// to 0 and decodes back to `min`. The encode/decode math is bit-for-bit
/// identical to [`Scalar8Quantizer`]'s private `encode_dim`/`decode_dim`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Sq8Params {
    /// Per-dimension minimum value.
    pub mins: Vec<f32>,
    /// Per-dimension scale (`max - min`).
    pub scales: Vec<f32>,
}

impl Sq8Params {
    /// Fit per-dimension min/max over `sample`.
    ///
    /// `dim` is the required vector dimensionality; sample vectors of a
    /// different length are skipped. If no usable vector is present the
    /// params degenerate to zero scale (every code becomes 0, decoding to 0).
    pub fn fit(sample: &[Vec<f32>], dim: usize) -> Sq8Params {
        Sq8Params::fit_borrowed(sample.iter().map(|v| v.as_slice()), dim)
    }

    /// Fit per-dimension min/max over borrowed vectors.
    ///
    /// Identical math to [`Sq8Params::fit`], without requiring the caller to
    /// own the fitting sample. The kNN serving path fits over exactly the
    /// candidate vectors it is about to encode — which it already holds — so
    /// this lets it do that without copying the candidate set to build a
    /// sample. Fitting over the encoded set is also what makes clamping
    /// impossible on that path: every value encoded is inside `[min,max]` by
    /// construction (#371).
    pub fn fit_borrowed<'a, I>(sample: I, dim: usize) -> Sq8Params
    where
        I: IntoIterator<Item = &'a [f32]>,
    {
        let mut mins = vec![f32::MAX; dim];
        let mut maxs = vec![f32::MIN; dim];
        let mut seen = false;
        for v in sample {
            if v.len() != dim {
                continue;
            }
            seen = true;
            for (d, &x) in v.iter().enumerate() {
                if x < mins[d] {
                    mins[d] = x;
                }
                if x > maxs[d] {
                    maxs[d] = x;
                }
            }
        }
        if !seen {
            mins = vec![0.0; dim];
            maxs = vec![0.0; dim];
        }
        let scales = mins
            .iter()
            .zip(maxs.iter())
            .map(|(&mn, &mx)| mx - mn)
            .collect();
        Sq8Params { mins, scales }
    }

    /// Vector dimensionality this codec was fitted for.
    #[inline]
    pub fn dim(&self) -> usize {
        self.mins.len()
    }

    /// Encode a full-precision vector to one u8 per dimension.
    #[inline]
    pub fn encode(&self, v: &[f32]) -> Vec<u8> {
        let mut out = vec![0u8; v.len()];
        self.encode_into(v, &mut out);
        out
    }

    /// Encode into a caller-provided buffer, avoiding per-document allocation
    /// on the hot kNN scan. `out` must be at least `v.len()` long.
    ///
    /// This is the counterpart to [`Sq8Params::decode_into`]: the scan
    /// quantizes each candidate's current vector and dequantizes it straight
    /// back, so a `scalar8` score is computed from 1-byte-per-dimension codes
    /// without anything having to cache those codes per document.
    #[inline]
    pub fn encode_into(&self, v: &[f32], out: &mut [u8]) {
        for (d, &x) in v.iter().enumerate() {
            let min = self.mins.get(d).copied().unwrap_or(0.0);
            let scale = self.scales.get(d).copied().unwrap_or(0.0);
            if scale == 0.0 {
                out[d] = 0u8;
                continue;
            }
            let normalized = (x - min) / scale;
            out[d] = (normalized * 255.0).round().clamp(0.0, 255.0) as u8;
        }
    }

    /// Decode a code slice back to approximate f32 values (allocating).
    #[inline]
    pub fn decode(&self, codes: &[u8]) -> Vec<f32> {
        let mut out = vec![0.0f32; codes.len()];
        self.decode_into(codes, &mut out);
        out
    }

    /// Decode into a caller-provided buffer, avoiding per-score allocation on
    /// the hot kNN scan. `out` must be at least `codes.len()` long.
    #[inline]
    pub fn decode_into(&self, codes: &[u8], out: &mut [f32]) {
        for (d, &b) in codes.iter().enumerate() {
            let min = self.mins.get(d).copied().unwrap_or(0.0);
            let scale = self.scales.get(d).copied().unwrap_or(0.0);
            out[d] = min + (b as f32 / 255.0) * scale;
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Scalar4Quantizer
// ─────────────────────────────────────────────────────────────────────────────

/// 4-bit scalar quantization: packs two dimensions into each byte (nibble encoding).
///
/// Each dimension is mapped to a value in `[0, 15]` using per-dimension min/max
/// statistics.  Two adjacent dimensions are stored in the high and low nibbles
/// of a single byte, giving **8× memory compression** vs. full-precision f32.
///
/// This is the recommended quantization scheme when vector count exceeds
/// `hnsw_offload_threshold` and memory must be conserved (see config).
/// Accuracy loss is typically 2–4% vs. 1–2% for [`Scalar8Quantizer`].
///
/// # Memory usage
/// - f32:     4 bytes/dim
/// - Scalar8: 1 byte/dim  (4× compression)
/// - Scalar4: 0.5 byte/dim (8× compression)
#[derive(Debug, Default, Clone)]
pub struct Scalar4Quantizer;

impl Scalar4Quantizer {
    /// Encode a single f32 dimension value to a 4-bit nibble `[0, 15]`.
    #[inline]
    fn encode_dim(value: f32, min: f32, scale: f32) -> u8 {
        if scale == 0.0 {
            return 0;
        }
        let normalized = (value - min) / scale;
        (normalized * 15.0).round().clamp(0.0, 15.0) as u8
    }

    /// Decode a nibble `[0, 15]` back to an approximate f32.
    #[inline]
    fn decode_dim(nibble: u8, min: f32, scale: f32) -> f32 {
        min + (nibble as f32 / 15.0) * scale
    }
}

impl Quantizer for Scalar4Quantizer {
    fn quantize(&self, vectors: &[Vec<f32>]) -> Result<QuantizedVectors> {
        if vectors.is_empty() {
            return Ok(QuantizedVectors {
                count: 0,
                dim: 0,
                data: QuantizedData::Nibble {
                    bytes: vec![],
                    mins: vec![],
                    scales: vec![],
                },
            });
        }

        let dim = vectors[0].len();

        // Compute per-dimension min and max.
        let mut mins = vec![f32::MAX; dim];
        let mut maxs = vec![f32::MIN; dim];

        for vec in vectors {
            if vec.len() != dim {
                return Err(XerjError::invalid_mapping(
                    "Scalar4Quantizer: inconsistent vector dimensions",
                ));
            }
            for (d, &v) in vec.iter().enumerate() {
                if v < mins[d] {
                    mins[d] = v;
                }
                if v > maxs[d] {
                    maxs[d] = v;
                }
            }
        }

        let scales: Vec<f32> = mins
            .iter()
            .zip(maxs.iter())
            .map(|(&mn, &mx)| mx - mn)
            .collect();

        // Each vector takes `ceil(dim/2)` bytes.
        let bytes_per_vec = dim.div_ceil(2);
        let mut bytes = Vec::with_capacity(vectors.len() * bytes_per_vec);

        for vec in vectors {
            let mut d = 0;
            while d < dim {
                let hi = Self::encode_dim(vec[d], mins[d], scales[d]);
                let lo = if d + 1 < dim {
                    Self::encode_dim(vec[d + 1], mins[d + 1], scales[d + 1])
                } else {
                    0u8
                };
                bytes.push((hi << 4) | (lo & 0x0F));
                d += 2;
            }
        }

        Ok(QuantizedVectors {
            count: vectors.len(),
            dim,
            data: QuantizedData::Nibble {
                bytes,
                mins,
                scales,
            },
        })
    }

    fn distance(&self, query: &[f32], quantized: &QuantizedData, id: usize) -> Result<f32> {
        let (bytes, mins, scales) = match quantized {
            QuantizedData::Nibble {
                bytes,
                mins,
                scales,
            } => (bytes, mins, scales),
            _ => {
                return Err(XerjError::internal(
                    "Scalar4Quantizer: wrong QuantizedData variant",
                ))
            }
        };

        let dim = query.len();
        let bytes_per_vec = dim.div_ceil(2);
        let byte_start = id * bytes_per_vec;
        let byte_end = byte_start + bytes_per_vec;

        if byte_end > bytes.len() {
            return Err(XerjError::internal(format!(
                "Scalar4Quantizer: id {id} out of range"
            )));
        }

        let dist: f32 = (0..dim)
            .map(|d| {
                let byte_idx = byte_start + d / 2;
                let nibble = if d % 2 == 0 {
                    (bytes[byte_idx] >> 4) & 0x0F
                } else {
                    bytes[byte_idx] & 0x0F
                };
                let stored = Self::decode_dim(nibble, mins[d], scales[d]);
                let diff = query[d] - stored;
                diff * diff
            })
            .sum();

        Ok(dist)
    }

    fn name(&self) -> &'static str {
        "scalar4"
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn approx_eq(a: f32, b: f32, tol: f32) -> bool {
        (a - b).abs() < tol
    }

    #[test]
    fn none_quantizer_roundtrip() {
        let q = NoneQuantizer;
        let vecs = vec![vec![1.0, 2.0, 3.0], vec![4.0, 5.0, 6.0]];
        let qv = q.quantize(&vecs).unwrap();

        let v0 = qv.data.get_f32(0, 3).unwrap();
        assert_eq!(v0, vec![1.0, 2.0, 3.0]);

        let v1 = qv.data.get_f32(1, 3).unwrap();
        assert_eq!(v1, vec![4.0, 5.0, 6.0]);
    }

    #[test]
    fn scalar8_roundtrip_approx() {
        let q = Scalar8Quantizer;
        let vecs = vec![vec![0.0, 0.5, 1.0], vec![0.2, 0.7, 0.9]];
        let qv = q.quantize(&vecs).unwrap();

        // Dequantized values should be close to originals (within ~1% error)
        let recovered = qv.data.get_f32(0, 3).unwrap();
        for (orig, rec) in vecs[0].iter().zip(recovered.iter()) {
            assert!(approx_eq(*orig, *rec, 0.02), "expected ~{orig}, got {rec}");
        }
    }

    #[test]
    fn scalar8_empty_input() {
        let q = Scalar8Quantizer;
        let qv = q.quantize(&[]).unwrap();
        assert_eq!(qv.count, 0);
    }

    #[test]
    fn scalar8_distance_ordering() {
        let q = Scalar8Quantizer;
        let vecs = vec![
            vec![1.0, 0.0, 0.0], // close to query
            vec![0.0, 0.0, 1.0], // far from query
        ];
        let qv = q.quantize(&vecs).unwrap();

        let query = vec![1.0, 0.0, 0.0];
        let d0 = q.distance(&query, &qv.data, 0).unwrap();
        let d1 = q.distance(&query, &qv.data, 1).unwrap();
        assert!(d0 < d1, "closer vector should have smaller distance");
    }

    #[test]
    fn scalar4_roundtrip_approx() {
        let q = Scalar4Quantizer;
        let vecs = vec![vec![0.0, 0.5, 1.0], vec![0.2, 0.7, 0.9]];
        let qv = q.quantize(&vecs).unwrap();
        // 4-bit gives 16 levels over the range — tolerance of ~7%
        let recovered = qv.data.get_f32(0, 3).unwrap();
        for (orig, rec) in vecs[0].iter().zip(recovered.iter()) {
            assert!((orig - rec).abs() < 0.08, "expected ~{orig}, got {rec}");
        }
    }

    #[test]
    fn scalar4_empty_input() {
        let q = Scalar4Quantizer;
        let qv = q.quantize(&[]).unwrap();
        assert_eq!(qv.count, 0);
    }

    #[test]
    fn scalar4_distance_ordering() {
        let q = Scalar4Quantizer;
        let vecs = vec![
            vec![1.0, 0.0, 0.0], // close to query
            vec![0.0, 0.0, 1.0], // far from query
        ];
        let qv = q.quantize(&vecs).unwrap();

        let query = vec![1.0, 0.0, 0.0];
        let d0 = q.distance(&query, &qv.data, 0).unwrap();
        let d1 = q.distance(&query, &qv.data, 1).unwrap();
        assert!(
            d0 < d1,
            "closer vector should have smaller distance (4-bit)"
        );
    }

    #[test]
    fn scalar4_memory_is_half_scalar8() {
        // For N vectors of dim D:
        //   scalar8 → N * D bytes
        //   scalar4 → N * ceil(D/2) bytes  ≈ N * D/2 bytes
        let q4 = Scalar4Quantizer;
        let q8 = Scalar8Quantizer;
        let vecs: Vec<Vec<f32>> = (0..10).map(|i| vec![i as f32; 64]).collect();

        let qv4 = q4.quantize(&vecs).unwrap();
        let qv8 = q8.quantize(&vecs).unwrap();

        let bytes4 = match &qv4.data {
            QuantizedData::Nibble { bytes, .. } => bytes.len(),
            _ => panic!(),
        };
        let bytes8 = match &qv8.data {
            QuantizedData::U8 { bytes, .. } => bytes.len(),
            _ => panic!(),
        };

        // scalar4 should use ≤ 55% of scalar8 byte count (target is 50%)
        assert!(
            bytes4 <= bytes8 * 55 / 100,
            "scalar4 ({bytes4} B) should be ~50% of scalar8 ({bytes8} B)"
        );
    }

    // ── Sq8Params (serving-path codec) ────────────────────────────────────────

    /// Tiny deterministic xorshift RNG so the recall/memory tests are
    /// reproducible without pulling in the `rand` crate.
    struct XorShift(u64);
    impl XorShift {
        fn next_u64(&mut self) -> u64 {
            let mut x = self.0;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.0 = x;
            x
        }
        /// Standard-normal-ish sample via sum of 4 uniforms (CLT), in ~[-2,2].
        fn next_gauss(&mut self) -> f32 {
            let mut s = 0.0f32;
            for _ in 0..4 {
                s += (self.next_u64() as f64 / u64::MAX as f64) as f32;
            }
            s - 2.0 // mean 0
        }
    }

    fn l2_normalize(v: &mut [f32]) {
        let norm: f32 = v.iter().map(|x| x * x).sum::<f32>().sqrt();
        if norm > 0.0 {
            for x in v.iter_mut() {
                *x /= norm;
            }
        }
    }

    fn cosine_sim(a: &[f32], b: &[f32]) -> f32 {
        let dot: f32 = a.iter().zip(b).map(|(x, y)| x * y).sum();
        let na: f32 = a.iter().map(|x| x * x).sum::<f32>().sqrt();
        let nb: f32 = b.iter().map(|x| x * x).sum::<f32>().sqrt();
        if na > 0.0 && nb > 0.0 {
            dot / (na * nb)
        } else {
            0.0
        }
    }

    /// (b) MEMORY: SQ8 codes are ~4× smaller than the f32 vectors they encode.
    /// This is a property of the codec, measured here on the codec; since #392
    /// the engine realizes it on the kNN path too — the serving scan scores
    /// against the ingest-time code array ([`crate::sq8_codes::Sq8CodeStore`]),
    /// not the f32 `_source` vectors.
    #[test]
    fn sq8_store_is_quarter_of_f32() {
        let n = 2000usize;
        let dim = 128usize;
        let mut rng = XorShift(0x1234_5678_9abc_def0);
        let vecs: Vec<Vec<f32>> = (0..n)
            .map(|_| {
                let mut v: Vec<f32> = (0..dim).map(|_| rng.next_gauss()).collect();
                l2_normalize(&mut v);
                v
            })
            .collect();
        let params = Sq8Params::fit(&vecs, dim);
        let code_bytes: usize = vecs.iter().map(|v| params.encode(v).len()).sum();
        // params overhead is 2 * dim * 4 bytes, shared across all N vectors.
        let params_bytes = (params.mins.len() + params.scales.len()) * std::mem::size_of::<f32>();
        let f32_bytes = n * dim * std::mem::size_of::<f32>();
        let ratio = f32_bytes as f64 / (code_bytes + params_bytes) as f64;
        println!(
            "SQ8 memory: f32={f32_bytes}B codes={code_bytes}B params={params_bytes}B ratio={ratio:.3}x"
        );
        assert!(
            ratio >= 3.5,
            "SQ8 store should be >=3.5x smaller than f32, got {ratio:.3}x"
        );
    }

    /// (c) RECALL: scalar8 serving-path scoring keeps recall@10 >= 0.90 vs the
    /// exact (none) path over >=2000 vectors / >=100 queries at dim>=64.
    #[test]
    fn sq8_recall_at_10_above_090() {
        let n = 2000usize;
        let dim = 128usize;
        let k = 10usize;
        let queries = 100usize;
        let mut rng = XorShift(0xdead_beef_cafe_0001);

        // Corpus, L2-normalized (cosine convention, as the serving path does).
        let corpus: Vec<Vec<f32>> = (0..n)
            .map(|_| {
                let mut v: Vec<f32> = (0..dim).map(|_| rng.next_gauss()).collect();
                l2_normalize(&mut v);
                v
            })
            .collect();

        // Fit params from the first 1000 vectors (mirrors the engine's sample).
        let sample: Vec<Vec<f32>> = corpus.iter().take(1000).cloned().collect();
        let params = Sq8Params::fit(&sample, dim);
        let codes: Vec<Vec<u8>> = corpus.iter().map(|v| params.encode(v)).collect();

        let mut recall_sum = 0.0f64;
        let mut decoded = vec![0.0f32; dim];
        for _ in 0..queries {
            let q: Vec<f32> = (0..dim).map(|_| rng.next_gauss()).collect();

            // Exact (ground truth) top-k by cosine on the raw f32 corpus.
            let mut exact: Vec<(usize, f32)> = corpus
                .iter()
                .enumerate()
                .map(|(i, v)| (i, cosine_sim(&q, v)))
                .collect();
            exact.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
            let truth: std::collections::HashSet<usize> =
                exact.iter().take(k).map(|(i, _)| *i).collect();

            // Approximate top-k by cosine on the DECODED SQ8 codes.
            let mut approx: Vec<(usize, f32)> = codes
                .iter()
                .enumerate()
                .map(|(i, c)| {
                    params.decode_into(c, &mut decoded);
                    (i, cosine_sim(&q, &decoded))
                })
                .collect();
            approx.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());

            let hit = approx
                .iter()
                .take(k)
                .filter(|(i, _)| truth.contains(i))
                .count();
            recall_sum += hit as f64 / k as f64;
        }
        let mean_recall = recall_sum / queries as f64;
        println!("SQ8 recall@{k}: {mean_recall:.4} over {queries} queries / {n} vectors dim={dim}");
        assert!(
            mean_recall >= 0.90,
            "SQ8 recall@{k} should be >=0.90, got {mean_recall:.4}"
        );
    }
}

//! High-level vector search interface.
//!
//! [`VectorSearcher`] wraps an [`HnswIndex`] and handles query normalization,
//! filtered search, and result formatting.

use xerj_common::XerjError;

use crate::distance::DistanceMetric;
use crate::hnsw::HnswIndex;

/// Result alias.
pub type Result<T> = std::result::Result<T, XerjError>;

/// A single search result.
#[derive(Debug, Clone, PartialEq)]
pub struct SearchResult {
    /// Internal document ID.
    pub doc_id: u64,
    /// Distance from the query (lower = closer).
    pub distance: f32,
    /// Similarity score in `[0, 1]` (higher = more similar).
    pub score: f32,
}

impl SearchResult {
    fn new(doc_id: u64, distance: f32, metric: DistanceMetric) -> Self {
        let score = distance_to_score(distance, metric);
        Self {
            doc_id,
            distance,
            score,
        }
    }
}

/// Convert a raw distance to a [0, 1] similarity score.
fn distance_to_score(dist: f32, metric: DistanceMetric) -> f32 {
    match metric {
        // dist = 1 - cosine_similarity, so similarity = 1 - dist
        DistanceMetric::Cosine => (1.0 - dist).max(0.0),
        // L2 squared: map to [0, 1] via 1/(1+dist)
        DistanceMetric::L2 => 1.0 / (1.0 + dist),
        // Dot product: dist = -dot_product, so score = -dist
        DistanceMetric::DotProduct => (-dist).max(0.0),
    }
}

/// High-level KNN search over an [`HnswIndex`].
pub struct VectorSearcher {
    index: HnswIndex,
    /// Default ef (beam width) for search. Higher = better recall, slower.
    default_ef: usize,
}

impl VectorSearcher {
    /// Create a searcher with the given index and default ef=50.
    pub fn new(index: HnswIndex) -> Self {
        Self {
            index,
            default_ef: 50,
        }
    }

    /// Create a searcher with a custom ef.
    pub fn with_ef(index: HnswIndex, ef: usize) -> Self {
        Self {
            index,
            default_ef: ef,
        }
    }

    /// Get a reference to the underlying index.
    pub fn index(&self) -> &HnswIndex {
        &self.index
    }

    /// Number of indexed vectors.
    pub fn len(&self) -> usize {
        self.index.len()
    }

    pub fn is_empty(&self) -> bool {
        self.index.is_empty()
    }

    /// Perform a K-nearest-neighbor search.
    ///
    /// Returns results sorted by score descending (best first).
    pub fn search(&self, query: &[f32], k: usize) -> Result<Vec<SearchResult>> {
        self.search_with_ef(query, k, self.default_ef)
    }

    /// KNN search with an explicit ef override.
    pub fn search_with_ef(&self, query: &[f32], k: usize, ef: usize) -> Result<Vec<SearchResult>> {
        let metric = self.index.params().metric;
        let raw = self.index.search(query, k, ef)?;
        let mut results: Vec<SearchResult> = raw
            .into_iter()
            .map(|(id, dist)| SearchResult::new(id, dist, metric))
            .collect();
        // Sort by score descending
        results.sort_unstable_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        Ok(results)
    }

    /// KNN search with a filter predicate pushed into graph traversal.
    ///
    /// The filter is applied **during** graph exploration, not as a post-filter.
    /// This is critical for high-selectivity filters — post-filtering would
    /// require retrieving many more candidates to find k valid results.
    pub fn search_filtered(
        &self,
        query: &[f32],
        k: usize,
        filter: &dyn Fn(u64) -> bool,
    ) -> Result<Vec<SearchResult>> {
        self.search_filtered_with_ef(query, k, self.default_ef, filter)
    }

    /// Filtered KNN search with explicit ef.
    pub fn search_filtered_with_ef(
        &self,
        query: &[f32],
        k: usize,
        ef: usize,
        filter: &dyn Fn(u64) -> bool,
    ) -> Result<Vec<SearchResult>> {
        let metric = self.index.params().metric;
        // Use a larger ef to compensate for filtered nodes
        let effective_ef = (ef * 4).max(k * 2);
        let raw = self.index.search_filtered(query, k, effective_ef, filter)?;
        let mut results: Vec<SearchResult> = raw
            .into_iter()
            .map(|(id, dist)| SearchResult::new(id, dist, metric))
            .collect();
        results.sort_unstable_by(|a, b| {
            b.score
                .partial_cmp(&a.score)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        Ok(results)
    }

    /// Insert a vector into the underlying index.
    pub fn insert(&self, id: u64, vector: Vec<f32>) -> Result<()> {
        self.index.insert(id, vector)
    }

    /// Batch insert vectors.
    pub fn insert_batch(&self, items: Vec<(u64, Vec<f32>)>) -> Result<()> {
        self.index.insert_batch(items)
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hnsw::{HnswIndex, HnswParams};

    fn make_searcher(dim: usize) -> VectorSearcher {
        let params = HnswParams::new(dim, DistanceMetric::Cosine);
        VectorSearcher::new(HnswIndex::new(params))
    }

    #[test]
    fn search_returns_best_match() {
        let s = make_searcher(3);
        s.insert(0, vec![1.0, 0.0, 0.0]).unwrap();
        s.insert(1, vec![0.0, 1.0, 0.0]).unwrap();
        s.insert(2, vec![0.0, 0.0, 1.0]).unwrap();

        let results = s.search(&[1.0, 0.0, 0.0], 1).unwrap();
        assert!(!results.is_empty());
        assert_eq!(results[0].doc_id, 0);
        // Score should be close to 1.0 for identical vectors
        assert!(results[0].score > 0.99, "score was {}", results[0].score);
    }

    #[test]
    fn scores_are_descending() {
        let s = make_searcher(3);
        for i in 0..10u64 {
            s.insert(i, vec![i as f32, 1.0, 0.0]).unwrap();
        }
        let results = s.search(&[5.0, 1.0, 0.0], 5).unwrap();
        for window in results.windows(2) {
            assert!(
                window[0].score >= window[1].score,
                "scores not descending: {} < {}",
                window[0].score,
                window[1].score
            );
        }
    }

    #[test]
    fn filtered_search_respects_predicate() {
        let s = make_searcher(4);
        for i in 0..20u64 {
            s.insert(i, vec![i as f32, 0.0, 0.0, 1.0]).unwrap();
        }

        let results = s
            .search_filtered(&[10.0, 0.0, 0.0, 1.0], 5, &|id| id % 3 == 0)
            .unwrap();

        for r in &results {
            assert_eq!(r.doc_id % 3, 0, "id {} should be divisible by 3", r.doc_id);
        }
    }

    #[test]
    fn empty_searcher() {
        let s = make_searcher(4);
        assert!(s.is_empty());
        let results = s.search(&[1.0, 0.0, 0.0, 0.0], 5).unwrap();
        assert!(results.is_empty());
    }

    #[test]
    fn distance_to_score_cosine() {
        // distance 0 → score 1.0 (identical direction)
        assert!((distance_to_score(0.0, DistanceMetric::Cosine) - 1.0).abs() < 1e-6);
        // distance 2.0 → score 0.0 (opposite direction, clamped)
        assert_eq!(distance_to_score(2.0, DistanceMetric::Cosine), 0.0);
    }
}

//! Ingest-time, slot-addressed SQ8 code store — issue #392.
//!
//! [`Sq8CodeStore`] is the durable counterpart of the per-query codec
//! ([`Sq8Params`](crate::quantizer::Sq8Params)): one u8 code per dimension
//! per document, written when the document is indexed and rewritten when it
//! is updated, in a single flat `Vec<u8>` addressed by a dense slot —
//! `codes[slot * dim .. slot * dim + dim]` — the same slot discipline the
//! HNSW slab uses for its f32 vectors. The codebook is fitted from the
//! vectors as they are ingested and lives with the data, so a document's
//! quantized score is a function of the index state alone and not of the
//! candidate set a particular query happens to scan (#392's second half).
//!
//! Reference points (retrieved, not copied):
//!  * qdrant `lib/quantization/src/encoded_vectors_u8.rs` (Apache-2.0) —
//!    quantized codes are written once at build time into contiguous
//!    storage, fetched by `get_vector_data(offset)` at
//!    `offset * quantized_vector_size`; the codebook (alpha/offset) is
//!    fitted at build time and persisted next to the codes; the query is
//!    encoded once and scored against stored codes without touching f32.
//!  * Lucene `OffHeapScalarQuantizedVectorValues.vectorValue(targetOrd)`
//!    seeks `targetOrd * byteSize` into a per-segment slice written at index
//!    time; requantization happens at merge time, never at query time
//!    (cited from issue #392; Elasticsearch/Lucene is AGPL/SSPL — approach
//!    only).
//!
//! The one structural difference from both: XERJ maintains the store
//! incrementally per document instead of rebuilding it per segment merge, so
//! the codebook WIDENS whenever an ingested vector falls outside the fitted
//! range (and narrows when the document holding a per-dimension bound is
//! replaced or removed), and every live code is re-encoded FROM ITS RETAINED
//! ORIGINAL VECTOR on each such re-fit. Re-encoding from the original (not
//! through a decode/encode round trip of the stored bytes — each round trip
//! drifts by up to the quantization step, and they compound) is what keeps
//! the codes bit-identical to a one-shot `Sq8Params::fit_borrowed` +
//! `encode_into` over the live set, which is the arithmetic the exact
//! scan's per-query codec performs; that bit-identity is pinned by
//! `codes_are_bit_identical_to_a_one_shot_fit_over_the_live_set` below and
//! by the engine's exact-scan honesty tests. The price is honesty about
//! memory: beside the 1 byte/dim codes the store retains the 4 bytes/dim
//! normalized f32 originals (`originals_bytes`), touched only at ingest and
//! re-fit — never on the scoring path. Widening at ingest is the same order
//! of accuracy work a merge-time requantization does, and it is what makes
//! clamping structurally impossible: the codebook always spans every live
//! vector (#371's defect class cannot recur — a vector written outside the
//! range extends the range rather than being clamped into it).

use std::collections::HashMap;

use crate::quantizer::Sq8Params;

/// Slot-addressed SQ8 code store for ONE dense_vector field.
///
/// All mutating operations are `&mut self`; the engine keeps each store
/// behind a lock and serves scans under a read guard, so a scan observes the
/// codes and the codebook of one consistent generation.
#[derive(Debug)]
pub struct Sq8CodeStore {
    dim: usize,
    /// The live codebook. `maxs` are kept alongside so an out-of-range
    /// ingest can extend the range exactly rather than through the
    /// dequantized grid.
    mins: Vec<f32>,
    maxs: Vec<f32>,
    /// slot → doc id. Slots of tombstoned documents keep their last id
    /// (never read again; `slot_of` is the live set).
    ids: Vec<String>,
    /// doc id → slot (the live set).
    slot_of: HashMap<String, u32>,
    /// Flat code array, `codes[slot * dim .. slot * dim + dim]`.
    codes: Vec<u8>,
    /// Flat ORIGINAL vector array, `originals[slot * dim .. slot * dim +
    /// dim]` — the exact (normalized) f32 each slot was encoded from,
    /// append-only like `codes`. A codebook re-fit re-encodes every live
    /// slot from these, never through its own stored bytes: a decode/encode
    /// round trip moves a value by up to the (new, wider) quantization step
    /// and the drift compounds over successive widenings, which broke
    /// bit-identity with the exact scan's per-query codec. Never read on
    /// the scoring path.
    originals: Vec<f32>,
    /// Soft delete marks, one per slot (the slab's discipline: append-only,
    /// tombstone on delete, never physically free).
    tomb: Vec<bool>,
    /// Coverage-gate denominator: number of DISTINCT doc ids ever offered to
    /// [`Self::upsert`] and not since removed. Mirrors the engine's
    /// `vector_doc_count` (counted on attempt): a rejected vector (wrong
    /// dimension) increments this without creating a slot, so
    /// `live_len() != expected` and consumers fall back to exact paths.
    expected: u64,
    /// Number of codebook widenings (observability).
    refits: u64,
}

impl Sq8CodeStore {
    /// An empty store for `dim`-dimensional vectors.
    pub fn new(dim: usize) -> Self {
        Sq8CodeStore {
            dim,
            mins: vec![0.0; dim],
            maxs: vec![0.0; dim],
            ids: Vec::new(),
            slot_of: HashMap::new(),
            codes: Vec::new(),
            originals: Vec::new(),
            tomb: Vec::new(),
            expected: 0,
            refits: 0,
        }
    }

    /// Vector dimensionality this store encodes.
    pub fn dim(&self) -> usize {
        self.dim
    }

    /// The current codebook (mins/scales), for decoding at query time.
    pub fn codebook(&self) -> Sq8Params {
        let scales = self
            .mins
            .iter()
            .zip(self.maxs.iter())
            .map(|(&mn, &mx)| mx - mn)
            .collect();
        Sq8Params {
            mins: self.mins.clone(),
            scales,
        }
    }

    /// Live documents holding a code slot (the coverage-gate numerator).
    pub fn live_len(&self) -> u64 {
        self.slot_of.len() as u64
    }

    /// Distinct doc ids ever accepted for this field minus removals (the
    /// coverage-gate denominator). See the field docs for the attempt
    /// semantics.
    pub fn expected(&self) -> u64 {
        self.expected
    }

    /// The serving gate: every doc id that ever carried (or attempted to
    /// carry) this field holds a live slot. Consumers that score from the
    /// codes must fall back to an exact path when this is false — a doc with
    /// a rejected vector would otherwise be silently missing from results.
    pub fn coverage_ok(&self) -> bool {
        self.live_len() == self.expected
    }

    /// Codebook widenings since construction (observability).
    pub fn refits(&self) -> u64 {
        self.refits
    }

    /// Bytes occupied by the flat code array (including tombstoned slots —
    /// the array is append-only).
    pub fn codes_bytes(&self) -> usize {
        self.codes.len()
    }

    /// Bytes occupied by the retained original (normalized) f32 vectors —
    /// 4 bytes/dim/slot beside the 1 byte/dim codes. They exist so a
    /// codebook re-fit re-encodes from the true vectors instead of drifting
    /// through decode/encode round trips (see the module docs); they are
    /// never read on the scoring path.
    pub fn originals_bytes(&self) -> usize {
        self.originals.len() * std::mem::size_of::<f32>()
    }

    /// The live codes of one document, `dim` bytes at `slot * dim`.
    pub fn codes_for(&self, doc_id: &str) -> Option<&[u8]> {
        let &slot = self.slot_of.get(doc_id)?;
        Some(&self.codes[slot as usize * self.dim..][..self.dim])
    }

    /// Iterate every LIVE `(doc id, codes)` pair. Slot-addressed order.
    pub fn iter_live(&self) -> impl Iterator<Item = (&str, &[u8])> {
        let dim = self.dim;
        self.slot_of
            .iter()
            .map(move |(id, &slot)| (id.as_str(), &self.codes[slot as usize * dim..][..dim]))
    }

    /// Write (or rewrite, on update) one document's codes.
    ///
    /// Returns `false` when `vector` does not have exactly [`Self::dim`]
    /// dimensions — the attempt is still counted in `expected` (no slot is
    /// created), which breaks [`Self::coverage_ok`] and keeps consumers on
    /// exact paths: the same wrong-dimension document the brute-force scan
    /// skips must not be half-represented here.
    ///
    /// The invariant after every successful call: `codebook()` is the fit
    /// over the live originals and every live code is
    /// `codebook().encode(original)` — bit-identical to a one-shot
    /// `Sq8Params::fit_borrowed` + `encode_into` over the live set. A
    /// vector outside the fitted range widens the codebook; a replaced
    /// vector that held a per-dimension bound may narrow it. Either way the
    /// affected live codes are re-encoded FROM THEIR ORIGINALS (see the
    /// module docs), never through a decode/encode round trip.
    pub fn upsert(&mut self, doc_id: &str, vector: &[f32]) -> bool {
        if vector.len() != self.dim {
            // Count the attempt for a NEW id only: an id that never had a
            // slot must not leak a phantom expectation, and an id whose
            // field silently appeared with the wrong arity keeps its slot
            // (remove() is the API for that).
            if !self.slot_of.contains_key(doc_id) {
                self.expected += 1;
            }
            return false;
        }
        let live = self.slot_of.get(doc_id).copied();
        let had_live = !self.slot_of.is_empty();
        // Does this write move a per-dimension bound? Widening: the new
        // vector sits outside the fitted range. Narrowing: a REPLACED live
        // vector sat exactly on a bound, so removing it may shrink the fit
        // (a tie with another live vector keeps the bound; the re-fit that
        // follows decides, and lands back on the same codebook when nothing
        // moved).
        let mut refit = false;
        if had_live {
            for (d, &x) in vector.iter().enumerate() {
                if x < self.mins[d] || x > self.maxs[d] {
                    refit = true;
                    break;
                }
            }
            if !refit {
                if let Some(slot) = live {
                    let start = slot as usize * self.dim;
                    for d in 0..self.dim {
                        let o = self.originals[start + d];
                        if o == self.mins[d] || o == self.maxs[d] {
                            refit = true;
                            break;
                        }
                    }
                }
            }
        }
        let slot = match live {
            Some(slot) => slot,
            None => {
                let slot = self.ids.len() as u32;
                self.ids.push(doc_id.to_string());
                self.codes.extend(vec![0u8; self.dim]);
                self.originals.extend(vec![0.0f32; self.dim]);
                self.tomb.push(false);
                self.slot_of.insert(doc_id.to_string(), slot);
                self.expected += 1;
                slot
            }
        };
        let start = slot as usize * self.dim;
        self.originals[start..][..self.dim].copy_from_slice(vector);
        self.tomb[slot as usize] = false;
        if !had_live {
            // The first live vector adopts the degenerate per-dimension
            // range [v, v]: every code is 0 and decodes back to v exactly,
            // so the first document carries no quantization error.
            self.mins = vector.to_vec();
            self.maxs = vector.to_vec();
        }
        if refit {
            self.refits += 1;
            self.refit_from_originals();
        } else {
            // Even without a re-fit the slot's own codes must reflect its
            // current vector under the CURRENT codebook (an update inside
            // the range changes nothing else).
            let codebook = self.codebook();
            codebook.encode_into(vector, &mut self.codes[start..][..self.dim]);
        }
        true
    }

    /// Drop a document's live slot (delete, or the document no longer
    /// carries the field). Returns whether a slot was live. The slot is
    /// tombstoned, not freed — same append-only discipline as the HNSW
    /// slab. When the removed vector held a per-dimension bound the
    /// codebook narrows to the remaining live set and every live code is
    /// re-encoded from its original, keeping the fit equal to what a
    /// per-query codec fitted over the (now smaller) live set would
    /// compute.
    pub fn remove(&mut self, doc_id: &str) -> bool {
        match self.slot_of.remove(doc_id) {
            Some(slot) => {
                self.tomb[slot as usize] = true;
                self.expected = self.expected.saturating_sub(1);
                let start = slot as usize * self.dim;
                let mut held_bound = false;
                for d in 0..self.dim {
                    let o = self.originals[start + d];
                    if o == self.mins[d] || o == self.maxs[d] {
                        held_bound = true;
                        break;
                    }
                }
                if held_bound {
                    self.refits += 1;
                    self.refit_from_originals();
                }
                true
            }
            None => false,
        }
    }

    /// Recompute `mins`/`maxs` over the live originals and re-encode every
    /// live code from its original. After this, codes and codebook are
    /// bit-identical to `Sq8Params::fit_borrowed` over the live vectors
    /// followed by one `encode_into` per vector — the exact bytes the
    /// serving paths' per-query fallback produces, which is the bit-identity
    /// the exact-scan honesty tests pin.
    fn refit_from_originals(&mut self) {
        let dim = self.dim;
        if self.slot_of.is_empty() {
            self.mins = vec![0.0; dim];
            self.maxs = vec![0.0; dim];
            return;
        }
        let mut mins = vec![f32::MAX; dim];
        let mut maxs = vec![f32::MIN; dim];
        for &slot in self.slot_of.values() {
            let start = slot as usize * dim;
            for d in 0..dim {
                let x = self.originals[start + d];
                if x < mins[d] {
                    mins[d] = x;
                }
                if x > maxs[d] {
                    maxs[d] = x;
                }
            }
        }
        self.mins = mins;
        self.maxs = maxs;
        let codebook = self.codebook();
        for &slot in self.slot_of.values() {
            let start = slot as usize * dim;
            codebook.encode_into(
                &self.originals[start..][..dim],
                &mut self.codes[start..][..dim],
            );
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn store_with(vectors: &[Vec<f32>]) -> Sq8CodeStore {
        let mut s = Sq8CodeStore::new(vectors[0].len());
        for (i, v) in vectors.iter().enumerate() {
            assert!(s.upsert(&i.to_string(), v), "upsert {i} must succeed");
        }
        s
    }

    #[test]
    fn first_vector_encodes_exactly() {
        // Degenerate range [v, v] per dim → code 0 → decode back to v.
        let v = vec![0.25, -0.5, 1.75];
        let s = store_with(std::slice::from_ref(&v));
        let codebook = s.codebook();
        let codes = s.codes_for("0").unwrap();
        assert_eq!(codes, vec![0, 0, 0]);
        let decoded = codebook.decode(codes);
        assert_eq!(decoded, v);
    }

    #[test]
    fn roundtrip_within_one_step() {
        let vectors: Vec<Vec<f32>> = (0..20)
            .map(|i| {
                (0..4)
                    .map(|d| ((i * 37 + d * 101) % 199) as f32 / 99.0 - 1.0)
                    .collect()
            })
            .collect();
        let s = store_with(&vectors);
        let codebook = s.codebook();
        for (i, v) in vectors.iter().enumerate() {
            let decoded = codebook.decode(s.codes_for(&i.to_string()).unwrap());
            let step: f32 = codebook.scales.iter().cloned().sum();
            let err: f32 = v.iter().zip(decoded).map(|(a, b)| (a - b).abs()).sum();
            assert!(
                err < step,
                "doc {i}: |err| {err} must be < one total step {step}"
            );
        }
    }

    #[test]
    fn out_of_range_vector_extends_rather_than_clamps() {
        // #371's defect class: a corpus whose dim 0 never leaves +1.0, then a
        // document rewritten to -1.0. A clamping (stale) codebook decodes
        // -1.0 back to +1.0; a widening one decodes it near -1.0.
        let mut s = store_with(&[vec![1.0, 0.0], vec![1.0, 0.5]]);
        let before_refits = s.refits();
        assert!(s.upsert("0", &[-1.0, 0.0]));
        assert_eq!(s.refits(), before_refits + 1, "must have widened");
        let decoded = s.codebook().decode(s.codes_for("0").unwrap());
        assert!(
            (decoded[0] - (-1.0)).abs() < 2.0 / 255.0,
            "dim 0 decoded to {} — the codebook clamped (#371 defect class)",
            decoded[0]
        );
        // The untouched dimension-1 values of the OTHER document survive the
        // re-encode within a step.
        let d1 = s.codebook().decode(s.codes_for("1").unwrap());
        assert!((d1[0] - 1.0).abs() < 2.0 / 255.0);
        assert!((d1[1] - 0.5).abs() < 2.0 / 255.0);
    }

    #[test]
    fn update_rewrites_the_slot() {
        let mut s = store_with(&[vec![0.0, 1.0], vec![1.0, 0.0]]);
        let codebook_before = s.codebook();
        let old = codebook_before.decode(s.codes_for("0").unwrap());
        assert_eq!(old, vec![0.0, 1.0]);
        assert!(s.upsert("0", &[1.0, 1.0]));
        // Both dims' ranges now [0,1]; doc 0 re-encoded in place.
        assert_eq!(s.live_len(), 2, "update must not grow the live set");
        let decoded = s.codebook().decode(s.codes_for("0").unwrap());
        assert!((decoded[0] - 1.0).abs() < 1.0 / 255.0);
        assert!((decoded[1] - 1.0).abs() < 1.0 / 255.0);
    }

    #[test]
    fn remove_breaks_coverage_and_delete_reinsert_restores_it() {
        let mut s = store_with(&[vec![0.0], vec![1.0]]);
        assert!(s.coverage_ok());
        assert!(s.remove("0"));
        assert_eq!(s.live_len(), 1);
        assert!(s.coverage_ok(), "remove decrements both sides");
        assert!(!s.remove("0"), "second remove is a no-op");
        assert!(s.upsert("0", &[0.5]));
        assert!(s.coverage_ok());
        assert_eq!(s.live_len(), 2);
    }

    #[test]
    fn wrong_dim_attempt_breaks_coverage() {
        let mut s = store_with(&[vec![0.0, 0.0]]);
        assert!(!s.upsert("bad", &[0.0, 0.0, 0.0]), "mismatch rejected");
        assert_eq!(s.live_len(), 1);
        assert_eq!(s.expected(), 2);
        assert!(
            !s.coverage_ok(),
            "a rejected vector must keep consumers on exact paths"
        );
        assert!(s.codes_for("bad").is_none());
    }

    #[test]
    fn codes_bytes_is_one_byte_per_dim_per_slot() {
        let s = store_with(&[vec![0.0; 8], vec![1.0; 8], vec![0.5; 8]]);
        assert_eq!(s.codes_bytes(), 3 * 8);
    }

    #[test]
    fn iter_live_skips_removed_and_addresses_by_slot() {
        let mut s = store_with(&[vec![0.0, 0.1], vec![0.2, 0.3]]);
        assert!(s.remove("0"));
        let live: Vec<&str> = s.iter_live().map(|(id, _)| id).collect();
        assert_eq!(live, vec!["1"]);
        let (_, codes) = s.iter_live().next().unwrap();
        assert_eq!(codes.len(), 2);
    }

    #[test]
    fn codebook_is_order_independent() {
        // The final range spans the same values regardless of ingest order,
        // so a restart rebuild produces the same codebook — and, since every
        // re-fit re-encodes from the retained originals rather than through
        // decode/encode round trips, the same CODES bit for bit (ids are
        // positional here, so the comparison is per VECTOR).
        let a: Vec<Vec<f32>> = vec![vec![0.0, 1.0], vec![-2.0, 0.5], vec![3.0, -1.0]];
        let mut b = a.clone();
        b.reverse();
        let sa = store_with(&a);
        let sb = store_with(&b);
        assert_eq!(sa.codebook().mins, sb.codebook().mins);
        assert_eq!(sa.codebook().scales, sb.codebook().scales);
        for v in &a {
            let pos_a = a.iter().position(|x| x == v).unwrap();
            let pos_b = b.iter().position(|x| x == v).unwrap();
            assert_eq!(
                sa.codes_for(&pos_a.to_string()),
                sb.codes_for(&pos_b.to_string()),
                "codes for {v:?}"
            );
        }
    }

    #[test]
    fn codes_are_bit_identical_to_a_one_shot_fit_over_the_live_set() {
        // #392's serving claim, pinned at the codec level: after ANY
        // sequence of upserts (fresh writes, in-range and out-of-range
        // updates) and removes, the store's codebook and every live code
        // are bit-identical to fitting `Sq8Params` over the live vectors
        // once and encoding each under that fit — the exact bytes the
        // per-query fallback codec computes. The decode/encode round-trip
        // re-encode this test guards against drifted by up to the
        // quantization step per widening, which broke bit-identity between
        // the codes serving path and the exact scan.
        let mut s = Sq8CodeStore::new(4);
        let mut live: Vec<(String, Vec<f32>)> = Vec::new();
        let upsert =
            |s: &mut Sq8CodeStore, live: &mut Vec<(String, Vec<f32>)>, id: &str, v: Vec<f32>| {
                s.upsert(id, &v);
                if let Some(slot) = live.iter_mut().find(|(i, _)| i == id) {
                    slot.1 = v;
                } else {
                    live.push((id.to_string(), v));
                }
            };
        let v = |a: f32, b: f32, c: f32, d: f32| vec![a, b, c, d];
        // Fresh writes (several widen the range), then an out-of-range
        // update, an in-range update, a delete of a bound holder, and a
        // delete of a non-bound doc.
        upsert(&mut s, &mut live, "a", v(0.0, 0.5, -0.5, 0.1));
        upsert(&mut s, &mut live, "b", v(1.0, -1.0, 0.5, -0.9));
        upsert(&mut s, &mut live, "c", v(-0.7, 0.2, 0.9, 0.3));
        upsert(&mut s, &mut live, "d", v(0.4, 0.4, 0.4, 0.4));
        upsert(&mut s, &mut live, "b", v(-3.0, 0.0, 2.0, 0.0)); // out-of-range update
        upsert(&mut s, &mut live, "c", v(0.1, 0.1, 0.1, 0.1)); // in-range update
        assert!(s.remove("a")); // held dim-1 max / dim-2 min before its update
        assert!(s.remove("d")); // interior doc: no bound moves
        let live_now: Vec<&[f32]> = live
            .iter()
            .filter(|(id, _)| id != "a" && id != "d")
            .map(|(_, v)| v.as_slice())
            .collect();
        let fit = Sq8Params::fit_borrowed(live_now.iter().copied(), 4);
        let book = s.codebook();
        assert_eq!(
            book.mins, fit.mins,
            "codebook mins must equal the one-shot fit"
        );
        assert_eq!(
            book.scales, fit.scales,
            "codebook scales must equal the one-shot fit"
        );
        for (id, _) in live.iter() {
            if id == "a" || id == "d" {
                continue;
            }
            assert_eq!(
                s.codes_for(id).map(<[u8]>::to_vec),
                Some(
                    fit.encode(
                        &live
                            .iter()
                            .find(|(i, _)| i == id)
                            .map(|(_, v)| v.clone())
                            .unwrap()
                    )
                ),
                "codes for {id} must be bit-identical to encode-under-fit"
            );
        }
    }
}

