//! Fuzz the two script tokenisers that live in the aggregation engine.
//!
//! `xerj_engine::painless::tokenize` is not the only Painless-subset scanner in
//! the tree. `aggs.rs` holds two more with the same byte-walk / `&str`-slice
//! shape, reached from an ordinary `_search` body and nothing else:
//!
//! * `aggs::lex_script`      — `scripted_metric` (`init/map/combine/reduce`)
//! * `aggs::tokenize_script` — `bucket_script` / `bucket_selector`
//!
//! Neither was covered when the `painless` target found its char-boundary
//! crash, and both had the identical defect: `&src[i..i + 2]` for a two-char
//! operator, taken at a byte index that can sit inside a multi-byte character
//! because every arm above it is ASCII-only. `{"map_script":"中"}` was
//! `end byte index 2 is not a char boundary` — the process, under
//! `panic = "abort"` (#207).
//!
//! The harness supplies only the *script source* and wraps it in fixed agg
//! bodies over fixed documents. That is deliberate: fuzzing whole aggregation
//! JSON would spend its budget on `date_histogram` intervals and bucket counts
//! and turn a security gate into an out-of-memory lottery, while the parsers
//! this file exists to protect would barely be reached.
#![no_main]

use libfuzzer_sys::fuzz_target;
use serde_json::json;

fuzz_target!(|data: &[u8]| {
    let Ok(src) = std::str::from_utf8(data) else {
        return;
    };
    // Both evaluators reject longer sources on a length check before they
    // tokenize; past that bound the fuzzer is only exercising `len()`.
    if src.len() > 4096 {
        return;
    }

    let docs = vec![
        json!({ "k": "a", "v": 1.0 }),
        json!({ "k": "a", "v": 2.0 }),
        json!({ "k": "b", "v": 3.0 }),
    ];

    // scripted_metric -> lex_script
    let _ = xerj_engine::aggs::run_aggs(
        &json!({ "m": { "scripted_metric": {
            "init_script": src,
            "map_script": src,
            "combine_script": src,
            "reduce_script": src,
        }}}),
        &docs,
    );

    // bucket_script (sibling pipeline agg) -> tokenize_script
    let _ = xerj_engine::aggs::run_aggs(
        &json!({
            "s": { "sum": { "field": "v" } },
            "bs": { "bucket_script": { "buckets_path": { "x": "s" }, "script": src } },
        }),
        &docs,
    );

    // bucket_selector (parent pipeline agg) -> tokenize_script
    let _ = xerj_engine::aggs::run_aggs(
        &json!({ "by": {
            "terms": { "field": "k" },
            "aggs": {
                "s": { "sum": { "field": "v" } },
                "sel": { "bucket_selector": { "buckets_path": { "x": "s" }, "script": src } },
            },
        }}),
        &docs,
    );
});

//! Fuzz date-math expressions and date-format patterns.
//!
//! Both key spaces are attacker-influenced: `"gte": "now-1d/d"` and
//! `"format": "yyyy-MM-dd'T'HH:mm:ss.SSSZ||epoch_millis"` arrive in a range
//! query body, and the pattern compiler is a hand-written tokeniser over
//! quoted literals, repeated field letters and `||`-separated alternatives.
//!
//! Deliberately uses the *uncached* `compile_formats`: the cached wrapper is
//! keyed on the format string, and driving unique keys through it at fuzzing
//! rates measures the cache's eviction policy instead of the parser.
#![no_main]

use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    let Ok(text) = std::str::from_utf8(data) else {
        return;
    };
    if text.len() > 1024 {
        return;
    }

    // Date math applied to both epoch 0 and a realistic base, rounding both
    // ways — the rounding paths do the calendar arithmetic that can overflow.
    for base in [0i64, 1_700_000_000_000] {
        for round_up in [false, true] {
            let _ = xerj_query::dates::apply_date_math(base, text, round_up);
        }
    }

    // Pattern compilation, then parsing real values with whatever compiled.
    if let Ok(formats) = xerj_query::dates::compile_formats(text) {
        for probe in [
            serde_json::Value::String("2026-01-31T23:59:59.999Z".to_string()),
            serde_json::Value::String(text.to_string()),
            serde_json::Value::from(1_700_000_000_000i64),
        ] {
            let _ = xerj_query::dates::date_value_matches_formats(&probe, &formats);
        }
        for round_up in [false, true] {
            let _ = xerj_query::dates::resolve_date_bound_str(text, round_up, Some(&formats));
        }
    }

    // Bound resolution with no declared format — the `now`-anchored and
    // `<anchor>||<math>` branches.
    for round_up in [false, true] {
        let _ = xerj_query::dates::resolve_date_bound_str(text, round_up, None);
    }
});

//! Fuzz Elasticsearch index-name date math: `<logs-{now/d}>`.
//!
//! This one is reached from a request *URI*, not a body — every write and read
//! that names an index runs the name through it — and it is a second,
//! independent implementation of date math with its own hand-written brace
//! scanner on top. Both halves are attacker-controlled: the arithmetic
//! (`now+9999999999999d`) and the brace/format structure (`<a{b{c}}>`).
//!
//! **The resolver that runs on the wire is `xerj_api::es_compat`'s.** The first
//! version of this harness fuzzed `xerj_engine::index::resolve_date_math`
//! instead, which is a re-implementation with no production callers — grep
//! `crates/` and the only hits are `lib.rs`'s re-export, its own `#[cfg(test)]`
//! module and this file. So the harness passed while the resolver that actually
//! runs on the index path parameter (`es_compat.rs` `create_index`) and on the
//! `_search` index list still aborted the process on
//! `<logs-{2026-01-01||+9999999999999d}>`. `resolve_date_math_index` is fuzzed
//! first here for that reason; the engine copy is kept because it is exported
//! from `xerj-engine`'s public API and costs nothing to drive with the same
//! input (#207).
#![no_main]

use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    let Ok(name) = std::str::from_utf8(data) else {
        return;
    };
    if name.len() > 1024 {
        return;
    }
    // The one that runs on the wire.
    let _ = xerj_api::es_compat::resolve_date_math_index(name);
    // The public engine re-implementation, same input.
    let _ = xerj_engine::index::resolve_date_math(name);
});

//! Fuzz the Painless script tokeniser, parser and evaluator.
//!
//! Scripts arrive inside ordinary search and update bodies, so this is
//! attacker-supplied *code* — the highest-value parser in the engine and the
//! historical source of the worst ES CVEs (CVE-2015-1427, Groovy sandbox
//! escape). The harness runs both the admission check (`check_script_limits`,
//! which must reject rather than hang) and a full evaluation against a
//! realistic document, so the depth, op-count and deadline budgets are
//! exercised rather than just the grammar.
#![no_main]

use libfuzzer_sys::fuzz_target;
use xerj_engine::painless::{check_script_limits, eval_painless, PainlessCtx};

fuzz_target!(|data: &[u8]| {
    let Ok(src) = std::str::from_utf8(data) else {
        return;
    };
    // The engine's own cap is larger; a smaller one here keeps every input the
    // fuzzer generates inside the interesting (accepted) region.
    if src.len() > 4096 {
        return;
    }

    let _ = check_script_limits(src);

    let doc = serde_json::json!({
        "title": "the quick brown fox",
        "price": 12.5,
        "count": 7,
        "tags": ["a", "b", "c"],
        "nested": { "inner": [1, 2, 3] },
    });
    let params = serde_json::json!({ "factor": 2, "name": "x" });
    let ctx = PainlessCtx::new(&doc, &params, 1.0);
    let _ = eval_painless(src, &ctx);
    let _ = ctx.take_emits();
});

//! Fuzz the Elasticsearch-compatible search DSL parser.
//!
//! Reachable by any client that can POST to `/{index}/_search`, so the whole
//! body is untrusted: nesting depth, clause count, field names, numeric
//! ranges, `_source` filters, sort specs and aggregation shapes all come
//! straight off the wire.
//!
//! The harness runs parse *and* rewrite, because the rewriter walks the tree
//! the parser produced — a parser that accepts a pathological shape and a
//! rewriter that then recurses on it are one bug, not two.
#![no_main]

use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    // serde_json is a third-party parser with its own fuzzing; this harness
    // is about what xerj does with the value once it is JSON.
    let Ok(value) = serde_json::from_slice::<serde_json::Value>(data) else {
        return;
    };

    if let Ok(request) = xerj_query::parse_request(&value) {
        // The parser's depth and clause budgets are the only thing standing
        // between an untrusted body and unbounded recursion here.
        let _ = xerj_query::rewrite(request.query);
    }

    // `parse_query` is also called directly (binary protocol, percolate-style
    // paths), so exercise it on the same input rather than only through a
    // well-formed request envelope.
    let _ = xerj_query::parse_query(&value);
});

//! Fuzz the Lucene `query_string` / `simple_query_string` mini-language.
//!
//! This is the one hand-written recursive-descent grammar on the read path:
//! it tokenises quotes, escapes, field prefixes, boolean operators, grouping
//! parens, wildcards and `[a TO b]` / `field:>10` range syntax. It is reachable
//! unauthenticated wherever search is, both from a request body and from the
//! `?q=` URI parameter, which is exactly the surface ES burned itself on in
//! CVE-2023-31419 (stack overflow via crafted query strings).
#![no_main]

use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    let Ok(query) = std::str::from_utf8(data) else {
        return;
    };
    // The parser enforces its own length cap; staying under it keeps the
    // fuzzer's budget on grammar states rather than on the length check.
    if query.len() > 4096 {
        return;
    }

    for default_operator in ["OR", "AND"] {
        let body = serde_json::json!({
            "query_string": {
                "query": query,
                "default_field": "body",
                "default_operator": default_operator,
            }
        });
        let _ = xerj_query::parse_query(&body);
    }

    // No `default_field`: takes the `*`/multi-field lowering branch, which has
    // different range-syntax handling from the single-field one.
    let body = serde_json::json!({ "query_string": { "query": query } });
    let _ = xerj_query::parse_query(&body);

    let body = serde_json::json!({ "simple_query_string": { "query": query } });
    let _ = xerj_query::parse_query(&body);
});

//! Fuzz the SQL parser behind `/_sql`.
//!
//! A second hand-written tokeniser and recursive-descent parser, reachable
//! with a single POST. ES's own equivalent surface produced CVE-2024-43709
//! (crafted SQL query → OutOfMemoryError → node crash), so "does a crafted
//! statement panic or allocate without bound" is the exact question here.
#![no_main]

use libfuzzer_sys::fuzz_target;

fuzz_target!(|data: &[u8]| {
    let Ok(sql) = std::str::from_utf8(data) else {
        return;
    };
    if sql.len() > 8192 {
        return;
    }
    let _ = xerj_engine::sql::parse_sql(sql);
});

syntax = "proto3";
package xerj.v1;

service XerjSearch {
  rpc Search(SearchRequest) returns (SearchResponse);
  rpc Index(IndexRequest) returns (IndexResponse);
  rpc BulkIndex(stream IndexRequest) returns (BulkResponse);
  rpc GetDocument(GetRequest) returns (GetResponse);
  rpc DeleteDocument(DeleteRequest) returns (DeleteResponse);
  rpc Health(HealthRequest) returns (HealthResponse);
}

message SearchRequest {
  string index = 1;
  string query_json = 2;  // ES-compatible query DSL as JSON
  int32 size = 3;
  int32 from = 4;
}

message SearchResponse {
  int64 total_hits = 1;
  repeated Hit hits = 2;
  int64 took_ms = 3;
  bool timed_out = 4;
}

message Hit {
  string id = 1;
  float score = 2;
  string source_json = 3;
  string index = 4;
}

message IndexRequest {
  string index = 1;
  string id = 2;
  string source_json = 3;
}

message IndexResponse {
  string id = 1;
  int64 version = 2;
  string result = 3;
}

message BulkResponse {
  int64 took_ms = 1;
  bool errors = 2;
  int32 indexed = 3;
}

message GetRequest {
  string index = 1;
  string id = 2;
}

message GetResponse {
  bool found = 1;
  string id = 2;
  string source_json = 3;
  int64 version = 4;
}

message DeleteRequest {
  string index = 1;
  string id = 2;
}

message DeleteResponse {
  string result = 1;
}

message HealthRequest {}
message HealthResponse {
  string status = 1;
  int32 num_indices = 2;
  int64 total_docs = 3;
}

// ===========================================================================
// Corpus Hub v2 — pack query surface (discussion #1374).
//
// Contract locked by docs/CORPUS_HUB_V2_IMPLEMENTATION.md §7. The messages
// mirror the shared Rust types in engine/crates/xerj-common/src/hub.rs
// (`Answer`, `Hit`) one-to-one so gRPC, the MCP tools and the CLI speak one
// vocabulary. Both gRPC and MCP must call `xerj_hub::ask`/`def` rather than
// reimplement the flow — see docs/hub-v2-grpc-mcp-notes.md for the field
// mapping and the MCP tool specs.
//
// FIELD NUMBERS ARE PERMANENT. They are fixed by §7 and §11 ("do not …
// renumber proto fields") of the plan: once this lands they must never be
// renumbered, reused, or repurposed — this is a wire contract. Each message
// below records its live field-number range in a comment; new fields may only
// be appended with the next free number.
//
// The service trait and client are generated by build.rs (tonic/prost); the
// server impl is engine/crates/xerj-server/src/grpc_hub.rs, registered in
// grpc.rs next to XerjSearch behind the same interceptor.
// ===========================================================================
service XerjHub {
  rpc Ask(HubAskRequest) returns (HubAnswer);
  rpc Def(HubDefRequest) returns (HubAnswer);
  rpc Catalogue(HubCatalogueRequest) returns (HubCatalogueResponse);
}

// Fields 1-4 (permanent). The corpus is never required in the question; when
// `corpus` is empty the sketch router picks it. `mode` is empty for auto.
message HubAskRequest {
  string question = 1;    // natural-language question
  string corpus = 2;      // optional explicit corpus slug; "" = route by sketch
  string mode = 3;        // "def" | "how" | "files"; "" = auto
  uint32 max_tokens = 4;  // soft output budget; 0 = default
}

// Fields 1-3 (permanent).
message HubDefRequest {
  string slug = 1;    // corpus slug to resolve the symbol in
  string symbol = 2;  // exact definition name
  uint32 k = 3;       // max hits; 0 = default
}

// No fields (permanent). A catalogue fetch takes no arguments.
message HubCatalogueRequest {}

// Fields 1-2 (permanent). `catalogue_json` is the serialized `Catalogue`
// (hub.rs) as the exact bytes the signature covers.
message HubCatalogueResponse {
  bytes catalogue_json = 1;  // serialized `Catalogue`, verbatim signed bytes
  bytes signature = 2;       // ed25519 signature over catalogue_json
}

// Fields 1-7 (permanent). Mirror of hub.rs `Hit`. Rust `value` and
// `licence_warning` are `Option<String>`; proto3 has no null, so `None` maps
// to the empty string "".
message HubHit {
  string file = 1;
  uint32 line = 2;
  string kind = 3;
  string text = 4;
  string value = 5;            // Rust Option<String>; None -> ""
  float score = 6;
  string licence_warning = 7;  // Rust Option<String>; None -> ""
}

// Fields 1-11 (permanent). Mirror of hub.rs `Answer`. The enum fields carry the
// serde string forms of the Rust enums: `licence_class` is LicenceClass
// kebab-case ("adapt-with-attribution" | "approach-only" | "excluded"),
// `answered_from` is AnsweredFrom snake_case ("local_pack" | "hosted" |
// "local_index"), `mode` is AnswerMode snake_case ("def" | "how" | "files").
message HubAnswer {
  string corpus = 1;
  string pin_sha = 2;
  string pin_date = 3;
  uint32 age_days = 4;
  string licence_spdx = 5;
  string licence_class = 6;   // LicenceClass serde kebab-case
  string answered_from = 7;   // AnsweredFrom serde snake_case
  string mode = 8;            // AnswerMode serde snake_case
  repeated HubHit hits = 9;
  bool truncated = 10;
  repeated string warnings = 11;
}

